INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2, 'juklak-1-2023', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian Nomor 1 Tahun 2023');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2, 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian Nomor 1 Tahun 2023', 'Judul', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian Nomor 1 Tahun 2023');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3, 'juklak-1-2023', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN BANTUAN DANA TUNGGU HUNIAN NOMOR 1 TAHUN 2023');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN BANTUAN DANA TUNGGU HUNIAN NOMOR 1 TAHUN 2023', 'Isi hal. 1', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian Nomor 1 Tahun 2023');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4, 'juklak-1-2023', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Jumlah kejadian bencana di Indonesia cenderung meningkat setiap tahunnya. Dampak buruk dari kejadian bencana seringkali menyebabkan adanya arus pengungsian penduduk terdampak. Oleh karena itu, dalam rangka pemenuhan kebutuhan dasar bagi pengungsi, perlu upaya penyediaan hunian sementara.
Untuk mendukung upaya penyediaan hunian sementara, maka sesuai dengan lampiran petunjuk pelaksanaan Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai, terhadap korban dan pengungsi akibat bencana dapat diberikan dana tunggu hunian pada saat diberlakukannya status keadaan darurat bencana. Pada saat ini belum terdapat instrumen hukum yang mengatur secara spesifik tentang tata cara pemberian dana tunggu hunian.
Sehingga, perlu dibentuk Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian Bagi Pengungsi Korban Bencana Pada Status Keadaan Darurat Bencana.
B. Maksud dan Tujuan
1. Petunjuk Pelaksanaan ini dimaksudkan sebagai rujukan/acuan bagi BNPB, BPBD Provinsi/Kabupaten/Kota terkait dengan penggunaan dana siap pakai untuk pemberian bantuan dana tunggu hunian bagi korban dan pengungsi akibat bencana.
2. Tujuan dari Petunjuk Pelaksanaan ini adalah tersedianya mekanisme pengelolaan pemberian bantuan dana tunggu hunian bagi korban dan pengungsi akibat bencana secara tertib, cepat, tepat waktu, dan tepat sasaran, sehingga dapat dipertanggungjawabkan secara transparan dan akuntabel.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4, 'PENDAHULUAN A. Latar Belakang Jumlah kejadian bencana di Indonesia cenderung meningkat setiap tahunnya. Dampak buruk dari kejadian bencana seringkali menyebabkan adanya arus pengungsian penduduk terdampak. Oleh karena itu, dalam rangka pemenuhan kebutuhan dasar bagi pengungsi, perlu upaya penyediaan hunian sementara.
Untuk mendukung upaya penyediaan hunian sementara, maka sesuai dengan lampiran petunjuk pelaksanaan Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai, terhadap korban dan pengungsi akibat bencana dapat diberikan dana tunggu hunian pada saat diberlakukannya status keadaan darurat bencana. Pada saat ini belum terdapat instrumen hukum yang mengatur secara spesifik tentang tata cara pemberian dana tunggu hunian.
Sehingga, perlu dibentuk Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian Bagi Pengungsi Korban Bencana Pada Status Keadaan Darurat Bencana.
B. Maksud dan Tujuan
1. Petunjuk Pelaksanaan ini dimaksudkan sebagai rujukan/acuan bagi BNPB, BPBD Provinsi/Kabupaten/Kota terkait dengan penggunaan dana siap pakai untuk pemberian bantuan dana tunggu hunian bagi korban dan pengungsi akibat bencana.
2. Tujuan dari Petunjuk Pelaksanaan ini adalah tersedianya mekanisme pengelolaan pemberian bantuan dana tunggu hunian bagi korban dan pengungsi akibat bencana secara tertib, cepat, tepat waktu, dan tepat sasaran, sehingga dapat dipertanggungjawabkan secara transparan dan akuntabel.', 'BAB I', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian Nomor 1 Tahun 2023');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5, 'juklak-1-2023', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'C. Ruang Lingkup Ruang lingkup Petunjuk Pelaksanaan ini meliputi:
1. pengertian,
2. kriteria penerima,
3. standar pemberian,
4. jangka waktu pemberian,
5. besaran dan penyaluran,
6. mekanisme pengusulan,
7. mekanisme verifikasi,
8. pertanggungjawaban penggunaan,
9. monitoring, evaluasi, dan pelaporan.
D. Pengertian
1. Dana Tunggu Hunian, yang selanjutnya disingkat DTH adalah dana siap pakai yang diberikan kepada korban dan pengungsi akibat bencana yang digunakan untuk mencari tempat tinggal sementara pada saat menunggu hunian tetap/rumahnya selesai dibangun.
2. Dana Siap Pakai, yang selanjutnya disingkat DSP adalah dana yang selalu tersedia dan dicadangkan oleh Pemerintah untuk digunakan pada saat keadaan darurat, keadaan tertentu, dan pertimbangan adanya risiko bencana berdampak luas yang ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5, 'C. Ruang Lingkup Ruang lingkup Petunjuk Pelaksanaan ini meliputi:
1. pengertian,
2. kriteria penerima,
3. standar pemberian,
4. jangka waktu pemberian,
5. besaran dan penyaluran,
6. mekanisme pengusulan,
7. mekanisme verifikasi,
8. pertanggungjawaban penggunaan,
9. monitoring, evaluasi, dan pelaporan.
D. Pengertian
1. Dana Tunggu Hunian, yang selanjutnya disingkat DTH adalah dana siap pakai yang diberikan kepada korban dan pengungsi akibat bencana yang digunakan untuk mencari tempat tinggal sementara pada saat menunggu hunian tetap/rumahnya selesai dibangun.
2. Dana Siap Pakai, yang selanjutnya disingkat DSP adalah dana yang selalu tersedia dan dicadangkan oleh Pemerintah untuk digunakan pada saat keadaan darurat, keadaan tertentu, dan pertimbangan adanya risiko bencana berdampak luas yang ditetapkan oleh Kepala BNPB.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian Nomor 1 Tahun 2023');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6, 'juklak-1-2023', 4, 'lain', 'BAB II', NULL, 3, 'PELAKSANAAN PENGELOLAAN BANTUAN DTH Kriteria Penerima Bantuan DTH diberikan dengan kriteria sebagai berikut:
1. korban dan pengungsi akibat bencana yang rumah tinggalnya:
a. masuk dalam kategori rumah rusak berat akibat bencana, atau
b. tidak layak huni akibat bencana.
2. tidak layak huni sebagaimana dimaksud pada Angka 1 huruf b meliputi:
a. tidak memenuhi persyaratan keselamatan bangunan dan kesehatan penghuni sesuai dengan ketentuan peraturan pe-rundang-undangan, atau
b. masuk dalam kawasan rawan bencana (zona merah) sesuai dengan rekomendasi kementerian/lembaga terkait.
3. korban dan pengungsi akibat bencana tidak mendapatkan fasili-tas hunian sementara dari pemerintah/lembaga usaha/lembaga kemanusiaan /organisasi kemasyarakatan.
4. korban dan pengungsi akibat bencana tidak mampu secara man-diri menyediakan tempat hunian sementara.
Standar Pemberian Bantuan DTH diberikan dengan standar sebagai berikut:
1. diberikan per 1 (satu) Kepala Keluarga,
2. ditetapkan dengan Keputusan Kepala Daerah terdampak bencana dengan dilengkapi rincian daftar nama penerima bantuan berdasarkan alamat tempat tinggal sebagaimana tercantum dalam Lampiran I.
3. hunian sementara yang dapat disewa harus memenuhi standar minimal:
a. berukuran 3 m?per orang,
b. memiliki persyaratan keamanan dan kesehatan,
c. memiliki aksesibilitas terhadap fasilitas umum, dan
d. menjamin privasi antar jenis kelamin dan berbagai kelompok usia.
Jangka Waktu Pemberian Bantuan DTH diberikan pada saat:');
