INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (11, 'juklak-1-2023', 9, 'lampiran', 'LAMPIRAN I', NULL, 7, 'PETUNJUK PELAKSANAAN BANTUAN DANA TUNGGU HUNIAN NOMOR 1 TAHUN 2023 FORMAT KEPUTUSAN KEPALA DAERAH KEPUTUSAN KEPALA DAERAH.....
NOMOR TAHUN .......
TENTANG PENERIMA BANTUAN DANA TUNGGU HUNIAN BENCANA.......
PADA DARURAT BENCANA DI ...........
KEPALA DAERAH (GUBERNUR/BUPATI/WALIKOTA......) Menimbang 1 a. bahwa dalamrangka penyediaan penampungan serta tempat hunian sementara bagi korban dan pengungsi akibat bencana yang tempat tinggalnya tidak dapat dihuni, diperlukan bantuan dari pemerintah,
b. bahwa salah satu bentuk pemberian bantuan penyediaan penampungan serta tempat hunian sementara sebagaimana dimaksud dalam huruf a berupa dana tunggu hunian,
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b perlu menetapkan Keputusan Gubernur/ Bupati/ Walikota ..... tentang Penerima Bantuan Dana Tunggu Hunian, Mengingat 11 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),
2. Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 244, Tambahan Lembaran Negara Republik Indonesia Nomor 5587) sebagaimana telah diubah terakhir dengan Undang-Undang Nomor 9 Tahun 2015 tentang Perubahan Kedua Atas Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaga Negara Republik Indonesia Tahun 2014 Nomor 58, Tambahan Lembaran Negara Republik Indonesia Nomor 5679),');
