INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (19, 'juklak-1-2025', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
