INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (20, 'juklak-1-2025', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PASCABENCANA NOMOR 1 TAHUN 2025');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (20, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PASCABENCANA NOMOR 1 TAHUN 2025', 'Isi hal. 1', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (21, 'juklak-1-2025', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Pasal 33 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menyatakan bahwa penyelenggaraan penanggulangan bencana meliputi prabencana, saat tanggap darurat, dan pemulihan pascabencana. Secara spesifik dalam Pasal 57 dinyatakan bahwa penyelenggaraan penanggulangan bencana pada tahap pascabencana meliputi rehabilitasi dan rekonstruksi. Upaya rehabilitasi dan rekonstruksi pascabencana dilakukan dalam rangka menumbuhkan kembali daya lenting bagi masyarakat terdampak bencana agar dapat bangkit dari keterpurukan melalui konsep membangun kembali yang lebih baik, aman, dan berkelanjutan berbasis pengurangan risiko bencana dengan mengedepankan kearifan lokal.
Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana merupakan regulasi yang mengatur mengenai sumber pendanaan alternatif yang dapat menjamin ketersediaan dana penanggulangan bencana yang memadai, tepat waktu, tepat sasaran, terencana, berkelanjutan, melindungi keuangan negara, dan memperkuat kapasitas baik pemerintah pusat maupun pemerintah daerah dalam pendanaan penanggulangan bencana. Kementerian Keuangan menerbitkan Keputusan Menteri Keuangan Nomor 407 Tahun 2021 yang menugaskan Badan Pengelola Dana Lingkungan Hidup untuk melaksanakan pengelolaan dana bersama penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (21, 'PENDAHULUAN A. Latar Belakang Pasal 33 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menyatakan bahwa penyelenggaraan penanggulangan bencana meliputi prabencana, saat tanggap darurat, dan pemulihan pascabencana. Secara spesifik dalam Pasal 57 dinyatakan bahwa penyelenggaraan penanggulangan bencana pada tahap pascabencana meliputi rehabilitasi dan rekonstruksi. Upaya rehabilitasi dan rekonstruksi pascabencana dilakukan dalam rangka menumbuhkan kembali daya lenting bagi masyarakat terdampak bencana agar dapat bangkit dari keterpurukan melalui konsep membangun kembali yang lebih baik, aman, dan berkelanjutan berbasis pengurangan risiko bencana dengan mengedepankan kearifan lokal.
Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana merupakan regulasi yang mengatur mengenai sumber pendanaan alternatif yang dapat menjamin ketersediaan dana penanggulangan bencana yang memadai, tepat waktu, tepat sasaran, terencana, berkelanjutan, melindungi keuangan negara, dan memperkuat kapasitas baik pemerintah pusat maupun pemerintah daerah dalam pendanaan penanggulangan bencana. Kementerian Keuangan menerbitkan Keputusan Menteri Keuangan Nomor 407 Tahun 2021 yang menugaskan Badan Pengelola Dana Lingkungan Hidup untuk melaksanakan pengelolaan dana bersama penanggulangan bencana.', 'BAB I', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (22, 'juklak-1-2025', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Adapun peran BNPB dalam penyaluran dana bersama penanggulangan bencana ini adalah untuk melaksanakan penelaahan, verifikasi, dan evaluasi. Untuk melaksanakan tugas dan fungsi tersebut, BNPB menetapkan Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
Sebagai penjabaran operasional mengenai penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana pada tahap pascabencana, Badan Nasional Penanggulangan Bencana menyusun Petunjuk Pelaksanaan Penelaahan, Verifikasi dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana agar dapat dipedomani oleh Badan Nasional Penanggulangan Bencana, Kementerian/Lembaga, Pemerintah Daerah, dan masyarakat.
B. Maksud dan Tujuan Petunjuk pelaksanaan ini dimaksudkan sebagai acuan dan alat bantu dalam tata cara permohonan, penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana tahap pascabencana bagi Badan Nasional Penanggulangan Bencana, Kementerian/Lembaga, Pemerintah Daerah, dan masyarakat.
Tujuan penyusunan Petunjuk Pelaksanaan ini adalah mendukung dan melengkapi ketersediaan dana penanggulangan bencana yang memadai, tepat waktu, tepat sasaran, terencana, dan berkelanjutan dalam upaya penanggulangan bencana secara berdaya guna, berhasil guna, dan dapat dipertanggungjawabkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (22, 'Adapun peran BNPB dalam penyaluran dana bersama penanggulangan bencana ini adalah untuk melaksanakan penelaahan, verifikasi, dan evaluasi. Untuk melaksanakan tugas dan fungsi tersebut, BNPB menetapkan Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
Sebagai penjabaran operasional mengenai penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana pada tahap pascabencana, Badan Nasional Penanggulangan Bencana menyusun Petunjuk Pelaksanaan Penelaahan, Verifikasi dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana agar dapat dipedomani oleh Badan Nasional Penanggulangan Bencana, Kementerian/Lembaga, Pemerintah Daerah, dan masyarakat.
B. Maksud dan Tujuan Petunjuk pelaksanaan ini dimaksudkan sebagai acuan dan alat bantu dalam tata cara permohonan, penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana tahap pascabencana bagi Badan Nasional Penanggulangan Bencana, Kementerian/Lembaga, Pemerintah Daerah, dan masyarakat.
Tujuan penyusunan Petunjuk Pelaksanaan ini adalah mendukung dan melengkapi ketersediaan dana penanggulangan bencana yang memadai, tepat waktu, tepat sasaran, terencana, dan berkelanjutan dalam upaya penanggulangan bencana secara berdaya guna, berhasil guna, dan dapat dipertanggungjawabkan.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (23, 'juklak-1-2025', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, 'C. Ruang Lingkup Ruang lingkup Petunjuk pelaksanaan ini memuat kriteria, tata cara permohonan, pertimbangan, penelaahan, verifikasi, pemberian rekomendasi, pemantauan, dan evaluasi penyaluran dana bersama penanggulangan bencana pada tahap pascabencana.
D. Pengertian
1. Dana Penanggulangan Bencana adalah dana yang digunakan bagi penanggulangan bencana untuk tahap prabencana, darurat bencana, dan/atau pascabencana.
2. Dana Bersama Penanggulangan Bencana yang selanjutnya disebut Dana Bersama adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi Dana Penanggulangan Bencana yang memadai dan berkelanjutan.
3. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
4. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara Pemerintahan Daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
5. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
6. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan Pemerintah Daerah yang melakukan Penyelenggaraan Penanggulangan Bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (23, 'C. Ruang Lingkup Ruang lingkup Petunjuk pelaksanaan ini memuat kriteria, tata cara permohonan, pertimbangan, penelaahan, verifikasi, pemberian rekomendasi, pemantauan, dan evaluasi penyaluran dana bersama penanggulangan bencana pada tahap pascabencana.
D. Pengertian
1. Dana Penanggulangan Bencana adalah dana yang digunakan bagi penanggulangan bencana untuk tahap prabencana, darurat bencana, dan/atau pascabencana.
2. Dana Bersama Penanggulangan Bencana yang selanjutnya disebut Dana Bersama adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi Dana Penanggulangan Bencana yang memadai dan berkelanjutan.
3. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
4. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara Pemerintahan Daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
5. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
6. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan Pemerintah Daerah yang melakukan Penyelenggaraan Penanggulangan Bencana di daerah.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (24, 'juklak-1-2025', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, '7. Kelompok Masyarakat adalah forum pengurangan risiko bencana, kumpulan individu dari masyarakat terdampak bencana, serta kelompok masyarakat binaan organisasi pemerintah daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (24, '7. Kelompok Masyarakat adalah forum pengurangan risiko bencana, kumpulan individu dari masyarakat terdampak bencana, serta kelompok masyarakat binaan organisasi pemerintah daerah.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (25, 'juklak-1-2025', 6, 'lain', 'BAB II', NULL, 3, 'PELAKSANAAN A. Kriteria Kriteria permohonan penyaluran Dana Bersama terdiri atas kriteria penerima dan kriteria kegiatan.
1. Kriteria Penerima Kriteria penerima Dana Bersama tahap pascabencana adalah sebagai berikut.
a. Kementerian/lembaga dan BNPB yang mempunyai program penanggulangan bencana tahap pascabencana dan tercantum dalam rencana rehabilitasi dan rekonstruksi pascabencana yang masih berlaku;
b. Pemerintah Daerah yang mempunyai program penanggulangan bencana tahap pascabencana dan tercantum dalam rencana rehabilitasi dan rekonstruksi pascabencana yang masih berlaku; dan
c. Kelompok Masyarakat terdampak bencana yang telah diverifikasi oleh Pemerintah Daerah yang mencakup:
1) forum pengurangan risiko bencana;
2) forum tematik pengurangan risiko bencana tingkat lokal;
3) Kelompok Masyarakat binaan kementerian/lembaga dan perangkat daerah; dan 4) kumpulan individu dari masyarakat terdampak bencana.
2. Kriteria Kelembagaan Permohonan Dana Bersama dapat diajukan dengan mekanisme sebagai berikut.
a. Kementerian/lembaga diajukan oleh paling rendah pejabat pimpinan tinggi madya.
b. Pemerintah Daerah diajukan oleh Kepala Daerah.
c. Permohonan dari Pemerintah Daerah yang diprakarsai oleh perangkat daerah selain BPBD, perangkat daerah sebagaimana dimaksud wajib berkoordinasi dengan BPBD.
d. BPBD dapat membentuk tim yang ditetapkan oleh serendah-rendahnya Sekretaris Daerah untuk melakukan koordinasi sebagaimana dimaksud pada angka 3.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (25, 'PELAKSANAAN A. Kriteria Kriteria permohonan penyaluran Dana Bersama terdiri atas kriteria penerima dan kriteria kegiatan.
1. Kriteria Penerima Kriteria penerima Dana Bersama tahap pascabencana adalah sebagai berikut.
a. Kementerian/lembaga dan BNPB yang mempunyai program penanggulangan bencana tahap pascabencana dan tercantum dalam rencana rehabilitasi dan rekonstruksi pascabencana yang masih berlaku;
b. Pemerintah Daerah yang mempunyai program penanggulangan bencana tahap pascabencana dan tercantum dalam rencana rehabilitasi dan rekonstruksi pascabencana yang masih berlaku; dan
c. Kelompok Masyarakat terdampak bencana yang telah diverifikasi oleh Pemerintah Daerah yang mencakup:
1) forum pengurangan risiko bencana;
2) forum tematik pengurangan risiko bencana tingkat lokal;
3) Kelompok Masyarakat binaan kementerian/lembaga dan perangkat daerah; dan 4) kumpulan individu dari masyarakat terdampak bencana.
2. Kriteria Kelembagaan Permohonan Dana Bersama dapat diajukan dengan mekanisme sebagai berikut.
a. Kementerian/lembaga diajukan oleh paling rendah pejabat pimpinan tinggi madya.
b. Pemerintah Daerah diajukan oleh Kepala Daerah.
c. Permohonan dari Pemerintah Daerah yang diprakarsai oleh perangkat daerah selain BPBD, perangkat daerah sebagaimana dimaksud wajib berkoordinasi dengan BPBD.
d. BPBD dapat membentuk tim yang ditetapkan oleh serendah-rendahnya Sekretaris Daerah untuk melakukan koordinasi sebagaimana dimaksud pada angka 3.', 'BAB II', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (26, 'juklak-1-2025', 7, 'lain', 'BAB II (lanjutan 1)', NULL, 3, 'e. Pemerintah Daerah bertugas memfasilitasi pengajuan permohonan Kelompok Masyarakat yang akan dibiayai oleh Dana Bersama.
3. Kriteria Kegiatan Kriteria kegiatan yang dapat dibiayai menggunakan Dana Bersama adalah kegiatan rehabilitasi dan rekonstruksi dalam dokumen rencana rehabilitasi dan rekonstruksi pascabencana, meliputi 5 (lima) sektor antara lain sebagai berikut.
a. Perumahan Rehabilitasi dan rekonstruksi perumahan pascabencana perlu memperhatikan hal-hal antara lain:
1) kesiapan Pemerintah Daerah untuk penyediaan lahan jika kegiatan dilaksanakan dengan cara merelokasi rumah;
2) Rencana Tata Ruang Wilayah; dan 3) pemetaan zona aman dan rawan ancaman bencana yang dikeluarkan oleh instansi yang berwenang.
Kegiatan pada sektor perumahan terdiri atas subsektor rumah dan subsektor prasarana lingkungan.
b. Infrastruktur Rehabilitasi dan rekonstruksi pada sektor infrastruktur perlu memperhatikan hal-hal antara lain:
1) berdasarkan kebutuhan prioritas;
2) pembangunan infrastruktur yang dapat meminimalkan dampak bencana;
3) kesiapan lahan dan perizinan pada lokasi kegiatan;
4) Rencana Tata Ruang Wilayah;
5) perencanaan desain konstruksi yang lebih aman dan lebih kuat;
6) untuk kegiatan pembangunan ex-situ lebih memperhatikan pemetaan zona aman dan rawan ancaman bencana yang dikeluarkan oleh instansi yang berwenang untuk memitigasi potensi bencana berikutnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (26, 'e. Pemerintah Daerah bertugas memfasilitasi pengajuan permohonan Kelompok Masyarakat yang akan dibiayai oleh Dana Bersama.
3. Kriteria Kegiatan Kriteria kegiatan yang dapat dibiayai menggunakan Dana Bersama adalah kegiatan rehabilitasi dan rekonstruksi dalam dokumen rencana rehabilitasi dan rekonstruksi pascabencana, meliputi 5 (lima) sektor antara lain sebagai berikut.
a. Perumahan Rehabilitasi dan rekonstruksi perumahan pascabencana perlu memperhatikan hal-hal antara lain:
1) kesiapan Pemerintah Daerah untuk penyediaan lahan jika kegiatan dilaksanakan dengan cara merelokasi rumah;
2) Rencana Tata Ruang Wilayah; dan 3) pemetaan zona aman dan rawan ancaman bencana yang dikeluarkan oleh instansi yang berwenang.
Kegiatan pada sektor perumahan terdiri atas subsektor rumah dan subsektor prasarana lingkungan.
b. Infrastruktur Rehabilitasi dan rekonstruksi pada sektor infrastruktur perlu memperhatikan hal-hal antara lain:
1) berdasarkan kebutuhan prioritas;
2) pembangunan infrastruktur yang dapat meminimalkan dampak bencana;
3) kesiapan lahan dan perizinan pada lokasi kegiatan;
4) Rencana Tata Ruang Wilayah;
5) perencanaan desain konstruksi yang lebih aman dan lebih kuat;
6) untuk kegiatan pembangunan ex-situ lebih memperhatikan pemetaan zona aman dan rawan ancaman bencana yang dikeluarkan oleh instansi yang berwenang untuk memitigasi potensi bencana berikutnya.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (27, 'juklak-1-2025', 8, 'lain', 'BAB II (lanjutan 2)', NULL, 4, 'c. Sosial Rehabilitasi dan rekonstruksi pada sektor sosial dilaksanakan menggunakan pendekatan pemberdayaan masyarakat terdampak bencana sebagai pelaku aktif dengan tujuan sebagai berikut.
1) Meningkatkan kapasitas masyarakat untuk aktivasi modal sosialnya dalam rangka percepatan pemulihan kondisi sosial pascabencana.
2) Meningkatkan motivasi dan peran anggota masyarakat dalam kegiatan sosial masyarakat.
3) Meningkatkan peran aktif dan dukungan kementerian/lembaga, perangkat daerah lainnya, masyarakat/komunitas dan lembaga usaha serta pemangku kepentingan lainnya sebagai upaya pemulihan dan peningkatan aktivitas sosial masyarakat di daerah pascabencana.
Kegiatan pada sektor sosial terdiri atas subsektor-subsektor antara lain:
1) kesehatan;
2) pendidikan;
3) keagamaan;
4) budaya; dan 5) lembaga sosial.
d. Ekonomi Kegiatan rehabilitasi dan rekonstruksi pada sektor ekonomi dilaksanakan dengan menggunakan pendekatan pemberdayaan masyarakat yang menempatkan warga terdampak bencana sebagai pelaku aktif dalam pemenuhan kebutuhan ekonomi dengan tujuan antara lain:
1) meningkatkan kapasitas sumber daya masyarakat dan kelembagaan ekonomi di wilayah pascabencana;
2) memulihkan usaha ekonomi masyarakat terdampak bencana;
3) mengangkat potensi komoditas lokal;
4) meningkatkan nilai tambah komoditas lokal;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (27, 'c. Sosial Rehabilitasi dan rekonstruksi pada sektor sosial dilaksanakan menggunakan pendekatan pemberdayaan masyarakat terdampak bencana sebagai pelaku aktif dengan tujuan sebagai berikut.
1) Meningkatkan kapasitas masyarakat untuk aktivasi modal sosialnya dalam rangka percepatan pemulihan kondisi sosial pascabencana.
2) Meningkatkan motivasi dan peran anggota masyarakat dalam kegiatan sosial masyarakat.
3) Meningkatkan peran aktif dan dukungan kementerian/lembaga, perangkat daerah lainnya, masyarakat/komunitas dan lembaga usaha serta pemangku kepentingan lainnya sebagai upaya pemulihan dan peningkatan aktivitas sosial masyarakat di daerah pascabencana.
Kegiatan pada sektor sosial terdiri atas subsektor-subsektor antara lain:
1) kesehatan;
2) pendidikan;
3) keagamaan;
4) budaya; dan 5) lembaga sosial.
d. Ekonomi Kegiatan rehabilitasi dan rekonstruksi pada sektor ekonomi dilaksanakan dengan menggunakan pendekatan pemberdayaan masyarakat yang menempatkan warga terdampak bencana sebagai pelaku aktif dalam pemenuhan kebutuhan ekonomi dengan tujuan antara lain:
1) meningkatkan kapasitas sumber daya masyarakat dan kelembagaan ekonomi di wilayah pascabencana;
2) memulihkan usaha ekonomi masyarakat terdampak bencana;
3) mengangkat potensi komoditas lokal;
4) meningkatkan nilai tambah komoditas lokal;', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (28, 'juklak-1-2025', 9, 'lain', 'BAB II (lanjutan 3)', NULL, 4, '5) memperluas dan memperkuat jejaring pemasaran produk; dan 6) meningkatkan peran aktif dan dukungan kementerian/lembaga, perangkat daerah, masyarakat/komunitas dan lembaga usaha serta pemangku kepentingan lainnya dalam upaya keberlanjutan dan replikasi program.
Kegiatan pada sektor ekonomi terdiri atas subsektor antara lain:
1) pertanian;
2) perkebunan;
3) peternakan;
4) perikanan;
5) perindustrian;
6) perdagangan;
7) pariwisata;
8) koperasi; dan 9) usaha mikro, kecil dan menengah.
e. Lintas Sektor Kegiatan rehabilitasi dan rekonstruksi pada lintas sektor terdiri atas subsektor antara lain:
1) pemerintahan;
2) perbankan;
3) ketertiban keamanan;
4) sumber daya alam dan lingkungan; dan 5) pengurangan risiko.
Kegiatan dilaksanakan menggunakan pendekatan pemberdayaan masyarakat yang menempatkan warga terdampak bencana sebagai pelaku aktif dalam mengelola sumber daya alam dan lingkungan dengan tujuan meliputi:
1) meningkatkan pemberdayaan masyarakat dalam upaya pemulihan sumber daya alam dan lingkungan melalui Kelompok Masyarakat;
2) meningkatkan pemanfaatan sumber daya alam dan lingkungan untuk meminimalkan bencana serta meningkatkan produktivitas dengan basis sumber daya endemik;
3) meningkatkan ketangguhan masyarakat dalam menghadapi bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (28, '5) memperluas dan memperkuat jejaring pemasaran produk; dan 6) meningkatkan peran aktif dan dukungan kementerian/lembaga, perangkat daerah, masyarakat/komunitas dan lembaga usaha serta pemangku kepentingan lainnya dalam upaya keberlanjutan dan replikasi program.
