INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (49, 'juklak-1-2025', 30, 'lampiran', 'LAMPIRAN I (lanjutan 1)', NULL, 18, 'Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Pertanian 3.1.1.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Pertanian 3.1.1.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Pertanian 3.1.2 Pembangunan dan/atau Menengah - Tinggi perbaikan bangunan sarana dan prasarana pertanian 3.2 Perkebunan 3.2.1 Pemberdayaan Kelompok Masyarakat Perkebunan Terdampak Bencana 3.2.1.1 Pendampingan Kelompok Rendah Masyarakat Perkebunan 3.2.1.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Perkebunan 3.2.1.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Perkebunan 3.2.1.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Perkebunan 3.2.2 Pembangunan dan/atau Menengah - Tinggi perbaikan bangunan sarana dan prasarana perkebunan 3.3 Peternakan 3.3.1.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (49, 'Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Pertanian 3.1.1.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Pertanian 3.1.1.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Pertanian 3.1.2 Pembangunan dan/atau Menengah - Tinggi perbaikan bangunan sarana dan prasarana pertanian 3.2 Perkebunan 3.2.1 Pemberdayaan Kelompok Masyarakat Perkebunan Terdampak Bencana 3.2.1.1 Pendampingan Kelompok Rendah Masyarakat Perkebunan 3.2.1.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Perkebunan 3.2.1.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Perkebunan 3.2.1.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Perkebunan 3.2.2 Pembangunan dan/atau Menengah - Tinggi perbaikan bangunan sarana dan prasarana perkebunan 3.3 Peternakan 3.3.1.', 'LAMPIRAN I (lanjutan 1)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (50, 'juklak-1-2025', 31, 'lampiran', 'LAMPIRAN I (lanjutan 2)', NULL, 18, 'Pemberdayaan Kelompok Masyarakat Peternakan Terdampak Bencana 3.3.1.1 Pendampingan Kelompok Rendah Masyarakat Perternakan 3.3.1.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Peternakan 3.3.1.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Peternakan 3.3.1.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Peternakan 3.3.2 Pembangunan atau perbaikan Menengah bangunan sarana dan prasarana kandang, gudang dan penyimpanan pakan 3.4 Perikanan 3.4.1 Pemberdayaan Kelompok Masyarakat Perikanan Terdampak Bencana 3.4.1.1 Pendampingan Kelompok Rendah Masyarakat Perikanan 3.4.1.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Perikanan 3.4.1.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Perikanan 3.4.1.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Perikanan 3.4.2 Pembangunan atau perbaikan Menengah - Tinggi bangunan sarana dan prasarana perikanan 3.5 Pariwisata 3.5.1 Pendampingan Kelompok Rendah Masyarakat Pariwisata 3.5.1.1 Pendampingan Kelompok Rendah Masyarakat Pariwisata 3.5.1.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Pariwisata Kecil Menengah 3.5.1.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Pariwisata Kecil Menengah 3.5.1.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Pariwisata Kecil Menengah 3.5.2 Pembangunan atau perbaikan Menengah bangunan sarana dan prasarana fasilitas obyek wisata 3.6 Koperasi, dan Usaha Mikro, Kecil dan Menengah (UMKM) 3.6.1');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (50, 'Pemberdayaan Kelompok Masyarakat Peternakan Terdampak Bencana 3.3.1.1 Pendampingan Kelompok Rendah Masyarakat Perternakan 3.3.1.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Peternakan 3.3.1.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Peternakan 3.3.1.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Peternakan 3.3.2 Pembangunan atau perbaikan Menengah bangunan sarana dan prasarana kandang, gudang dan penyimpanan pakan 3.4 Perikanan 3.4.1 Pemberdayaan Kelompok Masyarakat Perikanan Terdampak Bencana 3.4.1.1 Pendampingan Kelompok Rendah Masyarakat Perikanan 3.4.1.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Perikanan 3.4.1.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Perikanan 3.4.1.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Perikanan 3.4.2 Pembangunan atau perbaikan Menengah - Tinggi bangunan sarana dan prasarana perikanan 3.5 Pariwisata 3.5.1 Pendampingan Kelompok Rendah Masyarakat Pariwisata 3.5.1.1 Pendampingan Kelompok Rendah Masyarakat Pariwisata 3.5.1.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Pariwisata Kecil Menengah 3.5.1.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Pariwisata Kecil Menengah 3.5.1.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Pariwisata Kecil Menengah 3.5.2 Pembangunan atau perbaikan Menengah bangunan sarana dan prasarana fasilitas obyek wisata 3.6 Koperasi, dan Usaha Mikro, Kecil dan Menengah (UMKM) 3.6.1', 'LAMPIRAN I (lanjutan 2)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (51, 'juklak-1-2025', 32, 'lampiran', 'LAMPIRAN I (lanjutan 3)', NULL, 18, 'Pemberdayaan Kelompok Masyarakat Koperasi dan UMKM Terdampak Bencana 3.6.1.1 Pendampingan Kelompok Rendah Masyarakat Koperasi dan UMKM 3.6.1.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Koperasi dan UMKM 3.6.1.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Koperasi dan UMKM 3.6.1.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Koperasi dan UMKM 3.6.2 Pembangunan atau perbaikan Menengah bangunan sarana dan prasarana pasar, ruko, los, kios, loket 3.6.3 Pembangunan atau perbaikan Menengah bangunan sarana dan prasarana industri kecil (pabrik sekala rumah tangga, gudang, gedung administrasi) 3.6.4 Dukungan pemasaran kelompok Rendah masyarakat terdampak bencana 4 SEKTOR SOSIAL 4.1 Kesehatan 4.1.1 Pembangunan kembali atau Tinggi perbaikan bangunan sarana dan prasarana fasilitas kesehatan 4.1.2 Pemberdayaan kelompok masyarakat untuk Pelayanan Posyandu 4.1.2.1 Pendampingan Kelompok Rendah Masyarakat Pelayanan Posyandu 4.1.2.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Pelayanan Posyandu 4.1.2.3 Penguatan Kapasitas Tenaga Rendah Kesehatan dan Kelompok Masyarakat Pelayanan Posyandu 4.1.2.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Pelayanan Posyandu 4.1.3 Pemberdayaan Kelompok Masyarakat Program Pembina Kesejahteraan Keluarga (PKK) 4.1.3.1 Pendampingan Kelompok Rendah Masyarakat Program Pembina Kesejahteraan Keluarga (PKK) 4.1.3.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (51, 'Pemberdayaan Kelompok Masyarakat Koperasi dan UMKM Terdampak Bencana 3.6.1.1 Pendampingan Kelompok Rendah Masyarakat Koperasi dan UMKM 3.6.1.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Koperasi dan UMKM 3.6.1.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Koperasi dan UMKM 3.6.1.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Koperasi dan UMKM 3.6.2 Pembangunan atau perbaikan Menengah bangunan sarana dan prasarana pasar, ruko, los, kios, loket 3.6.3 Pembangunan atau perbaikan Menengah bangunan sarana dan prasarana industri kecil (pabrik sekala rumah tangga, gudang, gedung administrasi) 3.6.4 Dukungan pemasaran kelompok Rendah masyarakat terdampak bencana 4 SEKTOR SOSIAL 4.1 Kesehatan 4.1.1 Pembangunan kembali atau Tinggi perbaikan bangunan sarana dan prasarana fasilitas kesehatan 4.1.2 Pemberdayaan kelompok masyarakat untuk Pelayanan Posyandu 4.1.2.1 Pendampingan Kelompok Rendah Masyarakat Pelayanan Posyandu 4.1.2.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Pelayanan Posyandu 4.1.2.3 Penguatan Kapasitas Tenaga Rendah Kesehatan dan Kelompok Masyarakat Pelayanan Posyandu 4.1.2.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Pelayanan Posyandu 4.1.3 Pemberdayaan Kelompok Masyarakat Program Pembina Kesejahteraan Keluarga (PKK) 4.1.3.1 Pendampingan Kelompok Rendah Masyarakat Program Pembina Kesejahteraan Keluarga (PKK) 4.1.3.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat', 'LAMPIRAN I (lanjutan 3)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (52, 'juklak-1-2025', 33, 'lampiran', 'LAMPIRAN I (lanjutan 4)', NULL, 18, 'Program PKK 4.1.3.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Program PKK 4.1.3.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Program PKK 4.2 Pendidikan 4.2.1 Pembangunan atau perbaikan Menengah - Tinggi bangunan, sarana, prasarana pelayanan pendidikan 4.2.2 Pemberdayaan Kelompok Masyarakat Pendidikan tambahan untuk anak setingkat PAUD, SD, SMP, SMA 4.2.2.1 Pendampingan Kelompok Rendah Masyarakat 4.2.2.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Pendidikan Tambahan Untuk Anak setingkat PAUD, SD, SMP, SMA 4.2.2.3 Penguatan Kapasitas Tenaga Rendah Pendidik, Kependidikan dan Kelompok Masyarakat Pendidikan Tambahan Untuk Anak setingkat PAUD, SD, SMP, SMA 4.2.2.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Pendidikan Tambahan Untuk Anak setingkat PAUD, SD, SMP, SMA 4.2.3 Pemberdayaan Kelompok Masyarakat Pendidikan Agama Anak 4.2.3.1 Pendampingan Kelompok Rendah Masyarakat 4.2.3.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Pendidikan Agama Anak 4.2.3.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Pendidikan Agama Anak 4.2.3.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Pendidikan Agama Anak 4.3 Keagamaan 4.3.1 Pembangunan atau perbaikan Tinggi bangunan, dan sarana prasarana peribadatan 4.3.2 Pemberdayaan Kelompok Masyarakat Aktivitas Keagamaan 4.3.2.1 Pendampingan Kelompok Rendah Masyarakat 4.3.2.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (52, 'Program PKK 4.1.3.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Program PKK 4.1.3.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Program PKK 4.2 Pendidikan 4.2.1 Pembangunan atau perbaikan Menengah - Tinggi bangunan, sarana, prasarana pelayanan pendidikan 4.2.2 Pemberdayaan Kelompok Masyarakat Pendidikan tambahan untuk anak setingkat PAUD, SD, SMP, SMA 4.2.2.1 Pendampingan Kelompok Rendah Masyarakat 4.2.2.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Pendidikan Tambahan Untuk Anak setingkat PAUD, SD, SMP, SMA 4.2.2.3 Penguatan Kapasitas Tenaga Rendah Pendidik, Kependidikan dan Kelompok Masyarakat Pendidikan Tambahan Untuk Anak setingkat PAUD, SD, SMP, SMA 4.2.2.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Pendidikan Tambahan Untuk Anak setingkat PAUD, SD, SMP, SMA 4.2.3 Pemberdayaan Kelompok Masyarakat Pendidikan Agama Anak 4.2.3.1 Pendampingan Kelompok Rendah Masyarakat 4.2.3.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Pendidikan Agama Anak 4.2.3.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Pendidikan Agama Anak 4.2.3.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Pendidikan Agama Anak 4.3 Keagamaan 4.3.1 Pembangunan atau perbaikan Tinggi bangunan, dan sarana prasarana peribadatan 4.3.2 Pemberdayaan Kelompok Masyarakat Aktivitas Keagamaan 4.3.2.1 Pendampingan Kelompok Rendah Masyarakat 4.3.2.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat', 'LAMPIRAN I (lanjutan 4)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (53, 'juklak-1-2025', 34, 'lampiran', 'LAMPIRAN I (lanjutan 5)', NULL, 18, 'Aktivitas Keagamaan (Majelis Taklim, Majelis Gereja) 4.3.2.3 Penguatan Kapasitas Pemuka Rendah Agama, dan Kelompok Masyarakat Aktivitas Keagamaan 4.3.2.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Aktivitas Keagamaan 4.4 Budaya 4.4.1 Pembangunan atau perbaikan Tinggi bangunan sarana dan prasarana cagar budaya atau bangunan bersejarah 4.4.2 Pemberdayaan Kelompok Masyarakat Seni dan Budaya 4.4.2.1 Pendampingan Kelompok Rendah Masyarakat 4.4.2.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Seni dan Budaya 4.4.2.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Seni dan Budaya 4.4.2.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Seni dan Budaya 4.5 Lembaga Sosial 4.5.1 Pemberian dukungan psikososial Rendah-pascabencana (klaster: anak, Menengah remaja, dewasa, lansia) 4.5.2 Pemberdayaan Kelompok Lembaga Sosial Kemasyarakatan 4.5.2.1 Pendampingan Kelompok Rendah Masyarakat 4.5.2.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Lembaga Sosial Kemasyarakatan 4.5.2.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Lembaga Sosial Kemasyarakatan 4.5.2.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Lembaga Sosial Kemasyarakatan 4.5.3 Pemberdayaan Kelompok Masyarakat Bidang Olahraga 4.5.3.1 Pendampingan Kelompok Rendah Masyarakat 4.5.3.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Bidang Olahraga 4.5.3.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Bidang Olahraga 4.5.3.4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (53, 'Aktivitas Keagamaan (Majelis Taklim, Majelis Gereja) 4.3.2.3 Penguatan Kapasitas Pemuka Rendah Agama, dan Kelompok Masyarakat Aktivitas Keagamaan 4.3.2.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Aktivitas Keagamaan 4.4 Budaya 4.4.1 Pembangunan atau perbaikan Tinggi bangunan sarana dan prasarana cagar budaya atau bangunan bersejarah 4.4.2 Pemberdayaan Kelompok Masyarakat Seni dan Budaya 4.4.2.1 Pendampingan Kelompok Rendah Masyarakat 4.4.2.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Seni dan Budaya 4.4.2.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Seni dan Budaya 4.4.2.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Seni dan Budaya 4.5 Lembaga Sosial 4.5.1 Pemberian dukungan psikososial Rendah-pascabencana (klaster: anak, Menengah remaja, dewasa, lansia) 4.5.2 Pemberdayaan Kelompok Lembaga Sosial Kemasyarakatan 4.5.2.1 Pendampingan Kelompok Rendah Masyarakat 4.5.2.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Lembaga Sosial Kemasyarakatan 4.5.2.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Lembaga Sosial Kemasyarakatan 4.5.2.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Lembaga Sosial Kemasyarakatan 4.5.3 Pemberdayaan Kelompok Masyarakat Bidang Olahraga 4.5.3.1 Pendampingan Kelompok Rendah Masyarakat 4.5.3.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Bidang Olahraga 4.5.3.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Bidang Olahraga 4.5.3.4', 'LAMPIRAN I (lanjutan 5)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (54, 'juklak-1-2025', 35, 'lampiran', 'LAMPIRAN I (lanjutan 6)', NULL, 18, 'Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Bidang Olahraga 4.5.4 Pemberdayaan Kelompok Masyarakat Karang Taruna 4.5.4.1 Pendampingan Kelompok Rendah Masyarakat 4.5.4.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Karang Taruna 4.5.4.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Karang Taruna 4.5.4.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Karang Taruna 5 LINTAS SEKTOR 5.1 Pembangunan kembali atau Menengah perbaikan bangunan sarana dan prasarana aset milik Kementerian/Lembaga 5.2 Pembangunan kembali atau Menengah perbaikan bangunan sarana dan prasarana aset kantor milik pemerintahan daerah 5.3 Pemberdayaan masyarakat dalam rehabilitasi hutan dan lahan melalui penataan lahan dan vegetasi seperti pembuatan terasering dan penanaman pohon 5.3.1 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok rehabilitasi hutan dan lahan melalui penataan lahan dan vegetasi seperti pembuatan terasering dan penanaman pohon 5.3.2 Penguatan Kapasitas Kelompok Rendah masyarakat rehabilitasi hutan dan lahan melalui penataan lahan dan vegetasi seperti pembuatan terasering dan penanaman pohon 5.3.3 Penyusunan Rencana Rendah Keberlanjutan Kelompok masyarakat rehabilitasi hutan dan lahan melalui penataan lahan dan vegetasi seperti pembuatan terasering dan penanaman pohon 5.4 Pemberdayaan masyarakat dalam Rehabilitasi kawasan pantai melalui vegetasi dan terumbu karang 5.4.1 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (54, 'Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Bidang Olahraga 4.5.4 Pemberdayaan Kelompok Masyarakat Karang Taruna 4.5.4.1 Pendampingan Kelompok Rendah Masyarakat 4.5.4.2 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok Masyarakat Karang Taruna 4.5.4.3 Penguatan Kapasitas Kelompok Rendah Masyarakat Karang Taruna 4.5.4.4 Penyusunan Rencana Rendah Keberlanjutan Kelompok Masyarakat Karang Taruna 5 LINTAS SEKTOR 5.1 Pembangunan kembali atau Menengah perbaikan bangunan sarana dan prasarana aset milik Kementerian/Lembaga 5.2 Pembangunan kembali atau Menengah perbaikan bangunan sarana dan prasarana aset kantor milik pemerintahan daerah 5.3 Pemberdayaan masyarakat dalam rehabilitasi hutan dan lahan melalui penataan lahan dan vegetasi seperti pembuatan terasering dan penanaman pohon 5.3.1 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok rehabilitasi hutan dan lahan melalui penataan lahan dan vegetasi seperti pembuatan terasering dan penanaman pohon 5.3.2 Penguatan Kapasitas Kelompok Rendah masyarakat rehabilitasi hutan dan lahan melalui penataan lahan dan vegetasi seperti pembuatan terasering dan penanaman pohon 5.3.3 Penyusunan Rencana Rendah Keberlanjutan Kelompok masyarakat rehabilitasi hutan dan lahan melalui penataan lahan dan vegetasi seperti pembuatan terasering dan penanaman pohon 5.4 Pemberdayaan masyarakat dalam Rehabilitasi kawasan pantai melalui vegetasi dan terumbu karang 5.4.1 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok', 'LAMPIRAN I (lanjutan 6)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (55, 'juklak-1-2025', 36, 'lampiran', 'LAMPIRAN I (lanjutan 7)', NULL, 18, 'kawasan pantai 5.4.2 Penguatan Kapasitas Kelompok Rendah masyarakat kawasan pantai) 5.4.3 Penyusunan Rencana Rendah Keberlanjutan Kelompok masyarakat kawasan pantai 5.5 Rehabilitasi daerah aliran Menengah - Tinggi sungai dan daerah tangkapan air melalui vegetasi 5.6 Pemberdayaan masyarakat dalam pengelolaan sampah, limbah padat dan cair 5.6.1 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok pengelolaan sampah, limbah padat dan cair 5.6.2 Penguatan Kapasitas Kelompok Rendah masyarakat pengelolaan sampah, limbah padat dan cair 5.6.3 Penyusunan Rencana Rendah Keberlanjutan Kelompok masyarakat pengelolaan sampah, limbah padat dan cair 5.7 Pemberdayaan masyarakat dalam pengelolaan lahan basah dan lahan kering (good agricultural practices) 5.7.1 Pemberian Bantuan Alat dan Rendah Bahan Stimulan Kelompok pengelolaan lahan basah dan lahan kering (good agricultural practices) 5.7.2 Penguatan Kapasitas Kelompok Rendah masyarakat pengelolaan lahan basah dan lahan kering (good agricultural practices) 5.7.3 Penyusunan Rencana Rendah Keberlanjutan Kelompok masyarakat pengelolaan lahan basah dan lahan kering (good agricultural practices) KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
