INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (56, 'juklak-1-2025', 37, 'lampiran', 'LAMPIRAN II', NULL, 32, 'PETUNJUK PELAKSANAAN PENELAAHAN, VERIFIKASI DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PASCABENCANA NOMOR 1 TAHUN 2025 FORMAT PERMOHONAN PENYALURAN DANA BERSAMA Sistematika penulisan permohonan penyaluran Dana Bersama, paling sedikit memuat:
1. Cover
2. Kata Pengantar
3. Ringkasan Eksekutif
4. Daftar Isi
5. Identitas Pemohon
6. Permohonan
7. Lampiran Contoh penulisan permohonan.
