INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (57, 'juklak-1-2025', 38, 'lampiran', 'LAMPIRAN II (lanjutan 1)', NULL, 35, '(Informasi lain bila ada) ……….., ,,,,,,,,,,,,,,,,,,,,,, Jabatan, (ttd + stempel instansi) Nama Lengkap NIP (apabila ada) PERMOHONAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PASCABENCANA*) (JUDUL, LOKASI, DAN TAHUN KEGIATAN)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (57, '(Informasi lain bila ada) ……….., ,,,,,,,,,,,,,,,,,,,,,, Jabatan, (ttd + stempel instansi) Nama Lengkap NIP (apabila ada) PERMOHONAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PASCABENCANA*) (JUDUL, LOKASI, DAN TAHUN KEGIATAN)', 'LAMPIRAN II (lanjutan 1)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (58, 'juklak-1-2025', 39, 'lain', 'BAB I Pendahuluan', NULL, 36, 'A. Latar Belakang (kurang lebih 400 – 500 kata) ● Gambaran umum: konteks keseluruhan dari pemohon kegiatan, profil bencana singkat, dampak kerugian dan kerusakan bencana, gambaran rencana rehabilitasi dan rekonstruksi pascabencana, serta faktor historis, sosial dan ekonomi yang melatarbelakangi permohonan. ● Pernyataan masalah: deskripsi masalah secara jelas, data-data yang mendukung, dan dampak negatif apabila masalah tidak diselesaikan. ● Kesenjangan dan tantangan: identifikasi kesenjangan dan tantangan dalam menghadapi masalah, serta mengapa keadaan sekarang tidak cukup untuk mengatasi masalah tersebut. ● Kesesuaian dengan ESMS: Penjelasan bahwa pemohon kegiatan tidak masuk dalam Daftar Negatif serta telah mempertimbangkan risiko-risiko lingkungan dan sosial sesuai persyaratan.
B. Maksud dan Tujuan (kurang lebih 150 – 200 kata) ● Jelaskan apa tujuan dan sasaran menyeluruh dari pemohon kegiatan. ● Relevansi pemohon kegiatan untuk mengatasi masalah: penjabaran bagaimana pemohon kegiatan dapat mengatasi masalah serta kesenjangan dan tantangan yang teridentifikasi.
C. Ruang Lingkup (kurang lebih 50 – 100 kata) ● Penjelasan mengenai batasan – batasan untuk kegiatan yang diusulkan D. Keluaran (kurang lebih 150 – 200 kata) ● Gambarkan secara jelas keluaran yang akan dihasilkan dari pemohon kegiatan serta keterkaitannya dengan pencapaian tujuan kegiatan ● Penjabaran kriteria SMART (Specific, Measurable, Achievable, Realistic, Timely) terhadap keluaran yang akan dihasilkan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (58, 'A. Latar Belakang (kurang lebih 400 – 500 kata) ● Gambaran umum: konteks keseluruhan dari pemohon kegiatan, profil bencana singkat, dampak kerugian dan kerusakan bencana, gambaran rencana rehabilitasi dan rekonstruksi pascabencana, serta faktor historis, sosial dan ekonomi yang melatarbelakangi permohonan. ● Pernyataan masalah: deskripsi masalah secara jelas, data-data yang mendukung, dan dampak negatif apabila masalah tidak diselesaikan. ● Kesenjangan dan tantangan: identifikasi kesenjangan dan tantangan dalam menghadapi masalah, serta mengapa keadaan sekarang tidak cukup untuk mengatasi masalah tersebut. ● Kesesuaian dengan ESMS: Penjelasan bahwa pemohon kegiatan tidak masuk dalam Daftar Negatif serta telah mempertimbangkan risiko-risiko lingkungan dan sosial sesuai persyaratan.
B. Maksud dan Tujuan (kurang lebih 150 – 200 kata) ● Jelaskan apa tujuan dan sasaran menyeluruh dari pemohon kegiatan. ● Relevansi pemohon kegiatan untuk mengatasi masalah: penjabaran bagaimana pemohon kegiatan dapat mengatasi masalah serta kesenjangan dan tantangan yang teridentifikasi.
C. Ruang Lingkup (kurang lebih 50 – 100 kata) ● Penjelasan mengenai batasan – batasan untuk kegiatan yang diusulkan D. Keluaran (kurang lebih 150 – 200 kata) ● Gambarkan secara jelas keluaran yang akan dihasilkan dari pemohon kegiatan serta keterkaitannya dengan pencapaian tujuan kegiatan ● Penjabaran kriteria SMART (Specific, Measurable, Achievable, Realistic, Timely) terhadap keluaran yang akan dihasilkan', 'BAB I Pendahuluan', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (59, 'juklak-1-2025', 40, 'lain', 'BAB II Gambaran Umum', NULL, 36, 'A. Profil Institusi (K/L) atau Profil Daerah (Pemerintah Daerah & Kelompok Masyarakat) (kurang lebih 150 – 200 kata) ● Gambaran umum mengenai profil pemohon, tugas dan fungsi institusi, struktur organisasi, dan wilayah yang akan menjadi lokasi kegiatan B. Laporan Kejadian Bencana ● Laporan yang dibuat oleh Pusdalops BPBD baik fisik dan/atau elektronik yang tercatat di Pusdalops BNPB ● Dapat dilengkapi dengan artikel media cetak/elektronik tentang kejadian bencana yang memuat jenis bencana, waktu kejadian bencana, dan/atau lokasi kejadian bencana ● Tingkat Indeks Ketahanan Daerah ● Data bencana yang paling sering terjadi serta kondisi kerentanan dan kapasitas C. Kondisi Anggaran (kurang lebih 150 – 200 kata) ● Penjelasan mengenai postur anggaran di K/L atau kapasitas fiskal di Pemda dalam 2 – 3 tahun terakhir ● Penjelasan apakah terdapat anggaran khusus untuk penanggulangan bencana.
D. Riwayat Kerja Sama Lembaga/Donor (kurang lebih 150 – 200 kata) ● Penjelasan mengenai riwayat kerja sama institusi pemohon dengan donor, apakah pernah menerima bantuan program atau kerja sama dengan lembaga donor nasional atau internasional dalam kurun waktu 5 (lima) tahun terakhir, apabila ada. ● Deskripsi mengenai program, anggaran, pelaksana dan hasil dari program kolaborasi tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (59, 'A. Profil Institusi (K/L) atau Profil Daerah (Pemerintah Daerah & Kelompok Masyarakat) (kurang lebih 150 – 200 kata) ● Gambaran umum mengenai profil pemohon, tugas dan fungsi institusi, struktur organisasi, dan wilayah yang akan menjadi lokasi kegiatan B. Laporan Kejadian Bencana ● Laporan yang dibuat oleh Pusdalops BPBD baik fisik dan/atau elektronik yang tercatat di Pusdalops BNPB ● Dapat dilengkapi dengan artikel media cetak/elektronik tentang kejadian bencana yang memuat jenis bencana, waktu kejadian bencana, dan/atau lokasi kejadian bencana ● Tingkat Indeks Ketahanan Daerah ● Data bencana yang paling sering terjadi serta kondisi kerentanan dan kapasitas C. Kondisi Anggaran (kurang lebih 150 – 200 kata) ● Penjelasan mengenai postur anggaran di K/L atau kapasitas fiskal di Pemda dalam 2 – 3 tahun terakhir ● Penjelasan apakah terdapat anggaran khusus untuk penanggulangan bencana.
D. Riwayat Kerja Sama Lembaga/Donor (kurang lebih 150 – 200 kata) ● Penjelasan mengenai riwayat kerja sama institusi pemohon dengan donor, apakah pernah menerima bantuan program atau kerja sama dengan lembaga donor nasional atau internasional dalam kurun waktu 5 (lima) tahun terakhir, apabila ada. ● Deskripsi mengenai program, anggaran, pelaksana dan hasil dari program kolaborasi tersebut.', 'BAB II Gambaran Umum', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (60, 'juklak-1-2025', 41, 'lain', 'BAB III Permohonan Kegiatan', NULL, 37, '1. Rekapitulasi permohonan kegiatan ● Rekapitulasi permohonan kegiatan rehabilitasi dan rekonstruksi pascabencana memuat nama kegiatan, lokasi, volume, satuan, harga satuan, dan total anggaran yang ditandatangani oleh Pejabat Pimpinan Tinggi Pratama pada kementerian/lembaga atau Kepala Pelaksana BPBD.
2. Pendekatan (kurang lebih 300 - 500 kata) ● Penggambaran mengenai metode kegiatan yang akan dilakukan dengan sorotan pada aspek inovatif metode yang dipilih. ● Penggambaran pemangku kepentingan yang akan terlibat dalam implementasi kegiatan ● Penjelasan kepatuhan pemohon kegiatan dengan prinsip dan pendekatan strategis serta standar sosial dan lingkungan ● Identifikasi potensi risiko dari pemohon kegiatan dan langkah-langkah memitigasi potensi risiko tersebut
3. Metodologi (kurang lebih 300 – 500 kata) ● Penjelasan mengenai tahapan pelaksanaan kegiatan ● Hasil yang akan dicapai dalam tiap tahapan (milestone) ● Keterkaitan masing-masing tahapan dalam mencapai tujuan ● Alur kronologis dari setiap tahapan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (60, '1. Rekapitulasi permohonan kegiatan ● Rekapitulasi permohonan kegiatan rehabilitasi dan rekonstruksi pascabencana memuat nama kegiatan, lokasi, volume, satuan, harga satuan, dan total anggaran yang ditandatangani oleh Pejabat Pimpinan Tinggi Pratama pada kementerian/lembaga atau Kepala Pelaksana BPBD.
2. Pendekatan (kurang lebih 300 - 500 kata) ● Penggambaran mengenai metode kegiatan yang akan dilakukan dengan sorotan pada aspek inovatif metode yang dipilih. ● Penggambaran pemangku kepentingan yang akan terlibat dalam implementasi kegiatan ● Penjelasan kepatuhan pemohon kegiatan dengan prinsip dan pendekatan strategis serta standar sosial dan lingkungan ● Identifikasi potensi risiko dari pemohon kegiatan dan langkah-langkah memitigasi potensi risiko tersebut
3. Metodologi (kurang lebih 300 – 500 kata) ● Penjelasan mengenai tahapan pelaksanaan kegiatan ● Hasil yang akan dicapai dalam tiap tahapan (milestone) ● Keterkaitan masing-masing tahapan dalam mencapai tujuan ● Alur kronologis dari setiap tahapan', 'BAB III Permohonan Kegiatan', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (61, 'juklak-1-2025', 42, 'lain', 'BAB III Permohonan Kegiatan (lanjutan 1)', NULL, 37, '4. Pelaksana (kurang lebih 200 – 300 kata) ● Penjelasan mengenai susunan tim pelaksana kegiatan beserta pihak yang akan mengawasi implementasi kegiatan ● Pengalaman atau rekam jejak dalam melaksanakan kegiatan serupa ● Identifikasi personil kunci yang akan terlibat, kualifikasi yang dimiliki serta bagaimana keahlian mereka berkontribusi terhadap implementasi kegiatan ● Penjelasan mengenai pembagian peran dan tanggung jawab tim pelaksana dan personil kunci untuk mencegah ambiguitas ● Pengembangan kapasitas terhadap tim pelaksana dan personil kunci dalam upaya keberlanjutan kegiatan
5. Rencana Kerja (timeline) (kurang lebih 200 – 400 kata) ● Penjelasan mengenai rincian kegiatan yang akan dilakukan setiap bulan atau triwulan serta milestone yang akan dicapai ● Pastikan keselarasan antara rencana kerja dengan tahapan yang diuraikan pada bagian metodologi
6. Gambar Rencana Kegiatan (untuk kegiatan konstruksi) ● Untuk jenis kegiatan konstruksi ● Berisi tentang site plan dan gambar detail kegiatan yang ditandatangani oleh instansi teknis terkait
7. Rencana Kerja dan Syarat ● Berisikan penjelasan proyek secara rinci mulai dari jenis, besar, dan lokasi yang menjelaskan mengenai kegiatan yang akan dilaksanakan.
8. Kurva S ● Berisikan formulasi penjumlahan persentase kumulatif bobot masing-masing kegiatan pada suatu periode di antara durasi kegiatan dan diplotkan terhadap sumbu vertikal sehingga jika garis-garis tersebut dihubungkan, maka akan membentuk huruf S.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (61, '4. Pelaksana (kurang lebih 200 – 300 kata) ● Penjelasan mengenai susunan tim pelaksana kegiatan beserta pihak yang akan mengawasi implementasi kegiatan ● Pengalaman atau rekam jejak dalam melaksanakan kegiatan serupa ● Identifikasi personil kunci yang akan terlibat, kualifikasi yang dimiliki serta bagaimana keahlian mereka berkontribusi terhadap implementasi kegiatan ● Penjelasan mengenai pembagian peran dan tanggung jawab tim pelaksana dan personil kunci untuk mencegah ambiguitas ● Pengembangan kapasitas terhadap tim pelaksana dan personil kunci dalam upaya keberlanjutan kegiatan
5. Rencana Kerja (timeline) (kurang lebih 200 – 400 kata) ● Penjelasan mengenai rincian kegiatan yang akan dilakukan setiap bulan atau triwulan serta milestone yang akan dicapai ● Pastikan keselarasan antara rencana kerja dengan tahapan yang diuraikan pada bagian metodologi
6. Gambar Rencana Kegiatan (untuk kegiatan konstruksi) ● Untuk jenis kegiatan konstruksi ● Berisi tentang site plan dan gambar detail kegiatan yang ditandatangani oleh instansi teknis terkait
7. Rencana Kerja dan Syarat ● Berisikan penjelasan proyek secara rinci mulai dari jenis, besar, dan lokasi yang menjelaskan mengenai kegiatan yang akan dilaksanakan.
8. Kurva S ● Berisikan formulasi penjumlahan persentase kumulatif bobot masing-masing kegiatan pada suatu periode di antara durasi kegiatan dan diplotkan terhadap sumbu vertikal sehingga jika garis-garis tersebut dihubungkan, maka akan membentuk huruf S.', 'BAB III Permohonan Kegiatan (lanjutan 1)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (62, 'juklak-1-2025', 43, 'lain', 'BAB III Permohonan Kegiatan (lanjutan 2)', NULL, 38, '9. Kerangka pemantauan dan evaluasi (kurang lebih 300 – 500 kata) ● Penjelasan mengenai urgensi pemantauan dan evaluasi serta komponen dan metodologi yang digunakan untuk pemantauan dan evaluasi ● Penjelasan mengenai Indikator Kinerja Utama (IKU) yang dipilih untuk mengukur keberhasilan kegiatan serta alasan pemilihannya ● Penjelasan mengenai metode untuk mendapat umpan balik dari para pemangku kepentingan yang terlibat ● Frekuensi melakukan pemantauan dan evaluasi selama implementasi kegiatan ● Penjelasan mengenai langkah-langkah melakukan evaluasi, kriteria keberhasilan program serta hasil yang diharapkan dari evaluasi
10. Rencana tindak lanjut (kurang lebih 200 – 300 kata) ● Penjelasan mengenai langkah-langkah yang akan diambil oleh pemohon untuk memastikan keberlanjutan kegiatan setelah selesai implementasi ● Gambaran mengenai dampak-dampak lanjutan apa yang akan dicapai dengan keberlanjutan kegiatan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (62, '9. Kerangka pemantauan dan evaluasi (kurang lebih 300 – 500 kata) ● Penjelasan mengenai urgensi pemantauan dan evaluasi serta komponen dan metodologi yang digunakan untuk pemantauan dan evaluasi ● Penjelasan mengenai Indikator Kinerja Utama (IKU) yang dipilih untuk mengukur keberhasilan kegiatan serta alasan pemilihannya ● Penjelasan mengenai metode untuk mendapat umpan balik dari para pemangku kepentingan yang terlibat ● Frekuensi melakukan pemantauan dan evaluasi selama implementasi kegiatan ● Penjelasan mengenai langkah-langkah melakukan evaluasi, kriteria keberhasilan program serta hasil yang diharapkan dari evaluasi
10. Rencana tindak lanjut (kurang lebih 200 – 300 kata) ● Penjelasan mengenai langkah-langkah yang akan diambil oleh pemohon untuk memastikan keberlanjutan kegiatan setelah selesai implementasi ● Gambaran mengenai dampak-dampak lanjutan apa yang akan dicapai dengan keberlanjutan kegiatan', 'BAB III Permohonan Kegiatan (lanjutan 2)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (63, 'juklak-1-2025', 44, 'lain', 'BAB IV Penutup (kurang lebih 150 – 200 kata)', NULL, 38, '● Ringkasan mengenai isi permohonan secara keseluruhan: tujuan utama, keluaran serta dampak yang diharapkan ● Penekanan mengenai pentingnya permohonan kegiatan untuk mendapatkan dukungan pendanaan guna mengatasi permasalahan yang ada Penanggung Jawab Kegiatan, (ttd + stempel instansi) (Nama dan tanda tangan) Lampiran
a. Surat Pengantar Permohonan Penyaluran Dana Bersama ditandatangani oleh Kepala Daerah atau K/L)
b. Keputusan Tanggap Darurat atau Surat Pernyataan Bencana
c. Rekapitulasi Permohonan Kegiatan
d. Surat Pernyataan Kewenangan
e. Narasi permohonan
f. Dokumen Rencana Rehabilitasi dan Rekonstruksi Pascabencana
g. Reviu aparat pengawas intern pemerintah (Format reviu disesuaikan dengan tata naskah dinas yang berlaku pada instansi pemohon)
h. Dokumen pengelolaan lingkungan dan sosial
i. Laporan kejadian bencana
j. Dokumentasi Aset Rusak
k. Kartu Inventaris Barang
l. Surat keterangan verifikasi kelompok masyarakat dari instansi pembina sesuai ruang lingkupnya dan kewenangannya
m. Rencana anggaran dan biaya (RAB)
n. Gambar rencana kegiatan (untuk permohonan kegiatan konstruksi)
o. Rencana kerja dan syarat
p. Kurva S
q. Keputusan Kepala Daerah tentang Penetapan Penerima Bantuan Nonkonstruksi (khusus untuk bantuan stimulan rumah)
r. Keputusan mengenai Pembentukan Kelompok Masyarakat (khusus untuk kegiatan nonkonstruksi)
s. Keputusan mengenai Kelompok Masyarakat Penerima Bantuan Nonkonstruksi
t. Ringkasan APBD Penanggulangan Bencana (Untuk Pemohon dari Pemerintah Daerah)');
