INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (65, 'juklak-1-2025', 46, 'lampiran', 'LAMPIRAN III', NULL, 40, 'PETUNJUK PELAKSANAAN PENELAAHAN, VERIFIKASI DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 1 TAHUN 2025 FORMAT DOKUMEN PERSYARATAN PERMOHONAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PASCABENCANA Format 1 - Surat Permohonan Penyaluran dari Kementerian/Lembaga KOP SURAT KEMENTERIAN/LEMBAGA PEMOHON ………………., …………………… Nomor :
Lampiran :
Hal :
