INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (68, 'juklak-1-2025', 49, 'lampiran', 'LAMPIRAN III (lanjutan 3)', NULL, 45, 'No Waktu Lokasi Jenis Keterangan 1 2 Kejadian bencana alam tersebut di atas berdampak kepada kehidupan dan penghidupan masyarakat dan memerlukan penanganan segera.
