INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (70, 'juklak-1-2025', 51, 'lampiran', 'LAMPIRAN IV', NULL, 49, 'PETUNJUK PELAKSANAAN PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PASCABENCANA NOMOR 1 TAHUN 2025 FORMAT LAPORAN Sistematika penulisan sampul, paling sedikit memuat:
