INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (71, 'juklak-1-2025', 52, 'lampiran', 'LAMPIRAN IV (lanjutan 1)', NULL, 52, 'Jumlah Dana yang diterima : Rp. ………………………………………… (terbilang) : ……………………………………………… ……….., ……………. ... Jabatan … (ttd dan stempel instansi) Nama Lengkap NIP. (apabila ada) LAPORAN PEMANTAUAN KEGIATAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA (JUDUL, LOKASI DAN TAHUN KEGIATAN) PERIODE: Pendahuluan / Akhir Bab I Pendahuluan A. Latar Belakang (kurang lebih 400 – 500 kata) ● Gambaran umum: konteks keseluruhan dari permohonan kegiatan, profil bencana singkat, serta faktor historis, sosial dan ekonomi yang melatarbelakangi permohonan ● Pernyataan masalah: deskripsi masalah secara jelas, data-data yang mendukung, dan dampak negatif apabila masalah tidak diselesaikan ● Kesenjangan dan tantangan: identifikasi kesenjangan dan tantangan dalam menghadapi masalah, serta mengapa keadaan sekarang tidak cukup untuk mengatasi masalah tersebut ● Kesesuaian dengan Sistem Pengelolaan Lingkungan dan Sosial: Penjelasan bahwa pelaksanaan kegiatan tidak masuk dalam Daftar Negatif serta telah mempertimbangkan risiko-risiko lingkungan dan sosial sesuai persyaratan B. Maksud dan Tujuan (kurang lebih 150 – 200 kata) ● Jelaskan apa tujuan dan sasaran menyeluruh dari permohonan kegiatan ● Relevansi kegiatan dalam mengatasi masalah serta kesenjangan dan tantangan yang teridentifikasi C. Ruang Lingkup (kurang lebih 50 – 100 kata) ● Penjelasan mengenai batasan-batasan untuk kegiatan yang diusulkan D.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (71, 'Jumlah Dana yang diterima : Rp. ………………………………………… (terbilang) : ……………………………………………… ……….., ……………. ... Jabatan … (ttd dan stempel instansi) Nama Lengkap NIP. (apabila ada) LAPORAN PEMANTAUAN KEGIATAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA (JUDUL, LOKASI DAN TAHUN KEGIATAN) PERIODE: Pendahuluan / Akhir Bab I Pendahuluan A. Latar Belakang (kurang lebih 400 – 500 kata) ● Gambaran umum: konteks keseluruhan dari permohonan kegiatan, profil bencana singkat, serta faktor historis, sosial dan ekonomi yang melatarbelakangi permohonan ● Pernyataan masalah: deskripsi masalah secara jelas, data-data yang mendukung, dan dampak negatif apabila masalah tidak diselesaikan ● Kesenjangan dan tantangan: identifikasi kesenjangan dan tantangan dalam menghadapi masalah, serta mengapa keadaan sekarang tidak cukup untuk mengatasi masalah tersebut ● Kesesuaian dengan Sistem Pengelolaan Lingkungan dan Sosial: Penjelasan bahwa pelaksanaan kegiatan tidak masuk dalam Daftar Negatif serta telah mempertimbangkan risiko-risiko lingkungan dan sosial sesuai persyaratan B. Maksud dan Tujuan (kurang lebih 150 – 200 kata) ● Jelaskan apa tujuan dan sasaran menyeluruh dari permohonan kegiatan ● Relevansi kegiatan dalam mengatasi masalah serta kesenjangan dan tantangan yang teridentifikasi C. Ruang Lingkup (kurang lebih 50 – 100 kata) ● Penjelasan mengenai batasan-batasan untuk kegiatan yang diusulkan D.', 'LAMPIRAN IV (lanjutan 1)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (72, 'juklak-1-2025', 53, 'lampiran', 'LAMPIRAN IV (lanjutan 2)', NULL, 52, 'Keluaran (kurang lebih 150 – 200 kata) ● Gambarkan secara jelas keluaran yang dihasilkan dari pelaksanaan kegiatan serta keterkaitannya dengan pencapaian tujuan kegiatan ● Penjabaran kriteria SMART (Specific, Measurable, Achievable, Realistic, Timely) terhadap keluaran yang dihasilkan E. Dasar Pelaksanaan (kurang lebih 150 – 200 kata) ● Identifikasi regulasi-regulasi dan dokumen-dokumen yang menjadi dasar pelaksanaan kegiatan (misal Peraturan Presiden Nomor 75 Tahun 2021, Peraturan BNPB Nomor 1 Tahun 2024, dll) Bab II Pelaksanaan Kegiatan A. Lokasi dan Jadwal Pelaksanaan (kurang lebih 150 – 200 kata) ● Penjelasan mengenai wilayah yang menjadi lokasi kegiatan serta penjabaran progres jadwal pelaksanaan kegiatan didukung dengan representasi visual berupa tabel B. Pelaksana (kurang lebih 200 – 300 kata) ● Penjelasan mengenai pihak-pihak yang menjadi pelaksana kegiatan beserta uraian pembagian peran dan tanggung jawab dalam implementasi ● Penjelasan mengenai keterlibatan personil kunci sebagaimana tercantum dalam permohonan ● Penjabaran peningkatan kapasitas yang dialami oleh tim pelaksana dan personil kunci dalam kaitannya untuk keberlanjutan kegiatan C. Sasaran (kurang lebih 150 – 200 kata) ● Penjelasan apakah sasaran kegiatan masih sesuai dengan perencanaan sebagaimana termuat dalam permohonan. Berikan penjelasan tambahan apabila ada perubahan sasaran. ● Penggambaran apakah tujuan kegiatan yang terkait dengan sasaran dapat tercapai atau tidak D.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (72, 'Keluaran (kurang lebih 150 – 200 kata) ● Gambarkan secara jelas keluaran yang dihasilkan dari pelaksanaan kegiatan serta keterkaitannya dengan pencapaian tujuan kegiatan ● Penjabaran kriteria SMART (Specific, Measurable, Achievable, Realistic, Timely) terhadap keluaran yang dihasilkan E. Dasar Pelaksanaan (kurang lebih 150 – 200 kata) ● Identifikasi regulasi-regulasi dan dokumen-dokumen yang menjadi dasar pelaksanaan kegiatan (misal Peraturan Presiden Nomor 75 Tahun 2021, Peraturan BNPB Nomor 1 Tahun 2024, dll) Bab II Pelaksanaan Kegiatan A. Lokasi dan Jadwal Pelaksanaan (kurang lebih 150 – 200 kata) ● Penjelasan mengenai wilayah yang menjadi lokasi kegiatan serta penjabaran progres jadwal pelaksanaan kegiatan didukung dengan representasi visual berupa tabel B. Pelaksana (kurang lebih 200 – 300 kata) ● Penjelasan mengenai pihak-pihak yang menjadi pelaksana kegiatan beserta uraian pembagian peran dan tanggung jawab dalam implementasi ● Penjelasan mengenai keterlibatan personil kunci sebagaimana tercantum dalam permohonan ● Penjabaran peningkatan kapasitas yang dialami oleh tim pelaksana dan personil kunci dalam kaitannya untuk keberlanjutan kegiatan C. Sasaran (kurang lebih 150 – 200 kata) ● Penjelasan apakah sasaran kegiatan masih sesuai dengan perencanaan sebagaimana termuat dalam permohonan. Berikan penjelasan tambahan apabila ada perubahan sasaran. ● Penggambaran apakah tujuan kegiatan yang terkait dengan sasaran dapat tercapai atau tidak D.', 'LAMPIRAN IV (lanjutan 2)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (73, 'juklak-1-2025', 54, 'lampiran', 'LAMPIRAN IV (lanjutan 3)', NULL, 52, 'Pemangku Kepentingan (kurang lebih 150 – 200 kata) ● Identifikasi seluruh komponen pemangku kepentingan yang terlibat selama implementasi kegiatan serta peran dan tanggung jawab masing masing E. Metode Pelaksanaan (kurang lebih 200 – 300 kata) ● Penjelasan mengenai metode pelaksanaan dan tahap-tahap kegiatan, dengan sorotan pada aspek inovasi yang diterapkan ● Penjelasan apakah terdapat perubahan metode dan tahapan kegiatan dari yang termuat dalam permohonan serta alasannya F. Progres Pelaksanaan (kurang lebih 250 – 350 kata) ● Penjabaran progres indikator kinerja utama yang telah dicapai dalam pelaksanaan kegiatan sesuai dengan rencana kerja dan tahapan yang tercantum dalam permohonan dalam bentuk tabel dengan deskripsi naratif Bab III Pemantauan Kegiatan A. Analisis SWOT (kurang lebih 200 – 300 kata) ● Identifikasi strength (kekuatan), weaknesses (kelemahan), opportunity (kesempatan) serta threat (tantangan) dalam pelaksanaan kegiatan dalam bentuk tabel disertai penjelasan naratif ● Penjelasan mengenai langkah-langkah yang diambil oleh tim pelaksana kegiatan untuk memanfaatkan kekuatan dan kesempatan, serta mengatasi kelemahan dan tantangan yang teridentifikasi B. Kepatuhan terhadap sistem pengelolaan lingkungan dan sosial (kurang lebih 300 – 500 kata) ● Ringkasan, rencana, dan kinerja manajemen risiko lingkungan dan sosial selama pelaksanaan kegiatan; ● Evaluasi pelaksanaan manajemen risiko lingkungan dan sosial; dan ● Kesimpulan dan pelajaran yang didapat C.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (73, 'Pemangku Kepentingan (kurang lebih 150 – 200 kata) ● Identifikasi seluruh komponen pemangku kepentingan yang terlibat selama implementasi kegiatan serta peran dan tanggung jawab masing masing E. Metode Pelaksanaan (kurang lebih 200 – 300 kata) ● Penjelasan mengenai metode pelaksanaan dan tahap-tahap kegiatan, dengan sorotan pada aspek inovasi yang diterapkan ● Penjelasan apakah terdapat perubahan metode dan tahapan kegiatan dari yang termuat dalam permohonan serta alasannya F. Progres Pelaksanaan (kurang lebih 250 – 350 kata) ● Penjabaran progres indikator kinerja utama yang telah dicapai dalam pelaksanaan kegiatan sesuai dengan rencana kerja dan tahapan yang tercantum dalam permohonan dalam bentuk tabel dengan deskripsi naratif Bab III Pemantauan Kegiatan A. Analisis SWOT (kurang lebih 200 – 300 kata) ● Identifikasi strength (kekuatan), weaknesses (kelemahan), opportunity (kesempatan) serta threat (tantangan) dalam pelaksanaan kegiatan dalam bentuk tabel disertai penjelasan naratif ● Penjelasan mengenai langkah-langkah yang diambil oleh tim pelaksana kegiatan untuk memanfaatkan kekuatan dan kesempatan, serta mengatasi kelemahan dan tantangan yang teridentifikasi B. Kepatuhan terhadap sistem pengelolaan lingkungan dan sosial (kurang lebih 300 – 500 kata) ● Ringkasan, rencana, dan kinerja manajemen risiko lingkungan dan sosial selama pelaksanaan kegiatan; ● Evaluasi pelaksanaan manajemen risiko lingkungan dan sosial; dan ● Kesimpulan dan pelajaran yang didapat C.', 'LAMPIRAN IV (lanjutan 3)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (74, 'juklak-1-2025', 55, 'lampiran', 'LAMPIRAN IV (lanjutan 4)', NULL, 52, 'Hasil Pemantauan (kurang lebih 300 – 500 kata) ● Penjelasan apabila terdapat perubahan untuk kerangka pemantauan dan evaluasi implementasi kegiatan, termasuk frekuensi dan langkah pelaksanaannya ● Penjelasan mengenai serapan realisasi anggaran untuk pelaksanaan kegiatan yang sudah berjalan ● Identifikasi penyebab serta solusi apabila ada percepatan atau keterlambatan pencapaian progres ● Penjelasan apakah Indikator Kinerja Utama (IKU) yang dipilih telah sesuai untuk menggambarkan efektivitas dan keberhasilan kegiatan ● Penjelasan apakah metode umpan balik pemangku kepentingan dapat berjalan dengan baik ● Identifikasi kesesuaian spesifikasi barang dan jasa dengan yang tercantum di permohonan, serta penjelasan apabila ada perubahan D. Rencana Tindak Lanjut (kurang lebih 150 - 250 kata) ● Identifikasi pembelajaran positif dan negatif yang dapat diambil dari implementasi kegiatan ● Penjelasan apabila terdapat perubahan terhadap langkah-langkah yang akan diambil oleh tim pelaksana kegiatan untuk memastikan keberlanjutan kegiatan Bab IV Kesimpulan dan Saran (kurang lebih 150 – 200 kata) ● Penjelasan mengenai kesimpulan yang didapatkan dari progres pelaksanaan kegiatan ● Saran-saran yang dapat diberikan untuk perbaikan pelaksanaan kegiatan ke depan Bab V Penutup (kurang lebih 150 – 200 kata) ● Ringkasan mengenai isi laporan secara singkat: realisasi pelaksanaan kegiatan serta perubahan-perubahan yang teridentifikasi ● Komitmen tim pelaksana kegiatan untuk melakukan perbaikan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (74, 'Hasil Pemantauan (kurang lebih 300 – 500 kata) ● Penjelasan apabila terdapat perubahan untuk kerangka pemantauan dan evaluasi implementasi kegiatan, termasuk frekuensi dan langkah pelaksanaannya ● Penjelasan mengenai serapan realisasi anggaran untuk pelaksanaan kegiatan yang sudah berjalan ● Identifikasi penyebab serta solusi apabila ada percepatan atau keterlambatan pencapaian progres ● Penjelasan apakah Indikator Kinerja Utama (IKU) yang dipilih telah sesuai untuk menggambarkan efektivitas dan keberhasilan kegiatan ● Penjelasan apakah metode umpan balik pemangku kepentingan dapat berjalan dengan baik ● Identifikasi kesesuaian spesifikasi barang dan jasa dengan yang tercantum di permohonan, serta penjelasan apabila ada perubahan D. Rencana Tindak Lanjut (kurang lebih 150 - 250 kata) ● Identifikasi pembelajaran positif dan negatif yang dapat diambil dari implementasi kegiatan ● Penjelasan apabila terdapat perubahan terhadap langkah-langkah yang akan diambil oleh tim pelaksana kegiatan untuk memastikan keberlanjutan kegiatan Bab IV Kesimpulan dan Saran (kurang lebih 150 – 200 kata) ● Penjelasan mengenai kesimpulan yang didapatkan dari progres pelaksanaan kegiatan ● Saran-saran yang dapat diberikan untuk perbaikan pelaksanaan kegiatan ke depan Bab V Penutup (kurang lebih 150 – 200 kata) ● Ringkasan mengenai isi laporan secara singkat: realisasi pelaksanaan kegiatan serta perubahan-perubahan yang teridentifikasi ● Komitmen tim pelaksana kegiatan untuk melakukan perbaikan', 'LAMPIRAN IV (lanjutan 4)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Nomor 1 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (75, 'juklak-1-2025', 56, 'lampiran', 'LAMPIRAN IV (lanjutan 5)', NULL, 52, 'implementasi kegiatan ke depan Penanggung Jawab Kegiatan, (ttd dan stempel instansi) Nama Lengkap Lampiran ● Dokumentasi setiap tahapan kegiatan disertai dengan narasi penjelasan. ● Dokumen-dokumen pendukung lain yang diperlukan untuk menunjukkan progres kegiatan. *) Pilih salah satu **) Sistematika laporan menyesuaikan kebutuhan permohonan kegiatan.
