INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (78, 'juklak-15-2025', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BA0AN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN BANTUAN DANA TUNGGU HUNIAN UNTUK PROVlNSI ACEH , SUMATERA UTARA DAN SUMATERA BARAT AKIBAT BENCANA ALAM NOMOR 15 TAHUN 2025');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (78, 'SALINAN KEPALA BA0AN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN BANTUAN DANA TUNGGU HUNIAN UNTUK PROVlNSI ACEH , SUMATERA UTARA DAN SUMATERA BARAT AKIBAT BENCANA ALAM NOMOR 15 TAHUN 2025', 'Isi hal. 1', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian untuk Provinsi Aceh, Sumatera Utara dan Sumatera Barat Akibat Bencana Alam Nomor 15 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (79, 'juklak-15-2025', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Lalar Bclakang Tcrjadinya pcningkatan jumlah kcjadian bcncana di Indonesia disclfap tahunnya, dan scrangkaian bcncana yang mcnimbulkan kcrugian material dan korban j iwa dalam skala bcsar pada wilayah Provinsi Acch, Provinsi Sumatcra Barat, dan Provinsi Sumatcra Utara. Dampak yang dilimbulkan dari kcjadian bcncana bcrpengaruh tcrhadap kondisi sosial, ckonomi, dan kcscjahlcraan masyarakat, tcrmasuk tcrganggunya fungsi hunian scl;>agai kcbuluhan dasar bagi masyarakat lcrdampak.
Sebagai upaya dalam mcmbcrikan pcrlindungan dan pcmcnuhan kcbutuhan dasar masyarakal tcrdampak bcncana yang tclah lcrjadi pada wilayah Provinsi Aceh, Provinsi Sumalcra Baral, dan Provinsi Sumatcra Utara, Pemcrintah mclakukan pcrccpatan pcnanganan pcnanggulangan bcncana sccara scrius dan ccpat. Salah satu bcntuk dukungan pcrcepatan pcnanganan dalam pcnyclcnggaraan pcnanggulangan bencana yang dilaksanakan Pcmcrintah ya.itu pcmbcrian Bantuan Dana Tunggu Hunian scbagai fasililas pcndukung hunion scmcntora scbclum hunian tctap dapat ditcmpali kcmbali.
Untuk menjamin tersclcnggaranya pcnyaluran Dana Tunggu Hunian sccara ccpat, tcpal, cfcktif, dan akuntabel, scrta guna mcmbcrikan kcpaslian daJam pcrccpatan pcnanganan bantuan kepada masyarakat tcrdampak pada wilayah Provinsi Acch, Provinsi Sumatcra Barat, dan Provinsi Sumatcra Utara, dipcrlukan pcngaturan mckanismc pcloksanaan pcnyaluran Dana Tunggu Hunian yang bcrpcdoman pado. ketcntuan pcraturan perundang-undanga n.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (79, 'PENDAHULUAN A. Lalar Bclakang Tcrjadinya pcningkatan jumlah kcjadian bcncana di Indonesia disclfap tahunnya, dan scrangkaian bcncana yang mcnimbulkan kcrugian material dan korban j iwa dalam skala bcsar pada wilayah Provinsi Acch, Provinsi Sumatcra Barat, dan Provinsi Sumatcra Utara. Dampak yang dilimbulkan dari kcjadian bcncana bcrpengaruh tcrhadap kondisi sosial, ckonomi, dan kcscjahlcraan masyarakat, tcrmasuk tcrganggunya fungsi hunian scl;>agai kcbuluhan dasar bagi masyarakat lcrdampak.
Sebagai upaya dalam mcmbcrikan pcrlindungan dan pcmcnuhan kcbutuhan dasar masyarakal tcrdampak bcncana yang tclah lcrjadi pada wilayah Provinsi Aceh, Provinsi Sumalcra Baral, dan Provinsi Sumatcra Utara, Pemcrintah mclakukan pcrccpatan pcnanganan pcnanggulangan bcncana sccara scrius dan ccpat. Salah satu bcntuk dukungan pcrcepatan pcnanganan dalam pcnyclcnggaraan pcnanggulangan bencana yang dilaksanakan Pcmcrintah ya.itu pcmbcrian Bantuan Dana Tunggu Hunian scbagai fasililas pcndukung hunion scmcntora scbclum hunian tctap dapat ditcmpali kcmbali.
Untuk menjamin tersclcnggaranya pcnyaluran Dana Tunggu Hunian sccara ccpat, tcpal, cfcktif, dan akuntabel, scrta guna mcmbcrikan kcpaslian daJam pcrccpatan pcnanganan bantuan kepada masyarakat tcrdampak pada wilayah Provinsi Acch, Provinsi Sumatcra Barat, dan Provinsi Sumatcra Utara, dipcrlukan pcngaturan mckanismc pcloksanaan pcnyaluran Dana Tunggu Hunian yang bcrpcdoman pado. ketcntuan pcraturan perundang-undanga n.', 'BAB I', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian untuk Provinsi Aceh, Sumatera Utara dan Sumatera Barat Akibat Bencana Alam Nomor 15 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (80, 'juklak-15-2025', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Berdasarkan hal tcrscbut, maka perlu disusun Pctunjuk Pelaksanaan Penyaluran Dana Tunggu Hunian untuk \Vilayah Provinsi Aceh, Provinsi Sumalcra Baral, dan Provinsi Sumatcra Utara sebagai pcdoman bagi Sadan Nasional Pcnanggulangan Bcncana dan Pcmcrintah Dacrah dalam pcnyclcnggaraan pcnyaluran bantuan Dana Tunggu Hunian.
Petunjuk Pelaksanaan ini dimaksudkan sebagai pedoman bagi Badan Nasional Penanggulangan Bencana dan Pemerintah Daerah dalam percepatan pelaksanaan penyaluran Bantuan Dana Tunggu Hunian pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara.
2. Tujuan Petunjuk Pelaksanaan ini bertujuan untuk:
a. Mempercepat pelaksanaan penyaluran Dana Tunggu Hunian kepada masyarakat terdampak bencana;
b. Memberikan kepastian terhadap mekanisme pelaksanaan dan kepastian penerimaan bantuan bagi masyarakat terdampak bencana;
c. Memastikan pelaksanaan bantuan tetap akuntabel, efektif, dan sesuai ketentuan peraturan perundang-undangan;
d. Memperjelas pembagian peran dan tanggung jawab antara Badan Nasional Penanggulangan Bencana dan Pemerintah Daerah.
C. Pengertian Dalam Petunjuk Pelaksanaan ini yang dimaksud dengan:
1. Dana Tunggu Hunian, yang selanjutnya disingkat DTH adalah dana siap pakai yang diberikan kepada korban dan pengungsi akibat bencana yang digunakan untuk mencari tempat tinggal sementara pada saat menunggu hunian tetap/rumahnya selesai dibangun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (80, 'Berdasarkan hal tcrscbut, maka perlu disusun Pctunjuk Pelaksanaan Penyaluran Dana Tunggu Hunian untuk \Vilayah Provinsi Aceh, Provinsi Sumalcra Baral, dan Provinsi Sumatcra Utara sebagai pcdoman bagi Sadan Nasional Pcnanggulangan Bcncana dan Pcmcrintah Dacrah dalam pcnyclcnggaraan pcnyaluran bantuan Dana Tunggu Hunian.
Petunjuk Pelaksanaan ini dimaksudkan sebagai pedoman bagi Badan Nasional Penanggulangan Bencana dan Pemerintah Daerah dalam percepatan pelaksanaan penyaluran Bantuan Dana Tunggu Hunian pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara.
2. Tujuan Petunjuk Pelaksanaan ini bertujuan untuk:
a. Mempercepat pelaksanaan penyaluran Dana Tunggu Hunian kepada masyarakat terdampak bencana;
b. Memberikan kepastian terhadap mekanisme pelaksanaan dan kepastian penerimaan bantuan bagi masyarakat terdampak bencana;
c. Memastikan pelaksanaan bantuan tetap akuntabel, efektif, dan sesuai ketentuan peraturan perundang-undangan;
d. Memperjelas pembagian peran dan tanggung jawab antara Badan Nasional Penanggulangan Bencana dan Pemerintah Daerah.
C. Pengertian Dalam Petunjuk Pelaksanaan ini yang dimaksud dengan:
1. Dana Tunggu Hunian, yang selanjutnya disingkat DTH adalah dana siap pakai yang diberikan kepada korban dan pengungsi akibat bencana yang digunakan untuk mencari tempat tinggal sementara pada saat menunggu hunian tetap/rumahnya selesai dibangun.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian untuk Provinsi Aceh, Sumatera Utara dan Sumatera Barat Akibat Bencana Alam Nomor 15 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (81, 'juklak-15-2025', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, '2. Pemerintah daerah adalah gubernur, bupati/walikota, atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara.
3. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB, adalah lembaga pemerintah non-departemen sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (81, '2. Pemerintah daerah adalah gubernur, bupati/walikota, atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara.
3. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB, adalah lembaga pemerintah non-departemen sesuai dengan ketentuan peraturan perundang-undangan.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian untuk Provinsi Aceh, Sumatera Utara dan Sumatera Barat Akibat Bencana Alam Nomor 15 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (82, 'juklak-15-2025', 5, 'lain', 'BAB II', NULL, 3, 'PELAKSANAAN PENGELOLAAN A. Kebijakan Umum Penyaluran Pelaksanaan penyaluran DTH pada Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara merupakan bagian dari percepatan penanganan dampak bencana untuk memberikan kepastian bantuan bagi masyarakat terdampak. Penyaluran DTH berpedoman pada ketentuan peraturan perundang-undangan di bidang penanggulangan bencana, pendanaan bencana, pengelolaan Dana Siap Pakai, dan kebijakan yang ditetapkan oleh Kepala BNPB.
B. Kriteria Penerima Bantuan Bantuan DTH diberikan dengan kriteria sebagai berikut:
1. Merupakan masyarakat terdampak bencana pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara, sebagai berikut:
a. Korban dan pengungsi akibat bencana tidak mendapatkan fasilitas hunian sementara dari pemerintah/lembaga usaha/lembaga kemanusiaan /organisasi kemasyarakatan;
b. Korban dan pengungsi akibat bencana tidak mampu secara mandiri menyediakan tempat hunian sementara; dan
c. Termasuk dalam daftar hasil pendataan, verifikasi, dan validasi Pemerintah Daerah.
2. Kondisi rumah yang masuk dalam kategori rusak berat/hilang/hanyut sehingga tidak dapat ditempati dan/atau tidak layak huni akibat bencana. Rumah tidak layak huniyaitu:
a. Tidak memenuhi persyaratan keselamatan bangunan dan Kesehatan penghuni sesuai dengan ketentuan peraturan perundang-undangan,
b. Masuk dalam Kawasan rawan bencana (zona merah) sesuai dengan rekomendasi kementerian/lembaga terkait; atau');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (82, 'PELAKSANAAN PENGELOLAAN A. Kebijakan Umum Penyaluran Pelaksanaan penyaluran DTH pada Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara merupakan bagian dari percepatan penanganan dampak bencana untuk memberikan kepastian bantuan bagi masyarakat terdampak. Penyaluran DTH berpedoman pada ketentuan peraturan perundang-undangan di bidang penanggulangan bencana, pendanaan bencana, pengelolaan Dana Siap Pakai, dan kebijakan yang ditetapkan oleh Kepala BNPB.
B. Kriteria Penerima Bantuan Bantuan DTH diberikan dengan kriteria sebagai berikut:
1. Merupakan masyarakat terdampak bencana pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara, sebagai berikut:
a. Korban dan pengungsi akibat bencana tidak mendapatkan fasilitas hunian sementara dari pemerintah/lembaga usaha/lembaga kemanusiaan /organisasi kemasyarakatan;
b. Korban dan pengungsi akibat bencana tidak mampu secara mandiri menyediakan tempat hunian sementara; dan
c. Termasuk dalam daftar hasil pendataan, verifikasi, dan validasi Pemerintah Daerah.
2. Kondisi rumah yang masuk dalam kategori rusak berat/hilang/hanyut sehingga tidak dapat ditempati dan/atau tidak layak huni akibat bencana. Rumah tidak layak huniyaitu:
a. Tidak memenuhi persyaratan keselamatan bangunan dan Kesehatan penghuni sesuai dengan ketentuan peraturan perundang-undangan,
b. Masuk dalam Kawasan rawan bencana (zona merah) sesuai dengan rekomendasi kementerian/lembaga terkait; atau', 'BAB II', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian untuk Provinsi Aceh, Sumatera Utara dan Sumatera Barat Akibat Bencana Alam Nomor 15 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (83, 'juklak-15-2025', 6, 'lain', 'BAB II (lanjutan 1)', NULL, 3, 'c. Surat pernyataan tidak layak huni dari pemerintah daerah.
C. Standar Pemberian Bantuan DTH diberikan dengan standar sebagai berikut:
1. Diberikan per 1 (satu) Kepala Keluarga;
2. Bantuan DTH tidak diberikan kepada pihak penyewa bangunan yang terdampak bencana; dan
3. Ditetapkan dengan keputusan kepala daerah terdampak bencana dengan dilengkapi rincian daftar nama penerima bantuan berdasarkan alamat tempat tinggal sesuai dengan Format-1 Keputusan Kepala Daerah tentang Penerima Bantuan Dana Tunggu Hunian Bencana Pada Darurat Bencana.
D. Bentuk Bantuan
1. Bantuan yang diberikan berupa DTH yaitu bantuan dana yang diperuntukkan mendukung kebutuhan hunian sementara bagi masyarakat terdampak sampai dengan tersedianya hunian tetap.
2. Bantuan DTH diberikan dengan ketentuan sebagai berikut:
a. Selama status keadaan darurat bencana/status keadaan tertentu diberlakukan;
b. Dapat diberikan selama 3 (tiga) bulan dan/atau berdasarkan keputusan Kepala BNPB; dan
c. Besaran DTH yang diberikan dengan nilai sebesar Rp600.000,- (enam ratus ribu rupiah) per bulan.
3. Penyaluran DTH:
a. Penyaluran DTH disalurkan dari BNPB ke rekening buku Tabungan penerima sesuai Keputusan Kepala Daerah yang diajukan kepada BNPB.
b. Pemberian buku tabungan ke penerima DTH dilengkapi dengan:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (83, 'c. Surat pernyataan tidak layak huni dari pemerintah daerah.
C. Standar Pemberian Bantuan DTH diberikan dengan standar sebagai berikut:
1. Diberikan per 1 (satu) Kepala Keluarga;
2. Bantuan DTH tidak diberikan kepada pihak penyewa bangunan yang terdampak bencana; dan
3. Ditetapkan dengan keputusan kepala daerah terdampak bencana dengan dilengkapi rincian daftar nama penerima bantuan berdasarkan alamat tempat tinggal sesuai dengan Format-1 Keputusan Kepala Daerah tentang Penerima Bantuan Dana Tunggu Hunian Bencana Pada Darurat Bencana.
D. Bentuk Bantuan
1. Bantuan yang diberikan berupa DTH yaitu bantuan dana yang diperuntukkan mendukung kebutuhan hunian sementara bagi masyarakat terdampak sampai dengan tersedianya hunian tetap.
2. Bantuan DTH diberikan dengan ketentuan sebagai berikut:
a. Selama status keadaan darurat bencana/status keadaan tertentu diberlakukan;
b. Dapat diberikan selama 3 (tiga) bulan dan/atau berdasarkan keputusan Kepala BNPB; dan
c. Besaran DTH yang diberikan dengan nilai sebesar Rp600.000,- (enam ratus ribu rupiah) per bulan.
3. Penyaluran DTH:
a. Penyaluran DTH disalurkan dari BNPB ke rekening buku Tabungan penerima sesuai Keputusan Kepala Daerah yang diajukan kepada BNPB.
b. Pemberian buku tabungan ke penerima DTH dilengkapi dengan:', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian untuk Provinsi Aceh, Sumatera Utara dan Sumatera Barat Akibat Bencana Alam Nomor 15 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (84, 'juklak-15-2025', 7, 'lain', 'BAB II (lanjutan 2)', NULL, 4, '1) Surat Pernyataan Penerima Bantuan DTH bagi penerima yang memiliki bukti diri sesuai dengan Format-3 Surat Pernyataan Penerima Bantuan DTH; atau 2) Surat Tanda Terima DTH dari DSP BNPB bagi penerima yang tidak memiliki bukti diri sesuai dengan Format-4 Tanda Terima DTH dari DSP BNPB.
E. Penetapan Penerima Bantuan Pelaksanaan penetapan penerima DTH pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara dilaksanakan sebagai berikut:
1. Pemerintah Daerah Provinsi/Kabupaten/Kota melakukan pendataan, verifikasi, dan validasi terhadap masyarakat terdampak bencana yang memenuhi kriteria sebagai penerima DTH.
2. Hasil pendataan, verifikasi, dan validasi sebagaimana dimaksud pada angka 1 (satu) ditetapkan melalui Keputusan Kepala Daerah (Gubernur/Bupati/ Walikota).
3. Keputusan Kepala Daerah beserta lampiran daftar penerima merupakan daftar yang digunakan sebagai dasar pelaksanaan penyaluran Bantuan DTH oleh BNPB.
F. Mekanisme Pelaksanaan Pelaksanaan penyaluran Bantuan DTH pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara dilaksanakan melalui mekanisme sebagai berikut:
1. Pemerintah Daerah menyampaikan kepada BNPB, dengan melampirkan dokumen sebagai berikut:
a. Surat permohonan bantuan DTH dari Kepala Daerah yang disampaikan kepada Kepala BNPB;
b. Keputusan Kepala Daerah tentang Penetapan Penerima Bantuan DTH beserta lampiran daftar penerima;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (84, '1) Surat Pernyataan Penerima Bantuan DTH bagi penerima yang memiliki bukti diri sesuai dengan Format-3 Surat Pernyataan Penerima Bantuan DTH; atau 2) Surat Tanda Terima DTH dari DSP BNPB bagi penerima yang tidak memiliki bukti diri sesuai dengan Format-4 Tanda Terima DTH dari DSP BNPB.
E. Penetapan Penerima Bantuan Pelaksanaan penetapan penerima DTH pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara dilaksanakan sebagai berikut:
1. Pemerintah Daerah Provinsi/Kabupaten/Kota melakukan pendataan, verifikasi, dan validasi terhadap masyarakat terdampak bencana yang memenuhi kriteria sebagai penerima DTH.
2. Hasil pendataan, verifikasi, dan validasi sebagaimana dimaksud pada angka 1 (satu) ditetapkan melalui Keputusan Kepala Daerah (Gubernur/Bupati/ Walikota).
3. Keputusan Kepala Daerah beserta lampiran daftar penerima merupakan daftar yang digunakan sebagai dasar pelaksanaan penyaluran Bantuan DTH oleh BNPB.
F. Mekanisme Pelaksanaan Pelaksanaan penyaluran Bantuan DTH pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara dilaksanakan melalui mekanisme sebagai berikut:
1. Pemerintah Daerah menyampaikan kepada BNPB, dengan melampirkan dokumen sebagai berikut:
a. Surat permohonan bantuan DTH dari Kepala Daerah yang disampaikan kepada Kepala BNPB;
b. Keputusan Kepala Daerah tentang Penetapan Penerima Bantuan DTH beserta lampiran daftar penerima;', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian untuk Provinsi Aceh, Sumatera Utara dan Sumatera Barat Akibat Bencana Alam Nomor 15 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (85, 'juklak-15-2025', 8, 'lain', 'BAB II (lanjutan 3)', NULL, 4, 'c. Surat Pernyataan Tanggung Jawab Mutlak (SPTJM) yang merupakan surat pernyataan yang ditandatangani oleh Kepala Daerah sebagai bentuk pertanggungjawaban atas kebenaran data calon penerima Bantuan DTH. Format-2 Surat Pernyataan Tanggung Jawab Mutlak;
d. Kerangka Acuan Kerja (KAK) permohonan DTH;
e. Surat Keputusan Status Darurat Bencana dari Kepala Daerah;
f. Surat Keputusan Aktivasi Posko Darurat Bencana dari Kepala Daerah; dan
g. Surat Pernyataan Kejadian Bencana oleh Kepala Daerah.
2. Dalam rangka memastikan tertib tata kelola dan pengendalian internal, pelaksanaan penyaluran DTH dapat melibatkan Aparat Pengawasan Intern Pemerintah (APIP) pada tingkat pusat dan daerah dalam fungsi pengawasan internal dan pendampingan pelaksanaan.
3. Jika data penerima DTH diketahui meninggal dunia, bekerja di luar kota, atau kondisi yang tidak memungkinkan, maka DTH dapat diambil oleh ahli waris sah dengan ketentuan sebagai berikut:
a. Surat keterangan kematian, asli/copy (yang dilegalisir).
b. Asli/copy (yang dilegalisir) surat keterangan ahli waris sebagai berikut:
1) Surat keterangan ahli waris yang dibuat dan ditandatangani oleh seluruh ahli waris dengan diketahui Kepala Desa/Lurah dan Camat;
2) Surat keterangan ahli waris dibuat secara Notariil oleh Notaris;
3) Surat keterangan ahli waris dibuat oleh Balai Harta Peninggalan (BHP);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (85, 'c. Surat Pernyataan Tanggung Jawab Mutlak (SPTJM) yang merupakan surat pernyataan yang ditandatangani oleh Kepala Daerah sebagai bentuk pertanggungjawaban atas kebenaran data calon penerima Bantuan DTH. Format-2 Surat Pernyataan Tanggung Jawab Mutlak;
d. Kerangka Acuan Kerja (KAK) permohonan DTH;
e. Surat Keputusan Status Darurat Bencana dari Kepala Daerah;
f. Surat Keputusan Aktivasi Posko Darurat Bencana dari Kepala Daerah; dan
g. Surat Pernyataan Kejadian Bencana oleh Kepala Daerah.
2. Dalam rangka memastikan tertib tata kelola dan pengendalian internal, pelaksanaan penyaluran DTH dapat melibatkan Aparat Pengawasan Intern Pemerintah (APIP) pada tingkat pusat dan daerah dalam fungsi pengawasan internal dan pendampingan pelaksanaan.
3. Jika data penerima DTH diketahui meninggal dunia, bekerja di luar kota, atau kondisi yang tidak memungkinkan, maka DTH dapat diambil oleh ahli waris sah dengan ketentuan sebagai berikut:
a. Surat keterangan kematian, asli/copy (yang dilegalisir).
b. Asli/copy (yang dilegalisir) surat keterangan ahli waris sebagai berikut:
1) Surat keterangan ahli waris yang dibuat dan ditandatangani oleh seluruh ahli waris dengan diketahui Kepala Desa/Lurah dan Camat;
2) Surat keterangan ahli waris dibuat secara Notariil oleh Notaris;
3) Surat keterangan ahli waris dibuat oleh Balai Harta Peninggalan (BHP);', 'BAB II (lanjutan 3)', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian untuk Provinsi Aceh, Sumatera Utara dan Sumatera Barat Akibat Bencana Alam Nomor 15 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (86, 'juklak-15-2025', 9, 'lain', 'BAB II (lanjutan 4)', NULL, 5, '4) Penetapan ahli waris dibuat oleh Pengadilan Agama/Pengadilan Negeri; dan/atau 5) Putusan Pengadilan Agama/Pengadilan Negeri (dalam hal terjadi sengketa) yang berkekuatan hukum tetap.
c. Asli KTP ahli waris/Kartu Keluarga (untuk ahli waris yang belum cakap hukum) untuk di copy oleh petugas.
d. Surat Kuasa Asli.
e. Pendamping dari Pemerintah Daerah terkait dengan melibatkan BNPB untuk memverifikasi kebenaran dokumen.
f. Mengikuti aturan dan ketentuan dari bank penyalur DTH.
4. Penyaluran DTH dilaksanakan dengan prinsip cepat, tepat, efektif, efisien, transparan, dan akuntabel sesuai ketentuan peraturan perundang-undangan.
5. BNPB menggunakan Keputusan Kepala Daerah sebagaimana dimaksud pada angka 1 (satu) sebagai dasar dalam pelaksanaan penyaluran Bantuan DTH dengan tetap mengedepankan percepatan penanganan, kepastian bantuan bagi masyarakat terdampak.
6. Dalam hal setelah penetapan daftar penerima ditemukan ketidaksesuaian data, perubahan kondisi, atau koreksi yang diperlukan, Pemerintah Daerah dapat melakukan perbaikan melalui mekanisme verifikasi ulang dan menetapkannya dalam Perubahan Keputusan Kepala Daerah, disertai pembaruan dokumen pendukung, serta disampaikan kepada BNPB untuk penyesuaian administrasi pelaksanaan.
G. Pertanggungjawaban
1. Keterlibatan APIP dalam mekanisme pelaksanaan merupakan bagian dari penguatan fungsi pengawasan internal untuk memastikan pelaksanaan penyaluran DTH berjalan sesuai ketentuan dan akuntabel.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (86, '4) Penetapan ahli waris dibuat oleh Pengadilan Agama/Pengadilan Negeri; dan/atau 5) Putusan Pengadilan Agama/Pengadilan Negeri (dalam hal terjadi sengketa) yang berkekuatan hukum tetap.
c. Asli KTP ahli waris/Kartu Keluarga (untuk ahli waris yang belum cakap hukum) untuk di copy oleh petugas.
d. Surat Kuasa Asli.
e. Pendamping dari Pemerintah Daerah terkait dengan melibatkan BNPB untuk memverifikasi kebenaran dokumen.
f. Mengikuti aturan dan ketentuan dari bank penyalur DTH.
4. Penyaluran DTH dilaksanakan dengan prinsip cepat, tepat, efektif, efisien, transparan, dan akuntabel sesuai ketentuan peraturan perundang-undangan.
5. BNPB menggunakan Keputusan Kepala Daerah sebagaimana dimaksud pada angka 1 (satu) sebagai dasar dalam pelaksanaan penyaluran Bantuan DTH dengan tetap mengedepankan percepatan penanganan, kepastian bantuan bagi masyarakat terdampak.
6. Dalam hal setelah penetapan daftar penerima ditemukan ketidaksesuaian data, perubahan kondisi, atau koreksi yang diperlukan, Pemerintah Daerah dapat melakukan perbaikan melalui mekanisme verifikasi ulang dan menetapkannya dalam Perubahan Keputusan Kepala Daerah, disertai pembaruan dokumen pendukung, serta disampaikan kepada BNPB untuk penyesuaian administrasi pelaksanaan.
G. Pertanggungjawaban
1. Keterlibatan APIP dalam mekanisme pelaksanaan merupakan bagian dari penguatan fungsi pengawasan internal untuk memastikan pelaksanaan penyaluran DTH berjalan sesuai ketentuan dan akuntabel.', 'BAB II (lanjutan 4)', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian untuk Provinsi Aceh, Sumatera Utara dan Sumatera Barat Akibat Bencana Alam Nomor 15 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (87, 'juklak-15-2025', 10, 'lain', 'BAB II (lanjutan 5)', NULL, 6, '2. Pemerintah Daerah bertanggung jawab atas kebenaran data penerima bantuan, ketepatan sasaran, serta validitas daftar penerima yang ditetapkan.
3. BNPB bertanggung jawab atas ketepatan mekanisme penyaluran serta tertib administrasi pertanggungjawaban tingkat pusat sesuai ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (87, '2. Pemerintah Daerah bertanggung jawab atas kebenaran data penerima bantuan, ketepatan sasaran, serta validitas daftar penerima yang ditetapkan.
3. BNPB bertanggung jawab atas ketepatan mekanisme penyaluran serta tertib administrasi pertanggungjawaban tingkat pusat sesuai ketentuan peraturan perundang-undangan.', 'BAB II (lanjutan 5)', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian untuk Provinsi Aceh, Sumatera Utara dan Sumatera Barat Akibat Bencana Alam Nomor 15 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (88, 'juklak-15-2025', 11, 'lain', 'BAB III', NULL, 7, 'MONITORING, EVALUASI, DAN PELAPORAN A. Monitoring Monitoring pelaksanaan penyaluran Bantuan DTH pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara dilaksanakan secara berkala dan/atau sewaktu-waktu apabila diperlukan dengan tetap mengedepankan prinsip koordinasi, efektivitas, serta mendukung percepatan pemenuhan hak masyarakat terdampak untuk memastikan bahwa pelaksanaan bantuan berjalan sesuai dengan tujuan, mekanisme, dan ketentuan yang berlaku.
B. Evaluasi Evaluasi pelaksanaan Bantuan DTH dilakukan untuk menilai:
1. Pelaksanaan Bantuan DTH pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara;
2. Ketepatan sasaran penerima bantuan sesuai Keputusan Kepala Daerah;
3. Kendala, hambatan, serta faktor yang mempengaruhi kelancaran pelaksanaan penyaluran bantuan; dan
4. Kesesuaian pelaksanaan dengan ketentuan peraturan perundang-undangan.
Evaluasi dilaksanakan oleh BNPB bersama Pemerintah Daerah secara terkoordinasi sebagai dasar pengambilan langkah perbaikan kebijakan apabila diperlukan serta memastikan pelaksanaan program tetap mendukung percepatan penanganan bencana dan pemberian kepastian bantuan kepada masyarakat terdampak.
C. Pelaporan Pemerintah Daerah menyampaikan laporan pelaksanaan kegiatan kepada Deputi Penanganan Darurat, laporan pelaksanaan kegiatan memuat dokumen paling sedikit:
1. Data penerima manfaat sesuai Keputusan Kepala Daerah;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (88, 'MONITORING, EVALUASI, DAN PELAPORAN A. Monitoring Monitoring pelaksanaan penyaluran Bantuan DTH pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara dilaksanakan secara berkala dan/atau sewaktu-waktu apabila diperlukan dengan tetap mengedepankan prinsip koordinasi, efektivitas, serta mendukung percepatan pemenuhan hak masyarakat terdampak untuk memastikan bahwa pelaksanaan bantuan berjalan sesuai dengan tujuan, mekanisme, dan ketentuan yang berlaku.
B. Evaluasi Evaluasi pelaksanaan Bantuan DTH dilakukan untuk menilai:
1. Pelaksanaan Bantuan DTH pada wilayah Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara;
2. Ketepatan sasaran penerima bantuan sesuai Keputusan Kepala Daerah;
3. Kendala, hambatan, serta faktor yang mempengaruhi kelancaran pelaksanaan penyaluran bantuan; dan
4. Kesesuaian pelaksanaan dengan ketentuan peraturan perundang-undangan.
Evaluasi dilaksanakan oleh BNPB bersama Pemerintah Daerah secara terkoordinasi sebagai dasar pengambilan langkah perbaikan kebijakan apabila diperlukan serta memastikan pelaksanaan program tetap mendukung percepatan penanganan bencana dan pemberian kepastian bantuan kepada masyarakat terdampak.
C. Pelaporan Pemerintah Daerah menyampaikan laporan pelaksanaan kegiatan kepada Deputi Penanganan Darurat, laporan pelaksanaan kegiatan memuat dokumen paling sedikit:
1. Data penerima manfaat sesuai Keputusan Kepala Daerah;', 'BAB III', 'Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian untuk Provinsi Aceh, Sumatera Utara dan Sumatera Barat Akibat Bencana Alam Nomor 15 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (89, 'juklak-15-2025', 12, 'lain', 'BAB III (lanjutan 1)', NULL, 7, '2. Perkembangan pelaksanaan penyaluran bantuan; dan Deputi Penanganan Darurat menyampaikan pelaporan terkait penyaluran DTH kepada Kepala BNPB, memuat dokumen paling sedikit:
