INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (90, 'juklak-15-2025', 13, 'lain', 'BAB IV', NULL, 8, 'PENUTUP Pctunjuk Pclaksanaan Penyaluran Bantuan DTH ini disusun sebagai pcdoman bagi BNPB dan Pcmcrintah Daerah dalam rangka pelaksanaan pcnyaluran 0TH di ,vilayah Provinsi Aceh, Provinsi Sumatera Baral, dan Provinsi Sumatcra Utara.
Mclalui Petunjuk Pclaksanaan ini diharapkan seluruh proses pelaksanaan penyaJuran 0TH dapat berlangsung lebih sederhana, terarah, terkoordinasi, dan berjalan sesuai kelentuan, sehingga mendukung percepatan penanganan dampak bencana khususnya terkait pemenuhan kebutuhan hunian sementara bagi masyarakal terdampak di Provinsi Aceh, Provinsi Sumatera Barat, dan Provinsi Sumatera Utara.
HaJ-hal yang belum diatur dalam Petunjuk Pelaksanaan ini akan diatur kemudian sesuai ketentuan peraturan pcrundang-undangan serta berdasarkan kebutuhan pelaksanaan penanganan bencana di lapangan.
Ditetapkan di Jakarta Pada tanggal 15 Dcsember 2025 KEPALA SADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya SADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hu , Organisasi, dan Kerja Sama R,l/u"'')i,.l''Q ismayati v-------,,');
