INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (91, 'juklak-15-2025', 14, 'lampiran', 'LAMPIRAN', NULL, 9, 'PETUNJUK PELAKSANAAN TENTANG BANTUAN DANA TUNGGU HUNIAN UNTUK PROVINSI ACEH, SUMATERA UTARA DAN SUMATERA BARAT AKIBAT BENCANA ALAM NOMOR TAHUN 2026 Format-1 Keputusan Kepala Daerah tentang Penerima Bantuan Dana Tunggu Hunian Bencana Pada Darurat Bencana KEPALA DAERAH….
KEPUTUSAN KEPALA DAERAH NOMOR …… TAHUN …… TENTANG PENERIMA BANTUAN DANA TUNGGU HUNIAN BENCANA PADA DARURAT BENCANA DI …… KEPALA DAERAH (GUBERNUR/BUPATI/WALIKOTA ……) Menimbang : a. bahwa dalam rangka penyediaan penampungan serta tempat hunian sementara bagi korban dan pengungsi akibat bencana yang tempat tinggalnya tidak dapat dihuni, diperlukan bantuan dari pemerintah;
b. bahwa salah satu bentuk pemberian bantuan penyediaan penampungan serta tempat hunian sementara sebagaimana dimaksud dalam huruf a berupa Dana Tunggu Hunian;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b perlu menetapkan Keputusan Gubernur/Bupati/Walikota …… tentang Penerima Bantuan Dana Tunggu Hunian;
Mengingat : 1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);');
