INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (106, 'juklak-16-2025', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (106, 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025', 'Judul', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (107, 'juklak-16-2025', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PENYELENGGARAAN KLASTER LOGISTIK PENANGGULANGAN BENCANA NOMOR 16 TAHUN 2025');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (107, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PENYELENGGARAAN KLASTER LOGISTIK PENANGGULANGAN BENCANA NOMOR 16 TAHUN 2025', 'Isi hal. 1', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (108, 'juklak-16-2025', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Badan Nasional Penanggulangan Bencana telah menetapkan Peraturan Badan Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana, berdasarkan peraturan badan ini yang menjadi landasan pokok pikiran adalah penyelenggaraan manajemen logistik penanggulangan bencana yang efektif dan efisien melalui mekanisme klaster logistik dengan pelibatan multi pihak, sejalan dengan pelaksanaan tersebut, Badan Nasional Penanggulangan Bencana juga telah menetapkan Surat Keputusan Nomor 308 Tahun 2024 tentang Klaster Penanggulangan Bencana, melalui Surat Keputusan ini ditetapkan 6 (enam) klaster penanggulangan bencana, sebagai berikut:
1. Klaster Pencarian dan Pertolongan dengan koordinator Badan Nasional Pencarian dan Pertolongan,
2. Klaster Pengungsian dan Perlindungan dengan koordinator Kementerian Sosial,
3. Klaster Logistik dengan koordinator Badan Nasional Penanggulangan Bencana,
4. Klaster Kesehatan dengan koordinator Kementerian Kesehatan,
5. Klaster Pendidikan dengan koordinator Kementerian Pendidikan dan Kebudayaan, dan
6. Klaster Pemulihan dengan koordinator Kementerian Dalam Negeri.
Salah satu tujuan penyelenggaraan klaster logistik penanggulangan bencana adalah untuk memastikan pelaksanaan koordinasi antara instansi pemerintah, lembaga usaha, dan masyarakat serta meningkatkan respon penanggulangan bencana khusunya pada bidang logistik saat pra bencana, darurat bencana, dan pasca bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (108, 'PENDAHULUAN A. Latar Belakang Badan Nasional Penanggulangan Bencana telah menetapkan Peraturan Badan Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana, berdasarkan peraturan badan ini yang menjadi landasan pokok pikiran adalah penyelenggaraan manajemen logistik penanggulangan bencana yang efektif dan efisien melalui mekanisme klaster logistik dengan pelibatan multi pihak, sejalan dengan pelaksanaan tersebut, Badan Nasional Penanggulangan Bencana juga telah menetapkan Surat Keputusan Nomor 308 Tahun 2024 tentang Klaster Penanggulangan Bencana, melalui Surat Keputusan ini ditetapkan 6 (enam) klaster penanggulangan bencana, sebagai berikut:
1. Klaster Pencarian dan Pertolongan dengan koordinator Badan Nasional Pencarian dan Pertolongan,
2. Klaster Pengungsian dan Perlindungan dengan koordinator Kementerian Sosial,
3. Klaster Logistik dengan koordinator Badan Nasional Penanggulangan Bencana,
4. Klaster Kesehatan dengan koordinator Kementerian Kesehatan,
5. Klaster Pendidikan dengan koordinator Kementerian Pendidikan dan Kebudayaan, dan
6. Klaster Pemulihan dengan koordinator Kementerian Dalam Negeri.
Salah satu tujuan penyelenggaraan klaster logistik penanggulangan bencana adalah untuk memastikan pelaksanaan koordinasi antara instansi pemerintah, lembaga usaha, dan masyarakat serta meningkatkan respon penanggulangan bencana khusunya pada bidang logistik saat pra bencana, darurat bencana, dan pasca bencana.', 'BAB I', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (109, 'juklak-16-2025', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Mempertimbangkan hal tersebut diatas, maka perlu disusun Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana.
2 B. Maksud dan Tujuan
1. Maksud petunjuk pelaksanaan ini adalah memberikan panduan dan tata laksana bagi pihak-pihak yang terlibat dalam penyelenggaraan klaster logistik penanggulangan bencana.
2. Tujuan dari petunjuk pelaksanaan ini adalah:
a. Tersedianya panduan penyelenggaraan klaster logistik penanggulangan bencana;
b. Meningkatkan kolaborasi instansi pemerintah, lembaga usaha, dan masyarakat dalam penyelenggaraan klaster logistik penanggulangan bencana; dan
c. Penyelenggaraan klaster logistik penanggulangan bencana dapat dilaksanakan secara terpadu, efektif dan akuntabel.
C. Ruang Lingkup Ruang lingkup Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana meliputi:
1. Pengorganisasian Klaster Logistik;
2. Penyelenggaraan Klaster Logistik;
3. Pelaporan.
D. Pengertian Umum
1. Klaster Logistik adalah merupakan wadah sekumpulan organisasi yang terdiri atas Instansi Pemerintah, Lembaga Usaha dan Masyarakat, dan yang bekerja bersama-sama untuk meningkatkan respon penanggulangan bencana pada bidang logistik dan bersifat sukarela.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (109, 'Mempertimbangkan hal tersebut diatas, maka perlu disusun Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana.
2 B. Maksud dan Tujuan
1. Maksud petunjuk pelaksanaan ini adalah memberikan panduan dan tata laksana bagi pihak-pihak yang terlibat dalam penyelenggaraan klaster logistik penanggulangan bencana.
2. Tujuan dari petunjuk pelaksanaan ini adalah:
a. Tersedianya panduan penyelenggaraan klaster logistik penanggulangan bencana;
b. Meningkatkan kolaborasi instansi pemerintah, lembaga usaha, dan masyarakat dalam penyelenggaraan klaster logistik penanggulangan bencana; dan
c. Penyelenggaraan klaster logistik penanggulangan bencana dapat dilaksanakan secara terpadu, efektif dan akuntabel.
C. Ruang Lingkup Ruang lingkup Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana meliputi:
1. Pengorganisasian Klaster Logistik;
2. Penyelenggaraan Klaster Logistik;
3. Pelaporan.
D. Pengertian Umum
1. Klaster Logistik adalah merupakan wadah sekumpulan organisasi yang terdiri atas Instansi Pemerintah, Lembaga Usaha dan Masyarakat, dan yang bekerja bersama-sama untuk meningkatkan respon penanggulangan bencana pada bidang logistik dan bersifat sukarela.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (110, 'juklak-16-2025', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, '2. Pos Komando Penanganan Darurat Bencana yang selanjutnya disebut Posko PDB adalah institusi yang berfungsi sebagai pusat komando operasi penanganan darurat bencana yang merupakan posko utama di dalam Sistem Komando Penanganan Darurat Bencana, untuk mengoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan penanganan darurat bencana.
3. Sistem Komando Penanganan Darurat Bencana yang selanjutnya disingkat SKPDB adalah satu kesatuan upaya terstruktur dalam satu komando yang digunakan untuk mengintegrasikan kegiatan penanganan darurat secara efektif dan efisien dalam mengendalikan ancaman/penyebab bencana dan menanggulangi dampak pada saat keadaan darurat bencana.
4. Organisasi Perangkat Daerah yang selanjutnya disingkat OPD adalah organisasi pembantu Kepala Daerah dan Dewan Perwakilan Rakyat Daerah dalam penyelenggaraan urusan Pemerintahan yang menjadi kewenangan Daerah.
5. Masyarakat adalah perseorangan, kelompok orang dan/atau badan hukum.
6. Lembaga Usaha adalah setiap badan hukum yang dapat berbentuk Badan Usaha Milik Negara, Badan Usaha Milik Daerah, koperasi, atau swasta yang didirikan sesuai dengan ketentuan peraturan perundang-undangan yang menjalankan jenis usaha tetap dan terus-menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (110, '2. Pos Komando Penanganan Darurat Bencana yang selanjutnya disebut Posko PDB adalah institusi yang berfungsi sebagai pusat komando operasi penanganan darurat bencana yang merupakan posko utama di dalam Sistem Komando Penanganan Darurat Bencana, untuk mengoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan penanganan darurat bencana.
3. Sistem Komando Penanganan Darurat Bencana yang selanjutnya disingkat SKPDB adalah satu kesatuan upaya terstruktur dalam satu komando yang digunakan untuk mengintegrasikan kegiatan penanganan darurat secara efektif dan efisien dalam mengendalikan ancaman/penyebab bencana dan menanggulangi dampak pada saat keadaan darurat bencana.
4. Organisasi Perangkat Daerah yang selanjutnya disingkat OPD adalah organisasi pembantu Kepala Daerah dan Dewan Perwakilan Rakyat Daerah dalam penyelenggaraan urusan Pemerintahan yang menjadi kewenangan Daerah.
5. Masyarakat adalah perseorangan, kelompok orang dan/atau badan hukum.
6. Lembaga Usaha adalah setiap badan hukum yang dapat berbentuk Badan Usaha Milik Negara, Badan Usaha Milik Daerah, koperasi, atau swasta yang didirikan sesuai dengan ketentuan peraturan perundang-undangan yang menjalankan jenis usaha tetap dan terus-menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (111, 'juklak-16-2025', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, '7. TNI adalah Tentara Nasional Indonesia komponen utama sistem pertahanan negara yang memiliki tugas pokok menegakkan 3 kedaulatan negara, mempertahankan keutuhan wilayah NKRI, dan melindungi segenap bangsa dari ancaman
8. Kepolisian Negara Republik Indonesia yang selanjutnya disebut Polri adalah alat negara yang berperan dalam memelihara keamanan dan ketertiban masyarakat, menegakkan hukum, serta memberikan perlindungan, pengayoman dan pelayanan kepada masyarakat dalam rangka terpeliharanya keamanan dalam negeri.
9. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah Lembaga Pemerintah Non Kementerian yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan.
10. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah Badan Pemerintah Daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
11. Pemerintah Pusat yang selanjutnya disebut Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
12. Pemerintah Daerah adalah Gubernur, Bupati/Walikota, atau perangkat daerah sebagai unsur penyelenggara Pemerintahan Daerah.
4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (111, '7. TNI adalah Tentara Nasional Indonesia komponen utama sistem pertahanan negara yang memiliki tugas pokok menegakkan 3 kedaulatan negara, mempertahankan keutuhan wilayah NKRI, dan melindungi segenap bangsa dari ancaman
8. Kepolisian Negara Republik Indonesia yang selanjutnya disebut Polri adalah alat negara yang berperan dalam memelihara keamanan dan ketertiban masyarakat, menegakkan hukum, serta memberikan perlindungan, pengayoman dan pelayanan kepada masyarakat dalam rangka terpeliharanya keamanan dalam negeri.
9. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah Lembaga Pemerintah Non Kementerian yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan.
10. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah Badan Pemerintah Daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
11. Pemerintah Pusat yang selanjutnya disebut Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
12. Pemerintah Daerah adalah Gubernur, Bupati/Walikota, atau perangkat daerah sebagai unsur penyelenggara Pemerintahan Daerah.
4', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (112, 'juklak-16-2025', 6, 'lain', 'BAB II', NULL, 4, 'PENGORGANISASIAN KLASTER LOGISTIK Pengorganisasian Klaster Logistik memiliki peran penting dalam meningkatkan koordinasi antar pemangku kepentingan, memperlancar arus barang dan jasa, serta mendukung ketahanan ekonomi nasional maupun daerah, selanjutnya pengorganisasian Klaster Logistik juga memperkuat sistem logistik nasional dan daerah yang efisien, terintegrasi, dan berdaya saing sehingga diperlukan pengorganisasian Klaster Logistik yang terdiri dari Klaster Logistik Nasional dan Klaster Logistik Daerah.
A. Klaster Logistik Nasional
1. Struktur Organisasi Klaster Logistik Nasional (gambar 1): struktur organisasi Klaster Logistik nasional Klaster Logistik Nasional dijalankan dengan elemen koordinasi sebagai berikut:
a. Koordinator dijabat oleh pihak/ lembaga yang memiliki tugas dan tanggungjawab dalam bidang logistik dan peralatan penanggulangan bencana yaitu Deputi Bidang Logistik dan Peralatan.
b. Wakil Koordinator dapat dijabat oleh pihak/lembaga dan/atau unsur nonpemerintah lainnya yang mendukung dalam penanggulangan bencana di bidang logistik.
c. Sekretariat berasal dari unit eselon 2 (dua) di lingkungan BNPB yang memiliki tugas fungsi dibidang kemitraan logistik dan peralatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (112, 'PENGORGANISASIAN KLASTER LOGISTIK Pengorganisasian Klaster Logistik memiliki peran penting dalam meningkatkan koordinasi antar pemangku kepentingan, memperlancar arus barang dan jasa, serta mendukung ketahanan ekonomi nasional maupun daerah, selanjutnya pengorganisasian Klaster Logistik juga memperkuat sistem logistik nasional dan daerah yang efisien, terintegrasi, dan berdaya saing sehingga diperlukan pengorganisasian Klaster Logistik yang terdiri dari Klaster Logistik Nasional dan Klaster Logistik Daerah.
A. Klaster Logistik Nasional
1. Struktur Organisasi Klaster Logistik Nasional (gambar 1): struktur organisasi Klaster Logistik nasional Klaster Logistik Nasional dijalankan dengan elemen koordinasi sebagai berikut:
a. Koordinator dijabat oleh pihak/ lembaga yang memiliki tugas dan tanggungjawab dalam bidang logistik dan peralatan penanggulangan bencana yaitu Deputi Bidang Logistik dan Peralatan.
b. Wakil Koordinator dapat dijabat oleh pihak/lembaga dan/atau unsur nonpemerintah lainnya yang mendukung dalam penanggulangan bencana di bidang logistik.
c. Sekretariat berasal dari unit eselon 2 (dua) di lingkungan BNPB yang memiliki tugas fungsi dibidang kemitraan logistik dan peralatan.', 'BAB II', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (113, 'juklak-16-2025', 7, 'lain', 'BAB II (lanjutan 1)', NULL, 4, 'd. Kepala Bidang Perencanaan dan Pemenuhan Kebutuhan dapat dijabat oleh unsur yang berasal dari BNPB, kementerian/lembaga, lembaga nonpemerintah, lembaga usaha, dan/atau organisasi kemasyarakatan lainnya yang memiliki kapasitas serta kompetensi dibidang perencanaan dan pemenuhan kebutuhan dalam mendukung penanggulangan bencana.
5
e. Kepala Bidang Penyimpanan dapat dijabat oleh unsur yang berasal dari BNPB, kementerian/lembaga, lembaga nonpemerintah, lembaga usaha dan/atau organisasi kemasyarakatan lainnya yang memiliki kapasitas serta kompetensi dibidang penyimpanan dalam mendukung penanggulangan bencana.
f. Kepala Bidang Pendistribusian dapat dijabat oleh unsur yang berasal dari BNPB, kementerian/lembaga, lembaga nonpemerintah, lembaga usaha, dan/atau organisasi kemasyarakatan lainnya yang memiliki kapasitas serta kompetensi dibidang pendistribusian dalam mendukung penanggulangan bencana.
g. Keanggotaan Klaster Logistik didasarkan atas kapasitas dan kompetensi yang dimiliki oleh masing-masing organisasi yang dapat mencakup 4 (empat) hal terdiri dari:
1) penyediaan/penyiapan sumber daya logistik dan peralatan;
2) penyediaan sarana transportasi/angkutan;
3) penyediaan fasilitas penyimpanan/pergudangan; dan 4) penyediaan personil tenaga kerja bongkar muat dan Keamanan.
Keanggotaan klaster berasal dari:
a. Kementrian/lembaga, TNI, dan Polri yang mendukung dalam penanggulangan bencana di bidang logistik.
b. Unsur Lembaga nonpemerintah, lembaga usaha dan organisasi kemasyarakatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (113, 'd. Kepala Bidang Perencanaan dan Pemenuhan Kebutuhan dapat dijabat oleh unsur yang berasal dari BNPB, kementerian/lembaga, lembaga nonpemerintah, lembaga usaha, dan/atau organisasi kemasyarakatan lainnya yang memiliki kapasitas serta kompetensi dibidang perencanaan dan pemenuhan kebutuhan dalam mendukung penanggulangan bencana.
5
e. Kepala Bidang Penyimpanan dapat dijabat oleh unsur yang berasal dari BNPB, kementerian/lembaga, lembaga nonpemerintah, lembaga usaha dan/atau organisasi kemasyarakatan lainnya yang memiliki kapasitas serta kompetensi dibidang penyimpanan dalam mendukung penanggulangan bencana.
f. Kepala Bidang Pendistribusian dapat dijabat oleh unsur yang berasal dari BNPB, kementerian/lembaga, lembaga nonpemerintah, lembaga usaha, dan/atau organisasi kemasyarakatan lainnya yang memiliki kapasitas serta kompetensi dibidang pendistribusian dalam mendukung penanggulangan bencana.
g. Keanggotaan Klaster Logistik didasarkan atas kapasitas dan kompetensi yang dimiliki oleh masing-masing organisasi yang dapat mencakup 4 (empat) hal terdiri dari:
1) penyediaan/penyiapan sumber daya logistik dan peralatan;
2) penyediaan sarana transportasi/angkutan;
3) penyediaan fasilitas penyimpanan/pergudangan; dan 4) penyediaan personil tenaga kerja bongkar muat dan Keamanan.
Keanggotaan klaster berasal dari:
a. Kementrian/lembaga, TNI, dan Polri yang mendukung dalam penanggulangan bencana di bidang logistik.
b. Unsur Lembaga nonpemerintah, lembaga usaha dan organisasi kemasyarakatan.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (114, 'juklak-16-2025', 8, 'lain', 'BAB II (lanjutan 2)', NULL, 5, '2. Tugas dan Tanggung Jawab Tugas dan tanggung jawab merupakan langkah awal dalam rangka optimalisasi pelaksanaan Klaster Logistik Nasional, selanjutnya tugas dan tanggung jawab juga menciptakan struktur yang jelas dalam mencapai tujuan organisasi Klaster Logistik Nasional.
Berikut tugas dan tanggung jawab Klaster Logistik Nasional:
a. Koordinator memiliki tugas dan tanggung jawab mengkoordinasikan pelaksanaan tugas sekretariat dan bidang-bidang pada Klaster Logistik Nasional penanggulangan bencana.
b. Wakil Koordinator memiliki tugas dan tanggung jawab membantu pelaksanaan tugas dan fungsi Koordinator Klaster Logistik Nasional penanggulangan bencana.
c. Sekretaris memiliki tugas pelaksanaan admnistrasi persuratan dan administrasi keuangan, dalam meenajalankan tugasnya Sekretaris bertanggung jawab langsung kepada koordinator Klaster Logistik Nasional penanggulangan bencana.
d. Kepala Bidang Perencanaan dan Pemenuhan Kebutuhan bertugas dan bertanggung jawab langsung kepada koordinator Klaster Logistik Nasional penanggulangan bencana.
e. Kepala Bidang Penyimpanan bertugas memimpin dan mengkoordinasikan pelaksanaan tugas teknis atau operasional bidang penyimpanan, dalam melaksanakan tugasnya Kepala Bidang Penyimpanan bertanggung jawab langsung kepada koordinator Klaster Logistik Nasional penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (114, '2. Tugas dan Tanggung Jawab Tugas dan tanggung jawab merupakan langkah awal dalam rangka optimalisasi pelaksanaan Klaster Logistik Nasional, selanjutnya tugas dan tanggung jawab juga menciptakan struktur yang jelas dalam mencapai tujuan organisasi Klaster Logistik Nasional.
Berikut tugas dan tanggung jawab Klaster Logistik Nasional:
a. Koordinator memiliki tugas dan tanggung jawab mengkoordinasikan pelaksanaan tugas sekretariat dan bidang-bidang pada Klaster Logistik Nasional penanggulangan bencana.
b. Wakil Koordinator memiliki tugas dan tanggung jawab membantu pelaksanaan tugas dan fungsi Koordinator Klaster Logistik Nasional penanggulangan bencana.
c. Sekretaris memiliki tugas pelaksanaan admnistrasi persuratan dan administrasi keuangan, dalam meenajalankan tugasnya Sekretaris bertanggung jawab langsung kepada koordinator Klaster Logistik Nasional penanggulangan bencana.
d. Kepala Bidang Perencanaan dan Pemenuhan Kebutuhan bertugas dan bertanggung jawab langsung kepada koordinator Klaster Logistik Nasional penanggulangan bencana.
e. Kepala Bidang Penyimpanan bertugas memimpin dan mengkoordinasikan pelaksanaan tugas teknis atau operasional bidang penyimpanan, dalam melaksanakan tugasnya Kepala Bidang Penyimpanan bertanggung jawab langsung kepada koordinator Klaster Logistik Nasional penanggulangan bencana.', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (115, 'juklak-16-2025', 9, 'lain', 'BAB II (lanjutan 3)', NULL, 5, 'f. Kepala Bidang Pendistribusian bertugas memimpin dan mengkoordinasikan pelaksanaan tugas teknis atau operasional bidang pendistribusian, dalam melaksanakan tugasnya Kepala 6 bidang pendistribusian bertanggung jawab langsung kepada koordinator Klaster Logistik Nasional penanggulangan bencana.
B. Klaster Logistik Daerah
1. Struktur Organisasi Klaster Logistik Daerah Klaster Logistik Daerah dibentuk oleh Pemerintah Daerah sesuai kewenangannya serta dalam pembentukannya struktur organisasi dapat disesuaikan dengan kebutuhan.
(gambar 2): Struktur Organisasi Klaster Logistik Daerah Klaster Logistik Daerah dijalankan dengan elemen koordinasi sebagai berikut:
a. Pengarah dijabat oleh Kepala Daerah yang memiliki tugas dan fungsi dalam penyelenggaraan penanggulangan bencana di wilayahnya.
b. Koordinator dijabat oleh Kepala Pelaksana BPBD yang merupakan pejabat yang memiliki tugas dan tanggungjawab dalam pelaksanaan penanggulangan bencana daerah.
c. Wakil Koordinator dapat dijabat oleh pihak/lembaga dan unsur nonpemerintah lainnya yang mendukung dalam penanggulangan bencana di bidang logistik.
d. Sekretariat dapat dijabat oleh pihak/lembaga yang memiliki tugas dan tanggungjawab pada pengadministrasian dan pengelolaan informasi dalam penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (115, 'f. Kepala Bidang Pendistribusian bertugas memimpin dan mengkoordinasikan pelaksanaan tugas teknis atau operasional bidang pendistribusian, dalam melaksanakan tugasnya Kepala 6 bidang pendistribusian bertanggung jawab langsung kepada koordinator Klaster Logistik Nasional penanggulangan bencana.
B. Klaster Logistik Daerah
1. Struktur Organisasi Klaster Logistik Daerah Klaster Logistik Daerah dibentuk oleh Pemerintah Daerah sesuai kewenangannya serta dalam pembentukannya struktur organisasi dapat disesuaikan dengan kebutuhan.
(gambar 2): Struktur Organisasi Klaster Logistik Daerah Klaster Logistik Daerah dijalankan dengan elemen koordinasi sebagai berikut:
a. Pengarah dijabat oleh Kepala Daerah yang memiliki tugas dan fungsi dalam penyelenggaraan penanggulangan bencana di wilayahnya.
b. Koordinator dijabat oleh Kepala Pelaksana BPBD yang merupakan pejabat yang memiliki tugas dan tanggungjawab dalam pelaksanaan penanggulangan bencana daerah.
c. Wakil Koordinator dapat dijabat oleh pihak/lembaga dan unsur nonpemerintah lainnya yang mendukung dalam penanggulangan bencana di bidang logistik.
d. Sekretariat dapat dijabat oleh pihak/lembaga yang memiliki tugas dan tanggungjawab pada pengadministrasian dan pengelolaan informasi dalam penanggulangan bencana.', 'BAB II (lanjutan 3)', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (116, 'juklak-16-2025', 10, 'lain', 'BAB II (lanjutan 4)', NULL, 6, 'e. Kepala Bidang Perencanaan dan Pemenuhan Kebutuhan dapat dijabat oleh unsur yang berasal dari BPBD, OPD atau lembaga nonpemerintah, lembaga usaha dan/atau organisasi kemasyarakatan lainnya yang memiliki kapasitas dan kompetensi dibidang perencanaan dan pemenuhan kebutuhan dalam mendukung penanggulangan bencana.
f. Kepala Bidang Penyimpanan dapat dijabat oleh OPD, instansi vertikal di daerah, TNI, Polri atau lembaga nonpemerintah, lembaga usaha dan/atau organisasi kemasyarakatan lainnya 7 yang memiliki kapasitas dan kompetensi dibidang penyimpanan dalam mendukung penanggulangan bencana.
g. Kepala Bidang Pendistribusian dapat dijabat oleh OPD, instansi vertikal di daerah, TNI, Polri atau lembaga nonpemerintah, lembaga usaha dan/atau organisasi kemasyarakatan lainnya yang memiliki kapasitas dan kompetensi dibidang pendistribusian dalam mendukung penanggulangan bencana.
h. Keanggotaan Klaster Logistik Daerah didasarkan atas kapasitas dan kompetensi yang dimiliki oleh masing-masing organisasi yang dapat mencakup 4 (empat) hal terdiri dari:
1) penyediaan/penyiapan sumber daya logistik dan peralatan;
2) penyediaan sarana transportasi/angkutan;
3) penyediaan fasilitas penyimpanan/pergudangan; dan 4) penyediaan personil tenaga kerja bongkar muat dan Keamanan.
Anggota Klaster Logistik Daerah dapat berasal dari:
a. OPD, instansi vertikal di daerah, TNI dan POLRI yang mendukung dalam penanggulangan bencana di bidang logistik; dan');
