INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (118, 'juklak-16-2025', 12, 'lain', 'BAB II (lanjutan 6)', NULL, 7, '1) Sub Bidang Perencanaan Kebutuhan bertugas dan bertanggung jawab dalam urusan Perencanaan Kebutuhan.
