INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (135, 'juklak-16-2025', 29, 'lain', 'BAB VII', NULL, 16, 'PENUTUP Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana digunakan sebagai acuan dalam penyelenggaraan Klaster Logistik.
Untuk implementasi yang baik diperlukan komitmen dan peran serta para pihak yang terlibat.
