INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (136, 'juklak-16-2025', 30, 'lampiran', 'LAMPIRAN', NULL, 17, 'PETUNJUK PELAKSANAAN PENYELENGGARAAN KLASTER LOGISTIK PENANGGULANGAN BENCANA NOMOR 16 TAHUN 2025 FORMAT DOKUMEN PENYELENGGARAAN KLASTER LOGISTIK PENANGGULANGAN BENCANA Format 1- Surat keputusan Logo Povinsi/Kabupaten/Kota KEPUTUSAN GUBERNUR/ WALIKOTA/BUPATI NOMOR TAHUN …… TENTANG PEMBENTUKAN KLASTER LOGISTIK PENANGGULANGAN BENCANA PROVINSI/ KABUPATEN/KOTA GUBERNUR/BUPATI/WALIKOTA, Menimbang : a. bahwa berdasarkan ketentuan Pasal 2 ayat (4) Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana, Klaster Logistik Provinsi dibentuk oleh Pemerintah Daerah sesuai dengan kewenangannya;
b. bahwa dalam rangka menyelenggarakan manajemen logistik penanggulangan bencana yang efektif dan efisien, perlu pelibatan multipihak yang dilaksanakan melalui mekanisme klaster logistik;
C. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Keputusan Gubernur/Bupati/Walikota tentang Pembentukan Klaster Logistik Penanggulangan Bencana Provinsi/ Kabupaten/Kota;
Mengingat : 1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 18 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);');
