INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (145, 'juklak-16-2025', 39, 'lampiran', 'LAMPIRAN II', NULL, 22, 'KEPUTUSAN GUBERNUR/WALIKOTA/BUPATI NOMOR: TAHUN XXXX TENTANG: KLASTER LOGISTIK PENANGGULANGAN BENCANA PROVINSI/KABUPATEN/KOTA TUGAS DAN TANGGUNG JAWAB KEANGGOTAAN KLASTER LOGISTIK PENANGGULANGAN BENCANA PROVINSI/KABUPATEN/KOTA NO Kedudukan dalam Rincian tugas satuan tugas
1. Pengarah a. Memimpin penyelenggaraan, pembinaan, keberlangsungan, dan keberlanjutan Klaster Logistik Provinsi sesuai peraturan perundang-undangan.
b. Memberikan arahan dan bimbingan kepada Tim Klaster Logistik Provinsi sesuai peraturan perundang-undangan.
c. Memberikan saran, masukan, atau pertimbangan terkait pengembangan organisasi, program kerja, dan kebijakan sesuai peraturan perundang-undangan.
d. Bertanggung jawab atas pelaksanaan Klaster Logistik Provinsi sesuai peraturan perundang-undangan.
e. Mengkoordinasikan sinergi lintas sektor, lintas OPD, lembaga, dunia usaha, akademisi, dan masyarakat dalam mendukung penyelenggaraan logistik bencana di provinsi.
f. Melakukan pengawasan, monitoring, dan evaluasi terhadap pelaksanaan Klaster Logistik Provinsi serta memberikan rekomendasi perbaikan.
g. Menetapkan langkah-langkah strategis dalam mengatasi hambatan dan tantangan penyelenggaraan dukungan logistik di daerah.
h. Mendorong inovasi, digitalisasi, dan optimalisasi sumber daya logistik 23 untuk meningkatkan ketahanan logistik bencana di tingkat provinsi.
2. Koordinator a. Mengoordinasikan pelaksanaan tugas sekretariat dan bidang-bidang pada Klaster Logistik Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (145, 'KEPUTUSAN GUBERNUR/WALIKOTA/BUPATI NOMOR: TAHUN XXXX TENTANG: KLASTER LOGISTIK PENANGGULANGAN BENCANA PROVINSI/KABUPATEN/KOTA TUGAS DAN TANGGUNG JAWAB KEANGGOTAAN KLASTER LOGISTIK PENANGGULANGAN BENCANA PROVINSI/KABUPATEN/KOTA NO Kedudukan dalam Rincian tugas satuan tugas
1. Pengarah a. Memimpin penyelenggaraan, pembinaan, keberlangsungan, dan keberlanjutan Klaster Logistik Provinsi sesuai peraturan perundang-undangan.
b. Memberikan arahan dan bimbingan kepada Tim Klaster Logistik Provinsi sesuai peraturan perundang-undangan.
c. Memberikan saran, masukan, atau pertimbangan terkait pengembangan organisasi, program kerja, dan kebijakan sesuai peraturan perundang-undangan.
d. Bertanggung jawab atas pelaksanaan Klaster Logistik Provinsi sesuai peraturan perundang-undangan.
e. Mengkoordinasikan sinergi lintas sektor, lintas OPD, lembaga, dunia usaha, akademisi, dan masyarakat dalam mendukung penyelenggaraan logistik bencana di provinsi.
f. Melakukan pengawasan, monitoring, dan evaluasi terhadap pelaksanaan Klaster Logistik Provinsi serta memberikan rekomendasi perbaikan.
g. Menetapkan langkah-langkah strategis dalam mengatasi hambatan dan tantangan penyelenggaraan dukungan logistik di daerah.
h. Mendorong inovasi, digitalisasi, dan optimalisasi sumber daya logistik 23 untuk meningkatkan ketahanan logistik bencana di tingkat provinsi.
2. Koordinator a. Mengoordinasikan pelaksanaan tugas sekretariat dan bidang-bidang pada Klaster Logistik Penanggulangan Bencana;', 'LAMPIRAN II', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (146, 'juklak-16-2025', 40, 'lampiran', 'LAMPIRAN II (lanjutan 1)', NULL, 23, 'b. Mengoordinasikan dukungan logistik dengan klaster lainnya serta pemangku kepentingan penanggulangan bencana terkait;
c. Mengoordinasikan Klaster Logistik Penanggulangan Bencana dan anggotanya terintegrasi dalam Sistem Komando Penanganan Darurat Bencana untuk dukungan teknis dan operasional logistik;
d. Memastikan terlaksananya pengendalian, pengawasan, evaluasi dan pembelajaran terkait pelaksanaan kegiatan Klaster Logistik Penanggulangan Bencana;
e. Melaporkan hasil pelaksanaan kegiatan Klaster Logistik kepada Kepala Daerah dengan tembusan kepada Kepala BNPB dan pimpinan institusi yang menjadi anggota klaster logistik terkait.
2. Wakil Koordinator a. Membantu pelaksanaan tugas dan fungsi Koordinator Klaster Logistik;
b. Membantu membangun kemitraan multipihak di luar keanggotaan klaster logistik daerah yang bergerak dalam logistik kebencanaan;
c. Bertanggungjawab menggantikan tugas Koordinator apabila yang bersangkutan tidak hadir atau berhalangan sementara;
d. Menjembatani komunikasi antar bidang, antar klaster dan integrasi dengan Sistem Komando Penanganan Darurat Bencana serta menyampaikan kebijakan/arahan dari Koordinator;
e. Membantu mengoordinasikan penyusunan Rencana Rehabilitasi dan Rekonstruksi Pasca Bencana 24
2. Sekretariat a. Sekretariat dikoordinasikan oleh Sekretaris;
b. Melaksanakan pengendalian, pengawasan, evaluasi dan pembelajaran terkait pelaksanaan kegiatan Klaster Logistik Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (146, 'b. Mengoordinasikan dukungan logistik dengan klaster lainnya serta pemangku kepentingan penanggulangan bencana terkait;
c. Mengoordinasikan Klaster Logistik Penanggulangan Bencana dan anggotanya terintegrasi dalam Sistem Komando Penanganan Darurat Bencana untuk dukungan teknis dan operasional logistik;
d. Memastikan terlaksananya pengendalian, pengawasan, evaluasi dan pembelajaran terkait pelaksanaan kegiatan Klaster Logistik Penanggulangan Bencana;
e. Melaporkan hasil pelaksanaan kegiatan Klaster Logistik kepada Kepala Daerah dengan tembusan kepada Kepala BNPB dan pimpinan institusi yang menjadi anggota klaster logistik terkait.
2. Wakil Koordinator a. Membantu pelaksanaan tugas dan fungsi Koordinator Klaster Logistik;
b. Membantu membangun kemitraan multipihak di luar keanggotaan klaster logistik daerah yang bergerak dalam logistik kebencanaan;
c. Bertanggungjawab menggantikan tugas Koordinator apabila yang bersangkutan tidak hadir atau berhalangan sementara;
d. Menjembatani komunikasi antar bidang, antar klaster dan integrasi dengan Sistem Komando Penanganan Darurat Bencana serta menyampaikan kebijakan/arahan dari Koordinator;
e. Membantu mengoordinasikan penyusunan Rencana Rehabilitasi dan Rekonstruksi Pasca Bencana 24
2. Sekretariat a. Sekretariat dikoordinasikan oleh Sekretaris;
b. Melaksanakan pengendalian, pengawasan, evaluasi dan pembelajaran terkait pelaksanaan kegiatan Klaster Logistik Penanggulangan Bencana;', 'LAMPIRAN II (lanjutan 1)', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (147, 'juklak-16-2025', 41, 'lampiran', 'LAMPIRAN II (lanjutan 2)', NULL, 24, 'c. Sekretaris bertugas dan bertanggung jawab dalam kegiatan:
1. Penyelenggaraan administrasi dan keuangan;
2. Penyelenggaraan data dan informasi;
3. Penyelenggaraan monitoring dan evaluasi;
d. Sekretaris bertanggung jawab langsung kepada Koordinator Klaster Logistik;
e. Dalam pelaksanaan tugasnya dibantu oleh beberapa Kepala Sub Bagian:
1. Sub Bagian Administrasi dan Keuangan;
2. Sub Bagian Pengelolaan Data dan Informasi;
3. Sub Bagian Monitoring dan Evaluasi;
f. Sub Bagian Administrasi dan Keuangan dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan administrasi dan keuangan, bertugas dan bertanggung jawab dalam kegiatan:
1. Menyiapkan, mengelola dan mengarsipkan dokumen administrasi dan persuratan dalam pelaksanaan kegiatan Klaster Logistik Penanggulangan Bencana;
2. Menyusun kebutuhan anggaran untuk penyelenggaraan kegiatan Klaster Logistik;
3. Menyelenggarakan pertanggungjawaban keuangan;
4. Mengkompilasi rencana kerja Klaster Logistik dari masing-masing bidang;
25
5. Mengoordinasikan jadwal pertemuan dan kegiatan koordinasi lainnya baik kepada anggota Klaster Logistik maupun kegiatan koordinasi antar klaster;
6. Menyusun rencana peningkatan kapasitas Sumber Daya Manusia;
7. Mengumpulkan dan menyiapkan bahan rapat koordinasi;
8. Menyiapkan dokumen administrasi penyelenggaraan klaster;
9. Mengarsipkan segala dokumen penyelenggaraan kegiatan Klaster Logistik;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (147, 'c. Sekretaris bertugas dan bertanggung jawab dalam kegiatan:
1. Penyelenggaraan administrasi dan keuangan;
2. Penyelenggaraan data dan informasi;
3. Penyelenggaraan monitoring dan evaluasi;
d. Sekretaris bertanggung jawab langsung kepada Koordinator Klaster Logistik;
e. Dalam pelaksanaan tugasnya dibantu oleh beberapa Kepala Sub Bagian:
1. Sub Bagian Administrasi dan Keuangan;
2. Sub Bagian Pengelolaan Data dan Informasi;
3. Sub Bagian Monitoring dan Evaluasi;
f. Sub Bagian Administrasi dan Keuangan dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan administrasi dan keuangan, bertugas dan bertanggung jawab dalam kegiatan:
1. Menyiapkan, mengelola dan mengarsipkan dokumen administrasi dan persuratan dalam pelaksanaan kegiatan Klaster Logistik Penanggulangan Bencana;
2. Menyusun kebutuhan anggaran untuk penyelenggaraan kegiatan Klaster Logistik;
3. Menyelenggarakan pertanggungjawaban keuangan;
4. Mengkompilasi rencana kerja Klaster Logistik dari masing-masing bidang;
25
5. Mengoordinasikan jadwal pertemuan dan kegiatan koordinasi lainnya baik kepada anggota Klaster Logistik maupun kegiatan koordinasi antar klaster;
6. Menyusun rencana peningkatan kapasitas Sumber Daya Manusia;
7. Mengumpulkan dan menyiapkan bahan rapat koordinasi;
8. Menyiapkan dokumen administrasi penyelenggaraan klaster;
9. Mengarsipkan segala dokumen penyelenggaraan kegiatan Klaster Logistik;', 'LAMPIRAN II (lanjutan 2)', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (148, 'juklak-16-2025', 42, 'lampiran', 'LAMPIRAN II (lanjutan 3)', NULL, 25, 'g. Sub Bagian Pengelolaan Data dan Informasi dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan data dan informasi, bertugas dan bertanggungjawab dalam kegiatan:
1. Mengumpulkan dan mengelola data terkait logistik;
2. Menyiapkan dan memutakhirkan data informasi terkait logistik;
3. Menyusun pesan kunci dan Menyebarluaskan informasi terkait logistik yang dibutuhkan dan direncanakan dalam bentuk produk informasi;
h. Sub Bagian Monitoring dan Evaluasi dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan monitoring dan evaluasi, bertugas dan bertanggungjawab dalam kegiatan:
1. Melakukan monitoring atas pelaksanaan kegiatan masing-masing bidang Klaster Logistik;
2. Melakukan evaluasi atas pelaksanaan semua bidang klaster logistik;
3. Menyusun rekomendasi untuk perbaikan atau pembaharuan 26 pelaksanaan kegiatan Klaster Logistik;
4. Menyusun dan mengkompilasi laporan akhir dari masing-masing bidang Klaster Logistik.
3. Bidang Perencanaan
a. Bidang Perencanaan dan dan Pemenuhan Pemenuhan Kebutuhan Kebutuhan dikoordinasikan oleh Kepala Bidang dengan tugas memimpin dan mengoordinasi pelaksanaan tugas teknis atau operasional Bidang Perencanaan dan Pemenuhan Kebutuhan
b. Kepala Bidang bertugas dan bertanggung jawab dalam kegiatan:
1. Penyelenggaraan perencanaan dan pemenuhan kebutuhan logistik dan peralatan;
2. Menyusun bahan laporan kegiatan bidang perencanaan dan Pemenuhan Kebutuhan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (148, 'g. Sub Bagian Pengelolaan Data dan Informasi dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan data dan informasi, bertugas dan bertanggungjawab dalam kegiatan:
1. Mengumpulkan dan mengelola data terkait logistik;
2. Menyiapkan dan memutakhirkan data informasi terkait logistik;
3. Menyusun pesan kunci dan Menyebarluaskan informasi terkait logistik yang dibutuhkan dan direncanakan dalam bentuk produk informasi;
h. Sub Bagian Monitoring dan Evaluasi dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan monitoring dan evaluasi, bertugas dan bertanggungjawab dalam kegiatan:
1. Melakukan monitoring atas pelaksanaan kegiatan masing-masing bidang Klaster Logistik;
2. Melakukan evaluasi atas pelaksanaan semua bidang klaster logistik;
3. Menyusun rekomendasi untuk perbaikan atau pembaharuan 26 pelaksanaan kegiatan Klaster Logistik;
4. Menyusun dan mengkompilasi laporan akhir dari masing-masing bidang Klaster Logistik.
3. Bidang Perencanaan
a. Bidang Perencanaan dan dan Pemenuhan Pemenuhan Kebutuhan Kebutuhan dikoordinasikan oleh Kepala Bidang dengan tugas memimpin dan mengoordinasi pelaksanaan tugas teknis atau operasional Bidang Perencanaan dan Pemenuhan Kebutuhan
b. Kepala Bidang bertugas dan bertanggung jawab dalam kegiatan:
1. Penyelenggaraan perencanaan dan pemenuhan kebutuhan logistik dan peralatan;
2. Menyusun bahan laporan kegiatan bidang perencanaan dan Pemenuhan Kebutuhan;', 'LAMPIRAN II (lanjutan 3)', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (149, 'juklak-16-2025', 43, 'lampiran', 'LAMPIRAN II (lanjutan 4)', NULL, 26, '3. Menyusun laporan pemantauan dan evaluasi bidang Perencanaan dan Pemenuhan Kebutuhan.
c. Kepala Bidang Perencanaan dan Pemenuhan Kebutuhan bertanggung jawab langsung kepada Koordinator Klaster Logistik;
d. Dalam pelaksanaan tugasnya dibantu oleh Kepala Sub Bidang:
1. Sub Bidang Perencanaan Kebutuhan;
2. Sub Bidang Pemenuhan Kebutuhan.
e. Sub Bidang Perencanaan Kebutuhan dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan perencanaan kebutuhan logistik dan peralatan, bertugas dan bertanggung jawab dalam kegiatan:
1. Melakukan inventarisasi atau pemetaan dukungan sumber daya logistik dan peralatan serta sarana dan prasarana yang dimiliki oleh anggota 27 klaster dan dapat dikerahkan pada saat penanganan darurat bencana melalui sistem informasi logistik yang berlaku;
2. Melakukan identifikasi kebutuhan logistik dan peralatan untuk penyelamatan dan evakuasi korban, pemenuhan kebutuhan dasar dan, pemulihan segera sarana dan prasarana vital;
3. Menyusun standar operasional prosedur dan rencana kerja Bidang perencanaan dan Pemenuhan Kebutuhan.
f. Sub Bidang Pemenuhan Kebutuhan dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan pemenuhan kebutuhan logistik dan peralatan, bertugas dan bertanggung jawab dalam kegiatan:
1. Melakukan pemenuhan kebutuhan melalui pengadaan, hibah, pinjam pakai dan/atau alih status;
2. Melakukan koordinasi dengan Bidang Penyimpanan dan Pendistribusian;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (149, '3. Menyusun laporan pemantauan dan evaluasi bidang Perencanaan dan Pemenuhan Kebutuhan.
c. Kepala Bidang Perencanaan dan Pemenuhan Kebutuhan bertanggung jawab langsung kepada Koordinator Klaster Logistik;
d. Dalam pelaksanaan tugasnya dibantu oleh Kepala Sub Bidang:
1. Sub Bidang Perencanaan Kebutuhan;
2. Sub Bidang Pemenuhan Kebutuhan.
e. Sub Bidang Perencanaan Kebutuhan dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan perencanaan kebutuhan logistik dan peralatan, bertugas dan bertanggung jawab dalam kegiatan:
1. Melakukan inventarisasi atau pemetaan dukungan sumber daya logistik dan peralatan serta sarana dan prasarana yang dimiliki oleh anggota 27 klaster dan dapat dikerahkan pada saat penanganan darurat bencana melalui sistem informasi logistik yang berlaku;
2. Melakukan identifikasi kebutuhan logistik dan peralatan untuk penyelamatan dan evakuasi korban, pemenuhan kebutuhan dasar dan, pemulihan segera sarana dan prasarana vital;
3. Menyusun standar operasional prosedur dan rencana kerja Bidang perencanaan dan Pemenuhan Kebutuhan.
f. Sub Bidang Pemenuhan Kebutuhan dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan pemenuhan kebutuhan logistik dan peralatan, bertugas dan bertanggung jawab dalam kegiatan:
1. Melakukan pemenuhan kebutuhan melalui pengadaan, hibah, pinjam pakai dan/atau alih status;
2. Melakukan koordinasi dengan Bidang Penyimpanan dan Pendistribusian;', 'LAMPIRAN II (lanjutan 4)', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (150, 'juklak-16-2025', 44, 'lampiran', 'LAMPIRAN II (lanjutan 5)', NULL, 27, '3. Melakukan koordinasi dengan Lembaga Usaha, Unsur Non Pemerintah, dan Lembaga Internasional.
4. Bidang Penyimpanan
a. Bidang Penyimpanan dikoordinasikan oleh Kepala Bidang dengan tugas memimpin dan mengoordinasi pelaksanaan tugas teknis atau operasional Bidang Penyimpanan
b. Kepala Bidang bertugas dan bertanggung jawab dalam kegiatan:
1. Memastikan kebutuhan dan ketersediaan sarana dan prasarana penyimpanan serta kebutuhan operasional gudang;
2. Memimpin dan mengoordinasikan pelaksanaan tugas teknis atau operasional Bidang Penyimpanan yang meliputi proses penerimaan, 28 penyimpanan, pemeliharaan, pengeluaran, pembuatan laporan dan pengelolaan sumber daya manusia;
3. Menyampaikan data ketersediaan logistik kepada Koordinator Klaster Logistik;
4. Menyusun laporan pemantauan dan evaluasi bidang penyimpanan.
c. Kepala Bidang Penyimpanan bertanggung jawab langsung kepada Koordinator Klaster Logistik.
d. Dalam pelaksanaan tugasnya dibantu oleh kepala sub bidang:
1. Sub Bidang Penyimpanan Umum;
2. Sub Bidang Penyimpanan Khusus (cold storage, bahan beracun dan berbahaya (b3), dan lainnya)
e. Sub Bidang Penyimpanan Umum dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan pengelolaan logistik dan peralatan, bertugas dan bertanggung jawab dalam kegiatan:
1. Menerima, memeriksa, mencatat, menyimpan, dan mengeluarkan bantuan logistik dan peralatan;
2. Melakukan pemutakhiran data stok akhir harian;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (150, '3. Melakukan koordinasi dengan Lembaga Usaha, Unsur Non Pemerintah, dan Lembaga Internasional.
4. Bidang Penyimpanan
a. Bidang Penyimpanan dikoordinasikan oleh Kepala Bidang dengan tugas memimpin dan mengoordinasi pelaksanaan tugas teknis atau operasional Bidang Penyimpanan
b. Kepala Bidang bertugas dan bertanggung jawab dalam kegiatan:
1. Memastikan kebutuhan dan ketersediaan sarana dan prasarana penyimpanan serta kebutuhan operasional gudang;
2. Memimpin dan mengoordinasikan pelaksanaan tugas teknis atau operasional Bidang Penyimpanan yang meliputi proses penerimaan, 28 penyimpanan, pemeliharaan, pengeluaran, pembuatan laporan dan pengelolaan sumber daya manusia;
3. Menyampaikan data ketersediaan logistik kepada Koordinator Klaster Logistik;
4. Menyusun laporan pemantauan dan evaluasi bidang penyimpanan.
c. Kepala Bidang Penyimpanan bertanggung jawab langsung kepada Koordinator Klaster Logistik.
d. Dalam pelaksanaan tugasnya dibantu oleh kepala sub bidang:
1. Sub Bidang Penyimpanan Umum;
2. Sub Bidang Penyimpanan Khusus (cold storage, bahan beracun dan berbahaya (b3), dan lainnya)
e. Sub Bidang Penyimpanan Umum dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan pengelolaan logistik dan peralatan, bertugas dan bertanggung jawab dalam kegiatan:
1. Menerima, memeriksa, mencatat, menyimpan, dan mengeluarkan bantuan logistik dan peralatan;
2. Melakukan pemutakhiran data stok akhir harian;', 'LAMPIRAN II (lanjutan 5)', 'Petunjuk Pelaksanaan Penyelenggaraan Klaster Logistik Penanggulangan Bencana Nomor 16 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (151, 'juklak-16-2025', 45, 'lampiran', 'LAMPIRAN II (lanjutan 6)', NULL, 28, '3. Menyampaikan data ketersediaan logistik dan peralatan kepada Kepala Bidang Penyimpanan;
4. Melaksanakan stock opname secara berkala untuk logistik dan peralatan;
