INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (152, 'juklak-16-2025', 46, 'lampiran', 'LAMPIRAN II (lanjutan 7)', NULL, 29, 'c. Kepala Bidang Pendistribusian bertanggung jawab langsung kepada Koordinator Klaster Logistik;
d. Dalam pelaksanaan tugasnya dibantu oleh beberapa Kepala Sub Bidang:
1. Sub Bidang Pengerahan Angkutan/Transportasi
2. Sub Bidang Pengerahan Personel;
3. Sub Bidang Keamanan;
e. Sub Bidang Pengerahan Angkutan/Transportasi dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan angkutan/ 30 transportasi, bertugas dan bertanggung jawab dalam kegiatan:
1. Melakukan perencanaan di Sub Bidang Pengerahan Angkutan/Transportasi dan pemetaan jalur distribusi.
2. Memastikan kesiapan dan ketersediaan moda transportasi dan infrastruktur di titik asal sesuai dengan jadwal pendistribusian yang telah disusun.
3. Menentukan moda transportasi sesuai dengan perhitungan berat dan volume barang bantuan yang akan didistribusikan.
4. Memastikan kesesuaian barang bantuan yang akan didistribusikan dengan dokumen pengiriman.
5. Mengoordinasikan dengan penerima barang terkait proses pendistribusian (waktu, jumlah, jenis barang)
6. Penyelenggaraan pendistribusian dari titik asal ke titik distribusi dengan memperhatikan aspek: ● aksesibilitas ● keamanan ● keselamatan ● tepat waktu ● tepat sasaran
7. Melaporkan hasil pelaksanaan dan evaluasi kegiatan ke Kepala Bidang Pendistribusian;
f. Sub Bidang Pengerahan Personel dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan pengerahan personel, bertugas dan bertanggung jawab dalam kegiatan:');
