INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (153, 'juklak-16-2025', 47, 'lampiran', 'LAMPIRAN II (lanjutan 8)', NULL, 30, '1. Melakukan perencanaan pada Sub Bidang Pengerahan Personel yang dibutuhkan;
2. Memastikan ketersediaan personel bongkar muat di titik asal dan titik distribusi;
3. Melakukan koordinasi dan pendampingan pendistribusian dari titik asal sampai titik distribusi dan memastikan 31 kesesuaian dokumen pendistribusian barang bantuan;
4. Melaporkan hasil pelaksanaan dan evaluasi kegiatan ke Kepala Bidang Pendistribusian;
g. Sub Bidang Keamanan dikoordinasikan dan dilaksanakan oleh anggota Klaster Logistik yang membidangi urusan keamanan, bertugas dan bertanggung jawab dalam kegiatan:
1. Berkoordinasi dengan tim di daerah/lokasi bencana untuk keamanan bantuan;
2. Melaksanakan pembekalan teknis terkait prosedur keamanan dan keselamatan selama proses distribusi dukungan logistik;
3. Menjaga keamanan dan pengawalan barang bantuan logistik dan peralatan dari titik asal sampai titik distribusi;
4. Menjaga jalur distribusi aman dari gangguan;
5. Menjaga ketertiban masyarakat pada saat proses pendistribusian;
6. Mendukung pengamanan operasional penyimpanan.
