INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (154, 'juklak-16-2025', 48, 'lampiran', 'LAMPIRAN II (lanjutan 9)', NULL, 32, 'a. Membangun koordinasi di antara pelaku-pelaku logistik tingkat Provinsi dan antar Kabupaten/Kota.
b. Terbangunnya manajemen data dan informasi logistik.
