INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (220, 'juklak-2-2022', 1, 'lain', 'Isi hal. 1', NULL, 1, 'KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN BANTUAN DANA TUNGGU HUNIAN NOMOR 2 TAHUN 2022');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (220, 'KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN BANTUAN DANA TUNGGU HUNIAN NOMOR 2 TAHUN 2022', 'Isi hal. 1', 'Petunjuk Pelaksanaan Nomor 2 Tahun 2022 tentang Bantuan Dana Tunggu Hunian');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (221, 'juklak-2-2022', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Jumlah kejadian bencana di Indonesia cenderung meningkat setiap ta-hunnya. Dampak buruk dari kejadian bencana seringkali menyebabkan adanya arus pengungsian penduduk terdampak. Oleh karena itu, dalam rangka pemenuhan kebutuhan dasar bagi pengungsi, perlu upaya penye-diaan hunian sementara.
Untuk mendukung upaya penyediaan hunian sementara, maka sesuai dengan lampiran petunjuk pelaksanaan Peraturan Badan Nasional Pe-nanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai, terhadap korban dan pengungsi akibat bencana dapat diberikan dana tunggu hunian pada saat diberlakukannya status keadaan darurat bencana.
Pada saat ini belum terdapat instrumen hukum yang mengatur secara spe-sifik tentang tata cara pemberian dana tunggu hunian. Sehingga, perlu diben-tuk Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian Bagi Pengungsi Korban Bencana Pada Status Keadaan Darurat Bencana.
B. Maksud dan Tujuan
1. Petunjuk Pelaksanaan ini dimaksudkan sebagai rujukan/acuan bagi BNPB, BPBD Provinsi/Kabupaten/Kota terkait dengan peng-gunaan dana siap pakai untuk pemberian bantuan dana tunggu hunian bagi korban dan pengungsi akibat bencana.
Sa
2. Tujuan dari Petunjuk Pelaksanaan ini adalah tersedianya meka-nisme pengelolaan pemberian bantuan dana tunggu hunian bagi korban dan pengungsi akibat bencana secara tertib, cepat, tepat waktu, dan tepat sasaran, sehingga dapat dipertanggungjawabkan secara transparan dan akuntabel.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (221, 'PENDAHULUAN A. Latar Belakang Jumlah kejadian bencana di Indonesia cenderung meningkat setiap ta-hunnya. Dampak buruk dari kejadian bencana seringkali menyebabkan adanya arus pengungsian penduduk terdampak. Oleh karena itu, dalam rangka pemenuhan kebutuhan dasar bagi pengungsi, perlu upaya penye-diaan hunian sementara.
Untuk mendukung upaya penyediaan hunian sementara, maka sesuai dengan lampiran petunjuk pelaksanaan Peraturan Badan Nasional Pe-nanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai, terhadap korban dan pengungsi akibat bencana dapat diberikan dana tunggu hunian pada saat diberlakukannya status keadaan darurat bencana.
Pada saat ini belum terdapat instrumen hukum yang mengatur secara spe-sifik tentang tata cara pemberian dana tunggu hunian. Sehingga, perlu diben-tuk Petunjuk Pelaksanaan Bantuan Dana Tunggu Hunian Bagi Pengungsi Korban Bencana Pada Status Keadaan Darurat Bencana.
B. Maksud dan Tujuan
1. Petunjuk Pelaksanaan ini dimaksudkan sebagai rujukan/acuan bagi BNPB, BPBD Provinsi/Kabupaten/Kota terkait dengan peng-gunaan dana siap pakai untuk pemberian bantuan dana tunggu hunian bagi korban dan pengungsi akibat bencana.
Sa
2. Tujuan dari Petunjuk Pelaksanaan ini adalah tersedianya meka-nisme pengelolaan pemberian bantuan dana tunggu hunian bagi korban dan pengungsi akibat bencana secara tertib, cepat, tepat waktu, dan tepat sasaran, sehingga dapat dipertanggungjawabkan secara transparan dan akuntabel.', 'BAB I', 'Petunjuk Pelaksanaan Nomor 2 Tahun 2022 tentang Bantuan Dana Tunggu Hunian');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (222, 'juklak-2-2022', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 2, 'Ruang Lingkup Ruang lingkup Petunjuk Pelaksanaan ini meliputi:
Pengertian Kriteria Penerima Standar Pemberian Jangka Waktu Pemberian Besaran dan Penyaluran Mekanisme Pengusulan Mekanisme Verifikasi Pertanggungjawaban Penggunaan Monitoring, Evaluasi, dan Pelaporan Pengertian Dana Tunggu Hunian, yang selanjutnya disingkat DTH adalah dana siap pakai yang diberikan kepada korban dan pengungsi akibat bencana yang digunakan untuk mencari tempat tinggal sementara pada saat menunggu hunian tetap/rumahnya selesai dibangun.
Dana Siap Pakai, yang selanjutnya disingkat DSP adalah dana yang selalu tersedia dan dicadangkan oleh Pemerintah untuk digunakan pada saat keadaan darurat, keadaan tertentu, dan pertimbangan adanya risiko bencana berdampak luas yang ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (222, 'Ruang Lingkup Ruang lingkup Petunjuk Pelaksanaan ini meliputi:
Pengertian Kriteria Penerima Standar Pemberian Jangka Waktu Pemberian Besaran dan Penyaluran Mekanisme Pengusulan Mekanisme Verifikasi Pertanggungjawaban Penggunaan Monitoring, Evaluasi, dan Pelaporan Pengertian Dana Tunggu Hunian, yang selanjutnya disingkat DTH adalah dana siap pakai yang diberikan kepada korban dan pengungsi akibat bencana yang digunakan untuk mencari tempat tinggal sementara pada saat menunggu hunian tetap/rumahnya selesai dibangun.
Dana Siap Pakai, yang selanjutnya disingkat DSP adalah dana yang selalu tersedia dan dicadangkan oleh Pemerintah untuk digunakan pada saat keadaan darurat, keadaan tertentu, dan pertimbangan adanya risiko bencana berdampak luas yang ditetapkan oleh Kepala BNPB.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 2 Tahun 2022 tentang Bantuan Dana Tunggu Hunian');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (223, 'juklak-2-2022', 4, 'lain', 'BAB II', NULL, 3, 'PELAKSANAAN PENGELOLAAN BANTUAN DTH Kriteria Penerima Bantuan DTH diberikan dengan kriteria sebagai berikut:
1. korban dan pengungsi akibat bencana yang rumah tinggalnya:
a. masuk dalam kategori rumah rusak berat akibat bencana, atau
b. tidak layak huni akibat bencana.
2. tidak layak huni sebagaimana dimaksud pada Angka 1 huruf b meliputi:
a. tidak memenuhi persyaratan keselamatan bangunan dan kesehatan penghuni sesuai dengan ketentuan peraturan pe-rundang-undangan, atau
b. masuk dalam kawasan rawan bencana (zona merah) sesuai dengan rekomendasi kementerian /lembaga terkait.
3. korban dan pengungsi akibat bencana tidak mendapatkan fasilitas hunian sementara dari pemerintah/lembaga usaha/ lembaga ke-manusiaan/organisasi kemasyarakatan.
4. korban dan pengungsi akibat bencana tidak mampu secara mandiri menyediakan tempat hunian sementara.
Standar Pemberian Bantuan DTH diberikan dengan standar sebagai berikut:
1. diberikan per 1 (satu) Kepala Keluarga,
2. ditetapkan dengan Keputusan Kepala Daerah terdampak bencana dengan dilengkapi rincian daftar nama penerima bantuan berdasar-kan alamat tempat tinggal sebagaimana tercantum dalam Lampiran
1. 3. hunian sementara yang dapat disewa harus memenuhi standar minimal:
a. berukuran 3 m?per orang,
b. memiliki persyaratan keamanan dan kesehatan, Cc. memiliki aksesibilitas terhadap fasilitas umum, dan
d. menjamin privasi antar jenis kelamin dan berbagai kelompok usia.
2g Jangka Waktu Pemberian Bantuan DTH diberikan pada saat:');
