INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (227, 'juklak-2-2022', 8, 'lain', 'BAB III', NULL, 7, 'PENUTUP Petunjuk Pelaksanaan ini digunakan sebagai rujukan/acuan bagi BNPB, BPBD provinsi/kabupaten/kota mengenai penggunaan DSP untuk pemberian bantuan DTH bagi korban dan pengungsi akibat bencana.
Hal-hal yang tidak/belum diatur dalam Petunjuk Pelaksanaan ini dilaksanakan sebagaimana mestinya, berpedoman pada ketentuan peraturan perundang-undangan.
Ditetapkan di Jakarta Pada tanggal 21 A9ukUS 2021 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, Ahuyyur SUHARYANTO');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (227, 'PENUTUP Petunjuk Pelaksanaan ini digunakan sebagai rujukan/acuan bagi BNPB, BPBD provinsi/kabupaten/kota mengenai penggunaan DSP untuk pemberian bantuan DTH bagi korban dan pengungsi akibat bencana.
Hal-hal yang tidak/belum diatur dalam Petunjuk Pelaksanaan ini dilaksanakan sebagaimana mestinya, berpedoman pada ketentuan peraturan perundang-undangan.
Ditetapkan di Jakarta Pada tanggal 21 A9ukUS 2021 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, Ahuyyur SUHARYANTO', 'BAB III', 'Petunjuk Pelaksanaan Nomor 2 Tahun 2022 tentang Bantuan Dana Tunggu Hunian');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (228, 'juklak-2-2022', 9, 'lampiran', 'LAMPIRAN 1', NULL, 8, 'PETUNJUK PELAKSANAAN TENTANG BANTUAN DANA TUNGGU HUNIAN FORMAT KEPUTUSAN KEPALA DAERAH KEPUTUSAN GUBERNUR/BUPATI/WALIKOTA NOMOR ... TAHUN ...
TENTANG PENERIMA BANTUAN DANA TUNGGU HUNIAN BENCANA PADA DARURAT BENCANA DI. ...........
GUBERNUR/BUPATI/ WALIKOTA ..., Menimbang 1 a. bahwa dalam rangka penyediaan penampungan serta tempat hunian sementara bagi korban dan pengungsi akibat bencana yang tempat tinggalnya tidak dapat dihuni, diperlukan bantuan dari pemerintah:
b. bahwa salah satu bentuk pemberian bantuan penyediaan penampungan serta tempat hunian sementara sebagaimana dimaksud dalam huruf a berupa dana tunggu hunian,
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b perlu menetapkan Keputusan Gubernur/Bupati/ Walikota 252 tentang Penerima Bantuan Dana Tunggu Hunian, Mengingat 1 1 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),
2. Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 244, Tambahan Lembaran Negara Republik Indonesia Nomor 5587) sebagaimana telah diubah terakhir dengan Undang-Undang Nomor 9 Tahun 2015 tentang Perubahan Kedua Atas Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaga Negara Republik Indonesia Tahun 2014 Nomor 58, Tambahan Lembaran Negara Republik Indonesia Nomor 5679),');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (228, 'PETUNJUK PELAKSANAAN TENTANG BANTUAN DANA TUNGGU HUNIAN FORMAT KEPUTUSAN KEPALA DAERAH KEPUTUSAN GUBERNUR/BUPATI/WALIKOTA NOMOR ... TAHUN ...
