INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (236, 'juklak-2-2025', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (236, 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025', 'Judul', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (237, 'juklak-2-2025', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN SISTEM PENGELOLAAN LINGKUNGAN DAN SOSIAL PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2025');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (237, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN SISTEM PENGELOLAAN LINGKUNGAN DAN SOSIAL PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2025', 'Isi hal. 1', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (238, 'juklak-2-2025', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Berdasarkan Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana, penyaluran dana bersama penanggulangan bencana ditujukan untuk mendukung dan melengkapi ketersediaan dana penanggulangan bencana yang memadai, tepat waktu, tepat sasaran, terencana, dan berkelanjutan dalam upaya penanggulangan bencana secara berdaya guna, berhasil guna dan dapat dipertanggungjawabkan. Adapun dana bersama penanggulangan bencana dapat disalurkan pada tahap prabencana, darurat bencana, pascabencana terutama untuk pemulihan, dan untuk pendanaan transfer risiko.
Penyaluran dana bersama penanggulangan bencana dijalankan dengan prinsip membangun pengelolaan lingkungan yang berkelanjutan dan meningkatkan manfaat sosial.
Sistem pengelolaan lingkungan dan sosial merupakan prinsip-prinsip kepatuhan untuk memastikan bahwa potensi dampak negatif terhadap lingkungan dan sosial atas penyelenggaraan kegiatan dapat dimitigasi dan meningkatkan manfaat sebesar-besarnya serta mempromosikan praktik-praktik baik yang bertanggung jawab dan berkelanjutan. Dalam rangka mewujudkan pengelolaan lingkungan yang berkelanjutan serta meningkatkan manfaat bagi masyarakat, pemohon wajib melaksanakan dan menaati peraturan perundang-undangan terkait pengelolaan lingkungan dan sosial yang berlaku serta memenuhi Standar Lingkungan dan Sosial (SLS) mulai dari tahap perencanaan hingga pengakhiran kegiatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (238, 'PENDAHULUAN A. Latar Belakang Berdasarkan Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana, penyaluran dana bersama penanggulangan bencana ditujukan untuk mendukung dan melengkapi ketersediaan dana penanggulangan bencana yang memadai, tepat waktu, tepat sasaran, terencana, dan berkelanjutan dalam upaya penanggulangan bencana secara berdaya guna, berhasil guna dan dapat dipertanggungjawabkan. Adapun dana bersama penanggulangan bencana dapat disalurkan pada tahap prabencana, darurat bencana, pascabencana terutama untuk pemulihan, dan untuk pendanaan transfer risiko.
Penyaluran dana bersama penanggulangan bencana dijalankan dengan prinsip membangun pengelolaan lingkungan yang berkelanjutan dan meningkatkan manfaat sosial.
Sistem pengelolaan lingkungan dan sosial merupakan prinsip-prinsip kepatuhan untuk memastikan bahwa potensi dampak negatif terhadap lingkungan dan sosial atas penyelenggaraan kegiatan dapat dimitigasi dan meningkatkan manfaat sebesar-besarnya serta mempromosikan praktik-praktik baik yang bertanggung jawab dan berkelanjutan. Dalam rangka mewujudkan pengelolaan lingkungan yang berkelanjutan serta meningkatkan manfaat bagi masyarakat, pemohon wajib melaksanakan dan menaati peraturan perundang-undangan terkait pengelolaan lingkungan dan sosial yang berlaku serta memenuhi Standar Lingkungan dan Sosial (SLS) mulai dari tahap perencanaan hingga pengakhiran kegiatan.', 'BAB I', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (239, 'juklak-2-2025', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Berdasarkan Peraturan BNPB Nomor 1 Tahun 2024 tentang Penelahaan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana, kepatuhan terhadap sistem pengelolaan lingkungan dan sosial menjadi salah satu kriteria penyaluran untuk permohonan penyaluran dana bersama penanggulangan bencana baik pada tahap prabencana dan tahap pascabencana. Pemohon diwajibkan untuk melengkapi dokumen pengelolaan lingkungan dan sosial dalam pengajuan permohonan penyaluran dana bersama penanggulangan bencana untuk kemudian dilakukan penelaahan, verifikasi dan evaluasi. Adapun dokumen yang diwajibkan dalam rangka pelaksanaan pelindungan lingkungan dan sosial terdiri atas surat pernyataan pelindungan lingkungan dan sosial, formulir pelindungan lingkungan dan sosial, serta rancangan rencana komitmen pelindungan lingkungan dan sosial Dana Bersama Penanggulangan Bencana.
Sistem Pengelolaan Lingkungan dan Sosial dalam Petunjuk Pelaksanaan ini masih terbatas pada kegiatan pada tahap prabencana dengan risiko lingkungan dan sosial pada tingkat rendah hingga menengah, yang mencakup diantaranya penyusunan peraturan, peningkatan kapasitas, dan/atau aktivitas relevan lainnya yang memiliki dampak lingkungan dan sosial yang terkategori minimal.
Berdasarkan pertimbangan sebagaimana disebutkan di atas, perlu menyusun Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (239, 'Berdasarkan Peraturan BNPB Nomor 1 Tahun 2024 tentang Penelahaan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana, kepatuhan terhadap sistem pengelolaan lingkungan dan sosial menjadi salah satu kriteria penyaluran untuk permohonan penyaluran dana bersama penanggulangan bencana baik pada tahap prabencana dan tahap pascabencana. Pemohon diwajibkan untuk melengkapi dokumen pengelolaan lingkungan dan sosial dalam pengajuan permohonan penyaluran dana bersama penanggulangan bencana untuk kemudian dilakukan penelaahan, verifikasi dan evaluasi. Adapun dokumen yang diwajibkan dalam rangka pelaksanaan pelindungan lingkungan dan sosial terdiri atas surat pernyataan pelindungan lingkungan dan sosial, formulir pelindungan lingkungan dan sosial, serta rancangan rencana komitmen pelindungan lingkungan dan sosial Dana Bersama Penanggulangan Bencana.
Sistem Pengelolaan Lingkungan dan Sosial dalam Petunjuk Pelaksanaan ini masih terbatas pada kegiatan pada tahap prabencana dengan risiko lingkungan dan sosial pada tingkat rendah hingga menengah, yang mencakup diantaranya penyusunan peraturan, peningkatan kapasitas, dan/atau aktivitas relevan lainnya yang memiliki dampak lingkungan dan sosial yang terkategori minimal.
Berdasarkan pertimbangan sebagaimana disebutkan di atas, perlu menyusun Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (240, 'juklak-2-2025', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, 'B. Maksud dan Tujuan Petunjuk Pelaksanaan ini dimaksudkan sebagai panduan operasional dan tata laksana sistem pengelolaan lingkungan dan sosial yang merupakan salah satu persyaratan dalam permohonan penyaluran Dana Bersama Penanggulangan Bencana tahap prabencana bagi pemohon dari Kementerian/Lembaga dan Pemerintah Daerah, serta kelompok masyarakat sebagai penerima manfaat.
Petunjuk Pelaksanaan ini disusun dengan tujuan untuk:
1. Memberikan panduan bagi Kementerian/Lembaga dan Pemerintah Daerah dalam pelaksanaan sistem pengelolaan lingkungan dan sosial kegiatan yang dibiayai dana bersama penanggulangan bencana.
2. Meningkatkan pemahaman pemohon tentang tata laksana sistem pengelolaan lingkungan dan sosial dalam penyaluran Dana Bersama Penanggulangan Bencana tahap prabencana; dan
3. Meningkatkan kualitas penyusunan dokumen pengelolaan lingkungan dan sosial dalam permohonan penyaluran Dana Bersama Penanggulangan Bencana tahap prabencana.
C. Ruang Lingkup Petunjuk Pelaksanaan ini meliputi pembahasan tentang:
1. Proses Bisnis Sistem Pengelolaan Lingkungan dan Sosial; dan
2. Tata Cara Pengelolaan Lingkungan dan Sosial.
D. Pengertian Dalam Petunjuk Pelaksanaan ini yang dimaksud dengan:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (240, 'B. Maksud dan Tujuan Petunjuk Pelaksanaan ini dimaksudkan sebagai panduan operasional dan tata laksana sistem pengelolaan lingkungan dan sosial yang merupakan salah satu persyaratan dalam permohonan penyaluran Dana Bersama Penanggulangan Bencana tahap prabencana bagi pemohon dari Kementerian/Lembaga dan Pemerintah Daerah, serta kelompok masyarakat sebagai penerima manfaat.
Petunjuk Pelaksanaan ini disusun dengan tujuan untuk:
1. Memberikan panduan bagi Kementerian/Lembaga dan Pemerintah Daerah dalam pelaksanaan sistem pengelolaan lingkungan dan sosial kegiatan yang dibiayai dana bersama penanggulangan bencana.
2. Meningkatkan pemahaman pemohon tentang tata laksana sistem pengelolaan lingkungan dan sosial dalam penyaluran Dana Bersama Penanggulangan Bencana tahap prabencana; dan
3. Meningkatkan kualitas penyusunan dokumen pengelolaan lingkungan dan sosial dalam permohonan penyaluran Dana Bersama Penanggulangan Bencana tahap prabencana.
C. Ruang Lingkup Petunjuk Pelaksanaan ini meliputi pembahasan tentang:
1. Proses Bisnis Sistem Pengelolaan Lingkungan dan Sosial; dan
2. Tata Cara Pengelolaan Lingkungan dan Sosial.
D. Pengertian Dalam Petunjuk Pelaksanaan ini yang dimaksud dengan:', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (241, 'juklak-2-2025', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, '1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non-alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, pengungsian, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
3. Prabencana adalah penyelenggaraan penanggulangan bencana pada masa tidak terjadi bencana dan pada masa terdapat potensi bencana.
4. Dana Penanggulangan Bencana adalah dana yang digunakan bagi penanggulangan bencana untuk tahap prabencana, darurat bencana, dan/atau pascabencana.
5. Dana Bersama Penanggulangan Bencana yang selanjutnya disebut Dana Bersama adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi Dana Penanggulangan Bencana yang memadai dan berkelanjutan.
6. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (241, '1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non-alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, pengungsian, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
3. Prabencana adalah penyelenggaraan penanggulangan bencana pada masa tidak terjadi bencana dan pada masa terdapat potensi bencana.
4. Dana Penanggulangan Bencana adalah dana yang digunakan bagi penanggulangan bencana untuk tahap prabencana, darurat bencana, dan/atau pascabencana.
5. Dana Bersama Penanggulangan Bencana yang selanjutnya disebut Dana Bersama adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi Dana Penanggulangan Bencana yang memadai dan berkelanjutan.
6. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (242, 'juklak-2-2025', 6, 'lain', 'BAB I (lanjutan 4)', NULL, 3, '7. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan Pemerintah Daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
8. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
9. Kelompok Masyarakat adalah forum pengurangan risiko bencana, forum tematik pengurangan risiko bencana tingkat lokal, kelompok masyarakat binaan kementerian/lembaga dan perangkat daerah, serta kumpulan individu dari masyarakat terdampak bencana.
10. Sistem Pengelolaan Lingkungan dan Sosial adalah seperangkat kebijakan, prosedur, perangkat, dan kemampuan kapasitas internal untuk mengidentifikasi, mengelola, menilai, dan memantau risiko dan dampak lingkungan dan sosial secara berkelanjutan atas kegiatan yang mendapatkan pendanaan dari Dana Bersama.
11. Standar Lingkungan dan Sosial yang selanjutnya disingkat SLS adalah serangkaian standar yang digunakan untuk menghindari, meminimalkan, mengurangi, atau memitigasi risiko dan dampak yang merugikan terhadap lingkungan dan sosial.
12. Kegiatan Berbasis Lahan adalah kegiatan pengolahan struktur ruang dan pembentukan ruang-ruang antara yang dilaksanakan di atas sebuah lahan.
13. Mitigasi Risiko adalah tindakan yang bertujuan untuk menurunkan dan/atau menjaga besaran dan/atau level risiko utama hingga mencapai risiko residual harapan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (242, '7. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan Pemerintah Daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
8. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
9. Kelompok Masyarakat adalah forum pengurangan risiko bencana, forum tematik pengurangan risiko bencana tingkat lokal, kelompok masyarakat binaan kementerian/lembaga dan perangkat daerah, serta kumpulan individu dari masyarakat terdampak bencana.
10. Sistem Pengelolaan Lingkungan dan Sosial adalah seperangkat kebijakan, prosedur, perangkat, dan kemampuan kapasitas internal untuk mengidentifikasi, mengelola, menilai, dan memantau risiko dan dampak lingkungan dan sosial secara berkelanjutan atas kegiatan yang mendapatkan pendanaan dari Dana Bersama.
11. Standar Lingkungan dan Sosial yang selanjutnya disingkat SLS adalah serangkaian standar yang digunakan untuk menghindari, meminimalkan, mengurangi, atau memitigasi risiko dan dampak yang merugikan terhadap lingkungan dan sosial.
12. Kegiatan Berbasis Lahan adalah kegiatan pengolahan struktur ruang dan pembentukan ruang-ruang antara yang dilaksanakan di atas sebuah lahan.
13. Mitigasi Risiko adalah tindakan yang bertujuan untuk menurunkan dan/atau menjaga besaran dan/atau level risiko utama hingga mencapai risiko residual harapan.', 'BAB I (lanjutan 4)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (243, 'juklak-2-2025', 7, 'lain', 'BAB I (lanjutan 5)', NULL, 3, '14. Nomor Induk Berusaha yang selanjutnya disingkat NIB adalah identitas resmi yang diterbitkan oleh Lembaga Online Single Submission (OSS) bagi pelaku usaha.
15. Kesesuaian Kegiatan Pemanfaatan Ruang yang selanjutnya disingkat KKPR adalah perizinan dasar yang harus dipenuhi sebelum pelaku usaha dapat melanjutkan proses perizinan berusaha.
16. Persetujuan Kesesuaian Kegiatan Pemanfaatan Ruang yang selanjutnya disingkat PKKPR adalah dokumen yang menyatakan kesesuaian antara rencana kegiatan pemanfaatan ruang dengan Rencana Tata Ruang.
17. Surat Pernyataan Pengelolaan Lingkungan yang selanjutnya disingkat SPPL adalah surat yang wajib dimiliki oleh pelaku usaha yang seluruh kegiatan usahanya memiliki dampak penting bagi lingkungan hidup.
18. Upaya Pengelolaan Lingkungan Hidup dan Upaya Pemantauan Lingkungan Hidup yang selanjutnya disingkat UKL/UPL adalah dokumen lingkungan hidup yang harus disusun oleh pelaku usaha yang kegiatannya tidak berdampak besar terhadap lingkungan.
19. Cagar Budaya adalah warisan budaya bersifat kebendaan berupa benda cagar budaya, bangunan cagar budaya, struktur cagar budaya, situs cagar budaya, dan kawasan cagar budaya di darat dan/atau di air yang perlu dilestarikan keberadaannya karena memiliki nilai penting bagi sejarah, ilmu pengetahuan, pendidikan, agama, dan/atau kebudayaan melalui proses penetapan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (243, '14. Nomor Induk Berusaha yang selanjutnya disingkat NIB adalah identitas resmi yang diterbitkan oleh Lembaga Online Single Submission (OSS) bagi pelaku usaha.
15. Kesesuaian Kegiatan Pemanfaatan Ruang yang selanjutnya disingkat KKPR adalah perizinan dasar yang harus dipenuhi sebelum pelaku usaha dapat melanjutkan proses perizinan berusaha.
16. Persetujuan Kesesuaian Kegiatan Pemanfaatan Ruang yang selanjutnya disingkat PKKPR adalah dokumen yang menyatakan kesesuaian antara rencana kegiatan pemanfaatan ruang dengan Rencana Tata Ruang.
17. Surat Pernyataan Pengelolaan Lingkungan yang selanjutnya disingkat SPPL adalah surat yang wajib dimiliki oleh pelaku usaha yang seluruh kegiatan usahanya memiliki dampak penting bagi lingkungan hidup.
18. Upaya Pengelolaan Lingkungan Hidup dan Upaya Pemantauan Lingkungan Hidup yang selanjutnya disingkat UKL/UPL adalah dokumen lingkungan hidup yang harus disusun oleh pelaku usaha yang kegiatannya tidak berdampak besar terhadap lingkungan.
19. Cagar Budaya adalah warisan budaya bersifat kebendaan berupa benda cagar budaya, bangunan cagar budaya, struktur cagar budaya, situs cagar budaya, dan kawasan cagar budaya di darat dan/atau di air yang perlu dilestarikan keberadaannya karena memiliki nilai penting bagi sejarah, ilmu pengetahuan, pendidikan, agama, dan/atau kebudayaan melalui proses penetapan.', 'BAB I (lanjutan 5)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (244, 'juklak-2-2025', 8, 'lain', 'BAB I (lanjutan 6)', NULL, 4, '20. Prosedur Penemuan Tak Terduga adalah langkah-langkah yang harus dilakukan oleh pemohon yang kegiatannya didanai oleh Dana Bersama apabila menemukan cagar budaya secara tidak sengaja pada saat pelaksanaan kegiatan.
21. Masyarakat Hukum Adat adalah kelompok masyarakat yang secara turun temurun bermukim di wilayah geografis tertentu karena adanya ikatan pada asal usul leluhur, adanya hubungan yang kuat dengan lingkungan hidup, serta adanya sistem nilai yang menentukan pranata ekonomi, politik, sosial, dan hukum.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (244, '20. Prosedur Penemuan Tak Terduga adalah langkah-langkah yang harus dilakukan oleh pemohon yang kegiatannya didanai oleh Dana Bersama apabila menemukan cagar budaya secara tidak sengaja pada saat pelaksanaan kegiatan.
21. Masyarakat Hukum Adat adalah kelompok masyarakat yang secara turun temurun bermukim di wilayah geografis tertentu karena adanya ikatan pada asal usul leluhur, adanya hubungan yang kuat dengan lingkungan hidup, serta adanya sistem nilai yang menentukan pranata ekonomi, politik, sosial, dan hukum.', 'BAB I (lanjutan 6)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (245, 'juklak-2-2025', 9, 'lain', 'BAB II', NULL, 5, 'PROSES BISNIS PENGELOLAAN LINGKUNGAN DAN SOSIAL Sistem Pengelolaan Lingkungan dan Sosial merupakan sistem yang disusun untuk mewujudkan pengelolaan lingkungan dan sosial yang berkelanjutan serta meningkatkan manfaat bagi masyarakat dalam kegiatan yang mendapat dukungan pendanaan dari Dana Bersama. Proses bisnis dari Pengelolaan Lingkungan dan Sosial dalam Penyaluran Dana Bersama tahap prabencana terbagi menjadi 3 (tiga) tahapan seperti berikut.
A. Tahap Prapenilaian Kegiatan prapenilaian dimulai dengan penerbitan Keputusan Kepala BNPB mengenai kegiatan prioritas penyaluran dana bersama penanggulangan bencana dan pengumuman penerimaan permohonan. Pengelolaan lingkungan dan sosial dalam Penyaluran Dana Bersama tahap prabencana dimulai saat penyiapan dan pengiriman dokumen yang dilakukan oleh pemohon atau penerima manfaat baik yang berasal dari Kementerian/Lembaga, Pemerintah Daerah, serta kelompok masyarakat yang difasilitasi oleh Pemerintah Daerah. Pada tahap ini, pemohon menyusun Dokumen Pengelolaan Lingkungan dan Sosial yang dilakukan dengan mekanisme:
a. pendeskripsian usulan kegiatan;
b. penilaian mandiri terhadap tingkat risiko kegiatan dan standar lingkungan dan sosial yang terpicu; dan
c. penyusunan rancangan awal komitmen pelindungan lingkungan dan sosial Dana Bersama Penanggulangan Bencana.
Adapun dokumen pengelolaan lingkungan dan sosial berisi 3 (tiga) bagian utama, yaitu:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (245, 'PROSES BISNIS PENGELOLAAN LINGKUNGAN DAN SOSIAL Sistem Pengelolaan Lingkungan dan Sosial merupakan sistem yang disusun untuk mewujudkan pengelolaan lingkungan dan sosial yang berkelanjutan serta meningkatkan manfaat bagi masyarakat dalam kegiatan yang mendapat dukungan pendanaan dari Dana Bersama. Proses bisnis dari Pengelolaan Lingkungan dan Sosial dalam Penyaluran Dana Bersama tahap prabencana terbagi menjadi 3 (tiga) tahapan seperti berikut.
A. Tahap Prapenilaian Kegiatan prapenilaian dimulai dengan penerbitan Keputusan Kepala BNPB mengenai kegiatan prioritas penyaluran dana bersama penanggulangan bencana dan pengumuman penerimaan permohonan. Pengelolaan lingkungan dan sosial dalam Penyaluran Dana Bersama tahap prabencana dimulai saat penyiapan dan pengiriman dokumen yang dilakukan oleh pemohon atau penerima manfaat baik yang berasal dari Kementerian/Lembaga, Pemerintah Daerah, serta kelompok masyarakat yang difasilitasi oleh Pemerintah Daerah. Pada tahap ini, pemohon menyusun Dokumen Pengelolaan Lingkungan dan Sosial yang dilakukan dengan mekanisme:
a. pendeskripsian usulan kegiatan;
b. penilaian mandiri terhadap tingkat risiko kegiatan dan standar lingkungan dan sosial yang terpicu; dan
c. penyusunan rancangan awal komitmen pelindungan lingkungan dan sosial Dana Bersama Penanggulangan Bencana.
Adapun dokumen pengelolaan lingkungan dan sosial berisi 3 (tiga) bagian utama, yaitu:', 'BAB II', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (246, 'juklak-2-2025', 10, 'lain', 'BAB II (lanjutan 1)', NULL, 5, '1. Surat Pernyataan Pelindungan Lingkungan dan Sosial (Format 1) Surat ini berisi identitas pemohon serta pernyataan bahwa informasi yang dicantumkan sesuai dengan kondisi sebenarnya dan dapat dipertanggungjawabkan.
2. Formulir Pelindungan Lingkungan dan Sosial (Format 2) Formulir ini berisi penilaian mandiri terhadap kegiatan yang diajukan oleh pemohon untuk menilai dampak lingkungan dan sosial yang mungkin timbul dari usulan kegiatan.
3. Rancangan Awal Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana (Format 3) Bagian ini berisi rumusan rencana komitmen tindakan yang akan dilakukan oleh pemohon yang menerima penyaluran Dana Bersama.
Jika permohonan disetujui, dokumen ini akan menjadi bagian dari perjanjian hukum yang memuat kewajiban pihak pemohon untuk mendukung pelaksanaan Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana ini.
Dokumen pengelolaan lingkungan dan sosial sebagaimana dimaksud di atas disusun sesuai Format 1, Format 2 dan Format 3 yang termuat dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
Setelah seluruh dokumen wajib dan dokumen tambahan telah tersedia, pemohon mengajukan permohonan ke BNPB dan mendapatkan tanda terima. Penyusunan dokumen pengelolaan lingkungan dan sosial oleh pemohon dalam tahapan prapenilaian Penyaluran Dana Bersama tahap prabencana dapat dilihat pada Gambar 1.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (246, '1. Surat Pernyataan Pelindungan Lingkungan dan Sosial (Format 1) Surat ini berisi identitas pemohon serta pernyataan bahwa informasi yang dicantumkan sesuai dengan kondisi sebenarnya dan dapat dipertanggungjawabkan.
2. Formulir Pelindungan Lingkungan dan Sosial (Format 2) Formulir ini berisi penilaian mandiri terhadap kegiatan yang diajukan oleh pemohon untuk menilai dampak lingkungan dan sosial yang mungkin timbul dari usulan kegiatan.
3. Rancangan Awal Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana (Format 3) Bagian ini berisi rumusan rencana komitmen tindakan yang akan dilakukan oleh pemohon yang menerima penyaluran Dana Bersama.
Jika permohonan disetujui, dokumen ini akan menjadi bagian dari perjanjian hukum yang memuat kewajiban pihak pemohon untuk mendukung pelaksanaan Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana ini.
Dokumen pengelolaan lingkungan dan sosial sebagaimana dimaksud di atas disusun sesuai Format 1, Format 2 dan Format 3 yang termuat dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
Setelah seluruh dokumen wajib dan dokumen tambahan telah tersedia, pemohon mengajukan permohonan ke BNPB dan mendapatkan tanda terima. Penyusunan dokumen pengelolaan lingkungan dan sosial oleh pemohon dalam tahapan prapenilaian Penyaluran Dana Bersama tahap prabencana dapat dilihat pada Gambar 1.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (247, 'juklak-2-2025', 11, 'lain', 'BAB II (lanjutan 2)', NULL, 6, 'IEBE!EC !?#ABAC D?!EFEGHC!H !?CJK#K#ECG!?C?LM#EEC C1M,( !B)B*,K,) =BK1*1$,)& !"(#"(*,$&=BL(,*,) !B)L1-1-,)& !B)B"(-,,)& !LE!?CMFEMEC !B);(,K,)& T#+1-B)& ?,@(D&A,());, !B",)W,)L,) =BL(,*,)& !B);(,K,)& Y$1M,)& =BL(,*,)& T#+1-B)& B&9,-D,P,) !NOP;<;O4OG UN<=RS><SG DNTS4W4O >, !NOP4RSOT4OG U49W4R #4<;= ?4@4AG CNT4WS9 ?49W4RGCNT4WS9B !NONOW;4OG D@4<S9S=4<SG 9(2,+ LS<S=C !NOP4RSOT4O a!"#$$%&%''()EW4O?4RG FSOT=;OT4OG cGEC<S4@ !NR;A;<4OG MO<WR;ANOG ?4OGEWR4WNTSG !NOTN@C@44OG FSOT=;OT4OG cGEC<S4@ iAL#KFMLG!?LFMCUKCJEC FMCJDKCJECGcG EAEMEF !NR;A;<4O L4Od4OT4OG Ee4@GLNOd4O4G DCASWANOG FSOT=;OT4OG cGEC<S4@ LECfECJECGEgEF L?CfECEGDA#MI#?CG FMCJDKCJECGUECGEAEMEFG !?FEDEECEGD?JMEIEC UADK#?CGEMEI?#G !?CJ?FAFEEC FMCJDKCJECGUECG EAEMEF !LA!AEEFG !?CJEKKECG aUADK#?CGgEKMHG !B)B"(-,,)& !"#K#$,M !?L#ABACEC cGUADK#?CG IE#HEBECM aBMB$,( !"#$B$&D($)($&*B"+,(*&$($*B-&KB)LBM#M,,)&M()L+1)L,)&2,)&$#$(,M !"#$B$&D($)($&*B"+,(*&KB)BM,,P,)4&5B"(S(+,$(&2,)&B5,M1,$(&T,),&UB"$,-,&!U&9,P,K&!",DB)W,), Gambar 1. Proses Bisnis Pengelolaan Lingkungan dan Sosial dalam Tahapan Prapenilaian Penyaluran Dana Bersama Tahap Prabencana B. Tahap Penilaian Pada tahap penilaian, dokumen pengelolaan lingkungan dan sosial pemohon akan ditelaah dan diverifikasi oleh BNPB melalui tim penelaahan, verifikasi, dan evaluasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (247, 'IEBE!EC !?#ABAC D?!EFEGHC!H !?CJK#K#ECG!?C?LM#EEC C1M,( !B)B*,K,) =BK1*1$,)& !"(#"(*,$&=BL(,*,) !B)L1-1-,)& !B)B"(-,,)& !LE!?CMFEMEC !B);(,K,)& T#+1-B)& ?,@(D&A,());, !B",)W,)L,) =BL(,*,)& !B);(,K,)& Y$1M,)& =BL(,*,)& T#+1-B)& B&9,-D,P,) !NOP;<;O4OG UN<=RS><SG DNTS4W4O >, !NOP4RSOT4OG U49W4R #4<;= ?4@4AG CNT4WS9 ?49W4RGCNT4WS9B !NONOW;4OG D@4<S9S=4<SG 9(2,+ LS<S=C !NOP4RSOT4O a!"#$$%&%''()EW4O?4RG FSOT=;OT4OG cGEC<S4@ !NR;A;<4OG MO<WR;ANOG ?4OGEWR4WNTSG !NOTN@C@44OG FSOT=;OT4OG cGEC<S4@ iAL#KFMLG!?LFMCUKCJEC FMCJDKCJECGcG EAEMEF !NR;A;<4O L4Od4OT4OG Ee4@GLNOd4O4G DCASWANOG FSOT=;OT4OG cGEC<S4@ LECfECJECGEgEF L?CfECEGDA#MI#?CG FMCJDKCJECGUECGEAEMEFG !?FEDEECEGD?JMEIEC UADK#?CGEMEI?#G !?CJ?FAFEEC FMCJDKCJECGUECG EAEMEF !LA!AEEFG !?CJEKKECG aUADK#?CGgEKMHG !B)B"(-,,)& !"#K#$,M !?L#ABACEC cGUADK#?CG IE#HEBECM aBMB$,( !"#$B$&D($)($&*B"+,(*&$($*B-&KB)LBM#M,,)&M()L+1)L,)&2,)&$#$(,M !"#$B$&D($)($&*B"+,(*&KB)BM,,P,)4&5B"(S(+,$(&2,)&B5,M1,$(&T,),&UB"$,-,&!U&9,P,K&!",DB)W,), Gambar 1. Proses Bisnis Pengelolaan Lingkungan dan Sosial dalam Tahapan Prapenilaian Penyaluran Dana Bersama Tahap Prabencana B. Tahap Penilaian Pada tahap penilaian, dokumen pengelolaan lingkungan dan sosial pemohon akan ditelaah dan diverifikasi oleh BNPB melalui tim penelaahan, verifikasi, dan evaluasi.', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (248, 'juklak-2-2025', 12, 'lain', 'BAB II (lanjutan 3)', NULL, 6, 'Pada saat proses penelaahan, tim penelaahan, verifikasi, dan evaluasi dapat meminta pemohon untuk melakukan perbaikan Dokumen Pengelolaan Lingkungan dan Sosial dalam waktu 3 (tiga) hari kerja sejak permohonan disampaikan.
Setelah disusunnya berita acara penelaahan oleh tim penelaahan, verifikasi, dan evaluasi, dilakukan verifikasi terhadap Dokumen Pengelolaan Lingkungan dan Sosial yang disampaikan oleh pemohon. Pada tahapan verifikasi, tim penelaahan, verifikasi, dan evaluasi melakukan verifikasi terhadap:
a. kesesuaian dengan daftar negatif kegiatan;
b. pemenuhan standar lingkungan dan sosial;
c. rancangan awal rencana komitmen lingkungan dan sosial; dan
d. kebutuhan verifikasi lapangan untuk kegiatan dengan risiko lingkungan dan sosial menengah, apabila diperlukan.
Tim penelaahan, verifikasi, dan evaluasi melakukan reviu dan memberikan masukan terhadap rancangan awal rencana komitmen lingkungan dan sosial Dana Bersama Penanggulangan Bencana kepada pemohon dan hasil kesepakatan dituangkan ke dalam risalah hasil penelaahan dan verifikasi.
Setelah risalah hasil penelaahan dan verifikasi diterbitkan, pemohon diwajibkan untuk mengirimkan dokumen fisik pengajuan permohonan asli ke BNPB termasuk Dokumen Pengelolaan Lingkungan dan Sosial.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (248, 'Pada saat proses penelaahan, tim penelaahan, verifikasi, dan evaluasi dapat meminta pemohon untuk melakukan perbaikan Dokumen Pengelolaan Lingkungan dan Sosial dalam waktu 3 (tiga) hari kerja sejak permohonan disampaikan.
