INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (269, 'juklak-2-2025', 33, 'lampiran', 'LAMPIRAN I (lanjutan 2)', NULL, 19, '2. Jelaskan lokasi diisi: Lampiran 1*: Peta kegiatan* - Lingkup wilayah (desa/kelurahan, Lokasi Kegiatan Catatan: *untuk kecamatan, kabupaten/kota, provinsi) (diutamakan kegiatan berbasis - Batas wilayah administrasi dalam format .shp lahan - Luas wilayah yang akan digunakan atau .tif.
