INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (270, 'juklak-2-2025', 34, 'lampiran', 'LAMPIRAN I (lanjutan 3)', NULL, 20, '5. Perizinan yang Jenis Perizinan : Ya Tidak dibutuhkan NIB KKPR/PKKPR SPPL UKL/UPL Perizinan lainnya : ……….. (sebutkan) Tidak dibutuhkan perizinan BAGIAN 3. PERATURAN PERUNDANG-UNDANGAN YANG RELEVAN Identifikasi diisi: peraturan Jenis peraturan perundang-undangan, nomor, tahun dan tentang. perundang-undangan yang berlaku untuk aktivitas kegiatan BAGIAN 4. PELIBATAN PEMANGKU KEPENTINGAN Pemangku Kepentingan Terkait Identifikasi kapan/di mana proses konsultasi publik berlangsung, apabila diperlukan BAGIAN 5: PENGELOLAAN LINGKUNGAN DAN SOSIAL A. DAFTAR NEGATIF Pemohon menyaring kegiatan yang diusulkan apakah termasuk pada daftar negatif berikut:
1. kegiatan yang melibatkan pembelian minuman beralkohol, produk tembakau, obat-obatan rekreasional, barang mewah, sebagaimana dimaksud dalam ketentuan peraturan perundang-undangan, dan/atau barang serupa lainnya;
2. transaksi yang dilarang oleh undang-undang dan peraturan nasional serta keputusan Dewan Keamanan PBB berdasarkan Bab VII Piagam PBB;
3. terindikasi dan/atau berpotensi melanggar peraturan perundang-undangan;
4. kegiatan yang melibatkan bahan dilarang menurut peraturan internasional dan nasional termasuk namun tidak terbatas pada produksi dan/atau penggunaan produk yang mengandung material asbes dan/atau serat asbes tidak terikat;
5. kegiatan yang menunjukkan perilaku diskriminatif;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (270, '5. Perizinan yang Jenis Perizinan : Ya Tidak dibutuhkan NIB KKPR/PKKPR SPPL UKL/UPL Perizinan lainnya : ……….. (sebutkan) Tidak dibutuhkan perizinan BAGIAN 3. PERATURAN PERUNDANG-UNDANGAN YANG RELEVAN Identifikasi diisi: peraturan Jenis peraturan perundang-undangan, nomor, tahun dan tentang. perundang-undangan yang berlaku untuk aktivitas kegiatan BAGIAN 4. PELIBATAN PEMANGKU KEPENTINGAN Pemangku Kepentingan Terkait Identifikasi kapan/di mana proses konsultasi publik berlangsung, apabila diperlukan BAGIAN 5: PENGELOLAAN LINGKUNGAN DAN SOSIAL A. DAFTAR NEGATIF Pemohon menyaring kegiatan yang diusulkan apakah termasuk pada daftar negatif berikut:
1. kegiatan yang melibatkan pembelian minuman beralkohol, produk tembakau, obat-obatan rekreasional, barang mewah, sebagaimana dimaksud dalam ketentuan peraturan perundang-undangan, dan/atau barang serupa lainnya;
2. transaksi yang dilarang oleh undang-undang dan peraturan nasional serta keputusan Dewan Keamanan PBB berdasarkan Bab VII Piagam PBB;
3. terindikasi dan/atau berpotensi melanggar peraturan perundang-undangan;
4. kegiatan yang melibatkan bahan dilarang menurut peraturan internasional dan nasional termasuk namun tidak terbatas pada produksi dan/atau penggunaan produk yang mengandung material asbes dan/atau serat asbes tidak terikat;
5. kegiatan yang menunjukkan perilaku diskriminatif;', 'LAMPIRAN I (lanjutan 3)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (271, 'juklak-2-2025', 35, 'lampiran', 'LAMPIRAN I (lanjutan 4)', NULL, 20, '6. berpotensi melibatkan pekerja anak dan/atau kerja paksa yang tidak sesuai dengan ketentuan peraturan perundang-undangan di bidang ketenagakerjaan;
7. kegiatan berpotensi menimbulkan risiko bencana baru atau meningkatkan risiko bencana yang sudah ada;
8. kegiatan yang bertentangan dengan upaya pengurangan risiko bencana;
9. kegiatan yang diklasifikasikan sebagai kegiatan dengan tingkat risiko lingkungan dan sosial yang substansial hingga tinggi pada operasionalisasi penyaluran Dana Bersama Penanggulangan Bencana tahap awal, meliputi:
a. kegiatan yang wajib memiliki Analisis Mengenai Dampak Lingkungan (AMDAL);
b. Operasi kegiatan dapat menimbulkan dampak lingkungan dan sosial yang signifikan, tidak dapat dipulihkan, dan tidak dapat diabaikan;
c. Memerlukan pembebasan lahan secara tidak sukarela/paksa baik yang mengakibatkan penggusuran/pemindahan/relokasi paksa masyarakat setempat dan/atau masyarakat hukum adat, yang mengakibatkan perubahan fisik dan/atau ekonomi/perpindahan masyarakat yang berdampak pada pembatasan atau penghentian akses masyarakat terhadap tanah dan/atau sumber daya tradisional yang merupakan sumber mata pencaharian mereka;
d. Terkait dengan pekerjaan dan pembiayaan pembangunan infrastruktur besar/pekerjaan sipil besar, pembangunan infrastruktur yang berada di perairan nasional/internasional, wilayah sengketa, dan/atau pada lahan yang tidak dapat dibuktikan status lahannya secara jelas dan bersih; dan/atau');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (271, '6. berpotensi melibatkan pekerja anak dan/atau kerja paksa yang tidak sesuai dengan ketentuan peraturan perundang-undangan di bidang ketenagakerjaan;
7. kegiatan berpotensi menimbulkan risiko bencana baru atau meningkatkan risiko bencana yang sudah ada;
8. kegiatan yang bertentangan dengan upaya pengurangan risiko bencana;
9. kegiatan yang diklasifikasikan sebagai kegiatan dengan tingkat risiko lingkungan dan sosial yang substansial hingga tinggi pada operasionalisasi penyaluran Dana Bersama Penanggulangan Bencana tahap awal, meliputi:
a. kegiatan yang wajib memiliki Analisis Mengenai Dampak Lingkungan (AMDAL);
b. Operasi kegiatan dapat menimbulkan dampak lingkungan dan sosial yang signifikan, tidak dapat dipulihkan, dan tidak dapat diabaikan;
c. Memerlukan pembebasan lahan secara tidak sukarela/paksa baik yang mengakibatkan penggusuran/pemindahan/relokasi paksa masyarakat setempat dan/atau masyarakat hukum adat, yang mengakibatkan perubahan fisik dan/atau ekonomi/perpindahan masyarakat yang berdampak pada pembatasan atau penghentian akses masyarakat terhadap tanah dan/atau sumber daya tradisional yang merupakan sumber mata pencaharian mereka;
d. Terkait dengan pekerjaan dan pembiayaan pembangunan infrastruktur besar/pekerjaan sipil besar, pembangunan infrastruktur yang berada di perairan nasional/internasional, wilayah sengketa, dan/atau pada lahan yang tidak dapat dibuktikan status lahannya secara jelas dan bersih; dan/atau', 'LAMPIRAN I (lanjutan 4)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (272, 'juklak-2-2025', 36, 'lampiran', 'LAMPIRAN I (lanjutan 5)', NULL, 21, 'e. Beroperasinya kegiatan yang dapat menimbulkan kerugian bagi masyarakat lokal dan/atau masyarakat hukum adat, misalnya berdampak pada hak-hak adat masyarakat hukum adat dalam menggunakan dan mengakses tanah, aset dan sumber daya alam.
10. berpotensi menimbulkan atau mengakibatkan kerusakan permanen dan/atau kerusakan yang berarti/bermakna terhadap aset budaya dan cagar budaya, serta bangunan bersejarah dan/atau situs arkeologi yang tidak dapat diduplikasi dan diganti; dan/atau
11. berpotensi menimbulkan kerusakan atau hilangnya keanekaragaman hayati dan habitat, khususnya spesies rentan dan terancam punah yang tercantum dalam kriteria dan kategori daftar merah sesuai dengan ketentuan peraturan perundang-undangan Berdasarkan hasil penyaringan terhadap daftar negatif, usulan kegiatan (pilih satu jawaban): [ ] Termasuk dalam daftar negatif nomor … (diisi dengan nomor daftar negatif) [ ] Tidak termasuk dalam daftar negatif B. KLASIFIKASI TINGKAT RISIKO LINGKUNGAN DAN SOSIAL Dalam menentukan tingkat risiko lingkungan dan sosial, pemohon kegiatan perlu memperhatikan kriteria dengan seksama sehingga penilaian mandiri yang dilakukan sesuai dengan kondisi usulan kegiatan secara nyata.
Jika kegiatan dinilai telah memenuhi satu atau lebih kriteria pada suatu tingkat risiko, maka kegiatan yang diusulkan memiliki tingkat risiko lingkungan dan sosial tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (272, 'e. Beroperasinya kegiatan yang dapat menimbulkan kerugian bagi masyarakat lokal dan/atau masyarakat hukum adat, misalnya berdampak pada hak-hak adat masyarakat hukum adat dalam menggunakan dan mengakses tanah, aset dan sumber daya alam.
10. berpotensi menimbulkan atau mengakibatkan kerusakan permanen dan/atau kerusakan yang berarti/bermakna terhadap aset budaya dan cagar budaya, serta bangunan bersejarah dan/atau situs arkeologi yang tidak dapat diduplikasi dan diganti; dan/atau
11. berpotensi menimbulkan kerusakan atau hilangnya keanekaragaman hayati dan habitat, khususnya spesies rentan dan terancam punah yang tercantum dalam kriteria dan kategori daftar merah sesuai dengan ketentuan peraturan perundang-undangan Berdasarkan hasil penyaringan terhadap daftar negatif, usulan kegiatan (pilih satu jawaban): [ ] Termasuk dalam daftar negatif nomor … (diisi dengan nomor daftar negatif) [ ] Tidak termasuk dalam daftar negatif B. KLASIFIKASI TINGKAT RISIKO LINGKUNGAN DAN SOSIAL Dalam menentukan tingkat risiko lingkungan dan sosial, pemohon kegiatan perlu memperhatikan kriteria dengan seksama sehingga penilaian mandiri yang dilakukan sesuai dengan kondisi usulan kegiatan secara nyata.
Jika kegiatan dinilai telah memenuhi satu atau lebih kriteria pada suatu tingkat risiko, maka kegiatan yang diusulkan memiliki tingkat risiko lingkungan dan sosial tersebut.', 'LAMPIRAN I (lanjutan 5)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (273, 'juklak-2-2025', 37, 'lampiran', 'LAMPIRAN I (lanjutan 6)', NULL, 21, 'Tingkat Kriteria Ya Tidak Risiko L&S Rendah Potensi risiko dan dampak buruk terhadap manusia dan/atau lingkungan cenderung rendah atau dapat diabaikan.
Menengah Potensi risiko, dampak, dan permasalahan dapat diprediksi dan bersifat sementara Besaran dampak bersifat rendah Lokasi kegiatan telah terdefinisi secara spesifik, tanpa adanya kemungkinan timbulnya dampak di luar batas kegiatan Kemungkinan terjadinya dampak terhadap kesehatan manusia dan/atau lingkungan tergolong rendah.
Risiko dan dampak kegiatan dapat dengan mudah dimitigasi dengan cara yang dapat diprediksi.
C. PEMERIKSAAN RISIKO LINGKUNGAN DAN SOSIAL*
• Pemohon mengidentifikasi setiap indikator terkait Standar Lingkungan dan Sosial yang mungkin terpicu dari dampak dan risiko kegiatan yang diusulkan.
Apabila pertanyaan yang terdapat dalam indikator tidak relevan dengan usulan kegiatan, maka pemohon mengisi kolom “Tidak”. Sedangkan bila pertanyaan yang terdapat dalam indikator relevan, maka pemohon mengisi kolom “Ya”.
• Apabila terdapat jawaban “Ya”, pemohon mengidentifikasi dampak yang mungkin terjadi, serta instrumen yang dibutuhkan untuk memitigasi risiko lingkungan dan sosial dari tiap indikator terkait. * - Sekurang-kurangnya SLS 1 dan SLS 10 akan terpicu untuk semua usulan kegiatan.
- Referensi instrumen yang relevan dapat dilihat pada Lampiran IV.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (273, 'Tingkat Kriteria Ya Tidak Risiko L&S Rendah Potensi risiko dan dampak buruk terhadap manusia dan/atau lingkungan cenderung rendah atau dapat diabaikan.
Menengah Potensi risiko, dampak, dan permasalahan dapat diprediksi dan bersifat sementara Besaran dampak bersifat rendah Lokasi kegiatan telah terdefinisi secara spesifik, tanpa adanya kemungkinan timbulnya dampak di luar batas kegiatan Kemungkinan terjadinya dampak terhadap kesehatan manusia dan/atau lingkungan tergolong rendah.
Risiko dan dampak kegiatan dapat dengan mudah dimitigasi dengan cara yang dapat diprediksi.
C. PEMERIKSAAN RISIKO LINGKUNGAN DAN SOSIAL*
• Pemohon mengidentifikasi setiap indikator terkait Standar Lingkungan dan Sosial yang mungkin terpicu dari dampak dan risiko kegiatan yang diusulkan.
Apabila pertanyaan yang terdapat dalam indikator tidak relevan dengan usulan kegiatan, maka pemohon mengisi kolom “Tidak”. Sedangkan bila pertanyaan yang terdapat dalam indikator relevan, maka pemohon mengisi kolom “Ya”.
• Apabila terdapat jawaban “Ya”, pemohon mengidentifikasi dampak yang mungkin terjadi, serta instrumen yang dibutuhkan untuk memitigasi risiko lingkungan dan sosial dari tiap indikator terkait. * - Sekurang-kurangnya SLS 1 dan SLS 10 akan terpicu untuk semua usulan kegiatan.
- Referensi instrumen yang relevan dapat dilihat pada Lampiran IV.', 'LAMPIRAN I (lanjutan 6)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (274, 'juklak-2-2025', 38, 'lampiran', 'LAMPIRAN I (lanjutan 7)', NULL, 22, 'Indikator Tidak Ya Dampak Strategi Pengelolaan Dampak dan/atau Instrumen yang Dibutuhkan SLS Apakah kegiatan yang 1 diusulkan dan fasilitas pendukung yang menyertai atau di sekitarnya (jika ada) akan berpotensi menimbulkan dampak lingkungan dan sosial? Apakah kegiatan yang diusulkan akan mengakibatkan terdapat perbedaan pendapat dari masyarakat terkait? Apakah kegiatan yang diusulkan termasuk dalam salah satu daftar kegiatan atau usaha yang memerlukan Upaya Pengelolaan Lingkungan Hidup dan Upaya Pemantauan Lingkungan Hidup (UKL-UPL), atau Surat Pernyataan Persetujuan tentang Pengelolaan dan Pemantauan Lingkungan Hidup (SPPL) sebagaimana dipersyaratkan dalam peraturan perundang-undangan yang mengatur mengenai daftar usaha/daftar kegiatan yang wajib memiliki AMDAL, UKL-UPL dan SPPL? SLS Apakah kegiatan yang 2 diusulkan akan melibatkan tenaga kerja campuran (lokal dan/atau eksternal) atau menimbulkan risiko terhadap Kesehatan dan Keselamatan Kerja (K3) seperti kecelakaan kerja dan/atau gangguan terhadap lingkungan kerja? Apakah terdapat potensi risiko terhadap pekerja anak (di bawah usia 18 tahun) yang ditimbulkan atas pelaksanaan kegiatan? Apakah terdapat risiko yang akan ditimbulkan atas penerimaan tenaga kerja? SLS Apakah kegiatan yang 3 diusulkan akan melibatkan penggunaan bahan kimia dan berbahaya dan/atau melibatkan produksi limbah padat atau cair (misalnya air, limbah berbahaya, limbah rumah tangga atau konstruksi), atau peningkatan produksi limbah selama tahap');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (274, 'Indikator Tidak Ya Dampak Strategi Pengelolaan Dampak dan/atau Instrumen yang Dibutuhkan SLS Apakah kegiatan yang 1 diusulkan dan fasilitas pendukung yang menyertai atau di sekitarnya (jika ada) akan berpotensi menimbulkan dampak lingkungan dan sosial? Apakah kegiatan yang diusulkan akan mengakibatkan terdapat perbedaan pendapat dari masyarakat terkait? Apakah kegiatan yang diusulkan termasuk dalam salah satu daftar kegiatan atau usaha yang memerlukan Upaya Pengelolaan Lingkungan Hidup dan Upaya Pemantauan Lingkungan Hidup (UKL-UPL), atau Surat Pernyataan Persetujuan tentang Pengelolaan dan Pemantauan Lingkungan Hidup (SPPL) sebagaimana dipersyaratkan dalam peraturan perundang-undangan yang mengatur mengenai daftar usaha/daftar kegiatan yang wajib memiliki AMDAL, UKL-UPL dan SPPL? SLS Apakah kegiatan yang 2 diusulkan akan melibatkan tenaga kerja campuran (lokal dan/atau eksternal) atau menimbulkan risiko terhadap Kesehatan dan Keselamatan Kerja (K3) seperti kecelakaan kerja dan/atau gangguan terhadap lingkungan kerja? Apakah terdapat potensi risiko terhadap pekerja anak (di bawah usia 18 tahun) yang ditimbulkan atas pelaksanaan kegiatan? Apakah terdapat risiko yang akan ditimbulkan atas penerimaan tenaga kerja? SLS Apakah kegiatan yang 3 diusulkan akan melibatkan penggunaan bahan kimia dan berbahaya dan/atau melibatkan produksi limbah padat atau cair (misalnya air, limbah berbahaya, limbah rumah tangga atau konstruksi), atau peningkatan produksi limbah selama tahap', 'LAMPIRAN I (lanjutan 7)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (275, 'juklak-2-2025', 39, 'lampiran', 'LAMPIRAN I (lanjutan 8)', NULL, 22, 'konstruksi atau operasi? Apakah kegiatan yang diusulkan akan melibatkan penggunaan sumber daya, termasuk energi, air, dan bahan baku? Apakah kegiatan yang diusulkan akan menimbulkan risiko peningkatan polusi udara (misalnya debu, kebisingan, getaran, emisi gas)? Apakah kegiatan yang diusulkan akan mempengaruhi kuantitas atau kualitas air permukaan (misalnya laut, sungai, aliran sungai, lahan basah) atau air tanah (misalnya sumur)? Apakah kegiatan yang diusulkan akan menimbulkan risiko peningkatan degradasi atau erosi tanah? SLS Apakah kegiatan yang 4 diusulkan akan menimbulkan dampak dan risiko terhadap kesehatan dan keselamatan masyarakat dari kegiatan konstruksi dan/atau operasi? Apakah kegiatan yang diusulkan akan berpotensi menimbulkan risiko paparan masyarakat dan pekerja terhadap penyakit yang ditularkan melalui air, berbasis air, terkait air, dan ditularkan melalui vektor, serta penyakit menular dan tidak menular? Apakah kegiatan yang diusulkan akan melibatkan interaksi antara kontraktor dengan penerima manfaat lokal di daerah terpencil serta masyarakat yang terkena dampak? Apakah kegiatan yang diusulkan akan menimbulkan dampak dan risiko yang tidak proporsional terhadap kelompok tertentu (antara lain kelompok rentan, gender)? Apakah usulan kegiatan dilakukan pada lokasi dengan risiko bencana yang berdampak pada kesehatan dan keselamatan masyarakat? SLS Apakah usulan lokasi 5 tersebut akan berlokasi di kawasan yang tidak sesuai dengan rencana tata ruang wilayah?');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (275, 'konstruksi atau operasi? Apakah kegiatan yang diusulkan akan melibatkan penggunaan sumber daya, termasuk energi, air, dan bahan baku? Apakah kegiatan yang diusulkan akan menimbulkan risiko peningkatan polusi udara (misalnya debu, kebisingan, getaran, emisi gas)? Apakah kegiatan yang diusulkan akan mempengaruhi kuantitas atau kualitas air permukaan (misalnya laut, sungai, aliran sungai, lahan basah) atau air tanah (misalnya sumur)? Apakah kegiatan yang diusulkan akan menimbulkan risiko peningkatan degradasi atau erosi tanah? SLS Apakah kegiatan yang 4 diusulkan akan menimbulkan dampak dan risiko terhadap kesehatan dan keselamatan masyarakat dari kegiatan konstruksi dan/atau operasi? Apakah kegiatan yang diusulkan akan berpotensi menimbulkan risiko paparan masyarakat dan pekerja terhadap penyakit yang ditularkan melalui air, berbasis air, terkait air, dan ditularkan melalui vektor, serta penyakit menular dan tidak menular? Apakah kegiatan yang diusulkan akan melibatkan interaksi antara kontraktor dengan penerima manfaat lokal di daerah terpencil serta masyarakat yang terkena dampak? Apakah kegiatan yang diusulkan akan menimbulkan dampak dan risiko yang tidak proporsional terhadap kelompok tertentu (antara lain kelompok rentan, gender)? Apakah usulan kegiatan dilakukan pada lokasi dengan risiko bencana yang berdampak pada kesehatan dan keselamatan masyarakat? SLS Apakah usulan lokasi 5 tersebut akan berlokasi di kawasan yang tidak sesuai dengan rencana tata ruang wilayah?', 'LAMPIRAN I (lanjutan 8)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (276, 'juklak-2-2025', 40, 'lampiran', 'LAMPIRAN I (lanjutan 9)', NULL, 22, 'Apakah kegiatan yang diusulkan akan mempengaruhi aktivitas ekonomi masyarakat/akses masyarakat terhadap penggunaan lahan? Apakah kegiatan yang diusulkan akan menggunakan lahan yang saat ini ditempati atau biasa digunakan untuk tujuan produktif (misalnya berkebun, bertani, lokasi penangkapan ikan, hutan)? Apakah kegiatan yang diusulkan akan mengakibatkan hilangnya sumber pendapatan dan mata pencaharian akibat pembebasan lahan? Apakah kegiatan akan memicu atau memperburuk konflik sosial (di tempat-tempat yang secara historis diketahui pernah mengalami konflik sosial)? Apakah usulan kegiatan dilakukan pada lahan atau kawasan dengan tingkat risiko bencana tinggi? SLS Apakah kegiatan dapat 6 menimbulkan dampak terhadap salah satu Kawasan di bawah ini:
- Taman Nasional
- Cagar Alam
- Suaka Margasatwa
- Taman Wisata Alam');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (276, 'Apakah kegiatan yang diusulkan akan mempengaruhi aktivitas ekonomi masyarakat/akses masyarakat terhadap penggunaan lahan? Apakah kegiatan yang diusulkan akan menggunakan lahan yang saat ini ditempati atau biasa digunakan untuk tujuan produktif (misalnya berkebun, bertani, lokasi penangkapan ikan, hutan)? Apakah kegiatan yang diusulkan akan mengakibatkan hilangnya sumber pendapatan dan mata pencaharian akibat pembebasan lahan? Apakah kegiatan akan memicu atau memperburuk konflik sosial (di tempat-tempat yang secara historis diketahui pernah mengalami konflik sosial)? Apakah usulan kegiatan dilakukan pada lahan atau kawasan dengan tingkat risiko bencana tinggi? SLS Apakah kegiatan dapat 6 menimbulkan dampak terhadap salah satu Kawasan di bawah ini:
- Taman Nasional
- Cagar Alam
- Suaka Margasatwa
- Taman Wisata Alam', 'LAMPIRAN I (lanjutan 9)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (277, 'juklak-2-2025', 41, 'lampiran', 'LAMPIRAN I (lanjutan 10)', NULL, 25, '- Taman Hutan Raya Akankah kegiatan yang diusulkan akan mendatangkan jenis flora/fauna baru ke dalam suatu Kawasan? Apakah kegiatan tersebut melakukan pengadaan pestisida (baik secara langsung melalui kegiatan, atau secara tidak langsung melalui pinjaman, pembiayaan bersama, atau pendanaan mitra pemerintah), atau dapat mempengaruhi pengendalian hama dengan cara yang dapat merugikan, meskipun kegiatan tersebut tidak direncanakan untuk melibatkan penggunaan pestisida? Akankah kegiatan yang diusulkan akan melibatkan pemanenan atau eksploitasi sumber daya alam dalam jumlah besar seperti sumber daya kelautan dan perairan, hasil hutan kayu dan non-kayu, air tawar, dan lain-lain? SLS Apakah terdapat 7 kelompok sosial budaya di wilayah kegiatan, atau individu/kelompok yang terlibat/mendapatkan manfaat dari pelaksanaan kegiatan, yang dapat dianggap sebagai “Masyarakat Hukum Adat? Apakah terdapat anggota masyarakat dari kelompok masyarakat hukum adat di wilayah kegiatan yang akan menerima manfaat atau terkena dampak negatif dari kegiatan tersebut? Apakah terdapat individu/kelompok (terlibat/mendapatkan manfaat dari pelaksanaan kegiatan) yang menggunakan bahasa asli yang berbeda dari bahasa nasional atau bahasa yang digunakan oleh mayoritas penduduk di wilayah kegiatan? Apakah wilayah kegiatan akan berlokasi di dalam tanah/hutan adat? SLS Apakah kegiatan 8 pembangunan yang diusulkan akan dilaksanakan di kawasan yang dikenal sebagai situs cagar budaya? SLS Apakah kegiatan akan 10');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (277, '- Taman Hutan Raya Akankah kegiatan yang diusulkan akan mendatangkan jenis flora/fauna baru ke dalam suatu Kawasan? Apakah kegiatan tersebut melakukan pengadaan pestisida (baik secara langsung melalui kegiatan, atau secara tidak langsung melalui pinjaman, pembiayaan bersama, atau pendanaan mitra pemerintah), atau dapat mempengaruhi pengendalian hama dengan cara yang dapat merugikan, meskipun kegiatan tersebut tidak direncanakan untuk melibatkan penggunaan pestisida? Akankah kegiatan yang diusulkan akan melibatkan pemanenan atau eksploitasi sumber daya alam dalam jumlah besar seperti sumber daya kelautan dan perairan, hasil hutan kayu dan non-kayu, air tawar, dan lain-lain? SLS Apakah terdapat 7 kelompok sosial budaya di wilayah kegiatan, atau individu/kelompok yang terlibat/mendapatkan manfaat dari pelaksanaan kegiatan, yang dapat dianggap sebagai “Masyarakat Hukum Adat? Apakah terdapat anggota masyarakat dari kelompok masyarakat hukum adat di wilayah kegiatan yang akan menerima manfaat atau terkena dampak negatif dari kegiatan tersebut? Apakah terdapat individu/kelompok (terlibat/mendapatkan manfaat dari pelaksanaan kegiatan) yang menggunakan bahasa asli yang berbeda dari bahasa nasional atau bahasa yang digunakan oleh mayoritas penduduk di wilayah kegiatan? Apakah wilayah kegiatan akan berlokasi di dalam tanah/hutan adat? SLS Apakah kegiatan 8 pembangunan yang diusulkan akan dilaksanakan di kawasan yang dikenal sebagai situs cagar budaya? SLS Apakah kegiatan akan 10', 'LAMPIRAN I (lanjutan 10)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (278, 'juklak-2-2025', 42, 'lampiran', 'LAMPIRAN I (lanjutan 11)', NULL, 25, 'melibatkan pemangku kepentingan terkait (misalnya diskusi publik, pertemuan, peningkatan kapasitas, lokakarya, atau kegiatan relevan lainnya)? Pemohon, ttd dan stempel/TTE [… nama lengkap dan tanda tangan…] Format 3 - Rancangan Awal Rencana Komitmen Lingkungan Dan Sosial Dana Bersama Penanggulangan Bencana RANCANGAN AWAL RENCANA KOMITMEN LINGKUNGAN DAN SOSIAL DANA BERSAMA PENANGGULANGAN BENCANA [NAMA KEGIATAN], [LOKASI KEGIATAN], [TAHUN]
1. [Nama pemohon kegiatan] berkomitmen untuk mematuhi kerangka kebijakan lingkungan dan sosial yang diuraikan dalam Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana.
2. [Nama pemohon kegiatan] berkomitmen untuk melaksanakan semua tindakan yang tercantum dalam Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana. Segala implementasi tindakan sebagaimana dirincikan dalam Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana, akan dikoordinasikan, dipantau, dan dilaporkan secara cermat oleh [Nama pemohon kegiatan] kepada BNPB. Proses implementasi dan pemantauan tindakan tersebut merupakan bagian yang terintegrasi dalam rangka memastikan kinerja, kemajuan, dan penyelesaian selama pelaksanaan kegiatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (278, 'melibatkan pemangku kepentingan terkait (misalnya diskusi publik, pertemuan, peningkatan kapasitas, lokakarya, atau kegiatan relevan lainnya)? Pemohon, ttd dan stempel/TTE [… nama lengkap dan tanda tangan…] Format 3 - Rancangan Awal Rencana Komitmen Lingkungan Dan Sosial Dana Bersama Penanggulangan Bencana RANCANGAN AWAL RENCANA KOMITMEN LINGKUNGAN DAN SOSIAL DANA BERSAMA PENANGGULANGAN BENCANA [NAMA KEGIATAN], [LOKASI KEGIATAN], [TAHUN]
1. [Nama pemohon kegiatan] berkomitmen untuk mematuhi kerangka kebijakan lingkungan dan sosial yang diuraikan dalam Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana.
2. [Nama pemohon kegiatan] berkomitmen untuk melaksanakan semua tindakan yang tercantum dalam Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana. Segala implementasi tindakan sebagaimana dirincikan dalam Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana, akan dikoordinasikan, dipantau, dan dilaporkan secara cermat oleh [Nama pemohon kegiatan] kepada BNPB. Proses implementasi dan pemantauan tindakan tersebut merupakan bagian yang terintegrasi dalam rangka memastikan kinerja, kemajuan, dan penyelesaian selama pelaksanaan kegiatan.', 'LAMPIRAN I (lanjutan 11)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (279, 'juklak-2-2025', 43, 'lampiran', 'LAMPIRAN I (lanjutan 12)', NULL, 28, '3. Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana dapat direvisi oleh [Nama pemohon kegiatan] selama pelaksanaan kegiatan dalam rangka menerapkan pendekatan pengelolaan yang adaptif dan juga untuk beradaptasi terhadap perubahan, kontingensi, atau evaluasi kinerja. Setiap perkembangan atau perubahan atas kegiatan harus disetujui oleh [Nama pemohon kegiatan] dan didokumentasikan melalui surat yang ditandatangani oleh BNPB.
Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana yang diperbarui harus dipublikasikan oleh [Nama pemohon kegiatan].
4. Bilamana terjadi pemutakhiran atau modifikasi yang berkaitan dengan kegiatan, keadaan tak terduga, atau perubahan kinerja kegiatan yang menyebabkan perubahan risiko dan dampak lingkungan dan sosial selama pelaksanaan kegiatan, [Nama pemohon kegiatan] harus mengalokasikan dana tambahan (jika perlu) untuk menerapkan strategi dan langkah-langkah untuk mengurangi risiko dan dampak yang ditimbulkan. Hal ini termasuk mengidentifikasi risiko dan dampak relevan yang terkait dengan pengembangan dan/atau perubahan kegiatan.
A. KOMITMEN PEMANTAUAN DAN PELAPORAN ASPEK TINDAKAN JANGKA WAKTU PELAPORAN
(1) (2) (3) PEMANTAUAN A. PELAPORAN DAN PELAPORAN B. INSIDEN DAN KECELAKAAN Keterangan:
(1) Aspek komitmen
(2) Diisi dengan rancangan komitmen tindakan yang akan dilakukan terkait pelaporan dan insiden dan kecelakaan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (279, '3. Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana dapat direvisi oleh [Nama pemohon kegiatan] selama pelaksanaan kegiatan dalam rangka menerapkan pendekatan pengelolaan yang adaptif dan juga untuk beradaptasi terhadap perubahan, kontingensi, atau evaluasi kinerja. Setiap perkembangan atau perubahan atas kegiatan harus disetujui oleh [Nama pemohon kegiatan] dan didokumentasikan melalui surat yang ditandatangani oleh BNPB.
Rencana Komitmen Lingkungan dan Sosial Dana Bersama Penanggulangan Bencana yang diperbarui harus dipublikasikan oleh [Nama pemohon kegiatan].
4. Bilamana terjadi pemutakhiran atau modifikasi yang berkaitan dengan kegiatan, keadaan tak terduga, atau perubahan kinerja kegiatan yang menyebabkan perubahan risiko dan dampak lingkungan dan sosial selama pelaksanaan kegiatan, [Nama pemohon kegiatan] harus mengalokasikan dana tambahan (jika perlu) untuk menerapkan strategi dan langkah-langkah untuk mengurangi risiko dan dampak yang ditimbulkan. Hal ini termasuk mengidentifikasi risiko dan dampak relevan yang terkait dengan pengembangan dan/atau perubahan kegiatan.
A. KOMITMEN PEMANTAUAN DAN PELAPORAN ASPEK TINDAKAN JANGKA WAKTU PELAPORAN
(1) (2) (3) PEMANTAUAN A. PELAPORAN DAN PELAPORAN B. INSIDEN DAN KECELAKAAN Keterangan:
(1) Aspek komitmen
(2) Diisi dengan rancangan komitmen tindakan yang akan dilakukan terkait pelaporan dan insiden dan kecelakaan', 'LAMPIRAN I (lanjutan 12)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (280, 'juklak-2-2025', 44, 'lampiran', 'LAMPIRAN I (lanjutan 13)', NULL, 29, '(3) i. Aspek A. PELAPORAN diisi dengan frekuensi pelaporan, misalnya triwulanan, enam-bulanan, dan/atau tahunan selama pelaksanaan kegiatan ii. Aspek B. INSIDEN DAN KECELAKAAN diisi dengan waktu pelaporan jika terjadi insiden dan kecelakaan, misal: dalam waktu 48 jam setelah kejadian atau kecelakaan tertangani.
B. KOMITMEN TERKAIT STANDAR LINGKUNGAN DAN SOSIAL DAN PENINGKATAN KAPASITAS STANDAR LINGKUNGAN DAN SOSIAL JANGKA WAKTU TINDAKAN (SLS) PELAPORAN
(1) (2) (3) SLS 1: EVALUASI DAN 1.1. STRUKTUR Tidak Memerlukan PENGELOLAAN RISIKO ORGANISASI Laporan Berkala DAN DAMPAK 1.2. PENILAIAN LINGKUNGAN DAN LINGKUNGAN DAN SOSIAL SOSIAL SLS 2: KETENAGAKERJA 2.1. PROSEDUR AN DAN KONDISI KERJA MANAJEMEN KETENAGAKERJAAN 2.2. MEKANISME PENGADUAN BAGI PEKERJA KEGIATAN 2.3. TINDAKAN PERLINDUNGAN KESEHATAN DAN KESELAMATAN KERJA SLS 3: EFISIENSI 3.1. RENCANA SUMBER DAYA DAN PENGELOLAAN LIMBAH MANAJEMEN ELEKTRONIK PENCEGAHAN POLUSI 3.2. EFISIENSI SUMBER DAYA DAN MANAJEMEN PENCEGAHAN POLUSI SLS 4: KESEHATAN DAN 4.1. KESELAMATAN LALU KESELAMATAN LINTAS DAN JALAN MASYARAKAT 4.2. KESEHATAN DAN KESELAMATAN MASYARAKAT 4.3. KEKERASAN BERBASIS GENDER, EKSPLOITASI SEKSUAL DAN PELECEHAN SEKSUAL 4.4. PETUGAS Tidak Memerlukan KEAMANAN Laporan Berkala SLS 5: AKUISISI TANAH 5.1. RENCANA DAN PEMUKIMAN PENGADAAN TANAH & KEMBALI SECARA RENCANA PEMUKIMAN TIDAK SUKARELA KEMBALI 5.2. MEKANISME PENANGANAN KELUHAN STANDAR LINGKUNGAN DAN SOSIAL JANGKA WAKTU TINDAKAN (SLS) PELAPORAN');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (280, '(3) i. Aspek A. PELAPORAN diisi dengan frekuensi pelaporan, misalnya triwulanan, enam-bulanan, dan/atau tahunan selama pelaksanaan kegiatan ii. Aspek B. INSIDEN DAN KECELAKAAN diisi dengan waktu pelaporan jika terjadi insiden dan kecelakaan, misal: dalam waktu 48 jam setelah kejadian atau kecelakaan tertangani.
B. KOMITMEN TERKAIT STANDAR LINGKUNGAN DAN SOSIAL DAN PENINGKATAN KAPASITAS STANDAR LINGKUNGAN DAN SOSIAL JANGKA WAKTU TINDAKAN (SLS) PELAPORAN
(1) (2) (3) SLS 1: EVALUASI DAN 1.1. STRUKTUR Tidak Memerlukan PENGELOLAAN RISIKO ORGANISASI Laporan Berkala DAN DAMPAK 1.2. PENILAIAN LINGKUNGAN DAN LINGKUNGAN DAN SOSIAL SOSIAL SLS 2: KETENAGAKERJA 2.1. PROSEDUR AN DAN KONDISI KERJA MANAJEMEN KETENAGAKERJAAN 2.2. MEKANISME PENGADUAN BAGI PEKERJA KEGIATAN 2.3. TINDAKAN PERLINDUNGAN KESEHATAN DAN KESELAMATAN KERJA SLS 3: EFISIENSI 3.1. RENCANA SUMBER DAYA DAN PENGELOLAAN LIMBAH MANAJEMEN ELEKTRONIK PENCEGAHAN POLUSI 3.2. EFISIENSI SUMBER DAYA DAN MANAJEMEN PENCEGAHAN POLUSI SLS 4: KESEHATAN DAN 4.1. KESELAMATAN LALU KESELAMATAN LINTAS DAN JALAN MASYARAKAT 4.2. KESEHATAN DAN KESELAMATAN MASYARAKAT 4.3. KEKERASAN BERBASIS GENDER, EKSPLOITASI SEKSUAL DAN PELECEHAN SEKSUAL 4.4. PETUGAS Tidak Memerlukan KEAMANAN Laporan Berkala SLS 5: AKUISISI TANAH 5.1. RENCANA DAN PEMUKIMAN PENGADAAN TANAH & KEMBALI SECARA RENCANA PEMUKIMAN TIDAK SUKARELA KEMBALI 5.2. MEKANISME PENANGANAN KELUHAN STANDAR LINGKUNGAN DAN SOSIAL JANGKA WAKTU TINDAKAN (SLS) PELAPORAN', 'LAMPIRAN I (lanjutan 13)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (281, 'juklak-2-2025', 45, 'lampiran', 'LAMPIRAN I (lanjutan 14)', NULL, 30, '(1) (2) (3) SLS 6: KONSERVASI 6.1. RISIKO DAN DAMPAK KEANEKARAGAMA N KEANEKARAGAMAN HAYATI DAN HAYATI PENGELOLAAN SUMBER DAYA ALAM HIDUP BERKELANJUTAN SLS 7: MASYARAKAT 7.1. MASYARAKAT HUKUM ADAT HUKUM ADAT SLS 8: CAGAR BUDAYA 8.1 PROSEDUR PENEMUAN TAK TERDUGA SLS 10: KETERLIBATAN 10.1 PERSIAPAN DAN PEMANGKU PELAKSANAAN RENCANA KEPENTINGAN DAN KETERLIBATAN KETERBUKAAN PEMANGKU INFORMASI KEPENTINGAN 10.2 MEKANISME PENGADUAN KEGIATAN PENINGKATAN KAPASITAS BAGI PENERIMA Tidak Memerlukan MANFAAT Laporan Berkala Keterangan:
(1) Diisi sesuai dengan SLS yang terpicu pada Formulir Pelindungan Lingkungan dan Sosial
(2) Diisi dengan rancangan komitmen tindakan yang akan dilakukan sesuai rumusan Strategi Pengelolaan Dampak dan/atau Instrumen yang Dibutuhkan pada Formulir Pelindungan Lingkungan dan Sosial
(3) Diisi dengan frekuensi pelaporan, misalnya triwulanan, enam-bulanan, tahunan, dan/atau pasca pelaksanaan kegiatan Pemohon Kegiatan, ttd dan stempel / TTE (Nama dan tanda tangan) KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (281, '(1) (2) (3) SLS 6: KONSERVASI 6.1. RISIKO DAN DAMPAK KEANEKARAGAMA N KEANEKARAGAMAN HAYATI DAN HAYATI PENGELOLAAN SUMBER DAYA ALAM HIDUP BERKELANJUTAN SLS 7: MASYARAKAT 7.1. MASYARAKAT HUKUM ADAT HUKUM ADAT SLS 8: CAGAR BUDAYA 8.1 PROSEDUR PENEMUAN TAK TERDUGA SLS 10: KETERLIBATAN 10.1 PERSIAPAN DAN PEMANGKU PELAKSANAAN RENCANA KEPENTINGAN DAN KETERLIBATAN KETERBUKAAN PEMANGKU INFORMASI KEPENTINGAN 10.2 MEKANISME PENGADUAN KEGIATAN PENINGKATAN KAPASITAS BAGI PENERIMA Tidak Memerlukan MANFAAT Laporan Berkala Keterangan:
(1) Diisi sesuai dengan SLS yang terpicu pada Formulir Pelindungan Lingkungan dan Sosial
(2) Diisi dengan rancangan komitmen tindakan yang akan dilakukan sesuai rumusan Strategi Pengelolaan Dampak dan/atau Instrumen yang Dibutuhkan pada Formulir Pelindungan Lingkungan dan Sosial
(3) Diisi dengan frekuensi pelaporan, misalnya triwulanan, enam-bulanan, tahunan, dan/atau pasca pelaksanaan kegiatan Pemohon Kegiatan, ttd dan stempel / TTE (Nama dan tanda tangan) KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati', 'LAMPIRAN I (lanjutan 14)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (282, 'juklak-2-2025', 46, 'lampiran', 'LAMPIRAN II', NULL, 31, 'PETUNJUK PELAKSANAAN SISTEM PENGELOLAAN LINGKUNGAN DAN SOSIAL PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2025 DAFTAR NEGATIF Kegiatan yang termasuk dalam daftar berikut tidak mendapat dukungan pendanaan dari Dana Bersama, meliputi:
1. kegiatan yang melibatkan pembelian minuman beralkohol, produk tembakau, obat-obatan rekreasional, barang mewah sebagaimana dimaksud dalam ketentuan peraturan perundang-undangan, dan/atau barang serupa lainnya;
2. transaksi yang dilarang oleh undang-undang dan peraturan nasional serta keputusan Dewan Keamanan PBB berdasarkan Bab VII Piagam PBB;
3. terindikasi dan/atau berpotensi melanggar peraturan perundang-undangan;
4. kegiatan yang melibatkan bahan dilarang menurut peraturan internasional dan nasional termasuk namun tidak terbatas pada produksi dan/atau penggunaan produk yang mengandung material asbes dan/atau serat asbes tidak terikat;
5. kegiatan yang menunjukkan perilaku diskriminatif;
6. berpotensi melibatkan pekerja anak dan/atau kerja paksa yang tidak sesuai dengan ketentuan peraturan perundang-undangan di bidang ketenagakerjaan;
7. kegiatan berpotensi menimbulkan risiko bencana baru atau meningkatkan risiko bencana yang sudah ada;
8. kegiatan yang bertentangan dengan upaya pengurangan risiko bencana;
9. kegiatan yang diklasifikasikan sebagai kegiatan dengan tingkat risiko lingkungan dan sosial yang substansial hingga tinggi pada operasionalisasi penyaluran Dana Bersama tahap awal, meliputi:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (282, 'PETUNJUK PELAKSANAAN SISTEM PENGELOLAAN LINGKUNGAN DAN SOSIAL PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2025 DAFTAR NEGATIF Kegiatan yang termasuk dalam daftar berikut tidak mendapat dukungan pendanaan dari Dana Bersama, meliputi:
1. kegiatan yang melibatkan pembelian minuman beralkohol, produk tembakau, obat-obatan rekreasional, barang mewah sebagaimana dimaksud dalam ketentuan peraturan perundang-undangan, dan/atau barang serupa lainnya;
2. transaksi yang dilarang oleh undang-undang dan peraturan nasional serta keputusan Dewan Keamanan PBB berdasarkan Bab VII Piagam PBB;
3. terindikasi dan/atau berpotensi melanggar peraturan perundang-undangan;
4. kegiatan yang melibatkan bahan dilarang menurut peraturan internasional dan nasional termasuk namun tidak terbatas pada produksi dan/atau penggunaan produk yang mengandung material asbes dan/atau serat asbes tidak terikat;
5. kegiatan yang menunjukkan perilaku diskriminatif;
6. berpotensi melibatkan pekerja anak dan/atau kerja paksa yang tidak sesuai dengan ketentuan peraturan perundang-undangan di bidang ketenagakerjaan;
7. kegiatan berpotensi menimbulkan risiko bencana baru atau meningkatkan risiko bencana yang sudah ada;
8. kegiatan yang bertentangan dengan upaya pengurangan risiko bencana;
9. kegiatan yang diklasifikasikan sebagai kegiatan dengan tingkat risiko lingkungan dan sosial yang substansial hingga tinggi pada operasionalisasi penyaluran Dana Bersama tahap awal, meliputi:', 'LAMPIRAN II', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (283, 'juklak-2-2025', 47, 'lampiran', 'LAMPIRAN II (lanjutan 1)', NULL, 31, 'a. kegiatan yang wajib memiliki Analisis Mengenai Dampak Lingkungan (AMDAL);
b. pelaksanaan kegiatan dapat menimbulkan dampak lingkungan dan sosial yang signifikan, tidak dapat dipulihkan, dan tidak dapat diabaikan;
c. Memerlukan pembebasan lahan secara tidak sukarela/paksa baik yang mengakibatkan penggusuran/pemindahan/relokasi paksa masyarakat setempat dan/atau masyarakat hukum adat, yang mengakibatkan perubahan fisik dan/atau ekonomi/perpindahan masyarakat yang berdampak pada pembatasan atau penghentian akses masyarakat terhadap tanah dan/atau sumber daya tradisional yang merupakan sumber mata pencaharian mereka;
d. Terkait dengan pekerjaan dan pembiayaan pembangunan infrastruktur besar/pekerjaan sipil besar, pembangunan infrastruktur yang berada di perairan nasional/internasional, wilayah sengketa, dan/atau pada lahan yang tidak dapat dibuktikan status lahannya secara jelas dan bersih; dan/atau
e. terlaksananya kegiatan yang dapat menimbulkan kerugian bagi masyarakat lokal dan/atau masyarakat hukum adat, misalnya berdampak pada hak-hak adat masyarakat hukum adat dalam menggunakan dan mengakses tanah, aset dan sumber daya alam.
10. berpotensi menimbulkan atau mengakibatkan kerusakan permanen dan/atau kerusakan yang berarti/bermakna terhadap aset budaya dan cagar budaya, serta bangunan bersejarah dan/atau situs arkeologi yang tidak dapat diduplikasi dan diganti; dan/atau');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (283, 'a. kegiatan yang wajib memiliki Analisis Mengenai Dampak Lingkungan (AMDAL);
b. pelaksanaan kegiatan dapat menimbulkan dampak lingkungan dan sosial yang signifikan, tidak dapat dipulihkan, dan tidak dapat diabaikan;
c. Memerlukan pembebasan lahan secara tidak sukarela/paksa baik yang mengakibatkan penggusuran/pemindahan/relokasi paksa masyarakat setempat dan/atau masyarakat hukum adat, yang mengakibatkan perubahan fisik dan/atau ekonomi/perpindahan masyarakat yang berdampak pada pembatasan atau penghentian akses masyarakat terhadap tanah dan/atau sumber daya tradisional yang merupakan sumber mata pencaharian mereka;
d. Terkait dengan pekerjaan dan pembiayaan pembangunan infrastruktur besar/pekerjaan sipil besar, pembangunan infrastruktur yang berada di perairan nasional/internasional, wilayah sengketa, dan/atau pada lahan yang tidak dapat dibuktikan status lahannya secara jelas dan bersih; dan/atau
e. terlaksananya kegiatan yang dapat menimbulkan kerugian bagi masyarakat lokal dan/atau masyarakat hukum adat, misalnya berdampak pada hak-hak adat masyarakat hukum adat dalam menggunakan dan mengakses tanah, aset dan sumber daya alam.
10. berpotensi menimbulkan atau mengakibatkan kerusakan permanen dan/atau kerusakan yang berarti/bermakna terhadap aset budaya dan cagar budaya, serta bangunan bersejarah dan/atau situs arkeologi yang tidak dapat diduplikasi dan diganti; dan/atau', 'LAMPIRAN II (lanjutan 1)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (284, 'juklak-2-2025', 48, 'lampiran', 'LAMPIRAN II (lanjutan 2)', NULL, 32, '11. berpotensi menimbulkan kerusakan atau hilangnya keanekaragaman hayati dan habitat, khususnya spesies rentan dan terancam punah yang tercantum dalam kriteria dan kategori daftar merah sesuai dengan ketentuan peraturan perundang-undangan.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (284, '11. berpotensi menimbulkan kerusakan atau hilangnya keanekaragaman hayati dan habitat, khususnya spesies rentan dan terancam punah yang tercantum dalam kriteria dan kategori daftar merah sesuai dengan ketentuan peraturan perundang-undangan.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati', 'LAMPIRAN II (lanjutan 2)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (285, 'juklak-2-2025', 49, 'lampiran', 'LAMPIRAN III', NULL, 33, 'PETUNJUK PELAKSANAAN SISTEM PENGELOLAAN LINGKUNGAN DAN SOSIAL PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2025 KLASIFIKASI RISIKO*) Klasifikasi risiko pada Sistem Pengelolaan Lingkungan dan Sosial dilakukan untuk mengelompokkan potensi dampak yang terjadi dari kegiatan yang diajukan dengan penjelasan sebagai berikut:
1. Rendah Potensi risiko dan dampak buruk terhadap manusia dan/atau lingkungan cenderung rendah atau dapat diabaikan sehingga tidak memerlukan penilaian lingkungan dan sosial lebih lanjut setelah proses penapisan.
2. Menengah Pelaksanaan kegiatan berpotensi menimbulkan dampak negatif yang tidak signifikan terhadap manusia dan/atau lingkungan. Hal ini dikarenakan kegiatan tersebut bersifat tidak kompleks dan/atau besar, tidak melibatkan kegiatan yang berpotensi merugikan masyarakat atau lingkungan hidup, serta berlokasi jauh dari kawasan sensitif secara lingkungan atau sosial.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (285, 'PETUNJUK PELAKSANAAN SISTEM PENGELOLAAN LINGKUNGAN DAN SOSIAL PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2025 KLASIFIKASI RISIKO*) Klasifikasi risiko pada Sistem Pengelolaan Lingkungan dan Sosial dilakukan untuk mengelompokkan potensi dampak yang terjadi dari kegiatan yang diajukan dengan penjelasan sebagai berikut:
1. Rendah Potensi risiko dan dampak buruk terhadap manusia dan/atau lingkungan cenderung rendah atau dapat diabaikan sehingga tidak memerlukan penilaian lingkungan dan sosial lebih lanjut setelah proses penapisan.
2. Menengah Pelaksanaan kegiatan berpotensi menimbulkan dampak negatif yang tidak signifikan terhadap manusia dan/atau lingkungan. Hal ini dikarenakan kegiatan tersebut bersifat tidak kompleks dan/atau besar, tidak melibatkan kegiatan yang berpotensi merugikan masyarakat atau lingkungan hidup, serta berlokasi jauh dari kawasan sensitif secara lingkungan atau sosial.', 'LAMPIRAN III', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (286, 'juklak-2-2025', 50, 'lampiran', 'LAMPIRAN III (lanjutan 1)', NULL, 33, 'Selain itu, pada tingkat risiko menengah, potensi risiko, dampak, dan permasalahan yang timbul: a) dapat diprediksi dan bersifat sementara dan/atau dapat dipulihkan; b) besaran dampak bersifat rendah; c) lokasi kegiatan telah terdefinisi secara spesifik, tanpa adanya kemungkinan timbulnya dampak di luar batas kegiatan; dan d) kemungkinan terjadinya dampak terhadap kesehatan manusia dan/atau lingkungan tergolong rendah (misalnya, kegiatan tidak melibatkan penggunaan atau pembuangan bahan beracun, tindakan pencegahan keselamatan rutin diharapkan cukup untuk mencegah kecelakaan, dll.).
Risiko dan dampak kegiatan dapat dengan mudah dimitigasi dengan cara yang dapat diprediksi.
3. Substansial Kegiatan tidak berada pada area yang sangat sensitif secara lingkungan dan sosial, namun berpotensi menimbulkan tingkat risiko yang signifikan dengan karakteristik: a) sebagian besar risiko yang ditimbulkan bersifat sementara, dapat diprediksi, dapat dipulihkan, dan dapat dihindari; b) berpotensi menimbulkan dampak sosial yang merugikan dan berpotensi dapat menimbulkan konflik sosial, bahaya, atau risiko terhadap keamanan manusia dalam tingkat yang terbatas; c) besaran dan skala sebaran potensi dampak bersifat menengah; d) risiko terhadap kesehatan manusia dan/atau lingkungan bersifat rendah hingga menengah (misalnya karena kecelakaan, pembuangan limbah beracun, dll.), dan terdapat mekanisme yang diketahui dan dapat diandalkan untuk mencegah atau meminimalkan risiko tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (286, 'Selain itu, pada tingkat risiko menengah, potensi risiko, dampak, dan permasalahan yang timbul: a) dapat diprediksi dan bersifat sementara dan/atau dapat dipulihkan; b) besaran dampak bersifat rendah; c) lokasi kegiatan telah terdefinisi secara spesifik, tanpa adanya kemungkinan timbulnya dampak di luar batas kegiatan; dan d) kemungkinan terjadinya dampak terhadap kesehatan manusia dan/atau lingkungan tergolong rendah (misalnya, kegiatan tidak melibatkan penggunaan atau pembuangan bahan beracun, tindakan pencegahan keselamatan rutin diharapkan cukup untuk mencegah kecelakaan, dll.).
Risiko dan dampak kegiatan dapat dengan mudah dimitigasi dengan cara yang dapat diprediksi.
3. Substansial Kegiatan tidak berada pada area yang sangat sensitif secara lingkungan dan sosial, namun berpotensi menimbulkan tingkat risiko yang signifikan dengan karakteristik: a) sebagian besar risiko yang ditimbulkan bersifat sementara, dapat diprediksi, dapat dipulihkan, dan dapat dihindari; b) berpotensi menimbulkan dampak sosial yang merugikan dan berpotensi dapat menimbulkan konflik sosial, bahaya, atau risiko terhadap keamanan manusia dalam tingkat yang terbatas; c) besaran dan skala sebaran potensi dampak bersifat menengah; d) risiko terhadap kesehatan manusia dan/atau lingkungan bersifat rendah hingga menengah (misalnya karena kecelakaan, pembuangan limbah beracun, dll.), dan terdapat mekanisme yang diketahui dan dapat diandalkan untuk mencegah atau meminimalkan risiko tersebut.', 'LAMPIRAN III (lanjutan 1)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (287, 'juklak-2-2025', 51, 'lampiran', 'LAMPIRAN III (lanjutan 2)', NULL, 33, 'Langkah-langkah mitigasi dan/atau kompensasi dapat direncanakan dengan lebih mudah dan dapat diandalkan dibandingkan dengan kegiatan dengan tingkat risiko Tinggi.
4. Tinggi Berpotensi menimbulkan berbagai risiko merugikan yang signifikan terhadap manusia atau lingkungan yang: a) bersifat jangka panjang, permanen dan/atau tidak dapat diubah dan tidak mungkin dihindari seluruhnya karena perencanaan, pelaksanaan, atau pasca pelaksanaan kegiatan; b) besaran dampak dan/atau jangkauan spasial yang luas; c) dampak kumulatif merugikan yang signifikan tak dapat diterapkan; dan d) kemungkinan yang tinggi atas terjadinya dampak negatif yang serius terhadap kesehatan manusia dan/atau lingkungan (misalnya akibat kecelakaan, pembuangan limbah beracun, dll.) Langkah-langkah mitigasi dan/atau kompensasi direncanakan dengan pelibatan multipihak dan pelaksanaannya sesuai ketentuan peraturan perundang-undangan. *) untuk sistem pengelolaan lingkungan dan sosial tahap awal, kegiatan yang diakomodir hanya kegiatan dengan risiko lingkungan dan sosial rendah dan menengah.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (287, 'Langkah-langkah mitigasi dan/atau kompensasi dapat direncanakan dengan lebih mudah dan dapat diandalkan dibandingkan dengan kegiatan dengan tingkat risiko Tinggi.
4. Tinggi Berpotensi menimbulkan berbagai risiko merugikan yang signifikan terhadap manusia atau lingkungan yang: a) bersifat jangka panjang, permanen dan/atau tidak dapat diubah dan tidak mungkin dihindari seluruhnya karena perencanaan, pelaksanaan, atau pasca pelaksanaan kegiatan; b) besaran dampak dan/atau jangkauan spasial yang luas; c) dampak kumulatif merugikan yang signifikan tak dapat diterapkan; dan d) kemungkinan yang tinggi atas terjadinya dampak negatif yang serius terhadap kesehatan manusia dan/atau lingkungan (misalnya akibat kecelakaan, pembuangan limbah beracun, dll.) Langkah-langkah mitigasi dan/atau kompensasi direncanakan dengan pelibatan multipihak dan pelaksanaannya sesuai ketentuan peraturan perundang-undangan. *) untuk sistem pengelolaan lingkungan dan sosial tahap awal, kegiatan yang diakomodir hanya kegiatan dengan risiko lingkungan dan sosial rendah dan menengah.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati', 'LAMPIRAN III (lanjutan 2)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (288, 'juklak-2-2025', 52, 'lampiran', 'LAMPIRAN IV', NULL, 35, 'PETUNJUK PELAKSANAAN SISTEM PENGELOLAAN LINGKUNGAN DAN SOSIAL PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2025 STANDAR LINGKUNGAN DAN SOSIAL Standar Lingkungan dan Sosial dalam penyaluran Dana Bersama merupakan standar untuk menghindari, meminimalkan, mengurangi, atau memitigasi risiko dan dampak yang merugikan terhadap lingkungan dan sosial atas pelaksanaan penyaluran Dana Bersama dan pelaksanaan kegiatan yang berpotensi mendapat dukungan pendanaan tersebut. Terdapat 10 (sepuluh) SLS dalam penyaluran Dana Bersama, namun terdapat 1 (satu) SLS yang tidak digunakan dalam dokumen pengelolaan lingkungan dan sosial untuk permohonan penyaluran Dana Bersama tahap prabencana, yaitu SLS 9 – Perantara Keuangan. Penjelasan masing-masing SLS sebagai berikut:
1. SLS 1 – Penilaian dan Pengelolaan Risiko dan Dampak Lingkungan dan Sosial Standar ini menekankan tanggung jawab pemohon kegiatan untuk menilai, mengelola, dan memantau risiko dan dampak lingkungan dan sosial yang terkait dengan penyaluran Dana Bersama dan pelaksanaan kegiatan yang mendapat dukungan pendanaan tersebut, untuk mencapai kinerja pengelolaan lingkungan dan sosial yang sesuai dengan Standar Lingkungan dan Sosial pada kegiatan Dana Bersama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (288, 'PETUNJUK PELAKSANAAN SISTEM PENGELOLAAN LINGKUNGAN DAN SOSIAL PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2025 STANDAR LINGKUNGAN DAN SOSIAL Standar Lingkungan dan Sosial dalam penyaluran Dana Bersama merupakan standar untuk menghindari, meminimalkan, mengurangi, atau memitigasi risiko dan dampak yang merugikan terhadap lingkungan dan sosial atas pelaksanaan penyaluran Dana Bersama dan pelaksanaan kegiatan yang berpotensi mendapat dukungan pendanaan tersebut. Terdapat 10 (sepuluh) SLS dalam penyaluran Dana Bersama, namun terdapat 1 (satu) SLS yang tidak digunakan dalam dokumen pengelolaan lingkungan dan sosial untuk permohonan penyaluran Dana Bersama tahap prabencana, yaitu SLS 9 – Perantara Keuangan. Penjelasan masing-masing SLS sebagai berikut:
1. SLS 1 – Penilaian dan Pengelolaan Risiko dan Dampak Lingkungan dan Sosial Standar ini menekankan tanggung jawab pemohon kegiatan untuk menilai, mengelola, dan memantau risiko dan dampak lingkungan dan sosial yang terkait dengan penyaluran Dana Bersama dan pelaksanaan kegiatan yang mendapat dukungan pendanaan tersebut, untuk mencapai kinerja pengelolaan lingkungan dan sosial yang sesuai dengan Standar Lingkungan dan Sosial pada kegiatan Dana Bersama.', 'LAMPIRAN IV', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (289, 'juklak-2-2025', 53, 'lampiran', 'LAMPIRAN IV (lanjutan 1)', NULL, 35, '2. SLS 2 – Kondisi Ketenagakerjaan dan Lingkungan Kerja Standar ini mendorong penciptaan lapangan kerja dan peningkatan pendapatan dalam upaya pengentasan kemiskinan dan pertumbuhan ekonomi inklusif. Penyaluran Dana Bersama dan pelaksanaan kegiatan yang mendapat dukungan pendanaan tersebut harus meningkatkan hubungan baik antara pekerja dengan manajemen kunci dan meningkatkan manfaat pembangunan suatu kegiatan dengan memperlakukan pekerja yang terlibat dalam kegiatan secara adil dan menyediakan kondisi kerja yang aman dan sehat.
3. SLS 3 – Efisiensi Sumber Daya dan Pencegahan dan Pengelolaan Polusi Standar ini mendorong terwujudnya lingkungan yang berkelanjutan atas pelaksanaan kegiatan dengan memperhatikan potensi risiko dan dampak lingkungan yang ditimbukan seperti peningkatan polusi udara, air, dan tanah, serta eksploitasi atas sumber daya yang dapat menimbulkan dampak negatif bagi manusia, ekosistem, dan lingkungan hidup baik pada tingkat lokal, regional, maupun global, termasuk didalamnya peningkatan konsentrasi gas rumah kaca (GRK).
4. SLS 4 – Kesehatan dan Keselamatan Masyarakat Standar ini menjelaskan bahwa pelaksanaan kegiatan, peralatan, dan infrastruktur dapat meningkatkan keterpaparan masyarakat terhadap risiko dan dampak. Selain itu, masyarakat yang sudah terkena dampak dari perubahan iklim juga dapat mengalami percepatan atau intensifikasi dampak akibat pelaksanaan kegiatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (289, '2. SLS 2 – Kondisi Ketenagakerjaan dan Lingkungan Kerja Standar ini mendorong penciptaan lapangan kerja dan peningkatan pendapatan dalam upaya pengentasan kemiskinan dan pertumbuhan ekonomi inklusif. Penyaluran Dana Bersama dan pelaksanaan kegiatan yang mendapat dukungan pendanaan tersebut harus meningkatkan hubungan baik antara pekerja dengan manajemen kunci dan meningkatkan manfaat pembangunan suatu kegiatan dengan memperlakukan pekerja yang terlibat dalam kegiatan secara adil dan menyediakan kondisi kerja yang aman dan sehat.
3. SLS 3 – Efisiensi Sumber Daya dan Pencegahan dan Pengelolaan Polusi Standar ini mendorong terwujudnya lingkungan yang berkelanjutan atas pelaksanaan kegiatan dengan memperhatikan potensi risiko dan dampak lingkungan yang ditimbukan seperti peningkatan polusi udara, air, dan tanah, serta eksploitasi atas sumber daya yang dapat menimbulkan dampak negatif bagi manusia, ekosistem, dan lingkungan hidup baik pada tingkat lokal, regional, maupun global, termasuk didalamnya peningkatan konsentrasi gas rumah kaca (GRK).
4. SLS 4 – Kesehatan dan Keselamatan Masyarakat Standar ini menjelaskan bahwa pelaksanaan kegiatan, peralatan, dan infrastruktur dapat meningkatkan keterpaparan masyarakat terhadap risiko dan dampak. Selain itu, masyarakat yang sudah terkena dampak dari perubahan iklim juga dapat mengalami percepatan atau intensifikasi dampak akibat pelaksanaan kegiatan.', 'LAMPIRAN IV (lanjutan 1)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (290, 'juklak-2-2025', 54, 'lampiran', 'LAMPIRAN IV (lanjutan 2)', NULL, 35, '5. SLS 5 – Pembebasan Lahan, Pembatasan Penggunaan Lahan dan Pemukiman Kembali Secara Tidak Sukarela Standar ini menekankan bahwa pengadaan tanah, pemukiman kembali, dan pembatasan penggunaan lahan terkait dengan penyelenggaraan kegiatan dapat menimbulkan dampak buruk terhadap individu dan masyarakat. Pembebasan lahan pemukiman kembali, atau pembatasan penggunaan lahan ini dapat menyebabkan perpindahan fisik (relokasi, hilangnya lahan pemukiman, atau hilangnya tempat berlindung), perpindahan ekonomi (kehilangan lahan, kehilangan aset selain lahan, atau kehilangan akses terhadap aset yang mengakibatkan hilangnya sumber pendapatan atau hal-hal lain sarana penghidupan), atau keduanya. Istilah “pemukiman kembali secara tidak sukarela” mengacu pada dampak-dampak tersebut. Pemukiman kembali dianggap tidak sukarela ketika orang atau masyarakat yang terkena dampak tidak mempunyai hak untuk menolak pembebasan lahan atau pembatasan penggunaan lahan yang mengakibatkan pengungsian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (290, '5. SLS 5 – Pembebasan Lahan, Pembatasan Penggunaan Lahan dan Pemukiman Kembali Secara Tidak Sukarela Standar ini menekankan bahwa pengadaan tanah, pemukiman kembali, dan pembatasan penggunaan lahan terkait dengan penyelenggaraan kegiatan dapat menimbulkan dampak buruk terhadap individu dan masyarakat. Pembebasan lahan pemukiman kembali, atau pembatasan penggunaan lahan ini dapat menyebabkan perpindahan fisik (relokasi, hilangnya lahan pemukiman, atau hilangnya tempat berlindung), perpindahan ekonomi (kehilangan lahan, kehilangan aset selain lahan, atau kehilangan akses terhadap aset yang mengakibatkan hilangnya sumber pendapatan atau hal-hal lain sarana penghidupan), atau keduanya. Istilah “pemukiman kembali secara tidak sukarela” mengacu pada dampak-dampak tersebut. Pemukiman kembali dianggap tidak sukarela ketika orang atau masyarakat yang terkena dampak tidak mempunyai hak untuk menolak pembebasan lahan atau pembatasan penggunaan lahan yang mengakibatkan pengungsian.', 'LAMPIRAN IV (lanjutan 2)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (291, 'juklak-2-2025', 55, 'lampiran', 'LAMPIRAN IV (lanjutan 3)', NULL, 36, '6. SLS 6 – Konservasi Keanekaragaman Hayati dan Pengelolaan Sumber Daya Alam Hayati yang Berkelanjutan Standar ini menekankan bahwa melindungi dan melestarikan keanekaragaman hayati dan mengelola sumber daya alam hayati secara berkelanjutan merupakan hal mendasar dalam pembangunan berkelanjutan. Keanekaragaman hayati didefinisikan sebagai keragaman organisme hidup dari semua sumber termasuk, antara lain, ekosistem darat, laut, dan perairan lainnya serta kompleks ekologi di mana organisme tersebut menjadi bagiannya; hal ini mencakup keanekaragaman dalam spesies, antar spesies, dan ekosistem. Keanekaragaman hayati sering kali mendasari jasa ekosistem yang bernilai bagi manusia. Oleh karena itu, dampak terhadap keanekaragaman hayati sering kali berdampak buruk terhadap penyediaan jasa ekosistem.
7. SLS 7 – Masyarakat Hukum Adat Standar ini berkontribusi pada pembangunan berkelanjutan dengan memastikan bahwa kegiatan yang didukung oleh Dana Bersama meningkatkan peluang bagi masyarakat hukum adat untuk berpartisipasi dan mendapatkan manfaat dari proses pelaksanaan kegiatan dengan cara yang tidak mengancam identitas budaya dan kesejahteraan mereka yang unik. SLS ini terbatas pada masyarakat hukum adat dengan penghormatan terhadap masyarakat hukum adat atau masyarakat yang mempunyai keterikatan kolektif pada wilayah kegiatan yang diusulkan, sebagaimana ditentukan selama penilaian lingkungan dan sosial.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (291, '6. SLS 6 – Konservasi Keanekaragaman Hayati dan Pengelolaan Sumber Daya Alam Hayati yang Berkelanjutan Standar ini menekankan bahwa melindungi dan melestarikan keanekaragaman hayati dan mengelola sumber daya alam hayati secara berkelanjutan merupakan hal mendasar dalam pembangunan berkelanjutan. Keanekaragaman hayati didefinisikan sebagai keragaman organisme hidup dari semua sumber termasuk, antara lain, ekosistem darat, laut, dan perairan lainnya serta kompleks ekologi di mana organisme tersebut menjadi bagiannya; hal ini mencakup keanekaragaman dalam spesies, antar spesies, dan ekosistem. Keanekaragaman hayati sering kali mendasari jasa ekosistem yang bernilai bagi manusia. Oleh karena itu, dampak terhadap keanekaragaman hayati sering kali berdampak buruk terhadap penyediaan jasa ekosistem.
7. SLS 7 – Masyarakat Hukum Adat Standar ini berkontribusi pada pembangunan berkelanjutan dengan memastikan bahwa kegiatan yang didukung oleh Dana Bersama meningkatkan peluang bagi masyarakat hukum adat untuk berpartisipasi dan mendapatkan manfaat dari proses pelaksanaan kegiatan dengan cara yang tidak mengancam identitas budaya dan kesejahteraan mereka yang unik. SLS ini terbatas pada masyarakat hukum adat dengan penghormatan terhadap masyarakat hukum adat atau masyarakat yang mempunyai keterikatan kolektif pada wilayah kegiatan yang diusulkan, sebagaimana ditentukan selama penilaian lingkungan dan sosial.', 'LAMPIRAN IV (lanjutan 3)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (292, 'juklak-2-2025', 56, 'lampiran', 'LAMPIRAN IV (lanjutan 4)', NULL, 36, '8. SLS 8 – Cagar Budaya Standar ini menekankan bahwa cagar budaya memberikan kesinambungan dalam benda dan tak benda antara masa lalu, masa kini, dan masa depan.
Masyarakat mengidentifikasi cagar budaya sebagai cerminan dan ekspresi nilai-nilai, kepercayaan, pengetahuan, dan tradisi mereka yang terus berkembang. Cagar budaya, dalam berbagai manifestasinya, penting sebagai sumber informasi ilmiah dan sejarah yang berharga, sebagai aset ekonomi dan sosial untuk pembangunan, dan sebagai bagian integral dari identitas dan praktik budaya masyarakat.
9. SLS 10 – Keterlibatan Pemangku Kepentingan dan Keterbukaan Informasi Pentingnya keterlibatan para pihak yang berperan dalam penyaluran Dana Bersama secara terbuka dan transparan. Keterlibatan pemangku kepentingan yang efektif dapat meningkatkan keberlanjutan pelindungan lingkungan dan sosial kegiatan, meningkatkan penerimaan terhadap kegiatan, dan memberikan kontribusi yang signifikan terhadap keberhasilan perencanaan kegiatan tersebut.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (292, '8. SLS 8 – Cagar Budaya Standar ini menekankan bahwa cagar budaya memberikan kesinambungan dalam benda dan tak benda antara masa lalu, masa kini, dan masa depan.
Masyarakat mengidentifikasi cagar budaya sebagai cerminan dan ekspresi nilai-nilai, kepercayaan, pengetahuan, dan tradisi mereka yang terus berkembang. Cagar budaya, dalam berbagai manifestasinya, penting sebagai sumber informasi ilmiah dan sejarah yang berharga, sebagai aset ekonomi dan sosial untuk pembangunan, dan sebagai bagian integral dari identitas dan praktik budaya masyarakat.
9. SLS 10 – Keterlibatan Pemangku Kepentingan dan Keterbukaan Informasi Pentingnya keterlibatan para pihak yang berperan dalam penyaluran Dana Bersama secara terbuka dan transparan. Keterlibatan pemangku kepentingan yang efektif dapat meningkatkan keberlanjutan pelindungan lingkungan dan sosial kegiatan, meningkatkan penerimaan terhadap kegiatan, dan memberikan kontribusi yang signifikan terhadap keberhasilan perencanaan kegiatan tersebut.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati', 'LAMPIRAN IV (lanjutan 4)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (293, 'juklak-2-2025', 57, 'lampiran', 'LAMPIRAN V', NULL, 38, 'PETUNJUK PELAKSANAAN SISTEM PENGELOLAAN LINGKUNGAN DAN SOSIAL PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2025 INSTRUMEN LINGKUNGAN DAN SOSIAL No. Klasifikasi SLS yang Instrumen Lingkungan dan Sosial Strategi Pengelolaan Tingkat Terpicu Bentuk Deskripsi Lingkungan dan Sosial Risiko Instrumen (Contoh)
1. Rendah Semua standar Surat Pernyataan SPPL adalah pernyataan kesediaan 1. Menetapkan struktur lingkungan Persetujuan tentang penanggung jawab kegiatan atau pemohon organisasi dan penunjukan dan sosial yang Pengelolaan dan kegiatan untuk melakukan pengelolaan pejabat/pegawai untuk relevan Pemantauan lingkungan dan sosial serta pemantauan mendukung implementasi sebagaimana Lingkungan Hidup potensi dampak lingkungan dan sosial selama manajemen risiko ditentukan (SPPL) pelaksanaan program/kegiatan yang tidak lingkungan dan sosial; dalam proses wajib didukung oleh AMDAL atau dokumen 2. Menetapkan persyaratan penapisan. UKL-UPL. Penyusunan dokumen SPPL bagi pelaksana kegiatan mengacu pada Lampiran III Peraturan untuk menilai potensi Pemerintah Nomor 22 Tahun 2021 tentang dampak dan menyiapkan Penyelenggaraan Pengamanan dan Pengelolaan rencana pengelolaan dan Lingkungan Hidup. pemantauan lingkungan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (293, 'PETUNJUK PELAKSANAAN SISTEM PENGELOLAAN LINGKUNGAN DAN SOSIAL PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2025 INSTRUMEN LINGKUNGAN DAN SOSIAL No. Klasifikasi SLS yang Instrumen Lingkungan dan Sosial Strategi Pengelolaan Tingkat Terpicu Bentuk Deskripsi Lingkungan dan Sosial Risiko Instrumen (Contoh)
1. Rendah Semua standar Surat Pernyataan SPPL adalah pernyataan kesediaan 1. Menetapkan struktur lingkungan Persetujuan tentang penanggung jawab kegiatan atau pemohon organisasi dan penunjukan dan sosial yang Pengelolaan dan kegiatan untuk melakukan pengelolaan pejabat/pegawai untuk relevan Pemantauan lingkungan dan sosial serta pemantauan mendukung implementasi sebagaimana Lingkungan Hidup potensi dampak lingkungan dan sosial selama manajemen risiko ditentukan (SPPL) pelaksanaan program/kegiatan yang tidak lingkungan dan sosial; dalam proses wajib didukung oleh AMDAL atau dokumen 2. Menetapkan persyaratan penapisan. UKL-UPL. Penyusunan dokumen SPPL bagi pelaksana kegiatan mengacu pada Lampiran III Peraturan untuk menilai potensi Pemerintah Nomor 22 Tahun 2021 tentang dampak dan menyiapkan Penyelenggaraan Pengamanan dan Pengelolaan rencana pengelolaan dan Lingkungan Hidup. pemantauan lingkungan', 'LAMPIRAN V', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (294, 'juklak-2-2025', 58, 'lampiran', 'LAMPIRAN V (lanjutan 1)', NULL, 38, '2. Rendah - Prinsip Kode Praktik Rencana pengelolaan lingkungan dan sosial ini dan sosial; dan Menengah Pelindungan Lingkungan dan berlaku untuk usulan kegiatan yang diajukan 3. Melaksanakan pengelolaan Lingkungan Sosial/ESCOPs oleh pemohon kegiatan dengan tingkat risiko lingkungan dan sosial serta dan Sosial rendah. pemantauan potensi yang Dipicu dampak lingkungan dan sosial selama pelaksanaan program/kegiatan sesuai SPPL dan/atau Kode Praktik Lingkungan dan Sosial/ESCOPs
4. Melaksanakan langkah-langkah efisiensi sumber daya, pencegahan dan No. Klasifikasi SLS yang Instrumen Lingkungan dan Sosial Strategi Pengelolaan Tingkat Terpicu Bentuk Deskripsi Lingkungan dan Sosial Risiko Instrumen (Contoh) pengelolaan polusi sesuai Kode Praktik Lingkungan dan Sosial (ESCOPs)/SPPL/UKL-UPL.
3. Rendah - SLS 1 Rencana Rencana pengelolaan dan pemantauan sosial Melaksanakan pengelolaan Menengah Pengelolaan dan dan gender merupakan dokumen yang dan pemantauan dampak Pemantauan disiapkan untuk merespons potensi dampak sosial dan gender.
Dampak Sosial dan yang muncul dalam studi penilaian dampak Gender lingkungan dan sosial. Dokumen ini memuat langkah-langkah mitigasi dampak berdasarkan hierarki mitigasi dan strategi pemantauan kinerja pengelolaan dampak serta signifikansi dampak. Dokumen rencana pengelolaan dan pemantauan dampak sosial dan gender dapat dimasukkan dalam atau terpisah dari dokumen ESMP.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (294, '2. Rendah - Prinsip Kode Praktik Rencana pengelolaan lingkungan dan sosial ini dan sosial; dan Menengah Pelindungan Lingkungan dan berlaku untuk usulan kegiatan yang diajukan 3. Melaksanakan pengelolaan Lingkungan Sosial/ESCOPs oleh pemohon kegiatan dengan tingkat risiko lingkungan dan sosial serta dan Sosial rendah. pemantauan potensi yang Dipicu dampak lingkungan dan sosial selama pelaksanaan program/kegiatan sesuai SPPL dan/atau Kode Praktik Lingkungan dan Sosial/ESCOPs
4. Melaksanakan langkah-langkah efisiensi sumber daya, pencegahan dan No. Klasifikasi SLS yang Instrumen Lingkungan dan Sosial Strategi Pengelolaan Tingkat Terpicu Bentuk Deskripsi Lingkungan dan Sosial Risiko Instrumen (Contoh) pengelolaan polusi sesuai Kode Praktik Lingkungan dan Sosial (ESCOPs)/SPPL/UKL-UPL.
3. Rendah - SLS 1 Rencana Rencana pengelolaan dan pemantauan sosial Melaksanakan pengelolaan Menengah Pengelolaan dan dan gender merupakan dokumen yang dan pemantauan dampak Pemantauan disiapkan untuk merespons potensi dampak sosial dan gender.
Dampak Sosial dan yang muncul dalam studi penilaian dampak Gender lingkungan dan sosial. Dokumen ini memuat langkah-langkah mitigasi dampak berdasarkan hierarki mitigasi dan strategi pemantauan kinerja pengelolaan dampak serta signifikansi dampak. Dokumen rencana pengelolaan dan pemantauan dampak sosial dan gender dapat dimasukkan dalam atau terpisah dari dokumen ESMP.', 'LAMPIRAN V (lanjutan 1)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (295, 'juklak-2-2025', 59, 'lampiran', 'LAMPIRAN V (lanjutan 2)', NULL, 39, '4. Menengah Semua standar Upaya Pengelolaan UKL-UPL merupakan serangkaian proses 1. Menetapkan struktur lingkungan Lingkungan Hidup penilaian untuk menentukan strategi organisasi dan dan sosial yang dan Upaya pengelolaan dan pemantauan lingkungan dan penunjukan relevan Pemantauan sosial yang dirumuskan dalam dokumen pejabat/pegawai untuk sebagaimana Lingkungan Hidup formal. Dokumen UKL-UPL merupakan mendukung implementasi ditentukan (UKL- UPL) prasyarat dalam pengambilan keputusan manajemen risiko dalam proses dalam pemberian izin usaha, atau persetujuan lingkungan dan sosial; penapisan dari Pemerintah Pusat atau Pemerintah 2. Menetapkan persyaratan dampak Daerah. Ketentuan penyusunan dokumen bagi pelaksana kegiatan lingkungan dan UKL-UPL mengacu pada Peraturan Pemerintah untuk menilai potensi sosial. Nomor 22 Tahun 2021 tentang dampak dan menyiapkan Penyelenggaraan Pengamanan dan Pengelolaan rencana pengelolaan dan Lingkungan Hidup dalam format UKL- UPL, pemantan lingkungan dan Lampiran III. sosial; dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (295, '4. Menengah Semua standar Upaya Pengelolaan UKL-UPL merupakan serangkaian proses 1. Menetapkan struktur lingkungan Lingkungan Hidup penilaian untuk menentukan strategi organisasi dan dan sosial yang dan Upaya pengelolaan dan pemantauan lingkungan dan penunjukan relevan Pemantauan sosial yang dirumuskan dalam dokumen pejabat/pegawai untuk sebagaimana Lingkungan Hidup formal. Dokumen UKL-UPL merupakan mendukung implementasi ditentukan (UKL- UPL) prasyarat dalam pengambilan keputusan manajemen risiko dalam proses dalam pemberian izin usaha, atau persetujuan lingkungan dan sosial; penapisan dari Pemerintah Pusat atau Pemerintah 2. Menetapkan persyaratan dampak Daerah. Ketentuan penyusunan dokumen bagi pelaksana kegiatan lingkungan dan UKL-UPL mengacu pada Peraturan Pemerintah untuk menilai potensi sosial. Nomor 22 Tahun 2021 tentang dampak dan menyiapkan Penyelenggaraan Pengamanan dan Pengelolaan rencana pengelolaan dan Lingkungan Hidup dalam format UKL- UPL, pemantan lingkungan dan Lampiran III. sosial; dan', 'LAMPIRAN V (lanjutan 2)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (296, 'juklak-2-2025', 60, 'lampiran', 'LAMPIRAN V (lanjutan 3)', NULL, 39, '5. Menengah Memicu Rencana ESMP merupakan upaya untuk menangani 3. Melaksanakan strategi standar Pengelolaan dampak lingkungan dan sosial akibat kegiatan pengelolaan lingkungan lingkungan Lingkungan dan dan/atau kegiatan yang direncanakan. ESMP dan sosial serta No. Klasifikasi SLS yang Instrumen Lingkungan dan Sosial Strategi Pengelolaan Tingkat Terpicu Bentuk Deskripsi Lingkungan dan Sosial Risiko Instrumen (Contoh) dan sosial Sosial disusun dengan mengacu pada hasil penilaian pemantauan potensi berdasarkan (Environmental and dampak lingkungan dan sosial serta langkah dampak lingkungan dan hasil Social Management mitigasi yang ditentukan. sosial selama pelaksanaan penyaringan Plan/ESMP) program/kegiatan sesuai dan hasil UKL-UPL dan/atau ESMP. penilaian dampak lingkungan dan sosial.
