INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (298, 'juklak-2-2025', 62, 'lampiran', 'LAMPIRAN V (lanjutan 5)', NULL, 40, 'Pemantauan ▪ Berdasarkan hasil analisis kesenjangan Ketenagakerjaan antara dokumen terkait ketenagakerjaan dan Kondisi Kerja dan kondisi kerja yang diberikan oleh No. Klasifikasi SLS yang Instrumen Lingkungan dan Sosial Strategi Pengelolaan Tingkat Terpicu Bentuk Deskripsi Lingkungan dan Sosial Risiko Instrumen (Contoh) pemohon kegiatan (seperti kebijakan/ketentuan terkait sumber daya manusia dan kebijakan/ketentuan/ dokumen lainnya). SLS 2 mengharuskan studi ini diselesaikan untuk tingkat risiko menengah hingga tinggi; dan/atau ▪ Hasil studi penilaian dampak terhadap ketenagakerjaan dan kondisi kerja mengidentifikasi persyaratan pengelolaan ketenagakerjaan dan kondisi kerja untuk memenuhi persyaratan dalam SLS 2 untuk tingkat risiko menengah hingga tinggi dan mencegah dampak negatif terhadap lingkungan dan sosial dari pelaksanaan kegiatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (298, 'Pemantauan ▪ Berdasarkan hasil analisis kesenjangan Ketenagakerjaan antara dokumen terkait ketenagakerjaan dan Kondisi Kerja dan kondisi kerja yang diberikan oleh No. Klasifikasi SLS yang Instrumen Lingkungan dan Sosial Strategi Pengelolaan Tingkat Terpicu Bentuk Deskripsi Lingkungan dan Sosial Risiko Instrumen (Contoh) pemohon kegiatan (seperti kebijakan/ketentuan terkait sumber daya manusia dan kebijakan/ketentuan/ dokumen lainnya). SLS 2 mengharuskan studi ini diselesaikan untuk tingkat risiko menengah hingga tinggi; dan/atau ▪ Hasil studi penilaian dampak terhadap ketenagakerjaan dan kondisi kerja mengidentifikasi persyaratan pengelolaan ketenagakerjaan dan kondisi kerja untuk memenuhi persyaratan dalam SLS 2 untuk tingkat risiko menengah hingga tinggi dan mencegah dampak negatif terhadap lingkungan dan sosial dari pelaksanaan kegiatan.', 'LAMPIRAN V (lanjutan 5)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (299, 'juklak-2-2025', 63, 'lampiran', 'LAMPIRAN V (lanjutan 6)', NULL, 41, '8. Menengah SLS 2, 3 dan 4. Penilaian Bahaya Penilaian Bahaya dan Risiko merupakan 1. Menyiapkan, mengadopsi, dan Risiko instrumen untuk mengidentifikasi, dan menerapkan langkah-menganalisa dan mengendalikan material dan langkah pengendalian kondisi yang berbahaya dan/atau berisiko material dan kondisi yang terhadap kesehatan dan keselamatan di lokasi berbahaya dan/atau kegiatan. Pemohon kegiatan dipersyaratkan berisiko terhadap untuk melaporkan volume dan rencana kesehatan dan penggunaan bahan-bahan yang mudah keselamatan tenaga kerja; terbakar, mudah meledak, reaktif, berbahaya 2. Menyiapkan, mengadopsi, dan beracun. Penilaian Bahaya dan Risiko dan menerapkan Rencana dapat menjadi bagian dari dokumen penilaian Pengelolaan Limbah dampak lingkungan dan sosial atau dokumen Elektronik; terpisah. 3. Melaksanakan langkah-langkah efisiensi sumber daya, pencegahan dan pengelolaan polusi sesuai Kode Praktik Lingkungan dan Sosial No. Klasifikasi SLS yang Instrumen Lingkungan dan Sosial Strategi Pengelolaan Tingkat Terpicu Bentuk Deskripsi Lingkungan dan Sosial Risiko Instrumen (Contoh) (ESCOPs)/SPPL/UKL-UPL; dan/atau
4. Mengembangkan dan menerapkan tindakan untuk menilai memitigasi dampak terhadap kesehatan dan keselamatan masyarakat sesuai penilaian bahaya dan risiko.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (299, '8. Menengah SLS 2, 3 dan 4. Penilaian Bahaya Penilaian Bahaya dan Risiko merupakan 1. Menyiapkan, mengadopsi, dan Risiko instrumen untuk mengidentifikasi, dan menerapkan langkah-menganalisa dan mengendalikan material dan langkah pengendalian kondisi yang berbahaya dan/atau berisiko material dan kondisi yang terhadap kesehatan dan keselamatan di lokasi berbahaya dan/atau kegiatan. Pemohon kegiatan dipersyaratkan berisiko terhadap untuk melaporkan volume dan rencana kesehatan dan penggunaan bahan-bahan yang mudah keselamatan tenaga kerja; terbakar, mudah meledak, reaktif, berbahaya 2. Menyiapkan, mengadopsi, dan beracun. Penilaian Bahaya dan Risiko dan menerapkan Rencana dapat menjadi bagian dari dokumen penilaian Pengelolaan Limbah dampak lingkungan dan sosial atau dokumen Elektronik; terpisah. 3. Melaksanakan langkah-langkah efisiensi sumber daya, pencegahan dan pengelolaan polusi sesuai Kode Praktik Lingkungan dan Sosial No. Klasifikasi SLS yang Instrumen Lingkungan dan Sosial Strategi Pengelolaan Tingkat Terpicu Bentuk Deskripsi Lingkungan dan Sosial Risiko Instrumen (Contoh) (ESCOPs)/SPPL/UKL-UPL; dan/atau
4. Mengembangkan dan menerapkan tindakan untuk menilai memitigasi dampak terhadap kesehatan dan keselamatan masyarakat sesuai penilaian bahaya dan risiko.', 'LAMPIRAN V (lanjutan 6)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (300, 'juklak-2-2025', 64, 'lampiran', 'LAMPIRAN V (lanjutan 7)', NULL, 42, '9. Menengah SLS 4 Penilaian Dampak Kajian dampak sosial dan gender diperlukan 1. Mengelola risiko dan Gender dan Sosial apabila terdapat potensi dampak langsung, dampak kekerasan dampak turunan, dampak kumulatif dan/atau berbasis gender, dampak yang timbul dari fasilitas pendukung eksploitasi seksual, dan bidang sosial, budaya, ekonomi, hak asasi pelecehan seksual manusia, pengarusutamaan gender, prinsip berdasarkan hasil non-diskriminasi dan pelindungan kelompok Penilaian Dampak Gender rentan. kelompok. Penilaian dampak sosial dan dan Sosial; dan gender ini dapat menjadi bagian atau terpisah 2. Menyediakan dana dari perumusan dokumen penilaian dampak tambahan untuk lingkungan dan sosial. Penentuan kebutuhan mengatasi risiko dan penelitian ini didasarkan pada hasil gap dampak kekerasan analyis. berbasis gender, eksploitasi seksual, dan pelecehan seksual (jika diperlukan).
10. Menengah - SLS 4 Rencana Rencana pengelolaan dan pemantauan 1. Mengadopsi dan Tinggi Pengelolaan dan kesehatan dan keselamatan masyarakat adalah menerapkan langkah Pemantauan dokumen untuk mitigasi dampak potensial penilaian dan mitigasi Kesehatan dan teridentifikasi dari penilaian dampak terhadap risiko keselamatan lalu Keselamatan kesehatan dan keselamatan masyarakat. lintas dan jalan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (300, '9. Menengah SLS 4 Penilaian Dampak Kajian dampak sosial dan gender diperlukan 1. Mengelola risiko dan Gender dan Sosial apabila terdapat potensi dampak langsung, dampak kekerasan dampak turunan, dampak kumulatif dan/atau berbasis gender, dampak yang timbul dari fasilitas pendukung eksploitasi seksual, dan bidang sosial, budaya, ekonomi, hak asasi pelecehan seksual manusia, pengarusutamaan gender, prinsip berdasarkan hasil non-diskriminasi dan pelindungan kelompok Penilaian Dampak Gender rentan. kelompok. Penilaian dampak sosial dan dan Sosial; dan gender ini dapat menjadi bagian atau terpisah 2. Menyediakan dana dari perumusan dokumen penilaian dampak tambahan untuk lingkungan dan sosial. Penentuan kebutuhan mengatasi risiko dan penelitian ini didasarkan pada hasil gap dampak kekerasan analyis. berbasis gender, eksploitasi seksual, dan pelecehan seksual (jika diperlukan).
10. Menengah - SLS 4 Rencana Rencana pengelolaan dan pemantauan 1. Mengadopsi dan Tinggi Pengelolaan dan kesehatan dan keselamatan masyarakat adalah menerapkan langkah Pemantauan dokumen untuk mitigasi dampak potensial penilaian dan mitigasi Kesehatan dan teridentifikasi dari penilaian dampak terhadap risiko keselamatan lalu Keselamatan kesehatan dan keselamatan masyarakat. lintas dan jalan;', 'LAMPIRAN V (lanjutan 7)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (301, 'juklak-2-2025', 65, 'lampiran', 'LAMPIRAN V (lanjutan 8)', NULL, 42, 'Masyarakat Dokumen ini diperlukan jika: 2. Mengembangkan dan ▪ Hasil studi penilaian dampak terhadap menerapkan tindakan No. Klasifikasi SLS yang Instrumen Lingkungan dan Sosial Strategi Pengelolaan Tingkat Terpicu Bentuk Deskripsi Lingkungan dan Sosial Risiko Instrumen (Contoh) kesehatan dan keselamatan masyarakat untuk menilai dan mengidentifikasi perlunya pengelolaan memitigasi dampak kesehatan dan keselamatan masyarakat terhadap kesehatan dan sebagaimana disyaratkan oleh SLS 4 untuk keselamatan masyarakat tingkat risiko menengah hingga tinggi; terhadap peningkatan dan/atau prevalensi penyakit, ▪ Terdapat kesenjangan antara dokumen kecelakaan akibat manajemen kesehatan dan keselamatan perencanaan kegiatan atau masyarakat (seperti prosedur tanggap kegagalan struktur, dan darurat, rencana peningkatan kapasitas berkurangnya sumber masyarakat untuk kesehatan dan daya; keselamatan dan dokumen serupa) yang 3. Melaksanakan langkah disusun oleh pemohon kegiatan dan mitigasi risiko sesuai persyaratan SLS 4 untuk tingkat risiko sesuai Rencana menengah hingga tinggi. Pengelolaan dan Dokumen rencana pengelolaan dan Pemantauan Kesehatan pemantauan kesehatan dan keselamatan dan Keselamatan masyarakat dapat menjadi bagian atau Masyarakat; dan/atau terpisah dari dokumen ESMP. 4. Menyiapkan dan melaksanakan rencana manajemen personel keamanan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (301, 'Masyarakat Dokumen ini diperlukan jika: 2. Mengembangkan dan ▪ Hasil studi penilaian dampak terhadap menerapkan tindakan No. Klasifikasi SLS yang Instrumen Lingkungan dan Sosial Strategi Pengelolaan Tingkat Terpicu Bentuk Deskripsi Lingkungan dan Sosial Risiko Instrumen (Contoh) kesehatan dan keselamatan masyarakat untuk menilai dan mengidentifikasi perlunya pengelolaan memitigasi dampak kesehatan dan keselamatan masyarakat terhadap kesehatan dan sebagaimana disyaratkan oleh SLS 4 untuk keselamatan masyarakat tingkat risiko menengah hingga tinggi; terhadap peningkatan dan/atau prevalensi penyakit, ▪ Terdapat kesenjangan antara dokumen kecelakaan akibat manajemen kesehatan dan keselamatan perencanaan kegiatan atau masyarakat (seperti prosedur tanggap kegagalan struktur, dan darurat, rencana peningkatan kapasitas berkurangnya sumber masyarakat untuk kesehatan dan daya; keselamatan dan dokumen serupa) yang 3. Melaksanakan langkah disusun oleh pemohon kegiatan dan mitigasi risiko sesuai persyaratan SLS 4 untuk tingkat risiko sesuai Rencana menengah hingga tinggi. Pengelolaan dan Dokumen rencana pengelolaan dan Pemantauan Kesehatan pemantauan kesehatan dan keselamatan dan Keselamatan masyarakat dapat menjadi bagian atau Masyarakat; dan/atau terpisah dari dokumen ESMP. 4. Menyiapkan dan melaksanakan rencana manajemen personel keamanan.', 'LAMPIRAN V (lanjutan 8)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (302, 'juklak-2-2025', 66, 'lampiran', 'LAMPIRAN V (lanjutan 9)', NULL, 43, '11. Menengah SLS 5 Kerangka Kerja Dokumen ini memberikan kerangka kerja Menyusun mekanisme Kebijakan untuk memperjelas prinsip- prinsip pengadaan penanganan keluhan terkait Pembebasan Lahan tanah dan pemukiman kembali, pengaturan akusisi tanah, pemukiman dan Pemukiman organisasi, dan kriteria desain/perencanaan kembali, pengadaan tanah, Kembali (Land untuk diterapkan pada kegiatan yang batas tanah, atau Acquisition and berpotensi mendapat dukungan Dana Bersama. pemanfaatan tanah.
Resettlement Policy Setelah desain kegiatan yang diusulkan Framework/LARPF) terdefinisi dengan jelas dan informasi yang diperlukan telah tersedia, pemohon kegiatan akan mengikuti LARPF dan memasukkan langkah-langkah yang tepat ke dalam dokumen No. Klasifikasi SLS yang Instrumen Lingkungan dan Sosial Strategi Pengelolaan Tingkat Terpicu Bentuk Deskripsi Lingkungan dan Sosial Risiko Instrumen (Contoh) ESMP. Dalam penyaluran Dana Bersama tahap prabencana instrumen ini tidak perlu digunakan untuk kegiatan yang tidak memerlukan akuisisi lahan/pemukiman kembali.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (302, '11. Menengah SLS 5 Kerangka Kerja Dokumen ini memberikan kerangka kerja Menyusun mekanisme Kebijakan untuk memperjelas prinsip- prinsip pengadaan penanganan keluhan terkait Pembebasan Lahan tanah dan pemukiman kembali, pengaturan akusisi tanah, pemukiman dan Pemukiman organisasi, dan kriteria desain/perencanaan kembali, pengadaan tanah, Kembali (Land untuk diterapkan pada kegiatan yang batas tanah, atau Acquisition and berpotensi mendapat dukungan Dana Bersama. pemanfaatan tanah.
Resettlement Policy Setelah desain kegiatan yang diusulkan Framework/LARPF) terdefinisi dengan jelas dan informasi yang diperlukan telah tersedia, pemohon kegiatan akan mengikuti LARPF dan memasukkan langkah-langkah yang tepat ke dalam dokumen No. Klasifikasi SLS yang Instrumen Lingkungan dan Sosial Strategi Pengelolaan Tingkat Terpicu Bentuk Deskripsi Lingkungan dan Sosial Risiko Instrumen (Contoh) ESMP. Dalam penyaluran Dana Bersama tahap prabencana instrumen ini tidak perlu digunakan untuk kegiatan yang tidak memerlukan akuisisi lahan/pemukiman kembali.', 'LAMPIRAN V (lanjutan 9)', 'Petunjuk Pelaksanaan Sistem Pengelolaan Lingkungan dan Sosial Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (303, 'juklak-2-2025', 67, 'lampiran', 'LAMPIRAN V (lanjutan 10)', NULL, 44, '12. Menengah SLS 6 Penilaian Dampak Instrumen ini diperlukan apabila: 1. Melaksanakan langkah-Keanekaragaman (i) terdapat indikasi potensi dampak (dampak langkah penanganan Hayati dan Sumber langsung, dampak turunan, dampak dampak Keanekaragaman Daya Alam Hayati. kumulatif dan/atau dampak yang timbul Hayati dan Sumber Daya dari fasilitas pendukung) terhadap Alam Hayati sesuai Kode keanekaragaman hayati dan sumber daya Praktik Lingkungan dan alam dalam proses penyaringan; dan/atau Sosial (ii) terdapat kesenjangan antara dokumen (ESCOPs)/SPPL/UKL-UPL dampak lingkungan yang diberikan oleh 2. Menyusun dan pemohon kegiatan dan persyaratan untuk melaksanakan Rencana memenuhi SLS 6. Pengelolaan Penyusunan dokumen ini mengacu pada Keanekaragaman Hayati Pedoman Pengkajian, Pengelolaan dan Pemantauan Dampak Terhadap Keanekaragaman Hayati dan Sumber Daya Alam. Dokumen ini dapat dimasukkan dalam, atau terpisah dari, dokumen UKL-UPL.
13. Menengah SLS 6 Rencana Rencana pengelolaan dan pemantauan Pengelolaan dan keanekaragaman hayati dan sumber daya alam Pemantauan merupakan dokumen mitigasi dampak Keanekaragaman potensial yang dianalisis dalam studi penilaian Hayati dan Sumber dampak terhadap keanekaragaman hayati dan Daya Alam sumber daya alam hayati. Dokumen ini dapat menjadi bagian atau terpisah dari dokumen ESMP.');
