INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (306, 'juklak-2-2026', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (306, 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026', 'Judul', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (307, 'juklak-2-2026', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN STANDAR KOMPONEN BIAYA USULAN KEGIATAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2026');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (307, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN STANDAR KOMPONEN BIAYA USULAN KEGIATAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2026', 'Isi hal. 1', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (308, 'juklak-2-2026', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Dalam rangka mempersiapkan perangkat teknis operasional pengelolaan penyaluran Dana Bersama Penanggulangan Bencana (selanjutnya disebut Dana Bersama), BNPB selaku leading sector penanggulangan bencana memiliki peran untuk memastikan dana dari pengelolaan Dana Bersama dapat dipergunakan dengan sebaik-baiknya demi meningkatkan ketahanan dan ketangguhan bangsa terhadap bencana.
Sehubungan dengan tujuan tersebut, telah disahkan Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana yang memuat norma yang secara umum mengenai pengaturan dan prioritas penyaluran, tata cara permohonan, tim penelaahan, verifikasi, evaluasi, dan sistem informasi.
Berbagai program kegiatan prabencana telah diidentifikasi dalam rangka melaksanakan kebijakan investasi pengelolaan risiko bencana sesuai dengan proyeksi risiko. Maka diperlukan pengaturan yang mengatur terkait standar biaya dan definisi operasional untuk masing-masing kegiatan yang akan diusulkan menggunakan Dana Bersama baik dari Kementerian/Lembaga, Pemerintah Daerah dan Kelompok Masyarakat.
Penyaluran Dana Bersama ini harus tetap memperhatikan proses bisnis penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (308, 'PENDAHULUAN A. Latar Belakang Dalam rangka mempersiapkan perangkat teknis operasional pengelolaan penyaluran Dana Bersama Penanggulangan Bencana (selanjutnya disebut Dana Bersama), BNPB selaku leading sector penanggulangan bencana memiliki peran untuk memastikan dana dari pengelolaan Dana Bersama dapat dipergunakan dengan sebaik-baiknya demi meningkatkan ketahanan dan ketangguhan bangsa terhadap bencana.
Sehubungan dengan tujuan tersebut, telah disahkan Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana yang memuat norma yang secara umum mengenai pengaturan dan prioritas penyaluran, tata cara permohonan, tim penelaahan, verifikasi, evaluasi, dan sistem informasi.
Berbagai program kegiatan prabencana telah diidentifikasi dalam rangka melaksanakan kebijakan investasi pengelolaan risiko bencana sesuai dengan proyeksi risiko. Maka diperlukan pengaturan yang mengatur terkait standar biaya dan definisi operasional untuk masing-masing kegiatan yang akan diusulkan menggunakan Dana Bersama baik dari Kementerian/Lembaga, Pemerintah Daerah dan Kelompok Masyarakat.
Penyaluran Dana Bersama ini harus tetap memperhatikan proses bisnis penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama Penanggulangan Bencana.', 'BAB I', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (309, 'juklak-2-2026', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Indonesia, sebagai negara dengan risiko bencana tinggi, menyadari bahwa penanggulangan bencana tidak hanya dapat dilakukan saat bencana terjadi, melainkan harus dimulai lebih awal melalui perencanaan matang pada tahap prabencana. Selain aspek teknis, Petunjuk Pelaksanaan ini juga mempertimbangkan pentingnya transparansi dan akuntabilitas dalam penggunaan dana bersama penanggulangan bencana untuk prabencana. Masyarakat dan pemangku kepentingan perlu diyakinkan bahwa dana dalam tahap prabencana dikelola dengan baik, digunakan untuk keperluan yang relevan, dan diawasi secara ketat.
Berdasarkan pertimbangan sebagaimana dimaksud di atas, perlu menyusun Petunjuk Pelaksanaan tentang Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana.
B. Maksud dan Tujuan Petunjuk Pelaksanaan ini dimaksudkan sebagai panduan operasional atau acuan dalam penyusunan rencana anggaran biaya kegiatan permohonan penyaluran Dana Bersama Penanggulangan Bencana.
Petunjuk Pelaksanaan ini bertujuan untuk:
1. memberikan panduan kepada kementerian/lembaga, pemerintah daerah dan kelompok masyarakat dalam penyusunan rencana anggaran biaya kegiatan permohonan penyaluran Dana Bersama Penanggulangan Bencana; dan
2. meningkatkan pemahaman pemohon tentang lingkup usulan kegiatan dan komponen pembiayaan yang dapat didanai oleh Dana Bersama tahap prabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (309, 'Indonesia, sebagai negara dengan risiko bencana tinggi, menyadari bahwa penanggulangan bencana tidak hanya dapat dilakukan saat bencana terjadi, melainkan harus dimulai lebih awal melalui perencanaan matang pada tahap prabencana. Selain aspek teknis, Petunjuk Pelaksanaan ini juga mempertimbangkan pentingnya transparansi dan akuntabilitas dalam penggunaan dana bersama penanggulangan bencana untuk prabencana. Masyarakat dan pemangku kepentingan perlu diyakinkan bahwa dana dalam tahap prabencana dikelola dengan baik, digunakan untuk keperluan yang relevan, dan diawasi secara ketat.
Berdasarkan pertimbangan sebagaimana dimaksud di atas, perlu menyusun Petunjuk Pelaksanaan tentang Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana.
B. Maksud dan Tujuan Petunjuk Pelaksanaan ini dimaksudkan sebagai panduan operasional atau acuan dalam penyusunan rencana anggaran biaya kegiatan permohonan penyaluran Dana Bersama Penanggulangan Bencana.
Petunjuk Pelaksanaan ini bertujuan untuk:
1. memberikan panduan kepada kementerian/lembaga, pemerintah daerah dan kelompok masyarakat dalam penyusunan rencana anggaran biaya kegiatan permohonan penyaluran Dana Bersama Penanggulangan Bencana; dan
2. meningkatkan pemahaman pemohon tentang lingkup usulan kegiatan dan komponen pembiayaan yang dapat didanai oleh Dana Bersama tahap prabencana.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (310, 'juklak-2-2026', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, 'C. Ruang Lingkup Petunjuk Pelaksanaan ini melingkupi definisi operasional dan komponen pembiayaan pada tiap usulan kegiatan yang dapat didanai oleh Dana Bersama Penanggulangan Bencana tahap prabencana.
Lingkup usulan kegiatan dalam Petunjuk Pelaksanaan ini mengacu pada Petunjuk Pelaksanaan Penelaahan, Verifikasi dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana yang ditetapkan oleh Kepala BNPB.
D. Pengertian
1. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
2. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
3. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, pengungsian, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
4. Prabencana adalah Penyelenggaraan Penanggulangan Bencana pada masa tidak terjadi bencana dan pada masa terdapat potensi bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (310, 'C. Ruang Lingkup Petunjuk Pelaksanaan ini melingkupi definisi operasional dan komponen pembiayaan pada tiap usulan kegiatan yang dapat didanai oleh Dana Bersama Penanggulangan Bencana tahap prabencana.
Lingkup usulan kegiatan dalam Petunjuk Pelaksanaan ini mengacu pada Petunjuk Pelaksanaan Penelaahan, Verifikasi dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana yang ditetapkan oleh Kepala BNPB.
D. Pengertian
1. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
2. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
3. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, pengungsian, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
4. Prabencana adalah Penyelenggaraan Penanggulangan Bencana pada masa tidak terjadi bencana dan pada masa terdapat potensi bencana.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (311, 'juklak-2-2026', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, '5. Dana Penanggulangan Bencana adalah dana yang digunakan bagi penanggulangan bencana untuk tahap prabencana, darurat bencana, dan/atau pascabencana.
6. Dana Bersama Penanggulangan Bencana yang selanjutnya disebut Dana Bersama, adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi Dana Penanggulangan Bencana yang memadai dan berkelanjutan.
7. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
8. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara Pemerintahan Daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
9. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nondepartemen setingkat menteri yang melakukan Penyelenggaraan Penanggulangan Bencana sesuai dengan ketentuan peraturan perundang-undangan.
10. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah perangkat daerah yang menyelenggarakan suburusan bencana.
11. Standar Biaya Keluaran yang selanjutnya disingkat SBK adalah indeks biaya yang ditetapkan untuk menghasilkan 1 (satu) volume keluaran.
12. SBK Umum adalah SBK yang berlaku untuk beberapa/seluruh kementerian/lembaga.
13. SBK Khusus adalah SBK yang berlaku untuk 1 (satu) kementerian/lembaga tertentu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (311, '5. Dana Penanggulangan Bencana adalah dana yang digunakan bagi penanggulangan bencana untuk tahap prabencana, darurat bencana, dan/atau pascabencana.
6. Dana Bersama Penanggulangan Bencana yang selanjutnya disebut Dana Bersama, adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi Dana Penanggulangan Bencana yang memadai dan berkelanjutan.
7. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
8. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara Pemerintahan Daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
9. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nondepartemen setingkat menteri yang melakukan Penyelenggaraan Penanggulangan Bencana sesuai dengan ketentuan peraturan perundang-undangan.
10. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah perangkat daerah yang menyelenggarakan suburusan bencana.
11. Standar Biaya Keluaran yang selanjutnya disingkat SBK adalah indeks biaya yang ditetapkan untuk menghasilkan 1 (satu) volume keluaran.
12. SBK Umum adalah SBK yang berlaku untuk beberapa/seluruh kementerian/lembaga.
13. SBK Khusus adalah SBK yang berlaku untuk 1 (satu) kementerian/lembaga tertentu.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (312, 'juklak-2-2026', 6, 'lain', 'BAB I (lanjutan 4)', NULL, 3, '14. Standar Komponen Biaya Usulan Kegiatan adalah standar komponen biaya yang digunakan dalam penyusunan permohonan penyaluran Dana Bersama Tahap Prabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (312, '14. Standar Komponen Biaya Usulan Kegiatan adalah standar komponen biaya yang digunakan dalam penyusunan permohonan penyaluran Dana Bersama Tahap Prabencana.', 'BAB I (lanjutan 4)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (313, 'juklak-2-2026', 7, 'lain', 'BAB II', NULL, 4, 'PENJELASAN USULAN KEGIATAN DAN KOMPONEN PEMBIAYAAN A. Umum Standar Komponen Biaya Usulan Kegiatan pada Petunjuk Pelaksanaan ini digunakan hanya untuk pengajuan permohonan penyaluran Dana Bersama. Segala sesuatu mengenai tata kelola dan tertib administrasi mengacu pada ketentuan peraturan perundang-undangan yang dikeluarkan oleh Kementerian Keuangan, BNPB, dan Pemerintah Daerah.
Lingkup nomenklatur usulan kegiatan yang digunakan dalam Petunjuk Pelaksanaan ini sesuai dengan dokumen produk hukum mengenai Penelaahan, Verifikasi dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana yang dikeluarkan oleh BNPB.
B. Pengelompokan Daftar Usulan Kegiatan Standar Komponen Biaya Usulan Kegiatan dikelompokkan dengan mempertimbangkan perimbangan kewenangan, lingkup, kompleksitas pelaksanaan kegiatan, dan prakarsa permohonan. Pengelompokan Daftar Usulan Kegiatan sebagai berikut:
a. Daftar Usulan Kegiatan dari Kementerian/Lembaga;
b. Daftar Usulan Kegiatan dari Pemerintah Provinsi;
c. Daftar Usulan Kegiatan dari Pemerintah Kabupaten/Kota; dan
d. Daftar Usulan Kegiatan dari Kelompok Masyarakat.
Daftar usulan kegiatan penyaluran Dana Bersama sebagaimana dimaksud di atas sesuai Lampiran I yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (313, 'PENJELASAN USULAN KEGIATAN DAN KOMPONEN PEMBIAYAAN A. Umum Standar Komponen Biaya Usulan Kegiatan pada Petunjuk Pelaksanaan ini digunakan hanya untuk pengajuan permohonan penyaluran Dana Bersama. Segala sesuatu mengenai tata kelola dan tertib administrasi mengacu pada ketentuan peraturan perundang-undangan yang dikeluarkan oleh Kementerian Keuangan, BNPB, dan Pemerintah Daerah.
Lingkup nomenklatur usulan kegiatan yang digunakan dalam Petunjuk Pelaksanaan ini sesuai dengan dokumen produk hukum mengenai Penelaahan, Verifikasi dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana yang dikeluarkan oleh BNPB.
B. Pengelompokan Daftar Usulan Kegiatan Standar Komponen Biaya Usulan Kegiatan dikelompokkan dengan mempertimbangkan perimbangan kewenangan, lingkup, kompleksitas pelaksanaan kegiatan, dan prakarsa permohonan. Pengelompokan Daftar Usulan Kegiatan sebagai berikut:
a. Daftar Usulan Kegiatan dari Kementerian/Lembaga;
b. Daftar Usulan Kegiatan dari Pemerintah Provinsi;
c. Daftar Usulan Kegiatan dari Pemerintah Kabupaten/Kota; dan
d. Daftar Usulan Kegiatan dari Kelompok Masyarakat.
Daftar usulan kegiatan penyaluran Dana Bersama sebagaimana dimaksud di atas sesuai Lampiran I yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.', 'BAB II', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (314, 'juklak-2-2026', 8, 'lain', 'BAB II (lanjutan 1)', NULL, 4, 'C. Struktur Penulisan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama untuk tiap-tiap kegiatan pada daftar usulan kegiatan sebagaimana dimaksud di atas terdiri atas 2 (dua) bagian, yaitu bagian definisi operasional dan bagian komponen pembiayaan.
1. Definisi Operasional Definisi operasional memberikan deskripsi, lingkup, skala, dan spesifikasi tiap-tiap kegiatan. Definisi operasional ini berbeda untuk setiap pemohon.
2. Komponen Pembiayaan
a. Uraian Berisi uraian komponen pembiayaan yang diperkenankan untuk pengusulan Dana Bersama Penanggulangan Bencana.
b. Variabel Berisi variabel pembiayaan yang diperkenankan untuk pengusulan Dana Bersama Penanggulangan Bencana
c. Kuantitas Berisi ketentuan jumlah variabel yang diperkenankan
d. Volume Berisi ketentuan volume yang diperkenankan untuk tiap-tiap variabel.
e. Besaran Berisi ketentuan hasil pengalian antara kuantitas, volume dan harga satuan. Harga satuan menggunakan standar biaya yang ditetapkan oleh Kementerian Keuangan serta pemerintah daerah.
f. Catatan Berisi ketentuan tambahan untuk tiap-tiap variabel
g. Sifat Berisi ketentuan sifat untuk tiap-tiap variabel. Sifat variabel terbagi atas sifat pokok dan sifat opsional. Sifat pokok berarti variabel tersebut wajib diajukan pada saat pengusulan suatu kegiatan. Sifat opsional berarti penggunaan variabel tersebut sesuai kebutuhan pemohon apakah dimasukkan dalam komponen pembiayaan atau tidak.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (314, 'C. Struktur Penulisan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama untuk tiap-tiap kegiatan pada daftar usulan kegiatan sebagaimana dimaksud di atas terdiri atas 2 (dua) bagian, yaitu bagian definisi operasional dan bagian komponen pembiayaan.
1. Definisi Operasional Definisi operasional memberikan deskripsi, lingkup, skala, dan spesifikasi tiap-tiap kegiatan. Definisi operasional ini berbeda untuk setiap pemohon.
2. Komponen Pembiayaan
a. Uraian Berisi uraian komponen pembiayaan yang diperkenankan untuk pengusulan Dana Bersama Penanggulangan Bencana.
b. Variabel Berisi variabel pembiayaan yang diperkenankan untuk pengusulan Dana Bersama Penanggulangan Bencana
c. Kuantitas Berisi ketentuan jumlah variabel yang diperkenankan
d. Volume Berisi ketentuan volume yang diperkenankan untuk tiap-tiap variabel.
e. Besaran Berisi ketentuan hasil pengalian antara kuantitas, volume dan harga satuan. Harga satuan menggunakan standar biaya yang ditetapkan oleh Kementerian Keuangan serta pemerintah daerah.
f. Catatan Berisi ketentuan tambahan untuk tiap-tiap variabel
g. Sifat Berisi ketentuan sifat untuk tiap-tiap variabel. Sifat variabel terbagi atas sifat pokok dan sifat opsional. Sifat pokok berarti variabel tersebut wajib diajukan pada saat pengusulan suatu kegiatan. Sifat opsional berarti penggunaan variabel tersebut sesuai kebutuhan pemohon apakah dimasukkan dalam komponen pembiayaan atau tidak.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (315, 'juklak-2-2026', 9, 'lain', 'BAB II (lanjutan 2)', NULL, 5, 'Komponen pembiayaan disusun dalam format seperti terlihat pada tabel di bawah ini.
D. Standar Komponen Biaya Usulan Kegiatan Detail Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana sebagaimana dimuat dalam Lampiran II.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (315, 'Komponen pembiayaan disusun dalam format seperti terlihat pada tabel di bawah ini.
D. Standar Komponen Biaya Usulan Kegiatan Detail Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana sebagaimana dimuat dalam Lampiran II.', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (316, 'juklak-2-2026', 10, 'lain', 'BAB III', NULL, 6, 'PELAKSANAAN DAN PENGAWASAN STANDAR KOMPONEN BIAYA USULAN KEGIATAN A. Ketentuan Umum Pelaksanaan Penerapan penggunaan Standar Komponen Biaya Usulan Kegiatan berpedoman pada ketentuan Peraturan Menteri Keuangan mengenai perencanaan anggaran, pelaksanaan anggaran serta akuntansi dan pelaporan keuangan.
Untuk standar biaya yang telah ditetapkan melalui SBK Umum dan/atau SBK Khusus oleh Kementerian Keuangan, nilai tersebut bersifat batas tertinggi yang tidak dapat dilampaui.
Untuk standar biaya yang disusun dalam bentuk costing (mata anggaran), penentuan nominal harga satuan disesuaikan dengan ketentuan yang berlaku pada tiap kementerian/lembaga atau Pemerintah Daerah dengan mempertimbangkan prinsip penganggaran yang selektif, efektif, dan efisien. Sedangkan variabel mata anggaran mengacu pada Petunjuk Pelaksanaan ini.
Sifat variabel mata anggaran pada standar biaya ini terdiri atas:
1. variabel mata anggaran yang bersifat pokok, merupakan standar minimal yang harus diperhitungkan; dan
2. variabel mata anggaran yang bersifat opsional, dapat dipilih sesuai kebutuhan.
B. Ketentuan Pengawasan Pengawasan atas pelaksanaan ketentuan dalam Petunjuk Pelaksanaan ini dilakukan oleh Aparat Pengawasan Intern Pemerintah kementerian/lembaga dan Pemerintah Daerah sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (316, 'PELAKSANAAN DAN PENGAWASAN STANDAR KOMPONEN BIAYA USULAN KEGIATAN A. Ketentuan Umum Pelaksanaan Penerapan penggunaan Standar Komponen Biaya Usulan Kegiatan berpedoman pada ketentuan Peraturan Menteri Keuangan mengenai perencanaan anggaran, pelaksanaan anggaran serta akuntansi dan pelaporan keuangan.
Untuk standar biaya yang telah ditetapkan melalui SBK Umum dan/atau SBK Khusus oleh Kementerian Keuangan, nilai tersebut bersifat batas tertinggi yang tidak dapat dilampaui.
Untuk standar biaya yang disusun dalam bentuk costing (mata anggaran), penentuan nominal harga satuan disesuaikan dengan ketentuan yang berlaku pada tiap kementerian/lembaga atau Pemerintah Daerah dengan mempertimbangkan prinsip penganggaran yang selektif, efektif, dan efisien. Sedangkan variabel mata anggaran mengacu pada Petunjuk Pelaksanaan ini.
Sifat variabel mata anggaran pada standar biaya ini terdiri atas:
1. variabel mata anggaran yang bersifat pokok, merupakan standar minimal yang harus diperhitungkan; dan
2. variabel mata anggaran yang bersifat opsional, dapat dipilih sesuai kebutuhan.
B. Ketentuan Pengawasan Pengawasan atas pelaksanaan ketentuan dalam Petunjuk Pelaksanaan ini dilakukan oleh Aparat Pengawasan Intern Pemerintah kementerian/lembaga dan Pemerintah Daerah sesuai dengan ketentuan peraturan perundang-undangan.', 'BAB III', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (317, 'juklak-2-2026', 11, 'lain', 'BAB IV', NULL, 7, 'PENUTUP Petunjuk Pelaksanaan ini merupakan instrumen turunan operasionalisasi penyaluran Dana Bersama Penanggulangan Bencana. Petunjuk pelaksanaan ini diharapkan dapat menjadi acuan bagi Kementerian/Lembaga, Pemerintah Daerah dan kelompok masyarakat yang akan mengajukan permohonan penyaluran Dana Bersama Penanggulangan Bencana pada tahap prabencana.
Ditetapkan di Jakarta pada tanggal 16 Maret 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (317, 'PENUTUP Petunjuk Pelaksanaan ini merupakan instrumen turunan operasionalisasi penyaluran Dana Bersama Penanggulangan Bencana. Petunjuk pelaksanaan ini diharapkan dapat menjadi acuan bagi Kementerian/Lembaga, Pemerintah Daerah dan kelompok masyarakat yang akan mengajukan permohonan penyaluran Dana Bersama Penanggulangan Bencana pada tahap prabencana.
Ditetapkan di Jakarta pada tanggal 16 Maret 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati', 'BAB IV', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (318, 'juklak-2-2026', 12, 'lampiran', 'LAMPIRAN I', NULL, 8, 'PETUNJUK PELAKSANAAN STANDAR KOMPONEN BIAYA USULAN KEGIATAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2026 DAFTAR USULAN KEGIATAN DANA BERSAMA PENANGGULANGAN BENCANA A. Daftar Usulan Kegiatan Dari Kementerian/Lembaga
1. Penyusunan Kajian Risiko Bencana
2. Penyusunan Rencana Penanggulangan Bencana
3. Penyusunan Rencana Kontingensi
4. Penyusunan Rencana Penanggulangan Kedaruratan Bencana
5. Penyusunan Rencana Kesiapsiagaan Logistik dan Peralatan
6. Penyusunan Dokumen Perencanaan Lain di Bidang Penanggulangan Bencana
7. Pembentukan Peraturan Pemerintah Bidang Penanggulangan Bencana
8. Pembentukan Peraturan Presiden Bidang Penanggulangan Bencana
9. Pembentukan Peraturan Menteri/Kepala Lembaga Bidang Penanggulangan Bencana
10. Penyusunan NSPK Bidang Penanggulangan Bencana
11. Penyusunan Naskah Akademis Kebijakan Bidang Penanggulangan Bencana
12. Penelitian dan Pengembangan Bidang Penanggulangan Bencana
13. Pendampingan, Monitoring, dan Evaluasi SPM Sub-Urusan Bencana
14. Penyusunan Standar Kompetensi Kerja Nasional Bidang Penanggulangan Bencana
15. Penyusunan Standar Nasional Indonesia Bidang Penanggulangan Bencana
16. Pembangunan/Pengembangan Sistem Informasi Bidang Penanggulangan Bencana
17. Pemantauan, Pengendalian, Evaluasi, dan Pelaporan Kinerja Penanggulangan Bencana
18. Sosialisasi Kebencanaan kepada Aparatur dan/atau Masyarakat
19. Penyelenggaraan Kegiatan Budaya Sadar Bencana
20. Pembentukan/Pengembangan Sektor Publik Tangguh Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (318, 'PETUNJUK PELAKSANAAN STANDAR KOMPONEN BIAYA USULAN KEGIATAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 2 TAHUN 2026 DAFTAR USULAN KEGIATAN DANA BERSAMA PENANGGULANGAN BENCANA A. Daftar Usulan Kegiatan Dari Kementerian/Lembaga
