INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (329, 'juklak-2-2026', 23, 'lampiran', 'LAMPIRAN II (lanjutan 4)', NULL, 14, 'Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah diskusi Opsional lembar materi yang Teknis sesuai teknis x Harga dibutuhkan kebutuhan satuan Konsultasi Transport Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta Pokok Publik sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 (empat) Jumlah jam kerja x Publik jam kerja total Jumlah konsultasi untuk 1 (satu) kali publik x Harga Konsultasi Publik) Satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu) kali Jumlah pertemuan di luar Jabodetabek Jabodetabek atau pertemuan x Jumlah hari x sesuai kebutuhan (maksimal 2 (dua) Harga satuan hari untuk 1 (satu) kali rapat) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (329, 'Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah diskusi Opsional lembar materi yang Teknis sesuai teknis x Harga dibutuhkan kebutuhan satuan Konsultasi Transport Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta Pokok Publik sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 (empat) Jumlah jam kerja x Publik jam kerja total Jumlah konsultasi untuk 1 (satu) kali publik x Harga Konsultasi Publik) Satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu) kali Jumlah pertemuan di luar Jabodetabek Jabodetabek atau pertemuan x Jumlah hari x sesuai kebutuhan (maksimal 2 (dua) Harga satuan hari untuk 1 (satu) kali rapat) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan', 'LAMPIRAN II (lanjutan 4)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (330, 'juklak-2-2026', 24, 'lampiran', 'LAMPIRAN II (lanjutan 5)', NULL, 14, 'Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah paket Maksimal 5 (lima) Opsional Dokumen dan Kajian Risiko penggandaan dokumen x Jumlah eksemplar Laporan Bencana penggandaan x penggandaan Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah paket Maksimal 5 (lima) Opsional Kegiatan penggandaan dokumen x Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Kegiatan penyusunan dokumen hingga siap untuk disahkan dalam segala bentuk hasil pengkajian pada kawasan yang Operasional menjadi kewenangan provinsi yang dilengkapi dokumen spasial dan tabular dengan tingkat kedalaman analisis minimal pada skala kecamatan dengan menggunakan metode yang valid untuk:
1. mengetahui tingkat risiko bencana baik ancaman tunggal dan/atau multiancaman; atau
2. mengetahui tingkat salah satu faktor risiko tematik (tingkat bahaya, tingkat kerentanan, dan/atau tingkat kapasitas) baik ancaman tunggal dan/atau multiancaman; atau
3. mengonsolidasikan data dan/atau hasil kajian risiko bencana tingkat kabupaten/kota.');
