INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (333, 'juklak-2-2026', 27, 'lampiran', 'LAMPIRAN II (lanjutan 8)', NULL, 18, 'data orang atau sesuai tenaga ahli kerja x Harga statistik kebutuhan (maksimal 6 (enam) satuan bulan) Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tenaga Maksimal 2 (dua) Opsional dokumen tim penulis penulis minimal 1 untuk tiap-tiap penulis x Jumlah orang (8 OB) (satu) orang atau penulis (maksimal 6 bulan kerja x Harga sesuai kebutuhan (enam) bulan) satuan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 6 (enam) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah diskusi total untuk 1 (satu) teknis x Harga kali Diskusi teknis) Satuan Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah diskusi Opsional lembar materi yang Teknis sesuai teknis x Harga dibutuhkan kebutuhan');
