INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (334, 'juklak-2-2026', 28, 'lampiran', 'LAMPIRAN II (lanjutan 9)', NULL, 18, 'satuan Konsultasi Transport Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta Pokok Publik sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 Jumlah jam kerja x Publik (empat) jam kerja Jumlah konsultasi total untuk 1 (satu) publik x Harga kali Konsultasi Satuan Publik) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x kebutuhan Jumlah konsultasi identifikasi tim publik x Harga teknis satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai hasil Publik sesuai Jumlah konsultasi identifikasi tim kebutuhan publik x Harga teknis satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Asistensi BNPB Konsumsi rapat Jumlah peserta Jumlah asistensi Jumlah peserta Pokok sesuai kebutuhan yang dilakukan Asistensi x Jumlah Asistensi x Harga satuan Snack rapat Jumlah peserta Jumlah asistensi Jumlah peserta Pokok sesuai hasil yang dilakukan Asistensi x Jumlah');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (334, 'satuan Konsultasi Transport Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta Pokok Publik sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 Jumlah jam kerja x Publik (empat) jam kerja Jumlah konsultasi total untuk 1 (satu) publik x Harga kali Konsultasi Satuan Publik) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x kebutuhan Jumlah konsultasi identifikasi tim publik x Harga teknis satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai hasil Publik sesuai Jumlah konsultasi identifikasi tim kebutuhan publik x Harga teknis satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Asistensi BNPB Konsumsi rapat Jumlah peserta Jumlah asistensi Jumlah peserta Pokok sesuai kebutuhan yang dilakukan Asistensi x Jumlah Asistensi x Harga satuan Snack rapat Jumlah peserta Jumlah asistensi Jumlah peserta Pokok sesuai hasil yang dilakukan Asistensi x Jumlah', 'LAMPIRAN II (lanjutan 9)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (335, 'juklak-2-2026', 29, 'lampiran', 'LAMPIRAN II (lanjutan 10)', NULL, 18, 'identifikasi tim Asistensi x Harga teknis satuan Perjalanan Dinas Jumlah perwakilan Jumlah asistensi Jumlah tim 1. Bila Opsional Perwakilan Tim tim sesuai yang dilakukan perwakilan x dilaksanakan Penyusun dan kebutuhan Jumlah asistensi x secara tatap BPBD/Tim (maksimal 3 (tiga) Harga satuan muka Substansi orang) 2. Maksimal 2 (dua) kali Asistensi ke BNPB Perbanyakan materi Sesuai jumlah Jumlah asistensi Jumlah Asistensi x Opsional lembar materi yang yang dilakukan Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah paket Maksimal 5 (lima) Opsional Dokumen dan Kajian Risiko penggandaan dokumen x Jumlah eksemplar Laporan Bencana penggandaan penggandaan x Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah paket Maksimal 5 (lima) Opsional Kegiatan penggandaan dokumen x Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Kegiatan penyusunan dokumen hingga siap untuk disahkan dalam segala bentuk hasil pengkajian pada kawasan yang Operasional menjadi kewenangan kabupaten/kota yang dilengkapi dokumen spasial dan tabular dengan tingkat kedalaman analisis minimal pada skala setingkat desa/kelurahan dengan menggunakan metode yang valid untuk:
1. mengetahui tingkat risiko bencana baik ancaman tunggal dan/atau multi ancaman; atau');
