INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (336, 'juklak-2-2026', 30, 'lampiran', 'LAMPIRAN II (lanjutan 11)', NULL, 22, '2. mengetahui tingkat salah satu faktor risiko tematik (tingkat bahaya, tingkat kerentanan, dan/atau tingkat kapasitas) baik ancaman tunggal dan/atau multi ancaman.
