INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (337, 'Survei Biaya akomodasi Jumlah personil Jumlah hari kerja Jumlah personil x Pokok dan honorarium tim sesuai Jumlah tiap-tiap personil Jumlah hari kerja x survei lokasi yang akan sesuai durasi Harga satuan disurvei pelaksanaan survei Perlengkapan survei Jumlah Sesuai kebutuhan Jumlah Pokok perlengkapan perlengkapan x Sesuai kebutuhan Harga satuan Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim jumlah bulan kerja bulan x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 7 (tujuh) Opsional bidang ancaman tenaga ahli bidang yang digunakan untuk tiap-tiap x Jumlah bulan orang (42 OB). bencana ancaman bencana disesuaikan dengan tenaga ahli kerja x Harga Untuk KRB tematik jenis ancaman (maksimal 6 (enam) satuan maksimal 3 (tiga) bencana yang akan bulan) orang (18 OB) dikaji Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 4 (empat) Opsional bidang tenaga ahli bidang untuk bidang untuk tiap-tiap x Jumlah bulan orang (24 OB) kerentanan kerentanan kerentanan fisik, tenaga ahli kerja x Harga bencana ekonomi, sosial, (maksimal 6 (enam) satuan dan lingkungan bulan) Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 3 (tiga) Opsional bidang pemetaan tenaga ahli GIS minimal 1 (satu) untuk tiap-tiap x Jumlah bulan orang (18 OB) GIS dan data orang atau sesuai tenaga ahli', 'LAMPIRAN II (lanjutan 12)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (338, 'juklak-2-2026', 32, 'lampiran', 'LAMPIRAN II (lanjutan 13)', NULL, 23, 'kerja x Harga statistik kebutuhan (maksimal 6 (enam) satuan bulan) Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tenaga Maksimal 2 (dua) Opsional dokumen tim penulis penulis minimal 1 untuk tiap-tiap penulis x Jumlah orang (8 OB) (satu) orang atau tenaga penulis bulan kerja x Harga sesuai kebutuhan (maksimal 6 (enam) satuan bulan) Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 6 (enam) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah diskusi total untuk 1 (satu) teknis x Harga kali Diskusi teknis) Satuan Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah diskusi Opsional lembar materi yang Teknis sesuai teknis x Harga dibutuhkan kebutuhan satuan Konsultasi Transport');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (338, 'kerja x Harga statistik kebutuhan (maksimal 6 (enam) satuan bulan) Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tenaga Maksimal 2 (dua) Opsional dokumen tim penulis penulis minimal 1 untuk tiap-tiap penulis x Jumlah orang (8 OB) (satu) orang atau tenaga penulis bulan kerja x Harga sesuai kebutuhan (maksimal 6 (enam) satuan bulan) Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 6 (enam) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah diskusi total untuk 1 (satu) teknis x Harga kali Diskusi teknis) Satuan Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah diskusi Opsional lembar materi yang Teknis sesuai teknis x Harga dibutuhkan kebutuhan satuan Konsultasi Transport', 'LAMPIRAN II (lanjutan 13)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (339, 'juklak-2-2026', 33, 'lampiran', 'LAMPIRAN II (lanjutan 14)', NULL, 23, 'Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta Pokok Publik sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 Jumlah jam kerja x Publik (empat) jam kerja Jumlah konsultasi total untuk 1 (satu) publik x Harga kali Konsultasi Satuan Publik) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai hasil Publik sesuai Jumlah konsultasi identifikasi tim kebutuhan publik x Harga teknis satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Asistensi BNPB Konsumsi rapat Jumlah peserta Jumlah asistensi Jumlah peserta Pokok sesuai kebutuhan yang dilakukan Asistensi x Jumlah Asistensi x Harga satuan Snack rapat Jumlah peserta Jumlah asistensi Jumlah peserta x Pokok sesuai hasil yang dilakukan Jumlah Asistensi x Harga satuan identifikasi tim');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (339, 'Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta Pokok Publik sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 Jumlah jam kerja x Publik (empat) jam kerja Jumlah konsultasi total untuk 1 (satu) publik x Harga kali Konsultasi Satuan Publik) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai hasil Publik sesuai Jumlah konsultasi identifikasi tim kebutuhan publik x Harga teknis satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Asistensi BNPB Konsumsi rapat Jumlah peserta Jumlah asistensi Jumlah peserta Pokok sesuai kebutuhan yang dilakukan Asistensi x Jumlah Asistensi x Harga satuan Snack rapat Jumlah peserta Jumlah asistensi Jumlah peserta x Pokok sesuai hasil yang dilakukan Jumlah Asistensi x Harga satuan identifikasi tim', 'LAMPIRAN II (lanjutan 14)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (340, 'juklak-2-2026', 34, 'lampiran', 'LAMPIRAN II (lanjutan 15)', NULL, 23, 'teknis Perjalanan Dinas Jumlah perwakilan Jumlah asistensi Jumlah tim 1. Bila Opsional Perwakilan Tim tim sesuai yang dilakukan perwakilan x dilaksanakan Penyusun dan kebutuhan Jumlah asistensi x secara tatap BPBD/Tim (maksimal 3 (tiga) Harga satuan muka Substansi orang) 2. Maksimal 2 (dua) kali Asistensi ke BNPB Perbanyakan materi Sesuai jumlah Jumlah asistensi Jumlah Asistensi x Opsional lembar materi yang yang dilakukan Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah paket Maksimal 5 (lima) Opsional Dokumen dan Kajian Risiko penggandaan dokumen x Jumlah eksemplar Laporan Bencana penggandaan x penggandaan Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah paket Maksimal 5 (lima) Opsional Kegiatan penggandaan dokumen x Jumlah eksemplar penggandaan x penggandaan Harga satuan KEGIATAN : PENYUSUNAN RENCANA PENANGGULANGAN BENCANA SUB KATEGORI : PERENCANAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Kegiatan penyusunan dokumen untuk segala bentuk perencanaan terkait penyelenggaraan penanggulangan bencana di Operasional tingkat nasional maupun pada kawasan strategis nasional tertentu, yang berisikan pengenalan dan pengkajian ancaman, pemahaman tentang kerentanan masyarakat, analisis kemungkinan dampak bencana, pilihan tindakan pengurangan risiko bencana, penentuan mekanisme kesiapan dan penanggulangan dampak bencana, dan alokasi tugas kewenangan dan sumber daya yang tersedia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (340, 'teknis Perjalanan Dinas Jumlah perwakilan Jumlah asistensi Jumlah tim 1. Bila Opsional Perwakilan Tim tim sesuai yang dilakukan perwakilan x dilaksanakan Penyusun dan kebutuhan Jumlah asistensi x secara tatap BPBD/Tim (maksimal 3 (tiga) Harga satuan muka Substansi orang) 2. Maksimal 2 (dua) kali Asistensi ke BNPB Perbanyakan materi Sesuai jumlah Jumlah asistensi Jumlah Asistensi x Opsional lembar materi yang yang dilakukan Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah paket Maksimal 5 (lima) Opsional Dokumen dan Kajian Risiko penggandaan dokumen x Jumlah eksemplar Laporan Bencana penggandaan x penggandaan Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah paket Maksimal 5 (lima) Opsional Kegiatan penggandaan dokumen x Jumlah eksemplar penggandaan x penggandaan Harga satuan KEGIATAN : PENYUSUNAN RENCANA PENANGGULANGAN BENCANA SUB KATEGORI : PERENCANAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Kegiatan penyusunan dokumen untuk segala bentuk perencanaan terkait penyelenggaraan penanggulangan bencana di Operasional tingkat nasional maupun pada kawasan strategis nasional tertentu, yang berisikan pengenalan dan pengkajian ancaman, pemahaman tentang kerentanan masyarakat, analisis kemungkinan dampak bencana, pilihan tindakan pengurangan risiko bencana, penentuan mekanisme kesiapan dan penanggulangan dampak bencana, dan alokasi tugas kewenangan dan sumber daya yang tersedia.', 'LAMPIRAN II (lanjutan 15)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (341, 'juklak-2-2026', 35, 'lampiran', 'LAMPIRAN II (lanjutan 16)', NULL, 27, 'Khusus untuk pilihan tindakan pengurangan risiko bencana dijabarkan dalam bentuk program, kegiatan, indikator dan tahun pelaksanaan kegiatan beserta rincian anggarannya minimal untuk 5 tahun perencanaan.
Tim Substansi/ Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Pokok Tim Teknis tim substansi/ tim sesuai kebutuhan atau hari kerja tiap- Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan tiap tim substansi/ atau hari kerja x dan ditetapkan identifikasi tim teknis Harga satuan melalui Surat kementerian/ Keputusan Eselon I lembaga dan entitas utama terkait penanggulangan bencana berdasarkan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (341, 'Khusus untuk pilihan tindakan pengurangan risiko bencana dijabarkan dalam bentuk program, kegiatan, indikator dan tahun pelaksanaan kegiatan beserta rincian anggarannya minimal untuk 5 tahun perencanaan.
Tim Substansi/ Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Pokok Tim Teknis tim substansi/ tim sesuai kebutuhan atau hari kerja tiap- Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan tiap tim substansi/ atau hari kerja x dan ditetapkan identifikasi tim teknis Harga satuan melalui Surat kementerian/ Keputusan Eselon I lembaga dan entitas utama terkait penanggulangan bencana berdasarkan ketentuan peraturan perundang-undangan.', 'LAMPIRAN II (lanjutan 16)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (342, 'juklak-2-2026', 36, 'lampiran', 'LAMPIRAN II (lanjutan 17)', NULL, 27, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 10 Opsional Ketua Tim jumlah bulan kerja (sepuluh) bulan x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 10 Opsional bidang tenaga ahli maksimal 2 (dua) tiap-tiap tenaga ahli x Jumlah bulan (sepuluh) bulan kebencanaan orang kerja x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 10 Opsional bidang tenaga ahli maksimal 2 (dua) tiap-tiap tenaga ahli x Jumlah bulan (sepuluh) bulan perencanaan orang kerja x Harga pembangunan/ satuan kebijakan publik Tenaga penulis Biaya honorarium Jumlah personil Jumlah bulan kerja Jumlah personil x Maksimal 10 Opsional tim penulis maksimal 2 (dua) tiap-tiap personil Jumlah bulan kerja (sepuluh) bulan orang x Harga satuan Lokakarya Transport Peserta Jumlah peserta Jumlah lokakarya Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah lokakarya x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali lokakarya kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah lokakarya x total untuk 1 (satu) Harga Satuan kali Lokakarya) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk di luar Opsional dinas yang berada di luar 1 (satu) kali Jumlah lokakarya x Jabodetabek Jabodetabek atau lokakarya Jumlah hari x dan/atau');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (342, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 10 Opsional Ketua Tim jumlah bulan kerja (sepuluh) bulan x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 10 Opsional bidang tenaga ahli maksimal 2 (dua) tiap-tiap tenaga ahli x Jumlah bulan (sepuluh) bulan kebencanaan orang kerja x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 10 Opsional bidang tenaga ahli maksimal 2 (dua) tiap-tiap tenaga ahli x Jumlah bulan (sepuluh) bulan perencanaan orang kerja x Harga pembangunan/ satuan kebijakan publik Tenaga penulis Biaya honorarium Jumlah personil Jumlah bulan kerja Jumlah personil x Maksimal 10 Opsional tim penulis maksimal 2 (dua) tiap-tiap personil Jumlah bulan kerja (sepuluh) bulan orang x Harga satuan Lokakarya Transport Peserta Jumlah peserta Jumlah lokakarya Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah lokakarya x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali lokakarya kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah lokakarya x total untuk 1 (satu) Harga Satuan kali Lokakarya) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk di luar Opsional dinas yang berada di luar 1 (satu) kali Jumlah lokakarya x Jabodetabek Jabodetabek atau lokakarya Jumlah hari x dan/atau', 'LAMPIRAN II (lanjutan 17)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (343, 'juklak-2-2026', 37, 'lampiran', 'LAMPIRAN II (lanjutan 18)', NULL, 27, 'sesuai kebutuhan (Maksimal 2 (dua) Harga satuan penyusunan hari untuk 1 (satu) dokumen Kawasan/ kali lokakarya) Tematik Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 5 (lima) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Diskusi total untuk 1 (satu) Teknis x Harga kali Diskusi Teknis) Satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk di luar Opsional dinas yang berada di luar 1 (satu) kali Diskusi Jumlah Diskusi Jabodetabek dan/ Jabodetabek atau Teknis (maksimal 2 Teknis x Jumlah atau penyusunan sesuai kebutuhan (dua) hari untuk 1 hari x Harga satuan dokumen RPB (satu) kali Diskusi kawasan/tematik Teknis)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (343, 'sesuai kebutuhan (Maksimal 2 (dua) Harga satuan penyusunan hari untuk 1 (satu) dokumen Kawasan/ kali lokakarya) Tematik Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 5 (lima) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Diskusi total untuk 1 (satu) Teknis x Harga kali Diskusi Teknis) Satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk di luar Opsional dinas yang berada di luar 1 (satu) kali Diskusi Jumlah Diskusi Jabodetabek dan/ Jabodetabek atau Teknis (maksimal 2 Teknis x Jumlah atau penyusunan sesuai kebutuhan (dua) hari untuk 1 hari x Harga satuan dokumen RPB (satu) kali Diskusi kawasan/tematik Teknis)', 'LAMPIRAN II (lanjutan 18)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (344, 'juklak-2-2026', 38, 'lampiran', 'LAMPIRAN II (lanjutan 19)', NULL, 27, 'Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Konsultasi Transport Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta x Pokok Publik sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 Jumlah jam kerja x Publik (empat) jam kerja Jumlah Konsultasi total untuk 1 (satu) Publik x Harga kali Konsultasi Satuan Publik) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk di luar Opsional dinas yang berada di luar 1 (satu) kali Jumlah Konsultasi Jabodetabek dan/ Jabodetabek atau Konsultasi Publik Publik x Jumlah atau penyusunan sesuai kebutuhan (maksimal 2 (dua) hari x Harga satuan dokumen hari untuk 1 (satu) kawasan/tematik kali rapat) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (344, 'Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Konsultasi Transport Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta x Pokok Publik sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 Jumlah jam kerja x Publik (empat) jam kerja Jumlah Konsultasi total untuk 1 (satu) Publik x Harga kali Konsultasi Satuan Publik) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk di luar Opsional dinas yang berada di luar 1 (satu) kali Jumlah Konsultasi Jabodetabek dan/ Jabodetabek atau Konsultasi Publik Publik x Jumlah atau penyusunan sesuai kebutuhan (maksimal 2 (dua) hari x Harga satuan dokumen hari untuk 1 (satu) kawasan/tematik kali rapat) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik', 'LAMPIRAN II (lanjutan 19)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (345, 'juklak-2-2026', 39, 'lampiran', 'LAMPIRAN II (lanjutan 20)', NULL, 27, 'sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Asistensi dan Transportasi Jumlah peserta Jumlah pertemuan Jumlah peserta x Maksimal 3 (tiga) Pokok Harmonisasi Peserta sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan kali x Harga satuan Biaya honorarium Jumlah Jumlah jam kerja Jumlah Jika dilakukan Opsional Tenaga Narasumber narasumber sesuai sesuai kebutuhan narasumber x secara luring kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah pertemuan total untuk 1 (satu) x Harga Satuan kali pertemuan) Paket pertemuan Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan x Harga satuan Konsumsi rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan x Harga satuan Snack rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Konsultasi Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah pertemuan Jumlah pertemuan Opsional lembar');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (345, 'sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Asistensi dan Transportasi Jumlah peserta Jumlah pertemuan Jumlah peserta x Maksimal 3 (tiga) Pokok Harmonisasi Peserta sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan kali x Harga satuan Biaya honorarium Jumlah Jumlah jam kerja Jumlah Jika dilakukan Opsional Tenaga Narasumber narasumber sesuai sesuai kebutuhan narasumber x secara luring kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah pertemuan total untuk 1 (satu) x Harga Satuan kali pertemuan) Paket pertemuan Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan x Harga satuan Konsumsi rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan x Harga satuan Snack rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Konsultasi Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah pertemuan Jumlah pertemuan Opsional lembar', 'LAMPIRAN II (lanjutan 20)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (346, 'juklak-2-2026', 40, 'lampiran', 'LAMPIRAN II (lanjutan 21)', NULL, 27, 'materi yang sesuai kebutuhan x Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Penanggulangan penggandaan x penggandaan Bencana Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Kegiatan penyusunan dokumen untuk segala bentuk perencanaan terkait penyelenggaraan penanggulangan bencana di Operasional tingkat provinsi, yang berisikan pengenalan dan pengkajian ancaman, pemahaman tentang kerentanan masyarakat, analisis kemungkinan dampak bencana, pilihan tindakan pengurangan risiko bencana, penentuan mekanisme kesiapan dan penanggulangan dampak bencana, dan alokasi tugas kewenangan dan sumber daya yang tersedia.
Khusus untuk pilihan tindakan pengurangan risiko bencana dijabarkan dalam bentuk program, kegiatan, indikator dan tahun pelaksanaan kegiatan beserta rincian anggarannya minimal untuk 5 (lima) tahun perencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (346, 'materi yang sesuai kebutuhan x Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Penanggulangan penggandaan x penggandaan Bencana Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Kegiatan penyusunan dokumen untuk segala bentuk perencanaan terkait penyelenggaraan penanggulangan bencana di Operasional tingkat provinsi, yang berisikan pengenalan dan pengkajian ancaman, pemahaman tentang kerentanan masyarakat, analisis kemungkinan dampak bencana, pilihan tindakan pengurangan risiko bencana, penentuan mekanisme kesiapan dan penanggulangan dampak bencana, dan alokasi tugas kewenangan dan sumber daya yang tersedia.
Khusus untuk pilihan tindakan pengurangan risiko bencana dijabarkan dalam bentuk program, kegiatan, indikator dan tahun pelaksanaan kegiatan beserta rincian anggarannya minimal untuk 5 (lima) tahun perencanaan.', 'LAMPIRAN II (lanjutan 21)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (347, 'juklak-2-2026', 41, 'lampiran', 'LAMPIRAN II (lanjutan 22)', NULL, 32, 'Prasyarat permohonan: memiliki Dokumen Kajian Risiko Bencana yang masih berlaku Tim Substansi/ Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Pokok Tim Teknis tim substansi/ tim sesuai kebutuhan tiap-tiap tim atau Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan hari kerja atau hari kerja x dan ditetapkan identifikasi substansi/tim Harga satuan melalui Surat Perangkat Daerah teknis Keputusan Eselon II dan entitas utama terkait penanggulangan bencana provinsi berdasarkan ketentuan peraturan perundang-undangan Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 6 (enam) Opsional bidang tenaga ahli maksimal 1 (satu) tiap-tiap tenaga ahli x Jumlah bulan bulan kebencanaan orang kerja x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 6 (enam) Opsional bidang tenaga ahli maksimal 1 (satu) tiap-tiap tenaga ahli x Jumlah bulan bulan perencanaan orang kerja x Harga pembangunan/ satuan kebijakan publik Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tim penulis Maksimal 6 (enam) Opsional tim penulis penulis maksimal 1 tiap-tiap tenaga x Jumlah bulan bulan (satu) orang penulis kerja x Harga satuan Lokakarya Transport Peserta Jumlah peserta');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (347, 'Prasyarat permohonan: memiliki Dokumen Kajian Risiko Bencana yang masih berlaku Tim Substansi/ Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Pokok Tim Teknis tim substansi/ tim sesuai kebutuhan tiap-tiap tim atau Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan hari kerja atau hari kerja x dan ditetapkan identifikasi substansi/tim Harga satuan melalui Surat Perangkat Daerah teknis Keputusan Eselon II dan entitas utama terkait penanggulangan bencana provinsi berdasarkan ketentuan peraturan perundang-undangan Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 6 (enam) Opsional bidang tenaga ahli maksimal 1 (satu) tiap-tiap tenaga ahli x Jumlah bulan bulan kebencanaan orang kerja x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 6 (enam) Opsional bidang tenaga ahli maksimal 1 (satu) tiap-tiap tenaga ahli x Jumlah bulan bulan perencanaan orang kerja x Harga pembangunan/ satuan kebijakan publik Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tim penulis Maksimal 6 (enam) Opsional tim penulis penulis maksimal 1 tiap-tiap tenaga x Jumlah bulan bulan (satu) orang penulis kerja x Harga satuan Lokakarya Transport Peserta Jumlah peserta', 'LAMPIRAN II (lanjutan 22)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (348, 'juklak-2-2026', 42, 'lampiran', 'LAMPIRAN II (lanjutan 23)', NULL, 32, 'Jumlah lokakarya Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah lokakarya x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali lokakarya kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja total untuk 1 (satu) Jumlah lokakarya x kali Lokakarya) Harga Satuan Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 5 (lima) Opsional dan fasilitator narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Diskusi total untuk 1 (satu) Teknis x Harga kali Diskusi Teknis) Satuan Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (348, 'Jumlah lokakarya Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah lokakarya x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali lokakarya kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja total untuk 1 (satu) Jumlah lokakarya x kali Lokakarya) Harga Satuan Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 5 (lima) Opsional dan fasilitator narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Diskusi total untuk 1 (satu) Teknis x Harga kali Diskusi Teknis) Satuan Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai', 'LAMPIRAN II (lanjutan 23)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (349, 'juklak-2-2026', 43, 'lampiran', 'LAMPIRAN II (lanjutan 24)', NULL, 32, 'kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Konsultasi Transport Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta x Pokok Publik sesuai kebutuhan Publik sesuai Jumlah Konsultasi (Lokakarya kebutuhan Publik x Harga Akhir) satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 Jumlah jam kerja x Publik (empat) jam kerja Jumlah Konsultasi total untuk 1 (satu) Publik x Harga kali Konsultasi Satuan Publik) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (349, 'kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Konsultasi Transport Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta x Pokok Publik sesuai kebutuhan Publik sesuai Jumlah Konsultasi (Lokakarya kebutuhan Publik x Harga Akhir) satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 Jumlah jam kerja x Publik (empat) jam kerja Jumlah Konsultasi total untuk 1 (satu) Publik x Harga kali Konsultasi Satuan Publik) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah', 'LAMPIRAN II (lanjutan 24)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (350, 'juklak-2-2026', 44, 'lampiran', 'LAMPIRAN II (lanjutan 25)', NULL, 32, 'Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Asistensi BNPB Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai hasil Teknis sesuai Jumlah Asistensi x identifikasi tim kebutuhan Harga satuan teknis Perjalanan Dinas Jumlah perwakilan Jumlah asistensi Jumlah tim 1. Bila Opsional Perwakilan Tim tim sesuai yang dilakukan perwakilan x dilaksanakan Penyusun dan kebutuhan Jumlah asistensi x secara tatap BPBD/Tim (maksimal 3 (tiga) Harga satuan muka Substansi orang) 2. Maksimal 3 (tiga) kali Asistensi ke BNPB Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai kebutuhan Publik sesuai Asistensi x Jumlah kebutuhan Asistensi x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Asistensi x Opsional lembar materi yang Teknis sesuai Harga satuan dibutuhkan kebutuhan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Penanggulangan penggandaan x penggandaan Bencana Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Kegiatan penyusunan dokumen untuk segala bentuk perencanaan terkait penyelenggaraan penanggulangan bencana di Operasional tingkat kabupaten/kota maupun komunitas, yang');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (350, 'Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Asistensi BNPB Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai hasil Teknis sesuai Jumlah Asistensi x identifikasi tim kebutuhan Harga satuan teknis Perjalanan Dinas Jumlah perwakilan Jumlah asistensi Jumlah tim 1. Bila Opsional Perwakilan Tim tim sesuai yang dilakukan perwakilan x dilaksanakan Penyusun dan kebutuhan Jumlah asistensi x secara tatap BPBD/Tim (maksimal 3 (tiga) Harga satuan muka Substansi orang) 2. Maksimal 3 (tiga) kali Asistensi ke BNPB Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai kebutuhan Publik sesuai Asistensi x Jumlah kebutuhan Asistensi x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Asistensi x Opsional lembar materi yang Teknis sesuai Harga satuan dibutuhkan kebutuhan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Penanggulangan penggandaan x penggandaan Bencana Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Kegiatan penyusunan dokumen untuk segala bentuk perencanaan terkait penyelenggaraan penanggulangan bencana di Operasional tingkat kabupaten/kota maupun komunitas, yang', 'LAMPIRAN II (lanjutan 25)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (351, 'juklak-2-2026', 45, 'lampiran', 'LAMPIRAN II (lanjutan 26)', NULL, 32, 'berisikan pengenalan dan pengkajian ancaman, pemahaman tentang kerentanan masyarakat, analisis kemungkinan dampak bencana, pilihan tindakan pengurangan risiko bencana, penentuan mekanisme kesiapan dan penanggulangan dampak bencana, dan alokasi tugas kewenangan dan sumber daya yang tersedia.
Khusus untuk pilihan tindakan pengurangan risiko bencana dijabarkan dalam bentuk program, kegiatan, indikator dan tahun pelaksanaan kegiatan beserta rincian anggarannya minimal untuk 5 (lima) tahun perencanaan.
Prasyarat permohonan: memiliki Dokumen Kajian Risiko Bencana yang masih berlaku Tim Substansi/ Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Pokok Tim Teknis tim substansi/ tim sesuai kebutuhan atau hari kerja tiap- Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan tiap tim substansi/ atau hari kerja x dan ditetapkan identifikasi tim teknis Harga satuan melalui Surat perangkat daerah Keputusan Eselon II dan entitas utama terkait penanggulangan bencana kabupaten/kota berdasarkan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (351, 'berisikan pengenalan dan pengkajian ancaman, pemahaman tentang kerentanan masyarakat, analisis kemungkinan dampak bencana, pilihan tindakan pengurangan risiko bencana, penentuan mekanisme kesiapan dan penanggulangan dampak bencana, dan alokasi tugas kewenangan dan sumber daya yang tersedia.
Khusus untuk pilihan tindakan pengurangan risiko bencana dijabarkan dalam bentuk program, kegiatan, indikator dan tahun pelaksanaan kegiatan beserta rincian anggarannya minimal untuk 5 (lima) tahun perencanaan.
Prasyarat permohonan: memiliki Dokumen Kajian Risiko Bencana yang masih berlaku Tim Substansi/ Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Pokok Tim Teknis tim substansi/ tim sesuai kebutuhan atau hari kerja tiap- Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan tiap tim substansi/ atau hari kerja x dan ditetapkan identifikasi tim teknis Harga satuan melalui Surat perangkat daerah Keputusan Eselon II dan entitas utama terkait penanggulangan bencana kabupaten/kota berdasarkan ketentuan peraturan perundang-undangan.', 'LAMPIRAN II (lanjutan 26)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (352, 'juklak-2-2026', 46, 'lampiran', 'LAMPIRAN II (lanjutan 27)', NULL, 38, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 6 (enam) Opsional bidang tenaga ahli maksimal 1 (satu) tiap-tiap tenaga ahli x Jumlah bulan bulan kebencanaan orang kerja x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 6 (enam) Opsional bidang tenaga ahli maksimal 1 (satu) tiap-tiap tenaga ahli x Jumlah bulan bulan perencanaan orang kerja x Harga pembangunan/ satuan kebijakan publik Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tim penulis Maksimal 6 (enam) Opsional tim penulis penulis maksimal 1 tiap-tiap tenaga x Jumlah bulan bulan (satu) orang penulis kerja x Harga satuan Lokakarya Transport Peserta Jumlah peserta Jumlah lokakarya Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah lokakarya x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali lokakarya kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah lokakarya x total untuk 1 (satu) Harga Satuan kali Lokakarya) Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya');
