INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (353, 'juklak-2-2026', 47, 'lampiran', 'LAMPIRAN II (lanjutan 28)', NULL, 38, 'Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 5 (lima) Opsional dan fasilitator narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Diskusi total untuk 1 (satu) Teknis x Harga kali Diskusi Teknis) Satuan Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Konsultasi Transport Peserta Jumlah peserta Jumlah');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (353, 'Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 5 (lima) Opsional dan fasilitator narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Diskusi total untuk 1 (satu) Teknis x Harga kali Diskusi Teknis) Satuan Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Konsultasi Transport Peserta Jumlah peserta Jumlah', 'LAMPIRAN II (lanjutan 28)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (354, 'juklak-2-2026', 48, 'lampiran', 'LAMPIRAN II (lanjutan 29)', NULL, 38, 'Konsultasi Jumlah peserta x Pokok Publik sesuai kebutuhan Publik sesuai Jumlah rapat x (Lokakarya kebutuhan Harga satuan Akhir) Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 Jumlah jam kerja x Publik (empat) jam kerja Jumlah rapat x total untuk 1 (satu) Harga Satuan kali Konsultasi Publik) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah rapat x kebutuhan Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah rapat x kebutuhan Harga satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah rapat x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah rapat x Opsional lembar materi yang Publik sesuai Harga satuan dibutuhkan kebutuhan Asistensi BNPB Snack rapat Jumlah peserta Jumlah asistensi Jumlah peserta x Pokok sesuai hasil yang dilakukan Jumlah rapat x identifikasi tim Harga satuan teknis Perjalanan Dinas Jumlah perwakilan Jumlah asistensi Jumlah tim 1. Bila Pokok Perwakilan Tim tim sesuai yang dilakukan perwakilan x dilaksanakan Penyusun dan kebutuhan Jumlah asistensi x secara tatap (Jika BPBD/Tim (maksimal 3 (tiga) Harga satuan muka dilakukan Substansi orang) 2.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (354, 'Konsultasi Jumlah peserta x Pokok Publik sesuai kebutuhan Publik sesuai Jumlah rapat x (Lokakarya kebutuhan Harga satuan Akhir) Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 Jumlah jam kerja x Publik (empat) jam kerja Jumlah rapat x total untuk 1 (satu) Harga Satuan kali Konsultasi Publik) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah rapat x kebutuhan Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah rapat x kebutuhan Harga satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah rapat x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah rapat x Opsional lembar materi yang Publik sesuai Harga satuan dibutuhkan kebutuhan Asistensi BNPB Snack rapat Jumlah peserta Jumlah asistensi Jumlah peserta x Pokok sesuai hasil yang dilakukan Jumlah rapat x identifikasi tim Harga satuan teknis Perjalanan Dinas Jumlah perwakilan Jumlah asistensi Jumlah tim 1. Bila Pokok Perwakilan Tim tim sesuai yang dilakukan perwakilan x dilaksanakan Penyusun dan kebutuhan Jumlah asistensi x secara tatap (Jika BPBD/Tim (maksimal 3 (tiga) Harga satuan muka dilakukan Substansi orang) 2.', 'LAMPIRAN II (lanjutan 29)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (355, 'juklak-2-2026', 49, 'lampiran', 'LAMPIRAN II (lanjutan 30)', NULL, 38, 'Maksimal 3 (tiga) secara kali Asistensi ke Luring) BNPB Konsumsi rapat Jumlah peserta Jumlah asistensi Jumlah peserta x Opsional sesuai kebutuhan yang dilakukan Jumlah rapat x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah asistensi Jumlah rapat x Opsional lembar materi yang yang dilakukan Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Penanggulangan penggandaan x penggandaan Bencana Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan KEGIATAN : PENYUSUNAN RENCANA KONTINGENSI SUB KATEGORI : PERENCANAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Kegiatan penyusunan dokumen yang sah dalam bentuk perencanaan strategis, taktis, maupun analisis kebutuhan dan Operasional mobilisasi sumber daya untuk penanganan situasi darurat bencana nasional pada satu jenis bahaya tertentu yang disusun berdasarkan satu skenario dampak dan kejadian yang disepakati.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (355, 'Maksimal 3 (tiga) secara kali Asistensi ke Luring) BNPB Konsumsi rapat Jumlah peserta Jumlah asistensi Jumlah peserta x Opsional sesuai kebutuhan yang dilakukan Jumlah rapat x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah asistensi Jumlah rapat x Opsional lembar materi yang yang dilakukan Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Penanggulangan penggandaan x penggandaan Bencana Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan KEGIATAN : PENYUSUNAN RENCANA KONTINGENSI SUB KATEGORI : PERENCANAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Kegiatan penyusunan dokumen yang sah dalam bentuk perencanaan strategis, taktis, maupun analisis kebutuhan dan Operasional mobilisasi sumber daya untuk penanganan situasi darurat bencana nasional pada satu jenis bahaya tertentu yang disusun berdasarkan satu skenario dampak dan kejadian yang disepakati.', 'LAMPIRAN II (lanjutan 30)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (356, 'juklak-2-2026', 50, 'lampiran', 'LAMPIRAN II (lanjutan 31)', NULL, 42, 'Rencana kontingensi yang disusun oleh kementerian/lembaga selain BNPB, harus melalui kesepakatan/koordinasi substansi dengan BNPB Tim Substansi Biaya honorarium Jumlah tim Jumlah bulan kerja Jumlah personil x Tim Substansi Pokok tim substansi substansi sesuai atau hari kerja tiap- Jumlah bulan kerja adalah diluar tenaga kebutuhan tiap tim personil atau hari kerja x ahli dan ditetapkan berdasarkan tim substansi Harga satuan melalui Surat identifikasi Keputusan Eselon I kementerian/lemba ga dan entitas terkait operasi penanganan darurat bencana di nasional Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga Ahli Biaya tenaga ahli/ Jumlah tenaga ahli Jumlah bulan kerja Jumlah personil x Maksimal 30 OB Opsional sesuai kebutuhan tiap-tiap tenaga ahli Jumlah bulan kerja (maksimal 5 (lima) x Harga satuan orang) Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tenaga Maksimal 12 OB Opsional tenaga penulis penulis sesuai tiap-tiap personil penulis x Jumlah kebutuhan tenaga penulis (maksimal 3 (tiga) bulan kerja x Harga orang) satuan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Maksimal 3 sesi Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi (persiapan, kebutuhan Teknis x Harga penyusunan, dan satuan finalisasi) - (total maksimal 10 hari) Biaya honorarium Jumlah tenaga Jumlah jam kerja Jumlah tenaga');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (356, 'Rencana kontingensi yang disusun oleh kementerian/lembaga selain BNPB, harus melalui kesepakatan/koordinasi substansi dengan BNPB Tim Substansi Biaya honorarium Jumlah tim Jumlah bulan kerja Jumlah personil x Tim Substansi Pokok tim substansi substansi sesuai atau hari kerja tiap- Jumlah bulan kerja adalah diluar tenaga kebutuhan tiap tim personil atau hari kerja x ahli dan ditetapkan berdasarkan tim substansi Harga satuan melalui Surat identifikasi Keputusan Eselon I kementerian/lemba ga dan entitas terkait operasi penanganan darurat bencana di nasional Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga Ahli Biaya tenaga ahli/ Jumlah tenaga ahli Jumlah bulan kerja Jumlah personil x Maksimal 30 OB Opsional sesuai kebutuhan tiap-tiap tenaga ahli Jumlah bulan kerja (maksimal 5 (lima) x Harga satuan orang) Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tenaga Maksimal 12 OB Opsional tenaga penulis penulis sesuai tiap-tiap personil penulis x Jumlah kebutuhan tenaga penulis (maksimal 3 (tiga) bulan kerja x Harga orang) satuan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Maksimal 3 sesi Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi (persiapan, kebutuhan Teknis x Harga penyusunan, dan satuan finalisasi) - (total maksimal 10 hari) Biaya honorarium Jumlah tenaga Jumlah jam kerja Jumlah tenaga', 'LAMPIRAN II (lanjutan 31)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (357, 'juklak-2-2026', 51, 'lampiran', 'LAMPIRAN II (lanjutan 32)', NULL, 42, 'Maksimal 4 OJ Opsional tenaga fasilitator fasilitator diskusi tenaga fasilitator fasilitator x Harga untuk tiap-tiap disesuaikan dengan disesuaikan dengan satuan pertemuan jumlah pertemuan kebutuhan yang menggunakan tenaga fasilitator Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu) kali Jumlah Konsultasi di luar Jabodetabek Jabodetabek atau Konsultasi Publik Publik x Jumlah sesuai kebutuhan (maksimal 2 (dua) hari x Harga satuan hari untuk 1 (satu) kali rapat) Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Uji Publik Transport Peserta Jumlah peserta Jumlah Uji publik Jumlah peserta x Maksimal 2 (dua) Pokok sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x kali Harga satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu) kali Jumlah Konsultasi di luar Jabodetabek Jabodetabek atau Konsultasi Publik Publik x Jumlah sesuai kebutuhan (maksimal 2 (dua) hari x Harga satuan hari untuk 1 (satu) kali rapat) Konsumsi rapat Jumlah peserta');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (357, 'Maksimal 4 OJ Opsional tenaga fasilitator fasilitator diskusi tenaga fasilitator fasilitator x Harga untuk tiap-tiap disesuaikan dengan disesuaikan dengan satuan pertemuan jumlah pertemuan kebutuhan yang menggunakan tenaga fasilitator Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu) kali Jumlah Konsultasi di luar Jabodetabek Jabodetabek atau Konsultasi Publik Publik x Jumlah sesuai kebutuhan (maksimal 2 (dua) hari x Harga satuan hari untuk 1 (satu) kali rapat) Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Uji Publik Transport Peserta Jumlah peserta Jumlah Uji publik Jumlah peserta x Maksimal 2 (dua) Pokok sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x kali Harga satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu) kali Jumlah Konsultasi di luar Jabodetabek Jabodetabek atau Konsultasi Publik Publik x Jumlah sesuai kebutuhan (maksimal 2 (dua) hari x Harga satuan hari untuk 1 (satu) kali rapat) Konsumsi rapat Jumlah peserta', 'LAMPIRAN II (lanjutan 32)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (358, 'juklak-2-2026', 52, 'lampiran', 'LAMPIRAN II (lanjutan 33)', NULL, 42, 'Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Uji publik x Opsional lembar materi yang Teknis sesuai Harga satuan dibutuhkan kebutuhan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kontingensi penggandaan x penggandaan Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Kegiatan penyusunan dokumen yang sah dalam bentuk perencanaan strategis, taktis, maupun analisis kebutuhan dan Operasional mobilisasi sumber daya untuk penanganan situasi darurat bencana provinsi pada satu jenis bahaya tertentu yang disusun berdasarkan satu skenario dampak dan kejadian yang disepakati.
Prasyarat permohonan: memiliki Dokumen Kajian Risiko Bencana yang masih berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (358, 'Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Uji publik x Opsional lembar materi yang Teknis sesuai Harga satuan dibutuhkan kebutuhan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kontingensi penggandaan x penggandaan Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Kegiatan penyusunan dokumen yang sah dalam bentuk perencanaan strategis, taktis, maupun analisis kebutuhan dan Operasional mobilisasi sumber daya untuk penanganan situasi darurat bencana provinsi pada satu jenis bahaya tertentu yang disusun berdasarkan satu skenario dampak dan kejadian yang disepakati.
Prasyarat permohonan: memiliki Dokumen Kajian Risiko Bencana yang masih berlaku.', 'LAMPIRAN II (lanjutan 33)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (359, 'juklak-2-2026', 53, 'lampiran', 'LAMPIRAN II (lanjutan 34)', NULL, 45, 'Tim Substansi Biaya honorarium Jumlah tim Jumlah bulan kerja Jumlah personil x Tim Substansi Pokok tim substansi substansi sesuai atau hari kerja tiap- Jumlah bulan kerja adalah diluar tenaga kebutuhan tiap tim personil atau hari kerja x ahli dan ditetapkan berdasarkan tim substansi Harga satuan melalui Surat identifikasi Keputusan Eselon II kementerian/lemba ga dan entitas terkait operasi penanganan darurat bencana provinsi Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga Ahli Biaya tenaga ahli/ Jumlah tenaga ahli Jumlah bulan kerja Jumlah personil x Maksimal 30 OB Opsional sesuai kebutuhan tiap-tiap tenaga ahli Jumlah bulan kerja (maksimal 5 (lima) x Harga satuan orang) Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tenaga Maksimal 12 OB Opsional tenaga penulis penulis sesuai tiap-tiap personil penulis x Jumlah kebutuhan tenaga penulis bulan kerja x Harga (maksimal 3 (tiga) satuan orang) Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Maksimal 3 (tiga) sesi Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi (persiapan, kebutuhan Teknis x Harga penyusunan, dan satuan finalisasi) - (total maksimal 10 (sepuluh) hari) Biaya honorarium Jumlah tenaga Jumlah jam kerja Jumlah tenaga Maksimal 4 OJ Opsional tenaga fasilitator fasilitator diskusi tenaga fasilitator fasilitator x Harga untuk tiap-tiap');
