INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (360, 'juklak-2-2026', 54, 'lampiran', 'LAMPIRAN II (lanjutan 35)', NULL, 45, 'disesuaikan dengan disesuaikan dengan satuan pertemuan jumlah pertemuan kebutuhan yang menggunakan tenaga fasilitator Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Uji Publik Transport Peserta Jumlah peserta Jumlah Uji publik Jumlah peserta x Maksimal 2 (dua) Pokok sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x kali Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Uji publik x Opsional lembar materi yang Teknis sesuai Harga satuan dibutuhkan kebutuhan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kontingensi penggandaan penggandaan x Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar');
