INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (363, 'diskusi tenaga fasilitator fasilitator x Harga untuk tiap-tiap disesuaikan dengan disesuaikan dengan satuan pertemuan jumlah pertemuan kebutuhan yang menggunakan tenaga fasilitator Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Uji Publik Transport Peserta Jumlah peserta Jumlah Uji publik Jumlah peserta x Maksimal 2 (dua) Pokok sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x kali Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Uji publik x Opsional lembar materi yang Teknis sesuai Harga satuan dibutuhkan kebutuhan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kontingensi penggandaan x penggandaan Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x', 'LAMPIRAN II (lanjutan 38)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (364, 'juklak-2-2026', 58, 'lampiran', 'LAMPIRAN II (lanjutan 39)', NULL, 47, 'Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan KEGIATAN : PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA SUB KATEGORI : PERENCANAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Kegiatan penyusunan dokumen yang sah untuk penguatan kesiapsiagaan dan kesiagaan menghadapi bencana dalam bentuk Operasional kerangka kerja penanganan kedaruratan untuk berbagai ancaman bencana nasional, yang membagi peran dan tanggung jawab secara umum untuk efektivitas respon penanggulangan kedaruratan bencana, sebagai acuan bagi dalam menanggapi keadaan darurat bencana nasional.
Rencana Penanggulangan Kedaruratan Bencana memuat garis besar metode dan pelaksanaan penyelenggaraan bersama operasi kedaruratan multi ancaman bencana yang akan dilaksanakan secara menyeluruh oleh Kementerian/Lembaga, TNI/Polri, dan para stakeholder utama yang terlibat, beserta penggerakan sumber daya terkait secara terintegrasi dalam satu organisasi komando.
Rencana Penanggulangan Kedaruratan Bencana secara normatif menjabarkan doktrin, prinsip, kebijakan, strategi, asumsi, pembagian peran dan tanggung jawab, garis koordinasi dan komando, mekanisme kerja dan prioritas operasional yang disepakati, ditetapkan dan dianut sebagai panduan dalam mengatasi situasi kedaruratan bencana.
Penyusunan Rencana Penanggulangan Kedaruratan Bencana dilakukan di saat situasi normal atau sebelum bencana terjadi oleh pemerintah melalui fungsi koordinasi dan pelaksana BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (364, 'Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan KEGIATAN : PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA SUB KATEGORI : PERENCANAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Kegiatan penyusunan dokumen yang sah untuk penguatan kesiapsiagaan dan kesiagaan menghadapi bencana dalam bentuk Operasional kerangka kerja penanganan kedaruratan untuk berbagai ancaman bencana nasional, yang membagi peran dan tanggung jawab secara umum untuk efektivitas respon penanggulangan kedaruratan bencana, sebagai acuan bagi dalam menanggapi keadaan darurat bencana nasional.
Rencana Penanggulangan Kedaruratan Bencana memuat garis besar metode dan pelaksanaan penyelenggaraan bersama operasi kedaruratan multi ancaman bencana yang akan dilaksanakan secara menyeluruh oleh Kementerian/Lembaga, TNI/Polri, dan para stakeholder utama yang terlibat, beserta penggerakan sumber daya terkait secara terintegrasi dalam satu organisasi komando.
Rencana Penanggulangan Kedaruratan Bencana secara normatif menjabarkan doktrin, prinsip, kebijakan, strategi, asumsi, pembagian peran dan tanggung jawab, garis koordinasi dan komando, mekanisme kerja dan prioritas operasional yang disepakati, ditetapkan dan dianut sebagai panduan dalam mengatasi situasi kedaruratan bencana.
Penyusunan Rencana Penanggulangan Kedaruratan Bencana dilakukan di saat situasi normal atau sebelum bencana terjadi oleh pemerintah melalui fungsi koordinasi dan pelaksana BNPB.', 'LAMPIRAN II (lanjutan 39)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (365, 'juklak-2-2026', 59, 'lampiran', 'LAMPIRAN II (lanjutan 40)', NULL, 50, 'Tim Substansi/ Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Pokok Tim Teknis tim substansi/tim Sesuai kebutuhan atau hari kerja tiap- Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan tiap tim substansi/ atau hari kerja x dan ditetapkan identifikasi tim teknis Harga satuan melalui Surat kementerian/ Keputusan Eselon I lembaga dan entitas terkait operasi penanganan darurat bencana di nasional berdasarkan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (365, 'Tim Substansi/ Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Pokok Tim Teknis tim substansi/tim Sesuai kebutuhan atau hari kerja tiap- Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan tiap tim substansi/ atau hari kerja x dan ditetapkan identifikasi tim teknis Harga satuan melalui Surat kementerian/ Keputusan Eselon I lembaga dan entitas terkait operasi penanganan darurat bencana di nasional berdasarkan ketentuan peraturan perundang-undangan.', 'LAMPIRAN II (lanjutan 40)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (366, 'juklak-2-2026', 60, 'lampiran', 'LAMPIRAN II (lanjutan 41)', NULL, 51, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga Ahli/ Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 18 OB Opsional Narasumber tenaga ahli/ (maksimal 3 (tiga) tiap-tiap tenaga ahli x Jumlah bulan narasumber orang) kerja x Harga satuan Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tim penulis Maksimal 8 OB Opsional tenaga penulis penulis (maksimal 2 tiap-tiap tenaga x Jumlah bulan (dua) orang) penulis kerja x Harga satuan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Maksimal 5 (lima) Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kali kebutuhan Teknis x Harga satuan Biaya honorarium Jumlah tenaga Jumlah jam kerja Jumlah tenaga Maksimal 4 OJ Opsional tenaga fasilitator fasilitator diskusi tenaga fasilitator fasilitator x Harga untuk tiap-tiap disesuaikan dengan disesuaikan dengan satuan pertemuan jumlah pertemuan kebutuhan yang menggunakan tenaga fasilitator Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu) kali Jumlah Konsultasi di luar Jabodetabek Jabodetabek atau Konsultasi Publik Publik x Jumlah sesuai kebutuhan (maksimal 2 (dua) hari x Harga satuan hari untuk 1 (satu) kali rapat) Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (366, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga Ahli/ Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 18 OB Opsional Narasumber tenaga ahli/ (maksimal 3 (tiga) tiap-tiap tenaga ahli x Jumlah bulan narasumber orang) kerja x Harga satuan Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tim penulis Maksimal 8 OB Opsional tenaga penulis penulis (maksimal 2 tiap-tiap tenaga x Jumlah bulan (dua) orang) penulis kerja x Harga satuan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Maksimal 5 (lima) Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kali kebutuhan Teknis x Harga satuan Biaya honorarium Jumlah tenaga Jumlah jam kerja Jumlah tenaga Maksimal 4 OJ Opsional tenaga fasilitator fasilitator diskusi tenaga fasilitator fasilitator x Harga untuk tiap-tiap disesuaikan dengan disesuaikan dengan satuan pertemuan jumlah pertemuan kebutuhan yang menggunakan tenaga fasilitator Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu) kali Jumlah Konsultasi di luar Jabodetabek Jabodetabek atau Konsultasi Publik Publik x Jumlah sesuai kebutuhan (maksimal 2 (dua) hari x Harga satuan hari untuk 1 (satu) kali rapat) Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan', 'LAMPIRAN II (lanjutan 41)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (367, 'juklak-2-2026', 61, 'lampiran', 'LAMPIRAN II (lanjutan 42)', NULL, 51, 'Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Uji Publik Transport Peserta Jumlah peserta Jumlah Uji publik Jumlah peserta x Maksimal 2 (dua) Pokok sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x kali Harga satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu) kali Jumlah Konsultasi di luar Jabodetabek Jabodetabek atau Konsultasi Publik Publik x Jumlah sesuai kebutuhan (maksimal 2 (dua) hari x Harga satuan hari untuk 1 (satu) kali rapat) Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Uji publik x Opsional lembar materi yang Teknis sesuai Harga satuan dibutuhkan kebutuhan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kontingensi penggandaan x penggandaan Harga satuan Cetak Laporan Paket');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (367, 'Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Uji Publik Transport Peserta Jumlah peserta Jumlah Uji publik Jumlah peserta x Maksimal 2 (dua) Pokok sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x kali Harga satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu) kali Jumlah Konsultasi di luar Jabodetabek Jabodetabek atau Konsultasi Publik Publik x Jumlah sesuai kebutuhan (maksimal 2 (dua) hari x Harga satuan hari untuk 1 (satu) kali rapat) Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Uji publik x Opsional lembar materi yang Teknis sesuai Harga satuan dibutuhkan kebutuhan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kontingensi penggandaan x penggandaan Harga satuan Cetak Laporan Paket', 'LAMPIRAN II (lanjutan 42)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (368, 'juklak-2-2026', 62, 'lampiran', 'LAMPIRAN II (lanjutan 43)', NULL, 51, 'dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Kegiatan penyusunan dokumen yang sah untuk penguatan kesiapsiagaan dan kesiagaan menghadapi bencana dalam bentuk Operasional kerangka kerja penanganan kedaruratan untuk berbagai ancaman bencana provinsi, yang membagi peran dan tanggung jawab secara umum untuk efektivitas respon penanggulangan kedaruratan bencana, sebagai acuan bagi dalam menanggapi keadaan darurat bencana provinsi.
Rencana Penanggulangan Kedaruratan Bencana memuat garis besar metode dan pelaksanaan penyelenggaraan bersama operasi kedaruratan multi ancaman bencana yang akan dilaksanakan secara menyeluruh oleh Perangkat Daerah, TNI/Polri, dan para stakeholder utama yang terlibat, beserta penggerakan sumber daya terkait secara terintegrasi dalam satu organisasi komando.
Rencana Penanggulangan Kedaruratan Bencana secara normatif menjabarkan doktrin, prinsip, kebijakan, strategi, asumsi, pembagian peran dan tanggung jawab, garis koordinasi dan komando, mekanisme kerja dan prioritas operasional yang disepakati, ditetapkan dan dianut sebagai panduan dalam mengatasi situasi kedaruratan bencana.
Penyusunan Rencana Penanggulangan Kedaruratan Bencana dilakukan di saat situasi normal atau sebelum bencana terjadi oleh pemerintah melalui fungsi koordinasi BPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (368, 'dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Kegiatan penyusunan dokumen yang sah untuk penguatan kesiapsiagaan dan kesiagaan menghadapi bencana dalam bentuk Operasional kerangka kerja penanganan kedaruratan untuk berbagai ancaman bencana provinsi, yang membagi peran dan tanggung jawab secara umum untuk efektivitas respon penanggulangan kedaruratan bencana, sebagai acuan bagi dalam menanggapi keadaan darurat bencana provinsi.
Rencana Penanggulangan Kedaruratan Bencana memuat garis besar metode dan pelaksanaan penyelenggaraan bersama operasi kedaruratan multi ancaman bencana yang akan dilaksanakan secara menyeluruh oleh Perangkat Daerah, TNI/Polri, dan para stakeholder utama yang terlibat, beserta penggerakan sumber daya terkait secara terintegrasi dalam satu organisasi komando.
Rencana Penanggulangan Kedaruratan Bencana secara normatif menjabarkan doktrin, prinsip, kebijakan, strategi, asumsi, pembagian peran dan tanggung jawab, garis koordinasi dan komando, mekanisme kerja dan prioritas operasional yang disepakati, ditetapkan dan dianut sebagai panduan dalam mengatasi situasi kedaruratan bencana.
Penyusunan Rencana Penanggulangan Kedaruratan Bencana dilakukan di saat situasi normal atau sebelum bencana terjadi oleh pemerintah melalui fungsi koordinasi BPBD.', 'LAMPIRAN II (lanjutan 43)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (369, 'juklak-2-2026', 63, 'lampiran', 'LAMPIRAN II (lanjutan 44)', NULL, 53, 'Tim Substansi/ Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Pokok Tim Teknis tim substansi/tim Sesuai kebutuh-an atau hari kerja tiap- Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan tiap tim substansi/ atau hari kerja x dan ditetapkan identifikasi tim teknis Harga satuan melalui Surat Perangkat Daerah Keputusan Eselon II dan entitas terkait operasi penanganan darurat bencana di provinsi berdasarkan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (369, 'Tim Substansi/ Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Pokok Tim Teknis tim substansi/tim Sesuai kebutuh-an atau hari kerja tiap- Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan tiap tim substansi/ atau hari kerja x dan ditetapkan identifikasi tim teknis Harga satuan melalui Surat Perangkat Daerah Keputusan Eselon II dan entitas terkait operasi penanganan darurat bencana di provinsi berdasarkan ketentuan peraturan perundang-undangan.', 'LAMPIRAN II (lanjutan 44)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (370, 'juklak-2-2026', 64, 'lampiran', 'LAMPIRAN II (lanjutan 45)', NULL, 54, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga Ahli/ Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 18 OB Opsional Narasumber tenaga ahli/ (maksimal 3 (tiga) tiap-tiap tenaga ahli x Jumlah bulan narasumber orang) kerja x Harga satuan Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tim penulis Maksimal 8 OB Opsional tenaga penulis penulis (maksimal 2 tiap-tiap tenaga x Jumlah bulan (dua) orang) penulis kerja x Harga satuan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Maksimal 5 (lima) Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kali kebutuhan Teknis x Harga satuan Biaya honorarium Jumlah tenaga Jumlah jam kerja Jumlah tenaga Maksimal 4 OJ Opsional tenaga fasilitator fasilitator diskusi tenaga fasilitator fasilitator x Harga untuk tiap-tiap disesuaikan dengan disesuaikan dengan satuan pertemuan jumlah pertemuan kebutuhan yang menggunakan tenaga fasilitator Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (370, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga Ahli/ Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 18 OB Opsional Narasumber tenaga ahli/ (maksimal 3 (tiga) tiap-tiap tenaga ahli x Jumlah bulan narasumber orang) kerja x Harga satuan Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tim penulis Maksimal 8 OB Opsional tenaga penulis penulis (maksimal 2 tiap-tiap tenaga x Jumlah bulan (dua) orang) penulis kerja x Harga satuan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Maksimal 5 (lima) Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kali kebutuhan Teknis x Harga satuan Biaya honorarium Jumlah tenaga Jumlah jam kerja Jumlah tenaga Maksimal 4 OJ Opsional tenaga fasilitator fasilitator diskusi tenaga fasilitator fasilitator x Harga untuk tiap-tiap disesuaikan dengan disesuaikan dengan satuan pertemuan jumlah pertemuan kebutuhan yang menggunakan tenaga fasilitator Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis', 'LAMPIRAN II (lanjutan 45)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (371, 'juklak-2-2026', 65, 'lampiran', 'LAMPIRAN II (lanjutan 46)', NULL, 54, 'x Harga dibutuhkan kebutuhan satuan Uji Publik Transport Peserta Jumlah peserta Jumlah Uji publik Jumlah peserta x Maksimal 2 (dua) Pokok sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x kali Harga satuan Konsumsi rapat Jumlah peserta Jumlah Uji publik Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x Harga satuan Snack rapat Jumlah peserta Jumlah Uji publik Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Uji publik Jumlah Uji publik x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kontingensi penggandaan x penggandaan Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Kegiatan penyusunan dokumen yang sah untuk penguatan kesiapsiagaan dan kesiagaan menghadapi bencana dalam bentuk Operasional kerangka kerja penanganan kedaruratan untuk berbagai ancaman bencana kabupaten/kota, yang membagi peran dan tanggung jawab secara umum untuk efektivitas respon penanggulangan kedaruratan bencana, sebagai acuan bagi dalam menanggapi keadaan darurat bencana kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (371, 'x Harga dibutuhkan kebutuhan satuan Uji Publik Transport Peserta Jumlah peserta Jumlah Uji publik Jumlah peserta x Maksimal 2 (dua) Pokok sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x kali Harga satuan Konsumsi rapat Jumlah peserta Jumlah Uji publik Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x Harga satuan Snack rapat Jumlah peserta Jumlah Uji publik Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Uji publik Jumlah Uji publik x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kontingensi penggandaan x penggandaan Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Kegiatan penyusunan dokumen yang sah untuk penguatan kesiapsiagaan dan kesiagaan menghadapi bencana dalam bentuk Operasional kerangka kerja penanganan kedaruratan untuk berbagai ancaman bencana kabupaten/kota, yang membagi peran dan tanggung jawab secara umum untuk efektivitas respon penanggulangan kedaruratan bencana, sebagai acuan bagi dalam menanggapi keadaan darurat bencana kabupaten/kota.', 'LAMPIRAN II (lanjutan 46)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (372, 'juklak-2-2026', 66, 'lampiran', 'LAMPIRAN II (lanjutan 47)', NULL, 55, 'Rencana Penanggulangan Kedaruratan Bencana memuat garis besar metode dan pelaksanaan penyelenggaraan bersama operasi kedaruratan multi ancaman bencana yang akan dilaksanakan secara menyeluruh oleh Perangkat Daerah, TNI/Polri, PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA dan para stakeholder utama yang terlibat, beserta penggerakan sumber daya terkait secara terintegrasi dalam satu organisasi komando.
Rencana Penanggulangan Kedaruratan Bencana secara normatif menjabarkan doktrin, prinsip, kebijakan, strategi, asumsi, pembagian peran dan tanggung jawab, garis koordinasi dan komando, mekanisme kerja dan prioritas operasional yang disepakati, ditetapkan dan dianut sebagai panduan dalam mengatasi situasi kedaruratan bencana.
Penyusunan Rencana Penanggulangan Kedaruratan Bencana dilakukan di saat situasi normal atau sebelum bencana terjadi oleh pemerintah melalui fungsi koordinasi BPBD.
Tim Substansi/ Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Pokok Tim Teknis tim substansi/tim Sesuai kebutuhan atau hari kerja tiap- Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan tiap tim substansi/ atau hari kerja x dan ditetapkan identifikasi tim teknis Harga satuan melalui Surat Perangkat Daerah Keputusan Eselon II dan entitas terkait operasi penanganan darurat bencana di kabupaten/kota berdasarkan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (372, 'Rencana Penanggulangan Kedaruratan Bencana memuat garis besar metode dan pelaksanaan penyelenggaraan bersama operasi kedaruratan multi ancaman bencana yang akan dilaksanakan secara menyeluruh oleh Perangkat Daerah, TNI/Polri, PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA dan para stakeholder utama yang terlibat, beserta penggerakan sumber daya terkait secara terintegrasi dalam satu organisasi komando.
Rencana Penanggulangan Kedaruratan Bencana secara normatif menjabarkan doktrin, prinsip, kebijakan, strategi, asumsi, pembagian peran dan tanggung jawab, garis koordinasi dan komando, mekanisme kerja dan prioritas operasional yang disepakati, ditetapkan dan dianut sebagai panduan dalam mengatasi situasi kedaruratan bencana.
Penyusunan Rencana Penanggulangan Kedaruratan Bencana dilakukan di saat situasi normal atau sebelum bencana terjadi oleh pemerintah melalui fungsi koordinasi BPBD.
Tim Substansi/ Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Pokok Tim Teknis tim substansi/tim Sesuai kebutuhan atau hari kerja tiap- Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan tiap tim substansi/ atau hari kerja x dan ditetapkan identifikasi tim teknis Harga satuan melalui Surat Perangkat Daerah Keputusan Eselon II dan entitas terkait operasi penanganan darurat bencana di kabupaten/kota berdasarkan ketentuan peraturan perundang-undangan.', 'LAMPIRAN II (lanjutan 47)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (373, 'juklak-2-2026', 67, 'lampiran', 'LAMPIRAN II (lanjutan 48)', NULL, 56, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga Ahli/ Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 18 OB Opsional Narasumber tenaga ahli/ (maksimal 3 (tiga) tiap-tiap tenaga ahli x Jumlah bulan narasumber orang) kerja x Harga satuan Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tim penulis Maksimal 8 OB Opsional tenaga penulis penulis (maksimal 2 tiap-tiap tenaga x Jumlah bulan (dua) orang) penulis kerja x Harga satuan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Maksimal 5 (lima) Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kali kebutuhan Teknis x Harga satuan Biaya honorarium Jumlah tenaga Jumlah jam kerja Jumlah tenaga Maksimal 4 OJ Opsional tenaga fasilitator fasilitator diskusi tenaga fasilitator fasilitator x Harga untuk tiap-tiap disesuaikan dengan disesuaikan dengan satuan pertemuan jumlah pertemuan kebutuhan yang menggunakan tenaga fasilitator Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Uji publik x kebutuhan Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis');
