INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (374, 'juklak-2-2026', 68, 'lampiran', 'LAMPIRAN II (lanjutan 49)', NULL, 56, 'x Harga dibutuhkan kebutuhan satuan Uji Publik Transport Peserta Jumlah peserta Jumlah Uji publik Jumlah peserta x Maksimal 2 (dua) Pokok sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x kali Harga satuan Konsumsi rapat Jumlah peserta Jumlah Uji publik Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x Harga satuan Snack rapat Jumlah peserta Jumlah Uji publik Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Uji publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Uji publik Jumlah Uji publik x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kontingensi penggandaan x penggandaan Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan KEGIATAN : PENYUSUNAN RENCANA KESIAPSIAGAAN LOGISTIK DAN PERALATAN SUB KATEGORI : PERENCANAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Seluruh rangkaian kegiatan penyusunan dokumen analisis dan perencanaan pemenuhan logistik dan peralatan sesuai Operasional kewenangan kementerian/lembaga, baik logistik dan peralatan yang bersifat generik maupun spesifik yang dibutuhkan untuk kesiapsiagaan dan penanganan darurat tiap-tiap jenis ancaman melalui identifikasi kebutuhan, data, dan analisis untuk');
