INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (375, 'juklak-2-2026', 69, 'lampiran', 'LAMPIRAN II (lanjutan 50)', NULL, 56, 'mencapai Standar logistik dan peralatan yang berlaku.
Penyusunan Rencana Kesiapsiagaan Logistik dan Peralatan mengacu pada 5 (lima) komponen rencana kesiapsiagaan logistik dan peralatan, yaitu: a) Kemitraan; b) pemetaan sumber daya dan gap; c) penyusunan konsep operasi logistik dan peralatan; d) peningkatan kapasitas; dan e) pengujian konsep operasi logistik dan peralatan.
