INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (377, 'juklak-2-2026', 71, 'lampiran', 'LAMPIRAN II (lanjutan 52)', NULL, 60, 'Jabodetabek Jabodetabek atau lokakarya Jumlah hari x sesuai kebutuhan (Maksimal 3 hari Harga satuan untuk 1 (satu) kali lokakarya) Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 5 (lima) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Diskusi total untuk 1 (satu) Teknis x Harga kali Diskusi Teknis) Satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu) kali Diskusi Jumlah Diskusi di luar Jabodetabek Jabodetabek atau Teknis (maksimal 4 Teknis x Jumlah sesuai kebutuhan hari untuk 1 (satu) hari x Harga satuan kali Diskusi Teknis) Paket pertemuan Jumlah peserta');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (377, 'Jabodetabek Jabodetabek atau lokakarya Jumlah hari x sesuai kebutuhan (Maksimal 3 hari Harga satuan untuk 1 (satu) kali lokakarya) Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 5 (lima) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Diskusi total untuk 1 (satu) Teknis x Harga kali Diskusi Teknis) Satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu) kali Diskusi Jumlah Diskusi di luar Jabodetabek Jabodetabek atau Teknis (maksimal 4 Teknis x Jumlah sesuai kebutuhan hari untuk 1 (satu) hari x Harga satuan kali Diskusi Teknis) Paket pertemuan Jumlah peserta', 'LAMPIRAN II (lanjutan 52)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (378, 'juklak-2-2026', 72, 'lampiran', 'LAMPIRAN II (lanjutan 53)', NULL, 60, 'Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Pengujian Penyediaan dan Jumlah unit sesuai Jumlah hari sesuai Jumlah unit x Opsional konsep operasi mobilisasi kebutuhan sesi pengujian Jumlah hari x logistik dan Perlengkapan konsep operasi Harga satuan peralatan logistik dan peralatan Alat tulis Jumlah alat tulis Sesuai kebutuhan Jumlah alat tulis x Opsional sesuai kebutuhan Harga satuan Konsultasi Transport Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta x Pokok Publik sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 Jumlah jam kerja x Publik (empat) jam kerja Jumlah Konsultasi total untuk 1 (satu) kali Konsultasi Publik x Harga Publik) Satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (378, 'Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Pengujian Penyediaan dan Jumlah unit sesuai Jumlah hari sesuai Jumlah unit x Opsional konsep operasi mobilisasi kebutuhan sesi pengujian Jumlah hari x logistik dan Perlengkapan konsep operasi Harga satuan peralatan logistik dan peralatan Alat tulis Jumlah alat tulis Sesuai kebutuhan Jumlah alat tulis x Opsional sesuai kebutuhan Harga satuan Konsultasi Transport Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta x Pokok Publik sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 Jumlah jam kerja x Publik (empat) jam kerja Jumlah Konsultasi total untuk 1 (satu) kali Konsultasi Publik x Harga Publik) Satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk pelaksanaan Opsional dinas yang berada di luar 1 (satu)', 'LAMPIRAN II (lanjutan 53)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (379, 'juklak-2-2026', 73, 'lampiran', 'LAMPIRAN II (lanjutan 54)', NULL, 60, 'kali Jumlah Konsultasi di luar Jabodetabek Jabodetabek atau Konsultasi Publik Publik x Jumlah sesuai kebutuhan (maksimal 2 (dua) hari x Harga satuan hari untuk 1 (satu) kali rapat) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kesiapsiagaan penggandaan x penggandaan Logistik dan Harga satuan Peralatan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan penggandaan x Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI DEFINISI Seluruh rangkaian kegiatan penyusunan dokumen analisis dan perencanaan pemenuhan logistik dan peralatan sesuai OPERASIONAL kewenangan pemerintah provinsi, baik logistik dan peralatan yang bersifat generik maupun spesifik yang dibutuhkan untuk kesiapsiagaan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (379, 'kali Jumlah Konsultasi di luar Jabodetabek Jabodetabek atau Konsultasi Publik Publik x Jumlah sesuai kebutuhan (maksimal 2 (dua) hari x Harga satuan hari untuk 1 (satu) kali rapat) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kesiapsiagaan penggandaan x penggandaan Logistik dan Harga satuan Peralatan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan penggandaan x Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI DEFINISI Seluruh rangkaian kegiatan penyusunan dokumen analisis dan perencanaan pemenuhan logistik dan peralatan sesuai OPERASIONAL kewenangan pemerintah provinsi, baik logistik dan peralatan yang bersifat generik maupun spesifik yang dibutuhkan untuk kesiapsiagaan', 'LAMPIRAN II (lanjutan 54)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (380, 'juklak-2-2026', 74, 'lampiran', 'LAMPIRAN II (lanjutan 55)', NULL, 60, 'dan penanganan darurat tiap-tiap jenis ancaman melalui identifikasi kebutuhan, data, dan analisis untuk mencapai Standar logistik dan peralatan yang berlaku.
Penyusunan Rencana Kesiapsiagaan Logistik dan Peralatan mengacu kepada 5 komponen rencana kesiapsiagaan logistik dan peralatan, yaitu: a) kemitraan; b) pemetaan sumber daya dan gap; c) penyusunan konsep operasi logistik dan peralatan; d) peningkatan kapasitas; dan e) pengujian konsep operasi logistik dan peralatan.
Tim Biaya honorarium Jumlah tim Jumlah bulan kerja Jumlah personil x Tim Substansi Pokok Substansi/Tim tim substansi/ tim substansi sesuai atau hari kerja tiap- Jumlah bulan kerja adalah di luar Teknis Penyusun teknis kebutuhan tiap tim personil atau hari kerja x tenaga ahli dan berdasarkan tim substansi Harga satuan ditetapkan melalui identifikasi Surat Keputusan Perangkat Daerah Eselon II dan entitas utama terkait penanggulangan bencana provinsi berdasarkan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (380, 'dan penanganan darurat tiap-tiap jenis ancaman melalui identifikasi kebutuhan, data, dan analisis untuk mencapai Standar logistik dan peralatan yang berlaku.
Penyusunan Rencana Kesiapsiagaan Logistik dan Peralatan mengacu kepada 5 komponen rencana kesiapsiagaan logistik dan peralatan, yaitu: a) kemitraan; b) pemetaan sumber daya dan gap; c) penyusunan konsep operasi logistik dan peralatan; d) peningkatan kapasitas; dan e) pengujian konsep operasi logistik dan peralatan.
