INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (381, 'juklak-2-2026', 75, 'lampiran', 'LAMPIRAN II (lanjutan 56)', NULL, 65, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 10 OB Opsional bidang tenaga ahli sesuai kebutuhan tiap-tiap tenaga ahli x Jumlah bulan kebencanaan (maksimal 2 (dua) kerja x Harga orang) satuan Tenaga ahli Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 10 OB Opsional bidang logistik tenaga ahli sesuai kebutuhan tiap-tiap tenaga ahli x Jumlah bulan dan peralatan/ (maksimal 2 (dua) kerja x Harga pemetaan (GIS) orang) satuan Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tim penulis Maksimal 8 OB Opsional tim penulis penulis sesuai tiap-tiap tenaga x Jumlah bulan kebutuhan penulis kerja x Harga (maksimal 2 (dua) satuan orang) Lokakarya Awal Transport Peserta Jumlah peserta Jumlah lokakarya Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah lokakarya x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali lokakarya kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah lokakarya x total untuk 1 (satu) Harga Satuan kali Lokakarya) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x Untuk peserta luar Opsional dinas sesuai kebutuhan 1 (satu) kali Jumlah lokakarya x daerah lokakarya');
