INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (382, 'juklak-2-2026', 76, 'lampiran', 'LAMPIRAN II (lanjutan 57)', NULL, 65, 'Jumlah hari x (maksimal 3 hari Harga satuan untuk 1 (satu) kali lokakarya) Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 5 (lima) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Diskusi total untuk 1 (satu) Teknis x Harga kali Diskusi Teknis) Satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x Untuk peserta luar Opsional dinas sesuai kebutuhan 1 (satu) kali diskusi Jumlah diskusi daerah teknis (maksimal 4 teknis x Jumlah hari x Harga satuan hari untuk 1 (satu) kali diskusi teknis) Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (382, 'Jumlah hari x (maksimal 3 hari Harga satuan untuk 1 (satu) kali lokakarya) Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 5 (lima) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Diskusi total untuk 1 (satu) Teknis x Harga kali Diskusi Teknis) Satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x Untuk peserta luar Opsional dinas sesuai kebutuhan 1 (satu) kali diskusi Jumlah diskusi daerah teknis (maksimal 4 teknis x Jumlah hari x Harga satuan hari untuk 1 (satu) kali diskusi teknis) Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x', 'LAMPIRAN II (lanjutan 57)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (383, 'juklak-2-2026', 77, 'lampiran', 'LAMPIRAN II (lanjutan 58)', NULL, 65, 'Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Pengujian Penyediaan dan Jumlah unit sesuai Jumlah hari sesuai Jumlah unit x Opsional konsep operasi mobilisasi kebutuhan sesi pengujian Jumlah hari x logistik dan Perlengkapan konsep operasi Harga satuan peralatan logistik dan peralatan Alat tulis Jumlah alat tulis Sesuai kebutuhan Jumlah alat tulis x Opsional sesuai kebutuhan Harga satuan Konsultasi Transport Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta x Pokok Publik sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Konsultasi kebutuhan (maksimal 4 Jumlah jam kerja x Publik (empat) jam kerja Jumlah konsultasi total untuk 1 (satu) publik x Harga kali Konsultasi Satuan Publik) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x Untuk peserta luar Opsional dinas sesuai kebutuhan 1 (satu) kali Jumlah konsultasi daerah konsultasi publik publik x Jumlah (maksimal 3 hari hari x Harga satuan untuk 1');
