INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (384, 'juklak-2-2026', 78, 'lampiran', 'LAMPIRAN II (lanjutan 59)', NULL, 65, '(satu) kali konsultasi publik) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kesiapsiagaan penggandaan x penggandaan Logistik dan Harga satuan Peralatan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA DEFINISI Seluruh rangkaian kegiatan penyusunan dokumen analisis dan perencanaan pemenuhan logistik dan peralatan sesuai OPERASIONAL kewenangan pemerintah kabupaten/kota, baik logistik dan peralatan yang bersifat generik maupun spesifik yang dibutuhkan untuk kesiapsiagaan dan penanganan darurat tiap-tiap jenis ancaman melalui identifikasi kebutuhan, data, dan analisis untuk mencapai Standar logistik dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (384, '(satu) kali konsultasi publik) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kesiapsiagaan penggandaan x penggandaan Logistik dan Harga satuan Peralatan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA DEFINISI Seluruh rangkaian kegiatan penyusunan dokumen analisis dan perencanaan pemenuhan logistik dan peralatan sesuai OPERASIONAL kewenangan pemerintah kabupaten/kota, baik logistik dan peralatan yang bersifat generik maupun spesifik yang dibutuhkan untuk kesiapsiagaan dan penanganan darurat tiap-tiap jenis ancaman melalui identifikasi kebutuhan, data, dan analisis untuk mencapai Standar logistik dan', 'LAMPIRAN II (lanjutan 59)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (385, 'juklak-2-2026', 79, 'lampiran', 'LAMPIRAN II (lanjutan 60)', NULL, 65, 'peralatan yang berlaku.
Penyusunan Rencana Kesiapsiagaan Logistik dan Peralatan mengacu kepada 5 komponen rencana kesiapsiagaan logistik dan peralatan, yaitu: a) kemitraan b) pemetaan sumber daya dan gap c) penyusunan konsep operasi logistik dan peralatan d) peningkatan kapasitas e) pengujian konsep operasi logistik dan peralatan Tim Substansi/ Biaya honorarium Jumlah tim Jumlah bulan kerja Jumlah personil x Tim Substansi Pokok Tim Teknis tim substansi/ tim substansi sesuai atau hari kerja tiap- Jumlah bulan kerja adalah di luar Penyusun teknis kebutuhan tiap tim personil atau hari kerja x tenaga ahli dan berdasarkan tim substansi Harga satuan ditetapkan melalui identifikasi Surat Keputusan Perangkat Daerah Eselon II dan entitas utama terkait penanggulangan bencana provinsi berdasarkan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (385, 'peralatan yang berlaku.
Penyusunan Rencana Kesiapsiagaan Logistik dan Peralatan mengacu kepada 5 komponen rencana kesiapsiagaan logistik dan peralatan, yaitu: a) kemitraan b) pemetaan sumber daya dan gap c) penyusunan konsep operasi logistik dan peralatan d) peningkatan kapasitas e) pengujian konsep operasi logistik dan peralatan Tim Substansi/ Biaya honorarium Jumlah tim Jumlah bulan kerja Jumlah personil x Tim Substansi Pokok Tim Teknis tim substansi/ tim substansi sesuai atau hari kerja tiap- Jumlah bulan kerja adalah di luar Penyusun teknis kebutuhan tiap tim personil atau hari kerja x tenaga ahli dan berdasarkan tim substansi Harga satuan ditetapkan melalui identifikasi Surat Keputusan Perangkat Daerah Eselon II dan entitas utama terkait penanggulangan bencana provinsi berdasarkan ketentuan peraturan perundang-undangan.', 'LAMPIRAN II (lanjutan 60)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (386, 'juklak-2-2026', 80, 'lampiran', 'LAMPIRAN II (lanjutan 61)', NULL, 70, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 10 OB Opsional bidang tenaga ahli sesuai kebutuhan tiap-tiap tenaga ahli x Jumlah bulan kebencanaan (maksimal 2 (dua) kerja x Harga orang) satuan Tenaga ahli Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 10 OB Opsional bidang logistik tenaga ahli sesuai kebutuhan tiap-tiap tenaga ahli x Jumlah bulan dan peralatan/ (maksimal 2 (dua) kerja x Harga pemetaan (GIS) orang) satuan Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tim penulis Maksimal 8 OB Opsional tim penulis penulis sesuai tiap-tiap tenaga x Jumlah bulan kebutuhan penulis kerja x Harga (maksimal 2 (dua) satuan orang) Lokakarya Awal Transport Peserta Jumlah peserta Jumlah lokakarya Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah lokakarya x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali lokakarya kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah lokakarya x total untuk 1 (satu) Harga Satuan kali Lokakarya) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x Untuk peserta luar Opsional dinas sesuai kebutuhan 1 (satu) kali Jumlah lokakarya x daerah lokakarya');
