INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (389, 'juklak-2-2026', 83, 'lampiran', 'LAMPIRAN II (lanjutan 64)', NULL, 70, '(satu) kali konsultasi publik) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kesiapsiagaan penggandaan x penggandaan Logistik dan Harga satuan Peralatan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan KEGIATAN : PENYUSUNAN DOKUMEN PERENCANAAN LAIN DI BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PERENCANAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Seluruh rangkaian kegiatan penyusunan dokumen perencanaan pada saat sebelum terjadi bencana yang ditujukan untuk Operasional mengurangi risiko dan/atau dampak kejadian bencana, baik dalam bentuk perencanaan generik untuk seluruh jenis bencana maupun perencanaan sektoral dan tematik, sesuai lingkup');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (389, '(satu) kali konsultasi publik) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai kebutuhan Publik sesuai Jumlah Konsultasi kebutuhan Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Rencana penggandaan Jumlah eksemplar Laporan Kesiapsiagaan penggandaan x penggandaan Logistik dan Harga satuan Peralatan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan KEGIATAN : PENYUSUNAN DOKUMEN PERENCANAAN LAIN DI BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PERENCANAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Seluruh rangkaian kegiatan penyusunan dokumen perencanaan pada saat sebelum terjadi bencana yang ditujukan untuk Operasional mengurangi risiko dan/atau dampak kejadian bencana, baik dalam bentuk perencanaan generik untuk seluruh jenis bencana maupun perencanaan sektoral dan tematik, sesuai lingkup', 'LAMPIRAN II (lanjutan 64)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
