INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (391, 'juklak-2-2026', 85, 'lampiran', 'LAMPIRAN II (lanjutan 66)', NULL, 75, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 10 OB Opsional bidang tenaga ahli sesuai kebutuhan untuk tiap-tiap x Jumlah bulan kebencanaan (maksimal 2 (dua) tenaga ahli kerja x Harga orang) satuan Tenaga ahli Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 25 OB Opsional sesuai bidang tenaga ahli sesuai kebutuhan untuk tiap-tiap x Jumlah bulan sektoral dan (maksimal 5 (lima) tenaga ahli kerja x Harga tematik orang) satuan Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tenaga Maksimal 8 OB Opsional tim penulis penulis sesuai untuk tiap-tiap penulis x Jumlah kebutuhan tenaga penulis bulan kerja x Harga (maksimal 2 (dua) satuan orang) Tim Substansi/ Biaya honorarium Sesuai kebutuhan Jumlah bulan kerja Jumlah personil x Tim Substansi Opsional Tim Teknis tim substansi/ tim berdasarkan atau hari kerja tiap- Jumlah bulan kerja adalah diluar Penyusun teknis identifikasi tenaga ahli dan kementerian/ tiap tim personil atau hari kerja x ditetapkan melalui lembaga dan entitas tim substansi Harga satuan Surat Keputusan utama terkait Eselon I penanggulangan bencana berdasarkan ketentuan peraturan perundang-undangan.');
