INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (399, 'juklak-2-2026', 93, 'lampiran', 'LAMPIRAN II (lanjutan 74)', NULL, 81, 'jumlah Jumlah Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Asistensi dan Transportasi Jumlah peserta Jumlah pertemuan Jumlah peserta x Maksimal 3 (tiga) Pokok Harmonisasi Peserta sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan kali x Harga satuan Biaya honorarium Jumlah Jumlah jam kerja Jumlah Jika dilakukan Opsional Tenaga Narasumber narasumber sesuai sesuai kebutuhan narasumber x secara luring kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah pertemuan total untuk 1 (satu) x Harga Satuan kali pertemuan) Paket pertemuan Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan x Harga satuan Konsumsi rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan x Harga satuan Snack rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Konsultasi Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah pertemuan Jumlah pertemuan Opsional lembar materi yang sesuai kebutuhan x Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan penggandaan Jumlah eksemplar Laporan penggandaan x penggandaan Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (399, 'jumlah Jumlah Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Asistensi dan Transportasi Jumlah peserta Jumlah pertemuan Jumlah peserta x Maksimal 3 (tiga) Pokok Harmonisasi Peserta sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan kali x Harga satuan Biaya honorarium Jumlah Jumlah jam kerja Jumlah Jika dilakukan Opsional Tenaga Narasumber narasumber sesuai sesuai kebutuhan narasumber x secara luring kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah pertemuan total untuk 1 (satu) x Harga Satuan kali pertemuan) Paket pertemuan Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan x Harga satuan Konsumsi rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan x Harga satuan Snack rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Konsultasi Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah pertemuan Jumlah pertemuan Opsional lembar materi yang sesuai kebutuhan x Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan penggandaan Jumlah eksemplar Laporan penggandaan x penggandaan Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan', 'LAMPIRAN II (lanjutan 74)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (400, 'juklak-2-2026', 94, 'lampiran', 'LAMPIRAN II (lanjutan 75)', NULL, 81, 'Harga satuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Seluruh rangkaian kegiatan penyusunan dokumen perencanaan pada saat sebelum terjadi bencana yang ditujukan untuk Operasional mengurangi risiko dan/atau dampak kejadian bencana, baik dalam bentuk perencanaan generik untuk seluruh jenis bencana maupun perencanaan sektoral dan tematik, sesuai lingkup kewenangan pemerintah kabupaten/kota terkait.
Bentuk dokumen perencanaan lain di bidang penanggulangan bencana antara lain seperti:
1) Dokumen Rencana Mitigasi Bencana;
2) Dokumen Rencana Pemulihan Sebelum Bencana (Pre-Disaster Recovery Plan); dan 3) dsb.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (400, 'Harga satuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Seluruh rangkaian kegiatan penyusunan dokumen perencanaan pada saat sebelum terjadi bencana yang ditujukan untuk Operasional mengurangi risiko dan/atau dampak kejadian bencana, baik dalam bentuk perencanaan generik untuk seluruh jenis bencana maupun perencanaan sektoral dan tematik, sesuai lingkup kewenangan pemerintah kabupaten/kota terkait.
Bentuk dokumen perencanaan lain di bidang penanggulangan bencana antara lain seperti:
1) Dokumen Rencana Mitigasi Bencana;
2) Dokumen Rencana Pemulihan Sebelum Bencana (Pre-Disaster Recovery Plan); dan 3) dsb.', 'LAMPIRAN II (lanjutan 75)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (401, 'juklak-2-2026', 95, 'lampiran', 'LAMPIRAN II (lanjutan 76)', NULL, 85, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tuhuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 10 OB Opsional bidang tenaga ahli sesuai kebutuhan untuk tiap-tiap x Jumlah bulan kebencanaan (maksimal 2 (dua) tenaga ahli kerja x Harga orang) satuan Tenaga ahli Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 25 OB Opsional sesuai bidang tenaga ahli sesuai kebutuhan untuk tiap-tiap x Jumlah bulan sektoral dan (maksimal 5 (lima) tenaga ahli kerja x Harga tematik orang) satuan Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tenaga Maksimal 8 OB Opsional tim penulis penulis sesuai untuk tiap-tiap penulis x Jumlah kebutuhan tenaga penulis bulan kerja x Harga (Maksimal 2 (dua) satuan orang) Tim Substansi/ Biaya honorarium Sesuai kebutuhan Jumlah bulan kerja Jumlah personil x Tim Substansi Opsional Tim Teknis tim substansi/ tim berdasarkan atau hari kerja tiap- Jumlah bulan kerja adalah di luar Penyusun teknis identifikasi tiap tim personil atau hari kerja x tenaga ahli dan Perangkat Daerah tim substansi Harga satuan ditetapkan melalui dan entitas utama Surat Keputusan terkait Eselon II penanggulangan bencana berdasarkan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (401, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tuhuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 10 OB Opsional bidang tenaga ahli sesuai kebutuhan untuk tiap-tiap x Jumlah bulan kebencanaan (maksimal 2 (dua) tenaga ahli kerja x Harga orang) satuan Tenaga ahli Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 25 OB Opsional sesuai bidang tenaga ahli sesuai kebutuhan untuk tiap-tiap x Jumlah bulan sektoral dan (maksimal 5 (lima) tenaga ahli kerja x Harga tematik orang) satuan Tenaga penulis Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tenaga Maksimal 8 OB Opsional tim penulis penulis sesuai untuk tiap-tiap penulis x Jumlah kebutuhan tenaga penulis bulan kerja x Harga (Maksimal 2 (dua) satuan orang) Tim Substansi/ Biaya honorarium Sesuai kebutuhan Jumlah bulan kerja Jumlah personil x Tim Substansi Opsional Tim Teknis tim substansi/ tim berdasarkan atau hari kerja tiap- Jumlah bulan kerja adalah di luar Penyusun teknis identifikasi tiap tim personil atau hari kerja x tenaga ahli dan Perangkat Daerah tim substansi Harga satuan ditetapkan melalui dan entitas utama Surat Keputusan terkait Eselon II penanggulangan bencana berdasarkan ketentuan peraturan perundang-undangan.', 'LAMPIRAN II (lanjutan 76)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (402, 'juklak-2-2026', 96, 'lampiran', 'LAMPIRAN II (lanjutan 77)', NULL, 86, 'Lokakarya Awal Transport Peserta Jumlah peserta Jumlah lokakarya Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah lokakarya x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali lokakarya kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah lokakarya x total untuk 1 (satu) Harga Satuan kali Lokakarya) Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 5 (lima) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali Diskusi Teknis kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Diskusi total untuk 1 (satu) Teknis x Harga kali Diskusi Teknis) Satuan Paket pertemuan Jumlah peserta Jumlah Diskusi');
