INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (404, 'juklak-2-2026', 98, 'lampiran', 'LAMPIRAN II (lanjutan 79)', NULL, 86, 'jumlah Jumlah Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Asistensi dan Transportasi Jumlah peserta Jumlah pertemuan Jumlah peserta x Maksimal 3 (tiga) Pokok Harmonisasi Peserta sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan kali x Harga satuan Biaya honorarium Jumlah Jumlah jam kerja Jumlah Jika dilakukan Opsional Tenaga Narasumber narasumber sesuai sesuai kebutuhan narasumber x secara luring kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah pertemuan total untuk 1 (satu) x Harga Satuan kali pertemuan) Paket pertemuan Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan x Harga satuan Konsumsi rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan x Harga satuan Snack rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Konsultasi Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah pertemuan Jumlah pertemuan Opsional lembar materi yang sesuai kebutuhan x Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan penggandaan Jumlah eksemplar Laporan penggandaan x penggandaan Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (404, 'jumlah Jumlah Konsultasi Jumlah Konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Asistensi dan Transportasi Jumlah peserta Jumlah pertemuan Jumlah peserta x Maksimal 3 (tiga) Pokok Harmonisasi Peserta sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan kali x Harga satuan Biaya honorarium Jumlah Jumlah jam kerja Jumlah Jika dilakukan Opsional Tenaga Narasumber narasumber sesuai sesuai kebutuhan narasumber x secara luring kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah pertemuan total untuk 1 (satu) x Harga Satuan kali pertemuan) Paket pertemuan Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan x Harga satuan Konsumsi rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah pertemuan x Harga satuan Snack rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Konsultasi Publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah pertemuan Jumlah pertemuan Opsional lembar materi yang sesuai kebutuhan x Harga satuan dibutuhkan Penggandaan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan penggandaan Jumlah eksemplar Laporan penggandaan x penggandaan Harga satuan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Kegiatan penggandaan Jumlah eksemplar penggandaan x penggandaan', 'LAMPIRAN II (lanjutan 79)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (405, 'juklak-2-2026', 99, 'lampiran', 'LAMPIRAN II (lanjutan 80)', NULL, 86, 'Harga satuan KEGIATAN : PEMBENTUKAN PERATURAN PEMERINTAH BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan yang dibutuhkan dalam pembentukan regulasi satu tingkat di bawah Undang-Undang, mulai dari Operasional proses penyusunan hingga penetapan. Mengacu pada Peraturan Menteri Keuangan yang berlaku, kegiatan pembentukan peraturan pemerintah bidang penanggulangan bencana terdiri atas:
1) Peraturan Pemerintah yang Bersifat Sederhana Digunakan untuk menghasilkan Peraturan Pemerintah yang jumlah pasalnya tidak lebih dari 25 (dua puluh lima) pasal dan/atau melibatkan tidak lebih dari 5 (lima) kementerian/lembaga/instansi.
2) Peraturan Pemerintah yang Bersifat Kompleks Digunakan untuk menghasilkan Peraturan Pemerintah yang jumlah pasalnya lebih dari 25 (dua puluh lima) pasal dan melibatkan lebih dari 5 (lima) kementerian/lembaga/instansi.
Pembentukan Peraturan Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan Pokok Peraturan Pemerintah yang sesuai kebutuhan Harga satuan untuk 1 (satu) Pemerintah Bersifat Sederhana dokumen sesuai Bidang Peraturan Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x dengan SBK yang Pokok Penanggulangan Pemerintah yang sesuai kebutuhan Harga satuan ditetapkan PMK Bencana Bersifat Kompleks untuk tiap-tiap kementerian/lemba ga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (405, 'Harga satuan KEGIATAN : PEMBENTUKAN PERATURAN PEMERINTAH BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan yang dibutuhkan dalam pembentukan regulasi satu tingkat di bawah Undang-Undang, mulai dari Operasional proses penyusunan hingga penetapan. Mengacu pada Peraturan Menteri Keuangan yang berlaku, kegiatan pembentukan peraturan pemerintah bidang penanggulangan bencana terdiri atas:
1) Peraturan Pemerintah yang Bersifat Sederhana Digunakan untuk menghasilkan Peraturan Pemerintah yang jumlah pasalnya tidak lebih dari 25 (dua puluh lima) pasal dan/atau melibatkan tidak lebih dari 5 (lima) kementerian/lembaga/instansi.
2) Peraturan Pemerintah yang Bersifat Kompleks Digunakan untuk menghasilkan Peraturan Pemerintah yang jumlah pasalnya lebih dari 25 (dua puluh lima) pasal dan melibatkan lebih dari 5 (lima) kementerian/lembaga/instansi.
Pembentukan Peraturan Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan Pokok Peraturan Pemerintah yang sesuai kebutuhan Harga satuan untuk 1 (satu) Pemerintah Bersifat Sederhana dokumen sesuai Bidang Peraturan Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x dengan SBK yang Pokok Penanggulangan Pemerintah yang sesuai kebutuhan Harga satuan ditetapkan PMK Bencana Bersifat Kompleks untuk tiap-tiap kementerian/lemba ga.', 'LAMPIRAN II (lanjutan 80)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (406, 'juklak-2-2026', 100, 'lampiran', 'LAMPIRAN II (lanjutan 81)', NULL, 91, 'PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PEMBENTUKAN PERATURAN PRESIDEN BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan yang dibutuhkan dalam pembentukan regulasi satu tingkat di bawah Peraturan Pemerintah, mulai Operasional dari proses penyusunan hingga penetapan. Mengacu pada Peraturan Menteri Keuangan yang berlaku, kegiatan pembentukan Peraturan Presiden bidang penanggulangan bencana terdiri atas:
1) Peraturan Presiden yang Bersifat Sederhana Digunakan untuk menghasilkan Peraturan Presiden yang jumlah pasalnya tidak lebih dari 25 (dua puluh lima) pasal dan/atau melibatkan tidak lebih dari 5 (lima) kementerian/lembaga/instansi.
2) Peraturan Presiden yang Bersifat Kompleks Digunakan untuk menghasilkan Peraturan Presiden yang jumlah pasalnya lebih dari 25 (dua puluh lima) pasal dan melibatkan lebih dari 5 (lima) kementerian/lembaga/instansi.
Pembentukan Peraturan Presiden Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan Pokok Peraturan yang Bersifat sesuai kebutuhan Harga satuan untuk 1 (satu) Presiden Bidang Sederhana dokumen sesuai Penanggulangan Peraturan Presiden Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x dengan SBK yang Pokok Bencana yang Bersifat sesuai kebutuhan Harga satuan ditetapkan PMK Kompleks untuk tiap-tiap kementerian/ lembaga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (406, 'PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PEMBENTUKAN PERATURAN PRESIDEN BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan yang dibutuhkan dalam pembentukan regulasi satu tingkat di bawah Peraturan Pemerintah, mulai Operasional dari proses penyusunan hingga penetapan. Mengacu pada Peraturan Menteri Keuangan yang berlaku, kegiatan pembentukan Peraturan Presiden bidang penanggulangan bencana terdiri atas:
1) Peraturan Presiden yang Bersifat Sederhana Digunakan untuk menghasilkan Peraturan Presiden yang jumlah pasalnya tidak lebih dari 25 (dua puluh lima) pasal dan/atau melibatkan tidak lebih dari 5 (lima) kementerian/lembaga/instansi.
2) Peraturan Presiden yang Bersifat Kompleks Digunakan untuk menghasilkan Peraturan Presiden yang jumlah pasalnya lebih dari 25 (dua puluh lima) pasal dan melibatkan lebih dari 5 (lima) kementerian/lembaga/instansi.
Pembentukan Peraturan Presiden Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan Pokok Peraturan yang Bersifat sesuai kebutuhan Harga satuan untuk 1 (satu) Presiden Bidang Sederhana dokumen sesuai Penanggulangan Peraturan Presiden Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x dengan SBK yang Pokok Bencana yang Bersifat sesuai kebutuhan Harga satuan ditetapkan PMK Kompleks untuk tiap-tiap kementerian/ lembaga.', 'LAMPIRAN II (lanjutan 81)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (407, 'juklak-2-2026', 101, 'lampiran', 'LAMPIRAN II (lanjutan 82)', NULL, 92, 'PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PEMBENTUKAN PERATURAN MENTERI/KEPALA LEMBAGA BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan yang dibutuhkan dalam pembentukan regulasi setingkat peraturan menteri/lembaga, mulai dari Operasional proses penyusunan hingga penetapan. Mengacu pada Peraturan Menteri Keuangan yang berlaku, kegiatan pembentukan Peraturan Menteri/Kepala Lembaga bidang penanggulangan bencana terdiri atas:
1) Peraturan Menteri/Pimpinan Lembaga yang Bersifat Internal Digunakan untuk menghasilkan peraturan menteri/pimpinan lembaga yang penetapannya bersifat mengatur dan mengikat hanya ke dalam kementerian/lembaga berkenaan.
2) Peraturan Menteri/Pimpinan Lembaga yang Bersifat Eksternal Digunakan untuk menghasilkan peraturan menteri/pimpinan lembaga yang penetapannya bersifat mengatur dan mengikat ke luar kementerian/lembaga berkenaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (407, 'PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PEMBENTUKAN PERATURAN MENTERI/KEPALA LEMBAGA BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan yang dibutuhkan dalam pembentukan regulasi setingkat peraturan menteri/lembaga, mulai dari Operasional proses penyusunan hingga penetapan. Mengacu pada Peraturan Menteri Keuangan yang berlaku, kegiatan pembentukan Peraturan Menteri/Kepala Lembaga bidang penanggulangan bencana terdiri atas:
1) Peraturan Menteri/Pimpinan Lembaga yang Bersifat Internal Digunakan untuk menghasilkan peraturan menteri/pimpinan lembaga yang penetapannya bersifat mengatur dan mengikat hanya ke dalam kementerian/lembaga berkenaan.
2) Peraturan Menteri/Pimpinan Lembaga yang Bersifat Eksternal Digunakan untuk menghasilkan peraturan menteri/pimpinan lembaga yang penetapannya bersifat mengatur dan mengikat ke luar kementerian/lembaga berkenaan.', 'LAMPIRAN II (lanjutan 82)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (408, 'juklak-2-2026', 102, 'lampiran', 'LAMPIRAN II (lanjutan 83)', NULL, 93, 'Pembentukan Peraturan Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan Pokok Peraturan Menteri/Pimpinan sesuai kebutuhan Harga satuan untuk 1 (satu) Menteri/ Lembaga yang dokumen sesuai Pimpinan Bersifat Internal dengan SBK yang Lembaga Bidang Peraturan Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x ditetapkan PMK Pokok Penanggulangan Menteri/Pimpinan sesuai kebutuhan Harga satuan untuk tiap-tiap Bencana Lembaga yang kementerian/lemba Bersifat Eksternal ga.
PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PEMBENTUKAN PERATURAN KEPALA DAERAH BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Seluruh rangkaian proses pembentukan Peraturan Gubernur bidang penanggulangan bencana mengacu pada aturan dan Operasional mekanisme pembentukan peraturan perundang-undangan yang berlaku, meliputi perencanaan, penyusunan, pembahasan, penetapan dan pengundangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (408, 'Pembentukan Peraturan Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan Pokok Peraturan Menteri/Pimpinan sesuai kebutuhan Harga satuan untuk 1 (satu) Menteri/ Lembaga yang dokumen sesuai Pimpinan Bersifat Internal dengan SBK yang Lembaga Bidang Peraturan Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x ditetapkan PMK Pokok Penanggulangan Menteri/Pimpinan sesuai kebutuhan Harga satuan untuk tiap-tiap Bencana Lembaga yang kementerian/lemba Bersifat Eksternal ga.
PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PEMBENTUKAN PERATURAN KEPALA DAERAH BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Seluruh rangkaian proses pembentukan Peraturan Gubernur bidang penanggulangan bencana mengacu pada aturan dan Operasional mekanisme pembentukan peraturan perundang-undangan yang berlaku, meliputi perencanaan, penyusunan, pembahasan, penetapan dan pengundangan.', 'LAMPIRAN II (lanjutan 83)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (409, 'juklak-2-2026', 103, 'lampiran', 'LAMPIRAN II (lanjutan 84)', NULL, 94, 'Pembentukan Pembentukan Jumlah dokumen Sesuai kebutuhan Jumlah dokumen Harga satuan untuk 1 Pokok peraturan kepala Peraturan sesuai kebutuhan x Harga satuan (satu) dokumen sesuai daerah bidang Gubernur bidang dengan SBU yang penanggulangan Penanggulangan ditetapkan pada tiap-bencana Bencana tiap provinsi PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Seluruh rangkaian proses pembentukan Peraturan Bupati/Walikota bidang penanggulangan bencana mengacu pada Operasional aturan dan mekanisme pembentukan peraturan perundang-undangan yang berlaku, meliputi perencanaan, penyusunan, pembahasan, penetapan dan pengundangan.
Pembentukan Pembentukan Jumlah dokumen Sesuai kebutuhan Jumlah dokumen Harga satuan untuk 1 Pokok peraturan kepala Peraturan Walikota sesuai kebutuhan x Harga satuan (satu) dokumen sesuai daerah bidang /Bupati bidang dengan SBU yang penanggulangan Penanggulangan ditetapkan pada tiap-bencana Bencana tiap kabupaten/kota KEGIATAN : PENYUSUNAN NSPK BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan yang dibutuhkan untuk penyusunan dokumen Norma, Standar, Prosedur dan Kriteria untuk Operasional penyelenggaraan penanggulangan bencana, diprioritaskan untuk penerapan SPM Sub-Urusan Bencana, setidaknya melingkupi tahap persiapan, penyusunan NSPK, dan finalisasi, termasuk di dalamnya kegiatan pembahasan dan uji coba/uji petik NSPK.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (409, 'Pembentukan Pembentukan Jumlah dokumen Sesuai kebutuhan Jumlah dokumen Harga satuan untuk 1 Pokok peraturan kepala Peraturan sesuai kebutuhan x Harga satuan (satu) dokumen sesuai daerah bidang Gubernur bidang dengan SBU yang penanggulangan Penanggulangan ditetapkan pada tiap-bencana Bencana tiap provinsi PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Seluruh rangkaian proses pembentukan Peraturan Bupati/Walikota bidang penanggulangan bencana mengacu pada Operasional aturan dan mekanisme pembentukan peraturan perundang-undangan yang berlaku, meliputi perencanaan, penyusunan, pembahasan, penetapan dan pengundangan.
Pembentukan Pembentukan Jumlah dokumen Sesuai kebutuhan Jumlah dokumen Harga satuan untuk 1 Pokok peraturan kepala Peraturan Walikota sesuai kebutuhan x Harga satuan (satu) dokumen sesuai daerah bidang /Bupati bidang dengan SBU yang penanggulangan Penanggulangan ditetapkan pada tiap-bencana Bencana tiap kabupaten/kota KEGIATAN : PENYUSUNAN NSPK BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan yang dibutuhkan untuk penyusunan dokumen Norma, Standar, Prosedur dan Kriteria untuk Operasional penyelenggaraan penanggulangan bencana, diprioritaskan untuk penerapan SPM Sub-Urusan Bencana, setidaknya melingkupi tahap persiapan, penyusunan NSPK, dan finalisasi, termasuk di dalamnya kegiatan pembahasan dan uji coba/uji petik NSPK.', 'LAMPIRAN II (lanjutan 84)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (410, 'juklak-2-2026', 104, 'lampiran', 'LAMPIRAN II (lanjutan 85)', NULL, 95, 'Penyusunan Penyusunan NSPK Jumlah dokumen Sesuai kebutuhan Jumlah dokumen Harga satuan untuk Pokok NSPK bidang sesuai kebutuhan x Harga satuan 1 (satu) dokumen penanggulangan sesuai dengan SBK bencana yang ditetapkan PMK untuk tiap-tiap kementerian/ lembaga.
PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PENYUSUNAN NASKAH AKADEMIS KEBIJAKAN BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA DEFINISI Segala bentuk kegiatan yang dibutuhkan untuk penyusunan naskah kebijakan/rekomendasi dari kegiatan riset kebijakan, OPERASIONAL pengkajian kebijakan dan/atau pengumpulan data ilmiah dalam waktu pendek (kurang dari 4 (empat) bulan) yang merupakan penugasan dari pemerintah untuk menyelesaikan suatu kasus dengan hasil akhir berupa naskah kebijakan/rekomendasi (naskah akademik, naskah urgensi, monograf kebijakan, memo kebijakan, model kebijakan, kertas kerja kebijakan, risalah kebijakan, artikel kebijakan, atau bentuk lain dari naskah kebijakan yang ditetapkan oleh pimpinan lembaga negara yang menyelenggarakan urusan pemerintah di bidang riset dan inovasi). Tata cara pemenuhan output ditetapkan oleh pimpinan kementerian/lembaga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (410, 'Penyusunan Penyusunan NSPK Jumlah dokumen Sesuai kebutuhan Jumlah dokumen Harga satuan untuk Pokok NSPK bidang sesuai kebutuhan x Harga satuan 1 (satu) dokumen penanggulangan sesuai dengan SBK bencana yang ditetapkan PMK untuk tiap-tiap kementerian/ lembaga.
