INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (411, 'juklak-2-2026', 105, 'lampiran', 'LAMPIRAN II (lanjutan 86)', NULL, 96, 'Penyusunan Penyusunan Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan untuk Pokok naskah akademis Naskah Akademis sesuai kebutuhan Harga satuan 1 (satu) dokumen kebijakan bidang sesuai dengan SBK penanggulangan yang ditetapkan PMK bencana untuk tiap-tiap kementerian/ lembaga.
PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PENELITIAN DAN PENGEMBANGAN BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk riset terstruktur yang dilakukan dalam lingkup kewenangan nasional, guna menyempurnakan produk yang Operasional telah ada ataupun mengembangkan produk baru yang harus memberikan kemanfaatan sosial.
Mengacu pada Peraturan Menteri Keuangan, pengembangan produk baru dapat dalam bentuk:
1) Kekayaan Intelektual Kekayaan intelektual berupa hak cipta (copyright), paten (patent),desain industri (industrial design), merek (trademark), desain tata letak sirkuit terpadu (layout design of integrated circuit), dan indikasi geografis.
2) Purwarupa Purwarupa adalah hasil penelitian dan pengembangan yang dapat menjadi hasil akhir atau bagian dari hasil akhir sebagai proses pembuktian fungsi yang direncanakan.');
