INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (416, 'juklak-2-2026', 110, 'lampiran', 'LAMPIRAN II (lanjutan 91)', NULL, 99, 'Penelitian dan Kekayaan Jumlah kekayaan Sesuai kebutuhan Jumlah kekayaan Harga satuan untuk Opsional Pengembangan intelektual/ intelektual/ intelektual/Purwar 1 (satu) satuan Bidang Purwarupa/Model/ Purwarupa/Model/ upa/Model/ sesuai dengan SBK Penanggulangan Publikasi Publikasi bereputasi Publikasi yang ditetapkan PMK Bencana bereputasi global/ global/ Publikasi bereputasi global/ untuk tiap-tiap Publikasi bereputasi nasional Publikasi kementerian/ bereputasi nasional sesuai kebutuhan bereputasi nasional lembaga. x Harga satuan KEGIATAN : PENDAMPINGAN, MONITORING, DAN EVALUASI STANDAR PELAYANAN MINIMAL SUB-URUSAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan pemantauan, pengamatan, pencatatan, pemonitoran, dan penilaian atas pelaksanaan tugas dan fungsi Operasional pemerintah melalui visitasi lapangan yang dilaksanakan secara berkesinambungan atas kebijakan strategis terkait Standar Pelayanan Minimal Sub-Urusan Bencana kabupaten/kota, baik dalam lingkup pembinaan dan pengawasan umum maupun pembinaan dan pengawasan teknis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (416, 'Penelitian dan Kekayaan Jumlah kekayaan Sesuai kebutuhan Jumlah kekayaan Harga satuan untuk Opsional Pengembangan intelektual/ intelektual/ intelektual/Purwar 1 (satu) satuan Bidang Purwarupa/Model/ Purwarupa/Model/ upa/Model/ sesuai dengan SBK Penanggulangan Publikasi Publikasi bereputasi Publikasi yang ditetapkan PMK Bencana bereputasi global/ global/ Publikasi bereputasi global/ untuk tiap-tiap Publikasi bereputasi nasional Publikasi kementerian/ bereputasi nasional sesuai kebutuhan bereputasi nasional lembaga. x Harga satuan KEGIATAN : PENDAMPINGAN, MONITORING, DAN EVALUASI STANDAR PELAYANAN MINIMAL SUB-URUSAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan pemantauan, pengamatan, pencatatan, pemonitoran, dan penilaian atas pelaksanaan tugas dan fungsi Operasional pemerintah melalui visitasi lapangan yang dilaksanakan secara berkesinambungan atas kebijakan strategis terkait Standar Pelayanan Minimal Sub-Urusan Bencana kabupaten/kota, baik dalam lingkup pembinaan dan pengawasan umum maupun pembinaan dan pengawasan teknis.', 'LAMPIRAN II (lanjutan 91)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (417, 'juklak-2-2026', 111, 'lampiran', 'LAMPIRAN II (lanjutan 92)', NULL, 100, 'Pendampingan Pendampingan Jumlah daerah Jumlah kegiatan Jumlah daerah x Harga satuan Opsional Monitoring dan diutamakan untuk sesuai kebutuhan Jumlah kegiatan x untuk 1 (satu) Evaluasi kabupaten/kota Harga satuan kegiatan untuk 1 dengan IP Standar (satu) daerah sesuai Pelayanan Minimal dengan SBK yang Sub-Urusan ditetapkan PMK Bencana dengan untuk tiap-tiap kategori Rendah kementerian/ Monitoring dan Jumlah daerah Jumlah kegiatan Jumlah daerah x lembaga. Opsional Evaluasi diutamakan untuk sesuai kebutuhan Jumlah kegiatan x kabupaten/kota Harga satuan dengan IP Standar Pelayanan Minimal Sub-Urusan Bencana dengan kategori Rendah PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan pemantauan, pengamatan, pencatatan, pemonitoran, dan penilaian atas pelaksanaan tugas dan fungsi Operasional pemerintah melalui visitasi lapangan yang dilaksanakan secara berkesinambungan atas kebijakan strategis terkait Standar Pelayanan Minimal Sub-Urusan Bencana kabupaten/kota, baik dalam lingkup pembinaan dan pengawasan umum maupun pembinaan dan pengawasan teknis.
Pendampingan Pendampingan Jumlah daerah Jumlah kegiatan Jumlah daerah x Harga satuan Opsional Monitoring dan diutamakan untuk sesuai kebutuhan Jumlah kegiatan x untuk 1 (satu) Evaluasi kabupaten/kota Harga satuan kegiatan untuk 1 dengan IP Standar (satu) daerah sesuai Pelayanan Minimal dengan SBU yang Sub-Urusan Bencana ditetapkan pada dengan kategori tiap-tiap provinsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (417, 'Pendampingan Pendampingan Jumlah daerah Jumlah kegiatan Jumlah daerah x Harga satuan Opsional Monitoring dan diutamakan untuk sesuai kebutuhan Jumlah kegiatan x untuk 1 (satu) Evaluasi kabupaten/kota Harga satuan kegiatan untuk 1 dengan IP Standar (satu) daerah sesuai Pelayanan Minimal dengan SBK yang Sub-Urusan ditetapkan PMK Bencana dengan untuk tiap-tiap kategori Rendah kementerian/ Monitoring dan Jumlah daerah Jumlah kegiatan Jumlah daerah x lembaga. Opsional Evaluasi diutamakan untuk sesuai kebutuhan Jumlah kegiatan x kabupaten/kota Harga satuan dengan IP Standar Pelayanan Minimal Sub-Urusan Bencana dengan kategori Rendah PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan pemantauan, pengamatan, pencatatan, pemonitoran, dan penilaian atas pelaksanaan tugas dan fungsi Operasional pemerintah melalui visitasi lapangan yang dilaksanakan secara berkesinambungan atas kebijakan strategis terkait Standar Pelayanan Minimal Sub-Urusan Bencana kabupaten/kota, baik dalam lingkup pembinaan dan pengawasan umum maupun pembinaan dan pengawasan teknis.
Pendampingan Pendampingan Jumlah daerah Jumlah kegiatan Jumlah daerah x Harga satuan Opsional Monitoring dan diutamakan untuk sesuai kebutuhan Jumlah kegiatan x untuk 1 (satu) Evaluasi kabupaten/kota Harga satuan kegiatan untuk 1 dengan IP Standar (satu) daerah sesuai Pelayanan Minimal dengan SBU yang Sub-Urusan Bencana ditetapkan pada dengan kategori tiap-tiap provinsi.', 'LAMPIRAN II (lanjutan 92)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (418, 'juklak-2-2026', 112, 'lampiran', 'LAMPIRAN II (lanjutan 93)', NULL, 101, 'Rendah Monitoring dan Jumlah daerah Jumlah kegiatan Jumlah daerah x Opsional Evaluasi diutamakan untuk sesuai kebutuhan Jumlah kegiatan x kabupaten/kota Harga satuan dengan IP Standar Pelayanan Minimal Sub-Urusan Bencana dengan kategori Rendah PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PENYUSUNAN STANDAR KOMPETENSI KERJA NASIONAL BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan yang dibutuhkan untuk merumuskan ataupun mengkaji ulang berbagai standar kemampuan kerja Operasional yang mencakup aspek pengetahuan, keterampilan dan/atau keahlian serta sikap kerja yang relevan dengan persyaratan profesi bidang penanggulangan bencana yang ditetapkan sesuai dengan ketentuan peraturan perundang-undangan. Khusus untuk pengkajian ulang SKKNI dapat dilakukan oleh Komite Standar Kompetensi sesuai dengan sektor atau lapangan usaha paling lama 5 (lima) tahun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (418, 'Rendah Monitoring dan Jumlah daerah Jumlah kegiatan Jumlah daerah x Opsional Evaluasi diutamakan untuk sesuai kebutuhan Jumlah kegiatan x kabupaten/kota Harga satuan dengan IP Standar Pelayanan Minimal Sub-Urusan Bencana dengan kategori Rendah PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PENYUSUNAN STANDAR KOMPETENSI KERJA NASIONAL BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan yang dibutuhkan untuk merumuskan ataupun mengkaji ulang berbagai standar kemampuan kerja Operasional yang mencakup aspek pengetahuan, keterampilan dan/atau keahlian serta sikap kerja yang relevan dengan persyaratan profesi bidang penanggulangan bencana yang ditetapkan sesuai dengan ketentuan peraturan perundang-undangan. Khusus untuk pengkajian ulang SKKNI dapat dilakukan oleh Komite Standar Kompetensi sesuai dengan sektor atau lapangan usaha paling lama 5 (lima) tahun.', 'LAMPIRAN II (lanjutan 93)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (419, 'juklak-2-2026', 113, 'lampiran', 'LAMPIRAN II (lanjutan 94)', NULL, 102, 'Perumusan rancangan SKKNI dapat dilakukan dengan metode riset, adaptasi dari standar internasional atau standar khusus, maupun adopsi dari standar internasional atau standar khusus Penyusunan Penyusunan SKKNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan Opsional SKKNI bidang bidang sesuai kebutuhan Harga satuan untuk 1 dokumen Penanggulangan penanggulangan disamakan dengan Bencana bencana melalui SBKK Penyusunan riset RSNI3 Bidang Penyusunan SKKNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Bidang Opsional bidang sesuai kebutuhan Harga satuan Penanggulangan penanggulangan Bencana sesuai bencana melalui dengan SBK yang adaptasi standar ditetapkan PMK yang ada untuk tiap-tiap Penyusunan SKKNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x kementerian/lemba Opsional bidang sesuai kebutuhan Harga satuan ga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (419, 'Perumusan rancangan SKKNI dapat dilakukan dengan metode riset, adaptasi dari standar internasional atau standar khusus, maupun adopsi dari standar internasional atau standar khusus Penyusunan Penyusunan SKKNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan Opsional SKKNI bidang bidang sesuai kebutuhan Harga satuan untuk 1 dokumen Penanggulangan penanggulangan disamakan dengan Bencana bencana melalui SBKK Penyusunan riset RSNI3 Bidang Penyusunan SKKNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Bidang Opsional bidang sesuai kebutuhan Harga satuan Penanggulangan penanggulangan Bencana sesuai bencana melalui dengan SBK yang adaptasi standar ditetapkan PMK yang ada untuk tiap-tiap Penyusunan SKKNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x kementerian/lemba Opsional bidang sesuai kebutuhan Harga satuan ga.', 'LAMPIRAN II (lanjutan 94)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (420, 'juklak-2-2026', 114, 'lampiran', 'LAMPIRAN II (lanjutan 95)', NULL, 102, 'penanggulangan bencana melalui adopsi standar yang ada Kaji ulang SKKNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Opsional bidang sesuai kebutuhan Harga satuan penanggulangan bencana PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PENYUSUNAN STANDAR NASIONAL INDONESIA BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan yang dibutuhkan untuk menyusun Standar Nasional Indonesia bidang penanggulangan bencana, Operasional mulai dari tahap pembahasan konsep sampai dengan tahap konsensus Komite Teknis Perumusan Standar Nasional Indonesia (SNI) tingkat kementerian/lembaga.
Penyusunan SNI bidang penanggulangan bencana dapat dalam bentuk:
1) Penyusunan SNI Bidang Penanggulangan Bencana melalui metode pengembangan sendiri RSNI3 yang disusun dengan metode pengembangan sendiri yaitu metode perumusan RSNI3 dengan cara penyusunan sendiri berdasarkan data/hasil penelitian dan menggunakan referensi dokumen acuan yang tertelusur.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (420, 'penanggulangan bencana melalui adopsi standar yang ada Kaji ulang SKKNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Opsional bidang sesuai kebutuhan Harga satuan penanggulangan bencana PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PENYUSUNAN STANDAR NASIONAL INDONESIA BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan yang dibutuhkan untuk menyusun Standar Nasional Indonesia bidang penanggulangan bencana, Operasional mulai dari tahap pembahasan konsep sampai dengan tahap konsensus Komite Teknis Perumusan Standar Nasional Indonesia (SNI) tingkat kementerian/lembaga.
Penyusunan SNI bidang penanggulangan bencana dapat dalam bentuk:
1) Penyusunan SNI Bidang Penanggulangan Bencana melalui metode pengembangan sendiri RSNI3 yang disusun dengan metode pengembangan sendiri yaitu metode perumusan RSNI3 dengan cara penyusunan sendiri berdasarkan data/hasil penelitian dan menggunakan referensi dokumen acuan yang tertelusur.', 'LAMPIRAN II (lanjutan 95)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (421, 'juklak-2-2026', 115, 'lampiran', 'LAMPIRAN II (lanjutan 96)', NULL, 104, '2) Penyusunan SNI Bidang Penanggulangan Bencana melalui metode adopsi modifikasi RSNI3 yang disusun dengan metode adopsi modifikasi yaitu metode perumusan RSNI3 dengan mengadopsi standar atau publikasi internasional secara modifikasi dengan cara publikasi ulang menggunakan terjemahan bahasa Indonesia mengacu pada bahasa asli standar atau publikasi internasional yang diadopsi.
3) Penyusunan SNI Bidang Penanggulangan Bencana melalui metode adopsi identik terjemahan RSNI3 yang disusun dengan metode adopsi identik terjemahan yaitu metode perumusan RSNI3 dengan mengadopsi standar atau publikasi internasional secara identik dengan cara publikasi ulang menggunakan terjemahan bahasa Indonesia mengacu pada bahasa asli standar atau publikasi internasional yang diadopsi.
4) Penyusunan SNI Bidang Penanggulangan Bencana melalui metode adopsi republikasi-reprint RSNI3 yang disusun dengan metode adopsi republikasi-reprint yaitu metode perumusan RSNI3 dengan mengadopsi standar atau publikasi internasional secara identik dengan cara publikasi ulang menggunakan bahasa asli standar atau publikasi internasional yang diadopsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (421, '2) Penyusunan SNI Bidang Penanggulangan Bencana melalui metode adopsi modifikasi RSNI3 yang disusun dengan metode adopsi modifikasi yaitu metode perumusan RSNI3 dengan mengadopsi standar atau publikasi internasional secara modifikasi dengan cara publikasi ulang menggunakan terjemahan bahasa Indonesia mengacu pada bahasa asli standar atau publikasi internasional yang diadopsi.
3) Penyusunan SNI Bidang Penanggulangan Bencana melalui metode adopsi identik terjemahan RSNI3 yang disusun dengan metode adopsi identik terjemahan yaitu metode perumusan RSNI3 dengan mengadopsi standar atau publikasi internasional secara identik dengan cara publikasi ulang menggunakan terjemahan bahasa Indonesia mengacu pada bahasa asli standar atau publikasi internasional yang diadopsi.
4) Penyusunan SNI Bidang Penanggulangan Bencana melalui metode adopsi republikasi-reprint RSNI3 yang disusun dengan metode adopsi republikasi-reprint yaitu metode perumusan RSNI3 dengan mengadopsi standar atau publikasi internasional secara identik dengan cara publikasi ulang menggunakan bahasa asli standar atau publikasi internasional yang diadopsi.', 'LAMPIRAN II (lanjutan 96)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (422, 'juklak-2-2026', 116, 'lampiran', 'LAMPIRAN II (lanjutan 97)', NULL, 104, 'Penyusunan SNI Penyusunan SNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan untuk Opsional bidang Bidang PB melalui sesuai kebutuhan Harga satuan 1 dokumen sesuai penanggulangan metode dengan SBK yang bencana pengembangan ditetapkan PMK sendiri untuk tiap-tiap Penyusunan SNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x kementerian/ Opsional Bidang PB melalui sesuai kebutuhan Harga satuan lembaga. metode adopsi modifikasi Penyusunan SNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Opsional Bidang PB melalui sesuai kebutuhan Harga satuan metode adopsi identik terjemahan Penyusunan SNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Opsional Bidang PB melalui sesuai kebutuhan Harga satuan metode adopsi republikasi-reprint PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PEMBANGUNAN DAN PENGEMBANGAN SISTEM INFORMASI BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Kegiatan pembangunan sistem informasi mencakup tahap awal seperti perencanaan, analisis kebutuhan, perancangan Operasional sistem, hingga implementasi dan pengujian. Sementara itu, pengembangan lebih menekankan pada peningkatan dan penyesuaian sistem yang telah ada agar tetap relevan, efisien, dan sesuai dengan perkembangan teknologi serta kebutuhan kementerian/lembaga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (422, 'Penyusunan SNI Penyusunan SNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan untuk Opsional bidang Bidang PB melalui sesuai kebutuhan Harga satuan 1 dokumen sesuai penanggulangan metode dengan SBK yang bencana pengembangan ditetapkan PMK sendiri untuk tiap-tiap Penyusunan SNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x kementerian/ Opsional Bidang PB melalui sesuai kebutuhan Harga satuan lembaga. metode adopsi modifikasi Penyusunan SNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Opsional Bidang PB melalui sesuai kebutuhan Harga satuan metode adopsi identik terjemahan Penyusunan SNI Jumlah dokumen Sesuai kebutuhan Jumlah dokumen x Opsional Bidang PB melalui sesuai kebutuhan Harga satuan metode adopsi republikasi-reprint PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi -tidak dilaksanakan Operasional KEGIATAN : PEMBANGUNAN DAN PENGEMBANGAN SISTEM INFORMASI BIDANG PENANGGULANGAN BENCANA SUB KATEGORI : PENYUSUNAN KEBIJAKAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Kegiatan pembangunan sistem informasi mencakup tahap awal seperti perencanaan, analisis kebutuhan, perancangan Operasional sistem, hingga implementasi dan pengujian. Sementara itu, pengembangan lebih menekankan pada peningkatan dan penyesuaian sistem yang telah ada agar tetap relevan, efisien, dan sesuai dengan perkembangan teknologi serta kebutuhan kementerian/lembaga.', 'LAMPIRAN II (lanjutan 97)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (423, 'juklak-2-2026', 117, 'lampiran', 'LAMPIRAN II (lanjutan 98)', NULL, 106, 'Sistem informasi digunakan untuk mengumpulkan, memproses, menyimpan, dan menganalisis informasi kebencanaan dengan memperhatikan interoperabilitas data statistik kebencanaan, untuk mendukung penyelenggaraan pada setiap tahap penanggulangan bencana (pra, saat, pasca) serta monitoring dan evaluasi penyelenggaraan penanggulangan bencana.
Pembangunan Pembuatan 1 (satu) dokumen 1 (satu) sistem Jumlah dokumen x Dapat dilakukan Pokok dan dokumen untuk 1 (satu) informasi yang Jumlah sistem secara swakelola Pengembangan perencanaan/ sistem informasi dibangun dan/atau informasi x Harga atau menggunakan Sistem Informasi desain sistem dikembangkan Satuan konsultan. informasi Pembuatan/ 1 (satu) paket 1 (satu) sistem Jumlah paket x 1. Dapat diajukan Opsional pengembangan informasi yang Jumlah sistem setelah sistem informasi dibangun dan/atau informasi x Harga pembuatan (hard code) dikembangkan Satuan dokumen Pembuatan/ 1 (satu) paket 1 (satu) sistem Jumlah paket x perencanaan Opsional pengembangan informasi yang Jumlah sistem dilaksanakan, interoperabilitas dibangun dan/atau informasi x Harga 2. Jumlah harga data dikembangkan Satuan berdasarkan dokumen perencanaan Maintenance sistem 1 (satu) paket 1 (satu) sistem Jumlah paket x 1. Dilakukan Opsional informasi informasi yang Jumlah sistem setelah sistem dibangun dan/atau informasi x Harga informasi dikembangkan Satuan terbangun
2. Biaya ini adalah untuk 1 (satu) tahun
3. Hanya dapat diajukan pada 1 (satu) tahun pertama saja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (423, 'Sistem informasi digunakan untuk mengumpulkan, memproses, menyimpan, dan menganalisis informasi kebencanaan dengan memperhatikan interoperabilitas data statistik kebencanaan, untuk mendukung penyelenggaraan pada setiap tahap penanggulangan bencana (pra, saat, pasca) serta monitoring dan evaluasi penyelenggaraan penanggulangan bencana.
