INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (428, 'juklak-2-2026', 122, 'lampiran', 'LAMPIRAN II (lanjutan 103)', NULL, 110, 'Pemantauan, Pemantauan, 1 (satu) dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan Pokok pengendalian, pengendalian, Harga satuan untuk 1 (satu) evaluasi, dan evaluasi dan dokumen sesuai pelaporan kinerja pelaporan kinerja dengan SBK yang penanggulangan penanggulangan ditetapkan PMK bencana bencana nasional untuk tiap-tiap kementerian/lemba ga.
PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan pemantauan, pengamatan, pencatatan, pemonitoran, dan penilaian atas pelaksanaan tugas dan fungsi Operasional pemerintah provinsi dan/atau kabupaten/kota dalam penanggulangan bencana berdasarkan metadata indikator kinerja yang ditetapkan.
Pemantauan, Pemantauan, 1 (satu) dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan Pokok pengendalian, pengendalian, Harga satuan untuk 1 (satu) evaluasi, dan evaluasi dan dokumen sesuai pelaporan kinerja pelaporan kinerja dengan SBK yang penanggulangan penanggulangan ditetapkan PMK bencana bencana provinsi untuk tiap-tiap kementerian/lemba ga dan/atau Standar Biaya yang berlaku di daerah PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk kegiatan pemantauan, pengamatan, pencatatan, pemonitoran, dan penilaian atas pelaksanaan tugas dan fungsi Operasional pemerintah kabupaten/kota dalam penanggulangan bencana berdasarkan meta data indikator kinerja yang ditetapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (428, 'Pemantauan, Pemantauan, 1 (satu) dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan Pokok pengendalian, pengendalian, Harga satuan untuk 1 (satu) evaluasi, dan evaluasi dan dokumen sesuai pelaporan kinerja pelaporan kinerja dengan SBK yang penanggulangan penanggulangan ditetapkan PMK bencana bencana nasional untuk tiap-tiap kementerian/lemba ga.
PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan pemantauan, pengamatan, pencatatan, pemonitoran, dan penilaian atas pelaksanaan tugas dan fungsi Operasional pemerintah provinsi dan/atau kabupaten/kota dalam penanggulangan bencana berdasarkan metadata indikator kinerja yang ditetapkan.
Pemantauan, Pemantauan, 1 (satu) dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan Pokok pengendalian, pengendalian, Harga satuan untuk 1 (satu) evaluasi, dan evaluasi dan dokumen sesuai pelaporan kinerja pelaporan kinerja dengan SBK yang penanggulangan penanggulangan ditetapkan PMK bencana bencana provinsi untuk tiap-tiap kementerian/lemba ga dan/atau Standar Biaya yang berlaku di daerah PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk kegiatan pemantauan, pengamatan, pencatatan, pemonitoran, dan penilaian atas pelaksanaan tugas dan fungsi Operasional pemerintah kabupaten/kota dalam penanggulangan bencana berdasarkan meta data indikator kinerja yang ditetapkan.', 'LAMPIRAN II (lanjutan 103)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (429, 'juklak-2-2026', 123, 'lampiran', 'LAMPIRAN II (lanjutan 104)', NULL, 111, 'Pemantauan, Pemantauan, 1 (satu) dokumen Sesuai kebutuhan Jumlah dokumen x Harga satuan untuk Pokok pengendalian, pengendalian, Harga satuan 1 (satu) dokumen evaluasi, dan evaluasi dan sesuai dengan SBK pelaporan kinerja pelaporan kinerja yang ditetapkan PMK penanggulangan penanggulangan untuk tiap-tiap bencana bencana kementerian/lembag kabupaten/kota a dan/atau Standar Biaya yang berlaku di daerah KEGIATAN : SOSIALISASI KEBENCANAAN KEPADA APARATUR DAN/ATAU MASYARAKAT SUB KATEGORI : MITIGASI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan untuk menyampaikan/menyebarluaskan informasi kebencanaan kepada aparatur dan/atau Operasional masyarakat secara tatap muka, baik informasi yang bersifat tematik bencana tertentu maupun informasi kebijakan nasional terkait penanggulangan bencana, dalam rangka meningkatkan pengetahuan masyarakat terhadap risiko bencana yang ada di lingkungannya.
Mengacu pada Peraturan Menteri Keuangan yang berlaku, sosialisasi dapat dilaksanakan dalam bentuk layanan sosialisasi dengan jumlah peserta minimal 50 (lima puluh) orang.
Sosialisasi Layanan sosialisasi minimal 50 (lima 1 (satu) lokasi Jumlah orang x Harga satuan Pokok kebencanaan puluh) orang Jumlah lokasi x untuk 1 (satu) kepada aparatur peserta Harga satuan lokasi kegiatan dan/atau sesuai dengan SBK masyarakat yang ditetapkan PMK untuk tiap-tiap kementerian/ lembaga.');
