INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (437, 'juklak-2-2026', 131, 'lampiran', 'LAMPIRAN II (lanjutan 112)', NULL, 117, 'memberikan respon yang cepat, tepat, dan efektif untuk menghadapi berbagai jenis bencana.
Dalam hal ini sektor publik termasuk namun tidak terbatas pada:
1. fasilitas kesehatan yang pengelolaannya oleh pemerintah pusat
2. fasilitas pendidikan tinggi (universitas, sekolah tinggi, dsb) dan/atau fasilitas pendidikan yang pengelolaannya berada di bawah kementerian/lembaga (madrasah, dsb).
3. fasilitas dan bangunan publik yang berada pada kawasan strategis nasional.
4. bangunan pemerintah (kantor pemerintah, bank, dsb) yang pengelolaannya oleh pemerintah pusat.
Sektor publik Fasilitas publik Jumlah fasilitas Jumlah daerah Jumlah fasilitas Dapat didetailkan Pokok tangguh bencana nasional publik disesuaikan disesuaikan dengan publik x Jumlah sesuai dengan dengan kebutuhan lokasi fasilitas lokasi x Harga Standar Biaya yang publik satuan berlaku di kementerian/ lembaga.
PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan sistematis untuk meningkatkan kapasitas sektor publik yang berada pada dalam kewenangan Operasional pemerintah provinsi, dalam memberikan respon yang cepat, tepat, dan efektif untuk menghadapi berbagai jenis bencana.
Dalam hal ini sektor publik termasuk namun tidak terbatas pada:
1. fasilitas kesehatan yang pengelolaannya oleh pemerintah provinsi.
2. fasilitas pendidikan menengah atas.
3. fasilitas dan bangunan publik yang berada pada kawasan strategis provinsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (437, 'memberikan respon yang cepat, tepat, dan efektif untuk menghadapi berbagai jenis bencana.
Dalam hal ini sektor publik termasuk namun tidak terbatas pada:
1. fasilitas kesehatan yang pengelolaannya oleh pemerintah pusat
2. fasilitas pendidikan tinggi (universitas, sekolah tinggi, dsb) dan/atau fasilitas pendidikan yang pengelolaannya berada di bawah kementerian/lembaga (madrasah, dsb).
3. fasilitas dan bangunan publik yang berada pada kawasan strategis nasional.
4. bangunan pemerintah (kantor pemerintah, bank, dsb) yang pengelolaannya oleh pemerintah pusat.
Sektor publik Fasilitas publik Jumlah fasilitas Jumlah daerah Jumlah fasilitas Dapat didetailkan Pokok tangguh bencana nasional publik disesuaikan disesuaikan dengan publik x Jumlah sesuai dengan dengan kebutuhan lokasi fasilitas lokasi x Harga Standar Biaya yang publik satuan berlaku di kementerian/ lembaga.
PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan sistematis untuk meningkatkan kapasitas sektor publik yang berada pada dalam kewenangan Operasional pemerintah provinsi, dalam memberikan respon yang cepat, tepat, dan efektif untuk menghadapi berbagai jenis bencana.
Dalam hal ini sektor publik termasuk namun tidak terbatas pada:
1. fasilitas kesehatan yang pengelolaannya oleh pemerintah provinsi.
2. fasilitas pendidikan menengah atas.
3. fasilitas dan bangunan publik yang berada pada kawasan strategis provinsi.', 'LAMPIRAN II (lanjutan 112)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (438, 'juklak-2-2026', 132, 'lampiran', 'LAMPIRAN II (lanjutan 113)', NULL, 119, '4. bangunan pemerintah (kantor pemerintah, bank, dsb) yang pengelolaannya oleh pemerintah provinsi.
Sektor publik Fasilitas publik Jumlah fasilitas Jumlah daerah Jumlah fasilitas Dapat didetailkan Pokok tangguh bencana provinsi publik disesuaikan disesuaikan dengan publik x Jumlah sesuai dengan dengan kebutuhan lokasi fasilitas lokasi x Harga Standar Biaya yang publik satuan berlaku di daerah PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk kegiatan sistematis untuk meningkatkan kapasitas sektor publik yang berada pada dalam kewenangan Operasional pemerintah kabupaten/kota, dalam memberikan respon yang cepat, tepat, dan efektif untuk menghadapi berbagai jenis bencana.
Dalam hal ini sektor publik termasuk namun tidak terbatas pada:
1. fasilitas kesehatan yang pengelolaannya oleh pemerintah kabupaten/kota.
2. fasilitas pendidikan dasar dan menengah pertama.
3. fasilitas perekonomian (pasar tradisional, dsb)
4. bangunan publik (kantor pemerintah, bank, dsb) yang pengelolaannya oleh pemerintah kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (438, '4. bangunan pemerintah (kantor pemerintah, bank, dsb) yang pengelolaannya oleh pemerintah provinsi.
Sektor publik Fasilitas publik Jumlah fasilitas Jumlah daerah Jumlah fasilitas Dapat didetailkan Pokok tangguh bencana provinsi publik disesuaikan disesuaikan dengan publik x Jumlah sesuai dengan dengan kebutuhan lokasi fasilitas lokasi x Harga Standar Biaya yang publik satuan berlaku di daerah PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk kegiatan sistematis untuk meningkatkan kapasitas sektor publik yang berada pada dalam kewenangan Operasional pemerintah kabupaten/kota, dalam memberikan respon yang cepat, tepat, dan efektif untuk menghadapi berbagai jenis bencana.
Dalam hal ini sektor publik termasuk namun tidak terbatas pada:
1. fasilitas kesehatan yang pengelolaannya oleh pemerintah kabupaten/kota.
2. fasilitas pendidikan dasar dan menengah pertama.
3. fasilitas perekonomian (pasar tradisional, dsb)
4. bangunan publik (kantor pemerintah, bank, dsb) yang pengelolaannya oleh pemerintah kabupaten/kota.', 'LAMPIRAN II (lanjutan 113)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (439, 'juklak-2-2026', 133, 'lampiran', 'LAMPIRAN II (lanjutan 114)', NULL, 120, 'Sektor publik Fasilitas publik Jumlah fasilitas Jumlah daerah Jumlah fasilitas Dapat didetailkan Pokok tangguh bencana kabupaten/kota publik disesuaikan disesuaikan dengan publik x Jumlah sesuai dengan dengan kebutuhan lokasi fasilitas lokasi x Harga Standar Biaya yang publik satuan berlaku di daerah KEGIATAN : PEMBENTUKAN/PENGEMBANGAN WILAYAH ADMINISTRATIF TANGGUH BENCANA SUB KATEGORI : MITIGASI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk pendampingan teknis untuk peningkatan kapasitas tata kelola risiko maupun teknis kebencanaan terhadap Operasional provinsi, kabupaten/kota, kecamatan, dan desa/kelurahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (439, 'Sektor publik Fasilitas publik Jumlah fasilitas Jumlah daerah Jumlah fasilitas Dapat didetailkan Pokok tangguh bencana kabupaten/kota publik disesuaikan disesuaikan dengan publik x Jumlah sesuai dengan dengan kebutuhan lokasi fasilitas lokasi x Harga Standar Biaya yang publik satuan berlaku di daerah KEGIATAN : PEMBENTUKAN/PENGEMBANGAN WILAYAH ADMINISTRATIF TANGGUH BENCANA SUB KATEGORI : MITIGASI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk pendampingan teknis untuk peningkatan kapasitas tata kelola risiko maupun teknis kebencanaan terhadap Operasional provinsi, kabupaten/kota, kecamatan, dan desa/kelurahan.', 'LAMPIRAN II (lanjutan 114)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (440, 'juklak-2-2026', 134, 'lampiran', 'LAMPIRAN II (lanjutan 115)', NULL, 121, 'Pembentukan Pendampingan Jumlah provinsi Sesuai kebutuhan Jumlah provinsi x Dapat didetailkan Pokok wilayah teknis provinsi sesuai kebutuhan Harga satuan sesuai dengan administratif tangguh bencana Standar Biaya yang tangguh bencana Pendampingan Jumlah kabupaten/ Sesuai kebutuhan Jumlah berlaku di Opsional teknis kota sesuai kabupaten/kota x kementerian/ kabupaten/Kota kebutuhan Harga satuan lembaga. tangguh bencana Pendampingan Jumlah kecamatan Sesuai kebutuhan Jumlah kecamatan Opsional teknis kecamatan sesuai kebutuhan x Harga satuan tangguh bencana Pendampingan Jumlah desa/ Sesuai kebutuhan Jumlah desa atau Opsional teknis desa/ kelurahan sesuai kelurahan x Harga kelurahan tangguh kebutuhan satuan bencana Pengembangan Pendampingan Jumlah provinsi Sesuai kebutuhan Jumlah provinsi x Dapat didetailkan Pokok wilayah teknis provinsi sesuai kebutuhan Harga satuan sesuai dengan administratif tangguh bencana Standar Biaya yang tangguh bencana Pendampingan Jumlah kabupaten/ Sesuai kebutuhan Jumlah berlaku di Opsional teknis kota sesuai kabupaten/kota x kementerian/ kabupaten/Kota kebutuhan Harga satuan lembaga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (440, 'Pembentukan Pendampingan Jumlah provinsi Sesuai kebutuhan Jumlah provinsi x Dapat didetailkan Pokok wilayah teknis provinsi sesuai kebutuhan Harga satuan sesuai dengan administratif tangguh bencana Standar Biaya yang tangguh bencana Pendampingan Jumlah kabupaten/ Sesuai kebutuhan Jumlah berlaku di Opsional teknis kota sesuai kabupaten/kota x kementerian/ kabupaten/Kota kebutuhan Harga satuan lembaga. tangguh bencana Pendampingan Jumlah kecamatan Sesuai kebutuhan Jumlah kecamatan Opsional teknis kecamatan sesuai kebutuhan x Harga satuan tangguh bencana Pendampingan Jumlah desa/ Sesuai kebutuhan Jumlah desa atau Opsional teknis desa/ kelurahan sesuai kelurahan x Harga kelurahan tangguh kebutuhan satuan bencana Pengembangan Pendampingan Jumlah provinsi Sesuai kebutuhan Jumlah provinsi x Dapat didetailkan Pokok wilayah teknis provinsi sesuai kebutuhan Harga satuan sesuai dengan administratif tangguh bencana Standar Biaya yang tangguh bencana Pendampingan Jumlah kabupaten/ Sesuai kebutuhan Jumlah berlaku di Opsional teknis kota sesuai kabupaten/kota x kementerian/ kabupaten/Kota kebutuhan Harga satuan lembaga.', 'LAMPIRAN II (lanjutan 115)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (441, 'juklak-2-2026', 135, 'lampiran', 'LAMPIRAN II (lanjutan 116)', NULL, 121, 'tangguh bencana Pendampingan Jumlah kecamatan Sesuai kebutuhan Jumlah kecamatan Bagi yang sudah Opsional teknis kecamatan sesuai kebutuhan x Harga satuan membentuk wilayah tangguh bencana Pendampingan Jumlah desa/ Sesuai kebutuhan Jumlah desa atau administratif Opsional teknis desa/ kelurahan sesuai kelurahan x Harga tangguh bencana kelurahan tangguh kebutuhan satuan bencana PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk pelaksanaan kegiatan peningkatan kapasitas tata kelola risiko maupun teknis kebencanaan pada wilayah Operasional administratif provinsi, dan/atau pendampingan teknis untuk peningkatan kapasitas tata kelola risiko maupun teknis kebencanaan terhadap kabupaten/kota, kecamatan, dan desa/kelurahan, yang berada di dalam wilayah provinsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (441, 'tangguh bencana Pendampingan Jumlah kecamatan Sesuai kebutuhan Jumlah kecamatan Bagi yang sudah Opsional teknis kecamatan sesuai kebutuhan x Harga satuan membentuk wilayah tangguh bencana Pendampingan Jumlah desa/ Sesuai kebutuhan Jumlah desa atau administratif Opsional teknis desa/ kelurahan sesuai kelurahan x Harga tangguh bencana kelurahan tangguh kebutuhan satuan bencana PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk pelaksanaan kegiatan peningkatan kapasitas tata kelola risiko maupun teknis kebencanaan pada wilayah Operasional administratif provinsi, dan/atau pendampingan teknis untuk peningkatan kapasitas tata kelola risiko maupun teknis kebencanaan terhadap kabupaten/kota, kecamatan, dan desa/kelurahan, yang berada di dalam wilayah provinsi.', 'LAMPIRAN II (lanjutan 116)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (442, 'juklak-2-2026', 136, 'lampiran', 'LAMPIRAN II (lanjutan 117)', NULL, 122, 'Pembentukan Pendampingan Jumlah kabupaten/ Sesuai kebutuhan Jumlah Dapat didetailkan Pokok wilayah teknis kota sesuai kabupaten/kota x sesuai dengan administratif kabupaten/Kota kebutuhan Harga satuan Standar Biaya yang tangguh bencana tangguh bencana berlaku di daerah Pendampingan Jumlah provinsi Sesuai kebutuhan Jumlah provinsi x Opsional teknis provinsi sesuai kebutuhan Harga satuan tangguh bencana Pendampingan Jumlah kecamatan Sesuai kebutuhan Jumlah kecamatan Opsional teknis kecamatan sesuai kebutuhan x Harga satuan tangguh bencana Pendampingan Jumlah desa/ Sesuai kebutuhan Jumlah desa atau Opsional teknis desa/ kelurahan sesuai kelurahan x Harga kelurahan tangguh kebutuhan satuan bencana Pengembangan Pendampingan Jumlah kabupaten/ Sesuai kebutuhan Jumlah Dapat didetailkan Pokok wilayah teknis kota sesuai kabupaten/kota x sesuai dengan administratif kabupaten/Kota kebutuhan Harga satuan Standar Biaya yang tangguh bencana tangguh bencana berlaku di daerah Pendampingan Jumlah provinsi Sesuai kebutuhan Jumlah provinsi x Opsional teknis provinsi sesuai kebutuhan Harga satuan Bagi yang sudah tangguh bencana membentuk wilayah Pendampingan Jumlah kecamatan Sesuai kebutuhan Jumlah kecamatan administratif Opsional teknis kecamatan sesuai kebutuhan x Harga satuan tangguh bencana tangguh bencana Pendampingan Jumlah desa/ Sesuai kebutuhan Jumlah desa atau Opsional teknis desa/ kelurahan sesuai kelurahan x Harga kelurahan tangguh kebutuhan satuan bencana PEMOHON: PEMERINTAH DAERAH');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (442, 'Pembentukan Pendampingan Jumlah kabupaten/ Sesuai kebutuhan Jumlah Dapat didetailkan Pokok wilayah teknis kota sesuai kabupaten/kota x sesuai dengan administratif kabupaten/Kota kebutuhan Harga satuan Standar Biaya yang tangguh bencana tangguh bencana berlaku di daerah Pendampingan Jumlah provinsi Sesuai kebutuhan Jumlah provinsi x Opsional teknis provinsi sesuai kebutuhan Harga satuan tangguh bencana Pendampingan Jumlah kecamatan Sesuai kebutuhan Jumlah kecamatan Opsional teknis kecamatan sesuai kebutuhan x Harga satuan tangguh bencana Pendampingan Jumlah desa/ Sesuai kebutuhan Jumlah desa atau Opsional teknis desa/ kelurahan sesuai kelurahan x Harga kelurahan tangguh kebutuhan satuan bencana Pengembangan Pendampingan Jumlah kabupaten/ Sesuai kebutuhan Jumlah Dapat didetailkan Pokok wilayah teknis kota sesuai kabupaten/kota x sesuai dengan administratif kabupaten/Kota kebutuhan Harga satuan Standar Biaya yang tangguh bencana tangguh bencana berlaku di daerah Pendampingan Jumlah provinsi Sesuai kebutuhan Jumlah provinsi x Opsional teknis provinsi sesuai kebutuhan Harga satuan Bagi yang sudah tangguh bencana membentuk wilayah Pendampingan Jumlah kecamatan Sesuai kebutuhan Jumlah kecamatan administratif Opsional teknis kecamatan sesuai kebutuhan x Harga satuan tangguh bencana tangguh bencana Pendampingan Jumlah desa/ Sesuai kebutuhan Jumlah desa atau Opsional teknis desa/ kelurahan sesuai kelurahan x Harga kelurahan tangguh kebutuhan satuan bencana PEMOHON: PEMERINTAH DAERAH', 'LAMPIRAN II (lanjutan 117)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (443, 'juklak-2-2026', 137, 'lampiran', 'LAMPIRAN II (lanjutan 118)', NULL, 122, 'KABUPATEN/KOTA Definisi Segala bentuk pelaksanaan kegiatan peningkatan kapasitas tata kelola risiko maupun teknis kebencanaan pada wilayah Operasional administratif kabupaten/kota atau dibawahnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (443, 'KABUPATEN/KOTA Definisi Segala bentuk pelaksanaan kegiatan peningkatan kapasitas tata kelola risiko maupun teknis kebencanaan pada wilayah Operasional administratif kabupaten/kota atau dibawahnya.', 'LAMPIRAN II (lanjutan 118)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (444, 'juklak-2-2026', 138, 'lampiran', 'LAMPIRAN II (lanjutan 119)', NULL, 123, 'Pembentukan Pendampingan Jumlah desa/ Sesuai kebutuhan Jumlah desa atau Dapat didetailkan Pokok wilayah teknis desa/ kelurahan sesuai kelurahan x Harga sesuai dengan administratif kelurahan tangguh kebutuhan satuan Standar Biaya yang tangguh bencana bencana berlaku di daerah Pendampingan Jumlah kabupaten/ Sesuai kebutuhan Jumlah Opsional teknis kota sesuai kabupaten/kota x kabupaten/kota kebutuhan Harga satuan tangguh bencana Pendampingan Jumlah kecamatan Sesuai kebutuhan Jumlah kecamatan Opsional teknis kecamatan sesuai kebutuhan x Harga satuan tangguh bencana Pengembangan Pendampingan Jumlah desa/ Sesuai kebutuhan Jumlah desa atau Dapat didetailkan Pokok wilayah teknis desa/ kelurahan sesuai kelurahan x Harga sesuai dengan administratif kelurahan tangguh kebutuhan satuan Standar Biaya yang tangguh bencana bencana berlaku di daerah Pendampingan Jumlah kabupaten/ Sesuai kebutuhan Jumlah Opsional teknis kota sesuai kabupaten/kota x Bagi yang sudah kabupaten/kota kebutuhan harga satuan membentuk wilayah tangguh bencana administratif Pendampingan Jumlah kecamatan Sesuai kebutuhan Jumlah kecamatan tangguh bencana Opsional teknis kecamatan sesuai kebutuhan x harga satuan tangguh bencana KEGIATAN : PEMBENTUKAN/PENGEMBANGAN KOMUNITAS TANGGUH BENCANA SUB KATEGORI : MITIGASI PEMOHON: KEMENTERIAN/LEMBAGA Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (444, 'Pembentukan Pendampingan Jumlah desa/ Sesuai kebutuhan Jumlah desa atau Dapat didetailkan Pokok wilayah teknis desa/ kelurahan sesuai kelurahan x Harga sesuai dengan administratif kelurahan tangguh kebutuhan satuan Standar Biaya yang tangguh bencana bencana berlaku di daerah Pendampingan Jumlah kabupaten/ Sesuai kebutuhan Jumlah Opsional teknis kota sesuai kabupaten/kota x kabupaten/kota kebutuhan Harga satuan tangguh bencana Pendampingan Jumlah kecamatan Sesuai kebutuhan Jumlah kecamatan Opsional teknis kecamatan sesuai kebutuhan x Harga satuan tangguh bencana Pengembangan Pendampingan Jumlah desa/ Sesuai kebutuhan Jumlah desa atau Dapat didetailkan Pokok wilayah teknis desa/ kelurahan sesuai kelurahan x Harga sesuai dengan administratif kelurahan tangguh kebutuhan satuan Standar Biaya yang tangguh bencana bencana berlaku di daerah Pendampingan Jumlah kabupaten/ Sesuai kebutuhan Jumlah Opsional teknis kota sesuai kabupaten/kota x Bagi yang sudah kabupaten/kota kebutuhan harga satuan membentuk wilayah tangguh bencana administratif Pendampingan Jumlah kecamatan Sesuai kebutuhan Jumlah kecamatan tangguh bencana Opsional teknis kecamatan sesuai kebutuhan x harga satuan tangguh bencana KEGIATAN : PEMBENTUKAN/PENGEMBANGAN KOMUNITAS TANGGUH BENCANA SUB KATEGORI : MITIGASI PEMOHON: KEMENTERIAN/LEMBAGA Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi -tidak dilaksanakan Operasional PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk', 'LAMPIRAN II (lanjutan 119)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (445, 'juklak-2-2026', 139, 'lampiran', 'LAMPIRAN II (lanjutan 120)', NULL, 123, 'kegiatan peningkatan pengetahuan dan keterampilan terkait kebencanaan bagi berbagai kelompok komunitas Operasional - termasuk komunitas profesi maupun komunitas hobi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (445, 'kegiatan peningkatan pengetahuan dan keterampilan terkait kebencanaan bagi berbagai kelompok komunitas Operasional - termasuk komunitas profesi maupun komunitas hobi.', 'LAMPIRAN II (lanjutan 120)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (446, 'juklak-2-2026', 140, 'lampiran', 'LAMPIRAN II (lanjutan 121)', NULL, 125, 'Pembentukan Pembentukan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas Dapat didetailkan Pokok komunitas komunitas tangguh x Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas berlaku di daerah Opsional teknis x Jumlah lokasi x pembentukan Harga satuan komunitas tangguh bencana Pengembangan Pengembangan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas Dapat didetailkan Pokok komunitas komunitas tangguh x Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas berlaku di daerah. Opsional teknis x Jumlah lokasi x pengembangan Harga satuan Bagi yang sudah komunitas tangguh membentuk bencana komunitas tangguh bencana PEMOHON: KELOMPOK MASYARAKAT Definisi Segala bentuk kegiatan yang memfasilitasi berbagai inisiatif dari berbagai kelompok komunitas - termasuk komunitas profesi Operasional maupun komunitas hobi - dalam peningkatan pengetahuan dan keterampilan terkait kebencanaan Pembentukan Pembentukan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas Dapat didetailkan Pokok komunitas komunitas tangguh x Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas berlaku di daerah Opsional teknis x Jumlah lokasi x pembentukan Harga satuan komunitas tangguh bencana Pengembangan Pengembangan 1');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (446, 'Pembentukan Pembentukan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas Dapat didetailkan Pokok komunitas komunitas tangguh x Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas berlaku di daerah Opsional teknis x Jumlah lokasi x pembentukan Harga satuan komunitas tangguh bencana Pengembangan Pengembangan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas Dapat didetailkan Pokok komunitas komunitas tangguh x Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas berlaku di daerah. Opsional teknis x Jumlah lokasi x pengembangan Harga satuan Bagi yang sudah komunitas tangguh membentuk bencana komunitas tangguh bencana PEMOHON: KELOMPOK MASYARAKAT Definisi Segala bentuk kegiatan yang memfasilitasi berbagai inisiatif dari berbagai kelompok komunitas - termasuk komunitas profesi Operasional maupun komunitas hobi - dalam peningkatan pengetahuan dan keterampilan terkait kebencanaan Pembentukan Pembentukan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas Dapat didetailkan Pokok komunitas komunitas tangguh x Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas berlaku di daerah Opsional teknis x Jumlah lokasi x pembentukan Harga satuan komunitas tangguh bencana Pengembangan Pengembangan 1', 'LAMPIRAN II (lanjutan 121)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (447, 'juklak-2-2026', 141, 'lampiran', 'LAMPIRAN II (lanjutan 122)', NULL, 125, '(satu) komunitas 1 (satu) lokasi Jumlah komunitas Dapat didetailkan Pokok komunitas komunitas tangguh x Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas berlaku di daerah. Opsional teknis x Jumlah lokasi x pengembangan Harga satuan Bagi yang sudah komunitas tangguh membentuk bencana komunitas tangguh bencana Fasilitator Honorarium Maksimal 2 (dua) Jumlah bulan Jumlah fasilitator x Penetapan jumlah Pokok fasilitator lapangan orang per kawasan/ pekerjaan jumlah bulan kerja fasilitator lapangan kecamatan/ x Harga satuan tidak boleh lebih desa/kelurahan dari 6 (enam) orang untuk 7 (tujuh) bulan kerja KEGIATAN : PEMBENTUKAN/PENGEMBANGAN KAWASAN TANGGUH BENCANA SUB KATEGORI : MITIGASI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan dalam rangka mempersiapkan suatu wilayah yang berada pada kawasan yang menjadi kewenangan Operasional pemerintah pusat secara khusus untuk menghadapi dan memulihkan diri dari bencana dengan memprioritaskan pada penguatan tata kelola, pengetahuan, dan keterampilan terkait kesiapsiagaan bencana. Dalam hal ini termasuk kawasan strategis nasional, kawasan rawan bencana yang lanskap nya berada pada 2 (dua) provinsi atau lebih.
Misal: KSPN tangguh bencana, KEK tangguh bencana, dsb.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (447, '(satu) komunitas 1 (satu) lokasi Jumlah komunitas Dapat didetailkan Pokok komunitas komunitas tangguh x Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) komunitas 1 (satu) lokasi Jumlah komunitas berlaku di daerah. Opsional teknis x Jumlah lokasi x pengembangan Harga satuan Bagi yang sudah komunitas tangguh membentuk bencana komunitas tangguh bencana Fasilitator Honorarium Maksimal 2 (dua) Jumlah bulan Jumlah fasilitator x Penetapan jumlah Pokok fasilitator lapangan orang per kawasan/ pekerjaan jumlah bulan kerja fasilitator lapangan kecamatan/ x Harga satuan tidak boleh lebih desa/kelurahan dari 6 (enam) orang untuk 7 (tujuh) bulan kerja KEGIATAN : PEMBENTUKAN/PENGEMBANGAN KAWASAN TANGGUH BENCANA SUB KATEGORI : MITIGASI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan dalam rangka mempersiapkan suatu wilayah yang berada pada kawasan yang menjadi kewenangan Operasional pemerintah pusat secara khusus untuk menghadapi dan memulihkan diri dari bencana dengan memprioritaskan pada penguatan tata kelola, pengetahuan, dan keterampilan terkait kesiapsiagaan bencana. Dalam hal ini termasuk kawasan strategis nasional, kawasan rawan bencana yang lanskap nya berada pada 2 (dua) provinsi atau lebih.
Misal: KSPN tangguh bencana, KEK tangguh bencana, dsb.', 'LAMPIRAN II (lanjutan 122)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (448, 'juklak-2-2026', 142, 'lampiran', 'LAMPIRAN II (lanjutan 123)', NULL, 127, 'Pembentukan Pembentukan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x Dapat didetailkan Pokok kawasan kawasan tangguh Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x berlaku di Opsional teknis Jumlah lokasi x kementerian/lemba pembentukan Harga satuan ga. kawasan tangguh bencana Pengembangan Pengembangan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x Dapat didetailkan Pokok kawasan kawasan tangguh Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x berlaku di Opsional teknis Jumlah lokasi x kementerian/ pengembangan Harga satuan lembaga kawasan tangguh Bagi yang sudah bencana membentuk kawasan tangguh bencana PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan dalam rangka mempersiapkan suatu wilayah yang berada pada kawasan yang menjadi kewenangan Operasional pemerintah provinsi secara khusus untuk menghadapi dan memulihkan diri dari bencana dengan memprioritaskan pada penguatan tata kelola, pengetahuan, dan keterampilan terkait kesiapsiagaan bencana. Dalam hal ini termasuk kawasan strategis provinsi, kawasan rawan bencana yang lanskap nya berada pada 2 kabupaten/kota atau lebih.
Misal: kawasan industri tangguh bencana, kawasan DAS tangguh bencana, dsb.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (448, 'Pembentukan Pembentukan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x Dapat didetailkan Pokok kawasan kawasan tangguh Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x berlaku di Opsional teknis Jumlah lokasi x kementerian/lemba pembentukan Harga satuan ga. kawasan tangguh bencana Pengembangan Pengembangan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x Dapat didetailkan Pokok kawasan kawasan tangguh Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x berlaku di Opsional teknis Jumlah lokasi x kementerian/ pengembangan Harga satuan lembaga kawasan tangguh Bagi yang sudah bencana membentuk kawasan tangguh bencana PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan dalam rangka mempersiapkan suatu wilayah yang berada pada kawasan yang menjadi kewenangan Operasional pemerintah provinsi secara khusus untuk menghadapi dan memulihkan diri dari bencana dengan memprioritaskan pada penguatan tata kelola, pengetahuan, dan keterampilan terkait kesiapsiagaan bencana. Dalam hal ini termasuk kawasan strategis provinsi, kawasan rawan bencana yang lanskap nya berada pada 2 kabupaten/kota atau lebih.
Misal: kawasan industri tangguh bencana, kawasan DAS tangguh bencana, dsb.', 'LAMPIRAN II (lanjutan 123)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (449, 'juklak-2-2026', 143, 'lampiran', 'LAMPIRAN II (lanjutan 124)', NULL, 128, 'Pembentukan Pembentukan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x Dapat didetailkan Pokok kawasan kawasan tangguh Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x berlaku di daerah Opsional teknis Jumlah lokasi x pembentukan Harga satuan kawasan tangguh bencana Pengembangan Pengembangan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x Dapat didetailkan Pokok kawasan kawasan tangguh Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x berlaku di daerah Opsional teknis Jumlah lokasi x Bagi yang sudah pengembangan Harga satuan membentuk kawasan tangguh kawasan tangguh bencana bencana PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk kegiatan dalam rangka mempersiapkan suatu wilayah yang berada pada kawasan yang menjadi kewenangan Operasional pemerintah kabupaten/kota secara khusus untuk menghadapi dan memulihkan diri dari bencana dengan memprioritaskan pada penguatan tata kelola, pengetahuan, dan keterampilan terkait kesiapsiagaan bencana. Dalam hal ini termasuk kawasan strategis daerah, kawasan rawan bencana yang lanskapnya berada pada di dalam satu wilayah kabupaten/kota, dsb.
Misal: kawasan cagar budaya tangguh bencana, kawasan pariwisata daerah tangguh bencana, dsb.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (449, 'Pembentukan Pembentukan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x Dapat didetailkan Pokok kawasan kawasan tangguh Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x berlaku di daerah Opsional teknis Jumlah lokasi x pembentukan Harga satuan kawasan tangguh bencana Pengembangan Pengembangan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x Dapat didetailkan Pokok kawasan kawasan tangguh Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x berlaku di daerah Opsional teknis Jumlah lokasi x Bagi yang sudah pengembangan Harga satuan membentuk kawasan tangguh kawasan tangguh bencana bencana PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk kegiatan dalam rangka mempersiapkan suatu wilayah yang berada pada kawasan yang menjadi kewenangan Operasional pemerintah kabupaten/kota secara khusus untuk menghadapi dan memulihkan diri dari bencana dengan memprioritaskan pada penguatan tata kelola, pengetahuan, dan keterampilan terkait kesiapsiagaan bencana. Dalam hal ini termasuk kawasan strategis daerah, kawasan rawan bencana yang lanskapnya berada pada di dalam satu wilayah kabupaten/kota, dsb.
Misal: kawasan cagar budaya tangguh bencana, kawasan pariwisata daerah tangguh bencana, dsb.', 'LAMPIRAN II (lanjutan 124)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (450, 'juklak-2-2026', 144, 'lampiran', 'LAMPIRAN II (lanjutan 125)', NULL, 129, 'Pembentukan Pembentukan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x Dapat didetailkan Pokok kawasan kawasan tangguh Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x berlaku di daerah Opsional teknis Jumlah lokasi x pembentukan Harga satuan kawasan tangguh bencana Pengembangan Pengembangan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x Dapat didetailkan Pokok kawasan kawasan tangguh Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x berlaku di daerah Opsional teknis Jumlah lokasi x pengembangan Harga satuan Bagi yang sudah kawasan tangguh membentuk bencana kawasan tangguh bencana KEGIATAN : MITIGASI BENCANA BERBASIS ALAM (NATURE-BASED SOLUTION) SUB KATEGORI : MITIGASI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Kegiatan fasilitasi, pembinaan, dan/atau pendekatan pengurangan risiko bencana dengan mengoptimalkan fungsi alamiah di Operasional kawasan berisiko bencana, yang dilaksanakan pada kawasan strategis nasional dan kawasan lain dalam kewenangan pemerintah pusat, untuk mengurangi dampak kejadian bencana, baik dalam rangka konservasi, rehabilitasi vegetatif, maupun pendekatan lain berbasis alam.
Contoh: a) Pembangunan jalur hijau di kawasan pulau-pulau kecil pada kawasan strategis nasional, b) Rehabilitasi kawasan hutan di kawasan rawan bencana kebakaran hutan dan lahan, dsb.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (450, 'Pembentukan Pembentukan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x Dapat didetailkan Pokok kawasan kawasan tangguh Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x berlaku di daerah Opsional teknis Jumlah lokasi x pembentukan Harga satuan kawasan tangguh bencana Pengembangan Pengembangan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x Dapat didetailkan Pokok kawasan kawasan tangguh Jumlah lokasi x sesuai dengan tangguh bencana bencana Harga satuan Standar Biaya yang Pendampingan 1 (satu) kawasan 1 (satu) lokasi Jumlah kawasan x berlaku di daerah Opsional teknis Jumlah lokasi x pengembangan Harga satuan Bagi yang sudah kawasan tangguh membentuk bencana kawasan tangguh bencana KEGIATAN : MITIGASI BENCANA BERBASIS ALAM (NATURE-BASED SOLUTION) SUB KATEGORI : MITIGASI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Kegiatan fasilitasi, pembinaan, dan/atau pendekatan pengurangan risiko bencana dengan mengoptimalkan fungsi alamiah di Operasional kawasan berisiko bencana, yang dilaksanakan pada kawasan strategis nasional dan kawasan lain dalam kewenangan pemerintah pusat, untuk mengurangi dampak kejadian bencana, baik dalam rangka konservasi, rehabilitasi vegetatif, maupun pendekatan lain berbasis alam.
Contoh: a) Pembangunan jalur hijau di kawasan pulau-pulau kecil pada kawasan strategis nasional, b) Rehabilitasi kawasan hutan di kawasan rawan bencana kebakaran hutan dan lahan, dsb.', 'LAMPIRAN II (lanjutan 125)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (451, 'juklak-2-2026', 145, 'lampiran', 'LAMPIRAN II (lanjutan 126)', NULL, 130, 'Mitigasi bencana Pembangunan Jumlah hektar Sesuai kebutuhan Jumlah hektar x Harga satuan per Pokok berbasis alam mitigasi bencana disesuaikan dengan Harga satuan hektar, sudah berbasis alam luas kawasan termasuk biaya mitigasi bencana bahan baku, honor, berbasis alam dsb - tidak termasuk pemeliharaan.
Biaya pemeliharaan menjadi tanggung jawab pemrakarsa Perencanaan dan Jumlah paket sesuai Sesuai kebutuhan Jumlah paket x Opsional koordinasi kebutuhan Harga satuan pembangunan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Kegiatan fasilitasi, pembinaan, dan/atau pendekatan pengurangan risiko bencana dengan mengoptimalkan fungsi alamiah di Operasional kawasan berisiko bencana, yang dilaksanakan pada kawasan yang menjadi kewenangan pemerintah provinsi untuk mengurangi dampak kejadian bencana, baik dalam rangka konservasi, rehabilitasi vegetatif, maupun pendekatan lain berbasis alam.
Contoh:
PEMOHON: PEMERINTAH DAERAH PROVINSI a) Penghijauan pada hulu DAS rawan banjir bandang yang menjadi kewenangan pemerintah provinsi, b) Konservasi dan rehabilitasi hutan dan mangrove di kawasan pesisir rawan bencana tsunami, c) Pembangunan jalur hijau di kawasan pesisir rawan bencana gelombang ekstrim dan abrasi, dsb.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (451, 'Mitigasi bencana Pembangunan Jumlah hektar Sesuai kebutuhan Jumlah hektar x Harga satuan per Pokok berbasis alam mitigasi bencana disesuaikan dengan Harga satuan hektar, sudah berbasis alam luas kawasan termasuk biaya mitigasi bencana bahan baku, honor, berbasis alam dsb - tidak termasuk pemeliharaan.
Biaya pemeliharaan menjadi tanggung jawab pemrakarsa Perencanaan dan Jumlah paket sesuai Sesuai kebutuhan Jumlah paket x Opsional koordinasi kebutuhan Harga satuan pembangunan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Kegiatan fasilitasi, pembinaan, dan/atau pendekatan pengurangan risiko bencana dengan mengoptimalkan fungsi alamiah di Operasional kawasan berisiko bencana, yang dilaksanakan pada kawasan yang menjadi kewenangan pemerintah provinsi untuk mengurangi dampak kejadian bencana, baik dalam rangka konservasi, rehabilitasi vegetatif, maupun pendekatan lain berbasis alam.
Contoh:
PEMOHON: PEMERINTAH DAERAH PROVINSI a) Penghijauan pada hulu DAS rawan banjir bandang yang menjadi kewenangan pemerintah provinsi, b) Konservasi dan rehabilitasi hutan dan mangrove di kawasan pesisir rawan bencana tsunami, c) Pembangunan jalur hijau di kawasan pesisir rawan bencana gelombang ekstrim dan abrasi, dsb.', 'LAMPIRAN II (lanjutan 126)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (452, 'juklak-2-2026', 146, 'lampiran', 'LAMPIRAN II (lanjutan 127)', NULL, 131, 'Mitigasi bencana Pembangunan Jumlah hektar Sesuai kebutuhan Jumlah hektar x Harga satuan per Pokok berbasis alam mitigasi bencana disesuaikan dengan Harga satuan hektar, sudah berbasis alam luas kawasan termasuk biaya mitigasi bencana bahan baku, honor, berbasis alam dsb - tidak termasuk pemeliharaan.
Biaya pemeliharaan menjadi tanggung jawab pemrakarsa Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Kegiatan fasilitasi, pembinaan, dan/atau pendekatan pengurangan risiko bencana dengan mengoptimalkan fungsi alamiah di Operasional kawasan berisiko bencana, yang dilaksanakan pada kawasan yang menjadi kewenangan pemerintah kabupaten/kota untuk mengurangi dampak kejadian bencana, baik dalam rangka konservasi, rehabilitasi vegetatif, maupun pendekatan lain berbasis alam.
Contoh: a) Penanaman pohon pada tebing rawan longsor b) Reboisasi pada kawasan hutan adat di kawasan rawan banjir dan longsor Mitigasi bencana Pembangunan Jumlah hektar Sesuai kebutuhan Jumlah hektar x Harga satuan per Pokok berbasis alam mitigasi bencana disesuaikan dengan Harga satuan hektar, sudah berbasis alam luas kawasan termasuk biaya mitigasi bencana bahan baku, honor, berbasis alam dsb - tidak termasuk pemeliharaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (452, 'Mitigasi bencana Pembangunan Jumlah hektar Sesuai kebutuhan Jumlah hektar x Harga satuan per Pokok berbasis alam mitigasi bencana disesuaikan dengan Harga satuan hektar, sudah berbasis alam luas kawasan termasuk biaya mitigasi bencana bahan baku, honor, berbasis alam dsb - tidak termasuk pemeliharaan.
