INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (453, 'juklak-2-2026', 147, 'lampiran', 'LAMPIRAN II (lanjutan 128)', NULL, 132, 'Biaya pemeliharaan menjadi tanggung jawab pemrakarsa Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan PEMOHON: KELOMPOK MASYARAKAT Definisi Kegiatan fasilitasi, pembinaan, dan/atau pendekatan pengurangan risiko bencana dengan mengoptimalkan fungsi alamiah Operasional di kawasan berisiko bencana, yang dilaksanakan pada kawasan yang diinisiasi oleh kelompok masyarakat untuk mengurangi dampak kejadian bencana, baik dalam rangka konservasi, rehabilitasi vegetatif, maupun pendekatan lain berbasis alam.
Contoh: a) Penanaman pohon pada tebing rawan longsor, b) Reboisasi pada kawasan hutan adat di kawasan rawan banjir dan longsor Mitigasi bencana Pembangunan Jumlah hektar Sesuai kebutuhan Jumlah hektar x Harga satuan per Pokok berbasis alam mitigasi bencana disesuaikan dengan Harga satuan hektar, sudah berbasis alam luas kawasan termasuk biaya mitigasi bencana bahan baku, honor, berbasis alam dsb - tidak termasuk pemeliharaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (453, 'Biaya pemeliharaan menjadi tanggung jawab pemrakarsa Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan PEMOHON: KELOMPOK MASYARAKAT Definisi Kegiatan fasilitasi, pembinaan, dan/atau pendekatan pengurangan risiko bencana dengan mengoptimalkan fungsi alamiah Operasional di kawasan berisiko bencana, yang dilaksanakan pada kawasan yang diinisiasi oleh kelompok masyarakat untuk mengurangi dampak kejadian bencana, baik dalam rangka konservasi, rehabilitasi vegetatif, maupun pendekatan lain berbasis alam.
Contoh: a) Penanaman pohon pada tebing rawan longsor, b) Reboisasi pada kawasan hutan adat di kawasan rawan banjir dan longsor Mitigasi bencana Pembangunan Jumlah hektar Sesuai kebutuhan Jumlah hektar x Harga satuan per Pokok berbasis alam mitigasi bencana disesuaikan dengan Harga satuan hektar, sudah berbasis alam luas kawasan termasuk biaya mitigasi bencana bahan baku, honor, berbasis alam dsb - tidak termasuk pemeliharaan.', 'LAMPIRAN II (lanjutan 128)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (454, 'juklak-2-2026', 148, 'lampiran', 'LAMPIRAN II (lanjutan 129)', NULL, 133, 'Biaya pemeliharaan menjadi tanggung jawab pemrakarsa Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Fasilitator Honorarium Maksimal 1 (satu) Jumlah bulan Jumlah fasilitator x Penetapan jumlah Pokok fasilitator lapangan orang per kawasan/ pekerjaan jumlah bulan kerja fasilitator lapangan kecamatan/desa/ x Harga satuan tidak boleh lebih kelurahan dari 2 (dua) orang untuk 6 (enam) bulan kerja KEGIATAN : PEMBANGUNAN/PENGUATAN INFRASTRUKTUR PENDUKUNG KETAHANAN BENCANA SUB KATEGORI : MITIGASI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan pembangunan infrastruktur pada wilayah dan/atau lingkup kewenangan pemerintah pusat dengan Operasional tujuan mengurangi risiko dan meningkatkan ketahanan terhadap bencana.
Contoh pembangunan infrastruktur pendukung ketahanan bencana diantaranya:
1) Pembuatan bronjong pada DAS rawan longsor 2) Pembuatan tanggul air pada kawasan rawan kebakaran hutan dan lahan yang menjadi kewenangan pemerintah pusat, dsb Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan/ Pembangunan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Harga satuan Pokok penguatan struktural Jumlah lokasi x untuk 1 (satu) infrastruktur Harga satuan kegiatan dapat pendukung didetailkan sesuai ketahanan dengan Standar bencana Biaya yang berlaku di kementerian/ lembaga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (454, 'Biaya pemeliharaan menjadi tanggung jawab pemrakarsa Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Fasilitator Honorarium Maksimal 1 (satu) Jumlah bulan Jumlah fasilitator x Penetapan jumlah Pokok fasilitator lapangan orang per kawasan/ pekerjaan jumlah bulan kerja fasilitator lapangan kecamatan/desa/ x Harga satuan tidak boleh lebih kelurahan dari 2 (dua) orang untuk 6 (enam) bulan kerja KEGIATAN : PEMBANGUNAN/PENGUATAN INFRASTRUKTUR PENDUKUNG KETAHANAN BENCANA SUB KATEGORI : MITIGASI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan pembangunan infrastruktur pada wilayah dan/atau lingkup kewenangan pemerintah pusat dengan Operasional tujuan mengurangi risiko dan meningkatkan ketahanan terhadap bencana.
