INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (455, 'juklak-2-2026', 149, 'lampiran', 'LAMPIRAN II (lanjutan 130)', NULL, 134, 'Penguatan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Dilakukan terhadap Pokok struktural Jumlah lokasi x infrastruktur yang Harga satuan telah ada.
PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan pembangunan infrastruktur pada wilayah dan/atau lingkup kewenangan pemerintah provinsi Operasional dengan tujuan mengurangi risiko dan meningkatkan ketahanan terhadap bencana.
Contoh pembangunan infrastruktur pendukung ketahanan bencana diantaranya:
PEMOHON: PEMERINTAH DAERAH PROVINSI 1) Pembuatan bronjong sederhana pada DAS rawan longsor 2) Pengerukan sungai yang menjadi kewenangan provinsi, dsb Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan/ Pembangunan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Harga satuan untuk Pokok penguatan struktural Jumlah lokasi x 1 (satu) kegiatan infrastruktur Harga satuan dapat didetailkan pendukung sesuai dengan ketahanan Standar Biaya yang bencana berlaku di daerah Penguatan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Harga satuan untuk Pokok struktural Jumlah lokasi x 1 (satu) kegiatan Harga satuan dapat didetailkan sesuai dengan Standar Biaya yang berlaku di daerah.
Dilakukan terhadap infrastruktur yang telah ada.');
