INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (457, 'juklak-2-2026', 151, 'lampiran', 'LAMPIRAN II (lanjutan 132)', NULL, 137, 'KEGIATAN : PENINGKATAN KAPASITAS BADAN AIR SUB KATEGORI : MITIGASI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan untuk meningkatkan kemampuan suatu badan air dalam lingkup kewenangan pemerintah pusat, Operasional seperti sungai, waduk, atau danau, untuk menampung air baik dalam hal volume maupun kualitas, melalui pembangunan infrastruktur baru, perbaikan infrastruktur yang sudah ada, atau pengelolaan yang lebih baik terhadap badan air terkait.
Contoh upaya peningkatan kapasitas badan air antara lain adalah:
1. Normalisasi sungai
2. Pembangunan tanggul sungai, dsb.
Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Peningkatan Peningkatan/ 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Harga satuan Pokok kapasitas badan perbaikan Jumlah lokasi x untuk 1 (satu) air infrastruktur Harga satuan kegiatan dapat didetailkan sesuai dengan Standar Biaya yang berlaku di kementerian/ lembaga.
Pembangunan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Harga satuan Opsional infrastruktur Jumlah lokasi x untuk 1 (satu) Harga satuan kegiatan dapat didetailkan sesuai dengan Standar Biaya yang berlaku di kementerian/ lembaga.
Pengelolaan badan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Harga satuan Opsional air Jumlah lokasi x untuk 1 (satu) Harga satuan kegiatan dapat didetailkan sesuai dengan Standar Biaya yang berlaku di kementerian/ lembaga.');
