INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (459, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Peningkatan Peningkatan/ 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Harga satuan untuk Pokok kapasitas badan perbaikan Jumlah lokasi x 1 (satu) kegiatan air infrastruktur Harga satuan dapat didetailkan sesuai dengan Standar Biaya yang berlaku di daerah Pembangunan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Harga satuan untuk Opsional infrastruktur Jumlah lokasi x 1 (satu) kegiatan Harga satuan dapat didetailkan sesuai dengan Standar Biaya yang berlaku di daerah Pengelolaan badan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Harga satuan untuk Opsional air Jumlah lokasi x 1 (satu) kegiatan Harga satuan dapat didetailkan sesuai dengan Standar Biaya yang berlaku di daerah PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk kegiatan untuk meningkatkan kemampuan suatu badan air dalam lingkup kewenangan pemerintah Operasional kabupaten/kota, seperti sungai, waduk, atau danau, untuk menampung air baik dalam hal volume maupun kualitas, melalui pembangunan infrastruktur baru, perbaikan infrastruktur yang sudah ada, atau pengelolaan yang lebih baik terhadap badan air terkait.
Contoh upaya peningkatan kapasitas badan air antara lain adalah:
1. Normalisasi sungai
2. Pembangunan tanggul sungai, dsb.', 'LAMPIRAN II (lanjutan 134)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (460, 'juklak-2-2026', 154, 'lampiran', 'LAMPIRAN II (lanjutan 135)', NULL, 139, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Peningkatan Peningkatan/ 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Harga satuan untuk Pokok kapasitas badan perbaikan Jumlah lokasi x 1 (satu) kegiatan air infrastruktur Harga satuan dapat didetailkan sesuai dengan Standar Biaya yang berlaku di daerah Pembangunan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Harga satuan untuk Opsional infrastruktur Jumlah lokasi x 1 (satu) kegiatan Harga satuan dapat didetailkan sesuai dengan Standar Biaya yang berlaku di daerah Pengelolaan badan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Harga satuan untuk Opsional air Jumlah lokasi x 1 (satu) kegiatan Harga satuan dapat didetailkan sesuai dengan Standar Biaya yang berlaku di daerah KEGIATAN : PENATAAN BANGUNAN DAN/ATAU LINGKUNGAN DI KAWASAN RAWAN BENCANA SUB KATEGORI : MITIGASI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan dalam lingkup kewenangan pemerintah pusat yang bertujuan mengendalikan pemanfaatan ruang dan Operasional menciptakan lingkungan yang tangguh bencana, tertata, berkelanjutan, berkualitas serta menambah vitalitas ekonomi dan kehidupan masyarakat.');
