INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (467, 'juklak-2-2026', 161, 'lampiran', 'LAMPIRAN II (lanjutan 142)', NULL, 146, 'Koordinasi Transport Peserta Jumlah peserta Jumlah rapat Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah rapat x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 5 (lima) Opsional dan fasilitator narasumber sesuai sesuai kebutuhan narasumber x kali Rapat kebutuhan (maksimal 4 Jumlah jam kerja x koordinasi (empat) jam kerja Jumlah rpat x total untuk 1 (satu) Harga Satuan kali rapat) Paket pertemuan Jumlah peserta Jumlah rapat Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah rapat x Harga satuan Konsumsi rapat Jumlah peserta Jumlah rapat Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah rapat x Harga satuan Snack rapat Jumlah peserta Jumlah rapat Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah rapat x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah rapat Jumlah peserta x Opsional lembar materi yang sesuai kebutuhan Jumlah rapat x dibutuhkan Harga satuan Penyusunan Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Rencana Ketua Tim Ketua Tim Jumlah bulan kerja bulan Relokasi x Harga satuan Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 6 (enam) Opsional tenaga ahli maksimal 1 (satu) tiap-tiap tenaga ahli x Jumlah bulan bulan orang kerja x Harga satuan Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 6 (enam) Opsional tenaga ahli maksimal 1 (satu) tiap-tiap tenaga ahli x');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (467, 'Koordinasi Transport Peserta Jumlah peserta Jumlah rapat Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah rapat x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 5 (lima) Opsional dan fasilitator narasumber sesuai sesuai kebutuhan narasumber x kali Rapat kebutuhan (maksimal 4 Jumlah jam kerja x koordinasi (empat) jam kerja Jumlah rpat x total untuk 1 (satu) Harga Satuan kali rapat) Paket pertemuan Jumlah peserta Jumlah rapat Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah rapat x Harga satuan Konsumsi rapat Jumlah peserta Jumlah rapat Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah rapat x Harga satuan Snack rapat Jumlah peserta Jumlah rapat Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah rapat x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah rapat Jumlah peserta x Opsional lembar materi yang sesuai kebutuhan Jumlah rapat x dibutuhkan Harga satuan Penyusunan Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Rencana Ketua Tim Ketua Tim Jumlah bulan kerja bulan Relokasi x Harga satuan Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 6 (enam) Opsional tenaga ahli maksimal 1 (satu) tiap-tiap tenaga ahli x Jumlah bulan bulan orang kerja x Harga satuan Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Maksimal 6 (enam) Opsional tenaga ahli maksimal 1 (satu) tiap-tiap tenaga ahli x', 'LAMPIRAN II (lanjutan 142)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (468, 'juklak-2-2026', 162, 'lampiran', 'LAMPIRAN II (lanjutan 143)', NULL, 146, 'Jumlah bulan bulan orang kerja x Harga satuan Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tim penulis Maksimal 6 (enam) Opsional tim penulis penulis maksimal 1 tiap-tiap tenaga x Jumlah bulan bulan (satu) orang penulis kerja x Harga satuan Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Opsional tim substansi/ tim sesuai kebutuhan atau hari kerja tiap- Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan tiap tim substansi/ atau hari kerja x dan ditetapkan identifikasi tim teknis Harga satuan melalui Surat Perangkat Daerah Keputusan Eselon II dan entitas utama terkait relokasi berdasarkan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (468, 'Jumlah bulan bulan orang kerja x Harga satuan Biaya honorarium Jumlah tenaga Jumlah bulan kerja Jumlah tim penulis Maksimal 6 (enam) Opsional tim penulis penulis maksimal 1 tiap-tiap tenaga x Jumlah bulan bulan (satu) orang penulis kerja x Harga satuan Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Opsional tim substansi/ tim sesuai kebutuhan atau hari kerja tiap- Jumlah bulan kerja diluar tenaga ahli teknis berdasarkan tiap tim substansi/ atau hari kerja x dan ditetapkan identifikasi tim teknis Harga satuan melalui Surat Perangkat Daerah Keputusan Eselon II dan entitas utama terkait relokasi berdasarkan ketentuan peraturan perundang-undangan.', 'LAMPIRAN II (lanjutan 143)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (469, 'juklak-2-2026', 163, 'lampiran', 'LAMPIRAN II (lanjutan 144)', NULL, 148, 'Paket Lokakarya Jumlah peserta Jumlah pertemuan Jumlah peserta x Maksimal 5 (lima) Opsional sesuai kebutuhan sesuai kebutuhan Jumlah diskusi t x kali Lokakarya Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan Relokasi Relokasi 1 (satu) kegiatan Sesuai kebutuhan Jumlah kegiatan x Harga satuan Opsional masyarakat masyarakat berisiko Harga satuan untuk 1 (satu) dan/atau bencana kegiatan dapat bangunan didetailkan sesuai dengan Standar Biaya yang berlaku di daerah Relokasi bangunan Jumlah unit sesuai sesuai Kebutuhan Jumlah unit x Harga satuan Opsional berisiko bencana kebutuhan Harga satuan untuk 1 (satu) unit dapat didetailkan sesuai dengan Standar Biaya yang berlaku di daerah PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk kegiatan pemindahan penduduk dan/atau bangunan dari lokasi yang berisiko bencana ke lokasi yang lebih Operasional aman dengan tujuan untuk mengurangi dampak bencana terhadap masyarakat.');
