INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (472, 'juklak-2-2026', 166, 'lampiran', 'LAMPIRAN II (lanjutan 147)', NULL, 150, 'Paket Lokakarya Jumlah peserta Jumlah pertemuan Jumlah peserta x Maksimal 5 (lima) Opsional sesuai kebutuhan sesuai kebutuhan Jumlah diskusi t x kali Lokakarya Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan Relokasi Relokasi 1 (satu) kegiatan Sesuai kebutuhan Jumlah kegiatan x Harga satuan untuk Opsional masyarakat masyarakat berisiko Harga satuan 1 (satu) kegiatan dan/atau bencana dapat didetailkan bangunan sesuai dengan Standar Biaya yang berlaku di daerah Relokasi bangunan Jumlah unit sesuai sesuai Kebutuhan Jumlah unit x Harga satuan untuk Opsional berisiko bencana kebutuhan Harga satuan 1 (satu) unit dapat didetailkan sesuai dengan Standar Biaya yang berlaku di daerah KEGIATAN : PEMBENTUKAN/PENGUATAN FORUM PENGURANGAN RISIKO BENCANA SUB KATEGORI : KESIAPSIAGAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan untuk membentuk wadah yang menyatukan unsur-unsur organisasi/kelompok pemangku Operasional kepentingan di tingkat nasional yang berkemauan untuk mendukung upaya-upaya tematik maupun holistik untuk pengurangan risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (472, 'Paket Lokakarya Jumlah peserta Jumlah pertemuan Jumlah peserta x Maksimal 5 (lima) Opsional sesuai kebutuhan sesuai kebutuhan Jumlah diskusi t x kali Lokakarya Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Cetak dokumen Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional penggandaan Jumlah eksemplar penggandaan x penggandaan Harga satuan Relokasi Relokasi 1 (satu) kegiatan Sesuai kebutuhan Jumlah kegiatan x Harga satuan untuk Opsional masyarakat masyarakat berisiko Harga satuan 1 (satu) kegiatan dan/atau bencana dapat didetailkan bangunan sesuai dengan Standar Biaya yang berlaku di daerah Relokasi bangunan Jumlah unit sesuai sesuai Kebutuhan Jumlah unit x Harga satuan untuk Opsional berisiko bencana kebutuhan Harga satuan 1 (satu) unit dapat didetailkan sesuai dengan Standar Biaya yang berlaku di daerah KEGIATAN : PEMBENTUKAN/PENGUATAN FORUM PENGURANGAN RISIKO BENCANA SUB KATEGORI : KESIAPSIAGAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan untuk membentuk wadah yang menyatukan unsur-unsur organisasi/kelompok pemangku Operasional kepentingan di tingkat nasional yang berkemauan untuk mendukung upaya-upaya tematik maupun holistik untuk pengurangan risiko bencana.', 'LAMPIRAN II (lanjutan 147)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (473, 'juklak-2-2026', 167, 'lampiran', 'LAMPIRAN II (lanjutan 148)', NULL, 152, 'Forum ini menyediakan mekanisme koordinasi untuk meningkatkan kerja sama berbagai pemangku kepentingan dalam keberlanjutan kegiatan-kegiatan pengurangan risiko bencana melalui proses yang konsultatif dan partisipatif.
Forum Pengurangan Risiko Bencana dalam hal ini juga termasuk forum-forum tematik terkait kebencanaan di tingkat nasional seperti: Forum Komunikasi Satu Data Bencana, Forum Manajemen Krisis Kepariwisataan, Forum Resiliensi Berkelanjutan, dsb.
Pembentukan Pembentukan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Dapat didetailkan Pokok Forum PRB Forum PRB Jumlah lokasi x sesuai dengan Nasional Harga satuan Standar Biaya yang Pendampingan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x berlaku di Opsional pembentukan Jumlah lokasi x kementerian/ Forum PRB Provinsi Harga satuan lembaga.
Pendampingan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Opsional pembentukan Jumlah lokasi x Forum PRB Harga satuan Kabupaten/Kota Penguatan Penguatan Forum 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Dapat didetailkan Pokok Forum PRB PRB Nasional Jumlah lokasi x sesuai dengan Harga satuan Standar Biaya yang Pendampingan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x berlaku di Opsional penguatan Forum Jumlah lokasi x kementerian/ PRB Provinsi Harga satuan lembaga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (473, 'Forum ini menyediakan mekanisme koordinasi untuk meningkatkan kerja sama berbagai pemangku kepentingan dalam keberlanjutan kegiatan-kegiatan pengurangan risiko bencana melalui proses yang konsultatif dan partisipatif.
Forum Pengurangan Risiko Bencana dalam hal ini juga termasuk forum-forum tematik terkait kebencanaan di tingkat nasional seperti: Forum Komunikasi Satu Data Bencana, Forum Manajemen Krisis Kepariwisataan, Forum Resiliensi Berkelanjutan, dsb.
Pembentukan Pembentukan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Dapat didetailkan Pokok Forum PRB Forum PRB Jumlah lokasi x sesuai dengan Nasional Harga satuan Standar Biaya yang Pendampingan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x berlaku di Opsional pembentukan Jumlah lokasi x kementerian/ Forum PRB Provinsi Harga satuan lembaga.
Pendampingan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Opsional pembentukan Jumlah lokasi x Forum PRB Harga satuan Kabupaten/Kota Penguatan Penguatan Forum 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Dapat didetailkan Pokok Forum PRB PRB Nasional Jumlah lokasi x sesuai dengan Harga satuan Standar Biaya yang Pendampingan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x berlaku di Opsional penguatan Forum Jumlah lokasi x kementerian/ PRB Provinsi Harga satuan lembaga.', 'LAMPIRAN II (lanjutan 148)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (474, 'juklak-2-2026', 168, 'lampiran', 'LAMPIRAN II (lanjutan 149)', NULL, 153, 'Pendampingan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Opsional penguatan Forum Jumlah lokasi x Bagi yang sudah PRB Kabupaten/ Harga satuan membentuk Forum Kota PRB PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan untuk membentuk wadah yang menyatukan unsur-unsur organisasi/kelompok pemangku Operasional kepentingan di tingkat provinsi yang berkemauan untuk mendukung upaya-upaya tematik maupun holistik untuk pengurangan risiko bencana.
Forum ini menyediakan mekanisme koordinasi untuk meningkatkan kerja sama berbagai pemangku kepentingan dalam keberlanjutan kegiatan-kegiatan pengurangan risiko bencana melalui proses yang konsultatif dan partisipatif.
