INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (478, 'Pembentukan Pendampingan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Dapat didetailkan Pokok Forum PRB pembentukan Jumlah lokasi x sesuai dengan Forum PRB Harga satuan Standar Biaya yang Komunitas berlaku di daerah Pendampingan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Opsional Forum PRB Jumlah lokasi x Kabupaten/Kota Harga satuan Pendampingan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Opsional pembentukan Jumlah lokasi x Forum PRB Harga satuan Kecamatan dan Desa/Kelurahan Penguatan Pendampingan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Dapat didetailkan Pokok Forum PRB penguatan Forum Jumlah lokasi x sesuai dengan PRB Komunitas Harga satuan Penguatan Forum 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Standar Biaya yang Opsional PRB Kabupaten/ Jumlah lokasi x berlaku di daerah Kota Harga satuan Pendampingan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x Bagi yang sudah Opsional penguatan Forum Jumlah lokasi x membentuk Forum PRB Kecamatan Harga satuan PRB dan Desa/ Kelurahan Pendampingan 1 (satu) kegiatan 1 (satu) lokasi Jumlah kegiatan x penguatan Forum Jumlah lokasi x PRB Kecamatan Harga satuan dan Desa/ Kelurahan Fasilitator Honorarium Maksimal 2 (dua) Jumlah bulan Jumlah fasilitator x Penetapan jumlah Pokok fasilitator lapangan orang pekerjaan jumlah bulan kerja fasilitator lapangan x Harga satuan tidak boleh lebih dari 6 (enam) bulan kerja KEGIATAN : PEMBENTUKAN/PENGUATAN KLASTER PENANGGULANGAN BENCANA SUB KATEGORI :', 'LAMPIRAN II (lanjutan 153)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (479, 'juklak-2-2026', 173, 'lampiran', 'LAMPIRAN II (lanjutan 154)', NULL, 155, 'KESIAPSIAGAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Pembentukan klaster penanggulangan bencana adalah segala bentuk kegiatan untuk membentuk klaster pada lingkup Operasional kewenangan pemerintah pusat dalam rangka membangun kemandirian pengurangan risiko dan respon penanggulangan bencana dan bersifat sukarela melalui kerja sama antara pemerintah dengan lembaga masyarakat dan lembaga usaha, termasuk diantaranya, namun tidak terbatas pada:
1) Sosialisasi Pembentukan Klaster 2) Identifikasi dan pemetaan anggota klaster;
3) Penyusunan produk hukum dan pengorganisasian; dan 4) Pengukuhan dan sosialisasi surat keputusan pembentukan klaster.
Penguatan klaster penanggulangan bencana adalah segala bentuk kegiatan untuk mengembangkan klaster pada lingkup kewenangan pemerintah pusat dalam rangka membangun kemandirian pengurangan risiko dan respon penanggulangan bencana dan bersifat sukarela melalui kerja sama antara pemerintah dengan lembaga masyarakat dan lembaga usaha, termasuk diantaranya, namun tidak terbatas pada:
1) Sosialisasi SK Klaster Logistik dan Aplikasi Lapor Klaster 2) Identifikasi sumber daya anggota Klaster 3) Penyusunan Rencana Kerja Klaster 4) Penyusunan SOP Klaster 5) Penyusunan Konsep Operasi Klaster Logistik 6) Simulasi/ Uji SOP dan Konsep Operasi Klaster.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (479, 'KESIAPSIAGAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Pembentukan klaster penanggulangan bencana adalah segala bentuk kegiatan untuk membentuk klaster pada lingkup Operasional kewenangan pemerintah pusat dalam rangka membangun kemandirian pengurangan risiko dan respon penanggulangan bencana dan bersifat sukarela melalui kerja sama antara pemerintah dengan lembaga masyarakat dan lembaga usaha, termasuk diantaranya, namun tidak terbatas pada:
1) Sosialisasi Pembentukan Klaster 2) Identifikasi dan pemetaan anggota klaster;
3) Penyusunan produk hukum dan pengorganisasian; dan 4) Pengukuhan dan sosialisasi surat keputusan pembentukan klaster.
Penguatan klaster penanggulangan bencana adalah segala bentuk kegiatan untuk mengembangkan klaster pada lingkup kewenangan pemerintah pusat dalam rangka membangun kemandirian pengurangan risiko dan respon penanggulangan bencana dan bersifat sukarela melalui kerja sama antara pemerintah dengan lembaga masyarakat dan lembaga usaha, termasuk diantaranya, namun tidak terbatas pada:
1) Sosialisasi SK Klaster Logistik dan Aplikasi Lapor Klaster 2) Identifikasi sumber daya anggota Klaster 3) Penyusunan Rencana Kerja Klaster 4) Penyusunan SOP Klaster 5) Penyusunan Konsep Operasi Klaster Logistik 6) Simulasi/ Uji SOP dan Konsep Operasi Klaster.', 'LAMPIRAN II (lanjutan 154)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (480, 'juklak-2-2026', 174, 'lampiran', 'LAMPIRAN II (lanjutan 155)', NULL, 157, 'PEMBENTUKAN KLASTER PENANGGULANGAN BENCANA Lokakarya Biaya honorarium Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Pokok Sosialisasi narasumber narasumber sesuai sesuai kebutuhan narasumber x kali lokakarya Pembentukan kebutuhan (maksimal 4 Jumlah jam kerja x Klaster (maksimal 2 (dua) (empat) jam kerja Jumlah kegiatan x orang) total untuk 1 (satu) Harga Satuan kali kegiatan) Biaya honorarium Jumlah Fasilitator/ Jumlah jam kerja Jumlah fasilitator/ Pokok Fasilitator/ Moderator sesuai sesuai kebutuhan moderator x Moderator kebutuhan (maksimal 4 Jumlah jam kerja x (maksimal 2 (dua) (empat) jam kerja Jumlah kegiatan x orang) total untuk 1 (satu) Harga Satuan kali kegiatan) Transport Peserta Jumlah peserta Jumlah lokakarya Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah lokakarya x Harga satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk di luar Opsional dinas yang berada di luar 1 (satu) kali Jumlah lokakarya x Jabodetabek Jabodetabek atau lokakarya Jumlah hari x sesuai kebutuhan (Maksimal 3 hari Harga satuan untuk 1 (satu) kali lokakarya) Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (480, 'PEMBENTUKAN KLASTER PENANGGULANGAN BENCANA Lokakarya Biaya honorarium Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Pokok Sosialisasi narasumber narasumber sesuai sesuai kebutuhan narasumber x kali lokakarya Pembentukan kebutuhan (maksimal 4 Jumlah jam kerja x Klaster (maksimal 2 (dua) (empat) jam kerja Jumlah kegiatan x orang) total untuk 1 (satu) Harga Satuan kali kegiatan) Biaya honorarium Jumlah Fasilitator/ Jumlah jam kerja Jumlah fasilitator/ Pokok Fasilitator/ Moderator sesuai sesuai kebutuhan moderator x Moderator kebutuhan (maksimal 4 Jumlah jam kerja x (maksimal 2 (dua) (empat) jam kerja Jumlah kegiatan x orang) total untuk 1 (satu) Harga Satuan kali kegiatan) Transport Peserta Jumlah peserta Jumlah lokakarya Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah lokakarya x Harga satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk di luar Opsional dinas yang berada di luar 1 (satu) kali Jumlah lokakarya x Jabodetabek Jabodetabek atau lokakarya Jumlah hari x sesuai kebutuhan (Maksimal 3 hari Harga satuan untuk 1 (satu) kali lokakarya) Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai', 'LAMPIRAN II (lanjutan 155)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
