INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (484, 'dinas yang berada di luar 1 (satu) kali Jumlah lokakarya x Jabodetabek Jabodetabek atau lokakarya Jumlah hari x sesuai kebutuhan (Maksimal 3 hari Harga satuan untuk 1 (satu) kali lokakarya) Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah personil x Maksimal 5 (lima) Pokok Penyusunan tenaga ahli sesuai kebutuhan sesuai kebutuhan Jumlah bulan kerja kali Diskusi Teknis Rencana Kerja, (maksimal 2 (dua) (maksimal 8 x Harga Satuan SOP, dan Konsep orang) (delapan) bulan) Operasi Klaster Biaya honorarium Jumlah Fasilitator/ Jumlah jam kerja Jumlah fasilitator/ Pokok Fasilitator/ Moderator sesuai sesuai kebutuhan moderator x Moderator kebutuhan (maksimal 4 Jumlah jam kerja x (maksimal 2 (dua) (empat) jam kerja Jumlah kegiatan x orang) total untuk 1 (satu) Harga Satuan kali kegiatan) Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai', 'LAMPIRAN II (lanjutan 159)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (485, 'juklak-2-2026', 179, 'lampiran', 'LAMPIRAN II (lanjutan 160)', NULL, 157, 'Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Opsional narasumber sesuai sesuai kebutuhan narasumber x kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Diskusi total untuk 1 (satu) Teknis x Harga kali Diskusi Teknis) Satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk di luar Opsional dinas yang berada di luar 1 (satu) kali Diskusi Jumlah Diskusi Jabodetabek Jabodetabek atau Teknis (maksimal 2 Teknis x Jumlah sesuai kebutuhan (dua) hari untuk 1 hari x Harga satuan (satu) kali Diskusi Teknis) Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Lokakarya Transport Peserta Jumlah peserta Jumlah Lokakarya Jumlah peserta x Pokok Simulasi/Uji SOP sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya Klaster x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali kebutuhan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (485, 'Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Opsional narasumber sesuai sesuai kebutuhan narasumber x kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Diskusi total untuk 1 (satu) Teknis x Harga kali Diskusi Teknis) Satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk di luar Opsional dinas yang berada di luar 1 (satu) kali Diskusi Jumlah Diskusi Jabodetabek Jabodetabek atau Teknis (maksimal 2 Teknis x Jumlah sesuai kebutuhan (dua) hari untuk 1 hari x Harga satuan (satu) kali Diskusi Teknis) Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Lokakarya Transport Peserta Jumlah peserta Jumlah Lokakarya Jumlah peserta x Pokok Simulasi/Uji SOP sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya Klaster x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali kebutuhan', 'LAMPIRAN II (lanjutan 160)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (486, 'juklak-2-2026', 180, 'lampiran', 'LAMPIRAN II (lanjutan 161)', NULL, 157, '(maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Lokakarya total untuk 1 (satu) x Harga satuan kali Lokakarya) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk di luar Opsional dinas yang berada di luar 1 (satu) kali Jumlah Lokakarya Jabodetabek Jabodetabek atau Lokakarya x Jumlah hari x sesuai kebutuhan (maksimal 4 hari Harga satuan untuk 1 (satu) kali rapat) Paket pertemuan Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Penggandaan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Kegiatan penggandaan Jumlah eksemplar Laporan penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Pembentukan klaster penanggulangan bencana adalah segala bentuk kegiatan untuk membentuk klaster pada lingkup Operasional kewenangan pemerintah provinsi dalam rangka membangun kemandirian pengurangan risiko dan respon penanggulangan bencana dan bersifat sukarela melalui kerja sama antara pemerintah');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (486, '(maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Lokakarya total untuk 1 (satu) x Harga satuan kali Lokakarya) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk di luar Opsional dinas yang berada di luar 1 (satu) kali Jumlah Lokakarya Jabodetabek Jabodetabek atau Lokakarya x Jumlah hari x sesuai kebutuhan (maksimal 4 hari Harga satuan untuk 1 (satu) kali rapat) Paket pertemuan Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Penggandaan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Kegiatan penggandaan Jumlah eksemplar Laporan penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Pembentukan klaster penanggulangan bencana adalah segala bentuk kegiatan untuk membentuk klaster pada lingkup Operasional kewenangan pemerintah provinsi dalam rangka membangun kemandirian pengurangan risiko dan respon penanggulangan bencana dan bersifat sukarela melalui kerja sama antara pemerintah', 'LAMPIRAN II (lanjutan 161)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (487, 'juklak-2-2026', 181, 'lampiran', 'LAMPIRAN II (lanjutan 162)', NULL, 157, 'dengan lembaga masyarakat dan lembaga usaha, termasuk diantaranya, namun tidak terbatas pada:
1) Sosialisasi Pembentukan Klaster 2) Identifikasi dan pemetaan anggota klaster;
3) Penyusunan produk hukum dan pengorganisasian;
4) Pengukuhan dan sosialisasi surat keputusan pembentukan klaster.
Penguatan klaster penanggulangan bencana adalah segala bentuk kegiatan untuk mengembangkan klaster pada lingkup kewenangan pemerintah provinsi dalam rangka membangun kemandirian pengurangan risiko dan respon penanggulangan bencana dan bersifat sukarela melalui kerja sama antara pemerintah dengan lembaga masyarakat dan lembaga usaha, termasuk diantaranya, namun tidak terbatas pada:
1) Sosialisasi SK Klaster Logistik dan Aplikasi Lapor Klaster 2) Identifikasi sumber daya anggota Klaster 3) Penyusunan Rencana Kerja Klaster 4) Penyusunan SOP Klaster 5) Penyusunan Konsep Operasi Klaster Logistik 6) Simulasi/Uji SOP dan Konsep Operasi Klaster.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (487, 'dengan lembaga masyarakat dan lembaga usaha, termasuk diantaranya, namun tidak terbatas pada:
1) Sosialisasi Pembentukan Klaster 2) Identifikasi dan pemetaan anggota klaster;
3) Penyusunan produk hukum dan pengorganisasian;
4) Pengukuhan dan sosialisasi surat keputusan pembentukan klaster.
Penguatan klaster penanggulangan bencana adalah segala bentuk kegiatan untuk mengembangkan klaster pada lingkup kewenangan pemerintah provinsi dalam rangka membangun kemandirian pengurangan risiko dan respon penanggulangan bencana dan bersifat sukarela melalui kerja sama antara pemerintah dengan lembaga masyarakat dan lembaga usaha, termasuk diantaranya, namun tidak terbatas pada:
1) Sosialisasi SK Klaster Logistik dan Aplikasi Lapor Klaster 2) Identifikasi sumber daya anggota Klaster 3) Penyusunan Rencana Kerja Klaster 4) Penyusunan SOP Klaster 5) Penyusunan Konsep Operasi Klaster Logistik 6) Simulasi/Uji SOP dan Konsep Operasi Klaster.', 'LAMPIRAN II (lanjutan 162)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (488, 'juklak-2-2026', 182, 'lampiran', 'LAMPIRAN II (lanjutan 163)', NULL, 165, 'PEMBENTUKAN KLASTER PENANGGULANGAN BENCANA Lokakarya Biaya honorarium Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Pokok Sosialisasi narasumber narasumber sesuai sesuai kebutuhan narasumber x kali lokakarya Pembentukan kebutuhan (maksimal 4 Jumlah jam kerja x Klaster (maksimal 2 (dua) (empat) jam kerja Jumlah kegiatan x orang) total untuk 1 (satu) Harga Satuan kali kegiatan) Biaya honorarium Jumlah Fasilitator/ Jumlah jam kerja Jumlah fasilitator/ Pokok Fasilitator/ Moderator sesuai sesuai kebutuhan moderator x Moderator kebutuhan (maksimal 4 Jumlah jam kerja x (maksimal 2 (dua) (empat) jam kerja Jumlah kegiatan x orang) total untuk 1 (satu) Harga Satuan kali kegiatan) Transport Peserta Jumlah peserta Jumlah lokakarya Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah lokakarya x Harga satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk luar daerah Opsional dinas yang berada di luar 1 (satu) kali Jumlah lokakarya x daerah atau sesuai lokakarya Jumlah hari x kebutuhan (Maksimal 3 hari Harga satuan untuk 1 (satu) kali lokakarya) Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (488, 'PEMBENTUKAN KLASTER PENANGGULANGAN BENCANA Lokakarya Biaya honorarium Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Pokok Sosialisasi narasumber narasumber sesuai sesuai kebutuhan narasumber x kali lokakarya Pembentukan kebutuhan (maksimal 4 Jumlah jam kerja x Klaster (maksimal 2 (dua) (empat) jam kerja Jumlah kegiatan x orang) total untuk 1 (satu) Harga Satuan kali kegiatan) Biaya honorarium Jumlah Fasilitator/ Jumlah jam kerja Jumlah fasilitator/ Pokok Fasilitator/ Moderator sesuai sesuai kebutuhan moderator x Moderator kebutuhan (maksimal 4 Jumlah jam kerja x (maksimal 2 (dua) (empat) jam kerja Jumlah kegiatan x orang) total untuk 1 (satu) Harga Satuan kali kegiatan) Transport Peserta Jumlah peserta Jumlah lokakarya Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah lokakarya x Harga satuan Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk luar daerah Opsional dinas yang berada di luar 1 (satu) kali Jumlah lokakarya x daerah atau sesuai lokakarya Jumlah hari x kebutuhan (Maksimal 3 hari Harga satuan untuk 1 (satu) kali lokakarya) Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya', 'LAMPIRAN II (lanjutan 163)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (489, 'juklak-2-2026', 183, 'lampiran', 'LAMPIRAN II (lanjutan 164)', NULL, 165, 'x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah personil x Maksimal 5 (lima) Pokok Identifikasi tenaga ahli sesuai kebutuhan sesuai kebutuhan Jumlah bulan kerja kali Diskusi Teknis pemetaan (maksimal 2 (dua) (maksimal 8 x Harga Satuan anggota dan orang) (delapan) bulan) Penyusunan Biaya honorarium Jumlah Fasilitator/ Jumlah jam kerja Jumlah fasilitator/ Pokok produk hukum Fasilitator/ Moderator sesuai sesuai kebutuhan moderator x keorganisasian Moderator kebutuhan (maksimal 4 Jumlah jam kerja x (maksimal 2 (dua) (empat) jam kerja Jumlah kegiatan x orang) total untuk 1 (satu) Harga Satuan kali kegiatan) Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah nara- Opsional narasumber sesuai sesuai kebutuhan sumber x Jumlah kebutuhan (maksimal 4 jam kerja x Jumlah (empat) jam kerja Diskusi Teknis x total untuk 1 (satu) Harga Satuan kali Diskusi Teknis) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk luar daerah Opsional dinas yang berada di luar 1 (satu) kali Diskusi Jumlah Diskusi daerah atau sesuai Teknis (maksimal 2 Teknis x Jumlah kebutuhan (dua) hari untuk 1 hari x Harga satuan (satu) kali Diskusi Teknis) Paket');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (489, 'x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah personil x Maksimal 5 (lima) Pokok Identifikasi tenaga ahli sesuai kebutuhan sesuai kebutuhan Jumlah bulan kerja kali Diskusi Teknis pemetaan (maksimal 2 (dua) (maksimal 8 x Harga Satuan anggota dan orang) (delapan) bulan) Penyusunan Biaya honorarium Jumlah Fasilitator/ Jumlah jam kerja Jumlah fasilitator/ Pokok produk hukum Fasilitator/ Moderator sesuai sesuai kebutuhan moderator x keorganisasian Moderator kebutuhan (maksimal 4 Jumlah jam kerja x (maksimal 2 (dua) (empat) jam kerja Jumlah kegiatan x orang) total untuk 1 (satu) Harga Satuan kali kegiatan) Transport Peserta Jumlah peserta Jumlah Diskusi Jumlah peserta x Pokok sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah nara- Opsional narasumber sesuai sesuai kebutuhan sumber x Jumlah kebutuhan (maksimal 4 jam kerja x Jumlah (empat) jam kerja Diskusi Teknis x total untuk 1 (satu) Harga Satuan kali Diskusi Teknis) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk luar daerah Opsional dinas yang berada di luar 1 (satu) kali Diskusi Jumlah Diskusi daerah atau sesuai Teknis (maksimal 2 Teknis x Jumlah kebutuhan (dua) hari untuk 1 hari x Harga satuan (satu) kali Diskusi Teknis) Paket', 'LAMPIRAN II (lanjutan 164)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (490, 'juklak-2-2026', 184, 'lampiran', 'LAMPIRAN II (lanjutan 165)', NULL, 165, 'pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai kebutuhan Teknis sesuai Jumlah Diskusi kebutuhan Teknis x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Pengukuhan Transport Peserta Jumlah peserta Jumlah Lokakarya Jumlah peserta x Pokok Klaster sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah Lokakarya total untuk 1 (satu) x Harga satuan kali Lokakarya) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk luar daerah Opsional dinas yang berada di luar 1 (satu) kali Jumlah Lokakarya daerah atau sesuai Lokakarya x Jumlah hari x kebutuhan (maksimal 4 hari Harga satuan untuk 1 (satu) kali rapat) Paket pertemuan Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan');
