INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (494, 'juklak-2-2026', 188, 'lampiran', 'LAMPIRAN II (lanjutan 169)', NULL, 165, 'total untuk 1 (satu) x Harga satuan kali Lokakarya) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk luar daerah Opsional dinas yang berada di luar 1 (satu) kali Jumlah Lokakarya daerah atau sesuai Lokakarya x Jumlah hari x kebutuhan (maksimal 4 hari Harga satuan untuk 1 (satu) kali rapat) Paket pertemuan Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Penggandaan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Kegiatan penggandaan Jumlah eksemplar Laporan penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Pembentukan klaster penanggulangan bencana adalah segala bentuk kegiatan untuk membentuk klaster pada lingkup Operasional kewenangan pemerintah kabupaten/kota dalam rangka membangun kemandirian pengurangan risiko dan respon penanggulangan bencana dan bersifat sukarela melalui kerjasama antara pemerintah dengan lembaga masyarakat dan lembaga usaha, termasuk diantaranya,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (494, 'total untuk 1 (satu) x Harga satuan kali Lokakarya) Biaya perjalanan Jumlah peserta Jumlah hari untuk Jumlah peserta x untuk luar daerah Opsional dinas yang berada di luar 1 (satu) kali Jumlah Lokakarya daerah atau sesuai Lokakarya x Jumlah hari x kebutuhan (maksimal 4 hari Harga satuan untuk 1 (satu) kali rapat) Paket pertemuan Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah Lokakarya Jumlah peserta x Opsional sesuai kebutuhan sesuai kebutuhan Jumlah Lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah Diskusi Opsional lembar materi yang Teknis sesuai Teknis x Harga dibutuhkan kebutuhan satuan Penggandaan Cetak Laporan Paket dokumen Jumlah eksemplar Jumlah lembar x Maksimal 5 (lima) Opsional Dokumen dan Kegiatan penggandaan Jumlah eksemplar Laporan penggandaan x penggandaan Harga satuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Pembentukan klaster penanggulangan bencana adalah segala bentuk kegiatan untuk membentuk klaster pada lingkup Operasional kewenangan pemerintah kabupaten/kota dalam rangka membangun kemandirian pengurangan risiko dan respon penanggulangan bencana dan bersifat sukarela melalui kerjasama antara pemerintah dengan lembaga masyarakat dan lembaga usaha, termasuk diantaranya,', 'LAMPIRAN II (lanjutan 169)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (495, 'juklak-2-2026', 189, 'lampiran', 'LAMPIRAN II (lanjutan 170)', NULL, 165, 'namun tidak terbatas pada:
1) Sosialisasi Pembentukan Klaster 2) Identifikasi dan pemetaan anggota klaster;
3) Penyusunan produk hukum dan pengorganisasian;
4) Pengukuhan dan sosialisasi surat keputusan pembentukan klaster.
Penguatan klaster penanggulangan bencana adalah segala bentuk kegiatan untuk mengembangkan klaster pada lingkup kewenangan pemerintah kabupaten/kota dalam rangka membangun kemandirian pengurangan risiko dan respon penanggulangan bencana dan bersifat sukarela melalui kerja sama antara pemerintah dengan lembaga masyarakat dan lembaga usaha, termasuk diantaranya, namun tidak terbatas pada:
1) Sosialisasi SK Klaster Logistik dan Aplikasi Lapor Klaster 2) Identifikasi sumber daya anggota Klaster 3) Penyusunan Rencana Kerja Klaster 4) Penyusunan SOP Klaster 5) Penyusunan Konsep Operasi Klaster Logistik 6) Simulasi/Uji SOP dan Konsep Operasi Klaster.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (495, 'namun tidak terbatas pada:
1) Sosialisasi Pembentukan Klaster 2) Identifikasi dan pemetaan anggota klaster;
3) Penyusunan produk hukum dan pengorganisasian;
4) Pengukuhan dan sosialisasi surat keputusan pembentukan klaster.
Penguatan klaster penanggulangan bencana adalah segala bentuk kegiatan untuk mengembangkan klaster pada lingkup kewenangan pemerintah kabupaten/kota dalam rangka membangun kemandirian pengurangan risiko dan respon penanggulangan bencana dan bersifat sukarela melalui kerja sama antara pemerintah dengan lembaga masyarakat dan lembaga usaha, termasuk diantaranya, namun tidak terbatas pada:
1) Sosialisasi SK Klaster Logistik dan Aplikasi Lapor Klaster 2) Identifikasi sumber daya anggota Klaster 3) Penyusunan Rencana Kerja Klaster 4) Penyusunan SOP Klaster 5) Penyusunan Konsep Operasi Klaster Logistik 6) Simulasi/Uji SOP dan Konsep Operasi Klaster.', 'LAMPIRAN II (lanjutan 170)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (496, 'juklak-2-2026', 190, 'lampiran', 'LAMPIRAN II (lanjutan 171)', NULL, 173, 'PEMBENTUKAN KLASTER PENANGGULANGAN BENCANA Lokakarya Biaya honorarium Jumlah Jumlah jam kerja Jumlah Maksimal 1 (satu) Pokok Sosialisasi narasumber narasumber sesuai sesuai kebutuhan narasumber x kali lokakarya Pembentukan kebutuhan (maksimal 4 Jumlah jam kerja x Klaster (maksimal 2 (dua) (empat) jam kerja Jumlah kegiatan x orang) total untuk 1 (satu) Harga Satuan kali kegiatan) Biaya honorarium Jumlah Fasilitator/ Jumlah jam kerja Jumlah fasilitator/ Pokok Fasilitator/ Moderator sesuai sesuai kebutuhan moderator x Moderator kebutuhan (maksimal 4 Jumlah jam kerja x (maksimal 2 (dua) (empat) jam kerja Jumlah kegiatan x orang) total untuk 1 (satu) Harga Satuan kali kegiatan) Transport Peserta Jumlah peserta Jumlah lokakarya Jumlah peserta x Pokok sesuai kebutuhan sesuai kebutuhan Jumlah lokakarya x Harga satuan Paket pertemuan Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Konsumsi rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Snack rapat Jumlah peserta Jumlah lokakarya Jumlah peserta Opsional sesuai kebutuhan sesuai kebutuhan lokakarya x Jumlah lokakarya x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah lokakarya Jumlah lokakarya x Opsional lembar materi yang sesuai kebutuhan Harga satuan dibutuhkan Diskusi Teknis Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah personil x');
