INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (507, 'juklak-2-2026', 201, 'lampiran', 'LAMPIRAN II (lanjutan 182)', NULL, 181, 'bencana bencana denah/peta x Harga satuan Biaya penggandaan Paket denah/peta Jumlah lembar Jumlah paket Maksimal 5 (lima) Pokok denah/peta dan denah/peta denah/peta x eksemplar jalur evakuasi Jumlah lembar penggandaan bencana denah/peta x Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan (termasuk perencanaan, pengumpulan data, pembuatan peta dan rencana arah evakuasi, hingga Operasional sosialisasi kepada unsur pemangku kepentingan terkait) untuk menghasilkan gambar dan rencana arah evakuasi yang lokasi evakuasinya berada kawasan strategis provinsi dan/atau pada wilayah kabupaten/kota bertetangga/ berdekatan yang membutuhkan rencana evakuasi gabungan.');
