INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (508, 'juklak-2-2026', 202, 'lampiran', 'LAMPIRAN II (lanjutan 183)', NULL, 185, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tenaga ahli di Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Total maksimal 14 Opsional bidang tenaga ahli sesuai kebutuhan tiap-tiap tenaga ahli x Jumlah bulan OB kebencanaan (maksimal 2 (dua) kerja x Harga orang) satuan Tenaga ahli Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Total maksimal 14 Opsional bidang tenaga ahli sesuai kebutuhan tiap-tiap tenaga ahli x Jumlah bulan OB pemodelan (maksimal 2 (dua) kerja x Harga bencana orang) satuan Tenaga ahli Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tenaga ahli Total maksimal 14 Opsional bidang GIS tenaga ahli sesuai kebutuhan tiap-tiap tenaga ahli x Jumlah bulan OB (maksimal 2 (dua) kerja x Harga orang) satuan Tenaga penulis Biaya honorarium Jumlah tenaga ahli Jumlah bulan kerja Jumlah tim penulis Total maksimal 8 Opsional tim penulis sesuai kebutuhan tiap-tiap tenaga ahli x Jumlah bulan OB (maksimal 2 (dua) kerja x Harga orang) satuan Tim Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis adalah Opsional Substansi/Tim tim substansi/ tim sesuai kebutuhan atau hari kerja tiap- Jumlah bulan kerja diluar tenaga ahli Teknis Penyusun teknis berdasarkan tiap tim substansi/ atau hari kerja x dan ditetapkan identifikasi entitas tim teknis Harga satuan melalui Surat');
