INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (516, 'juklak-2-2026', 210, 'lampiran', 'LAMPIRAN II (lanjutan 191)', NULL, 190, 'Diskusi teknis) Satuan Paket pertemuan Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Konsumsi rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Snack rapat Jumlah peserta Jumlah Diskusi Jumlah peserta x Opsional sesuai hasil Teknis sesuai Jumlah diskusi identifikasi tim kebutuhan teknis x Harga teknis satuan Perbanyakan materi Sesuai jumlah Jumlah Diskusi Jumlah diskusi Opsional lembar materi yang Teknis sesuai teknis x Harga dibutuhkan kebutuhan satuan Konsultasi Transport Peserta Jumlah peserta Jumlah Konsultasi Jumlah peserta Pokok Publik dan sesuai hasil Publik sesuai konsultasi publik x Sosialisasi identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah konsultasi total untuk 1 (satu) publik x Harga kali Konsultasi Satuan Publik) Paket pertemuan Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Konsumsi rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta x Opsional sesuai hasil Publik sesuai Jumlah konsultasi identifikasi');
