INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (517, 'juklak-2-2026', 211, 'lampiran', 'LAMPIRAN II (lanjutan 192)', NULL, 190, 'tim kebutuhan publik x Harga teknis satuan Snack rapat Jumlah peserta Jumlah Konsultasi Jumlah peserta Opsional sesuai hasil Publik sesuai konsultasi publik x identifikasi tim kebutuhan Jumlah konsultasi teknis publik x Harga satuan Perbanyakan materi Sesuai jumlah Jumlah Konsultasi Jumlah konsultasi Opsional lembar materi yang Publik sesuai publik x Harga dibutuhkan kebutuhan satuan Pencetakan Biaya pembuatan Paket denah/peta Jumlah lembar Jumlah paket Pokok denah/peta dan denah/peta dan denah/peta denah/peta x jalur evakuasi jalur evakuasi Jumlah lembar bencana bencana denah/peta x Harga satuan Biaya penggandaan Paket denah/peta Jumlah lembar Jumlah paket Maksimal 5 (lima) Pokok denah/peta dan denah/peta denah/peta x eksemplar jalur evakuasi Jumlah lembar penggandaan bencana denah/peta x Harga satuan PEMOHON: KELOMPOK MASYARAKAT Definisi Segala bentuk kegiatan (termasuk perencanaan, pengumpulan data, pembuatan denah dan rencana arah evakuasi, hingga Operasional sosialisasi kepada unsur pemangku kepentingan terkait) untuk menghasilkan gambar dan rencana arah evakuasi yang lokasi evakuasinya berada di dalam satu wilayah administrasi kabupaten/kota.');
