INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (518, 'juklak-2-2026', 212, 'lampiran', 'LAMPIRAN II (lanjutan 193)', NULL, 193, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 4 (empat) Pokok Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tim Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis dapat Pokok Substansi/Tim tim substansi/tim sesuai kebutuhan. tiap-tiap tim Jumlah bulan kerja terdiri dari anggota Teknis Penyusun teknis substansi/tim x Harga satuan masyarakat teknis setempat dan aparat terkait Konsultasi dan Transport Peserta Jumlah peserta Jumlah pertemuan Jumlah peserta x Pokok Sosialisasi sesuai hasil sesuai kebutuhan Jumlah pertemuan tingkat identifikasi tim x Harga satuan komunitas teknis Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah pertemuan total untuk 1 (satu) x Harga Satuan kali pertemuan) Konsumsi rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai hasil sesuai kebutuhan Jumlah pertemuan identifikasi tim x Harga satuan teknis Snack rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai hasil sesuai kebutuhan Jumlah pertemuan identifikasi tim x Harga satuan teknis Perbanyakan materi Sesuai jumlah Jumlah pertemuan Jumlah pertemuan Opsional lembar materi yang sesuai kebutuhan x Harga satuan dibutuhkan Pencetakan Biaya pembuatan Paket denah/peta Jumlah lembar Jumlah paket Pokok denah/peta dan denah/peta dan denah/peta');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (518, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 4 (empat) Pokok Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tim Biaya honorarium Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Tim Teknis dapat Pokok Substansi/Tim tim substansi/tim sesuai kebutuhan. tiap-tiap tim Jumlah bulan kerja terdiri dari anggota Teknis Penyusun teknis substansi/tim x Harga satuan masyarakat teknis setempat dan aparat terkait Konsultasi dan Transport Peserta Jumlah peserta Jumlah pertemuan Jumlah peserta x Pokok Sosialisasi sesuai hasil sesuai kebutuhan Jumlah pertemuan tingkat identifikasi tim x Harga satuan komunitas teknis Honor Narasumber Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional narasumber sesuai sesuai kebutuhan narasumber x kali kebutuhan (maksimal 4 Jumlah jam kerja x (empat) jam kerja Jumlah pertemuan total untuk 1 (satu) x Harga Satuan kali pertemuan) Konsumsi rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai hasil sesuai kebutuhan Jumlah pertemuan identifikasi tim x Harga satuan teknis Snack rapat Jumlah peserta Jumlah pertemuan Jumlah peserta x Opsional sesuai hasil sesuai kebutuhan Jumlah pertemuan identifikasi tim x Harga satuan teknis Perbanyakan materi Sesuai jumlah Jumlah pertemuan Jumlah pertemuan Opsional lembar materi yang sesuai kebutuhan x Harga satuan dibutuhkan Pencetakan Biaya pembuatan Paket denah/peta Jumlah lembar Jumlah paket Pokok denah/peta dan denah/peta dan denah/peta', 'LAMPIRAN II (lanjutan 193)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (519, 'juklak-2-2026', 213, 'lampiran', 'LAMPIRAN II (lanjutan 194)', NULL, 193, 'denah/peta x jalur evakuasi jalur evakuasi Jumlah lembar bencana bencana denah/peta x Harga satuan Biaya penggandaan Paket denah/peta Jumlah lembar Jumlah paket Maksimal 5 (lima) Pokok denah/peta dan denah/peta denah/peta x eksemplar jalur evakuasi Jumlah lembar penggandaan bencana denah/peta x Harga satuan Fasilitator Honorarium Maksimal 2 (dua) Jumlah bulan Jumlah fasilitator x Penetapan jumlah Pokok fasilitator lapangan orang per kawasan/ pekerjaan jumlah bulan kerja fasilitator lapangan kecamatan/desa/ x Harga satuan tidak boleh lebih kelurahan untuk 6 (enam) bulan kerja KEGIATAN : PENYEDIAAN DAN PEMASANGAN RAMBU EVAKUASI DAN PAPAN INFORMASI PUBLIK SUB KATEGORI : KESIAPSIAGAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan dalam rangka memproduksi dan memasang rambu evakuasi dan papan informasi publik pada Operasional kawasan strategis nasional sesuai dengan standar kualitas dan spesifikasi yang ditetapkan.
Rambu evakuasi adalah tanda yang digunakan untuk menginformasikan secara jelas tentang arah menuju tempat aman.
Rambu evakuasi difokuskan untuk bencana yang menjadi prioritas, yang setidaknya mencakup tanda arah evakuasi, tanda lokasi aman, dan tanda titik pengungsian. Penempatan rambu evakuasi dilakukan sesuai kebutuhan berdasarkan rencana peta jalur evakuasi.
Papan informasi publik adalah tanda pemberitahuan informasi kebencanaan yang ditempatkan pada lokasi/kawasan strategis sesuai jenis bencananya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (519, 'denah/peta x jalur evakuasi jalur evakuasi Jumlah lembar bencana bencana denah/peta x Harga satuan Biaya penggandaan Paket denah/peta Jumlah lembar Jumlah paket Maksimal 5 (lima) Pokok denah/peta dan denah/peta denah/peta x eksemplar jalur evakuasi Jumlah lembar penggandaan bencana denah/peta x Harga satuan Fasilitator Honorarium Maksimal 2 (dua) Jumlah bulan Jumlah fasilitator x Penetapan jumlah Pokok fasilitator lapangan orang per kawasan/ pekerjaan jumlah bulan kerja fasilitator lapangan kecamatan/desa/ x Harga satuan tidak boleh lebih kelurahan untuk 6 (enam) bulan kerja KEGIATAN : PENYEDIAAN DAN PEMASANGAN RAMBU EVAKUASI DAN PAPAN INFORMASI PUBLIK SUB KATEGORI : KESIAPSIAGAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan dalam rangka memproduksi dan memasang rambu evakuasi dan papan informasi publik pada Operasional kawasan strategis nasional sesuai dengan standar kualitas dan spesifikasi yang ditetapkan.
