INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (527, 'juklak-2-2026', 221, 'lampiran', 'LAMPIRAN II (lanjutan 202)', NULL, 200, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan Survei dan Biaya perizinan Jumlah titik Sesuai kebutuhan Jumlah titik Pokok Perizinan Lokasi lokasi penempatan penempatan sesuai penempatan x rambu evakuasi kebutuhan Harga satuan dan papan berdasarkan informasi publik kawasan berisiko tinggi Biaya survei lokasi Jumlah titik Sesuai kebutuhan Jumlah titik Diutamakan untuk Opsional penempatan rambu penempatan sesuai penempatan x jenis bencana evakuasi kebutuhan Harga satuan prioritas berdasarkan kawasan berisiko tinggi Biaya survei lokasi Jumlah titik Sesuai kebutuhan Jumlah titik Opsional penempatan papan penempatan sesuai penempatan x informasi publik kebutuhan Harga satuan berdasarkan kawasan berisiko tinggi Pengadaan dan Biaya pengadaan Jumlah rambu dan Sesuai kebutuhan (Jumlah rambu x Pokok pemasangan rambu evakuasi papan informasi Harga satuan) + Rambu Evakuasi dan papan publik sesuai (Jumlah papan dan Papan informasi publik kebutuhan informasi publik x Informasi Publik berdasarkan jumlah Harga satuan) titik penempatan Transportasi Jumlah titik Jumlah personil Jumlah titik x Pokok pemasangan penempatan sesuai untuk tiap-tiap titik Jumlah personil x kebutuhan pemasangan Harga satuan berdasarkan kawasan berisiko tinggi Material Jumlah titik Sesuai kebutuhan Jumlah titik Pokok pemasangan rambu penempatan sesuai pemasangan x dan papan kebutuhan Harga satuan informasi publik berdasarkan kawasan berisiko');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (527, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan Survei dan Biaya perizinan Jumlah titik Sesuai kebutuhan Jumlah titik Pokok Perizinan Lokasi lokasi penempatan penempatan sesuai penempatan x rambu evakuasi kebutuhan Harga satuan dan papan berdasarkan informasi publik kawasan berisiko tinggi Biaya survei lokasi Jumlah titik Sesuai kebutuhan Jumlah titik Diutamakan untuk Opsional penempatan rambu penempatan sesuai penempatan x jenis bencana evakuasi kebutuhan Harga satuan prioritas berdasarkan kawasan berisiko tinggi Biaya survei lokasi Jumlah titik Sesuai kebutuhan Jumlah titik Opsional penempatan papan penempatan sesuai penempatan x informasi publik kebutuhan Harga satuan berdasarkan kawasan berisiko tinggi Pengadaan dan Biaya pengadaan Jumlah rambu dan Sesuai kebutuhan (Jumlah rambu x Pokok pemasangan rambu evakuasi papan informasi Harga satuan) + Rambu Evakuasi dan papan publik sesuai (Jumlah papan dan Papan informasi publik kebutuhan informasi publik x Informasi Publik berdasarkan jumlah Harga satuan) titik penempatan Transportasi Jumlah titik Jumlah personil Jumlah titik x Pokok pemasangan penempatan sesuai untuk tiap-tiap titik Jumlah personil x kebutuhan pemasangan Harga satuan berdasarkan kawasan berisiko tinggi Material Jumlah titik Sesuai kebutuhan Jumlah titik Pokok pemasangan rambu penempatan sesuai pemasangan x dan papan kebutuhan Harga satuan informasi publik berdasarkan kawasan berisiko', 'LAMPIRAN II (lanjutan 202)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (528, 'juklak-2-2026', 222, 'lampiran', 'LAMPIRAN II (lanjutan 203)', NULL, 200, 'tinggi Akomodasi Jumlah titik Jumlah personil Jumlah titik x Opsional penempatan sesuai untuk tiap-tiap titik Jumlah personil x kebutuhan pemasangan Harga satuan berdasarkan kawasan berisiko tinggi PEMOHON: KELOMPOK MASYARAKAT Definisi Segala bentuk kegiatan dalam rangka memproduksi dan memasang rambu evakuasi dan papan informasi publik dengan Operasional inisiasi dari kelompok masyarakat pada kawasan yang pengelolaannya berada pada kewenangan pemerintah kabupaten/kota sesuai dengan standar kualitas dan spesifikasi yang ditetapkan.
Rambu evakuasi adalah tanda yang digunakan untuk menginformasikan secara jelas tentang arah menuju tempat aman.
Rambu evakuasi difokuskan untuk bencana yang menjadi prioritas, yang setidaknya mencakup tanda arah evakuasi, tanda lokasi aman, dan tanda titik pengungsian. Penempatan rambu evakuasi dilakukan sesuai kebutuhan berdasarkan rencana peta jalur evakuasi.
Papan informasi publik adalah tanda pemberitahuan informasi kebencanaan yang ditempatkan pada lokasi/kawasan strategis sesuai jenis bencananya. Papan informasi publik setidaknya memberikan informasi terkait ancaman bencana yang ada di lokasi, tanda-tanda kejadian bencana, peta evakuasi kawasan, larangan atau ajakan untuk mencegah bencana, langkah-langkah kesiapsiagaan, dan nomor kontak darurat.
Prasyarat permohonan: memiliki denah/ peta jalur evakuasi untuk bencana terkait.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (528, 'tinggi Akomodasi Jumlah titik Jumlah personil Jumlah titik x Opsional penempatan sesuai untuk tiap-tiap titik Jumlah personil x kebutuhan pemasangan Harga satuan berdasarkan kawasan berisiko tinggi PEMOHON: KELOMPOK MASYARAKAT Definisi Segala bentuk kegiatan dalam rangka memproduksi dan memasang rambu evakuasi dan papan informasi publik dengan Operasional inisiasi dari kelompok masyarakat pada kawasan yang pengelolaannya berada pada kewenangan pemerintah kabupaten/kota sesuai dengan standar kualitas dan spesifikasi yang ditetapkan.
Rambu evakuasi adalah tanda yang digunakan untuk menginformasikan secara jelas tentang arah menuju tempat aman.
Rambu evakuasi difokuskan untuk bencana yang menjadi prioritas, yang setidaknya mencakup tanda arah evakuasi, tanda lokasi aman, dan tanda titik pengungsian. Penempatan rambu evakuasi dilakukan sesuai kebutuhan berdasarkan rencana peta jalur evakuasi.
Papan informasi publik adalah tanda pemberitahuan informasi kebencanaan yang ditempatkan pada lokasi/kawasan strategis sesuai jenis bencananya. Papan informasi publik setidaknya memberikan informasi terkait ancaman bencana yang ada di lokasi, tanda-tanda kejadian bencana, peta evakuasi kawasan, larangan atau ajakan untuk mencegah bencana, langkah-langkah kesiapsiagaan, dan nomor kontak darurat.
Prasyarat permohonan: memiliki denah/ peta jalur evakuasi untuk bencana terkait.', 'LAMPIRAN II (lanjutan 203)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (529, 'juklak-2-2026', 223, 'lampiran', 'LAMPIRAN II (lanjutan 204)', NULL, 202, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tim Teknis Biaya honorarium tim Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Bertugas untuk Opsional teknis sesuai kebutuhan tiap-tiap tim tim Jumlah bulan kerja merencanakan teknis x Harga satuan penempatan serta mengelola penyediaan dan pemasangan rambu evakuasi dan papan informasi publik; maksimal 5 (lima) orang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (529, 'Ketua Tim Biaya honorarium 1 (satu) orang Jumlah bulan kerja 1 (satu) orang x Maksimal 7 (tujuh) Opsional Ketua Tim Ketua Tim Jumlah bulan kerja bulan x Harga satuan Tim Teknis Biaya honorarium tim Jumlah tim teknis Jumlah bulan kerja Jumlah personil x Bertugas untuk Opsional teknis sesuai kebutuhan tiap-tiap tim tim Jumlah bulan kerja merencanakan teknis x Harga satuan penempatan serta mengelola penyediaan dan pemasangan rambu evakuasi dan papan informasi publik; maksimal 5 (lima) orang.', 'LAMPIRAN II (lanjutan 204)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (530, 'juklak-2-2026', 224, 'lampiran', 'LAMPIRAN II (lanjutan 205)', NULL, 203, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan Survei Lokasi Biaya survei lokasi Jumlah titik Sesuai kebutuhan Jumlah titik Diutamakan untuk Opsional penempatan rambu penempatan sesuai penempatan x jenis bencana evakuasi kebutuhan Harga satuan prioritas berdasarkan kawasan berisiko tinggi Biaya survei lokasi Jumlah titik Sesuai kebutuhan Jumlah titik Opsional penempatan papan penempatan sesuai penempatan x informasi publik kebutuhan Harga satuan berdasarkan kawasan berisiko tinggi Pengadaan Biaya pengadaan Jumlah rambu dan Sesuai kebutuhan (Jumlah rambu x Pokok dan rambu evakuasi dan papan informasi Harga satuan) + pemasangan papan informasi publik sesuai (Jumlah papan Rambu publik kebutuhan informasi publik x Evakuasi dan berdasarkan jumlah Harga satuan) Papan titik penempatan Informasi Transportasi Jumlah titik Jumlah personil Jumlah titik x Pokok Publik pemasangan penempatan sesuai untuk tiap-tiap titik Jumlah personil x kebutuhan pemasangan Harga satuan berdasarkan kawasan berisiko tinggi Material untuk Jumlah titik Sesuai kebutuhan Jumlah titik Pokok pemasangan rambu penempatan sesuai pemasangan x dan papan informasi kebutuhan Harga satuan publik berdasarkan kawasan berisiko tinggi Akomodasi Jumlah titik Jumlah personil Jumlah titik x Opsional penempatan sesuai untuk tiap-tiap titik Jumlah personil x kebutuhan pemasangan Harga satuan berdasarkan kawasan berisiko tinggi Fasilitator Honorarium');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (530, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan Survei Lokasi Biaya survei lokasi Jumlah titik Sesuai kebutuhan Jumlah titik Diutamakan untuk Opsional penempatan rambu penempatan sesuai penempatan x jenis bencana evakuasi kebutuhan Harga satuan prioritas berdasarkan kawasan berisiko tinggi Biaya survei lokasi Jumlah titik Sesuai kebutuhan Jumlah titik Opsional penempatan papan penempatan sesuai penempatan x informasi publik kebutuhan Harga satuan berdasarkan kawasan berisiko tinggi Pengadaan Biaya pengadaan Jumlah rambu dan Sesuai kebutuhan (Jumlah rambu x Pokok dan rambu evakuasi dan papan informasi Harga satuan) + pemasangan papan informasi publik sesuai (Jumlah papan Rambu publik kebutuhan informasi publik x Evakuasi dan berdasarkan jumlah Harga satuan) Papan titik penempatan Informasi Transportasi Jumlah titik Jumlah personil Jumlah titik x Pokok Publik pemasangan penempatan sesuai untuk tiap-tiap titik Jumlah personil x kebutuhan pemasangan Harga satuan berdasarkan kawasan berisiko tinggi Material untuk Jumlah titik Sesuai kebutuhan Jumlah titik Pokok pemasangan rambu penempatan sesuai pemasangan x dan papan informasi kebutuhan Harga satuan publik berdasarkan kawasan berisiko tinggi Akomodasi Jumlah titik Jumlah personil Jumlah titik x Opsional penempatan sesuai untuk tiap-tiap titik Jumlah personil x kebutuhan pemasangan Harga satuan berdasarkan kawasan berisiko tinggi Fasilitator Honorarium', 'LAMPIRAN II (lanjutan 205)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (531, 'juklak-2-2026', 225, 'lampiran', 'LAMPIRAN II (lanjutan 206)', NULL, 203, 'fasilitator 1 (satu) orang per Jumlah bulan Jumlah fasilitator x Penetapan jumlah Pokok lapangan kawasan/ pekerjaan jumlah bulan kerja fasilitator lapangan kecamatan/ desa/ x Harga satuan tidak boleh lebih kelurahan dari 2 (dua) orang untuk 4 (empat) bulan kerja KEGIATAN : PENYEDIAAN SARANA PRASARANA KESIAPSIAGAAN TERHADAP BENCANA SUB KATEGORI : KESIAPSIAGAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk penyediaan sarana prasarana pada fase sebelum terjadi bencana untuk mendukung pelaksanaan Operasional kesiapsiagaan (antara lain seperti penyediaan gudang logistik, kelengkapan operasional gudang, penyediaan tangki pemanen air hujan, dan sebagainya) diutamakan untuk jenis bencana prioritas dengan risiko tinggi dan berpotensi akan terjadi pada tahun berjalan atau waktu dekat. Dalam hal ini termasuk segala bentuk upaya untuk mengadakan sarana prasarana kesiapsiagaan bagi kebutuhan dasar perempuan, anak, dan disabilitas jika terjadi bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (531, 'fasilitator 1 (satu) orang per Jumlah bulan Jumlah fasilitator x Penetapan jumlah Pokok lapangan kawasan/ pekerjaan jumlah bulan kerja fasilitator lapangan kecamatan/ desa/ x Harga satuan tidak boleh lebih kelurahan dari 2 (dua) orang untuk 4 (empat) bulan kerja KEGIATAN : PENYEDIAAN SARANA PRASARANA KESIAPSIAGAAN TERHADAP BENCANA SUB KATEGORI : KESIAPSIAGAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk penyediaan sarana prasarana pada fase sebelum terjadi bencana untuk mendukung pelaksanaan Operasional kesiapsiagaan (antara lain seperti penyediaan gudang logistik, kelengkapan operasional gudang, penyediaan tangki pemanen air hujan, dan sebagainya) diutamakan untuk jenis bencana prioritas dengan risiko tinggi dan berpotensi akan terjadi pada tahun berjalan atau waktu dekat. Dalam hal ini termasuk segala bentuk upaya untuk mengadakan sarana prasarana kesiapsiagaan bagi kebutuhan dasar perempuan, anak, dan disabilitas jika terjadi bencana.', 'LAMPIRAN II (lanjutan 206)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (532, 'juklak-2-2026', 226, 'lampiran', 'LAMPIRAN II (lanjutan 207)', NULL, 205, 'Prasyarat permohonan: memiliki Rencana Kesiapsiagaan Logistik dan Peralatan Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pengadaan Penyediaan Paket sarana Jumlah paket Sesuai kebutuhan Jumlah paket x Dapat didetailkan Pokok sarana prasarana sesuai dengan Harga satuan sesuai dengan prasarana kesiapsiagaan prioritas utama Standar Biaya yang kesiapsiagaan bencana dalam dokumen berlaku di terhadap Rencana kementerian/lemba bencana Kesiapsiagaan ga Logistik dan Peralatan) PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk penyediaan sarana prasarana pada fase sebelum terjadi bencana untuk mendukung pelaksanaan Operasional kesiapsiagaan (antara lain seperti penyediaan gudang logistik, kelengkapan operasional gudang, penyediaan tangki pemanen air hujan, dan sebagainya) diutamakan untuk jenis bencana prioritas dengan risiko tinggi dan berpotensi akan terjadi pada tahun berjalan atau waktu dekat. Dalam hal ini termasuk segala bentuk upaya untuk mengadakan sarana prasarana kesiapsiagaan bagi kebutuhan dasar perempuan, anak, dan disabilitas jika terjadi bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (532, 'Prasyarat permohonan: memiliki Rencana Kesiapsiagaan Logistik dan Peralatan Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pengadaan Penyediaan Paket sarana Jumlah paket Sesuai kebutuhan Jumlah paket x Dapat didetailkan Pokok sarana prasarana sesuai dengan Harga satuan sesuai dengan prasarana kesiapsiagaan prioritas utama Standar Biaya yang kesiapsiagaan bencana dalam dokumen berlaku di terhadap Rencana kementerian/lemba bencana Kesiapsiagaan ga Logistik dan Peralatan) PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk penyediaan sarana prasarana pada fase sebelum terjadi bencana untuk mendukung pelaksanaan Operasional kesiapsiagaan (antara lain seperti penyediaan gudang logistik, kelengkapan operasional gudang, penyediaan tangki pemanen air hujan, dan sebagainya) diutamakan untuk jenis bencana prioritas dengan risiko tinggi dan berpotensi akan terjadi pada tahun berjalan atau waktu dekat. Dalam hal ini termasuk segala bentuk upaya untuk mengadakan sarana prasarana kesiapsiagaan bagi kebutuhan dasar perempuan, anak, dan disabilitas jika terjadi bencana.', 'LAMPIRAN II (lanjutan 207)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (533, 'juklak-2-2026', 227, 'lampiran', 'LAMPIRAN II (lanjutan 208)', NULL, 205, 'Prasyarat permohonan: memiliki Rencana Kesiapsiagaan Logistik dan Peralatan Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pengadaan Penyediaan Paket sarana Jumlah paket Sesuai kebutuhan Jumlah paket x Dapat didetailkan Pokok sarana prasarana sesuai dengan Harga satuan sesuai dengan prasarana kesiapsiagaan prioritas utama Standar Biaya yang kesiapsiagaan bencana dalam dokumen berlaku di daerah terhadap Rencana bencana Kesiapsiagaan Logistik dan Peralatan) PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk penyediaan sarana prasarana pada fase sebelum terjadi bencana untuk mendukung pelaksanaan Operasional kesiapsiagaan (antara lain seperti penyediaan gudang logistik, kelengkapan operasional gudang, penyediaan tangki pemanen air hujan, dan sebagainya) diutamakan untuk jenis bencana prioritas dengan risiko tinggi dan berpotensi akan terjadi pada tahun berjalan atau waktu dekat. Dalam hal ini termasuk segala bentuk upaya untuk mengadakan sarana prasarana kesiapsiagaan bagi kebutuhan dasar perempuan, anak, dan disabilitas jika terjadi bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (533, 'Prasyarat permohonan: memiliki Rencana Kesiapsiagaan Logistik dan Peralatan Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pengadaan Penyediaan Paket sarana Jumlah paket Sesuai kebutuhan Jumlah paket x Dapat didetailkan Pokok sarana prasarana sesuai dengan Harga satuan sesuai dengan prasarana kesiapsiagaan prioritas utama Standar Biaya yang kesiapsiagaan bencana dalam dokumen berlaku di daerah terhadap Rencana bencana Kesiapsiagaan Logistik dan Peralatan) PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk penyediaan sarana prasarana pada fase sebelum terjadi bencana untuk mendukung pelaksanaan Operasional kesiapsiagaan (antara lain seperti penyediaan gudang logistik, kelengkapan operasional gudang, penyediaan tangki pemanen air hujan, dan sebagainya) diutamakan untuk jenis bencana prioritas dengan risiko tinggi dan berpotensi akan terjadi pada tahun berjalan atau waktu dekat. Dalam hal ini termasuk segala bentuk upaya untuk mengadakan sarana prasarana kesiapsiagaan bagi kebutuhan dasar perempuan, anak, dan disabilitas jika terjadi bencana.', 'LAMPIRAN II (lanjutan 208)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (534, 'juklak-2-2026', 228, 'lampiran', 'LAMPIRAN II (lanjutan 209)', NULL, 206, 'Prasyarat permohonan: memiliki Rencana Kesiapsiagaan Logistik dan Peralatan Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pengadaan Penyediaan Paket sarana Jumlah paket Sesuai kebutuhan Jumlah paket x Dapat didetailkan Pokok sarana prasarana sesuai dengan Harga satuan sesuai dengan prasarana kesiapsiagaan prioritas utama Standar Biaya yang kesiapsiagaan bencana dalam dokumen berlaku di daerah terhadap Rencana bencana Kesiapsiagaan Logistik dan Peralatan) KEGIATAN : PENYEDIAAN PERALATAN PERLINDUNGAN DAN KESIAPSIAGAAN TERHADAP BENCANA SUB KATEGORI : KESIAPSIAGAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Kegiatan pemenuhan kebutuhan peralatan keselamatan diri bagi individu, keluarga di kawasan rawan bencana, maupun Operasional petugas operasi kedaruratan bencana dalam melaksanakan tugas penyelamatan dan pengamanan yang dipersiapkan pada fase prabencana.
Penyediaan peralatan perlindungan dan kesiapsiagaan terhadap bencana, antara lain:
1) peralatan keselamatan diri petugas, antara lain dengan fungsi: (a) pelindung kepala, (b) pelindung mata dan muka, (c) pelindung telinga, (d) pelindung pernapasan beserta perlengkapannya, (e) pelindung tangan, (f) pelindung kaki, (g) pakaian pelindung, (maksimal) alat pelindung jatuh perorangan, dan (i) pelampung.
2) peralatan keselamatan keluarga, antara lain: (a) cadangan energi, (b) cadangan makanan, (c) radio transistor, (d) pakaian ganti, (e) obat sederhana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (534, 'Prasyarat permohonan: memiliki Rencana Kesiapsiagaan Logistik dan Peralatan Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pengadaan Penyediaan Paket sarana Jumlah paket Sesuai kebutuhan Jumlah paket x Dapat didetailkan Pokok sarana prasarana sesuai dengan Harga satuan sesuai dengan prasarana kesiapsiagaan prioritas utama Standar Biaya yang kesiapsiagaan bencana dalam dokumen berlaku di daerah terhadap Rencana bencana Kesiapsiagaan Logistik dan Peralatan) KEGIATAN : PENYEDIAAN PERALATAN PERLINDUNGAN DAN KESIAPSIAGAAN TERHADAP BENCANA SUB KATEGORI : KESIAPSIAGAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Kegiatan pemenuhan kebutuhan peralatan keselamatan diri bagi individu, keluarga di kawasan rawan bencana, maupun Operasional petugas operasi kedaruratan bencana dalam melaksanakan tugas penyelamatan dan pengamanan yang dipersiapkan pada fase prabencana.
Penyediaan peralatan perlindungan dan kesiapsiagaan terhadap bencana, antara lain:
1) peralatan keselamatan diri petugas, antara lain dengan fungsi: (a) pelindung kepala, (b) pelindung mata dan muka, (c) pelindung telinga, (d) pelindung pernapasan beserta perlengkapannya, (e) pelindung tangan, (f) pelindung kaki, (g) pakaian pelindung, (maksimal) alat pelindung jatuh perorangan, dan (i) pelampung.
2) peralatan keselamatan keluarga, antara lain: (a) cadangan energi, (b) cadangan makanan, (c) radio transistor, (d) pakaian ganti, (e) obat sederhana.', 'LAMPIRAN II (lanjutan 209)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (535, 'juklak-2-2026', 229, 'lampiran', 'LAMPIRAN II (lanjutan 210)', NULL, 208, '3) peralatan keselamatan individu/pribadi, antara lain: (a) peluit, (b) moda lain untuk pemanggil tim pencari saat terperangkap, (c) masker.
4) peralatan penyelamatan korban bencana, adalah peralatan dan sarana prasasarana yang dipersiapkan untuk operasi penyelamatan dan evakuasi korban bencana.
Prasyarat permohonan: memiliki Rencana Kesiapsiagaan Logistik dan Peralatan Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pengadaan Penyediaan Paket peralatan Jumlah peralatan Jumlah paket Jumlah peralatan x 1. Maksimal sesuai Pokok peralatan keselamatan sesuai kebutuhan sesuai jumlah Jumlah paket x jumlah rata-rata petugas/ paket petugas/ Harga satuan petugas aktif peralatan jumlah keluarga pada keselamatan penerima penanganan keluarga/paket peralatan/ jumlah darurat bencana peralatan warga negara terakhir di keselamatan penerima tingkat nasional. individu atau peralatan/ jumlah 2. Maksimal sesuai pribadi/paket kebutuhan jumlah keluarga peralatan penyelamatan yang berada di penyelamatan korban bencana daerah rawan korban bencana untuk jenis bencana yang diperkirakan akan terjadi pada tahun berjalan dan/atau waktu dekat.
3. Maksimal sesuai jumlah individu yang berada di daerah rawan untuk jenis bencana yang diperkirakan akan terjadi pada tahun berjalan dan/atau waktu dekat.');
