INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (540, 'juklak-2-2026', 234, 'lampiran', 'LAMPIRAN II (lanjutan 215)', NULL, 213, '4. Maksimal sesuai kebutuhan pada rencana kontingensi dan/atau standar minimal yang ditetapkan KEGIATAN : PEMBANGUNAN/PENGUATAN TEMPAT EVAKUASI SUB KATEGORI : KESIAPSIAGAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan penyiapan tempat aman yang lokasinya berada di kawasan strategis nasional yang menjadi Operasional kewenangan pemerintah pusat (termasuk penyediaan lokasi, pembangunan infrastruktur, penyediaan perlengkapan dan fasilitas pendukung, serta penyediaan cadangan logistik dasar) dimana penduduk terpapar dapat menyelamatkan diri untuk sementara pada saat terjadi bencana.
Prasyarat permohonan: memiliki denah/peta jalur evakuasi untuk bencana terkait.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (540, '4. Maksimal sesuai kebutuhan pada rencana kontingensi dan/atau standar minimal yang ditetapkan KEGIATAN : PEMBANGUNAN/PENGUATAN TEMPAT EVAKUASI SUB KATEGORI : KESIAPSIAGAAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan penyiapan tempat aman yang lokasinya berada di kawasan strategis nasional yang menjadi Operasional kewenangan pemerintah pusat (termasuk penyediaan lokasi, pembangunan infrastruktur, penyediaan perlengkapan dan fasilitas pendukung, serta penyediaan cadangan logistik dasar) dimana penduduk terpapar dapat menyelamatkan diri untuk sementara pada saat terjadi bencana.
Prasyarat permohonan: memiliki denah/peta jalur evakuasi untuk bencana terkait.', 'LAMPIRAN II (lanjutan 215)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (541, 'juklak-2-2026', 235, 'lampiran', 'LAMPIRAN II (lanjutan 216)', NULL, 214, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan/ Penyediaan dan 1 (satu) lokasi 1 (satu) paket Jumlah lokasi x Dapat didetailkan Pokok penguatan pembersihan lokasi Harga satuan sesuai dengan tempat evakuasi Pembangunan 1 (satu) lokasi 1 (satu) paket Jumlah lokasi x Standar Biaya yang Pokok sementara infrastruktur Harga satuan berlaku di Penyediaan 1 (satu) lokasi 1 (satu) paket Jumlah lokasi x kementerian/lemba Opsional perlengkapan dan Harga satuan ga. fasilitas pendukung Penyediaan 1 (satu) lokasi Sesuai daya Jumlah lokasi x Opsional cadangan logistik tampung tempat Harga satuan dasar evakuasi PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan persiapan titik aman yang lokasinya berada di kawasan strategis provinsi yang menjadi kewenangan Operasional pemerintah provinsi (termasuk penyediaan lokasi, pembangunan infrastruktur, penyediaan perlengkapan dan fasilitas pendukung, serta penyediaan cadangan logistik dasar) dimana penduduk terpapar dapat menyelamatkan diri untuk sementara pada saat bencana terjadi.
