INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (555, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pengadaan Honorarium Jumlah Jumlah jam kerja Jumlah jam kerja x Opsional narasumber narasumber sesuai atau hari kegiatan Harga satuan kebutuhan Peralatan Biaya pengadaan Jumlah peralatan Sesuai kebutuhan Jumlah peralatan x Dapat didetailkan Pokok teknologi peralatan sesuai kebutuhan Harga satuan sesuai dengan informasi dan berdasarkan jenis Standar Biaya yang komunikasi bencana dan berlaku di daerah untuk layanan karakteristik pesan singkat kawasan. secara broadcast Biaya pemeliharaan Jumlah peralatan Jumlah paket Jumlah peralatan x Pokok dan perawatan yang membutuhkan kegiatan Paket kegiatan x peralatan pemeliharaan dan Harga satuan pemeliharaan dan perawatan sesuai perawatan kebutuhan agar peralatan dapat beroperasi sepanjang tahun Fasilitator Honorarium Maksimal 2 (dua) Jumlah bulan Jumlah fasilitator x Penetapan jumlah Pokok fasilitator lapangan orang per kawasan/ pekerjaan jumlah bulan kerja fasilitator lapangan kecamatan/desa/ x Harga satuan tidak boleh lebih kelurahan dari 4 orang untuk 6 (enam) bulan kerja KEGIATAN : PENGUATAN RESPON MASYARAKAT TERHADAP PERINGATAN DINI BENCANA SUB KATEGORI : PERINGATAN DINI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan peningkatan kapasitas masyarakat dalam merespon peringatan dini bencana melalui pelibatan aktif Operasional masyarakat serta mengintegrasikan komponen struktural dan kultural dengan', 'LAMPIRAN II (lanjutan 230)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (556, 'juklak-2-2026', 250, 'lampiran', 'LAMPIRAN II (lanjutan 231)', NULL, 224, 'pendekatan Sistem Peringatan Dini Bencana Berbasis Masyarakat (SPDBBM) yang bertujuan untuk meningkatkan respon dan kapasitas masyarakat dalam menghadapi ancaman bencana agar dapat memastikan masyarakat siap bertindak secara tepat waktu dan efektif, sehingga dapat mengurangi risiko kerugian fisik dan korban jiwa saat bencana terjadi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (556, 'pendekatan Sistem Peringatan Dini Bencana Berbasis Masyarakat (SPDBBM) yang bertujuan untuk meningkatkan respon dan kapasitas masyarakat dalam menghadapi ancaman bencana agar dapat memastikan masyarakat siap bertindak secara tepat waktu dan efektif, sehingga dapat mengurangi risiko kerugian fisik dan korban jiwa saat bencana terjadi.', 'LAMPIRAN II (lanjutan 231)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (557, 'juklak-2-2026', 251, 'lampiran', 'LAMPIRAN II (lanjutan 232)', NULL, 226, 'Penguatan Sosialisasi risiko Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Dapat didetailkan Pokok sistem respon bencana dan sistem sesuai kebutuhan Jumlah lokasi x sesuai dengan masyarakat peringatan dini Harga satuan Standar Biaya yang terhadap bencana berlaku di peringatan dini Penyusunan Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x kementerian/lemba Pokok bencana prosedur sesuai kebutuhan Jumlah lokasi x ga peringatan dini Harga satuan masyarakat Minimal 3 (tiga) Uji coba prosedur Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x kegiatan untuk 1 Pokok peringatan dini sesuai kebutuhan Jumlah lokasi x (satu) lokasi masyarakat Harga satuan Pembentukan tim Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Opsional peringatan dini sesuai kebutuhan Jumlah lokasi x masyarakat Harga satuan Lokakarya akhir Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Opsional dan pembentukan sesuai kebutuhan Jumlah lokasi x komitmen Harga satuan Peralatan Perangkat penerima Jumlah alat untuk Jumlah paket Jumlah alat x Dapat didetailkan Opsional penyebaran informasi 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai dengan peringatan dini peringatan dini dan sesuai kebutuhan sebaran lokasi Harga satuan Standar Biaya yang bencana dan arahan evakuasi di berlaku di rekomendasi aksi tingkat masyarakat dini/ kementerian/ kesiapsiagaan lembaga Perangkat Jumlah alat untuk Jumlah paket Jumlah alat x Opsional penyebaran arahan 1 (satu) lokasi sesuai jumlah Jumlah lokasi x evakuasi di tingkat sesuai');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (557, 'Penguatan Sosialisasi risiko Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Dapat didetailkan Pokok sistem respon bencana dan sistem sesuai kebutuhan Jumlah lokasi x sesuai dengan masyarakat peringatan dini Harga satuan Standar Biaya yang terhadap bencana berlaku di peringatan dini Penyusunan Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x kementerian/lemba Pokok bencana prosedur sesuai kebutuhan Jumlah lokasi x ga peringatan dini Harga satuan masyarakat Minimal 3 (tiga) Uji coba prosedur Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x kegiatan untuk 1 Pokok peringatan dini sesuai kebutuhan Jumlah lokasi x (satu) lokasi masyarakat Harga satuan Pembentukan tim Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Opsional peringatan dini sesuai kebutuhan Jumlah lokasi x masyarakat Harga satuan Lokakarya akhir Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Opsional dan pembentukan sesuai kebutuhan Jumlah lokasi x komitmen Harga satuan Peralatan Perangkat penerima Jumlah alat untuk Jumlah paket Jumlah alat x Dapat didetailkan Opsional penyebaran informasi 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai dengan peringatan dini peringatan dini dan sesuai kebutuhan sebaran lokasi Harga satuan Standar Biaya yang bencana dan arahan evakuasi di berlaku di rekomendasi aksi tingkat masyarakat dini/ kementerian/ kesiapsiagaan lembaga Perangkat Jumlah alat untuk Jumlah paket Jumlah alat x Opsional penyebaran arahan 1 (satu) lokasi sesuai jumlah Jumlah lokasi x evakuasi di tingkat sesuai', 'LAMPIRAN II (lanjutan 232)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (558, 'juklak-2-2026', 252, 'lampiran', 'LAMPIRAN II (lanjutan 233)', NULL, 226, 'kebutuhan sebaran lokasi Harga satuan masyarakat Alat komunikasi Radio komunikasi Jumlah alat untuk Jumlah paket Jumlah alat x Dapat didetailkan Opsional darurat bencana di tingkat 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai dengan berbasis komunitas sesuai kebutuhan sebaran lokasi Harga satuan Standar Biaya yang komunitas berlaku di kementerian/ lembaga Izin frekuensi Jumlah izin untuk Jumlah paket Jumlah izin x Opsional komunikasi sesuai jumlah alat sesuai jumlah Jumlah lokasi x komunitas untuk 1 (satu) sebaran lokasi Harga satuan lokasi sesuai kebutuhan Biaya Pemeliharaan Jumlah alat untuk Jumlah paket Jumlah alat x Opsional 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai kebutuhan sebaran lokasi Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan peningkatan kapasitas masyarakat dalam merespon peringatan dini bencana melalui pelibatan aktif Operasional masyarakat serta mengintegrasikan komponen struktural dan kultural dengan pendekatan Sistem Peringatan Dini Bencana Berbasis Masyarakat (SPDBBM) yang bertujuan untuk meningkatkan respon dan kapasitas masyarakat dalam menghadapi ancaman bencana agar dapat memastikan masyarakat siap bertindak secara tepat waktu dan efektif, sehingga dapat mengurangi risiko kerugian fisik dan korban jiwa saat bencana terjadi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (558, 'kebutuhan sebaran lokasi Harga satuan masyarakat Alat komunikasi Radio komunikasi Jumlah alat untuk Jumlah paket Jumlah alat x Dapat didetailkan Opsional darurat bencana di tingkat 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai dengan berbasis komunitas sesuai kebutuhan sebaran lokasi Harga satuan Standar Biaya yang komunitas berlaku di kementerian/ lembaga Izin frekuensi Jumlah izin untuk Jumlah paket Jumlah izin x Opsional komunikasi sesuai jumlah alat sesuai jumlah Jumlah lokasi x komunitas untuk 1 (satu) sebaran lokasi Harga satuan lokasi sesuai kebutuhan Biaya Pemeliharaan Jumlah alat untuk Jumlah paket Jumlah alat x Opsional 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai kebutuhan sebaran lokasi Harga satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan peningkatan kapasitas masyarakat dalam merespon peringatan dini bencana melalui pelibatan aktif Operasional masyarakat serta mengintegrasikan komponen struktural dan kultural dengan pendekatan Sistem Peringatan Dini Bencana Berbasis Masyarakat (SPDBBM) yang bertujuan untuk meningkatkan respon dan kapasitas masyarakat dalam menghadapi ancaman bencana agar dapat memastikan masyarakat siap bertindak secara tepat waktu dan efektif, sehingga dapat mengurangi risiko kerugian fisik dan korban jiwa saat bencana terjadi.', 'LAMPIRAN II (lanjutan 233)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
