INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (562, 'juklak-2-2026', 256, 'lampiran', 'LAMPIRAN II (lanjutan 237)', NULL, 229, 'sebaran lokasi Harga satuan masyarakat Alat komunikasi Radio komunikasi Jumlah alat untuk Jumlah paket Jumlah alat x Dapat didetailkan Opsional darurat bencana di tingkat 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai dengan berbasis komunitas sesuai kebutuhan sebaran lokasi Harga satuan Standar Biaya yang komunitas Izin frekuensi Jumlah izin untuk Jumlah paket Jumlah izin x berlaku di daerah Opsional komunikasi sesuai jumlah alat sesuai jumlah Jumlah lokasi x komunitas untuk 1 (satu) sebaran lokasi Harga satuan lokasi sesuai kebutuhan Biaya Pemeliharaan Jumlah alat untuk Jumlah paket Jumlah alat x Opsional 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai kebutuhan sebaran lokasi Harga satuan PEMOHON: KELOMPOK MASYARAKAT Definisi Segala bentuk kegiatan peningkatan kapasitas masyarakat dalam merespon peringatan dini bencana melalui pelibatan aktif Operasional masyarakat serta mengintegrasikan komponen struktural dan kultural dengan pendekatan Sistem Peringatan Dini Bencana Berbasis Masyarakat (SPDBBM) yang bertujuan untuk meningkatkan respon dan kapasitas masyarakat dalam menghadapi ancaman bencana agar dapat memastikan masyarakat siap bertindak secara tepat waktu dan efektif, sehingga dapat mengurangi risiko kerugian fisik dan korban jiwa saat bencana terjadi.');
