INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (563, 'juklak-2-2026', 257, 'lampiran', 'LAMPIRAN II (lanjutan 238)', NULL, 231, 'Penguatan Sosialisasi risiko Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Dapat didetailkan Pokok sistem respon bencana dan sistem sesuai kebutuhan Jumlah lokasi x sesuai dengan masyarakat peringatan dini Harga satuan Standar Biaya yang terhadap bencana berlaku di daerah peringatan dini bencana Penyusunan Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Opsional prosedur sesuai kebutuhan Jumlah lokasi x peringatan dini Harga satuan masyarakat Uji coba prosedur Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Opsional peringatan dini sesuai kebutuhan Jumlah lokasi x masyarakat Harga satuan Pembentukan tim Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Opsional peringatan dini sesuai kebutuhan Jumlah lokasi x masyarakat Harga satuan Lokakarya akhir Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Opsional dan pembentukan sesuai kebutuhan Jumlah lokasi x komitmen Harga satuan Peralatan Perangkat penerima Jumlah alat untuk Jumlah paket Jumlah alat x Dapat didetailkan Opsional penyebaran informasi 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai dengan peringatan dini peringatan dini dan sesuai kebutuhan sebaran lokasi Harga satuan Standar Biaya yang bencana dan arahan evakuasi di berlaku di daerah rekomendasi aksi tingkat masyarakat dini/ Perangkat Jumlah alat untuk Jumlah paket Jumlah alat x Opsional kesiapsiagaan penyebaran arahan 1 (satu) lokasi sesuai jumlah Jumlah lokasi x evakuasi di tingkat sesuai kebutuhan sebaran lokasi Harga satuan masyarakat Alat komunikasi Radio');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (563, 'Penguatan Sosialisasi risiko Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Dapat didetailkan Pokok sistem respon bencana dan sistem sesuai kebutuhan Jumlah lokasi x sesuai dengan masyarakat peringatan dini Harga satuan Standar Biaya yang terhadap bencana berlaku di daerah peringatan dini bencana Penyusunan Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Opsional prosedur sesuai kebutuhan Jumlah lokasi x peringatan dini Harga satuan masyarakat Uji coba prosedur Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Opsional peringatan dini sesuai kebutuhan Jumlah lokasi x masyarakat Harga satuan Pembentukan tim Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Opsional peringatan dini sesuai kebutuhan Jumlah lokasi x masyarakat Harga satuan Lokakarya akhir Jumlah kegiatan Jumlah lokasi Jumlah kegiatan x Opsional dan pembentukan sesuai kebutuhan Jumlah lokasi x komitmen Harga satuan Peralatan Perangkat penerima Jumlah alat untuk Jumlah paket Jumlah alat x Dapat didetailkan Opsional penyebaran informasi 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai dengan peringatan dini peringatan dini dan sesuai kebutuhan sebaran lokasi Harga satuan Standar Biaya yang bencana dan arahan evakuasi di berlaku di daerah rekomendasi aksi tingkat masyarakat dini/ Perangkat Jumlah alat untuk Jumlah paket Jumlah alat x Opsional kesiapsiagaan penyebaran arahan 1 (satu) lokasi sesuai jumlah Jumlah lokasi x evakuasi di tingkat sesuai kebutuhan sebaran lokasi Harga satuan masyarakat Alat komunikasi Radio', 'LAMPIRAN II (lanjutan 238)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (564, 'juklak-2-2026', 258, 'lampiran', 'LAMPIRAN II (lanjutan 239)', NULL, 231, 'komunikasi Jumlah alat untuk Jumlah paket Jumlah alat x Dapat didetailkan Opsional darurat bencana di tingkat 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai dengan komunitas sesuai kebutuhan sebaran lokasi Harga satuan berbasis Izin frekuensi Jumlah izin untuk Jumlah paket Jumlah izin x Standar Biaya yang Opsional komunitas komunikasi sesuai jumlah alat sesuai jumlah Jumlah lokasi x berlaku di daerah komunitas untuk 1 (satu) sebaran lokasi Harga satuan lokasi sesuai kebutuhan Biaya Pemeliharaan Jumlah alat untuk Jumlah paket Jumlah alat x Opsional 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai kebutuhan sebaran lokasi Harga satuan Fasilitator Honorarium Maksimal 2 (dua) Jumlah bulan Jumlah fasilitator x Penetapan jumlah Pokok fasilitator lapangan orang per kawasan/ pekerjaan Jumlah bulan kerja fasilitator lapangan kecamatan/desa/ x Harga satuan tidak boleh lebih kelurahan dari 6 (enam) orang untuk 6 (enam) bulan kerja KEGIATAN : PEMANFAATAN INOVASI TEKNOLOGI UNTUK PENGUATAN KAPASITAS SISTEM PERINGATAN DINI SUB KATEGORI : PERINGATAN DINI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan penyediaan dan/atau pemanfaatan inovasi terbaru dalam bidang teknologi pada berbagai aspek Operasional peringatan dini sesuai lingkup kewenangan pemerintah pusat di tingkat nasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (564, 'komunikasi Jumlah alat untuk Jumlah paket Jumlah alat x Dapat didetailkan Opsional darurat bencana di tingkat 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai dengan komunitas sesuai kebutuhan sebaran lokasi Harga satuan berbasis Izin frekuensi Jumlah izin untuk Jumlah paket Jumlah izin x Standar Biaya yang Opsional komunitas komunikasi sesuai jumlah alat sesuai jumlah Jumlah lokasi x berlaku di daerah komunitas untuk 1 (satu) sebaran lokasi Harga satuan lokasi sesuai kebutuhan Biaya Pemeliharaan Jumlah alat untuk Jumlah paket Jumlah alat x Opsional 1 (satu) lokasi sesuai jumlah Jumlah lokasi x sesuai kebutuhan sebaran lokasi Harga satuan Fasilitator Honorarium Maksimal 2 (dua) Jumlah bulan Jumlah fasilitator x Penetapan jumlah Pokok fasilitator lapangan orang per kawasan/ pekerjaan Jumlah bulan kerja fasilitator lapangan kecamatan/desa/ x Harga satuan tidak boleh lebih kelurahan dari 6 (enam) orang untuk 6 (enam) bulan kerja KEGIATAN : PEMANFAATAN INOVASI TEKNOLOGI UNTUK PENGUATAN KAPASITAS SISTEM PERINGATAN DINI SUB KATEGORI : PERINGATAN DINI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan penyediaan dan/atau pemanfaatan inovasi terbaru dalam bidang teknologi pada berbagai aspek Operasional peringatan dini sesuai lingkup kewenangan pemerintah pusat di tingkat nasional.', 'LAMPIRAN II (lanjutan 239)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (565, 'juklak-2-2026', 259, 'lampiran', 'LAMPIRAN II (lanjutan 240)', NULL, 231, 'Dalam hal ini dapat berupa riset pembuatan perangkat peringatan dini dengan dasar teori dan konsep yang sudah tersusun dengan jelas dan teruji untuk menambah penerima layanan, luas layanan, dll.
Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan Honorarium Jumlah Jumlah jam kerja Jumlah jam kerja x Opsional narasumber narasumber sesuai atau hari kegiatan Harga satuan kebutuhan Pemanfaatan Uji coba operasional Jumlah inovasi Jumlah uji coba Jumlah inovasi Pokok inovasi teknologi inovasi teknologi yang diujicobakan inovasi yang teknologi x Jumlah peringatan dini sesuai kebutuhan dilakukan uji coba x Harga bencana satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan penyediaan dan/atau pemanfaatan inovasi terbaru dalam bidang teknologi pada berbagai aspek Operasional peringatan dini sesuai lingkup kewenangan pemerintah provinsi. Dalam hal ini dapat berupa riset pembuatan perangkat peringatan dini dengan dasar teori dan konsep yang sudah tersusun dengan jelas dan teruji untuk menambah penerima layanan, luas layanan dll.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (565, 'Dalam hal ini dapat berupa riset pembuatan perangkat peringatan dini dengan dasar teori dan konsep yang sudah tersusun dengan jelas dan teruji untuk menambah penerima layanan, luas layanan, dll.
Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan Honorarium Jumlah Jumlah jam kerja Jumlah jam kerja x Opsional narasumber narasumber sesuai atau hari kegiatan Harga satuan kebutuhan Pemanfaatan Uji coba operasional Jumlah inovasi Jumlah uji coba Jumlah inovasi Pokok inovasi teknologi inovasi teknologi yang diujicobakan inovasi yang teknologi x Jumlah peringatan dini sesuai kebutuhan dilakukan uji coba x Harga bencana satuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan penyediaan dan/atau pemanfaatan inovasi terbaru dalam bidang teknologi pada berbagai aspek Operasional peringatan dini sesuai lingkup kewenangan pemerintah provinsi. Dalam hal ini dapat berupa riset pembuatan perangkat peringatan dini dengan dasar teori dan konsep yang sudah tersusun dengan jelas dan teruji untuk menambah penerima layanan, luas layanan dll.', 'LAMPIRAN II (lanjutan 240)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (566, 'juklak-2-2026', 260, 'lampiran', 'LAMPIRAN II (lanjutan 241)', NULL, 233, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan Honorarium Jumlah Jumlah jam kerja Jumlah jam kerja x Opsional narasumber narasumber sesuai atau hari kegiatan Harga satuan kebutuhan Penyediaan Penyediaan 1 (satu) inovasi 1 (satu) paket Jumlah inovasi Dilakukan untuk Pokok inovasi teknologi pengembangan /pengembangan teknologi x Harga pengembangan instrumen inovasi/ teknologi satuan atau inovasi pengembangan teknologi teknologi peringatan dini bencana Pemanfaatan Uji coba operasional Jumlah inovasi Jumlah uji coba Jumlah inovasi Pokok inovasi teknologi inovasi teknologi yang diujicobakan inovasi yang teknologi x Jumlah peringatan dini sesuai kebutuhan dilakukan uji coba x Harga bencana satuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk kegiatan penyediaan dan/atau pemanfaatan inovasi terbaru dalam bidang teknologi pada berbagai aspek Operasional peringatan dini sesuai lingkup kewenangan pemerintah kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (566, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan Honorarium Jumlah Jumlah jam kerja Jumlah jam kerja x Opsional narasumber narasumber sesuai atau hari kegiatan Harga satuan kebutuhan Penyediaan Penyediaan 1 (satu) inovasi 1 (satu) paket Jumlah inovasi Dilakukan untuk Pokok inovasi teknologi pengembangan /pengembangan teknologi x Harga pengembangan instrumen inovasi/ teknologi satuan atau inovasi pengembangan teknologi teknologi peringatan dini bencana Pemanfaatan Uji coba operasional Jumlah inovasi Jumlah uji coba Jumlah inovasi Pokok inovasi teknologi inovasi teknologi yang diujicobakan inovasi yang teknologi x Jumlah peringatan dini sesuai kebutuhan dilakukan uji coba x Harga bencana satuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk kegiatan penyediaan dan/atau pemanfaatan inovasi terbaru dalam bidang teknologi pada berbagai aspek Operasional peringatan dini sesuai lingkup kewenangan pemerintah kabupaten/kota.', 'LAMPIRAN II (lanjutan 241)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (567, 'juklak-2-2026', 261, 'lampiran', 'LAMPIRAN II (lanjutan 242)', NULL, 233, 'Dalam hal ini dapat berupa riset pembuatan perangkat peringatan dini dengan dasar teori dan konsep yang sudah tersusun dengan jelas dan teruji untuk menambah penerima layanan, luas layanan dll Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan Honorarium Jumlah Jumlah jam kerja Jumlah jam kerja x Opsional narasumber narasumber sesuai atau hari kegiatan Harga satuan kebutuhan Penyediaan Penyediaan 1 (satu) inovasi 1 (satu) paket Jumlah inovasi Dilakukan untuk Pokok inovasi teknologi pengembangan /pengembangan teknologi x Harga pengembangan instrumen inovasi/ teknologi satuan atau inovasi pengembangan teknologi teknologi peringatan dini bencana Pemanfaatan Uji coba operasional Jumlah inovasi Jumlah uji coba Jumlah inovasi Pokok inovasi teknologi inovasi teknologi yang diujicobakan inovasi yang teknologi x Jumlah peringatan dini sesuai kebutuhan dilakukan uji coba x Harga bencana satuan KEGIATAN : PENYELENGGARAAN INSTRUMENTASI PERINGATAN DINI SUB KATEGORI : PERINGATAN DINI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan operasionalisasi sistem, platform, dan perangkat peringatan dini yang telah ada di tingkat nasional, Operasional baik berupa operasionalisasi peralatan pengamatan gejala bencana, penerima informasi peringatan dini dari kementerian/lembaga penyedia layanan peringatan dini maupun perangkat penyebaran informasi peringatan dini dan rekomendasi aksi dini kepada pemerintah daerah,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (567, 'Dalam hal ini dapat berupa riset pembuatan perangkat peringatan dini dengan dasar teori dan konsep yang sudah tersusun dengan jelas dan teruji untuk menambah penerima layanan, luas layanan dll Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan Honorarium Jumlah Jumlah jam kerja Jumlah jam kerja x Opsional narasumber narasumber sesuai atau hari kegiatan Harga satuan kebutuhan Penyediaan Penyediaan 1 (satu) inovasi 1 (satu) paket Jumlah inovasi Dilakukan untuk Pokok inovasi teknologi pengembangan /pengembangan teknologi x Harga pengembangan instrumen inovasi/ teknologi satuan atau inovasi pengembangan teknologi teknologi peringatan dini bencana Pemanfaatan Uji coba operasional Jumlah inovasi Jumlah uji coba Jumlah inovasi Pokok inovasi teknologi inovasi teknologi yang diujicobakan inovasi yang teknologi x Jumlah peringatan dini sesuai kebutuhan dilakukan uji coba x Harga bencana satuan KEGIATAN : PENYELENGGARAAN INSTRUMENTASI PERINGATAN DINI SUB KATEGORI : PERINGATAN DINI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan operasionalisasi sistem, platform, dan perangkat peringatan dini yang telah ada di tingkat nasional, Operasional baik berupa operasionalisasi peralatan pengamatan gejala bencana, penerima informasi peringatan dini dari kementerian/lembaga penyedia layanan peringatan dini maupun perangkat penyebaran informasi peringatan dini dan rekomendasi aksi dini kepada pemerintah daerah,', 'LAMPIRAN II (lanjutan 242)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (568, 'juklak-2-2026', 262, 'lampiran', 'LAMPIRAN II (lanjutan 243)', NULL, 233, 'masyarakat, dan kelompok interface lainnya.
Layanan Honorarium Jumlah petugas Jumlah hari kerja Jumlah petugas x (maksimal Opsional Pengamatan dan/atau uang sesuai kebutuhan tiap-tiap petugas Hari kerja x Harga sebanyak jumlah Gejala Bencana saku petugas satuan hari dalam 1 (satu) tahun) Operasional, Sesuai jumlah Jumlah hari kerja Jumlah petugas x Opsional konsumsi, dan petugas, dapat tiap-tiap petugas Hari kerja x Harga akomodasi petugas dalam bentuk satuan tunjangan operasional dan sejenisnya.
Layanan Honorarium Jumlah petugas Jumlah hari kerja Jumlah petugas x Maksimal sebanyak Opsional Pusdalops BNPB dan/atau uang sesuai kebutuhan tiap-tiap petugas Hari kerja x Harga jumlah hari dalam saku petugas satuan 1 (satu) tahun Pusdalops Operasional, Sesuai jumlah Jumlah hari kerja Jumlah petugas x Opsional konsumsi, dan petugas, dapat tiap-tiap petugas Hari kerja x Harga akomodasi dalam bentuk satuan Pusdalops tunjangan operasional dan sejenisnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (568, 'masyarakat, dan kelompok interface lainnya.
Layanan Honorarium Jumlah petugas Jumlah hari kerja Jumlah petugas x (maksimal Opsional Pengamatan dan/atau uang sesuai kebutuhan tiap-tiap petugas Hari kerja x Harga sebanyak jumlah Gejala Bencana saku petugas satuan hari dalam 1 (satu) tahun) Operasional, Sesuai jumlah Jumlah hari kerja Jumlah petugas x Opsional konsumsi, dan petugas, dapat tiap-tiap petugas Hari kerja x Harga akomodasi petugas dalam bentuk satuan tunjangan operasional dan sejenisnya.
Layanan Honorarium Jumlah petugas Jumlah hari kerja Jumlah petugas x Maksimal sebanyak Opsional Pusdalops BNPB dan/atau uang sesuai kebutuhan tiap-tiap petugas Hari kerja x Harga jumlah hari dalam saku petugas satuan 1 (satu) tahun Pusdalops Operasional, Sesuai jumlah Jumlah hari kerja Jumlah petugas x Opsional konsumsi, dan petugas, dapat tiap-tiap petugas Hari kerja x Harga akomodasi dalam bentuk satuan Pusdalops tunjangan operasional dan sejenisnya.', 'LAMPIRAN II (lanjutan 243)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (569, 'juklak-2-2026', 263, 'lampiran', 'LAMPIRAN II (lanjutan 244)', NULL, 237, 'Koordinasi Tim Biaya pemetaan 1 dokumen Jumlah kawasan Jumlah dokumen x Maksimal 1 (satu) Pokok Teknis lokasi penempatan Jumlah kawasan x dokumen untuk 1 Peringatan Dini instrumen Harga satuan (satu) kawasan peringatan dini Konsumsi rapat Sesuai jumlah Jumlah rapat Jumlah peserta x Opsional koordinasi peserta rapat sesuai kebutuhan Jumlah rapat x Harga satuan Snack rapat Sesuai jumlah Jumlah rapat Jumlah peserta x Opsional peserta rapat sesuai kebutuhan Jumlah rapat x Harga satuan Penggandaan Sesuai jumlah rapat Sesuai kebutuhan Jumlah rapat x Opsional materi rapat Harga satuan koordinasi ATK rapat Sesuai jumlah rapat Sesuai kebutuhan Jumlah rapat x Opsional koordinasi Harga satuan Honorarium Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional Narasumber Rapat narasumber sesuai sesuai kebutuhan narasumber x kali rapat untuk 1 Koordinasi kebutuhan (maksimal 4 Jumlah jam kerja x (satu) tahun (empat) jam kerja Jumlah diskusi total untuk 1 (satu) teknis x Harga kali rapat Satuan koordinasi) Operasional Biaya paket data Jumlah perangkat Jumlah bulan Jumlah perangkat x Maksimal sesuai Opsional teknologi internet yang membutuhkan operasi perangkat Jumlah bulan kebutuhan untuk informasi paket data operasi dalam satu beroperasi komunikasi tahun x Harga sepanjang tahun satuan Biaya pulsa Jumlah perangkat Jumlah bulan Jumlah perangkat x Opsional peralatan teknologi yang membutuhkan operasi perangkat Jumlah bulan informasi pulsa operasi dalam satu komunikasi tahun x Harga satuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (569, 'Koordinasi Tim Biaya pemetaan 1 dokumen Jumlah kawasan Jumlah dokumen x Maksimal 1 (satu) Pokok Teknis lokasi penempatan Jumlah kawasan x dokumen untuk 1 Peringatan Dini instrumen Harga satuan (satu) kawasan peringatan dini Konsumsi rapat Sesuai jumlah Jumlah rapat Jumlah peserta x Opsional koordinasi peserta rapat sesuai kebutuhan Jumlah rapat x Harga satuan Snack rapat Sesuai jumlah Jumlah rapat Jumlah peserta x Opsional peserta rapat sesuai kebutuhan Jumlah rapat x Harga satuan Penggandaan Sesuai jumlah rapat Sesuai kebutuhan Jumlah rapat x Opsional materi rapat Harga satuan koordinasi ATK rapat Sesuai jumlah rapat Sesuai kebutuhan Jumlah rapat x Opsional koordinasi Harga satuan Honorarium Jumlah Jumlah jam kerja Jumlah Maksimal 2 (dua) Opsional Narasumber Rapat narasumber sesuai sesuai kebutuhan narasumber x kali rapat untuk 1 Koordinasi kebutuhan (maksimal 4 Jumlah jam kerja x (satu) tahun (empat) jam kerja Jumlah diskusi total untuk 1 (satu) teknis x Harga kali rapat Satuan koordinasi) Operasional Biaya paket data Jumlah perangkat Jumlah bulan Jumlah perangkat x Maksimal sesuai Opsional teknologi internet yang membutuhkan operasi perangkat Jumlah bulan kebutuhan untuk informasi paket data operasi dalam satu beroperasi komunikasi tahun x Harga sepanjang tahun satuan Biaya pulsa Jumlah perangkat Jumlah bulan Jumlah perangkat x Opsional peralatan teknologi yang membutuhkan operasi perangkat Jumlah bulan informasi pulsa operasi dalam satu komunikasi tahun x Harga satuan', 'LAMPIRAN II (lanjutan 244)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (570, 'juklak-2-2026', 264, 'lampiran', 'LAMPIRAN II (lanjutan 245)', NULL, 237, 'Biaya pemeliharaan Jumlah perangkat Jumlah bulan Jumlah perangkat x Opsional dan perawatan yang membutuh- operasi perangkat Jumlah bulan instrumen kan pemeliharaan operasi dalam satu peringatan dini dan perawatan tahun x Harga satuan Pembangunan Biaya Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Termasuk untuk Pokok infrastruktur dan pembangunan kebutuhan Harga satuan pembangunan peralatan infrastruktur dan tower sirene, peralatan repeater, pengendali instrumentasi sirene, dsb, peringatan dini/ Biaya instalasi peralatan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan operasionalisasi sistem, platform, dan perangkat peringatan dini yang telah ada sesuai kewenangan Operasional pemerintah provinsi, baik peralatan pengamatan gejala bencana, peralatan penerima informasi peringatan dini dan rekomendasi aksi dini dari kementerian/lembaga penyedia layanan; perangkat untuk menganalisis hasil kaji cepat untuk mengeluarkan rekomendasi tingkat dan status kedaruratan bencana provinsi; perangkat komunikasi kepada unsur pimpinan daerah provinsi untuk mendapatkan arahan evakuasi dan pengendalian operasi kedaruratan bencana; serta perangkat penyebaran arahan evakuasi yang dikeluarkan oleh unsur pimpinan daerah kepada masyarakat di kawasan rawan bencana.');
