INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (575, 'Koordinasi Tim Biaya pemetaan 1 (satu) dokumen Jumlah kawasan Jumlah dokumen x Maksimal 1 (satu) Pokok Teknis lokasi penempatan Jumlah kawasan x dokumen untuk 1 Peringatan Dini instrumen Harga satuan (satu) kawasan. peringatan dini Konsumsi rapat Sesuai jumlah Jumlah rapat Jumlah peserta x Opsional koordinasi peserta rapat sesuai kebutuhan Jumlah rapat x Harga satuan Snack rapat Sesuai jumlah Jumlah rapat Jumlah peserta x Opsional peserta rapat sesuai kebutuhan Jumlah rapat x Harga satuan Penggandaan Sesuai jumlah rapat Sesuai kebutuhan Jumlah rapat x Opsional materi rapat Harga satuan koordinasi ATK rapat Sesuai jumlah rapat Sesuai kebutuhan Jumlah rapat x Opsional koordinasi Harga satuan Honorarium Jumlah Jumlah jam kerja Jumlah Maksimal 52 (dua) Opsional Narasumber Rapat narasumber sesuai sesuai kebutuhan narasumber x kali rapat untuk 1 Koordinasi kebutuhan (maksimal 4 Jumlah jam kerja x (satu) tahun.', 'LAMPIRAN II (lanjutan 250)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (576, 'juklak-2-2026', 270, 'lampiran', 'LAMPIRAN II (lanjutan 251)', NULL, 242, '(empat) jam kerja Jumlah diskusi total untuk 1 (satu) teknis x Harga kali rapat Satuan koordinasi) Operasional Biaya paket data Jumlah perangkat Jumlah bulan Jumlah perangkat x Maksimal sesuai Opsional teknologi internet yang membutuhkan operasi perangkat Jumlah bulan kebutuhan untuk informasi paket data operasi dalam satu beroperasi komunikasi tahun x Harga sepanjang tahun. satuan Biaya pulsa Jumlah perangkat Jumlah bulan Jumlah perangkat x Opsional peralatan teknologi yang membutuhkan operasi perangkat Jumlah bulan informasi pulsa operasi dalam satu komunikasi tahun x Harga satuan Biaya pemeliharaan Jumlah perangkat Jumlah bulan Jumlah perangkat x Opsional dan perawatan yang membutuh- operasi perangkat Jumlah bulan instrumen kan pemeliharaan operasi dalam satu peringatan dini dan perawatan tahun x Harga satuan Pembangunan Biaya Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Termasuk untuk Pokok infrastruktur dan pembangunan kebutuhan Harga satuan pembangunan peralatan infrastruktur dan tower sirene, peralatan repeater, pengendali instrumentasi sirene, dsb. peringatan dini/ biaya instalasi peralatan KEGIATAN : PEMBANGUNAN/PENGUATAN POS PEMANTAU ANCAMAN SUB KATEGORI : PERINGATAN DINI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk penyediaan infrastruktur dan fasilitas dalam lingkup kewenangan pemerintah pusat, untuk memantau dan Operasional mendeteksi sejak dini potensi ancaman bencana yang beroperasi 24/7.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (576, '(empat) jam kerja Jumlah diskusi total untuk 1 (satu) teknis x Harga kali rapat Satuan koordinasi) Operasional Biaya paket data Jumlah perangkat Jumlah bulan Jumlah perangkat x Maksimal sesuai Opsional teknologi internet yang membutuhkan operasi perangkat Jumlah bulan kebutuhan untuk informasi paket data operasi dalam satu beroperasi komunikasi tahun x Harga sepanjang tahun. satuan Biaya pulsa Jumlah perangkat Jumlah bulan Jumlah perangkat x Opsional peralatan teknologi yang membutuhkan operasi perangkat Jumlah bulan informasi pulsa operasi dalam satu komunikasi tahun x Harga satuan Biaya pemeliharaan Jumlah perangkat Jumlah bulan Jumlah perangkat x Opsional dan perawatan yang membutuh- operasi perangkat Jumlah bulan instrumen kan pemeliharaan operasi dalam satu peringatan dini dan perawatan tahun x Harga satuan Pembangunan Biaya Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Termasuk untuk Pokok infrastruktur dan pembangunan kebutuhan Harga satuan pembangunan peralatan infrastruktur dan tower sirene, peralatan repeater, pengendali instrumentasi sirene, dsb. peringatan dini/ biaya instalasi peralatan KEGIATAN : PEMBANGUNAN/PENGUATAN POS PEMANTAU ANCAMAN SUB KATEGORI : PERINGATAN DINI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk penyediaan infrastruktur dan fasilitas dalam lingkup kewenangan pemerintah pusat, untuk memantau dan Operasional mendeteksi sejak dini potensi ancaman bencana yang beroperasi 24/7.', 'LAMPIRAN II (lanjutan 251)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (577, 'juklak-2-2026', 271, 'lampiran', 'LAMPIRAN II (lanjutan 252)', NULL, 244, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan Pembangunan 1 (satu) lokasi 1 (satu) paket Jumlah lokasi x Dapat didetailkan Pokok pos pemantau infrastruktur pos Harga satuan sesuai dengan ancaman pemantau ancaman Standar Biaya yang bencana berlaku di kementerian/ lembaga Penguatan pos Penyediaan Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Dapat didetailkan Pokok pemantau peralatan dan kebutuhan Harga satuan sesuai dengan ancaman fasilitas pemantau Standar Biaya yang ancaman bencana berlaku di kementerian/ lembaga PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk penyediaan infrastruktur dan fasilitas dalam lingkup kewenangan pemerintah provinsi, untuk memantau dan Operasional mendeteksi sejak dini potensi ancaman bencana yang beroperasi 24/7.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (577, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan Pembangunan 1 (satu) lokasi 1 (satu) paket Jumlah lokasi x Dapat didetailkan Pokok pos pemantau infrastruktur pos Harga satuan sesuai dengan ancaman pemantau ancaman Standar Biaya yang bencana berlaku di kementerian/ lembaga Penguatan pos Penyediaan Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Dapat didetailkan Pokok pemantau peralatan dan kebutuhan Harga satuan sesuai dengan ancaman fasilitas pemantau Standar Biaya yang ancaman bencana berlaku di kementerian/ lembaga PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk penyediaan infrastruktur dan fasilitas dalam lingkup kewenangan pemerintah provinsi, untuk memantau dan Operasional mendeteksi sejak dini potensi ancaman bencana yang beroperasi 24/7.', 'LAMPIRAN II (lanjutan 252)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (578, 'juklak-2-2026', 272, 'lampiran', 'LAMPIRAN II (lanjutan 253)', NULL, 244, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan Pembangunan 1 (satu) lokasi 1 (satu) paket Jumlah lokasi x Dapat didetailkan Pokok pos pemantau infrastruktur pos Harga satuan sesuai dengan ancaman pemantau ancaman Standar Biaya yang bencana berlaku di daerah Penguatan pos Penyediaan Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Dapat didetailkan Pokok pemantau peralatan dan kebutuhan Harga satuan sesuai dengan ancaman fasilitas pemantau Standar Biaya yang ancaman bencana berlaku di daerah PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk penyediaan infrastruktur dan fasilitas dalam lingkup kewenangan pemerintah kabupaten/kota, untuk Operasional memantau dan mendeteksi sejak dini potensi ancaman bencana yang beroperasi 24/7.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (578, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan Pembangunan 1 (satu) lokasi 1 (satu) paket Jumlah lokasi x Dapat didetailkan Pokok pos pemantau infrastruktur pos Harga satuan sesuai dengan ancaman pemantau ancaman Standar Biaya yang bencana berlaku di daerah Penguatan pos Penyediaan Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Dapat didetailkan Pokok pemantau peralatan dan kebutuhan Harga satuan sesuai dengan ancaman fasilitas pemantau Standar Biaya yang ancaman bencana berlaku di daerah PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk penyediaan infrastruktur dan fasilitas dalam lingkup kewenangan pemerintah kabupaten/kota, untuk Operasional memantau dan mendeteksi sejak dini potensi ancaman bencana yang beroperasi 24/7.', 'LAMPIRAN II (lanjutan 253)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (579, 'juklak-2-2026', 273, 'lampiran', 'LAMPIRAN II (lanjutan 254)', NULL, 245, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan Pembangunan 1 (satu) lokasi 1 (satu) paket Jumlah lokasi x Dapat didetailkan Pokok pos pemantau infrastruktur pos Harga satuan sesuai dengan ancaman pemantau ancaman Standar Biaya yang bencana berlaku di daerah Penguatan pos Penyediaan Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Dapat didetailkan Pokok pemantau peralatan dan kebutuhan Harga satuan sesuai dengan ancaman fasilitas pemantau Standar Biaya yang ancaman bencana berlaku di daerah KEGIATAN : PEMBANGUNAN/PENGUATAN INFRASTRUKTUR PUSAT PENGENDALI OPERASI SUB KATEGORI : PERINGATAN DINI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan pembangunan infrastruktur dan penyediaan fasilitas pendukung Pusat Pengendali Operasi Operasional (Pusdalops) untuk dapat beroperasi sesuai fungsinya 24/7.
Infrastruktur dan fasilitas pendukung Pusdalops antara lain seperti:
1. infrastruktur bangunan gedung;
2. fasilitas kelistrikan;
3. fasilitas pemipaan air bersih dan sanitasi;
4. fasilitas penangkal petir;
5. fasilitas deteksi kebakaran dan pemadam;
6. fasilitas jaringan internet dan LAN;
7. interior dan furniture pendukung;
8. dsb.');
