INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (580, 'juklak-2-2026', 274, 'lampiran', 'LAMPIRAN II (lanjutan 255)', NULL, 246, 'Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan Pembangunan 1 (satu) lokasi 1 (satu) paket Jumlah lokasi x Dapat didetailkan Pokok infrastruktur infrastruktur Pusat Harga satuan sesuai dengan Pusat Pengendali Pengendali Operasi Standar Biaya yang Operasi berlaku di kementerian/ lembaga Penguatan Penyediaan Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Dapat didetailkan Pokok infrastruktur peralatan dan kebutuhan Harga satuan sesuai dengan Pusat Pengendali fasilitas Pusat Standar Biaya yang Operasi Pengendali Operasi berlaku di kementerian/ lembaga PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan pembangunan infrastruktur dan penyediaan fasilitas pendukung Pusat Pengendali Operasi Operasional (Pusdalops) BPBD Provinsi untuk dapat beroperasi sesuai fungsinya 24/7.
