INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (582, 'juklak-2-2026', 276, 'lampiran', 'LAMPIRAN II (lanjutan 257)', NULL, 248, '8. dsb Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan Pembangunan 1 (satu) lokasi 1 (satu) paket Jumlah lokasi x Dapat didetailkan Pokok infrastruktur infrastruktur Pusat Harga satuan sesuai dengan Pusat Pengendali Pengendali Operasi Standar Biaya yang Operasi berlaku di daerah Penguatan Penyediaan Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Dapat didetailkan Pokok infrastruktur peralatan dan kebutuhan Harga satuan sesuai dengan Pusat Pengendali fasilitas Pusat Standar Biaya yang Operasi Pengendali Operasi berlaku di daerah KEGIATAN : PEMENUHAN KEBUTUHAN LOGISTIK DAN PERALATAN UNTUK KESIAPSIAGAAN SUB KATEGORI : LOGISTIK DAN PERALATAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan penyediaan cadangan barang habis pakai dan peralatan di tingkat nasional yang dipersiapkan pada Operasional fase prabencana, untuk pemenuhan kebutuhan dasar korban bencana berupa sandang, pangan, dan kebutuhan lainnya serta segala bentuk alat yang dapat dipergunakan untuk menyelenggarakan kesiapsiagaan bencana.
Pemenuhan kebutuhan logistik untuk kesiapsiagaan bencana diprioritaskan kepada:
1) logistik prioritas 1, adalah logistik yang perlu dipersiapkan sebagai kebutuhan pada penanganan awal korban bencana, seperti makanan siap saji, paket perlengkapan keluarga, matras/kasur lipat, selimut, paket sembako, terpal, dsb.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (582, '8. dsb Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan Pembangunan 1 (satu) lokasi 1 (satu) paket Jumlah lokasi x Dapat didetailkan Pokok infrastruktur infrastruktur Pusat Harga satuan sesuai dengan Pusat Pengendali Pengendali Operasi Standar Biaya yang Operasi berlaku di daerah Penguatan Penyediaan Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Dapat didetailkan Pokok infrastruktur peralatan dan kebutuhan Harga satuan sesuai dengan Pusat Pengendali fasilitas Pusat Standar Biaya yang Operasi Pengendali Operasi berlaku di daerah KEGIATAN : PEMENUHAN KEBUTUHAN LOGISTIK DAN PERALATAN UNTUK KESIAPSIAGAAN SUB KATEGORI : LOGISTIK DAN PERALATAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan penyediaan cadangan barang habis pakai dan peralatan di tingkat nasional yang dipersiapkan pada Operasional fase prabencana, untuk pemenuhan kebutuhan dasar korban bencana berupa sandang, pangan, dan kebutuhan lainnya serta segala bentuk alat yang dapat dipergunakan untuk menyelenggarakan kesiapsiagaan bencana.
