INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (583, 'juklak-2-2026', 277, 'lampiran', 'LAMPIRAN II (lanjutan 258)', NULL, 249, '2) logistik prioritas 2, adalah logistik yang perlu diadakan sesuai kebutuhan spesifik korban terdampak bencana pada saat kebutuhan logistik prioritas 1 (satu) telah terpenuhi, seperti paket sandang, paket perlengkapan balita, paket perlengkapan sekolah, paket kebersihan, kantung jenazah, obat-obatan, vaksin, air bersih, dsb.
