INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (584, 'juklak-2-2026', 278, 'lampiran', 'LAMPIRAN II (lanjutan 259)', NULL, 250, '2. Maksimal sesuai kebutuhan pada Rencana Kontingensi dan/atau Standar yang ditetapkan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan penyediaan cadangan barang habis pakai di tingkat provinsi yang dipersiapkan pada fase prabencana, Operasional untuk pemenuhan kebutuhan dasar korban bencana berupa sandang, pangan, dan kebutuhan lainnya serta segala bentuk alat yang dapat dipergunakan untuk menyelenggarakan kesiapsiagaan bencana.
