INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (585, 'juklak-2-2026', 279, 'lampiran', 'LAMPIRAN II (lanjutan 260)', NULL, 251, 'PEMOHON: PEMERINTAH DAERAH PROVINSI Prasyarat permohonan: memiliki Keputusan Kepala Daerah tentang Penetapan Standar Minimal Kebutuhan.
