INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (587, 'juklak-2-2026', 281, 'lampiran', 'LAMPIRAN II (lanjutan 262)', NULL, 252, 'Prasyarat permohonan: memiliki Keputusan Kepala Daerah tentang Penetapan Standar Minimal Kebutuhan Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pengadaan Pemenuhan Logistik prioritas Jumlah logistik/ Jumlah paket Jumlah 1. Maksimal Pokok kebutuhan 1/Logistik prioritas peralatan sesuai sesuai kebutuhan logistik/peralatan x sesuai logistik dan 2/Peralatan kebutuhan Jumlah paket x Penetapan peralatan kesiapsiagaan Harga satuan Standar bencana Minimal Kebutuhan dan/atau akumulasi dukungan sumber daya nasional untuk penanganan darurat bencana pada satu tahun terakhir.
2. Maksimal sesuai kebutuhan pada Rencana Kontingensi dan/atau Standar yang ditetapkan KEGIATAN : DISTRIBUSI LOGISTIK DAN PERALATAN PENANGGULANGAN BENCANA SUB KATEGORI : LOGISTIK DAN PERALATAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan penyaluran logistik dan peralatan penanggulangan bencana pada fase prabencana oleh Operasional kementerian/lembaga, dari titik asal ke titik distribusi dengan menggunakan moda transportasi darat, laut dan udara melalui perencanaan yang memperhatikan rute distribusi, kecepatan dan ketepatan serta menjamin kualitas logistik dan peralatan dalam keadaan baik sampai titik pendistribusian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (587, 'Prasyarat permohonan: memiliki Keputusan Kepala Daerah tentang Penetapan Standar Minimal Kebutuhan Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pengadaan Pemenuhan Logistik prioritas Jumlah logistik/ Jumlah paket Jumlah 1. Maksimal Pokok kebutuhan 1/Logistik prioritas peralatan sesuai sesuai kebutuhan logistik/peralatan x sesuai logistik dan 2/Peralatan kebutuhan Jumlah paket x Penetapan peralatan kesiapsiagaan Harga satuan Standar bencana Minimal Kebutuhan dan/atau akumulasi dukungan sumber daya nasional untuk penanganan darurat bencana pada satu tahun terakhir.
