INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (588, 'juklak-2-2026', 282, 'lampiran', 'LAMPIRAN II (lanjutan 263)', NULL, 254, 'Distribusi logistik Biaya distribusi Berat/dimensi Sesuai kebutuhan Berat/dimensi Pokok dan peralatan PB sesuai pengemasan logistik dan logistik dan peralatan x Harga peralatan satuan pada lokasi tujuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan penyaluran logistik dan peralatan penanggulangan bencana pada fase prabencana oleh pemerintah Operasional provinsi, dari titik asal ke titik distribusi dengan menggunakan moda transportasi darat, laut dan udara melalui perencanaan yang memperhatikan rute distribusi, kecepatan dan ketepatan serta menjamin kualitas logistik dan peralatan dalam keadaan baik sampai titik pendistribusian.
Distribusi Biaya distribusi Berat/dimensi Sesuai kebutuhan Berat/dimensi Pokok logistik dan sesuai pengemasan logistik dan peralatan PB logistik dan peralatan x Harga peralatan satuan pada lokasi tujuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk kegiatan penyaluran logistik dan peralatan penanggulangan bencana pada fase prabencana oleh pemerintah Operasional kabupaten/kota, masyarakat, dan/atau penyediaan barang/jasa, dari titik asal ke titik distribusi dengan menggunakan moda transportasi darat, laut dan udara melalui perencanaan yang memperhatikan rute distribusi, kecepatan dan ketepatan serta menjamin kualitas logistik dan peralatan dalam keadaan baik sampai titik pendistribusian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (588, 'Distribusi logistik Biaya distribusi Berat/dimensi Sesuai kebutuhan Berat/dimensi Pokok dan peralatan PB sesuai pengemasan logistik dan logistik dan peralatan x Harga peralatan satuan pada lokasi tujuan PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan penyaluran logistik dan peralatan penanggulangan bencana pada fase prabencana oleh pemerintah Operasional provinsi, dari titik asal ke titik distribusi dengan menggunakan moda transportasi darat, laut dan udara melalui perencanaan yang memperhatikan rute distribusi, kecepatan dan ketepatan serta menjamin kualitas logistik dan peralatan dalam keadaan baik sampai titik pendistribusian.
Distribusi Biaya distribusi Berat/dimensi Sesuai kebutuhan Berat/dimensi Pokok logistik dan sesuai pengemasan logistik dan peralatan PB logistik dan peralatan x Harga peralatan satuan pada lokasi tujuan PEMOHON: PEMERINTAH DAERAH KABUPATEN/KOTA Definisi Segala bentuk kegiatan penyaluran logistik dan peralatan penanggulangan bencana pada fase prabencana oleh pemerintah Operasional kabupaten/kota, masyarakat, dan/atau penyediaan barang/jasa, dari titik asal ke titik distribusi dengan menggunakan moda transportasi darat, laut dan udara melalui perencanaan yang memperhatikan rute distribusi, kecepatan dan ketepatan serta menjamin kualitas logistik dan peralatan dalam keadaan baik sampai titik pendistribusian.', 'LAMPIRAN II (lanjutan 263)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (589, 'juklak-2-2026', 283, 'lampiran', 'LAMPIRAN II (lanjutan 264)', NULL, 255, 'Distribusi Biaya distribusi Berat/dimensi Sesuai kebutuhan Berat/dimensi Pokok logistik dan sesuai pengemasan logistik dan peralatan PB logistik dan peralatan x Harga peralatan satuan pada lokasi tujuan KEGIATAN : PENYEDIAAN SARANA DAN PRASARANA PERTOLONGAN DAN EVAKUASI DAN PEMBUATAN JALUR PERTOLONGAN DAN EVAKUASI SUB KATEGORI : LOGISTIK DAN PERALATAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan pada fase prabencana di tingkat nasional dalam menyediakan sarana prasarana yang dapat Operasional dimobilisasi pada fase kedaruratan bencana untuk mendukung tim penyelamat dalam memberikan pertolongan serta sarana prasarana untuk memastikan akses tim penyelamat ke lokasi pemberian pertolongan.
Sarana prasarana pertolongan evakuasi antara lain melingkupi fungsi untuk:
1) peralatan pencarian dan fasilitas penanganan orang hilang.
2) peralatan pencarian dan fasilitas penanganan orang meninggal.
3) peralatan dan fasilitas penanganan medis.
Sarana dan prasarana pembuatan jalur pertolongan dan evakuasi antara lain melingkupi fungsi untuk:
1) sarana prasarana pembangunan jembatan darurat.
2) sarana prasarana pembuka jalan alternatif.
3) sarana prasarana transportasi bantuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (589, 'Distribusi Biaya distribusi Berat/dimensi Sesuai kebutuhan Berat/dimensi Pokok logistik dan sesuai pengemasan logistik dan peralatan PB logistik dan peralatan x Harga peralatan satuan pada lokasi tujuan KEGIATAN : PENYEDIAAN SARANA DAN PRASARANA PERTOLONGAN DAN EVAKUASI DAN PEMBUATAN JALUR PERTOLONGAN DAN EVAKUASI SUB KATEGORI : LOGISTIK DAN PERALATAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan pada fase prabencana di tingkat nasional dalam menyediakan sarana prasarana yang dapat Operasional dimobilisasi pada fase kedaruratan bencana untuk mendukung tim penyelamat dalam memberikan pertolongan serta sarana prasarana untuk memastikan akses tim penyelamat ke lokasi pemberian pertolongan.
Sarana prasarana pertolongan evakuasi antara lain melingkupi fungsi untuk:
1) peralatan pencarian dan fasilitas penanganan orang hilang.
2) peralatan pencarian dan fasilitas penanganan orang meninggal.
3) peralatan dan fasilitas penanganan medis.
Sarana dan prasarana pembuatan jalur pertolongan dan evakuasi antara lain melingkupi fungsi untuk:
1) sarana prasarana pembangunan jembatan darurat.
2) sarana prasarana pembuka jalan alternatif.
3) sarana prasarana transportasi bantuan.', 'LAMPIRAN II (lanjutan 264)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
