INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (592, 'Prasyarat permohonan: memiliki Rencana Kesiapsiagaan Logistik dan Peralatan Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pengadaan Penyediaan Sarana prasarana Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Dapat didetailkan Pokok sarana pertolongan kebutuhan Harga satuan sesuai dengan prasarana evakuasi/sarana (maksimal sesuai Standar Biaya yang prasarana kebutuhan pada berlaku di daerah pembuatan jalur rencana pertolongan dan kontingensi evakuasi dan/atau standar yang ditetapkan) KEGIATAN : PEMBANGUNAN/PENGUATAN FASILITAS PERGUDANGAN SUB KATEGORI : LOGISTIK DAN PERALATAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Segala bentuk kegiatan pembangunan infrastruktur tempat penyimpanan logistik dan peralatan kesiapsiagaan bencana dalam Operasional kawasan dan lingkup kewenangan pemerintah pusat, yang telah dilengkapi dengan fasilitas pendukungnya.', 'LAMPIRAN II (lanjutan 267)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (593, 'juklak-2-2026', 287, 'lampiran', 'LAMPIRAN II (lanjutan 268)', NULL, 259, 'Prasyarat permohonan: memiliki Rencana Kesiapsiagaan Logistik dan Peralatan Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan/ Pembangunan Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Dapat didetailkan Pokok penguatan infrastruktur kebutuhan Harga satuan sesuai dengan fasilitas gudang logistik dan (maksimal sesuai Standar Biaya yang pergudangan peralatan kebutuhan pada berlaku di Rencana Kesiap- Kementerian/ siagaan Logistik Lembaga dan Peralatan dan/atau Standar yang ditetapkan) Penguatan fasilitas Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Dapat didetailkan Pokok pendukung kebutuhan Harga satuan sesuai dengan pergudangan (maksimal sesuai Standar Biaya yang kebutuhan pada berlaku di Rencana Kesiap- Kementerian/ siagaan Logistik Lembaga dan Peralatan dan/atau Standar yang ditetapkan) PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Segala bentuk kegiatan pembangunan infrastruktur tempat penyimpanan logistik dan peralatan kesiapsiagaan bencana dalam Operasional kawasan dan lingkup kewenangan pemerintah provinsi, yang telah dilengkapi dengan fasilitas pendukungnya.');
