INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (595, 'juklak-2-2026', 289, 'lampiran', 'LAMPIRAN II (lanjutan 270)', NULL, 261, 'Prasyarat permohonan: memiliki Rencana Kesiapsiagaan Logistik dan Peralatan Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan/ Pembangunan Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x dapat didetailkan Pokok penguatan infrastruktur kebutuhan Harga satuan sesuai dengan fasilitas gudang logistik dan (maksimal sesuai standar biaya yang pergudangan peralatan kebutuhan pada berlaku di daerah Rencana Kesiap-siagaan Logistik dan Peralatan dan/atau Standar yang ditetapkan) Penguatan fasilitas Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Dapat didetailkan Pokok pendukung kebutuhan Harga satuan sesuai dengan pergudangan (maksimal sesuai Standar Biaya yang kebutuhan pada berlaku di daerah Rencana Kesiap-siagaan Logistik dan Peralatan dan/atau Standar yang ditetapkan) KEGIATAN : PELATIHAN TEKNIS PENANGGULANGAN BENCANA SUB KATEGORI : PELATIHAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Seluruh proses penyelenggaraan belajar mengajar dalam rangka meningkatkan kemampuan aparatur sipil negara (ASN) Operasional tingkat pusat, provinsi dan/atau kabupaten/kota untuk memberikan penguasaan pengetahuan dan keterampilan di bidang penanggulangan bencana (termasuk kemampuan dasar, sosio kultural, maupun teknis sektoral) dengan model pelatihan klasikal dan ruang maya yang diselenggarakan oleh lembaga penyelenggara pelatihan terakreditasi atau mendapat penjaminan mutu lembaga diklat yang terakreditasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (595, 'Prasyarat permohonan: memiliki Rencana Kesiapsiagaan Logistik dan Peralatan Persiapan Perencanaan dan Jumlah paket Sesuai kebutuhan Jumlah paket x Opsional koordinasi sesuai kebutuhan Harga satuan pembangunan Pembangunan/ Pembangunan Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x dapat didetailkan Pokok penguatan infrastruktur kebutuhan Harga satuan sesuai dengan fasilitas gudang logistik dan (maksimal sesuai standar biaya yang pergudangan peralatan kebutuhan pada berlaku di daerah Rencana Kesiap-siagaan Logistik dan Peralatan dan/atau Standar yang ditetapkan) Penguatan fasilitas Jumlah unit sesuai Sesuai kebutuhan Jumlah unit x Dapat didetailkan Pokok pendukung kebutuhan Harga satuan sesuai dengan pergudangan (maksimal sesuai Standar Biaya yang kebutuhan pada berlaku di daerah Rencana Kesiap-siagaan Logistik dan Peralatan dan/atau Standar yang ditetapkan) KEGIATAN : PELATIHAN TEKNIS PENANGGULANGAN BENCANA SUB KATEGORI : PELATIHAN PEMOHON: KEMENTERIAN/LEMBAGA Definisi Seluruh proses penyelenggaraan belajar mengajar dalam rangka meningkatkan kemampuan aparatur sipil negara (ASN) Operasional tingkat pusat, provinsi dan/atau kabupaten/kota untuk memberikan penguasaan pengetahuan dan keterampilan di bidang penanggulangan bencana (termasuk kemampuan dasar, sosio kultural, maupun teknis sektoral) dengan model pelatihan klasikal dan ruang maya yang diselenggarakan oleh lembaga penyelenggara pelatihan terakreditasi atau mendapat penjaminan mutu lembaga diklat yang terakreditasi.', 'LAMPIRAN II (lanjutan 270)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (596, 'juklak-2-2026', 290, 'lampiran', 'LAMPIRAN II (lanjutan 271)', NULL, 262, 'Paket Pelatihan Paket pelatihan per Jumlah peserta 1 (satu) paket Jumlah orang x Harga satuan Pokok peserta sesuai kebutuhan Harga satuan untuk 1 (satu) orang peserta pelatihan sesuai dengan SBK yang ditetapkan PMK untuk tiap-tiap kementerian/ lembaga.
PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Seluruh proses penyelenggaraan belajar mengajar dalam rangka meningkatkan kemampuan aparatur sipil negara (ASN) Operasional tingkat provinsi dan/atau kabupaten/kota untuk memberikan penguasaan pengetahuan dan keterampilan di bidang penanggulangan bencana (termasuk kemampuan dasar, sosio kultural, maupun teknis sektoral) dengan model pelatihan klasikal dan ruang maya yang diselenggarakan oleh lembaga penyelenggara pelatihan terakreditasi atau mendapat penjaminan mutu lembaga diklat yang terakreditasi Paket Pelatihan Paket pelatihan per Jumlah peserta 1 (satu) paket Jumlah orang x Harga satuan Pokok peserta sesuai kebutuhan Harga satuan untuk 1 (satu) orang peserta pelatihan sesuai dengan SBK yang ditetapkan PMK untuk tiap-tiap kementerian/lemba ga atau Standar Biaya yang berlaku di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (596, 'Paket Pelatihan Paket pelatihan per Jumlah peserta 1 (satu) paket Jumlah orang x Harga satuan Pokok peserta sesuai kebutuhan Harga satuan untuk 1 (satu) orang peserta pelatihan sesuai dengan SBK yang ditetapkan PMK untuk tiap-tiap kementerian/ lembaga.
