INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (602, 'juklak-2-2026', 296, 'lampiran', 'LAMPIRAN II (lanjutan 277)', NULL, 268, 'KEGIATAN : SERTIFIKASI KOMPETENSI/PROFESI UNTUK PELAKU PENANGGULANGAN BENCANA SUB KATEGORI : PROFESI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Seluruh kegiatan terkait pengukuran dan penilaian kompetensi teknis profesi perorangan ASN kementerian/lembaga terkait Operasional penanggulangan bencana melalui uji kompetensi teknis yang diselenggarakan oleh layanan lembaga sertifikasi profesi yang sah sesuai peraturan perundangan serta kegiatan terkait pengembangan dan peningkatan kompetensi teknis profesi terkait penanggulangan bencana dengan memanfaatkan fasilitas pendidikan formal, informal maupun non formal pada tingkat pusat yang telah ada.
Pengelompokan usulan kegiatan Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana mengacu pada pelaksanaan sertifikasi profesi penanggulangan bencana yang terdiri dari 3 kategori:
• Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana Kategori 1.
Merupakan sertifikasi untuk Level 1-3 dengan sasaran operator.
• Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana Kategori 2.
Merupakan sertifikasi untuk Level 4-6 dengan sasaran jabatan teknisi/analis: koordinator/supervisi.
• Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana Kategori 3.
Merupakan sertifikasi untuk level 7-9 dengan sasaran jabatan ahli: komandan/manajer.
Proses pemberian sertifikat kompetensi yang dilakukan secara sistematis dan objektif melalui uji asesmen kompetensi yang mengacu pada standar kompetensi kerja nasional Indonesia dan/atau internasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (602, 'KEGIATAN : SERTIFIKASI KOMPETENSI/PROFESI UNTUK PELAKU PENANGGULANGAN BENCANA SUB KATEGORI : PROFESI PEMOHON: KEMENTERIAN/LEMBAGA Definisi Seluruh kegiatan terkait pengukuran dan penilaian kompetensi teknis profesi perorangan ASN kementerian/lembaga terkait Operasional penanggulangan bencana melalui uji kompetensi teknis yang diselenggarakan oleh layanan lembaga sertifikasi profesi yang sah sesuai peraturan perundangan serta kegiatan terkait pengembangan dan peningkatan kompetensi teknis profesi terkait penanggulangan bencana dengan memanfaatkan fasilitas pendidikan formal, informal maupun non formal pada tingkat pusat yang telah ada.
Pengelompokan usulan kegiatan Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana mengacu pada pelaksanaan sertifikasi profesi penanggulangan bencana yang terdiri dari 3 kategori:
• Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana Kategori 1.
Merupakan sertifikasi untuk Level 1-3 dengan sasaran operator.
• Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana Kategori 2.
Merupakan sertifikasi untuk Level 4-6 dengan sasaran jabatan teknisi/analis: koordinator/supervisi.
• Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana Kategori 3.
Merupakan sertifikasi untuk level 7-9 dengan sasaran jabatan ahli: komandan/manajer.
Proses pemberian sertifikat kompetensi yang dilakukan secara sistematis dan objektif melalui uji asesmen kompetensi yang mengacu pada standar kompetensi kerja nasional Indonesia dan/atau internasional.', 'LAMPIRAN II (lanjutan 277)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (603, 'juklak-2-2026', 297, 'lampiran', 'LAMPIRAN II (lanjutan 278)', NULL, 268, 'Sertifikasi profesi Sertifikasi kategori Jumlah peserta 1 (satu) paket Jumlah orang x Harga satuan Opsional pelaku 1 sesuai kebutuhan Harga satuan untuk 1 (satu) penanggulangan Sertifikasi kategori Jumlah peserta 1 (satu) paket Jumlah orang x orang peserta Opsional bencana 2 sesuai kebutuhan Harga satuan sertifikasi sesuai Sertifikasi kategori Jumlah peserta 1 (satu) paket Jumlah orang x dengan SBK yang Opsional 3 sesuai kebutuhan Harga satuan ditetapkan PMK untuk tiap-tiap kementerian/lemba ga.
Pengembangan Kegiatan Jumlah kegiatan 1 (satu) paket Jumlah kegiatan x Dapat didetailkan Pokok profesi bidang pengembangan sesuai kebutuhan Harga satuan sesuai dengan penanggulangan profesi bidang (maksimal 1 (satu) Standar Biaya yang bencana penanggulangan kegiatan) berlaku di bencana kementerian/lemba ga.
PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Seluruh kegiatan terkait pengukuran dan penilaian kompetensi teknis profesi perorangan ASN pemerintah provinsi terkait Operasional penanggulangan bencana melalui uji kompetensi teknis yang diselenggarakan oleh layanan lembaga sertifikasi profesi yang sah sesuai peraturan perundangan serta kegiatan terkait pengembangan dan peningkatan kompetensi teknis profesi terkait penanggulangan bencana dengan memanfaatkan fasilitas pendidikan formal, informal maupun non formal pada tingkat pusat yang telah ada.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (603, 'Sertifikasi profesi Sertifikasi kategori Jumlah peserta 1 (satu) paket Jumlah orang x Harga satuan Opsional pelaku 1 sesuai kebutuhan Harga satuan untuk 1 (satu) penanggulangan Sertifikasi kategori Jumlah peserta 1 (satu) paket Jumlah orang x orang peserta Opsional bencana 2 sesuai kebutuhan Harga satuan sertifikasi sesuai Sertifikasi kategori Jumlah peserta 1 (satu) paket Jumlah orang x dengan SBK yang Opsional 3 sesuai kebutuhan Harga satuan ditetapkan PMK untuk tiap-tiap kementerian/lemba ga.
Pengembangan Kegiatan Jumlah kegiatan 1 (satu) paket Jumlah kegiatan x Dapat didetailkan Pokok profesi bidang pengembangan sesuai kebutuhan Harga satuan sesuai dengan penanggulangan profesi bidang (maksimal 1 (satu) Standar Biaya yang bencana penanggulangan kegiatan) berlaku di bencana kementerian/lemba ga.
PEMOHON: PEMERINTAH DAERAH PROVINSI Definisi Seluruh kegiatan terkait pengukuran dan penilaian kompetensi teknis profesi perorangan ASN pemerintah provinsi terkait Operasional penanggulangan bencana melalui uji kompetensi teknis yang diselenggarakan oleh layanan lembaga sertifikasi profesi yang sah sesuai peraturan perundangan serta kegiatan terkait pengembangan dan peningkatan kompetensi teknis profesi terkait penanggulangan bencana dengan memanfaatkan fasilitas pendidikan formal, informal maupun non formal pada tingkat pusat yang telah ada.', 'LAMPIRAN II (lanjutan 278)', 'Petunjuk Pelaksanaan Standar Komponen Biaya Usulan Kegiatan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 2 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (604, 'juklak-2-2026', 298, 'lampiran', 'LAMPIRAN II (lanjutan 279)', NULL, 269, 'Pengelompokan usulan kegiatan Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana mengacu pada pelaksanaan sertifikasi profesi penanggulangan bencana yang terdiri dari 3 kategori:
1. Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana Kategori 1.
Merupakan sertifikasi untuk Level 1-3 dengan sasaran operator.
2. Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana Kategori 2.
Merupakan sertifikasi untuk Level 4-6 dengan sasaran jabatan teknisi/analis: koordinator/ supervisi.
3. Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana Kategori 3.
Merupakan sertifikasi untuk level 7-9 dengan sasaran jabatan ahli: komandan/manajer.
Proses pemberian sertifikat kompetensi yang dilakukan secara sistematis dan objektif melalui uji asesmen kompetensi yang mengacu pada standar kompetensi kerja nasional Indonesia dan/atau internasional.
Sertifikasi profesi Sertifikasi kategori Jumlah peserta 1 paket Jumlah orang x Harga satuan Opsional pelaku 1 sesuai kebutuhan Harga satuan untuk 1 (satu) penanggulangan Sertifikasi kategori Jumlah peserta 1 (satu) paket Jumlah orang x orang peserta Opsional bencana 2 sesuai kebutuhan Harga satuan sertifikasi sesuai dengan SBK yang Sertifikasi kategori Jumlah peserta 1 (satu) paket Jumlah orang x ditetapkan PMK Opsional 3 sesuai kebutuhan Harga satuan untuk tiap-tiap kementerian/lemba ga atau Standar Biaya yang berlaku di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (604, 'Pengelompokan usulan kegiatan Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana mengacu pada pelaksanaan sertifikasi profesi penanggulangan bencana yang terdiri dari 3 kategori:
1. Sertifikasi Profesi untuk Pelaku Penanggulangan Bencana Kategori 1.
