INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (615, 'transportasi Jumlah peserta sesuai Sesuai kebutuhan Jumlah peserta x Pokok peserta kebutuhan Harga satuan Akomodasi dan Tempat dan lokasi Sesuai kebutuhan Sesuai kebutuhan Jumlah hari x Pokok konsumsi simulasi/gladi jumlah hari Harga satuan pelaksanaan penanggulangan simulasi/gladi bencana penanggulangan bencana Konsumsi Jumlah peserta sesuai Jumlah hari sesuai Jumlah peserta x Pokok simulasi/gladi kebutuhan sesi simulasi/gladi Jumlah hari x penanggulangan penanggulangan Harga satuan bencana bencana Mobilisasi Penyediaan dan Jumlah unit sesuai Jumlah hari sesuai Jumlah unit x Pokok peralatan dan mobilisasi kebutuhan sesi simulasi/gladi Jumlah hari x perlengkapan perlengkapan berdasarkan silabus penanggulangan Harga satuan simulasi/gladi simulasi/gladi bencana penanggulangan penanggulangan bencana bencana Sound system Jumlah unit sesuai Jumlah hari sesuai Jumlah unit x Opsional ruangan simulasi/ kebutuhan sesi simulasi/gladi Jumlah hari x gladi berdasarkan silabus penanggulangan Harga satuan penanggulangan simulasi/gladi bencana bencana penanggulangan bencana ATK Alat tulis Jumlah alat tulis Sesuai kebutuhan Jumlah alat tulis x Opsional sesuai kebutuhan Harga satuan KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, Salinan sesuai dengan aslinya ttd.
