INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (616, 'juklak-3-2022', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (616, 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana', 'Judul', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (617, 'juklak-3-2022', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PENGKAJIAN CEPAT PADA KEADAAN DARURAT BENCANA NOMOR 3 TAHUN 2022');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (617, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PENGKAJIAN CEPAT PADA KEADAAN DARURAT BENCANA NOMOR 3 TAHUN 2022', 'Isi hal. 1', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (618, 'juklak-3-2022', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Pasal 48 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menjelaskan bahwa kegiatan pengkajian cepat sebagai salah satu upaya dalam tanggap darurat bencana. Kegiatan tersebut dilakukan untuk memberikan gambaran permasalahan sebagai dampak buruk akibat terjadinya peristiwa ancaman bencana.
Pengkajian secara cepat dan tepat menurut Pasal 22 ayat (1) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, juga menjelaskan bahwa dilakukannya kegiatan pengkajian cepat adalah untuk menentukan kebutuhan dan tindakan yang tepat dalam penanggulangan bencana pada saat tanggap darurat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (618, 'PENDAHULUAN A. Latar Belakang Pasal 48 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menjelaskan bahwa kegiatan pengkajian cepat sebagai salah satu upaya dalam tanggap darurat bencana. Kegiatan tersebut dilakukan untuk memberikan gambaran permasalahan sebagai dampak buruk akibat terjadinya peristiwa ancaman bencana.
Pengkajian secara cepat dan tepat menurut Pasal 22 ayat (1) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, juga menjelaskan bahwa dilakukannya kegiatan pengkajian cepat adalah untuk menentukan kebutuhan dan tindakan yang tepat dalam penanggulangan bencana pada saat tanggap darurat.', 'BAB I', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (619, 'juklak-3-2022', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Untuk pelaksanaan kegiatan pengkajian cepat situasi dan kebutuhan menjadi sangat penting artinya sebagai bentuk respon cepat dari pemerintah kabupaten/kota, mengingat bahwa kabupaten/kota sebagai ujung tombak dalam penanganan darurat bencana. Informasi yang dihasilkan dari pengkajian cepat situasi dan kebutuhan menjadi bahan masukan pemerintah kabupaten/kota dalam menetapkan status keadaan darurat bencana dan untuk menentukan tindakan lebih lanjut atas situasi keadaan darurat bencana yang terjadi. Selain itu sesuai dengan Peraturan Menteri Dalam Negeri Nomor 101 Tahun 2018 tentang Standar Teknis Pelayanan Dasar Pada Standar Pelayanan Minimal Sub Urusan Bencana Daerah Kabupaten/Kota, bahwa kegiatan pengkajian cepat merupakan hal penting sebagai bentuk implementasi dari kegiatan respon cepat dan bagian dari pelayanan penyelamatan dan evakuasi korban bencana yang menjadi urusan wajib pemerintah kabupaten/kota untuk dilaksanakan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (619, 'Untuk pelaksanaan kegiatan pengkajian cepat situasi dan kebutuhan menjadi sangat penting artinya sebagai bentuk respon cepat dari pemerintah kabupaten/kota, mengingat bahwa kabupaten/kota sebagai ujung tombak dalam penanganan darurat bencana. Informasi yang dihasilkan dari pengkajian cepat situasi dan kebutuhan menjadi bahan masukan pemerintah kabupaten/kota dalam menetapkan status keadaan darurat bencana dan untuk menentukan tindakan lebih lanjut atas situasi keadaan darurat bencana yang terjadi. Selain itu sesuai dengan Peraturan Menteri Dalam Negeri Nomor 101 Tahun 2018 tentang Standar Teknis Pelayanan Dasar Pada Standar Pelayanan Minimal Sub Urusan Bencana Daerah Kabupaten/Kota, bahwa kegiatan pengkajian cepat merupakan hal penting sebagai bentuk implementasi dari kegiatan respon cepat dan bagian dari pelayanan penyelamatan dan evakuasi korban bencana yang menjadi urusan wajib pemerintah kabupaten/kota untuk dilaksanakan.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (620, 'juklak-3-2022', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 1, 'Dalam rangka untuk meningkatkan keberhasilan dalam pelaksanaan kegiatan pengkajian cepat situasi dan kebutuhan terkait keadaan darurat bencana, tentunya dibutuhkan suatu pedoman yang dapat digunakan Tim Reaksi Cepat Penanggulangan Bencana kabupaten/kota sebagai acuan dalam pelaksanaan kegiatan dimaksud. Berdasarkan Pasal 12 huruf a Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menyatakan bahwa salah satu tugas BNPB adalah memberikan pedoman dan pengarahan terhadap usaha penang-gulangan bencana yang mencakup pencegahan bencana, penanganan tanggap darurat, dan rehabilitasi dan rekonstruksi secara adil dan setara.
Dengan demikian, atas pertimbangan sebagaimana disebutkan sebelumnya, disusun petunjuk pelaksanaan mengenai Pengkajian Cepat Pada Keadaan Darurat Bencana.
B. Dasar Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah.
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
4. Peraturan Pemerintah Nomor 2 Tahun 2018 tentang Standar Pelayanan Minimal.
5. Peraturan Menteri Dalam Negeri Nomor 101 Tahun 2018 tentang Standar Teknis Pelayanan Dasar pada Standar Pelayanan Minimal Sub Urusan Bencana Daerah Kabupaten/Kota.
C. Maksud dan Tujuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (620, 'Dalam rangka untuk meningkatkan keberhasilan dalam pelaksanaan kegiatan pengkajian cepat situasi dan kebutuhan terkait keadaan darurat bencana, tentunya dibutuhkan suatu pedoman yang dapat digunakan Tim Reaksi Cepat Penanggulangan Bencana kabupaten/kota sebagai acuan dalam pelaksanaan kegiatan dimaksud. Berdasarkan Pasal 12 huruf a Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menyatakan bahwa salah satu tugas BNPB adalah memberikan pedoman dan pengarahan terhadap usaha penang-gulangan bencana yang mencakup pencegahan bencana, penanganan tanggap darurat, dan rehabilitasi dan rekonstruksi secara adil dan setara.
Dengan demikian, atas pertimbangan sebagaimana disebutkan sebelumnya, disusun petunjuk pelaksanaan mengenai Pengkajian Cepat Pada Keadaan Darurat Bencana.
B. Dasar Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah.
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
4. Peraturan Pemerintah Nomor 2 Tahun 2018 tentang Standar Pelayanan Minimal.
5. Peraturan Menteri Dalam Negeri Nomor 101 Tahun 2018 tentang Standar Teknis Pelayanan Dasar pada Standar Pelayanan Minimal Sub Urusan Bencana Daerah Kabupaten/Kota.
C. Maksud dan Tujuan', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (621, 'juklak-3-2022', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, '1. Maksud Petunjuk pelaksanaan ini dimaksudkan sebagai acuan bagi petugas di kabupaten/kota dan dapat digunakan oleh petugas di provinsi dalam melaksanakan pengkajian cepat untuk penanganan darurat bencana.
2. Tujuan Petunjuk pelaksanaan ini bertujuan agar pelaksanaan pengkajian cepat situasi dan kebutuhan dapat terselenggara dengan cepat, tepat, dan akurat untuk mendukung upaya penanganan darurat bencana.
D. Ruang Lingkup Ruang lingkup dari petunjuk pelaksanaan ini mencakup:
a. pelaksanaan pengkajian cepat; dan
b. pengelolaan data dan informasi.
E. Pengertian Umum
1. Data adalah catatan atas kumpulan fakta atau deskripsi berupa angka, karakter, simbol, gambar, peta, tanda isyarat, tulisan, suara, dan/atau bunyi yang merepresentasikan keadaan sebenarnya atau menunjukkan suatu ide, objek, kondisi, atau situasi.
2. Informasi adalah data yang telah diolah sehingga mempunyai makna atau arti.
3. Pengkajian cepat adalah penilaian yang dilakukan segera setelah ada informasi awal adanya ancaman atau kejadian darurat bencana untuk memberikan informasi secara cepat, tepat dan akurat.
4. Pengkajian cepat situasi dan kebutuhan adalah pengkajian cepat yang dilakukan untuk mendapatkan gambaran tentang situasi, dampak dan identifikasi kebutuhan penanganan darurat bencana.
5. Tim Reaksi Cepat Penanggulangan Bencana yang selanjutnya disebut TRC PB adalah tim terpadu lintas sektor yang melakukan tindakan segera setelah ada informasi awal kejadian atau ancaman bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (621, '1. Maksud Petunjuk pelaksanaan ini dimaksudkan sebagai acuan bagi petugas di kabupaten/kota dan dapat digunakan oleh petugas di provinsi dalam melaksanakan pengkajian cepat untuk penanganan darurat bencana.
2. Tujuan Petunjuk pelaksanaan ini bertujuan agar pelaksanaan pengkajian cepat situasi dan kebutuhan dapat terselenggara dengan cepat, tepat, dan akurat untuk mendukung upaya penanganan darurat bencana.
D. Ruang Lingkup Ruang lingkup dari petunjuk pelaksanaan ini mencakup:
a. pelaksanaan pengkajian cepat; dan
b. pengelolaan data dan informasi.
E. Pengertian Umum
1. Data adalah catatan atas kumpulan fakta atau deskripsi berupa angka, karakter, simbol, gambar, peta, tanda isyarat, tulisan, suara, dan/atau bunyi yang merepresentasikan keadaan sebenarnya atau menunjukkan suatu ide, objek, kondisi, atau situasi.
2. Informasi adalah data yang telah diolah sehingga mempunyai makna atau arti.
3. Pengkajian cepat adalah penilaian yang dilakukan segera setelah ada informasi awal adanya ancaman atau kejadian darurat bencana untuk memberikan informasi secara cepat, tepat dan akurat.
4. Pengkajian cepat situasi dan kebutuhan adalah pengkajian cepat yang dilakukan untuk mendapatkan gambaran tentang situasi, dampak dan identifikasi kebutuhan penanganan darurat bencana.
5. Tim Reaksi Cepat Penanggulangan Bencana yang selanjutnya disebut TRC PB adalah tim terpadu lintas sektor yang melakukan tindakan segera setelah ada informasi awal kejadian atau ancaman bencana.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (622, 'juklak-3-2022', 6, 'lain', 'BAB I (lanjutan 4)', NULL, 3, '6. Keadaan darurat bencana adalah suatu keadaan yang mengancam dan mengganggu kehidupan dan penghidupan sekelompok orang/masyarakat dan memerlukan respon penanggulangan segera dan memadai.
7. Status Keadaan Darurat Bencana adalah suatu keadaan darurat bencana yang ditetapkan oleh Pemerintah/Pemerintah Daerah untuk jangka waktu tertentu atas dasar rekomendasi badan yang menyelenggarakan urusan di bidang penanggulangan bencana dan dapat dimulai sejak status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.
8. Status siaga darurat adalah keadaan ketika potensi ancaman bencana sudah mengarah pada terjadinya bencana ditandai dengan adanya informasi peningkatan ancaman berdasarkan sistem peringatan dini yang diberlakukan dan pertimbangan dampak yang akan terjadi di masyarakat.
9. Status tanggap darurat adalah keadaan ketika ancaman bencana benar-benar terjadi dan telah mengganggu kehidupan dan penghidupan sekelompok orang/masyarakat.
10. Penduduk terancam adalah sekelompok orang/masyarakat yang berpotensi terkena dampak buruk bilamana bencana terjadi
11. Penduduk terdampak adalah sekelompok orang/masyarakat yang terkena dampak buruk pada saat kejadian bencana
12. Bed Occupation Rate untuk selanjutnya disingkat BOR adalah persentase pemakaian tempat tidur ruang rawat inap di fasilitas kesehatan pada satuan waktu tertentu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (622, '6. Keadaan darurat bencana adalah suatu keadaan yang mengancam dan mengganggu kehidupan dan penghidupan sekelompok orang/masyarakat dan memerlukan respon penanggulangan segera dan memadai.
7. Status Keadaan Darurat Bencana adalah suatu keadaan darurat bencana yang ditetapkan oleh Pemerintah/Pemerintah Daerah untuk jangka waktu tertentu atas dasar rekomendasi badan yang menyelenggarakan urusan di bidang penanggulangan bencana dan dapat dimulai sejak status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.
8. Status siaga darurat adalah keadaan ketika potensi ancaman bencana sudah mengarah pada terjadinya bencana ditandai dengan adanya informasi peningkatan ancaman berdasarkan sistem peringatan dini yang diberlakukan dan pertimbangan dampak yang akan terjadi di masyarakat.
9. Status tanggap darurat adalah keadaan ketika ancaman bencana benar-benar terjadi dan telah mengganggu kehidupan dan penghidupan sekelompok orang/masyarakat.
10. Penduduk terancam adalah sekelompok orang/masyarakat yang berpotensi terkena dampak buruk bilamana bencana terjadi
11. Penduduk terdampak adalah sekelompok orang/masyarakat yang terkena dampak buruk pada saat kejadian bencana
12. Bed Occupation Rate untuk selanjutnya disingkat BOR adalah persentase pemakaian tempat tidur ruang rawat inap di fasilitas kesehatan pada satuan waktu tertentu.', 'BAB I (lanjutan 4)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (623, 'juklak-3-2022', 7, 'lain', 'BAB I (lanjutan 5)', NULL, 3, '13. Rumah tidak layak huni akibat bencana adalah rumah yang tidak memenuhi persyaratan keselamatan bangunan dan kesehatan penghuni sesuai dengan ketentuan peraturan perundang-undangan atau rumah yang berada dalam kawasan rawan bencana (zona merah) sesuai dengan rekomendasi kementerian/lembaga terkait.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (623, '13. Rumah tidak layak huni akibat bencana adalah rumah yang tidak memenuhi persyaratan keselamatan bangunan dan kesehatan penghuni sesuai dengan ketentuan peraturan perundang-undangan atau rumah yang berada dalam kawasan rawan bencana (zona merah) sesuai dengan rekomendasi kementerian/lembaga terkait.', 'BAB I (lanjutan 5)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (624, 'juklak-3-2022', 8, 'lain', 'BAB II', NULL, 4, 'PELAKSANAAN PENGKAJIAN CEPAT A. Umum Tujuan pelaksanaan pengkajian cepat adalah untuk mendapatkan informasi mengenai:
1. Permasalahan kedaruratan bencana yang terjadi.
2. Respons yang telah dilakukan oleh masyarakat dan petugas setempat.
3. Kebutuhan penanganan darurat bencana dan skala prioritasnya.
4. Kebutuhan sumber daya untuk penanganan darurat bencana disesuaikan dengan standar yang berlaku.
Berdasarkan status keadaan darurat bencana, pengkajian cepat situasi dan kebutuhan dibagi menjadi 2 (dua), yaitu:
1. Pengkajian cepat situasi dan kebutuhan untuk status siaga darurat.
Pengkajian cepat situasi dan kebutuhan ini hanya dilakukan untuk jenis bencana yang “slow on set” atau jenis bencana yang perkembangan kejadian bencananya dapat diamati/tidak mendadak. Pada status keadaan siaga darurat, pengkajian cepat dilakukan segera pada saat awal diketahui adanya peristiwa yang berpotensi menyebabkan terjadinya keadaan darurat bencana.
2. Pengkajian cepat situasi dan kebutuhan untuk status tanggap darurat.
Pengkajian cepat situasi dan kebutuhan yang dilakukan segera pada saat awal terjadinya keadaan darurat bencana.
B. Kebutuhan Informasi Pengkajian cepat dimaksudkan untuk mendapatkan informasi yang cukup bagi para pengambil keputusan di tingkat kabupaten/kota dalam mengantisipasi dan menindaklanjuti ancaman atau kejadian bencana yang terjadi.
Informasi yang dihasilkan dari Pengkajian cepat berfungsi untuk:
1. menggambarkan status siaga darurat; dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (624, 'PELAKSANAAN PENGKAJIAN CEPAT A. Umum Tujuan pelaksanaan pengkajian cepat adalah untuk mendapatkan informasi mengenai:
1. Permasalahan kedaruratan bencana yang terjadi.
2. Respons yang telah dilakukan oleh masyarakat dan petugas setempat.
3. Kebutuhan penanganan darurat bencana dan skala prioritasnya.
4. Kebutuhan sumber daya untuk penanganan darurat bencana disesuaikan dengan standar yang berlaku.
Berdasarkan status keadaan darurat bencana, pengkajian cepat situasi dan kebutuhan dibagi menjadi 2 (dua), yaitu:
1. Pengkajian cepat situasi dan kebutuhan untuk status siaga darurat.
Pengkajian cepat situasi dan kebutuhan ini hanya dilakukan untuk jenis bencana yang “slow on set” atau jenis bencana yang perkembangan kejadian bencananya dapat diamati/tidak mendadak. Pada status keadaan siaga darurat, pengkajian cepat dilakukan segera pada saat awal diketahui adanya peristiwa yang berpotensi menyebabkan terjadinya keadaan darurat bencana.
2. Pengkajian cepat situasi dan kebutuhan untuk status tanggap darurat.
Pengkajian cepat situasi dan kebutuhan yang dilakukan segera pada saat awal terjadinya keadaan darurat bencana.
B. Kebutuhan Informasi Pengkajian cepat dimaksudkan untuk mendapatkan informasi yang cukup bagi para pengambil keputusan di tingkat kabupaten/kota dalam mengantisipasi dan menindaklanjuti ancaman atau kejadian bencana yang terjadi.
Informasi yang dihasilkan dari Pengkajian cepat berfungsi untuk:
1. menggambarkan status siaga darurat; dan', 'BAB II', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (625, 'juklak-3-2022', 9, 'lain', 'BAB II (lanjutan 1)', NULL, 4, '2. menggambarkan status tanggap darurat, dengan penjelasan sebagai berikut:
1. Informasi untuk menggambarkan status siaga darurat terdiri atas:
a. potensi ancaman bencana terkini berdasarkan sistem peringatan dini yang diberlakukan.
b. kondisi wilayah yang terancam.
c. perkiraan penduduk yang terancam, dengan berdasarkan:
1) wilayah terancam; dan 2) demografi, yang terdiri atas: jenis kelamin, rumah tangga/kepala keluarga, kelompok rentan (bayi (0-11 bulan), balita (1-4 tahun), anak (5 tahun – sebelum 18 tahun), ibu hamil, ibu menyusui, lanjut usia (lebih dari 60 tahun) dan kelompok berkebutuhan khusus serta WUS (Wanita Usia Subur).
d. penduduk yang mengungsi/dikarantina (apabila ada), dengan berdasarkan:
1) titik lokasi pengungsian/wilayah karantina.
2) demografi, yang terdiri atas: jenis kelamin, rumah tangga/kepala keluarga, kelompok rentan (bayi (0-11 bulan), balita (1-4 tahun), anak (5 tahun – sebelum 18 tahun), ibu hamil, ibu menyusui, lanjut usia (lebih dari 60 tahun) dan kelompok berkebutuhan khusus) serta WUS (Wanita Usia Subur).
e. status tingkat pendidikan dan sosial penduduk terancam, dengan berdasarkan:
1) Persentase penduduk buta huruf.
2) Persentase penduduk miskin.
3) Kebiasaan makan (pola makanan pokok).
4) Ketersediaan pangan di tingkat penduduk.
f. fasilitas kesehatan dan kesehatan masyarakat di wilayah terancam, dengan berdasarkan:
1) Cakupan imunisasi bayi dan status gizi balita di daerah.
2) Data endemisitas penyakit menular potensial wabah di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (625, '2. menggambarkan status tanggap darurat, dengan penjelasan sebagai berikut:
1. Informasi untuk menggambarkan status siaga darurat terdiri atas:
a. potensi ancaman bencana terkini berdasarkan sistem peringatan dini yang diberlakukan.
b. kondisi wilayah yang terancam.
c. perkiraan penduduk yang terancam, dengan berdasarkan:
1) wilayah terancam; dan 2) demografi, yang terdiri atas: jenis kelamin, rumah tangga/kepala keluarga, kelompok rentan (bayi (0-11 bulan), balita (1-4 tahun), anak (5 tahun – sebelum 18 tahun), ibu hamil, ibu menyusui, lanjut usia (lebih dari 60 tahun) dan kelompok berkebutuhan khusus serta WUS (Wanita Usia Subur).
d. penduduk yang mengungsi/dikarantina (apabila ada), dengan berdasarkan:
1) titik lokasi pengungsian/wilayah karantina.
2) demografi, yang terdiri atas: jenis kelamin, rumah tangga/kepala keluarga, kelompok rentan (bayi (0-11 bulan), balita (1-4 tahun), anak (5 tahun – sebelum 18 tahun), ibu hamil, ibu menyusui, lanjut usia (lebih dari 60 tahun) dan kelompok berkebutuhan khusus) serta WUS (Wanita Usia Subur).
e. status tingkat pendidikan dan sosial penduduk terancam, dengan berdasarkan:
1) Persentase penduduk buta huruf.
2) Persentase penduduk miskin.
3) Kebiasaan makan (pola makanan pokok).
4) Ketersediaan pangan di tingkat penduduk.
f. fasilitas kesehatan dan kesehatan masyarakat di wilayah terancam, dengan berdasarkan:
1) Cakupan imunisasi bayi dan status gizi balita di daerah.
2) Data endemisitas penyakit menular potensial wabah di daerah.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (626, 'juklak-3-2022', 10, 'lain', 'BAB II (lanjutan 2)', NULL, 5, '3) Data cakupan pemanfaatan sarana kesehatan lingkungan (air bersih dan sanitasi) dengan mengidentifikasi ketersediaan yang ada.
4) Data fasilitas kesehatan masyarakat yang dapat difungsikan (Poskesdes, Puskesmas Pembantu, dan Puskesmas).
5) Data fasilitas kesehatan rujukan (puskesmas dan rumah sakit) yang dapat difungsikan dengan memperhitungkan kapasitas (tempat tidur dan BOR).
g. ketersediaan sarana yang dapat dimanfaatkan (sarana angkutan, sarana penerangan/generator set (genset)).
h. tindakan awal yang dilakukan oleh masyarakat, relawan, petugas lokal dan organisasi nonpemerintah di wilayah terancam.
i. Ketersediaan peta jalur evakuasi.
j. akses menuju lokasi wilayah yang terancam.
2. Informasi untuk menggambarkan status tanggap darurat terdiri atas:
a. kronologis kejadian bencana.
b. potensi ancaman bencana ikutan dan susulan.
c. wilayah yang terdampak.
d. penduduk yang terdampak, dengan berdasarkan:
1) wilayah terdampak.
2) demografi, yang terdiri atas: jenis kelamin, rumah tangga/kepala keluarga, kelompok rentan (bayi (0-11 bulan), balita (1-4 tahun), anak (5 tahun – sebelum 18 tahun), ibu hamil, ibu menyusui, lanjut usia (lebih dari 60 tahun) dan kelompok berkebutuhan khusus) serta WUS (Wanita Usia Subur).
e. korban, dengan berdasarkan:
1) angka kematian (angka kematian kasar dan angka kematian balita). Rumus perhitungan angka kematian tercantum pada petunjuk pengisian instrumen pengumpulan data.
2) luka (luka berat dan luka ringan).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (626, '3) Data cakupan pemanfaatan sarana kesehatan lingkungan (air bersih dan sanitasi) dengan mengidentifikasi ketersediaan yang ada.
4) Data fasilitas kesehatan masyarakat yang dapat difungsikan (Poskesdes, Puskesmas Pembantu, dan Puskesmas).
5) Data fasilitas kesehatan rujukan (puskesmas dan rumah sakit) yang dapat difungsikan dengan memperhitungkan kapasitas (tempat tidur dan BOR).
g. ketersediaan sarana yang dapat dimanfaatkan (sarana angkutan, sarana penerangan/generator set (genset)).
h. tindakan awal yang dilakukan oleh masyarakat, relawan, petugas lokal dan organisasi nonpemerintah di wilayah terancam.
i. Ketersediaan peta jalur evakuasi.
j. akses menuju lokasi wilayah yang terancam.
2. Informasi untuk menggambarkan status tanggap darurat terdiri atas:
a. kronologis kejadian bencana.
b. potensi ancaman bencana ikutan dan susulan.
c. wilayah yang terdampak.
d. penduduk yang terdampak, dengan berdasarkan:
1) wilayah terdampak.
2) demografi, yang terdiri atas: jenis kelamin, rumah tangga/kepala keluarga, kelompok rentan (bayi (0-11 bulan), balita (1-4 tahun), anak (5 tahun – sebelum 18 tahun), ibu hamil, ibu menyusui, lanjut usia (lebih dari 60 tahun) dan kelompok berkebutuhan khusus) serta WUS (Wanita Usia Subur).
e. korban, dengan berdasarkan:
1) angka kematian (angka kematian kasar dan angka kematian balita). Rumus perhitungan angka kematian tercantum pada petunjuk pengisian instrumen pengumpulan data.
2) luka (luka berat dan luka ringan).', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (627, 'juklak-3-2022', 11, 'lain', 'BAB II (lanjutan 3)', NULL, 5, '3) sakit menurut jenis penyakit akibat bencana.
4) belum ditemukan dan hilang.
5) penduduk yang terdampak tetapi tidak mengungsi (jumlah, menurut jenis kelamin dan kelompok rentan).
f. penduduk yang mengungsi/dikarantina, dengan berdasarkan:
1) titik lokasi pengungsian/wilayah karantina.
2) demografi, yang terdiri atas: jenis kelamin, rumah tangga/kepala keluarga, kelompok rentan (bayi (0-11 bulan), balita (1-4 tahun), anak (5 tahun – sebelum 18 tahun), ibu hamil, ibu menyusui, lanjut usia (lebih dari 60 tahun) dan kelompok berkebutuhan khusus) serta WUS (Wanita Usia Subur).
Informasi ini tidak diperlukan apabila tidak terdapat penduduk yang mengungsi/dikarantina.
g. kerusakan, yang meliputi:
1) rumah tidak layak huni akibat bencana.
2) prasarana fisik seperti: jalan, jembatan, tanggul, bandara, pelabuhan, tempat ibadah, sekolah, kantor pemerintah, pasar, dan lain-lain.
3) sarana utilitas seperti: jaringan listrik, jaringan komunikasi, jaringan air bersih, tempat pengisian bahan bakar umum.
4) kerusakan lahan (pertanian, perkebunan, perikanan dan peternakan).
h. status tingkat pendidikan dan sosial penduduk terdampak, dengan berdasarkan:
1) persentase penduduk buta huruf.
2) persentase penduduk miskin.
3) kebiasaan makan (pola makanan pokok).
4) ketersediaan pangan penduduk terdampak.
i. kesehatan, dengan berdasarkan:
1) cakupan imunisasi bayi dan status gizi balita di daerah.
2) data endemisitas penyakit menular potensial di daerah.');
