INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (628, 'juklak-3-2022', 12, 'lain', 'BAB II (lanjutan 4)', NULL, 6, '3) data cakupan pemanfaatan sarana kesehatan lingkungan (air bersih dan sanitasi) dengan mengidentifikasi ketersediaan yang ada.
4) data fasilitas kesehatan masyarakat yang dapat difungsikan (poskesdes, puskesmas pembantu, dan puskesmas).
5) data fasilitas kesehatan rujukan (rumah sakit) yang dapat difungsikan dengan memperhitungkan kapasitas (tempat tidur dan BOR).
j. ketersediaan sarana yang dapat dimanfaatkan (sarana angkutan, sarana penerangan/genset, alat berat, dan lain-lain).
k. ketersediaan peta jalur evakuasi.
l. akses menuju lokasi wilayah terdampak dan tempat pengungsian.
m. tindakan awal yang dilakukan oleh masyarakat, relawan, petugas lokal dan organisasi nonpemerintah di wilayah terdampak.
n. kebutuhan mendesak untuk penanganan darurat bencana, yang terdiri atas:
1) pencarian dan pertolongan korban.
2) evakuasi korban dan pengungsi.
3) pemenuhan kebutuhan dasar (air bersih, sanitasi, pangan, sandang, pelayanan kesehatan, pelayanan psikososial dan penampungan sementara/shelter).
4) perbaikan fungsi prasarana dan sarana vital.
C. Waktu, Tempat, dan Pelaksana
1. Waktu pelaksanaan Waktu pelaksanaan pengkajian cepat disesuaikan dengan status penanganan darurat, terdiri atas:
a. Status siaga darurat Kaji cepat dilakukan paling lambat 1 x 24 jam setelah informasi diterima dari masyarakat, relawan atau petugas lokal yang menunjukkan tanda-tanda mengarah akan terjadi bencana sesuai dengan sistem peringatan dini yang diberlakukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (628, '3) data cakupan pemanfaatan sarana kesehatan lingkungan (air bersih dan sanitasi) dengan mengidentifikasi ketersediaan yang ada.
4) data fasilitas kesehatan masyarakat yang dapat difungsikan (poskesdes, puskesmas pembantu, dan puskesmas).
5) data fasilitas kesehatan rujukan (rumah sakit) yang dapat difungsikan dengan memperhitungkan kapasitas (tempat tidur dan BOR).
j. ketersediaan sarana yang dapat dimanfaatkan (sarana angkutan, sarana penerangan/genset, alat berat, dan lain-lain).
k. ketersediaan peta jalur evakuasi.
l. akses menuju lokasi wilayah terdampak dan tempat pengungsian.
m. tindakan awal yang dilakukan oleh masyarakat, relawan, petugas lokal dan organisasi nonpemerintah di wilayah terdampak.
n. kebutuhan mendesak untuk penanganan darurat bencana, yang terdiri atas:
1) pencarian dan pertolongan korban.
2) evakuasi korban dan pengungsi.
3) pemenuhan kebutuhan dasar (air bersih, sanitasi, pangan, sandang, pelayanan kesehatan, pelayanan psikososial dan penampungan sementara/shelter).
4) perbaikan fungsi prasarana dan sarana vital.
C. Waktu, Tempat, dan Pelaksana
1. Waktu pelaksanaan Waktu pelaksanaan pengkajian cepat disesuaikan dengan status penanganan darurat, terdiri atas:
a. Status siaga darurat Kaji cepat dilakukan paling lambat 1 x 24 jam setelah informasi diterima dari masyarakat, relawan atau petugas lokal yang menunjukkan tanda-tanda mengarah akan terjadi bencana sesuai dengan sistem peringatan dini yang diberlakukan.', 'BAB II (lanjutan 4)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (629, 'juklak-3-2022', 13, 'lain', 'BAB II (lanjutan 5)', NULL, 7, 'b. Status tanggap darurat Kaji cepat dilakukan paling lambat 1 x 24 jam setelah informasi awal terjadinya bencana yang diterima berdasarkan laporan oleh masyarakat ataupun petugas lokal.
2. Tempat Pelaksanaan Tempat pelaksanaan pengkajian cepat adalah:
a. Status siaga darurat, dilakukan di wilayah yang berpotensi terdampak bencana.
b. Status tanggap darurat, dilakukan di:
1) wilayah terdampak langsung bencana;
2) wilayah yang tidak terdampak langsung bencana tetapi terdapat pengungsian; dan 3) wilayah sekitar lokasi bencana yang memiliki potensi dapat membantu penanganan darurat bencana.
3. Pelaksana Kaji cepat dilakukan oleh petugas yang tergabung dalam TRC PB kabupaten/kota, dengan susunan tim paling sedikit terdiri atas:
a. Ketua tim;
b. Anggota (kompeten mengkaji bidang kesehatan);
c. Anggota (kompeten mengkaji bidang sosial);
d. Anggota (kompeten mengkaji bidang infrastruktur);
e. Anggota (kompeten dalam pengelolaan data dan informasi);
f. Anggota (kompeten dalam pengkajian bidang logistik dan peralatan); dan
g. Anggota (tenaga pendukung).
D. Prosedur Pelaksanaan
1. Persiapan Persiapan pelaksanaan pengkajian cepat terdiri atas:
a. Menyiapkan Surat Tugas yang ditandatangani oleh Sekretaris Daerah selaku Kepala BPBD.
b. Menyiapkan data sekunder.
c. Menghubungi aparat setempat dan komunikasikan tentang penugasan.
d. Melakukan pembagian tugas tim.
e. mempelajari kronologis kejadian berdasarkan informasi awal yang ada.
f. mempelajari wilayah penugasan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (629, 'b. Status tanggap darurat Kaji cepat dilakukan paling lambat 1 x 24 jam setelah informasi awal terjadinya bencana yang diterima berdasarkan laporan oleh masyarakat ataupun petugas lokal.
2. Tempat Pelaksanaan Tempat pelaksanaan pengkajian cepat adalah:
a. Status siaga darurat, dilakukan di wilayah yang berpotensi terdampak bencana.
b. Status tanggap darurat, dilakukan di:
1) wilayah terdampak langsung bencana;
2) wilayah yang tidak terdampak langsung bencana tetapi terdapat pengungsian; dan 3) wilayah sekitar lokasi bencana yang memiliki potensi dapat membantu penanganan darurat bencana.
3. Pelaksana Kaji cepat dilakukan oleh petugas yang tergabung dalam TRC PB kabupaten/kota, dengan susunan tim paling sedikit terdiri atas:
a. Ketua tim;
b. Anggota (kompeten mengkaji bidang kesehatan);
c. Anggota (kompeten mengkaji bidang sosial);
d. Anggota (kompeten mengkaji bidang infrastruktur);
e. Anggota (kompeten dalam pengelolaan data dan informasi);
f. Anggota (kompeten dalam pengkajian bidang logistik dan peralatan); dan
g. Anggota (tenaga pendukung).
D. Prosedur Pelaksanaan
1. Persiapan Persiapan pelaksanaan pengkajian cepat terdiri atas:
a. Menyiapkan Surat Tugas yang ditandatangani oleh Sekretaris Daerah selaku Kepala BPBD.
b. Menyiapkan data sekunder.
c. Menghubungi aparat setempat dan komunikasikan tentang penugasan.
d. Melakukan pembagian tugas tim.
e. mempelajari kronologis kejadian berdasarkan informasi awal yang ada.
f. mempelajari wilayah penugasan.', 'BAB II (lanjutan 5)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2022 tentang Pengkajian Cepat Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (630, 'juklak-3-2022', 14, 'lain', 'BAB II (lanjutan 6)', NULL, 8, 'g. Memahami karakteristik dari jenis bencana yang terjadi atau yang akan terjadi.
h. Menyiapkan sarana transportasi dan akomodasi (dana operasional, kelengkapan pribadi, alat tulis kantor, obat-obatan pribadi, logistik, dan lain lain).
i. Menyiapkan form-form pengkajian cepat yang digunakan.
j. Menggunakan identitas/atribut yang seragam.
2. Hal-hal yang harus diperhatikan dalam pelaksanaan
a. Paling lambat 1 x 24 jam setelah perintah penugasan diterima, satuan tugas TRC PB kabupaten/kota yang mendapatkan penugasan pengkajian cepat harus sudah bergerak menuju lokasi terancam/terdampak bencana.
b. Setibanya di lokasi tugas, TRC PB kabupaten/kota agar segera melaporkan diri kepada pejabat/petugas setempat dan menjelaskan rencana kegiatan pengkajian cepat yang akan dilakukan.
c. Pelaksanaan kegiatan pengkajian cepat dapat dilakukan penyesuaian-penyesuaian dengan dinamika situasi dan perkembangan di lapangan.
d. Melaporkan/menginformasikan hasil pengkajian cepat sesegera mungkin dengan mengutamakan informasi yang menjadi prioritas.
e. Waktu pelaksanaan tugas disesuaikan dengan kebutuhan dan dapat diperpanjang atau diperpendek jika diperlukan.
f. Memperhatikan norma, adat, budaya, dan kondisi masyarakat terdampak bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (630, 'g. Memahami karakteristik dari jenis bencana yang terjadi atau yang akan terjadi.
h. Menyiapkan sarana transportasi dan akomodasi (dana operasional, kelengkapan pribadi, alat tulis kantor, obat-obatan pribadi, logistik, dan lain lain).
