INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (633, 'juklak-3-2022', 17, 'lain', 'BAB III (lanjutan 2)', NULL, 10, 'Tabel 1. Jumlah korban banjir di kecamatan Sukamaju Uraian korban Jumlah Meninggal 23 Luka Berat 16 Luka Ringan 108 Hilang 17 Total 163 Dari tabel di atas tampak tertulis total korban adalah 163 orang, yang seharusnya jika dilakukan perhitungan seksama totalnya adalah 164 orang.
