INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (636, 'juklak-3-2022', 20, 'lain', 'I. Tidak tamat SD: 1 orang', NULL, 12, 'J. Tidak sekolah: 1 orang Dari data tersebut kita ubah menjadi variabel tingkat pendidikan KK K. Pendidikan Tinggi (D3 keatas): 4 orang L. Pendidikan Sedang (Tamat SLTA, Tamat SLTP): 11 orang M. Pendidikan Rendah (Tamat SD, Tidak Tamat SD, Tidak Sekolah): 5 orang Contoh transformasi data dengan mengelompokan nilainya menjadi variabel baru:
Hasil pendataan status imunisasi bayi di lokasi pengungsian Balai Desa Lor No Nama Nama BCG DPT-3 Polio- Campa HB-Bayi KK 4 k 3 1 Fahri Ahmad + + + - + 2 Lili Agus + + + + + 3 Valen Riky - + + + - 4 Syukur Abdul + + - + + 5 Ami Umar + + + + + 6 Zainal Joko + - - + + 7 Yayah Ibnu + + + + + 8 Husein Amir - - - - - 9 Linda Saat - - - + - 10 Anita Teguh + + + + + Dari data status imunisasi bayi di atas dibuatlah variabel baru yaitu imunisasi lengkap. Dikatakan lengkap jika bayi telah mendapatkan imunisasi BCG, DPT 3x, Polio 4x, campak dan HB 3x. Dengan demikian nilai variabel imunisasi bayi lengkap adalah sebagai berikut:
N. Imunisasi bayi lengkap: 4 anak O. Imunisasi bayi belum lengkap: 6 anak
5. Penyajian Data Penyajian Data merupakan tindakan menyajikan data, berupa tulisan, tabel, diagram dan/atau sajian lainnya sesuai kebutuhan.
a. Tulisan Data disajikan dalam bentuk kalimat untuk menerangkan kumpulan data yang telah diperoleh.
Contoh:
Jumlah korban pada kejadian bencana banjir bandang di kabupaten Cilacap tanggal 12 Februari 2007 adalah 3 orang meninggal, 17 orang luka berat dan 45 luka ringan serta 6 orang hilang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (636, 'J. Tidak sekolah: 1 orang Dari data tersebut kita ubah menjadi variabel tingkat pendidikan KK K. Pendidikan Tinggi (D3 keatas): 4 orang L. Pendidikan Sedang (Tamat SLTA, Tamat SLTP): 11 orang M. Pendidikan Rendah (Tamat SD, Tidak Tamat SD, Tidak Sekolah): 5 orang Contoh transformasi data dengan mengelompokan nilainya menjadi variabel baru:
Hasil pendataan status imunisasi bayi di lokasi pengungsian Balai Desa Lor No Nama Nama BCG DPT-3 Polio- Campa HB-Bayi KK 4 k 3 1 Fahri Ahmad + + + - + 2 Lili Agus + + + + + 3 Valen Riky - + + + - 4 Syukur Abdul + + - + + 5 Ami Umar + + + + + 6 Zainal Joko + - - + + 7 Yayah Ibnu + + + + + 8 Husein Amir - - - - - 9 Linda Saat - - - + - 10 Anita Teguh + + + + + Dari data status imunisasi bayi di atas dibuatlah variabel baru yaitu imunisasi lengkap. Dikatakan lengkap jika bayi telah mendapatkan imunisasi BCG, DPT 3x, Polio 4x, campak dan HB 3x. Dengan demikian nilai variabel imunisasi bayi lengkap adalah sebagai berikut:
N. Imunisasi bayi lengkap: 4 anak O. Imunisasi bayi belum lengkap: 6 anak
