INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (678, 'juklak-3-2022', 62, 'lain', 'V. KESIMPULAN DAN REKOMENDASI', NULL, 39, '1) Kesimpulan dan rekomendasi untuk penetapan status siaga darurat bencana: siaga darurat bencana atau tidak, jika siaga darurat bencana berapa lama perkiraan waktu berlakunya Petunjuk: lingkari jawaban yang sesuai Apakah Status Siaga Darurat Bencana? Ya Tidak Petunjuk: Jika status keadaan menunjukkan siaga darurat bencana, maka anda dimohon untuk lanjut mengisi tabel berikut:
Perkiraan Lama waktu Status Siaga Alasan Darurat Bencana ………… hari 2) Kesimpulan dan rekomendasi kebutuhan tindakan dan sumber daya, gambaran kendala/hambatan Sektor Kebutuhan Tindakan dan Sumber Daya Kesehatan Penyelamatan dan evakuasi Air bersih, sanitasi, dan hygiene Pangan (memperhatikan pola makanan pokok) Nonpangan Penampungan dan hunian sementara Sarana utilitas (jaringan listrik, telekomunikasi, dan air bersih) Prasarana dan sarana lain');
