INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (681, 'juklak-3-2022', 65, 'lain', 'II. ANALISIS SITUASI DAMPAK', NULL, 41, 'a. Cakupan wilayah terdampak: (nama wilayah Desa/Kelurahan, Kecamatan, jumlah dan persentase pada wilayah terdampak) ……………………………………………………………………………………… ……………………………………………………………………………………… ………………………………………………………………………………………
