INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (703, 'Petunjuk Pelaksanaan Nomor 3 Tahun 2023 tentang Pemberian Bantuan Hunian Sementara Bagi Pengungsi Korban Bencana', 'Judul', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2023 tentang Pemberian Bantuan Hunian Sementara Bagi Pengungsi Korban Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (704, 'juklak-3-2023', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMBERIAN BANTUAN HUNIAN SEMENTARA BAGI PENGUNGSI KORBAN BENCANA NOMOR 3 TAHUN 2023');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (704, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMBERIAN BANTUAN HUNIAN SEMENTARA BAGI PENGUNGSI KORBAN BENCANA NOMOR 3 TAHUN 2023', 'Isi hal. 1', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2023 tentang Pemberian Bantuan Hunian Sementara Bagi Pengungsi Korban Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (705, 'juklak-3-2023', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN Latar Belakang Jumlah kejadian bencana di Indonesia cenderung meningkat setiap tahunnya. Salah satu dampak buruk dari kejadian bencana seringkali menimbulkan adanya arus pengungsian penduduk terdampak. Pasal 53 huruf f Undang-Undang Nomor 24 tahun 2007 tentang Penanggulangan Bencana menjelaskan bahwa upaya pemenuhan kebutuhan dasar salah satunya adalah berupa bantuan penyediaan penampungan dan tempat hunian. Bantuan penampungan dan tempat hunian yang diharapkan adalah dalam bentuk hunian sementara yang dipergunakan selama waktu mengungsi.
Selama ini hunian sementara yang disiapkan bagi pengungsi pada setiap kejadian bencana sangat bervariasi baik jenis maupun luasannya. Hal ini seringkali menimbulkan masalah tersendiri di dalam mengelola tempat pengungsi korban dampak bencana. Sesuai amanat pasal 12 huruf a dan b Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menjelaskan bahwa salah satu tugas Badan Nasional Penanggulangan Bencana (BNPB) adalah memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana yang mencakup pencegahan bencana, penanganan tanggap darurat, rehabilitasi, dan rekonstruksi secara adil dan setara, serta menetapkan standardisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundang-undangan. Untuk itulah, dalam rangka mendukung upaya pemenuhan kebutuhan dasar terkait penyedian tempat huntara bagi para pengungsi akibat bencana perlu didukung adanya Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (705, 'PENDAHULUAN Latar Belakang Jumlah kejadian bencana di Indonesia cenderung meningkat setiap tahunnya. Salah satu dampak buruk dari kejadian bencana seringkali menimbulkan adanya arus pengungsian penduduk terdampak. Pasal 53 huruf f Undang-Undang Nomor 24 tahun 2007 tentang Penanggulangan Bencana menjelaskan bahwa upaya pemenuhan kebutuhan dasar salah satunya adalah berupa bantuan penyediaan penampungan dan tempat hunian. Bantuan penampungan dan tempat hunian yang diharapkan adalah dalam bentuk hunian sementara yang dipergunakan selama waktu mengungsi.
Selama ini hunian sementara yang disiapkan bagi pengungsi pada setiap kejadian bencana sangat bervariasi baik jenis maupun luasannya. Hal ini seringkali menimbulkan masalah tersendiri di dalam mengelola tempat pengungsi korban dampak bencana. Sesuai amanat pasal 12 huruf a dan b Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menjelaskan bahwa salah satu tugas Badan Nasional Penanggulangan Bencana (BNPB) adalah memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana yang mencakup pencegahan bencana, penanganan tanggap darurat, rehabilitasi, dan rekonstruksi secara adil dan setara, serta menetapkan standardisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundang-undangan. Untuk itulah, dalam rangka mendukung upaya pemenuhan kebutuhan dasar terkait penyedian tempat huntara bagi para pengungsi akibat bencana perlu didukung adanya Petunjuk Pelaksanaan.', 'BAB I', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2023 tentang Pemberian Bantuan Hunian Sementara Bagi Pengungsi Korban Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (706, 'juklak-3-2023', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Maksud dan Tujuan
1. Maksud Petunjuk pelaksanaan ini dimaksudkan sebagai rujukan /acuan bagi kementerian/lembaga, pemerintah daerah, lembaga non pemerintah, lembaga internasional dan/atau lembaga asing non pemerintah terkait dalam mengelola bantuan hunian sementara.
1
2. Tujuan Tujuan dari petunjuk pelaksanan ini adalah tersedianya mekanisme pengelolaan bantuan hunian sementara secara cepat, tepat, efektif, efisien, transparan, akuntabel dan inklusi.
Ruang Lingkup Ruang lingkup Petunjuk Pelaksanaan ini meliputi:
1. standar dan jenis bantuan, dan
2. mekanisme penyelenggaraan bantuan.
Pengertian
1. Pemerintah Pusat, yang selanjutnya disebut Pemerintah, adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
2. Pemerintah Daerah adalah gubernur, bupati/walikota atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
3. Kementerian Negara yang selanjutnya disebut Kementerian adalah perangkat pemerintah yang membidangi urusan tertentu dalam pemerintahan.
4. Lembaga Pemerintah Non kementerian yang selanjutnya disingkat LPNK adalah lembaga pemerintah pusat yang melaksanakan tugas pemerintahan tertentu.
5. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB, adalah lembaga pemerintah non-departemen sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (706, 'Maksud dan Tujuan
1. Maksud Petunjuk pelaksanaan ini dimaksudkan sebagai rujukan /acuan bagi kementerian/lembaga, pemerintah daerah, lembaga non pemerintah, lembaga internasional dan/atau lembaga asing non pemerintah terkait dalam mengelola bantuan hunian sementara.
1
2. Tujuan Tujuan dari petunjuk pelaksanan ini adalah tersedianya mekanisme pengelolaan bantuan hunian sementara secara cepat, tepat, efektif, efisien, transparan, akuntabel dan inklusi.
Ruang Lingkup Ruang lingkup Petunjuk Pelaksanaan ini meliputi:
1. standar dan jenis bantuan, dan
2. mekanisme penyelenggaraan bantuan.
Pengertian
1. Pemerintah Pusat, yang selanjutnya disebut Pemerintah, adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
2. Pemerintah Daerah adalah gubernur, bupati/walikota atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
3. Kementerian Negara yang selanjutnya disebut Kementerian adalah perangkat pemerintah yang membidangi urusan tertentu dalam pemerintahan.
4. Lembaga Pemerintah Non kementerian yang selanjutnya disingkat LPNK adalah lembaga pemerintah pusat yang melaksanakan tugas pemerintahan tertentu.
5. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB, adalah lembaga pemerintah non-departemen sesuai dengan ketentuan peraturan perundang-undangan.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2023 tentang Pemberian Bantuan Hunian Sementara Bagi Pengungsi Korban Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (707, 'juklak-3-2023', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, '6. Badan Penanggulangan Bencana Daerah, yang selanjutnya disingkat BPBD, adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
7. Lembaga/Organisasi Non Pemerintah adalah suatu lembaga yang didirikan atas prakarsa swasta yang menghimpun orang-orang swasta atau publik, fisik dan moral dari berbagai kewarganegaraan.
8. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
9. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
10. 11.
12. 13.
14. 15.
16. K7 Keadaan Darurat Bencana adalah suatu keadaan yang mengancam dan mengganggu kehidupan dan penghidupan sekelompok orang/masyarakat yang memerlukan tindakan penanganan segera dan memadai.
Status Keadaan Darurat Bencana adalah suatu keadaan yang ditetapkan oleh pemerintah untuk jangka waktu tertentu atas dasar rekomendasi Badan yang diberi tugas untuk menanggulangi bencana terdiri atas siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (707, '6. Badan Penanggulangan Bencana Daerah, yang selanjutnya disingkat BPBD, adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
7. Lembaga/Organisasi Non Pemerintah adalah suatu lembaga yang didirikan atas prakarsa swasta yang menghimpun orang-orang swasta atau publik, fisik dan moral dari berbagai kewarganegaraan.
8. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
9. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
10. 11.
12. 13.
14. 15.
16. K7 Keadaan Darurat Bencana adalah suatu keadaan yang mengancam dan mengganggu kehidupan dan penghidupan sekelompok orang/masyarakat yang memerlukan tindakan penanganan segera dan memadai.
Status Keadaan Darurat Bencana adalah suatu keadaan yang ditetapkan oleh pemerintah untuk jangka waktu tertentu atas dasar rekomendasi Badan yang diberi tugas untuk menanggulangi bencana terdiri atas siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2023 tentang Pemberian Bantuan Hunian Sementara Bagi Pengungsi Korban Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (708, 'juklak-3-2023', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 3, 'Penanganan Darurat Bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada keadaan darurat bencana untuk mengendalikan ancaman/penyebab bencana dan menanggulangi dampak yang ditimbulkan.
Bantuan Penanganan Darurat Bencana adalah bantuan untuk mengendalikan ancaman/penyebab bencana dan menanggulangi dampak yang ditimbulkan pada keadaan darurat bencana.
Korban bencana adalah orang atau kelompok orang yang menderita atau meninggal dunia akibat bencana.
Pengungsi adalah orang atau kelompok orang yang terpaksa atau dipaksa keluar dari tempat tinggalnya untuk jangka waktu yang belum pasti sebagai akibat dampak buruk bencana.
Hunian Sementara yang selanjutnya disingkat Huntara adalah tempat tinggal sementara selama korban bencana mengungsi, baik berupa tempat tinggal individu, keluarga maupun penampungan kolektif yang dapat memberikan perlindungan dari pengaruh buruk dari cuaca/kondisi alam lainnya, penyakit, kekerasan, kejahatan dan bahaya lainnya.
Kelompok rentan adalah bayi, anak usia dibawah lima tahun, anak-anak, ibu hamil atau menyusui, penyandang disabilitas, dan orang lanjut usia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (708, 'Penanganan Darurat Bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada keadaan darurat bencana untuk mengendalikan ancaman/penyebab bencana dan menanggulangi dampak yang ditimbulkan.
Bantuan Penanganan Darurat Bencana adalah bantuan untuk mengendalikan ancaman/penyebab bencana dan menanggulangi dampak yang ditimbulkan pada keadaan darurat bencana.
Korban bencana adalah orang atau kelompok orang yang menderita atau meninggal dunia akibat bencana.
Pengungsi adalah orang atau kelompok orang yang terpaksa atau dipaksa keluar dari tempat tinggalnya untuk jangka waktu yang belum pasti sebagai akibat dampak buruk bencana.
Hunian Sementara yang selanjutnya disingkat Huntara adalah tempat tinggal sementara selama korban bencana mengungsi, baik berupa tempat tinggal individu, keluarga maupun penampungan kolektif yang dapat memberikan perlindungan dari pengaruh buruk dari cuaca/kondisi alam lainnya, penyakit, kekerasan, kejahatan dan bahaya lainnya.
Kelompok rentan adalah bayi, anak usia dibawah lima tahun, anak-anak, ibu hamil atau menyusui, penyandang disabilitas, dan orang lanjut usia.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2023 tentang Pemberian Bantuan Hunian Sementara Bagi Pengungsi Korban Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (709, 'juklak-3-2023', 6, 'lain', 'BAB II', NULL, 4, 'STANDAR DAN JENIS BANTUAN A. STANDAR BANTUAN Pemberian bantuan Huntara perlu memastikan terpenuhinya standar teknis minimal. Standar teknis minimal yang harus dipenuhi adalah sebagai berikut:
1. Ruang untuk hunian berukuran minimal 3,5 m2 per orang,
2. Memenuhi persyaratan keamanan dan keselamatan:
3. Memenuhi persyaratan kenyamanan dan kesehatan (sirkulasi udara dan pencahayaan yang cukup):
4. Menjamin privasi antar jenis kelamin dan berbagai kelompok usia, dan
5. Memiliki aksesibilitas terhadap fasilitas umum Adapun rincian dari standar teknis minimal bantuan Huntara sebagaimana dimaksud di atas meliputi: rancang bangun, lokasi, fasilitas pendukung, dan pemulihan mandiri.
1. Rancang Bangun Rancang bangun penyediaan Huntara memerlukan pengaturan minimal mengenai struktur bangunan, desain bangunan, kebutuhan ruang, material bangunan, aspek kesehatan, serta aspek keselamatan, keamanan, dan lingkungan.
a. Struktur bangunan Huntara Bangunan Huntara memiliki pondasi, kolom utama, balok utama, serta memiliki penutup atap dengan konstruksi kuda-kuda yang kuat.
b. Desain bangunan Pemilihan desain bangunan bantuan Huntara dilaksanakan oleh ahli yang kompeten dan memiliki kemampuan konstruksi bangunan baik dalam perencanaan maupun pelaksanaan.
c. Kebutuhan minimal ruang Kebutuhan minimal ruang tidur dan ruang kumpul anggota keluarga.
d. Material/ bahan.
Material/ bahan yang digunakan untuk penyediaan Huntara:
1) Memenuhi Standar Nasional Indonesia (SNI):');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (709, 'STANDAR DAN JENIS BANTUAN A. STANDAR BANTUAN Pemberian bantuan Huntara perlu memastikan terpenuhinya standar teknis minimal. Standar teknis minimal yang harus dipenuhi adalah sebagai berikut:
1. Ruang untuk hunian berukuran minimal 3,5 m2 per orang,
2. Memenuhi persyaratan keamanan dan keselamatan:
3. Memenuhi persyaratan kenyamanan dan kesehatan (sirkulasi udara dan pencahayaan yang cukup):
4. Menjamin privasi antar jenis kelamin dan berbagai kelompok usia, dan
5. Memiliki aksesibilitas terhadap fasilitas umum Adapun rincian dari standar teknis minimal bantuan Huntara sebagaimana dimaksud di atas meliputi: rancang bangun, lokasi, fasilitas pendukung, dan pemulihan mandiri.
1. Rancang Bangun Rancang bangun penyediaan Huntara memerlukan pengaturan minimal mengenai struktur bangunan, desain bangunan, kebutuhan ruang, material bangunan, aspek kesehatan, serta aspek keselamatan, keamanan, dan lingkungan.
a. Struktur bangunan Huntara Bangunan Huntara memiliki pondasi, kolom utama, balok utama, serta memiliki penutup atap dengan konstruksi kuda-kuda yang kuat.
b. Desain bangunan Pemilihan desain bangunan bantuan Huntara dilaksanakan oleh ahli yang kompeten dan memiliki kemampuan konstruksi bangunan baik dalam perencanaan maupun pelaksanaan.
c. Kebutuhan minimal ruang Kebutuhan minimal ruang tidur dan ruang kumpul anggota keluarga.
d. Material/ bahan.
Material/ bahan yang digunakan untuk penyediaan Huntara:
1) Memenuhi Standar Nasional Indonesia (SNI):', 'BAB II', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2023 tentang Pemberian Bantuan Hunian Sementara Bagi Pengungsi Korban Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (710, 'juklak-3-2023', 7, 'lain', 'BAB II (lanjutan 1)', NULL, 4, '2) Menggunakan material tidak beracun, baik sebelum maupun sesudah digunakan. Sebagai contoh: tidak menggunakan material yang mengandung asbestos, 3) Menggunakan material dalam proses pembuatannya tidak memproduksi zat-zat berbahaya bagi lingkungan, 4) Menggunakan material yang bisa didapatkan dengan mudah dan dekat, tanpa merusak lingkungan, dan 5) Mempertimbangkan kekuatan jenis material yang digunakan dalam waktu tertentu dan menghindari penggunaan material yang mudah terbakar.
e. Kebutuhan minimal aspek kesehatan:
1) Pencahayaan Ruang Huntara mendapatkan cahaya yang cukup minimal 1046 (sepuluh persen) dari luas lantai ruangan dan mendapatkan distribusi cahaya secara merata.
2) Penghawaan/sirkulasi udara Kesegaran udara dalam ruangan dari penghawaan alami, maka diberikan peranginan silang (ventilasi silang) dengan ketentuan lubang penghawaan minimal 5x (lima persen) dari luas lantai ruangan.
f. Aspek keamanan dan kearifan lokal Aspek keamanan dan kearifan lokal dipenuhi dengan cara penilaian risiko terhadap lokasi Huntara yang direncanakan. Penilaian risiko dilakukan pada saat pemilihan lokasi Huntara.
g. Jangka waktu penyediaan.
Jangka waktu penyediaan memperhitungkan:
1) perencanaan dan jangka waktu penyediaan hunian tetap yang direncanakan Pemerintah, 2) komitmen penyedia Huntara:
3) kesediaan penerima manfaat: dan 4) ketersediaan sumber daya yang dibutuhkan.
h. Jangka waktu pemanfaatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (710, '2) Menggunakan material tidak beracun, baik sebelum maupun sesudah digunakan. Sebagai contoh: tidak menggunakan material yang mengandung asbestos, 3) Menggunakan material dalam proses pembuatannya tidak memproduksi zat-zat berbahaya bagi lingkungan, 4) Menggunakan material yang bisa didapatkan dengan mudah dan dekat, tanpa merusak lingkungan, dan 5) Mempertimbangkan kekuatan jenis material yang digunakan dalam waktu tertentu dan menghindari penggunaan material yang mudah terbakar.
e. Kebutuhan minimal aspek kesehatan:
1) Pencahayaan Ruang Huntara mendapatkan cahaya yang cukup minimal 1046 (sepuluh persen) dari luas lantai ruangan dan mendapatkan distribusi cahaya secara merata.
2) Penghawaan/sirkulasi udara Kesegaran udara dalam ruangan dari penghawaan alami, maka diberikan peranginan silang (ventilasi silang) dengan ketentuan lubang penghawaan minimal 5x (lima persen) dari luas lantai ruangan.
f. Aspek keamanan dan kearifan lokal Aspek keamanan dan kearifan lokal dipenuhi dengan cara penilaian risiko terhadap lokasi Huntara yang direncanakan. Penilaian risiko dilakukan pada saat pemilihan lokasi Huntara.
g. Jangka waktu penyediaan.
Jangka waktu penyediaan memperhitungkan:
1) perencanaan dan jangka waktu penyediaan hunian tetap yang direncanakan Pemerintah, 2) komitmen penyedia Huntara:
3) kesediaan penerima manfaat: dan 4) ketersediaan sumber daya yang dibutuhkan.
h. Jangka waktu pemanfaatan.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2023 tentang Pemberian Bantuan Hunian Sementara Bagi Pengungsi Korban Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (711, 'juklak-3-2023', 8, 'lain', 'BAB II (lanjutan 2)', NULL, 5, 'Jangka waktu pemanfaatan Huntara disesuaikan dengan jangka waktu yang dibutuhkan untuk ketersediaan hunian tetap yang layak dihuni.
i. Aksesibilitas Huntara disediakan dengan kemudahan akses bagi penerima manfaat dengan memperhatikan aspek inklusi.
Aspek inklusi ditujukan untuk:
1) memastikan kelompok rentan dan kelompok berisiko lainnya mempunyai akses yang setara ke layanan dasar, 2) memastikan kelompok rentan dan kelompok berisiko lainnya memiliki hak suara dalam pengembangan dan pelaksanaan layanan dasar, dan 3) memastikan penyedia bantuan Huntara melakukan upaya-upaya khusus untuk mengatasi dan menghilangkan hambatan bagi kelompok rentan dan kelompok berisiko lainnya.
Aksesibilitas meliputi:
1) Privasi Huntara minimal memiliki 1 (satu) ruang privasi yang dapat digunakan oleh anggota keluarga.
2) Kelompok rentan dan kelompok berisiko lainnya Desain huntara pada keadaaan darurat bencana memperhatikan kemudahan akses kelompok rentan (bayi, anak usia dibawah 5 tahun, anak-anak, ibu hamil atau menyusui, penyandang disabilitas, dan lanjut usia) dan kelompok berisiko lainnya seperti penderita HIV AIDS, orang dengan komplikasi penyakit dan orang yang tinggal di wilayah berisiko tinggi.
3) Aspek penghidupan (livelihood) Huntara harus memperhatikan jarak dengan lokasi mata pencaharian korban bencana.
2. Lokasi Pemilihan lokasi penyediaan Huntara memperhatikan aspek-aspek sebagai berikut :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (711, 'Jangka waktu pemanfaatan Huntara disesuaikan dengan jangka waktu yang dibutuhkan untuk ketersediaan hunian tetap yang layak dihuni.
i. Aksesibilitas Huntara disediakan dengan kemudahan akses bagi penerima manfaat dengan memperhatikan aspek inklusi.
Aspek inklusi ditujukan untuk:
1) memastikan kelompok rentan dan kelompok berisiko lainnya mempunyai akses yang setara ke layanan dasar, 2) memastikan kelompok rentan dan kelompok berisiko lainnya memiliki hak suara dalam pengembangan dan pelaksanaan layanan dasar, dan 3) memastikan penyedia bantuan Huntara melakukan upaya-upaya khusus untuk mengatasi dan menghilangkan hambatan bagi kelompok rentan dan kelompok berisiko lainnya.
Aksesibilitas meliputi:
1) Privasi Huntara minimal memiliki 1 (satu) ruang privasi yang dapat digunakan oleh anggota keluarga.
2) Kelompok rentan dan kelompok berisiko lainnya Desain huntara pada keadaaan darurat bencana memperhatikan kemudahan akses kelompok rentan (bayi, anak usia dibawah 5 tahun, anak-anak, ibu hamil atau menyusui, penyandang disabilitas, dan lanjut usia) dan kelompok berisiko lainnya seperti penderita HIV AIDS, orang dengan komplikasi penyakit dan orang yang tinggal di wilayah berisiko tinggi.
3) Aspek penghidupan (livelihood) Huntara harus memperhatikan jarak dengan lokasi mata pencaharian korban bencana.
2. Lokasi Pemilihan lokasi penyediaan Huntara memperhatikan aspek-aspek sebagai berikut :', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2023 tentang Pemberian Bantuan Hunian Sementara Bagi Pengungsi Korban Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (712, 'juklak-3-2023', 9, 'lain', 'BAB II (lanjutan 3)', NULL, 6, 'a. Kepemilikan lahan Memastikan status hukum kepemilikan dan perizinan lahan yang akan dimanfaatkan untuk Huntara sehingga tidak berpotensi sengketa di masa yang akan datang.
b. Menilai risiko Melakukan penilaian risiko yang komprehensif terhadap lokasi dengan melakukan identifikasi dan evaluasi bahaya/ancaman seperti banjir, longsor, gempa bumi, jarak dengan area industri, pembuangan sampah, kesehatan lingkungan, rawa-rawa atau ancaman lain yang dapat membahayakan keselamatan pengungsi dan korban bencana.
c. Melibatkan pemangku kepentingan dan ahli Pemilihan lokasi Huntara melibatkan pemangku kepentingan dan ahli dalam memberikan pertimbangan tentang risiko geografis, persyaratan dan masalah potensial yang spesifik untuk wilayah tersebut.
d. Akses ke layanan dasar Pemilihan lokasi Huntara mempertimbangkan ketersediaan dan jarak ke layanan dasar seperti air bersih, fasilitas sanitasi, layanan kesehatan, layanan pendidikan, layanan informasi dan peluang mata pencaharian.
e. Infrastruktur dan utilitas Mempertimbangkan infrastruktur dan utilitas yang sudah ada, seperti jalan, listrik dan telekomunikasi.
f. Partisipasi masyarakat Memastikan adanya komunikasi dua arah, memastikan masyarakat memiliki peran yang bermakna dalam setiap tahapan kegiatan, merencanakan mekanisme umpan balik bersama masyarakat dan berjalan sesuai dengan aspek sosial dan budaya masyarakat setempat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (712, 'a. Kepemilikan lahan Memastikan status hukum kepemilikan dan perizinan lahan yang akan dimanfaatkan untuk Huntara sehingga tidak berpotensi sengketa di masa yang akan datang.
b. Menilai risiko Melakukan penilaian risiko yang komprehensif terhadap lokasi dengan melakukan identifikasi dan evaluasi bahaya/ancaman seperti banjir, longsor, gempa bumi, jarak dengan area industri, pembuangan sampah, kesehatan lingkungan, rawa-rawa atau ancaman lain yang dapat membahayakan keselamatan pengungsi dan korban bencana.
c. Melibatkan pemangku kepentingan dan ahli Pemilihan lokasi Huntara melibatkan pemangku kepentingan dan ahli dalam memberikan pertimbangan tentang risiko geografis, persyaratan dan masalah potensial yang spesifik untuk wilayah tersebut.
d. Akses ke layanan dasar Pemilihan lokasi Huntara mempertimbangkan ketersediaan dan jarak ke layanan dasar seperti air bersih, fasilitas sanitasi, layanan kesehatan, layanan pendidikan, layanan informasi dan peluang mata pencaharian.
e. Infrastruktur dan utilitas Mempertimbangkan infrastruktur dan utilitas yang sudah ada, seperti jalan, listrik dan telekomunikasi.
f. Partisipasi masyarakat Memastikan adanya komunikasi dua arah, memastikan masyarakat memiliki peran yang bermakna dalam setiap tahapan kegiatan, merencanakan mekanisme umpan balik bersama masyarakat dan berjalan sesuai dengan aspek sosial dan budaya masyarakat setempat.', 'BAB II (lanjutan 3)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2023 tentang Pemberian Bantuan Hunian Sementara Bagi Pengungsi Korban Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (713, 'juklak-3-2023', 10, 'lain', 'BAB II (lanjutan 4)', NULL, 6, 'g. Dampak lingkungan Pemilihan lokasi Huntara meminimalkan efek negatif terhadap lingkungan, sebagai contoh seperti berlokasi di kawasan konservasi.
h. Keamanan dan keselamatan Penilaian keamanan dan keselamatan lokasi Huntara dilakukan dengan mempertimbangkan faktor-faktor seperti tingkat kejahatan, daerah konflik, keberadaan layanan keamanan, potensi kekerasan berbasis gender, dan lingkungan yang nyaman bagi penghuninya.
i. Perencanaan kedepan Pemilihan lokasi harus mempertimbangkan rencana keberlanjutan jangka panjang dan rencana pengembangan di daerah tersebut.
Perencanaan dilakukan dengan mengevaluasi lokasi Huntara yang ditentukan dengan jangka waktu kebutuhan pemukiman.
3. Fasilitas Pendukung Penyediaan Huntara wajib dilengkapi dengan fasilitas pendukung dengan pemenuhan terhadap aspek-aspek sebagai berikut:
a. Akses transportasi Lokasi Huntara harus memiliki akses transportasi guna memastikan dukungan mobilitas bagi korban bencana.
b. Akses telekomunikasi.
Lokasi Huntara harus memiliki akses telekomunikasi guna memastikan dukungan informasi mudah diterima oleh korban bencana.
Cc. Akses energi (listrik, gas dan bbm) Lokasi Huntara harus memiliki akses pada energi untuk memenuhi kebutuhan dasar korban bencana.
d. Akses pelayanan kesehatan, air bersih dan sanitasi Lokasi Huntara harus memiliki akses pada layanan kesehatan, air bersih dan sanitasi untuk memenuhi kebutuhan dasar korban bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (713, 'g. Dampak lingkungan Pemilihan lokasi Huntara meminimalkan efek negatif terhadap lingkungan, sebagai contoh seperti berlokasi di kawasan konservasi.
h. Keamanan dan keselamatan Penilaian keamanan dan keselamatan lokasi Huntara dilakukan dengan mempertimbangkan faktor-faktor seperti tingkat kejahatan, daerah konflik, keberadaan layanan keamanan, potensi kekerasan berbasis gender, dan lingkungan yang nyaman bagi penghuninya.
i. Perencanaan kedepan Pemilihan lokasi harus mempertimbangkan rencana keberlanjutan jangka panjang dan rencana pengembangan di daerah tersebut.
