INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (718, 'juklak-3-2023', 15, 'lain', 'BAB II (lanjutan 9)', NULL, 10, 'Satu tanda indikator panjang setiap meter/logo pelanggan berdasarkan permintaan Terpal atau Tenda Gulung Kelebihan Kekurangan 1) Tersedia dalam bentuk 1) Terbatasnya ventilasi gulungan atau Lembaran. menyebabkan suhu 2) Dapat dipotong-potong meningkat di siang hari, sesuai ukuran yang sehingga hanya cocok diinginkan dan lebih digunakan di malam hari. fleksibel. 2) Risiko terjadinya 3) Dapat dibuat ventilasi kebakaran jika melakukan sesuai kebutuhan, sehingga aktivitas memasak di dianggap lebih sesuai dalam tenda. untuk daerah tropis. 3) Tidak dapat dikembangkan 4) Berfungsi baik dengan menjadi tempat hunian material yang ada. permanen.
5) Lebih sesuai untuk kondisi | 4) Kemungkinan perdesaan yang keterpaparan terhadap komunitasnya mungkin faktor alam dalam jangka memiliki keterampilan panjang akan membangun lebih tinggi menimbulkan masalah dan akses ke material Kesehatan khususnya jika kerangka yang lebih luas. terjadi pergantian musim.
6) Sesuai untuk penggunaan 5) Harus ada konstruksi yang lebih luas, atap yang pendukung rusak, struktur umum, 6) Tidak dapat digunakan 10 dinding jamban. untuk jangka waktu yang 7) Tidak terlalu tebal sehingga lama. banyak yang dapat diangkut oleh transportasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (718, 'Satu tanda indikator panjang setiap meter/logo pelanggan berdasarkan permintaan Terpal atau Tenda Gulung Kelebihan Kekurangan 1) Tersedia dalam bentuk 1) Terbatasnya ventilasi gulungan atau Lembaran. menyebabkan suhu 2) Dapat dipotong-potong meningkat di siang hari, sesuai ukuran yang sehingga hanya cocok diinginkan dan lebih digunakan di malam hari. fleksibel. 2) Risiko terjadinya 3) Dapat dibuat ventilasi kebakaran jika melakukan sesuai kebutuhan, sehingga aktivitas memasak di dianggap lebih sesuai dalam tenda. untuk daerah tropis. 3) Tidak dapat dikembangkan 4) Berfungsi baik dengan menjadi tempat hunian material yang ada. permanen.
5) Lebih sesuai untuk kondisi | 4) Kemungkinan perdesaan yang keterpaparan terhadap komunitasnya mungkin faktor alam dalam jangka memiliki keterampilan panjang akan membangun lebih tinggi menimbulkan masalah dan akses ke material Kesehatan khususnya jika kerangka yang lebih luas. terjadi pergantian musim.
6) Sesuai untuk penggunaan 5) Harus ada konstruksi yang lebih luas, atap yang pendukung rusak, struktur umum, 6) Tidak dapat digunakan 10 dinding jamban. untuk jangka waktu yang 7) Tidak terlalu tebal sehingga lama. banyak yang dapat diangkut oleh transportasi.', 'BAB II (lanjutan 9)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2023 tentang Pemberian Bantuan Hunian Sementara Bagi Pengungsi Korban Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (719, 'juklak-3-2023', 16, 'lain', 'BAB II (lanjutan 10)', NULL, 11, 'c. Perbaikan bangunan rumah untuk tinggal sementara Perbaikan terhadap non-struktural atau bagian lain dari rumah tinggal asal yang terdampak bencana agar dapat ditempati sementara berupa bantuan penyediaan material hunian dan peralatan pertukangan untuk mendukung perbaikan dan/atau jasa untuk perbaikan. Penilaian awal harus dilakukan oleh tenaga yang kompeten dari instansi berwenang sebelum perbaikan bangunan.
Kriteria umum perbaikan non-struktural meliputi:
1) Perbaikan terhadap non-struktur bangunan rumah seperti dinding retak dengan lebar « 6mm/tidak tembus, kaca pecah, genteng terlepas dan plafon lepas.
2) Bangunan masih tegak berdiri dan tidak miring.
3) Tidak ada kerusakan/keretakan pada pondasi, kolom, balok, dan rangka kuda-kuda. perbaikan bangunan rumah untuk tinggal sementara Kelebihan Kekurangan 1) Bagi pengungsi mudah |1) Diperlukan waktu untuk menyesuaikan dengan identifikasi perbaikan rumah tempat tinggal tinggal sementara sementaranya. 2) Ketersediaan jenis material 2) Terlibat langsung dalam sesuai kebutuhan perencanaan perbaikan | 3) Masih ada kekhawatiran bagi rumah. pengungsi terhadap 3) Dukungan sarana dan perbaikan sementara rumah prasarana awal yang tinggalnya masih dapat dimanfaatkan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (719, 'c. Perbaikan bangunan rumah untuk tinggal sementara Perbaikan terhadap non-struktural atau bagian lain dari rumah tinggal asal yang terdampak bencana agar dapat ditempati sementara berupa bantuan penyediaan material hunian dan peralatan pertukangan untuk mendukung perbaikan dan/atau jasa untuk perbaikan. Penilaian awal harus dilakukan oleh tenaga yang kompeten dari instansi berwenang sebelum perbaikan bangunan.
Kriteria umum perbaikan non-struktural meliputi:
1) Perbaikan terhadap non-struktur bangunan rumah seperti dinding retak dengan lebar « 6mm/tidak tembus, kaca pecah, genteng terlepas dan plafon lepas.
2) Bangunan masih tegak berdiri dan tidak miring.
3) Tidak ada kerusakan/keretakan pada pondasi, kolom, balok, dan rangka kuda-kuda. perbaikan bangunan rumah untuk tinggal sementara Kelebihan Kekurangan 1) Bagi pengungsi mudah |1) Diperlukan waktu untuk menyesuaikan dengan identifikasi perbaikan rumah tempat tinggal tinggal sementara sementaranya. 2) Ketersediaan jenis material 2) Terlibat langsung dalam sesuai kebutuhan perencanaan perbaikan | 3) Masih ada kekhawatiran bagi rumah. pengungsi terhadap 3) Dukungan sarana dan perbaikan sementara rumah prasarana awal yang tinggalnya masih dapat dimanfaatkan', 'BAB II (lanjutan 10)', 'Petunjuk Pelaksanaan Nomor 3 Tahun 2023 tentang Pemberian Bantuan Hunian Sementara Bagi Pengungsi Korban Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (720, 'juklak-3-2023', 17, 'lain', 'BAB II (lanjutan 11)', NULL, 11, 'd. Pembangunan hunian non permanen baru Membangun bangunan/hunian non permanen baru yang dapat ditinggali sementara, seperti rumah individu/keluarga atau rumah deret. Kriteria umum pembangunan hunian non permanen baru merujuk pada poin A standar teknis bantuan nomor 1 tentang rancang bangun.
11 pembangunan hunian non permanen baru Kelebihan Kekurangan 1) Bagi pengungsi lebih aman, | 1) Kemungkinan potensi nyaman, sehat dan konflik karena komunitas bermartabat baru (asal yang berbeda).
2) Terlibat langsung dalam| 2) Terbatasnya ketersediaan perencanaan pembangunan lahan. huntara 3) Diperlukan waktu yang lama untuk administrasi dan proses pembangunan huntara sampai siap huni. . Pemanfaatan rumah warga yang sudah ada sebagai hunian sementara Rumah warga yang sudah ada dapat dimanfaatkan sebagai Huntara. Penilaian awal harus dilakukan oleh tenaga yang kompeten sebelum pemanfaatan rumah.
Kriteria umum pemanfaatan rumah warga yang sudah ada sebagai hunian sementara meliputi:
1) Penggunaan pemanfaatan rumah sudah memiliki izin guna pakai.
2) Bangunan masih tegak berdiri dan tidak miring.');
