INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (738, 'juklak-3-2023', 35, 'lain', 'BAB IV', NULL, 26, 'PENUTUP Petunjuk Pelaksanaan ini digunakan sebagai rujukan/acuan bagi BNPB, Kementerian/Lembaga, BPBD Provinsi/Kabupaten/Kota dan stakeholder lainnya mengenai pemberian bantuan Huntara bagi korban dan pengungsi akibat bencana.
Apabila dalam Petunjuk Pelaksanaan ini terdapat ketidaksesuaian, maka ini akan dilakukan perubahan atau perbaikan sebagaimana mestinya. Hal-hal yang belum diatur dalam Petunjuk Pelaksanaan ini dilaksanakan sebagaimana mestinya dengan berpedoman pada ketentuan peraturan perundang-undangan.
Ditetapkan di Jakarta pada tanggal 24 Oktober 2023 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA , ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASGNEAB PENANGGULANGAN BENCANA » Oy 73 @rganisasi dan Kerja Sama, to) z | d 4 a Dewi Rismayati 26');
