INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (739, 'juklak-3-2024', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (739, 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024', 'Judul', 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (740, 'juklak-3-2024', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMBERIAN BANTUAN PEMERINTAH LOGISTIK DAN PERALATAN PENANGGULANGAN BENCANA UNTUK KESIAPSIAGAAN NOMOR 3 TAHUN 2024');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (740, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMBERIAN BANTUAN PEMERINTAH LOGISTIK DAN PERALATAN PENANGGULANGAN BENCANA UNTUK KESIAPSIAGAAN NOMOR 3 TAHUN 2024', 'Isi hal. 1', 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (741, 'juklak-3-2024', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN Latar Belakang Berdasarkan ketentuan Peraturan Menteri Keuangan Nomor 168/PMK.05/2015 tentang Mekanisme Pelaksanaan Anggaran Bantuan Pemerintah Pada Kementerian Negara/Lembaga sebagaimana telah diubah dengan Peraturan Menteri Keuangan Nomor 173/PMK.05/2016 tentang perubahan atas Peraturan Menteri Keuangan Nomor 168/PMK.05/2015 tentang Mekanisme Pelaksanaan Anggaran Bantuan Pemerintah Pada Kementerian Negara/ Lembaga, Kementerian Keuangan telah memberikan panduan dalam pelaksanaan pemberian bantuan pemerintah. Menindaklanjuti peraturan tersebut, Badan Nasional Penanggulangan Bencana telah membentuk Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2017 tentang Pedoman Umum Mekanisme Pelaksanaan Anggaran Bantuan Pemerintah Di lingkungan Badan Nasional Penanggulangan Bencana.
Badan Nasional Penanggulangan Bencana sebagai lembaga pemerintah nonkementerian memiliki fungsi koordinator, komando, dan pelaksana dalam penyelenggaraan penanggulangan bencanaa. Melalui Kedeputian Bidang Logistik dan peralatan, sesuai dengan tugas dan fungsinya, penyelenggaraan pemberian bantuan logistik dan peralatan Penanggulangan Bencana dilakukan bedasarkan analisis kebutuhan dan ketersediaan anggaran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (741, 'PENDAHULUAN Latar Belakang Berdasarkan ketentuan Peraturan Menteri Keuangan Nomor 168/PMK.05/2015 tentang Mekanisme Pelaksanaan Anggaran Bantuan Pemerintah Pada Kementerian Negara/Lembaga sebagaimana telah diubah dengan Peraturan Menteri Keuangan Nomor 173/PMK.05/2016 tentang perubahan atas Peraturan Menteri Keuangan Nomor 168/PMK.05/2015 tentang Mekanisme Pelaksanaan Anggaran Bantuan Pemerintah Pada Kementerian Negara/ Lembaga, Kementerian Keuangan telah memberikan panduan dalam pelaksanaan pemberian bantuan pemerintah. Menindaklanjuti peraturan tersebut, Badan Nasional Penanggulangan Bencana telah membentuk Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2017 tentang Pedoman Umum Mekanisme Pelaksanaan Anggaran Bantuan Pemerintah Di lingkungan Badan Nasional Penanggulangan Bencana.
Badan Nasional Penanggulangan Bencana sebagai lembaga pemerintah nonkementerian memiliki fungsi koordinator, komando, dan pelaksana dalam penyelenggaraan penanggulangan bencanaa. Melalui Kedeputian Bidang Logistik dan peralatan, sesuai dengan tugas dan fungsinya, penyelenggaraan pemberian bantuan logistik dan peralatan Penanggulangan Bencana dilakukan bedasarkan analisis kebutuhan dan ketersediaan anggaran.', 'BAB I', 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (742, 'juklak-3-2024', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Penyelenggaraan pemberian bantuan logistik dan peralatan Penanggulangan Bencana merupakan bentuk patisipasi aktif Badan Nasional Penanggulangan Bencana dalam program kesiapsiagaan, yang mana dalam pelaksanaan pemberian bantuan logistik dan peralatan Penanggulangan Bencana tersebut dilakukan melalui langkah yang tepat guna dan berdaya guna. Selain itu, dalam rangka melakukan upaya pencegahan, pengurangan risiko, dan mitigasi bencana dibutuhkan logistik dan peralatan penanggulangan bencana yang memadai.
Berdasarkan hal tersebut perlu disusun petunjuk pelaksanaan pemberian bantuan pemerintah logistik dan peralatan penanggulangan bencana untuk kesiapsiagaan agar penyelenggaraannya dapat berjalan dengan efektif, efisien dan akuntabel.
Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini sebagai panduan pemberian bantuan pemerintah logistik dan peralatan penanggulangan bencana untuk kesiapsiagaan dalam rangka penguatan kelembagaan dan upaya penanggulangan bencana.
2. Tujuan Petunjuk Pelaksanaan ini agar terlaksananya pemberian bantuan pemerintah logistik dan peralatan penanggulangan bencana untuk kesiapsiagaan berjalan secara cepat, tepat, efektif, efisien dan akuntabel.
Ruang Lingkup Ruang Lingkup Petunjuk Pelaksanaan ini mencakup prosedur pemberian bantuan pemerintah logistik dan peralatan penanggulangan bencana untuk kesiapsiagaan.
Pengertian');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (742, 'Penyelenggaraan pemberian bantuan logistik dan peralatan Penanggulangan Bencana merupakan bentuk patisipasi aktif Badan Nasional Penanggulangan Bencana dalam program kesiapsiagaan, yang mana dalam pelaksanaan pemberian bantuan logistik dan peralatan Penanggulangan Bencana tersebut dilakukan melalui langkah yang tepat guna dan berdaya guna. Selain itu, dalam rangka melakukan upaya pencegahan, pengurangan risiko, dan mitigasi bencana dibutuhkan logistik dan peralatan penanggulangan bencana yang memadai.
Berdasarkan hal tersebut perlu disusun petunjuk pelaksanaan pemberian bantuan pemerintah logistik dan peralatan penanggulangan bencana untuk kesiapsiagaan agar penyelenggaraannya dapat berjalan dengan efektif, efisien dan akuntabel.
Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini sebagai panduan pemberian bantuan pemerintah logistik dan peralatan penanggulangan bencana untuk kesiapsiagaan dalam rangka penguatan kelembagaan dan upaya penanggulangan bencana.
2. Tujuan Petunjuk Pelaksanaan ini agar terlaksananya pemberian bantuan pemerintah logistik dan peralatan penanggulangan bencana untuk kesiapsiagaan berjalan secara cepat, tepat, efektif, efisien dan akuntabel.
Ruang Lingkup Ruang Lingkup Petunjuk Pelaksanaan ini mencakup prosedur pemberian bantuan pemerintah logistik dan peralatan penanggulangan bencana untuk kesiapsiagaan.
Pengertian', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (743, 'juklak-3-2024', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, '1. Kuasa Pengguna Anggaran yang selanjutnya disingkat KPA adalah pejabat yang ditunjuk oleh Pengguna Anggaran untuk melaksanakan sebagian kewenangan dan tanggung jawab penggunaan anggaran
2. Logistik adalah barang untuk pemenuhan kebutuhan dasar seperti pangan, sandang, papan dan turunannya dalam rangka penanggulangan bencana.
3. Peralatan adalah segala bentuk alat yang dapat dipergunakan untuk melakukan, pencarian, penyelamatan dan evakuasi masyarakat terdampak bencana, membantu pemenuhan kebutuhan dasar untuk pemulihan segera sarana dan prasarana vital.
4. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB, adalah lembaga pemerintah non-departemen sesuai dengan ketentuan peraturan perundang-undangan.
5. Badan Penanggulangan Bencana Daerah, yang selanjutnya disingkat BPBD, adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (743, '1. Kuasa Pengguna Anggaran yang selanjutnya disingkat KPA adalah pejabat yang ditunjuk oleh Pengguna Anggaran untuk melaksanakan sebagian kewenangan dan tanggung jawab penggunaan anggaran
2. Logistik adalah barang untuk pemenuhan kebutuhan dasar seperti pangan, sandang, papan dan turunannya dalam rangka penanggulangan bencana.
3. Peralatan adalah segala bentuk alat yang dapat dipergunakan untuk melakukan, pencarian, penyelamatan dan evakuasi masyarakat terdampak bencana, membantu pemenuhan kebutuhan dasar untuk pemulihan segera sarana dan prasarana vital.
4. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB, adalah lembaga pemerintah non-departemen sesuai dengan ketentuan peraturan perundang-undangan.
5. Badan Penanggulangan Bencana Daerah, yang selanjutnya disingkat BPBD, adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (744, 'juklak-3-2024', 5, 'lain', 'BAB II', NULL, 3, 'PELAKSANAAN Pemberian Bantuan Pemerintah dan Sumber Pendanaan Bantuan pemerintah dalam bentuk Logistik dan peralatan penanggulangan bencana untuk kesiapsiagaan diberikan oleh BNPB.
Pemberian Bantuan Logistik dan Peralatan ini dilaksanakan oleh Deputi Bidang Logistik dan Peralatan melalui program dan kegiatan bantuan pemerintah.
Bantuan Logistik dan Peralatan dapat dialokasikan untuk keperluan buffer stock minimal sepuluh persen (1096) dari jumlah pengadaan.
Alokasi tersebut dipergunakan untuk tujuan pemberian bantuan pemerintah dalam rangka mengantisipasi kejadian bencana.
Sumber dana pengadaan Bantuan Logistik dan Peralatan penanggulangan bencana berasal dari Anggaran Pendapatan dan Belanja Negara yang dituangkan pada daftar isian pelaksanaan anggaran BNPB yang dialokasikan pada Deputi Bidang Logistik dan Peralatan.
Persyaratan Penerima Bantuan Pemerintah Penerima bantuan pemerintah Logistik dan Peralatan penanggulangan untuk kesiapsiagaan terdiri atas:
a. BPBD/perangkat daerah yang terlibat dalam penyelenggaraan penanggulangan bencana,
b. kementerian/lembaga,
c. lembaga sosial, lembaga budaya, lembaga keagamaan, lembaga kemanusiaan, atau lembaga pendidikan yang bersifat non komersial: dan
d. pemerintah negara lain dalam kerangka hubungan internasional.
Secara umum, persyaratan penerima bantuan pemerintah bidang penanggulangan bencana sangat tergantung pada aspek lokasi dan ketersediaan prasarana di daerah. Calon penerima bantuan wajib memenuhi ketentuan:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (744, 'PELAKSANAAN Pemberian Bantuan Pemerintah dan Sumber Pendanaan Bantuan pemerintah dalam bentuk Logistik dan peralatan penanggulangan bencana untuk kesiapsiagaan diberikan oleh BNPB.
Pemberian Bantuan Logistik dan Peralatan ini dilaksanakan oleh Deputi Bidang Logistik dan Peralatan melalui program dan kegiatan bantuan pemerintah.
Bantuan Logistik dan Peralatan dapat dialokasikan untuk keperluan buffer stock minimal sepuluh persen (1096) dari jumlah pengadaan.
Alokasi tersebut dipergunakan untuk tujuan pemberian bantuan pemerintah dalam rangka mengantisipasi kejadian bencana.
Sumber dana pengadaan Bantuan Logistik dan Peralatan penanggulangan bencana berasal dari Anggaran Pendapatan dan Belanja Negara yang dituangkan pada daftar isian pelaksanaan anggaran BNPB yang dialokasikan pada Deputi Bidang Logistik dan Peralatan.
Persyaratan Penerima Bantuan Pemerintah Penerima bantuan pemerintah Logistik dan Peralatan penanggulangan untuk kesiapsiagaan terdiri atas:
a. BPBD/perangkat daerah yang terlibat dalam penyelenggaraan penanggulangan bencana,
b. kementerian/lembaga,
c. lembaga sosial, lembaga budaya, lembaga keagamaan, lembaga kemanusiaan, atau lembaga pendidikan yang bersifat non komersial: dan
d. pemerintah negara lain dalam kerangka hubungan internasional.
Secara umum, persyaratan penerima bantuan pemerintah bidang penanggulangan bencana sangat tergantung pada aspek lokasi dan ketersediaan prasarana di daerah. Calon penerima bantuan wajib memenuhi ketentuan:', 'BAB II', 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (745, 'juklak-3-2024', 6, 'lain', 'BAB II (lanjutan 1)', NULL, 3, '1. Lolos persyaratan administrasi permohonan bantuan Logistik dan Peralatan dan mengirimkan surat pernyataan bersedia menerima hibah kepada BNPB. Format Surat Pernyataan Bersedia Menerima Hibah tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini,
2. Bagi BPBD yang baru terbentuk akan mendapatkan bantuan Logistik dan Peralatan penanggulangan bencana sesuai dengan skala prioritas dan ketersediaan anggaran Deputi Bidang Logistik dan Peralatan,
3. Prioritas sebagaimana dimaksud di atas dilakukan dengan penilaian terhadap:
a. Kelembagaan BPBD,
b. Indeks Risiko Bencana:
c. Kesesuaian karakteristik wilayah bencana,
d. Jenis ancaman bencana,
e. Program prioritas pembangunan nasional, fl. Anggaran dan Sumber Daya Penerima Bantuan, dan
g. Analisis strategis berdasarkan kebijakan situasi dan kondisi sehingga harus diberikan bantuan Logistik dan Peralatan.
4 Adapun pemberian bantuan pemerintah Logistik dan Peralatan penanggulangan bencana untuk kesiapsiagaan meliputi beberapa tahapan:
1. Perencanaan Perencanaan bantuan Logistik dan Peralatan penanggulangan bencana untuk kesiapsiagaan diawali dari pengumpulan data: analisis kebutuhan, dan inisiatif pemerintah/BNPB berdasarkan analisa kebutuhan Logistik dan Peralatan PB.
a. Pengumpulan Data Pengumpulan data dilakukan melalui kegiatan:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (745, '1. Lolos persyaratan administrasi permohonan bantuan Logistik dan Peralatan dan mengirimkan surat pernyataan bersedia menerima hibah kepada BNPB. Format Surat Pernyataan Bersedia Menerima Hibah tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini,
2. Bagi BPBD yang baru terbentuk akan mendapatkan bantuan Logistik dan Peralatan penanggulangan bencana sesuai dengan skala prioritas dan ketersediaan anggaran Deputi Bidang Logistik dan Peralatan,
3. Prioritas sebagaimana dimaksud di atas dilakukan dengan penilaian terhadap:
a. Kelembagaan BPBD,
b. Indeks Risiko Bencana:
c. Kesesuaian karakteristik wilayah bencana,
d. Jenis ancaman bencana,
e. Program prioritas pembangunan nasional, fl. Anggaran dan Sumber Daya Penerima Bantuan, dan
g. Analisis strategis berdasarkan kebijakan situasi dan kondisi sehingga harus diberikan bantuan Logistik dan Peralatan.
4 Adapun pemberian bantuan pemerintah Logistik dan Peralatan penanggulangan bencana untuk kesiapsiagaan meliputi beberapa tahapan:
1. Perencanaan Perencanaan bantuan Logistik dan Peralatan penanggulangan bencana untuk kesiapsiagaan diawali dari pengumpulan data: analisis kebutuhan, dan inisiatif pemerintah/BNPB berdasarkan analisa kebutuhan Logistik dan Peralatan PB.
a. Pengumpulan Data Pengumpulan data dilakukan melalui kegiatan:', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (746, 'juklak-3-2024', 7, 'lain', 'BAB II (lanjutan 2)', NULL, 4, '1) Inventarisasi ketersediaan dan kebutuhan baik ditingkat pusat maupun daerah melalui pertemuan dengan BPBD Provinsi/ Kabupaten/Kota, 2) Rekapitulasi permohonan kebutuhan Logistik dan Peralatan Penanggulangan Bencana yang disampaikan oleh BPBD Provinsi/ Kabupaten/Kota dengan persyaratan sebagai berikut: a) Telah dibentuk BPBD yang didukung dengan Peraturan Daerah: b) Permintaan bantuan Logistik dan Peralatan dari BPBD Provinsi ditandatangani serendah-rendahnya oleh Sekretaris Daerah yang ditujukan kepada Kepala BNPB cg. Deputi Bidang Logistik dan Peralatan dengan melampirkan rekomendasi dari Gubernur/Wakil Gubernur/ Sekretaris Daerah an.
Gubernur, c) Sedangkan permintaan bantuan Logistik dan Peralatan dari BPBD Kabupaten/Kota ditandatangani oleh Kepala Daerah yang ditujukan kepada Kepala BNPB cg. Deputi Bidang Logistik dan Peralatan dengan melampirkan rekomendasi dari Gubernur, d) Mengajukan proposal yang memuat informasi tentang:
(1) karakteristik wilayah,
(2) informasi BPBD yang mencakup ketersediaan Sumber Daya Manusia, Logistik dan Peralatan, ketersediaan anggaran untuk operasional, pemeliharaan serta ketersediaan sarana dan prasarana pendukung seperti kantor, gudang, garasi, dan dermaga,
(3) informasi frekuensi kejadian bencana minimal kurun waktu 1 (satu) tahun sebelumnya,
(4) data ketersediaan Logistik dan Peralatan di BPBD Intstansi terkait dan swasta di wilayah pemohon proposal bantuan, dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (746, '1) Inventarisasi ketersediaan dan kebutuhan baik ditingkat pusat maupun daerah melalui pertemuan dengan BPBD Provinsi/ Kabupaten/Kota, 2) Rekapitulasi permohonan kebutuhan Logistik dan Peralatan Penanggulangan Bencana yang disampaikan oleh BPBD Provinsi/ Kabupaten/Kota dengan persyaratan sebagai berikut: a) Telah dibentuk BPBD yang didukung dengan Peraturan Daerah: b) Permintaan bantuan Logistik dan Peralatan dari BPBD Provinsi ditandatangani serendah-rendahnya oleh Sekretaris Daerah yang ditujukan kepada Kepala BNPB cg. Deputi Bidang Logistik dan Peralatan dengan melampirkan rekomendasi dari Gubernur/Wakil Gubernur/ Sekretaris Daerah an.
Gubernur, c) Sedangkan permintaan bantuan Logistik dan Peralatan dari BPBD Kabupaten/Kota ditandatangani oleh Kepala Daerah yang ditujukan kepada Kepala BNPB cg. Deputi Bidang Logistik dan Peralatan dengan melampirkan rekomendasi dari Gubernur, d) Mengajukan proposal yang memuat informasi tentang:
(1) karakteristik wilayah,
(2) informasi BPBD yang mencakup ketersediaan Sumber Daya Manusia, Logistik dan Peralatan, ketersediaan anggaran untuk operasional, pemeliharaan serta ketersediaan sarana dan prasarana pendukung seperti kantor, gudang, garasi, dan dermaga,
(3) informasi frekuensi kejadian bencana minimal kurun waktu 1 (satu) tahun sebelumnya,
(4) data ketersediaan Logistik dan Peralatan di BPBD Intstansi terkait dan swasta di wilayah pemohon proposal bantuan, dan', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (747, 'juklak-3-2024', 8, 'lain', 'BAB II (lanjutan 3)', NULL, 4, '(5) jenis, jumlah, dan spesifikasi Logistik dan Peralatan yang diperlukan sesuai dengan kondisi daerah.
b. Analisis Kebutuhan 0 Hasil pengumpulan data kebutuhan dilakukan analisis untuk mendapatkan data antara lain: jenis, jumlah, dan spesifikasi teknis Logistik dan Peralatan untuk bahan usulan rencana kerja dan anggaran.
Analisis kebutuhan dilakukan melalui kegiatan antara lain:
1) membandingkan antara data kebutuhan dan ketersediaan Logistik dan Peralatan, 2) penilaian kebutuhan melalui rapat koordinasi, dan 3) penentuan skala prioritas berdasarkan ketersediaan anggaran pada Deputi Bidang Logistik dan Peralatan.
c. Inisiatif BNPB berdasarkan analisa kebutuhan Logistik dan Peralatan PB.
Dalam perencanaan kebutuhan selain berdasarkan analisa yang tersedia berdasarkan pengajuan permohonan dan inventarisasi kebutuhan, dapat juga melalui inisiatif pemerintah dalam upaya penanggulangan bencana berdasarkan hasil kajian/ pembahasan.
2. Penetapan Penerima Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana untuk kesiapsiagaan Penerima bantuan pemerintah Logistik dan Peralatan Penanggulangan Bencana untuk kesiapsiagaan ditetapkan atas dasar hasil identifikasi calon penerima bantuan Logistik dan Peralatan melalui Keputusan Deputi Bidang Logistik dan Peralatan.
Keputusan tersebut paling sedikit memuat jenis, jumlah, dan lokasi penerima Logistik dan Peralatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (747, '(5) jenis, jumlah, dan spesifikasi Logistik dan Peralatan yang diperlukan sesuai dengan kondisi daerah.
b. Analisis Kebutuhan 0 Hasil pengumpulan data kebutuhan dilakukan analisis untuk mendapatkan data antara lain: jenis, jumlah, dan spesifikasi teknis Logistik dan Peralatan untuk bahan usulan rencana kerja dan anggaran.
Analisis kebutuhan dilakukan melalui kegiatan antara lain:
1) membandingkan antara data kebutuhan dan ketersediaan Logistik dan Peralatan, 2) penilaian kebutuhan melalui rapat koordinasi, dan 3) penentuan skala prioritas berdasarkan ketersediaan anggaran pada Deputi Bidang Logistik dan Peralatan.
c. Inisiatif BNPB berdasarkan analisa kebutuhan Logistik dan Peralatan PB.
Dalam perencanaan kebutuhan selain berdasarkan analisa yang tersedia berdasarkan pengajuan permohonan dan inventarisasi kebutuhan, dapat juga melalui inisiatif pemerintah dalam upaya penanggulangan bencana berdasarkan hasil kajian/ pembahasan.
2. Penetapan Penerima Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana untuk kesiapsiagaan Penerima bantuan pemerintah Logistik dan Peralatan Penanggulangan Bencana untuk kesiapsiagaan ditetapkan atas dasar hasil identifikasi calon penerima bantuan Logistik dan Peralatan melalui Keputusan Deputi Bidang Logistik dan Peralatan.
Keputusan tersebut paling sedikit memuat jenis, jumlah, dan lokasi penerima Logistik dan Peralatan.', 'BAB II (lanjutan 3)', 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (748, 'juklak-3-2024', 9, 'lain', 'BAB II (lanjutan 4)', NULL, 5, '3. Penyaluran Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana untuk kesiapsiagaan Penyaluran bantuan Logistik dan Peralatan Penanggulangan Bencana dilakukan melalui mekanisme hibah dengan cara mengajukan kepada KPA. Ketentuan dalam penyaluran bantuan Logistik dan Peralatan Penanggulangan Bencana adalah sebagai berikut:
a. proses hibah wajib dilakukan oleh unit pemberi bantuan Logistik dan Peralatan dengan berdasarkan Surat Persetujuan Hibah dari Pengguna Barang/ Kuasa Pengguna Barang berdasarkan aturan yang berlaku,
b. biaya distribusi bantuan Logistik dan Peralatan dibebankan pada Anggaran Pendapatan dan Belanja Negara dan Anggaran Pendapatan dan Belanja Daerah, dan
c. alokasi Logistik dan Peralatan yang dijadikan buffer stock harus diberikan kepada daerah yang telah ditentukan dalam Keputusan.
Format Perjanjian Hibah Barang Milik Negara tercantum dalam Lampiran III yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
Bentuk Bantuan Pemerintah Bantuan pemerintah diberikan oleh Badan Nasional Penanggulangan Bencana dalam bentuk Logistik dan Peralatan penanggulangan bencana.
Dalam upaya penguatan kelembagaan dapat diberikan bantuan dalam bentuk sarana dan prasarana melalui penyediaan Peralatan kebencanaan. Melalui bantuan pemerintah tersebut, diharapkan standar minimal sarana penanggulangan bencana yang dimiliki pemerintah daerah dapat terpenuhi sehingga mampu mendukung petugas dalam penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (748, '3. Penyaluran Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana untuk kesiapsiagaan Penyaluran bantuan Logistik dan Peralatan Penanggulangan Bencana dilakukan melalui mekanisme hibah dengan cara mengajukan kepada KPA. Ketentuan dalam penyaluran bantuan Logistik dan Peralatan Penanggulangan Bencana adalah sebagai berikut:
a. proses hibah wajib dilakukan oleh unit pemberi bantuan Logistik dan Peralatan dengan berdasarkan Surat Persetujuan Hibah dari Pengguna Barang/ Kuasa Pengguna Barang berdasarkan aturan yang berlaku,
b. biaya distribusi bantuan Logistik dan Peralatan dibebankan pada Anggaran Pendapatan dan Belanja Negara dan Anggaran Pendapatan dan Belanja Daerah, dan
c. alokasi Logistik dan Peralatan yang dijadikan buffer stock harus diberikan kepada daerah yang telah ditentukan dalam Keputusan.
Format Perjanjian Hibah Barang Milik Negara tercantum dalam Lampiran III yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
Bentuk Bantuan Pemerintah Bantuan pemerintah diberikan oleh Badan Nasional Penanggulangan Bencana dalam bentuk Logistik dan Peralatan penanggulangan bencana.
Dalam upaya penguatan kelembagaan dapat diberikan bantuan dalam bentuk sarana dan prasarana melalui penyediaan Peralatan kebencanaan. Melalui bantuan pemerintah tersebut, diharapkan standar minimal sarana penanggulangan bencana yang dimiliki pemerintah daerah dapat terpenuhi sehingga mampu mendukung petugas dalam penanggulangan bencana.', 'BAB II (lanjutan 4)', 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (749, 'juklak-3-2024', 10, 'lain', 'BAB II (lanjutan 5)', NULL, 6, 'Jenis bantuan pemerintah dapat ditetapkan melalui keputusan sekretaris utama selaku KPA setiap tahun anggaran.
Rincian Jumlah Bantuan Pemerintah Bantuan Pemerintah yang dikelola oleh Deputi Bidang Logistik dan Peralatan Badan Nasional Penanggulangan Bencana ditetapkan secara berkala setiap tahun anggaran.
Tata Kelola Pencairan Bantuan Pemerintah Pencairan bantuan pemerintah yang berupa dana dan bantuan lainnya yang memiliki karakteristik bantuan pemerintah yang ditetapkan oleh Pengguna Anggaran dalam rangka pengadaan barang/jasa yang akan disalurkan untuk penerima bantuan pemerintah dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
Terkait pemberian bantuan pemerintah Logistik dan peralatan penanggulangan bencana untuk kesiapsiagaan, Deputi Bidang Logistik dan Peralatan tidak memberikan bantuan berupa uang.
Pertanggungjawaban Bantuan Pemerintah Deputi Bidang Logistik dan Peralatan selaku pelaksana program bantuan pemerintah membuat laporan pelaksanaan kegiatan yang menggambarkan proses pelaksanaan bantuan dari perencanaan, Pengadaan, Penyimpanan, Distribusi hingga berakhirnya pelaksanaan bantuan sebagai bentuk pertanggungjawaban kepada KPA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (749, 'Jenis bantuan pemerintah dapat ditetapkan melalui keputusan sekretaris utama selaku KPA setiap tahun anggaran.
Rincian Jumlah Bantuan Pemerintah Bantuan Pemerintah yang dikelola oleh Deputi Bidang Logistik dan Peralatan Badan Nasional Penanggulangan Bencana ditetapkan secara berkala setiap tahun anggaran.
Tata Kelola Pencairan Bantuan Pemerintah Pencairan bantuan pemerintah yang berupa dana dan bantuan lainnya yang memiliki karakteristik bantuan pemerintah yang ditetapkan oleh Pengguna Anggaran dalam rangka pengadaan barang/jasa yang akan disalurkan untuk penerima bantuan pemerintah dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
Terkait pemberian bantuan pemerintah Logistik dan peralatan penanggulangan bencana untuk kesiapsiagaan, Deputi Bidang Logistik dan Peralatan tidak memberikan bantuan berupa uang.
Pertanggungjawaban Bantuan Pemerintah Deputi Bidang Logistik dan Peralatan selaku pelaksana program bantuan pemerintah membuat laporan pelaksanaan kegiatan yang menggambarkan proses pelaksanaan bantuan dari perencanaan, Pengadaan, Penyimpanan, Distribusi hingga berakhirnya pelaksanaan bantuan sebagai bentuk pertanggungjawaban kepada KPA.', 'BAB II (lanjutan 5)', 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (750, 'juklak-3-2024', 11, 'lain', 'BAB II (lanjutan 6)', NULL, 6, 'Setelah pekerjaan selesai, maka diperlukan adanya Berita Acara Serah Terima Barang Milik Negara (BAST) yang ditandatangani oleh Kepala Pelaksana BPBD provinsi/kabupaten/kota dan disertai dokumentasi pelaksanaan kegiatan. Format Berita Acara Serah Terima Barang Milik Negara tercantum dalam Lampiran II yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
Deputi Bidang Logistik dan Peralatan melakukan pencatatan/pembukuan bukti serah terima barang. Pemerintah daerah selaku penerima bantuan pemerintah wajib melakukan:
a. pencatatan/pembukuan secara sederhana atas barang yang diterima
b. membuat laporan penggunaan barang kepada Deputi Bidang Logistik dan Peralatan.
Ketentuan Perpajakan Ketentuan perpajakan dalam penggunaan dana bantuan pemerintah dilaksanakan sesuai dengan peraturan perundang-undangan tentang perpajakan. Deputi Bidang Logistik dan Peralatan memiliki program dan kegiatan bantuan pemerintah tidak melakukan pemungutan pajak pada saat pemberian bantuan kepada lembaga penerima bantuan pemerintah.
Pemungutan pajak adalah tanggung jawab penerima bantuan sebagai unit pengelola keuangan dan kegiatan.
Sanksi Penerima bantuan pemerintah wajib melaksanakan pengelolaan barang dan kegiatan sesuai petunjuk pelaksanaan. Bagi yang tidak melaksanakan kegiatan sesuai dengan petunjuk pelaksanaan ini dikenai sanksi akan dipertimbangkan untuk tidak mendapatkan atau menerima program bantuan pemerintah pada tahun anggaran berikutnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (750, 'Setelah pekerjaan selesai, maka diperlukan adanya Berita Acara Serah Terima Barang Milik Negara (BAST) yang ditandatangani oleh Kepala Pelaksana BPBD provinsi/kabupaten/kota dan disertai dokumentasi pelaksanaan kegiatan. Format Berita Acara Serah Terima Barang Milik Negara tercantum dalam Lampiran II yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
