Sanksi Penerima bantuan pemerintah wajib melaksanakan pengelolaan barang dan kegiatan sesuai petunjuk pelaksanaan. Bagi yang tidak melaksanakan kegiatan sesuai dengan petunjuk pelaksanaan ini dikenai sanksi akan dipertimbangkan untuk tidak mendapatkan atau menerima program bantuan pemerintah pada tahun anggaran berikutnya.', 'BAB II (lanjutan 6)', 'Petunjuk Pelaksanaan Pemberian Bantuan Pemerintah Logistik dan Peralatan Penanggulangan Bencana Untuk Kesiapsiagaan Nomor 3 Tahun 2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (751, 'juklak-3-2024', 12, 'lain', 'BAB III', NULL, 8, 'PENUTUP Petunjuk pelaksanaan ini dapat dijadikan acuan dalam pemberian bantuan pemerintah Logistik dan Peralatan penanggulangan bencana untuk kesiasiagaan dengan harapan penanganan administrasi tercipta lebih tertib, efektif, dan efesien, sehingga dapat terselanggaranya penanggulangan bencana dengan baik.
Ditetapkan di Jakarta pada tanggal 21 Maret 2024 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (751, 'PENUTUP Petunjuk pelaksanaan ini dapat dijadikan acuan dalam pemberian bantuan pemerintah Logistik dan Peralatan penanggulangan bencana untuk kesiasiagaan dengan harapan penanganan administrasi tercipta lebih tertib, efektif, dan efesien, sehingga dapat terselanggaranya penanggulangan bencana dengan baik.
