INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (754, 'juklak-3-2024', 15, 'lain', 'KEDUA menerima penyerahan dari PIHAK PERTAMA, Barang Milik', NULL, 11, 'Negara selain tanah dan/atau bangunan dengan rincian sebagaimana terlampir dalam lampiran Berita Acara Serah Terima Ini:
2. Penyerahan ini dilakukan dalam rangka hibah dari Badan Nasional Penanggulangan Bencana kepada Badan Penaggulangan Bencana Daerah Provinsi/Kabupaten/Kota ..... sesuai Surat Sekretaris Utama Selaku Kuasa Pengguna Barang Nomor .......... tentang Persetujuan Hibah Barang Milik Negara selain tanah dan/atau Bangunan Pada Deputi Bidang Logistik dan Peralatan dan Naskah Perjanjian Hibah antara Badan Nasional Penanggulangan Bencana dengan Badan Penanggulangan Bencana Daerah Nomor ...... tanggal........... :
3. Terhitung sejak penandatanganan Berita Acara Serah Terima ini, maka seluruh hak dan kewajiban, tanggungjawab, dan kepemilikan terhadap Barang Milik Negara sebagaimana dimaksud dalam angka 1 beralih dari PIHAK PERTAMA ke PIHAK KEDUA,
4. Apabila dikemudian hari ternyata terdapat kekeliruan dalam Berita Acara Serah Terima ini, akan diadakan perbaikan sebagaimana mestinya.
Demikian Berita Acara Serah Terima ini dibuat untuk dipergunakan Dibuat di Jakarta, sebagaimana mestinya.
PIHAK PERTAMA PIHAK KEDUA SEKRETARIS UTAMA SELAKU KUASA PENGGUNA BARANG (Deputi Bidang Logisiik dan (Kepala Pelaksana BPBD Peralatan) Provinsi/ Kabuapten/Kota) MENGETAHUI, KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA');
