INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (755, 'juklak-3-2024', 16, 'lampiran', 'LAMPIRAN III', NULL, 13, 'PETUNJUK PELAKSANAAN PEMBERIAN BANTUAN LOGISTIK DAN PERALATAN PENANGGULANAN BENCANA UNTUK KESIAPSIAGAAN NOMOR 3 TAHUN 2024 FORMAT NASKAH PERJANJIAN HIBAH NASKAH PERJANJIAN HIBAH ANTARA BADAN NASIONAL PENANGGULANGAN BENCANA DENGAN BADAN PENANGGULANGAN BENCANA DAERAH PROVINSI/ KABUPATEN/KOTA .......
TENTANG HIBAH BARANG MILIK NEGARA BERUPA SELAIN TANAH DAN/ATAU BANGUNAN PADA BADAN NASIONAL PENANGGULANGAN BENCANA KEPADA BADAN PENANGGULANGAN BENCANA DAERAH PROVINSI/ KABUPATEN/KOTA .......
Pada hari ini ..... , tanggal .... bulan .... tahun ...., bertempat di Jakarta, yang bertanda tangan di bawah ini: senam dalam jabatannya sebagai Sekretaris Utama, Badan Nasional Penanggulangan Bencana Selaku Kuasa Pengguna Barang, beralamat di Jalan Pramuka Raya Kav. 38 Jakarta Timur, dalam hal ini bertindak untuk dan atas nama Kepala Badan Nasional Penanggulangan Bencana, yang memberikan hibah dan untuk selanjutnya disebut sebagai PIHAK I, sannawsnma dalam jabatannya sebagai Kepala Pelaksana Badan Penanggulangan Bencana Daerah Provinsi/Kabupaten/Kota beralamat di ...... dalam hal ini bertindak untuk dan atas nama Pemerintah Gubernur/Bupati/Walikota ....... , yang menerima hibah dan untuk selanjutnya disebut sebagai PIHAK II.
Memperhatikan:
1. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 70, Tambahan Lembaran Negara Republik Indonesia Nomor 4355),');
