INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (757, '9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2010 tentang Pedoman Distribusi Logistik dan Peralatan Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 1554),
