INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (792, 'juklak-3-2025', 28, 'lampiran', 'LAMPIRAN (lanjutan 10)', NULL, 20, '5) Pertimbangan dilakukan sejak penelaahan, paling lambat 10 (sepuluh) hari kerja sejak tanggal verifikasi keluar;
6) Hasil telaahan, verifikasi, evaluasi, dan pertimbangan ditetapkan oleh Kepala BNPB dalam bentuk rekomendasi penyaluran Dana Bersama dan disampaikan oleh Kepala BNPB kepada para pemohon;
