INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (794, 'juklak-3-2025', 30, 'lampiran', 'LAMPIRAN (lanjutan 12)', NULL, 22, 'Sesuai Nota Dinas Deputi ............... Nomor ……. tanggal ……. 20XX perihal ……. yang data lengkapnya diterima tanggal ……, berikut disampaikan hasil reviu terhadap Permohonan Penyaluran Dana Bersama Penanggulangan Bencana pada …… Tahun 20XX atas …… kegiatan pada …… sebesar Rp…….,00, adalah sebagai berikut:
