INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (796, 'juklak-4-2023', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Penilaian Awal Nomor 4 Tahun 2023');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (796, 'Petunjuk Pelaksanaan Penilaian Awal Nomor 4 Tahun 2023', 'Judul', 'Petunjuk Pelaksanaan Penilaian Awal Nomor 4 Tahun 2023');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (797, 'juklak-4-2023', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PENILAIAN AWAL NOMOR 4 TAHUN 2023');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (797, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PENILAIAN AWAL NOMOR 4 TAHUN 2023', 'Isi hal. 1', 'Petunjuk Pelaksanaan Penilaian Awal Nomor 4 Tahun 2023');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (798, 'juklak-4-2023', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN Latar Belakang Keberhasilan dalam merespons setiap keadaan darurat bencana bergantung pada ketersediaan informasi yang dapat dijadikan masukan dalam menentukan tindakan lebih lanjut. Ketersediaan informasi ini tentunya dapat dimulai dari masyarakat, relawan, dan petugas lokal yang berada di lokasi terdampak. Sesuai dengan ketentuan Pasal 27 huruf b dan huruf c Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, bahwa kewajiban masyarakat adalah melakukan kegiatan penanggulangan bencana dan memberikan informasi yang benar kepada publik tentang penanggulangan bencana.
Dalam rangka mendapatkan informasi ini dibutuhkan penilaian awal terhadap ancaman maupun kejadian bencana. Penilaian awal ini merupakan kegiatan yang diarahkan untuk mengumpulkan informasi awal dari lokasi terancam maupun terdampak yang diperlukan pemerintah kabupaten/kota dalam melakukan kegiatan pengkajian cepat situasi dan kebutuhan terkait keadaan darurat bencana yang dilakukan oleh Tim Reaksi Cepat Penanggulangan Bencana (TRC PB) multisektor.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (798, 'PENDAHULUAN Latar Belakang Keberhasilan dalam merespons setiap keadaan darurat bencana bergantung pada ketersediaan informasi yang dapat dijadikan masukan dalam menentukan tindakan lebih lanjut. Ketersediaan informasi ini tentunya dapat dimulai dari masyarakat, relawan, dan petugas lokal yang berada di lokasi terdampak. Sesuai dengan ketentuan Pasal 27 huruf b dan huruf c Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, bahwa kewajiban masyarakat adalah melakukan kegiatan penanggulangan bencana dan memberikan informasi yang benar kepada publik tentang penanggulangan bencana.
Dalam rangka mendapatkan informasi ini dibutuhkan penilaian awal terhadap ancaman maupun kejadian bencana. Penilaian awal ini merupakan kegiatan yang diarahkan untuk mengumpulkan informasi awal dari lokasi terancam maupun terdampak yang diperlukan pemerintah kabupaten/kota dalam melakukan kegiatan pengkajian cepat situasi dan kebutuhan terkait keadaan darurat bencana yang dilakukan oleh Tim Reaksi Cepat Penanggulangan Bencana (TRC PB) multisektor.', 'BAB I', 'Petunjuk Pelaksanaan Penilaian Awal Nomor 4 Tahun 2023');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (799, 'juklak-4-2023', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Agar penilaian awal dapat berjalan dengan baik dan terstandar, dibutuhkan suatu petunjuk pelaksanaan. Petunjuk pelaksanaan yang ditetapkan, diharapkan dapat menjadi acuan bagi masyarakat, relawan, dan petugas lokal didalam menyiapkan informasi pada saat awal diketahuinya tanda-tanda terjadi bencana atau kejadian ancaman yang mengarah ke situasi bencana melalui kegiatan penilaian awal. Informasi dimaksud sangat berguna sebagai bahan masukan bagi TRC PB multisektor di tingkat kabupaten/kota dalam melakukan kegiatan pengkajian cepat situasi dan kebutuhan sebagaimana telah kita atur dalam Petunjuk Pelaksanaan yang terpisah, yaitu Petunjuk Pelaksanaan Pengkajian Cepat Kebutuhan Pada Keadaan Darurat Bencana Nomor 3 Tahun 2022.
Dalam pelaksanaan penilaian awal, yang dapat menjadi dasar hukum antara lain:
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah.
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
4. Peraturan Pemerintah Nomor 2 Tahun 2018 tentang Standar Pelayanan Minimal.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (799, 'Agar penilaian awal dapat berjalan dengan baik dan terstandar, dibutuhkan suatu petunjuk pelaksanaan. Petunjuk pelaksanaan yang ditetapkan, diharapkan dapat menjadi acuan bagi masyarakat, relawan, dan petugas lokal didalam menyiapkan informasi pada saat awal diketahuinya tanda-tanda terjadi bencana atau kejadian ancaman yang mengarah ke situasi bencana melalui kegiatan penilaian awal. Informasi dimaksud sangat berguna sebagai bahan masukan bagi TRC PB multisektor di tingkat kabupaten/kota dalam melakukan kegiatan pengkajian cepat situasi dan kebutuhan sebagaimana telah kita atur dalam Petunjuk Pelaksanaan yang terpisah, yaitu Petunjuk Pelaksanaan Pengkajian Cepat Kebutuhan Pada Keadaan Darurat Bencana Nomor 3 Tahun 2022.
Dalam pelaksanaan penilaian awal, yang dapat menjadi dasar hukum antara lain:
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah.
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
4. Peraturan Pemerintah Nomor 2 Tahun 2018 tentang Standar Pelayanan Minimal.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Penilaian Awal Nomor 4 Tahun 2023');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (800, 'juklak-4-2023', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, 'S. Peraturan Menteri Dalam Negeri Nomor 101 Tahun 2018 tentang Standar Teknis Pelayanan Dasar pada Standar Pelayanan Minimal Sub Urusan Bencana Daerah Kabupaten/Kota Atas dasar hal tersebut di atas, maka perlu disusunlah Petunjuk Pelaksanaan Penilaian Awal untuk masyarakat, relawan, dan petugas lokal dalam rangka menyusun dan menyampaikan informasi awal terkait kejadian bencana keadaan darurat bencana.
Maksud dan Tujuan
1. Maksud Petunjuk pelaksanaan ini dimaksudkan untuk memberikan panduan bagi masyarakat, relawan, dan petugas lokal dalam menyampaikan informasi awal terkait keadaan darurat bencana melalui kegiatan penilaian awal.
2. Tujuan Petunjuk Pelaksanaan ini bertujuan untuk mendapatkan informasi awal kejadian bencana sebagai bahan masukan pelaksanaan pengkajian cepat situasi dan kebutuhan Ruang Lingkup Ruang lingkup petunjuk pelaksanaan penilaian awal adalah sebagai berikut:
1. prosedur penyampaian informasi awal kejadian bencana: dan
2. proses pengelolaan data dalam rangka penyiapan informasi.
Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan baik oleh faktor alam, faktor non-alam, maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (800, 'S. Peraturan Menteri Dalam Negeri Nomor 101 Tahun 2018 tentang Standar Teknis Pelayanan Dasar pada Standar Pelayanan Minimal Sub Urusan Bencana Daerah Kabupaten/Kota Atas dasar hal tersebut di atas, maka perlu disusunlah Petunjuk Pelaksanaan Penilaian Awal untuk masyarakat, relawan, dan petugas lokal dalam rangka menyusun dan menyampaikan informasi awal terkait kejadian bencana keadaan darurat bencana.
Maksud dan Tujuan
1. Maksud Petunjuk pelaksanaan ini dimaksudkan untuk memberikan panduan bagi masyarakat, relawan, dan petugas lokal dalam menyampaikan informasi awal terkait keadaan darurat bencana melalui kegiatan penilaian awal.
2. Tujuan Petunjuk Pelaksanaan ini bertujuan untuk mendapatkan informasi awal kejadian bencana sebagai bahan masukan pelaksanaan pengkajian cepat situasi dan kebutuhan Ruang Lingkup Ruang lingkup petunjuk pelaksanaan penilaian awal adalah sebagai berikut:
1. prosedur penyampaian informasi awal kejadian bencana: dan
2. proses pengelolaan data dalam rangka penyiapan informasi.
Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan baik oleh faktor alam, faktor non-alam, maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Penilaian Awal Nomor 4 Tahun 2023');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (801, 'juklak-4-2023', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, '2. Informasi adalah keterangan, pernyataan, gagasan, dan tanda-tanda yang mengandung nilai, makna, dan pesan, baik data, fakta maupun penjelasannya yang dapat dilihat, didengar, dan dibaca yang disajikan dalam berbagai kemasan dan format sesuai dengan perkembangan teknologi informasi dan komunikasi secara elektronik ataupun nonelektronik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (801, '2. Informasi adalah keterangan, pernyataan, gagasan, dan tanda-tanda yang mengandung nilai, makna, dan pesan, baik data, fakta maupun penjelasannya yang dapat dilihat, didengar, dan dibaca yang disajikan dalam berbagai kemasan dan format sesuai dengan perkembangan teknologi informasi dan komunikasi secara elektronik ataupun nonelektronik.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Penilaian Awal Nomor 4 Tahun 2023');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (802, 'juklak-4-2023', 6, 'lain', 'BAB II', NULL, 3, 'PELAKSANAAN Kebutuhan Informasi Kegiatan penilaian awal dapat dibedakan menjadi dua yaitu:
1. Penilaian awal terhadap peningkatan potensi ancaman bencana (Slow onset). Penilaian awal ini dilakukan segera pada saat-saat awal diketahuinya ada tanda-tanda mengarah ke terjadinya keadaan darurat bencana. Hal ini dilakukan hanya untuk jenis bencana yang perkembangan kejadian bencananya dapat diamati /tidak mendadak, seperti bencana banjir genangan, letusan gunungapi, kekeringan, dan lain-lain.
2. Penilaian awal terhadap kondisi peristiwa kedaruratan bencana (sudden onset). Penilaian awal ini dilakukan segera pada saat awal terjadinya keadaan darurat bencana.
Dalam pelaksanaan kegiatan penilaian awal informasi penting yang dibutuhkan terhadap peningkatan potensi ancaman bencana adalah:
a. Informasi terkini potensi ancaman bencana berdasarkan sistem peringatan dini yang diterapkan.
b. Informasi wilayah yang terancam, perkiraan jumlah penduduk, dan fasilitas pelayanan masyarakat yang terancam.
c. Informasi upaya mandiri yang dilakukan oleh masyarakat setempat terkait adanya informasi potensi ancaman.
d. Informasi akses menuju lokasi wilayah yang terancam.
e. Informasi fasilitas pelayanan masyarakat yang dapat dimanfaatkan untuk penyelamatan diri, antara lain:
1) tempat ibadah:
2) fasilitas pendidikan, 3) fasilitas pelayanan Kesehatan: dan 4) fasilitas umum lainya.
Sedangkan informasi penting yang dibutuhkan dalam penilaian awal terhadap kondisi peristiwa kedaruratan bencana adalah:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (802, 'PELAKSANAAN Kebutuhan Informasi Kegiatan penilaian awal dapat dibedakan menjadi dua yaitu:
1. Penilaian awal terhadap peningkatan potensi ancaman bencana (Slow onset). Penilaian awal ini dilakukan segera pada saat-saat awal diketahuinya ada tanda-tanda mengarah ke terjadinya keadaan darurat bencana. Hal ini dilakukan hanya untuk jenis bencana yang perkembangan kejadian bencananya dapat diamati /tidak mendadak, seperti bencana banjir genangan, letusan gunungapi, kekeringan, dan lain-lain.
2. Penilaian awal terhadap kondisi peristiwa kedaruratan bencana (sudden onset). Penilaian awal ini dilakukan segera pada saat awal terjadinya keadaan darurat bencana.
Dalam pelaksanaan kegiatan penilaian awal informasi penting yang dibutuhkan terhadap peningkatan potensi ancaman bencana adalah:
a. Informasi terkini potensi ancaman bencana berdasarkan sistem peringatan dini yang diterapkan.
b. Informasi wilayah yang terancam, perkiraan jumlah penduduk, dan fasilitas pelayanan masyarakat yang terancam.
c. Informasi upaya mandiri yang dilakukan oleh masyarakat setempat terkait adanya informasi potensi ancaman.
d. Informasi akses menuju lokasi wilayah yang terancam.
e. Informasi fasilitas pelayanan masyarakat yang dapat dimanfaatkan untuk penyelamatan diri, antara lain:
1) tempat ibadah:
2) fasilitas pendidikan, 3) fasilitas pelayanan Kesehatan: dan 4) fasilitas umum lainya.
Sedangkan informasi penting yang dibutuhkan dalam penilaian awal terhadap kondisi peristiwa kedaruratan bencana adalah:', 'BAB II', 'Petunjuk Pelaksanaan Penilaian Awal Nomor 4 Tahun 2023');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (803, 'juklak-4-2023', 7, 'lain', 'BAB II (lanjutan 1)', NULL, 3, 'a. Informasi kronologis kejadian bencana.
b. Informasi wilayah yang terdampak (hingga ke tingkat dusun/kampung/lingkungan).
c. Informasi awal perkiraan jumlah korban dan pengungsi.
d. Informasi awal kerusakan fisik, antara lain:
1) rumah tinggal, 2) bangunan pemerintahan, 3) tempat ibadah, 4) fasilitas pendidikan, S) fasilitas pelayanan kesehatan:
6) jalan, 7) jembatan, 8) fasilitas sosial: dan 9) fasilitas umum lainya.
e. Informasi tindakan awal yang dilakukan oleh masyarakat, relawan dan petugas lokal di wilayah terdampak.
f. Informasi perkiraan kebutuhan mendesak untuk penanganan darurat bencana.
g. Informasi akses menuju lokasi wilayah terdampak dan tempat pengungsian.
h. Informasi kondisi cuaca di lokasi terdampak.
Pengelolaan Data dan Pelaporan Untuk mendapatkan informasi dari penilaian awal yang dilakukan, diperlukan proses pengelolaan data dan pelaporan dengan tata cara sebagai berikut:
1. Pengumpulan Data Kegiatan penilaian awal dimulai dengan aktivitas pengumpulan data yaitu dengan mengumpulkan fakta dan data berdasarkan pengamatan lapangan di wilayah terancam maupun terdampak bencana. Fakta dan data yang dikumpulkan berkaitan dengan karakteristik peristiwanya. Untuk kejadian yang slow onset (secara perlahan-lahan), fakta dan data yang dikumpulkan dan dilaporkan (Format 1) adalah berkaitan dengan tanda-tanda dan situasi awal berhubungan dengan keadaan yang mengarah ke terjadinya bencana yang mungkin muncul.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (803, 'a. Informasi kronologis kejadian bencana.
b. Informasi wilayah yang terdampak (hingga ke tingkat dusun/kampung/lingkungan).
c. Informasi awal perkiraan jumlah korban dan pengungsi.
d. Informasi awal kerusakan fisik, antara lain:
1) rumah tinggal, 2) bangunan pemerintahan, 3) tempat ibadah, 4) fasilitas pendidikan, S) fasilitas pelayanan kesehatan:
6) jalan, 7) jembatan, 8) fasilitas sosial: dan 9) fasilitas umum lainya.
e. Informasi tindakan awal yang dilakukan oleh masyarakat, relawan dan petugas lokal di wilayah terdampak.
f. Informasi perkiraan kebutuhan mendesak untuk penanganan darurat bencana.
g. Informasi akses menuju lokasi wilayah terdampak dan tempat pengungsian.
h. Informasi kondisi cuaca di lokasi terdampak.
Pengelolaan Data dan Pelaporan Untuk mendapatkan informasi dari penilaian awal yang dilakukan, diperlukan proses pengelolaan data dan pelaporan dengan tata cara sebagai berikut:
1. Pengumpulan Data Kegiatan penilaian awal dimulai dengan aktivitas pengumpulan data yaitu dengan mengumpulkan fakta dan data berdasarkan pengamatan lapangan di wilayah terancam maupun terdampak bencana. Fakta dan data yang dikumpulkan berkaitan dengan karakteristik peristiwanya. Untuk kejadian yang slow onset (secara perlahan-lahan), fakta dan data yang dikumpulkan dan dilaporkan (Format 1) adalah berkaitan dengan tanda-tanda dan situasi awal berhubungan dengan keadaan yang mengarah ke terjadinya bencana yang mungkin muncul.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Penilaian Awal Nomor 4 Tahun 2023');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (804, 'juklak-4-2023', 8, 'lain', 'BAB II (lanjutan 2)', NULL, 4, 'Sedangkan untuk yang sudden onset (secara tiba-tiba), fakta dan data yang dikumpulkan dan dilaporkan (Format 2) adalah berkaitan dengan tanda-tanda dan situasi awal yang berhubungan dengan terjadinya keadaan darurat bencana.
2. Pelaporan (penyusunan informasi) Hasil pencatatan fakta dan data lapangan, kemudian dibuat tulisan uraian informasi secara singkat dan jelas serta mempunyai arti yang dapat dipahami yang berhubungan dengan keadaan darurat bencana. Uraian informasi tersebut selanjutnya dituangkan kedalam bentuk laporan tertulis (Format 3) yang singkat dan mudah dipahami.
Informasi hasil penilaian awal ini disampaikan segera ke Badan Penanggulangan Bencana Daerah Kabupaten/Kota setempat melalui sarana komunikasi, antara lain:
a. radio komunikasi,
b. telpon:
Cc. telpon genggam:
d. fax, dan
e. melalui kurir, menyampaikan langsung.
Selanjutnya Pusdalops PB BPBD Kabupaten/Kota melakukan pengecekan segera setelah menerima informasi yang disampaikan.');
