INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (810, 'juklak-4-2023', 14, 'lampiran', 'LAMPIRAN (lanjutan 4)', NULL, 10, 'a. Pelaporan penilaian awal terhadap peningkatan potensi ancaman bencana (slow onset).
Kepada Yth. Kepala Pelaksana BPBD Kabupaten X Dilaporkan bahwa pada jam 15.30 WIB telah terjadi perubahan situasi aliran Sungai Blanakan tampak keruh berwarna coklat dan tinggi muka air juga meninggi. Pada pintu air Soka menunjukkan angka 100 mm (kondisi normal ketinggian 70mm). situasi ini mengkhawatirkan terjadinya banjir untuk wilayah dusun Melati dan Cisangka, desa Suka Makmur, kecamatan Palaga. Mengingat hujan masih terus berlangsung, masyarakat setempat mulai berkemas untuk melakukan evakuasi. Akses jalan menuju ke daerah tersebut saat ini masih dapat dilalui kendaraan roda 4.
Demikian laporan ini, atas perhatiannya terima kasih Suka Makmur, 03-06-2016 (pukul 16.00 WIB) Hormat Saya Pelapor, Ahmad Sani (Hp. 0O813XXXXXXXX)
b. Pelaporan penilaian awal terhadap kondisi peristiwa kedaruratan bencana (sudden onset).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (810, 'a. Pelaporan penilaian awal terhadap peningkatan potensi ancaman bencana (slow onset).
Kepada Yth. Kepala Pelaksana BPBD Kabupaten X Dilaporkan bahwa pada jam 15.30 WIB telah terjadi perubahan situasi aliran Sungai Blanakan tampak keruh berwarna coklat dan tinggi muka air juga meninggi. Pada pintu air Soka menunjukkan angka 100 mm (kondisi normal ketinggian 70mm). situasi ini mengkhawatirkan terjadinya banjir untuk wilayah dusun Melati dan Cisangka, desa Suka Makmur, kecamatan Palaga. Mengingat hujan masih terus berlangsung, masyarakat setempat mulai berkemas untuk melakukan evakuasi. Akses jalan menuju ke daerah tersebut saat ini masih dapat dilalui kendaraan roda 4.
Demikian laporan ini, atas perhatiannya terima kasih Suka Makmur, 03-06-2016 (pukul 16.00 WIB) Hormat Saya Pelapor, Ahmad Sani (Hp. 0O813XXXXXXXX)
b. Pelaporan penilaian awal terhadap kondisi peristiwa kedaruratan bencana (sudden onset).', 'LAMPIRAN (lanjutan 4)', 'Petunjuk Pelaksanaan Penilaian Awal Nomor 4 Tahun 2023');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (811, 'juklak-4-2023', 15, 'lampiran', 'LAMPIRAN (lanjutan 5)', NULL, 10, 'Kepada Yth. Kepala Pelaksana BPBD Kota C Dilaporkan bahwa pada jam 16.20 WIB telah terjadi pergerakan tanah di wilayah kampung Parigi, Salatua dan Pemanah, Kelurahan Kertamukti, kecamatan Sawahan. Akibat bencana itu diketahui ada beberapa korban meninggal dan yang hilang belum diketemukan. Selain itu ada yang mengalami luka parah dan ada sejumlah warga yang mengungsi akibat rumahnya hancur ke gedung SDN 04 Sawahan. Akses jalan menuju ke lokasi terputus akibat rubuhnya jembatan Paiton. Warga setempat secara bersama-sama dengan menggunakan peralatan seadanya melakukan pencarian korban yang hilang tertimbun. Kebutuhan yang mendesak adalah bahan makanan, tikar, selimut dan air bersih serta sarana penerangan karena aliran listrik mati.
Demikian laporan ini, atas perhatiannya terima kasih Sawahan, 12-04-2016 (pukul 18.00 WIB) Hormat Saya Pelapor, Sukron (Hp. 0813XXXXXXKX) KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, Ttd.
SUHARYANTO Salinan.sesuyai dengan aslinya BADAN NA RBENANGGULANGAN BENCANA LO ganisas dan Kerja Sama');
