INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (814, 'juklak-4-2025', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 4 TAHUN 20254');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (814, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 4 TAHUN 20254', 'Isi hal. 1', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (815, 'juklak-4-2025', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Berdasarkan laporan Indeks Risiko Dunia tahun 2024, Indonesia merupakan negara dengan risiko bencana tertinggi kedua secara global dan hanya berada satu tingkat di bawah Filipina. Kondisi ini menunjukkan adanya peningkatan risiko bencana yang harus segera direspon secara serius oleh semua pihak, khususnya Pemerintah. Banyak negara telah membuat langkah yang signifikan dalam manajemen risiko bencana dengan adanya pergeseran paradigma yang semula menitikberatkan pada respon saat darurat menjadi lebih proaktif dalam upaya pengurangan risiko bencana. Pendekatan ini telah berhasil mengurangi jumlah korban jiwa dan dampak ekonomi akibat bencana.
Strategi Pembiayaan dan Asuransi Risiko Bencana (PARB) diluncurkan pada tahun 2018 yang kemudian diperkuat dengan penerbitan Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana. Strategi ini dimaksudkan untuk melengkapi mekanisme pembiayaan yang telah ada melalui Anggaran Pendapatan dan Belanja Negara dan Anggaran Pendapatan dan Belanja Daerah dalam membiayai dampak bencana. Penyaluran dana bersama penanggulangan bencana diperuntukkan pada tahap prabencana, saat tanggap darurat bencana, dan pascabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (815, 'PENDAHULUAN A. Latar Belakang Berdasarkan laporan Indeks Risiko Dunia tahun 2024, Indonesia merupakan negara dengan risiko bencana tertinggi kedua secara global dan hanya berada satu tingkat di bawah Filipina. Kondisi ini menunjukkan adanya peningkatan risiko bencana yang harus segera direspon secara serius oleh semua pihak, khususnya Pemerintah. Banyak negara telah membuat langkah yang signifikan dalam manajemen risiko bencana dengan adanya pergeseran paradigma yang semula menitikberatkan pada respon saat darurat menjadi lebih proaktif dalam upaya pengurangan risiko bencana. Pendekatan ini telah berhasil mengurangi jumlah korban jiwa dan dampak ekonomi akibat bencana.
Strategi Pembiayaan dan Asuransi Risiko Bencana (PARB) diluncurkan pada tahun 2018 yang kemudian diperkuat dengan penerbitan Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana. Strategi ini dimaksudkan untuk melengkapi mekanisme pembiayaan yang telah ada melalui Anggaran Pendapatan dan Belanja Negara dan Anggaran Pendapatan dan Belanja Daerah dalam membiayai dampak bencana. Penyaluran dana bersama penanggulangan bencana diperuntukkan pada tahap prabencana, saat tanggap darurat bencana, dan pascabencana.', 'BAB I', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (816, 'juklak-4-2025', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Dalam pengelolaan dana bersama penanggulangan bencana, Kementerian Keuangan menerbitkan Keputusan Menteri Keuangan Nomor 407 Tahun 2021 yang kemudian menugaskan Badan Pengelola Dana Lingkungan Hidup untuk melaksanakan pengelolaan dana bersama penanggulangan bencana. Adapun peran Badan Nasional Penanggulangan Bencana dalam penyaluran dana bersama penanggulangan bencana ini adalah untuk melaksanakan penelaahan, verifikasi, dan evaluasi terhadap permohonan penyaluran dana bersama penanggulangan bencana. Untuk melakukan tugas dan fungsi tersebut, Badan Nasional Penanggulangan Bencana menetapkan Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
Sebagai penjabaran operasional mengenai penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana pada tahap prabencana, Badan Nasional Penanggulangan Bencana menyusun Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana agar dapat dipedomani oleh Badan Nasional Penanggulangan Bencana, Kementerian/Lembaga, dan Pemerintah Daerah serta masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (816, 'Dalam pengelolaan dana bersama penanggulangan bencana, Kementerian Keuangan menerbitkan Keputusan Menteri Keuangan Nomor 407 Tahun 2021 yang kemudian menugaskan Badan Pengelola Dana Lingkungan Hidup untuk melaksanakan pengelolaan dana bersama penanggulangan bencana. Adapun peran Badan Nasional Penanggulangan Bencana dalam penyaluran dana bersama penanggulangan bencana ini adalah untuk melaksanakan penelaahan, verifikasi, dan evaluasi terhadap permohonan penyaluran dana bersama penanggulangan bencana. Untuk melakukan tugas dan fungsi tersebut, Badan Nasional Penanggulangan Bencana menetapkan Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
Sebagai penjabaran operasional mengenai penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana pada tahap prabencana, Badan Nasional Penanggulangan Bencana menyusun Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana agar dapat dipedomani oleh Badan Nasional Penanggulangan Bencana, Kementerian/Lembaga, dan Pemerintah Daerah serta masyarakat.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (817, 'juklak-4-2025', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, 'B. Maksud dan Tujuan Petunjuk Pelaksanaan ini dimaksudkan sebagai panduan operasional dan tata laksana penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana tahap prabencana bagi Badan Nasional Penanggulangan Bencana, Kementerian/Lembaga, Pemerintah Daerah, dan masyarakat.
Petunjuk Pelaksanaan ini disusun dengan tujuan untuk menjabarkan:
1. konsep penanggulangan bencana tahap prabencana;
2. prioritas penyaluran, kriteria kelembagaan, dan ruang lingkup;
3. prinsip dan pendekatan strategis dari penyaluran dana bersama penanggulangan bencana; dan
4. tata cara penelaahan, verifikasi, dan evaluasi untuk penyaluran dana bersama penanggulangan bencana.
C. Ruang Lingkup Petunjuk pelaksanaan ini meliputi pembahasan tentang:
1. latar belakang penyaluran dana bersama penanggulangan bencana;
2. konsep dan posisi dana bersama penanggulangan bencana;
3. prinsip dan pendekatan strategis dari penyaluran dana bersama penanggulangan bencana tahap prabencana; dan
4. penyelenggaraan penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana tahap prabencana.
D. Pengertian Dalam Petunjuk Pelaksanaan ini yang dimaksud dengan:
1. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (817, 'B. Maksud dan Tujuan Petunjuk Pelaksanaan ini dimaksudkan sebagai panduan operasional dan tata laksana penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana tahap prabencana bagi Badan Nasional Penanggulangan Bencana, Kementerian/Lembaga, Pemerintah Daerah, dan masyarakat.
Petunjuk Pelaksanaan ini disusun dengan tujuan untuk menjabarkan:
1. konsep penanggulangan bencana tahap prabencana;
2. prioritas penyaluran, kriteria kelembagaan, dan ruang lingkup;
3. prinsip dan pendekatan strategis dari penyaluran dana bersama penanggulangan bencana; dan
4. tata cara penelaahan, verifikasi, dan evaluasi untuk penyaluran dana bersama penanggulangan bencana.
C. Ruang Lingkup Petunjuk pelaksanaan ini meliputi pembahasan tentang:
1. latar belakang penyaluran dana bersama penanggulangan bencana;
2. konsep dan posisi dana bersama penanggulangan bencana;
3. prinsip dan pendekatan strategis dari penyaluran dana bersama penanggulangan bencana tahap prabencana; dan
4. penyelenggaraan penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana tahap prabencana.
D. Pengertian Dalam Petunjuk Pelaksanaan ini yang dimaksud dengan:
1. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (818, 'juklak-4-2025', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, '2. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
3. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, pengungsian, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
4. Prabencana adalah Penyelenggaraan Penanggulangan Bencana pada masa tidak terjadi bencana dan pada masa terdapat potensi bencana.
5. Dana Penanggulangan Bencana adalah dana yang digunakan bagi penanggulangan bencana untuk tahap prabencana, darurat bencana, dan/atau pascabencana.
6. Dana Bersama Penanggulangan Bencana, yang selanjutnya disebut Dana Bersama, adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi Dana Penanggulangan Bencana yang memadai dan berkelanjutan.
7. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (818, '2. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
3. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, pengungsian, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
4. Prabencana adalah Penyelenggaraan Penanggulangan Bencana pada masa tidak terjadi bencana dan pada masa terdapat potensi bencana.
5. Dana Penanggulangan Bencana adalah dana yang digunakan bagi penanggulangan bencana untuk tahap prabencana, darurat bencana, dan/atau pascabencana.
6. Dana Bersama Penanggulangan Bencana, yang selanjutnya disebut Dana Bersama, adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi Dana Penanggulangan Bencana yang memadai dan berkelanjutan.
7. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (819, 'juklak-4-2025', 6, 'lain', 'BAB I (lanjutan 4)', NULL, 3, '8. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara Pemerintahan Daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
9. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
10. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan Pemerintah Daerah yang melakukan Penyelenggaraan Penanggulangan Bencana di daerah.
11. Kelompok Masyarakat yang selanjutnya disebut Pokmas adalah forum pengurangan risiko bencana, forum tematik pengurangan risiko bencana tingkat lokal, kelompok masyarakat binaan kementerian/lembaga dan perangkat daerah, serta kumpulan individu dari masyarakat terdampak bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (819, '8. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara Pemerintahan Daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
9. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
10. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan Pemerintah Daerah yang melakukan Penyelenggaraan Penanggulangan Bencana di daerah.
11. Kelompok Masyarakat yang selanjutnya disebut Pokmas adalah forum pengurangan risiko bencana, forum tematik pengurangan risiko bencana tingkat lokal, kelompok masyarakat binaan kementerian/lembaga dan perangkat daerah, serta kumpulan individu dari masyarakat terdampak bencana.', 'BAB I (lanjutan 4)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (820, 'juklak-4-2025', 7, 'lain', 'BAB II', NULL, 4, 'KONSEP PENANGGULANGAN BENCANA TAHAP PRABENCANA A. Penanggulangan Bencana Menurut Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, bahwa Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat dan rehabilitasi. Dalam melaksanakan penanggulangan bencana, terdapat prinsip-prinsip yang harus dimiliki, yaitu cepat dan tepat, prioritas, koordinasi dan keterpaduan, berdaya guna dan berhasil guna, transparansi dan akuntabilitas, kemitraan, pemberdayaan, nondiskriminatif dan nonproletisi. Penanggulangan bencana bertujuan untuk:
1. memberikan pelindungan kepada masyarakat dari ancaman bencana;
2. menyelaraskan peraturan perundang-undangan yang sudah ada;
3. menjamin terselenggaranya penanggulangan bencana secara terencana, terpadu, terkoordinasi, dan menyeluruh;
4. menghargai budaya lokal;
5. membangun partisipasi dan kemitraan publik serta swasta;
6. mendorong semangat gotong royong, kesetiakawanan dan kedermawanan; dan
7. menciptakan perdamaian dalam kehidupan bermasyarakat, berbangsa dan bernegara.
Penyelenggaraan Penanggulangan Bencana dilaksanakan berdasarkan 4 (empat) aspek, yaitu sosial, ekonomi, dan budaya masyarakat; kelestarian lingkungan hidup; kemanfaatan dan efektivitas; dan lingkup luas wilayah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (820, 'KONSEP PENANGGULANGAN BENCANA TAHAP PRABENCANA A. Penanggulangan Bencana Menurut Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, bahwa Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat dan rehabilitasi. Dalam melaksanakan penanggulangan bencana, terdapat prinsip-prinsip yang harus dimiliki, yaitu cepat dan tepat, prioritas, koordinasi dan keterpaduan, berdaya guna dan berhasil guna, transparansi dan akuntabilitas, kemitraan, pemberdayaan, nondiskriminatif dan nonproletisi. Penanggulangan bencana bertujuan untuk:
1. memberikan pelindungan kepada masyarakat dari ancaman bencana;
2. menyelaraskan peraturan perundang-undangan yang sudah ada;
3. menjamin terselenggaranya penanggulangan bencana secara terencana, terpadu, terkoordinasi, dan menyeluruh;
4. menghargai budaya lokal;
5. membangun partisipasi dan kemitraan publik serta swasta;
6. mendorong semangat gotong royong, kesetiakawanan dan kedermawanan; dan
7. menciptakan perdamaian dalam kehidupan bermasyarakat, berbangsa dan bernegara.
Penyelenggaraan Penanggulangan Bencana dilaksanakan berdasarkan 4 (empat) aspek, yaitu sosial, ekonomi, dan budaya masyarakat; kelestarian lingkungan hidup; kemanfaatan dan efektivitas; dan lingkup luas wilayah.', 'BAB II', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (821, 'juklak-4-2025', 8, 'lain', 'BAB II (lanjutan 1)', NULL, 4, 'Secara umum, menurut Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana bahwa Penyelenggaraan Penanggulangan Bencana dapat dibagi ke dalam 3 (tiga) tahap utama, yakni Prabencana, saat tanggap darurat, dan pascabencana.
Dijelaskan lebih lanjut berdasarkan Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, bahwa pada tahap Prabencana dapat dikategorikan meliputi kondisi tidak terjadi bencana dan dalam kondisi terdapat potensi terjadinya bencana yang secara umum kegiatan di dalamnya mencakup bentuk pencegahan, mitigasi, dan kesiapsiagaan. Penanggulangan bencana melibatkan semua tingkat pemerintahan berikut lembaga swadaya masyarakat dan organisasi berbasis masyarakat yang juga memainkan peran penting dalam proses tersebut.
Gambar 2.1. Skema penanggulangan bencana menurut Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana Gambar 2.1 merupakan ilustrasi skema penanggulangan bencana serta kegiatan yang dilakukan untuk masing-masing ketiga tahap tersebut menurut Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (821, 'Secara umum, menurut Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana bahwa Penyelenggaraan Penanggulangan Bencana dapat dibagi ke dalam 3 (tiga) tahap utama, yakni Prabencana, saat tanggap darurat, dan pascabencana.
Dijelaskan lebih lanjut berdasarkan Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, bahwa pada tahap Prabencana dapat dikategorikan meliputi kondisi tidak terjadi bencana dan dalam kondisi terdapat potensi terjadinya bencana yang secara umum kegiatan di dalamnya mencakup bentuk pencegahan, mitigasi, dan kesiapsiagaan. Penanggulangan bencana melibatkan semua tingkat pemerintahan berikut lembaga swadaya masyarakat dan organisasi berbasis masyarakat yang juga memainkan peran penting dalam proses tersebut.
Gambar 2.1. Skema penanggulangan bencana menurut Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana Gambar 2.1 merupakan ilustrasi skema penanggulangan bencana serta kegiatan yang dilakukan untuk masing-masing ketiga tahap tersebut menurut Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (822, 'juklak-4-2025', 9, 'lain', 'BAB II (lanjutan 2)', NULL, 5, 'B. Pendanaan Penanggulangan Bencana Penggunaan Dana Penanggulangan Bencana dilaksanakan oleh Pemerintah Pusat (BNPB dan kementerian/lembaga terkait), Pemerintah Daerah (BPBD, perangkat daerah, dan lembaga terkait) sesuai dengan tugas pokok dan fungsinya. Penggunaan dana untuk prabencana bersumber dari Anggaran Pendapatan dan Belanja Negara dan Anggaran Pendapatan dan Belanja Daerah dilakukan sesuai dengan ketentuan peraturan perundang-undangan yang mengatur perencanaan, penganggaran, pelaksanaan, dan pertanggungjawabannya. Alokasi Dana Penanggulangan Bencana pada tahap Prabencana untuk kegiatan dalam situasi:
1. tidak terjadi bencana, penggunaan dana meliputi;
a. fasilitasi penyusunan rencana penanggulangan bencana;
b. program pengurangan risiko bencana;
c. program pencegahan bencana;
d. penyusunan analisis risiko bencana;
e. fasilitasi pelaksanaan penegakan rencana tata ruang;
f. penyelenggaraan pendidikan dan pelatihan penanggulangan bencana; dan
g. penyusunan standar teknis penanggulangan bencana; dan
2. terdapat potensi bencana, penggunaan dana meliputi:
a. kegiatan kesiapsiagaan, meliputi:
1) penyusunan dan uji coba rencana kedaruratan;
2) pengorganisasian;
3) pemasangan dan pengujian sistem peringatan dini;
4) penyediaan serta penyiapan barang pasokan dan peralatan;
5) pengorganisasian penyuluhan dan latihan tentang mekanisme tanggap darurat;
6) penyiapan lokasi evakuasi; dan 7) kegiatan kesiapsiagaan lainnya;
b. pembangunan sistem peringatan dini, meliputi:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (822, 'B. Pendanaan Penanggulangan Bencana Penggunaan Dana Penanggulangan Bencana dilaksanakan oleh Pemerintah Pusat (BNPB dan kementerian/lembaga terkait), Pemerintah Daerah (BPBD, perangkat daerah, dan lembaga terkait) sesuai dengan tugas pokok dan fungsinya. Penggunaan dana untuk prabencana bersumber dari Anggaran Pendapatan dan Belanja Negara dan Anggaran Pendapatan dan Belanja Daerah dilakukan sesuai dengan ketentuan peraturan perundang-undangan yang mengatur perencanaan, penganggaran, pelaksanaan, dan pertanggungjawabannya. Alokasi Dana Penanggulangan Bencana pada tahap Prabencana untuk kegiatan dalam situasi:
1. tidak terjadi bencana, penggunaan dana meliputi;
a. fasilitasi penyusunan rencana penanggulangan bencana;
b. program pengurangan risiko bencana;
c. program pencegahan bencana;
d. penyusunan analisis risiko bencana;
e. fasilitasi pelaksanaan penegakan rencana tata ruang;
f. penyelenggaraan pendidikan dan pelatihan penanggulangan bencana; dan
g. penyusunan standar teknis penanggulangan bencana; dan
2. terdapat potensi bencana, penggunaan dana meliputi:
a. kegiatan kesiapsiagaan, meliputi:
1) penyusunan dan uji coba rencana kedaruratan;
2) pengorganisasian;
3) pemasangan dan pengujian sistem peringatan dini;
4) penyediaan serta penyiapan barang pasokan dan peralatan;
5) pengorganisasian penyuluhan dan latihan tentang mekanisme tanggap darurat;
6) penyiapan lokasi evakuasi; dan 7) kegiatan kesiapsiagaan lainnya;
b. pembangunan sistem peringatan dini, meliputi:', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (823, 'juklak-4-2025', 10, 'lain', 'BAB II (lanjutan 3)', NULL, 6, '1) pengamatan gejala bencana;
2) analisis hasil pengamatan gejala bencana;
3) pengambilan keputusan oleh pihak yang berwenang;
4) penyebarluasan informasi tentang peringatan bencana; dan 5) pengambilan tindakan oleh masyarakat; dan
c. kegiatan mitigasi bencana, meliputi:
1) pelaksanaan penataan ruang;
2) pengaturan pembangunan;
3) pembangunan infrastruktur dan tata bangunan; dan 4) penyelenggaraan pendidikan, penyuluhan, dan pelatihan baik secara konvensional maupun modern.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (823, '1) pengamatan gejala bencana;
2) analisis hasil pengamatan gejala bencana;
3) pengambilan keputusan oleh pihak yang berwenang;
4) penyebarluasan informasi tentang peringatan bencana; dan 5) pengambilan tindakan oleh masyarakat; dan
c. kegiatan mitigasi bencana, meliputi:
1) pelaksanaan penataan ruang;
2) pengaturan pembangunan;
3) pembangunan infrastruktur dan tata bangunan; dan 4) penyelenggaraan pendidikan, penyuluhan, dan pelatihan baik secara konvensional maupun modern.', 'BAB II (lanjutan 3)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (824, 'juklak-4-2025', 11, 'lain', 'BAB III', NULL, 7, 'RUANG LINGKUP DAN KRITERIA PENYALURAN A. Lingkup Penyaluran dan Penerima Manfaat Pembiayaan Dana Bersama tahap Prabencana disalurkan untuk membiayai kegiatan penanggulangan bencana pada tahap Prabencana yang telah dilakukan penilaian mandiri atas pelindungan lingkungan dan sosial Dana Bersama dengan mengutamakan investasi pengurangan risiko bencana kepada penerima manfaat. Penerima manfaat merupakan pihak-pihak yang dapat menerima penyaluran Dana Bersama dari kementerian yang menyelenggarakan urusan pemerintahan di bidang keuangan negara.
Adapun penerima manfaat penyaluran Dana Bersama terdiri atas:
1. kementerian/lembaga;
2. Pemerintah Daerah;
3. Pokmas; dan
4. penyedia barang/jasa.
Pokmas penerima manfaat Dana Bersama antara lain:
1. forum pengurangan risiko bencana;
2. forum tematik pengurangan risiko bencana tingkat lokal;
3. Pokmas binaan kementerian/lembaga dan perangkat daerah; dan
4. kumpulan individu dari masyarakat terdampak bencana (hanya untuk tahap pascabencana).
Penyaluran Dana Bersama kepada Pokmas dapat didampingi oleh fasilitator sesuai jenis kegiatan. Fasilitator bertugas membantu pelaksanaan kegiatan dan ditetapkan paling rendah oleh Sekretaris Daerah. Fasilitator sebagaimana dimaksud dapat beranggotakan dari unsur:
1. kementerian negara/lembaga;
2. Pemerintah Daerah;
3. lembaga swadaya masyarakat;
4. akademisi; dan/atau
5. tim ahli.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (824, 'RUANG LINGKUP DAN KRITERIA PENYALURAN A. Lingkup Penyaluran dan Penerima Manfaat Pembiayaan Dana Bersama tahap Prabencana disalurkan untuk membiayai kegiatan penanggulangan bencana pada tahap Prabencana yang telah dilakukan penilaian mandiri atas pelindungan lingkungan dan sosial Dana Bersama dengan mengutamakan investasi pengurangan risiko bencana kepada penerima manfaat. Penerima manfaat merupakan pihak-pihak yang dapat menerima penyaluran Dana Bersama dari kementerian yang menyelenggarakan urusan pemerintahan di bidang keuangan negara.
Adapun penerima manfaat penyaluran Dana Bersama terdiri atas:
1. kementerian/lembaga;
2. Pemerintah Daerah;
3. Pokmas; dan
4. penyedia barang/jasa.
Pokmas penerima manfaat Dana Bersama antara lain:
1. forum pengurangan risiko bencana;
2. forum tematik pengurangan risiko bencana tingkat lokal;
3. Pokmas binaan kementerian/lembaga dan perangkat daerah; dan
4. kumpulan individu dari masyarakat terdampak bencana (hanya untuk tahap pascabencana).
Penyaluran Dana Bersama kepada Pokmas dapat didampingi oleh fasilitator sesuai jenis kegiatan. Fasilitator bertugas membantu pelaksanaan kegiatan dan ditetapkan paling rendah oleh Sekretaris Daerah. Fasilitator sebagaimana dimaksud dapat beranggotakan dari unsur:
1. kementerian negara/lembaga;
2. Pemerintah Daerah;
3. lembaga swadaya masyarakat;
4. akademisi; dan/atau
5. tim ahli.', 'BAB III', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (825, 'juklak-4-2025', 12, 'lain', 'BAB III (lanjutan 1)', NULL, 7, 'Sedangkan pemohon penyaluran Dana Bersama adalah pihak-pihak yang dapat mengajukan permohonan ke BNPB. Pemohon terdiri atas Kementerian/Lembaga dan Pemerintah Daerah.
B. Prioritas Penyaluran Dana Dana Bersama disalurkan kepada pemohon dengan mempertimbangkan prioritas:
1. kegiatan yang sesuai dengan Rencana Nasional Penanggulangan Bencana/Rencana Penanggulangan Bencana Daerah atau Rencana Kerja Pemerintah/Rencana Kerja Pemerintah Daerah;
2. kegiatan pada daerah dengan indeks risiko bencana tinggi; dan
3. kegiatan yang sesuai dengan standar pelayanan minimal di bidang penanggulangan bencana.
Terhadap pemohon Pemerintah Daerah akan diutamakan bagi yang telah berpartisipasi dalam Dana Bersama. Partisipasi dalam Dana Bersama dimaksud dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
C. Kriteria Kelembagaan Permohonan Dana Bersama dapat diajukan dengan mekanisme sebagai berikut.
1. Kementerian/lembaga diajukan oleh paling rendah pejabat pimpinan tinggi madya.
2. Pemerintah Daerah diajukan oleh Kepala Daerah.
3. Permohonan dari Pemerintah Daerah yang diprakarsai oleh perangkat daerah selain BPBD, perangkat daerah sebagaimana dimaksud wajib berkoordinasi dengan BPBD.
4. BPBD membentuk tim yang ditetapkan oleh serendah-rendahnya Sekretaris Daerah untuk melakukan koordinasi sebagaimana dimaksud pada angka 3.
5. Pemerintah Daerah bertugas memfasilitasi pengajuan permohonan Pokmas yang akan dibiayai oleh Dana Bersama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (825, 'Sedangkan pemohon penyaluran Dana Bersama adalah pihak-pihak yang dapat mengajukan permohonan ke BNPB. Pemohon terdiri atas Kementerian/Lembaga dan Pemerintah Daerah.
B. Prioritas Penyaluran Dana Dana Bersama disalurkan kepada pemohon dengan mempertimbangkan prioritas:
1. kegiatan yang sesuai dengan Rencana Nasional Penanggulangan Bencana/Rencana Penanggulangan Bencana Daerah atau Rencana Kerja Pemerintah/Rencana Kerja Pemerintah Daerah;
2. kegiatan pada daerah dengan indeks risiko bencana tinggi; dan
3. kegiatan yang sesuai dengan standar pelayanan minimal di bidang penanggulangan bencana.
Terhadap pemohon Pemerintah Daerah akan diutamakan bagi yang telah berpartisipasi dalam Dana Bersama. Partisipasi dalam Dana Bersama dimaksud dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
C. Kriteria Kelembagaan Permohonan Dana Bersama dapat diajukan dengan mekanisme sebagai berikut.
1. Kementerian/lembaga diajukan oleh paling rendah pejabat pimpinan tinggi madya.
2. Pemerintah Daerah diajukan oleh Kepala Daerah.
3. Permohonan dari Pemerintah Daerah yang diprakarsai oleh perangkat daerah selain BPBD, perangkat daerah sebagaimana dimaksud wajib berkoordinasi dengan BPBD.
4. BPBD membentuk tim yang ditetapkan oleh serendah-rendahnya Sekretaris Daerah untuk melakukan koordinasi sebagaimana dimaksud pada angka 3.
5. Pemerintah Daerah bertugas memfasilitasi pengajuan permohonan Pokmas yang akan dibiayai oleh Dana Bersama.', 'BAB III (lanjutan 1)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (826, 'juklak-4-2025', 13, 'lain', 'BAB III (lanjutan 2)', NULL, 8, 'Selain kriteria yang disebutkan di atas, perlu memperhatikan tiap pengusulan permohonan Dana Bersama hanya untuk pembiayaan atas 1 (satu) keluaran (output) kegiatan.
D. Ruang Lingkup Kegiatan Ruang lingkup kegiatan Prabencana yang bisa diajukan permohonan penyaluran Dana Bersama merupakan kegiatan yang masuk dalam daftar kegiatan penanggulangan bencana tahap Prabencana dan terbagi dalam kategori:
1. perencanaan dan penyusunan kebijakan;
2. pencegahan;
3. logistik dan peralatan; dan
4. peningkatan kapasitas dan profesi.
Ruang lingkup kegiatan Dana Bersama tahap Prabencana sebagaimana tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
Bagi pemohon Pemerintah Daerah agar dapat menentukan kode, klasifikasi, dan nomenklatur usulan kegiatan sesuai dengan ketentuan dari Kementerian Dalam Negeri mengenai klasifikasi, kodefikasi, dan nomenklatur perencanaan pembangunan dan keuangan daerah, guna memudahkan proses penyaluran Dana Bersama.
E. Prinsip Kegiatan Prinsip adalah nilai-nilai dasar dan pedoman etika yang akan mengarahkan rancangan, implementasi, serta evaluasi kegiatan. Prinsip-prinsip dalam kegiatan Dana Bersama ini merupakan keyakinan dasar yang mendukung pendekatan pengurangan risiko bencana dan pembangunan ketangguhan masyarakat.
Adapun prinsip-prinsip yang digunakan dalam penyaluran Dana Bersama tahap Prabencana sebagai berikut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (826, 'Selain kriteria yang disebutkan di atas, perlu memperhatikan tiap pengusulan permohonan Dana Bersama hanya untuk pembiayaan atas 1 (satu) keluaran (output) kegiatan.
D. Ruang Lingkup Kegiatan Ruang lingkup kegiatan Prabencana yang bisa diajukan permohonan penyaluran Dana Bersama merupakan kegiatan yang masuk dalam daftar kegiatan penanggulangan bencana tahap Prabencana dan terbagi dalam kategori:
1. perencanaan dan penyusunan kebijakan;
2. pencegahan;
3. logistik dan peralatan; dan
4. peningkatan kapasitas dan profesi.
Ruang lingkup kegiatan Dana Bersama tahap Prabencana sebagaimana tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
Bagi pemohon Pemerintah Daerah agar dapat menentukan kode, klasifikasi, dan nomenklatur usulan kegiatan sesuai dengan ketentuan dari Kementerian Dalam Negeri mengenai klasifikasi, kodefikasi, dan nomenklatur perencanaan pembangunan dan keuangan daerah, guna memudahkan proses penyaluran Dana Bersama.
E. Prinsip Kegiatan Prinsip adalah nilai-nilai dasar dan pedoman etika yang akan mengarahkan rancangan, implementasi, serta evaluasi kegiatan. Prinsip-prinsip dalam kegiatan Dana Bersama ini merupakan keyakinan dasar yang mendukung pendekatan pengurangan risiko bencana dan pembangunan ketangguhan masyarakat.
Adapun prinsip-prinsip yang digunakan dalam penyaluran Dana Bersama tahap Prabencana sebagai berikut.', 'BAB III (lanjutan 2)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (827, 'juklak-4-2025', 14, 'lain', 'BAB III (lanjutan 3)', NULL, 8, '1. Pendekatan Berbasis Dampak Pendekatan berbasis dampak memastikan bahwa kegiatan akan memberikan keluaran positif yang terukur dalam upaya pengurangan risiko bencana dan meningkatkan ketangguhan.
2. Prakarsa yang Dipimpin oleh Masyarakat.
Kegiatan harus mendorong peran sentral masyarakat lokal serta dapat meningkatkan kapasitas baik pengetahuan, keterampilan, dan kemampuan masyarakat dalam pengurangan Risiko Bencana.
3. Relevansi Kontekstual dan Solusi Lokal yang Adaptif.
Langkah-langkah kegiatan perlu disesuaikan dengan kebutuhan, budaya, dan kondisi unik masyarakat lokal, memastikan bahwa langkah-langkah tersebut relevan secara kontekstual serta mendorong solusi lokal yang adaptif dalam menangani Risiko Bencana.
4. Kepekaan terhadap Konflik.
Memastikan bahwa potensi konflik serta strategi menghadapinya telah diidentifikasi ketika melaksanakan aktivitas pengurangan Risiko Bencana dalam konteks lokal.
5. Keterbukaan Informasi.
Menyediakan informasi yang terbuka dan mudah diakses mengenai bagaimana dana dialokasikan, digunakan, dan proses pengambilan keputusan yang terlibat, dengan fokus khusus pada transparansi kepada para pelaku lokal.
6. Akuntabilitas.
Memastikan penerima penyaluran Dana Bersama menyampaikan pelaporan secara berkala sekaligus mempromosikan akuntabilitas kepada masyarakat lokal.
7. Keberlanjutan.
Memastikan langkah-langkah kegiatan dapat dipertahankan dan dikembangkan dari waktu ke waktu dengan manfaat dan ketahanan yang berkelanjutan.
8. Inklusivitas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (827, '1. Pendekatan Berbasis Dampak Pendekatan berbasis dampak memastikan bahwa kegiatan akan memberikan keluaran positif yang terukur dalam upaya pengurangan risiko bencana dan meningkatkan ketangguhan.
2. Prakarsa yang Dipimpin oleh Masyarakat.
