INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (848, 'juklak-4-2025', 35, 'lampiran', 'LAMPIRAN III', NULL, 24, 'PETUNJUK PELAKSANAAN PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 4 TAHUN 2025 FORMAT-FORMAT DOKUMEN PENGAJUAN PERMOHONAN DANA BERSAMA TAHAP PRABENCANA Format 1 - Surat Pengajuan Permohonan dari Kementerian/Lembaga KOP SURAT KEMENTERIAN/LEMBAGA PENGUSUL ………………., …………………… Nomor :
Lampiran :
Hal :
