INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (853, 'juklak-4-2025', 40, 'lampiran', 'LAMPIRAN V', NULL, 30, 'PETUNJUK PELAKSANAAN PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 4 TAHUN 2025 FORMAT PERMOHONAN Sistematika penulisan permohonan, paling sedikit memuat:
