INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (853, 'PETUNJUK PELAKSANAAN PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 4 TAHUN 2025 FORMAT PERMOHONAN Sistematika penulisan permohonan, paling sedikit memuat:
