INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (854, 'juklak-4-2025', 41, 'lampiran', 'LAMPIRAN V (lanjutan 1)', NULL, 33, 'Jabatan, (ttd + stempel instansi) Nama Lengkap NIP (apabila ada) PERMOHONAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA*) (JUDUL, LOKASI DAN TAHUN KEGIATAN) Bab I Pendahuluan A. Latar Belakang (kurang lebih 400 – 500 kata) ● Gambaran umum: konteks keseluruhan dari usulan kegiatan, profil bencana singkat, serta faktor historis, sosial dan ekonomi yang melatarbelakangi usulan kegiatan. ● Pernyataan masalah: deskripsi masalah secara jelas, data-data yang mendukung, dan dampak negatif apabila masalah tidak diselesaikan. ● Kesenjangan dan tantangan: identifikasi kesenjangan dan tantangan dalam menghadapi masalah, serta mengapa keadaan sekarang tidak cukup untuk mengatasi masalah tersebut. ● Kesesuaian dengan sistem pengelolaan lingkungan dan sosial: Penjelasan bahwa usulan kegiatan tidak masuk dalam Daftar Negatif serta telah mempertimbangkan risiko lingkungan dan sosial kegiatan serta rencana mitigasi dan pemantauannya.
B. Maksud dan Tujuan (kurang lebih 100 – 200 kata) ● Jelaskan apa tujuan dan sasaran menyeluruh dari usulan kegiatan. ● Relevansi usulan kegiatan untuk mengatasi masalah: penjabaran bagaimana usulan kegiatan dapat mengatasi masalah serta kesenjangan dan tantangan yang teridentifikasi.
C. Ruang Lingkup (kurang lebih 50 – 100 kata) ● Penjelasan mengenai batasan-batasan untuk kegiatan yang diusulkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (854, 'Jabatan, (ttd + stempel instansi) Nama Lengkap NIP (apabila ada) PERMOHONAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA*) (JUDUL, LOKASI DAN TAHUN KEGIATAN) Bab I Pendahuluan A. Latar Belakang (kurang lebih 400 – 500 kata) ● Gambaran umum: konteks keseluruhan dari usulan kegiatan, profil bencana singkat, serta faktor historis, sosial dan ekonomi yang melatarbelakangi usulan kegiatan. ● Pernyataan masalah: deskripsi masalah secara jelas, data-data yang mendukung, dan dampak negatif apabila masalah tidak diselesaikan. ● Kesenjangan dan tantangan: identifikasi kesenjangan dan tantangan dalam menghadapi masalah, serta mengapa keadaan sekarang tidak cukup untuk mengatasi masalah tersebut. ● Kesesuaian dengan sistem pengelolaan lingkungan dan sosial: Penjelasan bahwa usulan kegiatan tidak masuk dalam Daftar Negatif serta telah mempertimbangkan risiko lingkungan dan sosial kegiatan serta rencana mitigasi dan pemantauannya.
B. Maksud dan Tujuan (kurang lebih 100 – 200 kata) ● Jelaskan apa tujuan dan sasaran menyeluruh dari usulan kegiatan. ● Relevansi usulan kegiatan untuk mengatasi masalah: penjabaran bagaimana usulan kegiatan dapat mengatasi masalah serta kesenjangan dan tantangan yang teridentifikasi.
C. Ruang Lingkup (kurang lebih 50 – 100 kata) ● Penjelasan mengenai batasan-batasan untuk kegiatan yang diusulkan.', 'LAMPIRAN V (lanjutan 1)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (855, 'juklak-4-2025', 42, 'lampiran', 'LAMPIRAN V (lanjutan 2)', NULL, 34, 'D. Keluaran (kurang lebih 100 – 200 kata) ● Gambaran secara jelas keluaran yang akan dihasilkan dari usulan kegiatan serta keterkaitannya dengan pencapaian tujuan kegiatan. ● Penjabaran kriteria SMART (Specific, Measurable, Achievable, Realistic, Timely) terhadap keluaran yang akan dihasilkan.
Bab II Gambaran Umum A. Profil Institusi (K/L) atau Profil Daerah (Pemerintah Daerah & Pokmas) (kurang lebih 150 – 200 kata) ● Gambaran umum mengenai profil pemohon, tugas dan fungsi institusi, struktur organisasi, dan wilayah yang akan menjadi lokasi kegiatan ● Terhadap pemohon K/L disertakan gambaran keterlibatan institusi terhadap kegiatan penanggulangan bencana di Indonesia B. Profil Kebencanaan (kurang lebih 150 – 250 kata) ● Gambaran mengenai data historis bencana di daerah dalam jangka waktu 1 (satu) tahun terakhir ● Nilai Indeks Risiko Bencana minimal 5 tahun terakhir ● Risiko bencana prioritas berdasarkan kajian risiko bencana dan rencana penanggulangan bencana (bila ada) ● Tingkat Indeks Ketahanan Daerah minimal 5 tahun terakhir ● Data bencana yang paling sering terjadi serta kondisi kerentanan dan kapasitas C. Kondisi Anggaran (kurang lebih 100 – 200 kata) ● Penjelasan mengenai postur anggaran di kementerian/lembaga atau kapasitas fiskal di Pemda dalam 2 – 3 tahun terakhir ● Penjelasan apakah terdapat anggaran khusus untuk penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (855, 'D. Keluaran (kurang lebih 100 – 200 kata) ● Gambaran secara jelas keluaran yang akan dihasilkan dari usulan kegiatan serta keterkaitannya dengan pencapaian tujuan kegiatan. ● Penjabaran kriteria SMART (Specific, Measurable, Achievable, Realistic, Timely) terhadap keluaran yang akan dihasilkan.
Bab II Gambaran Umum A. Profil Institusi (K/L) atau Profil Daerah (Pemerintah Daerah & Pokmas) (kurang lebih 150 – 200 kata) ● Gambaran umum mengenai profil pemohon, tugas dan fungsi institusi, struktur organisasi, dan wilayah yang akan menjadi lokasi kegiatan ● Terhadap pemohon K/L disertakan gambaran keterlibatan institusi terhadap kegiatan penanggulangan bencana di Indonesia B. Profil Kebencanaan (kurang lebih 150 – 250 kata) ● Gambaran mengenai data historis bencana di daerah dalam jangka waktu 1 (satu) tahun terakhir ● Nilai Indeks Risiko Bencana minimal 5 tahun terakhir ● Risiko bencana prioritas berdasarkan kajian risiko bencana dan rencana penanggulangan bencana (bila ada) ● Tingkat Indeks Ketahanan Daerah minimal 5 tahun terakhir ● Data bencana yang paling sering terjadi serta kondisi kerentanan dan kapasitas C. Kondisi Anggaran (kurang lebih 100 – 200 kata) ● Penjelasan mengenai postur anggaran di kementerian/lembaga atau kapasitas fiskal di Pemda dalam 2 – 3 tahun terakhir ● Penjelasan apakah terdapat anggaran khusus untuk penanggulangan bencana.', 'LAMPIRAN V (lanjutan 2)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (856, 'juklak-4-2025', 43, 'lampiran', 'LAMPIRAN V (lanjutan 3)', NULL, 35, 'D. Potensi Sumber Daya Manusia (kurang lebih 100 – 200 kata) ● Penjelasan mengenai kualitas SDM (tingkat pendidikan, usia, pelatihan yang didapat). ● Kuantitas SDM yang terdapat di Kementerian/lembaga atau Pemerintah Daerah. ● Proporsi antara Aparatur Sipil Negara dan non Aparatur Sipil Negara.
E. Riwayat Kerja Sama Lembaga/Donor (kurang lebih 100 – 200 kata) ● Penjelasan mengenai riwayat kerja sama institusi pemohon dengan donor, apakah pernah menerima bantuan program atau kerja sama dengan lembaga donor nasional atau internasional dalam kurun waktu 5 tahun terakhir, apabila ada. ● Deskripsi mengenai program, anggaran, pelaksana dan hasil dari program kolaborasi tersebut, apabila ada.
Bab III Usulan Kegiatan
1. Kegiatan Eksisting dan Kegiatan yang Diusulkan (kurang lebih 300 - 500 kata) ● Penggambaran mengenai kegiatan terkait penanggulangan bencana yang saat ini dilakukan oleh institusi pemohon, baik rutin atau insidental, di tahap prabencana. ● Deskripsi kegiatan serta penekanan bahwa usulan kegiatan termasuk dalam prioritas penyaluran sebagaimana diatur dalam Pasal 5 ayat (1) Peraturan BNPB Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (856, 'D. Potensi Sumber Daya Manusia (kurang lebih 100 – 200 kata) ● Penjelasan mengenai kualitas SDM (tingkat pendidikan, usia, pelatihan yang didapat). ● Kuantitas SDM yang terdapat di Kementerian/lembaga atau Pemerintah Daerah. ● Proporsi antara Aparatur Sipil Negara dan non Aparatur Sipil Negara.
E. Riwayat Kerja Sama Lembaga/Donor (kurang lebih 100 – 200 kata) ● Penjelasan mengenai riwayat kerja sama institusi pemohon dengan donor, apakah pernah menerima bantuan program atau kerja sama dengan lembaga donor nasional atau internasional dalam kurun waktu 5 tahun terakhir, apabila ada. ● Deskripsi mengenai program, anggaran, pelaksana dan hasil dari program kolaborasi tersebut, apabila ada.
Bab III Usulan Kegiatan
1. Kegiatan Eksisting dan Kegiatan yang Diusulkan (kurang lebih 300 - 500 kata) ● Penggambaran mengenai kegiatan terkait penanggulangan bencana yang saat ini dilakukan oleh institusi pemohon, baik rutin atau insidental, di tahap prabencana. ● Deskripsi kegiatan serta penekanan bahwa usulan kegiatan termasuk dalam prioritas penyaluran sebagaimana diatur dalam Pasal 5 ayat (1) Peraturan BNPB Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.', 'LAMPIRAN V (lanjutan 3)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (857, 'juklak-4-2025', 44, 'lampiran', 'LAMPIRAN V (lanjutan 4)', NULL, 35, '2. Metodologi (kurang lebih 250 - 500 kata) ● Penggambaran mengenai metode kegiatan yang akan dilakukan dengan sorotan pada aspek inovatif metode yang dipilih. ● Penggambaran pemangku kepentingan yang akan terlibat dalam implementasi kegiatan. ● Penjelasan kepatuhan usulan kegiatan dengan prinsip dan pendekatan strategis serta standar sosial dan lingkungan.
3. Kerangka Kerja Logis (kurang lebih 200 – 400 kata) ● Penjelasan runut mengenai keterkaitan masukan, kegiatan, hasil, keluaran, dan dampak didukung dengan representasi visual dengan deskripsi naratif. ● Identifikasi potensi risiko lingkungan dan sosial dari usulan kegiatan dan langkah-langkah memitigasi potensi risiko tersebut.
4. Rencana Kerja (timeline) (kurang lebih 200 – 400 kata) ● Penjelasan mengenai rincian kegiatan yang akan dilakukan setiap bulan atau triwulan serta milestone yang akan dicapai, didukung dengan representasi visual dengan deskripsi naratif. ● Rencana penyerapan dana tiap tahap kegiatan meliputi frekuensi dan besarannya. ● Keterkaitan masing-masing tahapan dalam mencapai tujuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (857, '2. Metodologi (kurang lebih 250 - 500 kata) ● Penggambaran mengenai metode kegiatan yang akan dilakukan dengan sorotan pada aspek inovatif metode yang dipilih. ● Penggambaran pemangku kepentingan yang akan terlibat dalam implementasi kegiatan. ● Penjelasan kepatuhan usulan kegiatan dengan prinsip dan pendekatan strategis serta standar sosial dan lingkungan.
3. Kerangka Kerja Logis (kurang lebih 200 – 400 kata) ● Penjelasan runut mengenai keterkaitan masukan, kegiatan, hasil, keluaran, dan dampak didukung dengan representasi visual dengan deskripsi naratif. ● Identifikasi potensi risiko lingkungan dan sosial dari usulan kegiatan dan langkah-langkah memitigasi potensi risiko tersebut.
4. Rencana Kerja (timeline) (kurang lebih 200 – 400 kata) ● Penjelasan mengenai rincian kegiatan yang akan dilakukan setiap bulan atau triwulan serta milestone yang akan dicapai, didukung dengan representasi visual dengan deskripsi naratif. ● Rencana penyerapan dana tiap tahap kegiatan meliputi frekuensi dan besarannya. ● Keterkaitan masing-masing tahapan dalam mencapai tujuan.', 'LAMPIRAN V (lanjutan 4)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (858, 'juklak-4-2025', 45, 'lampiran', 'LAMPIRAN V (lanjutan 5)', NULL, 35, '5. Pelaksana (kurang lebih 200 – 400 kata) ● Penjelasan mengenai susunan tim pelaksana kegiatan beserta pihak yang akan mengawasi implementasi kegiatan. ● Pengalaman atau rekam jejak dalam melaksanakan kegiatan serupa. ● Identifikasi personil kunci yang akan terlibat, kualifikasi yang dimiliki serta bagaimana keahlian mereka berkontribusi terhadap implementasi kegiatan. ● Penjelasan mengenai pembagian peran dan tanggung jawab tim pelaksana dan personil kunci untuk mencegah ambiguitas. ● Rencana pengembangan kapasitas terhadap tim pelaksana dan personil kunci dalam upaya keberlanjutan kegiatan.
6. Kerangka pemantauan dan evaluasi (kurang lebih 300 – 500 kata) ● Penjelasan mengenai urgensi pemantauan dan evaluasi serta komponen dan metodologi yang digunakan untuk pemantauan dan evaluasi. ● Penjelasan mengenai indikator kinerja utama (IKU) yang dipilih untuk mengukur keberhasilan kegiatan serta alasan pemilihannya. ● Penjelasan mengenai metode untuk mendapat umpan balik dari para pemangku kepentingan yang terlibat. ● Frekuensi melakukan pemantauan dan evaluasi selama implementasi kegiatan. ● Penjelasan mengenai langkah-langkah melakukan evaluasi, kriteria keberhasilan kegiatan, serta hasil yang diharapkan dari evaluasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (858, '5. Pelaksana (kurang lebih 200 – 400 kata) ● Penjelasan mengenai susunan tim pelaksana kegiatan beserta pihak yang akan mengawasi implementasi kegiatan. ● Pengalaman atau rekam jejak dalam melaksanakan kegiatan serupa. ● Identifikasi personil kunci yang akan terlibat, kualifikasi yang dimiliki serta bagaimana keahlian mereka berkontribusi terhadap implementasi kegiatan. ● Penjelasan mengenai pembagian peran dan tanggung jawab tim pelaksana dan personil kunci untuk mencegah ambiguitas. ● Rencana pengembangan kapasitas terhadap tim pelaksana dan personil kunci dalam upaya keberlanjutan kegiatan.
6. Kerangka pemantauan dan evaluasi (kurang lebih 300 – 500 kata) ● Penjelasan mengenai urgensi pemantauan dan evaluasi serta komponen dan metodologi yang digunakan untuk pemantauan dan evaluasi. ● Penjelasan mengenai indikator kinerja utama (IKU) yang dipilih untuk mengukur keberhasilan kegiatan serta alasan pemilihannya. ● Penjelasan mengenai metode untuk mendapat umpan balik dari para pemangku kepentingan yang terlibat. ● Frekuensi melakukan pemantauan dan evaluasi selama implementasi kegiatan. ● Penjelasan mengenai langkah-langkah melakukan evaluasi, kriteria keberhasilan kegiatan, serta hasil yang diharapkan dari evaluasi.', 'LAMPIRAN V (lanjutan 5)', 'Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana Nomor 4 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (859, 'juklak-4-2025', 46, 'lampiran', 'LAMPIRAN V (lanjutan 6)', NULL, 36, '7. Rencana tindak lanjut (kurang lebih 200 – 300 kata) ● Penjelasan mengenai langkah-langkah yang akan diambil oleh pemohon untuk memastikan keberlanjutan kegiatan setelah pengakhiran kegiatan. ● Gambaran mengenai dampak-dampak lanjutan apa yang akan dicapai dengan keberlanjutan kegiatan.
Bab IV Penutup (kurang lebih 150 – 200 kata) ● Ringkasan mengenai isi permohonan secara keseluruhan: tujuan utama, keluaran, serta dampak yang diharapkan. ● Penekanan mengenai pentingnya usulan kegiatan untuk mendapatkan dukungan pendanaan guna mengatasi permasalahan yang ada.
Pelaksana Kegiatan, (ttd + stempel instansi) Nama Lengkap Lampiran Baik pemohon dari Kementerian/Lembaga atau Pemerintah Daerah dilengkapi dengan dokumen wajib dan tambahan sebagaimana dimaksud dalam Bab IV Subbab A nomor 2 huruf a dan b *) Sistematika permohonan menyesuaikan kebutuhan permohonan kegiatan.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi dan Kerja Sama, Irma Dewi Rismayati');
