INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (860, 'juklak-4-2025', 47, 'lampiran', 'LAMPIRAN VI', NULL, 37, 'PETUNJUK PELAKSANAAN PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA NOMOR 4 TAHUN 2025 FORMAT LAPORAN Sistematika penulisan laporan, paling sedikit memuat:
1. Sampul
2. Kata Pengantar
3. Daftar Isi
4. Identitas Pemohon
5. Laporan Pemantauan Kegiatan
6. Lampiran Contoh penulisan laporan.
(SAMPUL) LAPORAN PERIODE: PENDAHULUAN / ANTARA / AKHIR *) PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA ( ………. JUDUL, LOKASI DAN TAHUN KEGIATAN ……… ) LOGO INSTANSI PEMOHON ( ….. INSTANSI PEMOHON ……) TAHUN ……………..
KATA PENGANTAR …………………………………..
DAFTAR ISI …………………………………..
