INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (866, 'juklak-4-2026', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (866, 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026', 'Judul', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (867, 'juklak-4-2026', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMENUHAN STANDAR PELAYANAN MINIMAL SUB-URUSAN BENCANA DAERAH KABUPATEN/KOTA UNTUK SUBKEGIATAN GLADI KESIAPSIAGAAN TERHADAP BENCANA NOMOR 4 TAHUN 2026');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (867, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMENUHAN STANDAR PELAYANAN MINIMAL SUB-URUSAN BENCANA DAERAH KABUPATEN/KOTA UNTUK SUBKEGIATAN GLADI KESIAPSIAGAAN TERHADAP BENCANA NOMOR 4 TAHUN 2026', 'Isi hal. 1', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (868, 'juklak-4-2026', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Setiap Warga Negara Indonesia berhak untuk mendapatkan pelindungan dan rasa aman dari ancaman bencana. Hal ini telah menjadi amanat dari Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Pemerintah dan Pemerintah Daerah bertanggung jawab dalam penyelenggaraan penanggulangan bencana, yang merupakan bagian tidak terpisahkan dari urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (868, 'PENDAHULUAN A. Latar Belakang Setiap Warga Negara Indonesia berhak untuk mendapatkan pelindungan dan rasa aman dari ancaman bencana. Hal ini telah menjadi amanat dari Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Pemerintah dan Pemerintah Daerah bertanggung jawab dalam penyelenggaraan penanggulangan bencana, yang merupakan bagian tidak terpisahkan dari urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar.', 'BAB I', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (869, 'juklak-4-2026', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menegaskan bahwa tugas Badan Nasional Penanggulangan Bencana yaitu memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana dan menetapkan standardisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundang-undangan. Sejalan dengan tugas tersebut, dalam rangka sinergitas dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2021 tentang Penerapan Standar Pelayanan Minimal, Badan Nasional Penanggulangan Bencana sebagai kementerian/lembaga yang membidangi urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar bidang penanggulangan bencana, perlu melakukan pembinaan secara teknis terhadap penerapan standar pelayanan minimal di daerah dengan memberikan pedoman dan pengarahan, menetapkan standarisasi serta melakukan perumusan dan penetapan norma, standar, prosedur, kriteria. Dalam hal ini Badan Nasional Penanggulangan Bencana sebagai lembaga teknis penanggulangan bencana memberikan pembinaan dan pedoman norma, standar, prosedur, dan kriteria pada penerapan standar pelayanan minimal sub-urusan bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (869, 'Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menegaskan bahwa tugas Badan Nasional Penanggulangan Bencana yaitu memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana dan menetapkan standardisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundang-undangan. Sejalan dengan tugas tersebut, dalam rangka sinergitas dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2021 tentang Penerapan Standar Pelayanan Minimal, Badan Nasional Penanggulangan Bencana sebagai kementerian/lembaga yang membidangi urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar bidang penanggulangan bencana, perlu melakukan pembinaan secara teknis terhadap penerapan standar pelayanan minimal di daerah dengan memberikan pedoman dan pengarahan, menetapkan standarisasi serta melakukan perumusan dan penetapan norma, standar, prosedur, kriteria. Dalam hal ini Badan Nasional Penanggulangan Bencana sebagai lembaga teknis penanggulangan bencana memberikan pembinaan dan pedoman norma, standar, prosedur, dan kriteria pada penerapan standar pelayanan minimal sub-urusan bencana di daerah.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (870, 'juklak-4-2026', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 1, 'Untuk mempercepat penerapan Standar Pelayanan Minimal Sub-Urusan Bencana di daerah, Badan Nasional Penanggulangan Bencana perlu menyusun Petunjuk Pelaksanaan Pelayanan Standar Pelayanan Minimal Sub-Urusan Bencana untuk kabupaten/kota yang di dalamnya memuat penjabaran tahapan dan prosedur pelaksanaan pelayanan Standar Pelayanan Minimal Sub-Urusan Bencana. Petunjuk Pelaksanaan ini disusun untuk membantu daerah dalam memenuhi mutu pelayanan dasar dalam pelaksanaan Gladi Kesiapsiagaan terhadap Bencana.
Bahwa setiap warga negara yang berada di kawasan rawan bencana, khususnya para pelaku penanganan darurat bencana di kabupaten/kota, berhak mendapatkan peningkatan kemampuan manajerial maupun teknis dalam hal komunikasi, koordinasi, dan pengerahan sumber daya penanganan darurat bencana. Gladi atau latihan kesiapsiagaan merupakan serangkaian kegiatan yang melibatkan seluruh pemangku kepentingan untuk melatih aspek manajerial maupun teknis dalam hal komunikasi, koordinasi, dan pengerahan sumber daya penanganan darurat bencana berdasarkan skenario yang disusun yang mendekati kondisi sebenarnya. Jenis latihan ini berupa suatu kegiatan terfokus yang menempatkan pelakunya dalam situasi yang disimulasikan guna menjalankan fungsi yang diharapkan darinya pada saat kejadian bencana yang sesungguhnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (870, 'Untuk mempercepat penerapan Standar Pelayanan Minimal Sub-Urusan Bencana di daerah, Badan Nasional Penanggulangan Bencana perlu menyusun Petunjuk Pelaksanaan Pelayanan Standar Pelayanan Minimal Sub-Urusan Bencana untuk kabupaten/kota yang di dalamnya memuat penjabaran tahapan dan prosedur pelaksanaan pelayanan Standar Pelayanan Minimal Sub-Urusan Bencana. Petunjuk Pelaksanaan ini disusun untuk membantu daerah dalam memenuhi mutu pelayanan dasar dalam pelaksanaan Gladi Kesiapsiagaan terhadap Bencana.
Bahwa setiap warga negara yang berada di kawasan rawan bencana, khususnya para pelaku penanganan darurat bencana di kabupaten/kota, berhak mendapatkan peningkatan kemampuan manajerial maupun teknis dalam hal komunikasi, koordinasi, dan pengerahan sumber daya penanganan darurat bencana. Gladi atau latihan kesiapsiagaan merupakan serangkaian kegiatan yang melibatkan seluruh pemangku kepentingan untuk melatih aspek manajerial maupun teknis dalam hal komunikasi, koordinasi, dan pengerahan sumber daya penanganan darurat bencana berdasarkan skenario yang disusun yang mendekati kondisi sebenarnya. Jenis latihan ini berupa suatu kegiatan terfokus yang menempatkan pelakunya dalam situasi yang disimulasikan guna menjalankan fungsi yang diharapkan darinya pada saat kejadian bencana yang sesungguhnya.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (871, 'juklak-4-2026', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, 'Dengan adanya Petunjuk Pelaksanaan ini diharapkan upaya penerapan Standar Pelayanan Minimal Sub-urusan Bencana Subkegiatan Gladi Kesiapsiagaan terhadap Bencana dapat terlaksana dengan lebih terarah, terkoordinasi dan sesuai dengan mutu dan sasaran yang telah ditetapkan.
Berdasarkan pertimbangan sebagaimana disebutkan di atas, perlu menyusun dan menetapkan Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota Untuk Sub-kegiatan Gladi Kesiapsiagaan Terhadap Bencana.
B. Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini dimaksudkan sebagai acuan dalam prosedur pelaksanaan pelayanan dasar standar pelayanan minimal sub-urusan bencana oleh Pemerintah Daerah yang berhak diperoleh setiap warga negara yang berada di kawasan rawan bencana dan yang menjadi korban bencana secara minimal.
2. Tujuan Tujuan Petunjuk Pelaksanaan ini adalah untuk mendukung menyediakan standar teknis atau tata cara pemenuhan pelayanan dasar pada subkegiatan Gladi Kesiapsiagaan terhadap Bencana.
C. Ruang Lingkup Prosedur standar pelayanan minimal sub urusan bencana yang diatur dalam Petunjuk Pelaksanaan ini meliputi Gladi Kesiapsiagaan terhadap Bencana.
D. Pengertian
1. Pelayanan Dasar adalah pelayanan publik untuk memenuhi kebutuhan dasar Warga Negara yang terkena dampak di kawasan rawan bencana dan yang menjadi korban bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (871, 'Dengan adanya Petunjuk Pelaksanaan ini diharapkan upaya penerapan Standar Pelayanan Minimal Sub-urusan Bencana Subkegiatan Gladi Kesiapsiagaan terhadap Bencana dapat terlaksana dengan lebih terarah, terkoordinasi dan sesuai dengan mutu dan sasaran yang telah ditetapkan.
Berdasarkan pertimbangan sebagaimana disebutkan di atas, perlu menyusun dan menetapkan Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota Untuk Sub-kegiatan Gladi Kesiapsiagaan Terhadap Bencana.
B. Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini dimaksudkan sebagai acuan dalam prosedur pelaksanaan pelayanan dasar standar pelayanan minimal sub-urusan bencana oleh Pemerintah Daerah yang berhak diperoleh setiap warga negara yang berada di kawasan rawan bencana dan yang menjadi korban bencana secara minimal.
2. Tujuan Tujuan Petunjuk Pelaksanaan ini adalah untuk mendukung menyediakan standar teknis atau tata cara pemenuhan pelayanan dasar pada subkegiatan Gladi Kesiapsiagaan terhadap Bencana.
C. Ruang Lingkup Prosedur standar pelayanan minimal sub urusan bencana yang diatur dalam Petunjuk Pelaksanaan ini meliputi Gladi Kesiapsiagaan terhadap Bencana.
D. Pengertian
1. Pelayanan Dasar adalah pelayanan publik untuk memenuhi kebutuhan dasar Warga Negara yang terkena dampak di kawasan rawan bencana dan yang menjadi korban bencana.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (872, 'juklak-4-2026', 6, 'lain', 'BAB I (lanjutan 4)', NULL, 2, '2. Standar Pelayanan Minimal yang selanjutnya disingkat SPM adalah ketentuan mengenai jenis dan mutu pelayanan dasar yang merupakan urusan pemerintahan wajib yang berhak diperoleh setiap Warga Negara secara minimal.
3. Standar Teknis adalah standar jumlah dan kualitas barang dan/atau jasa, sumber daya manusia dan petunjuk teknis atau tata cara pemenuhan standar.
4. Jenis Pelayanan Dasar adalah jenis pelayanan dalam rangka penyediaan barang dan/atau jasa kebutuhan dasar yang berhak diperoleh oleh setiap Warga Negara secara minimal.
5. Mutu Pelayanan Dasar adalah ukuran kuantitas dan kualitas barang dan/atau jasa kebutuhan dasar serta pemenuhannya secara minimal dalam Pelayanan Dasar sesuai Standar Teknis agar hidup secara layak.
6. Gladi Ruang adalah latihan berbentuk diskusi yang bertujuan untuk meningkatkan pemahaman, mencari solusi terhadap permasalahan, menghimpun masukan, membangun kesepakatan dan/atau memvalidasi berbagai kebijakan, prosedur dan rencana yang ada.
7. Gladi Lapang adalah latihan operasional gabungan yang merujuk pada skenario kejadian bencana untuk memvalidasi kebijakan, konsep, rencana dan prosedur dengan pengerahan sumber daya dan kemampuan penanganan darurat bencana yang dilakukan dalam simulasi yang menyerupai kejadian sesungguhnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (872, '2. Standar Pelayanan Minimal yang selanjutnya disingkat SPM adalah ketentuan mengenai jenis dan mutu pelayanan dasar yang merupakan urusan pemerintahan wajib yang berhak diperoleh setiap Warga Negara secara minimal.
3. Standar Teknis adalah standar jumlah dan kualitas barang dan/atau jasa, sumber daya manusia dan petunjuk teknis atau tata cara pemenuhan standar.
4. Jenis Pelayanan Dasar adalah jenis pelayanan dalam rangka penyediaan barang dan/atau jasa kebutuhan dasar yang berhak diperoleh oleh setiap Warga Negara secara minimal.
5. Mutu Pelayanan Dasar adalah ukuran kuantitas dan kualitas barang dan/atau jasa kebutuhan dasar serta pemenuhannya secara minimal dalam Pelayanan Dasar sesuai Standar Teknis agar hidup secara layak.
6. Gladi Ruang adalah latihan berbentuk diskusi yang bertujuan untuk meningkatkan pemahaman, mencari solusi terhadap permasalahan, menghimpun masukan, membangun kesepakatan dan/atau memvalidasi berbagai kebijakan, prosedur dan rencana yang ada.
7. Gladi Lapang adalah latihan operasional gabungan yang merujuk pada skenario kejadian bencana untuk memvalidasi kebijakan, konsep, rencana dan prosedur dengan pengerahan sumber daya dan kemampuan penanganan darurat bencana yang dilakukan dalam simulasi yang menyerupai kejadian sesungguhnya.', 'BAB I (lanjutan 4)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (873, 'juklak-4-2026', 7, 'lain', 'BAB I (lanjutan 5)', NULL, 3, '8. Direktif Latihan adalah dokumen yang memuat pokok-pokok kebijakan/arahan pimpinan dalam menyelenggarakan gladi dan digunakan sebagai dasar, acuan atau pedoman dalam menyusun rencana garis besar gladi maupun dalam melaksanakan kegiatan gladi.
9. Rencana Garis Besar yang selanjutnya disingkat RGB adalah dokumen rencana penyelenggaraan gladi secara menyeluruh, yang memuat landasan, pokok-pokok penyelenggaraan gladi serta ringkasan cerita atau skenario simulasi/gladi yang akan digunakan.
10. Rencana Operasi Latihan yang selanjutnya disingkat ROL adalah dokumen yang disusun berdasarkan skenario strategis dan skenario taktis latihan dan menjadi alat kendali utama yang digunakan oleh tim pengawasan dan pengendalian dalam menjalankan dan mengendalikan gladi.
11. Skenario Strategis adalah gambaran tentang situasi atau keadaan umum suatu daerah yang terkena bencana yang menggambarkan kemungkinan kejadian serta potensi dampaknya, yang dikembangkan berdasarkan hasil kajian ilmiah atau ilmu pengetahuan dan dengan menggunakan data-data yang sahih.
12. Skenario Taktis adalah pengembangan dari skenario strategis yang memberikan gambaran situasi atau keadaan khusus secara terinci di daerah yang terkena bencana.
13. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintahan nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (873, '8. Direktif Latihan adalah dokumen yang memuat pokok-pokok kebijakan/arahan pimpinan dalam menyelenggarakan gladi dan digunakan sebagai dasar, acuan atau pedoman dalam menyusun rencana garis besar gladi maupun dalam melaksanakan kegiatan gladi.
9. Rencana Garis Besar yang selanjutnya disingkat RGB adalah dokumen rencana penyelenggaraan gladi secara menyeluruh, yang memuat landasan, pokok-pokok penyelenggaraan gladi serta ringkasan cerita atau skenario simulasi/gladi yang akan digunakan.
10. Rencana Operasi Latihan yang selanjutnya disingkat ROL adalah dokumen yang disusun berdasarkan skenario strategis dan skenario taktis latihan dan menjadi alat kendali utama yang digunakan oleh tim pengawasan dan pengendalian dalam menjalankan dan mengendalikan gladi.
11. Skenario Strategis adalah gambaran tentang situasi atau keadaan umum suatu daerah yang terkena bencana yang menggambarkan kemungkinan kejadian serta potensi dampaknya, yang dikembangkan berdasarkan hasil kajian ilmiah atau ilmu pengetahuan dan dengan menggunakan data-data yang sahih.
12. Skenario Taktis adalah pengembangan dari skenario strategis yang memberikan gambaran situasi atau keadaan khusus secara terinci di daerah yang terkena bencana.
13. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintahan nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.', 'BAB I (lanjutan 5)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (874, 'juklak-4-2026', 8, 'lain', 'BAB I (lanjutan 6)', NULL, 3, '14. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah perangkat daerah yang menyelenggarakan suburusan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (874, '14. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah perangkat daerah yang menyelenggarakan suburusan bencana.', 'BAB I (lanjutan 6)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (875, 'juklak-4-2026', 9, 'lain', 'BAB II', NULL, 4, 'PELAKSANAAN GLADI RUANG A. Gambaran Umum Gladi Ruang merupakan simulasi diskusi berbasis skenario yang digunakan untuk menguji rencana, kebijakan, dan prosedur dalam menghadapi situasi darurat bencana. Gladi Ruang berfungsi sebagai berikut.
a. Fungsi pemahaman: Gladi Ruang dapat berfungsi sebagai sarana untuk memberikan pemahaman tentang kebijakan, prosedur, dan rencana yang telah atau akan disusun. Gladi Ruang juga dapat menjadi sarana untuk memicu atau memberikan pemahaman bahwa suatu kebijakan, prosedur dan rencana belum tersedia, sehingga perlu disusun.
b. Fungsi Penyempurnaan: Gladi Ruang dapat berfungsi sebagai sarana untuk menghimpun berbagai masukan untuk penyempurnaan dokumen kebijakan, prosedur dan rencana yang sudah ada.
c. Fungsi validasi/pengujian: Gladi Ruang dapat berfungsi sebagai sarana untuk memvalidasi dan menguji apakah kebijakan, prosedur dan rencana yang sudah disusun dan diberlakukan sudah benar dan tepat.
Pelaksanaan gladi ruang untuk para pengambil keputusan sebagai pihak yang bertanggung jawab untuk menyempurnakan kebijakan, rencana dan prosedur. Penyelenggaraan Gladi Ruang dalam bentuk pleno sangat efektif untuk meningkatkan pemahaman banyak pihak sekaligus dalam satu kesempatan yang sama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (875, 'PELAKSANAAN GLADI RUANG A. Gambaran Umum Gladi Ruang merupakan simulasi diskusi berbasis skenario yang digunakan untuk menguji rencana, kebijakan, dan prosedur dalam menghadapi situasi darurat bencana. Gladi Ruang berfungsi sebagai berikut.
a. Fungsi pemahaman: Gladi Ruang dapat berfungsi sebagai sarana untuk memberikan pemahaman tentang kebijakan, prosedur, dan rencana yang telah atau akan disusun. Gladi Ruang juga dapat menjadi sarana untuk memicu atau memberikan pemahaman bahwa suatu kebijakan, prosedur dan rencana belum tersedia, sehingga perlu disusun.
b. Fungsi Penyempurnaan: Gladi Ruang dapat berfungsi sebagai sarana untuk menghimpun berbagai masukan untuk penyempurnaan dokumen kebijakan, prosedur dan rencana yang sudah ada.
c. Fungsi validasi/pengujian: Gladi Ruang dapat berfungsi sebagai sarana untuk memvalidasi dan menguji apakah kebijakan, prosedur dan rencana yang sudah disusun dan diberlakukan sudah benar dan tepat.
Pelaksanaan gladi ruang untuk para pengambil keputusan sebagai pihak yang bertanggung jawab untuk menyempurnakan kebijakan, rencana dan prosedur. Penyelenggaraan Gladi Ruang dalam bentuk pleno sangat efektif untuk meningkatkan pemahaman banyak pihak sekaligus dalam satu kesempatan yang sama.', 'BAB II', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (876, 'juklak-4-2026', 10, 'lain', 'BAB II (lanjutan 1)', NULL, 4, 'Dalam Gladi Ruang dilakukan kegiatan berbasis meja/ruang yang biasanya difasilitasi oleh fasilitator sesuai dengan materi latihan yang menjadi tanggung jawabnya dengan mengacu pada ROL serta memastikan pelaku Gladi Ruang berada dalam suatu skenario yang telah disusun sebagai latar belakang jalannya latihan. Gladi Ruang menawarkan kesempatan untuk mengeksplorasi berbagai gagasan dalam konteks skenario dunia nyata.
Fasilitasi yang efektif sangat penting untuk menjaga agar peserta fokus pada tujuan latihan. Fasilitator mungkin bertanya tentang keputusan yang dibuat, termasuk bagaimana keputusan dicapai atau apa implikasi keputusan tersebut. Pelibatan peserta dalam diskusi harus sesuai dengan konteks masalah, dalam hal ini fasilitator tidak bertugas untuk menyelesaikan permasalahan. Untuk memperkuat pembelajaran pada akhir Gladi Ruang dilakukan curah gagasan untuk mengumpulkan umpan balik dan masukan perbaikan.
B. Penyelenggara Gladi Ruang Penyelenggara Gladi Ruang antara lain:
1. pengarah;
2. ketua penyelenggara;
3. koordinator administrasi;
4. koordinator pendukung;
5. koordinator teknis latihan;
6. koordinator pengawas dan pengendali;
7. fasilitator;
8. notulis;
9. tim evaluasi; dan
10. pengamat, yang memiliki kompetensi di bidang teknis latihan dan pengalaman sesuai bidangnya masing-masing dalam penyelenggaraan latihan.
Perangkapan peran penyelenggara dapat dilakukan dalam hal terdapat kebutuhan penyesuaian terhadap kemampuan daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (876, 'Dalam Gladi Ruang dilakukan kegiatan berbasis meja/ruang yang biasanya difasilitasi oleh fasilitator sesuai dengan materi latihan yang menjadi tanggung jawabnya dengan mengacu pada ROL serta memastikan pelaku Gladi Ruang berada dalam suatu skenario yang telah disusun sebagai latar belakang jalannya latihan. Gladi Ruang menawarkan kesempatan untuk mengeksplorasi berbagai gagasan dalam konteks skenario dunia nyata.
Fasilitasi yang efektif sangat penting untuk menjaga agar peserta fokus pada tujuan latihan. Fasilitator mungkin bertanya tentang keputusan yang dibuat, termasuk bagaimana keputusan dicapai atau apa implikasi keputusan tersebut. Pelibatan peserta dalam diskusi harus sesuai dengan konteks masalah, dalam hal ini fasilitator tidak bertugas untuk menyelesaikan permasalahan. Untuk memperkuat pembelajaran pada akhir Gladi Ruang dilakukan curah gagasan untuk mengumpulkan umpan balik dan masukan perbaikan.
B. Penyelenggara Gladi Ruang Penyelenggara Gladi Ruang antara lain:
1. pengarah;
2. ketua penyelenggara;
3. koordinator administrasi;
4. koordinator pendukung;
5. koordinator teknis latihan;
6. koordinator pengawas dan pengendali;
7. fasilitator;
8. notulis;
9. tim evaluasi; dan
10. pengamat, yang memiliki kompetensi di bidang teknis latihan dan pengalaman sesuai bidangnya masing-masing dalam penyelenggaraan latihan.
Perangkapan peran penyelenggara dapat dilakukan dalam hal terdapat kebutuhan penyesuaian terhadap kemampuan daerah.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (877, 'juklak-4-2026', 11, 'lain', 'BAB II (lanjutan 2)', NULL, 5, 'Jumlah personel penyelenggara disesuaikan dengan kebutuhan.
Secara kolektif, tugas penyelenggara Gladi Ruang adalah:
1. Merancang dan mengendalikan pelaksanaan Gladi Ruang; dan
2. Menilai dan mengevaluasi hasil Gladi Ruang yang setidaknya mencakup:
a. rekomendasi perbaikan kebijakan dan mekanisme terkait penanganan darurat bencana;
b. rekomendasi perbaikan rencana kontingensi; dan
c. rekomendasi perbaikan sarana prasarana penanganan darurat bencana.
Dalam menjalankan tugas sebagaimana dimaksud di atas, unsur-unsur penyelenggara Gladi Ruang berbagi peran sesuai tahapan kegiatan dengan tugas secara spesifik sebagai berikut.
1. Pada saat perencanaan kegiatan adalah sebagai berikut:
a. pengarah Gladi Ruang, bertugas untuk memberikan arahan terkait hal-hal strategis yang perlu menjadi acuan, baik menyangkut materi maupun penyelenggaraan Gladi Ruang.
b. ketua penyelenggara, bertugas memimpin keseluruhan proses dan mengoordinasikan seluruh kegiatan Gladi Ruang, termasuk koordinasi lintas instansi/organisasi untuk memastikan kelancaran proses Gladi Ruang.
c. koordinator administrasi, bertugas mengoordinasikan bidang administrasi dan memfasilitasi pemenuhan kebutuhan persuratan, administrasi, keuangan, protokoler, dan kehumasan/publikasi untuk kelancaran proses Gladi Ruang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (877, 'Jumlah personel penyelenggara disesuaikan dengan kebutuhan.
Secara kolektif, tugas penyelenggara Gladi Ruang adalah:
1. Merancang dan mengendalikan pelaksanaan Gladi Ruang; dan
2. Menilai dan mengevaluasi hasil Gladi Ruang yang setidaknya mencakup:
a. rekomendasi perbaikan kebijakan dan mekanisme terkait penanganan darurat bencana;
b. rekomendasi perbaikan rencana kontingensi; dan
c. rekomendasi perbaikan sarana prasarana penanganan darurat bencana.
Dalam menjalankan tugas sebagaimana dimaksud di atas, unsur-unsur penyelenggara Gladi Ruang berbagi peran sesuai tahapan kegiatan dengan tugas secara spesifik sebagai berikut.
1. Pada saat perencanaan kegiatan adalah sebagai berikut:
a. pengarah Gladi Ruang, bertugas untuk memberikan arahan terkait hal-hal strategis yang perlu menjadi acuan, baik menyangkut materi maupun penyelenggaraan Gladi Ruang.
b. ketua penyelenggara, bertugas memimpin keseluruhan proses dan mengoordinasikan seluruh kegiatan Gladi Ruang, termasuk koordinasi lintas instansi/organisasi untuk memastikan kelancaran proses Gladi Ruang.
c. koordinator administrasi, bertugas mengoordinasikan bidang administrasi dan memfasilitasi pemenuhan kebutuhan persuratan, administrasi, keuangan, protokoler, dan kehumasan/publikasi untuk kelancaran proses Gladi Ruang.', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (878, 'juklak-4-2026', 12, 'lain', 'BAB II (lanjutan 3)', NULL, 5, 'd. koordinator pendukung Gladi Ruang, bertugas mengoordinasikan dan memfasilitasi proses Gladi Ruang dalam hal konsumsi, transportasi, akomodasi, peralatan/logistik, kesehatan, dan keamanan untuk setiap kegiatan mulai dari tahap perencanaan, persiapan, pelaksanaan hingga tahap evaluasi.
e. koordinator teknis latihan, bertugas mengoordinasikan dan memfasilitasi Gladi Ruang dalam hal substansi, teknis, operasional dan logistik dan menyusun rencana detail seluruh kegiatan Gladi Ruang mulai dari tahap persiapan, pelaksanaan, sampai evaluasi.
Gambar 1. Struktur Penyelenggaraan Gladi Ruang pada Saat Perencanaan Kegiatan
2. Pada saat pelaksanaan kegiatan adalah sebagai berikut.
a. Koordinator teknis latihan yang beralih fungsi menjadi koordinator pengawas dan pengendali, bertugas mengawasi dan mengendalikan seluruh kegiatan pelaksanaan Gladi Ruang dengan dibantu oleh pengawas dan pengendali operasional, pengawas dan pengendali materi gladi, dan pencatat waktu.
b. Fasilitator, bertugas mempelajari skenario dan materi Gladi Ruang, memfinalkan ROL, menyusun berbagai pertanyaan yang akan digunakan fasilitator dalam diskusi, dan menyusun materi visual.
c. Notulis, bertugas mencatat seluruh poin penting dan memastikan agar semua isu yang didiskusikan tercatat sebagai dasar pertimbangan dalam perumusan evaluasi, rekomendasi, dan laporan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (878, 'd. koordinator pendukung Gladi Ruang, bertugas mengoordinasikan dan memfasilitasi proses Gladi Ruang dalam hal konsumsi, transportasi, akomodasi, peralatan/logistik, kesehatan, dan keamanan untuk setiap kegiatan mulai dari tahap perencanaan, persiapan, pelaksanaan hingga tahap evaluasi.
e. koordinator teknis latihan, bertugas mengoordinasikan dan memfasilitasi Gladi Ruang dalam hal substansi, teknis, operasional dan logistik dan menyusun rencana detail seluruh kegiatan Gladi Ruang mulai dari tahap persiapan, pelaksanaan, sampai evaluasi.
Gambar 1. Struktur Penyelenggaraan Gladi Ruang pada Saat Perencanaan Kegiatan
2. Pada saat pelaksanaan kegiatan adalah sebagai berikut.
a. Koordinator teknis latihan yang beralih fungsi menjadi koordinator pengawas dan pengendali, bertugas mengawasi dan mengendalikan seluruh kegiatan pelaksanaan Gladi Ruang dengan dibantu oleh pengawas dan pengendali operasional, pengawas dan pengendali materi gladi, dan pencatat waktu.
b. Fasilitator, bertugas mempelajari skenario dan materi Gladi Ruang, memfinalkan ROL, menyusun berbagai pertanyaan yang akan digunakan fasilitator dalam diskusi, dan menyusun materi visual.
c. Notulis, bertugas mencatat seluruh poin penting dan memastikan agar semua isu yang didiskusikan tercatat sebagai dasar pertimbangan dalam perumusan evaluasi, rekomendasi, dan laporan.', 'BAB II (lanjutan 3)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (879, 'juklak-4-2026', 13, 'lain', 'BAB II (lanjutan 4)', NULL, 6, 'd. Tim evaluasi, bertugas menyusun perangkat evaluasi untuk setiap tahap kegiatan dan melakukan evaluasi (After Action Review/AAR) terhadap rangkaian kegiatan Gladi Ruang.
e. Pelaku, bertugas hadir sebelum acara dimulai agar dapat mengorientasi diri dengan kondisi/situasi, mengikuti sesi pembekalan, dan berperan aktif dalam keseluruhan kegiatan gladi hingga acara penutupan. Pelaku Gladi Ruang yakni mencakup perwakilan dari organisasi perangkat daerah, lembaga penanggulangan bencana, dan perangkat kecamatan/desa/kelurahan.
f. Pengamat, bertugas mengamati jalannya Gladi Ruang dan mengisi Lembar Pengamat serta mengembalikannya kepada penyelenggara Gladi Ruang.
Gambar 2. Struktur Penyelenggaraan Gladi Ruang pada Saat Pelaksanaan Kegiatan C. Penatalaksanaan Gladi Ruang Tata laksana penyelenggaraan Gladi Ruang dalam hal format, tujuan, peserta, lokasi Gladi Ruang, waktu, persiapan dan prasyarat dapat dilihat dalam tabel berikut.
Tabel 1. Tabel Tata Laksana Gladi Ruang Format • Latihan berbentuk diskusi.
• Latihan untuk para pengambil keputusan dari instansi/lembaga yang berwenang.
• Menjawab dan memecahkan suatu masalah berdasarkan ROL dan skenario yang disusun sebagai latar belakang jalannya latihan.
Tujuan • Meningkatkan pemahaman, mencari solusi terhadap permasalahan, menghimpun masukan, membangun kesepakatan dan/atau memvalidasi berbagai kebijakan, prosedur dan rencana yang ada, terutama aspek-aspek dari renkon.
Tugas dan • Mengatur pelaksanaan Gladi Ruang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (879, 'd. Tim evaluasi, bertugas menyusun perangkat evaluasi untuk setiap tahap kegiatan dan melakukan evaluasi (After Action Review/AAR) terhadap rangkaian kegiatan Gladi Ruang.
e. Pelaku, bertugas hadir sebelum acara dimulai agar dapat mengorientasi diri dengan kondisi/situasi, mengikuti sesi pembekalan, dan berperan aktif dalam keseluruhan kegiatan gladi hingga acara penutupan. Pelaku Gladi Ruang yakni mencakup perwakilan dari organisasi perangkat daerah, lembaga penanggulangan bencana, dan perangkat kecamatan/desa/kelurahan.
f. Pengamat, bertugas mengamati jalannya Gladi Ruang dan mengisi Lembar Pengamat serta mengembalikannya kepada penyelenggara Gladi Ruang.
Gambar 2. Struktur Penyelenggaraan Gladi Ruang pada Saat Pelaksanaan Kegiatan C. Penatalaksanaan Gladi Ruang Tata laksana penyelenggaraan Gladi Ruang dalam hal format, tujuan, peserta, lokasi Gladi Ruang, waktu, persiapan dan prasyarat dapat dilihat dalam tabel berikut.
Tabel 1. Tabel Tata Laksana Gladi Ruang Format • Latihan berbentuk diskusi.
• Latihan untuk para pengambil keputusan dari instansi/lembaga yang berwenang.
• Menjawab dan memecahkan suatu masalah berdasarkan ROL dan skenario yang disusun sebagai latar belakang jalannya latihan.
Tujuan • Meningkatkan pemahaman, mencari solusi terhadap permasalahan, menghimpun masukan, membangun kesepakatan dan/atau memvalidasi berbagai kebijakan, prosedur dan rencana yang ada, terutama aspek-aspek dari renkon.
Tugas dan • Mengatur pelaksanaan Gladi Ruang.', 'BAB II (lanjutan 4)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (880, 'juklak-4-2026', 14, 'lain', 'BAB II (lanjutan 5)', NULL, 7, 'Tanggung Jawab • Mengawasi dan mengendalikan jalannya Pengendali/ latihan/diskusi.
Pengawas dan • Mengawasi dan mengendalikan fasilitator agar Pengendali sesuai dengan ROL.
Tugas dan • Memfasilitasi diskusi saat sesi latihan/gladi Tanggung Jawab berlangsung sesuai dengan materi latihan yang Fasilitator mengacu pada ROL.
• Memastikan pelaku Gladi Ruang berada dalam suatu skenario yang telah disusun sebagai latar belakang jalannya latihan.
• Menyampaikan kasus melalui paparan, video atau gambar.
• Berusaha selalu mengikutsertakan seluruh peserta dalam setiap masalah.
• Memandu dalam penyelesaian suatu masalah.
Tugas dan • Proaktif berpartisipasi dalam Gladi Ruang dan Tanggung Jawab menanggapi masalah yang disampaikan Pelaku fasilitator.
• Memberikan jawaban, usulan, saran dan masukan yang membangun dalam setiap permasalahan.
Lokasi Gladi • Dapat menggunakan ruangan di kantor BPBD Ruang atau tempat lain yang difungsikan sebagai ruang pelaksanaan Gladi Ruang.
• Tata letak ruangan diatur sedemikian rupa guna mendukung proses diskusi peserta.
Waktu Gladi Ruang dapat dirancang untuk dilaksanakan dalam waktu 1-2 hari.
Persiapan Persiapan dan perencanaan Gladi Ruang berkisar antara beberapa hari sampai satu minggu tergantung kompleksitas gladi.
1. Tahap Perencanaan dan Persiapan Gladi Ruang Tahap ini meliputi:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (880, 'Tanggung Jawab • Mengawasi dan mengendalikan jalannya Pengendali/ latihan/diskusi.
Pengawas dan • Mengawasi dan mengendalikan fasilitator agar Pengendali sesuai dengan ROL.
Tugas dan • Memfasilitasi diskusi saat sesi latihan/gladi Tanggung Jawab berlangsung sesuai dengan materi latihan yang Fasilitator mengacu pada ROL.
• Memastikan pelaku Gladi Ruang berada dalam suatu skenario yang telah disusun sebagai latar belakang jalannya latihan.
• Menyampaikan kasus melalui paparan, video atau gambar.
• Berusaha selalu mengikutsertakan seluruh peserta dalam setiap masalah.
• Memandu dalam penyelesaian suatu masalah.
Tugas dan • Proaktif berpartisipasi dalam Gladi Ruang dan Tanggung Jawab menanggapi masalah yang disampaikan Pelaku fasilitator.
• Memberikan jawaban, usulan, saran dan masukan yang membangun dalam setiap permasalahan.
Lokasi Gladi • Dapat menggunakan ruangan di kantor BPBD Ruang atau tempat lain yang difungsikan sebagai ruang pelaksanaan Gladi Ruang.
• Tata letak ruangan diatur sedemikian rupa guna mendukung proses diskusi peserta.
Waktu Gladi Ruang dapat dirancang untuk dilaksanakan dalam waktu 1-2 hari.
Persiapan Persiapan dan perencanaan Gladi Ruang berkisar antara beberapa hari sampai satu minggu tergantung kompleksitas gladi.
1. Tahap Perencanaan dan Persiapan Gladi Ruang Tahap ini meliputi:', 'BAB II (lanjutan 5)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (881, 'juklak-4-2026', 15, 'lain', 'BAB II (lanjutan 6)', NULL, 8, 'a. Penyampaian Direktif Latihan Pengarah Gladi Ruang menetapkan Ketua Penyelenggara Gladi dan menyampaikan arahan latihan yang mudah dipahami terutama bagi kelompok yang memiliki keterbatasan kemampuan. Direktif Latihan merupakan petunjuk atau kebijakan dari pimpinan yang digunakan sebagai dasar, acuan atau pedoman dalam pelaksanaan Gladi Ruang. Arahan latihan digunakan sebagai dasar penyusunan RGB latihan.
b. Pembentukan Tim Perancang Gladi Ruang Ketua Penyelenggara Gladi membentuk tim perancang gladi yang melibatkan perwakilan pihak-pihak yang akan terlibat dalam gladi dengan memberikan kesempatan yang sama dan setara. Jumlah anggota tim tergantung tingkat kompleksitas gladi yang dirancang. Tim akan bertanggung jawab atas perencanaan, persiapan, pelaksanaan hingga evaluasi Gladi Ruang.
c. Penyusunan KAK dan Struktur Organisasi Gladi Ketua Penyelenggara Gladi memimpin tim perancang gladi untuk bersama-sama menyusun Kerangka Acuan Kegiatan yang antara lain berisi maksud, tujuan, sasaran, dan metode Gladi Ruang, sumber daya yang tersedia, skenario umum, tempat dan tanggal gladi, struktur organisasi gladi, pelaku gladi, asumsi-asumsi yang digunakan, metode pengendalian dan evaluasi, logistik, dan hal-hal yang membutuhkan perhatian khusus dan dengan memberikan kesempatan yang sama dan setara. Tim perancang juga menyusun agenda dan menjadwalkan kegiatan terinci dari rangkaian Gladi Ruang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (881, 'a. Penyampaian Direktif Latihan Pengarah Gladi Ruang menetapkan Ketua Penyelenggara Gladi dan menyampaikan arahan latihan yang mudah dipahami terutama bagi kelompok yang memiliki keterbatasan kemampuan. Direktif Latihan merupakan petunjuk atau kebijakan dari pimpinan yang digunakan sebagai dasar, acuan atau pedoman dalam pelaksanaan Gladi Ruang. Arahan latihan digunakan sebagai dasar penyusunan RGB latihan.
b. Pembentukan Tim Perancang Gladi Ruang Ketua Penyelenggara Gladi membentuk tim perancang gladi yang melibatkan perwakilan pihak-pihak yang akan terlibat dalam gladi dengan memberikan kesempatan yang sama dan setara. Jumlah anggota tim tergantung tingkat kompleksitas gladi yang dirancang. Tim akan bertanggung jawab atas perencanaan, persiapan, pelaksanaan hingga evaluasi Gladi Ruang.
c. Penyusunan KAK dan Struktur Organisasi Gladi Ketua Penyelenggara Gladi memimpin tim perancang gladi untuk bersama-sama menyusun Kerangka Acuan Kegiatan yang antara lain berisi maksud, tujuan, sasaran, dan metode Gladi Ruang, sumber daya yang tersedia, skenario umum, tempat dan tanggal gladi, struktur organisasi gladi, pelaku gladi, asumsi-asumsi yang digunakan, metode pengendalian dan evaluasi, logistik, dan hal-hal yang membutuhkan perhatian khusus dan dengan memberikan kesempatan yang sama dan setara. Tim perancang juga menyusun agenda dan menjadwalkan kegiatan terinci dari rangkaian Gladi Ruang.', 'BAB II (lanjutan 6)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (882, 'juklak-4-2026', 16, 'lain', 'BAB II (lanjutan 7)', NULL, 8, 'Ketua Penyelenggara menyampaikan usulan Kerangka Acuan Kegiatan dan struktur organisasi gladi kepada Pengarah Gladi guna mendapatkan masukan perbaikan dan persetujuan. KAK disusun sesuai Format 1 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
d. Rapat Penyusunan Dokumen Latihan 1) Tim perancang menyusun RGB latihan berdasarkan Direktif Latihan. RGB merupakan rencana atau konsep yang memuat landasan gladi, pokok-pokok penyelenggaraan gladi, pembelajaran yang ingin didapatkan dan ringkasan cerita atau skenario gladi mudah dipahami dan diakses oleh semua pihak yang akan dilaksanakan. RGB juga berisi urgensi pelaksanaan, tingkatan, tujuan dan sasaran gladi, skenario gladi, dokumen gladi, dan rencana dukungan logistik dan administrasi. RGB disusun sesuai Format 2 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
2) Tim Perancang menyusun matriks inventarisasi permasalahan dengan cara mengidentifikasi permasalahan yang ada di daerah untuk mengembangkan skenario gladi dan ROL. Identifikasi masalah menjadi dasar untuk menentukan hal-hal yang akan dievaluasi dalam pelaksanaan Gladi Ruang mencakup kebijakan yang ada, kewenangan antar instansi, dan pembagian tugas, fungsi, dan tanggung jawab berbagai pihak yang terlibat dalam konteks skenario yang digladikan.
3) Selanjutnya Tim Perancang menyusun skenario Gladi Ruang berupa daftar kronologis yang berisikan:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (882, 'Ketua Penyelenggara menyampaikan usulan Kerangka Acuan Kegiatan dan struktur organisasi gladi kepada Pengarah Gladi guna mendapatkan masukan perbaikan dan persetujuan. KAK disusun sesuai Format 1 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
d. Rapat Penyusunan Dokumen Latihan 1) Tim perancang menyusun RGB latihan berdasarkan Direktif Latihan. RGB merupakan rencana atau konsep yang memuat landasan gladi, pokok-pokok penyelenggaraan gladi, pembelajaran yang ingin didapatkan dan ringkasan cerita atau skenario gladi mudah dipahami dan diakses oleh semua pihak yang akan dilaksanakan. RGB juga berisi urgensi pelaksanaan, tingkatan, tujuan dan sasaran gladi, skenario gladi, dokumen gladi, dan rencana dukungan logistik dan administrasi. RGB disusun sesuai Format 2 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
2) Tim Perancang menyusun matriks inventarisasi permasalahan dengan cara mengidentifikasi permasalahan yang ada di daerah untuk mengembangkan skenario gladi dan ROL. Identifikasi masalah menjadi dasar untuk menentukan hal-hal yang akan dievaluasi dalam pelaksanaan Gladi Ruang mencakup kebijakan yang ada, kewenangan antar instansi, dan pembagian tugas, fungsi, dan tanggung jawab berbagai pihak yang terlibat dalam konteks skenario yang digladikan.
3) Selanjutnya Tim Perancang menyusun skenario Gladi Ruang berupa daftar kronologis yang berisikan:', 'BAB II (lanjutan 7)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (883, 'juklak-4-2026', 17, 'lain', 'BAB II (lanjutan 8)', NULL, 9, '(a) sinopsis kejadian sebagai pemicu;
(b) respons pelaku yang diharapkan;
(c) keterampilan, tugas, sasaran, atau standar yang menjadi dasar/pembanding yang diharapkan;
(d) personel yang bertanggung jawab;
(e) kejadian khusus dalam skenario (kasus) yang mengarahkan pelaku untuk mengimplementasikan kebijakan atau rencana atau prosedur yang akan divalidasi dalam Gladi Ruang; dan
(f) peralatan yang digunakan untuk penyampaian kasus mencakup telepon, faksimile, radio, email, dan utusan serta peralatan lainnya yang mempertimbangkan aksesibilitas bagi kelompok khusus.
Dalam penyusunan skenario dapat melihat data-data sejarah kejadian bencana sebelumnya yang sahih dan divalidasi oleh para ahli yang memahami konteks ancaman setempat. Skenario juga dapat dilengkapi dengan diskusi bersama para pelaku tanggap darurat yang telah memiliki pengalaman empirik merespons kejadian bencana yang akan digladikan.
4) Terdapat dua skenario, yakni skenario strategis dan skenario taktis.
5) Berdasarkan Skenario Strategis dan Skenario Taktis sebagaimana dimaksud angka 4, tim perancang menyusun ROL. Dokumen ini menjadi alat kendali utama bagi tim pengawasan dan pengendalian dalam menjalankan dan mengendalikan gladi. ROL berisi hal-hal atau isu-isu yang akan menjadi pokok diskusi dalam gladi, penyampaian masalah (inject) dalam bentuk pertanyaan yang akan diberikan oleh fasilitator, serta tanggapan yang diharapkan dan referensi terkait hal-hal yang akan dilatihkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (883, '(a) sinopsis kejadian sebagai pemicu;
(b) respons pelaku yang diharapkan;
(c) keterampilan, tugas, sasaran, atau standar yang menjadi dasar/pembanding yang diharapkan;
(d) personel yang bertanggung jawab;
(e) kejadian khusus dalam skenario (kasus) yang mengarahkan pelaku untuk mengimplementasikan kebijakan atau rencana atau prosedur yang akan divalidasi dalam Gladi Ruang; dan
(f) peralatan yang digunakan untuk penyampaian kasus mencakup telepon, faksimile, radio, email, dan utusan serta peralatan lainnya yang mempertimbangkan aksesibilitas bagi kelompok khusus.
Dalam penyusunan skenario dapat melihat data-data sejarah kejadian bencana sebelumnya yang sahih dan divalidasi oleh para ahli yang memahami konteks ancaman setempat. Skenario juga dapat dilengkapi dengan diskusi bersama para pelaku tanggap darurat yang telah memiliki pengalaman empirik merespons kejadian bencana yang akan digladikan.
4) Terdapat dua skenario, yakni skenario strategis dan skenario taktis.
5) Berdasarkan Skenario Strategis dan Skenario Taktis sebagaimana dimaksud angka 4, tim perancang menyusun ROL. Dokumen ini menjadi alat kendali utama bagi tim pengawasan dan pengendalian dalam menjalankan dan mengendalikan gladi. ROL berisi hal-hal atau isu-isu yang akan menjadi pokok diskusi dalam gladi, penyampaian masalah (inject) dalam bentuk pertanyaan yang akan diberikan oleh fasilitator, serta tanggapan yang diharapkan dan referensi terkait hal-hal yang akan dilatihkan.', 'BAB II (lanjutan 8)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (884, 'juklak-4-2026', 18, 'lain', 'BAB II (lanjutan 9)', NULL, 10, '6) Setelah menyusun RGB, skenario Gladi Ruang, dan ROL, tim perancang juga dapat menyusun panduan berupa:
(1) panduan Fasilitator yang berisi jadwal kegiatan, daftar personel perancang gladi dan data-data terkait lainnya sebagai pedoman bagi para fasilitator;
(2) panduan Tim Evaluasi yang berisi ceklist dan indikator lainnya sebagai pedoman bagi tim evaluasi dalam mengevaluasi jalannya gladi; dan
(3) panduan Pelaku yang memuat tata tertib bagi pelaku dalam mengikuti gladi.
Panduan tersebut di atas dapat dibuat menjadi dokumen terpisah atau dijadikan satu dokumen yang disusun sesuai Format 4, Format 5, dan Format 6 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
e. Persiapan Teknis sebelum Pelaksanaan Sebelum pelaksanaan gladi, tim perancang gladi mengadakan rapat persiapan teknis untuk mendiskusikan rencana pelaksanaan Gladi Ruang, kesiapan seluruh kegiatan pendukung gladi (jadwal, pendaftaran, kesiapan ruang dan alat-alat bantu diskusi, kebutuhan khusus tertentu bila ada, dan peralatan yang mempertimbangkan aksesibilitas bagi kelompok khusus), dan penentuan dokumen-dokumen Gladi Ruang dan materi presentasi. Rapat ini diharapkan akan menghasilkan kesepakatan terhadap hal berkaitan dengan prosedur dan proses Gladi Ruang dari penyelenggara, serta memecahkan permasalahan yang muncul di saat akhir persiapan teknis sebelum pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (884, '6) Setelah menyusun RGB, skenario Gladi Ruang, dan ROL, tim perancang juga dapat menyusun panduan berupa:
(1) panduan Fasilitator yang berisi jadwal kegiatan, daftar personel perancang gladi dan data-data terkait lainnya sebagai pedoman bagi para fasilitator;
(2) panduan Tim Evaluasi yang berisi ceklist dan indikator lainnya sebagai pedoman bagi tim evaluasi dalam mengevaluasi jalannya gladi; dan
(3) panduan Pelaku yang memuat tata tertib bagi pelaku dalam mengikuti gladi.
Panduan tersebut di atas dapat dibuat menjadi dokumen terpisah atau dijadikan satu dokumen yang disusun sesuai Format 4, Format 5, dan Format 6 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
e. Persiapan Teknis sebelum Pelaksanaan Sebelum pelaksanaan gladi, tim perancang gladi mengadakan rapat persiapan teknis untuk mendiskusikan rencana pelaksanaan Gladi Ruang, kesiapan seluruh kegiatan pendukung gladi (jadwal, pendaftaran, kesiapan ruang dan alat-alat bantu diskusi, kebutuhan khusus tertentu bila ada, dan peralatan yang mempertimbangkan aksesibilitas bagi kelompok khusus), dan penentuan dokumen-dokumen Gladi Ruang dan materi presentasi. Rapat ini diharapkan akan menghasilkan kesepakatan terhadap hal berkaitan dengan prosedur dan proses Gladi Ruang dari penyelenggara, serta memecahkan permasalahan yang muncul di saat akhir persiapan teknis sebelum pelaksanaan.', 'BAB II (lanjutan 9)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (885, 'juklak-4-2026', 19, 'lain', 'BAB II (lanjutan 10)', NULL, 10, 'Selain rapat persiapan teknis juga diadakan pembekalan untuk penyelenggara dan pengendali, pelaku, dan tim evaluasi.
Pembekalan ini dilaksanakan untuk memastikan agar semua unsur memahami proses penyelenggaraan gladi, skenario gladi, dan tugas serta tanggung jawab masing-masing dalam mencapai tujuan Gladi Ruang. Koordinator teknis latihan dengan dibantu oleh koordinator pendukung Gladi Ruang juga perlu menyiapkan lokasi gladi untuk memastikan kesiapan dari sisi tata letak, kebutuhan peralatan, logistik, keamanan, dan aksesibilitas.
Apabila Gladi Ruang yang akan dilaksanakan memiliki tingkat kompleksitas yang tinggi, dapat dilakukan gladi resik sebelum pelaksanaan Gladi Ruang yang sesungguhnya. Gladi resik ini melibatkan unsur penyelenggara, pelaku, dan tim evaluasi.
Tujuan kegiatan ini adalah untuk memberikan gambaran secara umum tentang bentuk dan mekanisme kegiatan Gladi Ruang yang akan dilaksanakan.
Tahap perencanaan dan persiapan ini merupakan tahapan yang berurutan dalam Gladi Ruang dan mempunyai bentuk pengorganisasian yang sama. Pada tahap perencanaan, tim bidang teknis latihan merupakan pihak yang memahami secara mendalam seluk beluk rancangan gladi yang akan dilaksanakan. Oleh karena itu, tim bidang teknis akan beralih fungsi menjadi tim pengawas dan pengendali. Jika terdapat keterbatasan jumlah personel yang terlibat dalam penyelenggaraan gladi, dimungkinkan perangkapan tugas dan fungsi beberapa unsur dengan memperhatikan kemampuan personel yang ditunjuk.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (885, 'Selain rapat persiapan teknis juga diadakan pembekalan untuk penyelenggara dan pengendali, pelaku, dan tim evaluasi.
Pembekalan ini dilaksanakan untuk memastikan agar semua unsur memahami proses penyelenggaraan gladi, skenario gladi, dan tugas serta tanggung jawab masing-masing dalam mencapai tujuan Gladi Ruang. Koordinator teknis latihan dengan dibantu oleh koordinator pendukung Gladi Ruang juga perlu menyiapkan lokasi gladi untuk memastikan kesiapan dari sisi tata letak, kebutuhan peralatan, logistik, keamanan, dan aksesibilitas.
Apabila Gladi Ruang yang akan dilaksanakan memiliki tingkat kompleksitas yang tinggi, dapat dilakukan gladi resik sebelum pelaksanaan Gladi Ruang yang sesungguhnya. Gladi resik ini melibatkan unsur penyelenggara, pelaku, dan tim evaluasi.
Tujuan kegiatan ini adalah untuk memberikan gambaran secara umum tentang bentuk dan mekanisme kegiatan Gladi Ruang yang akan dilaksanakan.
Tahap perencanaan dan persiapan ini merupakan tahapan yang berurutan dalam Gladi Ruang dan mempunyai bentuk pengorganisasian yang sama. Pada tahap perencanaan, tim bidang teknis latihan merupakan pihak yang memahami secara mendalam seluk beluk rancangan gladi yang akan dilaksanakan. Oleh karena itu, tim bidang teknis akan beralih fungsi menjadi tim pengawas dan pengendali. Jika terdapat keterbatasan jumlah personel yang terlibat dalam penyelenggaraan gladi, dimungkinkan perangkapan tugas dan fungsi beberapa unsur dengan memperhatikan kemampuan personel yang ditunjuk.', 'BAB II (lanjutan 10)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (886, 'juklak-4-2026', 20, 'lain', 'BAB II (lanjutan 11)', NULL, 11, '2. Tahap Pelaksanaan Gladi Ruang Pada tahap pelaksanaan terdapat 5 (lima) kegiatan utama, yaitu:
a. Pembukaan 1) Acara pembukaan yang dilaksanakan mengikuti alur standar protokoler yang berlaku.
2) Acara pembukaan agar dilakukan sesingkat mungkin, mengingat salah satu tantangan dalam melaksanakan Gladi Ruang adalah keterbatasan waktu. Target capaian Gladi akan lebih mudah dicapai apabila sesi latihan mendapatkan alokasi waktu yang benar-benar memadai.
b. Sesi Pembekalan 1) Sesi pembekalan merupakan sesi untuk menyampaikan penjelasan mengenai detail pelaksanaan kegiatan termasuk penjelasan mengenai peralatan yang akan digunakan dalam Gladi Ruang. Penyampaian penjelasan dengan mempertimbangkan aksesibilitas bagi kelompok khusus kepada para pelaku Gladi Ruang agar memahami skenario latihan yang akan disimulasikan, materi yang akan dilatihkan, dan mekanisme pelaksanaan Gladi Ruang.
2) Pelaku Gladi Ruang diharapkan merupakan personel/pejabat di bidang yang sesuai, sehingga sesi pembekalan yang cukup singkat waktu pelaksanaannya, akan cukup memadai untuk menyegarkan kembali ingatan atau pemahaman akan hal-hal yang akan dilatihkan.
3) Berbagai materi dalam sesi pembekalan disampaikan oleh para narasumber sesuai bidang keahliannya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (886, '2. Tahap Pelaksanaan Gladi Ruang Pada tahap pelaksanaan terdapat 5 (lima) kegiatan utama, yaitu:
a. Pembukaan 1) Acara pembukaan yang dilaksanakan mengikuti alur standar protokoler yang berlaku.
2) Acara pembukaan agar dilakukan sesingkat mungkin, mengingat salah satu tantangan dalam melaksanakan Gladi Ruang adalah keterbatasan waktu. Target capaian Gladi akan lebih mudah dicapai apabila sesi latihan mendapatkan alokasi waktu yang benar-benar memadai.
b. Sesi Pembekalan 1) Sesi pembekalan merupakan sesi untuk menyampaikan penjelasan mengenai detail pelaksanaan kegiatan termasuk penjelasan mengenai peralatan yang akan digunakan dalam Gladi Ruang. Penyampaian penjelasan dengan mempertimbangkan aksesibilitas bagi kelompok khusus kepada para pelaku Gladi Ruang agar memahami skenario latihan yang akan disimulasikan, materi yang akan dilatihkan, dan mekanisme pelaksanaan Gladi Ruang.
2) Pelaku Gladi Ruang diharapkan merupakan personel/pejabat di bidang yang sesuai, sehingga sesi pembekalan yang cukup singkat waktu pelaksanaannya, akan cukup memadai untuk menyegarkan kembali ingatan atau pemahaman akan hal-hal yang akan dilatihkan.
3) Berbagai materi dalam sesi pembekalan disampaikan oleh para narasumber sesuai bidang keahliannya.', 'BAB II (lanjutan 11)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (887, 'juklak-4-2026', 21, 'lain', 'BAB II (lanjutan 12)', NULL, 11, '4) Sesi pembekalan diakhiri dengan Briefing Pelaku Gladi Ruang oleh Koordinator Pengawas dan Pengendali Gladi Ruang yang menjelaskan mengenai tata tertib dalam Gladi Ruang. Pada sesi ini pelaku Gladi Ruang diberi kesempatan untuk bertanya sehingga sebelum sesi latihan yang sesungguhnya dimulai, semua pelaku Gladi Ruang sudah memahami tugas dan tanggung jawabnya serta tata tertib pelaksanaan Gladi Ruang.
5) Durasi pelaksanaan kegiatan Gladi Ruang berbeda-beda, tergantung dari materi yang akan dilatihkan. Apabila Gladi Ruang dilaksanakan dalam waktu lebih dari 1 (satu) hari, penyelenggara gladi perlu memastikan bahwa pelaku Gladi Ruang yang sama yang akan hadir pada hari-hari berikutnya. Hal ini dimaksudkan untuk menghindari kerancuan jalannya diskusi dan meminimalkan tantangan dalam mencapai hasil yang diinginkan.
c. Sesi Latihan 1) Sesi latihan diawali dengan pernyataan Koordinator Pengawas dan Pengendali menyatakan “Gladi Ruang dimulai”.
2) Sesi latihan dalam kegiatan Gladi Ruang merupakan sesi diskusi yang difasilitasi oleh 1 (satu) atau lebih fasilitator yang menguasai materi latihan dan mampu mengendalikan jalannya diskusi dengan alokasi waktu dan target capaian yang telah ditentukan. Hal ini dapat menjadi tantangan bagi fasilitator bila jumlah pelaku Gladi Ruang cukup besar.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (887, '4) Sesi pembekalan diakhiri dengan Briefing Pelaku Gladi Ruang oleh Koordinator Pengawas dan Pengendali Gladi Ruang yang menjelaskan mengenai tata tertib dalam Gladi Ruang. Pada sesi ini pelaku Gladi Ruang diberi kesempatan untuk bertanya sehingga sebelum sesi latihan yang sesungguhnya dimulai, semua pelaku Gladi Ruang sudah memahami tugas dan tanggung jawabnya serta tata tertib pelaksanaan Gladi Ruang.
5) Durasi pelaksanaan kegiatan Gladi Ruang berbeda-beda, tergantung dari materi yang akan dilatihkan. Apabila Gladi Ruang dilaksanakan dalam waktu lebih dari 1 (satu) hari, penyelenggara gladi perlu memastikan bahwa pelaku Gladi Ruang yang sama yang akan hadir pada hari-hari berikutnya. Hal ini dimaksudkan untuk menghindari kerancuan jalannya diskusi dan meminimalkan tantangan dalam mencapai hasil yang diinginkan.
c. Sesi Latihan 1) Sesi latihan diawali dengan pernyataan Koordinator Pengawas dan Pengendali menyatakan “Gladi Ruang dimulai”.
2) Sesi latihan dalam kegiatan Gladi Ruang merupakan sesi diskusi yang difasilitasi oleh 1 (satu) atau lebih fasilitator yang menguasai materi latihan dan mampu mengendalikan jalannya diskusi dengan alokasi waktu dan target capaian yang telah ditentukan. Hal ini dapat menjadi tantangan bagi fasilitator bila jumlah pelaku Gladi Ruang cukup besar.', 'BAB II (lanjutan 12)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (888, 'juklak-4-2026', 22, 'lain', 'BAB II (lanjutan 13)', NULL, 12, '3) Sebelum memfasilitasi diskusi suatu topik, fasilitator terlebih dahulu menyampaikan skenario yang menjadi konteks diskusi untuk topik yang akan didiskusikan. Agar pelaku Gladi Ruang mudah mengikuti atau memahami skenario tersebut, fasilitator menyiapkan dan menayangkan visualisasi (misalnya dalam bentuk paparan, video, peta, dan lainnya) dengan dibantu oleh penanggung jawab skenario. Diskusi yang berlangsung selama pelaksanaan sesi latihan harus tetap dalam konteks skenario yang telah disusun oleh tim perancang Gladi Ruang.
4) Skenario yang disusun harus mendekati realitas sebenarnya sebagaimana situasi darurat ketika bencana yang sesungguhnya terjadi, dengan permasalahan atau tantangan-tantangan yang sangat mungkin timbul pada kondisi yang demikian. Oleh karena itu, skenario Gladi Ruang memberikan konteks diskusi dan tidak seharusnya menjadi fokus diskusi.
5) Selanjutnya fasilitator melontarkan pertanyaan-pertanyaan kepada pelaku-pelaku tertentu sebagaimana yang terdapat pada ROL, dengan memperhatikan waktu yang dialokasikan untuk setiap topik/materi diskusi. Hal tersebut biasanya dilakukan cukup ketat oleh fasilitator, mengingat banyak pelaku-pelaku Gladi Ruang yang lain mempunyai pendapat atau pemikiran yang berbeda-beda dan ingin menyampaikan pendapat atau pemikirannya.
6) Setiap pelaku Gladi Ruang menunggu gilirannya untuk mendapatkan pertanyaan dan memberikan tanggapan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (888, '3) Sebelum memfasilitasi diskusi suatu topik, fasilitator terlebih dahulu menyampaikan skenario yang menjadi konteks diskusi untuk topik yang akan didiskusikan. Agar pelaku Gladi Ruang mudah mengikuti atau memahami skenario tersebut, fasilitator menyiapkan dan menayangkan visualisasi (misalnya dalam bentuk paparan, video, peta, dan lainnya) dengan dibantu oleh penanggung jawab skenario. Diskusi yang berlangsung selama pelaksanaan sesi latihan harus tetap dalam konteks skenario yang telah disusun oleh tim perancang Gladi Ruang.
4) Skenario yang disusun harus mendekati realitas sebenarnya sebagaimana situasi darurat ketika bencana yang sesungguhnya terjadi, dengan permasalahan atau tantangan-tantangan yang sangat mungkin timbul pada kondisi yang demikian. Oleh karena itu, skenario Gladi Ruang memberikan konteks diskusi dan tidak seharusnya menjadi fokus diskusi.
5) Selanjutnya fasilitator melontarkan pertanyaan-pertanyaan kepada pelaku-pelaku tertentu sebagaimana yang terdapat pada ROL, dengan memperhatikan waktu yang dialokasikan untuk setiap topik/materi diskusi. Hal tersebut biasanya dilakukan cukup ketat oleh fasilitator, mengingat banyak pelaku-pelaku Gladi Ruang yang lain mempunyai pendapat atau pemikiran yang berbeda-beda dan ingin menyampaikan pendapat atau pemikirannya.
6) Setiap pelaku Gladi Ruang menunggu gilirannya untuk mendapatkan pertanyaan dan memberikan tanggapan.', 'BAB II (lanjutan 13)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (889, 'juklak-4-2026', 23, 'lain', 'BAB II (lanjutan 14)', NULL, 12, 'Jika pelaku Gladi Ruang ingin memberikan tanggapan terhadap pernyataan pelaku gladi sebelumnya, maka pelaku Gladi Ruang tersebut meminta izin dengan memberikan tanda kepada fasilitator, dan menunggu hingga fasilitator memberikan giliran tersebut.
7) Selama sesi latihan berlangsung, tim evaluasi juga melakukan tugasnya untuk mengevaluasi dengan menggunakan perangkat evaluasi yang telah disiapkan sebelumnya.
8) Tim notulis melakukan pencatatan pokok-pokok diskusi untuk membantu perumusan hasil evaluasi, rekomendasi dan penyusunan laporan.
9) Personel yang bertugas sebagai pencatat/penjaga waktu atau time keeper selalu mengikuti jalannya diskusi dengan memperhatikan alokasi waktu, sehingga dapat membantu mengingatkan fasilitator secara bertahap terkait ketersediaan sisa waktu untuk memfasilitasi diskusi dengan menunjukkan kertas atau papan yang bertuliskan misalnya 10 menit, 5 menit, 3 menit, 1 menit, dan waktu habis.
10) Jika terdapat pengamat, unsur ini memberikan catatan/masukan secara tertulis dan pada akhir sesi latihan masukan tersebut akan dikumpulkan oleh tim pengawas dan pengendali dan diberikan kepada tim evaluasi. Untuk memudahkan tim evaluasi dalam mengompilasi berbagai masukan dari pengamat, setiap pengamat menggunakan formulir evaluasi yang telah disediakan.
11) Pada akhir sesi latihan, koordinator tim pengawas dan pengendali menyatakan “Gladi Ruang dinyatakan berakhir”.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (889, 'Jika pelaku Gladi Ruang ingin memberikan tanggapan terhadap pernyataan pelaku gladi sebelumnya, maka pelaku Gladi Ruang tersebut meminta izin dengan memberikan tanda kepada fasilitator, dan menunggu hingga fasilitator memberikan giliran tersebut.
7) Selama sesi latihan berlangsung, tim evaluasi juga melakukan tugasnya untuk mengevaluasi dengan menggunakan perangkat evaluasi yang telah disiapkan sebelumnya.
8) Tim notulis melakukan pencatatan pokok-pokok diskusi untuk membantu perumusan hasil evaluasi, rekomendasi dan penyusunan laporan.
9) Personel yang bertugas sebagai pencatat/penjaga waktu atau time keeper selalu mengikuti jalannya diskusi dengan memperhatikan alokasi waktu, sehingga dapat membantu mengingatkan fasilitator secara bertahap terkait ketersediaan sisa waktu untuk memfasilitasi diskusi dengan menunjukkan kertas atau papan yang bertuliskan misalnya 10 menit, 5 menit, 3 menit, 1 menit, dan waktu habis.
10) Jika terdapat pengamat, unsur ini memberikan catatan/masukan secara tertulis dan pada akhir sesi latihan masukan tersebut akan dikumpulkan oleh tim pengawas dan pengendali dan diberikan kepada tim evaluasi. Untuk memudahkan tim evaluasi dalam mengompilasi berbagai masukan dari pengamat, setiap pengamat menggunakan formulir evaluasi yang telah disediakan.
11) Pada akhir sesi latihan, koordinator tim pengawas dan pengendali menyatakan “Gladi Ruang dinyatakan berakhir”.', 'BAB II (lanjutan 14)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (890, 'juklak-4-2026', 24, 'lain', 'BAB II (lanjutan 15)', NULL, 13, '12) Dengan menggunakan ROL, tim pengawas dan pengendali gladi melakukan pengawasan terhadap jalannya latihan, maupun fasilitator yang bertugas. Apabila fasilitator dinilai tidak atau kurang mampu mengendalikan pelaku latihan, tim pengawas dan pengendali berhak mengingatkan fasilitator. Apabila fasilitator membutuhkan bantuan, tim pengawas dan pengendali akan membantu mengendalikan situasi latihan.
13) ROL yang digunakan dalam Gladi Ruang hanya diketahui atau dapat diakses oleh tim pengawas dan pengendali, fasilitator, dan tim evaluasi. Hal ini dilakukan agar menjaga kerahasiaan skenario Gladi Ruang.
d. Sesi Pemaparan Hasil Evaluasi dan Rekomendasi 1) Setelah sesi latihan berakhir, tim evaluasi diberi waktu singkat untuk merangkum hasil evaluasi bersama serta memberikan rekomendasi berdasarkan hasil temuan gladi untuk kemudian disampaikan kepada pelaku dan penyelenggara Gladi Ruang. Oleh karena itu, tim evaluasi ditempatkan pada posisi tertentu pada saat pelaksanaan Gladi Ruang, sehingga mereka dapat mengikuti jalannya latihan dengan baik dan dapat saling berkomunikasi dengan sesama personel tim evaluasi, jika diperlukan.
2) Pada saat tim evaluasi melakukan perumusan, pelaku Gladi Ruang dapat diberi kesempatan untuk rehat.
Alternatif lain, dengan difasilitasi oleh fasilitator atau salah satu anggota tim pengawas dan pengendali, pelaku Gladi Ruang diminta memberikan kesan terkait pelaksanaan Gladi Ruang yang baru saja diikuti.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (890, '12) Dengan menggunakan ROL, tim pengawas dan pengendali gladi melakukan pengawasan terhadap jalannya latihan, maupun fasilitator yang bertugas. Apabila fasilitator dinilai tidak atau kurang mampu mengendalikan pelaku latihan, tim pengawas dan pengendali berhak mengingatkan fasilitator. Apabila fasilitator membutuhkan bantuan, tim pengawas dan pengendali akan membantu mengendalikan situasi latihan.
13) ROL yang digunakan dalam Gladi Ruang hanya diketahui atau dapat diakses oleh tim pengawas dan pengendali, fasilitator, dan tim evaluasi. Hal ini dilakukan agar menjaga kerahasiaan skenario Gladi Ruang.
d. Sesi Pemaparan Hasil Evaluasi dan Rekomendasi 1) Setelah sesi latihan berakhir, tim evaluasi diberi waktu singkat untuk merangkum hasil evaluasi bersama serta memberikan rekomendasi berdasarkan hasil temuan gladi untuk kemudian disampaikan kepada pelaku dan penyelenggara Gladi Ruang. Oleh karena itu, tim evaluasi ditempatkan pada posisi tertentu pada saat pelaksanaan Gladi Ruang, sehingga mereka dapat mengikuti jalannya latihan dengan baik dan dapat saling berkomunikasi dengan sesama personel tim evaluasi, jika diperlukan.
2) Pada saat tim evaluasi melakukan perumusan, pelaku Gladi Ruang dapat diberi kesempatan untuk rehat.
Alternatif lain, dengan difasilitasi oleh fasilitator atau salah satu anggota tim pengawas dan pengendali, pelaku Gladi Ruang diminta memberikan kesan terkait pelaksanaan Gladi Ruang yang baru saja diikuti.', 'BAB II (lanjutan 15)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (891, 'juklak-4-2026', 25, 'lain', 'BAB II (lanjutan 16)', NULL, 13, '3) Pada sesi ini, tim evaluasi menyampaikan rumusan hasil evaluasi dan rekomendasi kepada para peserta Gladi Ruang secara pleno.
e. Penutupan Acara penutupan kegiatan Gladi Ruang dilakukan secara singkat sesuai aturan protokol yang berlaku. Pejabat yang menyampaikan sambutan penutupan kegiatan Gladi Ruang perlu menyampaikan mengenai rencana tindak lanjut hasil latihan.
f. Tahap Pengakhiran Pada tahap pengakhiran, kegiatan utama yang dilakukan mencakup: a) penyelesaian administrasi, pengembalian logistik dan peralatan Gladi Ruang oleh tim bidang administrasi dan tim bidang pendukung gladi; b) pemulangan pelaku Gladi Ruang; c) evaluasi keseluruhan yang melibatkan seluruh tim/panitia penyelenggara latihan dan tim evaluasi Gladi Ruang; d) perumusan detail hasil evaluasi (materi latihan) serta rekomendasinya yang melibatkan ketua dan atau wakil ketua penyelenggara Gladi Ruang, tim pengawas dan pengendali, dan tim evaluasi yang kemudian menjadi dasar penyusunan rencana tindakan perbaikan; dan e) penulisan dan penyelesaian laporan administrasi dan laporan operasional/pelaksanaan sebagai bentuk pertanggungjawaban dan juga sebagai dasar untuk menyampaikan masukan/usulan rencana tindak lanjut perbaikan yang diperlukan kepada pimpinan dan untuk pembinaan latihan di masa mendatang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (891, '3) Pada sesi ini, tim evaluasi menyampaikan rumusan hasil evaluasi dan rekomendasi kepada para peserta Gladi Ruang secara pleno.
e. Penutupan Acara penutupan kegiatan Gladi Ruang dilakukan secara singkat sesuai aturan protokol yang berlaku. Pejabat yang menyampaikan sambutan penutupan kegiatan Gladi Ruang perlu menyampaikan mengenai rencana tindak lanjut hasil latihan.
f. Tahap Pengakhiran Pada tahap pengakhiran, kegiatan utama yang dilakukan mencakup: a) penyelesaian administrasi, pengembalian logistik dan peralatan Gladi Ruang oleh tim bidang administrasi dan tim bidang pendukung gladi; b) pemulangan pelaku Gladi Ruang; c) evaluasi keseluruhan yang melibatkan seluruh tim/panitia penyelenggara latihan dan tim evaluasi Gladi Ruang; d) perumusan detail hasil evaluasi (materi latihan) serta rekomendasinya yang melibatkan ketua dan atau wakil ketua penyelenggara Gladi Ruang, tim pengawas dan pengendali, dan tim evaluasi yang kemudian menjadi dasar penyusunan rencana tindakan perbaikan; dan e) penulisan dan penyelesaian laporan administrasi dan laporan operasional/pelaksanaan sebagai bentuk pertanggungjawaban dan juga sebagai dasar untuk menyampaikan masukan/usulan rencana tindak lanjut perbaikan yang diperlukan kepada pimpinan dan untuk pembinaan latihan di masa mendatang.', 'BAB II (lanjutan 16)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (892, 'juklak-4-2026', 26, 'lain', 'BAB II (lanjutan 17)', NULL, 14, 'g. Tahap Tindakan Perbaikan Penyelenggaraan Gladi Ruang tidak berakhir pada acara penutupan pelaksanaan Gladi Ruang atau penyelesaian laporan administrasi dan operasional pelaksanaan kegiatan Gladi Ruang. Jika berakhir demikian, kegiatan Gladi Ruang tidak akan memberikan dampak nyata pada peningkatan kemampuan kesiapsiagaan suatu daerah, instansi/lembaga, kelompok dan/atau individu.
Rangkaian kegiatan yang dilaksanakan pada tahap tindakan perbaikan bertujuan agar kesenjangan dan tantangan atau permasalahan yang teridentifikasi dalam Gladi Ruang dapat ditindaklanjuti dengan upaya-upaya perbaikan yang nyata, termasuk perbaikan atau penyempurnaan kebijakan, prosedur atau rencana yang telah disusun atau bahkan untuk menyusun kebijakan, prosedur atau rencana yang belum ada namun sangat diperlukan.
Kegiatan utama dalam tahap tindakan perbaikan sebagai berikut.
a. Penyusunan usulan rencana tindakan perbaikan oleh lembaga/instansi penyelenggara Gladi Ruang berdasarkan hasil rumusan evaluasi dan rekomendasi. Usulan rencana tindakan perbaikan mencakup informasi antara lain:
1) hal-hal yang memerlukan tindakan perbaikan;
2) target capaian atau target perbaikan yang akan dicapai atau diselesaikan;
3) pihak yang terlibat untuk melaksanakan tindakan perbaikan, baik pihak yang menjadi focal point atau penanggung jawab utama maupun pihak pelaksana pendukung; dan 4) durasi waktu pelaksanaan dan tenggat waktu penyelesaian tindakan perbaikan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (892, 'g. Tahap Tindakan Perbaikan Penyelenggaraan Gladi Ruang tidak berakhir pada acara penutupan pelaksanaan Gladi Ruang atau penyelesaian laporan administrasi dan operasional pelaksanaan kegiatan Gladi Ruang. Jika berakhir demikian, kegiatan Gladi Ruang tidak akan memberikan dampak nyata pada peningkatan kemampuan kesiapsiagaan suatu daerah, instansi/lembaga, kelompok dan/atau individu.
Rangkaian kegiatan yang dilaksanakan pada tahap tindakan perbaikan bertujuan agar kesenjangan dan tantangan atau permasalahan yang teridentifikasi dalam Gladi Ruang dapat ditindaklanjuti dengan upaya-upaya perbaikan yang nyata, termasuk perbaikan atau penyempurnaan kebijakan, prosedur atau rencana yang telah disusun atau bahkan untuk menyusun kebijakan, prosedur atau rencana yang belum ada namun sangat diperlukan.
Kegiatan utama dalam tahap tindakan perbaikan sebagai berikut.
a. Penyusunan usulan rencana tindakan perbaikan oleh lembaga/instansi penyelenggara Gladi Ruang berdasarkan hasil rumusan evaluasi dan rekomendasi. Usulan rencana tindakan perbaikan mencakup informasi antara lain:
1) hal-hal yang memerlukan tindakan perbaikan;
2) target capaian atau target perbaikan yang akan dicapai atau diselesaikan;
3) pihak yang terlibat untuk melaksanakan tindakan perbaikan, baik pihak yang menjadi focal point atau penanggung jawab utama maupun pihak pelaksana pendukung; dan 4) durasi waktu pelaksanaan dan tenggat waktu penyelesaian tindakan perbaikan.', 'BAB II (lanjutan 17)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (893, 'juklak-4-2026', 27, 'lain', 'BAB II (lanjutan 18)', NULL, 14, 'b. Usulan rencana tindakan perbaikan tersebut kemudian disampaikan kepada atau didiskusikan dengan pihak-pihak yang akan terlibat dalam implementasinya, sehingga terdapat kesepakatan terkait pembagian tugas dan tanggung jawab, tindakan perbaikan yang perlu atau akan dilakukan beserta tenggat waktu penyelesaiannya.
c. Instansi penyelenggara gladi melakukan pemantauan terhadap kemajuan capaian tindakan perbaikan dan apabila diperlukan dapat dilaksanakan pertemuan koordinasi untuk memastikan tindakan perbaikan dapat diselesaikan sesuai target dan waktu yang telah ditentukan.
Penyelenggaraan Gladi Ruang yang berikutnya, sebaiknya dilaksanakan setelah adanya perbaikan kebijakan, rencana, ataupun prosedur sehingga hasil Gladi Ruang dapat benar-benar meningkatkan kapabilitas kesiapsiagaan. Oleh karena itu, tahap tindakan perbaikan ini, sama pentingnya dengan empat tahapan lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (893, 'b. Usulan rencana tindakan perbaikan tersebut kemudian disampaikan kepada atau didiskusikan dengan pihak-pihak yang akan terlibat dalam implementasinya, sehingga terdapat kesepakatan terkait pembagian tugas dan tanggung jawab, tindakan perbaikan yang perlu atau akan dilakukan beserta tenggat waktu penyelesaiannya.
c. Instansi penyelenggara gladi melakukan pemantauan terhadap kemajuan capaian tindakan perbaikan dan apabila diperlukan dapat dilaksanakan pertemuan koordinasi untuk memastikan tindakan perbaikan dapat diselesaikan sesuai target dan waktu yang telah ditentukan.
Penyelenggaraan Gladi Ruang yang berikutnya, sebaiknya dilaksanakan setelah adanya perbaikan kebijakan, rencana, ataupun prosedur sehingga hasil Gladi Ruang dapat benar-benar meningkatkan kapabilitas kesiapsiagaan. Oleh karena itu, tahap tindakan perbaikan ini, sama pentingnya dengan empat tahapan lainnya.', 'BAB II (lanjutan 18)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (894, 'juklak-4-2026', 28, 'lain', 'BAB III', NULL, 16, 'PELAKSANAAN GLADI LAPANG A. Gambaran Umum Gladi Lapang bersifat operasional dan bertujuan untuk mengonsolidasikan gabungan sumber daya penanganan darurat bencana, memvalidasi kemampuan teknis dalam menerapkan komponen-komponen kesiapsiagaan, serta meningkatkan kemampuan pelaku PDB di daerah. Oleh karena itu, penyelenggaraan Gladi Lapang berfungsi sebagai wahana untuk secara bersama-sama:
1. mengoordinasikan kemampuan semua unsur di daerah yang diikutsertakan dalam upaya pengerahan sumber daya untuk penanganan darurat bencana;
2. mengidentifikasi kemampuan dan celah-celah kekurangan atau kelemahan dalam pengerahan sumber daya serta upaya penyelamatan jiwa dan aset untuk tujuan perbaikan; dan
3. meningkatkan kemampuan setiap Pelaku PDB sesuai dengan tugas pokok dan fungsi masing-masing pada lembaga dan komunitasnya.
Pelaksanaan Gladi Lapang bertujuan untuk mengetahui kemampuan kesiapsiagaan daerah secara nyata dalam mengantisipasi situasi darurat bencana. Oleh karena itu, kegiatan ini sebaiknya melibatkan semua komponen yang berkepentingan dalam penanganan darurat bencana di daerah, mencakup:
1. rencana kontingensi;
2. tata kelola penanganan darurat bencana (kebijakan, sistem, rencana, prosedur);
3. pelaku penanganan darurat bencana; dan
4. sumber daya (sarana, prasarana, bantuan kemanusiaan dan pendanaan).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (894, 'PELAKSANAAN GLADI LAPANG A. Gambaran Umum Gladi Lapang bersifat operasional dan bertujuan untuk mengonsolidasikan gabungan sumber daya penanganan darurat bencana, memvalidasi kemampuan teknis dalam menerapkan komponen-komponen kesiapsiagaan, serta meningkatkan kemampuan pelaku PDB di daerah. Oleh karena itu, penyelenggaraan Gladi Lapang berfungsi sebagai wahana untuk secara bersama-sama:
1. mengoordinasikan kemampuan semua unsur di daerah yang diikutsertakan dalam upaya pengerahan sumber daya untuk penanganan darurat bencana;
2. mengidentifikasi kemampuan dan celah-celah kekurangan atau kelemahan dalam pengerahan sumber daya serta upaya penyelamatan jiwa dan aset untuk tujuan perbaikan; dan
3. meningkatkan kemampuan setiap Pelaku PDB sesuai dengan tugas pokok dan fungsi masing-masing pada lembaga dan komunitasnya.
Pelaksanaan Gladi Lapang bertujuan untuk mengetahui kemampuan kesiapsiagaan daerah secara nyata dalam mengantisipasi situasi darurat bencana. Oleh karena itu, kegiatan ini sebaiknya melibatkan semua komponen yang berkepentingan dalam penanganan darurat bencana di daerah, mencakup:
1. rencana kontingensi;
2. tata kelola penanganan darurat bencana (kebijakan, sistem, rencana, prosedur);
3. pelaku penanganan darurat bencana; dan
4. sumber daya (sarana, prasarana, bantuan kemanusiaan dan pendanaan).', 'BAB III', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (895, 'juklak-4-2026', 29, 'lain', 'BAB III (lanjutan 1)', NULL, 16, 'Semua komponen kesiapsiagaan penanganan darurat bencana dikembangkan dan dilatihkan dengan metode simulasi untuk membangun kemampuan penanganan darurat bencana di daerah. BNPB memformulasikan rangkaian upaya peningkatan kemampuan penanganan darurat bencana secara bertahap dan parsial melalui latihan dan simulasi.
Latihan dan simulasi bertujuan untuk meningkatkan kemampuan koordinasi, keterampilan teknis, pengoperasian sistem dan peralatan, implementasi kebijakan dan prosedur, serta penyusunan rencana dan tindakan. Uji sistem merupakan tahap akhir yang menggabungkan hasil dari semua latihan dan simulasi yang diwujudkan dalam penyelenggaraan latihan. Gladi Lapang menjadi tahap akhir untuk mengonsolidasikan kemampuan penanganan darurat bencana, menguji setiap komponen kesiapsiagaan, serta mengidentifikasi komponen kesiapsiagaan yang perlu diperbaiki untuk diterapkan di daerah. Selain itu, Gladi Lapang dilaksanakan juga untuk menguji kualitas rencana kontingensi.
Dokumen pelaksanaan Gladi Lapang setidaknya mencakup:
1. RGB Latihan, termasuk skenario latihan;
2. matriks inventarisasi permasalahan (dokumen yang bersifat terbatas); dan
3. RIG.
B. Penyelenggara Gladi Lapang Penyelenggara Gladi Lapang terdiri atas:
1. pengarah;
2. ketua penyelenggara;
3. koordinator administrasi;
4. koordinator pendukung;
5. koordinator teknis latihan;
6. koordinator pengawas dan pengendali;
7. fasilitator;
8. notulis;
9. tim evaluasi; dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (895, 'Semua komponen kesiapsiagaan penanganan darurat bencana dikembangkan dan dilatihkan dengan metode simulasi untuk membangun kemampuan penanganan darurat bencana di daerah. BNPB memformulasikan rangkaian upaya peningkatan kemampuan penanganan darurat bencana secara bertahap dan parsial melalui latihan dan simulasi.
Latihan dan simulasi bertujuan untuk meningkatkan kemampuan koordinasi, keterampilan teknis, pengoperasian sistem dan peralatan, implementasi kebijakan dan prosedur, serta penyusunan rencana dan tindakan. Uji sistem merupakan tahap akhir yang menggabungkan hasil dari semua latihan dan simulasi yang diwujudkan dalam penyelenggaraan latihan. Gladi Lapang menjadi tahap akhir untuk mengonsolidasikan kemampuan penanganan darurat bencana, menguji setiap komponen kesiapsiagaan, serta mengidentifikasi komponen kesiapsiagaan yang perlu diperbaiki untuk diterapkan di daerah. Selain itu, Gladi Lapang dilaksanakan juga untuk menguji kualitas rencana kontingensi.
Dokumen pelaksanaan Gladi Lapang setidaknya mencakup:
1. RGB Latihan, termasuk skenario latihan;
2. matriks inventarisasi permasalahan (dokumen yang bersifat terbatas); dan
3. RIG.
B. Penyelenggara Gladi Lapang Penyelenggara Gladi Lapang terdiri atas:
1. pengarah;
2. ketua penyelenggara;
3. koordinator administrasi;
4. koordinator pendukung;
5. koordinator teknis latihan;
6. koordinator pengawas dan pengendali;
7. fasilitator;
8. notulis;
9. tim evaluasi; dan', 'BAB III (lanjutan 1)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (896, 'juklak-4-2026', 30, 'lain', 'BAB III (lanjutan 2)', NULL, 17, '10. pengamat, yang memiliki kompetensi di bidang teknis latihan dan pengalaman sesuai bidangnya masing-masing dalam penyelenggaraan latihan.
Perangkapan peran penyelenggara dapat dilakukan dalam hal terdapat kebutuhan penyesuaian terhadap kemampuan daerah. Jumlah personel penyelenggara disesuaikan dengan kebutuhan.
Secara kolektif, tugas penyelenggara Gladi Lapang adalah:
1. Merancang dan mengendalikan pelaksanaan Gladi Lapang;
2. Menilai dan mengevaluasi hasil Gladi Lapang, setidaknya mencakup:
a. rekomendasi perbaikan rencana kontingensi;
b. rekomendasi penyempurnaan prosedur; dan
c. rekomendasi perbaikan sarana prasarana penanganan darurat bencana.
Dalam menjalankan tugas sebagaimana dimaksud di atas, unsur-unsur penyelenggara Gladi Ruang berbagi peran sesuai tahapan kegiatan dengan tugas secara spesifik sebagai berikut.
1. Pada saat perencanaan kegiatan adalah sebagai berikut:
a. pengarah, bertugas untuk memberikan arahan terkait hal-hal strategis yang perlu menjadi acuan, baik menyangkut materi maupun penyelenggaraan Gladi Lapang;
b. ketua penyelenggara, bertugas memimpin keseluruhan proses dan mengoordinasikan seluruh kegiatan Gladi Lapang, termasuk melakukan koordinasi lintas instansi/organisasi untuk memastikan kelancaran proses Gladi Lapang;
c. koordinator administrasi, bertugas mengoordinasikan bidang administrasi dan memfasilitasi pemenuhan kebutuhan persuratan, administrasi, keuangan, protokoler, dan kehumasan/publikasi untuk kelancaran proses Gladi Lapang;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (896, '10. pengamat, yang memiliki kompetensi di bidang teknis latihan dan pengalaman sesuai bidangnya masing-masing dalam penyelenggaraan latihan.
Perangkapan peran penyelenggara dapat dilakukan dalam hal terdapat kebutuhan penyesuaian terhadap kemampuan daerah. Jumlah personel penyelenggara disesuaikan dengan kebutuhan.
Secara kolektif, tugas penyelenggara Gladi Lapang adalah:
1. Merancang dan mengendalikan pelaksanaan Gladi Lapang;
2. Menilai dan mengevaluasi hasil Gladi Lapang, setidaknya mencakup:
a. rekomendasi perbaikan rencana kontingensi;
b. rekomendasi penyempurnaan prosedur; dan
c. rekomendasi perbaikan sarana prasarana penanganan darurat bencana.
Dalam menjalankan tugas sebagaimana dimaksud di atas, unsur-unsur penyelenggara Gladi Ruang berbagi peran sesuai tahapan kegiatan dengan tugas secara spesifik sebagai berikut.
1. Pada saat perencanaan kegiatan adalah sebagai berikut:
a. pengarah, bertugas untuk memberikan arahan terkait hal-hal strategis yang perlu menjadi acuan, baik menyangkut materi maupun penyelenggaraan Gladi Lapang;
b. ketua penyelenggara, bertugas memimpin keseluruhan proses dan mengoordinasikan seluruh kegiatan Gladi Lapang, termasuk melakukan koordinasi lintas instansi/organisasi untuk memastikan kelancaran proses Gladi Lapang;
c. koordinator administrasi, bertugas mengoordinasikan bidang administrasi dan memfasilitasi pemenuhan kebutuhan persuratan, administrasi, keuangan, protokoler, dan kehumasan/publikasi untuk kelancaran proses Gladi Lapang;', 'BAB III (lanjutan 2)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (897, 'juklak-4-2026', 31, 'lain', 'BAB III (lanjutan 3)', NULL, 17, 'd. koordinator pendukung Gladi Lapang, bertugas mengoordinasikan dan memfasilitasi proses Gladi Lapang dalam hal konsumsi, transportasi, akomodasi, peralatan/logistik, kesehatan, dan keamanan untuk setiap kegiatan mulai dari tahap perencanaan, persiapan, pelaksanaan, sampai evaluasi; dan
e. koordinator teknis latihan, bertugas mengoordinasikan dan memfasilitasi Gladi Lapang dalam hal substansi, teknis, operasional dan logistik dan menyusun rencana detail seluruh kegiatan Gladi Lapang mulai dari tahap persiapan, pelaksanaan, sampai evaluasi.
Gambar 3. Struktur Penyelenggaraan Gladi Lapang pada Saat Perencanaan Kegiatan
2. Pada saat pelaksanaan kegiatan adalah sebagai berikut.
a. Koordinator teknis latihan yang beralih fungsi menjadi koordinator pengawas dan pengendali, bertugas mengawasi dan mengendalikan seluruh kegiatan pelaksanaan Gladi Lapang dengan dibantu oleh pengawas dan pengendali operasional, pengawas dan pengendali materi gladi, dan pencatat waktu.
b. Fasilitator, bertugas mempelajari skenario dan materi Gladi Lapang, memfinalkan ROL, menyusun berbagai pertanyaan yang akan digunakan fasilitator dalam diskusi, dan menyusun materi visual.
c. Notulis, bertugas mencatat seluruh poin penting dan memastikan agar semua isu yang didiskusikan tercatat sebagai dasar pertimbangan dalam perumusan evaluasi, rekomendasi, dan laporan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (897, 'd. koordinator pendukung Gladi Lapang, bertugas mengoordinasikan dan memfasilitasi proses Gladi Lapang dalam hal konsumsi, transportasi, akomodasi, peralatan/logistik, kesehatan, dan keamanan untuk setiap kegiatan mulai dari tahap perencanaan, persiapan, pelaksanaan, sampai evaluasi; dan
e. koordinator teknis latihan, bertugas mengoordinasikan dan memfasilitasi Gladi Lapang dalam hal substansi, teknis, operasional dan logistik dan menyusun rencana detail seluruh kegiatan Gladi Lapang mulai dari tahap persiapan, pelaksanaan, sampai evaluasi.
Gambar 3. Struktur Penyelenggaraan Gladi Lapang pada Saat Perencanaan Kegiatan
2. Pada saat pelaksanaan kegiatan adalah sebagai berikut.
a. Koordinator teknis latihan yang beralih fungsi menjadi koordinator pengawas dan pengendali, bertugas mengawasi dan mengendalikan seluruh kegiatan pelaksanaan Gladi Lapang dengan dibantu oleh pengawas dan pengendali operasional, pengawas dan pengendali materi gladi, dan pencatat waktu.
b. Fasilitator, bertugas mempelajari skenario dan materi Gladi Lapang, memfinalkan ROL, menyusun berbagai pertanyaan yang akan digunakan fasilitator dalam diskusi, dan menyusun materi visual.
c. Notulis, bertugas mencatat seluruh poin penting dan memastikan agar semua isu yang didiskusikan tercatat sebagai dasar pertimbangan dalam perumusan evaluasi, rekomendasi, dan laporan.', 'BAB III (lanjutan 3)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (898, 'juklak-4-2026', 32, 'lain', 'BAB III (lanjutan 4)', NULL, 18, 'd. Tim evaluasi, bertugas menyusun perangkat evaluasi untuk setiap tahap kegiatan dan melakukan evaluasi (After Action Review/AAR) terhadap rangkaian kegiatan Gladi Ruang.
e. Pelaku, bertugas hadir sebelum acara dimulai agar dapat mengorientasi diri dengan kondisi/situasi, mengikuti sesi pembekalan, dan berperan aktif dalam keseluruhan kegiatan Gladi Lapang hingga acara penutupan.
f. Pengamat, bertugas mengamati jalannya Gladi Lapang dan mengisi Lembar Pengamat serta mengembalikannya kepada penyelenggara Gladi Lapang.
Gambar 4. Struktur Penyelenggaraan Gladi Lapang pada Saat Pelaksanaan Kegiatan C. Pelaku Gladi Lapang Pelaku Gladi Lapang sebagaimana disebutkan sebelumnya, dapat berasal dari unsur pemerintah daerah, pemerintah, Tentara Nasional Indonesia, Kepolisian Republik Indonesia, dan masyarakat. Pelaksanaan Gladi Lapang perlu mengikutsertakan unsur komunitas di daerah yang menjadi Pelaku atau pengampu fungsi-fungsi manajemen kedaruratan bencana.
Untuk mengetahui Pelaku yang perlu dilibatkan dalam Gladi Lapang, penyelenggara dapat melihat pihak-pihak yang tercantum dalam dokumen rencana kontingensi, antara lain:
1. Pemerintah, mencakup Bupati/Walikota, Wakil Bupati/Walikota, beserta jajarannya;
2. Tentara Nasional Indonesia beserta jajarannya;
3. Kepolisian Republik Indonesia beserta jajarannya;
4. Perangkat Daerah yang mempunyai tugas dalam penanggulangan bencana dan darurat kemanusiaan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (898, 'd. Tim evaluasi, bertugas menyusun perangkat evaluasi untuk setiap tahap kegiatan dan melakukan evaluasi (After Action Review/AAR) terhadap rangkaian kegiatan Gladi Ruang.
e. Pelaku, bertugas hadir sebelum acara dimulai agar dapat mengorientasi diri dengan kondisi/situasi, mengikuti sesi pembekalan, dan berperan aktif dalam keseluruhan kegiatan Gladi Lapang hingga acara penutupan.
f. Pengamat, bertugas mengamati jalannya Gladi Lapang dan mengisi Lembar Pengamat serta mengembalikannya kepada penyelenggara Gladi Lapang.
Gambar 4. Struktur Penyelenggaraan Gladi Lapang pada Saat Pelaksanaan Kegiatan C. Pelaku Gladi Lapang Pelaku Gladi Lapang sebagaimana disebutkan sebelumnya, dapat berasal dari unsur pemerintah daerah, pemerintah, Tentara Nasional Indonesia, Kepolisian Republik Indonesia, dan masyarakat. Pelaksanaan Gladi Lapang perlu mengikutsertakan unsur komunitas di daerah yang menjadi Pelaku atau pengampu fungsi-fungsi manajemen kedaruratan bencana.
Untuk mengetahui Pelaku yang perlu dilibatkan dalam Gladi Lapang, penyelenggara dapat melihat pihak-pihak yang tercantum dalam dokumen rencana kontingensi, antara lain:
1. Pemerintah, mencakup Bupati/Walikota, Wakil Bupati/Walikota, beserta jajarannya;
2. Tentara Nasional Indonesia beserta jajarannya;
3. Kepolisian Republik Indonesia beserta jajarannya;
4. Perangkat Daerah yang mempunyai tugas dalam penanggulangan bencana dan darurat kemanusiaan;', 'BAB III (lanjutan 4)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (899, 'juklak-4-2026', 33, 'lain', 'BAB III (lanjutan 5)', NULL, 19, '5. Komunitas kecamatan, kelurahan, desa, nagari/dusun, sekolah, pasar, tempat wisata, terminal/pelabuhan/bandara, pusat perbelanjaan, dan komunitas lainnya;
6. Organisasi nonpemerintah: PMI, SAR, RAPI, ORARI, LSM, kelompok masyarakat, akademisi, swasta, relawan, dan media;
7. Organisasi Komando PDB dengan struktur keanggotaan sesuai dokumen rencana kontingensi atau disesuaikan dengan skala Gladi Lapang; dan
8. Pendamping, mencakup BPBD Provinsi, BNPB, dan klaster PB.
Dalam pelaksanaan Gladi Lapang dinilai penting untuk mengikutsertakan kelompok masyarakat rentan (anak, para penyandang disabilitas, perempuan, dan orang lanjut usia). Pelibatan kelompok rentan dengan kebutuhan dan dukungan khusus dalam simulasi memberikan kesempatan kepada para penyedia bantuan untuk menguji strategi dan peralatan pendukung yang direncanakan untuk digunakan mulai dari saat penyebaran peringatan dini, evakuasi, sampai pemulangan.
D. Sarana Prasarana dan Bantuan Darurat Bencana Gladi Lapang dirancang sebagai latihan simulasi gabungan yang melibatkan berbagai unsur di daerah dan menyerupai kejadian yang sesungguhnya. Oleh karena itu, pelaksanaan Gladi Lapang perlu menggunakan prasarana, sarana, dan bantuan darurat bencana yang sesungguhnya, sebagaimana tercantum dalam Rencana Kontingensi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (899, '5. Komunitas kecamatan, kelurahan, desa, nagari/dusun, sekolah, pasar, tempat wisata, terminal/pelabuhan/bandara, pusat perbelanjaan, dan komunitas lainnya;
6. Organisasi nonpemerintah: PMI, SAR, RAPI, ORARI, LSM, kelompok masyarakat, akademisi, swasta, relawan, dan media;
7. Organisasi Komando PDB dengan struktur keanggotaan sesuai dokumen rencana kontingensi atau disesuaikan dengan skala Gladi Lapang; dan
8. Pendamping, mencakup BPBD Provinsi, BNPB, dan klaster PB.
Dalam pelaksanaan Gladi Lapang dinilai penting untuk mengikutsertakan kelompok masyarakat rentan (anak, para penyandang disabilitas, perempuan, dan orang lanjut usia). Pelibatan kelompok rentan dengan kebutuhan dan dukungan khusus dalam simulasi memberikan kesempatan kepada para penyedia bantuan untuk menguji strategi dan peralatan pendukung yang direncanakan untuk digunakan mulai dari saat penyebaran peringatan dini, evakuasi, sampai pemulangan.
D. Sarana Prasarana dan Bantuan Darurat Bencana Gladi Lapang dirancang sebagai latihan simulasi gabungan yang melibatkan berbagai unsur di daerah dan menyerupai kejadian yang sesungguhnya. Oleh karena itu, pelaksanaan Gladi Lapang perlu menggunakan prasarana, sarana, dan bantuan darurat bencana yang sesungguhnya, sebagaimana tercantum dalam Rencana Kontingensi.', 'BAB III (lanjutan 5)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (900, 'juklak-4-2026', 34, 'lain', 'BAB III (lanjutan 6)', NULL, 20, 'Pilihan jenis dan jumlah prasarana, sarana, dan bantuan darurat bencana dapat disesuaikan dengan besaran Gladi Lapang yang akan diselenggarakan. Dalam hal Gladi Lapang diselenggarakan dengan skala kecil-medium, penyelenggara dapat memilih sampel-sampel dari prasarana, sarana, dan jenis bantuan darurat yang dipandang penting untuk diujikan.
Contoh prasarana untuk lokasi Gladi Lapang terpadu dapat berupa:
1. kantor Bupati/Walikota sebagai pusat komando utama;
2. ruang Pusdalops BPBD atau kantor lain yang difungsikan sebagai pusat informasi dan peringatan dini daerah;
3. ruang/kantor Pemerintah Daerah, Tentara Nasional Indonesia, Kepolisian Republik Indonesia, Perangkat Daerah, dan organisasi nonpemerintah sebagai pelaku;
4. fasilitas umum (sekolah, pasar, tempat wisata, rumah sakit/pusat pelayanan kesehatan, jembatan, terminal, dll.), serta rumah penduduk, lokasi di kampung, dusun, RT/RW, dan tempat-tempat lain yang relevan; dan
5. jalur-jalur evakuasi, titik kumpul, tempat evakuasi sementara dan tempat evakuasi akhir berupa gedung atau lapangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (900, 'Pilihan jenis dan jumlah prasarana, sarana, dan bantuan darurat bencana dapat disesuaikan dengan besaran Gladi Lapang yang akan diselenggarakan. Dalam hal Gladi Lapang diselenggarakan dengan skala kecil-medium, penyelenggara dapat memilih sampel-sampel dari prasarana, sarana, dan jenis bantuan darurat yang dipandang penting untuk diujikan.
Contoh prasarana untuk lokasi Gladi Lapang terpadu dapat berupa:
1. kantor Bupati/Walikota sebagai pusat komando utama;
2. ruang Pusdalops BPBD atau kantor lain yang difungsikan sebagai pusat informasi dan peringatan dini daerah;
3. ruang/kantor Pemerintah Daerah, Tentara Nasional Indonesia, Kepolisian Republik Indonesia, Perangkat Daerah, dan organisasi nonpemerintah sebagai pelaku;
4. fasilitas umum (sekolah, pasar, tempat wisata, rumah sakit/pusat pelayanan kesehatan, jembatan, terminal, dll.), serta rumah penduduk, lokasi di kampung, dusun, RT/RW, dan tempat-tempat lain yang relevan; dan
5. jalur-jalur evakuasi, titik kumpul, tempat evakuasi sementara dan tempat evakuasi akhir berupa gedung atau lapangan.', 'BAB III (lanjutan 6)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (901, 'juklak-4-2026', 35, 'lain', 'BAB III (lanjutan 7)', NULL, 20, 'Gladi Lapang juga melatih pengoperasian beragam peralatan pendukung komunikasi dan transportasi. Peralatan komunikasi digunakan untuk mendukung koordinasi antar pelaku dan menyampaikan peringatan dini serta pemutakhiran informasi. Peran perangkat daerah seperti dinas yang mengurusi komunikasi, informatika, dan statistik dan termasuk institusi seperti Rapat Antar Penduduk Indonesia, dan Organisasi Amatir Radio Indonesia banyak memberikan bantuan teknis untuk kelancaran simulasi. Alat transportasi mendukung mobilisasi personel dan barang yang dapat didukung oleh Tentara Nasional Indonesia, Kepolisian Republik Indonesia, dan beberapa Perangkat Daerah.
Semua sarana yang digunakan dalam Gladi Lapang sebaiknya yang senyatanya akan dioperasikan pada saat kedaruratan bencana. Ini akan membantu penilaian atas keefektifan peralatan saat dioperasikan dalam situasi darurat bencana yang sesungguhnya. Jumlah alat pendukung yang digunakan disesuaikan dengan kebutuhan dan tujuan gladi. Alat komunikasi dan transportasi dapat berupa:
1. Alat komunikasi untuk koordinasi, seperti: Radio UHF, Radio VHF, Radio RIG, Hand Phone (HP), telepon, alat komunikasi lain yang relevan
2. Alat komunikasi untuk diseminasi peringatan dini, seperti: pengeras suara/sirine, kentongan, dan alat lain yang disepakati di komunitas, radio siaran dan/atau televisi di daerah
3. Alat transportasi: truk, ambulans, kendaraan bermotor (roda 4, roda 3, roda 2), dan alat pendukung transportasi lain yang relevan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (901, 'Gladi Lapang juga melatih pengoperasian beragam peralatan pendukung komunikasi dan transportasi. Peralatan komunikasi digunakan untuk mendukung koordinasi antar pelaku dan menyampaikan peringatan dini serta pemutakhiran informasi. Peran perangkat daerah seperti dinas yang mengurusi komunikasi, informatika, dan statistik dan termasuk institusi seperti Rapat Antar Penduduk Indonesia, dan Organisasi Amatir Radio Indonesia banyak memberikan bantuan teknis untuk kelancaran simulasi. Alat transportasi mendukung mobilisasi personel dan barang yang dapat didukung oleh Tentara Nasional Indonesia, Kepolisian Republik Indonesia, dan beberapa Perangkat Daerah.
Semua sarana yang digunakan dalam Gladi Lapang sebaiknya yang senyatanya akan dioperasikan pada saat kedaruratan bencana. Ini akan membantu penilaian atas keefektifan peralatan saat dioperasikan dalam situasi darurat bencana yang sesungguhnya. Jumlah alat pendukung yang digunakan disesuaikan dengan kebutuhan dan tujuan gladi. Alat komunikasi dan transportasi dapat berupa:
1. Alat komunikasi untuk koordinasi, seperti: Radio UHF, Radio VHF, Radio RIG, Hand Phone (HP), telepon, alat komunikasi lain yang relevan
2. Alat komunikasi untuk diseminasi peringatan dini, seperti: pengeras suara/sirine, kentongan, dan alat lain yang disepakati di komunitas, radio siaran dan/atau televisi di daerah
3. Alat transportasi: truk, ambulans, kendaraan bermotor (roda 4, roda 3, roda 2), dan alat pendukung transportasi lain yang relevan.', 'BAB III (lanjutan 7)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (902, 'juklak-4-2026', 36, 'lain', 'BAB III (lanjutan 8)', NULL, 20, 'Pengerahan sumber daya bantuan kebutuhan dasar merupakan bagian yang tidak terpisahkan dari operasi tanggap darurat bencana. Lembaga pemerintah dan nonpemerintah penyedia bantuan darurat bencana di daerah perlu diikutsertakan dalam Gladi Lapang untuk memberi kesempatan untuk mempraktikkan strategi pengerahan bantuan.
Penggunaan barang bantuan yang secara nyata akan dioperasikan dalam kedaruratan bencana sangat disarankan untuk menilai efektivitas dan efisiensinya. Ragam barang bantuan dapat dilihat dalam dokumen rencana kontingensi. Banyaknya bantuan yang disimulasikan disesuaikan dengan tujuan Gladi Lapang dan kemampuan daerah.
Ragam barang bantuan antara lain dapat berupa:
1. bantuan medis, dapur umum, shelter/tenda, air dan sanitasi, dan bantuan medis lainnya;
2. alat bantu untuk kelompok rentan; dan
3. jenis bantuan lain yang akan diujicobakan.
E. Penatalaksanaan Gladi Lapang Tabel 2. Tata Laksana Gladi Lapang Tata Laksana Prosedur Pelaksanaan Fokus Uji Kemampuan
a. Kajian Skenario kejadian bencana Realistis/tidak realistis Risiko, yang diasumsikan atau Renkon dikalkulasi
b. Peringatan a. Penerimaan informasi a. Koordinasi Dini potensi bahaya atau b. Peralatan dan jaring peringatan dari lembaga komunikasi terkait (BMKG, c. Prosedur Tetap PVMBG/ESDM, BWS) atau d. Pengetahuan dan sumber peringatan lain keterampilan personel (petugas, masyarakat, alat sensor).
b. Pengambilan keputusan di daerah (Pemerintah/ Pusdalops)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (902, 'Pengerahan sumber daya bantuan kebutuhan dasar merupakan bagian yang tidak terpisahkan dari operasi tanggap darurat bencana. Lembaga pemerintah dan nonpemerintah penyedia bantuan darurat bencana di daerah perlu diikutsertakan dalam Gladi Lapang untuk memberi kesempatan untuk mempraktikkan strategi pengerahan bantuan.
Penggunaan barang bantuan yang secara nyata akan dioperasikan dalam kedaruratan bencana sangat disarankan untuk menilai efektivitas dan efisiensinya. Ragam barang bantuan dapat dilihat dalam dokumen rencana kontingensi. Banyaknya bantuan yang disimulasikan disesuaikan dengan tujuan Gladi Lapang dan kemampuan daerah.
Ragam barang bantuan antara lain dapat berupa:
1. bantuan medis, dapur umum, shelter/tenda, air dan sanitasi, dan bantuan medis lainnya;
2. alat bantu untuk kelompok rentan; dan
3. jenis bantuan lain yang akan diujicobakan.
E. Penatalaksanaan Gladi Lapang Tabel 2. Tata Laksana Gladi Lapang Tata Laksana Prosedur Pelaksanaan Fokus Uji Kemampuan
a. Kajian Skenario kejadian bencana Realistis/tidak realistis Risiko, yang diasumsikan atau Renkon dikalkulasi
b. Peringatan a. Penerimaan informasi a. Koordinasi Dini potensi bahaya atau b. Peralatan dan jaring peringatan dari lembaga komunikasi terkait (BMKG, c. Prosedur Tetap PVMBG/ESDM, BWS) atau d. Pengetahuan dan sumber peringatan lain keterampilan personel (petugas, masyarakat, alat sensor).
b. Pengambilan keputusan di daerah (Pemerintah/ Pusdalops)', 'BAB III (lanjutan 8)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (903, 'juklak-4-2026', 37, 'lain', 'BAB III (lanjutan 9)', NULL, 21, 'c. Penyebaran Peringatan Dini dan arahan kepada petugas/sektor/pemangku kepentingan.
d. Penerimaan dan penyebaran peringatan dini kepada masyarakat.
c. Rencana a. Jalur dan rambu evakuasi a. Koordinasi Evakuasi b. Strategi evakuasi komunitas b. Ketepatan pilihan jalur
c. Keefektifan cara evakuasi
d. Peralatan evakuasi
e. Penyelamatan dan penanganan kecelakaan
d. Rencana a. Aktivasi Sistem Komando a. Koordinasi Operasi Penanganan Darurat b. Pengetahuan dan Bencana keterampilan personel
b. Aktivasi tindakan operasi
c. Aktivasi Pos Komando, Pos Lapangan, Pos Pendamping
e. Tanggap a. Pengerahan bantuan a. Koordinasi Darurat kemanusiaan b. Pengerahan sumber daya
b. Manajemen informasi dan peralatan
c. Sistem manajemen informasi
d. Pengetahuan dan keterampilan personel
1. Tahapan Perencanaan Gladi Lapang Pada tahap perencanaan, kebanyakan pekerjaan dilakukan oleh Koordinator Bidang Teknis dan Tim dibantu oleh Koordinator lain.
Pengembangan konsep dan materi Gladi Lapang perlu mempertimbangkan komponen tata laksana Gladi Lapang. Setiap perencanaan dilakukan melalui mekanisme rapat.
Tahap ini meliputi:
a. Rapat Penyusunan ROL Gladi Lapang ROL merupakan dokumen dasar yang dibuat oleh Ketua Penyelenggara, Koordinator dan pengusul setelah gagasan untuk menyelenggarakan Gladi Lapang disetujui. ROL berupa matriks yang memuat gambaran umum rencana gladi. ROL disusun sesuai Format 2 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (903, 'c. Penyebaran Peringatan Dini dan arahan kepada petugas/sektor/pemangku kepentingan.
d. Penerimaan dan penyebaran peringatan dini kepada masyarakat.
c. Rencana a. Jalur dan rambu evakuasi a. Koordinasi Evakuasi b. Strategi evakuasi komunitas b. Ketepatan pilihan jalur
c. Keefektifan cara evakuasi
d. Peralatan evakuasi
e. Penyelamatan dan penanganan kecelakaan
d. Rencana a. Aktivasi Sistem Komando a. Koordinasi Operasi Penanganan Darurat b. Pengetahuan dan Bencana keterampilan personel
b. Aktivasi tindakan operasi
c. Aktivasi Pos Komando, Pos Lapangan, Pos Pendamping
e. Tanggap a. Pengerahan bantuan a. Koordinasi Darurat kemanusiaan b. Pengerahan sumber daya
b. Manajemen informasi dan peralatan
c. Sistem manajemen informasi
d. Pengetahuan dan keterampilan personel
1. Tahapan Perencanaan Gladi Lapang Pada tahap perencanaan, kebanyakan pekerjaan dilakukan oleh Koordinator Bidang Teknis dan Tim dibantu oleh Koordinator lain.
Pengembangan konsep dan materi Gladi Lapang perlu mempertimbangkan komponen tata laksana Gladi Lapang. Setiap perencanaan dilakukan melalui mekanisme rapat.
Tahap ini meliputi:
a. Rapat Penyusunan ROL Gladi Lapang ROL merupakan dokumen dasar yang dibuat oleh Ketua Penyelenggara, Koordinator dan pengusul setelah gagasan untuk menyelenggarakan Gladi Lapang disetujui. ROL berupa matriks yang memuat gambaran umum rencana gladi. ROL disusun sesuai Format 2 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.', 'BAB III (lanjutan 9)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (904, 'juklak-4-2026', 38, 'lain', 'BAB III (lanjutan 10)', NULL, 22, 'b. Rapat Penyusunan Konsep RGB Gladi Lapang Konsep RGB merupakan kerangka dasar penyelenggaraan Gladi Lapang yang disusun oleh Penyelenggara. Konsep RGB memuat latar belakang, dasar, matriks inventarisasi permasalahan (identifikasi permasalahan yang ada di daerah), pokok-pokok penyelenggaraan simulasi, dan skenario Gladi Lapang. Terdapat 2 (dua) skenario yang dikembangkan, yaitu skenario strategis dan skenario taktis. Skenario strategis mengacu pada hasil KRB yang sudah dikembangkan berdasarkan analisis ilmiah atau pengetahuan yang menggunakan data sahih (lihat kajian risiko dalam dokumen rencana kontingensi). RGB disusun sesuai Format 3 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
c. Rapat Konsultasi RGB Gladi Lapang Perwakilan pelaku dihadirkan dalam rapat konsultasi untuk menggali masukan dan mengakomodasi kepentingan Pelaku ke dalam draf dokumen RGB Gladi Lapang. Kesempatan ini juga menjadi wahana untuk mensosialisasikan rencana kesiapsiagaan secara umum dan konsep Gladi Lapang secara khusus. Berdasarkan masukan dari para pelaku Gladi Lapang, penyelenggara pada kesempatan terpisah dapat melengkapi dokumen RGB secara singkat dan jelas sehingga mudah dipahami oleh para pengguna.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (904, 'b. Rapat Penyusunan Konsep RGB Gladi Lapang Konsep RGB merupakan kerangka dasar penyelenggaraan Gladi Lapang yang disusun oleh Penyelenggara. Konsep RGB memuat latar belakang, dasar, matriks inventarisasi permasalahan (identifikasi permasalahan yang ada di daerah), pokok-pokok penyelenggaraan simulasi, dan skenario Gladi Lapang. Terdapat 2 (dua) skenario yang dikembangkan, yaitu skenario strategis dan skenario taktis. Skenario strategis mengacu pada hasil KRB yang sudah dikembangkan berdasarkan analisis ilmiah atau pengetahuan yang menggunakan data sahih (lihat kajian risiko dalam dokumen rencana kontingensi). RGB disusun sesuai Format 3 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
c. Rapat Konsultasi RGB Gladi Lapang Perwakilan pelaku dihadirkan dalam rapat konsultasi untuk menggali masukan dan mengakomodasi kepentingan Pelaku ke dalam draf dokumen RGB Gladi Lapang. Kesempatan ini juga menjadi wahana untuk mensosialisasikan rencana kesiapsiagaan secara umum dan konsep Gladi Lapang secara khusus. Berdasarkan masukan dari para pelaku Gladi Lapang, penyelenggara pada kesempatan terpisah dapat melengkapi dokumen RGB secara singkat dan jelas sehingga mudah dipahami oleh para pengguna.', 'BAB III (lanjutan 10)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (905, 'juklak-4-2026', 39, 'lain', 'BAB III (lanjutan 11)', NULL, 22, 'd. Rapat Finalisasi RGB dan Materi Simulasi Pertemuan ini memaparkan draf awal dokumen RGB Gladi Lapang yang sudah lengkap kepada penyelenggara dan perwakilan Pelaku. Pada tahap ini, Tim Evaluasi sudah ditetapkan dan diikutsertakan dalam rapat. Kesempatan ini juga dapat digunakan untuk mengidentifikasi kebutuhan pendukung Gladi Lapang dan sumber untuk memenuhi kebutuhan dari semua peserta rapat.
e. Rapat Penyusunan Arahan Gladi Lapang Dokumen final RGB memberikan pemahaman tentang konsep lengkap pelaksanaan Gladi Lapang sehingga dapat digunakan untuk mengembangkan dokumen Arahan dan dokumen Petunjuk untuk Pengawas dan Pengendali, Tim Evaluasi, dan Pelaku Gladi Lapang. Arahan akan digunakan untuk sosialisasi kepada pihak-pihak terkait. Penyelenggara pada kesempatan terpisah dapat melengkapi draf dokumen Arahan dan Petunjuk Gladi Lapang dalam format yang mudah dipahami oleh para pengguna.
f. Kunjungan Lapangan Kunjungan lapangan dilakukan untuk mendapatkan pemahaman mengenai kesesuaian tempat/lokasi sebagai prasarana untuk simulasi dan mengidentifikasi hal-hal atau fasilitas pendukung yang masih perlu dilengkapi di lokasi tersebut. Banyaknya lokasi yang dipilih disesuaikan dengan kemampuan penyelenggaraan simulasi. Pada saat kunjungan ini dilakukan koordinasi dengan perangkat desa atau kelurahan yang bakal dijadikan lokasi pelaksanaan karena mereka termasuk sebagai Pelaku Gladi Lapang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (905, 'd. Rapat Finalisasi RGB dan Materi Simulasi Pertemuan ini memaparkan draf awal dokumen RGB Gladi Lapang yang sudah lengkap kepada penyelenggara dan perwakilan Pelaku. Pada tahap ini, Tim Evaluasi sudah ditetapkan dan diikutsertakan dalam rapat. Kesempatan ini juga dapat digunakan untuk mengidentifikasi kebutuhan pendukung Gladi Lapang dan sumber untuk memenuhi kebutuhan dari semua peserta rapat.
e. Rapat Penyusunan Arahan Gladi Lapang Dokumen final RGB memberikan pemahaman tentang konsep lengkap pelaksanaan Gladi Lapang sehingga dapat digunakan untuk mengembangkan dokumen Arahan dan dokumen Petunjuk untuk Pengawas dan Pengendali, Tim Evaluasi, dan Pelaku Gladi Lapang. Arahan akan digunakan untuk sosialisasi kepada pihak-pihak terkait. Penyelenggara pada kesempatan terpisah dapat melengkapi draf dokumen Arahan dan Petunjuk Gladi Lapang dalam format yang mudah dipahami oleh para pengguna.
f. Kunjungan Lapangan Kunjungan lapangan dilakukan untuk mendapatkan pemahaman mengenai kesesuaian tempat/lokasi sebagai prasarana untuk simulasi dan mengidentifikasi hal-hal atau fasilitas pendukung yang masih perlu dilengkapi di lokasi tersebut. Banyaknya lokasi yang dipilih disesuaikan dengan kemampuan penyelenggaraan simulasi. Pada saat kunjungan ini dilakukan koordinasi dengan perangkat desa atau kelurahan yang bakal dijadikan lokasi pelaksanaan karena mereka termasuk sebagai Pelaku Gladi Lapang.', 'BAB III (lanjutan 11)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (906, 'juklak-4-2026', 40, 'lain', 'BAB III (lanjutan 12)', NULL, 23, '2. Tahap Persiapan Pada tahap persiapan, Tim Gladi Lapang perlu mempertimbangkan komponen tata laksana Gladi Lapang. Setiap perencanaan dilakukan melalui mekanisme rapat.
a. Penyiapan Dokumen dan Materi Simulasi Koordinator Bidang Teknis memastikan semua materi simulasi yang terdiri atas Rencana Operasi Gladi Lapang, RGB Gladi Lapang, Arahan Gladi Lapang, Petunjuk untuk Pengawas dan Pengendali, Tim Evaluasi, dan Pelaku difinalkan dan dicetak untuk dibagikan kepada peserta sesuai tugasnya sebagai rujukan dalam pelaksanaan Gladi Lapang.
b. Kesiapan Pelaku Koordinator Bidang Pelibatan Komunitas memastikan agar setiap unsur komunitas yang akan terlibat sudah memahami rencana pelaksanaan Gladi Lapang sesuai RGB Gladi Lapang serta peran dan tugas masing-masing Pelaku. Pusdalops, Pimpinan Daerah, Perangkat Daerah, perangkat kecamatan, perangkat desa/kelurahan, dan organisasi nonpemerintah sudah memahami kebijakan, sistem, rencana dan prosedur yang dijalankan di masing-masing lembaganya. Selain itu, komunitas juga sudah harus memahami prosedur peringatan dini dan rencana evakuasi. Kesiapan ini dilakukan melalui sosialisasi atau pertemuan-pertemuan dengan komunitas untuk memahami kembali prosedur dan rencana yang berlaku di komunitasnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (906, '2. Tahap Persiapan Pada tahap persiapan, Tim Gladi Lapang perlu mempertimbangkan komponen tata laksana Gladi Lapang. Setiap perencanaan dilakukan melalui mekanisme rapat.
a. Penyiapan Dokumen dan Materi Simulasi Koordinator Bidang Teknis memastikan semua materi simulasi yang terdiri atas Rencana Operasi Gladi Lapang, RGB Gladi Lapang, Arahan Gladi Lapang, Petunjuk untuk Pengawas dan Pengendali, Tim Evaluasi, dan Pelaku difinalkan dan dicetak untuk dibagikan kepada peserta sesuai tugasnya sebagai rujukan dalam pelaksanaan Gladi Lapang.
b. Kesiapan Pelaku Koordinator Bidang Pelibatan Komunitas memastikan agar setiap unsur komunitas yang akan terlibat sudah memahami rencana pelaksanaan Gladi Lapang sesuai RGB Gladi Lapang serta peran dan tugas masing-masing Pelaku. Pusdalops, Pimpinan Daerah, Perangkat Daerah, perangkat kecamatan, perangkat desa/kelurahan, dan organisasi nonpemerintah sudah memahami kebijakan, sistem, rencana dan prosedur yang dijalankan di masing-masing lembaganya. Selain itu, komunitas juga sudah harus memahami prosedur peringatan dini dan rencana evakuasi. Kesiapan ini dilakukan melalui sosialisasi atau pertemuan-pertemuan dengan komunitas untuk memahami kembali prosedur dan rencana yang berlaku di komunitasnya.', 'BAB III (lanjutan 12)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (907, 'juklak-4-2026', 41, 'lain', 'BAB III (lanjutan 13)', NULL, 23, 'c. Prasarana, Sarana dan Bantuan Darurat Bencana Koordinator Bidang Pendukung memastikan bahwa semua prasarana, sarana, dan bantuan kemanusiaan sudah dipersiapkan untuk dioperasikan dalam Gladi Lapang. Daftar periksa berisi rincian sumber daya di atas dapat membantu pengecekan kesiapan.
Pada tahap ini, masing-masing Pelaku diharapkan sudah siap untuk mengoperasikan:
1) prasarana, seperti ruang pusat pengendalian operasi, kantor-kantor, fasilitas umum, jalur dan tempat evakuasi, dan lainnya; dan 2) sarana, seperti peralatan komunikasi/koordinasi, penyebaran dan penerimaan peringatan dini/arahan, alat-alat transportasi, dan peralatan pendukung;
Pelaku diharapkan sudah mengetahui jenis dan jumlah bantuan kemanusiaan yang diikuti dengan pengecekan pelaku yang dapat dilakukan melalui pelaksanaan rapat bersama atau kunjungan lapangan apabila diperlukan.
d. Administrasi Koordinator Bidang Administrasi memastikan agar semua urusan administrasi terkait persuratan, undangan, konfirmasi, persetujuan, dokumentasi Gladi Lapang, keuangan, dan lainnya sudah disiapkan dan dilakukan sesuai rencana.
e. Briefing Ketua/Wakil bersama Koordinator Bidang Teknis (Pengawas dan Pengendalian) memberikan briefing kepada:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (907, 'c. Prasarana, Sarana dan Bantuan Darurat Bencana Koordinator Bidang Pendukung memastikan bahwa semua prasarana, sarana, dan bantuan kemanusiaan sudah dipersiapkan untuk dioperasikan dalam Gladi Lapang. Daftar periksa berisi rincian sumber daya di atas dapat membantu pengecekan kesiapan.
Pada tahap ini, masing-masing Pelaku diharapkan sudah siap untuk mengoperasikan:
1) prasarana, seperti ruang pusat pengendalian operasi, kantor-kantor, fasilitas umum, jalur dan tempat evakuasi, dan lainnya; dan 2) sarana, seperti peralatan komunikasi/koordinasi, penyebaran dan penerimaan peringatan dini/arahan, alat-alat transportasi, dan peralatan pendukung;
Pelaku diharapkan sudah mengetahui jenis dan jumlah bantuan kemanusiaan yang diikuti dengan pengecekan pelaku yang dapat dilakukan melalui pelaksanaan rapat bersama atau kunjungan lapangan apabila diperlukan.
d. Administrasi Koordinator Bidang Administrasi memastikan agar semua urusan administrasi terkait persuratan, undangan, konfirmasi, persetujuan, dokumentasi Gladi Lapang, keuangan, dan lainnya sudah disiapkan dan dilakukan sesuai rencana.
e. Briefing Ketua/Wakil bersama Koordinator Bidang Teknis (Pengawas dan Pengendalian) memberikan briefing kepada:', 'BAB III (lanjutan 13)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (908, 'juklak-4-2026', 42, 'lain', 'BAB III (lanjutan 14)', NULL, 24, '1) organisasi Komando PDB, mengenai peran dan fungsinya, skenario kejadian, ruang Pos Komando, dan peralatan pendukung, serta hal lain yang diperlukan; dan 2) tim evaluasi dan tim pengamat, mengenai peran dan fungsi, skenario kejadian, pengisian formulir evaluasi dan observasi, serta lokasi-lokasi penempatannya.
h. Gladi Bersih Gladi bersih merupakan persiapan terakhir yang dilakukan sebagai uji coba sebelum pelaksanaan Gladi Lapang untuk memastikan persiapan sudah sesuai sehingga pada hari penyelenggaraannya, Gladi Lapang dapat berjalan lancar dan berhasil guna.
Gladi bersih bertujuan memantapkan koordinasi antar pelaku yang terlibat dan tindakan-tindakan yang sudah direncanakan. Gladi bersih memberikan kesempatan kepada:
1) penyelenggara Gladi Lapang dan pelaku, untuk mengikuti dengan teliti berjalannya agenda acara Gladi Lapang, mengevaluasi semua prosesnya, dan memperbaiki hal-hal yang perlu disempurnakan; dan 2) pelaku Gladi Lapang, untuk melatih kembali koordinasi dan komunikasi serta pengoperasian peralatan sesuai peran masing-masing agar lebih percaya diri.
Pada dasarnya Gladi bersih menjadi latihan terakhir yang dijalankan sesuai dengan Agenda Acara Gladi Lapang. Secara singkat Agenda Acara Gladi Lapang berisi kegiatan-kegiatan dengan alur waktu sesuai rencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (908, '1) organisasi Komando PDB, mengenai peran dan fungsinya, skenario kejadian, ruang Pos Komando, dan peralatan pendukung, serta hal lain yang diperlukan; dan 2) tim evaluasi dan tim pengamat, mengenai peran dan fungsi, skenario kejadian, pengisian formulir evaluasi dan observasi, serta lokasi-lokasi penempatannya.
h. Gladi Bersih Gladi bersih merupakan persiapan terakhir yang dilakukan sebagai uji coba sebelum pelaksanaan Gladi Lapang untuk memastikan persiapan sudah sesuai sehingga pada hari penyelenggaraannya, Gladi Lapang dapat berjalan lancar dan berhasil guna.
Gladi bersih bertujuan memantapkan koordinasi antar pelaku yang terlibat dan tindakan-tindakan yang sudah direncanakan. Gladi bersih memberikan kesempatan kepada:
1) penyelenggara Gladi Lapang dan pelaku, untuk mengikuti dengan teliti berjalannya agenda acara Gladi Lapang, mengevaluasi semua prosesnya, dan memperbaiki hal-hal yang perlu disempurnakan; dan 2) pelaku Gladi Lapang, untuk melatih kembali koordinasi dan komunikasi serta pengoperasian peralatan sesuai peran masing-masing agar lebih percaya diri.
Pada dasarnya Gladi bersih menjadi latihan terakhir yang dijalankan sesuai dengan Agenda Acara Gladi Lapang. Secara singkat Agenda Acara Gladi Lapang berisi kegiatan-kegiatan dengan alur waktu sesuai rencana.', 'BAB III (lanjutan 14)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (909, 'juklak-4-2026', 43, 'lain', 'BAB III (lanjutan 15)', NULL, 24, 'Tabel 3. Contoh Agenda Acara Kegiatan Gladi Lapang Pukul Tahapan Kegiatan Tindakan … Pra simulasi • Pemerintah dan masyarakat beraktivitas sesuai kegiatan kesehariannya 08:30 Penyebaran • Pusat Peringatan Dini menyebarkan Peringatan Dini peringatan dini dengan informasi parameter dan tingkatan ancaman 08:40 Arahan Evakuasi • Pusat Pengendalian Operasi BPBD mengambil keputusan dan menyebarkan informasi awal bencana dan arahan evakuasi kepada komunitas
• Komunitas melakukan proses evakuasi secara mandiri dan kelompok 08:50 Penetapan Status • TRC melakukan pengkajian cepat Darurat Bencana dampak bencana dan verifikasi di lapangan
• Pemerintah menetapkan Status Darurat Bencana 09:00 Aktivasi Sistem • Pemerintah/BPBD mengaktivasi Komando PDB Struktur Komando PDB
• Penunjukan Komandan PDB
• Pengaktivasian Posko PDB, dan bila diperlukan Pos Lapangan dan Pos Pendamping 09:10 Rencana Operasi • Pengumpulan laporan-laporan dari TRC serta informasi dari masyarakat dan sumber-sumber terpercaya lain
• Penyusunan Rencana Operasi berdasarkan laporan dan informasi yang terkumpul 09:20 Operasi Tanggap • Pelaksanaan operasi tanggap Darurat Bencana darurat bencana melalui kegiatan SAR, pendistribusian bantuan, dll. di komunitas yang didasarkan pada Rencana Operasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (909, 'Tabel 3. Contoh Agenda Acara Kegiatan Gladi Lapang Pukul Tahapan Kegiatan Tindakan … Pra simulasi • Pemerintah dan masyarakat beraktivitas sesuai kegiatan kesehariannya 08:30 Penyebaran • Pusat Peringatan Dini menyebarkan Peringatan Dini peringatan dini dengan informasi parameter dan tingkatan ancaman 08:40 Arahan Evakuasi • Pusat Pengendalian Operasi BPBD mengambil keputusan dan menyebarkan informasi awal bencana dan arahan evakuasi kepada komunitas
• Komunitas melakukan proses evakuasi secara mandiri dan kelompok 08:50 Penetapan Status • TRC melakukan pengkajian cepat Darurat Bencana dampak bencana dan verifikasi di lapangan
• Pemerintah menetapkan Status Darurat Bencana 09:00 Aktivasi Sistem • Pemerintah/BPBD mengaktivasi Komando PDB Struktur Komando PDB
• Penunjukan Komandan PDB
• Pengaktivasian Posko PDB, dan bila diperlukan Pos Lapangan dan Pos Pendamping 09:10 Rencana Operasi • Pengumpulan laporan-laporan dari TRC serta informasi dari masyarakat dan sumber-sumber terpercaya lain
• Penyusunan Rencana Operasi berdasarkan laporan dan informasi yang terkumpul 09:20 Operasi Tanggap • Pelaksanaan operasi tanggap Darurat Bencana darurat bencana melalui kegiatan SAR, pendistribusian bantuan, dll. di komunitas yang didasarkan pada Rencana Operasi', 'BAB III (lanjutan 15)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (910, 'juklak-4-2026', 44, 'lain', 'BAB III (lanjutan 16)', NULL, 25, '• Pemutakhiran informasi dari lembaga-lembaga bantuan kemanusiaan ke Posko PDB 11:00 Pengakhiran • Pengakhiran operasi tanggap Operasi Tanggap darurat bencana dikeluarkan Darurat Bencana sebagai penanda berakhirnya masa tanggap darurat bencana 11:30 Evaluasi • Evaluasi menyampaikan catatan-catatan praktik baik dan hal yang perlu diperbaiki.
Keterangan: Agenda kegiatan mengikuti skenario yang telah disusun oleh Tim Perancang Gladi Lapang.
Gladi bersih dilaksanakan dengan alokasi waktu yang cukup dan durasinya tidak harus sama dengan Gladi Lapang.
Gladi bersih dapat dilaksanakan di dalam atau di luar ruang dengan ketentuan sebagai berikut.
1) Tempat Gladi bersih di dalam ruang dapat menggunakan satu ruang besar atau kantor dengan pembagian ruang-ruang untuk setiap kelompok Pelaku. Peralatan pendukung seperti sound sistem/TOA, meja-kursi, dll dapat dioperasikan.
2) Tempat Gladi bersih di luar ruang dapat menggunakan tempat simulasi masing-masing Pelaku sebagaimana akan digunakan untuk pelaksanaan simulasi sesungguhnya.
3) Peralatan komunikasi yang digunakan menyesuaikan dengan realita dan kebutuhan untuk mendukung Gladi Lapang.
Sebelum melaksanakan Gladi bersih, Koordinator Pengawas dan Pengendalian memberikan arahan mengenai tujuan, proses dan hasil yang diharapkan dalam latihan terakhir tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (910, '• Pemutakhiran informasi dari lembaga-lembaga bantuan kemanusiaan ke Posko PDB 11:00 Pengakhiran • Pengakhiran operasi tanggap Operasi Tanggap darurat bencana dikeluarkan Darurat Bencana sebagai penanda berakhirnya masa tanggap darurat bencana 11:30 Evaluasi • Evaluasi menyampaikan catatan-catatan praktik baik dan hal yang perlu diperbaiki.
Keterangan: Agenda kegiatan mengikuti skenario yang telah disusun oleh Tim Perancang Gladi Lapang.
Gladi bersih dilaksanakan dengan alokasi waktu yang cukup dan durasinya tidak harus sama dengan Gladi Lapang.
Gladi bersih dapat dilaksanakan di dalam atau di luar ruang dengan ketentuan sebagai berikut.
1) Tempat Gladi bersih di dalam ruang dapat menggunakan satu ruang besar atau kantor dengan pembagian ruang-ruang untuk setiap kelompok Pelaku. Peralatan pendukung seperti sound sistem/TOA, meja-kursi, dll dapat dioperasikan.
2) Tempat Gladi bersih di luar ruang dapat menggunakan tempat simulasi masing-masing Pelaku sebagaimana akan digunakan untuk pelaksanaan simulasi sesungguhnya.
3) Peralatan komunikasi yang digunakan menyesuaikan dengan realita dan kebutuhan untuk mendukung Gladi Lapang.
Sebelum melaksanakan Gladi bersih, Koordinator Pengawas dan Pengendalian memberikan arahan mengenai tujuan, proses dan hasil yang diharapkan dalam latihan terakhir tersebut.', 'BAB III (lanjutan 16)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (911, 'juklak-4-2026', 45, 'lain', 'BAB III (lanjutan 17)', NULL, 26, 'Selama proses simulasi, dimungkinkan untuk dilakukan interupsi berupa penyampaian informasi, permintaan atau pertanyaan yang di luar skenario kepada pelaku tertentu untuk melatih pemecahan masalah (problem solving). Injeksi dipersiapkan oleh panitia dan tidak diketahui sebelumnya oleh Pelaku. Contoh Injeksi antara lain:
1) ’.... listrik di kampung kami padam, dan peralatan komunikasi tidak berfungsi, mohon dibantu ...’ 2) ’... di sini ada 4 orang terjebak reruntuhan bangunan, tolong dikirim bantuan segera ...’ 3) ’.... terjadi longsor menimpa jalur evakuasi di jalan XX ...’ 4) ’.... beberapa rumah di RT ... Dusun ... air banjir masuk ke dalam rumah sekitar 1 meter dan ada warga yang harus dievakuasi ke tempat aman ....
Tim Evaluasi melakukan fungsi monitoring selama proses pelaksanaan Gladi bersih dan memberikan hasil evaluasinya kepada penyelenggara untuk catatan perbaikan. Pada kegiatan Gladi bersih, jumlah Tim Evaluasi dan penempatannya sudah ditetapkan pada pelaksanaan Gladi Lapang yang sesungguhnya.
3. Tahap Pelaksanaan
a. Pengecekan Kesiapan Pada hari-H, sebelum pelaksanaan Gladi Lapang, Penyelenggara memastikan bahwa semua Pelaku, Tim Evaluasi dan Tim Pengamat serta perlengkapannya telah siap mengikuti kegiatan simulasi. Mempertimbangkan sebaran Pelaku di tempat/lokasi yang berbeda-beda, pengecekan kesiapannya dapat dilakukan dengan komunikasi Radio (VHF/UHF) dan telepon seluler.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (911, 'Selama proses simulasi, dimungkinkan untuk dilakukan interupsi berupa penyampaian informasi, permintaan atau pertanyaan yang di luar skenario kepada pelaku tertentu untuk melatih pemecahan masalah (problem solving). Injeksi dipersiapkan oleh panitia dan tidak diketahui sebelumnya oleh Pelaku. Contoh Injeksi antara lain:
1) ’.... listrik di kampung kami padam, dan peralatan komunikasi tidak berfungsi, mohon dibantu ...’ 2) ’... di sini ada 4 orang terjebak reruntuhan bangunan, tolong dikirim bantuan segera ...’ 3) ’.... terjadi longsor menimpa jalur evakuasi di jalan XX ...’ 4) ’.... beberapa rumah di RT ... Dusun ... air banjir masuk ke dalam rumah sekitar 1 meter dan ada warga yang harus dievakuasi ke tempat aman ....
Tim Evaluasi melakukan fungsi monitoring selama proses pelaksanaan Gladi bersih dan memberikan hasil evaluasinya kepada penyelenggara untuk catatan perbaikan. Pada kegiatan Gladi bersih, jumlah Tim Evaluasi dan penempatannya sudah ditetapkan pada pelaksanaan Gladi Lapang yang sesungguhnya.
3. Tahap Pelaksanaan
a. Pengecekan Kesiapan Pada hari-H, sebelum pelaksanaan Gladi Lapang, Penyelenggara memastikan bahwa semua Pelaku, Tim Evaluasi dan Tim Pengamat serta perlengkapannya telah siap mengikuti kegiatan simulasi. Mempertimbangkan sebaran Pelaku di tempat/lokasi yang berbeda-beda, pengecekan kesiapannya dapat dilakukan dengan komunikasi Radio (VHF/UHF) dan telepon seluler.', 'BAB III (lanjutan 17)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (912, 'juklak-4-2026', 46, 'lain', 'BAB III (lanjutan 18)', NULL, 26, 'Mengingat Gladi Lapang merupakan uji kesiapan kemampuan respons komunitas yang disimulasikan menyerupai kejadian yang sesungguhnya, Penyelenggara mempertimbangkan perlu atau tidak untuk memberikan informasi sebelumnya kepada Pelaku, Tim Evaluasi, dan Tim Pengamat pada hari-H tentang jam mulai simulasi atau pelaksanaan upacara pembukaan.
Apabila tidak diberitahu, Pelaku dapat diberikan informasi tentang kisaran waktu, misalnya simulasi akan dimulai pada sekitar pukul 08:00 WIB. Dengan tidak memberikan informasi rinci, maka akan memberikan efek kejadian yang ’sesungguhnya’, di mana bencana terjadi ketika komunitas sedang melakukan aktivitas rutin harian.
b. Penyiapan Pelaksanaan Gladi Lapang Ketua/Wakil dan Koordinator Pengawas dan Pengendalian memastikan bahwa:
1) tim evaluasi, tim pengamat, penyelenggara, atau relawan sudah berada di lokasi masing-masing dengan piranti pendukung (formulir dan alat tulis) masing-masing; dan 2) penyelenggara dan pelaku menyamakan jam sehingga proses Gladi Lapang merujuk pada alur waktu yang sama.
c. Pelaksanaan Gladi Lapang Proses Gladi Lapang dijalankan sesuai skenario Gladi Lapang yang diuraikan dalam agenda acara.
d. Acara Pembukaan Gladi Lapang Acara pembukaan pada tahap pelaksanaan menjadi pilihan untuk dilakukan atau tidak dilakukan. Apabila acara pembukaan diadakan, pembukaan dilakukan dengan jeda waktu yang cukup (15-30 menit) dari saat dimulainya Gladi Lapang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (912, 'Mengingat Gladi Lapang merupakan uji kesiapan kemampuan respons komunitas yang disimulasikan menyerupai kejadian yang sesungguhnya, Penyelenggara mempertimbangkan perlu atau tidak untuk memberikan informasi sebelumnya kepada Pelaku, Tim Evaluasi, dan Tim Pengamat pada hari-H tentang jam mulai simulasi atau pelaksanaan upacara pembukaan.
Apabila tidak diberitahu, Pelaku dapat diberikan informasi tentang kisaran waktu, misalnya simulasi akan dimulai pada sekitar pukul 08:00 WIB. Dengan tidak memberikan informasi rinci, maka akan memberikan efek kejadian yang ’sesungguhnya’, di mana bencana terjadi ketika komunitas sedang melakukan aktivitas rutin harian.
b. Penyiapan Pelaksanaan Gladi Lapang Ketua/Wakil dan Koordinator Pengawas dan Pengendalian memastikan bahwa:
1) tim evaluasi, tim pengamat, penyelenggara, atau relawan sudah berada di lokasi masing-masing dengan piranti pendukung (formulir dan alat tulis) masing-masing; dan 2) penyelenggara dan pelaku menyamakan jam sehingga proses Gladi Lapang merujuk pada alur waktu yang sama.
c. Pelaksanaan Gladi Lapang Proses Gladi Lapang dijalankan sesuai skenario Gladi Lapang yang diuraikan dalam agenda acara.
d. Acara Pembukaan Gladi Lapang Acara pembukaan pada tahap pelaksanaan menjadi pilihan untuk dilakukan atau tidak dilakukan. Apabila acara pembukaan diadakan, pembukaan dilakukan dengan jeda waktu yang cukup (15-30 menit) dari saat dimulainya Gladi Lapang.', 'BAB III (lanjutan 18)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (913, 'juklak-4-2026', 47, 'lain', 'BAB III (lanjutan 19)', NULL, 27, 'e. Mulainya Gladi Lapang Koordinator Pengawas dan Pengendali memulai simulasi dengan memberikan tanda isyarat dimulainya Gladi Lapang.
Tanda tersebut sebelumnya sudah disepakati bersama, misalnya dengan membunyikan sirene atau dentuman atau penanda lainnya.
f. Proses Gladi Lapang Semua pelaku melakukan kegiatan sebagaimana disepakati dan tertulis dalam agenda acara sampai pada waktu dinyatakan pengakhiran kegiatan Gladi Lapang.
4. Tahap Pengakhiran Koordinator Pengawas dan Pengendalian mengakhiri Gladi Lapang dan menyampaikannya kepada semua pelaku, tim evaluasi dan tim pengamat menggunakan alat komunikasi yang disepakati. Setelah simulasi dinyatakan berakhir, Penyelenggara melanjutkan dengan kegiatan akhir dan penutup. Setiap pelaku Gladi Lapang perlu memastikan bahwa semua tindakan pada tahap pengakhiran dilaksanakan dengan penuh tanggung jawab sehingga tidak menyisakan permasalahan.
Tabel 4. Contoh Kegiatan Akhir Gladi Lapang Kegiatan Tindakan
• Pemulangan • Semua Pelaku simulasi kembali ke tempat Pelaku Gladi asal masing-masing.
Lapang • Pelaku dari kelompok anak, disabilitas, lanjut usia, dan kelompok rentan lain difasilitasi dengan baik pada proses pemulangan sesuai rencana.
• Pengembalian • Pelaku simulasi dari komunitas dan Peralatan organisasi mengemas peralatan dan kembali ke asal masing-masing.
• Pembersihan • Tempat-tempat yang digunakan untuk Lokasi Gladi simulasi dibersihkan dan kondisi lokasi dikembalikan seperti semula.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (913, 'e. Mulainya Gladi Lapang Koordinator Pengawas dan Pengendali memulai simulasi dengan memberikan tanda isyarat dimulainya Gladi Lapang.
Tanda tersebut sebelumnya sudah disepakati bersama, misalnya dengan membunyikan sirene atau dentuman atau penanda lainnya.
f. Proses Gladi Lapang Semua pelaku melakukan kegiatan sebagaimana disepakati dan tertulis dalam agenda acara sampai pada waktu dinyatakan pengakhiran kegiatan Gladi Lapang.
4. Tahap Pengakhiran Koordinator Pengawas dan Pengendalian mengakhiri Gladi Lapang dan menyampaikannya kepada semua pelaku, tim evaluasi dan tim pengamat menggunakan alat komunikasi yang disepakati. Setelah simulasi dinyatakan berakhir, Penyelenggara melanjutkan dengan kegiatan akhir dan penutup. Setiap pelaku Gladi Lapang perlu memastikan bahwa semua tindakan pada tahap pengakhiran dilaksanakan dengan penuh tanggung jawab sehingga tidak menyisakan permasalahan.
Tabel 4. Contoh Kegiatan Akhir Gladi Lapang Kegiatan Tindakan
• Pemulangan • Semua Pelaku simulasi kembali ke tempat Pelaku Gladi asal masing-masing.
Lapang • Pelaku dari kelompok anak, disabilitas, lanjut usia, dan kelompok rentan lain difasilitasi dengan baik pada proses pemulangan sesuai rencana.
• Pengembalian • Pelaku simulasi dari komunitas dan Peralatan organisasi mengemas peralatan dan kembali ke asal masing-masing.
• Pembersihan • Tempat-tempat yang digunakan untuk Lokasi Gladi simulasi dibersihkan dan kondisi lokasi dikembalikan seperti semula.', 'BAB III (lanjutan 19)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (914, 'juklak-4-2026', 48, 'lain', 'BAB III (lanjutan 20)', NULL, 28, '• Penyelesaian • Urusan administrasi dan keuangan Administrasi diselesaikan.
• Evaluasi dan • Tim Evaluasi dan Tim Pengamat Rekomendasi menyampaikan hasil evaluasi, hasil observasi dan rekomendasi untuk perbaikan dalam rapat bersama Penyelenggara.
• Penutup • Ketua/Wakil menyatakan seluruh rangkaian Gladi Lapang sudah selesai dan ditutup.
• Media • Penyelenggaraan dan Pelaku memberikan pesan pembelajaran dari simulasi kepada media.
• Pelaporan • Penyelenggara menyusun laporan pelaksanaan Gladi Lapang.
5. Tahap Perbaikan Hasil dari semua pendokumentasian pembelajaran yang dikumpulkan dari pelaksanaan Gladi Lapang penting untuk dikaji bersama untuk menghasilkan butir-butir rekomendasi untuk perbaikan. Pertemuan untuk mengkaji dan merumuskan rekomendasi sebaiknya dilakukan oleh BPBD dan melibatkan penyelenggara dan pelaku sebanyak diperlukan. Waktu pelaksanaan pertemuan tersebut sebaiknya tidak berjeda lama dari hari pelaksanaan Gladi Lapang. Terdapat beberapa komponen dari Gladi Lapang yang perlu dikaji dan menghasilkan rekomendasi untuk perbaikan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (914, '• Penyelesaian • Urusan administrasi dan keuangan Administrasi diselesaikan.
• Evaluasi dan • Tim Evaluasi dan Tim Pengamat Rekomendasi menyampaikan hasil evaluasi, hasil observasi dan rekomendasi untuk perbaikan dalam rapat bersama Penyelenggara.
• Penutup • Ketua/Wakil menyatakan seluruh rangkaian Gladi Lapang sudah selesai dan ditutup.
• Media • Penyelenggaraan dan Pelaku memberikan pesan pembelajaran dari simulasi kepada media.
• Pelaporan • Penyelenggara menyusun laporan pelaksanaan Gladi Lapang.
5. Tahap Perbaikan Hasil dari semua pendokumentasian pembelajaran yang dikumpulkan dari pelaksanaan Gladi Lapang penting untuk dikaji bersama untuk menghasilkan butir-butir rekomendasi untuk perbaikan. Pertemuan untuk mengkaji dan merumuskan rekomendasi sebaiknya dilakukan oleh BPBD dan melibatkan penyelenggara dan pelaku sebanyak diperlukan. Waktu pelaksanaan pertemuan tersebut sebaiknya tidak berjeda lama dari hari pelaksanaan Gladi Lapang. Terdapat beberapa komponen dari Gladi Lapang yang perlu dikaji dan menghasilkan rekomendasi untuk perbaikan.', 'BAB III (lanjutan 20)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (915, 'juklak-4-2026', 49, 'lain', 'BAB III (lanjutan 21)', NULL, 28, 'Tabel 5. Contoh Komponen untuk Perbaikan Komponen Gladi Fokus Rekomendasi Perbaikan Tata Laksana PDB Kebijakan, sistem, rencana-rencana, termasuk dokumen Rencana Kontingensi, dan Prosedur Tetap Pelaku Kesiapan komunitas, lembaga pemerintah dan non pemerintah, akademisi, swasta Sumber daya Kesesuaian sarana dan prasarana, pengerahan bantuan darurat bencana, pendanaan Pengorganisasian Pengelolaan Gladi Lapang Simulasi Penyelenggaraan Koordinasi, materi-materi simulasi, dll Disarankan butir rekomendasi untuk perbaikan tersebut didaftar dan dilengkapi dengan informasi tentang waktu pelaksanaan perbaikan dan para pihak yang akan terlibat dalam pelaksanaannya. Selanjutnya, daftar rekomendasi untuk perbaikan perlu dibagikan kepada semua pihak terkait untuk ditindaklanjuti menjadi rencana perbaikan dan tindakan nyata oleh para pelaku di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (915, 'Tabel 5. Contoh Komponen untuk Perbaikan Komponen Gladi Fokus Rekomendasi Perbaikan Tata Laksana PDB Kebijakan, sistem, rencana-rencana, termasuk dokumen Rencana Kontingensi, dan Prosedur Tetap Pelaku Kesiapan komunitas, lembaga pemerintah dan non pemerintah, akademisi, swasta Sumber daya Kesesuaian sarana dan prasarana, pengerahan bantuan darurat bencana, pendanaan Pengorganisasian Pengelolaan Gladi Lapang Simulasi Penyelenggaraan Koordinasi, materi-materi simulasi, dll Disarankan butir rekomendasi untuk perbaikan tersebut didaftar dan dilengkapi dengan informasi tentang waktu pelaksanaan perbaikan dan para pihak yang akan terlibat dalam pelaksanaannya. Selanjutnya, daftar rekomendasi untuk perbaikan perlu dibagikan kepada semua pihak terkait untuk ditindaklanjuti menjadi rencana perbaikan dan tindakan nyata oleh para pelaku di daerah.', 'BAB III (lanjutan 21)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (916, 'juklak-4-2026', 50, 'lain', 'BAB III', NULL, 29, 'PENUTUP Petunjuk Pelaksanaan ini diharapkan dapat menjadi acuan bagi semua pemangku kepentingan yang terlibat dengan penerapan Standar Pelayanan Minimal Sub-Urusan Bencana Subkegiatan Gladi Kesiapsiagaan terhadap Bencana sehingga tercipta perlindungan warga negara dari ancaman bencana melalui peningkatan kapasitas setiap pelaku penanggulangan bencana baik di pusat maupun daerah.
Ditetapkan di Jakarta pada tanggal 15 September 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (916, 'PENUTUP Petunjuk Pelaksanaan ini diharapkan dapat menjadi acuan bagi semua pemangku kepentingan yang terlibat dengan penerapan Standar Pelayanan Minimal Sub-Urusan Bencana Subkegiatan Gladi Kesiapsiagaan terhadap Bencana sehingga tercipta perlindungan warga negara dari ancaman bencana melalui peningkatan kapasitas setiap pelaku penanggulangan bencana baik di pusat maupun daerah.
Ditetapkan di Jakarta pada tanggal 15 September 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati', 'BAB III', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (917, 'juklak-4-2026', 51, 'lampiran', 'LAMPIRAN', NULL, 30, 'PETUNJUK PELAKSANAAN PEMENUHAN STANDAR PELAYANAN MINIMAL SUB-URUSAN BENCANA DAERAH KABUPATEN/KOTA UNTUK SUBKEGIATAN GLADI KESIAPSIAGAAN TERHADAP BENCANA NOMOR 4 TAHUN 2026 FORMAT DOKUMEN GLADI KESIAPSIAGAAN Format 1 – Kerangka Acuan Kerja Kegiatan Gladi Kesiapsiagaan
1. Maksud Gladi Kesiapsiagaan (Menguraikan maksud secara umum (alasan atau niat dasar yang bersifat abstrak) kegiatan Gladi Kesiapsiagaan dan menguraikan tujuan (target atau hasil akhir yang ingin diwujudkan) dalam kegiatan Gladi Kesiapsiagaan. Sebaiknya uraian tujuan dibuat sespesifik mungkin.)
2. Tujuan Gladi Kesiapsiagaan (Menguraikan target peserta yang ikut dalam kegiatan Gladi Kesiapsiagaan.)
3. Sasaran Gladi Kesiapsiagaan (Menguraikan metode kegiatan yang digunakan untuk Gladi Ruang atau pun Gladi Lapang.)
4. Metode Gladi Kesiapsiagaan (Menguraikan sumber daya sarana dan prasarana yang digunakan dalam kegiatan Gladi Kesiapsiagaan.)
5. Skenario Umum Gladi Kesiapsiagaan.
(Menguraikan pengembangan skenario yang digunakan, baik skenario strategis maupun skenario taktis.)
6. Tanggal, Waktu, dan Durasi Gladi Kesiapsiagaan (Menguraikan tanggal dan waktu (jam) pelaksanaan serta lama waktu operasional kegiatan Gladi Kesiapsiagaan.)
7. Anggota Koordinator Teknis Latihan dan Koordinator Pendukung (Menguraikan panitia pelaksana yang meliputi koordinator teknis latihan dan koordinator pendukung kegiatan Gladi Kesiapsiagaan.)
8. Pelaku Gladi Kesiapsiagaan (Menguraikan para peserta dan pelaku Gladi Kesiapsiagaan.)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (917, 'PETUNJUK PELAKSANAAN PEMENUHAN STANDAR PELAYANAN MINIMAL SUB-URUSAN BENCANA DAERAH KABUPATEN/KOTA UNTUK SUBKEGIATAN GLADI KESIAPSIAGAAN TERHADAP BENCANA NOMOR 4 TAHUN 2026 FORMAT DOKUMEN GLADI KESIAPSIAGAAN Format 1 – Kerangka Acuan Kerja Kegiatan Gladi Kesiapsiagaan
