INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (919, 'juklak-4-2026', 53, 'lain', 'BAB I PENDAHULUAN', NULL, 32, 'A. Umum (Menguraikan gambaran umum dalam penyelenggaraan Gladi Kesiapsiagaan.) B. Maksud dan Tujuan (Menguraikan maksud secara umum (alasan atau niat dasar yang bersifat abstrak) kegiatan Gladi Kesiapsiagaan dan menguraikan tujuan (target atau hasil akhir yang ingin diwujudkan) dalam kegiatan Gladi Kesiapsiagaan. Sebaiknya uraian tujuan dibuat sespesifik mungkin.) C. Ruang Lingkup dan Tata Urut (Menguraikan ruang lingkup pelaksanaan Gladi Kesiapsiagaan dan tata urutan dokumen yang digunakan dalam pelaksanaan Gladi Kesiapsiagaan.) D. Dasar (Menguraikan landasan hukum pelaksanaan Gladi Kesiapsiagaan.)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (919, 'A. Umum (Menguraikan gambaran umum dalam penyelenggaraan Gladi Kesiapsiagaan.) B. Maksud dan Tujuan (Menguraikan maksud secara umum (alasan atau niat dasar yang bersifat abstrak) kegiatan Gladi Kesiapsiagaan dan menguraikan tujuan (target atau hasil akhir yang ingin diwujudkan) dalam kegiatan Gladi Kesiapsiagaan. Sebaiknya uraian tujuan dibuat sespesifik mungkin.) C. Ruang Lingkup dan Tata Urut (Menguraikan ruang lingkup pelaksanaan Gladi Kesiapsiagaan dan tata urutan dokumen yang digunakan dalam pelaksanaan Gladi Kesiapsiagaan.) D. Dasar (Menguraikan landasan hukum pelaksanaan Gladi Kesiapsiagaan.)', 'BAB I PENDAHULUAN', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (920, 'juklak-4-2026', 54, 'lain', 'BAB II LANDASAN PENYELENGGARAAN LATIHAN', NULL, 32, 'A. Latar Belakang (Menguraikan latar belakang pelaksanaan penyelenggaraan Gladi Kesiapsiagaan.) B. Urgensi (Menguraikan keharusan yang mendesak atau hal yang sangat penting untuk segera ditindaklanjuti dengan pelaksanaan Gladi Kesiapsiagaan.) C. Tema (Menguraikan tema kegiatan yang digunakan dalam Gladi Kesiapsiagaan.) D. Pokok-pokok hasil evaluasi yang lalu (Menguraikan hal-hal yang menjadi rekomendasi dari hasil evaluasi pelaksanaan Gladi Kesiapsiagaan sebelumnya (kalau ada).)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (920, 'A. Latar Belakang (Menguraikan latar belakang pelaksanaan penyelenggaraan Gladi Kesiapsiagaan.) B. Urgensi (Menguraikan keharusan yang mendesak atau hal yang sangat penting untuk segera ditindaklanjuti dengan pelaksanaan Gladi Kesiapsiagaan.) C. Tema (Menguraikan tema kegiatan yang digunakan dalam Gladi Kesiapsiagaan.) D. Pokok-pokok hasil evaluasi yang lalu (Menguraikan hal-hal yang menjadi rekomendasi dari hasil evaluasi pelaksanaan Gladi Kesiapsiagaan sebelumnya (kalau ada).)', 'BAB II LANDASAN PENYELENGGARAAN LATIHAN', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Gladi Kesiapsiagaan terhadap Bencana Nomor 4 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (921, 'juklak-4-2026', 55, 'lain', 'BAB III POKOK-POKOK PENYELENGGARAAN LATIHAN', NULL, 32, 'A. Tujuan (Menguraikan tujuan spesifik latihan yang hendak dicapai dalam kegiatan Gladi Kesiapsiagaan) B. Sasaran (Menguraikan daftar peserta yang ikut dalam kegiatan Gladi Kesiapsiagaan) C. Pelajaran yang ingin dikembangkan (Menguraikan hal-hal yang ingin dikembangkan dalam pelaksanaan Gladi Kesiapsiagaan) D. Macam, Sifat, Metode dan Tingkat (Menguraikan hal-hal teknis yang terkait dengan pelaksanaan Gladi Kesiapsiagaan, yaitu macam, sifat, metode, dan tingkat operasionalnya) E. Referensi (Menguraikan daftar rujukan atau referensi yang digunakan dalam pelaksanaan Gladi Kesiapsiagaan) F. Penyelenggaraan (Menguraikan hal-hal teknis dalam penyelenggaraan Gladi Kesiapsiagaan) G. Tempat dan Waktu (Menguraikan tempat kegiatan (lokasi) dilangsungkan dan waktu (hari, tanggal, dan jam) pelaksanaan Gladi Kesiapsiagaan) H. Dukungan Administrasi (Menguraikan dukungan administrasi dalam operasional Gladi Kesiapsiagaan)');
