INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (939, 'juklak-5-2025', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PENANGANAN PENGADUAN MASYARAKAT MELALUI UNIT LAYANAN PENGADUAN NOMOR 5 TAHUN 2025');
