INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (940, 'juklak-5-2025', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Peran serta masyarakat dalam penyelenggaraan negara guna mewujudkan penyelenggara negara yang bersih dan bebas dari korupsi, kolusi, dan nepotisme sesuai Peraturan Pemerintah Nomor 68 Tahun 1999 tentang Tata Cara Pelaksanaan Peran Serta Masyarakat dalam Penyelenggaraan Negara, antara lain dilaksanakan dalam bentuk hak mencari, memperoleh, dan memberikan informasi mengenai penyelenggaraan negara; hak memperoleh pelayanan yang sama dan adil dari penyelenggara negara; serta hak menyampaikan saran dan pendapat secara bertanggung jawab terhadap kebijakan penyelenggara negara yang dilaksanakan sesuai dengan ketentuan/peraturan perundang-undangan yang berlaku.
Pengaduan masyarakat juga merupakan salah satu bentuk peran serta masyarakat dalam pengawasan pelayanan publik, sehingga perlu memberikan akses kepada masyarakat dalam rangka menyampaikan pengaduan mengenai terjadinya pelanggaran dan tindak pidana di lingkungan Badan Nasional Penanggulangan Bencana.
Salah satu titik kritis dalam pengaduan masyarakat adalah perlindungan Pelapor. Perlindungan Pelapor adalah aspek penting dalam sistem manajemen pengaduan terutama dalam konteks organisasi.
Pelapor adalah individu yang mengungkapkan informasi tentang pelanggaran atau penyimpangan yang terjadi dalam sebuah organisasi.
Mekanisme perlindungan Pelapor yang kuat diperlukan untuk memastikan bahwa mereka dapat melaporkan masalah tanpa adanya intervensi atau ancaman.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (940, 'PENDAHULUAN A. Latar Belakang Peran serta masyarakat dalam penyelenggaraan negara guna mewujudkan penyelenggara negara yang bersih dan bebas dari korupsi, kolusi, dan nepotisme sesuai Peraturan Pemerintah Nomor 68 Tahun 1999 tentang Tata Cara Pelaksanaan Peran Serta Masyarakat dalam Penyelenggaraan Negara, antara lain dilaksanakan dalam bentuk hak mencari, memperoleh, dan memberikan informasi mengenai penyelenggaraan negara; hak memperoleh pelayanan yang sama dan adil dari penyelenggara negara; serta hak menyampaikan saran dan pendapat secara bertanggung jawab terhadap kebijakan penyelenggara negara yang dilaksanakan sesuai dengan ketentuan/peraturan perundang-undangan yang berlaku.
Pengaduan masyarakat juga merupakan salah satu bentuk peran serta masyarakat dalam pengawasan pelayanan publik, sehingga perlu memberikan akses kepada masyarakat dalam rangka menyampaikan pengaduan mengenai terjadinya pelanggaran dan tindak pidana di lingkungan Badan Nasional Penanggulangan Bencana.
Salah satu titik kritis dalam pengaduan masyarakat adalah perlindungan Pelapor. Perlindungan Pelapor adalah aspek penting dalam sistem manajemen pengaduan terutama dalam konteks organisasi.
Pelapor adalah individu yang mengungkapkan informasi tentang pelanggaran atau penyimpangan yang terjadi dalam sebuah organisasi.
Mekanisme perlindungan Pelapor yang kuat diperlukan untuk memastikan bahwa mereka dapat melaporkan masalah tanpa adanya intervensi atau ancaman.', 'BAB I', 'Petunjuk Pelaksanaan Penanganan Pengaduan Masyarakat melalui Unit Layanan Pengaduan Nomor 5 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (941, 'juklak-5-2025', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Dalam rangka mengoptimalkan perlindungan Pelapor, Badan Nasional Penanggulangan Bencana memberikan akses kepada masyarakat dalam memberikan pengaduan mengenai terjadinya tindakan balasan melalui Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat, sehingga hal tersebut dapat mendorong Pelapor melaporkan pelanggaran tanpa takut akan pembalasan, serta memastikan keamanan dan keadilan.
Selain perlindungan Pelapor, agar pengaduan masyarakat dapat ditangani dengan baik, benar dan efektif serta tanpa diskriminasi perlu juga untuk mengatur sikap, tindakan, ucapan dan perilaku petugas Unit Layanan Pengaduan yang menangani pengaduan masyarakat.
Berdasarkan uraian tersebut, dalam rangka peningkatan pelayanan pengaduan masyarakat, perlu diatur sikap, tindakan, ucapan, dan perilaku Petugas Unit Layanan Pengaduan. Selain itu untuk memberikan rasa aman terhadap Pelapor, perlu diatur lebih lanjut terkait mekanisme perlindungan terhadap Pelapor. Atas hal tersebut di atas, dipandang perlu untuk melakukan revisi Petunjuk Pelaksanaan Penanganan Pengaduan Masyarakat melalui Unit Layanan Pengaduan.
B. Maksud dan Tujuan Petunjuk Pelaksanaan Penanganan Pengaduan Masyarakat melalui Unit Layanan Pengaduan dimaksudkan sebagai acuan bagi Unit Layanan Pengaduan dalam melakukan penanganan pengaduan masyarakat.
Tujuan dari petunjuk pelaksanaan adalah:
1. Agar pengaduan masyarakat dapat ditangani dengan baik dan benar serta efektif.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (941, 'Dalam rangka mengoptimalkan perlindungan Pelapor, Badan Nasional Penanggulangan Bencana memberikan akses kepada masyarakat dalam memberikan pengaduan mengenai terjadinya tindakan balasan melalui Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat, sehingga hal tersebut dapat mendorong Pelapor melaporkan pelanggaran tanpa takut akan pembalasan, serta memastikan keamanan dan keadilan.
Selain perlindungan Pelapor, agar pengaduan masyarakat dapat ditangani dengan baik, benar dan efektif serta tanpa diskriminasi perlu juga untuk mengatur sikap, tindakan, ucapan dan perilaku petugas Unit Layanan Pengaduan yang menangani pengaduan masyarakat.
Berdasarkan uraian tersebut, dalam rangka peningkatan pelayanan pengaduan masyarakat, perlu diatur sikap, tindakan, ucapan, dan perilaku Petugas Unit Layanan Pengaduan. Selain itu untuk memberikan rasa aman terhadap Pelapor, perlu diatur lebih lanjut terkait mekanisme perlindungan terhadap Pelapor. Atas hal tersebut di atas, dipandang perlu untuk melakukan revisi Petunjuk Pelaksanaan Penanganan Pengaduan Masyarakat melalui Unit Layanan Pengaduan.
B. Maksud dan Tujuan Petunjuk Pelaksanaan Penanganan Pengaduan Masyarakat melalui Unit Layanan Pengaduan dimaksudkan sebagai acuan bagi Unit Layanan Pengaduan dalam melakukan penanganan pengaduan masyarakat.
Tujuan dari petunjuk pelaksanaan adalah:
1. Agar pengaduan masyarakat dapat ditangani dengan baik dan benar serta efektif.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Penanganan Pengaduan Masyarakat melalui Unit Layanan Pengaduan Nomor 5 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (942, 'juklak-5-2025', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, '2. Agar penanganan pengaduan masyarakat lebih terkoordinasi dan mempunyai mekanisme penanganan yang sama.
3. Memberdayakan pengaduan masyarakat sebagai kontrol sosial terhadap penyelenggaraan pemerintahan dan pelayanan masyarakat.
4. Mendorong terwujudnya penyelenggaraan pemerintah yang baik dan bebas dari korupsi, kolusi dan nepotisme.
5. Memberikan pelindungan hak pelapor dan terlapor selama proses penanganan pengaduan.
C. Ruang Lingkup Ruang lingkup Petunjuk Pelaksanaan Penanganan ini meliputi:
1. mengatur sikap, tindakan, ucapan, dan perilaku Petugas Unit Layanan Pengaduan yang menangani pengaduan masyarakat; dan
2. mekanisme penanganan pengaduan masyarakat yang disampaikan secara langsung maupun tidak langsung.
D. Pengertian Dalam Petunjuk Pelaksanaan ini, yang dimaksud dengan:
1. Pengaduan Masyarakat adalah bentuk penerapan dari pengawasan yang disampaikan oleh masyarakat, baik secara lisan maupun tertulis kepada Aparatur Pemerintah terkait, berupa sumbangan pikiran, saran, gagasan atau keluhan/pengaduan yang bersifat membangun.
2. Pengaduan berkadar pengawasan adalah pengaduan masyarakat yang isinya mengandung informasi atau adanya indikasi terjadinya penyimpangan atau penyalahgunaan wewenang oleh aparatur negara, yang dapat mengakibatkan kerugian bagi masyarakat/negara dalam rangka penyelenggaraan pemerintahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (942, '2. Agar penanganan pengaduan masyarakat lebih terkoordinasi dan mempunyai mekanisme penanganan yang sama.
3. Memberdayakan pengaduan masyarakat sebagai kontrol sosial terhadap penyelenggaraan pemerintahan dan pelayanan masyarakat.
4. Mendorong terwujudnya penyelenggaraan pemerintah yang baik dan bebas dari korupsi, kolusi dan nepotisme.
5. Memberikan pelindungan hak pelapor dan terlapor selama proses penanganan pengaduan.
C. Ruang Lingkup Ruang lingkup Petunjuk Pelaksanaan Penanganan ini meliputi:
1. mengatur sikap, tindakan, ucapan, dan perilaku Petugas Unit Layanan Pengaduan yang menangani pengaduan masyarakat; dan
2. mekanisme penanganan pengaduan masyarakat yang disampaikan secara langsung maupun tidak langsung.
D. Pengertian Dalam Petunjuk Pelaksanaan ini, yang dimaksud dengan:
1. Pengaduan Masyarakat adalah bentuk penerapan dari pengawasan yang disampaikan oleh masyarakat, baik secara lisan maupun tertulis kepada Aparatur Pemerintah terkait, berupa sumbangan pikiran, saran, gagasan atau keluhan/pengaduan yang bersifat membangun.
2. Pengaduan berkadar pengawasan adalah pengaduan masyarakat yang isinya mengandung informasi atau adanya indikasi terjadinya penyimpangan atau penyalahgunaan wewenang oleh aparatur negara, yang dapat mengakibatkan kerugian bagi masyarakat/negara dalam rangka penyelenggaraan pemerintahan.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Penanganan Pengaduan Masyarakat melalui Unit Layanan Pengaduan Nomor 5 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (943, 'juklak-5-2025', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, '3. Pengaduan tidak berkadar pengawasan adalah pengaduan masyarakat yang isinya mengandung informasi berupa sumbang saran, kritik yang konstruktif dan lain sebagainya yang bermanfaat bagi perbaikan penyelenggaraan pemerintahan dan pelayanan masyarakat.
4. Penanganan pengaduan masyarakat, adalah proses kegiatan yang meliputi penerimaan, pencatatan, penelaahan, penyaluran, konfirmasi, klarifikasi, penelitian, pemeriksaan, pelaporan, tindak lanjut dan pengarsipan.
5. Unit Layanan Pengaduan Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat ULP BNPB adalah tim penanganan pengaduan yang ditetapkan dengan Keputusan Kepala Badan Nasional Penanggulangan Bencana.
6. Konfirmasi adalah proses kegiatan untuk memperoleh penegasan mengenai keberadaan Terlapor yang teridentifikasi, baik bersifat perorangan, kelompok maupun institusional, dan apabila mungkin termasuk masalah yang dilaporkan.
7. Klarifikasi adalah suatu proses penjernihan atau kegiatan yang berupa memberikan penjelasan mengenai permasalahan yang diadukan pada proporsi yang sebenarnya kepada sumber pengaduan dan instansi terkait.
8. Pelapor adalah Pegawai, individu atau kelompok yang menyampaikan pengaduan tertulis kepada instansi pemerintah tertentu.
9. Terlapor adalah aparatur pemerintah atau lembaga yang diduga melakukan penyimpangan atau pelanggaran.
10. Perlindungan Pelapor adalah aspek penting dalam sistem manajemen pengaduan dan laporan yang efektif, terutama dalam konteks organisasi dan institusi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (943, '3. Pengaduan tidak berkadar pengawasan adalah pengaduan masyarakat yang isinya mengandung informasi berupa sumbang saran, kritik yang konstruktif dan lain sebagainya yang bermanfaat bagi perbaikan penyelenggaraan pemerintahan dan pelayanan masyarakat.
4. Penanganan pengaduan masyarakat, adalah proses kegiatan yang meliputi penerimaan, pencatatan, penelaahan, penyaluran, konfirmasi, klarifikasi, penelitian, pemeriksaan, pelaporan, tindak lanjut dan pengarsipan.
5. Unit Layanan Pengaduan Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat ULP BNPB adalah tim penanganan pengaduan yang ditetapkan dengan Keputusan Kepala Badan Nasional Penanggulangan Bencana.
6. Konfirmasi adalah proses kegiatan untuk memperoleh penegasan mengenai keberadaan Terlapor yang teridentifikasi, baik bersifat perorangan, kelompok maupun institusional, dan apabila mungkin termasuk masalah yang dilaporkan.
7. Klarifikasi adalah suatu proses penjernihan atau kegiatan yang berupa memberikan penjelasan mengenai permasalahan yang diadukan pada proporsi yang sebenarnya kepada sumber pengaduan dan instansi terkait.
8. Pelapor adalah Pegawai, individu atau kelompok yang menyampaikan pengaduan tertulis kepada instansi pemerintah tertentu.
9. Terlapor adalah aparatur pemerintah atau lembaga yang diduga melakukan penyimpangan atau pelanggaran.
10. Perlindungan Pelapor adalah aspek penting dalam sistem manajemen pengaduan dan laporan yang efektif, terutama dalam konteks organisasi dan institusi.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Penanganan Pengaduan Masyarakat melalui Unit Layanan Pengaduan Nomor 5 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (944, 'juklak-5-2025', 6, 'lain', 'BAB I (lanjutan 4)', NULL, 3, '11. Tindakan balasan adalah tindakan berupa ucapan, perbuatan, atau tindakan lainnya oleh Terlapor dan/atau pihak-pihak lain yang berhubungan dengan informasi Pelanggaran yang mengganggu rasa aman, merugikan secara kepegawaian, ancaman tindakan hukum, dan/atau dampak negatif lainnya yang diterima oleh Pelapor.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (944, '11. Tindakan balasan adalah tindakan berupa ucapan, perbuatan, atau tindakan lainnya oleh Terlapor dan/atau pihak-pihak lain yang berhubungan dengan informasi Pelanggaran yang mengganggu rasa aman, merugikan secara kepegawaian, ancaman tindakan hukum, dan/atau dampak negatif lainnya yang diterima oleh Pelapor.', 'BAB I (lanjutan 4)', 'Petunjuk Pelaksanaan Penanganan Pengaduan Masyarakat melalui Unit Layanan Pengaduan Nomor 5 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (945, 'juklak-5-2025', 7, 'lain', 'BAB II', NULL, 4, 'ETIKA DALAM PENANGANAN PENGADUAN MASYARAKAT Etika dalam Penanganan Pengaduan Masyarakat merupakan pedoman dalam bersikap, bertindak, berucap, dan berperilaku agar memiliki moral dan kepribadian yang baik, serta menumbuhkembangkan dan meningkatkan kepercayaan masyarakat dalam penanganan pengaduan masyarakat. Adapun etika yang harus dimiliki oleh Aparat Pengawasan Internal Pemerintah (APIP) yang menangani pengaduan masyarakat adalah sebagai berikut.
A. Etika Aparatur Pemerintah
1. Etika terhadap Pelapor
a. memberikan pelayanan dan empati, hormat dan santun, tanpa pamrih dan tanpa ada unsur pemaksaan;
b. memberikan pelayanan secara cepat, tepat, terbuka, dan adil serta tidak diskriminatif;
c. menjamin kerahasiaan identitas Pelapor sesuai dengan ketentuan peraturan perundang-undangan yang berlaku;
d. menciptakan kenyamanan dan keamanan kepada Pelapor; dan
e. memberikan penjelasan secara proporsional tentang perkembangan proses.
2. Etika terhadap Terlapor
a. menjunjung tinggi asas praduga tak bersalah;
b. menghormati hak-hak Terlapor; dan
c. diberikan perlakuan secara adil dan tidak diskriminatif.
3. Etika terhadap sesama Aparatur Pemerintah yang menangani pengaduan masyarakat
a. menjalin kerja sama secara kooperatif dengan unit kerja lain yang terkait dalam rangka pencapaian tujuan;
b. menggalang rasa kebersamaan;
c. menghargai perbedaan pendapat; dan
d. saling membimbing, mengingatkan, dan mengoreksi.
B. Kewajiban dan Larangan bagi Aparatur Pemerintah
1. Kewajiban');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (945, 'ETIKA DALAM PENANGANAN PENGADUAN MASYARAKAT Etika dalam Penanganan Pengaduan Masyarakat merupakan pedoman dalam bersikap, bertindak, berucap, dan berperilaku agar memiliki moral dan kepribadian yang baik, serta menumbuhkembangkan dan meningkatkan kepercayaan masyarakat dalam penanganan pengaduan masyarakat. Adapun etika yang harus dimiliki oleh Aparat Pengawasan Internal Pemerintah (APIP) yang menangani pengaduan masyarakat adalah sebagai berikut.
A. Etika Aparatur Pemerintah
1. Etika terhadap Pelapor
a. memberikan pelayanan dan empati, hormat dan santun, tanpa pamrih dan tanpa ada unsur pemaksaan;
b. memberikan pelayanan secara cepat, tepat, terbuka, dan adil serta tidak diskriminatif;
c. menjamin kerahasiaan identitas Pelapor sesuai dengan ketentuan peraturan perundang-undangan yang berlaku;
d. menciptakan kenyamanan dan keamanan kepada Pelapor; dan
e. memberikan penjelasan secara proporsional tentang perkembangan proses.
2. Etika terhadap Terlapor
a. menjunjung tinggi asas praduga tak bersalah;
b. menghormati hak-hak Terlapor; dan
c. diberikan perlakuan secara adil dan tidak diskriminatif.
3. Etika terhadap sesama Aparatur Pemerintah yang menangani pengaduan masyarakat
a. menjalin kerja sama secara kooperatif dengan unit kerja lain yang terkait dalam rangka pencapaian tujuan;
b. menggalang rasa kebersamaan;
c. menghargai perbedaan pendapat; dan
d. saling membimbing, mengingatkan, dan mengoreksi.
B. Kewajiban dan Larangan bagi Aparatur Pemerintah
1. Kewajiban', 'BAB II', 'Petunjuk Pelaksanaan Penanganan Pengaduan Masyarakat melalui Unit Layanan Pengaduan Nomor 5 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (946, 'juklak-5-2025', 8, 'lain', 'BAB II (lanjutan 1)', NULL, 4, 'a. melaksanakan nilai-nilai dasar aparatur sipil negara meliputi:
1) berorientasi pelayanan, yaitu komitmen memberikan pelayanan prima demi kepuasan masyarakat;
2) akuntabel, yaitu bertanggung jawab atas kepercayaan yang diberikan;
3) kompeten, yaitu terus belajar dan mengembangkan kapabilitas;
4) harmonis, yaitu saling peduli dan menghargai perbedaan;
5) loyal, yaitu berdedikasi dan mengutamakan kepentingan bangsa dan negara;
6) adaptif, yaitu terus berinovasi dan antusias dalam menggerakkan serta menghadapi perubahan; dan 7) kolaboratif, yaitu membangun kerja sama yang sinergis;
b. melaksanakan tugas dan wewenang secara proporsional dan profesional;
c. melaksanakan tugas dan wewenang sesuai dengan ketentuan yang berlaku;
d. membangun etos kerja untuk meningkatkan kinerja;
e. mengembangkan pemikiran secara kreatif dan inovatif dalam rangka peningkatan kinerja;
f. menjaga informasi yang bersifat rahasia terkait dengan jabatan, Pelapor, dan Terlapor;
g. menyerahkan seluruh dokumen atau bahan-bahan yang berkaitan dengan pengaduan masyarakat kepada atasannya, apabila sudah tidak menangani pengaduan masyarakat atau berhenti/alih tugas; dan
h. menjaga kerahasiaan, baik informasi maupun dalam bentuk dokumen kepada pihak lain yang diperoleh sebagai konsekuensi pelaksanaan tugas selama menangani pengaduan masyarakat, baik secara langsung maupun tidak langsung, apabila sudah tidak menangani pengaduan masyarakat atau berhenti/alih tugas.
2. Larangan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (946, 'a. melaksanakan nilai-nilai dasar aparatur sipil negara meliputi:
