INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (973, 'juklak-5-2026', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (973, 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026', 'Judul', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (974, 'juklak-5-2026', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMENUHAN STANDAR PELAYANAN MINIMAL SUB URUSAN BENCANA DAERAH KABUPATEN/KOTA UNTUK SUBKEGIATAN PENYEDIAAN PERALATAN PERLINDUNGAN DAN KESIAPSIAGAAN TERHADAP BENCANA NOMOR 5 TAHUN 2026');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (974, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMENUHAN STANDAR PELAYANAN MINIMAL SUB URUSAN BENCANA DAERAH KABUPATEN/KOTA UNTUK SUBKEGIATAN PENYEDIAAN PERALATAN PERLINDUNGAN DAN KESIAPSIAGAAN TERHADAP BENCANA NOMOR 5 TAHUN 2026', 'Isi hal. 1', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (975, 'juklak-5-2026', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Setiap Warga Negara Indonesia berhak untuk mendapatkan pelindungan dan rasa aman dari ancaman bencana. Hal ini telah menjadi amanat dari Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Pemerintah dan Pemerintah Daerah bertanggung jawab dalam penyelenggaraan penanggulangan bencana, yang merupakan bagian tidak terpisahkan dari urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (975, 'PENDAHULUAN A. Latar Belakang Setiap Warga Negara Indonesia berhak untuk mendapatkan pelindungan dan rasa aman dari ancaman bencana. Hal ini telah menjadi amanat dari Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Pemerintah dan Pemerintah Daerah bertanggung jawab dalam penyelenggaraan penanggulangan bencana, yang merupakan bagian tidak terpisahkan dari urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar.', 'BAB I', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (976, 'juklak-5-2026', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menegaskan bahwa tugas Badan Nasional Penanggulangan Bencana yaitu memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana dan menetapkan standardisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundang-undangan. Sejalan dengan tugas tersebut, dalam rangka sinergitas dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2021 tentang Penerapan Standar Pelayanan Minimal, Badan Nasional Penanggulangan Bencana sebagai kementerian/lembaga yang membidangi urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar bidang penanggulangan bencana, perlu melakukan pembinaan secara teknis terhadap penerapan standar pelayanan minimal di daerah dengan memberikan pedoman dan pengarahan, menetapkan standarisasi serta melakukan perumusan dan penetapan norma, standar, prosedur, kriteria. Dalam hal ini Badan Nasional Penanggulangan Bencana sebagai lembaga teknis penanggulangan bencana memberikan pembinaan dan pedoman norma, standar, prosedur, dan kriteria pada penerapan standar pelayanan minimal sub-urusan bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (976, 'Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menegaskan bahwa tugas Badan Nasional Penanggulangan Bencana yaitu memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana dan menetapkan standardisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundang-undangan. Sejalan dengan tugas tersebut, dalam rangka sinergitas dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2021 tentang Penerapan Standar Pelayanan Minimal, Badan Nasional Penanggulangan Bencana sebagai kementerian/lembaga yang membidangi urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar bidang penanggulangan bencana, perlu melakukan pembinaan secara teknis terhadap penerapan standar pelayanan minimal di daerah dengan memberikan pedoman dan pengarahan, menetapkan standarisasi serta melakukan perumusan dan penetapan norma, standar, prosedur, kriteria. Dalam hal ini Badan Nasional Penanggulangan Bencana sebagai lembaga teknis penanggulangan bencana memberikan pembinaan dan pedoman norma, standar, prosedur, dan kriteria pada penerapan standar pelayanan minimal sub-urusan bencana di daerah.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (977, 'juklak-5-2026', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 1, 'Untuk mempercepat penerapan Standar Pelayanan Minimal Sub-Urusan Bencana di daerah, Badan Nasional Penanggulangan Bencana perlu menyusun Petunjuk Pelaksanaan Pelayanan Standar Pelayanan Minimal Sub-Urusan Bencana untuk kabupaten/kota yang di dalamnya memuat penjabaran tahapan dan prosedur pelaksanaan pelayanan Standar Pelayanan Minimal Sub-Urusan Bencana. Petunjuk Pelaksanaan ini disusun untuk membantu daerah dalam memenuhi mutu pelayanan dasar dalam pelaksanaan pelayanan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana.
Sebagai bentuk pemenuhan penyediaan peralatan perlindungan dan kesiapsiagaan bencana menjadi hal penting dalam penanggulangan bencana. Penyelenggaraan peralatan perlindungan dan kesiapsiagaan terhadap bencana dilakukan sebagai upaya pencegahan, pengurangan risiko, dan mitigasi bencana yang merupakan tanggung jawab dari Pemerintah dan Pemerintah Daerah. Penyediaan alat perlindungan dan kesiapsiagaan terhadap bencana merupakan bentuk partisipasi aktif yang dilakukan sebagai upaya yang sangat dibutuhkan untuk mengurangi dampak bencana dan korban jiwa pada wilayah dan waktu tertentu sebagai bentuk pencegahan dan pengurangan risiko bencana.
Petunjuk Pelaksanaan ini tidak terlepas dari regulasi teknis terkait logistik dan peralatan di bidang penanggulangan bencana yang telah lebih dulu ada, sehingga kehadiran Petunjuk Pelaksanaan ini sebagai pelengkap pengaturan tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (977, 'Untuk mempercepat penerapan Standar Pelayanan Minimal Sub-Urusan Bencana di daerah, Badan Nasional Penanggulangan Bencana perlu menyusun Petunjuk Pelaksanaan Pelayanan Standar Pelayanan Minimal Sub-Urusan Bencana untuk kabupaten/kota yang di dalamnya memuat penjabaran tahapan dan prosedur pelaksanaan pelayanan Standar Pelayanan Minimal Sub-Urusan Bencana. Petunjuk Pelaksanaan ini disusun untuk membantu daerah dalam memenuhi mutu pelayanan dasar dalam pelaksanaan pelayanan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana.
Sebagai bentuk pemenuhan penyediaan peralatan perlindungan dan kesiapsiagaan bencana menjadi hal penting dalam penanggulangan bencana. Penyelenggaraan peralatan perlindungan dan kesiapsiagaan terhadap bencana dilakukan sebagai upaya pencegahan, pengurangan risiko, dan mitigasi bencana yang merupakan tanggung jawab dari Pemerintah dan Pemerintah Daerah. Penyediaan alat perlindungan dan kesiapsiagaan terhadap bencana merupakan bentuk partisipasi aktif yang dilakukan sebagai upaya yang sangat dibutuhkan untuk mengurangi dampak bencana dan korban jiwa pada wilayah dan waktu tertentu sebagai bentuk pencegahan dan pengurangan risiko bencana.
Petunjuk Pelaksanaan ini tidak terlepas dari regulasi teknis terkait logistik dan peralatan di bidang penanggulangan bencana yang telah lebih dulu ada, sehingga kehadiran Petunjuk Pelaksanaan ini sebagai pelengkap pengaturan tersebut.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (978, 'juklak-5-2026', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, 'Dengan adanya Petunjuk Pelaksanaan ini, diharapkan upaya penerapan Standar Pelayanan Minimal Sub-Urusan Bencana dapat terlaksana dengan lebih terarah, terkoordinasi, dan sesuai dengan mutu dan sasaran yang telah ditetapkan.
Berdasarkan pertimbangan sebagaimana disebutkan di atas, perlu menyusun dan menetapkan Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota Untuk Sub Kegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana.
B. Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini dimaksudkan sebagai acuan dalam tahapan prosedur pelaksanaan pelayanan dasar standar pelayanan minimal sub urusan bencana oleh Pemerintah Daerah yang berada diperoleh setiap warga negara yang berada di kawasan bencana dan yang menjadi korban bencana secara minimal.
2. Tujuan Tujuan Petunjuk Pelaksanaan ini adalah untuk mendukung menyediakan standar teknis datau tata cara pemenuhan pelayanan dasar pada subkegiatan penyediaan peralatan perlindungan dan kesiapsiagaan terhadap bencana.
C. Ruang Lingkup Prosedur standar pelayanan minimal sub urusan bencana yang diatur dalam Petunjuk Pelaksanaan ini meliputi mekanisme operasional penyediaan peralatan perlindungan dan kesiapsiagaan terhadap bencana.
D. Pengertian
1. Pelayanan Dasar adalah pelayanan publik untuk memenuhi kebutuhan dasar Warga Negara yang terkena dampak di kawasan rawan bencana dan yang akan menjadi korban bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (978, 'Dengan adanya Petunjuk Pelaksanaan ini, diharapkan upaya penerapan Standar Pelayanan Minimal Sub-Urusan Bencana dapat terlaksana dengan lebih terarah, terkoordinasi, dan sesuai dengan mutu dan sasaran yang telah ditetapkan.
Berdasarkan pertimbangan sebagaimana disebutkan di atas, perlu menyusun dan menetapkan Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota Untuk Sub Kegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana.
B. Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini dimaksudkan sebagai acuan dalam tahapan prosedur pelaksanaan pelayanan dasar standar pelayanan minimal sub urusan bencana oleh Pemerintah Daerah yang berada diperoleh setiap warga negara yang berada di kawasan bencana dan yang menjadi korban bencana secara minimal.
2. Tujuan Tujuan Petunjuk Pelaksanaan ini adalah untuk mendukung menyediakan standar teknis datau tata cara pemenuhan pelayanan dasar pada subkegiatan penyediaan peralatan perlindungan dan kesiapsiagaan terhadap bencana.
C. Ruang Lingkup Prosedur standar pelayanan minimal sub urusan bencana yang diatur dalam Petunjuk Pelaksanaan ini meliputi mekanisme operasional penyediaan peralatan perlindungan dan kesiapsiagaan terhadap bencana.
D. Pengertian
1. Pelayanan Dasar adalah pelayanan publik untuk memenuhi kebutuhan dasar Warga Negara yang terkena dampak di kawasan rawan bencana dan yang akan menjadi korban bencana.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (979, 'juklak-5-2026', 6, 'lain', 'BAB I (lanjutan 4)', NULL, 3, '2. Standar Pelayanan Minimal yang selanjutnya disingkat SPM adalah ketentuan mengenai jenis dan mutu pelayanan dasar yang merupakan urusan pemerintahan wajib yang berhak diperoleh setiap Warga Negara secara minimal.
3. Standar Teknis adalah standar jumlah dan kualitas barang dan/atau jasa, sumber daya manusia dan petunjuk teknis atau tata cara pemenuhan standar.
4. Mutu Pelayanan Dasar adalah ukuran kuantitas dan kualitas barang dan/atau jasa kebutusan dasar serta pemenuhannya secara minimal dalam pelayanan dasar sesuai standar teknis agar hidup secara layak.
5. Peralatan adalah segara bentuk alat yang dapat dipergunakan untuk melakukan pencarian, penyelamatan, evakuasi masyarakat terdampak bencana, membantu pemenuhan kebutuhan dasar untuk pemulihan segera sarana prasarana vital.
6. Peralatan Perlindungan atau Alat Pelindung Diri yang selanjutnya disebut APD adalah suatu alat yang akan melindungi seseorang dengan mengisolasi sebagian atau seluruh tubuh dari potensi bahaya di tempat kerja.
7. Kesiapsiagaan adalah serangkaian kegiatan yang dilakukan untuk mengantisipasi bencana melalui pengorganisasian serta melalui langkah yang tepat guna dan berdaya guna.
8. Peralatan Kesiapsiagaan adalah peralatan penanggulangan bencana yang disiapkan sejak sebelum terjadi bencana untuk memastikan upaya cepat dan tepat dalam menghadapi kejadian bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (979, '2. Standar Pelayanan Minimal yang selanjutnya disingkat SPM adalah ketentuan mengenai jenis dan mutu pelayanan dasar yang merupakan urusan pemerintahan wajib yang berhak diperoleh setiap Warga Negara secara minimal.
3. Standar Teknis adalah standar jumlah dan kualitas barang dan/atau jasa, sumber daya manusia dan petunjuk teknis atau tata cara pemenuhan standar.
4. Mutu Pelayanan Dasar adalah ukuran kuantitas dan kualitas barang dan/atau jasa kebutusan dasar serta pemenuhannya secara minimal dalam pelayanan dasar sesuai standar teknis agar hidup secara layak.
5. Peralatan adalah segara bentuk alat yang dapat dipergunakan untuk melakukan pencarian, penyelamatan, evakuasi masyarakat terdampak bencana, membantu pemenuhan kebutuhan dasar untuk pemulihan segera sarana prasarana vital.
6. Peralatan Perlindungan atau Alat Pelindung Diri yang selanjutnya disebut APD adalah suatu alat yang akan melindungi seseorang dengan mengisolasi sebagian atau seluruh tubuh dari potensi bahaya di tempat kerja.
7. Kesiapsiagaan adalah serangkaian kegiatan yang dilakukan untuk mengantisipasi bencana melalui pengorganisasian serta melalui langkah yang tepat guna dan berdaya guna.
8. Peralatan Kesiapsiagaan adalah peralatan penanggulangan bencana yang disiapkan sejak sebelum terjadi bencana untuk memastikan upaya cepat dan tepat dalam menghadapi kejadian bencana.', 'BAB I (lanjutan 4)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (980, 'juklak-5-2026', 7, 'lain', 'BAB I (lanjutan 5)', NULL, 3, '9. Rencana Kontigensi Bencana yang selanjutnya disebut Renkon, adalah dokumen hasil perencanaan kontigensi yang disusun dengan tujuan untuk meningkatkan kesiapsiagaan menghadapi suatu ancaman bencana pada suatu daerah atau wilayah tertentu.
10. Rawan Bencana adalah kondisi atau karakteristik geologis, biologis, hidrologis, klimatologis, geografis, sosial, budaya, politik, ekonomi, dan teknologi pada suatu wilayah untuk jangka waktu tertentu yang mengurangi kemampuan mencegah, meredam, mencapai kesiapan, dan mengurangi kemampuan untuk menanggapi dampak buruk bahaya tertentu.
11. Warga Negara Indonesia, yang selanjutnya disebut Warga Negara adalah orang bangsa Indonesia asli dan orang bangsa lain yang disahkan sesuai dengan ketentuan peraturan perundang-undangan.
12. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah perangkat daerah yang menyelenggarakan suburusan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (980, '9. Rencana Kontigensi Bencana yang selanjutnya disebut Renkon, adalah dokumen hasil perencanaan kontigensi yang disusun dengan tujuan untuk meningkatkan kesiapsiagaan menghadapi suatu ancaman bencana pada suatu daerah atau wilayah tertentu.
10. Rawan Bencana adalah kondisi atau karakteristik geologis, biologis, hidrologis, klimatologis, geografis, sosial, budaya, politik, ekonomi, dan teknologi pada suatu wilayah untuk jangka waktu tertentu yang mengurangi kemampuan mencegah, meredam, mencapai kesiapan, dan mengurangi kemampuan untuk menanggapi dampak buruk bahaya tertentu.
11. Warga Negara Indonesia, yang selanjutnya disebut Warga Negara adalah orang bangsa Indonesia asli dan orang bangsa lain yang disahkan sesuai dengan ketentuan peraturan perundang-undangan.
12. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah perangkat daerah yang menyelenggarakan suburusan bencana.', 'BAB I (lanjutan 5)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (981, 'juklak-5-2026', 8, 'lain', 'BAB II', NULL, 4, 'PROSEDUR A. Pendataan Daerah Rawan Bencana
1. Melakukan inventarisasi data daerah Rawan Bencana yang ada di wilayahnya dengan prioritas terhadap jenis ancaman bencana utama atau yang sering terjadi. Sumber data berasal dari dokumen Kajian Risiko Bencana dan Rencana Penanggulangan Bencana Daerah.
2. Penyediaan APD dan Peralatan Kesiapsiagaan terhadap bencana oleh BPBD kabupaten/kota dilakukan dengan memperhatikan:
a. karakteristik ancaman; dan
b. identifikasi kebutuhan seperti tercantum dalam Renkon atau apabila daerah belum mempunyai Renkon, dapat menggunakan data kerawanan daerah bencana.
B. Pendataan Warga Negara Sasaran Mendata jumlah Warga Negara yang bertempat tinggal atau beraktivitas di daerah tersebut dengan data terpilah berdasarkan jenis kelamin, unsur, disabilitas, dan kelompok berisiko, seperti penyandang disabilitas dengan ragamnya, lanjut usia, bayi, perempuan hamil, anak-anak, dan lain-lain. Sumber data dari Dinas Kependudukan dan Pencatatan Sipil, Badan Pusat Statistik, dan pemerintah desa/kelurahan setempat.
C. Pendataan Perangkat Daerah dan Instansi/Lembaga Terkait APD dan Peralatan Kesiapsiagaan Bencana.
Mendata perangkat daerah, instansi, lembaga non-pemerintah, lembaga kemasyarakatan, lembaga usaha, perguruan tinggi, relawan, dan lain-lain yang memiliki APD dan Peralatan Kesiapsiagaan bencana, antara lain sebagai berikut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (981, 'PROSEDUR A. Pendataan Daerah Rawan Bencana
1. Melakukan inventarisasi data daerah Rawan Bencana yang ada di wilayahnya dengan prioritas terhadap jenis ancaman bencana utama atau yang sering terjadi. Sumber data berasal dari dokumen Kajian Risiko Bencana dan Rencana Penanggulangan Bencana Daerah.
2. Penyediaan APD dan Peralatan Kesiapsiagaan terhadap bencana oleh BPBD kabupaten/kota dilakukan dengan memperhatikan:
a. karakteristik ancaman; dan
b. identifikasi kebutuhan seperti tercantum dalam Renkon atau apabila daerah belum mempunyai Renkon, dapat menggunakan data kerawanan daerah bencana.
B. Pendataan Warga Negara Sasaran Mendata jumlah Warga Negara yang bertempat tinggal atau beraktivitas di daerah tersebut dengan data terpilah berdasarkan jenis kelamin, unsur, disabilitas, dan kelompok berisiko, seperti penyandang disabilitas dengan ragamnya, lanjut usia, bayi, perempuan hamil, anak-anak, dan lain-lain. Sumber data dari Dinas Kependudukan dan Pencatatan Sipil, Badan Pusat Statistik, dan pemerintah desa/kelurahan setempat.
C. Pendataan Perangkat Daerah dan Instansi/Lembaga Terkait APD dan Peralatan Kesiapsiagaan Bencana.
Mendata perangkat daerah, instansi, lembaga non-pemerintah, lembaga kemasyarakatan, lembaga usaha, perguruan tinggi, relawan, dan lain-lain yang memiliki APD dan Peralatan Kesiapsiagaan bencana, antara lain sebagai berikut.', 'BAB II', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (982, 'juklak-5-2026', 9, 'lain', 'BAB II (lanjutan 1)', NULL, 4, '1. Dinas Pekerjaan Umum dan Penataan Ruang memiliki peralatan berat seperti backhoe/excavator, truk, buldozer, mobil tangki air, mobil penjernih air, mobil toilet, perahu karet, mesin pompa air, dan lain-lain.
2. Dinas Sosial memiliki peralatan mobil dapur umum lapangan, tenda peleton, tenda keluarga, tenda pengungsi, peralatan penjernih air, perahu karet, toilet portabel (porta potty) untuk akses bagi penyandang disabilitas dan kelompok berisiko seperti ibu hamil, anak-anak, lansia, dan lain-lain.
3. Dinas Kesehatan memiliki APD untuk penanganan wabah penyakit/epidemi, peralatan medis, ambulans, peralatan kesehatan lingkungan, peralatan surveilans epidemiologi, tenda khusus pemeriksaan kehamilan dan kelahiran, dan lain-lain.
4. Dinas Lingkungan Hidup dan Kehutanan memiliki peralatan pemadam kebakaran hutan dan lahan, peringatan dini kebakaran hutan dan lahan, dan lain-lain.
5. Dinas Pemadam Kebakaran memilik peralatan pemadam kebakaran (mobil dan portabel), gergaji mesin (beton, besi-baja, kayu), mobil tangki air, mesin diesel, mesin pompa air, dan lain-lain.
6. Badan Meteorologi, Klimatologi, dan Geofisika memiliki peralatan peringatan dini gempa, tsunami, cuaca, kebakaran hutan dan lahan, dan lain-lain.
7. Palang Merah Indonesia memiliki mobil ambulans, mobil evakuasi, perahu karet, mobil tangki air, mobil unit donor darah, peralatan air dan sanitasi, tenda peleton, tenda keluarga, dan lain-lain.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (982, '1. Dinas Pekerjaan Umum dan Penataan Ruang memiliki peralatan berat seperti backhoe/excavator, truk, buldozer, mobil tangki air, mobil penjernih air, mobil toilet, perahu karet, mesin pompa air, dan lain-lain.
2. Dinas Sosial memiliki peralatan mobil dapur umum lapangan, tenda peleton, tenda keluarga, tenda pengungsi, peralatan penjernih air, perahu karet, toilet portabel (porta potty) untuk akses bagi penyandang disabilitas dan kelompok berisiko seperti ibu hamil, anak-anak, lansia, dan lain-lain.
3. Dinas Kesehatan memiliki APD untuk penanganan wabah penyakit/epidemi, peralatan medis, ambulans, peralatan kesehatan lingkungan, peralatan surveilans epidemiologi, tenda khusus pemeriksaan kehamilan dan kelahiran, dan lain-lain.
4. Dinas Lingkungan Hidup dan Kehutanan memiliki peralatan pemadam kebakaran hutan dan lahan, peringatan dini kebakaran hutan dan lahan, dan lain-lain.
5. Dinas Pemadam Kebakaran memilik peralatan pemadam kebakaran (mobil dan portabel), gergaji mesin (beton, besi-baja, kayu), mobil tangki air, mesin diesel, mesin pompa air, dan lain-lain.
6. Badan Meteorologi, Klimatologi, dan Geofisika memiliki peralatan peringatan dini gempa, tsunami, cuaca, kebakaran hutan dan lahan, dan lain-lain.
7. Palang Merah Indonesia memiliki mobil ambulans, mobil evakuasi, perahu karet, mobil tangki air, mobil unit donor darah, peralatan air dan sanitasi, tenda peleton, tenda keluarga, dan lain-lain.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (983, 'juklak-5-2026', 10, 'lain', 'BAB II (lanjutan 2)', NULL, 5, '8. Radio Amatir Penduduk Indonesia, dan Organisasi Amatir Radio Republik Indonesia memiliki peralatan komunikasi (mobil dan portabel).
9. Dinas Pemberdayaan Perempuan dan Perlindungan Anak memiliki posko pencegahan dan penanganan kekerasan berbasis gender.
D. Pendataan Potensi Sumber Daya dan Dukungan dari Pemerintah Kabupaten/Kota tetangga, Pemerintah Provinsi dan Pemerintah Pusat, serta lembaga non-pemerintah.
1. Mendata potensi sumber daya dan dukungan dari pemerintah kabupaten/kota tetangga, pemerintah provinsi dan pemerintah pusat, serta lembaga non-pemerintah.
2. Contoh dukungan sumber daya seperti sumber daya manusia untuk operasi pencarian dan pertolongan, bantuan logistik, bantuan kebutuhan dasar untuk pengungsi terdampak bencana, bantuan pendanaan untuk operasional darurat bencana, dan lain-lain.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (983, '8. Radio Amatir Penduduk Indonesia, dan Organisasi Amatir Radio Republik Indonesia memiliki peralatan komunikasi (mobil dan portabel).
9. Dinas Pemberdayaan Perempuan dan Perlindungan Anak memiliki posko pencegahan dan penanganan kekerasan berbasis gender.
D. Pendataan Potensi Sumber Daya dan Dukungan dari Pemerintah Kabupaten/Kota tetangga, Pemerintah Provinsi dan Pemerintah Pusat, serta lembaga non-pemerintah.
1. Mendata potensi sumber daya dan dukungan dari pemerintah kabupaten/kota tetangga, pemerintah provinsi dan pemerintah pusat, serta lembaga non-pemerintah.
2. Contoh dukungan sumber daya seperti sumber daya manusia untuk operasi pencarian dan pertolongan, bantuan logistik, bantuan kebutuhan dasar untuk pengungsi terdampak bencana, bantuan pendanaan untuk operasional darurat bencana, dan lain-lain.', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (984, 'juklak-5-2026', 11, 'lain', 'BAB III', NULL, 6, 'PENYELENGGARAAN Penyelenggaraan penyediaan APD dan kesiapsiagaan terhadap bencana dilakukan sesuai dengan kondisi wilayah setempat dan karakteristik jenis bencana. Pemenuhan kebutuhan mengikuti petunjuk pelaksanaan standar minimal kebutuhan logistik dan peralatan. Tahapan penyelenggaraan yang dilakukan terbagi menjadi dua yaitu, APD dan peralatan kesiapsiagaan.
A. APD APD terdiri atas:
1. pelindung kepala;
2. pelindung mata dan muka;
3. pelindung telinga;
4. pelindung pernapasan beserta perlengkapannya;
5. pelindung tangan;
6. pelindung kaki;
7. pakaian pelindung
8. alat pelindung jatuh perorangan; dan
9. pelampung Namun terhadap spesifikasi teknis APD untuk kegiatan di air (pada saat di permukaan dan keadaan menyelam) berbeda. Semua pengadaan APD sesuai dengan Standar Nasional Indonesia atau standar yang berlaku.
B. Peralatan Kesiapsiagaan Peralatan Kesiapsiagaan merupakan Peralatan untuk penyelamatan diri bagi individu Warga Negara, keluarga, maupun petugas sesuai dengan jenis ancaman bencana di kawasan tempat tinggalnya. Semua Peralatan perlu disediakan sebagai upaya efektif dan efisien dalam mengurangi dampak bencana pada individu ataupun pada kelompok.
Peralatan Kesiapsiagaan disesuaikan dengan jenis ancaman bencana, perkembangan zaman dan ilmu teknologi. Penyediaan peralatan ini ditujukan bagi masyarakat yang tinggal di daerah rawan bencana dan para petugas/aparatur penanggulangan bencana yang mengoperasikan Peralatan tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (984, 'PENYELENGGARAAN Penyelenggaraan penyediaan APD dan kesiapsiagaan terhadap bencana dilakukan sesuai dengan kondisi wilayah setempat dan karakteristik jenis bencana. Pemenuhan kebutuhan mengikuti petunjuk pelaksanaan standar minimal kebutuhan logistik dan peralatan. Tahapan penyelenggaraan yang dilakukan terbagi menjadi dua yaitu, APD dan peralatan kesiapsiagaan.
A. APD APD terdiri atas:
1. pelindung kepala;
2. pelindung mata dan muka;
3. pelindung telinga;
4. pelindung pernapasan beserta perlengkapannya;
5. pelindung tangan;
6. pelindung kaki;
7. pakaian pelindung
8. alat pelindung jatuh perorangan; dan
9. pelampung Namun terhadap spesifikasi teknis APD untuk kegiatan di air (pada saat di permukaan dan keadaan menyelam) berbeda. Semua pengadaan APD sesuai dengan Standar Nasional Indonesia atau standar yang berlaku.
B. Peralatan Kesiapsiagaan Peralatan Kesiapsiagaan merupakan Peralatan untuk penyelamatan diri bagi individu Warga Negara, keluarga, maupun petugas sesuai dengan jenis ancaman bencana di kawasan tempat tinggalnya. Semua Peralatan perlu disediakan sebagai upaya efektif dan efisien dalam mengurangi dampak bencana pada individu ataupun pada kelompok.
Peralatan Kesiapsiagaan disesuaikan dengan jenis ancaman bencana, perkembangan zaman dan ilmu teknologi. Penyediaan peralatan ini ditujukan bagi masyarakat yang tinggal di daerah rawan bencana dan para petugas/aparatur penanggulangan bencana yang mengoperasikan Peralatan tersebut.', 'BAB III', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (985, 'juklak-5-2026', 12, 'lain', 'BAB III (lanjutan 1)', NULL, 6, 'APD dan Peralatan Kesiapsiagaan masuk dalam komponen penyediaan peralatan penyelamatan diri, yaitu:
1. Peralatan keselamatan petugas Penyediaan terhadap peralatan keselamatan petugas dilakukan sesuai kebutuhan sebagai berikut.
a. Berdasarkan Dokumen Renkon atau apabila daerah belum mempunyai dokumen Renkon. Dapat menggunakan data kerawanan daerah bencana;
b. Hasil penghitungan standar minimal kebutuhan peralatan dengan mengikuti petunjuk pelaksanaan mengenai standar minimal kebutuhan logistik dan peralatan.
c. Jumlah petugas aktif, jenis, potensi dampak, dan karakteristik bencana di kabupaten/kota setempat.
d. Penentuan APD yang digunakan disesuaikan dengan jenis bencana dan karakteristik wilayah kerawanan bencana.
e. Daftar jenis APD terhadap bencana mengacu kepada petunjuk pelaksanaan mengenai standar minimal kebutuhan logistik dan peralatan.
2. Peralatan keselamatan keluarga Penyediaan terhadap peralatan keselamatan keluarga dilakukan sesuai kebutuhan sebagai berikut:
a. Dokumen Renkon atau apabila daerah belum mempunyai dokumen Renkon, dapat menggunakan data kerawanan daerah bencana.
b. Hasil penghitungan standar minimal kebutuhan peralatan dengan mengikuti petunjuk pelaksanaan mengenai standar minimal kebutuhan logistik dan peralatan.
c. Perkiraan jumlah korban, jenis, potensi dampak, dan karakteristik bencana di kabupaten/kota setempat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (985, 'APD dan Peralatan Kesiapsiagaan masuk dalam komponen penyediaan peralatan penyelamatan diri, yaitu:
1. Peralatan keselamatan petugas Penyediaan terhadap peralatan keselamatan petugas dilakukan sesuai kebutuhan sebagai berikut.
a. Berdasarkan Dokumen Renkon atau apabila daerah belum mempunyai dokumen Renkon. Dapat menggunakan data kerawanan daerah bencana;
b. Hasil penghitungan standar minimal kebutuhan peralatan dengan mengikuti petunjuk pelaksanaan mengenai standar minimal kebutuhan logistik dan peralatan.
c. Jumlah petugas aktif, jenis, potensi dampak, dan karakteristik bencana di kabupaten/kota setempat.
d. Penentuan APD yang digunakan disesuaikan dengan jenis bencana dan karakteristik wilayah kerawanan bencana.
e. Daftar jenis APD terhadap bencana mengacu kepada petunjuk pelaksanaan mengenai standar minimal kebutuhan logistik dan peralatan.
2. Peralatan keselamatan keluarga Penyediaan terhadap peralatan keselamatan keluarga dilakukan sesuai kebutuhan sebagai berikut:
a. Dokumen Renkon atau apabila daerah belum mempunyai dokumen Renkon, dapat menggunakan data kerawanan daerah bencana.
b. Hasil penghitungan standar minimal kebutuhan peralatan dengan mengikuti petunjuk pelaksanaan mengenai standar minimal kebutuhan logistik dan peralatan.
c. Perkiraan jumlah korban, jenis, potensi dampak, dan karakteristik bencana di kabupaten/kota setempat.', 'BAB III (lanjutan 1)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (986, 'juklak-5-2026', 13, 'lain', 'BAB III (lanjutan 2)', NULL, 7, 'd. Penyediaan peralatan keselamatan keluarga dapat dilakukan untuk jenis bencana yang diperkirakan akan terjadi pada tahun berjalan dan/atau waktu dekat.
e. Peralatan keselamatan keluarga dimasukkan ke dalam Tas Siaga Bencana. Tas siaga bencana (tas darurat) adalah tas yang berisi barang-barang penting untuk bertahan hidup selama beberapa hari setelah bencana. Tas siaga bencana sebaiknya dibuat dari bahan tahan air (waterproof).
f. Berikut beberapa barang yang perlu ada di dalam tas siaga bencana, antara lain:
1) Fotokopi dokumen-dokumen penting, seperti ijazah, sertifikat tanah, surat kendaraan, Kartu Tanda Penduduk, Surat Ijin Mengemudi, kartu keluarga, dan polis asuransi.
2) Kotak pertolongan pertama pada kecelakaan yang berisi cairan pembersih luka, kapas, kain kasa, plester, salep antibiotik, obat penurun panas, obat pereda rasa sakit, dan obat diare, obat-obatan, serta obat-obatan yang bersifat sangat pribadi (misalkan ada anggota keluarga yang mempunyai penyakit alergi, diabetes, darah tinggi, dan lain-lain).
3) Makanan dan minuman tahan lama, seperti mi instan, air mineral, biskuit, dan abon.
4) Alat penerangan, seperti senter, lampu kepala, korek api, dan lilin.
5) Peluit untuk meminta pertolongan.
6) Perlengkapan mandi, seperti sabun, sikat gigi, dan pasta gigi 7) Alat komunikasi, seperti ponsel dan powerbank.
8) Pakaian ganti, setidaknya 1 (satu) pasang.
9) Uang tunai secukupnya.
10) Duplikat kunci kendaraan atau kunci rumah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (986, 'd. Penyediaan peralatan keselamatan keluarga dapat dilakukan untuk jenis bencana yang diperkirakan akan terjadi pada tahun berjalan dan/atau waktu dekat.
e. Peralatan keselamatan keluarga dimasukkan ke dalam Tas Siaga Bencana. Tas siaga bencana (tas darurat) adalah tas yang berisi barang-barang penting untuk bertahan hidup selama beberapa hari setelah bencana. Tas siaga bencana sebaiknya dibuat dari bahan tahan air (waterproof).
f. Berikut beberapa barang yang perlu ada di dalam tas siaga bencana, antara lain:
1) Fotokopi dokumen-dokumen penting, seperti ijazah, sertifikat tanah, surat kendaraan, Kartu Tanda Penduduk, Surat Ijin Mengemudi, kartu keluarga, dan polis asuransi.
2) Kotak pertolongan pertama pada kecelakaan yang berisi cairan pembersih luka, kapas, kain kasa, plester, salep antibiotik, obat penurun panas, obat pereda rasa sakit, dan obat diare, obat-obatan, serta obat-obatan yang bersifat sangat pribadi (misalkan ada anggota keluarga yang mempunyai penyakit alergi, diabetes, darah tinggi, dan lain-lain).
3) Makanan dan minuman tahan lama, seperti mi instan, air mineral, biskuit, dan abon.
4) Alat penerangan, seperti senter, lampu kepala, korek api, dan lilin.
5) Peluit untuk meminta pertolongan.
6) Perlengkapan mandi, seperti sabun, sikat gigi, dan pasta gigi 7) Alat komunikasi, seperti ponsel dan powerbank.
8) Pakaian ganti, setidaknya 1 (satu) pasang.
9) Uang tunai secukupnya.
10) Duplikat kunci kendaraan atau kunci rumah.', 'BAB III (lanjutan 2)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (987, 'juklak-5-2026', 14, 'lain', 'BAB III (lanjutan 3)', NULL, 7, 'g. Penyediaan peralatan keselamatan keluarga dapat disediakan oleh masing-masing keluarga yang bersangkutan. BPBD menyampaikan informasi mengenai jenis kebutuhan peralatan keselamatan keluarga kepada masyarakat di daerah rawan bencana.
3. Peralatan keselamatan pribadi Penyediaan terhadap peralatan keselamatan pribadi dilakukan sesuai kebutuhan sebagai berikut:
a. Dokumen Renkon atau apabila daerah belum mempunyai dokumen Renkon, dapat menggunakan data kerawanan daerah bencana.
b. Hasil penghitungan standar minimal kebutuhan peralatan dengan mengikuti petunjuk pelaksanaan mengenai standar minimal kebutuhan logistik dan peralatan.
c. Perkiraan jumlah korban, jenis, potensi dampak, dan karakteristik bencana di kabupaten/kota setempat.
d. Penyediaan peralatan keselamatan pribadi dapat dilakukan untuk jenis bencana yang diperkirakan akan terjadi pada tahun berjalan dan/atau waktu dekat.
e. Peralatan keselamatan pribadi antara lain: (a) peluit, (b) moda lain untuk pemanggil tim pencari saat terperangkap, dan lain-lain.
f. Penyediaan peralatan keselamatan pribadi dapat disediakan oleh masing-masing keluarga yang bersangkutan. BPBD menyampaikan informasi mengenai jenis kebutuhan peralatan keselamatan pribadi kepada masyarakat di daerah rawan bencana.
4. Peralatan penyelamatan korban bencana Peralatan penyelamatan korban bencana dilakukan sesuai kebutuhan berdasarkan:
a. Dokumen Renkon atau apabila daerah belum mempunyai dokumen Renkon, dapat menggunakan data kerawanan daerah bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (987, 'g. Penyediaan peralatan keselamatan keluarga dapat disediakan oleh masing-masing keluarga yang bersangkutan. BPBD menyampaikan informasi mengenai jenis kebutuhan peralatan keselamatan keluarga kepada masyarakat di daerah rawan bencana.
3. Peralatan keselamatan pribadi Penyediaan terhadap peralatan keselamatan pribadi dilakukan sesuai kebutuhan sebagai berikut:
a. Dokumen Renkon atau apabila daerah belum mempunyai dokumen Renkon, dapat menggunakan data kerawanan daerah bencana.
b. Hasil penghitungan standar minimal kebutuhan peralatan dengan mengikuti petunjuk pelaksanaan mengenai standar minimal kebutuhan logistik dan peralatan.
c. Perkiraan jumlah korban, jenis, potensi dampak, dan karakteristik bencana di kabupaten/kota setempat.
d. Penyediaan peralatan keselamatan pribadi dapat dilakukan untuk jenis bencana yang diperkirakan akan terjadi pada tahun berjalan dan/atau waktu dekat.
e. Peralatan keselamatan pribadi antara lain: (a) peluit, (b) moda lain untuk pemanggil tim pencari saat terperangkap, dan lain-lain.
f. Penyediaan peralatan keselamatan pribadi dapat disediakan oleh masing-masing keluarga yang bersangkutan. BPBD menyampaikan informasi mengenai jenis kebutuhan peralatan keselamatan pribadi kepada masyarakat di daerah rawan bencana.
4. Peralatan penyelamatan korban bencana Peralatan penyelamatan korban bencana dilakukan sesuai kebutuhan berdasarkan:
a. Dokumen Renkon atau apabila daerah belum mempunyai dokumen Renkon, dapat menggunakan data kerawanan daerah bencana.', 'BAB III (lanjutan 3)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (988, 'juklak-5-2026', 15, 'lain', 'BAB III (lanjutan 4)', NULL, 8, 'b. Hasil penghitungan standar minimal kebutuhan peralatan dengan mengikuti petunjuk pelaksanaan mengenai standar minimal kebutuhan logistik dan peralatan.
c. Perkiraan jumlah korban, jenis, potensi dampak, dan karakteristik bencana di kabupaten/kota setempat
d. Peralatan dan sarana prasarana untuk operasi penyelamatan dan evakuasi korban bencana, seperti perahu penyelamat (perahu karet, perahu fiber, perahu bermotor), jaket pelampung, ambulans, tenda pengungsi, tenda komando, mobil operasional untuk segala medan (mobil gardan ganda), motor trail, dan lain-lain.
e. Daftar jenis peralatan kesiapsiagaan terhadap bencana mengacu kepada Petunjuk Pelaksanaan Standar Minimal Kebutuhan Logistik dan Peralatan.
Sebagai referensi daftar jenis APD dan peralatan kesiapsiagaan terhadap bencana merujuk pada petunjuk pelaksanaan mengenai standar minimal kebutuhan logistik dan peralatan. Daftar peralatan ini disesuaikan dengan kondisi di lapangan dan ancaman bencana, baik multiancaman maupun satu jenis ancaman bencana.
Hasil-hasil pendataan dan perhitungan kebutuhan APD dan kesiapsiagaan terhadap bencana diintegrasikan atau dimasukkan ke dalam perencanaan dan penganggaran pembangunan daerah oleh BPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (988, 'b. Hasil penghitungan standar minimal kebutuhan peralatan dengan mengikuti petunjuk pelaksanaan mengenai standar minimal kebutuhan logistik dan peralatan.
c. Perkiraan jumlah korban, jenis, potensi dampak, dan karakteristik bencana di kabupaten/kota setempat
d. Peralatan dan sarana prasarana untuk operasi penyelamatan dan evakuasi korban bencana, seperti perahu penyelamat (perahu karet, perahu fiber, perahu bermotor), jaket pelampung, ambulans, tenda pengungsi, tenda komando, mobil operasional untuk segala medan (mobil gardan ganda), motor trail, dan lain-lain.
e. Daftar jenis peralatan kesiapsiagaan terhadap bencana mengacu kepada Petunjuk Pelaksanaan Standar Minimal Kebutuhan Logistik dan Peralatan.
Sebagai referensi daftar jenis APD dan peralatan kesiapsiagaan terhadap bencana merujuk pada petunjuk pelaksanaan mengenai standar minimal kebutuhan logistik dan peralatan. Daftar peralatan ini disesuaikan dengan kondisi di lapangan dan ancaman bencana, baik multiancaman maupun satu jenis ancaman bencana.
Hasil-hasil pendataan dan perhitungan kebutuhan APD dan kesiapsiagaan terhadap bencana diintegrasikan atau dimasukkan ke dalam perencanaan dan penganggaran pembangunan daerah oleh BPBD.', 'BAB III (lanjutan 4)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (989, 'juklak-5-2026', 16, 'lain', 'BAB IV', NULL, 9, 'PENUTUP Petunjuk Pelaksanaan ini diharapkan dapat menjadi acuan bagi semua pemangku kepentingan yang terlibat dengan penerapan Standar Pelayanan Minimal Sub-Urusan Bencana Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana sehingga tercipta perlindungan Warga Negara dari ancaman bencana.
Ditetapkan di Jakarta pada tanggal 15 September 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (989, 'PENUTUP Petunjuk Pelaksanaan ini diharapkan dapat menjadi acuan bagi semua pemangku kepentingan yang terlibat dengan penerapan Standar Pelayanan Minimal Sub-Urusan Bencana Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana sehingga tercipta perlindungan Warga Negara dari ancaman bencana.
Ditetapkan di Jakarta pada tanggal 15 September 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati', 'BAB IV', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Penyediaan Peralatan Perlindungan dan Kesiapsiagaan terhadap Bencana Nomor 5 Tahun 2026');
