INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (992, 'juklak-6-2025', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran');
