INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (993, 'juklak-6-2025', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMBERIAN PERTIMBANGAN UNTUK PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA NOMOR 6 TAHUN 2025');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (993, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMBERIAN PERTIMBANGAN UNTUK PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA NOMOR 6 TAHUN 2025', 'Isi hal. 1', 'Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (994, 'juklak-6-2025', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Berdasarkan ketentuan Pasal 8 Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana, Badan Nasional Penanggulangan Bencana bertanggung jawab atas pelaksanaan penelaahan, verifikasi, dan evaluasi terhadap permohonan tertulis yang disampaikan oleh pemohon sebelum dilakukan penganggaran dan pengalokasian dana bersama penanggulangan bencana. Dalam pelaksanaan penelaahan, verifikasi, dan evaluasi, terhadap permohonan penyaluran dana bersama penanggulangan bencana juga diberikan pertimbangan oleh kementerian/lembaga pemberi pertimbangan yang terdiri atas Kementerian Keuangan, Kementerian Perencanaan Pembangunan Nasional/Badan Perencanaan Pembangunan Nasional, dan Kementerian Dalam Negeri.
Pemberian pertimbangan penyaluran dana bersama penanggulangan bencana tersebut dilaksanakan sebagai bagian dari upaya mendapatkan permohonan kegiatan penyelenggaraan penanggulangan bencana yang searah dan sejalan dengan aspek-aspek pertimbangan sesuai dengan kewenangan masing-masing kementerian/lembaga pemberi pertimbangan. Pemberian pertimbangan menjamin akuntabilitas dan kejelasan tugas dalam pengelolaan dana bersama penanggulangan bencana, khususnya dalam pemberian pertimbangan penyaluran dana bersama penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (994, 'PENDAHULUAN A. Latar Belakang Berdasarkan ketentuan Pasal 8 Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana, Badan Nasional Penanggulangan Bencana bertanggung jawab atas pelaksanaan penelaahan, verifikasi, dan evaluasi terhadap permohonan tertulis yang disampaikan oleh pemohon sebelum dilakukan penganggaran dan pengalokasian dana bersama penanggulangan bencana. Dalam pelaksanaan penelaahan, verifikasi, dan evaluasi, terhadap permohonan penyaluran dana bersama penanggulangan bencana juga diberikan pertimbangan oleh kementerian/lembaga pemberi pertimbangan yang terdiri atas Kementerian Keuangan, Kementerian Perencanaan Pembangunan Nasional/Badan Perencanaan Pembangunan Nasional, dan Kementerian Dalam Negeri.
Pemberian pertimbangan penyaluran dana bersama penanggulangan bencana tersebut dilaksanakan sebagai bagian dari upaya mendapatkan permohonan kegiatan penyelenggaraan penanggulangan bencana yang searah dan sejalan dengan aspek-aspek pertimbangan sesuai dengan kewenangan masing-masing kementerian/lembaga pemberi pertimbangan. Pemberian pertimbangan menjamin akuntabilitas dan kejelasan tugas dalam pengelolaan dana bersama penanggulangan bencana, khususnya dalam pemberian pertimbangan penyaluran dana bersama penanggulangan bencana.', 'BAB I', 'Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (995, 'juklak-6-2025', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Dalam instrumen pelaksanaannya, Badan Nasional Penanggulangan Bencana menetapkan Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana yang dalam ketentuan Pasal 17 ayat (3) mengamanatkan adanya pengaturan lebih lanjut terkait mekanisme pemberian pertimbangan penyaluran dana bersama penanggulangan bencana sebagai bagian dari tata kelola operasionalisasi dana bersama penanggulangan bencana. Bahwa penyusunan mekanisme pemberian pertimbangan penyaluran dana bersama penanggulangan bencana dimaksud dilaksanakan melalui koordinasi dan kolaborasi dengan kementerian/lembaga pemberi pertimbangan.
Berdasarkan hal-hal sebagaimana disebutkan di atas, perlu disusun Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran Dana Bersama Penanggulangan Bencana.
B. Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini dimaksudkan sebagai panduan bagi:
a. BNPB dalam menatalaksanakan pemberian pertimbangan; dan
b. kementerian/lembaga pemberi pertimbangan dalam memberikan pertimbangan sesuai kewenangannya, sebagai bagian dari proses penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana.
2. Tujuan Tujuan dari Petunjuk Pelaksanaan ini adalah tersedianya panduan mekanisme pemberian pertimbangan dalam proses penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana sesuai dengan kewenangan kementerian/lembaga pemberi pertimbangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (995, 'Dalam instrumen pelaksanaannya, Badan Nasional Penanggulangan Bencana menetapkan Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana yang dalam ketentuan Pasal 17 ayat (3) mengamanatkan adanya pengaturan lebih lanjut terkait mekanisme pemberian pertimbangan penyaluran dana bersama penanggulangan bencana sebagai bagian dari tata kelola operasionalisasi dana bersama penanggulangan bencana. Bahwa penyusunan mekanisme pemberian pertimbangan penyaluran dana bersama penanggulangan bencana dimaksud dilaksanakan melalui koordinasi dan kolaborasi dengan kementerian/lembaga pemberi pertimbangan.
Berdasarkan hal-hal sebagaimana disebutkan di atas, perlu disusun Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran Dana Bersama Penanggulangan Bencana.
B. Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini dimaksudkan sebagai panduan bagi:
a. BNPB dalam menatalaksanakan pemberian pertimbangan; dan
b. kementerian/lembaga pemberi pertimbangan dalam memberikan pertimbangan sesuai kewenangannya, sebagai bagian dari proses penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana.
2. Tujuan Tujuan dari Petunjuk Pelaksanaan ini adalah tersedianya panduan mekanisme pemberian pertimbangan dalam proses penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana sesuai dengan kewenangan kementerian/lembaga pemberi pertimbangan.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (996, 'juklak-6-2025', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, 'C. Ruang Lingkup Ruang lingkup dari Petunjuk Pelaksanaan ini mencakup tata kelola pemberian pertimbangan terhadap permohonan penyaluran dana bersama penanggulangan bencana yang diajukan oleh kementerian/lembaga dan pemerintah daerah.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Dana Penanggulangan Bencana adalah dana yang digunakan bagi penanggulangan bencana untuk tahap prabencana, darurat bencana, dan/atau pascabencana.
3. Dana Bersama Penanggulangan Bencana, yang selanjutnya disebut Dana Bersama, adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi Dana Penanggulangan Bencana yang memadai dan berkelanjutan.
4. Anggaran Pendapatan dan Belanja Daerah yang selanjutnya disingkat APBD adalah rencana keuangan tahunan daerah yang ditetapkan dengan Peraturan Daerah.
5. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara pemerintahan daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
6. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat BNPB adalah lembaga pemerintah non-departemen sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (996, 'C. Ruang Lingkup Ruang lingkup dari Petunjuk Pelaksanaan ini mencakup tata kelola pemberian pertimbangan terhadap permohonan penyaluran dana bersama penanggulangan bencana yang diajukan oleh kementerian/lembaga dan pemerintah daerah.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Dana Penanggulangan Bencana adalah dana yang digunakan bagi penanggulangan bencana untuk tahap prabencana, darurat bencana, dan/atau pascabencana.
3. Dana Bersama Penanggulangan Bencana, yang selanjutnya disebut Dana Bersama, adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi Dana Penanggulangan Bencana yang memadai dan berkelanjutan.
4. Anggaran Pendapatan dan Belanja Daerah yang selanjutnya disingkat APBD adalah rencana keuangan tahunan daerah yang ditetapkan dengan Peraturan Daerah.
5. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara pemerintahan daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
6. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat BNPB adalah lembaga pemerintah non-departemen sesuai dengan ketentuan peraturan perundang-undangan.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (997, 'juklak-6-2025', 5, 'lain', 'BAB II', NULL, 3, 'RUANG LINGKUP PERTIMBANGAN A. Kementerian Keuangan Kementerian Keuangan fokus memberikan pertimbangan terkait aspek-aspek keuangan dalam penyaluran Dana Bersama. Pertimbangan ini mencakup:
1. ketersediaan anggaran Dana Bersama;
2. potensi duplikasi penganggaran;
3. prinsip belanja berkualitas;
4. khusus pemohon kementerian/lembaga, memperhatikan kesesuaian usulan kegiatan dengan tugas dan fungsi instansi pemohon; dan
5. khusus pemohon Pemerintah Daerah, memperhatikan:
a. penilaian kemampuan fiskal daerah;
b. kinerja pengelolaan APBD;
c. partisipasi daerah dalam Dana Bersama; dan
d. indikator lainnya jika diperlukan.
B. Kementerian Perencanaan Pembangunan Nasional/Badan Perencanaan Pembangunan Nasional Kementerian Perencanaan Pembangunan Nasional/ Badan Perencanaan Pembangunan Nasional berfokus pada pertimbangan yang berkaitan dengan:
a. kesesuaian kegiatan terhadap prioritas nasional;
b. kesesuaian kegiatan terhadap perencanaan pembangunan nasional dan perencanaan pembangunan daerah;
c. kesiapan rencana kerja dan rencana penarikan dana; dan
d. potensi duplikasi usulan kegiatan.
C. Kementerian Dalam Negeri Kementerian Dalam Negeri memberikan pertimbangan terkait dengan:
a. aspek kewenangan pelaksanaan kegiatan;
b. kesesuaian kegiatan terhadap perencanaan pembangunan daerah dan perencanaan perangkat daerah; dan
c. kesesuaian terhadap prioritas standar pelayanan minimal suburusan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (997, 'RUANG LINGKUP PERTIMBANGAN A. Kementerian Keuangan Kementerian Keuangan fokus memberikan pertimbangan terkait aspek-aspek keuangan dalam penyaluran Dana Bersama. Pertimbangan ini mencakup:
1. ketersediaan anggaran Dana Bersama;
2. potensi duplikasi penganggaran;
3. prinsip belanja berkualitas;
4. khusus pemohon kementerian/lembaga, memperhatikan kesesuaian usulan kegiatan dengan tugas dan fungsi instansi pemohon; dan
5. khusus pemohon Pemerintah Daerah, memperhatikan:
a. penilaian kemampuan fiskal daerah;
b. kinerja pengelolaan APBD;
c. partisipasi daerah dalam Dana Bersama; dan
d. indikator lainnya jika diperlukan.
B. Kementerian Perencanaan Pembangunan Nasional/Badan Perencanaan Pembangunan Nasional Kementerian Perencanaan Pembangunan Nasional/ Badan Perencanaan Pembangunan Nasional berfokus pada pertimbangan yang berkaitan dengan:
a. kesesuaian kegiatan terhadap prioritas nasional;
b. kesesuaian kegiatan terhadap perencanaan pembangunan nasional dan perencanaan pembangunan daerah;
c. kesiapan rencana kerja dan rencana penarikan dana; dan
d. potensi duplikasi usulan kegiatan.
C. Kementerian Dalam Negeri Kementerian Dalam Negeri memberikan pertimbangan terkait dengan:
a. aspek kewenangan pelaksanaan kegiatan;
b. kesesuaian kegiatan terhadap perencanaan pembangunan daerah dan perencanaan perangkat daerah; dan
c. kesesuaian terhadap prioritas standar pelayanan minimal suburusan bencana.', 'BAB II', 'Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (998, 'juklak-6-2025', 6, 'lain', 'BAB III', NULL, 4, 'MEKANISME PEMBERIAN PERTIMBANGAN Mekanisme pemberian pertimbangan merupakan proses pemberian pertimbangan sebagai bagian dari prosedur penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama yang dilakukan oleh kementerian/lembaga pemberi pertimbangan yang disampaikan kepada Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
A. Waktu
1. Pelaksanaan pemberian pertimbangan dimulai sejak BNPB menyampaikan permohonan pemberian pertimbangan penyaluran Dana Bersama kepada kementerian/lembaga pemberi pertimbangan.
2. Penyampaian permohonan pertimbangan sebagaimana dimaksud angka 1 dilaksanakan setelah BNPB mengoordinasikan daftar usulan kegiatan kepada Kementerian Koordinator Bidang Pembangunan Manusia dan Kebudayaan.
3. Risalah hasil pemberian pertimbangan disampaikan hingga paling lambat 10 (sepuluh) hari kerja terhitung sejak tanggal hasil verifikasi keluar.
B. Permohonan Pemberian Pertimbangan Penyampaian permohonan pemberian pertimbangan dilaksanakan secara kedinasan oleh pemohon pemberian pertimbangan penyaluran Dana Bersama, yakni Sekretaris Utama BNPB kepada penerima permohonan pertimbangan penyaluran Dana Bersama, yakni pejabat pimpinan tinggi madya pada kementerian/lembaga pemberi pertimbangan yang ditunjuk oleh masing-masing menteri/pimpinan lembaga untuk melaksanakan pemberian pertimbangan penyaluran Dana Bersama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (998, 'MEKANISME PEMBERIAN PERTIMBANGAN Mekanisme pemberian pertimbangan merupakan proses pemberian pertimbangan sebagai bagian dari prosedur penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama yang dilakukan oleh kementerian/lembaga pemberi pertimbangan yang disampaikan kepada Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
A. Waktu
1. Pelaksanaan pemberian pertimbangan dimulai sejak BNPB menyampaikan permohonan pemberian pertimbangan penyaluran Dana Bersama kepada kementerian/lembaga pemberi pertimbangan.
2. Penyampaian permohonan pertimbangan sebagaimana dimaksud angka 1 dilaksanakan setelah BNPB mengoordinasikan daftar usulan kegiatan kepada Kementerian Koordinator Bidang Pembangunan Manusia dan Kebudayaan.
3. Risalah hasil pemberian pertimbangan disampaikan hingga paling lambat 10 (sepuluh) hari kerja terhitung sejak tanggal hasil verifikasi keluar.
B. Permohonan Pemberian Pertimbangan Penyampaian permohonan pemberian pertimbangan dilaksanakan secara kedinasan oleh pemohon pemberian pertimbangan penyaluran Dana Bersama, yakni Sekretaris Utama BNPB kepada penerima permohonan pertimbangan penyaluran Dana Bersama, yakni pejabat pimpinan tinggi madya pada kementerian/lembaga pemberi pertimbangan yang ditunjuk oleh masing-masing menteri/pimpinan lembaga untuk melaksanakan pemberian pertimbangan penyaluran Dana Bersama.', 'BAB III', 'Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (999, 'juklak-6-2025', 7, 'lain', 'BAB III (lanjutan 1)', NULL, 4, 'C. Penyampaian Pemberian Pertimbangan Pelaksanaan penyampaian pemberian pertimbangan penyaluran Dana Bersama adalah sebagai berikut.
1. BNPB menyampaikan surat permohonan pertimbangan kepada kementerian/lembaga pemberi pertimbangan. Surat permohonan pertimbangan dilengkapi dengan salinan dokumen yang memuat informasi mengenai substansi permohonan penyaluran Dana Bersama.
2. Surat permohonan pertimbangan untuk penyaluran dana bersama tahap prabencana memuat daftar usulan permohonan kegiatan maksimal 10 (sepuluh) usulan.
3. Surat permohonan pertimbangan untuk penyaluran dana bersama tahap pascabencana memuat daftar usulan permohonan kegiatan maksimal 10 (sepuluh) usulan.
4. Dokumen sebagaimana dimaksud angka 1 terdiri atas:
a. kegiatan tahap prabencana, berupa:
1) dokumen permohonan penyaluran Dana Bersama tahap prabencana;
2) rencana anggaran biaya; dan 3) reviu Aparat Pengawas Intern Pemerintah pemohon.
b. kegiatan tahap pascabencana, berupa:
1) dokumen permohonan penyaluran Dana Bersama tahap pascabencana;
2) rencana anggaran biaya;
3) Rencana Rehabilitasi dan Rekonstruksi Pascabencana; dan 4) reviu Aparat Pengawas Intern Pemerintah pemohon.
5. Selain dokumen tersebut di atas, dalam rangka pelaksanaan pemberian pertimbangan, kementerian/lembaga pemberi pertimbangan dapat meminta salinan dokumen persyaratan lainnya kepada BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (999, 'C. Penyampaian Pemberian Pertimbangan Pelaksanaan penyampaian pemberian pertimbangan penyaluran Dana Bersama adalah sebagai berikut.
1. BNPB menyampaikan surat permohonan pertimbangan kepada kementerian/lembaga pemberi pertimbangan. Surat permohonan pertimbangan dilengkapi dengan salinan dokumen yang memuat informasi mengenai substansi permohonan penyaluran Dana Bersama.
2. Surat permohonan pertimbangan untuk penyaluran dana bersama tahap prabencana memuat daftar usulan permohonan kegiatan maksimal 10 (sepuluh) usulan.
3. Surat permohonan pertimbangan untuk penyaluran dana bersama tahap pascabencana memuat daftar usulan permohonan kegiatan maksimal 10 (sepuluh) usulan.
4. Dokumen sebagaimana dimaksud angka 1 terdiri atas:
a. kegiatan tahap prabencana, berupa:
1) dokumen permohonan penyaluran Dana Bersama tahap prabencana;
2) rencana anggaran biaya; dan 3) reviu Aparat Pengawas Intern Pemerintah pemohon.
b. kegiatan tahap pascabencana, berupa:
1) dokumen permohonan penyaluran Dana Bersama tahap pascabencana;
2) rencana anggaran biaya;
3) Rencana Rehabilitasi dan Rekonstruksi Pascabencana; dan 4) reviu Aparat Pengawas Intern Pemerintah pemohon.
5. Selain dokumen tersebut di atas, dalam rangka pelaksanaan pemberian pertimbangan, kementerian/lembaga pemberi pertimbangan dapat meminta salinan dokumen persyaratan lainnya kepada BNPB.', 'BAB III (lanjutan 1)', 'Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1000, 'juklak-6-2025', 8, 'lain', 'BAB III (lanjutan 2)', NULL, 5, '6. Permohonan berikut dokumen persyaratan administrasi sebagaimana dimaksud dalam angka 1 dikelola oleh Sekretariat Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana berikut dengan penyampaian salinan dokumen sebagaimana dimaksud dalam angka 4 dan/atau tambahan salinan dokumen persyaratan lainnya sebagaimana dimaksud dalam angka 5 kepada kementerian/lembaga pemberi pertimbangan.
7. Pelaksanaan pemberian pertimbangan oleh kementerian/lembaga pemberi pertimbangan disesuaikan dengan mekanisme dan/atau standar operasional prosedur sebagaimana diatur di internal kementerian/lembaga dimaksud.
8. Dalam melaksanakan pemberian pertimbangan, kementerian/lembaga pemberi pertimbangan dapat berkoordinasi dengan instansi dan/atau pihak terkait lainnya untuk memastikan kesesuaian kegiatan yang akan didanai.
9. Dalam rangka pemberitahuan pengakhiran tahap pemberian pertimbangan, BNPB menyampaikan surat pemberitahuan penyelesaian kegiatan verifikasi kepada kementerian/lembaga pemberi pertimbangan. Penerimaan surat dimaksud sebagai batas awal penghitungan 10 (sepuluh) hari batas waktu penyelesaian kegiatan pemberian pertimbangan.
10. Dalam hal pertimbangan tidak diberikan sampai batas waktu sebagaimana dimaksud pada huruf B, kementerian/lembaga pemberi pertimbangan dianggap telah memberikan pertimbangan.
11. Kementerian/lembaga pemberi pertimbangan menyampaikan hasil pertimbangan berupa risalah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1000, '6. Permohonan berikut dokumen persyaratan administrasi sebagaimana dimaksud dalam angka 1 dikelola oleh Sekretariat Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana berikut dengan penyampaian salinan dokumen sebagaimana dimaksud dalam angka 4 dan/atau tambahan salinan dokumen persyaratan lainnya sebagaimana dimaksud dalam angka 5 kepada kementerian/lembaga pemberi pertimbangan.
7. Pelaksanaan pemberian pertimbangan oleh kementerian/lembaga pemberi pertimbangan disesuaikan dengan mekanisme dan/atau standar operasional prosedur sebagaimana diatur di internal kementerian/lembaga dimaksud.
8. Dalam melaksanakan pemberian pertimbangan, kementerian/lembaga pemberi pertimbangan dapat berkoordinasi dengan instansi dan/atau pihak terkait lainnya untuk memastikan kesesuaian kegiatan yang akan didanai.
9. Dalam rangka pemberitahuan pengakhiran tahap pemberian pertimbangan, BNPB menyampaikan surat pemberitahuan penyelesaian kegiatan verifikasi kepada kementerian/lembaga pemberi pertimbangan. Penerimaan surat dimaksud sebagai batas awal penghitungan 10 (sepuluh) hari batas waktu penyelesaian kegiatan pemberian pertimbangan.
10. Dalam hal pertimbangan tidak diberikan sampai batas waktu sebagaimana dimaksud pada huruf B, kementerian/lembaga pemberi pertimbangan dianggap telah memberikan pertimbangan.
11. Kementerian/lembaga pemberi pertimbangan menyampaikan hasil pertimbangan berupa risalah.', 'BAB III (lanjutan 2)', 'Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1001, 'juklak-6-2025', 9, 'lain', 'BAB III (lanjutan 3)', NULL, 5, '12. Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana menghimpun dan memeriksa risalah hasil pertimbangan.
D. Risalah Pertimbangan
1. Risalah pertimbangan disampaikan oleh kementerian/lembaga pemberi pertimbangan kepada BNPB.
2. Risalah pertimbangan ditandatangani minimal oleh pejabat pimpinan tinggi madya pada kementerian/lembaga pemberi pertimbangan yang ditunjuk oleh masing-masing menteri/pimpinan lembaga untuk melaksanakan pemberian pertimbangan penyaluran Dana Bersama dan disampaikan secara kedinasan kepada Sekretaris Utama BNPB c.q. Penanggung Jawab Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
3. Risalah pertimbangan memuat narasi keselarasan dan kelayakan permohonan kegiatan yang diajukan dengan ruang lingkup pemberian pertimbangan.
4. Risalah pertimbangan dapat memuat pertimbangan terhadap 1 (satu) permohonan/lebih dari 1 (satu) permohonan/dibuat secara terpisah-pisah untuk masing-masing instansi pengusul penyaluran Dana Bersama.
5. Risalah pertimbangan dapat dilengkapi dengan kertas kerja yang memuat skoring sebagai bagian dari hasil telaah secara objektif terhadap permohonan kegiatan.
6. Perubahan risalah pertimbangan dapat dilakukan hanya jika masih disampaikan dalam jangka waktu pelaksanaan kegiatan pemberian pertimbangan. Penyampaian perubahan risalah pertimbangan dilaksanakan secara kedinasan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1001, '12. Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana menghimpun dan memeriksa risalah hasil pertimbangan.
D. Risalah Pertimbangan
1. Risalah pertimbangan disampaikan oleh kementerian/lembaga pemberi pertimbangan kepada BNPB.
2. Risalah pertimbangan ditandatangani minimal oleh pejabat pimpinan tinggi madya pada kementerian/lembaga pemberi pertimbangan yang ditunjuk oleh masing-masing menteri/pimpinan lembaga untuk melaksanakan pemberian pertimbangan penyaluran Dana Bersama dan disampaikan secara kedinasan kepada Sekretaris Utama BNPB c.q. Penanggung Jawab Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
3. Risalah pertimbangan memuat narasi keselarasan dan kelayakan permohonan kegiatan yang diajukan dengan ruang lingkup pemberian pertimbangan.
4. Risalah pertimbangan dapat memuat pertimbangan terhadap 1 (satu) permohonan/lebih dari 1 (satu) permohonan/dibuat secara terpisah-pisah untuk masing-masing instansi pengusul penyaluran Dana Bersama.
5. Risalah pertimbangan dapat dilengkapi dengan kertas kerja yang memuat skoring sebagai bagian dari hasil telaah secara objektif terhadap permohonan kegiatan.
6. Perubahan risalah pertimbangan dapat dilakukan hanya jika masih disampaikan dalam jangka waktu pelaksanaan kegiatan pemberian pertimbangan. Penyampaian perubahan risalah pertimbangan dilaksanakan secara kedinasan.', 'BAB III (lanjutan 3)', 'Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1002, 'juklak-6-2025', 10, 'lain', 'BAB III (lanjutan 4)', NULL, 6, '7. Risalah pertimbangan menjadi dasar pembuatan rekomendasi hasil penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama dari BNPB yang akan disampaikan kepada Kementerian Keuangan sebagai bagian dari proses penyaluran Dana Bersama kepada pemohon.
8. Risalah pertimbangan dapat disusun sesuai format sebagaimana dimuat dalam Lampiran Petunjuk Pelaksanaan ini.
9. Risalah pertimbangan paling sedikit memuat informasi mengenai pendahuluan, gambaran umum, pertimbangan, dan kesimpulan.
E. Rapat Koordinasi Pemberian Pertimbangan Penyaluran Dana Bersama Penanggulangan Bencana
1. Dalam hal terdapat perbedaan pendapat dalam hasil pertimbangan kementerian/lembaga pemberi pertimbangan sesuai hasil pemeriksaaan Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana sebagaimana dimaksud dalam huruf C angka 12, kementerian/lembaga pemberi pertimbangan dan BNPB dapat melakukan rapat koordinasi pemberian pertimbangan penyaluran Dana Bersama.
2. Rapat koordinasi pemberian pertimbangan penyaluran Dana Bersama merupakan forum diskusi untuk mengoordinasikan hasil pertimbangan penyaluran Dana Bersama yang dihadiri oleh kementerian/lembaga pemberi pertimbangan dan BNPB.
3. Rapat koordinasi dapat dilaksanakan minimal 1 (satu) kali dalam 1 (satu) periode penyampaian rekomendasi hasil penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama dari BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1002, '7. Risalah pertimbangan menjadi dasar pembuatan rekomendasi hasil penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama dari BNPB yang akan disampaikan kepada Kementerian Keuangan sebagai bagian dari proses penyaluran Dana Bersama kepada pemohon.
8. Risalah pertimbangan dapat disusun sesuai format sebagaimana dimuat dalam Lampiran Petunjuk Pelaksanaan ini.
9. Risalah pertimbangan paling sedikit memuat informasi mengenai pendahuluan, gambaran umum, pertimbangan, dan kesimpulan.
E. Rapat Koordinasi Pemberian Pertimbangan Penyaluran Dana Bersama Penanggulangan Bencana
1. Dalam hal terdapat perbedaan pendapat dalam hasil pertimbangan kementerian/lembaga pemberi pertimbangan sesuai hasil pemeriksaaan Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana sebagaimana dimaksud dalam huruf C angka 12, kementerian/lembaga pemberi pertimbangan dan BNPB dapat melakukan rapat koordinasi pemberian pertimbangan penyaluran Dana Bersama.
2. Rapat koordinasi pemberian pertimbangan penyaluran Dana Bersama merupakan forum diskusi untuk mengoordinasikan hasil pertimbangan penyaluran Dana Bersama yang dihadiri oleh kementerian/lembaga pemberi pertimbangan dan BNPB.
3. Rapat koordinasi dapat dilaksanakan minimal 1 (satu) kali dalam 1 (satu) periode penyampaian rekomendasi hasil penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama dari BNPB.', 'BAB III (lanjutan 4)', 'Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1003, 'juklak-6-2025', 11, 'lain', 'BAB III (lanjutan 5)', NULL, 6, '4. Rapat koordinasi diprakarsai oleh Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
5. Hasil rapat koordinasi menjadi bahan pendukung dalam menyusun rekomendasi hasil penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama dari BNPB yang akan disampaikan ke Kementerian Keuangan.
F. Sistem Informasi
1. Pemberian pertimbangan untuk penyaluran Dana Bersama dapat dilaksanakan melalui sistem informasi penelaahan, verifikasi dan evaluasi penyaluran Dana Bersama.
2. Pemberian Pertimbangan untuk penyaluran Dana Bersama dalam sistem informasi penelaahan, verifikasi dan evaluasi penyaluran Dana Bersama paling sedikit memuat:
a. permohonan pertimbangan;
b. waktu pengajuan permohonan pertimbangan;
c. waktu permohonan pertimbangan diterima;
d. proses pemberian pertimbangan;
e. penyampaian pertimbangan; dan
f. risalah pertimbangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1003, '4. Rapat koordinasi diprakarsai oleh Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
5. Hasil rapat koordinasi menjadi bahan pendukung dalam menyusun rekomendasi hasil penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama dari BNPB yang akan disampaikan ke Kementerian Keuangan.
F. Sistem Informasi
1. Pemberian pertimbangan untuk penyaluran Dana Bersama dapat dilaksanakan melalui sistem informasi penelaahan, verifikasi dan evaluasi penyaluran Dana Bersama.
2. Pemberian Pertimbangan untuk penyaluran Dana Bersama dalam sistem informasi penelaahan, verifikasi dan evaluasi penyaluran Dana Bersama paling sedikit memuat:
a. permohonan pertimbangan;
b. waktu pengajuan permohonan pertimbangan;
c. waktu permohonan pertimbangan diterima;
d. proses pemberian pertimbangan;
e. penyampaian pertimbangan; dan
f. risalah pertimbangan.', 'BAB III (lanjutan 5)', 'Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1004, 'juklak-6-2025', 12, 'lain', 'BAB IV', NULL, 8, 'PENUTUP Petunjuk Pelaksanaan ini merupakan instrumen turunan Peraturan BNPB Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana yang memberikan pedoman mengenai ruang lingkup dan mekanisme pemberian pertimbangan penyaluran dana bersama penanggulangan bencana bagi kementerian/lembaga pemberi pertimbangan dan BNPB.
Ditetapkan di Jakarta pada tanggal 07 Oktober 2025 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1004, 'PENUTUP Petunjuk Pelaksanaan ini merupakan instrumen turunan Peraturan BNPB Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana yang memberikan pedoman mengenai ruang lingkup dan mekanisme pemberian pertimbangan penyaluran dana bersama penanggulangan bencana bagi kementerian/lembaga pemberi pertimbangan dan BNPB.
Ditetapkan di Jakarta pada tanggal 07 Oktober 2025 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati', 'BAB IV', 'Petunjuk Pelaksanaan Pemberian Pertimbangan Untuk Penyaluran');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1005, 'juklak-6-2025', 13, 'lampiran', 'LAMPIRAN', NULL, 9, 'PETUNJUK PELAKSANAAN PEMBERIAN PERTIMBANGAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA NOMOR 6 TAHUN 2025 FORMAT RISALAH KOP Kementerian/Lembaga Risalah Pertimbangan Nomor: …… (sesuai tata naskah dinas K/L) A. Dasar Hukum Penerbitan Pertimbangan
1. (diisi dengan dasar hukum kewenangan K/L)
2. (diisi dengan dasar permohonan) B. Gambaran Umum (diisi dengan nama pemohon dan uraian singkat terkait dengan kegiatan yang dimohonkan) C. Pertimbangan (berisi aspek pertimbangan sesuai dengan kewenangan K/L) D. Kesimpulan (berisi simpulan berdasarkan pertimbangan sebagaimana disebutkan dalam huruf C berikut aspek atau alasan yang mendasari) Dibuat di…..
Pada tanggal… Nama Jabatan (ttd dan cap dinas/ tanda tangan elektronik) Nama Lengkap NIP.
