INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1006, 'juklak-6-2026', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1006, 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026', 'Judul', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1007, 'juklak-6-2026', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMENUHAN STANDAR PELAYANAN MINIMAL SUB-URUSAN BENCANA DAERAH KABUPATEN/KOTA UNTUK SUBKEGIATAN PENCARIAN, PERTOLONGAN DAN EVAKUASI KORBAN BENCANA NOMOR 6 TAHUN 2026');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1007, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMENUHAN STANDAR PELAYANAN MINIMAL SUB-URUSAN BENCANA DAERAH KABUPATEN/KOTA UNTUK SUBKEGIATAN PENCARIAN, PERTOLONGAN DAN EVAKUASI KORBAN BENCANA NOMOR 6 TAHUN 2026', 'Isi hal. 1', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1008, 'juklak-6-2026', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Setiap Warga Negara Indonesia berhak untuk mendapatkan pelindungan dan rasa aman dari ancaman bencana. Hal ini telah menjadi amanat dari Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Pemerintah dan Pemerintah Daerah bertanggung jawab dalam penyelenggaraan penanggulangan bencana, yang merupakan bagian tidak terpisahkan dari urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1008, 'PENDAHULUAN A. Latar Belakang Setiap Warga Negara Indonesia berhak untuk mendapatkan pelindungan dan rasa aman dari ancaman bencana. Hal ini telah menjadi amanat dari Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Pemerintah dan Pemerintah Daerah bertanggung jawab dalam penyelenggaraan penanggulangan bencana, yang merupakan bagian tidak terpisahkan dari urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar.', 'BAB I', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1009, 'juklak-6-2026', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menegaskan bahwa tugas Badan Nasional Penanggulangan Bencana yaitu memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana dan menetapkan standardisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundang-undangan. Sejalan dengan tugas tersebut, dalam rangka sinergitas dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2021 tentang Penerapan Standar Pelayanan Minimal, Badan Nasional Penanggulangan Bencana sebagai kementerian/lembaga yang membidangi urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar bidang penanggulangan bencana, perlu melakukan pembinaan secara teknis terhadap penerapan standar pelayanan minimal di daerah dengan memberikan pedoman dan pengarahan, menetapkan standarisasi serta melakukan perumusan dan penetapan norma, standar, prosedur, kriteria. Dalam hal ini Badan Nasional Penanggulangan Bencana sebagai lembaga teknis penanggulangan bencana memberikan pembinaan dan pedoman norma, standar, prosedur, dan kriteria pada penerapan standar pelayanan minimal sub-urusan bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1009, 'Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana menegaskan bahwa tugas Badan Nasional Penanggulangan Bencana yaitu memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana dan menetapkan standardisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundang-undangan. Sejalan dengan tugas tersebut, dalam rangka sinergitas dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2021 tentang Penerapan Standar Pelayanan Minimal, Badan Nasional Penanggulangan Bencana sebagai kementerian/lembaga yang membidangi urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar bidang penanggulangan bencana, perlu melakukan pembinaan secara teknis terhadap penerapan standar pelayanan minimal di daerah dengan memberikan pedoman dan pengarahan, menetapkan standarisasi serta melakukan perumusan dan penetapan norma, standar, prosedur, kriteria. Dalam hal ini Badan Nasional Penanggulangan Bencana sebagai lembaga teknis penanggulangan bencana memberikan pembinaan dan pedoman norma, standar, prosedur, dan kriteria pada penerapan standar pelayanan minimal sub-urusan bencana di daerah.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1010, 'juklak-6-2026', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 1, 'Untuk mempercepat penerapan Standar Pelayanan Minimal Sub-Urusan Bencana di daerah, Badan Nasional Penanggulangan Bencana perlu menyusun Petunjuk Pelaksanaan Pelayanan Standar Pelayanan Minimal Sub-Urusan Bencana untuk kabupaten/kota yang di dalamnya memuat penjabaran tahapan dan prosedur pelaksanaan pelayanan Standar Pelayanan Minimal Sub-Urusan Bencana. Petunjuk Pelaksanaan ini disusun untuk membantu daerah dalam memenuhi Mutu Pelayanan Dasar khususnya dalam pelaksanaan pelayanan pencarian, pertolongan dan evakuasi korban bencana.
Indonesia berada di wilayah yang sangat rawan bencana. Untuk mengurangi korban jiwa akibat bencana, pemerintah dan pemerintah daerah melakukan upaya penyelamatan melalui pencarian, pertolongan, dan evakuasi dalam situasi darurat bencana. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana dalam Pasal 52 mengatur bahwa penyelamatan dan evakuasi masyarakat terkena bencana dilakukan melalui pencarian dan penyelamatan korban, pertolongan darurat dan evakuasi korban. Hal ini secara umum telah dielaborasi dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan, dan Evakuasi, namun masih diperlukan sinkronisasi antara regulasi tersebut dengan implementasi yang ada di ranah sistem pemerintahan daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1010, 'Untuk mempercepat penerapan Standar Pelayanan Minimal Sub-Urusan Bencana di daerah, Badan Nasional Penanggulangan Bencana perlu menyusun Petunjuk Pelaksanaan Pelayanan Standar Pelayanan Minimal Sub-Urusan Bencana untuk kabupaten/kota yang di dalamnya memuat penjabaran tahapan dan prosedur pelaksanaan pelayanan Standar Pelayanan Minimal Sub-Urusan Bencana. Petunjuk Pelaksanaan ini disusun untuk membantu daerah dalam memenuhi Mutu Pelayanan Dasar khususnya dalam pelaksanaan pelayanan pencarian, pertolongan dan evakuasi korban bencana.
Indonesia berada di wilayah yang sangat rawan bencana. Untuk mengurangi korban jiwa akibat bencana, pemerintah dan pemerintah daerah melakukan upaya penyelamatan melalui pencarian, pertolongan, dan evakuasi dalam situasi darurat bencana. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana dalam Pasal 52 mengatur bahwa penyelamatan dan evakuasi masyarakat terkena bencana dilakukan melalui pencarian dan penyelamatan korban, pertolongan darurat dan evakuasi korban. Hal ini secara umum telah dielaborasi dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan, dan Evakuasi, namun masih diperlukan sinkronisasi antara regulasi tersebut dengan implementasi yang ada di ranah sistem pemerintahan daerah.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1011, 'juklak-6-2026', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, 'Bahwa kebutuhan atas kesamaan standar pelaksanaan, pemahaman, keterampilan, dan prosedur keselamatan ketika pencarian, pertolongan dan evakuasi korban bencana serta kebutuhan atas ketersediaan sarana prasarana penunjang evakuasi yang sesuai dengan jenis bencana dan lokasi operasi akan dapat meningkatkan efektivitas pelayanan atas respons lokal yang spesifik dan cepat.
Dengan adanya Petunjuk Pelaksanaan ini diharapkan upaya penerapan Standar Pelayanan Minimal Sub-urusan Bencana dapat terlaksana dengan lebih terarah, terkoordinasi dan sesuai dengan mutu dan sasaran yang telah ditetapkan. Selain itu, ketersediaan Petunjuk Pelaksanaan ini akan memudahkan setiap pelaku penanggulangan bencana termasuk pemerintah daerah untuk mengalokasikan, menggunakan, dan mempertanggungjawabkan anggaran kedaruratan secara cepat dan sesuai peraturan perundang-undangan saat bencana terjadi.
Berdasarkan pertimbangan sebagaimana disebutkan di atas, perlu menyusun dan menetapkan Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota Untuk Sub Kegiatan Pencarian, Pertolongan dan Evakuasi Korban Bencana.
B. Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini dimaksudkan sebagai acuan dalam prosedur pelaksanaan pelayanan dasar standar pelayanan minimal sub urusan bencana oleh Pemerintah Daerah yang berhak diperoleh setiap warga negara yang berada di kawasan bencana dan yang menjadi korban bencana secara minimal.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1011, 'Bahwa kebutuhan atas kesamaan standar pelaksanaan, pemahaman, keterampilan, dan prosedur keselamatan ketika pencarian, pertolongan dan evakuasi korban bencana serta kebutuhan atas ketersediaan sarana prasarana penunjang evakuasi yang sesuai dengan jenis bencana dan lokasi operasi akan dapat meningkatkan efektivitas pelayanan atas respons lokal yang spesifik dan cepat.
Dengan adanya Petunjuk Pelaksanaan ini diharapkan upaya penerapan Standar Pelayanan Minimal Sub-urusan Bencana dapat terlaksana dengan lebih terarah, terkoordinasi dan sesuai dengan mutu dan sasaran yang telah ditetapkan. Selain itu, ketersediaan Petunjuk Pelaksanaan ini akan memudahkan setiap pelaku penanggulangan bencana termasuk pemerintah daerah untuk mengalokasikan, menggunakan, dan mempertanggungjawabkan anggaran kedaruratan secara cepat dan sesuai peraturan perundang-undangan saat bencana terjadi.
Berdasarkan pertimbangan sebagaimana disebutkan di atas, perlu menyusun dan menetapkan Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota Untuk Sub Kegiatan Pencarian, Pertolongan dan Evakuasi Korban Bencana.
B. Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini dimaksudkan sebagai acuan dalam prosedur pelaksanaan pelayanan dasar standar pelayanan minimal sub urusan bencana oleh Pemerintah Daerah yang berhak diperoleh setiap warga negara yang berada di kawasan bencana dan yang menjadi korban bencana secara minimal.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1012, 'juklak-6-2026', 6, 'lain', 'BAB I (lanjutan 4)', NULL, 2, '2. Tujuan Tujuan Petunjuk Pelaksanaan ini adalah untuk mendukung menyediakan standar teknis atau tata cara pemenuhan pelayanan dasar pada subkegiatan Pencarian, Pertolongan dan Evakuasi Korban Bencana.
C. Ruang Lingkup Prosedur standar pelayanan minimal sub urusan bencana yang diatur dalam Petunjuk Pelaksanaan ini meliputi mekanisme operasional Pencarian, Pertolongan dan Evakuasi Korban Bencana.
D. Pengertian
1. Pelayanan Dasar adalah pelayanan publik untuk memenuhi kebutuhan dasar Warga Negara yang terkena dampak di kawasan rawan bencana dan yang menjadi korban bencana.
2. Standar Pelayanan Minimal yang selanjutnya disingkat SPM adalah ketentuan mengenai jenis dan mutu pelayanan dasar yang merupakan urusan pemerintahan wajib yang berhak diperoleh setiap Warga Negara secara minimal.
3. Standar Teknis adalah standar jumlah dan kualitas barang dan/atau jasa, sumber daya manusia dan petunjuk teknis atau tata cara pemenuhan standar.
4. Mutu Pelayanan Dasar adalah ukuran kuantitas dan kualitas barang dan/atau jasa kebutuhan dasar serta pemenuhannya secara minimal dalam Pelayanan Dasar sesuai Standar Teknis agar hidup secara layak.
5. Pencarian dan Pertolongan adalah segala usaha dan kegiatan mencari, menolong, menyelamatkan, dan mengevakuasi manusia yang menghadapi keadaan darurat dan/atau bahaya dalam kecelakaan, bencana, atau kondisi membahayakan manusia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1012, '2. Tujuan Tujuan Petunjuk Pelaksanaan ini adalah untuk mendukung menyediakan standar teknis atau tata cara pemenuhan pelayanan dasar pada subkegiatan Pencarian, Pertolongan dan Evakuasi Korban Bencana.
C. Ruang Lingkup Prosedur standar pelayanan minimal sub urusan bencana yang diatur dalam Petunjuk Pelaksanaan ini meliputi mekanisme operasional Pencarian, Pertolongan dan Evakuasi Korban Bencana.
D. Pengertian
1. Pelayanan Dasar adalah pelayanan publik untuk memenuhi kebutuhan dasar Warga Negara yang terkena dampak di kawasan rawan bencana dan yang menjadi korban bencana.
2. Standar Pelayanan Minimal yang selanjutnya disingkat SPM adalah ketentuan mengenai jenis dan mutu pelayanan dasar yang merupakan urusan pemerintahan wajib yang berhak diperoleh setiap Warga Negara secara minimal.
3. Standar Teknis adalah standar jumlah dan kualitas barang dan/atau jasa, sumber daya manusia dan petunjuk teknis atau tata cara pemenuhan standar.
4. Mutu Pelayanan Dasar adalah ukuran kuantitas dan kualitas barang dan/atau jasa kebutuhan dasar serta pemenuhannya secara minimal dalam Pelayanan Dasar sesuai Standar Teknis agar hidup secara layak.
5. Pencarian dan Pertolongan adalah segala usaha dan kegiatan mencari, menolong, menyelamatkan, dan mengevakuasi manusia yang menghadapi keadaan darurat dan/atau bahaya dalam kecelakaan, bencana, atau kondisi membahayakan manusia.', 'BAB I (lanjutan 4)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1013, 'juklak-6-2026', 7, 'lain', 'BAB I (lanjutan 5)', NULL, 3, '6. Evakuasi adalah kegiatan memindahkan korban dari lokasi kejadian bencana/kedaruratan ke tempat yang aman sampai mendapat penanganan medis lanjutan yang memadai.
7. Kelompok Berisiko adalah bayi, anak di bawah usia lima tahun, anak-anak, ibu hamil atau menyusui, penyandang disabilitas, dan orang lanjut usia.
8. Data Terpilah adalah nilai hasil pengamatan dan/atau pengukuran suatu variabel yang telah dikelompokkan menurut berbagai ciri, seperti jenis kelamin, wilayah, status sosial ekonomi, dan waktu.
9. Operasi Pencarian dan Pertolongan adalah serangkaian kegiatan meliputi pelaksanaan operasi pencarian dan pertolongan dan penghentian pelaksanaan operasi pencarian dan pertolongan.
10. Potensi Pencarian dan Pertolongan adalah sumber daya manusia, sarana dan prasarana, informasi dan teknologi, serta hewan, selain Badan Nasional Pencarian dan Pertolongan yang dapat dimanfaatkan untuk menunjang kegiatan penyelenggaraan Operasi Pencarian dan Pertolongan.
11. Status Keadaan Darurat Bencana adalah suatu keadaan yang ditetapkan oleh Pemerintah untuk jangka waktu tertentu atas dasar rekomendasi Badan yang diberi tugas untuk menanggulangi bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1013, '6. Evakuasi adalah kegiatan memindahkan korban dari lokasi kejadian bencana/kedaruratan ke tempat yang aman sampai mendapat penanganan medis lanjutan yang memadai.
7. Kelompok Berisiko adalah bayi, anak di bawah usia lima tahun, anak-anak, ibu hamil atau menyusui, penyandang disabilitas, dan orang lanjut usia.
8. Data Terpilah adalah nilai hasil pengamatan dan/atau pengukuran suatu variabel yang telah dikelompokkan menurut berbagai ciri, seperti jenis kelamin, wilayah, status sosial ekonomi, dan waktu.
9. Operasi Pencarian dan Pertolongan adalah serangkaian kegiatan meliputi pelaksanaan operasi pencarian dan pertolongan dan penghentian pelaksanaan operasi pencarian dan pertolongan.
10. Potensi Pencarian dan Pertolongan adalah sumber daya manusia, sarana dan prasarana, informasi dan teknologi, serta hewan, selain Badan Nasional Pencarian dan Pertolongan yang dapat dimanfaatkan untuk menunjang kegiatan penyelenggaraan Operasi Pencarian dan Pertolongan.
11. Status Keadaan Darurat Bencana adalah suatu keadaan yang ditetapkan oleh Pemerintah untuk jangka waktu tertentu atas dasar rekomendasi Badan yang diberi tugas untuk menanggulangi bencana.', 'BAB I (lanjutan 5)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1014, 'juklak-6-2026', 8, 'lain', 'BAB I (lanjutan 6)', NULL, 3, '12. Pos Komando Penanganan Darurat Bencana yang selanjutnya disingkat Posko PDB adalah institusi yang berfungsi sebagai pusat komando operasi penanganan darurat bencana yang merupakan posko utama di dalam sistem komando penanganan darurat bencana, untuk mengoordinasikan, mengendalikan, memantau, dan mengevaluasi pelaksanaan penanganan darurat bencana.
13. Tim Reaksi Cepat yang selanjutnya disingkat TRC adalah tim yang terdiri atas petugas yang memiliki kualifikasi dalam melakukan kegiatan kaji cepat bencana dan dampak bencana pada saat tanggap darurat.
14. Tim Reaksi Cepat Multisektor Provinsi/Kabupaten/Kota yang selanjutnya disebut TRC Multisektor adalah tim kolaborasi dan kerja sama multisektor dalam pelaksanaan tugas urusan penanggulangan bencana antara organisasi perangkat daerah, lembaga terkait dan unsur masyarakat lainnya secara sinergis dalam rangka penanganan darurat bencana yang dibentuk oleh Gubernur/Bupati/Walikota.
15. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintahan nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
16. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah perangkat daerah yang menyelenggarakan suburusan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1014, '12. Pos Komando Penanganan Darurat Bencana yang selanjutnya disingkat Posko PDB adalah institusi yang berfungsi sebagai pusat komando operasi penanganan darurat bencana yang merupakan posko utama di dalam sistem komando penanganan darurat bencana, untuk mengoordinasikan, mengendalikan, memantau, dan mengevaluasi pelaksanaan penanganan darurat bencana.
13. Tim Reaksi Cepat yang selanjutnya disingkat TRC adalah tim yang terdiri atas petugas yang memiliki kualifikasi dalam melakukan kegiatan kaji cepat bencana dan dampak bencana pada saat tanggap darurat.
14. Tim Reaksi Cepat Multisektor Provinsi/Kabupaten/Kota yang selanjutnya disebut TRC Multisektor adalah tim kolaborasi dan kerja sama multisektor dalam pelaksanaan tugas urusan penanggulangan bencana antara organisasi perangkat daerah, lembaga terkait dan unsur masyarakat lainnya secara sinergis dalam rangka penanganan darurat bencana yang dibentuk oleh Gubernur/Bupati/Walikota.
15. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintahan nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
16. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah perangkat daerah yang menyelenggarakan suburusan bencana.', 'BAB I (lanjutan 6)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1015, 'juklak-6-2026', 9, 'lain', 'BAB II', NULL, 5, 'PERSIAPAN PADA SAAT PRABENCANA Dalam rangka kesiapsiagaan menghadapi situasi bencana, diperlukan tindakan yang dilakukan jauh sebelum bencana tersebut terjadi. Pada situasi tidak terdapat bencana/ketika prabencana, semua pihak dapat menyiapkan strategi untuk memastikan kejadian bencana berdampak sangat minimal terhadap kehidupan dan penghidupan masyarakat. Strategi dimaksud tidak dibatasi pada kegiatan tertentu, namun disesuaikan dengan kebutuhan dan pilihan kebijakan sesuai kewenangan para pelaku penanggulangan bencana.
Dalam mendukung efektivitas pencarian, pertolongan dan evakuasi, ketika saat prabencana BPBD melakukan pengidentifikasian dan pendataan terhadap:
1. potensi sumber daya manusia, sarana dan prasarana, informasi dan teknologi, hewan, atau sumber daya lainnya yang dapat dimanfaatkan untuk menunjang kegiatan penyelenggaraan Operasi Pencarian dan Pertolongan; dan
2. lembaga/instansi yang mempunyai sarana dan prasarana pertolongan dan evakuasi serta yang dapat mendukung pembuatan jalur pertolongan dan evakuasi.
Sarana dan prasarana pertolongan dan evakuasi serta pembuatan jalur pertolongan dan evakuasi sebagaimana dimaksud di atas dapat berupa perahu penyelamat, tenda komando, mobil backhoe atau ekskavator, mobil buldoser, mobil dapur umum, ambulans, mobil komunikasi, dan lain-lain.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1015, 'PERSIAPAN PADA SAAT PRABENCANA Dalam rangka kesiapsiagaan menghadapi situasi bencana, diperlukan tindakan yang dilakukan jauh sebelum bencana tersebut terjadi. Pada situasi tidak terdapat bencana/ketika prabencana, semua pihak dapat menyiapkan strategi untuk memastikan kejadian bencana berdampak sangat minimal terhadap kehidupan dan penghidupan masyarakat. Strategi dimaksud tidak dibatasi pada kegiatan tertentu, namun disesuaikan dengan kebutuhan dan pilihan kebijakan sesuai kewenangan para pelaku penanggulangan bencana.
Dalam mendukung efektivitas pencarian, pertolongan dan evakuasi, ketika saat prabencana BPBD melakukan pengidentifikasian dan pendataan terhadap:
1. potensi sumber daya manusia, sarana dan prasarana, informasi dan teknologi, hewan, atau sumber daya lainnya yang dapat dimanfaatkan untuk menunjang kegiatan penyelenggaraan Operasi Pencarian dan Pertolongan; dan
2. lembaga/instansi yang mempunyai sarana dan prasarana pertolongan dan evakuasi serta yang dapat mendukung pembuatan jalur pertolongan dan evakuasi.
Sarana dan prasarana pertolongan dan evakuasi serta pembuatan jalur pertolongan dan evakuasi sebagaimana dimaksud di atas dapat berupa perahu penyelamat, tenda komando, mobil backhoe atau ekskavator, mobil buldoser, mobil dapur umum, ambulans, mobil komunikasi, dan lain-lain.', 'BAB II', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1016, 'juklak-6-2026', 10, 'lain', 'BAB II (lanjutan 1)', NULL, 5, 'Dalam melakukan pengidentifikasian dan pendataan, BPBD berkoordinasi dengan lembaga atau individu perorangan Potensi Pencarian dan Pertolongan yang mau bekerja sama untuk mendaftarkan dan melaporkan lembaga/dirinya ke BPBD dengan melengkapi dokumen berikut:
1. dokumen data diri, Kartu Tanda Penduduk, dan rincian kontak;
2. Daftar Riwayat Hidup singkat berisi pengalaman terkait;
3. surat izin dari instansi/lembaga tempat bernaung dan surat perintah penugasan;
4. sertifikat pendidikan dan pelatihan di bidang pencarian dan pertolongan atau sertifikat pelatihan teknis potensi pencarian dan pertolongan; dan
5. surat pernyataan sehat oleh petugas medis setempat.
Terhadap semua individu dan lembaga yang telah mendaftar dan melaporkan lembaga/dirinya akan diklasifikasikan berdasarkan kategori keterampilan pencarian dan pertolongan ke dalam kelompok potensi, antara lain:
1. reruntuhan bangunan;
2. ruang terbatas;
3. tanah longsor;
4. gunung dan hutan;
5. ketinggian;
6. jalan raya; dan
7. perairan (permukaan air dan bawah air).
Berdasarkan hasil pengklasifikasian di atas, BPBD membuat basis data Potensi Pencarian dan Pertolongan yang dikelompokkan berdasarkan asal lembaga, kemampuan/keterampilan sumber daya manusia, sarana dan prasarana, dan kesediaan untuk dilibatkan dalam Operasi Pencarian dan Pertolongan sewaktu-waktu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1016, 'Dalam melakukan pengidentifikasian dan pendataan, BPBD berkoordinasi dengan lembaga atau individu perorangan Potensi Pencarian dan Pertolongan yang mau bekerja sama untuk mendaftarkan dan melaporkan lembaga/dirinya ke BPBD dengan melengkapi dokumen berikut:
1. dokumen data diri, Kartu Tanda Penduduk, dan rincian kontak;
2. Daftar Riwayat Hidup singkat berisi pengalaman terkait;
3. surat izin dari instansi/lembaga tempat bernaung dan surat perintah penugasan;
4. sertifikat pendidikan dan pelatihan di bidang pencarian dan pertolongan atau sertifikat pelatihan teknis potensi pencarian dan pertolongan; dan
5. surat pernyataan sehat oleh petugas medis setempat.
Terhadap semua individu dan lembaga yang telah mendaftar dan melaporkan lembaga/dirinya akan diklasifikasikan berdasarkan kategori keterampilan pencarian dan pertolongan ke dalam kelompok potensi, antara lain:
1. reruntuhan bangunan;
2. ruang terbatas;
3. tanah longsor;
4. gunung dan hutan;
5. ketinggian;
6. jalan raya; dan
7. perairan (permukaan air dan bawah air).
Berdasarkan hasil pengklasifikasian di atas, BPBD membuat basis data Potensi Pencarian dan Pertolongan yang dikelompokkan berdasarkan asal lembaga, kemampuan/keterampilan sumber daya manusia, sarana dan prasarana, dan kesediaan untuk dilibatkan dalam Operasi Pencarian dan Pertolongan sewaktu-waktu.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1017, 'juklak-6-2026', 11, 'lain', 'BAB II (lanjutan 2)', NULL, 6, 'BPBD memanfaatkan media komunikasi dengan memperhatikan aksesibilitas dan inklusif untuk membangun dan memelihara jejaring potensi pencarian dan pertolongan. Hal ini juga akan mempermudah koordinasi ketika sewaktu-waktu dibutuhkan pengerahan ketika darurat bencana.
Pada saat tidak terjadi bencana/ketika prabencana, dapat dilakukan latihan bersama pencarian, pertolongan dan evakuasi di antara para Potensi Pencarian dan Pertolongan dengan melibatkan berbagai perangkat daerah terkait, lembaga penanggulangan bencana, TNI, Polri, dan organisasi terkait PPE lainnya.
Selain mendukung efektivitas pelaksanaan pencarian, pertolongan dan evakuasi, pelaksanaan identifikasi, pendataan, koordinasi, dan pelatihan ketika tahap prabencana memungkinkan adanya informasi terhadap kelayakan sumber daya dan pelaksanaan pencarian, pertolongan dan evakuasi yang dapat dipertanggungjawabkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1017, 'BPBD memanfaatkan media komunikasi dengan memperhatikan aksesibilitas dan inklusif untuk membangun dan memelihara jejaring potensi pencarian dan pertolongan. Hal ini juga akan mempermudah koordinasi ketika sewaktu-waktu dibutuhkan pengerahan ketika darurat bencana.
Pada saat tidak terjadi bencana/ketika prabencana, dapat dilakukan latihan bersama pencarian, pertolongan dan evakuasi di antara para Potensi Pencarian dan Pertolongan dengan melibatkan berbagai perangkat daerah terkait, lembaga penanggulangan bencana, TNI, Polri, dan organisasi terkait PPE lainnya.
Selain mendukung efektivitas pelaksanaan pencarian, pertolongan dan evakuasi, pelaksanaan identifikasi, pendataan, koordinasi, dan pelatihan ketika tahap prabencana memungkinkan adanya informasi terhadap kelayakan sumber daya dan pelaksanaan pencarian, pertolongan dan evakuasi yang dapat dipertanggungjawabkan.', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1018, 'juklak-6-2026', 12, 'lain', 'BAB III', NULL, 7, 'PELAKSANAAN A. Koordinasi Pembagian Zona/Wilayah Pencarian, Pertolongan dan Evakuasi Korban Bencana
1. Verifikasi data terpilah dengan akses dan inklusif serta informasi kedaruratan sebagai dasar penyusunan rencana operasi pencarian, pertolongan, dan evakuasi dilaksanakan oleh BPBD melalui tahapan sebagai berikut.
a. BPBD melakukan verifikasi dan analisis data terpilah dengan akses dan inklusivitas serta informasi kedaruratan dari masyarakat atau informasi hasil kaji cepat kejadian bencana.
Dalam pelaksanaannya, BPBD dapat melibatkan TRC Multisektor dalam mengidentifikasi kebutuhan pencarian, pertolongan dan evakuasi korban bencana dengan menggunakan data terpilah dengan akses dan inklusivitas.
Selain itu, TRC Multisektor juga dapat dimanfaatkan sebagai wadah koordinasi awal dalam penanganan darurat bencana.
Unsur di dalam TRC Multisektor juga dapat digerakkan untuk melaksanakan kegiatan pencarian, pertolongan dan evakuasi.
BPBD dan para pihak terkait atau melalui TRC Multisektor menginventarisasi, menghitung, dan menyiapkan sumber daya pencarian dan pertolongan (termasuk sumber daya lokal) yang dibutuhkan dan membagi tugas dan tanggung jawab di antara para petugas yang akan dikerahkan.
b. BPBD menentukan titik lokasi tepat kejadian bencana, luas wilayah terdampak dan memetakan kondisi cuaca, geografis, topografis, dan dampak bencana awal pada manusia (korban jiwa, terluka).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1018, 'PELAKSANAAN A. Koordinasi Pembagian Zona/Wilayah Pencarian, Pertolongan dan Evakuasi Korban Bencana
1. Verifikasi data terpilah dengan akses dan inklusif serta informasi kedaruratan sebagai dasar penyusunan rencana operasi pencarian, pertolongan, dan evakuasi dilaksanakan oleh BPBD melalui tahapan sebagai berikut.
a. BPBD melakukan verifikasi dan analisis data terpilah dengan akses dan inklusivitas serta informasi kedaruratan dari masyarakat atau informasi hasil kaji cepat kejadian bencana.
Dalam pelaksanaannya, BPBD dapat melibatkan TRC Multisektor dalam mengidentifikasi kebutuhan pencarian, pertolongan dan evakuasi korban bencana dengan menggunakan data terpilah dengan akses dan inklusivitas.
Selain itu, TRC Multisektor juga dapat dimanfaatkan sebagai wadah koordinasi awal dalam penanganan darurat bencana.
Unsur di dalam TRC Multisektor juga dapat digerakkan untuk melaksanakan kegiatan pencarian, pertolongan dan evakuasi.
BPBD dan para pihak terkait atau melalui TRC Multisektor menginventarisasi, menghitung, dan menyiapkan sumber daya pencarian dan pertolongan (termasuk sumber daya lokal) yang dibutuhkan dan membagi tugas dan tanggung jawab di antara para petugas yang akan dikerahkan.
b. BPBD menentukan titik lokasi tepat kejadian bencana, luas wilayah terdampak dan memetakan kondisi cuaca, geografis, topografis, dan dampak bencana awal pada manusia (korban jiwa, terluka).', 'BAB III', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1019, 'juklak-6-2026', 13, 'lain', 'BAB III (lanjutan 1)', NULL, 7, 'Berdasarkan informasi di atas, BPBD dan para pihak atau melalui TRC Multisektor berkoordinasi menentukan bentuk Operasi Pencarian dan Pertolongan serta peralatan yang akan digunakan.
c. BPBD dan para pihak atau melalui TRC Multisektor berkoordinasi dalam penyusunan rencana operasi pencarian, pertolongan, dan evakuasi yang sistematis dan terpadu.
Rencana operasi juga memuat rute evakuasi dan tempat penampungan, mekanisme komunikasi dan pertukaran informasi, pengaturan keamanan, dan evaluasi serta penyesuaian dalam pelaksanaan operasi. Pembuatan rencana operasi pencarian, pertolongan, dan evakuasi memperhatikan dokumen rencana kontingensi yang sudah ada.
Dalam hal terdapat keterbatasan sumber daya di daerah dalam pelaksanaan verifikasi data terpilah, BPBD dapat meminta dukungan BNPB untuk melakukan pendampingan pelaksanaan verifikasi dimaksud.
2. Potensi Pencarian dan Pertolongan mendaftarkan dan melaporkan lembaga/dirinya ke Posko PDB.
a. BPBD mengaktifkan Potensi Pencarian dan Pertolongan yang ada dalam basis data melalui media komunikasi dengan akses dan inklusif untuk mendukung Operasi Pencarian dan Pertolongan.
b. Potensi Pencarian dan Pertolongan yang sudah terdaftar dalam basis data BPBD harus melakukan daftar ulang ke bagian penanganan kedaruratan BPBD dan/atau Posko PDB dengan melampirkan dokumen antara lain:
1) fotokopi KTP;
2) surat tugas dari lembaga asal; dan 3) surat keterangan sehat dari fasilitas kesehatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1019, 'Berdasarkan informasi di atas, BPBD dan para pihak atau melalui TRC Multisektor berkoordinasi menentukan bentuk Operasi Pencarian dan Pertolongan serta peralatan yang akan digunakan.
c. BPBD dan para pihak atau melalui TRC Multisektor berkoordinasi dalam penyusunan rencana operasi pencarian, pertolongan, dan evakuasi yang sistematis dan terpadu.
Rencana operasi juga memuat rute evakuasi dan tempat penampungan, mekanisme komunikasi dan pertukaran informasi, pengaturan keamanan, dan evaluasi serta penyesuaian dalam pelaksanaan operasi. Pembuatan rencana operasi pencarian, pertolongan, dan evakuasi memperhatikan dokumen rencana kontingensi yang sudah ada.
Dalam hal terdapat keterbatasan sumber daya di daerah dalam pelaksanaan verifikasi data terpilah, BPBD dapat meminta dukungan BNPB untuk melakukan pendampingan pelaksanaan verifikasi dimaksud.
2. Potensi Pencarian dan Pertolongan mendaftarkan dan melaporkan lembaga/dirinya ke Posko PDB.
a. BPBD mengaktifkan Potensi Pencarian dan Pertolongan yang ada dalam basis data melalui media komunikasi dengan akses dan inklusif untuk mendukung Operasi Pencarian dan Pertolongan.
b. Potensi Pencarian dan Pertolongan yang sudah terdaftar dalam basis data BPBD harus melakukan daftar ulang ke bagian penanganan kedaruratan BPBD dan/atau Posko PDB dengan melampirkan dokumen antara lain:
1) fotokopi KTP;
2) surat tugas dari lembaga asal; dan 3) surat keterangan sehat dari fasilitas kesehatan.', 'BAB III (lanjutan 1)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1020, 'juklak-6-2026', 14, 'lain', 'BAB III (lanjutan 2)', NULL, 8, 'c. Potensi Pencarian dan Pertolongan yang tidak terdaftar dalam basis data BPBD harus melakukan pendaftaran terlebih dahulu ke Posko PDB sesuai dengan ketentuan yang berlaku.
d. Semua Potensi Pencarian dan Pertolongan wajib membawa peralatan pribadi dan alat pelindung diri yang sesuai dengan karakteristik wilayah dan jenis operasi pencarian, pertolongan dan evakuasi.
3. Penentuan bentuk operasi pencarian, pertolongan dan evakuasi
a. Dalam menentukan bentuk operasi pencarian, pertolongan dan evakuasi korban bencana mempertimbangkan tingkat waktu respons cepat dan waktu tempuh dengan mengidentifikasi, menghitung serta menginventarisasi kebutuhan terutama kelompok berisiko dan sumber daya lokal, termasuk potensi risiko sekunder bagi keselamatan petugas pencarian, pertolongan dan evakuasi dan korban bencana.
b. Tingkat waktu respons cepat paling lama 25 (dua puluh lima) menit yang dihitung sejak informasi/laporan kedaruratan dan kejadian bencana diterima sampai dengan unit pencarian dan pertolongan siap diberangkatkan. Sedangkan tingkat waktu tempuh ditentukan paling lama 150 (seratus lima puluh) menit yang dihitung sejak unit pencarian dan pertolongan dikerahkan sampai tiba di lokasi kejadian.
c. Penetapan waktu tempuh ini tanpa memperhitungkan hambatan seperti cuaca, kondisi jalan seperti berlubang, mendaki, berbelok-belok, macet, akses jalan terputus, dan gangguan keamanan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1020, 'c. Potensi Pencarian dan Pertolongan yang tidak terdaftar dalam basis data BPBD harus melakukan pendaftaran terlebih dahulu ke Posko PDB sesuai dengan ketentuan yang berlaku.
d. Semua Potensi Pencarian dan Pertolongan wajib membawa peralatan pribadi dan alat pelindung diri yang sesuai dengan karakteristik wilayah dan jenis operasi pencarian, pertolongan dan evakuasi.
3. Penentuan bentuk operasi pencarian, pertolongan dan evakuasi
a. Dalam menentukan bentuk operasi pencarian, pertolongan dan evakuasi korban bencana mempertimbangkan tingkat waktu respons cepat dan waktu tempuh dengan mengidentifikasi, menghitung serta menginventarisasi kebutuhan terutama kelompok berisiko dan sumber daya lokal, termasuk potensi risiko sekunder bagi keselamatan petugas pencarian, pertolongan dan evakuasi dan korban bencana.
b. Tingkat waktu respons cepat paling lama 25 (dua puluh lima) menit yang dihitung sejak informasi/laporan kedaruratan dan kejadian bencana diterima sampai dengan unit pencarian dan pertolongan siap diberangkatkan. Sedangkan tingkat waktu tempuh ditentukan paling lama 150 (seratus lima puluh) menit yang dihitung sejak unit pencarian dan pertolongan dikerahkan sampai tiba di lokasi kejadian.
c. Penetapan waktu tempuh ini tanpa memperhitungkan hambatan seperti cuaca, kondisi jalan seperti berlubang, mendaki, berbelok-belok, macet, akses jalan terputus, dan gangguan keamanan.', 'BAB III (lanjutan 2)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1021, 'juklak-6-2026', 15, 'lain', 'BAB III (lanjutan 3)', NULL, 8, 'd. Apabila di lokasi kedaruratan atau kejadian bencana di tingkat desa/kelurahan terdapat Potensi Pencarian dan Pertolongan yang terkoordinasi dengan BPBD yang melakukan upaya pencarian, pertolongan dan evakuasi korban bencana, sudah tercakup dalam penghitungan tingkat waktu respons cepat dan waktu tempuh.
4. Pembagian zona pencarian dengan membuat batasan lokasi bencana
a. Berdasarkan hasil verifikasi data terpilah dan informasi kedaruratan atau kejadian bencana, BPBD dan para pihak terkait berkoordinasi untuk membagi zona pencarian (perkiraan lokasi di mana korban berada berdasarkan hasil pengkajian teknis), dengan membuat batasan lokasi bencana berdasarkan klasifikasi berikut.
1) Ring/zona I yaitu daerah tempat terjadinya bencana, kemungkinan ditemukan korban paling banyak, dan kemungkinan munculnya bencana susulan.
2) Ring/zona II yaitu daerah sekitar terjadinya bencana yang masih dimungkinkan ditemukan korban.
3) Ring/zona III yaitu daerah yang relatif aman untuk dijadikan tempat evakuasi sementara.
b. Apabila diperlukan sesuai kondisi di lapangan, dapat dibuat pos-pos lapangan pencarian dan pertolongan untuk mengelola pelaksanaan penanganan darurat bencana sesuai rencana operasi di bawah komando dan koordinasi Posko PDB.
Persyaratan petugas pos lapangan antara lain:
1) memiliki kemampuan dalam pengelolaan zona operasi untuk seluruh daerah di suatu kawasan; dan 2) memiliki kemampuan komunikasi darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1021, 'd. Apabila di lokasi kedaruratan atau kejadian bencana di tingkat desa/kelurahan terdapat Potensi Pencarian dan Pertolongan yang terkoordinasi dengan BPBD yang melakukan upaya pencarian, pertolongan dan evakuasi korban bencana, sudah tercakup dalam penghitungan tingkat waktu respons cepat dan waktu tempuh.
4. Pembagian zona pencarian dengan membuat batasan lokasi bencana
a. Berdasarkan hasil verifikasi data terpilah dan informasi kedaruratan atau kejadian bencana, BPBD dan para pihak terkait berkoordinasi untuk membagi zona pencarian (perkiraan lokasi di mana korban berada berdasarkan hasil pengkajian teknis), dengan membuat batasan lokasi bencana berdasarkan klasifikasi berikut.
1) Ring/zona I yaitu daerah tempat terjadinya bencana, kemungkinan ditemukan korban paling banyak, dan kemungkinan munculnya bencana susulan.
2) Ring/zona II yaitu daerah sekitar terjadinya bencana yang masih dimungkinkan ditemukan korban.
3) Ring/zona III yaitu daerah yang relatif aman untuk dijadikan tempat evakuasi sementara.
b. Apabila diperlukan sesuai kondisi di lapangan, dapat dibuat pos-pos lapangan pencarian dan pertolongan untuk mengelola pelaksanaan penanganan darurat bencana sesuai rencana operasi di bawah komando dan koordinasi Posko PDB.
Persyaratan petugas pos lapangan antara lain:
1) memiliki kemampuan dalam pengelolaan zona operasi untuk seluruh daerah di suatu kawasan; dan 2) memiliki kemampuan komunikasi darurat bencana.', 'BAB III (lanjutan 3)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1022, 'juklak-6-2026', 16, 'lain', 'BAB III (lanjutan 4)', NULL, 9, 'Jumlah petugas pos lapangan disesuaikan dengan kebutuhan operasi penanganan darurat bencana.
c. Peralatan komunikasi darurat lapangan disesuaikan dengan jumlah zona dan personel pada operasi PPE. Peralatan komunikasi darurat setidaknya melingkupi fungsi untuk:
1) Saluran dan/atau frekuensi khusus komunikasi antar komando penanganan darurat.
2) Saluran dan/atau frekuensi khusus komunikasi antar pengelola operasi penanganan darurat bencana.
3) Saluran dan/atau frekuensi khusus komunikasi antar unit operasi penanganan darurat bencana.
4) Fasilitas utama peralatan komunikasi darurat dua arah.
5) Fasilitas cadangan peralatan komunikasi darurat dua arah.
6) Catatan komunikasi darurat tertentu.
B. Penyediaan Sarana dan Prasarana Pencarian, Pertolongan dan Evakuasi dan Pembuatan Jalur Pertolongan dan Evakuasi
1. Identifikasi kebutuhan sarana dan prasarana serta menyiapkan sarana dan prasarana (termasuk sumber daya lokal)
a. Berdasarkan basis data yang sudah disusun pada saat prabencana, BPBD mengaktifkan Potensi Pencarian dan Pertolongan dan/atau lembaga/instansi yang mempunyai sarana dan prasarana pertolongan dan evakuasi serta pembuatan jalur pertolongan dan evakuasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1022, 'Jumlah petugas pos lapangan disesuaikan dengan kebutuhan operasi penanganan darurat bencana.
c. Peralatan komunikasi darurat lapangan disesuaikan dengan jumlah zona dan personel pada operasi PPE. Peralatan komunikasi darurat setidaknya melingkupi fungsi untuk:
1) Saluran dan/atau frekuensi khusus komunikasi antar komando penanganan darurat.
2) Saluran dan/atau frekuensi khusus komunikasi antar pengelola operasi penanganan darurat bencana.
3) Saluran dan/atau frekuensi khusus komunikasi antar unit operasi penanganan darurat bencana.
4) Fasilitas utama peralatan komunikasi darurat dua arah.
5) Fasilitas cadangan peralatan komunikasi darurat dua arah.
6) Catatan komunikasi darurat tertentu.
B. Penyediaan Sarana dan Prasarana Pencarian, Pertolongan dan Evakuasi dan Pembuatan Jalur Pertolongan dan Evakuasi
1. Identifikasi kebutuhan sarana dan prasarana serta menyiapkan sarana dan prasarana (termasuk sumber daya lokal)
a. Berdasarkan basis data yang sudah disusun pada saat prabencana, BPBD mengaktifkan Potensi Pencarian dan Pertolongan dan/atau lembaga/instansi yang mempunyai sarana dan prasarana pertolongan dan evakuasi serta pembuatan jalur pertolongan dan evakuasi.', 'BAB III (lanjutan 4)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1023, 'juklak-6-2026', 17, 'lain', 'BAB III (lanjutan 5)', NULL, 9, 'b. Lingkup jenis, kuantitas, dan kualitas sarana dan prasarana antara lain pengadaan alat transportasi, peralatan pertolongan, alat komunikasi, peralatan pendukung, alat berat untuk kegiatan PPE mengacu pada peraturan perundang-undangan yang mengatur mengenai Pedoman Pencarian, Pertolongan dan Evakuasi sesuai kajian kondisi dan kebutuhan daerah rawan bencana di kabupaten/kota bersangkutan.
c. Dalam melakukan identifikasi kebutuhan sarana dan prasarana memperhatikan dokumen Kajian Risiko Bencana dan Rencana Kontingensi yang sudah ada sebagai referensi, serta aksesibilitas dan inklusif.
a. Sarana dan prasarana pertolongan dan evakuasi disesuaikan dengan durasi dan perkembangan operasi penanganan darurat bencana. Tiap sarana dan prasarana pertolongan evakuasi paling sedikit memiliki fungsi untuk:
1) peralatan pencarian dan fasilitas penanganan orang hilang;
2) peralatan pencarian dan fasilitas penanganan orang meninggal;
3) peralatan dan fasilitas penanganan medis; atau 4) peralatan dan fasilitas pengungsian.
b. Sarana dan prasarana pembuatan jalur pertolongan dan evakuasi disesuaikan dengan durasi dan perkembangan operasi penanganan darurat bencana. Tiap sarana dan prasarana pembuatan jalur pertolongan dan evakuasi paling sedikit memiliki fungsi untuk:
1) prasarana pembangunan jembatan darurat;
2) prasarana pembuka jalan alternatif; atau 3) prasarana transportasi bantuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1023, 'b. Lingkup jenis, kuantitas, dan kualitas sarana dan prasarana antara lain pengadaan alat transportasi, peralatan pertolongan, alat komunikasi, peralatan pendukung, alat berat untuk kegiatan PPE mengacu pada peraturan perundang-undangan yang mengatur mengenai Pedoman Pencarian, Pertolongan dan Evakuasi sesuai kajian kondisi dan kebutuhan daerah rawan bencana di kabupaten/kota bersangkutan.
c. Dalam melakukan identifikasi kebutuhan sarana dan prasarana memperhatikan dokumen Kajian Risiko Bencana dan Rencana Kontingensi yang sudah ada sebagai referensi, serta aksesibilitas dan inklusif.
a. Sarana dan prasarana pertolongan dan evakuasi disesuaikan dengan durasi dan perkembangan operasi penanganan darurat bencana. Tiap sarana dan prasarana pertolongan evakuasi paling sedikit memiliki fungsi untuk:
1) peralatan pencarian dan fasilitas penanganan orang hilang;
2) peralatan pencarian dan fasilitas penanganan orang meninggal;
3) peralatan dan fasilitas penanganan medis; atau 4) peralatan dan fasilitas pengungsian.
b. Sarana dan prasarana pembuatan jalur pertolongan dan evakuasi disesuaikan dengan durasi dan perkembangan operasi penanganan darurat bencana. Tiap sarana dan prasarana pembuatan jalur pertolongan dan evakuasi paling sedikit memiliki fungsi untuk:
1) prasarana pembangunan jembatan darurat;
2) prasarana pembuka jalan alternatif; atau 3) prasarana transportasi bantuan.', 'BAB III (lanjutan 5)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1024, 'juklak-6-2026', 18, 'lain', 'BAB III (lanjutan 6)', NULL, 10, '2. Koordinasi penentuan bentuk operasi pencarian, pertolongan dan evakuasi, sarana dan prasarana, serta peralatan yang akan digunakan
a. Posko PDB menentukan bentuk operasi pencarian, pertolongan dan evakuasi, sarana dan prasarana, serta peralatan yang akan digunakan sesuai jenis kejadian bencana, karakter wilayah operasi di lapangan, dan kebutuhan warga masyarakat terdampak.
3. Pelaksanaan pembuatan jalur pertolongan dan evakuasi dilaksanakan berdasarkan rencana operasi
c. BPBD dapat melibatkan perangkat daerah teknis terkait, lembaga usaha, dan lembaga penanggulangan bencana dalam pembuatan jalur pertolongan dan evakuasi.
d. Pelibatan mencakup penggunaan sumber daya sarana prasarana yang dimiliki dan penugasan operator untuk mengoperasikan sarana dan prasarana pertolongan dan evakuasi serta pembuatan jalur pertolongan dan evakuasi.
e. Penggunaan sarana dan prasarana pencarian, pertolongan dan evakuasi disesuaikan dengan jenis kejadian bencana, karakter wilayah operasi di lapangan, dan kebutuhan warga masyarakat terdampak.
f. Petugas pencarian, pertolongan dan evakuasi wajib menggunakan alat pelindung diri petugas pencarian, pertolongan dan evakuasi sesuai dengan karakteristik wilayah dan jenis operasi pencarian, pertolongan dan evakuasi.
C. Operasional Penyelamatan Melalui Pencarian, Pertolongan dan Evakuasi Korban Bencana
1. Pelaksanaan operasi pencarian, pertolongan dan evakuasi dilakukan sesuai rencana operasi dan zona pencarian');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1024, '2. Koordinasi penentuan bentuk operasi pencarian, pertolongan dan evakuasi, sarana dan prasarana, serta peralatan yang akan digunakan
a. Posko PDB menentukan bentuk operasi pencarian, pertolongan dan evakuasi, sarana dan prasarana, serta peralatan yang akan digunakan sesuai jenis kejadian bencana, karakter wilayah operasi di lapangan, dan kebutuhan warga masyarakat terdampak.
3. Pelaksanaan pembuatan jalur pertolongan dan evakuasi dilaksanakan berdasarkan rencana operasi
c. BPBD dapat melibatkan perangkat daerah teknis terkait, lembaga usaha, dan lembaga penanggulangan bencana dalam pembuatan jalur pertolongan dan evakuasi.
d. Pelibatan mencakup penggunaan sumber daya sarana prasarana yang dimiliki dan penugasan operator untuk mengoperasikan sarana dan prasarana pertolongan dan evakuasi serta pembuatan jalur pertolongan dan evakuasi.
e. Penggunaan sarana dan prasarana pencarian, pertolongan dan evakuasi disesuaikan dengan jenis kejadian bencana, karakter wilayah operasi di lapangan, dan kebutuhan warga masyarakat terdampak.
f. Petugas pencarian, pertolongan dan evakuasi wajib menggunakan alat pelindung diri petugas pencarian, pertolongan dan evakuasi sesuai dengan karakteristik wilayah dan jenis operasi pencarian, pertolongan dan evakuasi.
C. Operasional Penyelamatan Melalui Pencarian, Pertolongan dan Evakuasi Korban Bencana
1. Pelaksanaan operasi pencarian, pertolongan dan evakuasi dilakukan sesuai rencana operasi dan zona pencarian', 'BAB III (lanjutan 6)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1025, 'juklak-6-2026', 19, 'lain', 'BAB III (lanjutan 7)', NULL, 10, 'a. Rencana operasi pencarian, pertolongan dan evakuasi dan zona pencarian yang telah disusun bersama para pemangku kepentingan PPE menjadi acuan dalam operasional pencarian, pertolongan dan evakuasi di lapangan.
b. BPBD menyediakan sarana-prasarana pendukung operasional yang dibutuhkan sesuai kebutuhan yang teridentifikasi di dalam rencana operasi.
c. Petugas pencarian, pertolongan dan evakuasi yang mengikuti operasi pencarian, pertolongan dan evakuasi di lapangan wajib membawa alat pelindung diri yang sesuai dengan kondisi lapangan dan peralatan pribadi lainnya.
d. Petugas PPE termasuk TRC dengan melibatkan unsur terkait (mengakomodasi TRC Multisektor) dan masyarakat (potensi pencarian dan pertolongan). Peran petugas pencarian, pertolongan dan evakuasi ketika operasi dapat ditentukan sesuai keadaan di lapangan, seperti penyelamat (rescuer), peralatan dan logistik, komunikasi, evakuasi, dan lain-lain.
e. Data operasi pencarian, penyelamatan, dan evakuasi korban bencana disesuaikan dengan jumlah shift periode operasi dan durasi operasi pencarian, pertolongan dan evakuasi korban bencana. Petugas pencarian, pertolongan dan evakuasi yang bertanggung jawab atas data bertugas untuk mendata, mencatat, dan melaporkan kepada Pos Lapangan dan/atau Posko PDB terkait perkembangan operasi pencarian, penyelamatan, dan evakuasi korban bencana, sebaiknya berupa data terpilah dan setidaknya mencakup:
1) Data korban meninggal.
2) Data korban hilang.
3) Data korban luka ringan dan berat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1025, 'a. Rencana operasi pencarian, pertolongan dan evakuasi dan zona pencarian yang telah disusun bersama para pemangku kepentingan PPE menjadi acuan dalam operasional pencarian, pertolongan dan evakuasi di lapangan.
b. BPBD menyediakan sarana-prasarana pendukung operasional yang dibutuhkan sesuai kebutuhan yang teridentifikasi di dalam rencana operasi.
c. Petugas pencarian, pertolongan dan evakuasi yang mengikuti operasi pencarian, pertolongan dan evakuasi di lapangan wajib membawa alat pelindung diri yang sesuai dengan kondisi lapangan dan peralatan pribadi lainnya.
d. Petugas PPE termasuk TRC dengan melibatkan unsur terkait (mengakomodasi TRC Multisektor) dan masyarakat (potensi pencarian dan pertolongan). Peran petugas pencarian, pertolongan dan evakuasi ketika operasi dapat ditentukan sesuai keadaan di lapangan, seperti penyelamat (rescuer), peralatan dan logistik, komunikasi, evakuasi, dan lain-lain.
e. Data operasi pencarian, penyelamatan, dan evakuasi korban bencana disesuaikan dengan jumlah shift periode operasi dan durasi operasi pencarian, pertolongan dan evakuasi korban bencana. Petugas pencarian, pertolongan dan evakuasi yang bertanggung jawab atas data bertugas untuk mendata, mencatat, dan melaporkan kepada Pos Lapangan dan/atau Posko PDB terkait perkembangan operasi pencarian, penyelamatan, dan evakuasi korban bencana, sebaiknya berupa data terpilah dan setidaknya mencakup:
1) Data korban meninggal.
2) Data korban hilang.
3) Data korban luka ringan dan berat.', 'BAB III (lanjutan 7)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1026, 'juklak-6-2026', 20, 'lain', 'BAB III (lanjutan 8)', NULL, 11, '4) Data pengungsi.
2. Mekanisme Operasi pencarian, pertolongan dan evakuasi korban bencana dilaksanakan sesuai ketentuan peraturan perundang-undangan yang mengatur mengenai pencarian, pertolongan, dan evakuasi.
a. Pelaksanaan pencarian, pertolongan dan evakuasi melalui Posko PDB dan berada di bawah kendali Komandan PDB dan secara operasional di bawah Bidang Operasional Posko PDB.
b. Susunan organisasi Operasi Pencarian dan Pertolongan terdiri atas:
1) koordinator pencarian dan pertolongan sebagai pengarah;
2) koordinator misi pencarian dan pertolongan;
3) koordinator lapangan; dan 4) unit pencarian dan pertolongan.
c. Koordinator Misi Pencarian dan Pertolongan dalam melaksanakan tugas didukung staf yang terdiri atas:
1) bidang operasi;
2) bidang intelijen;
3) bidang komunikasi;
4) bidang administrasi;
5) bidang logistik;
6) bidang medis; dan/atau 7) bidang humas, data, dan informasi.
Staf merupakan petugas pencarian dan pertolongan yang berasal dari BPBD dan/atau instansi/organisasi potensi pencarian dan pertolongan.
d. Koordinator Lapangan merupakan pejabat atau staf yang ditugaskan oleh Koordinator Misi Pencarian dan Pertolongan untuk:
1) melaksanakan Operasi Pencarian dan Pertolongan di bawah koordinasi dan kendali Koordinator Misi Pencarian dan Pertolongan; dan 2) melaksanakan koordinasi, pengendalian dan pemantauan pergerakan unit pencarian dan pertolongan di daerah pencarian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1026, '4) Data pengungsi.
2. Mekanisme Operasi pencarian, pertolongan dan evakuasi korban bencana dilaksanakan sesuai ketentuan peraturan perundang-undangan yang mengatur mengenai pencarian, pertolongan, dan evakuasi.
a. Pelaksanaan pencarian, pertolongan dan evakuasi melalui Posko PDB dan berada di bawah kendali Komandan PDB dan secara operasional di bawah Bidang Operasional Posko PDB.
b. Susunan organisasi Operasi Pencarian dan Pertolongan terdiri atas:
1) koordinator pencarian dan pertolongan sebagai pengarah;
2) koordinator misi pencarian dan pertolongan;
3) koordinator lapangan; dan 4) unit pencarian dan pertolongan.
c. Koordinator Misi Pencarian dan Pertolongan dalam melaksanakan tugas didukung staf yang terdiri atas:
1) bidang operasi;
2) bidang intelijen;
3) bidang komunikasi;
4) bidang administrasi;
5) bidang logistik;
6) bidang medis; dan/atau 7) bidang humas, data, dan informasi.
Staf merupakan petugas pencarian dan pertolongan yang berasal dari BPBD dan/atau instansi/organisasi potensi pencarian dan pertolongan.
d. Koordinator Lapangan merupakan pejabat atau staf yang ditugaskan oleh Koordinator Misi Pencarian dan Pertolongan untuk:
1) melaksanakan Operasi Pencarian dan Pertolongan di bawah koordinasi dan kendali Koordinator Misi Pencarian dan Pertolongan; dan 2) melaksanakan koordinasi, pengendalian dan pemantauan pergerakan unit pencarian dan pertolongan di daerah pencarian.', 'BAB III (lanjutan 8)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1027, 'juklak-6-2026', 21, 'lain', 'BAB III (lanjutan 9)', NULL, 11, 'e. Operasi pencarian, pertolongan, penyelamatan, dan evakuasi korban memperhatikan kondisi wilayah dan karakteristik kejadian bencana.
f. Pertolongan darurat bencana diprioritaskan pada warga masyarakat terkena bencana yang mengalami luka parah dan kelompok berisiko dengan akses dan inklusif.
g. Terhadap masyarakat terkena bencana yang meninggal dunia dilakukan upaya identifikasi dan pemakamannya.
h. Dalam upaya penyelamatan terdapat kemudahan akses yang dilakukan melalui pencarian, pertolongan, dan evakuasi korban bencana.
Untuk memudahkan penyelamatan korban bencana dan harta benda, dapat dilakukan tindakan sebagai berikut.
1) Menyingkirkan dan/atau memusnahkan barang atau benda di lokasi bencana yang dapat membahayakan jiwa.
2) Menyingkirkan dan/atau memusnahkan barang atau benda yang dapat mengganggu proses penyelamatan.
3) Memerintahkan orang untuk keluar dari suatu lokasi atau melarang orang untuk memasuki suatu lokasi.
4) Mengisolasi atau menutup suatu lokasi baik milik publik maupun pribadi; dan 5) Memerintahkan kepada pimpinan instansi/lembaga terkait untuk mematikan aliran listrik, gas, atau menutup/membuka pintu air.
i. Mobilisasi unit pencarian dan pertolongan dilaksanakan melalui:
1) pengoordinasian, pengarahan dan penugasan unit pencarian dan pertolongan;
2) penggerakan unit pencarian dan pertolongan menuju lokasi dan/atau daerah pencarian;
3) pelaksanaan pengamatan dan pemantauan;
4) pelaksanaan pencarian sesuai pola pencarian;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1027, 'e. Operasi pencarian, pertolongan, penyelamatan, dan evakuasi korban memperhatikan kondisi wilayah dan karakteristik kejadian bencana.
f. Pertolongan darurat bencana diprioritaskan pada warga masyarakat terkena bencana yang mengalami luka parah dan kelompok berisiko dengan akses dan inklusif.
g. Terhadap masyarakat terkena bencana yang meninggal dunia dilakukan upaya identifikasi dan pemakamannya.
h. Dalam upaya penyelamatan terdapat kemudahan akses yang dilakukan melalui pencarian, pertolongan, dan evakuasi korban bencana.
Untuk memudahkan penyelamatan korban bencana dan harta benda, dapat dilakukan tindakan sebagai berikut.
1) Menyingkirkan dan/atau memusnahkan barang atau benda di lokasi bencana yang dapat membahayakan jiwa.
2) Menyingkirkan dan/atau memusnahkan barang atau benda yang dapat mengganggu proses penyelamatan.
3) Memerintahkan orang untuk keluar dari suatu lokasi atau melarang orang untuk memasuki suatu lokasi.
4) Mengisolasi atau menutup suatu lokasi baik milik publik maupun pribadi; dan 5) Memerintahkan kepada pimpinan instansi/lembaga terkait untuk mematikan aliran listrik, gas, atau menutup/membuka pintu air.
i. Mobilisasi unit pencarian dan pertolongan dilaksanakan melalui:
1) pengoordinasian, pengarahan dan penugasan unit pencarian dan pertolongan;
2) penggerakan unit pencarian dan pertolongan menuju lokasi dan/atau daerah pencarian;
3) pelaksanaan pengamatan dan pemantauan;
4) pelaksanaan pencarian sesuai pola pencarian;', 'BAB III (lanjutan 9)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pencarian, Pertolongan, dan Evakuasi Korban Bencana Nomor 6 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1028, 'juklak-6-2026', 22, 'lain', 'BAB III (lanjutan 10)', NULL, 12, '5) pengoordinasian dan pengendalian unit pencarian dan pertolongan; dan 6) pelaporan perkembangan pelaksanaan pencarian.
j. Pelaksanaan pertolongan dilakukan terhadap korban dengan tahapan:
1) penilaian kondisi lingkungan;
2) penilaian kondisi korban;
3) penyiapan peralatan pertolongan;
4) pelaksanaan pertolongan dan penyelamatan korban; dan 5) apabila diperlukan, dilakukan pertolongan pertama medis terhadap korban di lokasi kejadian.
k. Pelaksanaan evakuasi korban dilaksanakan dalam bentuk:
1) penentuan metode evakuasi;
2) pemindahan korban ke lokasi yang lebih aman;
3) penyerahan korban ke tim medis untuk penanganan lebih lanjut;
4) penyerahan korban kepada instansi yang menangani identifikasi; dan 5) penyerahan korban kepada pihak keluarga atau pihak lain yang mewakili.
Penyerahan korban sebagaimana dimaksud angka 4) dan angka 5) dituangkan dalam berita acara serah terima korban.
Berita acara serah terima disusun oleh koordinator misi pencarian dan pertolongan.
l. Evaluasi dan penyesuaian Koordinator Misi Pencarian dan Pertolongan bersama semua pihak terkait mengadakan evaluasi rutin pelaksanaan operasi pencarian, pertolongan dan evakuasi dan mengadakan penyesuaian-penyesuaian yang perlu terhadap jalannya operasi.
3. Penghentian operasi pencarian, pertolongan dan evakuasi dilakukan apabila:
a. seluruh korban telah ditemukan, ditolong, dan dievakuasi.
b. setelah jangka 7 (tujuh) hari pelaksanaan operasi pencarian tidak ada tanda-tanda korban ditemukan; dan/atau');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1028, '5) pengoordinasian dan pengendalian unit pencarian dan pertolongan; dan 6) pelaporan perkembangan pelaksanaan pencarian.
