INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1032, 'Petunjuk Pelaksanaan Nomor 7 Tahun 2024 tentang Pelayanan Penyediaan Data Inarisk Web', 'Judul', 'Petunjuk Pelaksanaan Nomor 7 Tahun 2024 tentang Pelayanan Penyediaan Data Inarisk Web');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1033, 'juklak-7-2025', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1033, 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025', 'Judul', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1034, 'juklak-7-2025', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN STRUKTUR TIM PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA NOMOR 7 TAHUN 2025');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1034, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN STRUKTUR TIM PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA NOMOR 7 TAHUN 2025', 'Isi hal. 1', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1035, 'juklak-7-2025', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Berdasarkan ketentuan Pasal 8 Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana, Badan Nasional Penanggulangan Bencana bertanggung jawab atas pelaksanaan penelaahan, verifikasi, dan evaluasi terhadap permohonan yang disampaikan oleh pemohon sebelum dilakukan penganggaran dan pengalokasian serta penyaluran dana bersama penanggulangan bencana oleh Kementerian Keuangan.
Bahwa untuk menjamin permohonan penyaluran dana bersama penanggulangan bencana yang diajukan oleh kementerian/lembaga dan pemerintah daerah telah sesuai dan selaras dengan ketentuan peraturan perundang-undangan berikut instrumen turunannya yang mengatur mengenai pengelolaan dana bersama penanggulangan bencana, diperlukan adanya pelaksana yang bertugas menelaah dan memverifikasi serta mengevaluasi permohonan penyaluran dana bersama penanggulangan bencana berikut dokumen-dokumen persyaratannya.
Ketentuan Pasal 25 dan Pasal 26 Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana telah mengatur mengenai Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
Keberadaan dari tim ini menjadi penting dalam pelaksanaan penyaluran dana bersama penanggulangan bencana sebagaimana diatur dalam Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1035, 'PENDAHULUAN A. Latar Belakang Berdasarkan ketentuan Pasal 8 Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana, Badan Nasional Penanggulangan Bencana bertanggung jawab atas pelaksanaan penelaahan, verifikasi, dan evaluasi terhadap permohonan yang disampaikan oleh pemohon sebelum dilakukan penganggaran dan pengalokasian serta penyaluran dana bersama penanggulangan bencana oleh Kementerian Keuangan.
Bahwa untuk menjamin permohonan penyaluran dana bersama penanggulangan bencana yang diajukan oleh kementerian/lembaga dan pemerintah daerah telah sesuai dan selaras dengan ketentuan peraturan perundang-undangan berikut instrumen turunannya yang mengatur mengenai pengelolaan dana bersama penanggulangan bencana, diperlukan adanya pelaksana yang bertugas menelaah dan memverifikasi serta mengevaluasi permohonan penyaluran dana bersama penanggulangan bencana berikut dokumen-dokumen persyaratannya.
Ketentuan Pasal 25 dan Pasal 26 Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana telah mengatur mengenai Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
Keberadaan dari tim ini menjadi penting dalam pelaksanaan penyaluran dana bersama penanggulangan bencana sebagaimana diatur dalam Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana.', 'BAB I', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1036, 'juklak-7-2025', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Berdasarkan pertimbangan sebagaimana disebutkan di atas, perlu untuk membentuk Petunjuk Pelaksanaan yang mengatur mengenai struktur tim penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana.
B. Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini dimaksudkan sebagai panduan bagi:
a. Badan Nasional Penanggulangan Bencana dalam pengorganisasian tim penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana;
b. tim penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana dalam melaksanakan penelaahan, verifikasi, dan evaluasi terhadap permohonan penyaluran dana bersama penanggulangan bencana; dan
c. kementerian/lembaga pemberi pertimbangan dalam koordinasi pemberian pertimbangan penyaluran dana bersama penanggulangan bencana.
2. Tujuan Tujuan dari Petunjuk Pelaksanaan ini adalah tersedianya mekanisme:
a. pembentukan tim penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana; dan
b. pelaksanaan penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana oleh tim penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana.
C. Ruang Lingkup Ruang lingkup Petunjuk Pelaksanaan ini meliputi:
a. pelaksanaan penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana bagi tim penelaahan, verifikasi, dan evaluasi; dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1036, 'Berdasarkan pertimbangan sebagaimana disebutkan di atas, perlu untuk membentuk Petunjuk Pelaksanaan yang mengatur mengenai struktur tim penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana.
B. Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini dimaksudkan sebagai panduan bagi:
a. Badan Nasional Penanggulangan Bencana dalam pengorganisasian tim penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana;
b. tim penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana dalam melaksanakan penelaahan, verifikasi, dan evaluasi terhadap permohonan penyaluran dana bersama penanggulangan bencana; dan
c. kementerian/lembaga pemberi pertimbangan dalam koordinasi pemberian pertimbangan penyaluran dana bersama penanggulangan bencana.
2. Tujuan Tujuan dari Petunjuk Pelaksanaan ini adalah tersedianya mekanisme:
a. pembentukan tim penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana; dan
b. pelaksanaan penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana oleh tim penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana.
C. Ruang Lingkup Ruang lingkup Petunjuk Pelaksanaan ini meliputi:
a. pelaksanaan penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana bagi tim penelaahan, verifikasi, dan evaluasi; dan', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1037, 'juklak-7-2025', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, 'b. pelaksanaan koordinasi pemberian pertimbangan penyaluran dana bersama penanggulangan bencana bagi kementerian/lembaga pemberi pertimbangan.
D. Pengertian Dalam Petunjuk Pelaksanaan ini yang dimaksud dengan:
1. Dana Bersama Penanggulangan Bencana yang selanjutnya disebut Dana Bersama adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi dana penanggulangan bencana yang memadai dan berkelanjutan.
2. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara Pemerintahan Daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
3. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1037, 'b. pelaksanaan koordinasi pemberian pertimbangan penyaluran dana bersama penanggulangan bencana bagi kementerian/lembaga pemberi pertimbangan.
D. Pengertian Dalam Petunjuk Pelaksanaan ini yang dimaksud dengan:
1. Dana Bersama Penanggulangan Bencana yang selanjutnya disebut Dana Bersama adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi dana penanggulangan bencana yang memadai dan berkelanjutan.
2. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara Pemerintahan Daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
3. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1038, 'juklak-7-2025', 5, 'lain', 'BAB II', NULL, 3, 'PENGORGANISASIAN A. Struktur Organisasi Dalam rangka operasionalisasi kegiatan penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama, perlu disusun struktur organisasi Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana. Struktur tersebut terdiri atas:
1. penanggung jawab;
2. sekretariat;
3. tim penelaahan, verifikasi, dan evaluasi Deputi Bidang Sistem dan Strategi;
4. tim penelaahan, verifikasi, dan evaluasi Deputi Bidang Pencegahan;
5. tim penelaahan, verifikasi, dan evaluasi Deputi Bidang Rehabilitasi dan Rekonstruksi; dan
6. tim penelaahan, verifikasi, dan evaluasi Deputi Bidang Logistik dan Peralatan.
Susunan penanggung jawab berjumlah sesuai bidang kegiatan, yakni:
1. penanggung jawab bidang sistem dan strategi;
2. penanggung jawab bidang pencegahan;
3. penanggung jawab bidang logistik dan peralatan; dan
4. penanggung jawab bidang rehabilitasi dan rekonstruksi.
Susunan sekretariat, terdiri atas:
1. koordinator;
2. anggota bidang administrasi; dan
3. anggota bidang sistem informasi.
Susunan sekretariat berjumlah gasal, terdiri atas:
1. koordinator sekretariat; dan
2. anggota, dengan ketentuan:
a. paling sedikit 11 (sebelas) orang dalam bidang administrasi; dan
b. paling sedikit 3 (tiga) orang dalam bidang sistem informasi.
Susunan tim penelaahan, verifikasi, dan evaluasi Deputi berjumlah gasal, terdiri atas:
1. koordinator tim; dan');
