INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1066, 'juklak-7-2025', 33, 'lampiran', 'LAMPIRAN III', NULL, 20, 'PETUNJUK PELAKSANAAN STRUKTUR TIM PENELAAHAN, VERIFIKASI DAN EVALUASI DANA BERSAMA PENANGGULANGAN BENCANA NOMOR 7 TAHUN 2025 FORMAT KERTAS KERJA PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA Format 1 – Pengumuman Penerimaan Permohonan Penyaluran Dana Bersama Tahap Prabencana PENGUMUMAN NOMOR …………………………………………… TENTANG PENERIMAAN PERMOHONAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA Dalam rangka pelaksanaan ketentuan Pasal 8 ayat (1) huruf a Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana, melalui pengumuman ini, BNPB membuka penerimaan permohonan penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana, dengan ketentuan sebagai berikut.
1. Latar Belakang Dana Bersama Penanggulangan Bencana (selanjutnya disebut Dana Bersama) merupakan mekanisme pengelolaan dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi dana penanggulangan bencana yang memadai, tepat waktu, tepat sasaran, terencana, dan berkelanjutan dalam upaya penanggulangan bencana secara berdaya guna, berhasil guna, dan dapat dipertanggungjawabkan. Secara umum, operasionalisasi Dana Bersama mencakup pengumpulan dana (seperti APBN, APBD, dan sumber lainnya yang sah), pengembangan dana baik investasi jangka pendek maupun panjang, penyaluran dana, dan penugasan lain sesuai dengan arahan Menteri Keuangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1066, 'PETUNJUK PELAKSANAAN STRUKTUR TIM PENELAAHAN, VERIFIKASI DAN EVALUASI DANA BERSAMA PENANGGULANGAN BENCANA NOMOR 7 TAHUN 2025 FORMAT KERTAS KERJA PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA Format 1 – Pengumuman Penerimaan Permohonan Penyaluran Dana Bersama Tahap Prabencana PENGUMUMAN NOMOR …………………………………………… TENTANG PENERIMAAN PERMOHONAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA Dalam rangka pelaksanaan ketentuan Pasal 8 ayat (1) huruf a Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana, melalui pengumuman ini, BNPB membuka penerimaan permohonan penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana, dengan ketentuan sebagai berikut.
1. Latar Belakang Dana Bersama Penanggulangan Bencana (selanjutnya disebut Dana Bersama) merupakan mekanisme pengelolaan dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi dana penanggulangan bencana yang memadai, tepat waktu, tepat sasaran, terencana, dan berkelanjutan dalam upaya penanggulangan bencana secara berdaya guna, berhasil guna, dan dapat dipertanggungjawabkan. Secara umum, operasionalisasi Dana Bersama mencakup pengumpulan dana (seperti APBN, APBD, dan sumber lainnya yang sah), pengembangan dana baik investasi jangka pendek maupun panjang, penyaluran dana, dan penugasan lain sesuai dengan arahan Menteri Keuangan.', 'LAMPIRAN III', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1067, 'juklak-7-2025', 34, 'lampiran', 'LAMPIRAN III (lanjutan 1)', NULL, 20, 'Guna mewujudkan ketahanan fiskal atas ancaman bencana serta meningkatkan kesiapsiagaan dan penanganan bencana, Dana Bersama membuka peluang permohonan kegiatan penanggulangan bencana dari kementerian/lembaga, dan pemerintah daerah yang disampaikan kepada BNPB. Penggunaan Dana Bersama mempertimbangkan aspek pelindungan lingkungan dan sosial. Lebih lanjut, permohonan tersebut akan ditelaah, diverifikasi, dan dievaluasi oleh BNPB dengan pertimbangan Kementerian Perencanaan Pembangunan Nasional/Badan Perencanaan Pembangunan Nasional, Kementerian Keuangan, dan Kementerian Dalam Negeri. Hasil penelaahan, verifikasi, dan evaluasi serta pertimbangan tersebut dituangkan dalam bentuk rekomendasi Kepala BNPB yang disampaikan kepada Menteri Keuangan. Penyaluran Dana Bersama ini dapat diberikan kepada kementerian/lembaga, pemerintah daerah, kelompok masyarakat, dan penyedia barang/jasa melalui Badan Pengelola Dana Lingkungan Hidup atas perintah Menteri Keuangan.
2. Prioritas penyaluran adalah sebagai berikut.
a. kegiatan yang sesuai dengan Rencana Nasional Penanggulangan Bencana/Rencana Penanggulangan Bencana Daerah atau Rencana Kerja Pemerintah/Rencana Kerja Pemerintah Daerah;
b. kegiatan pada daerah dengan indeks risiko bencana tinggi;
c. kegiatan yang sesuai dengan standar pelayanan minimal suburusan bencana; dan/atau
d. prioritas kegiatan berdasarkan Keputusan Kepala BNPB Nomor … Tahun … tentang … pada tautan ….
3. Ruang lingkup kegiatan tahap prabencana yang dapat dimohonkan adalah:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1067, 'Guna mewujudkan ketahanan fiskal atas ancaman bencana serta meningkatkan kesiapsiagaan dan penanganan bencana, Dana Bersama membuka peluang permohonan kegiatan penanggulangan bencana dari kementerian/lembaga, dan pemerintah daerah yang disampaikan kepada BNPB. Penggunaan Dana Bersama mempertimbangkan aspek pelindungan lingkungan dan sosial. Lebih lanjut, permohonan tersebut akan ditelaah, diverifikasi, dan dievaluasi oleh BNPB dengan pertimbangan Kementerian Perencanaan Pembangunan Nasional/Badan Perencanaan Pembangunan Nasional, Kementerian Keuangan, dan Kementerian Dalam Negeri. Hasil penelaahan, verifikasi, dan evaluasi serta pertimbangan tersebut dituangkan dalam bentuk rekomendasi Kepala BNPB yang disampaikan kepada Menteri Keuangan. Penyaluran Dana Bersama ini dapat diberikan kepada kementerian/lembaga, pemerintah daerah, kelompok masyarakat, dan penyedia barang/jasa melalui Badan Pengelola Dana Lingkungan Hidup atas perintah Menteri Keuangan.
2. Prioritas penyaluran adalah sebagai berikut.
a. kegiatan yang sesuai dengan Rencana Nasional Penanggulangan Bencana/Rencana Penanggulangan Bencana Daerah atau Rencana Kerja Pemerintah/Rencana Kerja Pemerintah Daerah;
b. kegiatan pada daerah dengan indeks risiko bencana tinggi;
c. kegiatan yang sesuai dengan standar pelayanan minimal suburusan bencana; dan/atau
d. prioritas kegiatan berdasarkan Keputusan Kepala BNPB Nomor … Tahun … tentang … pada tautan ….
3. Ruang lingkup kegiatan tahap prabencana yang dapat dimohonkan adalah:', 'LAMPIRAN III (lanjutan 1)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1068, 'juklak-7-2025', 35, 'lampiran', 'LAMPIRAN III (lanjutan 2)', NULL, 21, 'a. Perencanaan dan penyusunan kebijakan;
b. Pencegahan;
c. Logistik dan peralatan; dan
d. Peningkatan kapasitas dan profesi.
Adapun rincian kegiatan dapat dilihat pada Lampiran I Petunjuk Pelaksanaan BNPB tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana.
4. Kriteria kelembagaan pengajuan permohonan sebagai berikut.
a. Kementerian/lembaga diajukan oleh paling rendah pejabat pimpinan tinggi madya.
b. Pemerintah Daerah diajukan oleh Kepala Daerah.
c. Permohonan dari Pemerintah Daerah yang diprakarsai oleh perangkat daerah selain BPBD wajib dikoordinasikan oleh BPBD sebagai koordinator penanggulangan bencana di daerah.
d. Pemerintah Daerah bertugas memfasilitasi pengajuan permohonan, jika terdapat prakarsa dari Kelompok Masyarakat.
5. Linimasa Pengajuan:
No Tahapan Waktu Ket 1 Penerimaan Permohonan 2 Penelaahan dan Verifikasi 3 Pemberian Pertimbangan 4 Penerbitan Rekomendasi Permohonan diterima paling lambat pada tanggal … pukul 23.59 WIB
6. Alur Pengajuan Alur pengajuan dapat dilihat pada tautan ….
7. Format Permohonan dan Lampiran Ketentuan penulisan menggunakan kertas A4 dengan font Arial ukuran 12.
Adapun format permohonan dan lampirannya dapat diunduh pada tautan ….');
