INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1072, 'juklak-7-2025', 39, 'lampiran', 'LAMPIRAN III (lanjutan 6)', NULL, 25, '3. ….................................... (Tanda tangan dan cap instansi) Nama Lengkap NIP. …...........
PETUNJUK PENGGUNAAN KERTAS KERJA
1. Isilah identitas permohonan dengan lengkap.
2. Cek seluruh kelengkapan dokumen permohonan.
3. Beri tanda centang (V) sesuai kolom "Ada"/"Tidak".
4. Untuk informasi tambahan, dapat dituliskan pada kolom keterangan.
5. Setelah semua kelengkapan dokumen dicentang, isi hasil prapenilaian.
6. Apabila ada dokumen tidak lengkap, tuliskan dokumen apa yang dimaksud.
7. Lengkapi kertas kerja dengan lokasi, waktu, tanda tangan, dan identitas anggota Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana yang melakukan prapenilaian.
Format 4 – Kertas Kerja Penilaian Permohonan Penyaluran Dana Bersama Tahap Prabencana KERTAS KERJA PENILAIAN PERMOHOHONAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA Nomor ……………………………………………..');
