INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1073, 'juklak-7-2025', 40, 'lampiran', 'LAMPIRAN III (lanjutan 7)', NULL, 26, 'No Identitas Keterangan 1 Nomor Registrasi …………………………………………………… Permohonan 2 Nama Kegiatan …………………………………………………… 3 Kode Klasifikasi Kegiatan …………………………………………………… 4 Instansi Pemohon …………………………………………………… 5 Nomor Surat Pengajuan …………………………………………………… Permohonan 6 Pelaksana Kegiatan …………………………………………………… Lokasi Kegiatan Provinsi …………………………………………………… Kabupaten/Kota …………………………………………………… Kecamatan …………………………………………………… Desa / Kelurahan …………………………………………………… Alamat …………………………………………………… Koordinat …………………………………………………… 7 Tahun Pelaksanaan …………………………………………………… 8 Nominal Pengajuan Anggaran Rp. ……………………………………………….
