INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1073, 'No Identitas Keterangan 1 Nomor Registrasi …………………………………………………… Permohonan 2 Nama Kegiatan …………………………………………………… 3 Kode Klasifikasi Kegiatan …………………………………………………… 4 Instansi Pemohon …………………………………………………… 5 Nomor Surat Pengajuan …………………………………………………… Permohonan 6 Pelaksana Kegiatan …………………………………………………… Lokasi Kegiatan Provinsi …………………………………………………… Kabupaten/Kota …………………………………………………… Kecamatan …………………………………………………… Desa / Kelurahan …………………………………………………… Alamat …………………………………………………… Koordinat …………………………………………………… 7 Tahun Pelaksanaan …………………………………………………… 8 Nominal Pengajuan Anggaran Rp. ……………………………………………….
