INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1074, 'juklak-7-2025', 41, 'lampiran', 'LAMPIRAN III (lanjutan 8)', NULL, 26, 'Ya Tidak DOKUMEN WAJIB 1 Surat Pengajuan Menggunakan kepala surat Permohonan instansi Terdapat tanggal surat Terdapat nomor surat Ditujukan kepada Kepala BNPB Nomor Pengumuman sesuai Bertanda tangan dan berstempel Untuk permohonan Kementerian/Lembaga, ditandatangani oleh paling rendah Pejabat Pimpinan Tinggi Madya Untuk permohonan Pemerintah Daerah, ditandatangani oleh Kepala Daerah Isi dan format sesuai ketentuan dalam Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana 2 Dokumen Terdapat sampul yang paling Permohonan tidak memuat: nama, lokasi, Kegiatan tahun kegiatan, logo dan nama instansi pemohon Terdapat kata pengantar Terdapat ringkasan eksekutif Terdapat daftar isi Terdapat lembar identitas pemohon sesuai format, yang bertandatangan dan berstempel Bab I Pendahuluan terdiri dari 4 (empat) subbab, yaitu:
a. Latar belakang
b. Maksud dan tujuan
c. Ruang lingkup
d. Keluaran Bab II Gambaran Umum terdiri dari 5 (lima) subbab, yaitu:
a. Pemohon K/L menyampaikan profil institusi
b. Pemohon Pemda menyampaikan profil daerah
c. Profil kebencanaan
d. Kondisi anggaran
e. Potensi SDM
f. Riwayat kerjasama lembaga/donor Bab III Usulan Kegiatan terdiri dari 7 (tujuh) subbab, yaitu:
a. Kegiatan eksisting dan kegiatan yang diusulkan
b. Metodologi
c. Kerangka kerja logis
d. Rencana kerja (timeline)
e. Pelaksana
f. Kerangka pemantauan dan evaluasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1074, 'Ya Tidak DOKUMEN WAJIB 1 Surat Pengajuan Menggunakan kepala surat Permohonan instansi Terdapat tanggal surat Terdapat nomor surat Ditujukan kepada Kepala BNPB Nomor Pengumuman sesuai Bertanda tangan dan berstempel Untuk permohonan Kementerian/Lembaga, ditandatangani oleh paling rendah Pejabat Pimpinan Tinggi Madya Untuk permohonan Pemerintah Daerah, ditandatangani oleh Kepala Daerah Isi dan format sesuai ketentuan dalam Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana 2 Dokumen Terdapat sampul yang paling Permohonan tidak memuat: nama, lokasi, Kegiatan tahun kegiatan, logo dan nama instansi pemohon Terdapat kata pengantar Terdapat ringkasan eksekutif Terdapat daftar isi Terdapat lembar identitas pemohon sesuai format, yang bertandatangan dan berstempel Bab I Pendahuluan terdiri dari 4 (empat) subbab, yaitu:
