INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1079, 'Format 5 – Kertas Kerja Verifikasi Permohonan Penyaluran Dana Bersama Tahap Prabencana KERTAS KERJA VERIFIKASI PERMOHOHONAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA Nomor ……………………………………………..
No Identitas Keterangan 1 Nomor Registrasi …………………………………………………… Permohonan 2 Nama Kegiatan …………………………………………………… 3 Kode Klasifikasi …………………………………………………… Kegiatan 4 Instansi Pemohon …………………………………………………… 5 Nomor Surat …………………………………………………… Pengajuan Permohonan 6 Pelaksana Kegiatan …………………………………………………… Lokasi Kegiatan Provinsi …………………………………………………… Kabupaten/Kota …………………………………………………… Kecamatan …………………………………………………… Desa / Kelurahan …………………………………………………… Alamat …………………………………………………… Koordinat …………………………………………………… 7 Tahun Pelaksanaan …………………………………………………… 8 Nominal Pengajuan Rp. ……………………………………………….', 'LAMPIRAN III (lanjutan 13)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1080, 'juklak-7-2025', 47, 'lampiran', 'LAMPIRAN III (lanjutan 14)', NULL, 31, 'Anggaran (…………………………………………………..) Risiko Lingkungan dan Sosial : Rendah/Menengah/Substansial/Tinggi)* SKORING BOBOT NILAI EVIDEN/ NO KRITERIA RANGE PENILAIAN KETERANGAN DASAR HUKUM 0 - 100 % Skoring x Ruang Lingkup Kegiatan Bobot Kesesuaian usulan kegiatan dengan Sangat Sesuai (85 - 100) 0,02 0 ruang lingkup kegiatan yang dapat Sesuai (70 - 84) dibiayai Dana Bersama Penanggulangan Cukup Sesuai (50 - 69) Bencana Tahap Prabencana Kurang Sesuai (<50) Usulan kegiatan memenuhi kriteria Sangat Sesuai (85 - 100) 0,02 0 berjenjang/sequencing (contoh: usulan Sesuai (70 - 84) RPB berarti harus sudah memiliki KRB Cukup Sesuai (50 - 69) 1 yang masih berlaku) Kurang Sesuai (<50) Usulan kegiatan adalah layanan Sangat Sesuai (85 - 100) 0,01 0 langsung dimana pengusul telah memiliki Sesuai (70 - 84) dokumen dasar Penanggulangan Cukup Sesuai (50 - 69) Bencana yang lengkap dan aktif (contoh: Kurang Sesuai (<50) usulan sosialisasi dimana KRB, RPB, dan Renkon sudah ada dan masih aktif) Prioritas Penyaluran Dana 2 Usulan kegiatan memenuhi kriteria Untuk permohonan K/L, usulan 0,034 0 prioritas penyaluran Dana Bersama PB sesuai dengan Rencana (pilih salah satu) Nasional Penanggulangan Bencana dan Rencana Kerja Sangat Sesuai (85 - 100) Pemerintah Sesuai (70 - 84) Untuk permohonan Pemda, 0 Cukup Sesuai (50 - 69) usulan sesuai dengan Rencana Kurang Sesuai (<50) Penanggulangan Bencana Daerah dan Rencana Kerja Pemerintah Daerah Usulan kegiatan dilaksanakan di 0,033 0 daerah dengan indeks risiko bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1080, 'Anggaran (…………………………………………………..) Risiko Lingkungan dan Sosial : Rendah/Menengah/Substansial/Tinggi)* SKORING BOBOT NILAI EVIDEN/ NO KRITERIA RANGE PENILAIAN KETERANGAN DASAR HUKUM 0 - 100 % Skoring x Ruang Lingkup Kegiatan Bobot Kesesuaian usulan kegiatan dengan Sangat Sesuai (85 - 100) 0,02 0 ruang lingkup kegiatan yang dapat Sesuai (70 - 84) dibiayai Dana Bersama Penanggulangan Cukup Sesuai (50 - 69) Bencana Tahap Prabencana Kurang Sesuai (<50) Usulan kegiatan memenuhi kriteria Sangat Sesuai (85 - 100) 0,02 0 berjenjang/sequencing (contoh: usulan Sesuai (70 - 84) RPB berarti harus sudah memiliki KRB Cukup Sesuai (50 - 69) 1 yang masih berlaku) Kurang Sesuai (<50) Usulan kegiatan adalah layanan Sangat Sesuai (85 - 100) 0,01 0 langsung dimana pengusul telah memiliki Sesuai (70 - 84) dokumen dasar Penanggulangan Cukup Sesuai (50 - 69) Bencana yang lengkap dan aktif (contoh: Kurang Sesuai (<50) usulan sosialisasi dimana KRB, RPB, dan Renkon sudah ada dan masih aktif) Prioritas Penyaluran Dana 2 Usulan kegiatan memenuhi kriteria Untuk permohonan K/L, usulan 0,034 0 prioritas penyaluran Dana Bersama PB sesuai dengan Rencana (pilih salah satu) Nasional Penanggulangan Bencana dan Rencana Kerja Sangat Sesuai (85 - 100) Pemerintah Sesuai (70 - 84) Untuk permohonan Pemda, 0 Cukup Sesuai (50 - 69) usulan sesuai dengan Rencana Kurang Sesuai (<50) Penanggulangan Bencana Daerah dan Rencana Kerja Pemerintah Daerah Usulan kegiatan dilaksanakan di 0,033 0 daerah dengan indeks risiko bencana', 'LAMPIRAN III (lanjutan 14)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1081, 'juklak-7-2025', 48, 'lampiran', 'LAMPIRAN III (lanjutan 15)', NULL, 31, 'tinggi Usulan kegiatan sesuai dengan 0,033 0 SPM Sub Urusan Bencana 3 Prioritas Kegiatan Penanggulangan Usulan kegiatan sesuai dengan 0,05 0 Bencana prioritas kegiatan dalam Keputusan Kepala BNPB PRINSIP - PRINSIP PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA 4 Pendekatan Berbasis Dampak: Sangat Baik (85 - 100) 0,05 0 permohonan mendeskripsikan dampak Baik (70 - 84) positif yang terukur dalam upaya Cukup (50 - 69) pengurangan risiko bencana dan Kurang (<50) peningkatan ketangguhan 5 Prakarsa yang Dipimpin oleh Sangat Baik (85 - 100) 0,047 0 Masyarakat: permohonan Baik (70 - 84) mendeskripsikan peran sentral Cukup (50 - 69) masyarakat lokal serta dapat Kurang (<50) meningkatkan kapasitas masyarakat dalam pengurangan risiko bencana 6 Relevansi Kontekstual dan Solusi Sangat Baik (85 - 100) 0,042 0 Lokal yang Adaptif: permohonan Baik (70 - 84) mendeskripsikan bagaimana usulan Cukup (50 - 69) kegiatan disesuaikan dengan kebutuhan, Kurang (<50) budaya, dan kondisi unik pada lokasi pelaksanaan kegiatan 7 Kepekaan terhadap Konflik: Sangat Baik (85 - 100) 0,04 0 permohonan mengidentifikasi potensi Baik (70 - 84) konflik dalam konteks lokal serta strategi Cukup (50 - 69) dalam menghadapinya Kurang (<50) 8 Keterbukaan Informasi: permohonan Sangat Baik (85 - 100) 0,045 0 mendeskripsikan strategi komunikasi Baik (70 - 84) untuk penyediaan informasi yang terbuka Cukup (50 - 69) dan mudah diakses bagi semua Kurang (<50) pemangku kepentingan 9 Akuntabilitas: permohonan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1081, 'tinggi Usulan kegiatan sesuai dengan 0,033 0 SPM Sub Urusan Bencana 3 Prioritas Kegiatan Penanggulangan Usulan kegiatan sesuai dengan 0,05 0 Bencana prioritas kegiatan dalam Keputusan Kepala BNPB PRINSIP - PRINSIP PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA 4 Pendekatan Berbasis Dampak: Sangat Baik (85 - 100) 0,05 0 permohonan mendeskripsikan dampak Baik (70 - 84) positif yang terukur dalam upaya Cukup (50 - 69) pengurangan risiko bencana dan Kurang (<50) peningkatan ketangguhan 5 Prakarsa yang Dipimpin oleh Sangat Baik (85 - 100) 0,047 0 Masyarakat: permohonan Baik (70 - 84) mendeskripsikan peran sentral Cukup (50 - 69) masyarakat lokal serta dapat Kurang (<50) meningkatkan kapasitas masyarakat dalam pengurangan risiko bencana 6 Relevansi Kontekstual dan Solusi Sangat Baik (85 - 100) 0,042 0 Lokal yang Adaptif: permohonan Baik (70 - 84) mendeskripsikan bagaimana usulan Cukup (50 - 69) kegiatan disesuaikan dengan kebutuhan, Kurang (<50) budaya, dan kondisi unik pada lokasi pelaksanaan kegiatan 7 Kepekaan terhadap Konflik: Sangat Baik (85 - 100) 0,04 0 permohonan mengidentifikasi potensi Baik (70 - 84) konflik dalam konteks lokal serta strategi Cukup (50 - 69) dalam menghadapinya Kurang (<50) 8 Keterbukaan Informasi: permohonan Sangat Baik (85 - 100) 0,045 0 mendeskripsikan strategi komunikasi Baik (70 - 84) untuk penyediaan informasi yang terbuka Cukup (50 - 69) dan mudah diakses bagi semua Kurang (<50) pemangku kepentingan 9 Akuntabilitas: permohonan', 'LAMPIRAN III (lanjutan 15)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1082, 'juklak-7-2025', 49, 'lampiran', 'LAMPIRAN III (lanjutan 16)', NULL, 31, 'Sangat Baik (85 - 100) 0,037 0 mengidentifikasi langkah-langkah Baik (70 - 84) menjaga akuntabilitas usulan kegiatan Cukup (50 - 69) serta rencana penyampaian laporan Kurang (<50) secara berkala 10 Keberlanjutan: permohonan Sangat Baik (85 - 100) 0,045 0 mengidentifikasi langkah-langkah untuk Baik (70 - 84) mempertahankan dan mengembangkan Cukup (50 - 69) usulan kegiatan dari waktu ke waktu Kurang (<50) 11 Inklusivitas: permohonan menjamin Sangat Baik (85 - 100) 0,044 0 akses setara dan partisipasi bermakna, Baik (70 - 84) khususnya bagi perempuan, penyandang Cukup (50 - 69) disabilitas, anak, lansia, dan kelompok Kurang (<50) rentan, serta mencakup pencegahan diskriminasi dan kekerasan berbasis gender.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1082, 'Sangat Baik (85 - 100) 0,037 0 mengidentifikasi langkah-langkah Baik (70 - 84) menjaga akuntabilitas usulan kegiatan Cukup (50 - 69) serta rencana penyampaian laporan Kurang (<50) secara berkala 10 Keberlanjutan: permohonan Sangat Baik (85 - 100) 0,045 0 mengidentifikasi langkah-langkah untuk Baik (70 - 84) mempertahankan dan mengembangkan Cukup (50 - 69) usulan kegiatan dari waktu ke waktu Kurang (<50) 11 Inklusivitas: permohonan menjamin Sangat Baik (85 - 100) 0,044 0 akses setara dan partisipasi bermakna, Baik (70 - 84) khususnya bagi perempuan, penyandang Cukup (50 - 69) disabilitas, anak, lansia, dan kelompok Kurang (<50) rentan, serta mencakup pencegahan diskriminasi dan kekerasan berbasis gender.', 'LAMPIRAN III (lanjutan 16)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1083, 'juklak-7-2025', 50, 'lampiran', 'LAMPIRAN III (lanjutan 17)', NULL, 34, 'Pendekatan Strategis Penyaluran Dana Bersama 12 Kemitraan dan Kolaborasi: Sangat Baik (85 - 100) 0,1 0 permohonan mendeskripsikan langkah- Baik (70 - 84) langkah kolaborasi dengan pemangku Cukup (50 - 69) kepentingan lain dalam usulan kegiatan Kurang (<50) 13 Pengembangan Kapasitas: Sangat Baik (85 - 100) 0,08 0 permohonan mendeskripsikan rencana Baik (70 - 84) pengembangan kapasitas pemangku Cukup (50 - 69) kepentingan di bidang pengurangan Kurang (<50) risiko bencana dalam usulan kegiatan 14 Inovasi: permohonan mendeskripsikan Sangat Baik (85 - 100) 0,05 0 adanya inovasi dan adopsi pendekatan Baik (70 - 84) baru di bidang pengurangan risiko Cukup (50 - 69) bencana dalam usulan kegiatan Kurang (<50) 15 Adaptasi: permohonan mendeskripsikan Sangat Baik (85 - 100) 0,07 0 kemampuan beradaptasi yang Baik (70 - 84) memungkinkan penyesuaian Cukup (50 - 69) berdasarkan kondisi dan pengalaman Kurang (<50) lokal untuk meningkatkan efektivitas usulan kegiatan Kelayakan Teknis Rencana Anggaran Biaya (RAB) Kesesuaian RAB dengan ketentuan Sangat Sesuai (85 - 100) 0,025 0 dalam Juklak SBKK Sesuai (70 - 84) Cukup Sesuai (50 - 69) Kurang Sesuai (<50) 16 Kesesuaian seluruh operasi perhitungan Sangat Sesuai (85 - 100) 0,025 0 dalam RAB berdasarkan koreksi Sesuai (70 - 84) aritmetik Cukup Sesuai (50 - 69) Kurang Sesuai (<50) Dokumen Pengelolaan Lingkungan dan Sosial 17 Usulan kegiatan tidak masuk dalam Sangat Sesuai (85 - 100) 0,025 0 Daftar Negatif Sesuai (70 - 84) Cukup Sesuai (50 - 69)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1083, 'Pendekatan Strategis Penyaluran Dana Bersama 12 Kemitraan dan Kolaborasi: Sangat Baik (85 - 100) 0,1 0 permohonan mendeskripsikan langkah- Baik (70 - 84) langkah kolaborasi dengan pemangku Cukup (50 - 69) kepentingan lain dalam usulan kegiatan Kurang (<50) 13 Pengembangan Kapasitas: Sangat Baik (85 - 100) 0,08 0 permohonan mendeskripsikan rencana Baik (70 - 84) pengembangan kapasitas pemangku Cukup (50 - 69) kepentingan di bidang pengurangan Kurang (<50) risiko bencana dalam usulan kegiatan 14 Inovasi: permohonan mendeskripsikan Sangat Baik (85 - 100) 0,05 0 adanya inovasi dan adopsi pendekatan Baik (70 - 84) baru di bidang pengurangan risiko Cukup (50 - 69) bencana dalam usulan kegiatan Kurang (<50) 15 Adaptasi: permohonan mendeskripsikan Sangat Baik (85 - 100) 0,07 0 kemampuan beradaptasi yang Baik (70 - 84) memungkinkan penyesuaian Cukup (50 - 69) berdasarkan kondisi dan pengalaman Kurang (<50) lokal untuk meningkatkan efektivitas usulan kegiatan Kelayakan Teknis Rencana Anggaran Biaya (RAB) Kesesuaian RAB dengan ketentuan Sangat Sesuai (85 - 100) 0,025 0 dalam Juklak SBKK Sesuai (70 - 84) Cukup Sesuai (50 - 69) Kurang Sesuai (<50) 16 Kesesuaian seluruh operasi perhitungan Sangat Sesuai (85 - 100) 0,025 0 dalam RAB berdasarkan koreksi Sesuai (70 - 84) aritmetik Cukup Sesuai (50 - 69) Kurang Sesuai (<50) Dokumen Pengelolaan Lingkungan dan Sosial 17 Usulan kegiatan tidak masuk dalam Sangat Sesuai (85 - 100) 0,025 0 Daftar Negatif Sesuai (70 - 84) Cukup Sesuai (50 - 69)', 'LAMPIRAN III (lanjutan 17)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1084, 'juklak-7-2025', 51, 'lampiran', 'LAMPIRAN III (lanjutan 18)', NULL, 34, 'Kurang Sesuai (<50) 18 Kesesuaian risiko usulan kegiatan hasil Sangat Sesuai (85 - 100) 0,025 0 penilaian mandiri Pemohon dengan Sesuai (70 - 84) verifikasi Tim Cukup Sesuai (50 - 69) Kurang Sesuai (<50) 19 Kesesuaian standar lingkungan dan Sangat Sesuai (85 - 100) 0,025 0 Sosial (SLS) yang terpicu dengan Sesuai (70 - 84) strategi/instrumen mitigasinya Cukup Sesuai (50 - 69) Kurang Sesuai (<50) 20 Rencana komitmen lingkungan dan Sangat Baik (85 - 100) 0,025 0 sosial mendeskripsikan rencana Baik (70 - 84) pelaporan; pemantauan; strategi mitigasi Cukup (50 - 69) SLS yang terpicu; dan peningkatan Kurang (<50) kapasitas terhadap pemangku kepentingan NILAI AKHIR VERIFIKASI 0 DOKUMEN TINDAK LANJUT Dibuat di …......
Perlu konsultasi dengan K/L teknis, sebutkan: …………….. Pada tanggal …........
Perlu verifikasi lapangan hanya untuk kegiatan dengan risiko lingkungan dan sosial menengah ke atas) Lolos verifikasi dokumen, dengan nilai Anggota Tim, …. ttd + cap instansi )* : pilih salah satu Nama Lengkap NIP. ….....................
PETUNJUK PENGGUNAAN KERTAS KERJA
1. Isi nomor kertas kerja verifikasi sesuai ketentuan penomeran Sekretariat Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
2. Isilah identitas permohonan dengan lengkap.
3. Isilah klasifikasi risiko lingkungan dan sosial permohonan sesuai dokumen lingkungan dan sosial.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1084, 'Kurang Sesuai (<50) 18 Kesesuaian risiko usulan kegiatan hasil Sangat Sesuai (85 - 100) 0,025 0 penilaian mandiri Pemohon dengan Sesuai (70 - 84) verifikasi Tim Cukup Sesuai (50 - 69) Kurang Sesuai (<50) 19 Kesesuaian standar lingkungan dan Sangat Sesuai (85 - 100) 0,025 0 Sosial (SLS) yang terpicu dengan Sesuai (70 - 84) strategi/instrumen mitigasinya Cukup Sesuai (50 - 69) Kurang Sesuai (<50) 20 Rencana komitmen lingkungan dan Sangat Baik (85 - 100) 0,025 0 sosial mendeskripsikan rencana Baik (70 - 84) pelaporan; pemantauan; strategi mitigasi Cukup (50 - 69) SLS yang terpicu; dan peningkatan Kurang (<50) kapasitas terhadap pemangku kepentingan NILAI AKHIR VERIFIKASI 0 DOKUMEN TINDAK LANJUT Dibuat di …......
Perlu konsultasi dengan K/L teknis, sebutkan: …………….. Pada tanggal …........
Perlu verifikasi lapangan hanya untuk kegiatan dengan risiko lingkungan dan sosial menengah ke atas) Lolos verifikasi dokumen, dengan nilai Anggota Tim, …. ttd + cap instansi )* : pilih salah satu Nama Lengkap NIP. ….....................
PETUNJUK PENGGUNAAN KERTAS KERJA
1. Isi nomor kertas kerja verifikasi sesuai ketentuan penomeran Sekretariat Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
2. Isilah identitas permohonan dengan lengkap.
3. Isilah klasifikasi risiko lingkungan dan sosial permohonan sesuai dokumen lingkungan dan sosial.', 'LAMPIRAN III (lanjutan 18)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1085, 'juklak-7-2025', 52, 'lampiran', 'LAMPIRAN III (lanjutan 19)', NULL, 37, '4. Kolom Skoring diisi dengan kesesuaian narasi permohonan dengan kriteria verifikasi, berdasarkan eviden/dasar hukum dan hasil analisis Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
5. Kolom eviden/dasar hukum, diisi dengan kutipan dalam permohonan yang menjadi dasar hasil skoring.
6. Kolom keterangan diisi informasi tambahan atau justifikasi penilaian Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
7. Apabila semua kriteria sudah terisi, nilai akan terhitung secara otomatis.
8. Isi kolom tindak lanjut sesuai hasil verifikasi.
9. Untuk pertanyaan yang tidak dapat dijawab, beri nilai median 50. Contoh: kriteria prakarsa yang dipimpin oleh masyarakat tidak sesuai untuk penyusunan Peraturan Pemerintah.
10. Isilah lokasi, tanggal, tanda tangan, dan identitas Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana yang melakukan verifikasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1085, '4. Kolom Skoring diisi dengan kesesuaian narasi permohonan dengan kriteria verifikasi, berdasarkan eviden/dasar hukum dan hasil analisis Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
5. Kolom eviden/dasar hukum, diisi dengan kutipan dalam permohonan yang menjadi dasar hasil skoring.
6. Kolom keterangan diisi informasi tambahan atau justifikasi penilaian Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
7. Apabila semua kriteria sudah terisi, nilai akan terhitung secara otomatis.
8. Isi kolom tindak lanjut sesuai hasil verifikasi.
9. Untuk pertanyaan yang tidak dapat dijawab, beri nilai median 50. Contoh: kriteria prakarsa yang dipimpin oleh masyarakat tidak sesuai untuk penyusunan Peraturan Pemerintah.
10. Isilah lokasi, tanggal, tanda tangan, dan identitas Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana yang melakukan verifikasi.', 'LAMPIRAN III (lanjutan 19)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
