INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1088, 'juklak-7-2025', 55, 'lampiran', 'LAMPIRAN III (lanjutan 22)', NULL, 39, '3 Kesesuaian luas Merujuk pada wilayah lokasi Formulir kegiatan Pelindungan Lingkungan dan Luas: ……….. m2 Sosial 4 Kesesuaian koordinat Merujuk pada realtime lokasi Formulir kegiatan Pelindungan Lingkungan dan Koordinat: ………… Sosial KEPEMILIKAN LAHAN 5 Kesesuaian pemilik Merujuk pada lahan lokasi kegiatan Formulir Pelindungan Pemilik: Lingkungan dan ……………….. Sosial 6 Kesesuaian bukti Periksa dokumen kepemilikan lahan fisik bukti kepemilikan lahan, sesuai Permohonan 7 Kesesuaian tutupan Merujuk pada lahan di lokasi Formulir kegiatan Pelindungan Lingkungan dan Sosial 8 Kesesuaian aktivitas Merujuk pada di sekitar lokasi Formulir kegiatan Pelindungan Lingkungan dan Sosial WAWANCARA DENGAN MASYARAKAT TERDAMPAK Identitas Responden Nama : ……………………………………………… Alamat : ……………………………………………… No. Telpon : ……………………………………………… NO PERTANYAAN JAWABAN 1 Bagaimana respons masyarakat sekitar terhadap rencana pelaksanaan usulan kegiatan? 2 Apakah terdapat masyarakat hukum adat di sekitar lokasi usulan kegiatan yang perlu dilibatkan? 3 Apakah terdapat warisan budaya benda dan tak benda di sekitar lokasi usulan kegiatan? 4 Apakah harapan Bapak/Ibu terhadap rencana pelaksanaan usulan kegiatan? 5 Pertanyaan lain, apabila diperlukan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1088, '3 Kesesuaian luas Merujuk pada wilayah lokasi Formulir kegiatan Pelindungan Lingkungan dan Luas: ……….. m2 Sosial 4 Kesesuaian koordinat Merujuk pada realtime lokasi Formulir kegiatan Pelindungan Lingkungan dan Koordinat: ………… Sosial KEPEMILIKAN LAHAN 5 Kesesuaian pemilik Merujuk pada lahan lokasi kegiatan Formulir Pelindungan Pemilik: Lingkungan dan ……………….. Sosial 6 Kesesuaian bukti Periksa dokumen kepemilikan lahan fisik bukti kepemilikan lahan, sesuai Permohonan 7 Kesesuaian tutupan Merujuk pada lahan di lokasi Formulir kegiatan Pelindungan Lingkungan dan Sosial 8 Kesesuaian aktivitas Merujuk pada di sekitar lokasi Formulir kegiatan Pelindungan Lingkungan dan Sosial WAWANCARA DENGAN MASYARAKAT TERDAMPAK Identitas Responden Nama : ……………………………………………… Alamat : ……………………………………………… No. Telpon : ……………………………………………… NO PERTANYAAN JAWABAN 1 Bagaimana respons masyarakat sekitar terhadap rencana pelaksanaan usulan kegiatan? 2 Apakah terdapat masyarakat hukum adat di sekitar lokasi usulan kegiatan yang perlu dilibatkan? 3 Apakah terdapat warisan budaya benda dan tak benda di sekitar lokasi usulan kegiatan? 4 Apakah harapan Bapak/Ibu terhadap rencana pelaksanaan usulan kegiatan? 5 Pertanyaan lain, apabila diperlukan', 'LAMPIRAN III (lanjutan 22)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1089, 'juklak-7-2025', 56, 'lampiran', 'LAMPIRAN', NULL, 41, '1. Dokumentasi Verifikasi Lapangan disertai geotagging (koordinat lokasi)
2. Dokumen Lain yang diperlukan Dibuat di ………..
Pada tanggal ………..
No Nama Lengkap Jabatan dalam Tim PVE Tanda Tangan 1 2 3 dst PETUNJUK PENGGUNAAN KERTAS KERJA
1. Isi nomor kertas kerja sesuai ketentuan penomoran Sekretariat Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana.
2. Isilah identitas permohonan dengan lengkap.
3. Beri centang (V) pada kolom “Ya”/”Tidak” untuk setiap kriteria.
4. Kolom catatan diisi dengan keterangan tambahan yang didapat di lapangan.
5. Untuk memperkaya informasi di lapangan, lakukan wawancara dengan minimal 1 (satu) orang di lokasi kegiatan. Responden dapat berasal dari tokoh masyarakat/warga yang akan terdampak usulan kegiatan/warga sekitar lokasi kegiatan.
6. Kolom jawaban diisi dengan hasil wawancara kepada responden.
7. Tambahkan lampiran yang diperlukan untuk melengkapi kertas kerja, apabila ada.
8. Lengkapi kertas kerja dengan lokasi, waktu, tanda tangan, dan identitas anggota Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana yang melakukan verifikasi lapangan.');
