INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1090, 'Format 8 – Laporan Verifikasi Lapangan Permohonan Penyaluran Dana Bersama Tahap Prabencana LAPORAN VERIFIKASI LAPANGAN PERMOHONAN PENYALURAN DANA BERSAMA PB TAHAP PRABENCANA Nomor ………………………………………………… No Identitas Keterangan 1 Nomor Registrasi …………………………………………………… Permohonan 2 Nama Kegiatan …………………………………………………… 3 Instansi Pemohon …………………………………………………… 4 Nomor Surat Pengajuan …………………………………………………… Permohonan 5 Pelaksana Kegiatan …………………………………………………… 6 Lokasi Kegiatan Provinsi …………………………………………………… Kabupaten/Kota …………………………………………………… Kecamatan …………………………………………………… Desa / Kelurahan …………………………………………………… Alamat …………………………………………………… Koordinat …………………………………………………… 7 Tahun Pelaksanaan …………………………………………………… 8 Nominal Pengajuan Anggaran Rp. ……………………………………………….
