INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1091, 'juklak-7-2025', 58, 'lampiran', 'LAMPIRAN (lanjutan 2)', NULL, 42, 'No Nama Lengkap Jabatan dalam Tim PVE Tanda Tangan 1 2 3 dst Format 9 – Surat Pemberitahuan Masa Pelaksanaan Verifikasi atas Penerimaan Permohonan Dana Bersama Tahap Prabencana Nomor : ..................... tanggal, bulan, tahun Sifat : Segera Lampiran : ….. (….) halaman/set Hal : Surat Pemberitahuan Masa Pelaksanaan Verifikasi atas Penerimaan Permohonan Periode ………………………………… Yth. 1. Direktur Jenderal Anggaran, Kementerian Keuangan
2. Direktur Jenderal Perimbangan Keuangan, Kementerian Keuangan
3. Direktur Jenderal Bina Administrasi Kewilayahan, Kementerian Dalam Negeri
4. Deputi Bidang Pembangunan Kewilayahan, Kementerian PPN/Bappenas di – Tempat Dengan hormat, Sehubungan dengan telah berakhirnya masa penerimaan Permohonan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana periode ……………………………, Tim Penelaahan, Verifikasi, dan Evaluasi Dana Bersama Penanggulangan Bencana Tahap Prabencana menyatakan bahwa permohonan sebagaimana dimaksud telah selesai dilakukan penelaahan dan verifikasi, dengan risalah sebagaimana terlampir.
Sesuai dengan ketentuan Pasal 17 ayat (1) Peraturan BNPB Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Dana Bersama Penanggulangan Bencana, maka kementerian/lembaga pemberi pertimbangan dapat menyampaikan risalah pertimbangan sejak penelaahan dilakukan hingga maksimal 10 (sepuluh) hari kerja sejak risalah hasil penelaahan dan verifikasi keluar.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1091, 'No Nama Lengkap Jabatan dalam Tim PVE Tanda Tangan 1 2 3 dst Format 9 – Surat Pemberitahuan Masa Pelaksanaan Verifikasi atas Penerimaan Permohonan Dana Bersama Tahap Prabencana Nomor : ..................... tanggal, bulan, tahun Sifat : Segera Lampiran : ….. (….) halaman/set Hal : Surat Pemberitahuan Masa Pelaksanaan Verifikasi atas Penerimaan Permohonan Periode ………………………………… Yth. 1. Direktur Jenderal Anggaran, Kementerian Keuangan
2. Direktur Jenderal Perimbangan Keuangan, Kementerian Keuangan
3. Direktur Jenderal Bina Administrasi Kewilayahan, Kementerian Dalam Negeri
4. Deputi Bidang Pembangunan Kewilayahan, Kementerian PPN/Bappenas di – Tempat Dengan hormat, Sehubungan dengan telah berakhirnya masa penerimaan Permohonan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana periode ……………………………, Tim Penelaahan, Verifikasi, dan Evaluasi Dana Bersama Penanggulangan Bencana Tahap Prabencana menyatakan bahwa permohonan sebagaimana dimaksud telah selesai dilakukan penelaahan dan verifikasi, dengan risalah sebagaimana terlampir.
Sesuai dengan ketentuan Pasal 17 ayat (1) Peraturan BNPB Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Dana Bersama Penanggulangan Bencana, maka kementerian/lembaga pemberi pertimbangan dapat menyampaikan risalah pertimbangan sejak penelaahan dilakukan hingga maksimal 10 (sepuluh) hari kerja sejak risalah hasil penelaahan dan verifikasi keluar.', 'LAMPIRAN (lanjutan 2)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1092, 'juklak-7-2025', 59, 'lampiran', 'LAMPIRAN (lanjutan 3)', NULL, 43, 'Berkenaan dengan hal tersebut, kami mohon bagi kementerian/lembaga pemberi pertimbangan agar dapat menyampaikan risalah sebagaimana dimaksud. Untuk informasi lebih lanjut dapat mengakses Sistem Informasi Dana Bersama Penanggulangan Bencana atau menghubungi Sekretariat Tim Penelaahan, Verifikasi dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana pada alamat surat elektronik …………..
Demikian kami sampaikan, atas perhatian dan kerja samanya kami ucapkan terima kasih.
