INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1095, 'juklak-7-2025', 62, 'lampiran', 'LAMPIRAN (lanjutan 6)', NULL, 46, 'Sebagai tindak lanjut, sesuai dengan Petunjuk Pelaksanaan BNPB Nomor 4 Tahun 2025 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Prabencana, Pemohon diwajibkan untuk mengirimkan dokumen Permohonan secara fisik berikut dokumen persyaratan administrasinya. Apabila dokumen tersebut tidak disampaikan dalam jangka waktu 10 (sepuluh) hari sejak menerima surat ini, Permohonan tidak akan direkomendasikan untuk menerima penyaluran dana. Untuk informasi lebih lanjut dapat mengakses Sistem Informasi Dana Bersama Penanggulangan Bencana ……. atau menghubungi Sekretariat Tim Penelaahan, Verifikasi dan Evaluasi Dana Bersama Penanggulangan Bencana pada alamat surat elektronik ………...
Demikian kami sampaikan, atas perhatian dan kerja samanya kami ucapkan terima kasih.
Penanggung Jawab Tim Penelaahan, Verifikasi, dan Evaluasi Deputi …, (ttd + cap instansi/tte) …………………………… Tembusan:
Kepala BNPB (sebagai laporan) Format 12 – Tanda Terima Dokumen Fisik Permohonan Penyaluran Dana Bersama Tahap Prabencana TANDA TERIMA DOKUMEN FISIK PERMOHONAN PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA TAHAP PRABENCANA Nomor ………………………………………………… Nomor Registrasi Permohonan …………………………………………………..
