INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1100, 'juklak-7-2025', 67, 'lampiran', 'LAMPIRAN IV (lanjutan 1)', NULL, 51, 'Provinsi ……………………..………………………… Kabupaten/Kota ……………………..………………………… Kecamatan ……………………..………………………… 5 Kelurahan/Desa ……………………..………………………… 6 Tahun Penelaahan ……………………..………………………… 7 Nominal Pengajuan Anggaran Rp. ……………………..…………………… (terbilang dalam huruf) Dokumen Hasil No Penjelasan Umum Rincian Ada Tidak Surat permohonan ditandatangani oleh Pejabat Pimpinan Tinggi Madya bagi kementerian/lembaga dan Surat gubernur/bupati/walikota Dokumen permohonan bagi pemerintah daerah 1 Permohonan Penyaluran sesuai kewenangannya Dana Bersama permohonan dari Kelompok Masyarakat difasilitasi oleh Pemerintah Daerah Surat pernyataan bencana Surat Keputusan Dokumen bermeterai Rp.10.000,- atau 2 Tanggap Darurat Umum keputusan tanggap darurat atau Surat yang ditandatangani oleh Pernyataan gubernur/bupati/walikota Bencana sesuai kewenangannya Wajib memuat jenis bencana, waktu kejadian bencana, lokasi kejadian bencana (desa dan/atau kecamatan) Untuk permohonan kementerian/lembaga dan Pemerintah Provinsi harus dilengkapi dengan surat pernyataan bencana bupati/walikota bermeterai Rp10.000,- atau keputusan tanggap darurat dari provinsi/kabupaten/kota terdampak Rekapitulasi permohonan kegiatan rehabilitasi dan rekonstruksi pascabencana memuat nama kegiatan, lokasi, volume, satuan, Rekapitulasi harga satuan, dan total permohonan anggaran yang kegiatan ditandatangani oleh Pejabat Pimpinan Tinggi Pratama pada kementerian/lembaga atau Kepala Pelaksana BPBD Ditandatangani oleh Pejabat Pimpinan Tinggi Madya bagi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1100, 'Provinsi ……………………..………………………… Kabupaten/Kota ……………………..………………………… Kecamatan ……………………..………………………… 5 Kelurahan/Desa ……………………..………………………… 6 Tahun Penelaahan ……………………..………………………… 7 Nominal Pengajuan Anggaran Rp. ……………………..…………………… (terbilang dalam huruf) Dokumen Hasil No Penjelasan Umum Rincian Ada Tidak Surat permohonan ditandatangani oleh Pejabat Pimpinan Tinggi Madya bagi kementerian/lembaga dan Surat gubernur/bupati/walikota Dokumen permohonan bagi pemerintah daerah 1 Permohonan Penyaluran sesuai kewenangannya Dana Bersama permohonan dari Kelompok Masyarakat difasilitasi oleh Pemerintah Daerah Surat pernyataan bencana Surat Keputusan Dokumen bermeterai Rp.10.000,- atau 2 Tanggap Darurat Umum keputusan tanggap darurat atau Surat yang ditandatangani oleh Pernyataan gubernur/bupati/walikota Bencana sesuai kewenangannya Wajib memuat jenis bencana, waktu kejadian bencana, lokasi kejadian bencana (desa dan/atau kecamatan) Untuk permohonan kementerian/lembaga dan Pemerintah Provinsi harus dilengkapi dengan surat pernyataan bencana bupati/walikota bermeterai Rp10.000,- atau keputusan tanggap darurat dari provinsi/kabupaten/kota terdampak Rekapitulasi permohonan kegiatan rehabilitasi dan rekonstruksi pascabencana memuat nama kegiatan, lokasi, volume, satuan, Rekapitulasi harga satuan, dan total permohonan anggaran yang kegiatan ditandatangani oleh Pejabat Pimpinan Tinggi Pratama pada kementerian/lembaga atau Kepala Pelaksana BPBD Ditandatangani oleh Pejabat Pimpinan Tinggi Madya bagi', 'LAMPIRAN IV (lanjutan 1)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1101, 'juklak-7-2025', 68, 'lampiran', 'LAMPIRAN IV (lanjutan 2)', NULL, 51, 'kementerian/lembaga dan gubernur/bupati/walikota bagi pemerintah daerah sesuai kewenangannya bermeterai Rp10.000.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1101, 'kementerian/lembaga dan gubernur/bupati/walikota bagi pemerintah daerah sesuai kewenangannya bermeterai Rp10.000.', 'LAMPIRAN IV (lanjutan 2)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1102, 'juklak-7-2025', 69, 'lampiran', 'LAMPIRAN IV (lanjutan 3)', NULL, 52, 'Dokumen ini didukung dengan lampiran daftar permohonan kegiatan, nilai permohonan, kewenangan, dan keterangan Surat Untuk kewenangan milik Pernyataan pemerintah berisi data aset Kewenangan (nomor registrasi, kode barang, nama barang, dan kewenangan) Untuk kegiatan bantuan/stimulan perumahan, sosial, ekonomi, dan sumber daya alam diisi dengan kewenangan masyarakat Untuk kegiatan berupa nonkonstruksi seperti pendampingan, bimbingan teknis, dan lain sebagainya diisi dengan kewenangan kementerian/lembaga atau Pemerintah Daerah Narasi permohonan sesuai sistematika penulisan permohonan penyaluran Narasi dana bersama permohonan penanggulangan bencana tahap pascabencana dan juga substansi yang memperkuat permohonan Dokumen Acuan permohonan untuk Rencana semua jenis bencana Rehabilitasi dan menggunakan dokumen Rekonstruksi Rencana Rehabilitasi dan Pascabencana Rekonstruksi Pascabencana Reviu Aparat Berisi hasil reviu terhadap Pengawas perencanaan kegiatan dari Instansi Aparat Pengawas Instansi Pemerintah oleh Pemerintah instansi Inspektorat pemohon Surat Pernyataan Pelindungan Lingkungan dan Sosial Mengacu pada Petunjuk Formulir Dokumen Pelaksanaan yang mengatur Pelindungan Pengelolaan mengenai sistem 3 Lingkungan dan Lingkungan pengelolaan lingkungan dan Sosial dan Sosial sosial pada dana bersama Rancangan Awal penanggulangan bencana Rencana Komitmen Lingkungan dan Sosial Dana Bersama Laporan yang dibuat oleh Pusdalops BPBD baik fisik dan/atau elektronik yang tercatat di Pusdalops');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1102, 'Dokumen ini didukung dengan lampiran daftar permohonan kegiatan, nilai permohonan, kewenangan, dan keterangan Surat Untuk kewenangan milik Pernyataan pemerintah berisi data aset Kewenangan (nomor registrasi, kode barang, nama barang, dan kewenangan) Untuk kegiatan bantuan/stimulan perumahan, sosial, ekonomi, dan sumber daya alam diisi dengan kewenangan masyarakat Untuk kegiatan berupa nonkonstruksi seperti pendampingan, bimbingan teknis, dan lain sebagainya diisi dengan kewenangan kementerian/lembaga atau Pemerintah Daerah Narasi permohonan sesuai sistematika penulisan permohonan penyaluran Narasi dana bersama permohonan penanggulangan bencana tahap pascabencana dan juga substansi yang memperkuat permohonan Dokumen Acuan permohonan untuk Rencana semua jenis bencana Rehabilitasi dan menggunakan dokumen Rekonstruksi Rencana Rehabilitasi dan Pascabencana Rekonstruksi Pascabencana Reviu Aparat Berisi hasil reviu terhadap Pengawas perencanaan kegiatan dari Instansi Aparat Pengawas Instansi Pemerintah oleh Pemerintah instansi Inspektorat pemohon Surat Pernyataan Pelindungan Lingkungan dan Sosial Mengacu pada Petunjuk Formulir Dokumen Pelaksanaan yang mengatur Pelindungan Pengelolaan mengenai sistem 3 Lingkungan dan Lingkungan pengelolaan lingkungan dan Sosial dan Sosial sosial pada dana bersama Rancangan Awal penanggulangan bencana Rencana Komitmen Lingkungan dan Sosial Dana Bersama Laporan yang dibuat oleh Pusdalops BPBD baik fisik dan/atau elektronik yang tercatat di Pusdalops', 'LAMPIRAN IV (lanjutan 3)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1103, 'juklak-7-2025', 70, 'lampiran', 'LAMPIRAN IV (lanjutan 4)', NULL, 52, 'BNPB Laporan Kejadian Dokumen Bencana Dapat dilengkapi dengan 4 artikel media cetak/elektronik Tambahan tentang kejadian bencana yang memuat jenis bencana, waktu kejadian bencana, lokasi kejadian bencana Dokumentasi aset rusak Dokumentasi terdampak bencana yang Aset Rusak dilengkapi titik koordinat.
Berisi tentang nama aset, kode barang, nomor Kartu Inventaris registrasi, dimensi, tahun Barang. perolehan, nilai aset, status kondisi aset, dll, sesuai klasifikasinya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1103, 'BNPB Laporan Kejadian Dokumen Bencana Dapat dilengkapi dengan 4 artikel media cetak/elektronik Tambahan tentang kejadian bencana yang memuat jenis bencana, waktu kejadian bencana, lokasi kejadian bencana Dokumentasi aset rusak Dokumentasi terdampak bencana yang Aset Rusak dilengkapi titik koordinat.
Berisi tentang nama aset, kode barang, nomor Kartu Inventaris registrasi, dimensi, tahun Barang. perolehan, nilai aset, status kondisi aset, dll, sesuai klasifikasinya.', 'LAMPIRAN IV (lanjutan 4)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1104, 'juklak-7-2025', 71, 'lampiran', 'LAMPIRAN IV (lanjutan 5)', NULL, 54, 'Dikeluarkan oleh BPBD terhadap Kelompok Bukti Verifikasi Masyarakat terdampak Kelompok bencana yang memuat hasil Masyarakat oleh verifikasi nama kelompok Pemerintah beserta anggota, lokasi Daerah kelompok, dan komoditas dan/atau aset terdampak Berisi tentang volume dan Rencana harga satuan kegiatan yang Anggaran Biaya ditandatangani oleh instansi Kegiatan teknis terkait Gambar Berisi tentang site plan dan Rencana gambar detail kegiatan yang kegiatan (untuk ditandatangani oleh instansi kegiatan teknis terkait konstruksi) Berisikan penjelasan proyek secara rinci mulai dari jenis, besar, dan lokasi yang menjelaskan mengenai kegiatan yang akan dilaksanakan Dalam permohonan kegiatan nonkonstruksi dilengkapi dengan rancangan petunjuk Rencana Kerja teknis pelaksanaan kegiatan dan Syarat yang berisi uraian kegiatan/pembelanjaan, volume/jumlah satuan, harga satuan, spesifikasi barang, dan jumlah dana serta keterangan mengenai sumber pendanaan dan metode pelaksanaan kegiatan Grafik yang menggambarkan Kurva S perkembangan/ kemajuan kegiatan dari waktu ke waktu Berisikan penetapan individu calon penerima bantuan.
Keputusan Kepala Daerah Ditandatangani oleh tentang Bupati/Walikota sesuai Penetapan kewenangannya. Secara Penerima rinci berisi nama individu, Bantuan (khusus alamat (desa/kelurahan dan untuk bantuan kecamatan), Nomor Induk stimulan rumah) Kependudukan, Nomor Kartu Keluarga, dan kriteria kerusakan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1104, 'Dikeluarkan oleh BPBD terhadap Kelompok Bukti Verifikasi Masyarakat terdampak Kelompok bencana yang memuat hasil Masyarakat oleh verifikasi nama kelompok Pemerintah beserta anggota, lokasi Daerah kelompok, dan komoditas dan/atau aset terdampak Berisi tentang volume dan Rencana harga satuan kegiatan yang Anggaran Biaya ditandatangani oleh instansi Kegiatan teknis terkait Gambar Berisi tentang site plan dan Rencana gambar detail kegiatan yang kegiatan (untuk ditandatangani oleh instansi kegiatan teknis terkait konstruksi) Berisikan penjelasan proyek secara rinci mulai dari jenis, besar, dan lokasi yang menjelaskan mengenai kegiatan yang akan dilaksanakan Dalam permohonan kegiatan nonkonstruksi dilengkapi dengan rancangan petunjuk Rencana Kerja teknis pelaksanaan kegiatan dan Syarat yang berisi uraian kegiatan/pembelanjaan, volume/jumlah satuan, harga satuan, spesifikasi barang, dan jumlah dana serta keterangan mengenai sumber pendanaan dan metode pelaksanaan kegiatan Grafik yang menggambarkan Kurva S perkembangan/ kemajuan kegiatan dari waktu ke waktu Berisikan penetapan individu calon penerima bantuan.
Keputusan Kepala Daerah Ditandatangani oleh tentang Bupati/Walikota sesuai Penetapan kewenangannya. Secara Penerima rinci berisi nama individu, Bantuan (khusus alamat (desa/kelurahan dan untuk bantuan kecamatan), Nomor Induk stimulan rumah) Kependudukan, Nomor Kartu Keluarga, dan kriteria kerusakan.', 'LAMPIRAN IV (lanjutan 5)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1105, 'juklak-7-2025', 72, 'lampiran', 'LAMPIRAN IV (lanjutan 6)', NULL, 55, 'Keputusan mengenai Keputusan ditandatangani pembentukan minimal oleh Camat Kelompok Masyarakat (khusus untuk Berisikan data berupa kegiatan Non identitas kelompok dan Konstruksi) pengorganisasiannya.
