INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1106, 'juklak-7-2025', 73, 'lampiran', 'LAMPIRAN IV (lanjutan 7)', NULL, 56, '7 Nominal Pengajuan Anggaran Rp. …………………………………………………………………………………………………… (terbilang dalam huruf) Dokumen Hasil Ket. (Asli atau No Penjelasan Indikator Umum Rincian Sesuai Tidak Ragu) Surat permohonan ditandatangani oleh Pejabat Surat Pimpinan Tinggi Madya bagi Dokumen permohonan Menggunakan kepala surat 1 kementerian/lembaga dan Permohonan Penyaluran Dana instansi gubernur/bupati/walikota bagi Bersama pemerintah daerah sesuai kewenangannya.
Terdapat Kota dan Tanggal Pembuatan Surat Terdapat Nomor Surat Ditujukan kepada Kepala BNPB Dibubuhi tanda tangan dan cap basah Untuk permohonan Kementerian/Lembaga, ditandatangani oleh paling rendah Pejabat Pimpinan Tinggi Madya Untuk permohonan Pemerintah Daerah, ditandatangani oleh Kepala Daerah Surat pernyataan bencana bermeterai Rp.10.000,- atau keputusan tanggap darurat Jenis bencana yang ditandatangani oleh gubernur/bupati/walikota Surat Keputusan sesuai kewenangannya;
Tanggap Darurat Wajib memuat jenis bencana, Dokumen 2 atau Surat waktu kejadian bencana, lokasi Umum Waktu kejadian bencana Pernyataan kejadian bencana (desa Bencana dan/atau kecamatan);
Untuk permohonan Lokasi kejadian bencana (desa kementerian/lembaga dan dan/atau kecamatan);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1106, '7 Nominal Pengajuan Anggaran Rp. …………………………………………………………………………………………………… (terbilang dalam huruf) Dokumen Hasil Ket. (Asli atau No Penjelasan Indikator Umum Rincian Sesuai Tidak Ragu) Surat permohonan ditandatangani oleh Pejabat Surat Pimpinan Tinggi Madya bagi Dokumen permohonan Menggunakan kepala surat 1 kementerian/lembaga dan Permohonan Penyaluran Dana instansi gubernur/bupati/walikota bagi Bersama pemerintah daerah sesuai kewenangannya.
Terdapat Kota dan Tanggal Pembuatan Surat Terdapat Nomor Surat Ditujukan kepada Kepala BNPB Dibubuhi tanda tangan dan cap basah Untuk permohonan Kementerian/Lembaga, ditandatangani oleh paling rendah Pejabat Pimpinan Tinggi Madya Untuk permohonan Pemerintah Daerah, ditandatangani oleh Kepala Daerah Surat pernyataan bencana bermeterai Rp.10.000,- atau keputusan tanggap darurat Jenis bencana yang ditandatangani oleh gubernur/bupati/walikota Surat Keputusan sesuai kewenangannya;
Tanggap Darurat Wajib memuat jenis bencana, Dokumen 2 atau Surat waktu kejadian bencana, lokasi Umum Waktu kejadian bencana Pernyataan kejadian bencana (desa Bencana dan/atau kecamatan);
Untuk permohonan Lokasi kejadian bencana (desa kementerian/lembaga dan dan/atau kecamatan);', 'LAMPIRAN IV (lanjutan 7)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1107, 'juklak-7-2025', 74, 'lampiran', 'LAMPIRAN IV (lanjutan 8)', NULL, 57, 'Pemerintah Provinsi harus bertanda tangan bupati/walikota dilengkapi dengan surat dan cap (untuk surat pernyataan pernyataan bencana bencana harus file asli) bupati/walikota bermeterai Rp10.000,- atau keputusan tanggap darurat dari Bermeterai Rp10.000,- provinsi/kabupaten/kota terdampak Rekapitulasi permohonan nama kegiatan, kegiatan rehabilitasi dan lokasi rekonstruksi pascabencana volume, memuat nama kegiatan, lokasi, Rekapitulasi satuan, volume, satuan, harga satuan, permohonan harga satuan, dan total anggaran yang kegiatan ditandatangani oleh Pejabat dan total anggaran Pimpinan Tinggi Pratama pada ditandatangani oleh Pejabat kementerian/lembaga atau Pimpinan Tinggi Pratama (asli dan Kepala Pelaksana BPBD. cap basah) Ditandatangani oleh Pejabat Pimpinan Tinggi Madya bagi kementerian/lembaga dan gubernur/bupati/walikota bagi pemerintah daerah sesuai ditandatangani oleh Pejabat kewenangannya bermeterai Pimpinan Tinggi Madya (asli dan Rp10.000. Dokumen ini cap basah) Surat Pernyataan didukung dengan lampiran Kewenangan daftar permohonan kegiatan, nilai permohonan, kewenangan, dan keterangan.
Untuk kewenangan milik pemerintah berisi data aset (nomor registrasi, kode bermeterai Rp10.000 barang, nama barang, dan kewenangan).
Untuk kegiatan bantuan/stimulan perumahan, sosial, ekonomi, dan sumber nomor registrasi, daya alam diisi dengan kewenangan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1107, 'Pemerintah Provinsi harus bertanda tangan bupati/walikota dilengkapi dengan surat dan cap (untuk surat pernyataan pernyataan bencana bencana harus file asli) bupati/walikota bermeterai Rp10.000,- atau keputusan tanggap darurat dari Bermeterai Rp10.000,- provinsi/kabupaten/kota terdampak Rekapitulasi permohonan nama kegiatan, kegiatan rehabilitasi dan lokasi rekonstruksi pascabencana volume, memuat nama kegiatan, lokasi, Rekapitulasi satuan, volume, satuan, harga satuan, permohonan harga satuan, dan total anggaran yang kegiatan ditandatangani oleh Pejabat dan total anggaran Pimpinan Tinggi Pratama pada ditandatangani oleh Pejabat kementerian/lembaga atau Pimpinan Tinggi Pratama (asli dan Kepala Pelaksana BPBD. cap basah) Ditandatangani oleh Pejabat Pimpinan Tinggi Madya bagi kementerian/lembaga dan gubernur/bupati/walikota bagi pemerintah daerah sesuai ditandatangani oleh Pejabat kewenangannya bermeterai Pimpinan Tinggi Madya (asli dan Rp10.000. Dokumen ini cap basah) Surat Pernyataan didukung dengan lampiran Kewenangan daftar permohonan kegiatan, nilai permohonan, kewenangan, dan keterangan.
Untuk kewenangan milik pemerintah berisi data aset (nomor registrasi, kode bermeterai Rp10.000 barang, nama barang, dan kewenangan).
Untuk kegiatan bantuan/stimulan perumahan, sosial, ekonomi, dan sumber nomor registrasi, daya alam diisi dengan kewenangan masyarakat.', 'LAMPIRAN IV (lanjutan 8)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1108, 'juklak-7-2025', 75, 'lampiran', 'LAMPIRAN IV (lanjutan 9)', NULL, 59, 'Untuk kegiatan berupa nonkonstruksi seperti kode barang, pendampingan, bimbingan teknis, dan lain sebagainya diisi dengan kewenangan nama barang dan kewenangan kementerian/lembaga atau Pemerintah Daerah.
Terdapat Sampul sesuai format Terdapat kata pengantar Ringkasan eksekutif mencakup kerangka sesuai format Terdapat daftar isi Narasi permohonan sesuai Terdapat lembar identitas sistematika penulisan pemohon sesuai format, yang permohonan penyaluran dana bertanda tangan dan berstempel Narasi Bab I Pendahuluan terdiri dari 4 bersama penanggulangan Permohonan (empat) subbab: bencana tahap pascabencana dan juga substansi yang - Latar belakang (terdapat data-data memperkuat permohonan. pendukung kajian kebutuhan)
- Maksud dan tujuan
- Ruang lingkup
- Keluaran Bab II Gambaran Umum terdiri dari 5 (lima) subbab:
- Untuk pemohon:
- kementerian/lembaga menyampaikan profil institusi
- Pemerintah Daerah menyampaikan profil daerah
- Profil kebencanaan
- Kondisi anggaran
- Potensi sumber daya manusia
- Riwayat kerja sama lembaga/donor Bab III Usulan Kegiatan terdiri dari 7 (tujuh) subbab:
- Kegiatan eksisting dan kegiatan yang diusulkan
- Metodologi
- Kerangka kerja logis (di dukung dengan penjelasan telaah teknis)
- Rencana kerja (timeline)
- Pelaksana
- Kerangka pemantauan dan evaluasi
- Rencana tindak lanjut Bab IV Penutup terdiri dari 2 (dua) poin yaitu:
- Ringkasan isi permohonan');
