INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1109, 'juklak-7-2025', 76, 'lampiran', 'LAMPIRAN IV (lanjutan 10)', NULL, 60, '- Urgensi pembiayaan usulan kegiatan Permohonan ditandatangani dan distempel oleh pelaksana kegiatan Lampiran permohonan sesuai dengan Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Dokumen Acuan permohonan untuk Masih berlaku Rencana semua jenis bencana Rehabilitasi dan menggunakan dokumen Rekonstruksi Rencana Rehabilitasi dan Ditetapkan oleh Kepala Daerah Pascabencana Rekonstruksi Pascabencana.
Reviu Aparat Laporan Hasil Reviu Berisi hasil reviu terhadap Pengawas Nomor dan Tanggal perencanaan kegiatan dari Instansi Hasil Reviu Aparat Pengawas Instansi Pemerintah oleh Tanda tangan pejabat yang Pemerintah instansi pemohon.
Inspektorat berwenang Mengacu pada Petunjuk Kesesuaian Format Surat Surat Pernyataan Pelaksanaan yang mengatur Pelindungan mengenai sistem pengelolaan Surat pernyataan ditandatangan, Lingkungan dan lingkungan dan sosial pada bermaterai, dan distempel Sosial dana bersama pemohon penanggulangan bencana Bagian 1 Kelembagaan & Dokumen Administrasi, terisi pada bagian:
Pengelolaan - Judul Kegiatan 3 - Kode Kategori dan Klasifikasi Lingkungan Mengacu pada Petunjuk dan Sosial Formulir Pelaksanaan yang mengatur Risiko Pelindungan mengenai sistem pengelolaan - Ringkasan kegiatan yang Lingkungan dan lingkungan dan sosial pada diusulkan Sosial dana bersama - Kontak Institusi/ Lembaga penanggulangan bencana - Jenis Kegiatan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1109, '- Urgensi pembiayaan usulan kegiatan Permohonan ditandatangani dan distempel oleh pelaksana kegiatan Lampiran permohonan sesuai dengan Petunjuk Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Dokumen Acuan permohonan untuk Masih berlaku Rencana semua jenis bencana Rehabilitasi dan menggunakan dokumen Rekonstruksi Rencana Rehabilitasi dan Ditetapkan oleh Kepala Daerah Pascabencana Rekonstruksi Pascabencana.
