INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1110, 'juklak-7-2025', 77, 'lampiran', 'LAMPIRAN IV (lanjutan 11)', NULL, 61, '- Durasi Kegiatan yang diusulkan Bagian 2 Deskripsi Lokasi Kegiatan, terisi pada bagian:
- Nama Lokasi Kegiatan
