INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1111, 'juklak-7-2025', 78, 'lampiran', 'LAMPIRAN IV (lanjutan 12)', NULL, 62, '- Identifikasi kapan/di mana proses konsultasi publik berlangsung, apabila diperlukan Bagian 5 Pengelolaan Lingkungan dan Sosial - A. Daftar Negatif terisi Bagian 5 Pengelolaan Lingkungan dan Sosial - B. Klasifikasi Tingkat Risiko Lingkungan dan Sosial terisi Bagian 5 Pengelolaan Lingkungan dan Sosial - C. Pemeriksaan Risiko Lingkungan dan Sosial terisi paling sedikit pada SLS 1 dan SLS 10 Kesesuaian Ringkasan Kegiatan dengan Narasi Permohonan Kegiatan tidak masuk ke dalam Daftar Negatif Risiko tetap berada di tingkat rendah/menengah Dampak kegiatan teridentifikasi paling sedikit pada SLS 1 dan SLS 10 Strategi pengelolaan dampak dan/atau instrumen yang dibutuhkan terumuskan paling sedikit pada SLS 1 dan SLS 10 Halaman utama Rancangan Awal Rencana Komitmen Lingkungan Dan Sosial Dana Bersama Penanggulangan Bencana Bagian A. Komitmen Pemantauan dan Pelaporan - A. Pelaporan (Tindakan dan Rencana Jangka Waktu Pelaporan) terisi Rancangan Awal Mengacu pada Petunjuk Bagian A. Komitmen Pemantauan Rencana Pelaksanaan yang mengatur dan Pelaporan - B. Insiden dan Komitmen mengenai sistem pengelolaan Kecelakaan (Tindakan dan Lingkungan dan lingkungan dan sosial pada Rencana Jangka Waktu Sosial Dana dana bersama Pelaporan) terisi Bersama penanggulangan bencana.
Bagian B. Komitmen Terkait Standar Lingkungan dan Sosial dan Peningkatan Kapasitas terisi sesuai hasil Bagian B.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1111, '- Identifikasi kapan/di mana proses konsultasi publik berlangsung, apabila diperlukan Bagian 5 Pengelolaan Lingkungan dan Sosial - A. Daftar Negatif terisi Bagian 5 Pengelolaan Lingkungan dan Sosial - B. Klasifikasi Tingkat Risiko Lingkungan dan Sosial terisi Bagian 5 Pengelolaan Lingkungan dan Sosial - C. Pemeriksaan Risiko Lingkungan dan Sosial terisi paling sedikit pada SLS 1 dan SLS 10 Kesesuaian Ringkasan Kegiatan dengan Narasi Permohonan Kegiatan tidak masuk ke dalam Daftar Negatif Risiko tetap berada di tingkat rendah/menengah Dampak kegiatan teridentifikasi paling sedikit pada SLS 1 dan SLS 10 Strategi pengelolaan dampak dan/atau instrumen yang dibutuhkan terumuskan paling sedikit pada SLS 1 dan SLS 10 Halaman utama Rancangan Awal Rencana Komitmen Lingkungan Dan Sosial Dana Bersama Penanggulangan Bencana Bagian A. Komitmen Pemantauan dan Pelaporan - A. Pelaporan (Tindakan dan Rencana Jangka Waktu Pelaporan) terisi Rancangan Awal Mengacu pada Petunjuk Bagian A. Komitmen Pemantauan Rencana Pelaksanaan yang mengatur dan Pelaporan - B. Insiden dan Komitmen mengenai sistem pengelolaan Kecelakaan (Tindakan dan Lingkungan dan lingkungan dan sosial pada Rencana Jangka Waktu Sosial Dana dana bersama Pelaporan) terisi Bersama penanggulangan bencana.
Bagian B. Komitmen Terkait Standar Lingkungan dan Sosial dan Peningkatan Kapasitas terisi sesuai hasil Bagian B.', 'LAMPIRAN IV (lanjutan 12)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1112, 'juklak-7-2025', 79, 'lampiran', 'LAMPIRAN IV (lanjutan 13)', NULL, 63, 'Pemeriksaan Risiko Lingkungan dan Sosial pada Formulir Pelindungan Lingkungan dan Sosial Tanggal & Waktu kejadian Laporan yang dibuat oleh Dokumen Laporan Kejadian bencana 4 Pusdalops BPBD baik fisik Tambahan Bencana Kronologi/informasi kejadian dan/atau elektronik yang bencana tercatat di Pusat Pengendalian Lokasi kejadian bencana Operasi BNPB Data terdampak bencana (berupa aset yang terdampak dan di wilayah terdampak di Kecamatan xxx) Upaya tindakan dan penanganan Kendala Dapat dilengkapi dengan Jenis bencana artikel media cetak/elektronik Waktu kejadian bencana tentang kejadian bencana Lokasi kejadian bencana yang memuat jenis bencana, waktu kejadian bencana, lokasi kejadian bencana.
Foto/dokumentasi aset rusak dari Dokumentasi aset rusak dua sisi yang berbeda (terlihat aset Dokumentasi terdampak bencana yang rusak) Aset Rusak dilengkapi titik koordinat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1112, 'Pemeriksaan Risiko Lingkungan dan Sosial pada Formulir Pelindungan Lingkungan dan Sosial Tanggal & Waktu kejadian Laporan yang dibuat oleh Dokumen Laporan Kejadian bencana 4 Pusdalops BPBD baik fisik Tambahan Bencana Kronologi/informasi kejadian dan/atau elektronik yang bencana tercatat di Pusat Pengendalian Lokasi kejadian bencana Operasi BNPB Data terdampak bencana (berupa aset yang terdampak dan di wilayah terdampak di Kecamatan xxx) Upaya tindakan dan penanganan Kendala Dapat dilengkapi dengan Jenis bencana artikel media cetak/elektronik Waktu kejadian bencana tentang kejadian bencana Lokasi kejadian bencana yang memuat jenis bencana, waktu kejadian bencana, lokasi kejadian bencana.
Foto/dokumentasi aset rusak dari Dokumentasi aset rusak dua sisi yang berbeda (terlihat aset Dokumentasi terdampak bencana yang rusak) Aset Rusak dilengkapi titik koordinat.', 'LAMPIRAN IV (lanjutan 13)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1113, 'juklak-7-2025', 80, 'lampiran', 'LAMPIRAN IV (lanjutan 14)', NULL, 64, 'Dilengkapi titik koordinat dan lokasi Jenis aset/nama aset Nomor kode barang Nomor registrasi Konstruksi Berisi tentang nama aset, kode Dimensi (panjang, lebar, luas) barang, nomor registrasi, Kartu Inventaris dimensi, tahun perolehan, nilai Kondisi aset eksisting Barang. Tahun perolehan aset aset, status kondisi aset, dll, sesuai klasifikasinya. Status kepemilikan aset Dokumen KIB ditandatangani oleh Kepala BPKAD dan Kepala Perangkat Daerah teknis terkait (asli dan cap basah) Dikeluarkan oleh BPBD Ditandatangan oleh tim verifikasi terhadap Kelompok BPBD Bukti Verifikasi Nama kelompok masyarakat Masyarakat terdampak Kelompok bencana yang memuat hasil Lokasi kelompok Masyarakat oleh verifikasi nama kelompok Aset/komoditas terdampak Pemerintah beserta anggota, lokasi Daerah kelompok, dan komoditas dan/atau aset terdampak.
Berisi tentang volume dan Ditandatangan instansi teknis Rencana terkait (asli dan cap basah) harga satuan kegiatan yang Anggaran Biaya ditandatangani oleh instansi Kegiatan terdapat tanggal teknis terkait.
Gambar Rencana Berisi tentang site plan dan Ditandatangan instansi teknis kegiatan (untuk gambar detail kegiatan yang terkait (asli dan cap basah) kegiatan ditandatangani oleh instansi konstruksi) teknis terkait. terdapat tanggal Berisikan penjelasan proyek Ditandatangan instansi teknis secara rinci mulai dari jenis, terkait (asli dan cap basah) besar, dan lokasi yang menjelaskan mengenai kegiatan yang akan dilaksanakan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1113, 'Dilengkapi titik koordinat dan lokasi Jenis aset/nama aset Nomor kode barang Nomor registrasi Konstruksi Berisi tentang nama aset, kode Dimensi (panjang, lebar, luas) barang, nomor registrasi, Kartu Inventaris dimensi, tahun perolehan, nilai Kondisi aset eksisting Barang. Tahun perolehan aset aset, status kondisi aset, dll, sesuai klasifikasinya. Status kepemilikan aset Dokumen KIB ditandatangani oleh Kepala BPKAD dan Kepala Perangkat Daerah teknis terkait (asli dan cap basah) Dikeluarkan oleh BPBD Ditandatangan oleh tim verifikasi terhadap Kelompok BPBD Bukti Verifikasi Nama kelompok masyarakat Masyarakat terdampak Kelompok bencana yang memuat hasil Lokasi kelompok Masyarakat oleh verifikasi nama kelompok Aset/komoditas terdampak Pemerintah beserta anggota, lokasi Daerah kelompok, dan komoditas dan/atau aset terdampak.
Berisi tentang volume dan Ditandatangan instansi teknis Rencana terkait (asli dan cap basah) harga satuan kegiatan yang Anggaran Biaya ditandatangani oleh instansi Kegiatan terdapat tanggal teknis terkait.
Gambar Rencana Berisi tentang site plan dan Ditandatangan instansi teknis kegiatan (untuk gambar detail kegiatan yang terkait (asli dan cap basah) kegiatan ditandatangani oleh instansi konstruksi) teknis terkait. terdapat tanggal Berisikan penjelasan proyek Ditandatangan instansi teknis secara rinci mulai dari jenis, terkait (asli dan cap basah) besar, dan lokasi yang menjelaskan mengenai kegiatan yang akan dilaksanakan.', 'LAMPIRAN IV (lanjutan 14)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1114, 'juklak-7-2025', 81, 'lampiran', 'LAMPIRAN IV (lanjutan 15)', NULL, 65, 'Rencana Kerja Dalam permohonan kegiatan - Terdapat tanggal dan Syarat nonkonstruksi dilengkapi - Dibuatkan template dengan petunjuk teknis - Petunjuk teknis di rubah menjadi pelaksanaan kegiatan yang rancangan petunjuk teknis, yang berisi uraian kegiatan risiko rendah dapat kegiatan/pembelanjaan, disahkan oleh kepala dinas terkait volume/jumlah satuan, harga satuan, spesifikasi barang, dan jumlah dana serta keterangan mengenai sumber pendanaan dan metode pelaksanaan kegiatan.
Ditandatangani instansi teknis terkait (asli dan cap basah) terdapat tanggal Grafik yang menggambarkan Kurva S perkembangan/ kemajuan kegiatan dari waktu ke waktu Berisikan penetapan individu yang akan menerima bantuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1114, 'Rencana Kerja Dalam permohonan kegiatan - Terdapat tanggal dan Syarat nonkonstruksi dilengkapi - Dibuatkan template dengan petunjuk teknis - Petunjuk teknis di rubah menjadi pelaksanaan kegiatan yang rancangan petunjuk teknis, yang berisi uraian kegiatan risiko rendah dapat kegiatan/pembelanjaan, disahkan oleh kepala dinas terkait volume/jumlah satuan, harga satuan, spesifikasi barang, dan jumlah dana serta keterangan mengenai sumber pendanaan dan metode pelaksanaan kegiatan.
Ditandatangani instansi teknis terkait (asli dan cap basah) terdapat tanggal Grafik yang menggambarkan Kurva S perkembangan/ kemajuan kegiatan dari waktu ke waktu Berisikan penetapan individu yang akan menerima bantuan.', 'LAMPIRAN IV (lanjutan 15)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1115, 'juklak-7-2025', 82, 'lampiran', 'LAMPIRAN IV (lanjutan 16)', NULL, 66, 'Ditandatangani oleh Keputusan Bupati/Walikota (Asli dan cap Ditandatangani oleh basah) Kepala Daerah Bupati/Walikota sesuai tentang Nama Penerima Bantuan kewenangannya. Secara rinci Penetapan Nomor Induk Kependudukan dan berisi nama individu, alamat Penerima Nomor Kartu Keluarga dan Kriteria (desa/kelurahan dan Bantuan (khusus kerusakan masing-masing kecamatan), Nomor Induk untuk bantuan penerima Kependudukan, Nomor Kartu stimulan rumah) Alamat (desa/kelurahan dan Keluarga, dan kriteria kerusakan. kecamatan) Terdapat tanggal dan nomor Keputusan Keputusan Keputusan ditandatangani Ditandatangani oleh Camat (Asli mengenai minimal oleh Camat dan cap basah) Kelompok Menggunakan Kop Surat Masyarakat Terdapat tanggal dan nomor surat Berisikan data berupa identitas Penerima kelompok dan Bantuan pengorganisasiannya Nonkonstruksi Keputusan mengenai Keputusan ditandatangani Keputusan ditandatangani minimal Kelompok minimal oleh Camat oleh Camat Masyarakat Penerima Berisikan data berupa identitas Berisikan data berupa identitas Bantuan kelompok dan kelompok dan Nonkonstruksi pengorganisasiannya pengorganisasiannya.
Untuk permohonan dari Perda pembentukan awal BPBD Pemerintah Daerah Prov/Kab/Kota Peraturan Daerah Dalam Perda terdapat lampiran tentang SOTK BPBD Pembentukan Provinsi/Kabupaten/Kota BPBD Dokumen yang disampaikan dapat berupa fotokopi Format 3 – Surat Pemberitahuan Verifikasi Lapangan Nomor : ……. tanggal, bulan, tahun Sifat : …….
Lampiran : …….');
