INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1119, 'juklak-7-2025', 86, 'lampiran', 'LAMPIRAN IV (lanjutan 20)', NULL, 71, 'Penanggung Jawab Tim Penelaahan, Verifikasi dan Evaluasi Deputi Bidang Rehabilitasi dan Rekonstruksi.
Format 6 – Berita Acara Hasil Verifikasi Lapangan atas Permohonan Penyaluran Dana Bersama Tahap Pascabencana BERITA ACARA HASIL VERIFIKASI LAPANGAN ATAS PERMOHONAN NOMOR…….
KEMENTERIAN/LEMBAGA/PEMERINTAH PROVINSI/KABUPATEN/KOTA………..
NOMOR …/…/…/…/… Pada hari _____ tanggal _____ bulan ______ tahun ______ telah dilaksanakan rapat koordinasi hasil verifikasi lapangan atas permohonan nomor ________ kementerian/lembaga/Pemerintah provinsi/kabupaten/kota _____, dengan hasil sebagai berikut:
1. Verifikasi lapangan dilaksanakan berdasarkan : a) Surat Keputusan Tanggap Darurat atau Surat Pernyataan Bencana Nomor: _______ tanggal ________; b) Surat Permohonan Penyaluran Dana Bersama Nomor ________ tanggal _________;
2. Verifikasi lapangan dilakukan oleh Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Deputi Bidang Rehabilitasi dan Rekonstruksi melibatkan Pemerintah Daerah Provinsi/Kabupaten/Kota ________ dan Perangkat Daerah teknis. Adapun kegiatan yang memenuhi kriteria verifikasi lapangan dengan catatan sebagai berikut:
- Kegiatan Konstruksi/Kegiatan Non Konstruksi (Berisi hasil tinjauan lapangan): ________________________________________________________________ ________________________________________________________________ ____________');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1119, 'Penanggung Jawab Tim Penelaahan, Verifikasi dan Evaluasi Deputi Bidang Rehabilitasi dan Rekonstruksi.
Format 6 – Berita Acara Hasil Verifikasi Lapangan atas Permohonan Penyaluran Dana Bersama Tahap Pascabencana BERITA ACARA HASIL VERIFIKASI LAPANGAN ATAS PERMOHONAN NOMOR…….
KEMENTERIAN/LEMBAGA/PEMERINTAH PROVINSI/KABUPATEN/KOTA………..
NOMOR …/…/…/…/… Pada hari _____ tanggal _____ bulan ______ tahun ______ telah dilaksanakan rapat koordinasi hasil verifikasi lapangan atas permohonan nomor ________ kementerian/lembaga/Pemerintah provinsi/kabupaten/kota _____, dengan hasil sebagai berikut:
1. Verifikasi lapangan dilaksanakan berdasarkan : a) Surat Keputusan Tanggap Darurat atau Surat Pernyataan Bencana Nomor: _______ tanggal ________; b) Surat Permohonan Penyaluran Dana Bersama Nomor ________ tanggal _________;
2. Verifikasi lapangan dilakukan oleh Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Deputi Bidang Rehabilitasi dan Rekonstruksi melibatkan Pemerintah Daerah Provinsi/Kabupaten/Kota ________ dan Perangkat Daerah teknis. Adapun kegiatan yang memenuhi kriteria verifikasi lapangan dengan catatan sebagai berikut:
- Kegiatan Konstruksi/Kegiatan Non Konstruksi (Berisi hasil tinjauan lapangan): ________________________________________________________________ ________________________________________________________________ ____________', 'LAMPIRAN IV (lanjutan 20)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1120, 'juklak-7-2025', 87, 'lampiran', 'LAMPIRAN IV (lanjutan 21)', NULL, 72, '3. Kementerian/lembaga (Balai) dalam hal ini memberikan saran teknis sebagai berikut (dapat diberikan jika permohonan berasal dari pemerintah daerah) : _______________________________________________________________ ___________
4. Detailed Engineering Design (DED) akan disusun dengan berlandaskan Standar Harga Satuan yang telah ditetapkan oleh Kepala Daerah dan koefisien yang dipakai sesuai dengan Peraturan Menteri Pekerjaan Umum dan Perumahan Rakyat Nomor 8 Tahun 2023 tentang Pedoman Penyusunan Perkiraan Biaya Pekerjaan Konstruksi Bidang Pekerjaan Umum dan Perumahan Rakyat serta Surat Edaran Direktur Jenderal Bina Konstruksi Nomor 30/SE/Dk/2025 tanggal 28 Februari 2025 tentang Tata Cara Penyusunan Perkiraan Biaya Pekerjaan Konstruksi Bidang Pekerjaan Umum dan Perumahan Rakyat*) (DED akan dilengkapi dengan analisa harga barang sesuai lokasi kegiatan dengan mempertimbangkan mobilisasi material di lokasi usulan kegiatan).
5. Kelengkapan dokumen disampaikan kepada Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Deputi Bidang Rehabilitasi dan Rekonstruksi dalam bentuk hardcopy dan softcopy, khusus untuk Rencana Anggaran Biaya, Analiis Harga Satuan dan Perhitungan Volume dilengkapi pula dengan dokumen Softcopy dalam bentuk Ms. Excel.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1120, '3. Kementerian/lembaga (Balai) dalam hal ini memberikan saran teknis sebagai berikut (dapat diberikan jika permohonan berasal dari pemerintah daerah) : _______________________________________________________________ ___________
4. Detailed Engineering Design (DED) akan disusun dengan berlandaskan Standar Harga Satuan yang telah ditetapkan oleh Kepala Daerah dan koefisien yang dipakai sesuai dengan Peraturan Menteri Pekerjaan Umum dan Perumahan Rakyat Nomor 8 Tahun 2023 tentang Pedoman Penyusunan Perkiraan Biaya Pekerjaan Konstruksi Bidang Pekerjaan Umum dan Perumahan Rakyat serta Surat Edaran Direktur Jenderal Bina Konstruksi Nomor 30/SE/Dk/2025 tanggal 28 Februari 2025 tentang Tata Cara Penyusunan Perkiraan Biaya Pekerjaan Konstruksi Bidang Pekerjaan Umum dan Perumahan Rakyat*) (DED akan dilengkapi dengan analisa harga barang sesuai lokasi kegiatan dengan mempertimbangkan mobilisasi material di lokasi usulan kegiatan).
5. Kelengkapan dokumen disampaikan kepada Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Deputi Bidang Rehabilitasi dan Rekonstruksi dalam bentuk hardcopy dan softcopy, khusus untuk Rencana Anggaran Biaya, Analiis Harga Satuan dan Perhitungan Volume dilengkapi pula dengan dokumen Softcopy dalam bentuk Ms. Excel.', 'LAMPIRAN IV (lanjutan 21)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1121, 'juklak-7-2025', 88, 'lampiran', 'LAMPIRAN IV (lanjutan 22)', NULL, 73, '6. Kebenaran dari perhitungan, volume, harga satuan dan lokasi serta pembuktian kewenangan aset yang akan ditangani merupakan tanggung jawab sepenuhnya Kementerian/Lembaga/Pemerintah Provinsi/Kabupaten/Kota ______.
7. Kementerian/Lembaga/Pemerintah Provinsi/Kabupaten/Kota _______________ bertanggung jawab sepenuhnya secara formal dan materiil atas usulan kegiatan permohonan penyaluran Dana Bersama Penanggulangan Bencana.
8. Rincian kegiatan hasil identifikasi berdasarkan poin 2 di atas dapat dijadikan acuan dalam hal pemulihan dengan mekanisme dan ketentuan yang berlaku.
9. Berita Acara ini dibuat dengan sesungguhnya berdasarkan itikad baik dari semua pihak yang berkepentingan, untuk dipergunakan sebagaimana mestinya.
Demikian berita acara dibuat, sebagai pedoman untuk ditindaklanjuti.
Lokasi, Tgl/Bulan/Tahun No. Nama Jabatan Instansi Tanda Tangan *) disesuaikan dengan ketentuan peraturan perundang-undangan berlaku.');
