INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1133, 'juklak-7-2025', 100, 'lain', 'II. Bagian Umum', NULL, 88, 'PERSIAPAN DAN CHECKLIST VARIABEL PARAMETER KETERANGAN PERENCANAAN Ada Tidak Ada Persiapan dan Rekapitulasi permohonan ☐ ☐ Perencanaan kegiatan Dokumen R3P ☐ ☐ Surat Penetapan Alokasi ☐ ☐ RAB telah memuat: Situasi sebelum usulan ☐ ☐ program berdasarkan Kajian Kebutuhan Pasca Bencana (Jitupasna) Keluaran kegiatan dalam ☐ ☐ unit Spesifikasi teknis pada jenis ☐ ☐ pekerjaan non konstruksi (kegiatan fisik dan non fisik) Anggaran biaya ☐ ☐ Pelaksana/penanggung ☐ ☐ jawab program Lokasi program ☐ ☐ Gambar Rencana ☐ ☐ kegiatan (untuk kegiatan konstruksi) rancangan petunjuk ☐ ☐ teknis untuk kegiatan non konstruksi PELAKSANAAN CHECKLIST DAN VARIABEL PARAMETER TIDAK KETERANGAN SESUAI PELAPORAN SESUAI Pelaksanaan dan RAB perubahan ☐ ☐ apabila ada perubahan* Pelaporan Gambar Rencana kegiatan ☐ ☐ apabila ada perubahan* (untuk kegiatan konstruksi) rancangan petunjuk ☐ ☐ teknis, untuk kegiatan non konstruksi apabila ada perubahan* Status Kemajuan*) Laporan Berkala ☐ ☐ Laporan Akhir ☐ ☐ Konsistensi terhadap Kurva S Perencanaan Realisasi anggaran sesuai ☐ ☐ dicek secara pengamatan sesuai dengan perencanaan atau tidak Output sesuai dengan ☐ ☐ dokumentasi 0%, 50% dan 100% dokumen perencanaan dokumentasi dilengkapi dengan geotaging (untuk kegiatan konstruksi) dokumentasi pertahapan dengan geotaging (untuk kegiatan non konstruksi) Lokasi kegiatan sesuai ☐ ☐ dengan dokumen perencanaan Waktu pelaksanaan sesuai ☐ ☐ dengan dokumen perencanaan Koordinasi antar sektor/ Pemerintah Pusat (K/L ☐ ☐ (diisi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1133, 'PERSIAPAN DAN CHECKLIST VARIABEL PARAMETER KETERANGAN PERENCANAAN Ada Tidak Ada Persiapan dan Rekapitulasi permohonan ☐ ☐ Perencanaan kegiatan Dokumen R3P ☐ ☐ Surat Penetapan Alokasi ☐ ☐ RAB telah memuat: Situasi sebelum usulan ☐ ☐ program berdasarkan Kajian Kebutuhan Pasca Bencana (Jitupasna) Keluaran kegiatan dalam ☐ ☐ unit Spesifikasi teknis pada jenis ☐ ☐ pekerjaan non konstruksi (kegiatan fisik dan non fisik) Anggaran biaya ☐ ☐ Pelaksana/penanggung ☐ ☐ jawab program Lokasi program ☐ ☐ Gambar Rencana ☐ ☐ kegiatan (untuk kegiatan konstruksi) rancangan petunjuk ☐ ☐ teknis untuk kegiatan non konstruksi PELAKSANAAN CHECKLIST DAN VARIABEL PARAMETER TIDAK KETERANGAN SESUAI PELAPORAN SESUAI Pelaksanaan dan RAB perubahan ☐ ☐ apabila ada perubahan* Pelaporan Gambar Rencana kegiatan ☐ ☐ apabila ada perubahan* (untuk kegiatan konstruksi) rancangan petunjuk ☐ ☐ teknis, untuk kegiatan non konstruksi apabila ada perubahan* Status Kemajuan*) Laporan Berkala ☐ ☐ Laporan Akhir ☐ ☐ Konsistensi terhadap Kurva S Perencanaan Realisasi anggaran sesuai ☐ ☐ dicek secara pengamatan sesuai dengan perencanaan atau tidak Output sesuai dengan ☐ ☐ dokumentasi 0%, 50% dan 100% dokumen perencanaan dokumentasi dilengkapi dengan geotaging (untuk kegiatan konstruksi) dokumentasi pertahapan dengan geotaging (untuk kegiatan non konstruksi) Lokasi kegiatan sesuai ☐ ☐ dengan dokumen perencanaan Waktu pelaksanaan sesuai ☐ ☐ dengan dokumen perencanaan Koordinasi antar sektor/ Pemerintah Pusat (K/L ☐ ☐ (diisi', 'II. Bagian Umum', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1134, 'juklak-7-2025', 101, 'lain', 'II. Bagian Umum (lanjutan 1)', NULL, 88, 'dengan nama lembaga) Lembaga terkait*) terkait) Pemerintah Daerah ☐ ☐ (diisi dengan nama lembaga) Pelaku Usaha/Swasta ☐ ☐ (diisi dengan nama lembaga) Akademisi ☐ ☐ (diisi dengan nama lembaga) Media ☐ ☐ (diisi dengan nama lembaga) Kelompok Masyarakat ☐ ☐ (diisi dengan nama lembaga) (Kelompok Masyarakat, NGO, LSM, dll) UMKM ☐ ☐ (diisi dengan nama lembaga) Pelibatan Masyarakat Masyarakat sekitar ☐ ☐ dalam Program*) mendapat sosialisasi mengenai pelaksanaan program Masyarakat sekitar ☐ ☐ dilibatkan dalam pelaksanaan program Masyarakat sekitar ☐ ☐ dilibatkan dalam pengawasan pelaksanaan program Masyarakat sekitar memiliki ☐ ☐ forum untuk menyampaikan masukan terkait program Masyarakat sekitar ☐ ☐ dilibatkan dalam konsultasi serah terima keluaran dengan Pemerintah Daerah Transparansi Informasi Program diinformasikan ☐ ☐ kepada masyarakat sekitar Terdapat papan informasi ☐ ☐ program Terdapat rapat/ ☐ ☐ musyawarah berkala selama pelaksanaan program Pelibatan Perempuan Pelibatan Perempuan dalam ☐ ☐ (data pilah dilakukan sejak awal) dalam Program Program Tindak Lanjut Terdapat tindak lanjut ☐ ☐ perbaikan yang dapat dilakukan Terdapat upaya kemitraan ☐ ☐ lain setelah program dilaksanakan Terdapat pengelolaan aset ☐ ☐ dari program yang dijalankan Terdapat alternatif pola ☐ ☐ pendanaan lain untuk melanjutkan program Keterangan: *) : Dipilih yang relevan dengan pelaksanaan');
