INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1137, 'juklak-7-2025', 104, 'lain', 'III. Bagian Kepatuhan terhadap Standar Sistem Pengelolaan Lingkungan dan Sosial (lanjutan 2)', NULL, 93, 'No Nama Lengkap Jabatan dalam Tim Tanda Tangan 1 2 3 dst Format 10 – Rekomendasi atas Hasil Penelaahan, Verifikasi, dan Pertimbangan Pendanaan Dana Bersama Tahap Pascabencana KOP SURAT KEPALA BNPB Nomor : ………………… tanggal, bulan, tahun Sifat : Rahasia Lampiran : 1 (satu) berkas Hal : Rekomendasi atas Hasil Penelaahan, Verifikasi, dan Pertimbangan Permohonan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Yth. Menteri Keuangan di Tempat Dalam rangka pelaksanaan ketentuan Pasal 8 ayat (4) Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana, bersama ini disampaikan hal-hal sebagai berikut.
1. Permohonan yang telah disampaikan oleh Pemohon (kementerian/lembaga dan pemerintah daerah) kepada Badan Nasional Penanggulangan Bencana telah dilakukan penelaahan dan verifikasi (risalah hasil penelaahan dan verifikasi sebagaimana terlampir) setelah berkoordinasi dengan Kementerian Koordinator Bidang Pembangunan Manusia dan Kebudayaan.
2. Terhadap permohonan dimaksud pada angka 1 telah diberikan pertimbangan oleh Kementerian Keuangan, Kementerian Perencanaan Pembangunan Nasional/Badan Perencanaan Pembangunan Nasional, dan Kementerian Dalam Negeri (risalah pertimbangan sebagaimana terlampir).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1137, 'No Nama Lengkap Jabatan dalam Tim Tanda Tangan 1 2 3 dst Format 10 – Rekomendasi atas Hasil Penelaahan, Verifikasi, dan Pertimbangan Pendanaan Dana Bersama Tahap Pascabencana KOP SURAT KEPALA BNPB Nomor : ………………… tanggal, bulan, tahun Sifat : Rahasia Lampiran : 1 (satu) berkas Hal : Rekomendasi atas Hasil Penelaahan, Verifikasi, dan Pertimbangan Permohonan Penyaluran Dana Bersama Penanggulangan Bencana Tahap Pascabencana Yth. Menteri Keuangan di Tempat Dalam rangka pelaksanaan ketentuan Pasal 8 ayat (4) Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana, bersama ini disampaikan hal-hal sebagai berikut.
1. Permohonan yang telah disampaikan oleh Pemohon (kementerian/lembaga dan pemerintah daerah) kepada Badan Nasional Penanggulangan Bencana telah dilakukan penelaahan dan verifikasi (risalah hasil penelaahan dan verifikasi sebagaimana terlampir) setelah berkoordinasi dengan Kementerian Koordinator Bidang Pembangunan Manusia dan Kebudayaan.
2. Terhadap permohonan dimaksud pada angka 1 telah diberikan pertimbangan oleh Kementerian Keuangan, Kementerian Perencanaan Pembangunan Nasional/Badan Perencanaan Pembangunan Nasional, dan Kementerian Dalam Negeri (risalah pertimbangan sebagaimana terlampir).', 'III. Bagian Kepatuhan terhadap Standar Sistem Pengelolaan Lingkungan dan Sosial (lanjutan 2)', 'Petunjuk Pelaksanaan Struktur Tim Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana Nomor 7 Tahun 2025');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1138, 'juklak-7-2025', 105, 'lain', 'III. Bagian Kepatuhan terhadap Standar Sistem Pengelolaan Lingkungan dan Sosial (lanjutan 3)', NULL, 94, '3. Berdasarkan materi sebagaimana dimaksud angka 1 dan angka 2, terdapat … (…) permohonan yang diberikan rekomendasi hasil penelaahan, verifikasi, dan pertimbangan dengan jumlah anggaran senilai Rp……….,00 (dalam rupiah) (daftar kegiatan yang direkomendasikan sebagaimana terlampir).
4. Besaran penyaluran dan sebagaimana dimaksud angka 3 disesuaikan dengan ketersediaan anggaran yang ditetapkan Kementerian Keuangan dan mekanisme penyalurannya sepenuhnya menjadi kewenangan Kementerian Keuangan.
Demikian kami sampaikan. Atas perhatian dan kerja samanya diucapkan terima kasih.
Kepala Badan Nasional Penanggulangan Bencana, Letjen TNI Dr. Suharyanto, S.Sos., MM.
Tembusan:
1. Menteri Perencanaan Pembangunan/Badan Perencanaan Pembangunan Nasional
2. Menteri Dalam Negeri
3. Menteri Koordinator Bidang Pembangunan Manusia dan Kebudayaan
4. Menteri/Kepala Lembaga selaku Executing Agency
5. Menteri/Gubernur/Walikota/Bupati selaku Pemohon (daftar terlampir) BADAN NASIONAL PENANGGULANGAN BENCANA Lampiran 1 Surat Nomor : …………………………… Tanggal : …………………………… DAFTAR PEMOHON YANG DIBERIKAN REKOMENDASI Kementerian/Lembaga
1. Direktur Jenderal Sumber Daya Air, Kementerian Pekerjaan Umum (contoh)
2. …………….
Pemerintah Daerah
1. Bupati Konawe Selatan (contoh)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1138, '3. Berdasarkan materi sebagaimana dimaksud angka 1 dan angka 2, terdapat … (…) permohonan yang diberikan rekomendasi hasil penelaahan, verifikasi, dan pertimbangan dengan jumlah anggaran senilai Rp……….,00 (dalam rupiah) (daftar kegiatan yang direkomendasikan sebagaimana terlampir).
4. Besaran penyaluran dan sebagaimana dimaksud angka 3 disesuaikan dengan ketersediaan anggaran yang ditetapkan Kementerian Keuangan dan mekanisme penyalurannya sepenuhnya menjadi kewenangan Kementerian Keuangan.
Demikian kami sampaikan. Atas perhatian dan kerja samanya diucapkan terima kasih.
Kepala Badan Nasional Penanggulangan Bencana, Letjen TNI Dr. Suharyanto, S.Sos., MM.
