INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1141, 'juklak-7-2026', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMENUHAN STANDAR PELAYANAN MINIMAL SUB-URUSAN BENCANA DAERAH KABUPATEN/KOTA UNTUK SUBKEGIATAN PELAYANAN KOMUNIKASI, INFORMASI DAN EDUKASI RAWAN BENCANA NOMOR 7 TAHUN 2026');
