INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1142, 'juklak-7-2026', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Setiap Warga Negara Indonesia berhak untuk mendapatkan perlindungan dan rasa aman dari ancaman bencana. Hal ini telah menjadi amanat dari Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Pemerintah dan pemerintah daerah bertanggung jawab dalam penyelenggaraan penanggulangan bencana, yang merupakan bagian tidak terpisahkan dari urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1142, 'PENDAHULUAN A. Latar Belakang Setiap Warga Negara Indonesia berhak untuk mendapatkan perlindungan dan rasa aman dari ancaman bencana. Hal ini telah menjadi amanat dari Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Pemerintah dan pemerintah daerah bertanggung jawab dalam penyelenggaraan penanggulangan bencana, yang merupakan bagian tidak terpisahkan dari urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar.', 'BAB I', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1143, 'juklak-7-2026', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Pelaksanaan Standar Pelayanan Minimal Sub-Urusan Bencana dilaksanakan oleh Pemerintah Daerah, salah satunya Standar Pelayanan Minimal Sub-Urusan Bencana untuk subkegiatan pelayanan komunikasi, informasi dan edukasi rawan bencana. Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana ini sangat penting untuk mendukung peningkatan kapasitas warga negara agar dapat mengetahui risiko bencana yang dihadapi dan mengambil langkah-langkah yang perlu dilakukan untuk mengurangi risiko. Pelayanan komunikasi, informasi dan edukasi rawan bencana adalah pelayanan informasi tentang bagian wilayah kabupaten/kota yang rawan bencana yang disampaikan pemerintah daerah kepada warga negara yang berada di kawasan rawan bencana dan warga negara yang berpotensi terpapar bencana. Pemerintah daerah memastikan komunikasi, informasi dan edukasi dapat diakses oleh semua pihak tanpa terkecuali dan berpartisipasi penuh untuk mempromosikan komunikasi, informasi dan edukasi. Informasi yang disampaikan juga mencakup karakteristik ancaman bencana dan dampak perubahan iklim serta cara-cara untuk mengurangi risiko yang dapat ditimbulkan oleh ancaman tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1143, 'Pelaksanaan Standar Pelayanan Minimal Sub-Urusan Bencana dilaksanakan oleh Pemerintah Daerah, salah satunya Standar Pelayanan Minimal Sub-Urusan Bencana untuk subkegiatan pelayanan komunikasi, informasi dan edukasi rawan bencana. Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana ini sangat penting untuk mendukung peningkatan kapasitas warga negara agar dapat mengetahui risiko bencana yang dihadapi dan mengambil langkah-langkah yang perlu dilakukan untuk mengurangi risiko. Pelayanan komunikasi, informasi dan edukasi rawan bencana adalah pelayanan informasi tentang bagian wilayah kabupaten/kota yang rawan bencana yang disampaikan pemerintah daerah kepada warga negara yang berada di kawasan rawan bencana dan warga negara yang berpotensi terpapar bencana. Pemerintah daerah memastikan komunikasi, informasi dan edukasi dapat diakses oleh semua pihak tanpa terkecuali dan berpartisipasi penuh untuk mempromosikan komunikasi, informasi dan edukasi. Informasi yang disampaikan juga mencakup karakteristik ancaman bencana dan dampak perubahan iklim serta cara-cara untuk mengurangi risiko yang dapat ditimbulkan oleh ancaman tersebut.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1144, 'juklak-7-2026', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 1, 'Pelayanan komunikasi, informasi dan edukasi diberikan sesuai jenis ancaman bencana prioritas yang ada di kabupaten/kota, antara lain gempa bumi, tsunami, banjir, tanah longsor, letusan gunung api, gelombang laut ekstrem, angin topan (termasuk siklon tropis, puting beliung), kekeringan, kebakaran hutan dan lahan, dan epidemi/wabah penyakit/zoonosis prioritas (seperti rabies, antraks, leptospirosis, brucellosis, flu burung, dan sebagainya.).
Dalam hal pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana, Badan Nasional Penanggulangan Bencana bertugas memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana. Berkaitan dengan penerapan Standar Pelayanan Minimal Sub-Urusan Bencana, Badan Nasional Penanggulangan Bencana bertanggung jawab untuk memberikan pedoman dan pengarahan, menetapkan standarisasi serta melakukan perumusan dan penetapan norma, standar, prosedur, kriteria. Hal ini merupakan upaya sinergi dengan kementerian/lembaga yang membidangi urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar serta upaya melakukan pembinaan secara teknis terhadap penerapan Standar Pelayanan Minimal di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1144, 'Pelayanan komunikasi, informasi dan edukasi diberikan sesuai jenis ancaman bencana prioritas yang ada di kabupaten/kota, antara lain gempa bumi, tsunami, banjir, tanah longsor, letusan gunung api, gelombang laut ekstrem, angin topan (termasuk siklon tropis, puting beliung), kekeringan, kebakaran hutan dan lahan, dan epidemi/wabah penyakit/zoonosis prioritas (seperti rabies, antraks, leptospirosis, brucellosis, flu burung, dan sebagainya.).
Dalam hal pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana, Badan Nasional Penanggulangan Bencana bertugas memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana. Berkaitan dengan penerapan Standar Pelayanan Minimal Sub-Urusan Bencana, Badan Nasional Penanggulangan Bencana bertanggung jawab untuk memberikan pedoman dan pengarahan, menetapkan standarisasi serta melakukan perumusan dan penetapan norma, standar, prosedur, kriteria. Hal ini merupakan upaya sinergi dengan kementerian/lembaga yang membidangi urusan pemerintahan wajib yang berkaitan dengan pelayanan dasar serta upaya melakukan pembinaan secara teknis terhadap penerapan Standar Pelayanan Minimal di daerah.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1145, 'juklak-7-2026', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, 'Sebagai upaya pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana untuk sub-kegiatan komunikasi, informasi dan edukasi rawan bencana di daerah, Badan Nasional Penanggulangan Bencana perlu menyusun Petunjuk Pelaksanaan untuk membantu daerah dalam memenuhi mutu pelayanan dasar, khususnya dalam pelaksanaan pelayanan komunikasi, informasi dan edukasi rawan bencana. Dengan adanya Petunjuk Pelaksanaan ini diharapkan upaya penerapan Standar Pelayanan Minimal Sub-Urusan Bencana dapat terlaksana dengan lebih terarah, terkoordinasi dan sesuai dengan mutu dan sasaran yang telah ditetapkan.
Berdasarkan pertimbangan sebagaimana disebutkan di atas, perlu menyusun dan menetapkan Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Sub-Kegiatan Komunikasi, Informasi dan Edukasi Rawan Bencana.
B. Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini dimaksudkan sebagai acuan dan arahan dalam upaya memberikan kejelasan tahapan dan prosedur pelaksanaan pelayanan dasar SPM SUB yang berhak diperoleh setiap warga negara secara minimal.
2. Tujuan Tujuan Petunjuk Pelaksanaan ini adalah menyediakan tahapan dan prosedur penerapan pelayanan Komunikasi, Informasi dan Edukasi Rawan Bencana.
C. Ruang Lingkup Ruang lingkup pelaksanaan pelayanan Komunikasi, Informasi dan Edukasi Rawan Bencana sebagai berikut.
a. Prosedur Pelayanan Komunikasi, Informasi dan Edukasi Rawan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1145, 'Sebagai upaya pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana untuk sub-kegiatan komunikasi, informasi dan edukasi rawan bencana di daerah, Badan Nasional Penanggulangan Bencana perlu menyusun Petunjuk Pelaksanaan untuk membantu daerah dalam memenuhi mutu pelayanan dasar, khususnya dalam pelaksanaan pelayanan komunikasi, informasi dan edukasi rawan bencana. Dengan adanya Petunjuk Pelaksanaan ini diharapkan upaya penerapan Standar Pelayanan Minimal Sub-Urusan Bencana dapat terlaksana dengan lebih terarah, terkoordinasi dan sesuai dengan mutu dan sasaran yang telah ditetapkan.
Berdasarkan pertimbangan sebagaimana disebutkan di atas, perlu menyusun dan menetapkan Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Sub-Kegiatan Komunikasi, Informasi dan Edukasi Rawan Bencana.
B. Maksud dan Tujuan
1. Maksud Petunjuk Pelaksanaan ini dimaksudkan sebagai acuan dan arahan dalam upaya memberikan kejelasan tahapan dan prosedur pelaksanaan pelayanan dasar SPM SUB yang berhak diperoleh setiap warga negara secara minimal.
2. Tujuan Tujuan Petunjuk Pelaksanaan ini adalah menyediakan tahapan dan prosedur penerapan pelayanan Komunikasi, Informasi dan Edukasi Rawan Bencana.
C. Ruang Lingkup Ruang lingkup pelaksanaan pelayanan Komunikasi, Informasi dan Edukasi Rawan Bencana sebagai berikut.
a. Prosedur Pelayanan Komunikasi, Informasi dan Edukasi Rawan Bencana.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1146, 'juklak-7-2026', 6, 'lain', 'BAB I (lanjutan 4)', NULL, 2, 'b. Sosialisasi Tatap Muka Bagian ini membahas prosedur dan langkah-langkah terperinci dalam mempersiapkan pelaksanaan kegiatan sosialisasi tatap muka, mulai dari perencanaan, penyiapan personel penyelenggara, tempat dan peralatan, pembuatan bahan sosialisasi yang dapat diakses oleh semua, dan pelaksanaan sosialisasi oleh narasumber atau petugas penyuluh sampai dengan pemantauan, evaluasi dan pelaporan pelaksanaan sosialisasi.
c. Sosialisasi Melalui Media Sosial dan Wahana Multimedia Bagian ini menguraikan prosedur dan langkah-langkah tahap demi tahap dalam mempersiapkan pelaksanaan kegiatan sosialisasi melalui media sosial dan wahana multimedia yang dapat diakses dan inklusif, mulai dari perencanaan, identifikasi profil pengguna media sosial dan wahana multimedia, penyiapan personel penyelenggara, pembuatan materi-materi sosial media dan berbagai wahana multimedia yang relevan berdasarkan preferensi warga negara sasaran sosialisasi, pengunggahan (upload) bahan-bahan sosialisasi yang telah dibuat dan pemantauan, evaluasi serta pelaporan pelaksanaannya.
d. Penyediaan dan Pemasangan Rambu Evakuasi dan Papan Informasi Publik Bagian ini menguraikan prosedur dalam penyediaan dan pemasangan rambu evakuasi dan papan informasi publik.
D. Pengertian
1. Pelayanan Dasar adalah pelayanan publik untuk memenuhi kebutuhan dasar Warga Negara yang terkena dampak di kawasan rawan bencana dan yang menjadi korban bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1146, 'b. Sosialisasi Tatap Muka Bagian ini membahas prosedur dan langkah-langkah terperinci dalam mempersiapkan pelaksanaan kegiatan sosialisasi tatap muka, mulai dari perencanaan, penyiapan personel penyelenggara, tempat dan peralatan, pembuatan bahan sosialisasi yang dapat diakses oleh semua, dan pelaksanaan sosialisasi oleh narasumber atau petugas penyuluh sampai dengan pemantauan, evaluasi dan pelaporan pelaksanaan sosialisasi.
c. Sosialisasi Melalui Media Sosial dan Wahana Multimedia Bagian ini menguraikan prosedur dan langkah-langkah tahap demi tahap dalam mempersiapkan pelaksanaan kegiatan sosialisasi melalui media sosial dan wahana multimedia yang dapat diakses dan inklusif, mulai dari perencanaan, identifikasi profil pengguna media sosial dan wahana multimedia, penyiapan personel penyelenggara, pembuatan materi-materi sosial media dan berbagai wahana multimedia yang relevan berdasarkan preferensi warga negara sasaran sosialisasi, pengunggahan (upload) bahan-bahan sosialisasi yang telah dibuat dan pemantauan, evaluasi serta pelaporan pelaksanaannya.
d. Penyediaan dan Pemasangan Rambu Evakuasi dan Papan Informasi Publik Bagian ini menguraikan prosedur dalam penyediaan dan pemasangan rambu evakuasi dan papan informasi publik.
D. Pengertian
1. Pelayanan Dasar adalah pelayanan publik untuk memenuhi kebutuhan dasar Warga Negara yang terkena dampak di kawasan rawan bencana dan yang menjadi korban bencana.', 'BAB I (lanjutan 4)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1147, 'juklak-7-2026', 7, 'lain', 'BAB I (lanjutan 5)', NULL, 3, '2. Standar Pelayanan Minimal yang selanjutnya disingkat SPM adalah ketentuan mengenai jenis dan mutu pelayanan dasar yang merupakan urusan pemerintahan wajib yang berhak diperoleh setiap Warga Negara secara minimal.
3. Standar Teknis adalah standar jumlah dan kualitas barang dan/atau jasa, sumber daya manusia dan petunjuk teknis atau tata cara pemenuhan standar.
4. Jenis Pelayanan Dasar adalah jenis pelayanan dalam rangka penyediaan barang dan/atau jasa kebutuhan dasar yang berhak diperoleh oleh setiap Warga Negara secara minimal.
5. Mutu Pelayanan Dasar adalah ukuran kuantitas dan kualitas barang dan/atau jasa kebutuhan dasar serta pemenuhannya secara minimal dalam pelayanan dasar sesuai dengan standar teknis agar hidup secara layak.
6. Komunikasi adalah penyampaian pesan secara langsung atau tidak langsung melalui saluran komunikasi kepada penerima pesan untuk mendapatkan tanggapan.
7. Informasi adalah keterangan, pernyataan, atau gagasan yang mengandung nilai, makna, dan pesan, yang dapat dilihat, didengar, dan dibaca, yang dapat disajikan dalam berbagai kemasan dan format.
8. Edukasi adalah segala keadaan, hal, peristiwa atau kegiatan yang mendorong terjadinya penambahan pengetahuan, perubahan sikap, perilaku dan keterampilan seseorang atau kelompok orang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1147, '2. Standar Pelayanan Minimal yang selanjutnya disingkat SPM adalah ketentuan mengenai jenis dan mutu pelayanan dasar yang merupakan urusan pemerintahan wajib yang berhak diperoleh setiap Warga Negara secara minimal.
3. Standar Teknis adalah standar jumlah dan kualitas barang dan/atau jasa, sumber daya manusia dan petunjuk teknis atau tata cara pemenuhan standar.
4. Jenis Pelayanan Dasar adalah jenis pelayanan dalam rangka penyediaan barang dan/atau jasa kebutuhan dasar yang berhak diperoleh oleh setiap Warga Negara secara minimal.
5. Mutu Pelayanan Dasar adalah ukuran kuantitas dan kualitas barang dan/atau jasa kebutuhan dasar serta pemenuhannya secara minimal dalam pelayanan dasar sesuai dengan standar teknis agar hidup secara layak.
6. Komunikasi adalah penyampaian pesan secara langsung atau tidak langsung melalui saluran komunikasi kepada penerima pesan untuk mendapatkan tanggapan.
7. Informasi adalah keterangan, pernyataan, atau gagasan yang mengandung nilai, makna, dan pesan, yang dapat dilihat, didengar, dan dibaca, yang dapat disajikan dalam berbagai kemasan dan format.
8. Edukasi adalah segala keadaan, hal, peristiwa atau kegiatan yang mendorong terjadinya penambahan pengetahuan, perubahan sikap, perilaku dan keterampilan seseorang atau kelompok orang.', 'BAB I (lanjutan 5)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1148, 'juklak-7-2026', 8, 'lain', 'BAB I (lanjutan 6)', NULL, 3, '9. Papan Informasi Bencana yang selanjutnya disebut Papan Informasi adalah media yang digunakan untuk memberikan informasi mengenai ancaman bencana atau kawasan rawan Bencana, serta hal-hal yang perlu dilakukan untuk mengantisipasi ancaman bencana.
10. Rambu Bencana yang selanjutnya disebut Rambu adalah keterangan yang ditempatkan atau dipasang di kawasan rawan Bencana, berupa lambang, huruf, angka, dan/atau frasa, yang berfungsi untuk menjelaskan atau memberi petunjuk, peringatan, dan larangan bagi setiap orang yang berada di kawasan rawan Bencana.
11. Sosialisasi Penanggulangan Bencana adalah upaya atau serangkaian upaya penyampaian informasi, yang bertujuan untuk mengenal ancaman bencana, meningkatkan kesadaran, dan pembentukan sikap serta perilaku sehingga mempersiapkan masyarakat dalam menghadapi ancaman bencana.
12. Kelompok Rentan adalah bayi, anak usia di bawah lima tahun, anak-anak, ibu hamil atau menyusui, penyandang disabilitas dan orang lanjut usia.
13. Warga Negara Indonesia, yang selanjutnya disebut Warga Negara adalah orang bangsa Indonesia asli dan orang bangsa lain yang disahkan sesuai dengan ketentuan peraturan perundang-undangan.
14. Forum Pengurangan Risiko Bencana yang selanjutnya disingkat FPRB adalah wadah yang menyatukan unsur organisasi pemangku kepentingan di tingkat provinsi, kabupaten/kota, Desa dan Kelurahan untuk mendukung upaya pengurangan risiko bencana terutama melalui koordinasi antarpihak dan perencanaan kebijakan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1148, '9. Papan Informasi Bencana yang selanjutnya disebut Papan Informasi adalah media yang digunakan untuk memberikan informasi mengenai ancaman bencana atau kawasan rawan Bencana, serta hal-hal yang perlu dilakukan untuk mengantisipasi ancaman bencana.
10. Rambu Bencana yang selanjutnya disebut Rambu adalah keterangan yang ditempatkan atau dipasang di kawasan rawan Bencana, berupa lambang, huruf, angka, dan/atau frasa, yang berfungsi untuk menjelaskan atau memberi petunjuk, peringatan, dan larangan bagi setiap orang yang berada di kawasan rawan Bencana.
11. Sosialisasi Penanggulangan Bencana adalah upaya atau serangkaian upaya penyampaian informasi, yang bertujuan untuk mengenal ancaman bencana, meningkatkan kesadaran, dan pembentukan sikap serta perilaku sehingga mempersiapkan masyarakat dalam menghadapi ancaman bencana.
12. Kelompok Rentan adalah bayi, anak usia di bawah lima tahun, anak-anak, ibu hamil atau menyusui, penyandang disabilitas dan orang lanjut usia.
13. Warga Negara Indonesia, yang selanjutnya disebut Warga Negara adalah orang bangsa Indonesia asli dan orang bangsa lain yang disahkan sesuai dengan ketentuan peraturan perundang-undangan.
14. Forum Pengurangan Risiko Bencana yang selanjutnya disingkat FPRB adalah wadah yang menyatukan unsur organisasi pemangku kepentingan di tingkat provinsi, kabupaten/kota, Desa dan Kelurahan untuk mendukung upaya pengurangan risiko bencana terutama melalui koordinasi antarpihak dan perencanaan kebijakan.', 'BAB I (lanjutan 6)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1149, 'juklak-7-2026', 9, 'lain', 'BAB I (lanjutan 7)', NULL, 4, '15. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintahan nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
16. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah perangkat daerah yang menyelenggarakan suburusan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1149, '15. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintahan nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
16. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah perangkat daerah yang menyelenggarakan suburusan bencana.', 'BAB I (lanjutan 7)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1150, 'juklak-7-2026', 10, 'lain', 'BAB II', NULL, 5, 'PELAKSANAAN PELAYANAN KOMUNIKASI, INFORMASI, DAN EDUKASI RAWAN BENCANA A. Sosialisasi Tatap Muka
1. Perencanaan Umum Berikut langkah-langkah untuk menyusun rencana umum program Komunikasi, Informasi, dan Edukasi Rawan Bencana yang sistematis dan terukur:
a. Membentuk Tim Komunikasi, Informasi, dan Edukasi Kepala BPBD membentuk tim yang beranggotakan 2-3 aparatur yang biasa menangani urusan komunikasi, humas, data dan informasi. Tim terdiri atas aparatur BPBD yang kompeten dalam bidang komunikasi dan hubungan masyarakat dan/atau aparatur perangkat daerah lain yang memiliki tugas dan fungsi bidang komunikasi atau pemberdayaan masyarakat, dan/atau pihak lembaga nonpemerintah yang memiliki program Komunikasi, Informasi, dan Edukasi. Tugas Tim yakni menyusun rencana umum program Komunikasi, Informasi, dan Edukasi untuk sosialisasi dan edukasi rawan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1150, 'PELAKSANAAN PELAYANAN KOMUNIKASI, INFORMASI, DAN EDUKASI RAWAN BENCANA A. Sosialisasi Tatap Muka
1. Perencanaan Umum Berikut langkah-langkah untuk menyusun rencana umum program Komunikasi, Informasi, dan Edukasi Rawan Bencana yang sistematis dan terukur:
a. Membentuk Tim Komunikasi, Informasi, dan Edukasi Kepala BPBD membentuk tim yang beranggotakan 2-3 aparatur yang biasa menangani urusan komunikasi, humas, data dan informasi. Tim terdiri atas aparatur BPBD yang kompeten dalam bidang komunikasi dan hubungan masyarakat dan/atau aparatur perangkat daerah lain yang memiliki tugas dan fungsi bidang komunikasi atau pemberdayaan masyarakat, dan/atau pihak lembaga nonpemerintah yang memiliki program Komunikasi, Informasi, dan Edukasi. Tugas Tim yakni menyusun rencana umum program Komunikasi, Informasi, dan Edukasi untuk sosialisasi dan edukasi rawan bencana.', 'BAB II', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1151, 'juklak-7-2026', 11, 'lain', 'BAB II (lanjutan 1)', NULL, 5, 'b. Penyusunan Rencana Umum Komunikasi, Informasi, dan Edukasi Tim mengadakan pertemuan sebanyak 2-3 kali atau sesuai kebutuhan untuk menyusun Rencana Umum Komunikasi, Informasi, dan Edukasi yang berisi kegiatan pembuatan dan penyebarluasan materi rawan bencana untuk jangka menengah dan pendek (3-5 tahun). Rencana Umum Komunikasi, Informasi, dan Edukasi dapat digunakan sebagai acuan dalam penyusunan program dan kegiatan Komunikasi, Informasi, dan Edukasi di dalam Rencana Pembangunan Jangka Menengah Daerah, Rencana Kerja Perangkat Daerah atau Rencana Strategis Perangkat Daerah dan penghitungan anggaran yang dibutuhkan dalam Anggaran Pendapatan dan Belanja Daerah.
Rencana umum program Komunikasi, Informasi, dan Edukasi disusun dengan mempertimbangkan:
1) Kajian jenis ancaman/multi-ancaman yang akan menjadi prioritas pelaksanaan Komunikasi, Informasi, dan Edukasi dalam 3-5 tahun ke depan (prioritas kawasan dengan risiko tertinggi dan potensi dampak terbesar berdasarkan Indeks Risiko Bencana Indonesia, Kajian Risiko Bencana, Rencana Penanggulangan Bencana, Rencana Kontingensi, kajian kerentanan dan risiko iklim, atau dokumen resmi lainnya dan prioritas waktu pelaksanaan.
2) Kajian karakteristik warga negara yang tinggal di kawasan berisiko tinggi dan preferensi jenis media yang digunakan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1151, 'b. Penyusunan Rencana Umum Komunikasi, Informasi, dan Edukasi Tim mengadakan pertemuan sebanyak 2-3 kali atau sesuai kebutuhan untuk menyusun Rencana Umum Komunikasi, Informasi, dan Edukasi yang berisi kegiatan pembuatan dan penyebarluasan materi rawan bencana untuk jangka menengah dan pendek (3-5 tahun). Rencana Umum Komunikasi, Informasi, dan Edukasi dapat digunakan sebagai acuan dalam penyusunan program dan kegiatan Komunikasi, Informasi, dan Edukasi di dalam Rencana Pembangunan Jangka Menengah Daerah, Rencana Kerja Perangkat Daerah atau Rencana Strategis Perangkat Daerah dan penghitungan anggaran yang dibutuhkan dalam Anggaran Pendapatan dan Belanja Daerah.
Rencana umum program Komunikasi, Informasi, dan Edukasi disusun dengan mempertimbangkan:
1) Kajian jenis ancaman/multi-ancaman yang akan menjadi prioritas pelaksanaan Komunikasi, Informasi, dan Edukasi dalam 3-5 tahun ke depan (prioritas kawasan dengan risiko tertinggi dan potensi dampak terbesar berdasarkan Indeks Risiko Bencana Indonesia, Kajian Risiko Bencana, Rencana Penanggulangan Bencana, Rencana Kontingensi, kajian kerentanan dan risiko iklim, atau dokumen resmi lainnya dan prioritas waktu pelaksanaan.
2) Kajian karakteristik warga negara yang tinggal di kawasan berisiko tinggi dan preferensi jenis media yang digunakan.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1152, 'juklak-7-2026', 12, 'lain', 'BAB II (lanjutan 2)', NULL, 5, 'Profil warga negara yang akan menjadi sasaran program Komunikasi, Informasi, dan Edukasi akan menentukan jenis kegiatan Komunikasi, Informasi, dan Edukasi yang dipilih, media yang digunakan dan strategi Komunikasi, Informasi, dan Edukasi untuk menjangkau warga yang dituju.
3) Kajian ketersediaan sumber daya manusia dan anggaran, serta tambahan jenis dan jumlah sumber daya manusia yang harus dipenuhi. Pertimbangkan juga potensi pelibatan perangkat daerah lain, FPRB, Sekolah Lapang Iklim, fasilitator dan pendamping desa, dan pihak lainnya untuk menentukan kegiatan Komunikasi, Informasi, dan Edukasi yang bisa dilaksanakan secara bersama dengan mitra pendukung, misalkan sosialisasi atau edukasi melalui program Satuan Pendidikan Aman Bencana dari Dinas Pendidikan.
4) Penentuan kawasan prioritas, yakni kecamatan dan desa/kelurahan mana yang akan menjadi prioritas Komunikasi, Informasi, dan Edukasi pada tahun pertama, kedua, ketiga, dan seterusnya. Rencana umum program Komunikasi, Informasi, dan Edukasi perlu menetapkan juga desa/kelurahan atau kecamatan yang akan mendapat program Komunikasi, Informasi, dan Edukasi dan berapa persen warga di daerah tersebut yang akan dijangkau melalui sosialisasi tatap muka, sosialisasi melalui media sosial dan wahana multimedia serta perkiraan waktu pelaksanaan kegiatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1152, 'Profil warga negara yang akan menjadi sasaran program Komunikasi, Informasi, dan Edukasi akan menentukan jenis kegiatan Komunikasi, Informasi, dan Edukasi yang dipilih, media yang digunakan dan strategi Komunikasi, Informasi, dan Edukasi untuk menjangkau warga yang dituju.
3) Kajian ketersediaan sumber daya manusia dan anggaran, serta tambahan jenis dan jumlah sumber daya manusia yang harus dipenuhi. Pertimbangkan juga potensi pelibatan perangkat daerah lain, FPRB, Sekolah Lapang Iklim, fasilitator dan pendamping desa, dan pihak lainnya untuk menentukan kegiatan Komunikasi, Informasi, dan Edukasi yang bisa dilaksanakan secara bersama dengan mitra pendukung, misalkan sosialisasi atau edukasi melalui program Satuan Pendidikan Aman Bencana dari Dinas Pendidikan.
4) Penentuan kawasan prioritas, yakni kecamatan dan desa/kelurahan mana yang akan menjadi prioritas Komunikasi, Informasi, dan Edukasi pada tahun pertama, kedua, ketiga, dan seterusnya. Rencana umum program Komunikasi, Informasi, dan Edukasi perlu menetapkan juga desa/kelurahan atau kecamatan yang akan mendapat program Komunikasi, Informasi, dan Edukasi dan berapa persen warga di daerah tersebut yang akan dijangkau melalui sosialisasi tatap muka, sosialisasi melalui media sosial dan wahana multimedia serta perkiraan waktu pelaksanaan kegiatan.', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1153, 'juklak-7-2026', 13, 'lain', 'BAB II (lanjutan 3)', NULL, 6, '5) Rencana umum Komunikasi, Informasi, dan Edukasi dapat mempertimbangkan kalender kegiatan seperti Hari Kesiapsiagaan Bencana pada 26 April, hari Pengurangan Risiko Bencana Internasional pada 13 Oktober atau bulan Pengurangan Risiko Bencana Nasional pada Oktober, atau peringatan kejadian bencana besar seperti gempa dan tsunami Aceh pada 26 Desember, peringatan Letusan Gunung Tambora pada 11 April, atau hari seperti hari Lingkungan Hidup Nasional pada 10 Januari.
6) Penentuan program, bentuk, jumlah kegiatan sosialisasi yang akan dilaksanakan dan sumber daya yang dibutuhkan termasuk materi sosialisasi (bahan tayang, poster, brosur, film pendek, program TV, program radio, tulisan di koran dan majalah, dan sebagainya), kebutuhan personel, dan kebutuhan anggaran.
7) Penyusunan Rencana umum Komunikasi, Informasi, dan Edukasi dapat memperhatikan contoh Rencana umum Komunikasi, Informasi, dan Edukasi sesuai Format-1 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
c. Persiapan Sosialisasi Tatap Muka 1) Penyusunan Kerangka Acuan Kegiatan Tim Komunikasi, Informasi, dan Edukasi menyusun Kerangka Acuan Kegiatan Sosialisasi Tatap Muka.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1153, '5) Rencana umum Komunikasi, Informasi, dan Edukasi dapat mempertimbangkan kalender kegiatan seperti Hari Kesiapsiagaan Bencana pada 26 April, hari Pengurangan Risiko Bencana Internasional pada 13 Oktober atau bulan Pengurangan Risiko Bencana Nasional pada Oktober, atau peringatan kejadian bencana besar seperti gempa dan tsunami Aceh pada 26 Desember, peringatan Letusan Gunung Tambora pada 11 April, atau hari seperti hari Lingkungan Hidup Nasional pada 10 Januari.
6) Penentuan program, bentuk, jumlah kegiatan sosialisasi yang akan dilaksanakan dan sumber daya yang dibutuhkan termasuk materi sosialisasi (bahan tayang, poster, brosur, film pendek, program TV, program radio, tulisan di koran dan majalah, dan sebagainya), kebutuhan personel, dan kebutuhan anggaran.
7) Penyusunan Rencana umum Komunikasi, Informasi, dan Edukasi dapat memperhatikan contoh Rencana umum Komunikasi, Informasi, dan Edukasi sesuai Format-1 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
c. Persiapan Sosialisasi Tatap Muka 1) Penyusunan Kerangka Acuan Kegiatan Tim Komunikasi, Informasi, dan Edukasi menyusun Kerangka Acuan Kegiatan Sosialisasi Tatap Muka.', 'BAB II (lanjutan 3)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1154, 'juklak-7-2026', 14, 'lain', 'BAB II (lanjutan 4)', NULL, 6, 'Kerangka Acuan Kegiatan berisi tentang hal sebagai berikut. a) Latar belakang Memuat hal yang dibutuhkan, kegiatan apa yang akan dilaksanakan dan siapa penanggung jawab dan pelaksana. b) Maksud dan Tujuan Memuat maksud dan tujuan kegiatan, termasuk keluaran dan hasil yang akan dicapai. c) Tim Komunikasi, Informasi, dan Edukasi Memuat uraian organisasi pelaksana Komunikasi, Informasi, dan Edukasi sesuai kebutuhan dan sektor teknis yang diperlukan. d) Penentuan daerah rawan bencana Memuat penetapan kecamatan, desa/kelurahan atau dusun yang akan menjadi daerah prioritas sosialisasi tatap muka. Prioritas daerah sosialisasi ialah desa/kelurahan atau dusun yang berisiko tinggi dengan frekuensi ancaman kejadian tinggi dan memiliki banyak warga dengan tingkat risiko tinggi yang tidak dapat dijangkau melalui media lain.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1154, 'Kerangka Acuan Kegiatan berisi tentang hal sebagai berikut. a) Latar belakang Memuat hal yang dibutuhkan, kegiatan apa yang akan dilaksanakan dan siapa penanggung jawab dan pelaksana. b) Maksud dan Tujuan Memuat maksud dan tujuan kegiatan, termasuk keluaran dan hasil yang akan dicapai. c) Tim Komunikasi, Informasi, dan Edukasi Memuat uraian organisasi pelaksana Komunikasi, Informasi, dan Edukasi sesuai kebutuhan dan sektor teknis yang diperlukan. d) Penentuan daerah rawan bencana Memuat penetapan kecamatan, desa/kelurahan atau dusun yang akan menjadi daerah prioritas sosialisasi tatap muka. Prioritas daerah sosialisasi ialah desa/kelurahan atau dusun yang berisiko tinggi dengan frekuensi ancaman kejadian tinggi dan memiliki banyak warga dengan tingkat risiko tinggi yang tidak dapat dijangkau melalui media lain.', 'BAB II (lanjutan 4)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1155, 'juklak-7-2026', 15, 'lain', 'BAB II (lanjutan 5)', NULL, 7, 'Penentuan daerah prioritas dapat melibatkan aparat desa/kelurahan, tokoh masyarakat, tokoh agama, organisasi pemuda, aparat kecamatan dan perangkat daerah lain. e) Penerima manfaat Apabila telah ditetapkan daerah prioritas sosialisasi tatap muka, Tim menentukan warga negara di dusun/kampung/rukun warga/rukun tetangga yang menjadi sasaran. strategi untuk mencapai hasil yang efektif dan efisien. f) Waktu pelaksanaan kegiatan Sosialisasi tatap muka tidak hanya dilakukan pada saat prabencana tapi juga pada saat tanggap darurat bencana dan pascabencana. Pemilihan waktu untuk melaksanakan sosialisasi. Sosialisasi setidaknya dilakukan dua kali setahun di kabupaten/kota yang memiliki risiko tinggi dan sekali setahun di kabupaten/kota dengan risiko sedang. g) Penentuan durasi sosialisasi Penentuan durasi sosialisasi memperhatikan kelompok umur, ragam profesi, dan faktor-faktor lainnya termasuk karakteristik wilayah. h) Tempat pelaksanaan kegiatan Pemilihan tempat pelaksanaan kegiatan memperhatikan hal-hal sebagai berikut: aksebilitas, kenyamanan dan keamanan, kesesuaian dengan konteks dan kebutuhan kelompok sasaran, kesesuaian fasilitas serta ketersediaan sumber daya. i) Perkiraan kebutuhan anggaran.
2) Pengajuan anggaran Kerangka Acuan Kegiatan yang telah disetujui oleh pimpinan, diajukan untuk mendapatkan penganggaran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1155, 'Penentuan daerah prioritas dapat melibatkan aparat desa/kelurahan, tokoh masyarakat, tokoh agama, organisasi pemuda, aparat kecamatan dan perangkat daerah lain. e) Penerima manfaat Apabila telah ditetapkan daerah prioritas sosialisasi tatap muka, Tim menentukan warga negara di dusun/kampung/rukun warga/rukun tetangga yang menjadi sasaran. strategi untuk mencapai hasil yang efektif dan efisien. f) Waktu pelaksanaan kegiatan Sosialisasi tatap muka tidak hanya dilakukan pada saat prabencana tapi juga pada saat tanggap darurat bencana dan pascabencana. Pemilihan waktu untuk melaksanakan sosialisasi. Sosialisasi setidaknya dilakukan dua kali setahun di kabupaten/kota yang memiliki risiko tinggi dan sekali setahun di kabupaten/kota dengan risiko sedang. g) Penentuan durasi sosialisasi Penentuan durasi sosialisasi memperhatikan kelompok umur, ragam profesi, dan faktor-faktor lainnya termasuk karakteristik wilayah. h) Tempat pelaksanaan kegiatan Pemilihan tempat pelaksanaan kegiatan memperhatikan hal-hal sebagai berikut: aksebilitas, kenyamanan dan keamanan, kesesuaian dengan konteks dan kebutuhan kelompok sasaran, kesesuaian fasilitas serta ketersediaan sumber daya. i) Perkiraan kebutuhan anggaran.
2) Pengajuan anggaran Kerangka Acuan Kegiatan yang telah disetujui oleh pimpinan, diajukan untuk mendapatkan penganggaran.', 'BAB II (lanjutan 5)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1156, 'juklak-7-2026', 16, 'lain', 'BAB II (lanjutan 6)', NULL, 7, 'Sebagai alternatif dalam pendanaan kegiatan, pelaksanaan sosialisasi dapat dilakukan dengan berkolaborasi dengan perusahaan swasta, lembaga-lembaga kebencanaan, lembaga nonpemerintah, anggaran pemerintah desa, pihak ketiga, dan lain-lain.
3) Pengumpulan data penerima manfaat Tim mengumpulkan data jumlah dan profil warga negara secara terpilah berdasarkan jenis kelamin, kelompok umur, dan jenis disabilitas yang disandang (bila ada), serta sebaran geografis atau sebaran domisili warga negara. Dapat berupa data by name by address agar kegiatan Komunikasi, Informasi, dan Edukasi dapat tepat sasaran. Data ini dapat diperoleh dari perangkat daerah yang memiliki tugas dan fungsi bidang kependudukan dan pencatatan sipil, pemberdayaan masyarakat dan desa, sosial, Badan Pusat Statistik Daerah, atau perangkat daerah terkait lainnya.
Pengkajian profil dan karakteristik warga dapat memanfaatkan informasi dari orang-orang yang mengenal dusun dan desa rawan bencana atau informasi dari Lurah/Kepala Desa atau Kepala Dusun bersangkutan atau data dan informasi yang ada di kantor Kecamatan dan Desa/Kelurahan. Profil warga dapat berupa informasi tentang rata-rata tingkat pendidikan, pekerjaan, cara dan alat yang digunakan warga dalam berkomunikasi, dll. sesuai kebutuhan. Data ini dapat digunakan juga dalam menentukan sasaran sosialisasi melalui media daring dan wahana multimedia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1156, 'Sebagai alternatif dalam pendanaan kegiatan, pelaksanaan sosialisasi dapat dilakukan dengan berkolaborasi dengan perusahaan swasta, lembaga-lembaga kebencanaan, lembaga nonpemerintah, anggaran pemerintah desa, pihak ketiga, dan lain-lain.
3) Pengumpulan data penerima manfaat Tim mengumpulkan data jumlah dan profil warga negara secara terpilah berdasarkan jenis kelamin, kelompok umur, dan jenis disabilitas yang disandang (bila ada), serta sebaran geografis atau sebaran domisili warga negara. Dapat berupa data by name by address agar kegiatan Komunikasi, Informasi, dan Edukasi dapat tepat sasaran. Data ini dapat diperoleh dari perangkat daerah yang memiliki tugas dan fungsi bidang kependudukan dan pencatatan sipil, pemberdayaan masyarakat dan desa, sosial, Badan Pusat Statistik Daerah, atau perangkat daerah terkait lainnya.
Pengkajian profil dan karakteristik warga dapat memanfaatkan informasi dari orang-orang yang mengenal dusun dan desa rawan bencana atau informasi dari Lurah/Kepala Desa atau Kepala Dusun bersangkutan atau data dan informasi yang ada di kantor Kecamatan dan Desa/Kelurahan. Profil warga dapat berupa informasi tentang rata-rata tingkat pendidikan, pekerjaan, cara dan alat yang digunakan warga dalam berkomunikasi, dll. sesuai kebutuhan. Data ini dapat digunakan juga dalam menentukan sasaran sosialisasi melalui media daring dan wahana multimedia.', 'BAB II (lanjutan 6)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1157, 'juklak-7-2026', 17, 'lain', 'BAB II (lanjutan 7)', NULL, 8, '4) Penyiapan personel penyelenggara sosialisasi Tim Komunikasi, Informasi, dan Edukasi menyiapkan personel penyelenggara sosialisasi, yang terdiri dari narasumber, pembuat materi sosialisasi, dan personel pendukung kegiatan. Narasumber sosialisasi tatap muka adalah pejabat BPBD atau perangkat daerah lain yang menguasai hal yang akan disosialisasikan atau telah berpengalaman dan pernah mendapatkan pelatihan dalam isu terkait. Narasumber dapat juga menggunakan perwakilan FPRB/Adaptasi Perubahan Iklim, atau organisasi lain yang memiliki kompetensi yang sesuai.
Pembuat materi sosialisasi adalah aparatur yang memiliki kompetensi terkait materi yang akan disosialisasikan.
5) Penyediaan tempat sosialisasi Tim Komunikasi, Informasi, dan Edukasi menetapkan tempat sosialisasi tatap muka akan dilaksanakan. Tempat yang dapat digunakan antara lain kantor BPBD atau kantor perangkat daerah lain, kantor pemerintah desa/kelurahan atau kecamatan, balai dusun/kampung, sekolah, kampus, kantor FPRB atau lembaga swadaya masyarakat, atau tempat lain yang mudah dijangkau dan akses bagi penyandang disabilitas oleh warga masyarakat target sosialisasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1157, '4) Penyiapan personel penyelenggara sosialisasi Tim Komunikasi, Informasi, dan Edukasi menyiapkan personel penyelenggara sosialisasi, yang terdiri dari narasumber, pembuat materi sosialisasi, dan personel pendukung kegiatan. Narasumber sosialisasi tatap muka adalah pejabat BPBD atau perangkat daerah lain yang menguasai hal yang akan disosialisasikan atau telah berpengalaman dan pernah mendapatkan pelatihan dalam isu terkait. Narasumber dapat juga menggunakan perwakilan FPRB/Adaptasi Perubahan Iklim, atau organisasi lain yang memiliki kompetensi yang sesuai.
Pembuat materi sosialisasi adalah aparatur yang memiliki kompetensi terkait materi yang akan disosialisasikan.
5) Penyediaan tempat sosialisasi Tim Komunikasi, Informasi, dan Edukasi menetapkan tempat sosialisasi tatap muka akan dilaksanakan. Tempat yang dapat digunakan antara lain kantor BPBD atau kantor perangkat daerah lain, kantor pemerintah desa/kelurahan atau kecamatan, balai dusun/kampung, sekolah, kampus, kantor FPRB atau lembaga swadaya masyarakat, atau tempat lain yang mudah dijangkau dan akses bagi penyandang disabilitas oleh warga masyarakat target sosialisasi.', 'BAB II (lanjutan 7)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1158, 'juklak-7-2026', 18, 'lain', 'BAB II (lanjutan 8)', NULL, 8, '6) Koordinasi dengan pihak lain terkait penyelenggaraan sosialisasi Tim Komunikasi, Informasi, dan Edukasi melakukan pertemuan dengan perangkat desa/kelurahan/ kecamatan, satuan pendidikan, FPRB, lembaga keagamaan, lembaga kemasyarakatan/adat, lembaga swadaya masyarakat, atau organisasi untuk bekerja sama dan menyepakati pembagian tanggung jawab dalam penyelenggaraan sosialisasi.
7) Penyediaan Bahan Sosialisasi Tim Komunikasi, Informasi, dan Edukasi perlu mempersiapkan bahan atau materi sosialisasi tatap muka, baik dengan membuat sendiri ataupun memanfaatkan materi yang sudah disusun oleh BPBD kabupaten/kota atau instansi/organisasi lain, menyesuaikannya dengan konteks setempat. Panduan untuk membuat materi atau konten sosialisasi dalam rangka Komunikasi, Informasi, dan Edukasi Rawan Bencana mengacu pada Pedoman Sosialisasi Penanggulangan Bencana Nomor 3 Tahun 2024.
Dalam sosialisasi tatap muka, pesan atau informasi dapat disampaikan melalui ceramah narasumber atau presentasi salindia (powerpoint), pembagian poster, brosur atau materi cetak lain oleh narasumber. Pesan atau informasi bersifat adaptif dan inklusif. Agar lebih menarik, presentasi dapat dilengkapi dengan konten infografik, foto dan video. Pesan kunci yang disampaikan adalah tentang risiko bencana dan upaya meningkatkan kesiapsiagaan warga dalam menghadapi kedaruratan bencana dan mengambil langkah yang tepat untuk mengurangi risiko sesuai jenis ancaman yang ada di daerah mereka.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1158, '6) Koordinasi dengan pihak lain terkait penyelenggaraan sosialisasi Tim Komunikasi, Informasi, dan Edukasi melakukan pertemuan dengan perangkat desa/kelurahan/ kecamatan, satuan pendidikan, FPRB, lembaga keagamaan, lembaga kemasyarakatan/adat, lembaga swadaya masyarakat, atau organisasi untuk bekerja sama dan menyepakati pembagian tanggung jawab dalam penyelenggaraan sosialisasi.
7) Penyediaan Bahan Sosialisasi Tim Komunikasi, Informasi, dan Edukasi perlu mempersiapkan bahan atau materi sosialisasi tatap muka, baik dengan membuat sendiri ataupun memanfaatkan materi yang sudah disusun oleh BPBD kabupaten/kota atau instansi/organisasi lain, menyesuaikannya dengan konteks setempat. Panduan untuk membuat materi atau konten sosialisasi dalam rangka Komunikasi, Informasi, dan Edukasi Rawan Bencana mengacu pada Pedoman Sosialisasi Penanggulangan Bencana Nomor 3 Tahun 2024.
Dalam sosialisasi tatap muka, pesan atau informasi dapat disampaikan melalui ceramah narasumber atau presentasi salindia (powerpoint), pembagian poster, brosur atau materi cetak lain oleh narasumber. Pesan atau informasi bersifat adaptif dan inklusif. Agar lebih menarik, presentasi dapat dilengkapi dengan konten infografik, foto dan video. Pesan kunci yang disampaikan adalah tentang risiko bencana dan upaya meningkatkan kesiapsiagaan warga dalam menghadapi kedaruratan bencana dan mengambil langkah yang tepat untuk mengurangi risiko sesuai jenis ancaman yang ada di daerah mereka.', 'BAB II (lanjutan 8)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1159, 'juklak-7-2026', 19, 'lain', 'BAB II (lanjutan 9)', NULL, 9, 'Isi pesan harus menggunakan bahasa yang nonteknis. a) Materi sosialisasi tentang prabencana paling sedikit memuat informasi sebagai berikut.
(1) Pengenalan risiko: karakteristik ancaman bencana yang dihadapi daerah, yakni jenis ancaman, lokasi spesifik di desa, dusun atau kampung yang paling berisiko, bentuk spesifik risiko seperti apa dan mengancam apa saja potensi ancaman terhadap (jiwa, ternak, rumah, harta benda dan sumber penghidupan), kemungkinan kejadian bencana, intensitas, potensi dampak, tanda-tanda sebelum kejadian, hal penting lainnya. dll.
(2) Cara memantau ancaman, pengenalan sistem peringatan dini yang ada, bagaimana harus merespons cara merespon pesan peringatan dini.
(3) Cara mengurangi risiko sebelum bencana terjadi.
(4) Langkah kesiapsiagaan yang perlu diambil untuk menghadapi kedaruratan bencana.
(5) Memahami rambu dan jalur evakuasi untuk akses bagi kelompok berisiko serta tempat evakuasi penyelamatan diri yang aman.
(6) Cara menyelamatkan diri bila terjadi bencana. b) Materi sosialisasi tentang kondisi kedaruratan bencana setidaknya memuat informasi berikut:
(1) Kemungkinan adanya kejadian bencana sekunder/susulan;
(2) Cara mengurangi risiko bencana susulan;
(3) Cara menjaga kesehatan dan keamanan di tempat penampungan sementara;
(4) Cara mendapatkan bantuan sandang dan pangan, medis, dan psikososial bila tersedia, dan informasi terkait lainnya sesuai konteks setempat;
(5) Cara mengakses alat mobilitas bagi Kelompok Rentan; dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1159, 'Isi pesan harus menggunakan bahasa yang nonteknis. a) Materi sosialisasi tentang prabencana paling sedikit memuat informasi sebagai berikut.
(1) Pengenalan risiko: karakteristik ancaman bencana yang dihadapi daerah, yakni jenis ancaman, lokasi spesifik di desa, dusun atau kampung yang paling berisiko, bentuk spesifik risiko seperti apa dan mengancam apa saja potensi ancaman terhadap (jiwa, ternak, rumah, harta benda dan sumber penghidupan), kemungkinan kejadian bencana, intensitas, potensi dampak, tanda-tanda sebelum kejadian, hal penting lainnya. dll.
(2) Cara memantau ancaman, pengenalan sistem peringatan dini yang ada, bagaimana harus merespons cara merespon pesan peringatan dini.
(3) Cara mengurangi risiko sebelum bencana terjadi.
(4) Langkah kesiapsiagaan yang perlu diambil untuk menghadapi kedaruratan bencana.
(5) Memahami rambu dan jalur evakuasi untuk akses bagi kelompok berisiko serta tempat evakuasi penyelamatan diri yang aman.
(6) Cara menyelamatkan diri bila terjadi bencana. b) Materi sosialisasi tentang kondisi kedaruratan bencana setidaknya memuat informasi berikut:
(1) Kemungkinan adanya kejadian bencana sekunder/susulan;
(2) Cara mengurangi risiko bencana susulan;
(3) Cara menjaga kesehatan dan keamanan di tempat penampungan sementara;
(4) Cara mendapatkan bantuan sandang dan pangan, medis, dan psikososial bila tersedia, dan informasi terkait lainnya sesuai konteks setempat;
(5) Cara mengakses alat mobilitas bagi Kelompok Rentan; dan', 'BAB II (lanjutan 9)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1160, 'juklak-7-2026', 20, 'lain', 'BAB II (lanjutan 10)', NULL, 10, '(6) Cara mengakses layanan pendidikan darurat bagi anak usia sekolah. c) Materi sosialisasi tentang pascabencana setidaknya memuat informasi berikut:
(1) Proses rehabilitasi dan rekonstruksi.
(2) Cara mengakses dukungan pemulihan perumahan.
(3) Cara mengakses dukungan pemulihan mata pencaharian.
(4) Cara mengakses layanan psikososial dan penyembuhan trauma terutama bagi Kelompok Rentan.
(5) Cara mengakses layanan kesehatan bagi warga yang sakit termasuk Kelompok Rentan, dan juga penyandang disabilitas akibat bencana.
(6) Cara membangun kembali pascabencana dengan lebih baik dan aman sesuai konteks setempat.
2. Pelaksanaan Sosialisasi Tatap Muka
a. Persiapan Sarana-Prasarana Tim Komunikasi, Informasi, dan Edukasi perlu memeriksa kembali kesiapan sarana-prasarana yang mungkin dibutuhkan sebelum hari pelaksanaan sosialisasi tatap muka, hal yang perlu diperiksa antara lain:
1) ruangan atau aula tempat sosialisasi dengan akses bagi penyandang disabilitas;
2) bangku dan meja;
3) buku saku atau leaflet informasi risiko yang dapat dibagikan;
4) alat tulis-menulis;
5) mikrofon, pengeras suara dan peralatan audio-visual;
6) komputer/laptop dan LCD sesuai kebutuhan;
7) konsumsi peserta bila dibutuhkan; dan 8) penyebaran undangan yang mudah diakses kepada calon peserta sosialisasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1160, '(6) Cara mengakses layanan pendidikan darurat bagi anak usia sekolah. c) Materi sosialisasi tentang pascabencana setidaknya memuat informasi berikut:
(1) Proses rehabilitasi dan rekonstruksi.
(2) Cara mengakses dukungan pemulihan perumahan.
(3) Cara mengakses dukungan pemulihan mata pencaharian.
(4) Cara mengakses layanan psikososial dan penyembuhan trauma terutama bagi Kelompok Rentan.
(5) Cara mengakses layanan kesehatan bagi warga yang sakit termasuk Kelompok Rentan, dan juga penyandang disabilitas akibat bencana.
(6) Cara membangun kembali pascabencana dengan lebih baik dan aman sesuai konteks setempat.
2. Pelaksanaan Sosialisasi Tatap Muka
a. Persiapan Sarana-Prasarana Tim Komunikasi, Informasi, dan Edukasi perlu memeriksa kembali kesiapan sarana-prasarana yang mungkin dibutuhkan sebelum hari pelaksanaan sosialisasi tatap muka, hal yang perlu diperiksa antara lain:
1) ruangan atau aula tempat sosialisasi dengan akses bagi penyandang disabilitas;
2) bangku dan meja;
3) buku saku atau leaflet informasi risiko yang dapat dibagikan;
4) alat tulis-menulis;
5) mikrofon, pengeras suara dan peralatan audio-visual;
6) komputer/laptop dan LCD sesuai kebutuhan;
7) konsumsi peserta bila dibutuhkan; dan 8) penyebaran undangan yang mudah diakses kepada calon peserta sosialisasi.', 'BAB II (lanjutan 10)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1161, 'juklak-7-2026', 21, 'lain', 'BAB II (lanjutan 11)', NULL, 10, 'b. Penyampaian Sosialisasi Tatap Muka oleh Narasumber Penyampaian materi sosialisasi perlu disesuaikan dengan profil masyarakat setempat dan menggunakan bahasa yang mudah dipahami oleh peserta. Sebagai contoh, apabila sasaran sosialisasi merupakan warga negara lanjut usia, narasumber sebaiknya menggunakan bahasa Indonesia baku atau menggunakan bahasa daerah setempat. Contoh lain: apabila sasaran sosialisasi berprofesi sebagai nelayan, narasumber sebaiknya menggunakan contoh atau perumpamaan yang sesuai dengan profesi nelayan. Penyampaian pesan sebaiknya dilakukan lebih dalam bentuk dialog interaktif daripada ceramah atau penyuluhan satu arah saja.
Beberapa hal yang perlu dipastikan dalam penyampaian sosialisasi:
1) Disampaikan oleh fasilitator dan narasumber yang kompeten dan telah berpengalaman dalam isu kebencanaan, dampak perubahan iklim, gender dan disabilitas. Dalam penyampaian sosialisasi tatap muka ini perlu juga melibatkan juru bicara isyarat apabila peserta sosialisasi adalah para penyandang disabilitas.
2) Bisa menggunakan berbagai bentuk sosialisasi seperti penyuluhan, presentasi dan tanya-jawab, diskusi, kegiatan kesenian, pemutaran film, kegiatan olahraga, kegiatan keagamaan atau bentuk lainnya sesuai yang telah ditentukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1161, 'b. Penyampaian Sosialisasi Tatap Muka oleh Narasumber Penyampaian materi sosialisasi perlu disesuaikan dengan profil masyarakat setempat dan menggunakan bahasa yang mudah dipahami oleh peserta. Sebagai contoh, apabila sasaran sosialisasi merupakan warga negara lanjut usia, narasumber sebaiknya menggunakan bahasa Indonesia baku atau menggunakan bahasa daerah setempat. Contoh lain: apabila sasaran sosialisasi berprofesi sebagai nelayan, narasumber sebaiknya menggunakan contoh atau perumpamaan yang sesuai dengan profesi nelayan. Penyampaian pesan sebaiknya dilakukan lebih dalam bentuk dialog interaktif daripada ceramah atau penyuluhan satu arah saja.
Beberapa hal yang perlu dipastikan dalam penyampaian sosialisasi:
1) Disampaikan oleh fasilitator dan narasumber yang kompeten dan telah berpengalaman dalam isu kebencanaan, dampak perubahan iklim, gender dan disabilitas. Dalam penyampaian sosialisasi tatap muka ini perlu juga melibatkan juru bicara isyarat apabila peserta sosialisasi adalah para penyandang disabilitas.
2) Bisa menggunakan berbagai bentuk sosialisasi seperti penyuluhan, presentasi dan tanya-jawab, diskusi, kegiatan kesenian, pemutaran film, kegiatan olahraga, kegiatan keagamaan atau bentuk lainnya sesuai yang telah ditentukan.', 'BAB II (lanjutan 11)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1162, 'juklak-7-2026', 22, 'lain', 'BAB II (lanjutan 12)', NULL, 11, '3) Sosialisasi dapat dilakukan juga dengan menyediakan narasumber atau fasilitator BPBD untuk menyampaikan materi kebencanaan melalui program Satuan Pendidikan Aman Bencana, program Desa Tangguh Bencana, Program Komunitas Iklim, Sekolah Lapang Iklim, Kampung Siaga Bencana, Sekolah Sungai, Sekolah Gunung, Sekolah Pantai/Pesisir, program kesehatan melalui fasilitas kesehatan, program pemberdayaan masyarakat, penyuluhan pertanian, dan lainnya yang sesuai.
c. Sosialisasi tatap muka oleh lembaga/instansi lain Lembaga/instansi lain dapat melakukan sosialisasi tatap muka sebagai upaya pengurangan risiko bencana. Dalam pelaksanaan sosialisasi tatap muka oleh lembaga/instansi lain ini perlu berkoordinasi dengan BPBD agar substansi sosialisasi terkait kebencanaan dapat sesuai dengan dokumen kajian risiko bencana dan kaidah penerapan Standar Pelayanan Minimal Sub Urusan Bencana.
3. Pemantauan dan evaluasi sosialisasi tatap muka Pemantauan dan evaluasi perlu dilakukan untuk menilai keberhasilan sosialisasi tatap muka. Beberapa aspek yang perlu dipantau dan dievaluasi adalah sebagai berikut.
a. Jumlah kegiatan sosialisasi tatap muka yang dilakukan.
b. Jumlah peserta secara terpilah berdasarkan jenis kelamin, umur dan ragam disabilitas di setiap kegiatan sosialisasi dan jumlah total peserta yang hadir dalam seluruh sosialisasi.
c. Kesesuaian narasumber dan fasilitator.
d. Kesesuaian materi yang disampaikan.
e. Umpan balik dari peserta.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1162, '3) Sosialisasi dapat dilakukan juga dengan menyediakan narasumber atau fasilitator BPBD untuk menyampaikan materi kebencanaan melalui program Satuan Pendidikan Aman Bencana, program Desa Tangguh Bencana, Program Komunitas Iklim, Sekolah Lapang Iklim, Kampung Siaga Bencana, Sekolah Sungai, Sekolah Gunung, Sekolah Pantai/Pesisir, program kesehatan melalui fasilitas kesehatan, program pemberdayaan masyarakat, penyuluhan pertanian, dan lainnya yang sesuai.
c. Sosialisasi tatap muka oleh lembaga/instansi lain Lembaga/instansi lain dapat melakukan sosialisasi tatap muka sebagai upaya pengurangan risiko bencana. Dalam pelaksanaan sosialisasi tatap muka oleh lembaga/instansi lain ini perlu berkoordinasi dengan BPBD agar substansi sosialisasi terkait kebencanaan dapat sesuai dengan dokumen kajian risiko bencana dan kaidah penerapan Standar Pelayanan Minimal Sub Urusan Bencana.
3. Pemantauan dan evaluasi sosialisasi tatap muka Pemantauan dan evaluasi perlu dilakukan untuk menilai keberhasilan sosialisasi tatap muka. Beberapa aspek yang perlu dipantau dan dievaluasi adalah sebagai berikut.
a. Jumlah kegiatan sosialisasi tatap muka yang dilakukan.
b. Jumlah peserta secara terpilah berdasarkan jenis kelamin, umur dan ragam disabilitas di setiap kegiatan sosialisasi dan jumlah total peserta yang hadir dalam seluruh sosialisasi.
c. Kesesuaian narasumber dan fasilitator.
d. Kesesuaian materi yang disampaikan.
e. Umpan balik dari peserta.', 'BAB II (lanjutan 12)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1163, 'juklak-7-2026', 23, 'lain', 'BAB II (lanjutan 13)', NULL, 11, 'B. Sosialisasi melalui Media Sosial dan Wahana Multimedia
1. Perencanaan Sosialisasi melalui Media Sosial dan Wahana Multimedia
a. Penyusunan Kerangka Acuan Kegiatan Tim Komunikasi, Informasi, dan Edukasi menyusun Kerangka Acuan Kegiatan berisi tentang:
1) latar belakang (latar belakang permasalahan, apa yang dibutuhkan dalam hal Komunikasi, Informasi, dan Edukasi, kegiatan apa yang akan dilaksanakan dan siapa penanggung jawab dan pelaksana);
2) maksud dan tujuan (termasuk keluaran dan hasil yang akan dicapai);
3) penerima manfaat (warga negara spesifik yang akan menjadi sasaran);
4) tim sosialisasi media sosial dan wahana multimedia.
5) strategi untuk mencapai hasil yang efektif dan efisien;
6) media apa yang akan digunakan untuk menyasar warga negara spesifik tertentu, bila ada kelompok khusus yang ingin disasar;
7) saluran apa yang akan digunakan; dan 8) sumber daya manusia yang akan dilibatkan dan perkiraan kebutuhan anggaran.
b. Pengajuan anggaran Kerangka Acuan Kegiatan yang telah disetujui oleh pimpinan, diajukan untuk mendapatkan penganggaran. Sebagai alternatif dalam pendanaan kegiatan, pelaksanaan sosialisasi dapat dilakukan dengan berkolaborasi dengan perusahaan swasta, lembaga kebencanaan, lembaga nonpemerintah, anggaran pemerintah desa, pihak ketiga, dan lain-lain.
2. Persiapan Media Sosial dan Wahana Multimedia');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1163, 'B. Sosialisasi melalui Media Sosial dan Wahana Multimedia
1. Perencanaan Sosialisasi melalui Media Sosial dan Wahana Multimedia
a. Penyusunan Kerangka Acuan Kegiatan Tim Komunikasi, Informasi, dan Edukasi menyusun Kerangka Acuan Kegiatan berisi tentang:
1) latar belakang (latar belakang permasalahan, apa yang dibutuhkan dalam hal Komunikasi, Informasi, dan Edukasi, kegiatan apa yang akan dilaksanakan dan siapa penanggung jawab dan pelaksana);
2) maksud dan tujuan (termasuk keluaran dan hasil yang akan dicapai);
3) penerima manfaat (warga negara spesifik yang akan menjadi sasaran);
4) tim sosialisasi media sosial dan wahana multimedia.
5) strategi untuk mencapai hasil yang efektif dan efisien;
6) media apa yang akan digunakan untuk menyasar warga negara spesifik tertentu, bila ada kelompok khusus yang ingin disasar;
7) saluran apa yang akan digunakan; dan 8) sumber daya manusia yang akan dilibatkan dan perkiraan kebutuhan anggaran.
b. Pengajuan anggaran Kerangka Acuan Kegiatan yang telah disetujui oleh pimpinan, diajukan untuk mendapatkan penganggaran. Sebagai alternatif dalam pendanaan kegiatan, pelaksanaan sosialisasi dapat dilakukan dengan berkolaborasi dengan perusahaan swasta, lembaga kebencanaan, lembaga nonpemerintah, anggaran pemerintah desa, pihak ketiga, dan lain-lain.
2. Persiapan Media Sosial dan Wahana Multimedia', 'BAB II (lanjutan 13)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1164, 'juklak-7-2026', 24, 'lain', 'BAB II (lanjutan 14)', NULL, 12, 'a. Penyiapan personel pelaksana BPBD dapat menambah jumlah anggota Tim Komunikasi, Informasi, dan Edukasi yang memiliki kapasitas dalam memahami kebutuhan target yang berbeda. Penambahan anggota mendukung pelaksanaan sosialisasi melalui media sosial dan wahana multimedia. Tim dapat melibatkan perangkat daerah lain, FPRB, lembaga swadaya masyarakat, wartawan dan relawan/pekerja penanggulangan bencana yang biasa melaksanakan sosialisasi atau edukasi kebencanaan dan memiliki pengetahuan, kompetensi dan pengalaman dalam bidang manajemen risiko bencana dan dampak perubahan iklim, komunikasi dan edukasi masyarakat, pengembangan media sosial dan pembuatan materi/konten audio visual.
Tim Komunikasi, Informasi, dan Edukasi ditetapkan dalam keputusan Kepala BPBD. Tim dapat terdiri dari:
1) Tim analis atau perencanaan Komunikasi, Informasi, dan Edukasi bertugas: a) menganalisis karakteristik spesifik warga masyarakat sasaran dan pilihan mereka dalam menggunakan media komunikasi; b) menentukan media yang akan digunakan untuk sosialisasi; dan c) merancang program dan kegiatan sosialisasi media sosial dan wahana multimedia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1164, 'a. Penyiapan personel pelaksana BPBD dapat menambah jumlah anggota Tim Komunikasi, Informasi, dan Edukasi yang memiliki kapasitas dalam memahami kebutuhan target yang berbeda. Penambahan anggota mendukung pelaksanaan sosialisasi melalui media sosial dan wahana multimedia. Tim dapat melibatkan perangkat daerah lain, FPRB, lembaga swadaya masyarakat, wartawan dan relawan/pekerja penanggulangan bencana yang biasa melaksanakan sosialisasi atau edukasi kebencanaan dan memiliki pengetahuan, kompetensi dan pengalaman dalam bidang manajemen risiko bencana dan dampak perubahan iklim, komunikasi dan edukasi masyarakat, pengembangan media sosial dan pembuatan materi/konten audio visual.
Tim Komunikasi, Informasi, dan Edukasi ditetapkan dalam keputusan Kepala BPBD. Tim dapat terdiri dari:
1) Tim analis atau perencanaan Komunikasi, Informasi, dan Edukasi bertugas: a) menganalisis karakteristik spesifik warga masyarakat sasaran dan pilihan mereka dalam menggunakan media komunikasi; b) menentukan media yang akan digunakan untuk sosialisasi; dan c) merancang program dan kegiatan sosialisasi media sosial dan wahana multimedia.', 'BAB II (lanjutan 14)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1165, 'juklak-7-2026', 25, 'lain', 'BAB II (lanjutan 15)', NULL, 12, '2) Tim pembuat konten Komunikasi, Informasi, dan Edukasi terdiri dari personel yang kompeten dan berpengalaman atau telah mendapatkan pelatihan penyusunan materi tulis, pembuatan konten digital, penguasaan perangkat lunak (software) dan perangkat keras (hardware), pembuatan materi audio-visual, dan desain grafis yang adaptif. Tim bertugas untuk: a) mengidentifikasi materi yang dibutuhkan dan ketersediaan sumber materi yang dibutuhkan baik dari BNPB, BPBD kabupaten/kota, atau kementerian/lembaga teknis atau organisasi non pemerintah; b) mencari materi secara fisik maupun daring di perpustakaan maupun melalui media internet dan mencari tahu terkait hak cipta atas materi yang akan digunakan; c) meminta izin apabila akan menggunakan materi yang berasal dari kementerian/lembaga/organisasi lain; d) membuat materi sosialisasi media sosial dan wahana multimedia; e) mencari dan melibatkan narasumber, pembuat konten (content creator), dukungan personel teknologi informasi dari perangkat daerah terkait komunikasi-informasi, dan perangkat daerah lainnya. Bantuan juga dapat diperoleh dari relawan FPRB atau dunia usaha; dan f) mendukung pembuatan konten cetak dan digital terkait informasi kebencanaan yang dapat berbentuk teks untuk siaran pers atau artikel untuk koran/majalah, infografis untuk brosur dan poster, narasi singkat, foto, film pendek untuk diunggah di media sosial, rekaman siniar (podcast), dan lain-lain.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1165, '2) Tim pembuat konten Komunikasi, Informasi, dan Edukasi terdiri dari personel yang kompeten dan berpengalaman atau telah mendapatkan pelatihan penyusunan materi tulis, pembuatan konten digital, penguasaan perangkat lunak (software) dan perangkat keras (hardware), pembuatan materi audio-visual, dan desain grafis yang adaptif. Tim bertugas untuk: a) mengidentifikasi materi yang dibutuhkan dan ketersediaan sumber materi yang dibutuhkan baik dari BNPB, BPBD kabupaten/kota, atau kementerian/lembaga teknis atau organisasi non pemerintah; b) mencari materi secara fisik maupun daring di perpustakaan maupun melalui media internet dan mencari tahu terkait hak cipta atas materi yang akan digunakan; c) meminta izin apabila akan menggunakan materi yang berasal dari kementerian/lembaga/organisasi lain; d) membuat materi sosialisasi media sosial dan wahana multimedia; e) mencari dan melibatkan narasumber, pembuat konten (content creator), dukungan personel teknologi informasi dari perangkat daerah terkait komunikasi-informasi, dan perangkat daerah lainnya. Bantuan juga dapat diperoleh dari relawan FPRB atau dunia usaha; dan f) mendukung pembuatan konten cetak dan digital terkait informasi kebencanaan yang dapat berbentuk teks untuk siaran pers atau artikel untuk koran/majalah, infografis untuk brosur dan poster, narasi singkat, foto, film pendek untuk diunggah di media sosial, rekaman siniar (podcast), dan lain-lain.', 'BAB II (lanjutan 15)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1166, 'juklak-7-2026', 26, 'lain', 'BAB II (lanjutan 16)', NULL, 13, '3) Tim pengelola multimedia terdiri dari pegawai BPBD yang kompeten dan berpengalaman dalam pengembangan konten, pegawai pada dinas yang memiliki tugas dan fungsi bidang komunikasi dan informasi, atau perangkat daerah terkait lainnya, dan/atau relawan dari FPRB, lembaga swadaya masyarakat, wartawan, dan Pramuka yang merupakan digital native atau generasi yang sejak mulai belajar menulis/membaca, beraktivitas, dan berinteraksi sudah mengenal sekaligus memanfaatkan teknologi internet dan media sosial, sehingga piawai dalam membuat dan mengedit video, film pendek, animasi, dan lain-lain dan menyebarluaskannya di berbagai platform media sosial. Tim pengelola multimedia mempunyai tugas: a) menyebarluaskan materi sosialisasi ini melalui media sosial/digital (website, YouTube, Facebook, Instagram, Twitter/X, WhatsApp/WA, Telegram, TikTok, siniar), media cetak (koran, majalah, poster, brosur), media elektronik (radio, televisi) dan media luar ruangan (videotron, papan informasi publik, dan lain-lain); dan b) mengelola website, mengunggah konten dan menjadi admin akun media sosial yang digunakan dalam sosialisasi.
4) Tim pemantauan, evaluasi serta pelaporan bertugas memantau dan mengevaluasi sosialisasi dan edukasi kebencanaan melalui sosial media dan wahana multimedia.
5) Tim lain yang dibutuhkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1166, '3) Tim pengelola multimedia terdiri dari pegawai BPBD yang kompeten dan berpengalaman dalam pengembangan konten, pegawai pada dinas yang memiliki tugas dan fungsi bidang komunikasi dan informasi, atau perangkat daerah terkait lainnya, dan/atau relawan dari FPRB, lembaga swadaya masyarakat, wartawan, dan Pramuka yang merupakan digital native atau generasi yang sejak mulai belajar menulis/membaca, beraktivitas, dan berinteraksi sudah mengenal sekaligus memanfaatkan teknologi internet dan media sosial, sehingga piawai dalam membuat dan mengedit video, film pendek, animasi, dan lain-lain dan menyebarluaskannya di berbagai platform media sosial. Tim pengelola multimedia mempunyai tugas: a) menyebarluaskan materi sosialisasi ini melalui media sosial/digital (website, YouTube, Facebook, Instagram, Twitter/X, WhatsApp/WA, Telegram, TikTok, siniar), media cetak (koran, majalah, poster, brosur), media elektronik (radio, televisi) dan media luar ruangan (videotron, papan informasi publik, dan lain-lain); dan b) mengelola website, mengunggah konten dan menjadi admin akun media sosial yang digunakan dalam sosialisasi.
4) Tim pemantauan, evaluasi serta pelaporan bertugas memantau dan mengevaluasi sosialisasi dan edukasi kebencanaan melalui sosial media dan wahana multimedia.
5) Tim lain yang dibutuhkan.', 'BAB II (lanjutan 16)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1167, 'juklak-7-2026', 27, 'lain', 'BAB II (lanjutan 17)', NULL, 13, 'b. Penentuan sasaran penerima Tim analis dan perencanaan Komunikasi, Informasi, dan Edukasi menentukan warga negara di kawasan rawan bencana terpilih yang akan menjadi sasaran utama sosialisasi media sosial dan wahana multimedia. Tim mengumpulkan data jumlah dan profil warga masyarakat secara terpilah berdasarkan jenis kelamin, kelompok umur, pendidikan, pekerjaan dan jenis disabilitas yang disandang (apabila ada), serta sebaran geografis atau sebaran domisili di dusun/kampung dan desa/kelurahan mana saja, bila perlu by name by address, agar tim dapat menyebarluaskan materi sosialisasi ke tempat yang tepat. Data ini dapat diperoleh dari perangkat daerah yang memiliki tugas dan fungsi bidang sosial, kependudukan dan pencatatan sipil, pemberdayaan masyarakat dan desa, atau perangkat daerah terkait lainnya.
Pengkajian profil dan karakteristik warga dapat memanfaatkan informasi dari orang-orang yang mengenal dusun dan desa rawan bencana atau informasi dari Lurah/Kepala Desa atau Kepala Dusun bersangkutan atau data dan informasi yang ada di kantor kecamatan dan desa/kelurahan. Selain data terpilah tentang umur dan jenis kelamin, informasi berikut dapat berguna dalam memilih metode komunikasi yang paling tepat untuk digunakan, antara lain:
1) rata-rata tingkat pendidikan/tingkat literasi;
2) pekerjaan sebagian besar warga;
3) tingkat perekonomian warga;
4) cara dan alat yang digunakan dalam berkomunikasi;
5) tingkat kesehatan; dan 6) ragam disabilitas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1167, 'b. Penentuan sasaran penerima Tim analis dan perencanaan Komunikasi, Informasi, dan Edukasi menentukan warga negara di kawasan rawan bencana terpilih yang akan menjadi sasaran utama sosialisasi media sosial dan wahana multimedia. Tim mengumpulkan data jumlah dan profil warga masyarakat secara terpilah berdasarkan jenis kelamin, kelompok umur, pendidikan, pekerjaan dan jenis disabilitas yang disandang (apabila ada), serta sebaran geografis atau sebaran domisili di dusun/kampung dan desa/kelurahan mana saja, bila perlu by name by address, agar tim dapat menyebarluaskan materi sosialisasi ke tempat yang tepat. Data ini dapat diperoleh dari perangkat daerah yang memiliki tugas dan fungsi bidang sosial, kependudukan dan pencatatan sipil, pemberdayaan masyarakat dan desa, atau perangkat daerah terkait lainnya.
Pengkajian profil dan karakteristik warga dapat memanfaatkan informasi dari orang-orang yang mengenal dusun dan desa rawan bencana atau informasi dari Lurah/Kepala Desa atau Kepala Dusun bersangkutan atau data dan informasi yang ada di kantor kecamatan dan desa/kelurahan. Selain data terpilah tentang umur dan jenis kelamin, informasi berikut dapat berguna dalam memilih metode komunikasi yang paling tepat untuk digunakan, antara lain:
1) rata-rata tingkat pendidikan/tingkat literasi;
2) pekerjaan sebagian besar warga;
3) tingkat perekonomian warga;
4) cara dan alat yang digunakan dalam berkomunikasi;
5) tingkat kesehatan; dan 6) ragam disabilitas.', 'BAB II (lanjutan 17)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1168, 'juklak-7-2026', 28, 'lain', 'BAB II (lanjutan 18)', NULL, 14, 'c. Penentuan media yang akan digunakan untuk sosialisasi Tim analis dan perencanaan Komunikasi, Informasi, dan Edukasi menentukan jenis media yang akan digunakan untuk sosialisasi berdasarkan hal berikut.
1) Profil warga sasaran dan pilihan jenis media yang paling banyak digunakan (preferensi penggunaan jenis media).
2) Tujuan khusus sosialisasi yang ingin dicapai.
3) Pertimbangan metode dan jenis media yang paling efektif dan efisien untuk menyasar kelompok warga masyarakat yang dituju dengan karakteristik khas mereka dan inklusif.
4) Pertimbangan ketersediaan anggaran dan personel yang akan mengelola media komunikasi cetak dan digital.
5) Penetapan jenis media prioritas yang akan dibuat pertama dan berikutnya berdasarkan pertimbangan sebagaimana disebut di atas.
d. Pembuatan Materi Sosialisasi Media Sosial dan Wahana Multimedia Panduan untuk membuat materi atau konten sosialisasi dalam rangka Komunikasi, Informasi, dan Edukasi Rawan Bencana mengacu pada ketentuan peraturan perundang-undangan atau turunannya yang mengatur mengenai Sosialisasi Penanggulangan Bencana.
1) Materi sosialisasi dibuat oleh Tim pembuat konten Komunikasi, Informasi, dan Edukasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1168, 'c. Penentuan media yang akan digunakan untuk sosialisasi Tim analis dan perencanaan Komunikasi, Informasi, dan Edukasi menentukan jenis media yang akan digunakan untuk sosialisasi berdasarkan hal berikut.
1) Profil warga sasaran dan pilihan jenis media yang paling banyak digunakan (preferensi penggunaan jenis media).
2) Tujuan khusus sosialisasi yang ingin dicapai.
3) Pertimbangan metode dan jenis media yang paling efektif dan efisien untuk menyasar kelompok warga masyarakat yang dituju dengan karakteristik khas mereka dan inklusif.
4) Pertimbangan ketersediaan anggaran dan personel yang akan mengelola media komunikasi cetak dan digital.
5) Penetapan jenis media prioritas yang akan dibuat pertama dan berikutnya berdasarkan pertimbangan sebagaimana disebut di atas.
d. Pembuatan Materi Sosialisasi Media Sosial dan Wahana Multimedia Panduan untuk membuat materi atau konten sosialisasi dalam rangka Komunikasi, Informasi, dan Edukasi Rawan Bencana mengacu pada ketentuan peraturan perundang-undangan atau turunannya yang mengatur mengenai Sosialisasi Penanggulangan Bencana.
1) Materi sosialisasi dibuat oleh Tim pembuat konten Komunikasi, Informasi, dan Edukasi.', 'BAB II (lanjutan 18)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1169, 'juklak-7-2026', 29, 'lain', 'BAB II (lanjutan 19)', NULL, 14, '2) Tim dapat membuat materi yang baru sesuai konteks lokal, tentunya bila anggaran tersedia dan ada personel yang terampil dalam pengembangan materi tersebut. Tim pembuat konten juga melakukan pengembangan konten yaitu pemilihan multimedia, animasi, narasi (menarik atau sederhana), isi informasi dan kesesuaian dengan platform.
3) Materi ini dapat disampaikan ke warga oleh BPBD atau perangkat daerah ketika mereka melakukan kegiatan sosialisasi tatap muka, lewat media massa dan media sosial. Materi tersebut juga dapat dikutip narasinya atau dibuat infografis untuk bahan papan informasi publik dan rambu evakuasi.
4) Jumlah materi cetak dan digital yang akan dibuat harus mempertimbangkan jumlah ancaman dengan tingkat risiko tinggi yang ada, kebutuhan warga masyarakat yang akan disasar dan ketersediaan anggaran serta personel yang memiliki keahlian dan keterampilan yang dibutuhkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1169, '2) Tim dapat membuat materi yang baru sesuai konteks lokal, tentunya bila anggaran tersedia dan ada personel yang terampil dalam pengembangan materi tersebut. Tim pembuat konten juga melakukan pengembangan konten yaitu pemilihan multimedia, animasi, narasi (menarik atau sederhana), isi informasi dan kesesuaian dengan platform.
3) Materi ini dapat disampaikan ke warga oleh BPBD atau perangkat daerah ketika mereka melakukan kegiatan sosialisasi tatap muka, lewat media massa dan media sosial. Materi tersebut juga dapat dikutip narasinya atau dibuat infografis untuk bahan papan informasi publik dan rambu evakuasi.
4) Jumlah materi cetak dan digital yang akan dibuat harus mempertimbangkan jumlah ancaman dengan tingkat risiko tinggi yang ada, kebutuhan warga masyarakat yang akan disasar dan ketersediaan anggaran serta personel yang memiliki keahlian dan keterampilan yang dibutuhkan.', 'BAB II (lanjutan 19)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1170, 'juklak-7-2026', 30, 'lain', 'BAB II (lanjutan 20)', NULL, 15, 'e. Materi sosialisasi media sosial dan wahana multimedia 1) Prabencana, memuat informasi sebagai berikut. a) Pengenalan risiko, antara lain karakteristik ancaman bencana yang dihadapi daerah, yakni jenis ancaman, lokasi spesifik di desa, dusun atau kampung yang paling berisiko, bentuk spesifik risiko seperti apa dan mengancam apa saja (jiwa, ternak, rumah, harta benda), kemungkinan kejadian bencana, intensitas, potensi dampak, tanda-tanda sebelum kejadian, dll. b) Cara memantau ancaman, sistem peringatan dini yang ada, bagaimana harus merespons pesan peringatan dini. c) Cara mengurangi risiko sebelum terjadi bencana. d) Langkah kesiapsiagaan yang perlu diambil untuk menghadapi kedaruratan bencana. e) Memahami rambu dan jalur evakuasi serta tempat penyelamatan diri yang aman. f) Cara menyelamatkan diri bila terjadi bencana.
2) Kondisi darurat bencana, memuat informasi antara lain sebagai berikut. a) Kemungkinan adanya kejadian bencana sekunder/ susulan. b) Cara mengurangi risiko bencana susulan. c) Cara menjaga kesehatan dan keamanan di tempat penampungan sementara. d) Cara mengakses layanan pendidikan darurat bagi anak usia sekolah. e) Cara mendapatkan bantuan sandang dan pangan, medis, dan psikososial bila tersedia, dan informasi terkait lainnya sesuai konteks setempat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1170, 'e. Materi sosialisasi media sosial dan wahana multimedia 1) Prabencana, memuat informasi sebagai berikut. a) Pengenalan risiko, antara lain karakteristik ancaman bencana yang dihadapi daerah, yakni jenis ancaman, lokasi spesifik di desa, dusun atau kampung yang paling berisiko, bentuk spesifik risiko seperti apa dan mengancam apa saja (jiwa, ternak, rumah, harta benda), kemungkinan kejadian bencana, intensitas, potensi dampak, tanda-tanda sebelum kejadian, dll. b) Cara memantau ancaman, sistem peringatan dini yang ada, bagaimana harus merespons pesan peringatan dini. c) Cara mengurangi risiko sebelum terjadi bencana. d) Langkah kesiapsiagaan yang perlu diambil untuk menghadapi kedaruratan bencana. e) Memahami rambu dan jalur evakuasi serta tempat penyelamatan diri yang aman. f) Cara menyelamatkan diri bila terjadi bencana.
2) Kondisi darurat bencana, memuat informasi antara lain sebagai berikut. a) Kemungkinan adanya kejadian bencana sekunder/ susulan. b) Cara mengurangi risiko bencana susulan. c) Cara menjaga kesehatan dan keamanan di tempat penampungan sementara. d) Cara mengakses layanan pendidikan darurat bagi anak usia sekolah. e) Cara mendapatkan bantuan sandang dan pangan, medis, dan psikososial bila tersedia, dan informasi terkait lainnya sesuai konteks setempat.', 'BAB II (lanjutan 20)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1171, 'juklak-7-2026', 31, 'lain', 'BAB II (lanjutan 21)', NULL, 15, '3) Pascabencana memuat informasi sebagai berikut. a) Proses rehabilitasi dan rekonstruksi. b) Cara mengakses dukungan pemulihan perumahan. c) Cara mengakses dukungan pemulihan mata pencaharian. d) Cara mengakses layanan psikososial dan penyembuhan trauma terutama bagi warga yang rentan. e) Cara mengakses layanan kesehatan bagi warga yang sakit termasuk para penyandang disabilitas akibat bencana. f) Bagaimana membangun kembali dengan lebih baik dan aman, dan informasi terkait lainnya sesuai konteks setempat.
f. Informasi yang ada dalam materi sosialisasi melalui media sosial dan wahana multimedia sama dengan yang digunakan dalam sosialisasi tatap muka, tetapi perlu dipecah-pecah dalam bentuk informasi singkat-padat, adaptif dan inklusif yang dibuat menjadi film pendek, animasi pendek, presentasi salindia (powerpoint) pendek, pesan audio singkat, dll. yang dapat didiseminasikan melalui platform media daring atau elektronik. Materi yang sedikit panjang dapat didiseminasikan sebagai artikel di surat kabar atau majalah, program radio atau televisi, atau siniar yang diunggah secara daring. Selain itu konten untuk media sosial yang dapat diamplifikasi melalui banyak media sosial, misalkan satu konten dapat disebarluaskan melalui Instagram, Twitter/X, Facebook, WhatsApp, Youtube, dan lain-lain.
g. Jenis media yang dikembangkan Jenis media yang dapat dikembangkan antara lain:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1171, '3) Pascabencana memuat informasi sebagai berikut. a) Proses rehabilitasi dan rekonstruksi. b) Cara mengakses dukungan pemulihan perumahan. c) Cara mengakses dukungan pemulihan mata pencaharian. d) Cara mengakses layanan psikososial dan penyembuhan trauma terutama bagi warga yang rentan. e) Cara mengakses layanan kesehatan bagi warga yang sakit termasuk para penyandang disabilitas akibat bencana. f) Bagaimana membangun kembali dengan lebih baik dan aman, dan informasi terkait lainnya sesuai konteks setempat.
f. Informasi yang ada dalam materi sosialisasi melalui media sosial dan wahana multimedia sama dengan yang digunakan dalam sosialisasi tatap muka, tetapi perlu dipecah-pecah dalam bentuk informasi singkat-padat, adaptif dan inklusif yang dibuat menjadi film pendek, animasi pendek, presentasi salindia (powerpoint) pendek, pesan audio singkat, dll. yang dapat didiseminasikan melalui platform media daring atau elektronik. Materi yang sedikit panjang dapat didiseminasikan sebagai artikel di surat kabar atau majalah, program radio atau televisi, atau siniar yang diunggah secara daring. Selain itu konten untuk media sosial yang dapat diamplifikasi melalui banyak media sosial, misalkan satu konten dapat disebarluaskan melalui Instagram, Twitter/X, Facebook, WhatsApp, Youtube, dan lain-lain.
g. Jenis media yang dikembangkan Jenis media yang dapat dikembangkan antara lain:', 'BAB II (lanjutan 21)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1172, 'juklak-7-2026', 32, 'lain', 'BAB II (lanjutan 22)', NULL, 16, '1) Film/Video pendek Tim pembuat konten Komunikasi, Informasi, dan Edukasi dapat membuat film atau video pendek untuk diunggah ke akun media sosial BPBD dan/atau pemerintah daerah atau ditayangkan melalui Videotron di tempat umum.
Film pendek juga dapat dibuat dalam bentuk animasi.
Bila tidak ada personel dan anggaran untuk membuat film, Tim Komunikasi, Informasi, dan Edukasi dapat membuat film pendek sederhana dengan merekam presentasi singkat pejabat BPBD tentang ancaman bencana melalui HP Android biasa.
Dalam pembuatan konten film/video pendek ini perlu mempertimbangkan aspek gender dan disabilitas. Apabila sasaran sosialisasi adalah warga negara yang memiliki disabilitas tuna rungu, film/video perlu disertakan juru bicara isyarat. Pembuatan film/video dapat melibatkan Sekolah Luar Biasa, melibatkan ahli terkait kebutuhan khusus, dan multimedia video dengan kolaborasi ahli.
Tim juga dapat memanfaatkan film/video penyuluhan atau sosialisasi kebencanaan yang dibuat perangkat daerah lain, BPBD daerah lain, organisasi non-pemerintah di daerah atau yang dibuat pemerintah pusat.
Sebagai contoh untuk video penjelasan tentang banjir dapat menggunakan video yang telah ada milik Dinas Pekerjaan Umum atau video tentang tsunami oleh stasiun/unit pelaksana teknis Badan Meteorologi, Klimatologi, dan Geofisika setempat, atau video tentang erupsi gunung api dari Dinas Pertambangan dan Energi daerah atau Pusat Vulkanologi dan Mitigasi Bencana Geologi di pusat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1172, '1) Film/Video pendek Tim pembuat konten Komunikasi, Informasi, dan Edukasi dapat membuat film atau video pendek untuk diunggah ke akun media sosial BPBD dan/atau pemerintah daerah atau ditayangkan melalui Videotron di tempat umum.
Film pendek juga dapat dibuat dalam bentuk animasi.
Bila tidak ada personel dan anggaran untuk membuat film, Tim Komunikasi, Informasi, dan Edukasi dapat membuat film pendek sederhana dengan merekam presentasi singkat pejabat BPBD tentang ancaman bencana melalui HP Android biasa.
Dalam pembuatan konten film/video pendek ini perlu mempertimbangkan aspek gender dan disabilitas. Apabila sasaran sosialisasi adalah warga negara yang memiliki disabilitas tuna rungu, film/video perlu disertakan juru bicara isyarat. Pembuatan film/video dapat melibatkan Sekolah Luar Biasa, melibatkan ahli terkait kebutuhan khusus, dan multimedia video dengan kolaborasi ahli.
Tim juga dapat memanfaatkan film/video penyuluhan atau sosialisasi kebencanaan yang dibuat perangkat daerah lain, BPBD daerah lain, organisasi non-pemerintah di daerah atau yang dibuat pemerintah pusat.
Sebagai contoh untuk video penjelasan tentang banjir dapat menggunakan video yang telah ada milik Dinas Pekerjaan Umum atau video tentang tsunami oleh stasiun/unit pelaksana teknis Badan Meteorologi, Klimatologi, dan Geofisika setempat, atau video tentang erupsi gunung api dari Dinas Pertambangan dan Energi daerah atau Pusat Vulkanologi dan Mitigasi Bencana Geologi di pusat.', 'BAB II (lanjutan 22)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1173, 'juklak-7-2026', 33, 'lain', 'BAB II (lanjutan 23)', NULL, 16, '2) Pesan singkat Tim pembuat konten Komunikasi, Informasi, dan Edukasi dapat membuat pesan singkat yang disampaikan melalui WhatsApp blast atau broadcast, TikTok, Twitter/X, Telegram, SMS blast, atau media sosial lainnya. Informasi yang termuat dalam pesan singkat ini harus sangat singkat, padat, jelas dan informatif. Bentuk dan saluran komunikasi ini terutama digunakan dalam situasi darurat bencana atau untuk kesiapsiagaan dalam menghadapi ancaman bencana yang akan segera datang. Pesan singkat dapat berisi informasi dan perintah bagi masyarakat di dusun atau kampung yang berpotensi terdampak bencana banjir untuk bersiap-siap mengungsi atau pada contoh lain adalah pesan singkat yang berisi tentang penyebaran informasi cuaca ekstrem dan kemungkinan badai bagi nelayan di kawasan pesisir pantai.
3) Produk komunikasi cetak Tim pembuat konten Komunikasi, Informasi, dan Edukasi dapat membuat produk komunikasi cetak seperti poster, brosur, leaflet, buku saku atau bentuk barang cetak lainnya yang adaptif dan inklusif untuk dibagikan kepada warga negara yang tidak dapat mengakses media sosial.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1173, '2) Pesan singkat Tim pembuat konten Komunikasi, Informasi, dan Edukasi dapat membuat pesan singkat yang disampaikan melalui WhatsApp blast atau broadcast, TikTok, Twitter/X, Telegram, SMS blast, atau media sosial lainnya. Informasi yang termuat dalam pesan singkat ini harus sangat singkat, padat, jelas dan informatif. Bentuk dan saluran komunikasi ini terutama digunakan dalam situasi darurat bencana atau untuk kesiapsiagaan dalam menghadapi ancaman bencana yang akan segera datang. Pesan singkat dapat berisi informasi dan perintah bagi masyarakat di dusun atau kampung yang berpotensi terdampak bencana banjir untuk bersiap-siap mengungsi atau pada contoh lain adalah pesan singkat yang berisi tentang penyebaran informasi cuaca ekstrem dan kemungkinan badai bagi nelayan di kawasan pesisir pantai.
3) Produk komunikasi cetak Tim pembuat konten Komunikasi, Informasi, dan Edukasi dapat membuat produk komunikasi cetak seperti poster, brosur, leaflet, buku saku atau bentuk barang cetak lainnya yang adaptif dan inklusif untuk dibagikan kepada warga negara yang tidak dapat mengakses media sosial.', 'BAB II (lanjutan 23)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1174, 'juklak-7-2026', 34, 'lain', 'BAB II (lanjutan 24)', NULL, 17, 'Dalam proses pembuatan produk komunikasi perlu memperhatikan: a) tampilan warna yang ramah bagi penyandang disabilitas sensorik/buta warna; b) gambar yang bermakna bagi penyandang disabilitas buta aksara agar dapat memahami media cetak dengan baik tanpa harus membaca; c) dapat menyajikan infografis; d) muatan informasi dan pesan yang disampaikan dalam perlu disesuaikan dengan format produk komunikasi cetak yang akan dibuat; e) disebarkan kepada sasaran yang tepat atau ditempatkan di tempat umum, seperti kantor desa/dusun, sekolah, fasilitas kesehatan, pasar atau fasilitas umum lainnya; f) Tim pembuat konten Komunikasi, Informasi, dan Edukasi dapat menjalin kerja sama dengan lembaga swadaya masyarakat, relawan, swasta, media massa daerah atau perguruan tinggi dalam pembuatan produk komunikasi cetak; g) Tim juga dapat memohon bantuan file elektronik barang cetak yang diproduksi oleh perangkat daerah lain, BPBD daerah kabupaten/kota lain tetangga, lembaga non-pemerintah di daerah atau pemerintah pusat untuk dicetak dan dibagikan; dan h) File elektronik poster, brosur, leaflet dan buku saku dengan desain komunikasi visual yang menarik dapat diunggah ke dalam media sosial yang dimiliki BPBD dan pemerintah daerah. Sumber materi dapat disusun berdasarkan Katalog Komunikasi, Informasi, dan Edukasi Rawan Bencana sesuai Format-2 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1174, 'Dalam proses pembuatan produk komunikasi perlu memperhatikan: a) tampilan warna yang ramah bagi penyandang disabilitas sensorik/buta warna; b) gambar yang bermakna bagi penyandang disabilitas buta aksara agar dapat memahami media cetak dengan baik tanpa harus membaca; c) dapat menyajikan infografis; d) muatan informasi dan pesan yang disampaikan dalam perlu disesuaikan dengan format produk komunikasi cetak yang akan dibuat; e) disebarkan kepada sasaran yang tepat atau ditempatkan di tempat umum, seperti kantor desa/dusun, sekolah, fasilitas kesehatan, pasar atau fasilitas umum lainnya; f) Tim pembuat konten Komunikasi, Informasi, dan Edukasi dapat menjalin kerja sama dengan lembaga swadaya masyarakat, relawan, swasta, media massa daerah atau perguruan tinggi dalam pembuatan produk komunikasi cetak; g) Tim juga dapat memohon bantuan file elektronik barang cetak yang diproduksi oleh perangkat daerah lain, BPBD daerah kabupaten/kota lain tetangga, lembaga non-pemerintah di daerah atau pemerintah pusat untuk dicetak dan dibagikan; dan h) File elektronik poster, brosur, leaflet dan buku saku dengan desain komunikasi visual yang menarik dapat diunggah ke dalam media sosial yang dimiliki BPBD dan pemerintah daerah. Sumber materi dapat disusun berdasarkan Katalog Komunikasi, Informasi, dan Edukasi Rawan Bencana sesuai Format-2 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.', 'BAB II (lanjutan 24)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1175, 'juklak-7-2026', 35, 'lain', 'BAB II (lanjutan 25)', NULL, 17, '4) Program radio dan televisi Apabila berdasarkan kajian profil warga negara yang tinggal di kawasan rawan bencana menghasilkan data banyak warga masih mendengarkan radio dan menonton televisi lokal sebagai sumber informasi dan hiburan, Tim pembuat konten Komunikasi, Informasi, dan Edukasi dapat mengembangkan program dan kegiatan sosialisasi melalui kedua media ini. Pada tahap pra bencana atau dalam situasi darurat bencana, BPBD dapat mengajukan waktu tayang atau permohonan wawancara/diskusi kepada stasiun televisi dan radio lokal. BPBD dapat menjadi pengisi acara diskusi atau talkshow dengan melibatkan juru bahasa isyarat. Tim pembuat konten Komunikasi, Informasi, dan Edukasi perlu mempersiapkan informasi termutakhir yang penting, singkat, dan padat yang dapat dibawa ke dalam diskusi atau talkshow.
Tim Komunikasi, Informasi, dan Edukasi dapat juga mendorong pemilik radio swasta/pemerintah atau stasiun televisi lokal untuk bekerja sama mengembangkan program sosialisasi kebencanaan. Program radio dan televisi dapat melibatkan perangkat daerah teknis, akademisi atau praktisi, sehingga sosialisasi dapat dilaksanakan dengan lebih efektif dan efisien. Sumber materi dapat disusun berdasarkan Katalog Komunikasi, Informasi, dan Edukasi Rawan Bencana sesuai Format-2 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1175, '4) Program radio dan televisi Apabila berdasarkan kajian profil warga negara yang tinggal di kawasan rawan bencana menghasilkan data banyak warga masih mendengarkan radio dan menonton televisi lokal sebagai sumber informasi dan hiburan, Tim pembuat konten Komunikasi, Informasi, dan Edukasi dapat mengembangkan program dan kegiatan sosialisasi melalui kedua media ini. Pada tahap pra bencana atau dalam situasi darurat bencana, BPBD dapat mengajukan waktu tayang atau permohonan wawancara/diskusi kepada stasiun televisi dan radio lokal. BPBD dapat menjadi pengisi acara diskusi atau talkshow dengan melibatkan juru bahasa isyarat. Tim pembuat konten Komunikasi, Informasi, dan Edukasi perlu mempersiapkan informasi termutakhir yang penting, singkat, dan padat yang dapat dibawa ke dalam diskusi atau talkshow.
Tim Komunikasi, Informasi, dan Edukasi dapat juga mendorong pemilik radio swasta/pemerintah atau stasiun televisi lokal untuk bekerja sama mengembangkan program sosialisasi kebencanaan. Program radio dan televisi dapat melibatkan perangkat daerah teknis, akademisi atau praktisi, sehingga sosialisasi dapat dilaksanakan dengan lebih efektif dan efisien. Sumber materi dapat disusun berdasarkan Katalog Komunikasi, Informasi, dan Edukasi Rawan Bencana sesuai Format-2 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.', 'BAB II (lanjutan 25)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1176, 'juklak-7-2026', 36, 'lain', 'BAB II (lanjutan 26)', NULL, 18, '5) Artikel di media massa cetak Sosialisasi dapat dilakukan juga melalui media massa seperti surat kabar dan majalah. Sosialisasi melalui media massa cetak dapat dilakukan melalui penyusunan tulisan ilmiah atau kolom wawancara. BPBD dapat mempersiapkan tulisan yang berisi informasi singkat terkait bencana yang dapat dimuat di media milik pemerintah daerah atau siap untuk dibagikan kepada para wartawan bila diminta. Secara berkala bagian humas BPBD juga dapat mengirimkan siaran pers kepada media massa bila ada hal khusus yang ingin disampaikan berkaitan dengan kegiatan BPBD yang dapat juga menjadi sarana edukasi bagi masyarakat.
6) Siaran pers Dalam situasi tertentu dimana pemerintah daerah perlu menyampaikan arahan atau informasi kepada warga negara agar mengambil langkah tertentu dalam kesiapsiagaan bencana, BPBD dapat membuat siaran pers dan menyebarluaskannya ke jaringan media cetak dan elektronik di daerah. Kesiapsiagaan bencana dapat berupa informasi kenaikan status gunung api yang dikeluarkan oleh Pusat Vulkanologi dan Mitigasi Bencana Geologi atau peringatan dini cuaca yang dikeluarkan oleh Badan Meteorologi, Klimatologi, dan Geofisika atau peringatan lain yang dikeluarkan oleh instansi terkait lainnya. Panduan dan contoh pembuatan siaran pers sesuai Format-3 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
3. Pelaksanaan Sosialisasi Media Sosial dan Wahana Multimedia');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1176, '5) Artikel di media massa cetak Sosialisasi dapat dilakukan juga melalui media massa seperti surat kabar dan majalah. Sosialisasi melalui media massa cetak dapat dilakukan melalui penyusunan tulisan ilmiah atau kolom wawancara. BPBD dapat mempersiapkan tulisan yang berisi informasi singkat terkait bencana yang dapat dimuat di media milik pemerintah daerah atau siap untuk dibagikan kepada para wartawan bila diminta. Secara berkala bagian humas BPBD juga dapat mengirimkan siaran pers kepada media massa bila ada hal khusus yang ingin disampaikan berkaitan dengan kegiatan BPBD yang dapat juga menjadi sarana edukasi bagi masyarakat.
6) Siaran pers Dalam situasi tertentu dimana pemerintah daerah perlu menyampaikan arahan atau informasi kepada warga negara agar mengambil langkah tertentu dalam kesiapsiagaan bencana, BPBD dapat membuat siaran pers dan menyebarluaskannya ke jaringan media cetak dan elektronik di daerah. Kesiapsiagaan bencana dapat berupa informasi kenaikan status gunung api yang dikeluarkan oleh Pusat Vulkanologi dan Mitigasi Bencana Geologi atau peringatan dini cuaca yang dikeluarkan oleh Badan Meteorologi, Klimatologi, dan Geofisika atau peringatan lain yang dikeluarkan oleh instansi terkait lainnya. Panduan dan contoh pembuatan siaran pers sesuai Format-3 sebagaimana dimuat dalam Lampiran yang merupakan bagian tidak terpisahkan dari Petunjuk Pelaksanaan ini.
3. Pelaksanaan Sosialisasi Media Sosial dan Wahana Multimedia', 'BAB II (lanjutan 26)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1177, 'juklak-7-2026', 37, 'lain', 'BAB II (lanjutan 27)', NULL, 18, 'a. Diseminasi materi media sosial dan wahana multimedia Tim pengelola multimedia Komunikasi, Informasi, dan Edukasi melakukan diseminasi materi media yang telah disiapkan oleh Tim pembuat konten. Sosialisasi melalui media sosial dan multimedia dilakukan melalui film/video pendek, pesan singkat, produk cetak, program radio-TV, dan artikel di media cetak.
Pelaksanaan sosialisasi melalui media sosial dan wahana multimedia dapat dilakukan melalui:
1) Website dan/atau YouTube yang dimiliki BPBD atau Pemerintah Daerah a) Untuk mengunggah film/video pendek dan film animasi yang dilengkapi juru bahasa isyarat, pesan singkat, informasi/poster elektronik, dll. b) Menampilkan berita tertulis, berita foto dan video serta informasi kebencanaan lainnya yang dipublikasikan BPBD.
2) BPBD memilih satu atau dua platform media sosial yang populer di daerah (Facebook, Instagram, Twitter/X, TikTok, atau lainnya) untuk menjangkau kaum muda.
3) Grup WhatsApp a) Grup Whatsapp beranggotakan Bupati/Walikota, Sekretaris Daerah, Pimpinan perangkat daerah, Camat, dan Kepala Desa/Lurah. b) Grup Whatsapp beranggotakan BPBD, Tim Reaksi Cepat, Kepala Desa/Lurah, Kepala Dusun/Ketua RW, dan Ketua RT. c) Penyebaran informasi dari BPBD dapat dilakukan melalui aplikasi Whatsapp broadcast.
4) Kantor kecamatan, kantor desa/kelurahan, balai dusun/kampung, fasilitas pendidikan dan kesehatan untuk penempatan videotron, poster, leaflet atau materi cetak lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1177, 'a. Diseminasi materi media sosial dan wahana multimedia Tim pengelola multimedia Komunikasi, Informasi, dan Edukasi melakukan diseminasi materi media yang telah disiapkan oleh Tim pembuat konten. Sosialisasi melalui media sosial dan multimedia dilakukan melalui film/video pendek, pesan singkat, produk cetak, program radio-TV, dan artikel di media cetak.
Pelaksanaan sosialisasi melalui media sosial dan wahana multimedia dapat dilakukan melalui:
1) Website dan/atau YouTube yang dimiliki BPBD atau Pemerintah Daerah a) Untuk mengunggah film/video pendek dan film animasi yang dilengkapi juru bahasa isyarat, pesan singkat, informasi/poster elektronik, dll. b) Menampilkan berita tertulis, berita foto dan video serta informasi kebencanaan lainnya yang dipublikasikan BPBD.
2) BPBD memilih satu atau dua platform media sosial yang populer di daerah (Facebook, Instagram, Twitter/X, TikTok, atau lainnya) untuk menjangkau kaum muda.
3) Grup WhatsApp a) Grup Whatsapp beranggotakan Bupati/Walikota, Sekretaris Daerah, Pimpinan perangkat daerah, Camat, dan Kepala Desa/Lurah. b) Grup Whatsapp beranggotakan BPBD, Tim Reaksi Cepat, Kepala Desa/Lurah, Kepala Dusun/Ketua RW, dan Ketua RT. c) Penyebaran informasi dari BPBD dapat dilakukan melalui aplikasi Whatsapp broadcast.
4) Kantor kecamatan, kantor desa/kelurahan, balai dusun/kampung, fasilitas pendidikan dan kesehatan untuk penempatan videotron, poster, leaflet atau materi cetak lainnya.', 'BAB II (lanjutan 27)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1178, 'juklak-7-2026', 38, 'lain', 'BAB II (lanjutan 28)', NULL, 19, '5) Fasilitas yang dimiliki lembaga nonpemerintah yang mau berpartisipasi untuk penempatan videotron, poster, leaflet atau materi cetak lainnya.
6) Stasiun radio, radio komunitas, televisi atau ruang siniar mitra yang berkomitmen untuk berkolaborasi dalam sosialisasi dan perwakilannya menjadi bagian dari Tim Komunikasi, Informasi, dan Edukasi BPBD. Keuntungan menggunakan radio konvensional yaitu ada interaksi langsung dengan masyarakat. Kelemahannya hanya digunakan oleh komunitas tertentu dan tidak ada visual yang dapat ditampilkan.
7) Surat kabar atau majalah yang berkomitmen untuk bekerja sama dan perwakilannya menjadi bagian dari Tim Komunikasi, Informasi, dan Edukasi BPBD.
8) Pemanfaatan pengeras suara pada wilayah setempat, memanfaatkan poster/banner dengan mencantumkan kontak darurat (nomor telpon/WhatsApp, website).
Kelemahannya yaitu filtrasi informasi yang terkait dengan hoaks yang muncul kaitannya dengan bencana.
C. Penyediaan dan Pemasangan Rambu Evakuasi dan Papan Informasi Publik
1. Penyediaan Rambu Evakuasi dan Papan Informasi Publik Penyediaan rambu evakuasi dan papan informasi publik mengikuti ketentuan peraturan perundang-undangan yang mengatur mengenai rambu dan papan informasi bencana. Rambu evakuasi disediakan sesuai kebutuhan, inklusif, dan berdasarkan perencanaan jalur evakuasi, paling sedikit untuk bencana prioritas yang ditetapkan. Rambu evakuasi harus memenuhi persyaratan:
a. mudah terlihat dalam kondisi darurat; dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1178, '5) Fasilitas yang dimiliki lembaga nonpemerintah yang mau berpartisipasi untuk penempatan videotron, poster, leaflet atau materi cetak lainnya.
6) Stasiun radio, radio komunitas, televisi atau ruang siniar mitra yang berkomitmen untuk berkolaborasi dalam sosialisasi dan perwakilannya menjadi bagian dari Tim Komunikasi, Informasi, dan Edukasi BPBD. Keuntungan menggunakan radio konvensional yaitu ada interaksi langsung dengan masyarakat. Kelemahannya hanya digunakan oleh komunitas tertentu dan tidak ada visual yang dapat ditampilkan.
7) Surat kabar atau majalah yang berkomitmen untuk bekerja sama dan perwakilannya menjadi bagian dari Tim Komunikasi, Informasi, dan Edukasi BPBD.
8) Pemanfaatan pengeras suara pada wilayah setempat, memanfaatkan poster/banner dengan mencantumkan kontak darurat (nomor telpon/WhatsApp, website).
Kelemahannya yaitu filtrasi informasi yang terkait dengan hoaks yang muncul kaitannya dengan bencana.
C. Penyediaan dan Pemasangan Rambu Evakuasi dan Papan Informasi Publik
1. Penyediaan Rambu Evakuasi dan Papan Informasi Publik Penyediaan rambu evakuasi dan papan informasi publik mengikuti ketentuan peraturan perundang-undangan yang mengatur mengenai rambu dan papan informasi bencana. Rambu evakuasi disediakan sesuai kebutuhan, inklusif, dan berdasarkan perencanaan jalur evakuasi, paling sedikit untuk bencana prioritas yang ditetapkan. Rambu evakuasi harus memenuhi persyaratan:
a. mudah terlihat dalam kondisi darurat; dan', 'BAB II (lanjutan 28)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1179, 'juklak-7-2026', 39, 'lain', 'BAB II (lanjutan 29)', NULL, 20, 'b. memberi informasi sesuai jenis ancaman, antara lain berupa arah evakuasi, lokasi aman, titik pengungsian dan informasi terkait lainnya.
Papan informasi publik disediakan sesuai kebutuhan dan berdasarkan rencana jumlah penempatan di lokasi/kawasan strategis. Papan informasi publik harus memberikan informasi sesuai jenis ancaman dan berisi informasi tentang:
a. ancaman bencana yang ada di lokasi, termasuk tanda-tanda atau gejala bencana yang akan terjadi;
b. peta evakuasi kawasan yang mempertimbangkan aksesibilitas bagi kelompok berisiko;
c. larangan atau ajakan untuk mencegah bencana;
d. langkah kesiapsiagaan;
e. nomor kontak darurat; dan
f. informasi terkait lainnya.
D. Pemasangan Rambu Evakuasi dan Papan Informasi Publik Tahapan penyediaan dan pemasangan rambu evakuasi dan papan informasi publik adalah sebagai berikut.
1. Persiapan, dengan memperhatikan:
a. penentuan sasaran penerima;
b. penentuan daerah rawan bencana;
c. BPBD memfasilitasi pemerintah desa/kelurahan untuk menyusun peta evakuasi berdasarkan dokumen kajian risiko bencana dan dokumen rencana kontingensi, dan/atau data instansi sektoral; dan
d. peta dan dokumen di atas digunakan untuk menentukan jalur evakuasi, tempat hunian sementara, tempat hunian aman, titik pemasangan rambu evakuasi dan papan informasi publik.
2. Pelaksanaan, dengan memperhatikan:');
