INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1181, 'juklak-7-2026', 41, 'lain', 'BAB III', NULL, 22, 'PENUTUP Petunjuk Pelaksanaan ini diharapkan dapat menjadi acuan bagi semua pemangku kepentingan yang terlibat dengan penerapan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Sub-Kegiatan Komunikasi, Informasi dan Edukasi Rawan Bencana sehingga tercipta perlindungan warga negara dari ancaman bencana.
Ditetapkan di Jakarta pada tanggal 15 September 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1181, 'PENUTUP Petunjuk Pelaksanaan ini diharapkan dapat menjadi acuan bagi semua pemangku kepentingan yang terlibat dengan penerapan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Sub-Kegiatan Komunikasi, Informasi dan Edukasi Rawan Bencana sehingga tercipta perlindungan warga negara dari ancaman bencana.
Ditetapkan di Jakarta pada tanggal 15 September 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Irma Dewi Rismayati', 'BAB III', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1182, 'juklak-7-2026', 42, 'lampiran', 'LAMPIRAN', NULL, 23, 'PETUNJUK PELAKSANAAN PEMENUHAN STANDAR PELAYANAN MINIMAL SUB-URUSAN BENCANA DAERAH KABUPATEN/KOTA UNTUK SUBKEGIATAN PELAYANAN KOMUNIKASI, INFORMASI DAN EDUKASI RAWAN BENCANA NOMOR 7 TAHUN 2026 FORMAT DOKUMEN PELAYANAN KOMUNIKASI, INFORMASI DAN EDUKASI RAWAN BENCANA Format-1 Contoh Format Rencana Umum Program Komunikasi, Informasi, dan Edukasi Rawan Bencana Contoh kasus:
Kabupaten Sukadana memiliki 5 ancaman bencana yaitu sesuai urutan risiko tinggi ke rendah sebagai berikut: erupsi gunung api, banjir lahar hujan, kebakaran hutan, banjir, dan longsor.
Kabupaten tersebut memiliki penduduk sejumlah 517.000 jiwa yang berpotensi terpapar ancaman bencana. Sebanyak 75% (tujuh puluh lima persen) berdomisili di kawasan rawan gunung api dengan risiko erupsi gunung berapi dan banjir lahar hujan. Sementara itu 80% (delapan puluh persen) dari warga yang berdomisili di kawasan rawan gunung api adalah penduduk usia dewasa dan orang lanjut usia. BPBD perlu menyusun strategi dan tujuan-tujuan khusus Komunikasi, Informasi, dan Edukasi Rawan Bencana untuk menyasar penduduk usia dewasa dan orang lanjut usia yang tinggal di sekitar gunung api. Setelah itu baru menyasar masyarakat gunung api pada kelompok umur di bawahnya, penyandang disabilitas dan kelompok berisiko lainnya, dan selanjutnya baru menyusun program-kegiatan untuk ancaman lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1182, 'PETUNJUK PELAKSANAAN PEMENUHAN STANDAR PELAYANAN MINIMAL SUB-URUSAN BENCANA DAERAH KABUPATEN/KOTA UNTUK SUBKEGIATAN PELAYANAN KOMUNIKASI, INFORMASI DAN EDUKASI RAWAN BENCANA NOMOR 7 TAHUN 2026 FORMAT DOKUMEN PELAYANAN KOMUNIKASI, INFORMASI DAN EDUKASI RAWAN BENCANA Format-1 Contoh Format Rencana Umum Program Komunikasi, Informasi, dan Edukasi Rawan Bencana Contoh kasus:
