INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1183, 'juklak-7-2026', 43, 'lampiran', 'LAMPIRAN (lanjutan 1)', NULL, 24, '24 Format Rencana Umum Program Komunikasi, Informasi, dan Edukasi Rawan Bencana Sasaran Strategi Tahun Pertama Tahun Kedua Tahun Ketiga Tahun Keempat Tahun Kelima Penduduk usia Sosialisasi tatap Pertemuan rembug Pertemuan Pertemuan Pertemuan Pertemuan dewasa dan muka bekerja masyarakat di rembug rembug rembug rembug lanjut usia sama dengan Desa X, Y dan Z masyarakat di masyarakat di masyarakat di masyarakat di relawan dan untuk ancaman Desa G, H dan I Desa X dan Y Desa G dan Z Desa Y untuk lembaga swadaya erupsi untuk ancaman untuk ancaman untuk ancaman ancaman masyarakat lokal erupsi dan lahar longsor banjir kebakaran hujan hutan Pertunjukan seni Pentas wayang Pentas musik di budaya didukung kulit di Desa Z Desa Y dan M dunia usaha untuk sosialisasi untuk sosialisasi ancaman ancaman kebakaran hutan kebakaran hutan Sosialisasi melalui Pengajian ibu-ibu Sosialisasi Sosialisasi kegiatan di Desa M dan N ancaman erupsi ancaman erupsi keagamaan untuk ancaman gunung api lewat gunung api lewat erupsi gereja Kristen di Pura di Desa P Desa O Penduduk usia Sosialisasi melalui Film pendek Film pendek muda media sosial kerja tentang ancaman tentang cara (pekerja, sama dengan erupsi gunung api mengurangi karyawan, perangkat daerah dan banjir lahar ancaman banjir mahasiswa, terkait hujan melalui lahar hujan usia produktif Website dan melalui Twitter/X lainnya) Facebook dan Instagram Kegiatan olah raga Lomba Voli antar Lomba sepak Lomba Voli antar kerja sama dengan kampung di semua bola');
