INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1184, 'juklak-7-2026', 44, 'lampiran', 'LAMPIRAN (lanjutan 2)', NULL, 24, 'tangguh kampung di 5 dunia usaha desa rawan erupsi piala BPBD Desa rawan dan lahar hujan Kabupaten longsor 25 Sasaran Strategi Tahun Pertama Tahun Kedua Tahun Ketiga Tahun Keempat Tahun Kelima Sosialisasi melalui Distribusi poster di Distribusi poster Distribusi brosur Distribusi poster media cetak Desa X, Y dan Z di Desa G, H dan I tentang dan brosur (poster, brosur, tentang erupsi tentang erupsi ancaman longsor tentang ancaman dan buku saku) gunung api gunung api di Desa X dan Y banjir di Desa G dan Z Kerja sama dengan Talkshow di radio stasiun radio dengan perangkat untuk sosialisasi daerah dan ancaman erupsi akademisi tentang gunung api dan ancaman erupsi ancaman terkait dan lahar hujan Pelajar (SD- Kerja sama dengan Penyuluhan siaga Pelatihan siaga SMA dan Program Sekolah bencana melalui bencana lainnya yang Aman Bencana sekolah di kebakaran hutan setara) kawasan rawan di sekolah dekat erupsi dan lahar kawasan hutan hujan Penyandang Sosialisasi tatap Penyuluhan-Disabilitas muka dengan pelatihan organisasi kesiapsiagaan pendamping bencana dalam penyandang menghadapi disabilitas ancaman erupsi dan lahar hujan Format-2 Katalog Komunikasi, Informasi, dan Edukasi Rawan Bencana Katalog Komunikasi, Informasi, dan Edukasi Rawan Bencana dapat bersumber dari website, e-book, infografis, poster, atau sandiwara radio.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1184, 'tangguh kampung di 5 dunia usaha desa rawan erupsi piala BPBD Desa rawan dan lahar hujan Kabupaten longsor 25 Sasaran Strategi Tahun Pertama Tahun Kedua Tahun Ketiga Tahun Keempat Tahun Kelima Sosialisasi melalui Distribusi poster di Distribusi poster Distribusi brosur Distribusi poster media cetak Desa X, Y dan Z di Desa G, H dan I tentang dan brosur (poster, brosur, tentang erupsi tentang erupsi ancaman longsor tentang ancaman dan buku saku) gunung api gunung api di Desa X dan Y banjir di Desa G dan Z Kerja sama dengan Talkshow di radio stasiun radio dengan perangkat untuk sosialisasi daerah dan ancaman erupsi akademisi tentang gunung api dan ancaman erupsi ancaman terkait dan lahar hujan Pelajar (SD- Kerja sama dengan Penyuluhan siaga Pelatihan siaga SMA dan Program Sekolah bencana melalui bencana lainnya yang Aman Bencana sekolah di kebakaran hutan setara) kawasan rawan di sekolah dekat erupsi dan lahar kawasan hutan hujan Penyandang Sosialisasi tatap Penyuluhan-Disabilitas muka dengan pelatihan organisasi kesiapsiagaan pendamping bencana dalam penyandang menghadapi disabilitas ancaman erupsi dan lahar hujan Format-2 Katalog Komunikasi, Informasi, dan Edukasi Rawan Bencana Katalog Komunikasi, Informasi, dan Edukasi Rawan Bencana dapat bersumber dari website, e-book, infografis, poster, atau sandiwara radio.', 'LAMPIRAN (lanjutan 2)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1185, 'juklak-7-2026', 45, 'lampiran', 'LAMPIRAN (lanjutan 3)', NULL, 26, '1. Katalog Komunikasi, Informasi, dan Edukasi Kebencanaan ini memuat tautan (link) sumber materi konten kebencanaan berdasarkan 9 jenis ancaman bencana, yaitu banjir, tanah longsor, gempa bumi, tsunami, letusan gunung berapi, cuaca ekstrem/angin puting beliung, kekeringan, kebakaran hutan/lahan/pemukiman dan penyakit menular.
2. Pada jenis bencana ada konten berbentuk infografis, video (film pendek, animasi, dan sebagainya) dan/atau teks (tulisan). Konten infografis dan teks ada pada tautan website, sementara konten video pada tautan YouTube dan Instagram.
3. BPBD dapat mengunduh konten tersebut pada tautan sumber materi yang ada. Mereka dapat menambahkan teks atau narasi lembaganya, dengan menyebut sumber konten tersebut dari lembaga yang ada dalam tautan.
4. Lembaga yang membuat konten tersebut antara lain BNPB, Badan Meteorologi, Klimatologi, dan Geofisika, Kementerian Kesehatan dan sejumlah kementerian/lembaga lainnya, serta media massa.
5. Sumber materi sebagaimana dimaksud nomor 1 berisi konten kebencanaan umum (bukan per jenis bencana) yang diproduksi Pusat Data, Informasi dan Komunikasi Kebencanaan BNPB. Termasuk konten sandiwara radio.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1185, '1. Katalog Komunikasi, Informasi, dan Edukasi Kebencanaan ini memuat tautan (link) sumber materi konten kebencanaan berdasarkan 9 jenis ancaman bencana, yaitu banjir, tanah longsor, gempa bumi, tsunami, letusan gunung berapi, cuaca ekstrem/angin puting beliung, kekeringan, kebakaran hutan/lahan/pemukiman dan penyakit menular.
2. Pada jenis bencana ada konten berbentuk infografis, video (film pendek, animasi, dan sebagainya) dan/atau teks (tulisan). Konten infografis dan teks ada pada tautan website, sementara konten video pada tautan YouTube dan Instagram.
3. BPBD dapat mengunduh konten tersebut pada tautan sumber materi yang ada. Mereka dapat menambahkan teks atau narasi lembaganya, dengan menyebut sumber konten tersebut dari lembaga yang ada dalam tautan.
4. Lembaga yang membuat konten tersebut antara lain BNPB, Badan Meteorologi, Klimatologi, dan Geofisika, Kementerian Kesehatan dan sejumlah kementerian/lembaga lainnya, serta media massa.
5. Sumber materi sebagaimana dimaksud nomor 1 berisi konten kebencanaan umum (bukan per jenis bencana) yang diproduksi Pusat Data, Informasi dan Komunikasi Kebencanaan BNPB. Termasuk konten sandiwara radio.', 'LAMPIRAN (lanjutan 3)', 'Petunjuk Pelaksanaan Pemenuhan Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota untuk Subkegiatan Pelayanan Komunikasi, Informasi, dan Edukasi Rawan Bencana Nomor 7 Tahun 2026');
