INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1196, 'juklak-7-2026', 56, 'lampiran', 'LAMPIRAN (lanjutan 14)', NULL, 26, 'tengah bencana -- streaming di Radio Elisa FM No Ancaman Sumber Materi Keterangan https://www.bnpb.go.id/buku/b BNPB-Buku Saku Tanggap, uku-saku-bencana Tangkas dan Tangguh Menghadapi Bencana -- download buku Format-3 Panduan dan Contoh Pembuatan Siaran Pers Panduan Pembuatan Siaran Pers A. Membuat Siaran Pers
1. Apa itu siaran pers itu?
a. Siaran pers adalah pernyataan resmi yang disampaikan kepada media massa dengan tujuan mengumumkan suatu pernyataan atau sikap resmi dari suatu organisasi untuk dipublikasikan.
b. Siaran pers diedarkan dengan harapan dapat mencapai target audiens yang dituju, biasanya publik secara luas.
2. Kapan waktu mengeluarkan siaran pers
a. Dikeluarkan pada saat ada sesuatu hal yang baru (news), atau adanya reaksi dari organisasi mengenai suatu kejadian yang baru terjadi. Di luar waktu ini, bisa saja mengeluarkan pernyataan pers, sifatnya adalah ‘press briefing’.
b. Dari segi waktu mengeluarkannya, umumnya siaran pers dikeluarkan pada awal jam kerja media dan sebelum waktu tenggat publikasi. Tapi saat ini sebagian besar media massa menggunakan platform daring dan sifatnya mirip kantor berita yang tenggat waktu publikasinya tiap menit.
3. Kemana siaran pers diedarkan
a. Siaran pers diedarkan secara elektronik, baik melalui email, media sosial, atau dipublikasikan di website organisasi yang mengeluarkan, atau platform resmi organisasi tersebut lainnya.
b. Jadi selain email, Whatsapp, siaran pers juga bisa diedarkan melalui.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1196, 'tengah bencana -- streaming di Radio Elisa FM No Ancaman Sumber Materi Keterangan https://www.bnpb.go.id/buku/b BNPB-Buku Saku Tanggap, uku-saku-bencana Tangkas dan Tangguh Menghadapi Bencana -- download buku Format-3 Panduan dan Contoh Pembuatan Siaran Pers Panduan Pembuatan Siaran Pers A. Membuat Siaran Pers
