INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1200, 'juklak-8-2023', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Nomor 8 Tahun 2023 tentang Mekanisme Pemberian Bantuan Pemerintah Bidang Teknologi, Informasi, dan Dan Komunikasi, Dan Sarana Prasarana Pusat Pengendalian Operasi');
