INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1201, 'juklak-8-2024', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1201, 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah', 'Judul', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1202, 'juklak-8-2024', 1, 'lain', 'Isi hal. 1', NULL, 1, 'A.
SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMADUAN UNSUR-UNSUR PENANGGULANGAN BENCANA KE DALAM RENCANA PEMBANGUNAN JANGKA MENENGAH DAERAH NOMOR 8 TAHUN 2024');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1202, 'A.
SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PEMADUAN UNSUR-UNSUR PENANGGULANGAN BENCANA KE DALAM RENCANA PEMBANGUNAN JANGKA MENENGAH DAERAH NOMOR 8 TAHUN 2024', 'Isi hal. 1', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1203, 'juklak-8-2024', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN Latar Belakang Pasal 6 ayat (1) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana menyatakan bahwa perencanaan penanggulangan bencana merupakan bagian dari perencanaan pembangunan.
Pasal ini menegaskan keterkaitan erat antara penanggulangan bencana dengan pembangunan. Selanjutnya dalam Pasal 10 ayat (2) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana disebutkan bahwa pemaduan penanggulangan bencana dalam perencanaan pembangunan dilakukan dengan cara memasukkan unsur-unsur penanggulangan bencana ke dalam rencana pembangunan nasional dan daerah.
Pemerintah Daerah perlu memadukan unsur-unsur penanggulangan bencana (PB) ke dalam Rencana Pembangunan Jangka Menengah Daerah (RPJMD) demi meningkatkan resiliensi dalam menghadapi bencana dan melindungi aset-aset serta hasil pembangunan dari dampak bencana yang merusak, serta demi mendukung tercapainya tujuan-tujuan pembangunan berkelanjutan. Badan Penanggulangan Bencana Daerah (BPBD) sebagai Organisasi Perangkat Daerah yang bertanggung jawab dalam mengoordinasikan penanggulangan bencana di daerah wajib berkolaborasi dengan Bappeda untuk mendorong penyusunan dokumen Rencana Pembangunan Jangka Menengah Daerah (RPJMD) yang mengandung perspektif pengurangan risiko bencana yang kuat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1203, 'PENDAHULUAN Latar Belakang Pasal 6 ayat (1) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana menyatakan bahwa perencanaan penanggulangan bencana merupakan bagian dari perencanaan pembangunan.
Pasal ini menegaskan keterkaitan erat antara penanggulangan bencana dengan pembangunan. Selanjutnya dalam Pasal 10 ayat (2) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana disebutkan bahwa pemaduan penanggulangan bencana dalam perencanaan pembangunan dilakukan dengan cara memasukkan unsur-unsur penanggulangan bencana ke dalam rencana pembangunan nasional dan daerah.
Pemerintah Daerah perlu memadukan unsur-unsur penanggulangan bencana (PB) ke dalam Rencana Pembangunan Jangka Menengah Daerah (RPJMD) demi meningkatkan resiliensi dalam menghadapi bencana dan melindungi aset-aset serta hasil pembangunan dari dampak bencana yang merusak, serta demi mendukung tercapainya tujuan-tujuan pembangunan berkelanjutan. Badan Penanggulangan Bencana Daerah (BPBD) sebagai Organisasi Perangkat Daerah yang bertanggung jawab dalam mengoordinasikan penanggulangan bencana di daerah wajib berkolaborasi dengan Bappeda untuk mendorong penyusunan dokumen Rencana Pembangunan Jangka Menengah Daerah (RPJMD) yang mengandung perspektif pengurangan risiko bencana yang kuat.', 'BAB I', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1204, 'juklak-8-2024', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Dalam rangka meningkatkan keberhasilan pemaduan unsur-unsur Penanggulangan Bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah (RPJMD), dibutuhkan pedoman yang dapat digunakan oleh Badan Penanggulangan Bencana Daerah (BPBD) dan Badan Perencanaan dan Pembangunan Daerah (Bappeda) Provinsi/Kabupaten/Kota sebagai acuan dalam melaksanakan kegiatan tersebut. Oleh karena itulah, Badan Nasional Penanggulangan Bencana (BNPB) menyusun Petunjuk Pelaksanaan Pemaduan Unsur-Unsur Penanggulangan Bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah (RPJMD).
Dasar Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah.
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
4. Peraturan Pemerintah Nomor 2 Tahun 2018 tentang Standar Pelayanan Minimal.
5. Peraturan Menteri Dalam Negeri Nomor 86 Tahun 2017 tentang Tata Cara Perencanaan, Pengendalian dan Evaluasi Pembangunan Daerah, Tata Cara Evaluasi Rancangan Peraturan Daerah tentang Rencana Pembangunan Jangka Panjang Daerah dan Rencana Pembangunan Jangka Menengah Daerah, serta Tata Cara Perubahan Rencana Pembangunan Jangka Panjang Daerah, Rencana Pembangunan Pembangunan Jangka Menengah Daerah, dan Rencana Kerja Pemerintah Daerah.
6. Peraturan Menteri Dalam Negeri Nomor 101 Tahun 2018 tentang Standar Teknis Pelayanan Dasar pada Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1204, 'Dalam rangka meningkatkan keberhasilan pemaduan unsur-unsur Penanggulangan Bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah (RPJMD), dibutuhkan pedoman yang dapat digunakan oleh Badan Penanggulangan Bencana Daerah (BPBD) dan Badan Perencanaan dan Pembangunan Daerah (Bappeda) Provinsi/Kabupaten/Kota sebagai acuan dalam melaksanakan kegiatan tersebut. Oleh karena itulah, Badan Nasional Penanggulangan Bencana (BNPB) menyusun Petunjuk Pelaksanaan Pemaduan Unsur-Unsur Penanggulangan Bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah (RPJMD).
Dasar Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah.
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
4. Peraturan Pemerintah Nomor 2 Tahun 2018 tentang Standar Pelayanan Minimal.
5. Peraturan Menteri Dalam Negeri Nomor 86 Tahun 2017 tentang Tata Cara Perencanaan, Pengendalian dan Evaluasi Pembangunan Daerah, Tata Cara Evaluasi Rancangan Peraturan Daerah tentang Rencana Pembangunan Jangka Panjang Daerah dan Rencana Pembangunan Jangka Menengah Daerah, serta Tata Cara Perubahan Rencana Pembangunan Jangka Panjang Daerah, Rencana Pembangunan Pembangunan Jangka Menengah Daerah, dan Rencana Kerja Pemerintah Daerah.
6. Peraturan Menteri Dalam Negeri Nomor 101 Tahun 2018 tentang Standar Teknis Pelayanan Dasar pada Standar Pelayanan Minimal Sub-Urusan Bencana Daerah Kabupaten/Kota.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1205, 'juklak-8-2024', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, 'C. Maksud dan Tujuan
1. Maksud Petunjuk pelaksanaan ini dimaksudkan sebagai acuan bagi Pemerintah Provinsi dan Kabupaten/Kota serta para pihak terkait dalam melaksanakan pemaduan unsur-unsur penanggulangan bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah.
2. Tujuan Petunjuk pelaksanaan ini bertujuan agar pelaksanaan pemaduan unsur-unsur penanggulangan bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah dapat terselenggara dengan cepat, tepat, dan akurat sebagai bagian dari upaya untuk mewujudkan pembangunan yang resilien dan berkelanjutan.
D. Ruang Lingkup Ruang lingkup petunjuk pelaksanaan ini mencakup:
1. konsep dan prinsip pemaduan;
2. pelaksanaan pemaduan; dan
3. penyusunan telaah atau ringkasan pemaduan.
E. Pengertian
1. Arah Kebijakan adalah rumusan kerangka pikir atau kerangka kerja untuk menyelesaikan permasalahan penanggulangan bencana dan mengantisipasi isu strategis penyelenggaraan penanggulangan bencana daerah yang dilaksanakan secara bertahap sebagai penjabaran atas strategi.
2. Indikator Kinerja adalah ukuran kuantitatif dan/atau kualitatif yang berfungsi sebagai alat ukur pencapaian kinerja suatu kegiatan, program atau sasaran dan tujuan dalam bentuk keluaran (output), hasil (outcome), atau dampak (impact).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1205, 'C. Maksud dan Tujuan
1. Maksud Petunjuk pelaksanaan ini dimaksudkan sebagai acuan bagi Pemerintah Provinsi dan Kabupaten/Kota serta para pihak terkait dalam melaksanakan pemaduan unsur-unsur penanggulangan bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah.
2. Tujuan Petunjuk pelaksanaan ini bertujuan agar pelaksanaan pemaduan unsur-unsur penanggulangan bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah dapat terselenggara dengan cepat, tepat, dan akurat sebagai bagian dari upaya untuk mewujudkan pembangunan yang resilien dan berkelanjutan.
D. Ruang Lingkup Ruang lingkup petunjuk pelaksanaan ini mencakup:
1. konsep dan prinsip pemaduan;
2. pelaksanaan pemaduan; dan
3. penyusunan telaah atau ringkasan pemaduan.
E. Pengertian
1. Arah Kebijakan adalah rumusan kerangka pikir atau kerangka kerja untuk menyelesaikan permasalahan penanggulangan bencana dan mengantisipasi isu strategis penyelenggaraan penanggulangan bencana daerah yang dilaksanakan secara bertahap sebagai penjabaran atas strategi.
2. Indikator Kinerja adalah ukuran kuantitatif dan/atau kualitatif yang berfungsi sebagai alat ukur pencapaian kinerja suatu kegiatan, program atau sasaran dan tujuan dalam bentuk keluaran (output), hasil (outcome), atau dampak (impact).', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1206, 'juklak-8-2024', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, '3. Isu Strategis adalah kondisi atau hal yang harus diperhatikan atau dikedepankan dalam perencanaan pembangunan daerah karena dampaknya yang signifikan bagi daerah dengan karakteristik bersifat penting, mendasar, mendesak, berjangka menengah/panjang, dan menentukan pencapaian tujuan penyelenggaraan Pemerintah Daerah di masa yang akan datang.
4. Kinerja adalah capaian keluaran/hasil/dampak dari kegiatan/program/ sasaran dari penggunaan sumber daya.
5. Pemaduan adalah upaya memasukkan unsur-unsur penanggulangan bencana ke dalam rencana pembangunan nasional dan daerah.
6. Program adalah penjabaran kebijakan perangkat daerah dalam bentuk upaya yang berisi satu atau lebih kegiatan dengan menggunakan sumber daya yang disediakan untuk mencapai hasil yang terukur sesuai dengan tugas dan fungsi.
7. Program pembangunan Daerah adalah program strategis Daerah yang dilaksanakan oleh Perangkat Daerah sebagai instrumen arah kebijakan untuk mencapai sasaran RPJMD.
8. Risiko bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, mengungsi, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
9. Rencana Pembangunan Jangka Menengah Daerah yang selanjutnya disingkat RPJMD adalah dokumen perencanaan Daerah untuk periode 5 (lima) tahun terhitung sejak dilantik sampai dengan berakhirnya masa jabatan Kepala Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1206, '3. Isu Strategis adalah kondisi atau hal yang harus diperhatikan atau dikedepankan dalam perencanaan pembangunan daerah karena dampaknya yang signifikan bagi daerah dengan karakteristik bersifat penting, mendasar, mendesak, berjangka menengah/panjang, dan menentukan pencapaian tujuan penyelenggaraan Pemerintah Daerah di masa yang akan datang.
4. Kinerja adalah capaian keluaran/hasil/dampak dari kegiatan/program/ sasaran dari penggunaan sumber daya.
5. Pemaduan adalah upaya memasukkan unsur-unsur penanggulangan bencana ke dalam rencana pembangunan nasional dan daerah.
6. Program adalah penjabaran kebijakan perangkat daerah dalam bentuk upaya yang berisi satu atau lebih kegiatan dengan menggunakan sumber daya yang disediakan untuk mencapai hasil yang terukur sesuai dengan tugas dan fungsi.
7. Program pembangunan Daerah adalah program strategis Daerah yang dilaksanakan oleh Perangkat Daerah sebagai instrumen arah kebijakan untuk mencapai sasaran RPJMD.
8. Risiko bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, mengungsi, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
9. Rencana Pembangunan Jangka Menengah Daerah yang selanjutnya disingkat RPJMD adalah dokumen perencanaan Daerah untuk periode 5 (lima) tahun terhitung sejak dilantik sampai dengan berakhirnya masa jabatan Kepala Daerah.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1207, 'juklak-8-2024', 6, 'lain', 'BAB I (lanjutan 4)', NULL, 3, '10. Sasaran adalah rumusan kondisi yang menggambarkan tercapainya tujuan, berupa hasil penyelenggaraan penanggulangan bencana yang diperoleh dari pencapaian hasil (outcome) program.
11. Sistem Perencanaan Pembangunan adalah satu kesatuan tata cara perencanaan pembangunan untuk menghasilkan rencana-rencana pembangunan dalam jangka panjang, jangka menengah, dan tahunan yang dilaksanakan oleh unsur penyelenggara negara dan masyarakat di tingkat Pusat dan Daerah.
12. Strategi adalah langkah berisikan program-program sebagai prioritas pembangunan daerah/perangkat daerah untuk mencapai sasaran.
13. Tujuan adalah suatu kondisi yang akan dicapai atau dihasilkan dalam jangka waktu 5 (lima) tahun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1207, '10. Sasaran adalah rumusan kondisi yang menggambarkan tercapainya tujuan, berupa hasil penyelenggaraan penanggulangan bencana yang diperoleh dari pencapaian hasil (outcome) program.
11. Sistem Perencanaan Pembangunan adalah satu kesatuan tata cara perencanaan pembangunan untuk menghasilkan rencana-rencana pembangunan dalam jangka panjang, jangka menengah, dan tahunan yang dilaksanakan oleh unsur penyelenggara negara dan masyarakat di tingkat Pusat dan Daerah.
12. Strategi adalah langkah berisikan program-program sebagai prioritas pembangunan daerah/perangkat daerah untuk mencapai sasaran.
13. Tujuan adalah suatu kondisi yang akan dicapai atau dihasilkan dalam jangka waktu 5 (lima) tahun.', 'BAB I (lanjutan 4)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1208, 'juklak-8-2024', 7, 'lain', 'BAB II', NULL, 4, 'KONSEP DAN PRINSIP PEMADUAN A. Konsep dan Prinsip Berdasarkan Pasal 10 ayat (1) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, pemaduan merupakan koordinasi, integrasi, sinergi, dan sinkronisasi unsur-unsur PB ke dalam dokumen perencanaan pembangunan oleh Pemerintah atau Pemerintah Daerah. Pemaduan unsur-unsur PB ke dalam dokumen rencana pembangunan jangka menengah daerah merupakan kegiatan Pemerintah daerah dalam memasukkan atau menyatukan permasalahan dan upaya penanggulangan bencana ke dalam dokumen RPJMD.
Dalam konteks perencanaan pembangunan daerah, unsur PB diintegrasikan ke dalam struktur (bab-bab) pada dokumen RPJMD sampai ke dalam program, sehingga dokumen RPJMD secara sistematis memuat ringkasan analisis permasalahan terkait risiko dan potensi dampak bencana pada sektor. Analisis tersebut menjadi dasar perumusan tujuan, sasaran, strategi, arah kebijakan, dan program serta indikator kinerja dengan target-target pengurangan risiko bencana di daerah.
Pemaduan unsur-unsur PB ke dalam RPJMD dilaksanakan berdasarkan prinsip-prinsip sebagai berikut:
a. Proses pemaduan mengikuti logika dan alur penyusunan perencanaan pembangunan daerah;
b. Proses dan penyusunan substansi pemaduan dilaksanakan secara teknokratis, pendekatan atas-bawah dan bawah-atas serta partisipatif, dan menggunakan pendekatan Tematik, Holistik, Integratif, dan Spasial (THIS);
c. Substansi pemaduan harus tersedia terlebih dahulu sebagai bahan dalam proses pemaduan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1208, 'KONSEP DAN PRINSIP PEMADUAN A. Konsep dan Prinsip Berdasarkan Pasal 10 ayat (1) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, pemaduan merupakan koordinasi, integrasi, sinergi, dan sinkronisasi unsur-unsur PB ke dalam dokumen perencanaan pembangunan oleh Pemerintah atau Pemerintah Daerah. Pemaduan unsur-unsur PB ke dalam dokumen rencana pembangunan jangka menengah daerah merupakan kegiatan Pemerintah daerah dalam memasukkan atau menyatukan permasalahan dan upaya penanggulangan bencana ke dalam dokumen RPJMD.
Dalam konteks perencanaan pembangunan daerah, unsur PB diintegrasikan ke dalam struktur (bab-bab) pada dokumen RPJMD sampai ke dalam program, sehingga dokumen RPJMD secara sistematis memuat ringkasan analisis permasalahan terkait risiko dan potensi dampak bencana pada sektor. Analisis tersebut menjadi dasar perumusan tujuan, sasaran, strategi, arah kebijakan, dan program serta indikator kinerja dengan target-target pengurangan risiko bencana di daerah.
Pemaduan unsur-unsur PB ke dalam RPJMD dilaksanakan berdasarkan prinsip-prinsip sebagai berikut:
a. Proses pemaduan mengikuti logika dan alur penyusunan perencanaan pembangunan daerah;
b. Proses dan penyusunan substansi pemaduan dilaksanakan secara teknokratis, pendekatan atas-bawah dan bawah-atas serta partisipatif, dan menggunakan pendekatan Tematik, Holistik, Integratif, dan Spasial (THIS);
c. Substansi pemaduan harus tersedia terlebih dahulu sebagai bahan dalam proses pemaduan;', 'BAB II', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1209, 'juklak-8-2024', 8, 'lain', 'BAB II (lanjutan 1)', NULL, 4, 'd. Unsur PB diintegrasikan ke dalam semua sektor pembangunan terkait;
e. Proses pemaduan unsur PB dapat menjadi masukan bagi penetapan prioritas dan strategi dalam RPJMD;
f. Proses pemaduan unsur PB dapat membantu meningkatkan koordinasi antar pemangku kepentingan dalam penanggulangan bencana.
B. Unsur-unsur Penanggulangan Bencana untuk Pemaduan
1. Posisi Rencana Penanggulangan Bencana dalam Sistem Perencanaan Pembangunan Daerah Kedudukan Rencana Penanggulangan Bencana (RPB) dalam sistem perencanaan pembangunan daerah perlu dipadukan ke dalam rancangan dokumen RPJMD pada bagian (C) Hubungan antar Dokumen dari Bab I Pendahuluan, hal ini dimaksudkan untuk memberikan gambaran konteks yang jelas tentang pentingnya RPB sebagai bagian dari perencanaan pembangunan.
2. Gambaran Umum Kondisi Kebencanaan Kondisi kebencanaan daerah yang berisi tentang: Informasi Sejarah dan Dampak Bencana; Risiko Bencana; Analisis Potensi Kebencanaan Daerah dari kondisi geografis, geologis, topografis, klimatologis, hidrologis, dan demografis; Telaah Tata Ruang dan Penggunaan Lahan yang Berisiko Bencana; Evaluasi Kinerja Pembangunan Periode Sebelumnya dan Penyajian capaian SPM Sub urusan Bencana di Daerah perlu dipadukan ke dalam rancangan dokumen RPJMD pada Bab II terkait Gambaran Umum Kondisi Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1209, 'd. Unsur PB diintegrasikan ke dalam semua sektor pembangunan terkait;
e. Proses pemaduan unsur PB dapat menjadi masukan bagi penetapan prioritas dan strategi dalam RPJMD;
f. Proses pemaduan unsur PB dapat membantu meningkatkan koordinasi antar pemangku kepentingan dalam penanggulangan bencana.
B. Unsur-unsur Penanggulangan Bencana untuk Pemaduan
1. Posisi Rencana Penanggulangan Bencana dalam Sistem Perencanaan Pembangunan Daerah Kedudukan Rencana Penanggulangan Bencana (RPB) dalam sistem perencanaan pembangunan daerah perlu dipadukan ke dalam rancangan dokumen RPJMD pada bagian (C) Hubungan antar Dokumen dari Bab I Pendahuluan, hal ini dimaksudkan untuk memberikan gambaran konteks yang jelas tentang pentingnya RPB sebagai bagian dari perencanaan pembangunan.
2. Gambaran Umum Kondisi Kebencanaan Kondisi kebencanaan daerah yang berisi tentang: Informasi Sejarah dan Dampak Bencana; Risiko Bencana; Analisis Potensi Kebencanaan Daerah dari kondisi geografis, geologis, topografis, klimatologis, hidrologis, dan demografis; Telaah Tata Ruang dan Penggunaan Lahan yang Berisiko Bencana; Evaluasi Kinerja Pembangunan Periode Sebelumnya dan Penyajian capaian SPM Sub urusan Bencana di Daerah perlu dipadukan ke dalam rancangan dokumen RPJMD pada Bab II terkait Gambaran Umum Kondisi Daerah.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1210, 'juklak-8-2024', 9, 'lain', 'BAB II (lanjutan 2)', NULL, 5, '3. Permasalahan dan Isu Strategis PB Permasalahan pokok dan isu strategis PB daerah perlu dipadukan ke dalam rancangan dokumen RPJMD pada bagian (A) Permasalahan Pembangunan dan (B) Isu Strategis dari Bab IV terkait Permasalahan dan Isu Strategis.
4. Tujuan, Sasaran, Indikator, dan Target Kinerja PB Daerah Tujuan, Sasaran dan Indikator dan Target Kinerja PB Daerah perlu dipadukan ke dalam rancangan dokumen RPJMD pada bagian (E) Tujuan dan Sasaran dari Bab V terkait Visi, Misi, Tujuan dan Sasaran.
5. Strategi, Arah Kebijakan dan Program PB Strategi, Arah Kebijakan dan Program Prioritas PB Daerah perlu dipadukan ke dalam rancangan dokumen RPJMD pada bagian (A) Strategi, (B) Arah Kebijakan Pembangunan, dan (C) Prioritas Program Pembangunan dari Bab VI terkait Strategi, Arah Kebijakan dan Program Pembangunan Daerah.
6. Kinerja Penyelenggaraan Pemerintah Daerah untuk PB Indikator Kinerja Utama PB Daerah perlu dipadukan ke dalam rancangan dokumen RPJMD pada bagian (A) Indikator Kinerja Utama Daerah dari Bab VIII terkait Kinerja Penyelenggaraan Pemerintah Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1210, '3. Permasalahan dan Isu Strategis PB Permasalahan pokok dan isu strategis PB daerah perlu dipadukan ke dalam rancangan dokumen RPJMD pada bagian (A) Permasalahan Pembangunan dan (B) Isu Strategis dari Bab IV terkait Permasalahan dan Isu Strategis.
4. Tujuan, Sasaran, Indikator, dan Target Kinerja PB Daerah Tujuan, Sasaran dan Indikator dan Target Kinerja PB Daerah perlu dipadukan ke dalam rancangan dokumen RPJMD pada bagian (E) Tujuan dan Sasaran dari Bab V terkait Visi, Misi, Tujuan dan Sasaran.
5. Strategi, Arah Kebijakan dan Program PB Strategi, Arah Kebijakan dan Program Prioritas PB Daerah perlu dipadukan ke dalam rancangan dokumen RPJMD pada bagian (A) Strategi, (B) Arah Kebijakan Pembangunan, dan (C) Prioritas Program Pembangunan dari Bab VI terkait Strategi, Arah Kebijakan dan Program Pembangunan Daerah.
6. Kinerja Penyelenggaraan Pemerintah Daerah untuk PB Indikator Kinerja Utama PB Daerah perlu dipadukan ke dalam rancangan dokumen RPJMD pada bagian (A) Indikator Kinerja Utama Daerah dari Bab VIII terkait Kinerja Penyelenggaraan Pemerintah Daerah.', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1211, 'juklak-8-2024', 10, 'lain', 'BAB II (lanjutan 3)', NULL, 5, 'Tabel 1. Unsur PB yang dipadukan ke dalam RPJMD No Struktur RPJMD Unsur-unsur PB Materi Pemaduan (Permendagri No.86/2017) 1 BAB I Pendahuluan Posisi RPB dalam 1. Posisi RPB dalam (C) Hubungan Antar tata kelola Sistem Perencanaan Dokumen perencanaan Pembangunan Daerah 2 BAB II Gambaran Gambaran 1. Informasi Sejarah dan Umum Kondisi Daerah Umum Kondisi Dampak Bencana (A) Aspek Geografi dan Kebencanaan 2. Potensi Risiko Demografi Bencana (B) Aspek Kesejahteraan 3. Analisis Potensi Masyarakat Kebencanaan Daerah
4. Telaah Tata Ruang (C) Aspek Pelayanan dan Penggunaan Umum Urusan Pekerjaan Umum dan Lahan yang Berisiko Bencana Penataan Ruang
5. Evaluasi Kinerja (E) Evaluasi Kinerja Pembangunan Periode Pembangunan Sebelumnya Periode Sebelumnya 6. Penyajian capaian SPM Sub Urusan Bencana 3 BAB IV Permasalahan Permasalahan 1. Permasalahan Pokok dan Isu Strategis dan Isu Strategis PB Daerah (A) Permasalahan PB 2. Isu Strategis Pembangunan Penanggulangan (B) Isu Strategis Bencana 4 Bab V Visi, Misi Tujuan Tujuan, Sasaran, 2. Tujuan PB Daerah dan Sasaran Indikator, dan 3. Sasaran (E) Tujuan dan Sasaran Target Kinerja PB Penanggulangan Daerah Bencana Daerah
4. Target Kinerja PB Daerah No Struktur RPJMD Unsur-unsur PB Materi Pemaduan (Permendagri No.86/2017) 5 Bab VI Strategi, Arah Strategi, Arah 1. Strategi PBDaerah Kebijakan dan Program Kebijakan dan 2. Arah Kebijakan PB Pembangunan Daerah Program PB Daerah, dan (A) Strategi 3. Program Prioritas PB (B) Arah Kebijakan Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1211, 'Tabel 1. Unsur PB yang dipadukan ke dalam RPJMD No Struktur RPJMD Unsur-unsur PB Materi Pemaduan (Permendagri No.86/2017) 1 BAB I Pendahuluan Posisi RPB dalam 1. Posisi RPB dalam (C) Hubungan Antar tata kelola Sistem Perencanaan Dokumen perencanaan Pembangunan Daerah 2 BAB II Gambaran Gambaran 1. Informasi Sejarah dan Umum Kondisi Daerah Umum Kondisi Dampak Bencana (A) Aspek Geografi dan Kebencanaan 2. Potensi Risiko Demografi Bencana (B) Aspek Kesejahteraan 3. Analisis Potensi Masyarakat Kebencanaan Daerah
4. Telaah Tata Ruang (C) Aspek Pelayanan dan Penggunaan Umum Urusan Pekerjaan Umum dan Lahan yang Berisiko Bencana Penataan Ruang
5. Evaluasi Kinerja (E) Evaluasi Kinerja Pembangunan Periode Pembangunan Sebelumnya Periode Sebelumnya 6. Penyajian capaian SPM Sub Urusan Bencana 3 BAB IV Permasalahan Permasalahan 1. Permasalahan Pokok dan Isu Strategis dan Isu Strategis PB Daerah (A) Permasalahan PB 2. Isu Strategis Pembangunan Penanggulangan (B) Isu Strategis Bencana 4 Bab V Visi, Misi Tujuan Tujuan, Sasaran, 2. Tujuan PB Daerah dan Sasaran Indikator, dan 3. Sasaran (E) Tujuan dan Sasaran Target Kinerja PB Penanggulangan Daerah Bencana Daerah
4. Target Kinerja PB Daerah No Struktur RPJMD Unsur-unsur PB Materi Pemaduan (Permendagri No.86/2017) 5 Bab VI Strategi, Arah Strategi, Arah 1. Strategi PBDaerah Kebijakan dan Program Kebijakan dan 2. Arah Kebijakan PB Pembangunan Daerah Program PB Daerah, dan (A) Strategi 3. Program Prioritas PB (B) Arah Kebijakan Daerah.', 'BAB II (lanjutan 3)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1212, 'juklak-8-2024', 11, 'lain', 'BAB II (lanjutan 4)', NULL, 6, 'Pembangunan (C) Prioritas Program Pembangunan 6 Bab VIII Kinerja Kinerja Indikator Kinerja Utama Penyelenggaraan Penyelenggaraan Daerah untuk PB Pemerintah Daerah Pemerintah (A) Indikator Kinerja Daerah Utama/Daerah');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1212, 'Pembangunan (C) Prioritas Program Pembangunan 6 Bab VIII Kinerja Kinerja Indikator Kinerja Utama Penyelenggaraan Penyelenggaraan Daerah untuk PB Pemerintah Daerah Pemerintah (A) Indikator Kinerja Daerah Utama/Daerah', 'BAB II (lanjutan 4)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1213, 'juklak-8-2024', 12, 'lain', 'BAB III', NULL, 7, 'PELAKSANAAN PEMADUAN Tahapan Pemaduan Unsur-Unsur PB ke dalam RPJMD Pemaduan unsur-unsur penanggulangan bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah dilaksanakan melalui tahap-tahap berikut:
1. Tahap Persiapan Tahap ini terdiri dari:
a. Pembentukan Tim Pemaduan Pemaduan unsur-unsur PB ke dalam RPJMD merupakan proses yang membutuhkan partisipasi seluruh unsur pemangku kepentingan daerah.
Untuk itu, dibentuk tim yang dikoordinasikan oleh BPBD dan sekurang-kurangnya melibatkan unsur Bappeda, OPD pengelola data statistik daerah dan Forum PRB. Tim ini bertugas untuk menyusun telaah atau ringkasan materi PB dan melakukan advokasi kepada pimpinan daerah termasuk tim penyusunan RPJMD untuk memastikan agar unsur-unsur PB dipadukan ke dalam dokumen RPJMD. Tim sebagaimana dimaksud dibentuk oleh Kepala BPBD atau Kepala Pelaksana BPBD.
b. Pengumpulan dan Analisis Data dan Informasi Pendukung Pengumpulan dan analisis data-informasi pendukung dilakukan oleh Tim.
Data dan informasi yang dibutuhkan adalah:
1) Informasi kawasan rawan bencana, karakteristik ancaman bencana dan risiko bencana.
2) Sejarah kejadian dan dampak Bencana.
3) Permasalahan dan isu-isu strategis kebencanaan.
4) Tujuan, sasaran, strategi, arah kebijakan dan program penanggulangan bencana.
5) Capaian Indeks Risiko Bencana (IRBI) dan Indeks Ketahanan Daerah (IKD).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1213, 'PELAKSANAAN PEMADUAN Tahapan Pemaduan Unsur-Unsur PB ke dalam RPJMD Pemaduan unsur-unsur penanggulangan bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah dilaksanakan melalui tahap-tahap berikut:
1. Tahap Persiapan Tahap ini terdiri dari:
a. Pembentukan Tim Pemaduan Pemaduan unsur-unsur PB ke dalam RPJMD merupakan proses yang membutuhkan partisipasi seluruh unsur pemangku kepentingan daerah.
Untuk itu, dibentuk tim yang dikoordinasikan oleh BPBD dan sekurang-kurangnya melibatkan unsur Bappeda, OPD pengelola data statistik daerah dan Forum PRB. Tim ini bertugas untuk menyusun telaah atau ringkasan materi PB dan melakukan advokasi kepada pimpinan daerah termasuk tim penyusunan RPJMD untuk memastikan agar unsur-unsur PB dipadukan ke dalam dokumen RPJMD. Tim sebagaimana dimaksud dibentuk oleh Kepala BPBD atau Kepala Pelaksana BPBD.
b. Pengumpulan dan Analisis Data dan Informasi Pendukung Pengumpulan dan analisis data-informasi pendukung dilakukan oleh Tim.
Data dan informasi yang dibutuhkan adalah:
1) Informasi kawasan rawan bencana, karakteristik ancaman bencana dan risiko bencana.
2) Sejarah kejadian dan dampak Bencana.
3) Permasalahan dan isu-isu strategis kebencanaan.
4) Tujuan, sasaran, strategi, arah kebijakan dan program penanggulangan bencana.
5) Capaian Indeks Risiko Bencana (IRBI) dan Indeks Ketahanan Daerah (IKD).', 'BAB III', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1214, 'juklak-8-2024', 13, 'lain', 'BAB III (lanjutan 1)', NULL, 7, 'Data dan informasi di atas dapat ditemukan dalam dokumen-dokumen seperti: Kajian Risiko Bencana (KRB), Rencana Penanggulangan Bencana (RPB), Rencana Tata Ruang Wilayah (RTRW), Kajian Lingkungan Hidup Strategis (KLHS), Evaluasi RPJMD periode sebelumnya dan hasil-hasil penelitian terkait yang diterbitkan oleh perguruan tinggi atau lembaga penelitian.
2. Tahap Penyiapan Materi Pemaduan
a. Penyiapan dan penyusunan materi pemaduan dilakukan oleh Tim Pemaduan.
b. Waktu penyiapan materi pemaduan dilaksanakan sekurang-kurangnya satu bulan sebelum proses penyusunan RPJMD dimulai.
c. Materi pemaduan disajikan dalam bentuk telaah atau ringkasan materi pemaduan.
d. Tim Pemaduan menggunakan langkah-langkah penyusunan materi pemaduan pada Bab IV Petunjuk Pelaksanaan ini
3. Tahap Pelaksanaan Pemaduan PB ke dalam RPJMD Pelaksanaan pemaduan dikoordinasikan oleh Bappeda dengan melibatkan BPBD. Proses pemaduan dilaksanakan melalui dua tahap sebagai berikut:
a. Penyampaian hasil telaah atau ringkasan materi pemaduan Hasil telaah atau ringkasan materi pemaduan disampaikan kepada pimpinan daerah dan atau sekretaris daerah dengan tembusan Bappeda melalui nota dinas/telaah staf dari Kepala BPBD atau Kepala Pelaksana BPBD untuk disampaikan dalam rangka memberikan gambaran kepada Bappeda dan tim penyusun RPJMD. format hasil telaah/ringkasan materi pemaduan Unsur-unsur Penanggulangan Bencana tercantum pada Poin A Lampiran 1 Petunjuk Pelaksanaan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1214, 'Data dan informasi di atas dapat ditemukan dalam dokumen-dokumen seperti: Kajian Risiko Bencana (KRB), Rencana Penanggulangan Bencana (RPB), Rencana Tata Ruang Wilayah (RTRW), Kajian Lingkungan Hidup Strategis (KLHS), Evaluasi RPJMD periode sebelumnya dan hasil-hasil penelitian terkait yang diterbitkan oleh perguruan tinggi atau lembaga penelitian.
2. Tahap Penyiapan Materi Pemaduan
a. Penyiapan dan penyusunan materi pemaduan dilakukan oleh Tim Pemaduan.
b. Waktu penyiapan materi pemaduan dilaksanakan sekurang-kurangnya satu bulan sebelum proses penyusunan RPJMD dimulai.
c. Materi pemaduan disajikan dalam bentuk telaah atau ringkasan materi pemaduan.
d. Tim Pemaduan menggunakan langkah-langkah penyusunan materi pemaduan pada Bab IV Petunjuk Pelaksanaan ini
3. Tahap Pelaksanaan Pemaduan PB ke dalam RPJMD Pelaksanaan pemaduan dikoordinasikan oleh Bappeda dengan melibatkan BPBD. Proses pemaduan dilaksanakan melalui dua tahap sebagai berikut:
a. Penyampaian hasil telaah atau ringkasan materi pemaduan Hasil telaah atau ringkasan materi pemaduan disampaikan kepada pimpinan daerah dan atau sekretaris daerah dengan tembusan Bappeda melalui nota dinas/telaah staf dari Kepala BPBD atau Kepala Pelaksana BPBD untuk disampaikan dalam rangka memberikan gambaran kepada Bappeda dan tim penyusun RPJMD. format hasil telaah/ringkasan materi pemaduan Unsur-unsur Penanggulangan Bencana tercantum pada Poin A Lampiran 1 Petunjuk Pelaksanaan', 'BAB III (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1215, 'juklak-8-2024', 14, 'lain', 'BAB III (lanjutan 2)', NULL, 8, 'b. Pengawalan pelaksanaan pemaduan PB ke dalam penyusunan RPJMD Pengawalan hasil telaah atau ringkasan materi pemaduan dilaksanakan untuk memastikan agar unsur penanggulangan bencana terakomodasi pada bab-bab terkait di dalam dokumen RPJMD, sejak tahap rancangan teknokratis, rancangan awal, rancangan sampai pada rancangan akhir.
Pengawalan dapat dilakukan melalui dua pendekatan yaitu:
1) Pendekatan teknokratis melalui wakil-wakil BPBD dan Bappeda yang berada dalam tim penyusun untuk ikut serta dalam seluruh tahapan penyusunan dokumen RPJMD dan;
2) Pendekatan partisipatif dapat dilaksanakan melalui Forum Perangkat Daerah saat rancangan awal RPJMD, Musrenbang saat penyusunan rancangan RPJMD dan forum-forum tematik yang diselenggarakan dalam rangka penyusunan RPJMD.
4. Tahap Pengendalian dan Pelaporan Pemaduan Pengendalian dan pelaporan pemaduan dilakukan untuk memastikan agar unsur-unsur penanggulangan bencana benar-benar dipadukan ke dalam dokumen RPJMD. Pengendalian dan pelaporan dilaksanakan pada setiap tahapan penyusunan RPJMD dan setelah RPJMD ditetapkan. Proses ini dikoordinasikan oleh BPBD bersama Bappeda dengan cara:
a. Bappeda selaku tim penyusun RPJMD melakukan proses Pengendalian dan Pelaporan secara menyeluruh sesuai dengan ketentuan peraturan perundang-undangan.
b. BPBD melakukan proses Pengendalian dan Pelaporan berkoordinasi dengan Bappeda selaku tim penyusun RPJMD dengan menggunakan Form pada Poin B Lampiran Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1215, 'b. Pengawalan pelaksanaan pemaduan PB ke dalam penyusunan RPJMD Pengawalan hasil telaah atau ringkasan materi pemaduan dilaksanakan untuk memastikan agar unsur penanggulangan bencana terakomodasi pada bab-bab terkait di dalam dokumen RPJMD, sejak tahap rancangan teknokratis, rancangan awal, rancangan sampai pada rancangan akhir.
Pengawalan dapat dilakukan melalui dua pendekatan yaitu:
1) Pendekatan teknokratis melalui wakil-wakil BPBD dan Bappeda yang berada dalam tim penyusun untuk ikut serta dalam seluruh tahapan penyusunan dokumen RPJMD dan;
2) Pendekatan partisipatif dapat dilaksanakan melalui Forum Perangkat Daerah saat rancangan awal RPJMD, Musrenbang saat penyusunan rancangan RPJMD dan forum-forum tematik yang diselenggarakan dalam rangka penyusunan RPJMD.
4. Tahap Pengendalian dan Pelaporan Pemaduan Pengendalian dan pelaporan pemaduan dilakukan untuk memastikan agar unsur-unsur penanggulangan bencana benar-benar dipadukan ke dalam dokumen RPJMD. Pengendalian dan pelaporan dilaksanakan pada setiap tahapan penyusunan RPJMD dan setelah RPJMD ditetapkan. Proses ini dikoordinasikan oleh BPBD bersama Bappeda dengan cara:
a. Bappeda selaku tim penyusun RPJMD melakukan proses Pengendalian dan Pelaporan secara menyeluruh sesuai dengan ketentuan peraturan perundang-undangan.
b. BPBD melakukan proses Pengendalian dan Pelaporan berkoordinasi dengan Bappeda selaku tim penyusun RPJMD dengan menggunakan Form pada Poin B Lampiran Petunjuk Pelaksanaan.', 'BAB III (lanjutan 2)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1216, 'juklak-8-2024', 15, 'lain', 'BAB III (lanjutan 3)', NULL, 8, 'c. Pelaporan Pemaduan dilakukan setelah RPJMD ditetapkan.
d. BPBD Provinsi menyampaikan laporan pemaduan PB ke dalam RPJMD kepada BNPB melalui Deputi Bidang Sistem dan Strategi dengan tembusan Kemendagri pada Direktorat Jenderal Bina Administrasi Wilayah dan Direktorat Jenderal Bina Pembangunan Daerah
e. BPBD Kabupaten/Kota menyampaikan laporan pemaduan PB ke dalam RPJMD kepada Pemerintah Provinsi dengan tembusan Deputi Bidang Sistem dan Strategi BNPB dan Direktorat Jenderal Bina Administrasi Wilayah dan Direktorat Jenderal Bina Pembangunan Daerah Kemendagri.
Format pengendalian dan pemantauan pemaduan tercantum dalam Poin B Lampiran 1 Petunjuk Pelaksanaan.
Secara keseluruhan tahapan pemaduan Unsur-Unsur Penanggulangan Bencana ke dalam RPJMD tersusun dalam bagan sebagai berikut:
Gambar 1. Tahapan Pemaduan Unsur-Unsur PB ke dalam RPJMD');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1216, 'c. Pelaporan Pemaduan dilakukan setelah RPJMD ditetapkan.
d. BPBD Provinsi menyampaikan laporan pemaduan PB ke dalam RPJMD kepada BNPB melalui Deputi Bidang Sistem dan Strategi dengan tembusan Kemendagri pada Direktorat Jenderal Bina Administrasi Wilayah dan Direktorat Jenderal Bina Pembangunan Daerah
e. BPBD Kabupaten/Kota menyampaikan laporan pemaduan PB ke dalam RPJMD kepada Pemerintah Provinsi dengan tembusan Deputi Bidang Sistem dan Strategi BNPB dan Direktorat Jenderal Bina Administrasi Wilayah dan Direktorat Jenderal Bina Pembangunan Daerah Kemendagri.
Format pengendalian dan pemantauan pemaduan tercantum dalam Poin B Lampiran 1 Petunjuk Pelaksanaan.
Secara keseluruhan tahapan pemaduan Unsur-Unsur Penanggulangan Bencana ke dalam RPJMD tersusun dalam bagan sebagai berikut:
Gambar 1. Tahapan Pemaduan Unsur-Unsur PB ke dalam RPJMD', 'BAB III (lanjutan 3)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1217, 'juklak-8-2024', 16, 'lain', 'BAB IV', NULL, 9, 'PENYUSUNAN TELAAH ATAU RINGKASAN MATERI PEMADUAN Dalam rangka memberikan gambaran bagi pimpinan daerah dan instansi yang menyelenggarakan fungsi pemerintahan terkait dengan perencanaan pembangunan daerah, diperlukan telaah/ringkasan materi pemaduan.
A. Penyusunan Telaah/Ringkasan Materi Pemaduan Kerangka penyusunan telaah/ringkasan materi unsur-unsur penanggulangan bencana yang akan dipadukan ke dalam RPJMD adalah sebagai berikut:
1. Posisi Rencana PB dalam Sistem Perencanaan Pembangunan Daerah Pada bagian ini Tim Pemaduan menyajikan gambar struktur posisi RPB dalam sistem perencanaan pembangunan daerah dan hubungannya dengan perencanaan lainnya mulai dari RIPB, Renas PB, dan RPJMN sampai RPJMD dan RTRW Daerah. Gambar selanjutnya dilengkapi dengan narasi singkat tentang hubungan RPB dengan berbagai instrumen perencanaan dan pentingnya memadukan RPB ke dalam RPJMD. Perlu ditekankan juga kedudukan RPB sebagai bagian dari perencanaan pembangunan. Gambar dan narasi kemudian dipadukan ke dalam rancangan RPJMD pada bagian (C) Hubungan antar Dokumen dari Bab I Pendahuluan.
2. Gambaran Umum Kondisi Kebencanaan
a. Karakteristik kebencanaan daerah Pada bagian ini Tim Pemaduan pertama-tama menyusun uraian tentang karakteristik kebencanaan daerah dilihat dari kondisi geografis, geologis, topografis, klimatologis, hidrologis, dan demografis sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1217, 'PENYUSUNAN TELAAH ATAU RINGKASAN MATERI PEMADUAN Dalam rangka memberikan gambaran bagi pimpinan daerah dan instansi yang menyelenggarakan fungsi pemerintahan terkait dengan perencanaan pembangunan daerah, diperlukan telaah/ringkasan materi pemaduan.
A. Penyusunan Telaah/Ringkasan Materi Pemaduan Kerangka penyusunan telaah/ringkasan materi unsur-unsur penanggulangan bencana yang akan dipadukan ke dalam RPJMD adalah sebagai berikut:
1. Posisi Rencana PB dalam Sistem Perencanaan Pembangunan Daerah Pada bagian ini Tim Pemaduan menyajikan gambar struktur posisi RPB dalam sistem perencanaan pembangunan daerah dan hubungannya dengan perencanaan lainnya mulai dari RIPB, Renas PB, dan RPJMN sampai RPJMD dan RTRW Daerah. Gambar selanjutnya dilengkapi dengan narasi singkat tentang hubungan RPB dengan berbagai instrumen perencanaan dan pentingnya memadukan RPB ke dalam RPJMD. Perlu ditekankan juga kedudukan RPB sebagai bagian dari perencanaan pembangunan. Gambar dan narasi kemudian dipadukan ke dalam rancangan RPJMD pada bagian (C) Hubungan antar Dokumen dari Bab I Pendahuluan.
2. Gambaran Umum Kondisi Kebencanaan
a. Karakteristik kebencanaan daerah Pada bagian ini Tim Pemaduan pertama-tama menyusun uraian tentang karakteristik kebencanaan daerah dilihat dari kondisi geografis, geologis, topografis, klimatologis, hidrologis, dan demografis sebagai berikut:', 'BAB IV', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1218, 'juklak-8-2024', 17, 'lain', 'BAB IV (lanjutan 1)', NULL, 9, '• Aspek geografis berisi uraian tentang kondisi lingkungan alam dari Provinsi/Kabupaten/Kota bersangkutan, misalnya apakah secara geografis terdapat gunung api aktif yang berpotensi mengalami erupsi dan menyebabkan kebakaran hutan/lahan serta banjir lahar hujan.
• Aspek geologis berisi uraian tentang struktur tanah dan bebatuan di bawah permukaan bumi di Provinsi/Kabupaten/kota bersangkutan, misalnya apakah terdapat sesar aktif yang berpotensi memicu aktivitas kegempaan dan/atau aktivitas vulkanik.
• Aspek topografis berisi uraian tentang letak atau lokasi suatu Provinsi/Kabupaten/Kota dan bentuk muka buminya, misalnya daerah yang terdiri dari pegunungan dengan lereng-lereng curam berpotensi mengalami longsor ketika ditimpa hujan dengan intensitas ekstrem.
• Aspek hidrologis berisi uraian tentang hal-hal yang terkait dengan tata air di Provinsi/Kabupaten/Kota terutama berkaitan dengan kondisi Daerah Aliran Sungai di daerah tersebut sebagai faktor yang sangat menentukan potensi banjir dan kekeringan.
• Aspek klimatologis berisi uraian tentang kondisi iklim di Provinsi/Kabupaten/Kota yang menentukan pola musim, misalnya musim hujan dan musim kemarau, yang dapat berpengaruh pada sektor pertanian, perikanan dan bidang-bidang lainnya.
• Aspek demografis berisi uraian tentang profil dan perkiraan jumlah penduduk di Provinsi/Kota. Sebaran penduduk yang tinggal di daerah rawan bencana dapat menggambarkan potensi keterpaparan dan kerentanan warga terhadap ancaman bencana tertentu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1218, '• Aspek geografis berisi uraian tentang kondisi lingkungan alam dari Provinsi/Kabupaten/Kota bersangkutan, misalnya apakah secara geografis terdapat gunung api aktif yang berpotensi mengalami erupsi dan menyebabkan kebakaran hutan/lahan serta banjir lahar hujan.
• Aspek geologis berisi uraian tentang struktur tanah dan bebatuan di bawah permukaan bumi di Provinsi/Kabupaten/kota bersangkutan, misalnya apakah terdapat sesar aktif yang berpotensi memicu aktivitas kegempaan dan/atau aktivitas vulkanik.
• Aspek topografis berisi uraian tentang letak atau lokasi suatu Provinsi/Kabupaten/Kota dan bentuk muka buminya, misalnya daerah yang terdiri dari pegunungan dengan lereng-lereng curam berpotensi mengalami longsor ketika ditimpa hujan dengan intensitas ekstrem.
• Aspek hidrologis berisi uraian tentang hal-hal yang terkait dengan tata air di Provinsi/Kabupaten/Kota terutama berkaitan dengan kondisi Daerah Aliran Sungai di daerah tersebut sebagai faktor yang sangat menentukan potensi banjir dan kekeringan.
• Aspek klimatologis berisi uraian tentang kondisi iklim di Provinsi/Kabupaten/Kota yang menentukan pola musim, misalnya musim hujan dan musim kemarau, yang dapat berpengaruh pada sektor pertanian, perikanan dan bidang-bidang lainnya.
• Aspek demografis berisi uraian tentang profil dan perkiraan jumlah penduduk di Provinsi/Kota. Sebaran penduduk yang tinggal di daerah rawan bencana dapat menggambarkan potensi keterpaparan dan kerentanan warga terhadap ancaman bencana tertentu.', 'BAB IV (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1219, 'juklak-8-2024', 18, 'lain', 'BAB IV (lanjutan 2)', NULL, 10, 'Data dan informasi Aspek-aspek kondisi daerah tersebut dapat diperoleh dari:
• bagi Daerah yang telah Memiliki KRB dan RPB yang masih berlaku diambil dari Bab III dokumen KRB dan Bab II dokumen RPB yang terdiri dari aspek: (a) Geografi (b) Geologi (c) Topografi (d) Hidrologi (e) Klimatologi (f) Demografi.
• bagi daerah yang habis masa berlaku KRB/RPB-nya diambil dari Bab III KRB dan Bab II RPB periode sebelumnya.
• bagi daerah yang belum memiliki KRB/RPB dan habis masa berlaku KRB/RPB-nya diambil dari Bab II dokumen KLHS terkait gambaran umum wilayah, Bab II dokumen RPJMD gambaran umum kondisi wilayah.
b. Informasi sejarah kejadian dan dampak bencana Tim Pemaduan menyusun uraian tentang informasi sejarah kejadian dan dampak bencana di Provinsi/Kabupaten/Kota sebagai berikut:
• Sejarah kejadian dan dampak bencana: uraian tentang kejadian bencana historis berupa jumlah serta besaran dampak yang ditimbulkan yang dapat dijadikan sebagai alat bantu pemahaman terhadap kecenderungan kejadian bencana, bahaya, kerentanan, kapasitas, paparan, dan kerusakan lingkungan.
Format Penyajian Data Sejarah dan Dampak Kejadian Bencana tercantum dalam Poin A Lampiran II Petunjuk Pelaksanaan.
• Penduduk yang terpapar ancaman bencana: uraian tentang data dan informasi total jumlah penduduk terpapar berbagai ancaman yang ada di Provinsi/Kabupaten/Kota.
Format Penyajian Jumlah Penduduk Terpapar Ancaman Bencana tercantum dalam Poin B Lampiran II Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1219, 'Data dan informasi Aspek-aspek kondisi daerah tersebut dapat diperoleh dari:
• bagi Daerah yang telah Memiliki KRB dan RPB yang masih berlaku diambil dari Bab III dokumen KRB dan Bab II dokumen RPB yang terdiri dari aspek: (a) Geografi (b) Geologi (c) Topografi (d) Hidrologi (e) Klimatologi (f) Demografi.
• bagi daerah yang habis masa berlaku KRB/RPB-nya diambil dari Bab III KRB dan Bab II RPB periode sebelumnya.
• bagi daerah yang belum memiliki KRB/RPB dan habis masa berlaku KRB/RPB-nya diambil dari Bab II dokumen KLHS terkait gambaran umum wilayah, Bab II dokumen RPJMD gambaran umum kondisi wilayah.
b. Informasi sejarah kejadian dan dampak bencana Tim Pemaduan menyusun uraian tentang informasi sejarah kejadian dan dampak bencana di Provinsi/Kabupaten/Kota sebagai berikut:
• Sejarah kejadian dan dampak bencana: uraian tentang kejadian bencana historis berupa jumlah serta besaran dampak yang ditimbulkan yang dapat dijadikan sebagai alat bantu pemahaman terhadap kecenderungan kejadian bencana, bahaya, kerentanan, kapasitas, paparan, dan kerusakan lingkungan.
Format Penyajian Data Sejarah dan Dampak Kejadian Bencana tercantum dalam Poin A Lampiran II Petunjuk Pelaksanaan.
• Penduduk yang terpapar ancaman bencana: uraian tentang data dan informasi total jumlah penduduk terpapar berbagai ancaman yang ada di Provinsi/Kabupaten/Kota.
Format Penyajian Jumlah Penduduk Terpapar Ancaman Bencana tercantum dalam Poin B Lampiran II Petunjuk Pelaksanaan.', 'BAB IV (lanjutan 2)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1220, 'juklak-8-2024', 19, 'lain', 'BAB IV (lanjutan 3)', NULL, 10, '• Potensi kerusakan dan kerugian akibat bencana: uraian tentang data dan informasi potensi kerusakan dan kerugian dalam hal fisik, ekonomi dan lingkungan, berdasarkan berbagai jenis ancaman bencana yang ada di Provinsi/Kabupaten/Kota.
Format Penyajian Data Potensi kerusakan lingkungan dan kerugian akibat bencana tercantum dalam Poin C Lampiran II Petunjuk Pelaksanaan.
• Luas wilayah berpotensi terdampak bencana: uraian tentang data dan informasi total luas wilayah (hektar) di Provinsi/Kabupaten/Kota yang berpotensi terdampak berbagai jenis bencana.
Format Penyajian Potensi luas wilayah tedampak bencana tercantum dalam Poin D Lampiran II Petunjuk Pelaksanaan.
• Informasi tingkat risiko bencana di daerah: uraian tentang probabilitas dan kecenderungan atau besaran dampak dari setiap bencana yang dapat terjadi di Provinsi/Kabupaten/Kota.
Format Penyajian Tata tingkat risiko bencana tercantum dalam Poin E Lampiran II Petunjuk Pelaksanaan.
Data dan informasi risiko bencana serta sejarah kebencanaan di daerah yang bersumber dari:
• bagi daerah yang memiliki KRB dan RPB yang masih berlaku diambil dari Bab III Dokumen KRB dan Bab II RPB di antaranya: (a) Sejarah kejadian dan dampak bencana; (b) Deskripsi penduduk terpapar ancaman bencana (c) Deskripsi potensi kerusakan dan kerugian akibat bencana; (d) Deskripsi potensi luas wilayah terdampak bencana; (e) Informasi tingkat risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1220, '• Potensi kerusakan dan kerugian akibat bencana: uraian tentang data dan informasi potensi kerusakan dan kerugian dalam hal fisik, ekonomi dan lingkungan, berdasarkan berbagai jenis ancaman bencana yang ada di Provinsi/Kabupaten/Kota.
Format Penyajian Data Potensi kerusakan lingkungan dan kerugian akibat bencana tercantum dalam Poin C Lampiran II Petunjuk Pelaksanaan.
• Luas wilayah berpotensi terdampak bencana: uraian tentang data dan informasi total luas wilayah (hektar) di Provinsi/Kabupaten/Kota yang berpotensi terdampak berbagai jenis bencana.
Format Penyajian Potensi luas wilayah tedampak bencana tercantum dalam Poin D Lampiran II Petunjuk Pelaksanaan.
• Informasi tingkat risiko bencana di daerah: uraian tentang probabilitas dan kecenderungan atau besaran dampak dari setiap bencana yang dapat terjadi di Provinsi/Kabupaten/Kota.
Format Penyajian Tata tingkat risiko bencana tercantum dalam Poin E Lampiran II Petunjuk Pelaksanaan.
Data dan informasi risiko bencana serta sejarah kebencanaan di daerah yang bersumber dari:
• bagi daerah yang memiliki KRB dan RPB yang masih berlaku diambil dari Bab III Dokumen KRB dan Bab II RPB di antaranya: (a) Sejarah kejadian dan dampak bencana; (b) Deskripsi penduduk terpapar ancaman bencana (c) Deskripsi potensi kerusakan dan kerugian akibat bencana; (d) Deskripsi potensi luas wilayah terdampak bencana; (e) Informasi tingkat risiko bencana.', 'BAB IV (lanjutan 3)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1221, 'juklak-8-2024', 20, 'lain', 'BAB IV (lanjutan 4)', NULL, 11, '• bagi daerah yang belum memiliki atau habis masa berlakunya KRB/RPB diambil dari Bab VII dokumen RTRW Daerah terkait kawasan rawan bencana, Bab II Renstra BPBD terkait pelayanan perangkat daerah, Bab II RPJMD periode sebelumnya terkait gambaran umum wilayah dan dapat mengambil dari DIBI BNPB (htttp://dibi.bnpb.go.id). Informasi risiko bencana pada website https://inarisk.bnpb.go.id/webgis.
Ketentuan Pengambilan Data dan Informasi terkait dengan daerah yang belum memiliki atau habis masa berlakunya KRB/RPB dilaksanakan sesuai Lampiran IV Petunjuk Pelaksanaan.
• Informasi sejarah kebencanaan dapat diambil dari DIBI BNPB (htttp://dibi.bnpb.go.id) atau pencatatan data di Pemerintah Daerah.
c. Identifikasi risiko bencana terkait aspek tata ruang Tim Pemaduan juga mendeskripsikan risiko bencana terkait aspek tata ruang yang diidentifikasi dari dari dokumen Bab VII dokumen RTRW Daerah terkait kawasan rawan bencana. Ini dilaksanakan dengan menganalisis karakteristik ancaman berdasarkan tren pemanfaatan lahan dan tata ruang yang berpotensi meningkatkan risiko bencana
d. Evaluasi kinerja pembangunan daerah Tim Pemaduan menyusun ringkasan evaluasi kinerja pembangunan daerah dalam bidang penanggulangan bencana melalui capaian Indeks Risiko Bencana (IRBI) dan Indeks Ketahanan Daerah (IKD). Ringkasan ini menyajikan data dasar (baseline) dan time series penurunan nilai IRBI dan peningkatan nilai IKD periode 5 tahun terakhir.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1221, '• bagi daerah yang belum memiliki atau habis masa berlakunya KRB/RPB diambil dari Bab VII dokumen RTRW Daerah terkait kawasan rawan bencana, Bab II Renstra BPBD terkait pelayanan perangkat daerah, Bab II RPJMD periode sebelumnya terkait gambaran umum wilayah dan dapat mengambil dari DIBI BNPB (htttp://dibi.bnpb.go.id). Informasi risiko bencana pada website https://inarisk.bnpb.go.id/webgis.
Ketentuan Pengambilan Data dan Informasi terkait dengan daerah yang belum memiliki atau habis masa berlakunya KRB/RPB dilaksanakan sesuai Lampiran IV Petunjuk Pelaksanaan.
• Informasi sejarah kebencanaan dapat diambil dari DIBI BNPB (htttp://dibi.bnpb.go.id) atau pencatatan data di Pemerintah Daerah.
c. Identifikasi risiko bencana terkait aspek tata ruang Tim Pemaduan juga mendeskripsikan risiko bencana terkait aspek tata ruang yang diidentifikasi dari dari dokumen Bab VII dokumen RTRW Daerah terkait kawasan rawan bencana. Ini dilaksanakan dengan menganalisis karakteristik ancaman berdasarkan tren pemanfaatan lahan dan tata ruang yang berpotensi meningkatkan risiko bencana
d. Evaluasi kinerja pembangunan daerah Tim Pemaduan menyusun ringkasan evaluasi kinerja pembangunan daerah dalam bidang penanggulangan bencana melalui capaian Indeks Risiko Bencana (IRBI) dan Indeks Ketahanan Daerah (IKD). Ringkasan ini menyajikan data dasar (baseline) dan time series penurunan nilai IRBI dan peningkatan nilai IKD periode 5 tahun terakhir.', 'BAB IV (lanjutan 4)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1222, 'juklak-8-2024', 21, 'lain', 'BAB IV (lanjutan 5)', NULL, 11, 'Format Penyajian Data Indeks Risiko Bencana dan Indeks Ketahanan Daerah tercantum dalam Poin F Lampiran II Petunjuk Pelaksanaan.
e. Penyajian capaian SPM Sub urusan Bencana di Daerah Tim Pemaduan menyusun ringkasan penyajian capaian SPM daerah berdasarkan jenis dan mutu layanan urusan bencana yang berhak diterima oleh masyarakat, yaitu; Jumlah warga negara yang memperoleh layanan informasi rawan bencana, Jumlah warga negara yang memperoleh layanan pencegahan dan kesiapsiagaan terhadap bencana dan Jumlah warga negara yang memperoleh layanan penyelamatan dan evakuasi korban bencana.
Format Penyajian Data capaian SPM Daerah tercantum dalam Poin G Lampiran II Petunjuk Pelaksanaan.
3. Permasalahan dan Isu Strategis PB Permasalahan dan isu strategis kebencanaan daerah mencakup masalah pokok PB dan isu strategis PB daerah sebagai berikut:
a. Masalah pokok PB Tim Pemaduan merumuskan daftar dan deskripsi masalah pokok atau masalah utama dalam penanggulangan bencana di Provinsi/Kabupaten/Kota. Masalah pokok juga dapat berarti faktor pemicu yang mengharuskan pemerintah Provinsi/Kabupaten/Kota melakukan pengelolaan risiko untuk ancaman-ancaman bencana prioritas untuk melindungi warga dan hasil-hasil pembangunan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1222, 'Format Penyajian Data Indeks Risiko Bencana dan Indeks Ketahanan Daerah tercantum dalam Poin F Lampiran II Petunjuk Pelaksanaan.
e. Penyajian capaian SPM Sub urusan Bencana di Daerah Tim Pemaduan menyusun ringkasan penyajian capaian SPM daerah berdasarkan jenis dan mutu layanan urusan bencana yang berhak diterima oleh masyarakat, yaitu; Jumlah warga negara yang memperoleh layanan informasi rawan bencana, Jumlah warga negara yang memperoleh layanan pencegahan dan kesiapsiagaan terhadap bencana dan Jumlah warga negara yang memperoleh layanan penyelamatan dan evakuasi korban bencana.
Format Penyajian Data capaian SPM Daerah tercantum dalam Poin G Lampiran II Petunjuk Pelaksanaan.
3. Permasalahan dan Isu Strategis PB Permasalahan dan isu strategis kebencanaan daerah mencakup masalah pokok PB dan isu strategis PB daerah sebagai berikut:
a. Masalah pokok PB Tim Pemaduan merumuskan daftar dan deskripsi masalah pokok atau masalah utama dalam penanggulangan bencana di Provinsi/Kabupaten/Kota. Masalah pokok juga dapat berarti faktor pemicu yang mengharuskan pemerintah Provinsi/Kabupaten/Kota melakukan pengelolaan risiko untuk ancaman-ancaman bencana prioritas untuk melindungi warga dan hasil-hasil pembangunan.', 'BAB IV (lanjutan 5)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1223, 'juklak-8-2024', 22, 'lain', 'BAB IV (lanjutan 6)', NULL, 12, 'Informasi rumusan akar masalah/masalah pokok penanggulangan bencana dapat diambil dari Bab II Dokumen RPB bagi daerah yang telah memiliki dan aktif. Bagi daerah yang belum memiliki atau habis masa berlakunya KRB/RPB dapat mengidentifikasi akar masalah/masalah pokok penanggulangan bencana daerah berdasarkan berdasarkan keterpaparan risiko bencana, nilai terendah Indeks Ketahanan Daerah dan kesenjangan pencapaian pembangunan daerah terkait penanggulangan bencana bagi daerah yang belum memiliki atau habis masa berlaku KRB/RPB-nya.
Format Penyajian Daftar Identifikasi Masalah Pokok PB tercantum dalam Poin H Lampiran II Petunjuk Pelaksanaan.
b. Isu strategis PB Tim Pemaduan menyusun daftar dan deskripsi isu strategis PB daerah.
Isu strategis PB daerah adalah pilihan masalah yang dianggap sangat penting untuk diselesaikan melalui program-program pengurangan risiko bencana dalam lima tahun ke depan. Isu strategis juga dimengerti sebagai kondisi atau hal yang harus diperhatikan atau dikedepankan dalam perencanaan pembangunan daerah karena dampaknya yang signifikan bagi daerah; memiliki karakteristik penting, mendasar, mendesak, berjangka menengah dan/atau panjang dan menentukan pencapaian tujuan penyelenggaraan pemerintah daerah di masa yang akan datang.
Informasi isu strategis kebencanaan Daerah dapat diambil dari Bab II Dokumen RPB bagi daerah yang telah memiliki dan aktif.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1223, 'Informasi rumusan akar masalah/masalah pokok penanggulangan bencana dapat diambil dari Bab II Dokumen RPB bagi daerah yang telah memiliki dan aktif. Bagi daerah yang belum memiliki atau habis masa berlakunya KRB/RPB dapat mengidentifikasi akar masalah/masalah pokok penanggulangan bencana daerah berdasarkan berdasarkan keterpaparan risiko bencana, nilai terendah Indeks Ketahanan Daerah dan kesenjangan pencapaian pembangunan daerah terkait penanggulangan bencana bagi daerah yang belum memiliki atau habis masa berlaku KRB/RPB-nya.
Format Penyajian Daftar Identifikasi Masalah Pokok PB tercantum dalam Poin H Lampiran II Petunjuk Pelaksanaan.
b. Isu strategis PB Tim Pemaduan menyusun daftar dan deskripsi isu strategis PB daerah.
Isu strategis PB daerah adalah pilihan masalah yang dianggap sangat penting untuk diselesaikan melalui program-program pengurangan risiko bencana dalam lima tahun ke depan. Isu strategis juga dimengerti sebagai kondisi atau hal yang harus diperhatikan atau dikedepankan dalam perencanaan pembangunan daerah karena dampaknya yang signifikan bagi daerah; memiliki karakteristik penting, mendasar, mendesak, berjangka menengah dan/atau panjang dan menentukan pencapaian tujuan penyelenggaraan pemerintah daerah di masa yang akan datang.
Informasi isu strategis kebencanaan Daerah dapat diambil dari Bab II Dokumen RPB bagi daerah yang telah memiliki dan aktif.', 'BAB IV (lanjutan 6)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1224, 'juklak-8-2024', 23, 'lain', 'BAB IV (lanjutan 7)', NULL, 12, '4. Tujuan, Sasaran, Indikator, dan Target Kinerja PB Daerah Tim Pemaduan menguraikan kondisi yang akan dicapai atau dihasilkan dalam jangka waktu lima tahun ke depan dalam hal penanggulangan bencana yang diambil dari dokumen RPB. Tujuan merupakan jawaban atas masalah pokok (isu strategis), sedangkan sasaran adalah rumusan kondisi yang menggambarkan tercapainya tujuan, berupa jabaran dari dampak atau hasil utama yang diharapkan akan dicapai dalam kurun waktu tertentu.
Rumusan dan indikator tujuan PB dapat menjadi masukan bagi rumusan tujuan/sasaran dan indikator RPJMD dan dapat diadopsi sebagai IKU Kepala Daerah. Sementara itu, rumusan dan indikator sasaran PB dapat menjadi masukan rumusan sasaran RPJMD atau rumusan program dan indikator pembangunan daerah yang diadopsi sebagai Program Pemda (IKU Sekda/Asisten Sekda). Daftar dan Informasi Tujuan dan Sasaran PB dapat diperoleh pada Bab IV dokumen RPB bagi daerah yang memiliki RPB yang masih berlaku.
Format Penyajian Tujuan, Sasaran, Indikator dan Target Kinerja PB Daerah tercantum dalam Poin I Lampiran II Petunjuk Pelaksanaan.
5. Strategi, Arah Kebijakan dan Program PB Tim pemaduan merumuskan strategi, arah kebijakan dan program prioritas PB sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1224, '4. Tujuan, Sasaran, Indikator, dan Target Kinerja PB Daerah Tim Pemaduan menguraikan kondisi yang akan dicapai atau dihasilkan dalam jangka waktu lima tahun ke depan dalam hal penanggulangan bencana yang diambil dari dokumen RPB. Tujuan merupakan jawaban atas masalah pokok (isu strategis), sedangkan sasaran adalah rumusan kondisi yang menggambarkan tercapainya tujuan, berupa jabaran dari dampak atau hasil utama yang diharapkan akan dicapai dalam kurun waktu tertentu.
Rumusan dan indikator tujuan PB dapat menjadi masukan bagi rumusan tujuan/sasaran dan indikator RPJMD dan dapat diadopsi sebagai IKU Kepala Daerah. Sementara itu, rumusan dan indikator sasaran PB dapat menjadi masukan rumusan sasaran RPJMD atau rumusan program dan indikator pembangunan daerah yang diadopsi sebagai Program Pemda (IKU Sekda/Asisten Sekda). Daftar dan Informasi Tujuan dan Sasaran PB dapat diperoleh pada Bab IV dokumen RPB bagi daerah yang memiliki RPB yang masih berlaku.
Format Penyajian Tujuan, Sasaran, Indikator dan Target Kinerja PB Daerah tercantum dalam Poin I Lampiran II Petunjuk Pelaksanaan.
5. Strategi, Arah Kebijakan dan Program PB Tim pemaduan merumuskan strategi, arah kebijakan dan program prioritas PB sebagai berikut:', 'BAB IV (lanjutan 7)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1225, 'juklak-8-2024', 24, 'lain', 'BAB IV (lanjutan 8)', NULL, 12, 'a. Strategi penanggulangan bencana daerah Tim Pemaduan merumuskan strategi atau langkah-langkah strategis yang berisikan upaya untuk mencapai sasaran penanggulangan bencana dalam lima tahun ke depan. Strategi dapat dirumuskan untuk masing-masing sasaran PB yang akan dicapai selama 5 tahun atau satu strategi dapat diproyeksikan untuk mencapai beberapa sasaran sekaligus.
b. Arah kebijakan PB Tim Pemaduan menyarikan arah penanggulangan bencana daerah yang diambil dari dokumen RPB. Rumusan arah penanggulangan bencana daerah sangat penting agar dapat diintegrasikan ke dalam arah kebijakan pembangunan daerah. Daerah yang belum memiliki dokumen RPB dapat menyusun arah kebijakan penanggulangan bencana daerah dengan memperhatikan arah kebijakan penanggulangan bencana pusat dan Provinsi bagi Kabupaten/Kota.
Format Penyajian Strategi dan Arah Kebijakan PB di Daerah tercantum dalam Poin J Lampiran II Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1225, 'a. Strategi penanggulangan bencana daerah Tim Pemaduan merumuskan strategi atau langkah-langkah strategis yang berisikan upaya untuk mencapai sasaran penanggulangan bencana dalam lima tahun ke depan. Strategi dapat dirumuskan untuk masing-masing sasaran PB yang akan dicapai selama 5 tahun atau satu strategi dapat diproyeksikan untuk mencapai beberapa sasaran sekaligus.
b. Arah kebijakan PB Tim Pemaduan menyarikan arah penanggulangan bencana daerah yang diambil dari dokumen RPB. Rumusan arah penanggulangan bencana daerah sangat penting agar dapat diintegrasikan ke dalam arah kebijakan pembangunan daerah. Daerah yang belum memiliki dokumen RPB dapat menyusun arah kebijakan penanggulangan bencana daerah dengan memperhatikan arah kebijakan penanggulangan bencana pusat dan Provinsi bagi Kabupaten/Kota.
Format Penyajian Strategi dan Arah Kebijakan PB di Daerah tercantum dalam Poin J Lampiran II Petunjuk Pelaksanaan.', 'BAB IV (lanjutan 8)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1226, 'juklak-8-2024', 25, 'lain', 'BAB IV (lanjutan 9)', NULL, 13, 'c. Prioritas program kebencanaan daerah Tim Pemaduan merumuskan program terkait penanggulangan bencana/kebencanaan prioritas daerah yang adalah penjabaran kebijakan dalam bentuk satu atau lebih kegiatan. Program terkait PB prioritas dipilih berdasarkan nilai strategisnya dalam menyelesaikan isu-isu strategis PB yang telah dirumuskan. Pertimbangan untuk menentukan program antara lain adalah pelaksanaan Standar Pelayanan Minimal Sub-urusan Bencana, pelaksanaan Standar Pelayanan Minimal lainnya terkait kebencanaan, program yang paling efektif dalam meningkatkan pengurangan risiko dan sekaligus menjaga lingkungan hidup dan mengurangi dampak perubahan iklim, program yang meningkatkan kapasitas dan kapabilitas dalam kesiapsiagaan menghadapi bencana dan melakukan pemulihan pascabencana dengan membangun kembali dengan lebih baik. Program Prioritas Kebencanaan tidak hanya Program Penanggulangan Bencana di BPBD, namun bisa Program di SKPD lain terkait kebencanaan. Rumuskan strategi, arah kebijakan dan program prioritas PB dapat diperoloh dari Bab IV dokumen RPB bagi daerah yang memiliki RPB yang masih berlaku.
Format Prioritas program kebencanaan daerah yang disajikan dalam bentuk Sasaran, Indikator Sasaran, Program, Indikator Program tercantum dalam Poin K Lampiran II Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1226, 'c. Prioritas program kebencanaan daerah Tim Pemaduan merumuskan program terkait penanggulangan bencana/kebencanaan prioritas daerah yang adalah penjabaran kebijakan dalam bentuk satu atau lebih kegiatan. Program terkait PB prioritas dipilih berdasarkan nilai strategisnya dalam menyelesaikan isu-isu strategis PB yang telah dirumuskan. Pertimbangan untuk menentukan program antara lain adalah pelaksanaan Standar Pelayanan Minimal Sub-urusan Bencana, pelaksanaan Standar Pelayanan Minimal lainnya terkait kebencanaan, program yang paling efektif dalam meningkatkan pengurangan risiko dan sekaligus menjaga lingkungan hidup dan mengurangi dampak perubahan iklim, program yang meningkatkan kapasitas dan kapabilitas dalam kesiapsiagaan menghadapi bencana dan melakukan pemulihan pascabencana dengan membangun kembali dengan lebih baik. Program Prioritas Kebencanaan tidak hanya Program Penanggulangan Bencana di BPBD, namun bisa Program di SKPD lain terkait kebencanaan. Rumuskan strategi, arah kebijakan dan program prioritas PB dapat diperoloh dari Bab IV dokumen RPB bagi daerah yang memiliki RPB yang masih berlaku.
Format Prioritas program kebencanaan daerah yang disajikan dalam bentuk Sasaran, Indikator Sasaran, Program, Indikator Program tercantum dalam Poin K Lampiran II Petunjuk Pelaksanaan.', 'BAB IV (lanjutan 9)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1227, 'juklak-8-2024', 26, 'lain', 'BAB IV (lanjutan 10)', NULL, 13, '6. Kinerja Penyelenggaraan PB Pemerintah Daerah Indikator kinerja utama PB di daerah perlu dirumuskan untuk dipadukan ke dalam rancangan dokumen RPJMD. Indikator kinerja adalah alat ukur kuantitatif untuk mengetahui dampak pembangunan daerah yang telah dilaksanakan. Indikator kinerja PB daerah yang mencerminkan kemajuan dan peningkatan kinerja pengurangan risiko bencana dan atau penanggulangan bencana di daerah dari tahun ke tahun baik berupa peningkatan indeks kapasitas daerah (IKD) maupun penurunan indeks risiko bencananya (IRBI) perlu diintegrasikan ke dalam RPJMD.
Format Penyajian Proyeksi Pencapaian Indikator Kinerja Daerah untuk PB tercantum dalam Poin L Lampiran II Petunjuk Pelaksanaan.
B. Contoh Telaah/Ringkasan Materi Pemaduan Terkait dengan contoh telaah/penyiapan materi pemaduan penanggulangan bencana ke dalam rencana pembangunan jangka menengah daerah tercantum dalam Lampiran III Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1227, '6. Kinerja Penyelenggaraan PB Pemerintah Daerah Indikator kinerja utama PB di daerah perlu dirumuskan untuk dipadukan ke dalam rancangan dokumen RPJMD. Indikator kinerja adalah alat ukur kuantitatif untuk mengetahui dampak pembangunan daerah yang telah dilaksanakan. Indikator kinerja PB daerah yang mencerminkan kemajuan dan peningkatan kinerja pengurangan risiko bencana dan atau penanggulangan bencana di daerah dari tahun ke tahun baik berupa peningkatan indeks kapasitas daerah (IKD) maupun penurunan indeks risiko bencananya (IRBI) perlu diintegrasikan ke dalam RPJMD.
Format Penyajian Proyeksi Pencapaian Indikator Kinerja Daerah untuk PB tercantum dalam Poin L Lampiran II Petunjuk Pelaksanaan.
B. Contoh Telaah/Ringkasan Materi Pemaduan Terkait dengan contoh telaah/penyiapan materi pemaduan penanggulangan bencana ke dalam rencana pembangunan jangka menengah daerah tercantum dalam Lampiran III Petunjuk Pelaksanaan.', 'BAB IV (lanjutan 10)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1228, 'juklak-8-2024', 27, 'lain', 'BAB V', NULL, 14, 'PENUTUP Petunjuk Pelaksanaan Pemaduan Penanggulangan Bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah ini disusun sebagai panduan bagi BNPB, BPBD, Bappeda, Pemerintah Daerah dan Para Pihak terkait dalam memadukan unsur-unsur Penanggulangan Bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah guna mewujudkan resiliensi berkelanjutan di Indonesia.
Ditetapkan di Jakarta Pada tanggal 22 Juli 2024 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi dan Kerja Sama, Irma Dewi Rismayati');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1228, 'PENUTUP Petunjuk Pelaksanaan Pemaduan Penanggulangan Bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah ini disusun sebagai panduan bagi BNPB, BPBD, Bappeda, Pemerintah Daerah dan Para Pihak terkait dalam memadukan unsur-unsur Penanggulangan Bencana ke dalam Rencana Pembangunan Jangka Menengah Daerah guna mewujudkan resiliensi berkelanjutan di Indonesia.
Ditetapkan di Jakarta Pada tanggal 22 Juli 2024 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
