INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1229, 'juklak-8-2024', 28, 'lampiran', 'LAMPIRAN I', NULL, 15, 'PETUNJUK PELAKSANAAN PEMADUAN UNSUR-UNSUR PENANGGULANGAN BENCANA KE DALAM RENCANA PEMBANGUNAN JANGKA MENENGAH DAERAH NOMOR 8 TAHUN 2024 A. Format Hasil Telaah/Ringkasan Materi Pemaduan Unsur-unsur Penanggulangan Bencana KATA PENGANTAR DAFTAR ISI DAFTAR TABEL DAFTAR GAMBAR');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1229, 'PETUNJUK PELAKSANAAN PEMADUAN UNSUR-UNSUR PENANGGULANGAN BENCANA KE DALAM RENCANA PEMBANGUNAN JANGKA MENENGAH DAERAH NOMOR 8 TAHUN 2024 A. Format Hasil Telaah/Ringkasan Materi Pemaduan Unsur-unsur Penanggulangan Bencana KATA PENGANTAR DAFTAR ISI DAFTAR TABEL DAFTAR GAMBAR', 'LAMPIRAN I', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1230, 'juklak-8-2024', 29, 'lain', 'BAB I PENDAHULUAN', NULL, 15, '1.1 Latar Belakang Bagian ini berisi latar belakang pentingnya penyusunan dokumen Telaah/Ringkasan Materi Pemaduan PB ke dalam RPJMD dan dasar-dasar pertimbangannya dalam konteks tata kelola pemerintahan di daerah.
1.2 Maksud dan Tujuan Bagian ini menjelaskan maksud dan tujuan penyusunan dokumen.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1230, '1.1 Latar Belakang Bagian ini berisi latar belakang pentingnya penyusunan dokumen Telaah/Ringkasan Materi Pemaduan PB ke dalam RPJMD dan dasar-dasar pertimbangannya dalam konteks tata kelola pemerintahan di daerah.
1.2 Maksud dan Tujuan Bagian ini menjelaskan maksud dan tujuan penyusunan dokumen.', 'BAB I PENDAHULUAN', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1231, 'juklak-8-2024', 30, 'lain', 'BAB II. RINGKASAN MATERI PEMADUAN', NULL, 15, '2.1 Posisi RPB dalam Sistem Perencanaan Pembangunan (dipadukan ke dalam Bab I. Pendahuluan dari rancangan RPJMD pada bagian Hubungan antar Dokumen) 2.1.1 Posisi RPB dalam Sistem Perencanaan Pembangunan Daerah Bagian ini menyajikan gambar struktur posisi RPB dalam Sistem Perencanaan Pembangunan Daerah dan sedikit narasi yang menjelaskan gambar tersebut.
2.1.2 Hubungan RPB dengan Rencana Lainnya Bagian ini menjelaskan tentang hubungan antara RPB dengan perencanaan lainnya mulai dari tingkat pusat seperti RIPB, Renas PB, dan RPJMN sampai tingkat daerah dalam hal ini RTRW daerah dan RPJMD.
2.2 Gambaran Umum Kondisi Kebencanaan (dipadukan ke dalam Bab II. Gambaran Umum Kondisi Wilayah dari rancangan RPJMD pada aspek Geografi dan Demografi) 2.2.1 Karakteristik Kebencanaan Daerah Bagian ini menyajikan ringkasan karakteristik ancaman bencana pada aspek-aspek kondisi daerah.
2.2.2 Informasi Sejarah Kebencanaan dan Potensi Risiko Bencana Daerah Bagian ini menyajikan data dan informasi risiko bencana serta sejarah kebencanaan di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1231, '2.1 Posisi RPB dalam Sistem Perencanaan Pembangunan (dipadukan ke dalam Bab I. Pendahuluan dari rancangan RPJMD pada bagian Hubungan antar Dokumen) 2.1.1 Posisi RPB dalam Sistem Perencanaan Pembangunan Daerah Bagian ini menyajikan gambar struktur posisi RPB dalam Sistem Perencanaan Pembangunan Daerah dan sedikit narasi yang menjelaskan gambar tersebut.
2.1.2 Hubungan RPB dengan Rencana Lainnya Bagian ini menjelaskan tentang hubungan antara RPB dengan perencanaan lainnya mulai dari tingkat pusat seperti RIPB, Renas PB, dan RPJMN sampai tingkat daerah dalam hal ini RTRW daerah dan RPJMD.
2.2 Gambaran Umum Kondisi Kebencanaan (dipadukan ke dalam Bab II. Gambaran Umum Kondisi Wilayah dari rancangan RPJMD pada aspek Geografi dan Demografi) 2.2.1 Karakteristik Kebencanaan Daerah Bagian ini menyajikan ringkasan karakteristik ancaman bencana pada aspek-aspek kondisi daerah.
2.2.2 Informasi Sejarah Kebencanaan dan Potensi Risiko Bencana Daerah Bagian ini menyajikan data dan informasi risiko bencana serta sejarah kebencanaan di daerah.', 'BAB II. RINGKASAN MATERI PEMADUAN', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1232, 'juklak-8-2024', 31, 'lain', 'BAB II. RINGKASAN MATERI PEMADUAN (lanjutan 1)', NULL, 15, '2.2.3 Identifikasi Risiko Bencana terkait Aspek Tata Ruang (dipadukan ke dalam Bab II. Gambaran Umum Kondisi Wilayah dari rancangan RPJMD pada bagian Pelayanan Umum Urusan Pekerjaan Umum dan Penataan Ruang) 2.2.4 Evaluasi Kinerja Pembangunan Daerah dalam Bidang PB (dipadukan ke dalam Bab II. Gambaran Umum Kondisi Wilayah dari rancangan RPJMD pada bagian Evaluasi Kinerja Pembangunan Periode Sebelumnya) 2.2.5 Penyajian Capaian SPM Daerah (dipadukan ke dalam Bab II terkait Gambaran Umum Kondisi Daerah.
2.3 Permasalahan dan Isu Strategis PB (dipadukan ke dalam Bab IV. Permasalahan dan Isu Strategis dari rancangan RPJMD pada bagian Permasalahan Pembangunan) 2.3.1 Permasalahan Pokok PB Bagian ini menyajikan rumusan dan deskripsi akar masalah atau masalah pokok penanggulangan bencana daerah.
2.3.2 Pengelompokan Masalah Pokok PB Bagian ini menyajikan daftar masalah pokok penanggulangan bencana daerah.
2.3.3 Rumusan Isu Strategis PB Bagian ini menyajikan daftar isu strategis PB daerah 2.4 Tujuan dan Sasaran PB (dipadukan ke dalam Bab V. Visi, Misi, Tujuan dan Sasaran dari rancangan RPJMD pada bagian Tujuan dan Sasaran) 2.5 Strategi, Arah Kebijakan dan Program PB Daerah (dipadukan ke dalam Bab VI Strategi, Arah Kebijakan dan Program Pembangunan Daerah dari rancangan RPJMD) 2.5.1 Strategi PB Bagian ini menyajikan daftar strategi PB daerah.
2.5.2 Arah Kebijakan PB Bagian ini menyajikan informasi arah kebijakan PB daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1232, '2.2.3 Identifikasi Risiko Bencana terkait Aspek Tata Ruang (dipadukan ke dalam Bab II. Gambaran Umum Kondisi Wilayah dari rancangan RPJMD pada bagian Pelayanan Umum Urusan Pekerjaan Umum dan Penataan Ruang) 2.2.4 Evaluasi Kinerja Pembangunan Daerah dalam Bidang PB (dipadukan ke dalam Bab II. Gambaran Umum Kondisi Wilayah dari rancangan RPJMD pada bagian Evaluasi Kinerja Pembangunan Periode Sebelumnya) 2.2.5 Penyajian Capaian SPM Daerah (dipadukan ke dalam Bab II terkait Gambaran Umum Kondisi Daerah.
