INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1235, 'juklak-8-2024', 34, 'lampiran', 'LAMPIRAN', NULL, 17, 'B. Format Pengendalian dan Pelaporan Pengendalian dan Pelaporan Pemaduan PB ke dalam RPJMD No Unsur Pemaduan Hasil Pengendalian dan Pelaporan Kesesuaian Faktor Tidak Lanjut Ada Tidak Penyebab Penyempurnaan Ketidakses Apabila tidak uaian
(1) (2) (3) (4) (5) (6) 1 Gambar struktur posisi RPB di dalam sistem Perencanaan Pembangunan Daerah 2 Informasi sejarah dan dampak bencana serta risiko bencana 3 Analisis karakteristik ancaman bencana dari berbagai aspek ` 4 Identifikasi risiko bencana terkait aspek tata ruang 5 Data Capaian IKD dan IRBI 5 tahun sebelumnya 6 Data Capaian SPM sub urusan bencana sebelumnya 7 Isu strategis, tujuan, sasaran dan arah kebijakan PB 8 Prioritas program PB 9 Proyeksi peningkatan IKD dan/atau penurunan IRBI sebagai Indikator Kinerja Pemda Cara Pengisian :
Kolom (1) diisi nomor urut Kolom (2) diisi unsur pemaduan PB Kolom (3) diisi tanda (v-ya) kesesuaian pemaduan PB ke dalam RPJMD Kolom (4) diisi tanda (v-tidak) ketidaksesuaian pemaduan PB ke dalam RPJMD Kolom (5) diisi faktor penyebab ketidaksesuaian pemaduan PB Kolom (6) diisi rencana tindaklanjut dan rekomendasi KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO');
