INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1243, 'juklak-8-2024', 42, 'lampiran', 'LAMPIRAN III', NULL, 24, 'PETUNJUK PELAKSANAAN PEMADUAN UNSUR-UNSUR PENANGGULANGAN BENCANA KE DALAM RENCANA PEMBANGUNAN JANGKA MENENGAH DAERAH NOMOR 8 TAHUN 2024 Contoh Telaah/Ringkasan Materi Pemaduan Penanggulangan Bencana Ke Dalam Rencana Pembangunan Jangka Menengah Daerah
1. Posisi RPB dalam Sistem Perencanaan Pembangunan Daerah Hubungan antara RPB dengan perencanaan lainnya mulai dari tingkat pusat seperti RIPB, Renas PB, dan RPJMN sampai tingkat daerah, dalam hal ini RTRW Daerah dan RPJMD. Perencanaan penanggulangan bencana merupakan bagian dari perencanaan pembangunan ( Pasal 6 ayat (1) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana). RPB adalah bagian dari dokumen perencanaan yang harus ditelaah untuk menjadi masukan dalam perencanaan pembangunan daerah seperti, RPJMD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1243, 'PETUNJUK PELAKSANAAN PEMADUAN UNSUR-UNSUR PENANGGULANGAN BENCANA KE DALAM RENCANA PEMBANGUNAN JANGKA MENENGAH DAERAH NOMOR 8 TAHUN 2024 Contoh Telaah/Ringkasan Materi Pemaduan Penanggulangan Bencana Ke Dalam Rencana Pembangunan Jangka Menengah Daerah
1. Posisi RPB dalam Sistem Perencanaan Pembangunan Daerah Hubungan antara RPB dengan perencanaan lainnya mulai dari tingkat pusat seperti RIPB, Renas PB, dan RPJMN sampai tingkat daerah, dalam hal ini RTRW Daerah dan RPJMD. Perencanaan penanggulangan bencana merupakan bagian dari perencanaan pembangunan ( Pasal 6 ayat (1) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana). RPB adalah bagian dari dokumen perencanaan yang harus ditelaah untuk menjadi masukan dalam perencanaan pembangunan daerah seperti, RPJMD.', 'LAMPIRAN III', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1244, 'juklak-8-2024', 43, 'lampiran', 'LAMPIRAN III (lanjutan 1)', NULL, 24, 'Gambar 2. Posisi RPB dalam Sistem Perencanaan Pembangunan Daerah Gambar diatas menunjukan bahwa Rencana Penanggulangan Bencana (RPB) baik di Tingkat Provinsi dan Kabupaten/Kota menjadi rujukan dalam penyusunan Rencana Kerja Pemerintah (RKP) yang merupakan penjabaran RPJMD. RPB dalam proses penyusunannya juga merujuk pada Rencana Nasional Penanggulangan Bencana (Renas PB) yang merupakan penjabaran dari Rencana Induk Penanggulangan Bencana (RIPB) RPB bukan semata-mata perencanaan dalam sektor penanggulangan bencana, tetapi rencana multi sektor yang akan dilaksanakan oleh para pelaku pembangunan di daerah dalam membangun masyarakat yang berketahanan bencana. RPB bertujuan untuk membuat program pembangunan yang dilaksanakan oleh sektor melalui RPJMD menjadi berketahanan bencana. Oleh karenanya RPB harus diintegrasikan ke dalam RPJMD. Dengan demikian program-program penanggulangan bencana dapat menjadi bagian dari Rencana Strategis Organisasi Perangkat Daerah (Renstra PD) dan Rencana Kerja Pemerintah Daerah (RKPD) Selain itu, KRB dan RPB juga dapat menjadi bagian referensi dalam penyusunan RTRW Daerah yang sensitif/peka risiko bencana.
2. Gambaran Umum Kebencanaan Daerah');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1244, 'Gambar 2. Posisi RPB dalam Sistem Perencanaan Pembangunan Daerah Gambar diatas menunjukan bahwa Rencana Penanggulangan Bencana (RPB) baik di Tingkat Provinsi dan Kabupaten/Kota menjadi rujukan dalam penyusunan Rencana Kerja Pemerintah (RKP) yang merupakan penjabaran RPJMD. RPB dalam proses penyusunannya juga merujuk pada Rencana Nasional Penanggulangan Bencana (Renas PB) yang merupakan penjabaran dari Rencana Induk Penanggulangan Bencana (RIPB) RPB bukan semata-mata perencanaan dalam sektor penanggulangan bencana, tetapi rencana multi sektor yang akan dilaksanakan oleh para pelaku pembangunan di daerah dalam membangun masyarakat yang berketahanan bencana. RPB bertujuan untuk membuat program pembangunan yang dilaksanakan oleh sektor melalui RPJMD menjadi berketahanan bencana. Oleh karenanya RPB harus diintegrasikan ke dalam RPJMD. Dengan demikian program-program penanggulangan bencana dapat menjadi bagian dari Rencana Strategis Organisasi Perangkat Daerah (Renstra PD) dan Rencana Kerja Pemerintah Daerah (RKPD) Selain itu, KRB dan RPB juga dapat menjadi bagian referensi dalam penyusunan RTRW Daerah yang sensitif/peka risiko bencana.
2. Gambaran Umum Kebencanaan Daerah', 'LAMPIRAN III (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1245, 'juklak-8-2024', 44, 'lampiran', 'LAMPIRAN III (lanjutan 2)', NULL, 25, '1. Karakteristik Kebencanaan Daerah a) Geografi Secara geografis Kabupaten xx terletak di 110o13’00” sampai dengan 110o33’00” Bujur Timur dan 7o34’51” sampai dengan 7o47’03” Lintang Selatan. Terdiri dari 17 wilayah Kecamatan, 86 Desa, dan 1.212 Dusun. 3 (tiga) kecamatan berada di Kawasan Gunungapi dengan ketinggian 2.911 m diatas permukaan laut yang berpotensi terjadinya bencana letusan gunungapi diikuti banjir lahar dingin, serta kebakaran hutan dan lahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1245, '1. Karakteristik Kebencanaan Daerah a) Geografi Secara geografis Kabupaten xx terletak di 110o13’00” sampai dengan 110o33’00” Bujur Timur dan 7o34’51” sampai dengan 7o47’03” Lintang Selatan. Terdiri dari 17 wilayah Kecamatan, 86 Desa, dan 1.212 Dusun. 3 (tiga) kecamatan berada di Kawasan Gunungapi dengan ketinggian 2.911 m diatas permukaan laut yang berpotensi terjadinya bencana letusan gunungapi diikuti banjir lahar dingin, serta kebakaran hutan dan lahan.', 'LAMPIRAN III (lanjutan 2)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1246, 'juklak-8-2024', 45, 'lampiran', 'LAMPIRAN III (lanjutan 3)', NULL, 25, 'Sedangkan 4 di antaranya di kawasan pesisir yang berpotensi terjadinya tsunami. b) Geologi Ditinjau secara geologi, wilayah Kabupaten/Kota xxx termasuk daerah yang memiliki aktivitas gempa yang tinggi, karena adanya beberapa sesar aktif. Keberadaan sesar aktif ini selain memiliki potensi menimbulkan gempa juga dapat menimbulkan kegagalan struktur tanah sehingga tanah tidak lagi memiliki kekuatan untuk mendukung/menopang beban di atasnya (likuefaksi). Banyak pemukiman dan aktivitas masyarakat berada di daerah rawan gempa dan secara tanpa disadari rawan likuefaksi. Sesar yang berada di Kabupaten/kota xxx adalah: Sesar Opak (yang masih aktif sampai sekarang), Sesar Progo, Sesar Oyo dan Sesar Dengkeng. c) Topografi Ditinjau secara topografi, kawasan perbukitan menjadi bagian yang mendominasi Kabupaten xx, karena wilayahnya berada di sepanjang jajaran perbukitan. Terdapat 60% wilayah yang memiliki kelerengan >40% yang tergolong sangat curam dan rawan bahaya longsor. Hal ini menjadi indikasi bahwa sebagian besar kawasan di daerah ini rawan bahaya longsor. d) Hidrologi Ditinjau secara hidrologi, di wilayah Kabupaten/Kota xxx terdapat 4 Daerah Aliran Sungai (DAS), yaitu DAS Opak-Oyo, DAS Progo, DAS Serang dan DAS Bogowonto. Hanya DAS Serang yang seluruh wilayahnya berada di Kabupaten/Kota xxx, sedangkan DAS lainnya sebagian wilayahnya terutama bagian hulunya berada di Kabupaten/Kota lain yang hilirnya langsung bermuara di Samudra Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1246, 'Sedangkan 4 di antaranya di kawasan pesisir yang berpotensi terjadinya tsunami. b) Geologi Ditinjau secara geologi, wilayah Kabupaten/Kota xxx termasuk daerah yang memiliki aktivitas gempa yang tinggi, karena adanya beberapa sesar aktif. Keberadaan sesar aktif ini selain memiliki potensi menimbulkan gempa juga dapat menimbulkan kegagalan struktur tanah sehingga tanah tidak lagi memiliki kekuatan untuk mendukung/menopang beban di atasnya (likuefaksi). Banyak pemukiman dan aktivitas masyarakat berada di daerah rawan gempa dan secara tanpa disadari rawan likuefaksi. Sesar yang berada di Kabupaten/kota xxx adalah: Sesar Opak (yang masih aktif sampai sekarang), Sesar Progo, Sesar Oyo dan Sesar Dengkeng. c) Topografi Ditinjau secara topografi, kawasan perbukitan menjadi bagian yang mendominasi Kabupaten xx, karena wilayahnya berada di sepanjang jajaran perbukitan. Terdapat 60% wilayah yang memiliki kelerengan >40% yang tergolong sangat curam dan rawan bahaya longsor. Hal ini menjadi indikasi bahwa sebagian besar kawasan di daerah ini rawan bahaya longsor. d) Hidrologi Ditinjau secara hidrologi, di wilayah Kabupaten/Kota xxx terdapat 4 Daerah Aliran Sungai (DAS), yaitu DAS Opak-Oyo, DAS Progo, DAS Serang dan DAS Bogowonto. Hanya DAS Serang yang seluruh wilayahnya berada di Kabupaten/Kota xxx, sedangkan DAS lainnya sebagian wilayahnya terutama bagian hulunya berada di Kabupaten/Kota lain yang hilirnya langsung bermuara di Samudra Indonesia.', 'LAMPIRAN III (lanjutan 3)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1247, 'juklak-8-2024', 46, 'lampiran', 'LAMPIRAN III (lanjutan 4)', NULL, 25, 'Keberadaan DAS di Kabupaten/Kota xxx rentan banjir khususnya ketika terjadi cuaca ekstrem. Tingginya sendimentasi di DAS-DAS ini mengakibatkan kapasitas dan daya tampung air berkurang drastis dan dapat memicu timbulnya kekeringan saat musim kemarau. e) Klimatologi Ditinjau secara klimatologi, Kabupaten/Kota xxx memiliki iklim tropika basah, dengan temperatur bervariasi antara 20ºC hingga 33ºC dan curah hujan yang cukup tinggi yaitu 1600 – 4000 mm/tahun. Hal ini menyebabkan Kabupaten/Kota xxx memiliki kelembaban udara yang tinggi berkisar sekitar 80%. Sepanjang tahun terdapat dua musim yaitu musim penghujan antara Januari-Mei dan musim kemarau antara Juni-Agustus. Tingginya curah hujan mempengaruhi tingkat daya tampung drainase pada permukaan tanah yang dapat mengalami penjenuhan. Penjenuhan ini berpotensi memicu terjadinya bencana banjir dan tanah longsor di Kabupaten/Kota xxx. f) Demografi Ditinjau secara demografi, jumlah penduduk Kabupaten/Kota xxx tahun 2022 adalah 3.185.81 jiwa. Merujuk pada kajian risiko bencana Kabupaten/Kota tahun 2022-2026, rekapitulasi potensi penduduk terpapar dan kelompok rentan untuk 12 jenis ancaman di Kabupaten/Kota berada pada kelas sedang, kecuali pada kegagalan teknologi berada pada kelas Tinggi. Potensi penduduk terpapar terbanyak disebabkan oleh cuaca ekstrem, gempa bumi, kekeringan, epidemi dan wabah penyakit, kekeringan serta Covid -19.
2. Informasi Sejarah Kejadian dan Dampak Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1247, 'Keberadaan DAS di Kabupaten/Kota xxx rentan banjir khususnya ketika terjadi cuaca ekstrem. Tingginya sendimentasi di DAS-DAS ini mengakibatkan kapasitas dan daya tampung air berkurang drastis dan dapat memicu timbulnya kekeringan saat musim kemarau. e) Klimatologi Ditinjau secara klimatologi, Kabupaten/Kota xxx memiliki iklim tropika basah, dengan temperatur bervariasi antara 20ºC hingga 33ºC dan curah hujan yang cukup tinggi yaitu 1600 – 4000 mm/tahun. Hal ini menyebabkan Kabupaten/Kota xxx memiliki kelembaban udara yang tinggi berkisar sekitar 80%. Sepanjang tahun terdapat dua musim yaitu musim penghujan antara Januari-Mei dan musim kemarau antara Juni-Agustus. Tingginya curah hujan mempengaruhi tingkat daya tampung drainase pada permukaan tanah yang dapat mengalami penjenuhan. Penjenuhan ini berpotensi memicu terjadinya bencana banjir dan tanah longsor di Kabupaten/Kota xxx. f) Demografi Ditinjau secara demografi, jumlah penduduk Kabupaten/Kota xxx tahun 2022 adalah 3.185.81 jiwa. Merujuk pada kajian risiko bencana Kabupaten/Kota tahun 2022-2026, rekapitulasi potensi penduduk terpapar dan kelompok rentan untuk 12 jenis ancaman di Kabupaten/Kota berada pada kelas sedang, kecuali pada kegagalan teknologi berada pada kelas Tinggi. Potensi penduduk terpapar terbanyak disebabkan oleh cuaca ekstrem, gempa bumi, kekeringan, epidemi dan wabah penyakit, kekeringan serta Covid -19.
2. Informasi Sejarah Kejadian dan Dampak Bencana', 'LAMPIRAN III (lanjutan 4)', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1248, 'juklak-8-2024', 47, 'lampiran', 'LAMPIRAN III (lanjutan 5)', NULL, 26, 'a. Sejarah Kejadian dan Dampak Bencana Tabel 2.Data Sejarah dan Dampak Kejadian Bencana Sumber: Rencana Penanggulangan Bencana DIY 2022- 2027 Tabel di atas menunjukkan, di wilayah xxx telah terjadi 560 kejadian bencana dalam 10 tahun terakhir. Masing-masing bencana memberikan dampak berupa korban jiwa dan kerusakan serta kerugian. Jenis bencana dengan jumlah kejadian terbanyak dan trend meningkat adalah cuaca ekstrem sebanyak 264 kali. Sedangkan jenis bencana dengan dampak terbesar adalah gempa bumi, yang menelan korban 4.711 jiwa meninggal dunia serta kerusakan bangunan dan lain-lain.
b. Penduduk yang Terpapar Ancaman Bencana Jumlah penduduk terpapar ancaman bencana menyajikan data dan Informasi yang sangat penting untuk memberikan referensi bila ancaman bencana daerah tidak menjadi prioritas untuk ditangani.
Tabel 3. Jumlah Penduduk Terpapar Ancaman Bencana POTENSI PENDUDUK TERPAPAR (Jiwa) KELOMPOK RENTAN JENIS BAHAYA Penduduk Rasio Umur Penduduk Penduduk Kelas Jenis Rentan Miskin Disabilitas Kelamin
1. Banjir 55.237 102 17.625 23.358 668 Tinggi
2. Banjir Bandang 17.324 100 5.457 8.114 376 Tinggi
3. Cuaca Ekstrem 172.658 103 54.419 74.727 1.653 Tinggi
4. Gempabumi 183.177 103 57.727 79.965 1.160 Tinggi
5. Kebakaran Hutan dan - - - - - - Lahan
6. Kekeringan 183.177 103 57.727 79.965 1.160 Tinggi 7.Letusan Gunungapi 4.328 104 1.361 1.866 - Sedang Kerinci
8. Likuefaksi 91.247 101 29.300 39.935 - Tinggi');
