INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1251, 'juklak-8-2024', 50, 'lampiran', 'LAMPIRAN III (lanjutan 8)', NULL, 28, '9. Tanah Longsor 92.330,36 266,41 92.596,77 Tinggi 10.183,00 Tinggi Multi Bahaya 1.009.471,1 2.076,34 1.011.547, Tinggi 93.531,00 Tinggi 3 47 Sumber: Rencana Penanggulangan Bencana Kabupaten Solok Selatan Tahun 2025 - 2029 Berdasarkan tabel di atas, dapat diketahui bahwa kelas kerugian Sedang ada pada bahaya Kebakaran hutan dan lahan, kekeringan, sedangkan jenis bahaya lain memiliki kelas kerugian tinggi. Untuk Kelas kerusakan rendah untuk jenis bahaya Banjir, Likuefaksi dan Tanah Longsor. Kelas kerusakan tinggi pada Kebakaran hutan dan lahan, kekeringan dan letusan gunungapi Merapi.
d. Luas Wilayah Berpotensi Terdampak Bencana Penentuan tingkat bahaya tersebut diperoleh berdasarkan luas kawasan terpapar bahaya, selain itu juga mengacu pada peta bahaya untuk setiap potensi bencana yang ada di daerah xxx. Kelas tinggi menunjukan bahwa luas wilayah terdampak ancaman bencana memiliki tingkat risiko yang signifikan terhadap bencana yang dapat menyebabkan kerusakan besar, kerugian jiwa, atau dampak serius pada masyarakat dan lingkungan. Rincian tingkat bahaya, tingkat kerentanan, tingkat kapasitas, dan tingkat risiko bencana dapat dilihat pada tabel berikut;
Tabel 5. Potensi Luas Wilayah Terdampak Bencana LUAS (Ha) JENIS BAHAYA KELAS Rendah Sedang Tinggi Total
1. Banjir 8.038,89 8.130,60 4.541,40 20.710,89 Tinggi
2. Banjir Bandang 420,30 1.636,47 9.221,04 11.277,81 Tinggi
3. Cuaca Ekstrem - 31.061,25 90.563,76 121.625,01 Tinggi');
