INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1252, 'juklak-8-2024', 51, 'lampiran', 'LAMPIRAN III (lanjutan 9)', NULL, 28, '4. Gempa bumi 77.506,11 70.078,05 180.630,24 328.214,40 Tinggi
