INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1261, 'juklak-8-2024', 60, 'lampiran', 'LAMPIRAN III (lanjutan 18)', NULL, 34, '5. Meningkatkan 5. Terkelolanya 12. Pengelolaan DAS dan 12. Menurunya frekwensi fungsi DAS fungsi DAS daerah tangkapan air kejadian banjir dan dalam dalam untuk pengurangan longsor di daerah mengendalikan mengendalik risiko bencana debit air an debit air
6. Meningkatkan 6. 13. Pengelolaan tutupan 13. Adanya kebijakan pengelolaan dan Terlaksanany lereng di daerah berisiko daerah tentang pengawasan a pengelolaan bencana perlindungan kawasan pemanfaatan dan tangkapan dan resapan hutan dan pengawasan air lingkungan di pemanfaatan 14. Pemanfaatan dan 14. Menurunnya kasus kawasan rawan hutan dan pengendalian pemanfaatan bencana lingkungan di penggunaan lahan dan penggunaan lahan dan kawasan hutan di kawasan rawan hutan yang tidak sesuai rawan bencana dengan peruntukannya bencana 15. Peningkatan sistem 15. Tersedianya sarana pengelolaan prasarana pengelolaan persampahan daerah sampah (TPS dan TPA) sesuai dengan jenis sampahnya
7. Meningkatkan 7. 16. Pengendalian dan 16. Menurunnya tingkat pengawasan Terlaksanany pengawasan penataan pelanggaran penataan ruang a pemukiman di daerah pemanfaatan ruang di kawasan pengawasan rawan bencana Kawasan rawan bencana pemukiman di penataan daerah rawan ruang bencana kawasan pemukiman di daerah rawan bencana');
