INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1263, 'juklak-8-2024', 62, 'lampiran', 'LAMPIRAN IV', NULL, 36, 'PETUNJUK PELAKSANAAN PEMADUAN UNSUR-UNSUR PENANGGULANGAN BENCANA KE DALAM RENCANA PEMBANGUNAN JANGKA MENENGAH DAERAH NOMOR 8 TAHUN 2024 Ketentuan Pengambilan Data Dan Informasi Risiko Bencana Pada Kajian Risiko Bencana Nasional (Skala 1:250.000)
1. Pengambilan Data Peta Data/peta diambil langsung dari Kajian Risiko Bencana (KRB) Provinsi yang disajikan secara nasional (Skala 1:250.000). Data peta ditampilkan dalam layout level provinsi, cukup untuk menunjukkan posisi daerah berpotensi bencana walaupun masih dengan skala provinsi. Untuk mengambil data tersebut, dapat mengikuti langkah berikut.
1. Buka tautan https://bit.ly/PetaKRBNasional2022-2026
2. Tautan tersebut akan mengarah ke dalam folder. Masuk ke folder yang sesuai dengan Provinsi di masing-masing Kabupaten/Kota.
3. Pilih dan Unduh jenis bencana dan bahaya/kerentanan/kapasitas/risiko sesuai kebutuhan.
2. Pengambilan Data Atribut (Tabulasi Data) Data atribut atau juga dikenal dengan data tabular dari informasi spasial merupakan komponen yang tidak terpisahkan dari informasi kebencanaan. Data atribut diambil dari KRB Provinsi yang disajikan secara nasional. Data atribut memuat luasan bahaya, jumlah penduduk terpapar, jumlah kerugian baik fisik maupun ekonomi, luasan lingkungan yang rusak, tingkat kapasitas, maupun tingkat risiko bencana. Untuk mengambil data atribut, dapat mengikuti langkah sebagai berikut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1263, 'PETUNJUK PELAKSANAAN PEMADUAN UNSUR-UNSUR PENANGGULANGAN BENCANA KE DALAM RENCANA PEMBANGUNAN JANGKA MENENGAH DAERAH NOMOR 8 TAHUN 2024 Ketentuan Pengambilan Data Dan Informasi Risiko Bencana Pada Kajian Risiko Bencana Nasional (Skala 1:250.000)
1. Pengambilan Data Peta Data/peta diambil langsung dari Kajian Risiko Bencana (KRB) Provinsi yang disajikan secara nasional (Skala 1:250.000). Data peta ditampilkan dalam layout level provinsi, cukup untuk menunjukkan posisi daerah berpotensi bencana walaupun masih dengan skala provinsi. Untuk mengambil data tersebut, dapat mengikuti langkah berikut.
1. Buka tautan https://bit.ly/PetaKRBNasional2022-2026
2. Tautan tersebut akan mengarah ke dalam folder. Masuk ke folder yang sesuai dengan Provinsi di masing-masing Kabupaten/Kota.
3. Pilih dan Unduh jenis bencana dan bahaya/kerentanan/kapasitas/risiko sesuai kebutuhan.
2. Pengambilan Data Atribut (Tabulasi Data) Data atribut atau juga dikenal dengan data tabular dari informasi spasial merupakan komponen yang tidak terpisahkan dari informasi kebencanaan. Data atribut diambil dari KRB Provinsi yang disajikan secara nasional. Data atribut memuat luasan bahaya, jumlah penduduk terpapar, jumlah kerugian baik fisik maupun ekonomi, luasan lingkungan yang rusak, tingkat kapasitas, maupun tingkat risiko bencana. Untuk mengambil data atribut, dapat mengikuti langkah sebagai berikut.', 'LAMPIRAN IV', 'Petunjuk Pelaksanaan Nomor 8 Tahun 2024 tentang Pemaduan Unsur-Unsur Penanggulangan Bencana ke Dalam Rencana Pemabangunan Jangka Menengah Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1264, 'juklak-8-2024', 63, 'lampiran', 'LAMPIRAN IV (lanjutan 1)', NULL, 36, 'Langkah 1; Buka tautan https://inarisk.bnpb.go.id/webgis Langkah 2; Setelah tautan terbuka lakukan langkah-langkah berikut:
1) Tulis nama Kabupaten/Kota pada menu wilayah 2) Click nama wilayah Kabupaten/Kota 3 3) Click icon layer 4) Centang nama layer Data KRB 2021 5) Click wilayah di peta 6) Click Tulisan biru “Data KRB 2021” untuk memunculkan data tabulasi 7) Click tulisan Excel untuk download data atribut Langkah 3; Tampilan File excel yang telah diunduh adalah berikut.
Langkah 4; File tersebut perlu disesuaikan formatnya dan dibagi menjadi empat (4) jenis informasi seperti pada tampilan di bawah ini:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1264, 'Langkah 1; Buka tautan https://inarisk.bnpb.go.id/webgis Langkah 2; Setelah tautan terbuka lakukan langkah-langkah berikut:
1) Tulis nama Kabupaten/Kota pada menu wilayah 2) Click nama wilayah Kabupaten/Kota 3 3) Click icon layer 4) Centang nama layer Data KRB 2021 5) Click wilayah di peta 6) Click Tulisan biru “Data KRB 2021” untuk memunculkan data tabulasi 7) Click tulisan Excel untuk download data atribut Langkah 3; Tampilan File excel yang telah diunduh adalah berikut.
