INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1267, 'juklak-9-2024', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1267, 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan', 'Judul', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1268, 'juklak-9-2024', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN MEKANISME PELAKSANAAN, PELAPORAN, PEMANTAUAN, DAN EVALUASI KEGIATAN KONSTRUKSI HIBAH REHABILITASI DAN REKONSTRUKSI PASCABENCANA NOMOR 9 TAHUN 2024');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1268, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN MEKANISME PELAKSANAAN, PELAPORAN, PEMANTAUAN, DAN EVALUASI KEGIATAN KONSTRUKSI HIBAH REHABILITASI DAN REKONSTRUKSI PASCABENCANA NOMOR 9 TAHUN 2024', 'Isi hal. 1', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1269, 'juklak-9-2024', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Pelaksanaan kegiatan Rehabilitasi dan Rekonstruksi pascabencana melalui hibah dari Pemerintah kepada pemerintah daerah terdampak bencana merupakan komitmen Pemerintah Indonesia dalam upaya menangani pasca bencana yang dimaksudkan untuk menumbuhkan daya lenting masyarakat terdampak bencana agar dapat bangkit dari keterpurukan melalui konsep membangun kembali yang lebih baik, aman dan berkelanjutan berbasis pengurangan risiko bencana dengan mengutamakan kearifan lokal. Pemerintah telah menyusun kebijakan nasional terkait kebencanaan khususnya pascabencana baik pendanaan maupun kegiatannya agar mempercepat pemulihan, meningkatkan koordinasi, melindungi dan menjaga kesejahteraan masyarakat dan meningkatkan kesiapan Nasional. Salah satu sumber pendanaan bantuan kegiatan Rehabilitasi dan Rekonstruksi dari Pemerintah kepada Pemerintah Daerah yaitu Hibah Rehabilitasi dan Rekonstruksi Pascabencana.
Seiring perkembangan zaman, perlu adanya penyesuaian regulasi sebagai dasar hukum yang bersifat adaptif. Adapun landasan hukum dalam pelaksanaan hibah Rehabilitasi dan Rekonstruksi yakni Peraturan Menteri Keuangan (PMK) Nomor 29 Tahun 2024 tentang Pengelolaan Hibah Rehabilitasi dan Rekonstruksi Pascabencana. BNPB sebagai Lembaga yang menangani bidang kebencanaan khususnya kegiatan pascabencana telah menerbitkan Peraturan BNPB Nomor 4 Tahun 2024 tentang Penyelenggaraan Hibah Rehabilitasi dan Rekonstruksi Pasca Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1269, 'PENDAHULUAN A. Latar Belakang Pelaksanaan kegiatan Rehabilitasi dan Rekonstruksi pascabencana melalui hibah dari Pemerintah kepada pemerintah daerah terdampak bencana merupakan komitmen Pemerintah Indonesia dalam upaya menangani pasca bencana yang dimaksudkan untuk menumbuhkan daya lenting masyarakat terdampak bencana agar dapat bangkit dari keterpurukan melalui konsep membangun kembali yang lebih baik, aman dan berkelanjutan berbasis pengurangan risiko bencana dengan mengutamakan kearifan lokal. Pemerintah telah menyusun kebijakan nasional terkait kebencanaan khususnya pascabencana baik pendanaan maupun kegiatannya agar mempercepat pemulihan, meningkatkan koordinasi, melindungi dan menjaga kesejahteraan masyarakat dan meningkatkan kesiapan Nasional. Salah satu sumber pendanaan bantuan kegiatan Rehabilitasi dan Rekonstruksi dari Pemerintah kepada Pemerintah Daerah yaitu Hibah Rehabilitasi dan Rekonstruksi Pascabencana.
Seiring perkembangan zaman, perlu adanya penyesuaian regulasi sebagai dasar hukum yang bersifat adaptif. Adapun landasan hukum dalam pelaksanaan hibah Rehabilitasi dan Rekonstruksi yakni Peraturan Menteri Keuangan (PMK) Nomor 29 Tahun 2024 tentang Pengelolaan Hibah Rehabilitasi dan Rekonstruksi Pascabencana. BNPB sebagai Lembaga yang menangani bidang kebencanaan khususnya kegiatan pascabencana telah menerbitkan Peraturan BNPB Nomor 4 Tahun 2024 tentang Penyelenggaraan Hibah Rehabilitasi dan Rekonstruksi Pasca Bencana.', 'BAB I', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1270, 'juklak-9-2024', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Berdasarkan Peraturan BNPB Nomor 4 tahun 2024 tentang Penyelenggaraan Hibah Rehabilitasi dan Rekonstruksi Pascabencana pada Pasal 2 ayat (1) huruf a Hibah RR digunakan untuk pembiayaan kegiatan konstruksi dan pada Pasal 3 kegiatan konstruksi dimaksud berupa: a) perbaikan atau pembangunan kembali aset yang rusak akibat bencana mencakup penambahan volume kegiatan yang diperbolehkan maksimal sebesar 106 (sepuluh persen) dari volume aset yang rusak atau berdasarkan hasil telaahan tim teknis Pemerintah Daerah, b) penambahan item kegiatan/bangunan pelengkap yang diperlukan untuk mendukung fungsi dan melindungi bangunan utama berdasarkan hasil telaahan tim teknis Pemerintah Daerah merujuk pada standar minimal yang ditentukan kementerian dan lembaga terkait; c) perubahan konstruksi eksisting yang diperlukan karena perubahan struktur tanah, pola aliran sungai, ketersediaan bahan baku atau berdasarkan hasil telaahan tim teknis Pemerintah Daerah; dan d) pembangunan sarana dan prasarana lain pada kegiatan relokasi perumahan berdasarkan hasil telaahan tim teknis Pemerintah Daerah merujuk pada standar minimal yang ditentukan kementerian dan lembaga terkait.
Mempertimbangkan hal tersebut diatas maka diperlukan Petunjuk Pelaksanaan tentang Mekanisme Pelaksanaan, Pelaporan, Pemantauan dan Evaluasi Kegiatan Konstruksi Hibah Rehabilitasi dan Rekonstruksi Pascabencana.
B. Maksud dan Tujuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1270, 'Berdasarkan Peraturan BNPB Nomor 4 tahun 2024 tentang Penyelenggaraan Hibah Rehabilitasi dan Rekonstruksi Pascabencana pada Pasal 2 ayat (1) huruf a Hibah RR digunakan untuk pembiayaan kegiatan konstruksi dan pada Pasal 3 kegiatan konstruksi dimaksud berupa: a) perbaikan atau pembangunan kembali aset yang rusak akibat bencana mencakup penambahan volume kegiatan yang diperbolehkan maksimal sebesar 106 (sepuluh persen) dari volume aset yang rusak atau berdasarkan hasil telaahan tim teknis Pemerintah Daerah, b) penambahan item kegiatan/bangunan pelengkap yang diperlukan untuk mendukung fungsi dan melindungi bangunan utama berdasarkan hasil telaahan tim teknis Pemerintah Daerah merujuk pada standar minimal yang ditentukan kementerian dan lembaga terkait; c) perubahan konstruksi eksisting yang diperlukan karena perubahan struktur tanah, pola aliran sungai, ketersediaan bahan baku atau berdasarkan hasil telaahan tim teknis Pemerintah Daerah; dan d) pembangunan sarana dan prasarana lain pada kegiatan relokasi perumahan berdasarkan hasil telaahan tim teknis Pemerintah Daerah merujuk pada standar minimal yang ditentukan kementerian dan lembaga terkait.
Mempertimbangkan hal tersebut diatas maka diperlukan Petunjuk Pelaksanaan tentang Mekanisme Pelaksanaan, Pelaporan, Pemantauan dan Evaluasi Kegiatan Konstruksi Hibah Rehabilitasi dan Rekonstruksi Pascabencana.
B. Maksud dan Tujuan', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1271, 'juklak-9-2024', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, '1. Maksud Maksud petunjuk pelaksanaan ini adalah sebagai acuan bagi Pemerintah, Pemerintah Daerah, dan pihak lainnya dalam mekanisme pelaksanaan, pelaporan, pemantauan, dan evaluasi dalam kegiatan konstruksi hibah rehabilitasi dan rekonstruksi pascabencana.
2. Tujuan Tujuan ditetapkannya petunjuk pelaksanaan yaitu ini agar mekanisme pelaksanaan, pelaporan, pemantauan, dan evaluasi dalam kegiatan konstruksi hibah rehabilitasi dan rekonstruksi pascabencana terlaksana secara tertib, efektif, efisien, ekonomis, transparan, bertanggungjawab dan tepat sasaran.
C. Ruang Lingkup Ruang lingkup petunjuk pelaksanaan ini meliputi mekanisme pelaksanaan, pelaporan, pemantauan dan evaluasi dalam kegiatan konstruksi hibah rehabilitasi dan rekonstruksi pascabencana.
D. Pengertian
1. Hibah Rehabilitasi dan Rekonstruksi Pascabencana yang selanjutnya disebut Hibah RR adalah hibah dari pemerintah pusat kepada pemerintah daerah untuk bantuan rehabilitasi dan rekonstruksi pascabencana.
2. Perjanjian Hibah Daerah yang selanjutnya disingkat PHD adalah kesepakatan tertulis mengenai hibah antara pemerintah dan pemerintah daerah yang dituangkan dalam perjanjian.
3. Rencana Kegiatan dan Anggaran yang selanjutnya disingkat RKA adalah dokumen yang memuat rincian kegiatan dan besaran pendanaan selama 1 (satu) tahun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1271, '1. Maksud Maksud petunjuk pelaksanaan ini adalah sebagai acuan bagi Pemerintah, Pemerintah Daerah, dan pihak lainnya dalam mekanisme pelaksanaan, pelaporan, pemantauan, dan evaluasi dalam kegiatan konstruksi hibah rehabilitasi dan rekonstruksi pascabencana.
2. Tujuan Tujuan ditetapkannya petunjuk pelaksanaan yaitu ini agar mekanisme pelaksanaan, pelaporan, pemantauan, dan evaluasi dalam kegiatan konstruksi hibah rehabilitasi dan rekonstruksi pascabencana terlaksana secara tertib, efektif, efisien, ekonomis, transparan, bertanggungjawab dan tepat sasaran.
C. Ruang Lingkup Ruang lingkup petunjuk pelaksanaan ini meliputi mekanisme pelaksanaan, pelaporan, pemantauan dan evaluasi dalam kegiatan konstruksi hibah rehabilitasi dan rekonstruksi pascabencana.
D. Pengertian
1. Hibah Rehabilitasi dan Rekonstruksi Pascabencana yang selanjutnya disebut Hibah RR adalah hibah dari pemerintah pusat kepada pemerintah daerah untuk bantuan rehabilitasi dan rekonstruksi pascabencana.
2. Perjanjian Hibah Daerah yang selanjutnya disingkat PHD adalah kesepakatan tertulis mengenai hibah antara pemerintah dan pemerintah daerah yang dituangkan dalam perjanjian.
3. Rencana Kegiatan dan Anggaran yang selanjutnya disingkat RKA adalah dokumen yang memuat rincian kegiatan dan besaran pendanaan selama 1 (satu) tahun.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1272, 'juklak-9-2024', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, '4. Surat Penetapan Pemberian Hibah yang selanjutnya disingkat SPPH adalah surat yang diterbitkan oleh Menteri Keuangan atau pejabat yang diberi wewenang dan ditujukan kepada pemerintah daerah, yang memuat kegiatan dan besaran hibah yang bersumber dari penerimaan dalam negeri.
5. Rekening Kas Umum Negara yang selanjutnya disingkat RKUN adalah rekening tempat penyimpanan uang negara yang ditentukan oleh Menteri Keuangan selaku Bendahara Umum Negara untuk menampung seluruh penerimaan negara dan membayar seluruh pengeluaran negara pada bank sentral.
6. Rekening Kas Umum Daerah yang selanjutnya disingkat RKUD adalah rekening tempat penyimpanan uang daerah yang ditentukan oleh gubernur dan bupati/walikota untuk menampung seluruh penerimaan daerah dan membayar seluruh pengeluaran daerah pada bank yang ditetapkan.
7. Tender Pra-DPA adalah proses pengadaan barang atau jasa yang dilakukan sebelum penetapan DPA.
8. Tim Teknis adalah tim yang dibentuk dari unsur perangkat daerah teknis terkait yang bertugas untuk membantu memberi masukan dan melaksanakan tugas tertentu dalam pelaksanaan kegiatan konstruksi yang ditetapkan melalui keputusan oleh Kepala Daerah.
9. Aplikasi E-Pelaporan adalah aplikasi penyampaian pelaporan bagi pemerintah daerah penerima hibah rehabilitasi dan rekonstruksi pascabencana sebagai basis data untuk mendukung pemantauan.
10. Aplikasi Mapping Aset adalah aplikasi untuk memetakan penyebaran aset hasil kegiatan hibah rehabilitasi dan rekonstruksi pascabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1272, '4. Surat Penetapan Pemberian Hibah yang selanjutnya disingkat SPPH adalah surat yang diterbitkan oleh Menteri Keuangan atau pejabat yang diberi wewenang dan ditujukan kepada pemerintah daerah, yang memuat kegiatan dan besaran hibah yang bersumber dari penerimaan dalam negeri.
5. Rekening Kas Umum Negara yang selanjutnya disingkat RKUN adalah rekening tempat penyimpanan uang negara yang ditentukan oleh Menteri Keuangan selaku Bendahara Umum Negara untuk menampung seluruh penerimaan negara dan membayar seluruh pengeluaran negara pada bank sentral.
6. Rekening Kas Umum Daerah yang selanjutnya disingkat RKUD adalah rekening tempat penyimpanan uang daerah yang ditentukan oleh gubernur dan bupati/walikota untuk menampung seluruh penerimaan daerah dan membayar seluruh pengeluaran daerah pada bank yang ditetapkan.
7. Tender Pra-DPA adalah proses pengadaan barang atau jasa yang dilakukan sebelum penetapan DPA.
8. Tim Teknis adalah tim yang dibentuk dari unsur perangkat daerah teknis terkait yang bertugas untuk membantu memberi masukan dan melaksanakan tugas tertentu dalam pelaksanaan kegiatan konstruksi yang ditetapkan melalui keputusan oleh Kepala Daerah.
9. Aplikasi E-Pelaporan adalah aplikasi penyampaian pelaporan bagi pemerintah daerah penerima hibah rehabilitasi dan rekonstruksi pascabencana sebagai basis data untuk mendukung pemantauan.
10. Aplikasi Mapping Aset adalah aplikasi untuk memetakan penyebaran aset hasil kegiatan hibah rehabilitasi dan rekonstruksi pascabencana.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1273, 'juklak-9-2024', 6, 'lain', 'BAB I (lanjutan 4)', NULL, 3, '11. Laporan berkala adalah laporan pelaksanaan kegiatan yang disampaikan setiap 3 (tiga) bulan.
12. Laporan akhir adalah laporan pelaksanaan kegiatan secara komprehensif yang di susun dan disampaikan setelah masa pelaksanaan Hibah RR berakhir.
13. Laporan akhir adalah laporan pelaksanaan kegiatan secara komprehensif yang di susun dan disampaikan setelah masa pelaksanaan Hibah RR berakhir.
14. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
15. Aparat Pengawas Internal Pemerintah yang selanjutnya disingkat APIP adalah inspektorat jenderal kementerian, unit pengawasan lembaga pemerintah nonkementerian, inspektorat provinsi, dan inspektorat kabupaten/kota.
16. Perangkat Daerah adalah unsur pembantu kepala daerah dan Dewan Perwakilan Rakyat Daerah dalam penyelenggaraan urusan pemerintahan yang menjadi kewenangan daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1273, '11. Laporan berkala adalah laporan pelaksanaan kegiatan yang disampaikan setiap 3 (tiga) bulan.
12. Laporan akhir adalah laporan pelaksanaan kegiatan secara komprehensif yang di susun dan disampaikan setelah masa pelaksanaan Hibah RR berakhir.
13. Laporan akhir adalah laporan pelaksanaan kegiatan secara komprehensif yang di susun dan disampaikan setelah masa pelaksanaan Hibah RR berakhir.
14. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
15. Aparat Pengawas Internal Pemerintah yang selanjutnya disingkat APIP adalah inspektorat jenderal kementerian, unit pengawasan lembaga pemerintah nonkementerian, inspektorat provinsi, dan inspektorat kabupaten/kota.
16. Perangkat Daerah adalah unsur pembantu kepala daerah dan Dewan Perwakilan Rakyat Daerah dalam penyelenggaraan urusan pemerintahan yang menjadi kewenangan daerah.', 'BAB I (lanjutan 4)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1274, 'juklak-9-2024', 7, 'lain', 'BAB II', NULL, 4, 'PELAKSANAAN DAN PELAPORAN A. Pelaksanaan Setelah PHD ditetapkan dan selanjutnya Hibah RR telah disalurkan oleh Kementerian Keuangan ke RKUD, kegiatan Hibah RR dilaksanakan berdasarkan:
a. PHD;
b. RKA; dan/atau
c. petunjuk pelaksanaan/petunjuk teknis yang ditetapkan BNPB dan/atau kementerian/lembaga terkait.
Kepala Daerah penerima Hibah RR bertanggung jawab sepenuhnya baik secara materiil maupun formil terhadap pelaksanaan kegiatan dan pelaporan atas pelaksanaan Hibah RR.
Pemerintah Daerah wajib menyelenggarakan penatausahaan dan pertanggungjawaban sesuai dengan wewenang dan tanggung jawabnya.
Pertanggungjawaban pelaksanaan kegiatan dan anggaran disusun dalam suatu laporan yang disampaikan kepada pihak-pihak terkait baik di tingkat pusat maupun daerah.
Pelaksanaan Hibah RR agar memperhatikan:
a. membangun kembali lebih baik dan aman (build back better and safer)
b. menggunakan pendekatan sosial budaya, adat istiadat dan mengutamakan penggunaan sumber daya setempat.
c. Pelibatan APIP daerah untuk melakukan pendampingan terhadap pelaksanaan kegiatan Hibah RR.
1. Strategi Percepatan Pelaksanaan Pemerintah Daerah dapat melakukan strategi percepatan sejak SPPH ditetapkan, sebagai berikut:
a. mereviu perencanaan teknis atas kegiatan yang akan dilaksanakan sebagai langkah persiapan pelaksanaan kegiatan dan identifikasi kemungkinan adanya perubahan RKA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1274, 'PELAKSANAAN DAN PELAPORAN A. Pelaksanaan Setelah PHD ditetapkan dan selanjutnya Hibah RR telah disalurkan oleh Kementerian Keuangan ke RKUD, kegiatan Hibah RR dilaksanakan berdasarkan:
a. PHD;
b. RKA; dan/atau
c. petunjuk pelaksanaan/petunjuk teknis yang ditetapkan BNPB dan/atau kementerian/lembaga terkait.
Kepala Daerah penerima Hibah RR bertanggung jawab sepenuhnya baik secara materiil maupun formil terhadap pelaksanaan kegiatan dan pelaporan atas pelaksanaan Hibah RR.
Pemerintah Daerah wajib menyelenggarakan penatausahaan dan pertanggungjawaban sesuai dengan wewenang dan tanggung jawabnya.
Pertanggungjawaban pelaksanaan kegiatan dan anggaran disusun dalam suatu laporan yang disampaikan kepada pihak-pihak terkait baik di tingkat pusat maupun daerah.
Pelaksanaan Hibah RR agar memperhatikan:
a. membangun kembali lebih baik dan aman (build back better and safer)
b. menggunakan pendekatan sosial budaya, adat istiadat dan mengutamakan penggunaan sumber daya setempat.
c. Pelibatan APIP daerah untuk melakukan pendampingan terhadap pelaksanaan kegiatan Hibah RR.
1. Strategi Percepatan Pelaksanaan Pemerintah Daerah dapat melakukan strategi percepatan sejak SPPH ditetapkan, sebagai berikut:
a. mereviu perencanaan teknis atas kegiatan yang akan dilaksanakan sebagai langkah persiapan pelaksanaan kegiatan dan identifikasi kemungkinan adanya perubahan RKA.', 'BAB II', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1275, 'juklak-9-2024', 8, 'lain', 'BAB II (lanjutan 1)', NULL, 4, 'b. melaksanakan tender/seleksi Pra-DPA sesuai dengan ketentuan pengadaan barang/jasa pemerintah yang berlaku berdasarkan prinsip pengadaan.
c. memastikan bahwa penganggaran hibah RR telah tertuang dalam APBD tahun berjalan/tahun pelaksanaan sebelum penandatanganan kontrak.
d. pemilihan penyedia dan dapat melalui katalog elektronik sesuai dengan ketentuan pengadaan barang/jasa pemerintah yang berlaku berdasarkan prinsip pengadaan.
2. Tugas Dalam proses pelaksanaan Hibah RR kegiatan konstruksi, Pemerintah dan Pemerintah Daerah mempunyai tugas sebagai berikut:
a. BNPB 1) BNPB melaksanakan kegiatan peningkatan kesiapan daerah bersama kementerian/lembaga terkait.
2) BNPB melaksanakan asistensi pelaporan baik laporan berkala, laporan akhir dan penyetoran sisa dana yang disampaikan oleh Pemerintah Daerah penerimah Hibah RR.
3) BNPB menelaah surat permohonan perubahan RKA yang disampaikan oleh Kepala Daerah sesuai dengan peraturan perundang-undangan yang berlaku.
4) BNPB, selaku executing agency, melaksanakan pemantauan dan evaluasi terhadap pelaksanaan Hibah RR dan ketaatan pelaporan secara mandiri maupun bersama-sama dengan Kementerian Keuangan atas pelaksanaan kegiatan dan anggaran, sejak PHD ditetapkan sampai dengan pertanggungjawaban oleh pemerintah daerah disampaikan sesuai dengan peraturan perundang-undangan yang berlaku.
b. Pemerintah Daerah 1) Pemerintah Provinsi a) Dalam hal Pemerintah Provinsi sebagai penerima Hibah RR
(1) Menganggarkan Hibah RR pada APBD;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1275, 'b. melaksanakan tender/seleksi Pra-DPA sesuai dengan ketentuan pengadaan barang/jasa pemerintah yang berlaku berdasarkan prinsip pengadaan.
c. memastikan bahwa penganggaran hibah RR telah tertuang dalam APBD tahun berjalan/tahun pelaksanaan sebelum penandatanganan kontrak.
d. pemilihan penyedia dan dapat melalui katalog elektronik sesuai dengan ketentuan pengadaan barang/jasa pemerintah yang berlaku berdasarkan prinsip pengadaan.
2. Tugas Dalam proses pelaksanaan Hibah RR kegiatan konstruksi, Pemerintah dan Pemerintah Daerah mempunyai tugas sebagai berikut:
a. BNPB 1) BNPB melaksanakan kegiatan peningkatan kesiapan daerah bersama kementerian/lembaga terkait.
2) BNPB melaksanakan asistensi pelaporan baik laporan berkala, laporan akhir dan penyetoran sisa dana yang disampaikan oleh Pemerintah Daerah penerimah Hibah RR.
3) BNPB menelaah surat permohonan perubahan RKA yang disampaikan oleh Kepala Daerah sesuai dengan peraturan perundang-undangan yang berlaku.
4) BNPB, selaku executing agency, melaksanakan pemantauan dan evaluasi terhadap pelaksanaan Hibah RR dan ketaatan pelaporan secara mandiri maupun bersama-sama dengan Kementerian Keuangan atas pelaksanaan kegiatan dan anggaran, sejak PHD ditetapkan sampai dengan pertanggungjawaban oleh pemerintah daerah disampaikan sesuai dengan peraturan perundang-undangan yang berlaku.
b. Pemerintah Daerah 1) Pemerintah Provinsi a) Dalam hal Pemerintah Provinsi sebagai penerima Hibah RR
(1) Menganggarkan Hibah RR pada APBD;', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1276, 'juklak-9-2024', 9, 'lain', 'BAB II (lanjutan 2)', NULL, 5, '(2) Untuk mendukung pelaksanaan hibah RR, Pemda menganggarkan pada APBD untuk kegiatan perencanaan, pengawasan, operasional lain dan reviu APIP.
(3) Pemerintah Provinsi bertanggung jawab atas perencanaan teknis, pengadaan barang/jasa, pelaksanaan kegiatan hibah, pengawasan teknis, pelaporan kegiatan baik laporan berkala dan laporan akhir serta penyetoran sisa dana sesuai dengan peraturan perundang-undangan yang berlaku;
(4) Berkoordinasi dengan BNPB apabila ada rencana perubahan RKA;
(5) Melaksanakan rapat koordinasi dalam rangka penyelenggaraan pekerjaan dengan pihak-pihak terkait;
(6) Melaksanakan sosialisasi kepada warga setempat terkait pekerjaan konstruksi yang akan dilakukan;
(7) Berkoordinasi dengan konsultan pengawas dan tim teknis terkait dengan progres pelaksanaan, kendala-kendala yang dihadapi serta cara menindaklanjutinya dan percepatan pelaksanaan;
(8) Meng-input progres laporan berkala dan laporan akhir dalam apliaksi E-Pelaporan serta meng-input kegiatan konstruksi yang telah selesai dilaksanakan dalam aplikasi mapping aset;
(9) Menyampaikan laporan berkala dan laporan akhir ke BNPB dan Kementerian Keuangan serta penyetoran sisa dana ke RKUN;
(10) Melakukan pembayaran hasil pekerjaan kepada pihak penyedia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1276, '(2) Untuk mendukung pelaksanaan hibah RR, Pemda menganggarkan pada APBD untuk kegiatan perencanaan, pengawasan, operasional lain dan reviu APIP.
(3) Pemerintah Provinsi bertanggung jawab atas perencanaan teknis, pengadaan barang/jasa, pelaksanaan kegiatan hibah, pengawasan teknis, pelaporan kegiatan baik laporan berkala dan laporan akhir serta penyetoran sisa dana sesuai dengan peraturan perundang-undangan yang berlaku;
(4) Berkoordinasi dengan BNPB apabila ada rencana perubahan RKA;
(5) Melaksanakan rapat koordinasi dalam rangka penyelenggaraan pekerjaan dengan pihak-pihak terkait;
(6) Melaksanakan sosialisasi kepada warga setempat terkait pekerjaan konstruksi yang akan dilakukan;
(7) Berkoordinasi dengan konsultan pengawas dan tim teknis terkait dengan progres pelaksanaan, kendala-kendala yang dihadapi serta cara menindaklanjutinya dan percepatan pelaksanaan;
(8) Meng-input progres laporan berkala dan laporan akhir dalam apliaksi E-Pelaporan serta meng-input kegiatan konstruksi yang telah selesai dilaksanakan dalam aplikasi mapping aset;
(9) Menyampaikan laporan berkala dan laporan akhir ke BNPB dan Kementerian Keuangan serta penyetoran sisa dana ke RKUN;
(10) Melakukan pembayaran hasil pekerjaan kepada pihak penyedia.', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1277, 'juklak-9-2024', 10, 'lain', 'BAB II (lanjutan 3)', NULL, 5, '(11) Melakukan pelabelan berupa prasasti sesuai dengan format 1 lampiran. b) Pemerintah provinsi sebagai pelaksana pemantauan dan evaluasi Dalam hal penerima Hibah RR adalah Pemerintah Kabupaten/Kota, maka Pemerintah Provinsi adalah pihak yang diberi kewenangan dan tanggung jawab dalam melaksanakan pemantauan dan evaluasi terhadap pelaksanaan kegiatan di wilayahnya dengan menggunakan APBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1277, '(11) Melakukan pelabelan berupa prasasti sesuai dengan format 1 lampiran. b) Pemerintah provinsi sebagai pelaksana pemantauan dan evaluasi Dalam hal penerima Hibah RR adalah Pemerintah Kabupaten/Kota, maka Pemerintah Provinsi adalah pihak yang diberi kewenangan dan tanggung jawab dalam melaksanakan pemantauan dan evaluasi terhadap pelaksanaan kegiatan di wilayahnya dengan menggunakan APBD.', 'BAB II (lanjutan 3)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1278, 'juklak-9-2024', 11, 'lain', 'BAB II (lanjutan 4)', NULL, 6, '2) Pemerintah Kabupaten/Kota Dalam hal pelaksana kegiatan Hibah RR adalah Pemerintah Kabupaten/Kota a) Menganggarkan Hibah RR pada APBD; b) Untuk mendukung pelaksanaan Hibah RR, Pemda menganggarkan pada APBD untuk kegiatan perencanaan, pengawasan, operasional lain dan reviu APIP; c) bertanggung jawab sejak dari kegiatan perencanaan teknis, pengadaan barang/jasa, pelaksanaan kegiatan konstruksi, pengawasan teknis pelaporan kegiatan baik laporan berkala dan laporan akhir serta penyetoran sisa dana sesuai dengan peraturan perundang-undangan yang berlaku; d) Berkoordinasi dengan BNPB apabila ada rencana perubahan RKA; e) Melaksanakan rapat koordinasi dalam rangka penyelenggaraan pekerjaan dengan pihak-pihak terkait; f) Melaksanakan sosialisasi kepada warga setempat terkait pekerjaan konstruksi yang akan dilakukan; g) Berkoordinasi dengan konsutan pengawas dan tim teknis terkait dengan progres pelaksanaan, kendala-kendala yang dihadapi serta cara menindaklanjutinya dan percepatan pelaksanaan; h) Meng-input progres laporan berkala dan laporan akhir dalam apliaksi E-Pelaporan serta meng-input kegiatan konstruksi yang telah selesai dilaksanakan dalam aplikasi mapping aset; i) Menyampaikan laporan berkala dan laporan akhir ke BNPB dan Kementerian Keuangan serta sisa dana ke RKUN; j) Melakukan pembayaran hasil pekerjaan kepada pihak penyedia; k) Melakukan pelabelan berupa prasasti sesuai dengan format 1 lampiran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1278, '2) Pemerintah Kabupaten/Kota Dalam hal pelaksana kegiatan Hibah RR adalah Pemerintah Kabupaten/Kota a) Menganggarkan Hibah RR pada APBD; b) Untuk mendukung pelaksanaan Hibah RR, Pemda menganggarkan pada APBD untuk kegiatan perencanaan, pengawasan, operasional lain dan reviu APIP; c) bertanggung jawab sejak dari kegiatan perencanaan teknis, pengadaan barang/jasa, pelaksanaan kegiatan konstruksi, pengawasan teknis pelaporan kegiatan baik laporan berkala dan laporan akhir serta penyetoran sisa dana sesuai dengan peraturan perundang-undangan yang berlaku; d) Berkoordinasi dengan BNPB apabila ada rencana perubahan RKA; e) Melaksanakan rapat koordinasi dalam rangka penyelenggaraan pekerjaan dengan pihak-pihak terkait; f) Melaksanakan sosialisasi kepada warga setempat terkait pekerjaan konstruksi yang akan dilakukan; g) Berkoordinasi dengan konsutan pengawas dan tim teknis terkait dengan progres pelaksanaan, kendala-kendala yang dihadapi serta cara menindaklanjutinya dan percepatan pelaksanaan; h) Meng-input progres laporan berkala dan laporan akhir dalam apliaksi E-Pelaporan serta meng-input kegiatan konstruksi yang telah selesai dilaksanakan dalam aplikasi mapping aset; i) Menyampaikan laporan berkala dan laporan akhir ke BNPB dan Kementerian Keuangan serta sisa dana ke RKUN; j) Melakukan pembayaran hasil pekerjaan kepada pihak penyedia; k) Melakukan pelabelan berupa prasasti sesuai dengan format 1 lampiran.', 'BAB II (lanjutan 4)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1279, 'juklak-9-2024', 12, 'lain', 'BAB II (lanjutan 5)', NULL, 6, 'Penyusunan perencanaan teknis dilaksanakan oleh pemerintah daerah. Kegiatan ini dapat dilaksanakan secara swakelola atau kontraktual melalui penyedia jasa konsultan.
Perencanaan teknis konstruksi dilaksanakan sebagai berikut:
1) dilakukan oleh penyedia jasa badan usaha yang dinyatakan ahli dan profesional di bidang perencanaan jasa konstruksi yang mampu mewujudkan pekerjaan dalam bentuk dokumen perencanaan;
2) besarnya biaya untuk perencanaan mengacu pada peraturan perundang undangan yang berlaku;
3) perencanaan teknis konstruksi dilaksanakan dengan kontraktual/swakelola;
4) pekerjaan perencanaan teknis konstruksi meliputi: pembangunan dan perbaikan prasarana dan sarana umum, kegiatan yang menyangkut infrastruktur jalan, jembatan, bangunan gedung pemerintah, sarana telekomunikasi, bangunan air, jaringan irigasi, sektor perumahan, dan lain-lain yang menyangkut bidang konstruksi; dan 5) perencanaan teknis konstruksi harus sudah selesai dilaksanakan sebelum pekerjaan fisik dimulai.
Pengawasan kegiatan konstruksi dilaksanakan oleh pemerintah daerah melalui pihak ketiga atau secara swakelola dengan melibatkan OPD teknis terkait.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1279, 'Penyusunan perencanaan teknis dilaksanakan oleh pemerintah daerah. Kegiatan ini dapat dilaksanakan secara swakelola atau kontraktual melalui penyedia jasa konsultan.
Perencanaan teknis konstruksi dilaksanakan sebagai berikut:
1) dilakukan oleh penyedia jasa badan usaha yang dinyatakan ahli dan profesional di bidang perencanaan jasa konstruksi yang mampu mewujudkan pekerjaan dalam bentuk dokumen perencanaan;
2) besarnya biaya untuk perencanaan mengacu pada peraturan perundang undangan yang berlaku;
3) perencanaan teknis konstruksi dilaksanakan dengan kontraktual/swakelola;
4) pekerjaan perencanaan teknis konstruksi meliputi: pembangunan dan perbaikan prasarana dan sarana umum, kegiatan yang menyangkut infrastruktur jalan, jembatan, bangunan gedung pemerintah, sarana telekomunikasi, bangunan air, jaringan irigasi, sektor perumahan, dan lain-lain yang menyangkut bidang konstruksi; dan 5) perencanaan teknis konstruksi harus sudah selesai dilaksanakan sebelum pekerjaan fisik dimulai.
Pengawasan kegiatan konstruksi dilaksanakan oleh pemerintah daerah melalui pihak ketiga atau secara swakelola dengan melibatkan OPD teknis terkait.', 'BAB II (lanjutan 5)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1280, 'juklak-9-2024', 13, 'lain', 'BAB II (lanjutan 6)', NULL, 7, 'Pemerintah Daerah melaksanakan kegiatan konstruksi dan memperhatikan hal-hal sebagai berikut: a) metode pelaksanaan dan rencana kerja dengan metode aman dan bersih (clean construction); b) penyediaan jalan akses untuk mobilisasi peralatan dan material; c) program dan jadwal pekerjaan; d) gambar kerja (shop drawing) dan perubahan desain bila terjadi perbedaan dengan lapangan; e) pendirian bangunan kantor dan gudang proyek; f) mobilisasi peralatan, material dan tenaga kerja; g) penempatan dan penyediaan material di lokasi; h) hal lainnya sesuai kebutuhan kegiatan.
3. Masa Pelaksanaan Hibah Rehabilitasi dan Rekonstruksi Pemerintah daerah menyelesaikan penganggaran dan pelaksanaan kegiatan Hibah RR sesuai dengan jangka waktu yang telah ditetapkan pada PHD.
Hal-hal yang perlu diperhatikan dalam masa pelaksanaan Hibah Rehabilitasi dan Rekonstruksi adalah sebagai berikut:
a. proses pengadaan barang/jasa dan proses penyusunan kontrak/perjanjian harus memperhatikan ketentuan perundang-undangan.
b. pelaksanaan kegiatan dan penyerapan anggaran yang melampaui masa pelaksanaan hibah tidak dapat diperhitungkan sebagai realisasi hibah.
c. dalam hal Pemerintah Daerah tidak dapat menyelesaikan output kegiatan yang tercantum dalam PHD pada masa pelaksanaan hibah, Pemerintah Daerah bertanggung jawab menyelesaikan output kegiatan Hibah RR melalui APBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1280, 'Pemerintah Daerah melaksanakan kegiatan konstruksi dan memperhatikan hal-hal sebagai berikut: a) metode pelaksanaan dan rencana kerja dengan metode aman dan bersih (clean construction); b) penyediaan jalan akses untuk mobilisasi peralatan dan material; c) program dan jadwal pekerjaan; d) gambar kerja (shop drawing) dan perubahan desain bila terjadi perbedaan dengan lapangan; e) pendirian bangunan kantor dan gudang proyek; f) mobilisasi peralatan, material dan tenaga kerja; g) penempatan dan penyediaan material di lokasi; h) hal lainnya sesuai kebutuhan kegiatan.
3. Masa Pelaksanaan Hibah Rehabilitasi dan Rekonstruksi Pemerintah daerah menyelesaikan penganggaran dan pelaksanaan kegiatan Hibah RR sesuai dengan jangka waktu yang telah ditetapkan pada PHD.
Hal-hal yang perlu diperhatikan dalam masa pelaksanaan Hibah Rehabilitasi dan Rekonstruksi adalah sebagai berikut:
a. proses pengadaan barang/jasa dan proses penyusunan kontrak/perjanjian harus memperhatikan ketentuan perundang-undangan.
b. pelaksanaan kegiatan dan penyerapan anggaran yang melampaui masa pelaksanaan hibah tidak dapat diperhitungkan sebagai realisasi hibah.
c. dalam hal Pemerintah Daerah tidak dapat menyelesaikan output kegiatan yang tercantum dalam PHD pada masa pelaksanaan hibah, Pemerintah Daerah bertanggung jawab menyelesaikan output kegiatan Hibah RR melalui APBD.', 'BAB II (lanjutan 6)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1281, 'juklak-9-2024', 14, 'lain', 'BAB II (lanjutan 7)', NULL, 7, '4. Perubahan RKA Dalam hal pemerintah daerah mengidentifikasi adanya kebutuhan perubahan nilai volume dan harga satuan kegiatan dari RKA yang telah ditetapkan sebelumnya, pemerintah daerah harus mengajukan permohonan perubahan RKA dengan ketentuan sebagai berikut:
a. terdapat kebutuhan penyesuaian teknis kegiatan dan/atau terdapat penyesuaian atas standar biaya, dan/atau penyesuaian biaya lainnya berdasarkan peraturan perundang-undangan yang berlaku.
b. tidak diperkenankan adanya perubahan jenis kegiatan, perubahan lokasi kegiatan, penambahan kegiatan, dan optimalisasi pelaksanaan sisa tender yang dialihkan untuk paket kegiatan lain dalam RKA.
c. dilaksanakan paling lama 6 (enam) bulan sejak ditetapkannya PHD.
d. surat permohonan perubahan RKA disampaikan oleh kepala daerah kepada Kepala BNPB c.q. Deputi Bidang Rehabilitasi dan Rekonstruksi disampaikan paling lambat 5 (lima) bulan sejak ditetapkannya PHD dan sebelum pelaksanaan kegiatan konstruksi atas perubahan tersebut, dengan melampirkan:
1) telaahan PPK yang memuat detail usulan perubahan sesuai dengan format 2 lampiran;
2) matrik rincian perubahan RKA semula-menjadi sesuai dengan format 3 lampiran;
3) berita acara rapat koordinasi yang ditandatangani bersama yang dapat melibatkan perangkat daerah teknis terkait, APIP, Bappeda, Keuangan Daerah, Kalaksa BPBD, PPK, Tim Teknis, dan pihak lainnya yang menyebutkan kesepakatan diusulkannya perubahan RKA disertai dengan detail penjelasan sesuai dengan bidang masing-masing;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1281, '4. Perubahan RKA Dalam hal pemerintah daerah mengidentifikasi adanya kebutuhan perubahan nilai volume dan harga satuan kegiatan dari RKA yang telah ditetapkan sebelumnya, pemerintah daerah harus mengajukan permohonan perubahan RKA dengan ketentuan sebagai berikut:
a. terdapat kebutuhan penyesuaian teknis kegiatan dan/atau terdapat penyesuaian atas standar biaya, dan/atau penyesuaian biaya lainnya berdasarkan peraturan perundang-undangan yang berlaku.
b. tidak diperkenankan adanya perubahan jenis kegiatan, perubahan lokasi kegiatan, penambahan kegiatan, dan optimalisasi pelaksanaan sisa tender yang dialihkan untuk paket kegiatan lain dalam RKA.
c. dilaksanakan paling lama 6 (enam) bulan sejak ditetapkannya PHD.
d. surat permohonan perubahan RKA disampaikan oleh kepala daerah kepada Kepala BNPB c.q. Deputi Bidang Rehabilitasi dan Rekonstruksi disampaikan paling lambat 5 (lima) bulan sejak ditetapkannya PHD dan sebelum pelaksanaan kegiatan konstruksi atas perubahan tersebut, dengan melampirkan:
1) telaahan PPK yang memuat detail usulan perubahan sesuai dengan format 2 lampiran;
2) matrik rincian perubahan RKA semula-menjadi sesuai dengan format 3 lampiran;
3) berita acara rapat koordinasi yang ditandatangani bersama yang dapat melibatkan perangkat daerah teknis terkait, APIP, Bappeda, Keuangan Daerah, Kalaksa BPBD, PPK, Tim Teknis, dan pihak lainnya yang menyebutkan kesepakatan diusulkannya perubahan RKA disertai dengan detail penjelasan sesuai dengan bidang masing-masing;', 'BAB II (lanjutan 7)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1282, 'juklak-9-2024', 15, 'lain', 'BAB II (lanjutan 8)', NULL, 8, '4) justifikasi teknis yang dapat ditandatangani oleh tim teknis, PPK, dan mengetahui Kalaksa BPBD, dengan disertai dokumen rencana teknis dan dokumentasi semula-menjadi menggunakan geotagging;
5) rekomendasi teknis atau lampiran data dukung dari K/L atau perangkat teknis terkait;
6) jadwal pelaksanaan yang memuat rencana pelaksanaan kegiatan yang diusulkan untuk perubahan sesuai dengan format 4 lampiran; dan 7) standar satuan harga baru yang ditetapkan oleh Kepala Daerah.
Dalam melaksanakan perubahan RKA, dilakukan rapat koordinasi yang dapat melibatkan: a) Pemerintah Daerah 1) Kepala Daerah atau pejabat yang diberi kuasa;
2) Inspektorat Daerah;
3) Bappeda;
4) Perangkat daerah teknis terkait;
5) Badan Keuangan Daerah;
6) Kalaksa BPBD;
7) Pejabat Pembuat Komitmen;
8) Tim Teknis;
9) BPBD Provinsi (sebagai pelaksana pemantauan dan evaluasi);
10) Pihak terkait lainnya. b) BNPB 1) Deputi atau pejabat yang diberi kuasa;
2) Tim pendamping wilayah pemohon perubahan RKA;
3) Tim verifikasi usulan bantuan dana Hibah RR pada wilayah pemohon perubahan RKA; dan 4) Tim asistensi RKA Hibah RR pada wilayah pemohon perubahan RKA.
Hasil rapat koordinasi dituangkan dalam berita acara sesuai dengan pada format berita acara koordinasi pada sesuai dengan format 5 lampiran. Berdasarkan penelaahan terhadap kelengkapan dokumen perubahan RKA dan hasil rapat koordinasi, Direktur menyampaikan Nota Dinas tentang hasil telaah kepada sesuai dengan format 6 lampiran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1282, '4) justifikasi teknis yang dapat ditandatangani oleh tim teknis, PPK, dan mengetahui Kalaksa BPBD, dengan disertai dokumen rencana teknis dan dokumentasi semula-menjadi menggunakan geotagging;
5) rekomendasi teknis atau lampiran data dukung dari K/L atau perangkat teknis terkait;
6) jadwal pelaksanaan yang memuat rencana pelaksanaan kegiatan yang diusulkan untuk perubahan sesuai dengan format 4 lampiran; dan 7) standar satuan harga baru yang ditetapkan oleh Kepala Daerah.
Dalam melaksanakan perubahan RKA, dilakukan rapat koordinasi yang dapat melibatkan: a) Pemerintah Daerah 1) Kepala Daerah atau pejabat yang diberi kuasa;
2) Inspektorat Daerah;
3) Bappeda;
4) Perangkat daerah teknis terkait;
5) Badan Keuangan Daerah;
6) Kalaksa BPBD;
7) Pejabat Pembuat Komitmen;
8) Tim Teknis;
9) BPBD Provinsi (sebagai pelaksana pemantauan dan evaluasi);
10) Pihak terkait lainnya. b) BNPB 1) Deputi atau pejabat yang diberi kuasa;
2) Tim pendamping wilayah pemohon perubahan RKA;
3) Tim verifikasi usulan bantuan dana Hibah RR pada wilayah pemohon perubahan RKA; dan 4) Tim asistensi RKA Hibah RR pada wilayah pemohon perubahan RKA.
Hasil rapat koordinasi dituangkan dalam berita acara sesuai dengan pada format berita acara koordinasi pada sesuai dengan format 5 lampiran. Berdasarkan penelaahan terhadap kelengkapan dokumen perubahan RKA dan hasil rapat koordinasi, Direktur menyampaikan Nota Dinas tentang hasil telaah kepada sesuai dengan format 6 lampiran.', 'BAB II (lanjutan 8)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1283, 'juklak-9-2024', 16, 'lain', 'BAB II (lanjutan 9)', NULL, 9, 'Selanjutnya, Deputi menyampaikan surat tanggapan yang berisikan persetujuan atau penolakan atas permohonan perubahan RKA kepada Kepala Daerah bersangkutan sesuai dengan format 7 lampiran. Menindaklanjuti surat tanggapan Deputi, Pemerintah Daerah pemohon perubahan RKA yang mendapatkan persetujuan agar mengunggah matriks perubahan RKA semula-menjadi yang ditandatangani oleh PPK Pemerintah Daerah penerima Hibah RR di aplikasi E-Pelaporan serta disampaikan kepada Pemerintah Provinsi.
Salinan Perubahan RKA berupa matriks perubahan RKA semula mejadi disampaikan oleh BNPB kepada Kementerian Keuangan c.q Direktorat Jenderal Perimbangan Keuangan paling lambat 15 (lima belas) hari kalender setelah perubahan RKA disetujui.
Perubahan RKA yang telah mendapat persetujuan BNPB selanjutnya dimuat dan ditetapkan dalam DPA serta diunggah pada aplikasi E-Pelaporan.
Perubahan RKA dan pelaksanaan Hibah RR sepenuhnya menjadi tanggung jawab Pemerintah Daerah.
B. Pelaporan Kepala Daerah atau pejabat yang diberi kuasa oleh Kepala Daerah wajib menyampaikan hasil pelaksanaan Hibah RR berupa laporan berkala dan laporan akhir kepada Kepala BNPB c.q Deputi Bidang Rehabilitasi dan Rekonstruksi dan Menteri yang menyelenggarakan urusan pemerintahan di bidang keuangan negara c.q. KPA BUN Pengelolaan Dana Transfer Khusus.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1283, 'Selanjutnya, Deputi menyampaikan surat tanggapan yang berisikan persetujuan atau penolakan atas permohonan perubahan RKA kepada Kepala Daerah bersangkutan sesuai dengan format 7 lampiran. Menindaklanjuti surat tanggapan Deputi, Pemerintah Daerah pemohon perubahan RKA yang mendapatkan persetujuan agar mengunggah matriks perubahan RKA semula-menjadi yang ditandatangani oleh PPK Pemerintah Daerah penerima Hibah RR di aplikasi E-Pelaporan serta disampaikan kepada Pemerintah Provinsi.
Salinan Perubahan RKA berupa matriks perubahan RKA semula mejadi disampaikan oleh BNPB kepada Kementerian Keuangan c.q Direktorat Jenderal Perimbangan Keuangan paling lambat 15 (lima belas) hari kalender setelah perubahan RKA disetujui.
Perubahan RKA yang telah mendapat persetujuan BNPB selanjutnya dimuat dan ditetapkan dalam DPA serta diunggah pada aplikasi E-Pelaporan.
Perubahan RKA dan pelaksanaan Hibah RR sepenuhnya menjadi tanggung jawab Pemerintah Daerah.
B. Pelaporan Kepala Daerah atau pejabat yang diberi kuasa oleh Kepala Daerah wajib menyampaikan hasil pelaksanaan Hibah RR berupa laporan berkala dan laporan akhir kepada Kepala BNPB c.q Deputi Bidang Rehabilitasi dan Rekonstruksi dan Menteri yang menyelenggarakan urusan pemerintahan di bidang keuangan negara c.q. KPA BUN Pengelolaan Dana Transfer Khusus.', 'BAB II (lanjutan 9)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1284, 'juklak-9-2024', 17, 'lain', 'BAB II (lanjutan 10)', NULL, 9, '1. Laporan Berkala Dokumen laporan berkala disampaikan setiap tiga bulan sejak SPPH diterbitkan dan paling lambat 15 (lima belas) hari kalender setelah berakhirnya setiap tahapan dan diinput ke dalam aplikasi E-Pelaporan. a) Laporan berkala pelaksanaan kegiatan terdiri atas:
1) Laporan Berkala Tahap ke-I memuat kemajuan pelaksanaan kegiatan pada bulan ke-1 sampai dengan bulan ke-3;
2) Laporan Berkala Tahap ke-II memuat kemajuan pelaksanaan kegiatan pada bulan ke-4 sampai dengan bulan ke-6;
3) Laporan Berkala Tahap ke-III memuat kemajuan pelaksanaan kegiatan pada bulan ke-7 sampai dengan bulan ke-9;
4) Laporan Berkala Tahap ke-IV memuat kemajuan pelaksanaan kegiatan pada bulan ke-10 sampai dengan bulan ke-12;
5) Laporan Berkala Tahap ke-V memuat kemajuan pelaksanaan kegiatan pada bulan ke-13 sampai dengan bulan ke-15;
6) Laporan Berkala Tahap ke-VI memuat kemajuan pelaksanaan kegiatan pada bulan ke-16 sampai dengan bulan ke-18;
7) Laporan Berkala Tahap ke-VII memuat kemajuan pelaksanaan kegiatan pada bulan ke-19 sampai dengan bulan ke-21;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1284, '1. Laporan Berkala Dokumen laporan berkala disampaikan setiap tiga bulan sejak SPPH diterbitkan dan paling lambat 15 (lima belas) hari kalender setelah berakhirnya setiap tahapan dan diinput ke dalam aplikasi E-Pelaporan. a) Laporan berkala pelaksanaan kegiatan terdiri atas:
1) Laporan Berkala Tahap ke-I memuat kemajuan pelaksanaan kegiatan pada bulan ke-1 sampai dengan bulan ke-3;
2) Laporan Berkala Tahap ke-II memuat kemajuan pelaksanaan kegiatan pada bulan ke-4 sampai dengan bulan ke-6;
3) Laporan Berkala Tahap ke-III memuat kemajuan pelaksanaan kegiatan pada bulan ke-7 sampai dengan bulan ke-9;
4) Laporan Berkala Tahap ke-IV memuat kemajuan pelaksanaan kegiatan pada bulan ke-10 sampai dengan bulan ke-12;
5) Laporan Berkala Tahap ke-V memuat kemajuan pelaksanaan kegiatan pada bulan ke-13 sampai dengan bulan ke-15;
6) Laporan Berkala Tahap ke-VI memuat kemajuan pelaksanaan kegiatan pada bulan ke-16 sampai dengan bulan ke-18;
7) Laporan Berkala Tahap ke-VII memuat kemajuan pelaksanaan kegiatan pada bulan ke-19 sampai dengan bulan ke-21;', 'BAB II (lanjutan 10)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1285, 'juklak-9-2024', 18, 'lain', 'BAB II (lanjutan 11)', NULL, 10, '8) Laporan Berkala Tahap ke-VIII memuat kemajuan pelaksanaan kegiatan pada bulan ke-22 sampai dengan bulan ke-24. b) Kewajiban penyampaian laporan berkala disesuaikan dengan masa pelaksanaan hibah yang ditetapkan dalam PHD. c) Laporan berkala dibuat oleh PPK Pemerintah Daerah penerima Hibah RR dengan surat pengantar oleh Kepala Daerah yang ditujukan kepada Kepala BNPB c.q Deputi Bidang Rehabilitasi dan Rekonstruksi, Menteri yang menyelenggarakan urusan pemerintahan di bidang keuangan negara c.q. KPA BUN Pengelolaan Dana Transfer Khusus, dengan tembusan Kalaksa BPBD Provinsi.
Sistematika laporan berkala mengacu sesuai format 8 lampiran yang paling sedikit memuat:
1) penganggaran dalam APBD berupa DPA yang telah disahkan;
2) pelaksanaan pengadaan dapat berupa bukti tayang pelaksanaan pengadaan;
3) resume kontrak (menyesuaikan saat mulai kontrak);
4) realisasi penyerapan dana yang disertai rekapitulasi SP2D yang disahkan oleh instansi teknis terkait;
5) uraian detail pelaksanaan kegiatan pada periode tahapan beserta kronologis kendala pelaksanaan kegiatan dan rencana tindak lanjut dan/atau percepatan;
6) dokumentasi pelaksanaan kegiatan berupa foto berwarna dengan format geo-tagging yang memuat tanggal, nama lokasi, dan titik koordinat; dan 7) matrik progres pelaksanaan kegiatan berupa hasil cetak dari aplikasi E-Pelaporan yang ditandatangani oleh PPK mengetahui Kalaksa BPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1285, '8) Laporan Berkala Tahap ke-VIII memuat kemajuan pelaksanaan kegiatan pada bulan ke-22 sampai dengan bulan ke-24. b) Kewajiban penyampaian laporan berkala disesuaikan dengan masa pelaksanaan hibah yang ditetapkan dalam PHD. c) Laporan berkala dibuat oleh PPK Pemerintah Daerah penerima Hibah RR dengan surat pengantar oleh Kepala Daerah yang ditujukan kepada Kepala BNPB c.q Deputi Bidang Rehabilitasi dan Rekonstruksi, Menteri yang menyelenggarakan urusan pemerintahan di bidang keuangan negara c.q. KPA BUN Pengelolaan Dana Transfer Khusus, dengan tembusan Kalaksa BPBD Provinsi.
Sistematika laporan berkala mengacu sesuai format 8 lampiran yang paling sedikit memuat:
1) penganggaran dalam APBD berupa DPA yang telah disahkan;
2) pelaksanaan pengadaan dapat berupa bukti tayang pelaksanaan pengadaan;
3) resume kontrak (menyesuaikan saat mulai kontrak);
4) realisasi penyerapan dana yang disertai rekapitulasi SP2D yang disahkan oleh instansi teknis terkait;
5) uraian detail pelaksanaan kegiatan pada periode tahapan beserta kronologis kendala pelaksanaan kegiatan dan rencana tindak lanjut dan/atau percepatan;
6) dokumentasi pelaksanaan kegiatan berupa foto berwarna dengan format geo-tagging yang memuat tanggal, nama lokasi, dan titik koordinat; dan 7) matrik progres pelaksanaan kegiatan berupa hasil cetak dari aplikasi E-Pelaporan yang ditandatangani oleh PPK mengetahui Kalaksa BPBD.', 'BAB II (lanjutan 11)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1286, 'juklak-9-2024', 19, 'lain', 'BAB II (lanjutan 12)', NULL, 10, '2. Laporan Akhir Kepala Daerah atau pejabat yang diberi kuasa oleh Kepala Daerah menyampaikan laporan akhir pelaksanaan kegiatan dalam bentuk dokumen fisik (hardcopy) kepada Kepala BNPB c.q Deputi Bidang Rehabilitasi dan Rekonstruksi dan Menteri yang menyelenggarakan urusan pemerintahan di bidang keuangan negara c.q. KPA BUN Pengelolaan Dana Transfer Khusus, dan dokumen elektronik (softcopy) di-input dalam aplikasi E-Pelaporan paling lambat 60 (enam puluh) hari kalender sejak berakhirnya masa pelaksanaan kegiatan.
Dalam hal penerima Hibah RR adalah Pemerintah Kabupaten/Kota, laporan akhir perlu ditembuskan kepada Gubernur dan Kalaksa BPBD Provinsi di wilayahnya.
Laporan akhir pelaksanaan kegiatan berisi sesuai dengan format 9 lampiran: a) Surat pengantar penyampaian laporan akhir oleh Kepala Daerah; b) BAB I - Pendahuluan memuat kronologis pengajuan proposal sampai penerimaan hibah dan realisasi rincian kegiatan yang dilaksanakan sesuai dengan RKA; c) Bab II - Pelaksanaan kegiatan memuat:
1) Ruang lingkup kegiatan Rehabilitasi dan Rekonstruksi pascabencana;
2) Lokasi pekerjaan kegiatan Rehabilitasi dan Rekonstruksi pascabencana;
3) Informasi kontrak kegiatan Rehabilitasi dan Rekonstruksi pascabencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1286, '2. Laporan Akhir Kepala Daerah atau pejabat yang diberi kuasa oleh Kepala Daerah menyampaikan laporan akhir pelaksanaan kegiatan dalam bentuk dokumen fisik (hardcopy) kepada Kepala BNPB c.q Deputi Bidang Rehabilitasi dan Rekonstruksi dan Menteri yang menyelenggarakan urusan pemerintahan di bidang keuangan negara c.q. KPA BUN Pengelolaan Dana Transfer Khusus, dan dokumen elektronik (softcopy) di-input dalam aplikasi E-Pelaporan paling lambat 60 (enam puluh) hari kalender sejak berakhirnya masa pelaksanaan kegiatan.
Dalam hal penerima Hibah RR adalah Pemerintah Kabupaten/Kota, laporan akhir perlu ditembuskan kepada Gubernur dan Kalaksa BPBD Provinsi di wilayahnya.
Laporan akhir pelaksanaan kegiatan berisi sesuai dengan format 9 lampiran: a) Surat pengantar penyampaian laporan akhir oleh Kepala Daerah; b) BAB I - Pendahuluan memuat kronologis pengajuan proposal sampai penerimaan hibah dan realisasi rincian kegiatan yang dilaksanakan sesuai dengan RKA; c) Bab II - Pelaksanaan kegiatan memuat:
1) Ruang lingkup kegiatan Rehabilitasi dan Rekonstruksi pascabencana;
2) Lokasi pekerjaan kegiatan Rehabilitasi dan Rekonstruksi pascabencana;
3) Informasi kontrak kegiatan Rehabilitasi dan Rekonstruksi pascabencana;', 'BAB II (lanjutan 12)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1287, 'juklak-9-2024', 20, 'lain', 'BAB II (lanjutan 13)', NULL, 11, '4) Narasi pelaksanaan perkegiatan Rehabilitasi dan Rekonstruksi pascabencana dari Tahapan I hingga selesai. d) BAB III - Kendala dan tindak lanjut yang membahas permasalahan selama pelaksanan kegiatan Hibah RR dan tindak lanjut penyelesaian masalah; e) BAB IV - Kesimpulan dan saran: memuat dampak kegiatan Hibah RR dan keberlanjutan pencegahan bencana pada lokasi kegiatan serta saran perbaikan. f) Lampiran laporan akhir:
1) Matrik realisasi akhir berupa hasil cetak dari aplikasi E-Pelaporan yang ditandatangani oleh PPK sesuai dengan format 10 lampiran;
2) Fotocopy PHD sesuai dengan format 11 lampiran;
3) Tabel rekap SP2D realisasi hibah yang berlaku yang sudah ditandatangani oleh Kepala Badan Keuangan Daerah sesuai dengan format 12 lampiran;
4) Fotocopy bukti setoran sisa dana ke RKUN dan hasil cetak dari aplikasi sistem penerimaan negara sesuai dengan Peraturan Menteri Keuangan mengenai sistem penerimaan negara secara elektronik, dengan status sudah dibayar sesuai dengan format 13 lampiran;
5) Resume kontrak yang ditandatangani oleh PPK sesuai dengan format 14 lampiran;
6) Fotocopy Berita Acara Serah Terima Pekerjaan (BAST/PHO);
7) Fotocopy Berita Acara Pembayaran Terakhir;
8) Dokumentasi kemajuan pelaksanaan 0%, 50% dan 100% berupa foto berwarna dengan menggunakan geo-tagging yang memuat tanggal, nama lokasi, dan titik koordinat ; dan 9) Hasil reviu APIP Daerah.
10) Hasil output data pemetaan aset dalam aplikasi mapping aset sesuai dengan format 15 lampiran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1287, '4) Narasi pelaksanaan perkegiatan Rehabilitasi dan Rekonstruksi pascabencana dari Tahapan I hingga selesai. d) BAB III - Kendala dan tindak lanjut yang membahas permasalahan selama pelaksanan kegiatan Hibah RR dan tindak lanjut penyelesaian masalah; e) BAB IV - Kesimpulan dan saran: memuat dampak kegiatan Hibah RR dan keberlanjutan pencegahan bencana pada lokasi kegiatan serta saran perbaikan. f) Lampiran laporan akhir:
1) Matrik realisasi akhir berupa hasil cetak dari aplikasi E-Pelaporan yang ditandatangani oleh PPK sesuai dengan format 10 lampiran;
2) Fotocopy PHD sesuai dengan format 11 lampiran;
3) Tabel rekap SP2D realisasi hibah yang berlaku yang sudah ditandatangani oleh Kepala Badan Keuangan Daerah sesuai dengan format 12 lampiran;
4) Fotocopy bukti setoran sisa dana ke RKUN dan hasil cetak dari aplikasi sistem penerimaan negara sesuai dengan Peraturan Menteri Keuangan mengenai sistem penerimaan negara secara elektronik, dengan status sudah dibayar sesuai dengan format 13 lampiran;
5) Resume kontrak yang ditandatangani oleh PPK sesuai dengan format 14 lampiran;
6) Fotocopy Berita Acara Serah Terima Pekerjaan (BAST/PHO);
7) Fotocopy Berita Acara Pembayaran Terakhir;
8) Dokumentasi kemajuan pelaksanaan 0%, 50% dan 100% berupa foto berwarna dengan menggunakan geo-tagging yang memuat tanggal, nama lokasi, dan titik koordinat ; dan 9) Hasil reviu APIP Daerah.
10) Hasil output data pemetaan aset dalam aplikasi mapping aset sesuai dengan format 15 lampiran.', 'BAB II (lanjutan 13)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1288, 'juklak-9-2024', 21, 'lain', 'BAB II (lanjutan 14)', NULL, 12, 'Dalam penyusunan laporan akhir perlu memperhatikan check list kelengkapan laporan akhir sebagaimana terlampir dalam format 16.
C. Sisa Dana Dalam hal Pemerintah Daerah telah menyelesaikan kegiatan hibah sesuai dengan jangka waktu yang telah ditetapkan pada PHD dan berdasarkan reviu APIP Daerah masih terdapat sisa dana Hibah RR di RKUD, Pemerintah Daerah wajib menyetorkan sisa dana Hibah RR ke RKUN.
Dalam hal Pemerintah Daerah tidak dapat menyelesaikan kegiatan Hibah RR sesuai dengan jangka waktu yang telah ditetapkan pada PHD serta berdasarkan reviu APIP Daerah masih terdapat sisa dana Hibah RR di RKUD, Pemerintah Daerah wajib menyetorkan sisa dana Hibah ke RKUN dan bertanggung jawab menyelesaikan kegiatan Rehabilitasi dan Rekonstruksi pascabencana melalui APBD.
Penyetoran sisa dana Hibah ke RKUN dilaksanakan paling lambat 120 (seratus dua puluh) hari kalender sejak berakhirnya batas waktu pelaksanaan Hibah RR. Tata cara penyetoran sisa dana Hibah RR dilaksanakan sesuai dengan Peraturan Menteri Keuangan mengenai sistem penerimaan negara secara elektronik.
Bukti penyetoran sisa dana disampaikan sebagai lampiran laporan akhir. Dalam hal Pemerintah Daerah belum dapat melampirkan bukti penyetoran sisa dana sampai dengan batas waktu penyampaian laporan akhir, maka Pemerintah Daerah menyampaikan secara terpisah paling lambat 3 (tiga) hari kalender setelah batas waktu penyetoran sisa dana berakhir.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1288, 'Dalam penyusunan laporan akhir perlu memperhatikan check list kelengkapan laporan akhir sebagaimana terlampir dalam format 16.
C. Sisa Dana Dalam hal Pemerintah Daerah telah menyelesaikan kegiatan hibah sesuai dengan jangka waktu yang telah ditetapkan pada PHD dan berdasarkan reviu APIP Daerah masih terdapat sisa dana Hibah RR di RKUD, Pemerintah Daerah wajib menyetorkan sisa dana Hibah RR ke RKUN.
Dalam hal Pemerintah Daerah tidak dapat menyelesaikan kegiatan Hibah RR sesuai dengan jangka waktu yang telah ditetapkan pada PHD serta berdasarkan reviu APIP Daerah masih terdapat sisa dana Hibah RR di RKUD, Pemerintah Daerah wajib menyetorkan sisa dana Hibah ke RKUN dan bertanggung jawab menyelesaikan kegiatan Rehabilitasi dan Rekonstruksi pascabencana melalui APBD.
Penyetoran sisa dana Hibah ke RKUN dilaksanakan paling lambat 120 (seratus dua puluh) hari kalender sejak berakhirnya batas waktu pelaksanaan Hibah RR. Tata cara penyetoran sisa dana Hibah RR dilaksanakan sesuai dengan Peraturan Menteri Keuangan mengenai sistem penerimaan negara secara elektronik.
Bukti penyetoran sisa dana disampaikan sebagai lampiran laporan akhir. Dalam hal Pemerintah Daerah belum dapat melampirkan bukti penyetoran sisa dana sampai dengan batas waktu penyampaian laporan akhir, maka Pemerintah Daerah menyampaikan secara terpisah paling lambat 3 (tiga) hari kalender setelah batas waktu penyetoran sisa dana berakhir.', 'BAB II (lanjutan 14)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1289, 'juklak-9-2024', 22, 'lain', 'BAB III', NULL, 13, 'PEMANTAUAN DAN EVALUASI Secara umum pelaksanaan Pemantauan dan Evaluasi memperhatikan hal sebagai berikut.
1. Pemantauan dan evaluasi dilaksanakan oleh BNPB dan Kementerian Keuangan secara mandiri dan/atau bersama-sama atas kinerja pelaksanaan kegiatan Hibah RR oleh Pemerintah Daerah. Pemerintah Provinsi juga melaksanakan pemantauan dan evaluasi terhadap kabupaten/kota yang mendapatkan dana Hibah RR di wilayahnya dengan menggunakan APBD.
2. Pemantauan dilakukan secara periodik dapat berupa periode bulanan, tahapan, semester dan/atau bersifat insidental.
3. Pemantauan dan evaluasi bertujuan untuk mengidentifikasi: a) Kesesuaian antara kegiatan yang dilaksanakan dengan yang tertuang dalam PHD dan RKA; b) Permasalahan dan solusi yang relevan untuk dilaksanakan dalam rangka pencapaian tujuan kegiatan;
4. Ruang lingkup pemantauan dan evaluasi antara lain: a) Proses pelaporan Hibah RR dimulai dari SPPH diterbitkan hingga penyampaian laporan akhir dan penyetoran sisa dana; b) Rencana dan realisasi kegiatan Hibah RR yang tertuang dalam PHD dan RKA, laporan tahapan dan laporan akhir.
A. Pemantauan Dan Evaluasi Oleh Pemerintah Pemantauan dan evaluasi dilakukan terhadap kegiatan yang tercantum dalam dokumen RKA dan PHD sejak proses persiapan sampai dengan kegiatan selesai dilaksanakan agar sesuai target keluaran atau output.
Pemantauan dan evaluasi atas pelaksanaan kegiatan Hibah RR dilakukan melalui:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1289, 'PEMANTAUAN DAN EVALUASI Secara umum pelaksanaan Pemantauan dan Evaluasi memperhatikan hal sebagai berikut.
1. Pemantauan dan evaluasi dilaksanakan oleh BNPB dan Kementerian Keuangan secara mandiri dan/atau bersama-sama atas kinerja pelaksanaan kegiatan Hibah RR oleh Pemerintah Daerah. Pemerintah Provinsi juga melaksanakan pemantauan dan evaluasi terhadap kabupaten/kota yang mendapatkan dana Hibah RR di wilayahnya dengan menggunakan APBD.
2. Pemantauan dilakukan secara periodik dapat berupa periode bulanan, tahapan, semester dan/atau bersifat insidental.
3. Pemantauan dan evaluasi bertujuan untuk mengidentifikasi: a) Kesesuaian antara kegiatan yang dilaksanakan dengan yang tertuang dalam PHD dan RKA; b) Permasalahan dan solusi yang relevan untuk dilaksanakan dalam rangka pencapaian tujuan kegiatan;
4. Ruang lingkup pemantauan dan evaluasi antara lain: a) Proses pelaporan Hibah RR dimulai dari SPPH diterbitkan hingga penyampaian laporan akhir dan penyetoran sisa dana; b) Rencana dan realisasi kegiatan Hibah RR yang tertuang dalam PHD dan RKA, laporan tahapan dan laporan akhir.
A. Pemantauan Dan Evaluasi Oleh Pemerintah Pemantauan dan evaluasi dilakukan terhadap kegiatan yang tercantum dalam dokumen RKA dan PHD sejak proses persiapan sampai dengan kegiatan selesai dilaksanakan agar sesuai target keluaran atau output.
Pemantauan dan evaluasi atas pelaksanaan kegiatan Hibah RR dilakukan melalui:', 'BAB III', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1290, 'juklak-9-2024', 23, 'lain', 'BAB III (lanjutan 1)', NULL, 13, '1. Pelaporan Terhadap laporan berkala dan laporan akhir dilakukan asistensi kelengkapan dan kesesuaian dokumen yang disampaikan oleh Pemerintah Daerah penerima Hibah RR.
2. Rapat Koordinasi Rapat koordinasi dilakukan dengan mengadakan pertemuan dengan Pemerintah Daerah penerima Hibah RR secara periodik maupun insidental. Pada pertemuan ini dilakukan penilaian terhadap kesesuaian antara rencana dengan realisasi pelaksanaan kegiatan, pembahasan permasalahan yang dihadapi oleh Pemerintah Daerah dan informasi lainnya yang dibutuhkan terhadap pelaksanaan kegiatan Hibah RR.
Dengan metode ini diharapkan rekomendasi yang relevan terhadap permasalahan yang dihadapi oleh setiap Pemerintah Daerah penerima Hibah RR dapat diperoleh. Hasil rapat koordinasi yang dilakukan secara periodik berupa laporan legiatan, sementara yang dilakukan secara insidentil dapat berupa Berita Acara, Surat Teguran, dan Notulensi Rapat.
3. Rekonsiliasi BNPB, Kementerian yang menyelenggarakan urusan pemerintahan di bidang keuangan negara dan Pemerintah Daerah melakukan rekonsiliasi atas kinerja pelaksanaan kegiatan setiap tahapan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1290, '1. Pelaporan Terhadap laporan berkala dan laporan akhir dilakukan asistensi kelengkapan dan kesesuaian dokumen yang disampaikan oleh Pemerintah Daerah penerima Hibah RR.
2. Rapat Koordinasi Rapat koordinasi dilakukan dengan mengadakan pertemuan dengan Pemerintah Daerah penerima Hibah RR secara periodik maupun insidental. Pada pertemuan ini dilakukan penilaian terhadap kesesuaian antara rencana dengan realisasi pelaksanaan kegiatan, pembahasan permasalahan yang dihadapi oleh Pemerintah Daerah dan informasi lainnya yang dibutuhkan terhadap pelaksanaan kegiatan Hibah RR.
Dengan metode ini diharapkan rekomendasi yang relevan terhadap permasalahan yang dihadapi oleh setiap Pemerintah Daerah penerima Hibah RR dapat diperoleh. Hasil rapat koordinasi yang dilakukan secara periodik berupa laporan legiatan, sementara yang dilakukan secara insidentil dapat berupa Berita Acara, Surat Teguran, dan Notulensi Rapat.
3. Rekonsiliasi BNPB, Kementerian yang menyelenggarakan urusan pemerintahan di bidang keuangan negara dan Pemerintah Daerah melakukan rekonsiliasi atas kinerja pelaksanaan kegiatan setiap tahapan.', 'BAB III (lanjutan 1)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1291, 'juklak-9-2024', 24, 'lain', 'BAB III (lanjutan 2)', NULL, 13, 'Berdasarkan hasil rekonsiliasi, BNPB menyampaikan laporan hasil pemantauan dan evaluasi atas rekonsiliasi yang memuat perkembangan kinerja pelaksanaan fisik kegiatan, perkembangan realisasi penyerapan dana, permasalahan yang dihadapi, dan tindak lanjut yang diperlukan kepada: a) Menteri Koordinator yang membidangi Pembangunan Manusia dan Kebudayaan. b) Menteri yang menyelenggarakan urusan pemerintahan di bidang keuangan negara. c) Menteri yang menyelenggarakan urusan pemerintahan di bidang perencanaan pembangunan nasional. d) Menteri yang menyelenggarakan urusan pemerintahan dalam negeri.
4. Kunjungan ke Lokasi Kegiatan Hibah RR Kunjungan dan peninjauan langsung ke lokasi kegiatan dilakukan guna memastikan kondisi pelaksanaan di lapangan dan memperoleh informasi detail pelaksanaan kegiatan.
Sebelum pelaksanaan pemantauan dan evaluasi, Tim BNPB menyampaikan surat pemberitahuan kepada Pemerintah Daerah penerima Hibah RR. Dalam hal penerima Hibah RR adalah Kabupaten/Kota, maka Tim BNPB juga menyampaikan surat tersebut kepada Pemerintah Provinsi.
Dalam melaksanakan pemantauan dan evaluasi ke lokasi kegiatan hibah RR, Tim BNPB dapat didampingi oleh Kalaksa BPBD, PPK, Tim Teknis, Konsultan Pengawas kegiatan konstruksi, dan pihak lain sesuai bidangnya, dengan mempertimbangkan kondisi di lapangan.
Ruang lingkup pemantauan dan evaluasi ke lokasi kegiatan hibah RR adalah sebagai berikut:
1) pemantauan kemajuan pelaksanaan kegiatan dana Hibah RR;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1291, 'Berdasarkan hasil rekonsiliasi, BNPB menyampaikan laporan hasil pemantauan dan evaluasi atas rekonsiliasi yang memuat perkembangan kinerja pelaksanaan fisik kegiatan, perkembangan realisasi penyerapan dana, permasalahan yang dihadapi, dan tindak lanjut yang diperlukan kepada: a) Menteri Koordinator yang membidangi Pembangunan Manusia dan Kebudayaan. b) Menteri yang menyelenggarakan urusan pemerintahan di bidang keuangan negara. c) Menteri yang menyelenggarakan urusan pemerintahan di bidang perencanaan pembangunan nasional. d) Menteri yang menyelenggarakan urusan pemerintahan dalam negeri.
4. Kunjungan ke Lokasi Kegiatan Hibah RR Kunjungan dan peninjauan langsung ke lokasi kegiatan dilakukan guna memastikan kondisi pelaksanaan di lapangan dan memperoleh informasi detail pelaksanaan kegiatan.
Sebelum pelaksanaan pemantauan dan evaluasi, Tim BNPB menyampaikan surat pemberitahuan kepada Pemerintah Daerah penerima Hibah RR. Dalam hal penerima Hibah RR adalah Kabupaten/Kota, maka Tim BNPB juga menyampaikan surat tersebut kepada Pemerintah Provinsi.
Dalam melaksanakan pemantauan dan evaluasi ke lokasi kegiatan hibah RR, Tim BNPB dapat didampingi oleh Kalaksa BPBD, PPK, Tim Teknis, Konsultan Pengawas kegiatan konstruksi, dan pihak lain sesuai bidangnya, dengan mempertimbangkan kondisi di lapangan.
Ruang lingkup pemantauan dan evaluasi ke lokasi kegiatan hibah RR adalah sebagai berikut:
1) pemantauan kemajuan pelaksanaan kegiatan dana Hibah RR;', 'BAB III (lanjutan 2)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1292, 'juklak-9-2024', 25, 'lain', 'BAB III (lanjutan 3)', NULL, 14, '2) evaluasi pelaksanaan kegiatan dana Hibah RR melalui identifikasi permasalahan dan pemberian saran tindak lanjut.
Pelaksanaan pemantauan dan evaluasi mengacu pada instrumen pemantauan dan evaluasi kegiatan konstruksi sesuai dengan format 17 lampiran.
Laporan hasil pemantauan dan evaluasi ke lokasi disampaikan oleh Tim BNPB kepada pimpinan dengan sistematika laporan sesuai dengan format 18 lampiran sebagai berikut:
1) pendahuluan berisi informasi umum tentang dana hibah, maksud dan tujuan, ruang lingkup, dan dasar hukum pelaksanaan hibah;
2) kegiatan yang dilaksanakan berisi informasi waktu, lokasi, pelaksana, dan metode;
3) hasil yang dicapai berisi uraian capaian pelaksanaan Hibah RR baik keuangan dan fisiknya dan uraian hambatan serta kendala utama yang dihadapi dan rencana tindak lanjut;
4) kesimpulan dan saran;
5) penutup;
6) lampiran: dokumentasi kegiatan, Surat Tugas, Instrumen Pemantauan dan Evaluasi serta dokumen pendukung lainnya.
B. Pemantauan dan Evaluasi oleh Pemerintah Provinsi Pemerintah Provinsi melakukan pemantauan dan evaluasi terhadap kegiatan Hibah RR di Kabupaten/Kota penerima hibah yang berada di wilayahnya dengan alokasi dana melalui APBD. Adapun pemantauan dan evaluasi dapat dilakukan melalui:
1. Penerimaan tembusan laporan berkala Terhadap laporan ini dilakukan telaahan dan analisis terhadap permasalahan yang disampaikan dan rekomendasi tindak lanjut yang kemudian perlu disampaikan kepada Pemerintah Daerah Kabupaten/Kota untuk ditindaklanjuti.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1292, '2) evaluasi pelaksanaan kegiatan dana Hibah RR melalui identifikasi permasalahan dan pemberian saran tindak lanjut.
