INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1294, 'juklak-9-2024', 27, 'lain', 'BAB IV', NULL, 16, 'PENUTUP Petunjuk Pelaksanaan ini digunakan sebagai acuan dalam Mekanisme Pelaksanaan, Pelaporan, Pemantauan, Dan Evaluasi Kegiatan Konstruksi Hibah Rehabilitasi Dan Rekonstruksi Pascabencana bagi pemerintah dan pemerintah daerah dengan harapan agar dapat terlaksana secara tertib, efektif, efisien, ekonomis, transparan, bertanggungjawab dan tepat sasaran.
