INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1307, 'juklak-9-2024', 40, 'lain', 'VI. Saran Tindak Lanjut (memuat pernyataan singkat kebutuhan perubahan RKA) (lanjutan 6)', NULL, 24, 'b. Berita acara rapat koordinasi yang ditandatangani bersama yang melibatkan perangkat daerah teknis yang menyebutkan kesepakatan diusulkannya perubahan RKA disertai dengan detail penjelasan sesuai dengan bidang masing-masing;
