INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1317, 'Lampiran 1 Matrik Kegiatan Lampiran 2 Fotocopy Perjanjian Hibah Daerah Lampiran 3 Lap. Rekap SP2D Yang Sudah Ditandatangani oleh Kepala BPKAD Lampiran 4 Fotocopy Bukti Setoran Sisa Dana Lampiran 5 Fotocopy Resume Kontrak Lampiran 6 Fotocopy Berita Acara Serah Terima Perkerjaan Lampiran 7 Fotocopy Berita Acara Pembayaran Lampiran 8 Dokumentasi Pelaksanaan Kegiatan (0%, 50%, 100%) Lampiran 9 Hasil reviu APIP Daerah Lampiran 10 Hasil output data pemetaan aset dalam aplikasi mapping aset', 'LAMPIRAN', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1318, 'juklak-9-2024', 51, 'lain', 'BAB I', NULL, 33, 'PENDAHULUAN A. Latar Belakang Secara singkat memuat tentang:
1. Kejadian/kronologis bencana
2. Kronologis dari usulan pengajuan Hibah RR sampai penerimaan di RKUD
3. Rincian kegiatan yang dilaksnakan sesuai dengan RKA dan PHD B. Dasar Pelaksanaan
1. Undang-undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana;
2. Undang-undang Nomor 23 Tahun 2014 tentang Pemerintah Daerah sebagaimana telah beberapa kali diubah terakhir dengan Undang-undang Nomor 9 Tahun 2015 tentang Perubahan kedua atas Undang-undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah;
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana;
4. Peraturan Pemerintah Nomor 22 tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana;
5. Perturan Pemenrintah Nomor 2 Tahun 2012 tentang Hibah Daerah;
6. Peraturan Menteri Keuangan Nomor …………. tentang ………………………..;
7. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor …………………. tentang …………………………;
8. Perjanjian Hibah Daerah (PHD) antara Pemerintah Pusat dan Pemerintah Daerah …………..
Nomor: ………….. tanggal ……….. untuk Hibah Rehabilitasi dan Rekonstruksi Pascabencana Tahun Anggaran ……...
C. Maksud dan Tujuan Maksud dari Laporan Akhir ini untuk memenuhi amanat Peraturan Menteri Keuangan Nomor: ……….. tentang …………… dan Peraturan Badan Nasional Penanggulangan Bencana Nomor: ……….. tentang ………………...');
