INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1322, 'juklak-9-2024', 55, 'lain', 'BAB III', NULL, 35, 'KENDALA DAN TINDAK LANJUT A. Kendala Berisi tentang kendala-kendala apa saja selama pelaksanaan kegiatan Hibah Rehabilitasi dan Rekonstruksi dimulai dari sejak dana ditransfer ke RKUD hingga sampai dengan masa pelaksanaan hibah RR berakhir.
B. Tindak Lanjut Berisi tentang tindak lanjut dari penyelesaian kendala pada point A.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1322, 'KENDALA DAN TINDAK LANJUT A. Kendala Berisi tentang kendala-kendala apa saja selama pelaksanaan kegiatan Hibah Rehabilitasi dan Rekonstruksi dimulai dari sejak dana ditransfer ke RKUD hingga sampai dengan masa pelaksanaan hibah RR berakhir.
