INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1328, 'juklak-9-2024', 61, 'lain', 'BAB IV (lanjutan 5)', NULL, 45, 'Kelengkapan No Uraian Keterangan Ada Tidak Surat penyampaian laporan akhir dari Kepala Daerah kepada Kepala BNPB c.q 1 Deputi Bidang Rehabiltasi dan Rehabilitasi Laporan akhir pelaksanaan:
a. BAB I – Pendahuluan memuat kronologis pengajuan proposal sampai penerimaan anggaran dan rincian kegiatan yang dilaksanakan sesuai dengan RKA dan PHD.
b. Bab II – Pelaksanaan kegiatan memuat Ruang lingkup kegiatan Rehabilitasi dan Rekonstruksi pascabencana, Lokasi pekerjaan kegiatan Rehabilitasi dan Rekonstruksi pascabencana, Informasi kontrak kegiatan Rehabilitasi dan Rekonstruksi pascabencana dan narasi pelaksanaan perkegiatan Rehabilitasi 2 dan Rekonstruksi pascabencana dari Tahapan I hingga selesai termasuk kronologi perubahan RKA (jika terdapat perubahan RKA).
c. BAB III – Kendala dan tindak lanjut yang membahas permasalahan selama pelaksanan kegiatan Rehabilitasi dan Rekonstruksi pascabencana dan tindak lanjut penyelesaian masalah.
d. BAB IV – Kesimpulan dan saran memuat dampak kegiatan hibah RR dan keberlanjutan pencegahan bencana pada lokasi kegiatan serta saran perbaikan berdasarkan hasil reviu APIP Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1328, 'Kelengkapan No Uraian Keterangan Ada Tidak Surat penyampaian laporan akhir dari Kepala Daerah kepada Kepala BNPB c.q 1 Deputi Bidang Rehabiltasi dan Rehabilitasi Laporan akhir pelaksanaan:
a. BAB I – Pendahuluan memuat kronologis pengajuan proposal sampai penerimaan anggaran dan rincian kegiatan yang dilaksanakan sesuai dengan RKA dan PHD.
b. Bab II – Pelaksanaan kegiatan memuat Ruang lingkup kegiatan Rehabilitasi dan Rekonstruksi pascabencana, Lokasi pekerjaan kegiatan Rehabilitasi dan Rekonstruksi pascabencana, Informasi kontrak kegiatan Rehabilitasi dan Rekonstruksi pascabencana dan narasi pelaksanaan perkegiatan Rehabilitasi 2 dan Rekonstruksi pascabencana dari Tahapan I hingga selesai termasuk kronologi perubahan RKA (jika terdapat perubahan RKA).
c. BAB III – Kendala dan tindak lanjut yang membahas permasalahan selama pelaksanan kegiatan Rehabilitasi dan Rekonstruksi pascabencana dan tindak lanjut penyelesaian masalah.
d. BAB IV – Kesimpulan dan saran memuat dampak kegiatan hibah RR dan keberlanjutan pencegahan bencana pada lokasi kegiatan serta saran perbaikan berdasarkan hasil reviu APIP Daerah.', 'BAB IV (lanjutan 5)', 'Petunjuk Pelaksanaan Mekanisme Pelaksanaan, Pelaporan, Pemantauan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1329, 'juklak-9-2024', 62, 'lain', 'BAB IV (lanjutan 6)', NULL, 45, 'Matrik realisasi akhir berupa hasil cetak dari aplikasi E-Pelaporan yang 3 ditandatangani oleh Kalaksa BPBD dan di cap/stempel (sesuai Format 9) Fotocopy Perjanjian Hibah Daerah (PHD) 4 (susuai format 10) Tabel rekap SP2D yang sudah 5 ditandatangani oleh Kepala BPKAD dan di cap/stempel (sesuai Format 11) Fotocopy bukti setoran sisa dana ke RKUN dan hasil cetak dengan status sudah dibayar dari sistem penerimaan 6 negara sesuai dengan Peraturan Menteri Keuangan mengenai sistem penerimaan negara secara elektronik dan bukti setor bank (sesuai Format 12) Resume kontrak yang telah 7 ditandatangani oleh PPK dan di stempel/cap (sesuai Format 13) Fotocopy Berita Acara Serah Terima 8 Pekerjaan (BAST/PHO) Fotocopy berita acara pembayaran yang 9 ditandatangani oleh PPK dan di stempel/cap Dokumentasi berwarna 0%, 50% dan 10 100% menggunakan geo-tagging 11 Hasil reviu APIP Daerah Matriks perubahan RKA semula-menjadi 12 yang ditandatangani oleh PPK dan di stempel/cap (sesuai Format 2) Hasil output data pemetaan aset dalam aplikasi mapping aset yang 13 ditandatangani oleh Kalaksa BPBD dan di stempel/cap (sesuai Format 14) Direview pada tanggal:
Oleh:
No Tim Nama Tandatangan 1 PIC / Pelaksana 2 Supervisor 3 Penanggung Jawab Format 17 - Instrumen Pemantauan dan Evaluasi Kegiatan Konstruksi Hibah Rehabilitasi dan Rekonstruksi oleh Pemerintah INSTRUMENT PEMANTAUAN DAN EVALUASI HIBAH REHABILITASI DAN REKONSTRUKSI TA ……… PROV/KAB/KOTA …………………….
A. Informasi Umum
a. Total Dana Hibah Rp');
