INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1338, 'juknis-7-2023', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN PES KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN STANDAR DATA KEJADIAN DAN DAMPAK BENCANA NOMOR 7 TAHUN 2023');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1338, 'SALINAN PES KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN STANDAR DATA KEJADIAN DAN DAMPAK BENCANA NOMOR 7 TAHUN 2023', 'Isi hal. 1', 'Petunjuk Pelaksanaan Nomor 7 Tahun 2023 tentang Standar Data Kejadian dan Dampak Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1339, 'juknis-7-2023', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN LATAR BELAKANG Tren kejadian bencana menunjukan peningkatan dari tahun ke tahun.
Pencatatan data bencana yang sistematis dapat mempermudah pengolahan data bencana, membantu dalam perencanaan pengurangan risiko bencana, pengambilan keputusan yang tepat pada saat keadaan darurat bencana serta program rehabilitasi dan rekonstruksi pascabencana.
Penyelenggaraan penanggulangan Penanganan bencana perlu didukung dengan ketersediaan data yang akurat, mutakhir, terpadu, dapat dipertanggungjawabkan, mudah diakses, dan dapat dibagipakaikan.
Selama ini data bencana yang tersedia belum terintegrasi dengan baik dimana terdapat perbedaan standar data bencana antara kementerian/lembaga, pemerintah daerah dan organisasi lainnya, sehingga menyebabkan kesulitan dalam berbagi pakai data dan membuat rekapitulasi data bencana secara nasional, sehingga standarisasi terkait dengan data bencana menjadi sangat diperlukan untuk ditetapkan.
Badan Nasional Penanggulangan Bencana sebagai lembaga pemerintah nonkementerian yang menangani urusan kebencanaan perlu membakukan dan menyeragamkan standar data bencana di seluruh wilayah Indonesia, salah satunya yaitu dengan memenuhi prinsip Satu Data Indonesia. Pada saat ini telah dikeluarkan Peraturan BNPB Nomor 1 Tahun 2023 tentang Satu Data Bencana, namun pelaksanaan dari peraturan tersebut masih memerlukan petunjuk pelaksanaan yang dapat mengatur implementeasi peraturan tersebut secara lebih lanjut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1339, 'PENDAHULUAN LATAR BELAKANG Tren kejadian bencana menunjukan peningkatan dari tahun ke tahun.
Pencatatan data bencana yang sistematis dapat mempermudah pengolahan data bencana, membantu dalam perencanaan pengurangan risiko bencana, pengambilan keputusan yang tepat pada saat keadaan darurat bencana serta program rehabilitasi dan rekonstruksi pascabencana.
Penyelenggaraan penanggulangan Penanganan bencana perlu didukung dengan ketersediaan data yang akurat, mutakhir, terpadu, dapat dipertanggungjawabkan, mudah diakses, dan dapat dibagipakaikan.
Selama ini data bencana yang tersedia belum terintegrasi dengan baik dimana terdapat perbedaan standar data bencana antara kementerian/lembaga, pemerintah daerah dan organisasi lainnya, sehingga menyebabkan kesulitan dalam berbagi pakai data dan membuat rekapitulasi data bencana secara nasional, sehingga standarisasi terkait dengan data bencana menjadi sangat diperlukan untuk ditetapkan.
Badan Nasional Penanggulangan Bencana sebagai lembaga pemerintah nonkementerian yang menangani urusan kebencanaan perlu membakukan dan menyeragamkan standar data bencana di seluruh wilayah Indonesia, salah satunya yaitu dengan memenuhi prinsip Satu Data Indonesia. Pada saat ini telah dikeluarkan Peraturan BNPB Nomor 1 Tahun 2023 tentang Satu Data Bencana, namun pelaksanaan dari peraturan tersebut masih memerlukan petunjuk pelaksanaan yang dapat mengatur implementeasi peraturan tersebut secara lebih lanjut.', 'BAB I', 'Petunjuk Pelaksanaan Nomor 7 Tahun 2023 tentang Standar Data Kejadian dan Dampak Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1340, 'juknis-7-2023', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Mempertimbangkan wuraian di atas, perlu dibentuk petunjuk pelaksanaan standar data kejadian dan dampak bencana agar data bencana dapat terintegrasi dengan baik guna mewujudkan satu data bencana.
MAKSUD DAN TUJUAN Petunjuk pelaksanaan ini dimaksudkan sebagai panduan untuk BNPB, BPBD, kementerian/lembaga, dan pemangku kepentingan dalam pengelolaan data kejadian dan dampak bencana.
Petunjuk Pelaksanaan ini disusun dengan tujuan:
1. terstandarnya data kejadian dan dampak bencana,
2. tercapainya interoperabilitas data kejadian dan dampak bencana antar BNPB, BPBD, kementerian/lembaga, dan pemangku kepentingan lainnya.
C. RUANG LINGKUP Ruang lingkup Petunjuk Pelaksanaan ini terdiri atas:
a. pengelolaan data, standar data kejadian dan dampak bencana, dan
b. jenis ancaman bencana, kode referensi bencana, ambang batas, metode perhitungan dan daftar data.
D. PENGERTIAN
1. Data adalah catatan atas kumpulan fakta atau deskripsi berupa angka, karakter, simbol, gambar, peta, tanda, isyarat, tulisan, suara, dan/atau bunyi, yang merepresentasikan keadaan sebenarnya atau menunjukkan suatu ide, objek, kondisi, atau situasi.
2. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1340, 'Mempertimbangkan wuraian di atas, perlu dibentuk petunjuk pelaksanaan standar data kejadian dan dampak bencana agar data bencana dapat terintegrasi dengan baik guna mewujudkan satu data bencana.
MAKSUD DAN TUJUAN Petunjuk pelaksanaan ini dimaksudkan sebagai panduan untuk BNPB, BPBD, kementerian/lembaga, dan pemangku kepentingan dalam pengelolaan data kejadian dan dampak bencana.
Petunjuk Pelaksanaan ini disusun dengan tujuan:
1. terstandarnya data kejadian dan dampak bencana,
2. tercapainya interoperabilitas data kejadian dan dampak bencana antar BNPB, BPBD, kementerian/lembaga, dan pemangku kepentingan lainnya.
C. RUANG LINGKUP Ruang lingkup Petunjuk Pelaksanaan ini terdiri atas:
a. pengelolaan data, standar data kejadian dan dampak bencana, dan
b. jenis ancaman bencana, kode referensi bencana, ambang batas, metode perhitungan dan daftar data.
D. PENGERTIAN
1. Data adalah catatan atas kumpulan fakta atau deskripsi berupa angka, karakter, simbol, gambar, peta, tanda, isyarat, tulisan, suara, dan/atau bunyi, yang merepresentasikan keadaan sebenarnya atau menunjukkan suatu ide, objek, kondisi, atau situasi.
2. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 7 Tahun 2023 tentang Standar Data Kejadian dan Dampak Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1341, 'juknis-7-2023', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, '3. Data Bencana adalah Data mengenai Bencana yang sesuai kriteria yang ditetapkan oleh walidata bencana.
4. Standar Data adalah standar yang mendasari Data tertentu yarig terdiri dari lima komponen yaitu konsep, definisi, klasifikasi, ukuran dan satuan.
5. Konsep adalah ide yang mendasari data dan tujuan data tersebut diproduksi.
6. Definisi adalah penjelasan tentang data yang memberi batas atau membedakan secara jelas arti dan cakupan data tertentu dengan data yang lain.
7. Klasifikasi adalah penggolongan data secara sistematis ke dalam kelompok atau kategori berdasarkan kriteria yang telah ditetapkan oleh pembina data atau dibakukan secara luas.
8. Ukuran adalah unit yang digunakan dalam pengukuran jumlah, kadar, atau cakupan.
9. Satuan adalah besaran tertentu dalam data yang digunakan sebagai standar untuk mengukur atau menakar sebagai sebuah keseluruhan.
10. Kode Referensi adalah tanda berisi karakter yang mengandung atau menggambarkan makna, maksud atau norma tertentu sebagai rujukan identitas Data yang bersifat unik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1341, '3. Data Bencana adalah Data mengenai Bencana yang sesuai kriteria yang ditetapkan oleh walidata bencana.
4. Standar Data adalah standar yang mendasari Data tertentu yarig terdiri dari lima komponen yaitu konsep, definisi, klasifikasi, ukuran dan satuan.
5. Konsep adalah ide yang mendasari data dan tujuan data tersebut diproduksi.
6. Definisi adalah penjelasan tentang data yang memberi batas atau membedakan secara jelas arti dan cakupan data tertentu dengan data yang lain.
7. Klasifikasi adalah penggolongan data secara sistematis ke dalam kelompok atau kategori berdasarkan kriteria yang telah ditetapkan oleh pembina data atau dibakukan secara luas.
8. Ukuran adalah unit yang digunakan dalam pengukuran jumlah, kadar, atau cakupan.
9. Satuan adalah besaran tertentu dalam data yang digunakan sebagai standar untuk mengukur atau menakar sebagai sebuah keseluruhan.
10. Kode Referensi adalah tanda berisi karakter yang mengandung atau menggambarkan makna, maksud atau norma tertentu sebagai rujukan identitas Data yang bersifat unik.', 'BAB I (lanjutan 2)', 'Petunjuk Pelaksanaan Nomor 7 Tahun 2023 tentang Standar Data Kejadian dan Dampak Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1342, 'juknis-7-2023', 5, 'lain', 'BAB II', NULL, 3, 'PELAKSANAAN STANDARISASI DATA KEJADIAN DAN DAMPAK BENCANA A. PENGELOLAAN DATA Informasi yang cepat, tepat dan akurat tergantung dari adanya data pendukung yang terstruktur dan mudah dipahami. Penyebarluasan informasi dalam penanggulangan bencana dimulai sejak pengumpulan, pengolahan, dan analisis data. Data dan informasi bencana dikumpulkan dari berbagai sumber, antara lain dari pemerintahan, organisasi relawan/lembaga swadaya masyarakat/masyarakat dan berbagai sumber media. Data dikumpulkan baik secara langsung melalui wawancara ataupun secara tidak langsung seperti dari internet, televisi, media cetak dan sebagainya. Ada dua jenis data, yaitu data dinamis dan data statis. Data dinamis merupakan data tentang kejadian bencana yang bersifat sementara. Artinya data tersebut masih mengalami perubahan sesuai dengan laporan perkembangan selama keadaan darurat bencana. Data statis merupakan data kejadian bencana yang bersifat tetap atau tidak mengalami perubahan.
Dalam pengelolaan data terbagi dua alur pengelolaan data dan informasi dapat dilihat pada Gambar 1.
Gambar 1. Alur Pengelolaan Data dan Informasi Alur manajemen data dan informasi terbagi menjadi dua, yaitu alur manajemen data statis dan alur manajemen data dinamis. Alur manajemen data dinamis digunakan pada saat tanggap darurat bencana dan alur manajemen data statis digunakan dalam proses verifikasi data bencana bulanan/triwulan/semester/tahunan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1342, 'PELAKSANAAN STANDARISASI DATA KEJADIAN DAN DAMPAK BENCANA A. PENGELOLAAN DATA Informasi yang cepat, tepat dan akurat tergantung dari adanya data pendukung yang terstruktur dan mudah dipahami. Penyebarluasan informasi dalam penanggulangan bencana dimulai sejak pengumpulan, pengolahan, dan analisis data. Data dan informasi bencana dikumpulkan dari berbagai sumber, antara lain dari pemerintahan, organisasi relawan/lembaga swadaya masyarakat/masyarakat dan berbagai sumber media. Data dikumpulkan baik secara langsung melalui wawancara ataupun secara tidak langsung seperti dari internet, televisi, media cetak dan sebagainya. Ada dua jenis data, yaitu data dinamis dan data statis. Data dinamis merupakan data tentang kejadian bencana yang bersifat sementara. Artinya data tersebut masih mengalami perubahan sesuai dengan laporan perkembangan selama keadaan darurat bencana. Data statis merupakan data kejadian bencana yang bersifat tetap atau tidak mengalami perubahan.
Dalam pengelolaan data terbagi dua alur pengelolaan data dan informasi dapat dilihat pada Gambar 1.
Gambar 1. Alur Pengelolaan Data dan Informasi Alur manajemen data dan informasi terbagi menjadi dua, yaitu alur manajemen data statis dan alur manajemen data dinamis. Alur manajemen data dinamis digunakan pada saat tanggap darurat bencana dan alur manajemen data statis digunakan dalam proses verifikasi data bencana bulanan/triwulan/semester/tahunan.', 'BAB II', 'Petunjuk Pelaksanaan Nomor 7 Tahun 2023 tentang Standar Data Kejadian dan Dampak Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1343, 'juknis-7-2023', 6, 'lain', 'BAB II (lanjutan 1)', NULL, 3, 'Data dan Informasi bencana harus disimpan secara rapi dan baik secara elektronik maupun dalam bentuk dokumen tertulis. Dalam melakukan analisis data diperlukan prinsip kehati-hatian, teliti dan objektif agar menghasilkan informasi yang tepat, ringkas dan akurat. Sebagai acuan dalam analisis dilakukan dengan memperhatikan apa, di mana, kapan, siapa, mengapa dan bagaimana. Apabila tidak dapat dilakukan, paling sedikit mencakup informasi apa, dimana, kapan dan bagaimana. Data yang telah dianalisis menghasilkan informasi disebarkan secara tepat waktu dan dengan cara yang terstruktur, dengan ketentuan sebagai berikut:
a. saat keadaan darurat bencana data dinamis disampaikan minimal 1 hari sekali atau sesuai dengan kesepakatan dalam pos komando penanganan darurat bencana;
b. data statis disampaikan kepada walidata bencana sesuai dengan periode waktu yang telah ditentukan.
1. Pengumpulan Terdapat dua jenis data bencana yang dikumpulkan, yaitu data dinamis dan data statis. Pengumpulan data bencana ini dilakukan oleh BPBD kabupaten/kota selaku Produsen Data bencana di daerah dan unit kerja BNPB selaku Produsen Data bencana di BNPB.
Data statis dan data dinamis dikumpulkan sesuai dengan format data bencana yang tercantum dalam lampiran I.
2. Pengolahan Data yang telah dikumpulkan kemudian disimpan dan diolah oleh Produsen Data bencana, dengan format worksheet/tabular.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1343, 'Data dan Informasi bencana harus disimpan secara rapi dan baik secara elektronik maupun dalam bentuk dokumen tertulis. Dalam melakukan analisis data diperlukan prinsip kehati-hatian, teliti dan objektif agar menghasilkan informasi yang tepat, ringkas dan akurat. Sebagai acuan dalam analisis dilakukan dengan memperhatikan apa, di mana, kapan, siapa, mengapa dan bagaimana. Apabila tidak dapat dilakukan, paling sedikit mencakup informasi apa, dimana, kapan dan bagaimana. Data yang telah dianalisis menghasilkan informasi disebarkan secara tepat waktu dan dengan cara yang terstruktur, dengan ketentuan sebagai berikut:
a. saat keadaan darurat bencana data dinamis disampaikan minimal 1 hari sekali atau sesuai dengan kesepakatan dalam pos komando penanganan darurat bencana;
b. data statis disampaikan kepada walidata bencana sesuai dengan periode waktu yang telah ditentukan.
1. Pengumpulan Terdapat dua jenis data bencana yang dikumpulkan, yaitu data dinamis dan data statis. Pengumpulan data bencana ini dilakukan oleh BPBD kabupaten/kota selaku Produsen Data bencana di daerah dan unit kerja BNPB selaku Produsen Data bencana di BNPB.
Data statis dan data dinamis dikumpulkan sesuai dengan format data bencana yang tercantum dalam lampiran I.
2. Pengolahan Data yang telah dikumpulkan kemudian disimpan dan diolah oleh Produsen Data bencana, dengan format worksheet/tabular.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 7 Tahun 2023 tentang Standar Data Kejadian dan Dampak Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1344, 'juknis-7-2023', 7, 'lain', 'BAB II (lanjutan 2)', NULL, 4, 'Pengolahan data dilaksanakan melalui kompilasi data, pembersihan data dan verifikasi data. Proses verifikasi data di daerah dilakukan oleh BPBD provinsi, kabupaten/kota berkoordinasi dengan perangkat daerah terkait. Proses verifikasi dapat dilakukan melalui pertemuan dalam rangka pemutakhiran data.
3. Pelaksanaan Analisa Data Jenis analisis yang dilakukan oleh Produsen Data bencana dapat dihasilkan dari pengolahan data, adalah :
a. Analisis komposisi yaitu analisis yang membandingkan nilai kejadian atau lokasi bencana dengan dampak yang dipilih.
Analisa komposisi berguna untuk menunjukkan topologi bencana, dampak pada manusia (strategi kesiapsiagaan), dampak pada perumahan (strategi pembangunan), dampak pada perekonomian dan dampak pada infrastruktur.
b. Analisis temporal yaitu analisis yang menunjukkan aktivitas variabel dampak yang berbeda dari waktu ke waktu. Analisa temporal berguna untuk menunjukkan pola dan korelasi.
c. Analisis statistik yaitu analisis yang ditampilkan dalam bentuk statistik. Analisa statistik berguna untuk menunjukkan keterkaitan antar variabel dampak bencana serta hubungan sebab-akibat.
d. Analisis spasial yaitu analisis yang ditampilkan dalam bentuk peta. Analisa spasial berguna untuk menunjukkan sebaran kejadian maupun dampak bencana.
e. Hasil analisis dapat disajikan dalam bentuk cetak atau digital yang kemudian disampaikan ke Badan Nasional Penanggulangan Bencana selaku walidata bencana di tingkat pusat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1344, 'Pengolahan data dilaksanakan melalui kompilasi data, pembersihan data dan verifikasi data. Proses verifikasi data di daerah dilakukan oleh BPBD provinsi, kabupaten/kota berkoordinasi dengan perangkat daerah terkait. Proses verifikasi dapat dilakukan melalui pertemuan dalam rangka pemutakhiran data.
3. Pelaksanaan Analisa Data Jenis analisis yang dilakukan oleh Produsen Data bencana dapat dihasilkan dari pengolahan data, adalah :
a. Analisis komposisi yaitu analisis yang membandingkan nilai kejadian atau lokasi bencana dengan dampak yang dipilih.
Analisa komposisi berguna untuk menunjukkan topologi bencana, dampak pada manusia (strategi kesiapsiagaan), dampak pada perumahan (strategi pembangunan), dampak pada perekonomian dan dampak pada infrastruktur.
b. Analisis temporal yaitu analisis yang menunjukkan aktivitas variabel dampak yang berbeda dari waktu ke waktu. Analisa temporal berguna untuk menunjukkan pola dan korelasi.
c. Analisis statistik yaitu analisis yang ditampilkan dalam bentuk statistik. Analisa statistik berguna untuk menunjukkan keterkaitan antar variabel dampak bencana serta hubungan sebab-akibat.
d. Analisis spasial yaitu analisis yang ditampilkan dalam bentuk peta. Analisa spasial berguna untuk menunjukkan sebaran kejadian maupun dampak bencana.
e. Hasil analisis dapat disajikan dalam bentuk cetak atau digital yang kemudian disampaikan ke Badan Nasional Penanggulangan Bencana selaku walidata bencana di tingkat pusat.', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Nomor 7 Tahun 2023 tentang Standar Data Kejadian dan Dampak Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1345, 'juknis-7-2023', 8, 'lain', 'BAB II (lanjutan 3)', NULL, 5, '4. Penyajian dan Penyebarluasan Penyajian data bencana dapat berupa tabel, diagram dan peta.
Informasi yang disajikan antara lain pola sebaran kejadian bencana, korban bencana dan kerusakan yang ditimbulkan akibat bencana, serta data rinci tentang kejadian bencana di suatu wilayah tertentu.
Penyebarluasan informasi dapat dilakukan secara ‘online’ melalui Portal Satu Data Bencana atau dashboard dan media lainnya sesuai dengan ketentuan peraturan perundang-undangan.
B. STANDAR DATA KEJADIAN DAN DAMPAK BENCANA
1. Jenis Ancaman Secara garis besar Indonesia memiliki 13 jenis ancaman bencana yang dibagi menjadi 3 klasifikasi bencana yaitu bencana alam, bencana non alam dan bencana sosial yang dikelompokan sesuai dengan tabel berikut :
KLASIFIKASI JENIS KODE NAMA KEJADIAN BENCANA BENCANA BENCANA Bencana Banjir 1. Banjir rob 101 alam 2. Banjir bandang
3. Banjir dan tanah longsor
4. Banjir drainase & selokan
5. Banjir waduk
6. Banjir genangan
7. Tanggul jebol Tanah 1. Longsor 102 longsor 2. Gerakan tanah Gelombang 1. Gelombang pasang 103 pasang dan 2. Abrasi pantai abrasi Cuaca 1. Puting beliung 104 ekstrem 2. Angin kencang
3. Angin topan
4. Hujan es
5. Siklon tropis
6. Suhu udara ekstrem Kekeringan 1. Kekeringan 105 meteorologis
2. Kekeringan hidrologis
3. Kekeringan pertanian Kebakaran 1. Kebakaran hutan 106 hutan dan 2. Kebakaran lahan lahan 3. Kebakaran lahan gambut KLASIFIKASI JENIS KODE NAMA KEJADIAN BENCANA BENCANA BENCANA Gempabumi 1. Gempa tektonik 107
2. Gempa vulkanik');
