INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1355, 'juknis-7-2023', 18, 'lampiran', 'LAMPIRAN I (lanjutan 4)', NULL, 17, '7. Data kerusakan dan kerugian pelayanan dasar No Satuan Pendidikan Rumah Ibadat Fasilitas pelayanan kesehatan Taksiran Taksiran Taksiran RB RS RR Terendam RB RS RR Terendam RB RS RR Terendam kerugian kerugian kerugian 1 2 3 dst No Kantor Pasar RB RS RR Terendam Taksiran RB RS RR Terendam Taksiran kerugian kerugian 1 2 3 dst
8. Data aset dan layanan penanganan kedaruratan No Aset dan layanan penanganan kedaruratan 1 2 3 dst C. Petunjuk Pengisian Format Data KLASIFIKASI DATA DATA SATUA NO KETERANGAN PENDATAAN DINAMIS STATIS N
1. Data kejadian bencana Jenis bencana 1. Bencana Alam 101. Banjir 102. Tanah longsor 103. Gelombang pasang dan abrasi 104. Cuaca ekstrem 105. Kekeringan 106. Kebakaran hutan dan lahan 107. Gempabumi 108. Tsunami 109. Erupsi gunung api
2. Bencana NonAlam 201. Epidemi dan wabah penyakit 202. Kebakaran gedung dan pemukiman 202. Gagal teknologi
3. Bencana Sosial 301. Konflik sosial Nama Nama kejadian dari jenis bencana. kejadian Jika satu kejadian melibatkan lebih dari satu tipe kejadian bencana, ditentukan satu tipe kejadian utama. Misalnya, banjir dapat menyebabkan tanah longsor, jenis kejadiannya adalah banjir sedangkan nama kejadiannya adalah banjir dan tanah longsor.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1355, '7. Data kerusakan dan kerugian pelayanan dasar No Satuan Pendidikan Rumah Ibadat Fasilitas pelayanan kesehatan Taksiran Taksiran Taksiran RB RS RR Terendam RB RS RR Terendam RB RS RR Terendam kerugian kerugian kerugian 1 2 3 dst No Kantor Pasar RB RS RR Terendam Taksiran RB RS RR Terendam Taksiran kerugian kerugian 1 2 3 dst
8. Data aset dan layanan penanganan kedaruratan No Aset dan layanan penanganan kedaruratan 1 2 3 dst C. Petunjuk Pengisian Format Data KLASIFIKASI DATA DATA SATUA NO KETERANGAN PENDATAAN DINAMIS STATIS N
1. Data kejadian bencana Jenis bencana 1. Bencana Alam 101. Banjir 102. Tanah longsor 103. Gelombang pasang dan abrasi 104. Cuaca ekstrem 105. Kekeringan 106. Kebakaran hutan dan lahan 107. Gempabumi 108. Tsunami 109. Erupsi gunung api
2. Bencana NonAlam 201. Epidemi dan wabah penyakit 202. Kebakaran gedung dan pemukiman 202. Gagal teknologi
3. Bencana Sosial 301. Konflik sosial Nama Nama kejadian dari jenis bencana. kejadian Jika satu kejadian melibatkan lebih dari satu tipe kejadian bencana, ditentukan satu tipe kejadian utama. Misalnya, banjir dapat menyebabkan tanah longsor, jenis kejadiannya adalah banjir sedangkan nama kejadiannya adalah banjir dan tanah longsor.', 'LAMPIRAN I (lanjutan 4)', 'Petunjuk Pelaksanaan Nomor 7 Tahun 2023 tentang Standar Data Kejadian dan Dampak Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1356, 'juknis-7-2023', 19, 'lampiran', 'LAMPIRAN I (lanjutan 5)', NULL, 19, 'Tarikh Awal kejadian bencana tanggal – bulan - tahun Waktu Waktu kejadian bencana (Jam) kejadian Lokasi Lokasi kejadian bencana sesuai Provinsi, Kabupaten/kota, Kecamatan, Desa (Nomenklatur wilayah dan kode wilayah mengikuti Peraturan Kemendagri) Letak Latitude/Lintang dan Longitude/Bujur (Penulisan geografis desimal derajat minimal hingga 6 angka signifikan dibelakang koma, contoh: -6,597998; 106,797429) Penyebab Tuliskan pemicu terjadinya bencana bencana Kronologis Tuliskan kronologis terjadinya bencana bencana KLASIFIKASI DATA DATA SATUA NO KETERANGAN PENDATAAN DINAMIS STATIS N Deskripsi Deskripsi bencana dalam hal ini adalah cara penyampaian data/informasi kejadian bencana dengan terperinci melalui kata-kata atau tulisan, yang bertujuan agar data/informasi tersebut dapat dimengerti oleh orang lain yang tidak mengalami kejadian tersebut secara langsung.
Misalnya :
- Bencana banjir mencantumkan tinggi muka air.
- Bencana gempabumi mencantumkan titik episentrum, magnitude, kedalaman.
- Bencana erupsi gunung api mencantumkan nama gunung api yang mengalami erupsi.
- dll Sumber Tuliskan Sumber informasi kejadian bencana Kondisi Tuliskan kondisi terakhir di lokasi bencana mutakhir Status keadaan Tuliskan status bencana yang ditetapkan oleh darurat pemerintah sesuai dengan pedoman penetapan bencana status keadaan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1356, 'Tarikh Awal kejadian bencana tanggal – bulan - tahun Waktu Waktu kejadian bencana (Jam) kejadian Lokasi Lokasi kejadian bencana sesuai Provinsi, Kabupaten/kota, Kecamatan, Desa (Nomenklatur wilayah dan kode wilayah mengikuti Peraturan Kemendagri) Letak Latitude/Lintang dan Longitude/Bujur (Penulisan geografis desimal derajat minimal hingga 6 angka signifikan dibelakang koma, contoh: -6,597998; 106,797429) Penyebab Tuliskan pemicu terjadinya bencana bencana Kronologis Tuliskan kronologis terjadinya bencana bencana KLASIFIKASI DATA DATA SATUA NO KETERANGAN PENDATAAN DINAMIS STATIS N Deskripsi Deskripsi bencana dalam hal ini adalah cara penyampaian data/informasi kejadian bencana dengan terperinci melalui kata-kata atau tulisan, yang bertujuan agar data/informasi tersebut dapat dimengerti oleh orang lain yang tidak mengalami kejadian tersebut secara langsung.
Misalnya :
- Bencana banjir mencantumkan tinggi muka air.
- Bencana gempabumi mencantumkan titik episentrum, magnitude, kedalaman.
- Bencana erupsi gunung api mencantumkan nama gunung api yang mengalami erupsi.
- dll Sumber Tuliskan Sumber informasi kejadian bencana Kondisi Tuliskan kondisi terakhir di lokasi bencana mutakhir Status keadaan Tuliskan status bencana yang ditetapkan oleh darurat pemerintah sesuai dengan pedoman penetapan bencana status keadaan darurat bencana.', 'LAMPIRAN I (lanjutan 5)', 'Petunjuk Pelaksanaan Nomor 7 Tahun 2023 tentang Standar Data Kejadian dan Dampak Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1357, 'juknis-7-2023', 20, 'lampiran', 'LAMPIRAN I (lanjutan 6)', NULL, 20, 'Upaya Tuliskan upaya Rekap Rekap penanganan yang sudah upaya upaya dilakukan penanganan penanganan dalam yang telah yang telah menangani dilakukan dilakukan bencana Dokumentasi Foto, video dan dokumen lainnya Sebaran Sebaran dampak bencana dalam bentuk peta dampak Kode Identitas Contohnya Banjir di Kabupaten Bogor 19 September Bencana (KIB) 2023 maka KIB-nya sebagai berikut :
32 01 101 20230919 1, 15 digit awal dihitung sebagai satu kejadian bencana Catatan:
- Jika kejadian gempabumi yang berdampak empat kabupaten, kejadian nasional dihitung sebagai satu kejadian gempabumi, namun di level kabupaten dihitung satu kejadian tiap kabupaten.
- Jika kejadian bencana berdampak beberapa kecamatan berbeda dengan waktu yang berbeda maka tetap dihitung satu kejadian bencana.
2. Data Kebutuhan KLASIFIKASI DATA DATA SATUA NO KETERANGAN PENDATAAN DINAMIS STATIS N Sumber daya Tuliskan Rekap Rekap manusia kebutuhan kebutuhan kebutuhan sumber daya sumber sumber manusia sesuai daya daya dengan kondisi manusia manusia di lapangan.
Misalnya:
Relawan, tenaga kesehatan (dokter, perawat, bidan, sanitarian, apoteker, ahli gizi dan lain-lain ), TNI/Polri, tenaga SAR, desa siaga, dll.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1357, 'Upaya Tuliskan upaya Rekap Rekap penanganan yang sudah upaya upaya dilakukan penanganan penanganan dalam yang telah yang telah menangani dilakukan dilakukan bencana Dokumentasi Foto, video dan dokumen lainnya Sebaran Sebaran dampak bencana dalam bentuk peta dampak Kode Identitas Contohnya Banjir di Kabupaten Bogor 19 September Bencana (KIB) 2023 maka KIB-nya sebagai berikut :
32 01 101 20230919 1, 15 digit awal dihitung sebagai satu kejadian bencana Catatan:
- Jika kejadian gempabumi yang berdampak empat kabupaten, kejadian nasional dihitung sebagai satu kejadian gempabumi, namun di level kabupaten dihitung satu kejadian tiap kabupaten.
- Jika kejadian bencana berdampak beberapa kecamatan berbeda dengan waktu yang berbeda maka tetap dihitung satu kejadian bencana.
2. Data Kebutuhan KLASIFIKASI DATA DATA SATUA NO KETERANGAN PENDATAAN DINAMIS STATIS N Sumber daya Tuliskan Rekap Rekap manusia kebutuhan kebutuhan kebutuhan sumber daya sumber sumber manusia sesuai daya daya dengan kondisi manusia manusia di lapangan.
Misalnya:
Relawan, tenaga kesehatan (dokter, perawat, bidan, sanitarian, apoteker, ahli gizi dan lain-lain ), TNI/Polri, tenaga SAR, desa siaga, dll.', 'LAMPIRAN I (lanjutan 6)', 'Petunjuk Pelaksanaan Nomor 7 Tahun 2023 tentang Standar Data Kejadian dan Dampak Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1358, 'juknis-7-2023', 21, 'lampiran', 'LAMPIRAN I (lanjutan 7)', NULL, 21, 'Dana Tuliskan Rekap Rekap Rp kebutuhan kebutuhan kebutuhan (juta) dana sesuai dana dana dengan kondisi di lapangan Sarana dan Tuliskan Rekap Rekap prasarana kebutuhan kebutuhan kebutuhan sarana dan sarana dan sarana dan prasarana prasarana prasarana sesuai dengan kondisi di lapangan Logistik Tuliskan Rekap Rekap kebutuhan kebutuhan kebutuhan logistik sesuai logistik logistik dengan kondisi di lapangan Peralatan Tuliskan Rekap Rekap kebutuhan kebutuhan kebutuhan peralatan sesuai peralatan peralatan dengan kondisi di lapangan 3 Data akibat Anak : 0 – 17 Tahun , Dewasa : 17-59 tahun, terhadap Lansia : 60 tahun keatas. manusia Jenis kelamin L/P (korban mengungsi sesuai dengan juklak terkait pengungsi) Meninggal Jumlah korban Nominal Nominal orang meninggal terakhir terakhir KLASIFIKASI DATA DATA SATUA NO KETERANGAN PENDATAAN DINAMIS STATIS N akibat bencana Hilang Jumlah korban Nominal Nominal orang hilang akibat terakhir terakhir bencana Luka/sakit Jumlah korban Nominal Nominal orang luka/sakit terakhir terbesar akibat bencana Menderita/ Jumlah korban Nominal Nominal orang terdampak menderita/terd terakhir terbesar ampak akibat selama bencana masa tanggap darurat Mengungsi Jumlah korban Nominal Nominal orang mengungsi terakhir terbesar akibat bencana selama masa tanggap darurat');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1358, 'Dana Tuliskan Rekap Rekap Rp kebutuhan kebutuhan kebutuhan (juta) dana sesuai dana dana dengan kondisi di lapangan Sarana dan Tuliskan Rekap Rekap prasarana kebutuhan kebutuhan kebutuhan sarana dan sarana dan sarana dan prasarana prasarana prasarana sesuai dengan kondisi di lapangan Logistik Tuliskan Rekap Rekap kebutuhan kebutuhan kebutuhan logistik sesuai logistik logistik dengan kondisi di lapangan Peralatan Tuliskan Rekap Rekap kebutuhan kebutuhan kebutuhan peralatan sesuai peralatan peralatan dengan kondisi di lapangan 3 Data akibat Anak : 0 – 17 Tahun , Dewasa : 17-59 tahun, terhadap Lansia : 60 tahun keatas. manusia Jenis kelamin L/P (korban mengungsi sesuai dengan juklak terkait pengungsi) Meninggal Jumlah korban Nominal Nominal orang meninggal terakhir terakhir KLASIFIKASI DATA DATA SATUA NO KETERANGAN PENDATAAN DINAMIS STATIS N akibat bencana Hilang Jumlah korban Nominal Nominal orang hilang akibat terakhir terakhir bencana Luka/sakit Jumlah korban Nominal Nominal orang luka/sakit terakhir terbesar akibat bencana Menderita/ Jumlah korban Nominal Nominal orang terdampak menderita/terd terakhir terbesar ampak akibat selama bencana masa tanggap darurat Mengungsi Jumlah korban Nominal Nominal orang mengungsi terakhir terbesar akibat bencana selama masa tanggap darurat', 'LAMPIRAN I (lanjutan 7)', 'Petunjuk Pelaksanaan Nomor 7 Tahun 2023 tentang Standar Data Kejadian dan Dampak Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1359, 'juknis-7-2023', 22, 'lampiran', 'LAMPIRAN I (lanjutan 8)', NULL, 22, '4. Data kerusakan dan kerugian sosial ekonomi sawah Tuliskan luas Nominal Nominal Ha sawah yang terakhir terakhir rusak akibat bencana Lahan Tuliskan luas Nominal Nominal Ha lahan yang terakhir terakhir rusak akibat bencana Kebun Tuliskan luas Nominal Nominal Ha kebun yang terakhir terakhir rusak akibat bencana Hutan Tuliskan luas Nominal Nominal Ha hutan yang terakhir terakhir rusak akibat bencana Kios/toko Tuliskan jumlah Nominal Nominal Unit kios/toko rusak terakhir terakhir akibat bencana Kolam Tuliskan luas Nominal Nominal Ha tempat terakhir terakhir melakukan KLASIFIKASI DATA DATA SATUA NO KETERANGAN PENDATAAN DINAMIS STATIS N kegiatan pembudidayaan perikanan yang rusak akibat bencana baik kolam air tawar maupun air payau seperti tambak, kolam budidaya perikanan, dll baik milik perorangan maupun korporasi Pabrik Tuliskan jumlah Nominal Nominal Unit pabrik yang terakhir terakhir rusak akibat bencana Taksiran Jumlah Nominal Nominal Rp kerugian taksiran terakhir terakhir (Juta) kerugian yang dialami ketika terjadi bencana');
