INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1360, 'juknis-7-2023', 23, 'lampiran', 'LAMPIRAN I (lanjutan 9)', NULL, 23, '5. Data kerusakan dan kerugian prasarana dan sarana vital Jaringan air Tuliskan jaringan jaringan air bersih/minum yang bersih/minum rusak akibat bencana Jaringan Tuliskan jaringan lampu dan lampu penerangan lampu dan yang rusak akibat bencana lampu penerangan Jaringan Tuliskan jaringan telekomunikasi yang rusak akibat telekomunikasi bencana Jaringan Tuliskan jaringan irigasi yang rusak akibat bencana irigasi Jaringan jalan dan jembatan ● Jalan Tuliskan Nominal Nominal km panjang jalan terakhir terakhir rusak akibat bencana seperti jalan nasional, provinsi, kabupaten, kota KLASIFIKASI DATA DATA SATUA NO KETERANGAN PENDATAAN DINAMIS STATIS N dan jalan desa. ● Jembatan Tuliskan jumlah Nominal Nominal unit jembatan rusak terakhir terakhir akibat bencana Jaringan Tuliskan jaringan transportasi yang rusak akibat transportasi bencana Jaringan Tuliskan jaringan pengisian bahan bakar umum pengisian (SPBU) yang rusak akibat bencana bahan bakar umum Taksiran Jumlah Nominal Nominal Rp kerugian kerugian yang terakhir terakhir (Juta) dialami ketika terjadi bencana
6. Data kerusakan dan kerugian rumah Rumah Tuliskan jumlah Nominal Nominal Unit rumah rusak terakhir terakhir akibat bencana berdasarkan jenis kerusakan Taksiran Jumlah Nominal Nominal Rp kerugian kerugian yang terakhir terakhir (Juta) dialami ketika terjadi bencana 7 Data kerusakan dan kerugian pelayanan dasar.');
