INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1363, 'juknis-7-2023', 26, 'lampiran', 'LAMPIRAN II', NULL, 27, 'PETUNJUK PELAKSANAAN STANDAR DATA KEJADIAN DAN DAMPAK BENCANA NOMOR TAHUN 2023 DEFINISI DAN STANDAR DATA KEJADIAN DAN DAMPAK BENCANA A. KONSEP DAN DEFINISI KEJADIAN DAN DAMPAK BENCANA NO KONSEP DEFINISI 1 Bencana Peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non-alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2 Bencana alam Bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang disebabkan oleh alam antara lain berupa gempabumi, tsunami, gunung meletus, banjir, kekeringan, angin topan, dan tanah longsor.
3 Bencana non alam Bencana yang diakibatkan oleh peristiwa atau rangkaian peristiwa nonalam yang antara lain berupa gagal teknologi, gagal modernisasi, epidemi, dan wabah penyakit.
4 Bencana sosial Bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang diakibatkan oleh manusia yang meliputi konflik sosial antarkelompok atau antarkomunitas masyarakat, dan teror.
5 Wilayah Provinsi Wilayah administratif yang menjadi wilayah kerja bagi gubernur sebagai wakil Pemerintah Pusat dan wilayah kerja bagi gubernur dalam menyelenggarakan urusan pemerintahan umum di wilayah Daerah provinsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1363, 'PETUNJUK PELAKSANAAN STANDAR DATA KEJADIAN DAN DAMPAK BENCANA NOMOR TAHUN 2023 DEFINISI DAN STANDAR DATA KEJADIAN DAN DAMPAK BENCANA A. KONSEP DAN DEFINISI KEJADIAN DAN DAMPAK BENCANA NO KONSEP DEFINISI 1 Bencana Peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non-alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2 Bencana alam Bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang disebabkan oleh alam antara lain berupa gempabumi, tsunami, gunung meletus, banjir, kekeringan, angin topan, dan tanah longsor.
3 Bencana non alam Bencana yang diakibatkan oleh peristiwa atau rangkaian peristiwa nonalam yang antara lain berupa gagal teknologi, gagal modernisasi, epidemi, dan wabah penyakit.
4 Bencana sosial Bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang diakibatkan oleh manusia yang meliputi konflik sosial antarkelompok atau antarkomunitas masyarakat, dan teror.
5 Wilayah Provinsi Wilayah administratif yang menjadi wilayah kerja bagi gubernur sebagai wakil Pemerintah Pusat dan wilayah kerja bagi gubernur dalam menyelenggarakan urusan pemerintahan umum di wilayah Daerah provinsi.', 'LAMPIRAN II', 'Petunjuk Pelaksanaan Nomor 7 Tahun 2023 tentang Standar Data Kejadian dan Dampak Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1364, 'juknis-7-2023', 27, 'lampiran', 'LAMPIRAN II (lanjutan 1)', NULL, 27, '6 Wilayah Kabupaten/kota Wilayah Administratif yang menjadi wilayah kerja bagi bupati/walikota dalam NO KONSEP DEFINISI menyelenggarakan urusan pemerintahan umum di wilayah Daerah kabupaten/kota 7 Tarikh Tanggal yang memuat informasi hari, bulan, dan tahun (ddmmyyyy).
8 Korban Meninggal Orang yang dilaporkan tewas atau meninggal dunia akibat bencana.
9 Korban Hilang Orang yang dilaporkan hilang atau tidak ditemukan atau tidak diketahui keberadaannya setelah terjadi bencana.
10 Korban Luka/Sakit Orang yang mengalami luka-luka atau sakit, dalam keadaan luka ringan, maupun luka parah/berat, baik yang berobat jalan maupun rawat inap.
11 Terdampak/Penderita Orang atau sekelompok orang yang menderita akibat dampak buruk bencana, seperti kerusakan dan atau kerugian harta benda, namun masih dapat menempati tempat tinggalnya.
12 Pengungsi Orang atau kelompok orang yang terpaksa atau dipaksa keluar dari tempat tinggalnya untuk jangka waktu yang belum pasti sebagai akibat dampak buruk bencana.
13 Rumah Bangunan yang dihuni sebagai tempat tinggal 14 Kerusakan bangunan Tidak berfungsinya bangunan atau komponen bangunan akibat penyusutan/berakhirnya umur bangunan, atau akibat ulah manusia atau perilaku alam seperti beban fungsi yang berlebih, kebakaran, gempa bumi, atau sebab lain yang sejenis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1364, '6 Wilayah Kabupaten/kota Wilayah Administratif yang menjadi wilayah kerja bagi bupati/walikota dalam NO KONSEP DEFINISI menyelenggarakan urusan pemerintahan umum di wilayah Daerah kabupaten/kota 7 Tarikh Tanggal yang memuat informasi hari, bulan, dan tahun (ddmmyyyy).
8 Korban Meninggal Orang yang dilaporkan tewas atau meninggal dunia akibat bencana.
9 Korban Hilang Orang yang dilaporkan hilang atau tidak ditemukan atau tidak diketahui keberadaannya setelah terjadi bencana.
