INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1366, 'juknis-7-2023', 29, 'lampiran', 'LAMPIRAN II (lanjutan 3)', NULL, 29, '22 Lahan Bagian daratan dari permukaan bumi sebagai suatu lingkungan baik yang meliputi tanah beserta segenap faktor yang mempengaruhi penggunaannya seperti iklim relief, aspek geologi, dan hidrologi yang terbentuk secara alami maupun akibat pengaruh manusia.
23 Kebun Sebidang lahan, biasanya di tempat terbuka, yang mendapat perlakuan tertentu oleh manusia, khususnya sebagai tempat tumbuh tanaman NO KONSEP DEFINISI 24 Hutan Suatu kesatuan ekosistem berupa hamparan lahan berisi sumber daya alam hayati yang didominasi pepohonan dalam persekutuan alam lingkungannya, yang satu dengan lainnya tidak dapat dipisahkan.
25 Kolam Tempat melakukan kegiatan pembudidayaan perikanan.
26 Pabrik Suatu bangunan industri besar di mana para pekerja mengolah benda atau mengawasi pemrosesan mesin dari satu produk menjadi produk lain, sehingga mendapatkan nilai tambah 27 Kios/Toko Tempat berjualan yang diizinkan dan terpisah antara satu tempat dengan yang lain mulai dari lantai, dinding, plafond dan atap yang sifatnya tetap atau permanen sebagai tempat berjualan barang atau jasa.
28 Pasar Area tempat jual beli barang dengan jumlah penjual lebih dari satu baik yang disebut sebagai pusat perbelanjaan, pasar tradisional, pertokoan, mall, plasa, pusat perdagangan maupun sebutan lainnya.
29 Banjir Peristiwa atau keadaan dimana terendamnya suatu daerah atau daratan karena volume air yang meningkat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1366, '22 Lahan Bagian daratan dari permukaan bumi sebagai suatu lingkungan baik yang meliputi tanah beserta segenap faktor yang mempengaruhi penggunaannya seperti iklim relief, aspek geologi, dan hidrologi yang terbentuk secara alami maupun akibat pengaruh manusia.
23 Kebun Sebidang lahan, biasanya di tempat terbuka, yang mendapat perlakuan tertentu oleh manusia, khususnya sebagai tempat tumbuh tanaman NO KONSEP DEFINISI 24 Hutan Suatu kesatuan ekosistem berupa hamparan lahan berisi sumber daya alam hayati yang didominasi pepohonan dalam persekutuan alam lingkungannya, yang satu dengan lainnya tidak dapat dipisahkan.
25 Kolam Tempat melakukan kegiatan pembudidayaan perikanan.
26 Pabrik Suatu bangunan industri besar di mana para pekerja mengolah benda atau mengawasi pemrosesan mesin dari satu produk menjadi produk lain, sehingga mendapatkan nilai tambah 27 Kios/Toko Tempat berjualan yang diizinkan dan terpisah antara satu tempat dengan yang lain mulai dari lantai, dinding, plafond dan atap yang sifatnya tetap atau permanen sebagai tempat berjualan barang atau jasa.
