INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1383, 'juknis-7-2023', 46, 'lampiran', 'LAMPIRAN II (lanjutan 20)', NULL, 49, '40 Jumlah Konflik Jumlah kerusuhan sosial atau wilayah - Total kejadian bencana Sosial; huru hara adalah suatu konflik sosial Bencana; gerakan massal yang bersifat merusak tatanan dan tata tertib sosial yang ada, yang dipicu oleh kecemburuan sosial, budaya dan ekonomi yang biasanya dikemas sebagai pertentangan antar suku, agama, ras (SARA) yang mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan KLASIFIKASI NO NAMA DATA KONSEP DEFINISI KLASIFIKASI ISIAN UKURAN SATUAN PENYAJIAN dampak psikologis sesuai dengan ambang batas bencana yang telah ditentukan.
41 Jumlah Epidemi Jumlah Penyakit menular wilayah - Total kejadian bencana yang berjangkit dengan cepat epidemi di daerah yang luas dan menimbulkan banyak korban.
Peningkatan angka penyakit di atas normal yang biasanya terjadi secara tiba-tiba pada populasi suatu di area geografis tertentu dan mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis sesuai dengan ambang batas bencana yang telah ditentukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1383, '40 Jumlah Konflik Jumlah kerusuhan sosial atau wilayah - Total kejadian bencana Sosial; huru hara adalah suatu konflik sosial Bencana; gerakan massal yang bersifat merusak tatanan dan tata tertib sosial yang ada, yang dipicu oleh kecemburuan sosial, budaya dan ekonomi yang biasanya dikemas sebagai pertentangan antar suku, agama, ras (SARA) yang mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan KLASIFIKASI NO NAMA DATA KONSEP DEFINISI KLASIFIKASI ISIAN UKURAN SATUAN PENYAJIAN dampak psikologis sesuai dengan ambang batas bencana yang telah ditentukan.
