INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1386, 'juknis-9-2023', 0, 'judul', 'Judul', NULL, 1, 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1386, 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana', 'Judul', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1387, 'juknis-9-2023', 1, 'lain', 'Isi hal. 1', NULL, 1, '| SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PENGELOLAAN DATA DAN INFORMASI PENGUNGSI TERPILAH PADA KEADAAN DARURAT BENCANA NOMOR 9 TAHUN 2023');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1387, '| SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN PENGELOLAAN DATA DAN INFORMASI PENGUNGSI TERPILAH PADA KEADAAN DARURAT BENCANA NOMOR 9 TAHUN 2023', 'Isi hal. 1', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1388, 'juknis-9-2023', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Untuk melaksanakan ketentuan Pasal 11 ayat (6) Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana, Badan Nasional Penanggulangan Bencana perlu menyusun petunjuk pelaksanaan dalam rangka memperoleh data dan informasi pengungsi terpilah pada keadaan darurat bencana dengan mekanisme pengelolaan data dan informasi pengungsi mulai dari pos lapangan penanganan darurat bencana dan pos komando penanganan darurat bencana. Selain itu agar pengelolaan data dan informasi pengungsi terpilah dapat dilakukan secara efektif dan efisien, maka tentunya diperlukan infrastruktur pendukung, seperti pemanfaatan sistem informasi teknologi atau aplikasi.
Salah satu bentuk penanganan pengungsi pada keadaan darurat bencana adalah Pengelolaan Data dan Informasi, hal tersebut merupakan penjabaran ketentuan Pasal 1 angka 4 Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana menyatakan bahwa penanganan pengungsi pada keadaan darurat bencana adalah mencakup upaya yang meliputi pengelolaan Data dan Informasi, perlindungan dan pemberdayaan, penempatan, pemberian kompensasi dan pengembalian hak pengungsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1388, 'PENDAHULUAN A. Latar Belakang Untuk melaksanakan ketentuan Pasal 11 ayat (6) Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana, Badan Nasional Penanggulangan Bencana perlu menyusun petunjuk pelaksanaan dalam rangka memperoleh data dan informasi pengungsi terpilah pada keadaan darurat bencana dengan mekanisme pengelolaan data dan informasi pengungsi mulai dari pos lapangan penanganan darurat bencana dan pos komando penanganan darurat bencana. Selain itu agar pengelolaan data dan informasi pengungsi terpilah dapat dilakukan secara efektif dan efisien, maka tentunya diperlukan infrastruktur pendukung, seperti pemanfaatan sistem informasi teknologi atau aplikasi.
Salah satu bentuk penanganan pengungsi pada keadaan darurat bencana adalah Pengelolaan Data dan Informasi, hal tersebut merupakan penjabaran ketentuan Pasal 1 angka 4 Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana menyatakan bahwa penanganan pengungsi pada keadaan darurat bencana adalah mencakup upaya yang meliputi pengelolaan Data dan Informasi, perlindungan dan pemberdayaan, penempatan, pemberian kompensasi dan pengembalian hak pengungsi.', 'BAB I', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1389, 'juknis-9-2023', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Dalam pemenuhan kebutuhan Data dan Informasi untuk penanganan pengungsi tersebut tentunya dibutuhkan data pengungsi yang sudah terpilah seperti terpilah menurut kepala keluarga, jenis kelamin, umur, kelompok rentan dan kebutuhan dasar. Dengan tersedianya data dan informasi pengungsi terpilah tentunya sangat membantu di dalam memperhitungkan jumlah target kebutuhan dasar dan kebutuhan lainnya dalam penanganan pengungsi yang harus divenuhi.
Berdasarkan Pasal 48 ayat (3) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, menjelaskan bahwa Pos Komando merupakan institusi yang berwenang memberikan Data dan Informasi tentang penanganan tanggap darurat bencana termasuk dengan Data dan Informasi Pengungsi terpilah.
Mempertimbangkan uraian di atas, perlu dibentuk petunjuk pelaksanaan pengelolaan data dan informasi pengungsi terpilah pada keadaan darurat bencana agar pengelolaan data dan informasi pengungsi terpilah terlaksana dengan baik.
B. Maksud dan Tujuan Maksud petunjuk Pelaksanaan ini adalah sebagai acuan bagi pengelola Data dan Informasi Pengungsi akibat bencana di pos lapangan penanganan darurat bencana dan pos komando penanganan darurat bencana. Tujuan Petunjuk Pelaksanaan ini adalah terwujudnya validitas Data dan Informasi Pengungsi dalam keadaan darurat bencana secara efektif, efisien dan akuntabel sesuai kebutuhan.
C. Ruang Lingkup Ruang lingkup dari petunjuk pelaksanaan ini mencakup:
1. Pelaksanaan pengelolaan Data dan Informasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1389, 'Dalam pemenuhan kebutuhan Data dan Informasi untuk penanganan pengungsi tersebut tentunya dibutuhkan data pengungsi yang sudah terpilah seperti terpilah menurut kepala keluarga, jenis kelamin, umur, kelompok rentan dan kebutuhan dasar. Dengan tersedianya data dan informasi pengungsi terpilah tentunya sangat membantu di dalam memperhitungkan jumlah target kebutuhan dasar dan kebutuhan lainnya dalam penanganan pengungsi yang harus divenuhi.
Berdasarkan Pasal 48 ayat (3) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, menjelaskan bahwa Pos Komando merupakan institusi yang berwenang memberikan Data dan Informasi tentang penanganan tanggap darurat bencana termasuk dengan Data dan Informasi Pengungsi terpilah.
Mempertimbangkan uraian di atas, perlu dibentuk petunjuk pelaksanaan pengelolaan data dan informasi pengungsi terpilah pada keadaan darurat bencana agar pengelolaan data dan informasi pengungsi terpilah terlaksana dengan baik.
B. Maksud dan Tujuan Maksud petunjuk Pelaksanaan ini adalah sebagai acuan bagi pengelola Data dan Informasi Pengungsi akibat bencana di pos lapangan penanganan darurat bencana dan pos komando penanganan darurat bencana. Tujuan Petunjuk Pelaksanaan ini adalah terwujudnya validitas Data dan Informasi Pengungsi dalam keadaan darurat bencana secara efektif, efisien dan akuntabel sesuai kebutuhan.
C. Ruang Lingkup Ruang lingkup dari petunjuk pelaksanaan ini mencakup:
1. Pelaksanaan pengelolaan Data dan Informasi.', 'BAB I (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1390, 'juknis-9-2023', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, '2. Standar minimal Data dan Informasi pengungsi terpilah.
3. Pemantauan dan evaluasi.
D. Pengertian
a. Data adalah catatan atas kumpulan fakta atau deskripsi berupa angka, karakter, simbol, gambar, peta, tanda, isyarat, tulisan, suara dan/atau bunyi yang merepresentasikan keadaan sebenarnya atau menunjukkan suatu ide, objek, kondisi, atau situasi.
b. Pengungsi adalah orang atau kelompok orang yang terpaksa atau dipaksa keluar dari tempat tinggalnya untuk jangka waktu yang belum pasti sebagai akibat dampak buruk bencana.
c. Data dan Informasi Pengungsi Terpilah adalah gambaran Data dan Informasi Pengungsi yang dipilah berdasarkan jenis kelamin, kelompok umur, dan kebutuhan perlindungan Pengungsi.
d. Pengelolaan Data dan Informasi Pengungsi Terpilah adalah kegiatan yang meliputi pengumpulan, pengolahan, analisis, penyajian, diseminasi, serta pelaporan Data dan Informasi Pengungsi terpilah.
e. Tempat Pengungsian adalah tempat tinggal sementara selama korban bencana mengungsi, baik berupa tempat penampungan massal maupun keluarga, atau individual sesuai standar pelayanan minimum dan dilengkapi dengan utilitas dasar yang dibutuhkan.
f. Pos Komando Penanganan Darurat Bencana yang selanjutnya disingkat Posko PDB adalah institusi yang berfungsi sebagai pusat komando operasi penanganan darurat bencana yang merupakan posko utama di dalam Sistem Komando Penanganan Darurat Bencana, untuk mengoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan penanganan darurat bencana.');
