INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1391, 'juknis-9-2023', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 3, 'g. Pos Lapangan Penanganan Darurat Bencana yang selanjutnya disingkat Pos Lapangan PDB adalah Institusi yang berfungsi secara langsung sebagai pelaksana operasi penanganan darurat bencana baik di lokasi bencana, sekitar lokasi bencana, maupun lokasi Pengungsian.
h. Kelompok Rentan adalah bayi, anak usia di bawah lima tahun, anak-anak, ibu hamil atau menyusui, penyandang disabilitas, dan orang lanjut usia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1391, 'g. Pos Lapangan Penanganan Darurat Bencana yang selanjutnya disingkat Pos Lapangan PDB adalah Institusi yang berfungsi secara langsung sebagai pelaksana operasi penanganan darurat bencana baik di lokasi bencana, sekitar lokasi bencana, maupun lokasi Pengungsian.
h. Kelompok Rentan adalah bayi, anak usia di bawah lima tahun, anak-anak, ibu hamil atau menyusui, penyandang disabilitas, dan orang lanjut usia.', 'BAB I (lanjutan 3)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1392, 'juknis-9-2023', 6, 'lain', 'BAB II', NULL, 4, 'PELAKSANAAN PENGELOLAAN DATA DAN INFORMASI A. Pengorganisasian
1. Pelaksana Pelaksana kegiatan Pengelolaan Data dan Informasi Pengungsi Terpilah dilakukan oleh Pos Lapangan PDB yang berada dibawah Pos Komando PDB.
Pada saat keadaan darurat bencana, pengorganisasian pelaksanaan Pengelolaan Data dan Informasi Pengungsi Terpilah mengacu kepada Sistem Komando Penanganan Darurat Bencana dengan dimulai pada tingkat Pos Lapangan PDB dan Posko PDB.
1) Pengorganisasian di Pos Lapangan PDB Struktur pengorganisasian Pos Lapangan PDB dipimpin oleh Seorang Koordinator Pos Lapangan PDB. Dalam menjalankan tugasnya Koordinator Pos Lapangan PDB membawahi Sekretariat Pos Lapangan PDB. Selanjutnya Pengelolaan Data dan Informasi Pengungsi terpilah dilaksanakan oleh subbagian pengelolaan data, informasi dan komunikasi yang berada di bawah Sekretariat Pos Lapangan PDB.
Tugas dan fungsi koordinator Pos Lapangan PDB, sekretariat, kepala subbagian pengelolaan data, informasi, dan komunikasi, para petugas di Pos Lapangan PDB adalah sebagai berikut:
a. Koordinator Pos Lapangan PDB:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1392, 'PELAKSANAAN PENGELOLAAN DATA DAN INFORMASI A. Pengorganisasian
1. Pelaksana Pelaksana kegiatan Pengelolaan Data dan Informasi Pengungsi Terpilah dilakukan oleh Pos Lapangan PDB yang berada dibawah Pos Komando PDB.
Pada saat keadaan darurat bencana, pengorganisasian pelaksanaan Pengelolaan Data dan Informasi Pengungsi Terpilah mengacu kepada Sistem Komando Penanganan Darurat Bencana dengan dimulai pada tingkat Pos Lapangan PDB dan Posko PDB.
1) Pengorganisasian di Pos Lapangan PDB Struktur pengorganisasian Pos Lapangan PDB dipimpin oleh Seorang Koordinator Pos Lapangan PDB. Dalam menjalankan tugasnya Koordinator Pos Lapangan PDB membawahi Sekretariat Pos Lapangan PDB. Selanjutnya Pengelolaan Data dan Informasi Pengungsi terpilah dilaksanakan oleh subbagian pengelolaan data, informasi dan komunikasi yang berada di bawah Sekretariat Pos Lapangan PDB.
Tugas dan fungsi koordinator Pos Lapangan PDB, sekretariat, kepala subbagian pengelolaan data, informasi, dan komunikasi, para petugas di Pos Lapangan PDB adalah sebagai berikut:
a. Koordinator Pos Lapangan PDB:', 'BAB II', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1393, 'juknis-9-2023', 7, 'lain', 'BAB II (lanjutan 1)', NULL, 4, 'Koordinator Pos Lapangan PDB bertanggung jawab melaksanakan operasi penanganan darurat di tingkat lapangan, termasuk pengelolaan Tempat Pengungsian yang terdiri dari perencanaan lokasi Pengungsian, perencanaan sarana dan prasarana Pengungsian, perencanaan hunian Pengungsian, pemeliharaan Tempat Pengungsian , dan penutupan Tempat Pengungsian . Salah satu tugas Koordinator Pos Lapangan PDB adalah melaksanakan manajemen Data dan Informasi Pengungsi terpilah, yang selanjutnya hasil Data dan Informasi dilaporkan kepada Posko PDB sesuai dengan (Format 1).
b. Sekretariat Sekretariat berada di bawah Koordinator Pos Lapangan PDB.
Dalam struktur organisasi, Sekretariat dipimpin oleh seorang Sekretaris. Tugas dari Sekretariat antara lain adalah bertanggung jawab dalam kegiatan penyelenggaraan pengelolaan data, informasi dan komunikasi termasuk pendataan Pengungsi terpilah.
c. Kepala Subbagian Pengelolaan Data, Informasi dan Komunikasi Subbagian Pengelolaan Data, Informasi dan Komunikasi ditunjuk oleh Koordinator Pos Lapangan PDB dan berada dibawah Sekretariat Pos Lapangan PDB.
Penunjukan Kepala Subbagian Pengelolaan Data, Informasi dan Komunikasi, Koordinator Pos Lapangan PDB mempertimbangkan kriteria sebagai berikut:
1) Memiliki kompetensi dalam proses pengelolaan data.
2) Berasal dari unsur perangkat/petugas di tingkat desa/kampung/rt/rw, satuan perlindungan masyarakat atau relawan PB.
3) Memiliki pengalaman dalam pengelolaan data di lokasi Pengungsian.
4) Mampu bekerja dalam tim.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1393, 'Koordinator Pos Lapangan PDB bertanggung jawab melaksanakan operasi penanganan darurat di tingkat lapangan, termasuk pengelolaan Tempat Pengungsian yang terdiri dari perencanaan lokasi Pengungsian, perencanaan sarana dan prasarana Pengungsian, perencanaan hunian Pengungsian, pemeliharaan Tempat Pengungsian , dan penutupan Tempat Pengungsian . Salah satu tugas Koordinator Pos Lapangan PDB adalah melaksanakan manajemen Data dan Informasi Pengungsi terpilah, yang selanjutnya hasil Data dan Informasi dilaporkan kepada Posko PDB sesuai dengan (Format 1).
b. Sekretariat Sekretariat berada di bawah Koordinator Pos Lapangan PDB.
Dalam struktur organisasi, Sekretariat dipimpin oleh seorang Sekretaris. Tugas dari Sekretariat antara lain adalah bertanggung jawab dalam kegiatan penyelenggaraan pengelolaan data, informasi dan komunikasi termasuk pendataan Pengungsi terpilah.
c. Kepala Subbagian Pengelolaan Data, Informasi dan Komunikasi Subbagian Pengelolaan Data, Informasi dan Komunikasi ditunjuk oleh Koordinator Pos Lapangan PDB dan berada dibawah Sekretariat Pos Lapangan PDB.
Penunjukan Kepala Subbagian Pengelolaan Data, Informasi dan Komunikasi, Koordinator Pos Lapangan PDB mempertimbangkan kriteria sebagai berikut:
1) Memiliki kompetensi dalam proses pengelolaan data.
2) Berasal dari unsur perangkat/petugas di tingkat desa/kampung/rt/rw, satuan perlindungan masyarakat atau relawan PB.
3) Memiliki pengalaman dalam pengelolaan data di lokasi Pengungsian.
4) Mampu bekerja dalam tim.', 'BAB II (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1394, 'juknis-9-2023', 8, 'lain', 'BAB II (lanjutan 2)', NULL, 5, '5) Mampu bekerja selama 24 jam dalam penyelenggaraan dan pengelolaan lokasi Pengungsian.
6) Dapat mengoperasionalkan komputer.
Tugas Kepala Subbagian Pengelolaan Data, Informasi dan Komunikasi adalah:
1) Menyiapkan bahan analisis data pelaksanaan operasional lapangan;
2) Melaksanakan pengumpulan bahan analisis data pelaksanaan operasional lapangan;
3) Melaksanakan pengolahan analisis data pelaksanaan operasional lapangan;
4) Menganalisis data pelaksanaan operasional lapangan;
5) menyusun penyajian informasi pelaksanaan operasional lapangan terkini secara berkala;
6) Menyiapkan dan membangun jejaring komunikasi internal Pos Lapangan dan Tim yang bertugas di lapangan;
7) Mengkomunikasikan Data dan Informasi pelaksanaan operasional lapangan;
8) Menyiapkan notulensi rapat-rapat rutin dan tertentu; dan 9) Menyiapkan bahan laporan pelaksanaan operasional lapangan untuk di laporkan ke Posko PDB.
Fungsi Subbagian Pengelolaan Data, Informasi dan Komunikasi adalah:
1) Memastikan kesiapan sumber daya manusia dan infrastruktur pengelolaan Data dan Informasi di lapangan; dan 2) Memastikan pelaporan pelaksanaan operasi di lapangan termasuk data Pengungsi terpilah menjadi acuan dalam pengelolaan data di pos lapangan PDB.
d. Petugas Pengumpul Data Petugas Pengumpul Data ditunjuk oleh Kepala Subbagian Pengelolaan Data, Informasi dan Komunikasi dengan mempertimbangkan beberapa kriteria sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1394, '5) Mampu bekerja selama 24 jam dalam penyelenggaraan dan pengelolaan lokasi Pengungsian.
6) Dapat mengoperasionalkan komputer.
Tugas Kepala Subbagian Pengelolaan Data, Informasi dan Komunikasi adalah:
1) Menyiapkan bahan analisis data pelaksanaan operasional lapangan;
2) Melaksanakan pengumpulan bahan analisis data pelaksanaan operasional lapangan;
3) Melaksanakan pengolahan analisis data pelaksanaan operasional lapangan;
4) Menganalisis data pelaksanaan operasional lapangan;
5) menyusun penyajian informasi pelaksanaan operasional lapangan terkini secara berkala;
6) Menyiapkan dan membangun jejaring komunikasi internal Pos Lapangan dan Tim yang bertugas di lapangan;
7) Mengkomunikasikan Data dan Informasi pelaksanaan operasional lapangan;
8) Menyiapkan notulensi rapat-rapat rutin dan tertentu; dan 9) Menyiapkan bahan laporan pelaksanaan operasional lapangan untuk di laporkan ke Posko PDB.
Fungsi Subbagian Pengelolaan Data, Informasi dan Komunikasi adalah:
1) Memastikan kesiapan sumber daya manusia dan infrastruktur pengelolaan Data dan Informasi di lapangan; dan 2) Memastikan pelaporan pelaksanaan operasi di lapangan termasuk data Pengungsi terpilah menjadi acuan dalam pengelolaan data di pos lapangan PDB.
d. Petugas Pengumpul Data Petugas Pengumpul Data ditunjuk oleh Kepala Subbagian Pengelolaan Data, Informasi dan Komunikasi dengan mempertimbangkan beberapa kriteria sebagai berikut:', 'BAB II (lanjutan 2)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1395, 'juknis-9-2023', 9, 'lain', 'BAB II (lanjutan 3)', NULL, 5, '1) Memiliki kompetensi melakukan pengumpulan data Pengungsi terpilah sesuai dengan standar data Pengungsi terpilah.
2) Berasal dari unsur perangkat di tingkat desa/kampung/rt/rw/satuan perlindungan masyarakat atau relawan PB.
3) Mampu bekerja dalam tim.
4) mampu bekerja selama 24 jam pada saat proses pendataan Pengungsi harus dilakukan.
5) Dapat mengoperasionalkan komputer.
Tugas Pengumpul Data adalah:
1) Melaksanakan kegiatan pengumpulan data Pengungsi terpilah dilakukan sejak Pos Lapangan PDB terbentuk (Format 2);
2) Melakukan pemutakhiran data secara berkala; dan 3) Melaporkan pelaksanaan kegiatan pengumpulan data kepada Kepala Subbagian Pengelolaan Data, Informasi dan Komunikasi secara berkala.
e. Petugas Pengolahan Data Petugas Pengolahan Data ditunjuk oleh Kepala Subbagian Pengelolaan Data, Informasi dan Komunikasi dengan mempertimbangkan beberapa kriteria sebagai berikut:
1) Memiliki kompetensi melakukan pengolahan data Pengungsi terpilah sesuai dengan standar data Pengungsi terpilah.
2) Berasal dari unsur perangkat/petugas di tingkat desa/kampung/rt/rw/satuan perlindungan masyarakat atau relawan PB.
3) Mampu bekerja dalam tim.
4) Mampu bekerja selama 24 jam pada saat proses pendataan Pengungsi harus dilakukan.
5) Dapat mengoperasionalkan komputer.
Tugas Petugas Pengolahan Data adalah:
1) Melaksanakan kegiatan verifikasi data Pengungsi terpilah berdasarkan hasil petugas pengumpul data secara berkala.
2) Melakukan pengolahan data secara manual (Format 3).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1395, '1) Memiliki kompetensi melakukan pengumpulan data Pengungsi terpilah sesuai dengan standar data Pengungsi terpilah.
