INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1427, 'b. Pangan 1 Pemenuhan bantuan bahan Cukup/Tidak Cukup pangan sesuai dengan standar kebutuhan gizi (dalam 7 hari ke depan) 2 Ketersediaan dapur umum Jumlah : ………………………….. lapangan 3 Ketersediaan dapur umum Jumlah : ………………………….. lapangan yang menyelenggarakan Pemberian Makanan Bayi dan Anak (PMBA) 4 Ketersediaan dapur umum Jumlah : ………………………….. lapangan yang menyelenggarakan pemberian makanan untuk penderita penyakit bawaan 5 Ketersediaan layanan Jumlah : ………………………….. pemberian makanan tambahan bagi ibu hamil dan ibu menyusui 6 Ketersediaan dapur umum Jumlah : ………………………….. lapangan yang diawasi oleh tenaga gizi', 'LAMPIRAN (lanjutan 5)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1428, 'juknis-9-2023', 42, 'lampiran', 'LAMPIRAN (lanjutan 6)', NULL, 32, 'c. Sandang/Non Pangan 1 Pemenuhan perlengkapan Ada Tidak Distribusi Bantuan tersebut (Ada/Tidak) pribadi dan kebersihan pribadi seperti pakaian, Kebutuhan yang belum terpenuhi : ………… alas kaki, seragam sekolah, Pakaian Perempuan Dewasa : ………. perlengkapan ibadah, Pakaian Laki-Laki Dewasa :……… selimut, alas tidur Pakaian Perempuan (Anak-Anak) :…………… Pakaian Laki-Laki (Anak-Anak) : ………… Alas Kaki : ……………… Seragam Sekolah: ………………… Perlengkapan Ibadah : ………………… Selimut : ………………… Alas Tidur : ………………… 2 Pemenuhan paket Ada Tidak Distribusi Bantuan tersebut (Ada/Tidak) kebutuhan bayi dan balita Jika ada, apakah mencukupi (Cukup/Tidak Cukup) 3 Pemenuhan paket Ada Tidak Distribusi Bantuan tersebut (Ada/Tidak) kebutuhan bagi lansia Jika ada, apakah mencukupi (Cukup/Tidak Cukup) 4 Pemenuhan Kebutuhan Ada Tidak Distribusi Bantuan tersebut (Ada/Tidak) Pembalut Wanita Jika ada, apakah mencukupi (Cukup/Tidak Cukup)
