INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1430, 'juknis-9-2023', 44, 'lampiran', 'LAMPIRAN (lanjutan 8)', NULL, 33, '3. e. Penampungan dan Tempat Hunian Sementara 1 Tipe Tempat Pengungsian Fasilitas Umum/Tanah Lapang/Lahan/Gedung Swasta/Tempat Ibadah/Rumah milik Perorangan 2 Ketersediaan akses dan Tersedia/Tidak jangkauan listrik 3 Ketersediaan Layanan Tersedia/Tidak Pengamanan di tempat Pengungsian 4 Ketersediaan layanan Tersedia/Tidak Pengaduan
f. Penyediaan Layanan Pendidikan Darurat 1 Jumlah anak usia sekolah PAUD : …………..
(PAUD, SD, SMP, SMA) SD : ……………… SMP : …………… SMA : …………….
2 Ketersediaan layanan Tersedia/Tidak pendidikan darurat Petunjuk pengisian formulir pendataan Pengungsi terpilah
1. Diisi dengan nama petugas pengumpul data.
2. Diisi dengan nomor telepon/handphone petugas pengumpul data yang bisa dihubungi.
3. Diisi dengan hari dan tanggal pengumpulan data.
4. Diisi dengan lokasi pos lapangan.
5. Diisi dengan nama tempat Pengungsian.
6. Diisi dengan nama Provinsi tempat Pengungsian
7. Diisi dengan nama Kabupaten/Kota tempat Pengungsian.
8. Diisi dengan nama Kecamatan tempat Pengungsian.
9. Diisi dengan nama Desa/Kelurahan tempat Pengungsian.
10. Diisi dengan pelaksanaan pengumpulan data ke berapa.
11. Diisi dengan jenis bencana.
12. Diisi dengan lokasi koordinat GPS.
13. Diisi dengan kota terdekat yang bisa dijangkau dari pos Pengungsian.
14. Diisi dengan hari, tanggal buka tempat Pengungsian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1430, '3. e. Penampungan dan Tempat Hunian Sementara 1 Tipe Tempat Pengungsian Fasilitas Umum/Tanah Lapang/Lahan/Gedung Swasta/Tempat Ibadah/Rumah milik Perorangan 2 Ketersediaan akses dan Tersedia/Tidak jangkauan listrik 3 Ketersediaan Layanan Tersedia/Tidak Pengamanan di tempat Pengungsian 4 Ketersediaan layanan Tersedia/Tidak Pengaduan
f. Penyediaan Layanan Pendidikan Darurat 1 Jumlah anak usia sekolah PAUD : …………..
(PAUD, SD, SMP, SMA) SD : ……………… SMP : …………… SMA : …………….
2 Ketersediaan layanan Tersedia/Tidak pendidikan darurat Petunjuk pengisian formulir pendataan Pengungsi terpilah
1. Diisi dengan nama petugas pengumpul data.
2. Diisi dengan nomor telepon/handphone petugas pengumpul data yang bisa dihubungi.
3. Diisi dengan hari dan tanggal pengumpulan data.
4. Diisi dengan lokasi pos lapangan.
5. Diisi dengan nama tempat Pengungsian.
6. Diisi dengan nama Provinsi tempat Pengungsian
7. Diisi dengan nama Kabupaten/Kota tempat Pengungsian.
8. Diisi dengan nama Kecamatan tempat Pengungsian.
9. Diisi dengan nama Desa/Kelurahan tempat Pengungsian.
10. Diisi dengan pelaksanaan pengumpulan data ke berapa.
