INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1434, 'juknis-9-2023', 48, 'lampiran', 'LAMPIRAN (lanjutan 12)', NULL, 36, '- Jumlah ambulan Apabila tidak tersedia, maka dikosongkan.
4. Mencoret salah satu pilihan pada isian ketersediaan pelayanan kesehatan Ibu dan Anak (KIA).
5. Mencoret salah satu pilihan pada isian ketersediaan obat-obatan esensial.
6. Obat esensial adalah obat yang paling dibutuhkan dalam pelayanan kesehatan, termasuk obat generik, obat generik bermerek, dan obat originator (UU 17 tahun 2003)
7. Mencoret salah satu pilihan pada isian ketersediaan pelayanan kesehatan dan gizi bagi bagi orang dengan penyakit bawaan yang memerlukan penanganan khusus (Jantung, Stroke, Diabetes, Paru-Paru).
8. Mencoret salah satu pilihan pada isian ketersediaan pelayanan kesehatan reproduksi termasuk pelayanan korban kekerasan seksual.
9. Mencoret salah satu pilihan pada isian ketersediaan sarana rekreasi (bagi Pengungsi berdurasi lama).
10. Mencoret salah satu pilihan pada isian ketersediaan layanan dukungan psikososial dan kesehatan jiwa berupa pendampingan dan mekanisme rujukan.
11. Mencoret salah satu pilihan pada isian ketersediaan ruang ramah ibu dan anak.
12. Mencoret salah satu pilihan pada isian ketersediaan ruang laktasi.
13. Mencoret salah satu pilihan pada isian ketersediaan layanan pemberian suplemen gizi.
14. Mencoret salah satu pilihan pada isian ketersediaan layanan kesehatan dan alat bantu bagi lansia.
