INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1435, 'juknis-9-2023', 49, 'lampiran', 'LAMPIRAN (lanjutan 13)', NULL, 36, '16. Mencoret salah satu pilihan pada isian ketersediaan kegiatan pengendalian vektor penyakit potensial wabah.
