INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1443, 'juknis-9-2023', 57, 'lain', 'II. Jumlah Data Perlindungan dan Prioritas Kelompok Rentan (lanjutan 6)', NULL, 46, 'd. SMA 2 Ketersediaan layanan Tersedia: Tersedia: Tersedia: pendidikan darurat Tidak tersedia: Tidak tersedia: Tidak (jumlah tempat tersedia:
