INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1443, 'd. SMA 2 Ketersediaan layanan Tersedia: Tersedia: Tersedia: pendidikan darurat Tidak tersedia: Tidak tersedia: Tidak (jumlah tempat tersedia:
Pengungsian) Petunjuk Pengisian formulir Data Pengungsi Terpilah Data yang sudah dikumpulkan oleh petugas pengumpul data kemudian dipilah oleh petugas pengolah data sesuai dengan jenis Pengungsian (terkonsentrasi/tidak terkonsentrasi), selanjutnya petugas pengolah data Pengugsi terpilah melaksanakan rekapitulasi sesuai dengan format berikut ini:', 'II. Jumlah Data Perlindungan dan Prioritas Kelompok Rentan (lanjutan 6)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1444, 'juknis-9-2023', 58, 'lain', 'I. Jumlah data terpilah jenis kelamin dan kelompok umur di tempat', NULL, 46, 'pengungsian diisi dengan:
1. Jumlah kepala keluarga di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data keseluruhan jumlah total kepala keluarga.
2. Jumlah total Pengungsi di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total Pengungsi.
3. Jumlah Pengungsi laki-laki di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total Pengungsi laki-laki.
4. Jumlah Pengungsi perempuan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total Pengungsi perempuan.
5. Jumlah bayi perempuan dan laki-laki (0-11 bulan) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total bayi perempuan dan laki-laki.
6. Jumlah balita perempuan dan laki-laki (12-59 bulan) di tempat pengungsian terkonsentrasi dan tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total balita perempuan dan laki-laki.
7. Jumlah anak-anak perempuan dan laki-laki (5-12 tahun) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total anak-anak perempuan dan laki-laki.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1444, 'pengungsian diisi dengan:
1. Jumlah kepala keluarga di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data keseluruhan jumlah total kepala keluarga.
2. Jumlah total Pengungsi di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total Pengungsi.
3. Jumlah Pengungsi laki-laki di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total Pengungsi laki-laki.
4. Jumlah Pengungsi perempuan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total Pengungsi perempuan.
5. Jumlah bayi perempuan dan laki-laki (0-11 bulan) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total bayi perempuan dan laki-laki.
6. Jumlah balita perempuan dan laki-laki (12-59 bulan) di tempat pengungsian terkonsentrasi dan tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total balita perempuan dan laki-laki.
7. Jumlah anak-anak perempuan dan laki-laki (5-12 tahun) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total anak-anak perempuan dan laki-laki.', 'I. Jumlah data terpilah jenis kelamin dan kelompok umur di tempat', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1445, 'juknis-9-2023', 59, 'lain', 'I. Jumlah data terpilah jenis kelamin dan kelompok umur di tempat (lanjutan 1)', NULL, 47, '8. Jumlah remaja perempuan dan laki-laki (13-17 Tahun) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total remaja perempuan dan laki-laki.
9. Jumlah dewasa perempuan dan laki-laki (18-59 tahun) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total dewasa perempuan dan laki-laki.
10. Jumlah lansia perempuan dan laki-laki (+60 tahun) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total lansia perempuan dan laki-laki.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1445, '8. Jumlah remaja perempuan dan laki-laki (13-17 Tahun) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total remaja perempuan dan laki-laki.
9. Jumlah dewasa perempuan dan laki-laki (18-59 tahun) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total dewasa perempuan dan laki-laki.
10. Jumlah lansia perempuan dan laki-laki (+60 tahun) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total lansia perempuan dan laki-laki.', 'I. Jumlah data terpilah jenis kelamin dan kelompok umur di tempat (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1446, 'juknis-9-2023', 60, 'lain', 'II. Jumlah Data Perlindungan dan Prioritas Kelompok Rentan diisi', NULL, 47, 'dengan:
1. Jumlah bayi yatim piatu dan terpisah dari orangtua/wali (0-11 bulan) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total bayi yatim piatu dan terpisah dari orangtua/wali.
2. Jumlah balita yatim piatu dan terpisah dari orangtua/wali (12- 59 bulan) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total balita yatim piatu dan terpisah dari orangtua/wali.
3. Jumlah anak-anak yatim piatu dan terpisah dari orangtua/wali (5-12 tahun) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total anak-anak yatim piatu dan terpisah dari orangtua/wali.
4. Jumlah ibu hamil di tempat pengungsian terkonsentrasi dan di Tempat Pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total Pengungsi ibu hamil.
5. Jumlah ibu menyusui di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ibu menyusui.
6. Jumlah Pengungsi penyandang disabilitas di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total sesuai dengan jenis disabilitas. Kebutuhan alat bantu ditulis di kolom keterangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1446, 'dengan:
1. Jumlah bayi yatim piatu dan terpisah dari orangtua/wali (0-11 bulan) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total bayi yatim piatu dan terpisah dari orangtua/wali.
2. Jumlah balita yatim piatu dan terpisah dari orangtua/wali (12- 59 bulan) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total balita yatim piatu dan terpisah dari orangtua/wali.
3. Jumlah anak-anak yatim piatu dan terpisah dari orangtua/wali (5-12 tahun) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total anak-anak yatim piatu dan terpisah dari orangtua/wali.
4. Jumlah ibu hamil di tempat pengungsian terkonsentrasi dan di Tempat Pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total Pengungsi ibu hamil.
5. Jumlah ibu menyusui di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ibu menyusui.
6. Jumlah Pengungsi penyandang disabilitas di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total sesuai dengan jenis disabilitas. Kebutuhan alat bantu ditulis di kolom keterangan.', 'II. Jumlah Data Perlindungan dan Prioritas Kelompok Rentan diisi', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1447, 'juknis-9-2023', 61, 'lain', 'II. Jumlah Data Perlindungan dan Prioritas Kelompok Rentan diisi (lanjutan 1)', NULL, 47, '7. Jumlah anak-anak yang menjadi kepala keluarga di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total anak-anak yang menjadi kepala keluarga.
8. Jumlah perempuan yang menjadi kepala keluarga di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total perempuan yang menjadi kepala keluarga
9. Jumlah perempuan yang menikah di usia dini (kurang dari 19 tahun) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total perempuan yang menikah di usia dini (kurang dari 19 tahun).
10. Jumlah orang dengan penyakit kronis/gangguan kesehatan di Tempat Pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total orang dengan penyakit kronis/gangguan kesehatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1447, '7. Jumlah anak-anak yang menjadi kepala keluarga di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total anak-anak yang menjadi kepala keluarga.
8. Jumlah perempuan yang menjadi kepala keluarga di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total perempuan yang menjadi kepala keluarga
9. Jumlah perempuan yang menikah di usia dini (kurang dari 19 tahun) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total perempuan yang menikah di usia dini (kurang dari 19 tahun).
10. Jumlah orang dengan penyakit kronis/gangguan kesehatan di Tempat Pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total orang dengan penyakit kronis/gangguan kesehatan.', 'II. Jumlah Data Perlindungan dan Prioritas Kelompok Rentan diisi (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1448, 'juknis-9-2023', 62, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi', NULL, 48, 'a. Air Bersih dan Sanitasi diisi dengan:
1. Jumlah kecukupan air bersih kebutuhan sesuai standar kebutuhan (15 liter/orang/hari) di tempat pengungsian konsentrasi dan tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total kecukupan air bersih kebutuhan sesuai standar kebutuhan.
2. Jumlah ketersediaan toilet/jamban/kakus yang layak digunakan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi serta jumlah kecukupan Pemenuhan toilet/jamban/ kakus yang layak digunakan (sesuai standar kebutuhan 20 orang/jamban) di tempat Pengungsian konsentrasi dan tidak terkonsentrasi.
3. Jumlah ketersediaan toilet/jamban/kakus yang layak digunakan di tempat Pengungsian terkonsentrasi dan di tempat Pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan toilet/jamban/kakus yang layak digunakan.
4. Jumlah ketersediaan saluran pembuangan air limbah di tempat Pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan saluran pembuangan air limbah.
5. Jumlah ketersediaan tempat sampah buangan keluarga di tempat Pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi serta jumlah kecukupan tempat sampah buangan keluarga (sesuai standar kebutuhan 1 polybag/3 kepala keluarga/3 hari) di tempat pengungsian konsentrasi dan tidak terkonsentrasi
b. Pangan diisi dengan:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1448, 'a. Air Bersih dan Sanitasi diisi dengan:
1. Jumlah kecukupan air bersih kebutuhan sesuai standar kebutuhan (15 liter/orang/hari) di tempat pengungsian konsentrasi dan tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total kecukupan air bersih kebutuhan sesuai standar kebutuhan.
2. Jumlah ketersediaan toilet/jamban/kakus yang layak digunakan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi serta jumlah kecukupan Pemenuhan toilet/jamban/ kakus yang layak digunakan (sesuai standar kebutuhan 20 orang/jamban) di tempat Pengungsian konsentrasi dan tidak terkonsentrasi.
3. Jumlah ketersediaan toilet/jamban/kakus yang layak digunakan di tempat Pengungsian terkonsentrasi dan di tempat Pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan toilet/jamban/kakus yang layak digunakan.
4. Jumlah ketersediaan saluran pembuangan air limbah di tempat Pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan saluran pembuangan air limbah.
5. Jumlah ketersediaan tempat sampah buangan keluarga di tempat Pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi serta jumlah kecukupan tempat sampah buangan keluarga (sesuai standar kebutuhan 1 polybag/3 kepala keluarga/3 hari) di tempat pengungsian konsentrasi dan tidak terkonsentrasi
b. Pangan diisi dengan:', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1449, 'juknis-9-2023', 63, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 1)', NULL, 48, '1. Jumlah tempat pengungsian yang cukup dan tidak cukup dalam pemenuhan bantuan bahan pangan sesuai dengan standar kebutuhan gizi dalam 7 hari kedepan baik di tempat pengungsian terkonsentrasi maupun tidak terkonsentrasi, kemudian dijumlah sebagai data jumlah total pemenuhan bantuan bahan pangan sesuai dengan standar kebutuhan gizi dalam 7 hari ke depan. Jumlah jiwa Pengungsi untuk tempat pengungsian yang belum tercukupi kebutuhan bantuan bahan pangan sesuai dengan standar kebutuhan gizi dalam 7 hari ke depan, baik di tempat pengungsian terkonsentrasi maupun tidak terkonsentrasi, kemudian dijumlah sebagai data jumlah total jiwa Pengungsi yang belum tercukupi kebutuhannya. Standar pemenuhan pangan 2.100 kkal/orang/hari, 40 gr lemak/ orang/hari, 50 gr protein/orang/hari
2. Jumlah ketersediaan dapur umum lapangan di tempat pengungsian terkonsentrasi dan di tempat Pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan dapur umum lapangan.
3. Jumlah ketersediaan dapur umum lapangan yang menyelenggarakan Pemberian Makanan Bayi dan Anak (PMBA) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan dapur umum lapangan yang menyelenggarakan PMBA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1449, '1. Jumlah tempat pengungsian yang cukup dan tidak cukup dalam pemenuhan bantuan bahan pangan sesuai dengan standar kebutuhan gizi dalam 7 hari kedepan baik di tempat pengungsian terkonsentrasi maupun tidak terkonsentrasi, kemudian dijumlah sebagai data jumlah total pemenuhan bantuan bahan pangan sesuai dengan standar kebutuhan gizi dalam 7 hari ke depan. Jumlah jiwa Pengungsi untuk tempat pengungsian yang belum tercukupi kebutuhan bantuan bahan pangan sesuai dengan standar kebutuhan gizi dalam 7 hari ke depan, baik di tempat pengungsian terkonsentrasi maupun tidak terkonsentrasi, kemudian dijumlah sebagai data jumlah total jiwa Pengungsi yang belum tercukupi kebutuhannya. Standar pemenuhan pangan 2.100 kkal/orang/hari, 40 gr lemak/ orang/hari, 50 gr protein/orang/hari
2. Jumlah ketersediaan dapur umum lapangan di tempat pengungsian terkonsentrasi dan di tempat Pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan dapur umum lapangan.
3. Jumlah ketersediaan dapur umum lapangan yang menyelenggarakan Pemberian Makanan Bayi dan Anak (PMBA) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan dapur umum lapangan yang menyelenggarakan PMBA.', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 1)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1450, 'juknis-9-2023', 64, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 2)', NULL, 49, '4. Jumlah Ketersediaan dapur umum lapangan yang menyelenggarakan pemberian makanan untuk penderita penyakit bawaan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan Ketersediaan dapur umum lapangan yang menyelenggarakan pemberian makanan untuk penderita penyakit bawaan.
5. Jumlah ketersediaan layanan pemberian makanan tambahan bagi ibu hamil dan ibu menyusui di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan pemberian makanan tambahan bagi ibu hamil dan ibu menyusui.
6. Jumlah Ketersediaan dapur umum lapangan yang diawasi oleh tenaga gizi di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total Ketersediaan dapur umum lapangan yang diawasi oleh tenaga gizi.
c. Sandang/Non Pangan diisi dengan:
1. Jumlah tempat pengungsian yang Ada/Tidak Ada distribusi bantuan pemenuhan perlengkapan pribadi dan kebersihan pribadi baik di tempat pengungsian terkonsentrasi dan tidak terkonsentrasi, kemudian dijumlah sebagai jumlah total distribusi bantuan pemenuhan perlengkapan pribadi dan kebersihan pribadi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1450, '4. Jumlah Ketersediaan dapur umum lapangan yang menyelenggarakan pemberian makanan untuk penderita penyakit bawaan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan Ketersediaan dapur umum lapangan yang menyelenggarakan pemberian makanan untuk penderita penyakit bawaan.
5. Jumlah ketersediaan layanan pemberian makanan tambahan bagi ibu hamil dan ibu menyusui di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan pemberian makanan tambahan bagi ibu hamil dan ibu menyusui.
6. Jumlah Ketersediaan dapur umum lapangan yang diawasi oleh tenaga gizi di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total Ketersediaan dapur umum lapangan yang diawasi oleh tenaga gizi.
c. Sandang/Non Pangan diisi dengan:
1. Jumlah tempat pengungsian yang Ada/Tidak Ada distribusi bantuan pemenuhan perlengkapan pribadi dan kebersihan pribadi baik di tempat pengungsian terkonsentrasi dan tidak terkonsentrasi, kemudian dijumlah sebagai jumlah total distribusi bantuan pemenuhan perlengkapan pribadi dan kebersihan pribadi.', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 2)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1451, 'juknis-9-2023', 65, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 3)', NULL, 49, '2. Jumlah perlengkapan pribadi dan kebersihan pribadi seperti pakaian, alas kaki, seragam sekolah, perlengkapan ibadah, selimut, alas tidur yang belum tercukupi dengan memperhitungkan jumlah Pengungsi baik jenis kelamin dan usia di tempat pengungsian terkonsentrasi dan tidak terkonsentrasi kemudian dijumlah sebagai jumlah total pemenuhan perlengkapan pribadi dan kebersihan pribadi.
Kebutuhan pakaian tiap orang 1 (satu) stel, kecuali perempuan dan anak 2 (dua) stel.
3. Jumlah pemenuhan paket kebutuhan bayi dan balita (yang belum tercukupi) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data.
4. jumlah total paket kebutuhan bayi dan balita yang belum tercukupi.
5. Jumlah pemenuhan paket kebutuhan bagi lansia (yang belum tercukupi) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total paket kebutuhan bagi lansia yang belum tercukupi.
6. Jumlah pemenuhan kebutuhan pembalut wanita (yang belum terpenuhi) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total kebutuhan pembalut wanita yang belum terpenuhi
d. Kesehatan dan Psikososial diisi dengan:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1451, '2. Jumlah perlengkapan pribadi dan kebersihan pribadi seperti pakaian, alas kaki, seragam sekolah, perlengkapan ibadah, selimut, alas tidur yang belum tercukupi dengan memperhitungkan jumlah Pengungsi baik jenis kelamin dan usia di tempat pengungsian terkonsentrasi dan tidak terkonsentrasi kemudian dijumlah sebagai jumlah total pemenuhan perlengkapan pribadi dan kebersihan pribadi.
Kebutuhan pakaian tiap orang 1 (satu) stel, kecuali perempuan dan anak 2 (dua) stel.
3. Jumlah pemenuhan paket kebutuhan bayi dan balita (yang belum tercukupi) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data.
4. jumlah total paket kebutuhan bayi dan balita yang belum tercukupi.
5. Jumlah pemenuhan paket kebutuhan bagi lansia (yang belum tercukupi) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total paket kebutuhan bagi lansia yang belum tercukupi.
6. Jumlah pemenuhan kebutuhan pembalut wanita (yang belum terpenuhi) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total kebutuhan pembalut wanita yang belum terpenuhi
d. Kesehatan dan Psikososial diisi dengan:', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 3)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1452, 'juknis-9-2023', 66, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 4)', NULL, 50, '1. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia Pos Pelayanan Kesehatan di tempat pengungsian terkonsentrasi dan di tempat engungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan pos pelayanan kesehatan.
2. Jumlah dokter, bidan, asisten apoteker, sanitarian, ahli gizi, psikiater, psikolog, pekerja sosial, penyuluh sosial, relawan dan tenaga administrasi di tempat pengungsian terkonsentrasi, dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total dokter, bidan, asisten apoteker, sanitarian, ahli gizi, tenaga psikososial dan tenaga administrasi.
3. Jumlah ketersediaan prasarana dan sarana medis di pos pelayanan kesehatan beserta jumlah ketersediaan tandu/stretcher, kursi roda dan ambulan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan prasarana dan sarana medis di pos pelayanan kesehatan beserta jumlah ketersediaan tandu/stretcher, kursi roda dan ambulan.
4. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia pelayanan Kesehatan Ibu dan Anak (KIA) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total pelayanan Kesehatan Ibu dan Anak (KIA).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1452, '1. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia Pos Pelayanan Kesehatan di tempat pengungsian terkonsentrasi dan di tempat engungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan pos pelayanan kesehatan.
2. Jumlah dokter, bidan, asisten apoteker, sanitarian, ahli gizi, psikiater, psikolog, pekerja sosial, penyuluh sosial, relawan dan tenaga administrasi di tempat pengungsian terkonsentrasi, dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total dokter, bidan, asisten apoteker, sanitarian, ahli gizi, tenaga psikososial dan tenaga administrasi.
3. Jumlah ketersediaan prasarana dan sarana medis di pos pelayanan kesehatan beserta jumlah ketersediaan tandu/stretcher, kursi roda dan ambulan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan prasarana dan sarana medis di pos pelayanan kesehatan beserta jumlah ketersediaan tandu/stretcher, kursi roda dan ambulan.
4. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia pelayanan Kesehatan Ibu dan Anak (KIA) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total pelayanan Kesehatan Ibu dan Anak (KIA).', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 4)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1453, 'juknis-9-2023', 67, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 5)', NULL, 50, '5. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia Obat-Obatan Esensial di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan obat-obatan esensial.
6. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia pelayanan kesehatan dan gizi bagi penderita dengan penyakit bawaan/komorbid/menular di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan pelayanan kesehatan dan gizi bagi penderita dengan penyakit bawaan/komorbid/menular.
7. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia pelayanan kesehatan reproduksi termasuk pelayanan korban kekerasan seksual di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan pelayanan kesehatan reproduksi termasuk pelayanan korban kekerasan seksual.
8. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia sarana rekreasi (bagi Pengungsi berdurasi lama) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan sarana rekreasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1453, '5. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia Obat-Obatan Esensial di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan obat-obatan esensial.
6. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia pelayanan kesehatan dan gizi bagi penderita dengan penyakit bawaan/komorbid/menular di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan pelayanan kesehatan dan gizi bagi penderita dengan penyakit bawaan/komorbid/menular.
7. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia pelayanan kesehatan reproduksi termasuk pelayanan korban kekerasan seksual di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan pelayanan kesehatan reproduksi termasuk pelayanan korban kekerasan seksual.
8. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia sarana rekreasi (bagi Pengungsi berdurasi lama) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan sarana rekreasi.', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 5)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1454, 'juknis-9-2023', 68, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 6)', NULL, 51, '9. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia layanan dukungan psikososial dan kesehatan jiwa (pendampingan dan mekanisme rujukan) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan dukungan psikososial dan kesehatan jiwa.
10. Jumlah tempat Pengungsian yang Tersedia/Tidak tersedia ruang ramah ibu dan anak di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan ruang ramah ibu dan anak.
11. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia ruang laktasi di tempat pengungsian terkonsentrasi dan di tempat Pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan ruang laktasi.
12. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia layanan pemberian suplemen gizi di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan pemberian suplemen gizi.
13. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia layanan kesehatan dan alat bantu bagi lansia di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan kesehatan dan alat bantu bagi lansia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1454, '9. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia layanan dukungan psikososial dan kesehatan jiwa (pendampingan dan mekanisme rujukan) di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan dukungan psikososial dan kesehatan jiwa.
10. Jumlah tempat Pengungsian yang Tersedia/Tidak tersedia ruang ramah ibu dan anak di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan ruang ramah ibu dan anak.
11. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia ruang laktasi di tempat pengungsian terkonsentrasi dan di tempat Pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan ruang laktasi.
12. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia layanan pemberian suplemen gizi di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan pemberian suplemen gizi.
13. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia layanan kesehatan dan alat bantu bagi lansia di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan kesehatan dan alat bantu bagi lansia.', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 6)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1455, 'juknis-9-2023', 69, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 7)', NULL, 51, '14. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia layanan kesehatan dan alat bantu bagi disabilitas di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan kesehatan dan alat bantu bagi disabilitas
15. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia kegiatan pengendalian vektor penyakit potensial wabah di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan kegiatan pengendalian vektor penyakit potensial wabah.
16. Jumlah pasangan usia subur di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total pasangan usia subur.
17. Jumlah wanita usia subur di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total wanita usia subur.
18. Urutan penyakit yang banyak diidap oleh Pengungsi di tempat pengungsian (5 besar).
19. Urutan penyakit yang banyak diidap Pengungsi balita di tempat pengungsian (5 besar).
e. Penampungan dan Tempat Hunian Sementara diisi dengan:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1455, '14. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia layanan kesehatan dan alat bantu bagi disabilitas di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan kesehatan dan alat bantu bagi disabilitas
15. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia kegiatan pengendalian vektor penyakit potensial wabah di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan kegiatan pengendalian vektor penyakit potensial wabah.
16. Jumlah pasangan usia subur di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total pasangan usia subur.
17. Jumlah wanita usia subur di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total wanita usia subur.
18. Urutan penyakit yang banyak diidap oleh Pengungsi di tempat pengungsian (5 besar).
19. Urutan penyakit yang banyak diidap Pengungsi balita di tempat pengungsian (5 besar).
e. Penampungan dan Tempat Hunian Sementara diisi dengan:', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 7)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1456, 'juknis-9-2023', 70, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 8)', NULL, 52, '1. Jumlah tempat pengungsian di tempat fasilitas umum, tanah lapang, lahan/gedung swasta, tempat ibadah dan rumah milik perorangan di Tempat Pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total tipe tempat pengungsian di tempat fasilitas umum, tanah lapang, lahan/gedung swasta, tempat ibadah dan rumah milik perorangan. Standar untuk luas penampungan/tempat hunian sementara adalah 3.5 m2 / Orang.
2. Jumlah tempat pengungsian yang tersedia/tidak tersedia akses dan jangkauan listrik di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan akses dan jangkauan listrik.
3. Jumlah tempat pengungsian yang tersedia/tidak tersedia layanan pengamanan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan pengamanan di tempat pengungsian.
4. Jumlah tempat pengungsian yang tersedia/tidak tersedia layanan pengaduan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan pengaduan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1456, '1. Jumlah tempat pengungsian di tempat fasilitas umum, tanah lapang, lahan/gedung swasta, tempat ibadah dan rumah milik perorangan di Tempat Pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total tipe tempat pengungsian di tempat fasilitas umum, tanah lapang, lahan/gedung swasta, tempat ibadah dan rumah milik perorangan. Standar untuk luas penampungan/tempat hunian sementara adalah 3.5 m2 / Orang.
2. Jumlah tempat pengungsian yang tersedia/tidak tersedia akses dan jangkauan listrik di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan akses dan jangkauan listrik.
3. Jumlah tempat pengungsian yang tersedia/tidak tersedia layanan pengamanan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan pengamanan di tempat pengungsian.
4. Jumlah tempat pengungsian yang tersedia/tidak tersedia layanan pengaduan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan pengaduan', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 8)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1457, 'juknis-9-2023', 71, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 9)', NULL, 52, '5. Jumlah tempat pengungsian di tempat fasilitas umum, tanah lapang, lahan/gedung swasta, tempat ibadah dan rumah milik perorangan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total tipe tempat pengungsian di tempat fasilitas umum, tanah lapang, lahan/gedung swasta, tempat ibadah dan rumah milik perorangan. Standar untuk luas penampungan/tempat hunian sementara adalah 3.5 m2 / Orang
6. Jumlah tempat pengungsian yang tersedia/tidak tersedia akses dan jangkauan listrik di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan akses dan jangkauan listrik.
7. Jumlah tempat pengungsian yang tersedia/tidak tersedia layanan pengamanan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan pengamanan di tempat pengungsian.
8. Jumlah tempat pengungsian yang tersedia/tidak tersedia layanan pengaduan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan pengaduan
f. Penyediaan Layanan Pendidikan Darurat diisi dengan:
1. Jumlah anak usia sekolah (PAUD, SD, SMP, SMA) di tempat pengungsian terkonsentrasi dan tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total jumlah anak usia sekolah berdasarkan jenjang pendidikannya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1457, '5. Jumlah tempat pengungsian di tempat fasilitas umum, tanah lapang, lahan/gedung swasta, tempat ibadah dan rumah milik perorangan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total tipe tempat pengungsian di tempat fasilitas umum, tanah lapang, lahan/gedung swasta, tempat ibadah dan rumah milik perorangan. Standar untuk luas penampungan/tempat hunian sementara adalah 3.5 m2 / Orang
6. Jumlah tempat pengungsian yang tersedia/tidak tersedia akses dan jangkauan listrik di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan akses dan jangkauan listrik.
7. Jumlah tempat pengungsian yang tersedia/tidak tersedia layanan pengamanan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan pengamanan di tempat pengungsian.
8. Jumlah tempat pengungsian yang tersedia/tidak tersedia layanan pengaduan di tempat pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan pengaduan
f. Penyediaan Layanan Pendidikan Darurat diisi dengan:
1. Jumlah anak usia sekolah (PAUD, SD, SMP, SMA) di tempat pengungsian terkonsentrasi dan tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total jumlah anak usia sekolah berdasarkan jenjang pendidikannya.', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 9)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1458, 'juknis-9-2023', 72, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 10)', NULL, 53, '2. Jumlah tempat pengungsian yang Tersedia/Tidak tersedia layanan pendidikan darurat di Tempat Pengungsian terkonsentrasi dan di tempat pengungsian tidak terkonsentrasi kemudian dijumlah sebagai data jumlah total ketersediaan layanan layanan pendidikan darurat Format 4 - Laporan Hasil Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana Pelaporan Data dan Informasi Pengungsi Terpilah dari Posko PDB ke Kepala Daerah Provinsi/Kabupaten/Kota Surat Pengantar Penyampaian Hasil Pendataan Pengungsi Terpilah ……………. , …………….. 20.........
(Nama Kota/Kab, Tanggal, Bulan, Tahun) Kepada Yth.
