INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1461, 'juknis-9-2023', 75, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 13)', NULL, 56, '13. Penanganan Khusus (Jantung, Stroke, Paru-Paru, Diabetes) Hasil dan Rekomendasi Jenis Pemenuhan Kebutuhan Data Pengungsi Terpilah No. Jenis Pemenuhan Kebutuhan Saran Tindak Lanjut 1 Air Bersih dan Sanitasi 2 Pangan 3 Sandang/Non Pangan 4 Kesehatan dan Psikososial Penampungan dan 5 Tempat Hunian Sementara Penyediaan Layanan 6 Pendidikan Darurat 7 Hal-hal lain yang perlu disampaikan Komandan Posko Penanganan Darurat Bencana …, ( Nama Terang ) Format 5 – Contoh Proses CAPI (Computer Assisted Personal Interviewing) Contoh Proses CAPI Petunjuk Pengisian Form Pendataan Pengungsi Menggunakan Gawai
1. Persyaratan Gawai yang dapat digunakan adalah tipe Android minimum Android 6, atau menggunakan gawai Iphone dengan minimum IOS 13, serta tempat penyimpanan minimum 500mb.
2. Proses pengunduhan aplikasi Aplikasi diapat diunduh di Google Play Store ataupun Apple App Store dengan kata kunci “ArcGIS Survey123”
3. Proses Pengunduhan Formulir Formulir untuk survey perlu diunduh sebelum melaksanakan pengumpulan data. Formulir dapat diunduh dengan melakukan pindai QR code formulir dari dalam aplikasi ArcGIS Survey123. QR code formulir akan dibagikan oleh Unit Kerja di lingkungan Badan Nasional Penanggulangan Bencana yang menangani Pemulihan Sosial Ekonomi dan atau Unit Kerja di lingkungan Badan Nasional Penanggulangan Bencana yang menangani Data, Informasi, dan Komunikasi.
Ketuk simbol QR code di pojok kanan atas aplikasi untuk membuka kamera pemindai Proses Input Data');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1461, '13. Penanganan Khusus (Jantung, Stroke, Paru-Paru, Diabetes) Hasil dan Rekomendasi Jenis Pemenuhan Kebutuhan Data Pengungsi Terpilah No. Jenis Pemenuhan Kebutuhan Saran Tindak Lanjut 1 Air Bersih dan Sanitasi 2 Pangan 3 Sandang/Non Pangan 4 Kesehatan dan Psikososial Penampungan dan 5 Tempat Hunian Sementara Penyediaan Layanan 6 Pendidikan Darurat 7 Hal-hal lain yang perlu disampaikan Komandan Posko Penanganan Darurat Bencana …, ( Nama Terang ) Format 5 – Contoh Proses CAPI (Computer Assisted Personal Interviewing) Contoh Proses CAPI Petunjuk Pengisian Form Pendataan Pengungsi Menggunakan Gawai
1. Persyaratan Gawai yang dapat digunakan adalah tipe Android minimum Android 6, atau menggunakan gawai Iphone dengan minimum IOS 13, serta tempat penyimpanan minimum 500mb.
2. Proses pengunduhan aplikasi Aplikasi diapat diunduh di Google Play Store ataupun Apple App Store dengan kata kunci “ArcGIS Survey123”
3. Proses Pengunduhan Formulir Formulir untuk survey perlu diunduh sebelum melaksanakan pengumpulan data. Formulir dapat diunduh dengan melakukan pindai QR code formulir dari dalam aplikasi ArcGIS Survey123. QR code formulir akan dibagikan oleh Unit Kerja di lingkungan Badan Nasional Penanggulangan Bencana yang menangani Pemulihan Sosial Ekonomi dan atau Unit Kerja di lingkungan Badan Nasional Penanggulangan Bencana yang menangani Data, Informasi, dan Komunikasi.
Ketuk simbol QR code di pojok kanan atas aplikasi untuk membuka kamera pemindai Proses Input Data', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 13)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1462, 'juknis-9-2023', 76, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 14)', NULL, 59, 'a. Petugas input data langsung masuk ke aplikasi tanpa menggunakan login dengan cara memilih opsi “Continue without signing in”
b. Sebelum memulai proses pendataan, petugas input data terlebih dahulu harus mengunduh formulir pendataannya (cukup dilakukan sekali) melalui scan QR code pada langkah sebelumnya. Formulir yang sudah diunduh akan tersimpan dalam aplikasi yang sudah terinstal di gawai.
c. Klik pada formulir pendataan, kemudian isi formulir sesuai dengan pertanyaan yang muncul pada layar.
Untuk pertanyaan dengan jenis isian teks, dapat langsung diketik isian sesuai jawaban yang diinginkan dari pertanyaan
d. Untuk pertanyaan dengan jenis isian angka, dapat langsung diisikan sesuai angka yang diinginkan. Khusus untuk pertanyaan dengan jenis isian angka, papan ketik/keyboard yang muncul akan langsung menampilkan karakter angka saja.
e. Untuk pertanyaan mengenai koordinat lokasi, dapat dilakukan dengan cara otomatis memilih koordinat sesuai lokasi dimana petugas berada, atau memilih lokasi dengan bantuan peta. Pastikan akurasi koordinat sudah berada di rentang ketelitian yang cukup (<20 meter) untuk menjaga kualitas akurasi koordinat yang dihasilkan.
f. Untuk pertanyaan dengan jenis isian tanggal, dapat langsung memilih tanggal sesuai tampilan kalender yang muncul
g. Untuk pertanyaan dengan jenis jawab pilihan ganda, dapat langsung mengetuk pilihan jawaban yang tersedia pada layar');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1462, 'a. Petugas input data langsung masuk ke aplikasi tanpa menggunakan login dengan cara memilih opsi “Continue without signing in”
b. Sebelum memulai proses pendataan, petugas input data terlebih dahulu harus mengunduh formulir pendataannya (cukup dilakukan sekali) melalui scan QR code pada langkah sebelumnya. Formulir yang sudah diunduh akan tersimpan dalam aplikasi yang sudah terinstal di gawai.
c. Klik pada formulir pendataan, kemudian isi formulir sesuai dengan pertanyaan yang muncul pada layar.
Untuk pertanyaan dengan jenis isian teks, dapat langsung diketik isian sesuai jawaban yang diinginkan dari pertanyaan
d. Untuk pertanyaan dengan jenis isian angka, dapat langsung diisikan sesuai angka yang diinginkan. Khusus untuk pertanyaan dengan jenis isian angka, papan ketik/keyboard yang muncul akan langsung menampilkan karakter angka saja.
e. Untuk pertanyaan mengenai koordinat lokasi, dapat dilakukan dengan cara otomatis memilih koordinat sesuai lokasi dimana petugas berada, atau memilih lokasi dengan bantuan peta. Pastikan akurasi koordinat sudah berada di rentang ketelitian yang cukup (<20 meter) untuk menjaga kualitas akurasi koordinat yang dihasilkan.
f. Untuk pertanyaan dengan jenis isian tanggal, dapat langsung memilih tanggal sesuai tampilan kalender yang muncul
g. Untuk pertanyaan dengan jenis jawab pilihan ganda, dapat langsung mengetuk pilihan jawaban yang tersedia pada layar', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 14)', 'Petunjuk Pelaksanaan Nomor 9 Tahun 2023 tentang Pengelolaan Data dan Informasi Pengungsi Terpilah Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1463, 'juknis-9-2023', 77, 'lain', 'III. Jumlah Kebutuhan Pemenuhan Pengungsi (lanjutan 15)', NULL, 62, 'h. Dalam kondisi tidak ada sinyal internet yang memadai atau dalam situasi yang tidak memungkinkan petugas input data untuk mengirimkan formulir, petugas input data dapat menyimpannya terlebih dahulu di kotak keluar dengan mengetuk pilihan “Save in Outbox”
i. Apabila tidak ada kendala untuk mengirimkan formulir, petugas input data dapat langsung mengirimkan formulir tersebut dengan mengetuk pilihan “Send now
j. Jika petugas kemudian sudah terhubung dengan jaringan dan memiliki akses ke internet, petugas dapat mengirim hasil survey yang sudah tersimpan sebelumnya dalam kotak keluar/Outbox dan mengetuk pilihan “Send”.
Format 6 – Contoh Dashboard penyajian informasi dan pelaporan Dashboard yang disiapkan adalah tampilan untuk menyajikan data Pengungsi secara terpilah per kejadian bencana. Contoh dashboard penyajian data bisa menggunakan beberapa contoh berikut KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi dan Kerja Sama, Irma Dewi Rismayati');
