INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1476, 'pedoman-1-2024', 0, 'judul', 'Judul', NULL, 1, 'Pedoman Kepala BNPB Nomor 1 Tahun 2024 tentang Pengelolaan Arsip Elektronik di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1476, 'Pedoman Kepala BNPB Nomor 1 Tahun 2024 tentang Pengelolaan Arsip Elektronik di Lingkungan Badan Nasional Penanggulangan Bencana', 'Judul', 'Pedoman Kepala BNPB Nomor 1 Tahun 2024 tentang Pengelolaan Arsip Elektronik di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1477, 'pedoman-1-2024', 1, 'lain', 'Isi hal. 1', NULL, 1, 'KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PEDOMAN PENGELOLAAN ARSIP ELEKTRONIK DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 1 TAHUN 2024 BABI PENDAHULUAN Latar Belakang Penyelenggaraan negara seharusnya dapat bergerak menyesuaikan perubahan zaman dan kebutuhan akan teknologi informasi yang dilakukan melalui pelaksanaan proses transformasi menuju E-Government. Melalui proses transformasi tersebut, pemerintah dapat mengoptimasikan pemanfaatan kemajuan teknologi informasi untuk mengeliminasi sekat-sekat organisasi birokrasi, serta membentuk jaringan sistem manajemen dan proses kerja yang memungkinkan instansi-instansi pemerintah bekerja secara terpadu untuk menyederhanakan akses ke semua informasi dan layanan publik yang harus disediakan oleh pemerintah. Dengan demikian, seluruh lembaga negara, masyarakat, dunia usaha, dan pihak-pihak berkepentingan lainnya dapat setiap saat memanfaatkan informasi dan layanan pemerintah secara optimal.
E-Government merupakan situasi dimana proses suatu pemerintahan yang dijalankan berbasis elektronik atau dengan bantuan teknologi informasi dan komunikasi. E-Government juga bertujuan untuk meningkatkan kualitas layanan publik secara efektif dan efisien. Melalui E-Government dapat dilakukan penataan sistem manajemen dan proses kerja di lingkungan pemerintah dengan mengoptimalkan pemanfaatan teknologi informasi dan komunikasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1477, 'KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PEDOMAN PENGELOLAAN ARSIP ELEKTRONIK DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 1 TAHUN 2024 BABI PENDAHULUAN Latar Belakang Penyelenggaraan negara seharusnya dapat bergerak menyesuaikan perubahan zaman dan kebutuhan akan teknologi informasi yang dilakukan melalui pelaksanaan proses transformasi menuju E-Government. Melalui proses transformasi tersebut, pemerintah dapat mengoptimasikan pemanfaatan kemajuan teknologi informasi untuk mengeliminasi sekat-sekat organisasi birokrasi, serta membentuk jaringan sistem manajemen dan proses kerja yang memungkinkan instansi-instansi pemerintah bekerja secara terpadu untuk menyederhanakan akses ke semua informasi dan layanan publik yang harus disediakan oleh pemerintah. Dengan demikian, seluruh lembaga negara, masyarakat, dunia usaha, dan pihak-pihak berkepentingan lainnya dapat setiap saat memanfaatkan informasi dan layanan pemerintah secara optimal.
E-Government merupakan situasi dimana proses suatu pemerintahan yang dijalankan berbasis elektronik atau dengan bantuan teknologi informasi dan komunikasi. E-Government juga bertujuan untuk meningkatkan kualitas layanan publik secara efektif dan efisien. Melalui E-Government dapat dilakukan penataan sistem manajemen dan proses kerja di lingkungan pemerintah dengan mengoptimalkan pemanfaatan teknologi informasi dan komunikasi.', 'Isi hal. 1', 'Pedoman Kepala BNPB Nomor 1 Tahun 2024 tentang Pengelolaan Arsip Elektronik di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1478, 'pedoman-1-2024', 2, 'lain', 'Isi hal. 1', NULL, 1, 'Penerapan pengelolaan arsip elektronik merupakan salah satu upaya untuk terlaksananya implementasi e-Government tersebut. Pengelolaan arsip elektronik akan mengurangi proses yang tidak diperlukan dalam penanganan arsip karena prosedur standar yang biasanya dilakukan secara manual dapat dialihkan pada sistem elektronik. Kinerja dalam hal penanganan arsip akan meningkat karena sistem aplikasi pengelolaan arsip memungkinkan semua aktivitas berlangsung secara real time (waktu nyata) dan cepat yang dibentuk dengan teknologi informasi.
Oleh sebab itu, pedoman ini akan memuat ketentuan mengenai tahapan pengelolaan arsip elektronik yang mengacu pada penyelenggaraan kearsipan konvensional. Dengan demikian dibentuk Pedoman Pengelolaan Arsip Elektronik yang akan menjadi pedoman internal bagi pegawai Badan Nasional Penanggulangan Bencana dan pihak terkait dalam pengelolaan arsip elektronik Badan Nasional Penanggulangan Bencana.
Maksud dan Tujuan Maksud dan tujuan dari Pedoman ini adalah sebagai berikut.
1. Pedoman ini dimaksudkan sebagai acuan dalam pengelolaan arsip elektronik bagi unit kearsipan dan unit pengolah di lingkungan Badan Nasional Penanggulangan Bencana.
2. Tujuan dari pedoman ini adalah menyediakan mekanisme pengelolaan arsip elektronik mulai dari penciptaan, penyimpanan, penggunaan, sampai dengan penyusutan secara elektronik di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1478, 'Penerapan pengelolaan arsip elektronik merupakan salah satu upaya untuk terlaksananya implementasi e-Government tersebut. Pengelolaan arsip elektronik akan mengurangi proses yang tidak diperlukan dalam penanganan arsip karena prosedur standar yang biasanya dilakukan secara manual dapat dialihkan pada sistem elektronik. Kinerja dalam hal penanganan arsip akan meningkat karena sistem aplikasi pengelolaan arsip memungkinkan semua aktivitas berlangsung secara real time (waktu nyata) dan cepat yang dibentuk dengan teknologi informasi.
Oleh sebab itu, pedoman ini akan memuat ketentuan mengenai tahapan pengelolaan arsip elektronik yang mengacu pada penyelenggaraan kearsipan konvensional. Dengan demikian dibentuk Pedoman Pengelolaan Arsip Elektronik yang akan menjadi pedoman internal bagi pegawai Badan Nasional Penanggulangan Bencana dan pihak terkait dalam pengelolaan arsip elektronik Badan Nasional Penanggulangan Bencana.
Maksud dan Tujuan Maksud dan tujuan dari Pedoman ini adalah sebagai berikut.
1. Pedoman ini dimaksudkan sebagai acuan dalam pengelolaan arsip elektronik bagi unit kearsipan dan unit pengolah di lingkungan Badan Nasional Penanggulangan Bencana.
2. Tujuan dari pedoman ini adalah menyediakan mekanisme pengelolaan arsip elektronik mulai dari penciptaan, penyimpanan, penggunaan, sampai dengan penyusutan secara elektronik di lingkungan Badan Nasional Penanggulangan Bencana.', 'Isi hal. 1', 'Pedoman Kepala BNPB Nomor 1 Tahun 2024 tentang Pengelolaan Arsip Elektronik di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1479, 'pedoman-1-2024', 3, 'lain', 'Isi hal. 2', NULL, 2, 'Sasaran Sasaran Pedoman ini adalah seluruh pegawai di lingkungan BNPB dapat memahami pengelolaan arsip secara elektronik, meningkatkan transparansi dan akuntabilitas organisasi, serta mengimplementasikan sistem pemerintahan berbasis elektronik di lingkungan BNPB.
Asas Pengelolaan Arsip Elektronik
1. Kepastian Hukum Penyelenggaraan kearsipan dilaksanakan berdasarkan landasan hukum dan selaras dengan peraturan perundang-undangan, kepatutan, dan keadilan dalam kebijakan penyelenggara negara. Hal ini memenuhi penerapan asas supremasi hukum yang menyatakan bahwa setiap kegiatan penyelenggaraan negara didasarkan pada hukum yang berlaku.
2. Keautentikan dan Keterpercayaan Penyelenggaraan kearsipan harus berpegang pada asas menjaga keaslian dan keterpercayaan arsip sehingga dapat digunakan sebagai bukti dan bahan akuntabilitas.
3. Keutuhan Penyelenggaraan kearsipan harus menjaga kelengkapan arsip dari upaya pengurangan, penambahan, dan pengubahan informasi maupun fisiknya yang dapat mengganggu keautentikan dan keterpercayaan arsip.
4. Asal Usul (Principle of Provenance) Asas yang dilakukan untuk menjaga arsip tetap terkelola dalam satu kesatuan Pencipta Arsip (provenance), tidak dicampur dengan arsip yang berasal dari Pencipta Arsip lain, sehingga arsip dapat melekat pada konteks penciptaannya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1479, 'Sasaran Sasaran Pedoman ini adalah seluruh pegawai di lingkungan BNPB dapat memahami pengelolaan arsip secara elektronik, meningkatkan transparansi dan akuntabilitas organisasi, serta mengimplementasikan sistem pemerintahan berbasis elektronik di lingkungan BNPB.
Asas Pengelolaan Arsip Elektronik
1. Kepastian Hukum Penyelenggaraan kearsipan dilaksanakan berdasarkan landasan hukum dan selaras dengan peraturan perundang-undangan, kepatutan, dan keadilan dalam kebijakan penyelenggara negara. Hal ini memenuhi penerapan asas supremasi hukum yang menyatakan bahwa setiap kegiatan penyelenggaraan negara didasarkan pada hukum yang berlaku.
2. Keautentikan dan Keterpercayaan Penyelenggaraan kearsipan harus berpegang pada asas menjaga keaslian dan keterpercayaan arsip sehingga dapat digunakan sebagai bukti dan bahan akuntabilitas.
3. Keutuhan Penyelenggaraan kearsipan harus menjaga kelengkapan arsip dari upaya pengurangan, penambahan, dan pengubahan informasi maupun fisiknya yang dapat mengganggu keautentikan dan keterpercayaan arsip.
4. Asal Usul (Principle of Provenance) Asas yang dilakukan untuk menjaga arsip tetap terkelola dalam satu kesatuan Pencipta Arsip (provenance), tidak dicampur dengan arsip yang berasal dari Pencipta Arsip lain, sehingga arsip dapat melekat pada konteks penciptaannya.', 'Isi hal. 2', 'Pedoman Kepala BNPB Nomor 1 Tahun 2024 tentang Pengelolaan Arsip Elektronik di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1480, 'pedoman-1-2024', 4, 'lain', 'Isi hal. 2', NULL, 2, '5. Aturan Asli (Principle of Original Order) Asas yang dilakukan untuk menjaga arsip tetap ditata sesuai dengan pengaturan aslinya (original order) atau sesuai dengan pengaturan ketika arsip masih digunakan untuk pelaksanaan kegiatan Pencipta Arsip.
6. Keamanan dan Keselamatan Asas keamanan adalah penyelenggaraan kearsipan harus memberikan jaminan keamanan arsip dari kemungkinan kebocoran dan penyalahgunaan informasi oleh pengguna yang tidak berhak.
Sedangkan asas keselamatan adalah bahwa penyelenggaraan kearsipan harus dapat menjamin terselamatkannya arsip dari ancaman bahaya, baik yang disebabkan oleh alam maupun perbuatan manusia.
7. Akuntabilitas Penyelenggaraan kearsipan harus memperhatikan arsip sebagai bahan akuntabilitas dan harus bisa merefleksikan kegiatan dan peristiwa yang direkam.
8. Kemanfaatan Penyelenggaraan kearsipan harus dapat memberikan manfaat bagi kehidupan bermasyarakat, berbangsa, dan bernegara.
9. Aksesibilitas Penyelenggaraan kearsipan harus dapat memberikan kemudahan, ketersediaan dan keterjangkauan bagi masyarakat untuk memanfaatkan arsip.
10. Kepentingan Umum Penyelenggaraan kearsipan dilaksanakan dengan memperhatikan kepentingan umum dan tanpa diskriminasi.
Ruang Lingkup Ruang lingkup pengaturan Pedoman ini mencakup seluruh pegawai di lingkungan Badan Nasional Penanggulangan Bencana yang mengelola arsip elektronik.
Pengertian Umum');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1480, '5. Aturan Asli (Principle of Original Order) Asas yang dilakukan untuk menjaga arsip tetap ditata sesuai dengan pengaturan aslinya (original order) atau sesuai dengan pengaturan ketika arsip masih digunakan untuk pelaksanaan kegiatan Pencipta Arsip.
6. Keamanan dan Keselamatan Asas keamanan adalah penyelenggaraan kearsipan harus memberikan jaminan keamanan arsip dari kemungkinan kebocoran dan penyalahgunaan informasi oleh pengguna yang tidak berhak.
Sedangkan asas keselamatan adalah bahwa penyelenggaraan kearsipan harus dapat menjamin terselamatkannya arsip dari ancaman bahaya, baik yang disebabkan oleh alam maupun perbuatan manusia.
7. Akuntabilitas Penyelenggaraan kearsipan harus memperhatikan arsip sebagai bahan akuntabilitas dan harus bisa merefleksikan kegiatan dan peristiwa yang direkam.
8. Kemanfaatan Penyelenggaraan kearsipan harus dapat memberikan manfaat bagi kehidupan bermasyarakat, berbangsa, dan bernegara.
9. Aksesibilitas Penyelenggaraan kearsipan harus dapat memberikan kemudahan, ketersediaan dan keterjangkauan bagi masyarakat untuk memanfaatkan arsip.
10. Kepentingan Umum Penyelenggaraan kearsipan dilaksanakan dengan memperhatikan kepentingan umum dan tanpa diskriminasi.
Ruang Lingkup Ruang lingkup pengaturan Pedoman ini mencakup seluruh pegawai di lingkungan Badan Nasional Penanggulangan Bencana yang mengelola arsip elektronik.
Pengertian Umum', 'Isi hal. 2', 'Pedoman Kepala BNPB Nomor 1 Tahun 2024 tentang Pengelolaan Arsip Elektronik di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1481, 'pedoman-1-2024', 5, 'lain', 'Isi hal. 3', NULL, 3, '1. Arsip Elektronik adalah arsip yang diciptakan yaitu dibuat dan diterima dalam format elektronik atau arsip hasil alih media.
2. Pengelolaan Arsip Elektronik adalah proses pengendalian Arsip Elektronik secara efisien, efektif, dan sistematis yang meliputi pembuatan, penerimaan, penggunaan, penyimpanan, pemeliharaan, alih media, penyusutan, akuisisi, deskripsi, pengolahan, preservasi, akses dan pemanfaatan.
3. Arsip Dinamis adalah arsip yang digunakan secara langsung dalam kegiatan pencipta arsip dan disimpan selama jangka waktu tertentu.
4. Pencipta Arsip adalah pihak yang memiliki kemandirian dan otoritas dalam pelaksanaan fungsi, tugas, dan tanggung jawab di bidang pengelolaan Arsip Dinamis.
5. Unit Pengolah adalah unit kerja pada Pencipta Arsip yang mempunyai tugas dan tanggung jawab mengolah semua arsip yang berkaitan dengan kegiatan penciptaan arsip di lingkungannya.
6. Jadwal Retensi Arsip adalah daftar yang berisi sekurang-kurangnya jangka waktu penyimpanan atau retensi, jenis arsip, dan keterangan yang berisi rekomendasi tentang penetapan suatu jenis arsip dimusnahkan, dinilai kembali, atau dipermanenkan yang dipergunakan sebagai pedoman penyusutan dan penyelamatan arsip.
7. Tanda Tangan Elektronik adalah tanda tangan yang terdiri atas informasi elektronik yang dilekatkan, terasosiasi atau terkait dengan informasi elektronik lainnya yang digunakan sebagai alat verifikasi dan autentikasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1481, '1. Arsip Elektronik adalah arsip yang diciptakan yaitu dibuat dan diterima dalam format elektronik atau arsip hasil alih media.
2. Pengelolaan Arsip Elektronik adalah proses pengendalian Arsip Elektronik secara efisien, efektif, dan sistematis yang meliputi pembuatan, penerimaan, penggunaan, penyimpanan, pemeliharaan, alih media, penyusutan, akuisisi, deskripsi, pengolahan, preservasi, akses dan pemanfaatan.
3. Arsip Dinamis adalah arsip yang digunakan secara langsung dalam kegiatan pencipta arsip dan disimpan selama jangka waktu tertentu.
4. Pencipta Arsip adalah pihak yang memiliki kemandirian dan otoritas dalam pelaksanaan fungsi, tugas, dan tanggung jawab di bidang pengelolaan Arsip Dinamis.
5. Unit Pengolah adalah unit kerja pada Pencipta Arsip yang mempunyai tugas dan tanggung jawab mengolah semua arsip yang berkaitan dengan kegiatan penciptaan arsip di lingkungannya.
6. Jadwal Retensi Arsip adalah daftar yang berisi sekurang-kurangnya jangka waktu penyimpanan atau retensi, jenis arsip, dan keterangan yang berisi rekomendasi tentang penetapan suatu jenis arsip dimusnahkan, dinilai kembali, atau dipermanenkan yang dipergunakan sebagai pedoman penyusutan dan penyelamatan arsip.
7. Tanda Tangan Elektronik adalah tanda tangan yang terdiri atas informasi elektronik yang dilekatkan, terasosiasi atau terkait dengan informasi elektronik lainnya yang digunakan sebagai alat verifikasi dan autentikasi.', 'Isi hal. 3', 'Pedoman Kepala BNPB Nomor 1 Tahun 2024 tentang Pengelolaan Arsip Elektronik di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1482, 'pedoman-1-2024', 6, 'lain', 'Isi hal. 3', NULL, 3, '8. Informasi Elektronik adalah satu atau sekumpulan data elektronik, tetapi tidak terbatas pada tulisan, suara, gambar, peta, rancangan, foto, Electronic Data Interchange (EDI), surat elektronik (electronic mail), telegram, teleks, telecopy, atau sejenisnya, huruf, tanda, angka, kode akses, simbol, atau perforasi yang telah diolah yang memiliki arti atau dapat dipahami oleh orang yang mampu memahaminya.
9. Dokumen Elektronik adalah setiap Informasi Elektronik yang dibuat, diteruskan, dikirimkan, diterima, atau disimpan, dalam bentuk analog, digital, elektromagnetik, optikal, atau sejenisnya, yang dapat dilihat, ditampilkan, dan/atau didengar melalui komputer atau sistem elektronik, tetapi tidak terbatas pada tulisan, suara, gambar, peta, rancangan, foto, atau sejenisnya, huruf, tanda, angka, kode akses, simbol, atau perforasi yang memiliki makna atau arti atau dapat dipahami oleh orang yang mampu memahaminya.
10. 11.
12. 13.
Meterai adalah label atau carik dalam bentuk tempel, elektronik, atau bentuk lainnya yang memiliki ciri dan mengandung unsur pengaman yang dikeluarkan oleh Pemerintah Republik Indonesia, yang digunakan untuk membayar pajak atas dokumen.
Meterai Elektronik adalah Meterai berupa label yang penggunaannya dilakukan dengan cara dibubuhkan pada dokumen melalui sistem tertentu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1482, '8. Informasi Elektronik adalah satu atau sekumpulan data elektronik, tetapi tidak terbatas pada tulisan, suara, gambar, peta, rancangan, foto, Electronic Data Interchange (EDI), surat elektronik (electronic mail), telegram, teleks, telecopy, atau sejenisnya, huruf, tanda, angka, kode akses, simbol, atau perforasi yang telah diolah yang memiliki arti atau dapat dipahami oleh orang yang mampu memahaminya.
9. Dokumen Elektronik adalah setiap Informasi Elektronik yang dibuat, diteruskan, dikirimkan, diterima, atau disimpan, dalam bentuk analog, digital, elektromagnetik, optikal, atau sejenisnya, yang dapat dilihat, ditampilkan, dan/atau didengar melalui komputer atau sistem elektronik, tetapi tidak terbatas pada tulisan, suara, gambar, peta, rancangan, foto, atau sejenisnya, huruf, tanda, angka, kode akses, simbol, atau perforasi yang memiliki makna atau arti atau dapat dipahami oleh orang yang mampu memahaminya.
10. 11.
