INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1526, 'pedoman-1-2025', 21, 'lain', 'BAB V', NULL, 13, 'PENUTUP Pedoman Pemantuan Penyelesaian Tindak Lanjut Hasil Pemeriksaan dan Pengawasan ini digunakan sebagai acuan dalam pelaksanaan tindak lanjut hasil pemeriksaan dan pengawasan di lingkungan Badan Nasional Penanggulangan Bencana sehingga pelaksanaan dan penyelesaian tindak lanjut hasil pemeriksaan dan pengawasan dapat dilakukan secara efektif, efisien, dan akuntabel demi mewujudkan good governance dan clean govemmenit.
