INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1530, 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026', 'Judul', 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1531, 'pedoman-1-2026', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PEDOMAN PELAKSANAAN COACHING, MENTORING, DAN BELAJAR MANDIRI BAGI APARATUR SIPIL NEGARA DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 1 TAHUN 2026');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1531, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PEDOMAN PELAKSANAAN COACHING, MENTORING, DAN BELAJAR MANDIRI BAGI APARATUR SIPIL NEGARA DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 1 TAHUN 2026', 'Isi hal. 1', 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1532, 'pedoman-1-2026', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Dalam rangka memenuhi kebutuhan untuk meningkatkan kinerja, mengembangkan keterampilan, membangun potensi kepemimpinan, dan mendorong pertumbuhan individu serta organisasi di Lingkungan Badan Nasional Penanggulangan Bencana, maka perlu melakukan upaya pengembangan kompetensi yang sistematis. Berdasarkan Undang-Undang Nomor 20 Tahun 2023 tentang Aparatur Sipil Negara yang selanjutnya diatur pelaksananya melalui Peraturan Pemerintah Nomor 11 Tahun 2017 Tentang Manjemen Pegawai Negeri Sipil sebagaimana telah diubah dengan Peraturan Pemerintah Nomor 17 Tahun 2020 Tentang Perubahan Atas Peraturan Pemerintah Nomor 11 Tahun 2017 Tentang Manajemen Pegawai Negeri Sipil, bahwa Aparatur Sipil Negara memiliki hak mendapat pengembangan kompetensi 20 (dua puluh) Jam Pelajaran (JP) setahun. Kegiatan pengembangan kompetensi 20 (dua puluh) Jam Pelajaran (JP) setahun tersebut menerapkan konsep 10:20:70 pengembangan profesional yang terdiri dari 70Y6 pembelajaran terjadi melalui pengalaman kerja (tugas yang menantang dan pemecahan masalah), 20Y6 berasal dari interaksi dengan orang lain (umpan balik, panutan, dan kolaborasi), dan 10 diperoleh dari pendidikan dan pelatihan, berdasarkan komposisi tersebut dapat disimpulkan bahwa peranan atasan langsung dalam pengembangan kompetensi bawahannya sangat besar.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1532, 'PENDAHULUAN A. Latar Belakang Dalam rangka memenuhi kebutuhan untuk meningkatkan kinerja, mengembangkan keterampilan, membangun potensi kepemimpinan, dan mendorong pertumbuhan individu serta organisasi di Lingkungan Badan Nasional Penanggulangan Bencana, maka perlu melakukan upaya pengembangan kompetensi yang sistematis. Berdasarkan Undang-Undang Nomor 20 Tahun 2023 tentang Aparatur Sipil Negara yang selanjutnya diatur pelaksananya melalui Peraturan Pemerintah Nomor 11 Tahun 2017 Tentang Manjemen Pegawai Negeri Sipil sebagaimana telah diubah dengan Peraturan Pemerintah Nomor 17 Tahun 2020 Tentang Perubahan Atas Peraturan Pemerintah Nomor 11 Tahun 2017 Tentang Manajemen Pegawai Negeri Sipil, bahwa Aparatur Sipil Negara memiliki hak mendapat pengembangan kompetensi 20 (dua puluh) Jam Pelajaran (JP) setahun. Kegiatan pengembangan kompetensi 20 (dua puluh) Jam Pelajaran (JP) setahun tersebut menerapkan konsep 10:20:70 pengembangan profesional yang terdiri dari 70Y6 pembelajaran terjadi melalui pengalaman kerja (tugas yang menantang dan pemecahan masalah), 20Y6 berasal dari interaksi dengan orang lain (umpan balik, panutan, dan kolaborasi), dan 10 diperoleh dari pendidikan dan pelatihan, berdasarkan komposisi tersebut dapat disimpulkan bahwa peranan atasan langsung dalam pengembangan kompetensi bawahannya sangat besar.', 'BAB I', 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1533, 'pedoman-1-2026', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 2, 'Pengembangan kompetensi dilaksanakan agar Aparatur Sipil Negara semakin kompeten dan profesional dalam menjalankan tugas dan fungsinya dan pengembangan ini dilakukan berdasarkan pada hubungan kerja yang harmonis antara atasan langsung dengan bawahannya. Atasan dan bawahan harus selalu berkomunikasi dengan bawahan tentang tugas yang sedang dijalankan, target yang akan dicapai, dan kompetensi apa yang diperlukan untuk melaksanakan tugas dengan lebih efektif.
Komunikasi tentang pengembangan kompetensi fokus pada upaya pemenuhan kesenjangan kompetensi yang diketahui dari perbandingan antara kompetensi saat ini dengan standar kompetensi jabatan. Upaya pengembangan kompetensi sebagaimana dimaksud dilaksanakan melalui Coaching, Mentoring, dan Belajar Mandiri pelaksanaan secara umum akan menghasilakan antara lain:
1. Mengoptimalkan potensi diri,
2. Menggali kemampuan yang dimiliki pegawai, dan
3. Meningkatkan pengetahuan, keterampilan, dan kompetensi.
Mempertimbangkan hal tersebut diatas, maka perlu menetapkan Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.
B. Maksud dan Tujuan
1. Pedoman ini disusun dengan maksud sebagai acuan bagi pegawai dan atasan langsung dalam pelaksanaan kegiatan Coaching, Mentoring, dan Belajar Mandiri, sehingga penerapannya tepat sasaran dan berdampak langsung pada peningkatan kompetensi, kinerja, dan profesionalisme pegawai.
2. Pedoman ini disusun bertujuan untuk:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1533, 'Pengembangan kompetensi dilaksanakan agar Aparatur Sipil Negara semakin kompeten dan profesional dalam menjalankan tugas dan fungsinya dan pengembangan ini dilakukan berdasarkan pada hubungan kerja yang harmonis antara atasan langsung dengan bawahannya. Atasan dan bawahan harus selalu berkomunikasi dengan bawahan tentang tugas yang sedang dijalankan, target yang akan dicapai, dan kompetensi apa yang diperlukan untuk melaksanakan tugas dengan lebih efektif.
Komunikasi tentang pengembangan kompetensi fokus pada upaya pemenuhan kesenjangan kompetensi yang diketahui dari perbandingan antara kompetensi saat ini dengan standar kompetensi jabatan. Upaya pengembangan kompetensi sebagaimana dimaksud dilaksanakan melalui Coaching, Mentoring, dan Belajar Mandiri pelaksanaan secara umum akan menghasilakan antara lain:
1. Mengoptimalkan potensi diri,
2. Menggali kemampuan yang dimiliki pegawai, dan
3. Meningkatkan pengetahuan, keterampilan, dan kompetensi.
Mempertimbangkan hal tersebut diatas, maka perlu menetapkan Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.
B. Maksud dan Tujuan
1. Pedoman ini disusun dengan maksud sebagai acuan bagi pegawai dan atasan langsung dalam pelaksanaan kegiatan Coaching, Mentoring, dan Belajar Mandiri, sehingga penerapannya tepat sasaran dan berdampak langsung pada peningkatan kompetensi, kinerja, dan profesionalisme pegawai.
2. Pedoman ini disusun bertujuan untuk:', 'BAB I (lanjutan 1)', 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1534, 'pedoman-1-2026', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, 'a. Memberikan kejelasan peran dan tanggung jawab pegawai dan atasan langsung dalam pelaksanaan Coaching, Mentoring, dan Belajar Mandiri, dan
23. b. Menjamin keterlaksanaan Coaching, Mentoring, dan Belajar Mandiri secara efektif, terarah, dan akuntabel melalui peran pembinaan atasan langsung.
C. Sasaran Sasaran ini adalah seluruh pegawai ASN di lingkungan Badan Nasional Penanggulangan Bencana untuk memahami konsep, tujuan, serta pelaksanaan kegiatan Coaching, Mentoring, dan Belajar Mandiri sebagai bagian dari pengembangan kompetensi ASN.
D. Asas
1. Asas komunikasi efektif, yaitu komunikasi yang dilakukan secara terbuka dan saling menghargai antara atasan dan pegawai untuk mendukung proses Coaching, Mentoring, serta mendorong pegawai belajar dan mengembangkan diri secara mandiri.
2. Asas tujuan yang jelas dan terukur, yaitu setiap kegiatan Coaching, Mentoring, dan Belajar Mandiri memiliki tujuan yang jelas sehingga pegawai memahami arah pengembangan diri dan dapat memantau kemajuan yang dicapai.
3. Asas pemberdayaan dan akuntabilitas, yaitu pegawai didorong untuk aktif mengembangkan kompetensinya, sementara atasan berperan memberikan dukungan dan memastikan hasil pengembangan dapat dipertanggungjawabkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1534, 'a. Memberikan kejelasan peran dan tanggung jawab pegawai dan atasan langsung dalam pelaksanaan Coaching, Mentoring, dan Belajar Mandiri, dan
23. b. Menjamin keterlaksanaan Coaching, Mentoring, dan Belajar Mandiri secara efektif, terarah, dan akuntabel melalui peran pembinaan atasan langsung.
C. Sasaran Sasaran ini adalah seluruh pegawai ASN di lingkungan Badan Nasional Penanggulangan Bencana untuk memahami konsep, tujuan, serta pelaksanaan kegiatan Coaching, Mentoring, dan Belajar Mandiri sebagai bagian dari pengembangan kompetensi ASN.
D. Asas
1. Asas komunikasi efektif, yaitu komunikasi yang dilakukan secara terbuka dan saling menghargai antara atasan dan pegawai untuk mendukung proses Coaching, Mentoring, serta mendorong pegawai belajar dan mengembangkan diri secara mandiri.
2. Asas tujuan yang jelas dan terukur, yaitu setiap kegiatan Coaching, Mentoring, dan Belajar Mandiri memiliki tujuan yang jelas sehingga pegawai memahami arah pengembangan diri dan dapat memantau kemajuan yang dicapai.
3. Asas pemberdayaan dan akuntabilitas, yaitu pegawai didorong untuk aktif mengembangkan kompetensinya, sementara atasan berperan memberikan dukungan dan memastikan hasil pengembangan dapat dipertanggungjawabkan.', 'BAB I (lanjutan 2)', 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1535, 'pedoman-1-2026', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 3, 'E. Ruang Lingkup Ruang lingkup pedoman ini mencakup mengenai pelaksanaan, monitoring dan evaluasi kegiatan Coaching, Mentoring, dan Belajar Mandiri yang ditujukan kepada seluruh pegawai, atasan langsung, pimpinan unit kerja di lingkungan Badan Nasional Penanggulangan Bencana (BNPB), serta pihak lain yang memiliki keahlian di bidang yang dibutuhkan.
F. Pengertian Umum
1. Pembelajaran Coaching, Mentoring, dan Belajar Mandiri adalah pengembangan yang harus dilakukan oleh pegawai Badan Nasional Penanggulangan Bencana dalam rangka meningkatkan kompetensi berupa pengetahuan, keterampilan, dan sikap/perilaku seorang pegawai yang diamati, diukur, dan dikembangkan dalam melaksanakan tugasnya.
Coaching adalah pembimbingan peningkatan kinerja melalui pembekalan kemampuan memecahkan permasalahan dengan mengoptimalkan potensi diri.
Coach adalah atasan langsung dalam satu unit kerja yang bertaggung jawab untuk melakukan aktivitas coaching kepada bawahannya.
Coachee adalah ASN di Lingkungan Badan Nasional Penanggulangan Bencana yang membutuhkan bimbingan dan arahan terkait permasalahan dengan penyelesaian pekerjaan.
Mentoring adalah pembimbingan peningkatan kinerja melalui transfer pengetahuan, pengalaman, dan keterampilan dari orang yang lebih berpengalaman pada bidang yang sama yang dapat diperankan oleh atasan langsung, pegawai lain, atau pihak lain yang memiliki keahlian di bidang yang dibutuhkan oleh peserta mentoring.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1535, 'E. Ruang Lingkup Ruang lingkup pedoman ini mencakup mengenai pelaksanaan, monitoring dan evaluasi kegiatan Coaching, Mentoring, dan Belajar Mandiri yang ditujukan kepada seluruh pegawai, atasan langsung, pimpinan unit kerja di lingkungan Badan Nasional Penanggulangan Bencana (BNPB), serta pihak lain yang memiliki keahlian di bidang yang dibutuhkan.
F. Pengertian Umum
1. Pembelajaran Coaching, Mentoring, dan Belajar Mandiri adalah pengembangan yang harus dilakukan oleh pegawai Badan Nasional Penanggulangan Bencana dalam rangka meningkatkan kompetensi berupa pengetahuan, keterampilan, dan sikap/perilaku seorang pegawai yang diamati, diukur, dan dikembangkan dalam melaksanakan tugasnya.
Coaching adalah pembimbingan peningkatan kinerja melalui pembekalan kemampuan memecahkan permasalahan dengan mengoptimalkan potensi diri.
Coach adalah atasan langsung dalam satu unit kerja yang bertaggung jawab untuk melakukan aktivitas coaching kepada bawahannya.
Coachee adalah ASN di Lingkungan Badan Nasional Penanggulangan Bencana yang membutuhkan bimbingan dan arahan terkait permasalahan dengan penyelesaian pekerjaan.
Mentoring adalah pembimbingan peningkatan kinerja melalui transfer pengetahuan, pengalaman, dan keterampilan dari orang yang lebih berpengalaman pada bidang yang sama yang dapat diperankan oleh atasan langsung, pegawai lain, atau pihak lain yang memiliki keahlian di bidang yang dibutuhkan oleh peserta mentoring.', 'BAB I (lanjutan 3)', 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1536, 'pedoman-1-2026', 6, 'lain', 'BAB I (lanjutan 4)', NULL, 4, 'Mentor adalah seseorang yang memenuhi persyaratan untuk membimbing dan mengembangkan kompetensi mentee sehingga dapat menyelesaikan pekerjaannya.
Mentee adalah Peserta Mentoring, ASN di Lingkungan Badan Nasional Penanggulangan Bencana yang membutuhkan bimbingan dan arahan dalam pencapaian kinerja dan pengembangan diri.
Belajar Mandiri adalah upaya pegawai untuk mengembangkan kompetensinya secara mandiri melalui proses belajar dengan memanfaatkan sumber pembelajaran yang tersedia untuk meningkatkan kemampuan dalam menyelesaikan tugas sesuai dengan yang dipersyaratkan oleh nama jabatannya agar terwujudnya peningkatan pengetahuan, keterampilan, dan sikap dalam penyelesaian tugas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1536, 'Mentor adalah seseorang yang memenuhi persyaratan untuk membimbing dan mengembangkan kompetensi mentee sehingga dapat menyelesaikan pekerjaannya.
Mentee adalah Peserta Mentoring, ASN di Lingkungan Badan Nasional Penanggulangan Bencana yang membutuhkan bimbingan dan arahan dalam pencapaian kinerja dan pengembangan diri.
Belajar Mandiri adalah upaya pegawai untuk mengembangkan kompetensinya secara mandiri melalui proses belajar dengan memanfaatkan sumber pembelajaran yang tersedia untuk meningkatkan kemampuan dalam menyelesaikan tugas sesuai dengan yang dipersyaratkan oleh nama jabatannya agar terwujudnya peningkatan pengetahuan, keterampilan, dan sikap dalam penyelesaian tugas.', 'BAB I (lanjutan 4)', 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1537, 'pedoman-1-2026', 7, 'lain', 'BAB II', NULL, 5, 'PELAKSANAAN COACHING, MENTORING, DAN BELAJAR MANDIRI Untuk pelaksanaan Coaching, Mentoring, dan Belajar Mandiri bagi pegawai di lingkungan Badan Nasional Penanggulangan Bencana disampaikan ketentuan sebagai berikut:
A. Pelaksanaan
1. Setiap pegawai wajib memenuhi pengembangan kompetensi dengan jumlah 20 (dua puluh) JP dalam 1 (satu) tahun melalui pembelajaran nonklasikal berupa Coaching, Mentoring, dan Belajar Mandiri.
2. Sebelum melaksanakan Coaching, Mentoring, dan Belajar Mandiri pegawai menentukan area pengembangan yang akan dilaksanakan.
3. Pegawai melaksanakan dan menyelesaikan Coaching, Mentoring, dan Belajar Mandiri sesuai jadwal yang telah disepakati dengan atasan langsung dengan penuh tanggung jawab.
4. Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri dapat dilaksanakan melalui metode luring dan/atau daring, yang disertai dengan bukti hasil resume dan dokumentasi kegiatan yang dapat dipertanggungjawabkan kebenarannya.
5. Pelaksanan Coaching, Mentoring, dan Belajar Mandiri tersebut dibuktikan dengan pengisian formulir. Format-1 formulir mentoring sesuai dengan lampiran. Format-2 formulir Coaching sesuai dengan lampiran. Format-3 formulir Belajar Mandiri sesuai dengan lampiran.
6. Pegawai menyerahkan formulir hasil kegiatan Coaching, Mentoring, dan Belajar Mandiri kepada pimpinan unit kerja dan kemudian diserahkan ke Biro Sumber daya Manusia dan Umum.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1537, 'PELAKSANAAN COACHING, MENTORING, DAN BELAJAR MANDIRI Untuk pelaksanaan Coaching, Mentoring, dan Belajar Mandiri bagi pegawai di lingkungan Badan Nasional Penanggulangan Bencana disampaikan ketentuan sebagai berikut:
A. Pelaksanaan
1. Setiap pegawai wajib memenuhi pengembangan kompetensi dengan jumlah 20 (dua puluh) JP dalam 1 (satu) tahun melalui pembelajaran nonklasikal berupa Coaching, Mentoring, dan Belajar Mandiri.
2. Sebelum melaksanakan Coaching, Mentoring, dan Belajar Mandiri pegawai menentukan area pengembangan yang akan dilaksanakan.
3. Pegawai melaksanakan dan menyelesaikan Coaching, Mentoring, dan Belajar Mandiri sesuai jadwal yang telah disepakati dengan atasan langsung dengan penuh tanggung jawab.
4. Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri dapat dilaksanakan melalui metode luring dan/atau daring, yang disertai dengan bukti hasil resume dan dokumentasi kegiatan yang dapat dipertanggungjawabkan kebenarannya.
5. Pelaksanan Coaching, Mentoring, dan Belajar Mandiri tersebut dibuktikan dengan pengisian formulir. Format-1 formulir mentoring sesuai dengan lampiran. Format-2 formulir Coaching sesuai dengan lampiran. Format-3 formulir Belajar Mandiri sesuai dengan lampiran.
6. Pegawai menyerahkan formulir hasil kegiatan Coaching, Mentoring, dan Belajar Mandiri kepada pimpinan unit kerja dan kemudian diserahkan ke Biro Sumber daya Manusia dan Umum.', 'BAB II', 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1538, 'pedoman-1-2026', 8, 'lain', 'BAB II (lanjutan 1)', NULL, 5, '7. Biro Sumber Daya Manusia dan Umum melalui penyelenggaraan fungsi penyiapan koordinasi pelaksanaan urusan sumber daya manusia melaksanakan:
a. verifikasi/validasi hasil Coaching, Mentoring, dan Belajar Mandiri,
b. input data kedalam database pengembangan kompetensi, dan
c. melaporkan secara berkala kepada Sekretaris Utama.
8. Atasan langsung dan Biro SDM dan Umum memantau dan memberikan dukungan kepada pegawai yang melaksanakan Coaching, Mentoring, dan Belajar mandiri.
9. Pimpinan unit kerja berkoordinasi dengan Biro Sumber Daya manusia dan Umum untuk monitoring dan evaluasi pelaksanaan Coaching, Mentoring, dan Belajar Mandiri .
10. Pegawai dapat melaksanakan kegiatan Coaching, Mentoring, dan/atau Belajar Mandiri paling sedikit satu kali dalam satu bulan.
B. Coaching
1. Tata cara Coaching
a. Atasan langsung melakukan kesepakatan (konsensus) dengan pegawai untuk memulai proses Coaching terhadap pelaksanaan suatu kegiatan spesifik.
b. Atasan langsung dan pegawai menyamakan persepsi tentang tujuan dan sasaran yang ingin dicapai dari kegiatan.
c. Atasan langsung melakukan Coaching terhadap pegawai dengan perhitungan sebagai berikut:
1) 1 (satu) kali pertemuan setara dengan 2 (dua) JP, dan 2) Coaching paling tinggi dihitung 2 (dua) kali dalam 1 (satu) bulan.
d. Pimpinan unit kerja mendokumentasikan kegiatan selama proses Coaching.
2. Tugas Coach
a. Membantu pegawai untuk melihat tujuan pekerjaan jangka pendek yang akan dicapai dan hasil kinerja yang akan diperoleh (outcome).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1538, '7. Biro Sumber Daya Manusia dan Umum melalui penyelenggaraan fungsi penyiapan koordinasi pelaksanaan urusan sumber daya manusia melaksanakan:
a. verifikasi/validasi hasil Coaching, Mentoring, dan Belajar Mandiri,
b. input data kedalam database pengembangan kompetensi, dan
c. melaporkan secara berkala kepada Sekretaris Utama.
8. Atasan langsung dan Biro SDM dan Umum memantau dan memberikan dukungan kepada pegawai yang melaksanakan Coaching, Mentoring, dan Belajar mandiri.
9. Pimpinan unit kerja berkoordinasi dengan Biro Sumber Daya manusia dan Umum untuk monitoring dan evaluasi pelaksanaan Coaching, Mentoring, dan Belajar Mandiri .
10. Pegawai dapat melaksanakan kegiatan Coaching, Mentoring, dan/atau Belajar Mandiri paling sedikit satu kali dalam satu bulan.
B. Coaching
1. Tata cara Coaching
a. Atasan langsung melakukan kesepakatan (konsensus) dengan pegawai untuk memulai proses Coaching terhadap pelaksanaan suatu kegiatan spesifik.
b. Atasan langsung dan pegawai menyamakan persepsi tentang tujuan dan sasaran yang ingin dicapai dari kegiatan.
c. Atasan langsung melakukan Coaching terhadap pegawai dengan perhitungan sebagai berikut:
1) 1 (satu) kali pertemuan setara dengan 2 (dua) JP, dan 2) Coaching paling tinggi dihitung 2 (dua) kali dalam 1 (satu) bulan.
d. Pimpinan unit kerja mendokumentasikan kegiatan selama proses Coaching.
2. Tugas Coach
a. Membantu pegawai untuk melihat tujuan pekerjaan jangka pendek yang akan dicapai dan hasil kinerja yang akan diperoleh (outcome).', 'BAB II (lanjutan 1)', 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1539, 'pedoman-1-2026', 9, 'lain', 'BAB II (lanjutan 2)', NULL, 6, 'b. Membangun kesepakatan dengan pegawai untuk bekerja sama dalam mencapai tujuan dan hasil kinerja.
c. Membimbing dan mengarahkan sikap serta perilaku pegawai dalam mempercepat pencapaian tujuan dan hasil kinerja.
d. Memotivasi pegawai untuk meningkatkan kompetensi demi terciptanya ide baru dan inovasi yang berguna dalam menyelesaikan pekerjaan.
e. Membimbing pegawai dalam mengurai permasalahan dan mengembangkan alternatif solusi sebagai dasar untuk pengambilan keputusan.
f. Mengajak pegawai untuk berpikir, membuka wawasan, merumuskan gagasan/ide, dan menstrukturkan narasinya.
g. Memberi masukan, umpan balik, dan saran untuk memperkaya dan mempertajam gagasan pegawai.
h. Memastikan pegawai melaksanakan apa yang telah diperolehnya dari hasil Coaching.
3. Peran Coach
a. Dalam pelaksanaannya Coach juga berperan sebagai mitra kerja (partner) yang memberdayakan pegawai agar bisa mengaktualisasikan potensinya.
b. Sebagai penjamin mutu (guality assurance) yang melakukan proses pemantauan dan evaluasi atas kinerja pegawai.
c. Sebagai mediator yang menjadi penjembatan komunikasi antara pegawai dengan atasan dari atasan langsung.
4. Konversi Jam Pelajaran (JP) Kegiatan | Satuan Konversi JP Coaching | Kegiatan |a. 1 (satu) kali pertemuan setara dengan 2 (dua) JP.
b. Paling tinggi dihitung 2 (dua) kali dalam 1 (satu) bulan.
C. Mentoring
1. Tata cara Mentoring
a. Mentee dapat mengajukan permohonan mentoring kepada atasan langsung atau pihak lain yang bukan atasan langsungnya.');
