INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1543, 'pedoman-1-2026', 13, 'lain', 'BAB III', NULL, 11, 'MONITORING DAN EVALUASI Monitoring dan evaluasi dalam pelaksanaan Coaching, Mentoring, dan Belajar Mandiri merupakan bagian yang tidak terpisahkan dari manajemen pengembangan sumber daya manusia yang berfungsi untuk menjamin terpenuhinya hak dan kewajiban pegawai dalam pengembangan kompetensi melalui Coaching, Mentoring, dan Belajar Mandiri, serta memastikan perencanaan, pelaksanaan, pencatatan, dan pelaporannya dilaksanakan secara akuntabel oleh unit kerja.
A. Gambaran Umum
1. Monitoring merupakan kegiatan pengamatan, pencatatan, dan pengendalian yang dilakukan secara berkelanjutan terhadap pelaksanaan pengembangan kompetensi pegawai melalui Coaching, Mentoring, dan Belajar Mandiri.
2. Evaluasi merupakan kegiatan penilaian yang dilakukan secara periodik untuk mengukur ketercapaian tujuan, efektivitas pelaksanaan, serta hasil pengembangan kompetensi pegawai.
3. Pengembangan kompetensi pegawai melalui Coaching, Mentoring, dan Belajar Mandiri dilaksanakan untuk memenuhi kebutuhan peningkatan kompetensi teknis, manajerial, dan sosial kultural pegawai sesuai dengan standar kompetensi jabatan.
4. Monitoring dan evaluasi pelaksanaan Coaching, Mentoring, dan Belajar Mandiri dilaksanakan 2 (dua) kali dalam 1 (satu) tahun.
Monitoring dilakukan untuk memastikan keterlaksanaan kegiatan sesuai ketentuan, sedangkan evaluasi dilakukan untuk menilai efektivitas pelaksanaan serta capaian pengembangan kompetensi pegawai, termasuk pemenuhan 20 (dua puluh) JP dalam 1 (satu) tahun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1543, 'MONITORING DAN EVALUASI Monitoring dan evaluasi dalam pelaksanaan Coaching, Mentoring, dan Belajar Mandiri merupakan bagian yang tidak terpisahkan dari manajemen pengembangan sumber daya manusia yang berfungsi untuk menjamin terpenuhinya hak dan kewajiban pegawai dalam pengembangan kompetensi melalui Coaching, Mentoring, dan Belajar Mandiri, serta memastikan perencanaan, pelaksanaan, pencatatan, dan pelaporannya dilaksanakan secara akuntabel oleh unit kerja.
A. Gambaran Umum
1. Monitoring merupakan kegiatan pengamatan, pencatatan, dan pengendalian yang dilakukan secara berkelanjutan terhadap pelaksanaan pengembangan kompetensi pegawai melalui Coaching, Mentoring, dan Belajar Mandiri.
2. Evaluasi merupakan kegiatan penilaian yang dilakukan secara periodik untuk mengukur ketercapaian tujuan, efektivitas pelaksanaan, serta hasil pengembangan kompetensi pegawai.
3. Pengembangan kompetensi pegawai melalui Coaching, Mentoring, dan Belajar Mandiri dilaksanakan untuk memenuhi kebutuhan peningkatan kompetensi teknis, manajerial, dan sosial kultural pegawai sesuai dengan standar kompetensi jabatan.
4. Monitoring dan evaluasi pelaksanaan Coaching, Mentoring, dan Belajar Mandiri dilaksanakan 2 (dua) kali dalam 1 (satu) tahun.
Monitoring dilakukan untuk memastikan keterlaksanaan kegiatan sesuai ketentuan, sedangkan evaluasi dilakukan untuk menilai efektivitas pelaksanaan serta capaian pengembangan kompetensi pegawai, termasuk pemenuhan 20 (dua puluh) JP dalam 1 (satu) tahun.', 'BAB III', 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1544, 'pedoman-1-2026', 14, 'lain', 'BAB III (lanjutan 1)', NULL, 11, '5. Pimpinan Unit Kerja bertanggung jawab untuk melaksanakan monitoring dan evaluasi.
6. Monitoring dan Evaluasi dilaksanakan dengan prinsip objektif, transparan, akuntabel, dan berkesinambungan.
B. Penyelenggaraan Monitoring dan Evaluasi
1. Monitoring pelaksanaan Coaching, Mentoring, dan Belajar Mandiri dilakukan oleh atasan langsung untuk memastikan kesesuaian pelaksanaan Coaching dengan rencana pengembangan kompetensi pegawai.
2. Evaluasi Coaching, Mentoring, dan Belajar Mandiri dilakukan untuk menilai efektivitas proses Coaching, ketercapaian tujuan pembelajaran, serta kontribusinya terhadap peningkatan pegawai.
3. pimpinan unit kerja melaksanakan monitoring dan evaluasi, selanjutnya pelaksanaan Coaching, Mentoring, dan Belajar Mandiri dilaksanakan melalui pencatatan pada kartu pengendali. Format- 4 Kartu Pengendalian Pengembangan Kompetensi Melalui Coaching, Mentoring, dan Belajar Mandiri.
4. Kartu pengendali sebagaimana dimaksud pada angka 4 (empat) dibuat sesuai dengan format sebagaimana tercantum dalam format-4 Lampiran pedoman ini dan diisi oleh pegawai yang bersangkutan serta di verifikasi oleh pimpinan unit kerja.
5. Pimpinan unit kerja wajib menyampaikan hasil rekapitulasi kartu pengendali pengembagan kompetensi kepada Biro Sumber Daya Manusia dan Umum setiap 3 (tiga) bulan sekali. Format-5 Rekapitulasi Pelaksanaan Pengembangan Kompetensi Melalui Coaching, Mentoring, dan Belajar Mandiri.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1544, '5. Pimpinan Unit Kerja bertanggung jawab untuk melaksanakan monitoring dan evaluasi.
6. Monitoring dan Evaluasi dilaksanakan dengan prinsip objektif, transparan, akuntabel, dan berkesinambungan.
B. Penyelenggaraan Monitoring dan Evaluasi
1. Monitoring pelaksanaan Coaching, Mentoring, dan Belajar Mandiri dilakukan oleh atasan langsung untuk memastikan kesesuaian pelaksanaan Coaching dengan rencana pengembangan kompetensi pegawai.
2. Evaluasi Coaching, Mentoring, dan Belajar Mandiri dilakukan untuk menilai efektivitas proses Coaching, ketercapaian tujuan pembelajaran, serta kontribusinya terhadap peningkatan pegawai.
3. pimpinan unit kerja melaksanakan monitoring dan evaluasi, selanjutnya pelaksanaan Coaching, Mentoring, dan Belajar Mandiri dilaksanakan melalui pencatatan pada kartu pengendali. Format- 4 Kartu Pengendalian Pengembangan Kompetensi Melalui Coaching, Mentoring, dan Belajar Mandiri.
4. Kartu pengendali sebagaimana dimaksud pada angka 4 (empat) dibuat sesuai dengan format sebagaimana tercantum dalam format-4 Lampiran pedoman ini dan diisi oleh pegawai yang bersangkutan serta di verifikasi oleh pimpinan unit kerja.
5. Pimpinan unit kerja wajib menyampaikan hasil rekapitulasi kartu pengendali pengembagan kompetensi kepada Biro Sumber Daya Manusia dan Umum setiap 3 (tiga) bulan sekali. Format-5 Rekapitulasi Pelaksanaan Pengembangan Kompetensi Melalui Coaching, Mentoring, dan Belajar Mandiri.', 'BAB III (lanjutan 1)', 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1545, 'pedoman-1-2026', 15, 'lain', 'BAB III (lanjutan 2)', NULL, 12, '6. Evaluasi digunakan sebagai dasar pengambilan keputusan dalam perencanaan dan tindak lanjut pengembangan kompetensi pegawai.
7. Apabila terdapat pegawai yang belum terpenuhi atau dianggap tidak akan tercapai pengembangan kompetensinya, pimpinan unit kerja dapat menugaskan pegawai yang bersangkutan dalam kegiatan workshop/ sosialisasi/pelatihan dan atau dapat meminta atasan langsung pegawai tersebut/pegawai yang bersangkutan untuk melaksanakan kegiatan Coaching, Mentoring, dan Belajar Mandiri.
8. Pimpinan unit kerja melakukan monitoring dan evaluasi pelaksanaan Coaching pegawai yang dilakukan 2 (dua) kali dalam 1 (satu) tahun dan dalam 1 tahun wajib telah mendapatkan 20 (dua puluh) JP.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1545, '6. Evaluasi digunakan sebagai dasar pengambilan keputusan dalam perencanaan dan tindak lanjut pengembangan kompetensi pegawai.
7. Apabila terdapat pegawai yang belum terpenuhi atau dianggap tidak akan tercapai pengembangan kompetensinya, pimpinan unit kerja dapat menugaskan pegawai yang bersangkutan dalam kegiatan workshop/ sosialisasi/pelatihan dan atau dapat meminta atasan langsung pegawai tersebut/pegawai yang bersangkutan untuk melaksanakan kegiatan Coaching, Mentoring, dan Belajar Mandiri.
8. Pimpinan unit kerja melakukan monitoring dan evaluasi pelaksanaan Coaching pegawai yang dilakukan 2 (dua) kali dalam 1 (satu) tahun dan dalam 1 tahun wajib telah mendapatkan 20 (dua puluh) JP.', 'BAB III (lanjutan 2)', 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1546, 'pedoman-1-2026', 16, 'lain', 'BAB IV', NULL, 13, 'PENUTUP Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri ini disusun sebagai acuan bagi seluruh pegawai dan pimpinan di lingkungan Badan Nasional Penanggulangan Bencana dalam melaksanakan pengembangan kompetensi secara terarah dan berkelanjutan. Melalui pelaksanaan pedoman ini, diharapkan setiap pegawai mampu mengoptimalkan potensi diri, meningkatkan kinerja, serta menumbuhkan budaya belajar yang adaptif dan kolaboratif di lingkungan kerja.
Ditetapkan di Jakarta pada tanggal 25 Februari 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro KAN sanisasi dan Kerja Sama,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1546, 'PENUTUP Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri ini disusun sebagai acuan bagi seluruh pegawai dan pimpinan di lingkungan Badan Nasional Penanggulangan Bencana dalam melaksanakan pengembangan kompetensi secara terarah dan berkelanjutan. Melalui pelaksanaan pedoman ini, diharapkan setiap pegawai mampu mengoptimalkan potensi diri, meningkatkan kinerja, serta menumbuhkan budaya belajar yang adaptif dan kolaboratif di lingkungan kerja.
Ditetapkan di Jakarta pada tanggal 25 Februari 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro KAN sanisasi dan Kerja Sama,', 'BAB IV', 'Pedoman Pelaksanaan Coaching, Mentoring, dan Belajar Mandiri Bagi Aparatur Sipil Negara di Lingkungan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026');
