INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1548, 'pedoman-2-2024', 0, 'judul', 'Judul', NULL, 1, 'Pedoman Kepala BNPB Nomor 2 Tahun 2024 tentang Pelaksanaan Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1548, 'Pedoman Kepala BNPB Nomor 2 Tahun 2024 tentang Pelaksanaan Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana', 'Judul', 'Pedoman Kepala BNPB Nomor 2 Tahun 2024 tentang Pelaksanaan Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1549, 'pedoman-2-2024', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PEDOMAN PELAKSANAAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 2 TAHUN 2024');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1549, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PEDOMAN PELAKSANAAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 2 TAHUN 2024', 'Isi hal. 1', 'Pedoman Kepala BNPB Nomor 2 Tahun 2024 tentang Pelaksanaan Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1550, 'pedoman-2-2024', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Dalam rangka untuk melaksanakan ketentuan Peraturan Menteri Keuangan Nomor 20 Tahun 2023 tentang Perubahan Atas Peraturan Menteri Keuangan Nomor 80/PMK.05/2017 tentang Tata Cara Pembayaran Tunjangan Kinerja Pegawai Pada Kementerian Negara/Lembaga, bahwa mekanisme pembayaran tunjangan kinerja wajib dibayarkan pada setiap hari pertama atau hari kerja pertama kerja setiap bulan.
Bahwa untuk menjelaskan lebih lanjut mengenai mekanisme pembayaran tunjangan kinerja di lingkungan Badan Nasional Penanggulangan Bencana, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana perlu dibentuk Pedoman Pelaksanaan Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.
B. Maksud dan Tujuan
1. Pedoman ini dimaksudkan sebagai acuan dalam pembayaran tunjangan kinerja bagi pegawai di lingkungan Badan Nasional Penanggulangan Bencana.
2. Tujuan dari pedoman ini adalah menyediakan mekanisme pembayaran tunjangan kinerja agar dapat dilaksanakan secara akuntabel.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1550, 'PENDAHULUAN A. Latar Belakang Dalam rangka untuk melaksanakan ketentuan Peraturan Menteri Keuangan Nomor 20 Tahun 2023 tentang Perubahan Atas Peraturan Menteri Keuangan Nomor 80/PMK.05/2017 tentang Tata Cara Pembayaran Tunjangan Kinerja Pegawai Pada Kementerian Negara/Lembaga, bahwa mekanisme pembayaran tunjangan kinerja wajib dibayarkan pada setiap hari pertama atau hari kerja pertama kerja setiap bulan.
Bahwa untuk menjelaskan lebih lanjut mengenai mekanisme pembayaran tunjangan kinerja di lingkungan Badan Nasional Penanggulangan Bencana, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana perlu dibentuk Pedoman Pelaksanaan Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.
B. Maksud dan Tujuan
1. Pedoman ini dimaksudkan sebagai acuan dalam pembayaran tunjangan kinerja bagi pegawai di lingkungan Badan Nasional Penanggulangan Bencana.
2. Tujuan dari pedoman ini adalah menyediakan mekanisme pembayaran tunjangan kinerja agar dapat dilaksanakan secara akuntabel.', 'BAB I', 'Pedoman Kepala BNPB Nomor 2 Tahun 2024 tentang Pelaksanaan Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1551, 'pedoman-2-2024', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'C. Sasaran Sasaran Pedoman ini adalah unit kerja yang mempunyai tugas di bidang pelaksanaan koordinasi, pengelolaan, dan pelaksanaan anggaran di lingkungan Badan Nasional Penanggulangan Bencana dan unit kerja yang mempunyai tugas di bidang pelaksanaan koordinasi urusan sumber daya manusia, rumah tangga, tata usaha, keprotokolan, dan barang milik/kekayaan Negara di lingkungan Badan Nasional Penanggulangan Bencana.
D. Asas Sesuai dengan Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara, pembayaran tunjangan kinerja pegawai di lingkungan Badan Nasional Penanggulangan Bencana dilaksanakan dengan asas:
1. asas kesatuan;
2. asas universalitas;
3. asas tahunan; dan
4. asas spesialitas.
E. Ruang Lingkup Seluruh pegawai di lingkungan Badan Nasional Penanggulangan Bencana.
F. Pengertian Umum
1. Pegawai Negeri Sipil yang selanjutnya disingkat PNS adalah warga negara Indonesia yang memenuhi syarat tertentu, diangkat sebagai Pegawai Aparatur Sipil Negara secara tetap oleh pejabat Pembina Kepegawaian untuk menduduki jabatan pemerintahan.
2. Pegawai adalah Pegawai Negeri Sipil dan Pegawai lainnya yang berdasarkan keputusan pejabat yang berwenang diangkat dalam suatu jabatan atau ditugaskan dan bekerja secara penuh pada satuan organisasi di lingkungan Badan Nasional Penanggulangan Bencana.
3. Kelas Jabatan adalah tingkat jabatan struktural maupun jabatan fungsional dalam satuan organisasi negara yang digunakan sebagai dasar pemberian tunjangan kinerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1551, 'C. Sasaran Sasaran Pedoman ini adalah unit kerja yang mempunyai tugas di bidang pelaksanaan koordinasi, pengelolaan, dan pelaksanaan anggaran di lingkungan Badan Nasional Penanggulangan Bencana dan unit kerja yang mempunyai tugas di bidang pelaksanaan koordinasi urusan sumber daya manusia, rumah tangga, tata usaha, keprotokolan, dan barang milik/kekayaan Negara di lingkungan Badan Nasional Penanggulangan Bencana.
D. Asas Sesuai dengan Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara, pembayaran tunjangan kinerja pegawai di lingkungan Badan Nasional Penanggulangan Bencana dilaksanakan dengan asas:
1. asas kesatuan;
2. asas universalitas;
3. asas tahunan; dan
4. asas spesialitas.
E. Ruang Lingkup Seluruh pegawai di lingkungan Badan Nasional Penanggulangan Bencana.
F. Pengertian Umum
1. Pegawai Negeri Sipil yang selanjutnya disingkat PNS adalah warga negara Indonesia yang memenuhi syarat tertentu, diangkat sebagai Pegawai Aparatur Sipil Negara secara tetap oleh pejabat Pembina Kepegawaian untuk menduduki jabatan pemerintahan.
2. Pegawai adalah Pegawai Negeri Sipil dan Pegawai lainnya yang berdasarkan keputusan pejabat yang berwenang diangkat dalam suatu jabatan atau ditugaskan dan bekerja secara penuh pada satuan organisasi di lingkungan Badan Nasional Penanggulangan Bencana.
3. Kelas Jabatan adalah tingkat jabatan struktural maupun jabatan fungsional dalam satuan organisasi negara yang digunakan sebagai dasar pemberian tunjangan kinerja.', 'BAB I (lanjutan 1)', 'Pedoman Kepala BNPB Nomor 2 Tahun 2024 tentang Pelaksanaan Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1552, 'pedoman-2-2024', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, '4. Daftar Pembayaran Tunjangan Kinerja adalah daftar yang memuat nama, nomor induk pegawai, eselon, golongan/ruang, susunan keluarga, kelas jabatan, gaji, tunjangan kinerja, dan nomor rekening Pegawai penerima tunjangan kinerja.
5. Hari Libur Nasional adalah hari libur selain Sabtu dan Minggu yang ditetapkan secara resmi oleh Pemerintah.
6. Pejabat Penandatangan Surat Perintah Membayar yang selanjutnya disingkat PPSPM adalah pejabat yang diberi kewenangan oleh Pengguna Anggaran/Kuasa Pengguna Anggaran untuk melakukan pengujian atas permintaan pembayaran dan menerbitkan perintah pembayaran.
7. Kantor Pelayanan Perbendaharaan Negara yang selanjutnya disingkat KPPN adalah instansi vertikal Direktorat Jenderal Perbendaharaan yang memperoleh kuasa dari bendahara umum negara untuk melaksanakan sebagian fungsi kuasa bendahara umum negara.
8. Surat Perintah Membayar Langsung yang selanjutnya disebut SPM-LS adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan dana yang bersumber dari daftar isian pelaksanaan anggaran dalam rangka pembayaran tagihan kepada penerima hak/Bendahara Pengeluaran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1552, '4. Daftar Pembayaran Tunjangan Kinerja adalah daftar yang memuat nama, nomor induk pegawai, eselon, golongan/ruang, susunan keluarga, kelas jabatan, gaji, tunjangan kinerja, dan nomor rekening Pegawai penerima tunjangan kinerja.
5. Hari Libur Nasional adalah hari libur selain Sabtu dan Minggu yang ditetapkan secara resmi oleh Pemerintah.
6. Pejabat Penandatangan Surat Perintah Membayar yang selanjutnya disingkat PPSPM adalah pejabat yang diberi kewenangan oleh Pengguna Anggaran/Kuasa Pengguna Anggaran untuk melakukan pengujian atas permintaan pembayaran dan menerbitkan perintah pembayaran.
7. Kantor Pelayanan Perbendaharaan Negara yang selanjutnya disingkat KPPN adalah instansi vertikal Direktorat Jenderal Perbendaharaan yang memperoleh kuasa dari bendahara umum negara untuk melaksanakan sebagian fungsi kuasa bendahara umum negara.
8. Surat Perintah Membayar Langsung yang selanjutnya disebut SPM-LS adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan dana yang bersumber dari daftar isian pelaksanaan anggaran dalam rangka pembayaran tagihan kepada penerima hak/Bendahara Pengeluaran.', 'BAB I (lanjutan 2)', 'Pedoman Kepala BNPB Nomor 2 Tahun 2024 tentang Pelaksanaan Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1553, 'pedoman-2-2024', 5, 'lain', 'BAB II', NULL, 3, 'PELAKSANAAN Pembayaran tunjangan kinerja pegawai di lingkungan Badan Nasional Penanggulangan Bencana dilaksanakan dengan memperhatikan hal sebagai berikut:
1. Biro Sumber Daya Manusia dan Umum mengajukan permohonan pembayaran tunjangan kinerja pegawai kepada Sekretariat Utama u.p.
Biro Keuangan.
2. Pengajuan permohonan pembayaran tunjangan kinerja oleh Biro SDM dan Umum dilakukan dengan memperhatikan hal-hal sebagai berikut:
a. Kelas jabatan pegawai;
b. Pembayaran Tunjangan Kinerja dilaksanakan pada permulaan bulan;
c. Penghitungan Tunjangan Kinerja Pegawai dimulai pada tanggal 16 sampai dengan tanggal 15 bulan berikutnya; dan
d. Besaran pemotongan Tunjangan Kinerja sesuai dengan ketentuan peraturan perundang-undangan.
3. Permohonan pembayaran Tunjangan Kinerja wajib dilengkapi dengan Rekapitulasi Daftar Pembayaran Tunjangan Kinerja Pegawai. Format Rekapitulasi Daftar Pembayaran Tunjangan Kinerja Pegawai tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Pedoman ini.
4. Permohonan kekurangan pembayaran Tunjangan Kinerja wajib dilengkapi dengan Rekapitulasi Daftar Kekurangan Pembayaran Tunjangan Kinerja Pegawai. Format Rekapitulasi Daftar kekurangan Pembayaran Tunjangan Kinerja Pegawai tercantum dalam Lampiran II yang merupakan bagian tidak terpisahkan dari Pedoman ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1553, 'PELAKSANAAN Pembayaran tunjangan kinerja pegawai di lingkungan Badan Nasional Penanggulangan Bencana dilaksanakan dengan memperhatikan hal sebagai berikut:
1. Biro Sumber Daya Manusia dan Umum mengajukan permohonan pembayaran tunjangan kinerja pegawai kepada Sekretariat Utama u.p.
Biro Keuangan.
2. Pengajuan permohonan pembayaran tunjangan kinerja oleh Biro SDM dan Umum dilakukan dengan memperhatikan hal-hal sebagai berikut:
a. Kelas jabatan pegawai;
b. Pembayaran Tunjangan Kinerja dilaksanakan pada permulaan bulan;
c. Penghitungan Tunjangan Kinerja Pegawai dimulai pada tanggal 16 sampai dengan tanggal 15 bulan berikutnya; dan
d. Besaran pemotongan Tunjangan Kinerja sesuai dengan ketentuan peraturan perundang-undangan.
3. Permohonan pembayaran Tunjangan Kinerja wajib dilengkapi dengan Rekapitulasi Daftar Pembayaran Tunjangan Kinerja Pegawai. Format Rekapitulasi Daftar Pembayaran Tunjangan Kinerja Pegawai tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Pedoman ini.
4. Permohonan kekurangan pembayaran Tunjangan Kinerja wajib dilengkapi dengan Rekapitulasi Daftar Kekurangan Pembayaran Tunjangan Kinerja Pegawai. Format Rekapitulasi Daftar kekurangan Pembayaran Tunjangan Kinerja Pegawai tercantum dalam Lampiran II yang merupakan bagian tidak terpisahkan dari Pedoman ini.', 'BAB II', 'Pedoman Kepala BNPB Nomor 2 Tahun 2024 tentang Pelaksanaan Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1554, 'pedoman-2-2024', 6, 'lain', 'BAB II (lanjutan 1)', NULL, 3, '5. Permohonan pembayaran selisih Tunjangan Kinerja wajib dilengkapi dengan Rekapitulasi Daftar Pembayaran Selisih Tunjangan Kinerja Pegawai. Format Rekapitulasi Daftar Pembayaran Selisih Tunjangan Kinerja Pegawai tercantum dalam Lampiran III yang merupakan bagian tidak terpisahkan dari Pedoman ini.
6. Surat pernyataan tanggung jawab mutlak (SPTJM) ditandatangani oleh PPK. Fomat Surat Pernyataan Tanggung Jawab Mutlak tercantum dalam Lampiran IV yang merupakan bagian tidak terpisahkan dari Pedoman ini.
7. Sekretariat Utama u.p. Biro Keuangan menyalurkan dana Tunjangan Kinerja kepada pegawai yang berhak menerima pada hari pertama atau hari kerja pertama setiap bulan.
8. Untuk pembayaran Tunjangan Kinerja pada hari pertama bulan Januari tahun anggaran berikutnya, PPSPM mengajukan SPM-LS ke KPPN pada bulan Desember tahun anggaran berjalan yang dibebankan pada Daftar Isian Pelaksanaan Anggaran (DIPA) tahun anggaran berikutnya.
9. Mekanisme pencairan dana Tunjangan Kinerja dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1554, '5. Permohonan pembayaran selisih Tunjangan Kinerja wajib dilengkapi dengan Rekapitulasi Daftar Pembayaran Selisih Tunjangan Kinerja Pegawai. Format Rekapitulasi Daftar Pembayaran Selisih Tunjangan Kinerja Pegawai tercantum dalam Lampiran III yang merupakan bagian tidak terpisahkan dari Pedoman ini.
6. Surat pernyataan tanggung jawab mutlak (SPTJM) ditandatangani oleh PPK. Fomat Surat Pernyataan Tanggung Jawab Mutlak tercantum dalam Lampiran IV yang merupakan bagian tidak terpisahkan dari Pedoman ini.
7. Sekretariat Utama u.p. Biro Keuangan menyalurkan dana Tunjangan Kinerja kepada pegawai yang berhak menerima pada hari pertama atau hari kerja pertama setiap bulan.
8. Untuk pembayaran Tunjangan Kinerja pada hari pertama bulan Januari tahun anggaran berikutnya, PPSPM mengajukan SPM-LS ke KPPN pada bulan Desember tahun anggaran berjalan yang dibebankan pada Daftar Isian Pelaksanaan Anggaran (DIPA) tahun anggaran berikutnya.
9. Mekanisme pencairan dana Tunjangan Kinerja dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.', 'BAB II (lanjutan 1)', 'Pedoman Kepala BNPB Nomor 2 Tahun 2024 tentang Pelaksanaan Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1555, 'pedoman-2-2024', 7, 'lain', 'BAB III', NULL, 4, 'PENUTUP Pedoman Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana ini ditetapkan sebagai acuan di lingkungan Badan Nasional Penanggulangan Bencana dalam pelaksanaan pembayaran tunjangan kinerja pegawai secara efektif, efisien, dan akuntabel.
Ditetapkan di Jakarta pada tanggal 8 Mei 2024 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi dan Kerja Sama, Irma Dewi Rismayati');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1555, 'PENUTUP Pedoman Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana ini ditetapkan sebagai acuan di lingkungan Badan Nasional Penanggulangan Bencana dalam pelaksanaan pembayaran tunjangan kinerja pegawai secara efektif, efisien, dan akuntabel.
Ditetapkan di Jakarta pada tanggal 8 Mei 2024 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi dan Kerja Sama, Irma Dewi Rismayati', 'BAB III', 'Pedoman Kepala BNPB Nomor 2 Tahun 2024 tentang Pelaksanaan Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
