INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1563, '(6) Diisi dengan bulan dan tahun pembayaran tunjangan kinerja Pegawai Diisi dengan lokasi, tanggal, bulan, dan tahun penandatanganan surat
(7) pernyataan Diisi dengan jabatan Pejabat Pembuat Komitmen (PPK) penandatangan
(8) surat pernyataan
(9) Diisi dengan Tanda Tangan
(10) Diisi dengan nama lengkap penandatangan surat pernyataan
(11) Diisi dengan NIP pejabat penandatangan surat pernyataan KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi dan Kerja Sama, Irma Dewi Rismayati', 'LAMPIRAN IV (lanjutan 1)', 'Pedoman Kepala BNPB Nomor 2 Tahun 2024 tentang Pelaksanaan Pembayaran Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1564, 'pedoman-3-2024', 0, 'judul', 'Judul', NULL, 1, 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1564, 'Pedoman Sosialisasi Penanggulangan Bencana', 'Judul', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1565, 'pedoman-3-2024', 1, 'lain', 'Isi hal. 1', NULL, 1, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PEDOMAN SOSIALISASI PENANGGULANGAN BENCANA NOMOR 3 TAHUN 2024');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1565, 'SALINAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA PEDOMAN SOSIALISASI PENANGGULANGAN BENCANA NOMOR 3 TAHUN 2024', 'Isi hal. 1', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1566, 'pedoman-3-2024', 2, 'lain', 'BAB I', NULL, 1, 'PENDAHULUAN A. Latar Belakang Negara Kesatuan Republik Indonesia merupakan negara kepulauan yang terletak di zona geologi aktif, dan secara konsisten menghadapi ancaman bencana alam yang beragam dan kompleks. Dengan posisinya yang berada di Cincin Api Pasifik, Indonesia rentan terhadap berbagai jenis bencana seperti gempa bumi, tsunami, letusan gunung api, banjir, tanah longsor, dan cuaca ekstrem lainnya. Fenomena perubahan iklim, degradasi lingkungan, eksploitasi sumber daya alam, perkembangan infrastruktur dan ekonomi, serta meningkatnya kepadatan penduduk juga memengaruhi kejadian bencana di Indonesia. Dalam tiga belas tahun terakhir (2011 - 2023), kejadian bencana di Indonesia semakin sering terjadi (Gambar 1), dengan dampak yang semakin merusak, semakin luas, dan semakin kompleks penanganannya yang memengaruhi kehidupan sosial, ekonomi, dan lingkungan.
5.000 5.000 j Hoo 8 1 20 " 2014 1s 2016 2017 2018 2019 220 202 2022 2021 2011 2012 2013 @Oempa dan Trunami — WTewumi —@Laturan Gunung Api #Gempa Bumi“ Abrnsi Pantai #Kekaringan Kebakaran utan dan Lahan #Tarah Longsor « Cunca Eketrom — # Baniit Gambar 1. Tren kejadian bencana di Indonesia dari tahun 2011 — 2023.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1566, 'PENDAHULUAN A. Latar Belakang Negara Kesatuan Republik Indonesia merupakan negara kepulauan yang terletak di zona geologi aktif, dan secara konsisten menghadapi ancaman bencana alam yang beragam dan kompleks. Dengan posisinya yang berada di Cincin Api Pasifik, Indonesia rentan terhadap berbagai jenis bencana seperti gempa bumi, tsunami, letusan gunung api, banjir, tanah longsor, dan cuaca ekstrem lainnya. Fenomena perubahan iklim, degradasi lingkungan, eksploitasi sumber daya alam, perkembangan infrastruktur dan ekonomi, serta meningkatnya kepadatan penduduk juga memengaruhi kejadian bencana di Indonesia. Dalam tiga belas tahun terakhir (2011 - 2023), kejadian bencana di Indonesia semakin sering terjadi (Gambar 1), dengan dampak yang semakin merusak, semakin luas, dan semakin kompleks penanganannya yang memengaruhi kehidupan sosial, ekonomi, dan lingkungan.
5.000 5.000 j Hoo 8 1 20 " 2014 1s 2016 2017 2018 2019 220 202 2022 2021 2011 2012 2013 @Oempa dan Trunami — WTewumi —@Laturan Gunung Api #Gempa Bumi“ Abrnsi Pantai #Kekaringan Kebakaran utan dan Lahan #Tarah Longsor « Cunca Eketrom — # Baniit Gambar 1. Tren kejadian bencana di Indonesia dari tahun 2011 — 2023.', 'BAB I', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1567, 'pedoman-3-2024', 3, 'lain', 'BAB I (lanjutan 1)', NULL, 1, 'Sumber data: BNPB Dalam menghadapi situasi ini, penting untuk memastikan bahwa upaya penanggulangan bencana tidak hanya berfokus pada respons saat dan pascabencana, tetapi juga pada upaya pencegahan, mitigasi, dan kesiapsiagaan sebelum bencana terjadi. Sosialisasi memainkan peran kunci dalam membangun kesadaran, pengetahuan, dan kesiapsiagaan masyarakat dalam menghadapi bencana. Namun, berbagai persoalan dalam pelaksanaan sosialisasi kerap terjadi, beberapa diantaranya karena keterbatasan akses dan penyebaran informasi, tantangan dalam mendorong perubahan perilaku, strategi sosialisasi yang belum efektif dan tidak tepat sasaran, ketidakpercayaan terhadap pihak berwenang atau informasi resmi, adanya misinformasi, disinformasi, dan hoaks, pengarusutamaan gender, disabilitas, dan inklusi sosial, koordinasi yang lemah antara penyedia informasi dengan penyalur informasi, serta tidak adanya metode evaluasi untuk mengkaji efektivitas dari sosialisasi yang dilakukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1567, 'Sumber data: BNPB Dalam menghadapi situasi ini, penting untuk memastikan bahwa upaya penanggulangan bencana tidak hanya berfokus pada respons saat dan pascabencana, tetapi juga pada upaya pencegahan, mitigasi, dan kesiapsiagaan sebelum bencana terjadi. Sosialisasi memainkan peran kunci dalam membangun kesadaran, pengetahuan, dan kesiapsiagaan masyarakat dalam menghadapi bencana. Namun, berbagai persoalan dalam pelaksanaan sosialisasi kerap terjadi, beberapa diantaranya karena keterbatasan akses dan penyebaran informasi, tantangan dalam mendorong perubahan perilaku, strategi sosialisasi yang belum efektif dan tidak tepat sasaran, ketidakpercayaan terhadap pihak berwenang atau informasi resmi, adanya misinformasi, disinformasi, dan hoaks, pengarusutamaan gender, disabilitas, dan inklusi sosial, koordinasi yang lemah antara penyedia informasi dengan penyalur informasi, serta tidak adanya metode evaluasi untuk mengkaji efektivitas dari sosialisasi yang dilakukan.', 'BAB I (lanjutan 1)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1568, 'pedoman-3-2024', 4, 'lain', 'BAB I (lanjutan 2)', NULL, 2, 'Berbagai persoalan di atas mengindikasikan bahwa diperlukan upaya untuk merancang dan melaksanakan strategi komunikasi yang efektif, adanya prinsip atau kriteria dasar untuk melakukan sosialisasi, memiliki pesan kunci untuk berbagai jenis ancaman bencana, menentukan kelompok sasaran prioritas dan ragam media sosialisasi, memperkuat koordinasi dengan seluruh pihak terkait, menentukan peran terkait siapa, melakukan apa, dimana, dan kapan akan dilakukan sosialisasi, metode pemantauan dan pengawasan, hingga mekanisme umpan balik dari masyarakat atas efektivitas sosialisasi yang dilakukan oleh pemerintah.
Melalui sosialisasi yang efektif, efisien dengan mempertimbangkan persoalan dan kebutuhan di atas, diharapkan sosialisasi yang dilakukan pemangku kepentingan dapat menyasar seluruh lapisan masyarakat, terutama untuk melindungi kelompok-kelompok yang berisiko tinggi seperti bayi, anak usia di bawah lima tahun, anak-anak, ibu hamil atau menyusui, penyandang disabilitas, dan orang lanjut usia, serta kelompok rentan lainnya, sosialisasi penanggulangan bencana memiliki potensi untuk mengurangi risiko, meminimalkan kerugian, dan meningkatkan kemampuan adaptasi masyarakat terhadap ancaman bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1568, 'Berbagai persoalan di atas mengindikasikan bahwa diperlukan upaya untuk merancang dan melaksanakan strategi komunikasi yang efektif, adanya prinsip atau kriteria dasar untuk melakukan sosialisasi, memiliki pesan kunci untuk berbagai jenis ancaman bencana, menentukan kelompok sasaran prioritas dan ragam media sosialisasi, memperkuat koordinasi dengan seluruh pihak terkait, menentukan peran terkait siapa, melakukan apa, dimana, dan kapan akan dilakukan sosialisasi, metode pemantauan dan pengawasan, hingga mekanisme umpan balik dari masyarakat atas efektivitas sosialisasi yang dilakukan oleh pemerintah.
Melalui sosialisasi yang efektif, efisien dengan mempertimbangkan persoalan dan kebutuhan di atas, diharapkan sosialisasi yang dilakukan pemangku kepentingan dapat menyasar seluruh lapisan masyarakat, terutama untuk melindungi kelompok-kelompok yang berisiko tinggi seperti bayi, anak usia di bawah lima tahun, anak-anak, ibu hamil atau menyusui, penyandang disabilitas, dan orang lanjut usia, serta kelompok rentan lainnya, sosialisasi penanggulangan bencana memiliki potensi untuk mengurangi risiko, meminimalkan kerugian, dan meningkatkan kemampuan adaptasi masyarakat terhadap ancaman bencana.', 'BAB I (lanjutan 2)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1569, 'pedoman-3-2024', 5, 'lain', 'BAB I (lanjutan 3)', NULL, 2, 'Di sisi lain, perempuan dan anak-anak menghadapi kerentanan yang signifikan terkait dengan bencana dan perubahan iklim, termasuk pula risiko tinggi terhadap kekerasan berbasis gender. Keterbatasan akses terhadap sumber daya seperti air bersih, makanan, dan layanan kesehatan dapat memperburuk kondisi mereka selama dan setelah bencana. Selain itu, peran tradisional perempuan dalam perawatan keluarga dan tanggung jawab tambahan yang mereka tanggung dapat mempengaruhi kesejahteraan mereka. Dalam mengatasi kerentanan ini, penting untuk memasukkan perspektif gender dan kebutuhan anak-anak dalam sosialisasi penanggulangan bencana, termasuk juga meliputi perlindungan terhadap kekerasan, akses yang lebih baik terhadap layanan kesehatan dan pendidikan, serta pemberdayaan ekonomi perempuan.
Berdasarkan lampiran Peraturan Presiden Nomor 87 Tahun 2020 tentang Rencana Induk Penanggulangan Bencana menyatakan bahwa salah satu kebijakan pengutan tata kelola penanggulangan bencana yang semakin profesional, transparan, akuntabel, dilakukan dengan strategi meningkatkan edukasi kebencanaan dan pengelolaan pengetahuan penanggulangan bencana pada masyarakat dan pemangku kepentingan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1569, 'Di sisi lain, perempuan dan anak-anak menghadapi kerentanan yang signifikan terkait dengan bencana dan perubahan iklim, termasuk pula risiko tinggi terhadap kekerasan berbasis gender. Keterbatasan akses terhadap sumber daya seperti air bersih, makanan, dan layanan kesehatan dapat memperburuk kondisi mereka selama dan setelah bencana. Selain itu, peran tradisional perempuan dalam perawatan keluarga dan tanggung jawab tambahan yang mereka tanggung dapat mempengaruhi kesejahteraan mereka. Dalam mengatasi kerentanan ini, penting untuk memasukkan perspektif gender dan kebutuhan anak-anak dalam sosialisasi penanggulangan bencana, termasuk juga meliputi perlindungan terhadap kekerasan, akses yang lebih baik terhadap layanan kesehatan dan pendidikan, serta pemberdayaan ekonomi perempuan.
Berdasarkan lampiran Peraturan Presiden Nomor 87 Tahun 2020 tentang Rencana Induk Penanggulangan Bencana menyatakan bahwa salah satu kebijakan pengutan tata kelola penanggulangan bencana yang semakin profesional, transparan, akuntabel, dilakukan dengan strategi meningkatkan edukasi kebencanaan dan pengelolaan pengetahuan penanggulangan bencana pada masyarakat dan pemangku kepentingan.', 'BAB I (lanjutan 3)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1570, 'pedoman-3-2024', 6, 'lain', 'BAB I (lanjutan 4)', NULL, 2, 'Hal ini juga menjadi perhatian dalam Peraturan Menteri Dalam Negeri Nomor 101 tahun 2018 tentang Standar Teknis pada Standar Pelayanan Minimal, terkait pelayanan informasi yang dilaksanakan dengan kegiatan Komunikasi, Informasi dan Edukasi rawan bencana, dan sosialisasi menjadi salah satu komponennya. Berdasarkan hal tersebut diatas, perlu dibentuk pedoman sosialisasi penanggulangan bencana yang akan menjadi acuan bagi penyelenggara sosialisasi penanggulangan bencana.
B. Maksud dan Tujuan Pedoman ini disusun dengan maksud untuk menjadi acuan dalam penyelenggaraan sosialisasi penanggulangan bencana yang dilakukan oleh pemerintah pusat, pemerintah daerah, dan mitra pemangku kepentingan, yang merupakan bagian untuk mendukung pencapaian Standar Pelayanan Minimal Sub Urusan Bencana Sub Kegiatan Pelayanan Informasi Rawan Bencana oleh BPBD kabupaten/kota.
Pedoman ini bertujuan antara lain untuk:
1. meningkatkan pemahaman masyarakat tentang risiko bencana, langkah-langkah prabencana, saat darurat bencana, dan pascabencana, serta memotivasi adopsi perubahan perilaku dan budaya sadar bencana dalam kehidupan sehari-hari.
2. meningkatkan kesadaran, pengetahuan, dan keterampilan yang lebih baik, serta peningkatan partisipasi masyarakat dalam kegiatan prabencana terkait pengurangan kerentanan dan peningkatan kapasitas terhadap risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1570, 'Hal ini juga menjadi perhatian dalam Peraturan Menteri Dalam Negeri Nomor 101 tahun 2018 tentang Standar Teknis pada Standar Pelayanan Minimal, terkait pelayanan informasi yang dilaksanakan dengan kegiatan Komunikasi, Informasi dan Edukasi rawan bencana, dan sosialisasi menjadi salah satu komponennya. Berdasarkan hal tersebut diatas, perlu dibentuk pedoman sosialisasi penanggulangan bencana yang akan menjadi acuan bagi penyelenggara sosialisasi penanggulangan bencana.
B. Maksud dan Tujuan Pedoman ini disusun dengan maksud untuk menjadi acuan dalam penyelenggaraan sosialisasi penanggulangan bencana yang dilakukan oleh pemerintah pusat, pemerintah daerah, dan mitra pemangku kepentingan, yang merupakan bagian untuk mendukung pencapaian Standar Pelayanan Minimal Sub Urusan Bencana Sub Kegiatan Pelayanan Informasi Rawan Bencana oleh BPBD kabupaten/kota.
Pedoman ini bertujuan antara lain untuk:
1. meningkatkan pemahaman masyarakat tentang risiko bencana, langkah-langkah prabencana, saat darurat bencana, dan pascabencana, serta memotivasi adopsi perubahan perilaku dan budaya sadar bencana dalam kehidupan sehari-hari.
2. meningkatkan kesadaran, pengetahuan, dan keterampilan yang lebih baik, serta peningkatan partisipasi masyarakat dalam kegiatan prabencana terkait pengurangan kerentanan dan peningkatan kapasitas terhadap risiko bencana.', 'BAB I (lanjutan 4)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1571, 'pedoman-3-2024', 7, 'lain', 'BAB I (lanjutan 5)', NULL, 3, 'C. Sasaran Sasaran Pedoman ini adalah pemerintah pusat dan pemerintah daerah, khususnya Badan Nasional Penanggulangan Bencana (BNPB) dan Badan Penanggulangan Bencana Daerah (BPBD) serta lembaga pemerintah dan nonpemerintah lainnya yang menyelenggarakan sosialisasi penanggulangan bencana.
D. Asas Kegiatan sosialiasi penanggulangan bencana yang perlu diterapkan untuk mencapai proses yang efektif, tepat sasaran, dan sesuai dengan kebutuhan, berasaskan:
1. Berbasis Data Sosialisasi harus didasarkan pada informasi yang akurat, data ilmiah, dan pengetahuan yang terverifikasi. Pesan-pesan yang disampaikan juga disesuaikan dengan kearifan lokal yang mendukung ketangguhan bencana serta mengurangi dan/atau mencegah praktik-praktik atau tradisi yang dapat meningkatkan risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1571, 'C. Sasaran Sasaran Pedoman ini adalah pemerintah pusat dan pemerintah daerah, khususnya Badan Nasional Penanggulangan Bencana (BNPB) dan Badan Penanggulangan Bencana Daerah (BPBD) serta lembaga pemerintah dan nonpemerintah lainnya yang menyelenggarakan sosialisasi penanggulangan bencana.
D. Asas Kegiatan sosialiasi penanggulangan bencana yang perlu diterapkan untuk mencapai proses yang efektif, tepat sasaran, dan sesuai dengan kebutuhan, berasaskan:
1. Berbasis Data Sosialisasi harus didasarkan pada informasi yang akurat, data ilmiah, dan pengetahuan yang terverifikasi. Pesan-pesan yang disampaikan juga disesuaikan dengan kearifan lokal yang mendukung ketangguhan bencana serta mengurangi dan/atau mencegah praktik-praktik atau tradisi yang dapat meningkatkan risiko bencana.', 'BAB I (lanjutan 5)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1572, 'pedoman-3-2024', 8, 'lain', 'BAB I (lanjutan 6)', NULL, 3, '2. Partisipatif Melibatkan masyarakat/kelompok sasaran secara aktif dalam proses sosialisasi, mulai dari perencanaan, pelaksanaan, hingga evaluasi dan pemberian umpan balik. Pelibatan masyarakat adalah sangat penting untuk memperkuat rasa kepemilikan, meningkatkan penyerapan pesan-pesan yang disampaikan, dan mendorong terjadinya rencana tindak lanjut, aksi, hingga perubahan perilaku yang diinginkan. Selain itu, pelibatan masyarakat juga memperkuat efektivitas pesan sosialisasi dengan membuatnya lebih relevan, mudah dipahami, dan lebih mungkin diterima oleh kelompok sasaran. Dengan melibatkan kelompok sasaran dalam proses sosialisasi, masyarakat juga memiliki kesempatan untuk menyesuaikan pesan-pesan serta metode sosialisasi sehingga lebih sesuai dengan situasi dan konteks yang dimiliki.
3. Inklusif Proses sosialisasi perlu dirancang agar mudah diakses dan dipahami sesuai dengan kelompok sasaran yang dituju, termasuk perbedaan gender, usia (anak-anak hingga lansia), dan penyandang disabilitas.
Informasi perlu disampaikan dalam berbagai format yang sesuai dengan karakteristik dan kebutuhan kelompok sasaran yang dituju.
4. Sesuai dengan kebutuhan Kegiatan sosialisasi penanggulangan bencana perlu mendorong minat dan motivasi masyarakat untuk aktif terlibat dalam upaya kesiapsiagaan dan mitigasi bencana. Topik dan materi sosialisasi perlu diselaraskan dengan konteks lokal, situasi geografis, dan jenis ancaman bencana yang mungkin dihadapi oleh masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1572, '2. Partisipatif Melibatkan masyarakat/kelompok sasaran secara aktif dalam proses sosialisasi, mulai dari perencanaan, pelaksanaan, hingga evaluasi dan pemberian umpan balik. Pelibatan masyarakat adalah sangat penting untuk memperkuat rasa kepemilikan, meningkatkan penyerapan pesan-pesan yang disampaikan, dan mendorong terjadinya rencana tindak lanjut, aksi, hingga perubahan perilaku yang diinginkan. Selain itu, pelibatan masyarakat juga memperkuat efektivitas pesan sosialisasi dengan membuatnya lebih relevan, mudah dipahami, dan lebih mungkin diterima oleh kelompok sasaran. Dengan melibatkan kelompok sasaran dalam proses sosialisasi, masyarakat juga memiliki kesempatan untuk menyesuaikan pesan-pesan serta metode sosialisasi sehingga lebih sesuai dengan situasi dan konteks yang dimiliki.
3. Inklusif Proses sosialisasi perlu dirancang agar mudah diakses dan dipahami sesuai dengan kelompok sasaran yang dituju, termasuk perbedaan gender, usia (anak-anak hingga lansia), dan penyandang disabilitas.
Informasi perlu disampaikan dalam berbagai format yang sesuai dengan karakteristik dan kebutuhan kelompok sasaran yang dituju.
4. Sesuai dengan kebutuhan Kegiatan sosialisasi penanggulangan bencana perlu mendorong minat dan motivasi masyarakat untuk aktif terlibat dalam upaya kesiapsiagaan dan mitigasi bencana. Topik dan materi sosialisasi perlu diselaraskan dengan konteks lokal, situasi geografis, dan jenis ancaman bencana yang mungkin dihadapi oleh masyarakat.', 'BAB I (lanjutan 6)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1573, 'pedoman-3-2024', 9, 'lain', 'BAB I (lanjutan 7)', NULL, 4, '5. Menyeluruh dan adaptif Proses sosialisasi harus mencakup semua kelompok masyarakat, tanpa membedakan suku, agama, gender, usia, atau status sosial.
Pesan-pesan sosialisasi harus disusun sedemikian rupa sehingga relevan dan dapat diterima oleh semua kalangan. Pesan-pesan sosialisasi juga harus didesain sesuai kebutuhan, preferensi, dan kondisi lokal masing-masing wilayah atau komunitas. Faktor-faktor seperti budaya, bahasa, dan kondisi geografis dalam penyusunan pesan-pesan sosialisasi perlu menjadi pertimbangan.
6. Responsif Proses sosialisasi harus memberikan informasi yang mendorong kelompok sasaran untuk bertindak, termasuk langkah-langkah konkret yang dapat diambil untuk mempersiapkan diri, mengurangi risiko, dan merespons bencana. Proses sosialiasi perlu menyesuaikan secara cepat dan tepat terhadap perubahan-perubahan kondisi atau kebutuhan masyarakat terkait penanggulangan bencana serta sensitif terhadap situasi yang berkembang.
7. Lugas dan mudah dimengerti Pesan-pesan sosialisasi penanggulangan bencana perlu disampaikan dengan lugas agar mudah dipahami oleh semua lapisan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1573, '5. Menyeluruh dan adaptif Proses sosialisasi harus mencakup semua kelompok masyarakat, tanpa membedakan suku, agama, gender, usia, atau status sosial.
Pesan-pesan sosialisasi harus disusun sedemikian rupa sehingga relevan dan dapat diterima oleh semua kalangan. Pesan-pesan sosialisasi juga harus didesain sesuai kebutuhan, preferensi, dan kondisi lokal masing-masing wilayah atau komunitas. Faktor-faktor seperti budaya, bahasa, dan kondisi geografis dalam penyusunan pesan-pesan sosialisasi perlu menjadi pertimbangan.
6. Responsif Proses sosialisasi harus memberikan informasi yang mendorong kelompok sasaran untuk bertindak, termasuk langkah-langkah konkret yang dapat diambil untuk mempersiapkan diri, mengurangi risiko, dan merespons bencana. Proses sosialiasi perlu menyesuaikan secara cepat dan tepat terhadap perubahan-perubahan kondisi atau kebutuhan masyarakat terkait penanggulangan bencana serta sensitif terhadap situasi yang berkembang.
7. Lugas dan mudah dimengerti Pesan-pesan sosialisasi penanggulangan bencana perlu disampaikan dengan lugas agar mudah dipahami oleh semua lapisan masyarakat.', 'BAB I (lanjutan 7)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1574, 'pedoman-3-2024', 10, 'lain', 'BAB I (lanjutan 8)', NULL, 4, 'Bahasa yang jelas dan sederhana akan membantu memastikan bahwa informasi yang disampaikan dapat diakses oleh semua orang, termasuk kelompok masyarakat yang mungkin memiliki tingkat pendidikan atau literasi yang rendah. Dengan menyajikan informasi secara lugas, masyarakat akan lebih mudah memahami langkah-langkah yang perlu diambil untuk menghadapi ancaman bencana, serta mematuhi instruksi dan petunjuk yang diberikan
8. Kolaboratif Proses sosialiasi perlu melibatkan berbagai pemangku kepentingan, termasuk pemerintah, lembaga non-pemerintah, sektor swasta, akademisi, dan masyarakat sipil dalam penyusunan dan pelaksanaan sosialisasi, serta saat pemantauan, evaluasi, dan umpan balik.
Kolaborasi antar pihak dapat meningkatkan efektivitas dan dampak sosialisasi. Sosialisasi penanggulangan bencana juga harus terintegrasi dengan kebijakan, program, dan aktivitas lainnya yang terkait dengan prabencana, saat darurat bencana, dan pascabencana, termasuk juga program-program lainnya yang relevan. Koordinasi antarlembaga dan sektor sangat penting untuk mencapai masyarakat yang resilien.
9. Berkesinambungan Sosialisasi penanggulangan bencana harus menjadi bagian dari upaya yang berkelanjutan dan terus-menerus. Pemantauan, evaluasi, dan umpan balik perlu dilakukan secara berkala, untuk kemudian digunakan dalam penyesuaian strategi sosialisasi yang sesuai dengan perubahan kondisi dan kebutuhan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1574, 'Bahasa yang jelas dan sederhana akan membantu memastikan bahwa informasi yang disampaikan dapat diakses oleh semua orang, termasuk kelompok masyarakat yang mungkin memiliki tingkat pendidikan atau literasi yang rendah. Dengan menyajikan informasi secara lugas, masyarakat akan lebih mudah memahami langkah-langkah yang perlu diambil untuk menghadapi ancaman bencana, serta mematuhi instruksi dan petunjuk yang diberikan
8. Kolaboratif Proses sosialiasi perlu melibatkan berbagai pemangku kepentingan, termasuk pemerintah, lembaga non-pemerintah, sektor swasta, akademisi, dan masyarakat sipil dalam penyusunan dan pelaksanaan sosialisasi, serta saat pemantauan, evaluasi, dan umpan balik.
Kolaborasi antar pihak dapat meningkatkan efektivitas dan dampak sosialisasi. Sosialisasi penanggulangan bencana juga harus terintegrasi dengan kebijakan, program, dan aktivitas lainnya yang terkait dengan prabencana, saat darurat bencana, dan pascabencana, termasuk juga program-program lainnya yang relevan. Koordinasi antarlembaga dan sektor sangat penting untuk mencapai masyarakat yang resilien.
9. Berkesinambungan Sosialisasi penanggulangan bencana harus menjadi bagian dari upaya yang berkelanjutan dan terus-menerus. Pemantauan, evaluasi, dan umpan balik perlu dilakukan secara berkala, untuk kemudian digunakan dalam penyesuaian strategi sosialisasi yang sesuai dengan perubahan kondisi dan kebutuhan masyarakat.', 'BAB I (lanjutan 8)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1575, 'pedoman-3-2024', 11, 'lain', 'BAB I (lanjutan 9)', NULL, 5, 'E. Ruang Lingkup Ruang lingkup pedoman perencanaan sosialisasi penanggulangan bencana ini meliputi:
1. Konsep Sosialisasi;
2. Pelaksanaan;
3. Sosialisasi Langsung;
4. Sosialisasi Tidak Langsung;
5. Pesan Kunci; dan
6. Pemantauan, Evaluasi, dan Umpan Balik.
F. Pengertian Umum
1. Sosialisasi Penanggulangan Bencana adalah upaya atau serangkaian upaya penyampaian informasi, yang bertujuan untuk mengenal ancaman bencana, meningkatkan kesadaran, dan pembentukan sikap serta perilaku sehingga mempersiapkan masyarakat dalam menghadapi ancaman bencana
2. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat merupakan kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, mengungsi, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
3. Bahaya adalah suatu proses, fenomena atau aktivitas manusia yang dapat menyebabkan hilangnya nyawa, cedera atau dampak kesehatan lainnya, kerusakan properti, gangguan sosial dan ekonomi atau kerusakan lingkungan. Dalam pedoman ini, istilah bahaya dan ancaman bencana dapat dipertukarkan dengan pengertian yang sama
4. Kapasitas adalah kombinasi semua kekuatan, atribut, dan sumber daya yang tersedia dalam organisasi, komunitas atau masyarakat untuk mengelola dan mengurangi risiko bencana dan memperkuat ketahanan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1575, 'E. Ruang Lingkup Ruang lingkup pedoman perencanaan sosialisasi penanggulangan bencana ini meliputi:
1. Konsep Sosialisasi;
2. Pelaksanaan;
3. Sosialisasi Langsung;
4. Sosialisasi Tidak Langsung;
5. Pesan Kunci; dan
6. Pemantauan, Evaluasi, dan Umpan Balik.
F. Pengertian Umum
1. Sosialisasi Penanggulangan Bencana adalah upaya atau serangkaian upaya penyampaian informasi, yang bertujuan untuk mengenal ancaman bencana, meningkatkan kesadaran, dan pembentukan sikap serta perilaku sehingga mempersiapkan masyarakat dalam menghadapi ancaman bencana
2. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat merupakan kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, mengungsi, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
3. Bahaya adalah suatu proses, fenomena atau aktivitas manusia yang dapat menyebabkan hilangnya nyawa, cedera atau dampak kesehatan lainnya, kerusakan properti, gangguan sosial dan ekonomi atau kerusakan lingkungan. Dalam pedoman ini, istilah bahaya dan ancaman bencana dapat dipertukarkan dengan pengertian yang sama
4. Kapasitas adalah kombinasi semua kekuatan, atribut, dan sumber daya yang tersedia dalam organisasi, komunitas atau masyarakat untuk mengelola dan mengurangi risiko bencana dan memperkuat ketahanan', 'BAB I (lanjutan 9)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1576, 'pedoman-3-2024', 12, 'lain', 'BAB I (lanjutan 10)', NULL, 5, '5. Kerentanan adalah kondisi yang ditentukan oleh faktor fisik, sosial, ekonomi dan lingkungan atau proses yang meningkatkan risiko individu, komunitas, aset atau sistem terhadap dampak bahaya.
6. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis
7. Kelompok Berisiko atau Kelompok Rentan adalah anak-anak (termasuk bayi dan anak usia di bawah lima tahun), perempuan (termasuk ibu hamil dan ibu menyusui), penyandang disabilitas, orang lanjut usia, pengidap penyakit kronis, serta kelompok rentan lainnya.
8. Budaya Sadar Bencana adalah salah satu upaya untuk meningkatkan kesadaran secara kolektif untuk masyarakat dalam hal penanggulangan bencana dan kesiapsiagaan mereka dalam hal mengantisipasi bila terjadi bencana.
9. Masyarakat adalah perseorangan, kelompok orang dan/atau badan hukum.
10. Pemerintah Pusat, yang selanjutnya disebut Pemerintah, adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
11. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara Pemerintahan Daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1576, '5. Kerentanan adalah kondisi yang ditentukan oleh faktor fisik, sosial, ekonomi dan lingkungan atau proses yang meningkatkan risiko individu, komunitas, aset atau sistem terhadap dampak bahaya.
6. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis
7. Kelompok Berisiko atau Kelompok Rentan adalah anak-anak (termasuk bayi dan anak usia di bawah lima tahun), perempuan (termasuk ibu hamil dan ibu menyusui), penyandang disabilitas, orang lanjut usia, pengidap penyakit kronis, serta kelompok rentan lainnya.
8. Budaya Sadar Bencana adalah salah satu upaya untuk meningkatkan kesadaran secara kolektif untuk masyarakat dalam hal penanggulangan bencana dan kesiapsiagaan mereka dalam hal mengantisipasi bila terjadi bencana.
9. Masyarakat adalah perseorangan, kelompok orang dan/atau badan hukum.
10. Pemerintah Pusat, yang selanjutnya disebut Pemerintah, adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
11. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara Pemerintahan Daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.', 'BAB I (lanjutan 10)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1577, 'pedoman-3-2024', 13, 'lain', 'BAB II', NULL, 7, 'KONSEP SOSIALISASI A. Tujuan Sosialisasi Beberapa tujuan utama Sosialisasi Penanggulangan Bencana, antara lain untuk:
1. Meningkatkan kesadaran masyarakat akan Risiko Bencana yang ada di lingkungan mereka, serta pentingnya mengambil langkah-langkah pencegahan dan kesiapsiagaan, baik secara individual maupun kolektif dalam rangka membangun Budaya Sadar Bencana.
2. Memberikan edukasi dan pengetahuan kepada masyarakat tentang berbagai jenis risiko bencana, tanda-tanda peringatan, perilaku yang aman, dan langkah-langkah yang dapat mereka lakukan pada sebelum, saat, dan sesudah bencana.
3. Mengembangkan keterampilan praktis dalam penanggulangan bencana, seperti menyusun tas siaga bencana, melakukan evakuasi yang aman, dan melakukan tindakan menyelamatkan diri dari ancaman bencana.
4. Mengurangi kerentanan masyarakat atau kelompok berisiko tinggi terhadap bencana dengan memperkenalkan praktik-praktik yang dianjurkan untuk mengurangi risiko yang dapat membantu melindungi mereka dan harta benda mereka.
5. Mempromosikan partisipasi aktif masyarakat dalam perencanaan, pelaksanaan, dan evaluasi program Sosialisasi Penanggulangan Bencana, termasuk pula memberikan saran terkait advokasi kebijakan dan praktik yang efektif dapat dibangun berdasarkan kebutuhan dan pengalaman mereka.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1577, 'KONSEP SOSIALISASI A. Tujuan Sosialisasi Beberapa tujuan utama Sosialisasi Penanggulangan Bencana, antara lain untuk:
1. Meningkatkan kesadaran masyarakat akan Risiko Bencana yang ada di lingkungan mereka, serta pentingnya mengambil langkah-langkah pencegahan dan kesiapsiagaan, baik secara individual maupun kolektif dalam rangka membangun Budaya Sadar Bencana.
2. Memberikan edukasi dan pengetahuan kepada masyarakat tentang berbagai jenis risiko bencana, tanda-tanda peringatan, perilaku yang aman, dan langkah-langkah yang dapat mereka lakukan pada sebelum, saat, dan sesudah bencana.
3. Mengembangkan keterampilan praktis dalam penanggulangan bencana, seperti menyusun tas siaga bencana, melakukan evakuasi yang aman, dan melakukan tindakan menyelamatkan diri dari ancaman bencana.
4. Mengurangi kerentanan masyarakat atau kelompok berisiko tinggi terhadap bencana dengan memperkenalkan praktik-praktik yang dianjurkan untuk mengurangi risiko yang dapat membantu melindungi mereka dan harta benda mereka.
5. Mempromosikan partisipasi aktif masyarakat dalam perencanaan, pelaksanaan, dan evaluasi program Sosialisasi Penanggulangan Bencana, termasuk pula memberikan saran terkait advokasi kebijakan dan praktik yang efektif dapat dibangun berdasarkan kebutuhan dan pengalaman mereka.', 'BAB II', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1578, 'pedoman-3-2024', 14, 'lain', 'BAB II (lanjutan 1)', NULL, 7, 'B. Jenis sosialisasi Sosialisasi Penanggulangan Bencana memiliki beragam jenis yang bisa dipilah berdasarkan berbagai aspek. Dalam bagian ini menjelaskan beragam jenis sosialisasi penanggulangan bencana untuk memudahkan pihak penyelenggara sosialisasi dalam memilih jenis-jenis sosialisasi penanggulangan bencana sesuai dengan konteks, kebutuhan, dan sumber daya yang tersedia. Ragam jenis Sosialisasi Penanggulangan Bencana terdiri dari:
1. Berdasarkan metode penyampaian:
a. Sosialisasi Langsung: sosialisasi di mana pesan atau informasi disampaikan secara langsung kepada peserta oleh fasilitator sosialisasi. Kegiatan ini bisa terjadi baik dalam konteks tatap muka maupun tidak tatap muka, asalkan interaksi antara fasilitator dan peserta terjadi secara langsung.
b. Sosialiasi Tidak Langsung: sosialisasi di mana pesan atau informasi disampaikan kepada peserta tanpa melalui interaksi langsung dengan fasilitator sosialisasi. Kegiatan ini bisa meliputi penggunaan media massa atau materi sosialisasi (misalnya poster, flyer, booklet, atau media lainnya) yang dapat diakses secara mandiri oleh peserta.
2. Berdasarkan besaran sasaran:
a. Sosialisasi Individu: sosialisasi individu melibatkan komunikasi satu-satu antara fasilitator sosialisasi dan peserta. Ini dapat terjadi dalam bentuk konseling, kunjungan rumah, atau mentoring.
Sosialisasi individu memungkinkan penyesuaian pesan dengan kebutuhan dan karakteristik individu peserta.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1578, 'B. Jenis sosialisasi Sosialisasi Penanggulangan Bencana memiliki beragam jenis yang bisa dipilah berdasarkan berbagai aspek. Dalam bagian ini menjelaskan beragam jenis sosialisasi penanggulangan bencana untuk memudahkan pihak penyelenggara sosialisasi dalam memilih jenis-jenis sosialisasi penanggulangan bencana sesuai dengan konteks, kebutuhan, dan sumber daya yang tersedia. Ragam jenis Sosialisasi Penanggulangan Bencana terdiri dari:
1. Berdasarkan metode penyampaian:
a. Sosialisasi Langsung: sosialisasi di mana pesan atau informasi disampaikan secara langsung kepada peserta oleh fasilitator sosialisasi. Kegiatan ini bisa terjadi baik dalam konteks tatap muka maupun tidak tatap muka, asalkan interaksi antara fasilitator dan peserta terjadi secara langsung.
b. Sosialiasi Tidak Langsung: sosialisasi di mana pesan atau informasi disampaikan kepada peserta tanpa melalui interaksi langsung dengan fasilitator sosialisasi. Kegiatan ini bisa meliputi penggunaan media massa atau materi sosialisasi (misalnya poster, flyer, booklet, atau media lainnya) yang dapat diakses secara mandiri oleh peserta.
2. Berdasarkan besaran sasaran:
a. Sosialisasi Individu: sosialisasi individu melibatkan komunikasi satu-satu antara fasilitator sosialisasi dan peserta. Ini dapat terjadi dalam bentuk konseling, kunjungan rumah, atau mentoring.
Sosialisasi individu memungkinkan penyesuaian pesan dengan kebutuhan dan karakteristik individu peserta.', 'BAB II (lanjutan 1)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1579, 'pedoman-3-2024', 15, 'lain', 'BAB II (lanjutan 2)', NULL, 8, 'b. Sosialisasi Kelompok: sosialisasi kelompok dilakukan dalam lingkungan yang lebih kecil, seperti kelompok-kelompok komunitas, keluarga, atau organisasi. Ini dapat mencakup diskusi kelompok, lokakarya, atau pertemuan kecil di tingkat lokal. Sosialisasi kelompok memungkinkan interaksi yang lebih intim dan pertukaran informasi yang lebih mendalam antara peserta.
Sosialisasi ini misalnya dilakukan di sekolah, tempat ibadah, pasar, dan forum-forum publik lainnya.
c. Sosialisasi Massal: jenis sosialisasi ini melibatkan penyebaran pesan-pesan atau informasi kepada khalayak yang luas, seperti melalui media massa (televisi, radio, surat kabar), kampanye sosial, atau acara publik. Sosialisasi ini bisa menggunakan media elektronik dan/atau media non-elektronik. Sosialisasi massal efektif untuk mencapai target audiens yang besar dalam waktu yang relatif singkat.
3. Berdasarkan proses penyampaian:
a. Sosialisasi secara Luring (tatap muka): sosialisasi ini dilakukan dimana fasilitator dan kelompok sasaran berada dalam satu ruangan dan berinteraksi fisik secara langsung.
b. Sosialisasi secara Daring (tidak tatap muka): dalam era digital, sosialisasi juga dapat dilakukan melalui platform online, seperti webinar, podcast, dan forum diskusi online. Sosialisasi online memungkinkan penyebaran informasi yang cepat dan luas, serta interaksi antara peserta dari berbagai lokasi geografis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1579, 'b. Sosialisasi Kelompok: sosialisasi kelompok dilakukan dalam lingkungan yang lebih kecil, seperti kelompok-kelompok komunitas, keluarga, atau organisasi. Ini dapat mencakup diskusi kelompok, lokakarya, atau pertemuan kecil di tingkat lokal. Sosialisasi kelompok memungkinkan interaksi yang lebih intim dan pertukaran informasi yang lebih mendalam antara peserta.
Sosialisasi ini misalnya dilakukan di sekolah, tempat ibadah, pasar, dan forum-forum publik lainnya.
c. Sosialisasi Massal: jenis sosialisasi ini melibatkan penyebaran pesan-pesan atau informasi kepada khalayak yang luas, seperti melalui media massa (televisi, radio, surat kabar), kampanye sosial, atau acara publik. Sosialisasi ini bisa menggunakan media elektronik dan/atau media non-elektronik. Sosialisasi massal efektif untuk mencapai target audiens yang besar dalam waktu yang relatif singkat.
3. Berdasarkan proses penyampaian:
a. Sosialisasi secara Luring (tatap muka): sosialisasi ini dilakukan dimana fasilitator dan kelompok sasaran berada dalam satu ruangan dan berinteraksi fisik secara langsung.
b. Sosialisasi secara Daring (tidak tatap muka): dalam era digital, sosialisasi juga dapat dilakukan melalui platform online, seperti webinar, podcast, dan forum diskusi online. Sosialisasi online memungkinkan penyebaran informasi yang cepat dan luas, serta interaksi antara peserta dari berbagai lokasi geografis.', 'BAB II (lanjutan 2)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1580, 'pedoman-3-2024', 16, 'lain', 'BAB II (lanjutan 3)', NULL, 8, 'c. Sosialisasi secara Hybrid (kombinasi tatap muka dan tidak tatap muka): sosialisasi ini dilakukan dengan kombinasi antara peserta yang bertatap muka dan peserta yang bergabung secara daring.
4. Berdasarkan karakteristik penyampaian
a. Sosialisasi Formal: sosialisasi formal adalah proses pembelajaran dan penyerapan nilai, norma, dan keterampilan yang terjadi melalui struktur dan institusi formal dalam masyarakat, seperti sekolah, universitas, atau pelatihan kerja resmi. Proses sosialisasi ini umumnya terstruktur, didukung oleh kurikulum atau program pendidikan tertentu, dan dilakukan secara terencana oleh para pendidik atau pelatih. Contohnya termasuk pembelajaran di kelas, seminar, atau pelatihan kerja formal.
b. Sosialiasi Non Formal: sosialisasi non-formal adalah proses pembelajaran dan penyerapan nilai, norma, dan keterampilan yang terjadi di luar struktur institusi formal. Ini dapat terjadi melalui kegiatan atau program yang diselenggarakan oleh organisasi atau lembaga non-pemerintah, seperti kelompok masyarakat, klub, atau organisasi sukarela. Meskipun tidak terikat oleh kurikulum formal, sosialisasi non-formal sering kali didukung oleh pendampingan, pelatihan, atau panduan dari fasilitator yang berpengalaman.
Contohnya mencakup pelatihan keterampilan, lokakarya, atau program pengembangan diri.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1580, 'c. Sosialisasi secara Hybrid (kombinasi tatap muka dan tidak tatap muka): sosialisasi ini dilakukan dengan kombinasi antara peserta yang bertatap muka dan peserta yang bergabung secara daring.
4. Berdasarkan karakteristik penyampaian
a. Sosialisasi Formal: sosialisasi formal adalah proses pembelajaran dan penyerapan nilai, norma, dan keterampilan yang terjadi melalui struktur dan institusi formal dalam masyarakat, seperti sekolah, universitas, atau pelatihan kerja resmi. Proses sosialisasi ini umumnya terstruktur, didukung oleh kurikulum atau program pendidikan tertentu, dan dilakukan secara terencana oleh para pendidik atau pelatih. Contohnya termasuk pembelajaran di kelas, seminar, atau pelatihan kerja formal.
b. Sosialiasi Non Formal: sosialisasi non-formal adalah proses pembelajaran dan penyerapan nilai, norma, dan keterampilan yang terjadi di luar struktur institusi formal. Ini dapat terjadi melalui kegiatan atau program yang diselenggarakan oleh organisasi atau lembaga non-pemerintah, seperti kelompok masyarakat, klub, atau organisasi sukarela. Meskipun tidak terikat oleh kurikulum formal, sosialisasi non-formal sering kali didukung oleh pendampingan, pelatihan, atau panduan dari fasilitator yang berpengalaman.
Contohnya mencakup pelatihan keterampilan, lokakarya, atau program pengembangan diri.', 'BAB II (lanjutan 3)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1581, 'pedoman-3-2024', 17, 'lain', 'BAB II (lanjutan 4)', NULL, 8, 'c. Sosialisasi Informal: sosialisasi informal adalah proses pembelajaran dan penyerapan nilai, norma, dan keterampilan yang terjadi secara tidak resmi dan tidak terstruktur dalam interaksi sehari-hari antara individu dalam masyarakat. Ini bisa terjadi di tempat kerja, dalam keluarga, di lingkungan sekitar, atau dalam aktivitas sehari-hari lainnya. Sosialisasi informal cenderung tidak disengaja dan terjadi tanpa perencanaan yang khusus, tetapi memiliki dampak yang signifikan dalam membentuk kepribadian dan perilaku seseorang. Contohnya termasuk pembelajaran dari teman sebaya, anggota keluarga, atau figur otoritas informal di masyarakat.
5. Berdasarkan kelompok sasaran:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1581, 'c. Sosialisasi Informal: sosialisasi informal adalah proses pembelajaran dan penyerapan nilai, norma, dan keterampilan yang terjadi secara tidak resmi dan tidak terstruktur dalam interaksi sehari-hari antara individu dalam masyarakat. Ini bisa terjadi di tempat kerja, dalam keluarga, di lingkungan sekitar, atau dalam aktivitas sehari-hari lainnya. Sosialisasi informal cenderung tidak disengaja dan terjadi tanpa perencanaan yang khusus, tetapi memiliki dampak yang signifikan dalam membentuk kepribadian dan perilaku seseorang. Contohnya termasuk pembelajaran dari teman sebaya, anggota keluarga, atau figur otoritas informal di masyarakat.
5. Berdasarkan kelompok sasaran:', 'BAB II (lanjutan 4)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1582, 'pedoman-3-2024', 18, 'lain', 'BAB II (lanjutan 5)', NULL, 9, 'a. Sosialisasi untuk pemerintah pusat dan pemerintah daerah: sosialisasi untuk kalangan pemerintah, termasuk untuk kepala daerah dan kepala pemerintahan, dan juga para pembuat kebijakan lainnya, cenderung lebih fokus pada aspek kebijakan, regulasi, dan koordinasi antar instansi dalam penanggulangan bencana. Selain itu, informasi yang disampaikan akan lebih teknis dan terkait dengan perencanaan dan pengelolaan bencana di tingkat nasional dan lokal. Selain itu, tujuan sosialisasi ini untuk mempengaruhi kebijakan, program, dan anggaran yang mendukung upaya penanggulangan bencana. Fungsi dari sosialisasi ini adalah mendorong pengambil keputusan untuk mengadopsi kebijakan yang proaktif dan berkelanjutan dalam penanggulangan bencana, termasuk memastikan alokasi sumber daya yang memadai, serta memperkuat mekanisme koordinasi dan tindak lanjut dalam implementasi program-program penanggulangan bencana
b. Sosialisasi untuk lembaga non-pemerintah: sosialisasi untuk lembaga non-pemerintah lebih fokus pada penguatan kapasitas dalam hal implementasi penanggulangan bencana (termasuk penyediaan bantuan kemanusiaan dan pendampingan masyarakat), mulai dari prabencana, saat darurat bencana, hingga pascabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1582, 'a. Sosialisasi untuk pemerintah pusat dan pemerintah daerah: sosialisasi untuk kalangan pemerintah, termasuk untuk kepala daerah dan kepala pemerintahan, dan juga para pembuat kebijakan lainnya, cenderung lebih fokus pada aspek kebijakan, regulasi, dan koordinasi antar instansi dalam penanggulangan bencana. Selain itu, informasi yang disampaikan akan lebih teknis dan terkait dengan perencanaan dan pengelolaan bencana di tingkat nasional dan lokal. Selain itu, tujuan sosialisasi ini untuk mempengaruhi kebijakan, program, dan anggaran yang mendukung upaya penanggulangan bencana. Fungsi dari sosialisasi ini adalah mendorong pengambil keputusan untuk mengadopsi kebijakan yang proaktif dan berkelanjutan dalam penanggulangan bencana, termasuk memastikan alokasi sumber daya yang memadai, serta memperkuat mekanisme koordinasi dan tindak lanjut dalam implementasi program-program penanggulangan bencana
b. Sosialisasi untuk lembaga non-pemerintah: sosialisasi untuk lembaga non-pemerintah lebih fokus pada penguatan kapasitas dalam hal implementasi penanggulangan bencana (termasuk penyediaan bantuan kemanusiaan dan pendampingan masyarakat), mulai dari prabencana, saat darurat bencana, hingga pascabencana.', 'BAB II (lanjutan 5)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1583, 'pedoman-3-2024', 19, 'lain', 'BAB II (lanjutan 6)', NULL, 9, 'c. Sosialisasi untuk sektor swasta: sosialisasi untuk sektor swasta lebih menekankan pada upaya mempersiapkan bisnis dan infrastruktur agar lebih tangguh terhadap dampak bencana, termasuk pemahaman tentang risiko bisnis, penilaian dampak bencana, dan pengembangan rencana kontingensi dan tanggap darurat. Sosialisasi untuk sektor swasta juga meliputi pencegahan terjadinya risiko bencana baru akibat aktivitas sektor swasta.
d. Sosialisasi untuk masyarakat umum: sosialisasi kepada masyarakat umum bertujuan untuk meningkatkan kesadaran, pengetahuan, dan keterampilan dalam menghadapi ancaman bencana. Pesan-pesan yang disampaikan bersifat umum dan dapat mencakup berbagai aspek penanggulangan bencana, mulai dari persiapan individu hingga partisipasi dalam rencana tanggap darurat komunitas. Fungsi dari sosialisasi ini menekankan agar masyarakat untuk mengadopsi Budaya Sadar Bencana, serta meningkatkan kesiapsiagaan individu dan keluarga dalam menghadapi situasi darurat.
e. Sosialisasi untuk kelompok rentan atau berisiko tinggi: sosialisasi kepada kelompok rentan bertujuan untuk menyediakan informasi dan bantuan khusus yang sesuai dengan kebutuhan mereka serta memperkuat dukungan dan perlindungan sosial bagi kelompok ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1583, 'c. Sosialisasi untuk sektor swasta: sosialisasi untuk sektor swasta lebih menekankan pada upaya mempersiapkan bisnis dan infrastruktur agar lebih tangguh terhadap dampak bencana, termasuk pemahaman tentang risiko bisnis, penilaian dampak bencana, dan pengembangan rencana kontingensi dan tanggap darurat. Sosialisasi untuk sektor swasta juga meliputi pencegahan terjadinya risiko bencana baru akibat aktivitas sektor swasta.
d. Sosialisasi untuk masyarakat umum: sosialisasi kepada masyarakat umum bertujuan untuk meningkatkan kesadaran, pengetahuan, dan keterampilan dalam menghadapi ancaman bencana. Pesan-pesan yang disampaikan bersifat umum dan dapat mencakup berbagai aspek penanggulangan bencana, mulai dari persiapan individu hingga partisipasi dalam rencana tanggap darurat komunitas. Fungsi dari sosialisasi ini menekankan agar masyarakat untuk mengadopsi Budaya Sadar Bencana, serta meningkatkan kesiapsiagaan individu dan keluarga dalam menghadapi situasi darurat.
e. Sosialisasi untuk kelompok rentan atau berisiko tinggi: sosialisasi kepada kelompok rentan bertujuan untuk menyediakan informasi dan bantuan khusus yang sesuai dengan kebutuhan mereka serta memperkuat dukungan dan perlindungan sosial bagi kelompok ini.', 'BAB II (lanjutan 6)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1584, 'pedoman-3-2024', 20, 'lain', 'BAB II (lanjutan 7)', NULL, 9, 'Pesan-pesan yang disampaikan lebih berfokus pada kebutuhan dan tantangan yang dihadapi oleh kelompok rentan, serta langkah-langkah khusus yang dapat mereka ambil dalam menghadapi bencana. Terkait pelibatan kelompok rentan atau berisiko tinggi, terdapat tahapan-tahapan spesifik yang perlu dilakukan untuk mendorong partisipasi bermakna. Tahapan yang lebih detail akan diatur dalam panduan teknis.
6. Berdasarkan pembiayaan:
a. Sosialisasi dengan pembiayaan: sosialisasi ini melibatkan penggunaan dana atau sumber daya finansial yang ditentukan secara khusus untuk kegiatan sosialisasi penanggulangan bencana.
Dana ini dapat berasal dari anggaran pemerintah, sumbangan dari lembaga donor, atau sumber pembiayaan lainnya yang dialokasikan secara eksplisit untuk kegiatan sosialisasi
b. Sosialisasi tidak dengan pembiayaan: sosialisasi ini dilakukan tanpa keterlibatan dana atau sumber daya finansial yang khusus dialokasikan untuk kegiatan sosialisasi. Meskipun demikian, kegiatan ini masih dapat mengandalkan sumber daya internal institusi, organisasi, atau komunitas, seperti tenaga relawan, waktu luang, atau akses ke media sosial.
7. Berdasarkan jenis ancaman bencana:
Kegiatan sosialisasi dapat juga dipilah berdasarkan jenis ancaman bencana, misalnya sosialisasi penanggulangan bencana seperti gempa bumi, tsunami, letusan gunung api, banjir, tanah longsor, kekeringan, kebakaran bangunan, kebakaran hutan dan lahan, angin kencang, dan penyakit menular.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1584, 'Pesan-pesan yang disampaikan lebih berfokus pada kebutuhan dan tantangan yang dihadapi oleh kelompok rentan, serta langkah-langkah khusus yang dapat mereka ambil dalam menghadapi bencana. Terkait pelibatan kelompok rentan atau berisiko tinggi, terdapat tahapan-tahapan spesifik yang perlu dilakukan untuk mendorong partisipasi bermakna. Tahapan yang lebih detail akan diatur dalam panduan teknis.
6. Berdasarkan pembiayaan:
a. Sosialisasi dengan pembiayaan: sosialisasi ini melibatkan penggunaan dana atau sumber daya finansial yang ditentukan secara khusus untuk kegiatan sosialisasi penanggulangan bencana.
Dana ini dapat berasal dari anggaran pemerintah, sumbangan dari lembaga donor, atau sumber pembiayaan lainnya yang dialokasikan secara eksplisit untuk kegiatan sosialisasi
b. Sosialisasi tidak dengan pembiayaan: sosialisasi ini dilakukan tanpa keterlibatan dana atau sumber daya finansial yang khusus dialokasikan untuk kegiatan sosialisasi. Meskipun demikian, kegiatan ini masih dapat mengandalkan sumber daya internal institusi, organisasi, atau komunitas, seperti tenaga relawan, waktu luang, atau akses ke media sosial.
7. Berdasarkan jenis ancaman bencana:
Kegiatan sosialisasi dapat juga dipilah berdasarkan jenis ancaman bencana, misalnya sosialisasi penanggulangan bencana seperti gempa bumi, tsunami, letusan gunung api, banjir, tanah longsor, kekeringan, kebakaran bangunan, kebakaran hutan dan lahan, angin kencang, dan penyakit menular.', 'BAB II (lanjutan 7)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1585, 'pedoman-3-2024', 21, 'lain', 'BAB II (lanjutan 8)', NULL, 10, 'Berdasarkan jenis sosialisasi tersebut, sosialisasi dapat dikombinasikan, misalnya sosialisasi penanggulangan bencana terkait mitigasi tsunami dapat dilakukan untuk kelompok masyarakat yang tinggal di daerah pesisir, secara luring, langsung, dan formal, dan menggunakan pembiayaan dari pemerintah daerah setempat. Salah satu contoh lainnya adalah sosialisasi bisa dilakukan kombinasi langsung dan tidak langsung, misalnya sosialisasi diawali dengan diseminasi flyer dan poster (sosialisasi tidak langsung) dan kemudian dilanjutkan dengan diskusi tatap muka bersama masyarakat/ kelompok sasaran (sosialisasi langsung).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1585, 'Berdasarkan jenis sosialisasi tersebut, sosialisasi dapat dikombinasikan, misalnya sosialisasi penanggulangan bencana terkait mitigasi tsunami dapat dilakukan untuk kelompok masyarakat yang tinggal di daerah pesisir, secara luring, langsung, dan formal, dan menggunakan pembiayaan dari pemerintah daerah setempat. Salah satu contoh lainnya adalah sosialisasi bisa dilakukan kombinasi langsung dan tidak langsung, misalnya sosialisasi diawali dengan diseminasi flyer dan poster (sosialisasi tidak langsung) dan kemudian dilanjutkan dengan diskusi tatap muka bersama masyarakat/ kelompok sasaran (sosialisasi langsung).', 'BAB II (lanjutan 8)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1586, 'pedoman-3-2024', 22, 'lain', 'BAB III', NULL, 11, 'PELAKSANAAN A. Penyelenggara Sosialisasi Pihak-pihak yang menyelenggarakan sosialisasi penanggulangan bencana, antara lain:
a. Badan Nasional Penanggulangan Bencana Sebagai lembaga pemerintah yang bertanggung jawab atas koordinasi, penyelenggaraan, dan pelaksanaan kebijakan penanggulangan bencana di tingkat nasional, BNPB memainkan peran sentral dalam menyelenggarakan sosialisasi penanggulangan bencana. BNPB mengkoordinasikan berbagai pihak terkait dan menyediakan pedoman serta arahan teknis terkait sosialisasi, serta melakukan sosialiasi penanggulangan bencana di tingkat nasional.
b. Lembaga Pemerintah Selain BNPB, ada berbagai lembaga pemerintah terkait lainnya yang turut terlibat dalam penyelenggaraan sosialisasi penanggulangan bencana, termasuk Badan Meteorologi, Klimatologi, dan Geofisika, Kementerian Sosial, Kementerian Kesehatan, Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi, Kementerian Lingkungan Hidup dan Kehutanan, Kementerian Energi dan Sumber Daya Mineral, dan lain-lain, yang memiliki peran spesifik dalam menyediakan informasi, bantuan, dan dukungan terkait penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1586, 'PELAKSANAAN A. Penyelenggara Sosialisasi Pihak-pihak yang menyelenggarakan sosialisasi penanggulangan bencana, antara lain:
a. Badan Nasional Penanggulangan Bencana Sebagai lembaga pemerintah yang bertanggung jawab atas koordinasi, penyelenggaraan, dan pelaksanaan kebijakan penanggulangan bencana di tingkat nasional, BNPB memainkan peran sentral dalam menyelenggarakan sosialisasi penanggulangan bencana. BNPB mengkoordinasikan berbagai pihak terkait dan menyediakan pedoman serta arahan teknis terkait sosialisasi, serta melakukan sosialiasi penanggulangan bencana di tingkat nasional.
b. Lembaga Pemerintah Selain BNPB, ada berbagai lembaga pemerintah terkait lainnya yang turut terlibat dalam penyelenggaraan sosialisasi penanggulangan bencana, termasuk Badan Meteorologi, Klimatologi, dan Geofisika, Kementerian Sosial, Kementerian Kesehatan, Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi, Kementerian Lingkungan Hidup dan Kehutanan, Kementerian Energi dan Sumber Daya Mineral, dan lain-lain, yang memiliki peran spesifik dalam menyediakan informasi, bantuan, dan dukungan terkait penanggulangan bencana.', 'BAB III', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1587, 'pedoman-3-2024', 23, 'lain', 'BAB III (lanjutan 1)', NULL, 11, 'c. Pemerintah Daerah Pemerintah daerah, seperti gubernur, bupati, dan walikota, memiliki peran penting dalam menyelenggarakan sosialisasi penanggulangan bencana di tingkat lokal. Pemerintah daerah bertanggung jawab untuk merumuskan kebijakan, perencanaan, dan program penanggulangan bencana yang sesuai dengan karakteristik dan kebutuhan wilayahnya, termasuk pelaksanaan sosialisasi kepada masyarakat setempat.
d. Badan Penanggulangan Bencana Daerah BPBD memiliki peran sentral dalam penyelenggaraan sosialisasi penanggulangan bencana di tingkat lokal dengan mengoordinasikan kegiatan sosialisasi, menyediakan panduan teknis, dan mengelola sumber daya yang ada. Selain itu, BPBD juga bertanggung jawab untuk merumuskan kebijakan, perencanaan, dan program penanggulangan bencana yang sesuai dengan karakteristik wilayahnya, serta memobilisasi partisipasi masyarakat dalam upaya penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1587, 'c. Pemerintah Daerah Pemerintah daerah, seperti gubernur, bupati, dan walikota, memiliki peran penting dalam menyelenggarakan sosialisasi penanggulangan bencana di tingkat lokal. Pemerintah daerah bertanggung jawab untuk merumuskan kebijakan, perencanaan, dan program penanggulangan bencana yang sesuai dengan karakteristik dan kebutuhan wilayahnya, termasuk pelaksanaan sosialisasi kepada masyarakat setempat.
d. Badan Penanggulangan Bencana Daerah BPBD memiliki peran sentral dalam penyelenggaraan sosialisasi penanggulangan bencana di tingkat lokal dengan mengoordinasikan kegiatan sosialisasi, menyediakan panduan teknis, dan mengelola sumber daya yang ada. Selain itu, BPBD juga bertanggung jawab untuk merumuskan kebijakan, perencanaan, dan program penanggulangan bencana yang sesuai dengan karakteristik wilayahnya, serta memobilisasi partisipasi masyarakat dalam upaya penanggulangan bencana.', 'BAB III (lanjutan 1)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1588, 'pedoman-3-2024', 24, 'lain', 'BAB III (lanjutan 2)', NULL, 12, 'e. Perguruan Tinggi dan Lembaga Penelitian Perguruan Tinggi dan Lembaga Penelitian memiliki peran dalam menyediakan dasar ilmiah yang kuat melalui penelitian dan analisis, serta kontribusi dalam pembangunan kurikulum, materi pembelajaran, dan program pelatihan masyarakat. Institusi ini juga dapat memberikan konsultasi dan bimbingan teknis kepada pemerintah dan organisasi masyarakat dalam merancang program sosialisasi yang efektif, serta berperan sebagai pusat penyebaran informasi dan edukasi tentang bencana melalui publikasi ilmiah, seminar, dan media sosial, sehingga memastikan pesan-pesan sosialisasi berbasis bukti dan kredibel dapat disampaikan kepada masyarakat, membantu meningkatkan kesadaran dan kesiapsiagaan masyarakat dalam menghadapi ancaman bencana.
f. Lembaga Swadaya Masyarakat (LSM), Palang Merah Indonesia (PMI), dan Organisasi Non-Pemerintah lainnya LSM, PMI, dan organisasi non-pemerintah lainnya memiliki peran dalam mendukung penyelenggaraan sosialisasi penanggulangan bencana di tingkat komunitas. Institusi ini dapat menyediakan sumber daya manusia, fasilitas, dan jaringan komunitas untuk mendukung pelaksanaan sosialisasi, serta memperkuat partisipasi masyarakat dalam upaya penanggulangan bencana. Lembaga yang fokus pada kelompok rentan tertentu perlu dilibatkan untuk memberikan masukan teknis dan arahan untuk partisipasi kelompok rentan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1588, 'e. Perguruan Tinggi dan Lembaga Penelitian Perguruan Tinggi dan Lembaga Penelitian memiliki peran dalam menyediakan dasar ilmiah yang kuat melalui penelitian dan analisis, serta kontribusi dalam pembangunan kurikulum, materi pembelajaran, dan program pelatihan masyarakat. Institusi ini juga dapat memberikan konsultasi dan bimbingan teknis kepada pemerintah dan organisasi masyarakat dalam merancang program sosialisasi yang efektif, serta berperan sebagai pusat penyebaran informasi dan edukasi tentang bencana melalui publikasi ilmiah, seminar, dan media sosial, sehingga memastikan pesan-pesan sosialisasi berbasis bukti dan kredibel dapat disampaikan kepada masyarakat, membantu meningkatkan kesadaran dan kesiapsiagaan masyarakat dalam menghadapi ancaman bencana.
f. Lembaga Swadaya Masyarakat (LSM), Palang Merah Indonesia (PMI), dan Organisasi Non-Pemerintah lainnya LSM, PMI, dan organisasi non-pemerintah lainnya memiliki peran dalam mendukung penyelenggaraan sosialisasi penanggulangan bencana di tingkat komunitas. Institusi ini dapat menyediakan sumber daya manusia, fasilitas, dan jaringan komunitas untuk mendukung pelaksanaan sosialisasi, serta memperkuat partisipasi masyarakat dalam upaya penanggulangan bencana. Lembaga yang fokus pada kelompok rentan tertentu perlu dilibatkan untuk memberikan masukan teknis dan arahan untuk partisipasi kelompok rentan.', 'BAB III (lanjutan 2)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1589, 'pedoman-3-2024', 25, 'lain', 'BAB III (lanjutan 3)', NULL, 12, 'g. Tokoh Masyarakat (termasuk tokoh agama, pemengaruh atau influencer, dan tokoh lainnya) Tokoh masyarakat, termasuk tokoh agama, pemengaruh atau influencer, dan lainnya, memegang peran penting dalam sosialisasi penanggulangan bencana. Mereka menjadi agen perubahan yang memotivasi aksi-aksi terkait penanggulangan bencana, menyampaikan informasi risiko, dan memberikan dukungan moral dan spiritual.
Dengan otoritas dan jaringan mereka, tokoh masyarakat memfasilitasi komunikasi dan koordinasi antar komunitas serta lembaga terkait, sambil memberikan contoh praktik kebencanaan yang aman. Ini membantu memperkuat norma keselamatan dan solidaritas dalam komunitas. Tokoh masyarakat, dengan sumber daya dan relasi yang mereka miliki, dapat menyadarkan masyarakat akan pentingnya penanggulangan bencana dan juga memanfaatkan jaringan dan hubungan mereka untuk menghubungkan komunitas dengan sumber daya eksternal dan membantu memfasilitasi komunikasi serta koordinasi antar anggota komunitas, pemerintah, dan pihak lain yang terlibat dalam upaya penanggulangan bencana.
h. Media Massa Media massa menyediakan platform yang luas untuk menyampaikan informasi dan pesan-pesan kesiapsiagaan kepada masyarakat. Melalui liputan berita, konferensi pers, program edukasi, dan kampanye sosial, atau upaya lainnya, media massa dapat meningkatkan kesadaran publik tentang potensi ancaman bencana, tindakan mitigasi yang dapat diambil, dan langkah-langkah kesiapsiagaan yang diperlukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1589, 'g. Tokoh Masyarakat (termasuk tokoh agama, pemengaruh atau influencer, dan tokoh lainnya) Tokoh masyarakat, termasuk tokoh agama, pemengaruh atau influencer, dan lainnya, memegang peran penting dalam sosialisasi penanggulangan bencana. Mereka menjadi agen perubahan yang memotivasi aksi-aksi terkait penanggulangan bencana, menyampaikan informasi risiko, dan memberikan dukungan moral dan spiritual.
Dengan otoritas dan jaringan mereka, tokoh masyarakat memfasilitasi komunikasi dan koordinasi antar komunitas serta lembaga terkait, sambil memberikan contoh praktik kebencanaan yang aman. Ini membantu memperkuat norma keselamatan dan solidaritas dalam komunitas. Tokoh masyarakat, dengan sumber daya dan relasi yang mereka miliki, dapat menyadarkan masyarakat akan pentingnya penanggulangan bencana dan juga memanfaatkan jaringan dan hubungan mereka untuk menghubungkan komunitas dengan sumber daya eksternal dan membantu memfasilitasi komunikasi serta koordinasi antar anggota komunitas, pemerintah, dan pihak lain yang terlibat dalam upaya penanggulangan bencana.
h. Media Massa Media massa menyediakan platform yang luas untuk menyampaikan informasi dan pesan-pesan kesiapsiagaan kepada masyarakat. Melalui liputan berita, konferensi pers, program edukasi, dan kampanye sosial, atau upaya lainnya, media massa dapat meningkatkan kesadaran publik tentang potensi ancaman bencana, tindakan mitigasi yang dapat diambil, dan langkah-langkah kesiapsiagaan yang diperlukan.', 'BAB III (lanjutan 3)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1590, 'pedoman-3-2024', 26, 'lain', 'BAB III (lanjutan 4)', NULL, 12, 'Dalam kegiatan sosialisasi bersama media massa, bagian Humas dari Pemerintah Daerah dapat juga terlibat untuk meningkatkan efektifitas sosialisasi. Selain itu, media massa memiliki peran dalam menyediakan liputan berita yang akurat, terpercaya, dan terkini tentang perkembangan bencana, serta menyebarkan informasi resmi dan pesan kesiapsiagaan dari otoritas terkait kepada masyarakat luas.
Dengan demikian, media massa dapat menyampaikan informasi secara luas dan cepat, serta memudahkan mobilisasi partisipasi masyarakat dan meningkatkan respon terhadap ancaman bencana.
B. Kelompok Sasaran Kelompok sasaran sosialiasi penanggulangan bencana dapat dikategorikan berdasarkan, sebagai berikut:
a. Kelompok Umur Kelompok umur merupakan salah satu kriteria penting dalam menentukan kelompok sasaran sosialisasi penanggulangan bencana.
Hal ini termasuk anak-anak (termasuk anak usia dini), remaja, orang dewasa, dan lansia. Setiap kelompok umur memiliki kebutuhan dan karakteristik yang berbeda dalam menghadapi bencana, serta memiliki preferensi tersendiri dalam mengikuti proses sosialiasi. Misalnya, anak-anak cenderung lebih efektif menggunakan pendekatan bermain dan menggunakan visual yang atraktif dalam sosialisasi, sementara lansia mungkin memerlukan informasi yang lebih rinci tentang cara melindungi diri mereka sendiri.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1590, 'Dalam kegiatan sosialisasi bersama media massa, bagian Humas dari Pemerintah Daerah dapat juga terlibat untuk meningkatkan efektifitas sosialisasi. Selain itu, media massa memiliki peran dalam menyediakan liputan berita yang akurat, terpercaya, dan terkini tentang perkembangan bencana, serta menyebarkan informasi resmi dan pesan kesiapsiagaan dari otoritas terkait kepada masyarakat luas.
Dengan demikian, media massa dapat menyampaikan informasi secara luas dan cepat, serta memudahkan mobilisasi partisipasi masyarakat dan meningkatkan respon terhadap ancaman bencana.
B. Kelompok Sasaran Kelompok sasaran sosialiasi penanggulangan bencana dapat dikategorikan berdasarkan, sebagai berikut:
a. Kelompok Umur Kelompok umur merupakan salah satu kriteria penting dalam menentukan kelompok sasaran sosialisasi penanggulangan bencana.
Hal ini termasuk anak-anak (termasuk anak usia dini), remaja, orang dewasa, dan lansia. Setiap kelompok umur memiliki kebutuhan dan karakteristik yang berbeda dalam menghadapi bencana, serta memiliki preferensi tersendiri dalam mengikuti proses sosialiasi. Misalnya, anak-anak cenderung lebih efektif menggunakan pendekatan bermain dan menggunakan visual yang atraktif dalam sosialisasi, sementara lansia mungkin memerlukan informasi yang lebih rinci tentang cara melindungi diri mereka sendiri.', 'BAB III (lanjutan 4)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1591, 'pedoman-3-2024', 27, 'lain', 'BAB III (lanjutan 5)', NULL, 13, 'b. Karakteristik Wilayah Karakteristik wilayah, seperti geografi, topografi, iklim, dan tingkat kerentanan terhadap bencana, juga harus dipertimbangkan dalam menentukan kelompok sasaran sosialisasi. Daerah yang rentan terhadap gempa bumi mungkin memerlukan pendekatan yang berbeda dibandingkan dengan daerah yang rentan terhadap banjir atau tanah longsor. Selain itu, daerah perkotaan dan pedesaan mungkin memiliki kebutuhan yang berbeda dalam hal penanggulangan bencana.
c. Ragam Profesi Ragam profesi dan pekerjaan juga merupakan faktor penting dalam menentukan kelompok sasaran sosialisasi. Ini termasuk petani, nelayan, pekerja industri, guru, petugas kesehatan, dan lain-lain. Setiap profesi mungkin memiliki kebutuhan yang unik dalam menghadapi bencana, dan sosialisasi harus disesuaikan dengan kebutuhan masing-masing. Misalnya, petani mungkin memerlukan informasi tentang cara melindungi tanaman mereka dari ancaman kekeringan atau cuaca ekstrem lainnya, sementara petugas kesehatan mungkin memerlukan pelatihan tentang pertolongan pertama dan evakuasi saat darurat bencana.
d. Faktor Lainnya Selain itu, ada faktor khusus lainnya yang juga perlu dipertimbangkan dalam menentukan kelompok sasaran sosialisasi, seperti penyandang disabilitas, ibu hamil, ibu menyusui, kelompok etnis minoritas, dan kelompok rentan lainnya. Kelompok-kelompok ini mungkin memiliki kebutuhan yang lebih spesifik dan perlu perhatian khusus dalam proses sosialisasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1591, 'b. Karakteristik Wilayah Karakteristik wilayah, seperti geografi, topografi, iklim, dan tingkat kerentanan terhadap bencana, juga harus dipertimbangkan dalam menentukan kelompok sasaran sosialisasi. Daerah yang rentan terhadap gempa bumi mungkin memerlukan pendekatan yang berbeda dibandingkan dengan daerah yang rentan terhadap banjir atau tanah longsor. Selain itu, daerah perkotaan dan pedesaan mungkin memiliki kebutuhan yang berbeda dalam hal penanggulangan bencana.
c. Ragam Profesi Ragam profesi dan pekerjaan juga merupakan faktor penting dalam menentukan kelompok sasaran sosialisasi. Ini termasuk petani, nelayan, pekerja industri, guru, petugas kesehatan, dan lain-lain. Setiap profesi mungkin memiliki kebutuhan yang unik dalam menghadapi bencana, dan sosialisasi harus disesuaikan dengan kebutuhan masing-masing. Misalnya, petani mungkin memerlukan informasi tentang cara melindungi tanaman mereka dari ancaman kekeringan atau cuaca ekstrem lainnya, sementara petugas kesehatan mungkin memerlukan pelatihan tentang pertolongan pertama dan evakuasi saat darurat bencana.
d. Faktor Lainnya Selain itu, ada faktor khusus lainnya yang juga perlu dipertimbangkan dalam menentukan kelompok sasaran sosialisasi, seperti penyandang disabilitas, ibu hamil, ibu menyusui, kelompok etnis minoritas, dan kelompok rentan lainnya. Kelompok-kelompok ini mungkin memiliki kebutuhan yang lebih spesifik dan perlu perhatian khusus dalam proses sosialisasi.', 'BAB III (lanjutan 5)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1592, 'pedoman-3-2024', 28, 'lain', 'BAB III (lanjutan 6)', NULL, 14, 'C. Penentuan Waktu, Durasi, dan Lokasi Sosialisasi Dalam melaksanakan sosialisasi juga harus menentukan waktu, durasi dan lokasi sosialisasi.
1. Waktu Sosialisasi Dalam proses sosialisasi penanggulangan bencana, penting untuk memperhatikan waktu yang tepat untuk melakukan sosialisasi yang efektif. Pemilihan waktu yang tepat dapat memaksimalkan tingkat keterlibatan dan respon peserta, serta memastikan pesan-pesan yang disampaikan dapat diterima dengan baik oleh kelompok sasaran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1592, 'C. Penentuan Waktu, Durasi, dan Lokasi Sosialisasi Dalam melaksanakan sosialisasi juga harus menentukan waktu, durasi dan lokasi sosialisasi.
1. Waktu Sosialisasi Dalam proses sosialisasi penanggulangan bencana, penting untuk memperhatikan waktu yang tepat untuk melakukan sosialisasi yang efektif. Pemilihan waktu yang tepat dapat memaksimalkan tingkat keterlibatan dan respon peserta, serta memastikan pesan-pesan yang disampaikan dapat diterima dengan baik oleh kelompok sasaran.', 'BAB III (lanjutan 6)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1593, 'pedoman-3-2024', 29, 'lain', 'BAB III (lanjutan 7)', NULL, 14, 'Dalam menentukan waktu sosialisasi memperhatikan hal-hal sebagai berikut: a) Kelompok Umur Waktu sosialisasi perlu disesuaikan dengan karakteristik umur kelompok sasaran. Misalnya, sosialisasi untuk anak-anak mungkin lebih efektif dilakukan pada saat-saat setelah sekolah, saat masa orientasi sekolah, atau saat mereka sedang bermain, sementara sosialisasi untuk lansia dapat dipilih pada waktu yang lebih santai dan nyaman bagi mereka. b) Ragam Profesi Berdasarkan ragam profesi kelompok sasaran, waktu sosialisasi dapat disesuaikan dengan jadwal kerja atau aktivitas sehari-hari mereka. Misalnya, sosialisasi untuk petani bisa dilakukan pada waktu yang tidak bertepatan dengan waktu panen atau penanaman, sementara sosialisasi untuk pekerja kantor bisa dilakukan pada jam istirahat atau setelah jam kerja. c) Faktor-faktor Lainnya termasuk karakteristik wilayah Selain itu, faktor-faktor lain seperti kebiasaan lokal, acara komunitas, kegiatan religi, dan musim atau kondisi cuaca, serta perbedaan zona waktu juga perlu dipertimbangkan dalam menentukan waktu sosialisasi yang tepat. Pemahaman mendalam tentang konteks lokal dan kebutuhan kelompok sasaran akan membantu dalam menentukan waktu yang paling sesuai untuk melakukan sosialisasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1593, 'Dalam menentukan waktu sosialisasi memperhatikan hal-hal sebagai berikut: a) Kelompok Umur Waktu sosialisasi perlu disesuaikan dengan karakteristik umur kelompok sasaran. Misalnya, sosialisasi untuk anak-anak mungkin lebih efektif dilakukan pada saat-saat setelah sekolah, saat masa orientasi sekolah, atau saat mereka sedang bermain, sementara sosialisasi untuk lansia dapat dipilih pada waktu yang lebih santai dan nyaman bagi mereka. b) Ragam Profesi Berdasarkan ragam profesi kelompok sasaran, waktu sosialisasi dapat disesuaikan dengan jadwal kerja atau aktivitas sehari-hari mereka. Misalnya, sosialisasi untuk petani bisa dilakukan pada waktu yang tidak bertepatan dengan waktu panen atau penanaman, sementara sosialisasi untuk pekerja kantor bisa dilakukan pada jam istirahat atau setelah jam kerja. c) Faktor-faktor Lainnya termasuk karakteristik wilayah Selain itu, faktor-faktor lain seperti kebiasaan lokal, acara komunitas, kegiatan religi, dan musim atau kondisi cuaca, serta perbedaan zona waktu juga perlu dipertimbangkan dalam menentukan waktu sosialisasi yang tepat. Pemahaman mendalam tentang konteks lokal dan kebutuhan kelompok sasaran akan membantu dalam menentukan waktu yang paling sesuai untuk melakukan sosialisasi.', 'BAB III (lanjutan 7)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1594, 'pedoman-3-2024', 30, 'lain', 'BAB III (lanjutan 8)', NULL, 14, '2. Durasi Sosialiasi Selain memperhatikan waktu yang tepat untuk melakukan sosialisasi, penting juga untuk memperhitungkan durasi sosialisasi yang sesuai dengan karakteristik kelompok sasaran. Durasi sosialisasi yang tepat dapat memastikan pesan-pesan yang disampaikan dapat diserap dengan baik oleh peserta, tanpa mengganggu keseharian mereka.
Dalam menentukan durasi sosialisasi memperhatikan hal-hal sebagai berikut: a) Kelompok Umur Durasi sosialisasi perlu disesuaikan dengan rentang perhatian dan konsentrasi yang dimiliki oleh kelompok umur yang dituju.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1594, '2. Durasi Sosialiasi Selain memperhatikan waktu yang tepat untuk melakukan sosialisasi, penting juga untuk memperhitungkan durasi sosialisasi yang sesuai dengan karakteristik kelompok sasaran. Durasi sosialisasi yang tepat dapat memastikan pesan-pesan yang disampaikan dapat diserap dengan baik oleh peserta, tanpa mengganggu keseharian mereka.
Dalam menentukan durasi sosialisasi memperhatikan hal-hal sebagai berikut: a) Kelompok Umur Durasi sosialisasi perlu disesuaikan dengan rentang perhatian dan konsentrasi yang dimiliki oleh kelompok umur yang dituju.', 'BAB III (lanjutan 8)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1595, 'pedoman-3-2024', 31, 'lain', 'BAB III (lanjutan 9)', NULL, 14, 'Misalnya, sosialisasi untuk anak-anak mungkin perlu disesuaikan dengan durasi yang lebih singkat namun sering/ beberapa kali dan diselingi dengan aktivitas yang menarik perhatian mereka, sementara sosialisasi untuk orang dewasa bisa memiliki durasi yang lebih panjang. b) Ragam Profesi Berdasarkan ragam profesi kelompok sasaran, durasi sosialisasi perlu dipertimbangkan agar tidak mengganggu jadwal kerja atau aktivitas sehari-hari mereka. Misalnya, sosialisasi untuk petani mungkin perlu dilakukan dalam sesi yang singkat dan efisien, sementara sosialisasi untuk pekerja kantor bisa memiliki durasi yang lebih fleksibel. c) Faktor-faktor Lainnya termasuk karakteristik wilayah Selain itu, faktor-faktor seperti tingkat pendidikan, tingkat literasi, dan bahasa yang digunakan juga perlu dipertimbangkan dalam menentukan durasi sosialisasi yang tepat. Misalnya, sosialisasi untuk kelompok dengan tingkat pendidikan rendah mungkin memerlukan penjelasan yang lebih sederhana dan durasi yang lebih singkat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1595, 'Misalnya, sosialisasi untuk anak-anak mungkin perlu disesuaikan dengan durasi yang lebih singkat namun sering/ beberapa kali dan diselingi dengan aktivitas yang menarik perhatian mereka, sementara sosialisasi untuk orang dewasa bisa memiliki durasi yang lebih panjang. b) Ragam Profesi Berdasarkan ragam profesi kelompok sasaran, durasi sosialisasi perlu dipertimbangkan agar tidak mengganggu jadwal kerja atau aktivitas sehari-hari mereka. Misalnya, sosialisasi untuk petani mungkin perlu dilakukan dalam sesi yang singkat dan efisien, sementara sosialisasi untuk pekerja kantor bisa memiliki durasi yang lebih fleksibel. c) Faktor-faktor Lainnya termasuk karakteristik wilayah Selain itu, faktor-faktor seperti tingkat pendidikan, tingkat literasi, dan bahasa yang digunakan juga perlu dipertimbangkan dalam menentukan durasi sosialisasi yang tepat. Misalnya, sosialisasi untuk kelompok dengan tingkat pendidikan rendah mungkin memerlukan penjelasan yang lebih sederhana dan durasi yang lebih singkat.', 'BAB III (lanjutan 9)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1596, 'pedoman-3-2024', 32, 'lain', 'BAB III (lanjutan 10)', NULL, 15, 'Berbagai faktor ini perlu menjadi pertimbangan dalam memilih waktu dan durasi yang tepat untuk melakukan sosialisasi, pihak penyelenggara dapat meningkatkan efektivitas sosialisasi penanggulangan bencana dan memastikan pesan-pesan yang disampaikan dapat diterima dengan baik oleh kelompok sasaran, tanpa mengganggu aktivitas sehari-hari mereka. Hal ini akan membantu meningkatkan kesadaran, pengetahuan, dan kesiapsiagaan masyarakat dalam menghadapi ancaman bencana, serta meminimalkan dampak negatif yang ditimbulkan oleh bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1596, 'Berbagai faktor ini perlu menjadi pertimbangan dalam memilih waktu dan durasi yang tepat untuk melakukan sosialisasi, pihak penyelenggara dapat meningkatkan efektivitas sosialisasi penanggulangan bencana dan memastikan pesan-pesan yang disampaikan dapat diterima dengan baik oleh kelompok sasaran, tanpa mengganggu aktivitas sehari-hari mereka. Hal ini akan membantu meningkatkan kesadaran, pengetahuan, dan kesiapsiagaan masyarakat dalam menghadapi ancaman bencana, serta meminimalkan dampak negatif yang ditimbulkan oleh bencana.', 'BAB III (lanjutan 10)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1597, 'pedoman-3-2024', 33, 'lain', 'BAB III (lanjutan 11)', NULL, 15, '3. Pemilihan Lokasi Pemilihan lokasi sosialisasi merupakan faktor kunci dalam keberhasilan sosialisasi penanggulangan bencana. Dengan pemilihan lokasi yang tepat, dapat meningkatkan keterlibatan dan respon peserta, serta memastikan pesan-pesan yang disampaikan dapat diterima dengan baik oleh kelompok sasaran. Dalam penentuan lokasi sosialisasi memperhatikan hal-hal sebagai berikut: a) Aksesibilitas Lokasi sosialisasi harus mudah diakses oleh kelompok sasaran baik laki-laki maupun perempuan, terutama mereka yang mungkin memiliki keterbatasan mobilitas (lansia, ibu hamil dan menyusui, anak-anak, dan penyandang disabilitas) atau transportasi (termasuk akses jalan). Memilih lokasi yang terletak di pusat komunitas atau dekat dengan tempat tinggal atau tempat kerja peserta dapat meningkatkan partisipasi dan keterlibatan mereka dalam sosialisasi. Lokasi sosialisasi juga perlu disesuaikan bila ada peserta yang merupakan penyandang disabilitas, sehingga aksesibilitas perlu disesuaikan dengan jenis disabilitas yang dimiliki oleh peserta. Saat kegiatan tatap muka ataupun daring, tetap perlu memperhatikan kebutuhan kelompok rentan, misalnya ketersediaan Juru Bahasa Isyarat (JBI), dan pemilihan jenis huruf dalam presentasi. b) Kenyamanan dan Keamanan Lokasi sosialisasi harus memberikan kenyamanan dan rasa aman bagi peserta.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1597, '3. Pemilihan Lokasi Pemilihan lokasi sosialisasi merupakan faktor kunci dalam keberhasilan sosialisasi penanggulangan bencana. Dengan pemilihan lokasi yang tepat, dapat meningkatkan keterlibatan dan respon peserta, serta memastikan pesan-pesan yang disampaikan dapat diterima dengan baik oleh kelompok sasaran. Dalam penentuan lokasi sosialisasi memperhatikan hal-hal sebagai berikut: a) Aksesibilitas Lokasi sosialisasi harus mudah diakses oleh kelompok sasaran baik laki-laki maupun perempuan, terutama mereka yang mungkin memiliki keterbatasan mobilitas (lansia, ibu hamil dan menyusui, anak-anak, dan penyandang disabilitas) atau transportasi (termasuk akses jalan). Memilih lokasi yang terletak di pusat komunitas atau dekat dengan tempat tinggal atau tempat kerja peserta dapat meningkatkan partisipasi dan keterlibatan mereka dalam sosialisasi. Lokasi sosialisasi juga perlu disesuaikan bila ada peserta yang merupakan penyandang disabilitas, sehingga aksesibilitas perlu disesuaikan dengan jenis disabilitas yang dimiliki oleh peserta. Saat kegiatan tatap muka ataupun daring, tetap perlu memperhatikan kebutuhan kelompok rentan, misalnya ketersediaan Juru Bahasa Isyarat (JBI), dan pemilihan jenis huruf dalam presentasi. b) Kenyamanan dan Keamanan Lokasi sosialisasi harus memberikan kenyamanan dan rasa aman bagi peserta.', 'BAB III (lanjutan 11)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1598, 'pedoman-3-2024', 34, 'lain', 'BAB III (lanjutan 12)', NULL, 15, 'Ini dapat mencakup pemilihan ruangan yang nyaman, bebas dari gangguan atau kebisingan yang mengganggu, serta lingkungan yang aman dari ancaman potensial seperti cuaca buruk atau gangguan keamanan. c) Relevansi pada Konteks Lokasi sosialisasi harus relevan dengan konteks dan kebutuhan kelompok sasaran. Misalnya, untuk sosialisasi kepada petani, memilih lokasi yang berada di dekat area pertanian atau lahan pertanian akan meningkatkan relevansi pesan yang disampaikan dan memudahkan peserta untuk menerapkan informasi yang diberikan. Sosialisasi untuk anak-anak umumnya akan lebih efektif bila dilakukan di satuan pendidikan, seperti misalnya di sekolah, madrasah, pesantren, atau kelompok belajar. d) Kesesuaian Fasilitas Lokasi sosialisasi harus dilengkapi dengan fasilitas yang sesuai dengan kebutuhan peserta dan kegiatan sosialisasi. Ini termasuk fasilitas audio visual, toilet, tempat parkir, dan fasilitas lainnya yang dapat mendukung pelaksanaan sosialisasi dengan lancar. e) Ketersediaan Sumber Daya Lokasi sosialisasi harus memiliki ketersediaan sumber daya yang diperlukan untuk mendukung kegiatan sosialisasi, seperti listrik, air bersih, dan perlengkapan presentasi atau demonstrasi.
Memastikan ketersediaan sumber daya ini akan membantu kelancaran pelaksanaan sosialisasi dan meningkatkan efektivitas pesan yang disampaikan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1598, 'Ini dapat mencakup pemilihan ruangan yang nyaman, bebas dari gangguan atau kebisingan yang mengganggu, serta lingkungan yang aman dari ancaman potensial seperti cuaca buruk atau gangguan keamanan. c) Relevansi pada Konteks Lokasi sosialisasi harus relevan dengan konteks dan kebutuhan kelompok sasaran. Misalnya, untuk sosialisasi kepada petani, memilih lokasi yang berada di dekat area pertanian atau lahan pertanian akan meningkatkan relevansi pesan yang disampaikan dan memudahkan peserta untuk menerapkan informasi yang diberikan. Sosialisasi untuk anak-anak umumnya akan lebih efektif bila dilakukan di satuan pendidikan, seperti misalnya di sekolah, madrasah, pesantren, atau kelompok belajar. d) Kesesuaian Fasilitas Lokasi sosialisasi harus dilengkapi dengan fasilitas yang sesuai dengan kebutuhan peserta dan kegiatan sosialisasi. Ini termasuk fasilitas audio visual, toilet, tempat parkir, dan fasilitas lainnya yang dapat mendukung pelaksanaan sosialisasi dengan lancar. e) Ketersediaan Sumber Daya Lokasi sosialisasi harus memiliki ketersediaan sumber daya yang diperlukan untuk mendukung kegiatan sosialisasi, seperti listrik, air bersih, dan perlengkapan presentasi atau demonstrasi.
Memastikan ketersediaan sumber daya ini akan membantu kelancaran pelaksanaan sosialisasi dan meningkatkan efektivitas pesan yang disampaikan.', 'BAB III (lanjutan 12)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1599, 'pedoman-3-2024', 35, 'lain', 'BAB III (lanjutan 13)', NULL, 16, 'D. Media Pendukung Sosialisasi Dalam melaksanakan sosialisasi juga diperlukan media bantu. Media bantu merupakan alat atau sarana yang digunakan untuk menyampaikan pesan-pesan sosialisasi penanggulangan bencana kepada masyarakat.
Pemilihan jenis media bantu yang tepat akan sangat mempengaruhi efektivitas dan dampak dari sosialisasi tersebut.
Jenis media bantu yang umum digunakan, sebagai berikut:
1. Media Visual Media visual seperti poster, spanduk, brosur, buku panduan, dan leaflet merupakan alat yang efektif untuk menyampaikan informasi secara cepat dan mudah dipahami oleh masyarakat. Desain yang menarik dan informasi yang jelas dapat meningkatkan daya tarik dan kesan pesan yang disampaikan.
2. Media Audio Media audio seperti radio, pengeras suara, dan siaran televisi dapat digunakan untuk menyampaikan pesan-pesan sosialisasi secara verbal kepada masyarakat. Suara dan musik dapat digunakan untuk menarik perhatian dan meningkatkan daya ingat pesan yang disampaikan.
3. Media Audio Visual Media audio visual seperti video, film pendek, dan presentasi multimedia merupakan kombinasi dari media visual dan audio yang dapat menyajikan informasi dengan lebih dinamis dan menarik.
Penggunaan gambar, video, dan animasi dapat membantu masyarakat untuk lebih memahami konsep-konsep penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1599, 'D. Media Pendukung Sosialisasi Dalam melaksanakan sosialisasi juga diperlukan media bantu. Media bantu merupakan alat atau sarana yang digunakan untuk menyampaikan pesan-pesan sosialisasi penanggulangan bencana kepada masyarakat.
Pemilihan jenis media bantu yang tepat akan sangat mempengaruhi efektivitas dan dampak dari sosialisasi tersebut.
Jenis media bantu yang umum digunakan, sebagai berikut:
1. Media Visual Media visual seperti poster, spanduk, brosur, buku panduan, dan leaflet merupakan alat yang efektif untuk menyampaikan informasi secara cepat dan mudah dipahami oleh masyarakat. Desain yang menarik dan informasi yang jelas dapat meningkatkan daya tarik dan kesan pesan yang disampaikan.
2. Media Audio Media audio seperti radio, pengeras suara, dan siaran televisi dapat digunakan untuk menyampaikan pesan-pesan sosialisasi secara verbal kepada masyarakat. Suara dan musik dapat digunakan untuk menarik perhatian dan meningkatkan daya ingat pesan yang disampaikan.
3. Media Audio Visual Media audio visual seperti video, film pendek, dan presentasi multimedia merupakan kombinasi dari media visual dan audio yang dapat menyajikan informasi dengan lebih dinamis dan menarik.
Penggunaan gambar, video, dan animasi dapat membantu masyarakat untuk lebih memahami konsep-konsep penanggulangan bencana.', 'BAB III (lanjutan 13)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1600, 'pedoman-3-2024', 36, 'lain', 'BAB III (lanjutan 14)', NULL, 17, '4. Media Interaktif Media interaktif seperti aplikasi seluler, situs web interaktif, dan permainan edukatif dapat meningkatkan keterlibatan dan partisipasi masyarakat dalam proses sosialisasi. Fitur-fitur interaktif seperti kuis, simulasi, mendongeng, dan forum diskusi dapat memperkuat pemahaman dan kesiapsiagaan masyarakat terhadap bencana.
5. Media Sosial Media sosial seperti Facebook, Twitter (atau X), Instagram, dan juga aplikasi pesan singkat seperti WhatsApp atau Telegram merupakan platform yang dapat digunakan untuk menyebarkan informasi secara luas dan cepat kepada masyarakat. Kampanye sosial, diskusi online, dan seruan aksi secara online adalah beberapa contoh kegiatan yang dapat dilakukan memperkuat kesadaran dan partisipasi masyarakat dalam upaya penanggulangan bencana.
6. Media Massa Media massa seperti koran, majalah, buletin komunitas, serta berita online dapat menjadi sumber informasi yang dapat diakses secara mandiri oleh masyarakat. Konten yang berkualitas dan terpercaya dapat meningkatkan pengetahuan dan kesiapsiagaan masyarakat terhadap bencana.
Dengan mempertimbangkan berbagai jenis media bantu yang tersedia, pihak penyelenggara dapat memilih kombinasi media yang tepat dan sesuai dengan konteks lokal untuk mencapai kelompok sasaran secara efektif dan efisien. Adapun contoh media bantu sosialisasi dapat mengacu pada: https://bnpb.go.id/siaga-bencana.
E. Tahapan Dalam melaksanakan sosialisasi terdapat beberapa tahapan yang perlu dilakukan, antara lain:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1600, '4. Media Interaktif Media interaktif seperti aplikasi seluler, situs web interaktif, dan permainan edukatif dapat meningkatkan keterlibatan dan partisipasi masyarakat dalam proses sosialisasi. Fitur-fitur interaktif seperti kuis, simulasi, mendongeng, dan forum diskusi dapat memperkuat pemahaman dan kesiapsiagaan masyarakat terhadap bencana.
5. Media Sosial Media sosial seperti Facebook, Twitter (atau X), Instagram, dan juga aplikasi pesan singkat seperti WhatsApp atau Telegram merupakan platform yang dapat digunakan untuk menyebarkan informasi secara luas dan cepat kepada masyarakat. Kampanye sosial, diskusi online, dan seruan aksi secara online adalah beberapa contoh kegiatan yang dapat dilakukan memperkuat kesadaran dan partisipasi masyarakat dalam upaya penanggulangan bencana.
6. Media Massa Media massa seperti koran, majalah, buletin komunitas, serta berita online dapat menjadi sumber informasi yang dapat diakses secara mandiri oleh masyarakat. Konten yang berkualitas dan terpercaya dapat meningkatkan pengetahuan dan kesiapsiagaan masyarakat terhadap bencana.
Dengan mempertimbangkan berbagai jenis media bantu yang tersedia, pihak penyelenggara dapat memilih kombinasi media yang tepat dan sesuai dengan konteks lokal untuk mencapai kelompok sasaran secara efektif dan efisien. Adapun contoh media bantu sosialisasi dapat mengacu pada: https://bnpb.go.id/siaga-bencana.
E. Tahapan Dalam melaksanakan sosialisasi terdapat beberapa tahapan yang perlu dilakukan, antara lain:', 'BAB III (lanjutan 14)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1601, 'pedoman-3-2024', 37, 'lain', 'BAB III (lanjutan 15)', NULL, 17, '1. Perencanaan
a. Penentuan Tujuan Sosialiasi Tentukan tujuan sosialisasi yang ingin dicapai, baik dalam hal peningkatan kesadaran, pengetahuan, atau keterampilan masyarakat terkait penanggulangan bencana. Lakukan konsultasi dengan perwakilan kelompok sasaran untuk menyusun rencana sosialisasi secara bersama.
b. Analisis Kelompok Sasaran Kenali kelompok sasaran yang akan dituju, termasuk karakteristik, kebutuhan, dan tingkat risiko bencana yang dihadapi.
c. Pengembangan Materi Tentukan materi sosialisasi yang relevan, jelas, dan mudah dimengerti oleh target audiens, termasuk penggunaan gambar, video, atau contoh kasus.
d. Identifikasi Metode Komunikasi Pilih metode komunikasi yang sesuai dengan karakteristik kelompok sasaran, seperti ceramah, pelatihan, diskusi kelompok, atau kampanye media sosial. Lihat bagian Jenis Sosialiasi yang terdapat pada Bab II untuk memilih metode, proses, dan karakteristik penyampaian yang sesuai dengan kelompok sasaran.
e. Penentuan Target Luaran (Output).
Tentukan target kegiatan sosialisasi yang dapat diukur secara kualitatif dan / atau kuantitatif.
f. Pembiayaan Rencanakan alokasi pembiayaan kegiatan yang bersumber dari APBN, APBD, dan sumber pendanaan lain yang sah dan tidak mengikat berdasarkan ketentuan peraturan perundang-undangan.
g. Koordinasi Multi Pihak Identifikasi lembaga-lembaga lainnya yang perlu dilibatkan untuk berbagi sumber daya yang ada dan berbagi peran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1601, '1. Perencanaan
a. Penentuan Tujuan Sosialiasi Tentukan tujuan sosialisasi yang ingin dicapai, baik dalam hal peningkatan kesadaran, pengetahuan, atau keterampilan masyarakat terkait penanggulangan bencana. Lakukan konsultasi dengan perwakilan kelompok sasaran untuk menyusun rencana sosialisasi secara bersama.
b. Analisis Kelompok Sasaran Kenali kelompok sasaran yang akan dituju, termasuk karakteristik, kebutuhan, dan tingkat risiko bencana yang dihadapi.
c. Pengembangan Materi Tentukan materi sosialisasi yang relevan, jelas, dan mudah dimengerti oleh target audiens, termasuk penggunaan gambar, video, atau contoh kasus.
d. Identifikasi Metode Komunikasi Pilih metode komunikasi yang sesuai dengan karakteristik kelompok sasaran, seperti ceramah, pelatihan, diskusi kelompok, atau kampanye media sosial. Lihat bagian Jenis Sosialiasi yang terdapat pada Bab II untuk memilih metode, proses, dan karakteristik penyampaian yang sesuai dengan kelompok sasaran.
e. Penentuan Target Luaran (Output).
Tentukan target kegiatan sosialisasi yang dapat diukur secara kualitatif dan / atau kuantitatif.
f. Pembiayaan Rencanakan alokasi pembiayaan kegiatan yang bersumber dari APBN, APBD, dan sumber pendanaan lain yang sah dan tidak mengikat berdasarkan ketentuan peraturan perundang-undangan.
g. Koordinasi Multi Pihak Identifikasi lembaga-lembaga lainnya yang perlu dilibatkan untuk berbagi sumber daya yang ada dan berbagi peran.', 'BAB III (lanjutan 15)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1602, 'pedoman-3-2024', 38, 'lain', 'BAB III (lanjutan 16)', NULL, 18, 'Pada tahap Perencanaan ini, pihak penyelenggara sosialisasi perlu menyusun Kerangka Acuan Kerja (KAK). KAK merupakan dokumen penting yang berfungsi sebagai panduan terstruktur dalam perencanaan dan pelaksanaan kegiatan sosialisasi penanggulangan bencana. Menyiapkan KAK di tahap persiapan adalah langkah krusial untuk memastikan bahwa kegiatan sosialisasi berjalan efektif, efisien, dan mencapai tujuan yang telah ditetapkan. Format dan contoh Kerangka Acuan Kerja (KAK) tercantum pada Lampiran pedoman ini.
2. Persiapan
a. Penjadwalan Kegiatan Tentukan jadwal dan lokasi kegiatan sosialisasi yang memungkinkan partisipasi maksimal dari kelompok sasaran dan koordinasi dengan pihak terkait lainnya.
b. Persiapan Peserta Informasikan kepada peserta tentang tujuan sosialisasi, yakni apa yang ingin dicapai dengan kegiatan tersebut. Uraikan secara jelas manfaat yang diharapkan dari partisipasi mereka dalam sosialisasi.
Berikan informasi terperinci mengenai jadwal kegiatan sosialisasi, termasuk tanggal, waktu, dan lokasi pelaksanaan. Pastikan agar jadwal tersebut dapat diakses dan dimengerti dengan baik oleh target peserta. Jelaskan pula kepada peserta mengenai sumber daya yang dibutuhkan selama kegiatan sosialisasi (daring dan/ atau luring), seperti ketersediaan akses internet, kehadiran dengan pakaian yang sesuai, atau membawa peralatan tulis. Pastikan agar peserta memahami persyaratan dan persiapan yang diperlukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1602, 'Pada tahap Perencanaan ini, pihak penyelenggara sosialisasi perlu menyusun Kerangka Acuan Kerja (KAK). KAK merupakan dokumen penting yang berfungsi sebagai panduan terstruktur dalam perencanaan dan pelaksanaan kegiatan sosialisasi penanggulangan bencana. Menyiapkan KAK di tahap persiapan adalah langkah krusial untuk memastikan bahwa kegiatan sosialisasi berjalan efektif, efisien, dan mencapai tujuan yang telah ditetapkan. Format dan contoh Kerangka Acuan Kerja (KAK) tercantum pada Lampiran pedoman ini.
2. Persiapan
a. Penjadwalan Kegiatan Tentukan jadwal dan lokasi kegiatan sosialisasi yang memungkinkan partisipasi maksimal dari kelompok sasaran dan koordinasi dengan pihak terkait lainnya.
b. Persiapan Peserta Informasikan kepada peserta tentang tujuan sosialisasi, yakni apa yang ingin dicapai dengan kegiatan tersebut. Uraikan secara jelas manfaat yang diharapkan dari partisipasi mereka dalam sosialisasi.
Berikan informasi terperinci mengenai jadwal kegiatan sosialisasi, termasuk tanggal, waktu, dan lokasi pelaksanaan. Pastikan agar jadwal tersebut dapat diakses dan dimengerti dengan baik oleh target peserta. Jelaskan pula kepada peserta mengenai sumber daya yang dibutuhkan selama kegiatan sosialisasi (daring dan/ atau luring), seperti ketersediaan akses internet, kehadiran dengan pakaian yang sesuai, atau membawa peralatan tulis. Pastikan agar peserta memahami persyaratan dan persiapan yang diperlukan.', 'BAB III (lanjutan 16)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1603, 'pedoman-3-2024', 39, 'lain', 'BAB III (lanjutan 17)', NULL, 18, 'c. Persiapan Sumber Daya Siapkan fasilitas, materi sosialisasi, media (cetak dan/ atau elektronik) dan tenaga pendukung (termasuk narasumber, fasilitator, dan/ atau moderator) yang diperlukan untuk menyelenggarakan kegiatan sosialisasi dengan lancar.
3. Pelaksanaan
a. Penyampaian Materi Materi sosialisasi disampaikan secara sistematis dan interaktif, gunakan bahasa yang persuasif dan mudah dipahami, dan berikan contoh konkret untuk memperjelas konsep-konsep yang disampaikan.
b. Fasilitasi Diskusi Beri kesempatan kepada peserta untuk berdiskusi, bertanya, dan berbagi pengalaman terkait bencana, serta dorong partisipasi aktif dalam proses belajar.
c. Apabila pelaksanaan kegiatan sosialisasi dilakukan secara tidak langsung, maka perlu diperhatikan pula bentuk media yang digunakan (misalnya bila menggunakan video, perlu memperhatikan durasi penayangan, atau bila media yang dicetak, perlu diperhatikan kuantitas media yang perlu dicetak).
4. Pemantauan, Umpan Balik, dan Evaluasi
a. Pemantauan Pelaksanaan Pemantuan kegiatan sosialisasi dilaksanakan secara berkala, dengan mencatat perkembangan berdasarkan indikator capaian dan indikator proses yang telah disepakati, identifikasi kendala atau masalah yang mungkin muncul, serta didokumentasikan praktik baik dan pembelajaran yang muncul.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1603, 'c. Persiapan Sumber Daya Siapkan fasilitas, materi sosialisasi, media (cetak dan/ atau elektronik) dan tenaga pendukung (termasuk narasumber, fasilitator, dan/ atau moderator) yang diperlukan untuk menyelenggarakan kegiatan sosialisasi dengan lancar.
3. Pelaksanaan
