INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1629, 'pedoman-3-2024', 65, 'lain', 'BAB VI (lanjutan 8)', NULL, 33, '6. Pesan Kunci Angin Kencang 1) Tindakan untuk mencegah dampak angin kencang
a. Pangkas cabang pohon yang dekat dari rumah dan kabel listrik.
b. Pastikan ruangan dalam rumah yang dapat menjadi tempat berlindung.
c. Pastikan barang-barang di luar rumah yang tidak dapat terbang tertiup angin kencang.
d. Pastikan jendela dan atap bangunan terpasang dengan kokoh.
e. Kenali bahaya di sekitar yang mengancam, seperti puing-puing beterbangan yang dapat menyebabkan cedera.
f. Kenali dan pahami ancaman angin kencang dan bagaimana cara menyelamatkan diri.
g. Perhatikan tanda-tanda di sekitar akan terjadi angin kencang, misal udara terasa panas dan muncul awan gelap.
2) Tindakan saat terjadi angin kencang
a. Parkir kendaraan dan pindahkan barang di luar rumah ke tempat yang aman seperti basement gedung/dalam rumah.
b. Tutup jendela dan pintu, lalu kunci dan berlindung di dalam rumah hingga angin kencang berhenti.
c. Matikan aliran listrik dan peralatan elektronik.
d. Hati-hati potensi petir yang menyambar.
e. Jika diluar rumah, hindari bangunan yang tinggi, tiang listrik, pohon, papan reklame dan sebagainya yang berpotensi roboh saat terjadi angin kencang.
3) Tindakan sesudah terjadi angin kencang
a. Jangan mendekati kabel listrik yang mati
b. Laporkan apabila ada kabel listrik yang putus
c. Pantau berita lokal
d. Berhati-hati saat membersihkan puing
7. Pesan Kunci Kebakaran Hutan dan Lahan 1) Tindakan untuk mencegah dampak kebakaran hutan dan lahan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1629, '6. Pesan Kunci Angin Kencang 1) Tindakan untuk mencegah dampak angin kencang
a. Pangkas cabang pohon yang dekat dari rumah dan kabel listrik.
