INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1634, 'pedoman-3-2024', 70, 'lain', 'BAB VI (lanjutan 13)', NULL, 36, 'd. Praktikkan rotasi tanaman dengan lebih dari 2 jenis.
e. Mendaur ulang air bekas untuk toilet, peternakan dan pekarangan rumah.
f. Waspada gejala malnutrisi.
g. Gunakan alternatif sabut kelapa jika tidak ada sabun.
h. Gunakan masker untuk menghindar debu dan mencegah infeksi pernafasan.
i. Prioritaskan pemberian makanan pada anak-anak, ibu hamil dan menyusui.
j. Koordinasi dengan pihak terkait untuk memasok air ke lokasi yang mengalami kekeringan.
k. Cari bantuan pangan apabila mengalami gagal panen / krisis pangan.
l. Lakukan aksi adaptasi perubahan iklim.
m. Lakukan penyemaian hujan buatan di daerah tangkapan hujan.
3) Tindakan sesudah terjadi kekeringan
a. (sama dengan tindakan sebelum terjadi kekeringan).
10. Pesan Kunci untuk Penyakit Menular 1) Tindakan untuk mencegah dampak penyakit menular
a. Jaga kebersihan lingkungan.
b. Lindungi sumber air dari kontaminasi hewan dan air limbah.
c. Bersihkan toilet untuk menghindari penyakit.
d. Mewaspadai kemungkinan ancaman pandemi terjadi melalui udara, air, makanan dan cairan tubuh.
e. Jaga pola hidup bersih dan sehat serta kesehatan lingkungan.
f. Jaga kondisi kesehatan binatang peliharaan dan tidak berkeliaran.
g. Lakukan vaksinasi hewan yang rentan terkena penyakit menular.
h. Jaga kondisi kesehatan binatang peliharaan dan tidak berkeliaran.
i. Kenali jenis-jenis penyakit menular dan cara penularannya ke manusia.
2) Tindakan saat terjadi penyakit menular
a. Banyak konsumsi air mineral.');
