INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1635, 'pedoman-3-2024', 71, 'lain', 'BAB VI (lanjutan 14)', NULL, 37, 'b. Gunakan sumber air bersih dengan baik.
c. Selalu bersihkan tangan dan gunakan peralatan yang bersih.
d. Buang limbah rumah tangga, manusia dan hewan tanpa mengkontaminasi tanah dan air.
e. Jaga kebersihan rumah dan lingkungan sekitar.
f. Jaga kebersihan makanan.
g. Tempatkan toilet jauh dari sumber air dan jaga kebersihannya.
h. Hindari menyentuh mulut, mata dan hidung dengan tanganyang belum dicuci.
i. Batasi kontak fisik dengan orang lain dan hewan.
j. Gunakan alat pelindung sesuai anjuran (misal: masker, sarung tangan, dll).
k. Periksa selalu gejala yang menimpa diri sendiri.
l. Segera lapor ke puskeswan (bila sumber penularan akibat hewan)/puskesmas terdekat.
m. Segera melakukan pengobatan dan pastikan sembuh tuntas.
n. Ikuti arahan dari dokter atau tenaga kesehatan terkait.
3) Tindakan sesudah terjadi penyakit menular
a. Tetap jaga kebersihan diri.
b. Jaga imun dengan diet sehat dan olahraga.
c. Kurangi stres dan hindari merokok.
d. Lakukan pola hidup bersih dan sehat.
e. Edukasi masyarakat sekitar terkait kemungkinan penyakit menular.
j. Tetap gunakan masker saat beraktivitas di luar ruangan.');
