INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1636, 'pedoman-3-2024', 72, 'lain', 'BAB VII', NULL, 38, 'PEMANTAUAN, UMPAN BALIK, DAN EVALUASI Pemantauan, evaluasi, dan umpan balik merupakan salah satu komponen kunci dalam proses sosialisasi penanggulangan bencana.
Melalui pemantauan yang sistematis, informasi terkait pelaksanaan kegiatan dapat dikumpulkan dan masalah yang muncul dapat diidentifikasi secara cepat. Evaluasi kemudian dilakukan untuk menilai efektivitas, efisiensi, relevansi, dan dampak dari kegiatan sosialisasi tersebut, sehingga dapat diidentifikasi peluang perbaikan di masa mendatang. Sementara itu, umpan balik membantu dalam mendapatkan perspektif yang beragam dan akurat tentang kegiatan sosialisasi, yang dapat digunakan untuk meningkatkan pelaksanaan kegiatan di masa yang akan datang. Dengan memperhatikan ketiga elemen ini secara komprehensif, upaya sosialisasi penanggulangan bencana dapat berjalan efektif, efisien, sesuai dengan kebutuhan, serta berdampak positif bagi masyarakat yang dilayani.
Tim yang melakukan pemantauan, evaluasi, dan pengelolaan umpan balik sebaiknya adalah tim yang terpisah dan tidak terlibat dalam pelaksanaan sosialisasi penanggulangan bencana agar kajian dan penilaian yang dilakukan dapat bersifat objektif. Tim ini dapat melibatkan berbagai pihak dan berasal dari beragam institusi, termasuk mengikutsertakan kepakaran tertentu, misalnya ahli komunikasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1636, 'PEMANTAUAN, UMPAN BALIK, DAN EVALUASI Pemantauan, evaluasi, dan umpan balik merupakan salah satu komponen kunci dalam proses sosialisasi penanggulangan bencana.
Melalui pemantauan yang sistematis, informasi terkait pelaksanaan kegiatan dapat dikumpulkan dan masalah yang muncul dapat diidentifikasi secara cepat. Evaluasi kemudian dilakukan untuk menilai efektivitas, efisiensi, relevansi, dan dampak dari kegiatan sosialisasi tersebut, sehingga dapat diidentifikasi peluang perbaikan di masa mendatang. Sementara itu, umpan balik membantu dalam mendapatkan perspektif yang beragam dan akurat tentang kegiatan sosialisasi, yang dapat digunakan untuk meningkatkan pelaksanaan kegiatan di masa yang akan datang. Dengan memperhatikan ketiga elemen ini secara komprehensif, upaya sosialisasi penanggulangan bencana dapat berjalan efektif, efisien, sesuai dengan kebutuhan, serta berdampak positif bagi masyarakat yang dilayani.
Tim yang melakukan pemantauan, evaluasi, dan pengelolaan umpan balik sebaiknya adalah tim yang terpisah dan tidak terlibat dalam pelaksanaan sosialisasi penanggulangan bencana agar kajian dan penilaian yang dilakukan dapat bersifat objektif. Tim ini dapat melibatkan berbagai pihak dan berasal dari beragam institusi, termasuk mengikutsertakan kepakaran tertentu, misalnya ahli komunikasi.', 'BAB VII', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1637, 'pedoman-3-2024', 73, 'lain', 'BAB VII (lanjutan 1)', NULL, 38, 'Dengan melibatkan berbagai pihak dalam pelaksanaan sosialisasi penanggulangan bencana, diharapkan tim yang terbentuk dapat memiliki beragam perspektif dan kompetensi yang diperlukan untuk melakukan pemantauan, evaluasi, dan umpan balik yang komprehensif. Bagan terkait pemantauan, umpan balik dan evaluasi sebagai berikut:
Gambar 2. Bagan Pemantauan, Umpan Balik dan Evaluasi pelaksanaan sosialiasasi A. Pemantauan Pemantauan merupakan langkah penting dalam proses penyelenggaraan sosialisasi penanggulangan bencana yang bertujuan untuk memastikan bahwa kegiatan sosialisasi berjalan sesuai dengan rencana dan mencapai tujuan yang ditetapkan. Kegiatan pemantauan dapat dilakukan secara terencana dan berkelanjutan sepanjang proses sosialisasi. Beberapa hal yang perlu diperhatikan dalam kegiatan pemantauan meliputi:
1. Penetapan Tujuan Pemantauan Menetapkan tujuan pemantuan yang jelas dan spesifik, termasuk parameter-parameter yang akan dipantau seperti pengetahuan, sikap, dan perilaku masyarakat terkait penanggulangan bencana.
2. Pengembangan Indikator Pemantauan Mengidentifikasi indikator-indikator yang relevan dan dapat diukur untuk memantau capaian dan proses pelaksanaan sosialisasi penanggulangan bencana. Indikator-indikator perlu dirumuskan untuk menentukan parameter apa yang diukur saat pemantauan.
Berikut ini adalah beberapa indikator yang dapat digunakan sebagai acuan:
a. Indikator Capaian:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1637, 'Dengan melibatkan berbagai pihak dalam pelaksanaan sosialisasi penanggulangan bencana, diharapkan tim yang terbentuk dapat memiliki beragam perspektif dan kompetensi yang diperlukan untuk melakukan pemantauan, evaluasi, dan umpan balik yang komprehensif. Bagan terkait pemantauan, umpan balik dan evaluasi sebagai berikut:
Gambar 2. Bagan Pemantauan, Umpan Balik dan Evaluasi pelaksanaan sosialiasasi A. Pemantauan Pemantauan merupakan langkah penting dalam proses penyelenggaraan sosialisasi penanggulangan bencana yang bertujuan untuk memastikan bahwa kegiatan sosialisasi berjalan sesuai dengan rencana dan mencapai tujuan yang ditetapkan. Kegiatan pemantauan dapat dilakukan secara terencana dan berkelanjutan sepanjang proses sosialisasi. Beberapa hal yang perlu diperhatikan dalam kegiatan pemantauan meliputi:
1. Penetapan Tujuan Pemantauan Menetapkan tujuan pemantuan yang jelas dan spesifik, termasuk parameter-parameter yang akan dipantau seperti pengetahuan, sikap, dan perilaku masyarakat terkait penanggulangan bencana.
2. Pengembangan Indikator Pemantauan Mengidentifikasi indikator-indikator yang relevan dan dapat diukur untuk memantau capaian dan proses pelaksanaan sosialisasi penanggulangan bencana. Indikator-indikator perlu dirumuskan untuk menentukan parameter apa yang diukur saat pemantauan.
Berikut ini adalah beberapa indikator yang dapat digunakan sebagai acuan:
a. Indikator Capaian:', 'BAB VII (lanjutan 1)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1638, 'pedoman-3-2024', 74, 'lain', 'BAB VII (lanjutan 2)', NULL, 39, '• Jumlah peserta (dengan data terpilah berdasarkan jenis kelamin, umur, dan status disabilitas) yang mengikuti kegiatan sosialisasi penanggulangan bencana.
• Lokasi kegiatan sosialiasasi penanggulangan bencana
• Tingkat kesadaran masyarakat tentang risiko bencana dan kesiapsiagaan dalam menghadapi situasi darurat.
• Tingkat pengetahuan masyarakat tentang berbagai ancaman bencana disekitarnya dan langkah-langkah yang tepat di saat prabencana, saat darurat bencana, dan pascabencana.
• Tingkat kemampuan masyarakat dalam melakukan keterampilan praktis, misalnya melakukan evakuasi atau menyusun tas siaga
• Partisipasi aktif masyarakat dalam program kesiapsiagaan dan kegiatan mitigasi di tingkat individu dan komunitas.
• Tingkat perubahan perilaku masyarakat dalam mengimplementasikan tindakan pencegahan, mitigasi, dan kesiapsiagaan dalam kehidupan sehari-hari.
• Respons masyarakat terhadap informasi dan pesan sosialisasi yang disampaikan, termasuk tingkat kepercayaan dan kepuasan mereka terhadap materi yang disampaikan.
b. Indikator Proses:
• Ketersediaan dan keberhasilan implementasi rencana sosialisasi penanggulangan bencana.
• Tingkat partisipasi dan dukungan dari berbagai pihak terkait, termasuk pemerintah daerah, lembaga pemerintah terkait, LSM, dan komunitas lokal.
• Kelancaran dan efektivitas metode penyampaian pesan sosialisasi, termasuk keberhasilan dalam memilih media bantu yang sesuai dengan karakteristik masyarakat sasaran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1638, '• Jumlah peserta (dengan data terpilah berdasarkan jenis kelamin, umur, dan status disabilitas) yang mengikuti kegiatan sosialisasi penanggulangan bencana.
• Lokasi kegiatan sosialiasasi penanggulangan bencana
• Tingkat kesadaran masyarakat tentang risiko bencana dan kesiapsiagaan dalam menghadapi situasi darurat.
• Tingkat pengetahuan masyarakat tentang berbagai ancaman bencana disekitarnya dan langkah-langkah yang tepat di saat prabencana, saat darurat bencana, dan pascabencana.
• Tingkat kemampuan masyarakat dalam melakukan keterampilan praktis, misalnya melakukan evakuasi atau menyusun tas siaga
• Partisipasi aktif masyarakat dalam program kesiapsiagaan dan kegiatan mitigasi di tingkat individu dan komunitas.
• Tingkat perubahan perilaku masyarakat dalam mengimplementasikan tindakan pencegahan, mitigasi, dan kesiapsiagaan dalam kehidupan sehari-hari.
• Respons masyarakat terhadap informasi dan pesan sosialisasi yang disampaikan, termasuk tingkat kepercayaan dan kepuasan mereka terhadap materi yang disampaikan.
b. Indikator Proses:
• Ketersediaan dan keberhasilan implementasi rencana sosialisasi penanggulangan bencana.
• Tingkat partisipasi dan dukungan dari berbagai pihak terkait, termasuk pemerintah daerah, lembaga pemerintah terkait, LSM, dan komunitas lokal.
• Kelancaran dan efektivitas metode penyampaian pesan sosialisasi, termasuk keberhasilan dalam memilih media bantu yang sesuai dengan karakteristik masyarakat sasaran.', 'BAB VII (lanjutan 2)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1639, 'pedoman-3-2024', 75, 'lain', 'BAB VII (lanjutan 3)', NULL, 39, '• Ketersediaan dan kualitas materi sosialisasi, termasuk kejelasan, ketepatan, dan relevansi informasi yang disampaikan.
• Tingkat partisipasi dan keterlibatan masyarakat dalam proses pemantauan dan evaluasi sosialisasi penanggulangan bencana.
• Responsif terhadap umpan balik dan rekomendasi dari pemantauan dan evaluasi, termasuk kemampuan untuk melakukan perbaikan dan penyesuaian sesuai dengan hasil evaluasi yang diperoleh.
3. Pencatatan/ Pengumpulan Data Pemantauan dimulai dengan pencatatan data dan informasi terkait pelaksanaan kegiatan sosialisasi, termasuk jumlah peserta, materi yang disampaikan, dan respon peserta. Pencatatan secara berkala terhadap kegiatan sosialisasi akan digunakan untuk mengkaji apakah proses yang dilakukan sudah sesuai dengan yang direncanakan, merekam pihak-pihak yang terlibat dalam proses sosialisasi, serta menentukan langkah-langkah perbaikan atau penguatan. Data yang dicatat juga akan digunakan untuk proses evaluasi.
4. Analisis Analisis terhadap data pemantauan dilakukan untuk mengidentifikasi tren, pola, dan tantangan yang dihadapi dalam pelaksanaan sosialisasi, serta menyusun rekomendasi perbaikan untuk meningkatkan efektivitas kegiatan sosialisasi di masa mendatang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1639, '• Ketersediaan dan kualitas materi sosialisasi, termasuk kejelasan, ketepatan, dan relevansi informasi yang disampaikan.
• Tingkat partisipasi dan keterlibatan masyarakat dalam proses pemantauan dan evaluasi sosialisasi penanggulangan bencana.
• Responsif terhadap umpan balik dan rekomendasi dari pemantauan dan evaluasi, termasuk kemampuan untuk melakukan perbaikan dan penyesuaian sesuai dengan hasil evaluasi yang diperoleh.
3. Pencatatan/ Pengumpulan Data Pemantauan dimulai dengan pencatatan data dan informasi terkait pelaksanaan kegiatan sosialisasi, termasuk jumlah peserta, materi yang disampaikan, dan respon peserta. Pencatatan secara berkala terhadap kegiatan sosialisasi akan digunakan untuk mengkaji apakah proses yang dilakukan sudah sesuai dengan yang direncanakan, merekam pihak-pihak yang terlibat dalam proses sosialisasi, serta menentukan langkah-langkah perbaikan atau penguatan. Data yang dicatat juga akan digunakan untuk proses evaluasi.
4. Analisis Analisis terhadap data pemantauan dilakukan untuk mengidentifikasi tren, pola, dan tantangan yang dihadapi dalam pelaksanaan sosialisasi, serta menyusun rekomendasi perbaikan untuk meningkatkan efektivitas kegiatan sosialisasi di masa mendatang.', 'BAB VII (lanjutan 3)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1640, 'pedoman-3-2024', 76, 'lain', 'BAB VII (lanjutan 4)', NULL, 40, '5. Pelaporan Hasil pemantauan dicatat dan dilaporkan secara berkala kepada pihak terkait, termasuk manajemen penyelenggara sosialisasi dan stakeholder lainnya. Analisis terhadap data pemantauan dilakukan untuk mengidentifikasi tren, pola, dan tantangan yang dihadapi dalam pelaksanaan sosialisasi, serta menyusun rekomendasi perbaikan untuk meningkatkan efektivitas kegiatan sosialisasi di masa mendatang.
Pemantauan tidak hanya dilakukan selama pelaksanaan sosialisasi, tetapi juga perlu dilakukan secara berkelanjutan untuk memantau dampak jangka panjang dari kegiatan sosialisasi terhadap pengetahuan, sikap, dan perilaku masyarakat terkait penanggulangan bencana. Komitmen terhadap pemantauan berkelanjutan akan membantu penyelenggara sosialisasi dalam melakukan penyesuaian dan perbaikan berkelanjutan dalam strategi sosialisasi selanjutnya.
B. Umpan Balik Umpan balik merupakan sarana penyediaan informasi untuk memperoleh respon kelompok sasaran terhadap kegiatan sosialisasi yang sedang berlangsung. Umpan balik menceritakan tentang fasilitas dan/ atau media bantu yang digunakan, atau tentang perilaku dan sikap pihak penyelenggara atau pihak-pihak lainnya, atau narasi dan desain dalam sebuah konten media tidak langsung. Mekanisme umpan balik ini bertujuan agar proses sosialisasi dapat terselenggara lebih baik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1640, '5. Pelaporan Hasil pemantauan dicatat dan dilaporkan secara berkala kepada pihak terkait, termasuk manajemen penyelenggara sosialisasi dan stakeholder lainnya. Analisis terhadap data pemantauan dilakukan untuk mengidentifikasi tren, pola, dan tantangan yang dihadapi dalam pelaksanaan sosialisasi, serta menyusun rekomendasi perbaikan untuk meningkatkan efektivitas kegiatan sosialisasi di masa mendatang.
Pemantauan tidak hanya dilakukan selama pelaksanaan sosialisasi, tetapi juga perlu dilakukan secara berkelanjutan untuk memantau dampak jangka panjang dari kegiatan sosialisasi terhadap pengetahuan, sikap, dan perilaku masyarakat terkait penanggulangan bencana. Komitmen terhadap pemantauan berkelanjutan akan membantu penyelenggara sosialisasi dalam melakukan penyesuaian dan perbaikan berkelanjutan dalam strategi sosialisasi selanjutnya.
B. Umpan Balik Umpan balik merupakan sarana penyediaan informasi untuk memperoleh respon kelompok sasaran terhadap kegiatan sosialisasi yang sedang berlangsung. Umpan balik menceritakan tentang fasilitas dan/ atau media bantu yang digunakan, atau tentang perilaku dan sikap pihak penyelenggara atau pihak-pihak lainnya, atau narasi dan desain dalam sebuah konten media tidak langsung. Mekanisme umpan balik ini bertujuan agar proses sosialisasi dapat terselenggara lebih baik.', 'BAB VII (lanjutan 4)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1641, 'pedoman-3-2024', 77, 'lain', 'BAB VII (lanjutan 5)', NULL, 40, 'Umpan balik dapat diterima secara informal melalui percakapan antara kelompok sasaran dengan penyelenggara, maupun formal melalui saluran resmi seperti nomor hotline, meja pengaduan, kotak saran, atau melalui perwakilan masyarakat. Hal utama dari umpan balik adalah pentingnya untuk ditindaklanjuti dan ditanggapi.
Umpan balik yang sensitif dapat membahayakan individu yang menceritakan atau orang lain sehingga perlu ditangani dengan hati-hati.
Cerita sensitif dapat pula berkaitan dengan pelanggaran hukum dan dapat mempengaruhi keselamatan, martabat dan hak masyarakat, atau pelanggaran kode etik atau kebijakan terkait keamanan untuk pekerja, relawan, atau mitra. Umpan balik sensitif dapat membantu merespons kekhawatiran yang terjadi di tengah masyarakat akibat program.
1. Tujuan Mekanisme Umpan Balik Mekanisme umpan balik diperlukan untuk:
• Membantu meningkatkan kualitas proses sosialisasi dengan mengidentifikasi area untuk perbaikan, serta dapat menghemat dana dan sumber daya yang diperlukan dalam jangka panjang.
• Memungkinkan untuk memantau kinerja melalui sudut pandang masyarakat.
• Membangun kepercayaan di tengah masyarakat dengan mendengarkan dan menindaklanjuti umpan balik yang diterima.
• Mendorong pemberdayaan masyarakat dan membuat masyarakat lebih bersedia untuk terlibat dan memberikan masukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1641, 'Umpan balik dapat diterima secara informal melalui percakapan antara kelompok sasaran dengan penyelenggara, maupun formal melalui saluran resmi seperti nomor hotline, meja pengaduan, kotak saran, atau melalui perwakilan masyarakat. Hal utama dari umpan balik adalah pentingnya untuk ditindaklanjuti dan ditanggapi.
Umpan balik yang sensitif dapat membahayakan individu yang menceritakan atau orang lain sehingga perlu ditangani dengan hati-hati.
Cerita sensitif dapat pula berkaitan dengan pelanggaran hukum dan dapat mempengaruhi keselamatan, martabat dan hak masyarakat, atau pelanggaran kode etik atau kebijakan terkait keamanan untuk pekerja, relawan, atau mitra. Umpan balik sensitif dapat membantu merespons kekhawatiran yang terjadi di tengah masyarakat akibat program.
1. Tujuan Mekanisme Umpan Balik Mekanisme umpan balik diperlukan untuk:
• Membantu meningkatkan kualitas proses sosialisasi dengan mengidentifikasi area untuk perbaikan, serta dapat menghemat dana dan sumber daya yang diperlukan dalam jangka panjang.
• Memungkinkan untuk memantau kinerja melalui sudut pandang masyarakat.
• Membangun kepercayaan di tengah masyarakat dengan mendengarkan dan menindaklanjuti umpan balik yang diterima.
• Mendorong pemberdayaan masyarakat dan membuat masyarakat lebih bersedia untuk terlibat dan memberikan masukan.', 'BAB VII (lanjutan 5)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1642, 'pedoman-3-2024', 78, 'lain', 'BAB VII (lanjutan 6)', NULL, 41, '• Menyediakan peringatan dini dengan mendeteksi masalah sejak awal sebelum terjadi eskalasi dan mengancam implementasi atau keamanan dan akses baik untuk pihak penyelenggara atau pihak-pihak lainnya.
• Memudahkan masyarakat untuk melaporkan kasus-kasus sensitif secara aman.
• Menyediakan mekanisme bagi pihak penyelenggara atau pihak-pihak lainnya untuk menanggapi pertanyaan atau keluhan atau merujuk ke pihak lain bila sulit untuk ditanggapi dengan mudah.
• Mewujudkan hak warga terdampak untuk mengadu, dan lembaga memiliki tanggung jawab untuk mendengarkan dan menindaklanjuti.
2. Mekanisme dan Perangkat Umpan Balik yang Bisa Digunakan Ada dua cara untuk mengumpulkan umpan balik dari kelompok sasaran, yakni mekanisme proaktif dan reaktif. Mekanisme proaktif merupakan mekanisme di mana kelompok sasaran memberikan respon dengan menggunakan sarana umpan balik yang dimiliki oleh pihak penyelenggara. Sedangkan mekanisme reaktif merupakan mekanisme di mana pihak penyelenggara yang meminta umpan balik dari kelompok sasaran. Kedua cara ini penting dan mekanisme umpan balik terbaik menggunakan kombinasi metode proaktif dan reaktif dengan memperhatikan perbandingan mekanisme umpan balik yang proaktif dan reaktif (Tabel 1).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1642, '• Menyediakan peringatan dini dengan mendeteksi masalah sejak awal sebelum terjadi eskalasi dan mengancam implementasi atau keamanan dan akses baik untuk pihak penyelenggara atau pihak-pihak lainnya.
• Memudahkan masyarakat untuk melaporkan kasus-kasus sensitif secara aman.
• Menyediakan mekanisme bagi pihak penyelenggara atau pihak-pihak lainnya untuk menanggapi pertanyaan atau keluhan atau merujuk ke pihak lain bila sulit untuk ditanggapi dengan mudah.
• Mewujudkan hak warga terdampak untuk mengadu, dan lembaga memiliki tanggung jawab untuk mendengarkan dan menindaklanjuti.
2. Mekanisme dan Perangkat Umpan Balik yang Bisa Digunakan Ada dua cara untuk mengumpulkan umpan balik dari kelompok sasaran, yakni mekanisme proaktif dan reaktif. Mekanisme proaktif merupakan mekanisme di mana kelompok sasaran memberikan respon dengan menggunakan sarana umpan balik yang dimiliki oleh pihak penyelenggara. Sedangkan mekanisme reaktif merupakan mekanisme di mana pihak penyelenggara yang meminta umpan balik dari kelompok sasaran. Kedua cara ini penting dan mekanisme umpan balik terbaik menggunakan kombinasi metode proaktif dan reaktif dengan memperhatikan perbandingan mekanisme umpan balik yang proaktif dan reaktif (Tabel 1).', 'BAB VII (lanjutan 6)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1643, 'pedoman-3-2024', 79, 'lain', 'BAB VII (lanjutan 7)', NULL, 41, 'Tabel 1. Perbandingan mekanisme umpan balik yang proaktif dan reaktif Proaktif Reaktif Kelompok sasaran Penjelasan Pihak penyelenggara menghubungi pihak meminta umpan balik penyelenggara ketika kepada kelompok sasaran mereka memiliki umpan dengan mengajukan balik untuk dibagikan pertanyaan
• Telepon hotline Contoh • Diskusi kelompok
• Meja bantuan mekanisme terfokus komunitas • Kunjungan rumah ke
• Melalui saluran radio rumah atau jaringan radio • Survei persepsi atau amatir, seperti kepuasan ORARI, RAPI, dan • Wawancara informan Kopdar Kamtibmas kunci
• Mengirimkan SMS • Pertemuan Komite atau pesan singkat
• Melalui kotak saran
• Mengirimkan umpan balik secara online melalui website
• Menggunakan aplikasi berbasis online/chatbot
• Menggunakan media sosial
• Tersedia kapanpun Kelebihan • Beberapa ketika orang perlu orang/budaya mungkin menggunakannya merasa tidak nyaman
• Dapat menangkap atau tidak biasa umpan balik tentang menyampaikan umpan apa pun balik tanpa diminta
• Memiliki jangkauan • Mendukung interaksi wilayah yang lebih tatap muka dengan luas dan mencakup masyarakat kelompok manapun, • Dapat mengumpulkan termasuk kaum umpan balik tentang muda topik tertentu
• Memungkinkan • Lebih mudah bagi umpan balik secara lembaga untuk anonim memberikan tanggapan');
