INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1657, 'pedoman-3-2024', 93, 'lampiran', 'LAMPIRAN (lanjutan 5)', NULL, 52, '• Persentase peserta yang terlibat dalam diskusi dan kontribusi dalam menyusun rencana aksi
• Kualitas rencana aksi yang disusun oleh peserta dan adanya kontribusi sumber daya dan anggaran
• Jumlah umpan balik yang diterima mengenai penyelenggaraan sosialisasi dan materi yang disampaikan.
Waktu dan Tempat Kegiatan Kegiatan sosialisasi ini akan dilakukan di ruang pertemuan BPBD Provinsi NTT dan dilaksanakan pada hari Kamis, 18 Juli 2024 dari jam 08.30 – 15.30 WITA Peserta Peserta atau kelompok sasaran dalam kegiatan sosialisasi penanggulangan bencana ini adalah seluruh dinas Provinsi, Kabupaten, Kota yang diidentifikasi memiliki tugas pokok dan fungsi terkait penanggilangan bencana. Daftar rinci peserta terdapat di lampiran.
