INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1658, 'pedoman-3-2024', 94, 'lampiran', 'LAMPIRAN (lanjutan 6)', NULL, 53, '11:45 Antisipatif BPBD NTT 11:45 - Istirahat dan Makan Siang 12:45 12:45 - Sesi 3: Koordinasi dan Kolaborasi Antar Perwakilan 13:45 Instansi dalam Penanggulangan Bencana Pemerintah Daerah dan Lembaga Terkait 13:45 - Sesi 4: Penyusunan Rencana Aksi dan Diskusi 14:15 Strategi Penanggulangan Bencana Kelompok 14:15 - Rehat Kopi 14:30 14:30 - Sesi 5: Presentasi Hasil Diskusi (Setiap Diskusi Pleno 15:00 Kelompok Menyampaikan Rencana Aksi) 15.00 – Penutupan dan Evaluasi Singkat 15.30 Pembiayaan Kegiatan ini menggunakan anggaran BPBD Provinsi NTT.
C. Contoh Kerangka Acuan Kerja untuk Kegiatan Sosialisasi (Informal) Edukasi Siap Siaga Bencana Saat Masa Pengenalan Lingkungan Sekolah (MPLS) Kerangka Acuan Kerja Pendahuluan Yogyakarta sebagai salah satu kota yang dikenal dengan beragam kekayaan budaya dan situs-situs bersejarah, merupakan salah satu wilayah yang rentan terhadap berbagai jenis bencana. Salah satu risiko utama adalah letusan gunung merapi, yang merupakan salah satu gunung berapi paling aktif di dunia. Selain itu, Yogyakarta juga terletak di zona rawan gempa bumi karena berada di pertemuan lempeng tektonik Indo-Australia dan Eurasia.
Yogyakarta telah mengalami beberapa bencana alam besar dalam sejarahnya yang berdampak signifikan pada kehidupan masyarakatnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1658, '11:45 Antisipatif BPBD NTT 11:45 - Istirahat dan Makan Siang 12:45 12:45 - Sesi 3: Koordinasi dan Kolaborasi Antar Perwakilan 13:45 Instansi dalam Penanggulangan Bencana Pemerintah Daerah dan Lembaga Terkait 13:45 - Sesi 4: Penyusunan Rencana Aksi dan Diskusi 14:15 Strategi Penanggulangan Bencana Kelompok 14:15 - Rehat Kopi 14:30 14:30 - Sesi 5: Presentasi Hasil Diskusi (Setiap Diskusi Pleno 15:00 Kelompok Menyampaikan Rencana Aksi) 15.00 – Penutupan dan Evaluasi Singkat 15.30 Pembiayaan Kegiatan ini menggunakan anggaran BPBD Provinsi NTT.
C. Contoh Kerangka Acuan Kerja untuk Kegiatan Sosialisasi (Informal) Edukasi Siap Siaga Bencana Saat Masa Pengenalan Lingkungan Sekolah (MPLS) Kerangka Acuan Kerja Pendahuluan Yogyakarta sebagai salah satu kota yang dikenal dengan beragam kekayaan budaya dan situs-situs bersejarah, merupakan salah satu wilayah yang rentan terhadap berbagai jenis bencana. Salah satu risiko utama adalah letusan gunung merapi, yang merupakan salah satu gunung berapi paling aktif di dunia. Selain itu, Yogyakarta juga terletak di zona rawan gempa bumi karena berada di pertemuan lempeng tektonik Indo-Australia dan Eurasia.
Yogyakarta telah mengalami beberapa bencana alam besar dalam sejarahnya yang berdampak signifikan pada kehidupan masyarakatnya.', 'LAMPIRAN (lanjutan 6)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1659, 'pedoman-3-2024', 95, 'lampiran', 'LAMPIRAN (lanjutan 7)', NULL, 54, 'Beberapa kejadian bencana yang pernah terjadi di Yogyakarta yaitu letusan Gunung Merapi pada tahun 2010, yang menyebabkan ratusan kematian dan ribuan orang harus mengungsi. Letusan ini juga mengakibatkan kerusakan pada infrastruktur dan lahan pertanian di sekitar gunung. Selain itu, gempa bumi berkekuatan 6,3 skala Richter mengguncang Yogyakarta pada tanggal 27 Mei 2006, yang menyebabkan lebih dari 5.700 orang tewas, puluhan ribu luka-luka, dan ratusan ribu rumah hancur atau rusak berat. Sekolah menjadi salah satu lokasi yang terdampak secara signifikan dari kejadian-kejadian bencana. Siswa, guru dan staf sekolah yang saat kejadian bencana sedang menjalankan proses belajar mengajar, tidak sedikit yang terdampak secara fisik dan psikis dari kejadian bencana yang terjadi. Dampak lain dari kejadian bencana di lingkungan sekolah yakni adanya kerusakan infrastruktur dan aktivitas belajar mengajar yang terpaksa dihentikan hingga waktu yang tidak dapat ditentukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1659, 'Beberapa kejadian bencana yang pernah terjadi di Yogyakarta yaitu letusan Gunung Merapi pada tahun 2010, yang menyebabkan ratusan kematian dan ribuan orang harus mengungsi. Letusan ini juga mengakibatkan kerusakan pada infrastruktur dan lahan pertanian di sekitar gunung. Selain itu, gempa bumi berkekuatan 6,3 skala Richter mengguncang Yogyakarta pada tanggal 27 Mei 2006, yang menyebabkan lebih dari 5.700 orang tewas, puluhan ribu luka-luka, dan ratusan ribu rumah hancur atau rusak berat. Sekolah menjadi salah satu lokasi yang terdampak secara signifikan dari kejadian-kejadian bencana. Siswa, guru dan staf sekolah yang saat kejadian bencana sedang menjalankan proses belajar mengajar, tidak sedikit yang terdampak secara fisik dan psikis dari kejadian bencana yang terjadi. Dampak lain dari kejadian bencana di lingkungan sekolah yakni adanya kerusakan infrastruktur dan aktivitas belajar mengajar yang terpaksa dihentikan hingga waktu yang tidak dapat ditentukan.', 'LAMPIRAN (lanjutan 7)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1660, 'pedoman-3-2024', 96, 'lampiran', 'LAMPIRAN (lanjutan 8)', NULL, 54, 'Dalam menghadapi ancaman bencana yang dapat terjadi di lingkungan sekolah, diperlukan adanya upaya antisipasi melalui kegiatan sosialisasi kesiapsiagaan bencana yang diberikan untuk guru, murid dan warga sekolah lainnya. Sosialisasi ini mengenalkan ancaman dan bencana yang dapat terjadi di sekitar sekolah, serta praktik kesiapsiagaan bencana. Melalui kegiatan sosialisasi ini, diharapkan terbangunnya pemahaman yang lebih mendalam mengenai pentingnya kesiapsiagaan dan tindakan antisipatif menghadapi bencana di sekitar sekolah yang dapat terjadi.
Metodologi Pelaksanaan kegiatan sosialisasi penanggulangan bencana menggunakan metodologi sebagai berikut:
1. Persiapan dan Perencanaan:
• Identifikasi Kebutuhan: Menentukan pemateri, waktu pelaksanaan dan alat-alat pendukung dalam pemberian materi.
• Penyusunan Materi: Materi berisi pengenalan ancaman, kesiapsiagaan bencana dan praktiknya di lingkungan sekolah.
• Koordinasi dengan sekolah sasaran: Koordinasi mengenai waktu pelaksanaan MPLS, tempat dan peserta.
2. Pelaksanaan Sosialisasi:
• Pembukaan dan pengenalan dari panitia MPLS dan pemateri mengenai sosialisasi yang akan dilakukan.
• Ice breaking: Sesi ini dapat diisi oleh games atau kegiatan hiburan lainnya untuk memicu keingintahuan peserta mengenai kesiapsiagaan bencana, serta mengukur pengetahuan peserta mengenai ancaman di sekitar sekolah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1660, 'Dalam menghadapi ancaman bencana yang dapat terjadi di lingkungan sekolah, diperlukan adanya upaya antisipasi melalui kegiatan sosialisasi kesiapsiagaan bencana yang diberikan untuk guru, murid dan warga sekolah lainnya. Sosialisasi ini mengenalkan ancaman dan bencana yang dapat terjadi di sekitar sekolah, serta praktik kesiapsiagaan bencana. Melalui kegiatan sosialisasi ini, diharapkan terbangunnya pemahaman yang lebih mendalam mengenai pentingnya kesiapsiagaan dan tindakan antisipatif menghadapi bencana di sekitar sekolah yang dapat terjadi.
Metodologi Pelaksanaan kegiatan sosialisasi penanggulangan bencana menggunakan metodologi sebagai berikut:
1. Persiapan dan Perencanaan:
• Identifikasi Kebutuhan: Menentukan pemateri, waktu pelaksanaan dan alat-alat pendukung dalam pemberian materi.
• Penyusunan Materi: Materi berisi pengenalan ancaman, kesiapsiagaan bencana dan praktiknya di lingkungan sekolah.
• Koordinasi dengan sekolah sasaran: Koordinasi mengenai waktu pelaksanaan MPLS, tempat dan peserta.
2. Pelaksanaan Sosialisasi:
• Pembukaan dan pengenalan dari panitia MPLS dan pemateri mengenai sosialisasi yang akan dilakukan.
• Ice breaking: Sesi ini dapat diisi oleh games atau kegiatan hiburan lainnya untuk memicu keingintahuan peserta mengenai kesiapsiagaan bencana, serta mengukur pengetahuan peserta mengenai ancaman di sekitar sekolah.', 'LAMPIRAN (lanjutan 8)', 'Pedoman Sosialisasi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1661, 'pedoman-3-2024', 97, 'lampiran', 'LAMPIRAN (lanjutan 9)', NULL, 55, '• Sesi informasi: Sesi yang diisi oleh narasumber dari BPBD/lembaga kemanusiaan yang memiliki pemahaman dan pengalaman dalam materi kesiapsiagaan bencana khususnya di lingkungan sekolah.
• Sesi tanya jawab: Sesi ini sebagai ruang diskusi antara peserta dan pemateri mengenai praktik kesiapsiagaan bencana.
• Sesi praktik kesiapsiagaan bencana: Peserta mempraktikkan materi yang sudah diberikan (merunduk, berlindung & bertahan).
• Penutupan: Penyelenggara menutup acara dengan ringkasan kegiatan dan ajakan untuk memberikan umpan balik dari kegiatan yang sudah dilakukan.
3. Metode Evaluasi:
• Kuesioner Pra dan Pasca-Sosialisasi: Menyebarkan kuesioner kepada peserta sebelum dan sesudah sosialisasi untuk mengukur perubahan pengetahuan dan pemahaman.
• Observasi Langsung: Melakukan observasi selama acara berlangsung untuk menilai partisipasi dan interaksi peserta.
4. Indikator Keberhasilan:
• Jumlah peserta yang mengalami peningkatan skor pengetahuan peserta mengenai tindakan-tindakan yang bisa dilakukan untuk mengantisipasi bencana.
• Persentase peserta yang terlibat dalam diskusi dan praktik kesiapsiagaan bencana.
• Jumlah umpan balik yang diterima mengenai penyelenggaraan sosialisasi dan materi yang disampaikan.
Waktu dan Tempat Kegiatan Kegiatan sosialisasi ini akan dilakukan di 20 sekolah di Kota Yogyakarta bersamaan dengan Masa Pengenalan Lingkungan Sekolah (MPLS).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1661, '• Sesi informasi: Sesi yang diisi oleh narasumber dari BPBD/lembaga kemanusiaan yang memiliki pemahaman dan pengalaman dalam materi kesiapsiagaan bencana khususnya di lingkungan sekolah.
