INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1662, 'pedoman-3-2024', 98, 'lampiran', 'LAMPIRAN (lanjutan 10)', NULL, 55, 'Peserta Peserta atau kelompok sasaran dalam kegiatan sosialisasi kesiapsiagaan bencana ini adalah siswa/i, guru, staf sekolah, dan warga sekolah lainnya di 20 lokasi sekolah sasaran.
