INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1664, 'perban-1-2018', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk memberikan perlindungan kehidupan dan penghidupan masyarakat terdampak akibat bencana, diperlukan sumber daya manusia yang memiliki kompetensi, penjaminan mutu dan berdaya saing di bidang penanggulangan bencana;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana dalam implementasinya belum sepenuhnya dapat menampung perkembangan kebutuhan organisasi;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 2018, No.223 -2- tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana;');
