INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1667, 'perban-1-2018', 4, 'pasal', 'Pasal I', NULL, 3, 'Beberapa ketentuan dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 599) diubah sehingga berbunyi sebagai berikut:
1. Ketentuan Pasal 9 diubah sehingga berbunyi sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1667, 'Beberapa ketentuan dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 599) diubah sehingga berbunyi sebagai berikut:
1. Ketentuan Pasal 9 diubah sehingga berbunyi sebagai berikut:', 'Pasal I', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2018 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1668, 'perban-1-2018', 5, 'pasal', 'Pasal 9', NULL, 3, '(1) Lembaga Sertifikasi Profesi Penanggulangan Bencana terdiri atas:
a. penasehat;
b. dewan pengarah; dan
c. pelaksana.
(2) Dewan pengarah sebagaimana dimaksud pada ayat
(1) huruf b terdiri atas:
a. ketua; dan
b. anggota.
(3) Pelaksana sebagaimana dimaksud pada ayat (1) huruf c terdiri atas:
a. ketua;
b. wakil ketua;
c. sekretaris; dan
d. bidang.
(4) Bidang sebagaimana dimaksud pada ayat (3) huruf d terdiri atas:
a. bidang sertifikasi;
b. bidang manajemen mutu; dan
c. bidang kerja sama antar lembaga.
(5) Sekretaris sebagaimana dimaksud pada ayat (3) huruf c membawahi:
a. bagian perencanaan, informasi dan dokumentasi; dan
b. bagian administrasi dan keuangan.
2018, No.223 -4-
(6) Bidang sertifikasi sebagaimana dimaksud pada ayat
(4) huruf a dibantu oleh:
a. asisten bidang uji kompetensi;
b. asisten bidang pengembangan asesor dan tempat uji kompetensi; dan
c. asisten bidang standardisasi dan akreditasi.
(7) Bidang manajemen mutu sebagaimana dimaksud pada ayat (4) huruf b dibantu oleh:
a. asisten bidang pengendalian mutu; dan
b. asisten bidang pengembangan sistem manajemen.
(8) Bidang kerja sama antar lembaga sebagaimana dimaksud pada ayat (4) huruf c dibantu oleh:
a. asisten bidang kerja sama dalam negeri; dan
b. asisten bidang kerja sama luar negeri.
(9) Bagian dipimpin oleh kepala bagian.
(10) Bidang dipimpin oleh kepala bidang.
2. Diantara Pasal 9 dan Pasal 10 disisipkan 1 (satu) pasal baru, yakni Pasal 9A sehingga berbunyi sebagai berikut:');
