INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1669, 'perban-1-2018', 6, 'pasal', 'Pasal 9A', NULL, 4, '(1) Penasehat sebagaimana dimaksud dalam Pasal 9 ayat (1) huruf a mempunyai tugas memberikan pendapat, pandangan, dan saran kepada dewan pengarah dan pelaksana untuk menentukan arah kebijakan sesuai dengan kebutuhan masyarakat.
(2) Penasehat paling banyak berjumlah 3 (tiga) orang.
3. Ketentuan Pasal 10 diubah sehingga berbunyi sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1669, '(1) Penasehat sebagaimana dimaksud dalam Pasal 9 ayat (1) huruf a mempunyai tugas memberikan pendapat, pandangan, dan saran kepada dewan pengarah dan pelaksana untuk menentukan arah kebijakan sesuai dengan kebutuhan masyarakat.
(2) Penasehat paling banyak berjumlah 3 (tiga) orang.
3. Ketentuan Pasal 10 diubah sehingga berbunyi sebagai berikut:', 'Pasal 9A', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2018 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1670, 'perban-1-2018', 7, 'pasal', 'Pasal 10', NULL, 4, '(1) Dewan pengarah menetapkan kebijakan lembaga meliputi:
a. visi, misi dan tujuan LSP PB;
2018, No.223
b. rencana strategis, program kerja dan anggaran belanja; dan
c. membina komunikasi dengan pemangku kepentingan.
(2) Ketua dewan pengarah LSP PB yaitu kepala BNPB.
(3) Ketua dewan pengarah sebagaimana dimaksud pada ayat (2) merangkap sebagai anggota dewan pengarah.
(4) Ketua dewan pengarah mempunyai tugas:
a. menetapkan arah kebijakan LSP PB sesuai dengan kebutuhan masyarakat; dan
b. mengangkat dan memberhentikan penasehat, anggota dewan pengarah, dan pelaksana.
(5) Anggota dewan pengarah berjumlah 5 (lima) orang yang mewakili pemerintah, masyarakat dan lembaga usaha.
4. Ketentuan Pasal 11 diubah sehingga berbunyi sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1670, '(1) Dewan pengarah menetapkan kebijakan lembaga meliputi:
a. visi, misi dan tujuan LSP PB;
2018, No.223
b. rencana strategis, program kerja dan anggaran belanja; dan
c. membina komunikasi dengan pemangku kepentingan.
(2) Ketua dewan pengarah LSP PB yaitu kepala BNPB.
(3) Ketua dewan pengarah sebagaimana dimaksud pada ayat (2) merangkap sebagai anggota dewan pengarah.
(4) Ketua dewan pengarah mempunyai tugas:
a. menetapkan arah kebijakan LSP PB sesuai dengan kebutuhan masyarakat; dan
b. mengangkat dan memberhentikan penasehat, anggota dewan pengarah, dan pelaksana.
(5) Anggota dewan pengarah berjumlah 5 (lima) orang yang mewakili pemerintah, masyarakat dan lembaga usaha.
4. Ketentuan Pasal 11 diubah sehingga berbunyi sebagai berikut:', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2018 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1671, 'perban-1-2018', 8, 'pasal', 'Pasal 11', NULL, 5, '(1) Pelaksana sebagaimana dimaksud dalam Pasal 9 ayat (1) huruf c yaitu personil yang mempunyai sertifikat kompetensi.
(2) Pelaksana berada di bawah dan bertanggung jawab kepada dewan pengarah.
(3) Pelaksana mempunyai tugas:
a. melaksanakan kebijakan LSP PB;
b. melaksanakan anggaran dasar dan anggaran rumah tangga;
c. menyiapkan rencana program dan anggaran;
d. melaksanakan program kerja LSP PB;
e. mempertanggungjawabkan penggunaan anggaran;
f. merekomendasikan kepada Komite SKKNI PB mengenai pengembangan dan kaji ulang SKKNI PB;
2018, No.223 -6-
g. melakukan monitoring dan evaluasi; dan
h. menyampaikan laporan kepada dewan pengarah tentang hasil pelaksanaan tugas LSP PB.
(4) Ketua sebagaimana dimaksud dalam Pasal 9 ayat
(3) huruf a mempunyai tugas:
a. memimpin LSP PB dalam menjalankan fungsi, tugas, dan wewenang LSP PB;
b. mempertanggungjawabkan keuangan yang bersumber dari Anggaran Pendapatan dan Belanja Negara dan sumber lain yang sah dan tidak mengikat;
c. membentuk komite skema sertifikasi, manajemen representatif, dan komite teknis secara ad-hoc;
d. membentuk tim kajian;
e. mengusulkan pengangkatan dan pemberhentian tenaga ahli; dan
f. dapat mendelegasikan sebagian kewenangannya kepada anggota pelaksana dalam melaksanakan tugasnya, termasuk ke lembaga peradilan dan hukum.
(5) Komite skema sertifikasi, manajemen representatif, dan komite teknis sebagaimana dimaksud pada ayat
(4) huruf c berada di bawah dan bertanggung jawab kepada ketua.
(6) Wakil ketua mempunyai tugas membantu ketua dalam menjalankan fungsi, tugas, dan wewenang LSP PB.
5. Diantara Pasal 11 dan Pasal 12 disisipkan 3 (tiga) pasal, yaitu Pasal 11A, Pasal 11B dan Pasal 11C, sehingga Pasal 11A, Pasal 11B, dan Pasal 11C berbunyi sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1671, '(1) Pelaksana sebagaimana dimaksud dalam Pasal 9 ayat (1) huruf c yaitu personil yang mempunyai sertifikat kompetensi.
