INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1673, 'perban-1-2018', 10, 'pasal', 'Pasal 11B', NULL, 10, '(1) Tugas sekretaris sebagaimana dimaksud dalam Pasal 9 ayat (3) huruf c memfasilitasi unit kerja di lingkungan LSP PB untuk terselenggaranya program sertifikasi profesi meliputi perencanaan, informasi dan dokumentasi, administrasi dan keuangan.
(2) Tugas bagian sebagaimana dimaksud dalam Pasal 9 ayat (5) huruf a yaitu:
a. mengusulkan rancangan rencana strategis;
b. merencanakan program kerja/kegiatan berdasarkan usulan unit kerja di lingkungan LSP PB;
c. merencanakan penggunaan teknologi informasi dan komunikasi untuk mendukung program 2018, No.223 sertifikasi;
d. memelihara informasi sertifikasi kompetensi; dan
e. pengelolaan dokumentasi.
(3) Tugas bagian sebagaimana dimaksud dalam Pasal 9 ayat (5) huruf b yaitu:
a. melaksanakan tugas ketatausahaan, urusan personil, kerumahtanggaan, dan perlengkapan;
b. melaksanakan koordinasi dengan satuan kerja yang mewadahi anggaran LSP-PB;
c. mengusulkan rencana program dan anggaran;
d. membantu pelaksanakan penggunaan/ pengeluaran dan penerimaan anggaran;
e. membantu pelaksanakan pembukuan keuangan; dan
f. menyiapkan laporan pelaksanaan kegiatan dan anggaran LSP PB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1673, '(1) Tugas sekretaris sebagaimana dimaksud dalam Pasal 9 ayat (3) huruf c memfasilitasi unit kerja di lingkungan LSP PB untuk terselenggaranya program sertifikasi profesi meliputi perencanaan, informasi dan dokumentasi, administrasi dan keuangan.
(2) Tugas bagian sebagaimana dimaksud dalam Pasal 9 ayat (5) huruf a yaitu:
a. mengusulkan rancangan rencana strategis;
b. merencanakan program kerja/kegiatan berdasarkan usulan unit kerja di lingkungan LSP PB;
c. merencanakan penggunaan teknologi informasi dan komunikasi untuk mendukung program 2018, No.223 sertifikasi;
d. memelihara informasi sertifikasi kompetensi; dan
e. pengelolaan dokumentasi.
(3) Tugas bagian sebagaimana dimaksud dalam Pasal 9 ayat (5) huruf b yaitu:
a. melaksanakan tugas ketatausahaan, urusan personil, kerumahtanggaan, dan perlengkapan;
b. melaksanakan koordinasi dengan satuan kerja yang mewadahi anggaran LSP-PB;
c. mengusulkan rencana program dan anggaran;
d. membantu pelaksanakan penggunaan/ pengeluaran dan penerimaan anggaran;
e. membantu pelaksanakan pembukuan keuangan; dan
f. menyiapkan laporan pelaksanaan kegiatan dan anggaran LSP PB.', 'Pasal 11B', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2018 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1674, 'perban-1-2018', 11, 'pasal', 'Pasal 11C', NULL, 11, 'Tugas komite skema sertifikasi, manajemen representatif, dan komite teknis sebagaimana dimaksud dalam Pasal 11 ayat (4) huruf c adalah:
a. komite skema sertifikasi:
1. mengkaji SKKNI PB untuk digunakan dalam penyusunan kompetensi tertentu di bidang penanggulangan bencana;
2. merumuskan nama jabatan atau okupasi dan mengkomunikasikan dengan pihak ahli dalam profesi;
3. merumuskan skema sertifikasi yang berisi unit kompetensi yang harus dimiliki; dan
4. mengusulkan perbaikan, penambahan dan pengembangan skema sertifikasi ke BNSP untuk mendapat persetujuan.
b. manajemen representatif:
1. memastikan semua prosedur LSP PB dijalankan dengan baik;
2018, No.223 -12-
2. mengembangkan sistem manajemen LSP PB;
3. memberikan laporan dan masukan terhadap pelaksanaan manajemen LSP PB;
4. melakukan koordinasi dengan kepala bidang manajemen mutu dalam pelaksanaan internal audit; dan
5. berfungsi sebagai penghubung antara LSP PB dengan BNSP.
c. komite teknis:
1. melakukan pengecekan kelengkapan dokumen uji kompetensi;
2. memberikan rekomendasi berdasarkan hasil pengecekan kelengkapan dokumen uji kompetensi seorang asesi kompeten atau belum kompeten;
3. melaksanakan sidang pleno komite teknis yang dihadiri oleh salah satu asesor/lead asesor; dan
4. membuat catatan hasil pemantauan/evaluasi kepada asesor dalam melakukan uji kompetensi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1674, 'Tugas komite skema sertifikasi, manajemen representatif, dan komite teknis sebagaimana dimaksud dalam Pasal 11 ayat (4) huruf c adalah:
a. komite skema sertifikasi:
1. mengkaji SKKNI PB untuk digunakan dalam penyusunan kompetensi tertentu di bidang penanggulangan bencana;
2. merumuskan nama jabatan atau okupasi dan mengkomunikasikan dengan pihak ahli dalam profesi;
3. merumuskan skema sertifikasi yang berisi unit kompetensi yang harus dimiliki; dan
4. mengusulkan perbaikan, penambahan dan pengembangan skema sertifikasi ke BNSP untuk mendapat persetujuan.
b. manajemen representatif:
1. memastikan semua prosedur LSP PB dijalankan dengan baik;
2018, No.223 -12-
2. mengembangkan sistem manajemen LSP PB;
3. memberikan laporan dan masukan terhadap pelaksanaan manajemen LSP PB;
4. melakukan koordinasi dengan kepala bidang manajemen mutu dalam pelaksanaan internal audit; dan
5. berfungsi sebagai penghubung antara LSP PB dengan BNSP.
c. komite teknis:
1. melakukan pengecekan kelengkapan dokumen uji kompetensi;
2. memberikan rekomendasi berdasarkan hasil pengecekan kelengkapan dokumen uji kompetensi seorang asesi kompeten atau belum kompeten;
3. melaksanakan sidang pleno komite teknis yang dihadiri oleh salah satu asesor/lead asesor; dan
4. membuat catatan hasil pemantauan/evaluasi kepada asesor dalam melakukan uji kompetensi.', 'Pasal 11C', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2018 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1675, 'perban-1-2018', 12, 'pasal', 'Pasal II', NULL, 12, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
2018, No.223 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indoneisa.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1675, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
2018, No.223 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indoneisa.', 'Pasal II', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2018 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1676, 'perban-1-2018', 13, 'lain', 'Penutup', NULL, 13, 'Ditetapkan di Jakarta pada tanggal 05 Februari 2018 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd WILLEM RAMPANGILE Diundangkan di Jakarta pada tanggal 6 Februari 2018 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd WIDODO EKATJAHJANA 2018, No.223 -14-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1676, 'Ditetapkan di Jakarta pada tanggal 05 Februari 2018 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd WILLEM RAMPANGILE Diundangkan di Jakarta pada tanggal 6 Februari 2018 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd WIDODO EKATJAHJANA 2018, No.223 -14-', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2018 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1677, 'perban-1-2018', 14, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA NOMOR 01 TAHUN 2018 TENTANG PERUBAHAN ATAS PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 7 TAHUN 2014 TENTANG LEMBAGA SERTIFIKASI PROFESI PENANGGULANGAN BENCANA STRUKTUR ORGANISASI LEMBAGA SERTIFIKASI PROFESI PENANGGULANGAN BENCANA KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA ttd WILLEM RAMPANGILEI');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1677, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA NOMOR 01 TAHUN 2018 TENTANG PERUBAHAN ATAS PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 7 TAHUN 2014 TENTANG LEMBAGA SERTIFIKASI PROFESI PENANGGULANGAN BENCANA STRUKTUR ORGANISASI LEMBAGA SERTIFIKASI PROFESI PENANGGULANGAN BENCANA KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA ttd WILLEM RAMPANGILEI', 'Lampiran hal. 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2018 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1678, 'perban-1-2019', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2019 tentang Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1678, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2019 tentang Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2019 tentang Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1679, 'perban-1-2019', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk membangun kapasitas sumberdaya manusia yang kompeten dan profesional di bidang penanggulangan bencana, perlu pemberlakuan standar kompetensi kerja dalam bidang penanggulangan bencana melalui penyelenggaraan pendidikan dan pelatihan teknis;
b. bahwa berdasarkan Keputusan Menteri Ketenagakerjaan Nomor 60 Tahun 2018, telah ditetapkan Standar Kompetensi Kerja Nasional Indonesia Kategori Administrasi Golongan Pokok Administrasi Pemerintahan dan Pertahanan dan Jaminan Sosial Wajib Bidang Penanggulangan Bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1679, 'a. bahwa untuk membangun kapasitas sumberdaya manusia yang kompeten dan profesional di bidang penanggulangan bencana, perlu pemberlakuan standar kompetensi kerja dalam bidang penanggulangan bencana melalui penyelenggaraan pendidikan dan pelatihan teknis;
b. bahwa berdasarkan Keputusan Menteri Ketenagakerjaan Nomor 60 Tahun 2018, telah ditetapkan Standar Kompetensi Kerja Nasional Indonesia Kategori Administrasi Golongan Pokok Administrasi Pemerintahan dan Pertahanan dan Jaminan Sosial Wajib Bidang Penanggulangan Bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2019 tentang Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1680, 'perban-1-2019', 2, 'mengingat', 'Mengingat', NULL, 2, '2019, No. 739 -2-
1. Undang-Undang Nomor 13 Tahun 2003 tentang Ketenagakerjaan (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 39, Tambahan Lembaran Negara Republik Indonesia Nomor 4279);
