INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1681, 'perban-1-2019', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEMBERLAKUAN STANDAR KOMPETENSI KERJA NASIONAL INDONESIA BIDANG PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1681, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEMBERLAKUAN STANDAR KOMPETENSI KERJA NASIONAL INDONESIA BIDANG PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2019 tentang Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1682, 'perban-1-2019', 4, 'pasal', 'Pasal 1', 'BAB II MAKSUD DAN TUJUAN', 3, 'Dalam peraturan ini yang dimaksud dengan:
1. Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana yang selanjutnya disebut SKKNI PB adalah rumusan kemampuan kerja yang mencakup aspek pengetahuan, keterampilan dan/atau keahlian serta sikap kerja yang relevan dengan persyaratan profesi bidang penanggulangan bencana yang ditetapkan sesuai dengan ketentuan peraturan perundang-undangan.
2. Lembaga Sertifikasi Profesi bidang Penanggulangan Bencana yang selanjutnya disebut LSP PB adalah lembaga pelaksana kegiatan sertifikasi kompetensi kerja di bidang penanggulangan bencana berdasarkan lisensi dari Badan Nasional Sertifikasi Profesi.
3. Pengguna adalah Pemerintah, pemerintah daerah, masyarakat, dan lembaga usaha.
4. Tenaga Kerja Asing adalah warga negara asing yang bekerja di wilayah Negara Kesatuan Republik Indonesia sesuai dengan ketentuan peraturan perundang-undangan.
5. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat BNPB adalah lembaga pemerintah non-kementerian sesuai dengan ketentuan peraturan perundang-undangan.
2019, No. 739 -4-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1682, 'Dalam peraturan ini yang dimaksud dengan:
1. Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana yang selanjutnya disebut SKKNI PB adalah rumusan kemampuan kerja yang mencakup aspek pengetahuan, keterampilan dan/atau keahlian serta sikap kerja yang relevan dengan persyaratan profesi bidang penanggulangan bencana yang ditetapkan sesuai dengan ketentuan peraturan perundang-undangan.
2. Lembaga Sertifikasi Profesi bidang Penanggulangan Bencana yang selanjutnya disebut LSP PB adalah lembaga pelaksana kegiatan sertifikasi kompetensi kerja di bidang penanggulangan bencana berdasarkan lisensi dari Badan Nasional Sertifikasi Profesi.
3. Pengguna adalah Pemerintah, pemerintah daerah, masyarakat, dan lembaga usaha.
4. Tenaga Kerja Asing adalah warga negara asing yang bekerja di wilayah Negara Kesatuan Republik Indonesia sesuai dengan ketentuan peraturan perundang-undangan.
5. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat BNPB adalah lembaga pemerintah non-kementerian sesuai dengan ketentuan peraturan perundang-undangan.
2019, No. 739 -4-', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2019 tentang Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1683, 'perban-1-2019', 5, 'pasal', 'Pasal 2', 'BAB III PEMBERLAKUAN SKKNI PB', 4, '(1) Peraturan Badan ini dimaksudkan sebagai acuan dalam penyelenggaraan pendidikan dan pelatihan kerja profesi dan sertifikasi kompetensi kerja di bidang penanggulangan bencana.
(2) Peraturan Badan ini bertujuan untuk mewujudkan tenaga kerja di bidang penanggulangan bencana yang kompeten dan profesional untuk meningkatkan daya tahan, daya saing, dan produktifitas kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1683, '(1) Peraturan Badan ini dimaksudkan sebagai acuan dalam penyelenggaraan pendidikan dan pelatihan kerja profesi dan sertifikasi kompetensi kerja di bidang penanggulangan bencana.
(2) Peraturan Badan ini bertujuan untuk mewujudkan tenaga kerja di bidang penanggulangan bencana yang kompeten dan profesional untuk meningkatkan daya tahan, daya saing, dan produktifitas kerja.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2019 tentang Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1684, 'perban-1-2019', 6, 'pasal', 'Pasal 3', 'BAB III PEMBERLAKUAN SKKNI PB', 4, '(1) SKKNI PB meliputi unit kompetensi yang hasilnya merupakan satu satuan yang terukur pada subbidang prabencana, tanggap darurat, dan pascabencana.
(2) SKKNI PB sebagaimana dimaksud pada ayat (1) berlaku secara nasional bagi Pengguna.
(3) SKKNI PB sebagaimana dimaksud pada ayat (2) berlaku bagi Tenaga Kerja Asing yang melaksanakan kegiatan penanggulangan bencana di Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1684, '(1) SKKNI PB meliputi unit kompetensi yang hasilnya merupakan satu satuan yang terukur pada subbidang prabencana, tanggap darurat, dan pascabencana.
(2) SKKNI PB sebagaimana dimaksud pada ayat (1) berlaku secara nasional bagi Pengguna.
(3) SKKNI PB sebagaimana dimaksud pada ayat (2) berlaku bagi Tenaga Kerja Asing yang melaksanakan kegiatan penanggulangan bencana di Indonesia.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2019 tentang Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1685, 'perban-1-2019', 7, 'pasal', 'Pasal 4', 'BAB IV KETENTUAN PENUTUP', 4, '(1) Bidang keterampilan dan/atau keahlian yang menjadi obyek pemberlakuan SKKNI PB telah ditetapkan dengan keputusan menteri yang menyelenggarakan urusan pemerintahan di bidang ketenagakerjaan.
(2) Bidang keterampilan dan/atau keahlian sebagaimana dimaksud pada ayat (1) tercantum dalam lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
2019, No. 739
(3) Dalam hal SKKNI PB tidak dilaksanakan sesuai ketentuan, Pengguna dikenakan sanksi sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1685, '(1) Bidang keterampilan dan/atau keahlian yang menjadi obyek pemberlakuan SKKNI PB telah ditetapkan dengan keputusan menteri yang menyelenggarakan urusan pemerintahan di bidang ketenagakerjaan.
(2) Bidang keterampilan dan/atau keahlian sebagaimana dimaksud pada ayat (1) tercantum dalam lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
2019, No. 739
(3) Dalam hal SKKNI PB tidak dilaksanakan sesuai ketentuan, Pengguna dikenakan sanksi sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2019 tentang Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1686, 'perban-1-2019', 8, 'pasal', 'Pasal 5', 'BAB IV KETENTUAN PENUTUP', 5, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2015 tentang Penetapan dan Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana dicabut dan dinyatakan tidak berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1686, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2015 tentang Penetapan dan Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana dicabut dan dinyatakan tidak berlaku.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2019 tentang Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1687, 'perban-1-2019', 9, 'pasal', 'Pasal 6', 'BAB IV KETENTUAN PENUTUP', 5, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
2019, No. 739 -6- Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1687, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
