INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1688, 'perban-1-2019', 10, 'lain', 'Penutup', NULL, 6, 'Ditetapkan di Jakarta pada tanggal 29 April 2019 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd DONI MONARDO Diundangkan di Jakarta pada tanggal 4 Juli 2019 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd.
