INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1689, 'perban-1-2019', 11, 'lampiran', 'Lampiran hal. 7', NULL, 7, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA NOMOR 1 TAHUN 2019 TENTANG PEMBERLAKUAN STANDAR KOMPETENSI KERJA NASIONAL INDONESIA BIDANG PENANGGULANGAN BENCANA JUDUL KEPUTUSAN STANDAR TANGGAL NO. MENTERI KOMPETENSI KERJA PENETAPAN KETENAGAKERJAAN NASIONAL INDONESIA (SKKNI) PB
