INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1691, 'perban-1-2020', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk penyelarasan pengetahuan penanggulangan bencana dan meningkatkan mutu, efisiensi, efektivitas, dan akuntabilitas penyelenggaraan pendidikan dan pelatihan teknis penanggulangan bencana, diperlukan akreditasi atas lembaga penyelenggara pendidikan dan pelatihan untuk pendidikan dan pelatihan teknis penanggulangan bencana,
