INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1692, '1. Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
