INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1693, 'perban-1-2020', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG AKREDITASI PENDIDIKAN DAN PELATIHAN TEKNIS PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1693, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG AKREDITASI PENDIDIKAN DAN PELATIHAN TEKNIS PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1694, 'perban-1-2020', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Pusat Pendidikan dan Pelatihan Penanggulangan Bencana yang selanjutnya disebut Pusdiklat PB, adalah unit kerja yang mempunyai tugas melaksanakan pengoordinasian dan penyelenggaraan pengembangan kapasitas sumber daya manusia di bidang penanggulangan bencana.
2. Pendidikan dan pelatihan yang selanjutnya disebut Diklat, adalah proses penyelenggaraan belajar mengajar dalam rangka meningkatkan kemampuan sumber daya manusia.
3. Diklat Teknis Penanggulangan Bencana yang selanjutnya disebut Diklat Teknis PB, adalah Diklat yang diselenggarakan untuk memberikan penguasaan pengetahuan dan keterampilan di bidang penanggulangan bencana.
4. Akreditasi Diklat Teknis PB adalah penilaian kelayakan lembaga penyelenggara Diklat dalam melaksanakan Diklat Teknis PB yang ditetapkan dalam Surat Keputusan dan Sertifikat Akreditasi oleh instansi pembina Diklat Teknis PB.
5. Instansi Pembina Diklat Teknis PB yang selanjutnya disebut Instansi Pembina adalah Badan Nasional Penanggulangan Bencana.
6. Tim Akreditasi adalah tim yang dibentuk untuk melaksanakan penilaian pemenuhan persyaratan akreditasi lembaga penyelenggara Diklat Teknis PB.
7. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB, adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam Undang-Undang tentang penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1694, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Pusat Pendidikan dan Pelatihan Penanggulangan Bencana yang selanjutnya disebut Pusdiklat PB, adalah unit kerja yang mempunyai tugas melaksanakan pengoordinasian dan penyelenggaraan pengembangan kapasitas sumber daya manusia di bidang penanggulangan bencana.
2. Pendidikan dan pelatihan yang selanjutnya disebut Diklat, adalah proses penyelenggaraan belajar mengajar dalam rangka meningkatkan kemampuan sumber daya manusia.
3. Diklat Teknis Penanggulangan Bencana yang selanjutnya disebut Diklat Teknis PB, adalah Diklat yang diselenggarakan untuk memberikan penguasaan pengetahuan dan keterampilan di bidang penanggulangan bencana.
4. Akreditasi Diklat Teknis PB adalah penilaian kelayakan lembaga penyelenggara Diklat dalam melaksanakan Diklat Teknis PB yang ditetapkan dalam Surat Keputusan dan Sertifikat Akreditasi oleh instansi pembina Diklat Teknis PB.
5. Instansi Pembina Diklat Teknis PB yang selanjutnya disebut Instansi Pembina adalah Badan Nasional Penanggulangan Bencana.
6. Tim Akreditasi adalah tim yang dibentuk untuk melaksanakan penilaian pemenuhan persyaratan akreditasi lembaga penyelenggara Diklat Teknis PB.
7. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB, adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam Undang-Undang tentang penanggulangan bencana.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1695, 'perban-1-2020', 5, 'pasal', 'Pasal 2', 'BAB II INSTANSI PEMBINA, KEWENANGAN AKREDITASI LEMBAGA DIKLAT TEKNIS PB DAN LEMBAGA PENYELENGGARA DIKLAT TEKNIS PB; Bagian Kesatu Instansi Pembina', 3, 'Akreditasi Diklat Teknis PB bertujuan sebagai menjamin kualitas Diklat Teknis PB melalui serangkaian penilaian terhadap unsur akreditasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1695, 'Akreditasi Diklat Teknis PB bertujuan sebagai menjamin kualitas Diklat Teknis PB melalui serangkaian penilaian terhadap unsur akreditasi.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1696, 'perban-1-2020', 6, 'pasal', 'Pasal 3', 'BAB II INSTANSI PEMBINA, KEWENANGAN AKREDITASI LEMBAGA DIKLAT TEKNIS PB DAN LEMBAGA PENYELENGGARA DIKLAT TEKNIS PB; Bagian Kedua Lembaga Penyelenggara Diklat Teknis PB', 3, '(1) Dalam rangka menjamin kualitas penyelenggaraan Diklat Teknis PB sebagaimana dimaksud dalam Pasal 2, Instansi Pembina berwenang melakukan akreditasi terhadap lembaga penyelenggara Diklat.
(2) Selain melakukan akreditasi, Instansi Pembina sebagaimana dimaksud pada ayat (1) berwenang:
a. menyusun petunjuk pelaksanaan akreditasi; dan
b. melakukan monitoring dan evaluasi.
(3) Kewenangan sebagaimana dimaksud pada ayat (1) dan (2) tidak dapat didelegasikan kepada lembaga penyelenggara Diklat setelah mendapatkan akreditasi dari Instansi Pembina.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1696, '(1) Dalam rangka menjamin kualitas penyelenggaraan Diklat Teknis PB sebagaimana dimaksud dalam Pasal 2, Instansi Pembina berwenang melakukan akreditasi terhadap lembaga penyelenggara Diklat.
(2) Selain melakukan akreditasi, Instansi Pembina sebagaimana dimaksud pada ayat (1) berwenang:
a. menyusun petunjuk pelaksanaan akreditasi; dan
b. melakukan monitoring dan evaluasi.
(3) Kewenangan sebagaimana dimaksud pada ayat (1) dan (2) tidak dapat didelegasikan kepada lembaga penyelenggara Diklat setelah mendapatkan akreditasi dari Instansi Pembina.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1697, 'perban-1-2020', 7, 'pasal', 'Pasal 4', 'BAB II INSTANSI PEMBINA, KEWENANGAN AKREDITASI LEMBAGA DIKLAT TEKNIS PB DAN LEMBAGA PENYELENGGARA DIKLAT TEKNIS PB; Bagian Kedua Lembaga Penyelenggara Diklat Teknis PB', 4, '(1) Lembaga penyelenggara Diklat sebagaimana dimaksud dalam Pasal 3 ayat (1) bersifat mandiri atau merupakan bagian dari satuan unit organisasi yang melaksanakan Diklat Teknis PB.
(2) Lembaga penyelenggara Diklat meliputi:
a. Pemerintah;
b. Pemerintah Daerah;
c. lembaga usaha; dan
d. masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1697, '(1) Lembaga penyelenggara Diklat sebagaimana dimaksud dalam Pasal 3 ayat (1) bersifat mandiri atau merupakan bagian dari satuan unit organisasi yang melaksanakan Diklat Teknis PB.
(2) Lembaga penyelenggara Diklat meliputi:
a. Pemerintah;
b. Pemerintah Daerah;
c. lembaga usaha; dan
d. masyarakat.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1698, 'perban-1-2020', 8, 'pasal', 'Pasal 5', 'BAB III UNSUR, SUB UNSUR, DAN KOMPONEN AKREDITASI; Bagian Kesatu Unsur Akreditasi', 4, 'Akreditasi bagi penyelenggara Diklat pada lembaga usaha dan masyarakat dilaksanakan terhadap lembaga diklat lembaga usaha dan masyarakat yang berbadan hukum Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1698, 'Akreditasi bagi penyelenggara Diklat pada lembaga usaha dan masyarakat dilaksanakan terhadap lembaga diklat lembaga usaha dan masyarakat yang berbadan hukum Indonesia.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1699, 'perban-1-2020', 9, 'pasal', 'Pasal 6', 'BAB III UNSUR, SUB UNSUR, DAN KOMPONEN AKREDITASI; Bagian Kedua Sub Unsur dan Komponen dari Unsur Lembaga', 5, '(1) Akreditasi Lembaga penyelenggara Diklat dilakukan melalui penilaian terhadap unsur lembaga dan unsur program dan pengelolaan program.
(2) Dalam hal Lembaga penyelenggara Diklat Teknis PB merupakan lembaga usaha dan masyarakat, penilaian terhadap unsur lembaga dan unsur program dan pengelolaan program dilakukan terhadap nomenklatur yang disetarakan dengan unsur yang dinilai pada penyelenggara Diklat Teknis PB yang merupakan instansi Pemerintah.
(3) Ketentuan lebih lanjut mengenai penilaian terhadap unsur lembaga dan unsur program dan pengelolaan program sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1699, '(1) Akreditasi Lembaga penyelenggara Diklat dilakukan melalui penilaian terhadap unsur lembaga dan unsur program dan pengelolaan program.
(2) Dalam hal Lembaga penyelenggara Diklat Teknis PB merupakan lembaga usaha dan masyarakat, penilaian terhadap unsur lembaga dan unsur program dan pengelolaan program dilakukan terhadap nomenklatur yang disetarakan dengan unsur yang dinilai pada penyelenggara Diklat Teknis PB yang merupakan instansi Pemerintah.
(3) Ketentuan lebih lanjut mengenai penilaian terhadap unsur lembaga dan unsur program dan pengelolaan program sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1700, 'perban-1-2020', 10, 'pasal', 'Pasal 7', 'BAB III UNSUR, SUB UNSUR, DAN KOMPONEN AKREDITASI; Bagian Ketiga Sub Unsur dan Komponen dari Unsur Program dan', 5, '(1) Unsur lembaga sebagaimana dimaksud dalam Pasal 6 ayat (1) terdiri dari beberapa sub unsur yang terdiri atas:
a. kelembagaan Diklat;
b. tenaga kediklatan;
c. rencana strategis;
d. penjaminan pembiayaan;
e. fasilitas Diklat; dan
f. penjaminan mutu.
(2) Tenaga kediklatan sebagaimana dimaksud pada ayat
(1) huruf b, terdiri dari beberapa komponen yang terdiri atas:
a. pengelola Diklat;
b. penyelenggara Diklat;
c. tenaga pendidik; dan
d. pengelola Sistem Informasi Kediklatan.
(3) Ketentuan lebih lanjut mengenai sub unsur sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.
Pengelolaan Program');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1700, '(1) Unsur lembaga sebagaimana dimaksud dalam Pasal 6 ayat (1) terdiri dari beberapa sub unsur yang terdiri atas:
a. kelembagaan Diklat;
b. tenaga kediklatan;
c. rencana strategis;
d. penjaminan pembiayaan;
e. fasilitas Diklat; dan
f. penjaminan mutu.
(2) Tenaga kediklatan sebagaimana dimaksud pada ayat
(1) huruf b, terdiri dari beberapa komponen yang terdiri atas:
a. pengelola Diklat;
b. penyelenggara Diklat;
c. tenaga pendidik; dan
d. pengelola Sistem Informasi Kediklatan.
(3) Ketentuan lebih lanjut mengenai sub unsur sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.
Pengelolaan Program', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1701, 'perban-1-2020', 11, 'pasal', 'Pasal 8', 'BAB IV TIM AKREDITASI', 6, '(1) Unsur program dan pengelolaan program sebagaimana dimaksud dalam Pasal 7 ayat (1) terdiri atas sub unsur:
a. kurikulum program; dan
b. pengelolaan program.
(2) Sub unsur pengelolaan program sebagaimana dimaksud pada ayat (1) huruf b meliputi:
a. perencanaan;
b. penyelenggaraan;
c. monitoring dan evaluasi; dan
d. hasil penyelenggaraan.
(3) Ketentuan lebih lanjut mengenai unsur program dan pengelolaan program sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1701, '(1) Unsur program dan pengelolaan program sebagaimana dimaksud dalam Pasal 7 ayat (1) terdiri atas sub unsur:
a. kurikulum program; dan
b. pengelolaan program.
(2) Sub unsur pengelolaan program sebagaimana dimaksud pada ayat (1) huruf b meliputi:
a. perencanaan;
b. penyelenggaraan;
c. monitoring dan evaluasi; dan
d. hasil penyelenggaraan.
(3) Ketentuan lebih lanjut mengenai unsur program dan pengelolaan program sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1702, 'perban-1-2020', 12, 'pasal', 'Pasal 9', 'BAB V TAHAPAN PELAKSANAAN AKREDITASI', 7, '(1) Dalam pelaksanaan akreditasi Diklat Teknis PB, dibentuk tim akreditasi.
(2) Tim akreditasi sebagaimana dimaksud pada ayat (1) ditetapkan oleh Sekretaris Utama BNPB.
(3) Tim akreditasi sebagaimana dimaksud pada ayat (2) terdiri atas:
a. assessor;
b. sekretariat akreditasi; dan
c. tim penilai.
(4) Ketentuan lebih lanjut mengenai tim akreditasi sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1702, '(1) Dalam pelaksanaan akreditasi Diklat Teknis PB, dibentuk tim akreditasi.
(2) Tim akreditasi sebagaimana dimaksud pada ayat (1) ditetapkan oleh Sekretaris Utama BNPB.
(3) Tim akreditasi sebagaimana dimaksud pada ayat (2) terdiri atas:
a. assessor;
b. sekretariat akreditasi; dan
c. tim penilai.
(4) Ketentuan lebih lanjut mengenai tim akreditasi sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1703, 'perban-1-2020', 13, 'pasal', 'Pasal 10', 'BAB VI HAK DAN KEWAJIBAN LEMBAGA PENYELENGGARA DIKLAT TERAKREDITASI', 7, '(1) Akreditasi Diklat Teknis PB diperoleh melalui tahapan pelaksanaan kegiatan yang meliputi:
a. penerimaan permohonan akreditasi;
b. verifikasi;
c. visitasi; dan
d. penilaian.
(2) Instansi Pembina menerbitkan surat keputusan dan sertifikat akreditasi kepada lembaga penyelenggara Diklat Teknis PB yang memenuhi standar penilaian unsur akreditasi.
(3) Dalam hal lembaga penyelenggara Diklat tidak memenuhi standar penilaian unsur akreditasi, Instansi Pembina memberikan surat keterangan tidak terakreditasi.
(4) Ketentuan lebih lanjut mengenai tahapan pelaksanaan kegiatan akreditasi diatur melalui Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1703, '(1) Akreditasi Diklat Teknis PB diperoleh melalui tahapan pelaksanaan kegiatan yang meliputi:
a. penerimaan permohonan akreditasi;
b. verifikasi;
c. visitasi; dan
d. penilaian.
(2) Instansi Pembina menerbitkan surat keputusan dan sertifikat akreditasi kepada lembaga penyelenggara Diklat Teknis PB yang memenuhi standar penilaian unsur akreditasi.
(3) Dalam hal lembaga penyelenggara Diklat tidak memenuhi standar penilaian unsur akreditasi, Instansi Pembina memberikan surat keterangan tidak terakreditasi.
(4) Ketentuan lebih lanjut mengenai tahapan pelaksanaan kegiatan akreditasi diatur melalui Petunjuk Pelaksanaan.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1704, 'perban-1-2020', 14, 'pasal', 'Pasal 11', 'BAB VII PEMBINAAN, MONITORING DAN EVALUASI', 8, '(1) Lembaga penyelenggara Diklat terakreditasi berhak menyelenggarakan Diklat Teknis PB sebagaimana ditetapkan dalam sertifikat akreditasi.
(2) Lembaga penyelenggara Diklat terakreditasi wajib menyampaikan laporan dalam setiap penyelenggaraan Diklat Teknis PB kepada Instansi Pembina.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1704, '(1) Lembaga penyelenggara Diklat terakreditasi berhak menyelenggarakan Diklat Teknis PB sebagaimana ditetapkan dalam sertifikat akreditasi.
(2) Lembaga penyelenggara Diklat terakreditasi wajib menyampaikan laporan dalam setiap penyelenggaraan Diklat Teknis PB kepada Instansi Pembina.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1705, 'perban-1-2020', 15, 'pasal', 'Pasal 12', 'BAB VII PEMBINAAN, MONITORING DAN EVALUASI', 8, '(1) Instansi Pembina bertanggung jawab melakukan pembinaan Diklat bagi lembaga penyelenggara Diklat terakreditasi dilakukan melalui:
(2) Pembinaan Diklat merupakan kegiatan yang dilakukan agar pelaksanaan Diklat dan capaian kinerja Diklat sesuai dengan standar kompetensi dan sasaran yang ditetapkan.
(3) Pembinaan Diklat meliputi:
a. penyediaan kurikulum, modul, dan panduan terkait dengan pelaksanaan Diklat Teknis PB;
b. pelatihan untuk pelatih, seminar, dan workshop terkait dengan pelaksanaan Diklat Teknis PB;
c. pemberian informasi dalam rangka pemenuhan persyaratan dan kewajiban akreditasi; dan/atau
d. penerapan sistem manajemen mutu dalam pelaksanaan Diklat Teknis PB untuk meningkatkan kinerja pelaksanaan Diklat Teknis PB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1705, '(1) Instansi Pembina bertanggung jawab melakukan pembinaan Diklat bagi lembaga penyelenggara Diklat terakreditasi dilakukan melalui:
(2) Pembinaan Diklat merupakan kegiatan yang dilakukan agar pelaksanaan Diklat dan capaian kinerja Diklat sesuai dengan standar kompetensi dan sasaran yang ditetapkan.
(3) Pembinaan Diklat meliputi:
a. penyediaan kurikulum, modul, dan panduan terkait dengan pelaksanaan Diklat Teknis PB;
b. pelatihan untuk pelatih, seminar, dan workshop terkait dengan pelaksanaan Diklat Teknis PB;
c. pemberian informasi dalam rangka pemenuhan persyaratan dan kewajiban akreditasi; dan/atau
d. penerapan sistem manajemen mutu dalam pelaksanaan Diklat Teknis PB untuk meningkatkan kinerja pelaksanaan Diklat Teknis PB.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1706, 'perban-1-2020', 16, 'pasal', 'Pasal 13', 'BAB VIII KETENTUAN PENUTUP', 9, '(1) Monitoring dan evaluasi bagi lembaga penyelenggara Diklat terakreditasi dilakukan terhadap:
a. pemenuhan persyaratan akreditasi sebagaimana dimaksud dalam Pasal 6 sampai dengan Pasal 8; dan
b. pemenuhan hak dan kewajiban sebagaimana dimaksud dalam Pasal 11.
(2) Monitoring dan evaluasi sebagaimana dimaksud pada ayat (1) dilakukan sesuai kebutuhan dan/atau paling sedikit 1 (satu) kali dalam jangka waktu 1 (satu) tahun.
(3) Monitoring dan evaluasi sebagaimana dimaksud pada ayat (2) dengan cara:
a. visitasi; dan
b. reviu laporan hasil pelaksanaan Diklat Teknis PB.
(4) Hasil monitoring dan evaluasi dapat mempengaruhi nilai kelayakan akreditasi sebagai lembaga penyelenggara Diklat terakreditasi atau pencabutan status sebagai penyelenggara Diklat terakreditasi.
(5) Apabila dalam monitoring dan evaluasi sebagaimana dimaksud ayat (2) ditemukan pelanggaran atau penyimpangan terhadap pelaksanaan akreditasi maka akan dilakukan teguran pertama secara tertulis.
(6) Lembaga penyelenggara Diklat wajib menindaklanjuti teguran pertama.
(7) Apabila dalam kurun waktu tiga bulan tidak ada tanggapan atas teguran pertama maka akan dilakukan teguran kedua secara tertulis.
(8) Apabila dalam kurun waktu 3 (tiga) bulan tidak ada tanggapan atas teguran kedua maka akreditasi lembaga penyelenggara Diklat dicabut dan selanjutnya lembaga penyelenggara Diklat tidak memiliki kewenangan menyelenggarakan Diklat Teknis PB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1706, '(1) Monitoring dan evaluasi bagi lembaga penyelenggara Diklat terakreditasi dilakukan terhadap:
a. pemenuhan persyaratan akreditasi sebagaimana dimaksud dalam Pasal 6 sampai dengan Pasal 8; dan
b. pemenuhan hak dan kewajiban sebagaimana dimaksud dalam Pasal 11.
(2) Monitoring dan evaluasi sebagaimana dimaksud pada ayat (1) dilakukan sesuai kebutuhan dan/atau paling sedikit 1 (satu) kali dalam jangka waktu 1 (satu) tahun.
(3) Monitoring dan evaluasi sebagaimana dimaksud pada ayat (2) dengan cara:
a. visitasi; dan
b. reviu laporan hasil pelaksanaan Diklat Teknis PB.
(4) Hasil monitoring dan evaluasi dapat mempengaruhi nilai kelayakan akreditasi sebagai lembaga penyelenggara Diklat terakreditasi atau pencabutan status sebagai penyelenggara Diklat terakreditasi.
(5) Apabila dalam monitoring dan evaluasi sebagaimana dimaksud ayat (2) ditemukan pelanggaran atau penyimpangan terhadap pelaksanaan akreditasi maka akan dilakukan teguran pertama secara tertulis.
(6) Lembaga penyelenggara Diklat wajib menindaklanjuti teguran pertama.
(7) Apabila dalam kurun waktu tiga bulan tidak ada tanggapan atas teguran pertama maka akan dilakukan teguran kedua secara tertulis.
(8) Apabila dalam kurun waktu 3 (tiga) bulan tidak ada tanggapan atas teguran kedua maka akreditasi lembaga penyelenggara Diklat dicabut dan selanjutnya lembaga penyelenggara Diklat tidak memiliki kewenangan menyelenggarakan Diklat Teknis PB.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1707, 'perban-1-2020', 17, 'pasal', 'Pasal 14', 'BAB VIII KETENTUAN PENUTUP', 10, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1707, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1708, 'perban-1-2020', 18, 'lain', 'Penutup', NULL, 11, 'Ditetapkan di Jakarta pada tanggal 18 Februari 2020 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
DONI MONARDO Diundangkan di Jakarta pada tanggal 28 Februari 2020 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd.
WIDODO EKATJAHJANA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2020 NOMOR 186');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1708, 'Ditetapkan di Jakarta pada tanggal 18 Februari 2020 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
DONI MONARDO Diundangkan di Jakarta pada tanggal 28 Februari 2020 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd.
WIDODO EKATJAHJANA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2020 NOMOR 186', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1709, 'perban-1-2020', 19, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Satoe mah) Lana MAN Muabezi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1709, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Satoe mah) Lana MAN Muabezi', 'Lampiran hal. 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1710, 'perban-1-2020', 20, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR Ol TAHUN 2020 TENTANG AKREDITASI PENDIDIKAN DAN PELATIHAN TEKNIS PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN AKREDITASI PENDIDIKAN DAN PELATIHAN TEKNIS PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang BNPB sebagai Lembaga Pemerintah Nondepartemen setingkat Menteri, melalui Pusat Pendidikan dan Pelatihan Penanggulangan Bencana mempunyai tugas sebagaimana disebutkan dalam Pasal 281 Peraturan BNPB Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana, yaitu melaksanakan pengoordinasian dan penyelenggaraan pengembangan kapasitas sumber daya manusia di bidang penanggulangan bencana. Selain itu, berdasarkan Keputusan Kepala Lembaga Administrasi Negara Republik Indonesia Nomor 392/K. I/PDP.09/2016 pada tanggal 8 Desember 2016 Pusdiklat PB ditetapkan sebagai Instansi Pengakreditasi Diklat Teknis untuk Diklat Teknis Bidang Penanggulangan Bencana di bawah lingkungan Badan Nasional Penanggulangan Bencana dan Lembaga Diklat Pemerintah lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1710, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR Ol TAHUN 2020 TENTANG AKREDITASI PENDIDIKAN DAN PELATIHAN TEKNIS PENANGGULANGAN BENCANA PETUNJUK PELAKSANAAN AKREDITASI PENDIDIKAN DAN PELATIHAN TEKNIS PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang BNPB sebagai Lembaga Pemerintah Nondepartemen setingkat Menteri, melalui Pusat Pendidikan dan Pelatihan Penanggulangan Bencana mempunyai tugas sebagaimana disebutkan dalam Pasal 281 Peraturan BNPB Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana, yaitu melaksanakan pengoordinasian dan penyelenggaraan pengembangan kapasitas sumber daya manusia di bidang penanggulangan bencana. Selain itu, berdasarkan Keputusan Kepala Lembaga Administrasi Negara Republik Indonesia Nomor 392/K. I/PDP.09/2016 pada tanggal 8 Desember 2016 Pusdiklat PB ditetapkan sebagai Instansi Pengakreditasi Diklat Teknis untuk Diklat Teknis Bidang Penanggulangan Bencana di bawah lingkungan Badan Nasional Penanggulangan Bencana dan Lembaga Diklat Pemerintah lainnya.', 'Lampiran hal. 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1711, 'perban-1-2020', 21, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'Sejalan dengan tugas Pusdiklat PB dan kewenangan yang diperoleh dari Keputusan Kepala LAN RI, maka penyelenggaraan pendidikan dan pelatihan teknis penanggulangan bencana (Diklat Teknis PB) seyogyanya dilaksanakan oleh lembaga penyelenggara diklat yang telah terakreditasi Diklat Teknis PB. Adapun tujuan dari akreditasi Diklat Teknis PB adalah untuk menyelaraskan pengetahuan penanggulangan bencana dan meningkatkan mutu, efisiensi, efektivitas, dan akuntabilitas penyelenggaraan pendidikan dan pelatihan teknis penanggulangan bencana, serta percepatan diseminasi informasi dan peningkatan pengetahuan kebencanaan.
Berdasarkan Pasal 6 ayat (3), Pasal 7 ayat (3), Pasal 8 ayat (3), Pasal 9 ayat (4) dan Pasal 10 ayat (4) Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana, diperlukan pembentukan petunjuk pelaksanaan sebagai acuan pelaksanaan akreditasi pendidikan dan pelatihan teknis penanggulangan bencana.
B. Maksud dan Tujuan Maksud dari Petunjuk Pelaksanaan ini adalah:
1. sebagai panduan dalam pengajuan akreditasi diklat teknis PB bagi Penyelenggara Diklat; dan
2. sebagai pedoman dalam pelaksanaan dan penilaian akreditasi diklat teknis PB bagi Instansi Pembina.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1711, 'Sejalan dengan tugas Pusdiklat PB dan kewenangan yang diperoleh dari Keputusan Kepala LAN RI, maka penyelenggaraan pendidikan dan pelatihan teknis penanggulangan bencana (Diklat Teknis PB) seyogyanya dilaksanakan oleh lembaga penyelenggara diklat yang telah terakreditasi Diklat Teknis PB. Adapun tujuan dari akreditasi Diklat Teknis PB adalah untuk menyelaraskan pengetahuan penanggulangan bencana dan meningkatkan mutu, efisiensi, efektivitas, dan akuntabilitas penyelenggaraan pendidikan dan pelatihan teknis penanggulangan bencana, serta percepatan diseminasi informasi dan peningkatan pengetahuan kebencanaan.
Berdasarkan Pasal 6 ayat (3), Pasal 7 ayat (3), Pasal 8 ayat (3), Pasal 9 ayat (4) dan Pasal 10 ayat (4) Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana, diperlukan pembentukan petunjuk pelaksanaan sebagai acuan pelaksanaan akreditasi pendidikan dan pelatihan teknis penanggulangan bencana.
B. Maksud dan Tujuan Maksud dari Petunjuk Pelaksanaan ini adalah:
1. sebagai panduan dalam pengajuan akreditasi diklat teknis PB bagi Penyelenggara Diklat; dan
2. sebagai pedoman dalam pelaksanaan dan penilaian akreditasi diklat teknis PB bagi Instansi Pembina.', 'Lampiran hal. 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1712, 'perban-1-2020', 22, 'lampiran', 'Lampiran hal. 13', NULL, 13, 'Tujuan dari Petunjuk dan Akreditasi Diklat Teknis PB adalah untuk menyelaraskan pengetahuan penanggulangan bencana dan meningkatkan mutu, efisiensi, efektivitas, dan akuntabilitas penyelenggaraan diklat teknis PB serta untuk percepatan diseminasi informasi dan peningkatan pengetahuan kebencanaan.
C. Ruang Lingkup Petunjuk Pelaksanaan ini memuat:
1. penilaian terhadap unsur lembaga dan unsur program dan pengelolaan program;
2. sub unsur dan komponen dari unsur lembaga dan unsur program dan pengelolaan program;
3. tim akreditasi; dan
4. tahapan pelaksanaan kegiatan akreditasi.
D. Pengertian
1. Pusat Pendidikan dan Pelatihan Penanggulangan Bencana yang selanjutnya disingkat Pusdiklat PB adalah lembaga yang mempunyai tugas melaksanakan pengoordinasian dan 2 pelaksanaan kebijakan umum di bidang pendidikan dan pelatihan teknis kebencanaan.
2. Pendidikan dan Pelatihan yang selanjutnya disingkat Diklat adalah proses penyelenggaraan belajar mengajar dalam rangka meningkatkan kemampuan sumber daya manusia di bidang penanggulangan bencana.
3. Diklat Teknis Penanggulangan Bencana yang selanjutnya disingkat Diklat Teknis PB adalah diklat yang diselenggarakan untuk memberikan penguasaan pengetahuan dan keterampilan di bidang penanggulangan bencana.
4. Penyelenggara Diklat adalah Pemerintah, Pemerintah Daerah, Lembaga Usaha dan Masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1712, 'Tujuan dari Petunjuk dan Akreditasi Diklat Teknis PB adalah untuk menyelaraskan pengetahuan penanggulangan bencana dan meningkatkan mutu, efisiensi, efektivitas, dan akuntabilitas penyelenggaraan diklat teknis PB serta untuk percepatan diseminasi informasi dan peningkatan pengetahuan kebencanaan.
C. Ruang Lingkup Petunjuk Pelaksanaan ini memuat:
1. penilaian terhadap unsur lembaga dan unsur program dan pengelolaan program;
2. sub unsur dan komponen dari unsur lembaga dan unsur program dan pengelolaan program;
3. tim akreditasi; dan
4. tahapan pelaksanaan kegiatan akreditasi.
D. Pengertian
1. Pusat Pendidikan dan Pelatihan Penanggulangan Bencana yang selanjutnya disingkat Pusdiklat PB adalah lembaga yang mempunyai tugas melaksanakan pengoordinasian dan 2 pelaksanaan kebijakan umum di bidang pendidikan dan pelatihan teknis kebencanaan.
2. Pendidikan dan Pelatihan yang selanjutnya disingkat Diklat adalah proses penyelenggaraan belajar mengajar dalam rangka meningkatkan kemampuan sumber daya manusia di bidang penanggulangan bencana.
3. Diklat Teknis Penanggulangan Bencana yang selanjutnya disingkat Diklat Teknis PB adalah diklat yang diselenggarakan untuk memberikan penguasaan pengetahuan dan keterampilan di bidang penanggulangan bencana.
4. Penyelenggara Diklat adalah Pemerintah, Pemerintah Daerah, Lembaga Usaha dan Masyarakat.', 'Lampiran hal. 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1713, 'perban-1-2020', 23, 'lampiran', 'Lampiran hal. 14', NULL, 14, '5. Akreditasi Diklat Teknis PB adalah penilaian kelayakan lembaga pelaksana Diklat dalam melaksanakan Diklat Teknis PB yang ditetapkan dalam Surat Keputusan dan Sertifikat Akreditasi oleh Instansi Pembina Diklat Teknis PB.
6. Instansi Pembina Diklat Teknis PB yang selanjutnya disebut Instansi Pembina adalah Badan Nasional Penanggulangan Bencana yang secara fungsional bertanggung jawab atas pengaturan, koordinasi, dan penyelenggaraan serta akreditasi Diklat Teknis PB pada Lembaga Diklat Pemerintah, Pemerintah Daerah, Lembaga Usaha dan Masyarakat
7. Pembinaan Diklat adalah kegiatan yang dilakukan agar pelaksanaan Diklat dan capaian kinerja Diklat sesuai dengan standar kompetensi dan sasaran yang ditetapkan.
8. Tim Akreditasi adalah tim yang dibentuk untuk melaksanakan penilaian pemenuhan persyaratan akreditasi lembaga penyelenggara diklat teknis PB.
9. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat dengan BNPB adalah lembaga pemerintah nondepartemen sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1713, '5. Akreditasi Diklat Teknis PB adalah penilaian kelayakan lembaga pelaksana Diklat dalam melaksanakan Diklat Teknis PB yang ditetapkan dalam Surat Keputusan dan Sertifikat Akreditasi oleh Instansi Pembina Diklat Teknis PB.
6. Instansi Pembina Diklat Teknis PB yang selanjutnya disebut Instansi Pembina adalah Badan Nasional Penanggulangan Bencana yang secara fungsional bertanggung jawab atas pengaturan, koordinasi, dan penyelenggaraan serta akreditasi Diklat Teknis PB pada Lembaga Diklat Pemerintah, Pemerintah Daerah, Lembaga Usaha dan Masyarakat
7. Pembinaan Diklat adalah kegiatan yang dilakukan agar pelaksanaan Diklat dan capaian kinerja Diklat sesuai dengan standar kompetensi dan sasaran yang ditetapkan.
8. Tim Akreditasi adalah tim yang dibentuk untuk melaksanakan penilaian pemenuhan persyaratan akreditasi lembaga penyelenggara diklat teknis PB.
9. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat dengan BNPB adalah lembaga pemerintah nondepartemen sesuai dengan ketentuan peraturan perundang-undangan.', 'Lampiran hal. 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1714, 'perban-1-2020', 24, 'lampiran', 'Lampiran hal. 14', NULL, 14, '10. Lembaga masyarakat adalah lembaga yang dibentuk oleh anggota masyarakat Warga Negara Indonesia secara sukarela atas dasar kesamaan visi, misi, profesi, fungsi dan kegiatan untuk berperan serta dalam pembangunan dalam rangka 3 mencapai tujuan nasional dalam wadah Negara Kesatuan Republik Indonesia yang berdasarkan Pancasila, yang terdiri dari organisasi keagamaan, lembaga swadaya masyarakat, organisasi profesi, organisasi swasta, organisasi sosial, organisasi politik, media massa, dan bentuk organisasi lainnya.
11. Lembaga Usaha adalah setiap badan hukum yang dapat berbentuk Badan Usaha Milik Negara, Badan Usaha Milik Daerah, Koperasi, atau swasta yang didirikan sesuai dengan ketentuan peraturan perundang-undangan yang menjalankan jenis usaha tetap dan terus-menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia.
12. Lembaga Nonpemerintah adalah lembaga atau badan (organisasi) yang bukan menjadi bagian dari pemerintah, birokrasi ataupun negara yang dapat berbentuk lembaga swadaya masyarakat, lembaga/badan usaha, organisasi sosial masyarakat, perguruan tingi, organisasi komunitas berdasarkan profesi minat dan bakat, organisasi kemasyarakatan adat maupun keagamaan sesuai peraturan perundang-undangan dalam kegiatan penanggulangan bencana dan kegiatan kemanusiaan untuk memberikan pelayanan kepada masyarakat umum.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1714, '10. Lembaga masyarakat adalah lembaga yang dibentuk oleh anggota masyarakat Warga Negara Indonesia secara sukarela atas dasar kesamaan visi, misi, profesi, fungsi dan kegiatan untuk berperan serta dalam pembangunan dalam rangka 3 mencapai tujuan nasional dalam wadah Negara Kesatuan Republik Indonesia yang berdasarkan Pancasila, yang terdiri dari organisasi keagamaan, lembaga swadaya masyarakat, organisasi profesi, organisasi swasta, organisasi sosial, organisasi politik, media massa, dan bentuk organisasi lainnya.
11. Lembaga Usaha adalah setiap badan hukum yang dapat berbentuk Badan Usaha Milik Negara, Badan Usaha Milik Daerah, Koperasi, atau swasta yang didirikan sesuai dengan ketentuan peraturan perundang-undangan yang menjalankan jenis usaha tetap dan terus-menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia.
12. Lembaga Nonpemerintah adalah lembaga atau badan (organisasi) yang bukan menjadi bagian dari pemerintah, birokrasi ataupun negara yang dapat berbentuk lembaga swadaya masyarakat, lembaga/badan usaha, organisasi sosial masyarakat, perguruan tingi, organisasi komunitas berdasarkan profesi minat dan bakat, organisasi kemasyarakatan adat maupun keagamaan sesuai peraturan perundang-undangan dalam kegiatan penanggulangan bencana dan kegiatan kemanusiaan untuk memberikan pelayanan kepada masyarakat umum.', 'Lampiran hal. 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1715, 'perban-1-2020', 25, 'lampiran', 'Lampiran hal. 15', NULL, 15, 'BAB II PELAKSANAAN A. UNSUR, SUB UNSUR DAN KOMPONEN AKREDITASI DIKLAT TEKNIS PENANGGULANGAN BENCANA Akreditasi Diklat Teknis PB dilakukan melalui penilaian terhadap unsur, sub unsur dan komponen dari Akreditasi Diklat Teknis PB, yang terdiri atas:
1. Unsur Lembaga meliputi 6 (enam) sub unsur, yaitu:
a. Sub Unsur Kelembagaan Diklat;
b. Sub Unsur Tenaga Kediklatan, Sub Unsur Tenaga Kediklatan terdiri atas 4 (empat) komponen, yaitu:
4 1) Komponen Pengelola Diklat;
2) Komponen Penyelenggara Diklat;
3) Komponen Tenaga Pendidik; dan 4) Komponen Pengelola Sistem Informasi Kediklatan;
c. Sub Unsur Rencana Strategis/Perencanaan (AD/ART);
d. Sub Unsur Penjaminan Pembiayaan;
e. Sub Unsur Fasilitas Diklat; dan
f. Sub Unsur Penjaminan Mutu Diklat;
2. Unsur Program dan Pengelolaan Program meliputi 2 (dua) sub unsur, yaitu:
a. Sub Unsur Kurikulum; dan
b. Sub Unsur Pengelolaan Program, 1) Komponen Perencanaan Penyelenggaraan Diklat PB;
2) Komponen Penyelenggaraan Diklat PB;
3) Komponen Monitoring dan Evaluasi Penyelenggaraan Diklat PB; dan 4) Komponen Hasil Penyelenggaraan Diklat PB.
B. PENILAIAN AKREDITASI');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1715, 'BAB II PELAKSANAAN A. UNSUR, SUB UNSUR DAN KOMPONEN AKREDITASI DIKLAT TEKNIS PENANGGULANGAN BENCANA Akreditasi Diklat Teknis PB dilakukan melalui penilaian terhadap unsur, sub unsur dan komponen dari Akreditasi Diklat Teknis PB, yang terdiri atas:
1. Unsur Lembaga meliputi 6 (enam) sub unsur, yaitu:
a. Sub Unsur Kelembagaan Diklat;
b. Sub Unsur Tenaga Kediklatan, Sub Unsur Tenaga Kediklatan terdiri atas 4 (empat) komponen, yaitu:
4 1) Komponen Pengelola Diklat;
2) Komponen Penyelenggara Diklat;
3) Komponen Tenaga Pendidik; dan 4) Komponen Pengelola Sistem Informasi Kediklatan;
c. Sub Unsur Rencana Strategis/Perencanaan (AD/ART);
d. Sub Unsur Penjaminan Pembiayaan;
e. Sub Unsur Fasilitas Diklat; dan
f. Sub Unsur Penjaminan Mutu Diklat;
2. Unsur Program dan Pengelolaan Program meliputi 2 (dua) sub unsur, yaitu:
a. Sub Unsur Kurikulum; dan
b. Sub Unsur Pengelolaan Program, 1) Komponen Perencanaan Penyelenggaraan Diklat PB;
2) Komponen Penyelenggaraan Diklat PB;
3) Komponen Monitoring dan Evaluasi Penyelenggaraan Diklat PB; dan 4) Komponen Hasil Penyelenggaraan Diklat PB.
B. PENILAIAN AKREDITASI', 'Lampiran hal. 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1716, 'perban-1-2020', 26, 'lampiran', 'Lampiran hal. 16', NULL, 16, '1. PEMBOBOTAN AKREDITASI NO UNSUR/SUB UNSUR/ KOMPONEN BOBOT 1 Unsur Lembaga 50% 100% A Sub Unsur Kelembagaan / (KL) 5% B Sub Unsur Tenaga Kediklatan / 45% (TD) B.1. Komponen Pengelola 20% Diklat (KD) B.2. Komponen Penyelenggara 20% Diklat (SD) B.3. Komponen Tenaga 40% Pendidik (TP) B.4. Komponen Pengelola 20% Sistem Informasi Kediklatan (KSID) C Sub Unsur Rencana 10% Strategis/Perencanaan 5 (AD/ART) / (RS) D Sub Unsur Penjaminan 15% Pembiayaan (JB) E Sub Unsur Fasilitas Diklat (FD) 15% F Sub Unsur Penjaminan Mutu 10% (JM) 2 Unsur Program dan Pengelolaan Program 50% A. Sub Unsur Kurikulum / (KR) 30% B. Sub Unsur Pengelolaan Program 70% (KPr) B.1. Komponen Perencanaan 20% Penyelenggaraan Diklat (RSD) B.2. Komponen 40% Penyelenggaraan Diklat (SD) B.3. Komponen Monitoring dan 20% Evaluasi Penyelenggaraan Diklat (MESD) B.4. Komponen Hasil 20% Penyelenggaraan Diklat (HSD)
2. INDIKATOR DAN PENILAIAN AKREDITASI');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1716, '1. PEMBOBOTAN AKREDITASI NO UNSUR/SUB UNSUR/ KOMPONEN BOBOT 1 Unsur Lembaga 50% 100% A Sub Unsur Kelembagaan / (KL) 5% B Sub Unsur Tenaga Kediklatan / 45% (TD) B.1. Komponen Pengelola 20% Diklat (KD) B.2. Komponen Penyelenggara 20% Diklat (SD) B.3. Komponen Tenaga 40% Pendidik (TP) B.4. Komponen Pengelola 20% Sistem Informasi Kediklatan (KSID) C Sub Unsur Rencana 10% Strategis/Perencanaan 5 (AD/ART) / (RS) D Sub Unsur Penjaminan 15% Pembiayaan (JB) E Sub Unsur Fasilitas Diklat (FD) 15% F Sub Unsur Penjaminan Mutu 10% (JM) 2 Unsur Program dan Pengelolaan Program 50% A. Sub Unsur Kurikulum / (KR) 30% B. Sub Unsur Pengelolaan Program 70% (KPr) B.1. Komponen Perencanaan 20% Penyelenggaraan Diklat (RSD) B.2. Komponen 40% Penyelenggaraan Diklat (SD) B.3. Komponen Monitoring dan 20% Evaluasi Penyelenggaraan Diklat (MESD) B.4. Komponen Hasil 20% Penyelenggaraan Diklat (HSD)
2. INDIKATOR DAN PENILAIAN AKREDITASI', 'Lampiran hal. 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1717, 'perban-1-2020', 27, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'a. UNSUR LEMBAGA 1) Sub Unsur Kelembagaan Diklat a) Pengertian Kedudukan lembaga penyelenggara diklat/pengembangan kompetensi SDM dalam struktur organisasi Pemerintah, Pemerintah Daerah, lembaga usaha dan masyarakat dan kepemilikan tugas dan fungsi mandiri atau gabungan. b) Indikator Penilaian Kemandirian lembaga dalam menjalankan tugas. c) Cara Penilaian Penilaian terhadap sub unsur kelembagaan diklat dilakukan berdasarkan nilai kepemilikan tugas dan fungsi 6 mandiri atau gabungan lembaga dengan bobot penilaian sebesar 5% dari Unsur Lembaga yaitu 50%, yang dibuktikan dengan lampiran bukti fisik berupa:
1. Surat Keputusan atau Akta pendirian lembaga diklat; dan
2. uraian tupoksi/SOP/SOTK/struktur organisasi lembaga diklat, dengan perhitungan sebagaimana berikut:
𝑵𝒊𝒍𝒂𝒊 𝒌𝒆𝒑𝒆𝒎𝒊𝒍𝒊𝒌𝒂𝒏 𝒕𝒖𝒈𝒂𝒔 = 𝒙 𝟏𝟎𝟎 𝒙 𝟓% 𝟒 d) Kriteria Penilaian No. Uraian Nilai Keterangan
1. Mandiri 4 Berbadan hukum Indonesia dan mempunyai fungsi utama sebagai penyelenggara diklat/ pengembangan kompetensi SDM.
2. Tidak 2 Berbadan hukum Indonesia, tetapi tidak Mandiri mempunyai fungsi utama sebagai penyelenggara diklat/ pengembangan kompetensi SDM.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1717, 'a. UNSUR LEMBAGA 1) Sub Unsur Kelembagaan Diklat a) Pengertian Kedudukan lembaga penyelenggara diklat/pengembangan kompetensi SDM dalam struktur organisasi Pemerintah, Pemerintah Daerah, lembaga usaha dan masyarakat dan kepemilikan tugas dan fungsi mandiri atau gabungan. b) Indikator Penilaian Kemandirian lembaga dalam menjalankan tugas. c) Cara Penilaian Penilaian terhadap sub unsur kelembagaan diklat dilakukan berdasarkan nilai kepemilikan tugas dan fungsi 6 mandiri atau gabungan lembaga dengan bobot penilaian sebesar 5% dari Unsur Lembaga yaitu 50%, yang dibuktikan dengan lampiran bukti fisik berupa:
1. Surat Keputusan atau Akta pendirian lembaga diklat; dan
2. uraian tupoksi/SOP/SOTK/struktur organisasi lembaga diklat, dengan perhitungan sebagaimana berikut:
𝑵𝒊𝒍𝒂𝒊 𝒌𝒆𝒑𝒆𝒎𝒊𝒍𝒊𝒌𝒂𝒏 𝒕𝒖𝒈𝒂𝒔 = 𝒙 𝟏𝟎𝟎 𝒙 𝟓% 𝟒 d) Kriteria Penilaian No. Uraian Nilai Keterangan
1. Mandiri 4 Berbadan hukum Indonesia dan mempunyai fungsi utama sebagai penyelenggara diklat/ pengembangan kompetensi SDM.
2. Tidak 2 Berbadan hukum Indonesia, tetapi tidak Mandiri mempunyai fungsi utama sebagai penyelenggara diklat/ pengembangan kompetensi SDM.', 'Lampiran hal. 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1718, 'perban-1-2020', 28, 'lampiran', 'Lampiran hal. 18', NULL, 18, '2) Sub Unsur Tenaga Kediklatan a) Pengertian ASN dan/atau tenaga lain yang bertugas pada lembaga penyelenggara diklat atau lembaga yang mempunyai fungsi lainnya, yang terdiri dari Pengelola Diklat, Tenaga Pendidik, Penyelenggara Diklat dan Pengelola Sistem Informasi Diklat. b) Indikator Penilaian Kualitas dari Pengelola Diklat, Tenaga Pendidik, Penyelenggara Diklat dan Pengelola Sistem Informasi Diklat. c) Cara Penilaian Penilaian terhadap sub unsur Tenaga Kediklatan dilakukan berdasarkan nilai dari Komponen Pengelola Diklat, Tenaga Pendidik, Penyelenggara Diklat dan Pengelola Sistem Informasi Diklat dengan bobot penilaian sebesar 45% dari Unsur Lembaga, yaitu 50%, dengan perhitungan sebagaimana berikut: = 𝑵𝒊𝒍𝒂𝒊 𝑲𝒐𝒎𝒑𝒐𝒏𝒆𝒏 (𝑲𝑫 + 𝑷𝑫 + 𝑻𝑷 + 𝑲𝑺𝑰𝑫) 𝒙 𝟏𝟎𝟎 𝒙 𝟒𝟓% 7 2.1. Komponen Pengelola Diklat
(1) Pengertian ASN dan/atau tenaga lainnya seperti pejabat struktural (Eselon II/III/IV) atau top management, yang bertugas pada lembaga penyelenggara diklat atau lembaga yang mempunyai fungsi lainnya yang secara fungsional merencanakan, melaksanakan, mengawasi, mengendalikan dan mengevaluasi program diklat.
(2) Indikator Penilaian Kualitas Pengelola Diklat (pejabat struktural/top management).
(3) Cara Penilaian Penilaian komponen pengelola diklat dilakukan berdasarkan kepemilikan terhadap aspek kompetensi persyaratan seperti:
(a) Pengalaman kerja di bidang dan/atau pelatihan;
(b) Kompetensi pengelolaan diklat;
(c) Kompetensi kepemimpinan/ managemen development/ leadership training; dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1718, '2) Sub Unsur Tenaga Kediklatan a) Pengertian ASN dan/atau tenaga lain yang bertugas pada lembaga penyelenggara diklat atau lembaga yang mempunyai fungsi lainnya, yang terdiri dari Pengelola Diklat, Tenaga Pendidik, Penyelenggara Diklat dan Pengelola Sistem Informasi Diklat. b) Indikator Penilaian Kualitas dari Pengelola Diklat, Tenaga Pendidik, Penyelenggara Diklat dan Pengelola Sistem Informasi Diklat. c) Cara Penilaian Penilaian terhadap sub unsur Tenaga Kediklatan dilakukan berdasarkan nilai dari Komponen Pengelola Diklat, Tenaga Pendidik, Penyelenggara Diklat dan Pengelola Sistem Informasi Diklat dengan bobot penilaian sebesar 45% dari Unsur Lembaga, yaitu 50%, dengan perhitungan sebagaimana berikut: = 𝑵𝒊𝒍𝒂𝒊 𝑲𝒐𝒎𝒑𝒐𝒏𝒆𝒏 (𝑲𝑫 + 𝑷𝑫 + 𝑻𝑷 + 𝑲𝑺𝑰𝑫) 𝒙 𝟏𝟎𝟎 𝒙 𝟒𝟓% 7 2.1. Komponen Pengelola Diklat
(1) Pengertian ASN dan/atau tenaga lainnya seperti pejabat struktural (Eselon II/III/IV) atau top management, yang bertugas pada lembaga penyelenggara diklat atau lembaga yang mempunyai fungsi lainnya yang secara fungsional merencanakan, melaksanakan, mengawasi, mengendalikan dan mengevaluasi program diklat.
(2) Indikator Penilaian Kualitas Pengelola Diklat (pejabat struktural/top management).
(3) Cara Penilaian Penilaian komponen pengelola diklat dilakukan berdasarkan kepemilikan terhadap aspek kompetensi persyaratan seperti:
(a) Pengalaman kerja di bidang dan/atau pelatihan;
(b) Kompetensi pengelolaan diklat;
(c) Kompetensi kepemimpinan/ managemen development/ leadership training; dan', 'Lampiran hal. 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1719, 'perban-1-2020', 29, 'lampiran', 'Lampiran hal. 19', NULL, 19, '(d) Pengalaman menyelenggarakan diklat, dengan bobot penilaian sebesar 20% dari Sub Unsur Tenaga Kediklatan yaitu 45%, yang dibuktikan dengan lampiran bukti fisik berupa:
(a) Daftar Riwayat Hidup (sebagaimana tercantum dalam Format-A);
(b) Sertifikat Management of Training (MOT)/pelatihan pengelolaan diklat/pelatihan manajemen diklat yang disetarakan pada lembaga non pemerintah;
(c) Sertifikat Diklat PIM atau management development atau leadership training atau pelatihan kepemimpinan yang disetarakan pada lembaga non pemerintah; dan
(d) Surat Keputusan atau Surat Penugasan keikutsertaan penyelenggaraan diklat (minimal 2 kali dalam 5 tahun terakhir), dengan perhitungan sebagai berikut:
8
(a) Total Nilai Pengelola Diklat = 𝐾𝑒𝑝𝑒𝑚𝑖𝑙𝑖𝑘𝑎𝑛 𝑎𝑡𝑎𝑠 (𝐷𝑅𝐻 + 𝑀𝑂𝑇 + 𝐷𝑖𝑘𝑙𝑎𝑡 𝑃𝐼𝑀 + 𝑆𝐾 𝑎𝑡𝑎𝑢 𝑆𝑇 𝑃𝑒𝑛𝑦𝑒𝑙𝑒𝑛𝑔𝑔𝑎𝑟𝑎𝑎𝑛 𝐷𝑖𝑘𝑙𝑎𝑡)
(b) Rata-rata Nilai Pengelola Diklat 𝑇𝑜𝑡𝑎𝑙 𝑁𝑖𝑙𝑎𝑖 𝑃𝑒𝑛𝑔𝑒𝑙𝑜𝑙𝑎 𝑑𝑖𝑘𝑙𝑎𝑡 = 𝑗𝑢𝑚𝑙𝑎ℎ 𝑃𝑒𝑛𝑔𝑒𝑙𝑜𝑙𝑎 𝑑𝑖𝑘𝑙𝑎𝑡 Nilai Komponen Pengelola Diklat 𝑹𝒂𝒕𝒂 − 𝒓𝒂𝒕𝒂 𝑵𝒊𝒍𝒂𝒊 𝑷𝒆𝒏𝒈𝒆𝒍𝒐𝒍𝒂 𝑫𝒊𝒌𝒍𝒂𝒕 = 𝒙 𝟐𝟎% 𝟒
(4) Kriteria Penilaian No Uraian Nilai Keterangan
1. Memiliki 4 Pengelola memiliki keempat aspek seluruh kompetensi persyaratan, seperti: aspek (1) Daftar Riwat Hidup (dengan kompetensi melampirkan ijazah pendidikan persyaratan terakhir, dan portofolio pengalaman dalam 5 tahun terakhir);
(2) Sertifikat Management of Training (MOT) / pelatihan pengelolaan diklat / pelatihan manajemen diklat yang disetarakan pada lembaga non pemerintah;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1719, '(d) Pengalaman menyelenggarakan diklat, dengan bobot penilaian sebesar 20% dari Sub Unsur Tenaga Kediklatan yaitu 45%, yang dibuktikan dengan lampiran bukti fisik berupa:
(a) Daftar Riwayat Hidup (sebagaimana tercantum dalam Format-A);
(b) Sertifikat Management of Training (MOT)/pelatihan pengelolaan diklat/pelatihan manajemen diklat yang disetarakan pada lembaga non pemerintah;
(c) Sertifikat Diklat PIM atau management development atau leadership training atau pelatihan kepemimpinan yang disetarakan pada lembaga non pemerintah; dan
(d) Surat Keputusan atau Surat Penugasan keikutsertaan penyelenggaraan diklat (minimal 2 kali dalam 5 tahun terakhir), dengan perhitungan sebagai berikut:
8
(a) Total Nilai Pengelola Diklat = 𝐾𝑒𝑝𝑒𝑚𝑖𝑙𝑖𝑘𝑎𝑛 𝑎𝑡𝑎𝑠 (𝐷𝑅𝐻 + 𝑀𝑂𝑇 + 𝐷𝑖𝑘𝑙𝑎𝑡 𝑃𝐼𝑀 + 𝑆𝐾 𝑎𝑡𝑎𝑢 𝑆𝑇 𝑃𝑒𝑛𝑦𝑒𝑙𝑒𝑛𝑔𝑔𝑎𝑟𝑎𝑎𝑛 𝐷𝑖𝑘𝑙𝑎𝑡)
(b) Rata-rata Nilai Pengelola Diklat 𝑇𝑜𝑡𝑎𝑙 𝑁𝑖𝑙𝑎𝑖 𝑃𝑒𝑛𝑔𝑒𝑙𝑜𝑙𝑎 𝑑𝑖𝑘𝑙𝑎𝑡 = 𝑗𝑢𝑚𝑙𝑎ℎ 𝑃𝑒𝑛𝑔𝑒𝑙𝑜𝑙𝑎 𝑑𝑖𝑘𝑙𝑎𝑡 Nilai Komponen Pengelola Diklat 𝑹𝒂𝒕𝒂 − 𝒓𝒂𝒕𝒂 𝑵𝒊𝒍𝒂𝒊 𝑷𝒆𝒏𝒈𝒆𝒍𝒐𝒍𝒂 𝑫𝒊𝒌𝒍𝒂𝒕 = 𝒙 𝟐𝟎% 𝟒
(4) Kriteria Penilaian No Uraian Nilai Keterangan
1. Memiliki 4 Pengelola memiliki keempat aspek seluruh kompetensi persyaratan, seperti: aspek (1) Daftar Riwat Hidup (dengan kompetensi melampirkan ijazah pendidikan persyaratan terakhir, dan portofolio pengalaman dalam 5 tahun terakhir);
(2) Sertifikat Management of Training (MOT) / pelatihan pengelolaan diklat / pelatihan manajemen diklat yang disetarakan pada lembaga non pemerintah;', 'Lampiran hal. 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1720, 'perban-1-2020', 30, 'lampiran', 'Lampiran hal. 20', NULL, 20, '(3) Sertifikat Diklat PIM atau management development atau leadership training atau pelatihan kepemimpinan yang disetarakan pada lembaga non pemerintah; dan
(4) SK atau Surat Penugasan keikutsertaan penyelenggaraan diklat (minimal 2 kali dalam 5 tahun terakhir).
2. Memiliki 3 Pengelola memiliki tiga dari keempat tiga dari aspek kompetensi persyaratan, seperti: empat (1) Daftar Riwat Hidup (dengan aspek melampirkan ijazah pendidikan kompetensi terakhir, dan portofolio pengalaman persyaratan dalam 5 tahun terakhir);
(2) Sertifikat Management of Training (MOT) / pelatihan pengelolaan diklat / pelatihan manajemen diklat yang 9 disetarakan pada lembaga non pemerintah;
(3) Sertifikat Diklat PIM atau management development atau leadership training atau pelatihan kepemimpinan yang disetarakan pada lembaga non pemerintah; dan
(4) SK atau Surat Penugasan keikutsertaan penyelenggaraan diklat (minimal 2 kali dalam 5 tahun terakhir).
3. Memiliki 2 Pengelola memiliki dua dari keempat dua dari aspek kompetensi persyaratan, seperti: empat (1) Daftar Riwat Hidup (dengan aspek melampirkan ijazah pendidikan kompetensi terakhir, dan portofolio pengalaman persyaratan dalam 5 tahun terakhir);
(2) Sertifikat Management of Training (MOT) / pelatihan pengelolaan diklat / pelatihan manajemen diklat yang disetarakan pada lembaga non pemerintah;
(3) Sertifikat Diklat PIM atau management development atau leadership training atau pelatihan kepemimpinan yang disetarakan pada lembaga non pemerintah; dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1720, '(3) Sertifikat Diklat PIM atau management development atau leadership training atau pelatihan kepemimpinan yang disetarakan pada lembaga non pemerintah; dan
