INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1723, 'perban-1-2020', 33, 'lampiran', 'Lampiran hal. 23', NULL, 23, '2. Memiliki 3 Penyelenggara memiliki dua dari tiga dua dari aspek kompetensi persyaratan, seperti: tiga aspek (1) Daftar Riwat Hidup (dengan kompetensi melampirkan ijazah pendidikan persyaratan terakhir, dan portofolio pengalaman dalam 5 tahun terakhir);
(2) Sertifikat Training Officer Course (TOC) / pelatihan petugas penyelenggara diklat yang disetarakan pada lembaga non pemerintah; dan
(3) Surat Keputusan atau Surat Penugasan keikutsertaan penyelenggaraan diklat (minimal 2 kali dalam 5 tahun terakhir).
3. Memiliki 2 Penyelenggara memiliki satu dari tiga satu dari aspek kompetensi persyaratan, seperti: tiga aspek (1) Daftar Riwat Hidup (dengan 12 kompetensi melampirkan ijazah pendidikan persyaratan terakhir, dan portofolio pengalaman dalam 5 tahun terakhir);
(2) Sertifikat Training Officer Course (TOC) /pelatihan petugas penyelenggara diklat yang disetarakan pada lembaga non pemerintah; dan
(3) Surat Keputusan atau Surat Penugasan keikutsertaan penyelenggaraan diklat (minimal 2 kali dalam 5 tahun terakhir).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1723, '2. Memiliki 3 Penyelenggara memiliki dua dari tiga dua dari aspek kompetensi persyaratan, seperti: tiga aspek (1) Daftar Riwat Hidup (dengan kompetensi melampirkan ijazah pendidikan persyaratan terakhir, dan portofolio pengalaman dalam 5 tahun terakhir);
(2) Sertifikat Training Officer Course (TOC) / pelatihan petugas penyelenggara diklat yang disetarakan pada lembaga non pemerintah; dan
(3) Surat Keputusan atau Surat Penugasan keikutsertaan penyelenggaraan diklat (minimal 2 kali dalam 5 tahun terakhir).
3. Memiliki 2 Penyelenggara memiliki satu dari tiga satu dari aspek kompetensi persyaratan, seperti: tiga aspek (1) Daftar Riwat Hidup (dengan 12 kompetensi melampirkan ijazah pendidikan persyaratan terakhir, dan portofolio pengalaman dalam 5 tahun terakhir);
(2) Sertifikat Training Officer Course (TOC) /pelatihan petugas penyelenggara diklat yang disetarakan pada lembaga non pemerintah; dan
(3) Surat Keputusan atau Surat Penugasan keikutsertaan penyelenggaraan diklat (minimal 2 kali dalam 5 tahun terakhir).', 'Lampiran hal. 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1724, 'perban-1-2020', 34, 'lampiran', 'Lampiran hal. 24', NULL, 24, '4. Memiliki 1 Penyelenggara tidak memiliki ketiga aspek aspek kompetensi persyaratan. kompetensi persyaratan 2.3. Komponen Tenaga Pendidik 1) Pengertian Tenaga pendidik dapat berupa Widyaiswara, Narasumber dan Pelatih/Instruktur yang mempunyai tugas, tanggung jawab, dan wewenang untuk mendidik, mengajar, dan melatih serta melakukan evaluasi pengembangan diklat pada lembaga penyelenggara diklat. Tenaga pendidik dapat berasal dari unsur Pegawai Negeri Sipil, TNI/POLRI, Akademisi, Praktisi (tenaga profesional Non PNS).
2) Indikator Penilaian Kualitas tenaga pendidik di bidang kebencanaan.
3) Cara Penilaian Penilaian komponen tenaga pendidik dilakukan berdasarkan:
(a) Ketersediaan tenaga pendidik yang menguasai substansi, dinilai dari lampiran bukti fisik berupa sertifikat Training of Trainers (TOT) sesuai jenis diklat PB yang diajukan akreditasi.
(b) Penguasaan substansi pengetahuan tenaga pendidik yang berasal dari pendidikan formal, pelatihan TOT substansi sesuai jenis diklat PB yang diajukan akreditasi, dan pengembangan 13 profesi yang relevan, dinilai dari aspek penguasaan substansi pengetahuan yang dibuktikan dengan:
(1) Daftar Riwayat Hidup (sebagaimana tercantum dalam Format-A);
(2) sertifikat Training of Trainers (TOT) sesuai jenis diklat PB yang diajukan akreditasi;
(3) sertifikat pengembangan profesionalisme sesuai dengan PB (pelatihan, seminar, KTI, dsb); dan
(4) bahan ajar/bahan tayang sesuai spesialisasi/mata diklat yang diajarkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1724, '4. Memiliki 1 Penyelenggara tidak memiliki ketiga aspek aspek kompetensi persyaratan. kompetensi persyaratan 2.3. Komponen Tenaga Pendidik 1) Pengertian Tenaga pendidik dapat berupa Widyaiswara, Narasumber dan Pelatih/Instruktur yang mempunyai tugas, tanggung jawab, dan wewenang untuk mendidik, mengajar, dan melatih serta melakukan evaluasi pengembangan diklat pada lembaga penyelenggara diklat. Tenaga pendidik dapat berasal dari unsur Pegawai Negeri Sipil, TNI/POLRI, Akademisi, Praktisi (tenaga profesional Non PNS).
2) Indikator Penilaian Kualitas tenaga pendidik di bidang kebencanaan.
3) Cara Penilaian Penilaian komponen tenaga pendidik dilakukan berdasarkan:
(a) Ketersediaan tenaga pendidik yang menguasai substansi, dinilai dari lampiran bukti fisik berupa sertifikat Training of Trainers (TOT) sesuai jenis diklat PB yang diajukan akreditasi.
(b) Penguasaan substansi pengetahuan tenaga pendidik yang berasal dari pendidikan formal, pelatihan TOT substansi sesuai jenis diklat PB yang diajukan akreditasi, dan pengembangan 13 profesi yang relevan, dinilai dari aspek penguasaan substansi pengetahuan yang dibuktikan dengan:
(1) Daftar Riwayat Hidup (sebagaimana tercantum dalam Format-A);
(2) sertifikat Training of Trainers (TOT) sesuai jenis diklat PB yang diajukan akreditasi;
(3) sertifikat pengembangan profesionalisme sesuai dengan PB (pelatihan, seminar, KTI, dsb); dan
(4) bahan ajar/bahan tayang sesuai spesialisasi/mata diklat yang diajarkan.', 'Lampiran hal. 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1725, 'perban-1-2020', 35, 'lampiran', 'Lampiran hal. 25', NULL, 25, '(c) Pengalaman kerja tenaga pendidik yang mendukung penguasaan substansi, yang dibuktikan dengan:
(1) Surat Keputusan atau Penugasan mengajar pada program diklat teknis PB; atau
(2) Surat Keputusan atau Penugasan melaksanakan konsultan/riset/ praktisi/narasumber/fasilitator/dosen/guru/ instruktur/assessor/pelatih atau kegiatan lainnya yang mendukung penguasaan substansi, dengan bobot penilaian sebesar 40% dari Sub Unsur Tenaga Kediklatan sebesar 45%, dengan perhitungan sebagai berikut:
(1) Ketersediaan Tenaga Pendidik yang menguasai substansi = 𝑁𝑖𝑙𝑎𝑖 𝑘𝑒𝑡𝑒𝑟𝑠𝑒𝑑𝑖𝑎𝑎𝑛 𝑡𝑒𝑛𝑎𝑔𝑎 𝑝𝑒𝑛𝑑𝑖𝑑𝑖𝑘 𝑦𝑎𝑛𝑔 𝑚𝑒𝑛𝑔𝑢𝑎𝑠𝑎𝑖 𝑠𝑢𝑏𝑠𝑡𝑎𝑛𝑠𝑖
(2) Penguasaan substansi pengetahuan tenaga pendidik
(i) Total Nilai Penguasaan substansi = 𝑃𝑒𝑛𝑑. 𝑓𝑜𝑟𝑚𝑎𝑙 + 𝑆𝑒𝑟𝑡𝑖𝑓𝑖𝑘𝑎𝑡 𝑇𝑂𝑇 + 𝑆𝑒𝑟𝑡𝑖𝑓𝑖𝑘𝑎𝑡 𝑃𝑒𝑛𝑔𝑒𝑚𝑏𝑎𝑛𝑔𝑎𝑛 𝑃𝑟𝑜𝑓𝑒𝑠𝑖 + 𝐵ℎ𝑛. 𝑎𝑗𝑎𝑟/𝑡𝑎𝑦𝑎𝑛𝑔 14 (ii) Rata-rata nilai penguasaan subtansi 𝑇𝑜𝑡𝑎𝑙 𝑁𝑖𝑙𝑎𝑖 𝑃𝑒𝑛𝑔𝑢𝑎𝑠𝑎𝑎𝑛 𝑆𝑢𝑠𝑏𝑡𝑎𝑛𝑠𝑖 𝑇𝑒𝑛𝑎𝑔𝑎 𝑝𝑒𝑛𝑑𝑖𝑑𝑖𝑘 = 𝑗𝑢𝑚𝑙𝑎ℎ 𝑇𝑒𝑛𝑎𝑔𝑎 𝑝𝑒𝑛𝑑𝑖𝑑𝑖𝑘
(3) Pengalaman kerja tenaga pendidik yang mendukung penguasaan substansi
(i) Total Nilai Penguasaan substansi = 𝑃𝑒𝑛𝑔𝑎𝑙𝑎𝑚𝑎𝑛 𝑘𝑒𝑟𝑗𝑎 𝑠𝑒𝑡𝑎ℎ𝑢𝑛 ( > 2 𝑘𝑎𝑙𝑖 + 2 𝑘𝑎𝑙𝑖 + 1 𝑘𝑎𝑙𝑖 + 𝑡𝑖𝑑𝑎𝑘 𝑚𝑒𝑚𝑖𝑙𝑖𝑘𝑖) (ii) Rata-rata nilai penguasaan subtansi 𝑇𝑜𝑡𝑎𝑙 𝑁𝑖𝑙𝑎𝑖 𝑃𝑒𝑛𝑔𝑎𝑙𝑎𝑚𝑎𝑛 𝑘𝑒𝑟𝑗𝑎 𝑇𝑒𝑛𝑎𝑔𝑎 𝑝𝑒𝑛𝑑𝑖𝑑𝑖𝑘 = 𝑗𝑢𝑚𝑙𝑎ℎ 𝑇𝑒𝑛𝑎𝑔𝑎 𝑝𝑒𝑛𝑑𝑖𝑑𝑖𝑘 Nilai Komponen Tenaga Pendidik
(𝟏) + (𝟐) + (𝟑) = 𝒙 𝟒𝟎% 𝟏𝟐 4) Kriteria Penilaian No Uraian Nilai Keterangan
1. Ketersediaan tenaga pendidik yang menguasai substansi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1725, '(c) Pengalaman kerja tenaga pendidik yang mendukung penguasaan substansi, yang dibuktikan dengan:
(1) Surat Keputusan atau Penugasan mengajar pada program diklat teknis PB; atau
(2) Surat Keputusan atau Penugasan melaksanakan konsultan/riset/ praktisi/narasumber/fasilitator/dosen/guru/ instruktur/assessor/pelatih atau kegiatan lainnya yang mendukung penguasaan substansi, dengan bobot penilaian sebesar 40% dari Sub Unsur Tenaga Kediklatan sebesar 45%, dengan perhitungan sebagai berikut:
(1) Ketersediaan Tenaga Pendidik yang menguasai substansi = 𝑁𝑖𝑙𝑎𝑖 𝑘𝑒𝑡𝑒𝑟𝑠𝑒𝑑𝑖𝑎𝑎𝑛 𝑡𝑒𝑛𝑎𝑔𝑎 𝑝𝑒𝑛𝑑𝑖𝑑𝑖𝑘 𝑦𝑎𝑛𝑔 𝑚𝑒𝑛𝑔𝑢𝑎𝑠𝑎𝑖 𝑠𝑢𝑏𝑠𝑡𝑎𝑛𝑠𝑖
(2) Penguasaan substansi pengetahuan tenaga pendidik
(i) Total Nilai Penguasaan substansi = 𝑃𝑒𝑛𝑑. 𝑓𝑜𝑟𝑚𝑎𝑙 + 𝑆𝑒𝑟𝑡𝑖𝑓𝑖𝑘𝑎𝑡 𝑇𝑂𝑇 + 𝑆𝑒𝑟𝑡𝑖𝑓𝑖𝑘𝑎𝑡 𝑃𝑒𝑛𝑔𝑒𝑚𝑏𝑎𝑛𝑔𝑎𝑛 𝑃𝑟𝑜𝑓𝑒𝑠𝑖 + 𝐵ℎ𝑛. 𝑎𝑗𝑎𝑟/𝑡𝑎𝑦𝑎𝑛𝑔 14 (ii) Rata-rata nilai penguasaan subtansi 𝑇𝑜𝑡𝑎𝑙 𝑁𝑖𝑙𝑎𝑖 𝑃𝑒𝑛𝑔𝑢𝑎𝑠𝑎𝑎𝑛 𝑆𝑢𝑠𝑏𝑡𝑎𝑛𝑠𝑖 𝑇𝑒𝑛𝑎𝑔𝑎 𝑝𝑒𝑛𝑑𝑖𝑑𝑖𝑘 = 𝑗𝑢𝑚𝑙𝑎ℎ 𝑇𝑒𝑛𝑎𝑔𝑎 𝑝𝑒𝑛𝑑𝑖𝑑𝑖𝑘
(3) Pengalaman kerja tenaga pendidik yang mendukung penguasaan substansi
(i) Total Nilai Penguasaan substansi = 𝑃𝑒𝑛𝑔𝑎𝑙𝑎𝑚𝑎𝑛 𝑘𝑒𝑟𝑗𝑎 𝑠𝑒𝑡𝑎ℎ𝑢𝑛 ( > 2 𝑘𝑎𝑙𝑖 + 2 𝑘𝑎𝑙𝑖 + 1 𝑘𝑎𝑙𝑖 + 𝑡𝑖𝑑𝑎𝑘 𝑚𝑒𝑚𝑖𝑙𝑖𝑘𝑖) (ii) Rata-rata nilai penguasaan subtansi 𝑇𝑜𝑡𝑎𝑙 𝑁𝑖𝑙𝑎𝑖 𝑃𝑒𝑛𝑔𝑎𝑙𝑎𝑚𝑎𝑛 𝑘𝑒𝑟𝑗𝑎 𝑇𝑒𝑛𝑎𝑔𝑎 𝑝𝑒𝑛𝑑𝑖𝑑𝑖𝑘 = 𝑗𝑢𝑚𝑙𝑎ℎ 𝑇𝑒𝑛𝑎𝑔𝑎 𝑝𝑒𝑛𝑑𝑖𝑑𝑖𝑘 Nilai Komponen Tenaga Pendidik
(𝟏) + (𝟐) + (𝟑) = 𝒙 𝟒𝟎% 𝟏𝟐 4) Kriteria Penilaian No Uraian Nilai Keterangan
