INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1726, 'perban-1-2020', 36, 'lampiran', 'Lampiran hal. 26', NULL, 26, '1. Terdapat lebih dari 2 4 Terdapat tenaga pendidik lebih dari (dua) tenaga pendidik 2 orang dan telah mengikuti diklat yang telah mengikuti TOT Substansi diklat TOT Substansi
