INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1728, 'perban-1-2020', 38, 'lampiran', 'Lampiran hal. 28', NULL, 28, '3. Pengalaman kerja tenaga pendidik yang mendukung penguasaan substansi 1 Memiliki pengalaman 4 Melaksanakan pengajaran atau kerja yang konsultan/riset/praktisi/ mendukung narasumber/fasilitator/dosen/guru penguasaan /instruktur/assessor/pelatih atau substansi lebih dari 2 kegiatan lainnya yang mendukung kali dalam setahun penguasaan substansi lebih dari 2 kali dalam setahun.
2 Memiliki pengalaman 3 Melaksanakan pengajaran atau kerja yang konsultan/riset/praktisi/ mendukung narasumber/fasilitator/dosen/guru penguasaan /instruktur/assessor/pelatih atau substansi 2 kali kegiatan lainnya yang mendukung dalam setahun penguasaan substansi 2 kali dalam setahun.
3 Memiliki pengalaman 2 Melaksanakan pengajaran atau kerja yang konsultan/riset/praktisi/ mendukung narasumber/fasilitator/dosen/guru penguasaan /instruktur/assessor/pelatih atau substansi 1 kali kegiatan lainnya yang mendukung 17 dalam setahun penguasaan substansi 1 kali dalam setahun.
4 Tidak memiliki 0 Tidak pernah melaksanakan pengalaman kerja pengajaran atau konsultan/riset/ yang mendukung praktisi/narasumber/fasilitator/ penguasaan dosen/guru/instruktur/assessor/pe substansi latih atau kegiatan lainnya yang mendukung penguasaan substansi.
2.4. Komponen Pengelola Sistem Informasi Kediklatan
(1) Pengertian ASN dan/atau tenaga lain yang bertugas pada lembaga penyelenggara diklat atau lembaga yang berfungsi lainnya yang secara teknis memutakhirkan data diklat.');
