INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1729, 'perban-1-2020', 39, 'lampiran', 'Lampiran hal. 29', NULL, 29, '(2) Indikator Penilaian Kualitas Pengelola Sistem Informasi dalam pemanfaatan Sistem Informasi Kediklatan.
(3) Cara Penilaian Penilaian komponen pengelola sistem informasi kediklatan dilakukan berdasarkan pemanfaatan sistem informasi kediklatan oleh pengelola sistem dalam memberikan informasi kediklatan secara:
(a) Rutin, yaitu informasi selalu disampaikan/ diperbarui secara berkala;
(b) Lengkap, yaitu informasi memuat antara lain: (i) profil lembaga penyelenggara diklat seperti info umum, data SDM kediklatan, data tenaga pendidik, data fasilitas dan anggaran; (ii) informasi program diklat teknis PB); dan
(c) Tepat waktu, yaitu informasi yang disampaikan tepat pada waktunya atau tidak terlambat.
Hal ini dibuktikan dengan lampiran bukti fisik, berupa:
(a) Daftar Riwayat Hidup pengelola sistem informasi kediklatan dan melampirkan ijazah Pendidikan terakhir;
(b) SK atau Penugasan pengelola sistem informasi kediklatan;
18
(c) Sertifikat pelatihan atau kursus terkait sistem informasi; dan
(d) Bukti adanya link/screenshoot sistem informasi.
Bobot penilaian komponen pengelola sistem informasi kediklatan sebesar 20% dari Sub Unsur Tenaga Kediklatan yaitu 45%, dengan perhitungan sebagai berikut:
(a) Jumlah Total Nilai Pengelola Sistem Informasi Kediklatan: = DRH + SK/Penugasan + Sertifikat Pelatihan/Kursus/Sosialisasi + Link/screenshoot
(b) Rata-rata Nilai Pengelola Sistem Informasi Kediklatan:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1729, '(2) Indikator Penilaian Kualitas Pengelola Sistem Informasi dalam pemanfaatan Sistem Informasi Kediklatan.
