INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1733, 'perban-1-2020', 43, 'lampiran', 'Lampiran hal. 32', NULL, 32, '2 Renstra/Perencanaan 3 Internalisasi/sosialisasi (AD/ART) atau visi, misi, Renstra/Perencanaan (AD/ART) tujuan dan sasaran lembaga dilaksanakan sebagian besar diinternalisasikan kepada tenaga kediklatan (hanya unsur sebagian besar unsur internal) meliputi pengelola penyelenggara program diklat diklat, penyelenggara diklat, antara lain: Pengelola, tenaga pendidik, dan pengelola Penyelenggara, Tenaga sistem informasi kediklatan. pendidik dan Pengelola Sistem Informasi Kediklatan 21 3 Renstra/Perencanaan 2 Internalisasi/sosialisasi (AD/ART) atau visi, misi, Renstra/Perencanaan (AD/ART) tujuan dan sasaran lembaga dilaksanakan sebagian kecil diinternalisasikan kepada tenaga kediklatan (hanya unsur sebagian kecil unsur internal) meliputi pengelola penyelenggara program diklat diklat, penyelenggara diklat, dan antara lain: Pengelola, pengelola sistem informasi Penyelenggara, dan Pengelola kediklatan.
Sistem Informasi Kediklatan 4 Renstra/Perencanaan 1 Internalisasi/sosialisasi (AD/ART) atau visi, misi, Renstra/Perencanaan (AD/ART) tujuan dan sasaran lembaga tidak dilaksanakan kepada hanya dipahami oleh unsur unsur tenaga kediklatan, kecuali Pengelola hanya pengelola diklat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1733, '2 Renstra/Perencanaan 3 Internalisasi/sosialisasi (AD/ART) atau visi, misi, Renstra/Perencanaan (AD/ART) tujuan dan sasaran lembaga dilaksanakan sebagian besar diinternalisasikan kepada tenaga kediklatan (hanya unsur sebagian besar unsur internal) meliputi pengelola penyelenggara program diklat diklat, penyelenggara diklat, antara lain: Pengelola, tenaga pendidik, dan pengelola Penyelenggara, Tenaga sistem informasi kediklatan. pendidik dan Pengelola Sistem Informasi Kediklatan 21 3 Renstra/Perencanaan 2 Internalisasi/sosialisasi (AD/ART) atau visi, misi, Renstra/Perencanaan (AD/ART) tujuan dan sasaran lembaga dilaksanakan sebagian kecil diinternalisasikan kepada tenaga kediklatan (hanya unsur sebagian kecil unsur internal) meliputi pengelola penyelenggara program diklat diklat, penyelenggara diklat, dan antara lain: Pengelola, pengelola sistem informasi Penyelenggara, dan Pengelola kediklatan.
Sistem Informasi Kediklatan 4 Renstra/Perencanaan 1 Internalisasi/sosialisasi (AD/ART) atau visi, misi, Renstra/Perencanaan (AD/ART) tujuan dan sasaran lembaga tidak dilaksanakan kepada hanya dipahami oleh unsur unsur tenaga kediklatan, kecuali Pengelola hanya pengelola diklat.', 'Lampiran hal. 32', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1734, 'perban-1-2020', 44, 'lampiran', 'Lampiran hal. 33', NULL, 33, '5 Renstra/Perencanaan 0 Tidak ada internalisasi/ (AD/ART) atau visi, misi, sosialisasi Renstra/ Perencanaan tujuan dan sasaran lembaga (AD/ART) yang dilaksanakan. tidak diinternalisasikan kepada unsur penyelenggara program diklat 4) Sub Unsur Penjaminan Pembiayaan a) Pengertian Anggaran pembiayaan yang disediakan dalam penyelenggaraan diklat. b) Indikator Penilaian Ketersediaan anggaran dan pengelolaan pembiayaan dalam menyelenggarakan diklat teknis PB. c) Cara Penilaian Penilaian terhadap sub unsur penjaminan pembiayaan dengan bobot penilaian sebesar 15% dari unsur lembaga sebesar 50% yang dibuktikan dengan lampiran bukti fisik sebagai berikut:
(1) Daftar Isian Pelaksanaan Anggaran (DIPA) APBN/APBD
(2) Rincian Anggaran Biaya (RAB)
(3) Rencana Kerja Anggaran (RKA)
(4) Peraturan Daerah tentang PNBP atau Pola Kontribusi
(5) Memorandum of Understanding (MoU)
(6) Perjanjian Kerjasama (PKS) 22
(7) Donor/Sumbangan/Bantuan
(8) Corporate Social Responsibility (CSR) dilakukan berdasarkan:
(1) Lembaga penyelengara menyediakan anggaran dalam menyelenggarakan diklat teknis PB yang bersumber dari APBN/APBD/dana internal lembaga/organisasi/ perusahaan/pihak ketiga, seperti:
Donatur/Sumbangan/Bantuan/MoU/ Perjanjian Kerjama/CSR, dengan perhitungan: = 𝑁𝑖𝑙𝑎𝑖 𝑘𝑒𝑡𝑒𝑟𝑠𝑒𝑑𝑖𝑎𝑎𝑛 𝑎𝑛𝑔𝑔𝑎𝑟𝑎𝑛 𝑑𝑎𝑙𝑎𝑚 𝑚𝑒𝑛𝑦𝑒𝑙𝑒𝑛𝑔𝑔𝑎𝑟𝑎𝑘𝑎𝑛 𝑑𝑖𝑘𝑙𝑎𝑡 𝑡𝑒𝑘𝑛𝑖𝑠 𝑃𝐵');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1734, '5 Renstra/Perencanaan 0 Tidak ada internalisasi/ (AD/ART) atau visi, misi, sosialisasi Renstra/ Perencanaan tujuan dan sasaran lembaga (AD/ART) yang dilaksanakan. tidak diinternalisasikan kepada unsur penyelenggara program diklat 4) Sub Unsur Penjaminan Pembiayaan a) Pengertian Anggaran pembiayaan yang disediakan dalam penyelenggaraan diklat. b) Indikator Penilaian Ketersediaan anggaran dan pengelolaan pembiayaan dalam menyelenggarakan diklat teknis PB. c) Cara Penilaian Penilaian terhadap sub unsur penjaminan pembiayaan dengan bobot penilaian sebesar 15% dari unsur lembaga sebesar 50% yang dibuktikan dengan lampiran bukti fisik sebagai berikut:
