INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1735, 'perban-1-2020', 45, 'lampiran', 'Lampiran hal. 34', NULL, 34, '(2) Perbandingan kegiatan diklat teknis PB yang dibiayai anggaran sendiri dengan yang dibiayai melalui cost sharing atau ditanggung seluruhnya oleh instansi pengirim, dengan perhitungan: = 𝑁𝑖𝑙𝑎𝑖 𝑘𝑒𝑔𝑖𝑎𝑡𝑎𝑛 𝑦𝑎𝑛𝑔 𝑑𝑖𝑏𝑖𝑎𝑦𝑎𝑖 𝑠𝑒𝑛𝑑𝑖𝑟𝑖/𝑐𝑜𝑠𝑡 𝑠ℎ𝑎𝑟𝑖𝑛𝑔/𝑑𝑖𝑡𝑎𝑛𝑔𝑔𝑢𝑛𝑔 𝑖𝑛𝑠𝑡𝑎𝑛𝑠𝑖 𝑝𝑒𝑛𝑔𝑖𝑟𝑖𝑚
(3) Pengelolaan pembiayaan dalam penyelenggaraan diklat teknis PB mengacu standar biaya yang berlaku, dengan perhitungan: = 𝑁𝑖𝑙𝑎𝑖 𝑝𝑒𝑛𝑔𝑒𝑙𝑜𝑙𝑎𝑎𝑛 𝑝𝑒𝑚𝑏𝑖𝑎𝑦𝑎𝑎𝑛 𝑑𝑖𝑘𝑙𝑎𝑡 𝑡𝑒𝑘𝑛𝑖𝑠 𝑃𝐵 𝑠𝑒𝑠𝑢𝑎𝑖 𝑠𝑡𝑎𝑛𝑑𝑎𝑟 𝑎𝑡𝑎𝑢 𝑡𝑖𝑑𝑎𝑘 Penilaian Sub Unsur Renstra/Perencanaan (AD/ART)
(𝟏) + (𝟐) + (𝟑) = 𝒙 𝟏𝟎𝟎 𝒙 𝟏𝟓% 𝟏𝟐 d) Kriteria Penilaian No. Uraian Nilai Keterangan
1. Lembaga Penyelenggara menyediakan anggaran dalam menyelenggarakan diklat teknis PB yang bersumber dari APBN/APBD/dana internal lembaga/organisasi/ perusahaan/pihak ketiga, seperti: Donatur/Sumbangan/ Bantuan/MoU/Perjanjian Kerjama/CSR 1 YA 4 Tersedia anggaran penyelenggaraan diklat teknis PB 2 TIDAK 0 Tidak tersedia anggaran penyelenggaraan diklat teknis PB');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1735, '(2) Perbandingan kegiatan diklat teknis PB yang dibiayai anggaran sendiri dengan yang dibiayai melalui cost sharing atau ditanggung seluruhnya oleh instansi pengirim, dengan perhitungan: = 𝑁𝑖𝑙𝑎𝑖 𝑘𝑒𝑔𝑖𝑎𝑡𝑎𝑛 𝑦𝑎𝑛𝑔 𝑑𝑖𝑏𝑖𝑎𝑦𝑎𝑖 𝑠𝑒𝑛𝑑𝑖𝑟𝑖/𝑐𝑜𝑠𝑡 𝑠ℎ𝑎𝑟𝑖𝑛𝑔/𝑑𝑖𝑡𝑎𝑛𝑔𝑔𝑢𝑛𝑔 𝑖𝑛𝑠𝑡𝑎𝑛𝑠𝑖 𝑝𝑒𝑛𝑔𝑖𝑟𝑖𝑚
(3) Pengelolaan pembiayaan dalam penyelenggaraan diklat teknis PB mengacu standar biaya yang berlaku, dengan perhitungan: = 𝑁𝑖𝑙𝑎𝑖 𝑝𝑒𝑛𝑔𝑒𝑙𝑜𝑙𝑎𝑎𝑛 𝑝𝑒𝑚𝑏𝑖𝑎𝑦𝑎𝑎𝑛 𝑑𝑖𝑘𝑙𝑎𝑡 𝑡𝑒𝑘𝑛𝑖𝑠 𝑃𝐵 𝑠𝑒𝑠𝑢𝑎𝑖 𝑠𝑡𝑎𝑛𝑑𝑎𝑟 𝑎𝑡𝑎𝑢 𝑡𝑖𝑑𝑎𝑘 Penilaian Sub Unsur Renstra/Perencanaan (AD/ART)
