INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1737, 'perban-1-2020', 47, 'lampiran', 'Lampiran hal. 35', NULL, 35, '(1) Lembaga penyelenggara memiliki sarana dan prasarana yang diperlukan untuk menunjang penyelenggaraan diklat teknis PB sesuai dengan standar/kurikulum diklat teknis PB yang diselenggarakan, dengan perhitungan: = 𝑁𝑖𝑙𝑎𝑖 𝑘𝑒𝑡𝑒𝑟𝑠𝑒𝑑𝑖𝑎𝑎𝑛 𝑠𝑎𝑟𝑎𝑛𝑎 𝑑𝑎𝑛 𝑝𝑟𝑎𝑠𝑎𝑟𝑎𝑛𝑎 𝑝𝑒𝑛𝑦𝑒𝑙𝑒𝑛𝑔𝑔𝑎𝑟𝑎 𝑑𝑖𝑘𝑙𝑎𝑡 24
(2) Kelayakan sarana dan prasarana penunjang penyelenggaraan diklat teknis PB, dengan perhitungan: = 𝑁𝑖𝑙𝑎𝑖 𝑘𝑒𝑙𝑎𝑦𝑎𝑘𝑎𝑛 𝑠𝑎𝑟𝑎𝑛𝑎 𝑑𝑎𝑛 𝑝𝑟𝑎𝑠𝑎𝑟𝑎𝑛𝑎 𝑝𝑒𝑛𝑦𝑒𝑙𝑒𝑛𝑔𝑔𝑎𝑟𝑎𝑎𝑛 𝑑𝑖𝑘𝑙𝑎𝑡 Penilaian Sub Unsur Fasilitas Diklat
(𝟏) + (𝟐) = 𝒙 𝟏𝟎𝟎 𝒙 𝟏𝟓% 𝟖 Hal ini dinilai dari lampiran bukti fisik sebagai berikut:
(1) Daftar inventaris fasilitas diklat;
(2) Foto sarana dan prasarana; dan
(3) Dokumen kemitraan, antara lain seperti kerjasama peminjaman peralatan, atau perjanjian sewa-menyewa peralatan, atau bukti/surat permohonan peminjaman peralatan ke OPD terkait/private sector. d) Kriteria Penilaian No Uraian Nilai Keterangan
1. Lembaga penyelenggara memiliki sarana dan prasarana yang diperlukan untuk menunjang penyelenggaraan diklat teknis PB sesuai dengan standar/kurikulum diklat teknis PB yang diselenggarakan 1 Seluruh sarana dan prasarana 4 Lembaga Penyelenggara penyelenggaraan diklat teknis Diklat memiliki keseluruhan PB dimiliki oleh Lembaga sarana dan prasarana Penyelenggara Diklat sesuai penyelenggaraan diklat, dengan standar/kurikulum sesuai dengan standar/ diklat teknis PB yang kurikulum diklat teknis PB diselenggarakan. yang diselenggarakan.');
