INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1739, 'perban-1-2020', 49, 'lampiran', 'Lampiran hal. 37', NULL, 37, '5 < 20% sarana dan prasarana 0 Lembaga Penyelenggara penyelenggaraan diklat teknis Diklat memiliki sarana dan PB dimiliki oleh Lembaga prasarana penyelenggaraan Penyelenggara Diklat sesuai diklat < 20% sesuai dengan dengan standar/kurikulum standar/ kurikulum diklat diklat teknis PB yang teknis PB yang diselenggarakan, dan sebagian diselenggarakan, dan lagi didapat dari meminjam/ sebagian lagi didapat dari menyewa. meminjam/menyewa.
2. Kelayakan sarana dan prasarana penunjang penyelenggaraan diklat teknis PB 1 Layak 4 Sarana dan prasarana yang terdapat lembaga penyelenggara, layak digunakan untuk pelaksanaan diklat teknis PB 2 Tidak layak 2 Sarana dan prasarana yang terdapat lembaga penyelenggara, tidak layak digunakan untuk pelaksanaan diklat teknis PB 6) Sub Unsur Penjaminan Mutu Diklat a) Pengertian Tim atau Komite yang bertanggung jawab dalam menjamin 26 kualitas penyelenggaraan diklat. b) Indikator Penilaian Kejelasan penerapan penjamin mutu di lembaga diklat. c) Cara Penilaian Penilaian terhadap sub unsur penjaminan mutu diklat dengan bobot penilaian sebesar 10% dari unsur lembaga sebesar 50%, dilakukan berdasarkan:
(1) keberadaan komite penjamin mutu independen; dan
(2) implementasi standar mutu berbagai pedoman dalam penyelenggaraan diklat, dengan penghitungan:
𝑵𝒊𝒍𝒂𝒊 𝑷𝒆𝒏𝒋𝒂𝒎𝒊𝒏𝒂𝒏 𝑴𝒖𝒕𝒖 = 𝒙 𝟏𝟎𝟎 𝒙 𝟏𝟎% 𝟒 Hal ini dinilai dari lampiran bukti fisik sebagai berikut:
(1) Daftar Riwayat Hidup Tim/Komite Penjamin Mutu untuk Diklat Teknis PB');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1739, '5 < 20% sarana dan prasarana 0 Lembaga Penyelenggara penyelenggaraan diklat teknis Diklat memiliki sarana dan PB dimiliki oleh Lembaga prasarana penyelenggaraan Penyelenggara Diklat sesuai diklat < 20% sesuai dengan dengan standar/kurikulum standar/ kurikulum diklat diklat teknis PB yang teknis PB yang diselenggarakan, dan sebagian diselenggarakan, dan lagi didapat dari meminjam/ sebagian lagi didapat dari menyewa. meminjam/menyewa.
2. Kelayakan sarana dan prasarana penunjang penyelenggaraan diklat teknis PB 1 Layak 4 Sarana dan prasarana yang terdapat lembaga penyelenggara, layak digunakan untuk pelaksanaan diklat teknis PB 2 Tidak layak 2 Sarana dan prasarana yang terdapat lembaga penyelenggara, tidak layak digunakan untuk pelaksanaan diklat teknis PB 6) Sub Unsur Penjaminan Mutu Diklat a) Pengertian Tim atau Komite yang bertanggung jawab dalam menjamin 26 kualitas penyelenggaraan diklat. b) Indikator Penilaian Kejelasan penerapan penjamin mutu di lembaga diklat. c) Cara Penilaian Penilaian terhadap sub unsur penjaminan mutu diklat dengan bobot penilaian sebesar 10% dari unsur lembaga sebesar 50%, dilakukan berdasarkan:
(1) keberadaan komite penjamin mutu independen; dan
(2) implementasi standar mutu berbagai pedoman dalam penyelenggaraan diklat, dengan penghitungan:
𝑵𝒊𝒍𝒂𝒊 𝑷𝒆𝒏𝒋𝒂𝒎𝒊𝒏𝒂𝒏 𝑴𝒖𝒕𝒖 = 𝒙 𝟏𝟎𝟎 𝒙 𝟏𝟎% 𝟒 Hal ini dinilai dari lampiran bukti fisik sebagai berikut:
(1) Daftar Riwayat Hidup Tim/Komite Penjamin Mutu untuk Diklat Teknis PB', 'Lampiran hal. 37', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1740, 'perban-1-2020', 50, 'lampiran', 'Lampiran hal. 38', NULL, 38, '(2) SK Tim/Komite Penjamin Mutu untuk Diklat Teknis PB (terdiri atas minimal 3 orang maksimal 5 orang (1 orang dari unsur independen));
(3) SOP/Panduan/Instrumen, Berita Acara/Laporan Komite Penjamin Mutu terkait implementasi diklat teknis PB. d) Kriteria Penilaian No. Uraian Nilai Keterangan 1 Ada standar mutu yang 4 Penjaminan mutu di lembaga menjadi acuan lembaga dijamin oleh Tim Penjamin penyelenggara diklat yang Mutu (ada unsur independen), diimplementasikan dalam dan diterapkan dalam berbagai bentuk berbagai pedoman pedoman seperti dan dijamin oleh tim SOP/Panduan/Instrumen, penjamin mutu yang Berita Acara/Laporan independen Tim/Komite Penjamin Mutu.
2 Ada standar mutu yang 3 Penjaminan mutu di lembaga menjadi acuan lembaga dijamin oleh Tim Penjamin penyelenggara diklat yang Mutu (internal), dan diterapkan diimplementasikan dalam dalam berbagai pedoman bentuk berbagai pedoman seperti namun penjaminan SOP/Panduan/Instrumen, 27 dilakukan oleh tim penjamin Berita Acara/Laporan mutu internal Tim/Komite Penjamin Mutu.
3 Ada standar mutu yang 2 Penjaminan mutu di lembaga menjadi acuan lembaga dijamin oleh Tim Penjamin penyelenggara diklat tetapi Mutu (ada unsur independen), kurang diimplementasikan namun kurang diterapkan dalam bentuk berbagai dalam berbagai pedoman pedoman meskipun dijamin seperti oleh tim penjamin mutu SOP/Panduan/Instrumen, yang independen Berita Acara/Laporan Tim/Komite Penjamin Mutu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1740, '(2) SK Tim/Komite Penjamin Mutu untuk Diklat Teknis PB (terdiri atas minimal 3 orang maksimal 5 orang (1 orang dari unsur independen));
(3) SOP/Panduan/Instrumen, Berita Acara/Laporan Komite Penjamin Mutu terkait implementasi diklat teknis PB. d) Kriteria Penilaian No. Uraian Nilai Keterangan 1 Ada standar mutu yang 4 Penjaminan mutu di lembaga menjadi acuan lembaga dijamin oleh Tim Penjamin penyelenggara diklat yang Mutu (ada unsur independen), diimplementasikan dalam dan diterapkan dalam berbagai bentuk berbagai pedoman pedoman seperti dan dijamin oleh tim SOP/Panduan/Instrumen, penjamin mutu yang Berita Acara/Laporan independen Tim/Komite Penjamin Mutu.
2 Ada standar mutu yang 3 Penjaminan mutu di lembaga menjadi acuan lembaga dijamin oleh Tim Penjamin penyelenggara diklat yang Mutu (internal), dan diterapkan diimplementasikan dalam dalam berbagai pedoman bentuk berbagai pedoman seperti namun penjaminan SOP/Panduan/Instrumen, 27 dilakukan oleh tim penjamin Berita Acara/Laporan mutu internal Tim/Komite Penjamin Mutu.
3 Ada standar mutu yang 2 Penjaminan mutu di lembaga menjadi acuan lembaga dijamin oleh Tim Penjamin penyelenggara diklat tetapi Mutu (ada unsur independen), kurang diimplementasikan namun kurang diterapkan dalam bentuk berbagai dalam berbagai pedoman pedoman meskipun dijamin seperti oleh tim penjamin mutu SOP/Panduan/Instrumen, yang independen Berita Acara/Laporan Tim/Komite Penjamin Mutu.', 'Lampiran hal. 38', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1741, 'perban-1-2020', 51, 'lampiran', 'Lampiran hal. 39', NULL, 39, '4 Ada standar mutu yang 1 Penjaminan mutu di lembaga menjadi acuan lembaga dijamin oleh Tim Penjamin penyelenggara diklat tetapi Mutu (internal), namun kurang kurang diimplementasikan diterapkan dalam berbagai dalam bentuk berbagai pedoman seperti pedoman meskipun dijamin SOP/Panduan/Instrumen, oleh tim penjamin mutu Berita Acara/Laporan internal Tim/Komite Penjamin Mutu.
5 Tidak ada standar mutu 0 Penjaminan mutu tidak atau tidak dilakukan dilakukan atau standar mutu penjaminan mutu. tidak ada Penilaian Unsur Lembaga = 𝑵𝒊𝒍𝒂𝒊 𝑺𝒖𝒃 𝑼𝒏𝒔𝒖𝒓 (𝑲𝑳 + 𝑻𝑫 + 𝑹𝑺 + 𝑱𝑩 + 𝑭𝑫 + 𝑱𝑴) 𝒙 𝟓𝟎%
b. UNSUR PROGRAM DAN PENGELOLAAN PROGRAM
1. Sub Unsur Kurikulum a) Pengertian Seperangkat rencana dan pengaturan mengenai tujuan, isi, pengalaman belajar dan penilaian, serta cara yang digunakan sebagai pedoman penyelenggaraan kegiatan pembelajaran untuk mencapai tujuan Pendidikan tertentu. b) Indikator Penilaian Kejelasan kurikulum program yang dijadikan acuan dalam penyelenggaraan diklat teknis PB. c) Cara Penilaian Penilaian terhadap sub unsur kurikulum dilakukan berdasarkan kesesuaian kurikulum diklat yang disusun Instansi Pembina dijadikan acuan dalam penyelenggaraan 28 diklat beserta perangkat pelaksanaannya sesuai diklat teknis PB yang diajukan, meliputi: mata diklat, metode, durasi waktu dan target kompetensi, dengan bobot penilaian sebesar 30% dari Unsur Program dan Pengelolaan sebesar 50%, dibuktikan dengan lampiran bukti fisik berupa:
1) Kurikulum Diklat Teknis PB yang diajukan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1741, '4 Ada standar mutu yang 1 Penjaminan mutu di lembaga menjadi acuan lembaga dijamin oleh Tim Penjamin penyelenggara diklat tetapi Mutu (internal), namun kurang kurang diimplementasikan diterapkan dalam berbagai dalam bentuk berbagai pedoman seperti pedoman meskipun dijamin SOP/Panduan/Instrumen, oleh tim penjamin mutu Berita Acara/Laporan internal Tim/Komite Penjamin Mutu.
5 Tidak ada standar mutu 0 Penjaminan mutu tidak atau tidak dilakukan dilakukan atau standar mutu penjaminan mutu. tidak ada Penilaian Unsur Lembaga = 𝑵𝒊𝒍𝒂𝒊 𝑺𝒖𝒃 𝑼𝒏𝒔𝒖𝒓 (𝑲𝑳 + 𝑻𝑫 + 𝑹𝑺 + 𝑱𝑩 + 𝑭𝑫 + 𝑱𝑴) 𝒙 𝟓𝟎%
b. UNSUR PROGRAM DAN PENGELOLAAN PROGRAM
1. Sub Unsur Kurikulum a) Pengertian Seperangkat rencana dan pengaturan mengenai tujuan, isi, pengalaman belajar dan penilaian, serta cara yang digunakan sebagai pedoman penyelenggaraan kegiatan pembelajaran untuk mencapai tujuan Pendidikan tertentu. b) Indikator Penilaian Kejelasan kurikulum program yang dijadikan acuan dalam penyelenggaraan diklat teknis PB. c) Cara Penilaian Penilaian terhadap sub unsur kurikulum dilakukan berdasarkan kesesuaian kurikulum diklat yang disusun Instansi Pembina dijadikan acuan dalam penyelenggaraan 28 diklat beserta perangkat pelaksanaannya sesuai diklat teknis PB yang diajukan, meliputi: mata diklat, metode, durasi waktu dan target kompetensi, dengan bobot penilaian sebesar 30% dari Unsur Program dan Pengelolaan sebesar 50%, dibuktikan dengan lampiran bukti fisik berupa:
1) Kurikulum Diklat Teknis PB yang diajukan;', 'Lampiran hal. 39', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1742, 'perban-1-2020', 52, 'lampiran', 'Lampiran hal. 40', NULL, 40, '2) master jadwal/sequence;
3) laporan penyelenggaraan; dan 4) contoh bahan ajar, dengan perhitungan sebagaimana berikut:
𝑵𝒊𝒍𝒂𝒊 𝒌𝒆𝒔𝒆𝒔𝒖𝒂𝒊𝒂𝒏 𝒌𝒖𝒓𝒊𝒌𝒖𝒍𝒖𝒎 = 𝒙 𝟏𝟎𝟎 𝒙 𝟑𝟎% 𝟒 d) Kriteria Penilaian:
No. Uraian Nilai Keterangan 1 Menerapkan 4 Seluruh perangkat pelaksanaan diklat seluruh ketentuan (mata diklat, metode, durasi waktu dan kurikulum diklat target kompetensi) sesuai dengan teknis PB yang kurikulum Diklat Teknis PB yang disusun diajukan. Instansi Pembina untuk dijadikan acuan dalam penyelenggaraan diklat 2 Menerapkan 2 Sebagian perangkat pelaksanaan diklat sebagian (mata diklat, metode, durasi waktu dan ketentuan target kompetensi) sesuai dengan kurikulum diklat kurikulum Diklat Teknis PB yang disusun teknis PB yang Instansi Pembina untuk dijadikan acuan diajukan dalam penyelenggaraan diklat 3 Tidak menerapkan 1 Keseluruhan perangkat pelaksanaan ketentuan diklat (mata diklat, metode, durasi waktu kurikulum diklat dan target kompetensi) tidak sesuai teknis PB yang dengan kurikulum Diklat Teknis PB yang diajukan disusun Instansi Pembina untuk dijadikan acuan dalam penyelenggaraan Diklat');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1742, '2) master jadwal/sequence;
3) laporan penyelenggaraan; dan 4) contoh bahan ajar, dengan perhitungan sebagaimana berikut:
𝑵𝒊𝒍𝒂𝒊 𝒌𝒆𝒔𝒆𝒔𝒖𝒂𝒊𝒂𝒏 𝒌𝒖𝒓𝒊𝒌𝒖𝒍𝒖𝒎 = 𝒙 𝟏𝟎𝟎 𝒙 𝟑𝟎% 𝟒 d) Kriteria Penilaian:
No. Uraian Nilai Keterangan 1 Menerapkan 4 Seluruh perangkat pelaksanaan diklat seluruh ketentuan (mata diklat, metode, durasi waktu dan kurikulum diklat target kompetensi) sesuai dengan teknis PB yang kurikulum Diklat Teknis PB yang disusun diajukan. Instansi Pembina untuk dijadikan acuan dalam penyelenggaraan diklat 2 Menerapkan 2 Sebagian perangkat pelaksanaan diklat sebagian (mata diklat, metode, durasi waktu dan ketentuan target kompetensi) sesuai dengan kurikulum diklat kurikulum Diklat Teknis PB yang disusun teknis PB yang Instansi Pembina untuk dijadikan acuan diajukan dalam penyelenggaraan diklat 3 Tidak menerapkan 1 Keseluruhan perangkat pelaksanaan ketentuan diklat (mata diklat, metode, durasi waktu kurikulum diklat dan target kompetensi) tidak sesuai teknis PB yang dengan kurikulum Diklat Teknis PB yang diajukan disusun Instansi Pembina untuk dijadikan acuan dalam penyelenggaraan Diklat', 'Lampiran hal. 40', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1743, 'perban-1-2020', 53, 'lampiran', 'Lampiran hal. 40', NULL, 40, '2. Sub Unsur Pengelolaan Program a) Pengertian Penentuan serangkaian tindakan untuk mencapai suatu hasil yang diinginkan, mulai dari tahap perencanaan, 29 pelaksanaan hingga evaluasi. b) Indikator Penilaian Perencanaan penyelenggaraan diklat (RSD), Pelaksanaan proses pembelajaran dan mutu pembelajaran (SD), Penerapan monev dalam penyelenggaraan diklat (MESD), dan Hasil (output) penyelenggaraan diklat (HSD). c) Cara Penilaian Penilaian terhadap sub unsur Pengelolaan Program dilakukan berdasarkan nilai dari Komponen Perencanaan Penyelenggaraan Diklat, Penyelenggaraan Diklat, Penerapan monev dalam penyelenggaraan diklat dan Hasil (output) penyelenggaraan diklat, dengan bobot penilaian sebesar 70% dari Unsur Program dan Pengelolaan yaitu 50%, dengan perhitungan sebagaimana berikut: = 𝑵𝒊𝒍𝒂𝒊 𝑲𝒐𝒎𝒑𝒐𝒏𝒆𝒏 (𝑹𝑺𝑫 + 𝑺𝑫 + 𝑴𝑬𝑺𝑫 + 𝑯𝑺𝑫 ) 𝒙 𝟏𝟎𝟎 𝒙 𝟕𝟎 2.1. Komponen Perencanaan Penyelenggaraan Diklat PB 1) Pengertian Kematangan perencanaan penyelenggaraan diklat teknis PB yang meliputi aspek:
(a) muatan rencana penyelenggaraan (jadwal penyelenggaraan, lokasi, tenaga pendidik, peserta diklat, sarana dan prasarana, kerjasama penyelenggaraan, dll);
(b) pihak yang terlibat; dan
(c) diseminasi informasi tentang rencana penyelenggaraan kepada stakeholder/pemangku kepentingan.
2) Indikator Penilaian Perencanaan penyelenggaraan diklat teknis PB.
3) Cara Penilaian Penilaian komponen perencanaan penyelenggaraan diklat PB dilakukan berdasarkan:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1743, '2. Sub Unsur Pengelolaan Program a) Pengertian Penentuan serangkaian tindakan untuk mencapai suatu hasil yang diinginkan, mulai dari tahap perencanaan, 29 pelaksanaan hingga evaluasi. b) Indikator Penilaian Perencanaan penyelenggaraan diklat (RSD), Pelaksanaan proses pembelajaran dan mutu pembelajaran (SD), Penerapan monev dalam penyelenggaraan diklat (MESD), dan Hasil (output) penyelenggaraan diklat (HSD). c) Cara Penilaian Penilaian terhadap sub unsur Pengelolaan Program dilakukan berdasarkan nilai dari Komponen Perencanaan Penyelenggaraan Diklat, Penyelenggaraan Diklat, Penerapan monev dalam penyelenggaraan diklat dan Hasil (output) penyelenggaraan diklat, dengan bobot penilaian sebesar 70% dari Unsur Program dan Pengelolaan yaitu 50%, dengan perhitungan sebagaimana berikut: = 𝑵𝒊𝒍𝒂𝒊 𝑲𝒐𝒎𝒑𝒐𝒏𝒆𝒏 (𝑹𝑺𝑫 + 𝑺𝑫 + 𝑴𝑬𝑺𝑫 + 𝑯𝑺𝑫 ) 𝒙 𝟏𝟎𝟎 𝒙 𝟕𝟎 2.1. Komponen Perencanaan Penyelenggaraan Diklat PB 1) Pengertian Kematangan perencanaan penyelenggaraan diklat teknis PB yang meliputi aspek:
(a) muatan rencana penyelenggaraan (jadwal penyelenggaraan, lokasi, tenaga pendidik, peserta diklat, sarana dan prasarana, kerjasama penyelenggaraan, dll);
(b) pihak yang terlibat; dan
(c) diseminasi informasi tentang rencana penyelenggaraan kepada stakeholder/pemangku kepentingan.
2) Indikator Penilaian Perencanaan penyelenggaraan diklat teknis PB.
3) Cara Penilaian Penilaian komponen perencanaan penyelenggaraan diklat PB dilakukan berdasarkan:', 'Lampiran hal. 40', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1744, 'perban-1-2020', 54, 'lampiran', 'Lampiran hal. 41', NULL, 41, '(a) muatan rencana penyelenggaraan (jadwal penyelenggaraan, lokasi, tenaga pendidik, peserta 30 diklat, sarana dan prasarana, kerjasama penyelenggaraan, dll);
(b) pihak yang terlibat; dan
(c) diseminasi informasi tentang rencana penyelenggaraan kepada stakeholder/pemangku kepentingan, dengan bobot penilaian sebesar 20% dari Sub Unsur Pengelolaan Program, yaitu 70%. Hal ini dibuktikan dengan Lampiran Bukti Fisik, berupa:
(a) Surat undangan rapat persiapan
(b) Daftar hadir rapat persiapan
(c) Notulensi rapat persiapan penyelenggaraan diklat
(d) Kerjasama penyelenggaraan
(e) Kalender diklat, dengan perhitungan sebagai berikut:
𝑵𝒊𝒍𝒂𝒊 𝑷𝒆𝒏𝒈𝒆𝒍𝒐𝒍𝒂𝒂𝒏 𝑷𝒓𝒐𝒈𝒓𝒂𝒎 = 𝒙 𝟐𝟎% 𝟒 4) Kriteria Penilaian No. Uraian Nilai Keterangan 1 Seluruh 4 Muatan rencana penyelenggaraan (jadwal aspek penyelenggaraan, lokasi, tenaga pendidik, terencana peserta diklat, sarana dan prasarana, dengan baik kerjasama penyelenggaraan, dll), pihak yang terlibat, dan diseminasi informasi tentang rencana penyelenggaraan kepada stakeholder/pemangku kepentingan, terencana dengan baik.');
