INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1754, 'perban-1-2020', 64, 'lampiran', 'Lampiran hal. 50', NULL, 50, '2. Diseminasi produk pembelajaran diklat dilakukan kepada user (instansi pengirim) atau stakeholders lain yang lebih luas 1 Diseminasi 4 Diseminasi dilakukan melalui dilakukan secara display perpustakaan, upload non-klasikal dan dalam website, alumni gathering klasikal (non-klasikal) dan pemberitahuan tertulis kepada instansi (klasikal) 2 Diseminasi 3 Diseminasi dilakukan melalui dilakukan secara display perpustakaan, upload non-klasikal dalam website, alumni gathering (non-klasikal) 3 Diseminasi 2 Diseminasi dilakukan melalui dilakukan dengan pameran, dan pemberitahuan cara klasikal tertulis kepada instansi (klasikal).
4 Diseminasi tidak 0 Tidak dilakukan diseminasi. dilakukan PENILAIAN UNSUR PROGRAM DAN PENGELOLAAN PROGRAM = 𝑵𝒊𝒍𝒂𝒊 𝑺𝒖𝒃 𝑼𝒏𝒔𝒖𝒓 (𝑲𝑹 + 𝑲𝑷𝒓) 𝒙 𝟓𝟎% NILAI AKREDITASI: = 𝑵𝒊𝒍𝒂𝒊 𝑼𝒏𝒔𝒖𝒓 𝑳𝒆𝒎𝒃𝒂𝒈𝒂 + 𝑵𝒊𝒍𝒂𝒊 𝑼𝒏𝒔𝒖𝒓 𝑷𝒓𝒐𝒈𝒓𝒂𝒎 𝒅𝒂𝒏 𝑷𝒆𝒏𝒈𝒆𝒍𝒐𝒍𝒂𝒂𝒏 𝑷𝒓𝒐𝒈𝒓𝒂𝒎 Keterangan:
No. Kategorisasi Akreditasi Nilai
1. Terakreditasi A 91,00 s.d. 100
2. Terakreditasi B 81,00 s.d. 90,99
3. Terakreditasi C 71,00 s.d. 80,99
4. Tidak Terakreditasi Dibawah 71 atau salah satu unsur dibawah 35,50 39
3. PENILAIAN AKREDITASI Penilaian akreditasi lembaga penyelenggara Diklat Teknis PB dilakukan melalui pemberian penilaian terhadap Unsur, Sub Unsur dan Komponen Akreditasi, dengan nilai dan besaran sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1754, '2. Diseminasi produk pembelajaran diklat dilakukan kepada user (instansi pengirim) atau stakeholders lain yang lebih luas 1 Diseminasi 4 Diseminasi dilakukan melalui dilakukan secara display perpustakaan, upload non-klasikal dan dalam website, alumni gathering klasikal (non-klasikal) dan pemberitahuan tertulis kepada instansi (klasikal) 2 Diseminasi 3 Diseminasi dilakukan melalui dilakukan secara display perpustakaan, upload non-klasikal dalam website, alumni gathering (non-klasikal) 3 Diseminasi 2 Diseminasi dilakukan melalui dilakukan dengan pameran, dan pemberitahuan cara klasikal tertulis kepada instansi (klasikal).
4 Diseminasi tidak 0 Tidak dilakukan diseminasi. dilakukan PENILAIAN UNSUR PROGRAM DAN PENGELOLAAN PROGRAM = 𝑵𝒊𝒍𝒂𝒊 𝑺𝒖𝒃 𝑼𝒏𝒔𝒖𝒓 (𝑲𝑹 + 𝑲𝑷𝒓) 𝒙 𝟓𝟎% NILAI AKREDITASI: = 𝑵𝒊𝒍𝒂𝒊 𝑼𝒏𝒔𝒖𝒓 𝑳𝒆𝒎𝒃𝒂𝒈𝒂 + 𝑵𝒊𝒍𝒂𝒊 𝑼𝒏𝒔𝒖𝒓 𝑷𝒓𝒐𝒈𝒓𝒂𝒎 𝒅𝒂𝒏 𝑷𝒆𝒏𝒈𝒆𝒍𝒐𝒍𝒂𝒂𝒏 𝑷𝒓𝒐𝒈𝒓𝒂𝒎 Keterangan:
No. Kategorisasi Akreditasi Nilai
1. Terakreditasi A 91,00 s.d. 100
2. Terakreditasi B 81,00 s.d. 90,99
3. Terakreditasi C 71,00 s.d. 80,99
4. Tidak Terakreditasi Dibawah 71 atau salah satu unsur dibawah 35,50 39
3. PENILAIAN AKREDITASI Penilaian akreditasi lembaga penyelenggara Diklat Teknis PB dilakukan melalui pemberian penilaian terhadap Unsur, Sub Unsur dan Komponen Akreditasi, dengan nilai dan besaran sebagai berikut:', 'Lampiran hal. 50', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1755, 'perban-1-2020', 65, 'lampiran', 'Lampiran hal. 51', NULL, 51, 'a. Lembaga penyelenggara diklat dinyatakan layak, dan akan ditetapkan secara tertulis dalam Surat Keputusan dan diberikan Sertifikat Akreditasi oleh Instansi Pembina, apabila nilai total unsur akreditasinya adalah 71,00 atau lebih, dengan nilai minimal per masing-masing unsur akreditasi adalah 35,50.
b. Lembaga penyelenggara diklat dinyatakan tidak layak, apabila:
1) nilai akreditasinya di bawah nilai 71,00 2) nilai salah satu unsur dari akreditasi tidak mencapai 35,50, untuk selanjutnya akan diberitahukan secara tertulis kepada lembaga penyelenggara yang bersangkutan.
c. Penilaian akreditasi terhadap Lembaga penyelenggara diklat terdiri atas 3 kategori, yaitu:
1) Terakreditasi A, memiliki rentang nilai akreditasi 91,00 s.d. 100, dengan masa berlaku 5 (lima) tahun;
2) Terakreditasi B, memiliki rentang nilai 81,00 s.d. 90,99 dengan rentang masa berlaku 3 (tiga) tahun; dan 3) Terakreditasi C, memiliki rentang nilai 71,00 s.d. 80,99 dengan masa berlaku 2 (dua) tahun.
C. TIM AKREDITASI
1. Akreditasi Diklat Teknis PB terhadap Penyelenggara Diklat dilaksanakan oleh Tim Akreditasi yang ditetapkan dengan Surat Keputusan Sekretaris Utama BNPB.
2. Tim akreditasi dipimpin oleh seorang ketua tim yang ditetapkan dengan Surat Keputusan Sekretaris Utama.
3. Susunan Tim Akreditasi terdiri dari:
a. Sekretariat Akreditasi;
b. Assessor; dan
c. Tim Penilai.
4. Tim Akreditasi Diklat Teknis PB terdiri atas:
a. Sekretariat Akreditasi;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1755, 'a. Lembaga penyelenggara diklat dinyatakan layak, dan akan ditetapkan secara tertulis dalam Surat Keputusan dan diberikan Sertifikat Akreditasi oleh Instansi Pembina, apabila nilai total unsur akreditasinya adalah 71,00 atau lebih, dengan nilai minimal per masing-masing unsur akreditasi adalah 35,50.
b. Lembaga penyelenggara diklat dinyatakan tidak layak, apabila:
1) nilai akreditasinya di bawah nilai 71,00 2) nilai salah satu unsur dari akreditasi tidak mencapai 35,50, untuk selanjutnya akan diberitahukan secara tertulis kepada lembaga penyelenggara yang bersangkutan.
c. Penilaian akreditasi terhadap Lembaga penyelenggara diklat terdiri atas 3 kategori, yaitu:
1) Terakreditasi A, memiliki rentang nilai akreditasi 91,00 s.d. 100, dengan masa berlaku 5 (lima) tahun;
2) Terakreditasi B, memiliki rentang nilai 81,00 s.d. 90,99 dengan rentang masa berlaku 3 (tiga) tahun; dan 3) Terakreditasi C, memiliki rentang nilai 71,00 s.d. 80,99 dengan masa berlaku 2 (dua) tahun.
C. TIM AKREDITASI
1. Akreditasi Diklat Teknis PB terhadap Penyelenggara Diklat dilaksanakan oleh Tim Akreditasi yang ditetapkan dengan Surat Keputusan Sekretaris Utama BNPB.
2. Tim akreditasi dipimpin oleh seorang ketua tim yang ditetapkan dengan Surat Keputusan Sekretaris Utama.
3. Susunan Tim Akreditasi terdiri dari:
a. Sekretariat Akreditasi;
b. Assessor; dan
c. Tim Penilai.
4. Tim Akreditasi Diklat Teknis PB terdiri atas:
a. Sekretariat Akreditasi;', 'Lampiran hal. 51', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1756, 'perban-1-2020', 66, 'lampiran', 'Lampiran hal. 51', NULL, 51, '40 1) Sekretariat Akreditasi berjumlah minimal 2 (dua) orang, 2) Sekretariat Akreditasi bertanggung jawab dalam bidang akreditasi Penyelenggara Diklat; dan 3) Sekretariat Akreditasi mempunyai tugas memberikan bantuan administratif dalam menunjang kelancaran proses pelaksanaan akreditasi; memeriksa kelengkapan jenis dokumen akreditasi; dan menyediakan data, informasi, serta laporan untuk tindak lanjut akreditasi.
b. Assessor; dan 1) Assessor adalah ASN dan/atau Praktisi yang memiliki kompetensi untuk menilai kapasitas organisasi Penyelenggara Diklat, dan program Diklat dan pengelolaan program Diklat.
2) Kompetensi Assessor: a) Mempunyai pengalaman kerja di bidang penanggulangan bencana minimal 3 (tiga) tahun; dan/atau b) Mempunyai pengalaman kerja di bidang penyelenggaraan diklat minimal 2 (dua) tahun.
3) Tugas Assessor, adalah: a) mengumpulkan dan menganalisa data terkait unsur, sub unsur, dan komponen akreditasi; b) visitasi dan verifikasi data terkait unsur, sub unsur, dan komponen akreditasi; dan c) menilai data terkait unsur, sub unsur, dan komponen akreditasi; d) menyusun laporan hasil penilaian akreditasi; dan e) menyampaikan laporan hasil visitasi dan verifikasi kepada penilai.
4) Assessor dalam melaksanakan tugas, dilakukan dalam bentuk Tim, dan berjumlah paling banyak 3 (tiga) orang.
c. Tim Penilai.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1756, '40 1) Sekretariat Akreditasi berjumlah minimal 2 (dua) orang, 2) Sekretariat Akreditasi bertanggung jawab dalam bidang akreditasi Penyelenggara Diklat; dan 3) Sekretariat Akreditasi mempunyai tugas memberikan bantuan administratif dalam menunjang kelancaran proses pelaksanaan akreditasi; memeriksa kelengkapan jenis dokumen akreditasi; dan menyediakan data, informasi, serta laporan untuk tindak lanjut akreditasi.
b. Assessor; dan 1) Assessor adalah ASN dan/atau Praktisi yang memiliki kompetensi untuk menilai kapasitas organisasi Penyelenggara Diklat, dan program Diklat dan pengelolaan program Diklat.
2) Kompetensi Assessor: a) Mempunyai pengalaman kerja di bidang penanggulangan bencana minimal 3 (tiga) tahun; dan/atau b) Mempunyai pengalaman kerja di bidang penyelenggaraan diklat minimal 2 (dua) tahun.
3) Tugas Assessor, adalah: a) mengumpulkan dan menganalisa data terkait unsur, sub unsur, dan komponen akreditasi; b) visitasi dan verifikasi data terkait unsur, sub unsur, dan komponen akreditasi; dan c) menilai data terkait unsur, sub unsur, dan komponen akreditasi; d) menyusun laporan hasil penilaian akreditasi; dan e) menyampaikan laporan hasil visitasi dan verifikasi kepada penilai.
4) Assessor dalam melaksanakan tugas, dilakukan dalam bentuk Tim, dan berjumlah paling banyak 3 (tiga) orang.
c. Tim Penilai.', 'Lampiran hal. 51', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1757, 'perban-1-2020', 67, 'lampiran', 'Lampiran hal. 52', NULL, 52, '1) Tim Penilai bertugas memutuskan hasil akhir penilaian akreditasi dan menyampaikan laporan akreditasi Diklat Teknis PB kepada Sekretaris Utama BNPB 2) Tim Penilai bertugas:
41 a) Menerima, menilai laporan hasil visitasi dan verifikasi yang telah dilaporkan oleh assessor, dan menetapkan hasil akhir penilaian akreditasi; b) menyusun laporan hasil penilaian akreditasi; dan c) menyampaikan laporan hasil penilaian pada Sekretaris Utama BNPB.
3) Tim Penilai terdiri dari ASN dan/atau Praktisi yang memiliki kompetensi dalam menilai unsur, sub unsur, dan komponen akreditasi dalam penyelenggaraan Diklat.
4) Tim Penilai dalam melaksanakan tugas, dilakukan dalam bentuk Tim, berjumlah ganjil dan paling banyak 7 (tujuh) orang.
5) Tim Penilai terdiri dari: a) ketua merangkap anggota; b) sekretaris merangkap anggota; c) assessor merangkap anggota; dan d) anggota.
D. TAHAPAN PELAKSANAAN KEGIATAN AKREDITASI Akreditasi Diklat Teknis PB dilaksanakan melalui tahapan kegiatan yang meliputi:
1. Penerimaan Permohonan Akreditasi
a. Pusdiklat PB sebagai Instansi Pengakreditasi Diklat Teknis PB menyampaikan informasi/pemberitahuan rencana jadwal penyelenggaraan akreditasi.
b. Lembaga diklat yang akan mengajukan akreditasi, menyampaikan kesiapan diakreditasi, antara lain:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1757, '1) Tim Penilai bertugas memutuskan hasil akhir penilaian akreditasi dan menyampaikan laporan akreditasi Diklat Teknis PB kepada Sekretaris Utama BNPB 2) Tim Penilai bertugas:
41 a) Menerima, menilai laporan hasil visitasi dan verifikasi yang telah dilaporkan oleh assessor, dan menetapkan hasil akhir penilaian akreditasi; b) menyusun laporan hasil penilaian akreditasi; dan c) menyampaikan laporan hasil penilaian pada Sekretaris Utama BNPB.
3) Tim Penilai terdiri dari ASN dan/atau Praktisi yang memiliki kompetensi dalam menilai unsur, sub unsur, dan komponen akreditasi dalam penyelenggaraan Diklat.
4) Tim Penilai dalam melaksanakan tugas, dilakukan dalam bentuk Tim, berjumlah ganjil dan paling banyak 7 (tujuh) orang.
5) Tim Penilai terdiri dari: a) ketua merangkap anggota; b) sekretaris merangkap anggota; c) assessor merangkap anggota; dan d) anggota.
D. TAHAPAN PELAKSANAAN KEGIATAN AKREDITASI Akreditasi Diklat Teknis PB dilaksanakan melalui tahapan kegiatan yang meliputi:
1. Penerimaan Permohonan Akreditasi
a. Pusdiklat PB sebagai Instansi Pengakreditasi Diklat Teknis PB menyampaikan informasi/pemberitahuan rencana jadwal penyelenggaraan akreditasi.
b. Lembaga diklat yang akan mengajukan akreditasi, menyampaikan kesiapan diakreditasi, antara lain:', 'Lampiran hal. 52', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1758, 'perban-1-2020', 68, 'lampiran', 'Lampiran hal. 53', NULL, 53, '1) mengajukan permohonan akreditasi kepada Sekretaris Utama BNPB c.q. Kepala Pusdiklat PB secara tertulis (sebagaimana tercantum dalam Format-E); dan 2) mempersiapkan data/dokumen-dokumen akreditasi (sambil menunggu jawaban atas surat permohonan akreditasi).
c. Setelah mendapatkan surat jawaban atas permohonan akreditasi dari BNPB, Lembaga diklat yang mengajukan akreditasi dapat melakukan unggah data/dokumen akreditasi sesuai jadwal yang ditentukan dan proses unggah 42 data/dokumen akreditasi dilakukan secara online (untuk sementara melalui email atau googledrive).
d. Dalam proses unggah data/dokumen-dokumen tersebut, Sekretariat akreditasi melakukan pemeriksaan kelengkapan data/dokumen yang diunggah oleh Lembaga Diklat yang mengajukan akreditasi, serta menginformasikan kekurangan dokumen yang diunggah tersebut agar segera dilengkapi dalam waktu yang ditentukan.
e. Setelah waktu pengunggahan data tersebut ditutup, Sekretariat akreditasi melakukan validasi kelengkapan data/dokumen tersebut (sebagaimana tercantum dalam Format-F).
f. Hasil validasi tersebut disampaikan kepada Tim Assessor.
2. Verifikasi
a. Tim Assessor yang telah ditunjuk, melakukan verifikasi dan analisa terhadap data/dokumen kelengkapan lembaga yang mengajukan.
b. Selanjutnya hasil analisa dokumen dikonsolidasikan dalam rapat Tim Assessor sebelum melaksanakan visitasi ke lembaga diklat.
3. Visitasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1758, '1) mengajukan permohonan akreditasi kepada Sekretaris Utama BNPB c.q. Kepala Pusdiklat PB secara tertulis (sebagaimana tercantum dalam Format-E); dan 2) mempersiapkan data/dokumen-dokumen akreditasi (sambil menunggu jawaban atas surat permohonan akreditasi).
c. Setelah mendapatkan surat jawaban atas permohonan akreditasi dari BNPB, Lembaga diklat yang mengajukan akreditasi dapat melakukan unggah data/dokumen akreditasi sesuai jadwal yang ditentukan dan proses unggah 42 data/dokumen akreditasi dilakukan secara online (untuk sementara melalui email atau googledrive).
d. Dalam proses unggah data/dokumen-dokumen tersebut, Sekretariat akreditasi melakukan pemeriksaan kelengkapan data/dokumen yang diunggah oleh Lembaga Diklat yang mengajukan akreditasi, serta menginformasikan kekurangan dokumen yang diunggah tersebut agar segera dilengkapi dalam waktu yang ditentukan.
e. Setelah waktu pengunggahan data tersebut ditutup, Sekretariat akreditasi melakukan validasi kelengkapan data/dokumen tersebut (sebagaimana tercantum dalam Format-F).
f. Hasil validasi tersebut disampaikan kepada Tim Assessor.
2. Verifikasi
a. Tim Assessor yang telah ditunjuk, melakukan verifikasi dan analisa terhadap data/dokumen kelengkapan lembaga yang mengajukan.
b. Selanjutnya hasil analisa dokumen dikonsolidasikan dalam rapat Tim Assessor sebelum melaksanakan visitasi ke lembaga diklat.
3. Visitasi', 'Lampiran hal. 53', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1759, 'perban-1-2020', 69, 'lampiran', 'Lampiran hal. 54', NULL, 54, 'a. Dalam visitasi, Tim assessor memaparkan proses akreditasi dan dokumen-dokumen yang telah disampaikan oleh lembaga diklat, yang selanjutnya akan diperdalam melalui proses wawancara dengan para pihak serta melihat langsung dokumen-dokumen serta fasilitas-fasilitas lembaga diklat.
b. Jika terdapat temuan/kekurangan berdasarkan hasil visitasi tersebut, Tim Assessor akan menanyakan kepada lembaga penyelenggara terkait data-data dan dokumen tersebut, apakah lembaga penyelenggara diklat tersebut dapat melengkapi kekurangan tersebut atau tidak dengan jangka waktu 3 hari.
c. Selanjutnya, Assessor melakukan Analisa terhadap hasil pelaksanaan visitasi, yang kemudian dikonsolidasikan dalam rapat tim sebelum disampaikan kepada Tim Penilai.
4. Penilaian
a. Hasil analisis verifikasi dokumen dan visitasi disampaikan Tim Assessor kepada Tim Penilai.
43
b. Tim Assessor memaparkan hasil analisis verifikasi dokumen dan visitasi kepada Tim Penilai, pada Rapat/Sidang Penilaian Akreditasi, yang selanjutnya oleh Ketua Tim Penilai memutuskan apakah penyelengggara diklat teknis PB tersebut terakreditasi A atau B atau C atau tidak terakreditasi.
5. Penerbitan Surat Keputusan dan Sertifikat Akreditasi.
a. Tim Penilai menyampaikan keputusan hasil rapat/sidang penilaian akreditasi kepada Sekretaris Utama');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1759, 'a. Dalam visitasi, Tim assessor memaparkan proses akreditasi dan dokumen-dokumen yang telah disampaikan oleh lembaga diklat, yang selanjutnya akan diperdalam melalui proses wawancara dengan para pihak serta melihat langsung dokumen-dokumen serta fasilitas-fasilitas lembaga diklat.
b. Jika terdapat temuan/kekurangan berdasarkan hasil visitasi tersebut, Tim Assessor akan menanyakan kepada lembaga penyelenggara terkait data-data dan dokumen tersebut, apakah lembaga penyelenggara diklat tersebut dapat melengkapi kekurangan tersebut atau tidak dengan jangka waktu 3 hari.
c. Selanjutnya, Assessor melakukan Analisa terhadap hasil pelaksanaan visitasi, yang kemudian dikonsolidasikan dalam rapat tim sebelum disampaikan kepada Tim Penilai.
4. Penilaian
a. Hasil analisis verifikasi dokumen dan visitasi disampaikan Tim Assessor kepada Tim Penilai.
43
b. Tim Assessor memaparkan hasil analisis verifikasi dokumen dan visitasi kepada Tim Penilai, pada Rapat/Sidang Penilaian Akreditasi, yang selanjutnya oleh Ketua Tim Penilai memutuskan apakah penyelengggara diklat teknis PB tersebut terakreditasi A atau B atau C atau tidak terakreditasi.
5. Penerbitan Surat Keputusan dan Sertifikat Akreditasi.
a. Tim Penilai menyampaikan keputusan hasil rapat/sidang penilaian akreditasi kepada Sekretaris Utama', 'Lampiran hal. 54', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1760, 'perban-1-2020', 70, 'lampiran', 'Lampiran hal. 55', NULL, 55, 'b. Sekretaris Utama menetapkan Penyelenggara Diklat Teknis PB Terakreditasi dalam Surat Keputusan dan Sertifikat Akreditasi bagi Lembaga penyelenggara diklat yang dinilai layak sesuai dengan penilaian unsur akreditasi. Serta, bagi Lembaga penyelenggara diklat yang dinilai tidak layak disampaikan pemberitahuan secara tertulis kepada pemohonan.
