INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1761, 'perban-1-2020', 71, 'lampiran', 'Lampiran hal. 57', NULL, 57, 'Penyelenggaraan Pelatihan/Pengembangan Kompetensi lainnya RIWAYAT JABATAN JABATAN UNIT KERJA TMT RIWAYAT PENDIDIKAN JENJANG TEMPAT PENDIDIKAN TANGGAL IJAZAH PENDIDIKAN RIWAYAT DIKLAT/PELATIHAN/PENGEMBANGAN KOMPETENSI NAMA DIKLAT/ PELATIHAN/ PENYELENGGARA TEMPAT TAHUN PENGEMBANGAN KOMPETENSI PENYELENG PENYELENG GARAAN GARAAN 46 RIWAYAT PENGALAMAN KERJA SEBAGAI PENYELENGGARA PELATIHAN (*diisi oleh Tenaga Pengelola Diklat dan Tenaga Penyelenggara Diklat) NAMA DIKLAT/ PELATIHAN/ PENYELENGGARA TEMPAT TAHUN PENGEMBANGAN KOMPETENSI PENYELENG PENYELENG GARAAN GARAAN RIWAYAT KEGIATAN ILMIAH/SEMINAR (*diisi oleh Tenaga Pendidik) NAMA KEGIATAN PENYELENGGARA TEMPAT TAHUN ILMIAH/SEMINAR PENYELENGGARAAN PENYELENGGARAAN RIWAYAT PENGALAMAN YANG MENDUKUNG PENGUASAAN SUBSTANSI (*diisi oleh Tenaga Pendidik) NAMA KEGIATAN PENYELENGGARA TEMPAT TAHUN ILMIAH/SEMINAR PENYELENGGARAAN PENYELENGGARAAN RIWAYAT PENGALAMAN MENGAJAR (*diisi oleh Tenaga Pendidik) NAMA KEGIATAN PENYELENGGARA TEMPAT TAHUN ILMIAH/SEMINAR PENYELENGGARAAN PENYELENGGARAAN Catatan : Format untuk tenaga pendidik non widyaiswara dapat menyesuaikan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1761, 'Penyelenggaraan Pelatihan/Pengembangan Kompetensi lainnya RIWAYAT JABATAN JABATAN UNIT KERJA TMT RIWAYAT PENDIDIKAN JENJANG TEMPAT PENDIDIKAN TANGGAL IJAZAH PENDIDIKAN RIWAYAT DIKLAT/PELATIHAN/PENGEMBANGAN KOMPETENSI NAMA DIKLAT/ PELATIHAN/ PENYELENGGARA TEMPAT TAHUN PENGEMBANGAN KOMPETENSI PENYELENG PENYELENG GARAAN GARAAN 46 RIWAYAT PENGALAMAN KERJA SEBAGAI PENYELENGGARA PELATIHAN (*diisi oleh Tenaga Pengelola Diklat dan Tenaga Penyelenggara Diklat) NAMA DIKLAT/ PELATIHAN/ PENYELENGGARA TEMPAT TAHUN PENGEMBANGAN KOMPETENSI PENYELENG PENYELENG GARAAN GARAAN RIWAYAT KEGIATAN ILMIAH/SEMINAR (*diisi oleh Tenaga Pendidik) NAMA KEGIATAN PENYELENGGARA TEMPAT TAHUN ILMIAH/SEMINAR PENYELENGGARAAN PENYELENGGARAAN RIWAYAT PENGALAMAN YANG MENDUKUNG PENGUASAAN SUBSTANSI (*diisi oleh Tenaga Pendidik) NAMA KEGIATAN PENYELENGGARA TEMPAT TAHUN ILMIAH/SEMINAR PENYELENGGARAAN PENYELENGGARAAN RIWAYAT PENGALAMAN MENGAJAR (*diisi oleh Tenaga Pendidik) NAMA KEGIATAN PENYELENGGARA TEMPAT TAHUN ILMIAH/SEMINAR PENYELENGGARAAN PENYELENGGARAAN Catatan : Format untuk tenaga pendidik non widyaiswara dapat menyesuaikan.', 'Lampiran hal. 57', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2020 tentang Akreditasi Pendidikan dan Pelatihan Teknis Penanggulangan Bencana');
