INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1772, 'perban-1-2021', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2021 tentang Klasifikasi Arsip, Jadwal Retensi Arsip, dan Sistem Klasifikasi Keamanan dan Akses Arsip Dinamis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1772, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2021 tentang Klasifikasi Arsip, Jadwal Retensi Arsip, dan Sistem Klasifikasi Keamanan dan Akses Arsip Dinamis.', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2021 tentang Klasifikasi Arsip, Jadwal Retensi Arsip, dan Sistem Klasifikasi Keamanan dan Akses Arsip Dinamis.');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1773, 'perban-1-2021', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk mendukung pengelolaan arsip dinamis yang efektif dan efisien di pencipta arsip membuat instrumen tata naskah dinas, klasifikasi arsip, jadwal retensi arsip, dan sistem klasifikasi keamanan dan akses arsip dinamis;
b. bahwa keempat instrumen pengelolaan arsip dinamis sebagaimana dimaksud dalam huruf a, merupakan syarat awal terciptanya pengelolaan arsip dinamis dengan baik;
c. bahwa jadwal retensi arsip sebagaimana dimaksud dalam huruf a telah memperoleh persetujuan Kepala Arsip Nasional Republik Indonesia berdasarkan surat Kepala Arsip Nasional Republik Indonesia Nomor B-PK.02.09/4/2021 tanggal 26 Januari 2021;
