INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1836, 'perban-1-2021', 64, 'lampiran', 'Lampiran hal. 42', NULL, 42, 'Naskah-naskah yang berkaitan dengan pelaksanaan reviu RKA-KL yang meliputi penyusunan dan penetapan rencana reviu, surat PW 04.02 Reviu RKA K/L menyurat, surat penugasan, pelaksanaan reviu RKA-KL sampai dengan laporan RKAKL Naskah-naskah yang berkaitan dengan pelaksanaan reviu pencairan Dana Siap Pakai untuk kegiatan penanggulangan PW 04.03 Reviu DSP bencana yang meliputi penyusunan dan penetapan rencana reviu, surat menyurat, surat penugasan, pelaksanaan reviu DSP sampai dengan laporan DSP U, a. IA § 0 EVALUASI Naskah-naskah yang berkaitan dengan evaluasi atas suatu kegiatan seperti evaluasi kinerja, evaluasi strategis, dan evaluasi PW05.0 1 Evaluasi Pelaksanaan Kegiatan reformasi birokrasi serta evaluasi kegiatan lainnya meliputi surat penugasan, surat pemberitahuan, sampai dengan pelaporan PW 05.02 Evaluasi SAKIP dan LAKIP Naskah-naskah yang berkaitan dengan evaluasi Sistem Akuntabilitas Kinerja Instansi Pemerintah dan evaluasi Laporan *(7) co .(7) ea - cl) _Nc _v Ecs) (a U3 CIS -V F 0 734= Y 12 = U) Y(71 03 Deskripsi Klasifikasi Y 0 -7) Y ra Pemerintah (LAKIP) yang meliputi Aku nta bilitas Kinerja Instansi surat penugasan, surat menyurat sampai dengan laporan CI.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1836, 'Naskah-naskah yang berkaitan dengan pelaksanaan reviu RKA-KL yang meliputi penyusunan dan penetapan rencana reviu, surat PW 04.02 Reviu RKA K/L menyurat, surat penugasan, pelaksanaan reviu RKA-KL sampai dengan laporan RKAKL Naskah-naskah yang berkaitan dengan pelaksanaan reviu pencairan Dana Siap Pakai untuk kegiatan penanggulangan PW 04.03 Reviu DSP bencana yang meliputi penyusunan dan penetapan rencana reviu, surat menyurat, surat penugasan, pelaksanaan reviu DSP sampai dengan laporan DSP U, a. IA § 0 EVALUASI Naskah-naskah yang berkaitan dengan evaluasi atas suatu kegiatan seperti evaluasi kinerja, evaluasi strategis, dan evaluasi PW05.0 1 Evaluasi Pelaksanaan Kegiatan reformasi birokrasi serta evaluasi kegiatan lainnya meliputi surat penugasan, surat pemberitahuan, sampai dengan pelaporan PW 05.02 Evaluasi SAKIP dan LAKIP Naskah-naskah yang berkaitan dengan evaluasi Sistem Akuntabilitas Kinerja Instansi Pemerintah dan evaluasi Laporan *(7) co .(7) ea - cl) _Nc _v Ecs) (a U3 CIS -V F 0 734= Y 12 = U) Y(71 03 Deskripsi Klasifikasi Y 0 -7) Y ra Pemerintah (LAKIP) yang meliputi Aku nta bilitas Kinerja Instansi surat penugasan, surat menyurat sampai dengan laporan CI.', 'Lampiran hal. 42', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2021 tentang Klasifikasi Arsip, Jadwal Retensi Arsip, dan Sistem Klasifikasi Keamanan dan Akses Arsip Dinamis.');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1837, 'perban-1-2021', 65, 'lampiran', 'Lampiran hal. 42', NULL, 42, 'to 1:::! PEMANTAUAN Naskah-naskah yang berkaitan dengan kegiatan proses penilaian kemajuan suatu program/kegiatan dan percepatan penyerapan Pemantauan Pelaksanaan PW 06.01 anggaran dalam mencapai tujuan yang telah ditetapkan, termasuk Kegiatan didalamnya kegiatan monitoring pelaksanaan reformasi birokrasi di Lingkungan BNPB Naskah-naskah yang berkaitan dengan kegiatan pemantauan terhadap kerugian negara yang meliputi Tuntutan Perbendaharaan (TP)/Tuntutan Ganti Rugi (TGR) seperti: Laporan kehilangan, Berita Acara kehilangan barang/uang, SKtanggung jawab PW 06.02 Rugi (TGR) Tuntutan Ganti mutlak/surat kesanggupan untuk mengganti ke Kas Negara, SK penghapusan uang dan barang sampai laporan penyelesaian TP-TGR Pemantauan Tindak Lanjut Naskah-naskah yang berkaitan dengan pemantauan tindak lanjut PW 06.03 Laporan HasilPemeriksaan Laporan Hasil Pemeriksaan (LHP) BPK-RI, atau LHP lainnya yang (TLLHP) ditindaklanjuti sampai dengan pelaporan Naskah-naskah yang berkaitan dengan pelaksanaan fasilitasi Penerapan Sistem Peringatan Dini PW 06.04 ( Early Warning System) kepada unitkerja terhadap pengelolaan keuangan negara sampai dengan laporan.');
