INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1839, 'perban-1-2021', 67, 'lampiran', 'Lampiran hal. 45', NULL, 45, '(a O N 1:3 Sub Klasifikasi Klasifikasi Deskripsi Klasifikasi ct Y(7,) Naskah-naskah yang berkaitan dengan pengelolaan gratifikasi mulai dari persiapan, koordinasi, pelaksanaan, pengadministrasian, PW 08.03 Pengelolaan Gratifikasi penyetoran, tindaklanjut atas pelaporan penerimaan gratifikasi, penghargaan dan sanksi serta pelaporan dan sebagainya.
a. § cr) o KEGIATANPENGAWASANLAINNYA Naskah-naskah yang berkaitan dengan kegiatan sosialisasi pengawasan, pendidikan dan pelatihan pengawasan, Sosialisasi/Penyuluhan/Pembinaan PW.09.01 pembimbingan dan konsultasi, pengelolaan hasil pengawasan, Bidang Pengawasan pemaparan hasil pengawasan, keikutsertaan dalam Forbes APIP dan forum komunikasi lainnya. — TEKNOLOGI INFORMASI
g. I— Pengelolaan Data dan S istem Informasi Naskah-Naskah yang Berkaitan dengan Kegiatan ana lisis, IT.01.01 Data dan Sistem Informasi Spasial penyajian peta, evaluasi dan Pelaporan data Spasilal Naskah-Naskah yang berkaitan dengan kegiatan pengumpulan, IT.01.02 Data dan Sistem Informasi Statistik pengolahan dan pemuktahiran data statistik c4 a TEKNOLOGI DAN JARINGAN Naskah-naskah yang berkaitan dengan pembuatan dan CS pemeliharaan ap likasi, kegitan migrasi aplikasi dan data, dan OcNi Sistem dan Teknologi permintaan hosting, dari mulai analisis, evaluasi sampai dengan laporan CD _Ne O z TS ;•.');
