INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1986, 'perban-1-2022', 2, 'mengingat', 'Mengingat', NULL, 1, '(3) Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 87 Tahun 2020 tentang Jabatan Fungsional Analis Kebencanaan, perlu menyusun tata cara pengangkatan dalam Jabatan Fungsional Analis Kebencanaan melalui penyesuaian/ inpassing,
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723):
2. Undang-Undang Nomor 5 Tahun 2014 tentang Aparatur Sipil Negara (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 6, Tambahan Lembaran Negara Republik Indonesia Nomor 5494), Peraturan Pemerintah Nomor 11 Tahun 2017 tentang Manajemen Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 63, Tambahan Lembaran Negara Republik Indonesia Nomor 6037) sebagaimana telah diubah dengan Peraturan Pemerintah Nomor 17 Tahun 2020 tentang Perubahan atas Peraturan Pemerintah Nomor 11 Tahun 2017 tentang Manajemen Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2020 Nomor 68, Tambahan Lembaran Negara Republik Indonesia Nomor 6477), Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103), Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461), Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 87 Tahun 2020 tentang Jabatan Fungsional Analis Kebencanaan (Berita Negara Republik Indonesia Tahun 2020 Nomor 1588),');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1986, '(3) Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 87 Tahun 2020 tentang Jabatan Fungsional Analis Kebencanaan, perlu menyusun tata cara pengangkatan dalam Jabatan Fungsional Analis Kebencanaan melalui penyesuaian/ inpassing,
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723):
2. Undang-Undang Nomor 5 Tahun 2014 tentang Aparatur Sipil Negara (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 6, Tambahan Lembaran Negara Republik Indonesia Nomor 5494), Peraturan Pemerintah Nomor 11 Tahun 2017 tentang Manajemen Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 63, Tambahan Lembaran Negara Republik Indonesia Nomor 6037) sebagaimana telah diubah dengan Peraturan Pemerintah Nomor 17 Tahun 2020 tentang Perubahan atas Peraturan Pemerintah Nomor 11 Tahun 2017 tentang Manajemen Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2020 Nomor 68, Tambahan Lembaran Negara Republik Indonesia Nomor 6477), Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103), Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461), Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 87 Tahun 2020 tentang Jabatan Fungsional Analis Kebencanaan (Berita Negara Republik Indonesia Tahun 2020 Nomor 1588),', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1987, 'perban-1-2022', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENGANGKATAN DALAM JABATAN FUNGSIONAL ANALIS KEBENCANAAN MELALUI PENYESUAIAN / INPASSING.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1987, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENGANGKATAN DALAM JABATAN FUNGSIONAL ANALIS KEBENCANAAN MELALUI PENYESUAIAN / INPASSING.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1988, 'perban-1-2022', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM', 3, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Pegawai Negeri Sipil yang selanjutnya disingkat PNS adalah warga negara Indonesia yang memenuhi syarat tertentu, diangkat sebagai pegawai aparatur sipil negara secara tetap oleh pejabat pembina kepegawaian untuk menduduki jabatan pemerintahan.
2. Pejabat Pembina Kepegawaian yang selanjutnya disingkat PPK adalah pejabat yang mempunyai kewenangan menetapkan pengangkatan, pemindahan, dan pemberhentian PNS dan pembinaan manajemen aparatur sipil negara di instansi pemerintah sesuai dengan ketentuan peraturan perundang-undangan.
3. Pejabat yang Berwenang yang selanjutnya disebut PyB adalah pejabat yang mempunyai kewenangan melaksanakan proses pengangkatan, pemindahan, dan pemberhentian PNS sesuai dengan ketentuan peraturan perundang-undangan.
4. Jabatan Fungsional Analis Kebencanaan yang selanjutnya disingkat JF Analis Kebencanaan adalah jabatan yang mempunyai ruang lingkup tugas, tanggung jawab, dan wewenang untuk melaksanakan analisis kebencanaan.
5. Pejabat Fungsional Analis Kebencanaan yang selanjutnya disebut Analis Kebencanaan adalah PNS yang diberi tugas, tanggung jawab, dan wewenang secara penuh oleh PyB melaksanakan analisis kebencanaan.
10. ll:
12. 1G:
Analisis Kebencanaan adalah rangkaian kegiatan analisis penanggulangan bencana yang meliputi penyiapan bahan substansi teknis pengaturan bidang kebencanaan, perencanaan analisis bidang kebencanaan, pelaksanaan analisis bidang kebencanaan, pemantauan dan evaluasi, dan penyusunan norma, standar, prosedur, dan kriteria.
Penyesuaian/Inpassing JF Analis Kebencanaan adalah pengangkatan ke dalam JF Analis Kebencanaan dengan persyaratan tertentu bagi PNS yang telah dan/atau masih melaksanakan tugas di bidang JF Analis Kebencanaan guna memenuhi kebutuhan organisasi sesuai dengan ketentuan peraturan perundang-undangan dalam jangka waktu tertentu.
Kebutuhan JF Analis Kebencanaan adalah jumlah dan susunan JF Analis Kebencanaan dalam jenjang jabatan tertentu yang diperlukan oleh instansi pusat dan instansi daerah untuk melaksanakan tugas pokok dan fungsinya dalam jangka waktu tertentu.
Instansi Pembina JF Analis Kebencanaan adalah Badan Nasional Penanggulangan Bencana.
Instansi Pengguna adalah instansi pusat dan instansi daerah yang mempunyai tugas di bidang penanggulangan bencana.
Angka Kredit adalah satuan nilai dari uraian kegiatan yang ditetapkan dalam butir kegiatan dan/atau akumulasi nilai dari butir kegiatan yang harus dicapai oleh Analis Kebencanaan dalam rangka pembinaan karier yang bersangkutan.
Angka Kredit Kumulatif adalah akumulasi nilai Angka Kredit minimal yang harus dicapai oleh Analis Kebencanaan sebagai salah satu syarat kenaikan pangkat dan/atau jabatan.
Tim Penilai Angka Kredit JF Analis Kebencanaan yang selanjutnya disebut Tim Penilai adalah tim yang dibentuk dan ditetapkan oleh pejabat yang memiliki kewenangan menetapkan Angka Kredit dan bertugas mengevaluasi keselarasan hasil kerja dengan tugas yang disusun dalam sasaran kerja pegawai serta menilai capaian kinerja Analis Kebencanaan dalam bentuk Angka Kredit.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1988, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Pegawai Negeri Sipil yang selanjutnya disingkat PNS adalah warga negara Indonesia yang memenuhi syarat tertentu, diangkat sebagai pegawai aparatur sipil negara secara tetap oleh pejabat pembina kepegawaian untuk menduduki jabatan pemerintahan.
2. Pejabat Pembina Kepegawaian yang selanjutnya disingkat PPK adalah pejabat yang mempunyai kewenangan menetapkan pengangkatan, pemindahan, dan pemberhentian PNS dan pembinaan manajemen aparatur sipil negara di instansi pemerintah sesuai dengan ketentuan peraturan perundang-undangan.
3. Pejabat yang Berwenang yang selanjutnya disebut PyB adalah pejabat yang mempunyai kewenangan melaksanakan proses pengangkatan, pemindahan, dan pemberhentian PNS sesuai dengan ketentuan peraturan perundang-undangan.
4. Jabatan Fungsional Analis Kebencanaan yang selanjutnya disingkat JF Analis Kebencanaan adalah jabatan yang mempunyai ruang lingkup tugas, tanggung jawab, dan wewenang untuk melaksanakan analisis kebencanaan.
5. Pejabat Fungsional Analis Kebencanaan yang selanjutnya disebut Analis Kebencanaan adalah PNS yang diberi tugas, tanggung jawab, dan wewenang secara penuh oleh PyB melaksanakan analisis kebencanaan.
10. ll:
