INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1989, 'perban-1-2022', 5, 'pasal', 'Pasal 2', 'BAB I KETENTUAN UMUM', 5, 'Peraturan Badan ini disusun sebagai pedoman dalam melaksanakan pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/inpassing agar berjalan secara efektif, teratur, dan profesional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1989, 'Peraturan Badan ini disusun sebagai pedoman dalam melaksanakan pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/inpassing agar berjalan secara efektif, teratur, dan profesional.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1990, 'perban-1-2022', 6, 'pasal', 'Pasal 3', 'BAB II KRITERIA DAN PERSYARATAN PENYESUAIAN/ INPASSING JF ANALIS KEBENCANAAN', 5, 'Lingkup pengaturan Peraturan Badan ini meliputi:
a. kriteria dan persyaratan Penyesuaian/Inpassing JF Analis Kebencanaan,
b. prosedur Penyesuaian/Inpassing JF Analis Kebencanaanj: dan Cc. pengangkatan dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1990, 'Lingkup pengaturan Peraturan Badan ini meliputi:
a. kriteria dan persyaratan Penyesuaian/Inpassing JF Analis Kebencanaan,
b. prosedur Penyesuaian/Inpassing JF Analis Kebencanaanj: dan Cc. pengangkatan dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1991, 'perban-1-2022', 7, 'pasal', 'Pasal 4', 'BAB II KRITERIA DAN PERSYARATAN PENYESUAIAN/ INPASSING JF ANALIS KEBENCANAAN', 5, 'Pengangkatan dalam JF Analis Kebencanaan melalui penyesuaian/inpassing ditujukan bagi PNS yang pernah memiliki pengalaman dan/atau masih menjalankan tugas di bidang JF Analis Kebencanaan yang akan diduduki berdasarkan keputusan PPK.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1991, 'Pengangkatan dalam JF Analis Kebencanaan melalui penyesuaian/inpassing ditujukan bagi PNS yang pernah memiliki pengalaman dan/atau masih menjalankan tugas di bidang JF Analis Kebencanaan yang akan diduduki berdasarkan keputusan PPK.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1992, 'perban-1-2022', 8, 'pasal', 'Pasal 5', 'BAB II KRITERIA DAN PERSYARATAN PENYESUAIAN/ INPASSING JF ANALIS KEBENCANAAN', 5, '(1) Instansi Pengguna yang memiliki kebutuhan atas JF Analis Kebencanaan, dapat mengusulkan PNS untuk mengikuti proses penyesuaian/ inpassing.
(2) Untuk menjamin keseimbangan antara beban kerja dan jumlah PNS yang akan disesuaikan, pelaksanaan penyesuaian/inpassing sebagaimana dimaksud pada ayat (1) harus mempertimbangkan kebutuhan organisasi yang ditentukan melalui penghitungan kebutuhan JF Analis Kebencanaan.
(3) Instansi Pengguna menyusun penghitungan kebutuhan JF Analis Kebencanaan sebagaimana dimaksud pada ayat (1) sesuai dengan Peraturan Badan Nasional Penanggulangan Bencana mengenai pedoman penghitungan kebutuhan JF Analis Kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1992, '(1) Instansi Pengguna yang memiliki kebutuhan atas JF Analis Kebencanaan, dapat mengusulkan PNS untuk mengikuti proses penyesuaian/ inpassing.
(2) Untuk menjamin keseimbangan antara beban kerja dan jumlah PNS yang akan disesuaikan, pelaksanaan penyesuaian/inpassing sebagaimana dimaksud pada ayat (1) harus mempertimbangkan kebutuhan organisasi yang ditentukan melalui penghitungan kebutuhan JF Analis Kebencanaan.
(3) Instansi Pengguna menyusun penghitungan kebutuhan JF Analis Kebencanaan sebagaimana dimaksud pada ayat (1) sesuai dengan Peraturan Badan Nasional Penanggulangan Bencana mengenai pedoman penghitungan kebutuhan JF Analis Kebencanaan.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1993, 'perban-1-2022', 9, 'pasal', 'Pasal 6', 'BAB II KRITERIA DAN PERSYARATAN PENYESUAIAN/ INPASSING JF ANALIS KEBENCANAAN', 6, 'Pelaksanaan pengangkatan dalam JF Analis Kebencanaan melalui penyesuaian/inpassing sebagaimana dimaksud dalam Pasal 4 harus didasarkan pada kebutuhan JF Analis Kebencanaan yang telah ditetapkan oleh menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1993, 'Pelaksanaan pengangkatan dalam JF Analis Kebencanaan melalui penyesuaian/inpassing sebagaimana dimaksud dalam Pasal 4 harus didasarkan pada kebutuhan JF Analis Kebencanaan yang telah ditetapkan oleh menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1994, 'perban-1-2022', 10, 'pasal', 'Pasal 7', 'BAB III PROSEDUR PENYESUAIAN/ INPASSING JF ANALIS KEBENCANAAN', 6, '(1) PNS yang diangkat dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing harus memenuhi syarat sebagai berikut:
a. berstatus PNS,
b. memiliki integritas dan moralitas yang baik,
c. sehat jasmani dan rohani,
d. berijazah paling rendah sarjana atau diploma empat,
e. memiliki pengalaman dalam pelaksanaan tugas di bidang Analisis Kebencanaan paling singkat 2 (dua) tahun,
f. nilai prestasi kerja paling rendah bernilai baik dalam 2 (dua) tahun terakhir,
g. PNS yang dapat mengikuti penyesuaian/ inpassing berusia paling tinggi:
1. 55 (lima puluh lima) tahun bagi pejabat pelaksana,
2. 56 (lima puluh enam) tahun bagi pejabat administrator dan pejabat pengawas yang akan menduduki JF Analis Kebencanaan Ahli Pertama dan Ahli Muda,
3. 57 (lima puluh tujuh) tahun bagi pejabat administrator yang akan menduduki JF Analis Kebencanaan Ahli Madya, dan
4. 59 (lima puluh sembilan) tahun bagi pejabat pimpinan tinggi,
h. tidak sedang dalam proses atau menjalani hukuman disiplin tingkat sedang/ berat, dan/atau tidak sedang dalam proses pemeriksaan dengan ancaman hukuman disiplin tingkat sedang/ berat,
i. tidak sedang menjalankan tugas belajar lebih dari 6 (enam) bulan pada saat penyesuaian/inpassing, dan j- tidak sedang menjalankan cuti di luar tanggungan negara pada saat penyesuaian/ inpassing.
(2) Selain persyaratan sebagaimana dimaksud pada ayat
(1) Instansi Pengguna menyampaikan kebutuhan JF Analis Kebencanaan kepada Badan Nasional Penanggulangan Bencana untuk mendapatkan rekomendasi.
(3) Rekomendasi sebagaimana dimaksud pada ayat (2) menjadi dasar bagi PPK dalam mengusulkan kebutuhan JF Analis Kebencanaan yang diangkat melalui pengangkatan/inpassing.
(4) Kebutuhan JF Analis Kebencanaan sebagaimana dimaksud pada ayat (3) diusulkan oleh PPK kepada menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.
(5) Kebutuhan JF Analis Kebencanaan sebagaimana dimaksud pada ayat (4) ditetapkan oleh menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1994, '(1) PNS yang diangkat dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing harus memenuhi syarat sebagai berikut:
a. berstatus PNS,
b. memiliki integritas dan moralitas yang baik,
c. sehat jasmani dan rohani,
d. berijazah paling rendah sarjana atau diploma empat,
e. memiliki pengalaman dalam pelaksanaan tugas di bidang Analisis Kebencanaan paling singkat 2 (dua) tahun,
f. nilai prestasi kerja paling rendah bernilai baik dalam 2 (dua) tahun terakhir,
g. PNS yang dapat mengikuti penyesuaian/ inpassing berusia paling tinggi:
1. 55 (lima puluh lima) tahun bagi pejabat pelaksana,
2. 56 (lima puluh enam) tahun bagi pejabat administrator dan pejabat pengawas yang akan menduduki JF Analis Kebencanaan Ahli Pertama dan Ahli Muda,
3. 57 (lima puluh tujuh) tahun bagi pejabat administrator yang akan menduduki JF Analis Kebencanaan Ahli Madya, dan
4. 59 (lima puluh sembilan) tahun bagi pejabat pimpinan tinggi,
h. tidak sedang dalam proses atau menjalani hukuman disiplin tingkat sedang/ berat, dan/atau tidak sedang dalam proses pemeriksaan dengan ancaman hukuman disiplin tingkat sedang/ berat,
i. tidak sedang menjalankan tugas belajar lebih dari 6 (enam) bulan pada saat penyesuaian/inpassing, dan j- tidak sedang menjalankan cuti di luar tanggungan negara pada saat penyesuaian/ inpassing.
(2) Selain persyaratan sebagaimana dimaksud pada ayat
(1) Instansi Pengguna menyampaikan kebutuhan JF Analis Kebencanaan kepada Badan Nasional Penanggulangan Bencana untuk mendapatkan rekomendasi.
(3) Rekomendasi sebagaimana dimaksud pada ayat (2) menjadi dasar bagi PPK dalam mengusulkan kebutuhan JF Analis Kebencanaan yang diangkat melalui pengangkatan/inpassing.
(4) Kebutuhan JF Analis Kebencanaan sebagaimana dimaksud pada ayat (3) diusulkan oleh PPK kepada menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.
(5) Kebutuhan JF Analis Kebencanaan sebagaimana dimaksud pada ayat (4) ditetapkan oleh menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1995, 'perban-1-2022', 11, 'pasal', 'Pasal 8', 'BAB III PROSEDUR PENYESUAIAN/ INPASSING JF ANALIS KEBENCANAAN; Bagian Kesatu Pengusulan oleh Instansi Pengguna', 8, 'Prosedur Penyesuaian/Inpassing JF Analis Kebencanaan terdiri atas:
a. pengusulan oleh Instansi Pengguna, dan
b. seleksi administrasi dan portofolio.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1995, 'Prosedur Penyesuaian/Inpassing JF Analis Kebencanaan terdiri atas:
a. pengusulan oleh Instansi Pengguna, dan
b. seleksi administrasi dan portofolio.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1996, 'perban-1-2022', 12, 'pasal', 'Pasal 9', 'BAB III PROSEDUR PENYESUAIAN/ INPASSING JF ANALIS KEBENCANAAN; Bagian Kedua Seleksi Administrasi dan Portofolio', 8, '(1) PNS yang telah memenuhi persyaratan sebagaimana dimaksud dalam Pasal 7 dapat mengajukan permohonan usulan pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/inpassing kepada PPK melalui PyB secara hierarki.
(2) Permohonan sebagaimana dimaksud pada ayat (1) disampaikan oleh Instansi Pengguna kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana.
(3) Permohonan sebagaimana dimaksud pada ayat (2) dilengkapi dengan surat penetapan kebutuhan JF Analis Kebencanaan sebagaimana dimaksud dalam Pasal 7 ayat (2).
(4) Selain surat penetapan kebutuhan sebagaimana dimaksud pada ayat (3), permohonan harus dilengkapi dengan dokumen berupa:
a. salinan surat keputusan kenaikan pangkat terakhir,
b. salinan surat keputusan pengangkatan dalam jabatan terakhir,
c. surat keterangan dari pimpinan unit kerja yang menyatakan bahwa tidak sedang menjalani hukuman disiplin tingkat sedang maupun berat,
d. surat keterangan sehat jasmani dan rohani dari dokter:
e. salinan ijazah pendidikan terakhir sesuai kualifikasi,
f. salinan penilaian kinerja 2 (dua) tahun terakhir,
g. daftar riwayat hidup,
h. surat keterangan yang memuat pengalaman mengenai pelaksanaan tugas di bidang Analisis Kebencanaan secara kumulatif paling sedikit selama 2 (dua) tahun dan ditandatangani oleh PyB,
i. surat pernyataan yang menyatakan:
1. bersedia diangkat menjadi JF Analis Kebencanaan :
2. bersedia mengikuti pendidikan dan pelatihan, dan
3. kesediaan untuk melaksanakan kegiatan di bidang JF Analis Kebencanaan secara aktif, dan
j. surat keterangan tidak sedang menjalankan tugas belajar dan tidak sedang menjalankan cuti di luar tanggungan negara dari pejabat pimpinan tinggi pratama.
(5) Format surat permohonan sebagaimana dimaksud pada ayat (2) dan format dokumen persyaratan administrasi sebagaimana dimaksud pada ayat (4) huruf c, huruf g, huruf h, huruf i, dan huruf j dibuat sesuai dengan format sebagaimana tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1996, '(1) PNS yang telah memenuhi persyaratan sebagaimana dimaksud dalam Pasal 7 dapat mengajukan permohonan usulan pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/inpassing kepada PPK melalui PyB secara hierarki.
(2) Permohonan sebagaimana dimaksud pada ayat (1) disampaikan oleh Instansi Pengguna kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana.
(3) Permohonan sebagaimana dimaksud pada ayat (2) dilengkapi dengan surat penetapan kebutuhan JF Analis Kebencanaan sebagaimana dimaksud dalam Pasal 7 ayat (2).
(4) Selain surat penetapan kebutuhan sebagaimana dimaksud pada ayat (3), permohonan harus dilengkapi dengan dokumen berupa:
a. salinan surat keputusan kenaikan pangkat terakhir,
b. salinan surat keputusan pengangkatan dalam jabatan terakhir,
c. surat keterangan dari pimpinan unit kerja yang menyatakan bahwa tidak sedang menjalani hukuman disiplin tingkat sedang maupun berat,
d. surat keterangan sehat jasmani dan rohani dari dokter:
e. salinan ijazah pendidikan terakhir sesuai kualifikasi,
f. salinan penilaian kinerja 2 (dua) tahun terakhir,
g. daftar riwayat hidup,
h. surat keterangan yang memuat pengalaman mengenai pelaksanaan tugas di bidang Analisis Kebencanaan secara kumulatif paling sedikit selama 2 (dua) tahun dan ditandatangani oleh PyB,
i. surat pernyataan yang menyatakan:
1. bersedia diangkat menjadi JF Analis Kebencanaan :
2. bersedia mengikuti pendidikan dan pelatihan, dan
3. kesediaan untuk melaksanakan kegiatan di bidang JF Analis Kebencanaan secara aktif, dan
j. surat keterangan tidak sedang menjalankan tugas belajar dan tidak sedang menjalankan cuti di luar tanggungan negara dari pejabat pimpinan tinggi pratama.
(5) Format surat permohonan sebagaimana dimaksud pada ayat (2) dan format dokumen persyaratan administrasi sebagaimana dimaksud pada ayat (4) huruf c, huruf g, huruf h, huruf i, dan huruf j dibuat sesuai dengan format sebagaimana tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1997, 'perban-1-2022', 13, 'pasal', 'Pasal 10', 'BAB III PROSEDUR PENYESUAIAN/ INPASSING JF ANALIS KEBENCANAAN; Bagian Kedua Seleksi Administrasi dan Portofolio', 9, '(1) Pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/inpassing dilakukan dengan seleksi administrasi dan portofolio. -10--
(2) Seleksi administrasi dan portofolio sebagaimana dimaksud pada ayat (1) dilakukan oleh tim seleksi.
(3) Tim seleksi sebagaimana dimaksud pada ayat (2) ditetapkan oleh Sekretaris Utama Badan Nasional Penanggulangan Bencana.
(4) Tim seleksi sebagaimana dimaksud pada ayat (3) disesuaikan dengan kebutuhan penyelenggaraan seleksi administrasi dan portofolio, dengan susunan sebagai berikut:
a. ketua,
b. sekretaris: dan Cc. anggota
(5) Anggota sebagaimana dimaksud pada ayat (4) huruf c berjumlah paling sedikit 3 (tiga) orang.
(6) Tim seleksi sebagaimana dimaksud pada ayat (4) berjumlah ganjil.
(7) Tim seleksi sebagaimana dimaksud pada ayat (4) terdiri dari pejabat dan/atau pegawai yang mempunyai kemampuan untuk melakukan penilaian kinerja Analis Kebencanaan.
(8) Tim seleksi dapat melibatkan pihak dari luar Instansi Pembina JF Analis Kebencanaan.
(9) Proses seleksi administrasi dan portofolio oleh tim seleksi sebagaimana dimaksud pada ayat (1) dilakukan dalam jangka waktu paling lama 30 (tiga puluh) hari kerja terhitung sejak tanggal 23 September 2022.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1997, '(1) Pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/inpassing dilakukan dengan seleksi administrasi dan portofolio. -10--
(2) Seleksi administrasi dan portofolio sebagaimana dimaksud pada ayat (1) dilakukan oleh tim seleksi.
(3) Tim seleksi sebagaimana dimaksud pada ayat (2) ditetapkan oleh Sekretaris Utama Badan Nasional Penanggulangan Bencana.
(4) Tim seleksi sebagaimana dimaksud pada ayat (3) disesuaikan dengan kebutuhan penyelenggaraan seleksi administrasi dan portofolio, dengan susunan sebagai berikut:
a. ketua,
b. sekretaris: dan Cc. anggota
(5) Anggota sebagaimana dimaksud pada ayat (4) huruf c berjumlah paling sedikit 3 (tiga) orang.
(6) Tim seleksi sebagaimana dimaksud pada ayat (4) berjumlah ganjil.
(7) Tim seleksi sebagaimana dimaksud pada ayat (4) terdiri dari pejabat dan/atau pegawai yang mempunyai kemampuan untuk melakukan penilaian kinerja Analis Kebencanaan.
(8) Tim seleksi dapat melibatkan pihak dari luar Instansi Pembina JF Analis Kebencanaan.
(9) Proses seleksi administrasi dan portofolio oleh tim seleksi sebagaimana dimaksud pada ayat (1) dilakukan dalam jangka waktu paling lama 30 (tiga puluh) hari kerja terhitung sejak tanggal 23 September 2022.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1998, 'perban-1-2022', 14, 'pasal', 'Pasal 11', 'BAB III PROSEDUR PENYESUAIAN/ INPASSING JF ANALIS KEBENCANAAN; Bagian Kedua Seleksi Administrasi dan Portofolio', 10, 'Tim seleksi administrasi dan portofolio mempunyai tugas:
a. melakukan verifikasi kesesuaian dokumen administrasi persyaratan pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/inpassing yang diajukan oleh Instansi Pengguna,
b. melakukan penelaahan portofolio terhadap PNS yang akan dilakukan pengangkatan dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing,
c. memberikan penilaian dengan melakukan pemeringkatan terhadap kualifikasi kompetensi dan kinerja dari persyaratan administrasi dan portofolio, dan
d. melaporkan seluruh proses tahapan seleksi administrasi dan portofolio terhadap PNS yang mengikuti Penyesuaian/ Inpassing JF Analis Kebencanaan kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1998, 'Tim seleksi administrasi dan portofolio mempunyai tugas:
a. melakukan verifikasi kesesuaian dokumen administrasi persyaratan pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/inpassing yang diajukan oleh Instansi Pengguna,
b. melakukan penelaahan portofolio terhadap PNS yang akan dilakukan pengangkatan dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing,
c. memberikan penilaian dengan melakukan pemeringkatan terhadap kualifikasi kompetensi dan kinerja dari persyaratan administrasi dan portofolio, dan
d. melaporkan seluruh proses tahapan seleksi administrasi dan portofolio terhadap PNS yang mengikuti Penyesuaian/ Inpassing JF Analis Kebencanaan kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (1999, 'perban-1-2022', 15, 'pasal', 'Pasal 12', 'BAB IV PENGANGKATAN DALAM JF ANALIS KEBENCANAAN MELALUI PENYESUAIAN/ INPASSING; Bagian Kesatu Penilaian dan Penetapan Angka Kredit', 11, '(1) Tim seleksi sebagaimana dimaksud dalam Pasal 10 ayat
(2) menyampaikan hasil seleksi kepada pejabat pimpinan tinggi pratama yang membidangi pembinaan jabatan fungsional.
(2) Hasil seleksi sebagaimana dimaksud pada ayat (1) disampaikan kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana.
(3) Hasil seleksi sebagaimana dimaksud pada ayat (2) disampaikan oleh Sekretaris Utama Badan Nasional Penanggulangan Bencana kepada Instansi Pengguna yang memuat informasi sebagai berikut:
a. PNS dinyatakan lolos seleksi apabila memenuhi persyaratan administrasi dan portofolio, atau
b. PNS dinyatakan tidak lolos seleksi apabila tidak memenuhi persyaratan administrasi dan portofolio.
(4) Terhadap PNS yang lolos seleksi sebagaimana dimaksud pada ayat (3) huruf a diberikan rekomendasi untuk dapat digunakan sebagai syarat dalam pengangkatan JF Analis Kebencanaan melalui penyesuaian/ inpassing.
(5) Format rekomendasi sebagaimana dimaksud pada ayat
(4) sebagaimana tercantum dalam Lampiran II yang merupakan bagian yang tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (1999, '(1) Tim seleksi sebagaimana dimaksud dalam Pasal 10 ayat
(2) menyampaikan hasil seleksi kepada pejabat pimpinan tinggi pratama yang membidangi pembinaan jabatan fungsional.
(2) Hasil seleksi sebagaimana dimaksud pada ayat (1) disampaikan kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana.
(3) Hasil seleksi sebagaimana dimaksud pada ayat (2) disampaikan oleh Sekretaris Utama Badan Nasional Penanggulangan Bencana kepada Instansi Pengguna yang memuat informasi sebagai berikut:
a. PNS dinyatakan lolos seleksi apabila memenuhi persyaratan administrasi dan portofolio, atau
b. PNS dinyatakan tidak lolos seleksi apabila tidak memenuhi persyaratan administrasi dan portofolio.
(4) Terhadap PNS yang lolos seleksi sebagaimana dimaksud pada ayat (3) huruf a diberikan rekomendasi untuk dapat digunakan sebagai syarat dalam pengangkatan JF Analis Kebencanaan melalui penyesuaian/ inpassing.
(5) Format rekomendasi sebagaimana dimaksud pada ayat
(4) sebagaimana tercantum dalam Lampiran II yang merupakan bagian yang tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2000, 'perban-1-2022', 16, 'pasal', 'Pasal 13', 'BAB IV PENGANGKATAN DALAM JF ANALIS KEBENCANAAN MELALUI PENYESUAIAN/ INPASSING; Bagian Kedua Mekanisme Pengangkatan Dalam JF Analis Kebencanaan', 12, '(1) Jenjang JF Analis Kebencanaan ditetapkan setelah PNS memenuhi persyaratan sebagaimana dimaksud dalam Pasal 12 ayat (4) dan diberikan Angka Kredit sesuai dengan Angka Kredit Kumulatif untuk Penyesuaian/Inpassing JF Analis Kebencanaan sebagaimana tercantum dalam Lampiran III yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(2) Angka Kredit sebagaimana dimaksud pada ayat (1) sesuai dengan pendidikan, masa kerja dalam pangkat dan golongan ruang terakhir.
(3) Angka Kredit sebagaimana dimaksud pada ayat (2) hanya berlaku 1 (satu) kali pada saat Penyesuaian/ Inpassing JF Analis Kebencanaan .
(4) Penetapan Angka Kredit sebagaimana dimaksud ayat
(1) sebagaimana tercantum dalam Lampiran IV yang merupakan bagian yang tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2000, '(1) Jenjang JF Analis Kebencanaan ditetapkan setelah PNS memenuhi persyaratan sebagaimana dimaksud dalam Pasal 12 ayat (4) dan diberikan Angka Kredit sesuai dengan Angka Kredit Kumulatif untuk Penyesuaian/Inpassing JF Analis Kebencanaan sebagaimana tercantum dalam Lampiran III yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(2) Angka Kredit sebagaimana dimaksud pada ayat (1) sesuai dengan pendidikan, masa kerja dalam pangkat dan golongan ruang terakhir.
(3) Angka Kredit sebagaimana dimaksud pada ayat (2) hanya berlaku 1 (satu) kali pada saat Penyesuaian/ Inpassing JF Analis Kebencanaan .
(4) Penetapan Angka Kredit sebagaimana dimaksud ayat
(1) sebagaimana tercantum dalam Lampiran IV yang merupakan bagian yang tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2001, 'perban-1-2022', 17, 'pasal', 'Pasal 14', 'BAB V PELANTIKAN DAN PENGAMBILAN SUMPAH', 12, '(1) PNS yang telah mendapatkan rekomendasi dari Instansi Pembina JF Analis Kebencanaan diangkat dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing.
(2) Pengangkatan dalam JF Analis Kebencanaan melalui penyesuaian/inpassing ditetapkan dengan keputusan yang ditandatangani oleh PPK dan dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
(3) Pengangkatan dalam JF Analis Kebencanaan melalui penyesuaian/inpassing sebagamana dimaksud pada ayat (1) disampaikan kepada Analis Kebencanaan yang bersangkutan dengan tembusan disampaikan kepada:
a. Kepala Badan Nasional Penanggulangan Bencana,
b. Kepala Badan Kepegawaian Negara,
c. Kepala Kantor Pelayanan Perbendaharaan yang bersangkutan,
d. pimpinan unit kerja yang bersangkutan, dan
e. pejabat lain yang dianggap perlu.
(4) Keputusan sebagaimana dimaksud pada ayat (2) sesuai format sebagaimana tercantum dalam Lampiran V yang merupakan bagian yang tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2001, '(1) PNS yang telah mendapatkan rekomendasi dari Instansi Pembina JF Analis Kebencanaan diangkat dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing.
(2) Pengangkatan dalam JF Analis Kebencanaan melalui penyesuaian/inpassing ditetapkan dengan keputusan yang ditandatangani oleh PPK dan dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
(3) Pengangkatan dalam JF Analis Kebencanaan melalui penyesuaian/inpassing sebagamana dimaksud pada ayat (1) disampaikan kepada Analis Kebencanaan yang bersangkutan dengan tembusan disampaikan kepada:
a. Kepala Badan Nasional Penanggulangan Bencana,
b. Kepala Badan Kepegawaian Negara,
c. Kepala Kantor Pelayanan Perbendaharaan yang bersangkutan,
d. pimpinan unit kerja yang bersangkutan, dan
e. pejabat lain yang dianggap perlu.
(4) Keputusan sebagaimana dimaksud pada ayat (2) sesuai format sebagaimana tercantum dalam Lampiran V yang merupakan bagian yang tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2002, 'perban-1-2022', 18, 'pasal', 'Pasal 15', 'BAB VI PELAPORAN', 13, '(1) Setiap PNS yang diangkat menjadi Analis Kebencanaan melalui penyesuaian/inpassing wajib dilantik dan diambil sumpah/janji menurut agama atau kepercayaannya kepada Tuhan Yang Maha Esa.
(2) Pelantikan dan pengambilan sumpah /janji sebagaimana dimaksud pada ayat (1) sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2002, '(1) Setiap PNS yang diangkat menjadi Analis Kebencanaan melalui penyesuaian/inpassing wajib dilantik dan diambil sumpah/janji menurut agama atau kepercayaannya kepada Tuhan Yang Maha Esa.
(2) Pelantikan dan pengambilan sumpah /janji sebagaimana dimaksud pada ayat (1) sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2003, 'perban-1-2022', 19, 'pasal', 'Pasal 16', 'BAB VII KETENTUAN LAIN-LAIN', 13, '(1) Instansi Pengguna wajib melaporkan hasil pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/inpassing kepada Kepala Badan Nasional Penanggulangan Bencana sesuai dengan format laporan sebagaimana tercantum dalam Lampiran VI yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(2) Laporan hasil pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing ditembuskan kepada:
a. menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara, dan
b. Kepala Badan Kepegawaian Negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2003, '(1) Instansi Pengguna wajib melaporkan hasil pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/inpassing kepada Kepala Badan Nasional Penanggulangan Bencana sesuai dengan format laporan sebagaimana tercantum dalam Lampiran VI yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(2) Laporan hasil pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing ditembuskan kepada:
a. menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara, dan
b. Kepala Badan Kepegawaian Negara.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2004, 'perban-1-2022', 20, 'pasal', 'Pasal 17', 'BAB VIII KETENTUAN PENUTUP', 14, '(1) Dalam hal PNS yang dinyatakan lolos seleksi sampai dengan periode pengangkatan ke dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing mengalami:
a. kenaikan pangkat,
b. penyesuaian pendidikan, dan/atau
c. penambahan masa kerja, yang tidak mempengaruhi kenaikan jenjang jabatan namun mempengaruhi kenaikan angka kredit, dapat melakukan permohonan penyesuaian rekomendasi pengangkatan dalam JF Analis Kebencanaan sebagaimana dimaksud dalam Pasal 12 ayat (4) sampai dengan batas waktu pelaksanaan penyesuaian/ inpassing.
(2) Dalam hal PNS yang dinyatakan lolos seleksi sampai dengan periode pengangkatan ke dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing mengalami kenaikan pangkat yang mempengaruhi kenaikan jenjang jabatan, tidak dapat melakukan permohonan penyesuaian rekomendasi pengangkatan dalam JF Analis Kebencanaan sebagaimana dimaksud dalam Pasal 12 ayat (4) dan wajib mengikuti seleksi penyesuaian/ inpassing ulang.
(3) Dalam hal PNS sebagaimana dimaksud pada ayat (2) tidak mengikuti seleksi penyesuaian/inpassing ulang dan tetap ingin diangkat ke dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing, rekomendasi yang diberikan menggunakan kepangkatan, pendidikan, atau masa kerja yang ditetapkan berdasarkan hasil seleksi penyesuaian/inpassing yang pertama tetap berlaku dengan syarat kenaikan pangkat terbarunya dibatalkan terlebih dahulu dan dikembalikan ke pangkat sebelumnya.
(4) Permohonan penyesuaian rekomendasi sebagaimana dimaksud pada ayat (1) disampaikan oleh Instansi Pengguna kepada Instansi Pembina.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2004, '(1) Dalam hal PNS yang dinyatakan lolos seleksi sampai dengan periode pengangkatan ke dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing mengalami:
a. kenaikan pangkat,
b. penyesuaian pendidikan, dan/atau
c. penambahan masa kerja, yang tidak mempengaruhi kenaikan jenjang jabatan namun mempengaruhi kenaikan angka kredit, dapat melakukan permohonan penyesuaian rekomendasi pengangkatan dalam JF Analis Kebencanaan sebagaimana dimaksud dalam Pasal 12 ayat (4) sampai dengan batas waktu pelaksanaan penyesuaian/ inpassing.
(2) Dalam hal PNS yang dinyatakan lolos seleksi sampai dengan periode pengangkatan ke dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing mengalami kenaikan pangkat yang mempengaruhi kenaikan jenjang jabatan, tidak dapat melakukan permohonan penyesuaian rekomendasi pengangkatan dalam JF Analis Kebencanaan sebagaimana dimaksud dalam Pasal 12 ayat (4) dan wajib mengikuti seleksi penyesuaian/ inpassing ulang.
(3) Dalam hal PNS sebagaimana dimaksud pada ayat (2) tidak mengikuti seleksi penyesuaian/inpassing ulang dan tetap ingin diangkat ke dalam JF Analis Kebencanaan melalui penyesuaian/ inpassing, rekomendasi yang diberikan menggunakan kepangkatan, pendidikan, atau masa kerja yang ditetapkan berdasarkan hasil seleksi penyesuaian/inpassing yang pertama tetap berlaku dengan syarat kenaikan pangkat terbarunya dibatalkan terlebih dahulu dan dikembalikan ke pangkat sebelumnya.
(4) Permohonan penyesuaian rekomendasi sebagaimana dimaksud pada ayat (1) disampaikan oleh Instansi Pengguna kepada Instansi Pembina.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2005, 'perban-1-2022', 21, 'pasal', 'Pasal 19', 'BAB VIII KETENTUAN PENUTUP', 15, 'Pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/inpassing dilaksanakan sampai dengan 23 Desember 2022.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2005, 'Pengangkatan PNS dalam JF Analis Kebencanaan melalui penyesuaian/inpassing dilaksanakan sampai dengan 23 Desember 2022.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2006, 'perban-1-2022', 22, 'pasal', 'Pasal 20', 'BAB VIII KETENTUAN PENUTUP', 15, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2006, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
