INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2007, 'perban-1-2022', 23, 'lain', 'Penutup', NULL, 16, 'Ditetapkan di Jakarta pada tanggal 21 Januari 2022 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
