INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2009, 'perban-1-2022', 25, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'LAMPIRAN I PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR | TAHUN 2022 TENTANG PENGANGKATAN DALAM JABATAN FUNGSIONAL — ANALIS KEBENCANAAN MELALUI PENYESUAIAN/INPASSING FORMAT DOKUMEN PERSYARATAN ADMINISTRASI Format 1- Surat Permohonan Penyesuaian/Inpassing dalam Jabatan Fungsional Analis Kebencanaan KOP SURAT INSTANSI Tempat ...., Tanggal....
Nomor Tieemnanunancena Lampiran Dinnwanauann sean Sifat H keriasransasane Hal : Permohonan Pengangkatan Pegawai Negeri Sipil (PNS) dalam Jabatan Fungsional Analis Kebencanaan melalui Penyesuaian/Inpassing Kepada Yth.
Sekretaris Utama Badan Nasional Penanggulangan Bencana di Jakarta Menindaklanjuti Peraturan Badan Nasional Penanggulangan Bencana Nomor ...
Tahun ... tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan melalui Penyesuaian/Inpassing, bersama ini kami sampaikan permohonan pengangkatan PNS dalam Jabatan Fungsional Analis Kebencanaan melalui Penyesuaian /Inpassing sebagai berikut:
No Nama TMT Unit Lengkap | NIP | Pangkat/Gol. | Pangkat | Jabatan | Kerja/Instansi | Pendidikan | Keterangan dan Ruang Gelar dst Selanjutnya sebagai persyaratan, bersama ini kami lampirkan dokumen administrasi sebagai berikut:
1. salinan surat keputusan kenaikan pangkat terakhir,
2. salinan surat keputusan pengangkatan dalam jabatan terakhir,
3. surat keterangan dari PyB yang menyatakan bahwa tidak sedang menjalani hukuman disiplin tingkat sedang maupun berat,
4. surat keterangan sehat jasmani dan rohani dari dokter,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2009, 'LAMPIRAN I PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR | TAHUN 2022 TENTANG PENGANGKATAN DALAM JABATAN FUNGSIONAL — ANALIS KEBENCANAAN MELALUI PENYESUAIAN/INPASSING FORMAT DOKUMEN PERSYARATAN ADMINISTRASI Format 1- Surat Permohonan Penyesuaian/Inpassing dalam Jabatan Fungsional Analis Kebencanaan KOP SURAT INSTANSI Tempat ...., Tanggal....
Nomor Tieemnanunancena Lampiran Dinnwanauann sean Sifat H keriasransasane Hal : Permohonan Pengangkatan Pegawai Negeri Sipil (PNS) dalam Jabatan Fungsional Analis Kebencanaan melalui Penyesuaian/Inpassing Kepada Yth.
Sekretaris Utama Badan Nasional Penanggulangan Bencana di Jakarta Menindaklanjuti Peraturan Badan Nasional Penanggulangan Bencana Nomor ...
Tahun ... tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan melalui Penyesuaian/Inpassing, bersama ini kami sampaikan permohonan pengangkatan PNS dalam Jabatan Fungsional Analis Kebencanaan melalui Penyesuaian /Inpassing sebagai berikut:
No Nama TMT Unit Lengkap | NIP | Pangkat/Gol. | Pangkat | Jabatan | Kerja/Instansi | Pendidikan | Keterangan dan Ruang Gelar dst Selanjutnya sebagai persyaratan, bersama ini kami lampirkan dokumen administrasi sebagai berikut:
1. salinan surat keputusan kenaikan pangkat terakhir,
2. salinan surat keputusan pengangkatan dalam jabatan terakhir,
3. surat keterangan dari PyB yang menyatakan bahwa tidak sedang menjalani hukuman disiplin tingkat sedang maupun berat,
4. surat keterangan sehat jasmani dan rohani dari dokter,', 'Lampiran hal. 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Analis Kebencanaan Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2010, 'perban-1-2022', 26, 'lampiran', 'Lampiran hal. 18', NULL, 18, '5. salinan ijazah pendidikan terakhir sesuai kualifikasi,
6. salinan penilaian kinerja 2 (dua) tahun terakhir yang telah dilegalisir,
7. daftar riwayat hidup,
8. surat keterangan yang memuat pengalaman mengenai pelaksanaan tugas di bidang Analisis Kebencanaan paling sedikit selama 2 (dua) tahun dan ditandatangani oleh PyB,
9. surat pernyataan yang menyatakan:
a. bersedia diangkat menjadi Jabatan Fungsional Analis Kebencanaan,
b. bersedia mengikuti pendidikan dan pelatihan, dan
c. kesediaan untuk melaksanakan kegiatan di bidang Jabatan Fungsional Analis Kebencanaan secara aktif, dan
10. surat keterangan tidak sedang menjalankan tugas belajar, tidak sedang menjalankan cuti di luar tanggungan negara dari pejabat pimpinan tinggi pratama.
Atas perhatian dan perkenannya, kami mengucapkan terima kasih.
(Pejabat Pimpinan Tinggi Pratama Tingkat Pusat/Daerah) (tanda tangan, stempel dinas) 19 Format 2- Surat Keterangan Tidak Sedang Menjalani Hukuman Disiplin Tingkat Sedang Maupun Berat.
KOP SURAT INSTANSI SURAT KETERANGAN TIDAK SEDANG MENJALANI/DIJATUHI HUKUMAN DISIPLIN TINGKAT SEDANG MAUPUN BERAT Yang bertanda tangan di bawah ini:
Nama NIP Pangkat/ Gol.
Jabatan menyatakan dengan sesungguhnya bahwa Pegawai Negeri Sipil yang tersebut di bawah ini:
Nama NIP Pangkat/ Gol.
Jabatan Unit Kerja bahwa yang bersangkutan tidak sedang menjalani/dijatuhi hukuman disiplin tingkat sedang/ berat.
Demikian surat pernyataan ini dibuat untuk dapat dipergunakan sebagaimana mestinya.');
