INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2075, 'perban-1-2024', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk mewujudkan penyelenggaraan penanggulangan bencana yang profesional dan berbasis pengurangan risiko bencana, perlu didukung dengan mekanisme penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana;
b. bahwa penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana memerlukan pedoman penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2075, 'a. bahwa untuk mewujudkan penyelenggaraan penanggulangan bencana yang profesional dan berbasis pengurangan risiko bencana, perlu didukung dengan mekanisme penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana;
b. bahwa penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana memerlukan pedoman penelaahan, verifikasi, dan evaluasi penyaluran dana bersama penanggulangan bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2076, 'perban-1-2024', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 183);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja 2024, No.4 -2- Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2076, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 183);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja 2024, No.4 -2- Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2077, 'perban-1-2024', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2077, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENELAAHAN, VERIFIKASI, DAN EVALUASI PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2078, 'perban-1-2024', 4, 'pasal', 'Pasal 1', 'BAB II PRIORITAS PENYALURAN; Bagian Kesatu Umum', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
2. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
3. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, pengungsian, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
4. Dana Penanggulangan Bencana adalah dana yang digunakan bagi penanggulangan bencana untuk tahap prabencana, darurat bencana, dan/atau pascabencana.
5. Dana Bersama Penanggulangan Bencana, yang selanjutnya disebut Dana Bersama, adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi Dana Penanggulangan Bencana yang memadai dan berkelanjutan.
6. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
7. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara pemerintahan daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
2024, No.4
8. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nondepartemen setingkat menteri yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan.
9. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang menyelenggarakan penanggulangan bencana di daerah.
10. Kepala adalah pimpinan lembaga pemerintah nondepartemen setingkat menteri yang melakukan penyelenggaraan penanggulangan bencana.');
