INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2105, 'perban-1-2024', 31, 'pasal', 'Pasal 28', 'BAB VI KETENTUAN PENUTUP', 9, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
