INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2108, 'bahwa untuk melaksanakan ketentuan Pasal 4 ayat (2) Peraturan Presiden Nomor 87 Tahun 2020 tentang Rencana Induk Penanggulangan Bencana Tahun 2020-2044, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2109, 'perban-1-2025', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Presiden Nomor 87 Tahun 2020 tentang Rencana Induk Penanggulangan Bencana Tahun 2020- 2044 (Lembaran Negara Republik Indonesia Tahun 2020 Nomor 204);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2109, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Presiden Nomor 87 Tahun 2020 tentang Rencana Induk Penanggulangan Bencana Tahun 2020- 2044 (Lembaran Negara Republik Indonesia Tahun 2020 Nomor 204);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2110, 'perban-1-2025', 3, 'menetapkan', 'Menetapkan', NULL, 1, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG RENCANA NASIONAL PENANGGULANGAN BENCANA TAHUN 2025-2029.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2110, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG RENCANA NASIONAL PENANGGULANGAN BENCANA TAHUN 2025-2029.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2111, 'perban-1-2025', 4, 'pasal', 'Pasal 1', NULL, 2, 'Dalam Peraturan Badan ini, yang dimaksud dengan:
1. Rencana Induk Penanggulangan Bencana Tahun 2020- 2044 yang selanjutnya disebut RIPB Tahun 2020-2044 adalah pedoman nasional penyelenggaraan penanggulangan bencana.
2. Rencana Nasional Penanggulangan Bencana yang selanjutnya disebut RENAS PB adalah rencana umum dan menyeluruh yang disusun berdasarkan hasil pengkajian risiko bencana dan penanggulangan bencana yang dijabarkan dalam program kegiatan penanggulangan bencana dan rincian anggarannya.
3. Fokus Capaian adalah sasaran prioritas RIPB Tahun 2020- 2044 yang harus dicapai dalam penyelenggaraan penanggulangan bencana dalam rentang waktu 5 (lima) tahunan.
4. Resiliensi Berkelanjutan adalah pendekatan yang bertujuan untuk meningkatkan resiliensi dan daya lenting masyarakat terhadap risiko bencana dan dampak perubahan iklim yang berlandaskan penguatan budaya kesiapsiagaan, inovasi dalam ilmu pengetahuan, teknologi, dan akses pendanaan untuk mendukung penanggulangan bencana, pembangunan infrastruktur yang tangguh terhadap perubahan iklim dan bencana, integrasi perubahan iklim, pengurangan risiko bencana, dan pembangunan berkelanjutan yang dapat dilaksanakan secara terpadu di tingkat nasional dan daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2111, 'Dalam Peraturan Badan ini, yang dimaksud dengan:
1. Rencana Induk Penanggulangan Bencana Tahun 2020- 2044 yang selanjutnya disebut RIPB Tahun 2020-2044 adalah pedoman nasional penyelenggaraan penanggulangan bencana.
2. Rencana Nasional Penanggulangan Bencana yang selanjutnya disebut RENAS PB adalah rencana umum dan menyeluruh yang disusun berdasarkan hasil pengkajian risiko bencana dan penanggulangan bencana yang dijabarkan dalam program kegiatan penanggulangan bencana dan rincian anggarannya.
3. Fokus Capaian adalah sasaran prioritas RIPB Tahun 2020- 2044 yang harus dicapai dalam penyelenggaraan penanggulangan bencana dalam rentang waktu 5 (lima) tahunan.
4. Resiliensi Berkelanjutan adalah pendekatan yang bertujuan untuk meningkatkan resiliensi dan daya lenting masyarakat terhadap risiko bencana dan dampak perubahan iklim yang berlandaskan penguatan budaya kesiapsiagaan, inovasi dalam ilmu pengetahuan, teknologi, dan akses pendanaan untuk mendukung penanggulangan bencana, pembangunan infrastruktur yang tangguh terhadap perubahan iklim dan bencana, integrasi perubahan iklim, pengurangan risiko bencana, dan pembangunan berkelanjutan yang dapat dilaksanakan secara terpadu di tingkat nasional dan daerah.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2112, 'perban-1-2025', 5, 'pasal', 'Pasal 2', NULL, 2, '(1) Dalam rangka peningkatan tata kelola penanggulangan bencana mewujudkan Resiliensi Berkelanjutan secara nasional ditetapkan RENAS PB.
(2) RENAS PB sebagaimana dimaksud pada ayat (1) ditetapkan untuk tahun 2025-2029.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2112, '(1) Dalam rangka peningkatan tata kelola penanggulangan bencana mewujudkan Resiliensi Berkelanjutan secara nasional ditetapkan RENAS PB.
(2) RENAS PB sebagaimana dimaksud pada ayat (1) ditetapkan untuk tahun 2025-2029.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2113, 'perban-1-2025', 6, 'pasal', 'Pasal 3', NULL, 2, '(1) RENAS PB Tahun 2025-2029 sebagaimana dimaksud dalam Pasal 2 ayat (2) merupakan dokumen perencanaan dalam rangka pelaksanaan RIPB Tahun 2020-2044.
(2) RENAS PB Tahun 2025-2029 sebagaimana dimaksud dalam ayat (1) memperhatikan Fokus Capaian 2025-2029 pada RIPB Tahun 2020-2044.
(3) Fokus Capaian 2025-2029 pada RIPB Tahun 2020-2044 sebagaimana dimaksud pada ayat (2) terdiri atas:
a. terwujudnya peraturan perundang-undangan yang harmonis di bidang penanggulangan bencana;
b. terwujudnya kemandirian teknologi dan industrialisasi kebencanaan;
c. terwujudnya kemudahan akses layanan peringatan dini terpadu multi ancaman;
d. terwujudnya investasi yang memadai dalam pengurangan risiko bencana untuk ketangguhan;
e. terwujudnya tata kelola risiko bencana yang sinergis antara pusat dan daerah;
f. terwujudnya pemahaman terhadap risiko bencana, bentang alam, dan adaptasi perubahan iklim, serta ketahanan sosial dan ketahanan kesehatan masyarakat;
g. terwujudnya penanganan darurat bencana secara cepat, efektif, dan terkoordinasi;
h. terwujudnya penataan ruang dan permukiman serta perencanaan perkotaan yang terpadu terhadap ketahanan bencana dan adaptasi perubahan iklim, serta ketahanan sosial, dan ketahanan kesehatan masyarakat;
i. terwujudnya pelindungan ekosistem laut dan pesisir yang berisiko bencana;
j. tersedianya sumber daya manusia yang memiliki keahlian dan profesional di bidang kebencanaan;
k. terwujudnya pemulihan daerah terdampak bencana yang lebih baik, aman, dan berkelanjutan dengan memperhatikan pengurangan risiko bencana; dan
l. terwujudnya infrastruktur yang berkualitas, andal, serta berkelanjutan dan tangguh bencana.
(4) RENAS PB Tahun 2025-2029 meliputi:
a. pengenalan dan pengkajian ancaman bencana;
b. pemahaman tentang kerentanan masyarakat;
c. analisis kemungkinan dampak bencana;
d. pilihan tindakan pengurangan risiko bencana;
e. penentuan mekanisme kesiapan dan penanggulangan dampak bencana; dan
f. alokasi tugas, kewenangan, dan sumber daya yang tersedia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2113, '(1) RENAS PB Tahun 2025-2029 sebagaimana dimaksud dalam Pasal 2 ayat (2) merupakan dokumen perencanaan dalam rangka pelaksanaan RIPB Tahun 2020-2044.
