INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2138, 'perban-1-2025', 31, 'lampiran', 'Lampiran hal. 14', NULL, 14, '3. Penguatan investasi a. Melaksanakan dan risiko bencana, bentang pengelolaan risiko mengembangkan program alam, dan adaptasi bencana sesuai kesiapsiagaan dan perubahan iklim, serta dengan proyeksi pengelolaan risiko bencana ketahanan sosial dan peningkatan risiko dengan memperhatikan ketahanan Kesehatan bencana dengan tata ruang dan penataan masyarakat. memperhatikan tata kawasan. ruang dan penataan b. Meningkatkan investasi 7. Terwujudnya kawasan dan pemanfaatan berbagai penanganan darurat skema pendanaan inovatif bencana secara cepat, termasuk transfer risiko efektif, dan untuk penanggulangan terkoordinasi. bencana.
