INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2139, 'perban-1-2025', 32, 'lampiran', 'Lampiran hal. 15', NULL, 15, 'c. Meningkatkan keterbukaan berisiko bencana. informasi dan komunikasi, kualitas sistem 10. Tersedianya sumber perencanaan, serta daya manusia yang pemantauan dan evaluasi memiliki keahlian dan dalam penanggulangan profesional di bidang bencana. kebencanaan.
