INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2140, 'perban-1-2025', 33, 'lampiran', 'Lampiran hal. 15', NULL, 15, '6. Percepatan a. Mengoptimalkan pemulihan perencanaan rehabilitasi pascabencana pada dan rekonstruksi FOKUS CAPAIAN 2025- KEBIJAKAN STRATEGI 2029 daerah dan pascabencana berdasarkan masyarakat tata ruang yang peka risiko terdampak bencana bencana. untuk membangun b. Meningkatkan kualitas kehidupan yang lebih penghidupan masyarakat baik. terdampak bencana yang lebih baik.
c. Mewujudkan infrastruktur, perumahan, dan permukiman berketahanan bencana.
d. Meningkatkan kualitas pemulihan sosial ekonomi, sumber daya alam, dan lingkungan hidup.
1.4. Masa Berlaku RENAS PB Tahun 2025-2029 merupakan bentuk pelaksanaan RIPB Tahun 2020-2044 yang berlaku untuk jangka waktu 5 (lima) tahun. Dokumen RENAS PB Tahun 2025-2029 dapat ditinjau secara berkala setiap 2 (dua) tahun sekali atau sewaktu-waktu jika terjadi bencana. Peninjauan kembali RENAS PB Tahun 2025-2029 didasarkan pada hasil pemantauan, pengendalian, dan evaluasi tahunan pelaksanaan RENAS PB Tahun 2025-2029.
BAB II TUJUAN, SASARAN, KEBIJAKAN DAN STRATEGI NASIONAL PENANGGULANGAN BENCANA TAHUN 2025-2029 RENAS PB Tahun 2025-2029 disusun dengan menggunakan pendekatan dan metode penyusunan rencana strategis yang menggabungkan dimensi teknokratik, atas-bawah (top-down), bawah-atas (bottom-up), dan partisipatif.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2140, '6. Percepatan a. Mengoptimalkan pemulihan perencanaan rehabilitasi pascabencana pada dan rekonstruksi FOKUS CAPAIAN 2025- KEBIJAKAN STRATEGI 2029 daerah dan pascabencana berdasarkan masyarakat tata ruang yang peka risiko terdampak bencana bencana. untuk membangun b. Meningkatkan kualitas kehidupan yang lebih penghidupan masyarakat baik. terdampak bencana yang lebih baik.
c. Mewujudkan infrastruktur, perumahan, dan permukiman berketahanan bencana.
d. Meningkatkan kualitas pemulihan sosial ekonomi, sumber daya alam, dan lingkungan hidup.
1.4. Masa Berlaku RENAS PB Tahun 2025-2029 merupakan bentuk pelaksanaan RIPB Tahun 2020-2044 yang berlaku untuk jangka waktu 5 (lima) tahun. Dokumen RENAS PB Tahun 2025-2029 dapat ditinjau secara berkala setiap 2 (dua) tahun sekali atau sewaktu-waktu jika terjadi bencana. Peninjauan kembali RENAS PB Tahun 2025-2029 didasarkan pada hasil pemantauan, pengendalian, dan evaluasi tahunan pelaksanaan RENAS PB Tahun 2025-2029.
BAB II TUJUAN, SASARAN, KEBIJAKAN DAN STRATEGI NASIONAL PENANGGULANGAN BENCANA TAHUN 2025-2029 RENAS PB Tahun 2025-2029 disusun dengan menggunakan pendekatan dan metode penyusunan rencana strategis yang menggabungkan dimensi teknokratik, atas-bawah (top-down), bawah-atas (bottom-up), dan partisipatif.', 'Lampiran hal. 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2141, 'perban-1-2025', 34, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'Dimensi teknokratik RENAS PB Tahun 2025-2029 tercerminkan dalam proses pengenalan dan pengkajian ancaman bencana, pemahaman tentang kerentanan masyarakat, dan analisis kemungkinan dampak bencana dengan memanfaatkan hasil Kajian Risiko Bencana Indonesia Tahun 2022-2026 dan Indeks Risiko Bencana Tahun 2020-2023. Selain itu, dimensi teknokratik ditunjukkan dengan perumusan permasalahan dan isu strategis dengan memanfaatkan hasil identifikasi akar masalah dalam penanggulangan bencana dari laporan, publikasi ilmiah, diskusi para ahli dan walidata, serta berbagai sumber lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2141, 'Dimensi teknokratik RENAS PB Tahun 2025-2029 tercerminkan dalam proses pengenalan dan pengkajian ancaman bencana, pemahaman tentang kerentanan masyarakat, dan analisis kemungkinan dampak bencana dengan memanfaatkan hasil Kajian Risiko Bencana Indonesia Tahun 2022-2026 dan Indeks Risiko Bencana Tahun 2020-2023. Selain itu, dimensi teknokratik ditunjukkan dengan perumusan permasalahan dan isu strategis dengan memanfaatkan hasil identifikasi akar masalah dalam penanggulangan bencana dari laporan, publikasi ilmiah, diskusi para ahli dan walidata, serta berbagai sumber lainnya.', 'Lampiran hal. 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2142, 'perban-1-2025', 35, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'RENAS PB Tahun 2025-2029 juga memanfaatkan pendekatan campuran atas-bawah (top-down) dan bawah-atas (bottom-up) untuk merumuskan tujuan, sasaran, kebijakan, strategi, dan rencana aksi penanggulangan bencana tahun 2025-2029. RENAS PB Tahun 2025-2029 merupakan implementasi dari RIPB Tahun 2020-2024 yang menjabarkan kebijakan dan strategi serta program dan kegiatan dalam jangka waktu 5 (lima) tahun. Oleh karena itu, secara atas-bawah (top-down), kebijakan dan strategi dalam RENAS PB Tahun 2025-2029 perlu dirumuskan dalam skala nasional sesuai dengan RIPB Tahun 2020-2044, Rencana Pembangunan Jangka Panjang Nasional 2025-2045, dan dalam skala internasional atau global dengan SDGs, dan SFDRR 2015-2030. RENAS PB Tahun 2025-2029 perlu juga untuk memiliki tujuan dan sasaran yang diselaraskan dengan sasaran SFDRR 2015-2030, tujuan dan sasaran RIPB 2020-2044, dan sasaran pembangunan dalam Rencana Pembangunan Jangka Panjang Nasional 2025-2045.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2142, 'RENAS PB Tahun 2025-2029 juga memanfaatkan pendekatan campuran atas-bawah (top-down) dan bawah-atas (bottom-up) untuk merumuskan tujuan, sasaran, kebijakan, strategi, dan rencana aksi penanggulangan bencana tahun 2025-2029. RENAS PB Tahun 2025-2029 merupakan implementasi dari RIPB Tahun 2020-2024 yang menjabarkan kebijakan dan strategi serta program dan kegiatan dalam jangka waktu 5 (lima) tahun. Oleh karena itu, secara atas-bawah (top-down), kebijakan dan strategi dalam RENAS PB Tahun 2025-2029 perlu dirumuskan dalam skala nasional sesuai dengan RIPB Tahun 2020-2044, Rencana Pembangunan Jangka Panjang Nasional 2025-2045, dan dalam skala internasional atau global dengan SDGs, dan SFDRR 2015-2030. RENAS PB Tahun 2025-2029 perlu juga untuk memiliki tujuan dan sasaran yang diselaraskan dengan sasaran SFDRR 2015-2030, tujuan dan sasaran RIPB 2020-2044, dan sasaran pembangunan dalam Rencana Pembangunan Jangka Panjang Nasional 2025-2045.', 'Lampiran hal. 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2143, 'perban-1-2025', 36, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'Proses penyusunan RENAS PB Tahun 2025-2029 juga telah menghasilkan identifikasi permasalahan dan rumusan isu strategis yang perlu direspon dalam 5 (lima) tahun ke depan. Secara bawah-atas (bottom-up), RENAS PB Tahun 2025- 2029 perlu untuk memiliki program dan kegiatan yang dapat menjadi solusi terhadap permasalahan yang muncul dan memiliki strategi untuk merespon isu strategi yang ada. Dimensi bawah-atas (bottom-up) juga melingkupi dimensi partisipatif dalam pengusulan aksi (program dan kegiatan) di tahun 2025-2029 yang diusulkan Kementerian/Lembaga, pakar/ahli, dan perwakilan nonpemerintah sebagai pilihan tindakan untuk pengurangan risiko bencana.
Sebagai bentuk pelaksanaan RIPB Tahun 2020-2044, maka RENAS PB Tahun 2025-2029 telah menetapkan tujuan dan sasaran penanggulangan bencana yang disertai dengan target dan indikator yang harus dicapai di tahun 2029. RENAS PB Tahun 2025-2029 juga menetapkan kebijakan penanggulangan bencana jangka menengah yang juga menjadi dasar perumusan strategi untuk mencapai sasaran. Strategi-strategi yang telah dirumuskan kemudian diturunkan menjadi program dan kegiatan yang pelaksanaannya menjadi tanggung jawab pemerintah, pemerintah daerah maupun nonpemerintah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2143, 'Proses penyusunan RENAS PB Tahun 2025-2029 juga telah menghasilkan identifikasi permasalahan dan rumusan isu strategis yang perlu direspon dalam 5 (lima) tahun ke depan. Secara bawah-atas (bottom-up), RENAS PB Tahun 2025- 2029 perlu untuk memiliki program dan kegiatan yang dapat menjadi solusi terhadap permasalahan yang muncul dan memiliki strategi untuk merespon isu strategi yang ada. Dimensi bawah-atas (bottom-up) juga melingkupi dimensi partisipatif dalam pengusulan aksi (program dan kegiatan) di tahun 2025-2029 yang diusulkan Kementerian/Lembaga, pakar/ahli, dan perwakilan nonpemerintah sebagai pilihan tindakan untuk pengurangan risiko bencana.
Sebagai bentuk pelaksanaan RIPB Tahun 2020-2044, maka RENAS PB Tahun 2025-2029 telah menetapkan tujuan dan sasaran penanggulangan bencana yang disertai dengan target dan indikator yang harus dicapai di tahun 2029. RENAS PB Tahun 2025-2029 juga menetapkan kebijakan penanggulangan bencana jangka menengah yang juga menjadi dasar perumusan strategi untuk mencapai sasaran. Strategi-strategi yang telah dirumuskan kemudian diturunkan menjadi program dan kegiatan yang pelaksanaannya menjadi tanggung jawab pemerintah, pemerintah daerah maupun nonpemerintah.', 'Lampiran hal. 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2144, 'perban-1-2025', 37, 'lampiran', 'Lampiran hal. 18', NULL, 18, 'Gambar 2.1 Kerangka Kebijakan, Strategi, dan Rencana Aksi RENAS PB Tahun 2025-2029 2.1. Indeks Risiko Bencana Capaian pelaksanaan penanggulangan bencana nasional saat ini dapat digambarkan dengan penurunan Indeks Risiko Bencana dari tahun 2015 hingga 2023 yang mempertimbangkan komponen bahaya (hazard), kerentanan (vulnerability), dan kapasitas (capacity) di masing-masing provinsi dan kabupaten/kota. Indeks risiko bencana rata-rata nasional tahun 2023 memiliki nilai sebesar 132,25.
Gambar 2.2 Indeks Risiko Bencana Rata-Rata Nasional Tahun 2015-2023 Hasil perhitungan indeks risiko bencana tahun 2023 menunjukkan bahwa terdapat 13 (tiga belas) provinsi yang berada pada risiko bencana tinggi dengan 3 (tiga) provinsi yang berisiko paling tinggi yaitu Sulawesi Barat, Maluku, dan Kepulauan Bangka Belitung. Sebanyak 25 provinsi berada pada kelas risiko bencana sedang dengan provinsi yang memiliki indeks risiko terendah pada kelas sedang adalah Daerah Khusus Ibukota Jakarta, Papua Pegunungan, dan Daerah Istimewa Yogyakarta.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2144, 'Gambar 2.1 Kerangka Kebijakan, Strategi, dan Rencana Aksi RENAS PB Tahun 2025-2029 2.1. Indeks Risiko Bencana Capaian pelaksanaan penanggulangan bencana nasional saat ini dapat digambarkan dengan penurunan Indeks Risiko Bencana dari tahun 2015 hingga 2023 yang mempertimbangkan komponen bahaya (hazard), kerentanan (vulnerability), dan kapasitas (capacity) di masing-masing provinsi dan kabupaten/kota. Indeks risiko bencana rata-rata nasional tahun 2023 memiliki nilai sebesar 132,25.
Gambar 2.2 Indeks Risiko Bencana Rata-Rata Nasional Tahun 2015-2023 Hasil perhitungan indeks risiko bencana tahun 2023 menunjukkan bahwa terdapat 13 (tiga belas) provinsi yang berada pada risiko bencana tinggi dengan 3 (tiga) provinsi yang berisiko paling tinggi yaitu Sulawesi Barat, Maluku, dan Kepulauan Bangka Belitung. Sebanyak 25 provinsi berada pada kelas risiko bencana sedang dengan provinsi yang memiliki indeks risiko terendah pada kelas sedang adalah Daerah Khusus Ibukota Jakarta, Papua Pegunungan, dan Daerah Istimewa Yogyakarta.', 'Lampiran hal. 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2145, 'perban-1-2025', 38, 'lampiran', 'Lampiran hal. 19', NULL, 19, 'Gambar 2.3 Peta Indeks Risiko Bencana Provinsi di Indonesia Tahun 2023 Dari perhitungan nilai indeks risiko bencana untuk kabupaten/kota menunjukkan bahwa terdapat 168 kabupaten/kota yang berada pada risiko bencana tinggi dan sebanyak 346 kabupaten/kota berada pada risiko bencana sedang. Lima kabupaten/kota yang memiliki nilai indeks risiko bencana tertinggi yaitu Kabupaten Mandailing Natal, Kabupaten Halmahera Selatan, Kabupaten Nias Utara, Kabupaten Nias, dan Kabupaten Maluku Barat Daya.
Sedangkan kabupaten/kota yang memiliki nilai risiko bencana terendah ialah Kota Administratif Jakarta Selatan, Kota Surakarta, Kabupaten Sigi, Kabupaten Administratif Kepulauan Seribu, dan Kabupaten Mamberamo Tengah.
Gambar 2.4 Peta Indeks Risiko Bencana Indonesia Tahun 2023 2.2. Hasil Pengkajian Risiko Bencana 2022-2026 Hasil pengkajian risiko bencana di Indonesia tahun 2022-2026 menunjukkan informasi terkait tingkat bahaya, tingkat kerugian, tingkat kapasitas, dan tingkat risiko masing-masing bahaya yang kemudian diklasifikasikan menjadi tingkat rendah, sedang, dan tinggi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2145, 'Gambar 2.3 Peta Indeks Risiko Bencana Provinsi di Indonesia Tahun 2023 Dari perhitungan nilai indeks risiko bencana untuk kabupaten/kota menunjukkan bahwa terdapat 168 kabupaten/kota yang berada pada risiko bencana tinggi dan sebanyak 346 kabupaten/kota berada pada risiko bencana sedang. Lima kabupaten/kota yang memiliki nilai indeks risiko bencana tertinggi yaitu Kabupaten Mandailing Natal, Kabupaten Halmahera Selatan, Kabupaten Nias Utara, Kabupaten Nias, dan Kabupaten Maluku Barat Daya.
Sedangkan kabupaten/kota yang memiliki nilai risiko bencana terendah ialah Kota Administratif Jakarta Selatan, Kota Surakarta, Kabupaten Sigi, Kabupaten Administratif Kepulauan Seribu, dan Kabupaten Mamberamo Tengah.
Gambar 2.4 Peta Indeks Risiko Bencana Indonesia Tahun 2023 2.2. Hasil Pengkajian Risiko Bencana 2022-2026 Hasil pengkajian risiko bencana di Indonesia tahun 2022-2026 menunjukkan informasi terkait tingkat bahaya, tingkat kerugian, tingkat kapasitas, dan tingkat risiko masing-masing bahaya yang kemudian diklasifikasikan menjadi tingkat rendah, sedang, dan tinggi.', 'Lampiran hal. 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2146, 'perban-1-2025', 39, 'lampiran', 'Lampiran hal. 20', NULL, 20, 'Seluruh provinsi di Indonesia memiliki kelas bahaya dengan tingkat risiko tinggi. Luas wilayah bahaya berbasis risiko multibahaya di Indonesia secara total sebesar 192.473.073 ha dengan luas bahaya di kelas risiko tertinggi mendominasi sekitar 65,32%. Provinsi Papua (sebelum pemecahan menjadi Daerah Otonom Baru), Provinsi Kalimantan Tengah, dan Provinsi Kalimantan Timur memiliki luas multibahaya tertinggi dan Provinsi Daerah Khusus Ibukota Jakarta memiliki luas multibahaya terendah. Persentas luas bahaya pada kelas risiko tinggi terbesar berada di Provinsi Bengkulu (94,76%), Provinsi Gorontalo (84,05%), dan Provinsi Aceh (83,36%).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2146, 'Seluruh provinsi di Indonesia memiliki kelas bahaya dengan tingkat risiko tinggi. Luas wilayah bahaya berbasis risiko multibahaya di Indonesia secara total sebesar 192.473.073 ha dengan luas bahaya di kelas risiko tertinggi mendominasi sekitar 65,32%. Provinsi Papua (sebelum pemecahan menjadi Daerah Otonom Baru), Provinsi Kalimantan Tengah, dan Provinsi Kalimantan Timur memiliki luas multibahaya tertinggi dan Provinsi Daerah Khusus Ibukota Jakarta memiliki luas multibahaya terendah. Persentas luas bahaya pada kelas risiko tinggi terbesar berada di Provinsi Bengkulu (94,76%), Provinsi Gorontalo (84,05%), dan Provinsi Aceh (83,36%).', 'Lampiran hal. 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2147, 'perban-1-2025', 40, 'lampiran', 'Lampiran hal. 21', NULL, 21, 'Tabel 2.1 Profil Luas Multibahaya Per Provinsi LUAS BAHAYA (HA) NO PROVINSI RENDAH SEDANG TINGGI TOTAL KELAS 1 ACEH 130.144 834.479 4.830.977 5.795.600 TINGGI 2 SUMATERA UTARA 162.002 1.924.570 5.213.320 7.299.893 TINGGI 3 SUMATERA BARAT 29.711 791.733 3.379.845 4.201.289 TINGGI 4 RIAU 112.474 2.211.036 6.378.856 8.702.366 TINGGI 5 JAMBI 79.049 1.637.545 3.289.222 5.005.816 TINGGI 6 SUMATERA 163.791 2.153.653 6.862.295 9.179.739 TINGGI SELATAN 7 BENGKULU 217 104.077 1.887.640 1.991.933 TINGGI 8 LAMPUNG 70.560 847.127 2.544.693 3.462.380 TINGGI 9 KEPULAUAN 48.012 517.070 1.077.324 1.642.406 TINGGI BANGKA BELITUNG 10 KEPULAUAN RIAU 113.499 378.045 324.297 815.842 TINGGI 11 DKI JAKARTA 33.438 45.100 88.647 167.184 TINGGI 12 JAWA BARAT 84.850 586.887 2.865.401 3.537.137 TINGGI 13 JAWA TENGAH 234.510 685.900 2.356.698 3.277.108 TINGGI 14 DAERAH 9.114 107.032 202.435 318.581 TINGGI ISTIMEWA YOGYAKARTA 15 JAWA TIMUR 279.961 1.181.208 3.318.743 4.779.912 TINGGI 16 BANTEN 18.779 236.701 710.812 966.292 TINGGI 17 BALI 30.833 189.114 358.058 578.006 TINGGI 18 NUSA TENGGARA 18.077 706.954 1.132.201 1.857.232 TINGGI BARAT 19 NUSA TENGGARA 42.492 1.213.381 3.486.580 4.742.453 TINGGI TIMUR 20 KALIMANTAN 832.438 6.587.237 7.315.376 14.735.050 TINGGI BARAT 21 KALIMANTAN 1.915.818 5.712.734 7.727.898 15.356.450 TINGGI TENGAH 22 KALIMANTAN 109.392 1.372.477 2.392.555 3.874.423 TINGGI SELATAN 23 KALIMANTAN 1.612.250 5.904.071 5.390.343 12.906.664 TINGGI TIMUR 24 KALIMANTAN 337.303 2.612.812');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2147, 'Tabel 2.1 Profil Luas Multibahaya Per Provinsi LUAS BAHAYA (HA) NO PROVINSI RENDAH SEDANG TINGGI TOTAL KELAS 1 ACEH 130.144 834.479 4.830.977 5.795.600 TINGGI 2 SUMATERA UTARA 162.002 1.924.570 5.213.320 7.299.893 TINGGI 3 SUMATERA BARAT 29.711 791.733 3.379.845 4.201.289 TINGGI 4 RIAU 112.474 2.211.036 6.378.856 8.702.366 TINGGI 5 JAMBI 79.049 1.637.545 3.289.222 5.005.816 TINGGI 6 SUMATERA 163.791 2.153.653 6.862.295 9.179.739 TINGGI SELATAN 7 BENGKULU 217 104.077 1.887.640 1.991.933 TINGGI 8 LAMPUNG 70.560 847.127 2.544.693 3.462.380 TINGGI 9 KEPULAUAN 48.012 517.070 1.077.324 1.642.406 TINGGI BANGKA BELITUNG 10 KEPULAUAN RIAU 113.499 378.045 324.297 815.842 TINGGI 11 DKI JAKARTA 33.438 45.100 88.647 167.184 TINGGI 12 JAWA BARAT 84.850 586.887 2.865.401 3.537.137 TINGGI 13 JAWA TENGAH 234.510 685.900 2.356.698 3.277.108 TINGGI 14 DAERAH 9.114 107.032 202.435 318.581 TINGGI ISTIMEWA YOGYAKARTA 15 JAWA TIMUR 279.961 1.181.208 3.318.743 4.779.912 TINGGI 16 BANTEN 18.779 236.701 710.812 966.292 TINGGI 17 BALI 30.833 189.114 358.058 578.006 TINGGI 18 NUSA TENGGARA 18.077 706.954 1.132.201 1.857.232 TINGGI BARAT 19 NUSA TENGGARA 42.492 1.213.381 3.486.580 4.742.453 TINGGI TIMUR 20 KALIMANTAN 832.438 6.587.237 7.315.376 14.735.050 TINGGI BARAT 21 KALIMANTAN 1.915.818 5.712.734 7.727.898 15.356.450 TINGGI TENGAH 22 KALIMANTAN 109.392 1.372.477 2.392.555 3.874.423 TINGGI SELATAN 23 KALIMANTAN 1.612.250 5.904.071 5.390.343 12.906.664 TINGGI TIMUR 24 KALIMANTAN 337.303 2.612.812', 'Lampiran hal. 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2148, 'perban-1-2025', 41, 'lampiran', 'Lampiran hal. 21', NULL, 21, '4.596.654 7.546.770 TINGGI UTARA 25 SULAWESI UTARA 4.160 422.859 962.045 1.389.064 TINGGI 26 SULAWESI 98.856 1.663.469 4.421.803 6.184.129 TINGGI TENGAH 27 SULAWESI 251.200 1.553.723 3.757.127 5.562.050 TINGGI SELATAN 28 SULAWESI 220.439 1.980.816 1.605.515 3.806.770 TINGGI TENGGARA 29 GORONTALO 190 179.366 946.151 1.125.707 TINGGI 30 SULAWESI BARAT 17.054 583.032 975.969 1.576.056 TINGGI 31 MALUKU 479.247 1.640.208 2.571.948 4.691.403 TINGGI 32 MALUKU UTARA 42.002 1.499.825 1.656.423 3.198.250 TINGGI 33 PAPUA BARAT 905.817 2.743.182 6.646.516 10.295.515 TINGGI 34 PAPUA 1.982.411 5.459.096 24.462.097 31.903.603 TINGGI NASIONAL 10.470.092 56.266.520 125.736.462 192.473.073 Sumber: Kajian Risiko Bencana Tahun 2022-2026 Jika dilihat per jenis bahaya, luas bahaya bencana geologis seperti gempabumi memiliki luas bahaya tertinggi dengan total untuk seluruh kelas risiko sebesar 192.473.068 ha. Untuk bencana hidrometeorologis, luas bahaya tertinggi berada pada bencana kebakaran hutan dan lahan (karhutla) dan kekeringan. Sedangkan untuk bencana non alam, luas bahaya tertinggi berada pada bencana epidemi wabah penyakit dan COVID-19. Bencana tanah longsor, banjir bandang, dan banjir memiliki luas bahaya terbesar pada kelas risiko tinggi dengan persentase sebesar 61,18%, 57,81%, dan 50,43%.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2148, '4.596.654 7.546.770 TINGGI UTARA 25 SULAWESI UTARA 4.160 422.859 962.045 1.389.064 TINGGI 26 SULAWESI 98.856 1.663.469 4.421.803 6.184.129 TINGGI TENGAH 27 SULAWESI 251.200 1.553.723 3.757.127 5.562.050 TINGGI SELATAN 28 SULAWESI 220.439 1.980.816 1.605.515 3.806.770 TINGGI TENGGARA 29 GORONTALO 190 179.366 946.151 1.125.707 TINGGI 30 SULAWESI BARAT 17.054 583.032 975.969 1.576.056 TINGGI 31 MALUKU 479.247 1.640.208 2.571.948 4.691.403 TINGGI 32 MALUKU UTARA 42.002 1.499.825 1.656.423 3.198.250 TINGGI 33 PAPUA BARAT 905.817 2.743.182 6.646.516 10.295.515 TINGGI 34 PAPUA 1.982.411 5.459.096 24.462.097 31.903.603 TINGGI NASIONAL 10.470.092 56.266.520 125.736.462 192.473.073 Sumber: Kajian Risiko Bencana Tahun 2022-2026 Jika dilihat per jenis bahaya, luas bahaya bencana geologis seperti gempabumi memiliki luas bahaya tertinggi dengan total untuk seluruh kelas risiko sebesar 192.473.068 ha. Untuk bencana hidrometeorologis, luas bahaya tertinggi berada pada bencana kebakaran hutan dan lahan (karhutla) dan kekeringan. Sedangkan untuk bencana non alam, luas bahaya tertinggi berada pada bencana epidemi wabah penyakit dan COVID-19. Bencana tanah longsor, banjir bandang, dan banjir memiliki luas bahaya terbesar pada kelas risiko tinggi dengan persentase sebesar 61,18%, 57,81%, dan 50,43%.', 'Lampiran hal. 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2149, 'perban-1-2025', 42, 'lampiran', 'Lampiran hal. 22', NULL, 22, 'Tabel 2.2 Profil Luas Bahaya Per Jenis Bahaya LUAS BAHAYA (HA) NO BAHAYA RENDAH SEDANG TINGGI TOTAL 1 GEMPABUMI 132.283.200 29.444.424 30.745.445 192.473.068 2 TSUNAMI 557.233 448.754 740.906 1.746.893 3 LETUSAN GUNUNGAPI 1.058.007 329.832 189.193 1.577.032 4 BANJIR 1.480.200 23.929.691 25.846.638 51.256.529 5 BANJIR BANDANG 789.417 1.344.408 2.924.409 5.058.235 6 KEKERINGAN 32.847.198 129.623.605 30.002.272 192.473.075 7 KEBAKARAN HUTAN DAN 49.172.301 53.653.433 25.457.756 128.283.490 LAHAN 8 TANAH LONGSOR 4.398.167 28.199.931 51.321.334 83.919.432 9 LIKUEFAKSI 10.920.768 12.494.813 457.325 23.872.906 10 CUACA EKSTRIM 70.476.227 36.231.674 32.502.005 139.209.905 11 GELOMBANG EKSTRIM 1.282.191 166.470 303.252 1.751.913 DAN ABRASI 12 COVID-19 187.857.435 3.433.775 1.181.863 192.473.073 13 EPIDEMI WABAH 190.870.008 1.217.305 385.762 192.473.075 PENYAKIT 14 KEGAGALAN TEKNOLOGI 179.546 3.794 3.600 186.940 Sumber: Kajian Risiko Bencana Tahun 2022-2026 Pengkajian kerentanan dilakukan terhadap potensi penduduk terpapar dan potensi kerugian. Secara total, potensi penduduk terpapar multibahaya ialah sebanyak 271.130.365 jiwa. Seluruh provinsi di Indonesia memiliki kelas risiko untuk kerentanan dari potensi penduduk terpapar. Provinsi Jawa Barat, Provinsi Jawa Tengah, dan Provinsi Jawa Timur memiliki jumlah potensi penduduk terbesar untuk multibahaya termasuk jumlah potensi penduduk terpapar pada kelompok rentan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2149, 'Tabel 2.2 Profil Luas Bahaya Per Jenis Bahaya LUAS BAHAYA (HA) NO BAHAYA RENDAH SEDANG TINGGI TOTAL 1 GEMPABUMI 132.283.200 29.444.424 30.745.445 192.473.068 2 TSUNAMI 557.233 448.754 740.906 1.746.893 3 LETUSAN GUNUNGAPI 1.058.007 329.832 189.193 1.577.032 4 BANJIR 1.480.200 23.929.691 25.846.638 51.256.529 5 BANJIR BANDANG 789.417 1.344.408 2.924.409 5.058.235 6 KEKERINGAN 32.847.198 129.623.605 30.002.272 192.473.075 7 KEBAKARAN HUTAN DAN 49.172.301 53.653.433 25.457.756 128.283.490 LAHAN 8 TANAH LONGSOR 4.398.167 28.199.931 51.321.334 83.919.432 9 LIKUEFAKSI 10.920.768 12.494.813 457.325 23.872.906 10 CUACA EKSTRIM 70.476.227 36.231.674 32.502.005 139.209.905 11 GELOMBANG EKSTRIM 1.282.191 166.470 303.252 1.751.913 DAN ABRASI 12 COVID-19 187.857.435 3.433.775 1.181.863 192.473.073 13 EPIDEMI WABAH 190.870.008 1.217.305 385.762 192.473.075 PENYAKIT 14 KEGAGALAN TEKNOLOGI 179.546 3.794 3.600 186.940 Sumber: Kajian Risiko Bencana Tahun 2022-2026 Pengkajian kerentanan dilakukan terhadap potensi penduduk terpapar dan potensi kerugian. Secara total, potensi penduduk terpapar multibahaya ialah sebanyak 271.130.365 jiwa. Seluruh provinsi di Indonesia memiliki kelas risiko untuk kerentanan dari potensi penduduk terpapar. Provinsi Jawa Barat, Provinsi Jawa Tengah, dan Provinsi Jawa Timur memiliki jumlah potensi penduduk terbesar untuk multibahaya termasuk jumlah potensi penduduk terpapar pada kelompok rentan.', 'Lampiran hal. 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
