INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2151, 'perban-1-2025', 44, 'lampiran', 'Lampiran hal. 22', NULL, 22, 'CACAT RENTAN 21 KALIMANTAN TENGAH 2.639.990 239.053 161.500 11.421 SEDANG 22 KALIMANTAN SELATAN 4.103.548 384.600 318.634 14.614 SEDANG 23 KALIMANTAN TIMUR 3.803.972 367.075 195.153 8.691 SEDANG 24 KALIMANTAN UTARA 692.239 69.666 46.967 2.312 SEDANG 25 SULAWESI UTARA 2.674.331 257.633 254.552 12.718 SEDANG 26 SULAWESI TENGAH 3.032.535 290.681 310.242 15.629 SEDANG 27 SULAWESI SELATAN 8.962.956 986.208 939.022 41.076 SEDANG 28 SULAWESI TENGGARA 2.617.230 271.164 307.512 13.559 SEDANG 29 GORONTALO 1.198.765 116.598 152.152 6.159 SEDANG 30 SULAWESI BARAT 1.436.323 152.913 140.901 8.187 SEDANG 31 MALUKU 1.875.506 168.129 187.157 10.288 SEDANG 32 MALUKU UTARA 1.315.732 110.127 84.809 8.701 SEDANG 33 PAPUA BARAT 1.150.081 90.451 107.335 4.310 SEDANG 34 PAPUA 4.190.249 230.582 488.314 14.363 SEDANG NASIONAL 271.130.365 28.208.985 27.413.330 957.980 Sumber: Kajian Risiko Bencana Tahun 2022-2026 Potensi kerugian multibahaya memiliki nilai yang relatif besar secara nasional dengan nilai total potensi kerugian fisik dan ekonomi sebesar 4.082.564.437 Juta Rupiah dan nilai potensi kerusakan lingkungan seluas 51.261.652 ha. Potensi kerugian fisik dan ekonomi tertinggi masih didominasi oleh provinsi yang berada di pulau Jawa dan di pulau lainnya berada di Provinsi Sumatera Utara, Provinsi Riau, dan Provinsi Sulawesi Selatan.');
