INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2153, 'perban-1-2025', 46, 'lampiran', 'Lampiran hal. 23', NULL, 23, '49.250.304 34.089.359 83.339.663 2.959.250 TINGGI 21 KALIMANTAN 28.263.113 24.460.345 52.723.458 4.985.133 TINGGI TENGAH 22 KALIMANTAN 39.485.999 21.272.926 60.758.925 687.372 TINGGI SELATAN 23 KALIMANTAN TIMUR 30.202.625 35.811.865 66.014.491 3.702.524 TINGGI 24 KALIMANTAN UTARA 6.498.116 11.346.909 17.845.025 2.774.075 TINGGI 25 SULAWESI UTARA 23.826.224 22.450.935 46.277.159 364.495 TINGGI 26 SULAWESI TENGAH 29.630.086 35.068.261 64.698.347 2.451.681 TINGGI 27 SULAWESI SELATAN 80.459.832 88.260.610 168.720.442 1.045.313 TINGGI POTENSI KERUGIAN POTENSI KERUGIAN FISIK & EKONOMI KERUSAKAN LINGKUNGAN NO PROVINSI KERUGIAN KERUGIAN TOTAL FISIK EKONOMI (JUTA LUAS (HA) KELAS (JUTA RUPIAH) (JUTA RUPIAH) RUPIAH) 28 SULAWESI 19.531.139 19.741.862 39.273.001 990.180 TINGGI TENGGARA 29 GORONTALO 12.731.472 14.003.098 26.734.570 413.387 TINGGI 30 SULAWESI BARAT 12.115.193 13.957.484 26.072.677 547.931 TINGGI 31 MALUKU 16.950.391 6.653.075 23.603.466 1.233.880 TINGGI 32 MALUKU UTARA 12.824.086 6.899.380 19.723.466 1.048.992 TINGGI 33 PAPUA BARAT 11.715.118 7.592.982 19.308.100 3.630.917 TINGGI 34 PAPUA 37.716.277 23.189.481 60.905.758 12.276.302 TINGGI NASIONAL 2.356.643.119 1.725.921.319 4.082.564.437 51.261.652 Sumber: Kajian Risiko Bencana Tahun 2022-2026 Bencana gempabumi memiliki potensi penduduk terpapar tertinggi pada kelompok bencana geologi dengan jumlah 272.405.410 jiwa. Untuk bencana hidrometeorologis didominasi oleh bencana kekeringan dan cuaca ekstrim.');
