INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2154, 'perban-1-2025', 47, 'lampiran', 'Lampiran hal. 24', NULL, 24, 'Sementara itu, pada bencana non alam, bencana COVID-19 dan epidemi dan wabah penyakit memiliki potensi penduduk terpapar sebesar 272.566.688 jiwa.
Tabel 2.5 Profil Potensi Penduduk Terpapar Per Jenis Bahaya POTENSI PENDUDUK TERPAPAR (JIWA) KELOMPOK RENTAN JUMLAH NO PROVINSI KELOMPOK PENDUDUK PENDUDUK PENDUDUK UMUR TERPAPAR MISKIN CACAT RENTAN 1 GEMPABUMI 272.405.410 28.208.985 27.413.330 957.980 2 TSUNAMI 5.341.282 543.028 610.525 27.354 3 LETUSAN GUNUNGAPI 5.864.711 649.712 675.532 24.620 4 BANJIR 113.829.496 11.617.114 10.585.891 359.128 5 BANJIR BANDANG 15.391.846 1.609.035 1.752.472 65.922 6 KEKERINGAN 272.564.439 28.208.985 27.413.330 957.980 7 TANAH LONGSOR 25.252.687 2.587.270 3.289.097 128.459 8 LIKUEFAKSI 86.689.779 8.939.959 8.656.035 296.088 9 CUACA EKSTRIM 255.437.799 26.672.958 25.483.084 875.124 10 GELOMBANG EKSTRIM 4.129.597 405.613 464.390 22.651 DAN ABRASI 11 COVID-19 272.566.688 28.208.985 27.413.330 957.980 12 EPIDEMI WABAH 272.566.688 28.208.985 27.413.330 957.980 PENYAKIT 13 KEGAGALAN 713.784 94.387 221.154 1.732 TEKNOLOGI Sumber: Kajian Risiko Bencana Tahun 2022-2026 Potensi kerugian fisik dan ekonomi bencana gempabumi mencapai 1.111.318.267 Juta Rupiah dan merupakan nilai terbesar untuk bencana geologi. Sedangkan untuk bencana hidrometeorlogis, bencana cuaca ekstrim dan banjir memiliki nilai yang relatif besar dibandingkan bencana lainnya.');
