INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2155, 'perban-1-2025', 48, 'lampiran', 'Lampiran hal. 24', NULL, 24, 'Untuk potensi kerusakan lingkungan, bencana kekeringan memiliki nilai potensi kerugian terbesar, yaitu seluas 35.020.682 ha.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2155, 'Untuk potensi kerusakan lingkungan, bencana kekeringan memiliki nilai potensi kerugian terbesar, yaitu seluas 35.020.682 ha.', 'Lampiran hal. 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2156, 'perban-1-2025', 49, 'lampiran', 'Lampiran hal. 24', NULL, 24, 'Tabel 2.6 Profil Potensi Kerugian Per Jenis Bahaya POTENSI KERUGIAN KERUSAKAN POTENSI KERUGIAN FISIK & EKONOMI LINGKUNGAN NO PROVINSI KERUGIAN KERUGIAN FISIK EKONOMI TOTAL LUAS (HA) (JUTA RUPIAH) (JUTA RUPIAH) 1 GEMPABUMI 654.610.827 456.707.439 1.111.318.267 - 2 TSUNAMI 33.224.432 9.753.990 42.978.422 29.943 3 LETUSAN GUNUNGAPI 3.589.410 8.459.281 12.048.691 193.541 4 BANJIR 526.654.209 480.264.971 1.006.919.180 4.225.236 POTENSI KERUGIAN KERUSAKAN POTENSI KERUGIAN FISIK & EKONOMI LINGKUNGAN NO PROVINSI KERUGIAN KERUGIAN FISIK EKONOMI TOTAL LUAS (HA) (JUTA RUPIAH) (JUTA RUPIAH) 5 BANJIR BANDANG 97.377.587 50.295.748 147.673.335 57.079 6 KEKERINGAN - 967.552.017 967.552.017 35.020.682 7 KEBAKARAN HUTAN DAN - 709.049.963 709.049.963 6.284.991 LAHAN 8 TANAH LONGSOR 180.831.903 515.194.074 696.025.976 7.685.637 9 LIKUEFAKSI 208.655.711 143.220.239 351.875.950 1.342.986 10 CUACA EKSTRIM 1.962.997.383 781.335.463 2.744.332.847 - 11 GELOMBANG EKSTRIM 18.365.352 3.259.579 21.624.931 50.503 DAN ABRASI 12 KEGAGALAN TEKNOLOGI 584.288 - 584.288 - Sumber: Hasil Kajian Risiko Bencana Tahun 2022-2026 Pengkajian risiko bencana multibahaya menggabungkan penilaian kelas bahaya, kerentanan, dan kelas kapasitas pada bencana multibahaya. Hasil pengkajian risiko tersebut menunjukkan bahwa kelas risiko untuk seluruh provinsi di Indonesia memiliki kelas risiko tinggi kecuali Provinsi Daerah Khusus Ibukota Jakarta.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2156, 'Tabel 2.6 Profil Potensi Kerugian Per Jenis Bahaya POTENSI KERUGIAN KERUSAKAN POTENSI KERUGIAN FISIK & EKONOMI LINGKUNGAN NO PROVINSI KERUGIAN KERUGIAN FISIK EKONOMI TOTAL LUAS (HA) (JUTA RUPIAH) (JUTA RUPIAH) 1 GEMPABUMI 654.610.827 456.707.439 1.111.318.267 - 2 TSUNAMI 33.224.432 9.753.990 42.978.422 29.943 3 LETUSAN GUNUNGAPI 3.589.410 8.459.281 12.048.691 193.541 4 BANJIR 526.654.209 480.264.971 1.006.919.180 4.225.236 POTENSI KERUGIAN KERUSAKAN POTENSI KERUGIAN FISIK & EKONOMI LINGKUNGAN NO PROVINSI KERUGIAN KERUGIAN FISIK EKONOMI TOTAL LUAS (HA) (JUTA RUPIAH) (JUTA RUPIAH) 5 BANJIR BANDANG 97.377.587 50.295.748 147.673.335 57.079 6 KEKERINGAN - 967.552.017 967.552.017 35.020.682 7 KEBAKARAN HUTAN DAN - 709.049.963 709.049.963 6.284.991 LAHAN 8 TANAH LONGSOR 180.831.903 515.194.074 696.025.976 7.685.637 9 LIKUEFAKSI 208.655.711 143.220.239 351.875.950 1.342.986 10 CUACA EKSTRIM 1.962.997.383 781.335.463 2.744.332.847 - 11 GELOMBANG EKSTRIM 18.365.352 3.259.579 21.624.931 50.503 DAN ABRASI 12 KEGAGALAN TEKNOLOGI 584.288 - 584.288 - Sumber: Hasil Kajian Risiko Bencana Tahun 2022-2026 Pengkajian risiko bencana multibahaya menggabungkan penilaian kelas bahaya, kerentanan, dan kelas kapasitas pada bencana multibahaya. Hasil pengkajian risiko tersebut menunjukkan bahwa kelas risiko untuk seluruh provinsi di Indonesia memiliki kelas risiko tinggi kecuali Provinsi Daerah Khusus Ibukota Jakarta.', 'Lampiran hal. 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2157, 'perban-1-2025', 50, 'lampiran', 'Lampiran hal. 25', NULL, 25, 'Tabel 2.7 Tingkat Risiko Bencana Multibahaya Per Provinsi TINGKAT TINGKAT TINGKAT KELAS NO PROVINSI BAHAYA KERENTANAN KAPASITAS RISIKO 1 ACEH TINGGI TINGGI SEDANG TINGGI 2 SUMATERA UTARA TINGGI TINGGI SEDANG TINGGI 3 SUMATERA BARAT TINGGI TINGGI SEDANG TINGGI 4 RIAU TINGGI TINGGI SEDANG TINGGI 5 JAMBI TINGGI TINGGI SEDANG TINGGI 6 SUMATERA SELATAN TINGGI TINGGI SEDANG TINGGI 7 BENGKULU TINGGI TINGGI SEDANG TINGGI 8 LAMPUNG TINGGI TINGGI SEDANG TINGGI 9 KEPULAUAN BANGKA TINGGI TINGGI RENDAH TINGGI BELITUNG 10 KEPULAUAN RIAU TINGGI TINGGI SEDANG TINGGI 11 DKI JAKARTA TINGGI TINGGI SEDANG RENDAH 12 JAWA BARAT TINGGI TINGGI SEDANG TINGGI 13 JAWA TENGAH TINGGI TINGGI TINGGI TINGGI 14 DAERAH ISTIMEWA TINGGI TINGGI SEDANG TINGGI YOGYAKARTA 15 JAWA TIMUR TINGGI TINGGI SEDANG TINGGI 16 BANTEN TINGGI TINGGI SEDANG TINGGI 17 BALI TINGGI TINGGI SEDANG TINGGI 18 NUSA TENGGARA BARAT TINGGI TINGGI SEDANG TINGGI 19 NUSA TENGGARA TIMUR TINGGI TINGGI SEDANG TINGGI 20 KALIMANTAN BARAT TINGGI TINGGI SEDANG TINGGI 21 KALIMANTAN TENGAH TINGGI TINGGI SEDANG TINGGI 22 KALIMANTAN SELATAN TINGGI TINGGI RENDAH TINGGI 23 KALIMANTAN TIMUR TINGGI TINGGI SEDANG TINGGI 24 KALIMANTAN UTARA TINGGI TINGGI SEDANG TINGGI 25 SULAWESI UTARA TINGGI SEDANG SEDANG TINGGI 26 SULAWESI TENGAH TINGGI TINGGI SEDANG TINGGI 27 SULAWESI SELATAN TINGGI TINGGI SEDANG TINGGI 28 SULAWESI TENGGARA TINGGI TINGGI SEDANG TINGGI 29 GORONTALO TINGGI TINGGI SEDANG TINGGI 30 SULAWESI BARAT TINGGI TINGGI SEDANG TINGGI 31 MALUKU TINGGI');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2157, 'Tabel 2.7 Tingkat Risiko Bencana Multibahaya Per Provinsi TINGKAT TINGKAT TINGKAT KELAS NO PROVINSI BAHAYA KERENTANAN KAPASITAS RISIKO 1 ACEH TINGGI TINGGI SEDANG TINGGI 2 SUMATERA UTARA TINGGI TINGGI SEDANG TINGGI 3 SUMATERA BARAT TINGGI TINGGI SEDANG TINGGI 4 RIAU TINGGI TINGGI SEDANG TINGGI 5 JAMBI TINGGI TINGGI SEDANG TINGGI 6 SUMATERA SELATAN TINGGI TINGGI SEDANG TINGGI 7 BENGKULU TINGGI TINGGI SEDANG TINGGI 8 LAMPUNG TINGGI TINGGI SEDANG TINGGI 9 KEPULAUAN BANGKA TINGGI TINGGI RENDAH TINGGI BELITUNG 10 KEPULAUAN RIAU TINGGI TINGGI SEDANG TINGGI 11 DKI JAKARTA TINGGI TINGGI SEDANG RENDAH 12 JAWA BARAT TINGGI TINGGI SEDANG TINGGI 13 JAWA TENGAH TINGGI TINGGI TINGGI TINGGI 14 DAERAH ISTIMEWA TINGGI TINGGI SEDANG TINGGI YOGYAKARTA 15 JAWA TIMUR TINGGI TINGGI SEDANG TINGGI 16 BANTEN TINGGI TINGGI SEDANG TINGGI 17 BALI TINGGI TINGGI SEDANG TINGGI 18 NUSA TENGGARA BARAT TINGGI TINGGI SEDANG TINGGI 19 NUSA TENGGARA TIMUR TINGGI TINGGI SEDANG TINGGI 20 KALIMANTAN BARAT TINGGI TINGGI SEDANG TINGGI 21 KALIMANTAN TENGAH TINGGI TINGGI SEDANG TINGGI 22 KALIMANTAN SELATAN TINGGI TINGGI RENDAH TINGGI 23 KALIMANTAN TIMUR TINGGI TINGGI SEDANG TINGGI 24 KALIMANTAN UTARA TINGGI TINGGI SEDANG TINGGI 25 SULAWESI UTARA TINGGI SEDANG SEDANG TINGGI 26 SULAWESI TENGAH TINGGI TINGGI SEDANG TINGGI 27 SULAWESI SELATAN TINGGI TINGGI SEDANG TINGGI 28 SULAWESI TENGGARA TINGGI TINGGI SEDANG TINGGI 29 GORONTALO TINGGI TINGGI SEDANG TINGGI 30 SULAWESI BARAT TINGGI TINGGI SEDANG TINGGI 31 MALUKU TINGGI', 'Lampiran hal. 25', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2158, 'perban-1-2025', 51, 'lampiran', 'Lampiran hal. 25', NULL, 25, 'TINGGI SEDANG TINGGI 32 MALUKU UTARA TINGGI TINGGI SEDANG TINGGI 33 PAPUA BARAT TINGGI TINGGI RENDAH TINGGI 34 PAPUA TINGGI TINGGI SEDANG TINGGI Sumber: Hasil Kajian Risiko Bencana Tahun 2022-2026 2.3. Permasalahan dan Isu Strategis Penanggulangan Bencana 2025-2029 Identifikasi permasalahan dalam penyusunan RENAS PB dilakukan dengan memetakan masalah pokok dan akar masalah yang dibahas melalui kelompok disuksi terfokus dengan Kementerian/Lembaga wali data ancaman bencana, kajian literatur, dan tinjauan terhadap dokumen terkait penanggulangan bencana. Permasalahan penanggulangan bencana yang telah dihimpun kemudian distrukturkan dalam kerangka tahapan penanggulangan bencana dan pengurangan risiko bencana. Hasil identifikasi permasalahan dari proses yang telah dilakukan tersebut ialah sebagai berikut.
A. Banyaknya Jumlah Penduduk Terdampak Bencana Belum optimalnya tindakan pengamanan, penyelamatan, dan pelindungan masyarakat.
1. Rendahnya pemahaman masyarakat terhadap risiko bencana
a. Belum optimalnya pendidikan dan edukasi kebencanaan bagi masyarakat di semua satuan pendidikan yang disebabkan oleh belum semua menerapkan satuan pendidikan aman bencana.
b. Belum optimalnya implementasi program ketangguhan masyarakat yang disebabkan oleh: (1) program ketangguhan masyarakat belum terintegrasi dan menjadi prioritas desa; dan (2) belum adanya data terintegrasi dari kegiatan ketangguhan masyarakat dari seluruh pihak (pemerintah dan non pemerintah).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2158, 'TINGGI SEDANG TINGGI 32 MALUKU UTARA TINGGI TINGGI SEDANG TINGGI 33 PAPUA BARAT TINGGI TINGGI RENDAH TINGGI 34 PAPUA TINGGI TINGGI SEDANG TINGGI Sumber: Hasil Kajian Risiko Bencana Tahun 2022-2026 2.3. Permasalahan dan Isu Strategis Penanggulangan Bencana 2025-2029 Identifikasi permasalahan dalam penyusunan RENAS PB dilakukan dengan memetakan masalah pokok dan akar masalah yang dibahas melalui kelompok disuksi terfokus dengan Kementerian/Lembaga wali data ancaman bencana, kajian literatur, dan tinjauan terhadap dokumen terkait penanggulangan bencana. Permasalahan penanggulangan bencana yang telah dihimpun kemudian distrukturkan dalam kerangka tahapan penanggulangan bencana dan pengurangan risiko bencana. Hasil identifikasi permasalahan dari proses yang telah dilakukan tersebut ialah sebagai berikut.
A. Banyaknya Jumlah Penduduk Terdampak Bencana Belum optimalnya tindakan pengamanan, penyelamatan, dan pelindungan masyarakat.
1. Rendahnya pemahaman masyarakat terhadap risiko bencana
a. Belum optimalnya pendidikan dan edukasi kebencanaan bagi masyarakat di semua satuan pendidikan yang disebabkan oleh belum semua menerapkan satuan pendidikan aman bencana.
b. Belum optimalnya implementasi program ketangguhan masyarakat yang disebabkan oleh: (1) program ketangguhan masyarakat belum terintegrasi dan menjadi prioritas desa; dan (2) belum adanya data terintegrasi dari kegiatan ketangguhan masyarakat dari seluruh pihak (pemerintah dan non pemerintah).', 'Lampiran hal. 25', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2159, 'perban-1-2025', 52, 'lampiran', 'Lampiran hal. 26', NULL, 26, 'c. Belum optimalnya bpenggunaan dana desa untuk program ketangguhan bencana masyarakat desa; dan
d. Belum optimalnya pelibatan kelompok rentan.
2. Belum optimalnya pemenuhan dan pemanfaatan sistem peringatan dini oleh masyarakat dan aparatur pemerintah
a. Belum optimalnya pengelolaan sistem peringatan dini dan sistem peringatan dini multibahaya yang disebabkan oleh (1) belum optimalnya integrasi sistem peringatan dini; dan (2) belum memadainya sarana prasarana pendukung peringatan dini bencana di daerah.
b. Belum optimalnya pendekatan dalam pemenuhan kebutuhan sistem peringatan dini yang diperlukan di setiap daerah rawan bencana.
c. Belum optimalnya diseminasi peringatan bencana untuk aksi dini
d. Belum optimalnya regulasi peringatan dini yang ada terutama untuk multi ancaman bencana.
3. Belum optimalnya penanggulangan kedaruratan bencana
a. Keterbatasan pemanfaatan sumber daya pemerintah daerah dalam melakukan kedaruratan bencana, yang disebabkan oleh:
(1) potensi ketidakjelasan akuntabilitas pemanfaatan dana Biaya Tidak Terduga (BTT) oleh pemerintah daerah; (2) pemerintah daerah belum memaksimalkan peranan lembaga usaha dan lembaga non-pemerintahan pada saat terjadi darurat bencana; dan (3) belum tersinkronisasinya pemahaman dan pengelolaan dana untuk penanganan darurat bencana yang bersumber dari Anggaran Pendapatan dan Belanja Daerah (BTT) dan Anggaran Pendapatan dan Belanja Negara (Dana Siap Pakai/DSP).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2159, 'c. Belum optimalnya bpenggunaan dana desa untuk program ketangguhan bencana masyarakat desa; dan
d. Belum optimalnya pelibatan kelompok rentan.
2. Belum optimalnya pemenuhan dan pemanfaatan sistem peringatan dini oleh masyarakat dan aparatur pemerintah
a. Belum optimalnya pengelolaan sistem peringatan dini dan sistem peringatan dini multibahaya yang disebabkan oleh (1) belum optimalnya integrasi sistem peringatan dini; dan (2) belum memadainya sarana prasarana pendukung peringatan dini bencana di daerah.
b. Belum optimalnya pendekatan dalam pemenuhan kebutuhan sistem peringatan dini yang diperlukan di setiap daerah rawan bencana.
c. Belum optimalnya diseminasi peringatan bencana untuk aksi dini
d. Belum optimalnya regulasi peringatan dini yang ada terutama untuk multi ancaman bencana.
3. Belum optimalnya penanggulangan kedaruratan bencana
a. Keterbatasan pemanfaatan sumber daya pemerintah daerah dalam melakukan kedaruratan bencana, yang disebabkan oleh:
(1) potensi ketidakjelasan akuntabilitas pemanfaatan dana Biaya Tidak Terduga (BTT) oleh pemerintah daerah; (2) pemerintah daerah belum memaksimalkan peranan lembaga usaha dan lembaga non-pemerintahan pada saat terjadi darurat bencana; dan (3) belum tersinkronisasinya pemahaman dan pengelolaan dana untuk penanganan darurat bencana yang bersumber dari Anggaran Pendapatan dan Belanja Daerah (BTT) dan Anggaran Pendapatan dan Belanja Negara (Dana Siap Pakai/DSP).', 'Lampiran hal. 26', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2160, 'perban-1-2025', 53, 'lampiran', 'Lampiran hal. 26', NULL, 26, 'b. Belum optimalnya pengelolaan situasi darurat bencana (tata kelola belum terencana, terpadu, terkoordinasi, efisien, dan efektif), yang disebabkan oleh: (1) belum adanya peraturan perundangan dan petunjuk pelaksanaan bagaimana operasional dan pembentukan Tim Reaksi Cepat Penanggulangan Bencana (TRC PB) multisektor; (2) regulasi manajemen standar logistik dan peralatan penanggulangan bencana untuk pemerintah daerah sudah tidak relevan; dan (3) kurang optimalnya koordinasi multisektor dalam penerapan Sistem Komando Penanganan Kedaruratan Bencana (SKPDB) pada saat darurat bencana.
c. Belum optimalnya kolaborasi dengan pihak non pemerintah dalam penyediaan logistik dan peralatan, yang disebabkan oleh:
(1) belum tersedianya sistem informasi logistik dan peralatannya yang dimutakhirkan untuk semua tahapan penanggulangan bencana; dan (2) perbedaan mengenai standar minimum bantuan kemanusiaan yang dimiliki oleh lembaga kebencanaan (Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Badan Perserikatan Bangsa-Bangsa, Lembaga Non Pemerintah, dan lain-lain) dengan lembaga usaha.
B. Banyaknya Kerusakan Fisik (Infrastruktur dan Bangunan) dan Lingkungan Akibat Bencana
1. Banyaknya bangunan dan infrastruktur dengan kelayakan bangunan rendah dan belum memiliki konstruksi tahan bencana dan perubahan iklim.
Lemahnya penerapan pembangunan berketahanan bencana dan iklim oleh masyarakat dan sektor swasta');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2160, 'b. Belum optimalnya pengelolaan situasi darurat bencana (tata kelola belum terencana, terpadu, terkoordinasi, efisien, dan efektif), yang disebabkan oleh: (1) belum adanya peraturan perundangan dan petunjuk pelaksanaan bagaimana operasional dan pembentukan Tim Reaksi Cepat Penanggulangan Bencana (TRC PB) multisektor; (2) regulasi manajemen standar logistik dan peralatan penanggulangan bencana untuk pemerintah daerah sudah tidak relevan; dan (3) kurang optimalnya koordinasi multisektor dalam penerapan Sistem Komando Penanganan Kedaruratan Bencana (SKPDB) pada saat darurat bencana.
c. Belum optimalnya kolaborasi dengan pihak non pemerintah dalam penyediaan logistik dan peralatan, yang disebabkan oleh:
(1) belum tersedianya sistem informasi logistik dan peralatannya yang dimutakhirkan untuk semua tahapan penanggulangan bencana; dan (2) perbedaan mengenai standar minimum bantuan kemanusiaan yang dimiliki oleh lembaga kebencanaan (Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Badan Perserikatan Bangsa-Bangsa, Lembaga Non Pemerintah, dan lain-lain) dengan lembaga usaha.
B. Banyaknya Kerusakan Fisik (Infrastruktur dan Bangunan) dan Lingkungan Akibat Bencana
1. Banyaknya bangunan dan infrastruktur dengan kelayakan bangunan rendah dan belum memiliki konstruksi tahan bencana dan perubahan iklim.
Lemahnya penerapan pembangunan berketahanan bencana dan iklim oleh masyarakat dan sektor swasta', 'Lampiran hal. 26', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2161, 'perban-1-2025', 54, 'lampiran', 'Lampiran hal. 27', NULL, 27, 'a. Rendahnya kemampuan masyarakat dalam melakukan pembangunan yang tahan bencana dan iklim yang disebabkan oleh: (1) rendahnya pemahaman dan pengetahuan masyarakat terhadap konstruksi tahan bencana dan iklim; (2) harga konstruksi dan material tahan bencana mahal; dan (3) rendahnya ketersediaan tenaga ahli bangunan gedung untuk konstruksi tahan bencana dan iklim.
b. Industri konstruksi dan real estate yang belum mendukung penyediaan infrastruktur bangunan tahan bencana, yang disebabkan oleh: (1) belum optimalnya pengawasan dan penegakan hukum terhadap perdagangan material yang tidak memenuhi SNI; (2) harga konstruksi dan material tahan bencana mahal; dan (3) rendahnya ketersediaan tenaga ahli bangunan gedung untuk konstruksi tahan bencana.
c. Belum optimalnya penegakan hukum (law enforcement) terkait pembangunan yang disebabkan oleh: (1) rendahnya ketersediaan sumber daya dalam pengawasan dan penertiban; (2) rendahnya pengawasan mutu baku bahan bangunan di pasaran; dan (3) belum optimalnya sosialisasi pemanfaatan informasi risiko bencana dalam kelayakan perizinan dan bangunan.
2. Tingginya Tingkat Kepadatan Penduduk di Lokasi dengan Tingkat Kerawanan Bencana Tinggi
a. Belum optimalnya pelaksanaan penataan ruang Belum seluruh daerah memiliki Rencana Tata Ruang Wilayah (RTRW) dan Rencana Detail Tata Ruang (RDTR) berbasis mitigasi bencana dan ketahanan iklim.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2161, 'a. Rendahnya kemampuan masyarakat dalam melakukan pembangunan yang tahan bencana dan iklim yang disebabkan oleh: (1) rendahnya pemahaman dan pengetahuan masyarakat terhadap konstruksi tahan bencana dan iklim; (2) harga konstruksi dan material tahan bencana mahal; dan (3) rendahnya ketersediaan tenaga ahli bangunan gedung untuk konstruksi tahan bencana dan iklim.
b. Industri konstruksi dan real estate yang belum mendukung penyediaan infrastruktur bangunan tahan bencana, yang disebabkan oleh: (1) belum optimalnya pengawasan dan penegakan hukum terhadap perdagangan material yang tidak memenuhi SNI; (2) harga konstruksi dan material tahan bencana mahal; dan (3) rendahnya ketersediaan tenaga ahli bangunan gedung untuk konstruksi tahan bencana.
c. Belum optimalnya penegakan hukum (law enforcement) terkait pembangunan yang disebabkan oleh: (1) rendahnya ketersediaan sumber daya dalam pengawasan dan penertiban; (2) rendahnya pengawasan mutu baku bahan bangunan di pasaran; dan (3) belum optimalnya sosialisasi pemanfaatan informasi risiko bencana dalam kelayakan perizinan dan bangunan.
2. Tingginya Tingkat Kepadatan Penduduk di Lokasi dengan Tingkat Kerawanan Bencana Tinggi
a. Belum optimalnya pelaksanaan penataan ruang Belum seluruh daerah memiliki Rencana Tata Ruang Wilayah (RTRW) dan Rencana Detail Tata Ruang (RDTR) berbasis mitigasi bencana dan ketahanan iklim.', 'Lampiran hal. 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2162, 'perban-1-2025', 55, 'lampiran', 'Lampiran hal. 27', NULL, 27, 'b. Belum optimalnya perencanaan program pembangunan berbasis mitigasi bencana dan ketahanan iklim 1) Belum optimalnya pengintegrasian kajian dan rencana penanggulangan bencana dalam perencanaan pembangunan yang disebabkan oleh: (1) belum tersedianya kajian risiko bencana di seluruh kabupaten/kota; dan (2) keterbatasan data dan informasi untuk menyusun kajian risiko bencana.
2) Belum teridentifikasinya zona sumber bahaya terbaru dan kawasan rawan bencana secara lengkap untuk ancaman bencana gempabumi, tsunami, dan kegagalan teknologi yang disebabkan oleh belum optimalnya pengembangan metode identifikasi potensi bahaya.
C. Tingginya Nilai Kerugian Ekonomi Akibat Bencana dan Kemampuan (Daya Lenting) Masyarakat untuk Pulih Kembali dari Bencana Memerlukan Waktu yang Cukup Lama
1. Meningkatnya kegiatan ekonomi (individu, sektor swasta, dan publik) di daerah risiko bencana tinggi.
a. Belum optimalnya pengembangan kawasan investasi berbasis mitigasi bencana dan ketahanan iklim.
Belum optimalnya penerapan persyaratan analisis risiko bencana untuk kegiatan investasi yang disebabkan oleh belum optimalnya dukungan regulasi untuk persyaratan analisis risiko bencana dalam perizinan berusaha.
b. Rendahnya pemanfaatan asuransi bencana bagi kegiatan ekonomi masyarakat Rendahnya motivasi pelaku usaha untuk memiliki asuransi perlindungan bencana yang disebabkan oleh rendahnya tingkat literasi pelaku usaha terhadap risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2162, 'b. Belum optimalnya perencanaan program pembangunan berbasis mitigasi bencana dan ketahanan iklim 1) Belum optimalnya pengintegrasian kajian dan rencana penanggulangan bencana dalam perencanaan pembangunan yang disebabkan oleh: (1) belum tersedianya kajian risiko bencana di seluruh kabupaten/kota; dan (2) keterbatasan data dan informasi untuk menyusun kajian risiko bencana.
2) Belum teridentifikasinya zona sumber bahaya terbaru dan kawasan rawan bencana secara lengkap untuk ancaman bencana gempabumi, tsunami, dan kegagalan teknologi yang disebabkan oleh belum optimalnya pengembangan metode identifikasi potensi bahaya.
C. Tingginya Nilai Kerugian Ekonomi Akibat Bencana dan Kemampuan (Daya Lenting) Masyarakat untuk Pulih Kembali dari Bencana Memerlukan Waktu yang Cukup Lama
1. Meningkatnya kegiatan ekonomi (individu, sektor swasta, dan publik) di daerah risiko bencana tinggi.
a. Belum optimalnya pengembangan kawasan investasi berbasis mitigasi bencana dan ketahanan iklim.
Belum optimalnya penerapan persyaratan analisis risiko bencana untuk kegiatan investasi yang disebabkan oleh belum optimalnya dukungan regulasi untuk persyaratan analisis risiko bencana dalam perizinan berusaha.
b. Rendahnya pemanfaatan asuransi bencana bagi kegiatan ekonomi masyarakat Rendahnya motivasi pelaku usaha untuk memiliki asuransi perlindungan bencana yang disebabkan oleh rendahnya tingkat literasi pelaku usaha terhadap risiko bencana.', 'Lampiran hal. 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2163, 'perban-1-2025', 56, 'lampiran', 'Lampiran hal. 28', NULL, 28, '2. Belum optimalnya pelaksanaan rehabilitasi dan rekonstruksi pascabencana
a. Belum optimalnya pemulihan fungsi pemerintahan dan pelayanan publik di daerah Belum optimalnya kapasitas pemerintah daerah dalam rehabilitasi dan rekonstruksi yang disebabkan oleh: (1) rendahnya pemahaman pemerintah daerah dalam perencanaan rehabilitasi dan rekonstruksi serta pengkajian kebutuhan pascabencana; dan (2) belum optimalnya penganggaran biaya perencanaan dan pengawasan oleh pemerintah daerah dalam pemanfaatan dana hibah rehabilitasi dan rekonstruksi.
b. Belum optimalnya pemberian bantuan perbaikan rumah bagi masyarakat Belum optimalnya pengelolaan bantuan perbaikan rumah yang belum optimal disebabkan oleh: (1) perbedaan instrumen penilaian tingkat kerusakan rumah; (2) belum adanya standardisasi, tipe, tipologi bantuan rumah hunian tetap untuk korban bencana; (3) belum adanya standardisasi dan prosedur bantuan rumah untuk korban bencana yang berasal dari Corporate Social Responsibility (CSR) dan sumber pendanaan non pemerintah lainnya; dan (4) belum adanya sistem pelaporan terpusat terhadap bantuan korban bencana yang dilakukan oleh Lembaga Non Pemerintah, CSR maupun sumber pembiayaan lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2163, '2. Belum optimalnya pelaksanaan rehabilitasi dan rekonstruksi pascabencana
a. Belum optimalnya pemulihan fungsi pemerintahan dan pelayanan publik di daerah Belum optimalnya kapasitas pemerintah daerah dalam rehabilitasi dan rekonstruksi yang disebabkan oleh: (1) rendahnya pemahaman pemerintah daerah dalam perencanaan rehabilitasi dan rekonstruksi serta pengkajian kebutuhan pascabencana; dan (2) belum optimalnya penganggaran biaya perencanaan dan pengawasan oleh pemerintah daerah dalam pemanfaatan dana hibah rehabilitasi dan rekonstruksi.
b. Belum optimalnya pemberian bantuan perbaikan rumah bagi masyarakat Belum optimalnya pengelolaan bantuan perbaikan rumah yang belum optimal disebabkan oleh: (1) perbedaan instrumen penilaian tingkat kerusakan rumah; (2) belum adanya standardisasi, tipe, tipologi bantuan rumah hunian tetap untuk korban bencana; (3) belum adanya standardisasi dan prosedur bantuan rumah untuk korban bencana yang berasal dari Corporate Social Responsibility (CSR) dan sumber pendanaan non pemerintah lainnya; dan (4) belum adanya sistem pelaporan terpusat terhadap bantuan korban bencana yang dilakukan oleh Lembaga Non Pemerintah, CSR maupun sumber pembiayaan lainnya.', 'Lampiran hal. 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2164, 'perban-1-2025', 57, 'lampiran', 'Lampiran hal. 28', NULL, 28, 'Isu strategis penanggulangan bencana dirumuskan sebagai permasalahan yang telah teridentifikasi dan diprediksi akan terjadi dalam jangka menengah ke depan. Isu strategis yang dirumuskan juga meliputi tantangan dan peluang baik di tingkat nasional dan global dalam konteks penanggulangan bencana maupun pembangunan secara umum yang perlu direspon melalui kebijakan dan strategi serta rencana aksi pada 5 (lima) tahun ke depan. Isu strategi penanggulangan bencana 2025-2029 dirumuskan sebagai berikut:
1. Meningkatnya Potensi Dampak dan Risiko Bencana Geologi Peningkatan potensi dampak dan risiko bencana geologi di Indonesia terlihat dari data Sumber dan Bahaya Gempa Indonesia 2017 yang menunjukkan jumlah sesar atau patahan aktif meningkat menjadi 295, termasuk penambahan di zona laut dan darat Pulau Jawa. Subduksi selatan Jawa menunjukkan tiga lokasi seismic gap yang berpotensi memicu gempa dengan kekuatan hingga magnitudo 9 atau lebih, berpotensi menimbulkan tsunami. Jumlah penduduk terdampak gempa tertinggi ada di Jawa dan Bali, dengan analisis kerugian fisik mencakup fasilitas umum.
Ancaman tsunami tinggi tersebar di hampir seluruh wilayah pantai Indonesia, dengan proyeksi kenaikan jumlah populasi terdampak dan potensi kerugian fisik, ekonomi, serta kerusakan lingkungan meningkat dari 2015 hingga 2045. Selain itu, erupsi gunungapi di Indonesia juga memiliki dampak global dengan 70 gunungapi perlu mendapat perhatian khusus.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2164, 'Isu strategis penanggulangan bencana dirumuskan sebagai permasalahan yang telah teridentifikasi dan diprediksi akan terjadi dalam jangka menengah ke depan. Isu strategis yang dirumuskan juga meliputi tantangan dan peluang baik di tingkat nasional dan global dalam konteks penanggulangan bencana maupun pembangunan secara umum yang perlu direspon melalui kebijakan dan strategi serta rencana aksi pada 5 (lima) tahun ke depan. Isu strategi penanggulangan bencana 2025-2029 dirumuskan sebagai berikut:
1. Meningkatnya Potensi Dampak dan Risiko Bencana Geologi Peningkatan potensi dampak dan risiko bencana geologi di Indonesia terlihat dari data Sumber dan Bahaya Gempa Indonesia 2017 yang menunjukkan jumlah sesar atau patahan aktif meningkat menjadi 295, termasuk penambahan di zona laut dan darat Pulau Jawa. Subduksi selatan Jawa menunjukkan tiga lokasi seismic gap yang berpotensi memicu gempa dengan kekuatan hingga magnitudo 9 atau lebih, berpotensi menimbulkan tsunami. Jumlah penduduk terdampak gempa tertinggi ada di Jawa dan Bali, dengan analisis kerugian fisik mencakup fasilitas umum.
Ancaman tsunami tinggi tersebar di hampir seluruh wilayah pantai Indonesia, dengan proyeksi kenaikan jumlah populasi terdampak dan potensi kerugian fisik, ekonomi, serta kerusakan lingkungan meningkat dari 2015 hingga 2045. Selain itu, erupsi gunungapi di Indonesia juga memiliki dampak global dengan 70 gunungapi perlu mendapat perhatian khusus.', 'Lampiran hal. 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2165, 'perban-1-2025', 58, 'lampiran', 'Lampiran hal. 29', NULL, 29, '2. Meningkatnya Risiko dan Potensi Dampak Bencana Akibat Perubahan Iklim Perubahan iklim global, didorong oleh aktivitas manusia seperti pembakaran bahan bakar fosil dan penebangan hutan, meningkatkan potensi bencana hidrometeorologi di Indonesia. Badan Meteorologi, Klimatologi, dan Geofisika memperkirakan peningkatan hari hujan lebat dan suhu udara rata-rata yang lebih tinggi. Fenomena La Nina dan El Nino menunjukkan variabilitas yang tinggi, berkontribusi pada cuaca ekstrem dan bencana hidrometeorologi seperti banjir dan longsor. Data menunjukkan peningkatan frekuensi curah hujan ekstrem, terutama di Kalimantan Barat dan Papua. Kebakaran hutan dan lahan di provinsi Riau, Jambi, Sumatera Selatan, Kalimantan Tengah, Kalimantan Barat, dan Kalimantan Selatan juga meningkat. Peningkatan tinggi muka air laut juga dapat menyebabkan terjadinya perpindahan penduduk (displacement) di daerah Pantai dan pesisir, contohnya di beberapa wilayah pesisir pantai utara pulau Jawa. Perubahan iklim juga berdampak pada kesehatan manusia, meningkatkan penyakit yang ditularkan oleh vektor, air, dan makanan. Pertumbuhan penduduk dan urbanisasi yang tidak terkendali menambah kerentanan terhadap bencana.
3. Pertumbuhan Penduduk, Alih Fungsi Lahan, dan Percepatan Perkembangan Pusat-Pusat Pertumbuhan dan Kawasan Investasi Alih fungsi lahan di Indonesia, meskipun tren deforestasi menurun, masih mempengaruhi risiko bencana seperti banjir dan tanah longsor.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2165, '2. Meningkatnya Risiko dan Potensi Dampak Bencana Akibat Perubahan Iklim Perubahan iklim global, didorong oleh aktivitas manusia seperti pembakaran bahan bakar fosil dan penebangan hutan, meningkatkan potensi bencana hidrometeorologi di Indonesia. Badan Meteorologi, Klimatologi, dan Geofisika memperkirakan peningkatan hari hujan lebat dan suhu udara rata-rata yang lebih tinggi. Fenomena La Nina dan El Nino menunjukkan variabilitas yang tinggi, berkontribusi pada cuaca ekstrem dan bencana hidrometeorologi seperti banjir dan longsor. Data menunjukkan peningkatan frekuensi curah hujan ekstrem, terutama di Kalimantan Barat dan Papua. Kebakaran hutan dan lahan di provinsi Riau, Jambi, Sumatera Selatan, Kalimantan Tengah, Kalimantan Barat, dan Kalimantan Selatan juga meningkat. Peningkatan tinggi muka air laut juga dapat menyebabkan terjadinya perpindahan penduduk (displacement) di daerah Pantai dan pesisir, contohnya di beberapa wilayah pesisir pantai utara pulau Jawa. Perubahan iklim juga berdampak pada kesehatan manusia, meningkatkan penyakit yang ditularkan oleh vektor, air, dan makanan. Pertumbuhan penduduk dan urbanisasi yang tidak terkendali menambah kerentanan terhadap bencana.
3. Pertumbuhan Penduduk, Alih Fungsi Lahan, dan Percepatan Perkembangan Pusat-Pusat Pertumbuhan dan Kawasan Investasi Alih fungsi lahan di Indonesia, meskipun tren deforestasi menurun, masih mempengaruhi risiko bencana seperti banjir dan tanah longsor.', 'Lampiran hal. 29', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2166, 'perban-1-2025', 59, 'lampiran', 'Lampiran hal. 29', NULL, 29, 'Perkembangan pusat pertumbuhan dan kawasan investasi mendorong perubahan penggunaan lahan dan urbanisasi cepat, memberikan tekanan pada perkotaan dan meningkatkan risiko bencana. Peningkatan jumlah penduduk perkotaan mempengaruhi ketersediaan permukiman dan infrastruktur, sering menyebabkan urban sprawl dan penurunan kualitas lingkungan. Kawasan industri yang berkembang menghadapi tantangan perencanaan yang memadai untuk menghindari masalah lingkungan, kesehatan, dan keselamatan.
Pertumbuhan penduduk yang pesat dan peningkatan kepadatan penduduk di kawasan permukiman meningkatkan risiko bencana non alam seperti bencana kebakaran permukiman. Pertumbuhan dan migrasi penduduk juga mendorong peningkatan risiko epidemi dan wabah penyakit.
Peningkatan kegiatan industri termasuk industri yang memanfaatkan bahan minyak dan gas bumi, bahan kimia berbahaya, dan nuklir di hampir seluruh wilayah di Indonesia, meningkatkan potensi kejadian bencana gagal teknologi. Peningkatan risiko bencana gagal teknologi juga semakin meningkat dengan perkembangan kawasan permukiman dan pusat kegiatan ekonomi masyarakat yang tidak terkendali.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2166, 'Perkembangan pusat pertumbuhan dan kawasan investasi mendorong perubahan penggunaan lahan dan urbanisasi cepat, memberikan tekanan pada perkotaan dan meningkatkan risiko bencana. Peningkatan jumlah penduduk perkotaan mempengaruhi ketersediaan permukiman dan infrastruktur, sering menyebabkan urban sprawl dan penurunan kualitas lingkungan. Kawasan industri yang berkembang menghadapi tantangan perencanaan yang memadai untuk menghindari masalah lingkungan, kesehatan, dan keselamatan.
Pertumbuhan penduduk yang pesat dan peningkatan kepadatan penduduk di kawasan permukiman meningkatkan risiko bencana non alam seperti bencana kebakaran permukiman. Pertumbuhan dan migrasi penduduk juga mendorong peningkatan risiko epidemi dan wabah penyakit.
Peningkatan kegiatan industri termasuk industri yang memanfaatkan bahan minyak dan gas bumi, bahan kimia berbahaya, dan nuklir di hampir seluruh wilayah di Indonesia, meningkatkan potensi kejadian bencana gagal teknologi. Peningkatan risiko bencana gagal teknologi juga semakin meningkat dengan perkembangan kawasan permukiman dan pusat kegiatan ekonomi masyarakat yang tidak terkendali.', 'Lampiran hal. 29', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2167, 'perban-1-2025', 60, 'lampiran', 'Lampiran hal. 30', NULL, 30, '4. Potensi Kejadian Konflik Sosial Indonesia sebagai negara kepulauan dengan keanekaragaman etnis, agama, budaya, dan bahasa, memiliki tantangan besar dalam pengelolaan konflik sosial. Potensi konflik sosial di Indonesia dapat muncul akibat ketimpangan sosial dan ekonomi, isu etnis dan agama, pemanfaatan identitas politik, sengketa atas tanah dan sumber daya alam, migrasi masuk, dan lainnya.
Histori kejadian konflik di Indonesia di level mikro, meso, maupun makro dan tantangan kemajuan teknologi dan keterbukaan informasi meningkatkan potensi kejadian bencana akibat konflik sosial termasuk di jangka menengah ke depan. Tantangan semakin membesar dalam penanggulangan bencana akibat konflik sosial karena belum adanya sistem jaringan pengamatan potensi konflik sosial yang terpadu. Sistem jaringan pengamatan ini perlu untuk dimanfaatkan oleh pihak pemerintah, pemerintah daerah, Tentara Nasional Indonesia, maupun Kepolisian Negara Republik Indonesia dalam penanganan konflik sosial.
5. Belum Optimalnya Pemantauan, Evaluasi, dan Akuntabilitas Bidang Penanggulangan Bencana Pemantauan dan evaluasi upaya penanggulangan bencana yang dilakukan di setiap tahapan bencana baik di tingkat pusat maupun daerah penting dilakukan untuk menilai efektivitas kebijakan dan upaya tersebut dalam pengurangan risiko bencana. Pemantauan dan evaluasi serta pelaporannya juga penting dilakukan untuk meningkatkan akuntabilitas upaya penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2167, '4. Potensi Kejadian Konflik Sosial Indonesia sebagai negara kepulauan dengan keanekaragaman etnis, agama, budaya, dan bahasa, memiliki tantangan besar dalam pengelolaan konflik sosial. Potensi konflik sosial di Indonesia dapat muncul akibat ketimpangan sosial dan ekonomi, isu etnis dan agama, pemanfaatan identitas politik, sengketa atas tanah dan sumber daya alam, migrasi masuk, dan lainnya.
Histori kejadian konflik di Indonesia di level mikro, meso, maupun makro dan tantangan kemajuan teknologi dan keterbukaan informasi meningkatkan potensi kejadian bencana akibat konflik sosial termasuk di jangka menengah ke depan. Tantangan semakin membesar dalam penanggulangan bencana akibat konflik sosial karena belum adanya sistem jaringan pengamatan potensi konflik sosial yang terpadu. Sistem jaringan pengamatan ini perlu untuk dimanfaatkan oleh pihak pemerintah, pemerintah daerah, Tentara Nasional Indonesia, maupun Kepolisian Negara Republik Indonesia dalam penanganan konflik sosial.
5. Belum Optimalnya Pemantauan, Evaluasi, dan Akuntabilitas Bidang Penanggulangan Bencana Pemantauan dan evaluasi upaya penanggulangan bencana yang dilakukan di setiap tahapan bencana baik di tingkat pusat maupun daerah penting dilakukan untuk menilai efektivitas kebijakan dan upaya tersebut dalam pengurangan risiko bencana. Pemantauan dan evaluasi serta pelaporannya juga penting dilakukan untuk meningkatkan akuntabilitas upaya penanggulangan bencana.', 'Lampiran hal. 30', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2168, 'perban-1-2025', 61, 'lampiran', 'Lampiran hal. 30', NULL, 30, 'Pemantauan dan evaluasi, juga melingkupi pengawasan dan pelaporan pemerintah daerah dan pemerintahan pusat terhadap seluruh penanggulangan bencana sebagaimana diamanatkan Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Pengawasan dan pelaporan ini perlu untuk ditingkatkan dan dikelola dalam sistem informasi untuk mempermudah pengambilan keputusan berkaitan bencana.
Sistem informasi ini juga dibutuhkan tidak hanya untuk menjadi sarana pelaporan hasil pengawasan pemerintah, tetapi juga untuk melakukan pemantauan dan evaluasi pencapaian sasaran kinerja program dan kegiatan dalam rencana penanggulangan bencana. Selain itu, sistem informasi ini juga perlu untuk dibangun dalam mengakomodasi pelaporan capaian sasaran-sasaran dalam komitmen global, pengembangan metadata indikator penanggulangan bencana, dan pelaksanaan kegiatan penanggulangan bencana di berbagai tingkatan pemerintahan dan kontribusi pihak pemerintah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2168, 'Pemantauan dan evaluasi, juga melingkupi pengawasan dan pelaporan pemerintah daerah dan pemerintahan pusat terhadap seluruh penanggulangan bencana sebagaimana diamanatkan Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Pengawasan dan pelaporan ini perlu untuk ditingkatkan dan dikelola dalam sistem informasi untuk mempermudah pengambilan keputusan berkaitan bencana.
Sistem informasi ini juga dibutuhkan tidak hanya untuk menjadi sarana pelaporan hasil pengawasan pemerintah, tetapi juga untuk melakukan pemantauan dan evaluasi pencapaian sasaran kinerja program dan kegiatan dalam rencana penanggulangan bencana. Selain itu, sistem informasi ini juga perlu untuk dibangun dalam mengakomodasi pelaporan capaian sasaran-sasaran dalam komitmen global, pengembangan metadata indikator penanggulangan bencana, dan pelaksanaan kegiatan penanggulangan bencana di berbagai tingkatan pemerintahan dan kontribusi pihak pemerintah.', 'Lampiran hal. 30', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2169, 'perban-1-2025', 62, 'lampiran', 'Lampiran hal. 30', NULL, 30, '6. Kebutuhan Transformasi Tata Kelola Penanggulangan Bencana dan Kolaborasi Multi-Pihak Tata kelola penanggulangan bencana di Indonesia masih memiliki persoalan dan tantangan yang dihadapi terutama berkaitan dengan dukungan sistem regulasi, kelembagaan, pendanaan, dan kolaborasi multipihak. Transformasi tata kelola penanggulangan bencana ke depan dibutuhkan dalam berbagai hal seperti: penguatan kebijakan dan regulasi, peningkatan kapasitas sumber daya manusia, koordinasi antar lembaga; pemanfataan teknologi, informasi, dan inovasi; pemberdayaan masyarakat; dan penguatan pendanaan.
Transformasi tata kelola dalam penanggulangan bencana di Indonesia juga perlu didukung dengan kolaborasi multipihak di tingkat daerah, nasional, regional, maupun global. Kerjasama multipihak dalam bentuk kemitraan pengetahuan, pemanfaatan teknologi, pendanaan, termasuk pelaksanaan kegiatan. Kolaborasi multipihak juga perlu didorong untuk meningkatkan akses terhadap bantuan bencana dari masyarakat, lembaga usaha, lembaga internasional, maupun pihak lainnya.
7. Pengelolaan Satu Data dan Pemanfaatan Sistem Informasi Teknologi Kebencanaan Data terpadu dan pemanfaatan sistem informasi teknologi merupakan komoditas penting dalam tata kelola penanggulangan bencana ke depan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2169, '6. Kebutuhan Transformasi Tata Kelola Penanggulangan Bencana dan Kolaborasi Multi-Pihak Tata kelola penanggulangan bencana di Indonesia masih memiliki persoalan dan tantangan yang dihadapi terutama berkaitan dengan dukungan sistem regulasi, kelembagaan, pendanaan, dan kolaborasi multipihak. Transformasi tata kelola penanggulangan bencana ke depan dibutuhkan dalam berbagai hal seperti: penguatan kebijakan dan regulasi, peningkatan kapasitas sumber daya manusia, koordinasi antar lembaga; pemanfataan teknologi, informasi, dan inovasi; pemberdayaan masyarakat; dan penguatan pendanaan.
Transformasi tata kelola dalam penanggulangan bencana di Indonesia juga perlu didukung dengan kolaborasi multipihak di tingkat daerah, nasional, regional, maupun global. Kerjasama multipihak dalam bentuk kemitraan pengetahuan, pemanfaatan teknologi, pendanaan, termasuk pelaksanaan kegiatan. Kolaborasi multipihak juga perlu didorong untuk meningkatkan akses terhadap bantuan bencana dari masyarakat, lembaga usaha, lembaga internasional, maupun pihak lainnya.
7. Pengelolaan Satu Data dan Pemanfaatan Sistem Informasi Teknologi Kebencanaan Data terpadu dan pemanfaatan sistem informasi teknologi merupakan komoditas penting dalam tata kelola penanggulangan bencana ke depan.', 'Lampiran hal. 30', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2170, 'perban-1-2025', 63, 'lampiran', 'Lampiran hal. 31', NULL, 31, 'Indonesia telah mengimplementasikan pemanfaatan dan pengelolaan data terpadu melalui Peraturan Presiden Nomor 39 Tahun 2019 tentang Satu Data Indonesia. Badan Nasional Penanggulangan Bencana juga telah menerbitkan regulasi terkait pengelolaan data terpadu kebencanaan melalui Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2023 tentang Satu Data Bencana. Berbagai kebijakan di tingkat nasional dan sistem informasi teknologi juga telah tersedia di tingkat pusat untuk penanggulangan bencana.
Dalam jangka menengah ke depan pengelolaan data terpadu dan pemanfaatan sistem informasi teknologi masih menjadi tantangan terutama untuk untuk meningkatkan pemahaman risiko bencana dan pengambilan keputusan yang tepat. Persoalan dan tantangan terkait keterbukaan akses, integrasi data, interoprabilitas data, keamanan dan privasi, standardisasi data (ketersediaan dan kualitas data), serta peningkatan partisipasi para pihak masih dihadapi dan memerlukan solusi dalam jangka menengah ke depan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2170, 'Indonesia telah mengimplementasikan pemanfaatan dan pengelolaan data terpadu melalui Peraturan Presiden Nomor 39 Tahun 2019 tentang Satu Data Indonesia. Badan Nasional Penanggulangan Bencana juga telah menerbitkan regulasi terkait pengelolaan data terpadu kebencanaan melalui Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2023 tentang Satu Data Bencana. Berbagai kebijakan di tingkat nasional dan sistem informasi teknologi juga telah tersedia di tingkat pusat untuk penanggulangan bencana.
Dalam jangka menengah ke depan pengelolaan data terpadu dan pemanfaatan sistem informasi teknologi masih menjadi tantangan terutama untuk untuk meningkatkan pemahaman risiko bencana dan pengambilan keputusan yang tepat. Persoalan dan tantangan terkait keterbukaan akses, integrasi data, interoprabilitas data, keamanan dan privasi, standardisasi data (ketersediaan dan kualitas data), serta peningkatan partisipasi para pihak masih dihadapi dan memerlukan solusi dalam jangka menengah ke depan.', 'Lampiran hal. 31', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2171, 'perban-1-2025', 64, 'lampiran', 'Lampiran hal. 31', NULL, 31, '8. Kebutuhan Penguatan Kepemimpinan dan Peran Strategis Indonesia dalam Pengurangan Risiko Bencana di Tingkat Global Indonesia telah memiliki peran penting dalam upaya pengurangan risiko bencana global dengan peran kepemimpinannya dalam forum dan inisiatif internasional. Indonesia telah aktif berpartisipasi dalam United Nations Office for Disaster Risk Reduction (UNDRR) sejak 2009 hingga menjadi tuan rumah untuk Global Forum on Disaster Risk Reduction (GPDRR) ke-7 tanggal 23-28 Mei 2022 di Bali. Indonesia perlu memperkuat kapasitas diplomatik dalam menangani isu-isu pengurangan risiko bencana di tingkat global. Sebagai negara dengan tingkat kerentanan tinggi terhadap bencana, Indonesia memiliki pengalaman dan keahlian yang dapat dibagikan kepada negara-negara lain, terutama yang juga terletak di kawasan rawan bencana seperti ASEAN. Meningkatkan diplomasi bencana dan menjalin kerja sama yang lebih erat dengan negara-negara sahabat dapat membantu Indonesia memperkuat posisi strategis dalam forum internasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2171, '8. Kebutuhan Penguatan Kepemimpinan dan Peran Strategis Indonesia dalam Pengurangan Risiko Bencana di Tingkat Global Indonesia telah memiliki peran penting dalam upaya pengurangan risiko bencana global dengan peran kepemimpinannya dalam forum dan inisiatif internasional. Indonesia telah aktif berpartisipasi dalam United Nations Office for Disaster Risk Reduction (UNDRR) sejak 2009 hingga menjadi tuan rumah untuk Global Forum on Disaster Risk Reduction (GPDRR) ke-7 tanggal 23-28 Mei 2022 di Bali. Indonesia perlu memperkuat kapasitas diplomatik dalam menangani isu-isu pengurangan risiko bencana di tingkat global. Sebagai negara dengan tingkat kerentanan tinggi terhadap bencana, Indonesia memiliki pengalaman dan keahlian yang dapat dibagikan kepada negara-negara lain, terutama yang juga terletak di kawasan rawan bencana seperti ASEAN. Meningkatkan diplomasi bencana dan menjalin kerja sama yang lebih erat dengan negara-negara sahabat dapat membantu Indonesia memperkuat posisi strategis dalam forum internasional.', 'Lampiran hal. 31', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2172, 'perban-1-2025', 65, 'lampiran', 'Lampiran hal. 31', NULL, 31, 'Indonesia perlu untuk terus berperan aktif dalam forum internasional terkait pengurangan risiko bencana, baik di bawah naungan PBB maupun organisasi regional seperti ASEAN. Kepemimpinan Indonesia dibutuhkan untuk merumuskan kebijakan global terkait pengurangan risiko bencana dan perubahan iklim. Hal ini termasuk mendesak negara-negara besar untuk mengambil tanggung jawab lebih besar dalam mitigasi perubahan iklim dan pengurangan risiko bencana. Peran Indonesia juga dibutuhkan sebagai penghubungan antara negara negara berkembang dan negara maju juga termasuk mengintegrasikan pengurangan risiko bencana dalam kebijakan nasional dan komitmen global.
Untuk mewujudkan pengembangan pendekatan multipihak termasuk meningkatkan kerja sama internasional dalam pengurangan risiko bencana, di jangka menengah ke depan, penguatan kepemiminan dan peran strategis Indonesia masih sangat dibutuhkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2172, 'Indonesia perlu untuk terus berperan aktif dalam forum internasional terkait pengurangan risiko bencana, baik di bawah naungan PBB maupun organisasi regional seperti ASEAN. Kepemimpinan Indonesia dibutuhkan untuk merumuskan kebijakan global terkait pengurangan risiko bencana dan perubahan iklim. Hal ini termasuk mendesak negara-negara besar untuk mengambil tanggung jawab lebih besar dalam mitigasi perubahan iklim dan pengurangan risiko bencana. Peran Indonesia juga dibutuhkan sebagai penghubungan antara negara negara berkembang dan negara maju juga termasuk mengintegrasikan pengurangan risiko bencana dalam kebijakan nasional dan komitmen global.
Untuk mewujudkan pengembangan pendekatan multipihak termasuk meningkatkan kerja sama internasional dalam pengurangan risiko bencana, di jangka menengah ke depan, penguatan kepemiminan dan peran strategis Indonesia masih sangat dibutuhkan.', 'Lampiran hal. 31', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2173, 'perban-1-2025', 66, 'lampiran', 'Lampiran hal. 32', NULL, 32, '2.4. Tujuan dan Sasaran Rencana Nasional Penanggulangan Bencana Tahun 2025-2029 Dalam rancangan RENAS PB Tahun 2025-2029, dirumuskan bahwa tujuan utama dari upaya penanggulangan bencana di Indonesia adalah Meningkatkan Ketangguhan Bangsa dalam Mengelola Risiko Bencana Untuk Mewujudkan Resiliensi Berkelanjutan. Hal ini sejalan dengan amanat Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana maupun kerangka regulasi serta tujuan perencanaan di Indonesia yang tidak hanya memiliki tujuan pengelolaan risiko bencana dan membangun ketangguhan, namun juga menitikberatkan pada aspek keberlanjutan.
Gambar 2.5 Tujuan dan Sasaran RENAS PB Tahun 2025-2029 Tujuan RENAS PB Tahun 2025 ini diturunkan ke dalam 4 (empat) sasaran penanggulangan bencana yang masing-masing memiliki indikator dan target sebagaimana ditunjukkan dalam Tabel 2.8.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2173, '2.4. Tujuan dan Sasaran Rencana Nasional Penanggulangan Bencana Tahun 2025-2029 Dalam rancangan RENAS PB Tahun 2025-2029, dirumuskan bahwa tujuan utama dari upaya penanggulangan bencana di Indonesia adalah Meningkatkan Ketangguhan Bangsa dalam Mengelola Risiko Bencana Untuk Mewujudkan Resiliensi Berkelanjutan. Hal ini sejalan dengan amanat Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana maupun kerangka regulasi serta tujuan perencanaan di Indonesia yang tidak hanya memiliki tujuan pengelolaan risiko bencana dan membangun ketangguhan, namun juga menitikberatkan pada aspek keberlanjutan.
Gambar 2.5 Tujuan dan Sasaran RENAS PB Tahun 2025-2029 Tujuan RENAS PB Tahun 2025 ini diturunkan ke dalam 4 (empat) sasaran penanggulangan bencana yang masing-masing memiliki indikator dan target sebagaimana ditunjukkan dalam Tabel 2.8.', 'Lampiran hal. 32', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2174, 'perban-1-2025', 67, 'lampiran', 'Lampiran hal. 32', NULL, 32, 'Tabel 2.8 Sasaran, Indikator Sasaran, dan Target RENAS PB Tahun 2025-2029 SASARAN RENAS PROYEKSI TARGET PB TAHUN 2025- INDIKATOR SASARAN 2025 2029 2029 Sasaran 1 1.a Proporsi jumlah kematian 0,22 Menurun Mengurangi penduduk (dan hilang) Jumlah Penduduk akibat bencana per 100.000 Terdampak jiwa Bencana melalui Peningkatan 1.b Proporsi jumlah penduduk 2.643 Menurun Kualitas terdampak bencana per Kesiapsiagaan, 100.000 jiwa Peringatan Dini, dan 1.c Proporsi penduduk per 11.060 52.000 Penanggulangan 100.000 jiwa di daerah Kedaruratan berisiko bencana yang Bencana tercakup oleh informasi peringatan dini melalui pemerintah daerah atau melalui mekanisme diseminasi nasional Sasaran 2 2.a Penurunan Proporsi 0,137 0,135 Mengurangi Kerugian Ekonomi Langsung Dampak akibat bencana relatif Kerusakan dan terhadap PDB Kerugian Akibat SASARAN RENAS PROYEKSI TARGET PB TAHUN 2025- INDIKATOR SASARAN 2025 2029 2029 Bencana Melalui 2.b Penurunan Proporsi Nilai 0,004 0,003 Peningkatan Kerusakan Insfrastruktur Efektivitas Upaya akibat bencana relatif Pencegahan, terhadap Total Belanja APBN Mitigasi Bencana dan Ketahanan Iklim Sasaran 3 3.a Indeks Pemulihan 6,5 8 Meningkatkan Pascabencana Daya Lenting di Daerah Terdampak Melalui Peningkatan Kualitas Rehabilitasi dan Rekonstruksi Sasaran 4 4.a Persentase implementasi 87% 100 % Meningkatkan strategi pengurangan risiko Pelayanan dan bencana di level nasional (%) Kapasitas Penanggulangan 4.b Rata-rata persentase 12% 15% Bencana Melalui peningkatan nilai');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2174, 'Tabel 2.8 Sasaran, Indikator Sasaran, dan Target RENAS PB Tahun 2025-2029 SASARAN RENAS PROYEKSI TARGET PB TAHUN 2025- INDIKATOR SASARAN 2025 2029 2029 Sasaran 1 1.a Proporsi jumlah kematian 0,22 Menurun Mengurangi penduduk (dan hilang) Jumlah Penduduk akibat bencana per 100.000 Terdampak jiwa Bencana melalui Peningkatan 1.b Proporsi jumlah penduduk 2.643 Menurun Kualitas terdampak bencana per Kesiapsiagaan, 100.000 jiwa Peringatan Dini, dan 1.c Proporsi penduduk per 11.060 52.000 Penanggulangan 100.000 jiwa di daerah Kedaruratan berisiko bencana yang Bencana tercakup oleh informasi peringatan dini melalui pemerintah daerah atau melalui mekanisme diseminasi nasional Sasaran 2 2.a Penurunan Proporsi 0,137 0,135 Mengurangi Kerugian Ekonomi Langsung Dampak akibat bencana relatif Kerusakan dan terhadap PDB Kerugian Akibat SASARAN RENAS PROYEKSI TARGET PB TAHUN 2025- INDIKATOR SASARAN 2025 2029 2029 Bencana Melalui 2.b Penurunan Proporsi Nilai 0,004 0,003 Peningkatan Kerusakan Insfrastruktur Efektivitas Upaya akibat bencana relatif Pencegahan, terhadap Total Belanja APBN Mitigasi Bencana dan Ketahanan Iklim Sasaran 3 3.a Indeks Pemulihan 6,5 8 Meningkatkan Pascabencana Daya Lenting di Daerah Terdampak Melalui Peningkatan Kualitas Rehabilitasi dan Rekonstruksi Sasaran 4 4.a Persentase implementasi 87% 100 % Meningkatkan strategi pengurangan risiko Pelayanan dan bencana di level nasional (%) Kapasitas Penanggulangan 4.b Rata-rata persentase 12% 15% Bencana Melalui peningkatan nilai', 'Lampiran hal. 32', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2175, 'perban-1-2025', 68, 'lampiran', 'Lampiran hal. 32', NULL, 32, 'kerja sama Transformasi Tata resmi internasional terkait Kelola dan pengurangan risiko bencana Kolaborasi Multi- secara bilateral dan Pihak multilateral (Nilai Rp) 4.c Persentase penurunan nilai 1,2 % 1,2 % indeks risiko bencana (%) 2.5. Kebijakan, Strategi, dan Program Rencana Nasional Penaggulangan Bencana Tahun 2025-2029 Kebijakan Penanggulangan Bencana dalam RENAS PB Tahun 2025-2029 telah disusun dengan menurunkan kebijakan RIPB Tahun 2020-2044, fokus capaian RIPB di tahun 2025-2029 serta kebijakan dan pentahapan pertama Rencana Pembangunan Jangka Panjang Nasional periode 2025-2029. Kebijakan penanggulangan bencana yang telah dirumuskan dilakukan melalui strategi-strategi yang menjadi upaya untuk mencapai 4 (empat) sasaran penanggulangan bencana 2025-2029. Kebijakan ini juga dirumuskan untuk merespon isu strategis yang telah dirumuskan. Kebijakan RENAS PB Tahun 2025-2029 yang telah dirumuskan ialah sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2175, 'kerja sama Transformasi Tata resmi internasional terkait Kelola dan pengurangan risiko bencana Kolaborasi Multi- secara bilateral dan Pihak multilateral (Nilai Rp) 4.c Persentase penurunan nilai 1,2 % 1,2 % indeks risiko bencana (%) 2.5. Kebijakan, Strategi, dan Program Rencana Nasional Penaggulangan Bencana Tahun 2025-2029 Kebijakan Penanggulangan Bencana dalam RENAS PB Tahun 2025-2029 telah disusun dengan menurunkan kebijakan RIPB Tahun 2020-2044, fokus capaian RIPB di tahun 2025-2029 serta kebijakan dan pentahapan pertama Rencana Pembangunan Jangka Panjang Nasional periode 2025-2029. Kebijakan penanggulangan bencana yang telah dirumuskan dilakukan melalui strategi-strategi yang menjadi upaya untuk mencapai 4 (empat) sasaran penanggulangan bencana 2025-2029. Kebijakan ini juga dirumuskan untuk merespon isu strategis yang telah dirumuskan. Kebijakan RENAS PB Tahun 2025-2029 yang telah dirumuskan ialah sebagai berikut:', 'Lampiran hal. 32', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2176, 'perban-1-2025', 69, 'lampiran', 'Lampiran hal. 33', NULL, 33, '1. Penguatan Kerangka Regulasi untuk Mewujudkan Sistem Penanggulangan Bencana yang Efisien dan Efektif Kebijakan ini dilakukan melalui membangun sistem regulasi yang handal dan terpadu (sinkron) dalam mendukung kinerja sistem penanggulangan bencana. Pembangunan sistem regulasi, seperti peraturan perundang-undangan dan NSPK, dilakukan dengan penguatan regulasi yang telah ada maupun penyusunan regulasi baru untuk mendukung optimasi kinerja sistem penanggulangan bencana. Selain itu, pembangunan sistem regulasi juga dilakukan dengan pengarusutamaan kajian risiko bencana dan rencana penanggulangan bencana dalam rencana tata ruang, dan rencana pembangunan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2176, '1. Penguatan Kerangka Regulasi untuk Mewujudkan Sistem Penanggulangan Bencana yang Efisien dan Efektif Kebijakan ini dilakukan melalui membangun sistem regulasi yang handal dan terpadu (sinkron) dalam mendukung kinerja sistem penanggulangan bencana. Pembangunan sistem regulasi, seperti peraturan perundang-undangan dan NSPK, dilakukan dengan penguatan regulasi yang telah ada maupun penyusunan regulasi baru untuk mendukung optimasi kinerja sistem penanggulangan bencana. Selain itu, pembangunan sistem regulasi juga dilakukan dengan pengarusutamaan kajian risiko bencana dan rencana penanggulangan bencana dalam rencana tata ruang, dan rencana pembangunan.', 'Lampiran hal. 33', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2177, 'perban-1-2025', 70, 'lampiran', 'Lampiran hal. 34', NULL, 34, '2. Penguatan Kelembagaan, Pendanaan, dan Peningkatan Kolaborasi Multi-Pihak dalam Penanggulangan Bencana Kebijakan ini dilakukan melalui: (a) meningkatkan capaian penerapan SPM Sub Urusan bencana; (b) meningkatkan ketersediaan SDM yang memiliki keahlian dan profesional di bidang kebencanaan; (c) mengembangkan skema pendanaan inovatif dalam penanggulangan bencana; (d) meningkatkan kualitas pemantauan, pengendalian, dan evaluasi penanggulangan bencana, dan (e) meningkatkan advokasi Resiliensi Berkelanjutan di tingkat nasional dan global. Kebijakan ini juga dilakukan dengan memperkuat kolaborasi multi-pihak dalam pelaksanaan strategi di kebijakan lainnya, seperti untuk membangun ketangguhan masyarakat, menanggulangi kedaruratan bencana, melakukan pencegahan, mitigasi bencana, dan ketahanan iklim, juga mempercepat pelaksanaan rehabilitasi dan rekonstruksi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2177, '2. Penguatan Kelembagaan, Pendanaan, dan Peningkatan Kolaborasi Multi-Pihak dalam Penanggulangan Bencana Kebijakan ini dilakukan melalui: (a) meningkatkan capaian penerapan SPM Sub Urusan bencana; (b) meningkatkan ketersediaan SDM yang memiliki keahlian dan profesional di bidang kebencanaan; (c) mengembangkan skema pendanaan inovatif dalam penanggulangan bencana; (d) meningkatkan kualitas pemantauan, pengendalian, dan evaluasi penanggulangan bencana, dan (e) meningkatkan advokasi Resiliensi Berkelanjutan di tingkat nasional dan global. Kebijakan ini juga dilakukan dengan memperkuat kolaborasi multi-pihak dalam pelaksanaan strategi di kebijakan lainnya, seperti untuk membangun ketangguhan masyarakat, menanggulangi kedaruratan bencana, melakukan pencegahan, mitigasi bencana, dan ketahanan iklim, juga mempercepat pelaksanaan rehabilitasi dan rekonstruksi.', 'Lampiran hal. 34', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2178, 'perban-1-2025', 71, 'lampiran', 'Lampiran hal. 34', NULL, 34, '3. Penguatan Investasi Pengelolaan Risiko Bencana Kebijakan ini dilakukan melalui: (a) meningkatkan aksesibilitas layanan dan efektivitas pengelolaan sistem peringatan dini; (b) meningkatkan investasi publik dan lembaga usaha berketahanan bencana dan perubahan iklim; (c) meningkatkan pengembangan pusat pertumbuhan, perdesaan, dan kawasan investasi berketahanan bencana dan perubahan iklim; (d) meningkatkan kesesuaian tata ruang darat dan laut serta ketangguhan dan keandalan bangunan gedung; (e) meningkatkan pelindungan ekosistem laut dan pesisir yang berisiko bencana; dan (f) menciptakan lingkungan yang kondusif untuk menumbuhkembangkan industrialisasi kebencanaan.
4. Peningkatan Ketangguhan Masyarakat dan Lembaga Usaha dalam Menghadapi Bencana Kebijakan ini dilakukan melalui: (a) meningkatkan keterbukaan data dan informasi untuk ketangguhan masyarakat & lembaga usaha; (b) meningkatkan pemanfaatan skema perlindungan aset dan transfer risiko bencana oleh masyarakat dan lembaga usaha; dan (c) meningkatkan kolaborasi dalam membangun ketangguhan individu, keluarga, dan masyarakat.
5. Peningkatan Kapasitas dan Kapabilitas dalam Kesiapsiagaan dan Penanganan Kedaruratan Kebijakan ini dilakukan melalui: (a) meningkatkan investasi dan kapasitas sumber daya dalam kesiapsiagaan dan penanggulangan kedaruratan bencana; dan (b) meningkatkan kesiapan dan keandalan logistik serta peralatan untuk penanggulangan kedaruratan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2178, '3. Penguatan Investasi Pengelolaan Risiko Bencana Kebijakan ini dilakukan melalui: (a) meningkatkan aksesibilitas layanan dan efektivitas pengelolaan sistem peringatan dini; (b) meningkatkan investasi publik dan lembaga usaha berketahanan bencana dan perubahan iklim; (c) meningkatkan pengembangan pusat pertumbuhan, perdesaan, dan kawasan investasi berketahanan bencana dan perubahan iklim; (d) meningkatkan kesesuaian tata ruang darat dan laut serta ketangguhan dan keandalan bangunan gedung; (e) meningkatkan pelindungan ekosistem laut dan pesisir yang berisiko bencana; dan (f) menciptakan lingkungan yang kondusif untuk menumbuhkembangkan industrialisasi kebencanaan.
4. Peningkatan Ketangguhan Masyarakat dan Lembaga Usaha dalam Menghadapi Bencana Kebijakan ini dilakukan melalui: (a) meningkatkan keterbukaan data dan informasi untuk ketangguhan masyarakat & lembaga usaha; (b) meningkatkan pemanfaatan skema perlindungan aset dan transfer risiko bencana oleh masyarakat dan lembaga usaha; dan (c) meningkatkan kolaborasi dalam membangun ketangguhan individu, keluarga, dan masyarakat.
5. Peningkatan Kapasitas dan Kapabilitas dalam Kesiapsiagaan dan Penanganan Kedaruratan Kebijakan ini dilakukan melalui: (a) meningkatkan investasi dan kapasitas sumber daya dalam kesiapsiagaan dan penanggulangan kedaruratan bencana; dan (b) meningkatkan kesiapan dan keandalan logistik serta peralatan untuk penanggulangan kedaruratan bencana.', 'Lampiran hal. 34', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2179, 'perban-1-2025', 72, 'lampiran', 'Lampiran hal. 34', NULL, 34, '6. Peningkatan Kualitas Rehabilitasi dan Rekonstruksi Pascabencana Kebijakan ini dilakukan melalui: (a) meningkatkan kualitas perencanaan dan percepatan pelaksanaan rehabilitasi dan rekonstruksi pascabencana berbasis tata ruang dan pengurangan risiko bencana; dan (b) meningkatkan keterlibatan dan sinergi multipihak untuk mempercepat rehabilitasi dan rekonstruksi pasca bencana pada seluruh aspek secara efektif.
Setiap strategi penanggulangan bencana 2025-2029 yang menjadi upaya pencapaian sasaran RENAS PB Tahun 2025-2029 diturunkan menjadi program yang berisi kegiatan dalam rencana aksi yang harus dilaksanakan oleh K/L dan didukung pelaksanaannya oleh pemerintah daerah dan pihak lainnya. Sebagai bentuk operasionalisasi RIPB Tahun 2020-2044, strategi dan program dalam RENAS PB Tahun 2025-2029 juga menjadi bentuk upaya untuk mencapai fokus capaian RIPB Tahun 2020-2024 untuk tahun 2025-2029 dengan hubungan yang dapat dilihat sebagai berikut.
Tabel 2.9 Hubungan Sasaran, Strategi, dan Program RENAS PB Tahun 2025- 2029 dengan Fokus Capaian RIPB Tahun 2020-2044 SASARAN RENAS PB PROGRAM FOKUS CAPAIAN RIPB STRATEGI TAHUN 2025- TAHUN 2025-2029 2029 Sasaran 1 1.1 Meningkatkan 1.1.1 Pengembangan dan Fokus Capaian 3:
Mengurangi Aksesibilitas Pemanfaatan MHEWS Terwujudnya Jumlah Layanan dan kemudahan akses Penduduk Efektivitas layanan peringatan dini Terdampak Pengelolaan terpadu multi ancaman Bencana melalui Sistem 1.1.2 Penguatan Fokus Capaian 3:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2179, '6. Peningkatan Kualitas Rehabilitasi dan Rekonstruksi Pascabencana Kebijakan ini dilakukan melalui: (a) meningkatkan kualitas perencanaan dan percepatan pelaksanaan rehabilitasi dan rekonstruksi pascabencana berbasis tata ruang dan pengurangan risiko bencana; dan (b) meningkatkan keterlibatan dan sinergi multipihak untuk mempercepat rehabilitasi dan rekonstruksi pasca bencana pada seluruh aspek secara efektif.
Setiap strategi penanggulangan bencana 2025-2029 yang menjadi upaya pencapaian sasaran RENAS PB Tahun 2025-2029 diturunkan menjadi program yang berisi kegiatan dalam rencana aksi yang harus dilaksanakan oleh K/L dan didukung pelaksanaannya oleh pemerintah daerah dan pihak lainnya. Sebagai bentuk operasionalisasi RIPB Tahun 2020-2044, strategi dan program dalam RENAS PB Tahun 2025-2029 juga menjadi bentuk upaya untuk mencapai fokus capaian RIPB Tahun 2020-2024 untuk tahun 2025-2029 dengan hubungan yang dapat dilihat sebagai berikut.
Tabel 2.9 Hubungan Sasaran, Strategi, dan Program RENAS PB Tahun 2025- 2029 dengan Fokus Capaian RIPB Tahun 2020-2044 SASARAN RENAS PB PROGRAM FOKUS CAPAIAN RIPB STRATEGI TAHUN 2025- TAHUN 2025-2029 2029 Sasaran 1 1.1 Meningkatkan 1.1.1 Pengembangan dan Fokus Capaian 3:
Mengurangi Aksesibilitas Pemanfaatan MHEWS Terwujudnya Jumlah Layanan dan kemudahan akses Penduduk Efektivitas layanan peringatan dini Terdampak Pengelolaan terpadu multi ancaman Bencana melalui Sistem 1.1.2 Penguatan Fokus Capaian 3:', 'Lampiran hal. 34', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2180, 'perban-1-2025', 73, 'lampiran', 'Lampiran hal. 35', NULL, 35, 'Peningkatan Peringatan Implementasi Terwujudnya Kualitas Dini Pengamatan dan kemudahan akses Kesiapsiagaan, Diseminasi Peringatan layanan peringatan dini Peringatan Dini, Dini Bencana terpadu multi ancaman dan 1.2 Meningkatkan 1.2.1 Penguatan Fokus Capaian 7:
Penanggulangan Investasi dan Kesiapsiagaan dan Terwujudnya Kedaruratan Kapasitas Kesiagaan Menghadapi penanganan darurat Bencana Sumber Daya Kedaruratan Bencana bencana secara cepat, dalam dan Krisis Kesehatan efektif, dan terkoordinasi Kesiapsiagaan 1.2.2 Penguatan Sumber Daya Fokus Capaian 7: dan Untuk Operasi Terwujudnya Penanggulang Pencarian, Pertolongan, penanganan darurat an dan Evakuasi Korban bencana secara cepat, Kedaruratan Bencana efektif, dan terkoordinasi Bencana 1.2.3 Penguatan Kapasitas Fokus Capaian 7:
SDM dalam Terwujudnya Kesiapsiagaan dan penanganan darurat Penanganan bencana secara cepat, Kedaruratan efektif, dan terkoordinasi 1.2.4 Riset dan Fokus Capaian 7:
Pengembangan terkait Terwujudnya Peningkatan penanganan darurat Kesiapsiagaan Bencana bencana secara cepat, efektif, dan terkoordinasi 1.3 Meningkatkan 1.3.1 Pemenuhan Kebutuhan Fokus Capaian 7:');
