INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2181, 'perban-1-2025', 74, 'lampiran', 'Lampiran hal. 35', NULL, 35, 'Kesiapan dan Logistik dan Peralatan Terwujudnya Keandalan Kesiapsiagaan penanganan darurat Logistik Serta bencana secara cepat, Peralatan efektif, dan terkoordinasi Untuk Penanggulang 1.3.2 Pembangunan Gudang Fokus Capaian 7: an Logistik dan Peralatan Terwujudnya Kedaruratan penanganan darurat Bencana bencana secara cepat, efektif, dan terkoordinasi 1.3.3 Pengembangan Sistem Fokus Capaian 7:
Logistik dan Peralatan Terwujudnya Kebencanaan penanganan darurat bencana secara cepat, efektif, dan terkoordinasi 1.4 Meningkatkan 1.4.1 Pembangunan Satu Fokus Capaian 6:
Keterbukaan Data Bencana Terwujudnya Data dan Terintegrasi pemahaman terhadap Informasi risiko bencana, bentang untuk alam, dan adaptasi Ketangguhan perubahan iklim, serta Masyarakat ketahanan sosial dan dan Lembaga ketahanan Kesehatan Usaha masyarakat 1.4.2 Peningkatan Diseminasi Fokus Capaian 6:
Data dan Informasi Terwujudnya Kebencanaan Untuk pemahaman terhadap Masyarakat risiko bencana, bentang SASARAN RENAS PB PROGRAM FOKUS CAPAIAN RIPB STRATEGI TAHUN 2025- TAHUN 2025-2029 2029 alam, dan adaptasi perubahan iklim, serta ketahanan sosial dan ketahanan Kesehatan masyarakat Sasaran 2 2.1 Meningkatkan 2.1.1 Pengembangan Rumah Fokus Capaian 12:
Mengurangi Investasi Sakit dan Fasilitas Terwujudnya Dampak Publik dan Kesehatan Aman infrastruktur yang Kerusakan dan Lembaga Bencana berkualitas, andal, serta Kerugian Akibat Usaha berkelanjutan dan Bencana Melalui Berketahanan tangguh bencana.');
