INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2182, 'perban-1-2025', 75, 'lampiran', 'Lampiran hal. 36', NULL, 36, 'Peningkatan Bencana dan 2.1.2 Pembangunan Fasilitas Fokus Capaian 12:
Efektivitas Upaya Perubahan Publik Tangguh Terwujudnya Pencegahan, Iklim Bencana infrastruktur yang Mitigasi Bencana berkualitas, andal, serta dan Ketahanan berkelanjutan dan Iklim tangguh 2.1.3 Riset dan Fokus Capaian 2:
Pengembangan Terwujudnya Teknologi Infrastruktur kemandirian teknologi Tahan Bencana dan dan industrialisasi Perubahan Iklim kebencanaan 2.2 Meningkatkan 2.2.1 Pembangunan IKN Fokus Capaian 4:
Pengembanga Berketahanan Bencana Terwujudnya investasi n Pusat dan Perubahan Iklim yang memadai dalam Pertumbuhan, pengurangan risiko Perdesaan, bencana untuk dan Kawasan ketangguhan Investasi 2.2.2 Pengembangan Fokus Capaian 4:
Berketahanan Kawasan Perkotaan Terwujudnya investasi Bencana dan Berketahanan Bencana yang memadai dalam Perubahan dan Perubahan Iklim pengurangan risiko Iklim bencana untuk ketangguhan 2.2.3 Pengembangan Investasi Fokus Capaian 4: di Kawasan Strategis Terwujudnya investasi Ekonomi Berketahanan yang memadai dalam Bencana dan pengurangan risiko Perubahan Iklim bencana untuk ketangguhan 2.3 Meningkatkan 2.3.1 Peningkatan Fokus Capaian 8:');
