INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2183, 'perban-1-2025', 76, 'lampiran', 'Lampiran hal. 36', NULL, 36, 'Kesesuaian Kepatuhan/Kesesuaian Terwujudnya penataan Tata Ruang Tata Ruang ruang dan permukiman Darat dan serta perencanaan Laut Serta perkotaan yang terpadu Ketangguhan terhadap ketahanan dan Keandalan bencana dan adaptasi Bangunan perubahan iklim, serta Gedung ketahanan sosial, dan ketahanan kesehatan masyarakat 2.3.2 Peningkatan Kualitas Fokus Capaian 8:
Rencana Tata Ruang Terwujudnya penataan ruang dan permukiman serta perencanaan perkotaan yang terpadu terhadap ketahanan bencana dan adaptasi perubahan iklim, serta ketahanan sosial, dan ketahanan kesehatan masyarakat;
SASARAN RENAS PB PROGRAM FOKUS CAPAIAN RIPB STRATEGI TAHUN 2025- TAHUN 2025-2029 2029 2.3.3 Peningkatan Kualitas Fokus Capaian 8:
Pengelolaan DAS dan Terwujudnya penataan Hutan ruang dan permukiman serta perencanaan perkotaan yang terpadu terhadap ketahanan bencana dan adaptasi perubahan iklim, serta ketahanan sosial, dan ketahanan kesehatan masyarakat 2.3.4 Peningkatan Fokus Capaian 8:
