INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2184, 'perban-1-2025', 77, 'lampiran', 'Lampiran hal. 37', NULL, 37, 'Bencana Bangunan Pengaman Terwujudnya Pantai pelindungan ekosistem laut dan pesisir yang berisiko bencana 2.4.3 Peningkatan Partisipasi Fokus Capaian 9:
Masyarakat dalam Terwujudnya Pelindungan Ekosistem pelindungan ekosistem Laut dan Pesisir laut dan pesisir yang berisiko bencana 2.4.4 Peningkatan Mitigasi Fokus Capaian 9: dan Adaptasi Subsiden Terwujudnya Tanah pelindungan ekosistem laut dan pesisir yang berisiko bencana 2.5 Meningkatkan 2.5.1 Peningkatan Fokus Capaian 4:
Pemanfaatan Perlindungan Aset Terwujudnya investasi Skema Penghidupan yang memadai dalam Perlindungan Masyarakat Terhadap pengurangan risiko Aset dan Risiko Bencana bencana untuk Transfer Risiko ketangguhan Bencana oleh Masyarakat dan Lembaga Usaha Sasaran 3 3.1 Meningkatkan 3.1.1 Penguatan Kapasitas Fokus Capaian 11:
Meningkatkan Kualitas SDM Untuk Terwujudnya pemulihan Daya Lenting di Perencanaan Perencanaan daerah terdampak Daerah dan Rehabilitasi dan bencana yang lebih baik, Terdampak Percepatan Rekonstruksi aman, dan berkelanjutan Melalui Pelaksanaan dengan memperhatikan Peningkatan Rehabilitasi pengurangan risiko Kualitas dan bencana SASARAN RENAS PB PROGRAM FOKUS CAPAIAN RIPB STRATEGI TAHUN 2025- TAHUN 2025-2029 2029 Rehabilitasi dan Rekonstruksi 3.1.2 Percepatan Pelaksanaan Fokus Capaian 11:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2184, 'Bencana Bangunan Pengaman Terwujudnya Pantai pelindungan ekosistem laut dan pesisir yang berisiko bencana 2.4.3 Peningkatan Partisipasi Fokus Capaian 9:
Masyarakat dalam Terwujudnya Pelindungan Ekosistem pelindungan ekosistem Laut dan Pesisir laut dan pesisir yang berisiko bencana 2.4.4 Peningkatan Mitigasi Fokus Capaian 9: dan Adaptasi Subsiden Terwujudnya Tanah pelindungan ekosistem laut dan pesisir yang berisiko bencana 2.5 Meningkatkan 2.5.1 Peningkatan Fokus Capaian 4:
Pemanfaatan Perlindungan Aset Terwujudnya investasi Skema Penghidupan yang memadai dalam Perlindungan Masyarakat Terhadap pengurangan risiko Aset dan Risiko Bencana bencana untuk Transfer Risiko ketangguhan Bencana oleh Masyarakat dan Lembaga Usaha Sasaran 3 3.1 Meningkatkan 3.1.1 Penguatan Kapasitas Fokus Capaian 11:
Meningkatkan Kualitas SDM Untuk Terwujudnya pemulihan Daya Lenting di Perencanaan Perencanaan daerah terdampak Daerah dan Rehabilitasi dan bencana yang lebih baik, Terdampak Percepatan Rekonstruksi aman, dan berkelanjutan Melalui Pelaksanaan dengan memperhatikan Peningkatan Rehabilitasi pengurangan risiko Kualitas dan bencana SASARAN RENAS PB PROGRAM FOKUS CAPAIAN RIPB STRATEGI TAHUN 2025- TAHUN 2025-2029 2029 Rehabilitasi dan Rekonstruksi 3.1.2 Percepatan Pelaksanaan Fokus Capaian 11:', 'Lampiran hal. 37', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2185, 'perban-1-2025', 78, 'lampiran', 'Lampiran hal. 38', NULL, 38, 'Rekonstruksi Pascabencana Rehabilitasi dan Terwujudnya pemulihan Berbasis Tata Rekonstruksi daerah terdampak Ruang dan bencana yang lebih baik, Pengurangan aman, dan berkelanjutan Risiko dengan memperhatikan Bencana pengurangan risiko bencana 3.2 Meningkatkan 3.2.1 Penguatan Keterlibatan Fokus Capaian 11:
Keterlibatan dan Sinergi Multipihak Terwujudnya pemulihan dan Sinergi dalam Rehabilitasi dan daerah terdampak Multipihak Rekonstruksi bencana yang lebih baik, untuk Pascabencana aman, dan berkelanjutan Mempercepat dengan memperhatikan Rehabilitasi pengurangan risiko dan bencana Rekonstruksi Pasca Bencana pada Seluruh Aspek Secara Efektif Sasaran 4 4.1 Membangun 4.1.1 Penguatan Sistem Fokus Capaian 1:
Meningkatkan Sistem Regulasi Untuk Terwujudnya peraturan Pelayanan dan Regulasi yang Penanggulangan perundang-undangan Kapasitas Handal dan Bencana yang harmonis di bidang Penanggulangan Terpadu penanggulangan Bencana Melalui dalam bencana Transformasi Mendukung 4.1.2 Pemaduan KRB dan Fokus Capaian 1:
Tata Kelola dan Kinerja Sistem RPB dalam Rencana Terwujudnya peraturan Kolaborasi Multi- Penanggulang Pembangunan perundang-undangan Pihak an Bencana yang harmonis di bidang penanggulangan bencana 4.2 Meningkatkan 4.2.1 Penguatan Penerapan Fokus Capaian 5:
Capaian SPM Sub Urusan Terwujudnya tata kelola Penerapan Bencana risiko bencana yang SPM Sub sinergis antara pusat dan Urusan daerah Bencana 4.3 Meningkatkan 4.3.1 Peningkatan Kapasitas Fokus Capaian 10:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2185, 'Rekonstruksi Pascabencana Rehabilitasi dan Terwujudnya pemulihan Berbasis Tata Rekonstruksi daerah terdampak Ruang dan bencana yang lebih baik, Pengurangan aman, dan berkelanjutan Risiko dengan memperhatikan Bencana pengurangan risiko bencana 3.2 Meningkatkan 3.2.1 Penguatan Keterlibatan Fokus Capaian 11:
Keterlibatan dan Sinergi Multipihak Terwujudnya pemulihan dan Sinergi dalam Rehabilitasi dan daerah terdampak Multipihak Rekonstruksi bencana yang lebih baik, untuk Pascabencana aman, dan berkelanjutan Mempercepat dengan memperhatikan Rehabilitasi pengurangan risiko dan bencana Rekonstruksi Pasca Bencana pada Seluruh Aspek Secara Efektif Sasaran 4 4.1 Membangun 4.1.1 Penguatan Sistem Fokus Capaian 1:
Meningkatkan Sistem Regulasi Untuk Terwujudnya peraturan Pelayanan dan Regulasi yang Penanggulangan perundang-undangan Kapasitas Handal dan Bencana yang harmonis di bidang Penanggulangan Terpadu penanggulangan Bencana Melalui dalam bencana Transformasi Mendukung 4.1.2 Pemaduan KRB dan Fokus Capaian 1:
Tata Kelola dan Kinerja Sistem RPB dalam Rencana Terwujudnya peraturan Kolaborasi Multi- Penanggulang Pembangunan perundang-undangan Pihak an Bencana yang harmonis di bidang penanggulangan bencana 4.2 Meningkatkan 4.2.1 Penguatan Penerapan Fokus Capaian 5:
Capaian SPM Sub Urusan Terwujudnya tata kelola Penerapan Bencana risiko bencana yang SPM Sub sinergis antara pusat dan Urusan daerah Bencana 4.3 Meningkatkan 4.3.1 Peningkatan Kapasitas Fokus Capaian 10:', 'Lampiran hal. 38', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2186, 'perban-1-2025', 79, 'lampiran', 'Lampiran hal. 38', NULL, 38, 'Ketersediaan SDM Penanggulangan Tersedianya sumber daya SDM yang Bencana manusia yang memiliki Memiliki keahlian dan profesional Keahlian dan di bidang kebencanaan Profesional di 4.3.2 Pengembangan Fokus Capaian 10:
Bidang Standardisasi Tersedianya sumber daya Kebencanaan Kompetensi Bidang manusia yang memiliki Kebencanaan keahlian dan profesional di bidang kebencanaan 4.4 Menciptakan 4.4.1 Peningkatan Fokus Capaian 2:
Lingkungan Keterlibatan Multi Pihak Terwujudnya yang Kondusif Dalam Industrialisasi kemandirian teknologi untuk Kebencanaan dan industrialisasi Menumbuhke kebencanaan mbangkan Industrialisasi Kebencanaan 4.5 Meningkatkan 4.5.1 Peningkatan Fokus Capaian 4:
Kolaborasi Ketangguhan Berbasis Terwujudnya investasi dalam Komunitas yang memadai dalam SASARAN RENAS PB PROGRAM FOKUS CAPAIAN RIPB STRATEGI TAHUN 2025- TAHUN 2025-2029 2029 Membangun pengurangan risiko Ketangguhan bencana untuk Individu, ketangguhan Keluarga, dan 4.5.2 Pengembangan Fokus Capaian 6:
Masyarakat Pendidikan dan Edukasi Terwujudnya Kebencanaan Bagi pemahaman terhadap Masyarakat risiko bencana, bentang alam, dan adaptasi perubahan iklim, serta ketahanan sosial dan ketahanan Kesehatan masyarakat 4.6 4.6.1 Pengembangan Skema Fokus Capaian 4:
Mengembangk Perlindungan Sosial Terwujudnya investasi an Skema Adaptif yang memadai dalam Pendanaan pengurangan risiko Inovatif dalam bencana untuk Penanggulang ketangguhan an Bencana 4.6.2 Optimasi Pemanfaatan Fokus Capaian 4:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2186, 'Ketersediaan SDM Penanggulangan Tersedianya sumber daya SDM yang Bencana manusia yang memiliki Memiliki keahlian dan profesional Keahlian dan di bidang kebencanaan Profesional di 4.3.2 Pengembangan Fokus Capaian 10:
Bidang Standardisasi Tersedianya sumber daya Kebencanaan Kompetensi Bidang manusia yang memiliki Kebencanaan keahlian dan profesional di bidang kebencanaan 4.4 Menciptakan 4.4.1 Peningkatan Fokus Capaian 2:
Lingkungan Keterlibatan Multi Pihak Terwujudnya yang Kondusif Dalam Industrialisasi kemandirian teknologi untuk Kebencanaan dan industrialisasi Menumbuhke kebencanaan mbangkan Industrialisasi Kebencanaan 4.5 Meningkatkan 4.5.1 Peningkatan Fokus Capaian 4:
Kolaborasi Ketangguhan Berbasis Terwujudnya investasi dalam Komunitas yang memadai dalam SASARAN RENAS PB PROGRAM FOKUS CAPAIAN RIPB STRATEGI TAHUN 2025- TAHUN 2025-2029 2029 Membangun pengurangan risiko Ketangguhan bencana untuk Individu, ketangguhan Keluarga, dan 4.5.2 Pengembangan Fokus Capaian 6:
Masyarakat Pendidikan dan Edukasi Terwujudnya Kebencanaan Bagi pemahaman terhadap Masyarakat risiko bencana, bentang alam, dan adaptasi perubahan iklim, serta ketahanan sosial dan ketahanan Kesehatan masyarakat 4.6 4.6.1 Pengembangan Skema Fokus Capaian 4:
Mengembangk Perlindungan Sosial Terwujudnya investasi an Skema Adaptif yang memadai dalam Pendanaan pengurangan risiko Inovatif dalam bencana untuk Penanggulang ketangguhan an Bencana 4.6.2 Optimasi Pemanfaatan Fokus Capaian 4:', 'Lampiran hal. 38', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2187, 'perban-1-2025', 80, 'lampiran', 'Lampiran hal. 39', NULL, 39, 'Dana Bersama Terwujudnya investasi Penanggulangan yang memadai dalam Bencana pengurangan risiko bencana untuk ketangguhan 4.6.3 Pengembangan Fokus Capaian 4:
Kebijakan Asuransi Terwujudnya investasi Bencana dan yang memadai dalam Pembiayaan Risiko pengurangan risiko bencana untuk ketangguhan 4.7 Meningkatkan 4.7.1 Pengembangan Sistem Fokus Capaian 5:
Kualitas Pemantauan dan Terwujudnya tata kelola Pemantauan, Evaluasi risiko bencana yang Pengendalian, Penanggulangan sinergis antara pusat dan dan Evaluasi Bencana daerah Penanggulang an Bencana 4.8 Meningkatkan 4.8.1 Pengembangan Fokus Capaian 5:
Advokasi Kebijakan dan Kerangka Terwujudnya tata kelola Resiliensi Hukum Untuk risiko bencana yang Berkelanjutan Resiliensi Berkelanjutan sinergis antara pusat dan di Tingkat daerah Nasional dan 4.8.2 Peningkatan Kapasitas Fokus Capaian 5:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2187, 'Dana Bersama Terwujudnya investasi Penanggulangan yang memadai dalam Bencana pengurangan risiko bencana untuk ketangguhan 4.6.3 Pengembangan Fokus Capaian 4:
Kebijakan Asuransi Terwujudnya investasi Bencana dan yang memadai dalam Pembiayaan Risiko pengurangan risiko bencana untuk ketangguhan 4.7 Meningkatkan 4.7.1 Pengembangan Sistem Fokus Capaian 5:
Kualitas Pemantauan dan Terwujudnya tata kelola Pemantauan, Evaluasi risiko bencana yang Pengendalian, Penanggulangan sinergis antara pusat dan dan Evaluasi Bencana daerah Penanggulang an Bencana 4.8 Meningkatkan 4.8.1 Pengembangan Fokus Capaian 5:
Advokasi Kebijakan dan Kerangka Terwujudnya tata kelola Resiliensi Hukum Untuk risiko bencana yang Berkelanjutan Resiliensi Berkelanjutan sinergis antara pusat dan di Tingkat daerah Nasional dan 4.8.2 Peningkatan Kapasitas Fokus Capaian 5:', 'Lampiran hal. 39', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2188, 'perban-1-2025', 81, 'lampiran', 'Lampiran hal. 39', NULL, 39, 'Global dan Pengetahuan Terwujudnya tata kelola Tentang Resiliensi risiko bencana yang Berkelanjutan sinergis antara pusat dan daerah 4.8.3 Penguatan Kerja Sama Fokus Capaian 5: dan Kemitraan Untuk Terwujudnya tata kelola Resiliensi Berkelanjutan risiko bencana yang sinergis antara pusat dan daerah 2.6. Arah Kebijakan Penanggulangan Bencana Per Wilayah Indonesia merupakan negara kepulauan dengan masing-masing pulau atau gugusan kepulauan memiliki karakteristik yang berbeda-beda, termasuk potensi bencananya. Sejalan dengan Rencana Pembangunan Jangka Panjang Nasional 2025-2045 yang menetapkan arah kebijakan wilayah sesuai dengan karakteristik wilayah pulau, RENAS PB Tahun 2025-2029 menetapkan arah kebijakan penanggulangan bencana per wilayah pulau yang disesuaikan dengan karakteristik risiko bencana per wilayah pulau. Arah kebijakan penanggulangan bencana per wilayah berisi fokus upaya penanggulangan bencana per pulau dan menjadi acuan pelaksanaan aksi-aksi prioritas RENAS PB Tahun 2025-2029 oleh pemerintah pusat di masing-masing pulau. Arah kebijakan ini juga menjadi acuan bagi pemerintah daerah dalam menyusun kebijakan, strategi, program, dan kegiatan dalam Rencana Penanggulangan Bencana (RPB) daerah sebagai bentuk penyelarasan dengan RENAS PB Tahun 2025-2029.
1. Arah Kebijakan Penanggulangan Bencana Wilayah Sumatera Wilayah Sumatera terletak di bagian barat Indonesia dengan luas 473.481 km² dan menjadi pulau terbesar kedua dalam hal jumlah penduduk setelah Jawa.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2188, 'Global dan Pengetahuan Terwujudnya tata kelola Tentang Resiliensi risiko bencana yang Berkelanjutan sinergis antara pusat dan daerah 4.8.3 Penguatan Kerja Sama Fokus Capaian 5: dan Kemitraan Untuk Terwujudnya tata kelola Resiliensi Berkelanjutan risiko bencana yang sinergis antara pusat dan daerah 2.6. Arah Kebijakan Penanggulangan Bencana Per Wilayah Indonesia merupakan negara kepulauan dengan masing-masing pulau atau gugusan kepulauan memiliki karakteristik yang berbeda-beda, termasuk potensi bencananya. Sejalan dengan Rencana Pembangunan Jangka Panjang Nasional 2025-2045 yang menetapkan arah kebijakan wilayah sesuai dengan karakteristik wilayah pulau, RENAS PB Tahun 2025-2029 menetapkan arah kebijakan penanggulangan bencana per wilayah pulau yang disesuaikan dengan karakteristik risiko bencana per wilayah pulau. Arah kebijakan penanggulangan bencana per wilayah berisi fokus upaya penanggulangan bencana per pulau dan menjadi acuan pelaksanaan aksi-aksi prioritas RENAS PB Tahun 2025-2029 oleh pemerintah pusat di masing-masing pulau. Arah kebijakan ini juga menjadi acuan bagi pemerintah daerah dalam menyusun kebijakan, strategi, program, dan kegiatan dalam Rencana Penanggulangan Bencana (RPB) daerah sebagai bentuk penyelarasan dengan RENAS PB Tahun 2025-2029.
1. Arah Kebijakan Penanggulangan Bencana Wilayah Sumatera Wilayah Sumatera terletak di bagian barat Indonesia dengan luas 473.481 km² dan menjadi pulau terbesar kedua dalam hal jumlah penduduk setelah Jawa.', 'Lampiran hal. 39', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2189, 'perban-1-2025', 82, 'lampiran', 'Lampiran hal. 40', NULL, 40, 'Wilayah Sumatera memiliki potensi sumber daya alam yang tinggi, berupa hasil pertanian, perkebunan, pertambangan dan minyak serta gas, serta perikanan tangkap dan budidaya. Wilayah Sumatera memiliki risiko bencana yang tinggi karena terletak di wilayah vulkanologi dan patahan tektonik terutama di Pantai Barat Sumatera yang masuk dalam rangkaian pegunungan Bukit Barisan. Kondisi pesisir Pantai Barat Sumatera juga semakin diperburuk dengan abrasi dan kenaikan muka air laut. Selain memiliki profil bahaya geologi, seperti gempabumi, tsunami, dan gunung api, wilayah Sumatera juga menghadapi risiko bencana hidrometeorologi terutama berkaitan dengan tingginya laju deforestasi yang mengakibatkan penurunan tutupan hutan dan permasalahan siklus air.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2189, 'Wilayah Sumatera memiliki potensi sumber daya alam yang tinggi, berupa hasil pertanian, perkebunan, pertambangan dan minyak serta gas, serta perikanan tangkap dan budidaya. Wilayah Sumatera memiliki risiko bencana yang tinggi karena terletak di wilayah vulkanologi dan patahan tektonik terutama di Pantai Barat Sumatera yang masuk dalam rangkaian pegunungan Bukit Barisan. Kondisi pesisir Pantai Barat Sumatera juga semakin diperburuk dengan abrasi dan kenaikan muka air laut. Selain memiliki profil bahaya geologi, seperti gempabumi, tsunami, dan gunung api, wilayah Sumatera juga menghadapi risiko bencana hidrometeorologi terutama berkaitan dengan tingginya laju deforestasi yang mengakibatkan penurunan tutupan hutan dan permasalahan siklus air.', 'Lampiran hal. 40', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2190, 'perban-1-2025', 83, 'lampiran', 'Lampiran hal. 40', NULL, 40, 'Gambar 2.6 Peta Risiko Bencana Multi Bahaya Wilayah Sumatera Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Sumatera tahun 2025-2029 secara umum diarahkan pada: (a) pengembangan pendidikan aman bencana; (b) pemberdayaan masyarakat/peningkatan ketangguhan berbasis komunitas; (c) peningkatan layanan pemerintah dalam peringatan dini bencana, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (d) peningkatan kualitas dan ketersediaan infrastruktur publik berketahanan bencana dan iklim; (e) perencanaan tata ruang dan pengendalian pemanfaatan ruang serta perencanaan pembangunan berbasis mitigasi bencana dan ketahan iklim; (f) peningkatan kapasitas SDM pemerintah daerah di bidang kebencanaan; dan (g) pembangunan gudang logistik regional dan pengembangan klaster logistik.
Secara khusus, penanggulangan bencana di Wilayah Sumatera diarahkan pada: (a) peningkatan sarana dan prasarana pendukung serta diseminasi peringatan dini bencana gempa bumi, tsunami, dan letusan gunung api; (b) pengendalian deforestasi dan kebakaran hutan dan lahan; dan (c) pengurangan risiko abrasi.
2. Arah Kebijakan Penanggulangan Bencana Wilayah Jawa Wilayah Jawa memiliki luas total daratan dan lautan mencapai 132.114 km2.
Dengan luas wilayah yang relatif kecil, tingkat kepadatan penduduk di wilayah Jawa ialah tertinggi dan menjadi pusat pertumbuhan ekonomi utama di Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2190, 'Gambar 2.6 Peta Risiko Bencana Multi Bahaya Wilayah Sumatera Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Sumatera tahun 2025-2029 secara umum diarahkan pada: (a) pengembangan pendidikan aman bencana; (b) pemberdayaan masyarakat/peningkatan ketangguhan berbasis komunitas; (c) peningkatan layanan pemerintah dalam peringatan dini bencana, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (d) peningkatan kualitas dan ketersediaan infrastruktur publik berketahanan bencana dan iklim; (e) perencanaan tata ruang dan pengendalian pemanfaatan ruang serta perencanaan pembangunan berbasis mitigasi bencana dan ketahan iklim; (f) peningkatan kapasitas SDM pemerintah daerah di bidang kebencanaan; dan (g) pembangunan gudang logistik regional dan pengembangan klaster logistik.
Secara khusus, penanggulangan bencana di Wilayah Sumatera diarahkan pada: (a) peningkatan sarana dan prasarana pendukung serta diseminasi peringatan dini bencana gempa bumi, tsunami, dan letusan gunung api; (b) pengendalian deforestasi dan kebakaran hutan dan lahan; dan (c) pengurangan risiko abrasi.
2. Arah Kebijakan Penanggulangan Bencana Wilayah Jawa Wilayah Jawa memiliki luas total daratan dan lautan mencapai 132.114 km2.
Dengan luas wilayah yang relatif kecil, tingkat kepadatan penduduk di wilayah Jawa ialah tertinggi dan menjadi pusat pertumbuhan ekonomi utama di Indonesia.', 'Lampiran hal. 40', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2191, 'perban-1-2025', 84, 'lampiran', 'Lampiran hal. 41', NULL, 41, 'Tingkat urbanisasi di Wilayah Jawa cukup tinggi dengan kawasan perkotaan yang juga didominasi berlokasi di kawasan rawan bencana. Wilayah Jawa memiliki karakteristik risiko bencana yang tinggi karena terletak di wilayah vulkanologi dan patahan tektonik. Jenis ancaman bencana di Wilayah Jawa terutama terdiri dari banjir, gempa bumi, tsunami, tanah longsor, dan letusan gunung api.
Gambar 2.7 Peta Risiko Bencana Multi Bahaya Wilayah Jawa Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Jawa tahun 2025-2029 secara umum diarahkan pada: (a) pengembangan pendidikan aman bencana; (b) pemberdayaan masyarakat/peningkatan ketangguhan berbasis komunitas; (c) peningkatan layanan pemerintah dalam peringatan dini, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (d) peningkatan kualitas dan ketersediaan infrastruktur publik berketahanan bencana; dan (e) pembangunan gudang logistik regional dan pengembangan klaster logistik.
Secara khusus, penanggulangan bencana di Wilayah Jawa diarahkan pada: (a) pengendalian tata ruang di wilayah perkotaan dan pesisir dengan mempertimbangkan pengurangan risiko bencana dan ketahanan iklim; (b) pengurangan risiko abrasi di pesisir utara Jawa; dan (c) pengembangan kawasan perkotaan serta kawasan investasi yang berketahanan bencana dan perubahan iklim.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2191, 'Tingkat urbanisasi di Wilayah Jawa cukup tinggi dengan kawasan perkotaan yang juga didominasi berlokasi di kawasan rawan bencana. Wilayah Jawa memiliki karakteristik risiko bencana yang tinggi karena terletak di wilayah vulkanologi dan patahan tektonik. Jenis ancaman bencana di Wilayah Jawa terutama terdiri dari banjir, gempa bumi, tsunami, tanah longsor, dan letusan gunung api.
Gambar 2.7 Peta Risiko Bencana Multi Bahaya Wilayah Jawa Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Jawa tahun 2025-2029 secara umum diarahkan pada: (a) pengembangan pendidikan aman bencana; (b) pemberdayaan masyarakat/peningkatan ketangguhan berbasis komunitas; (c) peningkatan layanan pemerintah dalam peringatan dini, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (d) peningkatan kualitas dan ketersediaan infrastruktur publik berketahanan bencana; dan (e) pembangunan gudang logistik regional dan pengembangan klaster logistik.
Secara khusus, penanggulangan bencana di Wilayah Jawa diarahkan pada: (a) pengendalian tata ruang di wilayah perkotaan dan pesisir dengan mempertimbangkan pengurangan risiko bencana dan ketahanan iklim; (b) pengurangan risiko abrasi di pesisir utara Jawa; dan (c) pengembangan kawasan perkotaan serta kawasan investasi yang berketahanan bencana dan perubahan iklim.', 'Lampiran hal. 41', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2192, 'perban-1-2025', 85, 'lampiran', 'Lampiran hal. 42', NULL, 42, '3. Arah Kebijakan Penanggulangan Bencana Wilayah Bali-Nusa Tenggara Wilayah Bali-Nusa Tenggara merupakan daerah kepulauan di Indonesia yang memiliki potensi wisata alam dan budaya. Bali memiliki tiga sektor unggulan utama, yaitu pariwisata, hotel dan restoran, serta pertanian. Sebagai pintu gerbang pariwisata Indonesia, Bali memiliki beberapa destinasi yang terkenal secara nasional. Sementara di Nusa Tenggara, sektor unggulan meliputi pertanian, perdagangan jasa, serta hotel dan restoran, dengan tambahan kontribusi dari sektor pertambangan dan penggalian. Di Nusa Tenggara, terdapat beberapa kawasan pusat pertumbuhan ekonomi, diantaranya kawasan ekonomi khusus Mandalika, kawasan strategis pariwisata Tambora, dan kawasan strategis pariwisata Labuan Bajo sebagai pusat pertumbuhan ekonomi. Jenis ancaman bencana di wilayah Bali-Nusa Tenggara terutama terdiri dari gempa bumi, tsunami, letusan gunung api, kekeringan, dan banjir dan tanah longsor.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2192, '3. Arah Kebijakan Penanggulangan Bencana Wilayah Bali-Nusa Tenggara Wilayah Bali-Nusa Tenggara merupakan daerah kepulauan di Indonesia yang memiliki potensi wisata alam dan budaya. Bali memiliki tiga sektor unggulan utama, yaitu pariwisata, hotel dan restoran, serta pertanian. Sebagai pintu gerbang pariwisata Indonesia, Bali memiliki beberapa destinasi yang terkenal secara nasional. Sementara di Nusa Tenggara, sektor unggulan meliputi pertanian, perdagangan jasa, serta hotel dan restoran, dengan tambahan kontribusi dari sektor pertambangan dan penggalian. Di Nusa Tenggara, terdapat beberapa kawasan pusat pertumbuhan ekonomi, diantaranya kawasan ekonomi khusus Mandalika, kawasan strategis pariwisata Tambora, dan kawasan strategis pariwisata Labuan Bajo sebagai pusat pertumbuhan ekonomi. Jenis ancaman bencana di wilayah Bali-Nusa Tenggara terutama terdiri dari gempa bumi, tsunami, letusan gunung api, kekeringan, dan banjir dan tanah longsor.', 'Lampiran hal. 42', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2193, 'perban-1-2025', 86, 'lampiran', 'Lampiran hal. 42', NULL, 42, 'Gambar 2.8 Peta Risiko Bencana Multi Bahaya Wilayah Bali-Nusa Tenggara Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Bali-Nusa Tenggara tahun 2025-2029 secara umum diarahkan pada: (a) pemberdayaan masyarakat/peningkatan ketangguhan berbasis komunitas; (b) peningkatan layanan pemerintah dalam peringatan dini, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (c) peningkatan kualitas dan ketersediaan infrastruktur publik berketahanan bencana; (d) perencanaan tata ruang dan pengendalian pemanfaatan ruang berbasis mitigasi bencana; dan (e) pembangunan gudang logistik regional dan pengembangan klaster logistik.
Secara khusus, penanggulangan bencana di Wilayah Bali-Nusa Tenggara diarahkan pada: (a) pengendalian banjir terpadu di kawasan pariwisata; (b) peningkatan kolaborasi multi-pihak untuk pengurangan risiko bencana dan pemulihan pascabencana; (c) pengelolaan risiko bencana gempabumi dan tsunami di wilayah perkotaan dan kawasan pariwisata; dan (d) pelindungan pulau-pulau kecil serta ekosistem laut dan pesisir yang berisiko bencana dan perubahan iklim.
4. Arah Kebijakan Penanggulangan Bencana Wilayah Kalimantan Kalimantan merupakan wilayah dengan tutupan hutan terbesar kedua di Indonesia setelah Papua, mencakup 183,83 juta ha (65,24% dari total luas pulau).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2193, 'Gambar 2.8 Peta Risiko Bencana Multi Bahaya Wilayah Bali-Nusa Tenggara Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Bali-Nusa Tenggara tahun 2025-2029 secara umum diarahkan pada: (a) pemberdayaan masyarakat/peningkatan ketangguhan berbasis komunitas; (b) peningkatan layanan pemerintah dalam peringatan dini, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (c) peningkatan kualitas dan ketersediaan infrastruktur publik berketahanan bencana; (d) perencanaan tata ruang dan pengendalian pemanfaatan ruang berbasis mitigasi bencana; dan (e) pembangunan gudang logistik regional dan pengembangan klaster logistik.
Secara khusus, penanggulangan bencana di Wilayah Bali-Nusa Tenggara diarahkan pada: (a) pengendalian banjir terpadu di kawasan pariwisata; (b) peningkatan kolaborasi multi-pihak untuk pengurangan risiko bencana dan pemulihan pascabencana; (c) pengelolaan risiko bencana gempabumi dan tsunami di wilayah perkotaan dan kawasan pariwisata; dan (d) pelindungan pulau-pulau kecil serta ekosistem laut dan pesisir yang berisiko bencana dan perubahan iklim.
4. Arah Kebijakan Penanggulangan Bencana Wilayah Kalimantan Kalimantan merupakan wilayah dengan tutupan hutan terbesar kedua di Indonesia setelah Papua, mencakup 183,83 juta ha (65,24% dari total luas pulau).', 'Lampiran hal. 42', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2194, 'perban-1-2025', 87, 'lampiran', 'Lampiran hal. 43', NULL, 43, 'Tutupan hutan Kalimantan juga menyumbang sekitar 19,94% dari total luas hutan di Indonesia. Wilayah Kalimantan direncanakan untuk menjadi titik pusat pertumbuhan ekonomi di Kawasan Timur Indonesia dengan pembangunan IKN sebagai pusat pertumbuhan ekonomi dan pengembangan kawasan industri baru.
Wilayah Kalimantan ke depannya dihadapkan pada isu degradasi lingkungan dan deforestasi lahan akibat konsesi lahan di kawasan hutan. Jenis ancaman bencana di wilayah Pulau Kalimantan terutama terdiri dari kebakaran hutan dan lahan, banjir, dan kekeringan. Berkaitan dengan bencana hidrometeorologis, kejadian bencana berdasarkan Data dan Informasi Bencana Indonesia (DIBI) dalam 10 tahun terakhir mengidentifikasi bahwa bencana kebakaran hutan dan lahan dan banjir tercatat memiliki frekuensi yang tinggi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2194, 'Tutupan hutan Kalimantan juga menyumbang sekitar 19,94% dari total luas hutan di Indonesia. Wilayah Kalimantan direncanakan untuk menjadi titik pusat pertumbuhan ekonomi di Kawasan Timur Indonesia dengan pembangunan IKN sebagai pusat pertumbuhan ekonomi dan pengembangan kawasan industri baru.
Wilayah Kalimantan ke depannya dihadapkan pada isu degradasi lingkungan dan deforestasi lahan akibat konsesi lahan di kawasan hutan. Jenis ancaman bencana di wilayah Pulau Kalimantan terutama terdiri dari kebakaran hutan dan lahan, banjir, dan kekeringan. Berkaitan dengan bencana hidrometeorologis, kejadian bencana berdasarkan Data dan Informasi Bencana Indonesia (DIBI) dalam 10 tahun terakhir mengidentifikasi bahwa bencana kebakaran hutan dan lahan dan banjir tercatat memiliki frekuensi yang tinggi.', 'Lampiran hal. 43', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2195, 'perban-1-2025', 88, 'lampiran', 'Lampiran hal. 43', NULL, 43, 'Gambar 2.9 Peta Risiko Bencana Multi Bahaya Wilayah Kalimantan Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Kalimantan tahun 2025-2029 secara umum diarahkan pada: (a) pemberdayaan masyarakat/ peningkatan ketangguhan berbasis komunitas; (b) peningkatan layanan pemerintah dalam mitigasi, peringatan dini, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (c) peningkatan kualitas dan ketersediaan sarana dan prasarana berketahanan bencana; (d) perencanaan tata ruang dan pengendalian pemanfaatan ruang berbasis mitigasi bencana dan ketahanan iklim; (e) peningkatan kapasitas SDM Pemerintah Daerah di bidang kebencanaan; dan (f) pembangunan gudang logistik regional dan pengembangan klaster logistik. Secara khusus, penanggulangan bencana di Wilayah Kalimantan diarahkan pada: (a) pengembangan IKN berketahanan bencana dan iklim; (b) pengendalian deforestasi dan kebakaran hutan; (c) pengembangan solusi berbasis alam (nature-based solution) untuk pengendalian bencana dan ketahanan iklim; dan (d) peningkatan sarana dan prasarana pendukung dan diseminasi peringatan dini bencana banjir dan kebakaran hutan dan lahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2195, 'Gambar 2.9 Peta Risiko Bencana Multi Bahaya Wilayah Kalimantan Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Kalimantan tahun 2025-2029 secara umum diarahkan pada: (a) pemberdayaan masyarakat/ peningkatan ketangguhan berbasis komunitas; (b) peningkatan layanan pemerintah dalam mitigasi, peringatan dini, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (c) peningkatan kualitas dan ketersediaan sarana dan prasarana berketahanan bencana; (d) perencanaan tata ruang dan pengendalian pemanfaatan ruang berbasis mitigasi bencana dan ketahanan iklim; (e) peningkatan kapasitas SDM Pemerintah Daerah di bidang kebencanaan; dan (f) pembangunan gudang logistik regional dan pengembangan klaster logistik. Secara khusus, penanggulangan bencana di Wilayah Kalimantan diarahkan pada: (a) pengembangan IKN berketahanan bencana dan iklim; (b) pengendalian deforestasi dan kebakaran hutan; (c) pengembangan solusi berbasis alam (nature-based solution) untuk pengendalian bencana dan ketahanan iklim; dan (d) peningkatan sarana dan prasarana pendukung dan diseminasi peringatan dini bencana banjir dan kebakaran hutan dan lahan.', 'Lampiran hal. 43', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2196, 'perban-1-2025', 89, 'lampiran', 'Lampiran hal. 44', NULL, 44, '5. Arah Kebijakan Penanggulangan Bencana Wilayah Sulawesi Wilayah Sulawesi memiliki empat semenanjung, yaitu Semenanjung Utara, Semenanjung Timur, Semenanjung Selatan, dan Semenanjung Tenggara. Sulawesi memiliki luas hutan sebesar 69,56 juta ha (40,77% dari luas pulau) dan menyumbang sekitar 7,54% dari total luas hutan di Indonesia. Jenis ancaman bencana di wilayah Sulawesi terutama terdiri dari banjir, gempa bumi, tsunami, tanah longsor, letusan gunung api, likuefaksi, dan kekeringan.
Gambar 2.10 Peta Risiko Bencana Multi Bahaya Wilayah Sulawesi Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Sulawesi tahun 2025-2029 secara umum diarahkan pada: (a) pengembangan pendidikan aman bencana; (b) pemberdayaan masyarakat/ peningkatan ketangguhan berbasis komunitas; (c) peningkatan layanan pemerintah dalam mitigasi, peringatan dini, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (d) peningkatan kualitas dan ketersediaan infrastruktur publik berketahanan bencana; (e) perencanaan tata ruang dan pengendalian pemanfaatan ruang berbasis mitigasi bencana dan ketahanan iklim; (f) peningkatan kapasitas sumber daya manusia pemerintah daerah di bidang kebencanaan; dan (g) pembangunan gudang logistik regional dan pengembangan klaster logistik. Secara khusus, penanggulangan bencana di Wilayah Sulawesi diarahkan pada: (a) pembangunan infrastruktur tahan bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2196, '5. Arah Kebijakan Penanggulangan Bencana Wilayah Sulawesi Wilayah Sulawesi memiliki empat semenanjung, yaitu Semenanjung Utara, Semenanjung Timur, Semenanjung Selatan, dan Semenanjung Tenggara. Sulawesi memiliki luas hutan sebesar 69,56 juta ha (40,77% dari luas pulau) dan menyumbang sekitar 7,54% dari total luas hutan di Indonesia. Jenis ancaman bencana di wilayah Sulawesi terutama terdiri dari banjir, gempa bumi, tsunami, tanah longsor, letusan gunung api, likuefaksi, dan kekeringan.
Gambar 2.10 Peta Risiko Bencana Multi Bahaya Wilayah Sulawesi Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Sulawesi tahun 2025-2029 secara umum diarahkan pada: (a) pengembangan pendidikan aman bencana; (b) pemberdayaan masyarakat/ peningkatan ketangguhan berbasis komunitas; (c) peningkatan layanan pemerintah dalam mitigasi, peringatan dini, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (d) peningkatan kualitas dan ketersediaan infrastruktur publik berketahanan bencana; (e) perencanaan tata ruang dan pengendalian pemanfaatan ruang berbasis mitigasi bencana dan ketahanan iklim; (f) peningkatan kapasitas sumber daya manusia pemerintah daerah di bidang kebencanaan; dan (g) pembangunan gudang logistik regional dan pengembangan klaster logistik. Secara khusus, penanggulangan bencana di Wilayah Sulawesi diarahkan pada: (a) pembangunan infrastruktur tahan bencana;', 'Lampiran hal. 44', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2197, 'perban-1-2025', 90, 'lampiran', 'Lampiran hal. 44', NULL, 44, '(b) pemanfaatan dan penguatan teknologi kebencanaan; dan (c) peningkatan sarana dan prasarana pendukung dan diseminasi peringatan dini serta evakuasi bencana gempabumi, tsunami, likuefaksi, tanah longsor.
6. Arah Kebijakan Penanggulangan Bencana Wilayah Maluku Wilayah Maluku, secara geografis merupakan wilayah kepulauan dengan lebih dari 80% luas wilayahnya merupakan lautan. Wilayah Maluku merupakan wilayah kepulauan dengan potensi ekosistem pesisir dan pulau-pulau kecil yang cukup tinggi. Pada tahun 2021, berdasarkan data Badan Pusat Statistik, total terdapat 1.974 desa/kelurahan yang berada di tepi laut (coastal area). Jenis ancaman bencana di wilayah Maluku terutama terdiri dari banjir, gempa bumi, tsunami, tanah longsor, cuaca ekstrim dan abrasi. Berdasarkan Data Informasi Bencana Indonesia (DIBI) Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah Provinsi Maluku, dalam 10 (sepuluh) tahun terakhir terdapat 158 kejadian bencana dengan jumlah kejadian terbanyak adalah banjir.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2197, '(b) pemanfaatan dan penguatan teknologi kebencanaan; dan (c) peningkatan sarana dan prasarana pendukung dan diseminasi peringatan dini serta evakuasi bencana gempabumi, tsunami, likuefaksi, tanah longsor.
6. Arah Kebijakan Penanggulangan Bencana Wilayah Maluku Wilayah Maluku, secara geografis merupakan wilayah kepulauan dengan lebih dari 80% luas wilayahnya merupakan lautan. Wilayah Maluku merupakan wilayah kepulauan dengan potensi ekosistem pesisir dan pulau-pulau kecil yang cukup tinggi. Pada tahun 2021, berdasarkan data Badan Pusat Statistik, total terdapat 1.974 desa/kelurahan yang berada di tepi laut (coastal area). Jenis ancaman bencana di wilayah Maluku terutama terdiri dari banjir, gempa bumi, tsunami, tanah longsor, cuaca ekstrim dan abrasi. Berdasarkan Data Informasi Bencana Indonesia (DIBI) Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah Provinsi Maluku, dalam 10 (sepuluh) tahun terakhir terdapat 158 kejadian bencana dengan jumlah kejadian terbanyak adalah banjir.', 'Lampiran hal. 44', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2198, 'perban-1-2025', 91, 'lampiran', 'Lampiran hal. 45', NULL, 45, 'Gambar 2.11 Peta Risiko Bencana Multi Bahaya Wilayah Maluku Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Maluku tahun 2025-2029 secara umum diarahkan pada: (a) pemberdayaan masyarakat/ peningkatan ketangguhan berbasis komunitas; (b) peningkatan layanan pemerintah dalam peringatan dini, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (c) peningkatan kualitas dan ketersediaan infrastruktur publik berketahanan bencana dan iklim; (d) perencanaan tata ruang dan perencanaan pembangunan dengan mempertimbangkan risiko bencana dan perubahan iklim; (e) peningkatan kapasitas sumber daya manusia Pemerintah Daerah di bidang kebencanaan; dan (f) pembangunan gudang logistik regional dan pengembangan klaster logistik.
Secara khusus, penanggulangan bencana di Wilayah Maluku diarahkan pada:
(a) pengembangan solusi berbasis alam (nature-based solution) dan infrastruktur hijau (green-infrastructure) untuk pengendalian bencana & ketahanan iklim; (b) pelindungan pulau-pulau kecil serta ekosistem laut dan pesisir yang berisiko bencana tinggi; dan (c) peningkatan sarana dan prasarana pendukung dan diseminasi peringatan dini serta evakuasi bencana gempabumi, tsunami, letusan gunung api, cuaca ekstrim, dan gelombang tinggi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2198, 'Gambar 2.11 Peta Risiko Bencana Multi Bahaya Wilayah Maluku Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Maluku tahun 2025-2029 secara umum diarahkan pada: (a) pemberdayaan masyarakat/ peningkatan ketangguhan berbasis komunitas; (b) peningkatan layanan pemerintah dalam peringatan dini, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (c) peningkatan kualitas dan ketersediaan infrastruktur publik berketahanan bencana dan iklim; (d) perencanaan tata ruang dan perencanaan pembangunan dengan mempertimbangkan risiko bencana dan perubahan iklim; (e) peningkatan kapasitas sumber daya manusia Pemerintah Daerah di bidang kebencanaan; dan (f) pembangunan gudang logistik regional dan pengembangan klaster logistik.
Secara khusus, penanggulangan bencana di Wilayah Maluku diarahkan pada:
(a) pengembangan solusi berbasis alam (nature-based solution) dan infrastruktur hijau (green-infrastructure) untuk pengendalian bencana & ketahanan iklim; (b) pelindungan pulau-pulau kecil serta ekosistem laut dan pesisir yang berisiko bencana tinggi; dan (c) peningkatan sarana dan prasarana pendukung dan diseminasi peringatan dini serta evakuasi bencana gempabumi, tsunami, letusan gunung api, cuaca ekstrim, dan gelombang tinggi.', 'Lampiran hal. 45', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2199, 'perban-1-2025', 92, 'lampiran', 'Lampiran hal. 46', NULL, 46, '7. Arah Kebijakan Penanggulangan Bencana Wilayah Papua Wilayah Papua memiliki luas tutupan hutan terbesar di Indonesia, mencapai sekitar 343,62 juta ha pada tahun 2020, yang menutupi sekitar 84,43% dari total luas daratan pulau tersebut. Wilayah Papua Barat khususnya bagian kepala burung memiliki kondisi geologi yang kompleks akibat pertemuan antara tiga lempeng yaitu Eurasia, Pasifik, dan Australia. Wilayah Papua Barat terdiri dari sesar-sesar normal antara lain Sesar Sorong, Koor, Taminabun, Wandamen, Ransiki, serta Tarera-Aiduna sehingga rawan terhadap bencana gempabumi.
Sedangkan, wilayah Provinsi Papua terdiri dari wilayah dataran rendah, pesisir, dan pegunungan yang terdiri atas tiga deretan pegunungan yaitu: (a) Pegunungan Utara di lingkar luar; (b) deretan Pegunungan Selatan di lingkar dalam; dan (c) deretan Pegunungan Tengah yang merupakan tepi dari The Australian Continent. Daerah pegunungan berada pada ketinggian di antara 3.000-4.000 meter dan lebih dari 4.000 meter dari permukaan laut (mdpl). Jenis ancaman bencana di wilayah Papua terutama terdiri dari banjir, longsor, gempa bumi, dan tsunami.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2199, '7. Arah Kebijakan Penanggulangan Bencana Wilayah Papua Wilayah Papua memiliki luas tutupan hutan terbesar di Indonesia, mencapai sekitar 343,62 juta ha pada tahun 2020, yang menutupi sekitar 84,43% dari total luas daratan pulau tersebut. Wilayah Papua Barat khususnya bagian kepala burung memiliki kondisi geologi yang kompleks akibat pertemuan antara tiga lempeng yaitu Eurasia, Pasifik, dan Australia. Wilayah Papua Barat terdiri dari sesar-sesar normal antara lain Sesar Sorong, Koor, Taminabun, Wandamen, Ransiki, serta Tarera-Aiduna sehingga rawan terhadap bencana gempabumi.
Sedangkan, wilayah Provinsi Papua terdiri dari wilayah dataran rendah, pesisir, dan pegunungan yang terdiri atas tiga deretan pegunungan yaitu: (a) Pegunungan Utara di lingkar luar; (b) deretan Pegunungan Selatan di lingkar dalam; dan (c) deretan Pegunungan Tengah yang merupakan tepi dari The Australian Continent. Daerah pegunungan berada pada ketinggian di antara 3.000-4.000 meter dan lebih dari 4.000 meter dari permukaan laut (mdpl). Jenis ancaman bencana di wilayah Papua terutama terdiri dari banjir, longsor, gempa bumi, dan tsunami.', 'Lampiran hal. 46', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2200, 'perban-1-2025', 93, 'lampiran', 'Lampiran hal. 46', NULL, 46, 'Gambar 2.12 Peta Risiko Bencana Multi Bahaya Wilayah Papua Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Papua tahun 2025-2029 secara umum diarahkan pada: (a) pemberdayaan masyarakat/peningkatan ketangguhan berbasis komunitas; (b) peningkatan layanan pemerintah dalam mitigasi, peringatan dini, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (c) peningkatan kualitas dan ketersediaan infrastruktur publik berketahanan bencana dan iklim; (d) perencanaan tata ruang dan pengendalian pemanfaatan ruang serta perencanaan pembangunan berbasis mitigasi bencana dan berketahanan iklim; (e) peningkatan kapasitas sumber daya manusia pemerintah daerah di bidang kebencanaan; dan (f) pembangunan gudang logistik regional dan pengembangan klaster logistik.
Secara khusus, penanggulangan bencana di Wilayah Papua diarahkan pada:
(a) pengendalian banjir terpadu; dan (b) pelindungan ekosistem laut dan pesisir yang berisiko bencana. (c) peningkatan sarana dan prasarana pendukung dan diseminasi peringatan dini serta evakuasi bencana gempabumi, tsunami, tanah longsor, dan banjir; (d) revitalisasi sungai dan danau; dan (e) pelaksanaan rehabilitasi dan rekonstruksi di daerah terdampak bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2200, 'Gambar 2.12 Peta Risiko Bencana Multi Bahaya Wilayah Papua Sumber: diolah dari Kajian Risiko Bencana 2022-2026 Kebijakan penanggulangan bencana di Wilayah Papua tahun 2025-2029 secara umum diarahkan pada: (a) pemberdayaan masyarakat/peningkatan ketangguhan berbasis komunitas; (b) peningkatan layanan pemerintah dalam mitigasi, peringatan dini, kesiapsiagaan, penyelamatan dan evakuasi korban bencana; (c) peningkatan kualitas dan ketersediaan infrastruktur publik berketahanan bencana dan iklim; (d) perencanaan tata ruang dan pengendalian pemanfaatan ruang serta perencanaan pembangunan berbasis mitigasi bencana dan berketahanan iklim; (e) peningkatan kapasitas sumber daya manusia pemerintah daerah di bidang kebencanaan; dan (f) pembangunan gudang logistik regional dan pengembangan klaster logistik.
Secara khusus, penanggulangan bencana di Wilayah Papua diarahkan pada:
(a) pengendalian banjir terpadu; dan (b) pelindungan ekosistem laut dan pesisir yang berisiko bencana. (c) peningkatan sarana dan prasarana pendukung dan diseminasi peringatan dini serta evakuasi bencana gempabumi, tsunami, tanah longsor, dan banjir; (d) revitalisasi sungai dan danau; dan (e) pelaksanaan rehabilitasi dan rekonstruksi di daerah terdampak bencana.', 'Lampiran hal. 46', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2201, 'perban-1-2025', 94, 'lampiran', 'Lampiran hal. 47', NULL, 47, '2.7. Lokus Prioritas RENAS PB Tahun 2025-2029 menetapkan adanya lokus prioritas intervensi untuk menjadi pertimbangan utama dalam menentukan lokasi pelaksanaan rencana aksi tahun 2025-2029. Lokus prioritas tersebut ditetapkan berdasarkan beberapa kriteria, yaitu: (a) histori kejadian bencana; (b) hasil kajian risiko bencana multi bahaya (kelas bahaya dan kelas jiwa terpapar); (c) lokasi pusat kegiatan, pusat pertumbuhan, atau kawasan strategis/prioritas nasional yang ditetapkan dalam ketentuan peraturan perundang-undangan; (d) tingkat kapasitas fiskal daerah; (e) hasil kajian risiko bencana per jenis bahaya; dan/atau (f) identifikasi akar masalah yang dihimpun dari Kementerian/Lembaga. Lokus prioritas intervensi RENAS PB Tahun 2025-2029 ialah seperti tertera dalam Tabel 2.3 berikut.
Tabel 2.3 Lokus Prioritas Intervensi RENAS PB Tahun 2025-2029 WILAYAH LOKUS PRIORITAS Sumatera Kab. Aceh Barat, Kab. Aceh Besar, Kab. Pidie, Kab. Pidie Jaya, Kota Banda Aceh, Kab. Tapanuli Utara, Kab.Karo, Kota Sibolga, Kota Medan, Kota Binjai, Kota Padang Sidempuan, Kab.');
