INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2204, 'perban-1-2025', 97, 'lampiran', 'Lampiran hal. 49', NULL, 49, 'BAB III RENCANA AKSI RENCANA NASIONAL PENANGGULANGAN BENCANA TAHUN 2025-2029 Rencana aksi RENAS PB Tahun 2025-2029 berisi program dan kegiatan yang diturunkan dari kebijakan dan strategi yang ditetapkan untuk mencapai sasaran penanggulangan bencana 5 (lima) tahun ke depan. Kegiatan dan program sebagai aksi-aksi penanggulangan bencana di tahun 2025-2029 ini dirancang dalam rangka merespon isu strategis penanggulangan bencana dan menjadi solusi permasalahan-permasalahan yang diprediksi akan terjadi ke depan.
Program dalam rencana aksi 2025-2029 berisi kegiatan-kegiatan untuk mencapai sasaran program yang dirumuskan. Kegiatan-kegiatan tersebut diharapkan dapat menghasilkan luaran (output) dengan indikator dan target di tahun akhir RENAS PB Tahun 2025-2029. Setiap kegiatan telah dirancang untuk dilaksanakan dalam periode tahun pelaksanaan 2025-2029 oleh Kementerian/Lembaga Penanggung Jawab. Pada setiap kegiatan juga telah dirincikan besaran pagu indikatif dalam 1 (satu) periode pelaksanaan RENAS PB Tahun 2025-2029 bersama sumber pendanaannya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2204, 'BAB III RENCANA AKSI RENCANA NASIONAL PENANGGULANGAN BENCANA TAHUN 2025-2029 Rencana aksi RENAS PB Tahun 2025-2029 berisi program dan kegiatan yang diturunkan dari kebijakan dan strategi yang ditetapkan untuk mencapai sasaran penanggulangan bencana 5 (lima) tahun ke depan. Kegiatan dan program sebagai aksi-aksi penanggulangan bencana di tahun 2025-2029 ini dirancang dalam rangka merespon isu strategis penanggulangan bencana dan menjadi solusi permasalahan-permasalahan yang diprediksi akan terjadi ke depan.
Program dalam rencana aksi 2025-2029 berisi kegiatan-kegiatan untuk mencapai sasaran program yang dirumuskan. Kegiatan-kegiatan tersebut diharapkan dapat menghasilkan luaran (output) dengan indikator dan target di tahun akhir RENAS PB Tahun 2025-2029. Setiap kegiatan telah dirancang untuk dilaksanakan dalam periode tahun pelaksanaan 2025-2029 oleh Kementerian/Lembaga Penanggung Jawab. Pada setiap kegiatan juga telah dirincikan besaran pagu indikatif dalam 1 (satu) periode pelaksanaan RENAS PB Tahun 2025-2029 bersama sumber pendanaannya.', 'Lampiran hal. 49', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2205, 'perban-1-2025', 98, 'lampiran', 'Lampiran hal. 49', NULL, 49, 'Kementerian/Lembaga Penanggung Jawab bertugas untuk menganggarkan dan melaksanakan setiap kegiatan sesuai dengan kewenangan masing-masing dan melaporkan hasil pelaksanaannya dalam kegiatan pemantauan dan evaluasi. Pada setiap kegiatan juga dilakukan telah ditetapkan Kementerian/Lembaga Kontributor (Pendukung) berperan dalam mendukung pelaksanaan kegiatan oleh Kementerian/Lembaga Penanggung Jawab dalam berbagai bentuk, seperti: melakukan pembahasan substansi, memberikan pertimbangan dan masukan masukan gagasan, memberikan bantuan sumber daya, kerja sama dan kolaborasi pelaksanaan kegiatan, dan lainnya sesuai kewenangan masing-masing. Pada beberapa kegiatan juga telah ditetapkan pihak lainnya yang dapat mendukung atau perlu dilibatkan dalam pelaksanaannya, seperti pemerintah daerah, lembaga usaha, organisasi non pemerintah, perguruan tinggi, media, dan masyarakat.
Tabel 3.1 Rencana Aksi RENAS PB Tahun 2025-2029 TAHUN INSTANSI PAGU BASE- INDIKATIF SUMBER 2 2 2 2 2 TARGET PEMERINTAH KEGIATAN INDIKATOR SATUAN LINE LOKASI (Miliar PENDA- 0 0 0 0 0 2029 PIHAK 2024 Rupiah) NAAN PENANG- KONTRIBU- 2 2 2 2 2 GUNG TOR LAINNYA 5 6 7 8 9 JAWAB Sasaran 1 Mengurangi Jumlah Penduduk Terdampak Bencana melalui Peningkatan Kualitas Kesiapsiagaan, Peringatan Dini, dan Penanggulangan Kedaruratan Bencana Strategi 1.1 Meningkatkan Aksesibilitas Layanan dan Efektivitas Pengelolaan Sistem Perrington Dini Program 1.1.1 Pengembangan dan Pemanfaatan MHEWS Sasaran Program:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2205, 'Kementerian/Lembaga Penanggung Jawab bertugas untuk menganggarkan dan melaksanakan setiap kegiatan sesuai dengan kewenangan masing-masing dan melaporkan hasil pelaksanaannya dalam kegiatan pemantauan dan evaluasi. Pada setiap kegiatan juga dilakukan telah ditetapkan Kementerian/Lembaga Kontributor (Pendukung) berperan dalam mendukung pelaksanaan kegiatan oleh Kementerian/Lembaga Penanggung Jawab dalam berbagai bentuk, seperti: melakukan pembahasan substansi, memberikan pertimbangan dan masukan masukan gagasan, memberikan bantuan sumber daya, kerja sama dan kolaborasi pelaksanaan kegiatan, dan lainnya sesuai kewenangan masing-masing. Pada beberapa kegiatan juga telah ditetapkan pihak lainnya yang dapat mendukung atau perlu dilibatkan dalam pelaksanaannya, seperti pemerintah daerah, lembaga usaha, organisasi non pemerintah, perguruan tinggi, media, dan masyarakat.
Tabel 3.1 Rencana Aksi RENAS PB Tahun 2025-2029 TAHUN INSTANSI PAGU BASE- INDIKATIF SUMBER 2 2 2 2 2 TARGET PEMERINTAH KEGIATAN INDIKATOR SATUAN LINE LOKASI (Miliar PENDA- 0 0 0 0 0 2029 PIHAK 2024 Rupiah) NAAN PENANG- KONTRIBU- 2 2 2 2 2 GUNG TOR LAINNYA 5 6 7 8 9 JAWAB Sasaran 1 Mengurangi Jumlah Penduduk Terdampak Bencana melalui Peningkatan Kualitas Kesiapsiagaan, Peringatan Dini, dan Penanggulangan Kedaruratan Bencana Strategi 1.1 Meningkatkan Aksesibilitas Layanan dan Efektivitas Pengelolaan Sistem Perrington Dini Program 1.1.1 Pengembangan dan Pemanfaatan MHEWS Sasaran Program:', 'Lampiran hal. 49', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
