INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2215, 'perban-1-2025', 108, 'lampiran', 'Lampiran hal. 53', NULL, 53, 'Pemerintah, dan Pantauan pengamatan dan lainnya Dalam Negeri, Perguruan Konflik Sosial pantauan konflik Badan Intelijen Tinggi sosial yang Negara diperbarui/ditingk atkan kualitasnya 1.1.2.k Pengembangan Jumlah sarana, unit/jaringan NA 5 Pusat/Nasional 44,99 APBN dan Kementerian ESDM, BRIN Organisasi Jaringan prasarana, dan sumber Kementerian Non Pengamatan jaringan pendanaan Perindustrian Pemerintah, dan Pantauan pengamatan dan lainnya Perguruan Kedaruratan pantauan Tinggi Biologi dan kedaruratan Kimia biologi dan kimia yang diperbarui/ditingk atkan kualitasnya Program 1.2.1. Penguatan Kesiapsiagaan dan Kesiagaan Menghadapi Kedaruratan Bencana dan Krisis Kesehatan Sasaran Program:
