INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2221, 'perban-1-2025', 114, 'lampiran', 'Lampiran hal. 58', NULL, 58, 'Terwujudnya penanganan darurat bencana secara cepat, efektif, dan terkoordinasi TAHUN INSTANSI PAGU BASE- INDIKATIF SUMBER 2 2 2 2 2 TARGET PEMERINTAH KEGIATAN INDIKATOR SATUAN LINE LOKASI (Miliar PENDA- 0 0 0 0 0 2029 PIHAK 2024 Rupiah) NAAN PENANG- KONTRIBU- 2 2 2 2 2 GUNG TOR LAINNYA 5 6 7 8 9 JAWAB 1.2.2.a Pelatihan Jumlah angkatan orang peserta 3.000 17,450 Pusat/Nasion 542,60 APBN dan BNPP/BASARNAS Pemerintah Potensi SAR orang yang al dan sumber Daerah, mendapatkan diprioritaskan pendanaan Organisasi peningkatan untuk Lokus lainnya Non kapasitas terkait Prioritas Pemerintah, pencarian dan Intervensi Organisasi pertolongan dan RENAS PB Masyarakat/ potensi SAR Tahun 2025- Komunitas 2029 1.2.2.b Peningkatan Jumlah Komunitas/kelo 4 5 Pusat/Nasion 8,44 APBN dan BNPP/BASARNAS Pemerintah Kapasitas SDM komunitas/kelom mpok al dan sumber Daerah, Potensi pok masyarakat/ diprioritaskan pendanaan Organisasi Pencarian dan masyarakat/orang orang peserta untuk Lokus lainnya Non Pertolongan yang Prioritas Pemerintah, Berbasis mendapatkan Intervensi Organisasi Komunitas peningkatan RENAS PB Masyarakat/ kapasitas dan Tahun 2025- Komunitas pemberdayaan 2029 terkait pencarian dan pertolongan berbasis komunitas 1.2.2.c First Responder Jumlah latihan Kegiatan 1 5 Pusat/Nasional 0,39 APBN dan BNPP/BASARNAS Organisasi & National peningkatan sumber Non Accreditation kompetensi Tim pendanaan Pemerintah Process Tim Urban SAR di lainnya Usar Kantor SAR 1.2.2.d Penyediaan Jumlah peralatan set N/A');
