INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2257, 'perban-1-2025', 150, 'lampiran', 'Lampiran hal. 79', NULL, 79, 'Terwujudnya penataan ruang dan permukiman serta perencanaan perkotaan yang terpadu terhadap ketahanan bencana dan adaptasi perubahan iklim, serta ketahanan sosial, dan ketahanan kesehatan masyarakat 2.3.1.a Konfirmasi Jumlah dokumen Dokumen 2.339 4678 Diprioritaskan 148,57 APBN Kementerian Kementerian Pemerintah Kesesuaian hasil penilaian di Lokus ATR/BPN, Pekerjaan Daerah Kegiatan kepatuhan KKPR Prioritas BNPB Umum, Pemanfaatan Intervensi Kementerian Ruang RENAS PB Lingkungan Tahun 2025- Hidup, 2029 Kementerian Kelautan dan Perikanan 2.3.1.b Audit Tata Jumlah kasus kasus 32 42 Diprioritaskan 0,64 APBN Kementerian Kementerian Pemerintah Ruang audit tata ruang di Lokus ATR/BPN, Pekerjaan Daerah Prioritas BNPB Umum, Intervensi Kementerian RENAS PB Lingkungan Tahun 2025- Hidup, 2029 Kementerian Kelautan dan Perikanan 2.3.1.c Penataan Jumlah Dokumen/Reko - 1 Diprioritaskan 0,40 APBN dan Kementerian Pemerintah Bangunan dan dokumen/rekome mendasi di Lokus Sumber Pekerjaan Umum Daerah, Lingkungan ndasi kebijakan Kebijakan Prioritas Organisasi TAHUN INSTANSI PAGU BASE- INDIKATIF SUMBER 2 2 2 2 2 TARGET PEMERINTAH KEGIATAN INDIKATOR SATUAN LINE LOKASI (Miliar PENDA- 0 0 0 0 0 2029 PIHAK 2024 Rupiah) NAAN PENANG- KONTRIBU- 2 2 2 2 2 GUNG TOR LAINNYA 5 6 7 8 9 JAWAB Kawasan Rawan penataan Intervensi Pendanaan Non Bencana bangunan dan RENAS PB Lainnya Pemerintah, penataan Tahun 2025- Perguruan lingkungan di 2029 Tinggi, kawasan rawan Organisasi bencana Masyarakat/ Komunitas Program');
