INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2258, 'perban-1-2025', 151, 'lampiran', 'Lampiran hal. 79', NULL, 79, '2.3.2 Peningkatan Kualitas Rencana Tata Ruang Sasaran Program:
