INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2261, 'perban-1-2025', 154, 'lampiran', 'Lampiran hal. 81', NULL, 81, 'Terwujudnya penataan ruang dan permukiman serta perencanaan perkotaan yang terpadu terhadap ketahanan bencana dan adaptasi perubahan iklim, serta ketahanan sosial, dan ketahanan kesehatan masyarakat 2.3.4.a Peningkatan Jumlah Dokumen/Reko - 50 Diprioritaskan 20,00 APBN Kementerian Kementerian Pemerintah Pengawasan rekomendasi mendasi di Lokus Pekerjaan Umum, Perumahan Daerah, Penerapan tindak lanjut Kebijakan Prioritas BNPB dan Kawasan Organisasi Standar penerapan Intervensi Permukiman Non Bangunan standar bangunan RENAS PB Pemerintah, Tahan Bencana tahan bencana Tahun 2025- Lembaga 2029 Usaha, Perguruan TAHUN INSTANSI PAGU BASE- INDIKATIF SUMBER 2 2 2 2 2 TARGET PEMERINTAH KEGIATAN INDIKATOR SATUAN LINE LOKASI (Miliar PENDA- 0 0 0 0 0 2029 PIHAK 2024 Rupiah) NAAN PENANG- KONTRIBU- 2 2 2 2 2 GUNG TOR LAINNYA 5 6 7 8 9 JAWAB Tinggi, Organisasi Masyarakat/ Komunitas 2.3.4.b Pembinaan Jumlah aparatur orang 876 1000 Pusat/Nasional 49,60 APBN dan Kementerian Kementerian Pemerintah Pelaku pemerintah dan Sumber Pekerjaan Umum Perumahan Daerah, Konstruksi dan daerah/ diprioritaskan Pendanaan dan Kawasan Organisasi Pengembang pengembang di Lokus Lainnya Permukiman Non untuk (developer)/pelaku Prioritas Pemerintah, Pembangunan /tenaga kerja Intervensi Lembaga Berketahanan konstruksi yang RENAS PB Usaha, Bencana mendapatkan Tahun 2025- Perguruan pembinaan 2029 Tinggi, pembangunan Organisasi berketahanan Masyarakat/ bencana Komunitas 2.3.4.c Pendidikan dan Jumlah aparatur Orang');
