INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2270, 'perban-1-2025', 163, 'lampiran', 'Lampiran hal. 86', NULL, 86, 'Terwujudnya pelindungan ekosistem laut dan pesisir yang berisiko bencana 2.4.4.a Penyusunan Jumlah Naskah Dokumen - 5 Pusat/Nasional 2,00 APBN dan Kementerian Kementerian Pemerintah NSPK Mitigasi Akademis/RIA/Ur RNA/RIA/Urgen Sumber Lingkungan Hidup Hukum, Daerah, dan Adaptasi gensi/NSPK si/NSPK Pendanaan Kementerian Organisasi Subsiden Tanah terkait mitigasi Lainnya Koordinator Non dan adaptasi Bidang PMK, Pemerintah, subsiden tanah Kementerian Lembaga Koordinator Usaha, Bidang Perguruan Infrastruktur Tinggi, dan Organisasi Pembangunan Masyarakat/ Kewilayahan, Komunitas Kementerian ATR/BPN, BNPB, Kementerian Kelautan dan Perikanan 2.4.3.b Edukasi dan Jumlah aparatur Orang - 1000 Pusat/Nasional 8,00 APBN dan Kementerian Kementerian Pemerintah Peningkatan pemerintah/masy dan Sumber Lingkungan Hidup Hukum, Daerah, Kapasitas arakat yang diprioritaskan Pendanaan Kementerian Organisasi Mitigasi dan mendapatkan di Lokus Lainnya Koordinator Non Adaptasi peningkatan Prioritas Bidang PMK, Pemerintah, Subsiden Tanah pemahaman dan Intervensi Kementerian Lembaga kapasitas terkait RENAS PB Koordinator Usaha, mitigasi dan Tahun 2025- Bidang Perguruan adaptasi subsiden 2029 Infrastruktur Tinggi, tanah dan Organisasi Pembangunan Masyarakat/ Kewilayahan, Komunitas Kementerian ATR/BPN, BNPB, Kementerian Kelautan dan Perikanan Strategi 2.5 Meningkatkan Pemanfaatan Skema Perlindungan Aset dan Transfer Risiko Bencana oleh Masyarakat & Lembaga Usaha TAHUN INSTANSI PAGU BASE- INDIKATIF SUMBER 2 2');
