INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2272, 'perban-1-2025', 165, 'lampiran', 'Lampiran hal. 87', NULL, 87, 'Terwujudnya investasi yang memadai dalam pengurangan risiko bencana untuk ketangguhan 2.5.1.a Pengembangan Jumlah Naskah Dokumen - 1 Pusat/Nasional 0,40 APBN dan BNPB Kementerian Pemerintah Mekanisme Akademis/RIA/Ur RNA/RIA/Urgen sumber Keuangan Daerah, Perlindungan gensi/NSPK si/NSPK pendanaan Organisasi Penghidupan terkait Mekanisme lainnya Non Masyarakat Perlindungan Pemerintah, Penghidupan Lembaga Masyarakat Usaha, Perguruan Tinggi, Organisasi Masyarakat/ Komunitas 2.5.1.b Pengembangan Jumlah Naskah Dokumen - 1 Pusat/Nasional 0,40 APBN dan BNPB Kementerian Pemerintah Mekanisme Akademis/RIA/Ur RNA/RIA/Urge sumber Keuangan Daerah, Perlindungan gensi/NSPK nsi/NSPK pendanaan Organisasi Aset Produktif terkait Mekanisme lainnya Non Masyarakat Perlindungan Aset Pemerintah, produktif Lembaga masyarakat Usaha, Perguruan Tinggi, Organisasi Masyarakat/ Komunitas 2.5.1.c Asuransi Jumlah luas hektar 278.806 1.250.000 Diprioritaskan 7.769,55 APBN dan Kementerian Pemerintah Pertanian pertanaman di Lokus sumber Pertanian Daerah, pertanian yang Prioritas pendanaan Organisasi terlindungi Intervensi lainnya Non asuransi RENAS PB Pemerintah, Tahun 2025- Lembaga 2029 Usaha, Perguruan Tinggi, Organisasi Masyarakat/ Komunitas 2.5.1.d Pengamanan Jumlah areal hektar 25.000 45.000 Diprioritaskan 160,00 APBN dan Kementerian Pemerintah Pertanaman pertanaman di Lokus sumber Pertanian Daerah, Tanaman tanaman pangan Prioritas pendanaan Organisasi Pangan dari yang ditangani Intervensi lainnya Non TAHUN');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2272, 'Terwujudnya investasi yang memadai dalam pengurangan risiko bencana untuk ketangguhan 2.5.1.a Pengembangan Jumlah Naskah Dokumen - 1 Pusat/Nasional 0,40 APBN dan BNPB Kementerian Pemerintah Mekanisme Akademis/RIA/Ur RNA/RIA/Urgen sumber Keuangan Daerah, Perlindungan gensi/NSPK si/NSPK pendanaan Organisasi Penghidupan terkait Mekanisme lainnya Non Masyarakat Perlindungan Pemerintah, Penghidupan Lembaga Masyarakat Usaha, Perguruan Tinggi, Organisasi Masyarakat/ Komunitas 2.5.1.b Pengembangan Jumlah Naskah Dokumen - 1 Pusat/Nasional 0,40 APBN dan BNPB Kementerian Pemerintah Mekanisme Akademis/RIA/Ur RNA/RIA/Urge sumber Keuangan Daerah, Perlindungan gensi/NSPK nsi/NSPK pendanaan Organisasi Aset Produktif terkait Mekanisme lainnya Non Masyarakat Perlindungan Aset Pemerintah, produktif Lembaga masyarakat Usaha, Perguruan Tinggi, Organisasi Masyarakat/ Komunitas 2.5.1.c Asuransi Jumlah luas hektar 278.806 1.250.000 Diprioritaskan 7.769,55 APBN dan Kementerian Pemerintah Pertanian pertanaman di Lokus sumber Pertanian Daerah, pertanian yang Prioritas pendanaan Organisasi terlindungi Intervensi lainnya Non asuransi RENAS PB Pemerintah, Tahun 2025- Lembaga 2029 Usaha, Perguruan Tinggi, Organisasi Masyarakat/ Komunitas 2.5.1.d Pengamanan Jumlah areal hektar 25.000 45.000 Diprioritaskan 160,00 APBN dan Kementerian Pemerintah Pertanaman pertanaman di Lokus sumber Pertanian Daerah, Tanaman tanaman pangan Prioritas pendanaan Organisasi Pangan dari yang ditangani Intervensi lainnya Non TAHUN', 'Lampiran hal. 87', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2273, 'perban-1-2025', 166, 'lampiran', 'Lampiran hal. 87', NULL, 87, 'INSTANSI PAGU BASE- INDIKATIF SUMBER 2 2 2 2 2 TARGET PEMERINTAH KEGIATAN INDIKATOR SATUAN LINE LOKASI (Miliar PENDA- 0 0 0 0 0 2029 PIHAK 2024 Rupiah) NAAN PENANG- KONTRIBU- 2 2 2 2 2 GUNG TOR LAINNYA 5 6 7 8 9 JAWAB Dampak dari dampak RENAS PB Pemerintah, Perubahan perubahan iklim Tahun 2025- Lembaga Iklim 2029 Usaha, (Banjir/Kekerin Perguruan gan) Tinggi, Organisasi Masyarakat/ Komunitas 2.5.1.e Pengamanan Jumlah areal hektar 50.000 55.000 Diprioritaskan 40,00 APBN dan Kementerian Pemerintah Pertanaman serangan di Lokus sumber Pertanian Daerah, Tanaman Organisme Prioritas pendanaan Organisasi Pangan dari Pengganggu Intervensi lainnya Non Organisme Tanaman yang RENAS PB Pemerintah, Pengganggu ditangani Tahun 2025- Lembaga Tanaman (OPT) 2029 Usaha, Perguruan Tinggi, Organisasi Masyarakat/ Komunitas Sasaran 3 Meningkatkan Daya Lenting di Daerah Terdampak melalui Peningkatan Percepatan Rehabilitasi dan Rekonstruksi Strategi 3.1 Meningkatkan Kualitas Perencanaan dan Percepatan Pelaksanaan Rehabilitasi dan Rekonstruksi Pascabencana Berbasis Tata Ruang dan Pengurangan Risiko Bencana Program 3.1.1 Penguatan Kapasitas SDM untuk Perencanaan Rehabilitasi dan Rekonstruksi Sasaran Program:
1) Meningkatnya kualitas SDM pemerintah dalam perencanaan rehabilitasi dan rekonstruksi 2) Meningkatnya kualitas dokumen perencanaan rehabilitasi dan rekonstruksi Fokus Capaian RIPB 2025-2029 Fokus Capaian 11:');
