INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2275, 'Pemerintah Readiness negara yang penerima sumber Keuangan Daerah, Criteria mendapatkan hibah pendanaan Organisasi Pelaksanaan peningkatan pemulihan lainnya Non Pemulihan kapasitas pasca Pemerintah, Rehabilitasi dan readiness criteria bencana Perguruan Rekonstruksi pemulihan Tinggi Pasca Bencana rehabilitasi dan rekonstruksi pasca bencana Program 3.1.2 Percepatan Pelaksanaan Rehabilitasi dan Rekonstruksi Sasaran Program:
