INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2276, 'perban-1-2025', 169, 'lampiran', 'Lampiran hal. 89', NULL, 89, 'Terwujudnya pemulihan daerah terdampak bencana yang lebih baik, aman, dan berkelanjutan dengan memperhatikan pengurangan risiko bencana 3.1.2.a Koordinasi Jumlah Rekomendasi 42 52 Pusat/Nasional 5,57 APBN Kementerian Kementerian Identifikasi rekomendasi kebijakan Koordinator Bidang PPN/BAPPENA Pendanaan kebijakan PMK, BNPB S, Kementerian untuk Rencana identifikasi Keuangan, Rehabilitasi pendanaan untuk Kementerian Rekonstruksi R3P BUMN Pasca Bencana TAHUN INSTANSI PAGU BASE- INDIKATIF SUMBER 2 2 2 2 2 TARGET PEMERINTAH KEGIATAN INDIKATOR SATUAN LINE LOKASI (Miliar PENDA- 0 0 0 0 0 2029 PIHAK 2024 Rupiah) NAAN PENANG- KONTRIBU- 2 2 2 2 2 GUNG TOR LAINNYA 5 6 7 8 9 JAWAB 3.1.2.b Pendampingan Daerah yang daerah 8 10 Daerah 0,13 APBN Kementerian Dalam BNPB Pemerintah Pemerintah menerapkan (provinsi/kabup terdampak Negeri Daerah, Daerah dalam layanan aten/kota) bencana Organisasi Pelayanan pemerintah saat Non Pemerintahan pasca bencana Pemerintah, Saat Pasca Perguruan Bencana Tinggi 3.1.2.c Rehabilitasi dan Jumlah rumah rumah/unit/pa 1.160 5.802 Daerah 278,48 APBN dan Kementerian BNPB, Pemerintah Rekonstruksi dan sarpras ket penerima sumber Perumahan dan Kementerian Daerah, Sektor permukiman yang bantuan pendanaan Kawasan ATR/BPN, Organisasi Perumahan direhabilitasi/ stimulan lainnya Permukiman Kementerian Non direkonstruksi perbaikan BUMN Pemerintah, rumah Lembaga Usaha, Perguruan Tinggi, Organisasi Masyarakat /Komunitas 3.1.2.d Rehabilitasi dan Jumlah unit/kilometer 45.083');
