INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2297, 'perban-1-2025', 190, 'lampiran', 'Lampiran hal. 101', NULL, 101, 'Lainnya Kementerian Organisasi Pemantauan, terkait Koordinator Non dan Evaluasi Pembinaan, Bidang PMK, Pemerintah, Penerapan SPM Pemantauan, dan Kementerian Perguruan Sub Urusan Evaluasi PPN/BAPPENA Tinggi Bencana Penerapan SPM S Sub-Urusan Bencana 4.2.1.d Penguatan Jumlah Naskah Dokumen 10 Pusat/Nasional 4,00 APBN, Sumber BNPB, Kementerian Kementerian Pemerintah NSPK Akademis/RIA/Ur RNA/RIA/Urgen Pendanaan Dalam Negeri Hukum, Daerah, Penerapan SPM gensi/NSPK si/NSPK Lainnya Kementerian Organisasi Sub Urusan terkait Penerapan Koordinator Non Bencana SPM Sub-Urusan Bidang PMK, Pemerintah, Bencana Kementerian Perguruan PPN/BAPPENA Tinggi S 4.2.1.e Penguatan Jumlah daerah Daerah 25 50 Diprioritaskan 1,63 APBN Kementerian Dalam BNPB Pemerintah Kecamatan yang dibina dalam di lokasi Lokus Negeri Daerah, dalam penerapan Prioritas Organisasi Menghadapi kecamatan Intervensi Non Bencana tangguh bencana RENAS PB Pemerintah, dalam mendukung Tahun 2025- Perguruan layanan dasar 2029 Tinggi, Organisasi Masyarakat/ Komunitas 4.2.1.f Penguatan Jumlah bantuan Daerah 77 100 Diprioritaskan 26,14 APBN Kementerian Dalam BNPB, Pemerintah Sarana sarana pendukung di lokasi Lokus Negeri Kementerian Daerah, Pendukung dalam rangka Prioritas Organisasi TAHUN INSTANSI PAGU BASE- INDIKATIF SUMBER 2 2 2 2 2 TARGET PEMERINTAH KEGIATAN INDIKATOR SATUAN LINE LOKASI (Miliar PENDA- 0 0 0 0 0 2029 PIHAK 2024 Rupiah) NAAN PENANG- KONTRIBU- 2 2 2 2 2 GUNG TOR LAINNYA 5 6 7 8 9 JAWAB Penerapan SPM implementasi SPM');
