INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2320, 'perban-1-2025', 213, 'lampiran', 'Lampiran hal. 115', NULL, 115, 'Terwujudnya tata kelola risiko bencana yang sinergis antara pusat dan daerah 4.8.2.a Komunikasi, Jumlah orang Orang peserta 723 1.000 Pusat/Nasional 40,00 APBN dan BNPB Kementerian Pemerintah Informasi, dan yang per tahun sumber Luar Negeri, Daerah, Edukasi tentang mendapatkan pendanaan Kementerian Organisasi Resiliensi peningkatan lainnya PPN/BAPPENA Non Berkelanjutan pemahaman S Pemerintah, terkait resiliensi Lembaga berkelanjutan Usaha, Media, Perguruan Tinggi, Organisasi Masyarakat/ Komunitas Program 4.8.3 Penguatan Kerja Sama dan Kemitraan untuk Resiliensi Berkelanjutan Sasaran Program:
Meningkatnya jumlah kegiatan kerja sama dan kemitraan untuk resiliensi berkelanjutan Fokus Capaian RIPB 2025-2029 Fokus Capaian 5:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2320, 'Terwujudnya tata kelola risiko bencana yang sinergis antara pusat dan daerah 4.8.2.a Komunikasi, Jumlah orang Orang peserta 723 1.000 Pusat/Nasional 40,00 APBN dan BNPB Kementerian Pemerintah Informasi, dan yang per tahun sumber Luar Negeri, Daerah, Edukasi tentang mendapatkan pendanaan Kementerian Organisasi Resiliensi peningkatan lainnya PPN/BAPPENA Non Berkelanjutan pemahaman S Pemerintah, terkait resiliensi Lembaga berkelanjutan Usaha, Media, Perguruan Tinggi, Organisasi Masyarakat/ Komunitas Program 4.8.3 Penguatan Kerja Sama dan Kemitraan untuk Resiliensi Berkelanjutan Sasaran Program:
Meningkatnya jumlah kegiatan kerja sama dan kemitraan untuk resiliensi berkelanjutan Fokus Capaian RIPB 2025-2029 Fokus Capaian 5:', 'Lampiran hal. 115', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2321, 'perban-1-2025', 214, 'lampiran', 'Lampiran hal. 115', NULL, 115, 'Terwujudnya tata kelola risiko bencana yang sinergis antara pusat dan daerah 4.8.3.a Pengembangan 1) Jumlah 1)jejaring/forum 1)1 forum 1)2 forum Pusat/Nasional 39,56 APBN dan BNPB, Kementerian Kementerian Pemerintah Jaringan dan jejaring/forum 2)orang/forum 2)2 forum 2)2 forum sumber Luar Negeri Koordinator Daerah, Forum Multi Resiliensi 3)dokumen 3)2 3)3 pendanaan Bidang PMK, Organisasi Pemangku Berkelanjutan (outcome dokume dokumen lainnya Kementerian Non Kepentingan yang terbentuk documents) n PPN/BAPPENA Pemerintah, untuk Resiliensi 2) Jumlah S Lembaga Berkelanjutan orang/forum Usaha, yang Media, mendapatkan Perguruan pembinaan/pend Tinggi, ampingan/penin Organisasi gkatan kapasitas TAHUN INSTANSI PAGU BASE- INDIKATIF SUMBER 2 2 2 2 2 TARGET PEMERINTAH KEGIATAN INDIKATOR SATUAN LINE LOKASI (Miliar PENDA- 0 0 0 0 0 2029 PIHAK 2024 Rupiah) NAAN PENANG- KONTRIBU- 2 2 2 2 2 GUNG TOR LAINNYA 5 6 7 8 9 JAWAB terkait Resiliensi Masyarakat/ Berkelanjutan Komunitas 3) Jumlah dokumen (outcome documents) terkait resiliensi berkelanjutan dalam forum regional 4.8.3.b Promosi Jumlah Dokumen/Reko 2 7 Pusat/Nasional 2,79 APBN dan BNPB, Kementerian Kementerian Pemerintah Resiliensi rekomendasi mendasi sumber Luar Negeri Koordinator Daerah, Berkelanjutan kebijakan untuk Kebijakan pendanaan Bidang PMK, Organisasi melalui promosi resiliensi lainnya Kementerian Non Kolaborasi berkelanjutan di PPN/BAPPENA Pemerintah, dengan forum/pertemuan S Lembaga Organisasi tingkat nasional Usaha, Nasional');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2321, 'Terwujudnya tata kelola risiko bencana yang sinergis antara pusat dan daerah 4.8.3.a Pengembangan 1) Jumlah 1)jejaring/forum 1)1 forum 1)2 forum Pusat/Nasional 39,56 APBN dan BNPB, Kementerian Kementerian Pemerintah Jaringan dan jejaring/forum 2)orang/forum 2)2 forum 2)2 forum sumber Luar Negeri Koordinator Daerah, Forum Multi Resiliensi 3)dokumen 3)2 3)3 pendanaan Bidang PMK, Organisasi Pemangku Berkelanjutan (outcome dokume dokumen lainnya Kementerian Non Kepentingan yang terbentuk documents) n PPN/BAPPENA Pemerintah, untuk Resiliensi 2) Jumlah S Lembaga Berkelanjutan orang/forum Usaha, yang Media, mendapatkan Perguruan pembinaan/pend Tinggi, ampingan/penin Organisasi gkatan kapasitas TAHUN INSTANSI PAGU BASE- INDIKATIF SUMBER 2 2 2 2 2 TARGET PEMERINTAH KEGIATAN INDIKATOR SATUAN LINE LOKASI (Miliar PENDA- 0 0 0 0 0 2029 PIHAK 2024 Rupiah) NAAN PENANG- KONTRIBU- 2 2 2 2 2 GUNG TOR LAINNYA 5 6 7 8 9 JAWAB terkait Resiliensi Masyarakat/ Berkelanjutan Komunitas 3) Jumlah dokumen (outcome documents) terkait resiliensi berkelanjutan dalam forum regional 4.8.3.b Promosi Jumlah Dokumen/Reko 2 7 Pusat/Nasional 2,79 APBN dan BNPB, Kementerian Kementerian Pemerintah Resiliensi rekomendasi mendasi sumber Luar Negeri Koordinator Daerah, Berkelanjutan kebijakan untuk Kebijakan pendanaan Bidang PMK, Organisasi melalui promosi resiliensi lainnya Kementerian Non Kolaborasi berkelanjutan di PPN/BAPPENA Pemerintah, dengan forum/pertemuan S Lembaga Organisasi tingkat nasional Usaha, Nasional', 'Lampiran hal. 115', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2322, 'perban-1-2025', 215, 'lampiran', 'Lampiran hal. 115', NULL, 115, 'dan dan internasional Media, Internasional Perguruan Tinggi, Organisasi Masyarakat/ Komunitas BAB IV KAIDAH PELAKSANAAN Tujuan RENAS PB Tahun 2025-2029 dapat terwujud melalui partisipasi semua pihak dalam penanggulangan bencana dan sesuai dengan sifat kebencanaan yang inklusif. RENAS PB Tahun 2025-2029 harus menjadi acuan oleh para pihak dalam melaksanakan penanggulangan bencana sesuai peran masing-masing melalui kaidah pelaksanaan. Kaidah pelaksanaan RENAS PB meliputi pemaduan dalam rencana pembangunan, kerangka regulasi, kelembagaan, pendanaan, dan kerangka pemantauan, pengendalian dan evaluasi.
4.1. Pemaduan Rencana Nasional Penanggulangan Bencana Tahun 2025-2029 dalam Rencana Pembangunan Pasal 6 Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana telah menekankan bahwa perencanaan penanggulangan bencana merupakan bagian dari perencanaan pembangunan. Pemaduan RENAS PB Tahun 2025-2029 dalam rencana pembangunan diperlukan untuk memastikan mencantumkan unsur-unsur rencana penanggulangan bencana ke dalam rencana pembangunan pusat dan daerah. Penjabaran program dan kegiatan penanggulangan bencana dan rincian anggarannya dalam RENAS PB Tahun 2025-2029 dengan sistem perencanaan pembangunan nasional agar dapat dilaksanakan. Pemaduan tersebut juga penting untuk dilakukan agar program dan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029 dapat dianggarkan melalui APBN dan kemudian dilaksanakan oleh Kementerian/Lembaga terkait.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2322, 'dan dan internasional Media, Internasional Perguruan Tinggi, Organisasi Masyarakat/ Komunitas BAB IV KAIDAH PELAKSANAAN Tujuan RENAS PB Tahun 2025-2029 dapat terwujud melalui partisipasi semua pihak dalam penanggulangan bencana dan sesuai dengan sifat kebencanaan yang inklusif. RENAS PB Tahun 2025-2029 harus menjadi acuan oleh para pihak dalam melaksanakan penanggulangan bencana sesuai peran masing-masing melalui kaidah pelaksanaan. Kaidah pelaksanaan RENAS PB meliputi pemaduan dalam rencana pembangunan, kerangka regulasi, kelembagaan, pendanaan, dan kerangka pemantauan, pengendalian dan evaluasi.
4.1. Pemaduan Rencana Nasional Penanggulangan Bencana Tahun 2025-2029 dalam Rencana Pembangunan Pasal 6 Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana telah menekankan bahwa perencanaan penanggulangan bencana merupakan bagian dari perencanaan pembangunan. Pemaduan RENAS PB Tahun 2025-2029 dalam rencana pembangunan diperlukan untuk memastikan mencantumkan unsur-unsur rencana penanggulangan bencana ke dalam rencana pembangunan pusat dan daerah. Penjabaran program dan kegiatan penanggulangan bencana dan rincian anggarannya dalam RENAS PB Tahun 2025-2029 dengan sistem perencanaan pembangunan nasional agar dapat dilaksanakan. Pemaduan tersebut juga penting untuk dilakukan agar program dan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029 dapat dianggarkan melalui APBN dan kemudian dilaksanakan oleh Kementerian/Lembaga terkait.', 'Lampiran hal. 115', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2323, 'perban-1-2025', 216, 'lampiran', 'Lampiran hal. 117', NULL, 117, 'Gambar 4.1 Kerangka Pemaduan RENAS PB Tahun 2025-2029 ke dalam Rencana Pembangunan dan Penganggaran di Tingkat Nasional dan Daerah Pemaduan RENAS PB Tahun 2025-2029 dengan rencana pembangunan, terutama RPJMN dan Renstra Kementerian/Lembaga dilakukan dengan sinkronisasi periodisasi dengan RPJMN maupun Rentra Kementerian/Lembaga dalam jangka menengah 2025-2029. Rencana aksi dalam RENAS PB Tahun 2025- 2029 memiliki program dan kegiatan yang telah dirincikan tahun pelaksanaan, instansi penanggung jawab, dan indikasi pendanaannya. Program dan kegiatan tersebut penting untuk dikoordinasikan, diintegrasikan, dan tersinkronisasi ke dalam Rencana Kerja Pemerintah (RKP) dan Rencana Kerja (Renja) Kementerian/Lembaga untuk dapat dilaksanakan dan dianggarkan setiap tahunnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2323, 'Gambar 4.1 Kerangka Pemaduan RENAS PB Tahun 2025-2029 ke dalam Rencana Pembangunan dan Penganggaran di Tingkat Nasional dan Daerah Pemaduan RENAS PB Tahun 2025-2029 dengan rencana pembangunan, terutama RPJMN dan Renstra Kementerian/Lembaga dilakukan dengan sinkronisasi periodisasi dengan RPJMN maupun Rentra Kementerian/Lembaga dalam jangka menengah 2025-2029. Rencana aksi dalam RENAS PB Tahun 2025- 2029 memiliki program dan kegiatan yang telah dirincikan tahun pelaksanaan, instansi penanggung jawab, dan indikasi pendanaannya. Program dan kegiatan tersebut penting untuk dikoordinasikan, diintegrasikan, dan tersinkronisasi ke dalam Rencana Kerja Pemerintah (RKP) dan Rencana Kerja (Renja) Kementerian/Lembaga untuk dapat dilaksanakan dan dianggarkan setiap tahunnya.', 'Lampiran hal. 117', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2324, 'perban-1-2025', 217, 'lampiran', 'Lampiran hal. 118', NULL, 118, 'RENAS PB Tahun 2025-2029 juga menjadi acuan bagi pemerintah daerah dalam menyusun dan menetapkan Rencana Penanggulangan Bencana (RPB)daerah. Rencana Penanggulangan Bencana (RPB) yang telah ditetapkan oleh pemerintah daerah wajib untuk dipadukan dengan perencanaan pembangunan di daerah. Pemaduan Rencana Penanggulangan Bencana (RPB) daerah ke dalam Rencana Pembangunan Jangka Menengah Daerah dan Renstra Perangkat Daerah dilakukan untuk menjamin unsur-unsur penanggulangan bencana masuk ke dalam rencana pembangunan di daerah. RENAS PB Tahun 2025-2029 telah menetapkan arah kebijakan penanggulangan bencana per wilayah dan lokus prioritas. Selain kebijakan, strategi, dan rencana aksi dalam RENAS PB Tahun 2025-2029, kedua substansi tersebut penting untuk diperhatikan oleh pemerintah daerah dalam menyusun RPB untuk menyelaraskan upaya-upaya penanggulangan bencana yang diarahkan di masing-masing wilayah dan diprioritaskan di masing-masing lokasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2324, 'RENAS PB Tahun 2025-2029 juga menjadi acuan bagi pemerintah daerah dalam menyusun dan menetapkan Rencana Penanggulangan Bencana (RPB)daerah. Rencana Penanggulangan Bencana (RPB) yang telah ditetapkan oleh pemerintah daerah wajib untuk dipadukan dengan perencanaan pembangunan di daerah. Pemaduan Rencana Penanggulangan Bencana (RPB) daerah ke dalam Rencana Pembangunan Jangka Menengah Daerah dan Renstra Perangkat Daerah dilakukan untuk menjamin unsur-unsur penanggulangan bencana masuk ke dalam rencana pembangunan di daerah. RENAS PB Tahun 2025-2029 telah menetapkan arah kebijakan penanggulangan bencana per wilayah dan lokus prioritas. Selain kebijakan, strategi, dan rencana aksi dalam RENAS PB Tahun 2025-2029, kedua substansi tersebut penting untuk diperhatikan oleh pemerintah daerah dalam menyusun RPB untuk menyelaraskan upaya-upaya penanggulangan bencana yang diarahkan di masing-masing wilayah dan diprioritaskan di masing-masing lokasi.', 'Lampiran hal. 118', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2325, 'perban-1-2025', 218, 'lampiran', 'Lampiran hal. 118', NULL, 118, '4.2. Kerangka Regulasi Pencapaian tujuan dan sasaran RENAS PB Tahun 2025-209 perlu didukung oleh regulasi yang terharmonisasi dengan peraturan perundangan lainnya yang berlaku. Peningkatan sinkronisasi regulasi yaitu dengan memperhatikan peningkatan kuantitas dan kualitas regulasi yang diyakini dapat membantu memfasilitasi dan mendorong efektivitas pelaksanaan agenda penanggulangan bencana di jangka menengah ke depan serta mengatur pelaku sistem penanggulangan bencana. Regulasi yang dibutuhkan untuk implementasi dan pencapaian tujuan dan sasaran RENAS PB Tahun 2025-2029 perlu disusun dengan memperhatikan kaidah-kaidah pementukan regulasi yang berlaku. Kerangka regulasi yang disusun harus disusun secara sederhana, fleksibel, mudah dipahami, tertib, dan dapat berlaku efektif serta dapat memberikan manfaat dalam pelaksanaan penanggulangan bencana.
Tabel 4.1 Kebutuhan Regulasi dalam Mendukung Implementasi RENAS PB Tahun 2025-2029 SASARAN RENAS PB TAHUN SUBSTANSI UTAMA 2025-2029 Sasaran 1 a. Pengelolaan Multi Hazard Early Warning Mengurangi Jumlah Penduduk System (MHEWS) Terdampak Bencana melalui b. Standarisasi peringatan dini bencana Peningkatan Kualitas c. Kerangka kerja penilaian risiko, peringatan Kesiapsiagaan, Peringatan dini, dan sistem pendukung keputusan Dini, dan Penanggulangan d. Status tingkatan bencana Kedaruratan Bencana e. Standar pengadaan rambu informasi, jalur evakuasi di bangunan layanan umum dan kawasan permukiman');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2325, '4.2. Kerangka Regulasi Pencapaian tujuan dan sasaran RENAS PB Tahun 2025-209 perlu didukung oleh regulasi yang terharmonisasi dengan peraturan perundangan lainnya yang berlaku. Peningkatan sinkronisasi regulasi yaitu dengan memperhatikan peningkatan kuantitas dan kualitas regulasi yang diyakini dapat membantu memfasilitasi dan mendorong efektivitas pelaksanaan agenda penanggulangan bencana di jangka menengah ke depan serta mengatur pelaku sistem penanggulangan bencana. Regulasi yang dibutuhkan untuk implementasi dan pencapaian tujuan dan sasaran RENAS PB Tahun 2025-2029 perlu disusun dengan memperhatikan kaidah-kaidah pementukan regulasi yang berlaku. Kerangka regulasi yang disusun harus disusun secara sederhana, fleksibel, mudah dipahami, tertib, dan dapat berlaku efektif serta dapat memberikan manfaat dalam pelaksanaan penanggulangan bencana.
Tabel 4.1 Kebutuhan Regulasi dalam Mendukung Implementasi RENAS PB Tahun 2025-2029 SASARAN RENAS PB TAHUN SUBSTANSI UTAMA 2025-2029 Sasaran 1 a. Pengelolaan Multi Hazard Early Warning Mengurangi Jumlah Penduduk System (MHEWS) Terdampak Bencana melalui b. Standarisasi peringatan dini bencana Peningkatan Kualitas c. Kerangka kerja penilaian risiko, peringatan Kesiapsiagaan, Peringatan dini, dan sistem pendukung keputusan Dini, dan Penanggulangan d. Status tingkatan bencana Kedaruratan Bencana e. Standar pengadaan rambu informasi, jalur evakuasi di bangunan layanan umum dan kawasan permukiman', 'Lampiran hal. 118', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2326, 'perban-1-2025', 219, 'lampiran', 'Lampiran hal. 118', NULL, 118, 'f. Penanggulangan kedaruratan bencana (termasuk operasi tanggap darurat dan mobilisasi sumber daya)
g. Tim Reaksi Cepat penanggulangan bencana multisektor
h. Standar minimum bantuan kemanusiaan
i. Kerangka penanggulangan kedaruratan bencana
j. Manajemen standar logistik dan peralatan SASARAN RENAS PB TAHUN SUBSTANSI UTAMA 2025-2029 Sasaran 2 a. Persyaratan analisis risiko bencana Mengurangi Dampak b. Standar ketahanan infrastruktur Kerusakan Dan Kerugian c. Persyaratan minimum jalur penyelamatan Akibat Bencana Melalui d. Upaya mitigasi bencana untuk mengurangi Peningkatan Efektivitas Upaya dampak bencana Pencegahan, Mitigasi Bencana dan Ketahanan Iklim Sasaran 3 a. Pemulihan dan peningkatan sosial, Meningkatkan Daya Lenting di ekonomi, dan sda daerah terdampak Daerah Terdampak Melalui bencana Peningkatan Kualitas b. Pemulihan dan peningkatan fisik daerah Rehabilitasi dan Rekonstruksi terdampak bencana Sasaran 4 a. Penguatan kelembagaan BPBD Meningkatkan Pelayanan dan b. Pendanaan penanggulangan bencana Kapasitas Penanggulangan c. Pelayanan dan kerangka kerja Bencana Melalui Transformasi penanggulangan bencana Tata Kelola dan Kolaborasi d. Kerangka pemantauan dan evaluasi Multi-pihak penanggulangan bencana
e. Pelayanan penyelenggaraan penanggulangan bencana
f. Pengawasan dan sanksi penanggulangan bencana
g. Mekanisme akuntabilitas dan transparansi operasi penanggulangan bencana
h. Pencatatan dana penanggulangan bencana bersumber dari masyarakat');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2326, 'f. Penanggulangan kedaruratan bencana (termasuk operasi tanggap darurat dan mobilisasi sumber daya)
g. Tim Reaksi Cepat penanggulangan bencana multisektor
h. Standar minimum bantuan kemanusiaan
i. Kerangka penanggulangan kedaruratan bencana
j. Manajemen standar logistik dan peralatan SASARAN RENAS PB TAHUN SUBSTANSI UTAMA 2025-2029 Sasaran 2 a. Persyaratan analisis risiko bencana Mengurangi Dampak b. Standar ketahanan infrastruktur Kerusakan Dan Kerugian c. Persyaratan minimum jalur penyelamatan Akibat Bencana Melalui d. Upaya mitigasi bencana untuk mengurangi Peningkatan Efektivitas Upaya dampak bencana Pencegahan, Mitigasi Bencana dan Ketahanan Iklim Sasaran 3 a. Pemulihan dan peningkatan sosial, Meningkatkan Daya Lenting di ekonomi, dan sda daerah terdampak Daerah Terdampak Melalui bencana Peningkatan Kualitas b. Pemulihan dan peningkatan fisik daerah Rehabilitasi dan Rekonstruksi terdampak bencana Sasaran 4 a. Penguatan kelembagaan BPBD Meningkatkan Pelayanan dan b. Pendanaan penanggulangan bencana Kapasitas Penanggulangan c. Pelayanan dan kerangka kerja Bencana Melalui Transformasi penanggulangan bencana Tata Kelola dan Kolaborasi d. Kerangka pemantauan dan evaluasi Multi-pihak penanggulangan bencana
e. Pelayanan penyelenggaraan penanggulangan bencana
f. Pengawasan dan sanksi penanggulangan bencana
g. Mekanisme akuntabilitas dan transparansi operasi penanggulangan bencana
h. Pencatatan dana penanggulangan bencana bersumber dari masyarakat', 'Lampiran hal. 118', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2327, 'perban-1-2025', 220, 'lampiran', 'Lampiran hal. 119', NULL, 119, 'i. Struktur komando, koordinasi, dan interoperabilitas komunikasi 4.3. Kerangka Kelembagaan Agar tatanan kebijakan dan regulasi yang dirumuskan dapat diimplementasikan, maka perlu penataan kelembagaan yang sesuai dengan kebutuhan pelaksanaan peraturan perundangan di atas dan juga sesuai dengan kapasitas pelaksanaan (atau sistem operasional) sehingga dapat dicapai tujuan dalam kebijakan yang bersangkutan secara efektif. Kerangka kelembagaan yang dimaksud dalam RENAS PB Tahun 2025-2029 terdiri dari organisasi berikut sumber daya manusianya. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana telah menetapkan tanggung jawab dan wewenang pemerintah dan pemerintah daerah, serta peran lembaga usaha, lembaga internasional, dan masyarakat dalam penyelenggaraan penanggulangan bencana.
RENAS PB Tahun 2025-2029 telah menetapkan aksi-aksi yang diagendakan sebagai upaya penanggulangan bencana ke depan untuk dilaksanakan oleh Kementerian/Lembaga sesuai dengan alokasi tugas pokok, kewenangan, dan sumber daya yang dimiliki. Berdasarkan pengalokasian tugas pokok dan kewenangan tersebut, implementasi RENAS PB Tahun 2025-2029 memerlukan pelaksana kegiatan yang terbagi menjadi 2 (dua) kelompok utama, yaitu Kementerian/Lembaga Nonkementerian Penanggung Jawab Utama dan Kementerian/Lembaga Nonkementerian Pendukung/Kontributor.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2327, 'i. Struktur komando, koordinasi, dan interoperabilitas komunikasi 4.3. Kerangka Kelembagaan Agar tatanan kebijakan dan regulasi yang dirumuskan dapat diimplementasikan, maka perlu penataan kelembagaan yang sesuai dengan kebutuhan pelaksanaan peraturan perundangan di atas dan juga sesuai dengan kapasitas pelaksanaan (atau sistem operasional) sehingga dapat dicapai tujuan dalam kebijakan yang bersangkutan secara efektif. Kerangka kelembagaan yang dimaksud dalam RENAS PB Tahun 2025-2029 terdiri dari organisasi berikut sumber daya manusianya. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana telah menetapkan tanggung jawab dan wewenang pemerintah dan pemerintah daerah, serta peran lembaga usaha, lembaga internasional, dan masyarakat dalam penyelenggaraan penanggulangan bencana.
RENAS PB Tahun 2025-2029 telah menetapkan aksi-aksi yang diagendakan sebagai upaya penanggulangan bencana ke depan untuk dilaksanakan oleh Kementerian/Lembaga sesuai dengan alokasi tugas pokok, kewenangan, dan sumber daya yang dimiliki. Berdasarkan pengalokasian tugas pokok dan kewenangan tersebut, implementasi RENAS PB Tahun 2025-2029 memerlukan pelaksana kegiatan yang terbagi menjadi 2 (dua) kelompok utama, yaitu Kementerian/Lembaga Nonkementerian Penanggung Jawab Utama dan Kementerian/Lembaga Nonkementerian Pendukung/Kontributor.', 'Lampiran hal. 119', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2328, 'perban-1-2025', 221, 'lampiran', 'Lampiran hal. 120', NULL, 120, 'Gambar 4.2 Peta Kontribusi Kementerian/Lembaga Non Kementerian dalam Pencapaian Sasaran Renas PB Tahun 2025-2029 Pemerintah daerah berkontribusi dalam pencapaian sasaran RENAS PB Tahun 2025-2029 dengan menyelaraskan kebijakan, strategi, dan arah kebijakan per wilayah RENAS PB Tahun 2025-2029 dengan Rencana Penanggulangan Bencana (RPB) daerah yang kemudian dipadukan dengan Rencana Pembangunan Jangka Menengah Daerah. Pemerintah daerah dapat juga berkontribusi dalam pelaksanaan program dan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029 dengan melakukan kolaborasi pelaksanaan kegiatan, sinergi penerima manfaat (beneficiaries), sinergi lokasi pelaksanaan kegiatan, termasuk memberikan dukungan sumber daya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2328, 'Gambar 4.2 Peta Kontribusi Kementerian/Lembaga Non Kementerian dalam Pencapaian Sasaran Renas PB Tahun 2025-2029 Pemerintah daerah berkontribusi dalam pencapaian sasaran RENAS PB Tahun 2025-2029 dengan menyelaraskan kebijakan, strategi, dan arah kebijakan per wilayah RENAS PB Tahun 2025-2029 dengan Rencana Penanggulangan Bencana (RPB) daerah yang kemudian dipadukan dengan Rencana Pembangunan Jangka Menengah Daerah. Pemerintah daerah dapat juga berkontribusi dalam pelaksanaan program dan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029 dengan melakukan kolaborasi pelaksanaan kegiatan, sinergi penerima manfaat (beneficiaries), sinergi lokasi pelaksanaan kegiatan, termasuk memberikan dukungan sumber daya.', 'Lampiran hal. 120', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2329, 'perban-1-2025', 222, 'lampiran', 'Lampiran hal. 120', NULL, 120, 'Bagi pihak nonpemerintah, seperti lembaga usaha, organisasi non pemerintah, lembaga internasional, perguruan tinggi, media, dan organisasi masyarakat atau komunitas, dapat berkontribusi dan berpartisipasi dengan memberikan dukungan sumber daya sesuai dengan ragam aset, potensi, minat dan kewenangan masing-masing. Kontribusi dan partisipasi dari pihak non pemerintah diarahkan melalui kemitraan multipihak dalam bentuk kemitraan pelaksanaan, pengetahuan, standardisasi, pendanaan, dan lainnya sesuai dengan kesepakatan dan inisiatif sukarela seluruh pihak. Untuk meningkatkan koordinasi dan dalam rangka menghasilkan pemetaan peran pihak nonpemerintah dalam pelaksanaan RENAS PB Tahun 2025-2029, dapat dilakukan melalui forum multipihak minimal 1 (satu) tahun sekali di tingkat nasional.
4.4. Kerangka Pendanaan Pendanaan penanggulangan bencana ditujukan untuk membantu upaya penanggulangan bencana yang efektif, efisien, dan akuntabel. Sumber pendanaan pelaksanaan RENAS PB Tahun 2025-2029 bersumber dari Anggaran Pendapatan Belanja Negara, dukungan dari sektor swasta, dan lembaga donor, baik regional maupun internasional. Untuk mendorong efisiensi pemanfaatan APBN, pelaksanaan RENAS PB Tahun 2025-2029 juga perlu untuk mengoptimalkan pemanfaatan sumber pendanaan lainnya dan mengembangkan skema pendanaan inovatif terutama dalam pembiayaan risiko. Kerangka pendanaan dalam RENAS PB Tahun 2025-2029 mencakup sumber pendanaan, arah pemanfaatan dan prinsip pelaksanaan pendanaan sebagai berikut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2329, 'Bagi pihak nonpemerintah, seperti lembaga usaha, organisasi non pemerintah, lembaga internasional, perguruan tinggi, media, dan organisasi masyarakat atau komunitas, dapat berkontribusi dan berpartisipasi dengan memberikan dukungan sumber daya sesuai dengan ragam aset, potensi, minat dan kewenangan masing-masing. Kontribusi dan partisipasi dari pihak non pemerintah diarahkan melalui kemitraan multipihak dalam bentuk kemitraan pelaksanaan, pengetahuan, standardisasi, pendanaan, dan lainnya sesuai dengan kesepakatan dan inisiatif sukarela seluruh pihak. Untuk meningkatkan koordinasi dan dalam rangka menghasilkan pemetaan peran pihak nonpemerintah dalam pelaksanaan RENAS PB Tahun 2025-2029, dapat dilakukan melalui forum multipihak minimal 1 (satu) tahun sekali di tingkat nasional.
4.4. Kerangka Pendanaan Pendanaan penanggulangan bencana ditujukan untuk membantu upaya penanggulangan bencana yang efektif, efisien, dan akuntabel. Sumber pendanaan pelaksanaan RENAS PB Tahun 2025-2029 bersumber dari Anggaran Pendapatan Belanja Negara, dukungan dari sektor swasta, dan lembaga donor, baik regional maupun internasional. Untuk mendorong efisiensi pemanfaatan APBN, pelaksanaan RENAS PB Tahun 2025-2029 juga perlu untuk mengoptimalkan pemanfaatan sumber pendanaan lainnya dan mengembangkan skema pendanaan inovatif terutama dalam pembiayaan risiko. Kerangka pendanaan dalam RENAS PB Tahun 2025-2029 mencakup sumber pendanaan, arah pemanfaatan dan prinsip pelaksanaan pendanaan sebagai berikut.', 'Lampiran hal. 120', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2330, 'perban-1-2025', 223, 'lampiran', 'Lampiran hal. 121', NULL, 121, '1. Pendanaan Pemerintah
a. Anggaran Pendapatan Belanja Negara Pendanaan RENAS PB Tahun 2025-2029 yang bersumber dari Anggaran Pendapatan Belanja Negara dapat berasal dari pajak, penerimaan negara bukan pajak, sumber keuangan lainnya seperti pinjaman dan hibah yang berasal dari dalam negeri maupun luar negeri. Pendanaan yang bersumber dari Anggaran Pendapatan Belanja Negara dialokasikan secara rutin setiap tahunnya melalui anggaran masing-masing kementerian/lembaga. Pendanaan yang bersumber dari Anggaran Pendapatan Belanja Negara dalam konteks penanggulangan bencana mengacu pada sistem penganggaran yang diatur dalam ketentuan peraturan perundang-undangan berkaitan keuangan negara.
Pendanaan yang bersumber dari Anggaran Pendapatan Belanja Negara diprioritaskan untuk kegiatan RENAS PB Tahun 2025-2029 yang menjadi prioritas nasional dalam Rencana Pembangunan Jangka Menengah Nasional. Selain itu, pendanaan yang bersumber dari Anggaran Pendapatan Belanja Negara dapat juga diprioritaskan untuk kegiatan dalam RENAS PB Tahun 2025-2029 terkait penyusunan dan penetapan regulasi, penguatan kelembagaan, dan pelaksanaan pembinaan. Untuk pendanaan yang bersumber dari Anggaran Pendapatan Belanja Negara dan berasal dari hibah dapat diprioritaskan untuk peningkatan kapasitas komunitas, desa, dan aparatur pemerintah, pemberian bantuan, riset dan pengembangan teknologi kebencanaan, serta kegiatan rehabilitasi dan rekonstruksi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2330, '1. Pendanaan Pemerintah
a. Anggaran Pendapatan Belanja Negara Pendanaan RENAS PB Tahun 2025-2029 yang bersumber dari Anggaran Pendapatan Belanja Negara dapat berasal dari pajak, penerimaan negara bukan pajak, sumber keuangan lainnya seperti pinjaman dan hibah yang berasal dari dalam negeri maupun luar negeri. Pendanaan yang bersumber dari Anggaran Pendapatan Belanja Negara dialokasikan secara rutin setiap tahunnya melalui anggaran masing-masing kementerian/lembaga. Pendanaan yang bersumber dari Anggaran Pendapatan Belanja Negara dalam konteks penanggulangan bencana mengacu pada sistem penganggaran yang diatur dalam ketentuan peraturan perundang-undangan berkaitan keuangan negara.
Pendanaan yang bersumber dari Anggaran Pendapatan Belanja Negara diprioritaskan untuk kegiatan RENAS PB Tahun 2025-2029 yang menjadi prioritas nasional dalam Rencana Pembangunan Jangka Menengah Nasional. Selain itu, pendanaan yang bersumber dari Anggaran Pendapatan Belanja Negara dapat juga diprioritaskan untuk kegiatan dalam RENAS PB Tahun 2025-2029 terkait penyusunan dan penetapan regulasi, penguatan kelembagaan, dan pelaksanaan pembinaan. Untuk pendanaan yang bersumber dari Anggaran Pendapatan Belanja Negara dan berasal dari hibah dapat diprioritaskan untuk peningkatan kapasitas komunitas, desa, dan aparatur pemerintah, pemberian bantuan, riset dan pengembangan teknologi kebencanaan, serta kegiatan rehabilitasi dan rekonstruksi.', 'Lampiran hal. 121', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2331, 'perban-1-2025', 224, 'lampiran', 'Lampiran hal. 121', NULL, 121, 'Pendanaan yang berasal dari pinjaman baik dalam negeri maupun luar negeri dapat difokuskan untuk pembiayaan infrastruktur kebencanaan, praktik baik internasional dan berbagi pengetahuan, proyek piloting yang dapat direplikasi dengan pendanaan Anggaran Pendapatan Belanja Negara, dan menduukung pencapaian tujuan dan sasaran RENAS PB Tahun 2025-2029.
b. Dana Siap Pakai Selain penganggaran Anggaran Pendapatan Belanja Negara secara rutin yang umumnya dapat digunakan untuk kegiatan tahap prabencana dan pascabencana, pendanaan kegiatan RENAS PB Tahun 2025-2029 saat tanggap darurat dapat memanfaatkan Dana Siap Pakai. Dana Siap Pakai adalah dana yang selalu tersedia dan dicadangkan oleh pemerintah untuk digunakan pada saat keadaan darurat bencana, keadaan tertentu, dan pertimbangan adanya risiko bencana berdampak luas yang ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana. Penggunaan dana siap pakai yang ditetapkan dalam anggaran Badan Nasional Penanggulangan Bencana disesuaikan dengan ketentuan peraturan perundang-undangan yang berlaku.
2. Dana Bersama Penanggulangan Bencana Dana Bersama Penanggulangan Bencana adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi dana penanggulangan bencana yang memadai dan berkelanjutan. Dana bersama dikumpulkan dari Anggaran Pendapatan Belanja Negara, Anggaran Pendapatan Belanja Daerah, dan sumber dana lainnya yang sah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2331, 'Pendanaan yang berasal dari pinjaman baik dalam negeri maupun luar negeri dapat difokuskan untuk pembiayaan infrastruktur kebencanaan, praktik baik internasional dan berbagi pengetahuan, proyek piloting yang dapat direplikasi dengan pendanaan Anggaran Pendapatan Belanja Negara, dan menduukung pencapaian tujuan dan sasaran RENAS PB Tahun 2025-2029.
b. Dana Siap Pakai Selain penganggaran Anggaran Pendapatan Belanja Negara secara rutin yang umumnya dapat digunakan untuk kegiatan tahap prabencana dan pascabencana, pendanaan kegiatan RENAS PB Tahun 2025-2029 saat tanggap darurat dapat memanfaatkan Dana Siap Pakai. Dana Siap Pakai adalah dana yang selalu tersedia dan dicadangkan oleh pemerintah untuk digunakan pada saat keadaan darurat bencana, keadaan tertentu, dan pertimbangan adanya risiko bencana berdampak luas yang ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana. Penggunaan dana siap pakai yang ditetapkan dalam anggaran Badan Nasional Penanggulangan Bencana disesuaikan dengan ketentuan peraturan perundang-undangan yang berlaku.
2. Dana Bersama Penanggulangan Bencana Dana Bersama Penanggulangan Bencana adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi dana penanggulangan bencana yang memadai dan berkelanjutan. Dana bersama dikumpulkan dari Anggaran Pendapatan Belanja Negara, Anggaran Pendapatan Belanja Daerah, dan sumber dana lainnya yang sah.', 'Lampiran hal. 121', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2332, 'perban-1-2025', 225, 'lampiran', 'Lampiran hal. 121', NULL, 121, 'Dana Bersama Penanggulangan Bencana (pooling fund) dapat digunakan untuk pendanaan kegiatan dalam RENAS PB Tahun 2025-2029 dan diprioritaskan untuk kegiatan yang termasuk tahap prabencana, tahap darurat bencana, tahap pascabencana (terutama kegiatan pemulihan), dan pendanaan transfer risiko.
3. Pendanaan Nonpemerintah Sumber pendanaan nonpemerintah untuk pelaksanaan RENAS PB Tahun 2025-2029 dapat diperoleh dari badan usaha (swasta dan BUMN/BUMD) maupun masyarakat. Potensi sumber-sumber pendanaan nonpemerintah yang dapat dimanfaatkan untuk kegiatan RENAS PB Tahun 2025-2029 ialah sebagai berikut:
a. Tanggung Jawab Sosial Perusahaan (Corporate Social Responsibility/CSR) CSR merupakan bentuk komitmen perusahaan untuk berkontribusi pada peningkatan kualitas kehidupan komunitas setempat, maupun masyarakat pada umumnya. Pendanaan melalui CSR ini dapat difokuskan pada kegiatan: peningkatan ketangguhan komunitas dan desa; kegiatan mitigasi struktural dan non-struktural di skala komunitas/kelompok masyarakat; pembangunan sarana prasarana sosial dan lingkungan; serta pemulihan sosial, ekonomi, dan Sumber Daya Alam masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2332, 'Dana Bersama Penanggulangan Bencana (pooling fund) dapat digunakan untuk pendanaan kegiatan dalam RENAS PB Tahun 2025-2029 dan diprioritaskan untuk kegiatan yang termasuk tahap prabencana, tahap darurat bencana, tahap pascabencana (terutama kegiatan pemulihan), dan pendanaan transfer risiko.
3. Pendanaan Nonpemerintah Sumber pendanaan nonpemerintah untuk pelaksanaan RENAS PB Tahun 2025-2029 dapat diperoleh dari badan usaha (swasta dan BUMN/BUMD) maupun masyarakat. Potensi sumber-sumber pendanaan nonpemerintah yang dapat dimanfaatkan untuk kegiatan RENAS PB Tahun 2025-2029 ialah sebagai berikut:
a. Tanggung Jawab Sosial Perusahaan (Corporate Social Responsibility/CSR) CSR merupakan bentuk komitmen perusahaan untuk berkontribusi pada peningkatan kualitas kehidupan komunitas setempat, maupun masyarakat pada umumnya. Pendanaan melalui CSR ini dapat difokuskan pada kegiatan: peningkatan ketangguhan komunitas dan desa; kegiatan mitigasi struktural dan non-struktural di skala komunitas/kelompok masyarakat; pembangunan sarana prasarana sosial dan lingkungan; serta pemulihan sosial, ekonomi, dan Sumber Daya Alam masyarakat.', 'Lampiran hal. 121', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2333, 'perban-1-2025', 226, 'lampiran', 'Lampiran hal. 122', NULL, 122, 'b. Filantropi Filantropi adalah aktivitas yang dilakukan oleh sekelompok orang ataupun yayasan untuk kebaikan (kemaslahatan) publik atau masyarakat dengan semangat kebaikan bersama melalui dana pribadi maupun kelompok yang dihimpun secara sukarela. Kegiatan yang dilakukan filantropis dapat berupa pembangunan sarana prasarana sosial dan lingkungan untuk pemulihan pascabencana, bantuan kelangsungan hidup, dan pemberdayaan masyarakat.
c. Sumber Pendanaan Non Pemerintah Lainnya Dalam periode RENAS PB Tahun 2025-2029 diperlukan juga pengembangan skema pemanfaatan sumber pendanaan non-pemerintah lainnya terutama untuk mendorong kerja sama antara pemerintah dan sektor swasta dalam mengalihkan sebagian risiko ke pasar keuangan. Pengembangan strategi pembiayaan risiko, asuransi risiko bencana, dan perlindungan sosial adaptif akan menjadi bagian dari agenda utama pengembangan pengurangan risiko bencana dan juga dapat memanfaat pembiayaan sektor lain yang terkait dengan urusan kebencanaan seperti pembiayaan berkelanjutan (sustainable finance). Selain itu, diperlukan juga pengembangan pemanfaatan jaminan sosial dan ketenagakerjaan serta pemetaan sarana dan prasarana layanan umum dalam konteks penanggulangan bencana yang dapat disediakan dengan skema Kerjasama Pemerintah dan Badan Usaha (KPBU).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2333, 'b. Filantropi Filantropi adalah aktivitas yang dilakukan oleh sekelompok orang ataupun yayasan untuk kebaikan (kemaslahatan) publik atau masyarakat dengan semangat kebaikan bersama melalui dana pribadi maupun kelompok yang dihimpun secara sukarela. Kegiatan yang dilakukan filantropis dapat berupa pembangunan sarana prasarana sosial dan lingkungan untuk pemulihan pascabencana, bantuan kelangsungan hidup, dan pemberdayaan masyarakat.
c. Sumber Pendanaan Non Pemerintah Lainnya Dalam periode RENAS PB Tahun 2025-2029 diperlukan juga pengembangan skema pemanfaatan sumber pendanaan non-pemerintah lainnya terutama untuk mendorong kerja sama antara pemerintah dan sektor swasta dalam mengalihkan sebagian risiko ke pasar keuangan. Pengembangan strategi pembiayaan risiko, asuransi risiko bencana, dan perlindungan sosial adaptif akan menjadi bagian dari agenda utama pengembangan pengurangan risiko bencana dan juga dapat memanfaat pembiayaan sektor lain yang terkait dengan urusan kebencanaan seperti pembiayaan berkelanjutan (sustainable finance). Selain itu, diperlukan juga pengembangan pemanfaatan jaminan sosial dan ketenagakerjaan serta pemetaan sarana dan prasarana layanan umum dalam konteks penanggulangan bencana yang dapat disediakan dengan skema Kerjasama Pemerintah dan Badan Usaha (KPBU).', 'Lampiran hal. 122', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2334, 'perban-1-2025', 227, 'lampiran', 'Lampiran hal. 122', NULL, 122, '4.5. Kerangka Pemantauan, Pengendalian, dan Evaluasi RENAS PB Tahun 2025-2029 merupakan dokumen yang membutuhkan proses penyusunan, penetapan, termasuk evaluasi dan pengendalian untuk membentuk siklus perencanaan yang utuh. Kegiatan pemantauan, pengendalian, dan evaluasi RENAS PB Tahun 2025-2029 dimaksudkan untuk memastikan dan menjamin terlaksananya aksi-aksi yang direncanakan dan tercapainya target output, sasaran program, dan target sasaran yang ditetapkan.
Kegiatan pemantauan, pengendalian, dan evaluasi RENAS PB Tahun 2025-2029 merupakan bagian pemantauan, pengendalian, dan evaluasi RIPB Tahun 2020- 2044 Periode berjalan. Hasil kegiatan tersebut dapat memberikan masukan, saran, dan rekomendasi kepada berbagai pihak dalam melaksanakan penanggulangan bencana di Indonesia. Selain itu, hasil kegiatan pemantauan dan evaluasi dapat pula digunakan sebagai masukan kebijakan dalam rangka perbaikan RENAS PB Tahun 2025-2029 maupun penyusunan RENAS PB berikutnya.
1. Pemantauan Pemantauan merupakan langkah awal dari evaluasi dan pengendalian pelaksanaan RENAS PB Tahun 2025-2029. Pemantauan merupakan kegiatan mengamati perkembangan pelaksanaan RENAS PB Tahun 2025-2029 dan menjadi kunci utama dalam dalam pencapaian target dan sasaran yang ditetapkan. Pemantauan pelaksanaan RENAS PB Tahun 2025-2029 dilaksanakan setiap tahun dalam 2 (dua) tahap, yaitu sebelum pelaksanaan kegiatan (tahun T-1) dan saat pelaksanaan kegiatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2334, '4.5. Kerangka Pemantauan, Pengendalian, dan Evaluasi RENAS PB Tahun 2025-2029 merupakan dokumen yang membutuhkan proses penyusunan, penetapan, termasuk evaluasi dan pengendalian untuk membentuk siklus perencanaan yang utuh. Kegiatan pemantauan, pengendalian, dan evaluasi RENAS PB Tahun 2025-2029 dimaksudkan untuk memastikan dan menjamin terlaksananya aksi-aksi yang direncanakan dan tercapainya target output, sasaran program, dan target sasaran yang ditetapkan.
Kegiatan pemantauan, pengendalian, dan evaluasi RENAS PB Tahun 2025-2029 merupakan bagian pemantauan, pengendalian, dan evaluasi RIPB Tahun 2020- 2044 Periode berjalan. Hasil kegiatan tersebut dapat memberikan masukan, saran, dan rekomendasi kepada berbagai pihak dalam melaksanakan penanggulangan bencana di Indonesia. Selain itu, hasil kegiatan pemantauan dan evaluasi dapat pula digunakan sebagai masukan kebijakan dalam rangka perbaikan RENAS PB Tahun 2025-2029 maupun penyusunan RENAS PB berikutnya.
1. Pemantauan Pemantauan merupakan langkah awal dari evaluasi dan pengendalian pelaksanaan RENAS PB Tahun 2025-2029. Pemantauan merupakan kegiatan mengamati perkembangan pelaksanaan RENAS PB Tahun 2025-2029 dan menjadi kunci utama dalam dalam pencapaian target dan sasaran yang ditetapkan. Pemantauan pelaksanaan RENAS PB Tahun 2025-2029 dilaksanakan setiap tahun dalam 2 (dua) tahap, yaitu sebelum pelaksanaan kegiatan (tahun T-1) dan saat pelaksanaan kegiatan.', 'Lampiran hal. 122', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2335, 'perban-1-2025', 228, 'lampiran', 'Lampiran hal. 123', NULL, 123, 'a. Pra Pelaksanaan Kegiatan Pemantauan sebelum pelaksanaan kegiatan dilakukan pada triwulan ke-empat (TW-IV) di tahun T-1 terhadap perencanaan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029. Pemantauan dilakukan dengan meninjau Rencana Kerja (Renja) Kementerian/Lembagaa Penanggung Jawab untuk memetakan rencana pelaksanaan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029. Luaran dari kegiatan pemantauan saat pra pelaksanaan kegiatan ialah peta kegiatan RENAS PB Tahun 2025-2029 dalam Rencana Kerja (Renja) Kementerian/Lembaga yang meliputi rencana bentuk pelaksanaan kegiatan, target output, alokasi anggaran, dan unit kerja pelaksana.
b. Saat Pelaksanaan Pemantauan saat pelaksanaan kegiatan dilakukan sepanjang tahun berjalan. Pemantauan ini dilakukan untuk mengetahui kemajuan pelaksanaan kegiatan rencana aksi RENAS PB Tahun 2025-2029 di Kementerian/Lembaga Penanggung Jawab berdasarkan pemetaan kegiatan yang telah dilakukan sebelumnya. Luaran kegiatan pemantauan ini meliputi: (a) penyempurnaan peta kegiatan RENAS PB Tahun 2025-2029 dalam Rencana Kerja (Renja) Kementerian/Lembaga; (b) rekapitulasi kemajuan pelaksanaan kegiatan; dan (c) rekomendasi pelaksanaan kegiatan. Untuk mendapatkan hasil luaran yang diharapkan, dilaksanakan forum koordinasi dengan Kementerian/Lembaga Penanggung Jawab paling lambat pada triwulan ke-dua (TW-II) di tahun berjalan (tahun-T).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2335, 'a. Pra Pelaksanaan Kegiatan Pemantauan sebelum pelaksanaan kegiatan dilakukan pada triwulan ke-empat (TW-IV) di tahun T-1 terhadap perencanaan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029. Pemantauan dilakukan dengan meninjau Rencana Kerja (Renja) Kementerian/Lembagaa Penanggung Jawab untuk memetakan rencana pelaksanaan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029. Luaran dari kegiatan pemantauan saat pra pelaksanaan kegiatan ialah peta kegiatan RENAS PB Tahun 2025-2029 dalam Rencana Kerja (Renja) Kementerian/Lembaga yang meliputi rencana bentuk pelaksanaan kegiatan, target output, alokasi anggaran, dan unit kerja pelaksana.
b. Saat Pelaksanaan Pemantauan saat pelaksanaan kegiatan dilakukan sepanjang tahun berjalan. Pemantauan ini dilakukan untuk mengetahui kemajuan pelaksanaan kegiatan rencana aksi RENAS PB Tahun 2025-2029 di Kementerian/Lembaga Penanggung Jawab berdasarkan pemetaan kegiatan yang telah dilakukan sebelumnya. Luaran kegiatan pemantauan ini meliputi: (a) penyempurnaan peta kegiatan RENAS PB Tahun 2025-2029 dalam Rencana Kerja (Renja) Kementerian/Lembaga; (b) rekapitulasi kemajuan pelaksanaan kegiatan; dan (c) rekomendasi pelaksanaan kegiatan. Untuk mendapatkan hasil luaran yang diharapkan, dilaksanakan forum koordinasi dengan Kementerian/Lembaga Penanggung Jawab paling lambat pada triwulan ke-dua (TW-II) di tahun berjalan (tahun-T).', 'Lampiran hal. 123', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2336, 'perban-1-2025', 229, 'lampiran', 'Lampiran hal. 123', NULL, 123, '2. Pengendalian Pengendalian dilakukan berdasarkan hasil pemantauan dan evaluasi dengan melakukan tindakan korektif yang bersifat konstruktif maupun preventif untuk perbaikan dalam rangka pencapaian sasaran program dan target kegiatan. Pengendalian pelaksanaan RENAS PB Tahun 2025-2029 dilakukan untuk memastikan pelaksanaan program dan kegiatan berjalan sesuai dengan rencana aksi yang telah ditetapkan. Pengendalian pelaksanaan RENAS PB Tahun 2025-2029 dilakukan dengan perumusan dan pemberian rekomendasi tindakan korektif untuk kegiatan yang sedang berjalan (on-going) dan rencana kegiatan di tahun berikut. Rekomendasi yang dihasilkan dapat berupa saran perubahan lokasi, penerima manfaat (beneficiaries), volume output, bentuk kegiatan, dan lainnya sesuai dengan hasil pemantauan dan evaluasi.
3. Evaluasi Evaluasi RENAS PB Tahun 2025-2029 merupakan kegiatan yang dilaksanakan untuk menilai hasil dari pelaksanaan program dan kegiatan, kinerja sasaran program dan indikator kegiatan, serta pencapaian sasaran RENAS PB Tahun 2025-2029. Selain itu, evaluasi dilakukan untuk menganalisis permasalahan dalam proses pelaksanaan program dan kegiatan dalam mendukung pencapaian sasaran RENAS PB Tahun 2025-2029. Lingkup evaluasi RENAS PB Tahun 2025-2029 tersebut disesuaikan dengan periode waktu evaluasi RENAS PB Tahun 2025-2029 yang terbagi menjadi evaluasi tahunan, evaluasi paruh waktu, dan evaluasi akhir.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2336, '2. Pengendalian Pengendalian dilakukan berdasarkan hasil pemantauan dan evaluasi dengan melakukan tindakan korektif yang bersifat konstruktif maupun preventif untuk perbaikan dalam rangka pencapaian sasaran program dan target kegiatan. Pengendalian pelaksanaan RENAS PB Tahun 2025-2029 dilakukan untuk memastikan pelaksanaan program dan kegiatan berjalan sesuai dengan rencana aksi yang telah ditetapkan. Pengendalian pelaksanaan RENAS PB Tahun 2025-2029 dilakukan dengan perumusan dan pemberian rekomendasi tindakan korektif untuk kegiatan yang sedang berjalan (on-going) dan rencana kegiatan di tahun berikut. Rekomendasi yang dihasilkan dapat berupa saran perubahan lokasi, penerima manfaat (beneficiaries), volume output, bentuk kegiatan, dan lainnya sesuai dengan hasil pemantauan dan evaluasi.
3. Evaluasi Evaluasi RENAS PB Tahun 2025-2029 merupakan kegiatan yang dilaksanakan untuk menilai hasil dari pelaksanaan program dan kegiatan, kinerja sasaran program dan indikator kegiatan, serta pencapaian sasaran RENAS PB Tahun 2025-2029. Selain itu, evaluasi dilakukan untuk menganalisis permasalahan dalam proses pelaksanaan program dan kegiatan dalam mendukung pencapaian sasaran RENAS PB Tahun 2025-2029. Lingkup evaluasi RENAS PB Tahun 2025-2029 tersebut disesuaikan dengan periode waktu evaluasi RENAS PB Tahun 2025-2029 yang terbagi menjadi evaluasi tahunan, evaluasi paruh waktu, dan evaluasi akhir.', 'Lampiran hal. 123', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2337, 'perban-1-2025', 230, 'lampiran', 'Lampiran hal. 124', NULL, 124, 'a. Evaluasi Tahunan Evaluasi tahunan dilakukan pasca-pelaksanaan Renja Kementerian/Lembaga untuk menilai ketercapaian target indikator kegiatan (output) di setiap kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029. Evaluasi tahunan juga meliputi analisis permasalahan dan hambatan pelaksanaan dan pencapaian target indikator kegiatan. Evaluasi tahunan dilakukan maksimal hingga minggu terakhir di TW II tahun berikutnya (tahun T+1) dengan luaran berupa:
1) Peta kegiatan RENAS PB dalam Renja Kementerian/Lembaga (target output kegiatan, alokasi anggaran, UKE pelaksana);
2) Gap analysis capaian indikator output kegiatan RENAS PB; dan 3) Rekomendasi pelaksanaan kegiatan di tahun berikutnya.
b. Evaluasi Paruh Waktu Evaluasi paruh waktu RENAS PB Tahun 2025-2029 dilakukan untuk menilai pencapaian target indikator kegiatan, sasaran program, dan target indikator sasaran RENAS PB Tahun 2025-2029. Evaluasi paruh waktu juga dilakukan untuk menganalisis permasalahan dan hambatan pelaksanaan kebijakan, strategi, program, dan kegiatan serta pencapaian sasaran RENAS PB Tahun 2025-2029. Evaluasi paruh waktu dilakukan di tahun ketiga RENAS PB Tahun 2025-2029 dan digunakan untuk bahan masukan pelaksanaan kegiatan di tahun ke-4 dan ke-5, bahan pengendalian perbaikan RENAS PB Tahun 2025-2029, dan bahan masukan penyusunan RENAS PB periode berikutnya. Luaran kegiatan evaluasi paruh waktu, diantaranya:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2337, 'a. Evaluasi Tahunan Evaluasi tahunan dilakukan pasca-pelaksanaan Renja Kementerian/Lembaga untuk menilai ketercapaian target indikator kegiatan (output) di setiap kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029. Evaluasi tahunan juga meliputi analisis permasalahan dan hambatan pelaksanaan dan pencapaian target indikator kegiatan. Evaluasi tahunan dilakukan maksimal hingga minggu terakhir di TW II tahun berikutnya (tahun T+1) dengan luaran berupa:
1) Peta kegiatan RENAS PB dalam Renja Kementerian/Lembaga (target output kegiatan, alokasi anggaran, UKE pelaksana);
2) Gap analysis capaian indikator output kegiatan RENAS PB; dan 3) Rekomendasi pelaksanaan kegiatan di tahun berikutnya.
b. Evaluasi Paruh Waktu Evaluasi paruh waktu RENAS PB Tahun 2025-2029 dilakukan untuk menilai pencapaian target indikator kegiatan, sasaran program, dan target indikator sasaran RENAS PB Tahun 2025-2029. Evaluasi paruh waktu juga dilakukan untuk menganalisis permasalahan dan hambatan pelaksanaan kebijakan, strategi, program, dan kegiatan serta pencapaian sasaran RENAS PB Tahun 2025-2029. Evaluasi paruh waktu dilakukan di tahun ketiga RENAS PB Tahun 2025-2029 dan digunakan untuk bahan masukan pelaksanaan kegiatan di tahun ke-4 dan ke-5, bahan pengendalian perbaikan RENAS PB Tahun 2025-2029, dan bahan masukan penyusunan RENAS PB periode berikutnya. Luaran kegiatan evaluasi paruh waktu, diantaranya:', 'Lampiran hal. 124', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2338, 'perban-1-2025', 231, 'lampiran', 'Lampiran hal. 124', NULL, 124, '1) Gap analysis capaian indikator sasaran dan indikator kegiatan RENAS PB Tahun 2025-2029 2) Pencapaian sasaran program RENAS PB Tahun 2025-2029 3) Evaluasi pelaksanaan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029 4) Rekomendasi pelaksanaan kegiatan tahun berikutnya 5) Rekomendasi perbaikan RENAS PB Tahun 2025-2029 (bila perlu)
c. Evaluasi Akhir Evaluasi Akhir RENAS PB Tahun 2025-2029 dilakukan untuk menilai kinerja capaian kegiatan, sasaran program, dan sasaran RENAS PB Tahun 2025-2029 di akhir tahun pelaksanaan RENAS PB Tahun 2025-2029.
Dalam evaluasi Akhir RENAS PB Tahun 2025-2024 juga dilakukan analisis permasalahan dan hambatan pelaksanaan kebijakan, strategi, program, dan kegiatan serta pencapaian sasaran RENAS PB Tahun 2025-2029.
Evaluasi akhir dilakukan pasca pelaksanaan kegiatan di tahun ke-5 (lima) RENAS PB Tahun 2025-2029. dan digunakan untuk bahan masukan dan/atau perbaikan perencanaan penanggulangan bencana periode berikutnya. Luaran kegiatan Evaluasi Akhir RENAS PB Tahun 2025-2029, diantaranya:
1) Gap analysis capaian indikator sasaran dan indikator kegiatan RENAS PB Tahun 2025-2029;
2) Pencapaian sasaran program RENAS PB Tahun 2025-2029;
3) Evaluasi pelaksanaan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029; dan 4) Rekomendasi perencanaan RENAS PB periode selanjutnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2338, '1) Gap analysis capaian indikator sasaran dan indikator kegiatan RENAS PB Tahun 2025-2029 2) Pencapaian sasaran program RENAS PB Tahun 2025-2029 3) Evaluasi pelaksanaan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029 4) Rekomendasi pelaksanaan kegiatan tahun berikutnya 5) Rekomendasi perbaikan RENAS PB Tahun 2025-2029 (bila perlu)
c. Evaluasi Akhir Evaluasi Akhir RENAS PB Tahun 2025-2029 dilakukan untuk menilai kinerja capaian kegiatan, sasaran program, dan sasaran RENAS PB Tahun 2025-2029 di akhir tahun pelaksanaan RENAS PB Tahun 2025-2029.
Dalam evaluasi Akhir RENAS PB Tahun 2025-2024 juga dilakukan analisis permasalahan dan hambatan pelaksanaan kebijakan, strategi, program, dan kegiatan serta pencapaian sasaran RENAS PB Tahun 2025-2029.
Evaluasi akhir dilakukan pasca pelaksanaan kegiatan di tahun ke-5 (lima) RENAS PB Tahun 2025-2029. dan digunakan untuk bahan masukan dan/atau perbaikan perencanaan penanggulangan bencana periode berikutnya. Luaran kegiatan Evaluasi Akhir RENAS PB Tahun 2025-2029, diantaranya:
1) Gap analysis capaian indikator sasaran dan indikator kegiatan RENAS PB Tahun 2025-2029;
2) Pencapaian sasaran program RENAS PB Tahun 2025-2029;
3) Evaluasi pelaksanaan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029; dan 4) Rekomendasi perencanaan RENAS PB periode selanjutnya.', 'Lampiran hal. 124', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2339, 'perban-1-2025', 232, 'lampiran', 'Lampiran hal. 125', NULL, 125, 'Gambar 4.3 Linimasa Pemantauan, Pengendalian, dan Evaluasi RENAS PB Tahun 2025-2029 4.6. Pembaruan Pembaruan RENAS PB Tahun 2025-2029 dilakukan jika telah berakhir masa perencanaannya yaitu dalam kurun waktu 5 (lima) tahun. Jika hasil peninjauan kembali RENAS PB Tahun 2025-2029 merekomendasikan perubahan kebijakan, strategi, program, dan kegiatan dalam RENAS PB Tahun 2025-2029, maka dapat RENAS PB Tahun 2025-2029 dapat diubah.
Perubahan RENAS PB Tahun 2025-2029 yang didasarkan pada peninjauan kembali secara berkala dilakukan maksimal di tahun ketiga periode pelaksanaan RENAS PB Tahun 2025-2029. Rekomendasi peninjauan kembali tersebut harus termuat dalam hasil pemantauan dan evaluasi tahunan atau evaluasi paruh waktu.
Perubahan RENAS PB Tahun 2025-2029 yang didasarkan pada peninjauan kembali jika sewaktu-waktu terjadi bencana dilakukan maksimal di tahun keempat periode pelaksanaan RENAS PB Tahun 2025-2029. Perubahan tersebut dapat dilakukan terhadap program dan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029. Rekomendasi peninjauan kembali RENAS PB Tahun 2025- 2029 yang dilakukan karena terjadi bencana harus termuat dalam hasil pemantauan dan evaluasi tahunan atau evaluasi paruh waktu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2339, 'Gambar 4.3 Linimasa Pemantauan, Pengendalian, dan Evaluasi RENAS PB Tahun 2025-2029 4.6. Pembaruan Pembaruan RENAS PB Tahun 2025-2029 dilakukan jika telah berakhir masa perencanaannya yaitu dalam kurun waktu 5 (lima) tahun. Jika hasil peninjauan kembali RENAS PB Tahun 2025-2029 merekomendasikan perubahan kebijakan, strategi, program, dan kegiatan dalam RENAS PB Tahun 2025-2029, maka dapat RENAS PB Tahun 2025-2029 dapat diubah.
Perubahan RENAS PB Tahun 2025-2029 yang didasarkan pada peninjauan kembali secara berkala dilakukan maksimal di tahun ketiga periode pelaksanaan RENAS PB Tahun 2025-2029. Rekomendasi peninjauan kembali tersebut harus termuat dalam hasil pemantauan dan evaluasi tahunan atau evaluasi paruh waktu.
Perubahan RENAS PB Tahun 2025-2029 yang didasarkan pada peninjauan kembali jika sewaktu-waktu terjadi bencana dilakukan maksimal di tahun keempat periode pelaksanaan RENAS PB Tahun 2025-2029. Perubahan tersebut dapat dilakukan terhadap program dan kegiatan dalam rencana aksi RENAS PB Tahun 2025-2029. Rekomendasi peninjauan kembali RENAS PB Tahun 2025- 2029 yang dilakukan karena terjadi bencana harus termuat dalam hasil pemantauan dan evaluasi tahunan atau evaluasi paruh waktu.', 'Lampiran hal. 125', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2340, 'perban-1-2025', 233, 'lampiran', 'Lampiran hal. 126', NULL, 126, 'BAB V PENUTUP RENAS PB merupakan kesatuan langkah pemerintah dan para pihak dalam menyelenggarakan penanggulangan bencana secara terarah dan terpadu di seluruh wilayah Indonesia. RENAS PB tidak hanya menjadi rujukan penyelenggaraan penanggulangan bencana di tingkat kementerian/lembaga, namun juga menjadi rujukan bagi pemerintah daerah, baik provinsi maupun kabupaten/kota, organisasi pihak non pemerintah, lembaga usaha, lembaga internasional, akademisi/perguruan tinggi, media, dan kelompok masyarakat/komunitas.
Berbagai perangkat dan mekanisme penerapan di berbagai kelompok juga telah diberikan dalam RENAS PB. Diharapkan perangkat dan mekanisme penerapan tersebut dapat dilaksanakan secara komprehensif untuk mencapai sasaran nasional penanggulangan bencana yang telah ditetapkan dalam RENAS PB Tahun 2025-2029.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd.
SUHARYANTO');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2340, 'BAB V PENUTUP RENAS PB merupakan kesatuan langkah pemerintah dan para pihak dalam menyelenggarakan penanggulangan bencana secara terarah dan terpadu di seluruh wilayah Indonesia. RENAS PB tidak hanya menjadi rujukan penyelenggaraan penanggulangan bencana di tingkat kementerian/lembaga, namun juga menjadi rujukan bagi pemerintah daerah, baik provinsi maupun kabupaten/kota, organisasi pihak non pemerintah, lembaga usaha, lembaga internasional, akademisi/perguruan tinggi, media, dan kelompok masyarakat/komunitas.
Berbagai perangkat dan mekanisme penerapan di berbagai kelompok juga telah diberikan dalam RENAS PB. Diharapkan perangkat dan mekanisme penerapan tersebut dapat dilaksanakan secara komprehensif untuk mencapai sasaran nasional penanggulangan bencana yang telah ditetapkan dalam RENAS PB Tahun 2025-2029.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd.
SUHARYANTO', 'Lampiran hal. 126', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2025 tentang Rencana Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2341, 'perban-1-2026', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2341, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2342, 'perban-1-2026', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk mewujudkan penyelenggaraan penanggulangan bencana yang profesional dan berbasis pengurangan risiko bencana, pelaksanaan penyaluran dana bersama penanggulangan bencana perlu dilakukan untuk mencapai kemanfaatannya, lebih berkualitas, berkeadilan, transparan dan akuntabel;
b. bahwa penyaluran dana bersama penanggulangan bencana perlu didukung dengan mekanisme penelaahan, verifikasi, dan evaluasi permohonan dana bersama penanggulangan bencana yang akuntabel dan berkelanjutan;
c. bahwa Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana sudah tidak sesuai dengan kebutuhan perkembangan hukum, sehingga perlu diganti;
d. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, dan huruf c, serta berdasarkan ketentuan Pasal 8 Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2342, 'a. bahwa untuk mewujudkan penyelenggaraan penanggulangan bencana yang profesional dan berbasis pengurangan risiko bencana, pelaksanaan penyaluran dana bersama penanggulangan bencana perlu dilakukan untuk mencapai kemanfaatannya, lebih berkualitas, berkeadilan, transparan dan akuntabel;
b. bahwa penyaluran dana bersama penanggulangan bencana perlu didukung dengan mekanisme penelaahan, verifikasi, dan evaluasi permohonan dana bersama penanggulangan bencana yang akuntabel dan berkelanjutan;
c. bahwa Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana sudah tidak sesuai dengan kebutuhan perkembangan hukum, sehingga perlu diganti;
d. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, dan huruf c, serta berdasarkan ketentuan Pasal 8 Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2343, 'perban-1-2026', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 183);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 769) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2025 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 1159);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2343, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Presiden Nomor 75 Tahun 2021 tentang Dana Bersama Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 183);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 769) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2025 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 1159);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2344, 'perban-1-2026', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PELAKSANAAN PENELAAHAN, VERIFIKASI, DAN EVALUASI TERHADAP PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2344, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PELAKSANAAN PENELAAHAN, VERIFIKASI, DAN EVALUASI TERHADAP PENYALURAN DANA BERSAMA PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2345, 'perban-1-2026', 4, 'pasal', 'Pasal 1', 'BAB II PRIORITAS PENYALURAN; Bagian Kesatu Umum', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
2. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
3. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, pengungsian, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
4. Dana Penanggulangan Bencana adalah dana yang digunakan bagi penanggulangan bencana untuk tahap prabencana, darurat bencana, dan/atau pascabencana.
5. Dana Bersama Penanggulangan Bencana, yang selanjutnya disebut Dana Bersama, adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi Dana Penanggulangan Bencana yang memadai dan berkelanjutan.
6. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
7. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara pemerintahan daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
8. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam Undang-Undang tentang penanggulangan bencana.
9. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah Perangkat Daerah yang menyelenggarakan suburusan Bencana.
10. Kepala BNPB adalah pimpinan lembaga pemerintah nondepartemen setingkat menteri yang melakukan Penyelenggaraan Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2345, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
2. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
3. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, pengungsian, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
4. Dana Penanggulangan Bencana adalah dana yang digunakan bagi penanggulangan bencana untuk tahap prabencana, darurat bencana, dan/atau pascabencana.
5. Dana Bersama Penanggulangan Bencana, yang selanjutnya disebut Dana Bersama, adalah dana yang berasal dari berbagai sumber dan digunakan untuk mendukung dan melengkapi Dana Penanggulangan Bencana yang memadai dan berkelanjutan.
6. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
7. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara pemerintahan daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
8. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam Undang-Undang tentang penanggulangan bencana.
9. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah Perangkat Daerah yang menyelenggarakan suburusan Bencana.
10. Kepala BNPB adalah pimpinan lembaga pemerintah nondepartemen setingkat menteri yang melakukan Penyelenggaraan Penanggulangan Bencana.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2346, 'perban-1-2026', 5, 'pasal', 'Pasal 2', 'BAB II PRIORITAS PENYALURAN; Bagian Kesatu Umum', 3, '(1) Dana Bersama disalurkan untuk pendanaan kegiatan penanggulangan bencana.
(2) Penyaluran Dana Bersama untuk kegiatan penanggulangan bencana meliputi:
a. penyaluran pada tahap prabencana;
b. penyaluran pada tahap darurat bencana;
c. penyaluran pada tahap pascabencana, terutama kegiatan pemulihan; dan
d. penyaluran untuk pendanaan transfer risiko.
(3) Penyelenggaraan Penanggulangan Bencana mengutamakan kegiatan yang bersifat investasi pada pengurangan risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2346, '(1) Dana Bersama disalurkan untuk pendanaan kegiatan penanggulangan bencana.
(2) Penyaluran Dana Bersama untuk kegiatan penanggulangan bencana meliputi:
a. penyaluran pada tahap prabencana;
b. penyaluran pada tahap darurat bencana;
c. penyaluran pada tahap pascabencana, terutama kegiatan pemulihan; dan
d. penyaluran untuk pendanaan transfer risiko.
(3) Penyelenggaraan Penanggulangan Bencana mengutamakan kegiatan yang bersifat investasi pada pengurangan risiko bencana.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2347, 'perban-1-2026', 6, 'pasal', 'Pasal 3', 'BAB II PRIORITAS PENYALURAN; Bagian Kesatu Umum', 3, '(1) Penyaluran pada tahap prabencana sebagaimana dimaksud dalam Pasal 2 ayat (2) huruf a dan penyaluran dana pada tahap pascabencana sebagaimana dimaksud dalam Pasal 2 ayat (2) huruf c dilakukan setelah adanya permohonan.
(2) Penyaluran pada tahap darurat bencana sebagaimana dimaksud dalam Pasal 2 ayat (2) huruf b dan penyaluran untuk pendanaan transfer risiko sebagaimana dimaksud dalam Pasal 2 ayat (2) huruf d dilaksanakan sesuai ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2347, '(1) Penyaluran pada tahap prabencana sebagaimana dimaksud dalam Pasal 2 ayat (2) huruf a dan penyaluran dana pada tahap pascabencana sebagaimana dimaksud dalam Pasal 2 ayat (2) huruf c dilakukan setelah adanya permohonan.
(2) Penyaluran pada tahap darurat bencana sebagaimana dimaksud dalam Pasal 2 ayat (2) huruf b dan penyaluran untuk pendanaan transfer risiko sebagaimana dimaksud dalam Pasal 2 ayat (2) huruf d dilaksanakan sesuai ketentuan peraturan perundang-undangan.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2348, 'perban-1-2026', 7, 'pasal', 'Pasal 4', 'BAB II PRIORITAS PENYALURAN; Bagian Kedua Penerima Manfaat', 4, 'Dalam penyaluran Dana Bersama untuk kegiatan yang dilaksanakan melalui pendanaan Dana Bersama harus memperhatikan pelindungan lingkungan dan sosial serta tata kelola yang baik, transparansi, dan akuntabilitas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2348, 'Dalam penyaluran Dana Bersama untuk kegiatan yang dilaksanakan melalui pendanaan Dana Bersama harus memperhatikan pelindungan lingkungan dan sosial serta tata kelola yang baik, transparansi, dan akuntabilitas.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2349, 'perban-1-2026', 8, 'pasal', 'Pasal 5', 'BAB II PRIORITAS PENYALURAN; Bagian Kedua Penerima Manfaat', 4, 'Penerima manfaat penyaluran Dana Bersama terdiri atas:
a. kementerian/lembaga;
b. Pemerintah Daerah;
c. kelompok masyarakat; dan/atau
d. penyedia barang/jasa.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2349, 'Penerima manfaat penyaluran Dana Bersama terdiri atas:
a. kementerian/lembaga;
b. Pemerintah Daerah;
c. kelompok masyarakat; dan/atau
d. penyedia barang/jasa.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2350, 'perban-1-2026', 9, 'pasal', 'Pasal 6', 'BAB II PRIORITAS PENYALURAN; Bagian Ketiga Prioritas Penyaluran Dana', 4, '(1) Kelompok masyarakat sebagaimana dimaksud dalam Pasal 5 huruf c mencakup:
a. forum pengurangan risiko bencana;
b. forum tematik pengurangan risiko bencana;
c. kelompok masyarakat binaan kementerian/lembaga dan perangkat daerah; dan
d. kumpulan individu dari masyarakat terdampak bencana, yang telah diverifikasi oleh BPBD.
(2) Penyedia barang/jasa sebagaimana dimaksud dalam Pasal 5 huruf d menerima manfaat dari penyaluran Dana Bersama melalui penunjukan dari kementerian/lembaga dan Pemerintah Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2350, '(1) Kelompok masyarakat sebagaimana dimaksud dalam Pasal 5 huruf c mencakup:
a. forum pengurangan risiko bencana;
b. forum tematik pengurangan risiko bencana;
c. kelompok masyarakat binaan kementerian/lembaga dan perangkat daerah; dan
d. kumpulan individu dari masyarakat terdampak bencana, yang telah diverifikasi oleh BPBD.
(2) Penyedia barang/jasa sebagaimana dimaksud dalam Pasal 5 huruf d menerima manfaat dari penyaluran Dana Bersama melalui penunjukan dari kementerian/lembaga dan Pemerintah Daerah.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2351, 'perban-1-2026', 10, 'pasal', 'Pasal 7', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Kesatu Umum', 4, '(1) Kepala BNPB menetapkan prioritas kegiatan yang dapat dibiayai dengan Dana Bersama.
(2) Penetapan prioritas kegiatan sebagaimana dimaksud pada ayat (1) dengan mempertimbangkan:
a. kegiatan yang sesuai dengan Rencana Nasional Penanggulangan Bencana/Rencana Penanggulangan Bencana Daerah;
b. kegiatan pada daerah dengan indeks risiko bencana tinggi;
c. kegiatan yang ditetapkan dalam dokumen rencana rehabilitasi dan rekonstruksi pascabencana untuk penanganan pascabencana; dan/atau
d. kegiatan yang sesuai dengan standar pelayanan minimal sub urusan bencana.
(3) Penyusunan prioritas kegiatan sebagaimana dimaksud pada ayat (2) dilaksanakan dengan melibatkan Kementerian yang menyelenggarakan sinkronisasi dan koordinasi serta pengendalian pelaksanaan urusan Kementerian dalam penyelenggaraan pemerintahan di bidang pembangunan manusia dan kebudayaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2351, '(1) Kepala BNPB menetapkan prioritas kegiatan yang dapat dibiayai dengan Dana Bersama.
(2) Penetapan prioritas kegiatan sebagaimana dimaksud pada ayat (1) dengan mempertimbangkan:
a. kegiatan yang sesuai dengan Rencana Nasional Penanggulangan Bencana/Rencana Penanggulangan Bencana Daerah;
b. kegiatan pada daerah dengan indeks risiko bencana tinggi;
c. kegiatan yang ditetapkan dalam dokumen rencana rehabilitasi dan rekonstruksi pascabencana untuk penanganan pascabencana; dan/atau
d. kegiatan yang sesuai dengan standar pelayanan minimal sub urusan bencana.
(3) Penyusunan prioritas kegiatan sebagaimana dimaksud pada ayat (2) dilaksanakan dengan melibatkan Kementerian yang menyelenggarakan sinkronisasi dan koordinasi serta pengendalian pelaksanaan urusan Kementerian dalam penyelenggaraan pemerintahan di bidang pembangunan manusia dan kebudayaan.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2352, 'perban-1-2026', 11, 'pasal', 'Pasal 8', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Kedua Permohonan', 5, '(1) BNPB melakukan penelaahan, verifikasi, dan evaluasi.
(2) Dalam melakukan penelaahan, verifikasi, dan evaluasi sebagaimana dimaksud pada ayat (1), dilakukan berdasarkan permohonan.
(3) Dalam melakukan penelaahan, verifikasi, dan evaluasi sebagaimana dimaksud pada ayat (1), BNPB meminta pertimbangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2352, '(1) BNPB melakukan penelaahan, verifikasi, dan evaluasi.
(2) Dalam melakukan penelaahan, verifikasi, dan evaluasi sebagaimana dimaksud pada ayat (1), dilakukan berdasarkan permohonan.
(3) Dalam melakukan penelaahan, verifikasi, dan evaluasi sebagaimana dimaksud pada ayat (1), BNPB meminta pertimbangan.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2353, 'perban-1-2026', 12, 'pasal', 'Pasal 9', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Kedua Permohonan', 5, '(1) Permohonan penyaluran Dana Bersama sebagaimana dimaksud dalam Pasal 3 ayat (1) diajukan oleh pemohon kepada Kepala BNPB secara tertulis.
(2) Pemohon sebagaimana dimaksud pada ayat (1) terdiri atas:
a. kementerian/lembaga; dan
b. Pemerintah Daerah.
(3) Pengajuan permohonan dari kementerian/lembaga dilakukan oleh paling rendah pejabat pimpinan tinggi madya.
(4) Pengajuan permohonan dari Pemerintah Daerah dilakukan oleh Kepala Daerah.
(5) Permohonan dari pemohon pemerintah daerah kabupaten/kota ditembuskan kepada sekretaris daerah provinsi dan BPBD provinsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2353, '(1) Permohonan penyaluran Dana Bersama sebagaimana dimaksud dalam Pasal 3 ayat (1) diajukan oleh pemohon kepada Kepala BNPB secara tertulis.
(2) Pemohon sebagaimana dimaksud pada ayat (1) terdiri atas:
a. kementerian/lembaga; dan
b. Pemerintah Daerah.
(3) Pengajuan permohonan dari kementerian/lembaga dilakukan oleh paling rendah pejabat pimpinan tinggi madya.
(4) Pengajuan permohonan dari Pemerintah Daerah dilakukan oleh Kepala Daerah.
(5) Permohonan dari pemohon pemerintah daerah kabupaten/kota ditembuskan kepada sekretaris daerah provinsi dan BPBD provinsi.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2354, 'perban-1-2026', 13, 'pasal', 'Pasal 10', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Kedua Permohonan', 5, '(1) BNPB dapat menggunakan Dana Bersama dengan permohonan yang diajukan oleh pejabat pimpinan tinggi madya di lingkungan BNPB.
(2) Pengajuan permohonan sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2354, '(1) BNPB dapat menggunakan Dana Bersama dengan permohonan yang diajukan oleh pejabat pimpinan tinggi madya di lingkungan BNPB.
(2) Pengajuan permohonan sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2355, 'perban-1-2026', 14, 'pasal', 'Pasal 11', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Kedua Permohonan', 6, '(1) Dalam rangka persiapan pengajuan permohonan dan pelaksanaan kegiatan Dana Bersama, Pemerintah Daerah membentuk tim.
(2) Tim sebagaimana dimaksud pada ayat (1) terdiri atas:
a. BPBD selaku koordinator tim dan/atau pelaksana kegiatan;
b. perangkat daerah teknis pelaksana kegiatan dan/atau unsur kelompok masyarakat pelaksana kegiatan; dan
c. perangkat daerah yang mempunyai tugas pengawasan intern daerah.
(3) Tim sebagaimana dimaksud pada ayat (2) ditetapkan oleh Kepala Daerah.
(4) Penetapan sebagaimana dimaksud pada ayat (3) dapat didelegasikan kepada Sekretaris Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2355, '(1) Dalam rangka persiapan pengajuan permohonan dan pelaksanaan kegiatan Dana Bersama, Pemerintah Daerah membentuk tim.
(2) Tim sebagaimana dimaksud pada ayat (1) terdiri atas:
a. BPBD selaku koordinator tim dan/atau pelaksana kegiatan;
b. perangkat daerah teknis pelaksana kegiatan dan/atau unsur kelompok masyarakat pelaksana kegiatan; dan
c. perangkat daerah yang mempunyai tugas pengawasan intern daerah.
(3) Tim sebagaimana dimaksud pada ayat (2) ditetapkan oleh Kepala Daerah.
(4) Penetapan sebagaimana dimaksud pada ayat (3) dapat didelegasikan kepada Sekretaris Daerah.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2356, 'perban-1-2026', 15, 'pasal', 'Pasal 12', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Kedua Permohonan', 6, 'Permohonan penyaluran Dana Bersama sebagaimana dimaksud dalam Pasal 9 dapat diajukan oleh kelompok masyarakat melalui Pemerintah Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2356, 'Permohonan penyaluran Dana Bersama sebagaimana dimaksud dalam Pasal 9 dapat diajukan oleh kelompok masyarakat melalui Pemerintah Daerah.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2357, 'perban-1-2026', 16, 'pasal', 'Pasal 13', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Ketiga Penelaahan', 6, '(1) Berdasarkan permohonan tertulis sebagaimana dimaksud dalam Pasal 9 ayat (1), BNPB melakukan penelaahan, verifikasi, dan evaluasi setelah berkoordinasi dengan kementerian yang menyelenggarakan sinkronisasi dan koordinasi serta pengendalian pelaksanaan urusan Kementerian dalam penyelenggaraan pemerintahan di bidang pembangunan manusia dan kebudayaan.
(2) Koordinasi sebagaimana dimaksud pada ayat (1) dilakukan dengan menyampaikan daftar permohonan penyaluran Dana Bersama disertai dengan salinan dokumen permohonan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2357, '(1) Berdasarkan permohonan tertulis sebagaimana dimaksud dalam Pasal 9 ayat (1), BNPB melakukan penelaahan, verifikasi, dan evaluasi setelah berkoordinasi dengan kementerian yang menyelenggarakan sinkronisasi dan koordinasi serta pengendalian pelaksanaan urusan Kementerian dalam penyelenggaraan pemerintahan di bidang pembangunan manusia dan kebudayaan.
(2) Koordinasi sebagaimana dimaksud pada ayat (1) dilakukan dengan menyampaikan daftar permohonan penyaluran Dana Bersama disertai dengan salinan dokumen permohonan.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2358, 'perban-1-2026', 17, 'pasal', 'Pasal 14', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Ketiga Penelaahan', 6, '(1) BNPB melakukan penelaahan terhadap permohonan penyaluran Dana Bersama.
(2) Penelaahan sebagaimana dimaksud pada ayat (1) dilakukan berdasarkan kriteria penyaluran.
(3) Kriteria penyaluran sebagaimana dimaksud pada ayat
(2) terdiri atas:
a. kriteria penyaluran untuk permohonan pada tahap prabencana; dan
b. kriteria penyaluran untuk permohonan pada tahap pascabencana.
(4) Kriteria penyaluran untuk permohonan pada tahap prabencana sebagaimana dimaksud pada ayat (3) huruf a terdiri atas:
a. bagi pemohon dari kementerian/lembaga, kegiatan yang diajukan sesuai arah kebijakan terkait penanggulangan bencana dalam Rencana Nasional Penanggulangan Bencana dan Rencana Kerja Pemerintah; dan
b. bagi pemohon dari Pemerintah Daerah, kegiatan yang diajukan sesuai arah kebijakan terkait penanggulangan bencana dalam Rencana Kerja Pemerintah Daerah serta merujuk pada Rencana Penanggulangan Bencana Daerah dan/atau standar pelayanan minimal sub-urusan bencana.
(5) Kriteria penyaluran untuk permohonan pada tahap pascabencana sebagaimana dimaksud pada ayat (3) huruf b terdiri atas:
a. kegiatan yang diajukan oleh kementerian/lembaga dan Pemerintah Daerah wajib merujuk pada rencana rehabilitasi dan rekonstruksi pascabencana yang telah ditetapkan oleh pejabat yang berwenang; dan
b. permohonan diajukan pada masa keberlakuan rencana rehabilitasi dan rekonstruksi pascabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2358, '(1) BNPB melakukan penelaahan terhadap permohonan penyaluran Dana Bersama.
(2) Penelaahan sebagaimana dimaksud pada ayat (1) dilakukan berdasarkan kriteria penyaluran.
(3) Kriteria penyaluran sebagaimana dimaksud pada ayat
(2) terdiri atas:
a. kriteria penyaluran untuk permohonan pada tahap prabencana; dan
b. kriteria penyaluran untuk permohonan pada tahap pascabencana.
(4) Kriteria penyaluran untuk permohonan pada tahap prabencana sebagaimana dimaksud pada ayat (3) huruf a terdiri atas:
a. bagi pemohon dari kementerian/lembaga, kegiatan yang diajukan sesuai arah kebijakan terkait penanggulangan bencana dalam Rencana Nasional Penanggulangan Bencana dan Rencana Kerja Pemerintah; dan
b. bagi pemohon dari Pemerintah Daerah, kegiatan yang diajukan sesuai arah kebijakan terkait penanggulangan bencana dalam Rencana Kerja Pemerintah Daerah serta merujuk pada Rencana Penanggulangan Bencana Daerah dan/atau standar pelayanan minimal sub-urusan bencana.
(5) Kriteria penyaluran untuk permohonan pada tahap pascabencana sebagaimana dimaksud pada ayat (3) huruf b terdiri atas:
a. kegiatan yang diajukan oleh kementerian/lembaga dan Pemerintah Daerah wajib merujuk pada rencana rehabilitasi dan rekonstruksi pascabencana yang telah ditetapkan oleh pejabat yang berwenang; dan
b. permohonan diajukan pada masa keberlakuan rencana rehabilitasi dan rekonstruksi pascabencana.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2359, 'perban-1-2026', 18, 'pasal', 'Pasal 15', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Keempat Verifikasi', 7, 'Dalam hal permohonan yang tidak sesuai dengan kriteria penyaluran sebagaimana dimaksud dalam Pasal 14 ayat (4) dan ayat (5) tidak dapat dilanjutkan proses verifikasi dan dikembalikan kepada Pemohon.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2359, 'Dalam hal permohonan yang tidak sesuai dengan kriteria penyaluran sebagaimana dimaksud dalam Pasal 14 ayat (4) dan ayat (5) tidak dapat dilanjutkan proses verifikasi dan dikembalikan kepada Pemohon.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2360, 'perban-1-2026', 19, 'pasal', 'Pasal 16', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Keempat Verifikasi', 7, '(1) Permohonan yang telah ditelaah sesuai dengan kriteria penyaluran dilakukan verifikasi.
(2) BNPB melakukan verifikasi terhadap permohonan yang telah ditelaah sesuai dengan kriteria penyaluran sebagaimana dimaksud dalam Pasal 14.
(3) Permohonan sebagaimana dimaksud pada ayat (1) harus dilengkapi dengan dokumen persyaratan administrasi berupa:
a. kerangka acuan kerja;
b. rencana anggaran biaya;
c. reviu aparat pengawasan intern pemerintah pemohon;
d. spesifikasi barang dan/atau jasa;
e. dokumen standar sistem pengelolaan lingkungan dan sosial; dan
f. dokumen lainnya yang dipersyaratkan sesuai jenis kegiatan yang diusulkan.
(4) Verifikasi dilakukan dengan memeriksa kesesuaian antara persyaratan administrasi sebagaimana dimaksud pada ayat (3) dengan dokumen persyaratan administrasi yang diajukan.
(5) Dalam hal penerima manfaat berasal dari kelompok masyarakat, selain persyaratan administrasi sebagaimana dimaksud pada ayat (3), permohonan harus dilengkapi dengan bukti hasil verifikasi kelompok masyarakat dari BPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2360, '(1) Permohonan yang telah ditelaah sesuai dengan kriteria penyaluran dilakukan verifikasi.
(2) BNPB melakukan verifikasi terhadap permohonan yang telah ditelaah sesuai dengan kriteria penyaluran sebagaimana dimaksud dalam Pasal 14.
(3) Permohonan sebagaimana dimaksud pada ayat (1) harus dilengkapi dengan dokumen persyaratan administrasi berupa:
a. kerangka acuan kerja;
b. rencana anggaran biaya;
c. reviu aparat pengawasan intern pemerintah pemohon;
d. spesifikasi barang dan/atau jasa;
e. dokumen standar sistem pengelolaan lingkungan dan sosial; dan
f. dokumen lainnya yang dipersyaratkan sesuai jenis kegiatan yang diusulkan.
(4) Verifikasi dilakukan dengan memeriksa kesesuaian antara persyaratan administrasi sebagaimana dimaksud pada ayat (3) dengan dokumen persyaratan administrasi yang diajukan.
(5) Dalam hal penerima manfaat berasal dari kelompok masyarakat, selain persyaratan administrasi sebagaimana dimaksud pada ayat (3), permohonan harus dilengkapi dengan bukti hasil verifikasi kelompok masyarakat dari BPBD.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2361, 'perban-1-2026', 20, 'pasal', 'Pasal 17', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Keempat Verifikasi', 8, 'Dalam pelaksanaan verifikasi, permohonan untuk penyaluran pada tahap pascabencana sebagaimana dimaksud dalam Pasal 14 ayat (3) huruf b dilengkapi dengan salinan keputusan kepala daerah mengenai penetapan status keadaan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2361, 'Dalam pelaksanaan verifikasi, permohonan untuk penyaluran pada tahap pascabencana sebagaimana dimaksud dalam Pasal 14 ayat (3) huruf b dilengkapi dengan salinan keputusan kepala daerah mengenai penetapan status keadaan darurat bencana.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2362, 'perban-1-2026', 21, 'pasal', 'Pasal 18', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Keempat Verifikasi', 8, '(1) Untuk pemenuhan aspek kehati-hatian, verifikasi dapat dilakukan dengan melibatkan kementerian/lembaga terkait.
(2) Verifikasi sebagaimana dimaksud pada ayat (1) dapat dilengkapi dengan peninjauan ke lokasi rencana penggunaan Dana Bersama.
(3) Kegiatan peninjauan sebagaimana dimaksud pada ayat
(2) dilakukan dengan terlebih dulu menyampaikan surat pemberitahuan pelaksanaan verifikasi kepada pemohon.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2362, '(1) Untuk pemenuhan aspek kehati-hatian, verifikasi dapat dilakukan dengan melibatkan kementerian/lembaga terkait.
(2) Verifikasi sebagaimana dimaksud pada ayat (1) dapat dilengkapi dengan peninjauan ke lokasi rencana penggunaan Dana Bersama.
(3) Kegiatan peninjauan sebagaimana dimaksud pada ayat
(2) dilakukan dengan terlebih dulu menyampaikan surat pemberitahuan pelaksanaan verifikasi kepada pemohon.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2363, 'perban-1-2026', 22, 'pasal', 'Pasal 19', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Kelima Evaluasi', 8, 'Hasil verifikasi terhadap dokumen permohonan sebagaimana dimaksud dalam Pasal 16 ayat (3) dan/atau hasil peninjauan sebagaimana dimaksud dalam Pasal 18 dituangkan ke dalam risalah verifikasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2363, 'Hasil verifikasi terhadap dokumen permohonan sebagaimana dimaksud dalam Pasal 16 ayat (3) dan/atau hasil peninjauan sebagaimana dimaksud dalam Pasal 18 dituangkan ke dalam risalah verifikasi.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2364, 'perban-1-2026', 23, 'pasal', 'Pasal 20', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Keenam Pertimbangan', 8, '(1) Evaluasi dilakukan berdasarkan hasil risalah verifikasi.
(2) BNPB melakukan evaluasi berdasarkan hasil risalah verifikasi sebagaimana dimaksud pada ayat (1).
(3) Dalam hal pelaksanaan evaluasi masih memerlukan dokumen pendukung lain, BNPB menyampaikan permintaan dokumen tambahan kepada pemohon agar dilengkapi.
(4) Penyampaian dokumen tambahan sebagaimana dimaksud pada ayat (3) dilakukan dalam jangka waktu 5 (lima) hari kerja terhitung sejak tanggal permintaan.
(5) Apabila permintaan dokumen tambahan sebagaimana dimaksud pada ayat (3) dipenuhi oleh pemohon, dilanjutkan untuk dilakukan evaluasi.
(6) Apabila permintaan dokumen tambahan sebagaimana dimaksud pada ayat (3) tidak ditanggapi oleh pemohon, permohonan penyaluran dana bersama ditolak dan dikembalikan kepada pemohon.
(7) Penolakan dan pengembalian permohonan sebagaimana dimaksud pada ayat (6) disampaikan secara kedinasan dengan memuat alasan penolakan dan pengembalian.
(8) Hasil evaluasi permohonan dituangkan dalam risalah penelaahan, verifikasi, dan evaluasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2364, '(1) Evaluasi dilakukan berdasarkan hasil risalah verifikasi.
(2) BNPB melakukan evaluasi berdasarkan hasil risalah verifikasi sebagaimana dimaksud pada ayat (1).
(3) Dalam hal pelaksanaan evaluasi masih memerlukan dokumen pendukung lain, BNPB menyampaikan permintaan dokumen tambahan kepada pemohon agar dilengkapi.
(4) Penyampaian dokumen tambahan sebagaimana dimaksud pada ayat (3) dilakukan dalam jangka waktu 5 (lima) hari kerja terhitung sejak tanggal permintaan.
(5) Apabila permintaan dokumen tambahan sebagaimana dimaksud pada ayat (3) dipenuhi oleh pemohon, dilanjutkan untuk dilakukan evaluasi.
(6) Apabila permintaan dokumen tambahan sebagaimana dimaksud pada ayat (3) tidak ditanggapi oleh pemohon, permohonan penyaluran dana bersama ditolak dan dikembalikan kepada pemohon.
(7) Penolakan dan pengembalian permohonan sebagaimana dimaksud pada ayat (6) disampaikan secara kedinasan dengan memuat alasan penolakan dan pengembalian.
(8) Hasil evaluasi permohonan dituangkan dalam risalah penelaahan, verifikasi, dan evaluasi.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2365, 'perban-1-2026', 24, 'pasal', 'Pasal 21', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Keenam Pertimbangan', 9, '(1) BNPB dalam meminta pertimbangan sebagaimana dimaksud dalam Pasal 8 ayat (3) menyampaikan permohonan kepada:
a. kementerian yang menyelenggarakan urusan pemerintahan di bidang keuangan negara;
b. kementerian/lembaga yang menyelenggarakan urusan pemerintahan di bidang perencanaan pembangunan nasional; dan
c. kementerian yang menyelenggarakan urusan pemerintahan di bidang dalam negeri, sebagai instansi pemberi pertimbangan penyaluran Dana Bersama.
(2) Penyampaian pertimbangan oleh instansi sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai dengan kewenangannya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2365, '(1) BNPB dalam meminta pertimbangan sebagaimana dimaksud dalam Pasal 8 ayat (3) menyampaikan permohonan kepada:
a. kementerian yang menyelenggarakan urusan pemerintahan di bidang keuangan negara;
b. kementerian/lembaga yang menyelenggarakan urusan pemerintahan di bidang perencanaan pembangunan nasional; dan
c. kementerian yang menyelenggarakan urusan pemerintahan di bidang dalam negeri, sebagai instansi pemberi pertimbangan penyaluran Dana Bersama.
(2) Penyampaian pertimbangan oleh instansi sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai dengan kewenangannya.', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2366, 'perban-1-2026', 25, 'pasal', 'Pasal 22', 'BAB III TATA CARA PENELAAHAN, VERIFIKASI, DAN EVALUASI; Bagian Keenam Pertimbangan', 9, '(1) Instansi sebagaimana dimaksud dalam Pasal 21 ayat (1) memberikan pertimbangan setelah BNPB menyampaikan permohonan pertimbangan.
(2) Penentuan jangka waktu pemberian pertimbangan sebagaimana dimaksud pada ayat (1) sesuai jenis kegiatan yang akan didanai.
(3) Jangka waktu sebagaimana dimaksud pada ayat (2) dicantumkan dalam surat permohonan pemberian pertimbangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2366, '(1) Instansi sebagaimana dimaksud dalam Pasal 21 ayat (1) memberikan pertimbangan setelah BNPB menyampaikan permohonan pertimbangan.
(2) Penentuan jangka waktu pemberian pertimbangan sebagaimana dimaksud pada ayat (1) sesuai jenis kegiatan yang akan didanai.
(3) Jangka waktu sebagaimana dimaksud pada ayat (2) dicantumkan dalam surat permohonan pemberian pertimbangan.', 'Pasal 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2367, 'perban-1-2026', 26, 'pasal', 'Pasal 23', 'BAB IV REKOMENDASI', 9, '(1) Instansi sebagaimana dimaksud dalam Pasal 21 ayat (1) menyampaikan pertimbangannya dalam bentuk risalah pertimbangan.
(2) Risalah pertimbangan sebagaimana dimaksud pada ayat (1) dapat dilengkapi dengan kertas kerja pertimbangan.
(3) Risalah pertimbangan sebagaimana dimaksud pada ayat (1) disampaikan paling lambat 10 (sepuluh) hari kerja terhitung sejak tanggal penyampaian surat pemberitahuan pengakhiran tahap pemberian pertimbangan.
(4) Petunjuk Pelaksanaan pemberian pertimbangan penyaluran Dana Bersama sebagaimana dimaksud pada ayat (1) ditetapkan oleh Kepala BNPB dengan melibatkan instansi pemberi pertimbangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2367, '(1) Instansi sebagaimana dimaksud dalam Pasal 21 ayat (1) menyampaikan pertimbangannya dalam bentuk risalah pertimbangan.
(2) Risalah pertimbangan sebagaimana dimaksud pada ayat (1) dapat dilengkapi dengan kertas kerja pertimbangan.
(3) Risalah pertimbangan sebagaimana dimaksud pada ayat (1) disampaikan paling lambat 10 (sepuluh) hari kerja terhitung sejak tanggal penyampaian surat pemberitahuan pengakhiran tahap pemberian pertimbangan.
(4) Petunjuk Pelaksanaan pemberian pertimbangan penyaluran Dana Bersama sebagaimana dimaksud pada ayat (1) ditetapkan oleh Kepala BNPB dengan melibatkan instansi pemberi pertimbangan.', 'Pasal 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2368, 'perban-1-2026', 27, 'pasal', 'Pasal 24', 'BAB IV REKOMENDASI', 9, '(1) Hasil penelaahan, verifikasi, dan evaluasi sebagaimana dimaksud dalam Pasal 20 ayat (8) dan hasil pertimbangan penyaluran Dana Bersama sebagaimana dimaksud dalam Pasal 23 ayat (1) menjadi dasar pemberian rekomendasi dari BNPB.
(2) Rekomendasi sebagaimana dimaksud pada ayat (1) merupakan dasar pengalokasian anggaran dan revisi anggaran untuk Dana Bersama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2368, '(1) Hasil penelaahan, verifikasi, dan evaluasi sebagaimana dimaksud dalam Pasal 20 ayat (8) dan hasil pertimbangan penyaluran Dana Bersama sebagaimana dimaksud dalam Pasal 23 ayat (1) menjadi dasar pemberian rekomendasi dari BNPB.
(2) Rekomendasi sebagaimana dimaksud pada ayat (1) merupakan dasar pengalokasian anggaran dan revisi anggaran untuk Dana Bersama.', 'Pasal 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2369, 'perban-1-2026', 28, 'pasal', 'Pasal 25', 'BAB IV REKOMENDASI', 10, '(1) Rekomendasi sebagaimana dimaksud dalam Pasal 24 ayat (1) disampaikan oleh Kepala BNPB kepada menteri yang menyelenggarakan urusan pemerintahan di bidang keuangan negara dan pemohon penerima rekomendasi.
(2) Selain kepada menteri dan pemohon sebagaimana dimaksud pada ayat (1), rekomendasi juga disampaikan kepada:
a. kementerian yang menyelenggarakan sinkronisasi dan koordinasi serta pengendalian pelaksanaan urusan kementerian dalam penyelenggaraan pemerintahan di bidang pembangunan manusia dan kebudayaan
b. instansi sebagaimana dimaksud dalam Pasal 21 ayat (1); dan
c. kementerian/lembaga selaku executing agency pada mekanisme hibah ke Pemerintah Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2369, '(1) Rekomendasi sebagaimana dimaksud dalam Pasal 24 ayat (1) disampaikan oleh Kepala BNPB kepada menteri yang menyelenggarakan urusan pemerintahan di bidang keuangan negara dan pemohon penerima rekomendasi.
(2) Selain kepada menteri dan pemohon sebagaimana dimaksud pada ayat (1), rekomendasi juga disampaikan kepada:
a. kementerian yang menyelenggarakan sinkronisasi dan koordinasi serta pengendalian pelaksanaan urusan kementerian dalam penyelenggaraan pemerintahan di bidang pembangunan manusia dan kebudayaan
b. instansi sebagaimana dimaksud dalam Pasal 21 ayat (1); dan
c. kementerian/lembaga selaku executing agency pada mekanisme hibah ke Pemerintah Daerah.', 'Pasal 25', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2370, 'perban-1-2026', 29, 'pasal', 'Pasal 26', 'BAB V PEMBENTUKAN TIM PENELAAHAN, VERIFIKASI, DAN EVALUASI', 10, 'Ketentuan mengenai jenis kegiatan dan teknis penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2370, 'Ketentuan mengenai jenis kegiatan dan teknis penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama ditetapkan oleh Kepala BNPB.', 'Pasal 26', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2371, 'perban-1-2026', 30, 'pasal', 'Pasal 27', 'BAB V PEMBENTUKAN TIM PENELAAHAN, VERIFIKASI, DAN EVALUASI', 10, '(1) Untuk melakukan penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama, BNPB membentuk tim penelaahan, verifikasi dan evaluasi penyaluran dana bersama penanggulangan bencana.
(2) Tim sebagaimana dimaksud pada ayat (1) terdiri atas:
a. penanggung jawab;
b. tim penelaahan, verifikasi dan evaluasi bidang sistem dan strategi;
c. tim penelaahan, verifikasi dan evaluasi bidang pencegahan;
d. tim penelaahan, verifikasi dan evaluasi bidang rehabilitasi dan rekonstruksi;
e. tim penelaahan, verifikasi dan evaluasi bidang logistik dan peralatan; dan
f. tim sekretariat.
(3) Tim sebagaimana dimaksud pada ayat (2) ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2371, '(1) Untuk melakukan penelaahan, verifikasi, dan evaluasi penyaluran Dana Bersama, BNPB membentuk tim penelaahan, verifikasi dan evaluasi penyaluran dana bersama penanggulangan bencana.
(2) Tim sebagaimana dimaksud pada ayat (1) terdiri atas:
a. penanggung jawab;
b. tim penelaahan, verifikasi dan evaluasi bidang sistem dan strategi;
c. tim penelaahan, verifikasi dan evaluasi bidang pencegahan;
d. tim penelaahan, verifikasi dan evaluasi bidang rehabilitasi dan rekonstruksi;
e. tim penelaahan, verifikasi dan evaluasi bidang logistik dan peralatan; dan
f. tim sekretariat.
(3) Tim sebagaimana dimaksud pada ayat (2) ditetapkan oleh Kepala BNPB.', 'Pasal 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2372, 'perban-1-2026', 31, 'pasal', 'Pasal 28', 'BAB VI PEMANTAUAN, EVALUASI, DAN PELAPORAN; Bagian Kesatu Pemantauan dan Evaluasi', 11, '(1) Tim sebagaimana dimaksud dalam Pasal 27 terdiri atas pejabat dan pegawai di lingkungan BNPB.
(2) Tim sebagaimana dimaksud pada ayat (1) melaksanakan pertemuan rutin sesuai dengan kebutuhan atau setiap 3 (tiga) bulan sekali.
(3) Tim sebagaimana dimaksud pada ayat (1) memiliki masa kerja selama 2 (dua) tahun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2372, '(1) Tim sebagaimana dimaksud dalam Pasal 27 terdiri atas pejabat dan pegawai di lingkungan BNPB.
(2) Tim sebagaimana dimaksud pada ayat (1) melaksanakan pertemuan rutin sesuai dengan kebutuhan atau setiap 3 (tiga) bulan sekali.
(3) Tim sebagaimana dimaksud pada ayat (1) memiliki masa kerja selama 2 (dua) tahun.', 'Pasal 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2373, 'perban-1-2026', 32, 'pasal', 'Pasal 29', 'BAB VI PEMANTAUAN, EVALUASI, DAN PELAPORAN; Bagian Kesatu Pemantauan dan Evaluasi', 11, '(1) BNPB melakukan pemantauan dan evaluasi terhadap pelaksanaan kegiatan yang telah mendapatkan pendanaan Dana Bersama.
(2) Dalam hal kegiatan sebagaimana dimaksud pada ayat
(1) dilakukan oleh pemerintah kabupaten/kota, pemantauan dan evaluasi dilaksanakan dengan berkoordinasi dengan pemerintah provinsi.
(3) Pemantauan dan evaluasi dilakukan dengan cara memvalidasi kesesuaian antara dokumen permohonan yang mendapatkan rekomendasi hasil penelaahan, verifikasi, dan evaluasi terhadap kegiatan yang dilaksanakan berdasarkan pembiayaan Dana Bersama.
(4) Pemantauan dan evaluasi sebagaimana dimaksud pada ayat (3) dilakukan oleh BNPB terhadap:
a. standar teknis kegiatan;
b. kemajuan pelaksanaan kegiatan;
c. kepatuhan terhadap standar sistem pengelolaan lingkungan dan sosial; dan
d. pertimbangan lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2373, '(1) BNPB melakukan pemantauan dan evaluasi terhadap pelaksanaan kegiatan yang telah mendapatkan pendanaan Dana Bersama.
(2) Dalam hal kegiatan sebagaimana dimaksud pada ayat
(1) dilakukan oleh pemerintah kabupaten/kota, pemantauan dan evaluasi dilaksanakan dengan berkoordinasi dengan pemerintah provinsi.
(3) Pemantauan dan evaluasi dilakukan dengan cara memvalidasi kesesuaian antara dokumen permohonan yang mendapatkan rekomendasi hasil penelaahan, verifikasi, dan evaluasi terhadap kegiatan yang dilaksanakan berdasarkan pembiayaan Dana Bersama.
(4) Pemantauan dan evaluasi sebagaimana dimaksud pada ayat (3) dilakukan oleh BNPB terhadap:
a. standar teknis kegiatan;
b. kemajuan pelaksanaan kegiatan;
c. kepatuhan terhadap standar sistem pengelolaan lingkungan dan sosial; dan
d. pertimbangan lainnya.', 'Pasal 29', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2374, 'perban-1-2026', 33, 'pasal', 'Pasal 30', 'BAB VI PEMANTAUAN, EVALUASI, DAN PELAPORAN; Bagian Kesatu Pemantauan dan Evaluasi', 11, 'Pemantauan dan evaluasi sebagaimana dimaksud dalam Pasal 29 dapat dilakukan selama periode pelaksanaan kegiatan dan setelah berakhirnya pelaksanaan kegiatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2374, 'Pemantauan dan evaluasi sebagaimana dimaksud dalam Pasal 29 dapat dilakukan selama periode pelaksanaan kegiatan dan setelah berakhirnya pelaksanaan kegiatan.', 'Pasal 30', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2375, 'perban-1-2026', 34, 'pasal', 'Pasal 31', 'BAB VI PEMANTAUAN, EVALUASI, DAN PELAPORAN; Bagian Kedua Pelaporan', 11, 'Dalam pelaksanaan pemantauan dan evaluasi, BNPB dapat melibatkan:
a. kementerian/lembaga selaku pembina teknis kegiatan; dan/atau
b. kementerian/lembaga terkait, sesuai dengan kebutuhan teknis pelaksanaan kegiatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2375, 'Dalam pelaksanaan pemantauan dan evaluasi, BNPB dapat melibatkan:
a. kementerian/lembaga selaku pembina teknis kegiatan; dan/atau
b. kementerian/lembaga terkait, sesuai dengan kebutuhan teknis pelaksanaan kegiatan.', 'Pasal 31', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2376, 'perban-1-2026', 35, 'pasal', 'Pasal 32', 'BAB VII SISTEM INFORMASI', 11, '(1) Dalam rangka akuntabilitas, pemohon menyampaikan laporan pelaksanaan kegiatan yang didanai Dana Bersama kepada BNPB dan kementerian yang menyelenggarakan urusan pemerintahan di bidang keuangan negara.
(2) Laporan pelaksanaan kegiatan sebagaimana dimaksud pada ayat (1) terdiri atas:
a. laporan kemajuan; dan
b. laporan akhir.
(3) Penyampaian laporan kemajuan sebagaimana dimaksud pada ayat (2) huruf a disesuaikan dengan jangka waktu pelaksanaan kegiatan.
(4) Penyampaian laporan akhir sebagaimana dimaksud pada ayat (2) huruf b dilaksanakan paling lama 60 (enam puluh) hari kalender setelah berakhirnya pelaksanaan kegiatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2376, '(1) Dalam rangka akuntabilitas, pemohon menyampaikan laporan pelaksanaan kegiatan yang didanai Dana Bersama kepada BNPB dan kementerian yang menyelenggarakan urusan pemerintahan di bidang keuangan negara.
(2) Laporan pelaksanaan kegiatan sebagaimana dimaksud pada ayat (1) terdiri atas:
a. laporan kemajuan; dan
b. laporan akhir.
(3) Penyampaian laporan kemajuan sebagaimana dimaksud pada ayat (2) huruf a disesuaikan dengan jangka waktu pelaksanaan kegiatan.
(4) Penyampaian laporan akhir sebagaimana dimaksud pada ayat (2) huruf b dilaksanakan paling lama 60 (enam puluh) hari kalender setelah berakhirnya pelaksanaan kegiatan.', 'Pasal 32', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2377, 'perban-1-2026', 36, 'pasal', 'Pasal 33', 'BAB VIII KETENTUAN PENUTUP', 12, '(1) Dalam rangka dukungan pelaksanaan penelaahan, verifikasi dan evaluasi penyaluran Dana Bersama dibentuk sistem informasi.
(2) Sistem informasi sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai prinsip satu data.
(3) Pembangunan dan pengembangan sistem informasi sebagaimana dimaksud pada ayat (1) oleh unit kerja yang mempunyai tugas melaksanakan koordinasi dan pelayanan di bidang pengelolaan data dan informasi, dan pengembangan basis data dan informasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2377, '(1) Dalam rangka dukungan pelaksanaan penelaahan, verifikasi dan evaluasi penyaluran Dana Bersama dibentuk sistem informasi.
(2) Sistem informasi sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai prinsip satu data.
(3) Pembangunan dan pengembangan sistem informasi sebagaimana dimaksud pada ayat (1) oleh unit kerja yang mempunyai tugas melaksanakan koordinasi dan pelayanan di bidang pengelolaan data dan informasi, dan pengembangan basis data dan informasi.', 'Pasal 33', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2378, 'perban-1-2026', 37, 'pasal', 'Pasal 34', 'BAB VIII KETENTUAN PENUTUP', 12, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2024 Nomor 4), dicabut dan dinyatakan tidak berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2378, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2024 tentang Penelaahan, Verifikasi, dan Evaluasi Penyaluran Dana Bersama Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2024 Nomor 4), dicabut dan dinyatakan tidak berlaku.', 'Pasal 34', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2379, 'perban-1-2026', 38, 'pasal', 'Pasal 35', 'BAB VIII KETENTUAN PENUTUP', 12, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2379, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 35', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2380, 'perban-1-2026', 39, 'lain', 'Penutup', NULL, 13, 'Ditetapkan di Jakarta pada tanggal 10 Maret 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2026 NOMOR Ж');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2380, 'Ditetapkan di Jakarta pada tanggal 10 Maret 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2026 NOMOR Ж', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2026 tentang Pelaksanaan Penelaahan, Verifikasi, dan Evaluasi Terhadap Penyaluran Dana Bersama Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2381, 'perban-10-2025', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2381, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2382, 'perban-10-2025', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk mendukung tugas Badan Nasional Penanggulangan Bencana dalam menyelenggarakan urusan pemerintahan di bidang penanganan kebencanaan yang terpercaya dan berkualitas melalui pengelolaan dan pemanfaatan teknologi informasi dan komunikasi yang andal di lingkungan Badan Nasional Penanggulangan Bencana diperlukan tata kelola teknologi informasi dan komunikasi yang efektif, efisien, dan terpadu;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2014 tentang Pedoman Pengelolaan Teknologi Informasi Kebencanaan di Lingkungan Badan Nasional Penanggulangan Bencana dalam implementasinya sudah tidak sesuai dengan perkembangan kebutuhan hukum, sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Tata Kelola Teknologi Informasi dan Komunikasi;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2382, 'a. bahwa untuk mendukung tugas Badan Nasional Penanggulangan Bencana dalam menyelenggarakan urusan pemerintahan di bidang penanganan kebencanaan yang terpercaya dan berkualitas melalui pengelolaan dan pemanfaatan teknologi informasi dan komunikasi yang andal di lingkungan Badan Nasional Penanggulangan Bencana diperlukan tata kelola teknologi informasi dan komunikasi yang efektif, efisien, dan terpadu;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2014 tentang Pedoman Pengelolaan Teknologi Informasi Kebencanaan di Lingkungan Badan Nasional Penanggulangan Bencana dalam implementasinya sudah tidak sesuai dengan perkembangan kebutuhan hukum, sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Tata Kelola Teknologi Informasi dan Komunikasi;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2383, 'perban-10-2025', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 8 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 769);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2383, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 8 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 769);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2384, 'perban-10-2025', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA KELOLA TEKNOLOGI INFORMASI DAN KOMUNIKASI.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2384, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA KELOLA TEKNOLOGI INFORMASI DAN KOMUNIKASI.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2385, 'perban-10-2025', 4, 'pasal', 'Pasal 1', 'BAB II PERANAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Kesatu Umum', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Teknologi Informasi dan Komunikasi selanjutnya disingkat TIK adalah teknologi untuk mengumpulkan, menyiapkan, menyimpan, mengolah, mengumumkan, menganalisis, mengambil kembali, mengirim, dan/atau menerima data dan informasi.
2. Tata Kelola TIK adalah kerangka kerja yang mencakup struktur, kebijakan, prosedur, dan praktik untuk memastikan bahwa pemanfaatan TIK dapat berjalan secara efisien, efektif, terkontrol, dan sejalan dengan tujuan strategis organisasi.
3. Grand Design TIK adalah rencana induk strategis yang dirancang untuk mengelola, mengembangkan, dan memanfaatkan TIK secara terintegrasi dan terarah dalam mendukung pencapaian tujuan organisasi, pemerintahan, atau masyarakat.
4. Unit TIK adalah unit kerja yang melaksanakan tugas penyelenggaraan tata kelola, pengelolaan, dan pemanfaatan TIK untuk mendukung penyelenggaraan urusan pemerintahan di bidang penanggulangan bencana.
5. Unit Pemilik Proses Bisnis adalah unit dalam Badan Nasional Penanggulangan Bencana yang bertanggung jawab atas pengelolaan, pengendalian, dan pengembangan proses bisnis tertentu.
6. Layanan TIK adalah fasilitas berbentuk gabungan komponen teknologi, proses, dan/atau personel dalam rangka mendukung proses bisnis di lingkungan Badan Nasional Penanggulangan Bencana.
7. Pusat Data (Data Center) Badan Nasional Penanggulangan Bencana yang selanjutnya disebut DC Badan Nasional Penanggulangan Bencana adalah fasilitas yang digunakan untuk penempatan sistem informasi dan komponen terkait lainnya untuk keperluan penempatan, penyimpanan, pengolahan, dan pemulihan data di lingkungan Badan Nasional Penanggulangan Bencana.
8. Pusat Pemulihan Keadaan Bencana (Disaster Recovery Center) Badan Nasional Penanggulangan Bencana yang selanjutnya disebut DRC Badan Nasional Penanggulangan Bencana adalah fasilitas yang digunakan untuk memulihkan kembali data atau informasi serta fungsi-fungsi penting yang terganggu atau rusak akibat terjadinya bencana pada DC Badan Nasional Penanggulangan Bencana yang disebabkan oleh alam atau manusia di lingkungan Badan Nasional Penanggulangan Bencana.
9. Aset TIK adalah sumber daya, komponen, dan elemen teknologi informasi dan komunikasi yang dimiliki atau dikelola oleh Badan Nasional Penanggulangan Bencana untuk mendukung operasional, pengelolaan, dan pengembangan layanan TIK.
10. Aplikasi adalah perangkat lunak atau program komputer yang dirancang untuk menjalankan fungsi-fungsi tertentu yang mendukung kebutuhan organisasi, baik dalam operasional, manajemen, maupun pelayanan publik.
11. Aplikasi Umum adalah sistem aplikasi yang memiliki fungsi yang dapat digunakan secara bagi pakai oleh unit di lingkungan Badan Nasional Penanggulangan Bencana.
12. Aplikasi Khusus adalah sistem aplikasi untuk memenuhi kebutuhan khusus unit kerja di lingkungan Badan Nasional Penanggulangan Bencana dalam memberikan layanan dan menjalankan proses bisnis utama.
13. Pengguna adalah setiap pegawai di lingkungan Badan Nasional Penanggulangan Bencana.
14. Pihak Eksternal adalah pihak di luar Badan Nasional Penanggulangan Bencana yang berkaitan dengan penyelenggaraan tata kelola, pengelolaan, dan pemanfaatan TIK di lingkungan Badan Nasional Penanggulangan Bencana.
15. Pengembangan Aplikasi Bersama (Joint Application Development) yang selanjutnya disingkat JAD adalah pengembangan Sistem Informasi yang dilaksanakan secara bersama-sama oleh pengembang sistem informasi internal dengan melibatkan pengembang Sistem Informasi Internal pada unit lain maupun pengembang sistem informasi eksternal.
16. Sistem Informasi adalah sistem yang terdiri dari komponen TIK yang bekerja bersama untuk mengumpulkan, menyimpan, mengolah, dan mendistribusikan informasi guna mendukung aktivitas operasional, manajerial, dan pengambilan keputusan di Badan Nasional Penanggulangan Bencana.
17. Sistem Informasi Internal adalah Sistem Informasi yang berasal dari dalam organisasi untuk mendukung kegiatan operasional, pengambilan keputusan, dan pengendalian internal Badan Nasional Penanggulangan Bencana.
18. Sistem Informasi Eksternal adalah adalah Sistem Informasi yang berasal dari lingkungan luar Badan Nasional Penanggulangan Bencana.
19. Data adalah catatan atas kumpulan fakta atau deskripsi berupa angka, karakter, simbol, gambar, peta, tanda, isyarat, tulisan, suara, dan/atau bunyi, yang merepresentasikan keadaan sebenarnya atau menunjukkan suatu ide, objek, kondisi, atau situasi.
20. Basis Data adalah kumpulan data yang terstruktur dan terorganisir dengan cara tertentu untuk memudahkan pengelolaan, pencarian, pemrosesan, dan pengambilan informasi.
21. Kode Sumber (source code) adalah sekumpulan perintah atau instruksi yang ditulis dalam bahasa pemrograman oleh pengembang perangkat lunak untuk membuat suatu aplikasi, program, atau sistem.
22. Dokumentasi Sistem Informasi adalah serangkaian perangkat keras, perangkat jaringan, perangkat lunak, sumber daya manusia, serta prosedur dan/atau aturan yang dikelola secara terpadu untuk mengolah Data menjadi informasi yang berguna untuk mencapai suatu tujuan.
23. Manajemen Risiko adalah serangkaian kegiatan terencana dan terukur untuk mengelola dan mengendalikan Risiko yang berpotensi mengancam keberlangsungan dan pencapaian tujuan organisasi.
24. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintahan nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.');
