INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2386, 'perban-10-2025', 5, 'pasal', 'Pasal 2', 'BAB II PERANAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Kedua Enterprise Architecture Badan Nasional Penanggulangan', 4, '(1) TIK berperan sebagai penggerak proses bisnis dan penopang untuk memberikan nilai dalam mendukung transformasi digital di lingkungan BNPB serta mewujudkan pemerintahan digital.
(2) Dalam mengoptimalkan peran TIK sebagaimana dimaksud pada ayat (1) perlu memperhatikan:
a. enterprise architecture BNPB;
b. Grand Design TIK;
c. investasi TIK;
d. Manajemen Risiko; dan
e. pengukuran kinerja TIK.
Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2386, '(1) TIK berperan sebagai penggerak proses bisnis dan penopang untuk memberikan nilai dalam mendukung transformasi digital di lingkungan BNPB serta mewujudkan pemerintahan digital.
(2) Dalam mengoptimalkan peran TIK sebagaimana dimaksud pada ayat (1) perlu memperhatikan:
a. enterprise architecture BNPB;
b. Grand Design TIK;
c. investasi TIK;
d. Manajemen Risiko; dan
e. pengukuran kinerja TIK.
Bencana', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2387, 'perban-10-2025', 6, 'pasal', 'Pasal 3', 'BAB II PERANAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Kedua Enterprise Architecture Badan Nasional Penanggulangan', 5, '(1) Enterprise architecture BNPB sebagaimana dimaksud dalam Pasal 2 ayat (2) huruf a merupakan metode strategis untuk mencapai tujuan organisasi BNPB secara lebih efektif dan efisien dengan mendefinisikan, memetakan, merancang, menyelaraskan, dan mengintegrasikan domain layanan, aplikasi, bisnis, data dan informasi, infrastruktur, keamanan, dan teknologi.
(2) Enterprise architecture BNPB sebagaimana dimaksud pada ayat (1) terdiri atas:
a. visi;
b. prinsip;
c. referensi arsitektur;
d. domain;
e. metodologi;
f. perangkat;
g. kapabilitas; dan
h. tata kelola.
(3) Penerapan enterprise architecture di lingkungan BNPB dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
(4) Dokumen enterprise architecture ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2387, '(1) Enterprise architecture BNPB sebagaimana dimaksud dalam Pasal 2 ayat (2) huruf a merupakan metode strategis untuk mencapai tujuan organisasi BNPB secara lebih efektif dan efisien dengan mendefinisikan, memetakan, merancang, menyelaraskan, dan mengintegrasikan domain layanan, aplikasi, bisnis, data dan informasi, infrastruktur, keamanan, dan teknologi.
(2) Enterprise architecture BNPB sebagaimana dimaksud pada ayat (1) terdiri atas:
a. visi;
b. prinsip;
c. referensi arsitektur;
d. domain;
e. metodologi;
f. perangkat;
g. kapabilitas; dan
h. tata kelola.
(3) Penerapan enterprise architecture di lingkungan BNPB dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
(4) Dokumen enterprise architecture ditetapkan oleh Kepala BNPB.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2388, 'perban-10-2025', 7, 'pasal', 'Pasal 4', 'BAB II PERANAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Ketiga Grand Design TIK', 5, '(1) Enterprise architecture disusun oleh organisasi enterprise architecture BNPB.
(2) Organisasi enterprise architecture terdiri atas:
a. tim pengarah; dan
b. tim enterprise architecture.
(3) Tim pengarah sebagaimana dimaksud pada ayat (2) huruf a terdiri atas pimpinan unit kerja eselon I di lingkungan BNPB.
(4) Tim enterprise architecture sebagaimana dimaksud pada ayat (2) huruf b terdiri atas unit kerja eselon II di lingkungan BNPB.
(5) Organisasi enterprise architecture ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2388, '(1) Enterprise architecture disusun oleh organisasi enterprise architecture BNPB.
(2) Organisasi enterprise architecture terdiri atas:
a. tim pengarah; dan
b. tim enterprise architecture.
(3) Tim pengarah sebagaimana dimaksud pada ayat (2) huruf a terdiri atas pimpinan unit kerja eselon I di lingkungan BNPB.
(4) Tim enterprise architecture sebagaimana dimaksud pada ayat (2) huruf b terdiri atas unit kerja eselon II di lingkungan BNPB.
(5) Organisasi enterprise architecture ditetapkan oleh Kepala BNPB.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2389, 'perban-10-2025', 8, 'pasal', 'Pasal 5', 'BAB II PERANAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Ketiga Grand Design TIK', 5, '(1) Grand Design TIK sebagaimana dimaksud dalam Pasal 2 ayat (2) huruf b merupakan dokumen perencanaan strategis TIK untuk 5 (lima) tahunan.
(2) Grand Design TIK sebagaimana dimaksud pada ayat
(1) paling sedikit memuat:
a. visi dan misi TIK;
b. prinsip implementasi TIK; dan
c. fokus area TIK, terdiri atas identifikasi masalah dan kebutuhan, strategi, dan peta jalan.
(3) Grand Design TIK sebagaimana dimaksud pada ayat
(2) disusun sesuai dengan:
a. Rencana Strategis BNPB; dan
b. Rencana Nasional Penanggulangan Bencana.
(4) Penyusunan dan implementasi Grand Design TIK sebagaimana dimaksud pada ayat (1) dikoordinasikan oleh Pimpinan Unit TIK.
(5) Grand Design TIK ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2389, '(1) Grand Design TIK sebagaimana dimaksud dalam Pasal 2 ayat (2) huruf b merupakan dokumen perencanaan strategis TIK untuk 5 (lima) tahunan.
(2) Grand Design TIK sebagaimana dimaksud pada ayat
(1) paling sedikit memuat:
a. visi dan misi TIK;
b. prinsip implementasi TIK; dan
c. fokus area TIK, terdiri atas identifikasi masalah dan kebutuhan, strategi, dan peta jalan.
(3) Grand Design TIK sebagaimana dimaksud pada ayat
(2) disusun sesuai dengan:
a. Rencana Strategis BNPB; dan
b. Rencana Nasional Penanggulangan Bencana.
(4) Penyusunan dan implementasi Grand Design TIK sebagaimana dimaksud pada ayat (1) dikoordinasikan oleh Pimpinan Unit TIK.
(5) Grand Design TIK ditetapkan oleh Kepala BNPB.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2390, 'perban-10-2025', 9, 'pasal', 'Pasal 6', 'BAB II PERANAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Keempat Investasi Teknologi Informasi dan Komunikasi', 6, '(1) Pemantauan dan evaluasi Grand Design TIK dilaksanakan terhadap penerapan strategi dengan memperhatikan peta jalan.
(2) Pemantauan dan evaluasi sebagaimana dimaksud pada ayat (1) dilaksanakan paling sedikit 1 (satu) kali dalam 1 (satu) tahun.
(3) Pemantauan dan evaluasi Grand Design TIK sebagaimana dimaksud pada ayat (1) dikoordinasikan oleh Pimpinan Unit TIK dengan melibatkan Unit Pemilik Proses Bisnis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2390, '(1) Pemantauan dan evaluasi Grand Design TIK dilaksanakan terhadap penerapan strategi dengan memperhatikan peta jalan.
(2) Pemantauan dan evaluasi sebagaimana dimaksud pada ayat (1) dilaksanakan paling sedikit 1 (satu) kali dalam 1 (satu) tahun.
(3) Pemantauan dan evaluasi Grand Design TIK sebagaimana dimaksud pada ayat (1) dikoordinasikan oleh Pimpinan Unit TIK dengan melibatkan Unit Pemilik Proses Bisnis.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2391, 'perban-10-2025', 10, 'pasal', 'Pasal 7', 'BAB II PERANAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Keempat Investasi Teknologi Informasi dan Komunikasi', 6, '(1) Investasi TIK sebagaimana dimaksud dalam Pasal 2 ayat (3) huruf c dapat berupa:
a. belanja/pengeluaran modal untuk meningkatkan kualitas layanan dan memberikan layanan baru; dan/atau
b. belanja/pengeluaran barang TIK dalam rangka menjaga tingkat dan kualitas layanan.
(2) Investasi TIK sebagaimana dimaksud pada ayat (1) dilaksanakan oleh:
a. Unit TIK; dan
b. Unit Pemilik Proses Bisnis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2391, '(1) Investasi TIK sebagaimana dimaksud dalam Pasal 2 ayat (3) huruf c dapat berupa:
a. belanja/pengeluaran modal untuk meningkatkan kualitas layanan dan memberikan layanan baru; dan/atau
b. belanja/pengeluaran barang TIK dalam rangka menjaga tingkat dan kualitas layanan.
(2) Investasi TIK sebagaimana dimaksud pada ayat (1) dilaksanakan oleh:
a. Unit TIK; dan
b. Unit Pemilik Proses Bisnis.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2392, 'perban-10-2025', 11, 'pasal', 'Pasal 8', 'BAB II PERANAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Keempat Investasi Teknologi Informasi dan Komunikasi', 6, '(1) Investasi TIK oleh Unit TIK sebagaimana dimaksud dalam Pasal 7 ayat (2) huruf a dilaksanakan untuk mendukung:
a. layanan internal; dan
b. layanan publik;
(2) Layanan internal sebagaimana dimaksud pada ayat (1) huruf a merupakan layanan TIK yang dirancang untuk mendukung operasional, koordinasi, dan aktivitas internal BNPB.
(3) Layanan Publik sebagaimana dimaksud pada ayat (1) huruf b merupakan layanan berbasis teknologi yang disediakan oleh BNPB untuk memenuhi kebutuhan dan hak masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2392, '(1) Investasi TIK oleh Unit TIK sebagaimana dimaksud dalam Pasal 7 ayat (2) huruf a dilaksanakan untuk mendukung:
a. layanan internal; dan
b. layanan publik;
(2) Layanan internal sebagaimana dimaksud pada ayat (1) huruf a merupakan layanan TIK yang dirancang untuk mendukung operasional, koordinasi, dan aktivitas internal BNPB.
(3) Layanan Publik sebagaimana dimaksud pada ayat (1) huruf b merupakan layanan berbasis teknologi yang disediakan oleh BNPB untuk memenuhi kebutuhan dan hak masyarakat.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2393, 'perban-10-2025', 12, 'pasal', 'Pasal 9', 'BAB II PERANAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Keempat Investasi Teknologi Informasi dan Komunikasi', 7, '(1) Investasi TIK oleh Unit Pemilik Proses Bisnis sebagaimana dimaksud dalam Pasal 7 ayat (2) huruf b dilaksanakan dalam mendukung:
a. investasi TIK untuk kebutuhan spesifik unit masing-masing; dan
b. investasi TIK yang sesuai dengan tanggung jawab Unit Pemilik Proses Bisnis.
(2) Investasi TIK sebagaimana dimaksud pada ayat (1) dilaksanakan setelah terlebih dahulu dilakukan penyusunan kajian kebutuhan untuk setiap investasi TIK.
(3) Kajian kebutuhan sebagaimana dimaksud pada ayat
(2) memuat:
a. analisis kebutuhan organisasi; dan
b. analisis manfaat biaya.
(4) Dalam hal investasi TIK dilaksanakan dalam rangka peningkatan kualitas layanan dan memberikan layanan baru, kajian kebutuhan dapat memuat analisis perbandingan tolak ukur penerapan pada organisasi lain.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2393, '(1) Investasi TIK oleh Unit Pemilik Proses Bisnis sebagaimana dimaksud dalam Pasal 7 ayat (2) huruf b dilaksanakan dalam mendukung:
a. investasi TIK untuk kebutuhan spesifik unit masing-masing; dan
b. investasi TIK yang sesuai dengan tanggung jawab Unit Pemilik Proses Bisnis.
(2) Investasi TIK sebagaimana dimaksud pada ayat (1) dilaksanakan setelah terlebih dahulu dilakukan penyusunan kajian kebutuhan untuk setiap investasi TIK.
(3) Kajian kebutuhan sebagaimana dimaksud pada ayat
(2) memuat:
a. analisis kebutuhan organisasi; dan
b. analisis manfaat biaya.
(4) Dalam hal investasi TIK dilaksanakan dalam rangka peningkatan kualitas layanan dan memberikan layanan baru, kajian kebutuhan dapat memuat analisis perbandingan tolak ukur penerapan pada organisasi lain.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2394, 'perban-10-2025', 13, 'pasal', 'Pasal 10', 'BAB II PERANAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Kelima Manajemen Risiko Teknologi Informasi dan Komunikasi', 7, '(1) Kajian kebutuhan sebagaimana dimaksud dalam Pasal 9 ayat (2) diperlukan sebagai pertimbangan dalam proses seleksi untuk menentukan prioritas investasi TIK.
(2) Penentuan prioritas investasi TIK sebagaimana dimaksud pada ayat (1) memperhatikan:
a. rencana strategis BNPB;
b. Grand Design TIK; dan/atau
c. rencana strategis tingkat nasional mengenai sistem pemerintahan berbasis elektronik dan satu data Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2394, '(1) Kajian kebutuhan sebagaimana dimaksud dalam Pasal 9 ayat (2) diperlukan sebagai pertimbangan dalam proses seleksi untuk menentukan prioritas investasi TIK.
(2) Penentuan prioritas investasi TIK sebagaimana dimaksud pada ayat (1) memperhatikan:
a. rencana strategis BNPB;
b. Grand Design TIK; dan/atau
c. rencana strategis tingkat nasional mengenai sistem pemerintahan berbasis elektronik dan satu data Indonesia.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2395, 'perban-10-2025', 14, 'pasal', 'Pasal 11', 'BAB III PENYELENGGARA TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Kesatu Umum', 7, '(1) Manajemen Risiko TIK dilaksanakan untuk menjaga efektivitas, efisiensi, keamanan, dan keandalan TIK dalam mendukung pencapaian tujuan BNPB dan meminimalkan dampak risiko pada proses bisnis BNPB.
(2) Manajemen Risiko TIK sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2395, '(1) Manajemen Risiko TIK dilaksanakan untuk menjaga efektivitas, efisiensi, keamanan, dan keandalan TIK dalam mendukung pencapaian tujuan BNPB dan meminimalkan dampak risiko pada proses bisnis BNPB.
(2) Manajemen Risiko TIK sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2396, 'perban-10-2025', 15, 'pasal', 'Pasal 12', 'BAB III PENYELENGGARA TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Kedua Komite TIK', 8, 'Penyelenggara tata kelola, pengelolaan, dan pemanfaatan TIK BNPB terdiri atas:
a. komite TIK;
b. chief information officer;
c. Unit TIK;
d. Unit Pemilik Proses Bisnis; dan
e. Pihak Eksternal.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2396, 'Penyelenggara tata kelola, pengelolaan, dan pemanfaatan TIK BNPB terdiri atas:
a. komite TIK;
b. chief information officer;
c. Unit TIK;
d. Unit Pemilik Proses Bisnis; dan
e. Pihak Eksternal.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2397, 'perban-10-2025', 16, 'pasal', 'Pasal 13', 'BAB III PENYELENGGARA TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Ketiga Chief Information Officer', 8, '(1) Komite TIK sebagaimana dimaksud dalam Pasal 12 huruf a terdiri atas:
a. Sekretaris Utama BNPB sebagai ketua;
b. chief information officer sebagai sekretaris; dan
c. pimpinan tinggi pratama yang membawahi Unit Pemilik Proses Bisnis di lingkungan BNPB sebagai anggota.
(2) Komite TIK BNPB sebagaimana dimaksud pada ayat
(1) bertugas:
a. merumuskan kebijakan teknis TIK dalam Grand Design TIK;
b. memberikan pertimbangan dan/atau rekomendasi atas rencana kegiatan atau belanja/investasi kebutuhan TIK sesuai Grand Design TIK dalam rangka memastikan tidak adanya tumpang tindih pengadaan TIK antar unit; dan
c. melakukan pemantauan dan evaluasi berkala terhadap pelaksanaan Grand Design TIK.
(3) Pembentukan Komite TIK ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2397, '(1) Komite TIK sebagaimana dimaksud dalam Pasal 12 huruf a terdiri atas:
a. Sekretaris Utama BNPB sebagai ketua;
b. chief information officer sebagai sekretaris; dan
c. pimpinan tinggi pratama yang membawahi Unit Pemilik Proses Bisnis di lingkungan BNPB sebagai anggota.
(2) Komite TIK BNPB sebagaimana dimaksud pada ayat
(1) bertugas:
a. merumuskan kebijakan teknis TIK dalam Grand Design TIK;
b. memberikan pertimbangan dan/atau rekomendasi atas rencana kegiatan atau belanja/investasi kebutuhan TIK sesuai Grand Design TIK dalam rangka memastikan tidak adanya tumpang tindih pengadaan TIK antar unit; dan
c. melakukan pemantauan dan evaluasi berkala terhadap pelaksanaan Grand Design TIK.
(3) Pembentukan Komite TIK ditetapkan oleh Kepala BNPB.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2398, 'perban-10-2025', 17, 'pasal', 'Pasal 14', 'BAB III PENYELENGGARA TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Keempat Unit Teknologi Informasi dan Komunikasi', 8, '(1) Chief information officer sebagaimana dimaksud dalam Pasal 12 huruf b dilaksanakan oleh pimpinan unit kerja yang mempunyai tugas melaksanakan koordinasi dan pelayanan di bidang pengelolaan data dan informasi, pengembangan Basis Data dan informasi.
(2) Chief information officer sebagaimana dimaksud pada ayat (1) memiliki tugas:
a. menyusun Grand Design TIK setiap 5 (lima) tahun sekali dan menyampaikan kepada Komite TIK;
b. mengoordinasikan perencanaan dan pelaksanaan inisiatif pengembangan TIK di lingkungan BNPB;
c. melakukan evaluasi secara berkala setiap 1 (satu) tahun sekali atas pelaksanaan TIK di lingkungan BNPB;
d. menyusun kebijakan dan prosedur operasional standar Tata Kelola TIK;
e. melakukan sosialisasi kebijakan pengelolaan TIK kepada semua pengguna;
f. melakukan koordinasi dengan Unit Pemilik Proses Bisnis dalam pemeliharaan sumber daya TIK;
g. mengembangkan kompetensi sumber daya manusia TIK;
h. mengoordinasikan pengelolaan keamanan informasi di lingkungan BNPB;
i. mengoordinasikan perumusan dan penyempurnaan kebijakan mengenai pengelolaan keamanan informasi di lingkungan BNPB;
j. melaksanakan tugas dan wewenang lain terkait koordinasi pengelolaan keamanan informasi di lingkungan BNPB;
k. mengoordinasikan implementasi enterprise architecture BNPB;
l. menyusun ketentuan teknis mengenai enterprise architecture BNPB;
m. mengoordinasikan tata kelola data di lingkungan BNPB;
n. menyusun kebijakan mengenai penatalayanan dan pengolahan data di lingkungan BNPB;
o. melaksanakan tugas dan wewenang lain terkait koordinasi implementasi enterprise architecture BNPB; dan
p. melaksanakan tugas dan wewenang lain terkait koordinasi implementasi tata kelola data di lingkungan BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2398, '(1) Chief information officer sebagaimana dimaksud dalam Pasal 12 huruf b dilaksanakan oleh pimpinan unit kerja yang mempunyai tugas melaksanakan koordinasi dan pelayanan di bidang pengelolaan data dan informasi, pengembangan Basis Data dan informasi.
(2) Chief information officer sebagaimana dimaksud pada ayat (1) memiliki tugas:
a. menyusun Grand Design TIK setiap 5 (lima) tahun sekali dan menyampaikan kepada Komite TIK;
b. mengoordinasikan perencanaan dan pelaksanaan inisiatif pengembangan TIK di lingkungan BNPB;
c. melakukan evaluasi secara berkala setiap 1 (satu) tahun sekali atas pelaksanaan TIK di lingkungan BNPB;
d. menyusun kebijakan dan prosedur operasional standar Tata Kelola TIK;
e. melakukan sosialisasi kebijakan pengelolaan TIK kepada semua pengguna;
f. melakukan koordinasi dengan Unit Pemilik Proses Bisnis dalam pemeliharaan sumber daya TIK;
g. mengembangkan kompetensi sumber daya manusia TIK;
h. mengoordinasikan pengelolaan keamanan informasi di lingkungan BNPB;
i. mengoordinasikan perumusan dan penyempurnaan kebijakan mengenai pengelolaan keamanan informasi di lingkungan BNPB;
j. melaksanakan tugas dan wewenang lain terkait koordinasi pengelolaan keamanan informasi di lingkungan BNPB;
k. mengoordinasikan implementasi enterprise architecture BNPB;
l. menyusun ketentuan teknis mengenai enterprise architecture BNPB;
m. mengoordinasikan tata kelola data di lingkungan BNPB;
n. menyusun kebijakan mengenai penatalayanan dan pengolahan data di lingkungan BNPB;
o. melaksanakan tugas dan wewenang lain terkait koordinasi implementasi enterprise architecture BNPB; dan
p. melaksanakan tugas dan wewenang lain terkait koordinasi implementasi tata kelola data di lingkungan BNPB.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2399, 'perban-10-2025', 18, 'pasal', 'Pasal 15', 'BAB III PENYELENGGARA TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Kelima Unit Pemilik Proses Bisnis', 9, '(1) Unit TIK sebagaimana dimaksud dalam Pasal 12 huruf c dilaksanakan oleh unit kerja yang mempunyai tugas melaksanakan koordinasi dan pelayanan di bidang pengelolaan data dan informasi, pengembangan Basis Data dan informasi.
(2) Unit TIK sebagaimana dimaksud pada ayat (1) mempunyai tugas:
a. mengelola Layanan TIK;
b. mengelola data BNPB sesuai dengan lingkup tugas dan tanggung jawab Unit TIK sebagai walidata bencana;
c. melakukan pengelolaan risiko dan penanggulangan bencana TIK;
d. mengevaluasi pelaksanaan kualitas operasional Layanan TIK; dan
e. menjaga Aset TIK.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2399, '(1) Unit TIK sebagaimana dimaksud dalam Pasal 12 huruf c dilaksanakan oleh unit kerja yang mempunyai tugas melaksanakan koordinasi dan pelayanan di bidang pengelolaan data dan informasi, pengembangan Basis Data dan informasi.
(2) Unit TIK sebagaimana dimaksud pada ayat (1) mempunyai tugas:
a. mengelola Layanan TIK;
b. mengelola data BNPB sesuai dengan lingkup tugas dan tanggung jawab Unit TIK sebagai walidata bencana;
c. melakukan pengelolaan risiko dan penanggulangan bencana TIK;
d. mengevaluasi pelaksanaan kualitas operasional Layanan TIK; dan
e. menjaga Aset TIK.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2400, 'perban-10-2025', 19, 'pasal', 'Pasal 16', 'BAB III PENYELENGGARA TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Keenam Pihak Eksternal', 10, '(1) Unit Pemilik Proses Bisnis sebagaimana dimaksud dalam Pasal 12 huruf d merupakan unit kerja yang dipimpin oleh pejabat pimpinan tinggi pratama di lingkungan BNPB.
(2) Unit Pemilik Proses Bisnis sebagaimana dimaksud pada ayat (1) mempunyai tugas dan tanggung jawab:
a. mengidentifikasi kebutuhan pembangunan dan/atau pengembangan Aset TIK dan disampaikan kepada chief information officer;
b. memanfaatkan Aplikasi Khusus dan/atau Aplikasi Umum yang sesuai dengan tugas dan fungsinya; dan
c. melakukan evaluasi atas pelaksanaan kualitas operasional Layanan TIK.
(3) Evaluasi sebagaimana dimaksud pada ayat (2) huruf c dilaksanakan bersama dengan Unit TIK.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2400, '(1) Unit Pemilik Proses Bisnis sebagaimana dimaksud dalam Pasal 12 huruf d merupakan unit kerja yang dipimpin oleh pejabat pimpinan tinggi pratama di lingkungan BNPB.
(2) Unit Pemilik Proses Bisnis sebagaimana dimaksud pada ayat (1) mempunyai tugas dan tanggung jawab:
a. mengidentifikasi kebutuhan pembangunan dan/atau pengembangan Aset TIK dan disampaikan kepada chief information officer;
b. memanfaatkan Aplikasi Khusus dan/atau Aplikasi Umum yang sesuai dengan tugas dan fungsinya; dan
c. melakukan evaluasi atas pelaksanaan kualitas operasional Layanan TIK.
(3) Evaluasi sebagaimana dimaksud pada ayat (2) huruf c dilaksanakan bersama dengan Unit TIK.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2401, 'perban-10-2025', 20, 'pasal', 'Pasal 17', 'BAB III PENYELENGGARA TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Keenam Pihak Eksternal', 10, '(1) Untuk mendukung penyelenggaraan tata kelola TIK, Unit TIK dapat melakukan kerja sama dengan Pihak Eksternal.
(2) Kerja sama sebagaimana dimaksud pada ayat (1) dilaksanakan dengan perjanjian kerja sama berdasarkan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2401, '(1) Untuk mendukung penyelenggaraan tata kelola TIK, Unit TIK dapat melakukan kerja sama dengan Pihak Eksternal.
(2) Kerja sama sebagaimana dimaksud pada ayat (1) dilaksanakan dengan perjanjian kerja sama berdasarkan ketentuan peraturan perundang-undangan.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2402, 'perban-10-2025', 21, 'pasal', 'Pasal 18', 'BAB IV PENYELENGGARAAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Kesatu Umum', 10, 'Pihak Eksternal sebagaimana dimaksud dalam Pasal 17 terdiri atas:
a. kementerian yang menyelenggarakan urusan pemerintahan di bidang komunikasi dan digital;
b. kementerian yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara dan reformasi birokrasi;
c. kementerian/lembaga yang berkaitan dengan penyelenggaraan TIK nasional;
d. badan usaha lain yang berkaitan dengan penyelenggaraan TIK nasional;
e. pemerintah daerah; dan
f. komunitas keamanan informasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2402, 'Pihak Eksternal sebagaimana dimaksud dalam Pasal 17 terdiri atas:
a. kementerian yang menyelenggarakan urusan pemerintahan di bidang komunikasi dan digital;
b. kementerian yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara dan reformasi birokrasi;
c. kementerian/lembaga yang berkaitan dengan penyelenggaraan TIK nasional;
d. badan usaha lain yang berkaitan dengan penyelenggaraan TIK nasional;
e. pemerintah daerah; dan
f. komunitas keamanan informasi.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2403, 'perban-10-2025', 22, 'pasal', 'Pasal 19', 'BAB IV PENYELENGGARAAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Kedua Pengelolaan Data', 11, 'Penyelenggaraan TIK terdiri atas:
a. pengelolaan data;
b. pengembangan sistem informasi;
c. portofolio TIK;
d. standar TIK;
e. DC Badan Nasional Penanggulangan Bencana dan DRC Badan Nasional Penanggulangan Bencana; dan
f. pengelolaan keamanan informasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2403, 'Penyelenggaraan TIK terdiri atas:
a. pengelolaan data;
b. pengembangan sistem informasi;
c. portofolio TIK;
d. standar TIK;
e. DC Badan Nasional Penanggulangan Bencana dan DRC Badan Nasional Penanggulangan Bencana; dan
f. pengelolaan keamanan informasi.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2404, 'perban-10-2025', 23, 'pasal', 'Pasal 20', 'BAB IV PENYELENGGARAAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Ketiga Pengembangan Sistem Informasi', 11, '(1) Pengelolaan Data BNPB sebagaimana dimaksud dalam Pasal 19 huruf a dilaksanakan dengan memperhatikan pengelolaan:
a. enterprise architecture untuk domain Data;
b. kualitas Data; dan
c. keamanan Data.
(2) Pengelolaan Data BNPB sebagaimana dimaksud pada ayat (1) digunakan untuk mendukung proses bisnis, pengambilan keputusan, keterbukaan informasi publik, dan penyelenggaraan satu Data bencana Indonesia.
(3) Pengelolaan enterprise architecture untuk domain Data sebagaimana dimaksud pada ayat (1) huruf a dilaksanakan untuk:
a. menyediakan Data yang berkualitas;
b. mengidentifikasi dan mendefinisikan kebutuhan Data; dan
c. merancang struktur dan rencana untuk memenuhi kebutuhan Data saat ini dan kebutuhan data jangka panjang.
(4) Pengelolaan kualitas Data sebagaimana dimaksud pada ayat (1) huruf b dilaksanakan untuk:
a. menjamin Data yang dihasilkan:
b. memenuhi prinsip satu Data Indonesia; dan
c. memenuhi standar kualitas Data, mencakup keakuratan, kelengkapan, konsistensi, kewajaran, ketepatan waktu, keunikan, dan keabsahan.
(5) Pengelolaan keamanan Data sebagaimana dimaksud pada ayat (1) huruf c dilaksanakan untuk:
a. memenuhi standar keamanan Data, mencakup kerahasiaan, otentikasi akses, otorisasi akses, dan pelindungan Data pribadi;
b. menjamin kelangsungan ketersediaan akses Data; dan
c. menjaga keamanan Data dari akses yang tidak sesuai dengan peraturan perundang-undangan.
(6) Pengelolaan Data sebagaimana dimaksud pada ayat (1) dilaksanakan oleh Unit TIK.
(7) Pengelolaan Data dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
