INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2405, 'perban-10-2025', 24, 'pasal', 'Pasal 21', 'BAB IV PENYELENGGARAAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Ketiga Pengembangan Sistem Informasi', 12, '(1) Pengembangan Sistem Informasi sebagaimana dimaksud dalam Pasal 19 huruf b bertujuan untuk mendukung implementasi layanan pemerintahan berbasis digital.
(2) Sistem Informasi sebagaimana dimaksud pada ayat (1) terdiri atas aplikasi dan Basis Data.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2405, '(1) Pengembangan Sistem Informasi sebagaimana dimaksud dalam Pasal 19 huruf b bertujuan untuk mendukung implementasi layanan pemerintahan berbasis digital.
(2) Sistem Informasi sebagaimana dimaksud pada ayat (1) terdiri atas aplikasi dan Basis Data.', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2406, 'perban-10-2025', 25, 'pasal', 'Pasal 22', 'BAB IV PENYELENGGARAAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Ketiga Pengembangan Sistem Informasi', 12, '(1) Pengembangan Sistem Informasi dilaksanakan oleh Unit TIK.
(2) Pengembangan Sistem Informasi sebagaimana dimaksud pada ayat (1) dilaksanakan melalui:
a. pengembangan Sistem Informasi Internal;
b. pengembangan Sistem Informasi Eksternal;
c. JAD; atau
d. pemanfaatan akuisisi perangkat lunak yang tersedia:
1) secara komersil (Commercial Off-The-Shelf); atau 2) sebagai sumber terbuka (open source).
(3) Pengembangan Sistem Informasi Internal sebagaimana dimaksud pada ayat (2) huruf a merupakan kegiatan yang dilaksanakan secara mandiri dengan memanfaatkan sumber daya internal.
(4) Pengembangan Sistem Informasi Eksternal sebagaimana dimaksud pada ayat (2) huruf b merupakan kegiatan yang dilaksanakan melalui kerjasama dengan pihak ketiga sesuai dengan peraturan perundang-undangan mengenai pengadaan barang/jasa pemerintah.
(5) JAD sebagaimana dimaksud pada ayat (2) huruf c merupakan pengembangan Sistem Informasi yang dilaksanakan secara bersama-sama oleh Unit TIK dengan melibatkan pemilik proses bisnis serta pihak ketiga yang bekerja sama sesuai dengan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2406, '(1) Pengembangan Sistem Informasi dilaksanakan oleh Unit TIK.
(2) Pengembangan Sistem Informasi sebagaimana dimaksud pada ayat (1) dilaksanakan melalui:
a. pengembangan Sistem Informasi Internal;
b. pengembangan Sistem Informasi Eksternal;
c. JAD; atau
d. pemanfaatan akuisisi perangkat lunak yang tersedia:
1) secara komersil (Commercial Off-The-Shelf); atau 2) sebagai sumber terbuka (open source).
(3) Pengembangan Sistem Informasi Internal sebagaimana dimaksud pada ayat (2) huruf a merupakan kegiatan yang dilaksanakan secara mandiri dengan memanfaatkan sumber daya internal.
(4) Pengembangan Sistem Informasi Eksternal sebagaimana dimaksud pada ayat (2) huruf b merupakan kegiatan yang dilaksanakan melalui kerjasama dengan pihak ketiga sesuai dengan peraturan perundang-undangan mengenai pengadaan barang/jasa pemerintah.
(5) JAD sebagaimana dimaksud pada ayat (2) huruf c merupakan pengembangan Sistem Informasi yang dilaksanakan secara bersama-sama oleh Unit TIK dengan melibatkan pemilik proses bisnis serta pihak ketiga yang bekerja sama sesuai dengan peraturan perundang-undangan.', 'Pasal 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2407, 'perban-10-2025', 26, 'pasal', 'Pasal 23', 'BAB IV PENYELENGGARAAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Ketiga Pengembangan Sistem Informasi', 12, 'Pengembangan Sistem Informasi sebagaimana dimaksud dalam Pasal 22 dilaksanakan dengan memperhatikan:
a. pengembangan Aplikasi Khusus yang dikoordinasikan oleh Unit Pemilik Proses Bisnis;
b. kajian kebutuhan pengembangan Sistem Informasi;
c. pelaksanaan secara terencana, bertahap, serta berkesinambungan yang selaras dengan rencana strategis BNPB, Grand Design TIK BNPB, enterprise architecture BNPB, dan ketentuan peraturan perundang-undangan;
d. integrasi dan interoperabilitas dengan Sistem Informasi lainnya;
e. keamanan Sistem Informasi sesuai ketentuan peraturan perundang-undangan;
f. ketersediaan Sistem Informasi berdasarkan tingkat kekritisan; dan
g. ketentuan mengenai hak atas kekayaan intelektual.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2407, 'Pengembangan Sistem Informasi sebagaimana dimaksud dalam Pasal 22 dilaksanakan dengan memperhatikan:
a. pengembangan Aplikasi Khusus yang dikoordinasikan oleh Unit Pemilik Proses Bisnis;
b. kajian kebutuhan pengembangan Sistem Informasi;
c. pelaksanaan secara terencana, bertahap, serta berkesinambungan yang selaras dengan rencana strategis BNPB, Grand Design TIK BNPB, enterprise architecture BNPB, dan ketentuan peraturan perundang-undangan;
d. integrasi dan interoperabilitas dengan Sistem Informasi lainnya;
e. keamanan Sistem Informasi sesuai ketentuan peraturan perundang-undangan;
f. ketersediaan Sistem Informasi berdasarkan tingkat kekritisan; dan
g. ketentuan mengenai hak atas kekayaan intelektual.', 'Pasal 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2408, 'perban-10-2025', 27, 'pasal', 'Pasal 24', 'BAB IV PENYELENGGARAAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Keempat Portofolio Teknologi Informasi dan Komunikasi dan Standar', 13, '(1) Pengembangan Sistem Informasi dilakukan melalui:
a. perencanaan Sistem Informasi;
b. analisis Sistem Informasi;
c. perancangan Sistem Informasi;
d. implementasi Sistem Informasi;
e. pemeliharaan Sistem Informasi; dan
f. aktivitas lain sesuai dengan kebutuhan pengembangan Sistem Informasi yang mengacu pada praktik terbaik.
(2) Pengembangan Sistem Informasi sebagaimana dimaksud pada ayat (1) mengacu pada metodologi pengembangan Sistem Informasi yang ditetapkan oleh Unit TIK.
(3) Hasil pengembangan Sistem Informasi berupa Kode Sumber (source code) dan dokumentasi Sistem Informasi.
(4) Dalam hal hasil pengembangan Sistem Informasi dihasilkan oleh Pihak Eksternal, Kode Sumber (source code) dan dokumentasi Sistem Informasi harus diserahkan kepada Unit TIK.
(5) Pengembangan Sistem Informasi sebagaimana dimaksud pada ayat (1) wajib menjaga kerahasiaan data, informasi, dan kredensial pengguna melalui non-disclosure agreement.
(6) Dalam hal pengembangan dan/atau pemeliharaan Sistem Informasi dilakukan oleh Pihak Eksternal, Unit TIK memberikan kredensial pengguna.
(7) Dalam hal masa pengembangan dan/atau pemeliharaan berakhir, Unit TIK menghapus kredensial pengguna yang digunakan oleh Pihak Eksternal.
Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2408, '(1) Pengembangan Sistem Informasi dilakukan melalui:
a. perencanaan Sistem Informasi;
b. analisis Sistem Informasi;
c. perancangan Sistem Informasi;
d. implementasi Sistem Informasi;
e. pemeliharaan Sistem Informasi; dan
f. aktivitas lain sesuai dengan kebutuhan pengembangan Sistem Informasi yang mengacu pada praktik terbaik.
(2) Pengembangan Sistem Informasi sebagaimana dimaksud pada ayat (1) mengacu pada metodologi pengembangan Sistem Informasi yang ditetapkan oleh Unit TIK.
(3) Hasil pengembangan Sistem Informasi berupa Kode Sumber (source code) dan dokumentasi Sistem Informasi.
(4) Dalam hal hasil pengembangan Sistem Informasi dihasilkan oleh Pihak Eksternal, Kode Sumber (source code) dan dokumentasi Sistem Informasi harus diserahkan kepada Unit TIK.
(5) Pengembangan Sistem Informasi sebagaimana dimaksud pada ayat (1) wajib menjaga kerahasiaan data, informasi, dan kredensial pengguna melalui non-disclosure agreement.
(6) Dalam hal pengembangan dan/atau pemeliharaan Sistem Informasi dilakukan oleh Pihak Eksternal, Unit TIK memberikan kredensial pengguna.
(7) Dalam hal masa pengembangan dan/atau pemeliharaan berakhir, Unit TIK menghapus kredensial pengguna yang digunakan oleh Pihak Eksternal.
Teknologi Informasi dan Komunikasi', 'Pasal 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2025 tentang Tata Kelola Teknologi Informasi dan Komunikasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2409, 'perban-10-2025', 28, 'pasal', 'Pasal 25', 'BAB IV PENYELENGGARAAN TEKNOLOGI INFORMASI DAN KOMUNIKASI; Bagian Kelima Pusat Data (Data Center) Badan Nasional Penanggulangan', 13, '(1) Portofolio TIK sebagaimana dimaksud dalam Pasal 19 huruf c merupakan daftar aset pada setiap lapisan (layer) infrastruktur TIK.
(2) Dalam mendukung interoperabilitas, efektivitas, dan efisiensi pemanfaatan teknologi pada portofolio TIK BNPB disusun standar TIK.
(3) Standar TIK sebagaimana dimaksud pada ayat (2) memuat:
a. standar produk; dan/atau
b. konfigurasi TIK.
(4) Standar produk sebagaimana dimaksud pada ayat (3) huruf a memperhatikan prinsip:
a. penggunaan teknologi yang tepat;
b. standarisasi teknologi;
c. mudah dikelola;
d. interoperabilitas;
e. efektif dan efisien;
f. aman; dan
g. andal.
(5) Penentuan konfigurasi TIK sebagaimana dimaksud pada ayat (3) huruf b memperhatikan:
a. standar konfigurasi TIK dari prinsipal atau komunitas keamanan informasi di luar BNPB; dan/atau
b. praktik terbaik.
(6) Penyusunan dan pengelolaan portofolio TIK sebagaimana dimaksud pada ayat (1) dan standar TIK sebagaimana dimaksud pada ayat (3) dikoordinasikan oleh Unit TIK dengan melibatkan Unit Pemilik Proses Bisnis.
(7) Portofolio TIK dan standar TIK sebagaimana dimaksud pada ayat (6) dikembangkan dan dievaluasi oleh Unit TIK sesuai dengan kebutuhan organisasi.
(8) Standar TIK ditetapkan oleh Kepala BNPB.
Bencana dan Pusat Pemulihan Keadaan Bencana (Disaster Recovery Center) Badan Nasional Penangulangan Bencana');
