INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2466, 'perban-11-2025', 43, 'pasal', 'Pasal 137', NULL, 13, '(1) Kepala merupakan jabatan pimpinan tinggi utama.
(2) Sekretaris Utama, Deputi, dan Inspektur Utama merupakan jabatan pimpinan tinggi madya atau jabatan struktural eselon I.a.
(3) Kepala Biro, Direktur, Inspektur, dan Kepala Pusat merupakan jabatan pimpinan tinggi pratama atau jabatan struktural eselon II.a.
(4) Kepala Bagian merupakan jabatan administrator atau jabatan struktural eselon III.a.
(5) Kepala Subbagian merupakan jabatan pengawas atau jabatan struktural eselon IV.a.
37. Ketentuan ayat (2) dan ayat (3) Pasal 138 diubah, sehingga berbunyi sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2466, '(1) Kepala merupakan jabatan pimpinan tinggi utama.
(2) Sekretaris Utama, Deputi, dan Inspektur Utama merupakan jabatan pimpinan tinggi madya atau jabatan struktural eselon I.a.
(3) Kepala Biro, Direktur, Inspektur, dan Kepala Pusat merupakan jabatan pimpinan tinggi pratama atau jabatan struktural eselon II.a.
(4) Kepala Bagian merupakan jabatan administrator atau jabatan struktural eselon III.a.
(5) Kepala Subbagian merupakan jabatan pengawas atau jabatan struktural eselon IV.a.
37. Ketentuan ayat (2) dan ayat (3) Pasal 138 diubah, sehingga berbunyi sebagai berikut:', 'Pasal 137', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2025 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2467, 'perban-11-2025', 44, 'pasal', 'Pasal 138', NULL, 13, '(1) Kepala diangkat dan diberhentikan oleh Presiden.
(2) Sekretaris Utama, Deputi, dan Inspektur Utama diangkat dan diberhentikan oleh Presiden atas usul Kepala, setelah melalui prosedur seleksi berdasarkan ketentuan peraturan perundang-undangan.
(3) Kepala Biro, Direktur, Inspektur, dan Kepala Pusat diangkat dan diberhentikan oleh Kepala, setelah melalui prosedur seleksi berdasarkan ketentuan peraturan perundang-undangan.
(4) Kepala Bagian dan Kepala Subbagian diangkat dan diberhentikan oleh Kepala sesuai dengan ketentuan peraturan perundang-undangan.
(5) Pejabat fungsional diangkat dan diberhentikan sesuai dengan ketentuan peraturan perundang-undangan.
38. Lampiran dalam Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana diubah sehingga menjadi sebagaimana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2467, '(1) Kepala diangkat dan diberhentikan oleh Presiden.
(2) Sekretaris Utama, Deputi, dan Inspektur Utama diangkat dan diberhentikan oleh Presiden atas usul Kepala, setelah melalui prosedur seleksi berdasarkan ketentuan peraturan perundang-undangan.
(3) Kepala Biro, Direktur, Inspektur, dan Kepala Pusat diangkat dan diberhentikan oleh Kepala, setelah melalui prosedur seleksi berdasarkan ketentuan peraturan perundang-undangan.
(4) Kepala Bagian dan Kepala Subbagian diangkat dan diberhentikan oleh Kepala sesuai dengan ketentuan peraturan perundang-undangan.
(5) Pejabat fungsional diangkat dan diberhentikan sesuai dengan ketentuan peraturan perundang-undangan.
38. Lampiran dalam Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana diubah sehingga menjadi sebagaimana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 138', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2025 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2468, 'perban-11-2025', 45, 'pasal', 'Pasal II', NULL, 13, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2468, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
