INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2475, 'perban-2-2018', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2018 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2475, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2018 tentang Penggunaan Dana Siap Pakai', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2018 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2476, 'perban-2-2018', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk pelaksanaan kebijakan pendanaan dan pengelolaan bantuan bencana dalam penyelenggaraan penanggulangan bencana sebagaimana telah diatur dalam Pasal 17 ayat (3) Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana, telah ditetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6.A Tahun 2011 tentang Pedoman Penggunaan Dana Siap Pakai pada Status Keadaan Darurat Bencana;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6.A Tahun 2011 tentang Pedoman Penggunaan Dana Siap Pakai pada Status Keadaan Darurat Bencana dalam implementasinya perlu penyesuaian dengan dinamika penanganan darurat bencana saat ini, sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan 2018, No. 382 -2- Peraturan Badan Nasional Penanggulangan Bencana tentang Penggunaan Dana Siap Pakai;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2476, 'a. bahwa untuk pelaksanaan kebijakan pendanaan dan pengelolaan bantuan bencana dalam penyelenggaraan penanggulangan bencana sebagaimana telah diatur dalam Pasal 17 ayat (3) Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana, telah ditetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6.A Tahun 2011 tentang Pedoman Penggunaan Dana Siap Pakai pada Status Keadaan Darurat Bencana;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6.A Tahun 2011 tentang Pedoman Penggunaan Dana Siap Pakai pada Status Keadaan Darurat Bencana dalam implementasinya perlu penyesuaian dengan dinamika penanganan darurat bencana saat ini, sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan 2018, No. 382 -2- Peraturan Badan Nasional Penanggulangan Bencana tentang Penggunaan Dana Siap Pakai;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2018 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2477, 'perban-2-2018', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 244, Tambahan Lembaran Negara Republik Indonesia Nomor 5587) sebagaimana telah beberapa kali diubah, terakhir dengan Undang-Undang Nomor 9 Tahun 2015 tentang Perubahan Kedua atas Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2015 Nomor 58, Tambahan Lembaran Negara Republik Indonesia Nomor 5679);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 18 Tahun 2016 tentang Perangkat Daerah (Lembaran Negara Republik Indonesia Tahun 2016 Nomor 114, Tambahan Lembaran Negara Republik Indonesia Nomor 5887);
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Peraturan Menteri Keuangan Nomor 105/PMK.05/2013 tentang Mekanisme Pelaksanaan Anggaran Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2013 Nomor 971);
2018, No. 382
8. Peraturan Menteri Keuangan Nomor 168/PMK.05/2015 tentang Mekanisme Pelaksanaan Anggaran Bantuan Pemerintah pada Kementerian Negara/Lembaga (Berita Negara Republik Indonesia Tahun 2015 Nomor 1340);');
