INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2516, 'perban-2-2018', 41, 'pasal', 'Pasal 38', 'BAB X KETENTUAN LAIN-LAIN', 39, '(1) DSP juga digunakan untuk kegiatan yang berhubungan dengan antisipasi ancaman bencana sangat mendesak guna mengurangi risiko dan dampak yang lebih luas.
