INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2517, 'perban-2-2018', 42, 'pasal', 'Pasal 39', 'BAB XI KETENTUAN PENUTUP', 39, '(1) Semua hasil pengadaan barang/jasa yang menggunakan DSP kecuali barang habis pakai dilakukan pelabelan, dan dicatat dalam BMN/BMD selanjutnya dilaporkan ke BNPB.
