INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2523, 'perban-2-2019', 1, 'menimbang', 'Menimbang', NULL, 1, 'bahwa untuk melaksanakan ketentuan Pasal 54 ayat (3) Peraturan Pemerintah Nomor 38 Tahun 2016 tentang Tata Cara Tuntutan Ganti Kerugian Negara/Daerah Terhadap Pegawai Negeri Bukan Bendahara Atau Pejabat Lain, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Tata Cara Penyelesaian Kerugian Negara;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2523, 'bahwa untuk melaksanakan ketentuan Pasal 54 ayat (3) Peraturan Pemerintah Nomor 38 Tahun 2016 tentang Tata Cara Tuntutan Ganti Kerugian Negara/Daerah Terhadap Pegawai Negeri Bukan Bendahara Atau Pejabat Lain, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Tata Cara Penyelesaian Kerugian Negara;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2524, 'perban-2-2019', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Peraturan Pemerintah Nomor 38 Tahun 2016 tentang Tata Cara Tuntutan Ganti Kerugian Negara/Daerah Terhadap Pegawai Negeri Bukan Bendahara Atau Pejabat Lain (Lembaran Negara Republik Indonesia Tahun 2016 Nomor 196, Tambahan Lembaran Negara Republik Indonesia Nomor 5934);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1);
3. Peraturan Badan Pemeriksa Keuangan Republik Indonesia Nomor 3 Tahun 2007 tentang Tata Cara Penyelesaian Ganti Kerugian Negara Terhadap Bendahara 2019, No. 740 -2- (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 147);
4. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2013 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2013 Nomor 1441);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2524, '1. Peraturan Pemerintah Nomor 38 Tahun 2016 tentang Tata Cara Tuntutan Ganti Kerugian Negara/Daerah Terhadap Pegawai Negeri Bukan Bendahara Atau Pejabat Lain (Lembaran Negara Republik Indonesia Tahun 2016 Nomor 196, Tambahan Lembaran Negara Republik Indonesia Nomor 5934);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1);
3. Peraturan Badan Pemeriksa Keuangan Republik Indonesia Nomor 3 Tahun 2007 tentang Tata Cara Penyelesaian Ganti Kerugian Negara Terhadap Bendahara 2019, No. 740 -2- (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 147);
4. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2013 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2013 Nomor 1441);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2525, 'perban-2-2019', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA CARA PENYELESAIAN KERUGIAN NEGARA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2525, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA CARA PENYELESAIAN KERUGIAN NEGARA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2526, 'perban-2-2019', 4, 'pasal', 'Pasal 1', 'BAB II TATA CARA PENYELESAIAN KERUGIAN NEGARA', 2, 'Dalam Peraturan Badan ini, yang dimaksud dengan:
1. Pegawai Aparatur Sipil Negara yang selanjutnya disebut pegawai ASN adalah pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan digaji berdasarkan peraturan perundang-undangan.
2. Kementerian/Lembaga/Organisasi Perangkat Daerah/ Institusi lainnya, yang selanjutnya disebut K/L/D/I adalah instansi/institusi yang menggunakan Anggaran Pendapatan dan Belanja Negara.
3. Penyedia Barang/Jasa adalah badan usaha atau orang perseorangan yang menyediakan Barang/Pekerjaan Konstruksi/Jasa Konsultansi/Jasa Lainnya.
2019, No. 740
4. Pejabat Penyelesaian Kerugian Negara yang selanjutnya disingkat PPKN adalah Kepala Badan Nasional Penanggulangan Bencana yang memiliki kewenangan untuk menyelesaikan kerugian negara.
5. Bendahara Pengeluaran yang selanjutnya disingkat BP adalah orang yang ditunjuk untuk menerima, menyimpan, menyimpan, membayarkan, menatausahakan, dan mempertanggungjawabkan uang untuk keperluan belanja negara dalam rangka pelaksanaan Anggaran Pendapatan dan Belanja Negara pada kementerian/lembaga.
6. Bendahara Pengeluaran Pembantu yang selanjutnya disingkat BPP adalah orang yang ditunjuk untuk membantu BP untuk melaksanakan pembayaran kepada yang berhak guna kelancaran pelaksanaan kegiatan tertentu.
7. Tim Penyelesaian Kerugian Negara yang selanjutnya disingkat TPKN adalah tim yang bertugas memproses penyelesaian kerugian negara di lingkungan Badan Nasional Penanggulangan Bencana.
8. Majelis Pertimbangan Penyelesaian Kerugian Negara yang selanjutnya disebut Majelis adalah para pejabat/pegawai yang ditunjuk dan ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana untuk menyampaikan pertimbangan dan pendapat penyelesaian kerugian negara.
9. Kerugian Negara adalah kekurangan uang, surat berharga, dan barang yang nyata dan pasti jumlahnya sebagai akibat perbuatan melawan hukum baik sengaja maupun lalai.
10. Tuntutan Perbendaharaan adalah proses tuntutan yang dilakukan terhadap bendahara pengeluaran/ bendahara pengeluaran pembantu dengan tujuan untuk menuntut penggantian atas suatu kerugian yang diderita oleh negara sebagai akibat langsung atau pun tidak langsung dari suatu perbuatan melanggar hukum atau kelalaian dalam pelaksanaan tugas kewajibannya.
2019, No. 740 -4-
11. Tuntutan Ganti Kerugian adalah suatu proses tuntutan yang dilakukan terhadap pegawai aparatur sipil negara bukan bendahara dan/atau penyedia barang/jasa yang melaksanakan kerja untuk kepentingan Badan Nasional Penanggulangan Bencana dengan tujuan untuk menuntut penggantian atas suatu Kerugian Negara sebagai akibat langsung ataupun tidak langsung dari suatu perbuatan melanggar hukum atau kelalaian dalam pelaksanaan tugas kewajibannya.
12. Surat Keterangan Tanggung Jawab Mutlak yang selanjutnya disingkat SKTJM adalah surat keterangan yang menyatakan kesanggupan dan/atau pengakuan bahwa Kerugian Negara menjadi tanggung jawabnya dan bersedia mengganti Kerugian Negara dimaksud.
13. Surat Keputusan Pembebanan Penggantian Kerugian Sementara yang selanjutnya disebut SKP2KS adalah surat yang dibuat oleh Kepala Badan Nasional Penanggulangan Bencana dalam hal SKTJM tidak mungkin diperoleh.
14. Surat Keputusan Pembebanan Penggantian Kerugian yang selanjutnya disebut SKP2K adalah surat keputusan yang ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana yang mempunyai kekuatan hukum tetap tentang pembebanan penggantian Kerugian Negara terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain.
15. Surat Keputusan Pembebanan Sementara adalah surat keputusan yang dikeluarkan oleh Kepala Badan Nasional Penanggulangan Bencana untuk BP/BPP tentang pembebanan penggantian sementara atas Kerugian Negara sebagai dasar untuk melaksanakan sita jaminan.
16. Surat Keputusan Pembebanan adalah surat keputusan yang dikeluarkan oleh Badan Pemeriksa Keuangan yang mempunyai kekuatan hukum final tentang pembebanan penggantian Kerugian Negara terhadap bendahara.
17. Sita Jaminan adalah penyitaan yang dilakukan oleh pengadilan atas barang bergerak atau tidak bergerak 2019, No. 740 milik tergugat untuk menjamin adanya tuntutan hak dari pemohon sita.
18. Surat Keterangan Tanda Lunas yang selanjutnya disebut SKTL adalah surat keterangan yang ditandatangani oleh Kepala BNPB setelah Kerugian Negara dilunasi ke Kas Negara sesuai dengan jumlah dan jangka waktu yang tercantum dalam SKTJM, SKP2KS, atau SKP2K.
19. Tim Ad Hoc adalah tim yang dibentuk oleh pejabat eselon II di lingkungan Badan Nasional Penanggulangan Bencana untuk membantu TPKN dalam menyelesaikan Kerugian Negara.
20. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian setingkat menteri sesuai dengan ketentuan peraturan perundang-undangan.
21. Badan Penanggulangan Bencana Daerah, yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2526, 'Dalam Peraturan Badan ini, yang dimaksud dengan:
1. Pegawai Aparatur Sipil Negara yang selanjutnya disebut pegawai ASN adalah pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan digaji berdasarkan peraturan perundang-undangan.
2. Kementerian/Lembaga/Organisasi Perangkat Daerah/ Institusi lainnya, yang selanjutnya disebut K/L/D/I adalah instansi/institusi yang menggunakan Anggaran Pendapatan dan Belanja Negara.
3. Penyedia Barang/Jasa adalah badan usaha atau orang perseorangan yang menyediakan Barang/Pekerjaan Konstruksi/Jasa Konsultansi/Jasa Lainnya.
2019, No. 740
4. Pejabat Penyelesaian Kerugian Negara yang selanjutnya disingkat PPKN adalah Kepala Badan Nasional Penanggulangan Bencana yang memiliki kewenangan untuk menyelesaikan kerugian negara.
5. Bendahara Pengeluaran yang selanjutnya disingkat BP adalah orang yang ditunjuk untuk menerima, menyimpan, menyimpan, membayarkan, menatausahakan, dan mempertanggungjawabkan uang untuk keperluan belanja negara dalam rangka pelaksanaan Anggaran Pendapatan dan Belanja Negara pada kementerian/lembaga.
6. Bendahara Pengeluaran Pembantu yang selanjutnya disingkat BPP adalah orang yang ditunjuk untuk membantu BP untuk melaksanakan pembayaran kepada yang berhak guna kelancaran pelaksanaan kegiatan tertentu.
7. Tim Penyelesaian Kerugian Negara yang selanjutnya disingkat TPKN adalah tim yang bertugas memproses penyelesaian kerugian negara di lingkungan Badan Nasional Penanggulangan Bencana.
8. Majelis Pertimbangan Penyelesaian Kerugian Negara yang selanjutnya disebut Majelis adalah para pejabat/pegawai yang ditunjuk dan ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana untuk menyampaikan pertimbangan dan pendapat penyelesaian kerugian negara.
9. Kerugian Negara adalah kekurangan uang, surat berharga, dan barang yang nyata dan pasti jumlahnya sebagai akibat perbuatan melawan hukum baik sengaja maupun lalai.
10. Tuntutan Perbendaharaan adalah proses tuntutan yang dilakukan terhadap bendahara pengeluaran/ bendahara pengeluaran pembantu dengan tujuan untuk menuntut penggantian atas suatu kerugian yang diderita oleh negara sebagai akibat langsung atau pun tidak langsung dari suatu perbuatan melanggar hukum atau kelalaian dalam pelaksanaan tugas kewajibannya.
2019, No. 740 -4-
11. Tuntutan Ganti Kerugian adalah suatu proses tuntutan yang dilakukan terhadap pegawai aparatur sipil negara bukan bendahara dan/atau penyedia barang/jasa yang melaksanakan kerja untuk kepentingan Badan Nasional Penanggulangan Bencana dengan tujuan untuk menuntut penggantian atas suatu Kerugian Negara sebagai akibat langsung ataupun tidak langsung dari suatu perbuatan melanggar hukum atau kelalaian dalam pelaksanaan tugas kewajibannya.
12. Surat Keterangan Tanggung Jawab Mutlak yang selanjutnya disingkat SKTJM adalah surat keterangan yang menyatakan kesanggupan dan/atau pengakuan bahwa Kerugian Negara menjadi tanggung jawabnya dan bersedia mengganti Kerugian Negara dimaksud.
13. Surat Keputusan Pembebanan Penggantian Kerugian Sementara yang selanjutnya disebut SKP2KS adalah surat yang dibuat oleh Kepala Badan Nasional Penanggulangan Bencana dalam hal SKTJM tidak mungkin diperoleh.
14. Surat Keputusan Pembebanan Penggantian Kerugian yang selanjutnya disebut SKP2K adalah surat keputusan yang ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana yang mempunyai kekuatan hukum tetap tentang pembebanan penggantian Kerugian Negara terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain.
15. Surat Keputusan Pembebanan Sementara adalah surat keputusan yang dikeluarkan oleh Kepala Badan Nasional Penanggulangan Bencana untuk BP/BPP tentang pembebanan penggantian sementara atas Kerugian Negara sebagai dasar untuk melaksanakan sita jaminan.
16. Surat Keputusan Pembebanan adalah surat keputusan yang dikeluarkan oleh Badan Pemeriksa Keuangan yang mempunyai kekuatan hukum final tentang pembebanan penggantian Kerugian Negara terhadap bendahara.
17. Sita Jaminan adalah penyitaan yang dilakukan oleh pengadilan atas barang bergerak atau tidak bergerak 2019, No. 740 milik tergugat untuk menjamin adanya tuntutan hak dari pemohon sita.
18. Surat Keterangan Tanda Lunas yang selanjutnya disebut SKTL adalah surat keterangan yang ditandatangani oleh Kepala BNPB setelah Kerugian Negara dilunasi ke Kas Negara sesuai dengan jumlah dan jangka waktu yang tercantum dalam SKTJM, SKP2KS, atau SKP2K.
19. Tim Ad Hoc adalah tim yang dibentuk oleh pejabat eselon II di lingkungan Badan Nasional Penanggulangan Bencana untuk membantu TPKN dalam menyelesaikan Kerugian Negara.
20. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian setingkat menteri sesuai dengan ketentuan peraturan perundang-undangan.
21. Badan Penanggulangan Bencana Daerah, yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2527, 'perban-2-2019', 5, 'pasal', 'Pasal 2', 'BAB II TATA CARA PENYELESAIAN KERUGIAN NEGARA', 5, '(1) Penyelesaian Kerugian Negara meliputi:
a. Tuntutan Perbendaharaan; dan
b. Tuntutan Ganti Kerugian.
(2) Tuntutan perbendaharaan sebagaimana dimaksud pada ayat (1) huruf a berlaku bagi BP/BPP.
(3) Tuntutan Ganti Kerugian sebagaimana dimaksud pada ayat (1) huruf b berlaku bagi:
a. pegawai ASN di lingkungan BNPB;
b. pegawai ASN di lingkungan BPBD, K/L/D/I penerima anggaran dari DIPA BNPB;
c. penyedia barang/jasa yang melaksanakan kerja untuk kepentingan BNPB, BPBD dan K/L/D/I.
2019, No. 740 -6-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2527, '(1) Penyelesaian Kerugian Negara meliputi:
a. Tuntutan Perbendaharaan; dan
b. Tuntutan Ganti Kerugian.
(2) Tuntutan perbendaharaan sebagaimana dimaksud pada ayat (1) huruf a berlaku bagi BP/BPP.
(3) Tuntutan Ganti Kerugian sebagaimana dimaksud pada ayat (1) huruf b berlaku bagi:
a. pegawai ASN di lingkungan BNPB;
b. pegawai ASN di lingkungan BPBD, K/L/D/I penerima anggaran dari DIPA BNPB;
c. penyedia barang/jasa yang melaksanakan kerja untuk kepentingan BNPB, BPBD dan K/L/D/I.
2019, No. 740 -6-', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2528, 'perban-2-2019', 6, 'pasal', 'Pasal 3', 'BAB III SUMBER INFORMASI KERUGIAN NEGARA', 6, '(1) Penyelesaian Kerugian Negara dapat diselesaikan dengan cara:
a. penggantian secara tunai; dan
b. penggantian dengan cara mengangsur dengan menandatangani SKTJM disertai jaminan yang memadai.
(2) Penyelesaian Kerugian Negara sebagaimana dimaksud pada ayat (1) tidak dapat diganti dengan barang dan spesifikasi yang sama.
(3) Penggantian secara tunai sebagaimana dimaksud pada ayat (1) huruf a tidak memungkinkan, maka penggantian dilakukan secara angsuran maksimal 2 (dua) tahun dengan cara sebagai berikut:
a. BP/BPP melakukan pemotongan gaji, menyetorkannya ke rekening Kas Negara, dan menyampaikan bukti penyetorannya kepada Sekretaris Utama u.p. Kepala Biro Keuangan;
b. BP/BPP yang bersangkutan menyetorkan angsuran ke rekening Kas Negara dan menyampaikan bukti penyetorannya kepada Sekretaris Utama u.p. Kepala Biro Keuangan;
c. pemotongan gaji melalui KPPN dan menyampaikan fotokopi SPM/SP2D gaji yang tertera potongan pengembalian Kerugian Negara kepada Kepala Biro Keuangan;
d. dalam hal pegawai ASN memasuki masa pensiun, maka Sekretaris Utama menerbitkan surat pemberitahuan kepada cabang PT Taspen setempat dalam waktu paling lama 15 (lima belas) hari kerja setelah surat keputusan penghentian pembayaran dicantumkan bahwa yang bersangkutan masih mempunyai utang kepada negara; atau
e. dalam hal penggantian melewati batas waktu 2 (dua) tahun, maka TPKN wajib memperbarui SKTJM.
2019, No. 740
(4) Jaminan sebagaimana dimaksud pada ayat (1) huruf b disertai dengan kuasa untuk menjual barang yang dijadikan jaminan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2528, '(1) Penyelesaian Kerugian Negara dapat diselesaikan dengan cara:
a. penggantian secara tunai; dan
b. penggantian dengan cara mengangsur dengan menandatangani SKTJM disertai jaminan yang memadai.
(2) Penyelesaian Kerugian Negara sebagaimana dimaksud pada ayat (1) tidak dapat diganti dengan barang dan spesifikasi yang sama.
(3) Penggantian secara tunai sebagaimana dimaksud pada ayat (1) huruf a tidak memungkinkan, maka penggantian dilakukan secara angsuran maksimal 2 (dua) tahun dengan cara sebagai berikut:
a. BP/BPP melakukan pemotongan gaji, menyetorkannya ke rekening Kas Negara, dan menyampaikan bukti penyetorannya kepada Sekretaris Utama u.p. Kepala Biro Keuangan;
b. BP/BPP yang bersangkutan menyetorkan angsuran ke rekening Kas Negara dan menyampaikan bukti penyetorannya kepada Sekretaris Utama u.p. Kepala Biro Keuangan;
c. pemotongan gaji melalui KPPN dan menyampaikan fotokopi SPM/SP2D gaji yang tertera potongan pengembalian Kerugian Negara kepada Kepala Biro Keuangan;
d. dalam hal pegawai ASN memasuki masa pensiun, maka Sekretaris Utama menerbitkan surat pemberitahuan kepada cabang PT Taspen setempat dalam waktu paling lama 15 (lima belas) hari kerja setelah surat keputusan penghentian pembayaran dicantumkan bahwa yang bersangkutan masih mempunyai utang kepada negara; atau
e. dalam hal penggantian melewati batas waktu 2 (dua) tahun, maka TPKN wajib memperbarui SKTJM.
2019, No. 740
(4) Jaminan sebagaimana dimaksud pada ayat (1) huruf b disertai dengan kuasa untuk menjual barang yang dijadikan jaminan.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2529, 'perban-2-2019', 7, 'pasal', 'Pasal 4', 'BAB III SUMBER INFORMASI KERUGIAN NEGARA', 7, '(1) Informasi terjadinya Kerugian Negara bersumber dari:
a. hasil pengawasan yang dilaksanakan oleh atasan langsung;
b. hasil pengawasan Inspektorat Utama;
c. pemeriksaan Badan Pemeriksa Keuangan;
d. laporan tertulis yang bersangkutan;
e. informasi tertulis dari masyarakat secara bertanggung jawab;
f. perhitungan ex officio; dan/atau
g. pelapor secara tertulis.
(2) Perhitungan ex officio sebagaimana dimaksud pada ayat
(1) huruf f dilakukan oleh pejabat yang ditetapkan atas uang, surat berharga, dan/atau barang milik negara/daerah yang menjadi tanggung jawab pegawai negeri bukan bendahara atau pejabat lain yang berada dalam pengampuan, melarikan diri, atau meninggal dunia.
(3) Informasi sebagaimana dimaksud pada ayat (1) dijadikan sebagai dasar bagi pimpinan unit kerja dalam melakukan tindak lanjut ganti Kerugian Negara dan wajib dikelola oleh setiap pimpinan unit kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2529, '(1) Informasi terjadinya Kerugian Negara bersumber dari:
a. hasil pengawasan yang dilaksanakan oleh atasan langsung;
b. hasil pengawasan Inspektorat Utama;
c. pemeriksaan Badan Pemeriksa Keuangan;
d. laporan tertulis yang bersangkutan;
e. informasi tertulis dari masyarakat secara bertanggung jawab;
f. perhitungan ex officio; dan/atau
g. pelapor secara tertulis.
(2) Perhitungan ex officio sebagaimana dimaksud pada ayat
(1) huruf f dilakukan oleh pejabat yang ditetapkan atas uang, surat berharga, dan/atau barang milik negara/daerah yang menjadi tanggung jawab pegawai negeri bukan bendahara atau pejabat lain yang berada dalam pengampuan, melarikan diri, atau meninggal dunia.
(3) Informasi sebagaimana dimaksud pada ayat (1) dijadikan sebagai dasar bagi pimpinan unit kerja dalam melakukan tindak lanjut ganti Kerugian Negara dan wajib dikelola oleh setiap pimpinan unit kerja.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2530, 'perban-2-2019', 8, 'pasal', 'Pasal 5', 'BAB IV TIM PENYELESAIAN KERUGIAN NEGARA', 7, '(1) Pimpinan unit kerja wajib segera meneliti apakah informasi sebagaimana dimaksud dalam Pasal 4 berhubungan dengan kekayaan negara yang menjadi tanggung jawabnya.
2019, No. 740 -8-
(2) Informasi sebagaimana dimaksud pada ayat (1), pimpinan unit kerja wajib meneliti kembali hal-hal tersebut untuk ditindaklanjuti.
(3) Dalam melakukan penelitian sebagaimana dimaksud pada ayat (2), pimpinan unit kerja dapat membentuk Tim Ad Hoc untuk membantu TPKN dalam menyelesaikan Kerugian Negara.
(4) Keanggotaan Tim Ad Hoc sebagaimana dimaksud pada ayat (3) terdiri dari tiga orang yang berasal dari unsur:
a. pejabat administrator;
b. pejabat pengawas; dan
c. pelaksana.
(5) Penelitian yang dilakukan oleh Tim Ad Hoc dituangkan dalam laporan hasil pemeriksaan yang meliputi:
a. jumlah Kerugian Negara;
b. pegawai ASN dan penyedia barang/jasa yang bertanggung jawab atas terjadinya Kerugian Negara; dan
c. bukti dokumen.
(6) Pimpinan unit kerja melaporkan pelaksanaan tugas Tim Ad Hoc sebagaimana dimaksud pada ayat (3) kepada Kepala BNPB dengan tembusan kepada TPKN untuk diproses lebih lanjut.
(7) Kepala BNPB segera menugaskan TPKN untuk menindaklanjuti setiap kasus Kerugian Negara dalam waktu paling lama 7 (tujuh) hari kerja sejak menerima laporan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2530, '(1) Pimpinan unit kerja wajib segera meneliti apakah informasi sebagaimana dimaksud dalam Pasal 4 berhubungan dengan kekayaan negara yang menjadi tanggung jawabnya.
2019, No. 740 -8-
(2) Informasi sebagaimana dimaksud pada ayat (1), pimpinan unit kerja wajib meneliti kembali hal-hal tersebut untuk ditindaklanjuti.
(3) Dalam melakukan penelitian sebagaimana dimaksud pada ayat (2), pimpinan unit kerja dapat membentuk Tim Ad Hoc untuk membantu TPKN dalam menyelesaikan Kerugian Negara.
(4) Keanggotaan Tim Ad Hoc sebagaimana dimaksud pada ayat (3) terdiri dari tiga orang yang berasal dari unsur:
a. pejabat administrator;
b. pejabat pengawas; dan
c. pelaksana.
(5) Penelitian yang dilakukan oleh Tim Ad Hoc dituangkan dalam laporan hasil pemeriksaan yang meliputi:
a. jumlah Kerugian Negara;
b. pegawai ASN dan penyedia barang/jasa yang bertanggung jawab atas terjadinya Kerugian Negara; dan
c. bukti dokumen.
(6) Pimpinan unit kerja melaporkan pelaksanaan tugas Tim Ad Hoc sebagaimana dimaksud pada ayat (3) kepada Kepala BNPB dengan tembusan kepada TPKN untuk diproses lebih lanjut.
(7) Kepala BNPB segera menugaskan TPKN untuk menindaklanjuti setiap kasus Kerugian Negara dalam waktu paling lama 7 (tujuh) hari kerja sejak menerima laporan.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2531, 'perban-2-2019', 9, 'pasal', 'Pasal 6', 'BAB V MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP BENDAHARA PENGELUARAN/BENDAHARA PENGELUARAN PEMBANTU; Bagian Kesatu Verifikasi dan Penilaian Kerugian Negara', 8, '(1) Dalam menyelesaikan Kerugian Negara, Kepala BNPB membentuk TPKN.
(2) TPKN sebagaimana dimaksud pada ayat (1) terdiri atas:
a. sekretaris utama sebagai ketua;
b. inspektur utama sebagai wakil ketua;
2019, No. 740
c. kepala biro keuangan sebagai sekretaris;
d. inspektur sebagai wakil sekretaris; dan
e. anggota dari unit kerja terdiri atas inspektorat utama, biro keuangan, biro hukum dan kerja sama, biro umum, dan bidang lain terkait.
(3) TPKN melakukan pemeriksaan Kerugian Negara dalam waktu paling lama 7 (tujuh) hari kerja setelah dibentuk.
(4) TPKN memiliki tugas dan wewenang:
a. menyusun kronologi terjadinya Kerugian Negara;
b. menginventarisasi kasus Kerugian Negara;
c. menghitung jumlah Kerugian Negara;
d. mengumpulkan dan melakukan verifikasi bukti-bukti pendukung terjadinya Kerugian Negara;
e. menginventarisasi harta kekayaan milik bendahara, pegawai ASN bukan bendahara, atau pejabat lain yang dapat dijadikan sebagai jaminan penyelesaian Kerugian Negara;
f. menyelesaikan Kerugian Negara melalui SKTJM;
g. menatausahakan penyelesaian Kerugian Negara; dan
h. menyampaikan laporan perkembangan penyelesaian Kerugian Negara kepada pimpinan instansi.
(5) Dalam melaksanakan tugasnya, TPKN dibantu oleh Sekretariat TPKN.
2019, No. 740 -10-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2531, '(1) Dalam menyelesaikan Kerugian Negara, Kepala BNPB membentuk TPKN.
(2) TPKN sebagaimana dimaksud pada ayat (1) terdiri atas:
a. sekretaris utama sebagai ketua;
b. inspektur utama sebagai wakil ketua;
2019, No. 740
c. kepala biro keuangan sebagai sekretaris;
d. inspektur sebagai wakil sekretaris; dan
e. anggota dari unit kerja terdiri atas inspektorat utama, biro keuangan, biro hukum dan kerja sama, biro umum, dan bidang lain terkait.
(3) TPKN melakukan pemeriksaan Kerugian Negara dalam waktu paling lama 7 (tujuh) hari kerja setelah dibentuk.
(4) TPKN memiliki tugas dan wewenang:
a. menyusun kronologi terjadinya Kerugian Negara;
b. menginventarisasi kasus Kerugian Negara;
c. menghitung jumlah Kerugian Negara;
d. mengumpulkan dan melakukan verifikasi bukti-bukti pendukung terjadinya Kerugian Negara;
e. menginventarisasi harta kekayaan milik bendahara, pegawai ASN bukan bendahara, atau pejabat lain yang dapat dijadikan sebagai jaminan penyelesaian Kerugian Negara;
f. menyelesaikan Kerugian Negara melalui SKTJM;
g. menatausahakan penyelesaian Kerugian Negara; dan
h. menyampaikan laporan perkembangan penyelesaian Kerugian Negara kepada pimpinan instansi.
(5) Dalam melaksanakan tugasnya, TPKN dibantu oleh Sekretariat TPKN.
2019, No. 740 -10-', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2532, 'perban-2-2019', 10, 'pasal', 'Pasal 7', 'BAB V MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP BENDAHARA PENGELUARAN/BENDAHARA PENGELUARAN PEMBANTU; Bagian Kesatu Verifikasi dan Penilaian Kerugian Negara', 10, 'Dalam hal berdasarkan pemeriksaan atas Kerugian Negara BP/BPP diduga menimbulkan Kerugian Negara, Kepala BNPB selaku Pengguna Anggaran BNPB membebastugaskan sementara BP/BPP dari jabatannya dan menetapkan penggantinya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2532, 'Dalam hal berdasarkan pemeriksaan atas Kerugian Negara BP/BPP diduga menimbulkan Kerugian Negara, Kepala BNPB selaku Pengguna Anggaran BNPB membebastugaskan sementara BP/BPP dari jabatannya dan menetapkan penggantinya.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2533, 'perban-2-2019', 11, 'pasal', 'Pasal 8', 'BAB V MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP BENDAHARA PENGELUARAN/BENDAHARA PENGELUARAN PEMBANTU; Bagian Kedua Penyelesaian Kerugian Negara Melalui Penerbitan Surat', 10, '(1) TPKN berdasarkan penugasan dari Sekretaris Utama menindaklanjuti dengan mengumpulkan dokumen dan menyelesaikan verifikasi dalam waktu paling lama 30 (tiga puluh) hari kerja sejak menerima penugasan dari Sekretaris Utama.
(2) TPKN menyampaikan laporan hasil verifikasi Kerugian Negara sebagaimana dimaksud pada ayat (1) kepada Kepala BNPB sesuai dengan format sebagaimana tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(3) Kepala BNPB menyampaikan laporan hasil verifikasi Kerugian Negara sebagaimana dimaksud pada ayat (2) kepada Badan Pemeriksa Keuangan dalam waktu paling lama 7 (tujuh) hari kerja sejak menerima laporan dari TPKN.
(4) TPKN mengumpulkan dan melakukan verifikasi dokumen sebagai berikut:
a. surat keputusan pengangkatan sebagai bendahara atau sebagai pejabat yang melaksanakan fungsi kebendaharaan;
b. berita acara pemeriksaan kas/barang;
2019, No. 740
c. register penutupan buku kas/barang;
d. surat keterangan tentang sisa uang yang belum dipertanggungjawabkan dari Pengguna Anggaran/ Kuasa Pengguna Anggaran;
e. surat keterangan bank tentang saldo kas di bank bersangkutan;
f. fotokopi/rekaman buku kas umum bulan yang bersangkutan yang memuat adanya kekurangan kas;
g. surat tanda lapor dari kepolisian dalam hal Kerugian Negara mengandung indikasi tindak pidana;
h. berita acara pemeriksaan tempat kejadian perkara dari kepolisian dalam hal Kerugian Negara terjadi karena pencurian atau perampokan; dan
i. surat keterangan ahli waris dari kelurahan atau pengadilan.
(5) TPKN mencatat Kerugian Negara dalam Daftar Kerugian Negara sesuai dengan format sebagaimana tercantum dalam Lampiran II yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(6) Badan Pemeriksa Keuangan melakukan pemeriksaan atas Laporan Kerugian Negara berdasarkan Laporan Hasil Verifikasi Kerugian Negara.
Keterangan Tanggung Jawab Mutlak');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2533, '(1) TPKN berdasarkan penugasan dari Sekretaris Utama menindaklanjuti dengan mengumpulkan dokumen dan menyelesaikan verifikasi dalam waktu paling lama 30 (tiga puluh) hari kerja sejak menerima penugasan dari Sekretaris Utama.
(2) TPKN menyampaikan laporan hasil verifikasi Kerugian Negara sebagaimana dimaksud pada ayat (1) kepada Kepala BNPB sesuai dengan format sebagaimana tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(3) Kepala BNPB menyampaikan laporan hasil verifikasi Kerugian Negara sebagaimana dimaksud pada ayat (2) kepada Badan Pemeriksa Keuangan dalam waktu paling lama 7 (tujuh) hari kerja sejak menerima laporan dari TPKN.
(4) TPKN mengumpulkan dan melakukan verifikasi dokumen sebagai berikut:
a. surat keputusan pengangkatan sebagai bendahara atau sebagai pejabat yang melaksanakan fungsi kebendaharaan;
b. berita acara pemeriksaan kas/barang;
2019, No. 740
c. register penutupan buku kas/barang;
d. surat keterangan tentang sisa uang yang belum dipertanggungjawabkan dari Pengguna Anggaran/ Kuasa Pengguna Anggaran;
e. surat keterangan bank tentang saldo kas di bank bersangkutan;
f. fotokopi/rekaman buku kas umum bulan yang bersangkutan yang memuat adanya kekurangan kas;
g. surat tanda lapor dari kepolisian dalam hal Kerugian Negara mengandung indikasi tindak pidana;
h. berita acara pemeriksaan tempat kejadian perkara dari kepolisian dalam hal Kerugian Negara terjadi karena pencurian atau perampokan; dan
i. surat keterangan ahli waris dari kelurahan atau pengadilan.
(5) TPKN mencatat Kerugian Negara dalam Daftar Kerugian Negara sesuai dengan format sebagaimana tercantum dalam Lampiran II yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(6) Badan Pemeriksa Keuangan melakukan pemeriksaan atas Laporan Kerugian Negara berdasarkan Laporan Hasil Verifikasi Kerugian Negara.
Keterangan Tanggung Jawab Mutlak', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2534, 'perban-2-2019', 12, 'pasal', 'Pasal 9', 'BAB V MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP BENDAHARA PENGELUARAN/BENDAHARA PENGELUARAN PEMBANTU; Bagian Kedua Penyelesaian Kerugian Negara Melalui Penerbitan Surat', 11, '(1) Dalam hal hasil pemeriksaan Badan Pemeriksa Keuangan menunjukkan telah terjadi Kerugian Negara dengan terbukti adanya perbuatan melawan hukum baik sengaja maupun lalai, Badan Pemeriksa Keuangan mengeluarkan surat kepada BNPB untuk memproses penyelesaian Kerugian Negara melalui SKTJM.
(2) Dalam hal hasil pemeriksaan Badan Pemeriksa Keuangan menunjukkan tidak terdapat perbuatan melawan hukum 2019, No. 740 -12- baik sengaja maupun lalai, Badan Pemeriksa Keuangan mengeluarkan surat kepada Kepala BNPB untuk menghapus kasus Kerugian Negara dan mengeluarkannya dari Daftar Kerugian Negara.
(3) TPKN meminta BP/BPP untuk membuat dan menandatangani SKTJM.
(4) Pembuatan dan penandatanganan SKTJM oleh BP/BPP sebagaimana dimaksud pada ayat (3) dilakukan dalam waktu paling lama 7 (tujuh) hari kerja setelah menerima surat dari Badan Pemeriksa Keuangan.
(5) Bentuk dan isi SKTJM sesuai dengan format sebagaimana tercantum dalam Lampiran III yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2534, '(1) Dalam hal hasil pemeriksaan Badan Pemeriksa Keuangan menunjukkan telah terjadi Kerugian Negara dengan terbukti adanya perbuatan melawan hukum baik sengaja maupun lalai, Badan Pemeriksa Keuangan mengeluarkan surat kepada BNPB untuk memproses penyelesaian Kerugian Negara melalui SKTJM.
(2) Dalam hal hasil pemeriksaan Badan Pemeriksa Keuangan menunjukkan tidak terdapat perbuatan melawan hukum 2019, No. 740 -12- baik sengaja maupun lalai, Badan Pemeriksa Keuangan mengeluarkan surat kepada Kepala BNPB untuk menghapus kasus Kerugian Negara dan mengeluarkannya dari Daftar Kerugian Negara.
(3) TPKN meminta BP/BPP untuk membuat dan menandatangani SKTJM.
(4) Pembuatan dan penandatanganan SKTJM oleh BP/BPP sebagaimana dimaksud pada ayat (3) dilakukan dalam waktu paling lama 7 (tujuh) hari kerja setelah menerima surat dari Badan Pemeriksa Keuangan.
(5) Bentuk dan isi SKTJM sesuai dengan format sebagaimana tercantum dalam Lampiran III yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2535, 'perban-2-2019', 13, 'pasal', 'Pasal 10', 'BAB V MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP BENDAHARA PENGELUARAN/BENDAHARA PENGELUARAN PEMBANTU; Bagian Kedua Penyelesaian Kerugian Negara Melalui Penerbitan Surat', 12, 'Dalam hal kasus Kerugian Negara diperoleh berdasarkan pemeriksaan yang dilakukan oleh aparat pengawasan fungsional yang sedang melakukan tugasnya pada BNPB dan dalam proses pemeriksaan tersebut BP/BPP bersedia mengganti Kerugian Negara, BP/BPP membuat dan menandatangani SKTJM di hadapan pemeriksa yang bersangkutan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2535, 'Dalam hal kasus Kerugian Negara diperoleh berdasarkan pemeriksaan yang dilakukan oleh aparat pengawasan fungsional yang sedang melakukan tugasnya pada BNPB dan dalam proses pemeriksaan tersebut BP/BPP bersedia mengganti Kerugian Negara, BP/BPP membuat dan menandatangani SKTJM di hadapan pemeriksa yang bersangkutan.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2536, 'perban-2-2019', 14, 'pasal', 'Pasal 11', 'BAB V MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP BENDAHARA PENGELUARAN/BENDAHARA PENGELUARAN PEMBANTU; Bagian Kedua Penyelesaian Kerugian Negara Melalui Penerbitan Surat', 12, '(1) Dalam hal BP/BPP menandatangani SKTJM, yang bersangkutan wajib menyerahkan jaminan senilai Kerugian Negara kepada TPKN dalam bentuk dokumen yang meliputi:
a. bukti kepemilikan barang dan/atau kekayaan lain atas nama BP/BPP; dan
b. surat kuasa menjual barang dan/atau kekayaan lain yang dijaminkan oleh BP/BPP.
(2) SKTJM yang telah ditandatangani oleh BP/BPP sebagaimana dimaksud pada ayat (1) huruf a dan huruf b tidak dapat ditarik kembali.
2019, No. 740
(3) Surat kuasa dari BP/BPP sebagaimana dimaksud pada ayat (1) huruf b diberlakukan setelah Badan Pemeriksa Keuangan mengeluarkan Surat Keputusan Pembebanan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2536, '(1) Dalam hal BP/BPP menandatangani SKTJM, yang bersangkutan wajib menyerahkan jaminan senilai Kerugian Negara kepada TPKN dalam bentuk dokumen yang meliputi:
a. bukti kepemilikan barang dan/atau kekayaan lain atas nama BP/BPP; dan
b. surat kuasa menjual barang dan/atau kekayaan lain yang dijaminkan oleh BP/BPP.
(2) SKTJM yang telah ditandatangani oleh BP/BPP sebagaimana dimaksud pada ayat (1) huruf a dan huruf b tidak dapat ditarik kembali.
2019, No. 740
(3) Surat kuasa dari BP/BPP sebagaimana dimaksud pada ayat (1) huruf b diberlakukan setelah Badan Pemeriksa Keuangan mengeluarkan Surat Keputusan Pembebanan.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2537, 'perban-2-2019', 15, 'pasal', 'Pasal 12', 'BAB V MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP BENDAHARA PENGELUARAN/BENDAHARA PENGELUARAN PEMBANTU; Bagian Ketiga Penyelesaian Kerugian Negara Melalui Penerbitan Surat', 13, 'Penggantian Kerugian Negara oleh BP/BPP dilakukan secara tunai dalam waktu paling lama 40 (empat puluh) hari kerja sejak penandatanganan SKTJM.
Keputusan Pembebanan Kerugian Negara Sementara');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2537, 'Penggantian Kerugian Negara oleh BP/BPP dilakukan secara tunai dalam waktu paling lama 40 (empat puluh) hari kerja sejak penandatanganan SKTJM.
Keputusan Pembebanan Kerugian Negara Sementara', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2538, 'perban-2-2019', 16, 'pasal', 'Pasal 13', 'BAB V MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP BENDAHARA PENGELUARAN/BENDAHARA PENGELUARAN PEMBANTU; Bagian Ketiga Penyelesaian Kerugian Negara Melalui Penerbitan Surat', 13, '(1) Kepala BNPB menetapkan pembebanan sementara kepada BP/BPP, jika BP/BPP tidak bersedia menandatangani SKTJM atau tidak dapat menjamin pengembalian Kerugian Negara.
(2) Pembebanan sementara sebagaimana dimaksud pada ayat (1) ditetapkan dalam waktu paling lama 7 (tujuh) hari kerja sejak BP/BPP tidak bersedia menandatangani SKTJM.
(3) Kepala BNPB menyampaikan SKP2KS sebagaimana dimaksud pada ayat (1) kepada Badan Pemeriksa Keuangan sesuai dengan format sebagaimana tercantum dalam Lampiran IV yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2538, '(1) Kepala BNPB menetapkan pembebanan sementara kepada BP/BPP, jika BP/BPP tidak bersedia menandatangani SKTJM atau tidak dapat menjamin pengembalian Kerugian Negara.
(2) Pembebanan sementara sebagaimana dimaksud pada ayat (1) ditetapkan dalam waktu paling lama 7 (tujuh) hari kerja sejak BP/BPP tidak bersedia menandatangani SKTJM.
(3) Kepala BNPB menyampaikan SKP2KS sebagaimana dimaksud pada ayat (1) kepada Badan Pemeriksa Keuangan sesuai dengan format sebagaimana tercantum dalam Lampiran IV yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2539, 'perban-2-2019', 17, 'pasal', 'Pasal 14', 'BAB V MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP BENDAHARA PENGELUARAN/BENDAHARA PENGELUARAN PEMBANTU; Bagian Ketiga Penyelesaian Kerugian Negara Melalui Penerbitan Surat', 13, '(1) Pelaksanaan sita jaminan diajukan oleh Kepala BNPB kepada instansi yang berwenang melakukan penyitaan dalam waktu paling lama 7 (tujuh) hari kerja setelah diterbitkannya Surat Keputusan Pembebanan Sementara.
(2) Pelaksanaan sita jaminan dilakukan sesuai dengan ketentuan peraturan perundangan-undangan.
2019, No. 740 -14-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2539, '(1) Pelaksanaan sita jaminan diajukan oleh Kepala BNPB kepada instansi yang berwenang melakukan penyitaan dalam waktu paling lama 7 (tujuh) hari kerja setelah diterbitkannya Surat Keputusan Pembebanan Sementara.
(2) Pelaksanaan sita jaminan dilakukan sesuai dengan ketentuan peraturan perundangan-undangan.
2019, No. 740 -14-', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2540, 'perban-2-2019', 18, 'pasal', 'Pasal 15', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Kesatu Penyelesaian Kerugian Negara Melalui Penerbitan Surat', 14, '(1) Badan Pemeriksa Keuangan mengeluarkan Surat Keputusan Pembebanan apabila:
a. jangka waktu untuk mengajukan keberatan telah terlampaui dan bendahara tidak mengajukan keberatan;
b. bendahara mengajukan keberatan tetapi ditolak; atau
c. telah melampaui jangka waktu paling lama 40 (empat puluh) hari sejak ditandatangani SKTJM namun Kerugian Negara belum diganti sepenuhnya.
(2) Surat Keputusan Pembebanan disampaikan kepada bendahara melalui atasan langsung bendahara atau kepala kantor/satuan kerja bendahara dengan tembusan kepada pimpinan instansi yang bersangkutan dengan tanda terima dari bendahara.
(3) Surat Keputusan Pembebanan sebagaimana dimaksud dalam ayat (1) telah mempunyai kekuatan hukum yang bersifat final.
Keterangan Tanggung Jawab Mutlak');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2540, '(1) Badan Pemeriksa Keuangan mengeluarkan Surat Keputusan Pembebanan apabila:
a. jangka waktu untuk mengajukan keberatan telah terlampaui dan bendahara tidak mengajukan keberatan;
b. bendahara mengajukan keberatan tetapi ditolak; atau
c. telah melampaui jangka waktu paling lama 40 (empat puluh) hari sejak ditandatangani SKTJM namun Kerugian Negara belum diganti sepenuhnya.
(2) Surat Keputusan Pembebanan disampaikan kepada bendahara melalui atasan langsung bendahara atau kepala kantor/satuan kerja bendahara dengan tembusan kepada pimpinan instansi yang bersangkutan dengan tanda terima dari bendahara.
(3) Surat Keputusan Pembebanan sebagaimana dimaksud dalam ayat (1) telah mempunyai kekuatan hukum yang bersifat final.
Keterangan Tanggung Jawab Mutlak', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2541, 'perban-2-2019', 19, 'pasal', 'Pasal 16', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Kesatu Penyelesaian Kerugian Negara Melalui Penerbitan Surat', 14, '(1) TPKN dalam menghitung Kerugian Negara, dapat mengikutsertakan anggota tim dari Inspektorat Utama.
(2) TPKN sebagaimana dimaksud pada ayat (1) menyampaikan laporan hasil pemeriksaan kepada PPKN.
(3) Dalam hal terbukti ada perbuatan melawan hukum baik sengaja maupun lalai, Kepala BNPB menugaskan TPKN untuk penyelesaian kerugian negara melalui SKTJM.
2019, No. 740
(4) Bentuk dan isi SKTJM sesuai dengan format sebagaimana tercantum dalam Lampiran V yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2541, '(1) TPKN dalam menghitung Kerugian Negara, dapat mengikutsertakan anggota tim dari Inspektorat Utama.
(2) TPKN sebagaimana dimaksud pada ayat (1) menyampaikan laporan hasil pemeriksaan kepada PPKN.
(3) Dalam hal terbukti ada perbuatan melawan hukum baik sengaja maupun lalai, Kepala BNPB menugaskan TPKN untuk penyelesaian kerugian negara melalui SKTJM.
2019, No. 740
(4) Bentuk dan isi SKTJM sesuai dengan format sebagaimana tercantum dalam Lampiran V yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2542, 'perban-2-2019', 20, 'pasal', 'Pasal 17', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Kedua Penyelesaian Kerugian Negara Melalui Penerbitan Surat', 15, '(1) Dalam hal Kerugian Negara sebagai akibat perbuatan melanggar hukum, pegawai ASN bukan bendahara dan/atau penyedia barang/jasa wajib mengganti Kerugian Negara dalam waktu paling lama 90 (sembilan puluh) hari kalender sejak SKTJM ditandatangani dan menyampaikan bukti penyetorannya ke TPKN dan biro keuangan.
(2) Dalam hal Kerugian Negara sebagai akibat kelalaian, pegawai ASN bukan bendahara dan/atau penyedia barang/jasa wajib mengganti kerugian negara dalam waktu paling lama 24 (dua puluh empat) bulan sejak SKTJM ditandatangani dan menyampaikan bukti penyetorannya per bulan dikirimkan kepada TPKN dan biro keuangan.
(3) PPKN wajib melakukan pemantauan atas ketaatan pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dalam melakukan pembayaran sesuai dengan SKTJM.
(4) Dalam hal pegawai ASN bukan bendahara dan/atau penyedia barang/jasa melalaikan kewajiban pembayaran sesuai dengan SKTJM, PPKN menyampaikan teguran tertulis.
(5) Bentuk dan isi Surat Teguran sesuai dengan format sebagaimana tercantum dalam Lampiran VI yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(6) Dalam hal pegawai ASN bukan bendahara dan/atau penyedia barang/jasa tidak mengganti kerugian dalam jangka waktu yang telah ditentukan, pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dimaksud dinyatakan wanprestasi.
2019, No. 740 -16- Keputusan Pembebanan Penggantian Kerugian Sementara');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2542, '(1) Dalam hal Kerugian Negara sebagai akibat perbuatan melanggar hukum, pegawai ASN bukan bendahara dan/atau penyedia barang/jasa wajib mengganti Kerugian Negara dalam waktu paling lama 90 (sembilan puluh) hari kalender sejak SKTJM ditandatangani dan menyampaikan bukti penyetorannya ke TPKN dan biro keuangan.
(2) Dalam hal Kerugian Negara sebagai akibat kelalaian, pegawai ASN bukan bendahara dan/atau penyedia barang/jasa wajib mengganti kerugian negara dalam waktu paling lama 24 (dua puluh empat) bulan sejak SKTJM ditandatangani dan menyampaikan bukti penyetorannya per bulan dikirimkan kepada TPKN dan biro keuangan.
(3) PPKN wajib melakukan pemantauan atas ketaatan pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dalam melakukan pembayaran sesuai dengan SKTJM.
(4) Dalam hal pegawai ASN bukan bendahara dan/atau penyedia barang/jasa melalaikan kewajiban pembayaran sesuai dengan SKTJM, PPKN menyampaikan teguran tertulis.
(5) Bentuk dan isi Surat Teguran sesuai dengan format sebagaimana tercantum dalam Lampiran VI yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(6) Dalam hal pegawai ASN bukan bendahara dan/atau penyedia barang/jasa tidak mengganti kerugian dalam jangka waktu yang telah ditentukan, pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dimaksud dinyatakan wanprestasi.
2019, No. 740 -16- Keputusan Pembebanan Penggantian Kerugian Sementara', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2543, 'perban-2-2019', 21, 'pasal', 'Pasal 18', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Kedua Penyelesaian Kerugian Negara Melalui Penerbitan Surat', 16, '(1) SKTJM yang belum ditindaklanjuti dan/atau tidak dapat menjamin pengembalian Kerugian Negara, TPKN merekomendasikan kepada Kepala BNPB untuk menerbitkan SKP2KS kepada yang bersangkutan dengan tembusan kepada pimpinan unit kerja terkait sesuai dengan format sebagaimana tercantum dalam Lampiran VII yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(2) Kepala BNPB menerbitkan SKP2KS dalam waktu paling lama 7 (tujuh) hari kerja setelah menerima laporan dari TPKN.
(3) PPKN menyampaikan SKP2KS kepada pegawai ASN bukan bendahara dan/atau penyedia barang/jasa.
(4) Pegawai ASN bukan bendahara dan/atau penyedia barang/jasa yang diduga menyebabkan Kerugian Negara, dapat mengajukan keberatan pembelaan secara tertulis kepada Kepala BNPB dengan tembusan kepada TPKN dalam waktu paling lama 14 (empat belas) hari kerja sejak diterimanya SKP2KS dengan disertai bukti pendukung.
(5) Penggantian Kerugian Negara berdasarkan penerbitan SKP2KS dibayarkan secara tunai dalam waktu paling lama 90 (sembilan puluh) hari sejak diterbitkannya SKP2KS.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2543, '(1) SKTJM yang belum ditindaklanjuti dan/atau tidak dapat menjamin pengembalian Kerugian Negara, TPKN merekomendasikan kepada Kepala BNPB untuk menerbitkan SKP2KS kepada yang bersangkutan dengan tembusan kepada pimpinan unit kerja terkait sesuai dengan format sebagaimana tercantum dalam Lampiran VII yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(2) Kepala BNPB menerbitkan SKP2KS dalam waktu paling lama 7 (tujuh) hari kerja setelah menerima laporan dari TPKN.
(3) PPKN menyampaikan SKP2KS kepada pegawai ASN bukan bendahara dan/atau penyedia barang/jasa.
(4) Pegawai ASN bukan bendahara dan/atau penyedia barang/jasa yang diduga menyebabkan Kerugian Negara, dapat mengajukan keberatan pembelaan secara tertulis kepada Kepala BNPB dengan tembusan kepada TPKN dalam waktu paling lama 14 (empat belas) hari kerja sejak diterimanya SKP2KS dengan disertai bukti pendukung.
(5) Penggantian Kerugian Negara berdasarkan penerbitan SKP2KS dibayarkan secara tunai dalam waktu paling lama 90 (sembilan puluh) hari sejak diterbitkannya SKP2KS.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2544, 'perban-2-2019', 22, 'pasal', 'Pasal 19', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Ketiga Penyelesaian Kerugian Negara Melalui Majelis', 16, '(1) SKP2KS mempunyai kekuatan hukum untuk pelaksanaan sita jaminan.
(2) Pelaksanaan sita jaminan dilakukan oleh panitia urusan piutang negara.
(3) Pihak pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dapat menerima atau mengajukan keberatan 2019, No. 740 SKP2KS dalam waktu paling lama 14 (empat belas) hari kerja sejak diterimanya SKP2KS.
(4) Keberatan disampaikan secara tertulis kepada PPKN dengan disertai bukti.
(5) Pengajuan keberatan tidak menunda kewajiban pihak yang merugikan/pengampu/yang memperoleh hak/ ahli waris untuk mengganti Kerugian Negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2544, '(1) SKP2KS mempunyai kekuatan hukum untuk pelaksanaan sita jaminan.
(2) Pelaksanaan sita jaminan dilakukan oleh panitia urusan piutang negara.
(3) Pihak pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dapat menerima atau mengajukan keberatan 2019, No. 740 SKP2KS dalam waktu paling lama 14 (empat belas) hari kerja sejak diterimanya SKP2KS.
(4) Keberatan disampaikan secara tertulis kepada PPKN dengan disertai bukti.
(5) Pengajuan keberatan tidak menunda kewajiban pihak yang merugikan/pengampu/yang memperoleh hak/ ahli waris untuk mengganti Kerugian Negara.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2545, 'perban-2-2019', 23, 'pasal', 'Pasal 20', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Ketiga Penyelesaian Kerugian Negara Melalui Majelis', 17, '(1) Dalam rangka penyelesaian Kerugian Negara, PPKN membentuk Majelis.
(2) Jumlah anggota Majelis terdiri dari 3 (tiga) orang atau paling banyak 5 (lima) orang.
(3) Anggota Majelis yang dibentuk oleh PPKN terdiri atas:
a. pejabat pada Sekretariat Utama;
b. pejabat pada Inspektorat Utama; dan
c. pegawai lain yang diperlukan sesuai dengan keahliannya.
(4) Majelis mempunyai tugas memeriksa dan memberikan pertimbangan kepada PPKN terhadap:
a. penyelesaian atas kekurangan uang, surat berharga, dan/atau barang bukan disebabkan perbuatan melanggar hukum atau lalai pegawai ASN bukan bendahara dan/atau penyedia barang/jasa;
b. penggantian Kerugian Negara setelah pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dinyatakan wanprestasi; dan
c. penyelesaian Kerugian Negara yang telah diterbitkan SKP2KS.
(5) Dalam melaksanakan tugas, Majelis melakukan sidang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2545, '(1) Dalam rangka penyelesaian Kerugian Negara, PPKN membentuk Majelis.
(2) Jumlah anggota Majelis terdiri dari 3 (tiga) orang atau paling banyak 5 (lima) orang.
(3) Anggota Majelis yang dibentuk oleh PPKN terdiri atas:
a. pejabat pada Sekretariat Utama;
b. pejabat pada Inspektorat Utama; dan
c. pegawai lain yang diperlukan sesuai dengan keahliannya.
(4) Majelis mempunyai tugas memeriksa dan memberikan pertimbangan kepada PPKN terhadap:
a. penyelesaian atas kekurangan uang, surat berharga, dan/atau barang bukan disebabkan perbuatan melanggar hukum atau lalai pegawai ASN bukan bendahara dan/atau penyedia barang/jasa;
b. penggantian Kerugian Negara setelah pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dinyatakan wanprestasi; dan
c. penyelesaian Kerugian Negara yang telah diterbitkan SKP2KS.
(5) Dalam melaksanakan tugas, Majelis melakukan sidang.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2546, 'perban-2-2019', 24, 'pasal', 'Pasal 21', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Ketiga Penyelesaian Kerugian Negara Melalui Majelis', 17, '(1) Dalam hal hasil sidang terbukti bahwa kekurangan uang, surat berharga, dan/atau barang bukan disebabkan 2019, No. 740 -18- perbuatan melanggar hukum atau lalai pegawai ASN bukan bendahara dan/atau penyedia barang/jasa, Majelis menetapkan putusan hasil sidang berupa pertimbangan penghapusan.
(2) Tata cara penghapusan dilaksanakan sesuai ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2546, '(1) Dalam hal hasil sidang terbukti bahwa kekurangan uang, surat berharga, dan/atau barang bukan disebabkan 2019, No. 740 -18- perbuatan melanggar hukum atau lalai pegawai ASN bukan bendahara dan/atau penyedia barang/jasa, Majelis menetapkan putusan hasil sidang berupa pertimbangan penghapusan.
(2) Tata cara penghapusan dilaksanakan sesuai ketentuan peraturan perundang-undangan.', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2547, 'perban-2-2019', 25, 'pasal', 'Pasal 22', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Ketiga Penyelesaian Kerugian Negara Melalui Majelis', 18, '(1) Dalam hal hasil sidang merekomendasikan bahwa kekurangan uang, surat berharga, dan/atau barang disebabkan perbuatan melanggar hukum atau lalai pegawai ASN bukan bendahara dan/atau penyedia barang/jasa, Majelis dapat memerintahkan TPKN melalui PPKN untuk melakukan pemeriksaan kembali dan menyampaikan hal yang perlu mendapat perhatian dalam pemeriksaan kembali.
(2) Setelah melakukan pemeriksaan kembali sebagaimana dimaksud pada ayat (1), TPKN melalui PPKN menyampaikan laporan hasil pemeriksaan kembali kepada Majelis disertai dengan dokumen pendukung.
(3) PPKN menindaklanjuti putusan Majelis melalui proses penyelesaian Kerugian Negara melalui pertimbangan penghapusan, penerbitan SKTJM atau SKP2KS.
(4) Tata cara penghapusan dilaksanakan sesuai ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2547, '(1) Dalam hal hasil sidang merekomendasikan bahwa kekurangan uang, surat berharga, dan/atau barang disebabkan perbuatan melanggar hukum atau lalai pegawai ASN bukan bendahara dan/atau penyedia barang/jasa, Majelis dapat memerintahkan TPKN melalui PPKN untuk melakukan pemeriksaan kembali dan menyampaikan hal yang perlu mendapat perhatian dalam pemeriksaan kembali.
(2) Setelah melakukan pemeriksaan kembali sebagaimana dimaksud pada ayat (1), TPKN melalui PPKN menyampaikan laporan hasil pemeriksaan kembali kepada Majelis disertai dengan dokumen pendukung.
(3) PPKN menindaklanjuti putusan Majelis melalui proses penyelesaian Kerugian Negara melalui pertimbangan penghapusan, penerbitan SKTJM atau SKP2KS.
(4) Tata cara penghapusan dilaksanakan sesuai ketentuan peraturan perundang-undangan.', 'Pasal 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2548, 'perban-2-2019', 26, 'pasal', 'Pasal 23', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Ketiga Penyelesaian Kerugian Negara Melalui Majelis', 18, '(1) Dalam sidang untuk penyelesaian penggantian Kerugian Negara terhadap pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dinyatakan wanprestasi, Majelis menetapkan putusan berupa pertimbangan penerbitan SKP2K oleh PPKN.
(2) SKP2K sebagaimana dimaksud pada ayat (1) diterbitkan dalam waktu paling lama 14 (empat belas) hari kerja sejak Majelis menetapkan putusan.
(3) SKP2K sebagaimana dimaksud pada ayat (1) disampaikan kepada:
2019, No. 740
a. Badan Pemeriksa Keuangan;
b. Majelis;
c. panitia urusan piutang negara; dan
d. pegawai ASN bukan bendahara dan/atau penyedia barang/Jasa.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2548, '(1) Dalam sidang untuk penyelesaian penggantian Kerugian Negara terhadap pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dinyatakan wanprestasi, Majelis menetapkan putusan berupa pertimbangan penerbitan SKP2K oleh PPKN.
(2) SKP2K sebagaimana dimaksud pada ayat (1) diterbitkan dalam waktu paling lama 14 (empat belas) hari kerja sejak Majelis menetapkan putusan.
(3) SKP2K sebagaimana dimaksud pada ayat (1) disampaikan kepada:
2019, No. 740
a. Badan Pemeriksa Keuangan;
b. Majelis;
c. panitia urusan piutang negara; dan
d. pegawai ASN bukan bendahara dan/atau penyedia barang/Jasa.', 'Pasal 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2549, 'perban-2-2019', 27, 'pasal', 'Pasal 24', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Ketiga Penyelesaian Kerugian Negara Melalui Majelis', 19, '(1) Dalam sidang untuk penyelesaian Kerugian Negara yang telah diterbitkan SKP2KS, yang tidak ada pengajuan keberatan dari pegawai ASN bukan bendahara dan/atau penyedia barang/jasa, Majelis menetapkan putusan pertimbangan penerbitan SKP2K.
(2) Penyelesaian Kerugian Negara yang telah diterbitkan SKP2KS, yang diajukan keberatan dari pegawai ASN bukan bendahara dan/atau penyedia barang/jasa, apabila Majelis memperoleh cukup bukti, Majelis memutuskan:
a. menolak seluruhnya;
b. menerima seluruhnya; atau
c. menerima dan/atau menolak sebagian.
(3) Dalam hal dalam sidang Majelis belum memperoleh cukup bukti, Majelis dapat menugaskan TPKN melalui PPKN untuk melakukan pemeriksaan ulang terhadap materi yang terkait dengan Kerugian Negara yang terjadi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2549, '(1) Dalam sidang untuk penyelesaian Kerugian Negara yang telah diterbitkan SKP2KS, yang tidak ada pengajuan keberatan dari pegawai ASN bukan bendahara dan/atau penyedia barang/jasa, Majelis menetapkan putusan pertimbangan penerbitan SKP2K.
(2) Penyelesaian Kerugian Negara yang telah diterbitkan SKP2KS, yang diajukan keberatan dari pegawai ASN bukan bendahara dan/atau penyedia barang/jasa, apabila Majelis memperoleh cukup bukti, Majelis memutuskan:
a. menolak seluruhnya;
b. menerima seluruhnya; atau
c. menerima dan/atau menolak sebagian.
(3) Dalam hal dalam sidang Majelis belum memperoleh cukup bukti, Majelis dapat menugaskan TPKN melalui PPKN untuk melakukan pemeriksaan ulang terhadap materi yang terkait dengan Kerugian Negara yang terjadi.', 'Pasal 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2550, 'perban-2-2019', 28, 'pasal', 'Pasal 25', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Ketiga Penyelesaian Kerugian Negara Melalui Majelis', 19, '(1) SKP2K diterbitkan dalam waktu paling lama 14 (empat belas) hari kerja sejak Majelis menetapkan putusan hasil sidang.
(2) PPKN melakukan pengawasan atas pelaksanaan SKP2K.
(3) SKP2K mempunyai hak mendahulu.
(4) Bentuk dan isi SKP2K sesuai dengan format sebagaimana tercantum dalam Lampiran VIII yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
2019, No. 740 -20-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2550, '(1) SKP2K diterbitkan dalam waktu paling lama 14 (empat belas) hari kerja sejak Majelis menetapkan putusan hasil sidang.
(2) PPKN melakukan pengawasan atas pelaksanaan SKP2K.
(3) SKP2K mempunyai hak mendahulu.
(4) Bentuk dan isi SKP2K sesuai dengan format sebagaimana tercantum dalam Lampiran VIII yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
2019, No. 740 -20-', 'Pasal 25', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2551, 'perban-2-2019', 29, 'pasal', 'Pasal 26', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Keempat Penentuan Nilai Kerugian Negara', 20, '(1) Dalam hal sidang Majelis memutuskan menerima keberatan dari pegawai ASN bukan bendahara dan/atau penyedia barang/jasa, Majelis memberikan pertimbangan kepada PPKN untuk melakukan:
a. pembebasan penggantian Kerugian Negara;
b. penghapusan uang, surat berharga, dan/atau barang milik negara yang berada dalam penguasaan pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dan atau yang digunakan dalam penyelenggaraan tugas pemerintahan.
(2) Berdasarkan pertimbangan sebagaimana dimaksud pada ayat (1), PPKN:
a. menerbitkan surat keputusan pembebasan penggantian Kerugian Negara; dan
b. mengusulkan penghapusan uang, surat berharga, dan/atau barang milik negara yang berada dalam penguasaan pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dan/atau yang digunakan dalam penyelenggaraan tugas pemerintahan.
(3) Surat keputusan pembebasan penggantian Kerugian Negara diterbitkan dalam waktu paling lama 14 (empat hari) hari kerja sejak Majelis menetapkan putusan hasil sidang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2551, '(1) Dalam hal sidang Majelis memutuskan menerima keberatan dari pegawai ASN bukan bendahara dan/atau penyedia barang/jasa, Majelis memberikan pertimbangan kepada PPKN untuk melakukan:
a. pembebasan penggantian Kerugian Negara;
b. penghapusan uang, surat berharga, dan/atau barang milik negara yang berada dalam penguasaan pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dan atau yang digunakan dalam penyelenggaraan tugas pemerintahan.
(2) Berdasarkan pertimbangan sebagaimana dimaksud pada ayat (1), PPKN:
a. menerbitkan surat keputusan pembebasan penggantian Kerugian Negara; dan
b. mengusulkan penghapusan uang, surat berharga, dan/atau barang milik negara yang berada dalam penguasaan pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dan/atau yang digunakan dalam penyelenggaraan tugas pemerintahan.
(3) Surat keputusan pembebasan penggantian Kerugian Negara diterbitkan dalam waktu paling lama 14 (empat hari) hari kerja sejak Majelis menetapkan putusan hasil sidang.', 'Pasal 26', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2552, 'perban-2-2019', 30, 'pasal', 'Pasal 27', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Kelima Penagihan dan Penyetoran', 20, '(1) Dalam rangka penyelesaian Kerugian Negara, dilakukan penentuan nilai atas berkurangnya:
a. barang milik negara yang berada dalam penguasaan pegawai ASN bukan bendahara dan/atau penyedia barang/jasa; dan/atau
b. barang bukan milik negara yang berada dalam penguasaan pegawai ASN bukan bendahara 2019, No. 740 dan/atau penyedia barang/jasa yang digunakan dalam penyelenggaraan tugas pemerintahan.
(2) Penentuan nilai sebagaimana dimaksud pada ayat (1) didasarkan pada:
a. nilai buku; atau
b. nilai wajar atas barang yang sejenis.
(3) Dalam hal baik nilai buku maupun nilai wajar dapat ditentukan, nilai barang yang digunakan adalah nilai yang paling tinggi di antara kedua nilai tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2552, '(1) Dalam rangka penyelesaian Kerugian Negara, dilakukan penentuan nilai atas berkurangnya:
a. barang milik negara yang berada dalam penguasaan pegawai ASN bukan bendahara dan/atau penyedia barang/jasa; dan/atau
b. barang bukan milik negara yang berada dalam penguasaan pegawai ASN bukan bendahara 2019, No. 740 dan/atau penyedia barang/jasa yang digunakan dalam penyelenggaraan tugas pemerintahan.
(2) Penentuan nilai sebagaimana dimaksud pada ayat (1) didasarkan pada:
a. nilai buku; atau
b. nilai wajar atas barang yang sejenis.
(3) Dalam hal baik nilai buku maupun nilai wajar dapat ditentukan, nilai barang yang digunakan adalah nilai yang paling tinggi di antara kedua nilai tersebut.', 'Pasal 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2553, 'perban-2-2019', 31, 'pasal', 'Pasal 28', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Kelima Penagihan dan Penyetoran', 21, '(1) Penagihan dalam rangka penyelesaian Kerugian Negara dilakukan atas dasar:
a. SKTJM;
b. SKP2KS; atau
c. SKP2K.
(2) Penagihan sebagaimana dimaksud pada ayat (1) dilakukan dengan surat penagihan yang diterbitkan oleh PPKN dalam waktu paling lama 7 (tujuh) hari kerja sejak SKTJM, SKP2KS, atau SKP2K ditetapkan.
(3) Bentuk dan isi Surat Penagihan sesuai dengan format sebagaimana tercantum dalam Lampiran IX yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2553, '(1) Penagihan dalam rangka penyelesaian Kerugian Negara dilakukan atas dasar:
a. SKTJM;
b. SKP2KS; atau
c. SKP2K.
(2) Penagihan sebagaimana dimaksud pada ayat (1) dilakukan dengan surat penagihan yang diterbitkan oleh PPKN dalam waktu paling lama 7 (tujuh) hari kerja sejak SKTJM, SKP2KS, atau SKP2K ditetapkan.
(3) Bentuk dan isi Surat Penagihan sesuai dengan format sebagaimana tercantum dalam Lampiran IX yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2554, 'perban-2-2019', 32, 'pasal', 'Pasal 29', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Kelima Penagihan dan Penyetoran', 21, '(1) Pegawai ASN bukan bendahara dan/atau penyedia barang/jasa yang telah melakukan penyetoran ganti Kerugian Negara ke Kas Negara sesuai dengan jumlah dan jangka waktu yang tercantum dalam SKTJM, SKP2KS, atau SKP2K, dinyatakan telah melakukan pelunasan dengan SKTL yang ditandatangani oleh PPKN.
(2) Dalam hal SKTL diterbitkan atas dasar pelunasan SKTJM, pemberian SKTL kepada pegawai ASN bukan 2019, No. 740 -22- bendahara dan/atau penyedia barang/jasa disertai dengan pengembalian dokumen yang terkait dengan penyerahan barang jaminan.
(3) Dalam hal terdapat harta kekayaan pegawai ASN bukan bendahara dan/atau penyedia barang/jasa telah disita atas dasar SKP2KS atau SKP2K, pemberian SKTL kepada pegawai ASN bukan bendahara dan/atau penyedia barang/jasa disertai dengan surat permohonan pencabutan sita atas harta kekayaan kepada instansi yang berwenang.
(4) SKTL sebagaimana dimaksud pada ayat (1) disampaikan kepada:
a. Badan Pemeriksa Keuangan;
b. Majelis;
c. pegawai ASN bukan bendahara dan/atau penyedia barang/jasa; dan
d. panitia urusan piutang negara.
(5) Bentuk dan isi SKTL sesuai dengan format sebagaimana tercantum dalam Lampiran X yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2554, '(1) Pegawai ASN bukan bendahara dan/atau penyedia barang/jasa yang telah melakukan penyetoran ganti Kerugian Negara ke Kas Negara sesuai dengan jumlah dan jangka waktu yang tercantum dalam SKTJM, SKP2KS, atau SKP2K, dinyatakan telah melakukan pelunasan dengan SKTL yang ditandatangani oleh PPKN.
(2) Dalam hal SKTL diterbitkan atas dasar pelunasan SKTJM, pemberian SKTL kepada pegawai ASN bukan 2019, No. 740 -22- bendahara dan/atau penyedia barang/jasa disertai dengan pengembalian dokumen yang terkait dengan penyerahan barang jaminan.
(3) Dalam hal terdapat harta kekayaan pegawai ASN bukan bendahara dan/atau penyedia barang/jasa telah disita atas dasar SKP2KS atau SKP2K, pemberian SKTL kepada pegawai ASN bukan bendahara dan/atau penyedia barang/jasa disertai dengan surat permohonan pencabutan sita atas harta kekayaan kepada instansi yang berwenang.
(4) SKTL sebagaimana dimaksud pada ayat (1) disampaikan kepada:
a. Badan Pemeriksa Keuangan;
b. Majelis;
c. pegawai ASN bukan bendahara dan/atau penyedia barang/jasa; dan
d. panitia urusan piutang negara.
(5) Bentuk dan isi SKTL sesuai dengan format sebagaimana tercantum dalam Lampiran X yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 29', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2555, 'perban-2-2019', 33, 'pasal', 'Pasal 30', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Kelima Penagihan dan Penyetoran', 22, '(1) Berdasarkan SKTL sebagaimana dimaksud dalam Pasal 29, PPKN mengusulkan penghapusan uang, surat berharga, dan/atau barang milik negara yang berada dalam penguasaan pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dan atau yang digunakan dalam penyelenggaraan tugas pemerintahan.
(2) Tata cara penghapusan dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2555, '(1) Berdasarkan SKTL sebagaimana dimaksud dalam Pasal 29, PPKN mengusulkan penghapusan uang, surat berharga, dan/atau barang milik negara yang berada dalam penguasaan pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dan atau yang digunakan dalam penyelenggaraan tugas pemerintahan.
(2) Tata cara penghapusan dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 30', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2556, 'perban-2-2019', 34, 'pasal', 'Pasal 31', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Keenam Penyerahan Upaya Penagihan Kerugian Negara kepada', 22, '(1) Dalam hal dapat dibuktikan bahwa jumlah Kerugian Negara yang telah ditagih ternyata lebih besar dari pada yang seharusnya, pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dapat mengajukan permohonan pengurangan tagihan negara.
2019, No. 740
(2) Dalam hal pegawai ASN bukan bendahara dan/atau penyedia barang/jasa telah melakukan penyetoran ke Kas Negara, pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dapat mengajukan permohonan pengembalian kelebihan setoran Kerugian Negara atas dasar pengurangan tagihan.
(3) Tata cara pengembalian kelebihan tagihan negara sebagaimana dimaksud pada ayat (2) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
Instansi yang Menangani Pengurusan Piutang Negara');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2556, '(1) Dalam hal dapat dibuktikan bahwa jumlah Kerugian Negara yang telah ditagih ternyata lebih besar dari pada yang seharusnya, pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dapat mengajukan permohonan pengurangan tagihan negara.
2019, No. 740
(2) Dalam hal pegawai ASN bukan bendahara dan/atau penyedia barang/jasa telah melakukan penyetoran ke Kas Negara, pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dapat mengajukan permohonan pengembalian kelebihan setoran Kerugian Negara atas dasar pengurangan tagihan.
(3) Tata cara pengembalian kelebihan tagihan negara sebagaimana dimaksud pada ayat (2) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
Instansi yang Menangani Pengurusan Piutang Negara', 'Pasal 31', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2557, 'perban-2-2019', 35, 'pasal', 'Pasal 32', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Keenam Penyerahan Upaya Penagihan Kerugian Negara kepada', 23, 'Kepala BNPB menyerahkan upaya penagihan Kerugian Negara kepada panitia urusan piutang negara berdasarkan SKP2K yang diterbitkan atas penggantian Kerugian Negara yang dinyatakan wanprestasi dalam waktu paling lama 30 (tiga puluh) hari sejak SKP2K diterbitkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2557, 'Kepala BNPB menyerahkan upaya penagihan Kerugian Negara kepada panitia urusan piutang negara berdasarkan SKP2K yang diterbitkan atas penggantian Kerugian Negara yang dinyatakan wanprestasi dalam waktu paling lama 30 (tiga puluh) hari sejak SKP2K diterbitkan.', 'Pasal 32', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2558, 'perban-2-2019', 36, 'pasal', 'Pasal 33', 'BAB VI MEKANISME PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI APARATUR SIPIL NEGARA BUKAN BENDAHARA DAN/ATAU PENYEDIA BARANG/JASA; Bagian Keenam Penyerahan Upaya Penagihan Kerugian Negara kepada', 23, 'Dalam hal pegawai ASN bukan bendahara dan/atau penyedia barang/jasa tidak dapat mengganti Kerugian Negara dalam jangka waktu yang ditetapkan dalam SKP2K, Kepala BNPB menyerahkan upaya penagihan Kerugian Negara kepada panitia urusan piutang negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2558, 'Dalam hal pegawai ASN bukan bendahara dan/atau penyedia barang/jasa tidak dapat mengganti Kerugian Negara dalam jangka waktu yang ditetapkan dalam SKP2K, Kepala BNPB menyerahkan upaya penagihan Kerugian Negara kepada panitia urusan piutang negara.', 'Pasal 33', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2559, 'perban-2-2019', 37, 'pasal', 'Pasal 34', 'BAB VII DALUWARSA', 23, 'Penyerahan upaya penagihan Kerugian Negara kepada panitia urusan piutang negara sebagaimana dimaksud dalam Pasal 32 dan Pasal 33 dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
2019, No. 740 -24-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2559, 'Penyerahan upaya penagihan Kerugian Negara kepada panitia urusan piutang negara sebagaimana dimaksud dalam Pasal 32 dan Pasal 33 dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
2019, No. 740 -24-', 'Pasal 34', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2560, 'perban-2-2019', 38, 'pasal', 'Pasal 35', 'BAB VIII PELAPORAN PENYELESAIAN TUNTUTAN GANTI KERUGIAN DAN AKUNTANSI DAN PELAPORAN KEUANGAN', 24, '(1) Kewajiban BP/BPP, pegawai ASN bukan bendahara, dan/atau penyedia barang/jasa untuk membayar ganti rugi, menjadi daluwarsa apabila dalam waktu paling lama 5 (lima) tahun sejak diketahuinya Kerugian Negara tersebut atau dalam waktu paling lama 8 (delapan) tahun sejak terjadinya Kerugian Negara tidak dilakukan penuntutan ganti Kerugian Negara terhadap yang bersangkutan.
(2) Tanggung jawab pengampu/yang memperoleh hak/ahli waris untuk membayar ganti Kerugian Negara dari BP/BPP, pegawai ASN bukan bendahara, dan/atau penyedia barang/jasa menjadi hapus apabila:
a. dalam waktu paling lama 3 (tiga) tahun telah lewat sejak keputusan pengadilan yang menetapkan pengampuan kepada BP/BPP/pegawai ASN bukan bendahara/penyedia barang/jasa;
b. sejak yang bersangkutan diketahui melarikan diri; atau
c. meninggal dunia tidak diberitahukan oleh pejabat yang berwenang tentang Kerugian Negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2560, '(1) Kewajiban BP/BPP, pegawai ASN bukan bendahara, dan/atau penyedia barang/jasa untuk membayar ganti rugi, menjadi daluwarsa apabila dalam waktu paling lama 5 (lima) tahun sejak diketahuinya Kerugian Negara tersebut atau dalam waktu paling lama 8 (delapan) tahun sejak terjadinya Kerugian Negara tidak dilakukan penuntutan ganti Kerugian Negara terhadap yang bersangkutan.
(2) Tanggung jawab pengampu/yang memperoleh hak/ahli waris untuk membayar ganti Kerugian Negara dari BP/BPP, pegawai ASN bukan bendahara, dan/atau penyedia barang/jasa menjadi hapus apabila:
a. dalam waktu paling lama 3 (tiga) tahun telah lewat sejak keputusan pengadilan yang menetapkan pengampuan kepada BP/BPP/pegawai ASN bukan bendahara/penyedia barang/jasa;
b. sejak yang bersangkutan diketahui melarikan diri; atau
c. meninggal dunia tidak diberitahukan oleh pejabat yang berwenang tentang Kerugian Negara.', 'Pasal 35', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2561, 'perban-2-2019', 39, 'pasal', 'Pasal 36', 'BAB VIII PELAPORAN PENYELESAIAN TUNTUTAN GANTI KERUGIAN DAN AKUNTANSI DAN PELAPORAN KEUANGAN', 24, 'Kepala BNPB melaporkan penyelesaian Kerugian Negara kepada Badan Pemeriksa Keuangan dalam waktu paling lama 60 (enam puluh) hari setelah Tuntutan Ganti Kerugian dinyatakan selesai.
2019, No. 740');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2561, 'Kepala BNPB melaporkan penyelesaian Kerugian Negara kepada Badan Pemeriksa Keuangan dalam waktu paling lama 60 (enam puluh) hari setelah Tuntutan Ganti Kerugian dinyatakan selesai.
2019, No. 740', 'Pasal 36', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2562, 'perban-2-2019', 40, 'pasal', 'Pasal 37', 'BAB IX PENGHAPUSAN KERUGIAN NEGARA', 25, 'Akuntansi dan pelaporan keuangan dalam rangka penyelesaian Kerugian Negara dilaksanakan sesuai standar akuntansi pemerintahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2562, 'Akuntansi dan pelaporan keuangan dalam rangka penyelesaian Kerugian Negara dilaksanakan sesuai standar akuntansi pemerintahan.', 'Pasal 37', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2563, 'perban-2-2019', 41, 'pasal', 'Pasal 38', 'BAB IX PENGHAPUSAN KERUGIAN NEGARA', 25, 'Dalam hal terdapat kasus Kerugian Negara yang mengalami kesulitan dalam penagihannya/penanganannya, Kepala BNPB atau Sekretaris Utama Selaku Kuasa Pengguna Anggaran wajib melakukan penagihan dan peringatan secara tertulis kepada pihak yang melakukan Kerugian Negara sebanyak 3 (tiga) kali dalam waktu paling lama 30 (tiga puluh) hari kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2563, 'Dalam hal terdapat kasus Kerugian Negara yang mengalami kesulitan dalam penagihannya/penanganannya, Kepala BNPB atau Sekretaris Utama Selaku Kuasa Pengguna Anggaran wajib melakukan penagihan dan peringatan secara tertulis kepada pihak yang melakukan Kerugian Negara sebanyak 3 (tiga) kali dalam waktu paling lama 30 (tiga puluh) hari kerja.', 'Pasal 38', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2564, 'perban-2-2019', 42, 'pasal', 'Pasal 39', 'BAB IX PENGHAPUSAN KERUGIAN NEGARA', 25, 'Dalam hal penagihan dan peringatan secara tertulis tersebut tidak dipatuhi oleh pihak yang melakukan Kerugian Negara, Kepala BNPB atau Sekretaris Utama Selaku Kuasa Pengguna Anggaran menyerahkan Kerugian Negara tersebut melalui kantor pelayanan kekayaan negara dan lelang setempat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2564, 'Dalam hal penagihan dan peringatan secara tertulis tersebut tidak dipatuhi oleh pihak yang melakukan Kerugian Negara, Kepala BNPB atau Sekretaris Utama Selaku Kuasa Pengguna Anggaran menyerahkan Kerugian Negara tersebut melalui kantor pelayanan kekayaan negara dan lelang setempat.', 'Pasal 39', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2565, 'perban-2-2019', 43, 'pasal', 'Pasal 40', 'BAB IX PENGHAPUSAN KERUGIAN NEGARA', 25, 'Penyerahan Kerugian Negara sebagaimana dimaksud dalam Pasal 39, dilakukan untuk Kerugian Negara dalam kategori:
a. daluwarsa;
b. pelaku telah meninggal dunia;
c. pelaku melarikan diri;
d. pelaku di bawah pengampuan;
e. pelaku tidak mampu dari segi ekonominya; dan/atau
f. pelaku tidak diketahui alamatnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2565, 'Penyerahan Kerugian Negara sebagaimana dimaksud dalam Pasal 39, dilakukan untuk Kerugian Negara dalam kategori:
a. daluwarsa;
b. pelaku telah meninggal dunia;
c. pelaku melarikan diri;
d. pelaku di bawah pengampuan;
e. pelaku tidak mampu dari segi ekonominya; dan/atau
f. pelaku tidak diketahui alamatnya.', 'Pasal 40', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2566, 'perban-2-2019', 44, 'pasal', 'Pasal 41', 'BAB X SANKSI', 25, 'Kepala BNPB atau Sekretaris Utama Selaku Kuasa Pengguna Anggaran dalam melimpahkan kasus Kerugian Negara yang macet kepada kantor pelayanan kekayaan negara dan lelang 2019, No. 740 -26- sebagaimana dimaksud dalam Pasal 38, dengan dilengkapi dokumen:
a. laporan Kerugian Negara oleh TPKN;
b. SKTJM;
c. SKP2K yang ditetapkan oleh Kepala BNPB;
d. surat menyurat antara penyerah piutang dengan penanggung hutang yang berkaitan dengan usaha penagihan melalui surat peringatan I, surat peringatan II, dan surat peringatan III; dan
e. dokumen lainnya yang diperlukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2566, 'Kepala BNPB atau Sekretaris Utama Selaku Kuasa Pengguna Anggaran dalam melimpahkan kasus Kerugian Negara yang macet kepada kantor pelayanan kekayaan negara dan lelang 2019, No. 740 -26- sebagaimana dimaksud dalam Pasal 38, dengan dilengkapi dokumen:
a. laporan Kerugian Negara oleh TPKN;
b. SKTJM;
c. SKP2K yang ditetapkan oleh Kepala BNPB;
d. surat menyurat antara penyerah piutang dengan penanggung hutang yang berkaitan dengan usaha penagihan melalui surat peringatan I, surat peringatan II, dan surat peringatan III; dan
e. dokumen lainnya yang diperlukan.', 'Pasal 41', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2567, 'perban-2-2019', 45, 'pasal', 'Pasal 42', 'BAB XI KETENTUAN PENUTUP', 26, '(1) BP/BPP yang dikenai proses tuntutan perbendaharaan dan pegawai ASN bukan bendahara dan/atau penyedia barang/jasa yang dikenakan proses Tuntutan Ganti Kerugian dan dinyatakan bersalah dikenakan sanksi sesuai dengan ketentuan peraturan perundang-undangan.
(2) Dalam hal pimpinan unit kerja tidak melaporkan dan tidak menindaklanjuti Kerugian Negara yang terjadi di lingkungannya atau membiarkan dan tidak menindaklanjuti temuan pemeriksaan, dikenakan sanksi sesuai dengan ketentuan peraturan perundang-undangan.
(3) Putusan pidana tidak membebaskan:
a. BP/BPP dari tuntutan perbendaharaan; dan
b. pegawai ASN bukan bendahara dan/atau penyedia barang/jasa dari Tuntutan Ganti Kerugian.
2019, No. 740');
