INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2573, 'perban-2-2019', 51, 'lampiran', 'Lampiran hal. 31', NULL, 31, 'NIP Pangkat/Golongan Tempat/ Tanggal Lahir Alamat Nomor dan Tanggal SK Pengangkatan sebagai Bendahara Menyatakan dengan tidak akan menarik kembali, bahwa saya bertanggung jawab atas kerugian negara scbesar Rp. .dengan huruf.........! |), yakni kerugian yang discbabkan: .........oooo Kerugian tersebut akan saya ganti dengan menyetorkan jumlah tersebut kc Kas Ncgara dalam jangka waktu 40 (cmpat puluh) hari sejak saya menandatangani SKTJM ini.
Sebagai jaminan atas pernyataan ini, saya serahkan barang-barang beserta bukti kepemilikan dan surat kuasa menjual sebagai berikut.
Apabila dalam jangka waktu 40 (empat puluh) hari sctclah saya menandatangani pernyataan ini ternyata saya tidak mengganti seluruh jumlah kerugian tersebut, maka Negara dapat menjual atau melclang barang jaminan tersebut.
Mengetahui:
Kepala Badan Nasional Penanggulangan Bencana Meterai ”) Diisi dengan dua orang saksi dari pemeriksa Badan Pemeriksa Keuangan atau lingkungan instansi (BNPB) yang ikut menyaksikan penandatanganan SKTUM ini.
