INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2576, 'perban-2-2019', 54, 'lampiran', 'Lampiran hal. 33', NULL, 33, 'DONI MONARDO www.peraturan.go.id 2019, No. 740 -34- LAMPIRAN VI PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA NOMOR 2 TAHUN 2019 TENTANG TATA CARA PENYELESAIAN KERUGIAN NEGARA BADAN NASIONAL PENANGGULANGAN BENCANA Nomor Sifat Lampiran z a Hal 1 Surat Teguran Melalaikan Kewajiban Pelunasan/ Pembayaran atas Piutang Kerugian Negara Yen: Beren aa (Pihak yang menandatangani SKTUM) di Menunjuk Surat Keterangan Tanggung Jawab Mutlak (SKTJM) tanggal yang Saudara buat, yang menyatakan bahwa setiap bulan Saudara akan melakukan pelunasan/pcmbayaran atas ganti kerugian ncgara yang berupa piutang Penerimaan Negara Bukan Pajak (PNBP) sebesar Rp................ | KOaAR dengan huruf......... Ik Menurut penatausahaan piutang PNBP kami, sampai saat ini Saudara belum melakukan pelunasan/pembayaran atas atas ganti kerugian negara yang berupa piutang PNBP sebesar Rp................ | Ka dengan huruf......... ) sesuai dengan tanggal jatuh tempo sebagaimana tercantum dalam Surat Keterangan Tanggung Jawab Mutlak (SKTJM).
Oleh karcna itu diminta agar Saudara melunasi/ membayar tagihan tersebut dengan menyctorkannya kc Kas Ncgara pada Bank/Pos Persepsi untuk rekening Kas Negara paling lambat tanggal ............ dan apabila Saudara telah melakukan penyetoran, diminta agar fotokopi bukti setor berkenaan disampaikan kcpada kami.
