INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2592, 'perban-2-2020', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dengan ditetapkannya Peraturan Presiden Nomor 4 Tahun 2020 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana maka perlu dilakukan penyesuaian terhadap ketentuan dalam Peraturan Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana,
