b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana,', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 Tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2593, 'perban-2-2020', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1);
3. Peraturan Presiden Nomor 4 Tahun 2020 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2020 Nomor 12);
4. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2016 Nomor 1776);
5. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2593, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1);
3. Peraturan Presiden Nomor 4 Tahun 2020 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2020 Nomor 12);
4. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2016 Nomor 1776);
5. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 Tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2594, 'perban-2-2020', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PERUBAHAN ATAS PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 1 TAHUN 2016 TENTANG PELAKSANAAN PEMBERIAN TUNJANGAN KINERJA PEGAWAI DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
