INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2595, 'perban-2-2020', 4, 'pasal', 'Pasal I', NULL, 2, 'Beberapa ketentuan dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2016 Nomor 1776) diubah sebagai berikut:
1. Ketentuan angka 3 Pasal 1 diubah, sehingga Pasal 1 berbunyi sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2595, 'Beberapa ketentuan dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2016 Nomor 1776) diubah sebagai berikut:
1. Ketentuan angka 3 Pasal 1 diubah, sehingga Pasal 1 berbunyi sebagai berikut:', 'Pasal I', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 Tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2596, 'perban-2-2020', 5, 'pasal', 'Pasal 1', NULL, 3, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Pegawai Negeri Sipil yang selanjutnya disingkat PNS adalah warga negara Indonesia yang memenuhi syarat tertentu, diangkat sebagai Pegawai Aparatur Sipil Negara secara tetap oleh pejabat pembina kepegawaian untuk menduduki jabatan pemerintahan.
2. Pegawai adalah PNS dan Calon PNS yang berdasarkan Keputusan Pejabat yang berwenang diangkat dalam suatu jabatan dan bekerja secara penuh pada satuan organisasi di lingkungan Badan Nasional Penanggulangan Bencana.
3. Tunjangan Kinerja adalah tunjangan yang diberikan kepada Pegawai untuk meningkatkan kesejahteraan yang pelaksanaannya sesuai dengan Peraturan Presiden Nomor 4 Tahun 2020 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.
4. Kelas Jabatan adalah tingkat jabatan struktural maupun jabatan fungsional dalam satuan organisasi negara yang digunakan sebagai dasar pemberian tunjangan kinerja.
2. Ketentuan Pasal 2 diubah, sehingga berbunyi sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2596, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Pegawai Negeri Sipil yang selanjutnya disingkat PNS adalah warga negara Indonesia yang memenuhi syarat tertentu, diangkat sebagai Pegawai Aparatur Sipil Negara secara tetap oleh pejabat pembina kepegawaian untuk menduduki jabatan pemerintahan.
2. Pegawai adalah PNS dan Calon PNS yang berdasarkan Keputusan Pejabat yang berwenang diangkat dalam suatu jabatan dan bekerja secara penuh pada satuan organisasi di lingkungan Badan Nasional Penanggulangan Bencana.
3. Tunjangan Kinerja adalah tunjangan yang diberikan kepada Pegawai untuk meningkatkan kesejahteraan yang pelaksanaannya sesuai dengan Peraturan Presiden Nomor 4 Tahun 2020 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.
4. Kelas Jabatan adalah tingkat jabatan struktural maupun jabatan fungsional dalam satuan organisasi negara yang digunakan sebagai dasar pemberian tunjangan kinerja.
2. Ketentuan Pasal 2 diubah, sehingga berbunyi sebagai berikut:', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 Tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2597, 'perban-2-2020', 6, 'pasal', 'Pasal 2', NULL, 3, '(1) Setiap Pegawai berhak menerima Tunjangan Kinerja sesuai dengan ketentuan peraturan perundang-undangan.
(2) Tunjangan kinerja sebagaimana dimaksud pada ayat
(1) dibayarkan setiap bulan.
(3) Besaran Tunjangan Kinerja sebagaimana dimaksud pada ayat (1) tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(4) Tunjangan Kinerja sebagaimana dimaksud pada ayat
(1) diberikan terhitung mulai bulan Januari 2019.
3. Di antara Pasal 20 dan Pasal 21 disisipkan 1 (satu) Pasal yakni Pasal 20A, sehingga berbunyi sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2597, '(1) Setiap Pegawai berhak menerima Tunjangan Kinerja sesuai dengan ketentuan peraturan perundang-undangan.
