3. Di antara Pasal 20 dan Pasal 21 disisipkan 1 (satu) Pasal yakni Pasal 20A, sehingga berbunyi sebagai berikut:', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 Tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2598, 'perban-2-2020', 7, 'pasal', 'Pasal 20A', NULL, 4, '(1) Kepala Badan Nasional Penanggulangan Bencana diberikan tunjangan kinerja sebesar 150% (seratus lima puluh per seratus) dari Tunjangan Kinerja pada Kelas Jabatan tertinggi di lingkungan Badan Nasional Penanggulangan Bencana.
(2) Tunjangan Kinerja bagi Kepala Badan Nasional Penanggulangan Bencana sebagaimana dimaksud pada ayat (1) diberikan terhitung mulai bulan Januari 2019.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2598, '(1) Kepala Badan Nasional Penanggulangan Bencana diberikan tunjangan kinerja sebesar 150% (seratus lima puluh per seratus) dari Tunjangan Kinerja pada Kelas Jabatan tertinggi di lingkungan Badan Nasional Penanggulangan Bencana.
(2) Tunjangan Kinerja bagi Kepala Badan Nasional Penanggulangan Bencana sebagaimana dimaksud pada ayat (1) diberikan terhitung mulai bulan Januari 2019.', 'Pasal 20A', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 Tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2599, 'perban-2-2020', 8, 'pasal', 'Pasal II', NULL, 4, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan. ab Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
