INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2604, 'perban-2-2021', 1, 'mengingat', 'Mengingat', NULL, 1, 'Nasional Penanggulangan Bencana, Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran 1 Negara Republik Indonesia Nomor 4723),
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana sebagaimana telah telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461):');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2604, 'Nasional Penanggulangan Bencana, Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran 1 Negara Republik Indonesia Nomor 4723),
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana sebagaimana telah telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461):', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2605, 'perban-2-2021', 2, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG URAIAN FUNGSI ORGANISASI JABATAN PIMPINAN TINGGI PRATAMA DAN TUGAS KOORDINATOR JABATAN FUNGSIONAL DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2605, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG URAIAN FUNGSI ORGANISASI JABATAN PIMPINAN TINGGI PRATAMA DAN TUGAS KOORDINATOR JABATAN FUNGSIONAL DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2606, 'perban-2-2021', 3, 'pasal', 'Pasal 1', 'BAB I ORGANISASI DI LINGKUNGAN DEPUTI BIDANG SISTEM DAN STRATEGI; Bagian Kesatu Uraian Fungsi Direktorat Pemetaan dan Evaluasi Risiko', 2, 'Direktorat Pemetaan dan Evaluasi Risiko Bencana menyelenggarakan uraian fungsi:
a. penyiapan perumusan kebijakan teknis, penyusunan perencanaan dan pelaksanaan dukungan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan bimbingan teknis dan pengawasan, serta pelaksanaan monitoring dan evaluasi di bidang pemetaan dan analisis risiko bencana, dan
b. penyiapan perumusan kebijakan teknis, penyusunan perencanaan dan pelaksanaan dukungan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan bimbingan teknis dan pengawasan, pelaksanaan evaluasi dan analisis pelaporan di bidang monitoring dan evaluasi risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2606, 'Direktorat Pemetaan dan Evaluasi Risiko Bencana menyelenggarakan uraian fungsi:
a. penyiapan perumusan kebijakan teknis, penyusunan perencanaan dan pelaksanaan dukungan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan bimbingan teknis dan pengawasan, serta pelaksanaan monitoring dan evaluasi di bidang pemetaan dan analisis risiko bencana, dan
b. penyiapan perumusan kebijakan teknis, penyusunan perencanaan dan pelaksanaan dukungan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan bimbingan teknis dan pengawasan, pelaksanaan evaluasi dan analisis pelaporan di bidang monitoring dan evaluasi risiko bencana.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2607, 'perban-2-2021', 4, 'pasal', 'Pasal 2', 'BAB I ORGANISASI DI LINGKUNGAN DEPUTI BIDANG SISTEM DAN STRATEGI; Bagian Kedua Uraian Fungsi Direktorat Pengembangan Strategi', 3, 'Pengelompokan uraian fungsi Direktorat Pemetaan dan Evaluasi Risiko Bencana terdiri atas:
a. kelompok substansi pemetaan dan analisis risiko bencana, dan
b. kelompok substansi monitoring dan evaluasi risiko bencana.
Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2607, 'Pengelompokan uraian fungsi Direktorat Pemetaan dan Evaluasi Risiko Bencana terdiri atas:
a. kelompok substansi pemetaan dan analisis risiko bencana, dan
b. kelompok substansi monitoring dan evaluasi risiko bencana.
Penanggulangan Bencana', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2608, 'perban-2-2021', 5, 'pasal', 'Pasal 3', 'BAB I ORGANISASI DI LINGKUNGAN DEPUTI BIDANG SISTEM DAN STRATEGI; Bagian Kedua Uraian Fungsi Direktorat Pengembangan Strategi', 3, 'Direktorat Pengembangan Strategi Penanggulangan Bencana menyelenggarakan uraian fungsi:
a. penyiapan perumusan kebijakan teknis, penyusunan perencanaan dan pelaksanaan dukungan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan bimbingan teknis dan pengawasan, pelaksanaan monitoring dan evaluasi, pelaksanaan riset dan kajian teknis di bidang strategi pengurangan risiko: dan
b. penyusunan perencanaan dan pelaksanaan dukungan teknis, koordinasi penyusunan Norma, Standar, Prosedur, Kriteria, pelaksanaan bimbingan teknis dan pengawasan, pelaksanaan monitoring dan evaluasi di bidang tata kelola penanggulangan bencana serta pelaksanaan kebijakan pengembangan strategi penanggulangan bencana secara holistik, integratif dan multi perspektif.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2608, 'Direktorat Pengembangan Strategi Penanggulangan Bencana menyelenggarakan uraian fungsi:
a. penyiapan perumusan kebijakan teknis, penyusunan perencanaan dan pelaksanaan dukungan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan bimbingan teknis dan pengawasan, pelaksanaan monitoring dan evaluasi, pelaksanaan riset dan kajian teknis di bidang strategi pengurangan risiko: dan
b. penyusunan perencanaan dan pelaksanaan dukungan teknis, koordinasi penyusunan Norma, Standar, Prosedur, Kriteria, pelaksanaan bimbingan teknis dan pengawasan, pelaksanaan monitoring dan evaluasi di bidang tata kelola penanggulangan bencana serta pelaksanaan kebijakan pengembangan strategi penanggulangan bencana secara holistik, integratif dan multi perspektif.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2609, 'perban-2-2021', 6, 'pasal', 'Pasal 4', 'BAB I ORGANISASI DI LINGKUNGAN DEPUTI BIDANG SISTEM DAN STRATEGI; Bagian Ketiga Uraian Fungsi Direktorat Sistem Penanggulangan Bencana', 4, 'Pengelompokan uraian fungsi Direktorat Pengembangan Strategi Penanggulangan Bencana terdiri atas:
a. kelompok substansi strategi pengurangan risiko bencana, dan
b. kelompok substansi tata kelola penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2609, 'Pengelompokan uraian fungsi Direktorat Pengembangan Strategi Penanggulangan Bencana terdiri atas:
a. kelompok substansi strategi pengurangan risiko bencana, dan
b. kelompok substansi tata kelola penanggulangan bencana.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2610, 'perban-2-2021', 7, 'pasal', 'Pasal 5', 'BAB I ORGANISASI DI LINGKUNGAN DEPUTI BIDANG SISTEM DAN STRATEGI; Bagian Ketiga Uraian Fungsi Direktorat Sistem Penanggulangan Bencana', 4, 'Direktorat Sistem Penanggulangan Bencana menyelenggarakan uraian fungsi:
a. penyiapan perumusan kebijakan teknis, penyusunan perencanaan dan pelaksanaan dukungan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan bimbingan teknis dan pengawasan dan pelaksanaan monitoring dan evaluasi di bidang rancang bangun sistem serta pengembangan sistem penanggulangan bencana secara holistik, integratif dalam tahapan prabencana, tanggap darurat dan pascabencana, dan
b. penyusunan perencanaan dan pelaksanaan dukungan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan bimbingan teknis dan pengawasan dan pelaksanaan monitoring dan evaluasi di bidang pengembangan standar penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2610, 'Direktorat Sistem Penanggulangan Bencana menyelenggarakan uraian fungsi:
a. penyiapan perumusan kebijakan teknis, penyusunan perencanaan dan pelaksanaan dukungan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan bimbingan teknis dan pengawasan dan pelaksanaan monitoring dan evaluasi di bidang rancang bangun sistem serta pengembangan sistem penanggulangan bencana secara holistik, integratif dalam tahapan prabencana, tanggap darurat dan pascabencana, dan
b. penyusunan perencanaan dan pelaksanaan dukungan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan bimbingan teknis dan pengawasan dan pelaksanaan monitoring dan evaluasi di bidang pengembangan standar penanggulangan bencana.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2611, 'perban-2-2021', 8, 'pasal', 'Pasal 6', 'BAB II ORGANISASI DI LINGKUNGAN DEPUTI BIDANG PENCEGAHAN; Bagian Kesatu Uraian Fungsi Direktorat Mitigasi Bencana', 4, 'Pengelompokan uraian fungsi Direktorat Sistem Penanggulangan Bencana terdiri atas:
a. kelompok substansi rancang bangun sistem, dan
b. kelompok substansi pengembangan standar penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2611, 'Pengelompokan uraian fungsi Direktorat Sistem Penanggulangan Bencana terdiri atas:
a. kelompok substansi rancang bangun sistem, dan
b. kelompok substansi pengembangan standar penanggulangan bencana.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2612, 'perban-2-2021', 9, 'pasal', 'Pasal 7', 'BAB II ORGANISASI DI LINGKUNGAN DEPUTI BIDANG PENCEGAHAN; Bagian Kesatu Uraian Fungsi Direktorat Mitigasi Bencana', 5, 'Direktorat Mitigasi Bencana menyelenggarakan uraian fungsi:
a. penyiapan perumusan dan pelaksanaan kebijakan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, kampanye dan edukasi publik, pelaksanaan bimbingan teknis, pengawasan dan pelaksanaan monitoring dan evaluasi di bidang mitigasi struktural, dan
b. penyiapan perumusan dan pelaksanaan kebijakan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, kampanye dan edukasi publik, pelaksanaan bimbingan teknis, pengawasan dan pelaksanaan monitoring dan evaluasi di bidang mitigasi nonstruktural.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2612, 'Direktorat Mitigasi Bencana menyelenggarakan uraian fungsi:
a. penyiapan perumusan dan pelaksanaan kebijakan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, kampanye dan edukasi publik, pelaksanaan bimbingan teknis, pengawasan dan pelaksanaan monitoring dan evaluasi di bidang mitigasi struktural, dan
b. penyiapan perumusan dan pelaksanaan kebijakan teknis, koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, kampanye dan edukasi publik, pelaksanaan bimbingan teknis, pengawasan dan pelaksanaan monitoring dan evaluasi di bidang mitigasi nonstruktural.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2613, 'perban-2-2021', 10, 'pasal', 'Pasal 8', 'BAB II ORGANISASI DI LINGKUNGAN DEPUTI BIDANG PENCEGAHAN; Bagian Kedua Uraian Fungsi Direktorat Kesiapsiagaan', 5, 'Pengelompokan uraian fungsi Direktorat Mitigasi Bencana terdiri atas:
a. kelompok substansi mitigasi struktural: dan
b. kelompok substansi mitigasi nonstruktural.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2613, 'Pengelompokan uraian fungsi Direktorat Mitigasi Bencana terdiri atas:
a. kelompok substansi mitigasi struktural: dan
b. kelompok substansi mitigasi nonstruktural.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2614, 'perban-2-2021', 11, 'pasal', 'Pasal 9', 'BAB II ORGANISASI DI LINGKUNGAN DEPUTI BIDANG PENCEGAHAN; Bagian Kedua Uraian Fungsi Direktorat Kesiapsiagaan', 5, 'Direktorat Kesiapsiagaan menyelenggarakan uraian fungsi:
a. koordinasi penyusunan dan pelaksanaan kebijakan teknis di bidang perencanaan kesiapsiagaan, penyiapan lokasi evakuasi, penyiapan koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria dan bahan monitoring dan evaluasi di bidang perencanaan kesiapsiagaan serta penyiapan penyusunan dan uji coba rencana penanggulangan kedaruratan “bencana dan rencana kontingensi,
b. koordinasi penyusunan dan pelaksanaan kebijakan teknis di bidang pemberdayaan sumber daya, penyiapan koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, dan bahan monitoring dan evaluasi di bidang pemberdayaan sumber daya serta koordinasi pemberdayaan sumber daya penanggulangan bencana pada komunitas dan lembaga usaha, dan Cc. koordinasi penyusunan dan pelaksanaan kebijakan teknis di bidang penguatan ketahanan masyarakat, penyiapan koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria dan bahan monitoring dan evaluasi di bidang penguatan ketahanan masyarakat serta koordinasi fasilitasi peningkatan kesadaran dan kesiapsiagaan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2614, 'Direktorat Kesiapsiagaan menyelenggarakan uraian fungsi:
a. koordinasi penyusunan dan pelaksanaan kebijakan teknis di bidang perencanaan kesiapsiagaan, penyiapan lokasi evakuasi, penyiapan koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria dan bahan monitoring dan evaluasi di bidang perencanaan kesiapsiagaan serta penyiapan penyusunan dan uji coba rencana penanggulangan kedaruratan “bencana dan rencana kontingensi,
b. koordinasi penyusunan dan pelaksanaan kebijakan teknis di bidang pemberdayaan sumber daya, penyiapan koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, dan bahan monitoring dan evaluasi di bidang pemberdayaan sumber daya serta koordinasi pemberdayaan sumber daya penanggulangan bencana pada komunitas dan lembaga usaha, dan Cc. koordinasi penyusunan dan pelaksanaan kebijakan teknis di bidang penguatan ketahanan masyarakat, penyiapan koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria dan bahan monitoring dan evaluasi di bidang penguatan ketahanan masyarakat serta koordinasi fasilitasi peningkatan kesadaran dan kesiapsiagaan masyarakat.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2615, 'perban-2-2021', 12, 'pasal', 'Pasal 10', 'BAB II ORGANISASI DI LINGKUNGAN DEPUTI BIDANG PENCEGAHAN; Bagian Ketiga Uraian Fungsi Direktorat Peringatan Dini', 6, 'Pengelompokan uraian fungsi Direktorat Kesiapsiagaan terdiri atas:
a. kelompok substansi perencanaan kesiapsiagaan,
b. kelompok substansi pemberdayaan sumber daya, dan Cc. kelompok substansi penguatan ketahanan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2615, 'Pengelompokan uraian fungsi Direktorat Kesiapsiagaan terdiri atas:
a. kelompok substansi perencanaan kesiapsiagaan,
b. kelompok substansi pemberdayaan sumber daya, dan Cc. kelompok substansi penguatan ketahanan masyarakat.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2616, 'perban-2-2021', 13, 'pasal', 'Pasal 11', 'BAB II ORGANISASI DI LINGKUNGAN DEPUTI BIDANG PENCEGAHAN; Bagian Ketiga Uraian Fungsi Direktorat Peringatan Dini', 6, 'Direktorat Peringatan Dini menyelenggarakan uraian fungsi:
a. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria dan monitoring dan evaluasi di bidang pemantauan, pengolahan, koordinasi, serta integrasi sistem peringatan dini bencana secara efektif dan terpadu: dan
b. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria dan monitoring dan evaluasi di bidang diseminasi informasi, penguatan kapasitas, serta kesiapan respon masyarakat terhadap peringatan dini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2616, 'Direktorat Peringatan Dini menyelenggarakan uraian fungsi:
a. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria dan monitoring dan evaluasi di bidang pemantauan, pengolahan, koordinasi, serta integrasi sistem peringatan dini bencana secara efektif dan terpadu: dan
b. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria dan monitoring dan evaluasi di bidang diseminasi informasi, penguatan kapasitas, serta kesiapan respon masyarakat terhadap peringatan dini.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2617, 'perban-2-2021', 14, 'pasal', 'Pasal 12', 'BAB III ORGANISASI DI LINGKUNGAN DEPUTI BIDANG PENANGANAN DARURAT; Bagian Kesatu Uraian Fungsi Direktorat Dukungan Sumber Daya Darurat', 7, 'Pengelompokan uraian fungsi Direktorat Peringatan Dini terdiri atas:
a. kelompok substansi integrasi dan pengolahan pemantauan, dan
b. kelompok substansi diseminasi dan evaluasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2617, 'Pengelompokan uraian fungsi Direktorat Peringatan Dini terdiri atas:
a. kelompok substansi integrasi dan pengolahan pemantauan, dan
b. kelompok substansi diseminasi dan evaluasi.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2618, 'perban-2-2021', 15, 'pasal', 'Pasal 13', 'BAB III ORGANISASI DI LINGKUNGAN DEPUTI BIDANG PENANGANAN DARURAT; Bagian Kesatu Uraian Fungsi Direktorat Dukungan Sumber Daya Darurat', 7, 'Direktorat Dukungan Sumber Daya Darurat menyelenggarakan uraian fungsi:
a. komando pelaksanaan dukungan sumber daya darurat,
b. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan dan pelaksanaan pengerahan sumber daya manusia pemerintah dan monitoring dan evaluasi di bidang pengerahan sumber daya manusia pemerintah, Cc. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan dan pelaksanaan pengerahan sumber daya manusia lembaga usaha dan masyarakat dan monitoring dan evaluasi di bidang pengerahan sumber daya manusia lembaga usaha dan masyarakat,
d. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan dan pelaksanaan pengerahan logistik dan monitoring dan evaluasi di bidang pengerahan logistik,
e. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur dan Kriteria, penyusunan perencanaan dan pelaksanaan pengerahan peralatan dan monitoring dan evaluasi di bidang pengerahan peralatan,
f. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan dan pelaksanaan verifikasi dan penilaian kebutuhan bantuan dan dana kedaruratan dan monitoring dan evaluasi di bidang verifikasi dan penilaian kebutuhan bantuan dan dana kedaruratan, dan
g. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis dan pemantauan, evaluasi dan analisis pelaporan pengelolaan bantuan dan dana kedaruratan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2618, 'Direktorat Dukungan Sumber Daya Darurat menyelenggarakan uraian fungsi:
a. komando pelaksanaan dukungan sumber daya darurat,
b. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan dan pelaksanaan pengerahan sumber daya manusia pemerintah dan monitoring dan evaluasi di bidang pengerahan sumber daya manusia pemerintah, Cc. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan dan pelaksanaan pengerahan sumber daya manusia lembaga usaha dan masyarakat dan monitoring dan evaluasi di bidang pengerahan sumber daya manusia lembaga usaha dan masyarakat,
d. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan dan pelaksanaan pengerahan logistik dan monitoring dan evaluasi di bidang pengerahan logistik,
e. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur dan Kriteria, penyusunan perencanaan dan pelaksanaan pengerahan peralatan dan monitoring dan evaluasi di bidang pengerahan peralatan,
f. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan dan pelaksanaan verifikasi dan penilaian kebutuhan bantuan dan dana kedaruratan dan monitoring dan evaluasi di bidang verifikasi dan penilaian kebutuhan bantuan dan dana kedaruratan, dan
g. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis dan pemantauan, evaluasi dan analisis pelaporan pengelolaan bantuan dan dana kedaruratan.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2619, 'perban-2-2021', 16, 'pasal', 'Pasal 14', 'BAB III ORGANISASI DI LINGKUNGAN DEPUTI BIDANG PENANGANAN DARURAT; Bagian Kesatu Uraian Fungsi Direktorat Dukungan Sumber Daya Darurat', 8, 'Pengelompokan uraian fungsi Dukungan Sumber Daya Darurat terdiri atas:
a. kelompok substansi sumber daya manusia pemerintah:
b. kelompok substansi sumber daya manusia lembaga usaha dan masyarakat, Cc. kelompok substansi dukungan pengerahan logisitik:
d. kelompok substansi dukungan pengerahan peralatan:
e. kelompok substansi verifikasi dan penilaian kebutuhan kedaruratan, dan
f. kelompok substansi pemantauan, evaluasi dan pelaporan kedaruratan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2619, 'Pengelompokan uraian fungsi Dukungan Sumber Daya Darurat terdiri atas:
a. kelompok substansi sumber daya manusia pemerintah:
b. kelompok substansi sumber daya manusia lembaga usaha dan masyarakat, Cc. kelompok substansi dukungan pengerahan logisitik:
d. kelompok substansi dukungan pengerahan peralatan:
e. kelompok substansi verifikasi dan penilaian kebutuhan kedaruratan, dan
f. kelompok substansi pemantauan, evaluasi dan pelaporan kedaruratan.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2620, 'perban-2-2021', 17, 'pasal', 'Pasal 15', 'BAB III ORGANISASI DI LINGKUNGAN DEPUTI BIDANG PENANGANAN DARURAT; Bagian Kedua Uraian Fungsi Direktorat Dukungan Infrastruktur Darurat', 8, 'Ketentuan mengenai uraian fungsi yang menangani urusan dukungan pengerahan sumber daya manusia, dukungan pengerahan pengerahan logisiik dan peralatan dan pengelolaan bantuan dan dana kedaruratan berpedoman pada Peraturan Badan Nasional Penanggulangan Bencana yang mengatur mengenai organisasi dan tata kerja.
Direktorat Dukungan Infrastruktur Darurat menyelenggarakan uraian fungsi:
a. komando pelaksanaan dukungan infrastruktur darurat,
b. koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyiapan koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan dan pelaksanaan verifikasi dan penilaian kebutuhan pemulihan prasarana vital, Cc. penyiapan pemantauan, evaluasi dan analisis pelaporan di bidang pemulihan prasarana vital,
d. koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyiapan koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan dan pelaksanaan verifikasi dan penilaian kebutuhan pemulihan sarana dan utilitas, dan
e. penyiapan pemantauan, evaluasi dan analisis pelaporan di bidang pemulihan sarana dan utilitas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2620, 'Ketentuan mengenai uraian fungsi yang menangani urusan dukungan pengerahan sumber daya manusia, dukungan pengerahan pengerahan logisiik dan peralatan dan pengelolaan bantuan dan dana kedaruratan berpedoman pada Peraturan Badan Nasional Penanggulangan Bencana yang mengatur mengenai organisasi dan tata kerja.
Direktorat Dukungan Infrastruktur Darurat menyelenggarakan uraian fungsi:
a. komando pelaksanaan dukungan infrastruktur darurat,
b. koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyiapan koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan dan pelaksanaan verifikasi dan penilaian kebutuhan pemulihan prasarana vital, Cc. penyiapan pemantauan, evaluasi dan analisis pelaporan di bidang pemulihan prasarana vital,
d. koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyiapan koordinasi penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan dan pelaksanaan verifikasi dan penilaian kebutuhan pemulihan sarana dan utilitas, dan
e. penyiapan pemantauan, evaluasi dan analisis pelaporan di bidang pemulihan sarana dan utilitas.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2621, 'perban-2-2021', 18, 'pasal', 'Pasal 16', 'BAB III ORGANISASI DI LINGKUNGAN DEPUTI BIDANG PENANGANAN DARURAT; Bagian Kedua Uraian Fungsi Direktorat Dukungan Infrastruktur Darurat', 9, 'Pengelompokan uraian fungsi Direktorat Dukungan Infrastruktur Darurat terdiri atas:
a. kelompok substansi verifikasi dan penilaian kebutuhan pemulihan prasarana vital,
b. kelompok substansi pemantauan, evaluasi dan pelaporan pemulihan prasarana vital, dan Cc. kelompok substansi verifikasi dan penilaian kebutuhan pemulihan sarana dan utilitas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2621, 'Pengelompokan uraian fungsi Direktorat Dukungan Infrastruktur Darurat terdiri atas:
a. kelompok substansi verifikasi dan penilaian kebutuhan pemulihan prasarana vital,
b. kelompok substansi pemantauan, evaluasi dan pelaporan pemulihan prasarana vital, dan Cc. kelompok substansi verifikasi dan penilaian kebutuhan pemulihan sarana dan utilitas.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2622, 'perban-2-2021', 19, 'pasal', 'Pasal 17', 'BAB III ORGANISASI DI LINGKUNGAN DEPUTI BIDANG PENANGANAN DARURAT; Bagian Ketiga Uraian Fungsi Direktorat Fasilitasi Penanganan Korban dan', 10, 'Ketentuan mengenai uraian fungsi yang menangani urusan pemulihan prasarana vital, pemulihan " sarana dan pemantauan, evaluasi dan pelaporan pemulihan sarana dan utilitas berpedoman pada Peraturan Badan Nasional Penanggulangan Bencana yang mengatur mengenai organisasi dan tata kerja.
Pengungsi Pasal 18 .
Direktorat Fasilitasi Penanganan Korban dan Pengungsi uraian fungsi:
a. komando pelaksanaan fasilitasi penanganan korban dan pengungsi,
b. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, koordinasi penyusunan rencana dan pelaksanaan dan penyiapan bahan monitoring dan evaluasi di bidang pencarian dan pertolongan darurat, Cc. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, koordinasi penyusunan rencana, dan pelaksanaan dan penyiapan bahan monitoring dan evaluasi di bidang evakuasi dan perlindungan,
d. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyiapan dan penyajian data dan bahan monitoring dan evaluasi di bidang penyajian data korban dan pengungsi, dan
e. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, koordinasi fasilitasi pelayanan pemenuhan kebutuhan korban dan pengungsi dan penyiapan bahan monitoring dan evaluasi di bidang perencanaan pemenuhan kebutuhan korban dan pengungsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2622, 'Ketentuan mengenai uraian fungsi yang menangani urusan pemulihan prasarana vital, pemulihan " sarana dan pemantauan, evaluasi dan pelaporan pemulihan sarana dan utilitas berpedoman pada Peraturan Badan Nasional Penanggulangan Bencana yang mengatur mengenai organisasi dan tata kerja.
Pengungsi Pasal 18 .
Direktorat Fasilitasi Penanganan Korban dan Pengungsi uraian fungsi:
a. komando pelaksanaan fasilitasi penanganan korban dan pengungsi,
b. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, koordinasi penyusunan rencana dan pelaksanaan dan penyiapan bahan monitoring dan evaluasi di bidang pencarian dan pertolongan darurat, Cc. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, koordinasi penyusunan rencana, dan pelaksanaan dan penyiapan bahan monitoring dan evaluasi di bidang evakuasi dan perlindungan,
d. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyiapan dan penyajian data dan bahan monitoring dan evaluasi di bidang penyajian data korban dan pengungsi, dan
e. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, koordinasi fasilitasi pelayanan pemenuhan kebutuhan korban dan pengungsi dan penyiapan bahan monitoring dan evaluasi di bidang perencanaan pemenuhan kebutuhan korban dan pengungsi.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2623, 'perban-2-2021', 20, 'pasal', 'Pasal 19', 'BAB III ORGANISASI DI LINGKUNGAN DEPUTI BIDANG PENANGANAN DARURAT; Bagian Ketiga Uraian Fungsi Direktorat Fasilitasi Penanganan Korban dan', 11, 'Pengelompokan uraian fungsi Direktorat Fasilitasi Penanganan Korban dan Pengungsi dari:
a. kelompok substansi pencarian dan pertolongan darurat
b. kelompok substansi evakuasi dan perlindungan
c. kelompok substansi penyajian data korban dan pengungsi, dan
d. kelompok substansi perencanaan pemenuhan kebutuhan korban dan pengungsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2623, 'Pengelompokan uraian fungsi Direktorat Fasilitasi Penanganan Korban dan Pengungsi dari:
a. kelompok substansi pencarian dan pertolongan darurat
b. kelompok substansi evakuasi dan perlindungan
c. kelompok substansi penyajian data korban dan pengungsi, dan
d. kelompok substansi perencanaan pemenuhan kebutuhan korban dan pengungsi.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2624, 'perban-2-2021', 21, 'pasal', 'Pasal 20', 'BAB IV ORGANISASI DI LINGKUNGAN DEPUTI BIDANG REHABILITASI DAN REKONSTRUKSI; Bagian Kesatu Uraian Fungsi Direktorat Perencanaan Rehabilitasi dan', 11, 'Ketentuan mengenai uraian fungsi yang menangani urusan fasilitasi penyelamatan dan evakuasi, dan fasilitas pelayanan pemenuhan kebutuhan korban dan pengungsi berpedoman pada Peraturan Badan Nasional Penanggulangan Bencana yang mengatur mengenai organisasi dan tata kerja.
Rekonstruksi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2624, 'Ketentuan mengenai uraian fungsi yang menangani urusan fasilitasi penyelamatan dan evakuasi, dan fasilitas pelayanan pemenuhan kebutuhan korban dan pengungsi berpedoman pada Peraturan Badan Nasional Penanggulangan Bencana yang mengatur mengenai organisasi dan tata kerja.
Rekonstruksi', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2625, 'perban-2-2021', 22, 'pasal', 'Pasal 21', 'BAB IV ORGANISASI DI LINGKUNGAN DEPUTI BIDANG REHABILITASI DAN REKONSTRUKSI; Bagian Kesatu Uraian Fungsi Direktorat Perencanaan Rehabilitasi dan', 11, 'Direktorat Perencanaan Rehabilitasi dan Rekonstruksi menyelenggarakan uraian fungsi:
a. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan inventarisasi dan analisis kebutuhan bidang fisik serta penyiapan bahan monitoring dan evaluasi di bidang inventarisasi dan analisis kebutuhan fisik,
b. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan inventarisasi dan analisis kebutuhan bidang sosial, ekonomi, sumber daya alam dan lingkungan hidup serta penyiapan bahan monitoring dan evaluasi di bidang sosial, ekonomi, sumber daya alam dan lingkungan hidup, Cc. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan, pelaksanaan pendanaan bidang fisik serta penyiapan bahan monitoring dan evaluasi di bidang perencanaan pendanaan fisik, dan
d. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan, pelaksanaan pendanaan bidang sosial, ekonomi, sumber daya alam dan lingkungan hidup serta penyiapan bahan monitoring dan evaluasi di bidang perencanaan pendanaan sosial, ekonomi, sumber daya alam dan lingkungan hidup.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2625, 'Direktorat Perencanaan Rehabilitasi dan Rekonstruksi menyelenggarakan uraian fungsi:
a. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan inventarisasi dan analisis kebutuhan bidang fisik serta penyiapan bahan monitoring dan evaluasi di bidang inventarisasi dan analisis kebutuhan fisik,
b. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, pelaksanaan inventarisasi dan analisis kebutuhan bidang sosial, ekonomi, sumber daya alam dan lingkungan hidup serta penyiapan bahan monitoring dan evaluasi di bidang sosial, ekonomi, sumber daya alam dan lingkungan hidup, Cc. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan, pelaksanaan pendanaan bidang fisik serta penyiapan bahan monitoring dan evaluasi di bidang perencanaan pendanaan fisik, dan
d. penyiapan koordinasi penyusunan dan pelaksanaan kebijakan teknis, penyusunan Norma, Standar, Prosedur, dan Kriteria, penyusunan perencanaan, pelaksanaan pendanaan bidang sosial, ekonomi, sumber daya alam dan lingkungan hidup serta penyiapan bahan monitoring dan evaluasi di bidang perencanaan pendanaan sosial, ekonomi, sumber daya alam dan lingkungan hidup.', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2021 tentang Uraian Fungsi Organisasi Jabatan Pimpinan Tinggi Pratama dan Tugas Koordinator Jabatan Fungsional di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2626, 'perban-2-2021', 23, 'pasal', 'Pasal 22', 'BAB IV ORGANISASI DI LINGKUNGAN DEPUTI BIDANG REHABILITASI DAN REKONSTRUKSI; Bagian Kesatu Uraian Fungsi Direktorat Perencanaan Rehabilitasi dan', 12, 'Pengelompokan uraian fungsi Direktorat Perencanaan Rehabilitasi dan Rekonstruksi terdiri atas:
