INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2627, 'perban-2-2021', 24, 'pasal', 'Pasal 23', 'BAB IV ORGANISASI DI LINGKUNGAN DEPUTI BIDANG REHABILITASI DAN REKONSTRUKSI; Bagian Kedua Uraian Fungsi Direktorat Pemulihan dan Peningkatan Fisik', 12, 'Ketentuan mengenai uraian fungsi yang menangani urusan inventarisasi dan analisis kebutuhan, dan perencanaan pendanaan berpedoman pada Peraturan Badan Nasional Penanggulangan Bencana yang mengatur mengenai organisasi dan tata kerja.');
