b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana melalui Penyesuaian/Inpassing, 1 1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723):', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2660, 'perban-2-2022', 2, 'mengingat', 'Mengingat', NULL, 1, '(3) Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 88 Tahun 2020 tentang Jabatan Fungsional Penata Penanggulangan Bencana, perlu menyusun tata cara pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana melalui penyesuaian/ inpassing,
Undang-Undang Nomor 5 Tahun 2014 tentang Aparatur Sipil Negara (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 6, Tambahan Lembaran Negara Republik Indonesia Nomor 5494), Peraturan Pemerintah Nomor 11 Tahun 2017 tentang Manajemen Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 63, Tambahan Lembaran Negara Republik Indonesia Nomor 6037) sebagaimana telah diubah dengan Peraturan Pemerintah Nomor 17 Tahun 2020 tentang Perubahan atas Peraturan Pemerintah Nomor 11 Tahun 2017 tentang Manajemen Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2020 Nomor 68, Tambahan Lembaran Negara Republik Indonesia Nomor 6477), Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103), Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461), Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 88 Tahun 2020 tentang Jabatan Fungsional Penata Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1589),');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2660, '(3) Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 88 Tahun 2020 tentang Jabatan Fungsional Penata Penanggulangan Bencana, perlu menyusun tata cara pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana melalui penyesuaian/ inpassing,
Undang-Undang Nomor 5 Tahun 2014 tentang Aparatur Sipil Negara (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 6, Tambahan Lembaran Negara Republik Indonesia Nomor 5494), Peraturan Pemerintah Nomor 11 Tahun 2017 tentang Manajemen Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 63, Tambahan Lembaran Negara Republik Indonesia Nomor 6037) sebagaimana telah diubah dengan Peraturan Pemerintah Nomor 17 Tahun 2020 tentang Perubahan atas Peraturan Pemerintah Nomor 11 Tahun 2017 tentang Manajemen Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2020 Nomor 68, Tambahan Lembaran Negara Republik Indonesia Nomor 6477), Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103), Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461), Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 88 Tahun 2020 tentang Jabatan Fungsional Penata Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1589),', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2661, 'perban-2-2022', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENGANGKATAN DALAM JABATAN FUNGSIONAL PENATA PENANGGULANGAN BENCANA MELALUI PENYESUAIAN / INPASSING.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2661, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENGANGKATAN DALAM JABATAN FUNGSIONAL PENATA PENANGGULANGAN BENCANA MELALUI PENYESUAIAN / INPASSING.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2662, 'perban-2-2022', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM', 3, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Pegawai Negeri Sipil yang selanjutnya disingkat PNS adalah warga negara Indonesia yang memenuhi syarat tertentu, diangkat sebagai pegawai aparatur sipil negara secara tetap oleh pejabat pembina kepegawaian untuk menduduki jabatan pemerintahan.
2. Pejabat Pembina Kepegawaian yang selanjutnya disingkat PPK adalah pejabat yang mempunyai kewenangan menetapkan pengangkatan, pemindahan, dan pemberhentian PNS dan pembinaan manajemen aparatur sipil negara di instansi pemerintah sesuai dengan ketentuan peraturan perundang-undangan.
3. Pejabat yang Berwenang yang selanjutnya disebut PyB adalah pejabat yang mempunyai kewenangan melaksanakan proses pengangkatan, pemindahan, dan pemberhentian PNS sesuai dengan ketentuan peraturan perundang-undangan.
4. Jabatan Fungsional Penata Penanggulangan Bencana yang selanjutnya disingkat JF Penata Penanggulangan Bencana adalah jabatan yang mempunyai ruang lingkup tugas, tanggung jawab, dan wewenang untuk melaksanakan penyelenggaraan — penanggulangan bencana.
5. Pejabat Fungsional Penata Penanggulangan Bencana
10. 11.
12. yang selanjutnya disebut Penata Penanggulangan Bencana adalah PNS yang diberi tugas, tanggung jawab, dan wewenang secara penuh oleh Pejabat yang Berwenang melaksanakan penyelenggaraan penanggulangan bencana.
Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat dan rehabilitasi.
Penyesuaian/Inpassing JF Penata Penanggulangan Bencana adalah pengangkatan ke dalam JF Penata Penanggulangan Bencana dengan persyaratan tertentu bagi PNS yang telah dan/atau masih melaksanakan tugas di bidang JF Penata Penanggulangan Bencana guna memenuhi kebutuhan organisasi sesuai dengan ketentuan peraturan perundang-undangan dalam jangka waktu tertentu.
Kebutuhan JF Penata Penanggulangan Bencana adalah jumlah dan susunan JF Penata Penanggulangan Bencana dalam Jenjang jabatan tertentu yang diperlukan oleh instansi pusat dan instansi daerah untuk melaksanakan tugas pokok dan fungsinya dalam jangka waktu tertentu.
Instansi Pembina JF Penata Penanggulangan Bencana adalah Badan Nasional Penanggulangan Bencana.
Instansi Pengguna adalah instansi pusat dan instansi daerah yang mempunyai tugas di bidang penanggulangan bencana.
Angka Kredit adalah satuan nilai dari uraian kegiatan yang ditetapkan dalam butir kegiatan dan/atau akumulasi nilai dari butir kegiatan yang harus dicapai oleh Penata Penanggulangan Bencana dalam rangka pembinaan karier yang bersangkutan.
Angka Kredit Kumulatif adalah akumulasi nilai Angka Kredit minimal yang harus dicapai oleh Penata Penanggulangan Bencana sebagai salah satu syarat kenaikan pangkat dan/atau jabatan.
13. Tim Penilai Angka Kredit JF Penata Penanggulangan Bencana yang selanjutnya disebut Tim Penilai adalah tim yang dibentuk dan ditetapkan oleh pejabat yang memiliki kewenangan menetapkan Angka Kredit dan bertugas mengevaluasi keselarasan hasil kerja dengan tugas yang disusun dalam sasaran kerja pegawai serta menilai capaian kinerja Penata Penanggulangan Bencana dalam bentuk Angka Kredit.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2662, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Pegawai Negeri Sipil yang selanjutnya disingkat PNS adalah warga negara Indonesia yang memenuhi syarat tertentu, diangkat sebagai pegawai aparatur sipil negara secara tetap oleh pejabat pembina kepegawaian untuk menduduki jabatan pemerintahan.
2. Pejabat Pembina Kepegawaian yang selanjutnya disingkat PPK adalah pejabat yang mempunyai kewenangan menetapkan pengangkatan, pemindahan, dan pemberhentian PNS dan pembinaan manajemen aparatur sipil negara di instansi pemerintah sesuai dengan ketentuan peraturan perundang-undangan.
3. Pejabat yang Berwenang yang selanjutnya disebut PyB adalah pejabat yang mempunyai kewenangan melaksanakan proses pengangkatan, pemindahan, dan pemberhentian PNS sesuai dengan ketentuan peraturan perundang-undangan.
4. Jabatan Fungsional Penata Penanggulangan Bencana yang selanjutnya disingkat JF Penata Penanggulangan Bencana adalah jabatan yang mempunyai ruang lingkup tugas, tanggung jawab, dan wewenang untuk melaksanakan penyelenggaraan — penanggulangan bencana.
5. Pejabat Fungsional Penata Penanggulangan Bencana
10. 11.
12. yang selanjutnya disebut Penata Penanggulangan Bencana adalah PNS yang diberi tugas, tanggung jawab, dan wewenang secara penuh oleh Pejabat yang Berwenang melaksanakan penyelenggaraan penanggulangan bencana.
Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat dan rehabilitasi.
Penyesuaian/Inpassing JF Penata Penanggulangan Bencana adalah pengangkatan ke dalam JF Penata Penanggulangan Bencana dengan persyaratan tertentu bagi PNS yang telah dan/atau masih melaksanakan tugas di bidang JF Penata Penanggulangan Bencana guna memenuhi kebutuhan organisasi sesuai dengan ketentuan peraturan perundang-undangan dalam jangka waktu tertentu.
Kebutuhan JF Penata Penanggulangan Bencana adalah jumlah dan susunan JF Penata Penanggulangan Bencana dalam Jenjang jabatan tertentu yang diperlukan oleh instansi pusat dan instansi daerah untuk melaksanakan tugas pokok dan fungsinya dalam jangka waktu tertentu.
Instansi Pembina JF Penata Penanggulangan Bencana adalah Badan Nasional Penanggulangan Bencana.
Instansi Pengguna adalah instansi pusat dan instansi daerah yang mempunyai tugas di bidang penanggulangan bencana.
Angka Kredit adalah satuan nilai dari uraian kegiatan yang ditetapkan dalam butir kegiatan dan/atau akumulasi nilai dari butir kegiatan yang harus dicapai oleh Penata Penanggulangan Bencana dalam rangka pembinaan karier yang bersangkutan.
Angka Kredit Kumulatif adalah akumulasi nilai Angka Kredit minimal yang harus dicapai oleh Penata Penanggulangan Bencana sebagai salah satu syarat kenaikan pangkat dan/atau jabatan.
13. Tim Penilai Angka Kredit JF Penata Penanggulangan Bencana yang selanjutnya disebut Tim Penilai adalah tim yang dibentuk dan ditetapkan oleh pejabat yang memiliki kewenangan menetapkan Angka Kredit dan bertugas mengevaluasi keselarasan hasil kerja dengan tugas yang disusun dalam sasaran kerja pegawai serta menilai capaian kinerja Penata Penanggulangan Bencana dalam bentuk Angka Kredit.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2663, 'perban-2-2022', 5, 'pasal', 'Pasal 2', 'BAB I KETENTUAN UMUM', 5, 'Peraturan Badan ini disusun sebagai pedoman dalam melaksanakan pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/ inpassing agar berjalan secara efektif, teratur, dan profesional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2663, 'Peraturan Badan ini disusun sebagai pedoman dalam melaksanakan pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/ inpassing agar berjalan secara efektif, teratur, dan profesional.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2664, 'perban-2-2022', 6, 'pasal', 'Pasal 3', 'BAB II KRITERIA DAN PERSYARATAN PENYESUAIAN/ INPASSING JF PENATA PENANGGULANGAN BENCANA', 5, 'Lingkup pengaturan Peraturan Badan ini meliputi:
a. kriteria dan persyaratan Penyesuaian/Inpassing JF Penata Penanggulangan Bencana,
b. prosedur Penyesuaian/Inpassing JF Penata Penanggulangan Bencana, dan
c. pengangkatan dalam JF Penata Penanggulangan Bencana melalui penyesuaian/ inpassing.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2664, 'Lingkup pengaturan Peraturan Badan ini meliputi:
a. kriteria dan persyaratan Penyesuaian/Inpassing JF Penata Penanggulangan Bencana,
b. prosedur Penyesuaian/Inpassing JF Penata Penanggulangan Bencana, dan
c. pengangkatan dalam JF Penata Penanggulangan Bencana melalui penyesuaian/ inpassing.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2665, 'perban-2-2022', 7, 'pasal', 'Pasal 4', 'BAB II KRITERIA DAN PERSYARATAN PENYESUAIAN/ INPASSING JF PENATA PENANGGULANGAN BENCANA', 5, 'Pengangkatan dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing ditujukan bagi PNS yang pernah memiliki pengalaman dan/atau masih menjalankan tugas di bidang JF Penata Penanggulangan Bencana yang akan diduduki berdasarkan keputusan PPK.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2665, 'Pengangkatan dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing ditujukan bagi PNS yang pernah memiliki pengalaman dan/atau masih menjalankan tugas di bidang JF Penata Penanggulangan Bencana yang akan diduduki berdasarkan keputusan PPK.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2666, 'perban-2-2022', 8, 'pasal', 'Pasal 5', 'BAB II KRITERIA DAN PERSYARATAN PENYESUAIAN/ INPASSING JF PENATA PENANGGULANGAN BENCANA', 6, '(1) Instansi Pengguna yang memiliki kebutuhan atas JF Penata Penanggulangan Bencana, dapat mengusulkan PNS untuk mengikuti proses penyesuaian/inpassing.
(2) Untuk menjamin keseimbangan antara beban kerja dan jumlah PNS yang akan disesuaikan, pelaksanaan penyesuaian/inpassing sebagaimana dimaksud pada ayat (1) harus mempertimbangkan kebutuhan organisasi yang ditentukan melalui penghitungan kebutuhan JF Penata Penanggulangan Bencana.
(3) Instansi Pengguna menyusun penghitungan kebutuhan JF Penata Penanggulangan Bencana sebagaimana dimaksud pada ayat (1) sesuai dengan Peraturan Badan Nasional Penanggulangan Bencana mengenai pedoman penghitungan kebutuhan JF Penata Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2666, '(1) Instansi Pengguna yang memiliki kebutuhan atas JF Penata Penanggulangan Bencana, dapat mengusulkan PNS untuk mengikuti proses penyesuaian/inpassing.
(2) Untuk menjamin keseimbangan antara beban kerja dan jumlah PNS yang akan disesuaikan, pelaksanaan penyesuaian/inpassing sebagaimana dimaksud pada ayat (1) harus mempertimbangkan kebutuhan organisasi yang ditentukan melalui penghitungan kebutuhan JF Penata Penanggulangan Bencana.
(3) Instansi Pengguna menyusun penghitungan kebutuhan JF Penata Penanggulangan Bencana sebagaimana dimaksud pada ayat (1) sesuai dengan Peraturan Badan Nasional Penanggulangan Bencana mengenai pedoman penghitungan kebutuhan JF Penata Penanggulangan Bencana.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2667, 'perban-2-2022', 9, 'pasal', 'Pasal 6', 'BAB II KRITERIA DAN PERSYARATAN PENYESUAIAN/ INPASSING JF PENATA PENANGGULANGAN BENCANA', 6, 'Pelaksanaan pengangkatan dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing sebagaimana dimaksud dalam Pasal 4 harus didasarkan pada kebutuhan JF Penata Penanggulangan Bencana yang telah ditetapkan oleh menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2667, 'Pelaksanaan pengangkatan dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing sebagaimana dimaksud dalam Pasal 4 harus didasarkan pada kebutuhan JF Penata Penanggulangan Bencana yang telah ditetapkan oleh menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2668, 'perban-2-2022', 10, 'pasal', 'Pasal 7', 'BAB III PROSEDUR PENYESUAIAN/ INPASSING JF PENATA PENANGGULANGAN BENCANA', 6, '(1) PNS yang diangkat dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing harus memenuhi syarat sebagai berikut:
a. berstatus PNS,
b. memiliki integritas dan moralitas yang baik,
c. sehat jasmani dan rohani,
d. berijazah paling rendah sarjana atau diploma empat,
e. memiliki pengalaman dalam pelaksanaan tugas di bidang Penyelenggaraan Penanggulangan Bencana paling singkat 2 (dua) tahun,
f. nilai prestasi kerja paling rendah bernilai baik dalam 2 (dua) tahun terakhir,
g. PNS yang dapat mengikuti penyesuaian/ inpassing berusia paling tinggi:
1. SS (lima puluh lima) tahun bagi pejabat pelaksana,
2. 56 (lima puluh enam) tahun bagi pejabat administrator dan pejabat pengawas yang akan menduduki JF Penata Penanggulangan Bencana Ahli Pertama dan Ahli Muda,
3. S7 (lima puluh tujuh) tahun bagi pejabat administrator yang akan menduduki JF Penata Penanggulangan Bencana Ahli Madya, dan
4. 59 (lima puluh sembilan) tahun bagi pejabat pimpinan tinggi,
h. tidak sedang dalam proses atau menjalani hukuman disiplin tingkat sedang/ berat, dan/atau tidak sedang dalam proses pemeriksaan dengan ancaman hukuman disiplin tingkat sedang/ berat,
i. tidak sedang menjalankan tugas belajar lebih dari 6 (enam) bulan pada saat penyesuaian/inpassing, dan
j. tidak sedang menjalankan cuti di luar tanggungan negara pada saat penyesuaian/ inpassing.
(2) Selain persyaratan sebagaimana dimaksud pada ayat
(1) Instansi Pengguna menyampaikan kebutuhan JF Penata Penanggulangan Bencana kepada Badan Nasional Penanggulangan Bencana untuk mendapatkan rekomendasi.
(3) Rekomendasi sebagaimana dimaksud pada ayat (2) menjadi dasar bagi PPK dalam mengusulkan kebutuhan JF Penata Penanggulangan Bencana yang diangkat melalui pengangkatan/ inpassing.
(4) Kebutuhan JF Penata Penanggulangan Bencana sebagaimana dimaksud pada ayat (3) diusulkan oleh PPK kepada menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.
(5) Kebutuhan JF Penata Penanggulangan Bencana sebagaimana dimaksud pada ayat (4) ditetapkan oleh menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2668, '(1) PNS yang diangkat dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing harus memenuhi syarat sebagai berikut:
a. berstatus PNS,
b. memiliki integritas dan moralitas yang baik,
c. sehat jasmani dan rohani,
d. berijazah paling rendah sarjana atau diploma empat,
e. memiliki pengalaman dalam pelaksanaan tugas di bidang Penyelenggaraan Penanggulangan Bencana paling singkat 2 (dua) tahun,
f. nilai prestasi kerja paling rendah bernilai baik dalam 2 (dua) tahun terakhir,
g. PNS yang dapat mengikuti penyesuaian/ inpassing berusia paling tinggi:
1. SS (lima puluh lima) tahun bagi pejabat pelaksana,
2. 56 (lima puluh enam) tahun bagi pejabat administrator dan pejabat pengawas yang akan menduduki JF Penata Penanggulangan Bencana Ahli Pertama dan Ahli Muda,
3. S7 (lima puluh tujuh) tahun bagi pejabat administrator yang akan menduduki JF Penata Penanggulangan Bencana Ahli Madya, dan
4. 59 (lima puluh sembilan) tahun bagi pejabat pimpinan tinggi,
h. tidak sedang dalam proses atau menjalani hukuman disiplin tingkat sedang/ berat, dan/atau tidak sedang dalam proses pemeriksaan dengan ancaman hukuman disiplin tingkat sedang/ berat,
i. tidak sedang menjalankan tugas belajar lebih dari 6 (enam) bulan pada saat penyesuaian/inpassing, dan
j. tidak sedang menjalankan cuti di luar tanggungan negara pada saat penyesuaian/ inpassing.
(2) Selain persyaratan sebagaimana dimaksud pada ayat
(1) Instansi Pengguna menyampaikan kebutuhan JF Penata Penanggulangan Bencana kepada Badan Nasional Penanggulangan Bencana untuk mendapatkan rekomendasi.
(3) Rekomendasi sebagaimana dimaksud pada ayat (2) menjadi dasar bagi PPK dalam mengusulkan kebutuhan JF Penata Penanggulangan Bencana yang diangkat melalui pengangkatan/ inpassing.
(4) Kebutuhan JF Penata Penanggulangan Bencana sebagaimana dimaksud pada ayat (3) diusulkan oleh PPK kepada menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.
(5) Kebutuhan JF Penata Penanggulangan Bencana sebagaimana dimaksud pada ayat (4) ditetapkan oleh menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2669, 'perban-2-2022', 11, 'pasal', 'Pasal 8', 'BAB III PROSEDUR PENYESUAIAN/ INPASSING JF PENATA PENANGGULANGAN BENCANA; Bagian Kesatu Pengusulan oleh Instansi Pengguna', 8, 'Prosedur Penyesuaian/ Inpassing JF Penata Penanggulangan Bencana terdiri atas:
a. pengusulan oleh Instansi Pengguna, dan
b. seleksi administrasi dan portofolio.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2669, 'Prosedur Penyesuaian/ Inpassing JF Penata Penanggulangan Bencana terdiri atas:
a. pengusulan oleh Instansi Pengguna, dan
b. seleksi administrasi dan portofolio.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2670, 'perban-2-2022', 12, 'pasal', 'Pasal 9', 'BAB III PROSEDUR PENYESUAIAN/ INPASSING JF PENATA PENANGGULANGAN BENCANA; Bagian Kedua Seleksi Administrasi dan Portofolio', 8, '(1) PNS yang telah memenuhi persyaratan sebagaimana dimaksud dalam Pasal 7 dapat mengajukan permohonan usulan pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing kepada PPK melalui PyB secara hierarki.
(2) Permohonan sebagaimana dimaksud pada ayat (1) disampaikan oleh Instansi Pengguna kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana.
(3) Permohonan sebagaimana dimaksud pada ayat (2) dilengkapi dengan surat penetapan kebutuhan JF Penata Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 7 ayat (2).
(4) Selain surat penetapan kebutuhan sebagaimana dimaksud pada ayat (3), permohonan harus dilengkapi dengan dokumen berupa:
a. salinan surat keputusan kenaikan pangkat terakhir,
b. salinan surat keputusan pengangkatan dalam jabatan terakhir, C. surat keterangan dari pimpinan unit kerja yang menyatakan bahwa tidak sedang menjalani hukuman disiplin tingkat sedang maupun berat,
d. surat keterangan sehat jasmani dan rohani dari dokter,
e. salinan ijazah pendidikan terakhir sesuai kualifikasi,
f. salinan penilaian kinerja 2 (dua) tahun terakhir,
g. daftar riwayat hidup,
h. surat keterangan yang memuat pengalaman mengenai pelaksanaan tugas di bidang Penyelenggaraan Penanggulangan Bencana secara kumulatif paling sedikit selama 2 (dua) tahun dan ditandatangani oleh PyB,
i. surat pernyataan yang menyatakan:
1. bersedia diangkat menjadi JF Penata Penanggulangan Bencana,
2. bersedia mengikuti pendidikan dan pelatihan, dan
3. kesediaan untuk melaksanakan kegiatan di bidang JF Penata Penanggulangan Bencana secara aktif, dan j- surat keterangan tidak sedang menjalankan tugas belajar dan tidak sedang menjalankan cuti di luar tanggungan negara dari pejabat pimpinan tinggi pratama.
(5) Format surat permohonan sebagaimana dimaksud pada ayat (2) dan format dokumen persyaratan administrasi sebagaimana dimaksud pada ayat (4) huruf c, huruf g, huruf h, huruf i, dan huruf j dibuat sesuai dengan format sebagaimana tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2670, '(1) PNS yang telah memenuhi persyaratan sebagaimana dimaksud dalam Pasal 7 dapat mengajukan permohonan usulan pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing kepada PPK melalui PyB secara hierarki.
(2) Permohonan sebagaimana dimaksud pada ayat (1) disampaikan oleh Instansi Pengguna kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana.
(3) Permohonan sebagaimana dimaksud pada ayat (2) dilengkapi dengan surat penetapan kebutuhan JF Penata Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 7 ayat (2).
(4) Selain surat penetapan kebutuhan sebagaimana dimaksud pada ayat (3), permohonan harus dilengkapi dengan dokumen berupa:
a. salinan surat keputusan kenaikan pangkat terakhir,
b. salinan surat keputusan pengangkatan dalam jabatan terakhir, C. surat keterangan dari pimpinan unit kerja yang menyatakan bahwa tidak sedang menjalani hukuman disiplin tingkat sedang maupun berat,
d. surat keterangan sehat jasmani dan rohani dari dokter,
e. salinan ijazah pendidikan terakhir sesuai kualifikasi,
f. salinan penilaian kinerja 2 (dua) tahun terakhir,
g. daftar riwayat hidup,
h. surat keterangan yang memuat pengalaman mengenai pelaksanaan tugas di bidang Penyelenggaraan Penanggulangan Bencana secara kumulatif paling sedikit selama 2 (dua) tahun dan ditandatangani oleh PyB,
i. surat pernyataan yang menyatakan:
1. bersedia diangkat menjadi JF Penata Penanggulangan Bencana,
2. bersedia mengikuti pendidikan dan pelatihan, dan
3. kesediaan untuk melaksanakan kegiatan di bidang JF Penata Penanggulangan Bencana secara aktif, dan j- surat keterangan tidak sedang menjalankan tugas belajar dan tidak sedang menjalankan cuti di luar tanggungan negara dari pejabat pimpinan tinggi pratama.
(5) Format surat permohonan sebagaimana dimaksud pada ayat (2) dan format dokumen persyaratan administrasi sebagaimana dimaksud pada ayat (4) huruf c, huruf g, huruf h, huruf i, dan huruf j dibuat sesuai dengan format sebagaimana tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2671, 'perban-2-2022', 13, 'pasal', 'Pasal 10', 'BAB III PROSEDUR PENYESUAIAN/ INPASSING JF PENATA PENANGGULANGAN BENCANA; Bagian Kedua Seleksi Administrasi dan Portofolio', 10, '(1) Pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing dilakukan dengan seleksi administrasi dan portofolio.
(2) Seleksi administrasi dan portofolio sebagaimana dimaksud pada ayat (1) dilakukan oleh tim seleksi.
(3) Tim seleksi sebagaimana dimaksud pada ayat (2) ditetapkan oleh Sekretaris Utama Badan Nasional Penanggulangan Bencana.
(4) Tim seleksi sebagaimana dimaksud pada ayat (3) disesuaikan dengan kebutuhan penyelenggaraan seleksi administrasi dan portofolio, dengan susunan sebagai berikut:
a. ketua,
b. sekretaris: dan
c. anggota
(5) Anggota sebagaimana dimaksud pada ayat (4) huruf c berjumlah paling sedikit 3 (tiga) orang.
(6) Tim seleksi sebagaimana dimaksud pada ayat (4) berjumlah ganjil.
(7) Tim seleksi sebagaimana dimaksud pada ayat (4) terdiri dari pejabat dan/atau pegawai yang mempunyai kemampuan untuk melakukan penilaian kinerja Penata Penanggulangan Bencana.
(8) Tim seleksi dapat melibatkan pihak dari luar Instansi Pembina JF Penata Penanggulangan Bencana.
(9) Proses seleksi administrasi dan portofolio oleh tim seleksi sebagaimana dimaksud pada ayat (1) dilakukan dalam jangka waktu paling lama 30 (tiga puluh) hari kerja terhitung sejak tanggal 23 September 2022.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2671, '(1) Pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing dilakukan dengan seleksi administrasi dan portofolio.
(2) Seleksi administrasi dan portofolio sebagaimana dimaksud pada ayat (1) dilakukan oleh tim seleksi.
(3) Tim seleksi sebagaimana dimaksud pada ayat (2) ditetapkan oleh Sekretaris Utama Badan Nasional Penanggulangan Bencana.
(4) Tim seleksi sebagaimana dimaksud pada ayat (3) disesuaikan dengan kebutuhan penyelenggaraan seleksi administrasi dan portofolio, dengan susunan sebagai berikut:
a. ketua,
b. sekretaris: dan
c. anggota
(5) Anggota sebagaimana dimaksud pada ayat (4) huruf c berjumlah paling sedikit 3 (tiga) orang.
(6) Tim seleksi sebagaimana dimaksud pada ayat (4) berjumlah ganjil.
(7) Tim seleksi sebagaimana dimaksud pada ayat (4) terdiri dari pejabat dan/atau pegawai yang mempunyai kemampuan untuk melakukan penilaian kinerja Penata Penanggulangan Bencana.
(8) Tim seleksi dapat melibatkan pihak dari luar Instansi Pembina JF Penata Penanggulangan Bencana.
(9) Proses seleksi administrasi dan portofolio oleh tim seleksi sebagaimana dimaksud pada ayat (1) dilakukan dalam jangka waktu paling lama 30 (tiga puluh) hari kerja terhitung sejak tanggal 23 September 2022.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2672, 'perban-2-2022', 14, 'pasal', 'Pasal 11', 'BAB III PROSEDUR PENYESUAIAN/ INPASSING JF PENATA PENANGGULANGAN BENCANA; Bagian Kedua Seleksi Administrasi dan Portofolio', 11, 'Tim seleksi administrasi dan portofolio mempunyai tugas:
a. melakukan verifikasi kesesuaian dokumen administrasi persyaratan pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing yang diajukan oleh Instansi Pengguna,
b. melakukan penelaahan portofolio terhadap PNS yang akan dilakukan pengangkatan dalam JF Penata Penanggulangan Bencana melalui penyesuaian/ inpassing, Cc. memberikan penilaian dengan melakukan pemeringkatan terhadap kualifikasi kompetensi dan kinerja dari persyaratan administrasi dan portofolio, dan
d. melaporkan seluruh proses tahapan seleksi administrasi dan portofolio terhadap PNS yang mengikuti Penyesuaian/ Inpassing JF Penata Penanggulangan Bencana kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2672, 'Tim seleksi administrasi dan portofolio mempunyai tugas:
a. melakukan verifikasi kesesuaian dokumen administrasi persyaratan pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing yang diajukan oleh Instansi Pengguna,
b. melakukan penelaahan portofolio terhadap PNS yang akan dilakukan pengangkatan dalam JF Penata Penanggulangan Bencana melalui penyesuaian/ inpassing, Cc. memberikan penilaian dengan melakukan pemeringkatan terhadap kualifikasi kompetensi dan kinerja dari persyaratan administrasi dan portofolio, dan
d. melaporkan seluruh proses tahapan seleksi administrasi dan portofolio terhadap PNS yang mengikuti Penyesuaian/ Inpassing JF Penata Penanggulangan Bencana kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2673, 'perban-2-2022', 15, 'pasal', 'Pasal 12', 'BAB IV PENGANGKATAN DALAM JF PENATA PENANGGULANGAN BENCANA MELALUI PENYESUAIAN/ INPASSING; Bagian Kesatu Penilaian dan Penetapan Angka Kredit', 11, '(1) Tim seleksi sebagaimana dimaksud dalam Pasal 10 ayat
(2) menyampaikan hasil seleksi kepada pejabat pimpinan tinggi pratama yang membidangi pembinaan jabatan fungsional.
(2) Hasil seleksi sebagaimana dimaksud pada ayat (1) disampaikan kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana.
(3) Hasil seleksi sebagaimana dimaksud pada ayat (2) disampaikan oleh Sekretaris Utama Badan Nasional Penanggulangan Bencana kepada Instansi Pengguna yang memuat informasi sebagai berikut:
a. PNS dinyatakan lolos seleksi apabila memenuhi persyaratan administrasi dan portofolio, atau 12
b. PNS dinyatakan tidak lolos seleksi apabila tidak memenuhi persyaratan administrasi dan portofolio.
(4) Terhadap PNS yang lolos seleksi sebagaimana dimaksud pada ayat (3) huruf a diberikan rekomendasi untuk dapat digunakan sebagai syarat dalam pengangkatan JF Penata Penanggulangan Bencana melalui penyesuaian/ inpassing.
(5) Format rekomendasi sebagaimana dimaksud pada ayat
(4) sebagaimana tercantum dalam Lampiran II yang merupakan bagian yang tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2673, '(1) Tim seleksi sebagaimana dimaksud dalam Pasal 10 ayat
(2) menyampaikan hasil seleksi kepada pejabat pimpinan tinggi pratama yang membidangi pembinaan jabatan fungsional.
(2) Hasil seleksi sebagaimana dimaksud pada ayat (1) disampaikan kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana.
(3) Hasil seleksi sebagaimana dimaksud pada ayat (2) disampaikan oleh Sekretaris Utama Badan Nasional Penanggulangan Bencana kepada Instansi Pengguna yang memuat informasi sebagai berikut:
a. PNS dinyatakan lolos seleksi apabila memenuhi persyaratan administrasi dan portofolio, atau 12
b. PNS dinyatakan tidak lolos seleksi apabila tidak memenuhi persyaratan administrasi dan portofolio.
(4) Terhadap PNS yang lolos seleksi sebagaimana dimaksud pada ayat (3) huruf a diberikan rekomendasi untuk dapat digunakan sebagai syarat dalam pengangkatan JF Penata Penanggulangan Bencana melalui penyesuaian/ inpassing.
(5) Format rekomendasi sebagaimana dimaksud pada ayat
(4) sebagaimana tercantum dalam Lampiran II yang merupakan bagian yang tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2674, 'perban-2-2022', 16, 'pasal', 'Pasal 13', 'BAB IV PENGANGKATAN DALAM JF PENATA PENANGGULANGAN BENCANA MELALUI PENYESUAIAN/ INPASSING; Bagian Kedua Mekanisme Pengangkatan Dalam JF Penata', 12, '(1) Jenjang JF Penata Penanggulangan Bencana ditetapkan setelah PNS memenuhi persyaratan sebagaimana dimaksud dalam Pasal 12 ayat (4) dan diberikan Angka Kredit sesuai dengan Angka Kredit Kumulatif untuk Penyesuaian/Inpassing JF Penata Penanggulangan Bencana sebagaimana tercantum dalam Lampiran III yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(2) Angka Kredit sebagaimana dimaksud pada ayat (1) sesuai dengan pendidikan, masa kerja dalam pangkat dan golongan ruang terakhir.
(3) Angka Kredit sebagaimana dimaksud pada ayat (2) hanya berlaku 1 (satu) kali pada saat Penyesuaian/Inpassing JF Penata Penanggulangan Bencana.
(4) Penetapan Angka Kredit sebagaimana dimaksud ayat
(1) sebagaimana tercantum dalam Lampiran IV yang merupakan bagian yang tidak terpisahkan dari Peraturan Badan ini.
Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2674, '(1) Jenjang JF Penata Penanggulangan Bencana ditetapkan setelah PNS memenuhi persyaratan sebagaimana dimaksud dalam Pasal 12 ayat (4) dan diberikan Angka Kredit sesuai dengan Angka Kredit Kumulatif untuk Penyesuaian/Inpassing JF Penata Penanggulangan Bencana sebagaimana tercantum dalam Lampiran III yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(2) Angka Kredit sebagaimana dimaksud pada ayat (1) sesuai dengan pendidikan, masa kerja dalam pangkat dan golongan ruang terakhir.
(3) Angka Kredit sebagaimana dimaksud pada ayat (2) hanya berlaku 1 (satu) kali pada saat Penyesuaian/Inpassing JF Penata Penanggulangan Bencana.
(4) Penetapan Angka Kredit sebagaimana dimaksud ayat
(1) sebagaimana tercantum dalam Lampiran IV yang merupakan bagian yang tidak terpisahkan dari Peraturan Badan ini.
Penanggulangan Bencana', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2675, 'perban-2-2022', 17, 'pasal', 'Pasal 14', 'BAB V PELANTIKAN DAN PENGAMBILAN SUMPAH', 13, '(1) PNS yang telah mendapatkan rekomendasi dari Instansi Pembina JF Penata Penanggulangan Bencana diangkat dalam JF Penata Penanggulangan Bencana melalui penyesuaian/ inpassing.
(2) Pengangkatan dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing ditetapkan dengan keputusan yang ditandatangani oleh PPK dan dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
(3) Pengangkatan dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing sebagamana dimaksud pada ayat (1) disampaikan kepada Penata Penanggulangan Bencana yang bersangkutan dengan tembusan disampaikan kepada:
a. Kepala Badan Nasional Penanggulangan Bencana,
b. Kepala Badan Kepegawaian Negara,
c. Kepala Kantor Pelayanan Perbendaharaan yang bersangkutan,
d. pimpinan unit kerja yang bersangkutan, dan
e. pejabat lain yang dianggap perlu.
(4) Keputusan sebagaimana dimaksud pada ayat (2) sesuai format sebagaimana tercantum dalam Lampiran V yang merupakan bagian yang tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2675, '(1) PNS yang telah mendapatkan rekomendasi dari Instansi Pembina JF Penata Penanggulangan Bencana diangkat dalam JF Penata Penanggulangan Bencana melalui penyesuaian/ inpassing.
(2) Pengangkatan dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing ditetapkan dengan keputusan yang ditandatangani oleh PPK dan dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
(3) Pengangkatan dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing sebagamana dimaksud pada ayat (1) disampaikan kepada Penata Penanggulangan Bencana yang bersangkutan dengan tembusan disampaikan kepada:
a. Kepala Badan Nasional Penanggulangan Bencana,
b. Kepala Badan Kepegawaian Negara,
c. Kepala Kantor Pelayanan Perbendaharaan yang bersangkutan,
d. pimpinan unit kerja yang bersangkutan, dan
e. pejabat lain yang dianggap perlu.
(4) Keputusan sebagaimana dimaksud pada ayat (2) sesuai format sebagaimana tercantum dalam Lampiran V yang merupakan bagian yang tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2676, 'perban-2-2022', 18, 'pasal', 'Pasal 15', 'BAB VI PELAPORAN', 14, '(1) Setiap PNS yang diangkat menjadi Penata Penanggulangan Bencana melalui penyesuaian/inpassing wajib dilantik dan diambil sumpah/janji menurut agama atau kepercayaannya kepada Tuhan Yang Maha Esa.
(2) Pelantikan dan pengambilan sumpah /janji sebagaimana dimaksud pada ayat (1) sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2676, '(1) Setiap PNS yang diangkat menjadi Penata Penanggulangan Bencana melalui penyesuaian/inpassing wajib dilantik dan diambil sumpah/janji menurut agama atau kepercayaannya kepada Tuhan Yang Maha Esa.
(2) Pelantikan dan pengambilan sumpah /janji sebagaimana dimaksud pada ayat (1) sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2677, 'perban-2-2022', 19, 'pasal', 'Pasal 16', 'BAB VII KETENTUAN LAIN-LAIN', 14, '(1) Instansi Pengguna wajib melaporkan hasil pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing kepada Kepala Badan Nasional Penanggulangan Bencana sesuai dengan format laporan sebagaimana tercantum dalam Lampiran VI yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(2) Laporan hasil pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing ditembuskan kepada:
a. menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara, dan
b. Kepala Badan Kepegawaian Negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2677, '(1) Instansi Pengguna wajib melaporkan hasil pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing kepada Kepala Badan Nasional Penanggulangan Bencana sesuai dengan format laporan sebagaimana tercantum dalam Lampiran VI yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(2) Laporan hasil pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing ditembuskan kepada:
a. menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara, dan
b. Kepala Badan Kepegawaian Negara.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2678, 'perban-2-2022', 20, 'pasal', 'Pasal 17', 'BAB VIII KETENTUAN PENUTUP', 15, '(1) Dalam hal PNS yang dinyatakan lolos seleksi sampai dengan periode pengangkatan ke dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing mengalami:
a. kenaikan pangkat,
b. penyesuaian pendidikan, dan/atau Cc. penambahan masa kerja, yang tidak mempengaruhi kenaikan jenjang jabatan namun mempengaruhi kenaikan angka kredit, dapat melakukan permohonan penyesuaian rekomendasi pengangkatan dalam JF Penata Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 12 ayat
(4) sampai dengan batas waktu pelaksanaan penyesuaian/ inpassing.
(2) Dalam hal PNS yang dinyatakan lolos seleksi sampai dengan periode pengangkatan ke dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing mengalami kenaikan pangkat yang mempengaruhi kenaikan jenjang jabatan, tidak dapat melakukan permohonan penyesuaian rekomendasi pengangkatan dalam JF Penata Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 12 ayat (4) dan wajib mengikuti seleksi penyesuaian/inpassing ulang.
(3) Dalam hal PNS sebagaimana dimaksud pada ayat (2) tidak mengikuti seleksi penyesuaian/inpassing ulang dan tetap ingin diangkat ke dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing, rekomendasi yang diberikan menggunakan kepangkatan, pendidikan, atau masa kerja yang ditetapkan berdasarkan hasil seleksi penyesuaian/inpassing yang pertama tetap berlaku dengan syarat kenaikan pangkat terbarunya dibatalkan Tie - terlebih dahulu dan dikembalikan ke pangkat sebelumnya.
(4) Permohonan penyesuaian rekomendasi sebagaimana dimaksud pada ayat (1) disampaikan oleh Instansi Pengguna kepada Instansi Pembina.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2678, '(1) Dalam hal PNS yang dinyatakan lolos seleksi sampai dengan periode pengangkatan ke dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing mengalami:
a. kenaikan pangkat,
b. penyesuaian pendidikan, dan/atau Cc. penambahan masa kerja, yang tidak mempengaruhi kenaikan jenjang jabatan namun mempengaruhi kenaikan angka kredit, dapat melakukan permohonan penyesuaian rekomendasi pengangkatan dalam JF Penata Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 12 ayat
(4) sampai dengan batas waktu pelaksanaan penyesuaian/ inpassing.
(2) Dalam hal PNS yang dinyatakan lolos seleksi sampai dengan periode pengangkatan ke dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing mengalami kenaikan pangkat yang mempengaruhi kenaikan jenjang jabatan, tidak dapat melakukan permohonan penyesuaian rekomendasi pengangkatan dalam JF Penata Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 12 ayat (4) dan wajib mengikuti seleksi penyesuaian/inpassing ulang.
(3) Dalam hal PNS sebagaimana dimaksud pada ayat (2) tidak mengikuti seleksi penyesuaian/inpassing ulang dan tetap ingin diangkat ke dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing, rekomendasi yang diberikan menggunakan kepangkatan, pendidikan, atau masa kerja yang ditetapkan berdasarkan hasil seleksi penyesuaian/inpassing yang pertama tetap berlaku dengan syarat kenaikan pangkat terbarunya dibatalkan Tie - terlebih dahulu dan dikembalikan ke pangkat sebelumnya.
(4) Permohonan penyesuaian rekomendasi sebagaimana dimaksud pada ayat (1) disampaikan oleh Instansi Pengguna kepada Instansi Pembina.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2679, 'perban-2-2022', 21, 'pasal', 'Pasal 19', 'BAB VIII KETENTUAN PENUTUP', 16, 'Pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing dilaksanakan sampai dengan 23 Desember 2022.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2679, 'Pengangkatan PNS dalam JF Penata Penanggulangan Bencana melalui penyesuaian/inpassing dilaksanakan sampai dengan 23 Desember 2022.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2680, 'perban-2-2022', 22, 'pasal', 'Pasal 20', 'BAB VIII KETENTUAN PENUTUP', 16, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2680, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2022 tentang Pengangkatan dalam Jabatan Fungsional Penata Penanggulangan Bencana Melalui Penyesuaian/Inpassing');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2681, 'perban-2-2022', 23, 'lain', 'Penutup', NULL, 17, 'Ditetapkan di Jakarta pada tanggal 21 Januari 2022 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
