INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2684, 'perban-2-2022', 26, 'lampiran', 'Lampiran hal. 19', NULL, 19, '4. surat keterangan sehat jasmani dan rohani dari dokter,
5. salinan ijazah pendidikan terakhir sesuai kualifikasi,
6. salinan penilaian kinerja 2 (dua) tahun terakhir yang telah dilegalisir,
7. daftar riwayat hidup,
8. surat keterangan yang memuat pengalaman mengenai pelaksanaan tugas di bidang Penyelenggaraan Penanggulangan Bencana paling sedikit selama 2 (dua) tahun dan ditandatangani oleh PyB,
9. surat pernyataan yang menyatakan:
a. bersedia diangkat menjadi Jabatan Fungsional Penata Penanggulangan Bencana,
b. bersedia mengikuti pendidikan dan pelatihan, dan
c. kesediaan untuk melaksanakan kegiatan di bidang Jabatan Fungsional Penata Penanggulangan Bencana secara aktif, dan
10. surat keterangan tidak sedang menjalankan tugas belajar, tidak sedang menjalankan cuti di luar tanggungan negara dari pejabat pimpinan tinggi pratama.
Atas perhatian dan perkenannya, kami mengucapkan terima kasih.
(Pejabat Pimpinan Tinggi Pratama Tingkat Pusat/Daerah) (tanda tangan, stempel dinas) Format 2 - Surat Keterangan Tidak Sedang Menjalani Hukuman Disiplin Tingkat Sedang Maupun Berat.
