INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2694, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2695, 'perban-2-2023', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk menghadapi situasi kedaruratan yang diakibatkan oleh ancaman bencana, perlu dilakukan upaya kesiapsiagaan secara terencana melalui penyusunan rencana kontingensi bencana sebagai bagian dari rencana penanggulangan kedaruratan bencana;
b. bahwa untuk meningkatkan peran pemerintah dan pemerintah daerah dalam kesiapsiagaan menanggulangi kedaruratan bencana, perlu ditetapkan pedoman mengenai penyusunan rencana kontingensi bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Penyusunan Rencana Kontingensi Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2695, 'a. bahwa untuk menghadapi situasi kedaruratan yang diakibatkan oleh ancaman bencana, perlu dilakukan upaya kesiapsiagaan secara terencana melalui penyusunan rencana kontingensi bencana sebagai bagian dari rencana penanggulangan kedaruratan bencana;
b. bahwa untuk meningkatkan peran pemerintah dan pemerintah daerah dalam kesiapsiagaan menanggulangi kedaruratan bencana, perlu ditetapkan pedoman mengenai penyusunan rencana kontingensi bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Penyusunan Rencana Kontingensi Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2696, 'perban-2-2023', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2696, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2697, 'perban-2-2023', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENYUSUNAN RENCANA KONTINGENSI BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2697, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENYUSUNAN RENCANA KONTINGENSI BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2698, 'perban-2-2023', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Rencana Kontingensi Bencana adalah dokumen hasil perencanaan kontingensi yang disusun dengan tujuan untuk meningkatkan kesiapsiagaan menghadapi suatu ancaman bencana pada suatu daerah atau wilayah tertentu.
2. Rencana Penanggulangan Kedaruratan Bencana adalah kerangka kerja yang ditetapkan oleh pemerintah atau pemerintah daerah dalam melaksanakan penanggulangan kedaruratan bencana.
3. Sistem Komando Penanganan Darurat Bencana adalah satu kesatuan upaya terstruktur dalam satu komando yang digunakan untuk mengintegrasikan kegiatan penanganan darurat secara efektif dan efisien dalam mengendalikan ancaman/penyebab bencana dan menanggulangi dampak pada saat keadaan darurat bencana.
4. Rencana Operasi Darurat Bencana adalah dokumen perencanaan tindakan operasi darurat bencana dengan menyepakati tujuan operasi dan ketetapan tindakan teknis dan manajerial untuk penanganan darurat bencana dan disusun berdasarkan berbagai masukan penanganan bencana termasuk rencana kontingensi dan informasi bencana untuk mencapai tujuan penanganan darurat bencana secara aman, efektif, dan akuntabel.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2698, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Rencana Kontingensi Bencana adalah dokumen hasil perencanaan kontingensi yang disusun dengan tujuan untuk meningkatkan kesiapsiagaan menghadapi suatu ancaman bencana pada suatu daerah atau wilayah tertentu.
2. Rencana Penanggulangan Kedaruratan Bencana adalah kerangka kerja yang ditetapkan oleh pemerintah atau pemerintah daerah dalam melaksanakan penanggulangan kedaruratan bencana.
3. Sistem Komando Penanganan Darurat Bencana adalah satu kesatuan upaya terstruktur dalam satu komando yang digunakan untuk mengintegrasikan kegiatan penanganan darurat secara efektif dan efisien dalam mengendalikan ancaman/penyebab bencana dan menanggulangi dampak pada saat keadaan darurat bencana.
4. Rencana Operasi Darurat Bencana adalah dokumen perencanaan tindakan operasi darurat bencana dengan menyepakati tujuan operasi dan ketetapan tindakan teknis dan manajerial untuk penanganan darurat bencana dan disusun berdasarkan berbagai masukan penanganan bencana termasuk rencana kontingensi dan informasi bencana untuk mencapai tujuan penanganan darurat bencana secara aman, efektif, dan akuntabel.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2699, 'perban-2-2023', 5, 'pasal', 'Pasal 2', 'BAB II PELAKSANA', 2, '(1) Rencana Kontingensi Bencana merupakan bagian dari Rencana Penanggulangan Kedaruratan Bencana.
(2) Rencana Kontingensi Bencana dapat berubah menjadi Rencana Operasi Darurat Bencana dalam hal terjadi keadaan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2699, '(1) Rencana Kontingensi Bencana merupakan bagian dari Rencana Penanggulangan Kedaruratan Bencana.
(2) Rencana Kontingensi Bencana dapat berubah menjadi Rencana Operasi Darurat Bencana dalam hal terjadi keadaan darurat bencana.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2700, 'perban-2-2023', 6, 'pasal', 'Pasal 3', 'BAB III TAHAPAN PENYUSUNAN', 2, '(1) Pemerintah atau Pemerintah Daerah menetapkan Rencana Kontingensi Bencana sesuai kewenangannya.
(2) Rencana Kontingensi Bencana disusun secara partisipatif oleh para pihak yang terlibat dalam penyelenggaraan penanggulangan bencana.
(3) Penyusunan Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (2) dikoordinasikan oleh Badan Nasional Penanggulangan Bencana atau Badan Penanggulangan Bencana Daerah.
(4) Dalam hal terdapat risiko bencana yang berpotensi menimbulkan bencana, Rencana Kontingensi Bencana dapat ditetapkan oleh pihak lain.
(5) Pihak lain sebagaimana dimaksud pada ayat (4) mencakup lembaga usaha dan masyarakat.
(6) Penyusunan Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (4) dilakukan dengan berkoordinasi kepada Badan Nasional Penanggulangan Bencana dan/atau Badan Penanggulangan Bencana Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2700, '(1) Pemerintah atau Pemerintah Daerah menetapkan Rencana Kontingensi Bencana sesuai kewenangannya.
(2) Rencana Kontingensi Bencana disusun secara partisipatif oleh para pihak yang terlibat dalam penyelenggaraan penanggulangan bencana.
(3) Penyusunan Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (2) dikoordinasikan oleh Badan Nasional Penanggulangan Bencana atau Badan Penanggulangan Bencana Daerah.
(4) Dalam hal terdapat risiko bencana yang berpotensi menimbulkan bencana, Rencana Kontingensi Bencana dapat ditetapkan oleh pihak lain.
(5) Pihak lain sebagaimana dimaksud pada ayat (4) mencakup lembaga usaha dan masyarakat.
(6) Penyusunan Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (4) dilakukan dengan berkoordinasi kepada Badan Nasional Penanggulangan Bencana dan/atau Badan Penanggulangan Bencana Daerah.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2701, 'perban-2-2023', 7, 'pasal', 'Pasal 4', 'BAB III TAHAPAN PENYUSUNAN', 3, 'Penyusunan Rencana Kontingensi Bencana dilaksanakan secara bertahap, melalui:
a. persiapan;
b. pelaksanaan; dan
c. finalisasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2701, 'Penyusunan Rencana Kontingensi Bencana dilaksanakan secara bertahap, melalui:
a. persiapan;
b. pelaksanaan; dan
c. finalisasi.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2702, 'perban-2-2023', 8, 'pasal', 'Pasal 5', 'BAB III TAHAPAN PENYUSUNAN', 3, '(1) Persiapan sebagaimana dimaksud dalam Pasal 4 huruf a meliputi:
a. penyusunan kerangka acuan kegiatan;
b. penentuan jenis ancaman bencana;
c. identifikasi pihak dan pengorganisasian; dan
d. pengumpulan dan pengelolaan data.
(2) Kerangka acuan kerja sebagaimana dimaksud pada ayat
(1) huruf a paling sedikit memuat:
a. latar belakang;
b. maksud dan tujuan;
c. metode;
d. rangkaian dan waktu kegiatan;
e. rencana; dan
f. sumber anggaran.
(3) Penentuan jenis ancaman bencana sebagaimana dimaksud pada ayat (1) huruf b memperhatikan hasil kajian risiko bencana, atau adanya tanda tanda atau gejala lain yang menunjukkan akan terjadi bencana.
(4) Identifikasi pihak dan pengorganisasian sebagaimana dimaksud pada ayat (1) huruf c berupa penentuan pihak-pihak yang terlibat dalam penyusunan Rencana Kontingensi Bencana dengan memperhatikan inklusivitas beserta pengelompokan tugas yang diberikan.
(5) Pengumpulan dan pengelolaan data sebagaimana dimaksud pada ayat (1) huruf d berupa kegiatan mengumpulkan, mengorganisasi, dan menganalisis data dan informasi yang diperlukan untuk penyusunan Rencana Kontingensi Bencana.
(6) Data dan informasi yang diperlukan sebagaimana dimaksud pada ayat (5) berupa:
a. gambaran ancaman bencana yang mengacu pada dokumen kajian risiko bencana yang tersedia dan kajian ancaman yang dikeluarkan oleh lembaga terkait;
b. peraturan dan kebijakan daerah terkait kebencanaan dan penganggaran;
c. standar pemenuhan kebutuhan dasar;
d. prosedur tetap terkait penanganan darurat bencana;
e. ketersediaan sumber daya lembaga atau organisasi pelaku penanganan darurat bencana; dan
f. data sarana dan prasarana vital.');
