INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2703, 'perban-2-2023', 9, 'pasal', 'Pasal 6', 'BAB III TAHAPAN PENYUSUNAN', 4, '(1) Pelaksanaan sebagaimana dimaksud dalam Pasal 4 huruf b meliputi:
a. penentuan cakupan kedaruratan;
b. pengembangan kerangka respon; dan
c. penentuan rancangan respon.
(2) Pelaksanaan sebagaimana dimaksud pada ayat (1) dapat dilakukan dengan metode:
a. pengumpulan data;
b. pemetaan;
c. lokakarya; dan
d. diskusi kelompok terarah.
(3) Hasil perumusan pelaksanaan sebagaimana dimaksud pada ayat (1) dituangkan dalam bentuk rancangan awal Rencana Kontingensi Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2703, '(1) Pelaksanaan sebagaimana dimaksud dalam Pasal 4 huruf b meliputi:
a. penentuan cakupan kedaruratan;
b. pengembangan kerangka respon; dan
c. penentuan rancangan respon.
(2) Pelaksanaan sebagaimana dimaksud pada ayat (1) dapat dilakukan dengan metode:
a. pengumpulan data;
b. pemetaan;
c. lokakarya; dan
d. diskusi kelompok terarah.
(3) Hasil perumusan pelaksanaan sebagaimana dimaksud pada ayat (1) dituangkan dalam bentuk rancangan awal Rencana Kontingensi Bencana.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2704, 'perban-2-2023', 10, 'pasal', 'Pasal 7', 'BAB III TAHAPAN PENYUSUNAN', 4, '(1) Penentuan cakupan kedaruratan sebagaimana dimaksud dalam Pasal 6 ayat (1) huruf a meliputi:
a. karakteristik ancaman bencana;
b. skenario kejadian; dan
c. asumsi dampak bencana.
(2) Karakteristik ancaman bencana sebagaimana dimaksud pada ayat (1) huruf a memperhatikan lokasi, waktu, asal atau penyebab, durasi, frekuensi, periode, luasan terdampak, intensitas, kecepatan kejadian, jarak, proses, dan potensi ancaman bencana lanjutan atau ikutannya.
(3) Skenario kejadian sebagaimana dimaksud pada ayat (1) huruf b disusun dengan memperhatikan masukan dari narasumber atau pakar yang kompeten.
(4) Asumsi dampak bencana sebagaimana dimaksud pada ayat (1) huruf c berupa proyeksi akibat langsung yang dikembangkan berdasarkan skenario kejadian dan analisis risiko bencana.
(5) Asumsi dampak sebagaimana dimaksud pada ayat (4) diproyeksikan terhadap aspek:
a. lingkungan;
b. kependudukan;
c. ekonomi;
d. infrastruktur/fisik; dan
e. layanan sipil.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2704, '(1) Penentuan cakupan kedaruratan sebagaimana dimaksud dalam Pasal 6 ayat (1) huruf a meliputi:
a. karakteristik ancaman bencana;
b. skenario kejadian; dan
c. asumsi dampak bencana.
(2) Karakteristik ancaman bencana sebagaimana dimaksud pada ayat (1) huruf a memperhatikan lokasi, waktu, asal atau penyebab, durasi, frekuensi, periode, luasan terdampak, intensitas, kecepatan kejadian, jarak, proses, dan potensi ancaman bencana lanjutan atau ikutannya.
(3) Skenario kejadian sebagaimana dimaksud pada ayat (1) huruf b disusun dengan memperhatikan masukan dari narasumber atau pakar yang kompeten.
(4) Asumsi dampak bencana sebagaimana dimaksud pada ayat (1) huruf c berupa proyeksi akibat langsung yang dikembangkan berdasarkan skenario kejadian dan analisis risiko bencana.
(5) Asumsi dampak sebagaimana dimaksud pada ayat (4) diproyeksikan terhadap aspek:
a. lingkungan;
b. kependudukan;
c. ekonomi;
d. infrastruktur/fisik; dan
e. layanan sipil.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2705, 'perban-2-2023', 11, 'pasal', 'Pasal 8', 'BAB III TAHAPAN PENYUSUNAN', 5, 'Pengembangan kerangka respon sebagaimana dimaksud dalam Pasal 6 ayat (1) huruf b merupakan landasan penanganan kedaruratan yang telah disepakati atau ditetapkan dalam Rencana Penanggulangan Kedaruratan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2705, 'Pengembangan kerangka respon sebagaimana dimaksud dalam Pasal 6 ayat (1) huruf b merupakan landasan penanganan kedaruratan yang telah disepakati atau ditetapkan dalam Rencana Penanggulangan Kedaruratan Bencana.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2706, 'perban-2-2023', 12, 'pasal', 'Pasal 9', 'BAB III TAHAPAN PENYUSUNAN', 5, 'Penentuan kerangka respon sebagaimana dimaksud dalam Pasal 6 ayat (1) huruf c meliputi:
a. penatalaksanaan respon;
b. penatakelolaan administrasi dan sumber daya;
c. pengendalian; dan
d. pemenuhan kelengkapan operasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2706, 'Penentuan kerangka respon sebagaimana dimaksud dalam Pasal 6 ayat (1) huruf c meliputi:
a. penatalaksanaan respon;
b. penatakelolaan administrasi dan sumber daya;
c. pengendalian; dan
d. pemenuhan kelengkapan operasi.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2707, 'perban-2-2023', 13, 'pasal', 'Pasal 10', 'BAB III TAHAPAN PENYUSUNAN', 5, '(1) Penatalaksanaan respon sebagaimana dimaksud dalam Pasal 9 huruf a dilakukan untuk menentukan:
a. tujuan;
b. sasaran;
c. konsep operasi;
d. struktur organisasi penanganan kedaruratan; dan
e. kegiatan pokok.
(2) Tujuan sebagaimana dimaksud pada ayat (1) huruf a berupa narasi yang memuat tujuan umum penanganan darurat dan tujuan khusus sesuai kebijakan daerah.
(3) Sasaran sebagaimana dimaksud pada ayat (1) huruf b berupa kesepakatan target atau capaian dari tujuan atau operasi penanganan kedaruratan.
(4) Konsep operasi sebagaimana dimaksud pada ayat (1) huruf c berupa ruang lingkup operasi penanganan darurat bencana dan penjabaran tindakan yang akan dilakukan dalam kurun waktu atau periode yang telah ditentukan.
(5) Struktur organisasi penanganan kedaruratan sebagaimana dimaksud pada ayat (1) huruf d berupa penetapan bidang tugas dan fungsi organisasi penanganan kedaruratan sesuai dengan konsep operasi.
(6) Kegiatan pokok sebagaimana dimaksud pada ayat (1) huruf e berupa penjabaran fungsi operasional dari masing-masing bidang ke dalam bentuk kegiatan pokok.
(7) Kegiatan pokok sebagaimana dimaksud pada ayat (6) merupakan kerangka respon dalam penyusunan Rencana Kontingensi Bencana yang terdiri atas:
a. kegiatan prioritas yang dirancang berdasarkan kemampuan sumber daya yang tersedia; dan
b. kegiatan lain yang diperlukan.
(8) Penentuan struktur organisasi penanganan kedaruratan sebagaimana dimaksud pada ayat (5) berpedoman pada Peraturan Badan Nasional Penanggulangan Bencana mengenai Sistem Komando Penanganan Darurat Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2707, '(1) Penatalaksanaan respon sebagaimana dimaksud dalam Pasal 9 huruf a dilakukan untuk menentukan:
a. tujuan;
b. sasaran;
c. konsep operasi;
d. struktur organisasi penanganan kedaruratan; dan
e. kegiatan pokok.
(2) Tujuan sebagaimana dimaksud pada ayat (1) huruf a berupa narasi yang memuat tujuan umum penanganan darurat dan tujuan khusus sesuai kebijakan daerah.
(3) Sasaran sebagaimana dimaksud pada ayat (1) huruf b berupa kesepakatan target atau capaian dari tujuan atau operasi penanganan kedaruratan.
(4) Konsep operasi sebagaimana dimaksud pada ayat (1) huruf c berupa ruang lingkup operasi penanganan darurat bencana dan penjabaran tindakan yang akan dilakukan dalam kurun waktu atau periode yang telah ditentukan.
(5) Struktur organisasi penanganan kedaruratan sebagaimana dimaksud pada ayat (1) huruf d berupa penetapan bidang tugas dan fungsi organisasi penanganan kedaruratan sesuai dengan konsep operasi.
(6) Kegiatan pokok sebagaimana dimaksud pada ayat (1) huruf e berupa penjabaran fungsi operasional dari masing-masing bidang ke dalam bentuk kegiatan pokok.
(7) Kegiatan pokok sebagaimana dimaksud pada ayat (6) merupakan kerangka respon dalam penyusunan Rencana Kontingensi Bencana yang terdiri atas:
a. kegiatan prioritas yang dirancang berdasarkan kemampuan sumber daya yang tersedia; dan
b. kegiatan lain yang diperlukan.
(8) Penentuan struktur organisasi penanganan kedaruratan sebagaimana dimaksud pada ayat (5) berpedoman pada Peraturan Badan Nasional Penanggulangan Bencana mengenai Sistem Komando Penanganan Darurat Bencana.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2708, 'perban-2-2023', 14, 'pasal', 'Pasal 11', 'BAB III TAHAPAN PENYUSUNAN', 5, '(1) Penatakelolaan administrasi dan sumber daya sebagaimana dimaksud dalam Pasal 9 huruf b meliputi:
a. mekanisme pengelolaan administrasi dan keuangan untuk penanganan kedaruratan; dan
b. mekanisme pengelolaan sumber daya penanganan kedaruratan berupa ketersediaan, kebutuhan, dan kesenjangan sumber daya; dan
c. mekanisme dan strategi pemenuhan kesenjangan.
(2) Kesenjangan sebagaimana dimaksud pada ayat (1) merupakan kesenjangan pada administrasi dan/atau sumber daya yang tersedia dengan yang dibutuhkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2708, '(1) Penatakelolaan administrasi dan sumber daya sebagaimana dimaksud dalam Pasal 9 huruf b meliputi:
a. mekanisme pengelolaan administrasi dan keuangan untuk penanganan kedaruratan; dan
b. mekanisme pengelolaan sumber daya penanganan kedaruratan berupa ketersediaan, kebutuhan, dan kesenjangan sumber daya; dan
c. mekanisme dan strategi pemenuhan kesenjangan.
(2) Kesenjangan sebagaimana dimaksud pada ayat (1) merupakan kesenjangan pada administrasi dan/atau sumber daya yang tersedia dengan yang dibutuhkan.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2709, 'perban-2-2023', 15, 'pasal', 'Pasal 12', 'BAB III TAHAPAN PENYUSUNAN', 6, '(1) Pengendalian sebagaimana dimaksud dalam Pasal 9 huruf c berupa:
a. instruksi;
b. komando dan kendali;
c. koordinasi;
d. komunikasi; dan
e. pengelolaan informasi.
(2) Instruksi sebagaimana dimaksud pada ayat (1) huruf a, berupa arahan, perintah, pokok mandat atau langkah penanganan darurat bencana yang diberikan oleh Kepala Badan Nasional Penanggulangan Bencana atau Kepala Daerah.
(3) Komando dan kendali sebagaimana dimaksud pada ayat
(1) huruf b merupakan kegiatan mengidentifikasi dan menyepakati kewenangan komando untuk memberikan perintah, mengendalikan, memantau, dan mengevaluasi kegiatan penanganan darurat bencana.
(4) Koordinasi sebagaimana dimaksud pada ayat (1) huruf c merupakan kegiatan menyepakati mekanisme pemaduan peran dan fungsi sektor yang terkait secara proporsional dan saling mendukung dalam penanganan kedaruratan yang terdiri atas koordinasi horisontal dan koordinasi vertikal.
(5) Komunikasi sebagaimana dimaksud pada ayat (1) huruf d merupakan kegiatan menyepakati sistem komunikasi yang digunakan dalam penanganan kedaruratan.
(6) Pengelolaan informasi sebagaimana dimaksud pada ayat
(1) huruf e merupakan kesepakatan pengelolaan data dan informasi untuk mendukung operasi penanganan kedaruratan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2709, '(1) Pengendalian sebagaimana dimaksud dalam Pasal 9 huruf c berupa:
a. instruksi;
b. komando dan kendali;
c. koordinasi;
d. komunikasi; dan
e. pengelolaan informasi.
(2) Instruksi sebagaimana dimaksud pada ayat (1) huruf a, berupa arahan, perintah, pokok mandat atau langkah penanganan darurat bencana yang diberikan oleh Kepala Badan Nasional Penanggulangan Bencana atau Kepala Daerah.
(3) Komando dan kendali sebagaimana dimaksud pada ayat
(1) huruf b merupakan kegiatan mengidentifikasi dan menyepakati kewenangan komando untuk memberikan perintah, mengendalikan, memantau, dan mengevaluasi kegiatan penanganan darurat bencana.
(4) Koordinasi sebagaimana dimaksud pada ayat (1) huruf c merupakan kegiatan menyepakati mekanisme pemaduan peran dan fungsi sektor yang terkait secara proporsional dan saling mendukung dalam penanganan kedaruratan yang terdiri atas koordinasi horisontal dan koordinasi vertikal.
(5) Komunikasi sebagaimana dimaksud pada ayat (1) huruf d merupakan kegiatan menyepakati sistem komunikasi yang digunakan dalam penanganan kedaruratan.
(6) Pengelolaan informasi sebagaimana dimaksud pada ayat
(1) huruf e merupakan kesepakatan pengelolaan data dan informasi untuk mendukung operasi penanganan kedaruratan.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2710, 'perban-2-2023', 16, 'pasal', 'Pasal 13', 'BAB III TAHAPAN PENYUSUNAN', 6, 'Pemenuhan kelengkapan operasi sebagaimana dimaksud dalam Pasal 9 huruf d merupakan identifikasi dan verifikasi seluruh dokumen dan/atau perangkat pendukung operasi penanganan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2710, 'Pemenuhan kelengkapan operasi sebagaimana dimaksud dalam Pasal 9 huruf d merupakan identifikasi dan verifikasi seluruh dokumen dan/atau perangkat pendukung operasi penanganan darurat bencana.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2711, 'perban-2-2023', 17, 'pasal', 'Pasal 14', 'BAB III TAHAPAN PENYUSUNAN', 6, 'Finalisasi sebagaimana dimaksud dalam Pasal 4 huruf c terdiri atas:
a. konfirmasi kesepakatan para pihak;
b. penyempurnaan rancangan Rencana Kontingensi Bencana; dan
c. penetapan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2711, 'Finalisasi sebagaimana dimaksud dalam Pasal 4 huruf c terdiri atas:
a. konfirmasi kesepakatan para pihak;
b. penyempurnaan rancangan Rencana Kontingensi Bencana; dan
c. penetapan.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2712, 'perban-2-2023', 18, 'pasal', 'Pasal 15', 'BAB III TAHAPAN PENYUSUNAN', 7, 'Konfirmasi kesepakatan para pihak sebagaimana dimaksud dalam Pasal 14 huruf a berupa penyepakatan terhadap substansi dan rincian dari rancangan awal Rencana Kontingensi Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2712, 'Konfirmasi kesepakatan para pihak sebagaimana dimaksud dalam Pasal 14 huruf a berupa penyepakatan terhadap substansi dan rincian dari rancangan awal Rencana Kontingensi Bencana.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2713, 'perban-2-2023', 19, 'pasal', 'Pasal 16', 'BAB III TAHAPAN PENYUSUNAN', 7, '(1) Penyempurnaan rancangan Rencana Kontingensi Bencana sebagaimana dimaksud dalam Pasal 14 huruf b berupa penyempurnaan terhadap substansi dan rincian dari rancangan awal Rencana Kontingensi Bencana yang telah disepakati oleh para pihak.
(2) Kesepakatan hasil penyempurnaan rancangan Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (1) dituangkan ke dalam bentuk berita acara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2713, '(1) Penyempurnaan rancangan Rencana Kontingensi Bencana sebagaimana dimaksud dalam Pasal 14 huruf b berupa penyempurnaan terhadap substansi dan rincian dari rancangan awal Rencana Kontingensi Bencana yang telah disepakati oleh para pihak.
(2) Kesepakatan hasil penyempurnaan rancangan Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (1) dituangkan ke dalam bentuk berita acara.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2714, 'perban-2-2023', 20, 'pasal', 'Pasal 17', 'BAB IV PEMUTAKHIRAN DAN PENGUJIAN', 7, '(1) Penetapan sebagaimana dimaksud dalam Pasal 14 huruf c dilaksanakan sebagai proses formalisasi rencana kontingensi.
(2) Penetapan untuk tingkat pusat dilaksanakan oleh Kepala Badan Nasional Penanggulangan Bencana.
(3) Penetapan untuk tingkat daerah dilaksanakan oleh Kepala Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2714, '(1) Penetapan sebagaimana dimaksud dalam Pasal 14 huruf c dilaksanakan sebagai proses formalisasi rencana kontingensi.
(2) Penetapan untuk tingkat pusat dilaksanakan oleh Kepala Badan Nasional Penanggulangan Bencana.
(3) Penetapan untuk tingkat daerah dilaksanakan oleh Kepala Daerah.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2715, 'perban-2-2023', 21, 'pasal', 'Pasal 18', 'BAB IV PEMUTAKHIRAN DAN PENGUJIAN', 7, '(1) Untuk menjaga aktualitas dan validitas, terhadap Rencana Kontingensi Bencana yang telah ditetapkan sebagaimana dimaksud dalam Pasal 17 dapat dilakukan pemutakhiran.
(2) Pemutakhiran Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (1) merupakan pemutakhiran substansi Rencana Kontingensi Bencana.
(3) Pemutakhiran sebagaimana dimaksud pada ayat (2) dilakukan melalui:
a. menyusun rencana kegiatan tindak lanjut dalam tabel yang memuat tahapan, para pelaku/sektor, dan waktu pelaksanaan kegiatan;
b. melakukan inventarisasi, pemeliharaan ketersediaan dan kesiapan sumber daya, sarana dan prasarana yang ada dilakukan secara berkala;
c. melakukan pertemuan berkala untuk kaji ulang dalam rangka pemutakhiran data dan asumsi dampak bencana atau proyeksi kebutuhan sumber daya;
d. menyusun prosedur tetap untuk mendukung pelaksanaan atau aktivasi Rencana Kontingensi Bencana yang telah disusun;
e. melakukan pemantauan secara periodik terhadap ancaman dan peringatan dini beserta diseminasinya; dan
f. melakukan pemutakhiran data dengan mempertimbangkan kajian apabila tidak terjadi bencana dalam suatu periode tertentu.
(4) Pemutakhiran Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (3) disepakati para pihak.
(5) Terhadap Rencana Kontingensi Bencana yang telah disepakati sebagaimana dimaksud pada ayat (4) dilakukan penetapan kembali oleh Kepala Badan Nasional Penanggulangan Bencana atau Kepala Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2715, '(1) Untuk menjaga aktualitas dan validitas, terhadap Rencana Kontingensi Bencana yang telah ditetapkan sebagaimana dimaksud dalam Pasal 17 dapat dilakukan pemutakhiran.
(2) Pemutakhiran Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (1) merupakan pemutakhiran substansi Rencana Kontingensi Bencana.
(3) Pemutakhiran sebagaimana dimaksud pada ayat (2) dilakukan melalui:
a. menyusun rencana kegiatan tindak lanjut dalam tabel yang memuat tahapan, para pelaku/sektor, dan waktu pelaksanaan kegiatan;
b. melakukan inventarisasi, pemeliharaan ketersediaan dan kesiapan sumber daya, sarana dan prasarana yang ada dilakukan secara berkala;
c. melakukan pertemuan berkala untuk kaji ulang dalam rangka pemutakhiran data dan asumsi dampak bencana atau proyeksi kebutuhan sumber daya;
d. menyusun prosedur tetap untuk mendukung pelaksanaan atau aktivasi Rencana Kontingensi Bencana yang telah disusun;
e. melakukan pemantauan secara periodik terhadap ancaman dan peringatan dini beserta diseminasinya; dan
f. melakukan pemutakhiran data dengan mempertimbangkan kajian apabila tidak terjadi bencana dalam suatu periode tertentu.
(4) Pemutakhiran Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (3) disepakati para pihak.
(5) Terhadap Rencana Kontingensi Bencana yang telah disepakati sebagaimana dimaksud pada ayat (4) dilakukan penetapan kembali oleh Kepala Badan Nasional Penanggulangan Bencana atau Kepala Daerah.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2716, 'perban-2-2023', 22, 'pasal', 'Pasal 19', 'BAB IV PEMUTAKHIRAN DAN PENGUJIAN', 8, '(1) Untuk menjaga kualitas Rencana Kontingensi Bencana yang telah ditetapkan sebagaimana dimaksud dalam Pasal 17, dilakukan uji Rencana Kontingensi Bencana.
(2) Uji Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (1) melalui latihan kesiapsiagaan.
(3) Latihan kesiapsiagaan sebagaimana dimaksud pada ayat
(2) dilaksanakan melalui penyelenggaraan:
a. kegiatan dalam bentuk diskusi, seminar atau lokakarya untuk membangun dan memperkuat pemahaman para pihak;
b. uji latihan untuk meningkatkan keterampilan pada bidang atau aktivitas spesifik dalam penanganan darurat; dan
c. uji operasionalisasi dan kesesuaian perencanaan melalui geladi posko dan geladi lapang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2716, '(1) Untuk menjaga kualitas Rencana Kontingensi Bencana yang telah ditetapkan sebagaimana dimaksud dalam Pasal 17, dilakukan uji Rencana Kontingensi Bencana.
(2) Uji Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (1) melalui latihan kesiapsiagaan.
(3) Latihan kesiapsiagaan sebagaimana dimaksud pada ayat
(2) dilaksanakan melalui penyelenggaraan:
a. kegiatan dalam bentuk diskusi, seminar atau lokakarya untuk membangun dan memperkuat pemahaman para pihak;
b. uji latihan untuk meningkatkan keterampilan pada bidang atau aktivitas spesifik dalam penanganan darurat; dan
c. uji operasionalisasi dan kesesuaian perencanaan melalui geladi posko dan geladi lapang.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2717, 'perban-2-2023', 23, 'pasal', 'Pasal 20', 'BAB V MASA BERLAKU', 8, 'Panduan penulisan Rencana Kontingensi Bencana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2717, 'Panduan penulisan Rencana Kontingensi Bencana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2718, 'perban-2-2023', 24, 'pasal', 'Pasal 21', 'BAB VI DISEMINASI', 8, '(1) Rencana Kontingensi Bencana berlaku untuk jangka waktu 3 (tiga) tahun.
(2) Rencana Kontingensi Bencana dapat dilakukan reviu secara berkala paling sedikit 6 (enam) bulan sekali.
(3) Dalam hal hasil reviu diusulkan perubahan Rencana Kontingensi Bencana, dapat dilakukan pemutakhiran.
(4) Pelaksanaan pemutakhiran dilaksanakan sesuai dengan ketentuan sebagaimana dimuat dalam Pasal 19.
(5) Pemutakhiran sebagaimana dimaksud pada ayat (3) memperbaharui masa berlaku Rencana Kontingensi Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2718, '(1) Rencana Kontingensi Bencana berlaku untuk jangka waktu 3 (tiga) tahun.
(2) Rencana Kontingensi Bencana dapat dilakukan reviu secara berkala paling sedikit 6 (enam) bulan sekali.
(3) Dalam hal hasil reviu diusulkan perubahan Rencana Kontingensi Bencana, dapat dilakukan pemutakhiran.
(4) Pelaksanaan pemutakhiran dilaksanakan sesuai dengan ketentuan sebagaimana dimuat dalam Pasal 19.
(5) Pemutakhiran sebagaimana dimaksud pada ayat (3) memperbaharui masa berlaku Rencana Kontingensi Bencana.', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2719, 'perban-2-2023', 25, 'pasal', 'Pasal 22', 'BAB VII PENDANAAN', 8, '(1) Rencana Kontingensi Bencana disampaikan kepada pihak terkait penanganan kedaruratan bencana dalam rangka pelayanan publik.
(2) Penyampaian Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (1) dilaksanakan secara resmi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2719, '(1) Rencana Kontingensi Bencana disampaikan kepada pihak terkait penanganan kedaruratan bencana dalam rangka pelayanan publik.
(2) Penyampaian Rencana Kontingensi Bencana sebagaimana dimaksud pada ayat (1) dilaksanakan secara resmi.', 'Pasal 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2720, 'perban-2-2023', 26, 'pasal', 'Pasal 23', 'BAB VIII KETENTUAN PENUTUP', 9, 'Pendanaan penyusunan Rencana Kontingensi Bencana bersumber dari:
a. Anggaran Pendapatan Belanja Negara;
b. Anggaran Pendapatan Belanja Daerah; dan/atau
c. sumber lain yang sah dan tidak mengikat sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2720, 'Pendanaan penyusunan Rencana Kontingensi Bencana bersumber dari:
a. Anggaran Pendapatan Belanja Negara;
b. Anggaran Pendapatan Belanja Daerah; dan/atau
c. sumber lain yang sah dan tidak mengikat sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2721, 'perban-2-2023', 27, 'pasal', 'Pasal 24', 'BAB VIII KETENTUAN PENUTUP', 9, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2721, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2722, 'perban-2-2023', 28, 'lain', 'Penutup', NULL, 10, 'Ditetapkan di Jakarta pada tanggal 16 Juni 2023 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
