INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2722, 'Ditetapkan di Jakarta pada tanggal 16 Juni 2023 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
