INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2727, 'perban-2-2023', 33, 'lampiran', 'Lampiran hal. 12', NULL, 12, '2. Gambaran risiko bahaya; dan
3. Gambaran umum urgensi perencanaan kontingensi, yaitu memberikan perlindungan dan rasa aman kepada masyarakat.
1.2. Landasan Hukum Regulasi yang dirujuk dalam penyusunan Rencana Kontingensi Bencana, yaitu;
1. Undang-Undang;
2. Peraturan Pemerintah;
3. Peraturan/Instruksi/Keputusan Presiden;
4. Peraturan/Keputusan/Instruksi Tingkat Kementerian;
5. Peraturan BNPB;
6. Peraturan Daerah; dan
7. Peraturan/Keputusan Kepala Daerah.
1.3. Maksud dan Tujuan Narasi yang menyatakan tentang maksud dan tujuan atau manfaat penyusunan Rencana Kontingensi Bencana bagi daerah yang bersangkutan.
1.4. Ruang Lingkup Yaitu penjelasan tentang ruang lingkup atau cakupan dokumen Rencana Kontingensi Bencana. Ruang lingkup Rencana Kontingensi Bencana terdiri dari 3 (tiga) hal, yaitu:
1. Lingkup Bahaya dan Risiko Bencana, yaitu jenis bahaya/ancaman bencana yang disusun perencanaan kontingensinya.
2. Lingkup Wilayah Risiko, yaitu menjelaskan batas penanganan yang dikelola penanganan kedaruratannya, seperti desa, kabupaten, provinsi, nasional, atau berbasis kawasan.
3. Lingkup Pelaksana Aksi, yaitu menjelaskan tata kelola dan tata laksana penanganan kedaruratan. Selain pemerintah sebagai pemangku pemangku utama, semua pemangku kepentingan penanggulangan bencana, baik lembaga usaha, kelompok masyarakat, perguruan tinggi, dan lembaga nonpemerintah lainnya, yang dilibatkan dalam penanganan kedaruratan.');
