INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2737, 'perban-2-2023', 43, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'Struktur Organisasi No Fungsi/SubBagian/Unit Nama Organisasi 1 Komandan Tanggap Darurat Wakil Komandan 2 Sekretariat (Pemimpin) (Pendukung) 3 Humas (Pemimpin) (Pendukung) 4 Penghubung (Pemimpin) (Pendukung) 5 Bidang Administrasi dan (Pemimpin) Keuangan (Pendukung) 6 Bidang Keamanan Dan (Pemimpin) Keselamatan (Pendukung) 7 Bidang Perencanaan (Koordinator) Unit Data dan Informasi (Pemimpin) (Pendukung) Unit Strategi Pemulihan (Pemimpin) (Pendukung) 8 Bidang Operasi (Koordinator) Unit Pencarian dan (Pemimpin) Pertolongan (Pendukung) Unit Air Bersih dan Sanitasi (Pemimpin) (Pendukung) Unit Kesehatan (Pemimpin) (Pendukung) 9 Bidang Logistik (Koordinator) Unit Transportasi (Pemimpin) (Pendukung) Unit …………. (Pemimpin) (Pendukung) Unit …………. (Pemimpin) (Pendukung) Lampiran 3. Jaring Komunikasi Contoh:');
