INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2738, 'perban-2-2023', 44, 'lampiran', 'Lampiran hal. 19', NULL, 19, 'Contoh Konfigurasi Jaring Komunikasi BNPB Contoh Konfigurasi Jaring Komunikasi Karhutla – Asian Games 2018 Lampiran 4. Estimasi Ketersediaan dan Kebutuhan Sumber Daya Lampiran ini merincikan sumber daya yang tersedia dan proyeksi kebutuhan Ketersediaan Sumber Daya Ketersediaan Sumber Daya Manusia No Jenis Keahlian Jumlah Lokasi Personil Kontak Keterangan Administrasi dan Sekretariat Publikasi dan Informasi Perencanaan dan Pendataan Operasi Tanggap Darurat Ketersediaan Peralatan No Peralatan Jumlah Kondisi Lokasi Kontak Keterangan Kendaraan Roda 4 Alat Berat Kendaraan Penyedia Air Kendaraan Dapur Umum Kendaraan Pelayanan Kesehatan Peralatan Penyelamatan Peralatan Pengungsian Peralatan Publikasi dan Informasi Tempat Pelayanan Kesehatan Gedung Ketersediaan Bahan/Sediaan (Habis Pakai) No Jenis Jumlah Satuan Kondisi Lokasi Kontak Keterangan Obat Obatan Pangan No Jenis Jumlah Satuan Kondisi Lokasi Kontak Keterangan Perlengkapan Persediaan Alat Proyeksi Kebutuhan Sumber Daya Siaga Darurat TUGAS/KEGIATAN SUMBER DAYA KETERANGAN NO. (* KEGIATAN KATEGORI JENIS KEMAMPUAN KETERSEDIAAN KEBUTUHAN KESENJANGAN POKOK) 1 Manusia: - Peralatan Bahan:
