INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2740, 'perban-2-2023', 46, 'lampiran', 'Lampiran hal. 27', NULL, 27, 'Gempa 6,5 MMI diikuti dengan berbunyinya Sirine Peringatan Tsunami terjadi pada waktu hari Minggu jam 09.00 WIB dimana kegiatan masyarakat dan wisatawan pada umumnya yang berlibur di pantai, dengan kegiatan ekonomi yang ada yaitu para nelayan dan pedagang di sekitar pantai dan kegiatan sosial seperti kegiatan ibadah di gereja setempat dan kegiatan Pos Kesehatan Desa .
Penduduk di RT 11 dan RT 12 / RW 04 segera akan mengungsi setelah mendengarkan sirine baik yang mandiri maupun yang harus dipandu secara intens; tetapi ada satu keluarga dengan 1 (satu) warga yang sedang menjalankan isolasi mandiri COVID-19 tetapi ada warga yang tidak merespon (Dusun Sendang Biru) karena posnya terbatas dalam jangkauan penerimaan bunyi sirine.
Landaan tsunami bermula dari gempa yang terjadi dan diperkirakan sampai ke wilayah RT 11 dan RT 12 RW 04. Ketinggian gelombang mulai 20m di beberapa lokasi/wilayah/RT 12 RW 04 sampai dengan yang tertinggi setinggi 28 m di lokasi di wilayah RT 12 RW 04.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2740, 'Gempa 6,5 MMI diikuti dengan berbunyinya Sirine Peringatan Tsunami terjadi pada waktu hari Minggu jam 09.00 WIB dimana kegiatan masyarakat dan wisatawan pada umumnya yang berlibur di pantai, dengan kegiatan ekonomi yang ada yaitu para nelayan dan pedagang di sekitar pantai dan kegiatan sosial seperti kegiatan ibadah di gereja setempat dan kegiatan Pos Kesehatan Desa .
Penduduk di RT 11 dan RT 12 / RW 04 segera akan mengungsi setelah mendengarkan sirine baik yang mandiri maupun yang harus dipandu secara intens; tetapi ada satu keluarga dengan 1 (satu) warga yang sedang menjalankan isolasi mandiri COVID-19 tetapi ada warga yang tidak merespon (Dusun Sendang Biru) karena posnya terbatas dalam jangkauan penerimaan bunyi sirine.
Landaan tsunami bermula dari gempa yang terjadi dan diperkirakan sampai ke wilayah RT 11 dan RT 12 RW 04. Ketinggian gelombang mulai 20m di beberapa lokasi/wilayah/RT 12 RW 04 sampai dengan yang tertinggi setinggi 28 m di lokasi di wilayah RT 12 RW 04.', 'Lampiran hal. 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2741, 'perban-2-2023', 47, 'lampiran', 'Lampiran hal. 27', NULL, 27, '1. PERINGATAN DINI BAHAYA BENCANA PERINGATAN DINI BENCANA BERBASIS MASYARAKAT: TANDA ALAM KEJADIAN DAN PENGETAHUAN LOKAL GEMPA TANDA PERINGATAN SARAN TINDAKAN ORANG Jika gempabumi terasa sedikit tapi Menjauhi pantai dan tepi sungai, ke berlangsung lama tempat yang telah ditentukan dan mencari informasi 5-10 MENIT Jika gempa bumi terasa kuat dan SETELAH berlangsung lama (misalnya lebih dari 1 menit dan orang tidak bisa GEMPA berdiri) PERINGATAN DINI BENCANA RESMI OLEH BMKG MELALUI: SIARAN TV/RADIO, SIRENE PERINGATAN TSUNAMI TINGKAT PERKIRAAN SARAN TINDAKAN SARAN PERINGATAN TINGGI PEMERINTAH TINDAKAN TSUNAMI GELOMBANG DAERAH ORANG (LEVEL) WAKTU STATUS Ketinggian Pemerintah Evakuasi KEDATA-NGAN AWAS: tsunami lebih dari daerah/BPBD daerah bahaya, TSUNAMI EVAKUASI 3 meter setempat segera pergi ke tempat SEGERA mengekauasi aman yang masyarakat ke sudah tempat aman. disepakati, 18 – 33 MENIT menunggu informasi STATUS Ketinggian Pemerintah Evakuasi SIAGA: tsunami antara ½ daerah/BPBD daerah bahaya, EVAKUASI meter – 3 meter setempat segera pergi ke tempat SEGERA mengekauasi aman yang masyarakat ke sudah tempat evakuasi disepakati, terdekat. mencari informasi STATUS Ketinggian Pemerintah Menjauhi WASPADA: tsunami kurang daerah/BPBD pantai dan MENJAUHI dari ½ meter. setempat segera tepian sungai, PANTAI & mengarahkan mencari TEPIAN masyarakat informasi SUNGAI menjauhi pantai dan tepian sungai.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2741, '1. PERINGATAN DINI BAHAYA BENCANA PERINGATAN DINI BENCANA BERBASIS MASYARAKAT: TANDA ALAM KEJADIAN DAN PENGETAHUAN LOKAL GEMPA TANDA PERINGATAN SARAN TINDAKAN ORANG Jika gempabumi terasa sedikit tapi Menjauhi pantai dan tepi sungai, ke berlangsung lama tempat yang telah ditentukan dan mencari informasi 5-10 MENIT Jika gempa bumi terasa kuat dan SETELAH berlangsung lama (misalnya lebih dari 1 menit dan orang tidak bisa GEMPA berdiri) PERINGATAN DINI BENCANA RESMI OLEH BMKG MELALUI: SIARAN TV/RADIO, SIRENE PERINGATAN TSUNAMI TINGKAT PERKIRAAN SARAN TINDAKAN SARAN PERINGATAN TINGGI PEMERINTAH TINDAKAN TSUNAMI GELOMBANG DAERAH ORANG (LEVEL) WAKTU STATUS Ketinggian Pemerintah Evakuasi KEDATA-NGAN AWAS: tsunami lebih dari daerah/BPBD daerah bahaya, TSUNAMI EVAKUASI 3 meter setempat segera pergi ke tempat SEGERA mengekauasi aman yang masyarakat ke sudah tempat aman. disepakati, 18 – 33 MENIT menunggu informasi STATUS Ketinggian Pemerintah Evakuasi SIAGA: tsunami antara ½ daerah/BPBD daerah bahaya, EVAKUASI meter – 3 meter setempat segera pergi ke tempat SEGERA mengekauasi aman yang masyarakat ke sudah tempat evakuasi disepakati, terdekat. mencari informasi STATUS Ketinggian Pemerintah Menjauhi WASPADA: tsunami kurang daerah/BPBD pantai dan MENJAUHI dari ½ meter. setempat segera tepian sungai, PANTAI & mengarahkan mencari TEPIAN masyarakat informasi SUNGAI menjauhi pantai dan tepian sungai.', 'Lampiran hal. 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2023 tentang Penyusunan Rencana Kontingensi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2742, 'perban-2-2023', 48, 'lampiran', 'Lampiran hal. 27', NULL, 27, 'INFO GEMPA: Kembali ke TIDAK ADA aktivitas normal ANCAMAN (tergantung tingkat kerusakan akibat gempa) Gambar 1. Matrik Peringatan dan Respon Tindakan, Kabupaten Malang, Tsunami Megatrust
2. PEMICU EVAKUASI § Gempa dirasakan diatas 6,5 MMI di Desa Tambakrejo, tersedianya EWS/Sirine (jangkauan kurang lebih 2-3 Km dari Titik-Sirene Terpasang) § Gempa dirasakan diatas 6,5 MMI di beberapa Desa § Orang menerima informasi peringatan dini bencana dari TV/Radio/SMS Orang melakukan evakuasi mandiri dengan tetap memperhatikan protokol kesehatan sesuai informasi peta/jalur evakuasi.
• Menuju titik aman (tidak ada rambu)
• Pilihan terdekat, menuju tempat kumpul terdekat mengikuti jalur evakuasi (tempat evakuasi sementara, dilengkapi rambu)
• Pilihat terdekat, Menuju tempat pengungsian terdekat mengikuti jalur evakuasi (tempat evakuasi akhir, dilengkapi rambu)
3. STRATEGI EVAKUASI Perintah Evakuasi di Desa Tambakrejo mengikuti Komando dari Tim Siaga Desa/Forum PRB
• Komando untuk evakuasi dari Tim Siaga Desa/Forum PRB');
