INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2752, 'perban-2-2024', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2024 tentang Sistem Peringatan Dini Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2752, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2024 tentang Sistem Peringatan Dini Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2024 tentang Sistem Peringatan Dini Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2753, 'perban-2-2024', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk melindungi masyarakat dari dampak buruk yang diakibatkan oleh bencana, perlu penyelenggaraan layanan peringatan dini;
b. bahwa layanan peringatan dini untuk berbagai ancaman bencana sebagai bagian dari penyelenggaraan penanggulangan bencana, perlu ditingkatkan dengan mengintegrasikan ke dalam suatu sistem nasional;
c. bahwa untuk mewujudkan penyelenggaraan sistem peringatan dini bencana yang terintegrasi, diperlukan pengaturan mengenai sistem peringatan dini bencana;
d. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, dan huruf c, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Sistem Peringatan Dini Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2753, 'a. bahwa untuk melindungi masyarakat dari dampak buruk yang diakibatkan oleh bencana, perlu penyelenggaraan layanan peringatan dini;
b. bahwa layanan peringatan dini untuk berbagai ancaman bencana sebagai bagian dari penyelenggaraan penanggulangan bencana, perlu ditingkatkan dengan mengintegrasikan ke dalam suatu sistem nasional;
c. bahwa untuk mewujudkan penyelenggaraan sistem peringatan dini bencana yang terintegrasi, diperlukan pengaturan mengenai sistem peringatan dini bencana;
d. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, dan huruf c, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Sistem Peringatan Dini Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2024 tentang Sistem Peringatan Dini Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2754, 'perban-2-2024', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
3. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);
5. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah (Berita Negara Republik Indonesia Tahun 2022 Nomor 282);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2754, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
3. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);
5. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah (Berita Negara Republik Indonesia Tahun 2022 Nomor 282);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2024 tentang Sistem Peringatan Dini Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2755, 'perban-2-2024', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG SISTEM PERINGATAN DINI BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2755, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG SISTEM PERINGATAN DINI BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2024 tentang Sistem Peringatan Dini Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2756, 'perban-2-2024', 4, 'pasal', 'Pasal 1', 'BAB II KARAKTERISTIK SISTEM PERINGATAN DINI BENCANA; Bagian Kesatu Komponen Utama Sistem Peringatan Dini Bencana', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Bahaya adalah suatu situasi, kondisi, atau karakteristik biologis, geografis, sosial, ekonomi, politik, budaya dan teknologi suatu masyarakat di suatu wilayah untuk jangka waktu tertentu yang berpotensi menimbulkan korban dan kerusakan.
3. Peringatan Dini Bencana adalah serangkaian kegiatan pemberian peringatan sesegera mungkin kepada masyarakat tentang kemungkinan terjadinya Bencana pada suatu tempat oleh Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah.
4. Sistem Peringatan Dini Bencana adalah sebuah sistem terintegrasi yang mencakup pemantauan ancaman, peramalan dan prediksi, pengkajian risiko Bencana, aktivitas komunikasi dan Kesiapsiagaan, yang memungkinkan individu, komunitas, pemerintah, lembaga usaha, dan pihak-pihak lain mengambil tindakan tepat waktu untuk mengurangi risiko Bencana.
5. Platform Sistem Peringatan Dini Bencana yang selanjutnya disebut Platform adalah sistem yang terdiri dari kombinasi perangkat keras dan perangkat lunak yang menjalankan Program peringatan dini multi ancaman Bahaya yang dikelola oleh BNPB.
6. Aksi Merespon Peringatan Dini adalah serangkaian tindakan yang dilaksanakan oleh Pemerintah dan/atau masyarakat untuk mengantisipasi dampak, menyelamatkan nyawa, dan mengurangi kerugian serta kerusakan yang ditimbulkan akibat Bencana dengan berbasis pada prakiraan dan deteksi dini potensi Bencana.
7. Kesiapsiagaan adalah serangkaian kegiatan yang dilakukan untuk mengantisipasi Bencana melalui pengorganisasian serta melalui langkah yang tepat guna dan berdaya guna.
8. Kerentanan adalah suatu kondisi dari suatu komunitas atau masyarakat yang mengarah atau menyebabkan ketidakmampuan dalam menghadapi ancaman Bencana.
9. Kapasitas adalah kemampuan daerah dan masyarakat untuk melakukan tindakan pengurangan tingkat ancaman dan tingkat kerugian akibat Bencana.
10. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat Bencana pada suatu wilayah dan kurun waktu tertentu yang dapat merupakan kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, mengungsi, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
11. Interoperabilitas Data adalah kemampuan data untuk dibagipakaikan antar sistem elektronik yang saling berinteraksi.
12. Interkoneksi Sistem adalah keterhubungan berbagai sistem dari penyelenggara sistem yang berbeda.
13. Integrasi adalah kemampuan interkoneksi dan Interoperabilitas Data suatu sistem.
14. Pengguna Data adalah Instansi Pusat dan Instansi Daerah, perseorangan, kelompok orang, atau badan hukum yang menggunakan Data.
15. Pengelola Informasi adalah kelompok kerja yang melaksanakan tata kelola Sistem Peringatan Dini Bencana.
16. Pemerintah Pusat yang selanjutnya disebut Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
17. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara Pemerintahan Daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
18. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah non-kementerian sesuai dengan ketentuan peraturan perundang-undangan.
19. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.');
