INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2827, 'perban-2-2026', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2827, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2828, 'perban-2-2026', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa penyelenggaraan penanggulangan bencana wajib memperhatikan prinsip kemanusiaan, keadilan, kesetaraan dan inklusivitas agar dapat melindungi dan memenuhi hak warga negara dalam setiap aspek penyelenggaraan penangggulangan bencana;
b. bahwa penyelenggaraan penanggulangan bencana yang responsif gender perlu dilaksanakan untuk memastikan pemenuhan hak dan kebutuhan perempuan, laki-laki, anak, lansia, penyandang disabilitas, dan kelompok berisiko lainnya secara adil, setara, inklusi, dan bermartabat; c bahwa Peraturan Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana sudah tidak sesuai dengan kebutuhan perkembangan hukum, sehingga perlu diganti;
d. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, dan huruf c, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Pengarusutamaan Gender dalam Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2828, 'a. bahwa penyelenggaraan penanggulangan bencana wajib memperhatikan prinsip kemanusiaan, keadilan, kesetaraan dan inklusivitas agar dapat melindungi dan memenuhi hak warga negara dalam setiap aspek penyelenggaraan penangggulangan bencana;
b. bahwa penyelenggaraan penanggulangan bencana yang responsif gender perlu dilaksanakan untuk memastikan pemenuhan hak dan kebutuhan perempuan, laki-laki, anak, lansia, penyandang disabilitas, dan kelompok berisiko lainnya secara adil, setara, inklusi, dan bermartabat; c bahwa Peraturan Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana sudah tidak sesuai dengan kebutuhan perkembangan hukum, sehingga perlu diganti;
d. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, dan huruf c, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Pengarusutamaan Gender dalam Penanggulangan Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2829, 'perban-2-2026', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 769) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2025 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 1159);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2829, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 769) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2025 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 1159);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2830, 'perban-2-2026', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2830, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2831, 'perban-2-2026', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Gender adalah nilai, peran, dan tanggung jawab perempuan dan laki-laki yang dikonstruksikan secara sosial dan budaya masyarakat.
2. Kesetaraan Gender adalah kondisi dan kedudukan yang setara antara laki-laki dan perempuan untuk memperoleh hak-haknya sebagai manusia dalam mengakses dan mengontrol sumber daya, berpartisipasi di seluruh proses pembangunan dan pengambilan keputusan, serta memperoleh manfaat dari pembangunan.
3. Pengarusutamaan Gender yang selanjutnya disebut PUG adalah strategi untuk mewujudkan Kesetaraan Gender, melalui integrasi perspektif Gender ke dalam proses pembangunan yang mencakup penyusunan kebijakan, perencanaan dan penganggaran, pelaksanaan, pemantauan, evaluasi, pengawasan, dan pelaporan.
4. Penyelenggaraan PUG dalam Penanggulangan Bencana yang selanjutnya disebut Penyelenggaraan PUG adalah seluruh proses pelembagaan dan tata kelola pengintegrasian perspektif Gender dalam proses pembangunan nasional, daerah provinsi, dan daerah kabupaten/kota dalam penanggulangan bencana.
5. Analisis Gender adalah proses analisis data Gender secara sistematis tentang kondisi laki-laki dan perempuan khususnya berkaitan dengan tingkat akses, partisipasi, kontrol dan perolehan manfaat dalam proses pembangunan untuk mengungkapkan akar permasalahan terjadinya ketimpangan kedudukan, fungsi, peran dan tanggung jawab antara laki-laki dan perempuan.
6. Gender Analysis Pathway yang selanjutnya disingkat GAP adalah metode analisis yang digunakan untuk mengidentifikasi dan mengatasi kesenjangan Gender serta hambatan inklusi sosial melalui identifikasi isu, analisis penyebab, penyusunan rencana aksi responsif gender dan inklusif, serta penetapan pihak yang bertanggung jawab dalam pelaksanaannya guna memastikan terpenuhinya akses, partisipasi, kontrol, dan manfaat yang setara bagi seluruh kelompok masyarakat.
7. Gender Action Budget yang selanjutnya disingkat GAB adalah dokumen perencanaan dan penganggaran responsif Gender yang disusun berdasarkan hasil GAP untuk mengatasi kesenjangan Gender melalui program dan kegiatan yang dilengkapi dengan tujuan, sasaran, indikator, target, dan alokasi anggaran.
8. Gender Monitoring Checklist yang selanjutnya disingkat GMC adalah instrumen pemantauan berupa daftar periksa yang digunakan untuk menilai dan memastikan bahwa kebijakan, program, dan kegiatan telah dilaksanakan secara responsif Gender berdasarkan prinsip akses, partisipasi, kontrol, dan manfaat yang setara.
9. Responsif Gender adalah perhatian secara konsisten dan sistematis untuk merespons kebutuhan, permasalahan, aspirasi, dan pengalaman perempuan dan laki-laki yang bertujuan untuk mewujudkan Kesetaraan Gender.
10. Perencanaan dan Penganggaran Responsif Gender yang selanjutnya disingkat PPRG adalah upaya sistematis untuk mengintegrasikan Gender ke dalam perencanaan dan penganggaran.
11. Perencanaan Responsif Gender adalah penyusunan rencana yang meliputi kebijakan, program dan kegiatan penanggulangan bencana untuk mencapai kesetaraan dan keadilan gender, yang dilakukan melalui pengintegrasian pengalaman, aspirasi, kebutuhan, potensi, dan penyelesaian permasalahan Perempuan dan laki-laki.
12. Penganggaran Responsif Gender adalah anggaran yang mengakomodasi keadilan bagi perempuan dan laki-laki dalam memperoleh akses, manfaat, dan berpartisipasi dalam pengambilan keputusan dan kontrol terhadap sumber daya, serta kesetaraan terhadap kesempatan dalam menikmati hasil pembangunan.
13. Anggaran Responsif Gender yang selanjutnya disingkat ARG adalah anggaran yang merespon kebutuhan, permasalahan, aspirasi dan pengalaman perempuan dan laki-laki yang bertujuan untuk mewujudkan Kesetaraan Gender.
14. Fasilitator Gender adalah seseorang yang berperan memfasilitasi proses PUG dalam berbagai program dan kegiatan baik di tingkat kebijakan maupun implementasi di lapangan.
15. Gender Champion adalah individu, tokoh masyarakat atau pejabat yang bertindak sebagai agen perubahan serta memiliki komitmen dan kontribusi nyata dalam mendorong Kesetaraan Gender dan pemberdayaan perempuan.
16. Focal Point Pengarustamaan Gender yang selanjutnya disebut Penggerak PUG adalah aparatur pada kementerian/lembaga dan/atau perangkat daerah yang mempunyai kemampuan dan ditunjuk untuk melakukan PUG di unit kerjanya masing- masing.
17. Kelompok Kerja PUG yang selanjutnya disebut Pokja PUG adalah wadah koordinasi, konsultasi, dan fasilitasi antarunit kerja dalam rangka Penyelenggaraan PUG.
18. Kelompok Berisiko Lainnya adalah individu atau kelompok masyarakat yang menghadapi tingkat keterpaparan, kerentanan, dan keterbatasan kapasitas yang lebih tinggi terhadap bencana yang memerlukan tindakan pelindungan, pemenuhan kebutuhan spesifik, dan dukungan yang proporsional dalam penyelenggaraan penanggulangan bencana.
19. Data Terpilah adalah nilai hasil pengamatan dan/atau pengukuran suatu variabel yang telah dikelompokkan menurut berbagai ciri, seperti jenis kelamin, wilayah, status sosial ekonomi, dan waktu.
20. Kekerasan Berbasis Gender yang selanjutnya disingkat KBG adalah kekerasan yang disebabkan perbedaan KGB Gender yang mengakibatkan penderitaan fisik, seksual, psikologis, dan/atau penelantaran.
21. Kerentanan Berlapis adalah keadaan yang dialami oleh individu atau kelompok yang memiliki dua atau lebih karakteristik atau kondisi yang menyebabkan kerentanan secara bersamaan yang meningkatkan risiko terdampak bencana dan mengurangi kemampuan untuk mengakses perlindungan, bantuan, serta layanan pemulihan.
22. Kajian Risiko Bencana Responsif Gender yang selanjutnya disingkat KRB-RG adalah pendekatan dalam manajemen bencana yang memastikan bahwa kebutuhan, kerentanan, dan kapasitas laki-laki dan perempuan diperhitungkan secara adil dan setara dalam seluruh siklus penanggulangan bencana, mulai dari perencanaan, mitigasi, kesiapsiagaan, tanggap darurat, hingga pemulihan.');
