22. Kajian Risiko Bencana Responsif Gender yang selanjutnya disingkat KRB-RG adalah pendekatan dalam manajemen bencana yang memastikan bahwa kebutuhan, kerentanan, dan kapasitas laki-laki dan perempuan diperhitungkan secara adil dan setara dalam seluruh siklus penanggulangan bencana, mulai dari perencanaan, mitigasi, kesiapsiagaan, tanggap darurat, hingga pemulihan.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2832, 'perban-2-2026', 5, 'pasal', 'Pasal 1 (lanjutan 1)', 'BAB I KETENTUAN UMUM', 4, '23. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintahan nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
24. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah perangkat daerah yang menyelenggarakan suburusan bencana.
25. Kepala BNPB adalah pimpinan lembaga pemerintah non-kementerian setingkat menteri yang melakukan penyelenggaraan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2832, '23. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintahan nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
24. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah perangkat daerah yang menyelenggarakan suburusan bencana.
25. Kepala BNPB adalah pimpinan lembaga pemerintah non-kementerian setingkat menteri yang melakukan penyelenggaraan penanggulangan bencana.', 'Pasal 1 (lanjutan 1)', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2833, 'perban-2-2026', 6, 'pasal', 'Pasal 2', 'BAB I KETENTUAN UMUM', 5, 'PUG dalam penanggulangan bencana bertujuan untuk:
a. melaksanakan prinsip keadilan dan Kesetaraan Gender dalam setiap komponen penyelenggaraan penanggulangan bencana;
b. mendorong Penyelenggaraan PUG dalam perencanaan, penganggaran, pelaksanaan, pemantauan, evaluasi, pengawasan dan pelaporan dalam penanggulangan bencana; dan
c. mendorong terwujudnya perlindungan dan pemenuhan hak perempuan, laki-laki, anak, lansia, penyandang disabilitas dan Kelompok Berisiko Lainnya dalam penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2833, 'PUG dalam penanggulangan bencana bertujuan untuk:
a. melaksanakan prinsip keadilan dan Kesetaraan Gender dalam setiap komponen penyelenggaraan penanggulangan bencana;
b. mendorong Penyelenggaraan PUG dalam perencanaan, penganggaran, pelaksanaan, pemantauan, evaluasi, pengawasan dan pelaporan dalam penanggulangan bencana; dan
c. mendorong terwujudnya perlindungan dan pemenuhan hak perempuan, laki-laki, anak, lansia, penyandang disabilitas dan Kelompok Berisiko Lainnya dalam penanggulangan bencana.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2834, 'perban-2-2026', 7, 'pasal', 'Pasal 3', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Kesatu Umum', 5, 'PUG dalam penanggulangan bencana dilaksanakan dengan memperhatikan perbedaan pengalaman, kebutuhan, kapasitas, dan kerentanan perempuan, dan laki-laki serta memastikan pelindungan dan pemenuhan hak anak, lansia, penyandang disabilitas, dan Kelompok Berisiko Lainnya pada tiap tahap penyelenggaraan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2834, 'PUG dalam penanggulangan bencana dilaksanakan dengan memperhatikan perbedaan pengalaman, kebutuhan, kapasitas, dan kerentanan perempuan, dan laki-laki serta memastikan pelindungan dan pemenuhan hak anak, lansia, penyandang disabilitas, dan Kelompok Berisiko Lainnya pada tiap tahap penyelenggaraan penanggulangan bencana.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2835, 'perban-2-2026', 8, 'pasal', 'Pasal 4', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Kesatu Umum', 5, 'Penyelenggaraan PUG mencakup:
a. proses pembangunan PUG; dan
b. pelembagaan PUG.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2835, 'Penyelenggaraan PUG mencakup:
a. proses pembangunan PUG; dan
b. pelembagaan PUG.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2836, 'perban-2-2026', 9, 'pasal', 'Pasal 5', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Kedua Proses Pembangunan PUG', 5, 'PUG dalam penanggulangan bencana dilaksanakan dengan menggunakan 4 (empat) indikator Gender yaitu:
a. akses;
b. partisipasi;
c. kontrol terhadap sumber daya dan pengambilan keputusan; dan
d. manfaat dari kebijakan dan program, sesuai dengan ketentuan peraturan perundang-undangan mengenai Parameter Kesetaraan Gender.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2836, 'PUG dalam penanggulangan bencana dilaksanakan dengan menggunakan 4 (empat) indikator Gender yaitu:
a. akses;
b. partisipasi;
c. kontrol terhadap sumber daya dan pengambilan keputusan; dan
d. manfaat dari kebijakan dan program, sesuai dengan ketentuan peraturan perundang-undangan mengenai Parameter Kesetaraan Gender.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2837, 'perban-2-2026', 10, 'pasal', 'Pasal 6', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Kedua Proses Pembangunan PUG', 5, 'Proses pembangunan PUG sebagaimana dimaksud dalam Pasal 4 huruf a dilaksanakan melalui:
a. PPRG;
b. pelaksanaan program dan kegiatan;
c. pemantauan;
d. evaluasi;
e. pengawasan; dan
f. pelaporan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2837, 'Proses pembangunan PUG sebagaimana dimaksud dalam Pasal 4 huruf a dilaksanakan melalui:
a. PPRG;
b. pelaksanaan program dan kegiatan;
c. pemantauan;
d. evaluasi;
e. pengawasan; dan
f. pelaporan.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2838, 'perban-2-2026', 11, 'pasal', 'Pasal 7', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Kedua Proses Pembangunan PUG', 6, '(1) Perencanaan Responsif Gender dalam penanggulangan bencana mengacu pada rencana pembangunan jangka menengah nasional dan rencana pembangunan jangka menengah daerah.
(2) Perencanaan Responsif Gender pemerintah tertuang dalam rencana strategis dan rencana kerja pemerintah.
(3) Perencanaan Responsif Gender pemerintah daerah tertuang dalam rencana strategis dan rencana kerja pemerintah daerah.
(4) Perencanaan Responsif Gender bagi mitra pembangunan, organisasi masyarakat, organisasi perempuan, organisasi profesi, relawan, dan organisasi lainnya yang bergerak di bidang penanggulangan bencana tertuang dalam rencana kerja organisasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2838, '(1) Perencanaan Responsif Gender dalam penanggulangan bencana mengacu pada rencana pembangunan jangka menengah nasional dan rencana pembangunan jangka menengah daerah.
(2) Perencanaan Responsif Gender pemerintah tertuang dalam rencana strategis dan rencana kerja pemerintah.
(3) Perencanaan Responsif Gender pemerintah daerah tertuang dalam rencana strategis dan rencana kerja pemerintah daerah.
(4) Perencanaan Responsif Gender bagi mitra pembangunan, organisasi masyarakat, organisasi perempuan, organisasi profesi, relawan, dan organisasi lainnya yang bergerak di bidang penanggulangan bencana tertuang dalam rencana kerja organisasi.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2839, 'perban-2-2026', 12, 'pasal', 'Pasal 8', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Kedua Proses Pembangunan PUG', 6, '(1) Perencanaan Responsif Gender dilakukan berdasarkan Analisis Gender.
(2) Analisis Gender sebagaimana dimaksud pada ayat (1) menggunakan:
a. Data Terpilah; dan
b. metode GAP.
(3) Analisis Gender sebagaimana dimaksud pada ayat (2) dapat melibatkan akademisi dan/atau praktisi di bidang PUG dalam penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2839, '(1) Perencanaan Responsif Gender dilakukan berdasarkan Analisis Gender.
(2) Analisis Gender sebagaimana dimaksud pada ayat (1) menggunakan:
a. Data Terpilah; dan
b. metode GAP.
(3) Analisis Gender sebagaimana dimaksud pada ayat (2) dapat melibatkan akademisi dan/atau praktisi di bidang PUG dalam penanggulangan bencana.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2840, 'perban-2-2026', 13, 'pasal', 'Pasal 9', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Kedua Proses Pembangunan PUG', 6, '(1) Penganggaran Responsif Gender dalam penanggulangan bencana mengacu pada:
a. rencana strategis dan rencana kerja pemerintah untuk Pemerintah;
b. rencana strategis dan rencana kerja pemerintah daerah untuk pemerintah daerah; dan
c. rencana kerja organisasi untuk mitra pembangunan, organisasi masyarakat, organisasi perempuan, organisasi profesi, relawan, dan organisasi lainnya yang bergerak di bidang penanggulangan bencana.
(2) Penganggaran Responsif Gender sebagaimana dimaksud pada ayat (1) berupa ARG.
(3) ARG sebagaimana dimaksud pada ayat (2) harus dapat:
a. mengatasi masalah kesenjangan antara perempuan, laki-laki, anak, lansia, penyandang disabilitas, dan Kelompok Berisiko Lainnya dalam akses, partisipasi, kontrol terhadap sumber daya dan pengambilan keputusan, dan manfaat dari kebijakan dan program;
b. memperkuat pelembagaan PUG dalam hal ketersediaan Data Terpilah dan peningkatan kapasitas sumber daya manusia; dan
c. memenuhi kebutuhan dasar khusus perempuan, laki-laki, anak, lansia, penyandang disabilitas, dan Kelompok Berisiko Lainnya berdasarkan Analisis Gender.
(4) ARG sebagaimana yang dimaksud pada ayat (3) didokumentasikan dalam bentuk GAB.
(5) GAB sebagaimana dimaksud pada ayat (4) merupakan gambaran perencanaan dan penganggaran di dalam kerangka acuan kerja yang memuat informasi mengenai analisis situasi dan rencana aksi yang memuat program, kebijakan, dan kegiatan Responsif Gender.
(6) GAB sebagaimana dimaksud pada ayat (4) digunakan untuk:
a. pengajuan rencana kegiatan dan anggaran; dan
b. pelaksanaan penandaan anggaran (tagging) ARG yang tercantum pada rincian output.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2840, '(1) Penganggaran Responsif Gender dalam penanggulangan bencana mengacu pada:
a. rencana strategis dan rencana kerja pemerintah untuk Pemerintah;
b. rencana strategis dan rencana kerja pemerintah daerah untuk pemerintah daerah; dan
c. rencana kerja organisasi untuk mitra pembangunan, organisasi masyarakat, organisasi perempuan, organisasi profesi, relawan, dan organisasi lainnya yang bergerak di bidang penanggulangan bencana.
(2) Penganggaran Responsif Gender sebagaimana dimaksud pada ayat (1) berupa ARG.
(3) ARG sebagaimana dimaksud pada ayat (2) harus dapat:
a. mengatasi masalah kesenjangan antara perempuan, laki-laki, anak, lansia, penyandang disabilitas, dan Kelompok Berisiko Lainnya dalam akses, partisipasi, kontrol terhadap sumber daya dan pengambilan keputusan, dan manfaat dari kebijakan dan program;
b. memperkuat pelembagaan PUG dalam hal ketersediaan Data Terpilah dan peningkatan kapasitas sumber daya manusia; dan
c. memenuhi kebutuhan dasar khusus perempuan, laki-laki, anak, lansia, penyandang disabilitas, dan Kelompok Berisiko Lainnya berdasarkan Analisis Gender.
(4) ARG sebagaimana yang dimaksud pada ayat (3) didokumentasikan dalam bentuk GAB.
(5) GAB sebagaimana dimaksud pada ayat (4) merupakan gambaran perencanaan dan penganggaran di dalam kerangka acuan kerja yang memuat informasi mengenai analisis situasi dan rencana aksi yang memuat program, kebijakan, dan kegiatan Responsif Gender.
(6) GAB sebagaimana dimaksud pada ayat (4) digunakan untuk:
a. pengajuan rencana kegiatan dan anggaran; dan
b. pelaksanaan penandaan anggaran (tagging) ARG yang tercantum pada rincian output.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2841, 'perban-2-2026', 14, 'pasal', 'Pasal 10', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Kedua Proses Pembangunan PUG', 7, '(1) Pelaksanaan program dan kegiatan sebagaimana dimaksud dalam Pasal 6 huruf b dengan memperhatikan hasil Analisis Gender dan ARG.
(2) Pelaksanaan program dan kegiatan sebagaimana dimaksud pada ayat (1) menjamin akses, partisipasi, kontrol terhadap sumber daya dan pengambilan keputusan, dan manfaat dari kebijakan dan program setara bagi perempuan, laki-laki, anak, lansia, penyandang disabilitas, dan Kelompok Berisiko Lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2841, '(1) Pelaksanaan program dan kegiatan sebagaimana dimaksud dalam Pasal 6 huruf b dengan memperhatikan hasil Analisis Gender dan ARG.
(2) Pelaksanaan program dan kegiatan sebagaimana dimaksud pada ayat (1) menjamin akses, partisipasi, kontrol terhadap sumber daya dan pengambilan keputusan, dan manfaat dari kebijakan dan program setara bagi perempuan, laki-laki, anak, lansia, penyandang disabilitas, dan Kelompok Berisiko Lainnya.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2842, 'perban-2-2026', 15, 'pasal', 'Pasal 11', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Kedua Proses Pembangunan PUG', 7, '(1) BNPB, BPBD, mitra pembangunan, organisasi masyarakat, organisasi perempuan, organisasi profesi, relawan, dan organisasi lainnya yang bergerak di bidang penanggulangan bencana melakukan pemantauan sebagaimana dimaksud dalam Pasal 6 huruf c terhadap:
a. pelaksanaan GAP dan GAB; dan
b. capaian output dari rencana output yang di-dilakukan penandaan anggaran (tagging) ARG dengan menggunakan alat analisis GMC, sesuai kewenangannya.
(2) Pemantauan sebagaimana dimaksud pada ayat (1) dilaksanakan terhadap pelaksanaan program dan kegiatan.
(3) Hasil pemantauan disusun dalam bentuk laporan setiap 3 (tiga) bulan.
(4) Ketentuan mengenai mekanisme pelaksanaan pemantauan ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2842, '(1) BNPB, BPBD, mitra pembangunan, organisasi masyarakat, organisasi perempuan, organisasi profesi, relawan, dan organisasi lainnya yang bergerak di bidang penanggulangan bencana melakukan pemantauan sebagaimana dimaksud dalam Pasal 6 huruf c terhadap:
a. pelaksanaan GAP dan GAB; dan
b. capaian output dari rencana output yang di-dilakukan penandaan anggaran (tagging) ARG dengan menggunakan alat analisis GMC, sesuai kewenangannya.
(2) Pemantauan sebagaimana dimaksud pada ayat (1) dilaksanakan terhadap pelaksanaan program dan kegiatan.
(3) Hasil pemantauan disusun dalam bentuk laporan setiap 3 (tiga) bulan.
(4) Ketentuan mengenai mekanisme pelaksanaan pemantauan ditetapkan oleh Kepala BNPB.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2843, 'perban-2-2026', 16, 'pasal', 'Pasal 12', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Kedua Proses Pembangunan PUG', 8, '(1) BNPB, BPBD, mitra pembangunan, organisasi masyarakat, organisasi perempuan, organisasi profesi, relawan, dan organisasi lainnya yang bergerak di bidang penanggulangan bencana melakukan evaluasi sebagaimana dimaksud dalam Pasal 6 huruf d terhadap pelaksanaan program dan kegiatan sesuai dengan kewenangannya.
(2) Evaluasi sebagaimana dimaksud pada ayat (1) dilakukan melalui analisis atas program, kebijakan, dan capaian output sesuai dengan ketentuan peraturan perundang-undangan.
(3) Ketentuan mengenai mekanisme evaluasi sebagaimana dimaksud pada ayat (1) ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2843, '(1) BNPB, BPBD, mitra pembangunan, organisasi masyarakat, organisasi perempuan, organisasi profesi, relawan, dan organisasi lainnya yang bergerak di bidang penanggulangan bencana melakukan evaluasi sebagaimana dimaksud dalam Pasal 6 huruf d terhadap pelaksanaan program dan kegiatan sesuai dengan kewenangannya.
(2) Evaluasi sebagaimana dimaksud pada ayat (1) dilakukan melalui analisis atas program, kebijakan, dan capaian output sesuai dengan ketentuan peraturan perundang-undangan.
(3) Ketentuan mengenai mekanisme evaluasi sebagaimana dimaksud pada ayat (1) ditetapkan oleh Kepala BNPB.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2844, 'perban-2-2026', 17, 'pasal', 'Pasal 13', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Kedua Proses Pembangunan PUG', 8, '(1) BNPB, BPBD, mitra pembangunan, organisasi masyarakat, organisasi perempuan, organisasi profesi, relawan, dan organisasi lainnya yang bergerak di bidang penanggulangan bencana melakukan pengawasan sebagaimana dimaksud dalam Pasal 6 huruf e terhadap perencanaan, penganggaran, dan pelaksanaan PUG dalam penanggulangan bencana sesuai dengan kewenangannya.
(2) Pengawasan sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai ketentuan peraturan perundang-undangan.
(3) Hasil pengawasan menjadi dasar perbaikan kebijakan, perencanaan, penganggaran, dan pelaksanaan penanggulangan bencana yang Responsif Gender.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2844, '(1) BNPB, BPBD, mitra pembangunan, organisasi masyarakat, organisasi perempuan, organisasi profesi, relawan, dan organisasi lainnya yang bergerak di bidang penanggulangan bencana melakukan pengawasan sebagaimana dimaksud dalam Pasal 6 huruf e terhadap perencanaan, penganggaran, dan pelaksanaan PUG dalam penanggulangan bencana sesuai dengan kewenangannya.
(2) Pengawasan sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai ketentuan peraturan perundang-undangan.
(3) Hasil pengawasan menjadi dasar perbaikan kebijakan, perencanaan, penganggaran, dan pelaksanaan penanggulangan bencana yang Responsif Gender.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2845, 'perban-2-2026', 18, 'pasal', 'Pasal 14', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Ketiga Pelembagaan Pengarusutamaan Gender', 8, '(1) BNPB, BPBD, mitra pembangunan, organisasi masyarakat, organisasi perempuan, organisasi profesi, relawan, dan organisasi lainnya yang bergerak di bidang penanggulangan bencana melakukan pelaporan sebagaimana dimaksud dalam Pasal 6 huruf f atas pelaksanaan PUG dalam penanggulangan bencana sesuai dengan kewenangannya.
(2) Pelaporan atas pelaksanaan PUG dalam penanggulangan bencana sebagaimana dimaksud pada ayat (1) dimuat dalam laporan kinerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2845, '(1) BNPB, BPBD, mitra pembangunan, organisasi masyarakat, organisasi perempuan, organisasi profesi, relawan, dan organisasi lainnya yang bergerak di bidang penanggulangan bencana melakukan pelaporan sebagaimana dimaksud dalam Pasal 6 huruf f atas pelaksanaan PUG dalam penanggulangan bencana sesuai dengan kewenangannya.
(2) Pelaporan atas pelaksanaan PUG dalam penanggulangan bencana sebagaimana dimaksud pada ayat (1) dimuat dalam laporan kinerja.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2846, 'perban-2-2026', 19, 'pasal', 'Pasal 15', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Ketiga Pelembagaan Pengarusutamaan Gender', 9, '(1) Pelembagaan PUG sebagaimana dimaksud dalam Pasal 4 huruf b merupakan komponen yang mendukung pelaksanaan PUG dalam penanggulangan bencana.
(2) Pelembagaan PUG sebagaimana dimaksud pada ayat (1) terdiri atas:
a. kebijakan;
b. sumber daya manusia dan internalisasi PUG; dan
c. Data Terpilah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2846, '(1) Pelembagaan PUG sebagaimana dimaksud dalam Pasal 4 huruf b merupakan komponen yang mendukung pelaksanaan PUG dalam penanggulangan bencana.
(2) Pelembagaan PUG sebagaimana dimaksud pada ayat (1) terdiri atas:
a. kebijakan;
b. sumber daya manusia dan internalisasi PUG; dan
c. Data Terpilah.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2026 tentang Pengarusutamaan Gender dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2847, 'perban-2-2026', 20, 'pasal', 'Pasal 16', 'BAB II PENYELENGGARAAN PENGARUSUTAMAAN GENDER DALAM PENANGGULANGAN BENCANA; Bagian Ketiga Pelembagaan Pengarusutamaan Gender', 9, '(1) Kebijakan sebagaimana dimaksud dalam Pasal 15 ayat
(2) huruf a merupakan serangkaian peraturan perundang-undangan, instrumen hukum lainnya, dan arah strategis yang ditetapkan oleh pemerintah dan pemerintah daerah untuk menjamin integrasi perspektif Gender dalam proses pembangunan.
(2) Kebijakan sebagaimana dimaksud pada ayat (1) dipedomani oleh pelaksana PUG dalam penanggulangan bencana.
Gender');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2847, '(1) Kebijakan sebagaimana dimaksud dalam Pasal 15 ayat
(2) huruf a merupakan serangkaian peraturan perundang-undangan, instrumen hukum lainnya, dan arah strategis yang ditetapkan oleh pemerintah dan pemerintah daerah untuk menjamin integrasi perspektif Gender dalam proses pembangunan.
