INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2883, 'perban-3-2018', 11, 'pasal', 'Pasal 8', 'BAB IV PENANGANAN PENGUNGSI; Bagian Kesatu Umum', 8, 'Tanggung jawab BNPB, BPBD provinsi, dan BPBD kabupaten/kota dalam Penanganan Pengungsi meliputi:
