INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2883, 'Tanggung jawab BNPB, BPBD provinsi, dan BPBD kabupaten/kota dalam Penanganan Pengungsi meliputi:
a. pengelolaan data dan informasi pengungsi;
