INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2884, 'perban-3-2018', 12, 'pasal', 'Pasal 9', 'BAB IV PENANGANAN PENGUNGSI; Bagian Kedua Pengelolaan Data dan Informasi', 8, 'Penanganan Pengungsi dilaksanakan sesuai dengan kebutuhan pengungsi dan jenis bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2884, 'Penanganan Pengungsi dilaksanakan sesuai dengan kebutuhan pengungsi dan jenis bencana.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2885, 'perban-3-2018', 13, 'pasal', 'Pasal 10', 'BAB IV PENANGANAN PENGUNGSI; Bagian Kedua Pengelolaan Data dan Informasi', 8, 'Pengelolaan data dan informasi dalam Penanganan Pengungsi terintegrasi ke dalam Sistem Komando Penanganan Darurat Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2885, 'Pengelolaan data dan informasi dalam Penanganan Pengungsi terintegrasi ke dalam Sistem Komando Penanganan Darurat Bencana.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2886, 'perban-3-2018', 14, 'pasal', 'Pasal 11', 'BAB IV PENANGANAN PENGUNGSI; Bagian Kedua Pengelolaan Data dan Informasi', 8, '(1) Pengelolaan data dan informasi dalam Penanganan Pengungsi mencakup pengumpulan data, pengolahan data, dan diseminasi informasi.
(2) Pengumpulan data sebagaimana dimaksud pada ayat (1) terdiri atas:
a. penyiapan instrumen data; dan
b. kegiatan pengumpulan data.
2018, No. 827
(3) Pengolahan data sebagaimana dimaksud pada ayat (1) terdiri atas:
a. verifikasi dan validasi data; dan
b. analisis dan interpretasi data.
(4) Diseminasi informasi sebagaimana dimaksud pada ayat
(1) terdiri atas:
a. sosialisasi informasi; dan
b. penyebaran informasi.
(5) Pengelolaan data dan informasi sebagaimana dimaksud pada ayat (1) dapat dilakukan dengan aplikasi berbasis sistem operasi telepon seluler dan komputer.
(6) Ketentuan lebih lanjut mengenai pengelolaan data dan informasi diatur dengan Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2886, '(1) Pengelolaan data dan informasi dalam Penanganan Pengungsi mencakup pengumpulan data, pengolahan data, dan diseminasi informasi.
(2) Pengumpulan data sebagaimana dimaksud pada ayat (1) terdiri atas:
a. penyiapan instrumen data; dan
b. kegiatan pengumpulan data.
2018, No. 827
(3) Pengolahan data sebagaimana dimaksud pada ayat (1) terdiri atas:
a. verifikasi dan validasi data; dan
b. analisis dan interpretasi data.
(4) Diseminasi informasi sebagaimana dimaksud pada ayat
(1) terdiri atas:
a. sosialisasi informasi; dan
b. penyebaran informasi.
(5) Pengelolaan data dan informasi sebagaimana dimaksud pada ayat (1) dapat dilakukan dengan aplikasi berbasis sistem operasi telepon seluler dan komputer.
(6) Ketentuan lebih lanjut mengenai pengelolaan data dan informasi diatur dengan Petunjuk Pelaksanaan.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2887, 'perban-3-2018', 15, 'pasal', 'Pasal 12', 'BAB IV PENANGANAN PENGUNGSI; Bagian Kedua Pengelolaan Data dan Informasi', 9, 'Pengelolaan data dan informasi dalam Penanganan Pengungsi sebagaimana dimaksud dalam Pasal 11 ayat (1) meliputi:
a. pendataan Pengungsi dapat dilakukan dengan aplikasi berbasis sistem operasi telepon seluler dan komputer;
b. verifikasi dan validasi data dilakukan oleh petugas pendataan di Tempat Pengungsian;
c. penyebarluasan data dan informasi dilakukan oleh pos komando penanganan darurat bencana melalui media center dapat menggunakan media cetak, media elektronik, dan website;
d. data sebagaimana dimaksud dalam Pasal 11 ayat (2) diprioritaskan mengenai jumlah Pengungsi berdasar nama dan alamat, usia, status, jenis kelamin, kelompok rentan, jumlah dan jenis kebutuhan dasar serta jumlah dan jenis barang bantuan; dan
e. pengarsipan dan pemutakhiran data Penanganan Pengungsi dilakukan secara periodik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2887, 'Pengelolaan data dan informasi dalam Penanganan Pengungsi sebagaimana dimaksud dalam Pasal 11 ayat (1) meliputi:
a. pendataan Pengungsi dapat dilakukan dengan aplikasi berbasis sistem operasi telepon seluler dan komputer;
b. verifikasi dan validasi data dilakukan oleh petugas pendataan di Tempat Pengungsian;
c. penyebarluasan data dan informasi dilakukan oleh pos komando penanganan darurat bencana melalui media center dapat menggunakan media cetak, media elektronik, dan website;
d. data sebagaimana dimaksud dalam Pasal 11 ayat (2) diprioritaskan mengenai jumlah Pengungsi berdasar nama dan alamat, usia, status, jenis kelamin, kelompok rentan, jumlah dan jenis kebutuhan dasar serta jumlah dan jenis barang bantuan; dan
e. pengarsipan dan pemutakhiran data Penanganan Pengungsi dilakukan secara periodik.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2888, 'perban-3-2018', 16, 'pasal', 'Pasal 13', 'BAB IV PENANGANAN PENGUNGSI; Bagian Ketiga Perlindungan dan Pemberdayaan Pengungsi', 9, '(1) Data dan informasi mengenai jumlah dan jenis barang bantuan sebagaimana dimaksud dalam Pasal 12 huruf d meliputi:
2018, No. 827 -10-
a. jumlah dan jenis barang bantuan yang akan didistribusikan sesuai dengan kebutuhan Pengungsi;
b. rencana kebutuhan distribusi barang bantuan dan penyimpanan barang; dan
c. kualitas dan kuantitas dari barang bantuan yang didistribusikan.
(2) penyebarluasan informasi distribusi barang bantuan yang berasal dari Pemberi Bantuan dilakukan oleh pos komando penanganan darurat bencana.
(3) Pemberi Bantuan wajib memberikan informasi sebagaimana dimaksud pada ayat (1) kepada pos komando penanganan darurat bencana atau pos lapangan.
(4) Pemberi Bantuan dapat memberikan bantuan secara langsung kepada Pengungsi setelah tercatat dan mendapat persetujuan dari pos komando penanganan darurat bencana atau pos lapangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2888, '(1) Data dan informasi mengenai jumlah dan jenis barang bantuan sebagaimana dimaksud dalam Pasal 12 huruf d meliputi:
2018, No. 827 -10-
a. jumlah dan jenis barang bantuan yang akan didistribusikan sesuai dengan kebutuhan Pengungsi;
b. rencana kebutuhan distribusi barang bantuan dan penyimpanan barang; dan
c. kualitas dan kuantitas dari barang bantuan yang didistribusikan.
(2) penyebarluasan informasi distribusi barang bantuan yang berasal dari Pemberi Bantuan dilakukan oleh pos komando penanganan darurat bencana.
(3) Pemberi Bantuan wajib memberikan informasi sebagaimana dimaksud pada ayat (1) kepada pos komando penanganan darurat bencana atau pos lapangan.
(4) Pemberi Bantuan dapat memberikan bantuan secara langsung kepada Pengungsi setelah tercatat dan mendapat persetujuan dari pos komando penanganan darurat bencana atau pos lapangan.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2889, 'perban-3-2018', 17, 'pasal', 'Pasal 14', 'BAB IV PENANGANAN PENGUNGSI; Bagian Ketiga Perlindungan dan Pemberdayaan Pengungsi', 10, 'Kegiatan Perlindungan Pengungsi pada Keadaan Darurat Bencana meliputi:
a. penyelamatan dan evakuasi;
b. penyediaan kebutuhan air bersih dan sanitasi;
c. penyediaan kebutuhan sandang dan pangan;
d. penyediaan layanan kesehatan dan psikososial;
e. penyediaan dan pengelolaan tempat pengungsian;
f. pengamanan dan ketertiban;
g. perlindungan dengan prioritas terhadap kelompok rentan;
h. pengarusutamaan gender; dan
i. penyediaan layanan pendidikan darurat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2889, 'Kegiatan Perlindungan Pengungsi pada Keadaan Darurat Bencana meliputi:
a. penyelamatan dan evakuasi;
b. penyediaan kebutuhan air bersih dan sanitasi;
c. penyediaan kebutuhan sandang dan pangan;
d. penyediaan layanan kesehatan dan psikososial;
e. penyediaan dan pengelolaan tempat pengungsian;
f. pengamanan dan ketertiban;
g. perlindungan dengan prioritas terhadap kelompok rentan;
h. pengarusutamaan gender; dan
i. penyediaan layanan pendidikan darurat.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2890, 'perban-3-2018', 18, 'pasal', 'Pasal 15', 'BAB IV PENANGANAN PENGUNGSI; Bagian Ketiga Perlindungan dan Pemberdayaan Pengungsi', 10, 'Pemberdayaan Pengungsi dilakukan untuk mengembalikan kehidupan Pengungsi yang lebih mandiri dan bermartabat.
2018, No. 827');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2890, 'Pemberdayaan Pengungsi dilakukan untuk mengembalikan kehidupan Pengungsi yang lebih mandiri dan bermartabat.
2018, No. 827', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2891, 'perban-3-2018', 19, 'pasal', 'Pasal 16', 'BAB IV PENANGANAN PENGUNGSI; Bagian Keempat Penempatan Pengungsi', 11, 'Kegiatan Pemberdayaan Pengungsi pada Keadaan Darurat Bencana meliputi:
a. pelibatan Pengungsi dalam pemberian layanan dalam penanganan darurat bencana;
b. pelibatan Pengungsi dalam pengelolaan bantuan dalam penanganan darurat bencana;
c. pengembangan jejaring komunikasi antar Pengungsi; dan
d. pemberdayaan ekonomi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2891, 'Kegiatan Pemberdayaan Pengungsi pada Keadaan Darurat Bencana meliputi:
a. pelibatan Pengungsi dalam pemberian layanan dalam penanganan darurat bencana;
b. pelibatan Pengungsi dalam pengelolaan bantuan dalam penanganan darurat bencana;
c. pengembangan jejaring komunikasi antar Pengungsi; dan
d. pemberdayaan ekonomi.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2892, 'perban-3-2018', 20, 'pasal', 'Pasal 17', 'BAB IV PENANGANAN PENGUNGSI; Bagian Keempat Penempatan Pengungsi', 11, 'Penempatan Pengungsi pada Keadaan Darurat Bencana terdiri atas penyiapan hunian sementara, pemulangan, dan relokasi.
Paragraf Kesatu Penyiapan Hunian Sementara');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2892, 'Penempatan Pengungsi pada Keadaan Darurat Bencana terdiri atas penyiapan hunian sementara, pemulangan, dan relokasi.
Paragraf Kesatu Penyiapan Hunian Sementara', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2893, 'perban-3-2018', 21, 'pasal', 'Pasal 18', 'BAB IV PENANGANAN PENGUNGSI; Bagian Keempat Penempatan Pengungsi', 11, 'Kegiatan penyiapan hunian sementara pada Keadaan Darurat Bencana meliputi:
a. mengidentifikasi lokasi potensial untuk tempat hunian sementara;
b. mengidentifikasi ketersediaan fasilitas umum dan sosial untuk tempat hunian sementara;
c. pembersihan lingkungan untuk tempat hunian sementara;
d. penyiapan dan atau pendirian hunian sementara; dan
e. mengidentifikasi karakteristik Pengungsi.
2018, No. 827 -12- Paragraf Kedua Pemulangan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2893, 'Kegiatan penyiapan hunian sementara pada Keadaan Darurat Bencana meliputi:
a. mengidentifikasi lokasi potensial untuk tempat hunian sementara;
b. mengidentifikasi ketersediaan fasilitas umum dan sosial untuk tempat hunian sementara;
c. pembersihan lingkungan untuk tempat hunian sementara;
d. penyiapan dan atau pendirian hunian sementara; dan
e. mengidentifikasi karakteristik Pengungsi.
2018, No. 827 -12- Paragraf Kedua Pemulangan', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2894, 'perban-3-2018', 22, 'pasal', 'Pasal 19', 'BAB IV PENANGANAN PENGUNGSI; Bagian Keempat Penempatan Pengungsi', 12, 'Kegiatan pemulangan Pengungsi meliputi:
a. studi kelayakan untuk pemulangan;
b. sosialisasi pemulangan;
c. pembersihan permukiman lokasi asal; dan
d. penyiapan sarana transportasi dan akomodasi.
Paragraf Ketiga Relokasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2894, 'Kegiatan pemulangan Pengungsi meliputi:
a. studi kelayakan untuk pemulangan;
b. sosialisasi pemulangan;
c. pembersihan permukiman lokasi asal; dan
d. penyiapan sarana transportasi dan akomodasi.
Paragraf Ketiga Relokasi', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2895, 'perban-3-2018', 23, 'pasal', 'Pasal 20', 'BAB IV PENANGANAN PENGUNGSI; Bagian Kelima Kompensasi dan Pengembalian Hak Pengungsi', 12, 'Kegiatan relokasi Pengungsi meliputi;
a. studi kelayakan tempat relokasi;
b. sosialisasi relokasi;
c. penyiapan lahan dan pengurusan izin lahan untuk relokasi;
d. pendirian tempat hunian untuk relokasi; dan
e. penyiapan sarana transportasi dan akomodasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2895, 'Kegiatan relokasi Pengungsi meliputi;
a. studi kelayakan tempat relokasi;
b. sosialisasi relokasi;
c. penyiapan lahan dan pengurusan izin lahan untuk relokasi;
d. pendirian tempat hunian untuk relokasi; dan
e. penyiapan sarana transportasi dan akomodasi.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2896, 'perban-3-2018', 24, 'pasal', 'Pasal 21', 'BAB IV PENANGANAN PENGUNGSI; Bagian Kelima Kompensasi dan Pengembalian Hak Pengungsi', 12, '(1) Pemerintah dan/atau pemerintah daerah memberikan kompensasi dan Pengembalian Hak Pengungsi berdasarkan azas kemanusiaan dan keadilan sesuai dengan ketentuan peraturan perundang-undangan.
(2) Pemberian kompensasi dan pengembalian hak dapat dilakukan oleh lembaga nonpemerintah, lembaga usaha, dan masyarakat.
(3) Kompensasi dan Pengembalian Hak Pengungsi dilakukan sejak Pengungsi berada di Tempat Pengungsian sampai dengan pemulangan atau direlokasi.
2018, No. 827');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2896, '(1) Pemerintah dan/atau pemerintah daerah memberikan kompensasi dan Pengembalian Hak Pengungsi berdasarkan azas kemanusiaan dan keadilan sesuai dengan ketentuan peraturan perundang-undangan.
(2) Pemberian kompensasi dan pengembalian hak dapat dilakukan oleh lembaga nonpemerintah, lembaga usaha, dan masyarakat.
(3) Kompensasi dan Pengembalian Hak Pengungsi dilakukan sejak Pengungsi berada di Tempat Pengungsian sampai dengan pemulangan atau direlokasi.
2018, No. 827', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2897, 'perban-3-2018', 25, 'pasal', 'Pasal 22', 'BAB IV PENANGANAN PENGUNGSI; Bagian Kelima Kompensasi dan Pengembalian Hak Pengungsi', 13, 'Kegiatan kompensasi dan Pengembalian Hak Pengungsi pada Keadaan Darurat Bencana meliputi:
a. pemberian upah kerja bagi yang dipekerjakan;
b. pemberian santunan;
c. pengembalian hak status kependudukan dan politik;
d. sosialisasi pemberian kompensasi dan pengembalian hak pengungsi;
e. pengurusan dokumen yang hilang;
f. pemberian bantuan dana stimulan perbaikan rumah;
g. pemberian bantuan penggantian bibit tanaman dan ternak;
h. pemberian bantuan biaya sewa rumah dan lahan usaha; dan
i. pemantauan proses pemberian kompensasi dan pengembalian hak.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2897, 'Kegiatan kompensasi dan Pengembalian Hak Pengungsi pada Keadaan Darurat Bencana meliputi:
a. pemberian upah kerja bagi yang dipekerjakan;
b. pemberian santunan;
c. pengembalian hak status kependudukan dan politik;
d. sosialisasi pemberian kompensasi dan pengembalian hak pengungsi;
e. pengurusan dokumen yang hilang;
f. pemberian bantuan dana stimulan perbaikan rumah;
g. pemberian bantuan penggantian bibit tanaman dan ternak;
h. pemberian bantuan biaya sewa rumah dan lahan usaha; dan
i. pemantauan proses pemberian kompensasi dan pengembalian hak.', 'Pasal 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2898, 'perban-3-2018', 26, 'pasal', 'Pasal 23', 'BAB V PERAN SERTA LEMBAGA NON-PEMERINTAH, LEMBAGA USAHA DAN MASYARAKAT', 13, 'Ketentuan lebih lanjut mengenai pelaksanaan Penanganan Pengungsi pada Keadaan Darurat Bencana diatur dengan Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2898, 'Ketentuan lebih lanjut mengenai pelaksanaan Penanganan Pengungsi pada Keadaan Darurat Bencana diatur dengan Petunjuk Pelaksanaan.', 'Pasal 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2899, 'perban-3-2018', 27, 'pasal', 'Pasal 24', 'BAB V PERAN SERTA LEMBAGA NON-PEMERINTAH, LEMBAGA USAHA DAN MASYARAKAT', 13, 'Dalam Penanganan Pengungsi, BNPB/BPBD melibatkan lembaga nonpemerintah, lembaga usaha dan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2899, 'Dalam Penanganan Pengungsi, BNPB/BPBD melibatkan lembaga nonpemerintah, lembaga usaha dan masyarakat.', 'Pasal 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2900, 'perban-3-2018', 28, 'pasal', 'Pasal 25', 'BAB VI MONITORING, EVALUASI DAN PELAPORAN', 13, 'Peran serta dalam Penanganan Pengungsi sebagaimana dimaksud dalam Pasal 24 meliputi:
a. pembiayaan;
b. bantuan teknis dan administrasi;
c. bantuan tenaga dan keahlian; dan
d. bantuan logistik dan peralatan.
2018, No. 827 -14-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2900, 'Peran serta dalam Penanganan Pengungsi sebagaimana dimaksud dalam Pasal 24 meliputi:
a. pembiayaan;
b. bantuan teknis dan administrasi;
c. bantuan tenaga dan keahlian; dan
d. bantuan logistik dan peralatan.
2018, No. 827 -14-', 'Pasal 25', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2901, 'perban-3-2018', 29, 'pasal', 'Pasal 26', 'BAB VI MONITORING, EVALUASI DAN PELAPORAN', 14, '(1) Monitoring, evaluasi, dan pelaporan dilakukan pada setiap kegiatan Penanganan Pengungsi.
(2) Monitoring, evaluasi, dan pelaporan dilaksanakan oleh BNPB, BPBD provinsi, dan bekerja sama dengan kementerian/lembaga, dan organisasi perangkat daerah, lembaga nonpemerintah, lembaga usaha, dan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2901, '(1) Monitoring, evaluasi, dan pelaporan dilakukan pada setiap kegiatan Penanganan Pengungsi.
(2) Monitoring, evaluasi, dan pelaporan dilaksanakan oleh BNPB, BPBD provinsi, dan bekerja sama dengan kementerian/lembaga, dan organisasi perangkat daerah, lembaga nonpemerintah, lembaga usaha, dan masyarakat.', 'Pasal 26', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2902, 'perban-3-2018', 30, 'pasal', 'Pasal 27', 'BAB VI MONITORING, EVALUASI DAN PELAPORAN', 14, 'Monitoring dan evaluasi sebagaimana dimaksud dalam Pasal 26 bertujuan untuk:
a. peningkatan kualitas pelaksanaan penanganan pengungsi; dan
b. pengukuran keberhasilan dari program yang sudah dilakukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2902, 'Monitoring dan evaluasi sebagaimana dimaksud dalam Pasal 26 bertujuan untuk:
a. peningkatan kualitas pelaksanaan penanganan pengungsi; dan
b. pengukuran keberhasilan dari program yang sudah dilakukan.', 'Pasal 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2018 tentang Penanganan Pengungsi Pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2903, 'perban-3-2018', 31, 'pasal', 'Pasal 28', 'BAB VI MONITORING, EVALUASI DAN PELAPORAN', 14, '(1) Pelaporan sebagaimana dimaksud dalam Pasal 26 meliputi:
a. laporan harian;
b. laporan akhir; dan
c. laporan terfokus.
(2) Laporan harian sebagaimana dimaksud pada ayat (1) huruf a yaitu laporan hasil kegiatan Penanganan Pengungsi yang disampaikan secara rutin setiap harinya.
(3) Laporan akhir sebagaimana dimaksud pada ayat (1) huruf b yaitu laporan akhir hasil pelaksanaan kegiatan Penanganan Pengungsi pada periode waktu tertentu.
(4) Laporan terfokus sebagaimana dimaksud pada ayat (1) huruf c yaitu laporan khusus yang hanya menggambarkan kegiatan tertentu saja dari Penanganan Pengungsi pada periode waktu tertentu.
2018, No. 827');
