INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2907, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2019 tentang Pemanfaatan Hibah Dari Pemerintah Pusat Kepada Pemerintah Daerah Untuk Bantuan Rehabilitasi dan Rekonstruksi Pascabencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2019 tentang Pemanfaatan Hibah Dari Pemerintah Pusat Kepada Pemerintah Daerah Untuk Bantuan Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2908, 'perban-3-2019', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk penanggulangan bencana pada tahap pascabencana telah ditetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2015 tentang Petunjuk Pelaksanaan Hibah dari Pemerintah Pusat kepada Pemerintah Daerah dalam rangka Bantuan Pendanaan Rehabilitasi dan Rekonstruksi Pascabencana;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2015 tentang Petunjuk Pelaksanaan Hibah dari Pemerintah Pusat kepada Pemerintah Daerah dalam rangka Bantuan Pendanaan Rehabilitasi dan Rekonstruksi Pascabencana dalam implementasinya sudah tidak sesuai dengan dinamika saat ini sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana 2019, No.741 -2- tentang Pemanfaatan Hibah Dari Pemerintah Pusat Kepada Pemerintah Daerah Untuk Bantuan Rehabilitasi dan Rekonstruksi Pascabencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2908, 'a. bahwa untuk penanggulangan bencana pada tahap pascabencana telah ditetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2015 tentang Petunjuk Pelaksanaan Hibah dari Pemerintah Pusat kepada Pemerintah Daerah dalam rangka Bantuan Pendanaan Rehabilitasi dan Rekonstruksi Pascabencana;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2015 tentang Petunjuk Pelaksanaan Hibah dari Pemerintah Pusat kepada Pemerintah Daerah dalam rangka Bantuan Pendanaan Rehabilitasi dan Rekonstruksi Pascabencana dalam implementasinya sudah tidak sesuai dengan dinamika saat ini sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana 2019, No.741 -2- tentang Pemanfaatan Hibah Dari Pemerintah Pusat Kepada Pemerintah Daerah Untuk Bantuan Rehabilitasi dan Rekonstruksi Pascabencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2019 tentang Pemanfaatan Hibah Dari Pemerintah Pusat Kepada Pemerintah Daerah Untuk Bantuan Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2909, 'perban-3-2019', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 24 tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah sebagaimana telah beberapa kali diubah terakhir dengan Undang-Undang Nomor 9 Tahun 2015 tentang Perubahan kedua atas Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2015 Nomor 58 Tambahan Lembaran Negara Republik Indonesia Nomor 5679);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 2 Tahun 2012 tentang Hibah Daerah (Lembaran Negara Republik Indonesia Tahun 2012 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 5272);
6. Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu (Lembaran Negara Republik Indonesia Tahun 2018 Nomor 34);
2019, No.741
7. Peraturan Menteri Keuangan Nomor 224/PMK.07/2017 tentang Pengelolaan Hibah dari Pemerintah Pusat kepada Pemerintah Daerah (Berita Negara Republik Indonesia Tahun 2017 Nomor 1969);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2909, '1. Undang-Undang Nomor 24 tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah sebagaimana telah beberapa kali diubah terakhir dengan Undang-Undang Nomor 9 Tahun 2015 tentang Perubahan kedua atas Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2015 Nomor 58 Tambahan Lembaran Negara Republik Indonesia Nomor 5679);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 2 Tahun 2012 tentang Hibah Daerah (Lembaran Negara Republik Indonesia Tahun 2012 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 5272);
6. Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu (Lembaran Negara Republik Indonesia Tahun 2018 Nomor 34);
2019, No.741
7. Peraturan Menteri Keuangan Nomor 224/PMK.07/2017 tentang Pengelolaan Hibah dari Pemerintah Pusat kepada Pemerintah Daerah (Berita Negara Republik Indonesia Tahun 2017 Nomor 1969);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2019 tentang Pemanfaatan Hibah Dari Pemerintah Pusat Kepada Pemerintah Daerah Untuk Bantuan Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2910, 'perban-3-2019', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEMANFAATAN HIBAH DARI PEMERINTAH PUSAT KEPADA PEMERINTAH DAERAH UNTUK BANTUAN REHABILITASI DAN REKONSTRUKSI PASCABENCANA');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2910, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEMANFAATAN HIBAH DARI PEMERINTAH PUSAT KEPADA PEMERINTAH DAERAH UNTUK BANTUAN REHABILITASI DAN REKONSTRUKSI PASCABENCANA', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2019 tentang Pemanfaatan Hibah Dari Pemerintah Pusat Kepada Pemerintah Daerah Untuk Bantuan Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2911, 'perban-3-2019', 4, 'pasal', 'Pasal 1', 'BAB II RUANG LINGKUP', 3, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Hibah dari pemerintah pusat kepada pemerintah daerah untuk bantuan rehabilitasi dan rekonstruksi pascabencana yang selanjutnya disebut Hibah adalah pemberian dengan pengalihan hak atas sesuatu dari pemerintah pusat kepada pemerintah daerah yang secara spesifik telah ditetapkan peruntukannya dan dilakukan melalui perjanjian.
2. Perjanjian Hibah Daerah yang selanjutnya disebut PHD adalah kesepakatan tertulis mengenai Hibah antara pemerintah pusat dan pemerintah daerah yang dituangkan dalam perjanjian.
3. Surat Penetapan Pemberian Hibah yang selanjutnya disingkat SPPH adalah surat yang diterbitkan oleh Menteri Keuangan atau pejabat yang diberi wewenang dan ditujukan kepada pemerintah daerah yang memuat kegiatan dan besaran Hibah yang bersumber dari penerimaan dalam negeri.
4. Rencana Kegiatan dan Anggaran yang selanjutnya disingkat RKA adalah dokumen yang memuat rincian 2019, No.741 -4- kegiatan dan besaran pendanaan Hibah yang disusun pemerintah daerah.
5. Dokumen Pelaksanaan Anggaran yang selanjutnya disingkat DPA adalah dokumen yang memuat pendapatan dan belanja pemerintah daerah yang digunakan sebagai dasar pelaksanaan oleh Pengguna Anggaran.
6. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pascabencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.
7. Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta masyarakat.
8. Anggaran Pendapatan dan Belanja Negara yang selanjutnya disingkat APBN adalah rencana keuangan tahunan pemerintahan negara yang disetujui oleh Dewan Perwakilan Rakyat yang ditetapkan dengan undang-undang.
9. Anggaran Pendapatan dan Belanja Daerah yang selanjutnya disingkat APBD adalah rencana keuangan tahunan pemerintahan daerah yang dibahas dan disetujui bersama oleh pemerintah daerah dan dewan perwakilan rakyat daerah, dan ditetapkan dengan peraturan daerah.
10. Rekening Kas Umum Negara, yang selanjutnya disingkat RKUN adalah rekening tempat penyimpanan uang negara yang ditentukan oleh Menteri Keuangan selaku Bendahara Umum Negara untuk menampung seluruh penerimaan negara dan membayar seluruh pengeluaran negara pada bank sentral.
2019, No.741
11. Rekening Kas Umum Daerah, yang selanjutnya disingkat RKUD adalah rekening tempat penyimpanan uang daerah yang ditentukan oleh gubernur/bupati/walikota untuk menampung seluruh penerimaan daerah dan membayar seluruh pengeluaran daerah pada bank yang ditetapkan.
12. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sesuai dengan ketentuan peraturan perundang-undangan.
13. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
14. Pemerintah Pusat yang selanjutnya disebut Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan Pemerintahan Negara Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
15. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara pemerintahan daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan perintah daerah otonom.');
