INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2931, 'perban-3-2020', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk menjamin ketersediaan dan keseragaman arsip yang autentik dan terpercaya diperlukan pengelolaan arsip dinamis yang sesuai dengan standar kearsipan,
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2009 tentang Tata Kearsipan Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana dan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2013 tentang Pedoman Penyusutan Arsip di Lingkungan Badan Nasional Penanggulangan Bencana perlu disesuaikan dengan perkembangan dan kebutuhan Badan Nasional Penanggulangan Bencana,
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Pengelolaan Arsip Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2931, 'a. bahwa untuk menjamin ketersediaan dan keseragaman arsip yang autentik dan terpercaya diperlukan pengelolaan arsip dinamis yang sesuai dengan standar kearsipan,
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2009 tentang Tata Kearsipan Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana dan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2013 tentang Pedoman Penyusutan Arsip di Lingkungan Badan Nasional Penanggulangan Bencana perlu disesuaikan dengan perkembangan dan kebutuhan Badan Nasional Penanggulangan Bencana,
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Pengelolaan Arsip Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2020 tentang Pengelolaan Arsip Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2932, 'perban-3-2020', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2932, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2020 tentang Pengelolaan Arsip Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2933, 'perban-3-2020', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENGELOLAAN ARSIP DINAMIS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2933, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENGELOLAAN ARSIP DINAMIS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2020 tentang Pengelolaan Arsip Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2934, 'perban-3-2020', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Pengelolaan arsip dinamis adalah proses pengendalian arsip dinamis secara efisien, efektif, dan sistematis meliputi penciptaan, penggunaan, dan pemeliharaan, serta penyusutan arsip.
2. Arsip dinamis adalah arsip yang digunakan secara langsung dalam kegiatan pencipta arsip dan disimpan selama jangka waktu tertentu.
3. Arsip vital adalah arsip yang keberadaannya merupakan persyaratan dasar bagi kelangsungan operasional pencipta arsip, tidak dapat diperbarui, dan tidak tergantikan apabila rusak atau hilang.
4. Arsip terjaga adalah arsip negara yang berkaitan dengan keberadaan dan kelangsungan hidup bangsa dan negara yang harus dijaga keutuhan, keamanan, dan keselamatannya.
5. Arsip aktif adalah arsip yang frekuensi penggunaannya tinggi dan/atau terus-menerus.
6. Arsip inaktif adalah arsip yang frekuensi penggunaannya telah menurun.
7. Penciptaan Arsip adalah kegiatan pembuatan dan penerimaan Arsip yang dilaksanakan berdasarkan tata naskah dinas, klasifikasi arsip, serta sistem klasifikasi keamanan dan akses arsip di lingkungan Badan Nasional Penanggulangan Bencana.
8. Pencipta Arsip adalah pihak yang mempunyai kemandirian dan otoritas dalam pelaksanaan fungsi, tugas, dan tanggung jawab di bidang pengelolaan arsip dinamis.
9. Klasifikasi Arsip adalah pola pengaturan Arsip secara berjenjang dari hasil pelaksanaan fungsi dan tugas instansi menjadi beberapa kategori unit informasi kearsipan.
10. Jadwal Retensi Arsip yang selanjutnya disingkat JRA adalah daftar yang berisi sekurang-kurangnya jangka waktu penyimpanan atau retensi, jenis arsip, dan keterangan yang berisi rekomendasi tentang penetapan suatu jenis arsip dimusnahkan, dinilai kembali, atau dipermanenkan yang digunakan sebagai pedoman penyusutan dan penyelamatan arsip.
11. Sistem Klasifikasi Keamanan dan Akses Arsip adalah aturan pembatasan hak akses terhadap fisik arsip dan informasinya sebagai dasar untuk menentukan keterbukaan dan kerahasiaan arsip dalam rangka melindungi hak dan kewajiban Pencipta Arsip dan pengguna dalam pelayanan arsip.
12. Arsiparis adalah seseorang yang memiliki kompetensi di bidang kearsipan yang diperoleh melalui pendidikan formal dan/atau pendidikan dan pelatihan kearsipan serta mempunyai fungsi, tugas, dan tanggung jawab melaksanakan kegiatan kearsipan.
13. Unit Kearsipan adalah unit kerja pada Pencipta Arsip di lingkungan Badan Nasional Penanggulangan Bencana yang mempunyai tugas dan tanggung jawab dalam Pengelolaan Arsip Dinamis.
14. Unit Pengolah adalah satuan kerja pada Badan Nasional Penanggulangan Bencana yang mempunyai tugas dan tanggung jawab mengolah semua arsip yang berkaitan dengan kegiatan penciptaan arsip di lingkungannya.
15. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nondepartemen sebagaimana dimaksud dalam Undang-Undang.
16. Unit Kerja adalah unit kerja yang dipimpin oleh jabatan tinggi pratama di lingkungan BNPB.');
