INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2977, 'perban-3-2020', 47, 'pasal', 'Pasal 44', 'BAB VI KETENTUAN PENUTUP', 28, 'Pada saat Peraturan Badan ini mulai berlaku:
