INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2985, 'Pada hari ini, …… tanggal ... bulan … tahun … Pukul … WIB, kami yang bertanda tangan di bawah ini telah menyaksikan pemusnahan arsip inaktif yang tidak memiliki nilai guna bagi pencipta arsip dan telah melampaui jangka simpan sesuai dengan Peraturan Kepala BNPB Nomor 18 tahun 2011 tentang Jadwal Retensi Arsip Fasilitatif Non Keuangan dan Non Kepegawaian BNPB, serta Peraturan Kepala BNPB Nomor 21 Tahun 2010 tentang Jadwal Retensi Arsip Keuangan BNPB, dengan cara dicacah dan dilebur oleh PT …, … (alamat) serta telah disetujui oleh Kepala ANRI berdasarkan surat Nomor … tanggal … tentang persetujuan pemusnahan arsip.
