INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2986, 'perban-3-2020', 56, 'lampiran', 'Lampiran hal. 42', NULL, 42, 'Pada hari ini … tanggal … bulan … tahun … bertempat di …, …, …. kami yang bertanda tangan di bawah ini:
