INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2989, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2990, 'perban-3-2022', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk melindungi dan menjamin keberlangsungan kehidupan masyarakat pada saat keadaan darurat bencana, perlu melakukan pemulihan dengan segera prasarana dan sarana vital,
b. bahwa agar pemulihan dengan segera prasarana dan sarana vital sebagaimana dimaksud dalam huruf a dapat terlaksana dengan cepat, tepat, efektif, efisien dan akuntabel, perlu dibentuk pengaturan sebagai acuan pelaksanaan,
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Pemulihan dengan Segera Prasarana dan Sarana Vital,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2990, 'a. bahwa untuk melindungi dan menjamin keberlangsungan kehidupan masyarakat pada saat keadaan darurat bencana, perlu melakukan pemulihan dengan segera prasarana dan sarana vital,
b. bahwa agar pemulihan dengan segera prasarana dan sarana vital sebagaimana dimaksud dalam huruf a dapat terlaksana dengan cepat, tepat, efektif, efisien dan akuntabel, perlu dibentuk pengaturan sebagai acuan pelaksanaan,
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Pemulihan dengan Segera Prasarana dan Sarana Vital,', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2991, 'perban-3-2022', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723):
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461),');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2991, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723):
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461),', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2992, 'perban-3-2022', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEMULIHAN DENGAN SEGERA PRASARANA DAN SARANA VITAL.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2992, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEMULIHAN DENGAN SEGERA PRASARANA DAN SARANA VITAL.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2993, 'perban-3-2022', 4, 'pasal', 'Pasal 1', 'BAB II KEGIATAN PEMULIHAN DENGAN SEGERA', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Pemulihan dengan Segera Prasarana Dan Sarana Vital yang selanjutnya disebut Pemulihan Dengan Segera adalah serangkaian upaya pengembalian fungsi prasarana dan sarana vital yang dilakukan dengan segera pada saat keadaan darurat bencana dan bertujuan agar kehidupan masyarakat terdampak bencana tetap berlangsung.
2. Sistem Komando Penanganan Darurat Bencana adalah satu kesatuan upaya terstruktur dalam satu komando yang digunakan untuk mengintegrasikan kegiatan penanganan darurat secara efektif dan efisien dalam mengendalikan ancaman/penyebab bencana dan menanggulangi dampak pada saat keadaan darurat bencana.
3. Pos Komando Penanganan Darurat Bencana yang selanjutnya disingkat Posko PDB adalah institusi yang berfungsi sebagai pusat komando operasi penanganan darurat bencana yang merupakan posko utama di dalam sistem komando penanganan darurat bencana, untuk mengoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan penanganan darurat bencana.
4. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan.
5. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2993, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Pemulihan dengan Segera Prasarana Dan Sarana Vital yang selanjutnya disebut Pemulihan Dengan Segera adalah serangkaian upaya pengembalian fungsi prasarana dan sarana vital yang dilakukan dengan segera pada saat keadaan darurat bencana dan bertujuan agar kehidupan masyarakat terdampak bencana tetap berlangsung.
2. Sistem Komando Penanganan Darurat Bencana adalah satu kesatuan upaya terstruktur dalam satu komando yang digunakan untuk mengintegrasikan kegiatan penanganan darurat secara efektif dan efisien dalam mengendalikan ancaman/penyebab bencana dan menanggulangi dampak pada saat keadaan darurat bencana.
3. Pos Komando Penanganan Darurat Bencana yang selanjutnya disingkat Posko PDB adalah institusi yang berfungsi sebagai pusat komando operasi penanganan darurat bencana yang merupakan posko utama di dalam sistem komando penanganan darurat bencana, untuk mengoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan penanganan darurat bencana.
4. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan.
5. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2994, 'perban-3-2022', 5, 'pasal', 'Pasal 2', 'BAB III PELAKSANAAN PEMULIHAN DENGAN SEGERA; Bagian Kesatu Umum', 3, '(1) Kegiatan Pemulihan Dengan Segera meliputi:
a. pembersihan lokasi terdampak bencana, dan
b. perbaikan darurat sarana dan prasarana vital.
(2) Pembersihan lokasi terdampak bencana sebagaimana dimaksud pada ayat (1) huruf a merupakan penyelenggaraan pembersihan dan/atau menyingkirkan bahan/barang akibat kejadian bencana yang mencakup:
a. puing-puing,
b. sampah, Cc. lumpur,
d. abu vulkanik,
e. bahan/barang yang rusak,
f. limbah bahan berbahaya dan beracun, dan/atau
g. bahan/barang akibat kejadian bencana lainnya yang mengganggu kehidupan masyarakat.
(3) Perbaikan darurat sarana dan prasarana vital sebagaimana dimaksud pada ayat (1) huruf b dilakukan terhadap:
a. jaringan air bersih/minum,
b. jaringan listrik dan lampu penerangan,
c. jaringan telekomunikasi,
d. jaringan irigasi,
e. jaringan jalan dan jembatan,
f. jaringan transportasi,
g. sarana pengisian bahan bakar umum, dan
h. fasilitas pelayanan umum dan pemerintahan.
(4) Jaringan transportasi sebagaimana dimaksud pada ayat (3) huruf f meliputi pelabuhan, bandara, terminal, dan stasiun.
(5) Fasilitas pelayanan umum dimaksud pada ayat (3) huruf h mencakup fasilitas layanan kesehatan, fasilitas layanan pendidikan, tempat ibadah, dan pasar.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2994, '(1) Kegiatan Pemulihan Dengan Segera meliputi:
a. pembersihan lokasi terdampak bencana, dan
b. perbaikan darurat sarana dan prasarana vital.
(2) Pembersihan lokasi terdampak bencana sebagaimana dimaksud pada ayat (1) huruf a merupakan penyelenggaraan pembersihan dan/atau menyingkirkan bahan/barang akibat kejadian bencana yang mencakup:
a. puing-puing,
b. sampah, Cc. lumpur,
d. abu vulkanik,
e. bahan/barang yang rusak,
f. limbah bahan berbahaya dan beracun, dan/atau
g. bahan/barang akibat kejadian bencana lainnya yang mengganggu kehidupan masyarakat.
(3) Perbaikan darurat sarana dan prasarana vital sebagaimana dimaksud pada ayat (1) huruf b dilakukan terhadap:
a. jaringan air bersih/minum,
b. jaringan listrik dan lampu penerangan,
c. jaringan telekomunikasi,
d. jaringan irigasi,
e. jaringan jalan dan jembatan,
f. jaringan transportasi,
g. sarana pengisian bahan bakar umum, dan
h. fasilitas pelayanan umum dan pemerintahan.
(4) Jaringan transportasi sebagaimana dimaksud pada ayat (3) huruf f meliputi pelabuhan, bandara, terminal, dan stasiun.
(5) Fasilitas pelayanan umum dimaksud pada ayat (3) huruf h mencakup fasilitas layanan kesehatan, fasilitas layanan pendidikan, tempat ibadah, dan pasar.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2995, 'perban-3-2022', 6, 'pasal', 'Pasal 3', 'BAB III PELAKSANAAN PEMULIHAN DENGAN SEGERA; Bagian Kedua Kaji Cepat Pemulihan Dengan Segera', 4, 'Tahapan pelaksanaan Pemulihan Dengan Segera terdiri atas:
a. kaji cepat Pemulihan Dengan Segera,
b. penyusunan rencana operasi Pemulihan Dengan Segera, dan
c. operasi Pemulihan Dengan Segera.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2995, 'Tahapan pelaksanaan Pemulihan Dengan Segera terdiri atas:
a. kaji cepat Pemulihan Dengan Segera,
b. penyusunan rencana operasi Pemulihan Dengan Segera, dan
c. operasi Pemulihan Dengan Segera.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2996, 'perban-3-2022', 7, 'pasal', 'Pasal 4', 'BAB III PELAKSANAAN PEMULIHAN DENGAN SEGERA; Bagian Kedua Kaji Cepat Pemulihan Dengan Segera', 5, '(1) Kaji cepat Pemulihan Dengan Segera sebagaimana dimaksud dalam Pasal 3 huruf a merupakan penilaian situasi secara cepat dan tepat untuk menentukan tingkat kerusakan dan kebutuhan upaya Pemulihan Dengan Segera.
(2) Pelaksanaan kaji cepat Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (1) berupa:
a. penilaian tingkat kerusakan prasarana dan sarana vital di lokasi terdampak bencana, dan
b. penilaian kebutuhan untuk Pemulihan Dengan Segera.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2996, '(1) Kaji cepat Pemulihan Dengan Segera sebagaimana dimaksud dalam Pasal 3 huruf a merupakan penilaian situasi secara cepat dan tepat untuk menentukan tingkat kerusakan dan kebutuhan upaya Pemulihan Dengan Segera.
(2) Pelaksanaan kaji cepat Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (1) berupa:
a. penilaian tingkat kerusakan prasarana dan sarana vital di lokasi terdampak bencana, dan
b. penilaian kebutuhan untuk Pemulihan Dengan Segera.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2997, 'perban-3-2022', 8, 'pasal', 'Pasal 5', 'BAB III PELAKSANAAN PEMULIHAN DENGAN SEGERA; Bagian Ketiga Penyusunan Rencana Operasi Pemulihan Dengan Segera', 5, '(1) Kaji cepat Pemulihan Dengan Segera sebagaimana dimaksud dalam Pasal 4 ayat (1) dimulai sejak terjadinya kejadian bencana namun status keadaan darurat bencana belum ditetapkan.
(2) Kaji cepat Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (1) dilaksanakan oleh Tim Reaksi Cepat Penanggulangan Bencana yang dikoordinasikan oleh BNPB atau BPBD sesuai kewenangannya dengan melibatkan sektor terkait lainnya.
(3) Hasil kaji cepat pemulihan prasarana dan sarana vital disusun dalam bentuk dokumen laporan tertulis sebagai bahan masukan untuk penetapan status keadaan darurat bencana dan penyusunan rencana operasi penanganan darurat bencana.
(4) Prosedur pelaksanaan kaji cepat Pemulihan Dengan Segera sesuai ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2997, '(1) Kaji cepat Pemulihan Dengan Segera sebagaimana dimaksud dalam Pasal 4 ayat (1) dimulai sejak terjadinya kejadian bencana namun status keadaan darurat bencana belum ditetapkan.
(2) Kaji cepat Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (1) dilaksanakan oleh Tim Reaksi Cepat Penanggulangan Bencana yang dikoordinasikan oleh BNPB atau BPBD sesuai kewenangannya dengan melibatkan sektor terkait lainnya.
(3) Hasil kaji cepat pemulihan prasarana dan sarana vital disusun dalam bentuk dokumen laporan tertulis sebagai bahan masukan untuk penetapan status keadaan darurat bencana dan penyusunan rencana operasi penanganan darurat bencana.
(4) Prosedur pelaksanaan kaji cepat Pemulihan Dengan Segera sesuai ketentuan peraturan perundang-undangan.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2998, 'perban-3-2022', 9, 'pasal', 'Pasal 6', 'BAB III PELAKSANAAN PEMULIHAN DENGAN SEGERA; Bagian Keempat Operasi Pemulihan Dengan Segera', 6, '(1) Kegiatan Pemulihan Dengan Segera dilaksanakan berdasarkan rencana operasi Pemulihan Dengan Segera.
(2) Rencana operasi Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (1) disusun oleh Posko PDB.
(3) Penyusunan rencana operasi Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (2) mengacu pada laporan hasil kaji cepat Pemulihan Dengan Segera yang dapat didukung dengan dokumen rencana kontingensi.
(4) Dalam penyusunan rencana operasi Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (2) harus memuat prioritas pemulihan prasarana dan sarana vital.
(5) Penentuan prioritas sebagaimana dimaksud pada ayat
(4) didasarkan pada kondisi prasarana dan sarana vital yang dapat:
a. mendukung upaya penyelamatan dan evakuasi korban terdampak bencana,
b. mendukung upaya pemenuhan kebutuhan dasar bagi korban, pengungsi, perlindungan kelompok rentan dan masyarakat terdampak bencana, dan Cc. mendukung kemudahan akses bantuan kemanusiaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2998, '(1) Kegiatan Pemulihan Dengan Segera dilaksanakan berdasarkan rencana operasi Pemulihan Dengan Segera.
(2) Rencana operasi Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (1) disusun oleh Posko PDB.
(3) Penyusunan rencana operasi Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (2) mengacu pada laporan hasil kaji cepat Pemulihan Dengan Segera yang dapat didukung dengan dokumen rencana kontingensi.
(4) Dalam penyusunan rencana operasi Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (2) harus memuat prioritas pemulihan prasarana dan sarana vital.
(5) Penentuan prioritas sebagaimana dimaksud pada ayat
(4) didasarkan pada kondisi prasarana dan sarana vital yang dapat:
a. mendukung upaya penyelamatan dan evakuasi korban terdampak bencana,
b. mendukung upaya pemenuhan kebutuhan dasar bagi korban, pengungsi, perlindungan kelompok rentan dan masyarakat terdampak bencana, dan Cc. mendukung kemudahan akses bantuan kemanusiaan.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (2999, 'perban-3-2022', 10, 'pasal', 'Pasal 7', 'BAB III PELAKSANAAN PEMULIHAN DENGAN SEGERA; Bagian Keempat Operasi Pemulihan Dengan Segera', 7, '(1) Operasi Pemulihan Dengan Segera sebagaimana dimaksud dalam Pasal 3 huruf c dilaksanakan pada masa status keadaan darurat bencana ditetapkan berdasarkan rencana operasi Pemulihan Dengan Segera.
(2) Operasi Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (1) dilaksanakan oleh Posko PDB.
(3) Pembentukan dan pelaksanaan tugas Posko PDB sebagaimana dimaksud pada ayat (2) sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (2999, '(1) Operasi Pemulihan Dengan Segera sebagaimana dimaksud dalam Pasal 3 huruf c dilaksanakan pada masa status keadaan darurat bencana ditetapkan berdasarkan rencana operasi Pemulihan Dengan Segera.
(2) Operasi Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (1) dilaksanakan oleh Posko PDB.
(3) Pembentukan dan pelaksanaan tugas Posko PDB sebagaimana dimaksud pada ayat (2) sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3000, 'perban-3-2022', 11, 'pasal', 'Pasal 8', 'BAB III PELAKSANAAN PEMULIHAN DENGAN SEGERA; Bagian Keempat Operasi Pemulihan Dengan Segera', 7, 'Wewenang dan tanggung jawab operasi Pemulihan Dengan Segera diatur berdasarkan tingkatan status darurat bencana yang ditetapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3000, 'Wewenang dan tanggung jawab operasi Pemulihan Dengan Segera diatur berdasarkan tingkatan status darurat bencana yang ditetapkan.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3001, 'perban-3-2022', 12, 'pasal', 'Pasal 9', 'BAB IV BANTUAN PEMULIHAN DENGAN SEGERA', 7, '(1) Laporan operasi Pemulihan Dengan Segera disampaikan secara rutin dan sewaktu-waktu apabila diperlukan kepada Komandan Posko PDB.
(2) Laporan operasi Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (1) merupakan bagian tidak terpisahkan dari laporan pelaksanaan penanganan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3001, '(1) Laporan operasi Pemulihan Dengan Segera disampaikan secara rutin dan sewaktu-waktu apabila diperlukan kepada Komandan Posko PDB.
(2) Laporan operasi Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (1) merupakan bagian tidak terpisahkan dari laporan pelaksanaan penanganan darurat bencana.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3002, 'perban-3-2022', 13, 'pasal', 'Pasal 10', 'BAB V PEMANTAUAN DAN EVALUASI', 7, '(1) Pelaksanaan kegiatan Pemulihan Dengan Segera sebagaimana dimaksud dalam Pasal 2 ayat (1) dapat didukung bantuan Pemulihan Dengan Segera.
(2) Ketentuan lebih lanjut mengenai pemberian bantuan sebagaimana dimaksud pada ayat (1) diatur dengan petunjuk pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3002, '(1) Pelaksanaan kegiatan Pemulihan Dengan Segera sebagaimana dimaksud dalam Pasal 2 ayat (1) dapat didukung bantuan Pemulihan Dengan Segera.
(2) Ketentuan lebih lanjut mengenai pemberian bantuan sebagaimana dimaksud pada ayat (1) diatur dengan petunjuk pelaksanaan.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3003, 'perban-3-2022', 14, 'pasal', 'Pasal 11', 'BAB V PEMANTAUAN DAN EVALUASI', 8, '(1) Pemantauan merupakan kegiatan untuk memastikan pelaksanaan kegiatan operasi Pemulihan Dengan Segera dilaksanakan sesuai rencana operasi Pemulihan Dengan Segera yang telah ditetapkan.
(2) Pemantauan sebagaimana dimaksud pada ayat (1) dilakukan selama proses kegiatan operasi Pemulihan Dengan Segera berlangsung.
(3) Pemantauan sebagaimana dimaksud pada ayat (2) dilakukan oleh Posko PDB, BNPB/BPBD, kementerian/lembaga/instansi terkait sesuai dengan ketentuan peraturan perundang-perundangan.
(4) Hasil pemantauan sebagaimana dimaksud pada ayat (3) disampaikan kepada Komandan Posko PDB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3003, '(1) Pemantauan merupakan kegiatan untuk memastikan pelaksanaan kegiatan operasi Pemulihan Dengan Segera dilaksanakan sesuai rencana operasi Pemulihan Dengan Segera yang telah ditetapkan.
(2) Pemantauan sebagaimana dimaksud pada ayat (1) dilakukan selama proses kegiatan operasi Pemulihan Dengan Segera berlangsung.
(3) Pemantauan sebagaimana dimaksud pada ayat (2) dilakukan oleh Posko PDB, BNPB/BPBD, kementerian/lembaga/instansi terkait sesuai dengan ketentuan peraturan perundang-perundangan.
(4) Hasil pemantauan sebagaimana dimaksud pada ayat (3) disampaikan kepada Komandan Posko PDB.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3004, 'perban-3-2022', 15, 'pasal', 'Pasal 12', 'BAB V PEMANTAUAN DAN EVALUASI', 8, '(1) Evaluasi merupakan kegiatan penilaian capaian hasil pelaksanaan kegiatan Pemulihan Dengan Segera dengan membandingkan pada target dan sasaran yang tertuang pada dokumen rencana operasi pemulihan segera prasarana dan sarana vital yang telah disusun.
(2) Evaluasi sebagaimana dimaksud pada ayat (1) dilakukan secara rutin maupun pada saat tertentu sesuai dengan kebutuhan selama proses kegiatan operasi Pemulihan Dengan Segera berlangsung dan/atau setelah status darurat bencana berakhir.
(3) Pelaksanaan evaluasi sebagaimana dimaksud pada ayat (2) dilakukan oleh Posko PDB, BNPB/BPBD, kementerian/lembaga/instansi terkait sesuai dengan peraturan perundang-perundangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3004, '(1) Evaluasi merupakan kegiatan penilaian capaian hasil pelaksanaan kegiatan Pemulihan Dengan Segera dengan membandingkan pada target dan sasaran yang tertuang pada dokumen rencana operasi pemulihan segera prasarana dan sarana vital yang telah disusun.
(2) Evaluasi sebagaimana dimaksud pada ayat (1) dilakukan secara rutin maupun pada saat tertentu sesuai dengan kebutuhan selama proses kegiatan operasi Pemulihan Dengan Segera berlangsung dan/atau setelah status darurat bencana berakhir.
(3) Pelaksanaan evaluasi sebagaimana dimaksud pada ayat (2) dilakukan oleh Posko PDB, BNPB/BPBD, kementerian/lembaga/instansi terkait sesuai dengan peraturan perundang-perundangan.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3005, 'perban-3-2022', 16, 'pasal', 'Pasal 13', 'BAB VI KETENTUAN PENUTUP', 9, '(1) Evaluasi sebagaimana dimaksud dalam Pasal 12 dituangkan dalam laporan hasil evaluasi pelaksanaan Pemulihan Dengan Segera.
(2) Laporan hasil evaluasi pelaksanaan Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (1) disampaikan selama proses pelaksanaan kepada Komandan Posko PDB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3005, '(1) Evaluasi sebagaimana dimaksud dalam Pasal 12 dituangkan dalam laporan hasil evaluasi pelaksanaan Pemulihan Dengan Segera.
(2) Laporan hasil evaluasi pelaksanaan Pemulihan Dengan Segera sebagaimana dimaksud pada ayat (1) disampaikan selama proses pelaksanaan kepada Komandan Posko PDB.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3006, 'perban-3-2022', 17, 'pasal', 'Pasal 14', 'BAB VI KETENTUAN PENUTUP', 9, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3006, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3007, 'perban-3-2022', 18, 'lain', 'Penutup', NULL, 10, 'Ditetapkan di Jakarta pada tanggal 21 Januari 2022 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Diundangkan di Jakarta pada tanggal 08 Februari 2022 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd.
BENNY RIYANTO BERITA NEGARA REPUBLIK INDONESIA TAHUN 2022 NOMOR 160');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3007, 'Ditetapkan di Jakarta pada tanggal 21 Januari 2022 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Diundangkan di Jakarta pada tanggal 08 Februari 2022 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd.
BENNY RIYANTO BERITA NEGARA REPUBLIK INDONESIA TAHUN 2022 NOMOR 160', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3008, 'perban-3-2022', 19, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi dan Kerja Sama, K ZAHERMANN MundEah');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3008, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi dan Kerja Sama, K ZAHERMANN MundEah', 'Lampiran hal. 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2022 tentang Pemulihan dengan Segera Prasarana dan Sarana Vital pada Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3009, 'perban-3-2024', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2024 tentang Tata Cara Penyelesaian Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3009, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2024 tentang Tata Cara Penyelesaian Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2024 tentang Tata Cara Penyelesaian Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3010, 'perban-3-2024', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk penyesuaian kewenangan penyelesaian keuangan negara serta mekanisme penyelesaian keuangan negara terhadap pegawai negeri bukan bendahara atau pejabat lain terhadap Peraturan Pemerintah Nomor 38 Tahun 2016 tentang Tata Cara Tuntutan Ganti Kerugian Negara/Daerah terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain, perlu mengatur mengenai tata cara penyelesaian kerugian negara terhadap pegawai negeri bukan bendahara atau pejabat lain di lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara di Lingkungan Badan Nasional Penanggulangan Bencana perlu disesuaikan dengan ketentuan yang diatur dalam Peraturan Pemerintah Nomor 38 Tahun 2016 tentang Tata Cara Tuntutan Ganti Kerugian Negara/Daerah terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain, sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Tata Cara Penyelesaian Kerugian Negara terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3010, 'a. bahwa untuk penyesuaian kewenangan penyelesaian keuangan negara serta mekanisme penyelesaian keuangan negara terhadap pegawai negeri bukan bendahara atau pejabat lain terhadap Peraturan Pemerintah Nomor 38 Tahun 2016 tentang Tata Cara Tuntutan Ganti Kerugian Negara/Daerah terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain, perlu mengatur mengenai tata cara penyelesaian kerugian negara terhadap pegawai negeri bukan bendahara atau pejabat lain di lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2019 tentang Tata Cara Penyelesaian Kerugian Negara di Lingkungan Badan Nasional Penanggulangan Bencana perlu disesuaikan dengan ketentuan yang diatur dalam Peraturan Pemerintah Nomor 38 Tahun 2016 tentang Tata Cara Tuntutan Ganti Kerugian Negara/Daerah terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain, sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Tata Cara Penyelesaian Kerugian Negara terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2024 tentang Tata Cara Penyelesaian Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3011, 'perban-3-2024', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 1 Tahun 2004 tentang Pembendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 38 Tahun 2016 tentang Tata Cara Tuntutan Ganti Kerugian Negara/Daerah terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain (Lembaran Negara Republik Indonesia Tahun 2016 Nomor 196, Tambahan Lembaran Negara Republik Indonesia Nomor 5934);
4. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
5. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3011, '1. Undang-Undang Nomor 1 Tahun 2004 tentang Pembendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 38 Tahun 2016 tentang Tata Cara Tuntutan Ganti Kerugian Negara/Daerah terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain (Lembaran Negara Republik Indonesia Tahun 2016 Nomor 196, Tambahan Lembaran Negara Republik Indonesia Nomor 5934);
4. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
5. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2024 tentang Tata Cara Penyelesaian Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3012, 'perban-3-2024', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA CARA PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI NEGERI BUKAN BENDAHARA ATAU PEJABAT LAIN DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3012, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA CARA PENYELESAIAN KERUGIAN NEGARA TERHADAP PEGAWAI NEGERI BUKAN BENDAHARA ATAU PEJABAT LAIN DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2024 tentang Tata Cara Penyelesaian Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3013, 'perban-3-2024', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Kerugian Negara adalah kekurangan uang, surat berharga, dan barang, yang nyata dan pasti jumlahnya sebagai akibat perbuatan melawan hukum baik sengaja maupun lalai.
2. Tuntutan Ganti Kerugian adalah suatu proses tuntutan yang dilakukan terhadap pegawai negeri bukan bendahara atau pejabat lain dengan tujuan untuk memulihkan Kerugian Negara.
3. Surat Keterangan Tanggung Jawab Mutlak yang selanjutnya disingkat SKTJM adalah surat pernyataan dari Pegawai Negeri Bukan Bendahara atau Pejabat Lain, yang menyatakan kesanggupan dan/atau pengakuan bahwa Kerugian Negara menjadi tanggung jawabnya dan bersedia mengganti Kerugian Negara dimaksud.
4. Surat Keputusan Pembebanan Penggantian Kerugian Sementara yang selanjutnya disebut SKP2KS adalah surat yang dibuat oleh Sekretaris Utama Badan Nasional Penanggulangan Bencana dalam hal SKTJM tidak mungkin diperoleh.
5. Surat Keputusan Pembebanan Penggantian Kerugian yang selanjutnya disebut SKP2K adalah surat keputusan yang ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana yang mempunyai kekuatan hukum tetap tentang pembebanan penggantian Kerugian Negara terhadap Pegawai Negeri Bukan Bendahara dan Pejabat Lain.
6. Perhitungan Ex Officio adalah perhitungan yang dilakukan oleh pejabat yang ditetapkan, atas uang, surat berharga, dan/atau badan milik negara yang menjadi tanggung jawab Pegawai Negeri Bukan Bendahara dan Pejabat Lain yang berada dalam pengampuan, melarikan diri, atau meninggal dunia.
7. Surat Keterangan Tanda Lunas yang selanjutnya disingkat SKTL adalah surat keterangan yang menyatakan bahwa piutang telah lunas.
8. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian setingkat menteri sesuai dengan ketentuan peraturan perundang-undangan.
9. Kepala BNPB yang selanjutnya disebut Kepala adalah pejabat yang bertanggung jawab atas pengelolaan keuangan di lingkungan BNPB.
10. Pimpinan Unit Kerja adalah Pejabat Eselon I dan Kepala Pusat di Lingkungan BNPB.
11. Pejabat Penyelesaian Kerugian Negara yang selanjutnya disingkat PPKN adalah pejabat yang berwenang untuk menyelesaikan Kerugian Negara.
12. Pejabat yang Diberi Kewenangan adalah Sekretaris Utama yang diberi kewenangan oleh PPKN untuk menyelesaikan Kerugian Negara.
13. Majelis Pertimbangan Penyelesaian Kerugian Negara yang selanjutnya disebut Majelis adalah para pejabat/pegawai yang ditunjuk dan ditetapkan oleh Kepala BNPB untuk menyampaikan pertimbangan dan pendapat penyelesaian Kerugian Negara.
14. Tim Penyelesaian Kerugian Negara yang selanjutnya disingkat TPKN adalah tim yang bertugas memproses penyelesaian Kerugian Negara.
15. Pegawai Negeri Bukan Bendahara adalah Pegawai Aparatur Sipil Negara, Anggota Tentara Nasional Indonesia, Anggota Kepolisian Negara Republik Indonesia yang bekerja/diserahi tugas selain tugas bendahara.
16. Pejabat Lain adalah pejabat negara dan pejabat penyelenggara pemerintahan yang tidak berstatus pejabat negara, tidak termasuk bendahara dan Pegawai Negeri Bukan Bendahara.
17. Pihak yang Merugikan adalah Pegawai Negeri Bukan Bendahara atau Pejabat Lain yang berdasarkan hasil pemeriksaan menimbulkan Kerugian Negara.
18. Pengampu adalah orang atau badan yang mempunyai tanggung jawab hukum untuk mewakili seseorang karena sifat pribadinya dianggap tidak cakap atau tidak di dalam segala hal cakap untuk bertindak dalam hukum.
19. Yang Memperoleh Hak adalah orang atau badan karena adanya perbuatan atau peristiwa hukum, telah menerima pelepasan hak atas kepemilikan uang, surat berharga, dan/atau barang dari Pihak Yang Merugikan.
20. Ahli Waris adalah anggota keluarga yang masih hidup yang menggantikan kedudukan pewaris dalam bidang hukum kekayaan karena meninggalnya pewaris.');
