INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3084, 'perban-3-2024', 75, 'lampiran', 'Lampiran hal. 34', NULL, 34, '6. Format Daftar Pertanyaan Penyusunan Kronologis Terjadinya Kerugian Negara NAMA UNIT ORGANISASI/ SATUAN KERJA*) DAFTAR PERTANYAAN PENYUSUNAN KRONOLOGIS TERJADINYA KERUGIAN NEGARA No Pertanyaan No Jawaban 1 Bagaimana kejadian Kerugian Negara dapat 1 diketahui? 2 Dengan cara bagaimana Kerugian Negara itu 2 dapat terjadi? 3 Berapa jumlah kekurangan uang/barang 3 milik negara dan/atau uang/barang bukan milik negara dimaksud? 4 Berapa jumlah Kerugian Negara yang 4 diderita oleh negara? 5 Apabila belum dapat ditetapkan dengan 5 pasti, berapa kira-kira jumlah kerugian Negara dimaksud? 6 Siapa saja (nama, jabatan, pangkat dan 6 dalam kedudukannya sebagai apa) yang terindikasi terlibat dalam kejadian Kerugian Negara dan sampai dimana mereka harus dianggap turut dalam melanggar hukum/melalaikan kewajibannya sehingga mengakibatkan terjadinya Kerugian Negara dimaksud? 7 Apakah kejadian Kerugian Negara dimaksud 7 sudah dilaporkan kepada pihak Kepolisian RI atau telah ada keputusan Pengadilan yang berkekuatan hukum tetap? (Jika ada, lampirkan Surat laporan/Berita Acara Pemeriksaan Polisi atau keputusan pengadilan atas yang bersangkutan).');
