INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3087, 'perban-3-2024', 78, 'lampiran', 'Lampiran hal. 36', NULL, 36, 'Setelah Berita Acara Pemeriksaan ini dibacakan kembali di hadapan yang bersangkutan dan yang bersangkutan tidak mengajukan keberatan, maka ditandatangani oleh Tim Penyelesaian Kerugian Negara (TPKN) dan yang diperiksa seperti di bawah ini:
