INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3089, 'perban-3-2024', 80, 'lampiran', 'Lampiran hal. 38', NULL, 38, '2. Jumlah Kerugian Negara yang terjadi akibat kekurangan … (uang/barang milik negara atau uang/barang bukan milik negara*) dimaksud sebesar Rp… (…sebutkan dalam huruf…).
