INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3090, 'perban-3-2024', 81, 'lampiran', 'Lampiran hal. 39', NULL, 39, 'Sehubungan dengan pemeriksaan yang dilakukan Tim Penyelesaian Kerugian Negara (TPKN) kepada Saudara atas terjadinya Kerugian Negara di lingkungan Badan Nasional Penanggulangan Bencana, dengan ini kami sampaikan bahwa berdasarkan hasil pemeriksaan Kerugian Negara dengan nomor … tanggal … perihal … (terlampir), diperoleh kesimpulan bahwa terbukti terjadinya kekurangan … (uang/barang milik negara atau uang/barang bukan milik negara*) berupa .... (sebutkan jenis dan jumlah uang dan/atau barang dimaksud) dengan jumlah Kerugian Negara sebesar Rp… (sebutkan dalam huruf) disebabkan karena …**) dari Saudara … NIP … jabatan … Selanjutnya kepada Saudara, guna tindak lanjut penyelesaian ganti Kerugian Negara sesuai dengan ketentuan pada Peraturan Badan Nomor 3 Tahun 2024 tentang Tata Cara Tuntutan Ganti Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana, Saudara diberi kesempatan untuk menanggapi hasil pemeriksaan Kerugian Negara dimaksud paling lambat 14 (empat belas) hari kerja sejak surat hasil pemeriksaan disampaikan kepada Saudara. Apabila Saudara tidak memberi tanggapan sampai batas waktu dimaksud, Saudara dianggap tidak ada keberatan atas hasil pemeriksaan dimaksud.
Atas perhatian Saudara diucapkan terima kasih.
Ketua TPKN, …………………………..
