INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3092, 'perban-3-2024', 83, 'lampiran', 'Lampiran hal. 41', NULL, 41, '11. Format Laporan tentang Hasil Pemeriksaan Kerugian Negara Atas Kekurangan Uang/Barang Milik Negara atau Uang/Barang Bukan Milik Negara Disebabkan Perbuatan Melanggar Hukum atau Lalai Pegawai Negeri Bukan Bendahara atau Pejabat Lain BADAN NASIONAL PENANGGULANGAN BENCANA LAPORAN HASIL PEMERIKSAAN KERUGIAN NEGARA ATAS KEKURANGAN UANG/BARANG MILIK NEGARA ATAU UANG/BARANG BUKAN MILIK NEGARA *) DISEBABKAN PERBUATAN MELANGGAR HUKUM ATAU LALAI PEGAWAI NEGERI BUKAN BENDAHARA ATAU PEJABAT LAIN A. Pendahuluan
1. Dasar Pemeriksaan
a. Peraturan Badan Nomor 3 Tahun 2024 tentang Tata Cara Tuntutan Ganti Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana; dan
b. Keputusan pembentukan Tim Penyelesaian Kerugian Negara (TPKN) Nomor … tanggal … tentang ….
2. Maksud dan Tujuan Pemeriksaan
a. Untuk mengetahui Pegawai Negeri Bukan Bendahara atau Pejabat Lain yang bertanggung jawab atas terjadinya kekurangan … (uang/barang milik negara atau uang/barang bukan milik negara*) berupa … (sebutkan jenis dan jumlah uang, surat berharga, dan/atau barang dimaksud);
b. Untuk mengetahui penyebab perbuatan Pegawai Negeri Bukan Bendahara atau Pejabat Lain dimaksud yang mengakibatkan terjadinya kekurangan … (uang/barang milik negara atau uang/barang bukan milik negara*);
c. Menghitung jumlah Kerugian Negara atas berkurangnya … (uang/barang milik negara atau uang/barang bukan milik negara*);');
