INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3098, 'perban-3-2024', 89, 'lampiran', 'Lampiran hal. 45', NULL, 45, 'Sehubungan dengan Surat Saudara nomor … tanggal … perihal … yang menyampaikan Laporan Hasil Pemeriksaan TPKN tentang … tanggal …, dengan ini kami sampaikan bahwa berdasarkan penelaahan atas laporan hasil pemeriksaan dimaksud beserta bukti pendukung dan mempertimbangkan ketentuan pada Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2024 tentang Tata Cara Tuntutan Ganti Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana, kami berpendapat menyetujui Laporan Hasil Pemeriksaan TPKN dimaksud yang menyatakan bahwa terbukti terjadinya kekurangan … (uang/barang milik negara atau uang/barang bukan milik negara*) disebabkan (perbuatan melanggar hukum atau lalai/bukan disebabkan perbuatan melanggar hukum atau lalai*) Saudara … NIP. … jabatan ….
Berkenaan dengan hal tersebut di atas, kami menugaskan TPKN untuk melakukan penuntutan penggantian Kerugian Negara sesuai ketentuan pada Peraturan BNPB Nomor 3 Tahun 2024 dimaksud kepada Saudara …, dengan mengupayakan surat pernyataan kesanggupan dan/atau pengakuan bahwa kerugian dimaksud dalam bentuk Surat Keterangan Tanggung Jawab Mutlak (SKTJM) (pernyataan ini ditambahkan bila mana PPKN menyetujui kekurangan uang/barang di maksud disebabkan perbuatan melanggar hukum atau lalai).
Demikian disampaikan, atas perhatian Saudara diucapkan terima kasih.
Sekretaris Utama selaku Kepala Satker, ……………………….
NIP………………….. *) Pilih salah satu');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3098, 'Sehubungan dengan Surat Saudara nomor … tanggal … perihal … yang menyampaikan Laporan Hasil Pemeriksaan TPKN tentang … tanggal …, dengan ini kami sampaikan bahwa berdasarkan penelaahan atas laporan hasil pemeriksaan dimaksud beserta bukti pendukung dan mempertimbangkan ketentuan pada Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2024 tentang Tata Cara Tuntutan Ganti Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana, kami berpendapat menyetujui Laporan Hasil Pemeriksaan TPKN dimaksud yang menyatakan bahwa terbukti terjadinya kekurangan … (uang/barang milik negara atau uang/barang bukan milik negara*) disebabkan (perbuatan melanggar hukum atau lalai/bukan disebabkan perbuatan melanggar hukum atau lalai*) Saudara … NIP. … jabatan ….
Berkenaan dengan hal tersebut di atas, kami menugaskan TPKN untuk melakukan penuntutan penggantian Kerugian Negara sesuai ketentuan pada Peraturan BNPB Nomor 3 Tahun 2024 dimaksud kepada Saudara …, dengan mengupayakan surat pernyataan kesanggupan dan/atau pengakuan bahwa kerugian dimaksud dalam bentuk Surat Keterangan Tanggung Jawab Mutlak (SKTJM) (pernyataan ini ditambahkan bila mana PPKN menyetujui kekurangan uang/barang di maksud disebabkan perbuatan melanggar hukum atau lalai).
Demikian disampaikan, atas perhatian Saudara diucapkan terima kasih.
Sekretaris Utama selaku Kepala Satker, ……………………….
NIP………………….. *) Pilih salah satu', 'Lampiran hal. 45', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2024 tentang Tata Cara Penyelesaian Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3099, 'perban-3-2024', 90, 'lampiran', 'Lampiran hal. 46', NULL, 46, '14. Format Surat Pendapat PPKN Tidak Menyetujui atas Laporan Hasil Pemeriksaan Tim Penyelesaian Kerugian Negara (TPKN) BADAN NASIONAL PENANGGULANGAN BENCANA Nomor : R-……………… (tanggal, bulan, tahun) Sifat : Rahasia Lampiran : … (…) berkas Hal : Pendapat atas Laporan Hasil Pemeriksaan Tim Penyelesaian Kerugian Negara (TPKN) Yth. Ketua Tim Penyelesaian Kerugian Negara (TPKN) di …………………..
Sehubungan dengan Surat Saudara nomor … tanggal … hal … yang menyampaikan Laporan Hasil Pemeriksaan TPKN tentang … tanggal …, dengan ini kami sampaikan bahwa berdasarkan penelaahan atas laporan hasil pemeriksaan dimaksud beserta bukti pendukung dan mempertimbangkan ketentuan pada Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2024 tentang Tata Cara Tuntutan Ganti Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana, kami berpendapat tidak menyetujui Laporan Hasil Pemeriksaan TPKN dimaksud.
Perlu kami sampaikan bahwa pendapat tidak menyetujui atas Laporan Hasil Pemeriksaan dimaksud terkait materi … (sebutkan dan jelaskan materi Laporan Hasil Pemeriksaan TPKN yang tidak disetujui PPKN) Berkenaan dengan hal tersebut di atas, kami menugaskan TPKN segera untuk melakukan pemeriksaan ulang terhadap materi yang tidak disetujui tersebut di atas dalam Laporan Hasil Pemeriksaan dimaksud.
Demikian disampaikan atas perhatian Saudara diucapkan terima kasih.
Sekretaris Utama selaku Kepala satker ……………………….');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3099, '14. Format Surat Pendapat PPKN Tidak Menyetujui atas Laporan Hasil Pemeriksaan Tim Penyelesaian Kerugian Negara (TPKN) BADAN NASIONAL PENANGGULANGAN BENCANA Nomor : R-……………… (tanggal, bulan, tahun) Sifat : Rahasia Lampiran : … (…) berkas Hal : Pendapat atas Laporan Hasil Pemeriksaan Tim Penyelesaian Kerugian Negara (TPKN) Yth. Ketua Tim Penyelesaian Kerugian Negara (TPKN) di …………………..
Sehubungan dengan Surat Saudara nomor … tanggal … hal … yang menyampaikan Laporan Hasil Pemeriksaan TPKN tentang … tanggal …, dengan ini kami sampaikan bahwa berdasarkan penelaahan atas laporan hasil pemeriksaan dimaksud beserta bukti pendukung dan mempertimbangkan ketentuan pada Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2024 tentang Tata Cara Tuntutan Ganti Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana, kami berpendapat tidak menyetujui Laporan Hasil Pemeriksaan TPKN dimaksud.
Perlu kami sampaikan bahwa pendapat tidak menyetujui atas Laporan Hasil Pemeriksaan dimaksud terkait materi … (sebutkan dan jelaskan materi Laporan Hasil Pemeriksaan TPKN yang tidak disetujui PPKN) Berkenaan dengan hal tersebut di atas, kami menugaskan TPKN segera untuk melakukan pemeriksaan ulang terhadap materi yang tidak disetujui tersebut di atas dalam Laporan Hasil Pemeriksaan dimaksud.
Demikian disampaikan atas perhatian Saudara diucapkan terima kasih.
Sekretaris Utama selaku Kepala satker ……………………….', 'Lampiran hal. 46', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2024 tentang Tata Cara Penyelesaian Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3100, 'perban-3-2024', 91, 'lampiran', 'Lampiran hal. 46', NULL, 46, 'NIP………………….. *) Pilih salah satu
15. Format Surat Sekretaris Utama selaku Kepala Satuan Kerja Kepada Kepala BNPB Selaku PPKN Atas Laporan Hasil Pemeriksaan Tim Penyelesaian Kerugian Negara (TPKN) BADAN NASIONAL PENANGGULANGAN BENCANA Nomor : R-……………… (tanggal, bulan, tahun) Sifat : Rahasia Lampiran : … (…) berkas Hal : Laporan Hasil Pemeriksaan Tim Penyelesaian Kerugian Negara (TPKN) Yth. Kepala Badan Nasional Penanggulangan Bencana Jalan Pramuka Raya Kav.38 Jakarta Timur Sehubungan dengan hal tersebut di atas, dengan hormat kami laporkan hal-hal sebagai berikut:
1. Berkenaan dengan telah terjadi kekurangan ……. (uang/barang milik negara atau uang/barang bukan milik negara*) di lingkungan Badan Nasional Penanggulangan Bencana. Kami telah menindaklanjuti hal tersebut dengan membentuk Tim Penyelesaian Kerugian Negara (TPKN) dengan Keputusan Pembentukan TPKN Nomor ……. Tanggal …… tentang …….. (terlampir), dan sudah melakukan pemeriksaan atas Kerugian Negara dimaksud dengan Laporan Hasil Pemeriksaan TPKN tentang … tanggal …, (terlampir), serta telah mendapat persetujuan dari PPKN atau Pejabat yang diberi kewenangan dengan surat nomor … tanggal … hal Pendapat atas Laporan Hasil Pemeriksaan TPKN (terlampir).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3100, 'NIP………………….. *) Pilih salah satu
15. Format Surat Sekretaris Utama selaku Kepala Satuan Kerja Kepada Kepala BNPB Selaku PPKN Atas Laporan Hasil Pemeriksaan Tim Penyelesaian Kerugian Negara (TPKN) BADAN NASIONAL PENANGGULANGAN BENCANA Nomor : R-……………… (tanggal, bulan, tahun) Sifat : Rahasia Lampiran : … (…) berkas Hal : Laporan Hasil Pemeriksaan Tim Penyelesaian Kerugian Negara (TPKN) Yth. Kepala Badan Nasional Penanggulangan Bencana Jalan Pramuka Raya Kav.38 Jakarta Timur Sehubungan dengan hal tersebut di atas, dengan hormat kami laporkan hal-hal sebagai berikut:
1. Berkenaan dengan telah terjadi kekurangan ……. (uang/barang milik negara atau uang/barang bukan milik negara*) di lingkungan Badan Nasional Penanggulangan Bencana. Kami telah menindaklanjuti hal tersebut dengan membentuk Tim Penyelesaian Kerugian Negara (TPKN) dengan Keputusan Pembentukan TPKN Nomor ……. Tanggal …… tentang …….. (terlampir), dan sudah melakukan pemeriksaan atas Kerugian Negara dimaksud dengan Laporan Hasil Pemeriksaan TPKN tentang … tanggal …, (terlampir), serta telah mendapat persetujuan dari PPKN atau Pejabat yang diberi kewenangan dengan surat nomor … tanggal … hal Pendapat atas Laporan Hasil Pemeriksaan TPKN (terlampir).', 'Lampiran hal. 46', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2024 tentang Tata Cara Penyelesaian Kerugian Negara Terhadap Pegawai Negeri Bukan Bendahara atau Pejabat Lain di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3101, 'perban-3-2024', 92, 'lampiran', 'Lampiran hal. 47', NULL, 47, '2. Berdasarkan hasil pemeriksaan TPKN tersebut di atas, bahwa terbukti terjadinya Kerugian Negara akibat kekurangan … (uang/barang milik negara atau uang/barang bukan milik negara*) berupa .... (sebutkan jenis dan jumlah uang dan/atau barang dimaksud) dengan jumlah Kerugian Negara sebesar Rp… (sebutkan dalam huruf) yang disebabkan karena …**) dari Saudara … NIP. … jabatan ….
Demikian kami laporkan, atas perhatian Bapak/Ibu diucapkan terima kasih.
Sekretaris Utama selaku Kepala satker ……………………….
NIP…………………..
Tembusan:
1. Pimpinan Unit Eselon I;
2. Kepala Biro Keuangan;
3. Pimpinan UKE II terjadinya Kerugian Negara. *) Pilih salah satu **) Pilih salah satu: perbuatan melanggar hukum, perbuatan lalai, bukan perbuatan melanggar hukum atau lalai.
16. Format Surat Pernyataan Kesanggupan dan/atau Pengakuan Pihak yang Merugikan/Pengampu/Yang Memperoleh Hak/Ahli Waris SURAT PERNYATAAN KESANGGUPAN DAN/ATAU PENGAKUAN*) Yang bertanda tangan di bawah ini:
Nama : ………………….NIP. ………..… Pangkat/Golongan : ……………………………..……..
Jabatan : …………………………………….');
