INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3103, 'perban-3-2024', 94, 'lampiran', 'Lampiran hal. 49', NULL, 49, '1. Jumlah Kerugian Negara dimaksud telah saya ganti dengan menyetorkan jumlah dimaksud ke rekening Kas Negara di … pada tanggal … (salinan bukti tanda setor dilampirkan bersama ini).*) atau
2. Jumlah Kerugian Negara dimaksud akan saya ganti dengan menyetorkan jumlah ke rekening Kas Negara di … dalam jangka waktu …**), dengan angsuran tiap bulan sebesar Rp.... (sebutkan dalam huruf) dengan menyerahkan jaminan berupa ….*) Apabila dalam jangka waktu di atas setelah saya menandatangani pernyataan ini ternyata saya tidak mengganti seluruh jumlah kerugian tersebut, maka Negara dapat menjual atau melelang barang jaminan tersebut. Saya menyadari bahwa setelah keterangan ini dibuat tidak boleh mengajukan pembelaan diri dalam bentuk apapun. ………, ………………… Mengetahui:
