INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3103, '1. Jumlah Kerugian Negara dimaksud telah saya ganti dengan menyetorkan jumlah dimaksud ke rekening Kas Negara di … pada tanggal … (salinan bukti tanda setor dilampirkan bersama ini).*) atau
