INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3105, '2. ………………………. *) Pilih salah satu **) Pilih salah satu pernyataan 1 dan 2 ***) Kerugian Negara akibat perbuatan melanggar hukum paling lama 90 hari kalender sejak SKTJM ditandatangani atau akibat kelalaian paling lama 24 bulan sejak SKTJM ditandatangani atau jangka waktu sesuai dengan persetujuan Kepala Badan atas jangka waktu kondisi tertentu.
