INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3116, 'Ditetapkan di Jakarta pada tanggal ……. a.n. KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, KEPALA SATKER/ATASAN KEPALA SATKER*), ……………………………………… NIP. ………………………………..
