INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3117, 'perban-3-2024', 108, 'lampiran', 'Lampiran hal. 60', NULL, 60, '26. Format Surat Keberatan Atas Keputusan Pembebanan Penggantian Kerugian Sementara (SKP2KS) Nomor : ……………… Lampiran : … (…) berkas Hal : Keberatan Atas Keputusan Pembebanan Penggantian Kerugian Sementara (SKP2KS) Yth. Kepala BNPB u.p.
