INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3137, 'perban-3-2024', 128, 'lampiran', 'Lampiran hal. 75', NULL, 75, 'Saudara …*) oleh Saudara sesuai dengan Surat Perintah Penyitaan (SPP) nomor … tanggal … dengan Berita Acara Penyitaan nomor … tanggal …, dengan ini kami mengajukan permohonan pencabutan sita atas harta kekayaan a.n. Saudara …*) untuk dilakukan pengembalian harta kekayaan yang disita kepada Saudara …*).
