INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3139, 'perban-3-2024', 130, 'lampiran', 'Lampiran hal. 77', NULL, 77, 'Sehubungan dengan hal tersebut di atas, dengan hormat saya mengajukan permohonan pengembalian kelebihan pembayaran/setoran atas ganti Kerugian Negara yang saya bayarkan berdasarkan SKTJM/SKP2KS/SKP2K*) …………… (sebutkan nomor/tanggal/perihal surat dimaksud) dan atas dasar pengurangan tagihan sesuai surat Kepala Badan Nasional Penanggulangan Bencana nomor … tanggal … perihal … Kelebihan pembayaran/setoran atas ganti Kerugian Negara dimaksud sebesar Rp…. (…sebutkan dengan huruf…).
