INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3140, 'perban-3-2025', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3140, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3141, 'perban-3-2025', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk melindungi seluruh masyarakat di wilayah yang memiliki potensi ancaman bencana, diperlukan metode komunikasi, edukasi, dan informasi kebencanaan berupa rambu dan papan informasi bencana;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana sudah tidak sesuai dengan perkembangan hukum, sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Rambu dan Papan Informasi Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3141, 'a. bahwa untuk melindungi seluruh masyarakat di wilayah yang memiliki potensi ancaman bencana, diperlukan metode komunikasi, edukasi, dan informasi kebencanaan berupa rambu dan papan informasi bencana;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana sudah tidak sesuai dengan perkembangan hukum, sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Rambu dan Papan Informasi Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3142, 'perban-3-2025', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
3. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata KerjaBadan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3142, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
3. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata KerjaBadan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3143, 'perban-3-2025', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG RAMBU DAN PAPAN INFORMASI BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3143, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG RAMBU DAN PAPAN INFORMASI BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3144, 'perban-3-2025', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Rambu Bencana yang selanjutnya disebut Rambu adalah keterangan yang ditempatkan atau dipasang di kawasan rawan Bencana, berupa lambang, huruf, angka, dan/atau frasa, yang berfungsi untuk menjelaskan atau memberi petunjuk, peringatan, dan larangan bagi setiap orang yang berada di kawasan rawan Bencana.
3. Papan Informasi Bencana yang selanjutnya disebut Papan Informasi adalah media yang digunakan untuk memberikan informasi mengenai ancaman bencana atau kawasan rawan Bencana, serta hal-hal yang perlu dilakukan untuk mengantisipasi ancaman bencana.
4. Rawan Bencana adalah kondisi atau karakteristik geologis, biologis, hidrologis, klimatologis, geografis, sosial, budaya, politik, ekonomi, dan teknologi pada suatu wilayah untuk jangka waktu tertentu yang mengurangi kemampuan mencegah, meredam, mencapai kesiapan, dan mengurangi kemampuan untuk menanggapi dampak buruk bahaya tertentu.
5. Status keadaan darurat bencana adalah suatu keadaan yang ditetapkan oleh Pemerintah untuk jangka waktu tertentu atas dasar rekomendasi Badan yang diberi tugas untuk menanggulangi bencana.
6. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
7. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara pemerintahan daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
8. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam Undang-Undang tentang penanggulangan Bencana.
9. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan Pemerintah Daerah yang melakukan penyelenggaraan penanggulangan Bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3144, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Rambu Bencana yang selanjutnya disebut Rambu adalah keterangan yang ditempatkan atau dipasang di kawasan rawan Bencana, berupa lambang, huruf, angka, dan/atau frasa, yang berfungsi untuk menjelaskan atau memberi petunjuk, peringatan, dan larangan bagi setiap orang yang berada di kawasan rawan Bencana.
3. Papan Informasi Bencana yang selanjutnya disebut Papan Informasi adalah media yang digunakan untuk memberikan informasi mengenai ancaman bencana atau kawasan rawan Bencana, serta hal-hal yang perlu dilakukan untuk mengantisipasi ancaman bencana.
4. Rawan Bencana adalah kondisi atau karakteristik geologis, biologis, hidrologis, klimatologis, geografis, sosial, budaya, politik, ekonomi, dan teknologi pada suatu wilayah untuk jangka waktu tertentu yang mengurangi kemampuan mencegah, meredam, mencapai kesiapan, dan mengurangi kemampuan untuk menanggapi dampak buruk bahaya tertentu.
5. Status keadaan darurat bencana adalah suatu keadaan yang ditetapkan oleh Pemerintah untuk jangka waktu tertentu atas dasar rekomendasi Badan yang diberi tugas untuk menanggulangi bencana.
6. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
7. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara pemerintahan daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
8. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam Undang-Undang tentang penanggulangan Bencana.
9. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan Pemerintah Daerah yang melakukan penyelenggaraan penanggulangan Bencana di daerah.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3145, 'perban-3-2025', 5, 'pasal', 'Pasal 2', 'BAB II PENYELENGGARA', 3, 'Rambu dan Papan Informasi digunakan untuk jenis ancaman Bencana, paling sedikit meliputi:
a. gempa bumi;
b. tsunami;
c. erupsi gunung api;
d. longsor;
e. banjir;
f. banjir bandang;
g. kebakaran hutan dan lahan; dan
h. gagal teknologi.');
