INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3146, 'perban-3-2025', 6, 'pasal', 'Pasal 3', 'BAB II PENYELENGGARA', 3, 'Rambu dan Papan Informasi diselenggarakan oleh Pemerintah Daerah kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3146, 'Rambu dan Papan Informasi diselenggarakan oleh Pemerintah Daerah kabupaten/kota.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3147, 'perban-3-2025', 7, 'pasal', 'Pasal 4', 'BAB III PENYELENGGARAAN; Bagian Kesatu Umum', 3, '(1) Pemerintah Daerah Kabupaten/Kota sebagaimana dimaksud dalam Pasal 3 didukung oleh:
