INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3148, 'perban-3-2025', 8, 'pasal', 'Pasal 5', 'BAB III PENYELENGGARAAN; Bagian Kedua Perencanaan', 4, 'Penyelenggaraan Rambu dan Papan Informasi, meliputi:
