INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3148, 'Penyelenggaraan Rambu dan Papan Informasi, meliputi:
a. perencanaan;
b. pengadaan;
c. penempatan dan pemasangan; dan
