INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3149, 'perban-3-2025', 9, 'pasal', 'Pasal 6', 'BAB III PENYELENGGARAAN; Bagian Kedua Perencanaan', 4, '(1) Perencanaan sebagaimana dimaksud dalam Pasal 5 huruf a meliputi:
a. jenis Rambu dan Papan Informasi;
b. jumlah Rambu dan Papan Informasi; dan
c. lokasi penempatan dan pemasangan Rambu dan Papan Informasi.
(2) Perencanaan sebagaimana dimaksud pada ayat (1) dilakukan melalui tahapan:
a. inventarisasi kebutuhan;
b. survei lapangan; dan
c. penentuan dan penetapan kebutuhan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3149, '(1) Perencanaan sebagaimana dimaksud dalam Pasal 5 huruf a meliputi:
a. jenis Rambu dan Papan Informasi;
b. jumlah Rambu dan Papan Informasi; dan
c. lokasi penempatan dan pemasangan Rambu dan Papan Informasi.
(2) Perencanaan sebagaimana dimaksud pada ayat (1) dilakukan melalui tahapan:
a. inventarisasi kebutuhan;
b. survei lapangan; dan
c. penentuan dan penetapan kebutuhan.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3150, 'perban-3-2025', 10, 'pasal', 'Pasal 7', 'BAB III PENYELENGGARAAN; Bagian Kedua Perencanaan', 4, '(1) Inventarisasi kebutuhan sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf a berdasarkan dokumen perencanaan terkait penanggulangan Bencana.
(2) Dokumen perencanaan sebagaimana dimaksud pada ayat (1) meliputi:
a. dokumen kajian risiko Bencana provinsi, kabupaten/kota, desa/kelurahan, dan/atau kawasan tertentu/khusus;
b. dokumen rencana penanggulangan Bencana provinsi, kabupaten/kota, desa/kelurahan, dan/atau kawasan tertentu/khusus;
c. dokumen rencana kontingensi provinsi, kabupaten/kota, desa/kelurahan, dan/atau kawasan tertentu/khusus; dan/atau
d. dokumen rencana evakuasi Bencana provinsi, kabupaten/kota, desa/kelurahan, dan/atau kawasan tertentu/khusus.
(3) Dalam hal tidak terdapat dokumen sebagaimana dimaksud pada ayat (1), inventarisasi kebutuhan Rambu dan Papan Informasi dikoordinasikan kepada BPBD kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3150, '(1) Inventarisasi kebutuhan sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf a berdasarkan dokumen perencanaan terkait penanggulangan Bencana.
(2) Dokumen perencanaan sebagaimana dimaksud pada ayat (1) meliputi:
a. dokumen kajian risiko Bencana provinsi, kabupaten/kota, desa/kelurahan, dan/atau kawasan tertentu/khusus;
b. dokumen rencana penanggulangan Bencana provinsi, kabupaten/kota, desa/kelurahan, dan/atau kawasan tertentu/khusus;
c. dokumen rencana kontingensi provinsi, kabupaten/kota, desa/kelurahan, dan/atau kawasan tertentu/khusus; dan/atau
d. dokumen rencana evakuasi Bencana provinsi, kabupaten/kota, desa/kelurahan, dan/atau kawasan tertentu/khusus.
(3) Dalam hal tidak terdapat dokumen sebagaimana dimaksud pada ayat (1), inventarisasi kebutuhan Rambu dan Papan Informasi dikoordinasikan kepada BPBD kabupaten/kota.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3151, 'perban-3-2025', 11, 'pasal', 'Pasal 8', 'BAB III PENYELENGGARAAN; Bagian Kedua Perencanaan', 5, '(1) Survei lapangan sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf b dilaksanakan untuk memastikan kebutuhan dan lokasi penempatan dan pemasangan.
(2) Hasil survei lapangan sebagaimana dimaksud pada ayat (1) disusun dalam bentuk laporan.
(3) Laporan sebagaimana dimaksud pada ayat (2) paling sedikit memuat:
a. jenis Rambu dan Papan Informasi;
b. jumlah Rambu dan Papan Informasi;
c. lokasi dan titik koordinat penempatan dan pemasangan Rambu dan Papan Informasi; dan
d. rekomendasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3151, '(1) Survei lapangan sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf b dilaksanakan untuk memastikan kebutuhan dan lokasi penempatan dan pemasangan.
(2) Hasil survei lapangan sebagaimana dimaksud pada ayat (1) disusun dalam bentuk laporan.
(3) Laporan sebagaimana dimaksud pada ayat (2) paling sedikit memuat:
