INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3152, 'perban-3-2025', 12, 'pasal', 'Pasal 9', 'BAB III PENYELENGGARAAN; Bagian Ketiga Pengadaan', 5, '(1) Penentuan dan penetapan kebutuhan sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf c dilaksanakan melalui rapat koordinasi bersama BPBD Kabupaten/Kota.
(2) Penentuan dan penetapan kebutuhan sebagaimana dimaksud pada ayat (1) berdasarkan laporan sebagaimana dimaksud dalam Pasal 8 ayat (3).
(3) Penentuan dan penetapan kebutuhan sebagaimana dimaksud pada ayat (1) dituangkan dalam berita acara.
(4) Format berita acara sebagaimana dimaksud pada ayat
(2) tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3152, '(1) Penentuan dan penetapan kebutuhan sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf c dilaksanakan melalui rapat koordinasi bersama BPBD Kabupaten/Kota.
(2) Penentuan dan penetapan kebutuhan sebagaimana dimaksud pada ayat (1) berdasarkan laporan sebagaimana dimaksud dalam Pasal 8 ayat (3).
(3) Penentuan dan penetapan kebutuhan sebagaimana dimaksud pada ayat (1) dituangkan dalam berita acara.
(4) Format berita acara sebagaimana dimaksud pada ayat
(2) tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3153, 'perban-3-2025', 13, 'pasal', 'Pasal 10', 'BAB III PENYELENGGARAAN; Bagian Keempat Penempatan dan Pemasangan', 5, 'Pengadaan sebagaimana dimaksud dalam Pasal 3 huruf b dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3153, 'Pengadaan sebagaimana dimaksud dalam Pasal 3 huruf b dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3154, 'perban-3-2025', 14, 'pasal', 'Pasal 11', 'BAB III PENYELENGGARAAN; Bagian Kelima Evaluasi', 5, '(1) Penempatan dan pemasangan Rambu dan Papan Informasi sebagaimana dimaksud dalam Pasal 5 huruf c dilaksanakan melalui tahapan:
a. pendataan kebutuhan;
b. diskusi strategi; dan
c. penetapan kebutuhan.
(2) Penempatan dan pemasangan Rambu dan Papan Informasi sebagaimana dimaksud pada ayat (1) berdasarkan lokasi dan titik koordinat yang tercantum dalam berita acara sebagaimana dimaksud dalam Pasal 9 ayat (2).
(3) Penempatan dan pemasangan Rambu dan Papan Informasi sebagaimana dimaksud pada ayat (1) dilakukan pada lokasi berupa jalan yang dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3154, '(1) Penempatan dan pemasangan Rambu dan Papan Informasi sebagaimana dimaksud dalam Pasal 5 huruf c dilaksanakan melalui tahapan:
a. pendataan kebutuhan;
b. diskusi strategi; dan
c. penetapan kebutuhan.
(2) Penempatan dan pemasangan Rambu dan Papan Informasi sebagaimana dimaksud pada ayat (1) berdasarkan lokasi dan titik koordinat yang tercantum dalam berita acara sebagaimana dimaksud dalam Pasal 9 ayat (2).
(3) Penempatan dan pemasangan Rambu dan Papan Informasi sebagaimana dimaksud pada ayat (1) dilakukan pada lokasi berupa jalan yang dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3155, 'perban-3-2025', 15, 'pasal', 'Pasal 12', 'BAB IV PEMELIHARAAN DAN PENGGANTIAN', 6, '(1) Evaluasi sebagaimana dimaksud dalam Pasal 5 huruf d dilaksanakan terhadap:
a. perencanaan;
b. pengadaan;
c. penempatan dan pemasangan; dan
d. pemeliharaan dan penggantian;
(2) Evaluasi sebagaimana dimaksud pada ayat (1) huruf a, huruf c, dan huruf d dilaksanakan dengan mempertimbangkan perubahan informasi risiko Bencana.
(3) Evaluasi dilaksanakan paling sedikit 1 (satu) kali dalam setahun.
(4) Hasil evaluasi sebagaimana dimaksud pada ayat (1) disusun dalam bentuk laporan, paling sedikit memuat:
a. analisis;
b. kesimpulan; dan
c. rekomendasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3155, '(1) Evaluasi sebagaimana dimaksud dalam Pasal 5 huruf d dilaksanakan terhadap:
a. perencanaan;
