INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3165, 'perban-3-2025', 25, 'pasal', 'Pasal 22', 'BAB VI STANDAR TEKNIS; Bagian Kesatu Rambu', 8, '(1) Bagian Rambu terdiri atas:
a. daun Rambu; dan
b. tiang Rambu.
(2) Bagian Rambu sebagaimana dimaksud pada ayat (1) dapat dilengkapi dengan Papan Tambahan.
(3) Bagian Rambu harus memenuhi spesifikasi teknis Rambu dan Papan Informasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3165, '(1) Bagian Rambu terdiri atas:
a. daun Rambu; dan
b. tiang Rambu.
(2) Bagian Rambu sebagaimana dimaksud pada ayat (1) dapat dilengkapi dengan Papan Tambahan.
(3) Bagian Rambu harus memenuhi spesifikasi teknis Rambu dan Papan Informasi.', 'Pasal 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3166, 'perban-3-2025', 26, 'pasal', 'Pasal 23', 'BAB VI STANDAR TEKNIS; Bagian Kesatu Rambu', 8, '(1) Daun Rambu sebagaimana dimaksud dalam Pasal 22 ayat (1) huruf a berisikan informasi berupa:
