INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3181, 'perban-3-2025', 41, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'Ukuran dan Contoh Rambu Peringatan Standar Ukuran A B R (mm) Minimum 450 3% x A 3% x A Maksimum 900 Contoh Rambu Peringatan Standar. peringatan kawasan peringatan kawasan peringatan kawasan rawan tsunami rawan banjir rawan banjir bandang peringatan kawasan peringatan kawasan rawan peringatan kawasan rawan gunung api kebakaran hutan dan lahan rawan puting beliung peringatan kawasan Peringatan kawasan sesar Peringatan kawasan gas rawan longsor aktif; beracun Peringatan kawasan Peringatan kawasan bahaya radioaktif biologi Ukuran dan Contoh Rambu peringatan dengan kata-kata Contoh Rambu Peringatan dengan Kata-kata.
