INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3183, 'perban-3-2025', 43, 'lampiran', 'Lampiran hal. 19', NULL, 19, '4. Papan Tambahan Papan Tambahan berisikan informasi mengenai:
a. jarak;
b. ketinggian;
c. arah;
d. nama tempat/lokasi; dan/atau
e. jenis ancaman bencana.
Papan tambahan sebagaimana dimaksud memiliki:
a. warna dasar putih;
b. warna garis tepi hitam; dan
c. warna huruf dan/atau angka hitam.
Papan tambahan ditempatkan dengan jarak lima (5) cm sampai dengan sepuluh (10) cm dari sisi terbawah daun rambu dengan lebar papan tambahan secara vertikal tidak melebihi sisi daun rambu;
Ukuran dan Contoh Papan Tambahan, sebagai berikut:
A B C D R Minimum 200 450 Maksimum 450 900 5% x A 5% x A 5% x A Contoh penggunaan papan tambahan;
B. STANDAR TEKNIS PAPAN INFORMASI BENCANA Penyelenggara harus menyusun naskah informasi dalam bahasa Indonesia yang baik dan benar dengan menggunakan huruf latin. Naskah informasi dapat memakai bahasa asing yang ditulis di bagian bawah tulisan berbahasa Indonesia dengan menggunakan huruf latin yang lebih kecil. Contoh Papan Informasi Bencana sebagaimana berikut.');
