INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3184, 'perban-3-2025', 44, 'lampiran', 'Lampiran hal. 20', NULL, 20, 'Rencana Evakuasi Legenda Bencana Banjir Area terbuka Tempat perlindungan Jalur Evakuasi RSUD Rute yang dapat diakses Zona bahaya banjir Banjir Jalan bawah tanah Peringatan : zona bahaya Tanah longsor Parkiran Stasiun kereta Rumah Sakit Kantor Pos Taman Hotel SMP 2 Jakarta Contoh Papan Informasi Evakuasi Bencana Banjir Proyeksi kedalaman Air Banjir Jika tanggul hancur, area ini beresiko menimbulkan banjir dengan kedalaman lebih dari Tempat perlindungan 10 meter. Evakuasi area ini dengan cepat dan berlindung di luar ruangan.
SMP 2 Jakarta Warna kedalaman:
Contoh papan informasi zona bahaya / proyeksi landaan banjir Rencana Evakuasi Legenda Bencana Banjir Legend Flood evacuation plan Area perlindungan di luar ruangan Outdoor refuge area Tempat perlindungan Protection shelter Rumah Sakit Pusat Central Hospital Jalur Evakuasi Evacuation route Rute yang dapat diakses Accessible route Zona bahaya banjir Flood hazard zone Jalan bawah tanah Peringatan : zona bahaya Banjir Taman di atas bukit Park on the hill Underpass Flood Warning: hazard zone Tanah longsor Steep slope failure, landslide Stasiun kereta Railway station Rumah Sakit Hospital Kantor Pos Post office Taman Park Sekolah Menengah Pertama Junior High School Hotel Hotel Contoh rambu rencana evakuasi banjir dalam dua bahasa (bilingual) Contoh Papan Informasi bencana banjir bandang disertai tanda-tanda dan informasi kontak darurat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3184, 'Rencana Evakuasi Legenda Bencana Banjir Area terbuka Tempat perlindungan Jalur Evakuasi RSUD Rute yang dapat diakses Zona bahaya banjir Banjir Jalan bawah tanah Peringatan : zona bahaya Tanah longsor Parkiran Stasiun kereta Rumah Sakit Kantor Pos Taman Hotel SMP 2 Jakarta Contoh Papan Informasi Evakuasi Bencana Banjir Proyeksi kedalaman Air Banjir Jika tanggul hancur, area ini beresiko menimbulkan banjir dengan kedalaman lebih dari Tempat perlindungan 10 meter. Evakuasi area ini dengan cepat dan berlindung di luar ruangan.
SMP 2 Jakarta Warna kedalaman:
Contoh papan informasi zona bahaya / proyeksi landaan banjir Rencana Evakuasi Legenda Bencana Banjir Legend Flood evacuation plan Area perlindungan di luar ruangan Outdoor refuge area Tempat perlindungan Protection shelter Rumah Sakit Pusat Central Hospital Jalur Evakuasi Evacuation route Rute yang dapat diakses Accessible route Zona bahaya banjir Flood hazard zone Jalan bawah tanah Peringatan : zona bahaya Banjir Taman di atas bukit Park on the hill Underpass Flood Warning: hazard zone Tanah longsor Steep slope failure, landslide Stasiun kereta Railway station Rumah Sakit Hospital Kantor Pos Post office Taman Park Sekolah Menengah Pertama Junior High School Hotel Hotel Contoh rambu rencana evakuasi banjir dalam dua bahasa (bilingual) Contoh Papan Informasi bencana banjir bandang disertai tanda-tanda dan informasi kontak darurat.', 'Lampiran hal. 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2025 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3185, 'perban-3-2025', 45, 'lampiran', 'Lampiran hal. 23', NULL, 23, 'C. STANDAR TEKNIS RAMBU DAN PAPAN INFORMASI SEMENTARA Rambu dan Papan Informasi sementara berisikan:
a. informasi kejadian bencana yang sedang terjadi; dan/atau
b. peringatan ancaman dan/atau dampak Bencana susulan.
Rambu dan Papan Informasi sementara sebagaimana dimaksud memiliki:
a. warna dasar jingga;
b. warna garis tepi hitam; dan
c. warna huruf dan/atau angka hitam.
Ukuran Daun Rambu Sementara Standar, sebagai berikut:
Ukuran A B R (mm) Minimum 450 3% x A 3% x A Maksimum 900 Ukuran Daun Rambu Sementara Dengan Kata-Kata, sebagai berikut:
Contoh rambu dan papan informasi sementara, sebagai berikut:
Rambu Peringatan Sementara Rambu Sementara dengan Kata-Kata D. STANDAR TEKNIS DAUN DAN TIANG RAMBU
1. Bahan untuk Daun Rambu dan Papan Informasi adalah sebagai berikut:
1) Plat aluminium dengan ketebalan minimal 2,00 mm (termasuk reflective sheet).
2) Aluminium composite panel (ACP) dengan ketebalan minimal 3,0 mm (termasuk reflective sheet).
3) Bahan non-logam memiliki ketebalan minimal 2,0 mm (termasuk reflective sheet). Tahan terhadap cuaca; (memiliki garansi 5 tahun).
Dianjurkan menggunakan polycarbonate (min 5,0mm)/akrilik (min 0,8mm).
2. Persyaratan Reflective Sheet
a. Menggunakan teknologi prismatik minimal ASTM D4956 tipe I (garansi 5 tahun);
b. khusus penempatan pada jalan nasional menggunakan minimal ASTM D4956 tipe IV (garansi 7 tahun), dan tidak menggunakan bahan non logam; dan
c. tulisan/piktogram menggunakan sablon/cutting sticker Reflective Sheet.');
