INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3197, 'perban-3-2026', 6, 'pasal', 'Pasal 3', 'BAB I KETENTUAN UMUM', 4, 'RPBD sebagaimana dimaksud dalam Pasal 2 terdiri atas:
