INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3198, 'perban-3-2026', 7, 'pasal', 'Pasal 4', 'BAB I KETENTUAN UMUM', 4, '(1) RPBD provinsi sebagaimana dimaksud dalam Pasal 3 huruf a ditetapkan oleh Gubernur.
