INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3198, '(1) RPBD provinsi sebagaimana dimaksud dalam Pasal 3 huruf a ditetapkan oleh Gubernur.
(2) RPBD provinsi sebagaimana dimaksud pada ayat (1) mengacu pada:
