INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3199, 'perban-3-2026', 8, 'pasal', 'Pasal 5', 'BAB I KETENTUAN UMUM', 4, '(1) RPBD kabupaten/kota sebagaimana dimaksud dalam Pasal 4 huruf b ditetapkan oleh Bupati/Walikota.
