INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3200, 'perban-3-2026', 9, 'pasal', 'Pasal 6', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Kesatu Umum', 4, '(1) RPBD Provinsi disusun berdasarkan pada KRB tingkat provinsi yang telah ditetapkan.
(2) RPBD kabupaten/kota disusun berdasarkan pada KRB tingkat kabupaten/kota yang telah ditetapkan.
(3) Dalam hal KRB tingkat kabupaten/kota sebagaimana dimaksud pada ayat (2) belum ditetapkan, RPBD kabupaten/kota disusun berdasarkan KRB tingkat Provinsi.
(4) KRB sebagaimana dimaksud pada ayat (1) dan ayat (2) merupakan KRB yang masih berlaku untuk jangka waktu paling singkat 3 (tiga) tahun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3200, '(1) RPBD Provinsi disusun berdasarkan pada KRB tingkat provinsi yang telah ditetapkan.
(2) RPBD kabupaten/kota disusun berdasarkan pada KRB tingkat kabupaten/kota yang telah ditetapkan.
(3) Dalam hal KRB tingkat kabupaten/kota sebagaimana dimaksud pada ayat (2) belum ditetapkan, RPBD kabupaten/kota disusun berdasarkan KRB tingkat Provinsi.
(4) KRB sebagaimana dimaksud pada ayat (1) dan ayat (2) merupakan KRB yang masih berlaku untuk jangka waktu paling singkat 3 (tiga) tahun.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3201, 'perban-3-2026', 10, 'pasal', 'Pasal 7', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Kedua Persiapan', 4, 'Penyusunan RPBD sebagaimana dimaksud pada ayat (1) dilakukan melalui tahapan:
a. persiapan;
b. penyusunan rancangan awal;
c. pembahasan antarperangkat daerah.
d. konsultasi awal;
e. penyusunan rancangan akhir;
f. konsultasi akhir; dan
g. penetapan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3201, 'Penyusunan RPBD sebagaimana dimaksud pada ayat (1) dilakukan melalui tahapan:
a. persiapan;
b. penyusunan rancangan awal;
c. pembahasan antarperangkat daerah.
d. konsultasi awal;
e. penyusunan rancangan akhir;
f. konsultasi akhir; dan
g. penetapan.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3202, 'perban-3-2026', 11, 'pasal', 'Pasal 8', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Kedua Persiapan', 5, 'Persiapan sebagaimana dimaksud dalam Pasal 7 ayat (2) huruf a, meliputi:
a. pembentukan tim teknis;
b. penyusunan rencana kerja;
c. sosialisasi penyusunan RPBD; dan
d. pengumpulan data dan informasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3202, 'Persiapan sebagaimana dimaksud dalam Pasal 7 ayat (2) huruf a, meliputi:
a. pembentukan tim teknis;
b. penyusunan rencana kerja;
c. sosialisasi penyusunan RPBD; dan
d. pengumpulan data dan informasi.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3203, 'perban-3-2026', 12, 'pasal', 'Pasal 9', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Kedua Persiapan', 5, '(1) Pembentukan tim teknis sebagaimana dimaksud dalam Pasal 8 huruf a ditetapkan oleh Sekretaris Daerah.
(2) Tim teknis sebagaimana dimaksud pada ayat (1) beranggotakan:
a. BPBD;
b. Perangkat Daerah yang membidangi urusan perencanaan pembangunan daerah;
c. Perangkat Daerah yang membidangi urusan pengelolaan keuangan daerah;
d. Perangkat Daerah yang membidangi urusan hukum;
e. Perangkat Daerah yang membidangi urusan lingkungan hidup;
f. Perangkat Daerah yang membidangi urusan pekerjaan umum;
g. Perangkat Daerah yang membidangi urusan penataan ruang; dan
h. Perangkat Daerah terkait.
(3) Selain beranggotakan sebagaimana dimaksud pada ayat (2), tim teknis dapat berasal dari unsur instansi vertikal, nonpemerintah dan kelompok rentan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3203, '(1) Pembentukan tim teknis sebagaimana dimaksud dalam Pasal 8 huruf a ditetapkan oleh Sekretaris Daerah.
(2) Tim teknis sebagaimana dimaksud pada ayat (1) beranggotakan:
a. BPBD;
b. Perangkat Daerah yang membidangi urusan perencanaan pembangunan daerah;
c. Perangkat Daerah yang membidangi urusan pengelolaan keuangan daerah;
d. Perangkat Daerah yang membidangi urusan hukum;
e. Perangkat Daerah yang membidangi urusan lingkungan hidup;
f. Perangkat Daerah yang membidangi urusan pekerjaan umum;
g. Perangkat Daerah yang membidangi urusan penataan ruang; dan
h. Perangkat Daerah terkait.
(3) Selain beranggotakan sebagaimana dimaksud pada ayat (2), tim teknis dapat berasal dari unsur instansi vertikal, nonpemerintah dan kelompok rentan.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3204, 'perban-3-2026', 13, 'pasal', 'Pasal 10', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Kedua Persiapan', 5, '(1) Penyusunan rencana kerja sebagaimana dimaksud dalam Pasal 8 huruf b dilaksanakan oleh tim teknis.
(2) Rencana kerja sebagaimana dimaksud pada ayat (1) memuat:
