INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3204, '(1) Penyusunan rencana kerja sebagaimana dimaksud dalam Pasal 8 huruf b dilaksanakan oleh tim teknis.
(2) Rencana kerja sebagaimana dimaksud pada ayat (1) memuat:
