INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3205, 'perban-3-2026', 14, 'pasal', 'Pasal 11', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Kedua Persiapan', 5, 'Sosialisasi penyusunan RPBD sebagaimana dimaksud dalam Pasal 8 huruf c merupakan penyampaian informasi kepada publik mengenai:
a. urgensi penyusunan;
b. ruang lingkup substansi RPBD;
c. tahapan penyusunan;
d. rencana kerja penyusunan RPBD; dan
e. penjelasan lainnya terkait penyusunan RPBD sesuai kebutuhan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3205, 'Sosialisasi penyusunan RPBD sebagaimana dimaksud dalam Pasal 8 huruf c merupakan penyampaian informasi kepada publik mengenai:
a. urgensi penyusunan;
b. ruang lingkup substansi RPBD;
c. tahapan penyusunan;
d. rencana kerja penyusunan RPBD; dan
e. penjelasan lainnya terkait penyusunan RPBD sesuai kebutuhan.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3206, 'perban-3-2026', 15, 'pasal', 'Pasal 12', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 6, '(1) Pengumpulan data dan informasi sebagaimana dimaksud dalam Pasal 8 huruf d dilakukan terhadap data dan informasi yang mencakup:
a. data kejadian bencana;
b. ⁠dokumen KRB;
c. ⁠indeks risiko bencana;
d. ⁠indeks ketahanan daerah;
e. kondisi umum daerah;
f. data kapasitas kelembagaan penanggulangan bencana di daerah:
g. ⁠data kapasitas pendanaan penanggulangan bencana di daerah;
h. ⁠hasil evaluasi pelaksanaan RPBD periode sebelumnya;
i. capaian penerapan SPM sub-urusan bencana;
j. dokumen perencanaan sektoral di daerah; dan
k. data dan informasi terkait lainnya.
(2) Pengumpulan data dan informasi sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3206, '(1) Pengumpulan data dan informasi sebagaimana dimaksud dalam Pasal 8 huruf d dilakukan terhadap data dan informasi yang mencakup:
