INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3207, 'perban-3-2026', 16, 'pasal', 'Pasal 13', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 6, '(1) Penyusunan rancangan awal sebagaimana dimaksud dalam Pasal 7 huruf b dilaksanakan melalui pembahasan oleh tim teknis.
(2) Rancangan awal sebagaimana dimaksud pada ayat (1) disusun dengan sistematika yang teridiri atas:
a. pendahuluan;
b. kebijakan penanggulangan bencana;
c. karakteristik daerah dan isu strategis kebencanaan;
d. tujuan, sasaran, dan strategi penanggulangan bencana;
e. program dan kegiatan penanggulangan bencana;
f. pelaksanaan, pemantauan, dan evaluasi; dan
g. penutup.
(3) Sistematika RPBD sebagaimana dimaksud pada ayat (2) tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3207, '(1) Penyusunan rancangan awal sebagaimana dimaksud dalam Pasal 7 huruf b dilaksanakan melalui pembahasan oleh tim teknis.
