INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3208, 'perban-3-2026', 17, 'pasal', 'Pasal 14', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 6, 'Penyusunan rancangan awal dilaksanakan melalui:
a. penelaahan atas kebijakan penanggulangan bencana;
b. analisis karakteristik kebencanaan daerah;
c. penetapan potensi ancaman bencana prioritas;
