INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3209, 'perban-3-2026', 18, 'pasal', 'Pasal 15', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 7, '(1) Penelaahan atas kebijakan penanggulangan bencana sebagaimana dimaksud dalam Pasal 14 huruf a dilakukan terhadap:
a. RIPB Tahun 2020-2044; dan
b. RENAS PB.
(2) Dalam hal penelaahan atas kebijakan penanggulangan bencana dilakukan oleh Pemerintah Daerah kabupaten/kota, penelaahan juga dilakukan terhadap RPBD provinsi.
(3) Hasil penelaahan atas kebijakan penanggulangan bencana dituangkan dalam kertas kerja penelaahan atas kebijakan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3209, '(1) Penelaahan atas kebijakan penanggulangan bencana sebagaimana dimaksud dalam Pasal 14 huruf a dilakukan terhadap:
a. RIPB Tahun 2020-2044; dan
b. RENAS PB.
(2) Dalam hal penelaahan atas kebijakan penanggulangan bencana dilakukan oleh Pemerintah Daerah kabupaten/kota, penelaahan juga dilakukan terhadap RPBD provinsi.
(3) Hasil penelaahan atas kebijakan penanggulangan bencana dituangkan dalam kertas kerja penelaahan atas kebijakan penanggulangan bencana.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3210, 'perban-3-2026', 19, 'pasal', 'Pasal 16', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 7, 'Analisis karakteristik kebencanaan daerah sebagaimana dimaksud dalam Pasal 14 huruf b paling sedikit mencakup:
a. analisis kondisi umum daerah;
b. analisis kelembagaan dalam penanggulangan bencana;
c. analisis pendanaan dalam penanggulangan bencana;
d. analisis data kejadian bencana; dan
e. analisis data tingkat risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3210, 'Analisis karakteristik kebencanaan daerah sebagaimana dimaksud dalam Pasal 14 huruf b paling sedikit mencakup:
a. analisis kondisi umum daerah;
b. analisis kelembagaan dalam penanggulangan bencana;
c. analisis pendanaan dalam penanggulangan bencana;
d. analisis data kejadian bencana; dan
e. analisis data tingkat risiko bencana.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3211, 'perban-3-2026', 20, 'pasal', 'Pasal 17', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 7, 'Analisis kondisi umum daerah sebagaimana dimaksud dalam Pasal 16 huruf a dilakukan melalui pengkajian terhadap aspek:
a. geografis;
b. geologis;
c. topografis;
d. hidrologis;
e. klimatologis;
f. demografis;
g. ekonomi; dan
h. tata ruang, pada kondisi saat ini terhadap permasalahan yang berhubungan dengan risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3211, 'Analisis kondisi umum daerah sebagaimana dimaksud dalam Pasal 16 huruf a dilakukan melalui pengkajian terhadap aspek:
a. geografis;
b. geologis;
c. topografis;
d. hidrologis;
e. klimatologis;
f. demografis;
g. ekonomi; dan
h. tata ruang, pada kondisi saat ini terhadap permasalahan yang berhubungan dengan risiko bencana.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3212, 'perban-3-2026', 21, 'pasal', 'Pasal 18', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 8, 'Analisis kelembagaan dalam penanggulangan bencana sebagaimana dimaksud dalam Pasal 16 huruf b dilakukan melalui identifikasi tugas, fungsi, dan bentuk keterlibatan lembaga pemerintah dan nonpemerintah dalam penyelenggaraan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3212, 'Analisis kelembagaan dalam penanggulangan bencana sebagaimana dimaksud dalam Pasal 16 huruf b dilakukan melalui identifikasi tugas, fungsi, dan bentuk keterlibatan lembaga pemerintah dan nonpemerintah dalam penyelenggaraan penanggulangan bencana.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3213, 'perban-3-2026', 22, 'pasal', 'Pasal 19', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 8, '(1) Analisis pendanaan dalam penanggulangan bencana sebagaimana dimaksud dalam Pasal 16 huruf c dilakukan melalui pengkajian kapasitas fiskal daerah dan pemanfaatan dana untuk penanggulangan bencana dalam kurun waktu 5 (lima) tahun terakhir.
(2) Hasil analisis pendanaan dalam penanggulangan bencana sebagaimana dimaksud pada ayat (1) dituangkan dalam kertas kerja analisis pendanaan dalam penanggulangan bencana daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3213, '(1) Analisis pendanaan dalam penanggulangan bencana sebagaimana dimaksud dalam Pasal 16 huruf c dilakukan melalui pengkajian kapasitas fiskal daerah dan pemanfaatan dana untuk penanggulangan bencana dalam kurun waktu 5 (lima) tahun terakhir.
(2) Hasil analisis pendanaan dalam penanggulangan bencana sebagaimana dimaksud pada ayat (1) dituangkan dalam kertas kerja analisis pendanaan dalam penanggulangan bencana daerah.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3214, 'perban-3-2026', 23, 'pasal', 'Pasal 20', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 8, '(1) Analisis data kejadian bencana sebagaimana dimaksud dalam Pasal 16 huruf d dilakukan terhadap jenis, jumlah, dan besaran dampak bencana dalam kurun waktu 10 (sepuluh) tahun terakhir.
(2) Batasan kurun waktu sebagaimana dimaksud pada ayat (1) dikecualikan bagi jenis bencana geologi.
(3) Analisis data kejadian bencana geologi sebagaimana dimaksud pada ayat (2) didasarkan pada seluruh rekaman data kejadian yang tersedia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3214, '(1) Analisis data kejadian bencana sebagaimana dimaksud dalam Pasal 16 huruf d dilakukan terhadap jenis, jumlah, dan besaran dampak bencana dalam kurun waktu 10 (sepuluh) tahun terakhir.
(2) Batasan kurun waktu sebagaimana dimaksud pada ayat (1) dikecualikan bagi jenis bencana geologi.
(3) Analisis data kejadian bencana geologi sebagaimana dimaksud pada ayat (2) didasarkan pada seluruh rekaman data kejadian yang tersedia.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3215, 'perban-3-2026', 24, 'pasal', 'Pasal 21', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 8, '(1) Analisis data tingkat risiko bencana sebagaimana dimaksud dalam Pasal 16 huruf e memuat informasi terkait luas wilayah berisiko, potensi jumlah penduduk terpapar, potensi kerugian dan kerusakan lingkungan, dan tingkat risiko.
(2) Analisis data tingkat risiko bencana sebagaimana dimaksud pada ayat (1) memanfaatkan data dan informasi dalam dokumen KRB.
(3) Dalam hal dokumen KRB provinsi belum ditetapkan, data dan informasi untuk analisis data tingkat risiko bencana sebagaimana dimaksud pada ayat (2) diperoleh dengan memanfaatkan data dan informasi risiko bencana tingkat nasional.
(4) Dalam hal dokumen KRB kabupaten/kota belum ditetapkan, data dan informasi untuk analisis data tingkat risiko bencana sebagaimana dimaksud pada ayat (2) diperoleh dengan memanfaatkan data dan informasi risiko bencana tingkat provinsi atau nasional.
(5) Hasil analisis data tingkat risiko bencana dituangkan dalam kertas kerja analisis data tingkat risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3215, '(1) Analisis data tingkat risiko bencana sebagaimana dimaksud dalam Pasal 16 huruf e memuat informasi terkait luas wilayah berisiko, potensi jumlah penduduk terpapar, potensi kerugian dan kerusakan lingkungan, dan tingkat risiko.
(2) Analisis data tingkat risiko bencana sebagaimana dimaksud pada ayat (1) memanfaatkan data dan informasi dalam dokumen KRB.
(3) Dalam hal dokumen KRB provinsi belum ditetapkan, data dan informasi untuk analisis data tingkat risiko bencana sebagaimana dimaksud pada ayat (2) diperoleh dengan memanfaatkan data dan informasi risiko bencana tingkat nasional.
(4) Dalam hal dokumen KRB kabupaten/kota belum ditetapkan, data dan informasi untuk analisis data tingkat risiko bencana sebagaimana dimaksud pada ayat (2) diperoleh dengan memanfaatkan data dan informasi risiko bencana tingkat provinsi atau nasional.
(5) Hasil analisis data tingkat risiko bencana dituangkan dalam kertas kerja analisis data tingkat risiko bencana.', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3216, 'perban-3-2026', 25, 'pasal', 'Pasal 22', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 9, 'Penetapan potensi ancaman bencana prioritas sebagaimana dimaksud dalam Pasal 14 huruf c dilakukan dengan menilai:
a. tingkat kecenderungan kejadian; dan
b. tingkat risiko bencana.
Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3216, 'Penetapan potensi ancaman bencana prioritas sebagaimana dimaksud dalam Pasal 14 huruf c dilakukan dengan menilai:
a. tingkat kecenderungan kejadian; dan
b. tingkat risiko bencana.
Bencana', 'Pasal 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3217, 'perban-3-2026', 26, 'pasal', 'Pasal 23', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 9, '(1) Penelaahan hasil evaluasi kinerja penanggulangan bencana sebagaimana dimaksud dalam Pasal 14 huruf d dilakukan terhadap:
a. RPBD periode sebelumnya;
b. pencapaian SPM sub-urusan bencana;
c. pencapaian nilai penurunan indeks risiko bencana;
d. pencapaian nilai peningkatan indeks ketahanan daerah; dan
e. parameter penilaian lain terkait kebencanaan.
(2) Penelaahan terhadap RPBD periode sebelumnya sebagaimana dimaksud pada ayat (1) huruf a dikecualikan bagi Pemerintah Daerah yang belum pernah menetapkan RPBD.
(3) Hasil penelaahan terhadap hasil evaluasi kinerja penanggulangan bencana dituangkan dalam kertas kerja evaluasi kinerja penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3217, '(1) Penelaahan hasil evaluasi kinerja penanggulangan bencana sebagaimana dimaksud dalam Pasal 14 huruf d dilakukan terhadap:
a. RPBD periode sebelumnya;
b. pencapaian SPM sub-urusan bencana;
c. pencapaian nilai penurunan indeks risiko bencana;
d. pencapaian nilai peningkatan indeks ketahanan daerah; dan
e. parameter penilaian lain terkait kebencanaan.
(2) Penelaahan terhadap RPBD periode sebelumnya sebagaimana dimaksud pada ayat (1) huruf a dikecualikan bagi Pemerintah Daerah yang belum pernah menetapkan RPBD.
(3) Hasil penelaahan terhadap hasil evaluasi kinerja penanggulangan bencana dituangkan dalam kertas kerja evaluasi kinerja penanggulangan bencana.', 'Pasal 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3218, 'perban-3-2026', 27, 'pasal', 'Pasal 24', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 9, '(1) Perumusan permasalahan dan isu strategis kebencanaan sebagaimana dimaksud dalam Pasal 14 huruf e dilakukan sebagai bahan pertimbangan dalam merumuskan tujuan, sasaran, strategi, program, dan kegiatan penanggulangan bencana untuk 5 (lima) tahun mendatang.
(2) Perumusan permasalahan dan isu strategis kebencanaan sebagaimana dimaksud pada ayat (1) dilakukan melalui tahapan:
a. identifikasi permasalahan kebencanaan; dan
b. identifikasi isu kebencanaan.
(3) Perumusan permasalahan dan isu strategis kebencanaan sebagaimana dimaksud pada ayat (2) dilakukan bersama para pemangku kepentingan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3218, '(1) Perumusan permasalahan dan isu strategis kebencanaan sebagaimana dimaksud dalam Pasal 14 huruf e dilakukan sebagai bahan pertimbangan dalam merumuskan tujuan, sasaran, strategi, program, dan kegiatan penanggulangan bencana untuk 5 (lima) tahun mendatang.
(2) Perumusan permasalahan dan isu strategis kebencanaan sebagaimana dimaksud pada ayat (1) dilakukan melalui tahapan:
a. identifikasi permasalahan kebencanaan; dan
b. identifikasi isu kebencanaan.
(3) Perumusan permasalahan dan isu strategis kebencanaan sebagaimana dimaksud pada ayat (2) dilakukan bersama para pemangku kepentingan.', 'Pasal 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3219, 'perban-3-2026', 28, 'pasal', 'Pasal 25', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 9, '(1) Identifikasi permasalahan kebencanaan sebagaimana dimaksud dalam Pasal 24 ayat (2) huruf a, meliputi:
a. faktor keterpaparan dan kerentanan yang mempengaruhi risiko bencana yang prioritas untuk ditangani;
b. kesenjangan antara kapasitas penanggulangan bencana yang ada dengan kapasitas yang diharapkan atau ingin dicapai; dan
c. kesenjangan antara capaian dan target kinerja yang ditetapkan dalam dokumen perencanaan penanggulangan bencana, dokumen perencanaan pembangunan, dan/atau dokumen perencanaan lainnya.
(2) Hasil identifikasi permasalahan kebencanaan sebagaimana dimaksud pada ayat (1) dirumuskan menjadi permasalahan utama yang akan ditangani dalam 5 (lima) tahun mendatang.
(3) Hasil identifikasi permasalahan kebencanaan dan perumusan permasalahan utama dituangkan dalam dokumentasi hasil perumusan permasalahan kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3219, '(1) Identifikasi permasalahan kebencanaan sebagaimana dimaksud dalam Pasal 24 ayat (2) huruf a, meliputi:
a. faktor keterpaparan dan kerentanan yang mempengaruhi risiko bencana yang prioritas untuk ditangani;
b. kesenjangan antara kapasitas penanggulangan bencana yang ada dengan kapasitas yang diharapkan atau ingin dicapai; dan
c. kesenjangan antara capaian dan target kinerja yang ditetapkan dalam dokumen perencanaan penanggulangan bencana, dokumen perencanaan pembangunan, dan/atau dokumen perencanaan lainnya.
(2) Hasil identifikasi permasalahan kebencanaan sebagaimana dimaksud pada ayat (1) dirumuskan menjadi permasalahan utama yang akan ditangani dalam 5 (lima) tahun mendatang.
(3) Hasil identifikasi permasalahan kebencanaan dan perumusan permasalahan utama dituangkan dalam dokumentasi hasil perumusan permasalahan kebencanaan.', 'Pasal 25', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3220, 'perban-3-2026', 29, 'pasal', 'Pasal 26', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 10, '(1) Identifikasi isu kebencanaan sebagaimana dimaksud dalam Pasal 24 ayat (2) huruf b dilakukan dengan mempertimbangkan:
a. hasil pembahasan dari pemangku kepentingan;
b. hasil perumusan permasalahan utama;
c. hasil analisis karakteristik daerah;
d. hasil penetapan potensi ancaman prioritas;
e. hasil penelaahan atas kebijakan penanggulangan bencana;
f. hasil identifikasi isu kebencanaan di tingkat internasional, nasional, regional, dan daerah; dan/atau
g. kebijakan dan program pembangunan yang mempengaruhi tingkat risiko bencana.
(2) Hasil identifikasi isu kebencanaan sebagaimana dimaksud pada ayat (1) dirumuskan menjadi rumusan isu strategis kebencanaan.
(3) Perumusan isu strategis kebencanaan mempertimbangkan:
a. pengaruh signifikan terhadap penurunan risiko bencana prioritas yang akan ditangani;
b. isu lintas sektor;
c. kewenangan Pemerintah Daerah;
d. pengaruh terhadap kinerja penanggulangan bencana;
e. pengaruh terhadap kinerja pembangunan daerah; dan
f. pertimbangan lainnya sesuai kebutuhan.
(4) Hasil identifikasi isu kebencanaan dan perumusan isu strategis kebencanaan sebagaimana dimaksud pada ayat (1) dan ayat (2) dituangkan dalam dokumentasi hasil perumusan isu strategis kebencanaan.
Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3220, '(1) Identifikasi isu kebencanaan sebagaimana dimaksud dalam Pasal 24 ayat (2) huruf b dilakukan dengan mempertimbangkan:
a. hasil pembahasan dari pemangku kepentingan;
b. hasil perumusan permasalahan utama;
c. hasil analisis karakteristik daerah;
d. hasil penetapan potensi ancaman prioritas;
e. hasil penelaahan atas kebijakan penanggulangan bencana;
f. hasil identifikasi isu kebencanaan di tingkat internasional, nasional, regional, dan daerah; dan/atau
g. kebijakan dan program pembangunan yang mempengaruhi tingkat risiko bencana.
(2) Hasil identifikasi isu kebencanaan sebagaimana dimaksud pada ayat (1) dirumuskan menjadi rumusan isu strategis kebencanaan.
(3) Perumusan isu strategis kebencanaan mempertimbangkan:
a. pengaruh signifikan terhadap penurunan risiko bencana prioritas yang akan ditangani;
b. isu lintas sektor;
c. kewenangan Pemerintah Daerah;
d. pengaruh terhadap kinerja penanggulangan bencana;
e. pengaruh terhadap kinerja pembangunan daerah; dan
f. pertimbangan lainnya sesuai kebutuhan.
(4) Hasil identifikasi isu kebencanaan dan perumusan isu strategis kebencanaan sebagaimana dimaksud pada ayat (1) dan ayat (2) dituangkan dalam dokumentasi hasil perumusan isu strategis kebencanaan.
Bencana', 'Pasal 26', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3221, 'perban-3-2026', 30, 'pasal', 'Pasal 27', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 11, '(1) Perumusan tujuan, sasaran, dan strategi penanggulangan bencana sebagaimana dimaksud dalam Pasal 14 huruf f dilakukan dengan tahapan:
a. menetapkan kondisi ideal yang akan dicapai atau dihasilkan dari upaya penanggulangan bencana dalam waktu 5 (lima) tahun mendatang;
b. mendeskripsikan dampak dari pelaksanaan program, dan kegiatan penanggulangan bencana; dan
c. menyusun langkah-langkah untuk mencapai sasaran.
(2) Perumusan tujuan, sasaran, dan strategi penanggulangan bencana sebagaimana dimaksud pada ayat (1) dilakukan secara iteratif dengan proses perumusan program dan kegiatan penanggulangan bencana.
(3) Perumusan tujuan, sasaran, dan strategi penanggulangan bencana sebagaimana dimaksud pada ayat (2) dengan mempertimbangkan hasil rumusan permasalahan utama dan isu strategis sebagaimana dimaksud dalam Pasal 25 dan Pasal 26.
(4) Hasil perumusan tujuan, sasaran, dan strategi penanggulangan bencana dituangkan dalam kertas kerja rumusan tujuan, sasaran, dan strategi penanggulangan bencana.
Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3221, '(1) Perumusan tujuan, sasaran, dan strategi penanggulangan bencana sebagaimana dimaksud dalam Pasal 14 huruf f dilakukan dengan tahapan:
a. menetapkan kondisi ideal yang akan dicapai atau dihasilkan dari upaya penanggulangan bencana dalam waktu 5 (lima) tahun mendatang;
b. mendeskripsikan dampak dari pelaksanaan program, dan kegiatan penanggulangan bencana; dan
c. menyusun langkah-langkah untuk mencapai sasaran.
(2) Perumusan tujuan, sasaran, dan strategi penanggulangan bencana sebagaimana dimaksud pada ayat (1) dilakukan secara iteratif dengan proses perumusan program dan kegiatan penanggulangan bencana.
(3) Perumusan tujuan, sasaran, dan strategi penanggulangan bencana sebagaimana dimaksud pada ayat (2) dengan mempertimbangkan hasil rumusan permasalahan utama dan isu strategis sebagaimana dimaksud dalam Pasal 25 dan Pasal 26.
(4) Hasil perumusan tujuan, sasaran, dan strategi penanggulangan bencana dituangkan dalam kertas kerja rumusan tujuan, sasaran, dan strategi penanggulangan bencana.
Bencana', 'Pasal 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3222, 'perban-3-2026', 31, 'pasal', 'Pasal 28', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 11, '(1) Perumusan program dan kegiatan penanggulangan bencana sebagaimana dimaksud dalam Pasal 14 huruf g dilakukan dengan tahapan:
a. merumuskan rancangan program dan kegiatan;
b. menentukan kategori kegiatan sesuai jenis ancaman bencana prioritas; dan
c. merancang rincian rumusan kegiatan.
(2) Perumusan program dan kegiatan penanggulangan bencana sebagaimana dimaksud pada ayat (1) dilakukan secara iteratif dengan proses perumusan tujuan, sasaran, dan strategi penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3222, '(1) Perumusan program dan kegiatan penanggulangan bencana sebagaimana dimaksud dalam Pasal 14 huruf g dilakukan dengan tahapan:
a. merumuskan rancangan program dan kegiatan;
b. menentukan kategori kegiatan sesuai jenis ancaman bencana prioritas; dan
c. merancang rincian rumusan kegiatan.
(2) Perumusan program dan kegiatan penanggulangan bencana sebagaimana dimaksud pada ayat (1) dilakukan secara iteratif dengan proses perumusan tujuan, sasaran, dan strategi penanggulangan bencana.', 'Pasal 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3223, 'perban-3-2026', 32, 'pasal', 'Pasal 29', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 11, 'Perumusan rancangan program dan kegiatan sebagaimana dimaksud dalam Pasal 28 ayat (1) huruf a dilakukan untuk melaksanakan strategi penanggulangan bencana dengan memperhatikan:
a. hasil perumusan permasalahan utama dan isu strategis sebagaimana dimaksud dalam Pasal 25 dan Pasal 26;
b. pembagian urusan pemerintahan;
c. setiap rumusan program penanggulangan bencana memiliki hasil yang diharapkan;
d. setiap rumusan program dilaksanakan dalam bentuk kegiatan; dan
e. setiap rumusan kegiatan penanggulangan bencana memiliki indikator keluaran kegiatan yang diharapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3223, 'Perumusan rancangan program dan kegiatan sebagaimana dimaksud dalam Pasal 28 ayat (1) huruf a dilakukan untuk melaksanakan strategi penanggulangan bencana dengan memperhatikan:
a. hasil perumusan permasalahan utama dan isu strategis sebagaimana dimaksud dalam Pasal 25 dan Pasal 26;
b. pembagian urusan pemerintahan;
c. setiap rumusan program penanggulangan bencana memiliki hasil yang diharapkan;
d. setiap rumusan program dilaksanakan dalam bentuk kegiatan; dan
e. setiap rumusan kegiatan penanggulangan bencana memiliki indikator keluaran kegiatan yang diharapkan.', 'Pasal 29', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3224, 'perban-3-2026', 33, 'pasal', 'Pasal 30', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 12, '(1) Penentuan kategori kegiatan sesuai jenis ancaman bencana prioritas sebagaimana dimaksud dalam Pasal 28 ayat (1) huruf b dilakukan dengan menentukan kegiatan generik atau kegiatan spesifik.
(2) Kegiatan generik merupakan tindakan pengurangan risiko bencana yang dilakukan secara umum untuk seluruh jenis potensi ancaman bencana prioritas.
(3) Kategori kegiatan generik sebagaimana dimaksud pada ayat (2) memuat informasi:
a. lokasi pelaksanaan; dan
b. target penerima manfaat, pada setiap kegiatan.
(4) Kegiatan spesifik merupakan tindakan pengurangan risiko bencana terhadap 1 (satu) jenis potensi ancaman bencana prioritas.
(5) Kategori kegiatan spesifik sebagaimana dimaksud pada ayat (4) memuat informasi:
a. sifat kegiatan spesifik, berupa fisik atau nonfisik;
b. lokasi pelaksanaan; dan
c. target penerima manfaat.
(6) Lokasi pelaksanaan kegiatan spesifik yang bersifat fisik sebagaimana dimaksud pada ayat (5) huruf b digambarkan dalam peta yang ditumpangsusunkan (overlay) dengan peta risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3224, '(1) Penentuan kategori kegiatan sesuai jenis ancaman bencana prioritas sebagaimana dimaksud dalam Pasal 28 ayat (1) huruf b dilakukan dengan menentukan kegiatan generik atau kegiatan spesifik.
(2) Kegiatan generik merupakan tindakan pengurangan risiko bencana yang dilakukan secara umum untuk seluruh jenis potensi ancaman bencana prioritas.
(3) Kategori kegiatan generik sebagaimana dimaksud pada ayat (2) memuat informasi:
a. lokasi pelaksanaan; dan
b. target penerima manfaat, pada setiap kegiatan.
(4) Kegiatan spesifik merupakan tindakan pengurangan risiko bencana terhadap 1 (satu) jenis potensi ancaman bencana prioritas.
(5) Kategori kegiatan spesifik sebagaimana dimaksud pada ayat (4) memuat informasi:
a. sifat kegiatan spesifik, berupa fisik atau nonfisik;
b. lokasi pelaksanaan; dan
c. target penerima manfaat.
(6) Lokasi pelaksanaan kegiatan spesifik yang bersifat fisik sebagaimana dimaksud pada ayat (5) huruf b digambarkan dalam peta yang ditumpangsusunkan (overlay) dengan peta risiko bencana.', 'Pasal 30', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3225, 'perban-3-2026', 34, 'pasal', 'Pasal 31', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 12, '(1) Penentuan rincian rumusan kegiatan sebagaimana dimaksud dalam Pasal 28 ayat (1) huruf c dilakukan berdasarkan hasil rumusan rancangan program dan kegiatan dan kategori kegiatan sesuai jenis ancaman bencana prioritas.
(2) Rincian rumusan kegiatan sebagaimana dimaksud pada ayat (1) meliputi:
a. jenis potensi ancaman prioritas yang ditangani;
b. kategori kegiatan;
c. indikator hasil kegiatan;
d. target per tahun;
e. pagu indikatif per tahun;
f. hasil pemetaan sandingan dengan nomenklatur subkegiatan sesuai klasifikasi, kodefikasi, dan nomenklatur perencanaan pembangunan daerah;
g. lokasi pelaksanaan;
h. penerima manfaat;
i. sumber pendanaan;
j. Perangkat Daerah pelaksana;
k. instansi yang perlu dilibatkan; dan
l. hasil pemetaan kontribusi terhadap RIPB Tahun 2020-2044 dan RENAS PB.
(3) Selain rincian rumusan kegiatan sebagaimana dimaksud pada ayat (2), penyusunan RPBD kabupaten/kota memuat informasi mengenai hasil pemetaan kontribusi kegiatan terhadap RPBD provinsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3225, '(1) Penentuan rincian rumusan kegiatan sebagaimana dimaksud dalam Pasal 28 ayat (1) huruf c dilakukan berdasarkan hasil rumusan rancangan program dan kegiatan dan kategori kegiatan sesuai jenis ancaman bencana prioritas.
(2) Rincian rumusan kegiatan sebagaimana dimaksud pada ayat (1) meliputi:
a. jenis potensi ancaman prioritas yang ditangani;
b. kategori kegiatan;
c. indikator hasil kegiatan;
d. target per tahun;
e. pagu indikatif per tahun;
f. hasil pemetaan sandingan dengan nomenklatur subkegiatan sesuai klasifikasi, kodefikasi, dan nomenklatur perencanaan pembangunan daerah;
g. lokasi pelaksanaan;
h. penerima manfaat;
i. sumber pendanaan;
j. Perangkat Daerah pelaksana;
k. instansi yang perlu dilibatkan; dan
l. hasil pemetaan kontribusi terhadap RIPB Tahun 2020-2044 dan RENAS PB.
(3) Selain rincian rumusan kegiatan sebagaimana dimaksud pada ayat (2), penyusunan RPBD kabupaten/kota memuat informasi mengenai hasil pemetaan kontribusi kegiatan terhadap RPBD provinsi.', 'Pasal 31', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3226, 'perban-3-2026', 35, 'pasal', 'Pasal 32', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 13, 'Hasil perumusan program dan kegiatan penanggulangan bencana dituangkan dalam kertas kerja rumusan dan rincian program dan kegiatan penanggulangan bencana.
Evaluasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3226, 'Hasil perumusan program dan kegiatan penanggulangan bencana dituangkan dalam kertas kerja rumusan dan rincian program dan kegiatan penanggulangan bencana.
Evaluasi', 'Pasal 32', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3227, 'perban-3-2026', 36, 'pasal', 'Pasal 33', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 13, 'Perumusan kerangka pelaksanaan, pemantauan, dan evaluasi sebagaimana dimaksud dalam Pasal 14 huruf h meliputi:
a. perumusan mekanisme pelaksanaan; dan
b. perumusan mekanisme pemantauan dan evaluasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3227, 'Perumusan kerangka pelaksanaan, pemantauan, dan evaluasi sebagaimana dimaksud dalam Pasal 14 huruf h meliputi:
a. perumusan mekanisme pelaksanaan; dan
b. perumusan mekanisme pemantauan dan evaluasi.', 'Pasal 33', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3228, 'perban-3-2026', 37, 'pasal', 'Pasal 34', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 13, '(1) Perumusan mekanisme pelaksanaan sebagaimana dimaksud dalam Pasal 33 huruf a dilakukan dengan mempertimbangkan:
a. hasil analisis kelembagaan dalam penanggulangan bencana sebagaimana dimaksud dalam Pasal 18;
b. hasil perumusan tujuan, sasaran, dan strategi penanggulangan bencana sebagaimana dimaksud dalam Pasal 27; dan
c. hasil perumusan program dan kegiatan sebagaimana dimaksud dalam Pasal 32.
(2) Perumusan mekanisme pelaksanaan sebagaimana dimaksud pada ayat (1) dilakukan dengan tahapan:
a. perumusan kerangka kelembagaan dalam bentuk skema pembagian peran dan tanggung jawab Pemerintah Daerah; dan
b. perumusan skema pelibatan pihak nonpemerintah.
(3) Pembagian peran dan tanggung jawab Pemerintah Daerah sebagaimana dimaksud pada ayat (2) huruf a dilaksanakan sesuai kegiatan dan pencapaian sasaran penanggulangan bencana.
(4) Perumusan skema pelibatan pihak nonpemerintah sebagaimana dimaksud pada ayat (2) huruf b dilaksanakan melalui kemitraan yang dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3228, '(1) Perumusan mekanisme pelaksanaan sebagaimana dimaksud dalam Pasal 33 huruf a dilakukan dengan mempertimbangkan:
a. hasil analisis kelembagaan dalam penanggulangan bencana sebagaimana dimaksud dalam Pasal 18;
b. hasil perumusan tujuan, sasaran, dan strategi penanggulangan bencana sebagaimana dimaksud dalam Pasal 27; dan
c. hasil perumusan program dan kegiatan sebagaimana dimaksud dalam Pasal 32.
(2) Perumusan mekanisme pelaksanaan sebagaimana dimaksud pada ayat (1) dilakukan dengan tahapan:
a. perumusan kerangka kelembagaan dalam bentuk skema pembagian peran dan tanggung jawab Pemerintah Daerah; dan
b. perumusan skema pelibatan pihak nonpemerintah.
(3) Pembagian peran dan tanggung jawab Pemerintah Daerah sebagaimana dimaksud pada ayat (2) huruf a dilaksanakan sesuai kegiatan dan pencapaian sasaran penanggulangan bencana.
(4) Perumusan skema pelibatan pihak nonpemerintah sebagaimana dimaksud pada ayat (2) huruf b dilaksanakan melalui kemitraan yang dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 34', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3229, 'perban-3-2026', 38, 'pasal', 'Pasal 35', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketiga Penyusunan Rancangan Awal', 14, '(1) Perumusan mekanisme pemantauan dan evaluasi sebagaimana dimaksud dalam Pasal 33 huruf b dilakukan dengan menyusun rencana pelaksanaan pemantauan dan evaluasi RPBD.
(2) Rencana pelaksanaan pemantauan dan evaluasi RPBD sebagaimana dimaksud pada ayat (1) memuat:
a. waktu/frekuensi pelaksanaan;
b. objek pemantauan dan evaluasi;
c. pelaksana; dan
d. jenis laporan.
(3) Hasil perumusan mekanisme pemantauan dan evaluasi dituangkan dalam kertas kerja kerangka pemantauan dan evaluasi pelaksanaan RPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3229, '(1) Perumusan mekanisme pemantauan dan evaluasi sebagaimana dimaksud dalam Pasal 33 huruf b dilakukan dengan menyusun rencana pelaksanaan pemantauan dan evaluasi RPBD.
(2) Rencana pelaksanaan pemantauan dan evaluasi RPBD sebagaimana dimaksud pada ayat (1) memuat:
a. waktu/frekuensi pelaksanaan;
b. objek pemantauan dan evaluasi;
c. pelaksana; dan
d. jenis laporan.
(3) Hasil perumusan mekanisme pemantauan dan evaluasi dituangkan dalam kertas kerja kerangka pemantauan dan evaluasi pelaksanaan RPBD.', 'Pasal 35', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3230, 'perban-3-2026', 39, 'pasal', 'Pasal 36', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Keempat Pembahasan Antarperangkat Daerah.', 14, 'Format kertas kerja hasil penyusunan rancangan awal sebagaimana dimaksud dalam Pasal 15 ayat (3), Pasal 19 ayat (2), Pasal 21 ayat (5), Pasal 23 ayat (3), Pasal 27 ayat (3), Pasal 32, Pasal 35 ayat (3) tercantum dalam Lampiran II yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3230, 'Format kertas kerja hasil penyusunan rancangan awal sebagaimana dimaksud dalam Pasal 15 ayat (3), Pasal 19 ayat (2), Pasal 21 ayat (5), Pasal 23 ayat (3), Pasal 27 ayat (3), Pasal 32, Pasal 35 ayat (3) tercantum dalam Lampiran II yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 36', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3231, 'perban-3-2026', 40, 'pasal', 'Pasal 37', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Kelima Konsultasi Awal', 14, '(1) Pembahasan antarperangkat daerah sebagaimana dimaksd dalam Pasal 7 huruf c dilakukan terhadap rancangan awal yang telah disusun.
(2) Pembahasan antarperangkat daerah sebagaimana dimaksud pada ayat (1) digunakan sebagai wadah untuk mencapai kesepakatan atas materi muatan rancangan awal RPBD yang paling sedikit meliputi:
a. potensi ancaman bencana prioritas; dan
b. rumusan awal permasalahan dan isu strategis.
(3) Kesepakatan atas materi muatan rancangan awal RPBD sebagaimana dimaksud pada ayat (2) dirumuskan dalam berita acara.
(4) Hasil kesepakatan atas materi muatan rancangan awal RPBD sebagaimana dimaksud pada ayat (3) digunakan sebagai bahan perbaikan rancangan awal RPBD.
(5) Tim teknis melakukan perbaikan terhadap rancangan awal RPBD sebagaimana dimaksud pada ayat (4) sesuai berita acara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3231, '(1) Pembahasan antarperangkat daerah sebagaimana dimaksd dalam Pasal 7 huruf c dilakukan terhadap rancangan awal yang telah disusun.
(2) Pembahasan antarperangkat daerah sebagaimana dimaksud pada ayat (1) digunakan sebagai wadah untuk mencapai kesepakatan atas materi muatan rancangan awal RPBD yang paling sedikit meliputi:
a. potensi ancaman bencana prioritas; dan
b. rumusan awal permasalahan dan isu strategis.
(3) Kesepakatan atas materi muatan rancangan awal RPBD sebagaimana dimaksud pada ayat (2) dirumuskan dalam berita acara.
(4) Hasil kesepakatan atas materi muatan rancangan awal RPBD sebagaimana dimaksud pada ayat (3) digunakan sebagai bahan perbaikan rancangan awal RPBD.
(5) Tim teknis melakukan perbaikan terhadap rancangan awal RPBD sebagaimana dimaksud pada ayat (4) sesuai berita acara.', 'Pasal 37', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3232, 'perban-3-2026', 41, 'pasal', 'Pasal 38', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Keenam Penyusunan Rancangan Akhir', 14, '(1) Konsultasi awal sebagaimana dimaksud dalam Pasal 7 huruf d dilaksanakan untuk mendapatkan masukan terhadap:
a. kesesuaian sistematika dokumen;
b. penetapan potensi ancaman bencana prioritas;
c. perumusan awal permasalahan dan isu strategis;
d. perumusan tujuan, sasaran, dan strategi penanggulangan bencana; dan
e. perumusan program dan kegiatan penanggulangan bencana.
(2) Konsultasi awal sebagaimana dimaksud pada ayat (1) diajukan oleh Pemerintah Daerah kepada:
a. Kepala untuk RPBD Provinsi; dan
b. Gubernur untuk RPBD Kabupaten/Kota.
(3) Hasil konsultasi awal sebagaimana dimaksud pada ayat
(1) dituangkan dalam surat rekomendasi dengan melampirkan berita acara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3232, '(1) Konsultasi awal sebagaimana dimaksud dalam Pasal 7 huruf d dilaksanakan untuk mendapatkan masukan terhadap:
a. kesesuaian sistematika dokumen;
b. penetapan potensi ancaman bencana prioritas;
c. perumusan awal permasalahan dan isu strategis;
d. perumusan tujuan, sasaran, dan strategi penanggulangan bencana; dan
e. perumusan program dan kegiatan penanggulangan bencana.
(2) Konsultasi awal sebagaimana dimaksud pada ayat (1) diajukan oleh Pemerintah Daerah kepada:
a. Kepala untuk RPBD Provinsi; dan
b. Gubernur untuk RPBD Kabupaten/Kota.
(3) Hasil konsultasi awal sebagaimana dimaksud pada ayat
(1) dituangkan dalam surat rekomendasi dengan melampirkan berita acara.', 'Pasal 38', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3233, 'perban-3-2026', 42, 'pasal', 'Pasal 39', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Keenam Penyusunan Rancangan Akhir', 15, '(1) Penyusunan rancangan akhir RPBD sebagaimana dimaksud dalam Pasal 7 huruf e dilakukan setelah mendapatkan surat rekomendasi sebagaimana dimaksud dalam Pasal 38 ayat (3).
(2) Penyusunan rancangan akhir RPBD dilaksanakan melalui pembahasan oleh tim teknis dengan memperhatikan hasil konsultasi awal.
(3) Rancangan akhir RPBD disusun dengan sistematika yang sama dengan sistematika rancangan awal sebagaimana dimaksud dalam Pasal 13 ayat (2).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3233, '(1) Penyusunan rancangan akhir RPBD sebagaimana dimaksud dalam Pasal 7 huruf e dilakukan setelah mendapatkan surat rekomendasi sebagaimana dimaksud dalam Pasal 38 ayat (3).
(2) Penyusunan rancangan akhir RPBD dilaksanakan melalui pembahasan oleh tim teknis dengan memperhatikan hasil konsultasi awal.
(3) Rancangan akhir RPBD disusun dengan sistematika yang sama dengan sistematika rancangan awal sebagaimana dimaksud dalam Pasal 13 ayat (2).', 'Pasal 39', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3234, 'perban-3-2026', 43, 'pasal', 'Pasal 40', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketujuh Konsultasi Akhir', 15, '(1) Dalam penyusunan rancangan akhir dilakukan konsultasi publik untuk memperoleh kesepakatan terhadap muatan rancangan akhir RPBD.
(2) Muatan rancangan akhir RPBD sebagaimana dimaksud pada ayat (1), mencakup:
a. permasalahan dan isu strategis;
b. tujuan, sasaran, dan strategi penanggulangan bencana;
c. program dan kegiatan penanggulangan bencana;
d. mekanisme pelaksanaan; dan
e. kerangka pemantauan dan evaluasi.
(3) Konsultasi publik sebagaimana dimaksud pada ayat (1), melibatkan pemangku kepentingan yang meliputi:
a. unsur Perangkat Daerah;
b. forum pengurangan risiko bencana;
c. akademisi/forum perguruan tinggi;
d. lembaga usaha;
e. organisasi nonpemerintah;
f. media; dan
g. kelompok masyarakat, terutama kelompok rentan.
(4) Hasil kesepakatan konsultasi publik dirumuskan dalam berita acara.
(5) Hasil kesepakatan konsultasi publik sebagaimana dimaksud pada ayat (3) digunakan sebagai bahan perbaikan rancangan akhir RPBD.
(6) Tim teknis melakukan perbaikan terhadap rancangan akhir sesuai berita acara sebagaimana dimaksud pada ayat (3).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3234, '(1) Dalam penyusunan rancangan akhir dilakukan konsultasi publik untuk memperoleh kesepakatan terhadap muatan rancangan akhir RPBD.
(2) Muatan rancangan akhir RPBD sebagaimana dimaksud pada ayat (1), mencakup:
a. permasalahan dan isu strategis;
b. tujuan, sasaran, dan strategi penanggulangan bencana;
c. program dan kegiatan penanggulangan bencana;
d. mekanisme pelaksanaan; dan
e. kerangka pemantauan dan evaluasi.
(3) Konsultasi publik sebagaimana dimaksud pada ayat (1), melibatkan pemangku kepentingan yang meliputi:
a. unsur Perangkat Daerah;
b. forum pengurangan risiko bencana;
c. akademisi/forum perguruan tinggi;
d. lembaga usaha;
e. organisasi nonpemerintah;
f. media; dan
g. kelompok masyarakat, terutama kelompok rentan.
(4) Hasil kesepakatan konsultasi publik dirumuskan dalam berita acara.
(5) Hasil kesepakatan konsultasi publik sebagaimana dimaksud pada ayat (3) digunakan sebagai bahan perbaikan rancangan akhir RPBD.
(6) Tim teknis melakukan perbaikan terhadap rancangan akhir sesuai berita acara sebagaimana dimaksud pada ayat (3).', 'Pasal 40', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3235, 'perban-3-2026', 44, 'pasal', 'Pasal 41', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Ketujuh Konsultasi Akhir', 16, '(1) Konsultasi akhir sebagaimana dimaksud dalam Pasal 7 huruf f dilaksanakan untuk memeriksa dan memberi masukan terhadap:
a. kesesuaian sistematika dokumen;
b. penetapan permasalahan dan isu strategis;
c. perumusan tujuan, sasaran, dan strategi penanggulangan bencana;
d. perumusan program dan kegiatan penanggulangan bencana;
e. perumusan mekanisme pelaksanaan;
f. perumusan kerangka pemantauan dan evaluasi;
g. ketersediaan berita acara kesepakatan materi muatan rancangan awal sebagaimana dimaksud dalam Pasal 37 ayat (3) dan dokumen pendukungnya; dan
h. ketersediaan berita acara kesepakatan konsultasi publik sebagaimana dimaksud dalam Pasal 40 ayat (3) dan dokumen pendukungnya.
(2) Konsultasi akhir sebagaimana dimaksud pada ayat (1) diajukan oleh Pemerintah Daerah kepada:
a. Kepala untuk RPBD Provinsi; dan
b. Gubernur untuk RPBD Kabupaten/Kota.
(3) Hasil konsultasi akhir sebagaimana dimaksud pada ayat (1) dituangkan dalam berita acara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3235, '(1) Konsultasi akhir sebagaimana dimaksud dalam Pasal 7 huruf f dilaksanakan untuk memeriksa dan memberi masukan terhadap:
a. kesesuaian sistematika dokumen;
b. penetapan permasalahan dan isu strategis;
c. perumusan tujuan, sasaran, dan strategi penanggulangan bencana;
d. perumusan program dan kegiatan penanggulangan bencana;
e. perumusan mekanisme pelaksanaan;
f. perumusan kerangka pemantauan dan evaluasi;
g. ketersediaan berita acara kesepakatan materi muatan rancangan awal sebagaimana dimaksud dalam Pasal 37 ayat (3) dan dokumen pendukungnya; dan
h. ketersediaan berita acara kesepakatan konsultasi publik sebagaimana dimaksud dalam Pasal 40 ayat (3) dan dokumen pendukungnya.
(2) Konsultasi akhir sebagaimana dimaksud pada ayat (1) diajukan oleh Pemerintah Daerah kepada:
a. Kepala untuk RPBD Provinsi; dan
b. Gubernur untuk RPBD Kabupaten/Kota.
(3) Hasil konsultasi akhir sebagaimana dimaksud pada ayat (1) dituangkan dalam berita acara.', 'Pasal 41', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3236, 'perban-3-2026', 45, 'pasal', 'Pasal 42', 'BAB II TATA CARA PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH; Bagian Kedelapan Penetapan', 16, '(1) Hasil konsultasi akhir sebagaimana dimaksud dalam Pasal 41 ayat (3) digunakan sebagai bahan penyempurnaan rancangan akhir RPBD.
(2) Penyempurnaan rancangan akhir RPBD sebagaimana dimaksud pada ayat (1) dilaksanakan melalui pembahasan oleh tim teknis.
(3) Hasil penyempurnaan rancangan akhir RPBD sebagaimana dimaksud pada ayat (2) menjadi dasar pemberian surat rekomendasi oleh Kepala atau gubernur sesuai kewenangannya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3236, '(1) Hasil konsultasi akhir sebagaimana dimaksud dalam Pasal 41 ayat (3) digunakan sebagai bahan penyempurnaan rancangan akhir RPBD.
(2) Penyempurnaan rancangan akhir RPBD sebagaimana dimaksud pada ayat (1) dilaksanakan melalui pembahasan oleh tim teknis.
(3) Hasil penyempurnaan rancangan akhir RPBD sebagaimana dimaksud pada ayat (2) menjadi dasar pemberian surat rekomendasi oleh Kepala atau gubernur sesuai kewenangannya.', 'Pasal 42', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3237, 'perban-3-2026', 46, 'pasal', 'Pasal 43', 'BAB III PENINJAUAN DAN PERUBAHAN RENCANA PENANGGULANGAN BENCANA DAERAH', 17, '(1) Rancangan akhir RPBD sebagaimana dimaksud dalam Pasal 42 menjadi bagian dari penyusunan rancangan Perkada mengenai RPBD.
(2) Rancangan Perkada mengenai RPBD sebagaimana dimaksud pada ayat (1) ditetapkan oleh Kepala Daerah paling lama 1 (satu) tahun setelah penyampaian rancangan akhir RPBD.
(3) Mekanisme penyusunan dan penetapan rancangan Perkada mengenai RPBD sebagaimana dimaksud pada ayat (1) dan ayat (2) dilaksanakan sesuai ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3237, '(1) Rancangan akhir RPBD sebagaimana dimaksud dalam Pasal 42 menjadi bagian dari penyusunan rancangan Perkada mengenai RPBD.
(2) Rancangan Perkada mengenai RPBD sebagaimana dimaksud pada ayat (1) ditetapkan oleh Kepala Daerah paling lama 1 (satu) tahun setelah penyampaian rancangan akhir RPBD.
(3) Mekanisme penyusunan dan penetapan rancangan Perkada mengenai RPBD sebagaimana dimaksud pada ayat (1) dan ayat (2) dilaksanakan sesuai ketentuan peraturan perundang-undangan.', 'Pasal 43', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3238, 'perban-3-2026', 47, 'pasal', 'Pasal 44', 'BAB III PENINJAUAN DAN PERUBAHAN RENCANA PENANGGULANGAN BENCANA DAERAH', 17, '(1) Peninjauan RPBD dilakukan secara berkala setiap 2 (dua) tahun atau sewaktu-waktu apabila terjadi bencana.
(2) Peninjauan RPBD sebagaimana dimaksud pada ayat (1) dilakukan dengan memperhatikan:
a. hasil pemantauan dan evaluasi RPBD; dan/atau
b. pemutakhiran KRB.
(3) Hasil peninjauan RPBD dapat digunakan untuk pemaduan penanggulangan bencana ke dalam perencanaan pembangunan daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3238, '(1) Peninjauan RPBD dilakukan secara berkala setiap 2 (dua) tahun atau sewaktu-waktu apabila terjadi bencana.
(2) Peninjauan RPBD sebagaimana dimaksud pada ayat (1) dilakukan dengan memperhatikan:
a. hasil pemantauan dan evaluasi RPBD; dan/atau
b. pemutakhiran KRB.
(3) Hasil peninjauan RPBD dapat digunakan untuk pemaduan penanggulangan bencana ke dalam perencanaan pembangunan daerah.', 'Pasal 44', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3239, 'perban-3-2026', 48, 'pasal', 'Pasal 45', 'BAB IV PEMADUAN RENCANA PENANGGULANGAN BENCANA DAERAH DALAM PERENCANAAN PEMBANGUNAN DAERAH', 17, '(1) Pemutakhiran KRB sebagaimana dimaksud dalam Pasal 44 ayat (2) huruf b menjadi dasar perubahan RPBD.
(2) Perubahan RPBD sebagaimana dimaksud pada ayat (1) dilakukan apabila sisa masa berlaku RPBD paling sedikit (3) tiga tahun.
(3) Perubahan RPBD sebagaimana dimaksud pada ayat (2) tidak mengubah masa berlaku RPBD.
(4) Perubahan RPBD ditetapkan melalui Perkada.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3239, '(1) Pemutakhiran KRB sebagaimana dimaksud dalam Pasal 44 ayat (2) huruf b menjadi dasar perubahan RPBD.
(2) Perubahan RPBD sebagaimana dimaksud pada ayat (1) dilakukan apabila sisa masa berlaku RPBD paling sedikit (3) tiga tahun.
(3) Perubahan RPBD sebagaimana dimaksud pada ayat (2) tidak mengubah masa berlaku RPBD.
(4) Perubahan RPBD ditetapkan melalui Perkada.', 'Pasal 45', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3240, 'perban-3-2026', 49, 'pasal', 'Pasal 46', 'BAB V PEMANTAUAN DAN EVALUASI RENCANA PENANGGULANGAN BENCANA DAERAH', 17, '(1) Pemerintah Daerah melakukan pemaduan penanggulangan bencana ke dalam rencana pembangunan daerah untuk menjamin efektivitas penyelenggaraan penanggulangan bencana.
(2) Pemaduan sebagaimana dimaksud pada ayat (1) dilaksanakan dengan cara mencantumkan unsur RPBD ke dalam rencana pembangunan daerah.
(3) Pemaduan sebagaimana dimaksud pada ayat (2) dilakukan melalui:
a. koordinasi;
b. integrasi; dan
c. sinkronisasi.
(4) Unsur RPBD sebagaimana dimaksud pada ayat (2), meliputi:
a. pengenalan dan pengkajian ancaman bencana;
b. pemahaman tentang kerentanan masyarakat;
c. analisis kemungkinan dampak bencana;
d. pilihan tindakan pengurangan risiko bencana;
e. penentuan mekanisme kesiapan dan penanggulangan dampak bencana; dan
f. alokasi tugas, kewenangan, dan sumber daya yang tersedia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3240, '(1) Pemerintah Daerah melakukan pemaduan penanggulangan bencana ke dalam rencana pembangunan daerah untuk menjamin efektivitas penyelenggaraan penanggulangan bencana.
(2) Pemaduan sebagaimana dimaksud pada ayat (1) dilaksanakan dengan cara mencantumkan unsur RPBD ke dalam rencana pembangunan daerah.
(3) Pemaduan sebagaimana dimaksud pada ayat (2) dilakukan melalui:
a. koordinasi;
b. integrasi; dan
c. sinkronisasi.
(4) Unsur RPBD sebagaimana dimaksud pada ayat (2), meliputi:
a. pengenalan dan pengkajian ancaman bencana;
b. pemahaman tentang kerentanan masyarakat;
c. analisis kemungkinan dampak bencana;
d. pilihan tindakan pengurangan risiko bencana;
e. penentuan mekanisme kesiapan dan penanggulangan dampak bencana; dan
f. alokasi tugas, kewenangan, dan sumber daya yang tersedia.', 'Pasal 46', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3241, 'perban-3-2026', 50, 'pasal', 'Pasal 47', 'BAB V PEMANTAUAN DAN EVALUASI RENCANA PENANGGULANGAN BENCANA DAERAH', 18, '(1) Pemantauan dan evaluasi RPBD dikoordinasikan oleh Kepala BPBD dan dapat melibatkan Perangkat Daerah dan/atau pemangku kepentingan terkait.
(2) Pemantauan dan evaluasi RPBD sebagaimana dimaksud pada ayat (1) dilaksanakan paling sedikit 1 (satu) kali dalam 1 (satu) tahun.
(3) Hasil pemantauan dan evaluasi RPBD sebagaimana dimaksud pada ayat (1) dituangkan dalam bentuk laporan.
(4) Laporan sebagaimana dimaksud pada ayat (3) disampaikan kepada:
a. Kepala Daerah; dan
b. Kepala.
(5) Laporan hasil pemantauan dan evaluasi RPBD kabupaten/kota disampaikan kepada Kepala melalui Gubernur.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3241, '(1) Pemantauan dan evaluasi RPBD dikoordinasikan oleh Kepala BPBD dan dapat melibatkan Perangkat Daerah dan/atau pemangku kepentingan terkait.
(2) Pemantauan dan evaluasi RPBD sebagaimana dimaksud pada ayat (1) dilaksanakan paling sedikit 1 (satu) kali dalam 1 (satu) tahun.
(3) Hasil pemantauan dan evaluasi RPBD sebagaimana dimaksud pada ayat (1) dituangkan dalam bentuk laporan.
(4) Laporan sebagaimana dimaksud pada ayat (3) disampaikan kepada:
a. Kepala Daerah; dan
b. Kepala.
(5) Laporan hasil pemantauan dan evaluasi RPBD kabupaten/kota disampaikan kepada Kepala melalui Gubernur.', 'Pasal 47', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3242, 'perban-3-2026', 51, 'pasal', 'Pasal 48', 'BAB VI KETENTUAN PERALIHAN', 18, 'Laporan hasil pemantauan dan evaluasi RPBD sebagaimana dimaksud dalam Pasal 47 menjadi bahan pemantauan dan evaluasi terhadap pelaksanaan RIPB Tahun 2020-2044 dan RENAS PB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3242, 'Laporan hasil pemantauan dan evaluasi RPBD sebagaimana dimaksud dalam Pasal 47 menjadi bahan pemantauan dan evaluasi terhadap pelaksanaan RIPB Tahun 2020-2044 dan RENAS PB.', 'Pasal 48', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3243, 'perban-3-2026', 52, 'pasal', 'Pasal 49', 'BAB VII KETENTUAN PENUTUP', 18, 'Pada saat Peraturan Badan ini mulai berlaku:
a. RPBD yang sudah ditetapkan, dinyatakan masih berlaku sampai dengan berakhirnya RPBD;
b. rancangan RPBD yang telah memasuki tahapan penyusunan rancangan akhir dan belum dilakukan penetapan, dilakukan penyesuaian melalui tahapan konsultasi akhir sesuai dengan ketentuan Peraturan Badan ini; dan
c. proses penyusunan RPBD yang masih dalam tahapan penyusunan rancangan awal harus menyesuaikan dengan ketentuan dalam Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3243, 'Pada saat Peraturan Badan ini mulai berlaku:
a. RPBD yang sudah ditetapkan, dinyatakan masih berlaku sampai dengan berakhirnya RPBD;
b. rancangan RPBD yang telah memasuki tahapan penyusunan rancangan akhir dan belum dilakukan penetapan, dilakukan penyesuaian melalui tahapan konsultasi akhir sesuai dengan ketentuan Peraturan Badan ini; dan
c. proses penyusunan RPBD yang masih dalam tahapan penyusunan rancangan awal harus menyesuaikan dengan ketentuan dalam Peraturan Badan ini.', 'Pasal 49', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3244, 'perban-3-2026', 53, 'pasal', 'Pasal 50', 'BAB VII KETENTUAN PENUTUP', 19, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 1088), dicabut dan dinyatakan tidak berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3244, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 1088), dicabut dan dinyatakan tidak berlaku.', 'Pasal 50', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3245, 'perban-3-2026', 54, 'pasal', 'Pasal 51', 'BAB VII KETENTUAN PENUTUP', 19, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3245, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 51', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3246, 'perban-3-2026', 55, 'lain', 'Penutup', NULL, 20, 'Ditetapkan di Jakarta pada tanggal 06 Oktober 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2026 NOMOR Ж');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3246, 'Ditetapkan di Jakarta pada tanggal 06 Oktober 2026 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2026 NOMOR Ж', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3247, 'perban-3-2026', 56, 'lampiran', 'Lampiran hal. 21', NULL, 21, 'LAMPIRAN I PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 3 TAHUN 2026 TENTANG PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH SISTEMATIKA DOKUMEN RENCANA PENANGGULANGAN BENCANA DAERAH Daftar Singkatan Bagian ini berisi penjelasan singkatan yang digunakan dalam dokumen RPBD untuk mempermudah pemahaman pembaca.
Daftar Isi Bagian ini berisi judul-judul bagian (bab, subbab, dan/atau sub-subbab) dalam dokumen RPBD yang disertai nomor halaman. Pada bagian ini dapat ditambahkan daftar judul-judul gambar dan tabel yang disajikan dalam dokumen.
Bab I Pendahuluan 1.1 Latar Belakang Subbab ini berisi penjelasan ringkas mengenai 4 (empat) hal utama yaitu: a) Alasan mengapa RPBD penting bagi pemerintah daerah. b) Konteks periode waktu perencanaan dalam RPBD dan hubungannya dengan rencana pembangunan 5 (lima) tahunan di daerah. Pada subbab ini perlu ditekankan bahwa RPBD akan menjadi salah satu bahan masukan dalam penyusunan RPJMD, Renstra Perangkat Daerah ataupun penyusunan RKPD sebagai penjabaran RPJMD dan penyusunan Renja Perangkat Daerah sebagai penjabaran Renstra Perangkat Daerah. Pada subbab ini juga perlu ditekankan hubungan dokumen RPBD dengan dokumen perencanaan penanggulangan bencana di tingkat nasional (RIPB dan RENAS PB). c) RPBD sebagai dokumen yang disusun dengan melibatkan multipihak dan penjelasan siapa yang terlibat dalam penyusunannya. d) RPBD sebagai dokumen yang perlu diacu oleh semua pihak dalam pengelolaan risiko bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3247, 'LAMPIRAN I PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 3 TAHUN 2026 TENTANG PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH SISTEMATIKA DOKUMEN RENCANA PENANGGULANGAN BENCANA DAERAH Daftar Singkatan Bagian ini berisi penjelasan singkatan yang digunakan dalam dokumen RPBD untuk mempermudah pemahaman pembaca.
Daftar Isi Bagian ini berisi judul-judul bagian (bab, subbab, dan/atau sub-subbab) dalam dokumen RPBD yang disertai nomor halaman. Pada bagian ini dapat ditambahkan daftar judul-judul gambar dan tabel yang disajikan dalam dokumen.
Bab I Pendahuluan 1.1 Latar Belakang Subbab ini berisi penjelasan ringkas mengenai 4 (empat) hal utama yaitu: a) Alasan mengapa RPBD penting bagi pemerintah daerah. b) Konteks periode waktu perencanaan dalam RPBD dan hubungannya dengan rencana pembangunan 5 (lima) tahunan di daerah. Pada subbab ini perlu ditekankan bahwa RPBD akan menjadi salah satu bahan masukan dalam penyusunan RPJMD, Renstra Perangkat Daerah ataupun penyusunan RKPD sebagai penjabaran RPJMD dan penyusunan Renja Perangkat Daerah sebagai penjabaran Renstra Perangkat Daerah. Pada subbab ini juga perlu ditekankan hubungan dokumen RPBD dengan dokumen perencanaan penanggulangan bencana di tingkat nasional (RIPB dan RENAS PB). c) RPBD sebagai dokumen yang disusun dengan melibatkan multipihak dan penjelasan siapa yang terlibat dalam penyusunannya. d) RPBD sebagai dokumen yang perlu diacu oleh semua pihak dalam pengelolaan risiko bencana di daerah.', 'Lampiran hal. 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3248, 'perban-3-2026', 57, 'lampiran', 'Lampiran hal. 21', NULL, 21, '1.2 Tujuan Subbab ini berisi uraian ringkas tentang tujuan penyusunan dokumen RPBD.
1.3 Kedudukan Dokumen Subbab ini berisi penjelasan tentang kedudukan atau posisi RPBD dalam perencanaan penanggulangan bencana dan hubungannya dengan dokumen perencanaan lainnya.
1.4 Landasan Hukum Subbab ini berisi daftar peraturan perundang-undangan di tingkat pusat dan daerah yang menjadi dasar hukum dan pertimbangan dalam penyusunan dokumen RPBD.
1.5 Ruang Lingkup Subbab ini berisi penjelasan ringkas masing-masing ruang lingkup atau cakupan dokumen RPBD, sekurang-kurangnya meliputi unsur RPBD sebagai berikut. a) Pengenalan dan pengkajian ancaman bencana.
Berisi penjelasan mengenai hasil pengkajian bahaya/ancaman risiko bencana berupa ancaman bencana/bahaya (hazard) yang dihadapi oleh wilayah tersebut, yang diuraikan dalam BAB III. b) Pemahaman tentang kerentanan masyarakat.
Berisi penjelasan mengenai hasil pengkajian kerentanan (vulnerability), keadaan atau sifat/perilaku manusia atau masyarakat yang menyebabkan ketidakmampuan menghadapi bahaya atau ancaman, yang diuraikan dalam BAB III. c) Analisis kemungkinan dampak bencana.
Berisi penjelasan hasil pengkajian risiko terhadap kemungkinan dampak yang ditimbulkan oleh bencana, yang menghubungkan faktor ancaman, kerentanan, dan kemampuan daerah, termasuk permasalahan dan isu strategis kebencanaan, yang diuraikan dalam BAB III. d) Pilihan tindakan pengurangan risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3248, '1.2 Tujuan Subbab ini berisi uraian ringkas tentang tujuan penyusunan dokumen RPBD.
1.3 Kedudukan Dokumen Subbab ini berisi penjelasan tentang kedudukan atau posisi RPBD dalam perencanaan penanggulangan bencana dan hubungannya dengan dokumen perencanaan lainnya.
1.4 Landasan Hukum Subbab ini berisi daftar peraturan perundang-undangan di tingkat pusat dan daerah yang menjadi dasar hukum dan pertimbangan dalam penyusunan dokumen RPBD.
1.5 Ruang Lingkup Subbab ini berisi penjelasan ringkas masing-masing ruang lingkup atau cakupan dokumen RPBD, sekurang-kurangnya meliputi unsur RPBD sebagai berikut. a) Pengenalan dan pengkajian ancaman bencana.
Berisi penjelasan mengenai hasil pengkajian bahaya/ancaman risiko bencana berupa ancaman bencana/bahaya (hazard) yang dihadapi oleh wilayah tersebut, yang diuraikan dalam BAB III. b) Pemahaman tentang kerentanan masyarakat.
Berisi penjelasan mengenai hasil pengkajian kerentanan (vulnerability), keadaan atau sifat/perilaku manusia atau masyarakat yang menyebabkan ketidakmampuan menghadapi bahaya atau ancaman, yang diuraikan dalam BAB III. c) Analisis kemungkinan dampak bencana.
Berisi penjelasan hasil pengkajian risiko terhadap kemungkinan dampak yang ditimbulkan oleh bencana, yang menghubungkan faktor ancaman, kerentanan, dan kemampuan daerah, termasuk permasalahan dan isu strategis kebencanaan, yang diuraikan dalam BAB III. d) Pilihan tindakan pengurangan risiko bencana.', 'Lampiran hal. 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3249, 'perban-3-2026', 58, 'lampiran', 'Lampiran hal. 22', NULL, 22, 'Berisi penjelasan pilihan tindakan mengenai upaya penanggulangan yang akan dilakukan berdasarkan ancaman prioritas yang akan ditangani dan kemungkinan dampak yang ditimbulkan, yang diuraikan dalam BAB IV dan BAB V. e) Penentuan mekanisme kesiapan dan penanggulangan dampak bencana.
Berisi penjelasan mekanisme kesiapan dan penanggulangan dampak bencana, berupa perumusan tujuan, sasaran, strategi, program dan kegiatan penanggulangan bencana, yang diuraikan dalam BAB IV dan BAB V. f) ⁠Alokasi tugas, kewenangan, dan sumber daya yang tersedia serta pelibatan para pihak.
Berisi penjelasan mengenai pembagian alokasi tugas, kewenangan, dan sumber daya dalam pembagian peran dan fungsi pemerintahan, non pemerintah serta potensi masyarakat yang diuraikan dalam BAB IV dan BAB V.
1.6 Sistematika Dokumen Subbab ini berisi penjelasan tentang struktur dokumen RPBD dengan pengaturan bab serta garis besar isi dari setiap bab di dalamnya.
Bab II Kebijakan Penanggulangan Bencana Bab ini berisi ringkasan hasil penelaahan atas kebijakan nasional dan daerah yang berkaitan dengan penanggulangan bencana. Untuk dokumen RPBD provinsi, hasil penelaahan atas kebijakan yang disajikan meliputi kebijakan di tingkat nasional dan provinsi, sedangkan untuk dokumen RPBD kabupaten/kota kebijakan di tingkat nasional, provinsi, dan kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3249, 'Berisi penjelasan pilihan tindakan mengenai upaya penanggulangan yang akan dilakukan berdasarkan ancaman prioritas yang akan ditangani dan kemungkinan dampak yang ditimbulkan, yang diuraikan dalam BAB IV dan BAB V. e) Penentuan mekanisme kesiapan dan penanggulangan dampak bencana.
Berisi penjelasan mekanisme kesiapan dan penanggulangan dampak bencana, berupa perumusan tujuan, sasaran, strategi, program dan kegiatan penanggulangan bencana, yang diuraikan dalam BAB IV dan BAB V. f) ⁠Alokasi tugas, kewenangan, dan sumber daya yang tersedia serta pelibatan para pihak.
Berisi penjelasan mengenai pembagian alokasi tugas, kewenangan, dan sumber daya dalam pembagian peran dan fungsi pemerintahan, non pemerintah serta potensi masyarakat yang diuraikan dalam BAB IV dan BAB V.
1.6 Sistematika Dokumen Subbab ini berisi penjelasan tentang struktur dokumen RPBD dengan pengaturan bab serta garis besar isi dari setiap bab di dalamnya.
Bab II Kebijakan Penanggulangan Bencana Bab ini berisi ringkasan hasil penelaahan atas kebijakan nasional dan daerah yang berkaitan dengan penanggulangan bencana. Untuk dokumen RPBD provinsi, hasil penelaahan atas kebijakan yang disajikan meliputi kebijakan di tingkat nasional dan provinsi, sedangkan untuk dokumen RPBD kabupaten/kota kebijakan di tingkat nasional, provinsi, dan kabupaten/kota.', 'Lampiran hal. 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3250, 'perban-3-2026', 59, 'lampiran', 'Lampiran hal. 22', NULL, 22, '2.1. Kebijakan Tingkat Nasional Subbab ini berisi ringkasan hasil penelaahan atas kebijakan dan kerangka penanggulangan bencana di tingkat nasional yang menjadi acuan, rujukan, pedoman, dan kontekstual dengan perencanaan penanggulangan bencana di daerah. Kebijakan nasional yang ditinjau meliputi Rencana Induk Penanggulangan Bencana (RIPB) dan Rencana Nasional Penanggulangan Bencana (RENAS PB). Pada bagian akhir ringkasan ditambahkan keterkaitan hasil penelaahan substansi kebijakan tingkat nasional dengan sasaran dan strategi penanggulangan bencana provinsi/kabupaten/kota dalam muatan RPBD.
2.2. Kebijakan Tingkat Daerah Subbab ini berisi ringkasan hasil penelaahan atas kebijakan dan kerangka kerja penanggulangan bencana di tingkat daerah yang menjadi acuan, rujukan, pedoman, dan kontekstual dengan perencanaan penanggulangan bencana. Kebijakan dan kerangka penanggulangan bencana di tingkat daerah yang ditinjau meliputi RPJPD, peraturan daerah tentang penanggulangan bencana, peraturan daerah tentang bangunan aman bencana dan lainnya yang telah ditetapkan dalam bentuk produk hukum daerah. Untuk dokumen RPBD kabupaten/kota, penelaahan kebijakan tingkat daerah meliputi penelaahan RPBD provinsi. Pada bagian akhir ringkasan ditambahkan keterkaitan hasil penelaahan substansi kebijakan tingkat daerah dengan sasaran dan strategi penanggulangan bencana provinsi/kabupaten/kota dalam muatan RPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3250, '2.1. Kebijakan Tingkat Nasional Subbab ini berisi ringkasan hasil penelaahan atas kebijakan dan kerangka penanggulangan bencana di tingkat nasional yang menjadi acuan, rujukan, pedoman, dan kontekstual dengan perencanaan penanggulangan bencana di daerah. Kebijakan nasional yang ditinjau meliputi Rencana Induk Penanggulangan Bencana (RIPB) dan Rencana Nasional Penanggulangan Bencana (RENAS PB). Pada bagian akhir ringkasan ditambahkan keterkaitan hasil penelaahan substansi kebijakan tingkat nasional dengan sasaran dan strategi penanggulangan bencana provinsi/kabupaten/kota dalam muatan RPBD.
2.2. Kebijakan Tingkat Daerah Subbab ini berisi ringkasan hasil penelaahan atas kebijakan dan kerangka kerja penanggulangan bencana di tingkat daerah yang menjadi acuan, rujukan, pedoman, dan kontekstual dengan perencanaan penanggulangan bencana. Kebijakan dan kerangka penanggulangan bencana di tingkat daerah yang ditinjau meliputi RPJPD, peraturan daerah tentang penanggulangan bencana, peraturan daerah tentang bangunan aman bencana dan lainnya yang telah ditetapkan dalam bentuk produk hukum daerah. Untuk dokumen RPBD kabupaten/kota, penelaahan kebijakan tingkat daerah meliputi penelaahan RPBD provinsi. Pada bagian akhir ringkasan ditambahkan keterkaitan hasil penelaahan substansi kebijakan tingkat daerah dengan sasaran dan strategi penanggulangan bencana provinsi/kabupaten/kota dalam muatan RPBD.', 'Lampiran hal. 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3251, 'perban-3-2026', 60, 'lampiran', 'Lampiran hal. 23', NULL, 23, 'Bab III Karakteristik Daerah dan Isu Strategis Kebencanaan 3.1. Kondisi Umum Daerah Subbab ini berisi ringkasan penjelasan tentang aspek geografis, geologis, topografis, hidrologis, klimatologis, demografis, ekonomi, dan tata ruang yang berkaitan dengan kebencanaan. Pada subbab ini dibahas juga terkait analisis kelembagaan dan pendanaan dalam penanggulangan bencana di daerah.
Aspek kelembagaan dalam penanggulangan bencana berisi ringkasan kondisi kelembagaan formal dan non-formal dalam penyelenggaraan penanggulangan bencana yang sudah terbentuk beserta peran dan fungsinya.
Aspek pendanaan dalam penanggulangan bencana berisi uraian ringkasan kondisi kapasitas fiskal daerah, proporsi realisasi belanja per urusan Standar Pelayanan Minimal, pertumbuhan dan proporsi realisasi belanja sub-urusan bencana. Pada subbab ini juga ditambahkan ringkasan pemanfaatan dana siap pakai, belanja tidak terduga, dan pemanfaatan dana dari sumber pendanaan pemerintah maupun non pemerintah lainnya. Ringkasan aspek pendanaan dalam penanggulangan bencana memuat tabel sesuai Kertas Kerja 4 pada Lampiran 1.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3251, 'Bab III Karakteristik Daerah dan Isu Strategis Kebencanaan 3.1. Kondisi Umum Daerah Subbab ini berisi ringkasan penjelasan tentang aspek geografis, geologis, topografis, hidrologis, klimatologis, demografis, ekonomi, dan tata ruang yang berkaitan dengan kebencanaan. Pada subbab ini dibahas juga terkait analisis kelembagaan dan pendanaan dalam penanggulangan bencana di daerah.
Aspek kelembagaan dalam penanggulangan bencana berisi ringkasan kondisi kelembagaan formal dan non-formal dalam penyelenggaraan penanggulangan bencana yang sudah terbentuk beserta peran dan fungsinya.
Aspek pendanaan dalam penanggulangan bencana berisi uraian ringkasan kondisi kapasitas fiskal daerah, proporsi realisasi belanja per urusan Standar Pelayanan Minimal, pertumbuhan dan proporsi realisasi belanja sub-urusan bencana. Pada subbab ini juga ditambahkan ringkasan pemanfaatan dana siap pakai, belanja tidak terduga, dan pemanfaatan dana dari sumber pendanaan pemerintah maupun non pemerintah lainnya. Ringkasan aspek pendanaan dalam penanggulangan bencana memuat tabel sesuai Kertas Kerja 4 pada Lampiran 1.', 'Lampiran hal. 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3252, 'perban-3-2026', 61, 'lampiran', 'Lampiran hal. 23', NULL, 23, '3.2. Karakteristik Kebencanaan Daerah Subbab ini menguraikan hasil analisis data kejadian bencana yang menampilkan data ringkasan data jenis, jumlah, dan besaran dampak yang ditimbulkan oleh bencana dalam kurun waktu 10 (sepuluh) tahun terakhir, dengan ketentuan untuk bencana geologi tidak dibatasi dengan tahun kejadian. Subbab ini juga menguraikan hasil analisis data tingkat risiko bencana dan menampilkan ringkasan data tingkat risiko jenis ancaman bencana dalam bentuk tabel sesuai Kertas Kerja 8 pada Lampiran 1.
3.3. Potensi Ancaman Bencana Prioritas Sub bab ini berisi penjelasan tentang potensi ancaman bencana yang menjadi prioritas untuk dikelola daerah sesuai penilaian tingkat risiko dan kecenderungan kejadian bencana. Penjelasan dilakukan per butir potensi ancaman bencana prioritas dalam bentuk uraian kalimat. Pada setiap potensi ancaman bencana prioritas perlu disajikan pula ringkasan informasi luas wilayah berisiko, estimasi jumlah penduduk terpapar, potensi kerugian dan kerusakan lingkungan, serta tingkat risiko. Informasi tersebut dapat disajikan dalam bentuk tabel, diagram, infografis, atau bentuk lainnya.
3.4. Kinerja Penanggulangan Bencana Subbab ini berisi ringkasan kinerja pelaksanaan penanggulangan bencana yang meliputi: a) hasil evaluasi pelaksanaan RPBD periode sebelumnya; b) pencapaian penerapan SPM sub-urusan Bencana; dan/atau c) hasil penilaian Indeks Risiko Bencana (IRB), Indeks Ketahanan Daerah (IKD), dan parameter penilaian terkait lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3252, '3.2. Karakteristik Kebencanaan Daerah Subbab ini menguraikan hasil analisis data kejadian bencana yang menampilkan data ringkasan data jenis, jumlah, dan besaran dampak yang ditimbulkan oleh bencana dalam kurun waktu 10 (sepuluh) tahun terakhir, dengan ketentuan untuk bencana geologi tidak dibatasi dengan tahun kejadian. Subbab ini juga menguraikan hasil analisis data tingkat risiko bencana dan menampilkan ringkasan data tingkat risiko jenis ancaman bencana dalam bentuk tabel sesuai Kertas Kerja 8 pada Lampiran 1.
3.3. Potensi Ancaman Bencana Prioritas Sub bab ini berisi penjelasan tentang potensi ancaman bencana yang menjadi prioritas untuk dikelola daerah sesuai penilaian tingkat risiko dan kecenderungan kejadian bencana. Penjelasan dilakukan per butir potensi ancaman bencana prioritas dalam bentuk uraian kalimat. Pada setiap potensi ancaman bencana prioritas perlu disajikan pula ringkasan informasi luas wilayah berisiko, estimasi jumlah penduduk terpapar, potensi kerugian dan kerusakan lingkungan, serta tingkat risiko. Informasi tersebut dapat disajikan dalam bentuk tabel, diagram, infografis, atau bentuk lainnya.
3.4. Kinerja Penanggulangan Bencana Subbab ini berisi ringkasan kinerja pelaksanaan penanggulangan bencana yang meliputi: a) hasil evaluasi pelaksanaan RPBD periode sebelumnya; b) pencapaian penerapan SPM sub-urusan Bencana; dan/atau c) hasil penilaian Indeks Risiko Bencana (IRB), Indeks Ketahanan Daerah (IKD), dan parameter penilaian terkait lainnya.', 'Lampiran hal. 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3253, 'perban-3-2026', 62, 'lampiran', 'Lampiran hal. 23', NULL, 23, '3.5. Permasalahan Subbab ini menguraikan permasalahan kebencanaan dalam penyelenggaraan penanggulangan bencana di daerah, termasuk permasalahan terkait potensi ancaman bencana prioritas yang akan dikelola dan diselesaikan. Hasil rumusan permasalahan dijabarkan secara deskriptif per butir permasalahan dalam bentuk uraian kalimat dan didukung dengan data dan informasi yang valid dan relevan terhadap masalah yang diuraikan.
Permasalahan yang tidak diprioritaskan dalam proses perumusan isu strategis atau tidak menjadi agenda utama rencana penanggulangan bencana daerah dalam 5 (lima) tahun ke depan tidak perlu disajikan dalam bagian ini (tetap berada dalam kertas kerja perumusan).
3.6. Isu Strategis Subbab ini berisi hasil rumusan isu strategis kebencanaan yang dapat berasal dari masalah pokok yang dianggap paling prioritas untuk diselesaikan dalam 5 (lima) tahun ke depan maupun isu di tingkat nasional dan regional (kawasan, lintas kabupaten/kota, lintas provinsi, atau wilayah pulau) serta dapat ditambahkan isu internasional.
Rumusan isu strategis kebencanaan dijabarkan secara deskriptif per butir isu strategis dalam bentuk uraian kalimat. Deskripsi pada setiap isu strategis berisi penjabaran penting mengenai manfaat atau pengaruh dan hal-hal yang perlu direspons di masa mendatang dalam konteks penanggulangan bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3253, '3.5. Permasalahan Subbab ini menguraikan permasalahan kebencanaan dalam penyelenggaraan penanggulangan bencana di daerah, termasuk permasalahan terkait potensi ancaman bencana prioritas yang akan dikelola dan diselesaikan. Hasil rumusan permasalahan dijabarkan secara deskriptif per butir permasalahan dalam bentuk uraian kalimat dan didukung dengan data dan informasi yang valid dan relevan terhadap masalah yang diuraikan.
Permasalahan yang tidak diprioritaskan dalam proses perumusan isu strategis atau tidak menjadi agenda utama rencana penanggulangan bencana daerah dalam 5 (lima) tahun ke depan tidak perlu disajikan dalam bagian ini (tetap berada dalam kertas kerja perumusan).
3.6. Isu Strategis Subbab ini berisi hasil rumusan isu strategis kebencanaan yang dapat berasal dari masalah pokok yang dianggap paling prioritas untuk diselesaikan dalam 5 (lima) tahun ke depan maupun isu di tingkat nasional dan regional (kawasan, lintas kabupaten/kota, lintas provinsi, atau wilayah pulau) serta dapat ditambahkan isu internasional.
Rumusan isu strategis kebencanaan dijabarkan secara deskriptif per butir isu strategis dalam bentuk uraian kalimat. Deskripsi pada setiap isu strategis berisi penjabaran penting mengenai manfaat atau pengaruh dan hal-hal yang perlu direspons di masa mendatang dalam konteks penanggulangan bencana di daerah.', 'Lampiran hal. 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3254, 'perban-3-2026', 63, 'lampiran', 'Lampiran hal. 24', NULL, 24, 'Bab IV Tujuan, Sasaran, dan Strategi Penanggulangan Bencana 4.1. Tujuan dan Sasaran Subbab ini berisi hasil rumusan pernyataan tujuan, sasaran, indikator sasaran dari penyelenggaraan penanggulangan bencana dalam jangka 5 (lima) tahun yang didasarkan atas permasalahan dan/atau isu-isu strategis kebencanaan. Pada subbab ini diuraikan sekurang-kurangnya hal-hal berikut. a) Ringkasan penjelasan tujuan dan sasaran penanggulangan bencana dalam 5 (lima) tahun. b) Pernyataan tujuan penanggulangan bencana dalam bahasa yang jelas, ringkas, dan mudah dipahami. c) Pernyataan sasaran-sasaran penanggulangan bencana dalam bahasa yang jelas, ringkas, dan mudah dipahami. d) Pernyataan indikator sasaran dan target dalam jangka waktu 5 (lima) tahun pada setiap sasaran yang disajikan dalam bentuk tabel/matriks. e) Pernyataan tujuan dan sasaran dapat disajikan dalam tabel sebagai berikut:
Tabel 2-1 Tujuan dan Sasaran Penanggulangan Bencana Provinsi/Kabupaten/Kota.....*) Tahun ..... **) KONDISI TARGET INDIKATOR SATU AWAL/ TAHUN TAHUN TAHUN TAHUN TAHUN TUJUAN SASARAN SASARAN AN 1***) 2***) 3***) 4***) 5***) BASELIN E
(1) (2) (3) (4) (5) (6) Tujuan-1 Sasaran Indikator 1.1 Sasaran 1.1 Sasaran Indikator 1.2 Sasaran 1.2 Sasaran Indikator 1.3 Sasaran 1.3 Keterangan: *) diisi dengan nama provinsi/kabupaten/kota **) diisi dengan periode tahun perencanaan ***) disesuaikan dengan periode RPBD
(1) diisi dengan pernyataan tujuan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3254, 'Bab IV Tujuan, Sasaran, dan Strategi Penanggulangan Bencana 4.1. Tujuan dan Sasaran Subbab ini berisi hasil rumusan pernyataan tujuan, sasaran, indikator sasaran dari penyelenggaraan penanggulangan bencana dalam jangka 5 (lima) tahun yang didasarkan atas permasalahan dan/atau isu-isu strategis kebencanaan. Pada subbab ini diuraikan sekurang-kurangnya hal-hal berikut. a) Ringkasan penjelasan tujuan dan sasaran penanggulangan bencana dalam 5 (lima) tahun. b) Pernyataan tujuan penanggulangan bencana dalam bahasa yang jelas, ringkas, dan mudah dipahami. c) Pernyataan sasaran-sasaran penanggulangan bencana dalam bahasa yang jelas, ringkas, dan mudah dipahami. d) Pernyataan indikator sasaran dan target dalam jangka waktu 5 (lima) tahun pada setiap sasaran yang disajikan dalam bentuk tabel/matriks. e) Pernyataan tujuan dan sasaran dapat disajikan dalam tabel sebagai berikut:
Tabel 2-1 Tujuan dan Sasaran Penanggulangan Bencana Provinsi/Kabupaten/Kota.....*) Tahun ..... **) KONDISI TARGET INDIKATOR SATU AWAL/ TAHUN TAHUN TAHUN TAHUN TAHUN TUJUAN SASARAN SASARAN AN 1***) 2***) 3***) 4***) 5***) BASELIN E
(1) (2) (3) (4) (5) (6) Tujuan-1 Sasaran Indikator 1.1 Sasaran 1.1 Sasaran Indikator 1.2 Sasaran 1.2 Sasaran Indikator 1.3 Sasaran 1.3 Keterangan: *) diisi dengan nama provinsi/kabupaten/kota **) diisi dengan periode tahun perencanaan ***) disesuaikan dengan periode RPBD
(1) diisi dengan pernyataan tujuan penanggulangan bencana.', 'Lampiran hal. 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3255, 'perban-3-2026', 64, 'lampiran', 'Lampiran hal. 24', NULL, 24, '(2) diisi dengan pernyataan sasaran penanggulangan bencana untuk mencapai tujuan yang dirumuskan.
(3) diisi dengan hasil rumusan indikator sasaran (dampak) pada setiap sasaran.
(4) diisi dengan satuan indikator sasaran.
(5) diisi dengan data kondisi awal capaian indikator pada tahun sebelumnya (tahun n-1) hingga periode 3 (tiga) tahun ke belakang (tahun n-2) atau hasil proyeksi tahun awal perencanaan (tahun-1). Keterangan tahun data atau hasil proyeksi perlu dicantumkan di setiap isian.
(6) diisi dengan target indikator sasaran setiap tahun.
4.2. Strategi Subbab ini berisi rumusan pernyataan strategi penanggulangan bencana dalam jangka waktu 5 (lima) tahun, yang disajikan dalam tabel berikut:
Tabel 2-2 Strategi Penanggulangan Bencana Provinsi/Kabupaten/Kota.....*) Tahun ..... **) TUJUAN SASARAN INDIKATOR SASARAN STRATEGI
(1) (2) (3) (4) Tujuan-1 Sasaran 1.1 Indikator Sasaran 1.1 Strategi 1.1.1 Strategi 1.1.2 dst..
Sasaran 1.2 Indikator Sasaran 1.2 Strategi 1.2.1 Strategi 1.2.2 dst..
Sasaran 1.3 Indikator Sasaran 1.3 Strategi 1.3.1 Strategi 1.3.2 dst..
Keterangan: *) diisi dengan nama Provinsi/Kabupaten/Kota **) diisi dengan periode tahun perencanaan
(1) diisi dengan pernyataan tujuan penanggulangan bencana.
(2) diisi dengan pernyataan sasaran penanggulangan bencana untuk mencapai tujuan yang dirumuskan.
(3) diisi dengan hasil rumusan indikator sasaran (dampak) pada setiap sasaran.
(4) diisi dengan pernyataan strategi pada setiap sasaran.');
