INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3256, 'perban-3-2026', 65, 'lampiran', 'Lampiran hal. 25', NULL, 25, 'Pernyataan strategi harus relevan dan konsisten dengan pernyataan tujuan dan sasaran serta merespons isu strategis dan permasalahan kebencanaan yang telah dirumuskan. Apabila terdapat pernyataan strategi yang tidak relevan dan tidak konsisten dengan pernyataan lainnya, maka diperlukan perbaikan dalam proses perumusan strategi.
Bab V Program dan Kegiatan Penanggulangan Bencana Bab ini menyajikan program dan kegiatan sebagai komitmen daerah dalam mengelola risiko bencana dalam 5 tahun ke depan. Program dan kegiatan yang direncanakan disertai dengan rumusan indikator keluaran (output), nomenklatur subkegiatan berdasarkan nomenklatur perencanaan pembangunan dan keuangan daerah, target tiap tahun, lokasi, pagu indikatif total, sumber pendanaan, Perangkat Daerah pelaksana, dan instansi pendukung. Pada setiap kegiatan yang direncanakan ditambahkan hasil pemetaan kontribusi atau dukungan terhadap:
(1) fokus capaian RIPB; (2) sasaran dan arah kebijakan per wilayah dalam RENAS PB; dan (3) sasaran, program, dan/atau kegiatan spesifik untuk potensi ancaman bencana prioritas dalam RPBD provinsi untuk penyusunan RPBD kabupaten/kota. Rencana program dan kegiatan disajikan dalam bentuk matriks seperti Tabel 2-3.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3256, 'Pernyataan strategi harus relevan dan konsisten dengan pernyataan tujuan dan sasaran serta merespons isu strategis dan permasalahan kebencanaan yang telah dirumuskan. Apabila terdapat pernyataan strategi yang tidak relevan dan tidak konsisten dengan pernyataan lainnya, maka diperlukan perbaikan dalam proses perumusan strategi.
Bab V Program dan Kegiatan Penanggulangan Bencana Bab ini menyajikan program dan kegiatan sebagai komitmen daerah dalam mengelola risiko bencana dalam 5 tahun ke depan. Program dan kegiatan yang direncanakan disertai dengan rumusan indikator keluaran (output), nomenklatur subkegiatan berdasarkan nomenklatur perencanaan pembangunan dan keuangan daerah, target tiap tahun, lokasi, pagu indikatif total, sumber pendanaan, Perangkat Daerah pelaksana, dan instansi pendukung. Pada setiap kegiatan yang direncanakan ditambahkan hasil pemetaan kontribusi atau dukungan terhadap:
(1) fokus capaian RIPB; (2) sasaran dan arah kebijakan per wilayah dalam RENAS PB; dan (3) sasaran, program, dan/atau kegiatan spesifik untuk potensi ancaman bencana prioritas dalam RPBD provinsi untuk penyusunan RPBD kabupaten/kota. Rencana program dan kegiatan disajikan dalam bentuk matriks seperti Tabel 2-3.', 'Lampiran hal. 25', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3257, 'perban-3-2026', 66, 'lampiran', 'Lampiran hal. 25', NULL, 25, 'Pada bab ini juga ditambahkan uraian ringkas kegiatan spesifik pada setiap potensi ancaman bencana prioritas, baik berupa kegiatan fisik dan non fisik. Pada setiap kegiatan spesifik diberikan deskripsi singkat pelaksanaan kegiatan disertai dengan gambaran lokasi kegiatan dan penerima manfaat dalam bentuk peta yang menjadi lampiran yang tidak terpisahkan dari dokumen RPBD.
