INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3258, 'perban-3-2026', 67, 'lampiran', 'Lampiran hal. 26', NULL, 26, '- pernyataan sasaran dan strategi penanggulangan bencana sesuai yang dirumuskan di BAB IV
- nama program untuk mengimplementasikan strategi dan pernyataan hasil (outcome) dari program
(2) diisi dengan nama kegiatan untuk setiap program
(3) diisi dengan rumusan indikator keluaran langsung (output) kegiatan untuk ukuran keberhasilan pelaksaan kegiatan
(4) diisi dengan satuan indikator keluaran langsung (output) kegiatan.
(5) diisi dengan hasil pemetaan kegiatan yang ditetapkan terhadap nomenklatur subkegiatan pada ketentuan dan/atau peraturan perundang-undangan yang berlaku.
(6) Kolom NILAI diisi dengan target indikator kegiatan (output) per tahun pelaksanaan kegiatan.
Kolom PAGU INDIKATIF diisi dengan proyeksi kebutuhan pendanaan pelaksanaan kegiatan per tahun.
(7) diisi dengan tempat atau lokasi pelaksanaan kegiatan.
(8) diisi dengan perkiraan sumber pendanaan pelaksanaan kegiatan sesuai ketentuan berlaku
(9) diisi dengan Perangkat Daerah penanggung jawab utama pelaksanaan kegiatan.
(10) diisi dengan instansi pendukung pelaksanaan kegiatan, baik K/L, TNI/POLRI pendukung maupun pihak non pemerintah yang dapat terlibat dalam pelaksanaan kegiatan.
(11) diisi dengan hasil pemetaan peta kontribusi terhadap RIPB, RENAS PB, dan RPBD provinsi, melalui penulisan:
- RIPB;
- RENAS PB; dan/atau
- RPBD provinsi (untuk penyusunan RPBD kabupaten/kota).');
