INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3259, 'perban-3-2026', 68, 'lampiran', 'Lampiran hal. 28', NULL, 28, 'Bab VI Pelaksanaan, Pemantauan dan Evaluasi 6.1. Mekanisme Pelaksanaan Subbab ini berisi ringkasan penjelasan tentang kerangka kelembagaan dan pelibatan pihak non pemerintah dalam pelaksanaan program dan kegiatan dalam RPBD. a) Kerangka Kelembagaan Bagian ini berisi skema pembagian peran dan tanggung jawab Pemerintah Daerah dalam pelaksanaan kegiatan maupun pencapaian sasaran penanggulangan bencana yang ditargetkan dalam RPBD. Peran dan tanggung jawab tersebut dipetakan untuk BPBD atau Perangkat Daerah yang menyelenggarakan sub-urusan bencana dan Perangkat Daerah lainnya yang menjadi pelaksana utama dan kontributor/pendukung pelaksanaan kegiatan.
Pada bagian ini diuraikan pula pelibatan instansi vertikal yang terkait dengan penanggulangan bencana serta TNI dan Polri dalam pelaksanaan kegiatan atau pencapaian sasaran penanggulangan bencana yang dirumuskan dalam RPBD. b) Pelibatan Pihak Non-Pemerintah Bagian ini berisi uraian skema pelibatan pihak non-pemerintah, yaitu unsur dunia usaha, organisasi internasional, organisasi masyarakat sipil, komunitas, perguruan tinggi, dan media, yang belum terpetakan sebagai instansi pendukung pelaksanaan kegiatan di BAB V. Pada bagian ini juga dapat digambarkan bentuk pelibatan atau kemitraan pemerintah dan pihak non-pemerintah yang dapat dilakukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3259, 'Bab VI Pelaksanaan, Pemantauan dan Evaluasi 6.1. Mekanisme Pelaksanaan Subbab ini berisi ringkasan penjelasan tentang kerangka kelembagaan dan pelibatan pihak non pemerintah dalam pelaksanaan program dan kegiatan dalam RPBD. a) Kerangka Kelembagaan Bagian ini berisi skema pembagian peran dan tanggung jawab Pemerintah Daerah dalam pelaksanaan kegiatan maupun pencapaian sasaran penanggulangan bencana yang ditargetkan dalam RPBD. Peran dan tanggung jawab tersebut dipetakan untuk BPBD atau Perangkat Daerah yang menyelenggarakan sub-urusan bencana dan Perangkat Daerah lainnya yang menjadi pelaksana utama dan kontributor/pendukung pelaksanaan kegiatan.
Pada bagian ini diuraikan pula pelibatan instansi vertikal yang terkait dengan penanggulangan bencana serta TNI dan Polri dalam pelaksanaan kegiatan atau pencapaian sasaran penanggulangan bencana yang dirumuskan dalam RPBD. b) Pelibatan Pihak Non-Pemerintah Bagian ini berisi uraian skema pelibatan pihak non-pemerintah, yaitu unsur dunia usaha, organisasi internasional, organisasi masyarakat sipil, komunitas, perguruan tinggi, dan media, yang belum terpetakan sebagai instansi pendukung pelaksanaan kegiatan di BAB V. Pada bagian ini juga dapat digambarkan bentuk pelibatan atau kemitraan pemerintah dan pihak non-pemerintah yang dapat dilakukan.', 'Lampiran hal. 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3260, 'perban-3-2026', 69, 'lampiran', 'Lampiran hal. 28', NULL, 28, '6.2. Kerangka Pemantauan dan Evaluasi Subbab ini berisi uraian tentang komitmen dalam pelaksanaan pemantauan dan evaluasi terhadap implementasi program dan kegiatan dan pencapaian tujuan dan sasaran RPBD. Kerangka pemantauan dan evaluasi berisi gambaran waktu/frekuensi, objek, dan pelaksana serta bentuk pelaporan hasil pemantauan dan evaluasi yang dapat dituangkan dalam bentuk tabel sesuai Kertas Kerja Kerangka Pemantauan dan Evaluasi.
Bab VII Penutup Bab ini menyajikan narasi penutup dokumen RPBD. Selain sebagai pernyataan penutup, dalam bab ini dapat ditegaskan kembali tentang penggunaan RPBD dan/atau perlunya meninjau kembali dokumen RPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3260, '6.2. Kerangka Pemantauan dan Evaluasi Subbab ini berisi uraian tentang komitmen dalam pelaksanaan pemantauan dan evaluasi terhadap implementasi program dan kegiatan dan pencapaian tujuan dan sasaran RPBD. Kerangka pemantauan dan evaluasi berisi gambaran waktu/frekuensi, objek, dan pelaksana serta bentuk pelaporan hasil pemantauan dan evaluasi yang dapat dituangkan dalam bentuk tabel sesuai Kertas Kerja Kerangka Pemantauan dan Evaluasi.
Bab VII Penutup Bab ini menyajikan narasi penutup dokumen RPBD. Selain sebagai pernyataan penutup, dalam bab ini dapat ditegaskan kembali tentang penggunaan RPBD dan/atau perlunya meninjau kembali dokumen RPBD.', 'Lampiran hal. 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3261, 'perban-3-2026', 70, 'lampiran', 'Lampiran hal. 28', NULL, 28, 'Lampiran Berisi lampiran-lampiran berupa materi pendukung teknis dari dokumen RPBD, yang meliputi: a) Lampiran Kegiatan Spesifik Potensi Ancaman Bencana Prioritas (format lampiran dapat dilihat pada Tabel 2-4) b) Lampiran Gambar Lokasi Kegiatan Spesifik Potensi Ancaman Bencana Prioritas (format lampiran dapat dilihat pada Gambar 1-1) c) Lampiran Hasil Pemetaan Kontribusi Kegiatan terhadap RIPB, RENAS PB, dan RPBD Provinsi (format lampiran dapat dilihat pada Tabel 2-5) Tabel 2-4 Format Lampiran Kegiatan Spesifik Potensi Ancaman Bencana Prioritas RPBD Provinsi/Kabupaten/Kota TARGET TAHUN 1*) TAHUN 2*) TAHUN 3*) TAHUN 4*) TAHUN 5*) NOMENKLAT LOKASI/ SUMBER PERANGKA INDIKATOR SATUAN UR SUB NILAI PAGU NILAI PAGU NILAI PAGU NILAI PAGU NILAI PAGU PENERIMA PENDAN T DAERAH KEGIATAN KEGIATAN KEGIATAN INDIKATIF INDIKATIF INDIKATIF INDIKATIF INDIKATIF MANFAAT AAN PELAKSANA (Rp) (Rp) (Rp) (Rp) (Rp)
(1) (2) (3) (4) (5) (6) (7) (8) Jenis Potensi Ancaman Bencana Prioritas 1: ....
Jenis Potensi Ancaman Bencana Prioritas 2 : .... dst...
Keterangan: *) disesuaikan dengan periode RPBD
(1) diisi dengan nama kegiatan dari Tabel Program dan Kegiatan Penanggulangan Bencana di BAB V
(2) diisi dengan rumusan indikator keluaran langsung (output) kegiatan untuk ukuran keberhasilan pelaksaan kegiatan
(3) diisi dengan satuan indikator keluaran langsung (output) kegiatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3261, 'Lampiran Berisi lampiran-lampiran berupa materi pendukung teknis dari dokumen RPBD, yang meliputi: a) Lampiran Kegiatan Spesifik Potensi Ancaman Bencana Prioritas (format lampiran dapat dilihat pada Tabel 2-4) b) Lampiran Gambar Lokasi Kegiatan Spesifik Potensi Ancaman Bencana Prioritas (format lampiran dapat dilihat pada Gambar 1-1) c) Lampiran Hasil Pemetaan Kontribusi Kegiatan terhadap RIPB, RENAS PB, dan RPBD Provinsi (format lampiran dapat dilihat pada Tabel 2-5) Tabel 2-4 Format Lampiran Kegiatan Spesifik Potensi Ancaman Bencana Prioritas RPBD Provinsi/Kabupaten/Kota TARGET TAHUN 1*) TAHUN 2*) TAHUN 3*) TAHUN 4*) TAHUN 5*) NOMENKLAT LOKASI/ SUMBER PERANGKA INDIKATOR SATUAN UR SUB NILAI PAGU NILAI PAGU NILAI PAGU NILAI PAGU NILAI PAGU PENERIMA PENDAN T DAERAH KEGIATAN KEGIATAN KEGIATAN INDIKATIF INDIKATIF INDIKATIF INDIKATIF INDIKATIF MANFAAT AAN PELAKSANA (Rp) (Rp) (Rp) (Rp) (Rp)
(1) (2) (3) (4) (5) (6) (7) (8) Jenis Potensi Ancaman Bencana Prioritas 1: ....
Jenis Potensi Ancaman Bencana Prioritas 2 : .... dst...
Keterangan: *) disesuaikan dengan periode RPBD
(1) diisi dengan nama kegiatan dari Tabel Program dan Kegiatan Penanggulangan Bencana di BAB V
(2) diisi dengan rumusan indikator keluaran langsung (output) kegiatan untuk ukuran keberhasilan pelaksaan kegiatan
(3) diisi dengan satuan indikator keluaran langsung (output) kegiatan.', 'Lampiran hal. 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3262, 'perban-3-2026', 71, 'lampiran', 'Lampiran hal. 29', NULL, 29, '(4) diisi dengan hasil pemetaan kegiatan yang ditetapkan terhadap nomenklatur sub-kegiatan pada ketentuan dan/atau peraturan perundang-undangan yang berlaku.
(5) Kolom NILAI diisi dengan target indikator kegiatan (output) per tahun pelaksanaan kegiatan.
