INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3263, 'perban-3-2026', 72, 'lampiran', 'Lampiran hal. 31', NULL, 31, 'Wilayah:...... dst Kegiatan Indikator Fokus - Sasaran:.... - Sasaran:...
