INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3264, 'perban-3-2026', 73, 'lampiran', 'Lampiran hal. 32', NULL, 32, 'KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd.
SUHARYANTO LAMPIRAN II PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 3 TAHUN 2026 TENTANG PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH FORMAT KERTAS KERJA DAN DOKUMENTASI HASIL PENYUSUNAN RANCANGAN AWAL RENCANA PENANGGULANGAN BENCANA DAERAH Format 1 - Kertas Kerja Penelaahan atas Kebijakan Penanggulangan Bencana
1. Kertas Kerja Penelaahan atas Kebijakan Penanggulangan Bencana terhadap RIPB dan RENAS PB KERTAS KERJA PENELAAHAN ATAS KEBIJAKAN PENANGGULANGAN BENCANA TERHADAP RIPB DAN RENAS PB UNSUR ARAHAN KEBIJAKAN/TARGET PELUANG/ PENANGGULANGAN BENCANA TANTANGAN YANG PERLU DIRESPONS ATAU HASIL TELAAH
(1) (2) (3) RIPB Fokus Capaian RIPB Periode Terkait RENAS PB Tahun ..... *) Arah Kebijakan Penanggulangan Bencana Program Penanggulangan Bencana Indikator Capaian dan Target Keterangan:
Sifat Kertas Kerja: Alat bantu analisis, tidak dimuat dalam dokumen RPBD. *) Periode RENAS PB yang berlaku.
(1) Unsur dalam dokumen RIPB dan RENAS PB yang berlaku.
(2) Diisi dengan hasil penelaahan substansi dari dokumen RIPB dan RENAS PB yang berlaku:
- Baris Fokus Capaian RIPB Periode Terkait diisi dengan pernyataan fokus capaian RIPB pada periode yang sesuai dengan periode RPBD yang disusun.
- Baris Arah Kebijakan Penanggulangan Bencana diisi dengan tujuan, sasaran, dan ringkasan arah kebijakan penanggulangan bencana di wilayah pulau yang sesuai dengan lokasi provinsi/kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3264, 'KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd.
SUHARYANTO LAMPIRAN II PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 3 TAHUN 2026 TENTANG PENYUSUNAN RENCANA PENANGGULANGAN BENCANA DAERAH FORMAT KERTAS KERJA DAN DOKUMENTASI HASIL PENYUSUNAN RANCANGAN AWAL RENCANA PENANGGULANGAN BENCANA DAERAH Format 1 - Kertas Kerja Penelaahan atas Kebijakan Penanggulangan Bencana
1. Kertas Kerja Penelaahan atas Kebijakan Penanggulangan Bencana terhadap RIPB dan RENAS PB KERTAS KERJA PENELAAHAN ATAS KEBIJAKAN PENANGGULANGAN BENCANA TERHADAP RIPB DAN RENAS PB UNSUR ARAHAN KEBIJAKAN/TARGET PELUANG/ PENANGGULANGAN BENCANA TANTANGAN YANG PERLU DIRESPONS ATAU HASIL TELAAH
(1) (2) (3) RIPB Fokus Capaian RIPB Periode Terkait RENAS PB Tahun ..... *) Arah Kebijakan Penanggulangan Bencana Program Penanggulangan Bencana Indikator Capaian dan Target Keterangan:
Sifat Kertas Kerja: Alat bantu analisis, tidak dimuat dalam dokumen RPBD. *) Periode RENAS PB yang berlaku.
(1) Unsur dalam dokumen RIPB dan RENAS PB yang berlaku.
(2) Diisi dengan hasil penelaahan substansi dari dokumen RIPB dan RENAS PB yang berlaku:
- Baris Fokus Capaian RIPB Periode Terkait diisi dengan pernyataan fokus capaian RIPB pada periode yang sesuai dengan periode RPBD yang disusun.
- Baris Arah Kebijakan Penanggulangan Bencana diisi dengan tujuan, sasaran, dan ringkasan arah kebijakan penanggulangan bencana di wilayah pulau yang sesuai dengan lokasi provinsi/kabupaten/kota.', 'Lampiran hal. 32', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3265, 'perban-3-2026', 74, 'lampiran', 'Lampiran hal. 33', NULL, 33, '- Baris Program Penanggulangan Bencana diisi dengan program penanggulangan bencana dengan pelaksanaan kegiatan yang dapat dikontribusikan oleh pemerintah provinsi/kabupaten/kota.
- Baris Indikator Capaian dan Target diisi dengan indikator capaian penanggulangan bencana serta target di tahun akhir RENAS PB.
(3) Diisi dengan uraian singkat peluang atau tantangan yang perlu direspons dalam 5 (lima) tahun mendatang dari hasil penelaahan di kolom (2).
2. Kertas Kerja Penelaahan atas Kebijakan Penanggulangan Bencana terhadap RPJPD PENELAAHAN ARAHAN KEBIJAKAN PENANGGULANGAN BENCANA DALAM RPJPD PROVINSI/KABUPATEN/KOTA.....*) TAHUN ..... **) UNSUR ARAHAN KEBIJAKAN/TARGET PELUANG/ PEMBANGUNAN TERKAIT TANTANGAN YANG PENANGGULANGAN BENCANA PERLU DIRESPONS ATAU HASIL TELAAH
(1) (2) (3) Misi Arah Kebijakan Periode Terkait Sasaran Pokok Keterangan:
Sifat Kertas Kerja: Alat bantu analisis, tidak dimuat dalam dokumen RPBD. *) diisi dengan ama provinsi/kabupaten/kota. **) diisi dengan periode RPJPD provinsi/kabupaten/kota yang berlaku.
(1) Unsur dalam dokumen RPJPD provinsi/kabupaten/kota yang berlaku.
(2) Diisi dengan hasil penelaahan substansi dari dokumen RPJPD:
- Baris Misi diisi dengan pernyataan misi yang berkaitan dengan penanggulangan bencana.
- Baris Arah Kebijakan Periode Terkait diisi dengan ringkasan arahan kebijakan terkait penanggulangan bencana pada periode pentahapan RPJMD yang sesuai dengan periode RPBD yang disusun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3265, '- Baris Program Penanggulangan Bencana diisi dengan program penanggulangan bencana dengan pelaksanaan kegiatan yang dapat dikontribusikan oleh pemerintah provinsi/kabupaten/kota.
- Baris Indikator Capaian dan Target diisi dengan indikator capaian penanggulangan bencana serta target di tahun akhir RENAS PB.
(3) Diisi dengan uraian singkat peluang atau tantangan yang perlu direspons dalam 5 (lima) tahun mendatang dari hasil penelaahan di kolom (2).
2. Kertas Kerja Penelaahan atas Kebijakan Penanggulangan Bencana terhadap RPJPD PENELAAHAN ARAHAN KEBIJAKAN PENANGGULANGAN BENCANA DALAM RPJPD PROVINSI/KABUPATEN/KOTA.....*) TAHUN ..... **) UNSUR ARAHAN KEBIJAKAN/TARGET PELUANG/ PEMBANGUNAN TERKAIT TANTANGAN YANG PENANGGULANGAN BENCANA PERLU DIRESPONS ATAU HASIL TELAAH
(1) (2) (3) Misi Arah Kebijakan Periode Terkait Sasaran Pokok Keterangan:
Sifat Kertas Kerja: Alat bantu analisis, tidak dimuat dalam dokumen RPBD. *) diisi dengan ama provinsi/kabupaten/kota. **) diisi dengan periode RPJPD provinsi/kabupaten/kota yang berlaku.
(1) Unsur dalam dokumen RPJPD provinsi/kabupaten/kota yang berlaku.
(2) Diisi dengan hasil penelaahan substansi dari dokumen RPJPD:
- Baris Misi diisi dengan pernyataan misi yang berkaitan dengan penanggulangan bencana.
- Baris Arah Kebijakan Periode Terkait diisi dengan ringkasan arahan kebijakan terkait penanggulangan bencana pada periode pentahapan RPJMD yang sesuai dengan periode RPBD yang disusun.', 'Lampiran hal. 33', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2026 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3266, 'perban-3-2026', 75, 'lampiran', 'Lampiran hal. 34', NULL, 34, '- Baris Sasaran Pokok diisi dengan sasaran pokok terkait penanggulangan bencana serta target di tahun akhir RPJPD.
(3) Diisi dengan uraian singkat kebutuhan penyelerasan dengan rencana penanggulangan bencana, tindak lanjut, dan/atau peluang/tantangan yang perlu direspons dalam jangka waktu menengah dari hasil penelaahan di kolom (2).
3. Kertas Kerja Penelaahan atas Kebijakan Penanggulangan Bencana terhadap RPBD PENELAAHAN ARAHAN KEBIJAKAN PENANGGULANGAN BENCANA DALAM RPBD PROVINSI.....*) TAHUN ..... **) UNSUR ARAHAN KEBIJAKAN/TARGET PELUANG/ PENANGGULANGAN BENCANA TANTANGAN YANG PERLU DIRESPONS ATAU HASIL TELAAH
(1) (2) (3) Strategi Kegiatan Spesifik untuk Potensi Ancaman Bencana Prioritas Indikator Capaian dan Target Keterangan:
Sifat Kertas Kerja: Alat bantu analisis, tidak dimuat dalam dokumen RPBD. *) diisi dengan nama provinsi lokasi kabupaten/kota. **) diisi dengan periode RENAS PB yang berlaku.
(1) Unsur dalam dokumen RPBD provinsi yang berlaku.
(2) Diisi dengan hasil penelaahan substansi dari dokumen RPBD provinsi yang berlaku:
- Baris Strategi diisi dengan pernyataan strategi penanggulangan bencana
