INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3286, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG SISTEM MANAJEMEN LOGISTIK DAN PERALATAN.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3287, 'perban-4-2018', 4, 'pasal', 'Pasal 1', 'BAB II PRINSIP SISTEM LOGISTIK DAN PERALATAN', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
2. Logistik adalah barang untuk pemenuhan kebutuhan dasar seperti pangan, sandang, papan, dan turunannya dalam rangka penanggulangan bencana.
3. Peralatan adalah segala bentuk alat yang dapat dipergunakan untuk melakukan, pencarian, penyelamatan, dan evakuasi masyarakat terdampak bencana, membantu pemenuhan kebutuhan dasar untuk pemulihan segera sarana prasarana vital.
4. Sistem Manajemen Logistik dan Peralatan Penanggulangan Bencana adalah pengelolaan logistik dan peralatan meliputi perencanaan, pengadaan, pergudangan, pendistribusian, dan penghapusan guna mencapai tujuan dan sasaran secara efektif dan efisien.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3287, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
2. Logistik adalah barang untuk pemenuhan kebutuhan dasar seperti pangan, sandang, papan, dan turunannya dalam rangka penanggulangan bencana.
3. Peralatan adalah segala bentuk alat yang dapat dipergunakan untuk melakukan, pencarian, penyelamatan, dan evakuasi masyarakat terdampak bencana, membantu pemenuhan kebutuhan dasar untuk pemulihan segera sarana prasarana vital.
4. Sistem Manajemen Logistik dan Peralatan Penanggulangan Bencana adalah pengelolaan logistik dan peralatan meliputi perencanaan, pengadaan, pergudangan, pendistribusian, dan penghapusan guna mencapai tujuan dan sasaran secara efektif dan efisien.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3288, 'perban-4-2018', 5, 'pasal', 'Pasal 2', 'BAB II PRINSIP SISTEM LOGISTIK DAN PERALATAN', 2, 'Sistem Logistik dan Peralatan Penanggulangan Bencana dilaksanakan dengan prinsip:
a. tepat jenis;
b. tepat jumlah;
2018, No. 828
c. tepat kualitas;
d. tepat waktu;
e. tepat sasaran;
f. tepat biaya; dan
g. tepat pelaporan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3288, 'Sistem Logistik dan Peralatan Penanggulangan Bencana dilaksanakan dengan prinsip:
a. tepat jenis;
b. tepat jumlah;
2018, No. 828
c. tepat kualitas;
d. tepat waktu;
e. tepat sasaran;
f. tepat biaya; dan
g. tepat pelaporan.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3289, 'perban-4-2018', 6, 'pasal', 'Pasal 3', 'BAB III SISTEM MANAJEMEN LOGISTIK DAN PERALATAN', 3, '(1) Pelaksanaan Sistem Logistik dan Peralatan memerlukan perhatian dengan mempertimbangkan keterbatasan sarana transportasi, sebaran kejadian, lokasi, serta kecepatan respon di lapangan.
(2) Pelaksanaan Sistem Logistik dan Peralatan sebagaimana dimaksud pada ayat (1) mengoptimalkan koordinasi dan peran serta dari kementerian/lembaga, dunia usaha, masyarakat, dan instansi terkait.
(3) Pelaksanaan Sistem Logistik dan Peralatan sebagaimana dimaksud pada ayat (1) memperhatikan dinamika pergerakan masyarakat korban bencana.
(4) Pelaksanaan Sistem Logistik dan Peralatan sebagaimana dimaksud pada ayat (1) memperhatikan faktor budaya, sosial ekonomi, dan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3289, '(1) Pelaksanaan Sistem Logistik dan Peralatan memerlukan perhatian dengan mempertimbangkan keterbatasan sarana transportasi, sebaran kejadian, lokasi, serta kecepatan respon di lapangan.
(2) Pelaksanaan Sistem Logistik dan Peralatan sebagaimana dimaksud pada ayat (1) mengoptimalkan koordinasi dan peran serta dari kementerian/lembaga, dunia usaha, masyarakat, dan instansi terkait.
(3) Pelaksanaan Sistem Logistik dan Peralatan sebagaimana dimaksud pada ayat (1) memperhatikan dinamika pergerakan masyarakat korban bencana.
(4) Pelaksanaan Sistem Logistik dan Peralatan sebagaimana dimaksud pada ayat (1) memperhatikan faktor budaya, sosial ekonomi, dan masyarakat.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3290, 'perban-4-2018', 7, 'pasal', 'Pasal 4', 'BAB III SISTEM MANAJEMEN LOGISTIK DAN PERALATAN; Bagian Kesatu Perencanaan', 3, '(1) Sistem Manajemen Logistik dan Peralatan dalam Penanggulangan Bencana meliputi:
a. perencanaan;
b. pengadaan;
c. pergudangan;
d. pendistribusian; dan
e. penghapusan.
(2) Sistem Manajemen Logistik dan Peralatan sebagaimana dimaksud pada ayat (1) huruf a dilaksanakan secara menyeluruh dan terpadu.
2018, No. 828 -4-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3290, '(1) Sistem Manajemen Logistik dan Peralatan dalam Penanggulangan Bencana meliputi:
a. perencanaan;
b. pengadaan;
c. pergudangan;
d. pendistribusian; dan
e. penghapusan.
(2) Sistem Manajemen Logistik dan Peralatan sebagaimana dimaksud pada ayat (1) huruf a dilaksanakan secara menyeluruh dan terpadu.
2018, No. 828 -4-', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3291, 'perban-4-2018', 8, 'pasal', 'Pasal 5', 'BAB III SISTEM MANAJEMEN LOGISTIK DAN PERALATAN; Bagian Kedua Pengadaan', 4, '(1) Perencanaan merupakan kegiatan melalui identifikasi kebutuhan, inventarisasi ketersediaan, pengumpulan data, dan analisis untuk menghasilkan standar minimal kebutuhan dalam penanggulangan bencana.
(2) Maksud dan tujuan perencanaan untuk:
a. mengetahui jumlah dan jenis bantuan kemanusiaan dan peralatan yang dibutuhkan;
b. mengetahui jumlah korban terkena bencana yang membutuhkan bantuan logistik dan peralatan;
c. menentukan metode pendistribusian;
d. mengetahui sasaran penerima bantuan; dan
e. menentukan waktu penyampaian bantuan.
(3) Perencanaan terdiri atas:
a. penyusunan standar kebutuhan minimal;
b. identifikasi kebutuhan; dan
c. penyusunan kebutuhan jangka pendek, menengah, dan panjang.
(4) Perencanaan sebagaimana dimaksud pada ayat (1) diatur dengan Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3291, '(1) Perencanaan merupakan kegiatan melalui identifikasi kebutuhan, inventarisasi ketersediaan, pengumpulan data, dan analisis untuk menghasilkan standar minimal kebutuhan dalam penanggulangan bencana.
(2) Maksud dan tujuan perencanaan untuk:
a. mengetahui jumlah dan jenis bantuan kemanusiaan dan peralatan yang dibutuhkan;
b. mengetahui jumlah korban terkena bencana yang membutuhkan bantuan logistik dan peralatan;
c. menentukan metode pendistribusian;
d. mengetahui sasaran penerima bantuan; dan
e. menentukan waktu penyampaian bantuan.
(3) Perencanaan terdiri atas:
a. penyusunan standar kebutuhan minimal;
b. identifikasi kebutuhan; dan
c. penyusunan kebutuhan jangka pendek, menengah, dan panjang.
(4) Perencanaan sebagaimana dimaksud pada ayat (1) diatur dengan Petunjuk Pelaksanaan.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3292, 'perban-4-2018', 9, 'pasal', 'Pasal 6', 'BAB III SISTEM MANAJEMEN LOGISTIK DAN PERALATAN; Bagian Ketiga Pergudangan', 4, '(1) Pengadaan merupakan kegiatan pemenuhan atau penyediaan kebutuhan melalui perencanaan kebutuhan sampai dengan perolehan.
(2) Tujuan pengadaan untuk memenuhi kebutuhan logistik dan peralatan.
(3) Pengadaan Logistik dan Peralatan berasal dari Anggaran Pendapatan dan Belanja Negara atau sumber resmi lainnya yang tidak mengikat.
2018, No. 828
(4) Proses pengadaan Logistik dan Peralatan dilaksanakan secara terencana sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3292, '(1) Pengadaan merupakan kegiatan pemenuhan atau penyediaan kebutuhan melalui perencanaan kebutuhan sampai dengan perolehan.
(2) Tujuan pengadaan untuk memenuhi kebutuhan logistik dan peralatan.
(3) Pengadaan Logistik dan Peralatan berasal dari Anggaran Pendapatan dan Belanja Negara atau sumber resmi lainnya yang tidak mengikat.
2018, No. 828
(4) Proses pengadaan Logistik dan Peralatan dilaksanakan secara terencana sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3293, 'perban-4-2018', 10, 'pasal', 'Pasal 7', 'BAB III SISTEM MANAJEMEN LOGISTIK DAN PERALATAN; Bagian keempat Pendistribusian', 5, '(1) Pergudangan merupakan pengelolaan penerimaan, penyimpanan, pemeliharaan, dan pengeluaran logistik dan peralatan di gudang.
(2) Prosedur penetapan gudang terdiri atas lokasi, kemudahan akses, jenis gudang, kapasitas dan fasilitas penyimpanan, sistem pengamanan dan keselamatan, sesuai dengan ketentuan peraturan perundang-undangan.
(3) Tujuan pergudangan untuk:
a. mencatat jenis, jumlah, kualitas, kondisi logistik dan peralatan, waktu, dan identitas petugas;
b. menjaga kondisi logistik dan peralatan dari kerusakan dan kehilangan atau berkurangnya standar mutu;
c. memudahkan pendistribusian Logistik dan Peralatan, dengan menggunakan metode pertama masuk-pertama keluar (first-in first-out), dan pertama kadaluarsa-pertama keluar (first-expired first-out); dan
d. menjamin ketersediaan Logistik dan Peralatan setiap waktu.
(4) Pergudangan sebagaimana dimaksud pada ayat (1) diatur dengan Petunjuk Pelaksanaan.
2018, No. 828 -6-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3293, '(1) Pergudangan merupakan pengelolaan penerimaan, penyimpanan, pemeliharaan, dan pengeluaran logistik dan peralatan di gudang.
(2) Prosedur penetapan gudang terdiri atas lokasi, kemudahan akses, jenis gudang, kapasitas dan fasilitas penyimpanan, sistem pengamanan dan keselamatan, sesuai dengan ketentuan peraturan perundang-undangan.
(3) Tujuan pergudangan untuk:
a. mencatat jenis, jumlah, kualitas, kondisi logistik dan peralatan, waktu, dan identitas petugas;
b. menjaga kondisi logistik dan peralatan dari kerusakan dan kehilangan atau berkurangnya standar mutu;
c. memudahkan pendistribusian Logistik dan Peralatan, dengan menggunakan metode pertama masuk-pertama keluar (first-in first-out), dan pertama kadaluarsa-pertama keluar (first-expired first-out); dan
d. menjamin ketersediaan Logistik dan Peralatan setiap waktu.
(4) Pergudangan sebagaimana dimaksud pada ayat (1) diatur dengan Petunjuk Pelaksanaan.
2018, No. 828 -6-', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3294, 'perban-4-2018', 11, 'pasal', 'Pasal 8', 'BAB III SISTEM MANAJEMEN LOGISTIK DAN PERALATAN; Bagian Kelima Penghapusan', 6, '(1) Pendistribusian merupakan sistem penyaluran dan penyerahan Logistik dan Peralatan dari daerah asal ke daerah tujuan sampai pada sasaran yang dituju.
(2) Pendistribusian Logistik dan Peralatan dengan menggunakan moda transportasi.
(3) Jenis moda transportasi terdiri atas angkutan darat, laut, sungai, danau dan udara, baik secara komersial maupun nonkomersial sesuai dengan kebutuhan efektivitas distribusi.
(4) Pemilihan moda angkutan berdasarkan pertimbangan:
a. situasi dan kondisi keadaan darurat;
b. kecepatan distribusi;
c. ketersediaan alat angkutan dan infrastruktur yang ada;
d. kondisi wilayah asal dan tujuan;
e. efektivitas dan efisiensi; dan
f. keamanan dan keselamatan.
(5) Tujuan pendistribusian untuk:
a. menyerahkan bantuan Logistik dan Peralatan ke penerima;
b. menjamin keamanan, keselamatan, dan keutuhan bantuan Logistik dan Peralatan selama proses transportasi dari gudang ke tujuan penerima; dan
c. mempercepat penyampaian bantuan Logistik dan Peralatan dengan biaya yang paling efisien.
(6) Pendistribusian sebagaimana dimaksud pada ayat (1) diatur dengan Petunjuk Pelaksanaan.
2018, No. 828');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3294, '(1) Pendistribusian merupakan sistem penyaluran dan penyerahan Logistik dan Peralatan dari daerah asal ke daerah tujuan sampai pada sasaran yang dituju.
(2) Pendistribusian Logistik dan Peralatan dengan menggunakan moda transportasi.
(3) Jenis moda transportasi terdiri atas angkutan darat, laut, sungai, danau dan udara, baik secara komersial maupun nonkomersial sesuai dengan kebutuhan efektivitas distribusi.
(4) Pemilihan moda angkutan berdasarkan pertimbangan:
a. situasi dan kondisi keadaan darurat;
b. kecepatan distribusi;
c. ketersediaan alat angkutan dan infrastruktur yang ada;
d. kondisi wilayah asal dan tujuan;
e. efektivitas dan efisiensi; dan
f. keamanan dan keselamatan.
(5) Tujuan pendistribusian untuk:
a. menyerahkan bantuan Logistik dan Peralatan ke penerima;
b. menjamin keamanan, keselamatan, dan keutuhan bantuan Logistik dan Peralatan selama proses transportasi dari gudang ke tujuan penerima; dan
c. mempercepat penyampaian bantuan Logistik dan Peralatan dengan biaya yang paling efisien.
(6) Pendistribusian sebagaimana dimaksud pada ayat (1) diatur dengan Petunjuk Pelaksanaan.
2018, No. 828', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3295, 'perban-4-2018', 12, 'pasal', 'Pasal 9', 'BAB IV POLA PENYELENGGARAAN; Bagian Kesatu Umum', 7, '(1) Penghapusan barang milik negara dari daftar barang dengan menerbitkan keputusan dari pejabat yang berwenang untuk membebaskan pengelola barang, pengguna barang dan/atau kuasa pengguna barang dari tanggung jawab administrasi dan fisik atas barang yang berada dalam penguasaannya.
(2) Penghapusan dapat dilakukan dengan cara;
a. penyerahan kepada pengguna barang;
b. pemindahtanganan;
c. adanya putusan pengadilan yang telah memperoleh kekuatan hukum tetap dan sudah tidak ada upaya hukum;
d. karena melaksanakan ketentuan peraturan perundangan; dan
e. pemusnahan.
(3) Penghapusan sebagaimana dimaksud pada ayat (1) berdasarkan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3295, '(1) Penghapusan barang milik negara dari daftar barang dengan menerbitkan keputusan dari pejabat yang berwenang untuk membebaskan pengelola barang, pengguna barang dan/atau kuasa pengguna barang dari tanggung jawab administrasi dan fisik atas barang yang berada dalam penguasaannya.
(2) Penghapusan dapat dilakukan dengan cara;
a. penyerahan kepada pengguna barang;
b. pemindahtanganan;
c. adanya putusan pengadilan yang telah memperoleh kekuatan hukum tetap dan sudah tidak ada upaya hukum;
d. karena melaksanakan ketentuan peraturan perundangan; dan
e. pemusnahan.
(3) Penghapusan sebagaimana dimaksud pada ayat (1) berdasarkan ketentuan peraturan perundang-undangan.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3296, 'perban-4-2018', 13, 'pasal', 'Pasal 10', 'BAB IV POLA PENYELENGGARAAN; Bagian Kedua Penyelenggaraan Tingkat Nasional', 7, '(1) Pola penyelenggaraan Logistik dan Peralatan berdasarkan kegiatan pemetaan kapasitas sumber daya.
(2) Pola penyelenggaraan Logistik dan Peralatan sebagaimana dimaksud pada ayat (1) mulai dari:
a. tingkat nasional meliputi kementerian/lembaga, dunia usaha, dan masyarakat;
2018, No. 828 -8-
b. tingkat daerah provinsi meliputi organisasi perangkat daerah, dunia usaha, dan masyarakat; dan
c. tingkat daerah kabupaten/kota meliputi organisasi perangkat daerah, dunia usaha, dan masyarakat.
(3) Pola penyelenggaraan sebagaimana dimaksud pada ayat
(2) melalui pola kerja sama di bidang:
a. sistem manajemen yang mengikuti fungsinya;
b. sistem komando;
c. sistem koordinasi;
d. sistem pelaksana;
e. sistem perencanaan;
f. sistem administrasi dan keuangan;
g. sistem komunikasi; dan
h. sistem transportasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3296, '(1) Pola penyelenggaraan Logistik dan Peralatan berdasarkan kegiatan pemetaan kapasitas sumber daya.
(2) Pola penyelenggaraan Logistik dan Peralatan sebagaimana dimaksud pada ayat (1) mulai dari:
a. tingkat nasional meliputi kementerian/lembaga, dunia usaha, dan masyarakat;
2018, No. 828 -8-
b. tingkat daerah provinsi meliputi organisasi perangkat daerah, dunia usaha, dan masyarakat; dan
c. tingkat daerah kabupaten/kota meliputi organisasi perangkat daerah, dunia usaha, dan masyarakat.
(3) Pola penyelenggaraan sebagaimana dimaksud pada ayat
(2) melalui pola kerja sama di bidang:
a. sistem manajemen yang mengikuti fungsinya;
b. sistem komando;
c. sistem koordinasi;
d. sistem pelaksana;
e. sistem perencanaan;
f. sistem administrasi dan keuangan;
g. sistem komunikasi; dan
h. sistem transportasi.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3297, 'perban-4-2018', 14, 'pasal', 'Pasal 11', 'BAB IV POLA PENYELENGGARAAN; Bagian Ketiga Penyelenggaraan Tingkat Provinsi', 8, '(1) Penyelenggaraan Sistem Manajemen Logistik dan Peralatan dilaksanakan oleh Badan Nasional Penanggulangan Bencana.
(2) Badan Nasional Penanggulangan Bencana berkoordinasi dengan kementerian/lembaga yang membantu Sistem Manajemen Logistik dan Peralatan.
(3) Fungsi penyelenggaraan Sistem Manajemen Logistik dan Peralatan tingkat nasional agar:
a. mematuhi dan melaksanakan Sistem Manajemen Logistik dan Peralatan yang telah ditetapkan, baik prabencana, tanggap darurat, dan pascabencana;
b. melakukan koordinasi antara Pemerintah, pemerintah daerah provinsi, pemerintah daerah kabupaten/kota dan/atau lembaga lain;
c. menghimpun data dan informasi yang diperlukan oleh masyarakat dari berbagai sumber yang tidak mengikat yang dapat dipertangungjawabkan;
2018, No. 828
d. menjalankan pedoman Sistem Manajemen Logistik dan Peralatan secara konsisten;
e. membuat perencanaan dan kesepakatan yang relevan;
f. mempertanggungjawabkan tugas dan koordinasi seluruh sumber daya;
g. mengoordinasikan informasi dan komunikasi organisasi pendukung; dan
h. memegang sistem komando bencana dalam hal logistik dan peralatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3297, '(1) Penyelenggaraan Sistem Manajemen Logistik dan Peralatan dilaksanakan oleh Badan Nasional Penanggulangan Bencana.
(2) Badan Nasional Penanggulangan Bencana berkoordinasi dengan kementerian/lembaga yang membantu Sistem Manajemen Logistik dan Peralatan.
(3) Fungsi penyelenggaraan Sistem Manajemen Logistik dan Peralatan tingkat nasional agar:
a. mematuhi dan melaksanakan Sistem Manajemen Logistik dan Peralatan yang telah ditetapkan, baik prabencana, tanggap darurat, dan pascabencana;
b. melakukan koordinasi antara Pemerintah, pemerintah daerah provinsi, pemerintah daerah kabupaten/kota dan/atau lembaga lain;
c. menghimpun data dan informasi yang diperlukan oleh masyarakat dari berbagai sumber yang tidak mengikat yang dapat dipertangungjawabkan;
2018, No. 828
d. menjalankan pedoman Sistem Manajemen Logistik dan Peralatan secara konsisten;
e. membuat perencanaan dan kesepakatan yang relevan;
f. mempertanggungjawabkan tugas dan koordinasi seluruh sumber daya;
g. mengoordinasikan informasi dan komunikasi organisasi pendukung; dan
h. memegang sistem komando bencana dalam hal logistik dan peralatan.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3298, 'perban-4-2018', 15, 'pasal', 'Pasal 12', 'BAB IV POLA PENYELENGGARAAN; Bagian Keempat Penyelenggaraan Tingkat Kabupaten/Kota', 9, '(1) Penyelenggaraan Sistem Manajemen Logistik dan Peralatan dilaksanakan oleh Badan Penanggulangan Bencana Daerah provinsi.
(2) Badan Penanggulangan Bencana Daerah provinsi berkoordinasi dengan organisasi/lembaga yang membantu Sistem Manajemen Logistik dan Peralatan.
(3) Fungsi penyelenggaraan Sistem Manajemen Logistik dan Peralatan tingkat daerah provinsi agar:
a. mempertanggungjawabkan tugas dan wewenang di wilayahnya;
b. membentuk pusat informasi, pemantauan, dan evaluasi situasi di lokasi bencana;
c. mengoordinasikan semua organisasi/lembaga yang terkait dalam penanggulangan bencana dan melaporkannya secara periodik kepada Kepala Badan Nasional Penanggulangan Bencana;
d. memberikan pendampingan kepada daerah kabupaten/kota yang memerlukan; dan
e. membantu wilayah daerah provinsi lainnya atas permintaan atau inisiatif.
2018, No. 828 -10-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3298, '(1) Penyelenggaraan Sistem Manajemen Logistik dan Peralatan dilaksanakan oleh Badan Penanggulangan Bencana Daerah provinsi.
(2) Badan Penanggulangan Bencana Daerah provinsi berkoordinasi dengan organisasi/lembaga yang membantu Sistem Manajemen Logistik dan Peralatan.
(3) Fungsi penyelenggaraan Sistem Manajemen Logistik dan Peralatan tingkat daerah provinsi agar:
a. mempertanggungjawabkan tugas dan wewenang di wilayahnya;
b. membentuk pusat informasi, pemantauan, dan evaluasi situasi di lokasi bencana;
c. mengoordinasikan semua organisasi/lembaga yang terkait dalam penanggulangan bencana dan melaporkannya secara periodik kepada Kepala Badan Nasional Penanggulangan Bencana;
d. memberikan pendampingan kepada daerah kabupaten/kota yang memerlukan; dan
e. membantu wilayah daerah provinsi lainnya atas permintaan atau inisiatif.
2018, No. 828 -10-', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3299, 'perban-4-2018', 16, 'pasal', 'Pasal 13', 'BAB V PEMBINAAN DAN PENGAWASAN; Bagian Kesatu Pembinaan', 10, '(1) Penyelenggaraan Sistem Manajemen Logistik dan Peralatan dilaksanakan oleh Badan Penanggulangan Bencana Daerah kabupaten/kota.
(2) Badan Penanggulangan Bencana Daerah kabupaten/kota berkoordinasi dengan organisasi/lembaga yang membantu Sistem Manajemen Logistik dan Peralatan.
(3) Fungsi penyelenggaraan Sistem Manajemen Logistik dan Peralatan tingkat daerah kabupaten/kota agar:
a. mengelola dan mengoordinasikan seluruh aktivitas Manajemen Logistik dan Peralatan pada prabencana, saat tanggap darurat dan pascabencana dengan organisasi/lembaga terkait;
b. mempertanggungjawabkan dukungan fasilitas, pelayanan, personil, peralatan dan bahan atau material lain yang dibutuhkan oleh Pos Komando Penanganan Darurat Bencana di area bencana; dan
c. membantu wilayah daerah kabupaten/kota lainnya atas permintaan atau inisiatif.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3299, '(1) Penyelenggaraan Sistem Manajemen Logistik dan Peralatan dilaksanakan oleh Badan Penanggulangan Bencana Daerah kabupaten/kota.
(2) Badan Penanggulangan Bencana Daerah kabupaten/kota berkoordinasi dengan organisasi/lembaga yang membantu Sistem Manajemen Logistik dan Peralatan.
(3) Fungsi penyelenggaraan Sistem Manajemen Logistik dan Peralatan tingkat daerah kabupaten/kota agar:
a. mengelola dan mengoordinasikan seluruh aktivitas Manajemen Logistik dan Peralatan pada prabencana, saat tanggap darurat dan pascabencana dengan organisasi/lembaga terkait;
b. mempertanggungjawabkan dukungan fasilitas, pelayanan, personil, peralatan dan bahan atau material lain yang dibutuhkan oleh Pos Komando Penanganan Darurat Bencana di area bencana; dan
c. membantu wilayah daerah kabupaten/kota lainnya atas permintaan atau inisiatif.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3300, 'perban-4-2018', 17, 'pasal', 'Pasal 14', 'BAB V PEMBINAAN DAN PENGAWASAN; Bagian Kedua Pengawasan', 10, '(1) Pembinaan Sistem Manajemen Logistik dan Peralatan dilakukan secara berjenjang sesuai dengan tahapan penanggulangan bencana.
(2) Pejabat yang berwenang memimpin Sistem Manajemen Logistik dan Peralatan diutamakan yang telah memiliki sertifikasi kompetensi yang dikeluarkan oleh Badan Nasional Penanggulangan Bencana.
2018, No. 828
(3) Petugas perencanaan, pengadaan, pergudangan, pendistribusian, penghapusan pada Sistem Manajemen Logistik dan Peralatan, wajib memahami tugas dan tanggung jawabnya.
(4) Apabila ditemukan kesenjangan antara kemampuan petugas dengan hasil yang diharapkan, perlu dilakukan pembinaan terhadap petugas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3300, '(1) Pembinaan Sistem Manajemen Logistik dan Peralatan dilakukan secara berjenjang sesuai dengan tahapan penanggulangan bencana.
(2) Pejabat yang berwenang memimpin Sistem Manajemen Logistik dan Peralatan diutamakan yang telah memiliki sertifikasi kompetensi yang dikeluarkan oleh Badan Nasional Penanggulangan Bencana.
2018, No. 828
(3) Petugas perencanaan, pengadaan, pergudangan, pendistribusian, penghapusan pada Sistem Manajemen Logistik dan Peralatan, wajib memahami tugas dan tanggung jawabnya.
(4) Apabila ditemukan kesenjangan antara kemampuan petugas dengan hasil yang diharapkan, perlu dilakukan pembinaan terhadap petugas.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3301, 'perban-4-2018', 18, 'pasal', 'Pasal 15', 'BAB VI KETENTUAN PENUTUP', 11, '(1) Pengawasan dilakukan secara internal dan eksternal pada setiap tahapan proses Manajemen Logistik dan Peralatan.
(2) Pengawasan internal sebagaimana dimaksud pada ayat
(1) dilakukan oleh inspektorat utama.
(3) Pengawasan eksternal sebagaimana dimaksud pada ayat
(1) dilakukan oleh Badan Pemeriksa Keuangan.
(4) Pengawasan mencakup aktivitas pemantauan, audit, pengukuran, analisis dan evaluasi.
(5) Pengawasan dilakukan dengan merumuskan:
a. kriteria tolok ukur terhadap proses yang terkandung di dalam Sistem Manajemen Logistik dan Peralatan;
b. metode yang digunakan untuk memastikan hasil yang valid;
c. kapan akan dilakukan; dan
d. kapan hasil pengawasan perlu dilakukan analisis dan evaluasi.
(6) Informasi secara tertulis dari hasil pengawasan harus didokumentasikan dan dikendalikan dengan baik sebagai upaya perbaikan berkelanjutan.
2018, No. 828 -12-');
