INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3302, 'perban-4-2018', 19, 'pasal', 'Pasal 16', 'BAB VI KETENTUAN PENUTUP', 12, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008 tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 1411), dicabut dan dinyatakan tidak berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3302, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008 tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 1411), dicabut dan dinyatakan tidak berlaku.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3303, 'perban-4-2018', 20, 'pasal', 'Pasal 17', 'BAB VI KETENTUAN PENUTUP', 12, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
