INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3304, 'perban-4-2018', 21, 'lain', 'Penutup', NULL, 13, 'Ditetapkan di Jakarta pada tanggal 27 Juni 2018 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 29 Juni 2018 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd WIDODO EKATJAHJANA');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3304, 'Ditetapkan di Jakarta pada tanggal 27 Juni 2018 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 29 Juni 2018 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd WIDODO EKATJAHJANA', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2018 tentang Sistem Manajemen Logistik dan Peralatan');
