INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3305, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3306, 'perban-4-2019', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk melaksanakan ketentuan Pasal 62 Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana, perlu menyusun Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana;
b. bahwa organisasi dan tata kerja Badan Nasional Penanggulangan Bencana telah memperoleh persetujuan Menteri Negara Pendayagunaan Aparatur Negara dan Reformasi Birokrasi berdasarkan surat Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor B/788/M.KT.01/2019 tanggal 5 September 2019 perihal Penataan Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3306, 'a. bahwa untuk melaksanakan ketentuan Pasal 62 Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana, perlu menyusun Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana;
b. bahwa organisasi dan tata kerja Badan Nasional Penanggulangan Bencana telah memperoleh persetujuan Menteri Negara Pendayagunaan Aparatur Negara dan Reformasi Birokrasi berdasarkan surat Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor B/788/M.KT.01/2019 tanggal 5 September 2019 perihal Penataan Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3307, 'perban-4-2019', 2, 'mengingat', 'Mengingat', NULL, 2, '2019, No. 1156 -2-
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
