INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3308, 'perban-4-2019', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG ORGANISASI DAN TATA KERJA BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3308, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG ORGANISASI DAN TATA KERJA BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3309, 'perban-4-2019', 4, 'pasal', 'Pasal 1', 'BAB I KEDUDUKAN, TUGAS DAN FUNGSI', 2, '(1) Badan Nasional Penanggulangan Bencana adalah lembaga pemerintah nonkementerian yang berada di bawah dan bertanggung jawab kepada Presiden.
(2) Badan Nasional Penanggulangan Bencana dipimpin oleh seorang Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3309, '(1) Badan Nasional Penanggulangan Bencana adalah lembaga pemerintah nonkementerian yang berada di bawah dan bertanggung jawab kepada Presiden.
(2) Badan Nasional Penanggulangan Bencana dipimpin oleh seorang Kepala.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3310, 'perban-4-2019', 5, 'pasal', 'Pasal 2', 'BAB I KEDUDUKAN, TUGAS DAN FUNGSI', 2, 'Badan Nasional Penanggulangan Bencana mempunyai tugas:
a. memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana yang mencakup pencegahan bencana, penanganan keadaan darurat bencana, rehabilitasi, dan rekonstruksi secara adil dan setara;
b. menetapkan standarisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundang- undangan;
c. menyampaikan informasi kegiatan penanggulangan bencana kepada masyarakat;
d. melaporkan penyelenggaraan penanggulangan bencana kepada Presiden setiap sebulan sekali dalam kondisi normal dan setiap saat dalam kondisi darurat bencana;
2019, No. 1156
e. menggunakan dan mempertanggungjawabkan sumbangan/bantuan nasional dan internasional;
f. mempertanggungjawabkan penggunaan anggaran yang diterima dari Anggaran Pendapatan dan Belanja Negara;
g. melaksanakan kewajiban lain sesuai dengan peraturan perundang- undangan; dan
h. menyusun pedoman pembentukan Badan Penanggulangan Bencana Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3310, 'Badan Nasional Penanggulangan Bencana mempunyai tugas:
a. memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana yang mencakup pencegahan bencana, penanganan keadaan darurat bencana, rehabilitasi, dan rekonstruksi secara adil dan setara;
b. menetapkan standarisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundang- undangan;
c. menyampaikan informasi kegiatan penanggulangan bencana kepada masyarakat;
d. melaporkan penyelenggaraan penanggulangan bencana kepada Presiden setiap sebulan sekali dalam kondisi normal dan setiap saat dalam kondisi darurat bencana;
2019, No. 1156
e. menggunakan dan mempertanggungjawabkan sumbangan/bantuan nasional dan internasional;
f. mempertanggungjawabkan penggunaan anggaran yang diterima dari Anggaran Pendapatan dan Belanja Negara;
g. melaksanakan kewajiban lain sesuai dengan peraturan perundang- undangan; dan
h. menyusun pedoman pembentukan Badan Penanggulangan Bencana Daerah.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3311, 'perban-4-2019', 6, 'pasal', 'Pasal 3', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Pertama Susunan Organisasi', 3, 'Pasal 2, Badan Nasional Penanggulangan Bencana menyelenggarakan fungsi:
a. perumusan dan penetapan norma, standar, prosedur, kriteria, serta persyaratan dan prosedur perizinan dan/atau rekomendasi penyelenggaraan penanggulangan bencana;
b. perumusan dan penetapan kebijakan penanggulangan bencana dan penanganan pengungsi dengan bertindak cepat dan tepat serta efektif dan efisien; dan
c. pengoordinasian pelaksanaan kegiatan penanggulangan bencana secara terencana, terpadu, dan menyeluruh.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3311, 'Pasal 2, Badan Nasional Penanggulangan Bencana menyelenggarakan fungsi:
a. perumusan dan penetapan norma, standar, prosedur, kriteria, serta persyaratan dan prosedur perizinan dan/atau rekomendasi penyelenggaraan penanggulangan bencana;
b. perumusan dan penetapan kebijakan penanggulangan bencana dan penanganan pengungsi dengan bertindak cepat dan tepat serta efektif dan efisien; dan
c. pengoordinasian pelaksanaan kegiatan penanggulangan bencana secara terencana, terpadu, dan menyeluruh.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3312, 'perban-4-2019', 7, 'pasal', 'Pasal 4', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Kedua Kepala', 3, 'Badan Nasional Penanggulangan Bencana terdiri atas:
a. Kepala;
b. unsur pengarah; dan
c. unsur pelaksana.
2019, No. 1156 -4-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3312, 'Badan Nasional Penanggulangan Bencana terdiri atas:
a. Kepala;
b. unsur pengarah; dan
c. unsur pelaksana.
2019, No. 1156 -4-', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3313, 'perban-4-2019', 8, 'pasal', 'Pasal 5', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Ketiga Unsur Pengarah', 4, 'Kepala mempunyai tugas memimpin Badan Nasional Penanggulangan Bencana dalam menjalankan tugas dan fungsi Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3313, 'Kepala mempunyai tugas memimpin Badan Nasional Penanggulangan Bencana dalam menjalankan tugas dan fungsi Badan Nasional Penanggulangan Bencana.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3314, 'perban-4-2019', 9, 'pasal', 'Pasal 6', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Ketiga Unsur Pengarah', 4, 'Unsur pengarah berada di bawah dan bertanggung jawab kepada Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3314, 'Unsur pengarah berada di bawah dan bertanggung jawab kepada Kepala.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3315, 'perban-4-2019', 10, 'pasal', 'Pasal 7', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Ketiga Unsur Pengarah', 4, 'Unsur pengarah mempunyai tugas memberikan masukan dan saran kepada Kepala dalam penyelenggaraan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3315, 'Unsur pengarah mempunyai tugas memberikan masukan dan saran kepada Kepala dalam penyelenggaraan penanggulangan bencana.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3316, 'perban-4-2019', 11, 'pasal', 'Pasal 8', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Ketiga Unsur Pengarah', 4, 'Unsur pengarah menyelenggarakan fungsi:
a. perumusan konsep kebijakan penanggulangan bencana nasional;
b. pemantauan; dan
c. evaluasi dalam penyelenggaraan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3316, 'Unsur pengarah menyelenggarakan fungsi:
a. perumusan konsep kebijakan penanggulangan bencana nasional;
b. pemantauan; dan
c. evaluasi dalam penyelenggaraan penanggulangan bencana.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3317, 'perban-4-2019', 12, 'pasal', 'Pasal 9', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Ketiga Unsur Pengarah', 4, 'Unsur pengarah terdiri dari Ketua yang dijabat oleh Kepala dan 20 (dua puluh) Anggota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3317, 'Unsur pengarah terdiri dari Ketua yang dijabat oleh Kepala dan 20 (dua puluh) Anggota.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3318, 'perban-4-2019', 13, 'pasal', 'Pasal 10', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 4, '(1) Anggota unsur pengarah terdiri dari:
a. 11 (sebelas) pejabat eselon I.a dan eselon I.b atau setara pejabat tinggi madya, yang diusulkan oleh Pimpinan Instansi Pemerintah; dan 2019, No. 1156
b. 9 (sembilan) anggota masyarakat profesional.
(2) Pejabat Pemerintah sebagaimana dimaksud pada ayat (1) huruf a mewakili:
a. Kementerian Koordinator Bidang Pembangunan Manusia dan Kebudayaan;
b. Kementerian Koordinator Bidang Politik, Hukum dan Keamanan;
c. Kementerian Dalam Negeri;
d. Kementerian Keuangan;
e. Kementerian Kesehatan;
f. Kementerian Sosial;
g. Kementerian Energi dan Sumber Daya Mineral;
h. Kementerian Pekerjaan Umum dan Perumahan Rakyat;
i. Kementerian Perhubungan;
j. Kepolisian Negara Republik Indonesia; dan
k. Tentara Negara Republik Indonesia.
(3) Unsur pengarah yang berasal dari masyarakat profesional sebagaimana dimaksud pada ayat (1) huruf b, berasal dari para pakar/profesional dan/atau tokoh masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3318, '(1) Anggota unsur pengarah terdiri dari:
a. 11 (sebelas) pejabat eselon I.a dan eselon I.b atau setara pejabat tinggi madya, yang diusulkan oleh Pimpinan Instansi Pemerintah; dan 2019, No. 1156
b. 9 (sembilan) anggota masyarakat profesional.
(2) Pejabat Pemerintah sebagaimana dimaksud pada ayat (1) huruf a mewakili:
a. Kementerian Koordinator Bidang Pembangunan Manusia dan Kebudayaan;
b. Kementerian Koordinator Bidang Politik, Hukum dan Keamanan;
c. Kementerian Dalam Negeri;
d. Kementerian Keuangan;
e. Kementerian Kesehatan;
f. Kementerian Sosial;
g. Kementerian Energi dan Sumber Daya Mineral;
h. Kementerian Pekerjaan Umum dan Perumahan Rakyat;
i. Kementerian Perhubungan;
j. Kepolisian Negara Republik Indonesia; dan
k. Tentara Negara Republik Indonesia.
(3) Unsur pengarah yang berasal dari masyarakat profesional sebagaimana dimaksud pada ayat (1) huruf b, berasal dari para pakar/profesional dan/atau tokoh masyarakat.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3319, 'perban-4-2019', 14, 'pasal', 'Pasal 11', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 5, 'Unsur pelaksana berada di bawah dan bertanggung jawab kepada Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3319, 'Unsur pelaksana berada di bawah dan bertanggung jawab kepada Kepala.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3320, 'perban-4-2019', 15, 'pasal', 'Pasal 12', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 5, 'Unsur pelaksana mempunyai tugas melaksanakan penanggulangan bencana secara terintegrasi yang meliputi prabencana, saat keadaan darurat bencana, dan pascabencana.
2019, No. 1156 -6-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3320, 'Unsur pelaksana mempunyai tugas melaksanakan penanggulangan bencana secara terintegrasi yang meliputi prabencana, saat keadaan darurat bencana, dan pascabencana.
2019, No. 1156 -6-', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3321, 'perban-4-2019', 16, 'pasal', 'Pasal 13', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 6, 'Tugas sebagaimana dimaksud dalam Pasal 12 meliputi:
a. penyusunan kebijakan di bidang penanggulangan bencana;
b. pelaksanaan kebijakan di bidang penanggulangan bencana;
c. penyusunan, perumusan, dan penetapan norma, standar, kriteria, dan prosedur di bidang penanggulangan bencana;
d. pemberian bimbingan teknis dan supervisi di bidang penanggulangan bencana;
e. pengoordinasian instansi pemerintah terkait, pemerintah daerah, masyarakat, dan lembaga usaha serta lembaga internasional dalam rangka penyusunan dan perumusan serta pelaksanaan kebijakan teknis di bidang penanggulangan bencana;
f. koordinasi pelaksanaan fungsi, pembinaan, dan pemberian dukungan administrasi kepada seluruh unsur organisasi di lingkungan Badan Nasional Penanggulangan Bencana;
g. pengelolaan barang milik/kekayaan negara yang menjadi tanggung jawab Badan Nasional Penanggulangan Bencana;
h. pengawasan atas pelaksanaan fungsi di lingkungan Badan Nasional Penanggulangan Bencana; dan
i. pelaksanaan dukungan yang bersifat substantif kepada seluruh unsur organisasi di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3321, 'Tugas sebagaimana dimaksud dalam Pasal 12 meliputi:
a. penyusunan kebijakan di bidang penanggulangan bencana;
b. pelaksanaan kebijakan di bidang penanggulangan bencana;
c. penyusunan, perumusan, dan penetapan norma, standar, kriteria, dan prosedur di bidang penanggulangan bencana;
d. pemberian bimbingan teknis dan supervisi di bidang penanggulangan bencana;
e. pengoordinasian instansi pemerintah terkait, pemerintah daerah, masyarakat, dan lembaga usaha serta lembaga internasional dalam rangka penyusunan dan perumusan serta pelaksanaan kebijakan teknis di bidang penanggulangan bencana;
f. koordinasi pelaksanaan fungsi, pembinaan, dan pemberian dukungan administrasi kepada seluruh unsur organisasi di lingkungan Badan Nasional Penanggulangan Bencana;
g. pengelolaan barang milik/kekayaan negara yang menjadi tanggung jawab Badan Nasional Penanggulangan Bencana;
h. pengawasan atas pelaksanaan fungsi di lingkungan Badan Nasional Penanggulangan Bencana; dan
i. pelaksanaan dukungan yang bersifat substantif kepada seluruh unsur organisasi di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3322, 'perban-4-2019', 17, 'pasal', 'Pasal 14', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 6, 'Dalam menyelenggarakan tugas sebagaimana dimaksud dalam Pasal 13, unsur pelaksana mempunyai fungsi:
a. koordinasi penyelenggaraan penanggulangan bencana;
b. komando penyelenggaraan penanggulangan bencana; dan
c. pelaksana dalam penyelenggaraan penanggulangan bencana.
2019, No. 1156');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3322, 'Dalam menyelenggarakan tugas sebagaimana dimaksud dalam Pasal 13, unsur pelaksana mempunyai fungsi:
a. koordinasi penyelenggaraan penanggulangan bencana;
b. komando penyelenggaraan penanggulangan bencana; dan
c. pelaksana dalam penyelenggaraan penanggulangan bencana.
2019, No. 1156', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3323, 'perban-4-2019', 18, 'pasal', 'Pasal 15', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 7, '(1) Fungsi koordinasi sebagaimana dimaksud dalam Pasal 14 huruf a dilaksanakan pada tahap prabencana dan pascabencana.
(2) Fungsi koordinasi unsur pelaksana dilaksanakan melalui koordinasi dengan instansi pemerintah baik pusat maupun daerah, masyarakat, lembaga usaha, lembaga internasional dan/atau pihak lain yang dipandang perlu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3323, '(1) Fungsi koordinasi sebagaimana dimaksud dalam Pasal 14 huruf a dilaksanakan pada tahap prabencana dan pascabencana.
(2) Fungsi koordinasi unsur pelaksana dilaksanakan melalui koordinasi dengan instansi pemerintah baik pusat maupun daerah, masyarakat, lembaga usaha, lembaga internasional dan/atau pihak lain yang dipandang perlu.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3324, 'perban-4-2019', 19, 'pasal', 'Pasal 16', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 7, '(1) Fungsi komando unsur pelaksana sebagaimana dimaksud dalam Pasal 14 huruf b dilaksanakan melalui pengerahan sumber daya manusia, logistik dan peralatan dari instansi terkait, Kepolisian Negara Republik Indonesia, dan Tentara Nasional Indonesia serta langkah lain yang diperlukan dalam rangka penanganan darurat bencana.
(2) Pelaksanaan ketentuan sebagaimana dimaksud pada ayat (1) dilakukan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3324, '(1) Fungsi komando unsur pelaksana sebagaimana dimaksud dalam Pasal 14 huruf b dilaksanakan melalui pengerahan sumber daya manusia, logistik dan peralatan dari instansi terkait, Kepolisian Negara Republik Indonesia, dan Tentara Nasional Indonesia serta langkah lain yang diperlukan dalam rangka penanganan darurat bencana.
(2) Pelaksanaan ketentuan sebagaimana dimaksud pada ayat (1) dilakukan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3325, 'perban-4-2019', 20, 'pasal', 'Pasal 17', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 7, 'Fungsi pelaksanaan pada unsur pelaksana sebagaimana dimaksud pada Pasal 14 huruf c dilaksanakan secara terkoordinasi dan terintegrasi dengan instansi pemerintah baik pusat maupun daerah, Kepolisian Negara Republik Indonesia dan Tentara Nasional Indonesia dengan memperhatikan kebijakan penyelenggaraan penanggulangan bencana dan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3325, 'Fungsi pelaksanaan pada unsur pelaksana sebagaimana dimaksud pada Pasal 14 huruf c dilaksanakan secara terkoordinasi dan terintegrasi dengan instansi pemerintah baik pusat maupun daerah, Kepolisian Negara Republik Indonesia dan Tentara Nasional Indonesia dengan memperhatikan kebijakan penyelenggaraan penanggulangan bencana dan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3326, 'perban-4-2019', 21, 'pasal', 'Pasal 18', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 7, 'Dalam melaksanakan tugas dan fungsi sebagaimana dimaksud dalam Pasal 13 dan Pasal 17, Badan Nasional Penanggulangan Bencana dikoordinasikan oleh kementerian yang menyelenggarakan koordinasi, sinkronisasi, dan pengendalian urusan kementerian dalam penyelenggaraan 2019, No. 1156 -8- pemerintahan di bidang pembangunan manusia dan kebudayaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3326, 'Dalam melaksanakan tugas dan fungsi sebagaimana dimaksud dalam Pasal 13 dan Pasal 17, Badan Nasional Penanggulangan Bencana dikoordinasikan oleh kementerian yang menyelenggarakan koordinasi, sinkronisasi, dan pengendalian urusan kementerian dalam penyelenggaraan 2019, No. 1156 -8- pemerintahan di bidang pembangunan manusia dan kebudayaan.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3327, 'perban-4-2019', 22, 'pasal', 'Pasal 19', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 8, 'Susunan Organisasi unsur pelaksana terdiri dari:
a. Sekretariat Utama;
b. Deputi Bidang Sistem dan Strategi;
c. Deputi Bidang Pencegahan;
d. Deputi Bidang Penanganan Darurat;
e. Deputi Bidang Rehabilitasi dan Rekonstruksi;
f. Deputi Bidang Logistik dan Peralatan; dan
g. Inspektorat Utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3327, 'Susunan Organisasi unsur pelaksana terdiri dari:
a. Sekretariat Utama;
b. Deputi Bidang Sistem dan Strategi;
c. Deputi Bidang Pencegahan;
d. Deputi Bidang Penanganan Darurat;
e. Deputi Bidang Rehabilitasi dan Rekonstruksi;
f. Deputi Bidang Logistik dan Peralatan; dan
g. Inspektorat Utama.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3328, 'perban-4-2019', 23, 'pasal', 'Pasal 20', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 8, '(1) Sekretariat Utama berada berada di bawah dan bertanggung jawab kepada Kepala.
(2) Sekretariat Utama dipimpin oleh Sekretaris Utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3328, '(1) Sekretariat Utama berada berada di bawah dan bertanggung jawab kepada Kepala.
(2) Sekretariat Utama dipimpin oleh Sekretaris Utama.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3329, 'perban-4-2019', 24, 'pasal', 'Pasal 21', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 8, 'Sekretariat Utama mempunyai tugas menyelenggarakan koordinasi pelaksanaan tugas, pembinaan, dan pemberian dukungan administrasi kepada seluruh unsur organisasi di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3329, 'Sekretariat Utama mempunyai tugas menyelenggarakan koordinasi pelaksanaan tugas, pembinaan, dan pemberian dukungan administrasi kepada seluruh unsur organisasi di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3330, 'perban-4-2019', 25, 'pasal', 'Pasal 22', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 8, 'Pasal 21, Sekretariat Utama menyelenggarakan fungsi:
a. koordinasi kegiatan Badan Nasional Penanggulangan Bencana;
b. koordinasi dan penyusunan rencana, program dan anggaran Badan Nasional Penanggulangan Bencana;
2019, No. 1156
c. pembinaan dan pemberian dukungan administrasi yang meliputi ketatausahaan, kearsipan, sumber daya manusia, keuangan, kerumahtanggaan, kerja sama, hubungan masyarakat, dokumentasi, dan keprotokolan Badan Nasional Penanggulangan Bencana;
d. pembinaan dan penataan organisasi dan tata laksana;
e. koordinasi dan penyusunan peraturan perundang-undangan serta pelaksanaan advokasi hukum;
f. penyelenggaraan pengelolaan barang milik/kekayaan Negara; dan
g. pelaksanaan fungsi lain yang diberikan oleh Kepala.');
