INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3331, 'perban-4-2019', 26, 'pasal', 'Pasal 23', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 9, 'Sekretariat Utama terdiri dari:
