INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3332, 'perban-4-2019', 27, 'pasal', 'Pasal 24', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 9, 'Biro Perencanaan mempunyai tugas melaksanakan koordinasi penyusunan program dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara dan nonAnggaran Pendapatan dan Belanja Negara luar negeri dan dalam negeri, monitoring, evaluasi, dan penyusunan laporan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3332, 'Biro Perencanaan mempunyai tugas melaksanakan koordinasi penyusunan program dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara dan nonAnggaran Pendapatan dan Belanja Negara luar negeri dan dalam negeri, monitoring, evaluasi, dan penyusunan laporan Badan Nasional Penanggulangan Bencana.', 'Pasal 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3333, 'perban-4-2019', 28, 'pasal', 'Pasal 25', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 9, 'Pasal 24, Biro Perencanaan menyelenggarakan fungsi:
