INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3334, 'perban-4-2019', 29, 'pasal', 'Pasal 26', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 10, 'Biro Perencanaan terdiri dari:
