INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3335, 'perban-4-2019', 30, 'pasal', 'Pasal 27', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 10, 'Bagian Penyusunan Program dan Anggaran I mempunyai tugas melaksanakan penyiapan koordinasi penyusunan program dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara dan nonAnggaran Pendapatan dan Belanja Negara dalam negeri di lingkungan Deputi Bidang Sistem dan Strategi, Deputi Bidang Pencegahan, Deputi Bidang Rehabilitasi dan Rekonstruksi, Pusat Data, Informasi dan Komunikasi Kebencanaan, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, dan Pusat Pengendalian Operasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3335, 'Bagian Penyusunan Program dan Anggaran I mempunyai tugas melaksanakan penyiapan koordinasi penyusunan program dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara dan nonAnggaran Pendapatan dan Belanja Negara dalam negeri di lingkungan Deputi Bidang Sistem dan Strategi, Deputi Bidang Pencegahan, Deputi Bidang Rehabilitasi dan Rekonstruksi, Pusat Data, Informasi dan Komunikasi Kebencanaan, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, dan Pusat Pengendalian Operasi.', 'Pasal 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3336, 'perban-4-2019', 31, 'pasal', 'Pasal 28', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 10, 'Pasal 27, Bagian Penyusunan Program dan Anggaran I menyelenggarakan fungsi:
a. penyiapan bahan penyusunan rencana, program, kegiatan dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara; dan
b. penyiapan bahan penyusunan rencana, program, kegiatan dan anggaran yang bersumber dari nonAnggaran Belanja dan Pendapatan Negara dalam negeri.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3336, 'Pasal 27, Bagian Penyusunan Program dan Anggaran I menyelenggarakan fungsi:
a. penyiapan bahan penyusunan rencana, program, kegiatan dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara; dan
b. penyiapan bahan penyusunan rencana, program, kegiatan dan anggaran yang bersumber dari nonAnggaran Belanja dan Pendapatan Negara dalam negeri.', 'Pasal 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3337, 'perban-4-2019', 32, 'pasal', 'Pasal 29', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 10, 'Bagian Penyusunan Program dan Anggaran I terdiri dari:
