INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3338, 'perban-4-2019', 33, 'pasal', 'Pasal 30', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 11, '(1) Subbagian Program dan Anggaran IA mempunyai tugas melakukan penyiapan bahan penyusunan rencana, program, kegiatan dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara dan nonAnggaran Pendapatan dan Belanja Negara dalam Negeri di lingkungan Deputi Bidang Sistem dan Strategi dan Deputi Bidang Pencegahan.
(2) Subbagian Program dan Anggaran IB mempunyai tugas melakukan penyiapan bahan penyusunan rencana, program, kegiatan dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara dan nonAnggaran Pendapatan dan Belanja Negara dalam negeri di lingkungan Deputi Bidang Rehabilitasi dan Rekonstruksi, Pusat Data, Informasi dan Komunikasi Kebencanaan, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, dan Pusat Pengendalian Operasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3338, '(1) Subbagian Program dan Anggaran IA mempunyai tugas melakukan penyiapan bahan penyusunan rencana, program, kegiatan dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara dan nonAnggaran Pendapatan dan Belanja Negara dalam Negeri di lingkungan Deputi Bidang Sistem dan Strategi dan Deputi Bidang Pencegahan.
(2) Subbagian Program dan Anggaran IB mempunyai tugas melakukan penyiapan bahan penyusunan rencana, program, kegiatan dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara dan nonAnggaran Pendapatan dan Belanja Negara dalam negeri di lingkungan Deputi Bidang Rehabilitasi dan Rekonstruksi, Pusat Data, Informasi dan Komunikasi Kebencanaan, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, dan Pusat Pengendalian Operasi.', 'Pasal 30', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3339, 'perban-4-2019', 34, 'pasal', 'Pasal 31', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 11, 'Bagian Penyusunan Program dan Anggaran II mempunyai tugas melaksanakan penyiapan bahan koordinasi penyusunan program dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara dan non Anggaran Pendapatan dan Belanja Negara luar negeri di lingkungan Deputi Bidang Penanganan Darurat, Deputi Bidang Logistik dan Peralatan, Sekretariat Utama, dan Inspektorat Utama.');
