INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3342, '(1) Subbagian Program dan Anggaran IIA mempunyai tugas melakukan penyiapan bahan penyusunan rencana, program, kegiatan, dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara dan nonAnggaran Pendapatan dan Belanja Negara luar Negeri di lingkungan Deputi Bidang Penanganan Darurat dan Deputi Bidang Logistik dan Peralatan.
(2) Subbagian Anggaran dan Program IIB mempunyai tugas melakukan penyiapan bahan penyusunan rencana, program, kegiatan dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara dan nonAnggaran Pendapatan dan Belanja Negara luar negeri di lingkungan Sekretariat Utama dan Inspektorat Utama.', 'Pasal 34', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
