INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3346, 'perban-4-2019', 41, 'pasal', 'Pasal 38', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 13, '(1) Subbagian Monitoring dan Evaluasi Program dan Anggaran I mempunyai tugas melakukan penyiapan bahan koordinasi monitoring, evaluasi, dan laporan pelaksanaan program, kegiatan dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara dan nonAnggaran Pendapatan dan Belanja Negara di lingkungan Deputi Bidang Sistem dan Strategi, Deputi Bidang Pencegahan, Deputi Bidang Rehabilitasi dan Rekonstruksi, Pusat Data, Informasi dan Komunikasi Kebencanaan, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, dan Pusat Pengendalian Operasi.
