INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3347, 'perban-4-2019', 42, 'pasal', 'Pasal 39', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 14, 'Biro Keuangan mempunyai tugas melaksanakan koordinasi, pengelolaan, dan pelaksanaan anggaran di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3347, 'Biro Keuangan mempunyai tugas melaksanakan koordinasi, pengelolaan, dan pelaksanaan anggaran di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 39', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3348, 'perban-4-2019', 43, 'pasal', 'Pasal 40', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 14, 'Pasal 39, Biro Keuangan menyelenggarakan fungsi:
a. penyiapan koordinasi pelaksanaan anggaran pendapatan dan belanja negara;
b. koordinasi penyusunan norma, standar, prosedur, dan kriteria di bidang keuangan;
c. pelaksanaan pengeluaran keuangan;
d. pelaksanaan urusan perbendaharaan, penyelesaian kerugian negara dan pembinaan penatausahaan administrasi keuangan;
e. pelaksanaan koordinasi pembinaan penatausahaan Penerimaan Negara Bukan Pajak; dan
f. pelaksanaan verifikasi dan akuntansi anggaran serta penyusunan laporan keuangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3348, 'Pasal 39, Biro Keuangan menyelenggarakan fungsi:
a. penyiapan koordinasi pelaksanaan anggaran pendapatan dan belanja negara;
b. koordinasi penyusunan norma, standar, prosedur, dan kriteria di bidang keuangan;
c. pelaksanaan pengeluaran keuangan;
d. pelaksanaan urusan perbendaharaan, penyelesaian kerugian negara dan pembinaan penatausahaan administrasi keuangan;
e. pelaksanaan koordinasi pembinaan penatausahaan Penerimaan Negara Bukan Pajak; dan
f. pelaksanaan verifikasi dan akuntansi anggaran serta penyusunan laporan keuangan.', 'Pasal 40', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3349, 'perban-4-2019', 44, 'pasal', 'Pasal 41', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 14, 'Biro Keuangan terdiri dari:
