INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3350, 'Bagian Pelaksanaan Anggaran mempunyai tugas melaksanakan penyiapan koordinasi penggunaan/ pengeluaran dan penerimaan anggaran serta pengelolaan anggaran di lingkungan Badan Nasional Penanggulangan Bencana.
