INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3351, 'perban-4-2019', 46, 'pasal', 'Pasal 43', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 15, 'Pasal 42, Bagian Pelaksanaan Anggaran menyelenggarakan fungsi:
a. penyiapan bahan koordinasi penggunaan/pengeluaran dan penerimaan serta pengelolaan anggaran yang proses dan pertanggungjawabannya melalui Kantor Pelayanan Perbendaharaan Negara; dan
b. penyiapan bahan koordinasi penggunaan/pengeluaran dan penerimaan serta pengelolaan anggaran yang proses dan pertanggungjawabannya tidak melalui Kantor Pelayanan Perbendaharaan Negara.');
