INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3377, 'Biro Sumber Daya Manusia dan Umum mempunyai tugas melaksanakan koordinasi urusan sumber daya manusia, rumah tangga, tata usaha, keprotokolan, dan barang milik/kekayaan Negara di lingkungan Badan Nasional Penanggulangan Bencana.
