INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3378, 'perban-4-2019', 73, 'pasal', 'Pasal 70', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 21, 'Pasal 69, Biro Sumber Daya Manusia dan Umum menyelenggarakan fungsi:
