INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3379, 'perban-4-2019', 74, 'pasal', 'Pasal 71', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 21, 'Biro Sumber Daya Manusia dan Umum terdiri dari:
