INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3380, 'perban-4-2019', 75, 'pasal', 'Pasal 72', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 21, 'Bagian Sumber Daya Manusia mempunyai tugas melaksanakan penyiapan koordinasi pembinaan, penyusunan dan penetapan kebutuhan, pengadaan, kepangkatan, pengembangan dan pola karir, mutasi, penilaian kinerja, kesejahteraan, penghargaan, disiplin, pemberhentian, dan pengembangan sistem informasi sumber daya manusia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3380, 'Bagian Sumber Daya Manusia mempunyai tugas melaksanakan penyiapan koordinasi pembinaan, penyusunan dan penetapan kebutuhan, pengadaan, kepangkatan, pengembangan dan pola karir, mutasi, penilaian kinerja, kesejahteraan, penghargaan, disiplin, pemberhentian, dan pengembangan sistem informasi sumber daya manusia.', 'Pasal 72', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3381, 'perban-4-2019', 76, 'pasal', 'Pasal 73', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 21, 'Pasal 72, Bagian Sumber Daya Manusia menyelenggarakan fungsi:
