INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3382, 'perban-4-2019', 77, 'pasal', 'Pasal 74', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 22, 'Bagian Sumber Daya Manusia terdiri dari:
