INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3383, 'perban-4-2019', 78, 'pasal', 'Pasal 75', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 22, '(1) Subbagian Perencanaan dan Pengembangan Sumber Daya Manusia mempunyai tugas melakukan penyiapan bahan pelaksanaan penyusunan dan penetapan kebutuhan, pengadaan, pengembangan dan pola karier, penilaian kinerja sumber daya manusia.
(2) Subbagian Mutasi dan Kesejahteraan mempunyai tugas melakukan penyiapan bahan pelaksanaan pengangkatan, pemindahan, pemberhentian, kesejahteraan, disiplin, konseling, administrasi dan pengembangan sistem informasi sumber daya manusia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3383, '(1) Subbagian Perencanaan dan Pengembangan Sumber Daya Manusia mempunyai tugas melakukan penyiapan bahan pelaksanaan penyusunan dan penetapan kebutuhan, pengadaan, pengembangan dan pola karier, penilaian kinerja sumber daya manusia.
(2) Subbagian Mutasi dan Kesejahteraan mempunyai tugas melakukan penyiapan bahan pelaksanaan pengangkatan, pemindahan, pemberhentian, kesejahteraan, disiplin, konseling, administrasi dan pengembangan sistem informasi sumber daya manusia.', 'Pasal 75', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3384, 'perban-4-2019', 79, 'pasal', 'Pasal 76', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 22, 'Bagian Rumah Tangga dan Perlengkapan mempunyai tugas melaksanakan penyiapan koordinasi urusan rumah tangga, barang milik/kekayaan Negara, perlengkapan, dan pelayanan pengadaan barang/jasa di lingkungan Badan Nasional Penanggulangan Bencana.');
