INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3385, 'perban-4-2019', 80, 'pasal', 'Pasal 77', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 22, 'Pasal 76, Bagian Rumah Tangga dan Perlengkapan menyelenggarakan fungsi:
