INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3386, 'perban-4-2019', 81, 'pasal', 'Pasal 78', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 23, 'Bagian Rumah Tangga dan Perlengkapan terdiri dari:
