INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3387, 'perban-4-2019', 82, 'pasal', 'Pasal 79', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 23, '(1) Subbagian Urusan Dalam mempunyai tugas melakukan urusan rumah tangga, perlengkapan, pemeliharaan gedung, kendaraan, ketertiban, dan keamanan.
(2) Subbagian Barang Milik Negara mempunyai tugas melakukan urusan barang milik negara, peralatan kerja, barang inventaris kantor, dan penyiapan bahan koordinasi pelayanan pengadaan barang dan jasa di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3387, '(1) Subbagian Urusan Dalam mempunyai tugas melakukan urusan rumah tangga, perlengkapan, pemeliharaan gedung, kendaraan, ketertiban, dan keamanan.
(2) Subbagian Barang Milik Negara mempunyai tugas melakukan urusan barang milik negara, peralatan kerja, barang inventaris kantor, dan penyiapan bahan koordinasi pelayanan pengadaan barang dan jasa di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 79', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3388, 'perban-4-2019', 83, 'pasal', 'Pasal 80', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 23, 'Bagian Tata Usaha dan Kearsipan mempunyai tugas melaksanakan penyiapan koordinasi urusan persuratan, kearsipan, protokol, dan tata usaha pimpinan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3388, 'Bagian Tata Usaha dan Kearsipan mempunyai tugas melaksanakan penyiapan koordinasi urusan persuratan, kearsipan, protokol, dan tata usaha pimpinan.', 'Pasal 80', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
