INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3391, 'perban-4-2019', 86, 'pasal', 'Pasal 83', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 24, '(1) Subbagian Persuratan dan Kearsipan mempunyai tugas melakukan urusan persuratan dan kearsipan.
(2) Subbagian Tata Usaha Pimpinan dan Protokol mempunyai tugas melakukan urusan tata usaha dan protokol Kepala.
(3) Subbagian Tata Usaha Deputi Bidang Sistem dan Strategi mempunyai tugas melakukan urusan tata usaha di lingkungan Deputi Bidang Sistem dan Strategi.
(4) Subbagian Tata Usaha Deputi Bidang Pencegahan mempunyai tugas melakukan urusan tata usaha di lingkungan Deputi Bidang Pencegahan.
(5) Subbagian Tata Usaha Deputi Bidang Penanganan Darurat mempunyai tugas melakukan urusan tata usaha di lingkungan Deputi Bidang Penanganan Darurat.
(6) Subbagian Tata Usaha Deputi Bidang Rehabilitasi dan Rekonstruksi mempunyai tugas melakukan urusan tata usaha di lingkungan Deputi Bidang Rehabilitasi dan Rekonstruksi.
(7) Subbagian Tata Usaha Deputi Bidang Logistik dan Peralatan mempunyai tugas melakukan urusan tata usaha di lingkungan Deputi Bidang Logistik dan Peralatan.
2019, No. 1156');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3391, '(1) Subbagian Persuratan dan Kearsipan mempunyai tugas melakukan urusan persuratan dan kearsipan.
(2) Subbagian Tata Usaha Pimpinan dan Protokol mempunyai tugas melakukan urusan tata usaha dan protokol Kepala.
(3) Subbagian Tata Usaha Deputi Bidang Sistem dan Strategi mempunyai tugas melakukan urusan tata usaha di lingkungan Deputi Bidang Sistem dan Strategi.
(4) Subbagian Tata Usaha Deputi Bidang Pencegahan mempunyai tugas melakukan urusan tata usaha di lingkungan Deputi Bidang Pencegahan.
(5) Subbagian Tata Usaha Deputi Bidang Penanganan Darurat mempunyai tugas melakukan urusan tata usaha di lingkungan Deputi Bidang Penanganan Darurat.
(6) Subbagian Tata Usaha Deputi Bidang Rehabilitasi dan Rekonstruksi mempunyai tugas melakukan urusan tata usaha di lingkungan Deputi Bidang Rehabilitasi dan Rekonstruksi.
(7) Subbagian Tata Usaha Deputi Bidang Logistik dan Peralatan mempunyai tugas melakukan urusan tata usaha di lingkungan Deputi Bidang Logistik dan Peralatan.
2019, No. 1156', 'Pasal 83', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3392, 'perban-4-2019', 87, 'pasal', 'Pasal 84', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 25, 'Deputi Bidang Sistem dan Strategi mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan di bidang sistem dan strategi penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3392, 'Deputi Bidang Sistem dan Strategi mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan di bidang sistem dan strategi penanggulangan bencana.', 'Pasal 84', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3393, 'perban-4-2019', 88, 'pasal', 'Pasal 85', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 25, 'Pasal 84, Deputi Bidang Sistem dan Strategi menyelenggarakan fungsi:
a. penyusunan kebijakan teknis di bidang sistem dan strategi;
b. pelaksanaan kebijakan teknis di bidang sistem dan strategi;
c. koordinasi dan sinkronisasi kebijakan dalam perencanaan penanggulangan bencana;
d. penyusunan norma, standar, prosedur, dan kriteria di bidang sistem dan strategi;
e. pemberian bimbingan teknis dan supervisi di bidang sistem dan strategi;
f. pemantauan, evaluasi dan pelaporan di bidang sistem dan strategi; dan
g. pelaksanaan fungsi lain yang diberikan oleh Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3393, 'Pasal 84, Deputi Bidang Sistem dan Strategi menyelenggarakan fungsi:
a. penyusunan kebijakan teknis di bidang sistem dan strategi;
b. pelaksanaan kebijakan teknis di bidang sistem dan strategi;
c. koordinasi dan sinkronisasi kebijakan dalam perencanaan penanggulangan bencana;
d. penyusunan norma, standar, prosedur, dan kriteria di bidang sistem dan strategi;
e. pemberian bimbingan teknis dan supervisi di bidang sistem dan strategi;
f. pemantauan, evaluasi dan pelaporan di bidang sistem dan strategi; dan
g. pelaksanaan fungsi lain yang diberikan oleh Kepala.', 'Pasal 85', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
