INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3559, 'perban-4-2019', 254, 'pasal', 'Pasal 251', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 72, 'Inspektorat Utama mempunyai tugas menyelenggarakan tugas pengawasan internal di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3559, 'Inspektorat Utama mempunyai tugas menyelenggarakan tugas pengawasan internal di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 251', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3560, 'perban-4-2019', 255, 'pasal', 'Pasal 252', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 72, 'Pasal 251, Inspektorat Utama menyelenggarakan fungsi:
a. penyusunan kebijakan teknis pengawasan internal di lingkungan Badan Nasional Penanggulangan Bencana;
b. pelaksanaan pengawasan internal di lingkungan Badan Nasional Penanggulangan Bencana terhadap kinerja dan keuangan melalui audit, reviu, evaluasi, dan pemantauan;
c. pelaksanaan pengawasan untuk tujuan tertentu atas penugasan Kepala;
d. penyusunan laporan hasil pengawasan;
e. pelaksanaan administrasi Inspektorat Utama; dan
f. pelaksanaan fungsi lain yang diberikan oleh Kepala.');
