INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3568, 'perban-4-2019', 263, 'pasal', 'Pasal 260', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 75, '(1) Inspektorat I, Inspektorat II, dan Inspektorat III sebagaimana dimaksud pada Pasal 253 didukung oleh Kelompok Jabatan Fungsional Auditor.
