INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3568, '(1) Inspektorat I, Inspektorat II, dan Inspektorat III sebagaimana dimaksud pada Pasal 253 didukung oleh Kelompok Jabatan Fungsional Auditor.
(2) Kelompok Jabatan Fungsional Auditor sebagaimana dimaksud pada ayat (1) mempunyai tugas melakukan kegiatan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 260', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3569, 'perban-4-2019', 264, 'pasal', 'Pasal 261', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 75, 'Bagian Tata Usaha mempunyai tugas menyelenggarakan dan mengoordinasikan dukungan tata usaha untuk kelancaran tugas dan fungsi Inspektorat Utama serta melaporkan pelaksanaan tugas kepada Inspektur Utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3569, 'Bagian Tata Usaha mempunyai tugas menyelenggarakan dan mengoordinasikan dukungan tata usaha untuk kelancaran tugas dan fungsi Inspektorat Utama serta melaporkan pelaksanaan tugas kepada Inspektur Utama.', 'Pasal 261', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
