INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3572, 'perban-4-2019', 267, 'pasal', 'Pasal 264', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 75, '(1) Subbagian Pengelolaan Tindak Lanjut Hasil Pemeriksaan mempunyai tugas melakukan urusan tata usaha laporan hasil pengawasan dan tindak lanjut hasil pengawasan.
