(2) Subbagian Umum dan Keuangan mempunyai tugas melakukan urusan tata usaha, keuangan, kepegawaian, perlengkapan, arsip dan dokumentasi di lingkungan Inspektorat Utama.', 'Pasal 264', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3573, 'perban-4-2019', 268, 'pasal', 'Pasal 265', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 76, 'Pusat Data, Informasi, dan Komunikasi Kebencanaan mempunyai tugas koordinasi dan pelayanan di bidang pengelolaan data dan informasi, pengembangan basis data dan informasi, serta pelaksanaan komunikasi kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3573, 'Pusat Data, Informasi, dan Komunikasi Kebencanaan mempunyai tugas koordinasi dan pelayanan di bidang pengelolaan data dan informasi, pengembangan basis data dan informasi, serta pelaksanaan komunikasi kebencanaan.', 'Pasal 265', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3574, 'perban-4-2019', 269, 'pasal', 'Pasal 266', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 76, 'Pasal 265, Pusat Data, Informasi, dan Komunikasi Kebencanaan menyelenggarakan fungsi:
a. penyiapan penyusunan dan pelaksanaan kebijakan teknis di bidang data, informasi dan komunikasi kebencanaan;
b. penyiapan koordinasi penyusunan norma, standar, prosedur dan kriteria di bidang data, informasi, dan komunikasi kebencanaan;
c. pengelolaan, pengembangan, dan pengintegrasian teknologi dan jaringan di lingkungan Badan Nasional Penanggulangan Bencana;
d. penyiapan komunikasi dengan media, pemberitaan, peliputan, publikasi serta pengelolaan dokumentasi penanggulangan bencana;
e. pengelolaan perpustakaan dan pelaksanaan digitalisasi dokumen kebencanaan di bidang penanggulangan bencana; dan
f. pemantauan, evaluasi dan analisis laporan pengelolaan data, informasi dan komunikasi kebencanaan.
2019, No. 1156');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3574, 'Pasal 265, Pusat Data, Informasi, dan Komunikasi Kebencanaan menyelenggarakan fungsi:
