INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3576, 'perban-4-2019', 271, 'pasal', 'Pasal 268', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 77, 'Bidang Pengelolaan Data dan Sistem Informasi mempunyai tugas melaksanakan penyiapan koordinasi penyusunan rencana dan program pengelolaan data spasial dan statistik, melaksanakan pengumpulan, pengolahan, analisis dan penyajian data spasial dan statistik, pengembangan metode dan standar pengelolaan basis data penanggulangan bencana.');
