INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3579, 'perban-4-2019', 274, 'pasal', 'Pasal 271', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 78, '(1) Subbidang Pengelolaan Data dan Sistem Informasi Spasial mempunyai tugas melakukan penyiapan bahan penyusunan rencana dan program pengelolaan data spasial, pengumpulan, pengolahan, analisis dan penyajian data spasial, pengembangan metode dan standar pengelolaan basis data spasial, serta pemantauan, evaluasi dan analisis pelaporan di bidang pengelolaan data dan sistem informasi spasial.
(2) Subbidang Pengelolaan Data dan Sistem Informasi Statistik mempunyai tugas melakukan penyiapan bahan penyusunan rencana dan program pengelolaan data statistik, pengumpulan, pengolahan, analisa dan penyajian data statistik, pengembangan metode dan standard pengelolaan basis data statistik, serta pemantauan, evaluasi dan analisis pelaporan di bidang pengelolaan data dan sistem informasi statistik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3579, '(1) Subbidang Pengelolaan Data dan Sistem Informasi Spasial mempunyai tugas melakukan penyiapan bahan penyusunan rencana dan program pengelolaan data spasial, pengumpulan, pengolahan, analisis dan penyajian data spasial, pengembangan metode dan standar pengelolaan basis data spasial, serta pemantauan, evaluasi dan analisis pelaporan di bidang pengelolaan data dan sistem informasi spasial.
(2) Subbidang Pengelolaan Data dan Sistem Informasi Statistik mempunyai tugas melakukan penyiapan bahan penyusunan rencana dan program pengelolaan data statistik, pengumpulan, pengolahan, analisa dan penyajian data statistik, pengembangan metode dan standard pengelolaan basis data statistik, serta pemantauan, evaluasi dan analisis pelaporan di bidang pengelolaan data dan sistem informasi statistik.', 'Pasal 271', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3580, 'perban-4-2019', 275, 'pasal', 'Pasal 272', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 78, 'Bidang Teknologi dan Jaringan mempunyai tugas melaksanakan penyusunan, perencanaan, penelaahaan, pengembangan, pembinaan, koordinasi, pemantauan evaluasi dan pelaporan pelaksanaan teknologi informasi dan komunikasi kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3580, 'Bidang Teknologi dan Jaringan mempunyai tugas melaksanakan penyusunan, perencanaan, penelaahaan, pengembangan, pembinaan, koordinasi, pemantauan evaluasi dan pelaporan pelaksanaan teknologi informasi dan komunikasi kebencanaan.', 'Pasal 272', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3581, 'perban-4-2019', 276, 'pasal', 'Pasal 273', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 78, 'Pasal 272, Bidang Teknologi dan Jaringan menyelenggarakan fungsi:
a. koordinasi, penyiapan, penyusunan dan pelaksanaan pemuktahiran rencana strategis, arsitektur, analisis kapasitas, kebijakan dan standardisasi, pengembangan, integrasi sistem informasi dan pembinaan jabatan fungsional pranata komputer di bidang pengelolaan sistem dan teknologi;
b. koordinasi, penyiapan, penyusunan dan pelaksanaan manajemen dan operasional layanan, manajemen 2019, No. 1156 keamanan informasi, tata kelola bina kepatuhan, manajemen risiko dan pembinaan jabatan fungsional pranata komputer di bidang insfrastruktur dan jaringan; dan
c. pemantauan, evaluasi dan analisis pelaporan di bidang teknologi dan jaringan.');
