INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3583, 'perban-4-2019', 278, 'pasal', 'Pasal 275', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 79, '(1) Subbidang Pengelolaan Sistem dan Teknologi mempunyai tugas malakukan penyiapan bahan penyusunan, penelaahan, pembinaan, koordinasi, pelaksanaan pengelolaan sistem dan teknologi.
(2) Subbidang Jaringan dan Prasarana mempunyai tugas melakukan penyiapan bahan penyusunan, penelaahan, pembinaan, koordinasi, pelaksanaan pemeliharaan insfrastruktur dan jaringan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3583, '(1) Subbidang Pengelolaan Sistem dan Teknologi mempunyai tugas malakukan penyiapan bahan penyusunan, penelaahan, pembinaan, koordinasi, pelaksanaan pengelolaan sistem dan teknologi.
(2) Subbidang Jaringan dan Prasarana mempunyai tugas melakukan penyiapan bahan penyusunan, penelaahan, pembinaan, koordinasi, pelaksanaan pemeliharaan insfrastruktur dan jaringan.', 'Pasal 275', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3584, 'perban-4-2019', 279, 'pasal', 'Pasal 276', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 79, 'Bidang Komunikasi Kebencanaan mempunyai tugas mengelola dan melaksanakan komunikasi publik, pelayanan informasi, melaksanakan hubungan pers dan media, pengelolaan dokumentasi, edukasi kepada masyarakat di bidang penanggulangan bencana, pameran, serta pemantauan, evaluasi dan analisis pelaporan di bidang komunikasi kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3584, 'Bidang Komunikasi Kebencanaan mempunyai tugas mengelola dan melaksanakan komunikasi publik, pelayanan informasi, melaksanakan hubungan pers dan media, pengelolaan dokumentasi, edukasi kepada masyarakat di bidang penanggulangan bencana, pameran, serta pemantauan, evaluasi dan analisis pelaporan di bidang komunikasi kebencanaan.', 'Pasal 276', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3585, 'perban-4-2019', 280, 'pasal', 'Pasal 277', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 79, 'Pasal 276, Bidang Komunikasi Kebencanaan menyelenggarakan fungsi:
2019, No. 1156 -80-
a. penyiapan dan pelaksanaan konferensi pers, peliputan dan dokumentasi terkait kegiatan Badan Nasional Penanggulangan Bencana.
b. penyediaan dan publikasi informasi kebencanaan kepada masyarakat dalam bentuk media cetak, media elektronik, media sosial dan layanan informasi melalui perpustakaan dan diorama edukasi bencana.
c. analisis pemberitaaan media dan koordinasi hubungan komunikasi dan kerjasama terkait hubungan masyarakat dengan seluruh unit organisasi di lingkungan Badan Nasional Penanggulangan Bencana/ Kementerian/Lembaga/Pemerintah Daerah dan masyarakat serta penanganan pengaduan terkait Badan Nasional Penanggulangan Bencana;
d. penyelenggaraan pameran kebencanaan, bimbingan teknis dan edukasi budaya sadar bencana kepada pelajar, hubungan dengan media/wartawan dan masyarakat; dan
e. pemantauan, evaluasi dan analisis pelaporan di bidang komunikasi kebencanaan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3585, 'Pasal 276, Bidang Komunikasi Kebencanaan menyelenggarakan fungsi:
