INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3587, '(1) Subbidang Pemberitaan dan Publikasi Kebencanaan mempunyai tugas melaksanakan penyediaan dan publikasi, edukasi, dan layanan informasi kebencanaan kepada masyarakat dalam bentuk media cetak, media elektronik dan media sosial.
(2) Subbidang Hubungan Antar Media mempunyai tugas menyiapkan dan melaksanakan konferensi pers, peliputan, komunikasi kepada masyarakat terkait kebencanaan dan menjalin komunikasi dan kerja sama dengan media.
2019, No. 1156', 'Pasal 279', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3588, 'perban-4-2019', 283, 'pasal', 'Pasal 280', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 81, 'Subbagian Tata Usaha mempunyai tugas melakukan urusan persuratan, kearsipan, keuangan, kepegawaian, perlengkapan, perpustakaan, dan digitalisasi dokumen kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3588, 'Subbagian Tata Usaha mempunyai tugas melakukan urusan persuratan, kearsipan, keuangan, kepegawaian, perlengkapan, perpustakaan, dan digitalisasi dokumen kebencanaan.', 'Pasal 280', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3589, 'perban-4-2019', 284, 'pasal', 'Pasal 281', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 81, 'Pusat Pendidikan dan Pelatihan Penanggulangan Bencana mempunyai tugas melaksanakan pengoordinasian dan penyelenggaraan pengembangan kapasitas sumber daya manusia di bidang penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3589, 'Pusat Pendidikan dan Pelatihan Penanggulangan Bencana mempunyai tugas melaksanakan pengoordinasian dan penyelenggaraan pengembangan kapasitas sumber daya manusia di bidang penanggulangan bencana.', 'Pasal 281', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3590, 'perban-4-2019', 285, 'pasal', 'Pasal 282', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 81, 'Pasal 281, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana menyelenggarakan fungsi:
a. penyiapan koordinasi dan pelaksanaan penyelenggaraan pendidikan dan pelatihan teknis penanggulangan bencana dan simulasi penanggulangan secara nasional dan internasional;
b. pengembangan program dan akreditasi pendidikan dan pelatihan penanggulangan bencana;
c. penyiapan koordinasi penyusunan norma, standar, prosedur dan kriteria di bidang pendidikan dan pelatihan penanggulangan bencana;
d. penyelenggaraan pendidikan dan pelatihan dasar, struktural, fungsional, dan teknis lainnya bagi sumber daya manusia di bidang penanggulangan bencana;
e. penyelenggaraan sertifikasi dan uji kompetensi profesi; dan
f. penyiapan pemantauan, evaluasi dan analisis pelaporan di bidang Pendidikan dan pelatihan penanggulangan bencana.
2019, No. 1156 -82-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3590, 'Pasal 281, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana menyelenggarakan fungsi:
a. penyiapan koordinasi dan pelaksanaan penyelenggaraan pendidikan dan pelatihan teknis penanggulangan bencana dan simulasi penanggulangan secara nasional dan internasional;
