INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3591, 'Pusat Pendidikan dan Pelatihan Penanggulangan Bencana terdiri dari:
a. Bidang Program dan Evaluasi;
b. Bidang Penyelenggaraan Pendidikan dan Pelatihan;
c. Subbagian Tata Usaha; dan
d. Kelompok Jabatan Fungsional.', 'Pasal 283', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3592, 'perban-4-2019', 287, 'pasal', 'Pasal 284', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 82, 'Bidang Program dan Evaluasi mempunyai tugas mengembangkan program dan penyelenggaraan pendidikan dan pelatihan untuk pemenuhan kebutuhan sumber daya manusia di bidang penanggulangan bencana yang profesional dalam kuantitas, kualitas dan sebaran wilayah sesuai dengan karakteristik dan potensi kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3592, 'Bidang Program dan Evaluasi mempunyai tugas mengembangkan program dan penyelenggaraan pendidikan dan pelatihan untuk pemenuhan kebutuhan sumber daya manusia di bidang penanggulangan bencana yang profesional dalam kuantitas, kualitas dan sebaran wilayah sesuai dengan karakteristik dan potensi kebencanaan.', 'Pasal 284', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3593, 'perban-4-2019', 288, 'pasal', 'Pasal 285', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 82, 'Pasal 284, Bidang Program dan Evaluasi menyelenggarakan fungsi:
a. penyusunan dan pengembangan program pendidikan dan pelatihan;
b. pengembangan program akreditasi lembaga pendidikan dan pelatihan;
c. persiapan pemantauan dan evaluasi kualitas program pendidikan dan pelatihan, kualitas sumber daya manusia hasil pendidikan, kecukupan pemenuhan rasio dan sebaran sumber daya manusia penanggulangan bencana secara nasional dan anggaran dan kinerja Pusat Pendidikan dan Pelatihan Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3593, 'Pasal 284, Bidang Program dan Evaluasi menyelenggarakan fungsi:
