INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3596, 'perban-4-2019', 291, 'pasal', 'Pasal 288', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 83, 'Bidang Penyelenggaraan Pendidikan dan Pelatihan mempunyai tugas menyelenggarakan pendidikan dan pelatihan teknis penanggulangan bencana bagi aparat pemerintah dan organisasi, lembaga dan masyarakat, pendidikan dan pelatihan struktural dan fungsional, pelatihan dasar dan teknis lainnya, pendidikan dan pelatihan penanggulangan bencana internasional, dan simulasi penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3596, 'Bidang Penyelenggaraan Pendidikan dan Pelatihan mempunyai tugas menyelenggarakan pendidikan dan pelatihan teknis penanggulangan bencana bagi aparat pemerintah dan organisasi, lembaga dan masyarakat, pendidikan dan pelatihan struktural dan fungsional, pelatihan dasar dan teknis lainnya, pendidikan dan pelatihan penanggulangan bencana internasional, dan simulasi penanggulangan bencana.', 'Pasal 288', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
