INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3613, 'perban-4-2019', 308, 'pasal', 'Pasal 305', 'BAB III UNIT PELAKSANA TEKNIS', 87, 'Jabatan fungsional dapat ditetapkan di lingkungan Badan Nasional Penanggulangan Bencana sesuai dengan kebutuhan yang dilaksanakan sesuai dengan ketentuan perundang-undangan.');
