INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3615, 'perban-4-2019', 310, 'pasal', 'Pasal 307', 'BAB IV TATA KERJA', 88, 'Kepala mengendalikan pelaksanaan tugas dan fungsi unsur pengarah dan unsur pelaksana.');
