INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3616, 'perban-4-2019', 311, 'pasal', 'Pasal 308', 'BAB IV TATA KERJA', 88, 'Setiap pimpinan satuan organisasi di lingkungan unsur pelaksana wajib melaksanakan sistem pengendalian intern di lingkungan masing-masing yang memungkinkan terlaksananya mekanisme uji silang.');
