INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3617, 'perban-4-2019', 312, 'pasal', 'Pasal 309', 'BAB IV TATA KERJA', 88, 'Setiap pimpinan satuan organisasi di lingkungan Unsur Pelaksana bertanggung jawab memimpin dan mengoordinasikan bawahan masing-masing dan memberikan pengarahan serta petunjuk bagi pelaksanaan tugas bawahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3617, 'Setiap pimpinan satuan organisasi di lingkungan Unsur Pelaksana bertanggung jawab memimpin dan mengoordinasikan bawahan masing-masing dan memberikan pengarahan serta petunjuk bagi pelaksanaan tugas bawahan.', 'Pasal 309', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
