INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3620, 'perban-4-2019', 315, 'pasal', 'Pasal 312', 'BAB IV KETENTUAN LAIN-LAIN', 89, '(1) Unit organisasi yang menangani fungsi di bidang pengadaan barang/jasa pemerintah, melaksanakan tugas dan fungsi unit layanan pengadaan barang/jasa pemerintah di lingkungan Badan Nasional Penanggulangan Bencana.
