INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3622, 'perban-4-2019', 317, 'pasal', 'Pasal 314', 'BAB IV KETENTUAN LAIN-LAIN', 89, '(1) Pemimpin unit organisasi yang menangani fungsi di bidang pengelolaan dan pelayanan informasi, karena sifat tugas dan fungsinya menjadi pejabat pengelola informasi dan dokumentasi di lingkungan Badan Nasional Penanggulangan Bencana.
