INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3623, 'perban-4-2019', 318, 'pasal', 'Pasal 315', 'BAB IV KETENTUAN LAIN-LAIN', 90, 'Perubahan atas organisasi dan tata Kerja Badan Nasional Penanggulangan Bencana sebagaimana diatur dalam Peraturan Badan ini ditetapkan oleh Kepala setelah terlebih dahulu mendapat persetujuan tertulis dari Menteri yang bertanggung jawab di bidang pendayagunaan aparatur negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3623, 'Perubahan atas organisasi dan tata Kerja Badan Nasional Penanggulangan Bencana sebagaimana diatur dalam Peraturan Badan ini ditetapkan oleh Kepala setelah terlebih dahulu mendapat persetujuan tertulis dari Menteri yang bertanggung jawab di bidang pendayagunaan aparatur negara.', 'Pasal 315', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3624, 'perban-4-2019', 319, 'pasal', 'Pasal 316', 'BAB IV KETENTUAN LAIN-LAIN', 90, '(1) Untuk melaksanakan tugas dan fungsi tertentu, di lingkungan Badan Nasional Penanggulangan Bencana dapat membentuk kelompok kerja sesuai kebutuhan.
(2) Kelompok kerja sebagaimana dimaksud pada ayat (1) ditetapkan dengan keputusan Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3624, '(1) Untuk melaksanakan tugas dan fungsi tertentu, di lingkungan Badan Nasional Penanggulangan Bencana dapat membentuk kelompok kerja sesuai kebutuhan.
(2) Kelompok kerja sebagaimana dimaksud pada ayat (1) ditetapkan dengan keputusan Kepala.', 'Pasal 316', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3625, 'perban-4-2019', 320, 'pasal', 'Pasal 317', 'BAB V KETENTUAN PERALIHAN', 90, 'Bagan struktur susunan organisasi Badan Nasional Penanggulangan Bencana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3625, 'Bagan struktur susunan organisasi Badan Nasional Penanggulangan Bencana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan ini.', 'Pasal 317', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3626, 'perban-4-2019', 321, 'pasal', 'Pasal 318', 'BAB V KETENTUAN PERALIHAN', 90, 'Jabatan dan pejabat yang memangku jabatan di lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana sebagaimana telah diubah dengan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2013 tentang Perubahan Atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana, tetap melaksanakan tugas dan fungsi sampai dengan ditetapkannya jabatan dan pejabat yang 2019, No. 1156 memangku jabatan di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3626, 'Jabatan dan pejabat yang memangku jabatan di lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana sebagaimana telah diubah dengan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2013 tentang Perubahan Atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana, tetap melaksanakan tugas dan fungsi sampai dengan ditetapkannya jabatan dan pejabat yang 2019, No. 1156 memangku jabatan di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 318', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3627, 'perban-4-2019', 322, 'pasal', 'Pasal 319', 'BAB VI KETENTUAN PENUTUP', 91, 'Pada saat Peraturan Badan ini mulai berlaku, semua Peraturan Kepala Badan Nasional Penanggulangan Bencana dinyatakan tetap berlaku sepanjang tidak bertentangan dengan ketentuan dalam Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3627, 'Pada saat Peraturan Badan ini mulai berlaku, semua Peraturan Kepala Badan Nasional Penanggulangan Bencana dinyatakan tetap berlaku sepanjang tidak bertentangan dengan ketentuan dalam Peraturan Badan ini.', 'Pasal 319', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3628, 'perban-4-2019', 323, 'pasal', 'Pasal 320', 'BAB VI KETENTUAN PENUTUP', 91, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Tahun 2008 Nomor 1439) sebagaimana telah diubah dengan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2013 tentang Perubahan Atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Tahun 2013 Nomor 1441), dicabut dan dinyatakan tidak berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3628, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Tahun 2008 Nomor 1439) sebagaimana telah diubah dengan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2013 tentang Perubahan Atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Tahun 2013 Nomor 1441), dicabut dan dinyatakan tidak berlaku.', 'Pasal 320', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
