INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3632, 'perban-4-2020', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk lebih menciptakan keadilan bagi masyarakat yang terkena dampak bencana serta memberikan kepastian hukum dalam pelaksanaan penggunaan dana siap pakai guna pendanaan dan pengelolaan bantuan bencana, perlu mengganti Peraturan Badan Nasional Penanggulangan Bencana Nomor 02 Tahun 2018 tentang Penggunaan Dana Siap Pakai karena sudah tidak sesuai dengan perkembangan hukum dan kebutuhan masyarakat dalam penyelenggaraan penanggulangan bencana,
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Penggunaan Dana Siap Pakai,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3632, 'a. bahwa untuk lebih menciptakan keadilan bagi masyarakat yang terkena dampak bencana serta memberikan kepastian hukum dalam pelaksanaan penggunaan dana siap pakai guna pendanaan dan pengelolaan bantuan bencana, perlu mengganti Peraturan Badan Nasional Penanggulangan Bencana Nomor 02 Tahun 2018 tentang Penggunaan Dana Siap Pakai karena sudah tidak sesuai dengan perkembangan hukum dan kebutuhan masyarakat dalam penyelenggaraan penanggulangan bencana,
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Penggunaan Dana Siap Pakai,', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3633, 'perban-4-2020', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723):
