INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3636, 'perban-4-2020', 5, 'pasal', 'Pasal 2', 'BAB II DASAR PERSETUJUAN PEMBERIAN DANA SIAP PAKAI; Bagian Kedua Persyaratan Permohonan Bantuan Dana Siap Pakai', 5, '(1) Pemberian Bantuan DSP dalam negeri berdasarkan atas:
a. adanya penetapan Status Keadaan Darurat Bencana yang ditetapkan oleh bupati/walikota, gubernur, atau Presiden,
b. adanya penetapan Status Keadaan Tertentu: dan Cc. pertimbangan adanya risiko Bencana berdampak Tuas yang ditetapkan oleh Kepala BNPB.
(2) Dalam hal Pemerintah memberikan DSP untuk bantuan kemanusiaan ke luar negeri harus berdasarkan pernyataan resmi/arahan Presiden Republik Indonesia/Menteri Koordinator/Menteri Luar Negeri.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3636, '(1) Pemberian Bantuan DSP dalam negeri berdasarkan atas:
a. adanya penetapan Status Keadaan Darurat Bencana yang ditetapkan oleh bupati/walikota, gubernur, atau Presiden,
b. adanya penetapan Status Keadaan Tertentu: dan Cc. pertimbangan adanya risiko Bencana berdampak Tuas yang ditetapkan oleh Kepala BNPB.
(2) Dalam hal Pemerintah memberikan DSP untuk bantuan kemanusiaan ke luar negeri harus berdasarkan pernyataan resmi/arahan Presiden Republik Indonesia/Menteri Koordinator/Menteri Luar Negeri.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3637, 'perban-4-2020', 6, 'pasal', 'Pasal 3', 'BAB II DASAR PERSETUJUAN PEMBERIAN DANA SIAP PAKAI; Bagian Kedua Persyaratan Permohonan Bantuan Dana Siap Pakai', 6, 'Pemberian bantuan DSP sebagaimana dimaksud dalam Pasal 2 harus dilakukan dengan permohonan kepada Kepala BNPB.
Berdasarkan Penetapan Status Keadaan Darurat Bencana yang Ditetapkan oleh Bupati/Walikota, Gubernur, dan Presiden');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3637, 'Pemberian bantuan DSP sebagaimana dimaksud dalam Pasal 2 harus dilakukan dengan permohonan kepada Kepala BNPB.
Berdasarkan Penetapan Status Keadaan Darurat Bencana yang Ditetapkan oleh Bupati/Walikota, Gubernur, dan Presiden', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3638, 'perban-4-2020', 7, 'pasal', 'Pasal 4', 'BAB II DASAR PERSETUJUAN PEMBERIAN DANA SIAP PAKAI; Bagian Kedua Persyaratan Permohonan Bantuan Dana Siap Pakai', 6, 'Permohonan pemberian bantuan DSP yang dilakukan berdasarkan penetapan Status Keadaan Darurat Bencana oleh bupati/walikota sebagaimana dimaksud dalam Pasal 2 ayat
(1) huruf a dengan kelengkapan dokumen paling sedikit:
a. laporan ancaman atau kejadian bencana yang disampaikan oleh BPBD kabupaten/kota terdampak kepada BNPB dalam jangka waktu paling lambat 3 (tiga) hari sejak terjadinya ancaman atau kejadian Bencana atau segera setelah kondisi memungkinkan terkait dengan dampak dari Bencana,
b. adanya penetapan Status Keadaan Darurat Bencana oleh bupati/walikota yang terkena terdampak, dan Cc. surat permohonan Bantuan Penanganan Darurat Bencana yang ditandatangani oleh bupati/walikota terdampak yang ditujukan kepada Kepala BNPB sejak ditetapkannya Status Keadaan Darurat Bencana dengan lampiran dokumen sebagai berikut:
1. keputusan Bupati/Walikota tentang penetapan Status Keadaan Darurat Bencana:
2. rencana kegiatan/operasi yang memuat batas waktu penyelesaian kegiatan:
3. rincian kebutuhan anggaran biaya:
4. pengkajian kebutuhan usulan kegiatan dari instansi/lembaga teknis berwenang,
5. laporan ancaman/kejadian bencana: dan
6. keputusan pembentukan Pos Komando Penanganan Darurat Bencana oleh kepala daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3638, 'Permohonan pemberian bantuan DSP yang dilakukan berdasarkan penetapan Status Keadaan Darurat Bencana oleh bupati/walikota sebagaimana dimaksud dalam Pasal 2 ayat
(1) huruf a dengan kelengkapan dokumen paling sedikit:
a. laporan ancaman atau kejadian bencana yang disampaikan oleh BPBD kabupaten/kota terdampak kepada BNPB dalam jangka waktu paling lambat 3 (tiga) hari sejak terjadinya ancaman atau kejadian Bencana atau segera setelah kondisi memungkinkan terkait dengan dampak dari Bencana,
b. adanya penetapan Status Keadaan Darurat Bencana oleh bupati/walikota yang terkena terdampak, dan Cc. surat permohonan Bantuan Penanganan Darurat Bencana yang ditandatangani oleh bupati/walikota terdampak yang ditujukan kepada Kepala BNPB sejak ditetapkannya Status Keadaan Darurat Bencana dengan lampiran dokumen sebagai berikut:
1. keputusan Bupati/Walikota tentang penetapan Status Keadaan Darurat Bencana:
2. rencana kegiatan/operasi yang memuat batas waktu penyelesaian kegiatan:
3. rincian kebutuhan anggaran biaya:
4. pengkajian kebutuhan usulan kegiatan dari instansi/lembaga teknis berwenang,
5. laporan ancaman/kejadian bencana: dan
6. keputusan pembentukan Pos Komando Penanganan Darurat Bencana oleh kepala daerah.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3639, 'perban-4-2020', 8, 'pasal', 'Pasal 5', 'BAB II DASAR PERSETUJUAN PEMBERIAN DANA SIAP PAKAI; Bagian Kedua Persyaratan Permohonan Bantuan Dana Siap Pakai', 7, 'Permohonan Pemberian Bantuan DSP berdasarkan penetapan status keadaan darurat bencana oleh gubernur sebagaimana dimaksud dalam Pasal 2 ayat (1) huruf a dengan kelengkapan dokumen paling sedikit:
a. laporan ancaman atau kejadian bencana yang disampaikan oleh gubernur yang terkena terdampak kepada Kepala BNPB dalam jangka waktu paling lambat 3 (tiga) hari sejak terjadinya ancaman atau kejadian bencana atau segera setelah kondisi memungkinkan terkait dengan dampak dari bencana:
b. adanya penetapan Status Keadaan Darurat Bencana oleh gubernur yang terkena terdampak, dan C. surat permohonan Bantuan Penanganan Darurat Bencana yang ditandatangani oleh gubernur yang ditujukan kepada Kepala BNPB sejak ditetapkannya Status Keadaan Darurat Bencana dengan lampiran dokumen sebagai berikut:
1. Keputusan Gubernur tentang penetapan Status Keadaan Darurat Bencana,
2. Keputusan Gubernur tentang Pembentukan Pos Komando Penanganan Darurat Bencana:
3. rencana kegiatan/operasi yang memuat batas waktu penyelesaian kegiatan,
4. rincian kebutuhan anggaran biaya: dan
5. pengkajian teknis usulan kegiatan dan/atau surat rekomendasi dari instansi/ lembaga teknis berwenang');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3639, 'Permohonan Pemberian Bantuan DSP berdasarkan penetapan status keadaan darurat bencana oleh gubernur sebagaimana dimaksud dalam Pasal 2 ayat (1) huruf a dengan kelengkapan dokumen paling sedikit:
a. laporan ancaman atau kejadian bencana yang disampaikan oleh gubernur yang terkena terdampak kepada Kepala BNPB dalam jangka waktu paling lambat 3 (tiga) hari sejak terjadinya ancaman atau kejadian bencana atau segera setelah kondisi memungkinkan terkait dengan dampak dari bencana:
b. adanya penetapan Status Keadaan Darurat Bencana oleh gubernur yang terkena terdampak, dan C. surat permohonan Bantuan Penanganan Darurat Bencana yang ditandatangani oleh gubernur yang ditujukan kepada Kepala BNPB sejak ditetapkannya Status Keadaan Darurat Bencana dengan lampiran dokumen sebagai berikut:
1. Keputusan Gubernur tentang penetapan Status Keadaan Darurat Bencana,
2. Keputusan Gubernur tentang Pembentukan Pos Komando Penanganan Darurat Bencana:
3. rencana kegiatan/operasi yang memuat batas waktu penyelesaian kegiatan,
4. rincian kebutuhan anggaran biaya: dan
5. pengkajian teknis usulan kegiatan dan/atau surat rekomendasi dari instansi/ lembaga teknis berwenang', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3640, 'perban-4-2020', 9, 'pasal', 'Pasal 6', 'BAB II DASAR PERSETUJUAN PEMBERIAN DANA SIAP PAKAI; Bagian Kedua Persyaratan Permohonan Bantuan Dana Siap Pakai', 8, 'Permohonan Pemberian Bantuan DSP berdasarkan penetapan status keadaan darurat bencana oleh Presiden sebagaimana dimaksud dalam Pasal 2 ayat (1) huruf a dapat dilakukan oleh gubernur atau kementerian/lembaga dengan kelengkapan dokumen paling sedikit:
a. adanya laporan ancaman atau kejadian bencana yang disampaikan oleh BNPB yang terkena terdampak kepada Presiden Republik Indonesia dalam jangka waktu paling lambat 3 (tiga) hari sejak terjadinya ancaman atau kejadian bencana atau segera setelah kondisi memungkinkan terkait dengan dampak dari bencana,
b. adanya penetapan Status Keadaan Darurat Bencana oleh Presiden Republik Indonesia daerah yang terkena terdampak bencana, dan Cc. surat permohonan Bantuan Penanganan Darurat Bencana yang ditandatangani oleh gubernur/kementerian/lembaga yang ditujukan kepada Kepala BNPB sejak ditetapkannya Status Keadaan Darurat Bencana dengan lampiran dokumen sebagai berikut:
1. Keputusan Presiden Republik Indonesia tentang penetapan Status Keadaan Darurat Bencana:
2. Keputusan BNPB tentang Pembentukan Pos Komando Nasional Penanganan Darurat Bencana,
3. rencana kegiatan/operasi yang memuat batas waktu penyelesaian kegiatan:
4. rincian kebutuhan anggaran biaya, dan
5. pengkajian teknis usulan kegiatan dan/atau surat rekomendasi dari instansi/lembaga teknis berwenang Status Keadaan Tertentu');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3640, 'Permohonan Pemberian Bantuan DSP berdasarkan penetapan status keadaan darurat bencana oleh Presiden sebagaimana dimaksud dalam Pasal 2 ayat (1) huruf a dapat dilakukan oleh gubernur atau kementerian/lembaga dengan kelengkapan dokumen paling sedikit:
a. adanya laporan ancaman atau kejadian bencana yang disampaikan oleh BNPB yang terkena terdampak kepada Presiden Republik Indonesia dalam jangka waktu paling lambat 3 (tiga) hari sejak terjadinya ancaman atau kejadian bencana atau segera setelah kondisi memungkinkan terkait dengan dampak dari bencana,
b. adanya penetapan Status Keadaan Darurat Bencana oleh Presiden Republik Indonesia daerah yang terkena terdampak bencana, dan Cc. surat permohonan Bantuan Penanganan Darurat Bencana yang ditandatangani oleh gubernur/kementerian/lembaga yang ditujukan kepada Kepala BNPB sejak ditetapkannya Status Keadaan Darurat Bencana dengan lampiran dokumen sebagai berikut:
1. Keputusan Presiden Republik Indonesia tentang penetapan Status Keadaan Darurat Bencana:
2. Keputusan BNPB tentang Pembentukan Pos Komando Nasional Penanganan Darurat Bencana,
3. rencana kegiatan/operasi yang memuat batas waktu penyelesaian kegiatan:
4. rincian kebutuhan anggaran biaya, dan
5. pengkajian teknis usulan kegiatan dan/atau surat rekomendasi dari instansi/lembaga teknis berwenang Status Keadaan Tertentu', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3641, 'perban-4-2020', 10, 'pasal', 'Pasal 7', 'BAB II DASAR PERSETUJUAN PEMBERIAN DANA SIAP PAKAI; Bagian Kedua Persyaratan Permohonan Bantuan Dana Siap Pakai', 9, '(1) Permohonan DSP berdasarkan penetapan status keadaan tertentu sebagaimana dimaksud dalam Pasal 2 ayat (1) huruf b dilaksanakan dengan ketentuan:
a. telah diterima informasi dan rekomendasi peringatan dini/ status ancaman bencana dari kementerian/lembaga yang berwenang secara teknis dan telah dilakukan kaji cepat oleh BNPB/BPBD daerah dengan melibatkan instansi terkait sesuai kewenangannya dengan memperhitungkan kemampuan sumber daya daerah terdampak:
b. pelaksanaan rapat koordinasi untuk menetapkan Status Keadaan Tertentu atas inisiatif BNPB: dan C. penentuan Status Keadaan Tertentu, berdasarkan:
1. keputusan yang diambil pada rapat koordinasi: dan
2. penetapan keputusan status keadaan tertentu Kepala BNPB berdasarkan keputusan hasil rapat yang memuat waktu dimulai dan diakhirinya Status Keadaan Tertentu.
Pertimbangan Adanya Risiko Bencana Berdampak Luas Yang Ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3641, '(1) Permohonan DSP berdasarkan penetapan status keadaan tertentu sebagaimana dimaksud dalam Pasal 2 ayat (1) huruf b dilaksanakan dengan ketentuan:
a. telah diterima informasi dan rekomendasi peringatan dini/ status ancaman bencana dari kementerian/lembaga yang berwenang secara teknis dan telah dilakukan kaji cepat oleh BNPB/BPBD daerah dengan melibatkan instansi terkait sesuai kewenangannya dengan memperhitungkan kemampuan sumber daya daerah terdampak:
b. pelaksanaan rapat koordinasi untuk menetapkan Status Keadaan Tertentu atas inisiatif BNPB: dan C. penentuan Status Keadaan Tertentu, berdasarkan:
1. keputusan yang diambil pada rapat koordinasi: dan
2. penetapan keputusan status keadaan tertentu Kepala BNPB berdasarkan keputusan hasil rapat yang memuat waktu dimulai dan diakhirinya Status Keadaan Tertentu.
Pertimbangan Adanya Risiko Bencana Berdampak Luas Yang Ditetapkan oleh Kepala BNPB.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3642, 'perban-4-2020', 11, 'pasal', 'Pasal 8', 'BAB II DASAR PERSETUJUAN PEMBERIAN DANA SIAP PAKAI; Bagian Kedua Persyaratan Permohonan Bantuan Dana Siap Pakai', 9, 'Permohonan DSP berdasarkan pertimbangan adanya risiko Bencana berdampak luas yang ditetapkan oleh Kepala BNPB sebagaimana dimaksud dalam Pasal 2 ayat (1) huruf c paling sedikit dilengkapi dengan:
a. rekomendasi dari Deputi terkait yang menjelaskan analisis risiko, potensi luasan dampak serta kebutuhan dan rincian biaya untuk kegiatan penanggulangan bencana,
b. persetujuan pemberian bantuan DSP dari Kepala BNPB atau dapat didelegasikan kepada KPA melalui keputusan: dan Cc. Kepala BNPB mengeluarkan surat keputusan penetapan lokasi dan kegiatan yang dapat dibiayai dengan DSP sebagaimana dimaksud pada huruf b.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3642, 'Permohonan DSP berdasarkan pertimbangan adanya risiko Bencana berdampak luas yang ditetapkan oleh Kepala BNPB sebagaimana dimaksud dalam Pasal 2 ayat (1) huruf c paling sedikit dilengkapi dengan:
a. rekomendasi dari Deputi terkait yang menjelaskan analisis risiko, potensi luasan dampak serta kebutuhan dan rincian biaya untuk kegiatan penanggulangan bencana,
b. persetujuan pemberian bantuan DSP dari Kepala BNPB atau dapat didelegasikan kepada KPA melalui keputusan: dan Cc. Kepala BNPB mengeluarkan surat keputusan penetapan lokasi dan kegiatan yang dapat dibiayai dengan DSP sebagaimana dimaksud pada huruf b.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3643, 'perban-4-2020', 12, 'pasal', 'Pasal 9', 'BAB II DASAR PERSETUJUAN PEMBERIAN DANA SIAP PAKAI; Bagian Ketiga Prosedur Verifikasi Dana Siap Pakai', 10, '(1) Permohonan bantuan DSP dari kementerian/lembaga paling sedikit dilengkapi dengan:
a. penetapan status keadaan darurat atau keadaan tertentu atau pertimbangan adanya risiko bencana berdampak luas yang ditetapkan oleh Kepala BNPB: dan
b. surat permohonan bantuan DSP ditandatangani oleh sekretaris jenderal/sekretaris utama atau pejabat setingkat eselon I kementerian/lembaga/Tentara Nasional Indonesia/Kepolisian Negara Republik Indonesia ditujukan kepada Kepala BNPB dengan melampirkan sebagai berikut:
1. rencana kegiatan/operasi yang mengenai batas waktu penyelesaian,
2. rincian kebutuhan anggaran biaya, dan
3. kajian teknis usulan kegiatan.
(2) Permohonan bantuan DSP dari Unit Kerja di Lingkungan BNPB berdasarkan atas:
a. penetapan Status Keadaan Darurat Bencana atau Status Keadaan Tertentu atau Pertimbangan Adanya Risiko Bencana Berdampak Luas yang Ditetapkan oleh Kepala BNPB: dan
b. surat permohonan bantuan DSP ditandatangani oleh pejabat eselon I/kepala pusat terkait yang ditujukan kepada Kepala BNPB dengan melampirkan:
1. kajian teknis usulan kegiatan dan/atau kerangka acuan kerja, dan
2. rincian kebutuhan anggaran biaya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3643, '(1) Permohonan bantuan DSP dari kementerian/lembaga paling sedikit dilengkapi dengan:
a. penetapan status keadaan darurat atau keadaan tertentu atau pertimbangan adanya risiko bencana berdampak luas yang ditetapkan oleh Kepala BNPB: dan
b. surat permohonan bantuan DSP ditandatangani oleh sekretaris jenderal/sekretaris utama atau pejabat setingkat eselon I kementerian/lembaga/Tentara Nasional Indonesia/Kepolisian Negara Republik Indonesia ditujukan kepada Kepala BNPB dengan melampirkan sebagai berikut:
1. rencana kegiatan/operasi yang mengenai batas waktu penyelesaian,
2. rincian kebutuhan anggaran biaya, dan
3. kajian teknis usulan kegiatan.
(2) Permohonan bantuan DSP dari Unit Kerja di Lingkungan BNPB berdasarkan atas:
a. penetapan Status Keadaan Darurat Bencana atau Status Keadaan Tertentu atau Pertimbangan Adanya Risiko Bencana Berdampak Luas yang Ditetapkan oleh Kepala BNPB: dan
b. surat permohonan bantuan DSP ditandatangani oleh pejabat eselon I/kepala pusat terkait yang ditujukan kepada Kepala BNPB dengan melampirkan:
1. kajian teknis usulan kegiatan dan/atau kerangka acuan kerja, dan
2. rincian kebutuhan anggaran biaya.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3644, 'perban-4-2020', 13, 'pasal', 'Pasal 10', 'BAB III KEGIATAN YANG DAPAT DIBIAYAI DANA SIAP PAKAI; Bagian Kesatu Umum', 11, '(1) Permohonan pemberian bantuan DSP harus dilakukan dilakukan verifikasi.
(2) Pemberian DSP sebagaimana dimaksud pada ayat (1) berdasarkan persetujuan Kepala BNPB atau pejabat yang diberi kuasa oleh Kepala BNPB melalui keputusan.
(3) Ketentuan lebih lanjut mengenai verifikasi sebagaimana dimaksud pada ayat (1) ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3644, '(1) Permohonan pemberian bantuan DSP harus dilakukan dilakukan verifikasi.
(2) Pemberian DSP sebagaimana dimaksud pada ayat (1) berdasarkan persetujuan Kepala BNPB atau pejabat yang diberi kuasa oleh Kepala BNPB melalui keputusan.
(3) Ketentuan lebih lanjut mengenai verifikasi sebagaimana dimaksud pada ayat (1) ditetapkan oleh Kepala BNPB.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3645, 'perban-4-2020', 14, 'pasal', 'Pasal 11', 'BAB III KEGIATAN YANG DAPAT DIBIAYAI DANA SIAP PAKAI; Bagian Kedua Bantuan Ke Luar Negeri', 11, 'Kegiatan yang dapat dibiayai dengan DSP akan ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3645, 'Kegiatan yang dapat dibiayai dengan DSP akan ditetapkan oleh Kepala BNPB.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3646, 'perban-4-2020', 15, 'pasal', 'Pasal 12', 'BAB IV PENGELOLA DAN PENGGUNA DANA SIAP PAKAI; Bagian Kesatu Pengelola', 11, '(1) Pemberian bantuan kemanusiaan ke luar negeri dengan DSP sebagaimana dimaksud dalam Pasal 2 ayat (2) terdiri atas:
a. pengadaan barang/jasa:
b. mobilisasi personil: dan/atau
c. dana.
(2) Pemberian bantuan kemanusiaan ke luar negeri dengan DSP sebagaimana dimaksud pada ayat (1) dilakukan sesuai situasi dan kondisi.
(1) (2)
(3) (4)
(1)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3646, '(1) Pemberian bantuan kemanusiaan ke luar negeri dengan DSP sebagaimana dimaksud dalam Pasal 2 ayat (2) terdiri atas:
a. pengadaan barang/jasa:
b. mobilisasi personil: dan/atau
c. dana.
(2) Pemberian bantuan kemanusiaan ke luar negeri dengan DSP sebagaimana dimaksud pada ayat (1) dilakukan sesuai situasi dan kondisi.
(1) (2)
(3) (4)
(1)', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3647, 'perban-4-2020', 16, 'pasal', 'Pasal 13', 'BAB IV PENGELOLA DAN PENGGUNA DANA SIAP PAKAI; Bagian Kedua Pengguna Dana Siap Pakai', 12, 'Pengelola DSP terdiri atas PPK dan BPP berdasarkan usulan unit kerja BNPB, BPBD kabupaten/kota, BPBD provinsi dan/atau kementerian/lembaga yang ditetapkan oleh KPA BNPB.
PPK dan BPP sebagaimana dimaksud pada ayat (1) merupakan pejabat/ pegawai berasal dari BNPB/ BPBD provinsi / kabupaten/kota dan/atau kementerian/lembaga.
KPA bertanggung jawab secara formal dan material atas pelaksanaan kegiatan dan penggunaan anggaran yang berada dalam penguasannya.
Untuk pelaksanaan kegiatan sebagaimana dimaksud pada ayat (3) yang sudah diserahterimakan dengan perjanjian kerja sama ke penerima, sepenuhnya baik fisik maupun keuangannya menjadi tanggung jawab penerima DSP.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3647, 'Pengelola DSP terdiri atas PPK dan BPP berdasarkan usulan unit kerja BNPB, BPBD kabupaten/kota, BPBD provinsi dan/atau kementerian/lembaga yang ditetapkan oleh KPA BNPB.
PPK dan BPP sebagaimana dimaksud pada ayat (1) merupakan pejabat/ pegawai berasal dari BNPB/ BPBD provinsi / kabupaten/kota dan/atau kementerian/lembaga.
KPA bertanggung jawab secara formal dan material atas pelaksanaan kegiatan dan penggunaan anggaran yang berada dalam penguasannya.
Untuk pelaksanaan kegiatan sebagaimana dimaksud pada ayat (3) yang sudah diserahterimakan dengan perjanjian kerja sama ke penerima, sepenuhnya baik fisik maupun keuangannya menjadi tanggung jawab penerima DSP.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3648, 'perban-4-2020', 17, 'pasal', 'Pasal 14', 'BAB V PENYALURAN DAN PENGEMBALIAN DANA SIAP PAKAI; Bagian Kesatu Prosedur Penyaluran Dana Siap Pakai', 12, 'Pengguna DSP terdiri atas:
a. BNPB:
b. kementerian/lembaga,
c. Tentara Nasional Indonesia/Kepolisian Negara Republik Indonesia,
d. pemerintah provinsi:
e. pemerintah daerah kabupaten/kota,
f. lembaga/ organisasi kemanusiaan atas persetujuan Kepala BNPB.
Lipa
(2) Pengguna DSP sebagaimana dimaksud pada ayat (1) huruf a meliputi unit kerja BNPB.
(3) Pengguna DSP sebagaimana dimaksud pada ayat (1) huruf b meliputi kementerian/lembaga pemerintah dan lembaga nonpemerintah yang telah terdaftar dan ditetapkan oleh Pemerintah.
(4) Pengguna DSP sebagaimana dimaksud pada ayat (1) huruf d meliputi BPBD provinsi, perangkat daerah provinsi dan lembaga nonpemerintah yang telah terdaftar dan ditetapkan oleh Pemerintah dan/atau pemerintah daerah.
(5) Pengguna DSP sebagaimana dimaksud pada ayat (1) huruf e meliputi BPBD kabupaten/kota, perangkat daerah kabupaten/kota, dan lembaga nonpemerintah yang telah terdaftar dan ditetapkan oleh Pemerintah dan/atau pemerintah daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3648, 'Pengguna DSP terdiri atas:
a. BNPB:
b. kementerian/lembaga,
c. Tentara Nasional Indonesia/Kepolisian Negara Republik Indonesia,
d. pemerintah provinsi:
e. pemerintah daerah kabupaten/kota,
f. lembaga/ organisasi kemanusiaan atas persetujuan Kepala BNPB.
Lipa
(2) Pengguna DSP sebagaimana dimaksud pada ayat (1) huruf a meliputi unit kerja BNPB.
(3) Pengguna DSP sebagaimana dimaksud pada ayat (1) huruf b meliputi kementerian/lembaga pemerintah dan lembaga nonpemerintah yang telah terdaftar dan ditetapkan oleh Pemerintah.
(4) Pengguna DSP sebagaimana dimaksud pada ayat (1) huruf d meliputi BPBD provinsi, perangkat daerah provinsi dan lembaga nonpemerintah yang telah terdaftar dan ditetapkan oleh Pemerintah dan/atau pemerintah daerah.
(5) Pengguna DSP sebagaimana dimaksud pada ayat (1) huruf e meliputi BPBD kabupaten/kota, perangkat daerah kabupaten/kota, dan lembaga nonpemerintah yang telah terdaftar dan ditetapkan oleh Pemerintah dan/atau pemerintah daerah.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3649, 'perban-4-2020', 18, 'pasal', 'Pasal 15', 'BAB V PENYALURAN DAN PENGEMBALIAN DANA SIAP PAKAI; Bagian Kesatu Prosedur Penyaluran Dana Siap Pakai', 13, '(1) Persetujuan pemberian bantuan DSP dapat dilakukan berdasarkan:
a. verifikasi terhadap permohonan bantuan:
b. rapat koordinasi kementerian/lembaga: dan
c. pertimbangan adanya risiko Bencana berdampak luas yang ditetapkan oleh Kepala BNPB.
(2) DSP dapat disalurkan ke pengguna melalui pengelola setelah mendapat persetujuan dari Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3649, '(1) Persetujuan pemberian bantuan DSP dapat dilakukan berdasarkan:
a. verifikasi terhadap permohonan bantuan:
b. rapat koordinasi kementerian/lembaga: dan
c. pertimbangan adanya risiko Bencana berdampak luas yang ditetapkan oleh Kepala BNPB.
(2) DSP dapat disalurkan ke pengguna melalui pengelola setelah mendapat persetujuan dari Kepala BNPB.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3650, 'perban-4-2020', 19, 'pasal', 'Pasal 16', 'BAB V PENYALURAN DAN PENGEMBALIAN DANA SIAP PAKAI; Bagian Kedua Pembentukan Tim Verifikasi Dana Siap Pakai', 13, 'Pengelola DSP sebagaimana dimaksud dalam Pasal 13 melaksanakan penyaluran melalui rekening khusus DSP sesuai dengan ketentuan peraturan perundang-undangan mengenai mekanisme pelaksanaan anggaran penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3650, 'Pengelola DSP sebagaimana dimaksud dalam Pasal 13 melaksanakan penyaluran melalui rekening khusus DSP sesuai dengan ketentuan peraturan perundang-undangan mengenai mekanisme pelaksanaan anggaran penanggulangan bencana.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3651, 'perban-4-2020', 20, 'pasal', 'Pasal 17', 'BAB V PENYALURAN DAN PENGEMBALIAN DANA SIAP PAKAI; Bagian Ketiga Pelaksanaan Penyaluran Dana Siap Pakai', 14, '(1) Deputi/kepala pusat terkait menunjuk tim verifikasi pemberian bantuan DSP.
(2) Hasil dari tim verifikasi sebagaimana dimaksud pada ayat
(1) menjadi bahan pertimbangan dalam pemberian DSP.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3651, '(1) Deputi/kepala pusat terkait menunjuk tim verifikasi pemberian bantuan DSP.
(2) Hasil dari tim verifikasi sebagaimana dimaksud pada ayat
(1) menjadi bahan pertimbangan dalam pemberian DSP.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3652, 'perban-4-2020', 21, 'pasal', 'Pasal 18', 'BAB V PENYALURAN DAN PENGEMBALIAN DANA SIAP PAKAI; Bagian Keempat Pengembalian Dana Siap Pakai', 14, '(1) KPA BNPB memerintahkan bendahara pengeluaran untuk memindahbukukan sejumlah dana UP dari rekening bendahara pengeluaran ke rekening BPP pengelola pada unit kerja di BNPB/BPBD dan/atau kementerian/lembaga terkait.
(2) Pemindahbukuan DSP kepada unit kerja BNPB/ BPBD atau kementerian/lembaga terkait dilaksanakan sesuai dengan jumlah yang telah disetujui KPA.
(3) Penyaluran Bantuan DSP untuk BPBD kabupaten/kota atau provinsi harus dilengkapi dengan Perjanjian Kerja Sama antara KPA BNPB dengan Kepala BPBD/Kepala Pelaksana BPBD atas nama pemerintah daerah.
(4) Penyaluran Bantuan DSP untuk kementerian/lembaga harus dilengkapi dengan Perjanjian Kerja Sama antara KPA BNPB dengan pejabat setingkat eselon I dari kementerian/lembaga terkait, kecuali bagi Tentara Nasional Indonesia/Kepolisian Negara Republik Indonesia dilakukan oleh komandan tertinggi di provinsi/ kabupaten/kota daerah terdampak.
(S) Penyaluran Bantuan DSP dapat diserahkan secara langsung kepada pemerintah kabupaten/kota atau provinsi melalui pengelola DSP BPBD setempat dilengkapi dengan bukti penerimaan berupa kuitansi, berita acara serah terima.
(6) Penyaluran Bantuan DSP dapat diserahkan secara langsung kepada unit kerja BNPB dan kementerian/lembaga terkait melalui pengelola DSP yang ditunjuk dilengkapi dengan bukti penerimaan berupa kuitansi dan berita acara serah terima.
(7) Waktu penyaluran Bantuan DSP disesuaikan dengan ketersediaan UP DSP yang ada pada rekening bendahara pengeluaran BNPB.
(8) Penyaluran bantuan DSP dapat pula diberikan dalam bentuk barang/jasa dengan mempertimbangkan aspek kemudahan, ketersediaan dan kelancaran distribusi.
(9) Pelaksanaan penyaluran dana siap pakai dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan mengenai mekanisme pelaksanaan anggaran penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3652, '(1) KPA BNPB memerintahkan bendahara pengeluaran untuk memindahbukukan sejumlah dana UP dari rekening bendahara pengeluaran ke rekening BPP pengelola pada unit kerja di BNPB/BPBD dan/atau kementerian/lembaga terkait.
(2) Pemindahbukuan DSP kepada unit kerja BNPB/ BPBD atau kementerian/lembaga terkait dilaksanakan sesuai dengan jumlah yang telah disetujui KPA.
(3) Penyaluran Bantuan DSP untuk BPBD kabupaten/kota atau provinsi harus dilengkapi dengan Perjanjian Kerja Sama antara KPA BNPB dengan Kepala BPBD/Kepala Pelaksana BPBD atas nama pemerintah daerah.
(4) Penyaluran Bantuan DSP untuk kementerian/lembaga harus dilengkapi dengan Perjanjian Kerja Sama antara KPA BNPB dengan pejabat setingkat eselon I dari kementerian/lembaga terkait, kecuali bagi Tentara Nasional Indonesia/Kepolisian Negara Republik Indonesia dilakukan oleh komandan tertinggi di provinsi/ kabupaten/kota daerah terdampak.
(S) Penyaluran Bantuan DSP dapat diserahkan secara langsung kepada pemerintah kabupaten/kota atau provinsi melalui pengelola DSP BPBD setempat dilengkapi dengan bukti penerimaan berupa kuitansi, berita acara serah terima.
(6) Penyaluran Bantuan DSP dapat diserahkan secara langsung kepada unit kerja BNPB dan kementerian/lembaga terkait melalui pengelola DSP yang ditunjuk dilengkapi dengan bukti penerimaan berupa kuitansi dan berita acara serah terima.
(7) Waktu penyaluran Bantuan DSP disesuaikan dengan ketersediaan UP DSP yang ada pada rekening bendahara pengeluaran BNPB.
(8) Penyaluran bantuan DSP dapat pula diberikan dalam bentuk barang/jasa dengan mempertimbangkan aspek kemudahan, ketersediaan dan kelancaran distribusi.
(9) Pelaksanaan penyaluran dana siap pakai dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan mengenai mekanisme pelaksanaan anggaran penanggulangan bencana.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3653, 'perban-4-2020', 22, 'pasal', 'Pasal 19', 'BAB VI MASA PENGGUNAAN DANA SIAP PAKAI; Bagian Kesatu Penggunaan Dana Siap Pakai', 15, '(1) Jika terdapat sisa DSP maka BPP BNPB/BPBD atau kementerian/lembaga terkait wajib mengembalikan DSP tersebut ke Kas Negara.
(2) Bukti pengembalian DSP ke Kas Negara sebagaimana dimaksud pada ayat (1) disampaikan kepada BNPB melalui Kepala Biro Keuangan dengan tembusan kepada Deputi/kepala pusat terkait dalam waktu paling lambat pada tanggal 5 (lima) di bulan berikutnya.
(3) Pengembalian sisa DSP dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan mengenai mekanisme pelaksanaan anggaran penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3653, '(1) Jika terdapat sisa DSP maka BPP BNPB/BPBD atau kementerian/lembaga terkait wajib mengembalikan DSP tersebut ke Kas Negara.
(2) Bukti pengembalian DSP ke Kas Negara sebagaimana dimaksud pada ayat (1) disampaikan kepada BNPB melalui Kepala Biro Keuangan dengan tembusan kepada Deputi/kepala pusat terkait dalam waktu paling lambat pada tanggal 5 (lima) di bulan berikutnya.
(3) Pengembalian sisa DSP dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan mengenai mekanisme pelaksanaan anggaran penanggulangan bencana.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3654, 'perban-4-2020', 23, 'pasal', 'Pasal 20', 'BAB VI MASA PENGGUNAAN DANA SIAP PAKAI; Bagian Kedua Waktu Penyelesaian Pertanggungjawaban Dana Siap Pakai', 16, '(1) DSP digunakan selama masa keadaan darurat bencana, keadaan tertentu, dan pertimbangan adanya risiko Bencana berdampak luas yang ditetapkan oleh Kepala BNPB.
(2) Dalam hal kegiatan masa keadaan darurat bencana, keadaan tertentu, dan pertimbangan adanya risiko Bencana berdampak luas yang ditetapkan oleh Kepala BNPB telah mendapat persetujuan dari Kepala BNPB akan dibiayai dengan DSP, namun anggaran DSP baru tersedia setelah kegiatan selesai, maka pembayaran kegiatan tersebut dapat dilaksanakan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3654, '(1) DSP digunakan selama masa keadaan darurat bencana, keadaan tertentu, dan pertimbangan adanya risiko Bencana berdampak luas yang ditetapkan oleh Kepala BNPB.
(2) Dalam hal kegiatan masa keadaan darurat bencana, keadaan tertentu, dan pertimbangan adanya risiko Bencana berdampak luas yang ditetapkan oleh Kepala BNPB telah mendapat persetujuan dari Kepala BNPB akan dibiayai dengan DSP, namun anggaran DSP baru tersedia setelah kegiatan selesai, maka pembayaran kegiatan tersebut dapat dilaksanakan.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3655, 'perban-4-2020', 24, 'pasal', 'Pasal 21', 'BAB VII MONITORING, EVALUASI, DAN PELAPORAN; Bagian Kesatu Monitoring dan Evaluasi', 16, '(1) Laporan perkembangan pelaksanaan penggunaan DSP disampaikan paling lambat setiap tanggal 5 (lima) bulan berikutnya terhitung sejak BPP BNPB/BPBD dan/atau kementerian/lembaga menerima pemindahbukuan dari bendahara pengeluaran BNPB.
(2) Penyelesaian pertanggungjawaban Bantuan DSP oleh pengguna paling lambat 3 (tiga) bulan setelah masa status keadaan darurat bencana berakhir, dengan melampirkan bukti sebagai berikut:
a. Surat keputusan penetapan status keadaan darurat bencana:
b. kuitansi dan berita acara penyerahan bantuan:
Cc. perjanjian kerja sama,
d. surat penunjukan pengelola DSP:
Cc. rencana anggaran biaya disetujui oleh BNPB,
f. laporan hasil pendampingan instansi/unit kerja bidang pengawasan:
g. rekapitulasi penggunaan DSP:
h. laporan pertanggungjawaban keuangan:
i. bukti penyaluran bantuan yang diketahui oleh pejabat setempat, J- bukti transaksi pengadaan peralatan dan logistik:
k. bukti sewa kendaraan pengiriman bantuan termasuk personil,
l. bukti pengepakan dan pengiriman bantuan ke lokasi bencana,
m. surat keputusan penunjukan,
n. perjanjian kontrak untuk pengadaan barang/jasa/Surat Perintah Kerja (SPK):
o. berita acara pemeriksaan dan penerimaan barang/jasa:
p. berita acara serah terima/berita acara penyelesaian pekerjaan: g- bukti setor pajak,
r. laporan pelaksanaan kegiatan: dan Ss. dokumentasi pelaksanaan kegiatan berupa notulensi dan foto kegiatan berdasarkan tingkat kemajuan fisik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3655, '(1) Laporan perkembangan pelaksanaan penggunaan DSP disampaikan paling lambat setiap tanggal 5 (lima) bulan berikutnya terhitung sejak BPP BNPB/BPBD dan/atau kementerian/lembaga menerima pemindahbukuan dari bendahara pengeluaran BNPB.
(2) Penyelesaian pertanggungjawaban Bantuan DSP oleh pengguna paling lambat 3 (tiga) bulan setelah masa status keadaan darurat bencana berakhir, dengan melampirkan bukti sebagai berikut:
