WIDODO EKATJAHJANA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2020 NOMOR 482');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3663, 'Ditetapkan di Jakarta pada tanggal 15 Mei 2020 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
DONI MONARDO Diundangkan di Jakarta pada tanggal 15 Mei 2020 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA ttd.
WIDODO EKATJAHJANA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2020 NOMOR 482', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3664, 'perban-4-2020', 33, 'lampiran', 'Lampiran hal. 21', NULL, 21, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Zahermann Muabezi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3664, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, Zahermann Muabezi', 'Lampiran hal. 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2020 tentang Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3665, 'perban-4-2022', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3665, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3666, 'perban-4-2022', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk meningkatkan kesiapsiagaan menghadapi bencana diperlukan pelaksanaan peringatan dini bencana secara terkoordinasi dan terpadu,
b. bahwa untuk melaksanakan peringatan dini bencana sebagaimana dimaksud dalam huruf a, diperlukan tata cara pelaksanaan peringatan dini bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3666, 'a. bahwa untuk meningkatkan kesiapsiagaan menghadapi bencana diperlukan pelaksanaan peringatan dini bencana secara terkoordinasi dan terpadu,
b. bahwa untuk melaksanakan peringatan dini bencana sebagaimana dimaksud dalam huruf a, diperlukan tata cara pelaksanaan peringatan dini bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah:', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3667, 'perban-4-2022', 2, 'mengingat', 'Mengingat', NULL, 1, 'Cc. berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah,
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461),');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3667, 'Cc. berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah,
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461),', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3668, 'perban-4-2022', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PELAKSANAAN PERINGATAN DINI BENCANA PADA BADAN NASIONAL PENANGGULANGAN BENCANA DAN BADAN PENANGGULANGAN BENCANA DAERAH.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3668, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PELAKSANAAN PERINGATAN DINI BENCANA PADA BADAN NASIONAL PENANGGULANGAN BENCANA DAN BADAN PENANGGULANGAN BENCANA DAERAH.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3669, 'perban-4-2022', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Peringatan Dini Bencana adalah serangkaian kegiatan pemberian peringatan sesegera mungkin kepada masyarakat tentang kemungkinan terjadinya bencana pada suatu tempat yang dilaksanakan oleh Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah.
2. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan.
3. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3669, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Peringatan Dini Bencana adalah serangkaian kegiatan pemberian peringatan sesegera mungkin kepada masyarakat tentang kemungkinan terjadinya bencana pada suatu tempat yang dilaksanakan oleh Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah.
2. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan.
3. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3670, 'perban-4-2022', 5, 'pasal', 'Pasal 2', 'BAB II PELAKSANAAN PERINGATAN DINI BENCANA', 3, 'Peringatan Dini Bencana bertujuan untuk:
a. meningkatkan perlindungan masyarakat dari berbagai ancaman bencana melalui pemberian Peringatan Dini Bencana yang cepat, efektif, dan bertanggung jawab, dan
b. menjamin terwujudnya pengurangan risiko bencana bagi masyarakat melalui pengambilan tindakan yang cepat dan tepat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3670, 'Peringatan Dini Bencana bertujuan untuk:
a. meningkatkan perlindungan masyarakat dari berbagai ancaman bencana melalui pemberian Peringatan Dini Bencana yang cepat, efektif, dan bertanggung jawab, dan
b. menjamin terwujudnya pengurangan risiko bencana bagi masyarakat melalui pengambilan tindakan yang cepat dan tepat.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3671, 'perban-4-2022', 6, 'pasal', 'Pasal 3', 'BAB II PELAKSANAAN PERINGATAN DINI BENCANA', 3, '(1) Peringatan Dini Bencana dilaksanakan melalui:
a. pengamatan gejala bencana,
b. analisa data hasil pengamatan,
c. pengambilan keputusan berdasarkan hasil analisa,
d. penyebarluasan hasil keputusan, dan
e. pengambilan tindakan oleh masyarakat.
(2) Dalam melaksanakan Peringatan Dini Bencana sebagaimana dimaksud pada ayat (1) diperlukan pemahaman pengetahuan mengenai risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3671, '(1) Peringatan Dini Bencana dilaksanakan melalui:
a. pengamatan gejala bencana,
b. analisa data hasil pengamatan,
c. pengambilan keputusan berdasarkan hasil analisa,
d. penyebarluasan hasil keputusan, dan
e. pengambilan tindakan oleh masyarakat.
(2) Dalam melaksanakan Peringatan Dini Bencana sebagaimana dimaksud pada ayat (1) diperlukan pemahaman pengetahuan mengenai risiko bencana.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3672, 'perban-4-2022', 7, 'pasal', 'Pasal 4', 'BAB II PELAKSANAAN PERINGATAN DINI BENCANA', 4, '(1) Pengamatan gejala bencana dan analisa data hasil pengamatan sebagaimana dimaksud dalam Pasal 3 ayat
(1) huruf a dan huruf b dilaksanakan oleh kementerian/lembaga sesuai dengan ketentuan peraturan perundang-undangan.
(2) Dalam rangka mendukung pelaksanaan pengamatan gejala bencana dan analisa data hasil pengamatan sebagaimana dimaksud pada ayat (1), BNPB/BPBD dapat melaksanakan tindakan pemantauan langsung.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3672, '(1) Pengamatan gejala bencana dan analisa data hasil pengamatan sebagaimana dimaksud dalam Pasal 3 ayat
(1) huruf a dan huruf b dilaksanakan oleh kementerian/lembaga sesuai dengan ketentuan peraturan perundang-undangan.
(2) Dalam rangka mendukung pelaksanaan pengamatan gejala bencana dan analisa data hasil pengamatan sebagaimana dimaksud pada ayat (1), BNPB/BPBD dapat melaksanakan tindakan pemantauan langsung.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3673, 'perban-4-2022', 8, 'pasal', 'Pasal 5', 'BAB II PELAKSANAAN PERINGATAN DINI BENCANA', 4, 'Dalam Peringatan Dini Bencana sebagaimana dimaksud dalam Pasal 3 ayat (1), BNPB dan BPBD berwenang dalam:
a. pengambilan keputusan berdasarkan hasil analisa,
b. penyebarluasan hasil keputusan, dan
c. pengambilan tindakan oleh masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3673, 'Dalam Peringatan Dini Bencana sebagaimana dimaksud dalam Pasal 3 ayat (1), BNPB dan BPBD berwenang dalam:
a. pengambilan keputusan berdasarkan hasil analisa,
b. penyebarluasan hasil keputusan, dan
c. pengambilan tindakan oleh masyarakat.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3674, 'perban-4-2022', 9, 'pasal', 'Pasal 6', 'BAB II PELAKSANAAN PERINGATAN DINI BENCANA', 4, '(1) Pengambilan keputusan sebagaimana dimaksud dalam Pasal 5 huruf a didasarkan atas analisa data hasil pengamatan yang disampaikan oleh kementerian/lembaga — yang mempunyai tugas melakukan pengamatan sesuai jenis ancaman bencana.
(2) Analisa data hasil pengamatan sebagaimana dimaksud pada ayat (1) paling sedikit memuat:
a. informasi peringatan bencana, dan
b. saran rekomendasi yang harus dilakukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3674, '(1) Pengambilan keputusan sebagaimana dimaksud dalam Pasal 5 huruf a didasarkan atas analisa data hasil pengamatan yang disampaikan oleh kementerian/lembaga — yang mempunyai tugas melakukan pengamatan sesuai jenis ancaman bencana.
(2) Analisa data hasil pengamatan sebagaimana dimaksud pada ayat (1) paling sedikit memuat:
a. informasi peringatan bencana, dan
b. saran rekomendasi yang harus dilakukan.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3675, 'perban-4-2022', 10, 'pasal', 'Pasal 7', 'BAB II PELAKSANAAN PERINGATAN DINI BENCANA', 4, '(1) Pengambilan keputusan sebagaimana dimaksud dalam Pasal 6 ayat (1) dapat berupa:
a. perintah Kepala BNPB, atau
b. keputusan Kepala Daerah.
(2) Keputusan sebagaimana dimaksud pada ayat (1) memuat:
a. upaya kesiapsiagaan,
b. upaya kedaruratan/perintah evakuasi, dan/atau Cc. wilayah yang diperkirakan akan terpapar bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3675, '(1) Pengambilan keputusan sebagaimana dimaksud dalam Pasal 6 ayat (1) dapat berupa:
a. perintah Kepala BNPB, atau
b. keputusan Kepala Daerah.
(2) Keputusan sebagaimana dimaksud pada ayat (1) memuat:
a. upaya kesiapsiagaan,
b. upaya kedaruratan/perintah evakuasi, dan/atau Cc. wilayah yang diperkirakan akan terpapar bencana.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3676, 'perban-4-2022', 11, 'pasal', 'Pasal 8', 'BAB II PELAKSANAAN PERINGATAN DINI BENCANA', 5, '(1) Keputusan sebagaimana dimaksud dalam Pasal 7 disebarluaskan secara:
a. kedinasan, dan/atau
b. publik.
(2) Penyebarluasan keputusan secara kedinasan sebagaimana dimaksud pada ayat (1) huruf a disampaikan kepada instansi/sektor terkait.
(3) Penyebarluasan keputusan secara publik sebagaimana dimaksud pada ayat (1) huruf b dapat dilaksanakan oleh penyelenggara informasi dan komunikasi publik, lembaga penyiaran swasta, media massa, dan media sosial.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3676, '(1) Keputusan sebagaimana dimaksud dalam Pasal 7 disebarluaskan secara:
a. kedinasan, dan/atau
b. publik.
(2) Penyebarluasan keputusan secara kedinasan sebagaimana dimaksud pada ayat (1) huruf a disampaikan kepada instansi/sektor terkait.
(3) Penyebarluasan keputusan secara publik sebagaimana dimaksud pada ayat (1) huruf b dapat dilaksanakan oleh penyelenggara informasi dan komunikasi publik, lembaga penyiaran swasta, media massa, dan media sosial.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3677, 'perban-4-2022', 12, 'pasal', 'Pasal 9', 'BAB III PENGUATAN PELAKSANAAN PERINGATAN DINI BENCANA', 5, '(1) Pengambilan tindakan oleh masyarakat dilakukan sebagai langkah penyelamatan dengan mempertimbangkan aspek perlindungan dan keamanan masyarakat.
(2) Pengambilan tindakan oleh masyarakat sebagaimana dimaksud pada ayat (1) dikoordinasikan oleh BNPB dan/atau BPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3677, '(1) Pengambilan tindakan oleh masyarakat dilakukan sebagai langkah penyelamatan dengan mempertimbangkan aspek perlindungan dan keamanan masyarakat.
(2) Pengambilan tindakan oleh masyarakat sebagaimana dimaksud pada ayat (1) dikoordinasikan oleh BNPB dan/atau BPBD.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3678, 'perban-4-2022', 13, 'pasal', 'Pasal 10', 'BAB III PENGUATAN PELAKSANAAN PERINGATAN DINI BENCANA', 5, 'Dalam rangka menunjang pelaksanaan Peringatan Dini Bencana sebagaimana dimaksud dalam Pasal 3, dapat dilakukan penguatan kelembagaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3678, 'Dalam rangka menunjang pelaksanaan Peringatan Dini Bencana sebagaimana dimaksud dalam Pasal 3, dapat dilakukan penguatan kelembagaan.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2022 tentang Pelaksanaan Peringatan Dini Bencana pada Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3679, 'perban-4-2022', 14, 'pasal', 'Pasal 11', 'BAB IV PENDANAAN', 5, '(1) Penguatan kelembagaan sebagaimana dimaksud pada ayat (2) terdiri atas:
a. penetapan norma, standar, prosedur, dan kriteria,
b. peningkatan kapasitas sumber daya manusia:
Cc. peningkatan kapasitas sarana dan prasarana, dan
d. pengoordinasian dan pengintegrasian pelaksanaan.
(2) Penetapan norma, standar, prosedur, dan kriteria sebagaimana dimaksud dalam ayat (1) huruf a meliputi:
a. penyusunan rencana induk sistem peringatan dini multi ancaman bencana, dan/atau
b. penatalaksanaan Peringatan Dini Bencana.
(3) Peningkatan kapasitas sumber daya manusia sebagaimana dimaksud dalam ayat (1) huruf b dilaksanakan melalui:
a. peningkatan pengetahuan mengenai risiko bencana,
b. peningkatan kemampuan pemantauan dan pengelolaan data informasi Peringatan Dini Bencana, Cc. peningkatan pemahaman dalam komunikasi dan diseminasi Peringatan Dini Bencana, dan/atau
d. peningkatan kemampuan respon tindakan kesiapsiagaan Peringatan Dini Bencana.
(4) Pelaksanaan peningkatan kapasitas sumber daya manusia sebagaimana dimaksud pada ayat (3) berupa:
a. bimbingan teknis, dan/atau
b. pelatihan dan latihan.
(5) Peningkatan kapasitas sarana dan prasarana sebagaimana dimaksud dalam ayat (1) huruf c dilakukan melalui:
a. penyediaan sarana dan prasarana Peringatan Dini Bencana,
b. penguatan infrastruktur teknologi informatika dan komunikasi, Cc. peningkatan kapasitas pusat pengendalian operasi, dan/atau
d. pemeliharaan alat Peringatan Dini Bencana.
(6) Pengoordinasian dan pengintegrasian pelaksanaan sebagaimana dimaksud dalam ayat (1) huruf d dilaksanakan melalui:
a. peningkatan koordinasi antar kementerian/lembaga dalam Peringatan Dini Bencana, dan
b. pembentukan dan pengembangan integrasi data dan informasi Peringatan Dini Bencana.
(7) Penguatan kelembagaan sebagaimana dimaksud dalam ayat (1) dilaksanakan oleh:
a. BNPB di tingkat pusat, dan
b. BPBD di tingkat daerah.
(8) Selain dilaksanakan oleh BNPB/BPBD, penguatan kelembagaan sebagaimana dimaksud pada ayat (1) huruf b dan huruf c dapat dilaksanakan oleh lembaga nonpemerintah, perguruan tinggi dan masyarakat yang memiliki kapasitas dalam Peringatan Dini Bencana.');
