INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3680, 'perban-4-2022', 15, 'pasal', 'Pasal 12', 'BAB V PEMANTAUAN DAN EVALUASI', 7, '(1) Dalam rangka memberikan pelayanan kepada masyarakat sesuai dengan standar pelayanan minimum urusan bencana, BNPB/BPBD menyusun program kerja pelaksanaan Peringatan Dini Bencana.
