INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3680, '(1) Dalam rangka memberikan pelayanan kepada masyarakat sesuai dengan standar pelayanan minimum urusan bencana, BNPB/BPBD menyusun program kerja pelaksanaan Peringatan Dini Bencana.
