INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3681, 'perban-4-2022', 16, 'pasal', 'Pasal 13', 'BAB VI KETENTUAN PENUTUP', 8, '(1) Terhadap pelaksanaan Peringatan Dini Bencana pada BNPB dan BPBD dilakukan pemantauan dan evaluasi.
