INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3682, 'perban-4-2022', 17, 'pasal', 'Pasal 14', 'BAB VI KETENTUAN PENUTUP', 8, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
