INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3685, 'perban-4-2024', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2024 tentang Penyelenggaraan Hibah Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3685, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2024 tentang Penyelenggaraan Hibah Rehabilitasi dan Rekonstruksi Pascabencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2024 tentang Penyelenggaraan Hibah Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3686, 'perban-4-2024', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam penyelenggaraan penanggulangan bencana, perlu dilakukan rehabilitasi dan rekonstruksi untuk mempercepat pemulihan kehidupan masyarakat serta pelayanan umum pada wilayah pascabencana;
b. bahwa Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2019 tentang Pemanfaatan Hibah dari Pemerintah Pusat Kepada Pemerintah Daerah untuk Bantuan Rehabilitasi dan Rekonstruksi Pascabencana dalam implementasinya sudah tidak sesuai dengan perkembangan kebutuhan hukum sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Penyelenggaraan Hibah Rehabilitasi dan Rekonstruksi Pascabencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3686, 'a. bahwa dalam penyelenggaraan penanggulangan bencana, perlu dilakukan rehabilitasi dan rekonstruksi untuk mempercepat pemulihan kehidupan masyarakat serta pelayanan umum pada wilayah pascabencana;
b. bahwa Peraturan Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2019 tentang Pemanfaatan Hibah dari Pemerintah Pusat Kepada Pemerintah Daerah untuk Bantuan Rehabilitasi dan Rekonstruksi Pascabencana dalam implementasinya sudah tidak sesuai dengan perkembangan kebutuhan hukum sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Penyelenggaraan Hibah Rehabilitasi dan Rekonstruksi Pascabencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2024 tentang Penyelenggaraan Hibah Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3687, 'perban-4-2024', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3687, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2024 tentang Penyelenggaraan Hibah Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3688, 'perban-4-2024', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENYELENGGARAAN HIBAH REHABILITASI DAN REKONSTRUKSI PASCABENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3688, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENYELENGGARAAN HIBAH REHABILITASI DAN REKONSTRUKSI PASCABENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2024 tentang Penyelenggaraan Hibah Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3689, 'perban-4-2024', 4, 'pasal', 'Pasal 1', 'BAB II KRITERIA; Bagian Kesatu Kriteria Kegiatan', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Hibah Rehabilitasi dan Rekonstruksi Pascabencana yang selanjutnya disebut Hibah RR adalah hibah dari pemerintah pusat kepada pemerintah daerah untuk bantuan rehabilitasi dan rekonstruksi pascabencana.
2. Perjanjian Hibah Daerah yang selanjutnya disingkat PHD adalah kesepakatan tertulis mengenai hibah antara pemerintah dan pemerintah daerah yang dituangkan dalam perjanjian.
3. Surat Penetapan Pemberian Hibah yang selanjutnya disingkat SPPH adalah surat yang diterbitkan oleh Menteri Keuangan atau pejabat yang diberi wewenang dan ditujukan kepada pemerintah daerah, yang memuat kegiatan dan besaran hibah yang bersumber dari penerimaan dalam negeri.
4. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pascabencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.
5. Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta Masyarakat dalam segala aspek kehidupan bermasyarakat pada wilayah pascabencana.
6. Anggaran Pendapatan dan Belanja Daerah yang selanjutnya disingkat APBD adalah rencana keuangan tahunan daerah yang ditetapkan dengan peraturan daerah.
7. Rekening Kas Umum Negara yang selanjutnya disingkat RKUN adalah rekening tempat penyimpanan uang negara yang ditentukan oleh Menteri Keuangan selaku Bendahara Umum Negara untuk menampung seluruh penerimaan negara dan membayar seluruh pengeluaran negara pada bank sentral.
8. Rekening Kas Umum Daerah yang selanjutnya disingkat RKUD adalah rekening tempat penyimpanan uang daerah yang ditentukan oleh gubernur dan bupati/walikota untuk menampung seluruh penerimaan daerah dan membayar seluruh pengeluaran daerah pada bank yang ditetapkan.
9. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
10. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara pemerintahan daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
11. Perangkat Daerah adalah unsur pembantu kepala daerah dan Dewan Perwakilan Rakyat Daerah dalam penyelenggaraan urusan pemerintahan yang menjadi kewenangan daerah.
12. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan Pemerintah Daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
13. Rencana Kegiatan dan Anggaran yang selanjutnya disingkat RKA adalah dokumen yang memuat rincian kegiatan dan besaran pendanaan selama 1 (satu) tahun.
14. Aparat Pengawas Internal Pemerintah yang selanjutnya disingkat APIP adalah inspektorat jenderal kementerian, unit pengawasan lembaga pemerintah nonkementerian, inspektorat provinsi, dan inspektorat kabupaten/kota.');
