INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3729, 'perban-4-2025', 5, 'pasal', 'Pasal 2', 'BAB I KETENTUAN UMUM', 4, 'Jabatan Fungsional di Bidang Kebencanaan terdiri atas:
a. Jabatan Fungsional Analis Kebencanaan; dan
b. Jabatan Fungsional Pranata Kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3729, 'Jabatan Fungsional di Bidang Kebencanaan terdiri atas:
a. Jabatan Fungsional Analis Kebencanaan; dan
b. Jabatan Fungsional Pranata Kebencanaan.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3730, 'perban-4-2025', 6, 'pasal', 'Pasal 3', 'BAB II KEDUDUKAN, TANGGUNG JAWAB, DAN KLASIFIKASI/RUMPUN JABATAN; Bagian Kesatu Kedudukan dan Tanggung Jawab', 4, 'Jabatan Fungsional di Bidang Kebencanaan sebagaimana dimaksud dalam Pasal 2 merupakan jabatan karier PNS.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3730, 'Jabatan Fungsional di Bidang Kebencanaan sebagaimana dimaksud dalam Pasal 2 merupakan jabatan karier PNS.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3731, 'perban-4-2025', 7, 'pasal', 'Pasal 4', 'BAB II KEDUDUKAN, TANGGUNG JAWAB, DAN KLASIFIKASI/RUMPUN JABATAN; Bagian Kedua Klasifikasi/Rumpun Jabatan', 4, '(1) Analis Kebencanaan berkedudukan sebagai pelaksana teknis kegiatan di bidang analisis kebencanaan, penyelenggaraan penanggulangan bencana, dan penyuluhan kebencanaan pada Instansi Pemerintah.
(2) Pranata Kebencanaan berkedudukan sebagai pelaksana teknis kegiatan di bidang operasional dan teknis penyelenggaraan penanggulangan bencana dan penyuluhan kebencanaan pada Instansi Pemerintah.
(3) Analis Kebencanaan dan Pranata Kebencanaan sebagaimana dimaksud pada ayat (1) dan ayat (2) berkedudukan di bawah dan bertanggung jawab secara langsung kepada pejabat pimpinan tinggi madya, pejabat pimpinan tinggi pratama, pejabat administrator, atau pejabat pengawas yang memiliki keterkaitan dengan pelaksanaan tugas Jabatan Fungsional di Bidang Kebencanaan.
(4) Dalam hal unit organisasi dipimpin oleh pejabat fungsional, Analis Kebencanaan dan Pranata Kebencanaan berkedudukan di bawah dan bertanggung jawab secara langsung kepada pejabat fungsional lain yang memimpin unit organisasi tersebut.
(5) Kedudukan Analis Kebencanaan dan Pranata Kebencanaan sebagaimana dimaksud pada ayat (3) dan ayat (4) ditetapkan dalam peta jabatan berdasarkan analisis tugas dan fungsi unit kerja, analisis jabatan, dan analisis beban kerja dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3731, '(1) Analis Kebencanaan berkedudukan sebagai pelaksana teknis kegiatan di bidang analisis kebencanaan, penyelenggaraan penanggulangan bencana, dan penyuluhan kebencanaan pada Instansi Pemerintah.
(2) Pranata Kebencanaan berkedudukan sebagai pelaksana teknis kegiatan di bidang operasional dan teknis penyelenggaraan penanggulangan bencana dan penyuluhan kebencanaan pada Instansi Pemerintah.
(3) Analis Kebencanaan dan Pranata Kebencanaan sebagaimana dimaksud pada ayat (1) dan ayat (2) berkedudukan di bawah dan bertanggung jawab secara langsung kepada pejabat pimpinan tinggi madya, pejabat pimpinan tinggi pratama, pejabat administrator, atau pejabat pengawas yang memiliki keterkaitan dengan pelaksanaan tugas Jabatan Fungsional di Bidang Kebencanaan.
(4) Dalam hal unit organisasi dipimpin oleh pejabat fungsional, Analis Kebencanaan dan Pranata Kebencanaan berkedudukan di bawah dan bertanggung jawab secara langsung kepada pejabat fungsional lain yang memimpin unit organisasi tersebut.
(5) Kedudukan Analis Kebencanaan dan Pranata Kebencanaan sebagaimana dimaksud pada ayat (3) dan ayat (4) ditetapkan dalam peta jabatan berdasarkan analisis tugas dan fungsi unit kerja, analisis jabatan, dan analisis beban kerja dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3732, 'perban-4-2025', 8, 'pasal', 'Pasal 5', 'BAB III KATEGORI, JENJANG, PANGKAT, GOLONGAN RUANG, TUGAS JABATAN, DAN RUANG LINGKUP KEGIATAN JABATAN FUNGSIONAL DI BIDANG KEBENCANAAN; Bagian Kesatu Kategori dan Jenjang Jabatan', 5, 'Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan termasuk dalam klasifikasi/rumpun manajemen.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3732, 'Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan termasuk dalam klasifikasi/rumpun manajemen.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3733, 'perban-4-2025', 9, 'pasal', 'Pasal 6', 'BAB III KATEGORI, JENJANG, PANGKAT, GOLONGAN RUANG, TUGAS JABATAN, DAN RUANG LINGKUP KEGIATAN JABATAN FUNGSIONAL DI BIDANG KEBENCANAAN; Bagian Kesatu Kategori dan Jenjang Jabatan', 5, '(1) Jabatan Fungsional Analis Kebencanaan merupakan Jabatan Fungsional kategori keahlian.
(2) Jenjang Jabatan Fungsional Analis Kebencanaan sebagaimana dimaksud pada ayat (1) terdiri atas:
a. Analis Kebencanaan Ahli Pertama;
b. Analis Kebencanaan Ahli Muda;
c. Analis Kebencanaan Ahli Madya; dan
d. Analis Kebencanaan Ahli Utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3733, '(1) Jabatan Fungsional Analis Kebencanaan merupakan Jabatan Fungsional kategori keahlian.
(2) Jenjang Jabatan Fungsional Analis Kebencanaan sebagaimana dimaksud pada ayat (1) terdiri atas:
a. Analis Kebencanaan Ahli Pertama;
b. Analis Kebencanaan Ahli Muda;
c. Analis Kebencanaan Ahli Madya; dan
d. Analis Kebencanaan Ahli Utama.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3734, 'perban-4-2025', 10, 'pasal', 'Pasal 7', 'BAB III KATEGORI, JENJANG, PANGKAT, GOLONGAN RUANG, TUGAS JABATAN, DAN RUANG LINGKUP KEGIATAN JABATAN FUNGSIONAL DI BIDANG KEBENCANAAN; Bagian Kedua Pangkat dan Golongan Ruang', 5, '(1) Jabatan Fungsional Pranata Kebencanaan merupakan Jabatan Fungsional kategori keterampilan.
(2) Jenjang Jabatan Fungsional Pranata Kebencanaan sebagaimana dimaksud pada ayat (1) terdiri atas:
a. Pranata Kebencanaan Pemula;
b. Pranata Kebencanaan Terampil;
c. Pranata Kebencanaan Mahir; dan
d. Pranata Kebencanaan Penyelia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3734, '(1) Jabatan Fungsional Pranata Kebencanaan merupakan Jabatan Fungsional kategori keterampilan.
(2) Jenjang Jabatan Fungsional Pranata Kebencanaan sebagaimana dimaksud pada ayat (1) terdiri atas:
a. Pranata Kebencanaan Pemula;
b. Pranata Kebencanaan Terampil;
c. Pranata Kebencanaan Mahir; dan
d. Pranata Kebencanaan Penyelia.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3735, 'perban-4-2025', 11, 'pasal', 'Pasal 8', 'BAB III KATEGORI, JENJANG, PANGKAT, GOLONGAN RUANG, TUGAS JABATAN, DAN RUANG LINGKUP KEGIATAN JABATAN FUNGSIONAL DI BIDANG KEBENCANAAN; Bagian Kedua Pangkat dan Golongan Ruang', 6, 'Pangkat dan golongan ruang Jabatan Fungsional Analis Kebencanaan meliputi:
a. Jabatan Fungsional Analis Kebencanaan Ahli Pertama, terdiri atas:
1. Pangkat Penata Muda, golongan ruang III/a; dan
2. Pangkat Penata Muda Tingkat I, golongan ruang III/b;
b. Jabatan Fungsional Analis Kebencanaan Ahli Muda, terdiri atas:
1. Pangkat Penata, golongan ruang III/c; dan
2. Pangkat Penata Tingkat I, golongan ruang III/d;
c. Jabatan Fungsional Analis Kebencanaan Ahli Madya, terdiri atas:
1. Pangkat Pembina, golongan ruang IV/a;
2. Pangkat Pembina Tingkat I, golongan ruang IV/b; dan
3. Pangkat Pembina Utama Muda, golongan ruang IV/c, dan
d. Jabatan Fungsional Analis Kebencanaan Ahli Utama, terdiri atas:
1. Pangkat Pembina Utama Madya, golongan ruang IV/d; dan
2. Pangkat Pembina Utama, golongan ruang IV/e.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3735, 'Pangkat dan golongan ruang Jabatan Fungsional Analis Kebencanaan meliputi:
a. Jabatan Fungsional Analis Kebencanaan Ahli Pertama, terdiri atas:
1. Pangkat Penata Muda, golongan ruang III/a; dan
2. Pangkat Penata Muda Tingkat I, golongan ruang III/b;
b. Jabatan Fungsional Analis Kebencanaan Ahli Muda, terdiri atas:
1. Pangkat Penata, golongan ruang III/c; dan
2. Pangkat Penata Tingkat I, golongan ruang III/d;
c. Jabatan Fungsional Analis Kebencanaan Ahli Madya, terdiri atas:
1. Pangkat Pembina, golongan ruang IV/a;
2. Pangkat Pembina Tingkat I, golongan ruang IV/b; dan
3. Pangkat Pembina Utama Muda, golongan ruang IV/c, dan
d. Jabatan Fungsional Analis Kebencanaan Ahli Utama, terdiri atas:
1. Pangkat Pembina Utama Madya, golongan ruang IV/d; dan
2. Pangkat Pembina Utama, golongan ruang IV/e.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3736, 'perban-4-2025', 12, 'pasal', 'Pasal 9', 'BAB III KATEGORI, JENJANG, PANGKAT, GOLONGAN RUANG, TUGAS JABATAN, DAN RUANG LINGKUP KEGIATAN JABATAN FUNGSIONAL DI BIDANG KEBENCANAAN; Bagian Kedua Pangkat dan Golongan Ruang', 6, 'Pangkat dan golongan ruang Jabatan Fungsional Pranata Kebencanaan meliputi:
a. Jabatan Fungsional Pranata Kebencanaan Pemula, terdiri atas Pengatur Muda, golongan ruang II/a;
b. Jabatan Fungsional Pranata Kebencanaan Terampil, terdiri atas:
1. Pangkat Pengatur Muda Tingkat I, golongan ruang II/b;
2. Pangkat Pengatur, golongan ruang II/c; dan
3. Pangkat Pengatur Tingkat I, golongan ruang II/d;
c. Jabatan Fungsional Pranata Kebencanaan Mahir, terdiri atas:
1. Pangkat Penata Muda, golongan ruang III/a; dan
2. Pangkat Penata Muda Tingkat I, golongan ruang III/b; dan
d. Jabatan Fungsional Pranata Kebencanaan Penyelia, terdiri atas:
1. Pangkat Penata, golongan ruang III/c; dan
2. Pangkat Penata Tingkat I, golongan ruang III/d.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3736, 'Pangkat dan golongan ruang Jabatan Fungsional Pranata Kebencanaan meliputi:
a. Jabatan Fungsional Pranata Kebencanaan Pemula, terdiri atas Pengatur Muda, golongan ruang II/a;
b. Jabatan Fungsional Pranata Kebencanaan Terampil, terdiri atas:
1. Pangkat Pengatur Muda Tingkat I, golongan ruang II/b;
2. Pangkat Pengatur, golongan ruang II/c; dan
3. Pangkat Pengatur Tingkat I, golongan ruang II/d;
c. Jabatan Fungsional Pranata Kebencanaan Mahir, terdiri atas:
1. Pangkat Penata Muda, golongan ruang III/a; dan
2. Pangkat Penata Muda Tingkat I, golongan ruang III/b; dan
d. Jabatan Fungsional Pranata Kebencanaan Penyelia, terdiri atas:
1. Pangkat Penata, golongan ruang III/c; dan
2. Pangkat Penata Tingkat I, golongan ruang III/d.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3737, 'perban-4-2025', 13, 'pasal', 'Pasal 10', 'BAB III KATEGORI, JENJANG, PANGKAT, GOLONGAN RUANG, TUGAS JABATAN, DAN RUANG LINGKUP KEGIATAN JABATAN FUNGSIONAL DI BIDANG KEBENCANAAN; Bagian Ketiga Tugas Jabatan dan Ruang Lingkup Kegiatan', 7, 'Pangkat dan golongan ruang Jabatan Fungsional Analis Kebencanaan sebagaimana dimaksud dalam Pasal 8 dan Jabatan Fungsional Pranata Kebencanaan sebagaimana dimaksud dalam Pasal 9 dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3737, 'Pangkat dan golongan ruang Jabatan Fungsional Analis Kebencanaan sebagaimana dimaksud dalam Pasal 8 dan Jabatan Fungsional Pranata Kebencanaan sebagaimana dimaksud dalam Pasal 9 dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3738, 'perban-4-2025', 14, 'pasal', 'Pasal 11', 'BAB III KATEGORI, JENJANG, PANGKAT, GOLONGAN RUANG, TUGAS JABATAN, DAN RUANG LINGKUP KEGIATAN JABATAN FUNGSIONAL DI BIDANG KEBENCANAAN; Bagian Ketiga Tugas Jabatan dan Ruang Lingkup Kegiatan', 7, '(1) Tugas Jabatan Fungsional Analis Kebencanaan yaitu melaksanakan analisis penanggulangan bencana.
(2) Tugas Jabatan Fungsional Pranata Kebencanaan yaitu melaksanakan kegiatan operasional dan teknis penyelenggaraan penanggulangan bencana.
(3) Tugas Jabatan Fungsional Analis kebencanaan sebagaimana dimaksud pada ayat (1) dilaksanakan dengan memperhatikan ruang lingkup kegiatan meliputi analisis kebencanaan, penyelenggaraan penanggulangan bencana, penyuluhan kebencanaan, dan pengembangan strategi kebencanaan.
(4) Tugas Jabatan Fungsional Pranata Kebencanaan sebagaimana dimaksud pada ayat (2) dilaksanakan dengan memperhatikan ruang lingkup kegiatan meliputi teknis kegiatan operasional dan teknis penyelenggaraan penanggulangan bencana dan penyuluhan kebencanaan.
(5) Ruang lingkup kegiatan sebagaimana dimaksud pada ayat (3) pada setiap jenjang jabatan meliputi:
a. Analis Kebencanaan Ahli Pertama melaksanakan inventarisasi dan identifikasi bahan analisis kebencanaan, penyelenggaraan penanggulangan bencana, dan penyuluhan kebencanaan;
b. Analis Kebencanaan Ahli Muda melaksanakan analisis kebencanaan, penyelenggaraan penanggulangan bencana, dan penyuluhan kebencanaan;
c. Analis Kebencanaan Ahli Madya melaksanakan monitoring, evaluasi, dan penyusunan rekomendasi analisis kebencanaan, penyelenggaraan penanggulangan bencana, dan penyuluhan kebencanaan; dan
d. Analis Kebencanaan Ahli Utama melaksanakan penyusunan, pengembangan strategi, dan kebijakan di bidang penanggulangan bencana.
(6) Ruang lingkup kegiatan sebagaimana dimaksud pada ayat (4) pada setiap jenjang jabatan meliputi:
a. Pranata Kebencanaan Pemula melaksanakan identifikasi kebutuhan kegiatan operasional dan teknis penyelenggaraan penanggulangan bencana dan penyuluhan kebencanaan;
b. Pranata Kebencanaan Terampil melakukan pengumpulan data dan pemetaan kegiatan operasional dan teknis penyelenggaraan penanggulangan bencana dan penyuluhan kebencanaan;
c. Pranata Kebencanaan Mahir melaksanakan kegiatan operasional dan teknis penyelenggaraan penanggulangan bencana dan penyuluhan kebencanaan; dan
d. Pranata Kebencanaan Penyelia melakukan evaluasi dan penyusunan rekomendasi kegiatan operasional dan teknis penyelenggaraan penanggulangan bencana dan penyuluhan kebencanaan.
(7) Selain tugas sebagaimana dimaksud pada ayat (1) dan ayat (2), Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan dapat diberikan tugas lainnya.
(8) Tugas Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan dilaksanakan untuk memenuhi Ekspektasi pada Instansi Pemerintah guna pencapaian target organisasi.
(9) Ekspektasi sebagaimana dimaksud pada ayat (8) ditetapkan berdasarkan prinsip pengelolaan kinerja pegawai aparatur sipil negara sesuai dengan ketentuan peraturan perundang-undangan.');
