INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3768, 'perban-4-2025', 44, 'pasal', 'Pasal 40', 'BAB VIII KOMPETENSI; Bagian Ketiga Pengembangan Kompetensi', 28, 'Pelatihan sebagaimana dimaksud dalam Pasal 39 ayat (1) diberikan paling sedikit 20 (dua puluh) jam pelajaran dalam 1 (satu) tahun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3768, 'Pelatihan sebagaimana dimaksud dalam Pasal 39 ayat (1) diberikan paling sedikit 20 (dua puluh) jam pelajaran dalam 1 (satu) tahun.', 'Pasal 40', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3769, 'perban-4-2025', 45, 'pasal', 'Pasal 41', 'BAB VIII KOMPETENSI; Bagian Ketiga Pengembangan Kompetensi', 28, '(1) Pelatihan fungsional Analis Kebencanaan dan pelatihan fungsional Pranata Kebencanaan sebagaimana dimaksud dalam Pasal 39 ayat (3) huruf a merupakan program pengembangan kompetensi sesuai dengan jenis dan jenjang Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan.
(2) Kurikulum pelatihan fungsional Analis Kebencanaan dan pelatihan fungsional Pranata Kebencanaan sebagaimana dimaksud pada ayat (1) ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3769, '(1) Pelatihan fungsional Analis Kebencanaan dan pelatihan fungsional Pranata Kebencanaan sebagaimana dimaksud dalam Pasal 39 ayat (3) huruf a merupakan program pengembangan kompetensi sesuai dengan jenis dan jenjang Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan.
(2) Kurikulum pelatihan fungsional Analis Kebencanaan dan pelatihan fungsional Pranata Kebencanaan sebagaimana dimaksud pada ayat (1) ditetapkan oleh Kepala BNPB.', 'Pasal 41', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3770, 'perban-4-2025', 46, 'pasal', 'Pasal 42', 'BAB VIII KOMPETENSI; Bagian Ketiga Pengembangan Kompetensi', 29, 'Pelatihan teknis sebagaimana dimaksud dalam Pasal 39 ayat
(3) huruf b merupakan program pengembangan kompetensi untuk meningkatkan kompetensi dan pengembangan karier Analis Kebencanaan dan Pranata Kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3770, 'Pelatihan teknis sebagaimana dimaksud dalam Pasal 39 ayat
(3) huruf b merupakan program pengembangan kompetensi untuk meningkatkan kompetensi dan pengembangan karier Analis Kebencanaan dan Pranata Kebencanaan.', 'Pasal 42', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3771, 'perban-4-2025', 47, 'pasal', 'Pasal 43', 'BAB IX PEMBERHENTIAN DARI JABATAN DAN PENGANGKATAN KEMBALI; Bagian Kesatu Pemberhentian dari Jabatan', 29, '(1) Kebutuhan pelatihan diperoleh melalui analisis kebutuhan pelatihan Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan.
(2) Analisis kebutuhan pelatihan fungsional Analis Kebencanaan dan pelatihan fungsional Pranata Kebencanaan sebagaimana dimaksud pada ayat (1) dilakukan untuk memenuhi kebutuhan pengembangan kompetensi Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan.
(3) Analisis kebutuhan pelatihan fungsional Analis Kebencanaan dan pelatihan fungsional Pranata Kebencanaan sebagaimana dimaksud pada ayat (1) dapat diperoleh melalui:
a. analisis hasil Uji Kompetensi; dan/atau
b. survei.
(4) Analisis hasil Uji Kompetensi sebagaimana dimaksud pada ayat (3) huruf a dilakukan untuk mengetahui kesenjangan kompetensi Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan dengan Standar Kompetensi yang bersangkutan.
(5) Survei sebagaimana dimaksud pada ayat (3) huruf b dapat dilakukan dengan metode wawancara, kuesioner, observasi, dan/atau metode ilmiah lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3771, '(1) Kebutuhan pelatihan diperoleh melalui analisis kebutuhan pelatihan Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan.
(2) Analisis kebutuhan pelatihan fungsional Analis Kebencanaan dan pelatihan fungsional Pranata Kebencanaan sebagaimana dimaksud pada ayat (1) dilakukan untuk memenuhi kebutuhan pengembangan kompetensi Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan.
(3) Analisis kebutuhan pelatihan fungsional Analis Kebencanaan dan pelatihan fungsional Pranata Kebencanaan sebagaimana dimaksud pada ayat (1) dapat diperoleh melalui:
a. analisis hasil Uji Kompetensi; dan/atau
b. survei.
(4) Analisis hasil Uji Kompetensi sebagaimana dimaksud pada ayat (3) huruf a dilakukan untuk mengetahui kesenjangan kompetensi Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan dengan Standar Kompetensi yang bersangkutan.
(5) Survei sebagaimana dimaksud pada ayat (3) huruf b dapat dilakukan dengan metode wawancara, kuesioner, observasi, dan/atau metode ilmiah lainnya.', 'Pasal 43', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3772, 'perban-4-2025', 48, 'pasal', 'Pasal 44', 'BAB IX PEMBERHENTIAN DARI JABATAN DAN PENGANGKATAN KEMBALI; Bagian Kesatu Pemberhentian dari Jabatan', 29, '(1) Analis Kebencanaan dan Pranata Kebencanaan diberhentikan dari jabatannya apabila:
a. mengundurkan diri dari jabatan;
b. diberhentikan sementara sebagai PNS;
c. menjalani cuti di luar tanggungan negara;
d. menjalani tugas belajar lebih dari 6 (enam) bulan;
e. ditugaskan secara penuh pada jabatan pimpinan tinggi, jabatan administrator, jabatan pengawas, atau jabatan pelaksana; atau
f. tidak memenuhi persyaratan Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan.
(2) Pemberhentian dengan alasan pengunduran diri dari jabatan sebagaimana dimaksud pada ayat (1) huruf a dapat dipertimbangkan dalam hal memiliki alasan pribadi yang tidak mungkin untuk melaksanakan tugas Jabatan Fungsional Analis Kebencanaan dan Jabatan Fungsional Pranata Kebencanaan.
(3) PPK menetapkan pemberhentian Analis Kebencanaan dan Pranata Kebencanaan karena pengunduran diri sebagaimana dimaksud pada ayat (1) huruf a setelah mendapatkan persetujuan dari pimpinan Instansi Pembina melalui pejabat pimpinan tinggi pratama yang membidangi pembinaan Jabatan Fungsional di Bidang Kebencanaan.
(4) Pemberhentian dengan alasan diberhentikan sementara sebagai PNS sebagaimana dimaksud pada ayat (1) huruf b diberikan dalam hal Analis Kebencanaan atau Pranata Kebencanaan:
a. diangkat menjadi pejabat negara;
b. diangkat menjadi komisioner atau anggota lembaga nonstruktural; atau
c. ditahan karena menjadi tersangka tindak pidana.
(5) Pemberhentian dengan alasan menjalani cuti di luar tanggungan negara sebagaimana dimaksud pada ayat
(1) huruf c merupakan cuti yang diberikan kepada PNS yang telah bekerja paling singkat 5 (lima) tahun secara terus menerus, karena alasan pribadi yang penting dan mendesak sehingga tidak bisa masuk kerja.
(6) Pemberhentian dengan alasan menjalani tugas belajar lebih dari 6 (enam) bulan sebagaimana dimaksud pada ayat (1) huruf d merupakan tugas kedinasan yang diberikan kepada PNS untuk mengikuti pendidikan formal baik di dalam negeri maupun di luar negeri dengan meninggalkan tugas.
(7) Pemberhentian dengan alasan tidak memenuhi persyaratan Jabatan Fungsional sebagaimana dimaksud pada ayat (1) huruf f dapat dipertimbangkan dalam hal:
a. predikat kinerja tahunan bagi pejabat fungsional kurang atau sangat kurang dan tidak menunjukkan perbaikan kinerja setelah diberikan kesempatan selama 6 (enam) bulan untuk memperbaiki kinerjanya sesuai dengan ketentuan peraturan perundang-undangan; dan/atau
b. tidak memenuhi Standar Kompetensi.');
