INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3797, 'perban-4-2025', 73, 'lampiran', 'Lampiran hal. 48', NULL, 48, '9. mengembangkan metode dan sistem penanganan kedaruratan bencana yang lebih baik;
