INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3798, 'perban-4-2025', 74, 'lampiran', 'Lampiran hal. 49', NULL, 49, 'Kebencanaan kegiatan operasional dan identifikasi 1. menyiapkan dokumen administrasi operasional dan teknis kebutuhan pelaksanaan kegiatan penyusunan teknis penyelenggaraan kegiatan dokumen perencanaan kegiatan penyelenggaraan bencana dan operasional dan penanggulangan bencana; penanggulangan penyuluhan teknis 2. menyiapkan dokumen administrasi bencana kebencanaan penyelenggaraan dan perlengkapan pelaksanaan penanggulangan kegiatan kesiapsiagaan masyarakat bencana dan seperti bimbingan teknis penyuluhan ketangguhan masyarakat dalam kebencanaan penanggulangan bencana berbasis gender, disabilitas, rencana keberlanjutan, dll;
3. menyiapkan alat dan perlengkapan pelaksanaan simulasi bencana;
4. mencatat informasi awal dalam pelaksanaan pengamatan kejadian bencana;
5. mencatat data/jumlah harian kejadian bencana;
6. menyusun tampilan papan informasi/display posko penanganan darurat bencana;
7. mencatat kebutuhan logistik dan peralatan penanggulangan bencana;
8. menyiapkan dokumen pelaksanaan penyimpanan logistik;
9. menyiapkan dokumen pencatatan pelaksanaan pemeliharaan peralatan penanggulangan bencana;
10. mencatat jumlah logistik dan peralatan dalam pelaksanaan stok opname;
11. menyusun alat dan perlengkapan pendirian tenda lapangan, dapur lapangan, dan posko bencana;
12. melakukan pengemasan bantuan bencana yang akan disalurkan; dan
13. kegiatan lain yang termasuk dalam ruang lingkup kegiatan jenjang pemula dan kebutuhan organisasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3798, 'Kebencanaan kegiatan operasional dan identifikasi 1. menyiapkan dokumen administrasi operasional dan teknis kebutuhan pelaksanaan kegiatan penyusunan teknis penyelenggaraan kegiatan dokumen perencanaan kegiatan penyelenggaraan bencana dan operasional dan penanggulangan bencana; penanggulangan penyuluhan teknis 2. menyiapkan dokumen administrasi bencana kebencanaan penyelenggaraan dan perlengkapan pelaksanaan penanggulangan kegiatan kesiapsiagaan masyarakat bencana dan seperti bimbingan teknis penyuluhan ketangguhan masyarakat dalam kebencanaan penanggulangan bencana berbasis gender, disabilitas, rencana keberlanjutan, dll;
3. menyiapkan alat dan perlengkapan pelaksanaan simulasi bencana;
4. mencatat informasi awal dalam pelaksanaan pengamatan kejadian bencana;
5. mencatat data/jumlah harian kejadian bencana;
6. menyusun tampilan papan informasi/display posko penanganan darurat bencana;
7. mencatat kebutuhan logistik dan peralatan penanggulangan bencana;
8. menyiapkan dokumen pelaksanaan penyimpanan logistik;
9. menyiapkan dokumen pencatatan pelaksanaan pemeliharaan peralatan penanggulangan bencana;
10. mencatat jumlah logistik dan peralatan dalam pelaksanaan stok opname;
11. menyusun alat dan perlengkapan pendirian tenda lapangan, dapur lapangan, dan posko bencana;
12. melakukan pengemasan bantuan bencana yang akan disalurkan; dan
13. kegiatan lain yang termasuk dalam ruang lingkup kegiatan jenjang pemula dan kebutuhan organisasi.', 'Lampiran hal. 49', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3799, 'perban-4-2025', 75, 'lampiran', 'Lampiran hal. 50', NULL, 50, 'Terampil Melakukan Cakupan kegiatan meliputi: pengumpulan 1. mengumpulkan data bahan data dan pelaksanaan diseminasi informasi pemetaan kajian risiko bencana; kegiatan 2. mengumpulkan dokumen untuk operasional dan bahan penyusunan dokumen teknis rencana penanggulangan bencana; penyelenggaraan 3. menyiapkan alat dan administrasi penanggulangan teknis pelaksanaan latihan bencana dan kesiapsiagaan bencana; penyuluhan 4. menyiapkan administrasi teknis dan kebencanaan pelaksanaan identifikasi survei titik lokasi pemasangan alat peringatan dini;
5. menyiapkan peralatan dan perlengkatan pemasangan rambu bencana;
6. menyiapkan dukungan dan kelengkapan pelaksanaan kesiapsiagaan berbasis komunitas seperti forum pengurangan risiko bencana, relawan, dsb;
7. melaksanakan pendataan kaji cepat pascabencana (jumlah korban, kepala keluarga terdampak, kerusakan prasarana dan sarana, gangguan fungsi pelayanan umum dan pemerintah;
8. mengumpulkan data kebutuhan dasar masyarakat terdampak pengungsi;
9. mengidentifikasi kemampuan dan sumber daya di lokasi bencana;
10. melaksanakan pendataan titik pengungsian sesuai dengan jumlah pengungsi;
11. menyusun notulensi rapat harian posko penanganan darurat bencana;
12. menyiapkan dan melaksanakan dukungan dapur umum di lokasi bencana;
13. melakukan konfirmasi dan verifikasi kejadian bencana;
14. menyusun laporan catatan kejadian bencana pada logbook harian;
15. melaksanakan komunikasi radio bencana;
16. menyusun laporan pelaksanaan stok opname;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3799, 'Terampil Melakukan Cakupan kegiatan meliputi: pengumpulan 1. mengumpulkan data bahan data dan pelaksanaan diseminasi informasi pemetaan kajian risiko bencana; kegiatan 2. mengumpulkan dokumen untuk operasional dan bahan penyusunan dokumen teknis rencana penanggulangan bencana; penyelenggaraan 3. menyiapkan alat dan administrasi penanggulangan teknis pelaksanaan latihan bencana dan kesiapsiagaan bencana; penyuluhan 4. menyiapkan administrasi teknis dan kebencanaan pelaksanaan identifikasi survei titik lokasi pemasangan alat peringatan dini;
5. menyiapkan peralatan dan perlengkatan pemasangan rambu bencana;
6. menyiapkan dukungan dan kelengkapan pelaksanaan kesiapsiagaan berbasis komunitas seperti forum pengurangan risiko bencana, relawan, dsb;
7. melaksanakan pendataan kaji cepat pascabencana (jumlah korban, kepala keluarga terdampak, kerusakan prasarana dan sarana, gangguan fungsi pelayanan umum dan pemerintah;
8. mengumpulkan data kebutuhan dasar masyarakat terdampak pengungsi;
9. mengidentifikasi kemampuan dan sumber daya di lokasi bencana;
10. melaksanakan pendataan titik pengungsian sesuai dengan jumlah pengungsi;
11. menyusun notulensi rapat harian posko penanganan darurat bencana;
12. menyiapkan dan melaksanakan dukungan dapur umum di lokasi bencana;
13. melakukan konfirmasi dan verifikasi kejadian bencana;
14. menyusun laporan catatan kejadian bencana pada logbook harian;
15. melaksanakan komunikasi radio bencana;
16. menyusun laporan pelaksanaan stok opname;', 'Lampiran hal. 50', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3800, 'perban-4-2025', 76, 'lampiran', 'Lampiran hal. 52', NULL, 52, '17. mengoperasikan peralatan penanggulangan bencana;
18. melaksanakan pemeliharaan dan perbaikan peralatan penanggulangan bencana;
19. mencatat dan menyusun tabel usulan bantuan rehabilitasi dan rekonstruksi;
20. menyiapkan bahan (format daftar tilik, data lokasi, jadwal survei, formulir survei) pelaksanaan verifikasi/survei lapangan terkait usulan bantuan rehabilitasi dan rekonstruksi;
21. menginput data progres pelaksanaan rehabilitasi dan rekonstruksi pascabencana; dan
22. kegiatan lain yang termasuk dalam ruang lingkup kegiatan jenjang terampil dan kebutuhan organisasi.
Mahir Melaksanakan Cakupan kegiatan meliputi: kegiatan 1. menyiapkan alat, bahan dan operasional dan dokumen pendukung pelaksanaan teknis sosialisasi Kajian Risiko Bencana; penyelenggaraan 2. menyiapkan bahan dan teknis penanggulangan pelaksanaan diskusi publik; bencana dan 3. mengolah data untuk penyusunan penyuluhan rencana kontingensi kebencanaan provinsi/kabupaten/kota;
4. melakukan verifikasi kesesuaian lokasi pemasangan alat peringatan dini bencana;
5. menyusun laporan pelaksanaan pemasangan rambu bencana;
6. menyusun laporan pelaksanaan kegiatan penguatan kesiapsiagaan berbasis komunitas;
7. menyusun bahan, media, alat pelaksanaan diseminasi informasi tentang penguatan ketangguhan masyarakat dalam penanggulangan bencana;
8. melakukan pendataan dan menyusun tabel pemenuhan kebutuhan dasar masyarakat terdampak dan pengungsi;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3800, '17. mengoperasikan peralatan penanggulangan bencana;
18. melaksanakan pemeliharaan dan perbaikan peralatan penanggulangan bencana;
19. mencatat dan menyusun tabel usulan bantuan rehabilitasi dan rekonstruksi;
20. menyiapkan bahan (format daftar tilik, data lokasi, jadwal survei, formulir survei) pelaksanaan verifikasi/survei lapangan terkait usulan bantuan rehabilitasi dan rekonstruksi;
21. menginput data progres pelaksanaan rehabilitasi dan rekonstruksi pascabencana; dan
22. kegiatan lain yang termasuk dalam ruang lingkup kegiatan jenjang terampil dan kebutuhan organisasi.
Mahir Melaksanakan Cakupan kegiatan meliputi: kegiatan 1. menyiapkan alat, bahan dan operasional dan dokumen pendukung pelaksanaan teknis sosialisasi Kajian Risiko Bencana; penyelenggaraan 2. menyiapkan bahan dan teknis penanggulangan pelaksanaan diskusi publik; bencana dan 3. mengolah data untuk penyusunan penyuluhan rencana kontingensi kebencanaan provinsi/kabupaten/kota;
4. melakukan verifikasi kesesuaian lokasi pemasangan alat peringatan dini bencana;
5. menyusun laporan pelaksanaan pemasangan rambu bencana;
6. menyusun laporan pelaksanaan kegiatan penguatan kesiapsiagaan berbasis komunitas;
7. menyusun bahan, media, alat pelaksanaan diseminasi informasi tentang penguatan ketangguhan masyarakat dalam penanggulangan bencana;
8. melakukan pendataan dan menyusun tabel pemenuhan kebutuhan dasar masyarakat terdampak dan pengungsi;', 'Lampiran hal. 52', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2025 tentang Petunjuk Pelaksanaan dan Petunjuk Teknis Jabatan Fungsional di Bidang Kebencanaan');
