INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3805, 'perban-5-2017', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk melaksanakan Rencana Rehabilitasi dan Rekonstruksi Pascabencana telah ditetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana;
b. bahwa untuk pemulihan pemukiman, infrastruktur, ekonomi produktif, fasilitas sosial, dan lintas sektor akibat bencana perlu dibangun kembali menjadi lebih baik dan lebih aman;
c. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana dalam implementasinya sudah tidak sesuai dengan kondisi dan kebutuhan saat ini, sehingga perlu diganti;
d. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, dan huruf c perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana;');
