INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3806, 'perban-5-2017', 2, 'mengingat', 'Mengingat', NULL, 2, '2017, No.1570 -2-
1. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
2. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
3. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
4. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3806, '2017, No.1570 -2-
1. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
2. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
3. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
4. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3807, 'perban-5-2017', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENYUSUNAN RENCANA REHABILITASI DAN REKONSTRUKSI PASCABENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3807, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENYUSUNAN RENCANA REHABILITASI DAN REKONSTRUKSI PASCABENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3808, 'perban-5-2017', 4, 'pasal', 'Pasal 1', 'BAB II TAHAPAN DAN TIM PENYUSUN RENCANA REHABILITASI DAN REKONSTRUKSI PASCABENCANA; Bagian Kesatu Tahapan', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan 2017, No.1570 penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, rehabilitasi dan rekonstruksi.
3. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pascabencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan, kehidupan dan penghidupan masyarakat pada wilayah pascabencana.
4. Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta masyarakat dalam segala aspek kehidupan bermasyarakat pada wilayah pascabencana.
5. Pengkajian Kebutuhan Pascabencana yang selanjutnya disebut Jitupasna adalah suatu rangkaian kegiatan pengkajian dan penilaian akibat, analisis dampak, perkiraan kebutuhan, dan rekomendasi awal terhadap strategi pemulihan yang menjadi dasar penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana.
6. Rencana Rehabilitasi dan Rekonstruksi Pascabencana adalah dokumen perencanaan yang disusun secara bersama antara Badan Nasional Penanggulangan Bencana/Badan Penanggulangan Bencana Daerah bersama kementerian/lembaga, perangkat daerah serta pemangku kepentingan lainnya berdasarkan atas pengkajian kebutuhan pascabencana untuk periode waktu 2017, No.1570 -4- tertentu.
7. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sesuai dengan ketentuan peraturan perundang-undangan.
8. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan Penanggulangan Bencana di daerah.
9. Anggaran Pendapatan dan Belanja Negara adalah rencana keuangan tahunan pemerintahan negara yang disetujui oleh Dewan Perwakilan Rakyat.
10. Anggaran Pendapatan dan Belanja Daerah adalah rencana keuangan tahunan pemerintahan daerah yang disetujui oleh Dewan Perwakilan Rakyat Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3808, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan 2017, No.1570 penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, rehabilitasi dan rekonstruksi.
3. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pascabencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan, kehidupan dan penghidupan masyarakat pada wilayah pascabencana.
4. Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta masyarakat dalam segala aspek kehidupan bermasyarakat pada wilayah pascabencana.
5. Pengkajian Kebutuhan Pascabencana yang selanjutnya disebut Jitupasna adalah suatu rangkaian kegiatan pengkajian dan penilaian akibat, analisis dampak, perkiraan kebutuhan, dan rekomendasi awal terhadap strategi pemulihan yang menjadi dasar penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana.
6. Rencana Rehabilitasi dan Rekonstruksi Pascabencana adalah dokumen perencanaan yang disusun secara bersama antara Badan Nasional Penanggulangan Bencana/Badan Penanggulangan Bencana Daerah bersama kementerian/lembaga, perangkat daerah serta pemangku kepentingan lainnya berdasarkan atas pengkajian kebutuhan pascabencana untuk periode waktu 2017, No.1570 -4- tertentu.
7. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sesuai dengan ketentuan peraturan perundang-undangan.
8. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan Penanggulangan Bencana di daerah.
9. Anggaran Pendapatan dan Belanja Negara adalah rencana keuangan tahunan pemerintahan negara yang disetujui oleh Dewan Perwakilan Rakyat.
10. Anggaran Pendapatan dan Belanja Daerah adalah rencana keuangan tahunan pemerintahan daerah yang disetujui oleh Dewan Perwakilan Rakyat Daerah.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3809, 'perban-5-2017', 5, 'pasal', 'Pasal 2', 'BAB II TAHAPAN DAN TIM PENYUSUN RENCANA REHABILITASI DAN REKONSTRUKSI PASCABENCANA; Bagian Kedua Tim Penyusun', 4, '(1) Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana dilakukan melalui tahap:
a. persiapan;
b. penyusunan rancangan;
c. penyajian rancangan;
d. konsultasi atau konsolidasi;
e. finalisasi; dan
f. penetapan.
(2) Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana sebagaimana dimaksud pada ayat (1), paling lama 90 (sembilan puluh) hari.
(3) Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana dimulai pada saat tanggap darurat.
2017, No.1570');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3809, '(1) Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana dilakukan melalui tahap:
a. persiapan;
b. penyusunan rancangan;
c. penyajian rancangan;
d. konsultasi atau konsolidasi;
e. finalisasi; dan
f. penetapan.
(2) Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana sebagaimana dimaksud pada ayat (1), paling lama 90 (sembilan puluh) hari.
(3) Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana dimulai pada saat tanggap darurat.
2017, No.1570', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3810, 'perban-5-2017', 6, 'pasal', 'Pasal 3', 'BAB III DOKUMEN RENCANA REHABILITASI DAN REKONSTRUKSI PASCABENCANA; Bagian Kesatu Umum', 5, '(1) Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana dilaksanakan oleh tim yang terdiri atas:
a. pemerintah; dan/atau
b. pemerintah daerah.
(2) Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana sebagaimana dimaksud pada ayat (1) huruf a, terdiri atas BNPB, Badan Perencanaan Pembangunan Nasional, kementerian/lembaga terkait, dan melibatkan masyarakat serta dunia usaha untuk skala nasional.
(3) Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana sebagaimana dimaksud pada ayat (1) huruf b, terdiri atas BPBD, Badan Perencanaan Pembangunan Daerah, perangkat daerah terkait di tingkat provinsi/kabupaten/kota wilayah terdampak, dan melibatkan masyarakat serta dunia usaha untuk skala provinsi/kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3810, '(1) Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana dilaksanakan oleh tim yang terdiri atas:
a. pemerintah; dan/atau
b. pemerintah daerah.
(2) Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana sebagaimana dimaksud pada ayat (1) huruf a, terdiri atas BNPB, Badan Perencanaan Pembangunan Nasional, kementerian/lembaga terkait, dan melibatkan masyarakat serta dunia usaha untuk skala nasional.
(3) Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana sebagaimana dimaksud pada ayat (1) huruf b, terdiri atas BPBD, Badan Perencanaan Pembangunan Daerah, perangkat daerah terkait di tingkat provinsi/kabupaten/kota wilayah terdampak, dan melibatkan masyarakat serta dunia usaha untuk skala provinsi/kabupaten/kota.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3811, 'perban-5-2017', 7, 'pasal', 'Pasal 4', 'BAB III DOKUMEN RENCANA REHABILITASI DAN REKONSTRUKSI PASCABENCANA; Bagian Kedua Penanggung jawab', 5, 'Rencana Rehabilitasi dan Rekonstruksi Pascabencana terdiri atas:
a. Rencana Rehabilitasi dan Rekonstruksi Pascabencana skala nasional;
b. Rencana Rehabilitasi dan Rekonstruksi Pascabencana skala provinsi; dan 2017, No.1570 -6-
c. Rencana Rehabilitasi dan Rekonstruksi Pascabencana skala kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3811, 'Rencana Rehabilitasi dan Rekonstruksi Pascabencana terdiri atas:
a. Rencana Rehabilitasi dan Rekonstruksi Pascabencana skala nasional;
b. Rencana Rehabilitasi dan Rekonstruksi Pascabencana skala provinsi; dan 2017, No.1570 -6-
c. Rencana Rehabilitasi dan Rekonstruksi Pascabencana skala kabupaten/kota.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3812, 'perban-5-2017', 8, 'pasal', 'Pasal 5', 'BAB III DOKUMEN RENCANA REHABILITASI DAN REKONSTRUKSI PASCABENCANA; Bagian Ketiga Penetapan', 6, '(1) Penanggung jawab penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana skala nasional dilakukan oleh Kepala BNPB.
(2) Penanggung jawab penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana skala provinsi dilakukan oleh gubernur.
(3) Penanggung jawab penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana skala kabupaten/kota dilakukan oleh bupati/walikota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3812, '(1) Penanggung jawab penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana skala nasional dilakukan oleh Kepala BNPB.
(2) Penanggung jawab penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana skala provinsi dilakukan oleh gubernur.
(3) Penanggung jawab penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana skala kabupaten/kota dilakukan oleh bupati/walikota.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3813, 'perban-5-2017', 9, 'pasal', 'Pasal 6', 'BAB III DOKUMEN RENCANA REHABILITASI DAN REKONSTRUKSI PASCABENCANA; Bagian Keempat Kedudukan', 6, '(1) Penetapan Rencana Rehabilitasi dan Rekonstruksi Pascabencana dilaksanakan oleh Pemerintah atau pemerintah daerah.
(2) Penetapan sebagaimana dimaksud pada ayat (1) melalui keputusan yang ditandatangani oleh:
a. Kepala BNPB untuk skala nasional;
b. gubernur untuk skala provinsi; atau
c. bupati/wali kota untuk skala kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3813, '(1) Penetapan Rencana Rehabilitasi dan Rekonstruksi Pascabencana dilaksanakan oleh Pemerintah atau pemerintah daerah.
(2) Penetapan sebagaimana dimaksud pada ayat (1) melalui keputusan yang ditandatangani oleh:
a. Kepala BNPB untuk skala nasional;
b. gubernur untuk skala provinsi; atau
c. bupati/wali kota untuk skala kabupaten/kota.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3814, 'perban-5-2017', 10, 'pasal', 'Pasal 7', 'BAB III DOKUMEN RENCANA REHABILITASI DAN REKONSTRUKSI PASCABENCANA; Bagian Keempat Kedudukan', 6, 'Kedudukan dokumen Rencana Rehabilitasi dan Rekonstruksi Pascabencana yaitu sebagai:
2017, No.1570
a. acuan penyelenggaraan rehabilitasi dan rekonstruksi pascabencana berdasarkan kewenangan dan tanggung jawab Pemerintah, pemerintah daerah, masyarakat dan dunia usaha;
b. dokumen perencanaan yang diintegrasikan dengan Rencana Pembangunan Jangka Menengah Nasional atau Rencana Pembangunan Jangka Menengah Daerah provinsi dan kabupaten/kota wilayah terdampak bencana;
c. dokumen perencanaan yang diintegrasikan dengan rencana kerja Pemerintah dan/atau pemerintah daerah serta perencanaan pembangunan sektor terkait; dan
d. acuan untuk penganggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara, Anggaran Pendapatan dan Belanja Daerah, dan Hibah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3814, 'Kedudukan dokumen Rencana Rehabilitasi dan Rekonstruksi Pascabencana yaitu sebagai:
2017, No.1570
a. acuan penyelenggaraan rehabilitasi dan rekonstruksi pascabencana berdasarkan kewenangan dan tanggung jawab Pemerintah, pemerintah daerah, masyarakat dan dunia usaha;
b. dokumen perencanaan yang diintegrasikan dengan Rencana Pembangunan Jangka Menengah Nasional atau Rencana Pembangunan Jangka Menengah Daerah provinsi dan kabupaten/kota wilayah terdampak bencana;
c. dokumen perencanaan yang diintegrasikan dengan rencana kerja Pemerintah dan/atau pemerintah daerah serta perencanaan pembangunan sektor terkait; dan
d. acuan untuk penganggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara, Anggaran Pendapatan dan Belanja Daerah, dan Hibah.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3815, 'perban-5-2017', 11, 'pasal', 'Pasal 8', 'BAB III DOKUMEN RENCANA REHABILITASI DAN REKONSTRUKSI PASCABENCANA; Bagian Kelima Jitupasna', 7, '(1) Isi dokumen Rencana Rehabilitasi dan Rekonstruksi Pascabencana mencakup:
a. kondisi wilayah dan kejadian bencana;
b. Jitupasna;
c. prinsip, kebijakan dan strategi; dan
d. penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana.
(2) Ruang lingkup Rencana Rehabilitasi dan Rekonstruksi Pascabencana meliputi:
a. sektor permukiman, merupakan perbaikan lingkungan daerah terdampak bencana, pemberian bantuan perbaikan rumah masyarakat, dan pembangunan kembali sarana sosial masyarakat;
b. sektor infrastruktur, merupakan perbaikan dan peningkatan kembali prasarana dan sarana umum untuk pemulihan fungsi pelayanan publik seperti transportasi darat, laut, udara, pos, telekomunikasi, energi, sumber daya air, air bersih dan sanitasi;
c. sektor ekonomi, merupakan pemulihan dan peningkatan ekonomi lokal, perdagangan dan pasar, usaha kecil dan menengah, pertanian, perikanan, peternakan, perkebunan dan pariwisata;
2017, No.1570 -8-
d. sektor sosial, merupakan pemulihan psikologis sosial, konstruksi sosial dan budaya, perbaikan dan peningkatan pelayanan kesehatan, pendidikan dan agama, pemulihan kearifan lokal dan tradisi masyarakat, pemulihan hubungan antara budaya dan keagamaan, serta membangkitkan kembali kehidupan sosial budaya masyarakat; dan
e. lintas sektor, merupakan pemulihan kegiatan tata pemerintahan keuangan dan perbankan, lingkungan hidup dan Pengurangan Risiko Bencana serta ketertiban dan keamanan.
(3) Rencana Rehabilitasi dan Rekonstruksi Pascabencana dalam rangka membangun kembali lebih baik dan lebih aman harus memperhatikan:
a. hasil Jitupasna;
b. lingkungan hidup dan daerah aliran sungai;
c. rencana pembangunan jangka menengah nasional dan/atau rencana pembangunan jangka menengah daerah provinsi dan kabupaten/kota;
d. rencana tata ruang nasional dan/atau rencana tata ruang provinsi/kabupaten/kota;
e. perencanaan sektor yang ada;
f. kajian risiko Bencana;
g. kesehatan masyarakat dan lingkungan sehat;
h. kondisi sosial, adat istiadat dan budaya lokal;
i. kondisi ekonomi lokal;
j. peraturan perundang-undangan dan standar nasional Indonesia mengenai penyelenggaraan bangunan gedung dan infrastruktur yang berlaku; dan
k. standar pelayanan minimal yang ditetapkan pemerintah dan/atau pemerintah daerah.
2017, No.1570');
