(6) Ketentuan lebih lanjut mengenai Jitupasna sebagaimana dimaksud pada ayat (1) diatur dengan Petunjuk Pelaksanaan.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3817, 'perban-5-2017', 13, 'pasal', 'Pasal 10', 'BAB III DOKUMEN RENCANA REHABILITASI DAN REKONSTRUKSI PASCABENCANA; Bagian Ketujuh Pendanaan', 9, 'Rencana Rehabilitasi dan Rekonstruksi Pascabencana merupakan suatu dokumen perencanaan penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana yang disusun 2017, No.1570 -10- untuk jangka waktu paling lama 3 (tiga) tahun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3817, 'Rencana Rehabilitasi dan Rekonstruksi Pascabencana merupakan suatu dokumen perencanaan penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana yang disusun 2017, No.1570 -10- untuk jangka waktu paling lama 3 (tiga) tahun.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3818, 'perban-5-2017', 14, 'pasal', 'Pasal 11', 'BAB IV KETENTUAN PENUTUP', 10, 'Sumber dana untuk penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana berasal dari:
a. Anggaran Pendapatan dan Belanja Negara; dan
b. Anggaran Pendapatan dan Belanja Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3818, 'Sumber dana untuk penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana berasal dari:
a. Anggaran Pendapatan dan Belanja Negara; dan
b. Anggaran Pendapatan dan Belanja Daerah.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3819, 'perban-5-2017', 15, 'pasal', 'Pasal 12', 'BAB IV KETENTUAN PENUTUP', 10, 'Pada saat Peraturan Badan ini mulai berlaku Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana (Berita Negara Republik Indonesia Tahun 2010 Nomor 1553) dicabut dan dinyatakan tidak berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3819, 'Pada saat Peraturan Badan ini mulai berlaku Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana (Berita Negara Republik Indonesia Tahun 2010 Nomor 1553) dicabut dan dinyatakan tidak berlaku.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3820, 'perban-5-2017', 16, 'pasal', 'Pasal 13', 'BAB IV KETENTUAN PENUTUP', 10, 'Pada saat Peraturan Badan ini mulai berlaku semua Peraturan Kepala Badan yang berkaitan secara langsung dengan rencana Rehabilitasi dan Rekonstruksi mendasarkan dan menyesuaikan pengaturannya pada Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3820, 'Pada saat Peraturan Badan ini mulai berlaku semua Peraturan Kepala Badan yang berkaitan secara langsung dengan rencana Rehabilitasi dan Rekonstruksi mendasarkan dan menyesuaikan pengaturannya pada Peraturan Badan ini.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3821, 'perban-5-2017', 17, 'pasal', 'Pasal 14', 'BAB IV KETENTUAN PENUTUP', 10, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
