INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3822, 'perban-5-2017', 18, 'lain', 'Penutup', NULL, 11, 'Ditetapkan di Jakarta pada tanggal 7 November 2017 BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd.
WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 8 November 2017 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd.
WIDODO EKATJAHJANA');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3822, 'Ditetapkan di Jakarta pada tanggal 7 November 2017 BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd.
WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 8 November 2017 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd.
WIDODO EKATJAHJANA', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2017 tentang Penyusunan Rencana Rehabilitasi dan Rekonstruksi Pascabencana');
