INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3824, 'perban-5-2018', 1, 'menimbang', 'Menimbang', NULL, 1, 'bahwa untuk melaksanakan ketentuan Pasal 3 ayat (4) Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3824, 'bahwa untuk melaksanakan ketentuan Pasal 3 ayat (4) Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3825, 'perban-5-2018', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 2018, No.1644 -2- 4828);
3. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan Dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
4. Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu (Lembaran Negara Republik Indonesia Tahun 2018 Nomor 34);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3825, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 2018, No.1644 -2- 4828);
3. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan Dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
4. Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu (Lembaran Negara Republik Indonesia Tahun 2018 Nomor 34);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3826, 'perban-5-2018', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG KONDISI DAN TATA CARA PELAKSANAAN PENYELENGGARAAN PENANGGULANGAN BENCANA DALAM KEADAAN TERTENTU.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3826, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG KONDISI DAN TATA CARA PELAKSANAAN PENYELENGGARAAN PENANGGULANGAN BENCANA DALAM KEADAAN TERTENTU.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3827, 'perban-5-2018', 4, 'pasal', 'Pasal 1', 'BAB II RUANG LINGKUP', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu adalah serangkaian upaya penyelenggaraan pada saat status keadaan darurat bencana belum ditetapkan atau status keadaan darurat bencana telah berakhir dan/atau tidak diperpanjang, namun diperlukan atau masih diperlukan tindakan guna mengurangi risiko bencana dan dampak yang lebih luas.
2. Kondisi adalah persyaratan atau keadaan yang harus dipenuhi.
3. Tata Cara adalah aturan atau langkah demi langkah pelaksanaan kegiatan dalam penyelenggaraan penanggulangan bencana dalam keadaan tertentu.
2018, No.1644');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3827, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu adalah serangkaian upaya penyelenggaraan pada saat status keadaan darurat bencana belum ditetapkan atau status keadaan darurat bencana telah berakhir dan/atau tidak diperpanjang, namun diperlukan atau masih diperlukan tindakan guna mengurangi risiko bencana dan dampak yang lebih luas.
2. Kondisi adalah persyaratan atau keadaan yang harus dipenuhi.
3. Tata Cara adalah aturan atau langkah demi langkah pelaksanaan kegiatan dalam penyelenggaraan penanggulangan bencana dalam keadaan tertentu.
2018, No.1644', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3828, 'perban-5-2018', 5, 'pasal', 'Pasal 2', 'BAB III KONDISI KEADAAN TERTENTU', 3, 'Ruang lingkup Peraturan Badan ini meliputi:
a. kondisi keadaan tertentu;
b. tata cara pelaksanaan penyelenggaraan;
c. rapat koordinasi;
d. peran pemerintah dan pemerintah daerah;
e. kemudahan akses; dan
f. pendanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3828, 'Ruang lingkup Peraturan Badan ini meliputi:
a. kondisi keadaan tertentu;
b. tata cara pelaksanaan penyelenggaraan;
c. rapat koordinasi;
d. peran pemerintah dan pemerintah daerah;
e. kemudahan akses; dan
f. pendanaan.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3829, 'perban-5-2018', 6, 'pasal', 'Pasal 3', 'BAB IV TATA CARA PELAKSANAAN PENYELENGGARAAN', 3, '(1) Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu dilakukan pada kondisi terdapat adanya potensi bencana dengan tingkat ancaman maksimum dan telah terjadi evakuasi/penyelamatan/ pengungsian atau gangguan fungsi pelayanan umum yang berdampak luas terhadap kehidupan sosial, ekonomi dan budaya masyarakat.
(2) Potensi bencana dengan tingkat ancaman maksimum sebagaimana dimaksud pada ayat (1) meliputi adanya:
a. peringatan dini yang dikeluarkan oleh kementerian/lembaga yang berwenang, yang terdiri atas:
1. ancaman bencana erupsi gunung berapi, yang berdasarkan kajian dan/atau analisis terhadap peningkatan aktivitas vulkanik, tingkat pencemaran udara, abu vulkanik, dan status level siaga ataupun awas;
2. ancaman bencana tanah longsor akibat hujan dan/atau akibat gempa, yang berdasarkan kajian dan/atau analisis terhadap curah hujan dan rekahan tanah;
2018, No.1644 -4-
3. ancaman bencana banjir, yang berdasarkan kajian dan/atau analisis terhadap curah hujan;
4. ancaman bencana banjir bandang, yang berdasarkan kajian dan/atau analisis terhadap curah hujan dan kondisi sarana dan prasarana dalam kondisi kritis;
5. kebakaran lahan dan hutan, yang berdasarkan kajian dan/atau analisis terhadap titik api dan tingkat pencemaran udara;
6. ancaman bencana gempa bumi, yang berdasarkan kajian dan/atau analisis terhadap peta risiko gempa bumi yang terkini dan skala intensitas gempa;
7. ancaman bencana tsunami, yang berdasarkan kajian dan/atau analisis terhadap peta risiko gempa bumi dan tsunami terkini serta intensitas gempa bumi dan tsunami;
8. ancaman bencana gelombang pasang/badai, yang berdasarkan kajian dan/atau analisis terhadap cuaca yang berdampak kepada gelombang laut ;
9. ancaman bencana kekeringan, yang berdasarkan kajian dan/atau analisis terhadap terjadinya kemarau panjang; dan
10. ancaman bencana wabah, epidemi, kegagalan teknologi, ledakan nuklir, kejadian antariksa/benda-benda angkasa, yang menghasilkan dampak kepada masyarakat,
b. ancaman bencana yang masih berlangsung; dan
c. ancaman bencana sebagaimana dimaksud pada huruf b berpotensi dan/atau berdampak menimbulkan korban, pengungsi, kerusakan dan gangguan pelayanan umum yang dapat mengganggu kehidupan dan penghidupan.
(3) Telah terjadi evakuasi/penyelamatan/pengungsian atau gangguan fungsi pelayanan umum yang berdampak luas terhadap kehidupan sosial, ekonomi dan budaya 2018, No.1644 masyarakat, yang berdasarkan laporan Badan Penanggulangan Bencana Daerah/masyarakat kepada Badan Nasional Penanggulangan Bencana yang paling sedikit meliputi:
a. adanya korban meninggal dunia dan luka berat;
b. adanya pengungsian yang memerlukan pemenuhan kebutuhan dasar;
c. adanya kerusakan sarana prasarana vital jalan, bandara, pelabuhan dan terminal;
d. adanya gangguan fungsi pelayanan umum dan pemerintahan; dan
e. perlunya pemulihan dengan segera prasarana dan sarana vital.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3829, '(1) Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu dilakukan pada kondisi terdapat adanya potensi bencana dengan tingkat ancaman maksimum dan telah terjadi evakuasi/penyelamatan/ pengungsian atau gangguan fungsi pelayanan umum yang berdampak luas terhadap kehidupan sosial, ekonomi dan budaya masyarakat.
(2) Potensi bencana dengan tingkat ancaman maksimum sebagaimana dimaksud pada ayat (1) meliputi adanya:
a. peringatan dini yang dikeluarkan oleh kementerian/lembaga yang berwenang, yang terdiri atas:
1. ancaman bencana erupsi gunung berapi, yang berdasarkan kajian dan/atau analisis terhadap peningkatan aktivitas vulkanik, tingkat pencemaran udara, abu vulkanik, dan status level siaga ataupun awas;
2. ancaman bencana tanah longsor akibat hujan dan/atau akibat gempa, yang berdasarkan kajian dan/atau analisis terhadap curah hujan dan rekahan tanah;
2018, No.1644 -4-
3. ancaman bencana banjir, yang berdasarkan kajian dan/atau analisis terhadap curah hujan;
4. ancaman bencana banjir bandang, yang berdasarkan kajian dan/atau analisis terhadap curah hujan dan kondisi sarana dan prasarana dalam kondisi kritis;
5. kebakaran lahan dan hutan, yang berdasarkan kajian dan/atau analisis terhadap titik api dan tingkat pencemaran udara;
6. ancaman bencana gempa bumi, yang berdasarkan kajian dan/atau analisis terhadap peta risiko gempa bumi yang terkini dan skala intensitas gempa;
7. ancaman bencana tsunami, yang berdasarkan kajian dan/atau analisis terhadap peta risiko gempa bumi dan tsunami terkini serta intensitas gempa bumi dan tsunami;
8. ancaman bencana gelombang pasang/badai, yang berdasarkan kajian dan/atau analisis terhadap cuaca yang berdampak kepada gelombang laut ;
9. ancaman bencana kekeringan, yang berdasarkan kajian dan/atau analisis terhadap terjadinya kemarau panjang; dan
10. ancaman bencana wabah, epidemi, kegagalan teknologi, ledakan nuklir, kejadian antariksa/benda-benda angkasa, yang menghasilkan dampak kepada masyarakat,
b. ancaman bencana yang masih berlangsung; dan
c. ancaman bencana sebagaimana dimaksud pada huruf b berpotensi dan/atau berdampak menimbulkan korban, pengungsi, kerusakan dan gangguan pelayanan umum yang dapat mengganggu kehidupan dan penghidupan.
(3) Telah terjadi evakuasi/penyelamatan/pengungsian atau gangguan fungsi pelayanan umum yang berdampak luas terhadap kehidupan sosial, ekonomi dan budaya 2018, No.1644 masyarakat, yang berdasarkan laporan Badan Penanggulangan Bencana Daerah/masyarakat kepada Badan Nasional Penanggulangan Bencana yang paling sedikit meliputi:
a. adanya korban meninggal dunia dan luka berat;
b. adanya pengungsian yang memerlukan pemenuhan kebutuhan dasar;
c. adanya kerusakan sarana prasarana vital jalan, bandara, pelabuhan dan terminal;
d. adanya gangguan fungsi pelayanan umum dan pemerintahan; dan
e. perlunya pemulihan dengan segera prasarana dan sarana vital.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3830, 'perban-5-2018', 7, 'pasal', 'Pasal 4', 'BAB V RAPAT KOORDINASI', 5, '(1) Tata Cara pelaksanaan Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu, meliputi:
a. telah diterima informasi dan rekomendasi peringatan dini/status ancaman bencana dari kementerian/lembaga yang berwenang secara teknis; dan
b. telah dilakukan kaji cepat oleh Badan Nasional Penanggulangan Bencana/Badan Penanggulangan Bencana Daerah dengan melibatkan instansi terkait sesuai kewenangannya dengan memperhitungkan kemampuan sumber daya daerah terdampak.
(2) Hasil kaji cepat sebagaimana dimaksud pada ayat (1) huruf b digunakan sebagai bahan rapat koordinasi kementerian/lembaga/daerah terkait dipimpin oleh Menteri Koordinator yang membidangi Penyelenggaraan Penanggulangan Bencana untuk menentukan penetapan status keadaan tertentu.
2018, No.1644 -6-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3830, '(1) Tata Cara pelaksanaan Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu, meliputi:
a. telah diterima informasi dan rekomendasi peringatan dini/status ancaman bencana dari kementerian/lembaga yang berwenang secara teknis; dan
b. telah dilakukan kaji cepat oleh Badan Nasional Penanggulangan Bencana/Badan Penanggulangan Bencana Daerah dengan melibatkan instansi terkait sesuai kewenangannya dengan memperhitungkan kemampuan sumber daya daerah terdampak.
(2) Hasil kaji cepat sebagaimana dimaksud pada ayat (1) huruf b digunakan sebagai bahan rapat koordinasi kementerian/lembaga/daerah terkait dipimpin oleh Menteri Koordinator yang membidangi Penyelenggaraan Penanggulangan Bencana untuk menentukan penetapan status keadaan tertentu.
2018, No.1644 -6-', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3831, 'perban-5-2018', 8, 'pasal', 'Pasal 5', 'BAB V RAPAT KOORDINASI', 6, '(1) Rapat koordinasi dilaksanakan untuk menentukan penetapan Status Keadaan Tertentu.
(2) Rapat koordinasi sebagaimana dimaksud pada ayat (1) dilaksanakan atas inisiatif Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3831, '(1) Rapat koordinasi dilaksanakan untuk menentukan penetapan Status Keadaan Tertentu.
(2) Rapat koordinasi sebagaimana dimaksud pada ayat (1) dilaksanakan atas inisiatif Badan Nasional Penanggulangan Bencana.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3832, 'perban-5-2018', 9, 'pasal', 'Pasal 6', 'BAB V RAPAT KOORDINASI', 6, 'Susunan anggota rapat koordinasi meliputi:
a. Kementerian Koordinator;
b. Badan Nasional Penanggulangan Bencana;
c. Kementerian Dalam Negeri;
d. Kementerian Keuangan;
e. Kementerian Kesehatan;
