INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3833, 'perban-5-2018', 10, 'pasal', 'Pasal 7', 'BAB V RAPAT KOORDINASI', 7, '(1) Penentuan Status Keadaan Tertentu berdasarkan keputusan yang diambil pada rapat koordinasi.
(2) Berdasarkan keputusan hasil rapat koordinasi sebagaimana dimaksud pada ayat (1), Kepala BNPB menetapkan Status Keadaan Tertentu dengan surat keputusan.
(3) Surat Keputusan Kepala Badan Nasional Penanggulangan Bencana sebagaimana dimaksud pada ayat (2) menentukan waktu dimulai dan diakhirinya Status Keadaan Tertentu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3833, '(1) Penentuan Status Keadaan Tertentu berdasarkan keputusan yang diambil pada rapat koordinasi.
(2) Berdasarkan keputusan hasil rapat koordinasi sebagaimana dimaksud pada ayat (1), Kepala BNPB menetapkan Status Keadaan Tertentu dengan surat keputusan.
(3) Surat Keputusan Kepala Badan Nasional Penanggulangan Bencana sebagaimana dimaksud pada ayat (2) menentukan waktu dimulai dan diakhirinya Status Keadaan Tertentu.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3834, 'perban-5-2018', 11, 'pasal', 'Pasal 8', 'BAB VI PERAN PEMERINTAH DAN PEMERINTAH DAERAH', 7, 'Dalam hal Pelaksanaan Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu, Badan Nasional Penanggulangan Bencana dapat mengaktifkan sistem komando penanganan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3834, 'Dalam hal Pelaksanaan Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu, Badan Nasional Penanggulangan Bencana dapat mengaktifkan sistem komando penanganan darurat bencana.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3835, 'perban-5-2018', 12, 'pasal', 'Pasal 9', 'BAB VI PERAN PEMERINTAH DAN PEMERINTAH DAERAH', 7, 'Badan Nasional Penanggulangan Bencana berwenang mengoordinasikan pelaksanaan pendampingan Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3835, 'Badan Nasional Penanggulangan Bencana berwenang mengoordinasikan pelaksanaan pendampingan Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3836, 'perban-5-2018', 13, 'pasal', 'Pasal 10', 'BAB VII KEMUDAHAN AKSES', 7, '(1) Pemerintah daerah terdampak bencana merupakan penanggung jawab utama terhadap Penyelenggaraan Penanggulangan Bencana sesuai dengan ketentuan peraturan perundang-undangan.
(2) Pelaksanaan Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu tidak mengurangi kewenangan Kepala Daerah.
2018, No.1644 -8-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3836, '(1) Pemerintah daerah terdampak bencana merupakan penanggung jawab utama terhadap Penyelenggaraan Penanggulangan Bencana sesuai dengan ketentuan peraturan perundang-undangan.
(2) Pelaksanaan Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu tidak mengurangi kewenangan Kepala Daerah.
2018, No.1644 -8-', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3837, 'perban-5-2018', 14, 'pasal', 'Pasal 11', 'BAB VIII PENDANAAN', 8, '(1) Pada saat Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu ditetapkan, Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah mempunyai kemudahan akses sesuai dengan ketentuan peraturan perundang-undangan.
(2) Kemudahan akses sebagaimana dimaksud pada ayat (1) diselenggarakan sesuai ketentuan yang berlaku, antara lain meliputi:
a. pengerahan sumber daya manusia;
b. pengerahan peralatan;
c. pengerahan logistik;
d. imigrasi, cukai dan karantina;
e. perizinan;
f. pengadaan barang/jasa;
g. pengelolaan dan pertanggungjawaban uang dan/atau barang;
h. penyelamatan; dan
i. komando untuk mengoordinasikan sektor/lembaga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3837, '(1) Pada saat Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu ditetapkan, Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah mempunyai kemudahan akses sesuai dengan ketentuan peraturan perundang-undangan.
(2) Kemudahan akses sebagaimana dimaksud pada ayat (1) diselenggarakan sesuai ketentuan yang berlaku, antara lain meliputi:
a. pengerahan sumber daya manusia;
b. pengerahan peralatan;
c. pengerahan logistik;
d. imigrasi, cukai dan karantina;
e. perizinan;
f. pengadaan barang/jasa;
g. pengelolaan dan pertanggungjawaban uang dan/atau barang;
h. penyelamatan; dan
i. komando untuk mengoordinasikan sektor/lembaga.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3838, 'perban-5-2018', 15, 'pasal', 'Pasal 12', 'BAB IX KETENTUAN PENUTUP', 8, '(1) Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah menggunakan APBN/APBD dan sumber dana lain yang tidak mengikat untuk melaksanakan Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu sesuai ketentuan yang berlaku.
(2) Tata Cara penggunaan APBN/APBD dan sumber dana lain yang tidak mengikat untuk Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu sebagaimana dimaksud pada ayat (1) dilaksanakan 2018, No.1644 sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3838, '(1) Badan Nasional Penanggulangan Bencana dan Badan Penanggulangan Bencana Daerah menggunakan APBN/APBD dan sumber dana lain yang tidak mengikat untuk melaksanakan Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu sesuai ketentuan yang berlaku.
(2) Tata Cara penggunaan APBN/APBD dan sumber dana lain yang tidak mengikat untuk Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu sebagaimana dimaksud pada ayat (1) dilaksanakan 2018, No.1644 sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2018 tentang Kondisi dan Tata Cara Pelaksanaan Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3839, 'perban-5-2018', 16, 'pasal', 'Pasal 13', 'BAB IX KETENTUAN PENUTUP', 9, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya pada Berita Negara Republik Indonesia.');
