INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3845, 'perban-5-2020', 4, 'pasal', 'Pasal 1', NULL, 3, 'Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2020-2024 merupakan dokumen perencanaan Badan Nasional Penanggulangan Bencana untuk periode 5 (lima) tahun, yakni tahun 2020 sampai dengan tahun 2024.');
