INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3846, 'perban-5-2020', 5, 'pasal', 'Pasal 2', NULL, 3, 'Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2020-2024 sebagaimana dimaksud dalam Pasal 1 tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
