INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3850, 'perban-5-2020', 9, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, J-'')) \-74%,„0 ‘-‘ Zahermann Muabezi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3850, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi, dan Kerja Sama, J-'')) \-74%,„0 ‘-‘ Zahermann Muabezi', 'Lampiran hal. 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3851, 'perban-5-2020', 10, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR TAHUN 2020 TENTANG RENCANA STRATEGIS BADAN NASIONAL PENANGGULANGAN BENCANA TAHUN 2020-2024 RENCANA STRATEGIS BADAN NASIONAL PENANGGULANGAN BENCANA TAHUN 2020-2024 BAB I PENDAHULUAN 1.1. Kondisi Umum Secara geografis, termasuk geologis dan demografis Indonesia merupakan wilayah yang rawan terjadi bencana, baik yang disebabkan oleh faktor alam, non alam maupun faktor manusia. Bencana yang terjadi umumnya mempunyai dampak yang merugikan dengan adanya korban jiwa, luka-luka dan hilang.
Selain manusia yang menjadi korban, sering pula menimbulkan terjadinya kehilangan harta benda, kerusakan bangunan serta prasarana dan sarana layanan masyarakat seperti jalan, jembatan, rumah sakit, puskesmas, sekolah, tempat ibadah, gedung perkantoran dan lain-lain. Kejadian bencana juga sangat berkaitan erat dengan perlunya penyediaan penampungan, makanan, pakaian, obat-obatan bagi masyarakat yang terlanda bencana terutama bila terjadi pengungsian ketempat yang lebih aman untuk sementara waktu. Lebih lanjut tentunya kejadian-kejadian bencana akan berdampak terhadap pencapaian pembangunan nasional.
1. .1. Ancaman Bencana Gambaran ancaman bencana di Indonesia antara lain:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3851, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR TAHUN 2020 TENTANG RENCANA STRATEGIS BADAN NASIONAL PENANGGULANGAN BENCANA TAHUN 2020-2024 RENCANA STRATEGIS BADAN NASIONAL PENANGGULANGAN BENCANA TAHUN 2020-2024 BAB I PENDAHULUAN 1.1. Kondisi Umum Secara geografis, termasuk geologis dan demografis Indonesia merupakan wilayah yang rawan terjadi bencana, baik yang disebabkan oleh faktor alam, non alam maupun faktor manusia. Bencana yang terjadi umumnya mempunyai dampak yang merugikan dengan adanya korban jiwa, luka-luka dan hilang.
Selain manusia yang menjadi korban, sering pula menimbulkan terjadinya kehilangan harta benda, kerusakan bangunan serta prasarana dan sarana layanan masyarakat seperti jalan, jembatan, rumah sakit, puskesmas, sekolah, tempat ibadah, gedung perkantoran dan lain-lain. Kejadian bencana juga sangat berkaitan erat dengan perlunya penyediaan penampungan, makanan, pakaian, obat-obatan bagi masyarakat yang terlanda bencana terutama bila terjadi pengungsian ketempat yang lebih aman untuk sementara waktu. Lebih lanjut tentunya kejadian-kejadian bencana akan berdampak terhadap pencapaian pembangunan nasional.
1. .1. Ancaman Bencana Gambaran ancaman bencana di Indonesia antara lain:', 'Lampiran hal. 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3852, 'perban-5-2020', 11, 'lampiran', 'Lampiran hal. 5', NULL, 5, '1) Gempa Bumi dan Tsunami Indonesia terletak pada pertemuan lempeng besar dunia dan beberapa lempeng kecil yang menyebabkan Indonesia merupakan wilayah rawan 6 terhadap terjadi gempa bumi dan tsunami. Indonesia di kelilingi lempeng utama yaitu lempeng Eurasia, Indo-Australia, Laut Filipina, Pasifik dan microplate Sunda. Pertemuan lempeng benua Eurasia membentuk busur vulkanik di Indonesia bagian Barat, yang merupakan salah satu daerah paling aktif secara seismik di planet ini.
Selain itu, dari hasil penelitian diketahui bahwa di wilayah Indonesia saat ini telah teridentifikasi adanya 295 sumber gempa sesar aktif yang tersebar di wilayah Pulau Sumatera, Pulau Jawa, Pulau Kalimantan, Pulau Sulawesi, Maluku dan Papua, Bali dan Nusa Tenggara.
10* (4 Mria> 9.2) Nkxtlkli 5,1,14A-N, Tbmi(Mlnax 8.›,5) 4 ctiy, Mria 8.1
41. runi Vmax —20* 100 110 120 Gambar 1.1. Kejadian Bencana Gempa Bumi dan Tsunami BMKG menginformasikan adanya risiko yang meningkat terhadap terjadinya gempa bumi di Indonesia untuk kurun waktu 2008-2018, dalam satu tahun telah terjadi:
1. Gempa dalam berbagai magnitude sebanyak sekitar 5.000 - 6.000 kali.
2. Gempa signifikan berkekuatan M=>5,0 sebanyak 250 - 350 kali.
3. Gempa merusak terjadi sebanyak sekitar 6 - 10 kali.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3852, '1) Gempa Bumi dan Tsunami Indonesia terletak pada pertemuan lempeng besar dunia dan beberapa lempeng kecil yang menyebabkan Indonesia merupakan wilayah rawan 6 terhadap terjadi gempa bumi dan tsunami. Indonesia di kelilingi lempeng utama yaitu lempeng Eurasia, Indo-Australia, Laut Filipina, Pasifik dan microplate Sunda. Pertemuan lempeng benua Eurasia membentuk busur vulkanik di Indonesia bagian Barat, yang merupakan salah satu daerah paling aktif secara seismik di planet ini.
Selain itu, dari hasil penelitian diketahui bahwa di wilayah Indonesia saat ini telah teridentifikasi adanya 295 sumber gempa sesar aktif yang tersebar di wilayah Pulau Sumatera, Pulau Jawa, Pulau Kalimantan, Pulau Sulawesi, Maluku dan Papua, Bali dan Nusa Tenggara.
10* (4 Mria> 9.2) Nkxtlkli 5,1,14A-N, Tbmi(Mlnax 8.›,5) 4 ctiy, Mria 8.1
41. runi Vmax —20* 100 110 120 Gambar 1.1. Kejadian Bencana Gempa Bumi dan Tsunami BMKG menginformasikan adanya risiko yang meningkat terhadap terjadinya gempa bumi di Indonesia untuk kurun waktu 2008-2018, dalam satu tahun telah terjadi:
1. Gempa dalam berbagai magnitude sebanyak sekitar 5.000 - 6.000 kali.
2. Gempa signifikan berkekuatan M=>5,0 sebanyak 250 - 350 kali.
3. Gempa merusak terjadi sebanyak sekitar 6 - 10 kali.', 'Lampiran hal. 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3853, 'perban-5-2020', 12, 'lampiran', 'Lampiran hal. 6', NULL, 6, '4. Dalam 2 tahun gempa berpotensi tsunami terjadi 1 kali Selain itu, terdapat 346 kabupaten/kota berada pada tingkat risiko bencana tinggi gempa bumi dengan jurnlah penduduk berisiko sebanyak 60,9 juta jiwa 7 dan 165 kabupaten/kota berada di zona bahaya sedang gempa bumi dengan jumlah penduduk berisiko sebanyak 142,1 juta jiwa. Tren kejadian gempa bumi di Indonesia sejak Januari 2008 sampai dengan Desember 2018 menunjukkan ada peningkatan, terutama pada periode 2013-2018, untuk lebih jelasnya dapat dilihat pada gambar berikut ini:
1-41 TAM JUMLAH GEMPA BUM WILAYAH IND NESIA PERIODE JANUARt 2008 s.d DESEMBER 2018 11920 12000 SJAK 3 ADA TREN PENINGKATAN AXTIVITAS GEMPA DI INDONEISIA
1. 010,9C0 4390 2017 2016 2015 2013 2"4 1 2 3 4 5 6 7 a 9 10 11 TAHUI4 2008 2009 2010 2011 2012 2013 2014 2015 26 2017 2018 41 Tatif 6amps 4138 4390 5861 4184 67o 4234 4434 5299 5646 7169 11920 is 11‘4.,5 3553 3745 5546 3929 6226 4014 4211 5072 5465 6947 11608 Mat5 585 645 315 255 504 220 2,23 227 isi 222 312 1111 (.21'' Gambar 1.2. Trend Kejadian Gempa Bumi di Indonesia (Periode Januari 2008 - Desember 2018) Selain gempabumi terdapat juga ancaman likuifaksi seperti yang terjadi di Palu dan Donggala Sulawesi Tengah tahun 2018 yang menunjukkan betapa dahsyatnya dampak yang ditimbulkan. Likuifaksi adalah proses terpisahnya air di dalam pori-pori tanah akibat getaran sehingga tanah kehilangan daya dukung terhadap bangunan yang ada di atasnya dan sebagai akibatnya banyak bangunan yang amblas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3853, '4. Dalam 2 tahun gempa berpotensi tsunami terjadi 1 kali Selain itu, terdapat 346 kabupaten/kota berada pada tingkat risiko bencana tinggi gempa bumi dengan jurnlah penduduk berisiko sebanyak 60,9 juta jiwa 7 dan 165 kabupaten/kota berada di zona bahaya sedang gempa bumi dengan jumlah penduduk berisiko sebanyak 142,1 juta jiwa. Tren kejadian gempa bumi di Indonesia sejak Januari 2008 sampai dengan Desember 2018 menunjukkan ada peningkatan, terutama pada periode 2013-2018, untuk lebih jelasnya dapat dilihat pada gambar berikut ini:
