INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3856, 'perban-5-2020', 15, 'lampiran', 'Lampiran hal. 9', NULL, 9, '30. Inierie Ngada (NTT) 64. Tambora Dompu, Bima (NTB)
31. Iya Ende (NTT) 65. Tandikat Agam, Padang Pariaman (Sumbar)
32. Kaba Rejang Lebong 66. Tangkoko Kota Bitung (Sulut) (Bengkulu)
33. Karangetang Sitaro (Sulut) 67. Tangkuban Subang, Bandung Perahu (Jabar)
34. Kelimutu Ende (NTT) 68. Wurlali Maluku Tenggara Barat (Maluku)
35. Kelud Kediri, Blitar, Malang (Jatim) Dari tabel gunungapi yang paling aktif di Indonesia, tampak bahwa Provinsi Nusa Tenggara Timur merupakan wilayah yang paling banyak memiliki gunungapi yang paling aktif, yaitu sebanyak 16 gunungapi aktif. Sedangkan wilayah kabupaten/kota yang paling banyak memiliki gunungapi yang paling aktif adalah Kabupaten Flores Timur sebanyak 4 gunungapi.
Selain rawan bencana geologis, Indonesia juga rawan terhadap terjadinya bencana hidrometeorologi. Bahkan sebagian besar (95%) bencana yang terjadi di Indonesia adalah jenis-jenis bencana hidrometeorologi, seperti banjir, tanah longsor/ pergerakan tanah, angin kencang/ angin puting beliung dan kekeringan. Pemicu utama bencana hidrometeorologi adalah adanya cuaca ekstrem. Cuaca ekstrem adalah kejadian cuaca yang tidak normal, tidak lazim yang dapat mengakibatkan kerugian terutama keselamatan jiwa dan harta (Perka BMKG No. Kep. 009 Tahun 2010 tentang Standar Operasional Pelaksanaan Peringatan Dini, Pelaporan dan Diseminasi Informasi Cuaca Ekstrem).');
