INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3860, 'perban-5-2020', 19, 'lampiran', 'Lampiran hal. 12', NULL, 12, '- 1 2- provinsi Jambi. Selain itu pada tahun 2019 kejadian bencana banjir merata di seluruh provinsi.
4) Pergerakan Tanah/Tanah longsor Kondisi geomorfologi dan geologi di Indonesia yang secara geografis berbukit-bukit atau pegunungan memiliki potensi terjadinya longsoran atau pergerakan tanah akibat terganggunya kestabilan tanah atau batuan penyusun lereng. Gangguan kestabilan lereng dikontrol oleh kondisi morfologis (terutama kemiringan lereng), kondisi batuan ataupun tanah penyusun lereng dan kondisi hidrologis atau tata air pada lereng. Meskipun suatu lereng rentan atau berpotensi longsor karena kondisi kemiringan lereng, batuan/ tanah dan tata airnya, namun lereng tersebut belum akan longsor atau terganggu kestabilannya tanpa dipicu oleh proses pemicunya seperti peningkatan kandungan air dalam lereng yang meregangkan ikatan antar butir tanah sehingga mudah longsor, getaran akibat gempa bumi ataupun ledakan, terutama pada tanah berpasir dengan kandungan air sering mengakibatkan likuifaksi, peningkatan beban yang melampaui daya dukung tanah dan pemotongan kaki lereng secara sembarangan yang mengakibatkan lereng kehilangan daya penyangga. `411, PETA RISIKO BENCANA TANAH LONGSOR LANDSLIDE F?l,SK MA, L.g.nds/L.wod T');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3860, '- 1 2- provinsi Jambi. Selain itu pada tahun 2019 kejadian bencana banjir merata di seluruh provinsi.
4) Pergerakan Tanah/Tanah longsor Kondisi geomorfologi dan geologi di Indonesia yang secara geografis berbukit-bukit atau pegunungan memiliki potensi terjadinya longsoran atau pergerakan tanah akibat terganggunya kestabilan tanah atau batuan penyusun lereng. Gangguan kestabilan lereng dikontrol oleh kondisi morfologis (terutama kemiringan lereng), kondisi batuan ataupun tanah penyusun lereng dan kondisi hidrologis atau tata air pada lereng. Meskipun suatu lereng rentan atau berpotensi longsor karena kondisi kemiringan lereng, batuan/ tanah dan tata airnya, namun lereng tersebut belum akan longsor atau terganggu kestabilannya tanpa dipicu oleh proses pemicunya seperti peningkatan kandungan air dalam lereng yang meregangkan ikatan antar butir tanah sehingga mudah longsor, getaran akibat gempa bumi ataupun ledakan, terutama pada tanah berpasir dengan kandungan air sering mengakibatkan likuifaksi, peningkatan beban yang melampaui daya dukung tanah dan pemotongan kaki lereng secara sembarangan yang mengakibatkan lereng kehilangan daya penyangga. `411, PETA RISIKO BENCANA TANAH LONGSOR LANDSLIDE F?l,SK MA, L.g.nds/L.wod T', 'Lampiran hal. 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3861, 'perban-5-2020', 20, 'lampiran', 'Lampiran hal. 12', NULL, 12, '• Gambar 1.4. Peta risiko bencana tanah longsor Dari peta di atas terlihat bahwa wilayah rawan pergerakan tanah/ tanah longsor di Indonesia memanjang dari Aceh, Sumatera Utara, Sumatera Barat, Bengkulu, Lampung, Banten, Jawa Barat, Jawa Tengah, DIY, Jawa Timur, Bali, NTB, NTT, sebagian wilayah Kalimantan terutama di bagian Timur dan Utara, sebagian besar Sulawesi, Maluku dan Maluku Utara serta sebagian Papua dan Papua Barat.
5) Kekeringan Indonesia rawan terhadap bencana kekeringan, dari data historis kekeringan di Indonesia sangat berkaitan erat dengan fenomena ENSO (El-Nino Southem Oscillation). Pengaruh El-Nino pada keragaman hujan memiliki beberapa pola yaitu : (1) akhir musim kemarau mundur dari normal, (2) awal masuk musim hujan mundur dari normal, (3) curah hujan musim kemarau turun tajam dibanding normal, (4) deret hari kering semakin panjang khususnya di daerah Indonesia bagian timur. Dampak bahaya kekeringan seringkali gradual/lambat, sehingga jika tidak terdapat pemantauan secara baik dan terus menerus akan mengakibatkan bencana berupa berkurangnya sumber air, berkurangnya produksi bahan pangan yang dapat memicu kelaparan dan dapat pula menimbulkan terjadinya kebakaran lahan dan hutan.
PETA RISIKO BENCANA KEKERINGAN lMP DROUGHT RISK MAP „ ; < ,EL4TAN SOATA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3861, '• Gambar 1.4. Peta risiko bencana tanah longsor Dari peta di atas terlihat bahwa wilayah rawan pergerakan tanah/ tanah longsor di Indonesia memanjang dari Aceh, Sumatera Utara, Sumatera Barat, Bengkulu, Lampung, Banten, Jawa Barat, Jawa Tengah, DIY, Jawa Timur, Bali, NTB, NTT, sebagian wilayah Kalimantan terutama di bagian Timur dan Utara, sebagian besar Sulawesi, Maluku dan Maluku Utara serta sebagian Papua dan Papua Barat.
5) Kekeringan Indonesia rawan terhadap bencana kekeringan, dari data historis kekeringan di Indonesia sangat berkaitan erat dengan fenomena ENSO (El-Nino Southem Oscillation). Pengaruh El-Nino pada keragaman hujan memiliki beberapa pola yaitu : (1) akhir musim kemarau mundur dari normal, (2) awal masuk musim hujan mundur dari normal, (3) curah hujan musim kemarau turun tajam dibanding normal, (4) deret hari kering semakin panjang khususnya di daerah Indonesia bagian timur. Dampak bahaya kekeringan seringkali gradual/lambat, sehingga jika tidak terdapat pemantauan secara baik dan terus menerus akan mengakibatkan bencana berupa berkurangnya sumber air, berkurangnya produksi bahan pangan yang dapat memicu kelaparan dan dapat pula menimbulkan terjadinya kebakaran lahan dan hutan.
PETA RISIKO BENCANA KEKERINGAN lMP DROUGHT RISK MAP „ ; < ,EL4TAN SOATA.', 'Lampiran hal. 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3862, 'perban-5-2020', 21, 'lampiran', 'Lampiran hal. 13', NULL, 13, 'k. e4,04,,EN Litgendi Liond bleka Rwho Ptc,« < Gambar 1.5. Peta risiko bencana kekeringan Dari peta di atas terlihat bahwa wilayah rawan kekeringan di Indonesia memanjang dari Aceh, hingga Lampung, Banten, Jawa Barat, Jawa Tengah, DIY, Jawa Timur, Bali, NTB, NTT, sebagian Kalimantan, Sulawesi, Maluku dan Maluku Utara.
6) Kebakaran Lahan dan Hutan Kejadian kebakaran lahan dan hutan di Indonesia selain dipengaruhi oleh faktor alam, sebagian besar juga dipengaruhi oleh faktor manusia yang sengaja melakukan pembakaran dan kelalaian dalam rangka penyiapan lahan untuk pertanian dan perkebunan. Kebakaran lahan dan hutan yang terluas terdapat di Provinsi Riau dan hampir di seluruh provinsi yang ada di Indonesia pada tahun 2013 dan tahun 2015. Bencana ini mengakibatkan adanya kabut
- 1 4- asap yang menyeberang (transboundary haze) ke negara tetangga yaitu Singapura dan Malaysia.
Luasnya areal lahan dan hutan yang terbakar di Indonesia hingga saat ini dipengaruhi pula oleh karakteristik biofisik lahan yang ada. Sebagian besar kejadian kebakaran dalam kurun waktu 10 tahun terakhir terjadi di lahan gambut. Lahan ini secara alami merupakan lahan basah yang tidak mudah terbakar, tetapi jika lahan gambut kering karena adanya drainase yang berlebihan maka sangat rentan terbakar. Lahan gambut yang kering juga dapat berubah sifatnya dan tidak dapat kembali lagi ke bentuk awalnya yang berupa lahan basah, sehingga tingkat kerentanan terbakarnya semakin tinggi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3862, 'k. e4,04,,EN Litgendi Liond bleka Rwho Ptc,« < Gambar 1.5. Peta risiko bencana kekeringan Dari peta di atas terlihat bahwa wilayah rawan kekeringan di Indonesia memanjang dari Aceh, hingga Lampung, Banten, Jawa Barat, Jawa Tengah, DIY, Jawa Timur, Bali, NTB, NTT, sebagian Kalimantan, Sulawesi, Maluku dan Maluku Utara.
6) Kebakaran Lahan dan Hutan Kejadian kebakaran lahan dan hutan di Indonesia selain dipengaruhi oleh faktor alam, sebagian besar juga dipengaruhi oleh faktor manusia yang sengaja melakukan pembakaran dan kelalaian dalam rangka penyiapan lahan untuk pertanian dan perkebunan. Kebakaran lahan dan hutan yang terluas terdapat di Provinsi Riau dan hampir di seluruh provinsi yang ada di Indonesia pada tahun 2013 dan tahun 2015. Bencana ini mengakibatkan adanya kabut
- 1 4- asap yang menyeberang (transboundary haze) ke negara tetangga yaitu Singapura dan Malaysia.
Luasnya areal lahan dan hutan yang terbakar di Indonesia hingga saat ini dipengaruhi pula oleh karakteristik biofisik lahan yang ada. Sebagian besar kejadian kebakaran dalam kurun waktu 10 tahun terakhir terjadi di lahan gambut. Lahan ini secara alami merupakan lahan basah yang tidak mudah terbakar, tetapi jika lahan gambut kering karena adanya drainase yang berlebihan maka sangat rentan terbakar. Lahan gambut yang kering juga dapat berubah sifatnya dan tidak dapat kembali lagi ke bentuk awalnya yang berupa lahan basah, sehingga tingkat kerentanan terbakarnya semakin tinggi.', 'Lampiran hal. 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3863, 'perban-5-2020', 22, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'Dengan demikian, aspek kondisi lahan dan iklim menjadi aspek penting yang berpengaruh terhadap kejadian kebakaran lahan dan hutan.
PETA RISIKO BENCANA KEBAKARAN HUTAN DAN LAHAN a a FORES T AND LAND FIRE RISK MAP Gambar 1.6. Peta risiko bencana kebakaran hutan dan lahan Dari peta di atas terlihat bahwa sebagian besar wilayah Indonesia rawan terhadap terjadinya bencana kebakaran lahan dan hutan. Sejak tahun 2015 hampir rutin setiap tahunnya terjadi kebakaran lahan dan hutan di wilayah provinsi Riau, Jambi, Sumatera Selatan, Kalimantan Barat, Kalimantan Tengah, Kalimantan Selatan dan Kalimantan Timur.
7) Angin Puting Beliung/Angin Kencang Cuaca ekstrem merupakan angin kencang dengan kecepatan 120 km/jam atau lebih seringkali terjadi di wilayah tropis diantara agraris balik utara dan selatan, kecuali di daerah-daerah yang sangat dekat dengan khatulistiwa.
Angin ini disebabkan oleh adanya perbedaan tekanan dalam suatu sistem cuaca seperti peningkatan tekanan udara maupun adanya pergerakan semu matahari yang secara tegak lurus dengan permukaan bumi (kulminasi).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3863, 'Dengan demikian, aspek kondisi lahan dan iklim menjadi aspek penting yang berpengaruh terhadap kejadian kebakaran lahan dan hutan.
PETA RISIKO BENCANA KEBAKARAN HUTAN DAN LAHAN a a FORES T AND LAND FIRE RISK MAP Gambar 1.6. Peta risiko bencana kebakaran hutan dan lahan Dari peta di atas terlihat bahwa sebagian besar wilayah Indonesia rawan terhadap terjadinya bencana kebakaran lahan dan hutan. Sejak tahun 2015 hampir rutin setiap tahunnya terjadi kebakaran lahan dan hutan di wilayah provinsi Riau, Jambi, Sumatera Selatan, Kalimantan Barat, Kalimantan Tengah, Kalimantan Selatan dan Kalimantan Timur.
7) Angin Puting Beliung/Angin Kencang Cuaca ekstrem merupakan angin kencang dengan kecepatan 120 km/jam atau lebih seringkali terjadi di wilayah tropis diantara agraris balik utara dan selatan, kecuali di daerah-daerah yang sangat dekat dengan khatulistiwa.
Angin ini disebabkan oleh adanya perbedaan tekanan dalam suatu sistem cuaca seperti peningkatan tekanan udara maupun adanya pergerakan semu matahari yang secara tegak lurus dengan permukaan bumi (kulminasi).', 'Lampiran hal. 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3864, 'perban-5-2020', 23, 'lampiran', 'Lampiran hal. 15', NULL, 15, 'Angin puting beliung/angin kencang bisa terjadi kapan dan dimana saja, baik di darat maupun di laut dan jika terjadi di laut durasinya lebih lama dibandingkan dengan darat. Angin puting beliung/angin kencang umumnya terjadi pada siang atau sore hari, terkadang pada malam hari dan lebih sering terjadi pada peralihan musim (pancaroba). Hingga saat ini telah banyak diberitakan bencana angin puting beliung/angin kencang di banyak tempat.
Angin puting beliung/angin kencang yang cukup besar yang dapat membuat banyak kerusakan sekaligus menimbulkan kerugian yang tidak sedikit seperti merusak rumah-rumah warga, pohon dan alat transportasi.
Hampir di semua wilayah di Indonesia rawan terjadi bencana angin puting beliung. Untuk lebih jelasnya dapat dilihat pada gambar berikut ini.
PETA RISIKO BENCANA ANC.1N PIJTING RF1.11ING _.~111~10,2-? '' , .14 Gambar 1.7. Peta risiko bencana Angin Puting Beliung 8) Epidemi dan Wabah Penyakit Ancaman bencana yang bersumber dari adanya kejadian epidemi dan wabah penyakit di Indonesia cenderung terus mengalami peningkatan dan berimplikasi pada aspek kesehatan, sosial, ekonomi, keamanan, dan kesejahteraan rakyat. Penyakit infeksi menular yang bersifat cepat menyebar pada suatu populasi manusia dapat berasal dari virus, bakteri atau parasit.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3864, 'Angin puting beliung/angin kencang bisa terjadi kapan dan dimana saja, baik di darat maupun di laut dan jika terjadi di laut durasinya lebih lama dibandingkan dengan darat. Angin puting beliung/angin kencang umumnya terjadi pada siang atau sore hari, terkadang pada malam hari dan lebih sering terjadi pada peralihan musim (pancaroba). Hingga saat ini telah banyak diberitakan bencana angin puting beliung/angin kencang di banyak tempat.
Angin puting beliung/angin kencang yang cukup besar yang dapat membuat banyak kerusakan sekaligus menimbulkan kerugian yang tidak sedikit seperti merusak rumah-rumah warga, pohon dan alat transportasi.
Hampir di semua wilayah di Indonesia rawan terjadi bencana angin puting beliung. Untuk lebih jelasnya dapat dilihat pada gambar berikut ini.
PETA RISIKO BENCANA ANC.1N PIJTING RF1.11ING _.~111~10,2-? '' , .14 Gambar 1.7. Peta risiko bencana Angin Puting Beliung 8) Epidemi dan Wabah Penyakit Ancaman bencana yang bersumber dari adanya kejadian epidemi dan wabah penyakit di Indonesia cenderung terus mengalami peningkatan dan berimplikasi pada aspek kesehatan, sosial, ekonomi, keamanan, dan kesejahteraan rakyat. Penyakit infeksi menular yang bersifat cepat menyebar pada suatu populasi manusia dapat berasal dari virus, bakteri atau parasit.', 'Lampiran hal. 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3865, 'perban-5-2020', 24, 'lampiran', 'Lampiran hal. 15', NULL, 15, 'Penyakit Infeksi menular mencakup penyakit yang baru muncul (new emerging disease) dan penyakit lama yang muncul kembali (reemerging disease). Sebagian besar penyakit infeksi menular berpotensi menyebabkan Kejadian Luar Biasa (KLB)/Wabah di Indonesia atau bahkan meluasnya KLB/Wabah antar negara yang dikenal dengan pandemi. Berdasarkan regulasi kebencanaan, Kejadian Luar Biasa (KLB) /Wabah merupakan bencana nonalam. Beberapa jenis penyakit yang mempunyai potensi ancaman di Indonesia diantaranya rabies, flu burung (H5N1), anthrax, SARS, MERS dan COVID-19. Sejak November 2019 telah merebak pandemik COVID-19 yang mewabah di 215 negara, termasuk Indonesia. Data secara global sampai dengan tanggal 28 Mei 2020 tercatat ada 5.803.658 kasus dan 357.712 kasus diantaranya meninggal dunia (CFR=6,1%). Sedangkan di Indonesia kasus COVID-19 telah merebak di seluruh provinsi yang mencakup 412 kabupaten/kota dengan kasus keseluruhan pada tanggal 28 Mei 2020 sebanyak 24.538 kasus dan meninggal dunia 1.496 kasus (CFR=6,1%). Dalam rangka percepatan penanganan COVID-19, Presiden telah mengeluarkan Keputusan Presiden Nomor 7 tahun 2020 tentang Pembentukan Gugus Tugas Percepatan Penanganan COVID-19 dan Keputusan Presiden Nomor 9 Tahun 2020 tentang Perubahan atas Keputusan Presiden Nomor 7 Tahun 2020 tentang Pembentukan Gugus Tugas Percepatan Penanganan COVID-19 yang melibatkan kementerian/lembaga terkait.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3865, 'Penyakit Infeksi menular mencakup penyakit yang baru muncul (new emerging disease) dan penyakit lama yang muncul kembali (reemerging disease). Sebagian besar penyakit infeksi menular berpotensi menyebabkan Kejadian Luar Biasa (KLB)/Wabah di Indonesia atau bahkan meluasnya KLB/Wabah antar negara yang dikenal dengan pandemi. Berdasarkan regulasi kebencanaan, Kejadian Luar Biasa (KLB) /Wabah merupakan bencana nonalam. Beberapa jenis penyakit yang mempunyai potensi ancaman di Indonesia diantaranya rabies, flu burung (H5N1), anthrax, SARS, MERS dan COVID-19. Sejak November 2019 telah merebak pandemik COVID-19 yang mewabah di 215 negara, termasuk Indonesia. Data secara global sampai dengan tanggal 28 Mei 2020 tercatat ada 5.803.658 kasus dan 357.712 kasus diantaranya meninggal dunia (CFR=6,1%). Sedangkan di Indonesia kasus COVID-19 telah merebak di seluruh provinsi yang mencakup 412 kabupaten/kota dengan kasus keseluruhan pada tanggal 28 Mei 2020 sebanyak 24.538 kasus dan meninggal dunia 1.496 kasus (CFR=6,1%). Dalam rangka percepatan penanganan COVID-19, Presiden telah mengeluarkan Keputusan Presiden Nomor 7 tahun 2020 tentang Pembentukan Gugus Tugas Percepatan Penanganan COVID-19 dan Keputusan Presiden Nomor 9 Tahun 2020 tentang Perubahan atas Keputusan Presiden Nomor 7 Tahun 2020 tentang Pembentukan Gugus Tugas Percepatan Penanganan COVID-19 yang melibatkan kementerian/lembaga terkait.', 'Lampiran hal. 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3866, 'perban-5-2020', 25, 'lampiran', 'Lampiran hal. 15', NULL, 15, 'Lebih dari itu pula Presiden juga telah menetapkan bahwa pandemi COVID-19 sebagai bencana nasional nonalam, melalui Keputusan Presiden Nomor 12 Tahun 2020.
9) Kegagalan Teknologi Bencana kegagalan teknologi adalah semua kejadian bencana yang diakibatkan oleh kesalahan desain, pengoperasian, kelalaian dan kesengajaan manusia dalam penggunaan teknologi dan/ atau industri. Penyebab terjadinya bencana kegagalan teknologi antara lain kegagalan/kesalahan desain keselamatan pabrik, kesalahan prosedur pengoperasian pabrik, kegagalan/kesalahan dalam pengelolaan Bahan Berbahaya dan Beracun (B3) dan limbah B3, dan kecelakaan transportasi. Dengan berkembangnya beberapa wilayah di Indonesia menjadi kawasan industri seperti wilayah Serang dan Cilegon di Banten, Gresik di Jawa Timur dan lain-lain tentunya mempunyai potensi tersendiri untuk terjadinya bencana kegagalan teknologi.
Munculnya kawasan industri seringkali akan muncul pula wilayah permukiman penduduk di sekitarnya, yang tentunya ini meningkatkan risiko adanya korban jika terjadi kegagalan teknologi pada pengelolaan operasional pabrik di wilayah tersebut.
Dalam rangka meningkatkan upaya pengelolaan dan pengendalian terhadap kejadian kedaruratan akibat pengelolaan limbah B3 yang berpotensi menimbulkan bencana, Pemerintah telah mengeluarkan Peraturan Pemerintah Nomor 101 Tahun 2014 tentang Pengelolaan Limbah B3.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3866, 'Lebih dari itu pula Presiden juga telah menetapkan bahwa pandemi COVID-19 sebagai bencana nasional nonalam, melalui Keputusan Presiden Nomor 12 Tahun 2020.
9) Kegagalan Teknologi Bencana kegagalan teknologi adalah semua kejadian bencana yang diakibatkan oleh kesalahan desain, pengoperasian, kelalaian dan kesengajaan manusia dalam penggunaan teknologi dan/ atau industri. Penyebab terjadinya bencana kegagalan teknologi antara lain kegagalan/kesalahan desain keselamatan pabrik, kesalahan prosedur pengoperasian pabrik, kegagalan/kesalahan dalam pengelolaan Bahan Berbahaya dan Beracun (B3) dan limbah B3, dan kecelakaan transportasi. Dengan berkembangnya beberapa wilayah di Indonesia menjadi kawasan industri seperti wilayah Serang dan Cilegon di Banten, Gresik di Jawa Timur dan lain-lain tentunya mempunyai potensi tersendiri untuk terjadinya bencana kegagalan teknologi.
Munculnya kawasan industri seringkali akan muncul pula wilayah permukiman penduduk di sekitarnya, yang tentunya ini meningkatkan risiko adanya korban jika terjadi kegagalan teknologi pada pengelolaan operasional pabrik di wilayah tersebut.
Dalam rangka meningkatkan upaya pengelolaan dan pengendalian terhadap kejadian kedaruratan akibat pengelolaan limbah B3 yang berpotensi menimbulkan bencana, Pemerintah telah mengeluarkan Peraturan Pemerintah Nomor 101 Tahun 2014 tentang Pengelolaan Limbah B3.', 'Lampiran hal. 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3867, 'perban-5-2020', 26, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'Selanjutnya di dalam Pasal 234 ayat (1), 235 ayat (1) dan 236 ayat (1) mengamanatkan bahwa Kepala BPBD Kabupaten/Kota, Provinsi dan Kepala BNPB agar menginisiasi dan memimpin pelaksanaan penanggulangan kedaruratan bencana yang diakibatkan pengelolaan limbah B3 sesuai tingkatan kewenangannya. Hal ini tentunya perlu mendapatkan perhatian bagi BNPB untuk mulai melakukan tindakan-tindakan untuk merespon peraturan tersebut dalam rangka peningkatan upaya penanggulangan bencana kegagalan teknologi. t .2 indeks Risiko Bencana di Indonesia Upaya penanggulangan bencana di Indonesia perlu diawali dengan pemahaman atas risiko bencana yang ada berdasarkan hasil kajian risiko.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3867, 'Selanjutnya di dalam Pasal 234 ayat (1), 235 ayat (1) dan 236 ayat (1) mengamanatkan bahwa Kepala BPBD Kabupaten/Kota, Provinsi dan Kepala BNPB agar menginisiasi dan memimpin pelaksanaan penanggulangan kedaruratan bencana yang diakibatkan pengelolaan limbah B3 sesuai tingkatan kewenangannya. Hal ini tentunya perlu mendapatkan perhatian bagi BNPB untuk mulai melakukan tindakan-tindakan untuk merespon peraturan tersebut dalam rangka peningkatan upaya penanggulangan bencana kegagalan teknologi. t .2 indeks Risiko Bencana di Indonesia Upaya penanggulangan bencana di Indonesia perlu diawali dengan pemahaman atas risiko bencana yang ada berdasarkan hasil kajian risiko.', 'Lampiran hal. 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3868, 'perban-5-2020', 27, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'Penilaian dampak bencana (korban jiwa, kerusakan atau kerugian) menjadi penilaian potensi kehilangan atau kerugian (risiko). Dalam indeks risiko, tingkat kebencanaan dinilai berdasarkan komponen penyusunnya, yaitu bahaya, keterpaparan, dan kapasitas pemerintah serta komunitas dalam menghadapi bencana. Adanya penilaian tingkat risiko berdasarkan potensi kerugian tentunya dapat membantu upaya untuk pengurangan risiko bencana di suatu daerah. Risiko bencana akan mengalami penurunan atau peningkatan seiring adanya perubahan pada komponen penyusunnya. Lebih lanjut, penilaian secara berkelanjutan terhadap indeks risiko ini dapat menjadi perangkat pemantauan dan evaluasi terhadap capaian program penanggulangan bencana pada periode tertentu. Data perkembangan indeks risiko bencana di Indonesia menurut provinsi tahun 2013 dan tahun 2018 dapat dilihat pada tabel berikut ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3868, 'Penilaian dampak bencana (korban jiwa, kerusakan atau kerugian) menjadi penilaian potensi kehilangan atau kerugian (risiko). Dalam indeks risiko, tingkat kebencanaan dinilai berdasarkan komponen penyusunnya, yaitu bahaya, keterpaparan, dan kapasitas pemerintah serta komunitas dalam menghadapi bencana. Adanya penilaian tingkat risiko berdasarkan potensi kerugian tentunya dapat membantu upaya untuk pengurangan risiko bencana di suatu daerah. Risiko bencana akan mengalami penurunan atau peningkatan seiring adanya perubahan pada komponen penyusunnya. Lebih lanjut, penilaian secara berkelanjutan terhadap indeks risiko ini dapat menjadi perangkat pemantauan dan evaluasi terhadap capaian program penanggulangan bencana pada periode tertentu. Data perkembangan indeks risiko bencana di Indonesia menurut provinsi tahun 2013 dan tahun 2018 dapat dilihat pada tabel berikut ini.', 'Lampiran hal. 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3869, 'perban-5-2020', 28, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'Tabel 1.3. Indeks Risiko Bencana di Indonesia menurut Provinsi Tahun 2013 dan tahun 2018 Tahun 2013 Tahun 2018 No Provinsi. Kelas Kelas Skor Skor Risiko Risiko 1 Aceh 160 Tinggi 157 56 Tinggi 2 Sumut 150 Tinggi 145 25 Tinggi 3 Sumbar 153 Tinggi 151 56 Tinggi 4 Riau 147 Tinggi 147 27 Tinggi 5 Kep. Riau 116 Sedang 116 40 Sedang 6 Jambi 142 Sedang 138 64 Sedang 7 Sumsel 142 Sedang 139 67 Sedang Tahun 2013 Tahun 2018 No Provinsi. Kelas Kelas Skor Skor Risiko Risiko 8 Babel 162 Tinggi 161 54 Tinggi 9 Bengkulu 172 Tinggi 163 29 Tinggi 10 Lampung 153 Tinggi 149 96 Tinggi 11 Banten 180 Tinggi 173 81 Tinggi 12 DKI Jakarta 103 Sedang 72,12 Sedang 13 Jabar 166 Tinggi 152 13 Tinggi 14 Jateng 158 Tinggi 146 47 Tinggi 15 DI Yogyakarta 165 Tinggi 142 24 Sedang 16 Jatim 171 Tinggi 152 40 Tinggi 17 Bali 170 Tinggi 145 24 Tinggi 18 NTB 172 Tinggi 139 92 Sedang 19 NTT 156 Tinggi 142 43 Sedang 20 Kalbar 157 Tinggi 138 49 Sedang 21 Kalteng 141 Sedang 133 00 Sedang 22 Kalsel 152 Tinggi 145 21 Tinggi 23 Kaltim 165 Tinggi 155 49 Tinggi 24 Kaltara 153 72 Tinggi 25 Sulut 151 Tinggi 141 45 Sedang 26 Gorontalo 140 Sedang 130 44 Sedang 27 Sulteng 158 Tinggi 146 39 Tinggi 28 Sulbar 191 Tinggi 162 92 Tinggi 29 Sulsel 167 Tinggi 160 05 Tinggi 30 Sultra 169 Tinggi 158 26 Tinggi 31 Malut 169 Tinggi 146 95 Tinggi 32 Maluku 179 Tinggi 160 42 Tinggi 33 Papua Barat 154 Tinggi 143 27 Sedang 34 Papua 125 Sedang 122 93 Sedang Dari tabel di atas terlihat ada 6 provinsi yang kelas risikonya menurun dari risiko tinggi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3869, 'Tabel 1.3. Indeks Risiko Bencana di Indonesia menurut Provinsi Tahun 2013 dan tahun 2018 Tahun 2013 Tahun 2018 No Provinsi. Kelas Kelas Skor Skor Risiko Risiko 1 Aceh 160 Tinggi 157 56 Tinggi 2 Sumut 150 Tinggi 145 25 Tinggi 3 Sumbar 153 Tinggi 151 56 Tinggi 4 Riau 147 Tinggi 147 27 Tinggi 5 Kep. Riau 116 Sedang 116 40 Sedang 6 Jambi 142 Sedang 138 64 Sedang 7 Sumsel 142 Sedang 139 67 Sedang Tahun 2013 Tahun 2018 No Provinsi. Kelas Kelas Skor Skor Risiko Risiko 8 Babel 162 Tinggi 161 54 Tinggi 9 Bengkulu 172 Tinggi 163 29 Tinggi 10 Lampung 153 Tinggi 149 96 Tinggi 11 Banten 180 Tinggi 173 81 Tinggi 12 DKI Jakarta 103 Sedang 72,12 Sedang 13 Jabar 166 Tinggi 152 13 Tinggi 14 Jateng 158 Tinggi 146 47 Tinggi 15 DI Yogyakarta 165 Tinggi 142 24 Sedang 16 Jatim 171 Tinggi 152 40 Tinggi 17 Bali 170 Tinggi 145 24 Tinggi 18 NTB 172 Tinggi 139 92 Sedang 19 NTT 156 Tinggi 142 43 Sedang 20 Kalbar 157 Tinggi 138 49 Sedang 21 Kalteng 141 Sedang 133 00 Sedang 22 Kalsel 152 Tinggi 145 21 Tinggi 23 Kaltim 165 Tinggi 155 49 Tinggi 24 Kaltara 153 72 Tinggi 25 Sulut 151 Tinggi 141 45 Sedang 26 Gorontalo 140 Sedang 130 44 Sedang 27 Sulteng 158 Tinggi 146 39 Tinggi 28 Sulbar 191 Tinggi 162 92 Tinggi 29 Sulsel 167 Tinggi 160 05 Tinggi 30 Sultra 169 Tinggi 158 26 Tinggi 31 Malut 169 Tinggi 146 95 Tinggi 32 Maluku 179 Tinggi 160 42 Tinggi 33 Papua Barat 154 Tinggi 143 27 Sedang 34 Papua 125 Sedang 122 93 Sedang Dari tabel di atas terlihat ada 6 provinsi yang kelas risikonya menurun dari risiko tinggi', 'Lampiran hal. 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3870, 'perban-5-2020', 29, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'pada tahun 2013 menjadi risiko sedang pada tahun 2018 yaitu provinsi DI Yogyakarta, NTB, NTT, Kalbar, Sulut dan Papua Barat. Sementara itu provinsi yang memiliki indeks risiko bencana tinggi pada tahun 2018 sebanyak 21 provinsi atau 61,76% dari seluruh provinsi yang ada. Adapun provinsi yang memiliki indeks risiko bencana tinggi adalah Provinsi Aceh, Sumatera Utara, Sumatera Barat, Riau, Bangka Belitung, Bengkulu, Lampung, Banten, Jabar, Jawa Tengah, Jawa Timur, Bali, Kalimantan Selatan, Kalimantan Timur, Kalimantan Utara, Sulawasi Tengah, Sulawesi Barat, Sulawesi Selatan, Sulawesi Utara, Maluku Utara dan Maluku.
Dalam 11 (sebelas) tahun terakhir (2009-2019), bencana yang paling sering terjadi di Indonesia adalah banjir (7.378 kejadian), puting beliung (6.330 kejadian, dan tanah longsor (1.873). Selanjutnya disusul oleh kebakaran hutan dan lahan (980 kejadian), gelombang pasang/abrasi (227 kejadian), gempabumi (186 kejadian), dan letusan gunung berapi (109 kejadian).
Sementara itu, dalam kurun waktu 2009-2019 terlihat bahwa kelompok bencana hidrometeorologi, memiliki jumlah kejadian lebih besar 2835 Frekuensi Kejadian 2489 2500 1897 1932 1754 1630 1656 2000 1598 297 1500 1000 500 5 15 14 20 14 19 35 17 18 83 24 0 2009 2010 20:11 2012 201.,3 2014 2015 2016 201,7 201.8 201.9 ...~..1-11DROMETEOROLOGI Gambar 1.8. Grafik Frekuensi Kejadian Bencana Hidrometeorologi dan Bencana Geologi di Indonesia Kurun Waktu 2009 -2019.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3870, 'pada tahun 2013 menjadi risiko sedang pada tahun 2018 yaitu provinsi DI Yogyakarta, NTB, NTT, Kalbar, Sulut dan Papua Barat. Sementara itu provinsi yang memiliki indeks risiko bencana tinggi pada tahun 2018 sebanyak 21 provinsi atau 61,76% dari seluruh provinsi yang ada. Adapun provinsi yang memiliki indeks risiko bencana tinggi adalah Provinsi Aceh, Sumatera Utara, Sumatera Barat, Riau, Bangka Belitung, Bengkulu, Lampung, Banten, Jabar, Jawa Tengah, Jawa Timur, Bali, Kalimantan Selatan, Kalimantan Timur, Kalimantan Utara, Sulawasi Tengah, Sulawesi Barat, Sulawesi Selatan, Sulawesi Utara, Maluku Utara dan Maluku.
Dalam 11 (sebelas) tahun terakhir (2009-2019), bencana yang paling sering terjadi di Indonesia adalah banjir (7.378 kejadian), puting beliung (6.330 kejadian, dan tanah longsor (1.873). Selanjutnya disusul oleh kebakaran hutan dan lahan (980 kejadian), gelombang pasang/abrasi (227 kejadian), gempabumi (186 kejadian), dan letusan gunung berapi (109 kejadian).
Sementara itu, dalam kurun waktu 2009-2019 terlihat bahwa kelompok bencana hidrometeorologi, memiliki jumlah kejadian lebih besar 2835 Frekuensi Kejadian 2489 2500 1897 1932 1754 1630 1656 2000 1598 297 1500 1000 500 5 15 14 20 14 19 35 17 18 83 24 0 2009 2010 20:11 2012 201.,3 2014 2015 2016 201,7 201.8 201.9 ...~..1-11DROMETEOROLOGI Gambar 1.8. Grafik Frekuensi Kejadian Bencana Hidrometeorologi dan Bencana Geologi di Indonesia Kurun Waktu 2009 -2019.', 'Lampiran hal. 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3871, 'perban-5-2020', 30, 'lampiran', 'Lampiran hal. 19', NULL, 19, 'Sumber: BNPB (2019) dibandingkan kejadian bencana yang disebabkan oleh dampak geologi. Dalam kurun waktu yang sama, data tersebut juga menunjukkan tren kenaikan jumlah bencana hidrometeorologi. Walaupun tren kenaikan bencana hidrometeorologi lebih tinggi dibandingkan tren kenaikan bencana geologi, dampak bencana geologi, seperti gempa dan tsunami, sering kali lebih banyak mengakibatkan korban jiwa dan kerugian ekonomi dalam skala besar.
Bagian barat Pulau Sumatera, selatan Pulau Jawa, Nusa Tenggara, bagian utara Papua, serta Sulawesi dan Maluku merupakan wilayah-wilayah yang rawan terpapar tsunami. Data menunjukkan bahwa Indonesia telah terpapar tsunami sebanyak lebih dari 172 tsunami dalam kurun waktu 1600-2012.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3871, 'Sumber: BNPB (2019) dibandingkan kejadian bencana yang disebabkan oleh dampak geologi. Dalam kurun waktu yang sama, data tersebut juga menunjukkan tren kenaikan jumlah bencana hidrometeorologi. Walaupun tren kenaikan bencana hidrometeorologi lebih tinggi dibandingkan tren kenaikan bencana geologi, dampak bencana geologi, seperti gempa dan tsunami, sering kali lebih banyak mengakibatkan korban jiwa dan kerugian ekonomi dalam skala besar.
Bagian barat Pulau Sumatera, selatan Pulau Jawa, Nusa Tenggara, bagian utara Papua, serta Sulawesi dan Maluku merupakan wilayah-wilayah yang rawan terpapar tsunami. Data menunjukkan bahwa Indonesia telah terpapar tsunami sebanyak lebih dari 172 tsunami dalam kurun waktu 1600-2012.', 'Lampiran hal. 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3872, 'perban-5-2020', 31, 'lampiran', 'Lampiran hal. 19', NULL, 19, 'Diketahui bahwa 90 persen dari tsunami tersebut disebabkan oleh aktivitas gempabumi tektonik, 9 persen akibat aktivitas vulkanik dan 1 persen oleh tanah longsor yang terjadi dalam tubuh air (danau atau laut) maupun longsoran dari darat yang masuk ke dalam tubuh air. Selama kurun waktu 30 tahun terakhir (1989-2019), tercatat bahwa bencana tsunami telah menyebabkan kehilangan jiwa dan kerugian infrastruktur yang besar. Antara tahun 1989-2019 telah terjadi tsunami besar sebagai berikut: (1)Tsunami di Flores (1992); (2) Tsunami di Banyuwangi Jawa Timur (1994); (3) Tsunami di Biak (1996); (4) Tsunami di Maluku (1998); (5) Tsunami di Banggai Sulawesi Utara (2000); (6) Tsunami di Aceh (2004); (7) Tsunami di Nias (2005); (8) Tsunami di Jawa Barat (2006); (9) Tsunami di Bengkulu (2007); (10) Tsunami di Mentawai (2010), dan (11) Tsunami di Selat Sunda (2018).
Bencana geologis lainnya yang memerlukan kesiapsiagaan besar adalah bencana letusan gunung api. Sejarah mencatat bahwa Indonesia pernah menjadi tempat terjadinya dua letusan gunung api terbesar di dunia. Tahun 1815 Gunung Tambora yang berada di Pulau Sumbawa, Nusa Tenggara Barat, meletus dan mengeluarkan sekitar 1,7 juta ton abu dan material vulkanik.
Selanjutnya, Gunung Krakatau meletus pada tahun 1883. Erupsi Krakatau ini diperkirakan memiliki kekuatan setara 200 megaton TNT, kira-kira 13.000 kali kekuatan ledakan bom atom yang menghancurkan Hiroshima.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3872, 'Diketahui bahwa 90 persen dari tsunami tersebut disebabkan oleh aktivitas gempabumi tektonik, 9 persen akibat aktivitas vulkanik dan 1 persen oleh tanah longsor yang terjadi dalam tubuh air (danau atau laut) maupun longsoran dari darat yang masuk ke dalam tubuh air. Selama kurun waktu 30 tahun terakhir (1989-2019), tercatat bahwa bencana tsunami telah menyebabkan kehilangan jiwa dan kerugian infrastruktur yang besar. Antara tahun 1989-2019 telah terjadi tsunami besar sebagai berikut: (1)Tsunami di Flores (1992); (2) Tsunami di Banyuwangi Jawa Timur (1994); (3) Tsunami di Biak (1996); (4) Tsunami di Maluku (1998); (5) Tsunami di Banggai Sulawesi Utara (2000); (6) Tsunami di Aceh (2004); (7) Tsunami di Nias (2005); (8) Tsunami di Jawa Barat (2006); (9) Tsunami di Bengkulu (2007); (10) Tsunami di Mentawai (2010), dan (11) Tsunami di Selat Sunda (2018).
Bencana geologis lainnya yang memerlukan kesiapsiagaan besar adalah bencana letusan gunung api. Sejarah mencatat bahwa Indonesia pernah menjadi tempat terjadinya dua letusan gunung api terbesar di dunia. Tahun 1815 Gunung Tambora yang berada di Pulau Sumbawa, Nusa Tenggara Barat, meletus dan mengeluarkan sekitar 1,7 juta ton abu dan material vulkanik.
Selanjutnya, Gunung Krakatau meletus pada tahun 1883. Erupsi Krakatau ini diperkirakan memiliki kekuatan setara 200 megaton TNT, kira-kira 13.000 kali kekuatan ledakan bom atom yang menghancurkan Hiroshima.', 'Lampiran hal. 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3873, 'perban-5-2020', 32, 'lampiran', 'Lampiran hal. 20', NULL, 20, 'Dalam kurun waktu 30 tahun terakhir, terdapat beberapa gunungapi yang harus mendapatkan perhatian penuh karena memiliki potensi erupsi yang tinggi, yaitu antara lain Gunung Sinabung, Gunung Merapi, Gunung Soputan, Gunung Agung, dan Gunung Lokon. Sedangkan kawah gunungapi yang perlu mendapat perhatian khusus adalah kawah Gunung Ijen dan Gunung Dempo.
Jumlah bencana hidrometeorologis terus menunjukkan tren naik yang positif.
Perubahan iklim telah menyebabkan meningkatnya bencana hidrometeorologis, yang diperburuk dengan degradasi kualitas lingkungan akibat ulah manusia. Perubahan iklim diprediksi menyebabkan temperatur permukaan di wilayah Indonesia meningkat secara konsisten.
Salah satu bencana hidrometeorologis adalah gelombang tinggi dan hampir semua kota/ kabupaten yang terletak di garis pantai tidak luput dari risiko ini. Gelombang tinggi telah membuat nelayan menjadi susah melaut dan selanjutnya berdampak pada menurunnya pendapatan nelayan. Gelombang tinggi akan mengurangi daya jelajah atau wilayah tangkap ikan nelayan dan membahayakan keselamatan pelayaran dengan ukuran kapal di bawah 10 GT.
Pengaruh lain dari perubahan iklim adalah berubahnya pola curah hujan. Hal ini ditunjukkan dengan semakin tingginya curah hujan pada bulan-bulan basah dan semakin rendah curah hujan pada bulan-bulan kering dengan rentang nilai perbedaan curah hujan berkisar -2,5 hingga 2,5 mm/hari.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3873, 'Dalam kurun waktu 30 tahun terakhir, terdapat beberapa gunungapi yang harus mendapatkan perhatian penuh karena memiliki potensi erupsi yang tinggi, yaitu antara lain Gunung Sinabung, Gunung Merapi, Gunung Soputan, Gunung Agung, dan Gunung Lokon. Sedangkan kawah gunungapi yang perlu mendapat perhatian khusus adalah kawah Gunung Ijen dan Gunung Dempo.
Jumlah bencana hidrometeorologis terus menunjukkan tren naik yang positif.
Perubahan iklim telah menyebabkan meningkatnya bencana hidrometeorologis, yang diperburuk dengan degradasi kualitas lingkungan akibat ulah manusia. Perubahan iklim diprediksi menyebabkan temperatur permukaan di wilayah Indonesia meningkat secara konsisten.
Salah satu bencana hidrometeorologis adalah gelombang tinggi dan hampir semua kota/ kabupaten yang terletak di garis pantai tidak luput dari risiko ini. Gelombang tinggi telah membuat nelayan menjadi susah melaut dan selanjutnya berdampak pada menurunnya pendapatan nelayan. Gelombang tinggi akan mengurangi daya jelajah atau wilayah tangkap ikan nelayan dan membahayakan keselamatan pelayaran dengan ukuran kapal di bawah 10 GT.
Pengaruh lain dari perubahan iklim adalah berubahnya pola curah hujan. Hal ini ditunjukkan dengan semakin tingginya curah hujan pada bulan-bulan basah dan semakin rendah curah hujan pada bulan-bulan kering dengan rentang nilai perbedaan curah hujan berkisar -2,5 hingga 2,5 mm/hari.', 'Lampiran hal. 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3874, 'perban-5-2020', 33, 'lampiran', 'Lampiran hal. 20', NULL, 20, 'Berubahnya pola curah hujan dapat meningkatkan risiko bencana lain, seperti kekeringan dan kebakaran hutan.
Selain dipicu oleh faktor berkurangnya curah hujan, kebakaran hutan juga sering kali dipicu faktor keterlibatan manusia. Kebakaran hutan telah memberikan kerugian fisik dan ekonomi yang besar. Selain mengakibatkan masalah polusi udara, kebakaran hutan juga telah mengakibatkan menurunnya tingkat kesehatan masyarakat terdampak dan membahayakan keselamatan transportasi.
Secara umum, kejadian bencana di Indonesia telah menyebabkan timbulnya korban jiwa. Salah satu penyebab banyaknya korban jiwa dan korban terdampak adalah karena sebagian besar wilayah permukiman di Indonesia terletak di daerah rawan bencana. Selain itu, rata-rata rencana lokasi pembangunan infrastruktur pada tahun 2045 berada di daerah risiko bencana tinggi. Sehingga diperlukan pengarusutamaan pengurangan risiko bencana dalam setiap rencana pembangunan.
Data BNPB dalam kurun waktu lima tahun terakhir (2015 - 2019) menunjukkan adanya kecenderungan peningkatan frekuensi kejadian bencana di Indonesia. Untuk lebih jelasnya dapat dilihat pada grafik berikut ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3874, 'Berubahnya pola curah hujan dapat meningkatkan risiko bencana lain, seperti kekeringan dan kebakaran hutan.
Selain dipicu oleh faktor berkurangnya curah hujan, kebakaran hutan juga sering kali dipicu faktor keterlibatan manusia. Kebakaran hutan telah memberikan kerugian fisik dan ekonomi yang besar. Selain mengakibatkan masalah polusi udara, kebakaran hutan juga telah mengakibatkan menurunnya tingkat kesehatan masyarakat terdampak dan membahayakan keselamatan transportasi.
Secara umum, kejadian bencana di Indonesia telah menyebabkan timbulnya korban jiwa. Salah satu penyebab banyaknya korban jiwa dan korban terdampak adalah karena sebagian besar wilayah permukiman di Indonesia terletak di daerah rawan bencana. Selain itu, rata-rata rencana lokasi pembangunan infrastruktur pada tahun 2045 berada di daerah risiko bencana tinggi. Sehingga diperlukan pengarusutamaan pengurangan risiko bencana dalam setiap rencana pembangunan.
Data BNPB dalam kurun waktu lima tahun terakhir (2015 - 2019) menunjukkan adanya kecenderungan peningkatan frekuensi kejadian bencana di Indonesia. Untuk lebih jelasnya dapat dilihat pada grafik berikut ini.', 'Lampiran hal. 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3875, 'perban-5-2020', 34, 'lampiran', 'Lampiran hal. 21', NULL, 21, 'Frekuensi Kejadian 5000 3814 4000 3000 2271 2384 2572 2000 1681 1000 0 s)0,76 •20,76, Gambar 1.9. Frekuensi Kejadian Bencana di Indonesia Periode 2015-2019 Dari grafik di atas terlihat bahwa pada tahun 2015 frekuensi kejadian bencana di Indonesia terdapat 1.681 kejadian dan tampak terjadi kenaikan frekuensi kejadian setiap tahunnya. Pada tahun 2019, frekuensi kejadian bencana di Indonesa tercatat menjadi 3.814 kejadian (lebih dari dua kali lipat dari tahun 2015).
Bila dilihat jumlah korban yang terdampak bencana pada periode tahun 2015 -2019, terdapat fluktuasi data korban meninggal dunia. Jumlah terbanyak korban meninggal dunia yakni pada tahun 2018 yaitu sebanyak 6.240 jiwa, dimana pada saat itu telah terjadi bencana yang cukup besar yaitu gempabumi di wilayah Lombok, gempabumi, tsunami dan likuifaksi di wilayah Palu dan sekitarnya serta tsunami di wilayah Selat Sunda. Jumlah keseluruhan korban meninggal dunia akibat bencana di Indonesia untuk periode 2015-2019 adalah sebanyak 8.061 jiwa. Untuk lebih jelasnya dapat dilihat pada gambar berikut ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3875, 'Frekuensi Kejadian 5000 3814 4000 3000 2271 2384 2572 2000 1681 1000 0 s)0,76 •20,76, Gambar 1.9. Frekuensi Kejadian Bencana di Indonesia Periode 2015-2019 Dari grafik di atas terlihat bahwa pada tahun 2015 frekuensi kejadian bencana di Indonesia terdapat 1.681 kejadian dan tampak terjadi kenaikan frekuensi kejadian setiap tahunnya. Pada tahun 2019, frekuensi kejadian bencana di Indonesa tercatat menjadi 3.814 kejadian (lebih dari dua kali lipat dari tahun 2015).
Bila dilihat jumlah korban yang terdampak bencana pada periode tahun 2015 -2019, terdapat fluktuasi data korban meninggal dunia. Jumlah terbanyak korban meninggal dunia yakni pada tahun 2018 yaitu sebanyak 6.240 jiwa, dimana pada saat itu telah terjadi bencana yang cukup besar yaitu gempabumi di wilayah Lombok, gempabumi, tsunami dan likuifaksi di wilayah Palu dan sekitarnya serta tsunami di wilayah Selat Sunda. Jumlah keseluruhan korban meninggal dunia akibat bencana di Indonesia untuk periode 2015-2019 adalah sebanyak 8.061 jiwa. Untuk lebih jelasnya dapat dilihat pada gambar berikut ini.', 'Lampiran hal. 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3876, 'perban-5-2020', 35, 'lampiran', 'Lampiran hal. 22', NULL, 22, 'Jumlah korban meninggai aklbat bencana 7000 6,240 6000 5000 4000 3000 2000 100• /8 378 589 2.16 0 2 0 1.5 2016 2017 2018 2019 Gambar 1.10. Jumlah Korban Meninggal Dunia Akibat Bencana di Indonesia Periode 2015 - 2019 Selain adanya korban meninggal dunia, bencana yang terjadi juga mengakibatkan adanya sekelompok penduduk yang terpaksa mengungsi dan yang tidak mengungsi akan tetap terancam jiwanya (menderita). Berdasarkan data yang dihimpun oleh BNPB sepanjang tahun 2015-2019, menunjukkan bahwa selama periode tersebut jumlah penduduk yang menderita dan mengungsi akibat bencana adalah sebesar 24.611.373 jiwa. Jumlah penduduk yang menderita dan mengungsi akibat bencana tertinggi terjadi pada tahun 2018 yaitu sebesar 10.417.179 jiwa. Untuk lebih jelasnya mengenai jumlah penduduk yang menderita dan mengungsi akibat bencana untuk periode tahun 2015-2019 dapat dilihat pada gambar berikut ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3876, 'Jumlah korban meninggai aklbat bencana 7000 6,240 6000 5000 4000 3000 2000 100• /8 378 589 2.16 0 2 0 1.5 2016 2017 2018 2019 Gambar 1.10. Jumlah Korban Meninggal Dunia Akibat Bencana di Indonesia Periode 2015 - 2019 Selain adanya korban meninggal dunia, bencana yang terjadi juga mengakibatkan adanya sekelompok penduduk yang terpaksa mengungsi dan yang tidak mengungsi akan tetap terancam jiwanya (menderita). Berdasarkan data yang dihimpun oleh BNPB sepanjang tahun 2015-2019, menunjukkan bahwa selama periode tersebut jumlah penduduk yang menderita dan mengungsi akibat bencana adalah sebesar 24.611.373 jiwa. Jumlah penduduk yang menderita dan mengungsi akibat bencana tertinggi terjadi pada tahun 2018 yaitu sebesar 10.417.179 jiwa. Untuk lebih jelasnya mengenai jumlah penduduk yang menderita dan mengungsi akibat bencana untuk periode tahun 2015-2019 dapat dilihat pada gambar berikut ini.', 'Lampiran hal. 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3877, 'perban-5-2020', 36, 'lampiran', 'Lampiran hal. 22', NULL, 22, 'Jumlan penduduk menderita dan mengungsl akibat bencana Indonesla 12000000 10,417,179 10000000 8000000 6,129,405 6000000 3,674,369 4000000 3,162,491 2000000 1,227,929 o 2015 2016 2017 2016 2019 Gambar 1.11. Jumlah Penduduk Menderita dan Mengungsi Akibat Bencana di Indonesia Periode 2015-2019 Kerugian akibat kejadian bencana tidak saja mengakibatkan korban jiwa, namun juga kerugian ekonomi. Kerugian ekonomi akibat bencana di Indonesia berdasarkan data BNPB dalam tiga tahun terakhir (2017 2019) menunjukkan nilai yang cukup besar. Pada tahun 2017 kerugian ekonomi akibat bencana di Indonesia sebesar 30 trilyun rupiah, meningkat pada tahun 2018 menjadi 34 trilyun rupiah, kemudian meningkat lagi menjadi 1,8 trilyun rupiah pada tahun 2019. Untuk lebih jelasnya dapat di lihat pada grafik berikut ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3877, 'Jumlan penduduk menderita dan mengungsl akibat bencana Indonesla 12000000 10,417,179 10000000 8000000 6,129,405 6000000 3,674,369 4000000 3,162,491 2000000 1,227,929 o 2015 2016 2017 2016 2019 Gambar 1.11. Jumlah Penduduk Menderita dan Mengungsi Akibat Bencana di Indonesia Periode 2015-2019 Kerugian akibat kejadian bencana tidak saja mengakibatkan korban jiwa, namun juga kerugian ekonomi. Kerugian ekonomi akibat bencana di Indonesia berdasarkan data BNPB dalam tiga tahun terakhir (2017 2019) menunjukkan nilai yang cukup besar. Pada tahun 2017 kerugian ekonomi akibat bencana di Indonesia sebesar 30 trilyun rupiah, meningkat pada tahun 2018 menjadi 34 trilyun rupiah, kemudian meningkat lagi menjadi 1,8 trilyun rupiah pada tahun 2019. Untuk lebih jelasnya dapat di lihat pada grafik berikut ini.', 'Lampiran hal. 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3878, 'perban-5-2020', 37, 'lampiran', 'Lampiran hal. 23', NULL, 23, 'Trilyun Rupiah 90 81.8 80 70 60 50 40 34 30 30 20 10 0 (.9 Gambar 1.12. Perkembangan Kerugian Ekonomi Akibat Bencana di Indonesia Periode 2017 - 2019 Dengan meningkatnya kerugian ekonomi akibat bencana tentunya akan berdampak terhadap pelaksanaan pembangunan dan pertumbuhan ekonomi Indonesia. .3 Peraturan Perundang- undan an Penyelenggaraan penanggulangan bencana pada hakekatnya adalah upaya yang dilakukan oleh seluruh komponen bangsa Indonesia. Untuk memberikan perlindungan kepada segenap lapisan masyarakat dari ancaman bencana. Dalam rangka mewujudkannya, diperlukan masyarakat yang berkemampuan untuk melaksanakan pembangunan nasional secara berkelanjutan dalam upaya mencapai cita-cita kemerdekaan menuju masyarakat adil dan makmur.
Undang-Undang Nomor 25 tahun 2004 tentang Sistem Perencanaan Pembangunan Nasional telah mengamanatkan bahwa setiap kementerian/lembaga agar menyusun Rencana Strategis yang mengacu kepada Rencana Pembangunan Jangka Menengah Nasional. Dengan telah ditetapkannya RPJMN 2020-2024 dalam Peraturan Presiden Nomor 18 Tahun 2020, maka Badan Nasional Penanggulangan Bencana perlu menyusun Renstra 2020-2024. Penyusunan Renstra BNPB berpedoman pada Peraturan Menteri Perencanaan Pembangunan Nasional/Kepala Bappenas Nomor 5 tahun 2019 tentang Tata Cara Penyusunan Rencana Strategis Kementerian/Lembaga Tahun 2020-2024.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3878, 'Trilyun Rupiah 90 81.8 80 70 60 50 40 34 30 30 20 10 0 (.9 Gambar 1.12. Perkembangan Kerugian Ekonomi Akibat Bencana di Indonesia Periode 2017 - 2019 Dengan meningkatnya kerugian ekonomi akibat bencana tentunya akan berdampak terhadap pelaksanaan pembangunan dan pertumbuhan ekonomi Indonesia. .3 Peraturan Perundang- undan an Penyelenggaraan penanggulangan bencana pada hakekatnya adalah upaya yang dilakukan oleh seluruh komponen bangsa Indonesia. Untuk memberikan perlindungan kepada segenap lapisan masyarakat dari ancaman bencana. Dalam rangka mewujudkannya, diperlukan masyarakat yang berkemampuan untuk melaksanakan pembangunan nasional secara berkelanjutan dalam upaya mencapai cita-cita kemerdekaan menuju masyarakat adil dan makmur.
Undang-Undang Nomor 25 tahun 2004 tentang Sistem Perencanaan Pembangunan Nasional telah mengamanatkan bahwa setiap kementerian/lembaga agar menyusun Rencana Strategis yang mengacu kepada Rencana Pembangunan Jangka Menengah Nasional. Dengan telah ditetapkannya RPJMN 2020-2024 dalam Peraturan Presiden Nomor 18 Tahun 2020, maka Badan Nasional Penanggulangan Bencana perlu menyusun Renstra 2020-2024. Penyusunan Renstra BNPB berpedoman pada Peraturan Menteri Perencanaan Pembangunan Nasional/Kepala Bappenas Nomor 5 tahun 2019 tentang Tata Cara Penyusunan Rencana Strategis Kementerian/Lembaga Tahun 2020-2024.', 'Lampiran hal. 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3879, 'perban-5-2020', 38, 'lampiran', 'Lampiran hal. 24', NULL, 24, 'Tingginya frekuensi bencana yang terjadi di Indonesia berikut konsekuensinya, menj adikan aspek kebencanaan demikian penting untuk diperhitungkan dalam perencanaan pembangunan bangsa Indonesia. Oleh karena itu dalam RPJMN 2020-2024, penanggulangan kebencanaan telah ditetapkan sebagai salah satu agenda pembangunan nasional untuk lima tahun kedepan.
Selain Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, terdapat undang-undang lain yang berkaitan erat dengan urusan kebencanaan, yaitu Undang-Undang Nomor 26 Tahun 2007 tentang Penataan Ruang. Undang-undang ini menyatakan bahwa Indonesia berada pada kawasan bencana, sehingga diperlukan penataan ruang berbasis mitigasi bencana sebagai upaya meningkatkan keselamatan dan kenyamanan kehidupan dan penghidupan.
Selanjutnya, menurut Pasal 56-59 Undang-Undang Nomor 27 Tahun 2007 tentang Pengelolaan Wilayah Pesisir dan Pulau-Pulau kecil, terkait mitigasi bencana, dinyatakan bahwa dalam menyusun rencana pengelolaan dan pemanfataan wilayah pesisir dan pulau-pulau kecil terpadu, Pemerintah dan/ atau Pemerintah Daerah wajib memasukkan dan melaksanakan bagian yang memuat mitigasi bencana di wilayah pesisir dan pulau-pulau kecil sesuai dengan jenis, tingkat, dan wilayahnya.
Kementerian kementerian teknis yang urusannya masih terkait dengan bencana perlu mengeluarkan Norma, Standar, Prosedur dan Kriteria (NSPK) yang memperhatikan kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3879, 'Tingginya frekuensi bencana yang terjadi di Indonesia berikut konsekuensinya, menj adikan aspek kebencanaan demikian penting untuk diperhitungkan dalam perencanaan pembangunan bangsa Indonesia. Oleh karena itu dalam RPJMN 2020-2024, penanggulangan kebencanaan telah ditetapkan sebagai salah satu agenda pembangunan nasional untuk lima tahun kedepan.
