INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3920, 'perban-5-2020', 79, 'lampiran', 'Lampiran hal. 52', NULL, 52, '2 Terselamatkannya sebanyak Rata-rata angka Jiwa/ mungkin jiwa pada saat keadaan kematian akibat 100.000 darurat bencana. bencana saat penduduk keadaan darurat wilayah per 100.000 terdampak jiwa.
3 Terpulihkannya sarana dan Rata-rata indeks prasarana, social, ekonomi dan Kenaikan Indeks produktivitas sumber daya alam Pemulihan pada daerah terdampak Pascabencana. pascabencana.
No Sasaran Strategis Indikator Kinerja Satuan Sasaran Strate: s 4 Meningkatnya kualitas tata kelola Indeks Reformasi indeks penyelengaraan penanggulangan Birokrasi. bencana yang profesional, akuntabel dan transparan.
Sinergitas pencapaian visi, misi, tujuan, dan sasaran strategis BNPB 2020-2024 melibatkan seluruh unit kerja BNPB dan juga didukung oleh lembaga lain baik di tingkat pusat maupun daerah. BNPB merupakan lembaga yang memiliki fungsi perumusan dan penetapan kebijakan penanggulangan bencana dan pengoordinasian pelaksanaan kegiatan penanggulangan bencana secara terencana, terpadu, dan menyeluruh. Tugas BNPB pada dasarnya adalah melakukan penanggulangan bencana melalui tiga tahapan, yaitu: prabencana, keadaan darurat, dan pascabencana. Untuk menjamin tercapainya penanganan bencana yang andal, maka fungsi BNPB pada ketiga tahapan penanggulangan bencana harus didukung oleh semua sumber daya yang ada di BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3920, '2 Terselamatkannya sebanyak Rata-rata angka Jiwa/ mungkin jiwa pada saat keadaan kematian akibat 100.000 darurat bencana. bencana saat penduduk keadaan darurat wilayah per 100.000 terdampak jiwa.
3 Terpulihkannya sarana dan Rata-rata indeks prasarana, social, ekonomi dan Kenaikan Indeks produktivitas sumber daya alam Pemulihan pada daerah terdampak Pascabencana. pascabencana.
