INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3973, 'perban-5-2021', 1, 'menimbang', 'Menimbang', NULL, 1, 'bahwa untuk melaksanakan Instruksi Presiden Republik Indonesia Nomor 2 Tahun 2021 tentang Optimalisasi Pelaksanaan Program Jaminan Sosial Ketenagakerjaan, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Jaminan Sosial Ketenagakerjaan Bagi Pekerja di Bidang Kebencanaan, 1 1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3973, 'bahwa untuk melaksanakan Instruksi Presiden Republik Indonesia Nomor 2 Tahun 2021 tentang Optimalisasi Pelaksanaan Program Jaminan Sosial Ketenagakerjaan, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Jaminan Sosial Ketenagakerjaan Bagi Pekerja di Bidang Kebencanaan, 1 1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial bagi Pekerja di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3974, 'perban-5-2021', 2, 'mengingat', 'Mengingat', NULL, 1, '2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461),');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3974, '2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461),', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial bagi Pekerja di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3975, 'perban-5-2021', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG JAMINAN SOSIAL KETENAGAKERJAAN BAGI PEKERJA DI BIDANG KEBENCANAAN.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3975, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG JAMINAN SOSIAL KETENAGAKERJAAN BAGI PEKERJA DI BIDANG KEBENCANAAN.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial bagi Pekerja di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3976, 'perban-5-2021', 4, 'pasal', 'Pasal 1', NULL, 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Jaminan Sosial adalah salah satu bentuk perlindungan sosial untuk menjamin seluruh rakyat agar dapat memenuhi kebutuhan dasar hidupnya yang layak.
2. Pekerja Bidang Kebencanaan adalah pekerja yang melakukan penanggulangan bencana.
3. Peserta adalah setiap orang, termasuk orang asing yang bekerja paling singkat 6 (enam) bulan di Indonesia, yang telah membayar iuran.
4. Jaminan Kecelakaan Kerja yang selanjutnya disingkat JKK adalah manfaat berupa uang tunai dan/atau pelayanan kesehatan yang diberikan pada saat Peserta mengalami kecelakaan kerja atau penyakit yang disebabkan lingkungan kerja.
5. Jaminan Kematian yang selanjutnya disingkat JKM adalah manfaat uang tunai yang diberikan kepada ahli waris ketika Peserta meninggal dunia bukan akibat kecelakaan kerja.
6. Jaminan Hari Tua yang selanjutnya disingkat JHT adalah manfaat uang tunai yang dibayarkan sekaligus pada saat Peserta selesai perjanjian kerja dan kembali ke Indonesia, meninggal dunia, atau mengalami cacat total tetap.
7. Pemberi Kerja adalah orang perseorangan, pengusaha, badan hukum, atau badan lainnya yang mempekerjakan tenaga kerja atau penyelenggara negara yang mempekerjakan pegawai negeri dengan membayar gaji, upah, atau imbalan dalam bentuk lainnya.
8. Iuran adalah sejumlah uang yang dibayar secara teratur oleh Peserta, Pemberi Kerja, dan/atau Pemerintah.
9. Manfaat adalah faedah Jaminan Sosial yang menjadi hak peserta dan/atau anggota keluarganya.
10. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan.
11. Badan Penyelenggara Jaminan Sosial Ketenagakerjaan yang selanjutnya disebut BPJS Ketenagakerjaan adalah badan hukum publik yang dibentuk oleh Undang-Undang Nomor 24 Tahun 2011 tentang Badan Penyelenggara Jaminan Sosial.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3976, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Jaminan Sosial adalah salah satu bentuk perlindungan sosial untuk menjamin seluruh rakyat agar dapat memenuhi kebutuhan dasar hidupnya yang layak.
2. Pekerja Bidang Kebencanaan adalah pekerja yang melakukan penanggulangan bencana.
3. Peserta adalah setiap orang, termasuk orang asing yang bekerja paling singkat 6 (enam) bulan di Indonesia, yang telah membayar iuran.
4. Jaminan Kecelakaan Kerja yang selanjutnya disingkat JKK adalah manfaat berupa uang tunai dan/atau pelayanan kesehatan yang diberikan pada saat Peserta mengalami kecelakaan kerja atau penyakit yang disebabkan lingkungan kerja.
5. Jaminan Kematian yang selanjutnya disingkat JKM adalah manfaat uang tunai yang diberikan kepada ahli waris ketika Peserta meninggal dunia bukan akibat kecelakaan kerja.
6. Jaminan Hari Tua yang selanjutnya disingkat JHT adalah manfaat uang tunai yang dibayarkan sekaligus pada saat Peserta selesai perjanjian kerja dan kembali ke Indonesia, meninggal dunia, atau mengalami cacat total tetap.
7. Pemberi Kerja adalah orang perseorangan, pengusaha, badan hukum, atau badan lainnya yang mempekerjakan tenaga kerja atau penyelenggara negara yang mempekerjakan pegawai negeri dengan membayar gaji, upah, atau imbalan dalam bentuk lainnya.
8. Iuran adalah sejumlah uang yang dibayar secara teratur oleh Peserta, Pemberi Kerja, dan/atau Pemerintah.
9. Manfaat adalah faedah Jaminan Sosial yang menjadi hak peserta dan/atau anggota keluarganya.
10. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan.
11. Badan Penyelenggara Jaminan Sosial Ketenagakerjaan yang selanjutnya disebut BPJS Ketenagakerjaan adalah badan hukum publik yang dibentuk oleh Undang-Undang Nomor 24 Tahun 2011 tentang Badan Penyelenggara Jaminan Sosial.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial bagi Pekerja di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3977, 'perban-5-2021', 5, 'pasal', 'Pasal 2', NULL, 3, '(1) Jaminan Sosial ketenagakerjaan diberikan kepada Pekerja Bidang Kebencanaan.
(2) Pemberi Kerja mengikutsertakan Pekerja Bidang Kebencanaan sebagai Peserta dalam program Jaminan Sosial ketenagakerjaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3977, '(1) Jaminan Sosial ketenagakerjaan diberikan kepada Pekerja Bidang Kebencanaan.
(2) Pemberi Kerja mengikutsertakan Pekerja Bidang Kebencanaan sebagai Peserta dalam program Jaminan Sosial ketenagakerjaan.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial bagi Pekerja di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3978, 'perban-5-2021', 6, 'pasal', 'Pasal 3', NULL, 3, '(1) Peserta sebagaimana dimaksud dalam Pasal 2 ayat (2) merupakan Pekerja Bidang Kebencanaan, meliputi:
a. pegawai nonASN, dan
b. relawan kebencanaan.
(2) Relawan kebencanaan sebagaimana dimaksud pada ayat (1) huruf b terdiri atas:
a. relawan kebencanaan pada kementerian/lembaga/ daerah, dan
b. relawan kebencanaan di luar kementerian/lembaga/ daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3978, '(1) Peserta sebagaimana dimaksud dalam Pasal 2 ayat (2) merupakan Pekerja Bidang Kebencanaan, meliputi:
a. pegawai nonASN, dan
b. relawan kebencanaan.
(2) Relawan kebencanaan sebagaimana dimaksud pada ayat (1) huruf b terdiri atas:
a. relawan kebencanaan pada kementerian/lembaga/ daerah, dan
b. relawan kebencanaan di luar kementerian/lembaga/ daerah.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial bagi Pekerja di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3979, 'perban-5-2021', 7, 'pasal', 'Pasal 4', NULL, 4, 'Program Jaminan Sosial ketenagakerjaan sebagaimana dimaksud dalam Pasal 2 ayat (2) meliputi:
a. JKK,
b. JKM, dan
c. JHT.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3979, 'Program Jaminan Sosial ketenagakerjaan sebagaimana dimaksud dalam Pasal 2 ayat (2) meliputi:
a. JKK,
b. JKM, dan
c. JHT.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial bagi Pekerja di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3980, 'perban-5-2021', 8, 'pasal', 'Pasal 5', NULL, 4, '(1) Pegawai nonASN sebagaimana dimaksud dalam Pasal 3 ayat (1) huruf a dan relawan kebencanaan pada kementerian/lembaga/ daerah sebagaimana dimaksud dalam Pasal 3 ayat (2) huruf a didaftarkan dalam program Jaminan Sosial ketenagakerjaan yang meliputi JKK, JKM, dan JHT.
(2) Relawan kebencanaan di luar kementerian/lembaga/ daerah sebagaimana dimaksud dalam Pasal 3 ayat (2) huruf b didaftarkan dalam program Jaminan Sosial ketenagakerjaan yang meliputi JKK dan JKM.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3980, '(1) Pegawai nonASN sebagaimana dimaksud dalam Pasal 3 ayat (1) huruf a dan relawan kebencanaan pada kementerian/lembaga/ daerah sebagaimana dimaksud dalam Pasal 3 ayat (2) huruf a didaftarkan dalam program Jaminan Sosial ketenagakerjaan yang meliputi JKK, JKM, dan JHT.
(2) Relawan kebencanaan di luar kementerian/lembaga/ daerah sebagaimana dimaksud dalam Pasal 3 ayat (2) huruf b didaftarkan dalam program Jaminan Sosial ketenagakerjaan yang meliputi JKK dan JKM.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial bagi Pekerja di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3981, 'perban-5-2021', 9, 'pasal', 'Pasal 6', NULL, 4, 'Program Jaminan Sosial ketenagakerjaan diberikan kepada Peserta sepanjang menjalankan tugas kebencanaan dari Pemberi Kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3981, 'Program Jaminan Sosial ketenagakerjaan diberikan kepada Peserta sepanjang menjalankan tugas kebencanaan dari Pemberi Kerja.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial bagi Pekerja di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3982, 'perban-5-2021', 10, 'pasal', 'Pasal 7', NULL, 4, '(1) Pemberi Kerja menganggarkan dan bertanggung jawab atas pembayaran Iuran program Jaminan Sosial ketenagakerjaan.
(2) Turan sebagaimana dimaksud pada ayat (1) dibayarkan setiap bulan kepada BPJS Ketenagakerjaan.
(3) Besaran Iuran program Jaminan Sosial ketenagakerjaan bagi pegawai nonASN sebagaimana dimaksud dalam Pasal 3 ayat (1) huruf a dan bagi relawan kebencanaan pada kementerian/lembaga/daerah sebagaimana dimaksud dalam Pasal 3 ayat (2) huruf a, sebagai berikut:
a. JKK sebesar 0,24Y6 - 1,74Yo (nol koma dua empat persen sampai dengan satu koma tujuh empat persen) dari upah yang dilaporkan, dibayarkan oleh Pemberi Kerja dan disesuaikan dengan tingkat risiko lingkungan kerja,
b. JKM sebesar 0,3 (nol koma tiga persen) dari upah yang dilaporkan, dibayarkan oleh Pemberi Kerja, dan
c. JHT sebesar 5,7Yo (lima koma tujuh persen) terdiri dari 3,7Yo (tiga koma tujuh persen) dibayarkan oleh Pemberi Kerja dan 2 (dua persen) dibayarkan oleh Peserta.
(4) Besaran Turan program Jaminan Sosial ketenagakerjaan bagi relawan kebencanaan di luar kementerian/lembaga/daerah sebagaimana dimaksud dalam Pasal 3 ayat (2) huruf b, sebagai berikut:
a. JKK sebesar 0,1» (nol koma satu persen) dari upah yang dilaporkan, dibayarkan oleh Pemberi Kerja dan disesuaikan dengan tingkat risiko lingkungan kerja, dan
b. JKM sebesar Rp6.800,00 (enam ribu delapan ratus rupiah), dibayarkan oleh Pemberi Kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3982, '(1) Pemberi Kerja menganggarkan dan bertanggung jawab atas pembayaran Iuran program Jaminan Sosial ketenagakerjaan.
(2) Turan sebagaimana dimaksud pada ayat (1) dibayarkan setiap bulan kepada BPJS Ketenagakerjaan.
(3) Besaran Iuran program Jaminan Sosial ketenagakerjaan bagi pegawai nonASN sebagaimana dimaksud dalam Pasal 3 ayat (1) huruf a dan bagi relawan kebencanaan pada kementerian/lembaga/daerah sebagaimana dimaksud dalam Pasal 3 ayat (2) huruf a, sebagai berikut:
a. JKK sebesar 0,24Y6 - 1,74Yo (nol koma dua empat persen sampai dengan satu koma tujuh empat persen) dari upah yang dilaporkan, dibayarkan oleh Pemberi Kerja dan disesuaikan dengan tingkat risiko lingkungan kerja,
b. JKM sebesar 0,3 (nol koma tiga persen) dari upah yang dilaporkan, dibayarkan oleh Pemberi Kerja, dan
c. JHT sebesar 5,7Yo (lima koma tujuh persen) terdiri dari 3,7Yo (tiga koma tujuh persen) dibayarkan oleh Pemberi Kerja dan 2 (dua persen) dibayarkan oleh Peserta.
(4) Besaran Turan program Jaminan Sosial ketenagakerjaan bagi relawan kebencanaan di luar kementerian/lembaga/daerah sebagaimana dimaksud dalam Pasal 3 ayat (2) huruf b, sebagai berikut:
a. JKK sebesar 0,1» (nol koma satu persen) dari upah yang dilaporkan, dibayarkan oleh Pemberi Kerja dan disesuaikan dengan tingkat risiko lingkungan kerja, dan
b. JKM sebesar Rp6.800,00 (enam ribu delapan ratus rupiah), dibayarkan oleh Pemberi Kerja.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial bagi Pekerja di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3983, 'perban-5-2021', 11, 'pasal', 'Pasal 8', NULL, 5, 'Tingkat risiko lingkungan kerja sebagaimana dimaksud dalam Pasal 7 memperhatikan kontak langsung/tidak langsung antara Pekerja Bidang Kebencanaan dengan penanganan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3983, 'Tingkat risiko lingkungan kerja sebagaimana dimaksud dalam Pasal 7 memperhatikan kontak langsung/tidak langsung antara Pekerja Bidang Kebencanaan dengan penanganan bencana.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial bagi Pekerja di Bidang Penanggulangan Bencana');
