INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3985, 'perban-5-2021', 13, 'pasal', 'Pasal 10', NULL, 6, '(1) Terhadap Iuran sebagaimana dimaksud dalam Pasal 7 ayat (3), ayat (4), dan ayat (5), Peserta memperoleh Manfaat program Jaminan Sosial ketenagakerjaan.
