INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3990, 'perban-5-2022', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk menyesuaikan besaran iuran jaminan kecelakaan kerja bagi peserta bukan penerima upah dengan ketentuan Pasal 20 ayat (1) Peraturan Pemerintah Nomor 44 Tahun 2015 tentang Penyelenggaraan Program Jaminan Kecelakaan Kerja dan Jaminan Kematian, perlu mengubah ketentuan dalam Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial Ketenagakerjaan bagi Pekerja di Bidang Kebencanaan,
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial Ketenagakerjaan bagi Pekerja di Bidang Kebencanaan,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3990, 'a. bahwa untuk menyesuaikan besaran iuran jaminan kecelakaan kerja bagi peserta bukan penerima upah dengan ketentuan Pasal 20 ayat (1) Peraturan Pemerintah Nomor 44 Tahun 2015 tentang Penyelenggaraan Program Jaminan Kecelakaan Kerja dan Jaminan Kematian, perlu mengubah ketentuan dalam Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial Ketenagakerjaan bagi Pekerja di Bidang Kebencanaan,
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial Ketenagakerjaan bagi Pekerja di Bidang Kebencanaan,', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2022 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial Ketenagakerjaan bagi Pekerja di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3991, 'perban-5-2022', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461),
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial Ketenagakerjaan bagi Pekerja di Bidang Kebencanaan (Berita Negara Republik Indonesia Tahun 2021 Nomor 1543):');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3991, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461),
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial Ketenagakerjaan bagi Pekerja di Bidang Kebencanaan (Berita Negara Republik Indonesia Tahun 2021 Nomor 1543):', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2022 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial Ketenagakerjaan bagi Pekerja di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3992, 'perban-5-2022', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PERUBAHAN ATAS PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 5 TAHUN 2021 TENTANG JAMINAN SOSIAL KETENAGAKERJAAN BAGI PEKERJA DI BIDANG KEBENCANAAN.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3992, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PERUBAHAN ATAS PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 5 TAHUN 2021 TENTANG JAMINAN SOSIAL KETENAGAKERJAAN BAGI PEKERJA DI BIDANG KEBENCANAAN.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2022 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial Ketenagakerjaan bagi Pekerja di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3993, 'perban-5-2022', 4, 'pasal', 'Pasal I', NULL, 3, 'Ketentuan Pasal 7 dalam Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial Ketenagakerjaan bagi Pekerja di Bidang Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2021 Nomor 1543) diubah, sehingga berbunyi sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3993, 'Ketentuan Pasal 7 dalam Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial Ketenagakerjaan bagi Pekerja di Bidang Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2021 Nomor 1543) diubah, sehingga berbunyi sebagai berikut:', 'Pasal I', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2022 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial Ketenagakerjaan bagi Pekerja di Bidang Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3994, 'perban-5-2022', 5, 'pasal', 'Pasal 7', NULL, 3, '(1) Pemberi Kerja menganggarkan dan bertanggung jawab atas pembayaran Iuran program Jaminan Sosial ketenagakerjaan.
(2) Iuran sebagaimana dimaksud pada ayat (1) dibayarkan setiap bulan kepada BPJS Ketenagakerjaan.
(3) Besaran Turan program Jaminan Sosial ketenagakerjaan bagi pegawai nonASN sebagaimana dimaksud dalam Pasal 3 ayat (1) huruf a, sebagai berikut:
a. JKK sebesar 0,24Y6 (nol koma dua empat persen) dari upah yang dilaporkan, dibayarkan oleh Pemberi Kerja,
b. JKM sebesar 0,3Yb (nol koma tiga persen) dari upah yang dilaporkan, dibayarkan oleh Pemberi Kerja, dan
c. JHT sebesar 5,746 (lima koma tujuh persen) terdiri dari 3,70 (tiga koma tujuh persen) dibayarkan oleh Pemberi Kerja dan 26 (dua persen) dibayarkan oleh Peserta.
(4) Besaran Iuran program Jaminan Sosial ketenagakerjaan bagi relawan kebencanaan pada kementerian/lembaga/daerah sebagaimana dimaksud dalam Pasal 3 ayat (2) huruf a dan relawan kebencanaan di luar kementerian/lembaga/ daerah sebagaimana dimaksud dalam Pasal 3 ayat (2) huruf b, sebagai berikut:
a. JKK sebesar 1 (satu persen) dari dasar penghasilan penetapan manfaat JKK, dibayarkan oleh Pemberi Kerja, dan
b. JKM sebesar Rp6.800,00 (enam ribu delapan ratus rupiah), dibayarkan oleh Pemberi Kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3994, '(1) Pemberi Kerja menganggarkan dan bertanggung jawab atas pembayaran Iuran program Jaminan Sosial ketenagakerjaan.
(2) Iuran sebagaimana dimaksud pada ayat (1) dibayarkan setiap bulan kepada BPJS Ketenagakerjaan.
(3) Besaran Turan program Jaminan Sosial ketenagakerjaan bagi pegawai nonASN sebagaimana dimaksud dalam Pasal 3 ayat (1) huruf a, sebagai berikut:
a. JKK sebesar 0,24Y6 (nol koma dua empat persen) dari upah yang dilaporkan, dibayarkan oleh Pemberi Kerja,
b. JKM sebesar 0,3Yb (nol koma tiga persen) dari upah yang dilaporkan, dibayarkan oleh Pemberi Kerja, dan
c. JHT sebesar 5,746 (lima koma tujuh persen) terdiri dari 3,70 (tiga koma tujuh persen) dibayarkan oleh Pemberi Kerja dan 26 (dua persen) dibayarkan oleh Peserta.
(4) Besaran Iuran program Jaminan Sosial ketenagakerjaan bagi relawan kebencanaan pada kementerian/lembaga/daerah sebagaimana dimaksud dalam Pasal 3 ayat (2) huruf a dan relawan kebencanaan di luar kementerian/lembaga/ daerah sebagaimana dimaksud dalam Pasal 3 ayat (2) huruf b, sebagai berikut:
a. JKK sebesar 1 (satu persen) dari dasar penghasilan penetapan manfaat JKK, dibayarkan oleh Pemberi Kerja, dan
b. JKM sebesar Rp6.800,00 (enam ribu delapan ratus rupiah), dibayarkan oleh Pemberi Kerja.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2022 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2021 tentang Jaminan Sosial Ketenagakerjaan bagi Pekerja di Bidang Kebencanaan');
