INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (3999, 'perban-5-2024', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk mengembangkan talenta dan karier di bidang penanggulangan bencana dibutuhkan standar kompetensi jabatan yang disusun berdasarkan kamus kompetensi teknis bidang penanggulangan bencana di lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa kamus kompetensi teknis bidang penanggulangan bencana telah memperoleh persetujuan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi berdasarkan surat Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (3999, 'a. bahwa untuk mengembangkan talenta dan karier di bidang penanggulangan bencana dibutuhkan standar kompetensi jabatan yang disusun berdasarkan kamus kompetensi teknis bidang penanggulangan bencana di lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa kamus kompetensi teknis bidang penanggulangan bencana telah memperoleh persetujuan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi berdasarkan surat Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4000, 'perban-5-2024', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4000, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4001, 'perban-5-2024', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG KAMUS KOMPETENSI TEKNIS BIDANG PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4001, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG KAMUS KOMPETENSI TEKNIS BIDANG PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4002, 'perban-5-2024', 4, 'pasal', 'Pasal 1', NULL, 2, 'Dalam Peraturan Badan ini, yang dimaksud dengan:
1. Kamus Kompetensi adalah kumpulan kompetensi yang meliputi nama kompetensi, definisi kompetensi, deskripsi dan level kompetensi serta Indikator Kompetensi.
2. Kompetensi Teknis adalah pengetahuan, keterampilan, dan sikap/perilaku yang dapat diamati, diukur dan dikembangkan yang spesifik berkaitan dengan bidang teknis jabatan.
3. Aparatur Sipil Negara yang selanjutnya disingkat ASN adalah profesi bagi pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang bekerja pada instansi pemerintah.
4. Pegawai Aparatur Sipil Negara yang selanjutnya disebut Pegawai ASN adalah pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan diberikan penghasilan berdasarkan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4002, 'Dalam Peraturan Badan ini, yang dimaksud dengan:
1. Kamus Kompetensi adalah kumpulan kompetensi yang meliputi nama kompetensi, definisi kompetensi, deskripsi dan level kompetensi serta Indikator Kompetensi.
2. Kompetensi Teknis adalah pengetahuan, keterampilan, dan sikap/perilaku yang dapat diamati, diukur dan dikembangkan yang spesifik berkaitan dengan bidang teknis jabatan.
3. Aparatur Sipil Negara yang selanjutnya disingkat ASN adalah profesi bagi pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang bekerja pada instansi pemerintah.
4. Pegawai Aparatur Sipil Negara yang selanjutnya disebut Pegawai ASN adalah pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan diberikan penghasilan berdasarkan peraturan perundang-undangan.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4003, 'perban-5-2024', 5, 'pasal', 'Pasal 2', NULL, 2, '(1) Kamus Kompetensi Teknis bidang penanggulangan bencana digunakan untuk:
a. penyusunan standar kompetensi jabatan ASN penanggulangan bencana sesuai karakter tugas jabatan;
b. untuk perencanaan sumber daya manusia, seleksi penerimaan sumber daya manusia, penempatan sumber daya manusia, pengembangan kompetensi, pengembangan karier, promosi, dan mutasi;
c. penyusunan kurikulum pendidikan dan pelatihan teknis bidang penanggulangan bencana; dan
d. penyusunan materi uji kompetensi teknis bidang penanggulangan bencana.
(2) Kamus Kompetensi Teknis bidang penanggulangan bencana diperuntukkan bagi:
a. kementerian/lembaga yang mempunyai tugas terkait penanggulangan bencana; dan
b. perangkat daerah di provinsi dan kabupaten/kota yang menyelenggarakan urusan penyelenggaraan layanan ketenteraman dan ketertiban umum serta perlindungan masyarakat suburusan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4003, '(1) Kamus Kompetensi Teknis bidang penanggulangan bencana digunakan untuk:
a. penyusunan standar kompetensi jabatan ASN penanggulangan bencana sesuai karakter tugas jabatan;
b. untuk perencanaan sumber daya manusia, seleksi penerimaan sumber daya manusia, penempatan sumber daya manusia, pengembangan kompetensi, pengembangan karier, promosi, dan mutasi;
c. penyusunan kurikulum pendidikan dan pelatihan teknis bidang penanggulangan bencana; dan
d. penyusunan materi uji kompetensi teknis bidang penanggulangan bencana.
(2) Kamus Kompetensi Teknis bidang penanggulangan bencana diperuntukkan bagi:
a. kementerian/lembaga yang mempunyai tugas terkait penanggulangan bencana; dan
b. perangkat daerah di provinsi dan kabupaten/kota yang menyelenggarakan urusan penyelenggaraan layanan ketenteraman dan ketertiban umum serta perlindungan masyarakat suburusan bencana.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4004, 'perban-5-2024', 6, 'pasal', 'Pasal 3', NULL, 3, 'Kamus Kompetensi Teknis Bidang Penanggulangan Bencana terdiri atas:
a. jenis kompetensi teknis;
b. nama kompetensi teknis;
c. kode kompetensi teknis;
d. definisi kompetensi teknis;
e. deskripsi level kompetensi teknis;
f. level kompetensi teknis; dan
g. indikator perilaku kompetensi teknis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4004, 'Kamus Kompetensi Teknis Bidang Penanggulangan Bencana terdiri atas:
a. jenis kompetensi teknis;
b. nama kompetensi teknis;
c. kode kompetensi teknis;
d. definisi kompetensi teknis;
e. deskripsi level kompetensi teknis;
f. level kompetensi teknis; dan
g. indikator perilaku kompetensi teknis.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4005, 'perban-5-2024', 7, 'pasal', 'Pasal 4', NULL, 3, '(1) Jenis Kompetensi Teknis sebagaimana dimaksud dalam Pasal 3 huruf a merupakan kemampuan/pengetahuan/keterampilan yang berkaitan dengan bidang penanggulangan bencana.
(2) Nama Kompetensi Teknis sebagaimana dimaksud dalam Pasal 3 huruf b merupakan pengetahuan/keterampilan/sikap/perilaku yang telah diidentifikasi sesuai dengan bidang penanggulangan bencana.
(3) Kode kompetensi teknis sebagaimana dimaksud dalam Pasal 3 huruf c merupakan penjelasan mengenai jenis dan nomor urut kompetensi.
(4) Definisi Kompetensi Teknis sebagaimana dimaksud dalam Pasal 3 huruf d merupakan penjabaran mengenai pengetahuan/keterampilan/sikap/perilaku sesuai jenis kompetensinya.
(5) Deskripsi level Kompetensi Teknis sebagaimana dimaksud dalam Pasal 3 huruf e merupakan penjabaran indikator perilaku sesuai tingkat kompetensi.
(6) Level Kompetensi Teknis sebagaimana dimaksud dalam Pasal 3 huruf f merupakan tingkat penerapan kompetensi yang berbeda-beda dalam satu jenis kompetensi.
(7) Indikator perilaku Kompetensi Teknis sebagaimana dimaksud dalam Pasal 3 huruf g merupakan tingkatan pengetahuan/keterampilan/sikap/perilaku untuk tiap tingkatan level kompetensi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4005, '(1) Jenis Kompetensi Teknis sebagaimana dimaksud dalam Pasal 3 huruf a merupakan kemampuan/pengetahuan/keterampilan yang berkaitan dengan bidang penanggulangan bencana.
(2) Nama Kompetensi Teknis sebagaimana dimaksud dalam Pasal 3 huruf b merupakan pengetahuan/keterampilan/sikap/perilaku yang telah diidentifikasi sesuai dengan bidang penanggulangan bencana.
(3) Kode kompetensi teknis sebagaimana dimaksud dalam Pasal 3 huruf c merupakan penjelasan mengenai jenis dan nomor urut kompetensi.
(4) Definisi Kompetensi Teknis sebagaimana dimaksud dalam Pasal 3 huruf d merupakan penjabaran mengenai pengetahuan/keterampilan/sikap/perilaku sesuai jenis kompetensinya.
(5) Deskripsi level Kompetensi Teknis sebagaimana dimaksud dalam Pasal 3 huruf e merupakan penjabaran indikator perilaku sesuai tingkat kompetensi.
(6) Level Kompetensi Teknis sebagaimana dimaksud dalam Pasal 3 huruf f merupakan tingkat penerapan kompetensi yang berbeda-beda dalam satu jenis kompetensi.
(7) Indikator perilaku Kompetensi Teknis sebagaimana dimaksud dalam Pasal 3 huruf g merupakan tingkatan pengetahuan/keterampilan/sikap/perilaku untuk tiap tingkatan level kompetensi.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4006, 'perban-5-2024', 8, 'pasal', 'Pasal 5', NULL, 3, 'Kamus Kompetensi Teknis bidang penanggulangan bencana sebagaimana dimaksud dalam Pasal 3 dikelompokkan dalam 2 (dua) jenis, terdiri atas:
a. kompetensi umum; dan
b. kompetensi khusus.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4006, 'Kamus Kompetensi Teknis bidang penanggulangan bencana sebagaimana dimaksud dalam Pasal 3 dikelompokkan dalam 2 (dua) jenis, terdiri atas:
a. kompetensi umum; dan
b. kompetensi khusus.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4007, 'perban-5-2024', 9, 'pasal', 'Pasal 6', NULL, 3, 'Kamus Kompetensi Teknis bidang penanggulangan bencana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4007, 'Kamus Kompetensi Teknis bidang penanggulangan bencana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4008, 'perban-5-2024', 10, 'pasal', 'Pasal 7', NULL, 3, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang yang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4008, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang yang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4009, 'perban-5-2024', 11, 'lain', 'Penutup', NULL, 4, 'Ditetapkan di Jakarta pada tanggal 25 Oktober 2024 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д PLT. DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, Ѽ ASEP N. MULYANA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2024 NOMOR Ж');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4009, 'Ditetapkan di Jakarta pada tanggal 25 Oktober 2024 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д PLT. DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, Ѽ ASEP N. MULYANA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2024 NOMOR Ж', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4010, 'perban-5-2024', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 5 TAHUN 2024 TENTANG KAMUS KOMPETENSI TEKNIS BIDANG PENANGGULANGAN BENCANA KAMUS KOMPETENSI TEKNIS BIDANG PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. UMUM
1. Pasal 2 Undang-Undang Nomor 20 Tahun 2023 tentang Aparatur Sipil Negara menyatakan penyelenggaraan kebijakan dan Manajemen Aparatur Sipil Negara berdasarkan pada asas kepastian hukum, profesionalitas, proporsionalitas, keterpaduan, pendelegasian, netralitas, akuntabilitas, efektivitas dan efisiensi, keterbukaan, nondiskriminatif, persatuan dan kesatuan, keadilan dan kesetaraan, dan kesejahteraan.
2. Pasal 3 Undang-Undang Nomor 20 Tahun 2023 bahwa Aparatur Sipil Negara sebagai profesi berlandaskan pada prinsip nilai dasar, kode etik dan kode perilaku, berorientasi pelayanan, akuntabel, kompeten, harmonis, loyal, adaptif, dan kolaboratif.
3. Pasal 46 Undang-Undang Nomor 20 Tahun 2023, bahwa pengembangan talenta dan karier dilakukan dengan mempertimbangkan kualifikasi, kompetensi, kinerja, dan kebutuhan Instansi Pemerintah.
4. Untuk mendukung terwujudnya profesionalisme Aparatur Sipil Negara dan untuk menyelenggarakan pengembangan talenta dan karier dalam manajemen Aparatur Sipil Negara diperlukan standar kompetensi jabatan, yang terdiri atas Kompetensi Teknis, Kompetensi Manajerial, Kompetensi Sosial Kultural.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4010, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 5 TAHUN 2024 TENTANG KAMUS KOMPETENSI TEKNIS BIDANG PENANGGULANGAN BENCANA KAMUS KOMPETENSI TEKNIS BIDANG PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. UMUM
1. Pasal 2 Undang-Undang Nomor 20 Tahun 2023 tentang Aparatur Sipil Negara menyatakan penyelenggaraan kebijakan dan Manajemen Aparatur Sipil Negara berdasarkan pada asas kepastian hukum, profesionalitas, proporsionalitas, keterpaduan, pendelegasian, netralitas, akuntabilitas, efektivitas dan efisiensi, keterbukaan, nondiskriminatif, persatuan dan kesatuan, keadilan dan kesetaraan, dan kesejahteraan.
2. Pasal 3 Undang-Undang Nomor 20 Tahun 2023 bahwa Aparatur Sipil Negara sebagai profesi berlandaskan pada prinsip nilai dasar, kode etik dan kode perilaku, berorientasi pelayanan, akuntabel, kompeten, harmonis, loyal, adaptif, dan kolaboratif.
3. Pasal 46 Undang-Undang Nomor 20 Tahun 2023, bahwa pengembangan talenta dan karier dilakukan dengan mempertimbangkan kualifikasi, kompetensi, kinerja, dan kebutuhan Instansi Pemerintah.
4. Untuk mendukung terwujudnya profesionalisme Aparatur Sipil Negara dan untuk menyelenggarakan pengembangan talenta dan karier dalam manajemen Aparatur Sipil Negara diperlukan standar kompetensi jabatan, yang terdiri atas Kompetensi Teknis, Kompetensi Manajerial, Kompetensi Sosial Kultural.', 'Lampiran hal. 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4011, 'perban-5-2024', 13, 'lampiran', 'Lampiran hal. 5', NULL, 5, '5. Standar Kompetensi Jabatan merupakan persyaratan kompetensi minimal yang harus dimiliki oleh seorang Aparatur Sipil Negara dalam melaksanakan tugas jabatan.
6. Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Republik Indonesia Nomor 38 Tahun 2017, bahwa untuk mendukung terwujudnya profesionalisme Aparatur Sipil Negara dan untuk menyelenggarakan Sistem Merit dalam manajemen Aparatur Sipil Negara diperlukan standar kompetensi jabatan, yang terdiri atas Kompetensi Teknis, Kompetensi Manajerial, Kompetensi Sosial Kultural.
B. MAKSUD DAN TUJUAN
1. Dokumen Kamus Kompetensi ini dimaksudkan sebagai acuan dalam Manajemen ASN di lingkungan Badan Nasional Penanggulangan Bencana untuk mengukur kompetensi individu Aparatur Sipil Negara dalam kegiatan rekrutmen, pengembangan, pengangkatan, penempatan, promosi dalam suatu jabatan, dan pelaksanaan rekrutmen terbuka jabatan tinggi di lingkungan Badan Nasional Penanggulangan Bencana.
2. Tujuan ditetapkannya Kamus Kompetensi ini adalah sarana dasar dalam menyelenggarakan sistem merit manajemen aparatur negara di lingkungan Badan Nasional Penanggulangan Bencana.
C. RUANG LINGKUP Ruang lingkup Dokumen Kamus Kompetensi ini meliputi:
1. Kompetensi yang bersifat umum (generik) yaitu kompetensi teknis yang harus dimiliki oleh seluruh (setiap jabatan) jabatan yang menyelenggarakan suatu urusan pemerintahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4011, '5. Standar Kompetensi Jabatan merupakan persyaratan kompetensi minimal yang harus dimiliki oleh seorang Aparatur Sipil Negara dalam melaksanakan tugas jabatan.
6. Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Republik Indonesia Nomor 38 Tahun 2017, bahwa untuk mendukung terwujudnya profesionalisme Aparatur Sipil Negara dan untuk menyelenggarakan Sistem Merit dalam manajemen Aparatur Sipil Negara diperlukan standar kompetensi jabatan, yang terdiri atas Kompetensi Teknis, Kompetensi Manajerial, Kompetensi Sosial Kultural.
B. MAKSUD DAN TUJUAN
1. Dokumen Kamus Kompetensi ini dimaksudkan sebagai acuan dalam Manajemen ASN di lingkungan Badan Nasional Penanggulangan Bencana untuk mengukur kompetensi individu Aparatur Sipil Negara dalam kegiatan rekrutmen, pengembangan, pengangkatan, penempatan, promosi dalam suatu jabatan, dan pelaksanaan rekrutmen terbuka jabatan tinggi di lingkungan Badan Nasional Penanggulangan Bencana.
2. Tujuan ditetapkannya Kamus Kompetensi ini adalah sarana dasar dalam menyelenggarakan sistem merit manajemen aparatur negara di lingkungan Badan Nasional Penanggulangan Bencana.
C. RUANG LINGKUP Ruang lingkup Dokumen Kamus Kompetensi ini meliputi:
1. Kompetensi yang bersifat umum (generik) yaitu kompetensi teknis yang harus dimiliki oleh seluruh (setiap jabatan) jabatan yang menyelenggarakan suatu urusan pemerintahan.', 'Lampiran hal. 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4012, 'perban-5-2024', 14, 'lampiran', 'Lampiran hal. 6', NULL, 6, '2. Kompetensi yang bersifat khusus (spesifik) yaitu kompetensi yang hanya dimiliki oleh jabatan-jabatan tertentu yang menyelenggarakan suatu urusan pemerintahan sesuai tugas jabatan.
D. BATASAN PENGERTIAN Dalam Dokumen Kamus Kompetensi ini yang dimaksud dengan:
1. Pegawai Aparatur Sipil Negara yang selanjutnya disebut Pegawai ASN adalah pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan digaji berdasarkan peraturan perundang-undangan.
2. Sistem Merit adalah kebijakan dan manajemen ASN yang berdasarkan pada kualifikasi, kompetensi, dan kinerja secara adil dan wajar dengan tanpa membedakan latar belakang politik, ras, warna kulit, agama, asal usul, jenis kelamin, status pernikahan, umur, atau kondisi kecacatan.
3. Kompetensi Teknis adalah pengetahuan, keterampilan, dan sikap/perilaku yang dapat diamati, diukur dan dikembangkan yang spesifik berkaitan dengan bidang teknis jabatan.
4. Kompetensi Manajerial adalah pengetahuan, keterampilan, dan sikap/perilaku yang dapat diamati, diukur, dikembangkan untuk memimpin dan/atau mengelola unit organisasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4012, '2. Kompetensi yang bersifat khusus (spesifik) yaitu kompetensi yang hanya dimiliki oleh jabatan-jabatan tertentu yang menyelenggarakan suatu urusan pemerintahan sesuai tugas jabatan.
D. BATASAN PENGERTIAN Dalam Dokumen Kamus Kompetensi ini yang dimaksud dengan:
1. Pegawai Aparatur Sipil Negara yang selanjutnya disebut Pegawai ASN adalah pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan digaji berdasarkan peraturan perundang-undangan.
2. Sistem Merit adalah kebijakan dan manajemen ASN yang berdasarkan pada kualifikasi, kompetensi, dan kinerja secara adil dan wajar dengan tanpa membedakan latar belakang politik, ras, warna kulit, agama, asal usul, jenis kelamin, status pernikahan, umur, atau kondisi kecacatan.
3. Kompetensi Teknis adalah pengetahuan, keterampilan, dan sikap/perilaku yang dapat diamati, diukur dan dikembangkan yang spesifik berkaitan dengan bidang teknis jabatan.
4. Kompetensi Manajerial adalah pengetahuan, keterampilan, dan sikap/perilaku yang dapat diamati, diukur, dikembangkan untuk memimpin dan/atau mengelola unit organisasi.', 'Lampiran hal. 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4013, 'perban-5-2024', 15, 'lampiran', 'Lampiran hal. 6', NULL, 6, '5. Kompetensi Sosial Kultural adalah pengetahuan, keterampilan, dan sikap/perilaku yang dapat diamati, diukur, dan dikembangkan terkait dengan pengalaman berinteraksi dengan masyarakat majemuk dalam hal agama, suku dan budaya, perilaku, wawasan kebangsaan, etika, nilai-nilai, moral, emosi dan prinsip, yang harus dipenuhi oleh setiap pemegang Jabatan untuk memperoleh hasil kerja sesuai dengan peran, fungsi dan Jabatan.
6. Kamus Kompetensi adalah kumpulan kompetensi yang meliputi nama kompetensi, definisi kompetensi, deskripsi dan level kompetensi serta Indikator Kompetensi.
7. Level Kompetensi adalah tingkat penguasaan kompetensi yang dirumuskan berupa Indikator Kompetensi pemangku jabatan, meliputi 5 (lima) level dengan kriteria sebagai berikut:
a. Level 1 Pemahaman/pengembangan (awareness/being developed), dengan kriteria:
1) Mengidentifikasi kemampuan melaksanakan tugas/pekerjaan teknis sederhana dengn proses dan aturan yang jelas, memerlukan pengawasan langsung/bantuan dari orang lain;
2) Mengindikasikan penguasaan pengetahuan dan keterampilan yang tidak memerlukan pelatihan khusus;
3) Mengindikasikan memiliki pemahaman dasar tentang prinsip-prinsip teori dan praktek, namun masih memerlukan pengawasan langsung atau bantuan pihak lain; dan 4) Mengindikasikan kemampuan bertanggung jawab atas pekerjaan sendiri.
b. Level 2 Dasar (basic), dengan kriteria:
1) Mengindikasikan kemamapuan melakukan kegiatan/tugas teknis dengan alat, prosedur, dan metode kerja yang sudah baku;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4013, '5. Kompetensi Sosial Kultural adalah pengetahuan, keterampilan, dan sikap/perilaku yang dapat diamati, diukur, dan dikembangkan terkait dengan pengalaman berinteraksi dengan masyarakat majemuk dalam hal agama, suku dan budaya, perilaku, wawasan kebangsaan, etika, nilai-nilai, moral, emosi dan prinsip, yang harus dipenuhi oleh setiap pemegang Jabatan untuk memperoleh hasil kerja sesuai dengan peran, fungsi dan Jabatan.
6. Kamus Kompetensi adalah kumpulan kompetensi yang meliputi nama kompetensi, definisi kompetensi, deskripsi dan level kompetensi serta Indikator Kompetensi.
7. Level Kompetensi adalah tingkat penguasaan kompetensi yang dirumuskan berupa Indikator Kompetensi pemangku jabatan, meliputi 5 (lima) level dengan kriteria sebagai berikut:
a. Level 1 Pemahaman/pengembangan (awareness/being developed), dengan kriteria:
1) Mengidentifikasi kemampuan melaksanakan tugas/pekerjaan teknis sederhana dengn proses dan aturan yang jelas, memerlukan pengawasan langsung/bantuan dari orang lain;
2) Mengindikasikan penguasaan pengetahuan dan keterampilan yang tidak memerlukan pelatihan khusus;
3) Mengindikasikan memiliki pemahaman dasar tentang prinsip-prinsip teori dan praktek, namun masih memerlukan pengawasan langsung atau bantuan pihak lain; dan 4) Mengindikasikan kemampuan bertanggung jawab atas pekerjaan sendiri.
b. Level 2 Dasar (basic), dengan kriteria:
1) Mengindikasikan kemamapuan melakukan kegiatan/tugas teknis dengan alat, prosedur, dan metode kerja yang sudah baku;', 'Lampiran hal. 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4014, 'perban-5-2024', 16, 'lampiran', 'Lampiran hal. 7', NULL, 7, '2) Mengindikasikan pemahaman tentang prinsip-prinsip teori dan praktek, dalam pelaksanaan tugas tanpa bantuan dan/atau pengawasan langsung;
3) Mengindikasikan penguasaan pengetahuan dan keterampilan yang memerlukan pelatihan tingkat dasar; dan 4) Mengindikasikan kemampuan untuk bertanggung jawab atas pekerjaan sendiri dan dapat diberi tanggung jawab membantu pekerjaan orang lain untuk tugas teknis ysnmg sederhana.
c. Level 3 Menengah (intermediate), dengan kriteria:
1) Mengindikasikan kemampuan melakukan tugas teknis yang lebih spesifik dengan menganalisis informasi secara terbatas dan pilihan metode untuk menyelesaikan permasalahan yang timbul dalam tugasnya 2) Mengindikasikan pemahaman tentang prinsip-prinsip teori dan praktek tanpa bantuan dan/atau pengawasan langsung, dengan kecepatan yang tepat penyelesaian pekerjaan yang cepat 3) Mengindikasikan kepercayaan diri dan kemampuan serta menunjukan kelancaran dan ketangkasan dalam praktek pelaksanaan pekerjaan teknis 4) Mengindikasikan penguasaan pengetahuan dan keterampilan yang memerlukan pelatihan tingkat menengah; dan 5) Mengindikasikan kemampuan bertanggung jawab atas pekerjaan sendiri dan dapat diberi tanggung jawab atas pekerjaan kelompok/tim.
d. Level 4 Mumpuni (advance), dengan kriteria:
1) Mengindikasikan kemampuan mengembangkan ilmu pengetahuan/iptek, konsep/teori dan praktek mampu mendapat pengakuan di tingkat instansi;
2) Mengindikasikan kemampuan menghasilkan perbaikan dan pembaharuan teknis, dan metode kerja;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4014, '2) Mengindikasikan pemahaman tentang prinsip-prinsip teori dan praktek, dalam pelaksanaan tugas tanpa bantuan dan/atau pengawasan langsung;
3) Mengindikasikan penguasaan pengetahuan dan keterampilan yang memerlukan pelatihan tingkat dasar; dan 4) Mengindikasikan kemampuan untuk bertanggung jawab atas pekerjaan sendiri dan dapat diberi tanggung jawab membantu pekerjaan orang lain untuk tugas teknis ysnmg sederhana.
c. Level 3 Menengah (intermediate), dengan kriteria:
1) Mengindikasikan kemampuan melakukan tugas teknis yang lebih spesifik dengan menganalisis informasi secara terbatas dan pilihan metode untuk menyelesaikan permasalahan yang timbul dalam tugasnya 2) Mengindikasikan pemahaman tentang prinsip-prinsip teori dan praktek tanpa bantuan dan/atau pengawasan langsung, dengan kecepatan yang tepat penyelesaian pekerjaan yang cepat 3) Mengindikasikan kepercayaan diri dan kemampuan serta menunjukan kelancaran dan ketangkasan dalam praktek pelaksanaan pekerjaan teknis 4) Mengindikasikan penguasaan pengetahuan dan keterampilan yang memerlukan pelatihan tingkat menengah; dan 5) Mengindikasikan kemampuan bertanggung jawab atas pekerjaan sendiri dan dapat diberi tanggung jawab atas pekerjaan kelompok/tim.
d. Level 4 Mumpuni (advance), dengan kriteria:
1) Mengindikasikan kemampuan mengembangkan ilmu pengetahuan/iptek, konsep/teori dan praktek mampu mendapat pengakuan di tingkat instansi;
2) Mengindikasikan kemampuan menghasilkan perbaikan dan pembaharuan teknis, dan metode kerja;', 'Lampiran hal. 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4015, 'perban-5-2024', 17, 'lampiran', 'Lampiran hal. 7', NULL, 7, '3) Mengindikasikan kemampuan beradaptasi dengan berbagai situasi, peningkatan kompleksitas dan resiko serta kemapuan memecahkan permasalahan teknis yang timbul dalam pekerjaan; dan 4) Mengindikasikan kemampuan mengembangkan dan menerapkan pendekatan mono disipliner/satu bidang keilmuan dan kemampuan melakukan uji kompetensi serta memiliki kemampuan pengajaran serta menjadi rujukan atau mentor tingkat instansi.
e. Level 5 Ahli (expert), dengan kriteria:
1) Mengindikasikan kemampuan mengembangkan ilmu pengetahuan/iptek, konsep/teori mampu mendapat pengakuan nasional dan internasional;
2) Mengindikasikan kemampuan menghasilkan karya kreatif, original dan teruji;
3) Menunjukkan inisiatif dan kemampuan beradaptasi dengan situasi masalah khusus, dan dapat memimpin orang lain dalam melakukan kegiatan teknis;
4) Mengindikasikan kemampuan mampu mengoordinasikan, memimpin dan menilai orang lain, kemampuan melakukan uji kompetensi, dan kemampuan menjadi pembimbing/mentor;
5) Mengindikasikan kemampuan mengembangkan dan menerapkan pendekatan inter, multi disipliner; dan 6) Mengindikasikan penguasaan pengetahuan dan keterampilan yang menjadi rujukan atau mentor tingkat nasional dan internasional.
8. Kompetensi Teknis Umum adalah pengetahuan, keterampilan, dan sikap/perilaku yang dapat diamati, diukur dan dikembangkan, bersifat umum berarti harus dimiliki oleh seluruh (setiap jabatan) yang menyelenggarakan suatu urusan pemerintahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4015, '3) Mengindikasikan kemampuan beradaptasi dengan berbagai situasi, peningkatan kompleksitas dan resiko serta kemapuan memecahkan permasalahan teknis yang timbul dalam pekerjaan; dan 4) Mengindikasikan kemampuan mengembangkan dan menerapkan pendekatan mono disipliner/satu bidang keilmuan dan kemampuan melakukan uji kompetensi serta memiliki kemampuan pengajaran serta menjadi rujukan atau mentor tingkat instansi.
e. Level 5 Ahli (expert), dengan kriteria:
1) Mengindikasikan kemampuan mengembangkan ilmu pengetahuan/iptek, konsep/teori mampu mendapat pengakuan nasional dan internasional;
2) Mengindikasikan kemampuan menghasilkan karya kreatif, original dan teruji;
3) Menunjukkan inisiatif dan kemampuan beradaptasi dengan situasi masalah khusus, dan dapat memimpin orang lain dalam melakukan kegiatan teknis;
4) Mengindikasikan kemampuan mampu mengoordinasikan, memimpin dan menilai orang lain, kemampuan melakukan uji kompetensi, dan kemampuan menjadi pembimbing/mentor;
5) Mengindikasikan kemampuan mengembangkan dan menerapkan pendekatan inter, multi disipliner; dan 6) Mengindikasikan penguasaan pengetahuan dan keterampilan yang menjadi rujukan atau mentor tingkat nasional dan internasional.
8. Kompetensi Teknis Umum adalah pengetahuan, keterampilan, dan sikap/perilaku yang dapat diamati, diukur dan dikembangkan, bersifat umum berarti harus dimiliki oleh seluruh (setiap jabatan) yang menyelenggarakan suatu urusan pemerintahan.', 'Lampiran hal. 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4016, 'perban-5-2024', 18, 'lampiran', 'Lampiran hal. 8', NULL, 8, '9. Kompetensi Teknis Khusus adalah pengetahuan, keterampilan, dan sikap/perilaku yang dapat diamati, diukur dan dikembangkan, hanya dimiliki oleh jabatan-jabatan tertentu yang menyelenggarakan suatu urusan pemerintahan sesuai tugas jabatan.
10. Kamus Kompetensi adalah kumpulan kompetensi yang meliputi nama kompetensi, definisi kompetensi, deskripsi dan level kompetensi serta Indikator Kompetensi.
BAB II DAFTAR KOMPETENSI A. Struktur Organisasi Badan Nasional Penanggulangan Bencana Berdasarkan Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana, telah dilakukan penataan kelembagaan yang ditetapkan melalui Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana. Penataan kelembagaan BNPB selanjutnya akan diikuti dengan penyesuaian nomenklatur program dan kegiatan. Disamping itu, akan diikuti penataan kelembagaan Unit Pelaksana Teknis BNPB di daerah serta penguatan kapasitas sumber daya manusia terutama terkait dengan pengembangan jabatan fungsional tertentu di BNPB.
Struktur organisasi BNPB yang merupakan bagian utama dari Kerangka Kelembagaan BNPB dapat dilihat pada Gambar berikut.
Gambar 2.1. Struktur Badan Nasional Penanggulangan Bencana Secara kelembagaan, BNPB merupakan Lembaga Pemerintah non Kementerian yang terdiri dari: (1) Kepala; (2) Unsur pengarah; dan (3) Unsur pelaksana. Susunan organisasi unsur pelaksana terdiri atas:
1. Sekretariat Utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4016, '9. Kompetensi Teknis Khusus adalah pengetahuan, keterampilan, dan sikap/perilaku yang dapat diamati, diukur dan dikembangkan, hanya dimiliki oleh jabatan-jabatan tertentu yang menyelenggarakan suatu urusan pemerintahan sesuai tugas jabatan.
10. Kamus Kompetensi adalah kumpulan kompetensi yang meliputi nama kompetensi, definisi kompetensi, deskripsi dan level kompetensi serta Indikator Kompetensi.
BAB II DAFTAR KOMPETENSI A. Struktur Organisasi Badan Nasional Penanggulangan Bencana Berdasarkan Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana, telah dilakukan penataan kelembagaan yang ditetapkan melalui Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana. Penataan kelembagaan BNPB selanjutnya akan diikuti dengan penyesuaian nomenklatur program dan kegiatan. Disamping itu, akan diikuti penataan kelembagaan Unit Pelaksana Teknis BNPB di daerah serta penguatan kapasitas sumber daya manusia terutama terkait dengan pengembangan jabatan fungsional tertentu di BNPB.
Struktur organisasi BNPB yang merupakan bagian utama dari Kerangka Kelembagaan BNPB dapat dilihat pada Gambar berikut.
Gambar 2.1. Struktur Badan Nasional Penanggulangan Bencana Secara kelembagaan, BNPB merupakan Lembaga Pemerintah non Kementerian yang terdiri dari: (1) Kepala; (2) Unsur pengarah; dan (3) Unsur pelaksana. Susunan organisasi unsur pelaksana terdiri atas:
1. Sekretariat Utama.', 'Lampiran hal. 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4017, 'perban-5-2024', 19, 'lampiran', 'Lampiran hal. 9', NULL, 9, '2. Deputi Bidang Sistem dan Strategi.
3. Deputi Bidang Pencegahan.
4. Deputi Bidang Penanganan Darurat.
5. Deputi Bidang Rehabilitasi dan Rekonstruksi.
6. Deputi Bidang Logistik dan Peralatan.
7. Inspektorat Utama.
Mengacu Peraturan Presiden Nomor 1 Tahun 2019 Pasal 15 disebutkan bahwa unsur pelaksana mempunyai tugas melaksanakan penanggulangan bencana secara terintegrasi yang meliputi prabencana, saat keadaan darurat bencana, dan pascabencana. Adapun tugas masing-masing unsur pelaksana adalah:
1. Sekretariat Utama Sekretariat Utama mempunyai tugas pembinaan dan pemberian dukungan administrasi kepada seluruh unsur organisasi di lingkungan BNPB.
Sekretariat Utama terdiri dari:
a. Biro Perencanaan;
b. Biro Keuangan;
c. Biro Hukum, Organisasi dan Kerja Sama; dan
d. Biro Sumber Daya Manusia dan Umum.
2. Deputi Bidang Sistem dan Strategi Deputi Bidang Sistem dan Strategi mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan bidang sistem dan strategi penanggulangan bencana.
Deputi Bidang Sistem dan Strategi terdiri dari:
a. Direktorat Pemetaan dan Evaluasi Risiko Bencana;
b. Direktorat Pengembangan Strategi Penanggulangan Bencana; dan
c. Direktorat Sistem Penanggulangan Bencana.
3. Deputi Bidang Pencegahan Deputi Bidang Pencegahan mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan bidang pencegahan.
Deputi Bidang Pencegahan terdiri dari:
a. Direktorat Mitigasi Bencana;
b. Direktorat Kesiapsiagaan; dan
c. Direktorat Peringatan Dini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4017, '2. Deputi Bidang Sistem dan Strategi.
3. Deputi Bidang Pencegahan.
4. Deputi Bidang Penanganan Darurat.
5. Deputi Bidang Rehabilitasi dan Rekonstruksi.
6. Deputi Bidang Logistik dan Peralatan.
7. Inspektorat Utama.
Mengacu Peraturan Presiden Nomor 1 Tahun 2019 Pasal 15 disebutkan bahwa unsur pelaksana mempunyai tugas melaksanakan penanggulangan bencana secara terintegrasi yang meliputi prabencana, saat keadaan darurat bencana, dan pascabencana. Adapun tugas masing-masing unsur pelaksana adalah:
1. Sekretariat Utama Sekretariat Utama mempunyai tugas pembinaan dan pemberian dukungan administrasi kepada seluruh unsur organisasi di lingkungan BNPB.
Sekretariat Utama terdiri dari:
a. Biro Perencanaan;
b. Biro Keuangan;
c. Biro Hukum, Organisasi dan Kerja Sama; dan
d. Biro Sumber Daya Manusia dan Umum.
2. Deputi Bidang Sistem dan Strategi Deputi Bidang Sistem dan Strategi mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan bidang sistem dan strategi penanggulangan bencana.
Deputi Bidang Sistem dan Strategi terdiri dari:
a. Direktorat Pemetaan dan Evaluasi Risiko Bencana;
b. Direktorat Pengembangan Strategi Penanggulangan Bencana; dan
c. Direktorat Sistem Penanggulangan Bencana.
3. Deputi Bidang Pencegahan Deputi Bidang Pencegahan mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan bidang pencegahan.
Deputi Bidang Pencegahan terdiri dari:
a. Direktorat Mitigasi Bencana;
b. Direktorat Kesiapsiagaan; dan
c. Direktorat Peringatan Dini.', 'Lampiran hal. 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4018, 'perban-5-2024', 20, 'lampiran', 'Lampiran hal. 10', NULL, 10, '4. Deputi Bidang Penanganan Darurat Deputi Bidang Penanganan Darurat mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan bidang penanganan keadaan darurat, meliputi penyelenggaraan siaga darurat, tanggap darurat, dan transisi darurat ke pemulihan.
Deputi Bidang Penanganan Darurat terdiri dari:
a. Direktorat Dukungan Sumber Daya Darurat;
b. Direktorat Dukungan Infrastruktur Darurat; dan
c. Direktorat Fasilitasi Penanganan Korban dan Pengungsi.
5. Deputi Bidang Rehabilitasi dan Rekonstruksi Deputi Bidang Rehabilitasi dan Rekonstruksi mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan bidang rehabilitasi dan rekonstruksi.
Deputi Bidang Rehabilitasi dan Rekonstruksi terdiri dari:
a. Direktorat Perencanaan Rehabilitasi dan Rekonstruksi;
b. Direktorat Pemulihan dan Peningkatan Fisik; dan
c. Direktorat Pemulihan dan Peningkatan Sosial, Ekonomi, dan Sumber Daya Alam.
6. Deputi Bidang Logistik dan Peralatan Deputi Bidang Logistik dan Peralatan mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan bidang logistik dan peralatan penanggulangan bencana.
Deputi Bidang Logistik dan Peralatan terdiri dari:
a. Direktorat Pengelolaan Logistik dan Peralatan; dan
b. Direktorat Optimasi Jaringan Logistik dan Peralatan.
7. Inspektorat Utama Inspektorat Utama mempunyai tugas menyelenggarakan tugas pengawasan internal di lingkungan BNPB.
Inspektorat Utama terdiri dari:
a. Inspektorat I;
b. Inspektorat II; dan
c. Inspektorat III
8. Pusat-Pusat');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4018, '4. Deputi Bidang Penanganan Darurat Deputi Bidang Penanganan Darurat mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan bidang penanganan keadaan darurat, meliputi penyelenggaraan siaga darurat, tanggap darurat, dan transisi darurat ke pemulihan.
Deputi Bidang Penanganan Darurat terdiri dari:
a. Direktorat Dukungan Sumber Daya Darurat;
b. Direktorat Dukungan Infrastruktur Darurat; dan
c. Direktorat Fasilitasi Penanganan Korban dan Pengungsi.
5. Deputi Bidang Rehabilitasi dan Rekonstruksi Deputi Bidang Rehabilitasi dan Rekonstruksi mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan bidang rehabilitasi dan rekonstruksi.
Deputi Bidang Rehabilitasi dan Rekonstruksi terdiri dari:
a. Direktorat Perencanaan Rehabilitasi dan Rekonstruksi;
b. Direktorat Pemulihan dan Peningkatan Fisik; dan
c. Direktorat Pemulihan dan Peningkatan Sosial, Ekonomi, dan Sumber Daya Alam.
6. Deputi Bidang Logistik dan Peralatan Deputi Bidang Logistik dan Peralatan mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan bidang logistik dan peralatan penanggulangan bencana.
Deputi Bidang Logistik dan Peralatan terdiri dari:
a. Direktorat Pengelolaan Logistik dan Peralatan; dan
b. Direktorat Optimasi Jaringan Logistik dan Peralatan.
7. Inspektorat Utama Inspektorat Utama mempunyai tugas menyelenggarakan tugas pengawasan internal di lingkungan BNPB.
Inspektorat Utama terdiri dari:
a. Inspektorat I;
b. Inspektorat II; dan
c. Inspektorat III
8. Pusat-Pusat', 'Lampiran hal. 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
