INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4029, 'perban-5-2024', 31, 'lampiran', 'Lampiran hal. 19', NULL, 19, '2 Mampu menerapkan 2.1 Mampu melaksanakan pengolahan data dan melaksanakan yang dibutuhkan untuk penyusunan berbagai konsep, teori, kebijakan bidang penanggulangan teknik, metode, bencana. strategi, dan tata cara 2.2 Mampu melakukan analisis terhadap penyusunan kebijakan data dan menyajikan analisis tersebut bidang untuk menyusun konsep kebijakan penanggulangan bidang penanggulangan bencana. bencana sesuai 2.3 Mampu menjelaskan secara lengkap, pedoman kerja atau rinci dan jelas penyusunan kebijakan petunjuk teknis. bidang penanggulangan bencana di tingkat nasional.
3 Mampu melaksanakan 3.1 Mampu merancang atau membuat penyusunan kebijakan sistematika draft kebijakan bidang bidang penanggulangan bencana dan penangggulangan menentukan substansi yang akan diatur. bencana. 3.2 Mampu mengoordinasikan dan mensosialisasikan pelaksanaan penyusunan kebijakan bidang penanggulangan bencana.
3.3 Mampu memecahkan masalah teknis operasional yang timbul dan mengambil keputusan dalam pelaksanaan penyusunan kebijakan bidang penanggulangan bencana.');
