INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4030, 'perban-5-2024', 32, 'lampiran', 'Lampiran hal. 20', NULL, 20, '4 Mampu mengevaluasi 4.1 Mampu melakukan evaluasi terhadap dan menyusun teknik/metode/sistem cara kerja, perangkat norma melakukan pengembangan atau standar prosedur perbaikan cara kerja penyusunan instrumen dalam kebijakan bidang penanggulangan melakukan bencana yang lebih efektif/efisien. penyusunan kebijakan 4.2 Mampu menyusun pedoman, petunjuk bidang teknis, cara kerja yang dijadikan norma, penanggulangan standar, prosedur, instrumen bencana. pelaksanaan penyusunan kebijakan bidang penanggulangan bencana.
4.3 Mampu meyakinkan dan memperoleh dukungan dari stakeholder terhadap pelaksanaan penyusunan kebijakan, memberikan bimbingan dan fasilitasi kepada instansi lain atau stakeholder terkait penyusunan kebijakan bidang penanggulangan bencana.
5 Mampu 5.1 Mengidentifikasi, menganalisis, teori, mengembangkan konsep, kebijakan serta pelaksanaan konsep, teori, dan penyusunan kebijakan bidang kebijakan penanggulangan bencana, mencari penanggulangan kelebihan dan kekurangan dan bencana, dan menjadi memberikan rekomendasi perbaikan. sumber rujukan untuk 5.2 Mengembangkan teori, konsep dan implementasi serta kebijakan meyakinkan stakeholder dan pemecahan masalah shareholder terkait untuk menerima penyusunan kebijakan konsep, teori dan kebijakan bidang bidang penanggulangan bencana yang penanggulangan dikembangkan. bencana. 5.3 Mampu menjadi sumber rujukan utama (nasional) dalam implementasi kebijakan dan pemecahan masalah dalam penyusunan kebijakan bidang penanggulangan bencana.');
