INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4031, 'perban-5-2024', 33, 'lampiran', 'Lampiran hal. 20', NULL, 20, '2. Advokasi Kebijakan Bidang Penanggulangan Bencana Nama Kompetensi : Advokasi Kebijakan Bidang Penanggulangan Bencana Kode Kompetensi : PB.02 Definisi : Kemampuan berupa pengetahuan dan keterampilan untuk melakukan usaha yang terencana dan sistematis untuk mempengaruhi dan mengupayakan terjadinya perubahan secara bertahap dalam menerapkan (mengadopsi dan mengimplementasi) kebijakan bidang penanggulangan bencana.
Kemampuan tersebut termasuk mengkomunikasikan konsep, strategi, proses, data, program serta kebijakan kepada stakeholder melalui metode-metode serta strategi yang terencana dengan tujuan agar stakeholder dapat memahami serta menerapkan kebijakan tentang penanggulangan bencana.
1 Mampu memahami 1.1 Mampu menjelaskan konsep dasar, berbagai konsep teknik metode, peraturan dan dasar, teknik, metode, mekanisme, tata cara prosedur advokasi peraturan dan kebijakan penanggulangan bencana. mekanisme, tata cara, 1.2 Mampu menjelaskan langkah langkah prosedur advokasi tahapan pelaksanaan advokasi kebijakan kebijakan bidang penanggulangan bencana. penanggulangan 1.3 Mampu mengidentifikasi berbagai bencana. sumber informasi dan mengumpulkan data advokasi kebijakan penanggulangan bencana.');
