INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4034, 'perban-5-2024', 36, 'lampiran', 'Lampiran hal. 22', NULL, 22, '3. Manajemen Bencana Nama Kompetensi : Manajemen Bencana Kode Kompetensi : PB.03 Definisi : Kemampuan mengumpulkan, mengidentifikasi, mengolah, menganalisis, dan merumuskan pengelolaan sumber daya penanggulangan bencana, memonitor dan evaluasi, mengidentifikasi umpan balik pelaksanaan penanggulangan bencana, serta mengembangkan teori, konsep, teknik metode penanggulangan bencana yang meliputi sistem dan strategi, sumber daya logistik dan peralatan, anggaran, peraturan, NSPK, sumber daya manusia, secara terpadu.
1 Mampu memahami 1.1 Mampu menjelaskan konsep dasar, berbagai konsep dasar, teori, metode, peraturan dan teknik, metode, tata cara, mekanisme, tata cara prosedur kebijakan, dan peraturan manajemen bencana. pengelolaan 1.2 Mampu menjelaskan langkah-penanggulangan bencana langkah tahapan pelaksanaan secara dinamis, manajemen bencana. berkelanjutan, dan 1.3 Mampu mengidentifikasi berbagai terpadu melalui sumber informasi dan pencegahan sebelum mengumpulkan data pengelolaan terjadinya bencana, penanggulangan bencana secara penanganan kedaruratan cermat, akurat, dan dapat selama terjadinya dipertanggungjawabkan. bencana, dan rehabilitasi dan rekonstruksi pasca bencana.');
