INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4035, 'perban-5-2024', 37, 'lampiran', 'Lampiran hal. 23', NULL, 23, '2 Mampu menerapkan dan 2.1 Mampu melaksanakan identifikasi, melaksanakan berbagai pengumpulan data dan bahan terkait konsep, teori, teknik, manajemen bencana. metode, strategi, dan tata 2.2 Mampu melaksanakan menyajikan cara manajemen dan memanfaatkan data tentang penanggulangan bencana manajemen bencana. secara dinamis, 2.3 Mampu menjelaskan secara lengkap, berkelanjutan, dan rinci dan jelas perihal manajemen terpadu melalui bencana kepada masyarakat dan pencegahan sebelum stakeholder. terjadinya bencana, penanganan kedaruratan selama terjadinya bencana, dan rehabilitasi dan rekonstruksi pasca bencana sesuai pedoman kerja/petunjuk teknis.
3 Mampu menyelenggarakan 3.1 Mampu merencanakan manajemen bimbingan teknis bencana secara dinamis, pelaksanaan manajemen berkelanjutan, dan terpadu melalui bencana. pencegahan sebelum terjadinya bencana, penanganan kedaruratan selama terjadinya bencana, dan rehabilitasi dan rekonstruksi pasca bencana.
