INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4036, 'perban-5-2024', 38, 'lampiran', 'Lampiran hal. 23', NULL, 23, '4 Mampu mengevaluasi dan 4.1 Mampu mengevaluasi dan menyusun norma, memberikan rekomendasi perbaikan standar, prosedur, dan penerapan berbagai konsep dan kriteria pengelolaan metode manajemen bencana. penanggulangan bencana 4.2 Mampu menyusun pedoman atau secara dinamis, petunjuk teknis pelaksanaan strategi berkelanjutan, dan manajemen bencana. terpadu melalui 4.3 Mampu mendeseminasikan konsep, pencegahan sebelum metode, strategi, dan kebijakan terjadinya bencana, kepada pemangku kepentingan penanganan kedaruratan manajemen bencana. selama terjadinya bencana, dan rehabilitasi dan rekonstruksi pasca bencana.
5 Mampu mengembangkan 5.1 Mampu mengembangkan konsep, konsep, teori, dan teori, metode dan kebijakan kebijakan dan menjadi manajemen bencana, meyakinkan sumber rujukan untuk stakeholder terkait untuk menerima implementasi serta konsep, teori dan kebijakan yang pemecahan masalah dikembangkan. pengelolaan penanggulangan bencana secara dinamis, 5.2 Mampu mengembangkan strategi, berkelanjutan, dan teknik, dan instrumen manajemen terpadu melalui bencana. pencegahan sebelum 5.3 Mampu menjadi sumber rujukan terjadinya bencana, utama (nasional) dalam implementasi penanganan kedaruratan keijakan dan pemecahan masalah selama terjadinya dalam manajemen bencana. bencana, dan rehabilitasi dan rekonstruksi pasca bencana.');
