INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4040, 'perban-5-2024', 42, 'lampiran', 'Lampiran hal. 25', NULL, 25, '5 Mengembangkan 5.1 Mengidentifikasi, menganalisis, teori, konsep, teori, konsep, kebijakan serta pelaksanaan kebijakan Bidang penyusunan kebijakan bidang sistem dan Sistem dan Strategi strategi penanggulangan bencana, Penanggulangan mencari kelebihan dan kekurangan dan Bencana dan menjadi memberikan rekomendasi perbaikan. sumber rujukan 5.2 Mengembangkan teori, konsep dan untuk implementasi kebijakan meyakinkan stakeholder dan serta pemecahan shareholder terkait untuk menerima masalah penyusunan konsep, teori dan kebijakan bidang kebijakan di bidang sistem dan strategi penanggulangan sistem dan strategi bencana yang dikembangkan. penanggulangan 5.3 Menjadi sumber rujukan utama bencana. (nasional) dalam implementasi kebijakan dan pemecahan masalah dalam penyusunan kebijakan bidang sistem dan strategi penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4040, '5 Mengembangkan 5.1 Mengidentifikasi, menganalisis, teori, konsep, teori, konsep, kebijakan serta pelaksanaan kebijakan Bidang penyusunan kebijakan bidang sistem dan Sistem dan Strategi strategi penanggulangan bencana, Penanggulangan mencari kelebihan dan kekurangan dan Bencana dan menjadi memberikan rekomendasi perbaikan. sumber rujukan 5.2 Mengembangkan teori, konsep dan untuk implementasi kebijakan meyakinkan stakeholder dan serta pemecahan shareholder terkait untuk menerima masalah penyusunan konsep, teori dan kebijakan bidang kebijakan di bidang sistem dan strategi penanggulangan sistem dan strategi bencana yang dikembangkan. penanggulangan 5.3 Menjadi sumber rujukan utama bencana. (nasional) dalam implementasi kebijakan dan pemecahan masalah dalam penyusunan kebijakan bidang sistem dan strategi penanggulangan bencana.', 'Lampiran hal. 25', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4041, 'perban-5-2024', 43, 'lampiran', 'Lampiran hal. 26', NULL, 26, '5. Advokasi Kebijakan Bidang Sistem dan Strategi Penanggulangan Bencana Nama Kompetensi : Advokasi Kebijakan Bidang Sistem dan Strategi Penanggulangan Bencana Kode Kompetensi : PB.05 Definisi : Kemampuan berupa pengetahuan dan keterampilan untuk melakukan usaha yang terencana dan sistematis untuk mempengaruhi dan mengupayakan terjadinya perubahan secara bertahap dalam menerapkan (mengadopsi dan mengimplementasi) kebijakan bidang sistem dan strategi penanggulangan bencana. Kemampuan tersebut termasuk mengkomunikasikan konsep, strategi, proses, data, program serta kebijakan kepada stakeholder melalui metode-metode serta strategi yang terencana dengan tujuan agar stakeholder dapat memahami serta menerapkan kebijakan tentang sistem dan strategi penanggulangan bencana.
1 Mampu memahami 1.1 Mampu menjelaskan konsep dasar, berbagai konsep teknik metode, peraturan dan dasar, teknik, metode, mekanisme, tata cara prosedur advokasi tata cara, kebijakan, kebijakan bidang sistem dan strategi dan peraturan penanggulangan bencana. advokasi kebijakan 1.2 Mampu menjelaskan langkah langkah bidang sistem dan tahapan pelaksanaan advokasi kebijakan strategi bidang sistem dan strategi penanggulangan penanggulangan bencana. bencana. 1.3 Mampu mengidentifikasi berbagai sumber informasi dan mengumpulkan data advokasi kebijakan bidang sistem dan strategi penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4041, '5. Advokasi Kebijakan Bidang Sistem dan Strategi Penanggulangan Bencana Nama Kompetensi : Advokasi Kebijakan Bidang Sistem dan Strategi Penanggulangan Bencana Kode Kompetensi : PB.05 Definisi : Kemampuan berupa pengetahuan dan keterampilan untuk melakukan usaha yang terencana dan sistematis untuk mempengaruhi dan mengupayakan terjadinya perubahan secara bertahap dalam menerapkan (mengadopsi dan mengimplementasi) kebijakan bidang sistem dan strategi penanggulangan bencana. Kemampuan tersebut termasuk mengkomunikasikan konsep, strategi, proses, data, program serta kebijakan kepada stakeholder melalui metode-metode serta strategi yang terencana dengan tujuan agar stakeholder dapat memahami serta menerapkan kebijakan tentang sistem dan strategi penanggulangan bencana.
1 Mampu memahami 1.1 Mampu menjelaskan konsep dasar, berbagai konsep teknik metode, peraturan dan dasar, teknik, metode, mekanisme, tata cara prosedur advokasi tata cara, kebijakan, kebijakan bidang sistem dan strategi dan peraturan penanggulangan bencana. advokasi kebijakan 1.2 Mampu menjelaskan langkah langkah bidang sistem dan tahapan pelaksanaan advokasi kebijakan strategi bidang sistem dan strategi penanggulangan penanggulangan bencana. bencana. 1.3 Mampu mengidentifikasi berbagai sumber informasi dan mengumpulkan data advokasi kebijakan bidang sistem dan strategi penanggulangan bencana.', 'Lampiran hal. 26', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4042, 'perban-5-2024', 44, 'lampiran', 'Lampiran hal. 26', NULL, 26, '2 Mampu menerapkan 2.1 Mampu melaksanakan konsep, teori, dan melaksanakan metode dan kebijakan advokasi kebijakan berbagai konsep, bidang sistem dan strategi teori, teknik, metode, penanggulangan bencana. strategi, dan tata cara 2.2 Mampu melaksanakan menyajikan dan advokasi kebijakan memanfaatkan data tentang advokasi bidang sistem dan kebijakan bidang sistem dan strategi strategi penanggulangan bencana. penanggulangan 2.3 Mampu menjelaskan secara lengkap, rinci bencana. dan jelas perihal advokasi kebijakan bidang sistem dan strategi penanggulangan bencana kepada masyarakat dan stakeholder.
3 Mampu 3.1 Mampu menyusun instrumen dan bahan menyelenggarakan pelaksanaan advokasi kebijakan bidang membimbing sistem dan strategi penanggulangan pelaksanaan advokasi bencana, melalui persuasi, sosialisasi, kebijakan bidang bimbingan teknis, pendampingan, sistem dan strategi monitoring evaluasi advokasi kebijakan penanggulangan publik. bencana. 3.2 Mampu mengembangkan serta menjalankan strategi atau intervensi melalui persuasi, sosialisasi, bimbingan teknis, pendampingan dalam mengatasi hambatan sistemik dan resistensi stakeholder dalam menerapkan advokasi kebijakan bidang sistem dan strategi penanggulangan bencana.
3.3 Mampu memecahkan masalah teknis operasional yang timbul dan mengambil keputusan dalam pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4042, '2 Mampu menerapkan 2.1 Mampu melaksanakan konsep, teori, dan melaksanakan metode dan kebijakan advokasi kebijakan berbagai konsep, bidang sistem dan strategi teori, teknik, metode, penanggulangan bencana. strategi, dan tata cara 2.2 Mampu melaksanakan menyajikan dan advokasi kebijakan memanfaatkan data tentang advokasi bidang sistem dan kebijakan bidang sistem dan strategi strategi penanggulangan bencana. penanggulangan 2.3 Mampu menjelaskan secara lengkap, rinci bencana. dan jelas perihal advokasi kebijakan bidang sistem dan strategi penanggulangan bencana kepada masyarakat dan stakeholder.
3 Mampu 3.1 Mampu menyusun instrumen dan bahan menyelenggarakan pelaksanaan advokasi kebijakan bidang membimbing sistem dan strategi penanggulangan pelaksanaan advokasi bencana, melalui persuasi, sosialisasi, kebijakan bidang bimbingan teknis, pendampingan, sistem dan strategi monitoring evaluasi advokasi kebijakan penanggulangan publik. bencana. 3.2 Mampu mengembangkan serta menjalankan strategi atau intervensi melalui persuasi, sosialisasi, bimbingan teknis, pendampingan dalam mengatasi hambatan sistemik dan resistensi stakeholder dalam menerapkan advokasi kebijakan bidang sistem dan strategi penanggulangan bencana.
3.3 Mampu memecahkan masalah teknis operasional yang timbul dan mengambil keputusan dalam pelaksanaan.', 'Lampiran hal. 26', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4043, 'perban-5-2024', 45, 'lampiran', 'Lampiran hal. 27', NULL, 27, '4 Mampu mengevaluasi 4.1 Mampu melakukan evaluasi terhadap dan mengembangkan teknik/metode/sistem cara kerja, teknik advokasi mencari kelebihan dan kekurangan, kebijakan bidang melakukan pengembangan atau sistem dan strategi perbaikan cara kerja advokasi kebijakan penanggulangan bidang sistem dan strategi bencana. penanggulangan bencana.
4.2 Mampu menyusun pedoman, petunjuk teknis, cara kerja yang dijadikan norma, standar, prosedur, instrumen pelaksanaan advokasi kebijakan bidang sistem dan strategi penanggulangan bencana.
4.3 Mampu meyakinkan dan memperoleh dukungan dari stakeholder terhadap pelaksanaan advokasi kebijakan, memberikan bimbingan dan fasilitasi kepada instansi lain atau stakeholder terkait advokasi kebijakan.
5 Mampu 5.1 Mampu mengembangkan konsep, teori, mengembangkan metode dan kebijakan advokasi kebijakan konsep, teori, dan bidang sistem dan strategi kebijakan advokasi penanggulangan bencana. kebijakan bidang 5.2 Mampu mengembangkan strategi, teknik, sistem dan strategi dan instrumen advokasi kebijakan bidang penanggulangan sistem dan strategi penanggulangan bencana yang sinergis bencana yang dapat memberikan dampak dan terintegrasi yang positif di tingkat nasional. berdampak nasional. 5.3 Mampu menjadi mentor dan rujukan dalam pemecahan masalah advokasi kebijakan bidang sistem dan strategi penanggulangan bencana di tingkat nasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4043, '4 Mampu mengevaluasi 4.1 Mampu melakukan evaluasi terhadap dan mengembangkan teknik/metode/sistem cara kerja, teknik advokasi mencari kelebihan dan kekurangan, kebijakan bidang melakukan pengembangan atau sistem dan strategi perbaikan cara kerja advokasi kebijakan penanggulangan bidang sistem dan strategi bencana. penanggulangan bencana.
4.2 Mampu menyusun pedoman, petunjuk teknis, cara kerja yang dijadikan norma, standar, prosedur, instrumen pelaksanaan advokasi kebijakan bidang sistem dan strategi penanggulangan bencana.
4.3 Mampu meyakinkan dan memperoleh dukungan dari stakeholder terhadap pelaksanaan advokasi kebijakan, memberikan bimbingan dan fasilitasi kepada instansi lain atau stakeholder terkait advokasi kebijakan.
5 Mampu 5.1 Mampu mengembangkan konsep, teori, mengembangkan metode dan kebijakan advokasi kebijakan konsep, teori, dan bidang sistem dan strategi kebijakan advokasi penanggulangan bencana. kebijakan bidang 5.2 Mampu mengembangkan strategi, teknik, sistem dan strategi dan instrumen advokasi kebijakan bidang penanggulangan sistem dan strategi penanggulangan bencana yang sinergis bencana yang dapat memberikan dampak dan terintegrasi yang positif di tingkat nasional. berdampak nasional. 5.3 Mampu menjadi mentor dan rujukan dalam pemecahan masalah advokasi kebijakan bidang sistem dan strategi penanggulangan bencana di tingkat nasional.', 'Lampiran hal. 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4044, 'perban-5-2024', 46, 'lampiran', 'Lampiran hal. 27', NULL, 27, '6. Pengelolaan Sistem dan Strategi Penanggulangan Bencana Nama Kompetensi : Pengelolaan Sistem dan Strategi Penanggulangan Bencana Kode Kompetensi : PB.06 Definisi : Kemampuan mengumpulkan, mengidentifikasi, mengolah menganalisis, merumuskan, memonitor dan mengevaluasi, mengidentifikasi umpan balik penerapan sistem dan strategi penanggulangan bencana serta mengembangkan teori, konsep, teknik metode pengelolaan sistem dan strategi penanggulangan bencana melalui pengurangan risiko dan tata kelola penanggulangan bencana.
1 Mampu memahami 1.1 Mampu menjelaskan konsep dasar, berbagai konsep teknik, metode, dan mekanisme tata cara dasar, teknik, metode, pengelolaan sistem dan strategi tata cara, kebijakan, penanggulangan bencana. dan peraturan 1.2 Mampu menjelaskan langkah-langkah pengelolaan sistem tahapan pelaksanaan pengelolaan sistem dan strategi dan strategi penanggulangan bencana. penanggulangan 1.3 Mampu menyiapkan data-data yang bencana. dibutuhkan untuk pengelolaan sistem dan strategi penanggulangan bencana.
2 Mampu menerapkan 2.1 Mampu melaksanakan pengolahan data dan melaksanakan yang dibutuhkan untuk pengelolaan berbagai konsep, teori, sistem dan strategi penanggulangan teknik, metode, bencana. strategi, dan tata cara 2.2 Mampu melakukan analisis terhadap pengelolaan sistem data dan menyajikan analisis tersebut dan strategi untuk menyusun konsep pengelolaan penanggulangan sistem dan strategi penanggulangan bencana. bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4044, '6. Pengelolaan Sistem dan Strategi Penanggulangan Bencana Nama Kompetensi : Pengelolaan Sistem dan Strategi Penanggulangan Bencana Kode Kompetensi : PB.06 Definisi : Kemampuan mengumpulkan, mengidentifikasi, mengolah menganalisis, merumuskan, memonitor dan mengevaluasi, mengidentifikasi umpan balik penerapan sistem dan strategi penanggulangan bencana serta mengembangkan teori, konsep, teknik metode pengelolaan sistem dan strategi penanggulangan bencana melalui pengurangan risiko dan tata kelola penanggulangan bencana.
1 Mampu memahami 1.1 Mampu menjelaskan konsep dasar, berbagai konsep teknik, metode, dan mekanisme tata cara dasar, teknik, metode, pengelolaan sistem dan strategi tata cara, kebijakan, penanggulangan bencana. dan peraturan 1.2 Mampu menjelaskan langkah-langkah pengelolaan sistem tahapan pelaksanaan pengelolaan sistem dan strategi dan strategi penanggulangan bencana. penanggulangan 1.3 Mampu menyiapkan data-data yang bencana. dibutuhkan untuk pengelolaan sistem dan strategi penanggulangan bencana.
2 Mampu menerapkan 2.1 Mampu melaksanakan pengolahan data dan melaksanakan yang dibutuhkan untuk pengelolaan berbagai konsep, teori, sistem dan strategi penanggulangan teknik, metode, bencana. strategi, dan tata cara 2.2 Mampu melakukan analisis terhadap pengelolaan sistem data dan menyajikan analisis tersebut dan strategi untuk menyusun konsep pengelolaan penanggulangan sistem dan strategi penanggulangan bencana. bencana.', 'Lampiran hal. 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4045, 'perban-5-2024', 47, 'lampiran', 'Lampiran hal. 28', NULL, 28, '2.3 Mampu menjelaskan secara lengkap, rinci dan jelas pengelolaan sistem dan strategi penanggulangan bencana.
3 Mampu 3.1 Mampu merencanakan pengelolaan merencanakan, sistem dan strategi penanggulangan melaksanakan, bencana, melalui pengelolaan rancang memantau, bangun sistem dan pengembangan mengendalikan, standar penanggulangan bencana memantau, dan terpadu, baik dari aspek legislasi, menyusun laporan kelembagaan, maupun pendanaannya. pengelolaan sistem 3.2 Mampu mengoordinasikan pelaksanaan dan strategi pengelolaan sistem dan strategi penanggulangan penanggulangan bencana. bencana sesuai 3.3 Mampu memecahkan masalah teknis pedoman atau operasional yang timbul dan mengambil petunjuk teknis. keputusan dalam pelaksanaan pengelolaan sistem dan strategi penanggulangan bencana.
4 Mampu menyusun 4.1 Mampu mengevaluasi dan memberikan norma, standar, rekomendasi perbaikan penerapan prosedur, dan kriteria berbagai konsep dan metode pengelolaan pengelolaan sistem sistem dan strategi penanggulangan dan strategi bencana. penanggulangan 4.2 Mampu menyusun pedoman atau bencana. petunjuk teknis pelaksanaan strategi pengelolaan sistem dan strategi penanggulangan bencana.
4.3 Mampu mendeseminasikan konsep, metode, strategi, dan kebijakan kepada pemangku kepentingan pengelolaan sistem dan strategi penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4045, '2.3 Mampu menjelaskan secara lengkap, rinci dan jelas pengelolaan sistem dan strategi penanggulangan bencana.
3 Mampu 3.1 Mampu merencanakan pengelolaan merencanakan, sistem dan strategi penanggulangan melaksanakan, bencana, melalui pengelolaan rancang memantau, bangun sistem dan pengembangan mengendalikan, standar penanggulangan bencana memantau, dan terpadu, baik dari aspek legislasi, menyusun laporan kelembagaan, maupun pendanaannya. pengelolaan sistem 3.2 Mampu mengoordinasikan pelaksanaan dan strategi pengelolaan sistem dan strategi penanggulangan penanggulangan bencana. bencana sesuai 3.3 Mampu memecahkan masalah teknis pedoman atau operasional yang timbul dan mengambil petunjuk teknis. keputusan dalam pelaksanaan pengelolaan sistem dan strategi penanggulangan bencana.
4 Mampu menyusun 4.1 Mampu mengevaluasi dan memberikan norma, standar, rekomendasi perbaikan penerapan prosedur, dan kriteria berbagai konsep dan metode pengelolaan pengelolaan sistem sistem dan strategi penanggulangan dan strategi bencana. penanggulangan 4.2 Mampu menyusun pedoman atau bencana. petunjuk teknis pelaksanaan strategi pengelolaan sistem dan strategi penanggulangan bencana.
4.3 Mampu mendeseminasikan konsep, metode, strategi, dan kebijakan kepada pemangku kepentingan pengelolaan sistem dan strategi penanggulangan bencana.', 'Lampiran hal. 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4046, 'perban-5-2024', 48, 'lampiran', 'Lampiran hal. 29', NULL, 29, '5 Mampu 5.1 Mampu mengembangkan konsep, teori, mengembangkan metode dan kebijakan pengelolaan sistem konsep, teori, dan dan strategi penanggulangan bencana. kebijakan pengelolaan 5.2 Mampu mengembangkan strategi, teknik, sistem dan strategi dan instrumen pengelolaan sistem dan penanggulangan strategi penanggulangan bencana. bencana. 5.3 Mampu menjadi rujukan pengelolaan sistem dan strategi penanggulangan bencana di tingkat nasional.
7. Penyusunan Rencana dan Dukungan Teknis Pemetaan dan Evaluasi Risiko Bencana Nama Kompetensi : Penyusunan Rencana dan Dukungan Teknis Pemetaan dan Evaluasi Risiko Bencana Kode Kompetensi : PB.07 Definisi : Kemampuan mengidentifikasi, mengumpulkan, mengolah, menganalisis, dan merumuskan, memonitor dan mengevaluasi, mengidentifikasi umpan balik penerapan rencana dan dukungan teknis pemetaan dan evaluasi risiko bencana, serta mengembangkan teori, konsep, teknik metode penyusunan rencana dan dukungan teknis pemetaan dan evaluasi risiko bencana.
1 Mampu memahami 1.1 Mampu memahami konsep dasar konsep dasar mengenai penyusunan rencana dan penyusunan rencana dukungan teknis pemetaan dan evaluasi kerja dan anggaran. risiko bencana.
1.2 Mampu memahami mengenai peraturan, prosedur dan mekanisme yang berhubungan dengan penyusunan rencana dan dukungan teknis pemetaan dan evaluasi risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4046, '5 Mampu 5.1 Mampu mengembangkan konsep, teori, mengembangkan metode dan kebijakan pengelolaan sistem konsep, teori, dan dan strategi penanggulangan bencana. kebijakan pengelolaan 5.2 Mampu mengembangkan strategi, teknik, sistem dan strategi dan instrumen pengelolaan sistem dan penanggulangan strategi penanggulangan bencana. bencana. 5.3 Mampu menjadi rujukan pengelolaan sistem dan strategi penanggulangan bencana di tingkat nasional.
7. Penyusunan Rencana dan Dukungan Teknis Pemetaan dan Evaluasi Risiko Bencana Nama Kompetensi : Penyusunan Rencana dan Dukungan Teknis Pemetaan dan Evaluasi Risiko Bencana Kode Kompetensi : PB.07 Definisi : Kemampuan mengidentifikasi, mengumpulkan, mengolah, menganalisis, dan merumuskan, memonitor dan mengevaluasi, mengidentifikasi umpan balik penerapan rencana dan dukungan teknis pemetaan dan evaluasi risiko bencana, serta mengembangkan teori, konsep, teknik metode penyusunan rencana dan dukungan teknis pemetaan dan evaluasi risiko bencana.
1 Mampu memahami 1.1 Mampu memahami konsep dasar konsep dasar mengenai penyusunan rencana dan penyusunan rencana dukungan teknis pemetaan dan evaluasi kerja dan anggaran. risiko bencana.
1.2 Mampu memahami mengenai peraturan, prosedur dan mekanisme yang berhubungan dengan penyusunan rencana dan dukungan teknis pemetaan dan evaluasi risiko bencana.', 'Lampiran hal. 29', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4047, 'perban-5-2024', 49, 'lampiran', 'Lampiran hal. 29', NULL, 29, '1.3 Mampu melaksanakan pengumpulan data kualitatif maupun kuantitatif yang dibutuhkan dan menyiapkan materi-materi yang diperlukan untuk melaksanakan penyusunan program dan anggaran.
2 Mampu melaksanakan 2.1 Mampu melaksanakan langkah-langkah pengumpulan data identifikasi, pengumpulan data, dan dan informasi sebagai pengolahan data penyusunan rencana bahan penyusunan dan dukungan teknis pemetaan dan rencana dan evaluasi risiko bencana. dukungan teknis 2.2 Mampu menganalisis, menyajikan, dan pemetaan dan evaluasi memanfaatkan hasil untuk risiko bencana. melaksanakan penyusunan konsep rencana dan dukungan teknis pemetaan dan evaluasi risiko bencana.
2.3 Mampu membuat konsep pelaksanaan kegiatan penyusunan konsep rencana dan dukungan teknis pemetaan dan evaluasi risiko bencana.
