INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4048, 'perban-5-2024', 50, 'lampiran', 'Lampiran hal. 30', NULL, 30, '4 Mampu mengevaluasi 4.1 Mampu melakukan evaluasi terhadap dan menyusun teknis/metode/sistem cara kerja perangkat norma menemukenali kelebihan dan standar prosedur kekurangan melakukan pengembangan instrument atau perbaikan dalam penyusunan penyusunan rencana rencana dan dukungan teknis pemetaan dan dukungan teknis dan evaluasi risiko bencana. pemetaan dan evaluasi 4.2 Mampu menyusun pedoman, petunjuk risiko bencana. teknis, cara kerja yang dijadikan norma standar, prosedur, instrumen dalam penyusunan rencana dan dukungan teknis pemetaan dan evaluasi risiko bencana.
