INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4049, 'perban-5-2024', 51, 'lampiran', 'Lampiran hal. 31', NULL, 31, '8. Analisis Potensi Kebencanaan, Ancaman, Kerentanan, Risiko, dan Kapasitas Nama Kompetensi : Analisis Potensi Kebencanaan, Ancaman, Kerentanan, Risiko, dan Kapasitas Kode Kompetensi : PB.08 Definisi : Kemampuan untuk memahami tahapan dan konsep dasar, menyiapkan data sebagai bahan analisis, menganalisis data dan menyusun analisis, membandingkan dan mengkaji ulang, mengevaluasi, serta menyempurnakan analisis, mengembangkan, menyusun rekomendasi, dan menjadi sumber rujukan utama dalam merumuskan analisis potensi kebencanaan, ancaman, kerentanan, risiko, dan kapasitas.
