INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4050, 'perban-5-2024', 52, 'lampiran', 'Lampiran hal. 31', NULL, 31, '2 Mampu menyiapkan 2.1 Mampu melaksanakan langkah - langkah dan mengolah data identifikasi, pengumpulan data, dan sebagai bahan analisis pengolahan data pada proses analisis potensi kebencanaan, potensi kebencanaan, ancaman, ancaman, kerentanan, kerentanan, risiko, dan kapasitas. risiko, dan kapasitas. 2.2 Mampu menganalisis, menyajikan, dan memanfaatkan hasil analisis potensi kebencanaan, ancaman, kerentanan, risiko, dan kapasitas.
2.3 Mampu membuat konsep pelaksanaan kegiatan di bidang analisis potensi kebencanaan, ancaman, kerentanan, risiko, dan kapasitas.
