INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4055, 'perban-5-2024', 57, 'lampiran', 'Lampiran hal. 34', NULL, 34, '1.3 Mampu melaksanakan pengumpulan data kualitatif maupun kuantitatif yang dibutuhkan dan menyiapkan materi-materi yang diperlukan untuk melaksanakan penyusunan sistem penanggulangan bencana.
2 Mampu menyiapkan 2.1 Mampu melaksanakan langkah-langkah dan mengolah data identifikasi, pengumpulan data, dan sebagai bahan pengolahan data pada proses penyusunan sistem penyusunan sistem penanggulangan penanggulangan bencana. bencana. 2.2 Mampu menganalisis, menyajikan, dan memanfaatkan hasil sebagai bahan penyusunan sistem penanggulangan bencana.
2.3 Mampu membuat konsep pelaksanaan kegiatan penyusunan sistem penanggulangan bencana.
3 Mampu 3.1 Mampu mendesain/merancang merencanakan, instrumen identifikasi, pengumpulan melaksanakan, data, pengolahan data, dan penyajian mengendalikan, data/hasil, atau menyusun peta jalan memantau, dan pelaksanaan penyusunan sistem menyusun laporan penanggulangan bencana. penyusunan sistem 3.2 Mampu menyosialisasikan (substansi), penanggulangan memberikan bimbingan, coaching, atau bencana. mentoring dalam pelaksanaan penyusunan sistem penanggulangan bencana.
