INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4056, 'perban-5-2024', 58, 'lampiran', 'Lampiran hal. 35', NULL, 35, '4 Mampu mengevaluasi 4.1 Mampu melakukan evaluasi terhadap dan menyusun teknis/metode/sistem cara kerja, perangkat norma menemukenali kelebihan dan standar prosedur kekurangan, melakukan pengembangan instrumen atau perbaikan dalam penyusunan penyusunan sistem sistem penanggulangan bencana. penanggulangan 4.2 Mampu menyusun pedoman, petunjuk bencana. teknis, dan cara kerja yang dijadikan norma standar, prosedur, dan instrumen dalam penyusunan sistem penanggulangan bencana.
4.3 Mampu meyakinkan dan memperoleh dukungan dari stakeholder terkait penyusunan rencana dan dukungan teknis sistem penanggulangan bencana dan memberikan bimbingan dan fasilitasi kepada instansi lain atau stakeholder terkait penyusunan sistem penanggulangan bencana.
5 Mampu membuat 5.1 Mampu memberikan arahan terkait kebijakan terintegrasi penyusunan sistem penanggulangan terkait penyusunan bencana. sistem 5.2 Mampu membuat kebijakan atas hal-hal penanggulangan yang berhubungan dengan penyusunan bencana. sistem penanggulangan bencana.
5.3 Mampu membuat kebijakan yang saling memberikan dampak terhadap tugas pokok dan fungsi penyusunan sistem penanggulangan bencana agar lebih efektif dan efisien dengan memperhatikan rekomendasi yang ada.');
