INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4057, 'perban-5-2024', 59, 'lampiran', 'Lampiran hal. 36', NULL, 36, '11. Pengembangan Sistem Penanggulangan Bencana Nama Kompetensi : Pengembangan Sistem Penanggulangan Bencana Kode Kompetensi : PB.11 Definisi : Kemampuan mengumpulkan/mengidentifikasi, mengolah, menganalisis, memonitor dan mengevaluasi, mengidentifikasi umpan balik serta mengembangkan sistem penanggulangan bencana yang ada di instansi pemerintah secara holistik dan integratif.
1 Mampu memahami 1.1 Mampu memahami dan menjelaskan berbagai konsep konsep dasar, teori, metode dan dasar, teknik, metode, kebijakan Pengembangan Sistem tata cara, kebijakan, Penanggulangan Bencana. dan peraturan terkait 1.2 Mampu menjelaskan langkah langkah pengembangan sistem tahapan pelaksanaan Pengembangan penanggulangan Sistem Penanggulangan Bencana. bencana. 1.3 Mampu mengidentifikasi berbagai sumber informasi dan mengumpulkan data Pengembangan Sistem Penanggulangan Bencana secara cermat, akurat, dan dapat dipertanggungjawabkan.
2 Mampu menerapkan 2.1 Mampu melaksanakan identifikasi, dan melaksanakan pengumpulan pengolahan data dari berbagai konsep, teori, pelaksanaan pengembangan sistem teknik, metode, penanggulangan bencana. strategi, dan tata cara 2.2 Mampu melaksanakan analisis, pelaksanaan menyajikan, dan memanfaatkan data pengembangan sistem pengembangan sistem penanggulangan penanggulangan bencana. bencana. 2.3 Mampu menjelaskan secara lengkap, rinci dan jelas perihal pengembangan sistem penanggulangan bencana.');
