INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4058, 'perban-5-2024', 60, 'lampiran', 'Lampiran hal. 36', NULL, 36, '3 Mampu 3.1 Mampu merencanakan pelaksanaan merencanakan, pengembangan sistem penanggulangan melaksanakan, bencana. memantau, 3.2 Mampu mengoordinasikan pelaksanaan mengendalikan, dan pengembangan sistem penanggulangan menyusun laporan bencana. pelaksanaan 3.3 Mampu memecahkan masalah teknis pengembangan sistem operasional yang timbul dan mengambil penanggulangan keputusan dalam pelaksanaan bencana sesuai pengembangan sistem penanggulangan pedoman atau bencana. petunjuk teknis.
