INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4065, 'perban-5-2024', 67, 'lampiran', 'Lampiran hal. 40', NULL, 40, '14. Advokasi Kebijakan Bidang Pencegahan Nama Kompetensi : Advokasi Kebijakan Bidang Pencegahan Kode Kompetensi : PB.14 Definisi : Kemampuan berupa pengetahuan dan keterampilan untuk melakukan usaha yang terencana dan sistematis untuk mempengaruhi dan mengupayakan terjadinya perubahan secara bertahap dalam menerapkan (mengadopsi dan mengimplementasi) kebijakan pencegahan bencana. Kemampuan tersebut termasuk mengkomunikasikan konsep, strategi, proses, data, program serta kebijakan kepada stakeholder melalui metode-metode serta strategi yang terencana dengan tujuan agar stakeholder dapat memahami serta menerapkan kebijakan tentang pencegahan bencana.
1 Mampu memahami 1.1 Mampu menjelaskan konsep dasar, berbagai konsep teknik metode, peraturan dan dasar, teknik, metode, mekanisme, tata cara prosedur advokasi tata cara, kebijakan, kebijakan kebijakan bidang pencegahan dan peraturan bencana. advokasi kebijakan 1.2 Mampu menjelaskan langkah langkah bidang teknis bidang tahapan pelaksanaan advokasi kebijakan pencegahan bencana. bidang pencegahan bencana.
1.3 Mampu mengidentifikasi berbagai sumber informasi dan mengumpulkan data advokasi kebijakan bidang pencegahan bencana.');
