INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4068, 'perban-5-2024', 70, 'lampiran', 'Lampiran hal. 42', NULL, 42, '15. Penyelenggaraan Pencegahan Bencana Nama Kompetensi : Penyelenggaraan Pencegahan Bencana Kode Kompetensi : PB.15 Definisi : Kemampuan melakukan tindakan yang cepat dan tepat dalam menghadapi kejadian bencana melalui penyusunan dan uji coba rencana penanggulangan kedaruratan bencana; pengorganisasian, pemasangan, dan pengujian sistem peringatan dini; penyediaan dan penyiapan barang pasokan pemenuhan kebutuhan dasar; pengorganisasian, penyuluhan, pelatihan, dan gladi tentang mekanisme tanggap darurat; penyiapan lokasi evakuasi; penyusunan data akurat, informasi, pemutakhiran dan pengembangan prosedur tetap tanggap darurat bencana; dan penyediaan dan penyiapan bahan, barang, dan peralatan untuk pemenuhan pemulihan prasarana dan sarana.
