INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4085, 'perban-5-2024', 87, 'lampiran', 'Lampiran hal. 53', NULL, 53, '22. Advokasi Kebijakan Bidang Penanganan Darurat Bencana Nama Kompetensi : Advokasi Kebijakan Bidang Penanganan Darurat Bencana Kode Kompetensi : PB.22 Definisi : Kemampuan mengumpulkan/mengidentifikasi, mengolah, menganalisis dan merumuskan usaha yang terencana dan sistematis untuk mempengaruhi dan mengupayakan terjadinya perubahan secara bertahap dalam menerapkan (mengadopsi dan mengimplementasi) kebijakan Penanganan darurat bencana. Kemampuan tersebut termasuk mengkomunikasikan konsep, strategi, proses, data, program serta kebijakan kepada stakeholder melalui metode-metode serta strategi yang terencana dengan tujuan agar stakeholder dapat memahami serta menerapkan kebijakan tentang Penanganan darurat bencana.
