INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4091, 'perban-5-2024', 93, 'lampiran', 'Lampiran hal. 56', NULL, 56, '24. Perencanaan Dukungan Sumber Daya Darurat Bencana Nama Kompetensi : Perencanaan Dukungan Sumber Daya Darurat Kode Kompetensi : PB.24 Definisi : Kemampuan mengumpulkan/mengidentifikasi, mengolah, menganalisis, merumuskan, memonitor dan mengevaluasi, mengidentifikasi umpan balik, serta mengembangkan teori, konsep, teknik dan metode dalam rencana komando penyelenggaraan dukungan sumber daya darurat.
1 Mampu memahami 1.1 Mampu memahami dan menjelaskan berbagai konsep konsep dasar, teori, metode dan dasar, teknik, metode, kebijakan penyelenggaraan dukungan tata cara, kebijakan, sumber daya darurat. dan peraturan terkait 1.2 Mampu menjelaskan langkah langkah penyelenggaraan tahapan pelaksanaan penyelenggaraan dukungan sumber dukungan sumber daya darurat. daya darurat. 1.3 Mampu mengidentifikasi berbagai sumber informasi dan mengumpulkan data penyelenggaraan dukungan sumber daya darurat secara cermat, akurat, dan dapat dipertanggungjawabkan.
2 Mampu menerapkan 2.1 Mampu melaksanakan identifikasi, dan melaksanakan pengumpulan pengolahan data dari berbagai konsep, teori, penyelenggaraan dukungan sumber daya teknik, metode, darurat. strategi, dan tata cara 2.2 Mampu melaksanakan analisis, penyelenggaraan menyajikan, dan memanfaatkan data dukungan sumber penyelenggaraan dukungan sumber daya daya darurat. darurat.
2.3 Mampu menjelaskan secara lengkap, rinci dan jelas perihal penyelenggaraan dukungan sumber daya darurat.');
