INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4093, 'perban-5-2024', 95, 'lampiran', 'Lampiran hal. 57', NULL, 57, '5 Mampu 5.1 Mampu mengidentifikasi, menganalisis mengembangkan teori, konsep, dan kebijakan konsep, teori, penyelenggaraan dukungan sumber daya kebijakan, dan darurat serta pelaksanaannya dalam hal menjadi sumber menemukan kelebihan dan kekurangan rujukan untuk serta rekomendasi perbaikannya. implementasi serta 5.2 Mampu mengembangkan teori, konsep pemecahan masalah dan kebijakan penyelenggaraan penyelenggaraan dukungan sumber daya darurat, dukungan sumber meyakinkan stakeholder dan shareholder daya darurat. terkait untuk menerima konsep, teori dan kebijakan yang dikembangkan.
5.3 Menjadi sumber rujukan utama (nasional) dalam implementasi kebijakan dan pemecahan masalah dalam penyelenggaraan dukungan sumber daya darurat.
