INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4095, 'perban-5-2024', 97, 'lampiran', 'Lampiran hal. 58', NULL, 58, '4 Mampu mengevaluasi 4.1 Mampu melakukan evaluasi terhadap dan menyusun norma, teknis/metode/sistem cara kerja standar, prosedur, dan menemukenali kelebihan dan kriteria pengelolaan kekurangan melakukan pengembangan dukungan sumber atau perbaikan pengelolaan dukungan daya kedaruratan. sumber daya kedaruratan yang lebih efektif/efisien.
4.2 Mampu menyusun pedoman, petunjuk teknis, cara kerja yang dijadikan norma standar, prosedur, instrumen pelaksanaan pengelolaan dukungan sumber daya kedaruratan.
4.3 Mampu meyakinkan dan memperoleh dukungan dari stakeholder pelaksanaan pengelolaan dukungan sumber daya kedaruratan dan memberikan bimbingan dan fasilitasi kepada instansi lain atau stakeholder terkait pengelolaan dukungan sumber daya kedaruratan.
5 Mampu 5.1 Mampu mengidentifikasi, menganalisis, mengembangkan teori, konsep, kebijakan pengelolaan konsep, teori, dukungan sumber daya kedaruratan kebijakan, dan serta pelaksanaannya dalam hal menjadi sumber menemukan kelebihan dan kekurangan rujukan untuk serta rekomendasi perbaikannya. implementasi serta 5.2 Mampu mengembangkan teori, konsep pemecahan masalah dan kebijakan pengelolaan dukungan pengelolaan dukungan sumber daya kedaruratan, meyakinkan sumber daya stakeholder dan shareholder terkait kedaruratan. untuk menerima konsep, teori dan kebijakan yang dikembangkan.
5.3 Menjadi sumber rujukan utama (nasional) dalam implementasi kebijakan dan pemecahan masalah dalam pengelolaan dukungan sumber daya kedaruratan.');
