INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4096, 'perban-5-2024', 98, 'lampiran', 'Lampiran hal. 59', NULL, 59, '26. Penyelenggaraan Dukungan Infrastruktur Darurat Nama Kompetensi : Penyelenggaraan Dukungan Infrastruktur Darurat Kode Kompetensi : PB.26 Definisi : Kemampuan mengumpulkan, mengidentifikasi, mengolah, menganalisis, merumuskan, memonitor dan evaluasi, mengidentifikasi umpan balik, serta mengembangkan teori, konsep, teknik metode komando penyelenggaraan dukungan infrastruktur darurat.
1 Mampu memahami 1.1 Mampu memahami dan menjelaskan berbagai konsep konsep dasar, teori, metode dan dasar, teknik, metode, kebijakan penyelenggaraan dukungan tata cara, kebijakan, infrastruktur darurat. dan peraturan terkait 1.2 Mampu menjelaskan langkah langkah penyelenggaraan tahapan pelaksanaan penyelenggaraan dukungan dukungan infrastruktur darurat. infrastruktur darurat. 1.3 Mampu mengidentifikasi berbagai sumber informasi dan mengumpulkan data penyelenggaraan dukungan infrastruktur darurat secara cermat, akurat, dan dapat dipertanggungjawabkan.
2 Mampu menerapkan 2.1 Mampu melaksanakan identifikasi, dan melaksanakan pengumpulan pengolahan data dari berbagai konsep, teori, penyelenggaraan dukungan infrastruktur teknik, metode, darurat. strategi, dan tata cara 2.2 Mampu melaksanakan analisis, penyelenggaraan menyajikan, dan memanfaatkan data dukungan penyelenggaraan dukungan infrastruktur infrastruktur darurat. darurat.
2.3 Mampu menjelaskan secara lengkap, rinci dan jelas perihal penyelenggaraan dukungan infrastruktur darurat.');
