INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4115, '5 Mampu 5.1 Mampu mengidentifikasi, menganalisis, mengembangkan teori, konsep, kebijakan dalam konsep, teori, dan perencanaan rehabilitasi dan kebijakan rehabilitasi rekonstruksi pasca bencana. dan rekonstruksi, 5.2 Mampu mengembangkan konsep, teori, melalui perencanaan dan kebijakan perencanaan rehabilitasi pemulihan dan dan rekonstruksi pasca bencana serta peningkatan fisik, meyakinkan stakeholder dan shareholder sosial, ekonomi, terkait untuk menerima konsep, teori sumber daya alam, dan dan kebijakan yang dikembangkan. lingkungan hidup yang 5.3 Mampu menjadi sumber rujukan utama sinergis dan (nasional) dalam implementasi kebijakan terintegrasi yang dan pemecahan masalah perencanaan berdampak nasional. rehabilitasi dan rekonstruksi pascabencana.
33. Perencanaan Pendanaan Rehabilitasi dan Rekonstruksi Pasca Bencana Nama Kompetensi : Perencanaan Pendanaan Rehabilitasi dan Rekonstruksi Pasca Bencana Kode Kompetensi : PB.33 Definisi : Kemampuan mengidentifikasi, mengumpulkan, mengolah, menganalisis, dan merumuskan perencanaan pendanaan rehabilitasi dan rekonstruksi meliputi inventarisasi kebutuhan, perencanaan pendanaan, pemantauan, evaluasi dan analisis pelaporan, dan mengidentifikasi umpan balik, serta mengembangkan teori, konsep, teknik metode di bidang perencanaan pendanaan rehabilitasi dan rekonstruksi pasca bencana.', 'Lampiran hal. 70', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4116, 'perban-5-2024', 118, 'lampiran', 'Lampiran hal. 71', NULL, 71, '1 Memahami Konsep 1.1 Mampu menjelaskan konsep dasar, dasar, teknik metode, teknik metode, peraturan dan peraturan dan mekanisme, tata cara prosedur mekanisme, tata cara perencanaan pendanaan rehabilitasi dan prosedur perencanaan rekonstruksi pasca bencana. pendanaan rehabilitasi 1.2 Mampu menjelaskan langkah-langkah dan rekonstruksi pasca atau tahapan-tahapan pelaksanaan bencana. dalam perencanaan pendanaan rehabilitasi dan rekonstruksi pascabencana.
1.3 Mampu memberikan informasi kepada masyarakat dan stakeholder secara tepat terkait perencanaan pendanaan rehabilitasi dan rekonstruksi pascabencana.
2 Mampu menerapkan 2.1 Mampu melaksanakan pengolahan data dan melaksanakan yang dibutuhkan dalam pelaksanaan berbagai konsep, teori, perencanaan pendanaan rehabilitasi dan teknik, metode, rekonstruksi pasca bencana. strategi, dan tata cara 2.2 Mampu melakukan analisis terhadap dalam perencanaan data dan menyajikan analisis tersebut pendanaan rehabilitasi untuk menyusun konsep perencanaan dan rekonstruksi pasca pendanaan rehabilitasi dan rekonstruksi bencana. pasca bencana.
2.3 Mampu menjelaskan secara lengkap, rinci dan jelas perihal perencanaan pendanaan rehabilitasi dan rekonstruksi pasca bencana kepada masyarakat dan stakeholder.');
