INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4117, 'perban-5-2024', 119, 'lampiran', 'Lampiran hal. 71', NULL, 71, '3 Mampu 3.1 Mampu mendesain/merancang merencanakan, instrumen perencanaan pendanaan melaksanakan, rehabilitasi dan rekonstruksi pasca memantau, bencana. mengendalikan, dan menyusun laporan 3.2 Mampu menyosialisasikan perencanaan perencanaan pendanaan rehabilitasi dan rekonstruksi pendanaan rehabilitasi pasca bencana dan memberikan dan rekonstruksi pasca bimbingan, coaching atau mentoring bencana. kepada pegawai di lingkungannya dalam melaksanakan perencanaan pendanaan rehabilitasi dan rekonstruksi pasca bencana.
3.3 Mampu memecahkan masalah teknis operasional yang timbul dan mengambil keputusan dalam perencanaan pendanaan rehabilitasi dan rekonstruksi pasca bencana.
4 Mampu mengevaluasi 4.1. Mampu melakukan evaluasi terhadap dan menyusun teknis/metode/sistem cara kerja perangkat norma menemu kenali kelebihan dan standar prosedur kekurangan melakukan pengembangan instrumen atau perbaikan dalam perencanaan perencanaan pendanaan rehabilitasi dan rekonstruksi pendanaan rehabilitasi pasca bencana. dan rekonstruksi 4.2. Mampu menyusun pedoman, petunjuk pasca bencana. teknis, dan cara kerja yang dijadikan norma standar, prosedur, dan instrumen dalam perencanaan penyusunan rencana rehabilitasi dan rekonstruksi pasca bencana.');
