INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4119, 'perban-5-2024', 121, 'lampiran', 'Lampiran hal. 73', NULL, 73, 'Nama Kompetensi : Inventarisasi dan Analisis Kebutuhan Rehabilitasi dan Rekonstruksi Kode Kompetensi : PB.34 Definisi : Kemampuan mengidentifikasi, mengumpulkan data, mengolah, menganalisis, merumuskan, pemantauan, evaluasi dan analisis pelaporan, dan mengidentifikasi umpan balik, serta mengembangkan teori, konsep, teknik metode dalam inventarisasi dan analisis kebutuhan rehabilitasi dan rekonstruksi.
