INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4129, 'perban-5-2024', 131, 'lampiran', 'Lampiran hal. 78', NULL, 78, '4 Mampu mengevaluasi 4.1. Mampu melakukan evaluasi terhadap dan menyusun teknik/metode/sistem cara kerja, perangkat norma melakukan pengembangan atau standar prosedur perbaikan cara kerja penyusunan instrument dalam kebijakan bidang pemulihan dan melakukan peningkatan sosial, ekonomi, dan SDA. penyusunan kebijakan 4.2. Mampu menyusun pedoman, petunjuk bidang pemulihan dan teknis, cara kerja yang dijadikan norma, peningkatan sosial, standar, prosedur, instrumen ekonomi, dan SDA. pelaksanaan penyusunan kebijakan bidang pemulihan dan peningkatan sosial, ekonomi, dan SDA.
4.3. Mampu meyakinkan dan memperoleh dukungan dari stakeholder terhadap pelaksanaan penyusunan kebijakan, memberikan bimbingan dan fasilitasi kepada instansi lain atau stakeholder terkait penyusunan kebijakan bidang pemulihan dan peningkatan sosial, ekonomi, dan SDA.
5 Mengembangkan 5.1 Mengidentifikasi, menganalisis, teori, konsep, teori, konsep, kebijakan serta pelaksanaan kebijakan bidang penyusunan kebijakan bidang pemulihan dan pemulihan dan peningkatan sosial, peningkatan sosial, ekonomi, dan SDA, mencari kelebihan ekonomi, dan SDA. dan kekurangan dan memberikan rekomendasi perbaikan.
5.2 Mengembangkan teori, konsep dan kebijakan meyakinkan stakeholder dan shareholder terkait untuk menerima konsep, teori dan kebijakan bidang pemulihan dan peningkatan sosial, ekonomi, dan SDA yang dikembangkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4129, '4 Mampu mengevaluasi 4.1. Mampu melakukan evaluasi terhadap dan menyusun teknik/metode/sistem cara kerja, perangkat norma melakukan pengembangan atau standar prosedur perbaikan cara kerja penyusunan instrument dalam kebijakan bidang pemulihan dan melakukan peningkatan sosial, ekonomi, dan SDA. penyusunan kebijakan 4.2. Mampu menyusun pedoman, petunjuk bidang pemulihan dan teknis, cara kerja yang dijadikan norma, peningkatan sosial, standar, prosedur, instrumen ekonomi, dan SDA. pelaksanaan penyusunan kebijakan bidang pemulihan dan peningkatan sosial, ekonomi, dan SDA.
4.3. Mampu meyakinkan dan memperoleh dukungan dari stakeholder terhadap pelaksanaan penyusunan kebijakan, memberikan bimbingan dan fasilitasi kepada instansi lain atau stakeholder terkait penyusunan kebijakan bidang pemulihan dan peningkatan sosial, ekonomi, dan SDA.
5 Mengembangkan 5.1 Mengidentifikasi, menganalisis, teori, konsep, teori, konsep, kebijakan serta pelaksanaan kebijakan bidang penyusunan kebijakan bidang pemulihan dan pemulihan dan peningkatan sosial, peningkatan sosial, ekonomi, dan SDA, mencari kelebihan ekonomi, dan SDA. dan kekurangan dan memberikan rekomendasi perbaikan.
5.2 Mengembangkan teori, konsep dan kebijakan meyakinkan stakeholder dan shareholder terkait untuk menerima konsep, teori dan kebijakan bidang pemulihan dan peningkatan sosial, ekonomi, dan SDA yang dikembangkan.', 'Lampiran hal. 78', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4130, 'perban-5-2024', 132, 'lampiran', 'Lampiran hal. 79', NULL, 79, '5.3 Menjadi sumber rujukan utama (nasional) dalam implementasi kebijakan dan pemecahan masalah dalam penyusunan kebijakan bidang pemulihan dan peningkatan sosial, ekonomi, dan SDA.
38. Penyelenggaraan Pemulihan dan Peningkatan Sosial, Ekonomi, dan SDA Nama Kompetensi : Penyelenggaraan Pemulihan dan Peningkatan Sosial, Ekonomi, dan SDA Kode Kompetensi : PB.38 Definisi : Kemampuan mengumpulkan, mengidentifikasi, mengolah, menganalisis, merumuskan, memantau dan mengevaluasi, menyusun laporan, dan mengidentifikasi umpan balik, serta mengembangkan teori, konsep, teknik metode penyelenggaraan penanggulangan bencana tahap pasca bencana melalui pelaksanaan pemulihan sosial psikologis korban, layanan kesehatan, rekonsiliasi dan resolusi konflik, sosial ekonomi budaya masyarakat, keamanan dan ketertiban, maupun lingkungan.
1 Mampu memahami 1.1 Mampu menjelaskan konsep dasar, berbagai konsep teknik metode, peraturan dan dasar, teknik, metode, mekanisme, tata cara prosedur tata cara, kebijakan, penyelenggaraan pemulihan dan dan peraturan peningkatan sosial, ekonomi, dan SDA penyelenggaraan pasca bencana. pemulihan dan peningkatan sosial, 1.2 Mampu menjelaskan langkah langkah ekonomi, dan SDA tahapan penyelenggaraan pemulihan dan pasca bencana. peningkatan sosial, ekonomi, dan SDA pasca bencana.
1.3 Mampu memberikan informasi kepada masyarakat, stakeholder secara tepat terkait penyelenggaraan pemulihan dan peningkatan sosial, ekonomi, dan SDA pasca bencana.');
