INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4135, 'perban-5-2024', 137, 'lampiran', 'Lampiran hal. 82', NULL, 82, '4 Mampu mengevaluasi 4.1 Mampu melakukan evaluasi terhadap dan menyusun teknik/metode/sistem cara kerja, perangkat norma melakukan pengembangan atau standar prosedur perbaikan cara kerja penyusunan instrument dalam kebijakan bidang logistik dan peralatan melakukan penanggulangan bencana. penyusunan 4.2 Mampu menyusun pedoman, petunjuk kebijakan bidang teknis, cara kerja yang dijadikan norma, logistik dan peralatan standar, prosedur, instrumen penanggulangan pelaksanaan penyusunan kebijakan bencana. bidang logistik dan peralatan penanggulangan bencana.
4.3 Mampu meyakinkan dan memperoleh dukungan dari stakeholder terhadap pelaksanaan penyusunan kebijakan, memberikan bimbingan dan fasilitasi kepada instansi lain atau stakeholder terkait penyusunan kebijakan bidang logistik dan peralatan penanggulangan bencana.
5 Mengembangkan 5.1 Mengidentifikasi, menganalisis, teori, konsep, teori, konsep, kebijakan serta pelaksanaan kebijakan bidang penyusunan kebijakan bidang logistik logistik dan peralatan dan peralatan penanggulangan bencana, penanggulangan mencari kelebihan dan kekurangan dan bencana. memberikan rekomendasi perbaikan.
5.2 Mengembangkan teori, konsep dan kebijakan meyakinkan stakeholder dan shareholder terkait untuk menerima konsep, teori dan kebijakan bidang logistik dan peralatan penanggulangan bencana yang dikembangkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4135, '4 Mampu mengevaluasi 4.1 Mampu melakukan evaluasi terhadap dan menyusun teknik/metode/sistem cara kerja, perangkat norma melakukan pengembangan atau standar prosedur perbaikan cara kerja penyusunan instrument dalam kebijakan bidang logistik dan peralatan melakukan penanggulangan bencana. penyusunan 4.2 Mampu menyusun pedoman, petunjuk kebijakan bidang teknis, cara kerja yang dijadikan norma, logistik dan peralatan standar, prosedur, instrumen penanggulangan pelaksanaan penyusunan kebijakan bencana. bidang logistik dan peralatan penanggulangan bencana.
4.3 Mampu meyakinkan dan memperoleh dukungan dari stakeholder terhadap pelaksanaan penyusunan kebijakan, memberikan bimbingan dan fasilitasi kepada instansi lain atau stakeholder terkait penyusunan kebijakan bidang logistik dan peralatan penanggulangan bencana.
5 Mengembangkan 5.1 Mengidentifikasi, menganalisis, teori, konsep, teori, konsep, kebijakan serta pelaksanaan kebijakan bidang penyusunan kebijakan bidang logistik logistik dan peralatan dan peralatan penanggulangan bencana, penanggulangan mencari kelebihan dan kekurangan dan bencana. memberikan rekomendasi perbaikan.
5.2 Mengembangkan teori, konsep dan kebijakan meyakinkan stakeholder dan shareholder terkait untuk menerima konsep, teori dan kebijakan bidang logistik dan peralatan penanggulangan bencana yang dikembangkan.', 'Lampiran hal. 82', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4136, 'perban-5-2024', 138, 'lampiran', 'Lampiran hal. 83', NULL, 83, '5.3 Mampu menjadi sumber rujukan utama (nasional) dalam implementasi kebijakan dan pemecahan masalah dalam penyusunan kebijakan bidang logistik dan peralatan penanggulangan bencana.
40. Advokasi Kebijakan Bidang Logistik dan Peralatan Penanggulangan Bencana Nama Kompetensi : Advokasi Kebijakan Bidang Logistik Dan Peralatan Penanggulangan Bencana Kode Kompetensi : PB.40 Definisi : Kemampuan mengumpulkan, mengidentifikasi, mengolah, menganalisis, dan merumuskan usaha yang terencana dan sistematis untuk mempengaruhi dan mengupayakan terjadinya perubahan secara bertahap dalam menerapkan (mengadopsi dan mengimplementasi) kebijakan bidang logistik dan peralatan. Kemampuan tersebut termasuk mengkomunikasikan konsep, strategi, proses, data, program serta kebijakan kepada stakeholder melalui metode-metode serta strategi yang terencana dengan tujuan agar stakeholder dapat memahami serta menerapkan kebijakan bidang logistik dan peralatan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4136, '5.3 Mampu menjadi sumber rujukan utama (nasional) dalam implementasi kebijakan dan pemecahan masalah dalam penyusunan kebijakan bidang logistik dan peralatan penanggulangan bencana.
40. Advokasi Kebijakan Bidang Logistik dan Peralatan Penanggulangan Bencana Nama Kompetensi : Advokasi Kebijakan Bidang Logistik Dan Peralatan Penanggulangan Bencana Kode Kompetensi : PB.40 Definisi : Kemampuan mengumpulkan, mengidentifikasi, mengolah, menganalisis, dan merumuskan usaha yang terencana dan sistematis untuk mempengaruhi dan mengupayakan terjadinya perubahan secara bertahap dalam menerapkan (mengadopsi dan mengimplementasi) kebijakan bidang logistik dan peralatan. Kemampuan tersebut termasuk mengkomunikasikan konsep, strategi, proses, data, program serta kebijakan kepada stakeholder melalui metode-metode serta strategi yang terencana dengan tujuan agar stakeholder dapat memahami serta menerapkan kebijakan bidang logistik dan peralatan penanggulangan bencana.', 'Lampiran hal. 83', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4137, 'perban-5-2024', 139, 'lampiran', 'Lampiran hal. 83', NULL, 83, '1 Mampu memahami 1.1 Mampu mengembangkan konsep, teori, berbagai konsep metode dan kebijakan advokasi kebijakan dasar, teknik, metode, bidang logistik dan peralatan tata cara, kebijakan, penanggulangan bencana. dan peraturan 1.2 Mampu menjelaskan langkah langkah advokasi kebijakan tahapan pelaksanaan advokasi kebijakan bidang logistik dan bidang logistik dan peralatan peralatan penanggulangan bencana. penanggulangan 1.3 Mampu mengidentifikasi berbagai sumber bencana. informasi dan mengumpulkan data advokasi kebijakan bidang logistik dan peralatan penanggulangan bencana.
2 Mampu menerapkan 2.1 Mampu melaksanakan konsep, teori, dan melaksanakan metode dan kebijakan advokasi kebijakan berbagai konsep, teori, bidang logistik dan peralatan teknik, metode, penanggulangan bencana. strategi, dan tata cara 2.2 Mampu melaksanakan menyajikan dan advokasi kebijakan memanfaatkan data tentang advokasi bidang logistik dan kebijakan bidang logistik dan peralatan peralatan penanggulangan bencana. penanggulangan 2.3 Mampu menjelaskan secara lengkap, rinci bencana. dan jelas perihal advokasi kebijakan bidang logistik dan peralatan penanggulangan bencana kepada masyarakat dan stakeholder.');
