INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4151, 'perban-5-2024', 153, 'lampiran', 'Lampiran hal. 91', NULL, 91, '2 Mampu menerapkan 2.1 Mampu melaksanakan pengolahan data dan melaksanakan yang dibutuhkan untuk menyusun berbagai konsep, teori, kebijakan bidang data, informasi dan teknik, metode, komunikasi kebencanaan. strategi, dan tata cara 2.2 Mampu melakukan analisis terhadap penyusunan kebijakan data dan menyajikan analisis tersebut bidang data, informasi untuk menyusun konsep kebijakan dan komunikasi bidang data, informasi dan komunikasi kebencanaan. kebencanaan.
