INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4153, 'perban-5-2024', 155, 'lampiran', 'Lampiran hal. 92', NULL, 92, '45. Advokasi Kebijakan Bidang Data, Informasi dan Komunikasi Kebencanaan Nama Kompetensi : Advokasi Kebijakan Bidang Data, Informasi dan Komunikasi Kebencanaan Kode Kompetensi : PB.45 Definisi : Kemampuan mengumpulkan, mengidentifikasi, mengolah, menganalisis, dan merumuskan usaha yang terencana dan sistematis untuk mempengaruhi dan mengupayakan terjadinya perubahan secara bertahap dalam menerapkan (mengadopsi dan mengimplementasi) kebijakan bidang data, informasi dan komunikasi kebencanaan. Kemampuan tersebut termasuk mengkomunikasikan konsep, strategi, proses, data, program serta kebijakan kepada stakeholder melalui metode-metode serta strategi yang terencana dengan tujuan agar stakeholder dapat memahami serta menerapkan kebijakan bidang data, informasi dan komunikasi kebencanaan.
1 Mampu memahami 1.1 Mampu menjelaskan konsep dasar, berbagai konsep teknik metode, peraturan dan dasar, teknik, metode, mekanisme, tata cara prosedur advokasi tata cara, kebijakan, kebijakan kebijakan bidang data, dan peraturan informasi dan komunikasi kebencanaan. advokasi kebijakan 1.2 Mampu menjelaskan langkah langkah bidang teknis bidang tahapan pelaksanaan advokasi kebijakan data, informasi dan bidang data, informasi dan komunikasi komunikasi kebencanaan. kebencanaan. 1.3 Mampu mengidentifikasi berbagai sumber informasi dan mengumpulkan data advokasi kebijakan bidang data, informasi dan komunikasi kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4153, '45. Advokasi Kebijakan Bidang Data, Informasi dan Komunikasi Kebencanaan Nama Kompetensi : Advokasi Kebijakan Bidang Data, Informasi dan Komunikasi Kebencanaan Kode Kompetensi : PB.45 Definisi : Kemampuan mengumpulkan, mengidentifikasi, mengolah, menganalisis, dan merumuskan usaha yang terencana dan sistematis untuk mempengaruhi dan mengupayakan terjadinya perubahan secara bertahap dalam menerapkan (mengadopsi dan mengimplementasi) kebijakan bidang data, informasi dan komunikasi kebencanaan. Kemampuan tersebut termasuk mengkomunikasikan konsep, strategi, proses, data, program serta kebijakan kepada stakeholder melalui metode-metode serta strategi yang terencana dengan tujuan agar stakeholder dapat memahami serta menerapkan kebijakan bidang data, informasi dan komunikasi kebencanaan.
