INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4154, 'perban-5-2024', 156, 'lampiran', 'Lampiran hal. 92', NULL, 92, '2 Mampu menerapkan 2.1 Mampu melaksanakan konsep, teori, dan melaksanakan metode dan kebijakan advokasi kebijakan berbagai konsep, teori, bidang data, informasi dan komunikasi teknik, metode, kebencanaan. strategi, dan tata cara 2.2 Mampu melaksanakan menyajikan dan advokasi kebijakan memanfaatkan data tentang advokasi bidang data, informasi dan komunikasi kebijakan bidang data, informasi dan kebencanaan. komunikasi kebencanaan.
