INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4156, '46. Manajemen Data dan Informasi Nama Kompetensi : Manajemen Data dan Informasi Kode Kompetensi : PB.46 Definisi : Kemampuan mengumpulkan, mengidentifikasi, mengolah, menganalisis, dan merumuskan konsep pengelolaan data dan informasi kebencanaan, memantau dan mengevaluasi, mengidentifikasi umpan balik serta pengembangan, dan pengintegrasian teknologi dan jaringan di lingkungan Badan Nasional Penanggulangan Bencana, meliputi pengolahan data, analisis dan diseminasi informasi darurat bencana.
1 Mampu memahami 1.1 Mampu memahami dan menjelaskan berbagai konsep konsep dasar, teori, metode dan dasar, teknik, metode, kebijakan manajemen data dan informasi tata cara, kebijakan, kebencanaan. dan peraturan terkait 1.2 Mampu menjelaskan langkah langkah manajemen data dan tahapan pelaksanaan manajemen data informasi dan informasi kebencanaan. kebencanaan. 1.3 Mampu mengidentifikasi berbagai sumber informasi dan mengumpulkan data manajemen logistik dan peralatan penanggulan bencana secara cermat, akurat, dan dapat dipertanggungjawabkan.', 'Lampiran hal. 94', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4157, 'perban-5-2024', 159, 'lampiran', 'Lampiran hal. 94', NULL, 94, '2 Mampu menerapkan 2.1 Mampu melaksanakan identifikasi, dan melaksanakan pengumpulan pengolahan data dari berbagai konsep, teori, pelaksanaan manajemen data dan teknik, metode, informasi kebencanaan. strategi, dan tata cara 2.2 Mampu melaksanakan analisis, pelaksanaan menyajikan, dan memanfaatkan data manajemen data dan manajemen data dan informasi informasi kebencanaan. kebencanaan. 2.3 Mampu menjelaskan secara lengkap, rinci dan jelas perihal manajemen data dan informasi kebencanaan.
3 Mampu 3.1 Mampu merencanakan pelaksanaan merencanakan, manajemen data dan informasi melaksanakan, kebencanaan. memantau, 3.2 Mampu mengoordinasikan pelaksanaan mengendalikan, dan manajemen logistik dan peralatan menyusun laporan penanggulangan bencana. pelaksanaan 3.3 Mampu memecahkan masalah teknis manajemen data dan operasional yang timbul dan mengambil informasi keputusan dalam pelaksanaan kebencanaan sesuai manajemen data dan informasi pedoman atau kebencanaan. petunjuk teknis.
4 Mampu mengevaluasi 4.1 Mampu melakukan evaluasi terhadap dan menyusun norma, teknis/metode/sistem cara kerja standar, prosedur, dan menemukenali kelebihan dan kriteria manajemen kekurangan melakukan pengembangan data dan informasi atau perbaikan manajemen data dan kebencanaan. informasi kebencanaan yang lebih efektif/efisien.
4.2 Mampu menyusun pedoman, petunjuk teknis, cara kerja yang dijadikan norma standar, prosedur, instrumen pelaksanaan manajemen data dan informasi kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4157, '2 Mampu menerapkan 2.1 Mampu melaksanakan identifikasi, dan melaksanakan pengumpulan pengolahan data dari berbagai konsep, teori, pelaksanaan manajemen data dan teknik, metode, informasi kebencanaan. strategi, dan tata cara 2.2 Mampu melaksanakan analisis, pelaksanaan menyajikan, dan memanfaatkan data manajemen data dan manajemen data dan informasi informasi kebencanaan. kebencanaan. 2.3 Mampu menjelaskan secara lengkap, rinci dan jelas perihal manajemen data dan informasi kebencanaan.
3 Mampu 3.1 Mampu merencanakan pelaksanaan merencanakan, manajemen data dan informasi melaksanakan, kebencanaan. memantau, 3.2 Mampu mengoordinasikan pelaksanaan mengendalikan, dan manajemen logistik dan peralatan menyusun laporan penanggulangan bencana. pelaksanaan 3.3 Mampu memecahkan masalah teknis manajemen data dan operasional yang timbul dan mengambil informasi keputusan dalam pelaksanaan kebencanaan sesuai manajemen data dan informasi pedoman atau kebencanaan. petunjuk teknis.
4 Mampu mengevaluasi 4.1 Mampu melakukan evaluasi terhadap dan menyusun norma, teknis/metode/sistem cara kerja standar, prosedur, dan menemukenali kelebihan dan kriteria manajemen kekurangan melakukan pengembangan data dan informasi atau perbaikan manajemen data dan kebencanaan. informasi kebencanaan yang lebih efektif/efisien.
4.2 Mampu menyusun pedoman, petunjuk teknis, cara kerja yang dijadikan norma standar, prosedur, instrumen pelaksanaan manajemen data dan informasi kebencanaan.', 'Lampiran hal. 94', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4158, 'perban-5-2024', 160, 'lampiran', 'Lampiran hal. 95', NULL, 95, '4.3 Mampu meyakinkan dan memperoleh dukungan dari stakeholder pelaksanaan manajemen data dan informasi kebencanaan dan memberikan bimbingan dan fasilitasi kepada instansi lain atau stakeholder terkait manajemen data dan informasi kebencanaan.
5 Mampu 5.1 Mampu mengidentifikasi, menganalisis, mengembangkan teori, konsep, kebijakan manajemen data konsep, teori, dan informasi kebencanaan serta kebijakan, dan pelaksanaannya dalam hal menemukan menjadi sumber kelebihan dan kekurangan serta rujukan untuk rekomendasi perbaikannya. implementasi serta 5.2 Mampu mengembangkan teori, konsep pemecahan masalah dan kebijakan manajemen data dan manajemen data dan informasi kebencanaan, meyakinkan informasi stakeholder dan shareholder terkait kebencanaan. untuk menerima konsep, teori dan kebijakan yang dikembangkan.
5.3 Menjadi sumber rujukan utama (nasional) dalam implementasi kebijakan dan pemecahan masalah dalam manajemen data dan informasi kebencanaan.
