INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4183, 'perban-5-2024', 185, 'lampiran', 'Lampiran hal. 109', NULL, 109, '55. Penyelenggaraan Pengendalian Operasi Penanggulangan Bencana Lintas Sektor Nama Kompetensi : Penyelenggaraan Pengendalian Operasi Penanggulangan Bencana Lintas Sektor Kode Kompetensi : PB.55 Definisi : Kemampuan mengumpulkan, mengidentifikasi, mengolah, menganalisis, merumuskan, memantau dan mengevaluasi, menyusun laporan, dan mengidentifikasi umpan balik, serta mengembangkan berbagai konsep dasar, teknik, metode penyelenggaraan pengendalian operasi penanggulangan bencana lintas sektor.
1 Mampu memahami 1.1 Mampu memahami dan menjelaskan berbagai konsep konsep dasar, teori, metode dan dasar, teknik, metode, kebijakan penyelenggaraan pengendalian tata cara, kebijakan, dan peraturan terkait operasi penanggulangan bencana lintas penyelenggaraan sektor. pengendalian operasi 1.2 Mampu menjelaskan langkah langkah penanggulangan tahapan pelaksanaan penyelenggaraan bencana lintas sektor. pengendalian operasi penanggulangan bencana lintas sektor.
1.3 Mampu mengidentifikasi berbagai sumber informasi dan mengumpulkan data penyelenggaraan pengendalian operasi penanggulangan bencana lintas sektor secara cermat, akurat, dan dapat dipertanggungjawabkan.');
