INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4194, 'perban-5-2024', 196, 'lampiran', 'Lampiran hal. 116', NULL, 116, 'Demikian dokumen Kamus Kompetensi Teknis Badan Nasional Penanggulangan Bencana disajikan. Dengan kamus kompetensi teknis ini, diharapkan dapat menjadi acuan dalam Manajemen ASN di lingkungan Badan Nasional Penanggulangan Bencana untuk mengukur kompetensi individu ASN dalam kegiatan rekrutmen, pengembangan, pengangkatan, penempatan, promosi dalam suatu jabatan, dan pelaksanaan rekrutmen terbuka jabatan tinggi di lingkungan Badan Nasional Penanggulangan Bencana. Kamus Kompetensi ini merupakan sarana dasar dalam menyelenggarakan sistem merit manajemen aparatur negara di lingkungan Badan Nasional Penanggulangan Bencana.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4194, 'Demikian dokumen Kamus Kompetensi Teknis Badan Nasional Penanggulangan Bencana disajikan. Dengan kamus kompetensi teknis ini, diharapkan dapat menjadi acuan dalam Manajemen ASN di lingkungan Badan Nasional Penanggulangan Bencana untuk mengukur kompetensi individu ASN dalam kegiatan rekrutmen, pengembangan, pengangkatan, penempatan, promosi dalam suatu jabatan, dan pelaksanaan rekrutmen terbuka jabatan tinggi di lingkungan Badan Nasional Penanggulangan Bencana. Kamus Kompetensi ini merupakan sarana dasar dalam menyelenggarakan sistem merit manajemen aparatur negara di lingkungan Badan Nasional Penanggulangan Bencana.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO', 'Lampiran hal. 116', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2024 tentang Kamus Kompetensi Teknis Bidang Penanggulangan Bencana');
