INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4199, 'perban-5-2025', 4, 'pasal', 'Pasal 1', NULL, 2, 'Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029 yang selanjutnya disebut Renstra Badan merupakan dokumen perencanaan Badan Nasional Penanggulangan Bencana untuk periode 5 (lima) tahun terhitung sejak tahun 2025 sampai dengan tahun 2029.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4199, 'Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029 yang selanjutnya disebut Renstra Badan merupakan dokumen perencanaan Badan Nasional Penanggulangan Bencana untuk periode 5 (lima) tahun terhitung sejak tahun 2025 sampai dengan tahun 2029.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4200, 'perban-5-2025', 5, 'pasal', 'Pasal 2', NULL, 2, '(1) Renstra Badan sebagaimana dimaksud dalam Pasal 1 memuat:
a. visi, misi, tujuan, dan sasaran strategis;
b. arah kebijakan, strategi, kerangka regulasi, dan kerangka kelembagaan; dan
c. target kinerja dan kerangka pendanaan.
(2) Ketentuan mengenai Renstra Badan sebagaimana dimaksud pada ayat (1) tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4200, '(1) Renstra Badan sebagaimana dimaksud dalam Pasal 1 memuat:
a. visi, misi, tujuan, dan sasaran strategis;
b. arah kebijakan, strategi, kerangka regulasi, dan kerangka kelembagaan; dan
c. target kinerja dan kerangka pendanaan.
(2) Ketentuan mengenai Renstra Badan sebagaimana dimaksud pada ayat (1) tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4201, 'perban-5-2025', 6, 'pasal', 'Pasal 3', NULL, 3, 'Data dan informasi kinerja Renstra Badan yang termuat dalam sistem informasi KRISNA-RENSTRA merupakan bagian yang tidak terpisahkan dari dokumen Renstra Badan sebagaimana dimaksud dalam Pasal 2.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4201, 'Data dan informasi kinerja Renstra Badan yang termuat dalam sistem informasi KRISNA-RENSTRA merupakan bagian yang tidak terpisahkan dari dokumen Renstra Badan sebagaimana dimaksud dalam Pasal 2.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4202, 'perban-5-2025', 7, 'pasal', 'Pasal 4', NULL, 3, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2020-2024 (Berita Negara Republik Indonesia Tahun 2020 Nomor 845), dicabut dan dinyatakan tidak berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4202, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2020 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2020-2024 (Berita Negara Republik Indonesia Tahun 2020 Nomor 845), dicabut dan dinyatakan tidak berlaku.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4203, 'perban-5-2025', 8, 'pasal', 'Pasal 5', NULL, 3, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4203, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4204, 'perban-5-2025', 9, 'lain', 'Penutup', NULL, 4, 'Ditetapkan di Jakarta pada tanggal 3 Oktober 2025 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2025 NOMOR Ж');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4204, 'Ditetapkan di Jakarta pada tanggal 3 Oktober 2025 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2025 NOMOR Ж', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4205, 'perban-5-2025', 10, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 5 TAHUN 2025 TENTANG RENCANA STRATEGIS BADAN NASIONAL PENANGGULANGAN BENCANA TAHUN 2025-2029 RENCANA STRATEGIS BADAN NASIONAL PENANGGULANGAN BENCANA TAHUN 2025-2029 BAB 1. PENDAHULUAN 1.1. Kondisi Umum Badan Nasional Penanggulangan Bencana (BNPB) sebagai lembaga pemerintah yang menyelenggarakan urusan di bidang penanggulangan bencana, melakukan penyusunan dokumen Renstra yang bertujuan untuk memberikan arah bagi BNPB dalam mencapai tujuan penanggulangan bencana di Indonesia. Dokumen ini akan menjadi penjabaran dari Rencana Pembangunan Jangka Menengah Nasional (RPJMN) 2025-2029, serta selaras dengan Visi Presiden dan Wakil Presiden periode 2025-2029 dan Visi RPJMN 2025-2029, yaitu “Bersama Indonesia Maju Menuju Indonesia Emas 2045”.
Penyusunan Renstra BNPB secara teknis berpedoman pada Rencana Induk Penanggulangan Bencana (RIPB) Tahun 2020-2044 yang merupakan pedoman nasional untuk penyelenggaraan penanggulangan bencana dan menjadi acuan bagi Kementerian/Lembaga, Tentara Nasional Indonesia, Kepolisian Negara Republik Indonesia, dan Pemerintah Daerah dalam perencanaan dan pelaksanaan penyelenggaraan penanggulangan bencana untuk jangka waktu 25 (dua puluh lima) tahun dan terdiri dari 5 tahap dengan jangka waktu 5 (lima) tahunan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4205, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 5 TAHUN 2025 TENTANG RENCANA STRATEGIS BADAN NASIONAL PENANGGULANGAN BENCANA TAHUN 2025-2029 RENCANA STRATEGIS BADAN NASIONAL PENANGGULANGAN BENCANA TAHUN 2025-2029 BAB 1. PENDAHULUAN 1.1. Kondisi Umum Badan Nasional Penanggulangan Bencana (BNPB) sebagai lembaga pemerintah yang menyelenggarakan urusan di bidang penanggulangan bencana, melakukan penyusunan dokumen Renstra yang bertujuan untuk memberikan arah bagi BNPB dalam mencapai tujuan penanggulangan bencana di Indonesia. Dokumen ini akan menjadi penjabaran dari Rencana Pembangunan Jangka Menengah Nasional (RPJMN) 2025-2029, serta selaras dengan Visi Presiden dan Wakil Presiden periode 2025-2029 dan Visi RPJMN 2025-2029, yaitu “Bersama Indonesia Maju Menuju Indonesia Emas 2045”.
Penyusunan Renstra BNPB secara teknis berpedoman pada Rencana Induk Penanggulangan Bencana (RIPB) Tahun 2020-2044 yang merupakan pedoman nasional untuk penyelenggaraan penanggulangan bencana dan menjadi acuan bagi Kementerian/Lembaga, Tentara Nasional Indonesia, Kepolisian Negara Republik Indonesia, dan Pemerintah Daerah dalam perencanaan dan pelaksanaan penyelenggaraan penanggulangan bencana untuk jangka waktu 25 (dua puluh lima) tahun dan terdiri dari 5 tahap dengan jangka waktu 5 (lima) tahunan.', 'Lampiran hal. 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4206, 'perban-5-2025', 11, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'Perencanaan Strategis ini disusun secara partisipatif, sistematis, dan berkelanjutan guna memusatkan seluruh kegiatan dalam rangka mencapai visi, misi, tujuan, dan sasaran BNPB. Perencanaan ini juga berfungsi untuk menetapkan strategi, arah, dan pedoman dalam pengambilan keputusan serta tindakan yang tepat, dengan mempertimbangkan pilihan terbaik dan ketersediaan sumber daya.
Bagian ini akan menjelaskan kondisi umum kebencanaan di Indonesia yang meliputi ancaman bencana dan indeks risiko bencana. Selain itu, bagian ini turut menjabarkan hasil evaluasi Renstra BNPB Tahun 2020-2024 yang meliputi pencapaian Sasaran Strategis, Capaian Sasaran Program, Capaian Sasaran Kegiatan.
Pemahaman mengenai upaya pengurangan risiko bencana sistemik diperlukan dalam upaya penanggulangan bencana di Indonesia. Dalam indeks risiko, tingkat risiko dinilai berdasarkan komponen penyusunnya, antara lain: bahaya, kerentanan, dan kapasitas pemerintah dalam menghadapi bencana. Penilaian tingkat risiko berdasarkan potensi kerugian dapat membantu upaya mengurangi risiko bencana. Gambar 1.1 menunjukkan peta persebaran indeks risiko bencana per provinsi di Indonesia. Ancaman yang menjadi konsiderasi dalam penentuan indeks risiko bencana ini meliputi gempa bumi, tsunami, letusan gunung api, tanah longsor, banjir, kekeringan, kebakaran hutan dan lahan, cuaca ekstrem, serta abrasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4206, 'Perencanaan Strategis ini disusun secara partisipatif, sistematis, dan berkelanjutan guna memusatkan seluruh kegiatan dalam rangka mencapai visi, misi, tujuan, dan sasaran BNPB. Perencanaan ini juga berfungsi untuk menetapkan strategi, arah, dan pedoman dalam pengambilan keputusan serta tindakan yang tepat, dengan mempertimbangkan pilihan terbaik dan ketersediaan sumber daya.
Bagian ini akan menjelaskan kondisi umum kebencanaan di Indonesia yang meliputi ancaman bencana dan indeks risiko bencana. Selain itu, bagian ini turut menjabarkan hasil evaluasi Renstra BNPB Tahun 2020-2024 yang meliputi pencapaian Sasaran Strategis, Capaian Sasaran Program, Capaian Sasaran Kegiatan.
Pemahaman mengenai upaya pengurangan risiko bencana sistemik diperlukan dalam upaya penanggulangan bencana di Indonesia. Dalam indeks risiko, tingkat risiko dinilai berdasarkan komponen penyusunnya, antara lain: bahaya, kerentanan, dan kapasitas pemerintah dalam menghadapi bencana. Penilaian tingkat risiko berdasarkan potensi kerugian dapat membantu upaya mengurangi risiko bencana. Gambar 1.1 menunjukkan peta persebaran indeks risiko bencana per provinsi di Indonesia. Ancaman yang menjadi konsiderasi dalam penentuan indeks risiko bencana ini meliputi gempa bumi, tsunami, letusan gunung api, tanah longsor, banjir, kekeringan, kebakaran hutan dan lahan, cuaca ekstrem, serta abrasi.', 'Lampiran hal. 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4207, 'perban-5-2025', 12, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'Gambar 1.1. Peta Indeks Risiko Bencana Tingkat Provinsi Tahun 2023 Sumber: BNPB, 2024 Risiko bencana akan mengalami fluktuasi dengan berubahnya komponen kerentanan dan kapasitas di suatu daerah. Penilaian risiko ini dapat digunakan sebagai perangkat pemantauan dan evaluasi terhadap capaian program penanggulangan bencana pada periode tertentu. Tabel 1.1. menunjukkan data perbandingan perubahan indeks risiko bencana di Indonesia berdasarkan provinsi pada tahun 2019 hingga tahun 2023. Tabel tersebut memperlihatkan bahwa hampir semua provinsi mengalami penurunan indeks risiko bencana, dengan sebanyak delapan provinsi di Indonesia mengalami penurunan tingkat dalam kelas indeks risiko bencana. Disampaikan pada evaluasi pelaksanaan Rencana Strategis BNPB Tahun 2020-2024, penurunan nilai indeks tersebut dapat terjadi salah satunya karena peningkatan upaya pemahaman dan keterlibatan masyarakat dalam merealisasikan rencana antisipasi ancaman/bahaya di daerah yang rawan bencana.
Semakin tinggi indeks risiko bencana suatu daerah menggambarkan semakin tingginya potensi daerah tersebut untuk berada pada jangkauan paparan bahaya, dan/atau semakin rentannya daerah tersebut ketika dihadapkan pada bencana, dan/atau semakin rendahnya kesiapan masyarakat, dan/atau semakin menurunnya kapasitas pemerintah dalam menghadapi keadaan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4207, 'Gambar 1.1. Peta Indeks Risiko Bencana Tingkat Provinsi Tahun 2023 Sumber: BNPB, 2024 Risiko bencana akan mengalami fluktuasi dengan berubahnya komponen kerentanan dan kapasitas di suatu daerah. Penilaian risiko ini dapat digunakan sebagai perangkat pemantauan dan evaluasi terhadap capaian program penanggulangan bencana pada periode tertentu. Tabel 1.1. menunjukkan data perbandingan perubahan indeks risiko bencana di Indonesia berdasarkan provinsi pada tahun 2019 hingga tahun 2023. Tabel tersebut memperlihatkan bahwa hampir semua provinsi mengalami penurunan indeks risiko bencana, dengan sebanyak delapan provinsi di Indonesia mengalami penurunan tingkat dalam kelas indeks risiko bencana. Disampaikan pada evaluasi pelaksanaan Rencana Strategis BNPB Tahun 2020-2024, penurunan nilai indeks tersebut dapat terjadi salah satunya karena peningkatan upaya pemahaman dan keterlibatan masyarakat dalam merealisasikan rencana antisipasi ancaman/bahaya di daerah yang rawan bencana.
Semakin tinggi indeks risiko bencana suatu daerah menggambarkan semakin tingginya potensi daerah tersebut untuk berada pada jangkauan paparan bahaya, dan/atau semakin rentannya daerah tersebut ketika dihadapkan pada bencana, dan/atau semakin rendahnya kesiapan masyarakat, dan/atau semakin menurunnya kapasitas pemerintah dalam menghadapi keadaan bencana.', 'Lampiran hal. 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
