INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4210, '144.96 Tinggi 144.96 Tinggi 146.07 Tinggi 143.44 Sedang 140.56 Sedang Tengah Sulawesi 34 157.72 Tinggi 157.72 Tinggi 157.9 Tinggi 155.79 Tinggi 153.08 Tinggi Tenggara Sulawesi 35 139.47 Sedang 139.47 Sedang 133.29 Sedang 129.62 Sedang 128.01 Sedang Utara Sumatera 36 150.24 Tinggi 145.18 Tinggi 147.36 Tinggi 144.39 Tinggi 144.38 Tinggi Barat Sumatera 37 139.62 Sedang 159.49 Tinggi 137.31 Sedang 132.99 Sedang 131.34 Sedang Selatan Sumatera 38 145.18 Tinggi 145.18 Tinggi 143.83 Sedang 142.51 Sedang 140.65 Sedang Utara Sumber: Buku Indeks Risiko Bencana Indonesia 2019-2023 Kemudian, terdapat juga hasil analisis jumlah jiwa terpapar bencana pada tahun 2023 yang dibagi berdasarkan tingkat/kelas risiko. Jumlah jiwa terpapar bencana berdasarkan kelas risiko multi ancaman kelas rendah sebanyak 8.654.582 jiwa, kelas sedang sebanyak 35.897.949 jiwa, dan kelas tinggi 213.519.183 jiwa.', 'Lampiran hal. 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4211, 'perban-5-2025', 16, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'Tabel 1.2. Potensi Jiwa Terpapar berdasarkan Kajian Risiko Bencana Multi Ancaman Jumlah Jiwa Terpapar berdasarkan Kajian Risiko Bencana Multi No Provinsi Ancaman Rendah Sedang Tinggi 1 Aceh 124,368.00 58,748.00 4,613,376.00 2 Bali 133,5.008 1,199,268.00 2,941,141.00 3 Banten 10,061.00 1,041,732.00 1,064,635.00 4 Bengkulu 69.00 26,932.00 1,999,938.00 5 Daerah Istimewa Yogyakarta 54,196.00 596,816.00 302,465.00 6 DKI Jakarta 7,011.00 16,179.00 11,222,878.00 7 Gorontalo 246.00 122,594.00 1,075,925.00 8 Jambi 154,531.00 634,859.00 2,767,683.00 9 Jawa Barat 684,429.00 5,594,879.00 41,254,627.00 10 Jawa Tengah 2,052,062.00 4,199,066.00 30,866,635.00 11 Jawa Timur 1,948,772.00 5,992,336.00 33,052,894.00 12 Kalimantan Barat 186,984.00 882,004.00 4,393,005.00 13 Kalimantan Selatan 87,419.00 424,867.00 3,591,262.00 14 Kalimantan Tengah 52,541.00 266,628.00 2,318,821.00 15 Kalimantan Timur 253,061.00 755,069.00 2,795,842.00 16 Kalimantan Utara 40,607.00 111,647.00 539,985.00 Jumlah Jiwa Terpapar berdasarkan Kajian Risiko Bencana Multi No Provinsi Ancaman Rendah Sedang Tinggi 17 Kepulauan Bangka Belitung 26,484.00 145,473.00 1,283,528.00 18 Kepulauan Riau 113,973.00 276,579.00 1,660,604.00 19 Lampung 175,300.00 1,248,970.00 7,427,296.00 20 Maluku 74,037.00 459,281.00 1,342,188.00 21 Maluku Utara 58,963.00 299,350.00 957,419.00 22 Nusa Tenggara Barat 55,660.00 1,111,670.00 4,222,320.00 23 Nusa Tenggara Timur 118,429.00 1,238,492.00 4,095,626.00 24 Papua 24,015.00 299,642.00 3,866,592.00');
