INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4212, 'perban-5-2025', 17, 'lampiran', 'Lampiran hal. 8', NULL, 8, '25 Papua Barat 51,939.00 133,654.00 964,488.00 26 Riau 207,789.00 1,337,804.00 4,665,166.00 27 Sulawesi Barat 80,282.00 473,693.00 882,348.00 28 Sulawesi Selatan 583,483.00 1,104,381.00 7,275,092.00 29 Sulawesi Tengah 101,145.00 527,781.00 2,403,609.00 30 Sulawesi Tenggara 300,632.00 872,751.00 1,443,847.00 31 Sulawesi Utara 51,146.00 549,051.00 2,074,134.00 32 Sumatera Barat 28,561.00 432,035.00 4,964,114.00 33 Sumatera Selatan 45,645.00 976,636.00 7,418,825.00 34 Sumatera Utara 900,609.00 2,487,082.00 11,770,875.00 Sumber: Buku Risiko Bencana Indonesia, 2023 Selanjutnya, berdasarkan kajian potensi kerugian ekonomi, total potensi kerugian ekonomi berdasarkan risiko bencana multi ancaman kelas sedang adalah sebanyak Rp315.780.125.000.000,00. dan kelas tinggi Rp1.409.941.193.000.000,00. Namun demikian, informasi mengenai sektor-sektor yang bertanggung jawab pada angka-angka tersebut perlu untuk disampaikan lebih lanjut untuk menjadi acuan dalam pemberian fokus, dalam hal ini menjadi sasaran/target dari program. Tabel 1.3. memperlihatkan hasil kajian kerugian fisik dan ekonomi secara lebih rinci untuk masing-masing provinsi.');
