INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4305, 'perban-5-2025', 110, 'lampiran', 'Lampiran hal. 56', NULL, 56, 'b. a Faktor Keberhasilan dan Penghambat Kinerja Program/Kegiatan n Faktor-faktor keberhasilan dalam pencapaian Renstra BNPB 2020-2024 sebagai R berikut.
1) e Komitmen Pemerintah terhadap penanggulangan bencana. aKomitmen Pemerintah terhadap Penanggulangan Bencana (PB) merupakan lfaktor pendukung utama lahirnya berbagai kebijakan dan program selama iperiode pembuatan Renstra, serta mempengaruhi budaya kerja untuk smendukung kesiapsiagaan dan mitigasi bencana yang lebih baik. Sosialisasi dan apelatihan yang dilakukan di Kalimantan Tengah merupakan pembelajaran yang sbaik untuk membuka pola pikir melalui materi, panduan, dan pedoman dalam imengenali tipe ancaman bencana dan bagaimana menanggulanginya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4305, 'b. a Faktor Keberhasilan dan Penghambat Kinerja Program/Kegiatan n Faktor-faktor keberhasilan dalam pencapaian Renstra BNPB 2020-2024 sebagai R berikut.
1) e Komitmen Pemerintah terhadap penanggulangan bencana. aKomitmen Pemerintah terhadap Penanggulangan Bencana (PB) merupakan lfaktor pendukung utama lahirnya berbagai kebijakan dan program selama iperiode pembuatan Renstra, serta mempengaruhi budaya kerja untuk smendukung kesiapsiagaan dan mitigasi bencana yang lebih baik. Sosialisasi dan apelatihan yang dilakukan di Kalimantan Tengah merupakan pembelajaran yang sbaik untuk membuka pola pikir melalui materi, panduan, dan pedoman dalam imengenali tipe ancaman bencana dan bagaimana menanggulanginya.', 'Lampiran hal. 56', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4306, 'perban-5-2025', 111, 'lampiran', 'Lampiran hal. 56', NULL, 56, 'AKeberhasilan upaya tersebut dapat berkontribusi dalam menurunkan indeks nrisiko bencana dari 144 menjadi 123. Profil risiko bencana di daerah yang cenderung menurun salah satunya karena komitmen pemerintah dalam g merealisasikan target yang telah direncanakan, terutama di daerah yang rawan gbencana. a 2) rKetersediaan sumber daya manusia. aSumber daya manusia merupakan faktor pendukung berjalannya seluruh program atau kegiatan yang dicanangkan dalam Renstra. Sehingga penting n adanya dukungan dari kementerian atau lembaga terkait dan dukungan dari TLembaga Pendidikan dan Pelatihan (Lemdiklat) dengan memasukkan program a h u n 2 pelatihan PB mengenai kemampuan perencanaan, alokasi, dan pemeliharaan sarana dan prasarana kesiapsiagaan dan tanggap bencana sebagai program tahunan yang terencana. Pendukung lainnya adalah tersedianya anggaran yang responsif terhadap tiga fase bencana. Jika alokasi pendanaan cukup berimbang, maka kegiatan dan program prabencana dapat diperbanyak dan diperkuat untuk meminimalkan risiko bencana, termasuk korban jiwa dan harta benda.
Selain itu, adanya infrastruktur yang memadai menjadi faktor penting dalam penanggulangan bencana. Pembangunan infrastruktur penanggulangan bencana belum merata di seluruh wilayah Indonesia sehingga perlu adanya prioritas atau afirmasi di periode berikutnya.
3) Kerja sama dan koordinasi antar lembaga mitra pembangunan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4306, 'AKeberhasilan upaya tersebut dapat berkontribusi dalam menurunkan indeks nrisiko bencana dari 144 menjadi 123. Profil risiko bencana di daerah yang cenderung menurun salah satunya karena komitmen pemerintah dalam g merealisasikan target yang telah direncanakan, terutama di daerah yang rawan gbencana. a 2) rKetersediaan sumber daya manusia. aSumber daya manusia merupakan faktor pendukung berjalannya seluruh program atau kegiatan yang dicanangkan dalam Renstra. Sehingga penting n adanya dukungan dari kementerian atau lembaga terkait dan dukungan dari TLembaga Pendidikan dan Pelatihan (Lemdiklat) dengan memasukkan program a h u n 2 pelatihan PB mengenai kemampuan perencanaan, alokasi, dan pemeliharaan sarana dan prasarana kesiapsiagaan dan tanggap bencana sebagai program tahunan yang terencana. Pendukung lainnya adalah tersedianya anggaran yang responsif terhadap tiga fase bencana. Jika alokasi pendanaan cukup berimbang, maka kegiatan dan program prabencana dapat diperbanyak dan diperkuat untuk meminimalkan risiko bencana, termasuk korban jiwa dan harta benda.
Selain itu, adanya infrastruktur yang memadai menjadi faktor penting dalam penanggulangan bencana. Pembangunan infrastruktur penanggulangan bencana belum merata di seluruh wilayah Indonesia sehingga perlu adanya prioritas atau afirmasi di periode berikutnya.
3) Kerja sama dan koordinasi antar lembaga mitra pembangunan.', 'Lampiran hal. 56', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4307, 'perban-5-2025', 112, 'lampiran', 'Lampiran hal. 57', NULL, 57, 'Kerja sama dan koordinasi antar lembaga mitra pembangunan merupakan faktor pendukung untuk mengisi kesenjangan fiskal guna meningkatkan efektivitas penanggulangan bencana. Selama periode Renstra Tahun 2020-2024 tercatat sebanyak 51 kegiatan dari sekitar enam donor. Dukungan mitra pembangunan ini terdiri dari dua bentuk yakni in-kind berupa alat, sarana dan prasarana, serta dana untuk mendukung pelaksanaan kegiatan serta pendampingan teknis atau tenaga ahli.
4) Peningkatan sistem peringatan dini.
Terdapat peningkatan yang signifikan dalam sistem peringatan dini di berbagai daerah, yang memperkuat kesiapsiagaan terhadap bencana. Ini mencerminkan upaya BNPB dalam mengimplementasikan teknologi dan mekanisme peringatan yang lebih efektif.
5) Peningkatan kapasitas penanggulangan bencana.
Program pendidikan dan pelatihan untuk pemangku kepentingan di tingkat daerah telah dilaksanakan dengan konsisten. Ini meningkatkan kesiapan daerah dalam menghadapi situasi darurat.
6) Penurunan angka kematian akibat bencana.
Rata-rata angka kematian akibat bencana menunjukkan penurunan signifikan selama periode Renstra, yang mencerminkan efektivitas dalam penanganan darurat bencana.
7) Pemulihan pasca bencana.
Capaian dalam pemulihan sarana dan prasarana sosial ekonomi di daerah terdampak bencana telah memenuhi target, yang menunjukkan keberhasilan dalam rehabilitasi dan rekonstruksi pasca bencana.
8) Ketersediaan sumber daya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4307, 'Kerja sama dan koordinasi antar lembaga mitra pembangunan merupakan faktor pendukung untuk mengisi kesenjangan fiskal guna meningkatkan efektivitas penanggulangan bencana. Selama periode Renstra Tahun 2020-2024 tercatat sebanyak 51 kegiatan dari sekitar enam donor. Dukungan mitra pembangunan ini terdiri dari dua bentuk yakni in-kind berupa alat, sarana dan prasarana, serta dana untuk mendukung pelaksanaan kegiatan serta pendampingan teknis atau tenaga ahli.
4) Peningkatan sistem peringatan dini.
Terdapat peningkatan yang signifikan dalam sistem peringatan dini di berbagai daerah, yang memperkuat kesiapsiagaan terhadap bencana. Ini mencerminkan upaya BNPB dalam mengimplementasikan teknologi dan mekanisme peringatan yang lebih efektif.
5) Peningkatan kapasitas penanggulangan bencana.
Program pendidikan dan pelatihan untuk pemangku kepentingan di tingkat daerah telah dilaksanakan dengan konsisten. Ini meningkatkan kesiapan daerah dalam menghadapi situasi darurat.
6) Penurunan angka kematian akibat bencana.
Rata-rata angka kematian akibat bencana menunjukkan penurunan signifikan selama periode Renstra, yang mencerminkan efektivitas dalam penanganan darurat bencana.
7) Pemulihan pasca bencana.
Capaian dalam pemulihan sarana dan prasarana sosial ekonomi di daerah terdampak bencana telah memenuhi target, yang menunjukkan keberhasilan dalam rehabilitasi dan rekonstruksi pasca bencana.
8) Ketersediaan sumber daya.', 'Lampiran hal. 57', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4308, 'perban-5-2025', 113, 'lampiran', 'Lampiran hal. 57', NULL, 57, 'Meskipun terdapat tantangan dalam beberapa daerah, beberapa wilayah telah mencapai tingkat kesiapan sumber daya yang memadai untuk mendukung penanganan darurat.
Adapun faktor-faktor penghambat dalam pelaksanaan Renstra BNPB 2020-2024 diantaranya:
1) Komitmen Pemerintah terhadap penanggulangan bencana.
Adanya pola pikir pimpinan aparatur dan tokoh masyarakat yang belum sepenuhnya sadar tentang pentingnya pemahaman terhadap risiko bencana menjadi faktor penghambat upaya kesiapsiagaan dan perencanaan PB yang lebih baik. Sebagai contoh, wilayah Papua Barat berhasil menurunkan risiko di daerah rawan bencana hingga mencapai angka kematian nol. Selain itu, pemimpin juga mampu mengubah paradigma dan pola pikir bahwa penanggulangan bencana adalah tanggung jawab bersama.
2) Ketersediaan sumber daya.
Infrastruktur yang memadai menjadi faktor penting dalam penanggulangan bencana. Pembangunan infrastruktur penanggulangan bencana belum merata di seluruh wilayah Indonesia sehingga perlu adanya prioritas di periode berikutnya.
3) Akurasi dan pemutakhiran data dan informasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4308, 'Meskipun terdapat tantangan dalam beberapa daerah, beberapa wilayah telah mencapai tingkat kesiapan sumber daya yang memadai untuk mendukung penanganan darurat.
Adapun faktor-faktor penghambat dalam pelaksanaan Renstra BNPB 2020-2024 diantaranya:
1) Komitmen Pemerintah terhadap penanggulangan bencana.
Adanya pola pikir pimpinan aparatur dan tokoh masyarakat yang belum sepenuhnya sadar tentang pentingnya pemahaman terhadap risiko bencana menjadi faktor penghambat upaya kesiapsiagaan dan perencanaan PB yang lebih baik. Sebagai contoh, wilayah Papua Barat berhasil menurunkan risiko di daerah rawan bencana hingga mencapai angka kematian nol. Selain itu, pemimpin juga mampu mengubah paradigma dan pola pikir bahwa penanggulangan bencana adalah tanggung jawab bersama.
2) Ketersediaan sumber daya.
Infrastruktur yang memadai menjadi faktor penting dalam penanggulangan bencana. Pembangunan infrastruktur penanggulangan bencana belum merata di seluruh wilayah Indonesia sehingga perlu adanya prioritas di periode berikutnya.
3) Akurasi dan pemutakhiran data dan informasi.', 'Lampiran hal. 57', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4309, 'perban-5-2025', 114, 'lampiran', 'Lampiran hal. 58', NULL, 58, 'Data yang kurang akurat dan update menghambat proses pengambilan keputusan yang tepat dalam penanggulangan bencana, utamanya saat darurat bencana. Hambatan tersebut masih terus terjadi di periode Renstra Tahun 2020- 2024 karena berkaitan dengan faktor SDM dan sistem monev di BNPB dan instansi terkait PB. Perbaikan terhadap sistem pemantauan dan evaluasi yang lebih baik, SPBE, dan Satu Data Indonesia (SDI) akan berkontribusi terhadap akurasi dan pemutakhiran data dan informasi yang lebih baik pula.
4) Keterbatasan dana.
Akses terhadap dana yang memadai masih menjadi kendala di banyak daerah, yang menghambat pelaksanaan program dan kesiapan daerah dalam menghadapi bencana.
5) Ketidakmerataan kesiapan fasilitas kesehatan.
Kesiapan fasilitas kesehatan belum merata di seluruh daerah, yang menyebabkan perbedaan dalam respons terhadap bencana dan pemulihan pasca bencana.
6) Kekurangan SDM terlatih.
Kekurangan tenaga kerja yang terampil menjadi hambatan dalam pelaksanaan program penanggulangan bencana di berbagai daerah.
7) Variasi dalam pelatihan dan simulasi.
Pelatihan dan simulasi bencana tidak dilakukan secara konsisten di semua daerah, yang mengakibatkan kesiapsiagaan yang tidak merata.
8) Koordinasi dan kolaborasi yang kurang.
Tantangan dalam koordinasi antara BNPB, BPBD, dan lembaga lainnya menghambat efektivitas pelaksanaan program, terutama dalam distribusi sumber daya dan penanganan darurat.
9) Akurasi data dan informasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4309, 'Data yang kurang akurat dan update menghambat proses pengambilan keputusan yang tepat dalam penanggulangan bencana, utamanya saat darurat bencana. Hambatan tersebut masih terus terjadi di periode Renstra Tahun 2020- 2024 karena berkaitan dengan faktor SDM dan sistem monev di BNPB dan instansi terkait PB. Perbaikan terhadap sistem pemantauan dan evaluasi yang lebih baik, SPBE, dan Satu Data Indonesia (SDI) akan berkontribusi terhadap akurasi dan pemutakhiran data dan informasi yang lebih baik pula.
4) Keterbatasan dana.
Akses terhadap dana yang memadai masih menjadi kendala di banyak daerah, yang menghambat pelaksanaan program dan kesiapan daerah dalam menghadapi bencana.
5) Ketidakmerataan kesiapan fasilitas kesehatan.
Kesiapan fasilitas kesehatan belum merata di seluruh daerah, yang menyebabkan perbedaan dalam respons terhadap bencana dan pemulihan pasca bencana.
6) Kekurangan SDM terlatih.
Kekurangan tenaga kerja yang terampil menjadi hambatan dalam pelaksanaan program penanggulangan bencana di berbagai daerah.
7) Variasi dalam pelatihan dan simulasi.
Pelatihan dan simulasi bencana tidak dilakukan secara konsisten di semua daerah, yang mengakibatkan kesiapsiagaan yang tidak merata.
8) Koordinasi dan kolaborasi yang kurang.
Tantangan dalam koordinasi antara BNPB, BPBD, dan lembaga lainnya menghambat efektivitas pelaksanaan program, terutama dalam distribusi sumber daya dan penanganan darurat.
9) Akurasi data dan informasi.', 'Lampiran hal. 58', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4310, 'perban-5-2025', 115, 'lampiran', 'Lampiran hal. 58', NULL, 58, 'Keterbatasan dalam mendapatkan data dan informasi yang akurat menghambat proses perencanaan dan pengambilan keputusan yang efektif.
1.1.5.2. Analisis Bidang Pembangunan
a. Keselarasan antara Renstra BNPB 2020-2024 dan RPJMN 2020-2024 Sesuai mandat RPJMN 2020-2024, BNPB diharapkan fokus pada 19 program/kegiatan/ proyek prioritas nasional yang kemudian dikelola oleh unit-unit kerja setingkat eselon 2 sebagai penanggung jawab kegiatan yang mendukung program. Dalam upaya menyelaraskan arah kebijakan nasional dengan program BNPB, penting dipahami bagaimana program-program diintegrasikan dalam strategi pelaksanaan kegiatan.
Analisis terhadap keterkaitan antara RPJMN dan Renstra BNPB 2020-2024 menunjukkan bahwa BNPB telah berupaya untuk mengintegrasikan berbagai program prioritas nasional ke dalam Renstra BNPB. Hal ini menunjukkan bahwa BNPB telah menempatkan program-program prioritas nasional sebagai bagian integral dari strategi penanggulangan bencana yang dilaksanakan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4310, 'Keterbatasan dalam mendapatkan data dan informasi yang akurat menghambat proses perencanaan dan pengambilan keputusan yang efektif.
1.1.5.2. Analisis Bidang Pembangunan
a. Keselarasan antara Renstra BNPB 2020-2024 dan RPJMN 2020-2024 Sesuai mandat RPJMN 2020-2024, BNPB diharapkan fokus pada 19 program/kegiatan/ proyek prioritas nasional yang kemudian dikelola oleh unit-unit kerja setingkat eselon 2 sebagai penanggung jawab kegiatan yang mendukung program. Dalam upaya menyelaraskan arah kebijakan nasional dengan program BNPB, penting dipahami bagaimana program-program diintegrasikan dalam strategi pelaksanaan kegiatan.
Analisis terhadap keterkaitan antara RPJMN dan Renstra BNPB 2020-2024 menunjukkan bahwa BNPB telah berupaya untuk mengintegrasikan berbagai program prioritas nasional ke dalam Renstra BNPB. Hal ini menunjukkan bahwa BNPB telah menempatkan program-program prioritas nasional sebagai bagian integral dari strategi penanggulangan bencana yang dilaksanakan.', 'Lampiran hal. 58', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4311, 'perban-5-2025', 116, 'lampiran', 'Lampiran hal. 59', NULL, 59, 'Tabel 1.11. Perbandingan antara RPJMN 2020-2024 dengan Renstra BNPB 2020- 2024 Identifikasi pola Kesesuaian dengan No kesesuaian dan unit Catatan RPJMN pengampu 1 Program dan kegiatan Program ini secara Tahun 2023, terjadi prasarana pengelolaan konsisten ada dalam Renja penurunan target output. Pada database. BNPB dari tahun 2020 dokumen Renja 2024 program Pusat Data dan hingga 2024, tetap dilanjutkan meski terjadi Informasi (Pusdatin) menunjukkan keselarasan perubahan nomenklatur dan yang baik dengan RPJMN menjadi RO “Pengelolaan Data dan Penyajian Informasi Kebencanaan”.
2 Rencana Program ini tercakup Penyusunan RPKB masuk penanggulangan dalam RPJMN dan dalam SPM sesuai regulasi kedaruratan bencana dilaksanakan oleh BNPB terbaru Permendagri Nomor dan penilaian secara konsisten dari 2020 101 Tahun 2018 menjadi ketangguhan hingga 2024 kewenangan daerah untuk desa/kelurahan. menyelenggarakan.
Direktorat Kesiapsiagaan 3 Budaya sadar bencana Program ini tercakup Penyesuaian ini penting untuk Pusat Data dan dalam RPJMN dan menjaga efektivitas Informasi (Pusdatin) Renstra, namun ada penyampaian informasi perubahan mekanisme kepada masyarakat, namun pelaksanaan dari perlu dipastikan bahwa sandiwara radio ke perubahan ini tidak medium lain ke pagelaran mengurangi dampak yang seni tradisional, yang diharapkan disesuaikan dengan kebutuhan lapangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4311, 'Tabel 1.11. Perbandingan antara RPJMN 2020-2024 dengan Renstra BNPB 2020- 2024 Identifikasi pola Kesesuaian dengan No kesesuaian dan unit Catatan RPJMN pengampu 1 Program dan kegiatan Program ini secara Tahun 2023, terjadi prasarana pengelolaan konsisten ada dalam Renja penurunan target output. Pada database. BNPB dari tahun 2020 dokumen Renja 2024 program Pusat Data dan hingga 2024, tetap dilanjutkan meski terjadi Informasi (Pusdatin) menunjukkan keselarasan perubahan nomenklatur dan yang baik dengan RPJMN menjadi RO “Pengelolaan Data dan Penyajian Informasi Kebencanaan”.
2 Rencana Program ini tercakup Penyusunan RPKB masuk penanggulangan dalam RPJMN dan dalam SPM sesuai regulasi kedaruratan bencana dilaksanakan oleh BNPB terbaru Permendagri Nomor dan penilaian secara konsisten dari 2020 101 Tahun 2018 menjadi ketangguhan hingga 2024 kewenangan daerah untuk desa/kelurahan. menyelenggarakan.
Direktorat Kesiapsiagaan 3 Budaya sadar bencana Program ini tercakup Penyesuaian ini penting untuk Pusat Data dan dalam RPJMN dan menjaga efektivitas Informasi (Pusdatin) Renstra, namun ada penyampaian informasi perubahan mekanisme kepada masyarakat, namun pelaksanaan dari perlu dipastikan bahwa sandiwara radio ke perubahan ini tidak medium lain ke pagelaran mengurangi dampak yang seni tradisional, yang diharapkan disesuaikan dengan kebutuhan lapangan.', 'Lampiran hal. 59', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4312, 'perban-5-2025', 117, 'lampiran', 'Lampiran hal. 59', NULL, 59, '4 Kajian teknis, riset dan Program ini selaras Perubahan nomenklatur ini dukungan teknis dengan RPJMN dan harus diikuti dengan pengembangan strategi Renstra, dengan beberapa penyesuaian dalam pelaporan PB. perubahan dalam dan evaluasi untuk Direktorat nomenklatur kegiatan memastikan keselarasan Pengembangan Strategi sejak tahun 2023 dengan tujuan strategis yang Penanggulangan lebih luas Bencana 5 Pendidikan dan Program ini konsisten Ada penyesuaian terkait Pelatihan Teknis dan dengan RPJMN dan kebijakan Redesain Sistem Simulasi PB di Daerah. dilaksanakan dalam Renja Perencanaan yang Pusdiklat BNPB setiap tahun mempengaruhi pelaksanaan program ini, namun tetap penting untuk memastikan bahwa perubahan tersebut tidak menghambat pencapaian target 6 Sistem dan dukungan Program ini selaras Adanya kebijakan redesain teknis penanggulangan dengan RPJMN dan sistem perencanaan bencana. terdapat dalam Renstra memberikan tantangan dalam Direktorat Sistem dan Renja BNPB. pelaksanaan program ini, Penanggulangan namun ini juga membuka Bencana peluang untuk penguatan dan inovasi dalam manajemen bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4312, '4 Kajian teknis, riset dan Program ini selaras Perubahan nomenklatur ini dukungan teknis dengan RPJMN dan harus diikuti dengan pengembangan strategi Renstra, dengan beberapa penyesuaian dalam pelaporan PB. perubahan dalam dan evaluasi untuk Direktorat nomenklatur kegiatan memastikan keselarasan Pengembangan Strategi sejak tahun 2023 dengan tujuan strategis yang Penanggulangan lebih luas Bencana 5 Pendidikan dan Program ini konsisten Ada penyesuaian terkait Pelatihan Teknis dan dengan RPJMN dan kebijakan Redesain Sistem Simulasi PB di Daerah. dilaksanakan dalam Renja Perencanaan yang Pusdiklat BNPB setiap tahun mempengaruhi pelaksanaan program ini, namun tetap penting untuk memastikan bahwa perubahan tersebut tidak menghambat pencapaian target 6 Sistem dan dukungan Program ini selaras Adanya kebijakan redesain teknis penanggulangan dengan RPJMN dan sistem perencanaan bencana. terdapat dalam Renstra memberikan tantangan dalam Direktorat Sistem dan Renja BNPB. pelaksanaan program ini, Penanggulangan namun ini juga membuka Bencana peluang untuk penguatan dan inovasi dalam manajemen bencana.', 'Lampiran hal. 59', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4313, 'perban-5-2025', 118, 'lampiran', 'Lampiran hal. 60', NULL, 60, 'Identifikasi pola Kesesuaian dengan No kesesuaian dan unit Catatan RPJMN pengampu 7 Pemenuhan Logistik dan Selaras dengan RPJMN Adanya kebijakan Redesain Peralatan PB. dan dilaksanakan dalam Sistem Perencanaan dan Direktorat Pengelolaan Renstra dan Renja BNPB Penganggaran (RSPP) sehingga Logistik dan Peralatan terdapat perbedaan satuan PB yang seharusnya kab/kota menjadi paket. Kebijakan redesain sistem perencanaan mempengaruhi pelaksanaan program ini, yang memerlukan perhatian lebih untuk menjaga efektivitas logistik dan peralatan dalam situasi darurat.
8 Distribusi Logistik dan Program ini konsisten Adanya kebijakan Redesain Peralatan PB. dalam RPJMN dan Renja Sistem Perencanaan dan Direktorat Optimasi BNPB setiap tahun. Penganggaran (RSPP) sehingga Jaringan Logistik dan terdapat perbedaan satuan Peralatan yang seharusnya kegiatan menjadi paket. Redesain sistem perencanaan yang diterapkan perlu dipantau secara ketat untuk memastikan bahwa distribusi logistik dan peralatan tetap cepat dan efektif, terutama dalam situasi darurat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4313, 'Identifikasi pola Kesesuaian dengan No kesesuaian dan unit Catatan RPJMN pengampu 7 Pemenuhan Logistik dan Selaras dengan RPJMN Adanya kebijakan Redesain Peralatan PB. dan dilaksanakan dalam Sistem Perencanaan dan Direktorat Pengelolaan Renstra dan Renja BNPB Penganggaran (RSPP) sehingga Logistik dan Peralatan terdapat perbedaan satuan PB yang seharusnya kab/kota menjadi paket. Kebijakan redesain sistem perencanaan mempengaruhi pelaksanaan program ini, yang memerlukan perhatian lebih untuk menjaga efektivitas logistik dan peralatan dalam situasi darurat.
8 Distribusi Logistik dan Program ini konsisten Adanya kebijakan Redesain Peralatan PB. dalam RPJMN dan Renja Sistem Perencanaan dan Direktorat Optimasi BNPB setiap tahun. Penganggaran (RSPP) sehingga Jaringan Logistik dan terdapat perbedaan satuan Peralatan yang seharusnya kegiatan menjadi paket. Redesain sistem perencanaan yang diterapkan perlu dipantau secara ketat untuk memastikan bahwa distribusi logistik dan peralatan tetap cepat dan efektif, terutama dalam situasi darurat.', 'Lampiran hal. 60', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4314, 'perban-5-2025', 119, 'lampiran', 'Lampiran hal. 60', NULL, 60, '9 Kajian pemetaan dan Program ini masuk dalam Penyusunan kajian risiko analisis risiko bencana RPJMN dan dilaksanakan bencana yang menjadi bagian Direktorat Pemetaan sesuai dengan Renstra dari SPM memerlukan Evaluasi Risiko Bencana dan Renja BNPB integrasi data yang lebih baik dan partisipasi aktif dari berbagai pemangku kepentingan untuk memastikan akurasi dan relevansi hasil kajian 10 Pengelola Infrastruktur Program ini selaras Penurunan alokasi anggaran Darurat dengan RPJMN dan dalam Renstra 2023 Direktorat Dukungan dilaksanakan dengan memerlukan strategi baru Infrastruktur Darurat penyesuaian dalam untuk memastikan bahwa alokasi anggaran infrastruktur darurat tetap dapat dikelola secara efektif.
11 Sistem Komando Program ini sesuai dengan Mengingat bahwa satuan Penanganan Darurat RPJMN dan ada dalam kegiatan mengikuti kejadian Bencana dan Renstra BNPB bencana, penting untuk Pengelolaan Dana memiliki fleksibilitas dalam Bantuan Kedaruratan. perencanaan anggaran dan Pusdalops. sumber daya agar dapat menyesuaikan dengan kebutuhan mendesak.
12 Pendampingan Program ini selaras Perubahan nomenklatur Penanganan Korban dan dengan RPJMN dan kegiatan sejak tahun 2023 Pengungsi. dilaksanakan dalam harus diikuti dengan Renstra BNPB. klarifikasi peran dan tanggung Identifikasi pola Kesesuaian dengan No kesesuaian dan unit Catatan RPJMN pengampu Direktorat Fasilitasi jawab untuk menghindari Penanganan Korban dan kebingungan di lapangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4314, '9 Kajian pemetaan dan Program ini masuk dalam Penyusunan kajian risiko analisis risiko bencana RPJMN dan dilaksanakan bencana yang menjadi bagian Direktorat Pemetaan sesuai dengan Renstra dari SPM memerlukan Evaluasi Risiko Bencana dan Renja BNPB integrasi data yang lebih baik dan partisipasi aktif dari berbagai pemangku kepentingan untuk memastikan akurasi dan relevansi hasil kajian 10 Pengelola Infrastruktur Program ini selaras Penurunan alokasi anggaran Darurat dengan RPJMN dan dalam Renstra 2023 Direktorat Dukungan dilaksanakan dengan memerlukan strategi baru Infrastruktur Darurat penyesuaian dalam untuk memastikan bahwa alokasi anggaran infrastruktur darurat tetap dapat dikelola secara efektif.
11 Sistem Komando Program ini sesuai dengan Mengingat bahwa satuan Penanganan Darurat RPJMN dan ada dalam kegiatan mengikuti kejadian Bencana dan Renstra BNPB bencana, penting untuk Pengelolaan Dana memiliki fleksibilitas dalam Bantuan Kedaruratan. perencanaan anggaran dan Pusdalops. sumber daya agar dapat menyesuaikan dengan kebutuhan mendesak.
12 Pendampingan Program ini selaras Perubahan nomenklatur Penanganan Korban dan dengan RPJMN dan kegiatan sejak tahun 2023 Pengungsi. dilaksanakan dalam harus diikuti dengan Renstra BNPB. klarifikasi peran dan tanggung Identifikasi pola Kesesuaian dengan No kesesuaian dan unit Catatan RPJMN pengampu Direktorat Fasilitasi jawab untuk menghindari Penanganan Korban dan kebingungan di lapangan.', 'Lampiran hal. 60', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4315, 'perban-5-2025', 120, 'lampiran', 'Lampiran hal. 61', NULL, 61, 'Pengungsi 13 Layanan Pendampingan Program ini sesuai dengan Program ini mengalami Pemulihan RPJMN dan ada dalam penyesuaian nomenklatur Pascabencana Bidang Renstra BNPB sejak 2023, yang memerlukan Fisik. pembaruan dalam Direktorat Pemulihan pelaksanaan dan evaluasi agar dan Peningkatan Fisik tetap sesuai dengan tujuan strategis.
14 Layanan Pemulihan Program ini selaras Penyesuaian ini perlu Pascabencana Bidang dengan RPJMN dan diintegrasikan dengan Pemulihan Sosial, dilaksanakan, meskipun kebijakan lain yang relevan Ekonomi, dan SDA. terjadi perubahan untuk memaksimalkan hasil Direktorat Pemulihan nomenklatur kegiatan. pemulihan pascabencana. dan Peningkatan Fisik 15 Pendampingan Program ini sepenuhnya Konsistensi dalam Pengkajian Kebutuhan sesuai dengan RPJMN dan implementasi dan pelaporan Pascabencana diimplementasikan dalam sangat penting untuk (JITUPASNA). Renstra BNPB tanpa memastikan bahwa kajian Direktorat Perencanaan catatan khusus kebutuhan pascabencana Rehabilitasi dan memberikan hasil yang dapat Rekonstruksi digunakan untuk perencanaan dan alokasi sumber daya yang lebih baik.
16 Sistem Peringatan Dini. Program ini sesuai dengan Redesain sistem perencanaan Direktorat Peringatan RPJMN dan dilaksanakan berdampak pada pelaksanaan Dini setiap tahun. program ini, yang memerlukan pemantauan ketat untuk menjaga efektivitas dan keandalan sistem peringatan dini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4315, 'Pengungsi 13 Layanan Pendampingan Program ini sesuai dengan Program ini mengalami Pemulihan RPJMN dan ada dalam penyesuaian nomenklatur Pascabencana Bidang Renstra BNPB sejak 2023, yang memerlukan Fisik. pembaruan dalam Direktorat Pemulihan pelaksanaan dan evaluasi agar dan Peningkatan Fisik tetap sesuai dengan tujuan strategis.
14 Layanan Pemulihan Program ini selaras Penyesuaian ini perlu Pascabencana Bidang dengan RPJMN dan diintegrasikan dengan Pemulihan Sosial, dilaksanakan, meskipun kebijakan lain yang relevan Ekonomi, dan SDA. terjadi perubahan untuk memaksimalkan hasil Direktorat Pemulihan nomenklatur kegiatan. pemulihan pascabencana. dan Peningkatan Fisik 15 Pendampingan Program ini sepenuhnya Konsistensi dalam Pengkajian Kebutuhan sesuai dengan RPJMN dan implementasi dan pelaporan Pascabencana diimplementasikan dalam sangat penting untuk (JITUPASNA). Renstra BNPB tanpa memastikan bahwa kajian Direktorat Perencanaan catatan khusus kebutuhan pascabencana Rehabilitasi dan memberikan hasil yang dapat Rekonstruksi digunakan untuk perencanaan dan alokasi sumber daya yang lebih baik.
16 Sistem Peringatan Dini. Program ini sesuai dengan Redesain sistem perencanaan Direktorat Peringatan RPJMN dan dilaksanakan berdampak pada pelaksanaan Dini setiap tahun. program ini, yang memerlukan pemantauan ketat untuk menjaga efektivitas dan keandalan sistem peringatan dini.', 'Lampiran hal. 61', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4316, 'perban-5-2025', 121, 'lampiran', 'Lampiran hal. 61', NULL, 61, '17 Desa Tangguh Bencana. Program ini selaras Kesuksesan program ini Direktorat Kesiapsiagaan dengan RPJMN dan sangat bergantung pada diimplementasikan dalam keterlibatan masyarakat dan Renstra BNPB secara dukungan lintas sektor, yang konsisten harus terus diperkuat.
18 Satuan Pendidikan Program ini selaras Peningkatan ini harus diikuti Aman Bencana. dengan RPJMN dan mulai dengan monitoring dan Direktorat Mitigasi tahun 2023 terdapat evaluasi yang lebih intensif Bencana peningkatan dalam untuk memastikan program ini pelaksanaannya. memberikan dampak yang signifikan dalam meningkatkan kesiapsiagaan di lingkungan pendidikan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4316, '17 Desa Tangguh Bencana. Program ini selaras Kesuksesan program ini Direktorat Kesiapsiagaan dengan RPJMN dan sangat bergantung pada diimplementasikan dalam keterlibatan masyarakat dan Renstra BNPB secara dukungan lintas sektor, yang konsisten harus terus diperkuat.
18 Satuan Pendidikan Program ini selaras Peningkatan ini harus diikuti Aman Bencana. dengan RPJMN dan mulai dengan monitoring dan Direktorat Mitigasi tahun 2023 terdapat evaluasi yang lebih intensif Bencana peningkatan dalam untuk memastikan program ini pelaksanaannya. memberikan dampak yang signifikan dalam meningkatkan kesiapsiagaan di lingkungan pendidikan.', 'Lampiran hal. 61', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4317, 'perban-5-2025', 122, 'lampiran', 'Lampiran hal. 61', NULL, 61, 'Sumber: Laporan Evaluasi Akhir Renstra BNPB 2020-2024 Berdasarkan tabel di atas, dari 19 program/kegiatan yang tercantum dalam RPJMN 2020-2024, terdapat lima program/kegiatan yang tidak secara eksplisit dikemukakan dalam Renstra BNPB 2020-2024, yaitu: 1) Prasarana dan Pengelolaan Database; 2) Budaya Sadar Bencana; 3) Kajian Teknis, Riset dan Dukungan Teknis Pengembangan Strategi PB; 4) Sistem dan dukungan teknis sistem penanggulangan bencana; dan 5) Pendamping Pengkajian Kebutuhan Pasca bencana (Jitupasna) dan Rencana Rehabilitasi dan Rekonstruksi Pascabencana. Ketidakhadiran program-program tersebut dalam Renstra memunculkan tantangan dalam pengelolaan data dan informasi, yang merupakan elemen krusial dalam penanggulangan bencana yang efektif. Meskipun demikian, dilaporkan bahwa seluruh program/kegiatan yang tercantum dalam RPJMN tetap dilaksanakan oleh unit-unit kerja terkait yang dicantumkan sebagai bagian dari rencana kerja tahunan (2020-2024).
Secara keseluruhan, implementasi Renstra BNPB 2020-2024 dan sinkronisasinya dengan RPJMN 2020-2024 telah menunjukkan hasil yang baik, namun masih terdapat tantangan yang perlu diatasi untuk mencapai hasil yang lebih optimal.
Penyebab ketidakselarasan antara Renstra BNPB Tahun 2020-2024 dengan RPJMN Tahun 2020-2024, diantaranya disebabkan oleh:
1) Ditetapkannya kebijakan Redesain Sistem Perencanaan dan Penganggaran (RSPP) yang menyebabkan sejumlah satuan target berubah;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4317, 'Sumber: Laporan Evaluasi Akhir Renstra BNPB 2020-2024 Berdasarkan tabel di atas, dari 19 program/kegiatan yang tercantum dalam RPJMN 2020-2024, terdapat lima program/kegiatan yang tidak secara eksplisit dikemukakan dalam Renstra BNPB 2020-2024, yaitu: 1) Prasarana dan Pengelolaan Database; 2) Budaya Sadar Bencana; 3) Kajian Teknis, Riset dan Dukungan Teknis Pengembangan Strategi PB; 4) Sistem dan dukungan teknis sistem penanggulangan bencana; dan 5) Pendamping Pengkajian Kebutuhan Pasca bencana (Jitupasna) dan Rencana Rehabilitasi dan Rekonstruksi Pascabencana. Ketidakhadiran program-program tersebut dalam Renstra memunculkan tantangan dalam pengelolaan data dan informasi, yang merupakan elemen krusial dalam penanggulangan bencana yang efektif. Meskipun demikian, dilaporkan bahwa seluruh program/kegiatan yang tercantum dalam RPJMN tetap dilaksanakan oleh unit-unit kerja terkait yang dicantumkan sebagai bagian dari rencana kerja tahunan (2020-2024).
Secara keseluruhan, implementasi Renstra BNPB 2020-2024 dan sinkronisasinya dengan RPJMN 2020-2024 telah menunjukkan hasil yang baik, namun masih terdapat tantangan yang perlu diatasi untuk mencapai hasil yang lebih optimal.
Penyebab ketidakselarasan antara Renstra BNPB Tahun 2020-2024 dengan RPJMN Tahun 2020-2024, diantaranya disebabkan oleh:
1) Ditetapkannya kebijakan Redesain Sistem Perencanaan dan Penganggaran (RSPP) yang menyebabkan sejumlah satuan target berubah;', 'Lampiran hal. 61', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4318, 'perban-5-2025', 123, 'lampiran', 'Lampiran hal. 62', NULL, 62, '2) Pada kegiatan Budaya Sadar Bencana terdapat perubahan metode, dari yang sebelumnya menggunakan radio, menjadi pagelaran seni tradisional. Hal ini didasari pada pendengar radio yang semakin berkurang sehingga dialihkan agar masyarakat yang mendapat pengetahuan dari Budaya Sadar Bencana menjadi lebih banyak;
3) Pada kegiatan pengelolaan dana bantuan keadaan darurat bencana, jumlah target berubah menyesuaikan pada jumlah kejadian bencana yang terjadi;
4) Adanya kebijakan tentang Standar Pelayanan Minimal (SPM) sehingga beberapa kegiatan tidak dialokasikan lagi di pusat karena sudah menjadi tanggung jawab Pemerintah Daerah; dan 5) Kegiatan Satuan Pendidikan Aman Bencana dialihkan pada Kementerian Pendidikan dan Kebudayaan berdasarkan rapat bersama antara BNPB, Kementerian Keuangan dan Bappenas.
Ketidakselarasan antara RPJMN dan Renstra perlu diantisipasi sejak proses teknokratik dilakukan, mulai dari perumusan sasaran strategis hingga perumusan program dan kegiatan. Meskipun akan terdapat proses pemutakhiran antara dokumen berdasarkan pembelajaran di tengah periode rencana, namun garis besar arah kebijakan tetap perlu sejalan dengan arah kebijakan nasional dalam RPJMN.
Oleh karena itu, koordinasi dan konsolidasi terkait seluruh proses perencanaan, monitoring, dan evaluasi ketercapaian target perlu dilakukan antara Bappenas, BNPB, dan kementerian atau lembaga terkait lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4318, '2) Pada kegiatan Budaya Sadar Bencana terdapat perubahan metode, dari yang sebelumnya menggunakan radio, menjadi pagelaran seni tradisional. Hal ini didasari pada pendengar radio yang semakin berkurang sehingga dialihkan agar masyarakat yang mendapat pengetahuan dari Budaya Sadar Bencana menjadi lebih banyak;
3) Pada kegiatan pengelolaan dana bantuan keadaan darurat bencana, jumlah target berubah menyesuaikan pada jumlah kejadian bencana yang terjadi;
4) Adanya kebijakan tentang Standar Pelayanan Minimal (SPM) sehingga beberapa kegiatan tidak dialokasikan lagi di pusat karena sudah menjadi tanggung jawab Pemerintah Daerah; dan 5) Kegiatan Satuan Pendidikan Aman Bencana dialihkan pada Kementerian Pendidikan dan Kebudayaan berdasarkan rapat bersama antara BNPB, Kementerian Keuangan dan Bappenas.
Ketidakselarasan antara RPJMN dan Renstra perlu diantisipasi sejak proses teknokratik dilakukan, mulai dari perumusan sasaran strategis hingga perumusan program dan kegiatan. Meskipun akan terdapat proses pemutakhiran antara dokumen berdasarkan pembelajaran di tengah periode rencana, namun garis besar arah kebijakan tetap perlu sejalan dengan arah kebijakan nasional dalam RPJMN.
Oleh karena itu, koordinasi dan konsolidasi terkait seluruh proses perencanaan, monitoring, dan evaluasi ketercapaian target perlu dilakukan antara Bappenas, BNPB, dan kementerian atau lembaga terkait lainnya.', 'Lampiran hal. 62', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4319, 'perban-5-2025', 124, 'lampiran', 'Lampiran hal. 62', NULL, 62, 'b. Dampak dan Keberlanjutan Dampak program yang nyata dan berkelanjutan menjadi fokus utama karena akan mempengaruhi perencanaan strategis untuk RPJMN 2025-2029. Hasil evaluasi menunjukkan bahwa meskipun beberapa target jangka pendek tercapai, dampaknya terhadap pengurangan risiko bencana dalam jangka panjang memerlukan penilaian lebih lanjut untuk memastikan efektivitasnya. Beberapa temuan terkait dampak antara lain:
1) Masalah logistik dan penyimpanan seperti bahan makanan yang memiliki tanggal kadaluarsa dan kurangnya fasilitas penyimpanan yang memadai di beberapa daerah;
2) Keterbatasan keberlanjutan program di tingkat lokal akibat anggaran yang terbatas. Ketidakberlanjutan ini menghambat pencapaian dampak jangka panjang yang diperlukan untuk mengurangi risiko bencana secara berkelanjutan;
3) Penguatan kapasitas lokal di tingkat daerah, agar menjadi lebih mandiri dalam penanggulangan bencana, sehingga meningkatkan dampak dari program BNPB.
Dampak ini menjadi lebih berkelanjutan ketika daerah memiliki kapasitas untuk melanjutkan inisiatif penanggulangan bencana tanpa selalu bergantung pada intervensi pusat;
4) Peningkatan infrastruktur dan logistik untuk memaksimalkan dampak.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4319, 'b. Dampak dan Keberlanjutan Dampak program yang nyata dan berkelanjutan menjadi fokus utama karena akan mempengaruhi perencanaan strategis untuk RPJMN 2025-2029. Hasil evaluasi menunjukkan bahwa meskipun beberapa target jangka pendek tercapai, dampaknya terhadap pengurangan risiko bencana dalam jangka panjang memerlukan penilaian lebih lanjut untuk memastikan efektivitasnya. Beberapa temuan terkait dampak antara lain:
1) Masalah logistik dan penyimpanan seperti bahan makanan yang memiliki tanggal kadaluarsa dan kurangnya fasilitas penyimpanan yang memadai di beberapa daerah;
2) Keterbatasan keberlanjutan program di tingkat lokal akibat anggaran yang terbatas. Ketidakberlanjutan ini menghambat pencapaian dampak jangka panjang yang diperlukan untuk mengurangi risiko bencana secara berkelanjutan;
3) Penguatan kapasitas lokal di tingkat daerah, agar menjadi lebih mandiri dalam penanggulangan bencana, sehingga meningkatkan dampak dari program BNPB.
Dampak ini menjadi lebih berkelanjutan ketika daerah memiliki kapasitas untuk melanjutkan inisiatif penanggulangan bencana tanpa selalu bergantung pada intervensi pusat;
4) Peningkatan infrastruktur dan logistik untuk memaksimalkan dampak.', 'Lampiran hal. 62', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4320, 'perban-5-2025', 125, 'lampiran', 'Lampiran hal. 63', NULL, 63, 'Infrastruktur yang memadai dan sistem logistik yang efisien sangat penting untuk memaksimalkan dampak program BNPB. Peningkatan infrastruktur seperti gudang penyimpanan dan sistem distribusi barang bantuan dapat meningkatkan responsivitas program, sehingga dampaknya lebih dirasakan oleh masyarakat terdampak.
Keberlanjutan program dalam RPJMN 2020-2024 memerlukan mekanisme yang kuat untuk memastikan relevansi program dari waktu ke waktu. Kesiapan fasilitas kesehatan yang belum merata menunjukkan bahwa keberlanjutan program masih menjadi tantangan, terutama dalam distribusi sumber daya dan infrastruktur.
Untuk memperkuat keberlanjutan program BNPB, diperlukan strategi yang memastikan relevansi dan distribusi yang merata di seluruh daerah. Peningkatan kapasitas sumber daya dan infrastruktur di daerah-daerah yang masih kurang siap sangat penting untuk mencapai keberlanjutan ini. Beberapa hal yang perlu diperhatikan antara lain:
a. Kebutuhan dan keinginan dalam desain program.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4320, 'Infrastruktur yang memadai dan sistem logistik yang efisien sangat penting untuk memaksimalkan dampak program BNPB. Peningkatan infrastruktur seperti gudang penyimpanan dan sistem distribusi barang bantuan dapat meningkatkan responsivitas program, sehingga dampaknya lebih dirasakan oleh masyarakat terdampak.
Keberlanjutan program dalam RPJMN 2020-2024 memerlukan mekanisme yang kuat untuk memastikan relevansi program dari waktu ke waktu. Kesiapan fasilitas kesehatan yang belum merata menunjukkan bahwa keberlanjutan program masih menjadi tantangan, terutama dalam distribusi sumber daya dan infrastruktur.
Untuk memperkuat keberlanjutan program BNPB, diperlukan strategi yang memastikan relevansi dan distribusi yang merata di seluruh daerah. Peningkatan kapasitas sumber daya dan infrastruktur di daerah-daerah yang masih kurang siap sangat penting untuk mencapai keberlanjutan ini. Beberapa hal yang perlu diperhatikan antara lain:
a. Kebutuhan dan keinginan dalam desain program.', 'Lampiran hal. 63', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4321, 'perban-5-2025', 126, 'lampiran', 'Lampiran hal. 63', NULL, 63, 'Program sering kali dirancang lebih berdasarkan keinginan pusat daripada kebutuhan lokal, yang mengurangi keberlanjutan program. Keterlibatan daerah dalam pengembangan kapasitas juga belum konsisten. Desain program BNPB harus lebih berbasis pada analisis kebutuhan lokal yang akurat, dengan meningkatkan konsistensi keterlibatan daerah dalam program pengembangan kapasitas. Hal ini akan memastikan bahwa program benar-benar sesuai dengan kebutuhan di lapangan dan dapat berkelanjutan. Selain itu, sinkronisasi program dan kegiatan antar unit kerja BNPB serta keselarasan antara Renja, Renstra, dan RPJMN dibutuhkan untuk program dan kegiatan berkelanjutan.
b. Kolaborasi dan pemerataan dalam alokasi sumber daya.
Pemerataan alokasi sumber daya sering kali mengurangi efektivitas program karena kurangnya kolaborasi, sementara kesiapan tim penanggulangan bencana perlu ditingkatkan dengan pelatihan yang relevan dan berkesinambungan. BNPB harus mendorong kolaborasi yang lebih kuat antara pusat dan daerah, serta memastikan pelatihan tim penanggulangan bencana dilakukan secara sistematis dan merata. Ini akan memastikan bahwa sumber daya digunakan lebih efisien dan program dapat mencapai dampak yang lebih besar dan berkelanjutan.
c. Peran BNPB sebagai koordinator dan pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4321, 'Program sering kali dirancang lebih berdasarkan keinginan pusat daripada kebutuhan lokal, yang mengurangi keberlanjutan program. Keterlibatan daerah dalam pengembangan kapasitas juga belum konsisten. Desain program BNPB harus lebih berbasis pada analisis kebutuhan lokal yang akurat, dengan meningkatkan konsistensi keterlibatan daerah dalam program pengembangan kapasitas. Hal ini akan memastikan bahwa program benar-benar sesuai dengan kebutuhan di lapangan dan dapat berkelanjutan. Selain itu, sinkronisasi program dan kegiatan antar unit kerja BNPB serta keselarasan antara Renja, Renstra, dan RPJMN dibutuhkan untuk program dan kegiatan berkelanjutan.
b. Kolaborasi dan pemerataan dalam alokasi sumber daya.
Pemerataan alokasi sumber daya sering kali mengurangi efektivitas program karena kurangnya kolaborasi, sementara kesiapan tim penanggulangan bencana perlu ditingkatkan dengan pelatihan yang relevan dan berkesinambungan. BNPB harus mendorong kolaborasi yang lebih kuat antara pusat dan daerah, serta memastikan pelatihan tim penanggulangan bencana dilakukan secara sistematis dan merata. Ini akan memastikan bahwa sumber daya digunakan lebih efisien dan program dapat mencapai dampak yang lebih besar dan berkelanjutan.
c. Peran BNPB sebagai koordinator dan pelaksana.', 'Lampiran hal. 63', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4322, 'perban-5-2025', 127, 'lampiran', 'Lampiran hal. 63', NULL, 63, 'Ketergantungan pada BNPB sebagai pelaksana dapat mengurangi keberlanjutan program. BNPB dapat mengambil peran lebih sebagai koordinator yang memfasilitasi keterlibatan berbagai pihak, sehingga program dapat dilanjutkan secara mandiri oleh daerah dan lembaga terkait setelah intervensi awal selesai.
Hal ini akan meningkatkan efektivitas dan keberlanjutan program.
d. Target mikro dan parsial yang membatasi keberlanjutan.
Fokus pada target mikro dapat menghambat pencapaian dampak yang lebih signifikan, terutama jika tidak disertai dengan evaluasi yang memadai. BNPB perlu memprioritaskan program dengan dampak mendalam, meskipun mungkin menjangkau lebih sedikit orang, untuk mencapai keberlanjutan yang lebih besar. Evaluasi dan penyesuaian program berdasarkan dampak nyata di lapangan harus menjadi fokus utama.
e. Anggaran terbatas dan dampaknya terhadap keberlanjutan.
Pemotongan anggaran selama pandemi membatasi keberlanjutan program, terutama dalam penyediaan dan pemeliharaan peralatan penanggulangan bencana. Penyesuaian target dan anggaran perlu dilakukan dengan mempertimbangkan keterbatasan anggaran, serta peningkatan efisiensi dalam penggunaan anggaran untuk menjaga keberlanjutan program. Perawatan peralatan yang sudah ada harus menjadi prioritas untuk memastikan kesiapan yang optimal.
f. Penentuan lokus Renstra harus mengacu pada lokus prioritas RPJMN
g. Kolaborasi lintas lembaga untuk keberlanjutan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4322, 'Ketergantungan pada BNPB sebagai pelaksana dapat mengurangi keberlanjutan program. BNPB dapat mengambil peran lebih sebagai koordinator yang memfasilitasi keterlibatan berbagai pihak, sehingga program dapat dilanjutkan secara mandiri oleh daerah dan lembaga terkait setelah intervensi awal selesai.
Hal ini akan meningkatkan efektivitas dan keberlanjutan program.
d. Target mikro dan parsial yang membatasi keberlanjutan.
Fokus pada target mikro dapat menghambat pencapaian dampak yang lebih signifikan, terutama jika tidak disertai dengan evaluasi yang memadai. BNPB perlu memprioritaskan program dengan dampak mendalam, meskipun mungkin menjangkau lebih sedikit orang, untuk mencapai keberlanjutan yang lebih besar. Evaluasi dan penyesuaian program berdasarkan dampak nyata di lapangan harus menjadi fokus utama.
e. Anggaran terbatas dan dampaknya terhadap keberlanjutan.
Pemotongan anggaran selama pandemi membatasi keberlanjutan program, terutama dalam penyediaan dan pemeliharaan peralatan penanggulangan bencana. Penyesuaian target dan anggaran perlu dilakukan dengan mempertimbangkan keterbatasan anggaran, serta peningkatan efisiensi dalam penggunaan anggaran untuk menjaga keberlanjutan program. Perawatan peralatan yang sudah ada harus menjadi prioritas untuk memastikan kesiapan yang optimal.
f. Penentuan lokus Renstra harus mengacu pada lokus prioritas RPJMN
g. Kolaborasi lintas lembaga untuk keberlanjutan.', 'Lampiran hal. 63', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4323, 'perban-5-2025', 128, 'lampiran', 'Lampiran hal. 64', NULL, 64, 'Kolaborasi lintas lembaga diperlukan untuk memperkecil gap capaian Renstra BNPB, serta untuk memastikan kesiapan yang merata di seluruh wilayah. BNPB harus terus mendorong sinergi antara berbagai lembaga dan daerah untuk memastikan keberlanjutan program. Ini termasuk kolaborasi dalam pengembangan dan pemeliharaan sistem peringatan dini dan infrastruktur kebencanaan.
h. Monitoring dan evaluasi berkelanjutan.
Monitoring dan evaluasi berkelanjutan penting untuk memastikan program tetap relevan dan bermanfaat, serta untuk menilai kesiapan fasilitas kesehatan di seluruh daerah. BNPB perlu mengimplementasikan mekanisme monitoring dan evaluasi yang berkelanjutan, dengan fokus pada peningkatan kesiapan fasilitas dan kapasitas di seluruh daerah. Ini akan memastikan bahwa program BNPB dapat terus berkembang dan beradaptasi dengan kebutuhan masa depan.
i. Keselarasan kebijakan antara Renstra BNPB, RPJMN, dan RPJMD.
Keselarasan kebijakan antara Renstra BNPB, RPJMN, dan RPJMD harus dijaga untuk keberlanjutan program. BNPB harus memastikan bahwa semua kebijakan dan program dirancang dan diimplementasikan secara konsisten di semua level pemerintahan, dengan memperhatikan masukan dari daerah dan pemangku kepentingan lainnya, serta dengan fokus pada peningkatan kapasitas lokal.
1.1.5.3. Rekomendasi Berdasarkan hasil evaluasi Renstra BNPB 2020-2024, terdapat beberapa aspek yang perlu dioptimalkan guna mendukung keberlangsungan kinerja BNPB pada periode renstra selanjutnya, di antaranya:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4323, 'Kolaborasi lintas lembaga diperlukan untuk memperkecil gap capaian Renstra BNPB, serta untuk memastikan kesiapan yang merata di seluruh wilayah. BNPB harus terus mendorong sinergi antara berbagai lembaga dan daerah untuk memastikan keberlanjutan program. Ini termasuk kolaborasi dalam pengembangan dan pemeliharaan sistem peringatan dini dan infrastruktur kebencanaan.
h. Monitoring dan evaluasi berkelanjutan.
Monitoring dan evaluasi berkelanjutan penting untuk memastikan program tetap relevan dan bermanfaat, serta untuk menilai kesiapan fasilitas kesehatan di seluruh daerah. BNPB perlu mengimplementasikan mekanisme monitoring dan evaluasi yang berkelanjutan, dengan fokus pada peningkatan kesiapan fasilitas dan kapasitas di seluruh daerah. Ini akan memastikan bahwa program BNPB dapat terus berkembang dan beradaptasi dengan kebutuhan masa depan.
i. Keselarasan kebijakan antara Renstra BNPB, RPJMN, dan RPJMD.
Keselarasan kebijakan antara Renstra BNPB, RPJMN, dan RPJMD harus dijaga untuk keberlanjutan program. BNPB harus memastikan bahwa semua kebijakan dan program dirancang dan diimplementasikan secara konsisten di semua level pemerintahan, dengan memperhatikan masukan dari daerah dan pemangku kepentingan lainnya, serta dengan fokus pada peningkatan kapasitas lokal.
1.1.5.3. Rekomendasi Berdasarkan hasil evaluasi Renstra BNPB 2020-2024, terdapat beberapa aspek yang perlu dioptimalkan guna mendukung keberlangsungan kinerja BNPB pada periode renstra selanjutnya, di antaranya:', 'Lampiran hal. 64', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4324, 'perban-5-2025', 129, 'lampiran', 'Lampiran hal. 64', NULL, 64, 'a. Penguatan kepemimpinan pusat dan daerah, perlu didukung kebijakan yang kuat untuk mendukung pelaksanaan Renstra;
b. Perbaikan kualitas knowledge management melalui pembelajaran dari mitra pembangunan, serta perbaikan data dan informasi yang lebih baik;
c. Pengembangan sistem monitoring dan evaluasi, baik dari sisi administrasi maupun dari aspek tugas dan fungsi unit-unit kerja di BNPB dalam rangka penanggulangan bencana;
d. Penyelarasan mandat, kewenangan, proses bisnis, dan restrukturisasi organisasi agar lebih efektif dan efisien dalam menjalankan tugasnya;
e. Sinkronisasi antara Rencana Strategis sebagai dokumen perencanaan pembangunan dengan Rencana Nasional Penanggulangan Bencana serta Rencana Kerja Tahunan;
f. Transparansi, akuntabilitas, dan inklusivitas proses untuk mendorong partisipasi multipihak dan memperhatikan pengarusutamaan gender;
g. Penguatan sistem peringatan dini dengan mengadopsi teknologi canggih dan pelatihan rutin untuk meningkatkan kesiapsiagaan masyarakat darurat bencana;
h. Peningkatan koordinasi dengan memperkuat sinergi antara BNPB, kementerian, lembaga, dan instansi di daerah untuk penanganan darurat yang lebih cepat dan efektif;
i. Pengembangan kapasitas daerah dengan meningkatkan pelatihan dan distribusi sumber daya yang lebih merata untuk daerah berisiko tinggi;
j. Reformasi Birokrasi dengan fokus pada peningkatan efisiensi, transparasi, dan akuntabilitas dalam tata kelola BNPB melalui reformasi birokrasi internal;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4324, 'a. Penguatan kepemimpinan pusat dan daerah, perlu didukung kebijakan yang kuat untuk mendukung pelaksanaan Renstra;
b. Perbaikan kualitas knowledge management melalui pembelajaran dari mitra pembangunan, serta perbaikan data dan informasi yang lebih baik;
c. Pengembangan sistem monitoring dan evaluasi, baik dari sisi administrasi maupun dari aspek tugas dan fungsi unit-unit kerja di BNPB dalam rangka penanggulangan bencana;
d. Penyelarasan mandat, kewenangan, proses bisnis, dan restrukturisasi organisasi agar lebih efektif dan efisien dalam menjalankan tugasnya;
e. Sinkronisasi antara Rencana Strategis sebagai dokumen perencanaan pembangunan dengan Rencana Nasional Penanggulangan Bencana serta Rencana Kerja Tahunan;
f. Transparansi, akuntabilitas, dan inklusivitas proses untuk mendorong partisipasi multipihak dan memperhatikan pengarusutamaan gender;
g. Penguatan sistem peringatan dini dengan mengadopsi teknologi canggih dan pelatihan rutin untuk meningkatkan kesiapsiagaan masyarakat darurat bencana;
h. Peningkatan koordinasi dengan memperkuat sinergi antara BNPB, kementerian, lembaga, dan instansi di daerah untuk penanganan darurat yang lebih cepat dan efektif;
i. Pengembangan kapasitas daerah dengan meningkatkan pelatihan dan distribusi sumber daya yang lebih merata untuk daerah berisiko tinggi;
j. Reformasi Birokrasi dengan fokus pada peningkatan efisiensi, transparasi, dan akuntabilitas dalam tata kelola BNPB melalui reformasi birokrasi internal;', 'Lampiran hal. 64', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4325, 'perban-5-2025', 130, 'lampiran', 'Lampiran hal. 65', NULL, 65, 'k. Optimalisasi penggunaan anggaran dengan memastikan alokasi anggaran yang tepat sasaran dengan perencanaan yang matang untuk mendukung prioritas di lapangan. Perlunya identifikasi sumber-sumber pendanaan lainnya untuk mendukung pelaksanaan program dan anggaran, seperti hibah, pinjaman, Kerja Sama Pemerintah dan Badan Usaha (KPBU), Corporate Social Responsibility (CSR), dan lain-lain;
l. Pemeliharaan keberlanjutan program dengan meningkatkan pemeliharaan infrastruktur dan penguatan kapasitas kelembagaan di daerah untuk memastikan keberlanjutan jangka panjang;
m. Perbaikan pada kapasitas lokal, infrastruktur, dan mekanisme monitoring serta evaluasi, bersama dengan peningkatan koordinasi lintas sektor, akan sangat penting dalam memastikan bahwa strategi penanggulangan bencana dapat diimplementasikan dengan lebih efektif di seluruh wilayah, sejalan dengan tujuan pembangunan nasional.
1.1.5.4. Faktor Pendukung dan Penghambat Keberhasilan Hal-hal yang menjadi faktor pendukung dan penghambat utama keberhasilan pelaksanaan Renstra BNPB Tahun 2020-2024 meliputi:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4325, 'k. Optimalisasi penggunaan anggaran dengan memastikan alokasi anggaran yang tepat sasaran dengan perencanaan yang matang untuk mendukung prioritas di lapangan. Perlunya identifikasi sumber-sumber pendanaan lainnya untuk mendukung pelaksanaan program dan anggaran, seperti hibah, pinjaman, Kerja Sama Pemerintah dan Badan Usaha (KPBU), Corporate Social Responsibility (CSR), dan lain-lain;
l. Pemeliharaan keberlanjutan program dengan meningkatkan pemeliharaan infrastruktur dan penguatan kapasitas kelembagaan di daerah untuk memastikan keberlanjutan jangka panjang;
m. Perbaikan pada kapasitas lokal, infrastruktur, dan mekanisme monitoring serta evaluasi, bersama dengan peningkatan koordinasi lintas sektor, akan sangat penting dalam memastikan bahwa strategi penanggulangan bencana dapat diimplementasikan dengan lebih efektif di seluruh wilayah, sejalan dengan tujuan pembangunan nasional.
1.1.5.4. Faktor Pendukung dan Penghambat Keberhasilan Hal-hal yang menjadi faktor pendukung dan penghambat utama keberhasilan pelaksanaan Renstra BNPB Tahun 2020-2024 meliputi:', 'Lampiran hal. 65', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4326, 'perban-5-2025', 131, 'lampiran', 'Lampiran hal. 65', NULL, 65, 'a. Komitmen Pemerintah terhadap penanggulangan bencana Pemerintah yang berkomitmen terhadap Penanggulangan Bencana (PB) merupakan faktor pendukung utama lahirnya berbagai kebijakan dan program selama periode pembuatan Renstra, serta mempengaruhi budaya kerja untuk mendukung kesiapsiagaan dan mitigasi bencana yang lebih baik. Adanya pola pikir pimpinan aparatur dan tokoh masyarakat yang belum sepenuhnya sadar tentang pentingnya pemahaman terhadap risiko bencana menjadi faktor penghambat upaya kesiapsiagaan dan perencanaan PB yang lebih baik. Sebagai contoh, wilayah Papua Barat berhasil menurunkan risiko di daerah rawan bencana hingga mencapai angka kematian nol. Selain itu, pemimpin juga mampu mengubah paradigma dan pola pikir bahwa penanggulangan bencana adalah tanggung jawab bersama. Sosialisasi dan pelatihan yang dilakukan di Kalimantan Tengah merupakan pembelajaran yang baik untuk membuka pola pikir melalui materi, panduan, dan pedoman dalam mengenali tipe ancaman bencana dan bagaimana menanggulanginya. Keberhasilan upaya tersebut dapat berkontribusi dalam menurunkan indeks risiko bencana dari 144 menjadi 123.
Profil risiko bencana di daerah yang cenderung menurun lebih lanjut dapat dicapai melalui komitmen dalam merealisasikan perencanaan, terutama di daerah yang rawan bencana, dengan sistem yang koersif untuk pengadaan yang efektif.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4326, 'a. Komitmen Pemerintah terhadap penanggulangan bencana Pemerintah yang berkomitmen terhadap Penanggulangan Bencana (PB) merupakan faktor pendukung utama lahirnya berbagai kebijakan dan program selama periode pembuatan Renstra, serta mempengaruhi budaya kerja untuk mendukung kesiapsiagaan dan mitigasi bencana yang lebih baik. Adanya pola pikir pimpinan aparatur dan tokoh masyarakat yang belum sepenuhnya sadar tentang pentingnya pemahaman terhadap risiko bencana menjadi faktor penghambat upaya kesiapsiagaan dan perencanaan PB yang lebih baik. Sebagai contoh, wilayah Papua Barat berhasil menurunkan risiko di daerah rawan bencana hingga mencapai angka kematian nol. Selain itu, pemimpin juga mampu mengubah paradigma dan pola pikir bahwa penanggulangan bencana adalah tanggung jawab bersama. Sosialisasi dan pelatihan yang dilakukan di Kalimantan Tengah merupakan pembelajaran yang baik untuk membuka pola pikir melalui materi, panduan, dan pedoman dalam mengenali tipe ancaman bencana dan bagaimana menanggulanginya. Keberhasilan upaya tersebut dapat berkontribusi dalam menurunkan indeks risiko bencana dari 144 menjadi 123.
Profil risiko bencana di daerah yang cenderung menurun lebih lanjut dapat dicapai melalui komitmen dalam merealisasikan perencanaan, terutama di daerah yang rawan bencana, dengan sistem yang koersif untuk pengadaan yang efektif.', 'Lampiran hal. 65', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4327, 'perban-5-2025', 132, 'lampiran', 'Lampiran hal. 66', NULL, 66, 'b. Ketersediaan Sumber Daya Sumber daya manusia merupakan faktor pendukung berjalannya seluruh program atau kegiatan yang dicanangkan dalam Renstra. Sehingga penting adanya dukungan dari kementerian atau lembaga terkait dan dukungan dari Lembaga Pendidikan dan Pelatihan (Lemdiklat) dengan memasukkan program pelatihan PB mengenai kemampuan perencanaan, alokasi, dan pemeliharaan sarana dan prasarana kesiapsiagaan dan tanggap bencana sebagai program tahunan yang terencana. Pendukung lainnya adalah tersedianya anggaran yang responsif terhadap tiga fase bencana. Jika alokasi pendanaan cukup berimbang, maka kegiatan dan program prabencana dapat diperbanyak dan diperkuat untuk meminimalkan risiko bencana, termasuk korban jiwa dan harta benda.
Selain itu, adanya infrastruktur yang memadai menjadi faktor penting dalam penanggulangan bencana. Pembangunan infrastruktur penanggulangan bencana belum merata di seluruh wilayah Indonesia sehingga perlu adanya prioritas atau afirmasi di periode berikutnya.
c. Kerja sama dan koordinasi antar lembaga mitra pembangunan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4327, 'b. Ketersediaan Sumber Daya Sumber daya manusia merupakan faktor pendukung berjalannya seluruh program atau kegiatan yang dicanangkan dalam Renstra. Sehingga penting adanya dukungan dari kementerian atau lembaga terkait dan dukungan dari Lembaga Pendidikan dan Pelatihan (Lemdiklat) dengan memasukkan program pelatihan PB mengenai kemampuan perencanaan, alokasi, dan pemeliharaan sarana dan prasarana kesiapsiagaan dan tanggap bencana sebagai program tahunan yang terencana. Pendukung lainnya adalah tersedianya anggaran yang responsif terhadap tiga fase bencana. Jika alokasi pendanaan cukup berimbang, maka kegiatan dan program prabencana dapat diperbanyak dan diperkuat untuk meminimalkan risiko bencana, termasuk korban jiwa dan harta benda.
Selain itu, adanya infrastruktur yang memadai menjadi faktor penting dalam penanggulangan bencana. Pembangunan infrastruktur penanggulangan bencana belum merata di seluruh wilayah Indonesia sehingga perlu adanya prioritas atau afirmasi di periode berikutnya.
c. Kerja sama dan koordinasi antar lembaga mitra pembangunan.', 'Lampiran hal. 66', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4328, 'perban-5-2025', 133, 'lampiran', 'Lampiran hal. 66', NULL, 66, 'Kerja sama dan koordinasi antar lembaga mitra pembangunan merupakan faktor pendukung untuk mengisi kesenjangan fiskal guna meningkatkan efektivitas penanggulangan bencana. Selama periode Renstra Tahun 2020-2024 tercatat sebanyak 51 kegiatan dari sekitar enam donor. Dukungan mitra pembangunan ini terdiri dari dua bentuk yakni in-kind berupa alat, sarana dan prasarana, serta dana untuk mendukung pelaksanaan kegiatan serta pendampingan teknis atau tenaga ahli. Adapun pembelajaran untuk perencanaan periode Renstra Tahun 2025-2029 antara lain diperlukan penataan ulang untuk hibah RR dengan menggunakan prinsip First in First out (FIFO). Hal ini penting untuk membantu keselarasan antara Renstra BNPB dengan Renstra/Renja/RKA kementerian atau lembaga dan berkontribusi terhadap peningkatan Indeks RR.
d. Akurasi dan pemutakhiran data dan informasi.
Data yang kurang akurat dan update menghambat proses pengambilan keputusan yang tepat dalam penanggulangan bencana, utamanya saat darurat bencana. Hambatan tersebut masih terus terjadi di periode Renstra Tahun 2020- 2024 karena berkaitan dengan faktor SDM dan sistem monev di BNPB dan instansi terkait PB. Perbaikan terhadap sistem pemantauan dan evaluasi yang lebih baik, SPBE, dan Satu Data Indonesia (SDI) akan berkontribusi terhadap akurasi dan pemutakhiran data dan informasi yang lebih baik pula.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4328, 'Kerja sama dan koordinasi antar lembaga mitra pembangunan merupakan faktor pendukung untuk mengisi kesenjangan fiskal guna meningkatkan efektivitas penanggulangan bencana. Selama periode Renstra Tahun 2020-2024 tercatat sebanyak 51 kegiatan dari sekitar enam donor. Dukungan mitra pembangunan ini terdiri dari dua bentuk yakni in-kind berupa alat, sarana dan prasarana, serta dana untuk mendukung pelaksanaan kegiatan serta pendampingan teknis atau tenaga ahli. Adapun pembelajaran untuk perencanaan periode Renstra Tahun 2025-2029 antara lain diperlukan penataan ulang untuk hibah RR dengan menggunakan prinsip First in First out (FIFO). Hal ini penting untuk membantu keselarasan antara Renstra BNPB dengan Renstra/Renja/RKA kementerian atau lembaga dan berkontribusi terhadap peningkatan Indeks RR.
d. Akurasi dan pemutakhiran data dan informasi.
Data yang kurang akurat dan update menghambat proses pengambilan keputusan yang tepat dalam penanggulangan bencana, utamanya saat darurat bencana. Hambatan tersebut masih terus terjadi di periode Renstra Tahun 2020- 2024 karena berkaitan dengan faktor SDM dan sistem monev di BNPB dan instansi terkait PB. Perbaikan terhadap sistem pemantauan dan evaluasi yang lebih baik, SPBE, dan Satu Data Indonesia (SDI) akan berkontribusi terhadap akurasi dan pemutakhiran data dan informasi yang lebih baik pula.', 'Lampiran hal. 66', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4329, 'perban-5-2025', 134, 'lampiran', 'Lampiran hal. 66', NULL, 66, 'Berdasarkan hasil evaluasi, terdapat beberapa aspek yang dapat dioptimalisasi untuk keberjalanan BNPB pada periode renstra selanjutnya, di antaranya:
a. Penguatan kepemimpinan pusat dan daerah, yaitu perlunya political willingness yang kuat untuk mendukung pelaksanaan Renstra;
b. Perbaikan kualitas knowledge management melalui pembelajaran dari mitra pembangunan, serta perbaikan data dan informasi yang lebih baik;
c. Pengembangan sistem monitoring dan evaluasi, baik dari sisi administrasi maupun dari aspek tugas dan fungsi unit-unit kerja di BNPB dalam rangka penanggulangan bencana;
d. Penyelarasan mandat, kewenangan, proses bisnis, dan restrukturisasi organisasi agar lebih efektif dan efisien dalam menjalankan tugasnya;
e. Sinkronisasi antara Rencana Strategis sebagai dokumen perencanaan pembangunan dengan Rencana Nasional Penanggulangan Bencana serta Rencana Kerja Tahunan;
f. Transparansi, akuntabilitas, dan inklusivitas proses untuk mendorong partisipasi multipihak dan memperhatikan pengarusutamaan gender;
g. Peningkatan kualitas alokasi dan belanja anggaran dan harmonisasi berbagai tipe dukungan hibah, serta memastikan bahwa semua hibah dapat diukur outcome dan dampaknya secara objektif.
1.1.6 Kerangka Kebijakan PB Peninjauan kerangka kebijakan dilakukan terhadap peraturan dan rencana yang mengatur dan mengarahkan penyelenggaraan penanggulangan bencana di Indonesia, antara lain:
a. Undang-Undang (UU) Nomor 24 tahun 2007 Tentang Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4329, 'Berdasarkan hasil evaluasi, terdapat beberapa aspek yang dapat dioptimalisasi untuk keberjalanan BNPB pada periode renstra selanjutnya, di antaranya:
