INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4347, 'perban-5-2025', 152, 'lampiran', 'Lampiran hal. 76', NULL, 76, '10. Kolaborasi dan integrasi sistem tidak hanya mengurangi alokasi peringatan dini secara modalitas, anggaran APBN murni BNPB, instrumentasi dan namun juga menambah beban kerja program/kegiatan dapat dilakukan di luar tupoksi (Isu Strategis 8) secara nasional maupun global. (Isu Strategis 5)
11. Sinkronisasi perencanaan (RPJMN, RPJMD, RKPD, KUPA dan PPAS, APBD) pembangunan, pemeliharaan, monitoring dan evaluasi sistem peringatan dini multi ancaman bencana antar pemerintah pusat dan daerah, termasuk perangkat infrastruktur dan pendanaan. (Isu Strategis 3)
12. Mendorong penerapan SPM di bidang pelayanan bencana melalui penyediaan layanan informasi kebencanaan termasuk sistem peringatan dini, kajian risiko bencana dengan skala yang lebih kecil dan penguatan respons masyarakat melalui gladi yang berkala (Isu Strategis 12)
13. Kajian intervensi kearifan lokal dan praktik baik daerah dalam respons kejadian bencana (Isu Strategis 3)
14. Sedang berjalannya pembangunan Sistem Informasi Manajemen Pusdalops (SIMAMPU) dan platform tata kelola DSP (Isu Strategis 10) Peluang (Opportunity) Ancaman (Threat)
15. Terdapat program kerja sama hibah bilateral untuk mendukung pencapaian misi BNPB, misalnya dengan Amerika Serikat, Australia, Jepang, dan Swiss (Isu Strategis 14)
16. SPM Sub-Urusan Bencana dapat mendorong pemerintah daerah untuk memenuhi layanan, sesuai standar dan teknis yang diatur oleh BNPB (Isu Strategis 12)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4347, '10. Kolaborasi dan integrasi sistem tidak hanya mengurangi alokasi peringatan dini secara modalitas, anggaran APBN murni BNPB, instrumentasi dan namun juga menambah beban kerja program/kegiatan dapat dilakukan di luar tupoksi (Isu Strategis 8) secara nasional maupun global. (Isu Strategis 5)
11. Sinkronisasi perencanaan (RPJMN, RPJMD, RKPD, KUPA dan PPAS, APBD) pembangunan, pemeliharaan, monitoring dan evaluasi sistem peringatan dini multi ancaman bencana antar pemerintah pusat dan daerah, termasuk perangkat infrastruktur dan pendanaan. (Isu Strategis 3)
12. Mendorong penerapan SPM di bidang pelayanan bencana melalui penyediaan layanan informasi kebencanaan termasuk sistem peringatan dini, kajian risiko bencana dengan skala yang lebih kecil dan penguatan respons masyarakat melalui gladi yang berkala (Isu Strategis 12)
13. Kajian intervensi kearifan lokal dan praktik baik daerah dalam respons kejadian bencana (Isu Strategis 3)
14. Sedang berjalannya pembangunan Sistem Informasi Manajemen Pusdalops (SIMAMPU) dan platform tata kelola DSP (Isu Strategis 10) Peluang (Opportunity) Ancaman (Threat)
15. Terdapat program kerja sama hibah bilateral untuk mendukung pencapaian misi BNPB, misalnya dengan Amerika Serikat, Australia, Jepang, dan Swiss (Isu Strategis 14)
16. SPM Sub-Urusan Bencana dapat mendorong pemerintah daerah untuk memenuhi layanan, sesuai standar dan teknis yang diatur oleh BNPB (Isu Strategis 12)', 'Lampiran hal. 76', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4348, 'perban-5-2025', 153, 'lampiran', 'Lampiran hal. 77', NULL, 77, '17. Inisiasi praktik ketangguhan berbasis masyarakat yang inklusif di berbagai daerah, walaupun sifatnya masih sporadis/ terbatas (Isu Strategis 3) Sumber: Analisis Penulis, 2024 Uraian permasalahan dan potensi yang telah dijabarkan dalam SWOT, selanjutnya dianalisis menggunakan metode TOWS untuk merumuskan strategi penanggulangan bencana. Hasil perumusan strategi ini selanjutnya akan menjadi input dalam perumusan strategi rencana strategis BNPB 2025-2029. Analisis perumusan strategi tersebut dibagi menjadi S-O, S-T, W-O, W-T sebagai berikut.
Tabel 1.14. Analisis TOWS Strategi Kekuatan (Strength) - Peluang (Opportunity)
1. Mengoptimalkan implementasi master plan MHEWS melalui sinkronisasi perencanaan pembangunan, pemeliharaan, monitoring, dan pendanaan yang berkelanjutan. (S16 - O8, O9, O10)
2. Mengembangkan skema pendanaan inovatif dalam penanggulangan bencana. (S1 - O5, O14)
3. Meningkatkan Kapasitas Logistik dan Peralatan dalam Penanggulangan Bencana (S2, S9 - O15)
4. Meningkatkan Kemitraan dan Jejaring Logistik dan Peralatan Penanggulangan Bencana (S14 - O10, O15)
5. Pengembangan Inovasi dan teknologi Logistik dan Peralatan Penanggulangan Bencana (S4 - O13)
6. Penyusunan Rencana Aksi Mitigasi Bencana berdasarkan karakteristik ancaman kebencanaan lokal (S7 - O2, O3, O4)
7. Mengoptimalkan pengelolaan bantuan dan partisipasi sukarelawan masyarakat dalam penanganan darurat bencana (S8 - O1) Strategi Kekuatan (Strength) - Ancaman (Threat)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4348, '17. Inisiasi praktik ketangguhan berbasis masyarakat yang inklusif di berbagai daerah, walaupun sifatnya masih sporadis/ terbatas (Isu Strategis 3) Sumber: Analisis Penulis, 2024 Uraian permasalahan dan potensi yang telah dijabarkan dalam SWOT, selanjutnya dianalisis menggunakan metode TOWS untuk merumuskan strategi penanggulangan bencana. Hasil perumusan strategi ini selanjutnya akan menjadi input dalam perumusan strategi rencana strategis BNPB 2025-2029. Analisis perumusan strategi tersebut dibagi menjadi S-O, S-T, W-O, W-T sebagai berikut.
Tabel 1.14. Analisis TOWS Strategi Kekuatan (Strength) - Peluang (Opportunity)
1. Mengoptimalkan implementasi master plan MHEWS melalui sinkronisasi perencanaan pembangunan, pemeliharaan, monitoring, dan pendanaan yang berkelanjutan. (S16 - O8, O9, O10)
2. Mengembangkan skema pendanaan inovatif dalam penanggulangan bencana. (S1 - O5, O14)
3. Meningkatkan Kapasitas Logistik dan Peralatan dalam Penanggulangan Bencana (S2, S9 - O15)
4. Meningkatkan Kemitraan dan Jejaring Logistik dan Peralatan Penanggulangan Bencana (S14 - O10, O15)
5. Pengembangan Inovasi dan teknologi Logistik dan Peralatan Penanggulangan Bencana (S4 - O13)
6. Penyusunan Rencana Aksi Mitigasi Bencana berdasarkan karakteristik ancaman kebencanaan lokal (S7 - O2, O3, O4)
7. Mengoptimalkan pengelolaan bantuan dan partisipasi sukarelawan masyarakat dalam penanganan darurat bencana (S8 - O1) Strategi Kekuatan (Strength) - Ancaman (Threat)', 'Lampiran hal. 77', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4349, 'perban-5-2025', 154, 'lampiran', 'Lampiran hal. 77', NULL, 77, '1. Meningkatkan keterlibatan dan sinergi multipihak untuk mempercepat rehabilitasi dan rekonstruksi pasca bencana pada seluruh aspek secara efektif (S10, S13 - T1, T6)
2. Mewujudkan dan meningkatkan sistem layanan data dan informasi kebencanaan yang terpadu dan berkesinambungan berdasarkan prinsip-prinsip kebijakan satu peta dan satu data (S4, S12, S15 - T2, T9)
3. Penguatan data informasi dan literasi kebencanaan (S7, S11, S12 - T8, T9) Strategi Kelemahan (Weakness) - Peluang (Opportunity)
1. Meningkatkan keterbukaan data dan informasi serta literasi kebencanaan untuk ketangguhan masyarakat (W21 - O6)
2. Menguatkan kualitas kelembagaan dan penggunaan ilmu pengetahuan dan teknologi. (W2, W15, W26 - O12, O13)
3. Membangun sistem manajemen darurat terpadu untuk meningkatkan kapasitas respons terhadap bencana dan situasi darurat (W9, W10, W12 - O11, O13)
4. Meningkatkan advokasi resiliensi berkelanjutan di tingkat nasional & global (W25 - O7, O14)
5. Mengoptimalkan program pengurangan risiko bencana yang inklusif dan berlandaskan hak asasi manusia (W6, W7 - O17) Strategi Kelemahan (Weakness) - Ancaman (Threat)
1. Mewujudkan integrasi sistem peringatan dini bencana yang holistik dan inklusif untuk memastikan efektivitas sistem peringatan dini bencana secara nasional dan daerah. (W23 - T9, T10, T11)
2. Meningkatkan kualitas perencanaan dan percepatan pelaksanaan rehabilitasi dan rekonstruksi pascabencana berbasis tata ruang dan pengurangan risiko bencana (W14, W17, W20 - T5, T8)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4349, '1. Meningkatkan keterlibatan dan sinergi multipihak untuk mempercepat rehabilitasi dan rekonstruksi pasca bencana pada seluruh aspek secara efektif (S10, S13 - T1, T6)
2. Mewujudkan dan meningkatkan sistem layanan data dan informasi kebencanaan yang terpadu dan berkesinambungan berdasarkan prinsip-prinsip kebijakan satu peta dan satu data (S4, S12, S15 - T2, T9)
3. Penguatan data informasi dan literasi kebencanaan (S7, S11, S12 - T8, T9) Strategi Kelemahan (Weakness) - Peluang (Opportunity)
1. Meningkatkan keterbukaan data dan informasi serta literasi kebencanaan untuk ketangguhan masyarakat (W21 - O6)
2. Menguatkan kualitas kelembagaan dan penggunaan ilmu pengetahuan dan teknologi. (W2, W15, W26 - O12, O13)
3. Membangun sistem manajemen darurat terpadu untuk meningkatkan kapasitas respons terhadap bencana dan situasi darurat (W9, W10, W12 - O11, O13)
4. Meningkatkan advokasi resiliensi berkelanjutan di tingkat nasional & global (W25 - O7, O14)
5. Mengoptimalkan program pengurangan risiko bencana yang inklusif dan berlandaskan hak asasi manusia (W6, W7 - O17) Strategi Kelemahan (Weakness) - Ancaman (Threat)
1. Mewujudkan integrasi sistem peringatan dini bencana yang holistik dan inklusif untuk memastikan efektivitas sistem peringatan dini bencana secara nasional dan daerah. (W23 - T9, T10, T11)
2. Meningkatkan kualitas perencanaan dan percepatan pelaksanaan rehabilitasi dan rekonstruksi pascabencana berbasis tata ruang dan pengurangan risiko bencana (W14, W17, W20 - T5, T8)', 'Lampiran hal. 77', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4350, 'perban-5-2025', 155, 'lampiran', 'Lampiran hal. 78', NULL, 78, '3. Mewujudkan dan meningkatkan sistem layanan data dan informasi kebencanaan yang terpadu dan berkesinambungan berdasarkan prinsip-prinsip kebijakan satu peta dan satu data (W2 - T2)
4. Meningkatkan kualitas & kuantitas SDM yang memiliki keahlian dan profesional di Bidang Kebencanaan (W3, W4, W5, W16, W27 - T3)
5. Meningkatkan investasi dan peningkatan kapasitas sumber daya dalam kesiapsiagaan dan penanggulangan kedaruratan bencana (W19 - T12) Sumber: Analisis Penulis, 2024 Program Prioritas Pengelolaan Risiko Bencana yang Efisien dan Tepat Guna sebagaimana diamanatkan dalam RPJMN merupakan salah satu instrumen penting untuk mewujudkan arah kebijakan pembangunan nasional di bidang penanggulangan bencana. BNPB, sebagai lembaga yang memiliki mandat koordinasi, komando, dan pelaksanaan, memegang peran sentral dalam memastikan pengelolaan risiko bencana berjalan secara terintegrasi dari hulu ke hilir.
Berdasarkan hasil analisis lingkungan strategis melalui pendekatan SWOT dan perumusan strategi TOWS, dapat diidentifikasi arah penguatan program BNPB untuk periode 2025–2029.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4350, '3. Mewujudkan dan meningkatkan sistem layanan data dan informasi kebencanaan yang terpadu dan berkesinambungan berdasarkan prinsip-prinsip kebijakan satu peta dan satu data (W2 - T2)
4. Meningkatkan kualitas & kuantitas SDM yang memiliki keahlian dan profesional di Bidang Kebencanaan (W3, W4, W5, W16, W27 - T3)
5. Meningkatkan investasi dan peningkatan kapasitas sumber daya dalam kesiapsiagaan dan penanggulangan kedaruratan bencana (W19 - T12) Sumber: Analisis Penulis, 2024 Program Prioritas Pengelolaan Risiko Bencana yang Efisien dan Tepat Guna sebagaimana diamanatkan dalam RPJMN merupakan salah satu instrumen penting untuk mewujudkan arah kebijakan pembangunan nasional di bidang penanggulangan bencana. BNPB, sebagai lembaga yang memiliki mandat koordinasi, komando, dan pelaksanaan, memegang peran sentral dalam memastikan pengelolaan risiko bencana berjalan secara terintegrasi dari hulu ke hilir.
Berdasarkan hasil analisis lingkungan strategis melalui pendekatan SWOT dan perumusan strategi TOWS, dapat diidentifikasi arah penguatan program BNPB untuk periode 2025–2029.', 'Lampiran hal. 78', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4351, 'perban-5-2025', 156, 'lampiran', 'Lampiran hal. 78', NULL, 78, 'Dari sisi kekuatan, BNPB telah memiliki landasan regulasi, pedoman teknis, sistem informasi, serta pengalaman koordinasi lintas sektor yang mendukung efektivitas penanggulangan bencana. Keberadaan sistem peringatan dini multi-bahaya (Multi Hazard Early Warning System), sistem database logistik nasional, serta integrasi kajian risiko bencana ke dalam rehabilitasi dan rekonstruksi menjadi modal utama dalam penguatan kapasitas nasional. Seluruh kekuatan ini selaras dengan target RPJMN untuk meningkatkan kesiapsiagaan, mempercepat respons, dan memperkuat pemulihan pascabencana yang adaptif terhadap perubahan iklim dan dinamika risiko. Namun demikian, kelemahan seperti belum optimalnya harmonisasi regulasi, keterbatasan kapasitas SDM dan anggaran, lemahnya interoperabilitas data, hingga belum meratanya inklusivitas dalam program menjadi tantangan yang perlu diatasi. Hal ini berpotensi menghambat pencapaian indikator kinerja RPJMN jika tidak segera dilakukan intervensi strategis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4351, 'Dari sisi kekuatan, BNPB telah memiliki landasan regulasi, pedoman teknis, sistem informasi, serta pengalaman koordinasi lintas sektor yang mendukung efektivitas penanggulangan bencana. Keberadaan sistem peringatan dini multi-bahaya (Multi Hazard Early Warning System), sistem database logistik nasional, serta integrasi kajian risiko bencana ke dalam rehabilitasi dan rekonstruksi menjadi modal utama dalam penguatan kapasitas nasional. Seluruh kekuatan ini selaras dengan target RPJMN untuk meningkatkan kesiapsiagaan, mempercepat respons, dan memperkuat pemulihan pascabencana yang adaptif terhadap perubahan iklim dan dinamika risiko. Namun demikian, kelemahan seperti belum optimalnya harmonisasi regulasi, keterbatasan kapasitas SDM dan anggaran, lemahnya interoperabilitas data, hingga belum meratanya inklusivitas dalam program menjadi tantangan yang perlu diatasi. Hal ini berpotensi menghambat pencapaian indikator kinerja RPJMN jika tidak segera dilakukan intervensi strategis.', 'Lampiran hal. 78', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4352, 'perban-5-2025', 157, 'lampiran', 'Lampiran hal. 79', NULL, 79, 'Dari sisi peluang, adanya dukungan mekanisme pooling fund, peningkatan kerja sama internasional, integrasi perencanaan pembangunan dengan rencana penanggulangan bencana, dan kemajuan teknologi informasi dapat dimanfaatkan untuk memperkuat peran BNPB. Peluang ini sejalan dengan amanat RPJMN yang mendorong inovasi pendanaan, penguatan jejaring kerja sama, dan pemanfaatan teknologi untuk mengurangi risiko bencana. Sementara itu, ancaman seperti lemahnya kepemimpinan lintas sektor, rendahnya komitmen pemerintah daerah terhadap integrasi pengurangan risiko bencana dalam tata ruang, perbedaan interpretasi sistem peringatan dini, serta keterbatasan anggaran daerah menuntut BNPB untuk memperkuat fungsi koordinasi dan advokasi kebijakan di tingkat nasional dan daerah.
Hasil analisis TOWS memandu BNPB untuk merumuskan strategi yang konkret, antara lain:
1. Mengoptimalkan master plan MHEWS dengan sinkronisasi perencanaan, pendanaan, dan pengoperasian secara berkelanjutan;
2. Mengembangkan skema pendanaan inovatif dan kemitraan strategis untuk mendukung penanggulangan bencana lintas sektor;
3. Memperkuat sistem data dan informasi kebencanaan terpadu berbasis prinsip Satu Data Indonesia, yang menjadi landasan pengambilan keputusan cepat dan akurat;
4. Meningkatkan kapasitas SDM dan kelembagaan, termasuk integrasi perspektif inklusi, gender, dan HAM dalam seluruh siklus penanggulangan bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4352, 'Dari sisi peluang, adanya dukungan mekanisme pooling fund, peningkatan kerja sama internasional, integrasi perencanaan pembangunan dengan rencana penanggulangan bencana, dan kemajuan teknologi informasi dapat dimanfaatkan untuk memperkuat peran BNPB. Peluang ini sejalan dengan amanat RPJMN yang mendorong inovasi pendanaan, penguatan jejaring kerja sama, dan pemanfaatan teknologi untuk mengurangi risiko bencana. Sementara itu, ancaman seperti lemahnya kepemimpinan lintas sektor, rendahnya komitmen pemerintah daerah terhadap integrasi pengurangan risiko bencana dalam tata ruang, perbedaan interpretasi sistem peringatan dini, serta keterbatasan anggaran daerah menuntut BNPB untuk memperkuat fungsi koordinasi dan advokasi kebijakan di tingkat nasional dan daerah.
Hasil analisis TOWS memandu BNPB untuk merumuskan strategi yang konkret, antara lain:
1. Mengoptimalkan master plan MHEWS dengan sinkronisasi perencanaan, pendanaan, dan pengoperasian secara berkelanjutan;
2. Mengembangkan skema pendanaan inovatif dan kemitraan strategis untuk mendukung penanggulangan bencana lintas sektor;
3. Memperkuat sistem data dan informasi kebencanaan terpadu berbasis prinsip Satu Data Indonesia, yang menjadi landasan pengambilan keputusan cepat dan akurat;
4. Meningkatkan kapasitas SDM dan kelembagaan, termasuk integrasi perspektif inklusi, gender, dan HAM dalam seluruh siklus penanggulangan bencana;', 'Lampiran hal. 79', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4353, 'perban-5-2025', 158, 'lampiran', 'Lampiran hal. 79', NULL, 79, '5. Membangun manajemen darurat terpadu yang mempercepat respons dan memperkuat kolaborasi antara pusat-daerah serta melibatkan masyarakat dan relawan.
Dengan strategi tersebut, pelaksanaan Program Prioritas Pengelolaan Risiko Bencana BNPB akan mampu menjawab target RPJMN, yaitu menciptakan sistem penanggulangan bencana yang efisien, tepat guna, inklusif, dan berkelanjutan.
Implementasi program ini diharapkan mampu menekan indeks risiko bencana nasional, meningkatkan ketangguhan masyarakat, serta memperkuat daya saing dan keberlanjutan pembangunan di Indonesia.
Dengan memanfaatkan kekuatan dan peluang secara maksimal, serta mengelola kelemahan dan ancaman secara bijak, BNPB akan mampu mewujudkan visinya sebagai lembaga yang tangguh dan responsif, serta menjalankan misinya dalam melindungi masyarakat, lingkungan, dan aset bangsa dari dampak bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4353, '5. Membangun manajemen darurat terpadu yang mempercepat respons dan memperkuat kolaborasi antara pusat-daerah serta melibatkan masyarakat dan relawan.
Dengan strategi tersebut, pelaksanaan Program Prioritas Pengelolaan Risiko Bencana BNPB akan mampu menjawab target RPJMN, yaitu menciptakan sistem penanggulangan bencana yang efisien, tepat guna, inklusif, dan berkelanjutan.
Implementasi program ini diharapkan mampu menekan indeks risiko bencana nasional, meningkatkan ketangguhan masyarakat, serta memperkuat daya saing dan keberlanjutan pembangunan di Indonesia.
Dengan memanfaatkan kekuatan dan peluang secara maksimal, serta mengelola kelemahan dan ancaman secara bijak, BNPB akan mampu mewujudkan visinya sebagai lembaga yang tangguh dan responsif, serta menjalankan misinya dalam melindungi masyarakat, lingkungan, dan aset bangsa dari dampak bencana.', 'Lampiran hal. 79', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4354, 'perban-5-2025', 159, 'lampiran', 'Lampiran hal. 80', NULL, 80, 'BAB 2. VISI, MISI, TUJUAN, DAN SASARAN STRATEGIS BNPB adalah sebuah Lembaga Pemerintah Nonkementerian yang mempunyai tugas membantu Presiden Republik Indonesia dalam melaksanakan penanggulangan bencana sesuai dengan amanat Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. BNPB dibentuk berdasarkan Peraturan Presiden Nomor 8 Tahun 2008 yang kemudian diganti dengan Peraturan Presiden Nomor 1 Tahun 2019. Salah satu tugasnya adalah memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana yang mencakup pencegahan bencana, penanganan keadaan darurat bencana, rehabilitasi, dan rekonstruksi. Fungsi BNPB meliputi perumusan dan penetapan kebijakan penanggulangan bencana dan penanganan pengungsi dengan bertindak cepat dan tepat serta efektif dan efisien; dan pengoordinasian pelaksanaan kegiatan penanggulangan bencana secara terencana, terpadu, dan menyeluruh. Selain itu apabila terjadi bencana nasional, BNPB melaksanakan fungsi komando dalam penanganan status keadaan darurat bencana dan keadaan tertentu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4354, 'BAB 2. VISI, MISI, TUJUAN, DAN SASARAN STRATEGIS BNPB adalah sebuah Lembaga Pemerintah Nonkementerian yang mempunyai tugas membantu Presiden Republik Indonesia dalam melaksanakan penanggulangan bencana sesuai dengan amanat Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. BNPB dibentuk berdasarkan Peraturan Presiden Nomor 8 Tahun 2008 yang kemudian diganti dengan Peraturan Presiden Nomor 1 Tahun 2019. Salah satu tugasnya adalah memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana yang mencakup pencegahan bencana, penanganan keadaan darurat bencana, rehabilitasi, dan rekonstruksi. Fungsi BNPB meliputi perumusan dan penetapan kebijakan penanggulangan bencana dan penanganan pengungsi dengan bertindak cepat dan tepat serta efektif dan efisien; dan pengoordinasian pelaksanaan kegiatan penanggulangan bencana secara terencana, terpadu, dan menyeluruh. Selain itu apabila terjadi bencana nasional, BNPB melaksanakan fungsi komando dalam penanganan status keadaan darurat bencana dan keadaan tertentu.', 'Lampiran hal. 80', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4355, 'perban-5-2025', 160, 'lampiran', 'Lampiran hal. 80', NULL, 80, '2.1. Visi BNPB Penyusunan Visi BNPB memiliki rujukan spesifik terkait penanggulangan kebencanaan dan rujukan umum terkait pembangunan nasional. Rujukan spesifik tersebut yaitu Rencana Induk Penanggulangan Bencana (RIPB) Tahun 2020-2044, adalah pedoman nasional penyelenggaraan penanggulangan bencana yang harus diacu oleh seluruh lembaga di Indonesia dalam perencanaan dan pelaksanaan penanggulangan bencana. Sejalan dengan hal tersebut, Visi BNPB Tahun 2025-2029 harus mendukung Visi RIPB 2020-2044.
Visi Penanggulangan Bencana dalam RIPB Tahun 2020-2044 “Mewujudkan Indonesia Tangguh Bencana untuk Pembangunan Berkelanjutan” Mengacu pada Peraturan Presiden Nomor 80 Tahun 2025, pengertian visi adalah Penjabaran visi Presiden dan Wakil Presiden sebagaimana dimuat dalam RPJM Nasional yang disusun dalam bentuk rumusan umum mengenai keadaan yang diinginkan pada akhir periode perencanaan sesuai dengan tugas dan fungsi kementerian/lembaga. Dalam hal ini, perumusan visi dan misi seluruh kementerian/lembaga mengacu pada Visi Presiden 2025-2029 berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4355, '2.1. Visi BNPB Penyusunan Visi BNPB memiliki rujukan spesifik terkait penanggulangan kebencanaan dan rujukan umum terkait pembangunan nasional. Rujukan spesifik tersebut yaitu Rencana Induk Penanggulangan Bencana (RIPB) Tahun 2020-2044, adalah pedoman nasional penyelenggaraan penanggulangan bencana yang harus diacu oleh seluruh lembaga di Indonesia dalam perencanaan dan pelaksanaan penanggulangan bencana. Sejalan dengan hal tersebut, Visi BNPB Tahun 2025-2029 harus mendukung Visi RIPB 2020-2044.
Visi Penanggulangan Bencana dalam RIPB Tahun 2020-2044 “Mewujudkan Indonesia Tangguh Bencana untuk Pembangunan Berkelanjutan” Mengacu pada Peraturan Presiden Nomor 80 Tahun 2025, pengertian visi adalah Penjabaran visi Presiden dan Wakil Presiden sebagaimana dimuat dalam RPJM Nasional yang disusun dalam bentuk rumusan umum mengenai keadaan yang diinginkan pada akhir periode perencanaan sesuai dengan tugas dan fungsi kementerian/lembaga. Dalam hal ini, perumusan visi dan misi seluruh kementerian/lembaga mengacu pada Visi Presiden 2025-2029 berikut:', 'Lampiran hal. 80', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4356, 'perban-5-2025', 161, 'lampiran', 'Lampiran hal. 80', NULL, 80, 'Visi Presiden 2025-2029 “Bersama Indonesia Maju Menuju Indonesia Emas 2045” Visi Presiden tersebut selanjutnya dituangkan ke dalam Rencana Pembangunan Jangka Menengah Nasional (RPJMN) 2025-2029. Visi "Indonesia Maju Menuju Indonesia Emas 2045" adalah cita-cita besar bangsa Indonesia untuk menjadi negara yang unggul, mandiri, adil, dan makmur pada peringatan 100 tahun kemerdekaan Indonesia di tahun 2045. Visi ini digagas oleh Presiden bersama pemerintah dan didukung seluruh rakyat Indonesia sebagai peta jalan pembangunan jangka panjang. Adapun penyelenggaraan penanggulangan bencana sebagai bagian tidak terpisahkan dari Rencana Pembangunan Jangka Menengah Nasional (RPJMN) 2025-2029, mengacu pada visi RPJMN yang menyebutkan: “Bersama Indonesia Maju Menuju Indonesia Emas 2045” Berdasarkan rujukan spesifik dan rujukan umum di atas, visi di dalam Renstra BNPB ini merupakan rumusan umum mengenai keadaan yang ingin dicapai oleh BNPB pada akhir periode perencanaan yang mengacu pada Visi RPJMN Tahun 2025- 2029.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4356, 'Visi Presiden 2025-2029 “Bersama Indonesia Maju Menuju Indonesia Emas 2045” Visi Presiden tersebut selanjutnya dituangkan ke dalam Rencana Pembangunan Jangka Menengah Nasional (RPJMN) 2025-2029. Visi "Indonesia Maju Menuju Indonesia Emas 2045" adalah cita-cita besar bangsa Indonesia untuk menjadi negara yang unggul, mandiri, adil, dan makmur pada peringatan 100 tahun kemerdekaan Indonesia di tahun 2045. Visi ini digagas oleh Presiden bersama pemerintah dan didukung seluruh rakyat Indonesia sebagai peta jalan pembangunan jangka panjang. Adapun penyelenggaraan penanggulangan bencana sebagai bagian tidak terpisahkan dari Rencana Pembangunan Jangka Menengah Nasional (RPJMN) 2025-2029, mengacu pada visi RPJMN yang menyebutkan: “Bersama Indonesia Maju Menuju Indonesia Emas 2045” Berdasarkan rujukan spesifik dan rujukan umum di atas, visi di dalam Renstra BNPB ini merupakan rumusan umum mengenai keadaan yang ingin dicapai oleh BNPB pada akhir periode perencanaan yang mengacu pada Visi RPJMN Tahun 2025- 2029.', 'Lampiran hal. 80', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4357, 'perban-5-2025', 162, 'lampiran', 'Lampiran hal. 80', NULL, 80, 'Adapun hasil perumusan Visi BNPB Tahun 2025-2029 sebagai berikut: “Mewujudkan Penyelenggaraan Penanggulangan Bencana yang Kolaboratif untuk Membangun Resiliensi Bangsa Menghadapi Bencana Bersama Indonesia Maju Menuju Indonesia Emas 2045” Bencana alam seringkali menyebabkan kehilangan jiwa dan kerugian ekonomi yang besar dalam bentuk kerusakan infrastruktur maupun gangguan pada aktivitas ekonomi sehingga kolaborasi penanggulangan bencana sangat dibutuhkan untuk mengurangi risiko dan dampak bencana. Penyelenggaraan penanggulangan bencana yang kolaboratif adalah upaya penanganan bencana yang dilakukan oleh berbagai pihak dengan melibatkan para pemangku kepentingan (kolaborasi multi-stakeholder) yang merupakan strategi kunci untuk membangun resiliensi bangsa dalam menghadapi bencana. Melalui kolaborasi dengan berbagai pihak dapat terbentuk sistem penanggulangan bencana yang kuat sehingga akan lebih siap dan tangguh dalam menghadapi potensi bencana di masa mendatang. Upaya kolaborasi ini merupakan perwujudan lebih strategis atas fungsi koordinasi BNPB dalam penanggulangan bencana. Indonesia, sebagai negara yang secara alami memiliki risiko sistemik tinggi terhadap bencana, sering menghadapi konsekuensi yang serius seperti hilangnya nyawa, kerugian materi, dan penundaan dalam proses pembangunan. Tingkat ketangguhan bencana yang tinggi akan membantu mengurangi dampak bertingkat tersebut, termasuk penurunan potensi kerugian ekonomi yang diakibatkan oleh kejadian bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4357, 'Adapun hasil perumusan Visi BNPB Tahun 2025-2029 sebagai berikut: “Mewujudkan Penyelenggaraan Penanggulangan Bencana yang Kolaboratif untuk Membangun Resiliensi Bangsa Menghadapi Bencana Bersama Indonesia Maju Menuju Indonesia Emas 2045” Bencana alam seringkali menyebabkan kehilangan jiwa dan kerugian ekonomi yang besar dalam bentuk kerusakan infrastruktur maupun gangguan pada aktivitas ekonomi sehingga kolaborasi penanggulangan bencana sangat dibutuhkan untuk mengurangi risiko dan dampak bencana. Penyelenggaraan penanggulangan bencana yang kolaboratif adalah upaya penanganan bencana yang dilakukan oleh berbagai pihak dengan melibatkan para pemangku kepentingan (kolaborasi multi-stakeholder) yang merupakan strategi kunci untuk membangun resiliensi bangsa dalam menghadapi bencana. Melalui kolaborasi dengan berbagai pihak dapat terbentuk sistem penanggulangan bencana yang kuat sehingga akan lebih siap dan tangguh dalam menghadapi potensi bencana di masa mendatang. Upaya kolaborasi ini merupakan perwujudan lebih strategis atas fungsi koordinasi BNPB dalam penanggulangan bencana. Indonesia, sebagai negara yang secara alami memiliki risiko sistemik tinggi terhadap bencana, sering menghadapi konsekuensi yang serius seperti hilangnya nyawa, kerugian materi, dan penundaan dalam proses pembangunan. Tingkat ketangguhan bencana yang tinggi akan membantu mengurangi dampak bertingkat tersebut, termasuk penurunan potensi kerugian ekonomi yang diakibatkan oleh kejadian bencana.', 'Lampiran hal. 80', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4358, 'perban-5-2025', 163, 'lampiran', 'Lampiran hal. 81', NULL, 81, 'Dalam mewujudkan visi terwujudnya resiliensi secara kolaboratif tersebut, BNPB berkomitmen untuk mengkoordinasikan, memimpin, dan melaksanakan penanggulangan bencana di Indonesia dengan pendekatan yang profesional, terpadu, adil, dan inovatif. Dengan mengutamakan koordinasi yang kuat, komando yang efektif, dan standar profesionalisme tinggi, BNPB akan bekerja sama dengan berbagai pemangku kepentingan untuk merancang solusi yang efektif dan berkelanjutan. Pemulihan pasca bencana tidak hanya akan fokus pada pemulihan infrastruktur fisik, tetapi juga memperhatikan kebutuhan masyarakat yang paling rentan secara sosial dan ekonomi, dengan memastikan perlakuan yang setara dan adil bagi semua. Melalui inovasi dan pendekatan yang terbarukan, BNPB akan terus mengeksplorasi upaya untuk meningkatkan efektivitas dalam menanggulangi bencana serta memperkuat ketahanan masyarakat terhadap ancaman yang akan datang.
2.2. Misi BNPB Mengacu pada Peraturan Presiden Nomor 80 Tahun 2025, pengertian Misi penjabaran misi Presiden dan Wakil Presiden sebagaimana dimuat dalam RPJM Nasional yang disusun dalam bentuk rumusan umum mengenai upaya-upaya yang akan dilaksanakan untuk mewujudkan Visi sesuai dengan tugas dan fungsi kementerian/lembaga. Misi tersebut berada dalam lingkup tugas dan fungsi BNPB tingkat pusat serta posisi BNPB sebagai lembaga publik pemerintah. Adapun Misi BNPB dalam Renstra Tahun 2025-2029, yaitu:
1. Meningkatkan penerapan pengelolaan risiko bencana dalam pembangunan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4358, 'Dalam mewujudkan visi terwujudnya resiliensi secara kolaboratif tersebut, BNPB berkomitmen untuk mengkoordinasikan, memimpin, dan melaksanakan penanggulangan bencana di Indonesia dengan pendekatan yang profesional, terpadu, adil, dan inovatif. Dengan mengutamakan koordinasi yang kuat, komando yang efektif, dan standar profesionalisme tinggi, BNPB akan bekerja sama dengan berbagai pemangku kepentingan untuk merancang solusi yang efektif dan berkelanjutan. Pemulihan pasca bencana tidak hanya akan fokus pada pemulihan infrastruktur fisik, tetapi juga memperhatikan kebutuhan masyarakat yang paling rentan secara sosial dan ekonomi, dengan memastikan perlakuan yang setara dan adil bagi semua. Melalui inovasi dan pendekatan yang terbarukan, BNPB akan terus mengeksplorasi upaya untuk meningkatkan efektivitas dalam menanggulangi bencana serta memperkuat ketahanan masyarakat terhadap ancaman yang akan datang.
2.2. Misi BNPB Mengacu pada Peraturan Presiden Nomor 80 Tahun 2025, pengertian Misi penjabaran misi Presiden dan Wakil Presiden sebagaimana dimuat dalam RPJM Nasional yang disusun dalam bentuk rumusan umum mengenai upaya-upaya yang akan dilaksanakan untuk mewujudkan Visi sesuai dengan tugas dan fungsi kementerian/lembaga. Misi tersebut berada dalam lingkup tugas dan fungsi BNPB tingkat pusat serta posisi BNPB sebagai lembaga publik pemerintah. Adapun Misi BNPB dalam Renstra Tahun 2025-2029, yaitu:
1. Meningkatkan penerapan pengelolaan risiko bencana dalam pembangunan;', 'Lampiran hal. 81', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4359, 'perban-5-2025', 164, 'lampiran', 'Lampiran hal. 81', NULL, 81, '2. Meningkatkan kualitas penyelenggaraan penanggulangan bencana yang terkoordinasi dan terpadu;
3. Meningkatkan kualitas SDM penanggulangan bencana yang profesional;
4. Meningkatkan kualitas tata Kelola kelembagaan BNPB yang transparan dan akuntabel.
Keempat misi BNPB dalam Renstra 2025–2029 dirancang secara berkesinambungan dan saling menguatkan untuk mewujudkan visi penanggulangan bencana nasional.
Misi Pertama BNPB – yaitu meningkatkan penerapan pengelolaan risiko bencana dalam pembangunan – merupakan langkah penting untuk memastikan bahwa setiap aspek pembangunan mempertimbangkan potensi risiko bencana dan mengambil langkah-langkah untuk mengurangi dampaknya. Meningkatnya penerapan pengelolaan risiko bencana dalam pembangunan berarti semakin banyak proyek pembangunan yang mempertimbangkan dan mengintegrasikan langkah-langkah untuk mengurangi risiko bencana, menetapkan kebijakan yang mendukung pengelolaan risiko bencana, termasuk regulasi zonasi dan standar bangunan yang ketat, integrasi analisis risiko bencana dalam rencana tata ruang dan penggunaan lahan dan merancang infrastruktur yang tahan terhadap bencana dengan menggunakan material dan teknik konstruksi yang inovatif. Untuk itu pemerintah dan semua pemangku kepentingan harus memiliki komitmen yang kuat untuk mengintegrasikan pengelolaan risiko bencana dalam semua aspek pembangunan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4359, '2. Meningkatkan kualitas penyelenggaraan penanggulangan bencana yang terkoordinasi dan terpadu;
3. Meningkatkan kualitas SDM penanggulangan bencana yang profesional;
4. Meningkatkan kualitas tata Kelola kelembagaan BNPB yang transparan dan akuntabel.
Keempat misi BNPB dalam Renstra 2025–2029 dirancang secara berkesinambungan dan saling menguatkan untuk mewujudkan visi penanggulangan bencana nasional.
Misi Pertama BNPB – yaitu meningkatkan penerapan pengelolaan risiko bencana dalam pembangunan – merupakan langkah penting untuk memastikan bahwa setiap aspek pembangunan mempertimbangkan potensi risiko bencana dan mengambil langkah-langkah untuk mengurangi dampaknya. Meningkatnya penerapan pengelolaan risiko bencana dalam pembangunan berarti semakin banyak proyek pembangunan yang mempertimbangkan dan mengintegrasikan langkah-langkah untuk mengurangi risiko bencana, menetapkan kebijakan yang mendukung pengelolaan risiko bencana, termasuk regulasi zonasi dan standar bangunan yang ketat, integrasi analisis risiko bencana dalam rencana tata ruang dan penggunaan lahan dan merancang infrastruktur yang tahan terhadap bencana dengan menggunakan material dan teknik konstruksi yang inovatif. Untuk itu pemerintah dan semua pemangku kepentingan harus memiliki komitmen yang kuat untuk mengintegrasikan pengelolaan risiko bencana dalam semua aspek pembangunan.', 'Lampiran hal. 81', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4360, 'perban-5-2025', 165, 'lampiran', 'Lampiran hal. 82', NULL, 82, 'Kebutuhan sumber daya penting dalam upaya ini, yaitu penyediaan anggaran yang cukup untuk implementasi pengelolaan risiko bencana, termasuk dana darurat dan investasi dalam infrastruktur tahan bencana. Keberhasilan misi ini akan menciptakan pondasi yang kokoh bagi penyelenggaraan penanggulangan bencana yang efektif.
Misi Kedua BNPB – yaitu meningkatkan kualitas penyelenggaraan penanggulangan bencana yang terkoordinasi dan terpadu – merupakan langkah penting di tengah ancaman bencana yang semakin tinggi dan kompleks. Karena itu dibutuhkan upaya yang kolaboratif, dan sistematis yang dapat meningkatkan kualitas penyelenggaraan penanggulangan bencana yang terkoordinasi dan terpadu. Tantangan besar yang dihadapi BNPB dalam upaya koordinasi dan keterpaduan, karena pihak-pihak yang berkoordinasi memiliki tujuan, prosedur, dan budaya kerja yang berbeda. Menyusun mekanisme koordinasi yang jelas dan sistematis, seperti pusat komando yang dapat menyatukan semua pihak dan menetapkan Standar Operasional Prosedur (SOP) yang disepakati bersama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4360, 'Kebutuhan sumber daya penting dalam upaya ini, yaitu penyediaan anggaran yang cukup untuk implementasi pengelolaan risiko bencana, termasuk dana darurat dan investasi dalam infrastruktur tahan bencana. Keberhasilan misi ini akan menciptakan pondasi yang kokoh bagi penyelenggaraan penanggulangan bencana yang efektif.
Misi Kedua BNPB – yaitu meningkatkan kualitas penyelenggaraan penanggulangan bencana yang terkoordinasi dan terpadu – merupakan langkah penting di tengah ancaman bencana yang semakin tinggi dan kompleks. Karena itu dibutuhkan upaya yang kolaboratif, dan sistematis yang dapat meningkatkan kualitas penyelenggaraan penanggulangan bencana yang terkoordinasi dan terpadu. Tantangan besar yang dihadapi BNPB dalam upaya koordinasi dan keterpaduan, karena pihak-pihak yang berkoordinasi memiliki tujuan, prosedur, dan budaya kerja yang berbeda. Menyusun mekanisme koordinasi yang jelas dan sistematis, seperti pusat komando yang dapat menyatukan semua pihak dan menetapkan Standar Operasional Prosedur (SOP) yang disepakati bersama.', 'Lampiran hal. 82', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4361, 'perban-5-2025', 166, 'lampiran', 'Lampiran hal. 82', NULL, 82, 'Misi Ketiga BNPB – yaitu meningkatkan kualitas Sumber Daya Manusia (SDM) dalam penanggulangan bencana secara profesional untuk memastikan respons dan mitigasi bencana yang efektif dan efisien agar mampu meminimalisasi dampak bencana dan mempercepat pemulihan masyarakat. Permasalahan dalam hal ini yaitu banyak personel penanggulangan bencana yang belum mendapatkan pendidikan formal atau pelatihan yang memadai di bidang manajemen bencana dan belum cukupnya standar profesional yang jelas dan sertifikasi yang diakui secara luas. Untuk mengatasi hal tersebut, maka dibutuhkan pelatihan teknis berkala untuk meningkatkan keterampilan praktis personel penanggulangan bencana, seperti teknik evakuasi, penyelamatan, dan penggunaan peralatan darurat, sertifikasi untuk kualifikasi dan kompetensi SDM yang diakui secara profesional dan keterampilan teknis seperti penggunaan peralatan penyelamatan, teknologi pemantauan, dan sistem peringatan dini sering kali tidak dimiliki secara merata oleh seluruh personel.
Misi Keempat BNPB – yaitu meningkatkan kualitas tata kelola kelembagaan Badan Nasional Penanggulangan Bencana (BNPB) yang transparan dan akuntabel sebagai pertanggungjawaban kepada publik. Tata kelola penyelenggaraan penanggulangan bencana yang profesional, akuntabel, dan transparan akan mendukung dan memperkuat penyelenggaraan penanggulangan bencana yang lebih andal.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4361, 'Misi Ketiga BNPB – yaitu meningkatkan kualitas Sumber Daya Manusia (SDM) dalam penanggulangan bencana secara profesional untuk memastikan respons dan mitigasi bencana yang efektif dan efisien agar mampu meminimalisasi dampak bencana dan mempercepat pemulihan masyarakat. Permasalahan dalam hal ini yaitu banyak personel penanggulangan bencana yang belum mendapatkan pendidikan formal atau pelatihan yang memadai di bidang manajemen bencana dan belum cukupnya standar profesional yang jelas dan sertifikasi yang diakui secara luas. Untuk mengatasi hal tersebut, maka dibutuhkan pelatihan teknis berkala untuk meningkatkan keterampilan praktis personel penanggulangan bencana, seperti teknik evakuasi, penyelamatan, dan penggunaan peralatan darurat, sertifikasi untuk kualifikasi dan kompetensi SDM yang diakui secara profesional dan keterampilan teknis seperti penggunaan peralatan penyelamatan, teknologi pemantauan, dan sistem peringatan dini sering kali tidak dimiliki secara merata oleh seluruh personel.
Misi Keempat BNPB – yaitu meningkatkan kualitas tata kelola kelembagaan Badan Nasional Penanggulangan Bencana (BNPB) yang transparan dan akuntabel sebagai pertanggungjawaban kepada publik. Tata kelola penyelenggaraan penanggulangan bencana yang profesional, akuntabel, dan transparan akan mendukung dan memperkuat penyelenggaraan penanggulangan bencana yang lebih andal.', 'Lampiran hal. 82', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4362, 'perban-5-2025', 167, 'lampiran', 'Lampiran hal. 83', NULL, 83, 'Keempat misi tersebut saling terkait secara berkesinambungan sebagai satu kesatuan upaya untuk mewujudkan penanggulangan bencana yang efektif, terukur dan berorientasi pada ketahanan nasional. Misi pertama menjadi pondasi utama untuk memastikan setiap proses pembangunan nasional mempertimbangkan potensi ancaman bencana sehingga dapat mengurangi kerugian dan memperkuat keberlanjutan. Upaya ini dapat berjalan optimal dengan dukungan misi kedua, yang memastikan sinergi lintas sektor, lintas wilayah, dan lintas pemangku kepentingan untuk mengimplementasikan kebijakan dan program secara selaras.
Kesinambungan tersebut diperkuat melalui misi ketiga, yaitu tercapainya kualitas perencanaan, pelaksanaan dan koordinasi karena ditopang oleh SDM yang memiliki kompetensi, integritas dan dedikasi tinggi.
Seluruh misi tersebut bermuara pada misi keempat, yang menjadi prasyarat agar setiap kebijakan, program dan sumber daya yang dikelola dapat dipertanggungjawabkan dan memberikan dampak nyata bagi masyarakat.
Dengan demikian, keempat misi tersebut membentuk siklus yang saling menguatkan mulai dari perencanaan berbasis risiko, pelaksanaan yang terkoordinasi, penguatan kapasitas SDM, hingga penerapan tata kelola yang baik sehingga tujuan besar pengurangan risiko bencana dapat diwujudkan secara efektif, tepat guna, dan berkelanjutan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4362, 'Keempat misi tersebut saling terkait secara berkesinambungan sebagai satu kesatuan upaya untuk mewujudkan penanggulangan bencana yang efektif, terukur dan berorientasi pada ketahanan nasional. Misi pertama menjadi pondasi utama untuk memastikan setiap proses pembangunan nasional mempertimbangkan potensi ancaman bencana sehingga dapat mengurangi kerugian dan memperkuat keberlanjutan. Upaya ini dapat berjalan optimal dengan dukungan misi kedua, yang memastikan sinergi lintas sektor, lintas wilayah, dan lintas pemangku kepentingan untuk mengimplementasikan kebijakan dan program secara selaras.
Kesinambungan tersebut diperkuat melalui misi ketiga, yaitu tercapainya kualitas perencanaan, pelaksanaan dan koordinasi karena ditopang oleh SDM yang memiliki kompetensi, integritas dan dedikasi tinggi.
Seluruh misi tersebut bermuara pada misi keempat, yang menjadi prasyarat agar setiap kebijakan, program dan sumber daya yang dikelola dapat dipertanggungjawabkan dan memberikan dampak nyata bagi masyarakat.
Dengan demikian, keempat misi tersebut membentuk siklus yang saling menguatkan mulai dari perencanaan berbasis risiko, pelaksanaan yang terkoordinasi, penguatan kapasitas SDM, hingga penerapan tata kelola yang baik sehingga tujuan besar pengurangan risiko bencana dapat diwujudkan secara efektif, tepat guna, dan berkelanjutan.', 'Lampiran hal. 83', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4363, 'perban-5-2025', 168, 'lampiran', 'Lampiran hal. 83', NULL, 83, '2.3. Tujuan BNPB Mengacu pada Peraturan Presiden Nomor 80 Tahun 2025, pengertian Tujuan adalah penjabaran atas visi dalam rangka mencapai sasaran program prioritas Presiden dan Wakil Presiden. Sejalan dengan Visi dan Misi BNPB, maka Tujuan BNPB Tahun 2025-2029 adalah: “Terwujudnya penyelenggaraan penanggulangan bencana yang terkoordinasi dan terpadu” Untuk mewujudkan penanggulangan bencana yang terkoordinasi dan terpadu, diperlukan suatu sistem yang melibatkan seluruh pemangku kepentingan dengan indikator pencapaian yang terukur. Indikator tujuan yang digunakan mengacu RPJMN dalam Prioritas Nasional 8 dengan indikator: “Proporsi kerugian ekonomi langsung akibat bencana relatif terhadap PDB dari 0,1370% menjadi 0,1350%” Penentuan target penurunan proporsi kerugian ekonomi langsung akibat bencana relatif terhadap PDB tersebut dirumuskan oleh Bappenas berdasarkan pada laporan BNPB terhadap ketercapaian SFDRR serta perhitungan investasi di bidang bencana secara nasional. Kerugian sebesar 0,1370% seutuhnya merupakan kerugian akibat bencana, dan belum termasuk perhitungan terkait kerugian iklim. Oleh karena itu, peran untuk mendukung ketercapaian indikator RPJMN ini akan diakomodasikan oleh BNPB. Selain berperan sebagai leading sector di bidang penanggulangan bencana, BNPB juga berperan untuk melaporkan ketercapaian ini sebagai perwakilan pemerintah Indonesia dalam forum SFDRR.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4363, '2.3. Tujuan BNPB Mengacu pada Peraturan Presiden Nomor 80 Tahun 2025, pengertian Tujuan adalah penjabaran atas visi dalam rangka mencapai sasaran program prioritas Presiden dan Wakil Presiden. Sejalan dengan Visi dan Misi BNPB, maka Tujuan BNPB Tahun 2025-2029 adalah: “Terwujudnya penyelenggaraan penanggulangan bencana yang terkoordinasi dan terpadu” Untuk mewujudkan penanggulangan bencana yang terkoordinasi dan terpadu, diperlukan suatu sistem yang melibatkan seluruh pemangku kepentingan dengan indikator pencapaian yang terukur. Indikator tujuan yang digunakan mengacu RPJMN dalam Prioritas Nasional 8 dengan indikator: “Proporsi kerugian ekonomi langsung akibat bencana relatif terhadap PDB dari 0,1370% menjadi 0,1350%” Penentuan target penurunan proporsi kerugian ekonomi langsung akibat bencana relatif terhadap PDB tersebut dirumuskan oleh Bappenas berdasarkan pada laporan BNPB terhadap ketercapaian SFDRR serta perhitungan investasi di bidang bencana secara nasional. Kerugian sebesar 0,1370% seutuhnya merupakan kerugian akibat bencana, dan belum termasuk perhitungan terkait kerugian iklim. Oleh karena itu, peran untuk mendukung ketercapaian indikator RPJMN ini akan diakomodasikan oleh BNPB. Selain berperan sebagai leading sector di bidang penanggulangan bencana, BNPB juga berperan untuk melaporkan ketercapaian ini sebagai perwakilan pemerintah Indonesia dalam forum SFDRR.', 'Lampiran hal. 83', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4364, 'perban-5-2025', 169, 'lampiran', 'Lampiran hal. 84', NULL, 84, 'Tabel 2.1. Indikator Tujuan BNPB Tahun 2025-2029 Indikator Tujuan BNPB 2025 2026 2027 2028 2029 Proporsi Kerugian Ekonomi 0,1365 0,1360 0,1355 0,1350 Langsung Akibat Bencana Relatif 0,1370% % % % % Terhadap PDB Sumber: RPJMN Tahun 2025-2029 Metode perhitungan indikator proporsi kerugian ekonomi langsung akibat bencana relatif terhadap PDB merupakan hasil pengurangan proporsi kerugian ekonomi langsung akibat bencana business as usual (tanpa Intervensi), dikurangi investasi terhadap upaya penanggulangan bencana. Semakin besar investasi yang dilakukan, maka semakin kecil kerugian yang ditimbulkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4364, 'Tabel 2.1. Indikator Tujuan BNPB Tahun 2025-2029 Indikator Tujuan BNPB 2025 2026 2027 2028 2029 Proporsi Kerugian Ekonomi 0,1365 0,1360 0,1355 0,1350 Langsung Akibat Bencana Relatif 0,1370% % % % % Terhadap PDB Sumber: RPJMN Tahun 2025-2029 Metode perhitungan indikator proporsi kerugian ekonomi langsung akibat bencana relatif terhadap PDB merupakan hasil pengurangan proporsi kerugian ekonomi langsung akibat bencana business as usual (tanpa Intervensi), dikurangi investasi terhadap upaya penanggulangan bencana. Semakin besar investasi yang dilakukan, maka semakin kecil kerugian yang ditimbulkan.', 'Lampiran hal. 84', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4365, 'perban-5-2025', 170, 'lampiran', 'Lampiran hal. 84', NULL, 84, 'Gambar 2.1. Metode Perhitungan Indikator Proporsi Kerugian Ekonomi Langsung Terhadap PDB Sumber: Direktorat Tata Ruang, Pertahanan, dan Penanggulangan Bencana, Bappenas, 2024 2.4. Sasaran Strategis BNPB Mengacu pada Peraturan Presiden Nomor 80 Tahun 2025, pengertian Sasaran Strategis adalah kondisi yang akan dicapai secara nyata oleh kementerian/lembaga yang mencermati pengaruh yang ditimbulkan oleh adanya hasil dari satu atau beberapa program. Sasaran Strategis BNPB berpedoman pada RPJMN Tahun 2025- 2029 Prioritas Nasional ke-8, yaitu Memperkuat Penyelarasan Kehidupan yang Harmonis dengan Lingkungan Alam dan Budaya, serta Peningkatan Toleransi Antarumat Beragama untuk Mencapai Masyarakat yang Adil dan Makmur, dengan arah pembangunan berupa: “Resiliensi Terhadap Bencana dan Perubahan Iklim” Indikator Kinerja Strategis pada RPJMN tersebut yaitu Persentase Penurunan Nilai Indeks Risiko Bencana Nasional 1,2% setiap tahun. Sasaran Strategis BNPB mengacu pada arah pembangunan RPJMN di atas, sehingga Sasaran Strategis BNPB berfokus pada: “Resiliensi Terhadap Bencana” Indikator Kinerja Strategis:
1. Persentase Penurunan Nilai Indeks Risiko Bencana Nasional 1,2% setiap tahun;
2. Persentase Daerah yang memiliki tingkat kapasitas penanggulangan bencana minimal kategori sedang dari 67% menjadi 90%.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4365, 'Gambar 2.1. Metode Perhitungan Indikator Proporsi Kerugian Ekonomi Langsung Terhadap PDB Sumber: Direktorat Tata Ruang, Pertahanan, dan Penanggulangan Bencana, Bappenas, 2024 2.4. Sasaran Strategis BNPB Mengacu pada Peraturan Presiden Nomor 80 Tahun 2025, pengertian Sasaran Strategis adalah kondisi yang akan dicapai secara nyata oleh kementerian/lembaga yang mencermati pengaruh yang ditimbulkan oleh adanya hasil dari satu atau beberapa program. Sasaran Strategis BNPB berpedoman pada RPJMN Tahun 2025- 2029 Prioritas Nasional ke-8, yaitu Memperkuat Penyelarasan Kehidupan yang Harmonis dengan Lingkungan Alam dan Budaya, serta Peningkatan Toleransi Antarumat Beragama untuk Mencapai Masyarakat yang Adil dan Makmur, dengan arah pembangunan berupa: “Resiliensi Terhadap Bencana dan Perubahan Iklim” Indikator Kinerja Strategis pada RPJMN tersebut yaitu Persentase Penurunan Nilai Indeks Risiko Bencana Nasional 1,2% setiap tahun. Sasaran Strategis BNPB mengacu pada arah pembangunan RPJMN di atas, sehingga Sasaran Strategis BNPB berfokus pada: “Resiliensi Terhadap Bencana” Indikator Kinerja Strategis:
1. Persentase Penurunan Nilai Indeks Risiko Bencana Nasional 1,2% setiap tahun;
2. Persentase Daerah yang memiliki tingkat kapasitas penanggulangan bencana minimal kategori sedang dari 67% menjadi 90%.', 'Lampiran hal. 84', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4366, 'perban-5-2025', 171, 'lampiran', 'Lampiran hal. 85', NULL, 85, 'Fokus resiliensi BNPB bertujuan untuk membangun fondasi yang kokoh bagi masyarakat dan infrastruktur negara untuk dapat bertahan dan pulih lebih cepat dari dampak bencana, sehingga menciptakan masa depan yang lebih aman dan berkelanjutan bagi semua warga Indonesia, secara kolaboratif, terkoordinasi, terpadu dan akuntabel.
Indeks Risiko Bencana Indonesia (IRBI) adalah suatu perangkat analisis kebencanaan yang menunjukkan riwayat dan dampak nyata bencana yang terjadi di wilayah Indonesia. IRBI digunakan untuk menilai kemungkinan dampak yang akan terjadi jika suatu ancaman menjadi bencana di suatu wilayah di Indonesia, serta untuk mengukur capaian penurunan indeks risiko bencana di tingkat kabupaten/kota dan provinsi. Penentuan target penurunan indeks risiko bencana nasional 1,2% didasarkan pada hasil capaian Indonesia sejauh ini pada Kerangka Kerja Sendai untuk Pengurangan Risiko Bencana. Kerangka Kerja Sendai menuturkan beberapa tujuan yang perlu dihimbau oleh negara partisipan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4366, 'Fokus resiliensi BNPB bertujuan untuk membangun fondasi yang kokoh bagi masyarakat dan infrastruktur negara untuk dapat bertahan dan pulih lebih cepat dari dampak bencana, sehingga menciptakan masa depan yang lebih aman dan berkelanjutan bagi semua warga Indonesia, secara kolaboratif, terkoordinasi, terpadu dan akuntabel.
Indeks Risiko Bencana Indonesia (IRBI) adalah suatu perangkat analisis kebencanaan yang menunjukkan riwayat dan dampak nyata bencana yang terjadi di wilayah Indonesia. IRBI digunakan untuk menilai kemungkinan dampak yang akan terjadi jika suatu ancaman menjadi bencana di suatu wilayah di Indonesia, serta untuk mengukur capaian penurunan indeks risiko bencana di tingkat kabupaten/kota dan provinsi. Penentuan target penurunan indeks risiko bencana nasional 1,2% didasarkan pada hasil capaian Indonesia sejauh ini pada Kerangka Kerja Sendai untuk Pengurangan Risiko Bencana. Kerangka Kerja Sendai menuturkan beberapa tujuan yang perlu dihimbau oleh negara partisipan.', 'Lampiran hal. 85', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4367, 'perban-5-2025', 172, 'lampiran', 'Lampiran hal. 85', NULL, 85, 'Indeks Ketahanan Daerah (IKD) merupakan upaya untuk mengukur kapasitas penanggulangan bencana di wilayah administrasi, baik di tingkat kabupaten/kota dan provinsi. Dengan terbitnya Undang-undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah, maka penanggulangan bencana menjadi urusan wajib daerah. Indeks Ketahanan Daerah ini nantinya akan mempengaruhi Indeks Risiko Bencana Indonesia di tingkat nasional pada setiap provinsi maupun kabupaten/kota di Indonesia. Setidaknya terdapat 7 prioritas, 71 indikator, dan 284 pertanyaan yang mesti dijawab dalam setiap pengisian Indeks Ketahanan Daerah (IKD).
Selanjutnya, untuk mengukur kelembagaan BNPB terhadap penilaian atas efektifitas efisiensi responsivitas organisasi dalam menjalankan tugas dan fungsinya, sehingga perlu dirumuskan Sasaran Strategis yang ke-2 yaitu: “Meningkatnya Kualitas Tata Kelola BNPB” Indikator Kinerja Strategis: Peningkatan Nilai Reformasi Birokrasi dari 77,18 menjadi 79.
Reformasi birokrasi adalah serangkaian upaya sistematis dan terencana yang dilakukan oleh pemerintah untuk memperbaiki kinerja birokrasi agar lebih efektif, efisien, transparan, dan akuntabel. Perubahan ini bertujuan untuk mencapai tata kelola pemerintahan yang baik (good governance). Indikator ini merupakan indikator tambahan untuk mengukur keberhasilan dan kemajuan reformasi birokrasi di lingkungan BNPB melalui penyusunan grand design reformasi birokrasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4367, 'Indeks Ketahanan Daerah (IKD) merupakan upaya untuk mengukur kapasitas penanggulangan bencana di wilayah administrasi, baik di tingkat kabupaten/kota dan provinsi. Dengan terbitnya Undang-undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah, maka penanggulangan bencana menjadi urusan wajib daerah. Indeks Ketahanan Daerah ini nantinya akan mempengaruhi Indeks Risiko Bencana Indonesia di tingkat nasional pada setiap provinsi maupun kabupaten/kota di Indonesia. Setidaknya terdapat 7 prioritas, 71 indikator, dan 284 pertanyaan yang mesti dijawab dalam setiap pengisian Indeks Ketahanan Daerah (IKD).
Selanjutnya, untuk mengukur kelembagaan BNPB terhadap penilaian atas efektifitas efisiensi responsivitas organisasi dalam menjalankan tugas dan fungsinya, sehingga perlu dirumuskan Sasaran Strategis yang ke-2 yaitu: “Meningkatnya Kualitas Tata Kelola BNPB” Indikator Kinerja Strategis: Peningkatan Nilai Reformasi Birokrasi dari 77,18 menjadi 79.
Reformasi birokrasi adalah serangkaian upaya sistematis dan terencana yang dilakukan oleh pemerintah untuk memperbaiki kinerja birokrasi agar lebih efektif, efisien, transparan, dan akuntabel. Perubahan ini bertujuan untuk mencapai tata kelola pemerintahan yang baik (good governance). Indikator ini merupakan indikator tambahan untuk mengukur keberhasilan dan kemajuan reformasi birokrasi di lingkungan BNPB melalui penyusunan grand design reformasi birokrasi.', 'Lampiran hal. 85', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4368, 'perban-5-2025', 173, 'lampiran', 'Lampiran hal. 85', NULL, 85, 'Dalam rangka mendukung pencapaian tujuan pembangunan nasional di bidang penanggulangan bencana, BNPB menetapkan dua sasaran strategis utama, yaitu meningkatkan resiliensi terhadap bencana serta meningkatkan kualitas tata kelola organisasi. Guna menjamin keberhasilan pencapaian kedua sasaran tersebut, diperlukan identifikasi dini terhadap berbagai indikasi risiko yang dapat menghambat efektivitas pelaksanaan program dan kegiatan.
Tabel 2.2. Identifikasi Indikasi Risiko Sasaran Strategis Indikasi PJ Sasaran Identifikasi Indikasi No. Indikasi Perlakuan Risiko Perlakuan Strategis Risiko Risiko
1. Resiliensi Peningkatan Risiko Penilaian Risiko Bencana Direktorat Terhadap Bencana Akibat PERB Bencana Perubahan Iklim Kegiatan Pengurangan Risiko Direktorat yang ekstrem dan Bencana yang bersifat Mitigasi sulit diprediksi Adaptif Perubahan Iklim Bencana dan Direktorat Kesiapsiagaan Keterbatasan 1. Penguatan Sinergi Lintas Direktorat jumlah Sektor untuk memperluas Peringatan infrastruktur Early cakupan EWS Dini Warning System 2. Memanfaatkan kearifan (EWS) yang tersedia lokal di wilayah masing-masing Kurangnya tingkat Edukasi Berbasis Komunitas Direktorat partisipasi dan dan Pelatihan serta Simulasi Mitigasi kesadaran secara rutin Bencana masyarakat dalam memahami risiko bencana di wilayah masing-masing');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4368, 'Dalam rangka mendukung pencapaian tujuan pembangunan nasional di bidang penanggulangan bencana, BNPB menetapkan dua sasaran strategis utama, yaitu meningkatkan resiliensi terhadap bencana serta meningkatkan kualitas tata kelola organisasi. Guna menjamin keberhasilan pencapaian kedua sasaran tersebut, diperlukan identifikasi dini terhadap berbagai indikasi risiko yang dapat menghambat efektivitas pelaksanaan program dan kegiatan.
Tabel 2.2. Identifikasi Indikasi Risiko Sasaran Strategis Indikasi PJ Sasaran Identifikasi Indikasi No. Indikasi Perlakuan Risiko Perlakuan Strategis Risiko Risiko
1. Resiliensi Peningkatan Risiko Penilaian Risiko Bencana Direktorat Terhadap Bencana Akibat PERB Bencana Perubahan Iklim Kegiatan Pengurangan Risiko Direktorat yang ekstrem dan Bencana yang bersifat Mitigasi sulit diprediksi Adaptif Perubahan Iklim Bencana dan Direktorat Kesiapsiagaan Keterbatasan 1. Penguatan Sinergi Lintas Direktorat jumlah Sektor untuk memperluas Peringatan infrastruktur Early cakupan EWS Dini Warning System 2. Memanfaatkan kearifan (EWS) yang tersedia lokal di wilayah masing-masing Kurangnya tingkat Edukasi Berbasis Komunitas Direktorat partisipasi dan dan Pelatihan serta Simulasi Mitigasi kesadaran secara rutin Bencana masyarakat dalam memahami risiko bencana di wilayah masing-masing', 'Lampiran hal. 85', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4369, 'perban-5-2025', 174, 'lampiran', 'Lampiran hal. 86', NULL, 86, '2. Meningkatnya Masih terbatasnya Pemetaan dan program Biro SDM dan Kualitas Tata pelatihan/bimtek pelatihan SDM kebencanaan Umum dan Kelola BNPB untuk peningkatan yang komprehensif, Pusdiklat PB kapasitas SDM mencakup aspek tata kelola, terkait dengan dan manajerial aspek tata Kelola dan manjerial Masih terdapat Penguatan kebijakan internal Biro Hukum, kesenjangan dan harmonisasi regulasi Organisasi regulasi yang dapat untuk menopang tata kelola dan Kerjasama menghambat organisasi yang adaptif, efektivitas responsif dan selaras dengan pelaksanaan tugas dinamika kebutuhan dan fungsi penanggulangan bencana organisasi.
Rendahnya capaian 1. Penguatan koordinasi Biro Hukum, nilai Reformasi dengan instansi meso Organisasi Birokrasi pengampu indikator RB dan Kerja General; Sama
2. Penguatan SDM yang profesional dalam melaksanakan program RB General dan RB Tematik;
3. Penguatan Anggaran Khususnya kegiatan yang mendukung capaian RB tematik (sesuai tema prioritas Presiden);
4. Komitmen unit kerja pengampu dalam memenuhi semua indikator IKU RB General yang menjadi Kewenangannya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4369, '2. Meningkatnya Masih terbatasnya Pemetaan dan program Biro SDM dan Kualitas Tata pelatihan/bimtek pelatihan SDM kebencanaan Umum dan Kelola BNPB untuk peningkatan yang komprehensif, Pusdiklat PB kapasitas SDM mencakup aspek tata kelola, terkait dengan dan manajerial aspek tata Kelola dan manjerial Masih terdapat Penguatan kebijakan internal Biro Hukum, kesenjangan dan harmonisasi regulasi Organisasi regulasi yang dapat untuk menopang tata kelola dan Kerjasama menghambat organisasi yang adaptif, efektivitas responsif dan selaras dengan pelaksanaan tugas dinamika kebutuhan dan fungsi penanggulangan bencana organisasi.
Rendahnya capaian 1. Penguatan koordinasi Biro Hukum, nilai Reformasi dengan instansi meso Organisasi Birokrasi pengampu indikator RB dan Kerja General; Sama
2. Penguatan SDM yang profesional dalam melaksanakan program RB General dan RB Tematik;
3. Penguatan Anggaran Khususnya kegiatan yang mendukung capaian RB tematik (sesuai tema prioritas Presiden);
4. Komitmen unit kerja pengampu dalam memenuhi semua indikator IKU RB General yang menjadi Kewenangannya.', 'Lampiran hal. 86', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4370, 'perban-5-2025', 175, 'lampiran', 'Lampiran hal. 86', NULL, 86, 'Sumber: Penulis, 2025 Dalam upaya meningkatkan kualitas pembangunan yang berkelanjutan serta menjamin keselamatan dan kesejahteraan masyarakat, BNPB menempatkan pengurangan risiko bencana sebagai salah satu prioritas strategis dalam manajemen kinerja, hal tersebut searah dengan Sendai Framework for Disaster Risk Reduction (SFDRR) 2015-2030 yaitu aksi global yang disepakati negara-negara anggota PBB untuk mengurangi risiko bencana secara signifikan melalui penguatan ketahanan terhadap bencana di tingkat individu komunitas negara. Hal ini tercermin dalam target penurunan Indeks Risiko Bencana (IRB) dan peningkatan Indeks Ketahanan Daerah (IKD) sebagai indikator utama yang mendukung pencapaian tujuan pembangunan yang inklusif, tangguh, dan adaptif terhadap perubahan iklim serta ancaman bencana.
Perencanaan strategis dalam rangka penurunan IRB dan peningkatan IKD dirancang secara holistik melalui pendekatan multisektor dan berbasis data risiko. Strategi ini meliputi:
a. Penguatan Sistem Informasi Kebencanaan Pemerintah daerah mengembangkan sistem pemantauan risiko berbasis teknologi informasi dan pemetaan rawan bencana yang akurat serta terintegrasi. Langkah ini mendukung pengambilan keputusan yang cepat dan tepat dalam mitigasi maupun respons bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4370, 'Sumber: Penulis, 2025 Dalam upaya meningkatkan kualitas pembangunan yang berkelanjutan serta menjamin keselamatan dan kesejahteraan masyarakat, BNPB menempatkan pengurangan risiko bencana sebagai salah satu prioritas strategis dalam manajemen kinerja, hal tersebut searah dengan Sendai Framework for Disaster Risk Reduction (SFDRR) 2015-2030 yaitu aksi global yang disepakati negara-negara anggota PBB untuk mengurangi risiko bencana secara signifikan melalui penguatan ketahanan terhadap bencana di tingkat individu komunitas negara. Hal ini tercermin dalam target penurunan Indeks Risiko Bencana (IRB) dan peningkatan Indeks Ketahanan Daerah (IKD) sebagai indikator utama yang mendukung pencapaian tujuan pembangunan yang inklusif, tangguh, dan adaptif terhadap perubahan iklim serta ancaman bencana.
Perencanaan strategis dalam rangka penurunan IRB dan peningkatan IKD dirancang secara holistik melalui pendekatan multisektor dan berbasis data risiko. Strategi ini meliputi:
a. Penguatan Sistem Informasi Kebencanaan Pemerintah daerah mengembangkan sistem pemantauan risiko berbasis teknologi informasi dan pemetaan rawan bencana yang akurat serta terintegrasi. Langkah ini mendukung pengambilan keputusan yang cepat dan tepat dalam mitigasi maupun respons bencana.', 'Lampiran hal. 86', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4371, 'perban-5-2025', 176, 'lampiran', 'Lampiran hal. 87', NULL, 87, 'b. Peningkatan Kapasitas Kelembagaan dan Masyarakat Ditingkatkan melalui pelatihan dan simulasi penanggulangan bencana, pemberdayaan komunitas siaga bencana, serta penguatan peran Forum Pengurangan Risiko Bencana (PRB). Upaya ini diharapkan mendorong partisipasi aktif seluruh lapisan masyarakat dalam membangun ketangguhan wilayah.
c. Penyusunan dan Implementasi Rencana Kontingensi serta Kajian Risiko Bencana Pemerintah daerah memastikan tersusunnya dokumen kajian risiko bencana dan rencana kontingensi di seluruh wilayah, sebagai dasar integrasi PRB ke dalam perencanaan pembangunan daerah.
d. Pengarusutamaan PRB ke dalam RPJMD dan RKPD Setiap program dan kegiatan pembangunan daerah dirancang dengan memperhatikan aspek risiko bencana guna mengurangi potensi kerugian dan memastikan keberlanjutan program lintas sektor.
e. Penguatan Infrastruktur Tangguh Bencana dan Tata Ruang Berbasis Risiko Pembangunan infrastruktur dan pengembangan kawasan diarahkan untuk memperhatikan aspek risiko bencana dan adaptasi perubahan iklim, termasuk penerapan prinsip pembangunan hijau dan berkelanjutan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4371, 'b. Peningkatan Kapasitas Kelembagaan dan Masyarakat Ditingkatkan melalui pelatihan dan simulasi penanggulangan bencana, pemberdayaan komunitas siaga bencana, serta penguatan peran Forum Pengurangan Risiko Bencana (PRB). Upaya ini diharapkan mendorong partisipasi aktif seluruh lapisan masyarakat dalam membangun ketangguhan wilayah.
c. Penyusunan dan Implementasi Rencana Kontingensi serta Kajian Risiko Bencana Pemerintah daerah memastikan tersusunnya dokumen kajian risiko bencana dan rencana kontingensi di seluruh wilayah, sebagai dasar integrasi PRB ke dalam perencanaan pembangunan daerah.
d. Pengarusutamaan PRB ke dalam RPJMD dan RKPD Setiap program dan kegiatan pembangunan daerah dirancang dengan memperhatikan aspek risiko bencana guna mengurangi potensi kerugian dan memastikan keberlanjutan program lintas sektor.
e. Penguatan Infrastruktur Tangguh Bencana dan Tata Ruang Berbasis Risiko Pembangunan infrastruktur dan pengembangan kawasan diarahkan untuk memperhatikan aspek risiko bencana dan adaptasi perubahan iklim, termasuk penerapan prinsip pembangunan hijau dan berkelanjutan.', 'Lampiran hal. 87', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4372, 'perban-5-2025', 177, 'lampiran', 'Lampiran hal. 87', NULL, 87, 'Dengan implementasi strategi tersebut, pemerintah daerah menargetkan penurunan signifikan terhadap nilai IRB dan peningkatan skor IKD dalam jangka menengah dan panjang. Evaluasi dan pengukuran kinerja dilakukan secara berkala melalui indikator yang ditetapkan oleh BNPB dan Bappenas, yang terintegrasi dalam Sistem Akuntabilitas Kinerja Instansi Pemerintah (SAKIP). Capaian indikator ini juga menjadi tolok ukur keberhasilan tata kelola risiko bencana yang adaptif dan berdaya lenting tinggi.
Melalui manajemen kinerja yang terencana dan terukur, pemerintah daerah berkomitmen untuk menciptakan wilayah yang lebih aman, tangguh, dan siap menghadapi berbagai potensi ancaman bencana di masa mendatang.
Pemantauan dan evaluasi merupakan komponen krusial dalam sistem penanggulangan bencana yang berfungsi untuk memastikan bahwa setiap tahapan penanganan bencana berjalan secara efektif, efisien, dan tepat sasaran. Proses ini dilakukan secara sistematis untuk menilai kinerja program, mengidentifikasi tantangan di lapangan, serta memberikan umpan balik bagi perbaikan kebijakan dan operasional.
Pemantauan dilakukan secara berkala selama pelaksanaan kegiatan penanggulangan bencana, baik dalam fase prabencana, saat tanggap darurat, maupun pascabencana. Kegiatan ini mencakup pengumpulan data, observasi langsung, serta pelaporan dari instansi dan pemangku kepentingan terkait.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4372, 'Dengan implementasi strategi tersebut, pemerintah daerah menargetkan penurunan signifikan terhadap nilai IRB dan peningkatan skor IKD dalam jangka menengah dan panjang. Evaluasi dan pengukuran kinerja dilakukan secara berkala melalui indikator yang ditetapkan oleh BNPB dan Bappenas, yang terintegrasi dalam Sistem Akuntabilitas Kinerja Instansi Pemerintah (SAKIP). Capaian indikator ini juga menjadi tolok ukur keberhasilan tata kelola risiko bencana yang adaptif dan berdaya lenting tinggi.
Melalui manajemen kinerja yang terencana dan terukur, pemerintah daerah berkomitmen untuk menciptakan wilayah yang lebih aman, tangguh, dan siap menghadapi berbagai potensi ancaman bencana di masa mendatang.
Pemantauan dan evaluasi merupakan komponen krusial dalam sistem penanggulangan bencana yang berfungsi untuk memastikan bahwa setiap tahapan penanganan bencana berjalan secara efektif, efisien, dan tepat sasaran. Proses ini dilakukan secara sistematis untuk menilai kinerja program, mengidentifikasi tantangan di lapangan, serta memberikan umpan balik bagi perbaikan kebijakan dan operasional.
Pemantauan dilakukan secara berkala selama pelaksanaan kegiatan penanggulangan bencana, baik dalam fase prabencana, saat tanggap darurat, maupun pascabencana. Kegiatan ini mencakup pengumpulan data, observasi langsung, serta pelaporan dari instansi dan pemangku kepentingan terkait.', 'Lampiran hal. 87', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4373, 'perban-5-2025', 178, 'lampiran', 'Lampiran hal. 88', NULL, 88, 'Pemantauan memungkinkan deteksi dini terhadap hambatan, kesenjangan layanan, dan kebutuhan tambahan, sehingga respons dapat segera disesuaikan.
Sementara itu, evaluasi berfokus pada penilaian menyeluruh terhadap hasil dan dampak kegiatan yang telah dilaksanakan. Evaluasi membantu menilai sejauh mana tujuan program tercapai, bagaimana efektivitas koordinasi antar instansi, serta efisiensi penggunaan sumber daya. Evaluasi dilakukan baik secara internal maupun eksternal agar hasilnya objektif dan komprehensif.
Manfaat utama dari pemantauan dan evaluasi antara lain:
1) Perbaikan Berkelanjutan Monitoring dan evaluasi memberikan dasar yang kuat untuk pengambilan keputusan berbasis bukti (evidence based decision making), sehingga kebijakan dan program dapat disesuaikan agar lebih relevan dan efektif.
2) Transparansi dan Akuntabilitas Proses monitoring dan evaluasi mendukung keterbukaan informasi dan pertanggungjawaban dalam penggunaan anggaran dan pelaksanaan kegiatan penanggulangan bencana.
3) Penguatan Kapasitas Institusi dan Komunitas Evaluasi membantu mengidentifikasi kelemahan dan kekuatan dalam sistem yang ada, serta memberikan rekomendasi untuk peningkatan kapasitas kelembagaan dan peran aktif masyarakat.
4) Peningkatan Respons dan Mitigasi Risiko Dengan informasi dari monitoring dan evaluasi, strategi penanggulangan bencana dapat lebih adaptif terhadap perubahan risiko dan kondisi lingkungan, sehingga meningkatkan kesiapsiagaan dan mempercepat pemulihan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4373, 'Pemantauan memungkinkan deteksi dini terhadap hambatan, kesenjangan layanan, dan kebutuhan tambahan, sehingga respons dapat segera disesuaikan.
Sementara itu, evaluasi berfokus pada penilaian menyeluruh terhadap hasil dan dampak kegiatan yang telah dilaksanakan. Evaluasi membantu menilai sejauh mana tujuan program tercapai, bagaimana efektivitas koordinasi antar instansi, serta efisiensi penggunaan sumber daya. Evaluasi dilakukan baik secara internal maupun eksternal agar hasilnya objektif dan komprehensif.
Manfaat utama dari pemantauan dan evaluasi antara lain:
1) Perbaikan Berkelanjutan Monitoring dan evaluasi memberikan dasar yang kuat untuk pengambilan keputusan berbasis bukti (evidence based decision making), sehingga kebijakan dan program dapat disesuaikan agar lebih relevan dan efektif.
2) Transparansi dan Akuntabilitas Proses monitoring dan evaluasi mendukung keterbukaan informasi dan pertanggungjawaban dalam penggunaan anggaran dan pelaksanaan kegiatan penanggulangan bencana.
3) Penguatan Kapasitas Institusi dan Komunitas Evaluasi membantu mengidentifikasi kelemahan dan kekuatan dalam sistem yang ada, serta memberikan rekomendasi untuk peningkatan kapasitas kelembagaan dan peran aktif masyarakat.
4) Peningkatan Respons dan Mitigasi Risiko Dengan informasi dari monitoring dan evaluasi, strategi penanggulangan bencana dapat lebih adaptif terhadap perubahan risiko dan kondisi lingkungan, sehingga meningkatkan kesiapsiagaan dan mempercepat pemulihan.', 'Lampiran hal. 88', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4374, 'perban-5-2025', 179, 'lampiran', 'Lampiran hal. 88', NULL, 88, 'Dengan melaksanakan pemantauan dan evaluasi secara konsisten, sistem penanggulangan bencana akan menjadi lebih tangguh.
BAB 3. ARAH KEBIJAKAN, STRATEGI, KERANGKA REGULASI, DAN KERANGKA KELEMBAGAAN Penyusunan kebijakan dan strategi dilakukan dengan mempertimbangkan dinamika lingkungan strategis, perkembangan isu kebencanaan, serta komitmen terhadap pencapaian visi dan misi BNPB. Dalam prosesnya, dilakukan pula identifikasi risiko terhadap setiap sasaran strategis, sebagai langkah mitigasi dini untuk memastikan efektivitas dan keberlanjutan program, sehingga langkah yang diambil tidak hanya responsif terhadap kebutuhan saat ini, tetapi juga tangguh menghadapi tantangan di masa depan.
Kerangka regulasi dan kelembagaan yang disusun akan menjadi instrumen penguat dalam mencapai sasaran strategis, sekaligus sebagai jaminan tata kelola penanggulangan bencana yang efektif, transparan, dan akuntabel.
Badan Nasional Penanggulangan Bencana (BNPB) merupakan Lembaga pemerintah non Kementerian yang dibentuk berdasarkan Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana dan Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4374, 'Dengan melaksanakan pemantauan dan evaluasi secara konsisten, sistem penanggulangan bencana akan menjadi lebih tangguh.
BAB 3. ARAH KEBIJAKAN, STRATEGI, KERANGKA REGULASI, DAN KERANGKA KELEMBAGAAN Penyusunan kebijakan dan strategi dilakukan dengan mempertimbangkan dinamika lingkungan strategis, perkembangan isu kebencanaan, serta komitmen terhadap pencapaian visi dan misi BNPB. Dalam prosesnya, dilakukan pula identifikasi risiko terhadap setiap sasaran strategis, sebagai langkah mitigasi dini untuk memastikan efektivitas dan keberlanjutan program, sehingga langkah yang diambil tidak hanya responsif terhadap kebutuhan saat ini, tetapi juga tangguh menghadapi tantangan di masa depan.
Kerangka regulasi dan kelembagaan yang disusun akan menjadi instrumen penguat dalam mencapai sasaran strategis, sekaligus sebagai jaminan tata kelola penanggulangan bencana yang efektif, transparan, dan akuntabel.
Badan Nasional Penanggulangan Bencana (BNPB) merupakan Lembaga pemerintah non Kementerian yang dibentuk berdasarkan Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana dan Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana.', 'Lampiran hal. 88', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4375, 'perban-5-2025', 180, 'lampiran', 'Lampiran hal. 89', NULL, 89, 'BNPB lembaga pemerintah yang memiliki mandat utama dalam mengoordinasikan serta menyelenggarakan penanggulangan bencana secara nasional. Dalam menjalankan perannya, BNPB memikul sejumlah tugas penting yang mencerminkan tanggung jawab negara dalam melindungi seluruh warga negara dari risiko bencana, serta memperkuat ketangguhan bangsa dalam menghadapi berbagai jenis ancaman bencana.
Salah satu tugas utama BNPB adalah memberikan pedoman dan pengarahan menyeluruh terhadap berbagai upaya penanggulangan bencana. Ini mencakup aspek pencegahan, penanganan keadaan darurat, serta rehabilitasi dan rekonstruksi pasca-bencana. Semua proses tersebut harus dilakukan secara adil dan setara, sehingga tidak ada pihak yang terabaikan, terutama kelompok masyarakat yang rentan.
Selain itu, BNPB juga bertanggung jawab dalam menetapkan standar dan kebutuhan teknis penyelenggaraan penanggulangan bencana. Penetapan ini dilakukan dengan merujuk pada peraturan perundang-undangan yang berlaku.
Standarisasi ini penting untuk menjamin keseragaman, kecepatan, dan efektivitas respons terhadap bencana di seluruh wilayah Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4375, 'BNPB lembaga pemerintah yang memiliki mandat utama dalam mengoordinasikan serta menyelenggarakan penanggulangan bencana secara nasional. Dalam menjalankan perannya, BNPB memikul sejumlah tugas penting yang mencerminkan tanggung jawab negara dalam melindungi seluruh warga negara dari risiko bencana, serta memperkuat ketangguhan bangsa dalam menghadapi berbagai jenis ancaman bencana.
Salah satu tugas utama BNPB adalah memberikan pedoman dan pengarahan menyeluruh terhadap berbagai upaya penanggulangan bencana. Ini mencakup aspek pencegahan, penanganan keadaan darurat, serta rehabilitasi dan rekonstruksi pasca-bencana. Semua proses tersebut harus dilakukan secara adil dan setara, sehingga tidak ada pihak yang terabaikan, terutama kelompok masyarakat yang rentan.
Selain itu, BNPB juga bertanggung jawab dalam menetapkan standar dan kebutuhan teknis penyelenggaraan penanggulangan bencana. Penetapan ini dilakukan dengan merujuk pada peraturan perundang-undangan yang berlaku.
Standarisasi ini penting untuk menjamin keseragaman, kecepatan, dan efektivitas respons terhadap bencana di seluruh wilayah Indonesia.', 'Lampiran hal. 89', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4376, 'perban-5-2025', 181, 'lampiran', 'Lampiran hal. 89', NULL, 89, 'BNPB juga memiliki tugas untuk menyampaikan informasi mengenai kegiatan penanggulangan bencana kepada masyarakat secara terbuka. Keterbukaan informasi ini bertujuan untuk meningkatkan kesadaran, kewaspadaan, dan partisipasi publik dalam mengantisipasi dan menghadapi bencana. Di sisi lain, BNPB juga wajib melaporkan pelaksanaan penanggulangan bencana kepada Presiden, yaitu setiap bulan dalam situasi normal dan setiap saat ketika terjadi kondisi darurat bencana, sebagai bentuk pertanggungjawaban terhadap pimpinan tertinggi negara.
Dalam hal pendanaan dan bantuan, BNPB memiliki wewenang untuk menggunakan dan mempertanggungjawabkan sumbangan atau bantuan, baik yang berasal dari dalam negeri maupun luar negeri. Setiap bantuan yang diterima dikelola secara transparan dan akuntabel untuk memastikan bahwa bantuan tersebut tepat sasaran dan memberikan manfaat optimal bagi para korban bencana.
Tugas berikutnya adalah mempertanggungjawabkan penggunaan anggaran yang berasal dari Anggaran Pendapatan dan Belanja Negara (APBN). BNPB harus memastikan bahwa seluruh dana negara yang digunakan dalam upaya penanggulangan bencana digunakan secara efisien dan sesuai dengan tujuan yang telah ditetapkan.
BNPB juga menjalankan berbagai kewajiban lain yang diamanatkan melalui peraturan perundang-undangan, sebagai bentuk adaptasi terhadap tantangan dan kebutuhan baru yang terus berkembang dalam konteks kebencanaan nasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4376, 'BNPB juga memiliki tugas untuk menyampaikan informasi mengenai kegiatan penanggulangan bencana kepada masyarakat secara terbuka. Keterbukaan informasi ini bertujuan untuk meningkatkan kesadaran, kewaspadaan, dan partisipasi publik dalam mengantisipasi dan menghadapi bencana. Di sisi lain, BNPB juga wajib melaporkan pelaksanaan penanggulangan bencana kepada Presiden, yaitu setiap bulan dalam situasi normal dan setiap saat ketika terjadi kondisi darurat bencana, sebagai bentuk pertanggungjawaban terhadap pimpinan tertinggi negara.
Dalam hal pendanaan dan bantuan, BNPB memiliki wewenang untuk menggunakan dan mempertanggungjawabkan sumbangan atau bantuan, baik yang berasal dari dalam negeri maupun luar negeri. Setiap bantuan yang diterima dikelola secara transparan dan akuntabel untuk memastikan bahwa bantuan tersebut tepat sasaran dan memberikan manfaat optimal bagi para korban bencana.
Tugas berikutnya adalah mempertanggungjawabkan penggunaan anggaran yang berasal dari Anggaran Pendapatan dan Belanja Negara (APBN). BNPB harus memastikan bahwa seluruh dana negara yang digunakan dalam upaya penanggulangan bencana digunakan secara efisien dan sesuai dengan tujuan yang telah ditetapkan.
BNPB juga menjalankan berbagai kewajiban lain yang diamanatkan melalui peraturan perundang-undangan, sebagai bentuk adaptasi terhadap tantangan dan kebutuhan baru yang terus berkembang dalam konteks kebencanaan nasional.', 'Lampiran hal. 89', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4377, 'perban-5-2025', 182, 'lampiran', 'Lampiran hal. 90', NULL, 90, 'Terakhir, BNPB bertugas untuk menyusun pedoman pembentukan Badan Penanggulangan Bencana Daerah (BPBD) di tingkat provinsi dan kabupaten/kota.
Langkah ini sangat penting guna memastikan bahwa setiap daerah memiliki kapasitas kelembagaan yang kuat dalam menghadapi bencana secara mandiri dan cepat.
Dengan menjalankan seluruh tugas tersebut, BNPB hadir sebagai pilar utama dalam sistem penanggulangan bencana nasional, sekaligus sebagai bentuk nyata kehadiran negara dalam melindungi rakyatnya dari risiko dan dampak bencana.
Dalam kerangka sistem penanggulangan bencana nasional, Badan Nasional Penanggulangan Bencana (BNPB) memegang peranan sentral sebagai lembaga yang diberikan mandat oleh negara untuk memastikan bahwa seluruh proses penanggulangan bencana di Indonesia berlangsung secara efektif, terkoordinasi, dan berkelanjutan. Keberadaan BNPB merupakan wujud nyata dari komitmen pemerintah dalam memberikan perlindungan kepada warga negara dari risiko dan dampak bencana, baik yang bersifat alam, nonalam, maupun sosial. Untuk mewujudkan tujuan tersebut, BNPB menjalankan fungsi-fungsi strategis yang saling terkait dan memperkuat satu sama lain.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4377, 'Terakhir, BNPB bertugas untuk menyusun pedoman pembentukan Badan Penanggulangan Bencana Daerah (BPBD) di tingkat provinsi dan kabupaten/kota.
Langkah ini sangat penting guna memastikan bahwa setiap daerah memiliki kapasitas kelembagaan yang kuat dalam menghadapi bencana secara mandiri dan cepat.
Dengan menjalankan seluruh tugas tersebut, BNPB hadir sebagai pilar utama dalam sistem penanggulangan bencana nasional, sekaligus sebagai bentuk nyata kehadiran negara dalam melindungi rakyatnya dari risiko dan dampak bencana.
Dalam kerangka sistem penanggulangan bencana nasional, Badan Nasional Penanggulangan Bencana (BNPB) memegang peranan sentral sebagai lembaga yang diberikan mandat oleh negara untuk memastikan bahwa seluruh proses penanggulangan bencana di Indonesia berlangsung secara efektif, terkoordinasi, dan berkelanjutan. Keberadaan BNPB merupakan wujud nyata dari komitmen pemerintah dalam memberikan perlindungan kepada warga negara dari risiko dan dampak bencana, baik yang bersifat alam, nonalam, maupun sosial. Untuk mewujudkan tujuan tersebut, BNPB menjalankan fungsi-fungsi strategis yang saling terkait dan memperkuat satu sama lain.', 'Lampiran hal. 90', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4378, 'perban-5-2025', 183, 'lampiran', 'Lampiran hal. 90', NULL, 90, 'Pertama, BNPB bertugas untuk merumuskan dan menetapkan norma, standar, prosedur, dan kriteria (NSPK), serta menyusun persyaratan dan prosedur perizinan dan/atau pemberian rekomendasi terkait penyelenggaraan penanggulangan bencana. Fungsi ini merupakan fondasi teknokratik dalam penanggulangan bencana, yang berfungsi memberikan arah, kejelasan, dan keseragaman dalam pelaksanaan kebijakan dan kegiatan kebencanaan oleh seluruh pemangku kepentingan. Dengan adanya NSPK yang kuat, maka penyelenggaraan penanggulangan bencana dapat dilakukan secara terukur, akuntabel, dan berbasis pada prinsip-prinsip terbaik di bidang kebencanaan, baik dari sisi regulasi, teknis operasional, hingga akreditasi kelembagaan dan sumber daya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4378, 'Pertama, BNPB bertugas untuk merumuskan dan menetapkan norma, standar, prosedur, dan kriteria (NSPK), serta menyusun persyaratan dan prosedur perizinan dan/atau pemberian rekomendasi terkait penyelenggaraan penanggulangan bencana. Fungsi ini merupakan fondasi teknokratik dalam penanggulangan bencana, yang berfungsi memberikan arah, kejelasan, dan keseragaman dalam pelaksanaan kebijakan dan kegiatan kebencanaan oleh seluruh pemangku kepentingan. Dengan adanya NSPK yang kuat, maka penyelenggaraan penanggulangan bencana dapat dilakukan secara terukur, akuntabel, dan berbasis pada prinsip-prinsip terbaik di bidang kebencanaan, baik dari sisi regulasi, teknis operasional, hingga akreditasi kelembagaan dan sumber daya.', 'Lampiran hal. 90', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4379, 'perban-5-2025', 184, 'lampiran', 'Lampiran hal. 90', NULL, 90, 'Kedua, BNPB memiliki tanggung jawab dalam merumuskan dan menetapkan kebijakan penanggulangan bencana dan penanganan pengungsi. Fungsi ini mencerminkan peran BNPB sebagai institusi pengambil kebijakan strategis yang bersifat lintas sektor dan lintas wilayah. Kebijakan yang disusun mencakup seluruh tahapan penanggulangan bencana, mulai dari mitigasi, kesiapsiagaan, tanggap darurat, hingga rehabilitasi dan rekonstruksi. Dalam hal penanganan pengungsi, BNPB memastikan bahwa setiap kebijakan didasarkan pada pendekatan yang humanis dan responsif terhadap kebutuhan kelompok rentan. Penetapan kebijakan ini harus dilakukan secara cepat dan tepat mengingat kondisi bencana yang kerap terjadi secara tiba-tiba dan memerlukan respons segera. Selain itu, BNPB juga dituntut untuk memastikan bahwa kebijakan yang diambil bersifat efektif dan efisien, tidak hanya dalam hal penggunaan sumber daya, tetapi juga dalam pencapaian tujuan perlindungan masyarakat dan percepatan pemulihan pascabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4379, 'Kedua, BNPB memiliki tanggung jawab dalam merumuskan dan menetapkan kebijakan penanggulangan bencana dan penanganan pengungsi. Fungsi ini mencerminkan peran BNPB sebagai institusi pengambil kebijakan strategis yang bersifat lintas sektor dan lintas wilayah. Kebijakan yang disusun mencakup seluruh tahapan penanggulangan bencana, mulai dari mitigasi, kesiapsiagaan, tanggap darurat, hingga rehabilitasi dan rekonstruksi. Dalam hal penanganan pengungsi, BNPB memastikan bahwa setiap kebijakan didasarkan pada pendekatan yang humanis dan responsif terhadap kebutuhan kelompok rentan. Penetapan kebijakan ini harus dilakukan secara cepat dan tepat mengingat kondisi bencana yang kerap terjadi secara tiba-tiba dan memerlukan respons segera. Selain itu, BNPB juga dituntut untuk memastikan bahwa kebijakan yang diambil bersifat efektif dan efisien, tidak hanya dalam hal penggunaan sumber daya, tetapi juga dalam pencapaian tujuan perlindungan masyarakat dan percepatan pemulihan pascabencana.', 'Lampiran hal. 90', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4380, 'perban-5-2025', 185, 'lampiran', 'Lampiran hal. 91', NULL, 91, 'Ketiga, BNPB menyelenggarakan fungsi pengoordinasian pelaksanaan kegiatan penanggulangan bencana. Fungsi ini merupakan kekuatan utama BNPB sebagai lembaga yang menjembatani dan mengarahkan keterlibatan berbagai aktor dalam sistem penanggulangan bencana nasional. Pengoordinasian ini dilakukan secara terencana, terpadu, dan menyeluruh, serta melibatkan berbagai komponen penting seperti kementerian dan lembaga pemerintah, pemerintah daerah, TNI, Polri, organisasi kemasyarakatan, dunia usaha, akademisi, media, dan komunitas relawan. Dalam menjalankan fungsi koordinatif ini, BNPB memastikan bahwa seluruh tahapan penanggulangan bencana berjalan dalam satu kesatuan kerangka kerja yang sinergis dan tidak berjalan sendiri-sendiri. Dengan demikian, setiap sumber daya yang tersedia dapat dimanfaatkan secara optimal dan risiko duplikasi maupun kekosongan peran dapat dihindari. Fungsi koordinasi yang dilakukan oleh BNPB tidak hanya terbatas pada situasi darurat, tetapi juga mencakup penguatan kapasitas kelembagaan daerah, harmonisasi perencanaan pembangunan dengan aspek pengurangan risiko bencana, serta fasilitasi pelatihan dan edukasi kebencanaan bagi masyarakat. Dalam hal ini, BNPB bertindak sebagai motor penggerak pembangunan ketangguhan bencana (disaster resilience) secara nasional, termasuk mendorong integrasi pengurangan risiko bencana ke dalam dokumen perencanaan pembangunan nasional dan daerah seperti RPJMN, RPJMD, dan Rencana Kontingensi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4380, 'Ketiga, BNPB menyelenggarakan fungsi pengoordinasian pelaksanaan kegiatan penanggulangan bencana. Fungsi ini merupakan kekuatan utama BNPB sebagai lembaga yang menjembatani dan mengarahkan keterlibatan berbagai aktor dalam sistem penanggulangan bencana nasional. Pengoordinasian ini dilakukan secara terencana, terpadu, dan menyeluruh, serta melibatkan berbagai komponen penting seperti kementerian dan lembaga pemerintah, pemerintah daerah, TNI, Polri, organisasi kemasyarakatan, dunia usaha, akademisi, media, dan komunitas relawan. Dalam menjalankan fungsi koordinatif ini, BNPB memastikan bahwa seluruh tahapan penanggulangan bencana berjalan dalam satu kesatuan kerangka kerja yang sinergis dan tidak berjalan sendiri-sendiri. Dengan demikian, setiap sumber daya yang tersedia dapat dimanfaatkan secara optimal dan risiko duplikasi maupun kekosongan peran dapat dihindari. Fungsi koordinasi yang dilakukan oleh BNPB tidak hanya terbatas pada situasi darurat, tetapi juga mencakup penguatan kapasitas kelembagaan daerah, harmonisasi perencanaan pembangunan dengan aspek pengurangan risiko bencana, serta fasilitasi pelatihan dan edukasi kebencanaan bagi masyarakat. Dalam hal ini, BNPB bertindak sebagai motor penggerak pembangunan ketangguhan bencana (disaster resilience) secara nasional, termasuk mendorong integrasi pengurangan risiko bencana ke dalam dokumen perencanaan pembangunan nasional dan daerah seperti RPJMN, RPJMD, dan Rencana Kontingensi.', 'Lampiran hal. 91', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4381, 'perban-5-2025', 186, 'lampiran', 'Lampiran hal. 91', NULL, 91, 'Melalui pelaksanaan ketiga fungsi utama tersebut, BNPB tidak hanya bertindak sebagai pelaksana tugas teknis kebencanaan, tetapi juga sebagai lembaga yang merumuskan arah kebijakan nasional, membangun sistem kelembagaan yang responsif dan adaptif terhadap perubahan risiko, serta menciptakan ekosistem kolaboratif yang melibatkan seluruh elemen bangsa. Peran BNPB menjadi semakin penting dalam menghadapi kompleksitas bencana yang semakin meningkat, baik dari segi frekuensi, intensitas, maupun dampaknya terhadap aspek sosial, ekonomi, dan lingkungan. Oleh karena itu, penguatan fungsi-fungsi BNPB ke depan menjadi hal yang mutlak, guna memastikan bahwa Indonesia mampu membangun sistem penanggulangan bencana yang tangguh, inklusif, dan berkelanjutan.
Untuk mendukung capaian sasaran utama RPJMN tersebut, maka BNPB telah menetapkan dua sasaran strategis yaitu pertama “Resiliensi terhadap Bencana”, dan telah dilengkapi dengan identifikasi indikasi risiko, sebagai berikut:
1. Sasaran strategis pertama adalah Resiliensi Terhadap Bencana dengan risiko yang diidentifikasi yaitu:
a. Peningkatan Risiko Bencana Akibat Perubahan Iklim yang ekstrem dan sulit diprediksi. Adapun perlakuan terhadap risiko adalah melaksanakan Pengurangan Risiko Bencana yang bersifat Adaptif terhadap Perubahan Iklim dengan unit penanggungjawab Direktorat Pemetaan dan Evaluasi Risiko Bencana.
b. Keterbatasan jumlah infrastruktur early warning system yang tersedia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4381, 'Melalui pelaksanaan ketiga fungsi utama tersebut, BNPB tidak hanya bertindak sebagai pelaksana tugas teknis kebencanaan, tetapi juga sebagai lembaga yang merumuskan arah kebijakan nasional, membangun sistem kelembagaan yang responsif dan adaptif terhadap perubahan risiko, serta menciptakan ekosistem kolaboratif yang melibatkan seluruh elemen bangsa. Peran BNPB menjadi semakin penting dalam menghadapi kompleksitas bencana yang semakin meningkat, baik dari segi frekuensi, intensitas, maupun dampaknya terhadap aspek sosial, ekonomi, dan lingkungan. Oleh karena itu, penguatan fungsi-fungsi BNPB ke depan menjadi hal yang mutlak, guna memastikan bahwa Indonesia mampu membangun sistem penanggulangan bencana yang tangguh, inklusif, dan berkelanjutan.
Untuk mendukung capaian sasaran utama RPJMN tersebut, maka BNPB telah menetapkan dua sasaran strategis yaitu pertama “Resiliensi terhadap Bencana”, dan telah dilengkapi dengan identifikasi indikasi risiko, sebagai berikut:
1. Sasaran strategis pertama adalah Resiliensi Terhadap Bencana dengan risiko yang diidentifikasi yaitu:
a. Peningkatan Risiko Bencana Akibat Perubahan Iklim yang ekstrem dan sulit diprediksi. Adapun perlakuan terhadap risiko adalah melaksanakan Pengurangan Risiko Bencana yang bersifat Adaptif terhadap Perubahan Iklim dengan unit penanggungjawab Direktorat Pemetaan dan Evaluasi Risiko Bencana.
b. Keterbatasan jumlah infrastruktur early warning system yang tersedia.', 'Lampiran hal. 91', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4382, 'perban-5-2025', 187, 'lampiran', 'Lampiran hal. 91', NULL, 91, 'Adapun perlakuan terhadap risiko dengan melakukan penguatan sinergi lintas sektor untuk memperluas cakupan EWS dan memanfaatkan kearifan lokal di wilayah masing-masing dengan unit penanggung jawab Direktorat Peringatan Dini.
c. Kurangnya tingkat partisipasi dan kesadaran masyarakat dalam memahami risiko bencana di wilayah masing-masing. Adapun perlakuan terhadap risiko adalah dengan melakukan edukasi berbasis komunitas, pelatihan dan simulasi kebencanaan secara rutin dengan unit penanggungjawab Direktorat Mitigasi Bencana.
2. Sasaran strategis yang kedua Meningkatnya Kualitas Tata Kelola BNPB dengan risiko yang diidentifikasi yaitu:
a. masih terbatasnya pelatihan atau bimbingan teknis yang ditujukan untuk meningkatkan kapasitas sumber daya manusia, khususnya dalam aspek tata kelola dan manajerial. Keterbatasan ini berpotensi menghambat optimalisasi kinerja organisasi, karena kemampuan SDM dalam mengelola program, mengatur sumber daya, serta mengambil keputusan strategis menjadi kurang maksimal. Untuk mengurangi risiko tersebut, diperlukan langkah-langkah perlakuan yang terencana dan terstruktur. Upaya yang akan dilakukan meliputi pemetaan kebutuhan pelatihan secara menyeluruh, sehingga program yang dirancang dapat benar-benar menjawab kekurangan yang ada.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4382, 'Adapun perlakuan terhadap risiko dengan melakukan penguatan sinergi lintas sektor untuk memperluas cakupan EWS dan memanfaatkan kearifan lokal di wilayah masing-masing dengan unit penanggung jawab Direktorat Peringatan Dini.
c. Kurangnya tingkat partisipasi dan kesadaran masyarakat dalam memahami risiko bencana di wilayah masing-masing. Adapun perlakuan terhadap risiko adalah dengan melakukan edukasi berbasis komunitas, pelatihan dan simulasi kebencanaan secara rutin dengan unit penanggungjawab Direktorat Mitigasi Bencana.
2. Sasaran strategis yang kedua Meningkatnya Kualitas Tata Kelola BNPB dengan risiko yang diidentifikasi yaitu:
a. masih terbatasnya pelatihan atau bimbingan teknis yang ditujukan untuk meningkatkan kapasitas sumber daya manusia, khususnya dalam aspek tata kelola dan manajerial. Keterbatasan ini berpotensi menghambat optimalisasi kinerja organisasi, karena kemampuan SDM dalam mengelola program, mengatur sumber daya, serta mengambil keputusan strategis menjadi kurang maksimal. Untuk mengurangi risiko tersebut, diperlukan langkah-langkah perlakuan yang terencana dan terstruktur. Upaya yang akan dilakukan meliputi pemetaan kebutuhan pelatihan secara menyeluruh, sehingga program yang dirancang dapat benar-benar menjawab kekurangan yang ada.', 'Lampiran hal. 91', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4383, 'perban-5-2025', 188, 'lampiran', 'Lampiran hal. 92', NULL, 92, 'Selanjutnya, akan disusun dan dilaksanakan program pelatihan SDM kebencanaan yang komprehensif, tidak hanya berfokus pada kemampuan teknis kebencanaan, tetapi juga mencakup penguatan aspek tata kelola dan manajerial. Program ini akan diampu oleh Biro SDM dan Umum, yang memiliki peran strategis dalam memastikan pelatihan berjalan sesuai kebutuhan, terukur hasilnya, dan berkelanjutan.
b. Masih terdapat kesenjangan regulasi yang berpotensi menghambat efektivitas pelaksanaan tugas dan fungsi organisasi. Hal ini disebabkan belum optimalnya sinkronisasi antara kebijakan internal dan regulasi terkait. Untuk mengatasinya, dilakukan penguatan kebijakan internal dan harmonisasi regulasi guna mewujudkan tata kelola organisasi yang adaptif, responsif, dan selaras dengan kebutuhan penanggulangan bencana. Penanggung jawab pelaksanaan langkah ini adalah Biro Hukum, Organisasi, dan Kerjasama.
c. Pembangunan Zona Integritas di lingkungan BNPB masih belum optimal, sehingga target reformasi birokrasi dan peningkatan tata kelola belum sepenuhnya tercapai. Untuk mengatasi hal ini, akan dilakukan pembangunan Zona Integritas pada unit kerja yang memenuhi syarat untuk diajukan kepada KemenPAN RB setiap tahun, dengan capaian WBK/WBBM, WTP, serta pelaporan LHKPN/LHKASN 100%. Pelaksanaan langkah ini menjadi tanggung jawab Inspektorat, dengan dukungan Biro Hukum, Organisasi, dan Kerjasama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4383, 'Selanjutnya, akan disusun dan dilaksanakan program pelatihan SDM kebencanaan yang komprehensif, tidak hanya berfokus pada kemampuan teknis kebencanaan, tetapi juga mencakup penguatan aspek tata kelola dan manajerial. Program ini akan diampu oleh Biro SDM dan Umum, yang memiliki peran strategis dalam memastikan pelatihan berjalan sesuai kebutuhan, terukur hasilnya, dan berkelanjutan.
b. Masih terdapat kesenjangan regulasi yang berpotensi menghambat efektivitas pelaksanaan tugas dan fungsi organisasi. Hal ini disebabkan belum optimalnya sinkronisasi antara kebijakan internal dan regulasi terkait. Untuk mengatasinya, dilakukan penguatan kebijakan internal dan harmonisasi regulasi guna mewujudkan tata kelola organisasi yang adaptif, responsif, dan selaras dengan kebutuhan penanggulangan bencana. Penanggung jawab pelaksanaan langkah ini adalah Biro Hukum, Organisasi, dan Kerjasama.
c. Pembangunan Zona Integritas di lingkungan BNPB masih belum optimal, sehingga target reformasi birokrasi dan peningkatan tata kelola belum sepenuhnya tercapai. Untuk mengatasi hal ini, akan dilakukan pembangunan Zona Integritas pada unit kerja yang memenuhi syarat untuk diajukan kepada KemenPAN RB setiap tahun, dengan capaian WBK/WBBM, WTP, serta pelaporan LHKPN/LHKASN 100%. Pelaksanaan langkah ini menjadi tanggung jawab Inspektorat, dengan dukungan Biro Hukum, Organisasi, dan Kerjasama.', 'Lampiran hal. 92', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4384, 'perban-5-2025', 189, 'lampiran', 'Lampiran hal. 92', NULL, 92, 'd. Tingkat tindak lanjut pengaduan masyarakat melalui LAPOR masih belum maksimal, sehingga penyelesaian laporan belum sepenuhnya optimal. Untuk mengatasi hal ini, akan disusun rencana aksi pengelolaan pengaduan serta dilakukan integrasi layanan pengaduan, baik manual maupun berbasis aplikasi, dengan LAPOR dan layanan dari unit kerja lain. Penanggung jawab pelaksanaan langkah ini adalah Pusat Data, Informasi, dan Komunikasi Kebencanaan.
e. Belum berpartisipasi dalam pengukuran nasional Indeks Kualitas Kebijakan (IKK). Ke depan, akan berpartisipasi dalam pengukuran nasional IKK yang diselenggarakan oleh LAN, dengan penanggung jawab pelaksana Biro Hukum, Organisasi, dan Kerja Sama.
f. Belum berpartisipasi dalam pengukuran nasional Indeks Reformasi Hukum (IRH). Ke depan, akan berpartisipasi dalam pengukuran nasional IRH yang diselenggarakan oleh Kementerian Hukum dan HAM, dengan penanggung jawab pelaksana Biro Hukum, Organisasi, dan Kerja Sama.
g. Masih perlu peningkatan penerapan aspek metadata statistik pada kegiatan, variabel, dan indikator. Perlakuan terhadap risiko dilakukan dengan menyusun prosedur baku untuk menjamin kualitas data, khususnya terkait relevansi, pemantauan, dan penyediaan format data, dengan penanggung jawab Pusat Data, Informasi, dan Komunikasi Kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4384, 'd. Tingkat tindak lanjut pengaduan masyarakat melalui LAPOR masih belum maksimal, sehingga penyelesaian laporan belum sepenuhnya optimal. Untuk mengatasi hal ini, akan disusun rencana aksi pengelolaan pengaduan serta dilakukan integrasi layanan pengaduan, baik manual maupun berbasis aplikasi, dengan LAPOR dan layanan dari unit kerja lain. Penanggung jawab pelaksanaan langkah ini adalah Pusat Data, Informasi, dan Komunikasi Kebencanaan.
e. Belum berpartisipasi dalam pengukuran nasional Indeks Kualitas Kebijakan (IKK). Ke depan, akan berpartisipasi dalam pengukuran nasional IKK yang diselenggarakan oleh LAN, dengan penanggung jawab pelaksana Biro Hukum, Organisasi, dan Kerja Sama.
f. Belum berpartisipasi dalam pengukuran nasional Indeks Reformasi Hukum (IRH). Ke depan, akan berpartisipasi dalam pengukuran nasional IRH yang diselenggarakan oleh Kementerian Hukum dan HAM, dengan penanggung jawab pelaksana Biro Hukum, Organisasi, dan Kerja Sama.
g. Masih perlu peningkatan penerapan aspek metadata statistik pada kegiatan, variabel, dan indikator. Perlakuan terhadap risiko dilakukan dengan menyusun prosedur baku untuk menjamin kualitas data, khususnya terkait relevansi, pemantauan, dan penyediaan format data, dengan penanggung jawab Pusat Data, Informasi, dan Komunikasi Kebencanaan.', 'Lampiran hal. 92', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4385, 'perban-5-2025', 190, 'lampiran', 'Lampiran hal. 93', NULL, 93, 'h. Belum ada keterisian JF PPBJ (kurang dari 60%) dan level kematangan tata kelola pengadaan belum mencapai level 3. Perlakuan terhadap risiko dilakukan dengan menghitung kembali kebutuhan formasi untuk memastikan jumlah yang tepat serta membentuk tim khusus guna mengakselerasi capaian kematangan Level 3, dengan penanggung jawab Biro Hukum, Organisasi, dan Kerjasama.
3.1. Arah Kebijakan dan Strategi Nasional Arah kebijakan nasional yang menjadi acuan dalam penanggulangan bencana di Indonesia adalah RIPB Tahun 2020-2044, RPJP Tahun 2025-2045, dan RPJMN Tahun 2025-2029, dan arahan-arahan dalam Renas PB Tahun 2025-2029.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4385, 'h. Belum ada keterisian JF PPBJ (kurang dari 60%) dan level kematangan tata kelola pengadaan belum mencapai level 3. Perlakuan terhadap risiko dilakukan dengan menghitung kembali kebutuhan formasi untuk memastikan jumlah yang tepat serta membentuk tim khusus guna mengakselerasi capaian kematangan Level 3, dengan penanggung jawab Biro Hukum, Organisasi, dan Kerjasama.
3.1. Arah Kebijakan dan Strategi Nasional Arah kebijakan nasional yang menjadi acuan dalam penanggulangan bencana di Indonesia adalah RIPB Tahun 2020-2044, RPJP Tahun 2025-2045, dan RPJMN Tahun 2025-2029, dan arahan-arahan dalam Renas PB Tahun 2025-2029.', 'Lampiran hal. 93', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4386, 'perban-5-2025', 191, 'lampiran', 'Lampiran hal. 93', NULL, 93, 'Kegiatan prioritas penanggulangan bencana diarahkan untuk membangun ketahanan nasional yang menyeluruh, dimulai dari penguatan upaya pencegahan dan mitigasi untuk meminimalkan risiko sebelum bencana terjadi. Langkah ini mencakup identifikasi dan pemetaan potensi bahaya, pembangunan infrastruktur yang tangguh, penerapan tata ruang berbasis mitigasi, serta peningkatan kesadaran dan partisipasi masyarakat. Pencegahan tersebut diperkuat oleh layanan peringatan dini dan penanganan kedaruratan yang andal, melalui pemanfaatan teknologi modern yang menjangkau seluruh wilayah rawan, peningkatan kapasitas personel tanggap darurat, dan koordinasi lintas sektor yang terpadu agar respons dapat dilakukan secara cepat, tepat, dan efektif. Pada tahap pascabencana, fokus diarahkan pada pemenuhan kebutuhan rehabilitasi dan rekonstruksi untuk memulihkan fungsi vital, layanan publik, dan kehidupan sosial ekonomi masyarakat, dengan mengedepankan prinsip build back better agar hasil pembangunan lebih aman dan berkelanjutan. Seluruh upaya ini berpuncak pada peningkatan resiliensi masyarakat, melalui pemberdayaan komunitas, penguatan kapasitas kelompok rentan, pembentukan desa atau kelurahan tangguh bencana, serta pengembangan jejaring kemitraan yang memperkuat kesiapsiagaan dan kemampuan adaptasi bersama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4386, 'Kegiatan prioritas penanggulangan bencana diarahkan untuk membangun ketahanan nasional yang menyeluruh, dimulai dari penguatan upaya pencegahan dan mitigasi untuk meminimalkan risiko sebelum bencana terjadi. Langkah ini mencakup identifikasi dan pemetaan potensi bahaya, pembangunan infrastruktur yang tangguh, penerapan tata ruang berbasis mitigasi, serta peningkatan kesadaran dan partisipasi masyarakat. Pencegahan tersebut diperkuat oleh layanan peringatan dini dan penanganan kedaruratan yang andal, melalui pemanfaatan teknologi modern yang menjangkau seluruh wilayah rawan, peningkatan kapasitas personel tanggap darurat, dan koordinasi lintas sektor yang terpadu agar respons dapat dilakukan secara cepat, tepat, dan efektif. Pada tahap pascabencana, fokus diarahkan pada pemenuhan kebutuhan rehabilitasi dan rekonstruksi untuk memulihkan fungsi vital, layanan publik, dan kehidupan sosial ekonomi masyarakat, dengan mengedepankan prinsip build back better agar hasil pembangunan lebih aman dan berkelanjutan. Seluruh upaya ini berpuncak pada peningkatan resiliensi masyarakat, melalui pemberdayaan komunitas, penguatan kapasitas kelompok rentan, pembentukan desa atau kelurahan tangguh bencana, serta pengembangan jejaring kemitraan yang memperkuat kesiapsiagaan dan kemampuan adaptasi bersama.', 'Lampiran hal. 93', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4387, 'perban-5-2025', 192, 'lampiran', 'Lampiran hal. 93', NULL, 93, '3.1.1. Rencana Induk Penanggulangan Bencana 2020-2044 Rencana Induk Penanggulangan Bencana (RIPB) merupakan pedoman nasional untuk penyelenggaraan Penanggulangan bencana yang berlaku selama 25 tahun dan menjadi acuan Kementerian atau Lembaga, Tentara Nasional Indonesia, Kepolisian Negara Republik Indonesia, dan Pemerintah Daerah. Berdasarkan Peraturan Presiden Nomor 87 Tahun 2020, RIPB ditetapkan untuk periode 2020- 2044 mengacu pada periode Rencana Pembangunan Jangka Panjang Nasional (RPJPN) pertama yang berakhir pada tahun 2025, dan periode RPJPN kedua tahun 2025-2045. sebagai acuan penanggulangan bencana jangka panjang, RIPB menjadi acuan wajib dalam penyusunan Renstra BNPB.
RIPB Tahun 2020-2044 memiliki visi “Mewujudkan Indonesia Tangguh Bencana untuk Pembangunan Berkelanjutan”. Tangguh bencana bermakna bahwa Indonesia mampu menahan, menyerap, beradaptasi, dan memulihkan diri dari akibat bencana dan perubahan iklim secara tepat waktu, efektif, dan efisien. Adapun misi untuk mewujudkan misi tersebut yaitu:
1. Mewujudkan penanggulangan bencana yang tangguh dan berkelanjutan;
2. Mewujudkan tata kelola penanggulangan bencana yang profesional dan inklusif;
3. Mewujudkan penanganan darurat bencana dan pemulihan pasca bencana yang prima.
Berikut merupakan tujuan, sasaran, kebijakan, strategi, serta fokus capaian pada periode 2025-2029.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4387, '3.1.1. Rencana Induk Penanggulangan Bencana 2020-2044 Rencana Induk Penanggulangan Bencana (RIPB) merupakan pedoman nasional untuk penyelenggaraan Penanggulangan bencana yang berlaku selama 25 tahun dan menjadi acuan Kementerian atau Lembaga, Tentara Nasional Indonesia, Kepolisian Negara Republik Indonesia, dan Pemerintah Daerah. Berdasarkan Peraturan Presiden Nomor 87 Tahun 2020, RIPB ditetapkan untuk periode 2020- 2044 mengacu pada periode Rencana Pembangunan Jangka Panjang Nasional (RPJPN) pertama yang berakhir pada tahun 2025, dan periode RPJPN kedua tahun 2025-2045. sebagai acuan penanggulangan bencana jangka panjang, RIPB menjadi acuan wajib dalam penyusunan Renstra BNPB.
RIPB Tahun 2020-2044 memiliki visi “Mewujudkan Indonesia Tangguh Bencana untuk Pembangunan Berkelanjutan”. Tangguh bencana bermakna bahwa Indonesia mampu menahan, menyerap, beradaptasi, dan memulihkan diri dari akibat bencana dan perubahan iklim secara tepat waktu, efektif, dan efisien. Adapun misi untuk mewujudkan misi tersebut yaitu:
1. Mewujudkan penanggulangan bencana yang tangguh dan berkelanjutan;
2. Mewujudkan tata kelola penanggulangan bencana yang profesional dan inklusif;
3. Mewujudkan penanganan darurat bencana dan pemulihan pasca bencana yang prima.
Berikut merupakan tujuan, sasaran, kebijakan, strategi, serta fokus capaian pada periode 2025-2029.', 'Lampiran hal. 93', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4388, 'perban-5-2025', 193, 'lampiran', 'Lampiran hal. 94', NULL, 94, 'TUJUAN "Meningkatkan ketangguhan Pemerintah, Pemerintah Daerah, dan Masyarakat dalam menghadapi bencana, serta mengurangi risiko bencana dalam jangka panjang" SASARAN
1. Kerangka peraturan perundang-undangan yang kuat & keterpaduan kelembagaan yang adaptif dalam PB.
2. Peningkatan investasi kesiapsiagaan & pengelolaan risiko bencana sesuai dengan proyeksi risiko bencana.
3. Peningkatan kualitas tata kelola PB yang profesional, transparan, dan akuntabel.
4. Penanganan darurat bencana yang cepat & andal.
5. Pemulihan infrastruktur, pelayanan publik, dan penghidupan masyarakat pascabencana yang lebih baik & aman.
KEBIJAKAN, STRATEGI DAN FOKUS CAPAIAN 2025-2029 Kebijakan 1. Penguatan Peraturan Perundang-undangan Penanggulangan bencana yang efektif dan efisien Strategi:
1. Meningkatkan kualitas perangkat peraturan perundang-undangan dan implementasi dalam penanggulangan bencana yang adaptif dan berkelanjutan.
2. Meningkatkan kualitas norma, standar, prosedur, dan kriteria penanggulangan bencana.
Fokus Capaian 1: Terwujudnya peraturan perundang-undangan yang harmonis di bidang penanggulangan bencana.
Kebijakan 2. Peningkatan sinergi antar kementerian/ lembaga dan pemangku kepentingan dalam penanggulangan bencana.
Strategi:
1. Meningkatkan koordinasi dan kerja sama antar kementerian/lembaga, pemerintah daerah, Tentara Nasional Indonesia, Kepolisian Negara Republik Indonesia, akademisi, lembaga usaha, masyarakat, media, dan pemangku kepentingan lainnya dalam penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4388, 'TUJUAN "Meningkatkan ketangguhan Pemerintah, Pemerintah Daerah, dan Masyarakat dalam menghadapi bencana, serta mengurangi risiko bencana dalam jangka panjang" SASARAN
1. Kerangka peraturan perundang-undangan yang kuat & keterpaduan kelembagaan yang adaptif dalam PB.
2. Peningkatan investasi kesiapsiagaan & pengelolaan risiko bencana sesuai dengan proyeksi risiko bencana.
3. Peningkatan kualitas tata kelola PB yang profesional, transparan, dan akuntabel.
4. Penanganan darurat bencana yang cepat & andal.
5. Pemulihan infrastruktur, pelayanan publik, dan penghidupan masyarakat pascabencana yang lebih baik & aman.
KEBIJAKAN, STRATEGI DAN FOKUS CAPAIAN 2025-2029 Kebijakan 1. Penguatan Peraturan Perundang-undangan Penanggulangan bencana yang efektif dan efisien Strategi:
1. Meningkatkan kualitas perangkat peraturan perundang-undangan dan implementasi dalam penanggulangan bencana yang adaptif dan berkelanjutan.
2. Meningkatkan kualitas norma, standar, prosedur, dan kriteria penanggulangan bencana.
Fokus Capaian 1: Terwujudnya peraturan perundang-undangan yang harmonis di bidang penanggulangan bencana.
Kebijakan 2. Peningkatan sinergi antar kementerian/ lembaga dan pemangku kepentingan dalam penanggulangan bencana.
Strategi:
1. Meningkatkan koordinasi dan kerja sama antar kementerian/lembaga, pemerintah daerah, Tentara Nasional Indonesia, Kepolisian Negara Republik Indonesia, akademisi, lembaga usaha, masyarakat, media, dan pemangku kepentingan lainnya dalam penanggulangan bencana.', 'Lampiran hal. 94', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4389, 'perban-5-2025', 194, 'lampiran', 'Lampiran hal. 94', NULL, 94, 'Fokus Capaian 2: Terwujudnya kemandirian teknologi dan industrialisasi kebencanaan.
2. Mewujudkan dan meningkatkan sistem peringatan dini, data, dan layanan informasi kebencanaan yang terpadu dan berkesinambungan berdasarkan prinsip-prinsip kebijakan satu peta dan satu data.
Fokus Capaian 3: Terwujudnya kemudahan akses layanan peringatan dini terpadu multi ancaman.
Kebijakan 3. Penguatan Investasi pengelolaan risiko bencana sesuai dengan proyeksi peningkatan risiko bencana dengan memperhatikan tata ruang dan penataan kawasan.
Strategi:
1. Melaksanakan dan mengembangkan program kesiapsiagaan dan pengelolaan risiko bencana dengan memperhatikan tata ruang dan penataan kawasan.
2. Meningkatkan investasi dan pemanfaatan berbagai skema pendanaan inovatif termasuk transfer risiko untuk penanggulangan bencana.
Fokus Capaian 4: Terwujudnya investasi yang memadai dalam pengurangan risiko bencana untuk ketangguhan
3. Mengoptimalkan pendanaan secara terpadu untuk penanggulangan bencana Fokus capaian 5: Terwujudnya tata kelola risiko bencana yang sinergis antara pusat dan daerah Kebijakan 4. Penguatan tata kelola penanggulangan bencana yang semakin profesional, transparan, dan akuntabel.
Strategi:
1. Meningkatkan kapasitas dan profesionalisme para penyelenggara dan pelaku penanggulangan bencana.
2. Mengoptimalkan pelaksanaan standar pelayanan minimal penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4389, 'Fokus Capaian 2: Terwujudnya kemandirian teknologi dan industrialisasi kebencanaan.
2. Mewujudkan dan meningkatkan sistem peringatan dini, data, dan layanan informasi kebencanaan yang terpadu dan berkesinambungan berdasarkan prinsip-prinsip kebijakan satu peta dan satu data.
Fokus Capaian 3: Terwujudnya kemudahan akses layanan peringatan dini terpadu multi ancaman.
Kebijakan 3. Penguatan Investasi pengelolaan risiko bencana sesuai dengan proyeksi peningkatan risiko bencana dengan memperhatikan tata ruang dan penataan kawasan.
Strategi:
1. Melaksanakan dan mengembangkan program kesiapsiagaan dan pengelolaan risiko bencana dengan memperhatikan tata ruang dan penataan kawasan.
2. Meningkatkan investasi dan pemanfaatan berbagai skema pendanaan inovatif termasuk transfer risiko untuk penanggulangan bencana.
Fokus Capaian 4: Terwujudnya investasi yang memadai dalam pengurangan risiko bencana untuk ketangguhan
3. Mengoptimalkan pendanaan secara terpadu untuk penanggulangan bencana Fokus capaian 5: Terwujudnya tata kelola risiko bencana yang sinergis antara pusat dan daerah Kebijakan 4. Penguatan tata kelola penanggulangan bencana yang semakin profesional, transparan, dan akuntabel.
Strategi:
1. Meningkatkan kapasitas dan profesionalisme para penyelenggara dan pelaku penanggulangan bencana.
2. Mengoptimalkan pelaksanaan standar pelayanan minimal penanggulangan bencana.', 'Lampiran hal. 94', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4390, 'perban-5-2025', 195, 'lampiran', 'Lampiran hal. 94', NULL, 94, 'Fokus Capaian 6: Terwujudnya pemahaman terhadap risiko bencana, bentang alam, dan adaptasi perubahan iklim, serta ketahanan sosial dan ketahanan kesehatan masyarakat.
3. Meningkatkan keterbukaan informasi dan komunikasi, kualitas sistem perencanaan, serta pemantauan dan evaluasi dalam penanggulangan bencana Fokus Capaian 7: Terwujudnya penanganan darurat bencana secara cepat, efektif, dan terkoordinasi
4. Mendorong pelibatan pemangku kepentingan dalam tata kelola penanggulangan bencana untuk meningkatkan akuntabilitas.
5. Mewujudkan kabupaten kota, desa/kelurahan, dan masyarakat tangguh bencana.
Fokus Capaian 8: Terwujudnya penataan ruang dan permukiman serta perencanaan perkotaan yang terpadu terhadap ketahanan bencana dan adaptasi perubahan iklim, serta ketahanan sosial dan ketahanan masyarakat
6. Mewujudkan sarana dan prasarana yang tangguh terhadap bencana.
7. Meningkatkan edukasi kebencanaan dan pengelolaan pengetahuan penanggulangan bencana kepada masyarakat dan pemangku kepentingan.
Fokus Capaian 9: Terwujudnya perlindungan ekosistem laut dan pesisir yang berisiko bencana Kebijakan 5. Peningkatan kapasitas dan kapabilitas penanganan kedaruratan bencana yang cepat dan andal.
Strategi:
1. Meningkatkan kuantitas dan kualitas sumber daya manusia dalam penanganan darurat bencana.
2. Meningkatkan kesiapan dan keandalan logistik dan peralatan penanganan darurat bencana.
3. Mengoptimalkan pengelolaan bantuan masyarakat dalam penanganan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4390, 'Fokus Capaian 6: Terwujudnya pemahaman terhadap risiko bencana, bentang alam, dan adaptasi perubahan iklim, serta ketahanan sosial dan ketahanan kesehatan masyarakat.
3. Meningkatkan keterbukaan informasi dan komunikasi, kualitas sistem perencanaan, serta pemantauan dan evaluasi dalam penanggulangan bencana Fokus Capaian 7: Terwujudnya penanganan darurat bencana secara cepat, efektif, dan terkoordinasi
4. Mendorong pelibatan pemangku kepentingan dalam tata kelola penanggulangan bencana untuk meningkatkan akuntabilitas.
5. Mewujudkan kabupaten kota, desa/kelurahan, dan masyarakat tangguh bencana.
Fokus Capaian 8: Terwujudnya penataan ruang dan permukiman serta perencanaan perkotaan yang terpadu terhadap ketahanan bencana dan adaptasi perubahan iklim, serta ketahanan sosial dan ketahanan masyarakat
6. Mewujudkan sarana dan prasarana yang tangguh terhadap bencana.
7. Meningkatkan edukasi kebencanaan dan pengelolaan pengetahuan penanggulangan bencana kepada masyarakat dan pemangku kepentingan.
Fokus Capaian 9: Terwujudnya perlindungan ekosistem laut dan pesisir yang berisiko bencana Kebijakan 5. Peningkatan kapasitas dan kapabilitas penanganan kedaruratan bencana yang cepat dan andal.
Strategi:
1. Meningkatkan kuantitas dan kualitas sumber daya manusia dalam penanganan darurat bencana.
2. Meningkatkan kesiapan dan keandalan logistik dan peralatan penanganan darurat bencana.
3. Mengoptimalkan pengelolaan bantuan masyarakat dalam penanganan darurat bencana.', 'Lampiran hal. 94', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4391, 'perban-5-2025', 196, 'lampiran', 'Lampiran hal. 95', NULL, 95, '4. Menguatkan kualitas kelembagaan dan penggunaan ilmu pengetahuan dan teknologi.
5. Mempercepat pemulihan sarana dan prasarana vital.
Fokus Capaian 10: Tersedianya sumber daya manusia yang memiliki keahlian dan profesional di bidang kebencanaan.
Kebijakan 6. Percepatan pemulihan pascabencana pada daerah dan masyarakat terdampak bencana untuk membangun kehidupan yang lebih baik.
Strategi:
1. Mengoptimalkan perencanaan rehabilitasi dan rekonstruksi pascabencana berdasarkan tata ruang yang peka risiko bencana.
Fokus Capaian 11: Terwujudnya pemulihan daerah terdampak bencana yang lebih baik, aman, dan berkelanjutan dengan memperhatikan pengurangan risiko bencana
2. Meningkatkan kualitas penghidupan masyarakat terdampak bencana yang lebih baik.
3. Mewujudkan infrastruktur, perumahan, dan permukiman berketahanan bencana.
4. Meningkatkan kualitas pemulihan sosial ekonomi, sumber daya alam, dan lingkungan hidup.
Fokus Capaian 12: Terwujudnya infrastruktur yang berkualitas, andal, serta berkelanjutan dan tangguh bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4391, '4. Menguatkan kualitas kelembagaan dan penggunaan ilmu pengetahuan dan teknologi.
5. Mempercepat pemulihan sarana dan prasarana vital.
Fokus Capaian 10: Tersedianya sumber daya manusia yang memiliki keahlian dan profesional di bidang kebencanaan.
Kebijakan 6. Percepatan pemulihan pascabencana pada daerah dan masyarakat terdampak bencana untuk membangun kehidupan yang lebih baik.
Strategi:
1. Mengoptimalkan perencanaan rehabilitasi dan rekonstruksi pascabencana berdasarkan tata ruang yang peka risiko bencana.
Fokus Capaian 11: Terwujudnya pemulihan daerah terdampak bencana yang lebih baik, aman, dan berkelanjutan dengan memperhatikan pengurangan risiko bencana
2. Meningkatkan kualitas penghidupan masyarakat terdampak bencana yang lebih baik.
3. Mewujudkan infrastruktur, perumahan, dan permukiman berketahanan bencana.
4. Meningkatkan kualitas pemulihan sosial ekonomi, sumber daya alam, dan lingkungan hidup.
Fokus Capaian 12: Terwujudnya infrastruktur yang berkualitas, andal, serta berkelanjutan dan tangguh bencana.', 'Lampiran hal. 95', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4392, 'perban-5-2025', 197, 'lampiran', 'Lampiran hal. 95', NULL, 95, 'Box 3.1. Tujuan, Sasaran, Kebijakan, Strategi, Serta Fokus Capaian Renstra 3.1.2. Rencana Pembangunan Jangka Panjang Nasional 2025-2045 Visi Indonesia Emas 2045 adalah Negara Nusantara Berdaulat, Maju, dan Berkelanjutan. Negara Nusantara artinya negara kepulauan yang memiliki ketangguhan politik, ekonomi, keamanan nasional, dan budaya/peradaban bahari sebagai poros maritim dunia. Berdaulat yang dicapai melalui ketahanan, kesatuan, mandiri, dan aman. Maju tercermin dari berdaya, modern, tangguh, inovatif, dan adil. Berkelanjutan melalui pembangunan yang lestari dan seimbang antara ekonomi, sosial, dan lingkungan.
Untuk mewujudkan Indonesia emas 2045 ditetapkan 8 misi (agenda) pembangunan yang terdiri atas: 1) Transformasi Sosial; 2) Transformasi Ekonomi; 3) Transformasi Tata Kelola; 4) Supremasi Hukum, Stabilitas, dan Kepemimpinan Indonesia; 5) Ketahanan Sosial Budaya dan Ekologi; 6) Pembangunan Kewilayahan yang Merata dan Berkeadilan; 7) Sarana dan Prasarana yang Berkualitas dan Ramah Lingkungan; dan 8) Kesinambungan Pembangunan. RPJPN dilakukan dalam 4 tahapan pembangunan dengan fokus yang terukur dan konsisten untuk mencapai visi Indonesia emas 2045.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4392, 'Box 3.1. Tujuan, Sasaran, Kebijakan, Strategi, Serta Fokus Capaian Renstra 3.1.2. Rencana Pembangunan Jangka Panjang Nasional 2025-2045 Visi Indonesia Emas 2045 adalah Negara Nusantara Berdaulat, Maju, dan Berkelanjutan. Negara Nusantara artinya negara kepulauan yang memiliki ketangguhan politik, ekonomi, keamanan nasional, dan budaya/peradaban bahari sebagai poros maritim dunia. Berdaulat yang dicapai melalui ketahanan, kesatuan, mandiri, dan aman. Maju tercermin dari berdaya, modern, tangguh, inovatif, dan adil. Berkelanjutan melalui pembangunan yang lestari dan seimbang antara ekonomi, sosial, dan lingkungan.
Untuk mewujudkan Indonesia emas 2045 ditetapkan 8 misi (agenda) pembangunan yang terdiri atas: 1) Transformasi Sosial; 2) Transformasi Ekonomi; 3) Transformasi Tata Kelola; 4) Supremasi Hukum, Stabilitas, dan Kepemimpinan Indonesia; 5) Ketahanan Sosial Budaya dan Ekologi; 6) Pembangunan Kewilayahan yang Merata dan Berkeadilan; 7) Sarana dan Prasarana yang Berkualitas dan Ramah Lingkungan; dan 8) Kesinambungan Pembangunan. RPJPN dilakukan dalam 4 tahapan pembangunan dengan fokus yang terukur dan konsisten untuk mencapai visi Indonesia emas 2045.', 'Lampiran hal. 95', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4393, 'perban-5-2025', 198, 'lampiran', 'Lampiran hal. 96', NULL, 96, 'Gambar 3.1. Pentahapan Implementasi RPJPN 2025 - 2045 Sumber: Kementerian PPN/Bappenas, 2024 Agenda penanggulangan bencana tercermin dalam transformasi sosial budaya dan ekologi dengan sasaran pembangunan yaitu resiliensi terhadap bencana dan perubahan Iklim. Dalam RPJPN Tahun 2025-2045 penanggulangan bencana diarahkan untuk berdasar pada karakteristik dan kondisi bencana berbasis pulau.
Adapun arah kebijakan penanggulangan bencana adalah sebagai berikut:
1. Identifikasi karakter dan potensi kebencanaan di seluruh wilayah pulau untuk penyusunan profil risiko dan program mitigasi bencana;
2. Penerapan pertimbangan aspek pengurangan risiko bencana dalam menyusun rencana tata ruang wilayah di setiap tingkatan;
3. Pengembangan pusat logistik dan jaringan kebencanaan melalui konektivitas antar pulau termasuk dampak bencana dan perubahan iklim dalam Pembangunan infrastruktur melalui pelibatan kolaboratif klaster logistik PB dan kemitraan sektor publik dan swasta (public private partnerships);
4. Pembangunan Grey infrastructure (seawall, breakwater, spillway) dan nature-based solution (pembangunan green belt) untuk wilayah pesisir rentan Tsunami dan kenaikan muka air laut;
5. Pembangunan sistem peringatan dini multi ancaman bencana terpadu dan inklusif melalui penerapan teknologi yang andal dan terintegrasi;
6. Pembangunan kesiapsiagaan bencana dimulai dari tingkatan individu, keluarga dan komunitas;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4393, 'Gambar 3.1. Pentahapan Implementasi RPJPN 2025 - 2045 Sumber: Kementerian PPN/Bappenas, 2024 Agenda penanggulangan bencana tercermin dalam transformasi sosial budaya dan ekologi dengan sasaran pembangunan yaitu resiliensi terhadap bencana dan perubahan Iklim. Dalam RPJPN Tahun 2025-2045 penanggulangan bencana diarahkan untuk berdasar pada karakteristik dan kondisi bencana berbasis pulau.
Adapun arah kebijakan penanggulangan bencana adalah sebagai berikut:
1. Identifikasi karakter dan potensi kebencanaan di seluruh wilayah pulau untuk penyusunan profil risiko dan program mitigasi bencana;
2. Penerapan pertimbangan aspek pengurangan risiko bencana dalam menyusun rencana tata ruang wilayah di setiap tingkatan;
3. Pengembangan pusat logistik dan jaringan kebencanaan melalui konektivitas antar pulau termasuk dampak bencana dan perubahan iklim dalam Pembangunan infrastruktur melalui pelibatan kolaboratif klaster logistik PB dan kemitraan sektor publik dan swasta (public private partnerships);
4. Pembangunan Grey infrastructure (seawall, breakwater, spillway) dan nature-based solution (pembangunan green belt) untuk wilayah pesisir rentan Tsunami dan kenaikan muka air laut;
5. Pembangunan sistem peringatan dini multi ancaman bencana terpadu dan inklusif melalui penerapan teknologi yang andal dan terintegrasi;
6. Pembangunan kesiapsiagaan bencana dimulai dari tingkatan individu, keluarga dan komunitas;', 'Lampiran hal. 96', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4394, 'perban-5-2025', 199, 'lampiran', 'Lampiran hal. 96', NULL, 96, '7. Pengembangan modul pengetahuan kebencanaan dalam kurikulum di level Pendidikan dasar dan menengah;
8. Peningkatan kemandirian pemerintah daerah dalam pengelolaan penanggulangan bencana;
9. Pembangunan infrastruktur terintegrasi yang bersifat multifungsi (penyediaan layanan dasar, infrastruktur sosial, dan tanggap darurat bencana);
10. Pembangunan sarana dan prasarana yang memperhatikan kerawanan bencana dan perubahan iklim.
3.1.3. Rencana Pembangunan Jangka Menengah Nasional 2025-2029 Rencana Pembangunan Jangka Menengah Nasional (RPJMN) Tahun 2025-2029 tertuang dalam Peraturan Presiden Nomor 12 Tahun 2005 yang merupakan tahap pertama dalam menuju Indonesia Emas 2045 di mana menjadi tahap perkuatan pondasi transformasi dalam empat tahap pembangunan menuju Indonesia Emas 2045. Dalam RPJMN Lampiran I penanggulangan bencana tercantum dalam Prioritas Nasional 8 yaitu memperkuat kehidupan yang harmonis dengan lingkungan alam dan budaya serta peningkatan toleransi antarumat beragama untuk mencapai masyarakat adil dan makmur yang berarti pemerintah berkomitmen untuk mewujudkan kehidupan yang harmonis dan selaras dengan lingkungan alam dan budaya serta memperkukuh toleransi antar umat beragama guna mencapai masyarakat yang adil dan makmur.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4394, '7. Pengembangan modul pengetahuan kebencanaan dalam kurikulum di level Pendidikan dasar dan menengah;
8. Peningkatan kemandirian pemerintah daerah dalam pengelolaan penanggulangan bencana;
9. Pembangunan infrastruktur terintegrasi yang bersifat multifungsi (penyediaan layanan dasar, infrastruktur sosial, dan tanggap darurat bencana);
10. Pembangunan sarana dan prasarana yang memperhatikan kerawanan bencana dan perubahan iklim.
3.1.3. Rencana Pembangunan Jangka Menengah Nasional 2025-2029 Rencana Pembangunan Jangka Menengah Nasional (RPJMN) Tahun 2025-2029 tertuang dalam Peraturan Presiden Nomor 12 Tahun 2005 yang merupakan tahap pertama dalam menuju Indonesia Emas 2045 di mana menjadi tahap perkuatan pondasi transformasi dalam empat tahap pembangunan menuju Indonesia Emas 2045. Dalam RPJMN Lampiran I penanggulangan bencana tercantum dalam Prioritas Nasional 8 yaitu memperkuat kehidupan yang harmonis dengan lingkungan alam dan budaya serta peningkatan toleransi antarumat beragama untuk mencapai masyarakat adil dan makmur yang berarti pemerintah berkomitmen untuk mewujudkan kehidupan yang harmonis dan selaras dengan lingkungan alam dan budaya serta memperkukuh toleransi antar umat beragama guna mencapai masyarakat yang adil dan makmur.', 'Lampiran hal. 96', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4395, 'perban-5-2025', 200, 'lampiran', 'Lampiran hal. 97', NULL, 97, 'Selanjutnya sasaran utama bidang kebencanaan yang termuat dalam Prioritas Nasional 8 adalah resiliensi terhadap bencana dan perubahan iklim dengan indikator utama pembangunan proporsi kerugian ekonomi langsung akibat bencana relatif terhadap PDB sehingga diperlukan adanya arah kebijakan pengelolaan risiko bencana yang efisien dan tepat guna. Pengelolaan risiko bencana yang efisien dan tepat guna diperlukan karena sifat bencana yang sering kali tidak terduga dan dapat menimbulkan dampak yang besar pada kehidupan manusia, lingkungan serta ekonomi sehingga diperlukan penerapan langkah-langkah terintegrasi untuk meminimalkan dampak bencana terhadap kehidupan manusia, lingkungan, dan pembangunan. Dengan pendekatan berbasis data, kolaborasi multipihak, perencanaan matang, serta edukasi masyarakat, kebijakan pengelolaan risiko dapat memastikan kesiapsiagaan, respons cepat, dan pemulihan yang efektif untuk mendukung keberlanjutan dan kesejahteraan bersama. Pendekatan ini berusaha mengubah ancaman menjadi peluang untuk membangun sistem yang lebih tangguh.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4395, 'Selanjutnya sasaran utama bidang kebencanaan yang termuat dalam Prioritas Nasional 8 adalah resiliensi terhadap bencana dan perubahan iklim dengan indikator utama pembangunan proporsi kerugian ekonomi langsung akibat bencana relatif terhadap PDB sehingga diperlukan adanya arah kebijakan pengelolaan risiko bencana yang efisien dan tepat guna. Pengelolaan risiko bencana yang efisien dan tepat guna diperlukan karena sifat bencana yang sering kali tidak terduga dan dapat menimbulkan dampak yang besar pada kehidupan manusia, lingkungan serta ekonomi sehingga diperlukan penerapan langkah-langkah terintegrasi untuk meminimalkan dampak bencana terhadap kehidupan manusia, lingkungan, dan pembangunan. Dengan pendekatan berbasis data, kolaborasi multipihak, perencanaan matang, serta edukasi masyarakat, kebijakan pengelolaan risiko dapat memastikan kesiapsiagaan, respons cepat, dan pemulihan yang efektif untuk mendukung keberlanjutan dan kesejahteraan bersama. Pendekatan ini berusaha mengubah ancaman menjadi peluang untuk membangun sistem yang lebih tangguh.', 'Lampiran hal. 97', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4396, 'perban-5-2025', 201, 'lampiran', 'Lampiran hal. 97', NULL, 97, 'Pengelolaan risiko bencana yang efisien dan tepat guna berperan penting dalam mewujudkan resiliensi terhadap bencana serta melindungi kehidupan dan penghidupan masyarakat. Hal tersebut ditopang melalui penataan ruang, penurunan tingkat kerentanan bencana, peningkatan kemampuan untuk merespons saat kejadian bencana dan pemulihan pascabencana, peningkatan kapasitas dan kompetensi sumber daya manusia bidang penanggulangan bencana serta pembangunan infrastruktur berketahanan bencana. Selain itu pengelolaan risiko bencana juga difokuskan pada penguatan kerangka regulasi, penguatan kelembagaan dan pendanaan, meningkatkan kolaborasi multipihak dalam penanggulangan bencana serta penguatan investasi pengelolaan risiko bencana untuk mewujudkan sistem penanggulangan bencana yang efisien dan efektif. Arah kebijakan ini dilaksanakan melalui peningkatan upaya pencegahan dan mitigasi, peningkatan layanan peringatan dini dan penanganan kedaruratan bencana, pemenuhan kebutuhan rehabilitasi dan rekonstruksi pascabencana, peningkatan resiliensi masyarakat terhadap bencana serta peningkatan infrastruktur berketahanan bencana.
Tabel 3.1. Indikator Pembangunan dan Intervensi Penanggulangan Bencana dalam RPJMN Tahun 2025 - 2029 Indikator Baseline Target Intervensi yang Menjadi Penekanan Pembangunan 2025 2029
1. Peningkatan upaya pencegahan dan mitigasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4396, 'Pengelolaan risiko bencana yang efisien dan tepat guna berperan penting dalam mewujudkan resiliensi terhadap bencana serta melindungi kehidupan dan penghidupan masyarakat. Hal tersebut ditopang melalui penataan ruang, penurunan tingkat kerentanan bencana, peningkatan kemampuan untuk merespons saat kejadian bencana dan pemulihan pascabencana, peningkatan kapasitas dan kompetensi sumber daya manusia bidang penanggulangan bencana serta pembangunan infrastruktur berketahanan bencana. Selain itu pengelolaan risiko bencana juga difokuskan pada penguatan kerangka regulasi, penguatan kelembagaan dan pendanaan, meningkatkan kolaborasi multipihak dalam penanggulangan bencana serta penguatan investasi pengelolaan risiko bencana untuk mewujudkan sistem penanggulangan bencana yang efisien dan efektif. Arah kebijakan ini dilaksanakan melalui peningkatan upaya pencegahan dan mitigasi, peningkatan layanan peringatan dini dan penanganan kedaruratan bencana, pemenuhan kebutuhan rehabilitasi dan rekonstruksi pascabencana, peningkatan resiliensi masyarakat terhadap bencana serta peningkatan infrastruktur berketahanan bencana.
Tabel 3.1. Indikator Pembangunan dan Intervensi Penanggulangan Bencana dalam RPJMN Tahun 2025 - 2029 Indikator Baseline Target Intervensi yang Menjadi Penekanan Pembangunan 2025 2029
1. Peningkatan upaya pencegahan dan mitigasi', 'Lampiran hal. 97', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4397, 'perban-5-2025', 202, 'lampiran', 'Lampiran hal. 98', NULL, 98, '2. Peningkatan layanan peringatan dini dan penanganan kedaruratan Proporsi kerugian bencana Ekonomi langsung 0,1370 0,1350 3. Pemenuhan kebutuhan rehabilitasi akibat bencana relatif dan rekonstruksi pascabencana terhadap PDB (%)
4. Peningkatan resiliensi masyarakat terhadap bencana
5. Peningkatan infrastruktur berketahanan bencana Sumber: Kementerian PPN/Bappenas, 2025 3.1.4. Rencana Nasional Penanggulangan Bencana Tahun 2025-2029 Rencana Nasional Penanggulangan Bencana (RENAS PB) adalah rencana yang memuat kebijakan dan strategi serta pilihan tindakan untuk mencapai sasaran penyelenggaraan penanggulangan bencana di tingkat nasional dalam kurun 5 tahun. Dokumen ini adalah penjabaran RIPB Tahun 2020-2044 pada skala operasional periode 2025-2029. RENAS PB ditujukan seluruh instansi terkait penanggulangan bencana pada tingkat pusat ataupun daerah, pemerintah maupun non pemerintah. Oleh karena itu rumusan arahan kebijakan dan strategi dalam Renstra BNPB Tahun 2025-2029 perlu mempertimbangkan arahan dari Renas PB Tahun 2025-2029.
Rumusan Tujuan Penanggulangan Bencana dalam RENAS PB Tahun 2025-2029 yaitu: “Meningkatkan Ketangguhan Bangsa dalam Mengelola Risiko Bencana untuk Mewujudkan Resiliensi Berkelanjutan” Adapun sasaran dan kebijakan untuk mencapai tujuan tersebut adalah sebagai berikut:
Sasaran
1. Mengurangi Jumlah Penduduk Terdampak Bencana melalui Peningkatan Kualitas Kesiapsiagaan, Peringatan Dini, dan Penanggulangan Kedaruratan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4397, '2. Peningkatan layanan peringatan dini dan penanganan kedaruratan Proporsi kerugian bencana Ekonomi langsung 0,1370 0,1350 3. Pemenuhan kebutuhan rehabilitasi akibat bencana relatif dan rekonstruksi pascabencana terhadap PDB (%)
4. Peningkatan resiliensi masyarakat terhadap bencana
5. Peningkatan infrastruktur berketahanan bencana Sumber: Kementerian PPN/Bappenas, 2025 3.1.4. Rencana Nasional Penanggulangan Bencana Tahun 2025-2029 Rencana Nasional Penanggulangan Bencana (RENAS PB) adalah rencana yang memuat kebijakan dan strategi serta pilihan tindakan untuk mencapai sasaran penyelenggaraan penanggulangan bencana di tingkat nasional dalam kurun 5 tahun. Dokumen ini adalah penjabaran RIPB Tahun 2020-2044 pada skala operasional periode 2025-2029. RENAS PB ditujukan seluruh instansi terkait penanggulangan bencana pada tingkat pusat ataupun daerah, pemerintah maupun non pemerintah. Oleh karena itu rumusan arahan kebijakan dan strategi dalam Renstra BNPB Tahun 2025-2029 perlu mempertimbangkan arahan dari Renas PB Tahun 2025-2029.
Rumusan Tujuan Penanggulangan Bencana dalam RENAS PB Tahun 2025-2029 yaitu: “Meningkatkan Ketangguhan Bangsa dalam Mengelola Risiko Bencana untuk Mewujudkan Resiliensi Berkelanjutan” Adapun sasaran dan kebijakan untuk mencapai tujuan tersebut adalah sebagai berikut:
Sasaran
1. Mengurangi Jumlah Penduduk Terdampak Bencana melalui Peningkatan Kualitas Kesiapsiagaan, Peringatan Dini, dan Penanggulangan Kedaruratan Bencana;', 'Lampiran hal. 98', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4398, 'perban-5-2025', 203, 'lampiran', 'Lampiran hal. 98', NULL, 98, '2. Mengurangi Dampak Kerusakan dan Kerugian Akibat Bencana Melalui Peningkatan Efektivitas Upaya Pencegahan, Mitigasi Bencana dan Adaptasi Perubahan Iklim;
3. Meningkatkan Daya Lenting di Daerah Terdampak Melalui Peningkatan Percepatan Rehabilitasi dan Rekonstruksi;
4. Meningkatkan Pelayanan dan Kapasitas Penanggulangan Bencana Melalui Transformasi Tata Kelola & Kolaborasi Multipihak.
Kebijakan
1. Penguatan Kerangka Regulasi untuk Mewujudkan Sistem Penanggulangan Bencana yang Efisien & Efektif;
2. Penguatan Kelembagaan, Pendanaan, dan Peningkatan Kolaborasi Multipihak dalam Penanggulangan Bencana;
3. Penguatan Investasi Pengelolaan Risiko Bencana;
4. Peningkatan Ketangguhan Masyarakat dan Lembaga Usaha dalam Menghadapi Bencana;
5. Peningkatan Kapasitas & Kapabilitas dalam Kesiapsiagaan dan Penanganan Kedaruratan;
6. Peningkatan Kualitas Rehabilitasi & Rekonstruksi Pascabencana.
