INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4401, 'perban-5-2025', 206, 'lampiran', 'Lampiran hal. 100', NULL, 100, '8. meningkatkan advokasi resiliensi berkelanjutan di tingkat nasional & global Sumber: Renas PB 2025-2029 3.2. Arah Kebijakan dan Strategi BNPB Sinergitas pencapaian visi, misi, tujuan, dan sasaran strategis BNPB Tahun 2025- 2029 melibatkan seluruh unit kerja BNPB dan juga didukung oleh lembaga lain, baik di tingkat pusat maupun daerah. BNPB berperan dalam merumuskan dan menetapkan kebijakan penanggulangan bencana dan mengkoordinasikan pelaksanaan kegiatan penanggulangan bencana secara terencana, terpadu, dan menyeluruh. Tugas BNPB pada dasarnya adalah melakukan penanggulangan bencana melalui tiga tahapan, yaitu: prabencana, keadaan darurat, dan pasca bencana.
Untuk menjamin tercapainya penanganan bencana yang andal, maka BNPB harus didukung oleh semua sumber daya yang ada, seperti peningkatan partisipasi masyarakat dalam proses penanggulangan bencana, penguatan koordinasi antar instansi dan pemangku kepentingan, serta implementasi mekanisme evaluasi dan pemantauan yang efektif untuk mengukur kemajuan dan mengidentifikasi area-area yang perlu diperbaiki dalam penanggulangan bencana di masa mendatang. Selain itu, kolaborasi multipihak antar lembaga pemerintah, lembaga swadaya masyarakat, sektor swasta, dan institusi pendidikan perlu ditingkatkan guna memastikan sinergi dalam implementasi program-program penanggulangan bencana, pertukaran pengetahuan dan sumber daya, serta pengembangan inovasi yang dapat memperkuat ketahanan terhadap bencana di seluruh Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4401, '8. meningkatkan advokasi resiliensi berkelanjutan di tingkat nasional & global Sumber: Renas PB 2025-2029 3.2. Arah Kebijakan dan Strategi BNPB Sinergitas pencapaian visi, misi, tujuan, dan sasaran strategis BNPB Tahun 2025- 2029 melibatkan seluruh unit kerja BNPB dan juga didukung oleh lembaga lain, baik di tingkat pusat maupun daerah. BNPB berperan dalam merumuskan dan menetapkan kebijakan penanggulangan bencana dan mengkoordinasikan pelaksanaan kegiatan penanggulangan bencana secara terencana, terpadu, dan menyeluruh. Tugas BNPB pada dasarnya adalah melakukan penanggulangan bencana melalui tiga tahapan, yaitu: prabencana, keadaan darurat, dan pasca bencana.
Untuk menjamin tercapainya penanganan bencana yang andal, maka BNPB harus didukung oleh semua sumber daya yang ada, seperti peningkatan partisipasi masyarakat dalam proses penanggulangan bencana, penguatan koordinasi antar instansi dan pemangku kepentingan, serta implementasi mekanisme evaluasi dan pemantauan yang efektif untuk mengukur kemajuan dan mengidentifikasi area-area yang perlu diperbaiki dalam penanggulangan bencana di masa mendatang. Selain itu, kolaborasi multipihak antar lembaga pemerintah, lembaga swadaya masyarakat, sektor swasta, dan institusi pendidikan perlu ditingkatkan guna memastikan sinergi dalam implementasi program-program penanggulangan bencana, pertukaran pengetahuan dan sumber daya, serta pengembangan inovasi yang dapat memperkuat ketahanan terhadap bencana di seluruh Indonesia.', 'Lampiran hal. 100', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4402, 'perban-5-2025', 207, 'lampiran', 'Lampiran hal. 100', NULL, 100, 'Keterlibatan daerah merupakan faktor kunci untuk memastikan bahwa program dan kegiatan BNPB memiliki dukungan, sinergi, serta keberlanjutan di tingkat nasional dan daerah. BNPB tidak dapat bekerja sendiri; keberhasilan penanggulangan bencana sangat bergantung pada peran pemerintah daerah karena merekalah pihak pertama yang merespons bencana. Peran daerah mencakup integrasi program BNPB ke dalam dokumen perencanaan daerah (RPJMD, Renstra BPBD), pelaksanaan kegiatan bersama seperti pelatihan, simulasi, dan penyusunan rencana kontingensi, penguatan kapasitas BPBD melalui dukungan sumber daya manusia, anggaran, dan peralatan, pertukaran data dan informasi risiko bencana secara berkala, serta koordinasi lintas wilayah untuk penanganan bencana yang melintasi batas administratif. Selain itu, daerah juga berperan dalam membangun jejaring kemitraan lokal guna memperkuat kesiapsiagaan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4402, 'Keterlibatan daerah merupakan faktor kunci untuk memastikan bahwa program dan kegiatan BNPB memiliki dukungan, sinergi, serta keberlanjutan di tingkat nasional dan daerah. BNPB tidak dapat bekerja sendiri; keberhasilan penanggulangan bencana sangat bergantung pada peran pemerintah daerah karena merekalah pihak pertama yang merespons bencana. Peran daerah mencakup integrasi program BNPB ke dalam dokumen perencanaan daerah (RPJMD, Renstra BPBD), pelaksanaan kegiatan bersama seperti pelatihan, simulasi, dan penyusunan rencana kontingensi, penguatan kapasitas BPBD melalui dukungan sumber daya manusia, anggaran, dan peralatan, pertukaran data dan informasi risiko bencana secara berkala, serta koordinasi lintas wilayah untuk penanganan bencana yang melintasi batas administratif. Selain itu, daerah juga berperan dalam membangun jejaring kemitraan lokal guna memperkuat kesiapsiagaan masyarakat.', 'Lampiran hal. 100', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4403, 'perban-5-2025', 208, 'lampiran', 'Lampiran hal. 100', NULL, 100, 'Keterlibatan sektor swasta menjadi bagian penting dalam mendukung upaya pencegahan, mitigasi, tanggap darurat, dan pemulihan pascabencana. Sektor swasta berperan sebagai mitra strategis melalui berbagai bentuk dukungan, antara lain pendanaan dan program CSR (Corporate Social Responsibility) untuk membiayai kegiatan pengurangan risiko bencana, penyediaan teknologi dan inovasi seperti sistem peringatan dini, aplikasi pemantauan, atau infrastruktur tangguh bencana, penyediaan logistik dan fasilitas pada saat darurat, serta pelatihan dan edukasi bagi karyawan dan komunitas sekitar industri untuk kesiapsiagaan. Selain itu, sektor swasta juga dapat berkolaborasi dalam riset terkait rekayasa bangunan, tata ruang, dan sistem ketahanan bisnis, serta mendorong penerapan standar keselamatan dan ketahanan bencana di sektor industri.
Upaya-upaya demi mewujudkan sasaran strategis BNPB diimplementasikan melalui arah kebijakan dan strategi Renstra BNPB Tahun 2025-2029. selain itu, analisis SWOT yang telah dilakukan pada Bab 1 sebelumnya juga menjadi pertimbangan dalam merumuskan arah kebijakan dan strategi tersebut. Dapat dilihat pada Tabel 3.3.
Tabel 3.3. Arah Kebijakan dan Strategi Rencana Strategis BNPB Tahun 2025-2029 No. Arah Kebijakan Strategi
1. Penguatan integrasi sistem 1. Mengembangkan sistem dan strategi dan strategi penanggulangan penanggulangan bencana. bencana yang terpadu,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4403, 'Keterlibatan sektor swasta menjadi bagian penting dalam mendukung upaya pencegahan, mitigasi, tanggap darurat, dan pemulihan pascabencana. Sektor swasta berperan sebagai mitra strategis melalui berbagai bentuk dukungan, antara lain pendanaan dan program CSR (Corporate Social Responsibility) untuk membiayai kegiatan pengurangan risiko bencana, penyediaan teknologi dan inovasi seperti sistem peringatan dini, aplikasi pemantauan, atau infrastruktur tangguh bencana, penyediaan logistik dan fasilitas pada saat darurat, serta pelatihan dan edukasi bagi karyawan dan komunitas sekitar industri untuk kesiapsiagaan. Selain itu, sektor swasta juga dapat berkolaborasi dalam riset terkait rekayasa bangunan, tata ruang, dan sistem ketahanan bisnis, serta mendorong penerapan standar keselamatan dan ketahanan bencana di sektor industri.
Upaya-upaya demi mewujudkan sasaran strategis BNPB diimplementasikan melalui arah kebijakan dan strategi Renstra BNPB Tahun 2025-2029. selain itu, analisis SWOT yang telah dilakukan pada Bab 1 sebelumnya juga menjadi pertimbangan dalam merumuskan arah kebijakan dan strategi tersebut. Dapat dilihat pada Tabel 3.3.
