INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4407, 'perban-5-2025', 212, 'lampiran', 'Lampiran hal. 104', NULL, 104, 'Tabel 3.4. Keterkaitan Kebijakan Nasional dan Arah Kebijakan BNPB Tahun 2025-2029 Arah Kebijakan Rencana Kebijakan RIPB Tahun 2020- Arah Kebijakan PB RPJP Tahun Highlight Intervensi PB RPJMN Arah Kebijakan Renas PB Tahun Strategis BNPB Tahun 2044 2025-2045 Tahun 2025-2029 2025-2029 2025 - 2029 Identifikasi karakter dan potensi Penguatan Peraturan Perundang- kebencanaan di seluruh wilayah undangan penanggulangan pulau untuk penyusunan profil bencana yang efektif dan efisien risiko dan program mitigasi Penguatan Kerangka Regulasi Penguatan integrasi sistem dan bencana. Penataan ruang dan penurunan untuk Mewujudkan Sistem strategi penanggulangan bencana tingkat kerentanan bencana Penanggulangan Bencana yang yang terpadu, inovatif, dan Peningkatan sinergi antar Penerapan pertimbangan aspek Efisien & Efektif inklusif kementerian/lembaga dan pengurangan risiko bencana pemangku kepentingan dalam dalam menyusun rencana tata penanggulangan bencana. ruang wilayah di setiap tingkatan Pembangunan Grey infrastructure (seawall, breakwater, spillway) Peningkatan infrastruktur dan nature based solution berketahanan bencana dan Penguatan Investasi Pengelolaan (Pembangunan green belt) untuk kapasitas masyarakat dalam Risiko Bencana wilayah pesisir rentan Tsunami menghadapi bencana dan kenaikan muka air laut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4407, 'Tabel 3.4. Keterkaitan Kebijakan Nasional dan Arah Kebijakan BNPB Tahun 2025-2029 Arah Kebijakan Rencana Kebijakan RIPB Tahun 2020- Arah Kebijakan PB RPJP Tahun Highlight Intervensi PB RPJMN Arah Kebijakan Renas PB Tahun Strategis BNPB Tahun 2044 2025-2045 Tahun 2025-2029 2025-2029 2025 - 2029 Identifikasi karakter dan potensi Penguatan Peraturan Perundang- kebencanaan di seluruh wilayah undangan penanggulangan pulau untuk penyusunan profil bencana yang efektif dan efisien risiko dan program mitigasi Penguatan Kerangka Regulasi Penguatan integrasi sistem dan bencana. Penataan ruang dan penurunan untuk Mewujudkan Sistem strategi penanggulangan bencana tingkat kerentanan bencana Penanggulangan Bencana yang yang terpadu, inovatif, dan Peningkatan sinergi antar Penerapan pertimbangan aspek Efisien & Efektif inklusif kementerian/lembaga dan pengurangan risiko bencana pemangku kepentingan dalam dalam menyusun rencana tata penanggulangan bencana. ruang wilayah di setiap tingkatan Pembangunan Grey infrastructure (seawall, breakwater, spillway) Peningkatan infrastruktur dan nature based solution berketahanan bencana dan Penguatan Investasi Pengelolaan (Pembangunan green belt) untuk kapasitas masyarakat dalam Risiko Bencana wilayah pesisir rentan Tsunami menghadapi bencana dan kenaikan muka air laut.', 'Lampiran hal. 104', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4408, 'perban-5-2025', 213, 'lampiran', 'Lampiran hal. 104', NULL, 104, 'Penguatan investasi pengelolaan Pembangunan kesiapsiagaan bencana dimulai dari tingkatan Peningkatan upaya pencegahan, risiko bencana sesuai dengan individu, keluarga dan mitigasi, kesiapsiagaan, dan proyeksi peningkatan risiko komunitas. Peningkatan Ketangguhan peringatan dini terhadap bencana dengan memperhatikan Masyarakat dan Lembaga Usaha bencana secara komprehensif, tata ruang dan penataan Pembangunan sarana dan Peningkatan upaya pencegahan, dalam Menghadapi Bencana inklusif, dan berkelanjutan kawasan. prasarana yang memperhatikan kesiapsiagaan, mitigasi dan kerawanan bencana dan peringatan dini terpadu perubahan iklim.
Pembangunan sistem peringatan Peningkatan Kapasitas & dini multi ancaman bencana Kapabilitas dalam Kesiapsiagaan terpadu dan inklusif melalui dan Penanganan Kedaruratan penerapan teknologi yang andal Arah Kebijakan Rencana Kebijakan RIPB Tahun 2020- Arah Kebijakan PB RPJP Tahun Highlight Intervensi PB RPJMN Arah Kebijakan Renas PB Tahun Strategis BNPB Tahun 2044 2025-2045 Tahun 2025-2029 2025-2029 2025 - 2029 dan terintegrasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4408, 'Penguatan investasi pengelolaan Pembangunan kesiapsiagaan bencana dimulai dari tingkatan Peningkatan upaya pencegahan, risiko bencana sesuai dengan individu, keluarga dan mitigasi, kesiapsiagaan, dan proyeksi peningkatan risiko komunitas. Peningkatan Ketangguhan peringatan dini terhadap bencana dengan memperhatikan Masyarakat dan Lembaga Usaha bencana secara komprehensif, tata ruang dan penataan Pembangunan sarana dan Peningkatan upaya pencegahan, dalam Menghadapi Bencana inklusif, dan berkelanjutan kawasan. prasarana yang memperhatikan kesiapsiagaan, mitigasi dan kerawanan bencana dan peringatan dini terpadu perubahan iklim.
