INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4409, 'perban-5-2025', 214, 'lampiran', 'Lampiran hal. 105', NULL, 105, 'Pembangunan infrastruktur Peningkatan kapasitas dan terintegrasi yang bersifat kapabilitas penanganan multifungsi (penyediaan layanan kedaruratan bencana yang cepat dasar, infrastruktur sosial, dan dan andal tanggap darurat bencana) Peningkatan kapasitas dan Pengembangan pusat logistik dan jaringan kebencanaan melalui Peningkatan Kapasitas & kapabilitas penanganan konektivitas antar pulau Kapabilitas dalam Kesiapsiagaan kedaruratan bencana yang cepat Peningkatan kapasitas resiliensi termasuk dampak bencana dan Penguatan tata kelola dan Penanganan Kedaruratan dan andal. berkelanjutan logistik dan perubahan iklim dalam penanganan darurat dan pemenuhan peralatan untuk Pembangunan infrastruktur rehabilitasi rekonstruksi mendukung penanggulangan melalui pelibatan kolaboratif pascabencana bencana berbasis kewilayahan cluster logistic PB dan kemitraan sektor public dan swasta (public private partnerships) Percepatan pemulihan pasca Peningkatan kualitas rehabilitasi Pembangunan sarana dan bencana pada daerah dan Peningkatan Kualitas & rekonstruksi pasca bencana prasarana yang memperhatikan masyarakat terdampak bencana Rehabilitasi & Rekonstruksi yang lebih efektif, aman, inklusif, kerawanan bencana dan untuk membangun kehidupan Pascabencana dan berkelanjutan bagi perubahan iklim. yang lebih baik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4409, 'Pembangunan infrastruktur Peningkatan kapasitas dan terintegrasi yang bersifat kapabilitas penanganan multifungsi (penyediaan layanan kedaruratan bencana yang cepat dasar, infrastruktur sosial, dan dan andal tanggap darurat bencana) Peningkatan kapasitas dan Pengembangan pusat logistik dan jaringan kebencanaan melalui Peningkatan Kapasitas & kapabilitas penanganan konektivitas antar pulau Kapabilitas dalam Kesiapsiagaan kedaruratan bencana yang cepat Peningkatan kapasitas resiliensi termasuk dampak bencana dan Penguatan tata kelola dan Penanganan Kedaruratan dan andal. berkelanjutan logistik dan perubahan iklim dalam penanganan darurat dan pemenuhan peralatan untuk Pembangunan infrastruktur rehabilitasi rekonstruksi mendukung penanggulangan melalui pelibatan kolaboratif pascabencana bencana berbasis kewilayahan cluster logistic PB dan kemitraan sektor public dan swasta (public private partnerships) Percepatan pemulihan pasca Peningkatan kualitas rehabilitasi Pembangunan sarana dan bencana pada daerah dan Peningkatan Kualitas & rekonstruksi pasca bencana prasarana yang memperhatikan masyarakat terdampak bencana Rehabilitasi & Rekonstruksi yang lebih efektif, aman, inklusif, kerawanan bencana dan untuk membangun kehidupan Pascabencana dan berkelanjutan bagi perubahan iklim. yang lebih baik.', 'Lampiran hal. 105', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4410, 'perban-5-2025', 215, 'lampiran', 'Lampiran hal. 105', NULL, 105, 'masyarakat yang terdampak Pengembangan modul pengetahuan kebencanaan dalam Penguatan tata kelola kurikulum di level Pendidikan Penguatan Kelembagaan, Perwujudan tata kelola penanggulangan bencana yang dasar dan menengah. Pendanaan, dan Peningkatan penyelenggaraan manajemen semakin profesional, transparan, Peningkatan kemandirian Kolaborasi Multipihak dalam kebencanaan yang profesional, dan akuntabel pemerintah daerah dalam Penanggulangan Bencana akuntabel, dan transparan pengelolaan penanggulangan bencana.
Sumber: Dokumen Perencanaan Nasional, 2025 3.3. Kerangka Regulasi Mengacu pada Peraturan Presiden Nomor 80 Tahun 2025, kerangka regulasi adalah perencanaan pembentukan yang dibutuhkan oleh kementerian/lembaga dalam rangka memfasilitasi, mendorong, dan mengatur perilaku masyarakat dan penyelenggara negara dalam rangka mencapai tujuan bernegara. Kerangka ini merupakan mekanisme penyampaian perencanaan pembangunan selain Kerangka Pendanaan dan Kerangka Kelembagaan.
Bagan 3.1. Kedudukan Kerangka Regulasi, Kerangka Kelembagaan, dan Kerangka Pendanaan dalam Pembangunan Nasional Sumber: Diadopsi dari Kementerian PPN/Bappenas, 2023 Kaidah-kaidah yang perlu diacu dalam membuat kerangka regulasi BNPB 2025- 2029, adalah sebagai berikut: 1) Kebutuhan regulasi yang akan dibentuk; 2) Didasarkan pada UUD NRI Tahun 1945, RPJPN 2025-2045, dan RPJMN 2025-2029;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4410, 'masyarakat yang terdampak Pengembangan modul pengetahuan kebencanaan dalam Penguatan tata kelola kurikulum di level Pendidikan Penguatan Kelembagaan, Perwujudan tata kelola penanggulangan bencana yang dasar dan menengah. Pendanaan, dan Peningkatan penyelenggaraan manajemen semakin profesional, transparan, Peningkatan kemandirian Kolaborasi Multipihak dalam kebencanaan yang profesional, dan akuntabel pemerintah daerah dalam Penanggulangan Bencana akuntabel, dan transparan pengelolaan penanggulangan bencana.
Sumber: Dokumen Perencanaan Nasional, 2025 3.3. Kerangka Regulasi Mengacu pada Peraturan Presiden Nomor 80 Tahun 2025, kerangka regulasi adalah perencanaan pembentukan yang dibutuhkan oleh kementerian/lembaga dalam rangka memfasilitasi, mendorong, dan mengatur perilaku masyarakat dan penyelenggara negara dalam rangka mencapai tujuan bernegara. Kerangka ini merupakan mekanisme penyampaian perencanaan pembangunan selain Kerangka Pendanaan dan Kerangka Kelembagaan.
Bagan 3.1. Kedudukan Kerangka Regulasi, Kerangka Kelembagaan, dan Kerangka Pendanaan dalam Pembangunan Nasional Sumber: Diadopsi dari Kementerian PPN/Bappenas, 2023 Kaidah-kaidah yang perlu diacu dalam membuat kerangka regulasi BNPB 2025- 2029, adalah sebagai berikut: 1) Kebutuhan regulasi yang akan dibentuk; 2) Didasarkan pada UUD NRI Tahun 1945, RPJPN 2025-2045, dan RPJMN 2025-2029;', 'Lampiran hal. 105', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4411, 'perban-5-2025', 216, 'lampiran', 'Lampiran hal. 106', NULL, 106, '3) Memfasilitasi, mendorong, dan/atau mengatur perilaku Masyarakat; 4) Hasil analisis atau evaluasi terhadap efektivitas regulasi yang ada; 5) Hasil identifikasi dan analisis terkait dampak, biaya dan manfaat atas suatu regulasi.
Dalam proses penyusunan kerangka regulasi Rencana Strategis BNPB 2025-2029, BNPB telah mengidentifikasi beberapa dokumen perencanaan serta regulasi di tingkat nasional yang patut menjadi perhatian. Kebutuhan regulasi pada RPJMN 2025-2029 mengamanahkan revisi UU Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Untuk mengakomodir perubahan ini, revisi juga diperlukan pada peraturan turunan, seperti PP Nomor 21 Tahun 2008, PP Nomor 22 Tahun 2008, dan PP Nomor 23 Tahun 2008. Lebih lanjut, usulan penyusunan Peraturan Presiden tentang Multi-Hazard Early Warning System (MHEWS) dan Sasaran Strategis BNPB 2025-2029 juga perlu dipertimbangkan.
Berdasarkan regulasi serta dokumen perencanaan di atas, analisis kebutuhan regulasi akan dilakukan dengan mempertimbangkan dokumen perencanaan nasional, regulasi dan sasaran tersebut dan menyandingkannya dengan masing-masing regulasi, tugas, dan fungsi dari setiap unit yang ada pada lingkup BNPB.
Pada saat yang bersamaan, analisis ini juga akan mengevaluasi efektivitas dari regulasi yang ada pada Internal BNPB. Nantinya, hasil analisis ini akan mengidentifikasi serta memetakan keperluan regulasi yang akan digunakan sebagai basis penyusunan kerangka regulasi BNPB 2025-2029.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4411, '3) Memfasilitasi, mendorong, dan/atau mengatur perilaku Masyarakat; 4) Hasil analisis atau evaluasi terhadap efektivitas regulasi yang ada; 5) Hasil identifikasi dan analisis terkait dampak, biaya dan manfaat atas suatu regulasi.
Dalam proses penyusunan kerangka regulasi Rencana Strategis BNPB 2025-2029, BNPB telah mengidentifikasi beberapa dokumen perencanaan serta regulasi di tingkat nasional yang patut menjadi perhatian. Kebutuhan regulasi pada RPJMN 2025-2029 mengamanahkan revisi UU Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Untuk mengakomodir perubahan ini, revisi juga diperlukan pada peraturan turunan, seperti PP Nomor 21 Tahun 2008, PP Nomor 22 Tahun 2008, dan PP Nomor 23 Tahun 2008. Lebih lanjut, usulan penyusunan Peraturan Presiden tentang Multi-Hazard Early Warning System (MHEWS) dan Sasaran Strategis BNPB 2025-2029 juga perlu dipertimbangkan.
Berdasarkan regulasi serta dokumen perencanaan di atas, analisis kebutuhan regulasi akan dilakukan dengan mempertimbangkan dokumen perencanaan nasional, regulasi dan sasaran tersebut dan menyandingkannya dengan masing-masing regulasi, tugas, dan fungsi dari setiap unit yang ada pada lingkup BNPB.
Pada saat yang bersamaan, analisis ini juga akan mengevaluasi efektivitas dari regulasi yang ada pada Internal BNPB. Nantinya, hasil analisis ini akan mengidentifikasi serta memetakan keperluan regulasi yang akan digunakan sebagai basis penyusunan kerangka regulasi BNPB 2025-2029.', 'Lampiran hal. 106', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4412, 'perban-5-2025', 217, 'lampiran', 'Lampiran hal. 106', NULL, 106, 'Analisis ini bertujuan untuk memastikan bahwa setiap unit di BNPB memiliki acuan yang jelas dan terstruktur dalam melaksanakan tugas dan fungsinya, serta untuk mengidentifikasi dan menutup kesenjangan regulasi yang ada sehingga tercipta sistem manajemen bencana yang lebih efektif dan efisien.
Melalui analisis regulasi ini, BNPB diharapkan dapat meningkatkan koordinasi antar unit, memperjelas alur kerja, mengoptimalkan sumber daya yang dimiliki untuk menghadapi berbagai situasi darurat secara lebih terintegrasi dan responsif, serta secara keseluruhan menopang arah gerak organisasi melalui regulasi yang terbarukan.
Bagan 3.2. hingga Bagan 3.8. merupakan visualisasi kebutuhan kerangka regulasi yang dipetakan berdasarkan masing-masing unit BNPB dan berpedoman kepada Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
Visualisasi ini meliputi upaya peningkatan regulasi di bidang tata kelola penanggulangan bencana dan Internal BNPB, pembiayaan penanggulangan bencana, meliputi prabencana, tanggap darurat, dan pasca bencana. Adapun kebutuhan kerangka regulasi yang telah dikategorikan berdasarkan strata regulasi dapat dilihat dalam Tabel 3.5 dan Lampiran II.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4412, 'Analisis ini bertujuan untuk memastikan bahwa setiap unit di BNPB memiliki acuan yang jelas dan terstruktur dalam melaksanakan tugas dan fungsinya, serta untuk mengidentifikasi dan menutup kesenjangan regulasi yang ada sehingga tercipta sistem manajemen bencana yang lebih efektif dan efisien.
Melalui analisis regulasi ini, BNPB diharapkan dapat meningkatkan koordinasi antar unit, memperjelas alur kerja, mengoptimalkan sumber daya yang dimiliki untuk menghadapi berbagai situasi darurat secara lebih terintegrasi dan responsif, serta secara keseluruhan menopang arah gerak organisasi melalui regulasi yang terbarukan.
Bagan 3.2. hingga Bagan 3.8. merupakan visualisasi kebutuhan kerangka regulasi yang dipetakan berdasarkan masing-masing unit BNPB dan berpedoman kepada Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
Visualisasi ini meliputi upaya peningkatan regulasi di bidang tata kelola penanggulangan bencana dan Internal BNPB, pembiayaan penanggulangan bencana, meliputi prabencana, tanggap darurat, dan pasca bencana. Adapun kebutuhan kerangka regulasi yang telah dikategorikan berdasarkan strata regulasi dapat dilihat dalam Tabel 3.5 dan Lampiran II.', 'Lampiran hal. 106', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4413, 'perban-5-2025', 218, 'lampiran', 'Lampiran hal. 108', NULL, 108, 'Bagan 3.2. Analisis Lansekap dan Kebutuhan Regulasi Tata Kelola PB dan Pengelolaan Internal BNPB Bagian I Sumber: Analisis Penulis, 2024 Bagan 3.3. Analisis Lansekap dan Kebutuhan Regulasi Tata Kelola PB dan Pengelolaan Internal BNPB Bagian II Sumber: Analisis Penulis, 2024 Bagan 3.3. Analisis Lansekap dan Kebutuhan Regulasi Pada Aspek Pembiayaan Penanggulangan Bencana Bagian I Sumber: Analisis Penulis, 2024 Bagan 3.5. Analisis Lansekap dan Kebutuhan Regulasi Pada Aspek Pembiayaan Penanggulangan Bencana Bagian II Sumber: Analisis Penulis, 2024 Bagan 3.6. Analisis Lansekap dan Kebutuhan Regulasi Pada Aspek Prabencana Sumber: Analisis Penulis, 2024 Bagan 3.4. Analisis Lansekap dan Kebutuhan Regulasi Pada Aspek Tanggap Darurat Sumber: Analisis Penulis, 2024 Bagan 3.5. Analisis Lansekap dan Kebutuhan Regulasi Pada Aspek Pasca Bencana Sumber: Analisis Penulis, 2024 Tabel 3.5. Kebutuhan Regulasi BNPB 2025-2029 Urgensi Pembentukan Arah Kerangka Berdasarkan Evaluasi Unit Penanggung No.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4413, 'Bagan 3.2. Analisis Lansekap dan Kebutuhan Regulasi Tata Kelola PB dan Pengelolaan Internal BNPB Bagian I Sumber: Analisis Penulis, 2024 Bagan 3.3. Analisis Lansekap dan Kebutuhan Regulasi Tata Kelola PB dan Pengelolaan Internal BNPB Bagian II Sumber: Analisis Penulis, 2024 Bagan 3.3. Analisis Lansekap dan Kebutuhan Regulasi Pada Aspek Pembiayaan Penanggulangan Bencana Bagian I Sumber: Analisis Penulis, 2024 Bagan 3.5. Analisis Lansekap dan Kebutuhan Regulasi Pada Aspek Pembiayaan Penanggulangan Bencana Bagian II Sumber: Analisis Penulis, 2024 Bagan 3.6. Analisis Lansekap dan Kebutuhan Regulasi Pada Aspek Prabencana Sumber: Analisis Penulis, 2024 Bagan 3.4. Analisis Lansekap dan Kebutuhan Regulasi Pada Aspek Tanggap Darurat Sumber: Analisis Penulis, 2024 Bagan 3.5. Analisis Lansekap dan Kebutuhan Regulasi Pada Aspek Pasca Bencana Sumber: Analisis Penulis, 2024 Tabel 3.5. Kebutuhan Regulasi BNPB 2025-2029 Urgensi Pembentukan Arah Kerangka Berdasarkan Evaluasi Unit Penanggung No.', 'Lampiran hal. 108', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4414, 'perban-5-2025', 219, 'lampiran', 'Lampiran hal. 108', NULL, 108, 'Regulasi dan/atau Unit Terkait/ Institusi Target Penyelesaian Regulasi Eksisting, Kajian Jawab Kebutuhan Regulasi Dan Penelitian Undang-Undang, Peraturan Pemerintah, Peraturan Presiden 1 Revisi Undang-Undang Undang-undang yang akan Bappenas, Kemendagri, Nomor 24 tahun 2007 direvisi sesuai amanat Kemham, KemenPUPR, tentang RPJMN, serta untuk KLHK, KKP, Kementan, BNPB 2025-2029 Penanggulangan melakukan pembaharuan Kemenkes, Kemensos, Bencana regulasi berdasarkan Kominfo, BMKG, BIG, perkembangan PB terkini. BRIN, PVMBG 2 Revisi Peraturan Mengakomodir revisi pada Bappenas, Kemendagri, Pemerintah Nomor 21 UU 24 Tahun 2007, serta Kemham, KemenPUPR, tahun 2008 tentang untuk melakukan KLHK, KKP, Kementan, BNPB 2025-2029 Penyelenggaraan pembaharuan regulasi Kemenkes, Kemensos, Penanggulangan berdasarkan perkembangan Kominfo, BMKG, BIG, Bencana PB terkini. BRIN, PVMBG 3 Revisi Peraturan Mengakomodir revisi pada Pemerintah Nomor 22 UU 24 Tahun 2007, serta tahun 2008 tentang untuk melakukan Kemenkeu, Kemendagri, BNPB 2025-2029 Pendanaan dan pembaharuan regulasi Bappenas Pengelolaan Bantuan berdasarkan perkembangan Bencana PB terkini.
4 Revisi Peraturan Mengakomodir revisi pada Pemerintah Nomor 23 UU 24 Tahun 2007, serta tahun 2008 tentang untuk melakukan Peran Serta Lembaga pembaharuan regulasi Kemendagri, Bappenas, Internasional dan berdasarkan perkembangan BNPB 2025-2029 Kemenkeu Lembaga Asing Non PB terkini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4414, 'Regulasi dan/atau Unit Terkait/ Institusi Target Penyelesaian Regulasi Eksisting, Kajian Jawab Kebutuhan Regulasi Dan Penelitian Undang-Undang, Peraturan Pemerintah, Peraturan Presiden 1 Revisi Undang-Undang Undang-undang yang akan Bappenas, Kemendagri, Nomor 24 tahun 2007 direvisi sesuai amanat Kemham, KemenPUPR, tentang RPJMN, serta untuk KLHK, KKP, Kementan, BNPB 2025-2029 Penanggulangan melakukan pembaharuan Kemenkes, Kemensos, Bencana regulasi berdasarkan Kominfo, BMKG, BIG, perkembangan PB terkini. BRIN, PVMBG 2 Revisi Peraturan Mengakomodir revisi pada Bappenas, Kemendagri, Pemerintah Nomor 21 UU 24 Tahun 2007, serta Kemham, KemenPUPR, tahun 2008 tentang untuk melakukan KLHK, KKP, Kementan, BNPB 2025-2029 Penyelenggaraan pembaharuan regulasi Kemenkes, Kemensos, Penanggulangan berdasarkan perkembangan Kominfo, BMKG, BIG, Bencana PB terkini. BRIN, PVMBG 3 Revisi Peraturan Mengakomodir revisi pada Pemerintah Nomor 22 UU 24 Tahun 2007, serta tahun 2008 tentang untuk melakukan Kemenkeu, Kemendagri, BNPB 2025-2029 Pendanaan dan pembaharuan regulasi Bappenas Pengelolaan Bantuan berdasarkan perkembangan Bencana PB terkini.
4 Revisi Peraturan Mengakomodir revisi pada Pemerintah Nomor 23 UU 24 Tahun 2007, serta tahun 2008 tentang untuk melakukan Peran Serta Lembaga pembaharuan regulasi Kemendagri, Bappenas, Internasional dan berdasarkan perkembangan BNPB 2025-2029 Kemenkeu Lembaga Asing Non PB terkini.', 'Lampiran hal. 108', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4415, 'perban-5-2025', 220, 'lampiran', 'Lampiran hal. 115', NULL, 115, 'Pemerintah dalam Penanggulangan Bencana 5 Revisi Peraturan Mengakomodir perubahan Presiden Nomor 1 pada struktur BNPB dan Tahun 2019 tentang perubahan lain pada BNPB KemenPANRB 2026 Badan Nasional peraturan diatasnya.
Penanggulangan Bencana 6 Peraturan Presiden Sebagai acuan dan dasar Kemenko PMK, tentang Implementasi hukum utama untuk Kemendagri, MHEWS implementasi MHEWS, serta KemenPUPR, Kominfo, peraturan lanjutan hasil BNPB KKP, KLHK, KKP, 2025-2026 pengembangan berdasarkan ESDM, Kemenhub, PERPRES 93 Tahun 2019. BMKG, PVMBG, BIG, BRIN Sumber: Biro Hukum, Organisasi dan Kerja Sama, 2024 3.4. Kerangka Kelembagaan Mengacu pada Peraturan Nomor 80 Tahun 2025, Kerangka Kelembagaan merujuk pada sistem kementerian atau lembaga yang mencakup struktur organisasi, prosedur operasional, serta manajemen pegawai negeri. Sistem ini dirancang untuk mencapai visi, misi, tujuan, strategi, kebijakan, serta program dan aktivitas pembangunan yang sesuai dengan tugas dan fungsi dari kementerian atau lembaga tersebut, dengan mengacu pada Rencana Pembangunan Jangka Menengah Nasional (RPJMN).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4415, 'Pemerintah dalam Penanggulangan Bencana 5 Revisi Peraturan Mengakomodir perubahan Presiden Nomor 1 pada struktur BNPB dan Tahun 2019 tentang perubahan lain pada BNPB KemenPANRB 2026 Badan Nasional peraturan diatasnya.
Penanggulangan Bencana 6 Peraturan Presiden Sebagai acuan dan dasar Kemenko PMK, tentang Implementasi hukum utama untuk Kemendagri, MHEWS implementasi MHEWS, serta KemenPUPR, Kominfo, peraturan lanjutan hasil BNPB KKP, KLHK, KKP, 2025-2026 pengembangan berdasarkan ESDM, Kemenhub, PERPRES 93 Tahun 2019. BMKG, PVMBG, BIG, BRIN Sumber: Biro Hukum, Organisasi dan Kerja Sama, 2024 3.4. Kerangka Kelembagaan Mengacu pada Peraturan Nomor 80 Tahun 2025, Kerangka Kelembagaan merujuk pada sistem kementerian atau lembaga yang mencakup struktur organisasi, prosedur operasional, serta manajemen pegawai negeri. Sistem ini dirancang untuk mencapai visi, misi, tujuan, strategi, kebijakan, serta program dan aktivitas pembangunan yang sesuai dengan tugas dan fungsi dari kementerian atau lembaga tersebut, dengan mengacu pada Rencana Pembangunan Jangka Menengah Nasional (RPJMN).', 'Lampiran hal. 115', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4416, 'perban-5-2025', 221, 'lampiran', 'Lampiran hal. 115', NULL, 115, 'Kerangka Kelembagaan adalah salah satu pedoman implementasi dalam Rencana Strategis kementerian atau lembaga yang bertujuan untuk meningkatkan efisiensi pelaksanaan pembangunan melalui dukungan kelembagaan yang sesuai ukuran, fungsi, dan prosedur. Selain sebagai alat untuk menyampaikan Rencana Strategis, mekanisme ini juga termasuk Kerangka Regulasi dan Kerangka Pendanaan. Fokus dari Kerangka Kelembagaan adalah struktur organisasi pemerintah, termasuk penentuan tugas, fungsi, wewenang, peran, dan susunan organisasi. Dengan memiliki kelembagaan yang sesuai fungsi, ukuran, dan proses, diharapkan akan memperkuat efektivitas kelembagaan yang sejalan dengan agenda pembangunan.
Dalam melaksanakan Rencana Strategis, BNPB mengoptimalkan pendekatan multipihak (pemerintah, lembaga usaha, masyarakat, perguruan tinggi dan media) dalam penyelenggaraan penanggulangan bencana.
Kerangka Kelembagaan merupakan sistem kementerian/lembaga yang mencakup struktur organisasi, tata kelola, dan manajemen pegawai negeri sipil. Kerangka ini dirancang untuk mencapai visi, misi, tujuan, strategi, kebijakan, serta program dan aktivitas pembangunan yang sesuai dengan fungsi dan tugas dari kementerian atau lembaga. Seluruhnya disusun dengan acuan pada Rencana Pembangunan Jangka Menengah Nasional (RPJMN). Dalam kelembagaan, BNPB perlu memperhatikan beberapa hal yang meliputi :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4416, 'Kerangka Kelembagaan adalah salah satu pedoman implementasi dalam Rencana Strategis kementerian atau lembaga yang bertujuan untuk meningkatkan efisiensi pelaksanaan pembangunan melalui dukungan kelembagaan yang sesuai ukuran, fungsi, dan prosedur. Selain sebagai alat untuk menyampaikan Rencana Strategis, mekanisme ini juga termasuk Kerangka Regulasi dan Kerangka Pendanaan. Fokus dari Kerangka Kelembagaan adalah struktur organisasi pemerintah, termasuk penentuan tugas, fungsi, wewenang, peran, dan susunan organisasi. Dengan memiliki kelembagaan yang sesuai fungsi, ukuran, dan proses, diharapkan akan memperkuat efektivitas kelembagaan yang sejalan dengan agenda pembangunan.
Dalam melaksanakan Rencana Strategis, BNPB mengoptimalkan pendekatan multipihak (pemerintah, lembaga usaha, masyarakat, perguruan tinggi dan media) dalam penyelenggaraan penanggulangan bencana.
Kerangka Kelembagaan merupakan sistem kementerian/lembaga yang mencakup struktur organisasi, tata kelola, dan manajemen pegawai negeri sipil. Kerangka ini dirancang untuk mencapai visi, misi, tujuan, strategi, kebijakan, serta program dan aktivitas pembangunan yang sesuai dengan fungsi dan tugas dari kementerian atau lembaga. Seluruhnya disusun dengan acuan pada Rencana Pembangunan Jangka Menengah Nasional (RPJMN). Dalam kelembagaan, BNPB perlu memperhatikan beberapa hal yang meliputi :', 'Lampiran hal. 115', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4417, 'perban-5-2025', 222, 'lampiran', 'Lampiran hal. 116', NULL, 116, '1. Perubahan dalam pendekatan pengelolaan bencana telah bergeser dari responsif menjadi fokus pada pengurangan risiko bencana dengan penekanan lebih pada tindakan pencegahan;
2. Mandat yang diberikan, meliputi mandat konstitusional, mandat teknis, mandat pembangunan, dan mandat organisasi serta mandat diplomasi;
3. Kebijakan pembangunan, kebijakan desentralisasi dan otonomi daerah, peraturan perundangan terkait yang berlaku;
4. Prinsip-prinsip penyelenggaraan penanggulangan bencana;
5. Tata laksana dan sumber daya aparatur.
3.4.1 Struktur Organisasi BNPB Berdasarkan Peraturan Presiden Nomor 01 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana yang diubah dalam Peraturan Presiden Nomor 29 Tahun 2021 dan Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana yang diubah dalam Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020, penataan kelembagaan BNPB akan dilanjutkan dengan penyesuaian nama program dan kegiatan.
Bagan 3.6. Struktur Organisasi BNPB Sumber: BNPB, 2024 Kepala Kepala mempunya tugas untuk memimpin dan menjalankan fungsi dan tanggung jawab Badan Nasional Penanggulangan Bencana.
Unsur Pengarah Unsur Pengarah mempunyai tugas untuk memberikan umpan balik dan rekomendasi kepada kepala terkait penyelenggaraan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4417, '1. Perubahan dalam pendekatan pengelolaan bencana telah bergeser dari responsif menjadi fokus pada pengurangan risiko bencana dengan penekanan lebih pada tindakan pencegahan;
2. Mandat yang diberikan, meliputi mandat konstitusional, mandat teknis, mandat pembangunan, dan mandat organisasi serta mandat diplomasi;
3. Kebijakan pembangunan, kebijakan desentralisasi dan otonomi daerah, peraturan perundangan terkait yang berlaku;
4. Prinsip-prinsip penyelenggaraan penanggulangan bencana;
5. Tata laksana dan sumber daya aparatur.
3.4.1 Struktur Organisasi BNPB Berdasarkan Peraturan Presiden Nomor 01 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana yang diubah dalam Peraturan Presiden Nomor 29 Tahun 2021 dan Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana yang diubah dalam Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020, penataan kelembagaan BNPB akan dilanjutkan dengan penyesuaian nama program dan kegiatan.
Bagan 3.6. Struktur Organisasi BNPB Sumber: BNPB, 2024 Kepala Kepala mempunya tugas untuk memimpin dan menjalankan fungsi dan tanggung jawab Badan Nasional Penanggulangan Bencana.
Unsur Pengarah Unsur Pengarah mempunyai tugas untuk memberikan umpan balik dan rekomendasi kepada kepala terkait penyelenggaraan penanggulangan bencana.', 'Lampiran hal. 116', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4418, 'perban-5-2025', 223, 'lampiran', 'Lampiran hal. 117', NULL, 117, 'Sekretariat Utama Sekretariat Utama bertanggung jawab dalam membina dan memberikan dukungan administrasi dalam lingkungan Badan Nasional Penanggulangan Bencana.
Sekretariat Utama terdiri dari:
a. Biro Perencanaan.
b. Biro Keuangan.
c. Biro Hukum, Organisasi dan Kerja Sama.
d. Biro Sumber Daya Manusia dan Umum.
Deputi Bidang Sistem dan Strategi Deputi Bidang Sistem dan Strategi bertanggung jawab atas perumusan dan pelaksanaan kebijakan yang berkaitan dengan sistem dan strategi penanggulangan bencana. Deputi Bidang Sistem dan Strategi terdiri dari:
a. Direktorat Pemetaan dan Evaluasi Risiko Bencana.
b. Direktorat Pengembangan Strategi Penanggulangan Bencana.
c. Direktorat Sistem Penanggulangan Bencana.
Deputi Bidang Pencegahan Deputi Bidang Pencegahan bertanggung jawab atas pembuatan dan pelaksanaan kebijakan pencegahan. Deputi Bidang Pencegahan terdiri dari:
a. Direktorat Mitigasi Bencana.
b. Direktorat Kesiapsiagaan.
c. Direktorat Peringatan Dini.
Deputi Bidang Penanganan Darurat Deputi Bidang Penanganan Darurat bertanggung jawab atas perumusan dan pelaksanaan kebijakan di bidang penanganan keadaan darurat, meliputi penyelenggaraan siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.
Deputi Bidang Penanganan Darurat terdiri dari:
a. Direktorat Dukungan Sumber Daya Darurat.
b. Direktorat Dukungan Infrastruktur Darurat.
c. Direktorat Fasilitasi Penanganan Korban dan Pengungsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4418, 'Sekretariat Utama Sekretariat Utama bertanggung jawab dalam membina dan memberikan dukungan administrasi dalam lingkungan Badan Nasional Penanggulangan Bencana.
Sekretariat Utama terdiri dari:
a. Biro Perencanaan.
b. Biro Keuangan.
c. Biro Hukum, Organisasi dan Kerja Sama.
d. Biro Sumber Daya Manusia dan Umum.
Deputi Bidang Sistem dan Strategi Deputi Bidang Sistem dan Strategi bertanggung jawab atas perumusan dan pelaksanaan kebijakan yang berkaitan dengan sistem dan strategi penanggulangan bencana. Deputi Bidang Sistem dan Strategi terdiri dari:
a. Direktorat Pemetaan dan Evaluasi Risiko Bencana.
b. Direktorat Pengembangan Strategi Penanggulangan Bencana.
c. Direktorat Sistem Penanggulangan Bencana.
Deputi Bidang Pencegahan Deputi Bidang Pencegahan bertanggung jawab atas pembuatan dan pelaksanaan kebijakan pencegahan. Deputi Bidang Pencegahan terdiri dari:
a. Direktorat Mitigasi Bencana.
b. Direktorat Kesiapsiagaan.
c. Direktorat Peringatan Dini.
Deputi Bidang Penanganan Darurat Deputi Bidang Penanganan Darurat bertanggung jawab atas perumusan dan pelaksanaan kebijakan di bidang penanganan keadaan darurat, meliputi penyelenggaraan siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.
Deputi Bidang Penanganan Darurat terdiri dari:
a. Direktorat Dukungan Sumber Daya Darurat.
b. Direktorat Dukungan Infrastruktur Darurat.
c. Direktorat Fasilitasi Penanganan Korban dan Pengungsi.', 'Lampiran hal. 117', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4419, 'perban-5-2025', 224, 'lampiran', 'Lampiran hal. 117', NULL, 117, 'Deputi Bidang Rehabilitasi dan Rekonstruksi Deputi Bidang Rehabilitasi dan Rekonstruksi bertanggung jawab atas perumusan dan pelaksanaan kebijakan teknis di bidang rehabilitasi dan rekonstruksi. Deputi Bidang Rehabilitasi dan Rekonstruksi terdiri dari:
a. Direktorat Perencanaan Rehabilitasi dan Rekonstruksi.
b. Direktorat Pemulihan dan Peningkatan Fisik.
c. Direktorat Pemulihan dan Peningkatan Sosial, Ekonomi, dan Sumber Daya Alam.
Deputi Bidang Logistik dan Peralatan Deputi Bidang Logistik dan Peralatan bertanggung jawab atas perumusan dan pelaksanaan kebijakan di bidang logistik dan peralatan penanggulangan bencana.
Deputi Bidang Logistik dan Peralatan terdiri dari:
a. Direktorat Pengelolaan Logistik dan Peralatan.
b. Direktorat Optimasi Jaringan Logistik dan Peralatan.
Inspektorat Utama Inspektorat Utama mempunyai tugas menyelenggarakan pengawasan Internal di lingkungan Badan Nasional Penanggulangan Bencana. Inspektorat Utama terdiri dari:
a. Inspektorat I.
b. Inspektorat II.
c. Inspektorat III.
Pusat-Pusat
a. Pusat Data, Informasi dan Komunikasi Kebencanaan Pusat Data, Informasi, dan Komunikasi Kebencanaan bertanggung jawab dalam mengkoordinasikan dan menyediakan layanan yang berkaitan dengan pengelolaan data dan informasi, pengembangan basis data dan informasi, dan melaksanakan komunikasi kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4419, 'Deputi Bidang Rehabilitasi dan Rekonstruksi Deputi Bidang Rehabilitasi dan Rekonstruksi bertanggung jawab atas perumusan dan pelaksanaan kebijakan teknis di bidang rehabilitasi dan rekonstruksi. Deputi Bidang Rehabilitasi dan Rekonstruksi terdiri dari:
a. Direktorat Perencanaan Rehabilitasi dan Rekonstruksi.
b. Direktorat Pemulihan dan Peningkatan Fisik.
c. Direktorat Pemulihan dan Peningkatan Sosial, Ekonomi, dan Sumber Daya Alam.
Deputi Bidang Logistik dan Peralatan Deputi Bidang Logistik dan Peralatan bertanggung jawab atas perumusan dan pelaksanaan kebijakan di bidang logistik dan peralatan penanggulangan bencana.
Deputi Bidang Logistik dan Peralatan terdiri dari:
a. Direktorat Pengelolaan Logistik dan Peralatan.
b. Direktorat Optimasi Jaringan Logistik dan Peralatan.
Inspektorat Utama Inspektorat Utama mempunyai tugas menyelenggarakan pengawasan Internal di lingkungan Badan Nasional Penanggulangan Bencana. Inspektorat Utama terdiri dari:
a. Inspektorat I.
b. Inspektorat II.
c. Inspektorat III.
Pusat-Pusat
a. Pusat Data, Informasi dan Komunikasi Kebencanaan Pusat Data, Informasi, dan Komunikasi Kebencanaan bertanggung jawab dalam mengkoordinasikan dan menyediakan layanan yang berkaitan dengan pengelolaan data dan informasi, pengembangan basis data dan informasi, dan melaksanakan komunikasi kebencanaan.', 'Lampiran hal. 117', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4420, 'perban-5-2025', 225, 'lampiran', 'Lampiran hal. 118', NULL, 118, 'b. Pusat Pendidikan dan Pelatihan Penanggulangan Bencana Pusat Pendidikan dan Pelatihan Penanggulangan Bencana bertanggung jawab dalam mengkoordinasikan dan menyelenggarakan pengembangan kapasitas sumber daya manusia di bidang penanggulangan bencana.
c. Pusat Pengendalian Operasi Pusat Pengendalian Operasi bertanggung jawab dalam mengkoordinasikan, menyiapkan, mengolah data dan menganalisis pemantauan potensi ancaman bencana, pengerahan sumber daya, diseminasi informasi, pelaksanaan komunikasi kedaruratan dan rekomendasi operasi penanganan darurat bencana.
3.4.2 Rencana Pengembangan Organisasi Terdapat beberapa langkah strategis ke depan yang akan dilakukan BNPB terkait dengan pengembangan kelembagaan, sesuai dengan tugas dan fungsi BNPB dan berpedoman pada RPJMN 2025-2029.
1. Penambahan Wakil Kepala BNPB Penanggulangan bencana telah diposisikan sebagai salah satu pilar transformasi sosial yang mendasari super prioritas ketahanan sosial dan ekologi dalam Visi Asta Cita Presiden Republik Indonesia. Hal ini juga semakin menegaskan cakupan kerja BNPB yang luas, meliputi semua bidang dan tahapan penyelenggaraan penanggulangan bencana dan jenis ancaman serta kejadian bencana yang menuntut koordinasi semua kementerian/lembaga sektoral.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4420, 'b. Pusat Pendidikan dan Pelatihan Penanggulangan Bencana Pusat Pendidikan dan Pelatihan Penanggulangan Bencana bertanggung jawab dalam mengkoordinasikan dan menyelenggarakan pengembangan kapasitas sumber daya manusia di bidang penanggulangan bencana.
c. Pusat Pengendalian Operasi Pusat Pengendalian Operasi bertanggung jawab dalam mengkoordinasikan, menyiapkan, mengolah data dan menganalisis pemantauan potensi ancaman bencana, pengerahan sumber daya, diseminasi informasi, pelaksanaan komunikasi kedaruratan dan rekomendasi operasi penanganan darurat bencana.
3.4.2 Rencana Pengembangan Organisasi Terdapat beberapa langkah strategis ke depan yang akan dilakukan BNPB terkait dengan pengembangan kelembagaan, sesuai dengan tugas dan fungsi BNPB dan berpedoman pada RPJMN 2025-2029.
1. Penambahan Wakil Kepala BNPB Penanggulangan bencana telah diposisikan sebagai salah satu pilar transformasi sosial yang mendasari super prioritas ketahanan sosial dan ekologi dalam Visi Asta Cita Presiden Republik Indonesia. Hal ini juga semakin menegaskan cakupan kerja BNPB yang luas, meliputi semua bidang dan tahapan penyelenggaraan penanggulangan bencana dan jenis ancaman serta kejadian bencana yang menuntut koordinasi semua kementerian/lembaga sektoral.', 'Lampiran hal. 118', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4421, 'perban-5-2025', 226, 'lampiran', 'Lampiran hal. 118', NULL, 118, 'Penambahan Wakil Kepala BNPB ini memperkuat kepemimpinan dan pembagian beban dan tanggung jawab tata kelola kepada Kepala Badan yang lebih fokus pada perumusan kebijakan, advokasi, dan kerjasama dengan berbagai pihak terkait. Wakil Kepala Badan berperan mendukung tanggung jawab Kepala Badan, dengan berfokus pada penerjemahan strategi menjadi program kegiatan, koordinasi lapangan, dan pengelolaan sumber daya.
2. Penambahan 1 (satu) Deputi Bidang Penanggulangan Bencana Non Alam dan Bencana Sosial.
Deputi Bidang Penanggulangan Bencana Non Alam dan Bencana Sosial terdiri atas 2 (dua) direktorat yakni:
a. Direktorat Penanggulangan Bencana Non Alam; dan
b. Direktorat Penanggulangan Bencana Sosial.
3. Penataan pada Deputi Bidang Penanganan Darurat Deputi Bidang Penanganan Darurat terdiri atas 4 (empat) direktorat, yakni:
a. Direktorat Pengendalian Operasi Darurat;
b. Direktorat Penanganan Darurat Wilayah I;
c. Direktorat Penanganan Darurat Wilayah II; dan
d. Direktorat Penanganan Darurat Wilayah III.
4. Penataan pada Deputi Bidang Rehabilitasi dan Rekonstruksi Deputi Bidang Rehabilitasi dan Rekonstruksi dilakukan penyesuaian uraian tugas dan fungsi pada direktoratnya menjadi:
a. Direktorat Pemulihan Perumahan;
b. Direktorat Pemulihan dan Peningkatan Infrastruktur; dan
c. Direktorat Pemulihan dan Peningkatan Sosial, Ekonomi dan Lingkungan Hidup.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4421, 'Penambahan Wakil Kepala BNPB ini memperkuat kepemimpinan dan pembagian beban dan tanggung jawab tata kelola kepada Kepala Badan yang lebih fokus pada perumusan kebijakan, advokasi, dan kerjasama dengan berbagai pihak terkait. Wakil Kepala Badan berperan mendukung tanggung jawab Kepala Badan, dengan berfokus pada penerjemahan strategi menjadi program kegiatan, koordinasi lapangan, dan pengelolaan sumber daya.
2. Penambahan 1 (satu) Deputi Bidang Penanggulangan Bencana Non Alam dan Bencana Sosial.
Deputi Bidang Penanggulangan Bencana Non Alam dan Bencana Sosial terdiri atas 2 (dua) direktorat yakni:
a. Direktorat Penanggulangan Bencana Non Alam; dan
b. Direktorat Penanggulangan Bencana Sosial.
3. Penataan pada Deputi Bidang Penanganan Darurat Deputi Bidang Penanganan Darurat terdiri atas 4 (empat) direktorat, yakni:
a. Direktorat Pengendalian Operasi Darurat;
b. Direktorat Penanganan Darurat Wilayah I;
c. Direktorat Penanganan Darurat Wilayah II; dan
d. Direktorat Penanganan Darurat Wilayah III.
4. Penataan pada Deputi Bidang Rehabilitasi dan Rekonstruksi Deputi Bidang Rehabilitasi dan Rekonstruksi dilakukan penyesuaian uraian tugas dan fungsi pada direktoratnya menjadi:
a. Direktorat Pemulihan Perumahan;
b. Direktorat Pemulihan dan Peningkatan Infrastruktur; dan
c. Direktorat Pemulihan dan Peningkatan Sosial, Ekonomi dan Lingkungan Hidup.', 'Lampiran hal. 118', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4422, 'perban-5-2025', 227, 'lampiran', 'Lampiran hal. 119', NULL, 119, '5. Pembentukan Pusat Pembinaan JF di Bidang Kebencanaan Pada Tahun 2020 BNPB telah membentuk 2 (dua) Jabatan Fungsional di Bidang Kebencanaan yaitu, Jabatan Fungsional Analis Kebencanaan berdasarkan PermenPANRB Nomor 87 Tahun 2020 dan Jabatan Fungsional Penata Penanggulangan Bencana berdasarkan PermenPANRB Nomor 88 Tahun 2020 dan sudah dilaksanakan inpasing pada Tahun 2022. Kedua Jabatan Fungsional ini merupakan Jabatan Keahlian dan bersifat terbuka sehingga dapat diduduki pada Pemerintah Pusat dan Pemerintah Daerah. Kedua Jabatan Fungsional ini juga dijadikan Jabatan Fungsional dalam penyetaraan jabatan pada Tingkat Pusat dan Daerah, khususnya di BNPB dan seluruh BPBD Provinsi dan BPBD Kabupaten/Kota. Dan pada Tahun 2024 dilaksanakan konsolidasi Jabatan Fungsional Analis kebencanaan dan Jabatan Fungsional Penata Penanggulangan Bencana menjadi 1 (satu) nomenklatur yaitu Jabatan Fungsional Analis Kebencanaan dengan PermenPANRB Nomor 7 Tahun 2024 dan dibentuk Jabatan Fungsional Pranata Kebencanaan untuk kategori Keterampilan. Saat ini Jabatan Fungsional Kebencanan berkedudukan pada lebih dari 500 Pemerintah Provinsi dan Kabupaten/Kota di seluruh Indonesia dengan jumlah formasi nasional 14.514 pegawai yang tersebar di seluruh Indonesia. Saat ini BNPB sebagai instansi Pembina Jabatan Fungsional tersebut belum terdapat unit kerja yang menangani khusus Pembinaan Jabatan Fungsional Kebencanaan tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4422, '5. Pembentukan Pusat Pembinaan JF di Bidang Kebencanaan Pada Tahun 2020 BNPB telah membentuk 2 (dua) Jabatan Fungsional di Bidang Kebencanaan yaitu, Jabatan Fungsional Analis Kebencanaan berdasarkan PermenPANRB Nomor 87 Tahun 2020 dan Jabatan Fungsional Penata Penanggulangan Bencana berdasarkan PermenPANRB Nomor 88 Tahun 2020 dan sudah dilaksanakan inpasing pada Tahun 2022. Kedua Jabatan Fungsional ini merupakan Jabatan Keahlian dan bersifat terbuka sehingga dapat diduduki pada Pemerintah Pusat dan Pemerintah Daerah. Kedua Jabatan Fungsional ini juga dijadikan Jabatan Fungsional dalam penyetaraan jabatan pada Tingkat Pusat dan Daerah, khususnya di BNPB dan seluruh BPBD Provinsi dan BPBD Kabupaten/Kota. Dan pada Tahun 2024 dilaksanakan konsolidasi Jabatan Fungsional Analis kebencanaan dan Jabatan Fungsional Penata Penanggulangan Bencana menjadi 1 (satu) nomenklatur yaitu Jabatan Fungsional Analis Kebencanaan dengan PermenPANRB Nomor 7 Tahun 2024 dan dibentuk Jabatan Fungsional Pranata Kebencanaan untuk kategori Keterampilan. Saat ini Jabatan Fungsional Kebencanan berkedudukan pada lebih dari 500 Pemerintah Provinsi dan Kabupaten/Kota di seluruh Indonesia dengan jumlah formasi nasional 14.514 pegawai yang tersebar di seluruh Indonesia. Saat ini BNPB sebagai instansi Pembina Jabatan Fungsional tersebut belum terdapat unit kerja yang menangani khusus Pembinaan Jabatan Fungsional Kebencanaan tersebut.', 'Lampiran hal. 119', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4423, 'perban-5-2025', 228, 'lampiran', 'Lampiran hal. 119', NULL, 119, 'Untuk itu perlu dibentuk Unit Kerja Eselon 2 yaitu Pusat Pembinaan Jabatan Fungsional yang khusus menangani Pembinaan Jabatan Fungsional di Bidang Kebencanaan, sesuai dengan PermenPANRB Nomor 1 Tahun 2023 terdapat 19 tugas Instansi Pembina yang harus dilaksanakan dalam pengelolaan Jabatan Fungsional.
6. Penambahan unit pada Biro Sumber Daya Manusia dan Umum, yaitu Bagian Pengadaan Barang dan Jasa Bagian Pengadaan Barang dan Jasa ditujukan untuk mempercepat proses pengadaan barang dan jasa khususnya pada perlengkapan Internal BNPB menimbang kebutuhan masing-masing unit yang belum terwadahi. Hal ini juga diperlukan untuk memenuhi ketentuan Pasal 75 Peraturan Presiden Nomor 16 Tahun 2018 j.o. Peraturan Presiden Nomor 12 Tahun 2021 dan j.o. Peraturan Presiden Nomor 46 Tahun 2025 tentang Pengadaan Barang/Jasa Pemerintah, yang mana setiap kementerian/lembaga wajib membentuk unit kerja pengadaan barang dan jasa (UKPBJ) secara struktural.
7. Pembentukan Unit Pelaksana Teknis BNPB dapat mengajukan pembentukan unit pelaksana teknis untuk melaksanakan tugas teknis operasional dan/atau tugas teknis penunjang tertentu, berdasarkan Pasal 53 Peraturan Presiden Nomor 1 Tahun 2019.
Melihat perlunya penunjang teknis bagi Deputi Bidang Logistik dan Peralatan, diusulkan pembentukan UPT Balai Besar Logistik Kebencanaan di Padang, Sumatera Barat. Kajian rinci mengenai usulan pengembangan organisasi ini disampaikan terpisah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4423, 'Untuk itu perlu dibentuk Unit Kerja Eselon 2 yaitu Pusat Pembinaan Jabatan Fungsional yang khusus menangani Pembinaan Jabatan Fungsional di Bidang Kebencanaan, sesuai dengan PermenPANRB Nomor 1 Tahun 2023 terdapat 19 tugas Instansi Pembina yang harus dilaksanakan dalam pengelolaan Jabatan Fungsional.
6. Penambahan unit pada Biro Sumber Daya Manusia dan Umum, yaitu Bagian Pengadaan Barang dan Jasa Bagian Pengadaan Barang dan Jasa ditujukan untuk mempercepat proses pengadaan barang dan jasa khususnya pada perlengkapan Internal BNPB menimbang kebutuhan masing-masing unit yang belum terwadahi. Hal ini juga diperlukan untuk memenuhi ketentuan Pasal 75 Peraturan Presiden Nomor 16 Tahun 2018 j.o. Peraturan Presiden Nomor 12 Tahun 2021 dan j.o. Peraturan Presiden Nomor 46 Tahun 2025 tentang Pengadaan Barang/Jasa Pemerintah, yang mana setiap kementerian/lembaga wajib membentuk unit kerja pengadaan barang dan jasa (UKPBJ) secara struktural.
7. Pembentukan Unit Pelaksana Teknis BNPB dapat mengajukan pembentukan unit pelaksana teknis untuk melaksanakan tugas teknis operasional dan/atau tugas teknis penunjang tertentu, berdasarkan Pasal 53 Peraturan Presiden Nomor 1 Tahun 2019.
Melihat perlunya penunjang teknis bagi Deputi Bidang Logistik dan Peralatan, diusulkan pembentukan UPT Balai Besar Logistik Kebencanaan di Padang, Sumatera Barat. Kajian rinci mengenai usulan pengembangan organisasi ini disampaikan terpisah.', 'Lampiran hal. 119', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4424, 'perban-5-2025', 229, 'lampiran', 'Lampiran hal. 120', NULL, 120, 'Dalam rangka mendukung upaya penanggulangan bencana, BNPB saat ini memiliki pegawai existing sebanyak 1.158 orang yang terdiri atas 654 PNS, 93 CPNS, 223 PPPK, dan 188 PPNPN. Berdasarkan jenis kelamin, terdapat 675 pegawai laki-laki dan 484 pegawai perempuan. Jika dilihat dari kelompok usia, mayoritas pegawai berada pada usia produktif, yaitu 567 orang berusia 30–39 tahun, 309 orang berusia 40–50 tahun, 214 orang berusia kurang dari 30 tahun, dan 69 orang berusia di atas 50 tahun. Dari sisi pendidikan, komposisi pegawai terdiri atas 11,6% berpendidikan SMA/SMK, 13,4% DII, 60,0% S1, dan 14,2% S2. Berdasarkan agama, mayoritas beragama Islam sebanyak 1.015 orang, diikuti Kristen 103 orang, Katolik 27 orang, Hindu 5 orang, dan Buddha 1 orang. Sementara itu, dari sisi jabatan, 502 orang menduduki jabatan fungsional, 373 orang sebagai pelaksana, dan 96 orang pada jabatan struktural. Data rinci komposisi pegawai BNPB dapat dilihat pada diagram berikut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4424, 'Dalam rangka mendukung upaya penanggulangan bencana, BNPB saat ini memiliki pegawai existing sebanyak 1.158 orang yang terdiri atas 654 PNS, 93 CPNS, 223 PPPK, dan 188 PPNPN. Berdasarkan jenis kelamin, terdapat 675 pegawai laki-laki dan 484 pegawai perempuan. Jika dilihat dari kelompok usia, mayoritas pegawai berada pada usia produktif, yaitu 567 orang berusia 30–39 tahun, 309 orang berusia 40–50 tahun, 214 orang berusia kurang dari 30 tahun, dan 69 orang berusia di atas 50 tahun. Dari sisi pendidikan, komposisi pegawai terdiri atas 11,6% berpendidikan SMA/SMK, 13,4% DII, 60,0% S1, dan 14,2% S2. Berdasarkan agama, mayoritas beragama Islam sebanyak 1.015 orang, diikuti Kristen 103 orang, Katolik 27 orang, Hindu 5 orang, dan Buddha 1 orang. Sementara itu, dari sisi jabatan, 502 orang menduduki jabatan fungsional, 373 orang sebagai pelaksana, dan 96 orang pada jabatan struktural. Data rinci komposisi pegawai BNPB dapat dilihat pada diagram berikut.', 'Lampiran hal. 120', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4425, 'perban-5-2025', 230, 'lampiran', 'Lampiran hal. 121', NULL, 121, 'Grafik 3.1. Data Rinci Komposisi Pegawai BNPB per-Agustus 2025 Sumber: BNPB, 2025 Dalam rangka mendukung pengembangan kelembagaan BNPB yang direncanakan pada periode mendatang, keberadaan sumber daya manusia (SDM) yang memadai, baik dari sisi jumlah maupun kualitas, menjadi salah satu faktor kunci yang menentukan keberhasilan pencapaian tujuan organisasi. SDM yang kompeten, terlatih, dan memiliki keahlian yang relevan dengan kebutuhan tugas akan memastikan pelaksanaan program dan kegiatan penanggulangan bencana dapat berjalan secara efektif, adaptif, dan berkelanjutan. Oleh karena itu, strategi penguatan SDM tidak hanya diarahkan pada penambahan jumlah pegawai, tetapi juga pada peningkatan kualitas melalui pendidikan, pelatihan, dan pengembangan karier yang berkesinambungan.
Ketersediaan SDM yang tepat di setiap lini tugas sangat penting untuk membangun kelembagaan yang tangguh, responsif, dan mampu menghadapi dinamika penanggulangan bencana yang semakin kompleks. Hal ini mencakup penempatan pegawai sesuai dengan kompetensi dan bidang keahlian, sehingga setiap individu dapat memberikan kontribusi maksimal terhadap pencapaian target organisasi.
Penempatan yang tepat ini juga didukung dengan upaya peningkatan kapasitas yang berfokus pada penguasaan keahlian teknis, pengembangan soft skills, serta pemanfaatan teknologi terkini dalam manajemen bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4425, 'Grafik 3.1. Data Rinci Komposisi Pegawai BNPB per-Agustus 2025 Sumber: BNPB, 2025 Dalam rangka mendukung pengembangan kelembagaan BNPB yang direncanakan pada periode mendatang, keberadaan sumber daya manusia (SDM) yang memadai, baik dari sisi jumlah maupun kualitas, menjadi salah satu faktor kunci yang menentukan keberhasilan pencapaian tujuan organisasi. SDM yang kompeten, terlatih, dan memiliki keahlian yang relevan dengan kebutuhan tugas akan memastikan pelaksanaan program dan kegiatan penanggulangan bencana dapat berjalan secara efektif, adaptif, dan berkelanjutan. Oleh karena itu, strategi penguatan SDM tidak hanya diarahkan pada penambahan jumlah pegawai, tetapi juga pada peningkatan kualitas melalui pendidikan, pelatihan, dan pengembangan karier yang berkesinambungan.
Ketersediaan SDM yang tepat di setiap lini tugas sangat penting untuk membangun kelembagaan yang tangguh, responsif, dan mampu menghadapi dinamika penanggulangan bencana yang semakin kompleks. Hal ini mencakup penempatan pegawai sesuai dengan kompetensi dan bidang keahlian, sehingga setiap individu dapat memberikan kontribusi maksimal terhadap pencapaian target organisasi.
Penempatan yang tepat ini juga didukung dengan upaya peningkatan kapasitas yang berfokus pada penguasaan keahlian teknis, pengembangan soft skills, serta pemanfaatan teknologi terkini dalam manajemen bencana.', 'Lampiran hal. 121', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4426, 'perban-5-2025', 231, 'lampiran', 'Lampiran hal. 121', NULL, 121, 'Seiring dengan perkembangan tantangan penanggulangan bencana, BNPB memandang bahwa perencanaan pengembangan SDM secara berkelanjutan menjadi kebutuhan yang tidak dapat ditunda. Perencanaan ini harus mempertimbangkan dinamika perubahan kebijakan, perkembangan teknologi, perubahan pola ancaman bencana, serta tuntutan akuntabilitas publik yang semakin tinggi. Dengan demikian, pengembangan SDM diarahkan untuk menghasilkan pegawai yang memiliki kompetensi teknis, profesionalisme yang tinggi, serta integritas yang kuat.
Pengembangan ini akan mencakup sejumlah langkah strategis, antara lain: peningkatan kapasitas melalui program pendidikan formal dan nonformal, pelatihan teknis yang berorientasi pada kebutuhan lapangan, workshop dan bimbingan teknis untuk meningkatkan keterampilan analisis dan pengambilan keputusan, serta program sertifikasi bagi jabatan-jabatan tertentu yang memerlukan pengakuan kompetensi profesional. Selain itu, perlu dilakukan penyesuaian dan pembaruan kurikulum pelatihan agar sesuai dengan perkembangan teknologi dan metodologi penanggulangan bencana terkini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4426, 'Seiring dengan perkembangan tantangan penanggulangan bencana, BNPB memandang bahwa perencanaan pengembangan SDM secara berkelanjutan menjadi kebutuhan yang tidak dapat ditunda. Perencanaan ini harus mempertimbangkan dinamika perubahan kebijakan, perkembangan teknologi, perubahan pola ancaman bencana, serta tuntutan akuntabilitas publik yang semakin tinggi. Dengan demikian, pengembangan SDM diarahkan untuk menghasilkan pegawai yang memiliki kompetensi teknis, profesionalisme yang tinggi, serta integritas yang kuat.
Pengembangan ini akan mencakup sejumlah langkah strategis, antara lain: peningkatan kapasitas melalui program pendidikan formal dan nonformal, pelatihan teknis yang berorientasi pada kebutuhan lapangan, workshop dan bimbingan teknis untuk meningkatkan keterampilan analisis dan pengambilan keputusan, serta program sertifikasi bagi jabatan-jabatan tertentu yang memerlukan pengakuan kompetensi profesional. Selain itu, perlu dilakukan penyesuaian dan pembaruan kurikulum pelatihan agar sesuai dengan perkembangan teknologi dan metodologi penanggulangan bencana terkini.', 'Lampiran hal. 121', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4427, 'perban-5-2025', 232, 'lampiran', 'Lampiran hal. 122', NULL, 122, 'Berdasarkan analisis kebutuhan kelembagaan, BNPB memperkirakan bahwa dalam lima tahun ke depan diperlukan tambahan pegawai sebanyak kurang lebih 563 orang. Kebutuhan ini mencakup pengisian jabatan pelaksana dan jabatan fungsional, dengan prioritas pada fungsional analis kebencanaan dan analis kebijakan. Kedua jenis jabatan ini memiliki peran strategis dalam mendukung penyusunan kebijakan, perencanaan program, pelaksanaan kegiatan, serta evaluasi hasil yang berbasis data dan analisis yang akurat. Pemenuhan kebutuhan SDM tersebut diharapkan tidak hanya menambah kapasitas organisasi secara kuantitatif, tetapi juga memperkuat kemampuan BNPB secara kualitatif, sehingga mampu merespons ancaman bencana secara cepat, tepat, dan terukur.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4427, 'Berdasarkan analisis kebutuhan kelembagaan, BNPB memperkirakan bahwa dalam lima tahun ke depan diperlukan tambahan pegawai sebanyak kurang lebih 563 orang. Kebutuhan ini mencakup pengisian jabatan pelaksana dan jabatan fungsional, dengan prioritas pada fungsional analis kebencanaan dan analis kebijakan. Kedua jenis jabatan ini memiliki peran strategis dalam mendukung penyusunan kebijakan, perencanaan program, pelaksanaan kegiatan, serta evaluasi hasil yang berbasis data dan analisis yang akurat. Pemenuhan kebutuhan SDM tersebut diharapkan tidak hanya menambah kapasitas organisasi secara kuantitatif, tetapi juga memperkuat kemampuan BNPB secara kualitatif, sehingga mampu merespons ancaman bencana secara cepat, tepat, dan terukur.', 'Lampiran hal. 122', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4428, 'perban-5-2025', 233, 'lampiran', 'Lampiran hal. 122', NULL, 122, 'Dengan penguatan kapasitas dan penambahan SDM yang terencana, BNPB diharapkan dapat membangun struktur kelembagaan yang lebih solid, adaptif, dan profesional. Hal ini menjadi modal penting untuk mewujudkan visi dan misi organisasi, sekaligus menjawab tantangan penanggulangan bencana di masa depan yang semakin dinamis dan kompleks. : Tetap : Usulan Pengembangan Organisasi Bagan 3.7. Usulan Struktur Organisasi BNPB Tahun 2025-2029 Sumber: Analisis Penulis, 2024 BAB 4. TARGET KINERJA DAN KERANGKA PENDANAAN Visi Presiden Prabowo Subianto periode tahun 2025-2029 yang tertuang dalam dokumen Asta Cita adalah "Bersama Indonesia Maju, Menuju Indonesia Emas 2045" yang mengandung maksud mengajak putra putri terbaik bangsa dari semua latar belakang yang memiliki kesamaan tekad untuk bekerja sama membangun bangsa.
Visi ini menekankan pentingnya kerja sama dan tekad bersama untuk mencapai Indonesia yang setara dengan negara maju dalam 20 tahun mendatang. Guna mencapai visi yang telah ditetapkan maka Presiden dan Wakil Presiden telah menetapkan 8 misi sebagai program kerjanya selama 5 tahun ke depan yang selanjutnya Visi dan Misi ini diadopsi dalam RPJMN 2025-2029.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4428, 'Dengan penguatan kapasitas dan penambahan SDM yang terencana, BNPB diharapkan dapat membangun struktur kelembagaan yang lebih solid, adaptif, dan profesional. Hal ini menjadi modal penting untuk mewujudkan visi dan misi organisasi, sekaligus menjawab tantangan penanggulangan bencana di masa depan yang semakin dinamis dan kompleks. : Tetap : Usulan Pengembangan Organisasi Bagan 3.7. Usulan Struktur Organisasi BNPB Tahun 2025-2029 Sumber: Analisis Penulis, 2024 BAB 4. TARGET KINERJA DAN KERANGKA PENDANAAN Visi Presiden Prabowo Subianto periode tahun 2025-2029 yang tertuang dalam dokumen Asta Cita adalah "Bersama Indonesia Maju, Menuju Indonesia Emas 2045" yang mengandung maksud mengajak putra putri terbaik bangsa dari semua latar belakang yang memiliki kesamaan tekad untuk bekerja sama membangun bangsa.
Visi ini menekankan pentingnya kerja sama dan tekad bersama untuk mencapai Indonesia yang setara dengan negara maju dalam 20 tahun mendatang. Guna mencapai visi yang telah ditetapkan maka Presiden dan Wakil Presiden telah menetapkan 8 misi sebagai program kerjanya selama 5 tahun ke depan yang selanjutnya Visi dan Misi ini diadopsi dalam RPJMN 2025-2029.', 'Lampiran hal. 122', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4429, 'perban-5-2025', 234, 'lampiran', 'Lampiran hal. 124', NULL, 124, 'Dalam dokumen Asta Cita dan RPJMN 2025-2029 di mana Penanggulangan Bencana tercantum dalam Program Kerja 8 yaitu memperkuat penyelarasan kehidupan yang harmonis dengan lingkungan alam dan budaya serta peningkatan toleransi antar umat beragama untuk mencapai masyarakat yang adil dan makmur yang terdiri dari enam sasaran yang akan dicapai antara kurun waktu 2025-2029, antara lain:
1. Meningkatkan anggaran mitigasi dan penanggulangan bencana, termasuk memutakhirkan sistem peringatan dini bencana;
2. Meningkatkan anggaran penanganan bencana untuk mempercepat rehabilitasi dan rekonstruksi wilayah yang terdampak bencana dan mengembalikan kesejahteraan rakyat di wilayah tersebut;
3. Membangun infrastruktur yang berorientasi pada kesiapan dan ketahanan untuk menghadapi situasi bencana;
4. Menata koordinasi antar lembaga terkait untuk mempercepat penanggulangan dan penanganan bencana;
5. Mencegah penguasaan dan pengurasan sumber daya alam secara tidak bertanggung jawab yang berpotensi mengakibatkan timbulnya bencana;
6. Menata sinergi antara pemerintah dengan swasta, kelompok masyarakat, dan lembaga donor asing dalam penanganan dan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4429, 'Dalam dokumen Asta Cita dan RPJMN 2025-2029 di mana Penanggulangan Bencana tercantum dalam Program Kerja 8 yaitu memperkuat penyelarasan kehidupan yang harmonis dengan lingkungan alam dan budaya serta peningkatan toleransi antar umat beragama untuk mencapai masyarakat yang adil dan makmur yang terdiri dari enam sasaran yang akan dicapai antara kurun waktu 2025-2029, antara lain:
1. Meningkatkan anggaran mitigasi dan penanggulangan bencana, termasuk memutakhirkan sistem peringatan dini bencana;
2. Meningkatkan anggaran penanganan bencana untuk mempercepat rehabilitasi dan rekonstruksi wilayah yang terdampak bencana dan mengembalikan kesejahteraan rakyat di wilayah tersebut;
3. Membangun infrastruktur yang berorientasi pada kesiapan dan ketahanan untuk menghadapi situasi bencana;
4. Menata koordinasi antar lembaga terkait untuk mempercepat penanggulangan dan penanganan bencana;
5. Mencegah penguasaan dan pengurasan sumber daya alam secara tidak bertanggung jawab yang berpotensi mengakibatkan timbulnya bencana;
6. Menata sinergi antara pemerintah dengan swasta, kelompok masyarakat, dan lembaga donor asing dalam penanganan dan penanggulangan bencana.', 'Lampiran hal. 124', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4430, 'perban-5-2025', 235, 'lampiran', 'Lampiran hal. 124', NULL, 124, 'Pada program kerja atau Prioritas Nasional 8 yaitu memperkuat penyelarasan kehidupan yang harmonis dengan lingkungan alam dan budaya serta peningkatan toleransi antar umat beragama untuk mencapai masyarakat yang adil dan Makmur telah ditetapkan sasaran utama pembangunan untuk bidang penanggulangan bencana yaitu resiliensi terhadap bencana dan perubahan iklim dengan rumusan indikator yaitu proporsi kerugian ekonomi langsung akibat bencana relatif terhadap PDB yang merupakan salah satu target utama dalam kerangka kerja Sendai Framework for Disaster Risk Reduction (SFDRR) untuk mengurangi risiko bencana dan kerugian yang diakibatkan oleh bencana dengan target penurunan di tahun 2025 sebesar 0,1370% menjadi sebesar 0,1350%, untuk mencapai target tersebut maka telah ditetapkan arah kebijakan penanggulangan bencana yaitu pengelolaan risiko bencana yang efisien dan tepat guna untuk mewujudkan resiliensi terhadap bencana serta melindungi kehidupan dan penghidupan masyarakat. Hal tersebut ditopang melalui penataan ruang, penurunan tingkat kerentanan bencana, peningkatan kemampuan untuk merespons saat kejadian bencana dan pemulihan pascabencana, peningkatan kapasitas dan kompetensi sumber daya manusia bidang penanggulangan bencana serta pembangunan infrastruktur berketahanan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4430, 'Pada program kerja atau Prioritas Nasional 8 yaitu memperkuat penyelarasan kehidupan yang harmonis dengan lingkungan alam dan budaya serta peningkatan toleransi antar umat beragama untuk mencapai masyarakat yang adil dan Makmur telah ditetapkan sasaran utama pembangunan untuk bidang penanggulangan bencana yaitu resiliensi terhadap bencana dan perubahan iklim dengan rumusan indikator yaitu proporsi kerugian ekonomi langsung akibat bencana relatif terhadap PDB yang merupakan salah satu target utama dalam kerangka kerja Sendai Framework for Disaster Risk Reduction (SFDRR) untuk mengurangi risiko bencana dan kerugian yang diakibatkan oleh bencana dengan target penurunan di tahun 2025 sebesar 0,1370% menjadi sebesar 0,1350%, untuk mencapai target tersebut maka telah ditetapkan arah kebijakan penanggulangan bencana yaitu pengelolaan risiko bencana yang efisien dan tepat guna untuk mewujudkan resiliensi terhadap bencana serta melindungi kehidupan dan penghidupan masyarakat. Hal tersebut ditopang melalui penataan ruang, penurunan tingkat kerentanan bencana, peningkatan kemampuan untuk merespons saat kejadian bencana dan pemulihan pascabencana, peningkatan kapasitas dan kompetensi sumber daya manusia bidang penanggulangan bencana serta pembangunan infrastruktur berketahanan bencana.', 'Lampiran hal. 124', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4431, 'perban-5-2025', 236, 'lampiran', 'Lampiran hal. 124', NULL, 124, 'Selain itu, pengelolaan risiko bencana juga difokuskan pada penguatan kerangka regulasi, penguatan kelembagaan dan pendanaan, peningkatan kolaborasi multipihak dalam penanggulangan bencana, serta penguatan investasi pengelolaan risiko bencana untuk mewujudkan sistem penanggulangan bencana yang efisien dan efektif.
Dalam rangka mewujudkan Prioritas Nasional 8, dalam RPJMN telah ditetapkan rumusan indikator utama Program Prioritas sebagai koordinator pencapaian indikator Program Prioritas yaitu persentase penurunan nilai indeks risiko bencana nasional dengan target penurunan sebesar 1,2 persen berturut-turut selama 5 tahun ke depan. Program Prioritas diturunkan dalam kegiatan prioritas untuk memastikan bahwa tujuan-tujuan strategis dapat tercapai dengan lebih efektif dan efisien.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4431, 'Selain itu, pengelolaan risiko bencana juga difokuskan pada penguatan kerangka regulasi, penguatan kelembagaan dan pendanaan, peningkatan kolaborasi multipihak dalam penanggulangan bencana, serta penguatan investasi pengelolaan risiko bencana untuk mewujudkan sistem penanggulangan bencana yang efisien dan efektif.
Dalam rangka mewujudkan Prioritas Nasional 8, dalam RPJMN telah ditetapkan rumusan indikator utama Program Prioritas sebagai koordinator pencapaian indikator Program Prioritas yaitu persentase penurunan nilai indeks risiko bencana nasional dengan target penurunan sebesar 1,2 persen berturut-turut selama 5 tahun ke depan. Program Prioritas diturunkan dalam kegiatan prioritas untuk memastikan bahwa tujuan-tujuan strategis dapat tercapai dengan lebih efektif dan efisien.', 'Lampiran hal. 124', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4432, 'perban-5-2025', 237, 'lampiran', 'Lampiran hal. 125', NULL, 125, 'Selanjutnya Kegiatan Prioritas perlu diturunkan menjadi proyek Prioritas Nasional yang merupakan inisiatif yang ditetapkan oleh Pemerintah untuk mencapai tujuan pembangunan strategis dan prioritas dalam jangka waktu tertentu yang dituangkan dalam RPJM yang mencangkup berbagai sektor pembangunan. Proyek Prioritas perlu dilengkapi dengan output-output prioritas yang jelas dan terukur. Dalam struktur RPJMN 2025-2029 Program Prioritas dirinci menjadi 5 Kegiatan Prioritas diantaranya peningkatan upaya pencegahan dan mitigasi, peningkatan layanan peringatan dini dan penanganan kedaruratan bencana, pemenuhan kebutuhan rehabilitasi dan rekonstruksi pascabencana, dan peningkatan resiliensi terhadap bencana serta peningkatan infrastruktur berketahanan bencana. BNPB fokus mengampu pada 4 Kegiatan Prioritas dari 5 Kegiatan Prioritas yang ada diantaranya:
1. Peningkatan upaya pencegahan dan mitigasi dengan indikator persentase daerah yang memiliki tingkat kapasitas penanggulangan bencana minimal pada kategori sedang dengan target tahun 2025 sebesar 67 persen dan tahun 2029 bertambah menjadi 90 persen. Kegiatan Prioritas ini memiliki 3 Proyek Prioritas dan Output Prioritas sebagai pendukung pencapaian Proyek Prioritas:
Tabel 4.1. Proyek dan Output Prioritas KP Pertama No Proyek Prioritas Output Prioritas Target');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4432, 'Selanjutnya Kegiatan Prioritas perlu diturunkan menjadi proyek Prioritas Nasional yang merupakan inisiatif yang ditetapkan oleh Pemerintah untuk mencapai tujuan pembangunan strategis dan prioritas dalam jangka waktu tertentu yang dituangkan dalam RPJM yang mencangkup berbagai sektor pembangunan. Proyek Prioritas perlu dilengkapi dengan output-output prioritas yang jelas dan terukur. Dalam struktur RPJMN 2025-2029 Program Prioritas dirinci menjadi 5 Kegiatan Prioritas diantaranya peningkatan upaya pencegahan dan mitigasi, peningkatan layanan peringatan dini dan penanganan kedaruratan bencana, pemenuhan kebutuhan rehabilitasi dan rekonstruksi pascabencana, dan peningkatan resiliensi terhadap bencana serta peningkatan infrastruktur berketahanan bencana. BNPB fokus mengampu pada 4 Kegiatan Prioritas dari 5 Kegiatan Prioritas yang ada diantaranya:
1. Peningkatan upaya pencegahan dan mitigasi dengan indikator persentase daerah yang memiliki tingkat kapasitas penanggulangan bencana minimal pada kategori sedang dengan target tahun 2025 sebesar 67 persen dan tahun 2029 bertambah menjadi 90 persen. Kegiatan Prioritas ini memiliki 3 Proyek Prioritas dan Output Prioritas sebagai pendukung pencapaian Proyek Prioritas:
Tabel 4.1. Proyek dan Output Prioritas KP Pertama No Proyek Prioritas Output Prioritas Target', 'Lampiran hal. 125', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4433, 'perban-5-2025', 238, 'lampiran', 'Lampiran hal. 125', NULL, 125, '1. Peningkatan kapasitas dalam penanganan 200 orang setiap Kapasitas Aparat korban dan pengungsi tahun Pemerintah Penanggulangan Lokasi sasaran utama Kota Bencana Surakarta, Kota Salatiga dan Kota Balikpapan 10 orang setiap Kota Pendampingan Sistem Komando 105 orang setiap Penanganan Darurat Bencana tahun dan Keposkoan Pendampingan Petugas 120 orang setiap Pengkajian Kebutuhan tahun, dan 40 Pascabencana dan Rehabilitasi orang di tahun Rekonstruksi Pascabencana 2029 Pendidikan dan Pelatihan Teknis 200 orang tahun PB Prioritas Nasional 2025 dan 239 orang tahun 2029 Pendidikan dan Pelatihan Teknis 280 orang tahun PB bagi Fasilitator Nasional 2025 dan 1.660 orang tahun 2029 Simulasi PB Prioritas Nasional 200 orang tahun 2025 dan 540 orang tahun 2029
2. Koordinasi dan Pemetaan Komponen Kerentanan 2 rekomendasi Penyusunan dan Kapasitas kebijakan setiap Dokumen tahun Penanggulangan Bencana Penilaian Indeks Risiko dan 1 rekomendasi Ketahanan Daerah terhadap kebijakan di tahun bencana 2025 dan 2029 sebanyak 2 rekomendasi kebijakan Penguatan Strategi Bidang 2 rekomendasi Penanggulangan Bencana kebijakan setiap tahun Advokasi Strategi 2 rekomendasi Penanggulangan Bencana kebijakan Tingkat Global dan Regional Advokasi Capaian untuk RIPB, 2 rekomendasi Renas PB dan SFDRR kebijakan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4433, '1. Peningkatan kapasitas dalam penanganan 200 orang setiap Kapasitas Aparat korban dan pengungsi tahun Pemerintah Penanggulangan Lokasi sasaran utama Kota Bencana Surakarta, Kota Salatiga dan Kota Balikpapan 10 orang setiap Kota Pendampingan Sistem Komando 105 orang setiap Penanganan Darurat Bencana tahun dan Keposkoan Pendampingan Petugas 120 orang setiap Pengkajian Kebutuhan tahun, dan 40 Pascabencana dan Rehabilitasi orang di tahun Rekonstruksi Pascabencana 2029 Pendidikan dan Pelatihan Teknis 200 orang tahun PB Prioritas Nasional 2025 dan 239 orang tahun 2029 Pendidikan dan Pelatihan Teknis 280 orang tahun PB bagi Fasilitator Nasional 2025 dan 1.660 orang tahun 2029 Simulasi PB Prioritas Nasional 200 orang tahun 2025 dan 540 orang tahun 2029
2. Koordinasi dan Pemetaan Komponen Kerentanan 2 rekomendasi Penyusunan dan Kapasitas kebijakan setiap Dokumen tahun Penanggulangan Bencana Penilaian Indeks Risiko dan 1 rekomendasi Ketahanan Daerah terhadap kebijakan di tahun bencana 2025 dan 2029 sebanyak 2 rekomendasi kebijakan Penguatan Strategi Bidang 2 rekomendasi Penanggulangan Bencana kebijakan setiap tahun Advokasi Strategi 2 rekomendasi Penanggulangan Bencana kebijakan Tingkat Global dan Regional Advokasi Capaian untuk RIPB, 2 rekomendasi Renas PB dan SFDRR kebijakan', 'Lampiran hal. 125', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4434, 'perban-5-2025', 239, 'lampiran', 'Lampiran hal. 126', NULL, 126, '3. Penyediaan Logistik Bantuan Peralatan/Sarana 60 unit ditahun dan Peralatan sesuai 2025 dan 1.245 Standar unit di tahun 2029 Penanggulangan Bencana Distribusi Logistik dan Peralatan 14 paket ditahun PB 2025-2029
2. Peningkatan layanan peringatan dini dan penanganan kedaruratan bencana dengan 2 (dua) Indikator yaitu Persentase cakupan layanan peringatan dini di daerah berisiko bencana, dan Persentase daerah yang menetapkan status keadaan darurat bencana dan menerima intervensi sesuai standar. Kegiatan Prioritas ini memiliki 2 (dua) Proyek Prioritas dan Output Prioritas sebagai pendukung pencapaian Proyek Prioritas:
Tabel 4.2. Proyek dan Output Prioritas KP Kedua No Proyek Prioritas Output Prioritas Target
1. Pendampingan Penyaluran dana siap pakai 30 paket per penanganan tahun kedaruratan bencana
2. Pelayanan peringatan Penguatan Instrumen Peringatan 23 paket tahun dini multi ancaman Dini Bencana 2025 dan 170 bencana paket tahun 2029 Sistem Informasi Bidang 3 sistem informasi Kebencanaan
3. Pemenuhan kebutuhan rehabilitasi dan rekonstruksi pascabencana dengan indikator Persentase daerah pasca bencana masif yang ditangani. Kegiatan Prioritas ini memiliki 2 Proyek Prioritas dan Output Prioritas sebagai pendukung pencapaian Proyek Prioritas:
Tabel 4.3. Proyek dan Output Prioritas KP Ketiga No Proyek Prioritas Output Prioritas Target');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4434, '3. Penyediaan Logistik Bantuan Peralatan/Sarana 60 unit ditahun dan Peralatan sesuai 2025 dan 1.245 Standar unit di tahun 2029 Penanggulangan Bencana Distribusi Logistik dan Peralatan 14 paket ditahun PB 2025-2029
2. Peningkatan layanan peringatan dini dan penanganan kedaruratan bencana dengan 2 (dua) Indikator yaitu Persentase cakupan layanan peringatan dini di daerah berisiko bencana, dan Persentase daerah yang menetapkan status keadaan darurat bencana dan menerima intervensi sesuai standar. Kegiatan Prioritas ini memiliki 2 (dua) Proyek Prioritas dan Output Prioritas sebagai pendukung pencapaian Proyek Prioritas:
Tabel 4.2. Proyek dan Output Prioritas KP Kedua No Proyek Prioritas Output Prioritas Target
1. Pendampingan Penyaluran dana siap pakai 30 paket per penanganan tahun kedaruratan bencana
2. Pelayanan peringatan Penguatan Instrumen Peringatan 23 paket tahun dini multi ancaman Dini Bencana 2025 dan 170 bencana paket tahun 2029 Sistem Informasi Bidang 3 sistem informasi Kebencanaan
3. Pemenuhan kebutuhan rehabilitasi dan rekonstruksi pascabencana dengan indikator Persentase daerah pasca bencana masif yang ditangani. Kegiatan Prioritas ini memiliki 2 Proyek Prioritas dan Output Prioritas sebagai pendukung pencapaian Proyek Prioritas:
Tabel 4.3. Proyek dan Output Prioritas KP Ketiga No Proyek Prioritas Output Prioritas Target', 'Lampiran hal. 126', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4435, 'perban-5-2025', 240, 'lampiran', 'Lampiran hal. 127', NULL, 127, '1. Pemulihan kehidupan Pendampingan pemulihan bidang 3 daerah setiap masyarakat fisik di wilayah terdampak bencana tahun pascabencana masif Layanan fasilitasi pemulihan dan 5 layanan peningkatan bidang sosial di daerah tahun 2025 dan pascabencana 6 layanan 2029 Layanan fasilitasi pemulihan dan 5 layanan peningkatan bidang sumber daya tahun 2025 alam dan lingkungan di daerah pascabencana
2. Pemulihan ekonomi Layanan fasilitasi pemulihan dan 6 Layanan terintegrasi peningkatan bidang ekonomi di tahun 2025 pascabencana daerah pascabencana
4. Peningkatan resiliensi masyarakat terhadap bencana dengan indikator persentase desa berketahanan bencana multipihak. Kegiatan Prioritas ini memiliki 1 Proyek Prioritas dan Output Prioritas sebagai pendukung pencapaian Proyek Prioritas:
Tabel 4.4. Proyek dan Output Prioritas KP Keempat No Proyek Prioritas Output Prioritas Target');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4435, '1. Pemulihan kehidupan Pendampingan pemulihan bidang 3 daerah setiap masyarakat fisik di wilayah terdampak bencana tahun pascabencana masif Layanan fasilitasi pemulihan dan 5 layanan peningkatan bidang sosial di daerah tahun 2025 dan pascabencana 6 layanan 2029 Layanan fasilitasi pemulihan dan 5 layanan peningkatan bidang sumber daya tahun 2025 alam dan lingkungan di daerah pascabencana
2. Pemulihan ekonomi Layanan fasilitasi pemulihan dan 6 Layanan terintegrasi peningkatan bidang ekonomi di tahun 2025 pascabencana daerah pascabencana
4. Peningkatan resiliensi masyarakat terhadap bencana dengan indikator persentase desa berketahanan bencana multipihak. Kegiatan Prioritas ini memiliki 1 Proyek Prioritas dan Output Prioritas sebagai pendukung pencapaian Proyek Prioritas:
Tabel 4.4. Proyek dan Output Prioritas KP Keempat No Proyek Prioritas Output Prioritas Target', 'Lampiran hal. 127', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4436, 'perban-5-2025', 241, 'lampiran', 'Lampiran hal. 127', NULL, 127, '1. Pemberdayaan Penguatan Desa/Kelurahan 10 desa tahun komunitas tangguh Bencana 2025 dan 170 masyarakat untuk desa tahun pengurangan risiko 2029 bencana Kerangka logis dari Rencana Strategis BNPB 2025-2029 menunjukkan hubungan antara sasaran strategis, sasaran program, dan sasaran kegiatan. Kerangka logis BNPB juga menunjukkan bagaimana program dan kegiatan BNPB dapat menunjang tercapainya cita-cita pembangunan nasional. Dalam pertemuan Bilateral Meeting pada tanggal 25 November 2024 telah dibahas dan disepakati bersama sasaran strategis yang merupakan bagian penting dari manajemen kinerja organisasi yang merupakan tujuan jangka panjang yang ingin dicapai oleh suatu organisasi untuk mendukung visi dan misi. Sasaran strategis tersebut telah dilengkapi dengan rumusan indikator sasaran strategis yang merupakan indikator kinerja utama BNPB yang mengadopsi dari RPJMN 2025-2029. IKU ini membantu organisasi untuk mengevaluasi seberapa baik dalam mencapai sasaran strategis. Pada RPJMN Tahun 2025-2029 bidang penanggulangan bencana tertuang dalam Misi ke 8 Memperkuat penyelarasan kehidupan yang harmonis dengan lingkungan alam dan budaya serta peningkatan toleransi antarumat beragama untuk mencapai masyarakat yang adil dan makmur dengan sasaran utama pembangunan resiliensi terhadap bencana dan perubahan iklim.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4436, '1. Pemberdayaan Penguatan Desa/Kelurahan 10 desa tahun komunitas tangguh Bencana 2025 dan 170 masyarakat untuk desa tahun pengurangan risiko 2029 bencana Kerangka logis dari Rencana Strategis BNPB 2025-2029 menunjukkan hubungan antara sasaran strategis, sasaran program, dan sasaran kegiatan. Kerangka logis BNPB juga menunjukkan bagaimana program dan kegiatan BNPB dapat menunjang tercapainya cita-cita pembangunan nasional. Dalam pertemuan Bilateral Meeting pada tanggal 25 November 2024 telah dibahas dan disepakati bersama sasaran strategis yang merupakan bagian penting dari manajemen kinerja organisasi yang merupakan tujuan jangka panjang yang ingin dicapai oleh suatu organisasi untuk mendukung visi dan misi. Sasaran strategis tersebut telah dilengkapi dengan rumusan indikator sasaran strategis yang merupakan indikator kinerja utama BNPB yang mengadopsi dari RPJMN 2025-2029. IKU ini membantu organisasi untuk mengevaluasi seberapa baik dalam mencapai sasaran strategis. Pada RPJMN Tahun 2025-2029 bidang penanggulangan bencana tertuang dalam Misi ke 8 Memperkuat penyelarasan kehidupan yang harmonis dengan lingkungan alam dan budaya serta peningkatan toleransi antarumat beragama untuk mencapai masyarakat yang adil dan makmur dengan sasaran utama pembangunan resiliensi terhadap bencana dan perubahan iklim.', 'Lampiran hal. 127', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4437, 'perban-5-2025', 242, 'lampiran', 'Lampiran hal. 127', NULL, 127, 'Selanjutnya resiliensi terhadap bencana dan perubahan iklim diadopsi menjadi sasaran strategis BNPB dengan 2 (dua) indikator pembangunan ditetapkan sebagai sasaran strategis yang merupakan turunan RPJMN 2025-2029 yaitu: 1) Persentase Penurunan Nilai Indeks Risiko Bencana Nasional 1,2% setiap tahunnya; dan 2) Persentase Daerah yang memiliki tingkat kapasitas penanggulangan bencana minimal kategori sedang dari 67% menjadi 90%. Sasaran Strategis Kedua “meningkatnya kualitas tata Kelola BNPB” dengan Indikator kinerjanya adalah Indeks Reformasi Birokrasi, dengan target sebesar 77,18 di tahun 2025 dan 79 untuk target 2029 dengan baseline capaian Indeks Reformasi Birokrasi tahun 2024 sebesar 77,18.
Selanjutnya untuk rumusan Sasaran Program yang merupakan tujuan spesifik dari masing-masing program yang dirancang untuk mencapai sasaran strategis telah berhasil dirumuskan oleh masing-masing Unit Kerja Eselon I dengan dilengkapi dengan indikator sasaran program sebagai alat ukur pencapaian sasaran program.
Sasaran program dan indikator sasaran program akan menjadi kinerja pejabat Eselon I. Pejabat Eselon I bertanggung jawab untuk memastikan bahwa sasaran program yang telah ditetapkan dapat dicapai dengan efektif dan efisien. Berdasarkan hasil Bilateral Meeting BNPB dengan Bappenas telah disepakati sasaran program masing-masing Unit Kerja Eselon I BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4437, 'Selanjutnya resiliensi terhadap bencana dan perubahan iklim diadopsi menjadi sasaran strategis BNPB dengan 2 (dua) indikator pembangunan ditetapkan sebagai sasaran strategis yang merupakan turunan RPJMN 2025-2029 yaitu: 1) Persentase Penurunan Nilai Indeks Risiko Bencana Nasional 1,2% setiap tahunnya; dan 2) Persentase Daerah yang memiliki tingkat kapasitas penanggulangan bencana minimal kategori sedang dari 67% menjadi 90%. Sasaran Strategis Kedua “meningkatnya kualitas tata Kelola BNPB” dengan Indikator kinerjanya adalah Indeks Reformasi Birokrasi, dengan target sebesar 77,18 di tahun 2025 dan 79 untuk target 2029 dengan baseline capaian Indeks Reformasi Birokrasi tahun 2024 sebesar 77,18.
Selanjutnya untuk rumusan Sasaran Program yang merupakan tujuan spesifik dari masing-masing program yang dirancang untuk mencapai sasaran strategis telah berhasil dirumuskan oleh masing-masing Unit Kerja Eselon I dengan dilengkapi dengan indikator sasaran program sebagai alat ukur pencapaian sasaran program.
Sasaran program dan indikator sasaran program akan menjadi kinerja pejabat Eselon I. Pejabat Eselon I bertanggung jawab untuk memastikan bahwa sasaran program yang telah ditetapkan dapat dicapai dengan efektif dan efisien. Berdasarkan hasil Bilateral Meeting BNPB dengan Bappenas telah disepakati sasaran program masing-masing Unit Kerja Eselon I BNPB.', 'Lampiran hal. 127', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4438, 'perban-5-2025', 243, 'lampiran', 'Lampiran hal. 129', NULL, 129, 'Grafik 4.1. Kerangka Logis Sasaran BNPB 2025-2029 Sumber: Analisis Penulis, 2024 Grafik 4.2. Kerangka Logis Indikator Kinerja BNPB 2025-2029 Sumber: Analisis Penulis, 2024 Setiap program kerja memiliki satu sasaran program yang ditetapkan untuk memantau dan mengevaluasi kemajuan pencapaian tujuan dan sasaran.
Keberjalanan dari setiap program diukur kinerjanya melalui indikator dan target yang tertera pada kerangka tersebut. Adapun indikator dari masing-masing sasaran program adalah sebagai berikut:
1. Program Pengembangan Sistem dan Strategi Penanggulangan Bencana
• Sasaran Program (outcome): Meningkatnya Sinkronisasi Pengembangan Sistem dan Strategi Penanggulangan Bencana Secara Terpadu dan Inovatif.
• Indikator Kinerja Program:
a. Persentase rekomendasi kebijakan sistem dan strategi yang di integrasikan oleh K/L/D ke dalam rencana pembangunan/sektoral.
2. Program Ketangguhan Masyarakat terhadap Bencana ● Sasaran Program (outcome): Meningkatnya kualitas masyarakat yang Tangguh terhadap Bencana di Kawasan Berisiko Bencana. ● Indikator Kinerja Program:
a. Persentase cakupan layanan peringatan dini di daerah berisiko bencana.
b. Persentase desa berketahanan bencana multipihak.
c. Persentase cakupan layanan mitigasi bencana di daerah berisiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4438, 'Grafik 4.1. Kerangka Logis Sasaran BNPB 2025-2029 Sumber: Analisis Penulis, 2024 Grafik 4.2. Kerangka Logis Indikator Kinerja BNPB 2025-2029 Sumber: Analisis Penulis, 2024 Setiap program kerja memiliki satu sasaran program yang ditetapkan untuk memantau dan mengevaluasi kemajuan pencapaian tujuan dan sasaran.
Keberjalanan dari setiap program diukur kinerjanya melalui indikator dan target yang tertera pada kerangka tersebut. Adapun indikator dari masing-masing sasaran program adalah sebagai berikut:
1. Program Pengembangan Sistem dan Strategi Penanggulangan Bencana
• Sasaran Program (outcome): Meningkatnya Sinkronisasi Pengembangan Sistem dan Strategi Penanggulangan Bencana Secara Terpadu dan Inovatif.
• Indikator Kinerja Program:
a. Persentase rekomendasi kebijakan sistem dan strategi yang di integrasikan oleh K/L/D ke dalam rencana pembangunan/sektoral.
2. Program Ketangguhan Masyarakat terhadap Bencana ● Sasaran Program (outcome): Meningkatnya kualitas masyarakat yang Tangguh terhadap Bencana di Kawasan Berisiko Bencana. ● Indikator Kinerja Program:
a. Persentase cakupan layanan peringatan dini di daerah berisiko bencana.
b. Persentase desa berketahanan bencana multipihak.
c. Persentase cakupan layanan mitigasi bencana di daerah berisiko bencana.', 'Lampiran hal. 129', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4439, 'perban-5-2025', 244, 'lampiran', 'Lampiran hal. 130', NULL, 130, '3. Program Manajemen Penanganan Darurat Bencana ● Sasaran Program (outcome): Meningkatnya kualitas Manajemen Penanganan Darurat pada Saat Kejadian Bencana. ● Indikator Kinerja Program: Persentase Daerah yang menetapkan status keadaan darurat bencana dan menerima intervensi sesuai standar.
4. Program Rehabilitasi dan Rekonstruksi Pascabencana ● Sasaran Program (outcome): Meningkatnya Kualitas Layanan Pemulihan Pascabencana Sektor Permukiman, Infrastruktur, Sosial, Ekonomi dan Lintas Sektor. ● Indikator Kinerja Program: Persentase Daerah pasca bencana masif yang ditangani.
5. Program Logistik dan Peralatan ● Sasaran Program (outcome): Meningkatnya Ketahanan Logistik dan Peralatan yang Berkelanjutan dalam Mendukung PB Berdasarkan Wilayah. ● Indikator Kinerja Program: Persentase Daerah yang difasilitasi Logistik dan Peralatan PB serta Sumber Daya Manusia yang Mampu Mengelola.
6. Program Koordinasi, Pembinaan, dan Dukungan Tata Kelola (Dukungan Manajemen) ● Sasaran Program (outcome): Meningkatnya Kualitas Tata Kelola Penyelenggaraan Penanggulangan Bencana yang Profesional, Akuntabel dan Transparan. ● Indikator Kinerja Program: Nilai Reformasi Birokrasi.
7. Program Pengawasan (Dukungan Manajemen) ● Sasaran Program (outcome): Meningkatnya Pengawasan yang Akuntabel dan Transparan. ● Indikator Kinerja Program:
a. Skor Kapabilitas APIP.
b. Persentase Tindak Lanjut Hasil Pemeriksaan BPK RI.
c. Persentase Pelaksanaan Tindak Lanjut Pengaduan Masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4439, '3. Program Manajemen Penanganan Darurat Bencana ● Sasaran Program (outcome): Meningkatnya kualitas Manajemen Penanganan Darurat pada Saat Kejadian Bencana. ● Indikator Kinerja Program: Persentase Daerah yang menetapkan status keadaan darurat bencana dan menerima intervensi sesuai standar.
4. Program Rehabilitasi dan Rekonstruksi Pascabencana ● Sasaran Program (outcome): Meningkatnya Kualitas Layanan Pemulihan Pascabencana Sektor Permukiman, Infrastruktur, Sosial, Ekonomi dan Lintas Sektor. ● Indikator Kinerja Program: Persentase Daerah pasca bencana masif yang ditangani.
5. Program Logistik dan Peralatan ● Sasaran Program (outcome): Meningkatnya Ketahanan Logistik dan Peralatan yang Berkelanjutan dalam Mendukung PB Berdasarkan Wilayah. ● Indikator Kinerja Program: Persentase Daerah yang difasilitasi Logistik dan Peralatan PB serta Sumber Daya Manusia yang Mampu Mengelola.
6. Program Koordinasi, Pembinaan, dan Dukungan Tata Kelola (Dukungan Manajemen) ● Sasaran Program (outcome): Meningkatnya Kualitas Tata Kelola Penyelenggaraan Penanggulangan Bencana yang Profesional, Akuntabel dan Transparan. ● Indikator Kinerja Program: Nilai Reformasi Birokrasi.
7. Program Pengawasan (Dukungan Manajemen) ● Sasaran Program (outcome): Meningkatnya Pengawasan yang Akuntabel dan Transparan. ● Indikator Kinerja Program:
a. Skor Kapabilitas APIP.
b. Persentase Tindak Lanjut Hasil Pemeriksaan BPK RI.
c. Persentase Pelaksanaan Tindak Lanjut Pengaduan Masyarakat.', 'Lampiran hal. 130', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4440, 'perban-5-2025', 245, 'lampiran', 'Lampiran hal. 131', NULL, 131, 'd. Persentase Tindak Lanjut Hasil Pengawasan APIP.
Untuk menopang masing-masing program dan sasarannya, BNPB juga telah merancang turunan dari sasaran program mulai dari sasaran kegiatan sampai level klasifikasi rincian output yang mendukung pencapaian indikator sasaran program sebagaimana yang tertuang di kerangka kerja dan kerangka pendanaan di bawah ini.
4.1. Target Kinerja Sasaran strategis BNPB tahun 2025-2029 yang merupakan kinerja dari Kepala BNPB adalah “Resiliensi Terhadap Bencana” dengan dua indikator sasaran strategis yaitu Penurunan Nilai Indeks Risiko Bencana Indonesia 1,2% setiap tahunnya dan Persentase Daerah yang memiliki tingkat kapasitas penanggulangan bencana minimal kategori sedang dari 67% menjadi 90%. Sasaran Strategis yang ke-dua adalah “Meningkatnya Kualitas Tata Kelola BNPB” dengan indikator sasaran strategis yaitu Indeks Reformasi Birokrasi meningkat dari 77,18 menjadi 79. Sasaran strategis tersebut telah dikembangkan menjadi tujuh sasaran program dengan 12 (dua belas) indikator sasaran program.
Tabel 4.5. Sasaran Strategis dan Indikator Sasaran Strategis BNPB 2025-2029 Sasaran Indikator Sasaran No 2025 2026 2027 2028 2029 Strategis Strategis');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4440, 'd. Persentase Tindak Lanjut Hasil Pengawasan APIP.
Untuk menopang masing-masing program dan sasarannya, BNPB juga telah merancang turunan dari sasaran program mulai dari sasaran kegiatan sampai level klasifikasi rincian output yang mendukung pencapaian indikator sasaran program sebagaimana yang tertuang di kerangka kerja dan kerangka pendanaan di bawah ini.
4.1. Target Kinerja Sasaran strategis BNPB tahun 2025-2029 yang merupakan kinerja dari Kepala BNPB adalah “Resiliensi Terhadap Bencana” dengan dua indikator sasaran strategis yaitu Penurunan Nilai Indeks Risiko Bencana Indonesia 1,2% setiap tahunnya dan Persentase Daerah yang memiliki tingkat kapasitas penanggulangan bencana minimal kategori sedang dari 67% menjadi 90%. Sasaran Strategis yang ke-dua adalah “Meningkatnya Kualitas Tata Kelola BNPB” dengan indikator sasaran strategis yaitu Indeks Reformasi Birokrasi meningkat dari 77,18 menjadi 79. Sasaran strategis tersebut telah dikembangkan menjadi tujuh sasaran program dengan 12 (dua belas) indikator sasaran program.
Tabel 4.5. Sasaran Strategis dan Indikator Sasaran Strategis BNPB 2025-2029 Sasaran Indikator Sasaran No 2025 2026 2027 2028 2029 Strategis Strategis', 'Lampiran hal. 131', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4441, 'perban-5-2025', 246, 'lampiran', 'Lampiran hal. 132', NULL, 132, '1. Resiliensi Persentase Terhadap Penurunan Nilai A 1,2% 1,2% 1,2% 1,2% 1,2% Bencana Indeks Risiko Bencana Nasional Persentase Daerah yang memiliki tingkat kapasitas 67% 73% 79% 85% 90% B penanggulangan bencana minimal kategori sedang 2 Meningkatnya Indeks Reformasi Kualitas Tata C 77,18 77,50 78 78,50 79 Birokrasi Kelola BNPB Sasaran program, indikator sasaran program dan target kinerja sasaran program untuk periode tahun 2025-2029 dilaksanakan oleh unit kerja setingkat eselon 1 BNPB. Berdasarkan Peraturan BNPB Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja BNPB terdapat 7 unit kerja setingkat eselon I yaitu Sekretariat Utama, Inspektorat Utama, Deputi Bidang Sistem dan Strategi, Deputi Bidang Pencegahan, Deputi Bidang Penanganan Darurat, Deputi Bidang Rehabilitasi dan Rekonstruksi dan Deputi Bidang Logistik dan Peralatan. Target kinerja sasaran program untuk periode tahun 2025 - 2029 dapat dilihat pada Tabel 4.7 berikut ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4441, '1. Resiliensi Persentase Terhadap Penurunan Nilai A 1,2% 1,2% 1,2% 1,2% 1,2% Bencana Indeks Risiko Bencana Nasional Persentase Daerah yang memiliki tingkat kapasitas 67% 73% 79% 85% 90% B penanggulangan bencana minimal kategori sedang 2 Meningkatnya Indeks Reformasi Kualitas Tata C 77,18 77,50 78 78,50 79 Birokrasi Kelola BNPB Sasaran program, indikator sasaran program dan target kinerja sasaran program untuk periode tahun 2025-2029 dilaksanakan oleh unit kerja setingkat eselon 1 BNPB. Berdasarkan Peraturan BNPB Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja BNPB terdapat 7 unit kerja setingkat eselon I yaitu Sekretariat Utama, Inspektorat Utama, Deputi Bidang Sistem dan Strategi, Deputi Bidang Pencegahan, Deputi Bidang Penanganan Darurat, Deputi Bidang Rehabilitasi dan Rekonstruksi dan Deputi Bidang Logistik dan Peralatan. Target kinerja sasaran program untuk periode tahun 2025 - 2029 dapat dilihat pada Tabel 4.7 berikut ini.', 'Lampiran hal. 132', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4442, 'perban-5-2025', 247, 'lampiran', 'Lampiran hal. 132', NULL, 132, 'Tabel 4.6. Target Kinerja Sasaran Program BNPB 2025-2029 Target (Tahun) No Sasaran Program Indikator Sasaran Program Baseline Unit 2025 2026 2027 2028 2029 1 Meningkatnya a Persentase rekomendasi 82,35% 87,06 90,59 94,12 97,65 100% Sinkronisasi kebijakan sistem dan % % % % Pengembangan strategi yang di Deputi Sistem dan Strategi integrasikan oleh K/L/D Bidang Penanggulangan ke dalam rencana Sistem dan Bencana Secara pembangunan/sektoral Strategi Terpadu dan Inovatif 2 Meningkatnya a Persentase cakupan N/A 6,10 6,17 6,21 6,26 6,32 Kualitas Masyarakat layanan peringatan dini % % % % % yang Tangguh di daerah berisiko terhadap Bencana bencana di Kawasan Berisiko b Persentase desa N/A 10,49 10,75 11,07 11,46 11,74 Deputi Bencana berketahanan bencana % % % % % Bidang multipihak Pencegahan c Persentase cakupan N/A 7,39 10,12 13,04 15,95 18,87 layanan mitigasi % % % % % bencana di daerah berisiko bencana 3 Meningkatnya a Persentase Daerah yang Manajemen menetapkan status Deputi Penanganan keadaan darurat Bidang N/A 100% 100% 100% 100% 100% Darurat Saat bencana dan menerima Penanganan Kejadian Bencana intervensi sesuai standar Darurat 4 Meningkatnya a Persentase Daerah kualitas layanan pascabencana masif Deputi Pemulihan yang ditangani Bidang Pascabencana N/A 100% 100% 100% 100% 100% Rehabilitasi Sektor Permukiman dan Infrastruktur Sosial, Rekonstruksi Ekonomi dan Lintas Sektor 5 Meningkatnya a Persentase daerah yang Ketahanan Logistik difasilitasi logistik dan dan Peralatan yang');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4442, 'Tabel 4.6. Target Kinerja Sasaran Program BNPB 2025-2029 Target (Tahun) No Sasaran Program Indikator Sasaran Program Baseline Unit 2025 2026 2027 2028 2029 1 Meningkatnya a Persentase rekomendasi 82,35% 87,06 90,59 94,12 97,65 100% Sinkronisasi kebijakan sistem dan % % % % Pengembangan strategi yang di Deputi Sistem dan Strategi integrasikan oleh K/L/D Bidang Penanggulangan ke dalam rencana Sistem dan Bencana Secara pembangunan/sektoral Strategi Terpadu dan Inovatif 2 Meningkatnya a Persentase cakupan N/A 6,10 6,17 6,21 6,26 6,32 Kualitas Masyarakat layanan peringatan dini % % % % % yang Tangguh di daerah berisiko terhadap Bencana bencana di Kawasan Berisiko b Persentase desa N/A 10,49 10,75 11,07 11,46 11,74 Deputi Bencana berketahanan bencana % % % % % Bidang multipihak Pencegahan c Persentase cakupan N/A 7,39 10,12 13,04 15,95 18,87 layanan mitigasi % % % % % bencana di daerah berisiko bencana 3 Meningkatnya a Persentase Daerah yang Manajemen menetapkan status Deputi Penanganan keadaan darurat Bidang N/A 100% 100% 100% 100% 100% Darurat Saat bencana dan menerima Penanganan Kejadian Bencana intervensi sesuai standar Darurat 4 Meningkatnya a Persentase Daerah kualitas layanan pascabencana masif Deputi Pemulihan yang ditangani Bidang Pascabencana N/A 100% 100% 100% 100% 100% Rehabilitasi Sektor Permukiman dan Infrastruktur Sosial, Rekonstruksi Ekonomi dan Lintas Sektor 5 Meningkatnya a Persentase daerah yang Ketahanan Logistik difasilitasi logistik dan dan Peralatan yang', 'Lampiran hal. 132', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4443, 'perban-5-2025', 248, 'lampiran', 'Lampiran hal. 132', NULL, 132, 'peralatan PB serta Deputi Berkelanjutan sumber daya manusia Bidang dalam Mendukung yang mampu mengelola N/A 35% 45% 55% 65% 75% Logistik dan Penanggulangan Peralatan Bencana Berdasarkan Wilayah 6 Meningkatnya a Nilai Reformasi Birokrasi Kualitas Tata Kelola Penyelenggaraan Penanggulangan Sekretariat 77,18 77,18 77,50 78 78,50 79 Bencana yang Utama Profesional, Akuntabel dan Transparan 7 Meningkatnya a Skor Kapabilitas APIP 3,04 3,05 3,1 3,15 3,2 3,25 Pengawasan yang Akuntabel dan b Persentase tindak lanjut Transparan Hasil Pemeriksaan BPK 75% 75% 75% 75% 75% 75% RI Inspektorat c Persentase pelaksanaan Utama tindak lanjut pengaduan 100% 100% 100% 100% 100% 100% masyarakat d Persentase tindak lanjut 40% 46% 52% 58% 64% 70% hasil pengawasan APIP Sasaran kegiatan, indikator sasaran kegiatan dan target kinerja sasaran kegiatan untuk periode tahun 2025-2029 dilaksanakan oleh unit kerja setingkat eselon II BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4443, 'peralatan PB serta Deputi Berkelanjutan sumber daya manusia Bidang dalam Mendukung yang mampu mengelola N/A 35% 45% 55% 65% 75% Logistik dan Penanggulangan Peralatan Bencana Berdasarkan Wilayah 6 Meningkatnya a Nilai Reformasi Birokrasi Kualitas Tata Kelola Penyelenggaraan Penanggulangan Sekretariat 77,18 77,18 77,50 78 78,50 79 Bencana yang Utama Profesional, Akuntabel dan Transparan 7 Meningkatnya a Skor Kapabilitas APIP 3,04 3,05 3,1 3,15 3,2 3,25 Pengawasan yang Akuntabel dan b Persentase tindak lanjut Transparan Hasil Pemeriksaan BPK 75% 75% 75% 75% 75% 75% RI Inspektorat c Persentase pelaksanaan Utama tindak lanjut pengaduan 100% 100% 100% 100% 100% 100% masyarakat d Persentase tindak lanjut 40% 46% 52% 58% 64% 70% hasil pengawasan APIP Sasaran kegiatan, indikator sasaran kegiatan dan target kinerja sasaran kegiatan untuk periode tahun 2025-2029 dilaksanakan oleh unit kerja setingkat eselon II BNPB.', 'Lampiran hal. 132', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4444, 'perban-5-2025', 249, 'lampiran', 'Lampiran hal. 132', NULL, 132, 'Berdasarkan Peraturan BNPB Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja BNPB terdapat 24 unit kerja setingkat eselon II yaitu Biro SDM dan Umum, Biro Hukum, Organisasi dan Kerja Sama, Biro Perencanaan, Biro Keuangan, Inspektorat I, Inspektorat II, Inspektorat III, Direktorat Pemetaan dan Evaluasi Risiko Bencana, Direktorat Pengembangan Strategi PB, Direktorat Sistem PB, Direktorat Mitigasi Bencana, Direktorat Kesiapsiagaan, Direktorat Peringatan Dini, Direktorat Dukungan Sumber Daya Darurat, Direktorat Dukungan Infrastruktur Darurat, Direktorat Fasilitasi Penanganan Korban dan Pengungsi, Direktorat Perencanaan Rehabilitasi dan Rekonstruksi, Direktorat Pemulihan dan Peningkatan Fisik, Direktorat Pemulihan dan Peningkatan Sosial, Ekonomi dan Sumber Daya Alam, Direktorat Pengelolaan Logistik dan Peralatan, Direktorat Optimasi Jaringan Logistik dan Peralatan, Pusat Data, Informasi dan Komunikasi Kebencanaan, Pusat Pendidikan dan Pelatihan PB, dan Pusat Pengendalian Operasi. Untuk masing-masing unit kerja setingkat eselon II mempunyai target kinerja sasaran kegiatan untuk periode tahun 2025-2029 yang dapat dilihat pada Tabel 4.8. berikut ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4444, 'Berdasarkan Peraturan BNPB Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja BNPB terdapat 24 unit kerja setingkat eselon II yaitu Biro SDM dan Umum, Biro Hukum, Organisasi dan Kerja Sama, Biro Perencanaan, Biro Keuangan, Inspektorat I, Inspektorat II, Inspektorat III, Direktorat Pemetaan dan Evaluasi Risiko Bencana, Direktorat Pengembangan Strategi PB, Direktorat Sistem PB, Direktorat Mitigasi Bencana, Direktorat Kesiapsiagaan, Direktorat Peringatan Dini, Direktorat Dukungan Sumber Daya Darurat, Direktorat Dukungan Infrastruktur Darurat, Direktorat Fasilitasi Penanganan Korban dan Pengungsi, Direktorat Perencanaan Rehabilitasi dan Rekonstruksi, Direktorat Pemulihan dan Peningkatan Fisik, Direktorat Pemulihan dan Peningkatan Sosial, Ekonomi dan Sumber Daya Alam, Direktorat Pengelolaan Logistik dan Peralatan, Direktorat Optimasi Jaringan Logistik dan Peralatan, Pusat Data, Informasi dan Komunikasi Kebencanaan, Pusat Pendidikan dan Pelatihan PB, dan Pusat Pengendalian Operasi. Untuk masing-masing unit kerja setingkat eselon II mempunyai target kinerja sasaran kegiatan untuk periode tahun 2025-2029 yang dapat dilihat pada Tabel 4.8. berikut ini.', 'Lampiran hal. 132', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4445, 'perban-5-2025', 250, 'lampiran', 'Lampiran hal. 134', NULL, 134, 'Tabel 4.7. Target Kinerja Sasaran Kegiatan BNPB 2025-2029 Indikator Target (Tahun) No Sasaran Kegiatan Sasaran Kegiatan 2025 2026 2027 2028 2029 Sasaran Program 1: Meningkatnya Sinkronisasi Pengembangan Sistem dan Strategi Penanggulangan Bencana Secara Terpadu dan Inovatif Deputi Bidang Sistem dan Strategi dan Pusat Data Informasi dan Komunikasi Kebencanaan 1 Direktorat Pemetaan dan Evaluasi Risiko Bencana Persentase Rekomendasi kebijakan dan dukungan teknis di Meningkatnya lingkup Kualitas Pemetaan pemetaan dan 100% 100% 100% 100% 100% dan Evaluasi Risiko evaluasi risiko Bencana bencana yang dimanfaatkan oleh K/L dan atau Pemerintah daerah 2 Direktorat Pengembangan Strategi Penanggulangan Bencana Persentase Rekomendasi Kebijakan dan dukungan teknis di Meningkatnya Lingkup Kualitas Pengembangan Pengembangan Strategi PB 100% 100% 100% 100% 100% Strategi yang Penanggulangan dimanfaatkan Bencana oleh Kementerian/L embaga dan atau Pemerintah Daerah 3 Direktorat Sistem Penanggulangan Bencana Persentase Rekomendasi Kebijakan dan Meningkatnya dukungan Kualitas teknis di Pengembangan lingkup Sistem 100% 100% 100% 100% 100% Sistem PB yang Penanggulangan dimanfaatkan Bencana oleh Kementerian/L embaga dan atau Pemerintah D aerah 4 Pusat Data, Informasi, dan Komunikasi Kebencanaan Persentase Penyampaian layanan informasi 100% 100% 100% 100% 100% kejadian Meningkatnya bencana ke Kualitas Layanan publik kurang Bidang Data, dari 2 jam Informasi dan Komunikasi Penanggulangan Indeks SPBE');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4445, 'Tabel 4.7. Target Kinerja Sasaran Kegiatan BNPB 2025-2029 Indikator Target (Tahun) No Sasaran Kegiatan Sasaran Kegiatan 2025 2026 2027 2028 2029 Sasaran Program 1: Meningkatnya Sinkronisasi Pengembangan Sistem dan Strategi Penanggulangan Bencana Secara Terpadu dan Inovatif Deputi Bidang Sistem dan Strategi dan Pusat Data Informasi dan Komunikasi Kebencanaan 1 Direktorat Pemetaan dan Evaluasi Risiko Bencana Persentase Rekomendasi kebijakan dan dukungan teknis di Meningkatnya lingkup Kualitas Pemetaan pemetaan dan 100% 100% 100% 100% 100% dan Evaluasi Risiko evaluasi risiko Bencana bencana yang dimanfaatkan oleh K/L dan atau Pemerintah daerah 2 Direktorat Pengembangan Strategi Penanggulangan Bencana Persentase Rekomendasi Kebijakan dan dukungan teknis di Meningkatnya Lingkup Kualitas Pengembangan Pengembangan Strategi PB 100% 100% 100% 100% 100% Strategi yang Penanggulangan dimanfaatkan Bencana oleh Kementerian/L embaga dan atau Pemerintah Daerah 3 Direktorat Sistem Penanggulangan Bencana Persentase Rekomendasi Kebijakan dan Meningkatnya dukungan Kualitas teknis di Pengembangan lingkup Sistem 100% 100% 100% 100% 100% Sistem PB yang Penanggulangan dimanfaatkan Bencana oleh Kementerian/L embaga dan atau Pemerintah D aerah 4 Pusat Data, Informasi, dan Komunikasi Kebencanaan Persentase Penyampaian layanan informasi 100% 100% 100% 100% 100% kejadian Meningkatnya bencana ke Kualitas Layanan publik kurang Bidang Data, dari 2 jam Informasi dan Komunikasi Penanggulangan Indeks SPBE', 'Lampiran hal. 134', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4446, 'perban-5-2025', 251, 'lampiran', 'Lampiran hal. 134', NULL, 134, '3,15 Indeks 3,2 Indeks 3,25 Indeks 3,3 Indeks 3,35 Indeks Bencana Indeks Pembangunan 2,6 Indeks 2,7 Indeks 2,8 Indeks 2,9 Indeks 3 Indeks Statistik Sasaran Program 2: Meningkatnya Kualitas Masyarakat yang Tangguh terhadap Bencana di Kawasan Berisiko Bencana Deputi Bidang Pencegahan 1 Direktorat Peringatan Dini Persentase layanan sistem diseminasi peringatan dini 6,14% 6,09% 6,18% 6,23% 6,29% bencana berbasis sirine yang memadai Meningkatnya Layanan Sistem Persentase Peringatan Dini layanan Bencana pembangunan sistem diseminasi peringatan dini 16,67% 33,33% 50% 83,3% 100% bencana berbasis sistem informasi yang memadai 2 Direktorat Mitigasi Bencana Persentase daerah Meningkatnya prioritas hasil daerah prioritas kajian risiko hasil kajian risiko 6,40% bencana yang 14,53% 23,26% 31,98% 40,70% bencana yang difasilitasi difasilitasi upaya upaya mitigasi mitigasi bencana bencana 3 Direktorat Kesiapsiagaan Persentase Meningkatnya daerah yang daerah yang memiliki memiliki dokumen 4,27% 4,61% 4,95% 5,39% 5,82% dokumen rencana aksi rencana aksi kesiapsiagaan kesiapsiagaan Meningkatnya Persentase daerah yang daerah yang 14,30% 14,49% 15,58% 16,67% 17,75% memiliki forum memiliki forum pengurangan risiko pengurangan bencana lembaga risiko bencana usaha dan Lembaga komunitas Usaha dan Komunitas Persentase Meningkatnya daerah yang daerah yang memiliki Desa 2,58% 2,61% 2,77% 2,99% 3,26% memiliki desa tangguh tangguh bencana Bencana Sasaran Program 3: Meningkatnya Manajemen Penanganan Darurat');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4446, '3,15 Indeks 3,2 Indeks 3,25 Indeks 3,3 Indeks 3,35 Indeks Bencana Indeks Pembangunan 2,6 Indeks 2,7 Indeks 2,8 Indeks 2,9 Indeks 3 Indeks Statistik Sasaran Program 2: Meningkatnya Kualitas Masyarakat yang Tangguh terhadap Bencana di Kawasan Berisiko Bencana Deputi Bidang Pencegahan 1 Direktorat Peringatan Dini Persentase layanan sistem diseminasi peringatan dini 6,14% 6,09% 6,18% 6,23% 6,29% bencana berbasis sirine yang memadai Meningkatnya Layanan Sistem Persentase Peringatan Dini layanan Bencana pembangunan sistem diseminasi peringatan dini 16,67% 33,33% 50% 83,3% 100% bencana berbasis sistem informasi yang memadai 2 Direktorat Mitigasi Bencana Persentase daerah Meningkatnya prioritas hasil daerah prioritas kajian risiko hasil kajian risiko 6,40% bencana yang 14,53% 23,26% 31,98% 40,70% bencana yang difasilitasi difasilitasi upaya upaya mitigasi mitigasi bencana bencana 3 Direktorat Kesiapsiagaan Persentase Meningkatnya daerah yang daerah yang memiliki memiliki dokumen 4,27% 4,61% 4,95% 5,39% 5,82% dokumen rencana aksi rencana aksi kesiapsiagaan kesiapsiagaan Meningkatnya Persentase daerah yang daerah yang 14,30% 14,49% 15,58% 16,67% 17,75% memiliki forum memiliki forum pengurangan risiko pengurangan bencana lembaga risiko bencana usaha dan Lembaga komunitas Usaha dan Komunitas Persentase Meningkatnya daerah yang daerah yang memiliki Desa 2,58% 2,61% 2,77% 2,99% 3,26% memiliki desa tangguh tangguh bencana Bencana Sasaran Program 3: Meningkatnya Manajemen Penanganan Darurat', 'Lampiran hal. 134', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4447, 'perban-5-2025', 252, 'lampiran', 'Lampiran hal. 134', NULL, 134, 'Saat Kejadian Bencana Deputi Bidang Penanganan Darurat dan Pusat Pengendalian Operasi 1 Direktorat Dukungan Sumber Daya Darurat Persentase Daerah yang mendapatkan Meningkatnya dukungan Dukungan Sumber sumber daya 100% 100% 100% 100% 100% Daya Saat Keadaan darurat pada Darurat Bencana saat keadaan darurat bencana 2 Direktorat Dukungan Infrastruktur Darurat Persentase Meningkatnya Daerah yang Dukungan Fasilitasi mendapatkan dan Pengelolaan Fasilitasi Pemulihan dengan Dukungan dan 100% 100% 100% 100% 100% Segera Prasarana Pengelolaan dan Sarana Vital Pemulihan pada Saat Keadaan dengan Segera Darurat Bencana Prasarana dan Sarana Vital 3 Direktorat Fasilitasi Penanganan Korban dan Pengungsi Persentase Daerah yang mendapat Meningkatnya Fasilitasi Kegiatan Fasilitasi Penanganan 100% 100% 100% 100% 100% Penanganan Korban Korban dan dan Pengungsi Pengungsi pada Keadaan darurat Bencana 4 Pusat Pengendalian Operasi Persentase Meningkatnya daerah yang Layanan Pusat mengaktivasi Pengendalian posko pada 15% 20% 25% 30% 35% Operasi sesuai saat penetapan standar status keadaan darurat bencana Sasaran Program 4: Meningkatnya Kualitas Layanan Pemulihan Pascabencana Sektor Permukiman, Infrastruktur Sosial, Ekonomi, dan Lintas Sektor Deputi Bidang Rehabilitasi dan Rekonstruksi 1 Direktorat Perencanaan Rehabilitasi dan Rekonstruksi Meningkatnya Persentase Layanan daerah 80% 85% 90% 95% 100% Perencanaan terdampak Rehabilitasi dan bencana yang Rekonstruksi mendapatkan Pascabencana pendampingan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4447, 'Saat Kejadian Bencana Deputi Bidang Penanganan Darurat dan Pusat Pengendalian Operasi 1 Direktorat Dukungan Sumber Daya Darurat Persentase Daerah yang mendapatkan Meningkatnya dukungan Dukungan Sumber sumber daya 100% 100% 100% 100% 100% Daya Saat Keadaan darurat pada Darurat Bencana saat keadaan darurat bencana 2 Direktorat Dukungan Infrastruktur Darurat Persentase Meningkatnya Daerah yang Dukungan Fasilitasi mendapatkan dan Pengelolaan Fasilitasi Pemulihan dengan Dukungan dan 100% 100% 100% 100% 100% Segera Prasarana Pengelolaan dan Sarana Vital Pemulihan pada Saat Keadaan dengan Segera Darurat Bencana Prasarana dan Sarana Vital 3 Direktorat Fasilitasi Penanganan Korban dan Pengungsi Persentase Daerah yang mendapat Meningkatnya Fasilitasi Kegiatan Fasilitasi Penanganan 100% 100% 100% 100% 100% Penanganan Korban Korban dan dan Pengungsi Pengungsi pada Keadaan darurat Bencana 4 Pusat Pengendalian Operasi Persentase Meningkatnya daerah yang Layanan Pusat mengaktivasi Pengendalian posko pada 15% 20% 25% 30% 35% Operasi sesuai saat penetapan standar status keadaan darurat bencana Sasaran Program 4: Meningkatnya Kualitas Layanan Pemulihan Pascabencana Sektor Permukiman, Infrastruktur Sosial, Ekonomi, dan Lintas Sektor Deputi Bidang Rehabilitasi dan Rekonstruksi 1 Direktorat Perencanaan Rehabilitasi dan Rekonstruksi Meningkatnya Persentase Layanan daerah 80% 85% 90% 95% 100% Perencanaan terdampak Rehabilitasi dan bencana yang Rekonstruksi mendapatkan Pascabencana pendampingan', 'Lampiran hal. 134', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4448, 'perban-5-2025', 253, 'lampiran', 'Lampiran hal. 134', NULL, 134, 'perencanaan rehabilitasi dan rekonstruksi pascabencana Persentase Daerah yang mendapatkan rekomendasi 50% 55% 60% 65% 70% bantuan pendanaan pascabencana 2 Direktorat Pemulihan dan Peningkatan Sosial Ekonomi dan SDA Persentase kelompok masyarakat terdampak Meningkatnya bencana masif Layanan Pemulihan yang dan Peningkatan mendapatkan 60% 65% 70% 75% 80% Sosial Ekonomi, pendampingan Sumber Daya Alam pemulihan dan Lingkungan sosial ekonomi dan sumber daya alam sesuai dengan kebutuhan 3 Direktorat Pemulihan dan Peningkatan Fisik Meningkatnya Persentase Layanan Daerah yang Rehabilitasi dan melaksanakan Rekonstruksi pemulihan 70% 75% 80% 85% 90% Bidang Pemulihan fisik dengan dan Peningkatan baik sesuai Fisik standar Sasaran Program 5: Meningkatnya Ketahanan Logistik dan Peralatan yang Berkelanjutan dalam Mendukung Penanggulangan Bencana Berdasarkan Wilayah Deputi Bidang Logistik dan Peralatan 1 Direktorat Pengelolaan Logistik dan Peralatan Persentase Terfasilitasinya daerah yang di pemenuhan logistik 75% 75% 75% 75% 75% fasilitasi di Daerah logistik Persentase Terfasilitasinya daerah yang di pemenuhan 35% 45% 55% 65% 75% fasilitasi peralatan di Daerah peralatan Persentase Tersedianya SDM ketersediaan pengelola logistik SDM Pengelola 35% 45% 55% 65% 75% dan peralatan Logistik dan Peralatan 2 Direktorat Optimasi Jaringan Logistik dan Peralatan Persentase Terpenuhinya logistik dan layanan distribusi peralatan yang 100% 100% 100% 100% 100% logistik dan terdistribusi ke peralatan daerah');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4448, 'perencanaan rehabilitasi dan rekonstruksi pascabencana Persentase Daerah yang mendapatkan rekomendasi 50% 55% 60% 65% 70% bantuan pendanaan pascabencana 2 Direktorat Pemulihan dan Peningkatan Sosial Ekonomi dan SDA Persentase kelompok masyarakat terdampak Meningkatnya bencana masif Layanan Pemulihan yang dan Peningkatan mendapatkan 60% 65% 70% 75% 80% Sosial Ekonomi, pendampingan Sumber Daya Alam pemulihan dan Lingkungan sosial ekonomi dan sumber daya alam sesuai dengan kebutuhan 3 Direktorat Pemulihan dan Peningkatan Fisik Meningkatnya Persentase Layanan Daerah yang Rehabilitasi dan melaksanakan Rekonstruksi pemulihan 70% 75% 80% 85% 90% Bidang Pemulihan fisik dengan dan Peningkatan baik sesuai Fisik standar Sasaran Program 5: Meningkatnya Ketahanan Logistik dan Peralatan yang Berkelanjutan dalam Mendukung Penanggulangan Bencana Berdasarkan Wilayah Deputi Bidang Logistik dan Peralatan 1 Direktorat Pengelolaan Logistik dan Peralatan Persentase Terfasilitasinya daerah yang di pemenuhan logistik 75% 75% 75% 75% 75% fasilitasi di Daerah logistik Persentase Terfasilitasinya daerah yang di pemenuhan 35% 45% 55% 65% 75% fasilitasi peralatan di Daerah peralatan Persentase Tersedianya SDM ketersediaan pengelola logistik SDM Pengelola 35% 45% 55% 65% 75% dan peralatan Logistik dan Peralatan 2 Direktorat Optimasi Jaringan Logistik dan Peralatan Persentase Terpenuhinya logistik dan layanan distribusi peralatan yang 100% 100% 100% 100% 100% logistik dan terdistribusi ke peralatan daerah', 'Lampiran hal. 134', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4449, 'perban-5-2025', 254, 'lampiran', 'Lampiran hal. 134', NULL, 134, 'Persentase Meningkatnya layanan layanan Kemitraan kemitraan 35% 45% 55% 65% 75% Logistik dan terkait logistik Peralatan dan peralatan Sasaran Program 6: Meningkatnya Kualitas Tata Kelola Penyelenggaraan Penanggulangan Bencana Yang Profesional, Akuntabel dan Transparan Sekretariat Utama dan Pusat Pendidikan dan Pelatihan 1 Biro Perencanaan Nilai Indeks Perencanaan 88 Indeks 89 Indeks 90 Indeks 91 Indeks 92 Indeks Pembangunan BNPB Meningkatnya Nilai Capaian Layanan Prioritas 75% 76% 77% 78% 79% Perencanaan, Nasional Pemantauan dan Nilai Sistem Evaluasi Akuntabilitas Kinerja 78,39 Nilai 78,59 Nilai 78,79 Nilai 78,99 Nilai 79,19 Nilai Instansi Pemerintah (Sakip) 2 Biro Keuangan Opini BPK atas Laporan WTP WTP WTP WTP WTP Keuangan BNPB Meningkatnya Nilai Indikator Layanan Kinerja Penatausahaan Pelaksanaan 89 Nilai 89 Nilai 89,5 Nilai 89,5 Nilai 90 Nilai keuangan yang Anggaran tertib, transparan, (IKPA) dan akuntabel Indeks Kepuasan 86,5 Indeks 87 Indeks 87,5 Indeks 88 Indeks 88,50 Indeks Layanan Keuangan 3 Biro Hukum, Organisasi, dan Kerja Sama Rencana Aksi Pembangunan 2,40 Nilai 2,41 Nilai 2,42 Nilai 2,45 Nilai 2,46 Nilai RB General Meningkatnya Tingkat Koordinasi Implementasi 96 Nilai 96 Nilai 97 Nilai 97 Nilai 98 Nilai Pengelolaan Rencana Aksi Penyusunan RB General Peraturan Perundang- Persentase undangan, Penyederhanaa 70% 72% 73% 74% 75% Organisasi, dan Tata n Struktur laksana serta Kerja Organisasi Sama di Bidang Penanggulangan Tingkat Bencana Capaian Sistem Kerja 4 Nilai 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4449, 'Persentase Meningkatnya layanan layanan Kemitraan kemitraan 35% 45% 55% 65% 75% Logistik dan terkait logistik Peralatan dan peralatan Sasaran Program 6: Meningkatnya Kualitas Tata Kelola Penyelenggaraan Penanggulangan Bencana Yang Profesional, Akuntabel dan Transparan Sekretariat Utama dan Pusat Pendidikan dan Pelatihan 1 Biro Perencanaan Nilai Indeks Perencanaan 88 Indeks 89 Indeks 90 Indeks 91 Indeks 92 Indeks Pembangunan BNPB Meningkatnya Nilai Capaian Layanan Prioritas 75% 76% 77% 78% 79% Perencanaan, Nasional Pemantauan dan Nilai Sistem Evaluasi Akuntabilitas Kinerja 78,39 Nilai 78,59 Nilai 78,79 Nilai 78,99 Nilai 79,19 Nilai Instansi Pemerintah (Sakip) 2 Biro Keuangan Opini BPK atas Laporan WTP WTP WTP WTP WTP Keuangan BNPB Meningkatnya Nilai Indikator Layanan Kinerja Penatausahaan Pelaksanaan 89 Nilai 89 Nilai 89,5 Nilai 89,5 Nilai 90 Nilai keuangan yang Anggaran tertib, transparan, (IKPA) dan akuntabel Indeks Kepuasan 86,5 Indeks 87 Indeks 87,5 Indeks 88 Indeks 88,50 Indeks Layanan Keuangan 3 Biro Hukum, Organisasi, dan Kerja Sama Rencana Aksi Pembangunan 2,40 Nilai 2,41 Nilai 2,42 Nilai 2,45 Nilai 2,46 Nilai RB General Meningkatnya Tingkat Koordinasi Implementasi 96 Nilai 96 Nilai 97 Nilai 97 Nilai 98 Nilai Pengelolaan Rencana Aksi Penyusunan RB General Peraturan Perundang- Persentase undangan, Penyederhanaa 70% 72% 73% 74% 75% Organisasi, dan Tata n Struktur laksana serta Kerja Organisasi Sama di Bidang Penanggulangan Tingkat Bencana Capaian Sistem Kerja 4 Nilai 4', 'Lampiran hal. 134', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4450, 'perban-5-2025', 255, 'lampiran', 'Lampiran hal. 134', NULL, 134, 'Nilai 4 Nilai 4 Nilai 4 Nilai untuk Penyederhanaa n Birokrasi Indeks Kualitas 65 Indeks 70 Indeks 75 Indeks 80 Indeks 80 Indeks Kebijakan Indeks Reformasi 70 Indeks 75 Indeks 80 Indeks 85 Indeks 85 Indeks Hukum Indeks Pelayanan 4,20 Indeks 4,21 Indeks 4,22 Indeks 4,23 Indeks 4,24 Indeks Publik Survei penilaian 80 Nilai 80,1 Nilai 80,2 Nilai 80,3 Nilai 80,4 Nilai integritas Survei Kepuasan 89 Nilai 90 Nilai 91 Nilai 92 Nilai 93 Nilai Masyarakat 4 Biro Sumber Daya Manusia dan Umum Skor ANRI 91,11 Nilai 91,12 Nilai 91,13 Nilai 91,14 Nilai 91,15 Nilai Indeks Sistem Merit 285,5 Nilai 286 Nilai 286,5 Nilai 287 Nilai 288 Nilai Meningkatnya Kualitas Indeks Pelaksanaan Urusan Pengelolaan 3,45 Nilai 3,46 Nilai 3,47 Nilai 3,48 Nilai 3,49 Nilai Sumber Daya Aset Manusia dan Indeks Tata Administrasi Umum Kelola 70 Nilai 70,5 Nilai 71 Nilai 71,5 Nilai 72 Nilai Pengadaan Indeks BerAKHLAK 62 Nilai 62,5 Nilai 62,8 Nilai 63 Nilai 63,3 Nilai 5 Pusat Pendidikan dan Pelatihan Persentase sumber daya Meningkatnya manusia Sumber Daya daerah rawan Manusia bencana yang Penanggulangan difasilitasi 64% 78% 80% 87% 96% Bencana pendidikan berdasarkan dan pelatihan kompetensi teknis penanggulanga n bencana Sasaran Program 7: Meningkatnya Pengawasan yang Akuntabel dan Transparan Inspektorat Utama 1 Inspektorat I Meningkatnya Persentase Penyusunan dan tindaklanjut Pelaksanaan hasil Kebijakan pemeriksaan 75% 75% 75% 75% 75% Pengawasan Intern BPK RI dan Melaksanakan dilingkup Pengawasan Wewenang Fungsional');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4450, 'Nilai 4 Nilai 4 Nilai 4 Nilai untuk Penyederhanaa n Birokrasi Indeks Kualitas 65 Indeks 70 Indeks 75 Indeks 80 Indeks 80 Indeks Kebijakan Indeks Reformasi 70 Indeks 75 Indeks 80 Indeks 85 Indeks 85 Indeks Hukum Indeks Pelayanan 4,20 Indeks 4,21 Indeks 4,22 Indeks 4,23 Indeks 4,24 Indeks Publik Survei penilaian 80 Nilai 80,1 Nilai 80,2 Nilai 80,3 Nilai 80,4 Nilai integritas Survei Kepuasan 89 Nilai 90 Nilai 91 Nilai 92 Nilai 93 Nilai Masyarakat 4 Biro Sumber Daya Manusia dan Umum Skor ANRI 91,11 Nilai 91,12 Nilai 91,13 Nilai 91,14 Nilai 91,15 Nilai Indeks Sistem Merit 285,5 Nilai 286 Nilai 286,5 Nilai 287 Nilai 288 Nilai Meningkatnya Kualitas Indeks Pelaksanaan Urusan Pengelolaan 3,45 Nilai 3,46 Nilai 3,47 Nilai 3,48 Nilai 3,49 Nilai Sumber Daya Aset Manusia dan Indeks Tata Administrasi Umum Kelola 70 Nilai 70,5 Nilai 71 Nilai 71,5 Nilai 72 Nilai Pengadaan Indeks BerAKHLAK 62 Nilai 62,5 Nilai 62,8 Nilai 63 Nilai 63,3 Nilai 5 Pusat Pendidikan dan Pelatihan Persentase sumber daya Meningkatnya manusia Sumber Daya daerah rawan Manusia bencana yang Penanggulangan difasilitasi 64% 78% 80% 87% 96% Bencana pendidikan berdasarkan dan pelatihan kompetensi teknis penanggulanga n bencana Sasaran Program 7: Meningkatnya Pengawasan yang Akuntabel dan Transparan Inspektorat Utama 1 Inspektorat I Meningkatnya Persentase Penyusunan dan tindaklanjut Pelaksanaan hasil Kebijakan pemeriksaan 75% 75% 75% 75% 75% Pengawasan Intern BPK RI dan Melaksanakan dilingkup Pengawasan Wewenang Fungsional', 'Lampiran hal. 134', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4451, 'perban-5-2025', 256, 'lampiran', 'Lampiran hal. 134', NULL, 134, 'Lingkup Inspektorat I Wewenang Persentase Inspektorat I Tindak Lanjut Hasil Pengawasan 46% 52% 58% 64% 70% APIP dilingkup wewenang Inspektorat I Skor Penilaian Mandiri 3,05 Nilai 3,1 Nilai 3,15 Nilai 3,2 Nilai 3,25 Nilai Kapabilitas APIP 2 Inspektorat II Skor Penilaian Mandiri 3,05 Nilai 3,1 Nilai 3,15 Nilai 3,2 Nilai 3,25 Nilai Kapabilitas APIP Persentase Meningkatnya Tindak Lanjut Penyusunan dan Hasil Pelaksanaan Pengawasan 46% 52% 58% 64% 70% Kebijakan APIP di Pengawasan Intern Lingkup dan Melaksanakan Wewenang Pengawasan Inspektorat II Fungsional di Persentase Lingkup Wewenang Tindak Lanjut Inspektorat II Hasil Pemeriksaan 75% 75% 75% 75% 75% BPK RI di Lingkup Wewenang Inspektorat II 3 Inspektorat III Presentase Tindak Lanjut Hasil Meningkatnya Pengawasan 46% 52% 58% 64% 70% Penyusunan dan APIP di lingkup Pelaksanaan wewenang Kebijakan Inspektorat III Pengawasan Intern serta Pelaksanaan Skor Penilaian Tugas Pengawasan Mandiri dengan Tujuan 3,05 Nilai 3,1 Nilai 3,15 Nilai 3,2 Nilai 3,25 Nilai Kapabilitas Tertentu di APIP Lingkungan Badan Nasional Penanggulangan Presentase Bencana Pelaksanaan Tindak Lanjut 100% 100% 100% 100% 100% Pengaduan Masyarakat Adapun dari sasaran kegiatan yang telah dituangkan dalam tabel di atas, terdapat beberapa masukan kegiatan yang ditujukan untuk meningkatkan kapasitas SDM BNPB serta BPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4451, 'Lingkup Inspektorat I Wewenang Persentase Inspektorat I Tindak Lanjut Hasil Pengawasan 46% 52% 58% 64% 70% APIP dilingkup wewenang Inspektorat I Skor Penilaian Mandiri 3,05 Nilai 3,1 Nilai 3,15 Nilai 3,2 Nilai 3,25 Nilai Kapabilitas APIP 2 Inspektorat II Skor Penilaian Mandiri 3,05 Nilai 3,1 Nilai 3,15 Nilai 3,2 Nilai 3,25 Nilai Kapabilitas APIP Persentase Meningkatnya Tindak Lanjut Penyusunan dan Hasil Pelaksanaan Pengawasan 46% 52% 58% 64% 70% Kebijakan APIP di Pengawasan Intern Lingkup dan Melaksanakan Wewenang Pengawasan Inspektorat II Fungsional di Persentase Lingkup Wewenang Tindak Lanjut Inspektorat II Hasil Pemeriksaan 75% 75% 75% 75% 75% BPK RI di Lingkup Wewenang Inspektorat II 3 Inspektorat III Presentase Tindak Lanjut Hasil Meningkatnya Pengawasan 46% 52% 58% 64% 70% Penyusunan dan APIP di lingkup Pelaksanaan wewenang Kebijakan Inspektorat III Pengawasan Intern serta Pelaksanaan Skor Penilaian Tugas Pengawasan Mandiri dengan Tujuan 3,05 Nilai 3,1 Nilai 3,15 Nilai 3,2 Nilai 3,25 Nilai Kapabilitas Tertentu di APIP Lingkungan Badan Nasional Penanggulangan Presentase Bencana Pelaksanaan Tindak Lanjut 100% 100% 100% 100% 100% Pengaduan Masyarakat Adapun dari sasaran kegiatan yang telah dituangkan dalam tabel di atas, terdapat beberapa masukan kegiatan yang ditujukan untuk meningkatkan kapasitas SDM BNPB serta BPBD.', 'Lampiran hal. 134', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4452, 'perban-5-2025', 257, 'lampiran', 'Lampiran hal. 134', NULL, 134, 'Dapat direncanakan untuk pengadaan kegiatan pelatihan khusus dalam merencanakan program pelatihan manajemen kebencanaan yang dilaksanakan terpadu dengan dipimpin oleh BNPB untuk BPBD. Selain itu, dapat pula menyusun Norma, Standar, Prosedur, dan Kriteria (NSPK) mengenai sebuah sistem sertifikasi atau akreditasi mengenai kebencanaan yang dapat diberikan pada lembaga swasta atau perguruan tinggi. Untuk menguatkan kepemimpinan dan peran strategis Indonesia dalam forum kebencanaan di tingkat global, BNPB perlu memperkuat diplomasi pada bidang kebencanaan serta meningkatkan kerja sama bilateral maupun multilateral dengan negara dan organisasi Internasional.
BNPB juga perlu mewujudkan sasaran strategis RPJMN 2025-2029 yang berfokus pada kebencanaan, yaitu resiliensi terhadap bencana dan perubahan iklim dengan indikator penurunan proporsi kerugian ekonomi langsung akibat bencana relatif terhadap PDB dan Penurunan Nilai Indeks Risiko Bencana Indonesia. Salah satu langkah yang dapat dilakukan untuk mencapai sasaran tersebut adalah melalui pembuatan skema rencana bisnis yang bertujuan untuk meringankan kerugian ekonomi yang didapatkan kabupaten/kota akibat bencana dan menurunkan indeks risiko bencana di wilayah Indonesia.
4.2. Kerangka Pendanaan Untuk mengoptimalkan dan mengkoordinasikan penggunaan berbagai sumber dana dalam pembangunan, diperlukan sebuah kerangka pendanaan yang mencakup asal-usul dana, tujuan penggunaan, dan prinsip-prinsip pelaksanaan pembangunan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4452, 'Dapat direncanakan untuk pengadaan kegiatan pelatihan khusus dalam merencanakan program pelatihan manajemen kebencanaan yang dilaksanakan terpadu dengan dipimpin oleh BNPB untuk BPBD. Selain itu, dapat pula menyusun Norma, Standar, Prosedur, dan Kriteria (NSPK) mengenai sebuah sistem sertifikasi atau akreditasi mengenai kebencanaan yang dapat diberikan pada lembaga swasta atau perguruan tinggi. Untuk menguatkan kepemimpinan dan peran strategis Indonesia dalam forum kebencanaan di tingkat global, BNPB perlu memperkuat diplomasi pada bidang kebencanaan serta meningkatkan kerja sama bilateral maupun multilateral dengan negara dan organisasi Internasional.
BNPB juga perlu mewujudkan sasaran strategis RPJMN 2025-2029 yang berfokus pada kebencanaan, yaitu resiliensi terhadap bencana dan perubahan iklim dengan indikator penurunan proporsi kerugian ekonomi langsung akibat bencana relatif terhadap PDB dan Penurunan Nilai Indeks Risiko Bencana Indonesia. Salah satu langkah yang dapat dilakukan untuk mencapai sasaran tersebut adalah melalui pembuatan skema rencana bisnis yang bertujuan untuk meringankan kerugian ekonomi yang didapatkan kabupaten/kota akibat bencana dan menurunkan indeks risiko bencana di wilayah Indonesia.
4.2. Kerangka Pendanaan Untuk mengoptimalkan dan mengkoordinasikan penggunaan berbagai sumber dana dalam pembangunan, diperlukan sebuah kerangka pendanaan yang mencakup asal-usul dana, tujuan penggunaan, dan prinsip-prinsip pelaksanaan pembangunan.', 'Lampiran hal. 134', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4453, 'perban-5-2025', 258, 'lampiran', 'Lampiran hal. 141', NULL, 141, 'Sumber utama pendanaan untuk pelaksanaan program dan kegiatan BNPB untuk tahun 2025-2029 berasal dari APBN.
Selain alokasi rutin untuk melaksanakan program dan kegiatan BNPB, penting juga untuk memastikan tersedianya dana siap pakai yang dapat segera digunakan dalam penanganan darurat bencana, baik dalam tahap siaga, tanggap darurat, maupun pemulihan. Dana hibah rehabilitasi dan rekonstruksi digunakan khususnya untuk memulihkan daerah yang terdampak bencana, dengan fokus pada pemenuhan kebutuhan dasar, infrastruktur layanan, pemulihan sosial ekonomi, dan pengelolaan sumber daya alam, sehingga dapat mengurangi risiko bencana di masa mendatang.
Selain itu, pemenuhan kebutuhan pendanaan yang bersumber dari APBN baik yang bersumber dari Rupiah Murni, Pendapatan Nasional Bukan Pajak (PNBP), Pinjaman dan/atau Hibah dan Luar Negeri (PHLN), serta sumber/skema lainnya seperti Kerjasama Pemerintah dan Badan Usaha (KPBU), Pooling Fund Bencana, dan Corporate Social Responsibility (CSR). Potensi pendanaan eksternal berupa pinjaman dan hibah luar negeri cukup signifikan dalam program penanggulangan bencana.
Pendanaan luar negeri memainkan peran penting dalam program penanggulangan bencana, antara lain digunakan untuk membiayai program pengurangan risiko bencana seperti pembangunan infrastruktur tahan bencana, sistem peringatan dini, pelatihan, penguatan kelembagaan, edukasi masyarakat, dan digitalisasi sistem penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4453, 'Sumber utama pendanaan untuk pelaksanaan program dan kegiatan BNPB untuk tahun 2025-2029 berasal dari APBN.
Selain alokasi rutin untuk melaksanakan program dan kegiatan BNPB, penting juga untuk memastikan tersedianya dana siap pakai yang dapat segera digunakan dalam penanganan darurat bencana, baik dalam tahap siaga, tanggap darurat, maupun pemulihan. Dana hibah rehabilitasi dan rekonstruksi digunakan khususnya untuk memulihkan daerah yang terdampak bencana, dengan fokus pada pemenuhan kebutuhan dasar, infrastruktur layanan, pemulihan sosial ekonomi, dan pengelolaan sumber daya alam, sehingga dapat mengurangi risiko bencana di masa mendatang.
Selain itu, pemenuhan kebutuhan pendanaan yang bersumber dari APBN baik yang bersumber dari Rupiah Murni, Pendapatan Nasional Bukan Pajak (PNBP), Pinjaman dan/atau Hibah dan Luar Negeri (PHLN), serta sumber/skema lainnya seperti Kerjasama Pemerintah dan Badan Usaha (KPBU), Pooling Fund Bencana, dan Corporate Social Responsibility (CSR). Potensi pendanaan eksternal berupa pinjaman dan hibah luar negeri cukup signifikan dalam program penanggulangan bencana.
Pendanaan luar negeri memainkan peran penting dalam program penanggulangan bencana, antara lain digunakan untuk membiayai program pengurangan risiko bencana seperti pembangunan infrastruktur tahan bencana, sistem peringatan dini, pelatihan, penguatan kelembagaan, edukasi masyarakat, dan digitalisasi sistem penanggulangan bencana.', 'Lampiran hal. 141', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4454, 'perban-5-2025', 259, 'lampiran', 'Lampiran hal. 141', NULL, 141, 'Tabel 4.8. Potensi Pinjaman Luar Negeri di BNPB 2025-2029 Pemberi Nilai 202 202 202 202 No Program 2025 Pinjaman Pinjaman 6 7 8 9 Indonesia Disaster Risk USD 1 The World Bank Resilience Initiatives Project 160.000.000 (IDRIP) Pembangunan Ekosistem Aksi Pemerintah USD 2 Dini Untuk Manajemen Spanyol 45.000.000 Risiko Bencana di Indonesia Tabel 4.9. Potensi Hibah Luar Negeri di BNPB 2025-2029 No Pemberi Hibah Program Nilai HIbah 2025 2026 2027 2028 2029 Peningkatan Ketangguhan Masyarakat dalam pengurangan Risiko Caritas EUR EUR Belum 1 Bencana melalui Germany 2.512.000 1.000.000 disusun Penguatan Koordinasi Para Pemangku Kepentingan Kemitraan Indonesia Department of Australia untuk AUD Foreign Affairs AUD Belum Belum 2 Kesiapsiagaan 6.517.648 and Trade 45.000.000 disusun disusun Bencana/Program ,83 (DFAT) Australia SIAP SIAGA The Swiss Kerja Sama di Bidang Agency for CHF CHF 3 Penanggulangan Development 1.850.000 383.355 Bencana and Cooperation United Nations Pengurangan Risiko International USD USD 4 Bencana dan Children’s Fund 750.000 46.955 Manajemen Bencana (UNICEF) The Deutsche Solusi Terpadu dalam Gesellschaft für Pengelolaan Risiko EUR EUR Belum 5 Internationale dan Perlindungan 5.750.000 2.576.000 disusun Zusammenarbeit Sosial (GIZ) Dukungan Teknis World Food Mitigasi Risiko USD USD 6 Programme Bencana dan 372.750 57.750 (WFP) Perubahan Iklim Implementation of UNFPA FUNDED United Nation Workplan Relating to USD USD 7 Population Fund the 2021-2025 330.000 155.100 (UNFPA)');
