INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4455, 'perban-5-2025', 260, 'lampiran', 'Lampiran hal. 141', NULL, 141, 'UNFPA Country Programme for Republic of Indonesia Kerjasama JICA dan Japan BNPB dalam Bidang Workplan 2025-2027 sudah JPY International Pengurangan Risiko disusun, namun AWP belum 8 188.000.00 Cooperation Bencana (masih disusun, masih dalam 0 Agency (JICA) dalam proses ttd proses MoC MoC) Pendanaan luar negeri mendorong kolaborasi antara pemerintah, lembaga internasional, NGO internasional, dan sektor swasta global, sehingga meningkatkan standar dan transparansi dalam tata kelola penanggulangan bencana.
Penggunaan dana dari Pihak Eksternal sangat dibutuhkan untuk menunjang kapasitas sumber dana internal dalam penanggulangan bencana yang saat ini dirasa kurang mampu dalam mendukung seluruh misi yang telah dicanangkan. Secara rinci anggaran yang dibutuhkan oleh BNPB setiap tahunnya dapat dilihat pada tabel berikut ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4455, 'UNFPA Country Programme for Republic of Indonesia Kerjasama JICA dan Japan BNPB dalam Bidang Workplan 2025-2027 sudah JPY International Pengurangan Risiko disusun, namun AWP belum 8 188.000.00 Cooperation Bencana (masih disusun, masih dalam 0 Agency (JICA) dalam proses ttd proses MoC MoC) Pendanaan luar negeri mendorong kolaborasi antara pemerintah, lembaga internasional, NGO internasional, dan sektor swasta global, sehingga meningkatkan standar dan transparansi dalam tata kelola penanggulangan bencana.
Penggunaan dana dari Pihak Eksternal sangat dibutuhkan untuk menunjang kapasitas sumber dana internal dalam penanggulangan bencana yang saat ini dirasa kurang mampu dalam mendukung seluruh misi yang telah dicanangkan. Secara rinci anggaran yang dibutuhkan oleh BNPB setiap tahunnya dapat dilihat pada tabel berikut ini.', 'Lampiran hal. 141', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4456, 'perban-5-2025', 261, 'lampiran', 'Lampiran hal. 143', NULL, 143, 'Tabel 4.10. Kebutuhan Penganggaran Rutin BNPB pada masing-masing Sasaran Program Kebutuhan Anggaran Indikatif (Ribuan) No. Unit Terkait Sasaran Program 2025 2026 2027 2028 2029 1 Deputi Bidang Meningkatnya 15.324.410 40.026.890 39.743.358 42.536.327 45.532.326 Sistem dan Sinkronisasi Strategi Pengembangan Sistem dan Strategi Pusat Data, Penanggulangan 76.741.399 1.299.698.80 1.301.503.11 1.306.747.52 488.935.071 Informasi dan Bencana Secara 0 0 0 Komunikasi Terpadu dan Kebencanaan Inovatif 2 Deputi Bidang Meningkatnya 58.807.832 48.950.909 78.895.395 107.707.105 136.456.441 Pencegahan Kualitas Masyarakat yang Tangguh terhadap Bencana di Kawasan Berisiko Bencana 3 Deputi Bidang Meningkatnya 260.923.996 269.054.352 270.058.321 270.858.881 271.749.488 Penanganan Manajemen Darurat Penanganan Darurat Saat Kejadian Bencana Pusat 194.186.219 8.540.239 8.988.040 9.372.542 9.788.694 Pengendalian Operasi 4 Deputi Bidang Meningkatnya 20.488.000 42.279.083 43.667.676 47.477.661 50.494.274 Rehabilitasi dan kualitas layanan Rekonstruksi Pemulihan Pascabencana Sektor Permukiman Infrastruktur Sosial, Ekonomi dan Lintas Sektor 5 Deputi Bidang Meningkatnya 508.481.988 523.986.165 504.933.737 504.229.392 541.415.190 Logistik dan Ketahanan Logistik Peralatan dan Peralatan yang Berkelanjutan dalam Mendukung Penanggulangan Bencana Berdasarkan Wilayah 6 Sekretariat Meningkatnya 306.212.682 339.672.468 357.266.645 369.234.262 381.013.067 Utama Kualitas Tata Kelola Penyelenggaraan Penanggulangan');
