INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4458, 'perban-5-2025', 263, 'lampiran', 'Lampiran hal. 144', NULL, 144, 'Tabel 4.11. Kerangka Pendanaan BNPB 2025-2029 Indikator Kerangka Pendanaan (Tahun) No Sasaran Kegiatan Sasaran Kegiatan 2025 2026 2027 2028 2029 Sasaran Program 1: Meningkatnya Sinkronisasi Pengembangan Sistem dan Strategi Penanggulangan Bencana Secara Terpadu dan Inovatif Deputi Bidang Sistem dan Strategi dan Pusat Data Informasi dan Komunikasi Kebencanaan 1 Direktorat Pemetaan dan Evaluasi Risiko Bencana Persentase rekomendasi kebijakan dan dukungan teknis di Sasaran Kegiatan: lingkup Meningkatnya pemetaan dan Kualitas Pemetaan 6.324.000 22.717.075 21.167.075 22.533.775 24.006.656 evaluasi risiko dan Evaluasi bencana yang Risiko Bencana dimanfaatkan oleh K/L dan atau Pemerintah Daerah 2 Direktorat Pengembangan Strategi Penanggulangan Bencana Persentase Rekomendasi Kebijakan dan dukungan teknis di Meningkatnya Lingkup Kualitas Pengembanga Pengembangan n Strategi PB 5.306.410 8.606.830 9.003.000 9.441.940 9.941.997 Strategi yang Penanggulangan dimanfaatkan Bencana oleh Kementerian/ Lembaga dan atau Pemerintah Daerah 3 Direktorat Sistem Penanggulangan Bencana Persentase Rekomendasi Kebijakan dan dukungan teknis di Meningkatnya lingkup kualitas Sistem PB pengembangan yang 3.694.000 8.702.985 9.573.283 10.560.612 11.583.673 sistem dimanfaatkan penanggulangan oleh bencana Kementerian/ Lembaga dan atau Pemerintah Daerah 4 Pusat Data, Informasi, dan Komunikasi Kebencanaan Persentase Meningkatnya Penyampaian kualitas layanan layanan bidang data, informasi informasi dan kejadian');
