INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4461, 'perban-5-2025', 266, 'lampiran', 'Lampiran hal. 144', NULL, 144, 'Indikator Kerangka Pendanaan (Tahun) No Sasaran Kegiatan Sasaran Kegiatan 2025 2026 2027 2028 2029 Persentase kelompok masyarakat Meningkatnya terdampak Layanan bencana masif Pemulihan dan yang Peningkatan mendapatkan 10.500.000 30.059.462 31.959.746 34.148.818 36.801.063 Sosial Ekonomi, pendampingan Sumber Daya pemulihan Alam dan sosial ekonomi Lingkungan dan sumber daya alam sesuai dengan kebutuhan 3 Direktorat Pemulihan dan Peningkatan Fisik Meningkatnya Persentase Layanan Daerah yang Rehabilitasi dan melaksanakan Rekonstruksi pemulihan 3.500.000 4.864.156 5.160.515 5.459.028 5.778.996 Bidang Pemulihan fisik dengan dan Peningkatan baik sesuai Fisik standar Sasaran Program 5: Meningkatnya Ketahanan Logistik dan Peralatan yang Berkelanjutan dalam Mendukung Penanggulangan Bencana Berdasarkan Wilayah Deputi Bidang Logistik dan Peralatan 1 Direktorat Pengelolaan Logistik dan Peralatan Persentase Terfasilitasinya daerah yang di pemenuhan 456.332.339 467.397.611 445.678.309 442.216.631 476.548.750 fasilitasi logistik di Daerah logistik 2 Direktorat Optimasi Jaringan Logistik dan Peralatan Persentase Terpenuhinya logistik dan layanan distribusi peralatan yang 52.149.649 56.588.554 59.255.428 62.012.761 64.866.440 logistik dan terdistribusi peralatan ke daerah Sasaran Program 6: Meningkatnya Kualitas Tata Kelola Penyelenggaraan Penanggulangan Bencana Yang Profesional, Akuntabel dan Transparan Sekretariat Utama dan Pusat Pendidikan dan Pelatihan 1 Biro Perencanaan Meningkatnya');
