INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4462, 'perban-5-2025', 267, 'lampiran', 'Lampiran hal. 144', NULL, 144, 'Nilai Indeks Layanan Perencanaan Perencanaan, Pembangunan 62.091.910 36.725.833 39.725.833 41.725.833 46.725.833 Pemantauan dan BNPB Evaluasi 2 Biro Keuangan Indikator Kerangka Pendanaan (Tahun) No Sasaran Kegiatan Sasaran Kegiatan 2025 2026 2027 2028 2029 Meningkatnya Layanan Opini BPK Penatausahaan atas laporan 141.656.287 165.417.396 181.653.573 183.880.190 184.728.995 keuangan yang keuangan tertib, transparan, BNPB dan akuntabel 3 Biro Hukum, Organisasi, dan Kerja Sama Meningkatnya Koordinasi Pengelolaan Penyusunan Peraturan Perundang- Rencana Aksi Undangan, Pembangunan 12.090.245 28.238.245 21.290.245 21.890.245 21.890.245 Organisasi, dan RB General Tatalaksana serta Kerjasama di Bidang Penanggulangan Bencana 4 Biro Sumber Daya Manusia dan Umum Meningkatnya Kualitas Pelaksanaan Urusan Sumber Skor ANRI 90.374.240 109.290.994 114.596.994 121.737.994 127.667.994 Daya Manusia dan Administrasi Umum 5 Pusat Pendidikan dan Pelatihan Persentase sumber daya Meningkatnya manusia Sumber Daya daerah rawan Manusia bencana yang Penanggulangan difasilitasi 9.921.900 18.651.391 20.601.079 22.965.116 24.627.716 Bencana pendidikan berdasarkan dan pelatihan kompetensi teknis penanggulang an bencana Sasaran Program 7: Meningkatnya Pengawasan yang Akuntabel dan Transparan Inspektorat Utama 1 Inspektorat I Meningkatnya Penyusunan dan Pelaksanaan Persentase Kebijakan tindak lanjut Pengawasan hasil Intern dan pemeriksaan 4.000.000 5.000.000 6.000.000 7.000.000 8.000.000 Melaksanakan BPK RI');
