INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4463, 'perban-5-2025', 268, 'lampiran', 'Lampiran hal. 144', NULL, 144, 'Pengawasan dilingkup Fungsional Wewenang Lingkup Inspektorat Wewenang Inspektorat I 2 Inspektorat II Indikator Kerangka Pendanaan (Tahun) No Sasaran Kegiatan Sasaran Kegiatan 2025 2026 2027 2028 2029 Meningkatnya Penyusunan dan Pelaksanaan Kebijakan Pengawasan Skor Penilaian Intern dan Mandiri 4.000.000 5.000.000 6.000.000 7.000.000 8.000.000 Melaksanakan Kapabilitas Pengawasan APIP Fungsional di Lingkup Wewenang Inspektorat II 3 Inspektorat III Meningkatnya Penyusunan dan Pelaksanaan Kebijakan Pengawasan Intern serta Presentase Pelaksanaan Pelaksanaan Tugas Tindak Lanjut 4.000.000 5.000.000 6.000.000 7.000.000 8.000.000 Pengawasan Pengaduan dengan Tujuan Masyarakat Tertentu di Lingkungan Badan Nasional Penanggulangan Bencana BAB 5. PENUTUP Rencana Strategis (Renstra) Badan Nasional Penanggulangan Bencana Tahun 2025- 2029 merupakan dokumen perencanaan yang memuat Visi, Misi, Tujuan, Sasaran Strategis, Arah Kebijakan, Strategi, Kerangka Regulasi, Kerangka Kelembagaan, dan Kerangka Pendanaan untuk periode lima tahun 2025-2029. Penyusunan Renstra ini mengacu pada Rencana Pembangunan Jangka Menengah Nasional (RPJMN) Tahun 2025-2029.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4463, 'Pengawasan dilingkup Fungsional Wewenang Lingkup Inspektorat Wewenang Inspektorat I 2 Inspektorat II Indikator Kerangka Pendanaan (Tahun) No Sasaran Kegiatan Sasaran Kegiatan 2025 2026 2027 2028 2029 Meningkatnya Penyusunan dan Pelaksanaan Kebijakan Pengawasan Skor Penilaian Intern dan Mandiri 4.000.000 5.000.000 6.000.000 7.000.000 8.000.000 Melaksanakan Kapabilitas Pengawasan APIP Fungsional di Lingkup Wewenang Inspektorat II 3 Inspektorat III Meningkatnya Penyusunan dan Pelaksanaan Kebijakan Pengawasan Intern serta Presentase Pelaksanaan Pelaksanaan Tugas Tindak Lanjut 4.000.000 5.000.000 6.000.000 7.000.000 8.000.000 Pengawasan Pengaduan dengan Tujuan Masyarakat Tertentu di Lingkungan Badan Nasional Penanggulangan Bencana BAB 5. PENUTUP Rencana Strategis (Renstra) Badan Nasional Penanggulangan Bencana Tahun 2025- 2029 merupakan dokumen perencanaan yang memuat Visi, Misi, Tujuan, Sasaran Strategis, Arah Kebijakan, Strategi, Kerangka Regulasi, Kerangka Kelembagaan, dan Kerangka Pendanaan untuk periode lima tahun 2025-2029. Penyusunan Renstra ini mengacu pada Rencana Pembangunan Jangka Menengah Nasional (RPJMN) Tahun 2025-2029.', 'Lampiran hal. 144', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4464, 'perban-5-2025', 269, 'lampiran', 'Lampiran hal. 150', NULL, 150, 'Renstra disusun dengan mempertimbangkan dinamika faktor lingkungan internal maupun eksternal, sehingga diharapkan mampu mengantisipasi perubahan yang mungkin terjadi. Untuk mencapai tujuan yang telah ditetapkan, seluruh aparatur BNPB diharapkan memahami dan melaksanakan Renstra ini secara konsisten dan penuh dedikasi. Sejalan dengan tugas, fungsi, dan struktur organisasi yang baru, BNPB perlu meningkatkan koordinasi, baik internal maupun eksternal, dalam pelaksanaan setiap program dan kegiatan. Pendekatan ini sejalan dengan amanat Undang-Undang Nomor 24 Tahun 2007, yang menegaskan bahwa penanggulangan bencana merupakan tanggung jawab bersama.
Renstra menjadi landasan utama dalam penyusunan Rencana Kerja (Renja) dan Rencana Kerja dan Anggaran (RKA), sehingga program dan kegiatan dapat lebih terarah, efisien, dan akuntabel. Dokumen ini juga memberikan panduan yang jelas bagi BNPB dalam menghadapi dinamika tantangan penanggulangan bencana selama periode 2025-2029.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4464, 'Renstra disusun dengan mempertimbangkan dinamika faktor lingkungan internal maupun eksternal, sehingga diharapkan mampu mengantisipasi perubahan yang mungkin terjadi. Untuk mencapai tujuan yang telah ditetapkan, seluruh aparatur BNPB diharapkan memahami dan melaksanakan Renstra ini secara konsisten dan penuh dedikasi. Sejalan dengan tugas, fungsi, dan struktur organisasi yang baru, BNPB perlu meningkatkan koordinasi, baik internal maupun eksternal, dalam pelaksanaan setiap program dan kegiatan. Pendekatan ini sejalan dengan amanat Undang-Undang Nomor 24 Tahun 2007, yang menegaskan bahwa penanggulangan bencana merupakan tanggung jawab bersama.
Renstra menjadi landasan utama dalam penyusunan Rencana Kerja (Renja) dan Rencana Kerja dan Anggaran (RKA), sehingga program dan kegiatan dapat lebih terarah, efisien, dan akuntabel. Dokumen ini juga memberikan panduan yang jelas bagi BNPB dalam menghadapi dinamika tantangan penanggulangan bencana selama periode 2025-2029.', 'Lampiran hal. 150', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4465, 'perban-5-2025', 270, 'lampiran', 'Lampiran hal. 150', NULL, 150, 'Pimpinan menegaskan bahwa keberhasilan Renstra tidak ditentukan semata oleh kelengkapan dokumen, melainkan oleh efektivitas dan keterpaduan pelaksanaannya di seluruh sektor. Renstra ini harus menjadi peta jalan yang hidup, mengarahkan langkah BNPB lima tahun ke depan dengan kerja nyata yang terukur, demi keselamatan, perlindungan, dan kesejahteraan masyarakat. Setiap unit kerja wajib memastikan bahwa setiap program dan kegiatan selaras dengan arah kebijakan ini, serta dilaksanakan dengan komitmen penuh dan koordinasi yang solid lintas sektor.
Selain itu, Pimpinan menginstruksikan agar dilakukan evaluasi secara berkala terhadap pelaksanaan program dan kegiatan, guna memastikan target yang telah ditetapkan dalam Renstra dapat tercapai secara optimal. Evaluasi tersebut harus menjadi landasan untuk melakukan penyesuaian strategi, memperkuat koordinasi, dan mengoptimalkan pemanfaatan sumber daya. Dengan demikian, setiap sasaran strategis dapat direalisasikan sesuai rencana, sekaligus memperkuat kapasitas dan kesiapsiagaan BNPB dalam menghadapi berbagai potensi ancaman bencana di masa mendatang.
Kepala BNPB melaksanakan pengendalian dan evaluasi terhadap pelaksanaan Rencana Strategis (Renstra) BNPB sesuai dengan tugas dan kewenangannya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4465, 'Pimpinan menegaskan bahwa keberhasilan Renstra tidak ditentukan semata oleh kelengkapan dokumen, melainkan oleh efektivitas dan keterpaduan pelaksanaannya di seluruh sektor. Renstra ini harus menjadi peta jalan yang hidup, mengarahkan langkah BNPB lima tahun ke depan dengan kerja nyata yang terukur, demi keselamatan, perlindungan, dan kesejahteraan masyarakat. Setiap unit kerja wajib memastikan bahwa setiap program dan kegiatan selaras dengan arah kebijakan ini, serta dilaksanakan dengan komitmen penuh dan koordinasi yang solid lintas sektor.
Selain itu, Pimpinan menginstruksikan agar dilakukan evaluasi secara berkala terhadap pelaksanaan program dan kegiatan, guna memastikan target yang telah ditetapkan dalam Renstra dapat tercapai secara optimal. Evaluasi tersebut harus menjadi landasan untuk melakukan penyesuaian strategi, memperkuat koordinasi, dan mengoptimalkan pemanfaatan sumber daya. Dengan demikian, setiap sasaran strategis dapat direalisasikan sesuai rencana, sekaligus memperkuat kapasitas dan kesiapsiagaan BNPB dalam menghadapi berbagai potensi ancaman bencana di masa mendatang.
Kepala BNPB melaksanakan pengendalian dan evaluasi terhadap pelaksanaan Rencana Strategis (Renstra) BNPB sesuai dengan tugas dan kewenangannya.', 'Lampiran hal. 150', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4466, 'perban-5-2025', 271, 'lampiran', 'Lampiran hal. 150', NULL, 150, 'Pengendalian dan evaluasi ini bertujuan untuk menjamin dan menilai ketercapaian setiap sasaran, indikator kinerja, dan target yang tertuang dalam Renstra BNPB, menilai efisiensi, efektivitas, manfaat, dampak, serta keberlanjutan dari setiap program, serta menilai penerapan manajemen risiko pembangunan nasional pada BNPB.
Mekanisme evaluasi pelaksanaan Renstra BNPB dilaksanakan secara sistematis, terukur, dan berkesinambungan sesuai dengan ketentuan Peraturan Presiden Nomor 80 Tahun 2025. Proses evaluasi diawali dengan pemantauan berkala terhadap seluruh unit kerja, baik di tingkat pusat maupun daerah, melalui pengumpulan data dan informasi kinerja yang mencakup Indikator Kinerja Utama (IKU) dan Indikator Kinerja Program (IKP), yang dihimpun dari laporan triwulanan dan tahunan.
Beberapa kendala yang berpotensi dihadapi dalam pelaksanaan Renstra BNPB Tahun 2025-2029, antara lain:
1. Perubahan kebijakan program dan anggaran yang dapat memengaruhi prioritas dan alokasi sumber daya;
2. Pergantian pimpinan yang dapat mengubah arah strategis organisasi.
Kondisi tersebut berisiko mengganggu konsistensi pelaksanaan rencana, baik dari sisi penetapan target kinerja maupun jadwal pelaksanaan program. Untuk mengantisipasi, diperlukan mekanisme adaptasi yang cepat, koordinasi efektif antar-unit kerja, dan penyesuaian kebijakan internal agar pelaksanaan Renstra tetap relevan, responsif, dan adaptif terhadap dinamika perubahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4466, 'Pengendalian dan evaluasi ini bertujuan untuk menjamin dan menilai ketercapaian setiap sasaran, indikator kinerja, dan target yang tertuang dalam Renstra BNPB, menilai efisiensi, efektivitas, manfaat, dampak, serta keberlanjutan dari setiap program, serta menilai penerapan manajemen risiko pembangunan nasional pada BNPB.
Mekanisme evaluasi pelaksanaan Renstra BNPB dilaksanakan secara sistematis, terukur, dan berkesinambungan sesuai dengan ketentuan Peraturan Presiden Nomor 80 Tahun 2025. Proses evaluasi diawali dengan pemantauan berkala terhadap seluruh unit kerja, baik di tingkat pusat maupun daerah, melalui pengumpulan data dan informasi kinerja yang mencakup Indikator Kinerja Utama (IKU) dan Indikator Kinerja Program (IKP), yang dihimpun dari laporan triwulanan dan tahunan.
Beberapa kendala yang berpotensi dihadapi dalam pelaksanaan Renstra BNPB Tahun 2025-2029, antara lain:
1. Perubahan kebijakan program dan anggaran yang dapat memengaruhi prioritas dan alokasi sumber daya;
2. Pergantian pimpinan yang dapat mengubah arah strategis organisasi.
Kondisi tersebut berisiko mengganggu konsistensi pelaksanaan rencana, baik dari sisi penetapan target kinerja maupun jadwal pelaksanaan program. Untuk mengantisipasi, diperlukan mekanisme adaptasi yang cepat, koordinasi efektif antar-unit kerja, dan penyesuaian kebijakan internal agar pelaksanaan Renstra tetap relevan, responsif, dan adaptif terhadap dinamika perubahan.', 'Lampiran hal. 150', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4467, 'perban-5-2025', 272, 'lampiran', 'Lampiran hal. 151', NULL, 151, 'Dengan pendekatan ini, BNPB memastikan bahwa pelaksanaan Renstra selalu selaras dengan visi dan misi lembaga, serta berkontribusi optimal terhadap pencapaian tujuan penanggulangan bencana nasional.
Demikian Renstra BNPB Tahun 2025-2029 agar dapat menjadi acuan dan pedoman dalam melaksanakan program dan kegiatan penanggulangan bencana serta menjadi acuan dalam penyusunan Renstra unit kerja Eselon I di BNPB.
LAMPIRAN I. MATRIKS KINERJA DAN PENDANAAN Unit SASARAN STRATEGIS s.d RO KEGIATAN ALOKASI ANGGARAN (dalam ribu rupiah) Sasaran Program Pelaksana Program/ Kegiatan (Outcome)/Sasaran Kegiatan (Outcome)/Indikator 2025 2026 2027 2028 2029 2025 2026 2027 2028 2029 1.999.458.868 Sasaran Strategis Resiliensi Terhadap Bencana 1.372.674.102 2.499.433.021 2.608.786.399 2.711.054.593 BNPB Persentase Penurunan Nilai
- 1.2% 1.2% 1.2% 1.2% 1.2% Indeks Risiko Bencana Nasional Indikator :
Persentase Daerah yang memiliki');
