INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4534, 'perban-5-2025', 339, 'lampiran', 'Lampiran hal. 196', NULL, 196, 'Sebagai acuan dalam Dit. Pemetaan Peraturan BNPB tentang Penyusunan Bappenas, BPS, 3 penghitungan indeks Evaluasi Risiko 2027 Indeks Risiko Bencana Kemendagri risiko bencana nasional Bencana Peraturan BNPB tentang Pedoman dan Tata Cara Pemantauan, Pengendalian, Sebagai panduan untuk Dit.
Kemendagri, 4 dan Evaluasi Pelaksanaan Rencana mengukur ketercapaian Pengembangan 2025 Bappenas, Kemenkeu Induk Penanggulangan Bencana Tahun RIPB dari waktu ke waktu. Strategi PB 2020 - 2044 Kemendagri, Kemham, Sebagai dasar hukum KemenPUPR, KLHK, Peraturan BNPB tentang Rencana Dit. yang menetapkan KKP, Kementan, 5 Nasional Penanggulangan Bencana Pengembangan 2024-2025 Rencana Nasional Kemenkes, Tahun 2025-2029 Strategi PB (RENAS) PB 2025 - 2029. Kemensos, Kominfo, BMKG, BIG, BRIN, PVMBG Pembaharuan Revisi Peraturan Kepala BNPB Nomor 4 Kemendagri, berdasarkan Dit. tahun 2008 tentang Pedoman ATR/BPN, Bappenas, 6 perkembangan keilmuan, Pengembangan 2025 Penyusunan Rencana Penanggulangan Kemenkeu, BPS, perubahan hukum terkait, Strategi PB Bencana BRIN dan pembelajaran terkini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4534, 'Sebagai acuan dalam Dit. Pemetaan Peraturan BNPB tentang Penyusunan Bappenas, BPS, 3 penghitungan indeks Evaluasi Risiko 2027 Indeks Risiko Bencana Kemendagri risiko bencana nasional Bencana Peraturan BNPB tentang Pedoman dan Tata Cara Pemantauan, Pengendalian, Sebagai panduan untuk Dit.
Kemendagri, 4 dan Evaluasi Pelaksanaan Rencana mengukur ketercapaian Pengembangan 2025 Bappenas, Kemenkeu Induk Penanggulangan Bencana Tahun RIPB dari waktu ke waktu. Strategi PB 2020 - 2044 Kemendagri, Kemham, Sebagai dasar hukum KemenPUPR, KLHK, Peraturan BNPB tentang Rencana Dit. yang menetapkan KKP, Kementan, 5 Nasional Penanggulangan Bencana Pengembangan 2024-2025 Rencana Nasional Kemenkes, Tahun 2025-2029 Strategi PB (RENAS) PB 2025 - 2029. Kemensos, Kominfo, BMKG, BIG, BRIN, PVMBG Pembaharuan Revisi Peraturan Kepala BNPB Nomor 4 Kemendagri, berdasarkan Dit. tahun 2008 tentang Pedoman ATR/BPN, Bappenas, 6 perkembangan keilmuan, Pengembangan 2025 Penyusunan Rencana Penanggulangan Kemenkeu, BPS, perubahan hukum terkait, Strategi PB Bencana BRIN dan pembelajaran terkini.', 'Lampiran hal. 196', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4535, 'perban-5-2025', 340, 'lampiran', 'Lampiran hal. 196', NULL, 196, 'Kemenko PMK, Bappenas, Kemenkeu, Kemendagri, Sebagai dasar hukum Peraturan BNPB tentang Rencana Dit. Kemenkumham, yang menetapkan 7 Nasional (Renas) Penanggulangan Pengembangan KemenPU, Kemen 2029-2030 Rencana Nasional Renas Bencana Tahun 2030-2034 Strategi PB PKP, KLH,Kemenhut, PB 2030-2034 KKP, Kementan, Kemenkes, Kemensos, Komdigi, BMKG, BIG, BRIN Kemenko Kesra, Pembaharuan Revisi Peraturan Kepala BNPB Nomor 4 Kemendikbud Ristek, berdasarkan Tahun 2014 tentang Penerapan kemenag, Kemkes, 8 perkembangan keilmuan, Dit Mitigasi 2025 Sekolah/Madrasah Aman Bencana Kemsos, Kemkeu, perubahan hukum terkait, (SMAB) KPP-PA, KLHK, BRIN, dan pembelajaran terkini.
Bappenas, BPS Pembaharuan Revisi Peraturan Kepala BNPB Nomor 7 berdasarkan Kemenhub, BBWS, 9 Tahun 2015 tentang Rambu dan Papan perkembangan keilmuan, Dit Mitigasi 2029 ESDM Informasi Bencana perubahan hukum terkait, dan pembelajaran terkini.
Sebagai acuan implementasi MHEWS, turunan PERPRES Dit. Peringatan 10 Peraturan BNPB tentang MHEWS BMKG 2027 MHEWS, serta acuan dini koordinasi aktor upstream dan downstream.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4535, 'Kemenko PMK, Bappenas, Kemenkeu, Kemendagri, Sebagai dasar hukum Peraturan BNPB tentang Rencana Dit. Kemenkumham, yang menetapkan 7 Nasional (Renas) Penanggulangan Pengembangan KemenPU, Kemen 2029-2030 Rencana Nasional Renas Bencana Tahun 2030-2034 Strategi PB PKP, KLH,Kemenhut, PB 2030-2034 KKP, Kementan, Kemenkes, Kemensos, Komdigi, BMKG, BIG, BRIN Kemenko Kesra, Pembaharuan Revisi Peraturan Kepala BNPB Nomor 4 Kemendikbud Ristek, berdasarkan Tahun 2014 tentang Penerapan kemenag, Kemkes, 8 perkembangan keilmuan, Dit Mitigasi 2025 Sekolah/Madrasah Aman Bencana Kemsos, Kemkeu, perubahan hukum terkait, (SMAB) KPP-PA, KLHK, BRIN, dan pembelajaran terkini.
Bappenas, BPS Pembaharuan Revisi Peraturan Kepala BNPB Nomor 7 berdasarkan Kemenhub, BBWS, 9 Tahun 2015 tentang Rambu dan Papan perkembangan keilmuan, Dit Mitigasi 2029 ESDM Informasi Bencana perubahan hukum terkait, dan pembelajaran terkini.
Sebagai acuan implementasi MHEWS, turunan PERPRES Dit. Peringatan 10 Peraturan BNPB tentang MHEWS BMKG 2027 MHEWS, serta acuan dini koordinasi aktor upstream dan downstream.', 'Lampiran hal. 196', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4536, 'perban-5-2025', 341, 'lampiran', 'Lampiran hal. 196', NULL, 196, 'Kemenko PMK, Revisi Peraturan BNPB Nomor 2 Tahun Pembaharuan Dit. Kemendagri, 11 2023 tentang Penyusunan Rencana berdasarkan 2027 Kesiapsiagaan KemenPUPR, Kontingensi Bencana perkembangan keilmuan, Kominfo, KKP, KLHK, Urgensi Pembentukan Unit Arah Kerangka Regulasi dan/atau Berdasarkan Evaluasi Target NO. Penanggung Unit Terkait/Institusi Kebutuhan Regulasi Regulasi Eksisting, Kajian Penyelesaian Jawab Dan Penelitian Peraturan Pada Lingkup BNPB perubahan hukum terkait, KKP, ESDM, dan pembelajaran terkini. Kemenhub, Kemenkeu, Kemendesa, KPPPA, ATR/BPN, BMKG, BRIN, Basarnas, PMI, BPS Sebagai acuan dan dasar hukum untuk memperkuat koordinasi Peraturan BNPB tentang Forum Dit.
12 dan kolaborasi dalam Kemendagri, 2027 Pengurangan Risiko Bencana Kesiapsiagaan pengurangan risiko bencana melalui Forum PRB Pembaharuan Revisi Peraturan Kepala BNPB Nomor berdasarkan Kemendagri, 11 Tahun 2014 tentang Peran Serta Dit.
13 perkembangan keilmuan, Bappenas, 2027 Masyarakat Dalam Penyelenggaraan Kesiapsiagaan perubahan hukum terkait, Kemendesa PDTT Penanggulangan Bencana dan pembelajaran terkini.
Revisi Peraturan Kepala BNPB Nomor Pembaharuan 12 Tahun 2014 tentang Peran Serta berdasarkan Kemendagri, Dit.
14 Lembaga Usaha Dalam perkembangan keilmuan, Bappenas, OJK, 2027 Kesiapsiagaan Penyelenggaraan Penanggulangan perubahan hukum terkait, Kemen KUKM Bencana dan pembelajaran terkini.');
