INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4537, 'perban-5-2025', 342, 'lampiran', 'Lampiran hal. 197', NULL, 197, 'Pembaharuan Revisi Peraturan Kepala BNPB Nomor berdasarkan 13 Tahun 2014 tentang Dit. KemenPPPA, 15 perkembangan keilmuan, 2027 Pengarusutamaan Gender di Bidang Kesiapsiagaan Kemensos perubahan hukum terkait, Penanggulangan Bencana dan pembelajaran terkini.
Revisi Peraturan Kepala BNPB Nomor Pembaharuan 14 Tahun 2014 tentang Penanganan, berdasarkan Dit. KemenPPPA, 16 Perlindungan dan Partisipasi perkembangan keilmuan, 2027 Kesiapsiagaan Kemensos Penyandang Disabilitas dalam perubahan hukum terkait, Penanggulangan Bencana dan pembelajaran terkini.
Kemendagri, Pembaharuan Kemensos, Revisi Peraturan Kepala BNPB Nomor 1 berdasarkan Dit. Kemendesa, 17 Tahun 2012 tentang Pedoman Umum perkembangan keilmuan, 2028 Kesiapsiagaan Kemenkes, Kominfo, Desa/Kelurahan Tangguh Bencana perubahan hukum terkait, Kemham, Perguruan dan pembelajaran terkini.
Tinggi, NGO Pembaharuan Kemenko Kesra, Revisi Peraturan Kepala BNPB Nomor berdasarkan Kemendagri, Dit.
18 17 Tahun 2011 tentang Pedoman perkembangan keilmuan, Kemensos, 2029 Kesiapsiagaan Relawan Penanggulangan Bencana perubahan hukum terkait, Kemenkes, Basarnas, dan pembelajaran terkini. PMI Pembaharuan Revisi Pedoman Perban Penetapan berdasarkan Dit. Dukungan Dit SPB dan Dit.
