INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4538, 'perban-5-2025', 343, 'lampiran', 'Lampiran hal. 197', NULL, 197, 'Kemendagri, Pembaharuan Kemhan, Kemlu, Dit. Fasilitas Revisi Peraturan Kepala BNPB Nomor 9 berdasarkan Kemenkumham, Penanganan 20 Tahun 2008 tentang Prosedur Tim perkembangan keilmuan, Kemensos, 2025 Korban dan Reaksi Cepat perubahan hukum terkait, Kemenhub, Kominfo, Pengungsi dan pembelajaran terkini. KemenPUPR, BPS, Basarnas, PMI Pembaharuan Kemendagri, Dit. Fasilitas Revisi Peraturan BNPB Nomor 3 Tahun berdasarkan Kemensos, Penanganan 21 2018 tentang Penanganan Pengungsi perkembangan keilmuan, Kemenkes, 2027 Korban dan pada Keadaan Darurat perubahan hukum terkait, Kemenhub, Kominfo, Pengungsi dan pembelajaran terkini. BNPP, PMI, Basarnas KLHK, ESDM, Pembaharuan Dit. Optimasi KemenPUPR, Pemda, Revisi Peraturan BNPB Nomor 6 Tahun berdasarkan Jaringan Kemenkeu, 22 2022 tentang Klaster Logistik perkembangan keilmuan, 2025 Logistik dan Kemensos, Penanggulangan Bencana perubahan hukum terkait, Peralatan Kemenkes, ATR/BPN, dan pembelajaran terkini.
BRIN Urgensi Pembentukan Unit Arah Kerangka Regulasi dan/atau Berdasarkan Evaluasi Target NO. Penanggung Unit Terkait/Institusi Kebutuhan Regulasi Regulasi Eksisting, Kajian Penyelesaian Jawab Dan Penelitian Peraturan Pada Lingkup BNPB Pembaharuan Dit. PANRB, KemenPUPR, Revisi Peraturan Kepala BNPB Nomor 5 berdasarkan Perencanaan Bappenas, 23 Tahun 2017 tentang Pedoman Rencana perkembangan keilmuan, 2025 Rehabilitasi dan Kemenkeu, Kemenko, Rehab Rekon perubahan hukum terkait, Rekonstruksi Bappenas, LKPP dan pembelajaran terkini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4538, 'Kemendagri, Pembaharuan Kemhan, Kemlu, Dit. Fasilitas Revisi Peraturan Kepala BNPB Nomor 9 berdasarkan Kemenkumham, Penanganan 20 Tahun 2008 tentang Prosedur Tim perkembangan keilmuan, Kemensos, 2025 Korban dan Reaksi Cepat perubahan hukum terkait, Kemenhub, Kominfo, Pengungsi dan pembelajaran terkini. KemenPUPR, BPS, Basarnas, PMI Pembaharuan Kemendagri, Dit. Fasilitas Revisi Peraturan BNPB Nomor 3 Tahun berdasarkan Kemensos, Penanganan 21 2018 tentang Penanganan Pengungsi perkembangan keilmuan, Kemenkes, 2027 Korban dan pada Keadaan Darurat perubahan hukum terkait, Kemenhub, Kominfo, Pengungsi dan pembelajaran terkini. BNPP, PMI, Basarnas KLHK, ESDM, Pembaharuan Dit. Optimasi KemenPUPR, Pemda, Revisi Peraturan BNPB Nomor 6 Tahun berdasarkan Jaringan Kemenkeu, 22 2022 tentang Klaster Logistik perkembangan keilmuan, 2025 Logistik dan Kemensos, Penanggulangan Bencana perubahan hukum terkait, Peralatan Kemenkes, ATR/BPN, dan pembelajaran terkini.
BRIN Urgensi Pembentukan Unit Arah Kerangka Regulasi dan/atau Berdasarkan Evaluasi Target NO. Penanggung Unit Terkait/Institusi Kebutuhan Regulasi Regulasi Eksisting, Kajian Penyelesaian Jawab Dan Penelitian Peraturan Pada Lingkup BNPB Pembaharuan Dit. PANRB, KemenPUPR, Revisi Peraturan Kepala BNPB Nomor 5 berdasarkan Perencanaan Bappenas, 23 Tahun 2017 tentang Pedoman Rencana perkembangan keilmuan, 2025 Rehabilitasi dan Kemenkeu, Kemenko, Rehab Rekon perubahan hukum terkait, Rekonstruksi Bappenas, LKPP dan pembelajaran terkini.', 'Lampiran hal. 197', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4539, 'perban-5-2025', 344, 'lampiran', 'Lampiran hal. 198', NULL, 198, 'KemenPUPR, Pembaharuan Kemendagri, Revisi Peraturan BNPB Nomor 6 Tahun Dit. berdasarkan Kemenkeu, Kemenko, 2017 tentang Penyelenggaraan Perencanaan 24 perkembangan keilmuan, Kemendesa, 2026 Rehabilitasi dan Rekonstruksi Rehabilitasi dan perubahan hukum terkait, Bappenas, LKPP, Pascabencana Rekonstruksi dan pembelajaran terkini. BPS, BMKG, PMI, Basarnas, TNI, POLRI Pembaharuan Revisi Peraturan Kepala BNPB Nomor 3 Dit. PANRB, KemenPUPR, berdasarkan Tahun 2013 Tentang Petunjuk Teknis Perencanaan Bappenas, 25 perkembangan keilmuan, 2026 Pelaksanaan Anggaran Kegiatan Rehabilitasi dan Kemenkeu, Kemenko, perubahan hukum terkait, Rehabilitasi dan Rekonstruksi Rekonstruksi Bappenas, LKPP dan pembelajaran terkini.
Pembaharuan Dit. PANRB, KemenPUPR, Revisi Peraturan Kepala BNPB Nomor 6 berdasarkan Perencanaan Bappenas, 26 Tahun 2013 tentang Juknis Rehab perkembangan keilmuan, 2027 Rehabilitasi dan Kemenkeu, Kemenko, Rekon Sektor Permukiman perubahan hukum terkait, Rekonstruksi Bappenas, LKPP dan pembelajaran terkini.
Pembaharuan Reviu Juklak Nomor 5 Tahun 2024 Direktorat Kemenkeu, berdasarkan tentang Bantuan Stimulan Pemulihan dan Bappenas, 27 perkembangan keilmuan, 2025 Perbaikan/Pembangunan Kembali Peningkatan KemenPUPR, LKPP, perubahan hukum terkait, Rumah Rusak Akibat bencana Fisik Pemda dan pembelajaran terkini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4539, 'KemenPUPR, Pembaharuan Kemendagri, Revisi Peraturan BNPB Nomor 6 Tahun Dit. berdasarkan Kemenkeu, Kemenko, 2017 tentang Penyelenggaraan Perencanaan 24 perkembangan keilmuan, Kemendesa, 2026 Rehabilitasi dan Rekonstruksi Rehabilitasi dan perubahan hukum terkait, Bappenas, LKPP, Pascabencana Rekonstruksi dan pembelajaran terkini. BPS, BMKG, PMI, Basarnas, TNI, POLRI Pembaharuan Revisi Peraturan Kepala BNPB Nomor 3 Dit. PANRB, KemenPUPR, berdasarkan Tahun 2013 Tentang Petunjuk Teknis Perencanaan Bappenas, 25 perkembangan keilmuan, 2026 Pelaksanaan Anggaran Kegiatan Rehabilitasi dan Kemenkeu, Kemenko, perubahan hukum terkait, Rehabilitasi dan Rekonstruksi Rekonstruksi Bappenas, LKPP dan pembelajaran terkini.
Pembaharuan Dit. PANRB, KemenPUPR, Revisi Peraturan Kepala BNPB Nomor 6 berdasarkan Perencanaan Bappenas, 26 Tahun 2013 tentang Juknis Rehab perkembangan keilmuan, 2027 Rehabilitasi dan Kemenkeu, Kemenko, Rekon Sektor Permukiman perubahan hukum terkait, Rekonstruksi Bappenas, LKPP dan pembelajaran terkini.
Pembaharuan Reviu Juklak Nomor 5 Tahun 2024 Direktorat Kemenkeu, berdasarkan tentang Bantuan Stimulan Pemulihan dan Bappenas, 27 perkembangan keilmuan, 2025 Perbaikan/Pembangunan Kembali Peningkatan KemenPUPR, LKPP, perubahan hukum terkait, Rumah Rusak Akibat bencana Fisik Pemda dan pembelajaran terkini.', 'Lampiran hal. 198', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4540, 'perban-5-2025', 345, 'lampiran', 'Lampiran hal. 198', NULL, 198, 'Sebagai acuan dan dasar Direktorat Kemenkeu, Pedoman penilaian pemulihan pada hukum dalam mengukur Pemulihan dan Bappenas, 28 lokasi pasca bencana yang mendapat pemulihan diwilayah 2026 Peningkatan KemenPUPR, LKPP, bantuan pascabencana yang Fisik Pemda mendapat bantuan Pembaharuan Reviu Juklak Mekanisme pelaksanaan, Direktorat Kemenkeu, berdasarkan pelaporan, pemantauan dan evaluasi Pemulihan dan Bappenas, 29 perkembangan keilmuan, 2027 kegiatan konstruksi Hibah RR Peningkatan KemenPUPR, LKPP, perubahan hukum terkait, Pascabencana Nomor 9 Tahun 2024 Fisik Pemda dan pembelajaran terkini.
Reviu Juklak Nomor 2 Tahun 2019 Pembaharuan Direktorat Kemenkeu, tentang Pemanfaatan Hibah dari berdasarkan Pemulihan dan Bappenas, 30 Pemerintah Pusat Kepada pemerintah perkembangan keilmuan, 2028 Peningkatan KemenPUPR, LKPP, Daerah untuk RR Perumahan perubahan hukum terkait, Fisik Pemda Pascabencana dan pembelajaran terkini.
Sebagai acuan dan dasar hukum monitoring dan Direktorat Kemenkeu, Penyusunan Juklak terkait monitoring evaluasi berdasarkan Pemulihan dan Bappenas, 31 dan evaluasi R3P Sektor Infrastruktur 2029 perkembangan keilmuan, Peningkatan KemenPUPR, LKPP, dan Perumahan perubahan hukum terkait, Fisik Pemda dan pembelajaran terkini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4540, 'Sebagai acuan dan dasar Direktorat Kemenkeu, Pedoman penilaian pemulihan pada hukum dalam mengukur Pemulihan dan Bappenas, 28 lokasi pasca bencana yang mendapat pemulihan diwilayah 2026 Peningkatan KemenPUPR, LKPP, bantuan pascabencana yang Fisik Pemda mendapat bantuan Pembaharuan Reviu Juklak Mekanisme pelaksanaan, Direktorat Kemenkeu, berdasarkan pelaporan, pemantauan dan evaluasi Pemulihan dan Bappenas, 29 perkembangan keilmuan, 2027 kegiatan konstruksi Hibah RR Peningkatan KemenPUPR, LKPP, perubahan hukum terkait, Pascabencana Nomor 9 Tahun 2024 Fisik Pemda dan pembelajaran terkini.
Reviu Juklak Nomor 2 Tahun 2019 Pembaharuan Direktorat Kemenkeu, tentang Pemanfaatan Hibah dari berdasarkan Pemulihan dan Bappenas, 30 Pemerintah Pusat Kepada pemerintah perkembangan keilmuan, 2028 Peningkatan KemenPUPR, LKPP, Daerah untuk RR Perumahan perubahan hukum terkait, Fisik Pemda Pascabencana dan pembelajaran terkini.
Sebagai acuan dan dasar hukum monitoring dan Direktorat Kemenkeu, Penyusunan Juklak terkait monitoring evaluasi berdasarkan Pemulihan dan Bappenas, 31 dan evaluasi R3P Sektor Infrastruktur 2029 perkembangan keilmuan, Peningkatan KemenPUPR, LKPP, dan Perumahan perubahan hukum terkait, Fisik Pemda dan pembelajaran terkini.', 'Lampiran hal. 198', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2025 tentang Rencana Strategis Badan Nasional Penanggulangan Bencana Tahun 2025-2029');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4541, 'perban-5-2025', 346, 'lampiran', 'Lampiran hal. 198', NULL, 198, 'Pembaharuan KemenPUPR, Revisi Peraturan BNPB Nomor 4 Tahun berdasarkan Dit. Pengelolaan Kominfo, Kemenkeu, 32 2018 tentang Sistem Manajemen perkembangan keilmuan, Logistik dan 2025 BPS, BMKG, BRIN, Logistik dan Peralatan perubahan hukum terkait, Peralatan Kemenhub dan pembelajaran terkini.
