INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4553, 'perban-6-2017', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk Penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana pada wilayah terdampak untuk mempercepat pemulihan kehidupan dan penghidupan masyarakat serta perbaikan prasarana dan sarana umum secara terencana, terkoordinasi dan terpadu;
