2017, No.1903 -14-', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2017 tentang Penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4570, 'perban-6-2017', 18, 'pasal', 'Pasal 15', 'BAB V KETENTUAN PENUTUP', 14, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
