INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4572, 'perban-6-2018', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4572, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4573, 'perban-6-2018', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk memperlancar dan mempermudah pengelolaan bantuan internasional pada keadaan darurat bencana yang dapat memberikan manfaat sebesar-besarnya bagi masyarakat yang terdampak bencana, telah ditetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2010 tentang Pedoman Peran Serta Lembaga Internasional dan Lembaga Asing Non-Pemerintah Pada Saat Tanggap Darurat;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2010 tentang Pedoman Peran Serta Lembaga Internasional dan Lembaga Asing Non-Pemerintah Pada Saat Tanggap Darurat sudah tidak sesuai dengan kebutuhan, sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan www.peraturan.go.id 2018, No.1645 -2- Peraturan Badan Nasional Penanggulangan Bencana tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4573, 'a. bahwa untuk memperlancar dan mempermudah pengelolaan bantuan internasional pada keadaan darurat bencana yang dapat memberikan manfaat sebesar-besarnya bagi masyarakat yang terdampak bencana, telah ditetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2010 tentang Pedoman Peran Serta Lembaga Internasional dan Lembaga Asing Non-Pemerintah Pada Saat Tanggap Darurat;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2010 tentang Pedoman Peran Serta Lembaga Internasional dan Lembaga Asing Non-Pemerintah Pada Saat Tanggap Darurat sudah tidak sesuai dengan kebutuhan, sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan www.peraturan.go.id 2018, No.1645 -2- Peraturan Badan Nasional Penanggulangan Bencana tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4574, 'perban-6-2018', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 24 Tahun 2000 tentang Perjanjian Internasional ( Lembaran Negara Republik Indonesia Tahun 2000 Nomor 185, Tambahan Lembaran Negara Republik Indonesia Nomor 4012);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Republik Indonesia Nomor 4830);
5. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
6. Peraturan Menteri Keuangan Nomor 69 Tahun 2012 tentang Pembebasan Bea Masuk dan atau Cukai atas Import Barang Kiriman Hadiah/Hibah untuk Kepentingan Penanggulangan Bencana Alam (Berita Negara Republik Indonesia Tahun 2012 Nomor 491);
7. Peraturan Kepala BNPB Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana (Berita Negara Republik Indonesia Tahun 2016 Nomor 1777); www.peraturan.go.id 2018, No.1645');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4574, '1. Undang-Undang Nomor 24 Tahun 2000 tentang Perjanjian Internasional ( Lembaran Negara Republik Indonesia Tahun 2000 Nomor 185, Tambahan Lembaran Negara Republik Indonesia Nomor 4012);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Republik Indonesia Nomor 4830);
5. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
6. Peraturan Menteri Keuangan Nomor 69 Tahun 2012 tentang Pembebasan Bea Masuk dan atau Cukai atas Import Barang Kiriman Hadiah/Hibah untuk Kepentingan Penanggulangan Bencana Alam (Berita Negara Republik Indonesia Tahun 2012 Nomor 491);
7. Peraturan Kepala BNPB Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana (Berita Negara Republik Indonesia Tahun 2016 Nomor 1777); www.peraturan.go.id 2018, No.1645', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4575, 'perban-6-2018', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENERIMAAN BANTUAN INTERNASIONAL DALAM KEADAAN DARURAT BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4575, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENERIMAAN BANTUAN INTERNASIONAL DALAM KEADAAN DARURAT BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4576, 'perban-6-2018', 4, 'pasal', 'Pasal 1', 'BAB II RUANG LINGKUP', 3, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Keadaan Darurat Bencana adalah suatu keadaan yang mengancam dan mengganggu kehidupan dan penghidupan sekelompok orang/masyarakat yang memerlukan tindakan penanganan segera dan memadai.
3. Hibah Pemerintah, yang selanjutnya disebut Hibah adalah setiap penerimaan negara dalam bentuk devisa, devisa yang dirupiahkan, rupiah, barang, jasa dan/atau surat berharga yang diperoleh dari pemberi hibah yang tidak perlu dibayar kembali, yang berasal dari dalam negeri atau luar negeri.
4. Bantuan Internasional adalah bantuan berasal dari luar negeri yang diberikan oleh negara sahabat, lembaga internasional, lembaga asing nonpemerintah, lembaga usaha asing, dan perseorangan pada keadaan darurat bencana berdasarkan pernyataan resmi Pemerintah Indonesia.
5. Pengelolaan Bantuan Internasional adalah serangkaian upaya penanganan bantuan internasional yang meliputi penerimaan, pemanfaatan, perpanjangan waktu serta pengakhiran pengelolaan bantuan selama masa keadaan www.peraturan.go.id 2018, No.1645 -4- darurat bencana.
6. Pos Komando Penanganan Darurat Bencana yang selanjutnya disingkat Posko PDB adalah institusi yang berfungsi sebagai pusat komando operasi penanganan darurat bencana yang merupakan posko utama di dalam Sistem Komando Penanganan Darurat Bencana, untuk mengoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan penanganan darurat bencana.
7. Pos Pendukung Penanganan Darurat Bencana yang selanjutnya disebut Pos Pendukung PDB adalah institusi yang berfungsi membantu kelancaran akses masuk, keluar, dan mobilisasi/distribusi bantuan penanganan darurat bencana dari luar wilayah terdampak.
8. Pos Pendamping Penanganan Darurat Bencana yang selanjutnya disebut Pos Pendamping PDB adalah institusi yang berperan mengoordinasikan mobilisasi bantuan penanganan darurat bencana meliputi pos pendamping nasional penanganan darurat bencana, pos pendamping penanganan darurat bencana provinsi, dan pos pendamping penanganan darurat bencana wilayah.
9. Kepabeanan adalah segala sesuatu yang berhubungan dengan pengawasan atas lalu lintas barang yang masuk atau keluar daerah pabean serta pemungutan bea masuk dan bea keluar.
10. Keimigrasian adalah hal ihwal lalu lintas orang yang masuk atau keluar wilayah Indonesia serta pengawasannya dalam rangka menjaga tegaknya kedaulatan negara.
11. Karantina adalah tempat pengasingan dan/atau tindakan sebagai upaya pencegahan masuk dan tersebarnya hama dan penyakit atau organisme pengganggu dari luar negeri dan dari suatu area ke area lain di dalam negeri atau keluarnya dari dalam wilayah negara Republik Indonesia;
12. Tempat transit adalah tempat singgah sementara bantuan internasional di suatu bandar udara internasional atau pelabuhan laut ataupun tempat lainnya yang telah ditetapkan oleh otoritas yang www.peraturan.go.id 2018, No.1645 berwenang di dalam wilayah Negara Kesatuan Republik Indonesia.
13. Pemerintah Pusat, yang selanjutnya disebut Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
14. Badan Nasional Penanggulangan Bencana yang selanjutnya dtraisingkat BNPB adalah Lembaga Pemerintah Non-Kementerian setingkat Menteri sesuai dengan ketentuan peraturan perundang-undangan.');
