INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4578, 'perban-6-2018', 6, 'pasal', 'Pasal 3', 'BAB III PENERIMAAN BANTUAN INTERNASIONAL; Bagian Kedua Persyaratan', 6, 'Jenis bantuan internasional terdiri atas:
