INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4580, 'perban-6-2018', 8, 'pasal', 'Pasal 5', 'BAB III PENERIMAAN BANTUAN INTERNASIONAL; Bagian Ketiga Prosedur Penerimaan', 9, '(1) Penerimaan bantuan internasional berdasarkan atas adanya pernyataan resmi Pemerintah.
(2) Pernyataan resmi Pemerintah sebagaimana dimaksud pada ayat (1), disampaikan setelah melalui rapat koordinasi antar kementerian/lembaga.
(3) Hasil koordinasi sebagaimana dimaksud pada ayat (2) ditindaklanjuti oleh BNPB dengan menyusun laporan situasi meliputi:
a. laporan singkat tentang bencana;
b. periode keadaan darurat bencana;
c. informasi kebutuhan jenis bantuan; dan
d. informasi mengenai pihak pemberi bantuan.
(4) Formulir laporan situasi sebagaimana dimaksud pada ayat (3) tercantum dalam Lampiran I yang merupakan www.peraturan.go.id 2018, No.1645 -10- bagian tidak terpisahkan dari Peraturan Badan ini.
(5) BNPB mengoordinasikan penyebarluasan informasi penerimaan bantuan internasional sebagaimana dimaksud pada ayat (1) melalui Kementerian Luar Negeri.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4580, '(1) Penerimaan bantuan internasional berdasarkan atas adanya pernyataan resmi Pemerintah.
(2) Pernyataan resmi Pemerintah sebagaimana dimaksud pada ayat (1), disampaikan setelah melalui rapat koordinasi antar kementerian/lembaga.
(3) Hasil koordinasi sebagaimana dimaksud pada ayat (2) ditindaklanjuti oleh BNPB dengan menyusun laporan situasi meliputi:
a. laporan singkat tentang bencana;
b. periode keadaan darurat bencana;
c. informasi kebutuhan jenis bantuan; dan
d. informasi mengenai pihak pemberi bantuan.
(4) Formulir laporan situasi sebagaimana dimaksud pada ayat (3) tercantum dalam Lampiran I yang merupakan www.peraturan.go.id 2018, No.1645 -10- bagian tidak terpisahkan dari Peraturan Badan ini.
(5) BNPB mengoordinasikan penyebarluasan informasi penerimaan bantuan internasional sebagaimana dimaksud pada ayat (1) melalui Kementerian Luar Negeri.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4581, 'perban-6-2018', 9, 'pasal', 'Pasal 6', 'BAB III PENERIMAAN BANTUAN INTERNASIONAL; Bagian Ketiga Prosedur Penerimaan', 10, '(1) Setiap tawaran bantuan internasional ditindaklanjuti oleh BNPB bersama kementerian/lembaga terkait.
(2) Setiap tawaran bantuan internasional sebagaimana dimaksud pada ayat (1) oleh pemberi disertai dengan penyerahan daftar bantuan yang akan diberikan.
(3) Daftar bantuan sebagaimana dimaksud pada ayat (2) dituangkan dalam formulir seperti yang tercantum pada Lampiran II yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(4) Pos Pendamping Nasional PDB atau Posko Nasional PDB melakukan pengkajian kesesuaian atas tawaran bantuan internasional sebagaimana dimaksud pada ayat (1) dengan daftar identifikasi kebutuhan sesuai dengan kewenangannya.
(5) Persetujuan terhadap hasil pengkajian atas tawaran bantuan internasional sebagaimana dimaksud pada ayat
(4) diinformasikan secara tertulis oleh BNPB kepada calon pemberi bantuan melalui Kementerian Luar Negeri dengan tembusan kepada Pos Pendamping Nasional PDB atau Posko Nasional PDB.
(6) Kementerian Luar Negeri melalui Kantor Perwakilan Diplomatik Republik Indonesia di negara asal pemberi bantuan melakukan verifikasi terhadap sumber pemberi bantuan, personil dan/atau barang bantuan yang akan diberikan.
(7) Hasil verifikasi sebagaimana dimaksud pada ayat (6) disampaikan kepada ke BNPB berikut dengan izin kedatangan bantuan internasional.
(8) BNPB mengirimkan informasi tertulis atas kedatangan bantuan internasional sebagaimana dimaksud pada ayat
(7) kepada Pos Pendamping Nasional PDB atau Posko www.peraturan.go.id 2018, No.1645 Nasional PDB.
(9) Pos Pendamping Nasional PDB atau Posko Nasional PDB memerintahkan Pos Pendukung PDB untuk memfasilitasi kedatangan bantuan internasional sebagaimana dimaksud pada ayat (8).
(10) Fasilitasi penerimaan bantuan internasional sebagaimana dimaksud pada ayat (9) diawali dengan pemeriksaan ijin masuk, termasuk karantina terhadap alat angkut, barang dan orang sebelum melewati proses di Pos Pendukung PDB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4581, '(1) Setiap tawaran bantuan internasional ditindaklanjuti oleh BNPB bersama kementerian/lembaga terkait.
(2) Setiap tawaran bantuan internasional sebagaimana dimaksud pada ayat (1) oleh pemberi disertai dengan penyerahan daftar bantuan yang akan diberikan.
(3) Daftar bantuan sebagaimana dimaksud pada ayat (2) dituangkan dalam formulir seperti yang tercantum pada Lampiran II yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(4) Pos Pendamping Nasional PDB atau Posko Nasional PDB melakukan pengkajian kesesuaian atas tawaran bantuan internasional sebagaimana dimaksud pada ayat (1) dengan daftar identifikasi kebutuhan sesuai dengan kewenangannya.
(5) Persetujuan terhadap hasil pengkajian atas tawaran bantuan internasional sebagaimana dimaksud pada ayat
(4) diinformasikan secara tertulis oleh BNPB kepada calon pemberi bantuan melalui Kementerian Luar Negeri dengan tembusan kepada Pos Pendamping Nasional PDB atau Posko Nasional PDB.
(6) Kementerian Luar Negeri melalui Kantor Perwakilan Diplomatik Republik Indonesia di negara asal pemberi bantuan melakukan verifikasi terhadap sumber pemberi bantuan, personil dan/atau barang bantuan yang akan diberikan.
(7) Hasil verifikasi sebagaimana dimaksud pada ayat (6) disampaikan kepada ke BNPB berikut dengan izin kedatangan bantuan internasional.
(8) BNPB mengirimkan informasi tertulis atas kedatangan bantuan internasional sebagaimana dimaksud pada ayat
(7) kepada Pos Pendamping Nasional PDB atau Posko www.peraturan.go.id 2018, No.1645 Nasional PDB.
(9) Pos Pendamping Nasional PDB atau Posko Nasional PDB memerintahkan Pos Pendukung PDB untuk memfasilitasi kedatangan bantuan internasional sebagaimana dimaksud pada ayat (8).
(10) Fasilitasi penerimaan bantuan internasional sebagaimana dimaksud pada ayat (9) diawali dengan pemeriksaan ijin masuk, termasuk karantina terhadap alat angkut, barang dan orang sebelum melewati proses di Pos Pendukung PDB.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4582, 'perban-6-2018', 10, 'pasal', 'Pasal 7', 'BAB III PENERIMAAN BANTUAN INTERNASIONAL; Bagian Ketiga Prosedur Penerimaan', 11, 'Proses penerimaan bantuan internasional sebagaimana dimaksud pada Pasal 5 dan Pasal 6 tercantum dalam Lampiran III yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
Paragraf Kesatu Penerimaan Bantuan Berupa Uang');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4582, 'Proses penerimaan bantuan internasional sebagaimana dimaksud pada Pasal 5 dan Pasal 6 tercantum dalam Lampiran III yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
Paragraf Kesatu Penerimaan Bantuan Berupa Uang', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4583, 'perban-6-2018', 11, 'pasal', 'Pasal 8', 'BAB III PENERIMAAN BANTUAN INTERNASIONAL; Bagian Ketiga Prosedur Penerimaan', 11, 'Prosedur Penerimaan Bantuan Uang sebagaimana dimaksud dalam Pasal 3 huruf a dilakukan melalui tata cara berikut:
a. pemerintah melalui BNPB menerima bantuan uang dalam bentuk uang tunai atau transfer antar rekening dari pemberi bantuan internasional dalam bentuk hibah;
b. hibah yang diterima harus mengacu pada prinsip-prinsip penerimaan hibah, yaitu transparansi, akuntabilitas, efisien dan efektif, kehati-hatian, tidak disertai ikatan politik dan tidak memiliki muatan yang mengganggu stabilitas keamanan negara;
c. bantuan uang yang diterima dapat pula disalurkan sesuai dengan ketentuan peraturan perundang-undangan mengenai Pengelolaan hibah di Indonesia; dan
d. penerimaan bantuan uang sebagaimana dimaksud pada huruf a, huruf b dan huruf c diisi sesuai format yang tercantum dalam Lampiran IV yang merupakan bagian www.peraturan.go.id 2018, No.1645 -12- tidak terpisahkan dari Peraturan Badan ini.
Paragraf Kedua Penerimaan Bantuan Logistik dan Peralatan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4583, 'Prosedur Penerimaan Bantuan Uang sebagaimana dimaksud dalam Pasal 3 huruf a dilakukan melalui tata cara berikut:
a. pemerintah melalui BNPB menerima bantuan uang dalam bentuk uang tunai atau transfer antar rekening dari pemberi bantuan internasional dalam bentuk hibah;
b. hibah yang diterima harus mengacu pada prinsip-prinsip penerimaan hibah, yaitu transparansi, akuntabilitas, efisien dan efektif, kehati-hatian, tidak disertai ikatan politik dan tidak memiliki muatan yang mengganggu stabilitas keamanan negara;
c. bantuan uang yang diterima dapat pula disalurkan sesuai dengan ketentuan peraturan perundang-undangan mengenai Pengelolaan hibah di Indonesia; dan
d. penerimaan bantuan uang sebagaimana dimaksud pada huruf a, huruf b dan huruf c diisi sesuai format yang tercantum dalam Lampiran IV yang merupakan bagian www.peraturan.go.id 2018, No.1645 -12- tidak terpisahkan dari Peraturan Badan ini.
Paragraf Kedua Penerimaan Bantuan Logistik dan Peralatan', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4584, 'perban-6-2018', 12, 'pasal', 'Pasal 9', 'BAB III PENERIMAAN BANTUAN INTERNASIONAL; Bagian Ketiga Prosedur Penerimaan', 12, 'Prosedur Penerimaan Bantuan Logistik dan Peralatan sebagaimana dimaksud dalam Pasal 3 huruf b dan huruf c dilakukan melalui tatacara berikut:
a. penerimaan dan pemeriksaan logistik ataupun peralatan bantuan internasional yang didatangkan dari luar negeri dilakukan di Pos Pendukung PDB sebelum didaftarkan dan/atau diserahkan ke Pos Pendamping Nasional PDB atau Posko Nasional PDB;
b. penerimaan dan pemeriksaan bantuan logistik ataupun peralatan bantuan internasional yang didatangkan dari atau sudah berada di dalam negeri, dilakukan di Pos Pendamping Nasional PDB atau Posko Nasional PDB;
c. dalam hal logistik dan peralatan masih dalam proses transportasi ke Indonesia dari negara asal dan diperkirakan akan tiba sesudah status keadaan darurat bencana berakhir, Pemerintah dapat menerima apabila pemberi bantuan internasional dapat membuktikan secara tertulis bahwa pengiriman dilakukan pada status keadaan darurat bencana atau bantuan tersebut memiliki manfaat untuk penanggulangan bencana lebih lanjut; dan
d. penerimaan logistik dan peralatan sebagaimana dimaksud pada huruf c dilakukan setelah mendapatkan rekomendasi tertulis dari BNPB.
Paragraf Ketiga Penerimaan Bantuan Personil');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4584, 'Prosedur Penerimaan Bantuan Logistik dan Peralatan sebagaimana dimaksud dalam Pasal 3 huruf b dan huruf c dilakukan melalui tatacara berikut:
a. penerimaan dan pemeriksaan logistik ataupun peralatan bantuan internasional yang didatangkan dari luar negeri dilakukan di Pos Pendukung PDB sebelum didaftarkan dan/atau diserahkan ke Pos Pendamping Nasional PDB atau Posko Nasional PDB;
b. penerimaan dan pemeriksaan bantuan logistik ataupun peralatan bantuan internasional yang didatangkan dari atau sudah berada di dalam negeri, dilakukan di Pos Pendamping Nasional PDB atau Posko Nasional PDB;
c. dalam hal logistik dan peralatan masih dalam proses transportasi ke Indonesia dari negara asal dan diperkirakan akan tiba sesudah status keadaan darurat bencana berakhir, Pemerintah dapat menerima apabila pemberi bantuan internasional dapat membuktikan secara tertulis bahwa pengiriman dilakukan pada status keadaan darurat bencana atau bantuan tersebut memiliki manfaat untuk penanggulangan bencana lebih lanjut; dan
d. penerimaan logistik dan peralatan sebagaimana dimaksud pada huruf c dilakukan setelah mendapatkan rekomendasi tertulis dari BNPB.
Paragraf Ketiga Penerimaan Bantuan Personil', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4585, 'perban-6-2018', 13, 'pasal', 'Pasal 10', 'BAB III PENERIMAAN BANTUAN INTERNASIONAL; Bagian Ketiga Prosedur Penerimaan', 12, 'Prosedur Penerimaan Bantuan Personil sebagaimana dimaksud dalam Pasal 3 huruf d dilakukan melalui tata cara www.peraturan.go.id 2018, No.1645 berikut:
a. pendaftaran personil dilakukan di Pos Pendamping Nasional PDB atau Posko Nasional PDB;
b. pendaftaran personil yang telah berdomisili dan bekerja di Indonesia dibuktikan dengan identitas diri yang berlaku, dilakukan di Pos Pendamping Nasional PDB atau Posko Nasional PDB;
c. Pos Pendamping Nasional PDB atau Posko Nasional PDB menerbitkan kartu identitas untuk setiap personil yang telah terdaftar;
d. kartu identitas wajib digunakan setiap personil selama bertugas di Indonesia dan harus ditunjukkan apabila sewaktu-waktu dilakukan pemeriksaan oleh pihak berwenang; dan
e. pendaftaran dan Kartu Identitas sebagaimana dimaksud pada huruf a, huruf b, huruf c, dan huruf d diisi sesuai format yang tercantum dalam Lampiran V yang merupakan bagian tidak terpisahkan dari peraturan ini.
Paragraf Keempat Penerimaan Bantuan Satuan Satwa');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4585, 'Prosedur Penerimaan Bantuan Personil sebagaimana dimaksud dalam Pasal 3 huruf d dilakukan melalui tata cara www.peraturan.go.id 2018, No.1645 berikut:
a. pendaftaran personil dilakukan di Pos Pendamping Nasional PDB atau Posko Nasional PDB;
b. pendaftaran personil yang telah berdomisili dan bekerja di Indonesia dibuktikan dengan identitas diri yang berlaku, dilakukan di Pos Pendamping Nasional PDB atau Posko Nasional PDB;
c. Pos Pendamping Nasional PDB atau Posko Nasional PDB menerbitkan kartu identitas untuk setiap personil yang telah terdaftar;
d. kartu identitas wajib digunakan setiap personil selama bertugas di Indonesia dan harus ditunjukkan apabila sewaktu-waktu dilakukan pemeriksaan oleh pihak berwenang; dan
e. pendaftaran dan Kartu Identitas sebagaimana dimaksud pada huruf a, huruf b, huruf c, dan huruf d diisi sesuai format yang tercantum dalam Lampiran V yang merupakan bagian tidak terpisahkan dari peraturan ini.
Paragraf Keempat Penerimaan Bantuan Satuan Satwa', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4586, 'perban-6-2018', 14, 'pasal', 'Pasal 11', 'BAB IV KEMUDAHAN AKSES', 13, 'Prosedur penerimaan bantuan satuan satwa sebagaimana dimaksud dalam Pasal 3 huruf e dilakukan melalui tatacara berikut:
a. penerimaan dan pemeriksaan satuan satwa dilakukan melalui prosedur karantina pada status keadaan darurat bencana oleh instansi yang berwenang;
b. penerimaan bantuan satuan satwa yang didatangkan dari dalam negeri dilakukan di Pos Pendamping Nasional PDB atau Posko Nasional PDB; dan
c. petugas pendamping satuan satwa wajib membawa Kartu Identitas selama bertugas di Indonesia dan harus menunjukkan apabila sewaktu-waktu dilakukan pemeriksaan oleh pihak berwenang. www.peraturan.go.id 2018, No.1645 -14-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4586, 'Prosedur penerimaan bantuan satuan satwa sebagaimana dimaksud dalam Pasal 3 huruf e dilakukan melalui tatacara berikut:
a. penerimaan dan pemeriksaan satuan satwa dilakukan melalui prosedur karantina pada status keadaan darurat bencana oleh instansi yang berwenang;
b. penerimaan bantuan satuan satwa yang didatangkan dari dalam negeri dilakukan di Pos Pendamping Nasional PDB atau Posko Nasional PDB; dan
c. petugas pendamping satuan satwa wajib membawa Kartu Identitas selama bertugas di Indonesia dan harus menunjukkan apabila sewaktu-waktu dilakukan pemeriksaan oleh pihak berwenang. www.peraturan.go.id 2018, No.1645 -14-', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4587, 'perban-6-2018', 15, 'pasal', 'Pasal 12', 'BAB V PEMANFAATAN BANTUAN INTERNASIONAL', 14, '(1) Pemerintah melalui BNPB dan/atau kementerian/ lembaga terkait memberikan kemudahan akses terhadap bantuan internasional.
(2) Kemudahan akses sebagaimana dimaksud pada ayat (1) berupa pemberian fasilitas yang diberikan pada setiap tahapan pengelolaan bantuan internasional.
(3) Pemberian fasilitas sebagaimana dimaksud pada ayat (2) berupa:
a. pembebasan bea masuk dan/atau cukai;
b. keimigrasian;
c. karantina;
d. keamanan dan keselamatan;
e. moneter dan fiskal;
f. perikatan perdata; dan
g. fasilitas kemudahan lainnya sesuai dengan ketentuan peraturan perundang-undangan.
(4) Kemudahan akses sebagaimana dimaksud pada ayat (1) dilakukan secara terpadu dalam Sistem Komando Penanganan Darurat Bencana.
(5) Kecuali ditentukan lain, kemudahan akses sebagaimana yang di maksud pada ayat (1) dapat diberikan sesuai dengan ketentuan peraturan perundang-undangan oleh kementerian/lembaga terkait setelah mendapat rekomendasi dari BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4587, '(1) Pemerintah melalui BNPB dan/atau kementerian/ lembaga terkait memberikan kemudahan akses terhadap bantuan internasional.
(2) Kemudahan akses sebagaimana dimaksud pada ayat (1) berupa pemberian fasilitas yang diberikan pada setiap tahapan pengelolaan bantuan internasional.
(3) Pemberian fasilitas sebagaimana dimaksud pada ayat (2) berupa:
a. pembebasan bea masuk dan/atau cukai;
b. keimigrasian;
c. karantina;
d. keamanan dan keselamatan;
e. moneter dan fiskal;
f. perikatan perdata; dan
g. fasilitas kemudahan lainnya sesuai dengan ketentuan peraturan perundang-undangan.
(4) Kemudahan akses sebagaimana dimaksud pada ayat (1) dilakukan secara terpadu dalam Sistem Komando Penanganan Darurat Bencana.
(5) Kecuali ditentukan lain, kemudahan akses sebagaimana yang di maksud pada ayat (1) dapat diberikan sesuai dengan ketentuan peraturan perundang-undangan oleh kementerian/lembaga terkait setelah mendapat rekomendasi dari BNPB.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4588, 'perban-6-2018', 16, 'pasal', 'Pasal 13', 'BAB V PEMANFAATAN BANTUAN INTERNASIONAL', 14, '(1) Pemanfaatan bantuan internasional dikelola dan diintegrasikan melalui Sistem Komando Penanganan Darurat Bencana. www.peraturan.go.id 2018, No.1645
(2) Pemanfaatan bantuan internasional sebagaimana dimaksud pada ayat (1) dimulai dari penerimaan bantuan oleh Pos Pendamping Nasional PDB atau Posko Nasional PDB yang dilengkapi dengan surat penerimaan dan berita acara serah terima.
(3) Surat Berita Acara Serah Terima Bantuan sebagaimana dimaksud pada ayat (2) diisi sesuai format yang tercantum dalam Lampiran VI yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4588, '(1) Pemanfaatan bantuan internasional dikelola dan diintegrasikan melalui Sistem Komando Penanganan Darurat Bencana. www.peraturan.go.id 2018, No.1645
(2) Pemanfaatan bantuan internasional sebagaimana dimaksud pada ayat (1) dimulai dari penerimaan bantuan oleh Pos Pendamping Nasional PDB atau Posko Nasional PDB yang dilengkapi dengan surat penerimaan dan berita acara serah terima.
(3) Surat Berita Acara Serah Terima Bantuan sebagaimana dimaksud pada ayat (2) diisi sesuai format yang tercantum dalam Lampiran VI yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4589, 'perban-6-2018', 17, 'pasal', 'Pasal 14', 'BAB VI KEWENANGAN DAN PENGORGANISASIAN; Bagian Kesatu Kewenangan', 15, '(1) Bantuan internasional dalam keadaan darurat bencana digunakan dalam serangkaian kegiatan yang dilakukan dengan segera untuk membantu penanganan darurat bencana, mencakup kegiatan:
a. pengendalian ancaman/penyebab bencana;
b. penyelamatan dan evakuasi korban dan harta benda;
c. pemenuhan kebutuhan dasar bagi korban bencana;
d. pemulihan dengan segera prasarana dan sarana vital; dan
e. kegiatan lain yang ditentukan oleh Pos Pendamping Nasional PDB dan Posko Nasional PDB.
(2) Pada masa transisi darurat bencana ke pemulihan, selain kegiatan sebagaimana dimaksud pada ayat (1), bantuan internasional dapat digunakan untuk melanjutkan kegiatan pada masa tanggap darurat serta kegiatan pemulihan dini kondisi sosial ekonomi masyarakat. www.peraturan.go.id 2018, No.1645 -16-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4589, '(1) Bantuan internasional dalam keadaan darurat bencana digunakan dalam serangkaian kegiatan yang dilakukan dengan segera untuk membantu penanganan darurat bencana, mencakup kegiatan:
a. pengendalian ancaman/penyebab bencana;
b. penyelamatan dan evakuasi korban dan harta benda;
c. pemenuhan kebutuhan dasar bagi korban bencana;
d. pemulihan dengan segera prasarana dan sarana vital; dan
e. kegiatan lain yang ditentukan oleh Pos Pendamping Nasional PDB dan Posko Nasional PDB.
(2) Pada masa transisi darurat bencana ke pemulihan, selain kegiatan sebagaimana dimaksud pada ayat (1), bantuan internasional dapat digunakan untuk melanjutkan kegiatan pada masa tanggap darurat serta kegiatan pemulihan dini kondisi sosial ekonomi masyarakat. www.peraturan.go.id 2018, No.1645 -16-', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4590, 'perban-6-2018', 18, 'pasal', 'Pasal 15', 'BAB VI KEWENANGAN DAN PENGORGANISASIAN; Bagian Kedua Pengorganisasian', 16, '(1) BNPB berwenang mengoordinasikan bantuan internasional melalui pengorganisasian dan pengelolaan bantuan internasional bersama kementerian/lembaga terkait di Pos Pendamping Nasional PDB atau Posko Nasional PDB
(2) Dalam serangkaian prosedur pengelolaan bantuan internasional sebagaimana dimaksud pada ayat (1), baik ketika bantuan tersebut belum tiba ataupun telah tiba di wilayah Indonesia, BNPB dan kementerian/lembaga terkait berwenang:
a. menolak tawaran bantuan apabila tidak sesuai kebutuhan;
b. memerintahkan pemberi bantuan internasional untuk melakukan reekspor apabila bantuan yang dibawa dalam keadaan rusak, kadaluarsa atau membahayakan manusia dan lingkungan serta sudah tidak dibutuhkan lagi.
(3) Pemerintah melalui BNPB dan kementerian/lembaga, selain berwenang sebagaimana dimaksud pada ayat (2), juga berwenang:
a. mendorong pemberi bantuan internasional untuk menghibahkan kepada Pemerintah atau pihak ketiga atas sisa bantuan yang masih bermanfaat dengan persetujuan Pemerintah;
b. melakukan pemeriksaan sewaktu-waktu terhadap kondisi bantuan internasional;
c. melakukan pemantauan, evaluasi, dan meminta laporan pelaksanaan bantuan internasional; dan
d. menjatuhkan sanksi bagi pemberi bantuan internasional yang melanggar ketentuan peraturan www.peraturan.go.id 2018, No.1645 perundang-undangan di Indonesia.
(4) BNPB menggunakan dan mempertanggungjawabkan pengelolaan bantuan internasional sebagaimana dimaksud pada Pasal (1) sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4590, '(1) BNPB berwenang mengoordinasikan bantuan internasional melalui pengorganisasian dan pengelolaan bantuan internasional bersama kementerian/lembaga terkait di Pos Pendamping Nasional PDB atau Posko Nasional PDB
(2) Dalam serangkaian prosedur pengelolaan bantuan internasional sebagaimana dimaksud pada ayat (1), baik ketika bantuan tersebut belum tiba ataupun telah tiba di wilayah Indonesia, BNPB dan kementerian/lembaga terkait berwenang:
a. menolak tawaran bantuan apabila tidak sesuai kebutuhan;
b. memerintahkan pemberi bantuan internasional untuk melakukan reekspor apabila bantuan yang dibawa dalam keadaan rusak, kadaluarsa atau membahayakan manusia dan lingkungan serta sudah tidak dibutuhkan lagi.
(3) Pemerintah melalui BNPB dan kementerian/lembaga, selain berwenang sebagaimana dimaksud pada ayat (2), juga berwenang:
a. mendorong pemberi bantuan internasional untuk menghibahkan kepada Pemerintah atau pihak ketiga atas sisa bantuan yang masih bermanfaat dengan persetujuan Pemerintah;
b. melakukan pemeriksaan sewaktu-waktu terhadap kondisi bantuan internasional;
c. melakukan pemantauan, evaluasi, dan meminta laporan pelaksanaan bantuan internasional; dan
d. menjatuhkan sanksi bagi pemberi bantuan internasional yang melanggar ketentuan peraturan www.peraturan.go.id 2018, No.1645 perundang-undangan di Indonesia.
(4) BNPB menggunakan dan mempertanggungjawabkan pengelolaan bantuan internasional sebagaimana dimaksud pada Pasal (1) sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4591, 'perban-6-2018', 19, 'pasal', 'Pasal 16', 'BAB VI KEWENANGAN DAN PENGORGANISASIAN; Bagian Ketiga Peran Kementerian/Lembaga', 17, '(1) Pengaturan penerimaan, pendaftaran dan koordinasi bantuan internasional dilakukan melalui Pos Pendamping Nasional PDB atau Posko Nasional PDB dalam Sistem Komando Penanganan Darurat Bencana.
(2) Bantuan internasional sebagaimana dimaksud pada ayat
(1) dikelola oleh Pos Pendamping Nasional PDB jika diberlakukan status keadaan darurat bencana daerah.
(3) Bantuan internasional sebagaimana dimaksud pada ayat
(1) dikelola oleh Posko Nasional PDB jika diberlakukan status keadaan darurat bencana nasional.
(4) Penerimaan dan reekspor bantuan internasional sebagaimana dimaksud pada ayat (1) dilakukan melalui Pos Pendukung PDB yang ditunjuk sebagai pintu masuk dan pintu keluar.
(5) Pos Pendukung PDB sebagaimana dimaksud pada ayat
(4) dibentuk oleh Pos Pendamping Nasional PDB atau Posko Nasional PDB.
(6) Fungsi Pos Pendukung PDB sebagaimana dimaksud pada ayat (4) dalam penerimaan bantuan internasional, meliputi:
a. pusat pengurusan kepabeanan, keimigrasian dan karantina untuk masuk dan keluarnya bantuan logistik, peralatan, personil asing, dan satuan satwa dari wilayah Indonesia; dan
b. pusat penanganan perijinan dan pengawasan keimigrasian, kepabeanan, perijinan keamanan untuk logistik, peralatan, personil, serta karantina www.peraturan.go.id 2018, No.1645 -18- kesehatan dan karantina tanaman dan/atau hewan.
(7) Setelah diterima di Pos Pendukung PDB sebagaimana dimaksud pada ayat (4), bantuan internasional didaftarkan dan dapat dikoordinasikan melalui pendekatan klaster.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4591, '(1) Pengaturan penerimaan, pendaftaran dan koordinasi bantuan internasional dilakukan melalui Pos Pendamping Nasional PDB atau Posko Nasional PDB dalam Sistem Komando Penanganan Darurat Bencana.
(2) Bantuan internasional sebagaimana dimaksud pada ayat
(1) dikelola oleh Pos Pendamping Nasional PDB jika diberlakukan status keadaan darurat bencana daerah.
(3) Bantuan internasional sebagaimana dimaksud pada ayat
(1) dikelola oleh Posko Nasional PDB jika diberlakukan status keadaan darurat bencana nasional.
(4) Penerimaan dan reekspor bantuan internasional sebagaimana dimaksud pada ayat (1) dilakukan melalui Pos Pendukung PDB yang ditunjuk sebagai pintu masuk dan pintu keluar.
(5) Pos Pendukung PDB sebagaimana dimaksud pada ayat
(4) dibentuk oleh Pos Pendamping Nasional PDB atau Posko Nasional PDB.
(6) Fungsi Pos Pendukung PDB sebagaimana dimaksud pada ayat (4) dalam penerimaan bantuan internasional, meliputi:
a. pusat pengurusan kepabeanan, keimigrasian dan karantina untuk masuk dan keluarnya bantuan logistik, peralatan, personil asing, dan satuan satwa dari wilayah Indonesia; dan
b. pusat penanganan perijinan dan pengawasan keimigrasian, kepabeanan, perijinan keamanan untuk logistik, peralatan, personil, serta karantina www.peraturan.go.id 2018, No.1645 -18- kesehatan dan karantina tanaman dan/atau hewan.
(7) Setelah diterima di Pos Pendukung PDB sebagaimana dimaksud pada ayat (4), bantuan internasional didaftarkan dan dapat dikoordinasikan melalui pendekatan klaster.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4592, 'perban-6-2018', 20, 'pasal', 'Pasal 17', 'BAB VI KEWENANGAN DAN PENGORGANISASIAN; Bagian Keempat Tempat Transit', 18, '(1) BNPB bersama kementerian/lembaga terkait melaksanakan peran di dalam Pos Pendamping Nasional PDB atau Posko Nasional PDB sebagai pusat koordinasi bantuan internasional.
(2) Komposisi dan peran kementerian/lembaga sebagaimana dimaksud pada ayat (1) dalam Pos Pendamping Nasional PDB atau Posko Nasional PDB sebagai berikut:
a. Kementerian Pertahanan dan Mabes TNI, berwenang dalam aspek perijinan dan pengamanan bantuan personil, logistik dan peralatan serta penggunaan atribut yang bersumber dari militer asing serta pergerakan personil militer asing selama pemberian bantuan kemanusiaan;
b. Mabes POLRI berwenang dalam aspek perijinan bantuan yang bersumber dari kepolisian asing serta menjamin keamanan dan keselamatan personil asing dan peralatan/logistiknya selama penanganan darurat bencana, serta memantau pergerakan personil asing;
c. Kementerian Kesehatan berwenang dalam pemeriksaan kualifikasi personil medis, persediaan farmasi, alat dan perbekalan kesehatan;
d. Kementerian Pertanian berwenang dalam pengurusan karantina tanaman dan/atau hewan;
e. Kementerian Sosial berwenang dalam pemulihan dan penguatan sosial, serta kemitraan dan pengelolaan logistik bencana; www.peraturan.go.id 2018, No.1645
f. Kementerian Lingkungan Hidup dan Kehutanan berwenang dalam penanganan bantuan kebakaran hutan dan lahan serta bencana dampak pengelolaan bahan berbahaya dan beracun (B3) dan limbah B3;
g. Kementerian Hukum dan Hak Asasi Manusia berwenang dalam pemberian visa setibanya di Indonesia, izin masuk dan izin tinggal;
h. Kementerian Keuangan berwenang dalam urusan kepabeanan dan perpajakan atas barang impor atau eskpor dan perijinan lalu lintas mata uang asing dari dan ke Indonesia;
i. Kementerian Luar Negeri berwenang dalam pengurusan perizinan diplomatik untuk personil asing, pemeriksaan barang oleh perwakilan diplomatik Republik Indonesia di negara pengirim sebelum dikirim ke Indonesia;
j. Kementerian Perdagangan berwenang dalam pengaturan barang yang diimpor ataupun reekspor;
k. Kementerian Dalam Negeri melalui Pemerintah Daerah/BPBD berwenang dalam penanganan bantuan internasional di Pos Pendukung PDB sesuai kewenangan Pemerintah Daerah/BPBD;
l. Kementerian Perhubungan berwenang dalam perizinan masuknya sarana transportasi, lalu lintas dan penggunaan fasilitas bandara/pelabuhan;
m. Kementerian Komunikasi dan Informatika berwenang dalam perijinan penggunaan alat komunikasi dan informatika yang dibawa oleh Lembaga Internasional dan Lembaga Asing Nonpemerintah;
n. Kementerian Pekerjaan Umum dan Perumahan Rakyat berwenang dalam penanganan bantuan bidang pekerjaan umum dan perumahan rakyat;
o. Kementerian Energi Sumber Daya Mineral berwenang dalam penanganan bantuan bidang energi sumber daya mineral; www.peraturan.go.id 2018, No.1645 -20-
p. Badan Meteorologi, Klimatologi, dan Geofisika berwenang dalam penanganan bantuan meteorologi, klimatologi, dan geofisika;
q. Badan Pengawas Tenaga Nuklir berwenang dalam penanganan bantuan bidang nuklir;
r. Badan Intelijen Negara berwenang dalam pemantauan masuknya bantuan internasional terkait kepentingan dan keamanan nasional;
s. Badan Nasional Pencarian dan Pertolongan berwenang untuk mendampingi proses pemeriksaan masuknya bantuan pencarian dan pertolongan asing;
t. Badan Pengawas Obat dan Makanan berwenang dalam pemeriksaan masuknya obat dan/atau makanan bantuan luar negeri sesuai dengan standar obat dan/atau makanan yang ditetapkan;
u. Lembaga Penerbangan dan Antariksa Nasional berwenang dalam bidang penerbangan dan antariksa;
v. Badan Pengkajian dan Penerapan Teknologi berwenang dalam bidang penerapan teknologi tepat guna;
w. Badan Informasi Geospasial berwenang dalam bidang penyediaan data geospasial pendukung penanganan darurat bencana.
(3) Kementerian/Lembaga sebagaimana tercantum pada ayat
(2) dapat menempatkan petugasnya di Pos Pendukung PDB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4592, '(1) BNPB bersama kementerian/lembaga terkait melaksanakan peran di dalam Pos Pendamping Nasional PDB atau Posko Nasional PDB sebagai pusat koordinasi bantuan internasional.
(2) Komposisi dan peran kementerian/lembaga sebagaimana dimaksud pada ayat (1) dalam Pos Pendamping Nasional PDB atau Posko Nasional PDB sebagai berikut:
a. Kementerian Pertahanan dan Mabes TNI, berwenang dalam aspek perijinan dan pengamanan bantuan personil, logistik dan peralatan serta penggunaan atribut yang bersumber dari militer asing serta pergerakan personil militer asing selama pemberian bantuan kemanusiaan;
b. Mabes POLRI berwenang dalam aspek perijinan bantuan yang bersumber dari kepolisian asing serta menjamin keamanan dan keselamatan personil asing dan peralatan/logistiknya selama penanganan darurat bencana, serta memantau pergerakan personil asing;
c. Kementerian Kesehatan berwenang dalam pemeriksaan kualifikasi personil medis, persediaan farmasi, alat dan perbekalan kesehatan;
d. Kementerian Pertanian berwenang dalam pengurusan karantina tanaman dan/atau hewan;
e. Kementerian Sosial berwenang dalam pemulihan dan penguatan sosial, serta kemitraan dan pengelolaan logistik bencana; www.peraturan.go.id 2018, No.1645
f. Kementerian Lingkungan Hidup dan Kehutanan berwenang dalam penanganan bantuan kebakaran hutan dan lahan serta bencana dampak pengelolaan bahan berbahaya dan beracun (B3) dan limbah B3;
g. Kementerian Hukum dan Hak Asasi Manusia berwenang dalam pemberian visa setibanya di Indonesia, izin masuk dan izin tinggal;
h. Kementerian Keuangan berwenang dalam urusan kepabeanan dan perpajakan atas barang impor atau eskpor dan perijinan lalu lintas mata uang asing dari dan ke Indonesia;
i. Kementerian Luar Negeri berwenang dalam pengurusan perizinan diplomatik untuk personil asing, pemeriksaan barang oleh perwakilan diplomatik Republik Indonesia di negara pengirim sebelum dikirim ke Indonesia;
j. Kementerian Perdagangan berwenang dalam pengaturan barang yang diimpor ataupun reekspor;
k. Kementerian Dalam Negeri melalui Pemerintah Daerah/BPBD berwenang dalam penanganan bantuan internasional di Pos Pendukung PDB sesuai kewenangan Pemerintah Daerah/BPBD;
l. Kementerian Perhubungan berwenang dalam perizinan masuknya sarana transportasi, lalu lintas dan penggunaan fasilitas bandara/pelabuhan;
m. Kementerian Komunikasi dan Informatika berwenang dalam perijinan penggunaan alat komunikasi dan informatika yang dibawa oleh Lembaga Internasional dan Lembaga Asing Nonpemerintah;
n. Kementerian Pekerjaan Umum dan Perumahan Rakyat berwenang dalam penanganan bantuan bidang pekerjaan umum dan perumahan rakyat;
o. Kementerian Energi Sumber Daya Mineral berwenang dalam penanganan bantuan bidang energi sumber daya mineral; www.peraturan.go.id 2018, No.1645 -20-
p. Badan Meteorologi, Klimatologi, dan Geofisika berwenang dalam penanganan bantuan meteorologi, klimatologi, dan geofisika;
q. Badan Pengawas Tenaga Nuklir berwenang dalam penanganan bantuan bidang nuklir;
r. Badan Intelijen Negara berwenang dalam pemantauan masuknya bantuan internasional terkait kepentingan dan keamanan nasional;
s. Badan Nasional Pencarian dan Pertolongan berwenang untuk mendampingi proses pemeriksaan masuknya bantuan pencarian dan pertolongan asing;
t. Badan Pengawas Obat dan Makanan berwenang dalam pemeriksaan masuknya obat dan/atau makanan bantuan luar negeri sesuai dengan standar obat dan/atau makanan yang ditetapkan;
u. Lembaga Penerbangan dan Antariksa Nasional berwenang dalam bidang penerbangan dan antariksa;
v. Badan Pengkajian dan Penerapan Teknologi berwenang dalam bidang penerapan teknologi tepat guna;
w. Badan Informasi Geospasial berwenang dalam bidang penyediaan data geospasial pendukung penanganan darurat bencana.
(3) Kementerian/Lembaga sebagaimana tercantum pada ayat
(2) dapat menempatkan petugasnya di Pos Pendukung PDB.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4593, 'perban-6-2018', 21, 'pasal', 'Pasal 18', 'BAB VI PERPANJANGAN WAKTU DAN PENGAKHIRAN PEMANFAATAN BANTUAN INTERNASIONAL; Bagian Kesatu Prosedur Perpanjangan Waktu Pemanfaatan Bantuan', 20, '(1) Tempat transit terdiri atas:
a. bandar udara;
b. pelabuhan laut;
c. pos lintas batas negara; atau www.peraturan.go.id 2018, No.1645
d. pangkalan militer jika kapasitas pintu masuk/keluar bantuan tidak memadai.
(2) BNPB menyampaikan informasi tempat transit sebagaimana dimaksud pada ayat (1) kepada pemberi bantuan internasional pada saat pernyataan resmi Pemerintah tentang penerimaan bantuan internasional disampaikan atau melalui informasi susulan.
(3) Bantuan internasional sebagaimana dimaksud pada ayat
(2) tidak dibenarkan untuk dibongkar muat di tempat transit.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4593, '(1) Tempat transit terdiri atas:
a. bandar udara;
b. pelabuhan laut;
c. pos lintas batas negara; atau www.peraturan.go.id 2018, No.1645
d. pangkalan militer jika kapasitas pintu masuk/keluar bantuan tidak memadai.
(2) BNPB menyampaikan informasi tempat transit sebagaimana dimaksud pada ayat (1) kepada pemberi bantuan internasional pada saat pernyataan resmi Pemerintah tentang penerimaan bantuan internasional disampaikan atau melalui informasi susulan.
(3) Bantuan internasional sebagaimana dimaksud pada ayat
(2) tidak dibenarkan untuk dibongkar muat di tempat transit.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4594, 'perban-6-2018', 22, 'pasal', 'Pasal 19', 'BAB VI PERPANJANGAN WAKTU DAN PENGAKHIRAN PEMANFAATAN BANTUAN INTERNASIONAL; Bagian Kedua Prosedur Pengakhiran Penerimaan Bantuan Internasional', 21, '(1) Jangka waktu pemanfaatan bantuan internasional dapat diperpanjang sesuai kebutuhan.
(2) Perpanjangan waktu pemanfaatan bantuan internasional sebagaimana dimaksud pada ayat (1) dilakukan berdasarkan:
a. pernyataan Pemerintah mengenai perpanjangan status keadaan darurat bencana; atau
b. pernyataan Pemerintah mengenai perpanjangan waktu untuk pemanfaatan bantuan tanpa memperpanjang status keadaan darurat bencana.
(3) BNPB mengoordinasikan secara langsung bantuan internasional dalam hal perpanjangan waktu sebagaimana dimaksud pada ayat (2) huruf b melalui Pos Pendamping Nasional PDB atau Posko Nasional PDB.
(4) Atas perpanjangan waktu pemanfaatan bantuan internasional sebagaimana dimaksud pada ayat (2), pemberi bantuan dapat mengajukan perpanjangan atau tetap menyelesaikan masa tugasnya. www.peraturan.go.id 2018, No.1645 -22-
(5) Pemberi bantuan internasional yang bersedia memperpanjang masa tugasnya sebagaimana dimaksud pada ayat (4) wajib melaporkan kesediaannya kepada Pos Pendamping Nasional PDB atau Posko Nasional PDB untuk mendapatkan perpanjangan ijin.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4594, '(1) Jangka waktu pemanfaatan bantuan internasional dapat diperpanjang sesuai kebutuhan.
(2) Perpanjangan waktu pemanfaatan bantuan internasional sebagaimana dimaksud pada ayat (1) dilakukan berdasarkan:
a. pernyataan Pemerintah mengenai perpanjangan status keadaan darurat bencana; atau
b. pernyataan Pemerintah mengenai perpanjangan waktu untuk pemanfaatan bantuan tanpa memperpanjang status keadaan darurat bencana.
(3) BNPB mengoordinasikan secara langsung bantuan internasional dalam hal perpanjangan waktu sebagaimana dimaksud pada ayat (2) huruf b melalui Pos Pendamping Nasional PDB atau Posko Nasional PDB.
(4) Atas perpanjangan waktu pemanfaatan bantuan internasional sebagaimana dimaksud pada ayat (2), pemberi bantuan dapat mengajukan perpanjangan atau tetap menyelesaikan masa tugasnya. www.peraturan.go.id 2018, No.1645 -22-
(5) Pemberi bantuan internasional yang bersedia memperpanjang masa tugasnya sebagaimana dimaksud pada ayat (4) wajib melaporkan kesediaannya kepada Pos Pendamping Nasional PDB atau Posko Nasional PDB untuk mendapatkan perpanjangan ijin.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4595, 'perban-6-2018', 23, 'pasal', 'Pasal 20', 'BAB VI PERPANJANGAN WAKTU DAN PENGAKHIRAN PEMANFAATAN BANTUAN INTERNASIONAL; Bagian Kedua Prosedur Pengakhiran Penerimaan Bantuan Internasional', 22, '(1) Ketetapan tanggal berakhirnya status keadaan darurat bencana sekaligus menjadi ketetapan pengakhiran penerimaan bantuan internasional
(2) Pengakhiran bantuan internasional sebagaimana dimaksud pada ayat (1) dilakukan berdasarkan pernyataan resmi Pemerintah.
(3) Pernyataan resmi Pemerintah sebagaimana dimaksud pada ayat (2) dapat dikeluarkan sebelum jangka waktu masa keadaan darurat bencana berakhir.
(4) Pengakhiran bantuan internasional sebagaimana dimaksud pada ayat (2) dilakukan berdasarkan perkembangan di daerah terkena bencana maupun situasi terkait di tingkat nasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4595, '(1) Ketetapan tanggal berakhirnya status keadaan darurat bencana sekaligus menjadi ketetapan pengakhiran penerimaan bantuan internasional
(2) Pengakhiran bantuan internasional sebagaimana dimaksud pada ayat (1) dilakukan berdasarkan pernyataan resmi Pemerintah.
(3) Pernyataan resmi Pemerintah sebagaimana dimaksud pada ayat (2) dapat dikeluarkan sebelum jangka waktu masa keadaan darurat bencana berakhir.
(4) Pengakhiran bantuan internasional sebagaimana dimaksud pada ayat (2) dilakukan berdasarkan perkembangan di daerah terkena bencana maupun situasi terkait di tingkat nasional.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4596, 'perban-6-2018', 24, 'pasal', 'Pasal 21', 'BAB VII PEMANTAUAN, EVALUASI DAN PELAPORAN PENGELOLAAN BANTUAN INTERNASIONAL; Bagian Kesatu Tujuan Pemantauan dan Evaluasi', 22, '(1) BNPB mengoordinasikan penyebarluasan informasi pengakhiran bantuan internasional melalui Kementerian Luar Negeri dengan dilengkapi:
a. laporan singkat tentang situasi dan kondisi terakhir; dan
b. pencapaian target kegiatan penanganan darurat bencana yang dilakukan oleh pemberi bantuan internasional dan para pelaku bencana lain.
(2) Laporan sebagaimana dimaksud pada ayat (1) ditindaklanjuti oleh BNPB dengan mengeluarkan pernyataan ucapan terima kasih atas dukungan pemberi bantuan internasional. www.peraturan.go.id 2018, No.1645
(3) Pemberi bantuan internasional sebagaimana dimaksud pada ayat (2) melapor ke Pos Pendamping Nasional PDB atau Posko Nasional PDB setelah selesainya penugasan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4596, '(1) BNPB mengoordinasikan penyebarluasan informasi pengakhiran bantuan internasional melalui Kementerian Luar Negeri dengan dilengkapi:
a. laporan singkat tentang situasi dan kondisi terakhir; dan
b. pencapaian target kegiatan penanganan darurat bencana yang dilakukan oleh pemberi bantuan internasional dan para pelaku bencana lain.
(2) Laporan sebagaimana dimaksud pada ayat (1) ditindaklanjuti oleh BNPB dengan mengeluarkan pernyataan ucapan terima kasih atas dukungan pemberi bantuan internasional. www.peraturan.go.id 2018, No.1645
(3) Pemberi bantuan internasional sebagaimana dimaksud pada ayat (2) melapor ke Pos Pendamping Nasional PDB atau Posko Nasional PDB setelah selesainya penugasan.', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4597, 'perban-6-2018', 25, 'pasal', 'Pasal 22', 'BAB VII PEMANTAUAN, EVALUASI DAN PELAPORAN PENGELOLAAN BANTUAN INTERNASIONAL; Bagian Kedua Waktu Pelaksanaan Pemantauan dan Evaluasi', 23, '(1) BNPB mengoordinasikan pemantauan dan evaluasi Pengelolaan Bantuan Internasional pada penanganan darurat bencana melalui Pos Pendamping Nasional PDB atau Posko Nasional PDB dengan mempertimbangkan informasi dari masyarakat.
(2) Pemantauan dan evaluasi sebagaimana dimaksud pada ayat (1) bertujuan untuk:
a. memantau dan mengevaluasi kemajuan kegiatan pemberi bantuan internasional;
b. memastikan kesesuaian rencana, pelaksanaan dan hasil yang diharapkan dari pemberi bantuan internasional; dan
c. memastikan akuntabilitas pengelolaan bantuan internasional oleh Pemerintah sesuai dengan peraturan perundang-undangan dan kaidah-kaidah internasional yang berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4597, '(1) BNPB mengoordinasikan pemantauan dan evaluasi Pengelolaan Bantuan Internasional pada penanganan darurat bencana melalui Pos Pendamping Nasional PDB atau Posko Nasional PDB dengan mempertimbangkan informasi dari masyarakat.
(2) Pemantauan dan evaluasi sebagaimana dimaksud pada ayat (1) bertujuan untuk:
a. memantau dan mengevaluasi kemajuan kegiatan pemberi bantuan internasional;
b. memastikan kesesuaian rencana, pelaksanaan dan hasil yang diharapkan dari pemberi bantuan internasional; dan
c. memastikan akuntabilitas pengelolaan bantuan internasional oleh Pemerintah sesuai dengan peraturan perundang-undangan dan kaidah-kaidah internasional yang berlaku.', 'Pasal 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4598, 'perban-6-2018', 26, 'pasal', 'Pasal 23', 'BAB VII PEMANTAUAN, EVALUASI DAN PELAPORAN PENGELOLAAN BANTUAN INTERNASIONAL; Bagian Ketiga Pelaporan', 23, '(1) Kegiatan pemantauan dilakukan secara berkala selama status keadaan darurat bencana diberlakukan.
(2) Evaluasi dapat dilakukan selama dan/atau setelah berakhirnya status keadaan darurat bencana www.peraturan.go.id 2018, No.1645 -24- diberlakukan.
(3) Formulir Pemantauan dan Evaluasi sebagaimana dimaksud pada ayat (1) dan ayat (2) tercantum dalam Lampiran VII, yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4598, '(1) Kegiatan pemantauan dilakukan secara berkala selama status keadaan darurat bencana diberlakukan.
(2) Evaluasi dapat dilakukan selama dan/atau setelah berakhirnya status keadaan darurat bencana www.peraturan.go.id 2018, No.1645 -24- diberlakukan.
(3) Formulir Pemantauan dan Evaluasi sebagaimana dimaksud pada ayat (1) dan ayat (2) tercantum dalam Lampiran VII, yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4599, 'perban-6-2018', 27, 'pasal', 'Pasal 24', 'BAB VIII BIAYA DAN PEMBEBASAN DARI TANGGUNG JAWAB GANTI RUGI; Bagian Kesatu Biaya', 24, '(1) Laporan pemberi bantuan internasional terdiri atas:
a. laporan rutin;
b. laporan tertentu; dan
c. laporan akhir.
(2) Laporan rutin sebagaimana dimaksud pada ayat (1) huruf a wajib diberikan oleh pemberi bantuan internasional kepada Koordinator Pos Pendamping Nasional PDB atau Komandan Posko Nasional PDB.
(3) Pemerintah sewaktu-waktu dapat meminta laporan tertentu sebagaimana dimaksud pada ayat (1) huruf b dari pemberi bantuan internasional.
(4) Pemberi bantuan internasional yang menyelesaikan tugasnya wajib menyerahkan laporan akhir pelaksanaan tugas secara tertulis sebagaimana dimaksud pada ayat
(1) huruf c kepada Pemerintah melalui BNPB.
(5) Laporan akhir sebagaimana dimaksud pada ayat (4) menjadi bahan masukan evaluasi Pemerintah atas bantuan internasional pada status keadaan darurat bencana dan digunakan sebagai pertimbangan dalam menentukan kebijakan Pemerintah dalam penanganan darurat bencana.
(6) Laporan Rutin dan Laporan Akhir sebagaimana dimaksud pada ayat (1) diisi sesuai format yang tercantum dalam Lampiran VIII, yang merupakan bagian tidak terpisahkan dari peraturan ini.
(7) Apabila diperlukan, pelaporan dapat dilengkapi dengan formulir yang telah ditetapkan oleh kementerian/lembaga www.peraturan.go.id 2018, No.1645 terkait.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4599, '(1) Laporan pemberi bantuan internasional terdiri atas:
a. laporan rutin;
b. laporan tertentu; dan
c. laporan akhir.
(2) Laporan rutin sebagaimana dimaksud pada ayat (1) huruf a wajib diberikan oleh pemberi bantuan internasional kepada Koordinator Pos Pendamping Nasional PDB atau Komandan Posko Nasional PDB.
(3) Pemerintah sewaktu-waktu dapat meminta laporan tertentu sebagaimana dimaksud pada ayat (1) huruf b dari pemberi bantuan internasional.
(4) Pemberi bantuan internasional yang menyelesaikan tugasnya wajib menyerahkan laporan akhir pelaksanaan tugas secara tertulis sebagaimana dimaksud pada ayat
(1) huruf c kepada Pemerintah melalui BNPB.
(5) Laporan akhir sebagaimana dimaksud pada ayat (4) menjadi bahan masukan evaluasi Pemerintah atas bantuan internasional pada status keadaan darurat bencana dan digunakan sebagai pertimbangan dalam menentukan kebijakan Pemerintah dalam penanganan darurat bencana.
(6) Laporan Rutin dan Laporan Akhir sebagaimana dimaksud pada ayat (1) diisi sesuai format yang tercantum dalam Lampiran VIII, yang merupakan bagian tidak terpisahkan dari peraturan ini.
(7) Apabila diperlukan, pelaporan dapat dilengkapi dengan formulir yang telah ditetapkan oleh kementerian/lembaga www.peraturan.go.id 2018, No.1645 terkait.', 'Pasal 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4600, 'perban-6-2018', 28, 'pasal', 'Pasal 25', 'BAB VIII BIAYA DAN PEMBEBASAN DARI TANGGUNG JAWAB GANTI RUGI; Bagian Kedua Tata Laksana Reekspor dan Pengurusan Hibah Bantuan', 25, 'Biaya untuk penyediaan bantuan darurat bencana, penanganan operasional ground handling, personil, logistik dan peralatan, pengemasan, pelabelan, distribusi bantuan ke lokasi tujuan, pemusnahan dan reekspor, menjadi tanggung jawab pemberi bantuan internasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4600, 'Biaya untuk penyediaan bantuan darurat bencana, penanganan operasional ground handling, personil, logistik dan peralatan, pengemasan, pelabelan, distribusi bantuan ke lokasi tujuan, pemusnahan dan reekspor, menjadi tanggung jawab pemberi bantuan internasional.', 'Pasal 25', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4601, 'perban-6-2018', 29, 'pasal', 'Pasal 26', 'BAB VIII BIAYA DAN PEMBEBASAN DARI TANGGUNG JAWAB GANTI RUGI; Bagian Ketiga Pembebasan dari Tanggung Jawab Ganti Rugi', 25, '(1) Tata laksana reekspor dan pengurusan hibah bantuan internasional dilaksanakan sesuai dengan ketentuan Peraturan Perundang-undangan.
(2) Pemberi bantuan internasional bertanggung jawab atas:
a. reekspor bantuan yang tidak diperlukan, rusak, atau selesai digunakan; dan
b. pengurusan hibah atas bantuan yang masih dapat dimanfaatkan oleh Pemerintah, Pemerintah Daerah atau kepada pihak ketiga, dilaksanakan sesuai dengan ketentuan Peraturan Perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4601, '(1) Tata laksana reekspor dan pengurusan hibah bantuan internasional dilaksanakan sesuai dengan ketentuan Peraturan Perundang-undangan.
(2) Pemberi bantuan internasional bertanggung jawab atas:
a. reekspor bantuan yang tidak diperlukan, rusak, atau selesai digunakan; dan
b. pengurusan hibah atas bantuan yang masih dapat dimanfaatkan oleh Pemerintah, Pemerintah Daerah atau kepada pihak ketiga, dilaksanakan sesuai dengan ketentuan Peraturan Perundang-undangan.', 'Pasal 26', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4602, 'perban-6-2018', 30, 'pasal', 'Pasal 27', 'BAB IX SANKSI', 25, 'Pemerintah dibebaskan dari tanggung jawab mengganti kerugian pemberi bantuan internasional serta personilnya www.peraturan.go.id 2018, No.1645 -26- atas kelalaian dan tindakan pelanggaran hukum yang berlaku di Indonesia dalam melakukan kegiatan kemanusiaan pada masa penanganan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4602, 'Pemerintah dibebaskan dari tanggung jawab mengganti kerugian pemberi bantuan internasional serta personilnya www.peraturan.go.id 2018, No.1645 -26- atas kelalaian dan tindakan pelanggaran hukum yang berlaku di Indonesia dalam melakukan kegiatan kemanusiaan pada masa penanganan darurat bencana.', 'Pasal 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4603, 'perban-6-2018', 31, 'pasal', 'Pasal 28', 'BAB X PENUTUP', 26, '(1) Pemerintah berwenang memberikan sanksi atas setiap pelanggaran yang dilakukan oleh pemberi bantuan internasional.
(2) Sanksi ditetapkan melalui rapat koordinasi Pos Pendamping Nasional PDB atau Posko Nasional PDB.
(3) Sanksi dapat berupa:
a. teguran tertulis;
b. pencabutan izin operasi sebagian; dan
c. pencabutan izin operasi keseluruhan.');
