INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4604, 'perban-6-2018', 32, 'pasal', 'Pasal 29', 'BAB X PENUTUP', 26, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2010 tentang Pedoman Peran Serta Lembaga Internasional dan Lembaga Asing Non-Pemerintah Pada Saat Tanggap Darurat, dicabut dan dinyatakan tidak berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4604, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2010 tentang Pedoman Peran Serta Lembaga Internasional dan Lembaga Asing Non-Pemerintah Pada Saat Tanggap Darurat, dicabut dan dinyatakan tidak berlaku.', 'Pasal 29', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4605, 'perban-6-2018', 33, 'pasal', 'Pasal 30', 'BAB X PENUTUP', 26, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan. www.peraturan.go.id 2018, No.1645 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4605, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan. www.peraturan.go.id 2018, No.1645 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 30', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4606, 'perban-6-2018', 34, 'lain', 'Penutup', NULL, 27, 'Ditetapkan di Jakarta pada tanggal 27 September 2018 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 13 Desember 2018 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN, KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd WIDODO EKATJAHJANA www.peraturan.go.id 2018, No.1645 Lampiran PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 6 TAHUN 2018 TENTANG PENERIMAAN BANTUAN INTERNASIONAL DALAM KEADAAN DARURAT BENCANA Lampiran I Formulir Laporan Situasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4606, 'Ditetapkan di Jakarta pada tanggal 27 September 2018 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 13 Desember 2018 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN, KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd WIDODO EKATJAHJANA www.peraturan.go.id 2018, No.1645 Lampiran PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 6 TAHUN 2018 TENTANG PENERIMAAN BANTUAN INTERNASIONAL DALAM KEADAAN DARURAT BENCANA Lampiran I Formulir Laporan Situasi', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4607, 'perban-6-2018', 35, 'lampiran', 'Lampiran hal. 28', NULL, 28, 'Lampiran II Daftar Bantuan Lampiran III Alur Penerimaan Bantuan Internasional Lampiran IV Formulir Pengiriman Bantuan Uang dan Kwitansi Lampiran V Format Pendaftaran dan Kartu Identitas Lampiran VI Format Berita Acara Serah Terima Bantuan Lampiran VII Formulir Pemantauan dan Evaluasi Lampiran VIII Formulir Laporan Rutin dan Laporan Akhir Pelaksanaan Tugas 29 2018, No.1645');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4607, 'Lampiran II Daftar Bantuan Lampiran III Alur Penerimaan Bantuan Internasional Lampiran IV Formulir Pengiriman Bantuan Uang dan Kwitansi Lampiran V Format Pendaftaran dan Kartu Identitas Lampiran VI Format Berita Acara Serah Terima Bantuan Lampiran VII Formulir Pemantauan dan Evaluasi Lampiran VIII Formulir Laporan Rutin dan Laporan Akhir Pelaksanaan Tugas 29 2018, No.1645', 'Lampiran hal. 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2018 tentang Penerimaan Bantuan Internasional Dalam Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4608, 'perban-6-2018', 36, 'lampiran', 'Lampiran hal. 29', NULL, 29, 'LAMPIRAN I PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 6 TAHUN 2018 TENTANG PENERIMAAN BANTUAN INTERNASIONAL DALAM KEADAAN DARURAT BENCANA BNPB FORMULIR LAPORAN SITUASI
1. Informasi Umum Dari : BNPB Kepada PAN NN NAN N NN PNNNNAANI (Komunitas Internasional) Tanggal :
Nama kejadian
2. Keterangan Singkat Tentang Kejadian Bencana (ringkasan kejadian bencana) (berikan keterangan dengan singkat tentang jenis bencana, lokasi spesifik, tanggal dan waktu serta dampak kejadian bencana, hal-hal yang menyebabkan kejadian bencana dan cakupan dampak).
Lihat lampiran (jika ada)
3. Kajian dampak bencana (jelaskan kajian dan ringkasan dampak bencana kepada kehidupan, perumahan dan kepemilikan, kehidupan ekonomi, infrastruktur publik, lingkungan) Lihat lampiran (jika ada) www.peraturan.go.id 2018, No.1645 -30-
4. Kajian kebutuhan (islaskan kajian kebutuhan saat ini dan yang akan datang untuk merespon bencana) Lihat lampiran (jika ada)
5. Tindakan dan mobilisasi sumber daya yang telah dilakukan (berikan ringkasan kegiatan dan mobilisasi sumber daya yang telah dilakukan oleh pihak-pihak berwenang dankesediaan menerima/permintaan bantuan internasionalatau tawaran bantuan internasional) Lihat lampiran (jika ada)
6. Hal-hal lain (berikan informasi yang relevan yang diberikan oleh pihak ketiga, misalnya negara-negara lain, organisasi internasional, media, yang mungkin berguna).
Lihat lampiran (jika ada)
31. 2018, No.1645');
