INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4619, 'c. Tanggung Jawab atas pelaksanaan kegiatan hibah/pengadaan (barang/jasa) dan biaya yang dikeluarkan sebagaimana dalam Berita Acara Serah Terima ini menjadi tanggung jawab sepenuhnya PIHAK PERTAMA
