INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4622, 'perban-6-2020', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4622, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4623, 'perban-6-2020', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk meningkatkan kinerja Badan Nasional Penanggulangan Bencana, perlu memberikan akses kepada masyarakat dalam memberikan pengaduan mengenai terjadinya pelanggaran dan tindak pidana di lingkungan Badan Nasional Penanggulangan Bencana,
b. bahwa pengaduan masyarakat sebagaimana dimaksud dalam huruf a, merupakan salah satu bentuk peran serta masyarakat dalam pengawasan pelaksanaan pelayanan publik, sehingga perlu mendapatkan tanggapan dengan cepat, tepat, dan dapat dipertanggungjawabkan,
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Penanganan Pengaduan Masyarakat:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4623, 'a. bahwa untuk meningkatkan kinerja Badan Nasional Penanggulangan Bencana, perlu memberikan akses kepada masyarakat dalam memberikan pengaduan mengenai terjadinya pelanggaran dan tindak pidana di lingkungan Badan Nasional Penanggulangan Bencana,
b. bahwa pengaduan masyarakat sebagaimana dimaksud dalam huruf a, merupakan salah satu bentuk peran serta masyarakat dalam pengawasan pelaksanaan pelayanan publik, sehingga perlu mendapatkan tanggapan dengan cepat, tepat, dan dapat dipertanggungjawabkan,
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Penanganan Pengaduan Masyarakat:', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4624, 'perban-6-2020', 2, 'mengingat', 'Mengingat', NULL, 1, '1 1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723):
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156):');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4624, '1 1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723):
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156):', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4625, 'perban-6-2020', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENANGANAN PENGADUAN MASYARAKAT.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4625, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENANGANAN PENGADUAN MASYARAKAT.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4626, 'perban-6-2020', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM', 2, 'Dalam Peraturan ini yang dimaksud dengan:
1. Pengaduan Masyarakat adalah bentuk penerapan dari pengawasan masyarakat yang disampaikan oleh masyarakat atau kelompok masyarakat kepada aparatur pemerintah, berupa sumbangan pikiran, saran, gagasan, atau keluhan/ pengaduan yang bersifat membangun.
2. Laporan Pengaduan adalah aduan yang disampaikan oleh pegawai atau masyarakat terkait adanya dugaan pelanggaran kode etik pegawai, dugaan pelanggaran disiplin pegawai, dugaan benturan kepentingan dan dugaan tindak pidana di lingkungan Badan Nasional Penanggulangan Bencana.
3. Unit Layanan Pengaduan adalah tim penanganan pengaduan yang ditetapkan dengan keputusan Kepala Badan Nasional Penanggulangan Bencana.
4. Pegawai adalah aparatur sipil negara, calon pegawai negeri Sipil, dan pegawai lain di lingkungan Badan Nasional Penanggulangan Bencana.
S5. Pelapor adalah Pegawai, individu atau kelompok masyarakat yang menyampaikan pengaduan kepada instansi pemerintah tertentu.
6. Terlapor adalah penyelenggara negara, pejabat, Pegawai yang diduga melakukan penyimpangan atau pelanggaran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4626, 'Dalam Peraturan ini yang dimaksud dengan:
1. Pengaduan Masyarakat adalah bentuk penerapan dari pengawasan masyarakat yang disampaikan oleh masyarakat atau kelompok masyarakat kepada aparatur pemerintah, berupa sumbangan pikiran, saran, gagasan, atau keluhan/ pengaduan yang bersifat membangun.
2. Laporan Pengaduan adalah aduan yang disampaikan oleh pegawai atau masyarakat terkait adanya dugaan pelanggaran kode etik pegawai, dugaan pelanggaran disiplin pegawai, dugaan benturan kepentingan dan dugaan tindak pidana di lingkungan Badan Nasional Penanggulangan Bencana.
3. Unit Layanan Pengaduan adalah tim penanganan pengaduan yang ditetapkan dengan keputusan Kepala Badan Nasional Penanggulangan Bencana.
4. Pegawai adalah aparatur sipil negara, calon pegawai negeri Sipil, dan pegawai lain di lingkungan Badan Nasional Penanggulangan Bencana.
S5. Pelapor adalah Pegawai, individu atau kelompok masyarakat yang menyampaikan pengaduan kepada instansi pemerintah tertentu.
6. Terlapor adalah penyelenggara negara, pejabat, Pegawai yang diduga melakukan penyimpangan atau pelanggaran.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4627, 'perban-6-2020', 5, 'pasal', 'Pasal 2', 'BAB II PENGADUAN MASYARAKAT', 3, 'Penanganan pengaduan masyarakat bertujuan untuk:
a. mewujudkan pengelolaan pengaduan masyarakat yang efektif dan efisien, serta menghindari terjadinya duplikasi dalam penanganan pengaduan masyarakat:
b. mendorong terwujudnya penyelenggaraan pemerintahan yang baik dan bebas dari korupsi, kolusi, dan nepotisme');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4627, 'Penanganan pengaduan masyarakat bertujuan untuk:
a. mewujudkan pengelolaan pengaduan masyarakat yang efektif dan efisien, serta menghindari terjadinya duplikasi dalam penanganan pengaduan masyarakat:
b. mendorong terwujudnya penyelenggaraan pemerintahan yang baik dan bebas dari korupsi, kolusi, dan nepotisme', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4628, 'perban-6-2020', 6, 'pasal', 'Pasal 3', 'BAB II PENGADUAN MASYARAKAT', 3, 'Pegawai, individu atau kelompok masyarakat dapat menyampaikan Laporan Pengaduan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4628, 'Pegawai, individu atau kelompok masyarakat dapat menyampaikan Laporan Pengaduan.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4629, 'perban-6-2020', 7, 'pasal', 'Pasal 4', 'BAB II PENGADUAN MASYARAKAT', 3, '(1) Laporan Pengaduan sebagaimana dimaksud dalam Pasal 3 dapat disampaikan secara:
a. langsung, dan
b. tidak langsung.
(2) Laporan pengaduan masyarakat secara langsung sebagaimana dimaksud pada ayat (1) huruf a disampaikan kepada Unit Layanan Pengaduan.
(3) Laporan Pengaduan secara tidak langsung sebagaimana dimaksud dalam ayat (1) huruf b disampaikan melalui:
a. website resmi Badan Nasional Penanggulangan Bencana,
b. surat elektronik dengan alamat inspektorat utama@bnpb.go.id, dan/atau Cc. saluran telepon pengaduan pada nomor 021-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4629, '(1) Laporan Pengaduan sebagaimana dimaksud dalam Pasal 3 dapat disampaikan secara:
a. langsung, dan
b. tidak langsung.
(2) Laporan pengaduan masyarakat secara langsung sebagaimana dimaksud pada ayat (1) huruf a disampaikan kepada Unit Layanan Pengaduan.
(3) Laporan Pengaduan secara tidak langsung sebagaimana dimaksud dalam ayat (1) huruf b disampaikan melalui:
a. website resmi Badan Nasional Penanggulangan Bencana,
b. surat elektronik dengan alamat inspektorat utama@bnpb.go.id, dan/atau Cc. saluran telepon pengaduan pada nomor 021-', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4630, 'perban-6-2020', 8, 'pasal', 'Pasal 5', 'BAB II PENGADUAN MASYARAKAT', 4, 'Laporan Pengaduan yang tidak memuat dan tidak melampirkan identitas Pelapor, wajib ditindaklanjuti oleh Unit Layanan Pengaduan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4630, 'Laporan Pengaduan yang tidak memuat dan tidak melampirkan identitas Pelapor, wajib ditindaklanjuti oleh Unit Layanan Pengaduan.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4631, 'perban-6-2020', 9, 'pasal', 'Pasal 6', 'BAB II PENGADUAN MASYARAKAT', 4, '(1) Laporan Pengaduan sebagaimana dimaksud dalam Pasal 4, paling sedikit memuat:
a. tempat kejadian,
b. waktu kejadian, Cc. pihak yang terlibat: dan
d. kronologis kejadian.
(2) Laporan Pengaduan sebagaimana dimaksud pada ayat (1) dilengkapi dengan dokumen atau bukti pendukung lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4631, '(1) Laporan Pengaduan sebagaimana dimaksud dalam Pasal 4, paling sedikit memuat:
a. tempat kejadian,
b. waktu kejadian, Cc. pihak yang terlibat: dan
d. kronologis kejadian.
(2) Laporan Pengaduan sebagaimana dimaksud pada ayat (1) dilengkapi dengan dokumen atau bukti pendukung lainnya.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4632, 'perban-6-2020', 10, 'pasal', 'Pasal 7', 'BAB II PENGADUAN MASYARAKAT; Bagian Kesatu Tahapan Penanganan Pengaduan Masyarakat', 4, '(1) Jenis pengaduan masyarakat terdiri atas:
a. pengaduan masyarakat berkadar pengawasan: dan
b. pengaduan masyarakat tidak berkadar pengawasan.
(2) Pengaduan masyarakat berkadar pengawasan sebagai mana dimaksud pada ayat (1) huruf a meliputi:
a. pelanggaran kode etik Pegawai:
b. pelanggaran disiplin Pegawai:
c. benturan kepentingan, dan
d. tindak pidana,
(3) Pengaduan masyarakat tidak berkadar pengawasan sebagaimana dimaksud pada ayat (1) huruf b meliputi pengaduan masyarakat yang berisi informasi berupa sumbang saran, kritik konstruktif yang bermanfaat bagi perbaikan penyelenggaraan pemerintahan dan pelayanan masyarakat.
BAB Il PELAKSANAAN');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4632, '(1) Jenis pengaduan masyarakat terdiri atas:
a. pengaduan masyarakat berkadar pengawasan: dan
b. pengaduan masyarakat tidak berkadar pengawasan.
(2) Pengaduan masyarakat berkadar pengawasan sebagai mana dimaksud pada ayat (1) huruf a meliputi:
a. pelanggaran kode etik Pegawai:
b. pelanggaran disiplin Pegawai:
c. benturan kepentingan, dan
d. tindak pidana,
(3) Pengaduan masyarakat tidak berkadar pengawasan sebagaimana dimaksud pada ayat (1) huruf b meliputi pengaduan masyarakat yang berisi informasi berupa sumbang saran, kritik konstruktif yang bermanfaat bagi perbaikan penyelenggaraan pemerintahan dan pelayanan masyarakat.
BAB Il PELAKSANAAN', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4633, 'perban-6-2020', 11, 'pasal', 'Pasal 8', 'BAB II PENGADUAN MASYARAKAT; Bagian Kesatu Tahapan Penanganan Pengaduan Masyarakat', 5, '(1) Pengaduan masyarakat sebagaimana dimaksud dalam Pasal 7 ditindaklanjuti melalui penanganan pengaduan masyarakat.
(2) Penanganan pengaduan masyarakat sebagaimana dimaksud pada ayat (1) dilaksanakan melalui tahapan meliputi:
a. pencatatan,
b. penelaahan,
c. penyaluran,
d. tindak lanjut,
e. pelaporan: dan
I. pengarsipan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4633, '(1) Pengaduan masyarakat sebagaimana dimaksud dalam Pasal 7 ditindaklanjuti melalui penanganan pengaduan masyarakat.
(2) Penanganan pengaduan masyarakat sebagaimana dimaksud pada ayat (1) dilaksanakan melalui tahapan meliputi:
a. pencatatan,
b. penelaahan,
c. penyaluran,
d. tindak lanjut,
e. pelaporan: dan
I. pengarsipan.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4634, 'perban-6-2020', 12, 'pasal', 'Pasal 9', 'BAB II PENGADUAN MASYARAKAT; Bagian Kesatu Tahapan Penanganan Pengaduan Masyarakat', 5, '(1) Pencatatan sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf a dilakukan dengan memuat data pengaduan berupa:
a. Laporan Pengaduan: dan
b. identitas pelapor.
(2) Identitas pelapor sebagaimana dimaksud pada ayat (1) huruf a paling sedikit memuat nama, alamat, nomor kontak, dan pekerjaan.
(3) Pencatatan sebagaimana dimaksud ayat (1) dilakukan secara manual dan/atau menggunakan sistem aplikasi komputer.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4634, '(1) Pencatatan sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf a dilakukan dengan memuat data pengaduan berupa:
a. Laporan Pengaduan: dan
b. identitas pelapor.
(2) Identitas pelapor sebagaimana dimaksud pada ayat (1) huruf a paling sedikit memuat nama, alamat, nomor kontak, dan pekerjaan.
(3) Pencatatan sebagaimana dimaksud ayat (1) dilakukan secara manual dan/atau menggunakan sistem aplikasi komputer.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4635, 'perban-6-2020', 13, 'pasal', 'Pasal 10', 'BAB II PENGADUAN MASYARAKAT; Bagian Kesatu Tahapan Penanganan Pengaduan Masyarakat', 6, '(1) Penelaahan sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf b merupakan proses menelaah data dan informasi Laporan Pengaduan.
(2) Penelaahan sebagaimana dimaksud pada ayat (1) meliputi:
a. merumuskan inti masalah yang diadukan:
b. menghubungkan materi pengaduan dengan peraturan perundang- undangan yang relevan: dan Cc. menetapkan hasil penelaahan pengaduan masyarakat tersebut untuk diproses lebih lanjut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4635, '(1) Penelaahan sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf b merupakan proses menelaah data dan informasi Laporan Pengaduan.
(2) Penelaahan sebagaimana dimaksud pada ayat (1) meliputi:
a. merumuskan inti masalah yang diadukan:
b. menghubungkan materi pengaduan dengan peraturan perundang- undangan yang relevan: dan Cc. menetapkan hasil penelaahan pengaduan masyarakat tersebut untuk diproses lebih lanjut.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4636, 'perban-6-2020', 14, 'pasal', 'Pasal 11', 'BAB II PENGADUAN MASYARAKAT; Bagian Kesatu Tahapan Penanganan Pengaduan Masyarakat', 6, '(1) Penyaluran sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf c merupakan penyampaian pengaduan masyarakat berdasarkan jenis pengaduan masyarakat.
(2) Pengaduan masyarakat berkadar pengawasan yang berindikasi penyimpangan berupa:
a. substansi pengaduan logis dan memadai:
b. identitas pelapornya jelas atau tidak jelas, dan
c. didukung dengan bukti-bukti yang cukup, dapat direkomendasikan untuk dilakukan audit dengan tujuan tertentu atau audit investigasi.
(3) Pengaduan masyarakat tidak berkadar pengawasan yang memerlukan tindak lanjut dapat direkomendasikan untuk diteruskan kepada unit kerja yang bersangkutan untuk ditindaklanjuti. -.7-
(4) Pengaduan masyarakat yang secara substansial bukan kewenangan Badan Nasional Penanggulangan Bencana untuk menindaklanjuti akan dikembalikan kepada Pelapor.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4636, '(1) Penyaluran sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf c merupakan penyampaian pengaduan masyarakat berdasarkan jenis pengaduan masyarakat.
(2) Pengaduan masyarakat berkadar pengawasan yang berindikasi penyimpangan berupa:
a. substansi pengaduan logis dan memadai:
b. identitas pelapornya jelas atau tidak jelas, dan
c. didukung dengan bukti-bukti yang cukup, dapat direkomendasikan untuk dilakukan audit dengan tujuan tertentu atau audit investigasi.
(3) Pengaduan masyarakat tidak berkadar pengawasan yang memerlukan tindak lanjut dapat direkomendasikan untuk diteruskan kepada unit kerja yang bersangkutan untuk ditindaklanjuti. -.7-
(4) Pengaduan masyarakat yang secara substansial bukan kewenangan Badan Nasional Penanggulangan Bencana untuk menindaklanjuti akan dikembalikan kepada Pelapor.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4637, 'perban-6-2020', 15, 'pasal', 'Pasal 12', 'BAB II PENGADUAN MASYARAKAT; Bagian Kesatu Tahapan Penanganan Pengaduan Masyarakat', 7, '(1) Tindak lanjut sebagaimana dimaksud dalam Pasal 8 ayat
(2) huruf d merupakan kegiatan yang dilakukan dalam rangka penyelesaian pengaduan masyarakat.
(2) Tindak lanjut sebagaimana dimaksud pada ayat (1) dilakukan melalui tahapan meliputi:
a. klarifikasi,
b. konfirmasi, C. penelitian, dan
d. pemeriksaan.
(3) Klarifikasi merupakan proses penjernihan masalah atau kegiatan yang pada proporsi yang sebenarnya kepada sumber pengaduan dan instansi terkait.
(4) Konfirmasi merupakan proses kegiatan untuk mendapatkan penegasan mengenai keberadaan terlapor yang teridentifikasi, baik bersifat perorangan, kelompok maupun institusional apabila memungkinkan termasuk masalah yang diadukan.
(5) Penelitian merupakan proses meneliti kelengkapan dari Laporan Pengaduan dan bukti pendukungnya.
(5) Pemeriksaan adalah proses identifikasi masalah, analisis, dan evaluasi bukti yang dilakukan secara independen, obyektif, dan profesional berdasarkan standar yang berlaku, untuk menilai kebenaran atas pengaduan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4637, '(1) Tindak lanjut sebagaimana dimaksud dalam Pasal 8 ayat
(2) huruf d merupakan kegiatan yang dilakukan dalam rangka penyelesaian pengaduan masyarakat.
(2) Tindak lanjut sebagaimana dimaksud pada ayat (1) dilakukan melalui tahapan meliputi:
a. klarifikasi,
b. konfirmasi, C. penelitian, dan
d. pemeriksaan.
(3) Klarifikasi merupakan proses penjernihan masalah atau kegiatan yang pada proporsi yang sebenarnya kepada sumber pengaduan dan instansi terkait.
(4) Konfirmasi merupakan proses kegiatan untuk mendapatkan penegasan mengenai keberadaan terlapor yang teridentifikasi, baik bersifat perorangan, kelompok maupun institusional apabila memungkinkan termasuk masalah yang diadukan.
(5) Penelitian merupakan proses meneliti kelengkapan dari Laporan Pengaduan dan bukti pendukungnya.
(5) Pemeriksaan adalah proses identifikasi masalah, analisis, dan evaluasi bukti yang dilakukan secara independen, obyektif, dan profesional berdasarkan standar yang berlaku, untuk menilai kebenaran atas pengaduan masyarakat.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4638, 'perban-6-2020', 16, 'pasal', 'Pasal 13', 'BAB II PENGADUAN MASYARAKAT; Bagian Kesatu Tahapan Penanganan Pengaduan Masyarakat', 7, '(1) Proses tindak lanjut sebagaimana dimaksud dalam Pasal pengawasan dilakukan dalam jangka waktu paling lama 20 (dua puluh) hari kerja sejak diterimanya Laporan Pengaduan.
(2) Proses tindak lanjut sebagaimana dimaksud pada ayat (1) dilanjutkan dengan audit dengan tujuan tertentu atau audit investigasi.
(3) Tindak lanjut pengaduan masyarakat yang tidak berkadar pengawasan dilakukan paling lama 15 (lima belas) hari kerja sejak Laporan Pengaduan diterima.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4638, '(1) Proses tindak lanjut sebagaimana dimaksud dalam Pasal pengawasan dilakukan dalam jangka waktu paling lama 20 (dua puluh) hari kerja sejak diterimanya Laporan Pengaduan.
(2) Proses tindak lanjut sebagaimana dimaksud pada ayat (1) dilanjutkan dengan audit dengan tujuan tertentu atau audit investigasi.
(3) Tindak lanjut pengaduan masyarakat yang tidak berkadar pengawasan dilakukan paling lama 15 (lima belas) hari kerja sejak Laporan Pengaduan diterima.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4639, 'perban-6-2020', 17, 'pasal', 'Pasal 14', 'BAB II PENGADUAN MASYARAKAT; Bagian Kesatu Tahapan Penanganan Pengaduan Masyarakat', 8, '(1) Pelaporan sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf e merupakan kegiatan penyusunan laporan hasil tindak lanjut penanganan pengaduan masyarakat sebagaimana dimaksud dalam Pasal 12.
(2) Laporan hasil tindak lanjut penanganan pengaduan masyarakat sebagaimana dimaksud ayat (1) disusun secara sistematis, singkat, jelas, dan dapat dipertanggungjawabkan serta memuat kesimpulan dan saran tindak lanjut.
(3) Laporan hasil tindak lanjut penanganan pengaduan masyarakat disampaikan kepada Kepala Badan Nasional Penanggulangan Bencana dan unit kerja terkait.
(M4) Selain disampaikan kepada Kepala Badan Nasional Penanggulangan Bencana, dalam hal laporan hasil tindak lanjut penanganan pengaduan masyarakat merupakan pengaduan masyarakat berkadar pengawasan, disampaikan juga kepada pejabat yang berwenang untuk dilakukan pemeriksaan sesuai peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4639, '(1) Pelaporan sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf e merupakan kegiatan penyusunan laporan hasil tindak lanjut penanganan pengaduan masyarakat sebagaimana dimaksud dalam Pasal 12.
(2) Laporan hasil tindak lanjut penanganan pengaduan masyarakat sebagaimana dimaksud ayat (1) disusun secara sistematis, singkat, jelas, dan dapat dipertanggungjawabkan serta memuat kesimpulan dan saran tindak lanjut.
(3) Laporan hasil tindak lanjut penanganan pengaduan masyarakat disampaikan kepada Kepala Badan Nasional Penanggulangan Bencana dan unit kerja terkait.
(M4) Selain disampaikan kepada Kepala Badan Nasional Penanggulangan Bencana, dalam hal laporan hasil tindak lanjut penanganan pengaduan masyarakat merupakan pengaduan masyarakat berkadar pengawasan, disampaikan juga kepada pejabat yang berwenang untuk dilakukan pemeriksaan sesuai peraturan perundang-undangan.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4640, 'perban-6-2020', 18, 'pasal', 'Pasal 15', 'BAB II PENGADUAN MASYARAKAT; Bagian Kedua Unit Layanan Pengaduan', 9, 'Pengarsipan sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf f merupakan kegiatan penataan dokumen laporan hasil tindak lanjut pengananan pengaduan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4640, 'Pengarsipan sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf f merupakan kegiatan penataan dokumen laporan hasil tindak lanjut pengananan pengaduan masyarakat.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4641, 'perban-6-2020', 19, 'pasal', 'Pasal 16', 'BAB II PENGADUAN MASYARAKAT; Bagian Kedua Unit Layanan Pengaduan', 9, '(1) Kepala Badan Nasional Penanggulangan Bencana membentuk Unit Layanan Pengaduan Badan Nasional Penanggulangan Bencana.
(2) Unit Layanan Pengaduan sebagaimana dimaksud pada ayat (1) terdiri atas:
a. auditor, dan
b. Pegawai pada unit kerja eselon I dan pusat, yang dikoordinasikan secara terpadu oleh Inspektorat Utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4641, '(1) Kepala Badan Nasional Penanggulangan Bencana membentuk Unit Layanan Pengaduan Badan Nasional Penanggulangan Bencana.
(2) Unit Layanan Pengaduan sebagaimana dimaksud pada ayat (1) terdiri atas:
a. auditor, dan
b. Pegawai pada unit kerja eselon I dan pusat, yang dikoordinasikan secara terpadu oleh Inspektorat Utama.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4642, 'perban-6-2020', 20, 'pasal', 'Pasal 17', 'BAB IV PEMANTAUAN PENGADUAN MASYARAKAT', 9, '(1) Unit Layanan Pengaduan sebagaimana dimaksud dalam Pasal 16 bertugas:
a. menerima Laporan Pengaduan:
b. mengumpulkan informasi mengenai kebenaran Laporan Pengaduan:
Cc. mengumpulkan data atau keterangan lainnya yang relevan dengan Pelapor:
d. menclaah Laporan Pengaduan:
e. menilai ancaman atau gangguan yang sudah atau akan terjadi pada Pelapor:
f. memberikan informasi perkembangan Laporan Pengaduan kepada Pelapor,
g. menyiapkan laporan hasil tindak lanjut penanganan pengaduan masyarakat untuk disampaikan kepada Kepala Badan Nasional Penanggulangan Bencana.
(2) Selain melaksanakan tugas sebagaimana dimaksud pada ayat (1), anggota Unit Layanan Pengaduan wajib merahasiakan identitas Pelapor.
(3) Dalam hal anggota Unit Layanan Pengaduan terbukti tidak melaksanakan kewajiban merahasiakan identitas Pelapor sebagaimana dimaksud pada ayat (2), dijatuhi hukuman disiplin sesuai dengan ketentuan peraturan perundang-undangan.
(4) Dalam melaksanakan tugas sebagaimana dimaksud pada ayat (1), Unit Layanan Pengaduan dikoordinasikan oleh Inspektur.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4642, '(1) Unit Layanan Pengaduan sebagaimana dimaksud dalam Pasal 16 bertugas:
a. menerima Laporan Pengaduan:
b. mengumpulkan informasi mengenai kebenaran Laporan Pengaduan:
Cc. mengumpulkan data atau keterangan lainnya yang relevan dengan Pelapor:
d. menclaah Laporan Pengaduan:
e. menilai ancaman atau gangguan yang sudah atau akan terjadi pada Pelapor:
f. memberikan informasi perkembangan Laporan Pengaduan kepada Pelapor,
g. menyiapkan laporan hasil tindak lanjut penanganan pengaduan masyarakat untuk disampaikan kepada Kepala Badan Nasional Penanggulangan Bencana.
(2) Selain melaksanakan tugas sebagaimana dimaksud pada ayat (1), anggota Unit Layanan Pengaduan wajib merahasiakan identitas Pelapor.
(3) Dalam hal anggota Unit Layanan Pengaduan terbukti tidak melaksanakan kewajiban merahasiakan identitas Pelapor sebagaimana dimaksud pada ayat (2), dijatuhi hukuman disiplin sesuai dengan ketentuan peraturan perundang-undangan.
(4) Dalam melaksanakan tugas sebagaimana dimaksud pada ayat (1), Unit Layanan Pengaduan dikoordinasikan oleh Inspektur.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4643, 'perban-6-2020', 21, 'pasal', 'Pasal 18', 'BAB IV PEMANTAUAN PENGADUAN MASYARAKAT', 10, '(1) Pemantauan penanganan pengaduan masyarakat dilakukan oleh Inspektur Utama.
(2) Pemantauan penanganan pengaduan masyarakat sebagaimana dimaksud dalam ayat (1) dilakukan melalui kegiatan:
a. monitoring ke unit kerja terkait:
b. pemutakhiran data, dan/atau C. rapat koordinasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4643, '(1) Pemantauan penanganan pengaduan masyarakat dilakukan oleh Inspektur Utama.
(2) Pemantauan penanganan pengaduan masyarakat sebagaimana dimaksud dalam ayat (1) dilakukan melalui kegiatan:
a. monitoring ke unit kerja terkait:
b. pemutakhiran data, dan/atau C. rapat koordinasi.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4644, 'perban-6-2020', 22, 'pasal', 'Pasal 19', 'BAB V PELINDUNGAN HUKUM DAN PERLAKUAN YANG WAJAR', 10, 'Pelapor berhak mendapatkan informasi mengenai perkembangan Laporan Pengaduan dari Unit Layanan Pengaduan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4644, 'Pelapor berhak mendapatkan informasi mengenai perkembangan Laporan Pengaduan dari Unit Layanan Pengaduan.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4645, 'perban-6-2020', 23, 'pasal', 'Pasal 20', 'BAB V PELINDUNGAN HUKUM DAN PERLAKUAN YANG WAJAR', 11, '(1) Kepala Badan Nasional Penanggulangan Bencana wajib memberikan pelindungan hukum dan perlakuan yang wajar kepada Pelapor dan Terlapor.
(2) Pelindungan hukum dan perlakuan yang wajar sebagaimana dimaksud pada ayat (1) diberikan sejak diterimanya Laporan Pengaduan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4645, '(1) Kepala Badan Nasional Penanggulangan Bencana wajib memberikan pelindungan hukum dan perlakuan yang wajar kepada Pelapor dan Terlapor.
(2) Pelindungan hukum dan perlakuan yang wajar sebagaimana dimaksud pada ayat (1) diberikan sejak diterimanya Laporan Pengaduan.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4646, 'perban-6-2020', 24, 'pasal', 'Pasal 21', 'BAB V PELINDUNGAN HUKUM DAN PERLAKUAN YANG WAJAR', 11, '(1) Pelindungan hukum dan perlakuan yang wajar kepada Pelapor sebagaimana dimaksud dalam Pasal 20 ayat (1) meliputi:
a. tidak dapat dituntut secara hukum baik pidana maupun perdata,
b. menjaga kerahasiaan identitas pelapor, dan Cc. apabila pengaduan tersebut sudah ditangani oleh aparat penegak hukum dan pelapor dijadikan saksi, pelapor berhak mendapatkan pelindungan sesuai dengan ketentuan peraturan perundang-undangan.
(2) Selain mendapat pelindungan hukum dan perlakuan yang wajar sebagaimana dimaksud pada ayat (1), bagi Pegawai diberikan pelindungan dari tindakan balasan administratif kepegawaian dan jaminan hak kepegawaian.
(3) Pejabat yang terbukti menyalahgunakan jabatan dan/atau kewenangannya untuk melakukan tindakan balasan sebagaimana dimaksud pada ayat (2) dijatuhi hukuman disiplin sesuai ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4646, '(1) Pelindungan hukum dan perlakuan yang wajar kepada Pelapor sebagaimana dimaksud dalam Pasal 20 ayat (1) meliputi:
a. tidak dapat dituntut secara hukum baik pidana maupun perdata,
b. menjaga kerahasiaan identitas pelapor, dan Cc. apabila pengaduan tersebut sudah ditangani oleh aparat penegak hukum dan pelapor dijadikan saksi, pelapor berhak mendapatkan pelindungan sesuai dengan ketentuan peraturan perundang-undangan.
(2) Selain mendapat pelindungan hukum dan perlakuan yang wajar sebagaimana dimaksud pada ayat (1), bagi Pegawai diberikan pelindungan dari tindakan balasan administratif kepegawaian dan jaminan hak kepegawaian.
(3) Pejabat yang terbukti menyalahgunakan jabatan dan/atau kewenangannya untuk melakukan tindakan balasan sebagaimana dimaksud pada ayat (2) dijatuhi hukuman disiplin sesuai ketentuan peraturan perundang-undangan.', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4647, 'perban-6-2020', 25, 'pasal', 'Pasal 22', 'BAB VI PENGHARGAAN DAN PEMBERIAN SANKSI', 11, 'Pelindungan hukum dan perlakuan yang wajar kepada Terlapor sebagaimana dimaksud dalam Pasal 20 ayat (1) meliputi:
a. memperlakukan terlapor sebagai pihak yang tidak pemeriksaan dapat membuktikan benar atau tidaknya dugaan pengaduan masyarakat, dan
b. tidak memberikan sanksi dalam bentuk apapun tanpa didukung bukti yang sah dari hasil telaahan, konfirmasi, klarifikasi dan pemeriksaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4647, 'Pelindungan hukum dan perlakuan yang wajar kepada Terlapor sebagaimana dimaksud dalam Pasal 20 ayat (1) meliputi:
a. memperlakukan terlapor sebagai pihak yang tidak pemeriksaan dapat membuktikan benar atau tidaknya dugaan pengaduan masyarakat, dan
b. tidak memberikan sanksi dalam bentuk apapun tanpa didukung bukti yang sah dari hasil telaahan, konfirmasi, klarifikasi dan pemeriksaan.', 'Pasal 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4648, 'perban-6-2020', 26, 'pasal', 'Pasal 23', 'BAB VI PENGHARGAAN DAN PEMBERIAN SANKSI', 12, '(1) Kepala Badan Nasional Penanggulangan Bencana dapat memberikan penghargaan kepada Pelapor sesuai dengan ketentuan peraturan perundang-undangan.
(2) Pemberian penghargaan sebagaimana dimaksud pada ayat (1) berbentuk piagam penghargaan.
(3) Selain piagam penghargaan sebagaimana dimaksud pada ayat (2) dapat diberikan penghargaan berupa:
a. promosi jabatan,
b. mutasi, Cc. rotasi:
d. pendidikan dan pelatihan: ce. beasiswa pendidikan, dan/atau
f. penghargaan lainnya.
4) Penghargaan sebagaimana dimaksud pada ayat (1) diberikan dalam hal Laporan Pengaduan:
a. berdasarkan hasil pemeriksaan, terbukti telah terjadi pelanggaran kode etik Pegawai, disiplin Pegawai atau benturan kepentingan, atau
b. berdasarkan putusan pengadilan yang telah mempunyai kekuatan hukum tetap terbukti telah terjadi tindak pidana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4648, '(1) Kepala Badan Nasional Penanggulangan Bencana dapat memberikan penghargaan kepada Pelapor sesuai dengan ketentuan peraturan perundang-undangan.
(2) Pemberian penghargaan sebagaimana dimaksud pada ayat (1) berbentuk piagam penghargaan.
(3) Selain piagam penghargaan sebagaimana dimaksud pada ayat (2) dapat diberikan penghargaan berupa:
a. promosi jabatan,
b. mutasi, Cc. rotasi:
d. pendidikan dan pelatihan: ce. beasiswa pendidikan, dan/atau
f. penghargaan lainnya.
4) Penghargaan sebagaimana dimaksud pada ayat (1) diberikan dalam hal Laporan Pengaduan:
a. berdasarkan hasil pemeriksaan, terbukti telah terjadi pelanggaran kode etik Pegawai, disiplin Pegawai atau benturan kepentingan, atau
b. berdasarkan putusan pengadilan yang telah mempunyai kekuatan hukum tetap terbukti telah terjadi tindak pidana.', 'Pasal 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4649, 'perban-6-2020', 27, 'pasal', 'Pasal 24', 'BAB VI PENGHARGAAN DAN PEMBERIAN SANKSI', 12, 'Pegawai yang berdasarkan hasil pemeriksaan terbukti membuat Laporan Pengaduan palsu dan/atau membuat Laporan Pengaduan yang bersifat fitnah, dijatuhi hukuman 318 - disiplin oleh pejabat yang berwenang sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4649, 'Pegawai yang berdasarkan hasil pemeriksaan terbukti membuat Laporan Pengaduan palsu dan/atau membuat Laporan Pengaduan yang bersifat fitnah, dijatuhi hukuman 318 - disiplin oleh pejabat yang berwenang sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4650, 'perban-6-2020', 28, 'pasal', 'Pasal 25', 'BAB VII KETENTUAN PENUTUP', 13, 'Pegawai yang berdasarkan hasil pemeriksaan terbukti mengganggu, menghambat, dan/atau menghalangi kelancaran proses kerja Unit Layanan Pengaduan, dijatuhi hukuman disiplin oleh pejabat yang berwenang sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4650, 'Pegawai yang berdasarkan hasil pemeriksaan terbukti mengganggu, menghambat, dan/atau menghalangi kelancaran proses kerja Unit Layanan Pengaduan, dijatuhi hukuman disiplin oleh pejabat yang berwenang sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 25', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4651, 'perban-6-2020', 29, 'pasal', 'Pasal 26', 'BAB VII KETENTUAN PENUTUP', 13, 'Unit Layanan Pengaduan dibentuk dalam jangka waktu paling lama 1 (satu) bulan terhitung sejak Peraturan Badan ini diundangkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4651, 'Unit Layanan Pengaduan dibentuk dalam jangka waktu paling lama 1 (satu) bulan terhitung sejak Peraturan Badan ini diundangkan.', 'Pasal 26', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2020 tentang Penanganan Pengaduan Masyarakat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4652, 'perban-6-2020', 30, 'pasal', 'Pasal 27', 'BAB VII KETENTUAN PENUTUP', 13, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
