INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4656, 'perban-6-2021', 1, 'menimbang', 'Menimbang', NULL, 1, 'b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Petunjuk Teknis Jabatan Fungsional Analis Kebencanaan, 1 1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4656, 'b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Petunjuk Teknis Jabatan Fungsional Analis Kebencanaan, 1 1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2021 tentang Petunjuk Teknis Jabatan Fungsional Analis Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4657, 'perban-6-2021', 2, 'mengingat', 'Mengingat', NULL, 1, '1 a. bahwa untuk menindaklanjuti ketentuan Pasal 53 ayat (2) huruf c Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 87 Tahun 2020 tentang Jabatan Fungsional Analis Kebencanaan, perlu mengatur mengenai petunjuk teknis jabatan fungsional analis kebencanaan,
2. Undang-Undang Nomor 5 Tahun 2014 tentang Aparatur Sipil Negara (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 6, Tambahan AN Lembaran Negara Republik Indonesia Nomor 5494):
Peraturan Pemerintah Nomor 11 Tahun 2017 tentang Manajemen Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 63, Tambahan Lembaran Negara Republik Indonesia Nomor 6037) sebagaimana telah diubah dengan Peraturan Pemerintah Nomor 17 Tahun 2020 tentang Perubahan atas Peraturan Pemerintah Nomor 11 Tahun 2017 tentang Manajemen Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2020 Nomor 68, Tambahan Lembaran Negara Republik Indonesia Nomor 6477), Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103):
Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461), Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 87 Tahun 2020 tentang Jabatan Fungsional Analis Kebencanaan (Berita Negara Republik Indonesia Tahun 2020 Nomor 1588),');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4657, '1 a. bahwa untuk menindaklanjuti ketentuan Pasal 53 ayat (2) huruf c Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 87 Tahun 2020 tentang Jabatan Fungsional Analis Kebencanaan, perlu mengatur mengenai petunjuk teknis jabatan fungsional analis kebencanaan,
2. Undang-Undang Nomor 5 Tahun 2014 tentang Aparatur Sipil Negara (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 6, Tambahan AN Lembaran Negara Republik Indonesia Nomor 5494):
Peraturan Pemerintah Nomor 11 Tahun 2017 tentang Manajemen Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 63, Tambahan Lembaran Negara Republik Indonesia Nomor 6037) sebagaimana telah diubah dengan Peraturan Pemerintah Nomor 17 Tahun 2020 tentang Perubahan atas Peraturan Pemerintah Nomor 11 Tahun 2017 tentang Manajemen Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2020 Nomor 68, Tambahan Lembaran Negara Republik Indonesia Nomor 6477), Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103):
Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461), Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 87 Tahun 2020 tentang Jabatan Fungsional Analis Kebencanaan (Berita Negara Republik Indonesia Tahun 2020 Nomor 1588),', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2021 tentang Petunjuk Teknis Jabatan Fungsional Analis Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4658, 'perban-6-2021', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PETUNJUK TEKNIS JABATAN FUNGSIONAL ANALIS KEBENCANAAN.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4658, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PETUNJUK TEKNIS JABATAN FUNGSIONAL ANALIS KEBENCANAAN.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2021 tentang Petunjuk Teknis Jabatan Fungsional Analis Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4659, 'perban-6-2021', 4, 'pasal', 'Pasal 1', 'BAB II STANDAR KUALITAS HASIL KERJA', 3, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Pegawai Negeri Sipil yang selanjutnya disingkat PNS adalah warga negara Indonesia yang memenuhi syarat tertentu, diangkat sebagai Pegawai ASN secara tetap oleh Pejabat Pembina Kepegawaian untuk menduduki jabatan pemerintahan.
2. Pejabat Pembina Kepegawaian yang selanjutnya disingkat PPK adalah pejabat yang mempunyai kewenangan menetapkan pengangkatan, pemindahan, dan pemberhentian PNS dan pembinaan manajemen PNS di instansi pemerintah sesuai dengan ketentuan peraturan perundang-undangan.
3. Pejabat yang Berwenang yang selanjutnya disebut PyB adalah pejabat yang mempunyai kewenangan melaksanakan proses pengangkatan, pemindahan, dan pemberhentian PNS sesuai dengan ketentuan peraturan perundang-undangan.
4. Instansi Pemerintah adalah instansi pusat dan instansi daerah.
5. Instansi Pusat adalah kementerian, lembaga pemerintah nonkementerian, kesekretariatan lembaga negara, dan kesekretariatan lembaga nonstruktural.
6. Instansi Daerah adalah perangkat daerah provinsi dan perangkat daerah kabupaten/kota yang meliputi sekretariat daerah, sekretariat dewan perwakilan rakyat daerah dan lembaga teknis daerah.
10. dal
12. 13.
14. 15.
Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan.
Instansi Pembina Jabatan Fungsional Analis Kebencanaan yang selanjutnya disebut Instansi Pembina adalah BNPB.
Instansi Pengguna adalah Instansi Pusat dan Instansi Daerah yang mempunyai tugas di bidang penanggulangan bencana.
Jabatan Fungsional Analis Kebencanaan adalah jabatan yang mempunyai ruang lingkup tugas, tanggung jawab, dan wewenang untuk melaksanakan analisis kebencanaan.
Pejabat Fungsional Analis Kebencanaan yang selanjutnya disebut Analis Kebencanaan adalah PNS yang diberi tugas, tanggung jawab, dan wewenang secara penuh oleh PyB melaksanakan analisis kebencanaan.
Analisis Kebencanaan adalah rangkaian kegiatan analisis penanggulangan bencana yang meliputi penyiapan bahan substansi teknis pengaturan bidang kebencanaan, perencanaan analisis bidang kebencanaan, pelaksnaan analisis bidang kebencanaan, pemantauan dan evaluasi, dan penyusunan norma, standar, prosedur, dan kriteria.
Sasaran Kinerja Pegawai yang selanjutnya disingkat SKP adalah rencana kinerja dan target yang akan dicapai oleh seorang PNS yang harus dicapai setiap tahun.
Capaian SKP adalah hasil penilaian rencana kinerja dan target yang dicapai PNS setiap tahun.
Angka Kredit adalah satuan nilai dari tiap butir kegiatan dan/atau akumulasi nilai butir-butir kegiatan yang harus dicapai oleh Analis Kebencanaan dalam rangka pembinaan karier yang bersangkutan.
16. 17.
18. 19.
20. 21.
22. 23.
Angka Kredit Kumulatif adalah akumulasi nilai Angka Kredit minimal yang harus dicapai oleh Analis Kebencanaan sebagai salah satu syarat kenaikan pangkat dan jabatan.
Penetapan Angka Kredit yang selanjutnya disingkat PAK adalah hasil penilaian yang diberikan berdasarkan Angka Kredit untuk pengangkatan atau kenaikan pangkat atau jabatan dalam Jabatan Fungsional Analis Kebencanaan.
Hasil Kerja Minimal adalah unsur kegiatan utama yang harus dicapai minimal oleh Analis Kebencanaan sebagai prasyarat pencapaian hasil kerja.
Tim Penilai Angka Kredit Jabatan Fungsional Analis Kebencanaan yang selanjutnya disebut Tim Penilai adalah tim yang dibentuk dan ditetapkan oleh pejabat yang memiliki kewenangan menetapkan Angka Kredit dan bertugas mengevaluasi keselarasan hasil kerja dengan tugas yang disusun dalam SKP serta menilai capaian kinerja Analis Kebencanaan dalam bentuk Angka Kredit Analis Kebencanaan.
Standar Kompetensi Analis Kebencanaan yang selanjutnya disebut Standar Kompetensi adalah deskripsi pengetahuan, keterampilan dan perilaku yang diperlukan seorang aparatur sipil negara dalam melaksanakan tugas Jabatan Fungsional Analis Kebencanaan.
Uji Kompetensi adalah proses pengukuran dan penilaian terhadap kompetensi teknis, manajerial dan/atau sosial- kultural dari Analis Kebencanaan dalam melaksanakan tugas dan fungsi dalam jabatan.
Karya Tulis/Karya Ilmiah adalah tulisan hasil pokok pikiran, pengembangan, dan hasil kajian/penelitian yang disusun oleh Analis Kebencanaan baik perorangan atau kelompok di bidang Analisis Kebencanaan.
Pemberhentian adalah pemberhentian dari Jabatan Fungsional Analis Kebencanaan dan bukan pemberhentian sebagai PNS.');
