INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4729, 'Pembentukan Organisasi Profesi sebagaimana dimaksud dalam Pasal 68 ayat (3) dilaksanakan paling lambat tanggal 23 Desember 2025.', 'Pasal 72', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2021 tentang Petunjuk Teknis Jabatan Fungsional Analis Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4730, 'perban-6-2021', 75, 'pasal', 'Pasal 73', 'BAB IX KETENTUAN PENUTUP', 47, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
