INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4731, 'perban-6-2021', 76, 'lain', 'Penutup', NULL, 48, 'Ditetapkan di Jakarta pada tanggal 13 Desember 2021 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Diundangkan di Jakarta pada tanggal 24 Desember 2021 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd.
BENNY RIYANTO BERITA NEGARA REPUBLIK INDONESIA TAHUN 2021 NOMOR 1420');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4731, 'Ditetapkan di Jakarta pada tanggal 13 Desember 2021 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SUHARYANTO Diundangkan di Jakarta pada tanggal 24 Desember 2021 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd.
BENNY RIYANTO BERITA NEGARA REPUBLIK INDONESIA TAHUN 2021 NOMOR 1420', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2021 tentang Petunjuk Teknis Jabatan Fungsional Analis Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4732, 'perban-6-2021', 77, 'lampiran', 'Lampiran hal. 48', NULL, 48, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4732, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA', 'Lampiran hal. 48', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2021 tentang Petunjuk Teknis Jabatan Fungsional Analis Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4733, 'perban-6-2021', 78, 'lampiran', 'Lampiran hal. 49', NULL, 49, 'LAMPIRAN I PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR ( TAHUN 2021 TENTANG PETUNJUK TEKNIS JABATAN FUNGSIONAL ANALIS KEBENCANAAN FORMAT DOKUMEN USULAN PENGANGKATAN DALAM JABATAN FUNGSIONAL ANALIS KEBENCANAAN MELALUI PERPINDAHAN DARI JABATAN LAIN Format 1 - Surat Pernyataan Bersedia Untuk Diangkat Dalam Jabatan Fungsional Analis Kebencanaan KOP SURAT INSTANSI Surat Pernyataan Yang bertanda tangan di bawah ini, Nama NIP Pangkat/ Gol.Ruang Instansi/Unit Kerja Jabatan Dengan ini menyatakan sesungguhnya, bahwa saya:
1. bersedia diangkat ke dalam Jabatan Fungsional Analis Kebencanaan,
2. tidak merangkap jabatan dalam jabatan fungsional lainnya,
3. bersedia mengikuti pendidikan dan pelatihan di bidang Kebencanaan, dan
4. bersedia melaksanakan kegiatan di bidang analisis kebencanaan secara aktif.
Demikian Surat Pernyataan ini saya buat untuk dapat dipergunakan sebagaimana mestinya.
Tempat ..., tanggal ....
Mengetahui, Jabatan Atasan Langsung Yang membuat pernyataan, Format 2 - Surat Keterangan Pengalaman Mengenai Pelaksanaan Tugas di Bidang Analisis Kebencanaan KOP SURAT INSTANSI Yang bertanda tangan di bawah ini, Nama NIP Jabatan Instansi Dengan ini menerangkan bahwa:
Nama NIP Pangkat/ Gol. Ruang/TMT Unit Kerja Yang bersangkutan memiliki pengalaman kerja atau jabatan di bidang Analisis No Jabatan Uraian tugas di bidang Jabatan Tahun Fungsional Analis Kebencanaan s.d Demikian surat keterangan ini dibuat dengan sebenarnya dan untuk dapat dipergunakan sebagaimana mestinya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4733, 'LAMPIRAN I PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR ( TAHUN 2021 TENTANG PETUNJUK TEKNIS JABATAN FUNGSIONAL ANALIS KEBENCANAAN FORMAT DOKUMEN USULAN PENGANGKATAN DALAM JABATAN FUNGSIONAL ANALIS KEBENCANAAN MELALUI PERPINDAHAN DARI JABATAN LAIN Format 1 - Surat Pernyataan Bersedia Untuk Diangkat Dalam Jabatan Fungsional Analis Kebencanaan KOP SURAT INSTANSI Surat Pernyataan Yang bertanda tangan di bawah ini, Nama NIP Pangkat/ Gol.Ruang Instansi/Unit Kerja Jabatan Dengan ini menyatakan sesungguhnya, bahwa saya:
