INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4745, 'perban-6-2022', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk menyelenggarakan manajemen logistik penanggulangan bencana yang efektif dan efisien, perlu pelibatan multipihak,
b. bahwa pelibatan multipihak sebagaimana dimaksud dalam huruf a dilaksanakan melalui mekanisme klaster logistik,
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Klaster Logistik Penanggulangan Bencana:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4745, 'a. bahwa untuk menyelenggarakan manajemen logistik penanggulangan bencana yang efektif dan efisien, perlu pelibatan multipihak,
b. bahwa pelibatan multipihak sebagaimana dimaksud dalam huruf a dilaksanakan melalui mekanisme klaster logistik,
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Klaster Logistik Penanggulangan Bencana:', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4746, 'perban-6-2022', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461),');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4746, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103),
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461),', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4747, 'perban-6-2022', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG KLASTER LOGISTIK PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4747, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG KLASTER LOGISTIK PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4748, 'perban-6-2022', 4, 'pasal', 'Pasal 1', 'BAB II PEMBENTUKAN KLASTER LOGISTIK; Bagian Kesatu Pembentukan', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Logistik adalah barang untuk pemenuhan kebutuhan dasar seperti pangan, sandang, papan, dan turunannya dalam rangka penanggulangan bencana.
2. Klaster Logistik adalah merupakan wadah sekumpulan organisasi yang terdiri atas instansi pemerintah, lembaga usaha dan masyarakat, dan yang bekerja bersama-sama untuk meningkatkan respon penanggulangan bencana pada bidang logistik dan bersifat sukarela.
Pemerintah Pusat yang selanjutnya disebut Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
Pemerintah Daerah adalah gubernur, bupati/walikota, atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
Pos Komando Penanganan Darurat Bencana yang selanjutnya disebut Posko PDB adalah institusi yang berfungsi sebagai pusat komando operasi penanganan darurat bencana yang merupakan posko utama di dalam sistem komando penanganan darurat bencana, untuk mengoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan penanganan darurat bencana.
Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan Lembaga Usaha adalah setiap badan hukum yang dapat berbentuk badan usaha milik negara, badan usaha milik daerah, koperasi, atau swasta yang didirikan sesuai dengan ketentuan peraturan perundang-undangan yang menjalankan jenis usaha tetap dan terus-menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia.
Masyarakat adalah perseorangan, kelompok orang dan/atau badan hukum.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4748, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Logistik adalah barang untuk pemenuhan kebutuhan dasar seperti pangan, sandang, papan, dan turunannya dalam rangka penanggulangan bencana.
2. Klaster Logistik adalah merupakan wadah sekumpulan organisasi yang terdiri atas instansi pemerintah, lembaga usaha dan masyarakat, dan yang bekerja bersama-sama untuk meningkatkan respon penanggulangan bencana pada bidang logistik dan bersifat sukarela.
Pemerintah Pusat yang selanjutnya disebut Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
Pemerintah Daerah adalah gubernur, bupati/walikota, atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
Pos Komando Penanganan Darurat Bencana yang selanjutnya disebut Posko PDB adalah institusi yang berfungsi sebagai pusat komando operasi penanganan darurat bencana yang merupakan posko utama di dalam sistem komando penanganan darurat bencana, untuk mengoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan penanganan darurat bencana.
Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan Lembaga Usaha adalah setiap badan hukum yang dapat berbentuk badan usaha milik negara, badan usaha milik daerah, koperasi, atau swasta yang didirikan sesuai dengan ketentuan peraturan perundang-undangan yang menjalankan jenis usaha tetap dan terus-menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia.
Masyarakat adalah perseorangan, kelompok orang dan/atau badan hukum.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4749, 'perban-6-2022', 5, 'pasal', 'Pasal 2', 'BAB II PEMBENTUKAN KLASTER LOGISTIK; Bagian Kedua Struktur Organisasi', 4, '(1) Pemerintah dan Pemerintah Daerah membentuk Klaster Logistik.
(2) Klaster Logistik sebagaimana dimaksud pada ayat (1) terdiri atas:
a. Klaster Logistik nasional,
b. Klaster Logistik provinsi, dan
c. Klaster Logistik kabupaten/kota.
(3) Klaster Logistik nasional sebagaimana dimaksud pada ayat (2) huruf a dibentuk oleh Kepala BNPB.
(4) Klaster Logistik provinsi dan Klaster Logistik kabupaten/kota sebagaimana dimaksud pada ayat (2) huruf b dan huruf c dibentuk oleh Pemerintah Daerah sesuai kewenangannya.
(5) BNPB dapat melakukan pendampingan pembentukan Klaster Logistik yang dilaksanakan Pemerintah Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4749, '(1) Pemerintah dan Pemerintah Daerah membentuk Klaster Logistik.
(2) Klaster Logistik sebagaimana dimaksud pada ayat (1) terdiri atas:
a. Klaster Logistik nasional,
b. Klaster Logistik provinsi, dan
c. Klaster Logistik kabupaten/kota.
(3) Klaster Logistik nasional sebagaimana dimaksud pada ayat (2) huruf a dibentuk oleh Kepala BNPB.
(4) Klaster Logistik provinsi dan Klaster Logistik kabupaten/kota sebagaimana dimaksud pada ayat (2) huruf b dan huruf c dibentuk oleh Pemerintah Daerah sesuai kewenangannya.
(5) BNPB dapat melakukan pendampingan pembentukan Klaster Logistik yang dilaksanakan Pemerintah Daerah.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4750, 'perban-6-2022', 6, 'pasal', 'Pasal 3', 'BAB II PEMBENTUKAN KLASTER LOGISTIK; Bagian Kedua Struktur Organisasi', 4, '(1) Struktur organisasi Klaster Logistik paling sedikit terdiri atas:
a. koordinator,
b. wakil koordinator,
c. sekretariat,
d. bidang perencanaan dan pemenuhan kebutuhan,
e. bidang penyimpanan, dan
f. bidang distribusi.
(2) Setiap bidang dipimpin oleh seorang kepala bidang yang bertanggung jawab kepada koordinator.
(3) Setiap bidang dapat mengembangkan rencana kerja bidang, menentukan peran dan tugas anggota bidang, dan menyusun prosedur di lapangan.
(4) Struktur organisasi Klaster Logistik sebagaimana dimaksud pada ayat (1) dapat disesuaikan dengan kebutuhan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4750, '(1) Struktur organisasi Klaster Logistik paling sedikit terdiri atas:
a. koordinator,
b. wakil koordinator,
c. sekretariat,
d. bidang perencanaan dan pemenuhan kebutuhan,
e. bidang penyimpanan, dan
f. bidang distribusi.
(2) Setiap bidang dipimpin oleh seorang kepala bidang yang bertanggung jawab kepada koordinator.
(3) Setiap bidang dapat mengembangkan rencana kerja bidang, menentukan peran dan tugas anggota bidang, dan menyusun prosedur di lapangan.
(4) Struktur organisasi Klaster Logistik sebagaimana dimaksud pada ayat (1) dapat disesuaikan dengan kebutuhan.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4751, 'perban-6-2022', 7, 'pasal', 'Pasal 4', 'BAB III PENYELENGGARAAN KLASTER LOGISTIK; Bagian Kesatu Prabencana', 5, 'Keanggotaan Klaster Logistik sebagaimana dimaksud dalam Pasal 3 ayat (1) terdiri dari unsur:
a. Pemerintah /Pemerintah Daerah,
b. Lembaga Usaha di bidang Logistik, dan
c. Masyarakat di bidang Logistik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4751, 'Keanggotaan Klaster Logistik sebagaimana dimaksud dalam Pasal 3 ayat (1) terdiri dari unsur:
a. Pemerintah /Pemerintah Daerah,
b. Lembaga Usaha di bidang Logistik, dan
c. Masyarakat di bidang Logistik.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4752, 'perban-6-2022', 8, 'pasal', 'Pasal 5', 'BAB III PENYELENGGARAAN KLASTER LOGISTIK; Bagian Kesatu Prabencana', 5, '(1) Pada tahap prabencana, Klaster Logistik melakukan kegiatan meliputi:
a. koordinasi,
b. meningkatkan kapasitas sumber daya manusia,
c. kajian di bidang logistik,
d. pemetaan sumber daya, dan
e. pemanfaatan sistem peringatan dini.
(2) Koordinasi sebagaimana dimaksud pada ayat (1) huruf a dilakukan melalui mekanisme rapat atau media komunikasi lainnya baik antar anggota dalam struktur organisasi klaster atau dengan pihak lain.
(3) Peningkatan kapasitas sumber daya manusia sebagaimana dimaksud pada ayat (1) huruf b dilakukan melalui seminar, bimbingan teknis dan lokakarya di bidang logistik.
(4) Kajian sebagaimana dimaksud pada ayat (1) huruf c berkaitan dengan bidang logistik yang dibuat apabila terdapat permintaan dari anggota klaster yang disampaikan kepada koordinator.
(5) Pemetaan sumber daya sebagaimana dimaksud pada ayat (1) huruf d dilakukan melalui inventarisasi terhadap sumber daya manusia, infrastruktur logistik, bahan habis pakai dan peralatan milik anggota klaster yang dapat dimanfaatkan bersama pada saat darurat bencana.
(6) Pemanfaatan sistem peringatan dini sebagaimana dimaksud pada ayat (1) huruf e sebagai dasar pertimbangan dan kajian penentuan jenis bantuan dan kebutuhan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4752, '(1) Pada tahap prabencana, Klaster Logistik melakukan kegiatan meliputi:
a. koordinasi,
b. meningkatkan kapasitas sumber daya manusia,
c. kajian di bidang logistik,
d. pemetaan sumber daya, dan
e. pemanfaatan sistem peringatan dini.
(2) Koordinasi sebagaimana dimaksud pada ayat (1) huruf a dilakukan melalui mekanisme rapat atau media komunikasi lainnya baik antar anggota dalam struktur organisasi klaster atau dengan pihak lain.
(3) Peningkatan kapasitas sumber daya manusia sebagaimana dimaksud pada ayat (1) huruf b dilakukan melalui seminar, bimbingan teknis dan lokakarya di bidang logistik.
(4) Kajian sebagaimana dimaksud pada ayat (1) huruf c berkaitan dengan bidang logistik yang dibuat apabila terdapat permintaan dari anggota klaster yang disampaikan kepada koordinator.
(5) Pemetaan sumber daya sebagaimana dimaksud pada ayat (1) huruf d dilakukan melalui inventarisasi terhadap sumber daya manusia, infrastruktur logistik, bahan habis pakai dan peralatan milik anggota klaster yang dapat dimanfaatkan bersama pada saat darurat bencana.
(6) Pemanfaatan sistem peringatan dini sebagaimana dimaksud pada ayat (1) huruf e sebagai dasar pertimbangan dan kajian penentuan jenis bantuan dan kebutuhan.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4753, 'perban-6-2022', 9, 'pasal', 'Pasal 6', 'BAB III PENYELENGGARAAN KLASTER LOGISTIK; Bagian Kedua Darurat Bencana', 6, 'Klaster Logistik dapat melakukan koordinasi minimal setiap 3 (tiga) bulan sekali.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4753, 'Klaster Logistik dapat melakukan koordinasi minimal setiap 3 (tiga) bulan sekali.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4754, 'perban-6-2022', 10, 'pasal', 'Pasal 7', 'BAB III PENYELENGGARAAN KLASTER LOGISTIK; Bagian Kedua Darurat Bencana', 6, '(1) Pada tahap darurat bencana Klaster Logistik melakukan kegiatan meliputi:
a. perencanaan logistik,
b. pencatatan bantuan,
c. distribusi bantuan: dan
d. kegiatan lain di bidang logistik yang dipandang perlu.
(2) Perencanaan logistik sebagaimana dimaksud pada ayat
(1) huruf a berupa:
a. identifikasi jenis dan jumlah kebutuhan korban terdampak,
b. identifikasi sarana prasarana logistik, dan C. penentuan titik masuk bantuan.
NU
(3) Perencanaan logistik sebagaimana dimaksud pada ayat
(2) dilakukan berdasarkan hasil kaji cepat logistik Posko PDB.
(4) Pencatatan bantuan sebagaimana dimaksud pada ayat
(1) huruf b dilakukan dengan mencatat jenis dan jumlah bantuan yang diterima dan didistribusikan.
(5) Distribusi bantuan sebagaimana dimaksud pada ayat
(1) huruf c dilakukan dengan mengirimkan bantuan dari titik masuk kepada penerima manfaat.
(6) Kegiatan lain di bidang logistik yang dipandang perlu dilakukan sebagaimana dimaksud pada ayat (1) huruf d merupakan kegiatan yang dapat dilaksanakan dengan memperhatikan kebutuhan dan situasi di lapangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4754, '(1) Pada tahap darurat bencana Klaster Logistik melakukan kegiatan meliputi:
a. perencanaan logistik,
b. pencatatan bantuan,
c. distribusi bantuan: dan
d. kegiatan lain di bidang logistik yang dipandang perlu.
(2) Perencanaan logistik sebagaimana dimaksud pada ayat
(1) huruf a berupa:
a. identifikasi jenis dan jumlah kebutuhan korban terdampak,
b. identifikasi sarana prasarana logistik, dan C. penentuan titik masuk bantuan.
NU
(3) Perencanaan logistik sebagaimana dimaksud pada ayat
(2) dilakukan berdasarkan hasil kaji cepat logistik Posko PDB.
(4) Pencatatan bantuan sebagaimana dimaksud pada ayat
(1) huruf b dilakukan dengan mencatat jenis dan jumlah bantuan yang diterima dan didistribusikan.
(5) Distribusi bantuan sebagaimana dimaksud pada ayat
(1) huruf c dilakukan dengan mengirimkan bantuan dari titik masuk kepada penerima manfaat.
(6) Kegiatan lain di bidang logistik yang dipandang perlu dilakukan sebagaimana dimaksud pada ayat (1) huruf d merupakan kegiatan yang dapat dilaksanakan dengan memperhatikan kebutuhan dan situasi di lapangan.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4755, 'perban-6-2022', 11, 'pasal', 'Pasal 8', 'BAB III PENYELENGGARAAN KLASTER LOGISTIK; Bagian Kedua Darurat Bencana', 7, '(1) Pada saat darurat bencana, Klaster Logistik bergabung di bawah koordinasi Posko PDB.
(2) Ketentuan mengenai Posko PDB sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4755, '(1) Pada saat darurat bencana, Klaster Logistik bergabung di bawah koordinasi Posko PDB.
(2) Ketentuan mengenai Posko PDB sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4756, 'perban-6-2022', 12, 'pasal', 'Pasal 9', 'BAB III PENYELENGGARAAN KLASTER LOGISTIK; Bagian Ketiga Pascabencana', 7, '(1) Pada bencana skala nasional, Klaster Logistik nasional berkedudukan di ibukota Negara atau wilayah terdekat yang tidak terdampak bencana.
(2) Pada bencana skala provinsi, Klaster Logistik provinsi berkedudukan di ibukota provinsi atau wilayah terdekat yang tidak terdampak bencana.
(3) Pada bencana skala kabupaten/kota, Klaster Logistik kabupaten/kota berkedudukan di ibukota kabupaten/kota atau wilayah terdekat yang tidak terdampak bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4756, '(1) Pada bencana skala nasional, Klaster Logistik nasional berkedudukan di ibukota Negara atau wilayah terdekat yang tidak terdampak bencana.
(2) Pada bencana skala provinsi, Klaster Logistik provinsi berkedudukan di ibukota provinsi atau wilayah terdekat yang tidak terdampak bencana.
(3) Pada bencana skala kabupaten/kota, Klaster Logistik kabupaten/kota berkedudukan di ibukota kabupaten/kota atau wilayah terdekat yang tidak terdampak bencana.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4757, 'perban-6-2022', 13, 'pasal', 'Pasal 10', 'BAB IV PELAPORAN', 8, '(1) Kegiatan Klaster Logistik pada tahap pascabencana hanya dilakukan berdasarkan kesepakatan anggota.
(2) Klaster Logistik dapat melakukan evaluasi penanganan darurat bencana yang telah selesai dilaksanakan.
(3) Evaluasi penanganan darurat bencana sebagaimana dimaksud pada ayat (2) meliputi:
a. pemahaman anggota klaster terhadap perannya di dalam struktur organisasi,
b. kelancaran koordinasi dalam struktur organisasi klaster,
c. keakuratan perencanaan logistik, dan/atau
d. kesesuaian pencatatan masuk dengan distribusi bantuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4757, '(1) Kegiatan Klaster Logistik pada tahap pascabencana hanya dilakukan berdasarkan kesepakatan anggota.
(2) Klaster Logistik dapat melakukan evaluasi penanganan darurat bencana yang telah selesai dilaksanakan.
(3) Evaluasi penanganan darurat bencana sebagaimana dimaksud pada ayat (2) meliputi:
a. pemahaman anggota klaster terhadap perannya di dalam struktur organisasi,
b. kelancaran koordinasi dalam struktur organisasi klaster,
c. keakuratan perencanaan logistik, dan/atau
d. kesesuaian pencatatan masuk dengan distribusi bantuan.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4758, 'perban-6-2022', 14, 'pasal', 'Pasal 11', 'BAB V PENDANAAN', 8, '(1) Sekretariat Klaster Logistik melaksanakan pelaporan kegiatan secara berkala.
(2) Pelaporan kegiatan pada tahap prabencana dengan mekanisme:
a. kegiatan yang dilaksanakan oleh Klaster Logistik nasional disampaikan setiap 3 (tiga) bulan kepada Kepala BNPB, dan
b. kegiatan yang dilaksanakan oleh Klaster Logistik provinsi dan Klaster Logistik kabupaten/kota disampaikan setiap 3 (tiga) bulan kepada kepala daerah.
(3) Pelaporan kegiatan pada saat darurat bencana yang dilaksanakan oleh Klaster Logistik disampaikan kepada Kepala BNPB melalui Posko PDB.
(4) Apabila diperlukan, pelaporan kegiatan pada tahap pascabencana dengan mekanisme:
a. kegiatan yang dilaksanakan oleh Klaster Logistik nasional disampaikan kepada Kepala BNPB, dan
b. kegiatan yang dilaksanakan oleh Klaster Logistik nasional disampaikan kepada kepala daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4758, '(1) Sekretariat Klaster Logistik melaksanakan pelaporan kegiatan secara berkala.
(2) Pelaporan kegiatan pada tahap prabencana dengan mekanisme:
a. kegiatan yang dilaksanakan oleh Klaster Logistik nasional disampaikan setiap 3 (tiga) bulan kepada Kepala BNPB, dan
b. kegiatan yang dilaksanakan oleh Klaster Logistik provinsi dan Klaster Logistik kabupaten/kota disampaikan setiap 3 (tiga) bulan kepada kepala daerah.
(3) Pelaporan kegiatan pada saat darurat bencana yang dilaksanakan oleh Klaster Logistik disampaikan kepada Kepala BNPB melalui Posko PDB.
(4) Apabila diperlukan, pelaporan kegiatan pada tahap pascabencana dengan mekanisme:
a. kegiatan yang dilaksanakan oleh Klaster Logistik nasional disampaikan kepada Kepala BNPB, dan
b. kegiatan yang dilaksanakan oleh Klaster Logistik nasional disampaikan kepada kepala daerah.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4759, 'perban-6-2022', 15, 'pasal', 'Pasal 12', 'BAB VI KETENTUAN PENUTUP', 9, 'Sumber pendanaan penyelenggaraan Klaster Logistik dapat berasal dari:
a. Anggaran Pendapatan dan Belanja Negara,
b. Anggaran Pendapatan dan Belanja Daerah, dan/atau
c. sumber pendanaan lain sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4759, 'Sumber pendanaan penyelenggaraan Klaster Logistik dapat berasal dari:
a. Anggaran Pendapatan dan Belanja Negara,
b. Anggaran Pendapatan dan Belanja Daerah, dan/atau
c. sumber pendanaan lain sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2022 tentang Klaster Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4760, 'perban-6-2022', 16, 'pasal', 'Pasal 13', 'BAB VI KETENTUAN PENUTUP', 9, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
