INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4763, 'perban-6-2024', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4763, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4764, 'perban-6-2024', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk melaksanakan pengendalian intern di lingkungan Badan Nasional Penanggulangan Bencana, perlu penerapan manajemen risiko guna menciptakan tata kelola pemerintahan yang baik;
b. bahwa pengelolaan risiko sebagaimana diatur dalam Peraturan Pemerintah Nomor 60 Tahun 2008 tentang Sistem Pengendalian Intern Pemerintah perlu diterapkan secara terintegrasi dengan melibatkan unit kerja di lingkungan Badan Nasional Penanggulangan Bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4764, 'a. bahwa untuk melaksanakan pengendalian intern di lingkungan Badan Nasional Penanggulangan Bencana, perlu penerapan manajemen risiko guna menciptakan tata kelola pemerintahan yang baik;
b. bahwa pengelolaan risiko sebagaimana diatur dalam Peraturan Pemerintah Nomor 60 Tahun 2008 tentang Sistem Pengendalian Intern Pemerintah perlu diterapkan secara terintegrasi dengan melibatkan unit kerja di lingkungan Badan Nasional Penanggulangan Bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4765, 'perban-6-2024', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4765, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4766, 'perban-6-2024', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG MANAJEMEN RISIKO DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4766, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG MANAJEMEN RISIKO DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4767, 'perban-6-2024', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Risiko adalah kemungkinan terjadinya suatu peristiwa yang membawa akibat yang tidak diinginkan atas pencapaian tujuan dan sasaran organisasi.
2. Manajemen Risiko adalah serangkaian kegiatan terencana dan terukur untuk mengelola dan mengendalikan Risiko yang berpotensi mengancam keberlangsungan dan pencapaian tujuan organisasi.
3. Budaya Sadar Risiko adalah sekumpulan nilai, kepercayaan, pengetahuan dan pemahaman tentang risiko, yang dimiliki bersama oleh sekelompok orang dengan tujuan yang sama.
4. Selera Risiko adalah ambang batas besaran level Risiko yang berada dalam area penerimaan Risiko dan tidak perlu dilakukan kegiatan pengendalian.
5. Risiko Kunci adalah Risiko yang sangat penting untuk dikelola bagi keberhasilan pencapaian tujuan organisasi.
6. Proses Manajemen Risiko adalah tahapan prosedur yang meliputi, penetapan konteks, identifikasi Risiko, analisis Risiko, evaluasi Risiko, respons Risiko, pemantauan, dan informasi dan komunikasi.
7. Unit Manajemen Risiko yang selanjutnya disingkat UMR adalah unit organisasi yang bertanggung jawab melaksanakan Manajemen Risiko.
8. Aparat Pengawasan Intern Pemerintah yang selanjutnya disingkat APIP adalah aparat pengawasan intern pemerintah di lingkungan Badan Nasional Penanggulangan Bencana.
9. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4767, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Risiko adalah kemungkinan terjadinya suatu peristiwa yang membawa akibat yang tidak diinginkan atas pencapaian tujuan dan sasaran organisasi.
2. Manajemen Risiko adalah serangkaian kegiatan terencana dan terukur untuk mengelola dan mengendalikan Risiko yang berpotensi mengancam keberlangsungan dan pencapaian tujuan organisasi.
3. Budaya Sadar Risiko adalah sekumpulan nilai, kepercayaan, pengetahuan dan pemahaman tentang risiko, yang dimiliki bersama oleh sekelompok orang dengan tujuan yang sama.
4. Selera Risiko adalah ambang batas besaran level Risiko yang berada dalam area penerimaan Risiko dan tidak perlu dilakukan kegiatan pengendalian.
5. Risiko Kunci adalah Risiko yang sangat penting untuk dikelola bagi keberhasilan pencapaian tujuan organisasi.
6. Proses Manajemen Risiko adalah tahapan prosedur yang meliputi, penetapan konteks, identifikasi Risiko, analisis Risiko, evaluasi Risiko, respons Risiko, pemantauan, dan informasi dan komunikasi.
7. Unit Manajemen Risiko yang selanjutnya disingkat UMR adalah unit organisasi yang bertanggung jawab melaksanakan Manajemen Risiko.
8. Aparat Pengawasan Intern Pemerintah yang selanjutnya disingkat APIP adalah aparat pengawasan intern pemerintah di lingkungan Badan Nasional Penanggulangan Bencana.
9. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4768, 'perban-6-2024', 5, 'pasal', 'Pasal 2', 'BAB I KETENTUAN UMUM', 2, 'Manajemen Risiko memiliki tujuan untuk:
a. mengelola dan memitigasi Risiko yang ada dalam proses bisnis dan fungsi dalam organisasi;
b. memberikan pelindungan bagi organisasi dari ancaman Risiko yang menghambat proses pencapaian tujuan dan sasaran kinerja;
c. mendorong seluruh unit organisasi untuk bertindak proaktif dan antisipatif;
d. meningkatkan kemampuan pegawai dalam menghadapi Risiko organisasi, sebagai upaya untuk memaksimalkan pencapaian kinerja; dan
e. mendorong kepedulian pegawai mengenai pentingnya Budaya Sadar Risiko.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4768, 'Manajemen Risiko memiliki tujuan untuk:
a. mengelola dan memitigasi Risiko yang ada dalam proses bisnis dan fungsi dalam organisasi;
b. memberikan pelindungan bagi organisasi dari ancaman Risiko yang menghambat proses pencapaian tujuan dan sasaran kinerja;
c. mendorong seluruh unit organisasi untuk bertindak proaktif dan antisipatif;
d. meningkatkan kemampuan pegawai dalam menghadapi Risiko organisasi, sebagai upaya untuk memaksimalkan pencapaian kinerja; dan
e. mendorong kepedulian pegawai mengenai pentingnya Budaya Sadar Risiko.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4769, 'perban-6-2024', 6, 'pasal', 'Pasal 3', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Kesatu Umum', 3, '(1) Manajemen Risiko dilaksanakan berdasarkan prinsip:
a. terintegrasi;
b. terstruktur dan komprehensif;
c. adaptif;
d. inklusif;
e. dinamis;
f. berdasarkan informasi terbaik yang tersedia;
g. memperhatikan sumber daya manusia dan budaya; dan
h. perbaikan berkesinambungan.
(2) Berdasarkan prinsip terintegrasi sebagaimana dimaksud pada ayat (1) huruf a, Manajemen Risiko dilaksanakan terintegrasi sebagai bagian-bagian suatu organisasi.
(3) Berdasarkan prinsip terstruktur dan komprehensif sebagaimana dimaksud pada ayat (1) huruf b, Manajemen Risiko dilaksanakan sebagai suatu pendekatan yang akan memberikan kontribusi pada hasil yang konsisten dan dapat dibandingkan.
(4) Berdasarkan prinsip adaptif sebagaimana dimaksud pada ayat (1) huruf c, Manajemen Risiko dilaksanakan sesuai konteks organisasi baik internal maupun eksternal sesuai dengan tujuan organisasi.
(5) Berdasarkan prinsip inklusif sebagaimana dimaksud pada ayat (1) huruf d, Manajemen Risiko dilaksanakan dengan menyesuaikan dan melibatkan pemangku kepentingan sesuai dengan pengetahuan, pandangan dan persepsinya.
(6) Berdasarkan prinsip dinamis sebagaimana dimaksud pada ayat (1) huruf e, Manajemen Risiko dilaksanakan sesuai risiko dapat timbul, berubah, atau hilang sesuai dengan perubahan konteks organisasi baik internal maupun eksternal
(7) Berdasarkan prinsip berdasarkan informasi terbaik yang tersedia sebagaimana dimaksud pada ayat (1) huruf f, Manajemen Risiko dilaksanakan berdasarkan informasi historis dan terkini, maupun ekspektasi masa datang.
(8) Berdasarkan prinsip memperhatikan sumber daya manusia dan budaya sebagaimana dimaksud pada ayat (1) huruf g, Manajemen Risiko dilaksanakan sesuai perilaku manusia dan budaya yang secara signifikan akan memengaruhi seluruh aspek Manajemen Risiko baik setiap level maupun tahapan.
(9) Berdasarkan prinsip perbaikan berkesinambungan sebagaimana dimaksud pada ayat (1) huruf h, Manajemen Risiko dilaksanakan untuk perbaikan secara berkelanjutan melalui pembelajaran dan pengalaman.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4769, '(1) Manajemen Risiko dilaksanakan berdasarkan prinsip:
a. terintegrasi;
b. terstruktur dan komprehensif;
c. adaptif;
d. inklusif;
e. dinamis;
f. berdasarkan informasi terbaik yang tersedia;
g. memperhatikan sumber daya manusia dan budaya; dan
h. perbaikan berkesinambungan.
(2) Berdasarkan prinsip terintegrasi sebagaimana dimaksud pada ayat (1) huruf a, Manajemen Risiko dilaksanakan terintegrasi sebagai bagian-bagian suatu organisasi.
(3) Berdasarkan prinsip terstruktur dan komprehensif sebagaimana dimaksud pada ayat (1) huruf b, Manajemen Risiko dilaksanakan sebagai suatu pendekatan yang akan memberikan kontribusi pada hasil yang konsisten dan dapat dibandingkan.
(4) Berdasarkan prinsip adaptif sebagaimana dimaksud pada ayat (1) huruf c, Manajemen Risiko dilaksanakan sesuai konteks organisasi baik internal maupun eksternal sesuai dengan tujuan organisasi.
(5) Berdasarkan prinsip inklusif sebagaimana dimaksud pada ayat (1) huruf d, Manajemen Risiko dilaksanakan dengan menyesuaikan dan melibatkan pemangku kepentingan sesuai dengan pengetahuan, pandangan dan persepsinya.
(6) Berdasarkan prinsip dinamis sebagaimana dimaksud pada ayat (1) huruf e, Manajemen Risiko dilaksanakan sesuai risiko dapat timbul, berubah, atau hilang sesuai dengan perubahan konteks organisasi baik internal maupun eksternal
(7) Berdasarkan prinsip berdasarkan informasi terbaik yang tersedia sebagaimana dimaksud pada ayat (1) huruf f, Manajemen Risiko dilaksanakan berdasarkan informasi historis dan terkini, maupun ekspektasi masa datang.
(8) Berdasarkan prinsip memperhatikan sumber daya manusia dan budaya sebagaimana dimaksud pada ayat (1) huruf g, Manajemen Risiko dilaksanakan sesuai perilaku manusia dan budaya yang secara signifikan akan memengaruhi seluruh aspek Manajemen Risiko baik setiap level maupun tahapan.
(9) Berdasarkan prinsip perbaikan berkesinambungan sebagaimana dimaksud pada ayat (1) huruf h, Manajemen Risiko dilaksanakan untuk perbaikan secara berkelanjutan melalui pembelajaran dan pengalaman.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4770, 'perban-6-2024', 7, 'pasal', 'Pasal 4', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Kedua Pembangunan Budaya Sadar Risiko', 4, '(1) Setiap pimpinan dan pegawai di lingkungan BNPB wajib menerapkan Manajemen Risiko dalam pelaksanaan kegiatan yang berkaitan dengan tujuan organisasi dan sasaran kinerja organisasi.
(2) Manajemen Risiko sebagaimana dimaksud pada ayat (1) diselenggarakan oleh seluruh unit kerja di lingkungan BNPB.
(3) Penerapan Manajemen Risiko sebagaimana dimaksud pada ayat (1) dilaksanakan melalui:
a. pembangunan Budaya Sadar Risiko;
b. pembentukan struktur Manajemen Risiko; dan
c. perumusan dan pelaksanaan Proses Manajemen Risiko.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4770, '(1) Setiap pimpinan dan pegawai di lingkungan BNPB wajib menerapkan Manajemen Risiko dalam pelaksanaan kegiatan yang berkaitan dengan tujuan organisasi dan sasaran kinerja organisasi.
(2) Manajemen Risiko sebagaimana dimaksud pada ayat (1) diselenggarakan oleh seluruh unit kerja di lingkungan BNPB.
(3) Penerapan Manajemen Risiko sebagaimana dimaksud pada ayat (1) dilaksanakan melalui:
a. pembangunan Budaya Sadar Risiko;
b. pembentukan struktur Manajemen Risiko; dan
c. perumusan dan pelaksanaan Proses Manajemen Risiko.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4771, 'perban-6-2024', 8, 'pasal', 'Pasal 5', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Ketiga Pembentukan Struktur Manajemen Risiko', 4, '(1) Pembangunan Budaya Sadar Risiko sebagaimana dimaksud dalam Pasal 4 ayat (3) huruf a dilaksanakan sesuai dengan asas dan prinsip penanggulangan bencana untuk mencapai tujuan dan sasaran BNPB.
(2) Pembangunan Budaya Sadar Risiko dilakukan dalam bentuk:
a. komitmen pimpinan;
b. pengintegrasian Manajemen Risiko dalam proses bisnis organisasi;
c. penyampaian informasi yang berkelanjutan mengenai Risiko;
d. tersedianya program pelatihan Manajemen Risiko untuk seluruh pegawai;
e. kejelasan tugas, fungsi, serta alokasi sumber daya untuk penanganan Risiko;
f. penghargaan terhadap ketepatan pengambilan Risiko oleh organisasi dan/atau pegawai; dan
g. ketersediaan informasi Risiko yang tepat sebagai landasan dalam pengambilan keputusan.
(3) Pembangunan Budaya Sadar Risiko dilaksanakan melalui tahap:
a. peningkatan kesadaran Budaya Sadar Risiko;
b. manajemen perubahan Budaya Sadar Risiko organisasi; dan
c. penyempurnaan Budaya Sadar Risiko organisasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4771, '(1) Pembangunan Budaya Sadar Risiko sebagaimana dimaksud dalam Pasal 4 ayat (3) huruf a dilaksanakan sesuai dengan asas dan prinsip penanggulangan bencana untuk mencapai tujuan dan sasaran BNPB.
(2) Pembangunan Budaya Sadar Risiko dilakukan dalam bentuk:
a. komitmen pimpinan;
b. pengintegrasian Manajemen Risiko dalam proses bisnis organisasi;
c. penyampaian informasi yang berkelanjutan mengenai Risiko;
d. tersedianya program pelatihan Manajemen Risiko untuk seluruh pegawai;
e. kejelasan tugas, fungsi, serta alokasi sumber daya untuk penanganan Risiko;
f. penghargaan terhadap ketepatan pengambilan Risiko oleh organisasi dan/atau pegawai; dan
g. ketersediaan informasi Risiko yang tepat sebagai landasan dalam pengambilan keputusan.
(3) Pembangunan Budaya Sadar Risiko dilaksanakan melalui tahap:
a. peningkatan kesadaran Budaya Sadar Risiko;
b. manajemen perubahan Budaya Sadar Risiko organisasi; dan
c. penyempurnaan Budaya Sadar Risiko organisasi.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4772, 'perban-6-2024', 9, 'pasal', 'Pasal 6', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Ketiga Pembentukan Struktur Manajemen Risiko', 5, '(1) Struktur Manajemen Risiko sebagaimana dimaksud dalam Pasal 4 ayat (3) huruf b merupakan sinergi antar personel pada semua level yang memberikan perspektif lengkap tentang Manajemen Risiko.
(2) Struktur Manajemen Risiko di lingkungan BNPB sebagaimana dimaksud pada ayat (1) menggunakan konsep 3 (tiga) lini, terdiri atas:
a. lini kesatu;
b. lini kedua; dan
c. lini ketiga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4772, '(1) Struktur Manajemen Risiko sebagaimana dimaksud dalam Pasal 4 ayat (3) huruf b merupakan sinergi antar personel pada semua level yang memberikan perspektif lengkap tentang Manajemen Risiko.
(2) Struktur Manajemen Risiko di lingkungan BNPB sebagaimana dimaksud pada ayat (1) menggunakan konsep 3 (tiga) lini, terdiri atas:
a. lini kesatu;
b. lini kedua; dan
c. lini ketiga.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4773, 'perban-6-2024', 10, 'pasal', 'Pasal 7', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Ketiga Pembentukan Struktur Manajemen Risiko', 5, '(1) Lini kesatu sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf a dilaksanakan oleh:
a. pemilik Risiko; dan
b. pengelola Risiko.
(2) Lini kedua sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf b dilaksanakan oleh UMR.
(3) Lini ketiga sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf c dilaksanakan oleh unit pengawas intern.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4773, '(1) Lini kesatu sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf a dilaksanakan oleh:
a. pemilik Risiko; dan
b. pengelola Risiko.
(2) Lini kedua sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf b dilaksanakan oleh UMR.
(3) Lini ketiga sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf c dilaksanakan oleh unit pengawas intern.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4774, 'perban-6-2024', 11, 'pasal', 'Pasal 8', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Ketiga Pembentukan Struktur Manajemen Risiko', 5, '(1) Pemilik Risiko sebagaimana dimaksud dalam Pasal 7 ayat
(1) huruf a merupakan pejabat yang menanggungjawabi Proses Manajemen Risiko atas sasaran organisasi sesuai tugas dan fungsi organisasi atau unit kerja yang bersangkutan.
(2) Pemilik Risiko sebagaimana dimaksud pada ayat (1) terdiri atas:
a. pemilik Risiko untuk level entitas BNPB yaitu Kepala BNPB;
b. pemilik Risiko untuk level Eselon I BNPB yaitu Sekretaris Utama, Inspektur Utama, dan Deputi; dan
c. pemilik Risiko untuk level Eselon II BNPB yaitu Kepala Pusat.
(3) Pemilik Risiko sebagaimana dimaksud pada ayat (1) bertanggung jawab:
a. memastikan Risiko telah diidentifikasi, dinilai, dikelola, dan dipantau;
b. menentukan Selera Risiko yang tepat;
c. mengintegrasikan Manajemen Risiko ke dalam pencapaian kinerja dengan menetapkan dan mendelegasikan pelaksanaan rencana tindak pengendalian; dan
d. menyampaikan laporan pengelolaan Risiko yang disusun pengelola Risiko.
(4) Laporan pengelolaan Risiko sebagaimana dimaksud pada ayat (3) huruf d untuk level Eselon I BNPB ditujukan kepada Kepala BNPB dengan tembusan kepada UMR.
(5) Laporan pengelolaan risiko sebagaimana dimaksud pada ayat (3) huruf d untuk level Eselon II BNPB ditujukan kepada Sekretaris Utama c.q UMR.
(6) Laporan pengelolaan Risiko sebagaimana dimaksud pada ayat (3) huruf d disampaikan secara berkala setiap 6 (enam) bulan atau sewaktu-waktu jika diperlukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4774, '(1) Pemilik Risiko sebagaimana dimaksud dalam Pasal 7 ayat
(1) huruf a merupakan pejabat yang menanggungjawabi Proses Manajemen Risiko atas sasaran organisasi sesuai tugas dan fungsi organisasi atau unit kerja yang bersangkutan.
(2) Pemilik Risiko sebagaimana dimaksud pada ayat (1) terdiri atas:
a. pemilik Risiko untuk level entitas BNPB yaitu Kepala BNPB;
b. pemilik Risiko untuk level Eselon I BNPB yaitu Sekretaris Utama, Inspektur Utama, dan Deputi; dan
c. pemilik Risiko untuk level Eselon II BNPB yaitu Kepala Pusat.
(3) Pemilik Risiko sebagaimana dimaksud pada ayat (1) bertanggung jawab:
a. memastikan Risiko telah diidentifikasi, dinilai, dikelola, dan dipantau;
b. menentukan Selera Risiko yang tepat;
c. mengintegrasikan Manajemen Risiko ke dalam pencapaian kinerja dengan menetapkan dan mendelegasikan pelaksanaan rencana tindak pengendalian; dan
d. menyampaikan laporan pengelolaan Risiko yang disusun pengelola Risiko.
(4) Laporan pengelolaan Risiko sebagaimana dimaksud pada ayat (3) huruf d untuk level Eselon I BNPB ditujukan kepada Kepala BNPB dengan tembusan kepada UMR.
(5) Laporan pengelolaan risiko sebagaimana dimaksud pada ayat (3) huruf d untuk level Eselon II BNPB ditujukan kepada Sekretaris Utama c.q UMR.
(6) Laporan pengelolaan Risiko sebagaimana dimaksud pada ayat (3) huruf d disampaikan secara berkala setiap 6 (enam) bulan atau sewaktu-waktu jika diperlukan.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4775, 'perban-6-2024', 12, 'pasal', 'Pasal 9', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Ketiga Pembentukan Struktur Manajemen Risiko', 6, '(1) Pengelola Risiko sebagaimana dimaksud dalam Pasal 7 ayat (1) huruf b merupakan pejabat yang ditunjuk sebagai penanggung jawab Manajemen Risiko pada unit kerja masing-masing.
(2) Pengelola Risiko sebagaimana dimaksud pada ayat (1) terdiri atas:
a. pengelola Risiko level entitas BNPB yaitu Sekretaris Utama, Inspektur Utama dan Deputi;
b. pengelola Risiko level Eselon I BNPB yaitu Kepala Biro, Inspektur, dan Direktur; dan
c. pengelola Risiko level Eselon II BNPB yaitu pejabat pengawas atau pejabat fungsional setara pejabat pengawas yang memiliki tugas melakukan manajemen risiko atau urusan tata usaha, keuangan, kepegawaian, perlengkapan, arsip dan dokumentasi pada Pusat.
(3) Pengelola Risiko sebagaimana dimaksud pada ayat (1) bertanggung jawab untuk:
a. memfasilitasi dan mengadministrasikan proses identifikasi dan analisis Risiko dalam register dan peta Risiko;
b. mengadministrasikan kegiatan pengendalian dan pemantauan Risiko serta menuangkannya dalam rencana tindak pengendalian;
c. menyelenggarakan catatan historis atas peristiwa Risiko yang terjadi dan menuangkannya ke dalam laporan peristiwa Risiko; dan
d. melaporkan pelaksanaan Manajemen Risiko kepada pemilik Risiko.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4775, '(1) Pengelola Risiko sebagaimana dimaksud dalam Pasal 7 ayat (1) huruf b merupakan pejabat yang ditunjuk sebagai penanggung jawab Manajemen Risiko pada unit kerja masing-masing.
(2) Pengelola Risiko sebagaimana dimaksud pada ayat (1) terdiri atas:
a. pengelola Risiko level entitas BNPB yaitu Sekretaris Utama, Inspektur Utama dan Deputi;
b. pengelola Risiko level Eselon I BNPB yaitu Kepala Biro, Inspektur, dan Direktur; dan
c. pengelola Risiko level Eselon II BNPB yaitu pejabat pengawas atau pejabat fungsional setara pejabat pengawas yang memiliki tugas melakukan manajemen risiko atau urusan tata usaha, keuangan, kepegawaian, perlengkapan, arsip dan dokumentasi pada Pusat.
(3) Pengelola Risiko sebagaimana dimaksud pada ayat (1) bertanggung jawab untuk:
a. memfasilitasi dan mengadministrasikan proses identifikasi dan analisis Risiko dalam register dan peta Risiko;
b. mengadministrasikan kegiatan pengendalian dan pemantauan Risiko serta menuangkannya dalam rencana tindak pengendalian;
c. menyelenggarakan catatan historis atas peristiwa Risiko yang terjadi dan menuangkannya ke dalam laporan peristiwa Risiko; dan
d. melaporkan pelaksanaan Manajemen Risiko kepada pemilik Risiko.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4776, 'perban-6-2024', 13, 'pasal', 'Pasal 10', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Ketiga Pembentukan Struktur Manajemen Risiko', 6, '(1) UMR sebagaimana dimaksud dalam Pasal 7 ayat (2) merupakan unit penyelenggara Manajemen Risiko yang ditunjuk untuk mengoordinasikan Proses Manajemen Risiko.
(2) UMR sebagaimana dimaksud pada ayat (1) yakni unit kerja yang melaksanakan koordinasi organisasi dan tata laksana.
(3) UMR sebagaimana dimaksud pada ayat (1) memiliki tugas:
a. memantau penilaian Risiko dan rencana tindak pengendalian;
b. memantau pelaksanaan rencana tindak pengendalian;
c. memantau tindak lanjut hasil reviu atau audit atas Manajemen Risiko;
d. memberikan umpan balik berupa usulan/rekomendasi perbaikan pelaksanaan Manajemen Risiko oleh unit pemilik Risiko;
e. menyusun laporan triwulanan dan tahunan kegiatan pemantauan Manajemen Risiko;
f. memberikan sosialisasi terkait Manajemen Risiko kepada seluruh unit kerja di lingkungan BNPB; dan
g. memvalidasi usulan Risiko baru dari unit pemilik Risiko.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4776, '(1) UMR sebagaimana dimaksud dalam Pasal 7 ayat (2) merupakan unit penyelenggara Manajemen Risiko yang ditunjuk untuk mengoordinasikan Proses Manajemen Risiko.
(2) UMR sebagaimana dimaksud pada ayat (1) yakni unit kerja yang melaksanakan koordinasi organisasi dan tata laksana.
(3) UMR sebagaimana dimaksud pada ayat (1) memiliki tugas:
a. memantau penilaian Risiko dan rencana tindak pengendalian;
b. memantau pelaksanaan rencana tindak pengendalian;
c. memantau tindak lanjut hasil reviu atau audit atas Manajemen Risiko;
d. memberikan umpan balik berupa usulan/rekomendasi perbaikan pelaksanaan Manajemen Risiko oleh unit pemilik Risiko;
e. menyusun laporan triwulanan dan tahunan kegiatan pemantauan Manajemen Risiko;
f. memberikan sosialisasi terkait Manajemen Risiko kepada seluruh unit kerja di lingkungan BNPB; dan
g. memvalidasi usulan Risiko baru dari unit pemilik Risiko.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4777, 'perban-6-2024', 14, 'pasal', 'Pasal 11', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Keempat Perumusan dan Pelaksanaan Proses Manajemen Risiko', 7, '(1) Unit pengawas intern sebagaimana dimaksud dalam Pasal 7 ayat (3) merupakan APIP.
(2) Unit pengawas intern sebagaimana dimaksud pada ayat
(1) bertanggung jawab dalam rangka kegiatan pengawasan intern berbasis Risiko.
(3) Unit pengawas intern sebagaimana dimaksud pada ayat
(1) bertugas:
a. memberikan keyakinan bahwa Proses Manajemen Risiko telah sesuai dengan ketentuan peraturan perundang-undangan;
b. melakukan evaluasi Proses Manajemen Risiko;
c. melakukan evaluasi atas pelaporan Risiko Kunci;
d. melakukan reviu atas pengelolaan Risiko Kunci; dan
e. memberikan keyakinan bahwa Risiko telah dievaluasi secara tepat.
(4) Apabila diperlukan, unit pengawas intern sebagaimana dimaksud pada ayat (1) dapat memberikan:
a. fasilitasi identifikasi Risiko dan evaluasi Risiko; dan/atau
b. saran kepada pemilik Risiko dan pengelola Risiko dalam melakukan respons Risiko.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4777, '(1) Unit pengawas intern sebagaimana dimaksud dalam Pasal 7 ayat (3) merupakan APIP.
(2) Unit pengawas intern sebagaimana dimaksud pada ayat
(1) bertanggung jawab dalam rangka kegiatan pengawasan intern berbasis Risiko.
(3) Unit pengawas intern sebagaimana dimaksud pada ayat
(1) bertugas:
a. memberikan keyakinan bahwa Proses Manajemen Risiko telah sesuai dengan ketentuan peraturan perundang-undangan;
b. melakukan evaluasi Proses Manajemen Risiko;
c. melakukan evaluasi atas pelaporan Risiko Kunci;
d. melakukan reviu atas pengelolaan Risiko Kunci; dan
e. memberikan keyakinan bahwa Risiko telah dievaluasi secara tepat.
(4) Apabila diperlukan, unit pengawas intern sebagaimana dimaksud pada ayat (1) dapat memberikan:
a. fasilitasi identifikasi Risiko dan evaluasi Risiko; dan/atau
b. saran kepada pemilik Risiko dan pengelola Risiko dalam melakukan respons Risiko.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4778, 'perban-6-2024', 15, 'pasal', 'Pasal 12', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Keempat Perumusan dan Pelaksanaan Proses Manajemen Risiko', 7, '(1) Proses Manajemen Risiko sebagaimana dimaksud dalam Pasal 4 ayat (3) huruf c merupakan penerapan kebijakan, prosedur, dan praktik manajemen secara sistematis.
(2) Proses Manajemen Risiko sebagaimana dimaksud pada ayat (1) dilakukan oleh seluruh jajaran pejabat dan pegawai di lingkungan BNPB.
(3) Proses Manajemen Risiko sebagaimana dimaksud pada ayat (1) terdiri atas:
a. penetapan konteks;
b. identifikasi Risiko;
c. analisis Risiko;
d. evaluasi Risiko;
e. respons Risiko;
f. pemantauan; dan
g. informasi dan komunikasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4778, '(1) Proses Manajemen Risiko sebagaimana dimaksud dalam Pasal 4 ayat (3) huruf c merupakan penerapan kebijakan, prosedur, dan praktik manajemen secara sistematis.
(2) Proses Manajemen Risiko sebagaimana dimaksud pada ayat (1) dilakukan oleh seluruh jajaran pejabat dan pegawai di lingkungan BNPB.
(3) Proses Manajemen Risiko sebagaimana dimaksud pada ayat (1) terdiri atas:
a. penetapan konteks;
b. identifikasi Risiko;
c. analisis Risiko;
d. evaluasi Risiko;
e. respons Risiko;
f. pemantauan; dan
g. informasi dan komunikasi.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4779, 'perban-6-2024', 16, 'pasal', 'Pasal 13', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Keempat Perumusan dan Pelaksanaan Proses Manajemen Risiko', 8, '(1) Penetapan konteks sebagaimana dimaksud dalam Pasal 12 ayat (3) huruf a merupakan proses menentukan parameter internal dan eksternal untuk mengelola Risiko serta menentukan ruang lingkup kriteria Risiko.
(2) Penetapan konteks sebagaimana dimaksud pada ayat (1) dilakukan dengan cara:
a. mengidentifikasi identitas pemilik Risiko;
b. menentukan periode penerapan Manajemen Risiko;
c. mengidentifikasi keberlangsungan;
d. mengidentifikasi sasaran strategis dan/atau program;
e. mengidentifikasi proses bisnis;
f. mengidentifikasi pemangku kepentingan; dan/atau
g. mengidentifikasi Selera Risiko.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4779, '(1) Penetapan konteks sebagaimana dimaksud dalam Pasal 12 ayat (3) huruf a merupakan proses menentukan parameter internal dan eksternal untuk mengelola Risiko serta menentukan ruang lingkup kriteria Risiko.
(2) Penetapan konteks sebagaimana dimaksud pada ayat (1) dilakukan dengan cara:
a. mengidentifikasi identitas pemilik Risiko;
b. menentukan periode penerapan Manajemen Risiko;
c. mengidentifikasi keberlangsungan;
d. mengidentifikasi sasaran strategis dan/atau program;
e. mengidentifikasi proses bisnis;
f. mengidentifikasi pemangku kepentingan; dan/atau
g. mengidentifikasi Selera Risiko.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4780, 'perban-6-2024', 17, 'pasal', 'Pasal 14', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Keempat Perumusan dan Pelaksanaan Proses Manajemen Risiko', 8, '(1) Identifikasi Risiko sebagaimana dimaksud dalam Pasal 12 ayat (3) huruf b merupakan proses menetapkan Risiko.
(2) Identifikasi Risiko sebagaimana dimaksud pada ayat (1) dilakukan dengan mengidentifikasi dan menguraikan seluruh hal yang berpotensi Risiko baik yang berasal dari faktor internal maupun faktor eksternal.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4780, '(1) Identifikasi Risiko sebagaimana dimaksud dalam Pasal 12 ayat (3) huruf b merupakan proses menetapkan Risiko.
(2) Identifikasi Risiko sebagaimana dimaksud pada ayat (1) dilakukan dengan mengidentifikasi dan menguraikan seluruh hal yang berpotensi Risiko baik yang berasal dari faktor internal maupun faktor eksternal.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4781, 'perban-6-2024', 18, 'pasal', 'Pasal 15', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Keempat Perumusan dan Pelaksanaan Proses Manajemen Risiko', 8, '(1) Analisis Risiko sebagaimana dimaksud dalam Pasal 12 ayat (3) huruf c merupakan proses penilaian terhadap Risiko yang telah teridentifikasi dalam rangka untuk menetapkan peta Risiko.
(2) Analisis Risiko sebagaimana dimaksud pada ayat (1) dilakukan dengan tahapan:
a. menetapkan level Risiko;
b. memilah Risiko berdasarkan level; dan
c. menyusun peta Risiko.
(3) Penetapan level Risiko sebagaimana dimaksud pada ayat
(2) huruf a memperhatikan:
a. kriteria kemungkinan; dan
b. kriteria dampak.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4781, '(1) Analisis Risiko sebagaimana dimaksud dalam Pasal 12 ayat (3) huruf c merupakan proses penilaian terhadap Risiko yang telah teridentifikasi dalam rangka untuk menetapkan peta Risiko.
(2) Analisis Risiko sebagaimana dimaksud pada ayat (1) dilakukan dengan tahapan:
a. menetapkan level Risiko;
b. memilah Risiko berdasarkan level; dan
c. menyusun peta Risiko.
(3) Penetapan level Risiko sebagaimana dimaksud pada ayat
(2) huruf a memperhatikan:
a. kriteria kemungkinan; dan
b. kriteria dampak.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4782, 'perban-6-2024', 19, 'pasal', 'Pasal 16', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Keempat Perumusan dan Pelaksanaan Proses Manajemen Risiko', 8, '(1) Evaluasi Risiko sebagaimana dimaksud dalam Pasal 12 ayat (3) huruf d merupakan proses untuk menentukan daftar prioritas Risiko.
(2) Evaluasi Risiko sebagaimana dimaksud pada ayat (1) dilakukan dengan membandingkan antara peta Risiko dengan Selera Risiko.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4782, '(1) Evaluasi Risiko sebagaimana dimaksud dalam Pasal 12 ayat (3) huruf d merupakan proses untuk menentukan daftar prioritas Risiko.
(2) Evaluasi Risiko sebagaimana dimaksud pada ayat (1) dilakukan dengan membandingkan antara peta Risiko dengan Selera Risiko.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4783, 'perban-6-2024', 20, 'pasal', 'Pasal 17', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Keempat Perumusan dan Pelaksanaan Proses Manajemen Risiko', 9, '(1) Respons Risiko sebagaimana dimaksud dalam Pasal 12 ayat (3) huruf e merupakan proses merancang dan menetapkan rencana tindak pengendalian.
(2) Kegiatan sebagaimana dimaksud pada ayat (1) dilakukan dengan tahapan:
a. mengidentifikasi akar penyebab dari Risiko terpilih;
b. menyusun kegiatan pengendalian dengan mempertimbangkan akar penyebab Risiko;
c. menentukan indikator terlaksananya kegiatan pengendalian dan pihak yang melaksanakan kegiatan pengendalian;
d. menjadwalkan penanganan Risiko dengan urutan waktu berdasarkan peringkat level Risiko; dan
e. melakukan taksiran terhadap level Risiko (treated risk/nilai risiko jika direspons) setelah mempertimbangkan kegiatan pengendalian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4783, '(1) Respons Risiko sebagaimana dimaksud dalam Pasal 12 ayat (3) huruf e merupakan proses merancang dan menetapkan rencana tindak pengendalian.
(2) Kegiatan sebagaimana dimaksud pada ayat (1) dilakukan dengan tahapan:
a. mengidentifikasi akar penyebab dari Risiko terpilih;
b. menyusun kegiatan pengendalian dengan mempertimbangkan akar penyebab Risiko;
c. menentukan indikator terlaksananya kegiatan pengendalian dan pihak yang melaksanakan kegiatan pengendalian;
d. menjadwalkan penanganan Risiko dengan urutan waktu berdasarkan peringkat level Risiko; dan
e. melakukan taksiran terhadap level Risiko (treated risk/nilai risiko jika direspons) setelah mempertimbangkan kegiatan pengendalian.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4784, 'perban-6-2024', 21, 'pasal', 'Pasal 18', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Keempat Perumusan dan Pelaksanaan Proses Manajemen Risiko', 9, '(1) Pemantauan sebagaimana dimaksud dalam Pasal 12 ayat
(3) huruf f merupakan proses pengawasan yang dilakukan secara terus-menerus untuk memastikan setiap Proses Manajemen Risiko telah dilaksanakan.
(2) Pemantauan sebagaimana dimaksud pada ayat (1) dilakukan dengan cara:
a. memastikan penerapan Manajemen Risiko berjalan secara efektif sesuai dengan rencana; dan
b. memberikan umpan balik bagi penyempurnaan Proses Manajemen Risiko.
(3) Pemantauan sebagaimana dimaksud pada ayat (2) dilaksanakan 3 (tiga) lini Struktur Manajemen Risiko sesuai tugas dan tanggung jawabnya.
(4) Pemantauan dilaksanakan paling sedikit 1 (satu) kali setahun dan dituangkan dalam bentuk laporan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4784, '(1) Pemantauan sebagaimana dimaksud dalam Pasal 12 ayat
(3) huruf f merupakan proses pengawasan yang dilakukan secara terus-menerus untuk memastikan setiap Proses Manajemen Risiko telah dilaksanakan.
(2) Pemantauan sebagaimana dimaksud pada ayat (1) dilakukan dengan cara:
a. memastikan penerapan Manajemen Risiko berjalan secara efektif sesuai dengan rencana; dan
b. memberikan umpan balik bagi penyempurnaan Proses Manajemen Risiko.
(3) Pemantauan sebagaimana dimaksud pada ayat (2) dilaksanakan 3 (tiga) lini Struktur Manajemen Risiko sesuai tugas dan tanggung jawabnya.
(4) Pemantauan dilaksanakan paling sedikit 1 (satu) kali setahun dan dituangkan dalam bentuk laporan.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4785, 'perban-6-2024', 22, 'pasal', 'Pasal 19', 'BAB II PENERAPAN MANAJEMEN RISIKO; Bagian Keempat Perumusan dan Pelaksanaan Proses Manajemen Risiko', 9, '(1) Informasi dan komunikasi sebagaimana dimaksud dalam Pasal 12 ayat (3) huruf g merupakan proses penyediaan dan pemanfaatan sarana komunikasi untuk menunjang pelaksanaan Manajemen Risiko.
(2) Informasi dan komunikasi sebagaimana dimaksud pada ayat (1) dilakukan dengan cara:
a. rapat berkala;
b. dialog Risiko;
c. penggunaan sistem informasi; dan/atau
d. pelaporan berkala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4785, '(1) Informasi dan komunikasi sebagaimana dimaksud dalam Pasal 12 ayat (3) huruf g merupakan proses penyediaan dan pemanfaatan sarana komunikasi untuk menunjang pelaksanaan Manajemen Risiko.
(2) Informasi dan komunikasi sebagaimana dimaksud pada ayat (1) dilakukan dengan cara:
a. rapat berkala;
b. dialog Risiko;
c. penggunaan sistem informasi; dan/atau
d. pelaporan berkala.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4786, 'perban-6-2024', 23, 'pasal', 'Pasal 20', 'BAB III SISTEM INFORMASI MANAJEMEN RISIKO', 10, 'Petunjuk Pelaksanaan Penerapan Manajemen Risiko di Lingkungan BNPB ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4786, 'Petunjuk Pelaksanaan Penerapan Manajemen Risiko di Lingkungan BNPB ditetapkan oleh Kepala BNPB.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4787, 'perban-6-2024', 24, 'pasal', 'Pasal 21', 'BAB III SISTEM INFORMASI MANAJEMEN RISIKO', 10, '(1) Dalam rangka dukungan pelaksanaan Manajemen Risiko dapat dibentuk sistem informasi Manajemen Risiko.
(2) Sistem informasi sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai prinsip satu data.
(3) Sistem informasi Manajemen Risiko sebagaimana dimaksud pada ayat (1) dikelola oleh UMR.
(4) Pembangunan dan pengembangan sistem informasi sebagaimana dimaksud pada ayat (1) oleh unit kerja yang mempunyai tugas melaksanakan koordinasi dan pelayanan di bidang pengelolaan data dan informasi, dan pengembangan basis data dan informasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4787, '(1) Dalam rangka dukungan pelaksanaan Manajemen Risiko dapat dibentuk sistem informasi Manajemen Risiko.
(2) Sistem informasi sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai prinsip satu data.
(3) Sistem informasi Manajemen Risiko sebagaimana dimaksud pada ayat (1) dikelola oleh UMR.
(4) Pembangunan dan pengembangan sistem informasi sebagaimana dimaksud pada ayat (1) oleh unit kerja yang mempunyai tugas melaksanakan koordinasi dan pelayanan di bidang pengelolaan data dan informasi, dan pengembangan basis data dan informasi.', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4788, 'perban-6-2024', 25, 'pasal', 'Pasal 22', 'BAB IV KETENTUAN PENUTUP', 10, 'Sistem informasi Manajemen Risiko sebagaimana dimaksud dalam Pasal 21 dimanfaatkan untuk:
a. mendukung Budaya Sadar Risiko;
b. menjaga konsistensi penerapan kebijakan Manajemen Risiko;
c. menjaga kualitas data terkait Risiko; dan
d. mempercepat proses pelaporan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4788, 'Sistem informasi Manajemen Risiko sebagaimana dimaksud dalam Pasal 21 dimanfaatkan untuk:
a. mendukung Budaya Sadar Risiko;
b. menjaga konsistensi penerapan kebijakan Manajemen Risiko;
c. menjaga kualitas data terkait Risiko; dan
d. mempercepat proses pelaporan.', 'Pasal 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4789, 'perban-6-2024', 26, 'pasal', 'Pasal 23', 'BAB IV KETENTUAN PENUTUP', 10, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4789, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4790, 'perban-6-2024', 27, 'lain', 'Penutup', NULL, 11, 'Ditetapkan di Jakarta pada tanggal 24 Desember 2024 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2024 NOMOR Ж');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4790, 'Ditetapkan di Jakarta pada tanggal 24 Desember 2024 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2024 NOMOR Ж', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2024 tentang Manajemen Risiko di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4791, 'perban-6-2025', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4791, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4792, 'perban-6-2025', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk mewujudkan organisasi dan tata kerja yang efektif dan efisien guna meningkatkan kinerja pelaksanaan tugas dan fungsi Badan Nasional Penanggulangan Bencana, perlu melakukan penataan organisasi dan tata kerja Badan Nasional Penanggulangan Bencana;
b. bahwa penataan organisasi dan tata kerja Badan Nasional Penanggulangan Bencana telah mendapatkan persetujuan tertulis dari Menteri Pendayagunaan Aparatur Sipil Negara dan Reformasi Birokrasi;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b serta untuk melaksanakan Pasal 76 Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4792, 'a. bahwa untuk mewujudkan organisasi dan tata kerja yang efektif dan efisien guna meningkatkan kinerja pelaksanaan tugas dan fungsi Badan Nasional Penanggulangan Bencana, perlu melakukan penataan organisasi dan tata kerja Badan Nasional Penanggulangan Bencana;
b. bahwa penataan organisasi dan tata kerja Badan Nasional Penanggulangan Bencana telah mendapatkan persetujuan tertulis dari Menteri Pendayagunaan Aparatur Sipil Negara dan Reformasi Birokrasi;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b serta untuk melaksanakan Pasal 76 Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4793, 'perban-6-2025', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4793, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4794, 'perban-6-2025', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG ORGANISASI DAN TATA KERJA BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4794, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG ORGANISASI DAN TATA KERJA BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4795, 'perban-6-2025', 4, 'pasal', 'Pasal 1', 'BAB I KEDUDUKAN, TUGAS, DAN FUNGSI', 2, '(1) Badan Nasional Penanggulangan Bencana adalah lembaga pemerintah nonkementerian yang berada di bawah dan bertanggung jawab kepada Presiden.
(2) Badan Nasional Penanggulangan Bencana dipimpin oleh seorang Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4795, '(1) Badan Nasional Penanggulangan Bencana adalah lembaga pemerintah nonkementerian yang berada di bawah dan bertanggung jawab kepada Presiden.
(2) Badan Nasional Penanggulangan Bencana dipimpin oleh seorang Kepala.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4796, 'perban-6-2025', 5, 'pasal', 'Pasal 2', 'BAB I KEDUDUKAN, TUGAS, DAN FUNGSI', 2, 'Badan Nasional Penanggulangan Bencana mempunyai tugas:
a. memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana yang mencakup pencegahan bencana, penanganan keadaan darurat bencana, rehabilitasi, dan rekonstruksi secara adil dan setara;
b. menetapkan standarisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundang- undangan;
c. menyampaikan informasi kegiatan penanggulangan bencana kepada masyarakat;
d. melaporkan penyelenggaraan penanggulangan bencana kepada Presiden setiap sebulan sekali dalam kondisi normal dan setiap saat dalam kondisi darurat bencana;
e. menggunakan dan mempertanggungjawabkan sumbangan/bantuan nasional dan internasional;
f. mempertanggungjawabkan penggunaan anggaran yang diterima dari Anggaran Pendapatan dan Belanja Negara;
g. melaksanakan kewajiban lain sesuai dengan peraturan perundang-undangan; dan
h. menyusun pedoman pembentukan Badan Penanggulangan Bencana Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4796, 'Badan Nasional Penanggulangan Bencana mempunyai tugas:
a. memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana yang mencakup pencegahan bencana, penanganan keadaan darurat bencana, rehabilitasi, dan rekonstruksi secara adil dan setara;
b. menetapkan standarisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundang- undangan;
c. menyampaikan informasi kegiatan penanggulangan bencana kepada masyarakat;
d. melaporkan penyelenggaraan penanggulangan bencana kepada Presiden setiap sebulan sekali dalam kondisi normal dan setiap saat dalam kondisi darurat bencana;
e. menggunakan dan mempertanggungjawabkan sumbangan/bantuan nasional dan internasional;
f. mempertanggungjawabkan penggunaan anggaran yang diterima dari Anggaran Pendapatan dan Belanja Negara;
g. melaksanakan kewajiban lain sesuai dengan peraturan perundang-undangan; dan
h. menyusun pedoman pembentukan Badan Penanggulangan Bencana Daerah.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4797, 'perban-6-2025', 6, 'pasal', 'Pasal 3', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Pertama Susunan Organisasi', 2, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 2, Badan Nasional Penanggulangan Bencana menyelenggarakan fungsi:
a. perumusan dan penetapan kebijakan penanggulangan bencana dan penanganan pengungsi dengan bertindak cepat dan tepat serta efektif dan efisien; dan
b. pengoordinasian pelaksanaan kegiatan penanggulangan bencana secara terencana, terpadu, dan menyeluruh.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4797, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 2, Badan Nasional Penanggulangan Bencana menyelenggarakan fungsi:
a. perumusan dan penetapan kebijakan penanggulangan bencana dan penanganan pengungsi dengan bertindak cepat dan tepat serta efektif dan efisien; dan
b. pengoordinasian pelaksanaan kegiatan penanggulangan bencana secara terencana, terpadu, dan menyeluruh.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4798, 'perban-6-2025', 7, 'pasal', 'Pasal 4', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Kedua Kepala', 3, 'Badan Nasional Penanggulangan Bencana terdiri atas:
a. Kepala;
b. unsur pengarah; dan
c. unsur pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4798, 'Badan Nasional Penanggulangan Bencana terdiri atas:
a. Kepala;
b. unsur pengarah; dan
c. unsur pelaksana.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4799, 'perban-6-2025', 8, 'pasal', 'Pasal 5', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Ketiga Unsur Pengarah', 3, 'Kepala mempunyai tugas memimpin Badan Nasional Penanggulangan Bencana dalam menjalankan tugas dan fungsi Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4799, 'Kepala mempunyai tugas memimpin Badan Nasional Penanggulangan Bencana dalam menjalankan tugas dan fungsi Badan Nasional Penanggulangan Bencana.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4800, 'perban-6-2025', 9, 'pasal', 'Pasal 6', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Ketiga Unsur Pengarah', 3, 'Unsur pengarah berada di bawah dan bertanggung jawab kepada Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4800, 'Unsur pengarah berada di bawah dan bertanggung jawab kepada Kepala.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4801, 'perban-6-2025', 10, 'pasal', 'Pasal 7', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Ketiga Unsur Pengarah', 3, 'Unsur pengarah mempunyai tugas memberikan masukan dan saran kepada Kepala dalam penyelenggaraan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4801, 'Unsur pengarah mempunyai tugas memberikan masukan dan saran kepada Kepala dalam penyelenggaraan penanggulangan bencana.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4802, 'perban-6-2025', 11, 'pasal', 'Pasal 8', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Ketiga Unsur Pengarah', 3, 'Unsur pengarah menyelenggarakan fungsi:
a. perumusan konsep kebijakan penanggulangan bencana nasional;
b. pemantauan; dan
c. evaluasi dalam penyelenggaraan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4802, 'Unsur pengarah menyelenggarakan fungsi:
a. perumusan konsep kebijakan penanggulangan bencana nasional;
b. pemantauan; dan
c. evaluasi dalam penyelenggaraan penanggulangan bencana.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4803, 'perban-6-2025', 12, 'pasal', 'Pasal 9', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Ketiga Unsur Pengarah', 3, 'Unsur pengarah terdiri atas Ketua yang dijabat oleh Kepala dan 20 (dua puluh) Anggota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4803, 'Unsur pengarah terdiri atas Ketua yang dijabat oleh Kepala dan 20 (dua puluh) Anggota.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4804, 'perban-6-2025', 13, 'pasal', 'Pasal 10', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 3, '(1) Anggota unsur pengarah terdiri atas:
a. 11 (sebelas) pejabat eselon I.a dan eselon I.b atau setara pejabat tinggi madya, yang diusulkan oleh Pimpinan Instansi Pemerintah; dan
b. 9 (sembilan) Anggota masyarakat profesional.
(2) Pejabat Pemerintah sebagaimana dimaksud pada ayat
(1) huruf a mewakili:
a. Kementerian Koordinator Bidang Pembangunan Manusia dan Kebudayaan;
b. Kementerian Koordinator Bidang Politik dan Keamanan;
c. Kementerian Dalam Negeri;
d. Kementerian Keuangan;
e. Kementerian Kesehatan;
f. Kementerian Sosial;
g. Kementerian Energi dan Sumber Daya Mineral;
h. Kementerian Pekerjaan Umum;
i. Kementerian Perhubungan;
j. Kepolisian Negara Republik Indonesia; dan
k. Tentara Nasional Indonesia.
(3) Unsur pengarah yang berasal dari masyarakat profesional sebagaimana dimaksud pada ayat (1) huruf b, berasal dari para pakar/profesional dan/atau tokoh masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4804, '(1) Anggota unsur pengarah terdiri atas:
a. 11 (sebelas) pejabat eselon I.a dan eselon I.b atau setara pejabat tinggi madya, yang diusulkan oleh Pimpinan Instansi Pemerintah; dan
b. 9 (sembilan) Anggota masyarakat profesional.
(2) Pejabat Pemerintah sebagaimana dimaksud pada ayat
(1) huruf a mewakili:
a. Kementerian Koordinator Bidang Pembangunan Manusia dan Kebudayaan;
b. Kementerian Koordinator Bidang Politik dan Keamanan;
c. Kementerian Dalam Negeri;
d. Kementerian Keuangan;
e. Kementerian Kesehatan;
f. Kementerian Sosial;
g. Kementerian Energi dan Sumber Daya Mineral;
h. Kementerian Pekerjaan Umum;
i. Kementerian Perhubungan;
j. Kepolisian Negara Republik Indonesia; dan
k. Tentara Nasional Indonesia.
(3) Unsur pengarah yang berasal dari masyarakat profesional sebagaimana dimaksud pada ayat (1) huruf b, berasal dari para pakar/profesional dan/atau tokoh masyarakat.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4805, 'perban-6-2025', 14, 'pasal', 'Pasal 11', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 4, 'Unsur pelaksana berada di bawah dan bertanggung jawab kepada Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4805, 'Unsur pelaksana berada di bawah dan bertanggung jawab kepada Kepala.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4806, 'perban-6-2025', 15, 'pasal', 'Pasal 12', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 4, 'Unsur pelaksana mempunyai tugas melaksanakan penanggulangan bencana secara terintegrasi yang meliputi prabencana, saat keadaan darurat bencana, dan pascabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4806, 'Unsur pelaksana mempunyai tugas melaksanakan penanggulangan bencana secara terintegrasi yang meliputi prabencana, saat keadaan darurat bencana, dan pascabencana.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4807, 'perban-6-2025', 16, 'pasal', 'Pasal 13', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 4, 'Tugas sebagaimana dimaksud dalam Pasal 12, meliputi:
a. penyusunan kebijakan di bidang penanggulangan bencana;
b. pelaksanaan kebijakan di bidang penanggulangan bencana;
c. penyusunan, perumusan, dan penetapan norma, standar, kriteria, dan prosedur di bidang penanggulangan bencana;
d. pemberian bimbingan teknis dan supervisi di bidang penanggulangan bencana;
e. pengoordinasian instansi pemerintah terkait, pemerintah daerah, masyarakat, dan lembaga usaha serta lembaga internasional dalam rangka penyusunan dan perumusan serta pelaksanaan kebijakan teknis di bidang penanggulangan bencana;
f. koordinasi pelaksanaan fungsi, pembinaan, dan pemberian dukungan administrasi kepada seluruh unsur organisasi di lingkungan Badan Nasional Penanggulangan Bencana;
g. pengelolaan barang milik/kekayaan negara yang menjadi tanggung jawab Badan Nasional Penanggulangan Bencana;
h. pengawasan atas pelaksanaan fungsi di lingkungan Badan Nasional Penanggulangan Bencana; dan
i. pelaksanaan dukungan yang bersifat substantif kepada seluruh unsur organisasi di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4807, 'Tugas sebagaimana dimaksud dalam Pasal 12, meliputi:
a. penyusunan kebijakan di bidang penanggulangan bencana;
b. pelaksanaan kebijakan di bidang penanggulangan bencana;
c. penyusunan, perumusan, dan penetapan norma, standar, kriteria, dan prosedur di bidang penanggulangan bencana;
d. pemberian bimbingan teknis dan supervisi di bidang penanggulangan bencana;
e. pengoordinasian instansi pemerintah terkait, pemerintah daerah, masyarakat, dan lembaga usaha serta lembaga internasional dalam rangka penyusunan dan perumusan serta pelaksanaan kebijakan teknis di bidang penanggulangan bencana;
f. koordinasi pelaksanaan fungsi, pembinaan, dan pemberian dukungan administrasi kepada seluruh unsur organisasi di lingkungan Badan Nasional Penanggulangan Bencana;
g. pengelolaan barang milik/kekayaan negara yang menjadi tanggung jawab Badan Nasional Penanggulangan Bencana;
h. pengawasan atas pelaksanaan fungsi di lingkungan Badan Nasional Penanggulangan Bencana; dan
i. pelaksanaan dukungan yang bersifat substantif kepada seluruh unsur organisasi di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4808, 'perban-6-2025', 17, 'pasal', 'Pasal 14', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 5, 'Dalam menyelenggarakan tugas sebagaimana dimaksud dalam Pasal 13, unsur pelaksana mempunyai fungsi:
a. koordinasi penyelenggaraan penanggulangan bencana;
b. komando penyelenggaraan penanggulangan bencana; dan
c. pelaksana dalam penyelenggaraan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4808, 'Dalam menyelenggarakan tugas sebagaimana dimaksud dalam Pasal 13, unsur pelaksana mempunyai fungsi:
a. koordinasi penyelenggaraan penanggulangan bencana;
b. komando penyelenggaraan penanggulangan bencana; dan
c. pelaksana dalam penyelenggaraan penanggulangan bencana.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4809, 'perban-6-2025', 18, 'pasal', 'Pasal 15', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 5, '(1) Fungsi koordinasi sebagaimana dimaksud dalam Pasal 14 huruf a dilaksanakan pada tahap prabencana dan pascabencana.
(2) Fungsi koordinasi unsur pelaksana dilaksanakan melalui koordinasi dengan instansi pemerintah baik pusat maupun daerah, masyarakat, lembaga usaha, lembaga internasional dan/atau pihak lain yang dipandang perlu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4809, '(1) Fungsi koordinasi sebagaimana dimaksud dalam Pasal 14 huruf a dilaksanakan pada tahap prabencana dan pascabencana.
(2) Fungsi koordinasi unsur pelaksana dilaksanakan melalui koordinasi dengan instansi pemerintah baik pusat maupun daerah, masyarakat, lembaga usaha, lembaga internasional dan/atau pihak lain yang dipandang perlu.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4810, 'perban-6-2025', 19, 'pasal', 'Pasal 16', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 5, '(1) Fungsi komando sebagaimana dimaksud dalam Pasal 14 huruf b unsur pelaksana dilaksanakan melalui pengerahan sumber daya manusia, logistik dan peralatan dari instansi terkait, Kepolisian Negara Republik Indonesia, dan Tentara Nasional Indonesia serta langkah lain yang diperlukan dalam rangka penanganan darurat bencana.
(2) Pelaksanaan ketentuan sebagaimana dimaksud pada ayat (1) dilakukan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4810, '(1) Fungsi komando sebagaimana dimaksud dalam Pasal 14 huruf b unsur pelaksana dilaksanakan melalui pengerahan sumber daya manusia, logistik dan peralatan dari instansi terkait, Kepolisian Negara Republik Indonesia, dan Tentara Nasional Indonesia serta langkah lain yang diperlukan dalam rangka penanganan darurat bencana.
(2) Pelaksanaan ketentuan sebagaimana dimaksud pada ayat (1) dilakukan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4811, 'perban-6-2025', 20, 'pasal', 'Pasal 17', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 5, 'Fungsi pelaksanaan pada unsur pelaksana sebagaimana dimaksud dalam Pasal 14 huruf c dilaksanakan secara terkoordinasi dan terintegrasi dengan instansi pemerintah baik pusat maupun daerah, Kepolisian Negara Republik Indonesia dan Tentara Nasional Indonesia dengan memperhatikan kebijakan penyelenggaraan penanggulangan bencana dan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4811, 'Fungsi pelaksanaan pada unsur pelaksana sebagaimana dimaksud dalam Pasal 14 huruf c dilaksanakan secara terkoordinasi dan terintegrasi dengan instansi pemerintah baik pusat maupun daerah, Kepolisian Negara Republik Indonesia dan Tentara Nasional Indonesia dengan memperhatikan kebijakan penyelenggaraan penanggulangan bencana dan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4812, 'perban-6-2025', 21, 'pasal', 'Pasal 18', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 5, 'Dalam melaksanakan tugas dan fungsi sebagaimana dimaksud dalam Pasal 13 dan Pasal 14, Badan Nasional Penanggulangan Bencana dikoordinasikan oleh kementerian yang menyelenggarakan sinkronisasi dan koordinasi, serta pengendalian pelaksanaan urusan kementerian dalam penyelenggaraan pemerintahan di bidang pembangunan manusia dan kebudayaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4812, 'Dalam melaksanakan tugas dan fungsi sebagaimana dimaksud dalam Pasal 13 dan Pasal 14, Badan Nasional Penanggulangan Bencana dikoordinasikan oleh kementerian yang menyelenggarakan sinkronisasi dan koordinasi, serta pengendalian pelaksanaan urusan kementerian dalam penyelenggaraan pemerintahan di bidang pembangunan manusia dan kebudayaan.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4813, 'perban-6-2025', 22, 'pasal', 'Pasal 19', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 6, '(1) Susunan Organisasi unsur pelaksana terdiri atas:
a. Sekretariat Utama;
b. Deputi Bidang Sistem dan Strategi;
c. Deputi Bidang Pencegahan;
d. Deputi Bidang Penanganan Darurat;
e. Deputi Bidang Rehabilitasi dan Rekonstruksi;
f. Deputi Bidang Logistik dan Peralatan; dan
g. Inspektorat Utama.
(2) Bagan susunan organisasi di lingkungan Badan Nasional Penanggulangan Bencana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4813, '(1) Susunan Organisasi unsur pelaksana terdiri atas:
a. Sekretariat Utama;
b. Deputi Bidang Sistem dan Strategi;
c. Deputi Bidang Pencegahan;
d. Deputi Bidang Penanganan Darurat;
e. Deputi Bidang Rehabilitasi dan Rekonstruksi;
f. Deputi Bidang Logistik dan Peralatan; dan
g. Inspektorat Utama.
(2) Bagan susunan organisasi di lingkungan Badan Nasional Penanggulangan Bencana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4814, 'perban-6-2025', 23, 'pasal', 'Pasal 20', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 6, '(1) Sekretariat Utama berada di bawah dan bertanggung jawab kepada Kepala.
(2) Sekretariat Utama dipimpin oleh Sekretaris Utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4814, '(1) Sekretariat Utama berada di bawah dan bertanggung jawab kepada Kepala.
(2) Sekretariat Utama dipimpin oleh Sekretaris Utama.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4815, 'perban-6-2025', 24, 'pasal', 'Pasal 21', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 6, 'Sekretariat Utama mempunyai tugas pembinaan, dan pemberian dukungan administrasi kepada seluruh unsur organisasi di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4815, 'Sekretariat Utama mempunyai tugas pembinaan, dan pemberian dukungan administrasi kepada seluruh unsur organisasi di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4816, 'perban-6-2025', 25, 'pasal', 'Pasal 22', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 6, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 21, Sekretariat Utama menyelenggarakan fungsi:
a. koordinasi kegiatan Badan Nasional Penanggulangan Bencana;
b. koordinasi dan penyusunan rencana, program dan anggaran Badan Nasional Penanggulangan Bencana;
c. pembinaan dan pemberian dukungan administrasi yang meliputi ketatausahaan, kepegawaian, keuangan, persandian, kerumahtanggaan, kerja sama, hubungan masyarakat, arsip, dan dokumentasi Badan Nasional Penanggulangan Bencana;
d. pembinaan dan penataan organisasi dan tata laksana;
e. koordinasi dan penyusunan peraturan perundang-undangan serta pelaksanaan advokasi hukum;
f. penyelenggaraan pengelolaan barang milik/kekayaan negara; dan
g. pelaksanaan fungsi lain yang diberikan oleh Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4816, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 21, Sekretariat Utama menyelenggarakan fungsi:
a. koordinasi kegiatan Badan Nasional Penanggulangan Bencana;
b. koordinasi dan penyusunan rencana, program dan anggaran Badan Nasional Penanggulangan Bencana;
c. pembinaan dan pemberian dukungan administrasi yang meliputi ketatausahaan, kepegawaian, keuangan, persandian, kerumahtanggaan, kerja sama, hubungan masyarakat, arsip, dan dokumentasi Badan Nasional Penanggulangan Bencana;
d. pembinaan dan penataan organisasi dan tata laksana;
e. koordinasi dan penyusunan peraturan perundang-undangan serta pelaksanaan advokasi hukum;
f. penyelenggaraan pengelolaan barang milik/kekayaan negara; dan
g. pelaksanaan fungsi lain yang diberikan oleh Kepala.', 'Pasal 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4817, 'perban-6-2025', 26, 'pasal', 'Pasal 23', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 6, 'Sekretariat Utama terdiri atas:
a. Biro Perencanaan;
b. Biro Keuangan;
c. Biro Sumber Daya Manusia dan Umum; dan
d. Biro Hukum, Organisasi dan Kerja Sama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4817, 'Sekretariat Utama terdiri atas:
a. Biro Perencanaan;
b. Biro Keuangan;
c. Biro Sumber Daya Manusia dan Umum; dan
d. Biro Hukum, Organisasi dan Kerja Sama.', 'Pasal 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4818, 'perban-6-2025', 27, 'pasal', 'Pasal 24', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 7, 'Biro Perencanaan mempunyai tugas melaksanakan koordinasi penyusunan program dan anggaran yang bersumber dari anggaran pendapatan dan belanja negara dan nonanggaran pendapatan dan belanja negara luar negeri dan dalam negeri, serta pemantauan, evaluasi, dan penyusunan laporan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4818, 'Biro Perencanaan mempunyai tugas melaksanakan koordinasi penyusunan program dan anggaran yang bersumber dari anggaran pendapatan dan belanja negara dan nonanggaran pendapatan dan belanja negara luar negeri dan dalam negeri, serta pemantauan, evaluasi, dan penyusunan laporan Badan Nasional Penanggulangan Bencana.', 'Pasal 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4819, 'perban-6-2025', 28, 'pasal', 'Pasal 25', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 7, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 24, Biro Perencanaan menyelenggarakan fungsi:
a. penyusunan program dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara;
b. penyusunan program dan anggaran yang bersumber dari nonAnggaran Pendapatan dan Belanja Negara luar negeri dan dalam negeri; dan
c. pelaksanaan pemantauan, evaluasi, dan penyusunan pelaporan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4819, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 24, Biro Perencanaan menyelenggarakan fungsi:
a. penyusunan program dan anggaran yang bersumber dari Anggaran Pendapatan dan Belanja Negara;
b. penyusunan program dan anggaran yang bersumber dari nonAnggaran Pendapatan dan Belanja Negara luar negeri dan dalam negeri; dan
c. pelaksanaan pemantauan, evaluasi, dan penyusunan pelaporan Badan Nasional Penanggulangan Bencana.', 'Pasal 25', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4820, 'perban-6-2025', 29, 'pasal', 'Pasal 26', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 7, 'Biro Perencanaan terdiri atas jabatan fungsional dan jabatan pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4820, 'Biro Perencanaan terdiri atas jabatan fungsional dan jabatan pelaksana.', 'Pasal 26', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4821, 'perban-6-2025', 30, 'pasal', 'Pasal 27', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 7, 'Biro Keuangan mempunyai tugas melaksanakan koordinasi, pengelolaan, dan pelaksanaan anggaran di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4821, 'Biro Keuangan mempunyai tugas melaksanakan koordinasi, pengelolaan, dan pelaksanaan anggaran di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4822, 'perban-6-2025', 31, 'pasal', 'Pasal 28', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 7, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 27, Biro Keuangan menyelenggarakan fungsi:
a. penyiapan koordinasi pelaksanaan Anggaran Pendapatan dan Belanja Negara;
b. pelaksanaan pengeluaran keuangan;
c. pelaksanaan urusan perbendaharaan, penyelesaian kerugian negara, dan pembinaan penatausahaan administrasi keuangan;
d. pelaksanaan koordinasi pembinaan penatausahaan Penerimaan Negara Bukan Pajak; dan
e. pelaksanaan verifikasi dan akuntansi anggaran serta penyusunan laporan keuangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4822, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 27, Biro Keuangan menyelenggarakan fungsi:
a. penyiapan koordinasi pelaksanaan Anggaran Pendapatan dan Belanja Negara;
b. pelaksanaan pengeluaran keuangan;
c. pelaksanaan urusan perbendaharaan, penyelesaian kerugian negara, dan pembinaan penatausahaan administrasi keuangan;
d. pelaksanaan koordinasi pembinaan penatausahaan Penerimaan Negara Bukan Pajak; dan
e. pelaksanaan verifikasi dan akuntansi anggaran serta penyusunan laporan keuangan.', 'Pasal 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4823, 'perban-6-2025', 32, 'pasal', 'Pasal 29', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 7, 'Biro Keuangan terdiri atas jabatan fungsional dan jabatan pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4823, 'Biro Keuangan terdiri atas jabatan fungsional dan jabatan pelaksana.', 'Pasal 29', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4824, 'perban-6-2025', 33, 'pasal', 'Pasal 30', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 7, 'Biro Sumber Daya Manusia dan Umum mempunyai tugas melaksanakan koordinasi urusan sumber daya manusia, rumah tangga, tata usaha, keprotokolan, barang milik/kekayaan negara, dan layanan pengadaan barang/jasa di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4824, 'Biro Sumber Daya Manusia dan Umum mempunyai tugas melaksanakan koordinasi urusan sumber daya manusia, rumah tangga, tata usaha, keprotokolan, barang milik/kekayaan negara, dan layanan pengadaan barang/jasa di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 30', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4825, 'perban-6-2025', 34, 'pasal', 'Pasal 31', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 8, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 30, Biro Sumber Daya Manusia dan Umum menyelenggarakan fungsi:
a. penyiapan koordinasi pelaksanaan urusan sumber daya manusia;
b. penyiapan koordinasi pelaksanaan urusan rumah tangga, perlengkapan, barang milik/kekayaan Negara;
c. penyiapan koordinasi dan pengelolaan layanan pengadaan barang/jasa di lingkungan Badan Nasional Penanggulangan Bencana; dan
d. penyiapan koordinasi pelaksanaan urusan tata usaha, kearsipan, dan protokol.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4825, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 30, Biro Sumber Daya Manusia dan Umum menyelenggarakan fungsi:
a. penyiapan koordinasi pelaksanaan urusan sumber daya manusia;
b. penyiapan koordinasi pelaksanaan urusan rumah tangga, perlengkapan, barang milik/kekayaan Negara;
c. penyiapan koordinasi dan pengelolaan layanan pengadaan barang/jasa di lingkungan Badan Nasional Penanggulangan Bencana; dan
d. penyiapan koordinasi pelaksanaan urusan tata usaha, kearsipan, dan protokol.', 'Pasal 31', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4826, 'perban-6-2025', 35, 'pasal', 'Pasal 32', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 8, 'Biro Sumber Daya Manusia dan Umum terdiri atas:
