INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4827, 'perban-6-2025', 36, 'pasal', 'Pasal 33', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 8, 'Bagian Rumah Tangga mempunyai tugas melaksanakan penyiapan koordinasi urusan rumah tangga, barang milik/kekayaan Negara, perlengkapan, dan layanan pengadaan barang/jasa di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4827, 'Bagian Rumah Tangga mempunyai tugas melaksanakan penyiapan koordinasi urusan rumah tangga, barang milik/kekayaan Negara, perlengkapan, dan layanan pengadaan barang/jasa di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 33', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4828, 'perban-6-2025', 37, 'pasal', 'Pasal 34', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 8, '(1) Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 33, Bagian Rumah Tangga menyelenggarakan fungsi:
a. pelaksanaan urusan rumah tangga, perlengkapan, dan barang milik/kekayaan Negara; dan
b. pelaksanaan pengelolaan pengadaan barang dan jasa pemerintah, layanan pengadaan secara elektronik, koordinasi identifikasi kebutuhan dan pengembangan kompetensi sumber daya manusia pengadaan barang dan jasa, koordinasi peningkatan kapabilitas kelembagaan pengadaan barang dan jasa, layanan pendampingan dan konsultasi pengadaan barang dan jasa, dan koordinasi bimbingan teknis pengadaan barang dan jasa.
(2) Selain menyelenggaraan fungsi sebagaimana dimaksud pada ayat (1) huruf b, dalam pelaksanaan tugas sebagai unit organisasi pengadaan barang/jasa berdasarkan peraturan perundang-undangan, Bagian Rumah Tangga juga menyelenggarakan fungsi:
a. pengelolaan pengadaan barang/jasa;
b. pengelolaan layanan pengadaan secara elektronik;
c. pembinaan sumber daya manusia dan kelembagaan pengadaan barang/jasa; dan
d. pelaksanaan pendampingan, konsultasi, dan/atau bimbingan teknis pengadaan barang/jasa.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4828, '(1) Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 33, Bagian Rumah Tangga menyelenggarakan fungsi:
