INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4834, 'perban-6-2025', 43, 'pasal', 'Pasal 40', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 9, '(1) Subbagian Tata Usaha Pimpinan dan Protokol mempunyai tugas melakukan urusan tata usaha dan protokol Kepala.
