INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4837, 'perban-6-2025', 46, 'pasal', 'Pasal 43', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 10, 'Biro Hukum, Organisasi dan Kerja Sama terdiri atas jabatan fungsional dan jabatan pelaksana.');
