INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4838, 'perban-6-2025', 47, 'pasal', 'Pasal 44', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 10, 'Deputi Bidang Sistem dan Strategi mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan di bidang sistem dan strategi penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4838, 'Deputi Bidang Sistem dan Strategi mempunyai tugas menyelenggarakan perumusan dan pelaksanaan kebijakan di bidang sistem dan strategi penanggulangan bencana.', 'Pasal 44', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4839, 'perban-6-2025', 48, 'pasal', 'Pasal 45', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 10, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 43, Deputi Bidang Sistem dan Strategi menyelenggarakan fungsi:
a. penyusunan kebijakan teknis di bidang sistem dan strategi;
