INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4840, 'perban-6-2025', 49, 'pasal', 'Pasal 46', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 11, 'Deputi Bidang Sistem dan Strategi terdiri atas:
