INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4841, 'perban-6-2025', 50, 'pasal', 'Pasal 47', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 11, 'Direktorat Pemetaan dan Evaluasi Risiko Bencana mempunyai tugas merumuskan dan melaksanakan koordinasi, penyusunan kebijakan teknis, hubungan kerja, rencana dan pelaksanaan serta pemantauan, evaluasi dan analisis pelaporan pada lingkup sistem dan strategi kebencanaan melalui pemetaan dan evaluasi risiko bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4841, 'Direktorat Pemetaan dan Evaluasi Risiko Bencana mempunyai tugas merumuskan dan melaksanakan koordinasi, penyusunan kebijakan teknis, hubungan kerja, rencana dan pelaksanaan serta pemantauan, evaluasi dan analisis pelaporan pada lingkup sistem dan strategi kebencanaan melalui pemetaan dan evaluasi risiko bencana.', 'Pasal 47', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
