INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4905, 'perban-6-2025', 114, 'pasal', 'Pasal 111', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 23, 'Bagian Tata Usaha mempunyai tugas menyelenggarakan dan mengoordinasikan dukungan tata usaha untuk kelancaran tugas dan fungsi Inspektorat Utama serta melaporkan pelaksanaan tugas kepada Inspektur Utama.');
