INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4906, 'perban-6-2025', 115, 'pasal', 'Pasal 112', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 24, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 111, Bagian Tata Usaha menyelenggarakan fungsi:
