INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4907, 'perban-6-2025', 116, 'pasal', 'Pasal 113', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 24, 'Pusat Data, Informasi, dan Komunikasi Kebencanaan mempunyai tugas melaksanakan koordinasi dan pelayanan di bidang pengelolaan data dan informasi, pengembangan basis data dan informasi, dan pelaksanaan komunikasi kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4907, 'Pusat Data, Informasi, dan Komunikasi Kebencanaan mempunyai tugas melaksanakan koordinasi dan pelayanan di bidang pengelolaan data dan informasi, pengembangan basis data dan informasi, dan pelaksanaan komunikasi kebencanaan.', 'Pasal 113', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4908, 'perban-6-2025', 117, 'pasal', 'Pasal 114', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 24, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 113, Pusat Data, Informasi, dan Komunikasi Kebencanaan menyelenggarakan fungsi:
a. penyiapan penyusunan dan pelaksanaan kebijakan teknis di bidang data, informasi dan komunikasi kebencanaan;
b. penyiapan koordinasi penyusunan norma, standar, prosedur dan kriteria di bidang data, informasi, dan komunikasi kebencanaan;
c. pengelolaan, pengembangan, dan pengintegrasian teknologi dan jaringan di lingkungan Badan Nasional Penanggulangan Bencana;
d. penyiapan komunikasi dengan media, pemberitaan, peliputan, publikasi serta pengelolaan dokumentasi penanggulangan bencana;
e. pengelolaan perpustakaan dan pelaksanaan digitalisasi dokumen kebencanaan di bidang penanggulangan bencana; dan
f. pemantauan, evaluasi dan analisis laporan pengelolaan data, informasi dan komunikasi kebencanaan.');
