INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4912, 'perban-6-2025', 121, 'pasal', 'Pasal 118', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 25, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 117, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana menyelenggarakan fungsi:
