INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4914, 'Subbagian Tata Usaha mempunyai tugas melakukan urusan tata usaha, keuangan, kepegawaian, perlengkapan, arsip, dan dokumentasi.', 'Pasal 120', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4915, 'perban-6-2025', 124, 'pasal', 'Pasal 121', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 25, 'Pusat Pengendalian Operasi mempunyai tugas melaksanakan koordinasi, penyiapan, pengolahan data dan analisis pemantauan potensi ancaman bencana, pengerahan sumber daya, diseminasi informasi, pelaksanaan komunikasi kedaruratan dan rekomendasi operasi penanganan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4915, 'Pusat Pengendalian Operasi mempunyai tugas melaksanakan koordinasi, penyiapan, pengolahan data dan analisis pemantauan potensi ancaman bencana, pengerahan sumber daya, diseminasi informasi, pelaksanaan komunikasi kedaruratan dan rekomendasi operasi penanganan darurat bencana.', 'Pasal 121', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4916, 'perban-6-2025', 125, 'pasal', 'Pasal 122', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 26, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 121, Pusat Pengendalian Operasi menyelenggarakan fungsi:
a. pengolahan data, analisis dan diseminasi informasi darurat bencana;
b. penyiapan koordinasi penyusunan norma, standar, prosedur dan kriteria di bidang pengendalian operasi penanganan darurat bencana;
c. penyusunan rencana operasi penanganan pada saat siaga darurat, tanggap darurat, dan transisi darurat ke pemulihan;
d. penyusunan rekomendasi operasi penanganan darurat bencana; dan
e. penyusunan koordinasi, komunikasi dan sinkronisasi penanggulangan bencana lintas sektor.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4916, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 121, Pusat Pengendalian Operasi menyelenggarakan fungsi:
a. pengolahan data, analisis dan diseminasi informasi darurat bencana;
b. penyiapan koordinasi penyusunan norma, standar, prosedur dan kriteria di bidang pengendalian operasi penanganan darurat bencana;
c. penyusunan rencana operasi penanganan pada saat siaga darurat, tanggap darurat, dan transisi darurat ke pemulihan;
d. penyusunan rekomendasi operasi penanganan darurat bencana; dan
e. penyusunan koordinasi, komunikasi dan sinkronisasi penanggulangan bencana lintas sektor.', 'Pasal 122', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4917, 'perban-6-2025', 126, 'pasal', 'Pasal 123', 'BAB II ORGANISASI BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Unsur Pelaksana', 26, 'Pusat Pengendalian Operasi Penanggulangan Bencana terdiri atas:
a. Subbagian Tata Usaha; dan
b. jabatan fungsional dan jabatan pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4917, 'Pusat Pengendalian Operasi Penanggulangan Bencana terdiri atas:
a. Subbagian Tata Usaha; dan
b. jabatan fungsional dan jabatan pelaksana.', 'Pasal 123', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4918, 'perban-6-2025', 127, 'pasal', 'Pasal 124', 'BAB III JABATAN FUNGSIONAL DAN JABATAN PELAKSANA', 26, 'Subbagian Tata Usaha mempunyai tugas melakukan urusan tata usaha, keuangan, kepegawaian, perlengkapan, arsip, dan dokumentasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4918, 'Subbagian Tata Usaha mempunyai tugas melakukan urusan tata usaha, keuangan, kepegawaian, perlengkapan, arsip, dan dokumentasi.', 'Pasal 124', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4919, 'perban-6-2025', 128, 'pasal', 'Pasal 125', 'BAB III JABATAN FUNGSIONAL DAN JABATAN PELAKSANA', 26, 'Jabatan fungsional dan jabatan pelaksana dapat ditetapkan di lingkungan Badan Nasional Penanggulangan Bencana sesuai dengan kebutuhan yang pelaksanaannya sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4919, 'Jabatan fungsional dan jabatan pelaksana dapat ditetapkan di lingkungan Badan Nasional Penanggulangan Bencana sesuai dengan kebutuhan yang pelaksanaannya sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 125', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4920, 'perban-6-2025', 129, 'pasal', 'Pasal 126', 'BAB III JABATAN FUNGSIONAL DAN JABATAN PELAKSANA', 26, '(1) Jabatan fungsional sebagaimana dimaksud dalam Pasal 125 mempunyai tugas memberikan pelayanan fungsional sesuai dengan bidang keahlian dan keterampilan.
(2) Jabatan pelaksana sebagaimana dimaksud dalam Pasal 125 mempunyai tugas melaksanakan kegiatan pelayanan publik serta administrasi pemerintahan dan pembangunan.
(3) Dalam pelaksanaan tugas sebagaimana dimaksud pada ayat (1) dan ayat (2), dibentuk jabatan fungsional dan jabatan pelaksana berdasarkan rumpun jabatan sesuai dengan ketentuan peraturan perundang-undangan.
(4) Jumlah jabatan fungsional dan jabatan pelaksana sebagaimana dimaksud pada ayat (3) ditentukan berdasarkan kebutuhan yang didasari atas analisis jabatan dan beban kerja.
(5) Tugas, jenis, dan jenjang jabatan fungsional sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
(6) Tugas dan klasifikasi jabatan pelaksana sebagaimana dimaksud pada ayat (2) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4920, '(1) Jabatan fungsional sebagaimana dimaksud dalam Pasal 125 mempunyai tugas memberikan pelayanan fungsional sesuai dengan bidang keahlian dan keterampilan.
(2) Jabatan pelaksana sebagaimana dimaksud dalam Pasal 125 mempunyai tugas melaksanakan kegiatan pelayanan publik serta administrasi pemerintahan dan pembangunan.
(3) Dalam pelaksanaan tugas sebagaimana dimaksud pada ayat (1) dan ayat (2), dibentuk jabatan fungsional dan jabatan pelaksana berdasarkan rumpun jabatan sesuai dengan ketentuan peraturan perundang-undangan.
(4) Jumlah jabatan fungsional dan jabatan pelaksana sebagaimana dimaksud pada ayat (3) ditentukan berdasarkan kebutuhan yang didasari atas analisis jabatan dan beban kerja.
(5) Tugas, jenis, dan jenjang jabatan fungsional sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.
(6) Tugas dan klasifikasi jabatan pelaksana sebagaimana dimaksud pada ayat (2) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 126', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4921, 'perban-6-2025', 130, 'pasal', 'Pasal 127', 'BAB IV UNIT PELAKSANA TEKNIS', 27, '(1) Jabatan Fungsional dan jabatan pelaksana dapat bekerja secara individu dan/atau dalam tim kerja untuk mendukung pencapaian tujuan dan kinerja organisasi.
(2) Tim kerja sebagaimana dimaksud pada ayat (1) terdiri atas:
a. ketua; dan
b. anggota.
(3) Penugasan secara individu dan/atau tim kerja sebagaimana dimaksud pada ayat (1) ditetapkan oleh pejabat penilai kinerja atau pimpinan unit organisasi.
(4) Pelaksanaan tugas dan penugasan dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4921, '(1) Jabatan Fungsional dan jabatan pelaksana dapat bekerja secara individu dan/atau dalam tim kerja untuk mendukung pencapaian tujuan dan kinerja organisasi.
(2) Tim kerja sebagaimana dimaksud pada ayat (1) terdiri atas:
a. ketua; dan
b. anggota.
(3) Penugasan secara individu dan/atau tim kerja sebagaimana dimaksud pada ayat (1) ditetapkan oleh pejabat penilai kinerja atau pimpinan unit organisasi.
(4) Pelaksanaan tugas dan penugasan dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 127', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4922, 'perban-6-2025', 131, 'pasal', 'Pasal 128', 'BAB V TATA KERJA', 27, '(1) Di lingkungan Badan Nasional Penanggulangan Bencana dapat dibentuk Unit Pelaksana Teknis sebagai pelaksana tugas teknis baik teknis penunjang maupun teknis operasional.
(2) Pembentukan organisasi dan tata kerja Unit Pelaksana Teknis sebagaimana dimaksud pada ayat (1), ditetapkan oleh Kepala setelah mendapat persetujuan tertulis dari Menteri yang membidangi urusan pemerintahan di bidang aparatur negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4922, '(1) Di lingkungan Badan Nasional Penanggulangan Bencana dapat dibentuk Unit Pelaksana Teknis sebagai pelaksana tugas teknis baik teknis penunjang maupun teknis operasional.
(2) Pembentukan organisasi dan tata kerja Unit Pelaksana Teknis sebagaimana dimaksud pada ayat (1), ditetapkan oleh Kepala setelah mendapat persetujuan tertulis dari Menteri yang membidangi urusan pemerintahan di bidang aparatur negara.', 'Pasal 128', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4923, 'perban-6-2025', 132, 'pasal', 'Pasal 129', 'BAB V TATA KERJA', 27, 'Kepala dalam memimpin pelaksanaan tugas dan fungsinya menerapkan sistem akuntabilitas kinerja pemerintah, manajemen risiko pembangunan nasional, dan transformasi digital nasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4923, 'Kepala dalam memimpin pelaksanaan tugas dan fungsinya menerapkan sistem akuntabilitas kinerja pemerintah, manajemen risiko pembangunan nasional, dan transformasi digital nasional.', 'Pasal 129', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4924, 'perban-6-2025', 133, 'pasal', 'Pasal 130', 'BAB V TATA KERJA', 27, '(1) Dalam mendukung optimalisasi pelaksanaan tugas dan fungsi secara terpadu antarunit organisasi di lingkungan Badan Nasional Penanggulangan Bencana didasarkan pada proses bisnis yang menggambarkan tata hubungan kerja yang efektif dan efisien dengan menerapkan prinsip koordinasi, integrasi, sinkronisasi, dan kolaborasi antarunit organisasi di lingkungan Badan Nasional Penanggulangan Bencana.
(2) Proses bisnis antarunit organisasi di lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud pada ayat (1) ditetapkan oleh Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4924, '(1) Dalam mendukung optimalisasi pelaksanaan tugas dan fungsi secara terpadu antarunit organisasi di lingkungan Badan Nasional Penanggulangan Bencana didasarkan pada proses bisnis yang menggambarkan tata hubungan kerja yang efektif dan efisien dengan menerapkan prinsip koordinasi, integrasi, sinkronisasi, dan kolaborasi antarunit organisasi di lingkungan Badan Nasional Penanggulangan Bencana.
(2) Proses bisnis antarunit organisasi di lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud pada ayat (1) ditetapkan oleh Kepala.', 'Pasal 130', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4925, 'perban-6-2025', 134, 'pasal', 'Pasal 131', 'BAB V TATA KERJA', 28, 'Kepala menyampaikan laporan kepada Presiden mengenai hasil pelaksanaan tugas pemerintahan secara berkala atau sewaktu-waktu sesuai dengan kebutuhan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4925, 'Kepala menyampaikan laporan kepada Presiden mengenai hasil pelaksanaan tugas pemerintahan secara berkala atau sewaktu-waktu sesuai dengan kebutuhan.', 'Pasal 131', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4926, 'perban-6-2025', 135, 'pasal', 'Pasal 132', 'BAB V TATA KERJA', 28, 'Badan Nasional Penanggulangan Bencana menyusun analisis jabatan, peta jabatan, analisis beban kerja, dan uraian tugas terhadap seluruh jabatan di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4926, 'Badan Nasional Penanggulangan Bencana menyusun analisis jabatan, peta jabatan, analisis beban kerja, dan uraian tugas terhadap seluruh jabatan di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 132', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4927, 'perban-6-2025', 136, 'pasal', 'Pasal 133', 'BAB V TATA KERJA', 28, '(1) Setiap unsur di lingkungan Badan Nasional Penanggulangan Bencana dalam melaksanakan tugas dan fungsi menerapkan prinsip koordinasi, integrasi, sinkronisasi, dan kolaborasi di lingkungan Badan Nasional Penanggulangan Bencana, antarinstansi pemerintah, dan dengan lembaga lain yang terkait.
(2) Prinsip koordinasi, integrasi, sinkronisasi, dan kolaborasi sebagaimana dimaksud pada ayat (1) didukung dengan melakukan interoperabilitas data dan informasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4927, '(1) Setiap unsur di lingkungan Badan Nasional Penanggulangan Bencana dalam melaksanakan tugas dan fungsi menerapkan prinsip koordinasi, integrasi, sinkronisasi, dan kolaborasi di lingkungan Badan Nasional Penanggulangan Bencana, antarinstansi pemerintah, dan dengan lembaga lain yang terkait.
(2) Prinsip koordinasi, integrasi, sinkronisasi, dan kolaborasi sebagaimana dimaksud pada ayat (1) didukung dengan melakukan interoperabilitas data dan informasi.', 'Pasal 133', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4928, 'perban-6-2025', 137, 'pasal', 'Pasal 134', 'BAB V TATA KERJA', 28, 'Semua unsur di lingkungan Badan Nasional Penanggulangan Bencana menerapkan sistem pengendalian intern pemerintah sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4928, 'Semua unsur di lingkungan Badan Nasional Penanggulangan Bencana menerapkan sistem pengendalian intern pemerintah sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 134', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4929, 'perban-6-2025', 138, 'pasal', 'Pasal 135', 'BAB V TATA KERJA', 28, '(1) Setiap pimpinan unit organisasi bertanggung jawab memimpin dan mengoordinasikan bawahan dan memberikan pengarahan serta petunjuk bagi pelaksanaan tugas sesuai dengan uraian tugas yang telah ditetapkan.
(2) Pengarahan dan petunjuk sebagaimana dimaksud pada ayat (1) diikuti dan dipatuhi oleh bawahan secara bertanggung jawab serta dilaporkan secara berkala sesuai dengan ketentuan peraturan perundang undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4929, '(1) Setiap pimpinan unit organisasi bertanggung jawab memimpin dan mengoordinasikan bawahan dan memberikan pengarahan serta petunjuk bagi pelaksanaan tugas sesuai dengan uraian tugas yang telah ditetapkan.
(2) Pengarahan dan petunjuk sebagaimana dimaksud pada ayat (1) diikuti dan dipatuhi oleh bawahan secara bertanggung jawab serta dilaporkan secara berkala sesuai dengan ketentuan peraturan perundang undangan.', 'Pasal 135', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4930, 'perban-6-2025', 139, 'pasal', 'Pasal 136', 'BAB VI JABATAN, PENGANGKATAN, DAN PEMBERHENTIAN', 28, 'Dalam melaksanakan tugas, setiap pimpinan unit organisasi harus melakukan pembinaan dan pengawasan terhadap unit organisasi di bawahnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4930, 'Dalam melaksanakan tugas, setiap pimpinan unit organisasi harus melakukan pembinaan dan pengawasan terhadap unit organisasi di bawahnya.', 'Pasal 136', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4931, 'perban-6-2025', 140, 'pasal', 'Pasal 137', 'BAB VI JABATAN, PENGANGKATAN, DAN PEMBERHENTIAN', 29, '(1) Kepala merupakan jabatan pimpinan tinggi utama.
(2) Sekretaris Utama, Deputi, dan Inspektur merupakan jabatan pimpinan tinggi madya atau jabatan struktural eselon I.a.
(3) Kepala Biro, Direktur, dan Kepala Pusat merupakan jabatan pimpinan tinggi pratama atau jabatan struktural eselon II.a.
(4) Kepala Bagian merupakan jabatan administrator atau jabatan struktural eselon III.a.
(5) Kepala Subbagian merupakan jabatan pengawas atau jabatan struktural eselon IV.a');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4931, '(1) Kepala merupakan jabatan pimpinan tinggi utama.
(2) Sekretaris Utama, Deputi, dan Inspektur merupakan jabatan pimpinan tinggi madya atau jabatan struktural eselon I.a.
(3) Kepala Biro, Direktur, dan Kepala Pusat merupakan jabatan pimpinan tinggi pratama atau jabatan struktural eselon II.a.
(4) Kepala Bagian merupakan jabatan administrator atau jabatan struktural eselon III.a.
(5) Kepala Subbagian merupakan jabatan pengawas atau jabatan struktural eselon IV.a', 'Pasal 137', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4932, 'perban-6-2025', 141, 'pasal', 'Pasal 138', 'BAB VII PENGELOLAAN INFORMASI DAN DOKUMENTASI', 29, '(1) Kepala diangkat dan diberhentikan oleh Presiden.
(2) Sekretaris Utama, Deputi, dan Inspektur diangkat dan diberhentikan oleh Presiden atas usul Kepala, setelah melalui prosedur seleksi berdasarkan ketentuan peraturan perundang-undangan.
(3) Kepala Biro, Direktur, dan Kepala Pusat diangkat dan diberhentikan oleh Kepala, setelah melalui prosedur seleksi berdasarkan ketentuan peraturan perundang-undangan.
(4) Kepala Bagian dan Kepala Subbagian diangkat dan diberhentikan oleh Kepala sesuai dengan ketentuan peraturan perundang undangan.
(5) Pejabat fungsional diangkat dan diberhentikan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4932, '(1) Kepala diangkat dan diberhentikan oleh Presiden.
(2) Sekretaris Utama, Deputi, dan Inspektur diangkat dan diberhentikan oleh Presiden atas usul Kepala, setelah melalui prosedur seleksi berdasarkan ketentuan peraturan perundang-undangan.
(3) Kepala Biro, Direktur, dan Kepala Pusat diangkat dan diberhentikan oleh Kepala, setelah melalui prosedur seleksi berdasarkan ketentuan peraturan perundang-undangan.
(4) Kepala Bagian dan Kepala Subbagian diangkat dan diberhentikan oleh Kepala sesuai dengan ketentuan peraturan perundang undangan.
(5) Pejabat fungsional diangkat dan diberhentikan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 138', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4933, 'perban-6-2025', 142, 'pasal', 'Pasal 139', 'BAB VIII PENATAAN ORGANISASI', 29, '(1) Pemimpin unit organisasi yang menangani fungsi di bidang pengelolaan dan pelayanan informasi, karena sifat tugas dan fungsinya menjadi pejabat pengelola informasi dan dokumentasi di lingkungan Badan Nasional Penanggulangan Bencana.
(2) Ketentuan mengenai tugas dan tanggung jawab pejabat pengelola informasi dan dokumentasi sebagaimana dimaksud pada ayat (1) diatur dengan Peraturan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4933, '(1) Pemimpin unit organisasi yang menangani fungsi di bidang pengelolaan dan pelayanan informasi, karena sifat tugas dan fungsinya menjadi pejabat pengelola informasi dan dokumentasi di lingkungan Badan Nasional Penanggulangan Bencana.
(2) Ketentuan mengenai tugas dan tanggung jawab pejabat pengelola informasi dan dokumentasi sebagaimana dimaksud pada ayat (1) diatur dengan Peraturan Badan Nasional Penanggulangan Bencana.', 'Pasal 139', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4934, 'perban-6-2025', 143, 'pasal', 'Pasal 140', 'BAB VI KETENTUAN PERALIHAN', 29, 'Perubahan atas kedudukan, tugas, fungsi, susunan organisasi, dan tata Kerja Badan Nasional Penanggulangan Bencana sebagaimana diatur dalam Peraturan Badan ini ditetapkan oleh Kepala setelah terlebih dahulu mendapat persetujuan tertulis dari Menteri yang menyelenggarakan urusan di bidang aparatur negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4934, 'Perubahan atas kedudukan, tugas, fungsi, susunan organisasi, dan tata Kerja Badan Nasional Penanggulangan Bencana sebagaimana diatur dalam Peraturan Badan ini ditetapkan oleh Kepala setelah terlebih dahulu mendapat persetujuan tertulis dari Menteri yang menyelenggarakan urusan di bidang aparatur negara.', 'Pasal 140', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4935, 'perban-6-2025', 144, 'pasal', 'Pasal 141', 'BAB VII KETENTUAN PENUTUP', 30, 'Pada saat Peraturan Badan ini mulai berlaku, jabatan dan pejabat yang memangku jabatan di lingkungan Badan Nasional Penanggulangan Bencana berdasarkan Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana, tetap melaksanakan tugas dan fungsi sampai dengan ditetapkannya jabatan dan pejabat yang memangku jabatan di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4935, 'Pada saat Peraturan Badan ini mulai berlaku, jabatan dan pejabat yang memangku jabatan di lingkungan Badan Nasional Penanggulangan Bencana berdasarkan Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana, tetap melaksanakan tugas dan fungsi sampai dengan ditetapkannya jabatan dan pejabat yang memangku jabatan di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 141', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4936, 'perban-6-2025', 145, 'pasal', 'Pasal 142', 'BAB VII KETENTUAN PENUTUP', 30, 'Pada saat Peraturan Badan ini mulai berlaku, semua peraturan perundang-undangan yang merupakan peraturan pelaksanaan dari Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 846), dinyatakan tetap berlaku sepanjang tidak bertentangan dengan ketentuan dalam Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4936, 'Pada saat Peraturan Badan ini mulai berlaku, semua peraturan perundang-undangan yang merupakan peraturan pelaksanaan dari Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 846), dinyatakan tetap berlaku sepanjang tidak bertentangan dengan ketentuan dalam Peraturan Badan ini.', 'Pasal 142', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4937, 'perban-6-2025', 146, 'pasal', 'Pasal 143', 'BAB VII KETENTUAN PENUTUP', 30, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 846), dicabut dan dinyatakan tidak berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4937, 'Pada saat Peraturan Badan ini mulai berlaku, Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 846), dicabut dan dinyatakan tidak berlaku.', 'Pasal 143', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4938, 'perban-6-2025', 147, 'pasal', 'Pasal 144', 'BAB VII KETENTUAN PENUTUP', 31, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4938, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 144', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4939, 'perban-6-2025', 148, 'lain', 'Penutup', NULL, 31, 'Ditetapkan di Jakarta pada tanggal 6 Oktober 2025 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2025 NOMOR Ж');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4939, 'Ditetapkan di Jakarta pada tanggal 6 Oktober 2025 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2025 NOMOR Ж', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
