INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4944, 'bahwa untuk melaksanakan ketentuan Pasal 7 ayat (1) dan Pasal 14 ayat (3) Peraturan Menteri Keuangan Nomor 140/PMK.05/2018 tentang Tata Cara Pengelolaan Dana Hibah Langsung dalam Bentuk Uang dari Pemberi Hibah Luar Negeri untuk Penanggulangan Bencana Alam di Sulawesi Tengah, perlu membentuk Peraturan Badan Nasional Penanggulangan Bencana tentang Tata Cara Pemindahan, Penarikan, Penggunaan dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4945, 'perban-7-2018', 2, 'mengingat', 'Mengingat', NULL, 1, 'Peraturan Menteri Keuangan Republik Indonesia Nomor 140/PMK.05/2018 tentang Tata Cara Pengelolaan Dana Hibah Langsung dalam Bentuk Uang dari Pemberi Hibah Luar 2018, No.1646 -2- Negeri untuk Penanggulangan Bencana Alam di Sulawesi Tengah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4945, 'Peraturan Menteri Keuangan Republik Indonesia Nomor 140/PMK.05/2018 tentang Tata Cara Pengelolaan Dana Hibah Langsung dalam Bentuk Uang dari Pemberi Hibah Luar 2018, No.1646 -2- Negeri untuk Penanggulangan Bencana Alam di Sulawesi Tengah.', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4946, 'perban-7-2018', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA CARA PEMINDAHAN, PENARIKAN, PENGGUNAAN DAN PELAPORAN DANA HIBAH LANGSUNG LUAR NEGERI UNTUK PENANGGULANGAN BENCANA ALAM DI PROVINSI SULAWESI TENGAH.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4946, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA CARA PEMINDAHAN, PENARIKAN, PENGGUNAAN DAN PELAPORAN DANA HIBAH LANGSUNG LUAR NEGERI UNTUK PENANGGULANGAN BENCANA ALAM DI PROVINSI SULAWESI TENGAH.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4947, 'perban-7-2018', 4, 'pasal', 'Pasal 1', 'BAB II PENANGGUNG JAWAB, PEMBUKAAN REKENING, DAN REGISTRASI HIBAH; Bagian Kesatu Penanggung Jawab', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Badan Nasional Penanggulangan Bencana yang selanjutnya disebut BNPB adalah lembaga pemerintah non-kementerian sesuai dengan ketentuan peraturan perundang-undangan.
2. Hibah Langsung adalah hibah yang dilaksanakan tidak melalui mekanisme perencanaan dari pemberi hibah luar negeri untuk penanggulangan bencana alam di Provinsi Sulawesi Tengah dalam bentuk uang.
3. Pemberi Hibah Luar Negeri adalah pemerintah asing dan/atau organisasi internasional/regional antar pemerintah.
4. Pemindahan adalah proses transaksi dalam bank dengan cara mendebit dan mengkredit dari dan ke Rekening Penampungan Dana Hibah Langsung.
5. Penarikan adalah kegiatan pengurangan atau pendebitan dari Rekening Penyaluran Dana Hibah.
6. Penggunaan adalah pelaksanaan kegiatan yang menggunakan dana Hibah Langsung luar negeri untuk penanggulangan bencana alam di Provinsi Sulawesi Tengah.
7. Pelaporan adalah penyusunan dan penyampaian informasi secara tertulis mengenai kegiatan dan capaian 2018, No.1646 yang dibiayai dana Hibah Langsung luar negeri untuk penanggulangan bencana alam di Provinsi Sulawesi Tengah dalam suatu periode tertentu sesuai dengan ketentuan peraturan perundang-undangan.
8. Pelaksana Kegiatan adalah unit kerja di lingkungan Badan Nasional Penanggulangan Bencana/ kementerian negara/lembaga/pemerintah provinsi/ kabupaten/kota di Sulawesi Tengah yang akan melaksanakan kegiatan penanggulangan bencana alam dengan menggunakan dana Hibah Langsung.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4947, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Badan Nasional Penanggulangan Bencana yang selanjutnya disebut BNPB adalah lembaga pemerintah non-kementerian sesuai dengan ketentuan peraturan perundang-undangan.
2. Hibah Langsung adalah hibah yang dilaksanakan tidak melalui mekanisme perencanaan dari pemberi hibah luar negeri untuk penanggulangan bencana alam di Provinsi Sulawesi Tengah dalam bentuk uang.
3. Pemberi Hibah Luar Negeri adalah pemerintah asing dan/atau organisasi internasional/regional antar pemerintah.
4. Pemindahan adalah proses transaksi dalam bank dengan cara mendebit dan mengkredit dari dan ke Rekening Penampungan Dana Hibah Langsung.
5. Penarikan adalah kegiatan pengurangan atau pendebitan dari Rekening Penyaluran Dana Hibah.
6. Penggunaan adalah pelaksanaan kegiatan yang menggunakan dana Hibah Langsung luar negeri untuk penanggulangan bencana alam di Provinsi Sulawesi Tengah.
7. Pelaporan adalah penyusunan dan penyampaian informasi secara tertulis mengenai kegiatan dan capaian 2018, No.1646 yang dibiayai dana Hibah Langsung luar negeri untuk penanggulangan bencana alam di Provinsi Sulawesi Tengah dalam suatu periode tertentu sesuai dengan ketentuan peraturan perundang-undangan.
8. Pelaksana Kegiatan adalah unit kerja di lingkungan Badan Nasional Penanggulangan Bencana/ kementerian negara/lembaga/pemerintah provinsi/ kabupaten/kota di Sulawesi Tengah yang akan melaksanakan kegiatan penanggulangan bencana alam dengan menggunakan dana Hibah Langsung.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4948, 'perban-7-2018', 5, 'pasal', 'Pasal 2', 'BAB II PENANGGUNG JAWAB, PEMBUKAAN REKENING, DAN REGISTRASI HIBAH; Bagian Kedua Pembukaan Rekening', 3, '(1) Kepala BNPB selaku Pengguna Anggaran mempunyai kewenangan atas pelaksanaan pengelolaan dana Hibah Langsung untuk penanggulangan bencana di Provinsi Sulawesi Tengah.
(2) Untuk melaksanakan kewenangan sebagaimana dimaksud pada ayat (1), Kepala BNPB menunjuk Sekretaris Utama sebagai Kuasa Pengguna Anggaran.
(3) Kuasa Pengguna Anggaran sebagaimana dimaksud pada ayat (2) menetapkan Pejabat Pembuat Komitmen di lingkungan BNPB untuk mengelola Rekening Penampungan Dana Hibah Langsung dan menetapkan Pejabat Pembuat Komitmen dan Bendahara Pengeluaran Pembantu pada Pelaksana Kegiatan untuk mengelola penggunaan dana Hibah Langsung.
(4) Penetapan Pejabat Pembuat Komitmen dan Bendahara Pengeluaran Pembantu pada Pelaksana Kegiatan sebagaimana dimaksud pada ayat (3) berdasarkan usulan kepada Kuasa Pengguna Anggaran.
2018, No.1646 -4- Paragraf Pertama Rekening Penampungan Dana Hibah Langsung');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4948, '(1) Kepala BNPB selaku Pengguna Anggaran mempunyai kewenangan atas pelaksanaan pengelolaan dana Hibah Langsung untuk penanggulangan bencana di Provinsi Sulawesi Tengah.
(2) Untuk melaksanakan kewenangan sebagaimana dimaksud pada ayat (1), Kepala BNPB menunjuk Sekretaris Utama sebagai Kuasa Pengguna Anggaran.
(3) Kuasa Pengguna Anggaran sebagaimana dimaksud pada ayat (2) menetapkan Pejabat Pembuat Komitmen di lingkungan BNPB untuk mengelola Rekening Penampungan Dana Hibah Langsung dan menetapkan Pejabat Pembuat Komitmen dan Bendahara Pengeluaran Pembantu pada Pelaksana Kegiatan untuk mengelola penggunaan dana Hibah Langsung.
(4) Penetapan Pejabat Pembuat Komitmen dan Bendahara Pengeluaran Pembantu pada Pelaksana Kegiatan sebagaimana dimaksud pada ayat (3) berdasarkan usulan kepada Kuasa Pengguna Anggaran.
2018, No.1646 -4- Paragraf Pertama Rekening Penampungan Dana Hibah Langsung', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4949, 'perban-7-2018', 6, 'pasal', 'Pasal 3', 'BAB II PENANGGUNG JAWAB, PEMBUKAAN REKENING, DAN REGISTRASI HIBAH; Bagian Kedua Pembukaan Rekening', 4, '(1) Kuasa Pengguna Anggaran mengajukan permohonan persetujuan pembukaan Rekening Penampungan Dana Hibah Langsung kepada Kepala Kantor Pelayanan Perbendaharaan Negara Mitra Kerja.
(2) Kuasa Pengguna Anggaran membuka Rekening Dana Penampungan Hibah Langsung di bank umum setelah mendapatkan persetujuan sebagaimana dimaksud pada ayat (1) dari Kepala Kantor Pelayanan Perbendaharaan Negara Mitra Kerja.
(3) Kuasa Pengguna Anggaran menugaskan Pejabat Pembuat Komitmen dan Bendahara Pengeluaran BNPB untuk mengelola Rekening Penampungan Dana Hibah Langsung sebagaimana dimaksud pada ayat (2).
Paragraf Kedua Rekening Penyaluran Dana Hibah');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4949, '(1) Kuasa Pengguna Anggaran mengajukan permohonan persetujuan pembukaan Rekening Penampungan Dana Hibah Langsung kepada Kepala Kantor Pelayanan Perbendaharaan Negara Mitra Kerja.
(2) Kuasa Pengguna Anggaran membuka Rekening Dana Penampungan Hibah Langsung di bank umum setelah mendapatkan persetujuan sebagaimana dimaksud pada ayat (1) dari Kepala Kantor Pelayanan Perbendaharaan Negara Mitra Kerja.
(3) Kuasa Pengguna Anggaran menugaskan Pejabat Pembuat Komitmen dan Bendahara Pengeluaran BNPB untuk mengelola Rekening Penampungan Dana Hibah Langsung sebagaimana dimaksud pada ayat (2).
Paragraf Kedua Rekening Penyaluran Dana Hibah', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4950, 'perban-7-2018', 7, 'pasal', 'Pasal 4', 'BAB II PENANGGUNG JAWAB, PEMBUKAAN REKENING, DAN REGISTRASI HIBAH; Bagian Kedua Pembukaan Rekening', 4, '(1) Kuasa Pengguna Anggaran mengajukan permohonan persetujuan pembukaan Rekening Penyaluran Dana Hibah kepada Kepala Kantor Pelayanan Perbendaharaan Negara Mitra Kerja.
(2) Kuasa Pengguna Anggaran membuka Rekening Penyaluran Dana Hibah di bank umum setelah mendapatkan persetujuan sebagaimana dimaksud pada ayat (1) dari Kepala Kantor Pelayanan Perbendaharaan Negara Mitra Kerja.
(3) Kuasa Pengguna Anggaran menugaskan Pejabat Pembuat Komitmen dan Bendahara Pengeluaran Pembantu Pelaksana Kegiatan untuk mengelola Rekening 2018, No.1646 Penyaluran Dana Hibah sebagaimana dimaksud pada ayat (2).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4950, '(1) Kuasa Pengguna Anggaran mengajukan permohonan persetujuan pembukaan Rekening Penyaluran Dana Hibah kepada Kepala Kantor Pelayanan Perbendaharaan Negara Mitra Kerja.
(2) Kuasa Pengguna Anggaran membuka Rekening Penyaluran Dana Hibah di bank umum setelah mendapatkan persetujuan sebagaimana dimaksud pada ayat (1) dari Kepala Kantor Pelayanan Perbendaharaan Negara Mitra Kerja.
(3) Kuasa Pengguna Anggaran menugaskan Pejabat Pembuat Komitmen dan Bendahara Pengeluaran Pembantu Pelaksana Kegiatan untuk mengelola Rekening 2018, No.1646 Penyaluran Dana Hibah sebagaimana dimaksud pada ayat (2).', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4951, 'perban-7-2018', 8, 'pasal', 'Pasal 5', 'BAB II PENANGGUNG JAWAB, PEMBUKAAN REKENING, DAN REGISTRASI HIBAH; Bagian Ketiga Registrasi Hibah', 5, 'Tata cara pengelolaan rekening sebagaimana dimaksud dalam Pasal 3 dan Pasal 4 mengacu pada ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4951, 'Tata cara pengelolaan rekening sebagaimana dimaksud dalam Pasal 3 dan Pasal 4 mengacu pada ketentuan peraturan perundang-undangan.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4952, 'perban-7-2018', 9, 'pasal', 'Pasal 6', 'BAB III PEMINDAHAN', 5, '(1) Kuasa Pengguna Anggaran mengajukan permohonan registrasi Hibah Langsung kepada Menteri Keuangan c.q.
Direktur Jenderal Pengelolaan dan Pembiayaan Risiko untuk seluruh penerimaan Hibah Langsung yang masuk ke Rekening Penampungan Dana Hibah Langsung dalam bentuk valuta asing Dollar Amerika Serikat.
(2) Tata cara registrasi Hibah Langsung sebagaimana dimaksud pada ayat (1) mengacu pada ketentuan peraturan perundang-undangan.
(3) Dalam hal terjadi penambahan saldo pada Rekening Penampungan Dana Hibah Langsung setelah dilakukan registrasi hibah, Kuasa Pengguna Anggaran akan menyampaikan pemutakhiran nilai hibah kepada Menteri Keuangan c.q. Direktur Jenderal Pengelolaan dan Pembiayaan Risiko.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4952, '(1) Kuasa Pengguna Anggaran mengajukan permohonan registrasi Hibah Langsung kepada Menteri Keuangan c.q.
Direktur Jenderal Pengelolaan dan Pembiayaan Risiko untuk seluruh penerimaan Hibah Langsung yang masuk ke Rekening Penampungan Dana Hibah Langsung dalam bentuk valuta asing Dollar Amerika Serikat.
(2) Tata cara registrasi Hibah Langsung sebagaimana dimaksud pada ayat (1) mengacu pada ketentuan peraturan perundang-undangan.
(3) Dalam hal terjadi penambahan saldo pada Rekening Penampungan Dana Hibah Langsung setelah dilakukan registrasi hibah, Kuasa Pengguna Anggaran akan menyampaikan pemutakhiran nilai hibah kepada Menteri Keuangan c.q. Direktur Jenderal Pengelolaan dan Pembiayaan Risiko.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4953, 'perban-7-2018', 10, 'pasal', 'Pasal 7', 'BAB IV PENARIKAN', 5, 'Proses Pemindahan dana dari Rekening Penampungan Dana Hibah Langsung dalam bentuk valuta asing Dollar Amerika Serikat ke Rekening Penyaluran Dana Hibah dalam bentuk Rupiah dilaksanakan dengan mekanisme sebagai berikut:
2018, No.1646 -6-
a. Pelaksana Kegiatan menyampaikan usulan penggunaan dana hibah kepada Sekretaris Utama selaku Kuasa Pengguna Anggaran yang dilengkapi kerangka acuan kerja dan rincian anggaran biaya;
b. usulan sebagaimana dimaksud pada huruf a harus mendapat persetujuan dari unit teknis di lingkungan BNPB;
c. Pejabat Pembuat Komitmen melakukan pengujian kembali terhadap usulan kegiatan dimaksud pada huruf b;
d. Kuasa Pengguna Anggaran menetapkan usulan kegiatan yang disampaikan oleh Pejabat Pembuat Komitmen;
e. Kuasa Pengguna Anggaran memerintahkan kepada Bendahara Pengeluaran untuk memindahbukukan dana dari Rekening Penampungan Dana Hibah Langsung ke Rekening Penyaluran Dana Hibah sesuai dengan usulan kegiatan yang telah ditetapkan; dan
f. Bendahara Pengeluaran melakukan pemindahbukuan dari Rekening Penampungan Dana Hibah Langsung ke Rekening Penyaluran Dana Hibah dengan menggunakan kurs yang berlaku pada saat transaksi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4953, 'Proses Pemindahan dana dari Rekening Penampungan Dana Hibah Langsung dalam bentuk valuta asing Dollar Amerika Serikat ke Rekening Penyaluran Dana Hibah dalam bentuk Rupiah dilaksanakan dengan mekanisme sebagai berikut:
2018, No.1646 -6-
a. Pelaksana Kegiatan menyampaikan usulan penggunaan dana hibah kepada Sekretaris Utama selaku Kuasa Pengguna Anggaran yang dilengkapi kerangka acuan kerja dan rincian anggaran biaya;
b. usulan sebagaimana dimaksud pada huruf a harus mendapat persetujuan dari unit teknis di lingkungan BNPB;
c. Pejabat Pembuat Komitmen melakukan pengujian kembali terhadap usulan kegiatan dimaksud pada huruf b;
d. Kuasa Pengguna Anggaran menetapkan usulan kegiatan yang disampaikan oleh Pejabat Pembuat Komitmen;
e. Kuasa Pengguna Anggaran memerintahkan kepada Bendahara Pengeluaran untuk memindahbukukan dana dari Rekening Penampungan Dana Hibah Langsung ke Rekening Penyaluran Dana Hibah sesuai dengan usulan kegiatan yang telah ditetapkan; dan
f. Bendahara Pengeluaran melakukan pemindahbukuan dari Rekening Penampungan Dana Hibah Langsung ke Rekening Penyaluran Dana Hibah dengan menggunakan kurs yang berlaku pada saat transaksi.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4954, 'perban-7-2018', 11, 'pasal', 'Pasal 8', 'BAB V PENGGUNAAN', 6, 'Penarikan dana dilakukan oleh Bendahara Pengeluaran Pembantu dari Rekening Penyaluran Dana Hibah dengan tata cara sebagai berikut:
a. Penarikan dana didasarkan pada kebutuhan dana untuk membiayai kegiatan penanggulangan bencana alam di Sulawesi Tengah; dan
b. Pejabat Pembuat Komitmen Pelaksana Kegiatan memerintahkan Bendahara Pengeluaran Pembantu untuk melakukan penatausahaan transaksi terhadap dana yang dikelola.
2018, No.1646');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4954, 'Penarikan dana dilakukan oleh Bendahara Pengeluaran Pembantu dari Rekening Penyaluran Dana Hibah dengan tata cara sebagai berikut:
a. Penarikan dana didasarkan pada kebutuhan dana untuk membiayai kegiatan penanggulangan bencana alam di Sulawesi Tengah; dan
b. Pejabat Pembuat Komitmen Pelaksana Kegiatan memerintahkan Bendahara Pengeluaran Pembantu untuk melakukan penatausahaan transaksi terhadap dana yang dikelola.
2018, No.1646', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4955, 'perban-7-2018', 12, 'pasal', 'Pasal 9', 'BAB V PENGGUNAAN', 7, '(1) Kuasa Pengguna Anggaran mengajukan usulan penyesuaian pagu DIPA kepada Kantor Wilayah Direktorat Jenderal Perbendaharaan yang bersumber dari Hibah Langsung sebesar usulan kegiatan yang telah ditetapkan sebagaimana dimaksud dalam Pasal 7 huruf
d. (2) Penyesuaian pagu DIPA sebagaimana dimaksud pada ayat (1) dilakukan melalui revisi sesuai dengan ketentuan peraturan perundang-undangan.
(3) Jenis belanja dalam DIPA dialokasikan sebagai belanja bantuan sosial untuk penanggulangan bencana yang dapat digunakan dalam bentuk uang/barang/jasa.
(4) Sisa dana Hibah Langsung yang belum digunakan sampai dengan akhir tahun anggaran dapat digunakan untuk membiayai kegiatan penanggulangan bencana alam di Provinsi Sulawesi Tengah tahun anggaran berikutnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4955, '(1) Kuasa Pengguna Anggaran mengajukan usulan penyesuaian pagu DIPA kepada Kantor Wilayah Direktorat Jenderal Perbendaharaan yang bersumber dari Hibah Langsung sebesar usulan kegiatan yang telah ditetapkan sebagaimana dimaksud dalam Pasal 7 huruf
d. (2) Penyesuaian pagu DIPA sebagaimana dimaksud pada ayat (1) dilakukan melalui revisi sesuai dengan ketentuan peraturan perundang-undangan.
(3) Jenis belanja dalam DIPA dialokasikan sebagai belanja bantuan sosial untuk penanggulangan bencana yang dapat digunakan dalam bentuk uang/barang/jasa.
(4) Sisa dana Hibah Langsung yang belum digunakan sampai dengan akhir tahun anggaran dapat digunakan untuk membiayai kegiatan penanggulangan bencana alam di Provinsi Sulawesi Tengah tahun anggaran berikutnya.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4956, 'perban-7-2018', 13, 'pasal', 'Pasal 10', 'BAB V PENGGUNAAN', 7, '(1) Penggunaan dana sebagaimana dimaksud dalam Pasal 9 ayat (3) ditujukan untuk mendanai kegiatan penanggulangan bencana alam di Provinsi Sulawesi Tengah dengan tata cara sebagai berikut:
a. untuk kegiatan penanganan darurat, Penggunaan dana mengacu kepada ketentuan Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2018 tentang Penggunaan Dana Siap Pakai; dan
b. untuk kegiatan rehabilitasi dan rekonstruksi, Penggunaan dana mengacu kepada ketentuan Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2017 tentang Penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana.
2018, No.1646 -8-
(2) Penggunaan dana Hibah Langsung sebagaimana dimaksud pada ayat (1) memperhatikan kebijakan pemerintah dan kebutuhan untuk penanggulangan bencana alam di Provinsi Sulawesi Tengah.
(3) Tata cara pengadaan barang/jasa untuk Penggunaan dana Hibah Langsung sebagaimana dimaksud pada ayat
(1) berpedoman pada ketentuan peraturan perundang-undangan mengenai pengadaan barang/jasa pemerintah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4956, '(1) Penggunaan dana sebagaimana dimaksud dalam Pasal 9 ayat (3) ditujukan untuk mendanai kegiatan penanggulangan bencana alam di Provinsi Sulawesi Tengah dengan tata cara sebagai berikut:
a. untuk kegiatan penanganan darurat, Penggunaan dana mengacu kepada ketentuan Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2018 tentang Penggunaan Dana Siap Pakai; dan
b. untuk kegiatan rehabilitasi dan rekonstruksi, Penggunaan dana mengacu kepada ketentuan Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2017 tentang Penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana.
2018, No.1646 -8-
(2) Penggunaan dana Hibah Langsung sebagaimana dimaksud pada ayat (1) memperhatikan kebijakan pemerintah dan kebutuhan untuk penanggulangan bencana alam di Provinsi Sulawesi Tengah.
(3) Tata cara pengadaan barang/jasa untuk Penggunaan dana Hibah Langsung sebagaimana dimaksud pada ayat
(1) berpedoman pada ketentuan peraturan perundang-undangan mengenai pengadaan barang/jasa pemerintah.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4957, 'perban-7-2018', 14, 'pasal', 'Pasal 11', 'BAB VI PERTANGGUNGJAWABAN DAN PELAPORAN', 8, '(1) Kuasa Pengguna Anggaran mengajukan pengesahan atas pendapatan dan belanja yang bersumber dari Hibah Langsung ke Kantor Pelayanan Perbendaharaan Negara Mitra Kerja.
(2) Tata cara pengesahan atas pendapatan dan belanja sebagaimana dimaksud pada ayat (1) mengacu pada ketentuan peraturan perundang-undangan mengenai administrasi pengelolaan hibah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4957, '(1) Kuasa Pengguna Anggaran mengajukan pengesahan atas pendapatan dan belanja yang bersumber dari Hibah Langsung ke Kantor Pelayanan Perbendaharaan Negara Mitra Kerja.
(2) Tata cara pengesahan atas pendapatan dan belanja sebagaimana dimaksud pada ayat (1) mengacu pada ketentuan peraturan perundang-undangan mengenai administrasi pengelolaan hibah.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4958, 'perban-7-2018', 15, 'pasal', 'Pasal 12', 'BAB VI PERTANGGUNGJAWABAN DAN PELAPORAN', 8, 'Pertanggungjawaban Penggunaan dana Hibah Langsung sebagaimana dimaksud dalam Pasal 10 mengacu pada ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4958, 'Pertanggungjawaban Penggunaan dana Hibah Langsung sebagaimana dimaksud dalam Pasal 10 mengacu pada ketentuan peraturan perundang-undangan.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4959, 'perban-7-2018', 16, 'pasal', 'Pasal 13', 'BAB VI PERTANGGUNGJAWABAN DAN PELAPORAN', 8, '(1) Pelaksana Kegiatan menyampaikan laporan Penggunaan dana Hibah Langsung kepada Kuasa Pengguna Anggaran.
(2) Kuasa Pengguna Anggaran menyampaikan laporan sebagaimana dimaksud pada ayat (1) kepada Kepala BNPB untuk diteruskan kepada:
a. Menteri Keuangan;
b. Menteri Luar Negeri; dan
c. Instansi pemerintah lainnya yang terkait.
2018, No.1646
(3) Laporan Kepala BNPB sebagaimana dimaksud pada ayat
(2) dituangkan dalam format sesuai dengan Lampiran yang merupakan bagian tidak terpisahkan dalam Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4959, '(1) Pelaksana Kegiatan menyampaikan laporan Penggunaan dana Hibah Langsung kepada Kuasa Pengguna Anggaran.
(2) Kuasa Pengguna Anggaran menyampaikan laporan sebagaimana dimaksud pada ayat (1) kepada Kepala BNPB untuk diteruskan kepada:
a. Menteri Keuangan;
b. Menteri Luar Negeri; dan
c. Instansi pemerintah lainnya yang terkait.
2018, No.1646
(3) Laporan Kepala BNPB sebagaimana dimaksud pada ayat
(2) dituangkan dalam format sesuai dengan Lampiran yang merupakan bagian tidak terpisahkan dalam Peraturan Badan ini.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4960, 'perban-7-2018', 17, 'pasal', 'Pasal 14', 'BAB VII KETENTUAN LAIN-LAIN', 9, '(1) Pejabat Pembuat Komitmen Pelaksana Kegiatan menyusun dan menyampaikan pertanggungjawaban kepada Kuasa Pengguna Anggaran mengenai penerimaan dan Penggunaan dana Hibah Langsung sebagaimana dimaksud dalam Pasal 10 secara berkala sesuai dengan ketentuan peraturan perundang-undangan.
(2) Akuntansi dan Pelaporan keuangan atas pengelolaan dana Hibah Langsung untuk penanggulangan bencana alam di Provinsi Sulawesi Tengah mengacu pada ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4960, '(1) Pejabat Pembuat Komitmen Pelaksana Kegiatan menyusun dan menyampaikan pertanggungjawaban kepada Kuasa Pengguna Anggaran mengenai penerimaan dan Penggunaan dana Hibah Langsung sebagaimana dimaksud dalam Pasal 10 secara berkala sesuai dengan ketentuan peraturan perundang-undangan.
(2) Akuntansi dan Pelaporan keuangan atas pengelolaan dana Hibah Langsung untuk penanggulangan bencana alam di Provinsi Sulawesi Tengah mengacu pada ketentuan peraturan perundang-undangan.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4961, 'perban-7-2018', 18, 'pasal', 'Pasal 15', 'BAB VIII KETENTUAN PENUTUP', 9, 'Dana yang berasal dari perorangan dan/atau kelompok masyarakat yang ditransfer ke Rekening Penampungan Dana Hibah Langsung diakui sebagai Hibah Langsung.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4961, 'Dana yang berasal dari perorangan dan/atau kelompok masyarakat yang ditransfer ke Rekening Penampungan Dana Hibah Langsung diakui sebagai Hibah Langsung.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4962, 'perban-7-2018', 19, 'pasal', 'Pasal 16', 'BAB VIII KETENTUAN PENUTUP', 9, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
2018, No.1646 -10- Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4962, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
2018, No.1646 -10- Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4963, 'perban-7-2018', 20, 'lain', 'Penutup', NULL, 10, 'Ditetapkan di Jakarta pada tanggal 16 November 2018 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 13 Desember 2018 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA ttd WIDODO EKATJAHJANA 2018, No.1646');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4963, 'Ditetapkan di Jakarta pada tanggal 16 November 2018 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 13 Desember 2018 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA ttd WIDODO EKATJAHJANA 2018, No.1646', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4964, 'perban-7-2018', 21, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA NOMOR 7 TAHUN 2018 TENTANG TATA CARA PEMINDAHAN, PENARIKAN, PENGGUNAAN, DAN PELAPORAN DANA HIBAH LANGSUNG LUAR NEGERI UNTUK PENANGGULANGAN BENCANA ALAM DI PROVINSI SULAWESI TENGAH FORMAT LAPORAN PENGGUNAAN DANA HIBAH LANGSUNG HALAMAN JUDUL KATA PENGANTAR DAFTAR ISI BAB I PENDAHULUAN BAB II PENERIMAAN DANA BAB III PENGGUNAAN DANA BAB IV PENUTUP LAMPIRAN-LAMPIRAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd WILLEM RAMPANGILEI');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4964, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA NOMOR 7 TAHUN 2018 TENTANG TATA CARA PEMINDAHAN, PENARIKAN, PENGGUNAAN, DAN PELAPORAN DANA HIBAH LANGSUNG LUAR NEGERI UNTUK PENANGGULANGAN BENCANA ALAM DI PROVINSI SULAWESI TENGAH FORMAT LAPORAN PENGGUNAAN DANA HIBAH LANGSUNG HALAMAN JUDUL KATA PENGANTAR DAFTAR ISI BAB I PENDAHULUAN BAB II PENERIMAAN DANA BAB III PENGGUNAAN DANA BAB IV PENUTUP LAMPIRAN-LAMPIRAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, ttd WILLEM RAMPANGILEI', 'Lampiran hal. 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2018 tentang Tata Cara Pemindahan, Penarikan, Penggunaan, dan Pelaporan Dana Hibah Langsung Luar Negeri Untuk Penanggulangan Bencana Alam di Provinsi Sulawesi Tengah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4965, 'perban-7-2020', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4965, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4966, 'perban-7-2020', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk mendukung upaya kinerja birokrasi dan peningkatan pelayanan menuju tata kelola pemerintahan yang baik diperlukan pemanfaatan teknologi informasi dalam pelaksanaan administrasi tata naskah dinas:
b. bahwa beberapa ketentuan dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik di Lingkungan Badan Nasional Penanggulangan Bencana dan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2016 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana masih terdapat kekurangan dan sudah tidak sesuai dengan kebutuhan, sehingga perlu diganti, Cc. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4966, 'a. bahwa untuk mendukung upaya kinerja birokrasi dan peningkatan pelayanan menuju tata kelola pemerintahan yang baik diperlukan pemanfaatan teknologi informasi dalam pelaksanaan administrasi tata naskah dinas:
b. bahwa beberapa ketentuan dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik di Lingkungan Badan Nasional Penanggulangan Bencana dan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2016 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana masih terdapat kekurangan dan sudah tidak sesuai dengan kebutuhan, sehingga perlu diganti, Cc. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana,', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4967, 'perban-7-2020', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1);
3. Peraturan Kepala Arsip Nasional Republik Indonesia Nomor 2 Tahun 2014 tentang Pedoman Tata Naskah Dinas (Berita Negara Republik Indonesia Tahun 2014 Nomor 432);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4967, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1);
3. Peraturan Kepala Arsip Nasional Republik Indonesia Nomor 2 Tahun 2014 tentang Pedoman Tata Naskah Dinas (Berita Negara Republik Indonesia Tahun 2014 Nomor 432);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4968, 'perban-7-2020', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA NASKAH DINAS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4968, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA NASKAH DINAS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4969, 'perban-7-2020', 4, 'pasal', 'Pasal 1', NULL, 2, 'Tata Naskah Dinas Badan Nasional Penanggulangan Bencana dimaksudkan sebagai acuan bagi seluruh unit kerja di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4969, 'Tata Naskah Dinas Badan Nasional Penanggulangan Bencana dimaksudkan sebagai acuan bagi seluruh unit kerja di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4970, 'perban-7-2020', 5, 'pasal', 'Pasal 2', NULL, 2, 'Tata Naskah Dinas sebagaimana dimaksud dalam Pasal 1 terdiri atas:
a. Pendahuluan;
b. Jenis Dan Format Naskah Dinas;
c. Penyusunan Naskah Dinas;
d. Pengurusan Naskah Dinas Korespodensi;
e. Pejabat Penanda Tangan Naskah Dinas;
f. Penggunaan Lambang Negara, Logo dan Cap Dinas Dalam Naskah Dinas;
g. Naskah Dinas Elektronik;
h. Perubahan, Pencabutan, Pembatalan, Dan Ralat Naskah Dinas; dan
i. Penutup.');
