INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4971, 'perban-7-2020', 6, 'pasal', 'Pasal 3', NULL, 3, 'Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 2 tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4971, 'Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 2 tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4972, 'perban-7-2020', 7, 'pasal', 'Pasal 4', NULL, 3, '(1) Tata naskah dinas di lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 3 dilengkapi dengan kode nama jabatan, kode nama instansi dan kode nama unit kerja.
(2) Kode nama jabatan, kode nama instansi dan kode nama unit kerja sebagaimana dimaksud pada ayat (1) tercantum dalam Lampiran II yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4972, '(1) Tata naskah dinas di lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 3 dilengkapi dengan kode nama jabatan, kode nama instansi dan kode nama unit kerja.
(2) Kode nama jabatan, kode nama instansi dan kode nama unit kerja sebagaimana dimaksud pada ayat (1) tercantum dalam Lampiran II yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4973, 'perban-7-2020', 8, 'pasal', 'Pasal 5', NULL, 3, 'Pada saat Peraturan Badan ini mulai berlaku:
a. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 1552); dan
b. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2016 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2016 Nomor 1970), dicabut dan dinyatakan tidak berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4973, 'Pada saat Peraturan Badan ini mulai berlaku:
a. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 1552); dan
b. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2016 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2016 Nomor 1970), dicabut dan dinyatakan tidak berlaku.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4974, 'perban-7-2020', 9, 'pasal', 'Pasal 6', NULL, 3, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan. sd Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4974, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan. sd Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4975, 'perban-7-2020', 10, 'lain', 'Penutup', NULL, 4, 'Ditetapkan di Jakarta pada tanggal 25 Agustus 2020 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
DONI MONARDO Diundangkan di Jakarta pada tanggal 22 September 2020 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd.
WIDODO EKATJAHJANA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2020 NOMOR 1055');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4975, 'Ditetapkan di Jakarta pada tanggal 25 Agustus 2020 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
DONI MONARDO Diundangkan di Jakarta pada tanggal 22 September 2020 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd.
WIDODO EKATJAHJANA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2020 NOMOR 1055', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4976, 'perban-7-2020', 11, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi dan Kerja Sama, Bahoman eh ZAHERMANN MUABEZI 155');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4976, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA Kepala Biro Hukum, Organisasi dan Kerja Sama, Bahoman eh ZAHERMANN MUABEZI 155', 'Lampiran hal. 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4977, 'perban-7-2020', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'LAMPIRAN I PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR TAHUN 2020 TENTANG TATA NASKAH DINAS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA TATA NASKAH DINAS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BAB I PENDAHULUAN Latar Belakang Tata naskah dinas merupakan salah satu unsur utama dari penyelenggaraan administrasi umum yang menjadi komponen penting dalam ketatalaksanaan. Pada berbagai bidang kegiatan pangadministrasian, ketatalaksanaan menjadi kendali dalam pengaturan pelaksanaan tugas dan fungsi. Tata naskah dinas memuat beberapa hal diantaranya yaitu, pengaturan tentang jenis dan format naskah dinas, aturan penyusunan naskah dinas, pengabsahan, penggunaan lambang negara, logo dan cap dalam naskah dinas, naskah dinas elektronik, perubahan dan pencabutan, pembatalan dan ralat naskah dinas.
Dalam upaya mendorong peningkatan kinerja birokrasi dan pelayanan mutu di lingkungan Badan Nasional Penanggulangan Bencana, perkembangan tata naskah dinas mengalami perubahan yang pesat mengikuti laju modernisasi yang dibarengi dengan pemanfaatan teknologi informasi dan komunikasi. Penggunaan naskah dinas elektronik menjadi salah satu wujud dari adanya perkembangan teknologi di lingkup administrasi tata laksana yang ada di lingkungan Badan Nasional Penanggulangan Bencana.
B. Maksud dan Tujuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4977, 'LAMPIRAN I PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR TAHUN 2020 TENTANG TATA NASKAH DINAS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA TATA NASKAH DINAS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BAB I PENDAHULUAN Latar Belakang Tata naskah dinas merupakan salah satu unsur utama dari penyelenggaraan administrasi umum yang menjadi komponen penting dalam ketatalaksanaan. Pada berbagai bidang kegiatan pangadministrasian, ketatalaksanaan menjadi kendali dalam pengaturan pelaksanaan tugas dan fungsi. Tata naskah dinas memuat beberapa hal diantaranya yaitu, pengaturan tentang jenis dan format naskah dinas, aturan penyusunan naskah dinas, pengabsahan, penggunaan lambang negara, logo dan cap dalam naskah dinas, naskah dinas elektronik, perubahan dan pencabutan, pembatalan dan ralat naskah dinas.
Dalam upaya mendorong peningkatan kinerja birokrasi dan pelayanan mutu di lingkungan Badan Nasional Penanggulangan Bencana, perkembangan tata naskah dinas mengalami perubahan yang pesat mengikuti laju modernisasi yang dibarengi dengan pemanfaatan teknologi informasi dan komunikasi. Penggunaan naskah dinas elektronik menjadi salah satu wujud dari adanya perkembangan teknologi di lingkup administrasi tata laksana yang ada di lingkungan Badan Nasional Penanggulangan Bencana.
B. Maksud dan Tujuan', 'Lampiran hal. 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4978, 'perban-7-2020', 13, 'lampiran', 'Lampiran hal. 6', NULL, 6, '1. Maksud Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana dimaksudkan sebagai acuan bagi seluruh unit kerja di lingkungan Badan Nasional Penanggulangan Bencana.
2. Tujuan Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana bertujuan menciptakan kelancaran komunikasi secara tertulis maupun secara elektronik yang efektif dan efisien dalam penyelenggaraan pemerintahan.
C. Sasaran Sasaran penetapan Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana adalah:
1. tercapainya kesamaan pengertian dan pemahaman dalam penyelenggaraan tata naskah dinas di lingkungan Badan Nasional Penanggulangan Bencana;
2. terwujudnya keterpaduan penyelenggaraan tata naskah dinas dengan unsur lainnya dalam lingkup administrasi umum;
3. terwujudnya kemudahan dan kelancaran dalam komunikasi tulis;
4. tercapainya efektivitas dan efisiensi penyelenggaraan tata naskah dinas; dan
5. berkurangnya tumpang tindih dan pemborosan penyelenggaraan tata naskah dinas.
D. Asas Asas yang harus diperhatikan dalam penyusunan naskah dinas adalah sebagai berikut:
1. Asas Efektif dan Efisien Penyelenggaraan tata naskah dinas perlu dilakukan secara efektif dan efisien dalam penulisan, penggunaan ruang atau lembar naskah dinas, penentuan spesifikasi informasi serta dalam penggunaan bahasa Indonesia yang baik, benar, dan lugas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4978, '1. Maksud Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana dimaksudkan sebagai acuan bagi seluruh unit kerja di lingkungan Badan Nasional Penanggulangan Bencana.
2. Tujuan Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana bertujuan menciptakan kelancaran komunikasi secara tertulis maupun secara elektronik yang efektif dan efisien dalam penyelenggaraan pemerintahan.
C. Sasaran Sasaran penetapan Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana adalah:
1. tercapainya kesamaan pengertian dan pemahaman dalam penyelenggaraan tata naskah dinas di lingkungan Badan Nasional Penanggulangan Bencana;
2. terwujudnya keterpaduan penyelenggaraan tata naskah dinas dengan unsur lainnya dalam lingkup administrasi umum;
3. terwujudnya kemudahan dan kelancaran dalam komunikasi tulis;
4. tercapainya efektivitas dan efisiensi penyelenggaraan tata naskah dinas; dan
5. berkurangnya tumpang tindih dan pemborosan penyelenggaraan tata naskah dinas.
D. Asas Asas yang harus diperhatikan dalam penyusunan naskah dinas adalah sebagai berikut:
1. Asas Efektif dan Efisien Penyelenggaraan tata naskah dinas perlu dilakukan secara efektif dan efisien dalam penulisan, penggunaan ruang atau lembar naskah dinas, penentuan spesifikasi informasi serta dalam penggunaan bahasa Indonesia yang baik, benar, dan lugas.', 'Lampiran hal. 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4979, 'perban-7-2020', 14, 'lampiran', 'Lampiran hal. 6', NULL, 6, '2. Asas Pembakuan Naskah dinas diproses dan disusun menurut tata cara dan bentuk baku, termasuk jenis, penyusunan naskah dinas, dan tata cara penyelenggaraannya.
3. Asas Pertanggungjawaban Penyelenggaraan tata naskah dinas dapat dipertanggungjawabkan dari segi isi, format, prosedur, kearsipan, kewenangan, dan keabsahan.
4. Asas Keterkaitan Kegiatan penyelenggaraan tata naskah dinas terkait dengan unsur administrasi umum lainnya.
5. Asas Kecepatan dan Ketepatan Untuk mendukung kelancaran tugas dan fungsi satuan kerja atau satuan organisasi, naskah dinas harus dapat diselesaikan tepat waktu dan tepat sasaran antara lain dilihat dari kejelasan redaksional, kemudahan prosedural, kecepatan penyampaian dan distribusi.
6. Asas Keamanan Naskah dinas harus aman secara fisik dan substansi mulai dari penyusunan, klasifikasi, penyampaian kepada yang berhak, pemberkasan, kearsipan dan distribusi.
E. Ruang Lingkup dan Tata Urut
1. Ruang lingkup Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana meliputi pengaturan tentang jenis dan format naskah dinas, penyusunan naskah dinas, pengurusan naskah dinas korespondensi, pejabat penanda tangan naskah dinas, penggunaan lambang negara, logo dan cap dinas dalam naskah dinas, perubahan, pencabutan, pembatalan, dan ralat naskah dinas.
2. Tata urut Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana sebagai berikut:
a. Bab I Pendahuluan;
b. Bab II Jenis dan Format Naskah Dinas;
c. Bab III Penyusunan Naskah Dinas;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4979, '2. Asas Pembakuan Naskah dinas diproses dan disusun menurut tata cara dan bentuk baku, termasuk jenis, penyusunan naskah dinas, dan tata cara penyelenggaraannya.
3. Asas Pertanggungjawaban Penyelenggaraan tata naskah dinas dapat dipertanggungjawabkan dari segi isi, format, prosedur, kearsipan, kewenangan, dan keabsahan.
4. Asas Keterkaitan Kegiatan penyelenggaraan tata naskah dinas terkait dengan unsur administrasi umum lainnya.
5. Asas Kecepatan dan Ketepatan Untuk mendukung kelancaran tugas dan fungsi satuan kerja atau satuan organisasi, naskah dinas harus dapat diselesaikan tepat waktu dan tepat sasaran antara lain dilihat dari kejelasan redaksional, kemudahan prosedural, kecepatan penyampaian dan distribusi.
6. Asas Keamanan Naskah dinas harus aman secara fisik dan substansi mulai dari penyusunan, klasifikasi, penyampaian kepada yang berhak, pemberkasan, kearsipan dan distribusi.
E. Ruang Lingkup dan Tata Urut
1. Ruang lingkup Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana meliputi pengaturan tentang jenis dan format naskah dinas, penyusunan naskah dinas, pengurusan naskah dinas korespondensi, pejabat penanda tangan naskah dinas, penggunaan lambang negara, logo dan cap dinas dalam naskah dinas, perubahan, pencabutan, pembatalan, dan ralat naskah dinas.
2. Tata urut Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana sebagai berikut:
a. Bab I Pendahuluan;
b. Bab II Jenis dan Format Naskah Dinas;
c. Bab III Penyusunan Naskah Dinas;', 'Lampiran hal. 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4980, 'perban-7-2020', 15, 'lampiran', 'Lampiran hal. 7', NULL, 7, 'd. Bab IV Pengurusan Naskah Dinas Korespondensi;
e. Bab V Pejabat Penanda Tangan Naskah Dinas;
f. Bab VI Penggunaan Lambang Negara, Logo dan Cap Dinas dalam Naskah Dinas;
g. Bab VII Naskah Dinas Elektronik;
h. Bab VIII Perubahan, Pencabutan, Pembatalan, dan Ralat Naskah Dinas; dan
i. Bab IX Penutup F. Pengertian Umum
1. Administrasi umum adalah rangkaian kegiatan administrasi yang meliputi tata naskah dinas, penamaan lembaga, singkatan dan akronim, kearsipan, serta tata ruang perkantoran.
2. Naskah dinas adalah komunikasi tulis sebagai alat komunikasi kedinasan yang dibuat dan/ atau dikeluarkan oleh pejabat yang berwenang di lingkungan Badan Nasional Penanggulangan Bencana dalam rangka penyelenggaraan tugas pemerintahan.
3. Tata naskah dinas adalah penyelenggaraan komunikasi tulis yang meliputi pengaturan jenis, format, penyiapan, pengamanan, pengabsahan, distribusi dan penyimpanan naskah dinas, serta media yang digunakan dalam komunikasi kedinasan.
4. Komunikasi intern adalah tata hubungan dalam penyampaian informasi kedinasan yang dilakukan antar unit kerja di lingkungan Badan Nasional Penanggulangan Bencana dalam organisasi secara vertikal dan horizontal.
5. Komunikasi ekstern adalah tata hubungan penyampaian informasi kedinasan yang dilakukan oleh Badan Nasional Penanggulangan Bencana dengan pihak lain di luar lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4980, 'd. Bab IV Pengurusan Naskah Dinas Korespondensi;
e. Bab V Pejabat Penanda Tangan Naskah Dinas;
f. Bab VI Penggunaan Lambang Negara, Logo dan Cap Dinas dalam Naskah Dinas;
g. Bab VII Naskah Dinas Elektronik;
h. Bab VIII Perubahan, Pencabutan, Pembatalan, dan Ralat Naskah Dinas; dan
i. Bab IX Penutup F. Pengertian Umum
1. Administrasi umum adalah rangkaian kegiatan administrasi yang meliputi tata naskah dinas, penamaan lembaga, singkatan dan akronim, kearsipan, serta tata ruang perkantoran.
2. Naskah dinas adalah komunikasi tulis sebagai alat komunikasi kedinasan yang dibuat dan/ atau dikeluarkan oleh pejabat yang berwenang di lingkungan Badan Nasional Penanggulangan Bencana dalam rangka penyelenggaraan tugas pemerintahan.
3. Tata naskah dinas adalah penyelenggaraan komunikasi tulis yang meliputi pengaturan jenis, format, penyiapan, pengamanan, pengabsahan, distribusi dan penyimpanan naskah dinas, serta media yang digunakan dalam komunikasi kedinasan.
4. Komunikasi intern adalah tata hubungan dalam penyampaian informasi kedinasan yang dilakukan antar unit kerja di lingkungan Badan Nasional Penanggulangan Bencana dalam organisasi secara vertikal dan horizontal.
5. Komunikasi ekstern adalah tata hubungan penyampaian informasi kedinasan yang dilakukan oleh Badan Nasional Penanggulangan Bencana dengan pihak lain di luar lingkungan Badan Nasional Penanggulangan Bencana.', 'Lampiran hal. 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4981, 'perban-7-2020', 16, 'lampiran', 'Lampiran hal. 8', NULL, 8, '6. Format adalah susunan dan bentuk naskah yang menggambarkan tata letak dan redaksional, serta penggunaan lambang negara, logo, dan cap dinas.
7. Kewenangan penandatanganan naskah dinas adalah hak dan kewajiban yang ada pada pejabat untuk menandatangani naskah dinas sesuai dengan tugas dan tanggung jawab kedinasan pada jabatannya.
8. Lambang negara adalah simbol negara yang dituangkan dalam gambar burung garuda sesuai dengan peraturan perundang-undangan.
9. Logo adalah gambar/huruf warna sebagai identitas Badan Nasional Penanggulangan Bencana.
10. Naskah Dinas Elektronik adalah informasi yang terekam dalam media elektronik sebagai alat komunikasi kedinasan, yang dibuat dan/atau diterima oleh pejabat/pimpinan yang berwenang di lingkungan Badan Nasional Penanggulangan Bencana.
BAB II JENIS DAN FORMAT NASKAH DINAS Jenis naskah dinas terdiri atas tiga macam, yaitu naskah dinas arahan, naskah dinas korespondensi, dan naskah dinas khusus. Ketiga jenis naskah dinas tersebut dijelaskan sebagai berikut:
A. Naskah Dinas Arahan Naskah dinas arahan merupakan naskah dinas yang memuat kebijakan pokok atau kebijakan pelaksanaan yang harus dipedomani dan dilaksanakan dalam penyelenggaraan tugas dan kegiatan Badan Nasional Penanggulangan Bencana yang berupa produk hukum yang bersifat pengaturan, penetapan, dan penugasan.
1. Naskah Dinas Pengaturan Naskah dinas yang bersifat pengaturan terdiri atas peraturan, pedoman, petunjuk pelaksanaan, standar operasional prosedur, dan surat edaran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4981, '6. Format adalah susunan dan bentuk naskah yang menggambarkan tata letak dan redaksional, serta penggunaan lambang negara, logo, dan cap dinas.
7. Kewenangan penandatanganan naskah dinas adalah hak dan kewajiban yang ada pada pejabat untuk menandatangani naskah dinas sesuai dengan tugas dan tanggung jawab kedinasan pada jabatannya.
8. Lambang negara adalah simbol negara yang dituangkan dalam gambar burung garuda sesuai dengan peraturan perundang-undangan.
9. Logo adalah gambar/huruf warna sebagai identitas Badan Nasional Penanggulangan Bencana.
10. Naskah Dinas Elektronik adalah informasi yang terekam dalam media elektronik sebagai alat komunikasi kedinasan, yang dibuat dan/atau diterima oleh pejabat/pimpinan yang berwenang di lingkungan Badan Nasional Penanggulangan Bencana.
BAB II JENIS DAN FORMAT NASKAH DINAS Jenis naskah dinas terdiri atas tiga macam, yaitu naskah dinas arahan, naskah dinas korespondensi, dan naskah dinas khusus. Ketiga jenis naskah dinas tersebut dijelaskan sebagai berikut:
A. Naskah Dinas Arahan Naskah dinas arahan merupakan naskah dinas yang memuat kebijakan pokok atau kebijakan pelaksanaan yang harus dipedomani dan dilaksanakan dalam penyelenggaraan tugas dan kegiatan Badan Nasional Penanggulangan Bencana yang berupa produk hukum yang bersifat pengaturan, penetapan, dan penugasan.
1. Naskah Dinas Pengaturan Naskah dinas yang bersifat pengaturan terdiri atas peraturan, pedoman, petunjuk pelaksanaan, standar operasional prosedur, dan surat edaran.', 'Lampiran hal. 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4982, 'perban-7-2020', 17, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'a. Peraturan Badan Sesuai dengan Undang-Undang Nomor 12 Tahun 2011 tentang Pembentukan Peraturan Perundang-undangan, bahwa Peraturan Badan Nasional Penanggulangan Bencana termasuk salah satu jenis peraturan yang ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana berdasarkan materi muatan dalam rangka penyelenggaraan urusan tertentu dalam pemerintahan.
Ketentuan mengenai tata naskah dinas tidak berlaku terhadap peraturan perundang-undangan. Penyusunan rancangan peraturan perundang-undangan dilakukan sesuai dengan teknik penyusunan eraturan perundang-undangan sebagaimana diatur dalam Lampiran II Undang-Undang Nomor 12 Tahun 2011 tentang Pembentukan Peraturan Perundang-undangan.
Format salinan peraturan dapat dilihat pada Contoh 1.
