INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4983, 'perban-7-2020', 18, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'Pasal 2 ………………………………………………………………………………………… ………………………………………………………………………………………… BAB … PENUTUP Pasal … ………………………………………………………………………………………… ………………………………………………………………………………………… Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.
Ditetapkan di Jakarta pada tanggal … KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
NAMA LENGKAP Diundangkan di Jakarta pada tanggal … DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA ttd.
NAMA PEJABAT BERITA NEGARA REPUBLIK INDONESIA TAHUN … NOMOR … Salinan peraturan Salinan sesuai dengan aslinya memuat tulisan BADAN NASIONAL PENANGGULANGAN BENCANA ‘Salinan sesuai dengan aslinya’, Kepala Biro Hukum, Organisasi dan Kerja Sama, nama lembaga, nama jabatan, tanda tangan, cap Tanda tangan dan cap instansi instansi dan nama penanda tangan salinan.
NAMA PEJABAT
b. Pedoman 1) Pengertian Pedoman adalah naskah dinas pengaturan yang memuat acuan yang bersifat umum di lingkungan Badan Nasional Penanggulangan Bencana yang perlu dijabarkan ke dalam petunjuk operasional dan penerapannya disesuaikan dengan karakteristik Badan Nasional Penanggulangan Bencana.
Pedoman dibuat dalam rangka menindaklanjuti kebijakan yang lebih tinggi.
2) Wewenang Penetapan dan Penandatanganan Pejabat yang berwenang menetapkan dan menandatangani pedoman adalah Kepala Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4983, 'Pasal 2 ………………………………………………………………………………………… ………………………………………………………………………………………… BAB … PENUTUP Pasal … ………………………………………………………………………………………… ………………………………………………………………………………………… Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.
Ditetapkan di Jakarta pada tanggal … KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
