INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4986, 'perban-7-2020', 21, 'lampiran', 'Lampiran hal. 15', NULL, 15, '3) Susunan a) Kepala Bagian kepala petunjuk pelaksanaan terdiri atas:
(1) kop petunjuk pelaksanaan/petunjuk teknis menggunakan lambang negara dan tulisan Kepala Badan Nasional Penanggulangan Bencana, ditulis dengan huruf kapital yang diletakkan secara simetris;
(2) tulisan petunjuk pelaksanaan/petunjuk teknis dengan huruf kapital, dicantumkan di tengah atas;
(3) rumusan judul petunjuk pelaksanaan/petunjuk teknis, ditulis dengan huruf kapital dan dicantumkan secara simetris; dan
(4) nomor dan tahun petunjuk pelaksanaan/petunjuk teknis, ditulis dengan huruf kapital secara simetris. b) Batang Tubuh Bagian batang tubuh petunjuk pelaksanaan/petunjuk teknis terdiri atas:
(1) pendahuluan, yang memuat latar belakang, maksud dan tujuan, ruang lingkup, pengertian, dan hal lain yang dipandang perlu;
(2) batang tubuh materi petunjuk pelaksanaan/petunjuk teknis, yang dengan jelas menunjukkan urutan tindakan, pengorganisasian, koordinasi, pengawasan dan pengendalian, serta hal lain yang dipandang perlu untuk dilaksanakan. c) Kaki Bagian kaki petunjuk pelaksanaan/petunjuk teknis ditempatkan di sebelah kanan bawah terdiri atas:
(1) tempat (kota sesuai alamat instansi) dan tanggal penandatanganan petunjuk pelaksanaan/petunjuk teknis;
(2) tulisan Kepala Badan Nasional Penanggulangan Bencana diketik dengan huruf kapital dan diakhiri dengan tanda baca koma;
(3) tanda tangan Kepala Badan Nasional Penanggulangan Bencana dibubuhi cap jabatan; dan');
