INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4989, 'perban-7-2020', 24, 'lampiran', 'Lampiran hal. 19', NULL, 19, 'd. Standar Operasional Prosedur Standar Operasional Prosedur (SOP) adalah serangkaian instruksi tertulis yang dibakukan mengenai proses penyelenggaraan aktivitas organisasi, bagaimana, kapan harus dilakukan, dimana, dan oleh siapa dilakukan. SOP Administrasi Pemerintahan merupakan prosedur operasional standar dari berbagai proses penyelenggaraan administrasi pemerintahan. Ketentuan lebih lanjut tentang penyusunan SOP administrasi pemerintahan sesuai dengan ketentuan peraturan perundang-undangan.
e. Surat Edaran 1) Pengertian Surat edaran adalah naskah dinas yang memuat pemberitahuan tentang hal tertentu yang dianggap penting dan mendesak.
2) Wewenang Penetapan dan Penandatanganan Kewenangan untuk menetapkan dan menandatangani surat edaran oleh Kepala Badan Nasional Penanggulangan Bencana dan dapat dilimpahkan kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana atau pejabat yang ditunjuk sesuai dengan substansi surat edaran.
3) Susunan a) Kepala Bagian kepala surat edaran terdiri atas:
(1) kop surat edaran yang ditandatangani Kepala menggunakan lambang negara dan tulisan Kepala Badan Nasional Penanggulangan Bencana, ditulis dengan huruf kapital yang diletakkan secara simetris;
(2) kop surat edaran yang ditandatangani oleh pejabat selain Kepala menggunakan logo Badan Nasional Penanggulangan Bencana dan tulisan Badan Nasional Penanggulangan Bencana, ditulis dengan huruf kapital yang diletakkan secara simetris;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4989, 'd. Standar Operasional Prosedur Standar Operasional Prosedur (SOP) adalah serangkaian instruksi tertulis yang dibakukan mengenai proses penyelenggaraan aktivitas organisasi, bagaimana, kapan harus dilakukan, dimana, dan oleh siapa dilakukan. SOP Administrasi Pemerintahan merupakan prosedur operasional standar dari berbagai proses penyelenggaraan administrasi pemerintahan. Ketentuan lebih lanjut tentang penyusunan SOP administrasi pemerintahan sesuai dengan ketentuan peraturan perundang-undangan.
e. Surat Edaran 1) Pengertian Surat edaran adalah naskah dinas yang memuat pemberitahuan tentang hal tertentu yang dianggap penting dan mendesak.
2) Wewenang Penetapan dan Penandatanganan Kewenangan untuk menetapkan dan menandatangani surat edaran oleh Kepala Badan Nasional Penanggulangan Bencana dan dapat dilimpahkan kepada Sekretaris Utama Badan Nasional Penanggulangan Bencana atau pejabat yang ditunjuk sesuai dengan substansi surat edaran.
3) Susunan a) Kepala Bagian kepala surat edaran terdiri atas:
(1) kop surat edaran yang ditandatangani Kepala menggunakan lambang negara dan tulisan Kepala Badan Nasional Penanggulangan Bencana, ditulis dengan huruf kapital yang diletakkan secara simetris;
(2) kop surat edaran yang ditandatangani oleh pejabat selain Kepala menggunakan logo Badan Nasional Penanggulangan Bencana dan tulisan Badan Nasional Penanggulangan Bencana, ditulis dengan huruf kapital yang diletakkan secara simetris;', 'Lampiran hal. 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4990, 'perban-7-2020', 25, 'lampiran', 'Lampiran hal. 19', NULL, 19, '(3) kata Yth. yang diikuti nama pejabat yang dikirimi surat edaran;
(4) tulisan surat edaran, yang dicantumkan di bawah lambang negara/logo Badan Nasional Penanggulangan Bencana, ditulis dengan huruf kapital, dan penulisan nomor dan tahun surat edaran di bawahnya yang diletakkan secara simetris;
(5) kata tentang, yang dicantumkan di bawah frasa surat edaran ditulis dengan huruf kapital secara simetris; dan
(6) rumusan judul surat edaran, yang ditulis dengan huruf kapital secara simetris di bawah kata tentang. b) Batang Tubuh Bagian batang tubuh surat edaran terdiri atas:
(1) alasan tentang perlunya dibuat surat edaran;
(2) maksud dan tujuan dibuatnya surat edaran;
(3) ruang lingkup diberlakukannya surat edaran;
(4) peraturan perundang-undangan atau naskah dinas lain yang menjadi dasar surat edaran;
(5) pemberitahuan tentang hal tertentu yang dianggap mendesak; dan
(6) penutup. c) Kaki Bagian kaki surat edaran terdiri atas:
(1) tempat (kota sesuai alamat instansi) dan tanggal penandatanganan surat edaran;
(2) nama jabatan pejabat penanda tangan ditulis dengan huruf kapital, diakhiri dengan tanda baca koma;
(3) tanda tangan pejabat penanda tangan;
(4) nama lengkap pejabat penanda tangan ditulis dengan huruf kapital;
(5) cap dinas; dan
(6) tembusan (jika diperlukan).
4) Distribusi Distribusi dilakukan dengan menggunakan daftar distribusi yang berlaku.
Format surat edaran dapat dilihat pada Contoh 4A dan 4B.');
