INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4993, 'perban-7-2020', 28, 'lampiran', 'Lampiran hal. 23', NULL, 23, '1) kepegawaian/personal/menetapkan/mengubah status keanggotaan/material/peristiwa;
2) menetapkan/mengubah/membubarkan suatu kepanitiaan/ tim; dan 3) menetapkan pelimpahan wewenang.
b. Wewenang Penetapan dan Penandatanganan Pejabat yang berwenang menetapkan dan menandatangani keputusan adalah Kepala Badan Nasional Penanggulangan Bencana atau pejabat lain yang menerima pendelegasian wewenang. Keputusan yang ditetapkan oleh pejabat eselon 1 selain Sekretaris Utama merupakan keputusan yang berkaitan dengan kelompok kerja dan tidak menimbulkan anggaran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4993, '1) kepegawaian/personal/menetapkan/mengubah status keanggotaan/material/peristiwa;
2) menetapkan/mengubah/membubarkan suatu kepanitiaan/ tim; dan 3) menetapkan pelimpahan wewenang.
b. Wewenang Penetapan dan Penandatanganan Pejabat yang berwenang menetapkan dan menandatangani keputusan adalah Kepala Badan Nasional Penanggulangan Bencana atau pejabat lain yang menerima pendelegasian wewenang. Keputusan yang ditetapkan oleh pejabat eselon 1 selain Sekretaris Utama merupakan keputusan yang berkaitan dengan kelompok kerja dan tidak menimbulkan anggaran.', 'Lampiran hal. 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4994, 'perban-7-2020', 29, 'lampiran', 'Lampiran hal. 23', NULL, 23, 'c. Susunan 1) Kepala Bagian kepala keputusan terdiri atas: a) kop keputusan yang ditandatangani oleh Kepala Badan Nasional Penanggulangan Bencana berisi lambang negara dan tulisan Kepala Badan Nasional Penanggulangan Bencana dan tulisan Badan Nasional Penanggulangan Bencana yang ditulis dengan huruf kapital diletakkan secara simetris; b) kop keputusan yang ditandatangani oleh pejabat selain Kepala menggunakan logo Badan Nasional Penanggulangan Bencana, dengan nama lembaga ditulis menggunakan huruf kapital diletakkan secara simetris; c) kata keputusan dan nama jabatan pejabat yang menetapkan, ditulis dengan huruf kapital secara simetris; d) nomor dan tahun keputusan, ditulis dengan huruf kapital secara simetris; e) kata penghubung tentang, ditulis dengan huruf kapital secara simetris; f) judul keputusan, ditulis dengan huruf kapital secara simetris; dan g) nama jabatan pejabat yang menetapkan keputusan, ditulis dengan huruf kapital dan diakhiri dengan tanda baca koma.
2) Konsiderans Bagian konsiderans keputusan terdiri atas: a) kata menimbang, yaitu konsiderans yang memuat alasan/tujuan/kepentingan/pertimbangan tentang perlu ditetapkannya keputusan; dan b) kata mengingat, yaitu konsiderans yang memuat peraturan perundang-undangan sebagai dasar kewenangan penetapan keputusan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4994, 'c. Susunan 1) Kepala Bagian kepala keputusan terdiri atas: a) kop keputusan yang ditandatangani oleh Kepala Badan Nasional Penanggulangan Bencana berisi lambang negara dan tulisan Kepala Badan Nasional Penanggulangan Bencana dan tulisan Badan Nasional Penanggulangan Bencana yang ditulis dengan huruf kapital diletakkan secara simetris; b) kop keputusan yang ditandatangani oleh pejabat selain Kepala menggunakan logo Badan Nasional Penanggulangan Bencana, dengan nama lembaga ditulis menggunakan huruf kapital diletakkan secara simetris; c) kata keputusan dan nama jabatan pejabat yang menetapkan, ditulis dengan huruf kapital secara simetris; d) nomor dan tahun keputusan, ditulis dengan huruf kapital secara simetris; e) kata penghubung tentang, ditulis dengan huruf kapital secara simetris; f) judul keputusan, ditulis dengan huruf kapital secara simetris; dan g) nama jabatan pejabat yang menetapkan keputusan, ditulis dengan huruf kapital dan diakhiri dengan tanda baca koma.
2) Konsiderans Bagian konsiderans keputusan terdiri atas: a) kata menimbang, yaitu konsiderans yang memuat alasan/tujuan/kepentingan/pertimbangan tentang perlu ditetapkannya keputusan; dan b) kata mengingat, yaitu konsiderans yang memuat peraturan perundang-undangan sebagai dasar kewenangan penetapan keputusan.', 'Lampiran hal. 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4995, 'perban-7-2020', 30, 'lampiran', 'Lampiran hal. 24', NULL, 24, '3) Diktum Bagian diktum keputusan terdiri atas: a) diktum dimulai dengan kata memutuskan yang ditulis dengan huruf kapital secara simetris dan diikuti kata menetapkan di tepi kiri sejajar dengan kata mengingat, menggunakan huruf awal kapital; b) substansi kebijakan yang ditetapkan dicantumkan setelah kata menetapkan yang ditulis dengan huruf kapital; c) nama yang tercantum dalam judul keputusan dicantumkan lagi setelah kata menetapkan yang ditulis dengan huruf awal kapital serta diakhiri dengan tanda baca titik; dan d) untuk keperluan tertentu, keputusan dapat dilengkapi dengan salinan dan petikan sesuai dengan peraturan perundang-undangan.
4) Batang Tubuh Diktum keputusan diuraikan bukan dalam pasal-pasal, melainkan diawali dengan bilangan bertingkat/diktum kesatu, kedua, ketiga, dan seterusnya yang ditulis seluruhnya dengan huruf kapital.
5) Kaki Bagian kaki keputusan terdiri atas: a) tempat (kota sesuai alamat instansi) dan tanggal penandatanganan keputusan; b) jabatan pejabat yang menetapkan, yang ditulis dengan huruf kapital, dan diakhiri dengan tanda baca koma; c) jabatan pejabat yang menetapkan, yang ditulis dengan huruf kapital, dan diakhiri dengan tanda baca koma; d) nama lengkap pejabat yang menandatangani keputusan, ditulis dengan huruf kapital tanpa mencantumkan gelar; dan e) cap dinas.
6) Lampiran (jika diperlukan)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4995, '3) Diktum Bagian diktum keputusan terdiri atas: a) diktum dimulai dengan kata memutuskan yang ditulis dengan huruf kapital secara simetris dan diikuti kata menetapkan di tepi kiri sejajar dengan kata mengingat, menggunakan huruf awal kapital; b) substansi kebijakan yang ditetapkan dicantumkan setelah kata menetapkan yang ditulis dengan huruf kapital; c) nama yang tercantum dalam judul keputusan dicantumkan lagi setelah kata menetapkan yang ditulis dengan huruf awal kapital serta diakhiri dengan tanda baca titik; dan d) untuk keperluan tertentu, keputusan dapat dilengkapi dengan salinan dan petikan sesuai dengan peraturan perundang-undangan.
4) Batang Tubuh Diktum keputusan diuraikan bukan dalam pasal-pasal, melainkan diawali dengan bilangan bertingkat/diktum kesatu, kedua, ketiga, dan seterusnya yang ditulis seluruhnya dengan huruf kapital.
5) Kaki Bagian kaki keputusan terdiri atas: a) tempat (kota sesuai alamat instansi) dan tanggal penandatanganan keputusan; b) jabatan pejabat yang menetapkan, yang ditulis dengan huruf kapital, dan diakhiri dengan tanda baca koma; c) jabatan pejabat yang menetapkan, yang ditulis dengan huruf kapital, dan diakhiri dengan tanda baca koma; d) nama lengkap pejabat yang menandatangani keputusan, ditulis dengan huruf kapital tanpa mencantumkan gelar; dan e) cap dinas.
6) Lampiran (jika diperlukan)', 'Lampiran hal. 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4996, 'perban-7-2020', 31, 'lampiran', 'Lampiran hal. 25', NULL, 25, 'd. Pengabsahan 1) Pengabsahan merupakan suatu pernyataan bahwa sebelum digandakan dan didistribusikan dengan sah. Suatu keputusan telah dicatat dan diteliti sehingga dapat diumumkan oleh pejabat yang bertanggung jawab di bidang hukum atau administrasi umum atau pejabat yang ditunjuk sesuai dengan substansi keputusan.
2) Pengabsahan dicantumkan di bawah ruang tanda tangan sebelah kiri bawah, yang terdiri atas frasa salinan sesuai dengan aslinya, nama lembaga, nama jabatan, tanda tangan, nama pejabat penanda tangan, dan dibubuhi cap dinas.
3) Pengabsahan sebagaimana tersebut pada angka 2 dibuatkan salinan yang ditandatangani oleh pejabat yang menerima pendelegasian wewenang.
e. Distribusi Keputusan yang telah ditetapkan didistribusikan kepada yang berkepentingan.
f. Hal yang perlu diperhatikan 1) Penyusunan rancangan keputusan dilakukan sesuai dengan teknik penyusunan peraturan perundang-undangan.
2) Naskah asli dan salinan keputusan yang ditandatangani harus disimpan sebagai arsip.
3) Pengajuan rancangan keputusan yang akan ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana atau Sekretaris Utama terlebih dahulu diparaf oleh pemrakarsa, pemeriksa, dan pejabat lain yang terkait menggunakan nota dinas sebagai pengantar.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4996, 'd. Pengabsahan 1) Pengabsahan merupakan suatu pernyataan bahwa sebelum digandakan dan didistribusikan dengan sah. Suatu keputusan telah dicatat dan diteliti sehingga dapat diumumkan oleh pejabat yang bertanggung jawab di bidang hukum atau administrasi umum atau pejabat yang ditunjuk sesuai dengan substansi keputusan.
2) Pengabsahan dicantumkan di bawah ruang tanda tangan sebelah kiri bawah, yang terdiri atas frasa salinan sesuai dengan aslinya, nama lembaga, nama jabatan, tanda tangan, nama pejabat penanda tangan, dan dibubuhi cap dinas.
3) Pengabsahan sebagaimana tersebut pada angka 2 dibuatkan salinan yang ditandatangani oleh pejabat yang menerima pendelegasian wewenang.
e. Distribusi Keputusan yang telah ditetapkan didistribusikan kepada yang berkepentingan.
f. Hal yang perlu diperhatikan 1) Penyusunan rancangan keputusan dilakukan sesuai dengan teknik penyusunan peraturan perundang-undangan.
2) Naskah asli dan salinan keputusan yang ditandatangani harus disimpan sebagai arsip.
3) Pengajuan rancangan keputusan yang akan ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana atau Sekretaris Utama terlebih dahulu diparaf oleh pemrakarsa, pemeriksa, dan pejabat lain yang terkait menggunakan nota dinas sebagai pengantar.', 'Lampiran hal. 25', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4997, 'perban-7-2020', 32, 'lampiran', 'Lampiran hal. 26', NULL, 26, '4) Keputusan tentang pembentukan tim, kelompok kerja dan sejenisnya dengan masa berlaku sampai dengan 1 (satu) tahun harus menyertakan nama dan jabatan. Sedangkan Keputusan tentang pembentukan tim, kelompok kerja dan sejenisnya dengan masa berlaku lebih dari 1 (satu) tahun cukup dengan menyertakan jabatan.
Format keputusan dapat dilihat pada Contoh 5A, 5B, 5C, 5D dan 5E.
Contoh 5A FORMAT KEPUTUSAN YANG DITANDATANGANI OLEH KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Lambang negara dan tulisan Kepala BNPB yang telah dicetak KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Penomoran yang berurutan dalam satu KEPUTUSAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA tahun takwin NOMOR … TAHUN … Judul TENTANG Keputusan ditulis ……………………………………………………………………. dengan huruf kapital tanpa diakhiri tanda baca KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, Memuat alasan Menimbang : a. bahwa ………………………………………………………………….; tentang perlunya
b. bahwa ………………………………………………………………….; ditetapkannya Keputusan Mengingat : 1. ………………………………………………………………………….; Memuat peraturan
2. ………………………………………………………………………….; yang menjadi dasar ditetapkanny MEMUTUSKAN a Keputusan Menetapkan : KEPUTUSAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG……………………………………………………..');
