INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (4999, 'perban-7-2020', 34, 'lampiran', 'Lampiran hal. 28', NULL, 28, '2. ………………………………………………………………………….; Memuat peraturan yang menjadi dasar MEMUTUSKAN ditetapkannya Menetapkan : KEPUTUSAN KEPALA BADAN NASIONAL PENANGGULANGAN Keputusan BENCANA TENTANG…………………………………………………….. Memuat substansi KESATU : ………………………………………………………………………………. tentang KEDUA : ………………………………………………………………………………. kebijakan yang KETIGA : ………………………………………………………………………………. ditetapkan Kota sesuai Ditetapkan di ……………………. dengan alamat pada tanggal ……………………. instansi dan tanggal penandatanga KEPALA BADAN NASIONAL nan PENANGGULANGAN BENCANA, Nama jabatan dan nama lengkap yang ttd. ditulis dengan huruf kapital tanpa gelar NAMA LENGKAP Salinan keputusan Salinan sesuai dengan aslinya memuat tulisan BADAN NASIONAL PENANGGULANGAN BENCANA ‘Salinan sesuai dengan Nama Jabatan, aslinya’, nama lembaga, nama jabatan, tanda tangan dan cap instansi tanda tangan, cap dinas dan nama penanda Nama Lengkap tangan salinan.
Contoh 5C FORMAT KEPUTUSAN YANG DITANDATANGANI OLEH SELAIN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Logo BNPB dan tulisan BNPB yang telah dicetak Tulisan Keputusan yang diikuti jabatan BADAN NASIONAL PENANGGULANGAN BENCANA penanda tangan Penomoran yang KEPUTUSAN SEKRETARIS UTAMA berurutan BADAN NASIONAL PENANGGULANGAN BENCANA dalam satu tahun takwin NOMOR … TAHUN … TENTANG Judul Keputusan ……………………………………………………………………. yang ditulis dengan huruf kapital SEKRETARIS UTAMA BADAN NASIONAL PENANGGULANGAN BENCANA, Memuat alasan tentang Menimbang : a. bahwa ………………………………………………………..……….; perlunya');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (4999, '2. ………………………………………………………………………….; Memuat peraturan yang menjadi dasar MEMUTUSKAN ditetapkannya Menetapkan : KEPUTUSAN KEPALA BADAN NASIONAL PENANGGULANGAN Keputusan BENCANA TENTANG…………………………………………………….. Memuat substansi KESATU : ………………………………………………………………………………. tentang KEDUA : ………………………………………………………………………………. kebijakan yang KETIGA : ………………………………………………………………………………. ditetapkan Kota sesuai Ditetapkan di ……………………. dengan alamat pada tanggal ……………………. instansi dan tanggal penandatanga KEPALA BADAN NASIONAL nan PENANGGULANGAN BENCANA, Nama jabatan dan nama lengkap yang ttd. ditulis dengan huruf kapital tanpa gelar NAMA LENGKAP Salinan keputusan Salinan sesuai dengan aslinya memuat tulisan BADAN NASIONAL PENANGGULANGAN BENCANA ‘Salinan sesuai dengan Nama Jabatan, aslinya’, nama lembaga, nama jabatan, tanda tangan dan cap instansi tanda tangan, cap dinas dan nama penanda Nama Lengkap tangan salinan.
Contoh 5C FORMAT KEPUTUSAN YANG DITANDATANGANI OLEH SELAIN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Logo BNPB dan tulisan BNPB yang telah dicetak Tulisan Keputusan yang diikuti jabatan BADAN NASIONAL PENANGGULANGAN BENCANA penanda tangan Penomoran yang KEPUTUSAN SEKRETARIS UTAMA berurutan BADAN NASIONAL PENANGGULANGAN BENCANA dalam satu tahun takwin NOMOR … TAHUN … TENTANG Judul Keputusan ……………………………………………………………………. yang ditulis dengan huruf kapital SEKRETARIS UTAMA BADAN NASIONAL PENANGGULANGAN BENCANA, Memuat alasan tentang Menimbang : a. bahwa ………………………………………………………..……….; perlunya', 'Lampiran hal. 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5000, 'perban-7-2020', 35, 'lampiran', 'Lampiran hal. 29', NULL, 29, 'b. bahwa ……………………………………………………..………….; ditetapkannya Keputusan.
Memuat Mengingat : 1. …………………………………………………………..……………..; peraturan yang menjadi
2. ………………………………………………………..………………..; dasar penetapan keputusan MEMUTUSKAN:
Menetapkan : KEPUTUSAN …………TENTANG ………………………..…………..… …………………………………………………………………………..……; Memuat substansi KESATU ……………….………………………..…………………………......……… tentang kebijakan ……………………………………………………………………..…………; yang ditetapkan KEDUA …………… …………………………..………………………...…………… ………………………………………………………………..………………;
KETIGA …………… …………………………..……………………………………… ……………………………………………………………………………..…;
Kota sesuai dengan Ditetapkan di ……………… alamat pada tanggal ……………….. instansi dan tanggal penandatang anan NAMA JABATAN, Nama jabatan Tanda tangan dan cap instansi dan nama lengkap yang ditulis dengan huruf NAMA LENGKAP kapital.
CONTOH 5D FORMAT SALINAN KEPUTUSAN YANG DITANDATANGANI OLEH SELAIN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Logo BNPB dan tulisan BNPB yang telah dicetak Tulisan Keputusan yang diikuti BADAN NASIONAL PENANGGULANGAN BENCANA jabatan penanda tangan Kata ‘salinan’ KEPUTUSAN SEKRETARIS UTAMA SALINAN Penomoran yang BADAN NASIONAL PENANGGULANGAN BENCANA berurutan dalam satu NOMOR … TAHUN … tahun takwin TENTANG ……………………………………………………………………. Judul Keputusan yang ditulis dengan huruf SEKRETARIS UTAMA BADAN NASIONAL PENANGGULANGAN BENCANA, kapital Menimbang : a. bahwa ………………………………………………………..…….....; Memuat alasan');
