INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5003, 'perban-7-2020', 38, 'lampiran', 'Lampiran hal. 32', NULL, 32, '(7) tulisan nama jabatan yang menetapkan instruksi yang ditulis dengan huruf kapital dan diakhiri dengan tanda baca koma secara simetris, b) Konsiderans Bagian konsiderans instruksi terdiri atas:
(1) kata Menimbang, yang memuat latar belakang penetapan instruksi; dan
(2) kata Mengingat, yang memuat dasar hukum sebagai landasan penetapan instruksi. c) Batang Tubuh Bagian batang tubuh instruksi terdiri atas:
(1) frasa ‘dalam rangka’ yang diteruskan dengan pertimbangan/alasan pemberian instruksi disambung dengan tanda baca koma yang kemudian dilanjutkan dengan frasa ‘dengan ini memberi instruksi’ tanpa tanda baca;
(2) kata kepada yang dilanjutkan dengan tanda baca titik dua dan daftar pejabat yang diberi instruksi;
(3) kata ‘untuk’ yang dihubungkan dengan tanda baca titik dua; dan
(4) subtansi yang dijabarkan bukan dalam pasal-pasal melainkan dengan bilangan bertingkat, diktum Kesatu, Kedua, Ketiga, dan seterusnya yang ditulis dengan huruf kapital. d) Kaki Bagian kaki instruksi ditempatkan di sebelah kanan bawah terdiri atas:
(1) tempat (kota sesuai alamat instansi) dan tanggal penandatanganan instruksi;
(2) nama jabatan pejabat yang menetapkan instruksi, yang ditulis dengan huruf kapital dan diakhiri dengan tanda baca koma;
(3) tanda tangan pejabat yang menetapkan Instruksi dibubuhi cap dinas; dan
(4) nama lengkap pejabat yang menandatangani Instruksi, ditulis dengan huruf kapital, tanpa mencantumkan gelar.');
