INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5004, 'perban-7-2020', 39, 'lampiran', 'Lampiran hal. 33', NULL, 33, '4) Distribusi dan Tembusan a) Instruksi yang telah ditetapkan disampaikan kepada pihak yang mendapat instruksi. b) Tembusan instruksi disampaikan kepada pejabat/instansi yang terkait.
5) Hal yang perlu diperhatikan a) Instruksi merupakan pelaksanaan kebijakan pokok sehingga instruksi harus merujuk pada suatu peraturan perundang-undangan. b) Wewenang penetapan dan penanda tangan instruksi tidak dapat dilimpahkan kepada pejabat lain.
