INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5007, 'perban-7-2020', 42, 'lampiran', 'Lampiran hal. 37', NULL, 37, '(3) kata surat perintah ditulis dengan huruf kapital secara simetris; dan
(4) kata nomor yang berada di bawah tulisan surat perintah, ditulis dengan huruf kapital secara simetris. b) Batang Tubuh Bagian batang tubuh surat perintah terdiri atas:
(1) konsiderans meliputi pertimbangan dan/atau dasar, pertimbangan memuat alasan atau tujuan ditetapkannya surat perintah, sedangkan dasar memuat ketentuan yang dijadikan landasan ditetapkannya Surat Perintah tersebut; dan
(2) diktum dimulai dengan frasa memberi perintah, yang ditulis dengan huruf awal kapital dicantumkan secara simetris, diikuti kata kepada di tepi kiri disertai nama dan jabatan pegawai yang mendapat tugas dan substansi arahan yang diperintahkan; c) Kaki Bagian kaki surat perintah terdiri atas:
(1) tempat (kota sesuai alamat instansi) dan tanggal penandatanganan surat perintah;
(2) nama jabatan pejabat yang menandatangani, ditulis dengan huruf awal kapital pada setiap awal unsurnya, dan diakhiri dengan tanda baca koma;
(3) tanda tangan pejabat yang memerintahkan;
(4) nama lengkap pejabat yang menandatangani surat perintah, ditulis dengan huruf awal kapital pada setiap awal unsurnya; dan
(5) cap dinas.
4) Distribusi dan Tembusan a) Surat perintah disampaikan kepada pihak yang mendapat perintah. b) Tembusan surat perintah disampaikan kepada pejabat/instansi yang terkait.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5007, '(3) kata surat perintah ditulis dengan huruf kapital secara simetris; dan
(4) kata nomor yang berada di bawah tulisan surat perintah, ditulis dengan huruf kapital secara simetris. b) Batang Tubuh Bagian batang tubuh surat perintah terdiri atas:
(1) konsiderans meliputi pertimbangan dan/atau dasar, pertimbangan memuat alasan atau tujuan ditetapkannya surat perintah, sedangkan dasar memuat ketentuan yang dijadikan landasan ditetapkannya Surat Perintah tersebut; dan
(2) diktum dimulai dengan frasa memberi perintah, yang ditulis dengan huruf awal kapital dicantumkan secara simetris, diikuti kata kepada di tepi kiri disertai nama dan jabatan pegawai yang mendapat tugas dan substansi arahan yang diperintahkan; c) Kaki Bagian kaki surat perintah terdiri atas:
(1) tempat (kota sesuai alamat instansi) dan tanggal penandatanganan surat perintah;
(2) nama jabatan pejabat yang menandatangani, ditulis dengan huruf awal kapital pada setiap awal unsurnya, dan diakhiri dengan tanda baca koma;
(3) tanda tangan pejabat yang memerintahkan;
(4) nama lengkap pejabat yang menandatangani surat perintah, ditulis dengan huruf awal kapital pada setiap awal unsurnya; dan
(5) cap dinas.
4) Distribusi dan Tembusan a) Surat perintah disampaikan kepada pihak yang mendapat perintah. b) Tembusan surat perintah disampaikan kepada pejabat/instansi yang terkait.', 'Lampiran hal. 37', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5008, 'perban-7-2020', 43, 'lampiran', 'Lampiran hal. 38', NULL, 38, '5) Hal yang perlu diperhatikan a) Jika perintah itu merupakan perintah kolektif, daftar pegawai yang diberi perintah dimasukkan ke dalam lampiran yang terdiri atas kolom nomor urut, nama, pangkat, nomor induk pegawai, jabatan, dan keterangan. b) Surat Perintah tidak berlaku lagi setelah perintah yang termuat selesai dilaksanakan. c) Penomoran Surat Perintah dilakukan dengan mencantumkan nomor surat perintah, kode jabatan penanda tangan, kode klasifikasi arsip, bulan, dan tahun.
Format Surat Perintah dapat dilihat pada Contoh 7A, 7B, 7C dan 7D.
Contoh 7A FORMAT SURAT PERINTAH YANG DITANDATANGANI OLEH KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Lambang negara dan tulisan kepala BNPB yang telah KEPALA dicetak BADAN NASIONAL PENANGGULANGAN BENCANA Penomoran yang SURAT PERINTAH berurutan dalam satu NOMOR … / …/ …/ …/ … tahun takwin Menimbang : a. bahwa ………………………………………………………..……….; Memuat alasan
b. bahwa ……………………………………………………..………….; perlunya ditetapkanny a Surat Dasar : 1. …………………………………………………………..………………; Perintah,
2. ………………………………………………………..…………………;
Memuat peraturan/ dasar Memberi Perintah penetapan Kepada : 1. nama : ……………………………… Surat Perintah NIP : ……………………………… pangkat, gol. Ruang : ……………………………… Daftar pejabat yang jabatan : ……………………………… menerima perintah
