INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5017, 'perban-7-2020', 52, 'lampiran', 'Lampiran hal. 49', NULL, 49, '(2) kata nota dinas ditulis dengan huruf kapital secara simetris;
(3) kata nomor ditulis dengan huruf kapital secara simetris; dan
(4) singkatan yth., kata dari, hal dan tanggal ditulis dengan huruf awal kapital diikuti dengan tanda baca titik dua yang diletakkan sebelah kiri atas. b) Batang Tubuh Bagian batang tubuh nota dinas terdiri atas alinea pembuka, isi, dan penutup secara singkat, padat, dan jelas. c) Kaki Bagian kaki nota dinas terdiri atas tanda tangan, nama pejabat, dan tembusan (jika diperlukan).
4) Hal yang perlu diperhatikan a) Nota dinas tidak dibubuhi cap dinas. b) Tembusan nota dinas berlaku di lingkungan Badan Nasional Penanggulangan Bencana. c) Penomoran nota dinas dilakukan dengan mencantumkan nomor nota dinas, kode jabatan penanda tangan, kode klasifikasi arsip, bulan, dan tahun.
Format nota dinas dapat dilihat pada Contoh 9.
