INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5026, 'perban-7-2020', 61, 'lampiran', 'Lampiran hal. 60', NULL, 60, 'a. Pengertian Surat undangan adalah surat dinas yang memuat undangan kepada pejabat/pegawai yang tersebut pada alamat tujuan untuk menghadiri suatu acara kedinasan tertentu, seperti rapat, upacara, dan pertemuan.
b. Kewenangan Surat undangan ditandatangani oleh pejabat sesuai dengan tugas, fungsi, wewenang, dan tanggung jawabnya.
c. Susunan 1) Kepala Bagian kepala surat undangan terdiri atas: a) kop surat undangan yang ditandatangani Kepala Badan Nasional Penanggulangan Bencana menggunakan lambang negara dan tulisan Kepala Badan Nasional Penanggulangan Bencana yang ditulis dengan huruf kapital secara simetris; b) kop surat undangan yang ditandatangani oleh selain Kepala Badan Nasional Penanggulangan Bencana menggunakan logo Badan Nasional Penanggulangan Bencana dan tulisan Badan Nasional Penanggulangan Bencana yang ditulis dengan huruf kapital secara simetris; c) kop surat undangan internal menggunakan tulisan Badan Nasional Penanggulangan Bencana dan nama unit kerja; d) kata nomor, sifat, lampiran, dan hal, diketik di sebelah kiri di bawah kop surat undangan; e) kata tempat dan tanggal pembuatan surat, diketik di sebelah kanan atas sejajar/sebaris dengan nomor; dan f) singkatan Yth., ditulis di bawah hal, diikuti dengan nama jabatan, dan alamat yang dikirimi surat (jika diperlukan).
2) Batang Tubuh Bagian batang tubuh surat undangan terdiri atas: a) alinea pembuka; b) isi undangan yang meliputi hari, tanggal, waktu, tempat, dan acara; dan c) alinea penutup.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5026, 'a. Pengertian Surat undangan adalah surat dinas yang memuat undangan kepada pejabat/pegawai yang tersebut pada alamat tujuan untuk menghadiri suatu acara kedinasan tertentu, seperti rapat, upacara, dan pertemuan.
b. Kewenangan Surat undangan ditandatangani oleh pejabat sesuai dengan tugas, fungsi, wewenang, dan tanggung jawabnya.
c. Susunan 1) Kepala Bagian kepala surat undangan terdiri atas: a) kop surat undangan yang ditandatangani Kepala Badan Nasional Penanggulangan Bencana menggunakan lambang negara dan tulisan Kepala Badan Nasional Penanggulangan Bencana yang ditulis dengan huruf kapital secara simetris; b) kop surat undangan yang ditandatangani oleh selain Kepala Badan Nasional Penanggulangan Bencana menggunakan logo Badan Nasional Penanggulangan Bencana dan tulisan Badan Nasional Penanggulangan Bencana yang ditulis dengan huruf kapital secara simetris; c) kop surat undangan internal menggunakan tulisan Badan Nasional Penanggulangan Bencana dan nama unit kerja; d) kata nomor, sifat, lampiran, dan hal, diketik di sebelah kiri di bawah kop surat undangan; e) kata tempat dan tanggal pembuatan surat, diketik di sebelah kanan atas sejajar/sebaris dengan nomor; dan f) singkatan Yth., ditulis di bawah hal, diikuti dengan nama jabatan, dan alamat yang dikirimi surat (jika diperlukan).
2) Batang Tubuh Bagian batang tubuh surat undangan terdiri atas: a) alinea pembuka; b) isi undangan yang meliputi hari, tanggal, waktu, tempat, dan acara; dan c) alinea penutup.', 'Lampiran hal. 60', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5027, 'perban-7-2020', 62, 'lampiran', 'Lampiran hal. 61', NULL, 61, '3) Kaki Bagian kaki surat undangan terdiri atas nama jabatan yang ditulis dengan huruf awal kapital, tanda tangan, dan nama pejabat yang ditulis dengan huruf awal kapital serta dibubuhi cap dinas.
d. Hal yang perlu diperhatikan 1) Format surat undangan sama dengan format surat dinas, yang membedakan adalah bahwa pihak yang dikirimi surat pada surat undangan dapat ditulis pada lampiran.
2) Surat undangan untuk keperluan tertentu dapat berbentuk kartu.
3) Pada akhir lampiran memuat nama jabatan dan nama pejabat yang ditulis dengan huruf awal kapital dan dibubuhi tanda tangan serta cap dinas.
4) Penomoran surat undangan mencantumkan nomor surat undangan, kode jabatan penanda tangan, kode klasifikasi arsip, bulan, dan tahun.
5) Apabila undangan tersebut diperuntukkan masih satu wilayah waktu, maka pada penulisan waktu/pukul tidak perlu menuliskan WIB/WITA/WIT.
Format surat undangan dapat dilihat pada Contoh 12A, 12B, 12C, 12D dan 12E.
Contoh 12A FORMAT SURAT UNDANGAN EKSTERN YANG DITANDATANGANI OLEH KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Lambang negara dan tulisan Kepala BNPB yang telah dicetak KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Tanggal pembuatan surat Nomor : B-..../KA BNPB/RT.06/07/2020 (Tgl., Bln., Thn.) Sifat : …………………. Penomoran yang berurutan Lampiran : …………………. dalam satu tahun takwin.
Hal : Undangan ……………..');
