INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5028, 'perban-7-2020', 63, 'lampiran', 'Lampiran hal. 62', NULL, 62, 'Yth. Ketua Komisi Pemilihan Umum Jalan …………………… Alamat tujuan yang ditulis Jakarta dibagian kiri, jika jumlahnya banyak, dapat Dengan Hormat, dibuat pada daftar lampiran ………………. (Alinea Pembuka dan Alinea Isi) …………………………... …………………………………………………………………………………….……… pada hari, tanggal : …………………….
