INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5031, 'perban-7-2020', 66, 'lampiran', 'Lampiran hal. 66', NULL, 66, '1. Surat Perjanjian Surat perjanjian adalah naskah dinas yang berisi kesepakatan bersama tentang objek yang mengikat antar kedua belah pihak atau lebih untuk melaksanakan tindakan atau perbuatan hukum yang telah disepakati bersama.
a. Perjanjian Dalam Negeri 1) Pengertian Kerja sama perjanjian dalam negeri antarlembaga di dalam negeri baik tingkat pusat maupun tingkat daerah dibuat dalam bentuk nota kesepahaman atau perjanjian kerja sama.
2) Wewenang Penetapan dan Penandatanganan Perjanjian yang dilakukan antarlembaga di dalam negeri baik lembaga pemerintah maupun lembaga nonpemerintah, baik di pusat maupun di daerah dibuat dan ditandatangani oleh pejabat sesuai dengan tugas, fungsi, wewenang, dan tanggung jawabnya.
3) Susunan a) Kepala Bagian kepala surat perjanjian dalam negeri terdiri atas:
(1) kop perjanjian dalam negeri antarlembaga pemerintah menggunakan lambang negara yang diletakkan secara simetris di bagian atas;
(2) kop perjanjian dalam negeri dengan institusi dalam negeri, baik lembaga pemerintah maupun lembaga nonpemerintah sepanjang para pihak bukan pejabat negara, menggunakan logo Badan Nasional Penanggulangan Bencana yang diletakkan di sebelah kanan dan kiri atas, disesuaikan dengan penyebutan nama instansi;
(3) nama instansi;
(4) judul perjanjian; dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5031, '1. Surat Perjanjian Surat perjanjian adalah naskah dinas yang berisi kesepakatan bersama tentang objek yang mengikat antar kedua belah pihak atau lebih untuk melaksanakan tindakan atau perbuatan hukum yang telah disepakati bersama.
a. Perjanjian Dalam Negeri 1) Pengertian Kerja sama perjanjian dalam negeri antarlembaga di dalam negeri baik tingkat pusat maupun tingkat daerah dibuat dalam bentuk nota kesepahaman atau perjanjian kerja sama.
2) Wewenang Penetapan dan Penandatanganan Perjanjian yang dilakukan antarlembaga di dalam negeri baik lembaga pemerintah maupun lembaga nonpemerintah, baik di pusat maupun di daerah dibuat dan ditandatangani oleh pejabat sesuai dengan tugas, fungsi, wewenang, dan tanggung jawabnya.
3) Susunan a) Kepala Bagian kepala surat perjanjian dalam negeri terdiri atas:
(1) kop perjanjian dalam negeri antarlembaga pemerintah menggunakan lambang negara yang diletakkan secara simetris di bagian atas;
(2) kop perjanjian dalam negeri dengan institusi dalam negeri, baik lembaga pemerintah maupun lembaga nonpemerintah sepanjang para pihak bukan pejabat negara, menggunakan logo Badan Nasional Penanggulangan Bencana yang diletakkan di sebelah kanan dan kiri atas, disesuaikan dengan penyebutan nama instansi;
(3) nama instansi;
(4) judul perjanjian; dan', 'Lampiran hal. 66', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5032, 'perban-7-2020', 67, 'lampiran', 'Lampiran hal. 67', NULL, 67, '(5) nomor. b) Batang Tubuh Bagian batang tubuh surat perjanjian dalam negeri memuat perjanjian yang dituangkan dalam bentuk pasal-pasal. c) Kaki Bagian kaki surat perjanjian dalam negeri terdiri atas nama penanda tangan para pihak yang mengadakan perjanjian dan para saksi (jika diperlukan) yang dibubuhi meterai sesuai dengan ketentuan peraturan perundang-undangan.
4) Hal yang perlu diperhatikan Perjanjian dalam negeri antarlembaga pemerintah yang menggunakan lambang negara hanya dapat ditandatangani oleh pejabat negara.
Format Perjanjian Dalam Negeri dapat dilihat pada Contoh 13A dan 13B.
