INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5034, 'perban-7-2020', 69, 'lampiran', 'Lampiran hal. 70', NULL, 70, 'Pasal 1 TUJUAN KERJA SAMA ……………………………………………………………………………………………....
