INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5042, 'perban-7-2020', 77, 'lampiran', 'Lampiran hal. 80', NULL, 80, '2. Nama : …………… jabatan Jabatan : …………… Selanjutnya disebut sebagai Pihak Kedua.
