INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5047, 'perban-7-2020', 82, 'lampiran', 'Lampiran hal. 86', NULL, 86, 'Penerima Pengirim Nama Jabatan, Nama Jabatan, Nama jabatan dan nama lengkap yang tanda tangan dan cap instansi tanda tangan dan cap instansi ditulis dalam huruf awal kapital Nama Lengkap Nama Lengkap NIP. ………………………. NIP. ……………………….
No. Telepon
6. Surat Pernyataan Pelaksanaan Kegiatan
a. Pengertian Surat pernyataan pelaksanaan kegiatan adalah naskah dinas yang berisi keterangan yang menyatakan bahwa telah dilaksanakannya sebuah kegiatan.
b. Wewenang Pembuatan dan Penandatanganan Surat pernyataan pelaksanaan kegiatan dibuat dan ditandatangani oleh pejabat yang sesuai dengan tugas, wewenang, dan tanggung jawabnya.
c. Susunan 1) Kepala Bagian kepala surat pernyataan pelaksanaan kegiatan terdiri atas: a) kop surat pernyataan pelaksanaan kegiatan menggunakan kop surat Badan Nasional Penanggulangan Bencana diletakkan secara simetris dan ditulis dengan huruf kapital; b) tulisan ‘surat pernyataan pelaksanaan kegiatan’ yang ditulis dengan huruf kapital diletakkan secara simetris; dan c) nomor surat pernyataan pelaksanaan kegiatan diletakkan secara sistematis.
2) Batang Tubuh a) Bagian batang tubuh surat pernyataan pelaksanaan kegiatan memuat nama pejabat yang menerangkan bahwa telah melakukan kegiatan. b) Kolom yang berisi:
(1) nomor urut;
(2) hari/tanggal;
(3) waktu;
(4) tempat; dan
(5) jumlah peserta.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5047, 'Penerima Pengirim Nama Jabatan, Nama Jabatan, Nama jabatan dan nama lengkap yang tanda tangan dan cap instansi tanda tangan dan cap instansi ditulis dalam huruf awal kapital Nama Lengkap Nama Lengkap NIP. ………………………. NIP. ……………………….
