INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5049, 'perban-7-2020', 84, 'lampiran', 'Lampiran hal. 89', NULL, 89, 'a. Pengertian Pengumuman adalah naskah dinas yang memuat pemberitahuan yang mendesak yang ditujukan kepada semua pejabat dan pegawai di lingkungan Badan Nasional Penanggulangan Bencana atau perseorangan dan golongan di dalam atau di luar Badan Nasional Penanggulangan Bencana.
b. Wewenang Pembuatan dan Penandatanganan Pengumuman dibuat dan ditandatangani oleh pejabat yang mengumumkan atau pejabat lain yang ditunjuk.
c. Susunan 1) Kepala Bagian kepala pengumuman terdiri atas: a) kop naskah dinas yang memuat logo Badan Nasional Penanggulangan Bencana dan tulisan Badan Nasional Penanggulangan Bencana yang ditulis dengan huruf kapital secara simetris; b) kata pengumuman dicantumkan di bawah logo Badan Nasional Penanggulangan Bencana, yang ditulis dengan huruf kapital secara simetris dan nomor pengumuman dicantumkan di bawahnya; c) kata tentang dicantumkan di bawah pengumuman ditulis dengan huruf kapital secara simetris; dan d) rumusan judul pengumuman ditulis dengan huruf kapital secara simetris di bawah kata tentang.
2) Batang Tubuh Bagian batang tubuh pengumuman terdiri atas: a) alasan tentang perlunya dibuat pengumuman; b) peraturan yang menjadi dasar pembuatan pengumuman; dan c) pemberitahuan tentang suatu hal tertentu yang mendesak.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5049, 'a. Pengertian Pengumuman adalah naskah dinas yang memuat pemberitahuan yang mendesak yang ditujukan kepada semua pejabat dan pegawai di lingkungan Badan Nasional Penanggulangan Bencana atau perseorangan dan golongan di dalam atau di luar Badan Nasional Penanggulangan Bencana.
