INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5057, 'perban-7-2020', 92, 'lampiran', 'Lampiran hal. 100', NULL, 100, '1. ……………. Tembusan (jika diperlukan)
