INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5059, 'perban-7-2020', 94, 'lampiran', 'Lampiran hal. 103', NULL, 103, '2) praanggapan, memuat dugaan yang beralasan berdasarkan data yang ada yang saling berhubungan sesuai dengan situasi yang dihadapi, dan merupakan kemungkinan kejadian di masa yang akan datang;
3) fakta yang mempengaruhi, memuat fakta yang merupakan landasan analisis dan pemecahan persoalan;
