INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5060, 'perban-7-2020', 95, 'lampiran', 'Lampiran hal. 104', NULL, 104, 'Contoh 24 FORMAT TELAAHAN STAF TELAAHAN STAF TENTANG ………………………………………………… A. Persoalan Bagian persoalan memuat pernyataan singkat dan jelas tentang persoalan yang akan dipecahkan B. Praanggapan Praanggapan memuat dugaan yang beralasan berdasarkan data dan saling berhubungan sesuai dengan situasi yang dihadapi dan merupakan kemungkinan keajadian dimasa mendatang C. Fakta yang mempengaruhi Bagian fakta yang mempengaruhi memuat fakta yang merupakan landasan analisis dan pemecahan persoalan D. Analisis Memuat analisis pengaruh praanggapan dan fakta terhadap persoalan serta akibatnya, hambatan serta keuntungan dan kerugiannya, serta pemecahan atau cara bertindak yang mungkin atau dapat dilakukan E. Simpulan Bagian simpulan memuat intisari hasil diskusi dan pilihan serta satu cara bertindak atau jalan keluar sebagai pemecahan persoalan yang dihadapi.
F. Saran Bagian saran memuat secara ringkas dan jelas tentang sarab tindakan untuk mengatasi persoalan yang dihadapi.
Nama Jabatan Pembuat Telaahan Staf, tanda tangan Nama Lengkap G. Formulir Formulir adalah bentuk pengaturan alokasi ruang atau lembar naskah untuk mencatat berbagai data dan informasi. Formulir dibuat dalam bentuk kartu atau lembaran tercetak dengan judul tertentu berisi keterangan yang diperlukan.
Format formulir dibuat dan disesuaikan dengan kebutuhan penggunanya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5060, 'Contoh 24 FORMAT TELAAHAN STAF TELAAHAN STAF TENTANG ………………………………………………… A. Persoalan Bagian persoalan memuat pernyataan singkat dan jelas tentang persoalan yang akan dipecahkan B. Praanggapan Praanggapan memuat dugaan yang beralasan berdasarkan data dan saling berhubungan sesuai dengan situasi yang dihadapi dan merupakan kemungkinan keajadian dimasa mendatang C. Fakta yang mempengaruhi Bagian fakta yang mempengaruhi memuat fakta yang merupakan landasan analisis dan pemecahan persoalan D. Analisis Memuat analisis pengaruh praanggapan dan fakta terhadap persoalan serta akibatnya, hambatan serta keuntungan dan kerugiannya, serta pemecahan atau cara bertindak yang mungkin atau dapat dilakukan E. Simpulan Bagian simpulan memuat intisari hasil diskusi dan pilihan serta satu cara bertindak atau jalan keluar sebagai pemecahan persoalan yang dihadapi.
F. Saran Bagian saran memuat secara ringkas dan jelas tentang sarab tindakan untuk mengatasi persoalan yang dihadapi.
Nama Jabatan Pembuat Telaahan Staf, tanda tangan Nama Lengkap G. Formulir Formulir adalah bentuk pengaturan alokasi ruang atau lembar naskah untuk mencatat berbagai data dan informasi. Formulir dibuat dalam bentuk kartu atau lembaran tercetak dengan judul tertentu berisi keterangan yang diperlukan.
Format formulir dibuat dan disesuaikan dengan kebutuhan penggunanya.', 'Lampiran hal. 104', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5061, 'perban-7-2020', 96, 'lampiran', 'Lampiran hal. 106', NULL, 106, 'BAB III PENYUSUNAN NASKAH DINAS A. Latar Belakang Setiap naskah dinas harus merupakan kebulatan pikiran yang jelas, padat, dan meyakinkan dalam susunan yang sistematis. Dalam penyusunannya perlu memperhatikan syarat-syarat sebagai berikut:
1. Ketelitian Dalam menyusun naskah dinas harus tercermin ketelitian dan kecermatan, dilihat dari bentuk, susunan pengetikan, isi, struktur, kaidah bahasa, dan penerapan kaidah ejaan di dalam pengetikan.
Kecermatan dan ketelitian sangat membantu pimpinan dalam mengurangi kesalahan pengambilan putusan/kebijakan.
2. Kejelasan Naskah dinas harus memperlihatkan kejelasan, aspek fisik, dan materi.
3. Singkat dan Padat Naskah dinas harus menggunakan bahasa Indonesia yang baik dan benar meliputi bahasa formal, efektif, singkat, padat, dan lengkap.
4. Logis dan Meyakinkan Naskah dinas harus runtut dan logis yang berarti bahwa penuangan gagasan ke dalam naskah dinas dilakukan menurut urutan yang logis dan meyakinkan. Struktur kalimat harus lengkap dan efektif sehingga memudahkan pemahaman penalaran bagi penerima naskah dinas.
5. Pembakuan Naskah dinas harus taat mengikuti aturan yang baku yang berlaku sesuai dengan tujuan pembuatan, baik dilihat dari sudut format maupun dari penggunaan bahasanya agar memudahkan dan memperlancar pemahaman isi naskah dinas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5061, 'BAB III PENYUSUNAN NASKAH DINAS A. Latar Belakang Setiap naskah dinas harus merupakan kebulatan pikiran yang jelas, padat, dan meyakinkan dalam susunan yang sistematis. Dalam penyusunannya perlu memperhatikan syarat-syarat sebagai berikut:
1. Ketelitian Dalam menyusun naskah dinas harus tercermin ketelitian dan kecermatan, dilihat dari bentuk, susunan pengetikan, isi, struktur, kaidah bahasa, dan penerapan kaidah ejaan di dalam pengetikan.
Kecermatan dan ketelitian sangat membantu pimpinan dalam mengurangi kesalahan pengambilan putusan/kebijakan.
2. Kejelasan Naskah dinas harus memperlihatkan kejelasan, aspek fisik, dan materi.
3. Singkat dan Padat Naskah dinas harus menggunakan bahasa Indonesia yang baik dan benar meliputi bahasa formal, efektif, singkat, padat, dan lengkap.
4. Logis dan Meyakinkan Naskah dinas harus runtut dan logis yang berarti bahwa penuangan gagasan ke dalam naskah dinas dilakukan menurut urutan yang logis dan meyakinkan. Struktur kalimat harus lengkap dan efektif sehingga memudahkan pemahaman penalaran bagi penerima naskah dinas.
5. Pembakuan Naskah dinas harus taat mengikuti aturan yang baku yang berlaku sesuai dengan tujuan pembuatan, baik dilihat dari sudut format maupun dari penggunaan bahasanya agar memudahkan dan memperlancar pemahaman isi naskah dinas.', 'Lampiran hal. 106', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5062, 'perban-7-2020', 97, 'lampiran', 'Lampiran hal. 106', NULL, 106, 'B. Nama Jabatan/Instansi pada Kepala Naskah Dinas Untuk memberikan identifikasi pada naskah dinas, pada halaman pertama naskah dinas dicantumkan kepala naskah dinas, yaitu nama jabatan atau nama instansi. Kepala nama jabatan digunakan untuk mengidentifikasikan bahwa naskah dinas ditetapkan oleh pejabat negara, sedangkan kepala nama instansi digunakan untuk mengidentifikasikan bahwa naskah dinas ditetapkan oleh pejabat yang bukan pejabat negara.
Pencantuman kepala naskah dinas adalah sebagai berikut:
1. Nama Jabatan Kertas dengan tulisan kepala nama jabatan dan lambang negara hanya digunakan untuk naskah dinas yang ditandatangani sendiri oleh Kepala Badan Nasional Penanggulangan Bencana. Kepala Nama Jabatan berturut-turut terdiri atas gambar lambang negara dan tulisan Kepala Badan Nasional Penanggulangan Bencana yang seluruhnya ditulis dengan huruf kapital, dicetak di bagian atas secara simetris. Perbandingan ukuran lambang negara dengan huruf yang digunakan hendaknya serasi dan sesuai dengan ukuran kertas.
2. Nama Instansi/Unit Organisasi Kertas kepala nama instansi dan logo instansi serta alamat lengkap digunakan untuk naskah dinas yang ditandatangani pejabat yang berwenang. Nama instansi berturut-turut terdiri atas logo Badan Nasional Penanggulangan Bencana dan tulisan Badan Nasional Penanggulangan Bencana yang seluruhnya ditulis dengan huruf kapital. Sedangkan alamat Badan Nasional Penanggulangan Bencana diletakkan di bawah tulisan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5062, 'B. Nama Jabatan/Instansi pada Kepala Naskah Dinas Untuk memberikan identifikasi pada naskah dinas, pada halaman pertama naskah dinas dicantumkan kepala naskah dinas, yaitu nama jabatan atau nama instansi. Kepala nama jabatan digunakan untuk mengidentifikasikan bahwa naskah dinas ditetapkan oleh pejabat negara, sedangkan kepala nama instansi digunakan untuk mengidentifikasikan bahwa naskah dinas ditetapkan oleh pejabat yang bukan pejabat negara.
Pencantuman kepala naskah dinas adalah sebagai berikut:
1. Nama Jabatan Kertas dengan tulisan kepala nama jabatan dan lambang negara hanya digunakan untuk naskah dinas yang ditandatangani sendiri oleh Kepala Badan Nasional Penanggulangan Bencana. Kepala Nama Jabatan berturut-turut terdiri atas gambar lambang negara dan tulisan Kepala Badan Nasional Penanggulangan Bencana yang seluruhnya ditulis dengan huruf kapital, dicetak di bagian atas secara simetris. Perbandingan ukuran lambang negara dengan huruf yang digunakan hendaknya serasi dan sesuai dengan ukuran kertas.
2. Nama Instansi/Unit Organisasi Kertas kepala nama instansi dan logo instansi serta alamat lengkap digunakan untuk naskah dinas yang ditandatangani pejabat yang berwenang. Nama instansi berturut-turut terdiri atas logo Badan Nasional Penanggulangan Bencana dan tulisan Badan Nasional Penanggulangan Bencana yang seluruhnya ditulis dengan huruf kapital. Sedangkan alamat Badan Nasional Penanggulangan Bencana diletakkan di bawah tulisan Badan Nasional Penanggulangan Bencana.', 'Lampiran hal. 106', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5063, 'perban-7-2020', 98, 'lampiran', 'Lampiran hal. 107', NULL, 107, 'C. Penomoran Naskah Dinas Nomor pada naskah dinas merupakan segmen penting dalam kearsipan. Oleh karena itu, susunannya harus dapat memberikan kemudahan penyimpanan, temu balik, dan penilaian arsip.
1. Nomor Naskah Dinas Arahan
a. Peraturan, Pedoman, Petunjuk Pelaksanaan, Keputusan, Arahan, Surat Edaran dan Instruksi Susunan nomor naskah dinas, peraturan, keputusan, surat edaran dan instruksi terdiri atas tulisan nomor, nomor naskah (nomor urut dalam satu tahun takwim), tulisan tahun dengan huruf kapital, dan tahun terbit.
Contoh penomoran peraturan:
PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR … TAHUN … TENTANG …………………………………………… …………………………………………… Contoh penomoran lampiran peraturan (jika diperlukan):
LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR … TAHUN … TENTANG … Contoh penomoran pedoman:
PEDOMAN …………………………….. ……………………………..
NOMOR … TAHUN … Contoh penomoran petunjuk pelaksanaan:
PETUNJUK PELAKSANAAN …………………………….. ……………………………..
NOMOR … TAHUN … Contoh penomoran keputusan:
KEPUTUSAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR … TAHUN … TENTANG …………………………………………… …………………………………………… Contoh penomoran lampiran keputusan:
LAMPIRAN KEPUTUSAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR … TAHUN … TENTANG … Contoh penomoran surat edaran:');
