INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5081, 'perban-7-2020', 116, 'lampiran', 'Lampiran hal. 129', NULL, 129, 'Yth. Sestama Diterima / Disetujui Yth. Irtama Diproses Sesuai Ketentuan Perundangan Yth. Deputi Bidang Sistem dan Strategi Proses Lebih Lanjut / Didukung / Dibantu Yth. Deputi Bidang Pencegahan Bicarakan Dengan Saya Yth. Deputi Bidang Penanganan Darurat Saya Hadir, Siapkan Bahan Yth. Deputi Bidang Rehabilitasi dan Rekonstruksi Wakili dan Laporkan Yth. Deputi Bidang Logistik dan Peralatan Buat Tanggapan dan Saran Yth. Kapusdatin dan Komunikasi Kebencanaan Pelajari / Kaji dan Laporkan ke Saya Yth. Kapusdiklat PB Edarkan ke Unit Terkait Yth. Karo Perencanaan Agendakan Waktunya Yth. Karo Keuangan Ikuti Perkembangannya Yth. Karo Hukum, Organisasi dan Kerja Sama Untuk Menjadi Perhatian Yth. Karo SDM dan Umum Pantau Yth. Kapusdalops Ingatkan Saya Yth. Tenaga Ahli Ditolak Simpan / Arsipkan CATATAN/DISPOSISI KEPALA Disposisi / Catatan SESTAMA / DEPUTI KEPALA BIRO / DIREKTUR BAB IV PENGURUSAN NASKAH DINAS KORESPONDENSI Korespondensi sangat penting untuk mendukung terselenggaranya tugas dan fungsi organisasi. Jika pelaksanaannya tidak diatur dengan cermat dan teliti, akan diperlukan banyak waktu dan biaya. Pengurusan naskah dinas korespondensi yang baik akan meningkatkan efektivitas dan efisiensi penyelenggaraan administrasi instansi pemerintah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5081, 'Yth. Sestama Diterima / Disetujui Yth. Irtama Diproses Sesuai Ketentuan Perundangan Yth. Deputi Bidang Sistem dan Strategi Proses Lebih Lanjut / Didukung / Dibantu Yth. Deputi Bidang Pencegahan Bicarakan Dengan Saya Yth. Deputi Bidang Penanganan Darurat Saya Hadir, Siapkan Bahan Yth. Deputi Bidang Rehabilitasi dan Rekonstruksi Wakili dan Laporkan Yth. Deputi Bidang Logistik dan Peralatan Buat Tanggapan dan Saran Yth. Kapusdatin dan Komunikasi Kebencanaan Pelajari / Kaji dan Laporkan ke Saya Yth. Kapusdiklat PB Edarkan ke Unit Terkait Yth. Karo Perencanaan Agendakan Waktunya Yth. Karo Keuangan Ikuti Perkembangannya Yth. Karo Hukum, Organisasi dan Kerja Sama Untuk Menjadi Perhatian Yth. Karo SDM dan Umum Pantau Yth. Kapusdalops Ingatkan Saya Yth. Tenaga Ahli Ditolak Simpan / Arsipkan CATATAN/DISPOSISI KEPALA Disposisi / Catatan SESTAMA / DEPUTI KEPALA BIRO / DIREKTUR BAB IV PENGURUSAN NASKAH DINAS KORESPONDENSI Korespondensi sangat penting untuk mendukung terselenggaranya tugas dan fungsi organisasi. Jika pelaksanaannya tidak diatur dengan cermat dan teliti, akan diperlukan banyak waktu dan biaya. Pengurusan naskah dinas korespondensi yang baik akan meningkatkan efektivitas dan efisiensi penyelenggaraan administrasi instansi pemerintah.', 'Lampiran hal. 129', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5082, 'perban-7-2020', 117, 'lampiran', 'Lampiran hal. 130', NULL, 130, 'A. Naskah Dinas Korespondensi Intern Pengurusan nota dinas/memorandum adalah pengelolaan nota dinas/memorandum yang diterima dan yang akan dikirim. Pengurusan nota dinas/memorandum itu dipusatkan pada kesekretariatan atau pada unit kerja masing-masing yang menyelenggarakan fungsi kesekretariatan untuk memudahkan pengawasan dan pengendaliannya.
B. Naskah Dinas Korespondensi Ekstern
1. Ketentuan Penyusunan Surat Dinas
a. Penyelenggaraan urusan kedinasan melalui surat-menyurat dinas harus dilaksanakan secara cermat dan teliti agar tidak menimbulkan salah penafsiran.
b. Urusan kedinasan yang dilakukan dengan menggunakan tata cara dan prosedur surat-menyurat harus menggunakan sarana komunikasi resmi.
c. Jawaban terhadap surat yang masuk 1) Instansi pengirim harus segera menginformasikan kepada penerima surat atas keterlambatan jawaban dalam suatu proses komunikasi; dan 2) Instansi penerima harus segera memberikan jawaban terhadap konfirmasi yang dilakukan oleh instansi pengirim.
2. Pengurusan Surat Masuk Surat masuk adalah semua surat dinas yang diterima. Untuk memudahkan pengawasan dan pengendalian, penerimaan surat masuk dipusatkan pada Bagian Tata Usaha dan Kearsipan, Biro SDM dan Umum Umum, Sekretaris Utama. Penanganan surat masuk dilaksanakan melalui tahapan berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5082, 'A. Naskah Dinas Korespondensi Intern Pengurusan nota dinas/memorandum adalah pengelolaan nota dinas/memorandum yang diterima dan yang akan dikirim. Pengurusan nota dinas/memorandum itu dipusatkan pada kesekretariatan atau pada unit kerja masing-masing yang menyelenggarakan fungsi kesekretariatan untuk memudahkan pengawasan dan pengendaliannya.
B. Naskah Dinas Korespondensi Ekstern
1. Ketentuan Penyusunan Surat Dinas
a. Penyelenggaraan urusan kedinasan melalui surat-menyurat dinas harus dilaksanakan secara cermat dan teliti agar tidak menimbulkan salah penafsiran.
b. Urusan kedinasan yang dilakukan dengan menggunakan tata cara dan prosedur surat-menyurat harus menggunakan sarana komunikasi resmi.
c. Jawaban terhadap surat yang masuk 1) Instansi pengirim harus segera menginformasikan kepada penerima surat atas keterlambatan jawaban dalam suatu proses komunikasi; dan 2) Instansi penerima harus segera memberikan jawaban terhadap konfirmasi yang dilakukan oleh instansi pengirim.
2. Pengurusan Surat Masuk Surat masuk adalah semua surat dinas yang diterima. Untuk memudahkan pengawasan dan pengendalian, penerimaan surat masuk dipusatkan pada Bagian Tata Usaha dan Kearsipan, Biro SDM dan Umum Umum, Sekretaris Utama. Penanganan surat masuk dilaksanakan melalui tahapan berikut:', 'Lampiran hal. 130', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5083, 'perban-7-2020', 118, 'lampiran', 'Lampiran hal. 131', NULL, 131, 'a. Penerimaan Surat masuk yang diterima dalam amplop tertutup dikelompokkan berdasarkan tingkat keamanan (SR, R, dan B) dan tingkat kecepatan penyampaiannya (kilat, sangat segera, segera, dan biasa). Selanjutnya, surat ditangani sesuai dengan tingkat keamanan dan tingkat kecepatan penyampaiannya.
b. Pencatatan 1) Surat masuk yang diterima diinput dalam komputer menurut tingkat keamanan.
2) Penginputan surat dinas yang mempunyai tingkat keamanan SR dan R dilakukan oleh pimpinan kesekretariatan atau pejabat tertentu yang mendapatkan kewenangan dari Kepala Badan Nasional Penanggulangan Bencana.
3) Pencatatan surat dinas yang mempunyai tingkat keamanan B dilakukan oleh Kepala Sub Bagian Persuratan Arsip dan Dokumentasi.
4) Pencatatan surat dilaksanakan dengan prioritas sesuai dengan tingkat kecepatan penyampaian.
5) Pencatatan dilakukan pula pada lembar disposisi dan buku tanda terima mengenai nomor agenda dan tanggal penerimaan.
6) Pencatatan surat masuk dimulai dari nomor 1 pada bulan Januari dan berakhir pada nomor terakhir dalam satu tahun, yaitu nomor terakhir pada tanggal 31 Desember.
7) Pencatatan surat selalu dilakukan pada setiap terjadi pemindahan dan penyimpanan.
c. Penilaian 1) Kegiatan penilaian surat masuk mulai dilaksanakan pada tahap pencatatan.
2) Pada tahap penilaian, surat dinilai apakah akan disampaikan kepada Sekretaris Utama/Kepala Badan Nasional Penanggulangan Bencana atau dapat disampaikan langsung kepada pejabat yang tertentu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5083, 'a. Penerimaan Surat masuk yang diterima dalam amplop tertutup dikelompokkan berdasarkan tingkat keamanan (SR, R, dan B) dan tingkat kecepatan penyampaiannya (kilat, sangat segera, segera, dan biasa). Selanjutnya, surat ditangani sesuai dengan tingkat keamanan dan tingkat kecepatan penyampaiannya.
b. Pencatatan 1) Surat masuk yang diterima diinput dalam komputer menurut tingkat keamanan.
2) Penginputan surat dinas yang mempunyai tingkat keamanan SR dan R dilakukan oleh pimpinan kesekretariatan atau pejabat tertentu yang mendapatkan kewenangan dari Kepala Badan Nasional Penanggulangan Bencana.
3) Pencatatan surat dinas yang mempunyai tingkat keamanan B dilakukan oleh Kepala Sub Bagian Persuratan Arsip dan Dokumentasi.
4) Pencatatan surat dilaksanakan dengan prioritas sesuai dengan tingkat kecepatan penyampaian.
5) Pencatatan dilakukan pula pada lembar disposisi dan buku tanda terima mengenai nomor agenda dan tanggal penerimaan.
6) Pencatatan surat masuk dimulai dari nomor 1 pada bulan Januari dan berakhir pada nomor terakhir dalam satu tahun, yaitu nomor terakhir pada tanggal 31 Desember.
7) Pencatatan surat selalu dilakukan pada setiap terjadi pemindahan dan penyimpanan.
c. Penilaian 1) Kegiatan penilaian surat masuk mulai dilaksanakan pada tahap pencatatan.
2) Pada tahap penilaian, surat dinilai apakah akan disampaikan kepada Sekretaris Utama/Kepala Badan Nasional Penanggulangan Bencana atau dapat disampaikan langsung kepada pejabat yang tertentu.', 'Lampiran hal. 131', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5084, 'perban-7-2020', 119, 'lampiran', 'Lampiran hal. 131', NULL, 131, '3) Selain penilaian penyampaian surat, dilakukan pula penilaian penanganan surat, apakah surat masuk itu akan diproses biasa atau melalui proses pemberkasan naskah.
4) Surat masuk yang beralamat pribadi (nama orang) dinilai termasuk surat yang harus disampaikan langsung kepada yang bersangkutan dalam keadaan amplop tertutup.
5) Penilaian dilakukan dengan berpedoman kepada tingkat keamanan dan tingkat kecepatan penyampaian surat.
d. Pengolahan 1) Pada tahap pengolahan, pimpinan/pejabat memutuskan tindakan yang akan diambil sehubungan dengan surat masuk tersebut.
2) Dari hasil pengolahan dapat diputuskan tindakan lanjutnya, yaitu langsung disimpan atau dibuat naskah dinas baru.
3) Pengolahan surat masuk dapat menggunakan proses pemberkasan naskah atau proses administrasi biasa sesuai dengan kebutuhan.
e. Penyimpanan 1) Surat dinas harus disimpan sedemikian rupa sehingga mudah ditemukan kembali jika diperlukan.
2) Surat masuk yang melalui proses pemberkasan naskah disimpan dalam berkas naskah dinas menurut bidang permasalahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5084, '3) Selain penilaian penyampaian surat, dilakukan pula penilaian penanganan surat, apakah surat masuk itu akan diproses biasa atau melalui proses pemberkasan naskah.
4) Surat masuk yang beralamat pribadi (nama orang) dinilai termasuk surat yang harus disampaikan langsung kepada yang bersangkutan dalam keadaan amplop tertutup.
5) Penilaian dilakukan dengan berpedoman kepada tingkat keamanan dan tingkat kecepatan penyampaian surat.
d. Pengolahan 1) Pada tahap pengolahan, pimpinan/pejabat memutuskan tindakan yang akan diambil sehubungan dengan surat masuk tersebut.
2) Dari hasil pengolahan dapat diputuskan tindakan lanjutnya, yaitu langsung disimpan atau dibuat naskah dinas baru.
3) Pengolahan surat masuk dapat menggunakan proses pemberkasan naskah atau proses administrasi biasa sesuai dengan kebutuhan.
e. Penyimpanan 1) Surat dinas harus disimpan sedemikian rupa sehingga mudah ditemukan kembali jika diperlukan.
2) Surat masuk yang melalui proses pemberkasan naskah disimpan dalam berkas naskah dinas menurut bidang permasalahan.', 'Lampiran hal. 131', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5085, 'perban-7-2020', 120, 'lampiran', 'Lampiran hal. 132', NULL, 132, '3) Surat masuk yang diproses tidak melalui proses pemberkasan, naskah dinas disimpan dalam himpunan sesuai dengan kebutuhan. Beberapa cara menghimpun surat adalah sebagai berikut: a) Seri adalah himpunan satu jenis surat dinas yang berdasarkan format surat atau jenis naskah dinas, misalnya keputusan, petunjuk pelaksanaan, dan surat edaran, disusun secara kronologis. Himpunan menurut seri selain dibatasi oleh kemampuan map juga dibatasi oleh tahun naskah dinas. b) Rubrik adalah himpunan dari satu macam masalah/hal/pokok persoalan yang disusun secara kronologis, misalnya cuti, kunjungan dinas, kerja lapangan. Himpunan menurut rubrik dibatasi dengan tahun atau dibatasi sampai dengan masalah selesai. c) Dosir adalah himpunan satu macam kegiatan atau persoalan yang disusun secara kronologis dari awal sampai akhir. Misalnya, berkas pegawai adalah himpunan naskah dinas mulai dari lamaran sampai dengan pemberhentian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5085, '3) Surat masuk yang diproses tidak melalui proses pemberkasan, naskah dinas disimpan dalam himpunan sesuai dengan kebutuhan. Beberapa cara menghimpun surat adalah sebagai berikut: a) Seri adalah himpunan satu jenis surat dinas yang berdasarkan format surat atau jenis naskah dinas, misalnya keputusan, petunjuk pelaksanaan, dan surat edaran, disusun secara kronologis. Himpunan menurut seri selain dibatasi oleh kemampuan map juga dibatasi oleh tahun naskah dinas. b) Rubrik adalah himpunan dari satu macam masalah/hal/pokok persoalan yang disusun secara kronologis, misalnya cuti, kunjungan dinas, kerja lapangan. Himpunan menurut rubrik dibatasi dengan tahun atau dibatasi sampai dengan masalah selesai. c) Dosir adalah himpunan satu macam kegiatan atau persoalan yang disusun secara kronologis dari awal sampai akhir. Misalnya, berkas pegawai adalah himpunan naskah dinas mulai dari lamaran sampai dengan pemberhentian.', 'Lampiran hal. 132', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5086, 'perban-7-2020', 121, 'lampiran', 'Lampiran hal. 133', NULL, 133, '4) Penyimpanan surat atau himpunan dilakukan sebagai berikut: a) Lateral adalah penyimpanan surat/himpunan yang diletakkan sedemikian rupa sehingga yang terlihat hanya bagian nisi camping, misalnya penyimpanan dalam ordner dan kotak arsip. b) Vertikal adalah penyimpanan surat/himpunan yang diletakkan sedemikian rupa sehingga yang terlihat hanya bagian muka, misalnya penyimpanan surat map pada lemari berkas. c) Horizontal adalah penyimpanan surat/himpunan yang diletakkan sedemikian rupa sehingga muka surat/himpunan terlihat di sebelah atas, misalnya penyimpanan peta atau gambar konstruksi.
5) Surat yang masih aktif, tetap berada di unit pengolah.
Setelah surat menjadi arsip inaktif, penyimpanannya harus sudah dialihkan ke unit kearsipan sesuai dengan ketentuan kearsipan yang berlaku.
f. Sarana Penanganan Surat Masuk Pencatatan adalah sarana utama pengendalian dan pengawasan surat masuk. Semua surat masuk pertama kali diinput dalam komputer, yang disusun dalam kolom catatan sebagai berikut:
1) tanggal;
2) nomor agenda;
3) nomor dan tanggal surat masuk;
4) lampiran;
5) alamat pengirim;
6) hal/isi surat; dan 7) keterangan
3. Pengurusan Surat Keluar Surat keluar yang ditandatangani oleh Kepala Badan Nasional Penanggulangan Bencana, atas nama Kepala Badan Nasional Penanggulangan Bencana, Sekretaris Utama dan atas nama Sekretaris Utama adalah semua surat dinas yang akan dikirim kepada pejabat yang tercantum pada alamat surat dinas dan amplop surat dinas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5086, '4) Penyimpanan surat atau himpunan dilakukan sebagai berikut: a) Lateral adalah penyimpanan surat/himpunan yang diletakkan sedemikian rupa sehingga yang terlihat hanya bagian nisi camping, misalnya penyimpanan dalam ordner dan kotak arsip. b) Vertikal adalah penyimpanan surat/himpunan yang diletakkan sedemikian rupa sehingga yang terlihat hanya bagian muka, misalnya penyimpanan surat map pada lemari berkas. c) Horizontal adalah penyimpanan surat/himpunan yang diletakkan sedemikian rupa sehingga muka surat/himpunan terlihat di sebelah atas, misalnya penyimpanan peta atau gambar konstruksi.
5) Surat yang masih aktif, tetap berada di unit pengolah.
Setelah surat menjadi arsip inaktif, penyimpanannya harus sudah dialihkan ke unit kearsipan sesuai dengan ketentuan kearsipan yang berlaku.
f. Sarana Penanganan Surat Masuk Pencatatan adalah sarana utama pengendalian dan pengawasan surat masuk. Semua surat masuk pertama kali diinput dalam komputer, yang disusun dalam kolom catatan sebagai berikut:
1) tanggal;
2) nomor agenda;
3) nomor dan tanggal surat masuk;
4) lampiran;
5) alamat pengirim;
6) hal/isi surat; dan 7) keterangan
3. Pengurusan Surat Keluar Surat keluar yang ditandatangani oleh Kepala Badan Nasional Penanggulangan Bencana, atas nama Kepala Badan Nasional Penanggulangan Bencana, Sekretaris Utama dan atas nama Sekretaris Utama adalah semua surat dinas yang akan dikirim kepada pejabat yang tercantum pada alamat surat dinas dan amplop surat dinas.', 'Lampiran hal. 133', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5087, 'perban-7-2020', 122, 'lampiran', 'Lampiran hal. 134', NULL, 134, 'Penanganan surat keluar, pencatatan/pengeditan, pemberian nomor, dan cap dan pengiriman surat keluar dipusatkan di Bagian Tata Usaha dan Kearsipan, Biro Sumber Daya Manusia dan Umum, Sekretaris Utama.
Penanganan surat keluar dilakukan melalui tahap sebagai berikut:
a. Pengolahan 1) Kegiatan pengolahan dimulai dari penyiapan hingga ke penandatanganan surat dinas. Penyiapan surat keluar dilaksanakan, antara lain karena: a) adanya kebijaksanaan pimpinan; b) reaksi atas suatu aksi; dan c) adanya konsep baru.
2) Penyiapan/penyusunan konsep surat keluar adalah sebagai berikut: a) Penyiapan/penyusunan konsep dilakukan oleh pejabat/pegawai yang membidanginya, sekretaris/pimpinan sekretariat atau pejabat yang ditunjuk. b) Setiap konsep yang disiapkan harus didasarkan pada kebijaksanaan dan pengarahan pimpinan. c) Setiap konsep yang akan diajukan kepada pimpinan terlebih dahulu harus diteliti oleh sekretaris/pimpinan sekretariat atau pejabat yang diserahi wewenang.
Sesuai dengan petunjuk pimpinan atau menurut pertimbangannya sendiri terhadap isi surat dinas, sekretaris pimpinan sekretariat menetapkan tingkat kecepatan penyampaian dan tingkat keamanan surat. d) Setiap konsep surat dinas sebelum ditandatangani oleh pejabat yang berwenang dibubuhi paraf terlebih dahulu oleh para pejabat dua tingkat di bawahnya yang bertugas menyiapkan konsep surat dinas tersebut. e) Letak pembubuhan paraf diatur sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5087, 'Penanganan surat keluar, pencatatan/pengeditan, pemberian nomor, dan cap dan pengiriman surat keluar dipusatkan di Bagian Tata Usaha dan Kearsipan, Biro Sumber Daya Manusia dan Umum, Sekretaris Utama.
Penanganan surat keluar dilakukan melalui tahap sebagai berikut:
a. Pengolahan 1) Kegiatan pengolahan dimulai dari penyiapan hingga ke penandatanganan surat dinas. Penyiapan surat keluar dilaksanakan, antara lain karena: a) adanya kebijaksanaan pimpinan; b) reaksi atas suatu aksi; dan c) adanya konsep baru.
2) Penyiapan/penyusunan konsep surat keluar adalah sebagai berikut: a) Penyiapan/penyusunan konsep dilakukan oleh pejabat/pegawai yang membidanginya, sekretaris/pimpinan sekretariat atau pejabat yang ditunjuk. b) Setiap konsep yang disiapkan harus didasarkan pada kebijaksanaan dan pengarahan pimpinan. c) Setiap konsep yang akan diajukan kepada pimpinan terlebih dahulu harus diteliti oleh sekretaris/pimpinan sekretariat atau pejabat yang diserahi wewenang.
Sesuai dengan petunjuk pimpinan atau menurut pertimbangannya sendiri terhadap isi surat dinas, sekretaris pimpinan sekretariat menetapkan tingkat kecepatan penyampaian dan tingkat keamanan surat. d) Setiap konsep surat dinas sebelum ditandatangani oleh pejabat yang berwenang dibubuhi paraf terlebih dahulu oleh para pejabat dua tingkat di bawahnya yang bertugas menyiapkan konsep surat dinas tersebut. e) Letak pembubuhan paraf diatur sebagai berikut:', 'Lampiran hal. 134', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5088, 'perban-7-2020', 123, 'lampiran', 'Lampiran hal. 134', NULL, 134, '(1) Paraf pejabat yang berada dua tingkat di bawah pejabat penanda tangan surat dinas dibubuhkan di sebelah kiri/sebelum nama pejabat penanda tangan surat.
(2) Paraf pejabat yang berada satu tingkat di bawah pejabat penanda tangan surat dinas dibubuhkan di sebelah kanan/setelah nama pejabat penanda tangan.
(3) Setelah surat dinas diparaf oleh pejabat yang bersangkutan dan tidak lagi mengandung kekurangan/kesalahan yang perlu diperbaiki, proses selanjutnya adalah:
(a) pengajuan kepada pejabat yang akan menandatangani surat;
(b) penandatanganan oleh pejabat yang bersangkutan;
(c) pembubuhan cap; dan
(d) pemberian nomor.
(4) Beberapa jenis surat tertentu dengan kebijakan atasan memerlukan format paraf khusus dari pejabat tinggi.
Contoh:
Persetujuan No. Jabatan Paraf 1 Sestama 2 Irtama 3 Deputi I 4 Deputi II 5 Deputi III 6 Deputi IV 7 Deputi V
b. Pencatatan Semua surat keluar diinput pada komputer yang bentuk, susunan, dan tata cara pencatatannya sesuai dengan peraturan perundang-undangan.
c. Penggandaan 1) Penggandaan adalah kegiatan memperbanyak surat dinas dengan sarana reproduksi yang tersedia sesuai dengan banyaknya alamat yang dituju.
2) Penggandaan hanya dilakukan setelah surat keluar ditandatangani oleh pejabat yang berhak.
3) Cap dinas yang dibubuhkan pada hasil penggandaan harus asli (bukan salinan).
4) Jumlah yang digandakan sesuai dengan alamat yang dituju (alamat distribusi).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5088, '(1) Paraf pejabat yang berada dua tingkat di bawah pejabat penanda tangan surat dinas dibubuhkan di sebelah kiri/sebelum nama pejabat penanda tangan surat.
(2) Paraf pejabat yang berada satu tingkat di bawah pejabat penanda tangan surat dinas dibubuhkan di sebelah kanan/setelah nama pejabat penanda tangan.
(3) Setelah surat dinas diparaf oleh pejabat yang bersangkutan dan tidak lagi mengandung kekurangan/kesalahan yang perlu diperbaiki, proses selanjutnya adalah:
(a) pengajuan kepada pejabat yang akan menandatangani surat;
(b) penandatanganan oleh pejabat yang bersangkutan;
(c) pembubuhan cap; dan
(d) pemberian nomor.
(4) Beberapa jenis surat tertentu dengan kebijakan atasan memerlukan format paraf khusus dari pejabat tinggi.
Contoh:
Persetujuan No. Jabatan Paraf 1 Sestama 2 Irtama 3 Deputi I 4 Deputi II 5 Deputi III 6 Deputi IV 7 Deputi V
b. Pencatatan Semua surat keluar diinput pada komputer yang bentuk, susunan, dan tata cara pencatatannya sesuai dengan peraturan perundang-undangan.
c. Penggandaan 1) Penggandaan adalah kegiatan memperbanyak surat dinas dengan sarana reproduksi yang tersedia sesuai dengan banyaknya alamat yang dituju.
2) Penggandaan hanya dilakukan setelah surat keluar ditandatangani oleh pejabat yang berhak.
3) Cap dinas yang dibubuhkan pada hasil penggandaan harus asli (bukan salinan).
4) Jumlah yang digandakan sesuai dengan alamat yang dituju (alamat distribusi).', 'Lampiran hal. 134', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5089, 'perban-7-2020', 124, 'lampiran', 'Lampiran hal. 136', NULL, 136, '5) Penggandaan surat keluar yang tingkat kecepatan penyampaiannya kilat dan sangat segera harus didahulukan.
6) Penggandaan surat keluar yang tingkat keamanannya sangat rahasia/rahasia harus diawasi dengan ketat.
7) Sekretaris/pimpinan sekretariat berkewajiban menjaga agar penggandaan sesuai kebutuhan.
d. Pengiriman 1) Surat keluar yang akan dikirimkan dimasukkan ke dalam amplop surat.
2) Pada amplop surat keluar yang tingkat keamanannya biasa (B), rahasia (R), dan sangat rahasia (SR) dicantumkan alamat lengkap, nomor surat dinas, dan cap yang sesuai dengan tingkat kecepatan penyampaian (kilat/segera/sangat segera/biasa).
3) Surat yang tingkat keamanannya sangat rahasia atau rahasia dimasukkan ke dalam amplop, dibubuhi alamat lengkap, nomor surat dinas, cap dinas, cap yang sesuai dengan tingkat kecepatan penyampaian dan cap tingkat keamanan. Amplop ini dimasukkan ke dalam amplop kedua dengan tanda-tanda yang sama kecuali cap tingkat keamanan.
4) Semua surat keluar yang dikirim dicatat dalam buku ekspedisi sebagai bukti pengiriman atau dibuatkan tanda bukti pengiriman tersendiri.
5) Untuk kepentingan keamanan, sekretaris/pimpinan sekretariat mengusahakan keselamatan pengiriman semua surat keluar, khususnya yang tingkat keamanannya sangat rahasia atau rahasia.
e. Penyimpanan 1) Semua arsip surat keluar ataupun pertinggal harus disimpan sesuai dengan ketentuan yang berlaku dalam kearsipan.
2) Naskah asli surat dinas keluar dan naskah yang diparaf harus disimpan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5089, '5) Penggandaan surat keluar yang tingkat kecepatan penyampaiannya kilat dan sangat segera harus didahulukan.
6) Penggandaan surat keluar yang tingkat keamanannya sangat rahasia/rahasia harus diawasi dengan ketat.
7) Sekretaris/pimpinan sekretariat berkewajiban menjaga agar penggandaan sesuai kebutuhan.
d. Pengiriman 1) Surat keluar yang akan dikirimkan dimasukkan ke dalam amplop surat.
2) Pada amplop surat keluar yang tingkat keamanannya biasa (B), rahasia (R), dan sangat rahasia (SR) dicantumkan alamat lengkap, nomor surat dinas, dan cap yang sesuai dengan tingkat kecepatan penyampaian (kilat/segera/sangat segera/biasa).
3) Surat yang tingkat keamanannya sangat rahasia atau rahasia dimasukkan ke dalam amplop, dibubuhi alamat lengkap, nomor surat dinas, cap dinas, cap yang sesuai dengan tingkat kecepatan penyampaian dan cap tingkat keamanan. Amplop ini dimasukkan ke dalam amplop kedua dengan tanda-tanda yang sama kecuali cap tingkat keamanan.
4) Semua surat keluar yang dikirim dicatat dalam buku ekspedisi sebagai bukti pengiriman atau dibuatkan tanda bukti pengiriman tersendiri.
5) Untuk kepentingan keamanan, sekretaris/pimpinan sekretariat mengusahakan keselamatan pengiriman semua surat keluar, khususnya yang tingkat keamanannya sangat rahasia atau rahasia.
e. Penyimpanan 1) Semua arsip surat keluar ataupun pertinggal harus disimpan sesuai dengan ketentuan yang berlaku dalam kearsipan.
2) Naskah asli surat dinas keluar dan naskah yang diparaf harus disimpan.', 'Lampiran hal. 136', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5090, 'perban-7-2020', 125, 'lampiran', 'Lampiran hal. 137', NULL, 137, '3) Tata cara penyimpanan surat keluar diatas sesuai dengan kebutuhan yang berlaku di lingkungan Badan Nasional Penanggulangan Bencana.
BAB V PEJABAT PENANDA TANGAN NASKAH DINAS A. Penandatanganan
1. Penggunaan Garis Kewenangan Kepala Badan Nasional Penanggulangan Bencana bertanggung jawab atas segala kegiatan yang dilakukan di dalam organisasi atau instansinya. Tanggung jawab tersebut tidak dapat dilimpahkan atau diserahkan kepada seseorang yang bukan pejabat berwenang. Garis kewenangan digunakan jika surat dinas ditandatangani oleh pejabat yang mendapat pelimpahan dari pejabat yang berwenang.
2. Penandatanganan Penandatanganan surat dinas yang menggunakan garis kewenangan dapat dilaksanakan dengan menggunakan tiga cara.
a. Atas Nama (a.n) Atas nama yang disingkat (a.n.) digunakan jika pejabat yang menandatangani surat dinas telah diberi kuasa oleh pejabat yang bertanggung jawab, berdasarkan bidang tugas dan tanggung jawab pejabat yang bersangkutan.
Susunan penandatanganan atas nama (a.n.) pejabat lain yaitu nama jabatan pejabat yang berwenang ditulis lengkap dengan huruf kapital pada setiap awal kata, didahului dengan singkatan a.n.
Contoh: a.n. Kepala Badan Nasional Penanggulan Bencana Sekretaris Utama, Tanda tangan Nama Lengkap');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5090, '3) Tata cara penyimpanan surat keluar diatas sesuai dengan kebutuhan yang berlaku di lingkungan Badan Nasional Penanggulangan Bencana.
BAB V PEJABAT PENANDA TANGAN NASKAH DINAS A. Penandatanganan
1. Penggunaan Garis Kewenangan Kepala Badan Nasional Penanggulangan Bencana bertanggung jawab atas segala kegiatan yang dilakukan di dalam organisasi atau instansinya. Tanggung jawab tersebut tidak dapat dilimpahkan atau diserahkan kepada seseorang yang bukan pejabat berwenang. Garis kewenangan digunakan jika surat dinas ditandatangani oleh pejabat yang mendapat pelimpahan dari pejabat yang berwenang.
2. Penandatanganan Penandatanganan surat dinas yang menggunakan garis kewenangan dapat dilaksanakan dengan menggunakan tiga cara.
a. Atas Nama (a.n) Atas nama yang disingkat (a.n.) digunakan jika pejabat yang menandatangani surat dinas telah diberi kuasa oleh pejabat yang bertanggung jawab, berdasarkan bidang tugas dan tanggung jawab pejabat yang bersangkutan.
Susunan penandatanganan atas nama (a.n.) pejabat lain yaitu nama jabatan pejabat yang berwenang ditulis lengkap dengan huruf kapital pada setiap awal kata, didahului dengan singkatan a.n.
Contoh: a.n. Kepala Badan Nasional Penanggulan Bencana Sekretaris Utama, Tanda tangan Nama Lengkap', 'Lampiran hal. 137', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5091, 'perban-7-2020', 126, 'lampiran', 'Lampiran hal. 138', NULL, 138, 'b. Untuk Beliau (u.b.) Untuk beliau yang disingkat (u.b.) digunakan jika yang diberikan kuasa memberikan kuasa lagi kepada pejabat satu tingkat di bawahnya, sehingga untuk beliau (u.b.) digunakan setelah atas nama (a.n.). Pelimpahan wewenang ini mengikuti urutan sampai dua tingkat struktural di bawahnya.
Contoh: a.n. Kepala Badan Nasional Penanggulan Bencana Sekretaris Utama, u.b Kepala Biro SDM dan Umum Tanda tangan Nama Lengkap
c. Untuk Perhatian (u.p.) Alamat surat dengan menggunakan singkatan u.p. (untuk perhatian) untuk keperluan berikut:
1) untuk mempercepat penyelesaian surat yang diperkirakan dilakukan oleh pejabat atau staf tertentu di lingkungan Badan Nasional Penanggulangan Bencana.
2) untuk mempermudah penyampaian oleh sekretariat penerima surat pejabat yang dituju dan untuk mempercepat penyelesaiannya sesuai dengan maksud surat.
3) untuk mempercepat penyelesaian surat karena tidak menunggu kebijaksanaan langsung Kepala Badan Nasional Penanggulangan Bencana.
Contoh:
Yth. Kepala Badan Nasional Penanggulangan Bencana Gedung Graha BNPB Jalan Pramuka Kav. 38, Jakarta Timur 13120 u.p.
Sekretaris Utama
d. Pelaksana Tugas (Plt.) Ketentuan penandatanganan pelaksana tugas, yang disingkat (Plt.), adalah sebagai berikut:
1) Plt. digunakan apabila pejabat yang berwenang menandatangani naskah dinas belum ditetapkan karena menunggu ketentuan bidang kepegawaian lebih lanjut.
2) Pelimpahan wewenang bersifat sementara sampai dengan pejabat yang definitif ditetapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5091, 'b. Untuk Beliau (u.b.) Untuk beliau yang disingkat (u.b.) digunakan jika yang diberikan kuasa memberikan kuasa lagi kepada pejabat satu tingkat di bawahnya, sehingga untuk beliau (u.b.) digunakan setelah atas nama (a.n.). Pelimpahan wewenang ini mengikuti urutan sampai dua tingkat struktural di bawahnya.
