INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5092, 'perban-7-2020', 127, 'lampiran', 'Lampiran hal. 140', NULL, 140, '3) Plt. bertanggung jawab terhadap naskah dinas yang ditandatanganinya.
Contoh:
Plt. Kepala Biro SDM dan Umum, Tanda Tangan Nama Lengkap
e. Pelaksana Harian (Plh.) Ketentuan penandatanganan pelaksana harian, yang disingkat (Plh.), adalah sebagai berikut:
1) Plh. digunakan apabila pejabat yang berwenang menandatangani naskah dinas tidak berada di tempat sehingga untuk kelancaran pelaksanaan pekerjaan sehari-hari perlu ada pejabat sementara yang menggantikannya.
2) Pelimpahan wewenang bersifat sementara, sampai dengan pejabat yang definitif kembali di tempat.
3) Plh. mempertanggungjawabkan naskah dinas yang ditandatanganinya kepada pejabat definitif.
Contoh:
Plh. Kepala Biro SDM dan Umum, Tanda Tangan Nama Lengkap
f. Kewenangan Penandatanganan 1) Kewenangan untuk melaksanakan dan menandatangani surat dinas antar/keluar instansi Badan Nasional Penanggulangan Bencana yang bersifat kebijakan/keputusan/arahan berada pada Kepala Badan Nasional Penanggulangan Bencana.
2) Kewenangan untuk melaksanakan dan menandatangani surat yang tidak bersifat kebijakan/keputusan/arahan dapat diserahkan/dilimpahkan kepada pimpinan pada setiap tingkat eselon atau pejabat lainnya yang diberi kewenangan untuk menandatanganinya.');
