INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5093, 'perban-7-2020', 128, 'lampiran', 'Lampiran hal. 141', NULL, 141, '3) Penyerahan/pelimpahan wewenang dan penandatanganan korespondensi kepada pejabat kepala/pimpinan dilaksanakan sebagai berikut: a) Sekretaris Utama Badan Nasional Penanggulangan Bencana dapat memperoleh pelimpahan kewenangan dan penandatanganan surat dinas tentang supervisi, arahan mengenai rencana strategis dan operasional, termasuk kegiatan lain yang dilaksanakan oleh organisasi lini di Badan Nasional Penanggulangan Bencana; dan b) Pimpinan organisasi lini pada instansi Badan Nasional Penanggulangan Bencana dapat memperoleh penyerahan/ pelimpahan wewenang dan penandatanganan surat dinas yang berkaitan dengan pelaksanaan tugas dan fungsi sesuai bidang masing-masing.
