INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5094, 'perban-7-2020', 129, 'lampiran', 'Lampiran hal. 142', NULL, 142, '23. Telaahan Staf √ √ √ √ √ √ BAB VI PENGGUNAAN LAMBANG NEGARA, LOGO DAN CAP DINAS DALAM NASKAH DINAS Lambang negara logo dan cap dinas digunakan dalam tata naskah dinas sebagai tanda pengenal atau identifikasi yang bersifat tetap dan resmi. Untuk memperoleh keseragaman dalam penyelenggaraan tata naskah dinas di lingkungan Badan Nasional Penanggulangan Bencana, perlu ditentukan penggunaan lambang negara dan logo pada kertas surat dan amplop.
A. Penggunaan Lambang Negara
1. Ketentuan Penggunaan Lambang Negara
a. Lambang negara digunakan dalam tata naskah dinas sebagai tanda pengenal atau identifikasi yang bersifat tetap dan resmi; dan
b. Pejabat yang berwenang menggunakan kop naskah dinas jabatan dan cap jabatan dengan lambang negara adalah Kepala Badan Nasional Penanggulangan Bencana.
2. Kop Naskah Dinas Jabatan dengan Lambang Negara Bentuk kop naskah dinas jabatan menggunakan lambang negara berwarna kuning emas, dengan ukuran tinggi 21,50 mm dan lebar 20,24 mm sesuai dengan ketentuan peraturan perundang-undangan.
Lambang negara terletak simetris di tengah kertas yang berjarak 20 mm dari tepi atas kertas dan berada di tengah tulisan nama jabatan.
Tulisan nama jabatan dicetak tebal dengan huruf kapital yang terletak 5 mm di bawah lambang negara.
Contoh bentuk dan spesifikasi kop naskah dinas jabatan dengan lambang negara dapat dilihat pada Gambar 1.
GAMBAR 1 20,24 mm 20,00 mm 21,50 mm 5,00 mm KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA
3. Cap Jabatan dengan Lambang Negara');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5094, '23. Telaahan Staf √ √ √ √ √ √ BAB VI PENGGUNAAN LAMBANG NEGARA, LOGO DAN CAP DINAS DALAM NASKAH DINAS Lambang negara logo dan cap dinas digunakan dalam tata naskah dinas sebagai tanda pengenal atau identifikasi yang bersifat tetap dan resmi. Untuk memperoleh keseragaman dalam penyelenggaraan tata naskah dinas di lingkungan Badan Nasional Penanggulangan Bencana, perlu ditentukan penggunaan lambang negara dan logo pada kertas surat dan amplop.
A. Penggunaan Lambang Negara
1. Ketentuan Penggunaan Lambang Negara
a. Lambang negara digunakan dalam tata naskah dinas sebagai tanda pengenal atau identifikasi yang bersifat tetap dan resmi; dan
