INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5097, 'perban-7-2020', 132, 'lampiran', 'Lampiran hal. 146', NULL, 146, '2) Bentuk kop naskah dinas dengan menggunakan Logo Badan Nasional Penanggulangan Bencana, terletak di tepi kiri atas kertas, diikuti dengan tulisan nama Badan Nasional Penanggulangan Bencana dan alamat lengkap yang terletak di sebelah kanan sejajar dengan logo. Tulisan Badan Nasional Penanggulangan Bencana dicetak tebal dengan huruf kapital tipe Arial ukuran 16 dengan warna hitam dan alamat lengkap ditulis dengan huruf awal kapital ukuran 12.
Contoh bentuk dan spesifikasi kop naskah dinas dengan menggunakan logo dapat dilihat pada Gambar 3.
