INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5098, 'perban-7-2020', 133, 'lampiran', 'Lampiran hal. 147', NULL, 147, '2) Lingkaran pertama adalah lingkaran paling luar. Pada lingkaran kedua, di bagian atas tercantum tulisan Badan Nasional sedangkan di bagian bawah tercantum tulisan Penanggulangan Bencana. Pada lingkaran ketiga, terdapat logo bentuk segitiga sama kaki dan di bawah logo ditulis BNPB secara simetris dengan ukuran 16.
3) Tinta cap instansi berwarna ungu.
4) Contoh bentuk dan spesifikasi cap instansi dengan menggunakan logo dapat dilihat pada Gambar 4.
GAMBAR 4 C. Penggunaan Lambang Negara dan Logo dalam Perjanjian Kerja Sama
1. Dalam hal dilakukan kerja sama antarpemerintah, perjanjian kerja sama menggunakan lambang negara.
2. Tata letak logo dalam perjanjian kerja sama nasional, baik antar kementerian/lembaga pemerintah nonkementerian/provinsi/ kabupaten/kota/lembaga nonpemerintah, logo yang dimiliki instansi masing-masing diletakkan di atas map naskah perjanjian.
D. Pengawasan Kepala Badan Nasional Penanggulangan Bencana bertanggung jawab atas pelaksanaan penggunaan lambang dan logo serta wajib melakukan pengawasan.
BAB VII NASKAH DINAS ELEKTRONIK Naskah dinas elektronik merupakan naskah dinas berupa komunikasi dan informasi yang dilakukan secara elektronik atau yang terekam dalam multimedia elektronik. Pengelolaan naskah dinas elektronik di lingkungan Badan Nasional Penanggulangan Bencana dilakukan melalui Sistem Informasi Persuratan dan Tata Naskah Dinas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5098, '2) Lingkaran pertama adalah lingkaran paling luar. Pada lingkaran kedua, di bagian atas tercantum tulisan Badan Nasional sedangkan di bagian bawah tercantum tulisan Penanggulangan Bencana. Pada lingkaran ketiga, terdapat logo bentuk segitiga sama kaki dan di bawah logo ditulis BNPB secara simetris dengan ukuran 16.
3) Tinta cap instansi berwarna ungu.
4) Contoh bentuk dan spesifikasi cap instansi dengan menggunakan logo dapat dilihat pada Gambar 4.
GAMBAR 4 C. Penggunaan Lambang Negara dan Logo dalam Perjanjian Kerja Sama
1. Dalam hal dilakukan kerja sama antarpemerintah, perjanjian kerja sama menggunakan lambang negara.
2. Tata letak logo dalam perjanjian kerja sama nasional, baik antar kementerian/lembaga pemerintah nonkementerian/provinsi/ kabupaten/kota/lembaga nonpemerintah, logo yang dimiliki instansi masing-masing diletakkan di atas map naskah perjanjian.
D. Pengawasan Kepala Badan Nasional Penanggulangan Bencana bertanggung jawab atas pelaksanaan penggunaan lambang dan logo serta wajib melakukan pengawasan.
BAB VII NASKAH DINAS ELEKTRONIK Naskah dinas elektronik merupakan naskah dinas berupa komunikasi dan informasi yang dilakukan secara elektronik atau yang terekam dalam multimedia elektronik. Pengelolaan naskah dinas elektronik di lingkungan Badan Nasional Penanggulangan Bencana dilakukan melalui Sistem Informasi Persuratan dan Tata Naskah Dinas.', 'Lampiran hal. 147', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5099, 'perban-7-2020', 134, 'lampiran', 'Lampiran hal. 149', NULL, 149, 'A. Penggunaan Sistem Informasi Persuratan dan Tata Naskah Dinas Sistem Informasi Persuratan dan Tata Naskah Dinas dikembangkan untuk membantu proses tatakelola persuratan dan naskah dinas di lingkungan Badan Nasional Penanggulangan Bencana. Penggunaan Sistem Informasi Persuratan dan Tata Naskah Dinas dalam pengelolaan surat meliputi kegiatan pengurusan surat masuk dan surat keluar.
1. Surat Masuk Kegiatan pengurusan surat masuk melalui Sistem Informasi Persuratan dan Tata Naskah Dinas digunakan untuk pencatatan dan distribusi surat masuk hingga penyampaian disposisi surat masuk ke tingkat staf. Serangkaian kegiatan tersebut secara otomatis tercatat oleh sistem dan dapat diketahui oleh pejabat dan staf yang ditunjuk.
2. Surat Keluar Pengurusan surat keluar melalui Sistem Informasi Persuratan dan Tata Naskah Dinas digunakan untuk pengelolaan naskah dinas korespondensi internal yang ada di lingkungan Badan Nasional Penanggulangan Bencana mulai dari pembuatan rancangan naskah dinas, pendistribusian hingga disposisi naskah dinas.
B. Pengawasan Ketentuan mengenai naskah dinas elektronik diatur sesuai dengan peraturan yang berlaku di lingkungan Badan Nasional Penanggulangan Bencana.
BAB VIII PERUBAHAN, PENCABUTAN, PEMBATALAN, DAN RALAT NASKAH DINAS Perubahan, pencabutan, pembatalan, serta ralat naskah dinas harus jelas dan dapat menunjukkan naskah dinas mana yang diadakan perubahan, pencabutan, pembatalan, dan/atau ralat tersebut.
A. Pengertian');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5099, 'A. Penggunaan Sistem Informasi Persuratan dan Tata Naskah Dinas Sistem Informasi Persuratan dan Tata Naskah Dinas dikembangkan untuk membantu proses tatakelola persuratan dan naskah dinas di lingkungan Badan Nasional Penanggulangan Bencana. Penggunaan Sistem Informasi Persuratan dan Tata Naskah Dinas dalam pengelolaan surat meliputi kegiatan pengurusan surat masuk dan surat keluar.
1. Surat Masuk Kegiatan pengurusan surat masuk melalui Sistem Informasi Persuratan dan Tata Naskah Dinas digunakan untuk pencatatan dan distribusi surat masuk hingga penyampaian disposisi surat masuk ke tingkat staf. Serangkaian kegiatan tersebut secara otomatis tercatat oleh sistem dan dapat diketahui oleh pejabat dan staf yang ditunjuk.
2. Surat Keluar Pengurusan surat keluar melalui Sistem Informasi Persuratan dan Tata Naskah Dinas digunakan untuk pengelolaan naskah dinas korespondensi internal yang ada di lingkungan Badan Nasional Penanggulangan Bencana mulai dari pembuatan rancangan naskah dinas, pendistribusian hingga disposisi naskah dinas.
B. Pengawasan Ketentuan mengenai naskah dinas elektronik diatur sesuai dengan peraturan yang berlaku di lingkungan Badan Nasional Penanggulangan Bencana.
BAB VIII PERUBAHAN, PENCABUTAN, PEMBATALAN, DAN RALAT NASKAH DINAS Perubahan, pencabutan, pembatalan, serta ralat naskah dinas harus jelas dan dapat menunjukkan naskah dinas mana yang diadakan perubahan, pencabutan, pembatalan, dan/atau ralat tersebut.
A. Pengertian', 'Lampiran hal. 149', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2020 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5100, 'perban-7-2020', 135, 'lampiran', 'Lampiran hal. 150', NULL, 150, '1. Perubahan Perubahan merupakan bagian tertentu dari naskah dinas diubah.
Perubahan dinyatakan dengan lembar perubahan.
2. Pencabutan Pencabutan merupakan naskah dinas tidak berlaku sejak pencabutan ditetapkan. Pencabutan naskah dinas dinyatakan dengan penetapan naskah dinas baru.
3. Pembatalan Pembatalan merupakan pernyataan bahwa seluruh materi naskah dinas tidak diberlakukan lagi melalui suatu pernyataan pembatalan dalam naskah dinas yang baru.
4. Ralat Ralat merupakan perbaikan yang dilakukan karena terjadi salah pengetikan atau salah cetak sehingga tidak sesuai dengan naskah aslinya.
B. Tata Cara Perubahan, Pencabutan, Pembatalan, dan Ralat
1. Naskah Dinas yang bersifat mengatur, apabila diubah, dicabut, atau dibatalkan harus diubah, dicabut, atau dibatalkan dengan naskah dinas yang sama jenisnya. Keputusan Kepala Badan Nasional Penanggulangan Bencana harus diubah, dicabut, atau dibatalkan dengan Keputusan Kepala Badan Nasional Penanggulangan Bencana juga.
2. Pejabat yang berhak menentukan perubahan, pencabutan, dan pembatalan adalah pejabat yang menandatangani naskah dinas tersebut atau oleh pejabat yang lebih tinggi kedudukannya.
3. Ralat yang bersifat kekeliruan kecil, seperti salah ketik, dilaksanakan oleh pejabat yang menandatangani naskah dinas atau dapat dilaksanakan oleh pejabat setingkat lebih rendah.');
