INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5101, 'perban-7-2020', 136, 'lampiran', 'Lampiran hal. 152', NULL, 152, 'BAB IX PENUTUP Tata Naskah Dinas ini merupakan acuan bagi seluruh unit kerja di lingkungan Badan Nasional Penanggulangan Bencana dalam penyelenggaraan tata naskah dinas dengan harapan penanganan administrasi lebih tertib, efektif dan efisien, sehingga dapat terselenggaranya penanggulangan bencana dengan baik.
