INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5189, 'perban-7-2021', 78, 'lampiran', 'Lampiran hal. 51', NULL, 51, 'LAMPIRAN I PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR £» TAHUN 2021 TENTANG PETUNJUK TEKNIS JABATAN FUNGSIONAL PENATA PENANGGULANGAN BENCANA FORMAT DOKUMEN USULAN PENGANGKATAN DALAM JABATAN FUNGSIONAL PENATA PENANGGULANGAN BENCANA MELALUI PERPINDAHAN DARI JABATAN LAIN Format 1 - Surat Pernyataan Bersedia Untuk Diangkat Dalam Jabatan Fungsional Penata Penanggulangan Bencana KOP SURAT INSTANSI Surat Pernyataan Yang bertanda tangan di bawah ini, Nama NIP Pangkat/ Gol.Ruang Instansi/ Unit Kerja Jabatan Dengan ini menyatakan sesungguhnya, bahwa saya:
1. bersedia diangkat ke dalam Jabatan Fungsional Penata Penanggulangan Bencana,
2. tidak merangkap jabatan dalam jabatan fungsional lainnya,
3. bersedia mengikuti pendidikan dan pelatihan di bidang penyelenggaraan penanggulangan bencana, dan
4. bersedia melaksanakan kegiatan di bidang penyelenggaraan penanggulangan bencana secara aktif.
Demikian Surat Pernyataan ini saya buat untuk dapat dipergunakan sebagaimana mestinya.
