INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5198, 'perban-7-2021', 87, 'lampiran', 'Lampiran hal. 67', NULL, 67, '1) Diisi dengan bulan periode dilakukannya penilaian Angka Kredit, 2) Diisi dengan nomor dokumen BAPAK, 3) Diisi dengan hari dilakukannya Sidang Pleno Penilaian dan Penetapan Angka Kredit, 4) Diisi dengan tanggal dilakukannya Sidang Pleno Penilaian dan Penetapan Angka Kredit, 5) Diisi dengan periode bulan dilakukannya Penilaian dan Penetapan Angka Kredit, 6) Diisi dengan lokasi dilakukannya Sidang Pleno Penilaian dan Penetapan Angka Kredit, 7) Diisi dengan jumlah Bahan Usulan Penilaian yang telah dilakukan penilaian oleh Tim Penilai, 8) Diisi dengan daftar Bahan Usulan Penilaian yang telah dilakukan penilaian oleh Tim Penilai, 9) Diisi dengan daftar nama Penata Penanggulangan Bencana yang dapat diusulkan untuk mendapat kenaikan pangkat/jabatan setingkat lebih tinggi, 10) Diisi dengan daftar nama Penata Penanggulangan Bencana yang belum dapat diusulkan untuk mendapat kenaikan pangkat/jabatan setingkat lebih tinggi.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
