INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5202, 'perban-7-2022', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Presiden Nomor 87 Tahun 2020 tentang Rencana Induk Penanggulangan Bencana Tahun 2020- 2044 (Lembaran Negara Republik Indonesia Tahun 2020 Nomor 204);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5202, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Presiden Nomor 87 Tahun 2020 tentang Rencana Induk Penanggulangan Bencana Tahun 2020- 2044 (Lembaran Negara Republik Indonesia Tahun 2020 Nomor 204);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5203, 'perban-7-2022', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG RENCANA NASIONAL PENANGGULANGAN BENCANA TAHUN 2020-2024.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5203, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG RENCANA NASIONAL PENANGGULANGAN BENCANA TAHUN 2020-2024.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5204, 'perban-7-2022', 4, 'pasal', 'Pasal 1', NULL, 2, '(1) Dalam rangka peningkatan tata kelola penanggulangan bencana secara nasional ditetapkan Rencana Nasional Penanggulangan Bencana.
(2) Rencana Nasional Penanggulangan Bencana sebagaimana dimaksud pada ayat (1) ditetapkan untuk tahun 2020- 2024.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5204, '(1) Dalam rangka peningkatan tata kelola penanggulangan bencana secara nasional ditetapkan Rencana Nasional Penanggulangan Bencana.
(2) Rencana Nasional Penanggulangan Bencana sebagaimana dimaksud pada ayat (1) ditetapkan untuk tahun 2020- 2024.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5205, 'perban-7-2022', 5, 'pasal', 'Pasal 2', NULL, 2, '(1) Rencana Nasional Penanggulangan Bencana Tahun 2020- 2024 sebagaimana dimaksud dalam Pasal 1 ayat (2) merupakan dokumen perencanaan dalam rangka pelaksanaan Rencana Induk Penanggulangan Bencana Tahun 2020-2044.
(2) Rencana Nasional Penanggulangan Bencana Tahun 2020- 2024 melaksanakan Fokus Capaian 2020-2024 pada Rencana Induk Penanggulangan Bencana 2020-2044.
(3) Fokus Capaian 2020-2024 sebagaimana dimaksud pada ayat (2) terdiri atas:
a. terwujudnya peraturan perundang-undangan yang harmonis di bidang penanggulangan bencana;
b. terintegrasinya riset inovasi dan teknologi kebencanaan;
c. tersedianya sistem peringatan dini terpadu multi ancaman bencana;
d. meningkatnya pengembangan dan inovasi skema alternatif pembiayaan penanggulangan bencana;
e. terwujudnya tata kelola risiko bencana yang berkelanjutan;
f. terintegrasinya data, informasi, dan literasi kebencanaan serta meningkatnya pemahaman terhadap risiko bencana, bentang alam, dan adaptasi perubahan iklim, serta upaya penguatan ketahanan sosial dan ketahanan kesehatan masyarakat;
g. meningkatnya kapasitas penanganan darurat bencana secara terpadu;
h. meningkatnya kapasitas kabupaten/kota dan masyarakat terhadap ketahanan bencana dan perubahan iklim;
i. terwujudnya pengelolaan ekosistem laut dan pesisir yang berbasis mitigasi bencana;
j. meningkatnya ketersediaan sarana prasarana pelatihan dan standarisasi kompetensi bidang kebencanaan;
k. terlaksananya perencanaan rehabilitasi dan rekonstruksi pascabencana secara terintegrasi oleh seluruh pemangku kepentingan berdasarkan semangat gotong royong, kesetiakawanan, dan kedermawanan; dan
l. meningkatnya kualitas infrastruktur vital yang berbasis mitigasi bencana dan adaptasi perubahan iklim, serta ketahanan sosial dan ketahanan kesehatan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5205, '(1) Rencana Nasional Penanggulangan Bencana Tahun 2020- 2024 sebagaimana dimaksud dalam Pasal 1 ayat (2) merupakan dokumen perencanaan dalam rangka pelaksanaan Rencana Induk Penanggulangan Bencana Tahun 2020-2044.
(2) Rencana Nasional Penanggulangan Bencana Tahun 2020- 2024 melaksanakan Fokus Capaian 2020-2024 pada Rencana Induk Penanggulangan Bencana 2020-2044.
(3) Fokus Capaian 2020-2024 sebagaimana dimaksud pada ayat (2) terdiri atas:
a. terwujudnya peraturan perundang-undangan yang harmonis di bidang penanggulangan bencana;
b. terintegrasinya riset inovasi dan teknologi kebencanaan;
c. tersedianya sistem peringatan dini terpadu multi ancaman bencana;
d. meningkatnya pengembangan dan inovasi skema alternatif pembiayaan penanggulangan bencana;
e. terwujudnya tata kelola risiko bencana yang berkelanjutan;
f. terintegrasinya data, informasi, dan literasi kebencanaan serta meningkatnya pemahaman terhadap risiko bencana, bentang alam, dan adaptasi perubahan iklim, serta upaya penguatan ketahanan sosial dan ketahanan kesehatan masyarakat;
g. meningkatnya kapasitas penanganan darurat bencana secara terpadu;
h. meningkatnya kapasitas kabupaten/kota dan masyarakat terhadap ketahanan bencana dan perubahan iklim;
i. terwujudnya pengelolaan ekosistem laut dan pesisir yang berbasis mitigasi bencana;
j. meningkatnya ketersediaan sarana prasarana pelatihan dan standarisasi kompetensi bidang kebencanaan;
k. terlaksananya perencanaan rehabilitasi dan rekonstruksi pascabencana secara terintegrasi oleh seluruh pemangku kepentingan berdasarkan semangat gotong royong, kesetiakawanan, dan kedermawanan; dan
l. meningkatnya kualitas infrastruktur vital yang berbasis mitigasi bencana dan adaptasi perubahan iklim, serta ketahanan sosial dan ketahanan kesehatan masyarakat.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5206, 'perban-7-2022', 6, 'pasal', 'Pasal 3', NULL, 3, '(1) Rencana Nasional Penanggulangan Bencana Tahun 2020- 2024 sebagaimana dimaksud dalam Pasal 1 ayat (2) disusun dengan mempertimbangkan kebijakan nasional penanggulangan bencana tahun 2020-2044.
(2) Rencana Nasional Penanggulangan Bencana Tahun 2020- 2024 menjadi acuan bagi kementerian/lembaga dan pemerintah daerah dalam menyusun perencanaan dan penganggaran pembangunan.
(3) Rencana Nasional Penanggulangan Bencana Tahun 2020- 2024 meliputi:
a. pengenalan dan pengkajian ancaman bencana;
b. pemahaman tentang kerentanan masyarakat;
c. analisis kemungkinan dampak bencana;
d. pilihan tindakan pengurangan risiko bencana;
e. penentuan mekanisme kesiapan dan penanggulangan dampak bencana; dan
f. alokasi tugas, kewenangan, dan sumber daya yang tersedia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5206, '(1) Rencana Nasional Penanggulangan Bencana Tahun 2020- 2024 sebagaimana dimaksud dalam Pasal 1 ayat (2) disusun dengan mempertimbangkan kebijakan nasional penanggulangan bencana tahun 2020-2044.
(2) Rencana Nasional Penanggulangan Bencana Tahun 2020- 2024 menjadi acuan bagi kementerian/lembaga dan pemerintah daerah dalam menyusun perencanaan dan penganggaran pembangunan.
(3) Rencana Nasional Penanggulangan Bencana Tahun 2020- 2024 meliputi:
a. pengenalan dan pengkajian ancaman bencana;
b. pemahaman tentang kerentanan masyarakat;
c. analisis kemungkinan dampak bencana;
d. pilihan tindakan pengurangan risiko bencana;
e. penentuan mekanisme kesiapan dan penanggulangan dampak bencana; dan
f. alokasi tugas, kewenangan, dan sumber daya yang tersedia.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5207, 'perban-7-2022', 7, 'pasal', 'Pasal 4', NULL, 3, '(1) Pengenalan dan pengkajian ancaman bencana sebagaimana dimaksud dalam Pasal 3 ayat (3) huruf a, dilakukan melalui:
a. pemantauan potensi ancaman bencana yang diperoleh dari kementerian/lembaga terkait;
b. penggunaan data indeks risiko bencana; dan
c. konsultasi dengan para ahli kebencanaan.
(2) Pengenalan dan pengkajian ancaman bencana sebagaimana dimaksud pada ayat (1), diprioritaskan terhadap:
a. ancaman bencana geologi;
b. ancaman bencana hidrometeorologi; dan
c. ancaman bencana nonalam.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5207, '(1) Pengenalan dan pengkajian ancaman bencana sebagaimana dimaksud dalam Pasal 3 ayat (3) huruf a, dilakukan melalui:
a. pemantauan potensi ancaman bencana yang diperoleh dari kementerian/lembaga terkait;
b. penggunaan data indeks risiko bencana; dan
c. konsultasi dengan para ahli kebencanaan.
(2) Pengenalan dan pengkajian ancaman bencana sebagaimana dimaksud pada ayat (1), diprioritaskan terhadap:
a. ancaman bencana geologi;
b. ancaman bencana hidrometeorologi; dan
c. ancaman bencana nonalam.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5208, 'perban-7-2022', 8, 'pasal', 'Pasal 5', NULL, 3, '(1) Pemahaman tentang kerentanan masyarakat sebagaimana dimaksud dalam Pasal 3 ayat (3) huruf b dilakukan melalui:
a. identifikasi akar masalah kerentanan sosial, ekonomi dan lingkungan pada kawasan berisiko tinggi; dan
b. konsultasi dengan para ahli sosial budaya.
(2) Pemahaman tentang kerentanan masyarakat sebagaimana dimaksud pada ayat (1) meliputi:
a. masih banyaknya penduduk yang berada di kawasan rawan bencana;
b. masih terdapat pembangunan di kawasan rawan bencana;
c. meningkatnya luas kawasan rawan bencana;
d. belum optimalnya tata kelola, perencanaan, dan pembiayaan/investasi penanggulangan bencana; dan
e. terpengaruhnya pertumbuhan ekonomi oleh bencana nonalam.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5208, '(1) Pemahaman tentang kerentanan masyarakat sebagaimana dimaksud dalam Pasal 3 ayat (3) huruf b dilakukan melalui:
a. identifikasi akar masalah kerentanan sosial, ekonomi dan lingkungan pada kawasan berisiko tinggi; dan
b. konsultasi dengan para ahli sosial budaya.
(2) Pemahaman tentang kerentanan masyarakat sebagaimana dimaksud pada ayat (1) meliputi:
a. masih banyaknya penduduk yang berada di kawasan rawan bencana;
b. masih terdapat pembangunan di kawasan rawan bencana;
c. meningkatnya luas kawasan rawan bencana;
d. belum optimalnya tata kelola, perencanaan, dan pembiayaan/investasi penanggulangan bencana; dan
e. terpengaruhnya pertumbuhan ekonomi oleh bencana nonalam.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5209, 'perban-7-2022', 9, 'pasal', 'Pasal 6', NULL, 3, '(1) Analisis kemungkinan dampak bencana sebagaimana dimaksud dalam Pasal 3 ayat (3) huruf c dilakukan dengan memperhatikan hasil pengenalan dan pengkajian ancaman bencana sebagaimana dimaksud dalam Pasal 4 ayat (2) serta hasil pemahaman kerentanan masyarakat sebagaimana dimaksud dalam Pasal 5 ayat (2).
(2) Analisis kemungkinan dampak bencana sebagaimana dimaksud dalam ayat (1), meliputi:
a. meningkatnya risiko bencana geologi;
b. meningkatnya risiko bencana hidrometeorologi;
c. meningkatnya risiko bencana nonalam; dan
d. meningkatnya kebutuhan terhadap penatakelolaan, perencanaan, dan pembiayaan/investasi penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5209, '(1) Analisis kemungkinan dampak bencana sebagaimana dimaksud dalam Pasal 3 ayat (3) huruf c dilakukan dengan memperhatikan hasil pengenalan dan pengkajian ancaman bencana sebagaimana dimaksud dalam Pasal 4 ayat (2) serta hasil pemahaman kerentanan masyarakat sebagaimana dimaksud dalam Pasal 5 ayat (2).
(2) Analisis kemungkinan dampak bencana sebagaimana dimaksud dalam ayat (1), meliputi:
a. meningkatnya risiko bencana geologi;
b. meningkatnya risiko bencana hidrometeorologi;
c. meningkatnya risiko bencana nonalam; dan
d. meningkatnya kebutuhan terhadap penatakelolaan, perencanaan, dan pembiayaan/investasi penanggulangan bencana.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5210, 'perban-7-2022', 10, 'pasal', 'Pasal 7', NULL, 4, '(1) Pilihan tindakan pengurangan risiko bencana sebagaimana dimaksud dalam Pasal 3 ayat (3) huruf d disusun untuk mengantisipasi potensi dampak bencana sebagaimana dimaksud dalam Pasal 6 ayat (2).
(2) Pilihan tindakan pengurangan risiko bencana sebagaimana dimaksud pada ayat (1) meliputi:
a. penguatan dan harmonisasi peraturan perundang-undangan penanggulangan bencana;
b. penguatan tata kelola penanggulangan bencana;
c. penerapan riset inovasi dan teknologi kebencanaan;
d. peningkatan sarana prasarana dalam pengurangan risiko bencana;
e. penguatan sistem kesiapsiagaan bencana;
f. pemberdayaan masyarakat dalam penanggulangan bencana;
g. peningkatan perlindungan terhadap kerentanan lingkungan di daerah rawan bencana;
h. penguatan sistem dan operasionalisasi penanganan darurat bencana; dan
i. penyelenggaraan rehabilitasi dan rekonstruksi di daerah terdampak bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5210, '(1) Pilihan tindakan pengurangan risiko bencana sebagaimana dimaksud dalam Pasal 3 ayat (3) huruf d disusun untuk mengantisipasi potensi dampak bencana sebagaimana dimaksud dalam Pasal 6 ayat (2).
(2) Pilihan tindakan pengurangan risiko bencana sebagaimana dimaksud pada ayat (1) meliputi:
a. penguatan dan harmonisasi peraturan perundang-undangan penanggulangan bencana;
b. penguatan tata kelola penanggulangan bencana;
