INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5212, 'perban-7-2022', 12, 'pasal', 'Pasal 9', NULL, 4, 'Alokasi tugas, kewenangan, dan sumber daya yang tersedia sebagaimana dimaksud dalam Pasal 3 ayat (3) huruf f merupakan pelibatan kementerian/lembaga dan unsur nonpemerintah dalam pelaksanaan Rencana Nasional Penanggulangan Bencana Tahun 2020-2024 sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5212, 'Alokasi tugas, kewenangan, dan sumber daya yang tersedia sebagaimana dimaksud dalam Pasal 3 ayat (3) huruf f merupakan pelibatan kementerian/lembaga dan unsur nonpemerintah dalam pelaksanaan Rencana Nasional Penanggulangan Bencana Tahun 2020-2024 sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5213, 'perban-7-2022', 13, 'pasal', 'Pasal 10', NULL, 4, 'Pelaksanaan Rencana Nasional Penanggulangan Bencana Tahun 2020-2024 sebagaimana dimaksud dalam Pasal 3 ayat
(3) tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5213, 'Pelaksanaan Rencana Nasional Penanggulangan Bencana Tahun 2020-2024 sebagaimana dimaksud dalam Pasal 3 ayat
(3) tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5214, 'perban-7-2022', 14, 'pasal', 'Pasal 11', NULL, 5, 'Dalam rangka melaksanakan Rencana Nasional Penanggulangan Bencana wajib memperhatikan isu lintas sektor yang tidak terbatas pada:
