INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5215, 'perban-7-2022', 15, 'pasal', 'Pasal 12', NULL, 5, 'Pemerintah daerah menyusun Rencana Penanggulangan Bencana daerah dengan mengacu pada Rencana Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5215, 'Pemerintah daerah menyusun Rencana Penanggulangan Bencana daerah dengan mengacu pada Rencana Nasional Penanggulangan Bencana.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5216, 'perban-7-2022', 16, 'pasal', 'Pasal 13', NULL, 5, 'Pendanaan pelaksanaan Rencana Nasional Penanggulangan Bencana Tahun 2020-2024 bersumber dari:
a. Anggaran Pendapatan dan Belanja Negara; dan
b. sumber pendanaan lain yang sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5216, 'Pendanaan pelaksanaan Rencana Nasional Penanggulangan Bencana Tahun 2020-2024 bersumber dari:
a. Anggaran Pendapatan dan Belanja Negara; dan
b. sumber pendanaan lain yang sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5217, 'perban-7-2022', 17, 'pasal', 'Pasal 14', NULL, 5, '(1) Peraturan Badan ini berlaku sampai dengan tanggal 31 Desember 2024.
(2) Rencana Nasional Penanggulangan Bencana Tahun 2020- 2024 dapat dilakukan kaji ulang.
(3) Kaji ulang sebagaimana dimaksud pada ayat (2) dilaksanakan berdasarkan:
a. hasil evaluasi dan rekomendasi Sekretariat Pelaksanaan Rencana Induk Penanggulangan Bencana; dan/atau
b. pertimbangan para pakar kebencanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5217, '(1) Peraturan Badan ini berlaku sampai dengan tanggal 31 Desember 2024.
(2) Rencana Nasional Penanggulangan Bencana Tahun 2020- 2024 dapat dilakukan kaji ulang.
(3) Kaji ulang sebagaimana dimaksud pada ayat (2) dilaksanakan berdasarkan:
a. hasil evaluasi dan rekomendasi Sekretariat Pelaksanaan Rencana Induk Penanggulangan Bencana; dan/atau
b. pertimbangan para pakar kebencanaan.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5218, 'perban-7-2022', 18, 'pasal', 'Pasal 15', NULL, 5, 'Rencana Nasional Penanggulangan Bencana Tahun 2020-2024 yang telah dilaksanakan sebelum adanya Peraturan Badan ini diakui keberadaannya sepanjang tidak bertentangan dengan ketentuan dalam Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5218, 'Rencana Nasional Penanggulangan Bencana Tahun 2020-2024 yang telah dilaksanakan sebelum adanya Peraturan Badan ini diakui keberadaannya sepanjang tidak bertentangan dengan ketentuan dalam Peraturan Badan ini.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5219, 'perban-7-2022', 19, 'pasal', 'Pasal 16', NULL, 5, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5219, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5220, 'perban-7-2022', 20, 'lain', 'Penutup', NULL, 6, 'Ditetapkan di Jakarta pada tanggal 23 November 2022 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SUHARYANTO Diundangkan di Jakarta pada tanggal MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY BERITA NEGARA REPUBLIK INDONESIA TAHUN 2022 NOMOR');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5220, 'Ditetapkan di Jakarta pada tanggal 23 November 2022 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SUHARYANTO Diundangkan di Jakarta pada tanggal MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY BERITA NEGARA REPUBLIK INDONESIA TAHUN 2022 NOMOR', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2022 tentang Rencana Nasional Penanggulangan Bencana Tahun 2020-2024');
