INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5243, 'perban-7-2024', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2024 tentang Perubahan Kedua atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5243, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2024 tentang Perubahan Kedua atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2024 tentang Perubahan Kedua atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5244, 'perban-7-2024', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dengan ditetapkannya Peraturan Presiden Nomor 204 Tahun 2024 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana, perlu dilakukan penyesuaian terhadap ketentuan dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Perubahan Kedua atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Lingkungan Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5244, 'a. bahwa dengan ditetapkannya Peraturan Presiden Nomor 204 Tahun 2024 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana, perlu dilakukan penyesuaian terhadap ketentuan dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Perubahan Kedua atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Lingkungan Badan Nasional Penanggulangan Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2024 tentang Perubahan Kedua atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5245, 'perban-7-2024', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 7, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Presiden Nomor 204 Tahun 2024 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2024 Nomor 402);
4. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2016 Nomor 1776) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 199);
5. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5245, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 7, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Presiden Nomor 204 Tahun 2024 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2024 Nomor 402);
4. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2016 Nomor 1776) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 199);
5. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 1156) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2024 tentang Perubahan Kedua atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5246, 'perban-7-2024', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PERUBAHAN KEDUA ATAS PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 1 TAHUN 2016 TENTANG PELAKSANAAN PEMBERIAN TUNJANGAN KINERJA PEGAWAI DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5246, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PERUBAHAN KEDUA ATAS PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 1 TAHUN 2016 TENTANG PELAKSANAAN PEMBERIAN TUNJANGAN KINERJA PEGAWAI DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2024 tentang Perubahan Kedua atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5247, 'perban-7-2024', 4, 'pasal', 'Pasal I', NULL, 2, 'Beberapa ketentuan dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2016 Nomor 1776) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 199) diubah sehingga berbunyi sebagai berikut:
1. Ketentuan Pasal 1 diubah, sehingga berbunyi sebagai berikut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5247, 'Beberapa ketentuan dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2016 Nomor 1776) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2020 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 199) diubah sehingga berbunyi sebagai berikut:
1. Ketentuan Pasal 1 diubah, sehingga berbunyi sebagai berikut.', 'Pasal I', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2024 tentang Perubahan Kedua atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5248, 'perban-7-2024', 5, 'pasal', 'Pasal 1', NULL, 3, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Aparatur Sipil Negara yang selanjutnya disingkat ASN adalah profesi bagi pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang bekerja pada instansi pemerintah.
2. Pegawai ASN adalah pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan diberikan penghasilan berdasarkan peraturan perundang-undangan.
3. Pegawai Lainnya adalah pegawai yang diangkat pada jabatan yang telah mendapat persetujuan dari menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.
4. Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana yang selanjutnya disebut Pegawai adalah Pegawai ASN dan Pegawai Lainnya.
5. Tunjangan Kinerja adalah tunjangan yang diberikan kepada Pegawai untuk meningkatkan kesejahteraan yang pelaksanaannya sesuai dengan Peraturan Presiden Nomor 204 Tahun 2024 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.
6. Kelas Jabatan adalah tingkat jabatan struktural maupun jabatan fungsional dalam satuan organisasi negara yang digunakan sebagai dasar pemberian Tunjangan Kinerja.
2. Ketentuan Pasal 2 diubah, sehingga berbunyi sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5248, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Aparatur Sipil Negara yang selanjutnya disingkat ASN adalah profesi bagi pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang bekerja pada instansi pemerintah.
2. Pegawai ASN adalah pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan diberikan penghasilan berdasarkan peraturan perundang-undangan.
3. Pegawai Lainnya adalah pegawai yang diangkat pada jabatan yang telah mendapat persetujuan dari menteri yang menyelenggarakan urusan pemerintahan di bidang pendayagunaan aparatur negara.
4. Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana yang selanjutnya disebut Pegawai adalah Pegawai ASN dan Pegawai Lainnya.
5. Tunjangan Kinerja adalah tunjangan yang diberikan kepada Pegawai untuk meningkatkan kesejahteraan yang pelaksanaannya sesuai dengan Peraturan Presiden Nomor 204 Tahun 2024 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.
6. Kelas Jabatan adalah tingkat jabatan struktural maupun jabatan fungsional dalam satuan organisasi negara yang digunakan sebagai dasar pemberian Tunjangan Kinerja.
2. Ketentuan Pasal 2 diubah, sehingga berbunyi sebagai berikut:', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2024 tentang Perubahan Kedua atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5249, 'perban-7-2024', 6, 'pasal', 'Pasal 2', NULL, 3, '(1) Setiap Pegawai berhak menerima Tunjangan Kinerja sesuai dengan ketentuan peraturan perundang-undangan.
(2) Tunjangan Kinerja sebagaimana dimaksud pada ayat
(1) dibayarkan setiap bulan.
(3) Besaran Tunjangan Kinerja sebagaimana dimaksud pada ayat (1) tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
(4) Tunjangan Kinerja sebagaimana dimaksud pada ayat
(1) diberikan terhitung sejak bulan Desember 2024.');
