INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5251, 'perban-7-2024', 8, 'lain', 'Penutup', NULL, 4, 'Ditetapkan di Jakarta pada tanggal 27 Desember 2024 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2024 NOMOR Ж');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5251, 'Ditetapkan di Jakarta pada tanggal 27 Desember 2024 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2024 NOMOR Ж', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2024 tentang Perubahan Kedua atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
