INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5259, 'perban-7-2025', 6, 'pasal', 'Pasal 3', 'BAB II PENYELENGGARA', 4, 'Penyelenggara Program Destana terdiri atas:
a. pelaksana; dan
b. pendukung.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5259, 'Penyelenggara Program Destana terdiri atas:
a. pelaksana; dan
b. pendukung.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5260, 'perban-7-2025', 7, 'pasal', 'Pasal 4', 'BAB II PENYELENGGARA', 4, '(1) Pelaksana sebagaimana dimaksud dalam Pasal 3 huruf a merupakan pihak dalam Desa dan Kelurahan sebagai pelaku utama pelaksanaan kegiatan untuk mencapai tujuan Destana.
(2) Pelaksana sebagaimana dimaksud pada ayat (1) terdiri atas:
a. masyarakat;
b. pemerintah Desa dan Kelurahan; dan
c. organisasi di tingkat Desa dan Kelurahan.
(3) Pelaksana sebagaimana dimaksud pada ayat (2) huruf c terdiri atas:
a. FPRB;
b. Tim Relawan Penanggulangan Bencana; dan/atau
c. organisasi lainnya.
(4) Organisasi sebagaimana dimaksud pada ayat (3) huruf c merupakan organisasi yang berada di wilayah Desa dan Kelurahan yang melaksanakan program dan pengelolaan sumber daya secara harmonis dan tersinkronisasi.
(5) Pelaksana sebagaimana dimaksud pada ayat (2) melakukan pengelolaan sumber daya, harmonisasi, dan sinkronisasi meliputi:
a. fasilitasi dukungan inisiatif Pengelolaan Risiko Bencana;
b. dorongan pengembangan keberlanjutan dan kualitas ketangguhan masyarakat;
c. dorongan upaya pembelajaran kolektif para pemangku kepentingan dalam Pengelolaan Risiko Bencana;
d. dorongan peningkatan kerja sama dan koordinasi para pemangku kepentingan dalam kegiatan Pengelolaan Risiko Bencana berkelanjutan di semua tahapan penanggulangan bencana; dan
e. koordinasi dengan pendukung Program Destana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5260, '(1) Pelaksana sebagaimana dimaksud dalam Pasal 3 huruf a merupakan pihak dalam Desa dan Kelurahan sebagai pelaku utama pelaksanaan kegiatan untuk mencapai tujuan Destana.
(2) Pelaksana sebagaimana dimaksud pada ayat (1) terdiri atas:
a. masyarakat;
b. pemerintah Desa dan Kelurahan; dan
c. organisasi di tingkat Desa dan Kelurahan.
(3) Pelaksana sebagaimana dimaksud pada ayat (2) huruf c terdiri atas:
a. FPRB;
b. Tim Relawan Penanggulangan Bencana; dan/atau
c. organisasi lainnya.
(4) Organisasi sebagaimana dimaksud pada ayat (3) huruf c merupakan organisasi yang berada di wilayah Desa dan Kelurahan yang melaksanakan program dan pengelolaan sumber daya secara harmonis dan tersinkronisasi.
(5) Pelaksana sebagaimana dimaksud pada ayat (2) melakukan pengelolaan sumber daya, harmonisasi, dan sinkronisasi meliputi:
a. fasilitasi dukungan inisiatif Pengelolaan Risiko Bencana;
b. dorongan pengembangan keberlanjutan dan kualitas ketangguhan masyarakat;
c. dorongan upaya pembelajaran kolektif para pemangku kepentingan dalam Pengelolaan Risiko Bencana;
d. dorongan peningkatan kerja sama dan koordinasi para pemangku kepentingan dalam kegiatan Pengelolaan Risiko Bencana berkelanjutan di semua tahapan penanggulangan bencana; dan
e. koordinasi dengan pendukung Program Destana.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5261, 'perban-7-2025', 8, 'pasal', 'Pasal 5', 'BAB III PENYELENGGARAAN', 4, '(1) Pendukung sebagaimana dimaksud dalam Pasal 3 huruf b merupakan pihak yang membantu pelaksanaan kegiatan untuk mencapai tujuan Destana.
(2) Pendukung sebagaimana dimaksud pada ayat (1) terdiri atas:
a. kementerian/lembaga pemerintah nonkementerian;
b. pemerintah daerah;
c. lembaga usaha;
d. perguruan tinggi serta lembaga pendidikan dan pelatihan lainnya; dan
e. organisasi nonpemerintah, organisasi non-pemerintah internasional, dan organisasi internasional.
(3) Pendukung Program Destana sebagaimana dimaksud pada ayat (2) mempunyai tugas:
a. memfasilitasi;
b. menginisiasi; dan/atau
c. mengakselerasi, tercapainya tujuan Destana melalui dukungan teknis, peralatan, teknologi, pendampingan, pembiayaan, dan/atau dukungan lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5261, '(1) Pendukung sebagaimana dimaksud dalam Pasal 3 huruf b merupakan pihak yang membantu pelaksanaan kegiatan untuk mencapai tujuan Destana.
(2) Pendukung sebagaimana dimaksud pada ayat (1) terdiri atas:
a. kementerian/lembaga pemerintah nonkementerian;
b. pemerintah daerah;
c. lembaga usaha;
d. perguruan tinggi serta lembaga pendidikan dan pelatihan lainnya; dan
e. organisasi nonpemerintah, organisasi non-pemerintah internasional, dan organisasi internasional.
(3) Pendukung Program Destana sebagaimana dimaksud pada ayat (2) mempunyai tugas:
a. memfasilitasi;
b. menginisiasi; dan/atau
c. mengakselerasi, tercapainya tujuan Destana melalui dukungan teknis, peralatan, teknologi, pendampingan, pembiayaan, dan/atau dukungan lainnya.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5262, 'perban-7-2025', 9, 'pasal', 'Pasal 6', 'BAB III PENYELENGGARAAN', 5, '(1) Untuk mencapai tujuan Destana sebagaimana dimaksud dalam Pasal 2 diselenggarakan Program Destana.
(2) Penyelenggaraan Program Destana sebagaimana dimaksud pada ayat (1) melalui tahapan:
a. persiapan;
b. pelaksanaan; dan
c. pendampingan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5262, '(1) Untuk mencapai tujuan Destana sebagaimana dimaksud dalam Pasal 2 diselenggarakan Program Destana.
(2) Penyelenggaraan Program Destana sebagaimana dimaksud pada ayat (1) melalui tahapan:
a. persiapan;
b. pelaksanaan; dan
c. pendampingan.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5263, 'perban-7-2025', 10, 'pasal', 'Pasal 7', 'BAB III PENYELENGGARAAN', 5, 'Persiapan sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf a dilaksanakan melalui tahapan:
a. perencanaan;
b. analisis kebutuhan;
c. orientasi wilayah kerja; dan
d. identifikasi pemangku kepentingan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5263, 'Persiapan sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf a dilaksanakan melalui tahapan:
a. perencanaan;
b. analisis kebutuhan;
c. orientasi wilayah kerja; dan
d. identifikasi pemangku kepentingan.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5264, 'perban-7-2025', 11, 'pasal', 'Pasal 8', 'BAB III PENYELENGGARAAN', 5, '(1) Pelaksanaan sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf b berupa aktivitas Program Destana terdiri atas:
a. pengintegrasian layanan dasar sektor pembangunan Desa dan Kelurahan dengan upaya Pengelolaan Risiko Bencana;
b. penyusunan peraturan dan kebijakan penanggulangan bencana tingkat Desa dan Kelurahan;
c. pengembangan tata kelola lokal pada pelaku lokal;
d. pengembangan kapasitas masyarakat Desa dan Kelurahan;
e. Penilaian Ketangguhan Desa dan Kelurahan;
f. identifikasi jenis dan karakteristik ancaman;
g. identifikasi kerentanan dan kapasitas aset berisiko;
h. pembentukan FPRB Desa dan Kelurahan;
i. pembentukan Tim Relawan Penanggulangan Bencana;
j. identifikasi sumber daya dan pengetahuan lokal;
k. penilaian risiko bencana;
l. membangun jejaring kemitraan;
m. perencanaan penanggulangan bencana berbasis masyarakat;
n. pelaksanaan rencana penanggulangan bencana berbasis masyarakat;
o. pengintegrasian rencana penanggulangan bencana dalam perencanaan pembangunan lokal;
p. perencanaan penanggulangan kedaruratan bencana berbasis masyarakat; dan
q. peningkatan kapasitas akses sumber daya, pembiayaan, teknologi, dan informasi penanggulangan bencana berbasis masyarakat.
(2) Aktivitas Program Destana sebagaimana dimaksud pada ayat (1) dapat dilaksanakan pada tingkat:
a. individu;
b. keluarga;
c. pemukiman;
d. sarana pendidikan;
e. tempat ibadah;
f. layanan kesehatan;
g. perkantoran;
h. pusat perniagaan; dan
i. objek vital lainnya.');
