INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5265, 'perban-7-2025', 12, 'pasal', 'Pasal 9', 'BAB III PENYELENGGARAAN', 6, 'Pelaksanaan Program Destana sebagaimana dimaksud dalam Pasal 8 ayat (1) dapat dilaksanakan secara kolaboratif bersama dengan pendukung.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5265, 'Pelaksanaan Program Destana sebagaimana dimaksud dalam Pasal 8 ayat (1) dapat dilaksanakan secara kolaboratif bersama dengan pendukung.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5266, 'perban-7-2025', 13, 'pasal', 'Pasal 10', 'BAB III PENYELENGGARAAN', 6, 'Pelaksanaan Program Destana sebagaimana dimaksud dalam Pasal 8 ayat (1) dan Pasal 9 dilaksanakan sesuai dengan muatan lokal, entitas adat, dan/atau desa adat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5266, 'Pelaksanaan Program Destana sebagaimana dimaksud dalam Pasal 8 ayat (1) dan Pasal 9 dilaksanakan sesuai dengan muatan lokal, entitas adat, dan/atau desa adat.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5267, 'perban-7-2025', 14, 'pasal', 'Pasal 11', 'BAB III PENYELENGGARAAN', 6, 'Pendampingan sebagaimana dimaksud dalam Pasal 6 ayat
(2) huruf c dilaksanakan melalui:
a. pemantauan keberlanjutan program;
b. peningkatan kapasitas lanjutan;
c. bantuan teknis dan konsultasi;
d. penyebaran hasil dan pembelajaran;
e. evaluasi dampak jangka panjang; dan/atau
f. peningkatan kolaborasi antar pihak.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5267, 'Pendampingan sebagaimana dimaksud dalam Pasal 6 ayat
(2) huruf c dilaksanakan melalui:
a. pemantauan keberlanjutan program;
b. peningkatan kapasitas lanjutan;
c. bantuan teknis dan konsultasi;
d. penyebaran hasil dan pembelajaran;
e. evaluasi dampak jangka panjang; dan/atau
f. peningkatan kolaborasi antar pihak.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5268, 'perban-7-2025', 15, 'pasal', 'Pasal 12', 'BAB III PENYELENGGARAAN', 6, 'Pedoman penyelenggaraan Program Destana sebagaimana dimaksud dalam Pasal 7, Pasal 8, dan Pasal 10 ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5268, 'Pedoman penyelenggaraan Program Destana sebagaimana dimaksud dalam Pasal 7, Pasal 8, dan Pasal 10 ditetapkan oleh Kepala BNPB.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5269, 'perban-7-2025', 16, 'pasal', 'Pasal 13', 'BAB IV PENILAIAN', 6, '(1) Dalam rangka menjaga kualitas, pelaksanaan Destana dan Program Destana berdasarkan indikator dasar dan indikator capaian.
(2) Pelaksanaan Destana dan Program Destana sebagaimana dimaksud pada ayat (1) sesuai dengan Standar Nasional Indonesia.
(3) Standar Nasional Indonesia sebagaimana dimaksud pada ayat (1) menjadi indikator Destana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5269, '(1) Dalam rangka menjaga kualitas, pelaksanaan Destana dan Program Destana berdasarkan indikator dasar dan indikator capaian.
(2) Pelaksanaan Destana dan Program Destana sebagaimana dimaksud pada ayat (1) sesuai dengan Standar Nasional Indonesia.
(3) Standar Nasional Indonesia sebagaimana dimaksud pada ayat (1) menjadi indikator Destana.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5270, 'perban-7-2025', 17, 'pasal', 'Pasal 14', 'BAB IV PENILAIAN', 7, '(1) Untuk mengukur tingkat ketangguhan Desa dan Kelurahan yang dilaksanakan sesuai tahapan penyelenggaraan Program Destana sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf b, dapat dilakukan Penilaian Ketangguhan Desa dan Kelurahan.
(2) Penilaian Ketangguhan Desa dan Kelurahan sebagaimana dimaksud pada ayat (1) menjadi acuan penetapan tingkat ketangguhan.
(3) Penilaian sebagaimana dimaksud pada ayat (1) menghasilkan rekomendasi.
(4) Penilaian sebagaimana dimaksud pada ayat (1) dilakukan secara mandiri oleh Desa dan Kelurahan.
(5) Penilaian sebagaimana dimaksud pada ayat (1) dilakukan paling sedikit setiap 3 (tiga) tahun.
(6) Penetapan tingkat ketangguhan sebagaimana dimaksud pada ayat (2), meliputi:
a. Desa dan Kelurahan tangguh utama;
b. Desa dan Kelurahan tangguh madya; dan
c. Desa dan Kelurahan tangguh pratama.
(7) Rekomendasi sebagaimana dimaksud pada ayat (3) ditindaklanjuti oleh Desa dan Kelurahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5270, '(1) Untuk mengukur tingkat ketangguhan Desa dan Kelurahan yang dilaksanakan sesuai tahapan penyelenggaraan Program Destana sebagaimana dimaksud dalam Pasal 6 ayat (2) huruf b, dapat dilakukan Penilaian Ketangguhan Desa dan Kelurahan.
(2) Penilaian Ketangguhan Desa dan Kelurahan sebagaimana dimaksud pada ayat (1) menjadi acuan penetapan tingkat ketangguhan.
(3) Penilaian sebagaimana dimaksud pada ayat (1) menghasilkan rekomendasi.
(4) Penilaian sebagaimana dimaksud pada ayat (1) dilakukan secara mandiri oleh Desa dan Kelurahan.
(5) Penilaian sebagaimana dimaksud pada ayat (1) dilakukan paling sedikit setiap 3 (tiga) tahun.
(6) Penetapan tingkat ketangguhan sebagaimana dimaksud pada ayat (2), meliputi:
a. Desa dan Kelurahan tangguh utama;
b. Desa dan Kelurahan tangguh madya; dan
c. Desa dan Kelurahan tangguh pratama.
(7) Rekomendasi sebagaimana dimaksud pada ayat (3) ditindaklanjuti oleh Desa dan Kelurahan.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5271, 'perban-7-2025', 18, 'pasal', 'Pasal 15', 'BAB IV PENILAIAN', 7, 'Rekomendasi sebagaimana dimaksud dalam Pasal 14 ayat
(7) digunakan untuk perencanaan pembangunan secara berkelanjutan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5271, 'Rekomendasi sebagaimana dimaksud dalam Pasal 14 ayat
(7) digunakan untuk perencanaan pembangunan secara berkelanjutan.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5272, 'perban-7-2025', 19, 'pasal', 'Pasal 16', 'BAB V PEMANTAUAN DAN EVALUASI', 7, 'Pedoman Penilaian Ketangguhan Desa dan Kelurahan ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5272, 'Pedoman Penilaian Ketangguhan Desa dan Kelurahan ditetapkan oleh Kepala BNPB.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5273, 'perban-7-2025', 20, 'pasal', 'Pasal 17', 'BAB V PEMANTAUAN DAN EVALUASI', 7, '(1) Terhadap penyelenggaraan Program Destana dilakukan:
a. pemantauan; dan
b. evaluasi.
(2) Pemantauan dan evaluasi sebagaimana dimaksud pada ayat (1) dilakukan oleh:
a. Desa dan Kelurahan;
b. kecamatan;
c. BPBD kabupaten/kota;
d. BPBD provinsi; dan
e. BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5273, '(1) Terhadap penyelenggaraan Program Destana dilakukan:
a. pemantauan; dan
b. evaluasi.
(2) Pemantauan dan evaluasi sebagaimana dimaksud pada ayat (1) dilakukan oleh:
a. Desa dan Kelurahan;
b. kecamatan;
c. BPBD kabupaten/kota;
d. BPBD provinsi; dan
e. BNPB.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5274, 'perban-7-2025', 21, 'pasal', 'Pasal 18', 'BAB V PEMANTAUAN DAN EVALUASI', 8, '(1) Pemantauan sebagaimana dimaksud dalam Pasal 17 ayat (1) huruf a dapat dilakukan melalui kunjungan dan/atau melalui rapat koordinasi pemantauan penyelenggaraan sesuai dengan kewenangannya.
(2) Pemantauan sebagaimana dimaksud pada ayat (1) dilakukan secara berkala dan/atau sewaktu-waktu apabila diperlukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5274, '(1) Pemantauan sebagaimana dimaksud dalam Pasal 17 ayat (1) huruf a dapat dilakukan melalui kunjungan dan/atau melalui rapat koordinasi pemantauan penyelenggaraan sesuai dengan kewenangannya.
(2) Pemantauan sebagaimana dimaksud pada ayat (1) dilakukan secara berkala dan/atau sewaktu-waktu apabila diperlukan.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5275, 'perban-7-2025', 22, 'pasal', 'Pasal 19', 'BAB VI SISTEM INFORMASI', 8, '(1) Evaluasi sebagaimana dimaksud dalam Pasal 17 ayat
(1) huruf b dapat dilakukan berdasarkan hasil Penilaian Ketangguhan Desa dan Kelurahan dan/atau hasil pemantauan.
(2) Evaluasi sebagaimana dimaksud pada ayat (1) dilakukan minimal 1 (satu) kali dalam kurun waktu 1 (satu) tahun.
(3) Hasil evaluasi sebagaimana dimaksud ayat (1) berupa laporan penyelenggaraan Program Destana.
(4) Laporan penyelenggaraan Program Destana disampaikan oleh pejabat pimpinan tinggi madya di bidang pencegahan kepada Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5275, '(1) Evaluasi sebagaimana dimaksud dalam Pasal 17 ayat
(1) huruf b dapat dilakukan berdasarkan hasil Penilaian Ketangguhan Desa dan Kelurahan dan/atau hasil pemantauan.
(2) Evaluasi sebagaimana dimaksud pada ayat (1) dilakukan minimal 1 (satu) kali dalam kurun waktu 1 (satu) tahun.
(3) Hasil evaluasi sebagaimana dimaksud ayat (1) berupa laporan penyelenggaraan Program Destana.
(4) Laporan penyelenggaraan Program Destana disampaikan oleh pejabat pimpinan tinggi madya di bidang pencegahan kepada Kepala BNPB.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2025 tentang Desa dan Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5276, 'perban-7-2025', 23, 'pasal', 'Pasal 20', 'BAB VII PENDANAAN', 8, '(1) Dalam rangka mendukung pelaksanaan Program Destana, pemantauan, dan evaluasi capaian Program Destana menggunakan Sistem Informasi.
(2) Sistem informasi sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai prinsip satu data.
(3) Sistem informasi sebagaimana dimaksud pada ayat (1) memuat:
a. informasi umum terkait Destana;
b. sebaran lokasi pelaksanaan program Destana;
c. Penilaian Ketangguhan Desa dan Kelurahan;
d. sumber daya fasilitator; dan
e. referensi pembelajaran ketangguhan secara umum.
(4) Sistem informasi sebagaimana dimaksud pada ayat (2) dimanfaatkan oleh:
a. kementerian/lembaga pemerintah nonkementerian;
b. pemerintah daerah;
c. pemerintah Desa dan Kelurahan;
d. lembaga usaha;
e. perguruan tinggi serta lembaga pendidikan dan pelatihan;
f. organisasi masyarakat;
g. organisasi nonpemerintah; dan/atau
h. pihak lain yang melaksanakan atau mendukung Program Destana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5276, '(1) Dalam rangka mendukung pelaksanaan Program Destana, pemantauan, dan evaluasi capaian Program Destana menggunakan Sistem Informasi.
(2) Sistem informasi sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai prinsip satu data.
(3) Sistem informasi sebagaimana dimaksud pada ayat (1) memuat:
