INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5277, 'perban-7-2025', 24, 'pasal', 'Pasal 21', 'BAB VIII KETENTUAN PENUTUP', 9, 'Pendanaan penyelenggaraan Program Destana bersumber dari:
a. Anggaran Pendapatan dan Belanja Negara;
b. Anggaran Pendapatan dan Belanja Daerah;
c. Anggaran Pendapatan dan Belanja Desa; dan
d. sumber pendanaan lainnya yang sah sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5277, 'Pendanaan penyelenggaraan Program Destana bersumber dari:
