INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5295, 'perban-8-2020', 14, 'pasal', 'Pasal 305', NULL, 9, '(1) Kelompok Jabatan Fungsional mempunyai tugas memberikan pelayanan fungsional dalam pelaksanaan tugas dan fungsi jabatan pimpinan tinggi pratama sesuai dengan bidang keahlian dan keterampilan.
(2) Dalam pelaksanaan tugas sebagaimana dimaksud pada ayat (1) ditetapkan Koordinator Pelaksana Fungsi Pelayanan Fungsional sesuai dengan ruang lingkup bidang tugas dan fungsi jabatan pimpinan tinggi pratama masing-masing.
(3) Koordinator Pelaksana Fungsi Pelayanan Fungsional sebagaimana dimaksud pada ayat (2) mempunyai tugas mengoordinasikan dan mengelola kegiatan pelayanan fungsional sesuai dengan bidang tugas masing-masing.
97. 98.
99. (4) Ketentuan lebih lanjut mengenai pembagian tugas Koordinator Pelaksana Fungsi Pelayanan Fungsional ditetapkan oleh Kepala Badan.
Di antara Pasal 305 dan Pasal 306 disisipkan 1 (satu) pasal yakni Pasal 305A, sehingga berbunyi sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5295, '(1) Kelompok Jabatan Fungsional mempunyai tugas memberikan pelayanan fungsional dalam pelaksanaan tugas dan fungsi jabatan pimpinan tinggi pratama sesuai dengan bidang keahlian dan keterampilan.
(2) Dalam pelaksanaan tugas sebagaimana dimaksud pada ayat (1) ditetapkan Koordinator Pelaksana Fungsi Pelayanan Fungsional sesuai dengan ruang lingkup bidang tugas dan fungsi jabatan pimpinan tinggi pratama masing-masing.
(3) Koordinator Pelaksana Fungsi Pelayanan Fungsional sebagaimana dimaksud pada ayat (2) mempunyai tugas mengoordinasikan dan mengelola kegiatan pelayanan fungsional sesuai dengan bidang tugas masing-masing.
97. 98.
99. (4) Ketentuan lebih lanjut mengenai pembagian tugas Koordinator Pelaksana Fungsi Pelayanan Fungsional ditetapkan oleh Kepala Badan.
Di antara Pasal 305 dan Pasal 306 disisipkan 1 (satu) pasal yakni Pasal 305A, sehingga berbunyi sebagai berikut:', 'Pasal 305', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5296, 'perban-8-2020', 15, 'pasal', 'Pasal 305A', NULL, 10, '(1) Kelompok Jabatan Fungsional sebagaimana dimaksud dalam Pasal 305, terdiri atas berbagai jenis jabatan fungsional sesuai dengan bidang keahliannya yang pengangkatannya sesuai dengan ketentuan peraturan perundang-undangan.
(2) Jumlah Kelompok Jabatan Fungsional sebagaimana dimaksud pada ayat (1), ditentukan berdasarkan kebutuhan yang didasarkan pada analisis jabatan dan beban kerja.
(3) Tugas, jenis, dan jenjang Kelompok Jabatan Fungsional sebagaimana dimaksud pada ayat (1) diatur lebih lanjut dalam peraturan perundang-undangan yang mengatur jabatan fungsional masing-masing.
Ketentuan Pasal 309 diubah sehingga berbunyi sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5296, '(1) Kelompok Jabatan Fungsional sebagaimana dimaksud dalam Pasal 305, terdiri atas berbagai jenis jabatan fungsional sesuai dengan bidang keahliannya yang pengangkatannya sesuai dengan ketentuan peraturan perundang-undangan.
(2) Jumlah Kelompok Jabatan Fungsional sebagaimana dimaksud pada ayat (1), ditentukan berdasarkan kebutuhan yang didasarkan pada analisis jabatan dan beban kerja.
(3) Tugas, jenis, dan jenjang Kelompok Jabatan Fungsional sebagaimana dimaksud pada ayat (1) diatur lebih lanjut dalam peraturan perundang-undangan yang mengatur jabatan fungsional masing-masing.
Ketentuan Pasal 309 diubah sehingga berbunyi sebagai berikut:', 'Pasal 305A', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5297, 'perban-8-2020', 16, 'pasal', 'Pasal 309', NULL, 10, 'Setiap pimpinan satuan organisasi di lingkungan unsur pelaksana bertanggung jawab memimpin dan mengoordinasikan bawahan dan kelompok jabatan fungsional pada satuan organisasi masing-masing dan memberikan pengarahan serta petunjuk bagi pelaksanaan tugasnya.
Ketentuan Pasal 317 tetap, dan lampiran diubah sebagaimana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.
100. Ketentuan Pasal 318 diubah sehingga berbunyi sebagai berikut:');
