101. Ketentuan Pasal 319 diubah sehingga berbunyi sebagai berikut:', 'Pasal 318', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5299, 'perban-8-2020', 18, 'pasal', 'Pasal 319', NULL, 11, 'Pada saat Peraturan Badan ini mulai berlaku, semua Peraturan Badan Nasional Penanggulangan Bencana dinyatakan tetap berlaku sepanjang tidak bertentangan dengan ketentuan dalam Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5299, 'Pada saat Peraturan Badan ini mulai berlaku, semua Peraturan Badan Nasional Penanggulangan Bencana dinyatakan tetap berlaku sepanjang tidak bertentangan dengan ketentuan dalam Peraturan Badan ini.', 'Pasal 319', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5300, 'perban-8-2020', 19, 'pasal', 'Pasal II', NULL, 11, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan. s 12 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5300, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan. s 12 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal II', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
