INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5309, 'perban-8-2021', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk menindaklanjuti Pasal 24 ayat (2) Peraturan Pemerintah Nomor 69 Tahun 2020 tentang Tata Cara Penetapan Tarif atas Jenis Penerimaan Negara Bukan Pajak,
