BENNY RIYANTO BERITA NEGARA REPUBLIK INDONESIA TAHUN 2021 NOMOR 1504', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2021 tentang Besaran, Persyaratan dan Tata Cara Pengenaan Tarif Penerimaan Negara Bukan Pajak Sampai Dengan Nol Rupiah atau Nol Persen pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5324, 'perban-8-2021', 16, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5324, 'Salinan sesuai dengan aslinya BADAN NASIONAL PENANGGULANGAN BENCANA', 'Lampiran hal. 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2021 tentang Besaran, Persyaratan dan Tata Cara Pengenaan Tarif Penerimaan Negara Bukan Pajak Sampai Dengan Nol Rupiah atau Nol Persen pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5325, 'perban-8-2021', 17, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'LAMPIRAN I PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 8 TAHUN 2021 TENTANG BESARAN, PERSYARATAN DAN TATA CARA PENGENAAN TARIF PENERIMAAN NEGARA BUKAN PAJAK SAMPAI DENGAN NOL RUPIAH ATAU NOL PERSEN BESARAN TARIF YANG DIKENAI TARIF SAMPAI DENGAN NOL RUPIAH ATAU NOL PERSEN TARIF JENIS PENERIMAAN NEGARA BUKAN PAJAK | SATUAN (RUPIAH)
