INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5328, 'perban-8-2022', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5328, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5329, 'perban-8-2022', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk mengoptimalkan pelaksanaan tugas dan fungsi unsur pengarah penanggulangan bencana serta memenuhi kebutuhan persyaratan pemilihan unsur pengarah penanggulangan bencana yang berasal dari masyarakat profesional, perlu dilakukan perubahan terhadap pengaturan yang telah ada;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2009 tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana dan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional pada Badan Nasional Penanggulangan Bencana sudah tidak sesuai dengan perkembangan dan kebutuhan pengaturan, sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5329, 'a. bahwa untuk mengoptimalkan pelaksanaan tugas dan fungsi unsur pengarah penanggulangan bencana serta memenuhi kebutuhan persyaratan pemilihan unsur pengarah penanggulangan bencana yang berasal dari masyarakat profesional, perlu dilakukan perubahan terhadap pengaturan yang telah ada;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2009 tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana dan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional pada Badan Nasional Penanggulangan Bencana sudah tidak sesuai dengan perkembangan dan kebutuhan pengaturan, sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5330, 'perban-8-2022', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 103) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5330, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
3. Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2019 Nomor 103) sebagaimana telah diubah dengan Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2020 tentang Perubahan atas Peraturan Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2019 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2020 Nomor 1461);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5331, 'perban-8-2022', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA CARA PEMILIHAN DAN TATA KERJA UNSUR PENGARAH PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5331, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA CARA PEMILIHAN DAN TATA KERJA UNSUR PENGARAH PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5332, 'perban-8-2022', 4, 'pasal', 'Pasal 1', 'BAB II KEDUDUKAN, TUGAS, DAN FUNGSI', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam Undang-Undang tentang penanggulangan bencana.
2. Unsur Pengarah Penanggulangan Bencana, yang selanjutnya disebut Unsur Pengarah adalah bagian/unsur BNPB yang memiliki tugas memberikan masukan dan saran kepada Kepala BNPB dalam penyelenggaraan penanggulangan bencana.
3. Masyarakat Profesional adalah para pakar/profesional dan/atau tokoh masyarakat yang memiliki pengetahuan, kemampuan, keahlian, dan pengalaman di bidang penanggulangan bencana.
4. Kepala BNPB yang selanjutnya disebut Kepala adalah pimpinan BNPB yang bertanggung jawab atas pelaksanaan tugas dan fungsi BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5332, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian sebagaimana dimaksud dalam Undang-Undang tentang penanggulangan bencana.
2. Unsur Pengarah Penanggulangan Bencana, yang selanjutnya disebut Unsur Pengarah adalah bagian/unsur BNPB yang memiliki tugas memberikan masukan dan saran kepada Kepala BNPB dalam penyelenggaraan penanggulangan bencana.
3. Masyarakat Profesional adalah para pakar/profesional dan/atau tokoh masyarakat yang memiliki pengetahuan, kemampuan, keahlian, dan pengalaman di bidang penanggulangan bencana.
4. Kepala BNPB yang selanjutnya disebut Kepala adalah pimpinan BNPB yang bertanggung jawab atas pelaksanaan tugas dan fungsi BNPB.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5333, 'perban-8-2022', 5, 'pasal', 'Pasal 2', 'BAB II KEDUDUKAN, TUGAS, DAN FUNGSI', 2, 'Unsur Pengarah berada di bawah dan bertanggung jawab kepada Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5333, 'Unsur Pengarah berada di bawah dan bertanggung jawab kepada Kepala.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5334, 'perban-8-2022', 6, 'pasal', 'Pasal 3', 'BAB II KEDUDUKAN, TUGAS, DAN FUNGSI', 2, 'Unsur Pengarah mempunyai tugas memberikan masukan dan saran kepada Kepala dalam penyelenggaraan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5334, 'Unsur Pengarah mempunyai tugas memberikan masukan dan saran kepada Kepala dalam penyelenggaraan penanggulangan bencana.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5335, 'perban-8-2022', 7, 'pasal', 'Pasal 4', 'BAB III SUSUNAN ORGANISASI', 2, 'Unsur Pengarah menyelenggarakan fungsi:
a. perumusan konsep kebijakan penanggulangan bencana nasional;
b. pemantauan; dan
c. evaluasi dalam penyelenggaraan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5335, 'Unsur Pengarah menyelenggarakan fungsi:
a. perumusan konsep kebijakan penanggulangan bencana nasional;
b. pemantauan; dan
c. evaluasi dalam penyelenggaraan penanggulangan bencana.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5336, 'perban-8-2022', 8, 'pasal', 'Pasal 5', 'BAB IV TATA CARA PENGISIAN KEANGGOTAAN; Bagian Kesatu Anggota dari Instansi Pemerintah', 3, '(1) Susunan organisasi Unsur Pengarah terdiri atas:
a. ketua; dan
b. anggota.
(2) Ketua sebagaimana dimaksud pada ayat (1) huruf a dijabat oleh Kepala.
(3) Anggota sebagaimana dimaksud pada ayat (1) huruf b terdiri atas:
a. 11 (sebelas) pejabat eselon I.a dan eselon I.b atau setara pejabat pimpinan tinggi madya, yang diusulkan oleh Pimpinan Instansi Pemerintah; dan
b. 9 (sembilan) anggota Masyarakat Profesional.
(4) Anggota sebagaimana dimaksud pada ayat (3) huruf a mewakili:
a. Kementerian Koordinator Bidang Pembangunan Manusia dan Kebudayaan;
b. Kementerian Koordinator Bidang Politik, Hukum, dan Keamanan;
c. Kementerian Dalam Negeri;
d. Kementerian Keuangan;
e. Kementerian Kesehatan;
f. Kementerian Sosial;
g. Kementerian Energi dan Sumber Daya Mineral;
h. Kementerian Pekerjaan Umum dan Perumahan Rakyat;
i. Kementerian Perhubungan;
j. Kepolisian Negara Republik Indonesia; dan
k. Tentara Nasional Indonesia.
(5) Anggota sebagaimana dimaksud pada ayat (3) huruf b berasal dari para pakar/profesional dan/atau tokoh masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5336, '(1) Susunan organisasi Unsur Pengarah terdiri atas:
a. ketua; dan
b. anggota.
(2) Ketua sebagaimana dimaksud pada ayat (1) huruf a dijabat oleh Kepala.
(3) Anggota sebagaimana dimaksud pada ayat (1) huruf b terdiri atas:
a. 11 (sebelas) pejabat eselon I.a dan eselon I.b atau setara pejabat pimpinan tinggi madya, yang diusulkan oleh Pimpinan Instansi Pemerintah; dan
b. 9 (sembilan) anggota Masyarakat Profesional.
(4) Anggota sebagaimana dimaksud pada ayat (3) huruf a mewakili:
a. Kementerian Koordinator Bidang Pembangunan Manusia dan Kebudayaan;
b. Kementerian Koordinator Bidang Politik, Hukum, dan Keamanan;
c. Kementerian Dalam Negeri;
d. Kementerian Keuangan;
e. Kementerian Kesehatan;
f. Kementerian Sosial;
g. Kementerian Energi dan Sumber Daya Mineral;
h. Kementerian Pekerjaan Umum dan Perumahan Rakyat;
i. Kementerian Perhubungan;
j. Kepolisian Negara Republik Indonesia; dan
k. Tentara Nasional Indonesia.
(5) Anggota sebagaimana dimaksud pada ayat (3) huruf b berasal dari para pakar/profesional dan/atau tokoh masyarakat.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5337, 'perban-8-2022', 9, 'pasal', 'Pasal 6', 'BAB IV TATA CARA PENGISIAN KEANGGOTAAN; Bagian Kedua Anggota Masyarakat Profesional', 3, '(1) Kepala menyampaikan permohonan pengisian keanggotaan Unsur Pengarah dari Instansi Pemerintah kepada pimpinan kementerian/lembaga.
(2) Calon anggota Unsur Pengarah sebagaimana dimaksud pada ayat (1) diusulkan oleh Pimpinan Instansi Pemerintah.
(3) Kepala menyampaikan usulan calon anggota Unsur Pengarah dari Instansi Pemerintah sebagaimana dimaksud pada ayat (2) kepada Presiden.
(4) Unsur Pengarah dari Instansi Pemerintah sebagaimana dimaksud pada ayat (3) ditetapkan oleh Presiden.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5337, '(1) Kepala menyampaikan permohonan pengisian keanggotaan Unsur Pengarah dari Instansi Pemerintah kepada pimpinan kementerian/lembaga.
(2) Calon anggota Unsur Pengarah sebagaimana dimaksud pada ayat (1) diusulkan oleh Pimpinan Instansi Pemerintah.
(3) Kepala menyampaikan usulan calon anggota Unsur Pengarah dari Instansi Pemerintah sebagaimana dimaksud pada ayat (2) kepada Presiden.
(4) Unsur Pengarah dari Instansi Pemerintah sebagaimana dimaksud pada ayat (3) ditetapkan oleh Presiden.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5338, 'perban-8-2022', 10, 'pasal', 'Pasal 7', 'BAB IV TATA CARA PENGISIAN KEANGGOTAAN; Bagian Kedua Anggota Masyarakat Profesional', 4, 'Calon anggota Unsur Pengarah dari Masyarakat Profesional harus memenuhi persyaratan:
a. Warga Negara Indonesia;
b. sehat jasmani dan rohani;
c. berkelakuan baik;
d. usia paling rendah 45 (empat puluh lima) tahun dan paling tinggi 65 (enam puluh lima) tahun;
e. memiliki wawasan kebangsaan;
f. memiliki pengetahuan dan pengalaman dalam penanggulangan bencana paling singkat 10 (sepuluh) tahun;
g. memiliki kemampuan berbahasa Inggris;
h. berpendidikan paling rendah Magister (S2);
i. memiliki integritas tinggi;
j. tidak pernah dipidana dengan pidana penjara berdasarkan putusan pengadilan yang sudah mempunyai kekuatan hukum tetap karena melakukan tindak pidana dengan pidana penjara 5 (lima) tahun atau lebih; dan
k. nonpartisan partai politik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5338, 'Calon anggota Unsur Pengarah dari Masyarakat Profesional harus memenuhi persyaratan:
a. Warga Negara Indonesia;
b. sehat jasmani dan rohani;
c. berkelakuan baik;
d. usia paling rendah 45 (empat puluh lima) tahun dan paling tinggi 65 (enam puluh lima) tahun;
e. memiliki wawasan kebangsaan;
f. memiliki pengetahuan dan pengalaman dalam penanggulangan bencana paling singkat 10 (sepuluh) tahun;
g. memiliki kemampuan berbahasa Inggris;
h. berpendidikan paling rendah Magister (S2);
i. memiliki integritas tinggi;
j. tidak pernah dipidana dengan pidana penjara berdasarkan putusan pengadilan yang sudah mempunyai kekuatan hukum tetap karena melakukan tindak pidana dengan pidana penjara 5 (lima) tahun atau lebih; dan
k. nonpartisan partai politik.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5339, 'perban-8-2022', 11, 'pasal', 'Pasal 8', 'BAB IV TATA CARA PENGISIAN KEANGGOTAAN; Bagian Kedua Anggota Masyarakat Profesional', 4, '(1) Persyaratan calon anggota Unsur Pengarah yang berasal dari Masyarakat Profesional sebagaimana dimaksud dalam Pasal 7 dibuktikan dengan dokumen:
a. kartu tanda penduduk/paspor;
b. surat keterangan sehat jasmani dari rumah sakit pemerintah;
c. surat keterangan bebas narkotika dan psikotropika dari rumah sakit pemerintah;
d. surat keterangan catatan kepolisian;
e. daftar riwayat pengalaman terkait penanggulangan bencana paling singkat 10 (sepuluh) tahun;
f. ijazah pendidikan terakhir; dan
g. surat pernyataan nonpartisan partai politik.
(2) Dokumen sebagaimana dimaksud pada ayat (1) dapat dilengkapi sertifikat TOEFL dengan skor paling rendah 500.
(3) Format surat pernyataan sebagaimana dimaksud pada ayat (1) huruf h tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5339, '(1) Persyaratan calon anggota Unsur Pengarah yang berasal dari Masyarakat Profesional sebagaimana dimaksud dalam Pasal 7 dibuktikan dengan dokumen:
a. kartu tanda penduduk/paspor;
b. surat keterangan sehat jasmani dari rumah sakit pemerintah;
c. surat keterangan bebas narkotika dan psikotropika dari rumah sakit pemerintah;
d. surat keterangan catatan kepolisian;
e. daftar riwayat pengalaman terkait penanggulangan bencana paling singkat 10 (sepuluh) tahun;
f. ijazah pendidikan terakhir; dan
g. surat pernyataan nonpartisan partai politik.
(2) Dokumen sebagaimana dimaksud pada ayat (1) dapat dilengkapi sertifikat TOEFL dengan skor paling rendah 500.
(3) Format surat pernyataan sebagaimana dimaksud pada ayat (1) huruf h tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Badan ini.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5340, 'perban-8-2022', 12, 'pasal', 'Pasal 9', 'BAB IV TATA CARA PENGISIAN KEANGGOTAAN; Bagian Kedua Anggota Masyarakat Profesional', 4, 'Pemilihan calon anggota Unsur Pengarah yang berasal dari Masyarakat Profesional dilaksanakan oleh panitia seleksi dengan dibantu oleh lembaga independen yang bersertifikasi di bidang sumber daya manusia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5340, 'Pemilihan calon anggota Unsur Pengarah yang berasal dari Masyarakat Profesional dilaksanakan oleh panitia seleksi dengan dibantu oleh lembaga independen yang bersertifikasi di bidang sumber daya manusia.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5341, 'perban-8-2022', 13, 'pasal', 'Pasal 10', 'BAB IV TATA CARA PENGISIAN KEANGGOTAAN; Bagian Kedua Anggota Masyarakat Profesional', 5, '(1) Panitia seleksi sebagaimana dimaksud dalam Pasal 9 bertugas:
a. menyusun dan menetapkan jadwal dan tahapan pemilihan;
b. menentukan metode seleksi dan menyusun materi seleksi;
c. menentukan sistem yang digunakan pada setiap tahapan pemilihan;
d. menentukan kriteria penilaian seleksi administrasi dan seleksi kompetensi;
e. mengumumkan lowongan dan persyaratan;
f. menetapkan lembaga independen;
g. melakukan seleksi administrasi dan seleksi kompetensi; dan
h. menyusun dan menyampaikan laporan hasil seleksi kepada Kepala.
(2) Panitia seleksi sebagaimana dimaksud pada ayat (1) terdiri dari unsur:
a. BNPB;
b. akademisi; dan
c. praktisi.
(3) Panitia seleksi sebagaimana dimaksud pada ayat (2) berjumlah gasal paling banyak 9 (sembilan) orang.
(4) Panitia seleksi sebagaimana dimaksud ayat (2) ditetapkan oleh Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5341, '(1) Panitia seleksi sebagaimana dimaksud dalam Pasal 9 bertugas:
a. menyusun dan menetapkan jadwal dan tahapan pemilihan;
b. menentukan metode seleksi dan menyusun materi seleksi;
c. menentukan sistem yang digunakan pada setiap tahapan pemilihan;
d. menentukan kriteria penilaian seleksi administrasi dan seleksi kompetensi;
e. mengumumkan lowongan dan persyaratan;
f. menetapkan lembaga independen;
g. melakukan seleksi administrasi dan seleksi kompetensi; dan
h. menyusun dan menyampaikan laporan hasil seleksi kepada Kepala.
(2) Panitia seleksi sebagaimana dimaksud pada ayat (1) terdiri dari unsur:
a. BNPB;
b. akademisi; dan
c. praktisi.
(3) Panitia seleksi sebagaimana dimaksud pada ayat (2) berjumlah gasal paling banyak 9 (sembilan) orang.
(4) Panitia seleksi sebagaimana dimaksud ayat (2) ditetapkan oleh Kepala.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5342, 'perban-8-2022', 14, 'pasal', 'Pasal 11', 'BAB IV TATA CARA PENGISIAN KEANGGOTAAN; Bagian Kedua Anggota Masyarakat Profesional', 5, '(1) Lembaga independen sebagaimana dimaksud dalam Pasal 9 bertugas:
a. melakukan seleksi kompetensi; dan
b. menyampaikan hasil seleksi kompetensi kepada panitia seleksi.
(2) Lembaga independen sebagaimana dimaksud pada ayat (1) ditetapkan oleh ketua panitia seleksi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5342, '(1) Lembaga independen sebagaimana dimaksud dalam Pasal 9 bertugas:
a. melakukan seleksi kompetensi; dan
b. menyampaikan hasil seleksi kompetensi kepada panitia seleksi.
(2) Lembaga independen sebagaimana dimaksud pada ayat (1) ditetapkan oleh ketua panitia seleksi.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5343, 'perban-8-2022', 15, 'pasal', 'Pasal 12', 'BAB IV TATA CARA PENGISIAN KEANGGOTAAN; Bagian Kedua Anggota Masyarakat Profesional', 5, '(1) Lembaga independen sebagaimana dimaksud dalam Pasal 11 menyampaikan hasil seleksi kepada panitia seleksi.
(2) Hasil seleksi sebagaimana dimaksud pada ayat (1) berjumlah 2 (dua) kali lipat dari jumlah anggota Unsur Pengarah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5343, '(1) Lembaga independen sebagaimana dimaksud dalam Pasal 11 menyampaikan hasil seleksi kepada panitia seleksi.
(2) Hasil seleksi sebagaimana dimaksud pada ayat (1) berjumlah 2 (dua) kali lipat dari jumlah anggota Unsur Pengarah.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5344, 'perban-8-2022', 16, 'pasal', 'Pasal 13', 'BAB V PENGANGKATAN DAN PEMBERHENTIAN; Bagian Kesatu Pengangkatan', 5, '(1) Kepala menyampaikan hasil seleksi sebagaimana dimaksud dalam Pasal 12 ayat (2) kepada Presiden.
(2) Presiden menyampaikan usulan calon anggota Unsur Pengarah kepada Dewan Perwakilan Rakyat Republik Indonesia untuk dilakukan uji kepatutan dan kelayakan.
(3) Dewan Perwakilan Rakyat Republik Indonesia menyampaikan 9 (sembilan) calon anggota Unsur Pengarah yang dinyatakan lulus uji kepatutan dan kelayakan kepada Presiden.
(4) Calon anggota Unsur Pengarah yang telah dinyatakan lulus uji kepatutan dan kelayakan sebagaimana dimaksud pada ayat (3) ditetapkan oleh Presiden.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5344, '(1) Kepala menyampaikan hasil seleksi sebagaimana dimaksud dalam Pasal 12 ayat (2) kepada Presiden.
(2) Presiden menyampaikan usulan calon anggota Unsur Pengarah kepada Dewan Perwakilan Rakyat Republik Indonesia untuk dilakukan uji kepatutan dan kelayakan.
(3) Dewan Perwakilan Rakyat Republik Indonesia menyampaikan 9 (sembilan) calon anggota Unsur Pengarah yang dinyatakan lulus uji kepatutan dan kelayakan kepada Presiden.
(4) Calon anggota Unsur Pengarah yang telah dinyatakan lulus uji kepatutan dan kelayakan sebagaimana dimaksud pada ayat (3) ditetapkan oleh Presiden.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5345, 'perban-8-2022', 17, 'pasal', 'Pasal 14', 'BAB V PENGANGKATAN DAN PEMBERHENTIAN; Bagian Kedua Pemberhentian Antarwaktu dan Penggantian Antarwaktu', 6, '(1) Pengangkatan anggota Unsur Pengarah ditetapkan oleh Presiden.
(2) Anggota Unsur Pengarah diangkat untuk masa jabatan selama 5 (lima) tahun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5345, '(1) Pengangkatan anggota Unsur Pengarah ditetapkan oleh Presiden.
(2) Anggota Unsur Pengarah diangkat untuk masa jabatan selama 5 (lima) tahun.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5346, 'perban-8-2022', 18, 'pasal', 'Pasal 15', 'BAB V PENGANGKATAN DAN PEMBERHENTIAN; Bagian Kedua Pemberhentian Antarwaktu dan Penggantian Antarwaktu', 6, 'Anggota Unsur Pengarah diberhentikan antarwaktu karena:
a. meninggal dunia;
b. mengundurkan diri;
c. diberhentikan;
d. berhalangan tetap berturut-turut dalam kurun waktu 6 (enam) bulan;
e. menjadi anggota partai politik; dan
f. dipidana hukuman kurungan/penjara selama 1 (satu) tahun berdasarkan putusan pengadilan yang telah memperoleh kekuatan hukum tetap.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5346, 'Anggota Unsur Pengarah diberhentikan antarwaktu karena:
a. meninggal dunia;
b. mengundurkan diri;
c. diberhentikan;
d. berhalangan tetap berturut-turut dalam kurun waktu 6 (enam) bulan;
e. menjadi anggota partai politik; dan
f. dipidana hukuman kurungan/penjara selama 1 (satu) tahun berdasarkan putusan pengadilan yang telah memperoleh kekuatan hukum tetap.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5347, 'perban-8-2022', 19, 'pasal', 'Pasal 16', 'BAB V PENGANGKATAN DAN PEMBERHENTIAN; Bagian Kedua Pemberhentian Antarwaktu dan Penggantian Antarwaktu', 6, '(1) Kepala menyampaikan usulan nama yang berhenti antarwaktu sebagaimana dimaksud dalam Pasal 15 kepada Presiden.
(2) Penyampaian usulan nama sebagaimana dimaksud pada ayat (1) dilampiri dengan dokumen pendukung.
(3) Dokumen pendukung sebagaimana dimaksud pada ayat
(2) terdiri atas:
a. surat keterangan kematian;
b. surat pengunduran diri;
c. salinan surat keputusan pengangkatan dalam keanggotaan partai politik; dan/atau
d. salinan putusan pengadilan.
(4) Pemberhentian antarwaktu keanggotaan Unsur Pengarah sebagaimana dimaksud pada ayat (1) ditetapkan oleh Presiden.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5347, '(1) Kepala menyampaikan usulan nama yang berhenti antarwaktu sebagaimana dimaksud dalam Pasal 15 kepada Presiden.
(2) Penyampaian usulan nama sebagaimana dimaksud pada ayat (1) dilampiri dengan dokumen pendukung.
(3) Dokumen pendukung sebagaimana dimaksud pada ayat
(2) terdiri atas:
a. surat keterangan kematian;
b. surat pengunduran diri;
c. salinan surat keputusan pengangkatan dalam keanggotaan partai politik; dan/atau
d. salinan putusan pengadilan.
(4) Pemberhentian antarwaktu keanggotaan Unsur Pengarah sebagaimana dimaksud pada ayat (1) ditetapkan oleh Presiden.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5348, 'perban-8-2022', 20, 'pasal', 'Pasal 17', 'BAB V PENGANGKATAN DAN PEMBERHENTIAN; Bagian Kedua Pemberhentian Antarwaktu dan Penggantian Antarwaktu', 7, '(1) Penggantian antarwaktu anggota Unsur Pengarah merupakan proses penggantian anggota Unsur Pengarah yang berhenti antarwaktu untuk digantikan calon pengganti antarwaktu yang diambil dari calon anggota yang telah mengikuti uji kepatutan dan kelayakan sebagaimana dimaksud dalam Pasal 13 ayat (2).
(2) Masa jabatan anggota Unsur Pengarah pengganti antarwaktu sebagaimana dimaksud pada ayat (1) melanjutkan sisa masa jabatan anggota Unsur Pengarah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5348, '(1) Penggantian antarwaktu anggota Unsur Pengarah merupakan proses penggantian anggota Unsur Pengarah yang berhenti antarwaktu untuk digantikan calon pengganti antarwaktu yang diambil dari calon anggota yang telah mengikuti uji kepatutan dan kelayakan sebagaimana dimaksud dalam Pasal 13 ayat (2).
(2) Masa jabatan anggota Unsur Pengarah pengganti antarwaktu sebagaimana dimaksud pada ayat (1) melanjutkan sisa masa jabatan anggota Unsur Pengarah.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5349, 'perban-8-2022', 21, 'pasal', 'Pasal 18', 'BAB VI TATA KERJA', 7, '(1) Penggantian antar waktu dilaksanakan setelah berkonsultasi dan mendapat persetujuan dari Dewan Perwakilan Rakyat Republik Indonesia.
(2) Penggantian antarwaktu keanggotaan Unsur Pengarah ditetapkan oleh Presiden.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5349, '(1) Penggantian antar waktu dilaksanakan setelah berkonsultasi dan mendapat persetujuan dari Dewan Perwakilan Rakyat Republik Indonesia.
(2) Penggantian antarwaktu keanggotaan Unsur Pengarah ditetapkan oleh Presiden.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5350, 'perban-8-2022', 22, 'pasal', 'Pasal 19', 'BAB VI TATA KERJA', 7, 'Pelaksanaan tugas dan fungsi oleh anggota Unsur Pengarah dilakukan melalui mekanisme:
a. mengusulkan dan mengajukan konsep rumusan kebijakan penanggulangan bencana kepada Kepala;
b. melakukan pemantauan dan evaluasi penyelenggaraan penanggulangan bencana secara mandiri dan/atau secara bersama dengan unsur pelaksana penanggulangan bencana; dan
c. melakukan konsultasi secara periodik dan/atau sewaktu-waktu sesuai dengan kebutuhan bersama Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5350, 'Pelaksanaan tugas dan fungsi oleh anggota Unsur Pengarah dilakukan melalui mekanisme:
a. mengusulkan dan mengajukan konsep rumusan kebijakan penanggulangan bencana kepada Kepala;
b. melakukan pemantauan dan evaluasi penyelenggaraan penanggulangan bencana secara mandiri dan/atau secara bersama dengan unsur pelaksana penanggulangan bencana; dan
c. melakukan konsultasi secara periodik dan/atau sewaktu-waktu sesuai dengan kebutuhan bersama Kepala.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5351, 'perban-8-2022', 23, 'pasal', 'Pasal 20', 'BAB VI TATA KERJA', 7, '(1) Unsur Pengarah melaksanakan rapat secara berkala paling sedikit 1 (satu) kali dalam 1 (satu) bulan atau sewaktu-waktu sesuai kebutuhan.
(2) Dalam pelaksanaan rapat sebagaimana dimaksud pada ayat (1), Unsur Pengarah dapat mengikutsertakan wakil dari Instansi Pemerintah di luar Unsur Pengarah, pemerintah daerah, lembaga usaha, lembaga internasional, dan/atau pihak lain yang terkait.
(3) Hasil rapat sebagaimana dimaksud pada ayat (1) disampaikan kepada Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5351, '(1) Unsur Pengarah melaksanakan rapat secara berkala paling sedikit 1 (satu) kali dalam 1 (satu) bulan atau sewaktu-waktu sesuai kebutuhan.
(2) Dalam pelaksanaan rapat sebagaimana dimaksud pada ayat (1), Unsur Pengarah dapat mengikutsertakan wakil dari Instansi Pemerintah di luar Unsur Pengarah, pemerintah daerah, lembaga usaha, lembaga internasional, dan/atau pihak lain yang terkait.
(3) Hasil rapat sebagaimana dimaksud pada ayat (1) disampaikan kepada Kepala.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5352, 'perban-8-2022', 24, 'pasal', 'Pasal 21', 'BAB VII KETENTUAN PENUTUP', 7, 'Dalam pelaksanaan tugas dan fungsi Unsur Pengarah, dibantu oleh kesekretariatan yang berkedudukan pada unit kerja yang mempunyai tugas melaksanakan koordinasi urusan sumber daya manusia di lingkungan BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5352, 'Dalam pelaksanaan tugas dan fungsi Unsur Pengarah, dibantu oleh kesekretariatan yang berkedudukan pada unit kerja yang mempunyai tugas melaksanakan koordinasi urusan sumber daya manusia di lingkungan BNPB.', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5353, 'perban-8-2022', 25, 'pasal', 'Pasal 22', 'BAB VII KETENTUAN PENUTUP', 8, 'Pada saat Peraturan Badan ini mulai berlaku:
1. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2009 tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 1551); dan
2. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional pada Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 1858), dicabut dan dinyatakan tidak berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5353, 'Pada saat Peraturan Badan ini mulai berlaku:
1. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2009 tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 1551); dan
2. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional pada Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 1858), dicabut dan dinyatakan tidak berlaku.', 'Pasal 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5354, 'perban-8-2022', 26, 'pasal', 'Pasal 23', 'BAB VII KETENTUAN PENUTUP', 8, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5354, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2022 tentang Tata Cara Pemilihan dan Tata Kerja Unsur Pengarah Penanggulangan Bencana');
