INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5357, 'perban-8-2022', 29, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'LAMPIRAN PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 8 TAHUN 2022 TENTANG TATA CARA PEMILIHAN DAN TATA KERJA UNSUR PENGARAH PENANGGULANGAN BENCANA FORMAT SURAT PERNYATAAN NONPARTISAN PARTAI POLITIK SURAT PERNYATAAN Yang bertanda tangan di bawah ini:
Nama :
Tempat, tanggal lahir :
NIK :
Alamat : dengan ini menyatakan dengan sesungguhnya, bahwa saya tidak merupakan anggota atau pengurus partai politik atau terlibat politik praktis.
Demikian pernyataan ini saya buat dengan sesungguhnya, apabila dikemudian hari terbukti pernyataan saya ini tidak benar, maka saya bersedia menerima keputusan panitia membatalkan keikutsertaan/kelulusan saya pada Seleksi Unsur Pengarah Penanggulangan Bencana yang berasal dari Masyarakat Profesional dan/atau segala tindakan yang diambil oleh pemerintah sesuai ketentuan peraturan perundang-undangan.
(Tempat, tanggal) Yang menyatakan, Meterai Rp.10.000 (NAMA LENGKAP) KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
