INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5358, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5359, 'perban-8-2025', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk mewujudkan pengelolaan dokumen dan informasi hukum yang lengkap, akurat, mudah, dan cepat serta terpadu, efektif, dan efisien di Badan Nasional Penanggulangan Bencana, perlu mengatur penyelenggaraan jaringan dokumentasi dan informasi hukum di Badan Nasional Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, serta untuk melaksanakan ketentuan Pasal 5 ayat (1) Peraturan Presiden Nomor 33 Tahun 2012 tentang Jaringan Dokumentasi dan Informasi Hukum Nasional, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Jaringan Dokumentasi dan Informasi Hukum;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5359, 'a. bahwa untuk mewujudkan pengelolaan dokumen dan informasi hukum yang lengkap, akurat, mudah, dan cepat serta terpadu, efektif, dan efisien di Badan Nasional Penanggulangan Bencana, perlu mengatur penyelenggaraan jaringan dokumentasi dan informasi hukum di Badan Nasional Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, serta untuk melaksanakan ketentuan Pasal 5 ayat (1) Peraturan Presiden Nomor 33 Tahun 2012 tentang Jaringan Dokumentasi dan Informasi Hukum Nasional, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Jaringan Dokumentasi dan Informasi Hukum;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5360, 'perban-8-2025', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 33 Tahun 2012 tentang Jaringan Dokumentasi dan Informasi Hukum Nasional (Lembaran Negara Republik Indonesia Tahun 2012 Nomor 82);
3. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 8 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
4. Peraturan Menteri Hukum dan Hak Asasi Manusia Nomor 8 Tahun 2019 tentang Standar Pengelolaan Dokumen dan Informasi Hukum (Berita Negara Republik Indonesia Tahun 2019 Nomor 692);
5. Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 769);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5360, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 33 Tahun 2012 tentang Jaringan Dokumentasi dan Informasi Hukum Nasional (Lembaran Negara Republik Indonesia Tahun 2012 Nomor 82);
3. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 8 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
4. Peraturan Menteri Hukum dan Hak Asasi Manusia Nomor 8 Tahun 2019 tentang Standar Pengelolaan Dokumen dan Informasi Hukum (Berita Negara Republik Indonesia Tahun 2019 Nomor 692);
5. Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 769);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5361, 'perban-8-2025', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG JARINGAN DOKUMENTASI DAN INFORMASI HUKUM.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5361, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG JARINGAN DOKUMENTASI DAN INFORMASI HUKUM.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5362, 'perban-8-2025', 4, 'pasal', 'Pasal 1', 'BAB II ORGANISASI JARINGAN DOKUMENTASI DAN INFORMASI HUKUM BADAN NASIONAL PENANGGULANGAN BENCANA', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Jaringan Dokumentasi dan Informasi Hukum pada Badan Nasional Penanggulangan Bencana yang selanjutnya disebut JDIH BNPB adalah wadah pendayagunaan bersama atas dokumen hukum secara tertib, terpadu, dan berkesinambungan, serta merupakan sarana pemberian pelayanan informasi hukum secara lengkap, akurat, mudah, dan cepat.
2. Dokumen Hukum adalah produk hukum yang berupa peraturan perundang-undangan atau produk hukum selain peraturan perundang-undangan yang meliputi namun tidak terbatas pada putusan pengadilan, yurisprudensi, monografi hukum, artikel majalah hukum, buku hukum, penelitian hukum, pengkajian hukum, naskah akademis, dan rancangan peraturan perundang-undangan.
3. Informasi Hukum adalah semua data dan keterangan yang dimuat dalam Dokumen Hukum.
4. Pengelolaan Dokumentasi dan Informasi Hukum adalah kegiatan pengumpulan, pengolahan, penyimpanan, pelestarian, dan pendayagunaan informasi Dokumen Hukum.
5. Pusat Jaringan Dokumentasi dan Informasi Hukum Nasional yang selanjutnya disebut Pusat JDIHN adalah pusat jaringan yang bertugas melakukan pembinaan, pengembangan, dan monitoring kepada anggota jaringan dokumentasi dan Informasi Hukum nasional.
6. Pusat Jaringan Dokumentasi dan Informasi Hukum yang selanjutnya disebut Pusat JDIH adalah pusat jaringan dokumentasi dan Informasi Hukum di lingkungan Badan Nasional Penanggulangan Bencana.
7. Anggota Jaringan Dokumentasi dan Informasi Hukum yang selanjutnya disebut Anggota JDIH adalah anggota jaringan dokumentasi dan Informasi Hukum di lingkungan Badan Nasional Penanggulangan Bencana.
8. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintahan nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5362, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Jaringan Dokumentasi dan Informasi Hukum pada Badan Nasional Penanggulangan Bencana yang selanjutnya disebut JDIH BNPB adalah wadah pendayagunaan bersama atas dokumen hukum secara tertib, terpadu, dan berkesinambungan, serta merupakan sarana pemberian pelayanan informasi hukum secara lengkap, akurat, mudah, dan cepat.
2. Dokumen Hukum adalah produk hukum yang berupa peraturan perundang-undangan atau produk hukum selain peraturan perundang-undangan yang meliputi namun tidak terbatas pada putusan pengadilan, yurisprudensi, monografi hukum, artikel majalah hukum, buku hukum, penelitian hukum, pengkajian hukum, naskah akademis, dan rancangan peraturan perundang-undangan.
3. Informasi Hukum adalah semua data dan keterangan yang dimuat dalam Dokumen Hukum.
4. Pengelolaan Dokumentasi dan Informasi Hukum adalah kegiatan pengumpulan, pengolahan, penyimpanan, pelestarian, dan pendayagunaan informasi Dokumen Hukum.
5. Pusat Jaringan Dokumentasi dan Informasi Hukum Nasional yang selanjutnya disebut Pusat JDIHN adalah pusat jaringan yang bertugas melakukan pembinaan, pengembangan, dan monitoring kepada anggota jaringan dokumentasi dan Informasi Hukum nasional.
6. Pusat Jaringan Dokumentasi dan Informasi Hukum yang selanjutnya disebut Pusat JDIH adalah pusat jaringan dokumentasi dan Informasi Hukum di lingkungan Badan Nasional Penanggulangan Bencana.
7. Anggota Jaringan Dokumentasi dan Informasi Hukum yang selanjutnya disebut Anggota JDIH adalah anggota jaringan dokumentasi dan Informasi Hukum di lingkungan Badan Nasional Penanggulangan Bencana.
8. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintahan nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5363, 'perban-8-2025', 5, 'pasal', 'Pasal 2', 'BAB II ORGANISASI JARINGAN DOKUMENTASI DAN INFORMASI HUKUM BADAN NASIONAL PENANGGULANGAN BENCANA', 3, '(1) Organisasi JDIH BNPB terdiri atas :
a. Pusat JDIH; dan
b. Anggota JDIH.
(2) Pusat JDIH sebagaimana dimaksud pada ayat (1) huruf a yaitu unit kerja yang mempunyai fungsi penyiapan koordinasi penyusunan peraturan perundang-undangan dan bahan advokasi hukum di bidang penanggulangan bencana.
(3) Anggota JDIH sebagaimana dimaksud pada ayat (1) huruf b terdiri atas:
a. unit organisasi jabatan pimpinan tinggi madya; dan
b. unit organisasi jabatan pimpinan tinggi pratama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5363, '(1) Organisasi JDIH BNPB terdiri atas :
a. Pusat JDIH; dan
b. Anggota JDIH.
(2) Pusat JDIH sebagaimana dimaksud pada ayat (1) huruf a yaitu unit kerja yang mempunyai fungsi penyiapan koordinasi penyusunan peraturan perundang-undangan dan bahan advokasi hukum di bidang penanggulangan bencana.
(3) Anggota JDIH sebagaimana dimaksud pada ayat (1) huruf b terdiri atas:
a. unit organisasi jabatan pimpinan tinggi madya; dan
b. unit organisasi jabatan pimpinan tinggi pratama.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5364, 'perban-8-2025', 6, 'pasal', 'Pasal 3', 'BAB II ORGANISASI JARINGAN DOKUMENTASI DAN INFORMASI HUKUM BADAN NASIONAL PENANGGULANGAN BENCANA', 3, 'Pusat JDIH sebagaimana dimaksud dalam Pasal 2 ayat (1) huruf a mempunyai tugas melakukan pengelolaan dokumentasi dan Informasi Hukum serta melakukan pembinaan, pengembangan, pemantauan, dan evaluasi kepada Anggota JDIH.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5364, 'Pusat JDIH sebagaimana dimaksud dalam Pasal 2 ayat (1) huruf a mempunyai tugas melakukan pengelolaan dokumentasi dan Informasi Hukum serta melakukan pembinaan, pengembangan, pemantauan, dan evaluasi kepada Anggota JDIH.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5365, 'perban-8-2025', 7, 'pasal', 'Pasal 4', 'BAB II ORGANISASI JARINGAN DOKUMENTASI DAN INFORMASI HUKUM BADAN NASIONAL PENANGGULANGAN BENCANA', 3, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 3, Pusat JDIH menyelenggarakan fungsi:
a. pengumpulan, pengolahan, penyimpanan, pelestarian, dan pendayagunaan informasi Dokumen Hukum dan Informasi Hukum yang diterbitkan oleh BNPB;
b. pembangunan sistem Informasi Hukum berbasis teknologi informasi dan komunikasi yang dapat diintegrasikan dengan laman Pusat JDIHN;
c. pengembangan sistem Informasi Hukum berbasis teknologi informasi dan komunikasi;
d. pemberian konsultasi terhadap permasalahan yang dihadapi oleh Anggota JDIH;
e. pembinaan dan pengembangan sumber daya manusia pengelolaan JDIH BNPB;
f. sosialisasi kebijakan dan pengelolaan teknis dokumentasi dan Informasi Hukum kepada Anggota JDIH;
g. penyediaan sarana dan prasarana pengelolaan di Pusat JDIH;
h. pelaksanaan pemantauan dan evaluasi mengenai Pengelolaan Dokumentasi dan Informasi Hukum di BNPB; dan
i. penyampaian laporan pelaksanaan JDIH BNPB kepada Kepala BNPB melalui Sekretaris Utama BNPB dan kepada Pusat JDIHN secara periodik 1 (satu) kali dalam setahun pada akhir tahun anggaran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5365, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 3, Pusat JDIH menyelenggarakan fungsi:
a. pengumpulan, pengolahan, penyimpanan, pelestarian, dan pendayagunaan informasi Dokumen Hukum dan Informasi Hukum yang diterbitkan oleh BNPB;
b. pembangunan sistem Informasi Hukum berbasis teknologi informasi dan komunikasi yang dapat diintegrasikan dengan laman Pusat JDIHN;
c. pengembangan sistem Informasi Hukum berbasis teknologi informasi dan komunikasi;
d. pemberian konsultasi terhadap permasalahan yang dihadapi oleh Anggota JDIH;
e. pembinaan dan pengembangan sumber daya manusia pengelolaan JDIH BNPB;
f. sosialisasi kebijakan dan pengelolaan teknis dokumentasi dan Informasi Hukum kepada Anggota JDIH;
g. penyediaan sarana dan prasarana pengelolaan di Pusat JDIH;
h. pelaksanaan pemantauan dan evaluasi mengenai Pengelolaan Dokumentasi dan Informasi Hukum di BNPB; dan
i. penyampaian laporan pelaksanaan JDIH BNPB kepada Kepala BNPB melalui Sekretaris Utama BNPB dan kepada Pusat JDIHN secara periodik 1 (satu) kali dalam setahun pada akhir tahun anggaran.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5366, 'perban-8-2025', 8, 'pasal', 'Pasal 5', 'BAB II ORGANISASI JARINGAN DOKUMENTASI DAN INFORMASI HUKUM BADAN NASIONAL PENANGGULANGAN BENCANA', 4, 'Anggota JDIH sebagaimana dimaksud dalam Pasal 4 ayat (1) huruf b, mempunyai tugas mendukung Pengelolaan Dokumentasi dan Informasi Hukum.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5366, 'Anggota JDIH sebagaimana dimaksud dalam Pasal 4 ayat (1) huruf b, mempunyai tugas mendukung Pengelolaan Dokumentasi dan Informasi Hukum.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5367, 'perban-8-2025', 9, 'pasal', 'Pasal 6', 'BAB III PENGELOLAAN DOKUMENTASI DAN INFORMASI HUKUM', 4, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 5, Anggota JDIH mempunyai fungsi:
a. pengumpulan, pengolahan, penyimpanan, pelestarian, dan pendayagunaan informasi Dokumen Hukum dan Informasi Hukum di lingkungan unit kerja masing-masing;
b. pemanfaatan sistem Informasi Hukum yang terpusat pada Pusat JDIH;
c. penyedia sarana dan prasarana Pengelolaan Dokumen dan Informasi Hukum di unit kerja masing-masing;
d. pelaksanaan pemantauan dan evaluasi berkaitan dengan Pengelolaan Dokumentasi dan Informasi Hukum di unit kerja masing-masing; dan
e. penyampaian laporan pelaksanaan fungsi sebagaimana dimaksud pada huruf a sampai dengan huruf d kepada Pusat JDIH paling sedikit 2 (dua) kali dalam 1 (satu) tahun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5367, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 5, Anggota JDIH mempunyai fungsi:
a. pengumpulan, pengolahan, penyimpanan, pelestarian, dan pendayagunaan informasi Dokumen Hukum dan Informasi Hukum di lingkungan unit kerja masing-masing;
b. pemanfaatan sistem Informasi Hukum yang terpusat pada Pusat JDIH;
c. penyedia sarana dan prasarana Pengelolaan Dokumen dan Informasi Hukum di unit kerja masing-masing;
d. pelaksanaan pemantauan dan evaluasi berkaitan dengan Pengelolaan Dokumentasi dan Informasi Hukum di unit kerja masing-masing; dan
e. penyampaian laporan pelaksanaan fungsi sebagaimana dimaksud pada huruf a sampai dengan huruf d kepada Pusat JDIH paling sedikit 2 (dua) kali dalam 1 (satu) tahun.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5368, 'perban-8-2025', 10, 'pasal', 'Pasal 7', 'BAB III PENGELOLAAN DOKUMENTASI DAN INFORMASI HUKUM', 4, '(1) Dokumen Hukum yang dikelola dalam JDIH BNPB, terdiri atas:
a. Undang-Undang;
b. Peraturan Pemerintah Pengganti Undang-Undang;
c. Peraturan Pemerintah;
d. Peraturan Presiden;
e. Peraturan BNPB;
f. keputusan yang berkaitan dengan tugas dan fungsi BNPB;
g. peraturan kebijakan yang berkaitan dengan tugas dan fungsi BNPB;
h. nota kesepahaman/kesepakatan bersama dan perjanjian kerja sama; dan
i. putusan Mahkamah Konstitusi, putusan Mahkamah Agung, dan putusan peradilan lainnya.
(2) Selain Dokumen Hukum sebagaimana dimaksud pada ayat (1), JDIH BNPB juga mengelola:
a. naskah akademik;
b. naskah urgensi;
c. monografi hukum;
d. rancangan peraturan perundang-undangan dan/atau rancangan keputusan yang berkaitan dengan tugas dan fungsi BNPB;
e. peraturan perundang-undangan yang telah diterjemahkan ke dalam bahasa Inggris sesuai dengan ketentuan peraturan perundang-undangan;
f. kajian hukum;
g. dokumen langka;
h. artikel hukum; dan/atau
i. bahan dokumentasi dan Informasi Hukum lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5368, '(1) Dokumen Hukum yang dikelola dalam JDIH BNPB, terdiri atas:
a. Undang-Undang;
b. Peraturan Pemerintah Pengganti Undang-Undang;
c. Peraturan Pemerintah;
d. Peraturan Presiden;
e. Peraturan BNPB;
f. keputusan yang berkaitan dengan tugas dan fungsi BNPB;
g. peraturan kebijakan yang berkaitan dengan tugas dan fungsi BNPB;
h. nota kesepahaman/kesepakatan bersama dan perjanjian kerja sama; dan
i. putusan Mahkamah Konstitusi, putusan Mahkamah Agung, dan putusan peradilan lainnya.
(2) Selain Dokumen Hukum sebagaimana dimaksud pada ayat (1), JDIH BNPB juga mengelola:
a. naskah akademik;
b. naskah urgensi;
c. monografi hukum;
d. rancangan peraturan perundang-undangan dan/atau rancangan keputusan yang berkaitan dengan tugas dan fungsi BNPB;
e. peraturan perundang-undangan yang telah diterjemahkan ke dalam bahasa Inggris sesuai dengan ketentuan peraturan perundang-undangan;
f. kajian hukum;
g. dokumen langka;
h. artikel hukum; dan/atau
i. bahan dokumentasi dan Informasi Hukum lainnya.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5369, 'perban-8-2025', 11, 'pasal', 'Pasal 8', 'BAB III PENGELOLAAN DOKUMENTASI DAN INFORMASI HUKUM', 5, 'Pengelolaan Dokumentasi dan Informasi Hukum di lingkungan BNPB dilakukan melalui:
a. aplikasi JDIH BNPB; dan
b. arsip manual.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5369, 'Pengelolaan Dokumentasi dan Informasi Hukum di lingkungan BNPB dilakukan melalui:
a. aplikasi JDIH BNPB; dan
b. arsip manual.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5370, 'perban-8-2025', 12, 'pasal', 'Pasal 9', 'BAB III PENGELOLAAN DOKUMENTASI DAN INFORMASI HUKUM', 5, '(1) Dalam Pengelolaan Dokumentasi dan Informasi Hukum melalui aplikasi JDIH BNPB sebagaimana dimaksud dalam Pasal 8 huruf a, Anggota JDIH menyampaikan Dokumen Hukum dan Informasi Hukum yang ditetapkan oleh Anggota JDIH kepada Pusat JDIH paling lambat 15 (lima belas) hari kerja sejak diterbitkan.
(2) Pusat JDIH menyampaikan Dokumen Hukum dan Informasi Hukum sebagaimana dimaksud pada ayat (1) melalui laman JDIH BNPB.
(3) Dokumen Hukum dan Informasi Hukum sebagaimana dimaksud pada ayat (1) disampaikan dalam bentuk salinan cetak dan/atau salinan digital.
(4) Laman JDIH BNPB sebagaimana dimaksud pada ayat
(2) terintegrasi dengan:
a. laman BNPB; dan
b. laman Pusat JDIHN.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5370, '(1) Dalam Pengelolaan Dokumentasi dan Informasi Hukum melalui aplikasi JDIH BNPB sebagaimana dimaksud dalam Pasal 8 huruf a, Anggota JDIH menyampaikan Dokumen Hukum dan Informasi Hukum yang ditetapkan oleh Anggota JDIH kepada Pusat JDIH paling lambat 15 (lima belas) hari kerja sejak diterbitkan.
(2) Pusat JDIH menyampaikan Dokumen Hukum dan Informasi Hukum sebagaimana dimaksud pada ayat (1) melalui laman JDIH BNPB.
(3) Dokumen Hukum dan Informasi Hukum sebagaimana dimaksud pada ayat (1) disampaikan dalam bentuk salinan cetak dan/atau salinan digital.
(4) Laman JDIH BNPB sebagaimana dimaksud pada ayat
(2) terintegrasi dengan:
a. laman BNPB; dan
b. laman Pusat JDIHN.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5371, 'perban-8-2025', 13, 'pasal', 'Pasal 10', 'BAB III PENGELOLAAN DOKUMENTASI DAN INFORMASI HUKUM', 5, 'Pengelolaan Dokumentasi dan Informasi Hukum melalui arsip manual sebagaimana dimaksud dalam Pasal 8 huruf b dilakukan dengan cara inventarisasi Dokumen Hukum dan Informasi Hukum untuk diarsip dan dikelola oleh Pusat JDIH dan Anggota JDIH.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5371, 'Pengelolaan Dokumentasi dan Informasi Hukum melalui arsip manual sebagaimana dimaksud dalam Pasal 8 huruf b dilakukan dengan cara inventarisasi Dokumen Hukum dan Informasi Hukum untuk diarsip dan dikelola oleh Pusat JDIH dan Anggota JDIH.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5372, 'perban-8-2025', 14, 'pasal', 'Pasal 11', 'BAB III PENGELOLAAN DOKUMENTASI DAN INFORMASI HUKUM', 5, '(1) Kepala BNPB membentuk tim teknis pengelola JDIH BNPB untuk mendukung Pengelolaan Dokumentasi dan Informasi Hukum bagi organisasi JDIH BNPB.
(2) Keanggotaan tim teknis pengelola JDIH BNPB sebagaimana dimaksud pada ayat (1) terdiri atas unsur:
a. Pusat JDIH BNPB;
b. Anggota JDIH BNPB; dan
c. unit kerja yang melaksanakan koordinasi dan pelayanan di bidang pengelolaan data dan informasi di lingkungan BNPB.
(3) Keanggotaan tim teknis pengelola JDIH BNPB sebagaimana dimaksud pada ayat (2) ditetapkan oleh Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5372, '(1) Kepala BNPB membentuk tim teknis pengelola JDIH BNPB untuk mendukung Pengelolaan Dokumentasi dan Informasi Hukum bagi organisasi JDIH BNPB.
(2) Keanggotaan tim teknis pengelola JDIH BNPB sebagaimana dimaksud pada ayat (1) terdiri atas unsur:
a. Pusat JDIH BNPB;
b. Anggota JDIH BNPB; dan
c. unit kerja yang melaksanakan koordinasi dan pelayanan di bidang pengelolaan data dan informasi di lingkungan BNPB.
(3) Keanggotaan tim teknis pengelola JDIH BNPB sebagaimana dimaksud pada ayat (2) ditetapkan oleh Kepala BNPB.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5373, 'perban-8-2025', 15, 'pasal', 'Pasal 12', 'BAB IV PEMANTAUAN DAN EVALUASI', 6, 'Pengelolaan Dokumentasi dan Informasi Hukum dilakukan sesuai dengan ketentuan peraturan perundang-undangan di bidang standar Pengelolaan Dokumentasi dan Informasi Hukum.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5373, 'Pengelolaan Dokumentasi dan Informasi Hukum dilakukan sesuai dengan ketentuan peraturan perundang-undangan di bidang standar Pengelolaan Dokumentasi dan Informasi Hukum.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5374, 'perban-8-2025', 16, 'pasal', 'Pasal 13', 'BAB V PENDANAAN', 6, '(1) Pusat JDIH melaksanakan pemantauan dan evaluasi sebagaimana dimaksud dalam Pasal 4 huruf h terhadap Pengelolaan Dokumentasi dan Informasi Hukum di lingkungan BNPB.
(2) Dalam rangka pelaksanaan pemantauan dan evaluasi sebagaimana dimaksud pada ayat (1), Pusat JDIH BNPB dan Anggota JDIH BNPB, melakukan pertemuan secara berkala setiap 6 (enam) bulan.
(3) Pemantauan dan evaluasi sebagaimana dimaksud pada ayat (1) dilaksanakan paling sedikit 1 (satu) tahun sekali.
(4) Hasil pemantauan dan evaluasi sebagaimana dimaksud pada ayat (1) disampaikan kepada Kepala BNPB melalui Sekretaris Utama BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5374, '(1) Pusat JDIH melaksanakan pemantauan dan evaluasi sebagaimana dimaksud dalam Pasal 4 huruf h terhadap Pengelolaan Dokumentasi dan Informasi Hukum di lingkungan BNPB.
(2) Dalam rangka pelaksanaan pemantauan dan evaluasi sebagaimana dimaksud pada ayat (1), Pusat JDIH BNPB dan Anggota JDIH BNPB, melakukan pertemuan secara berkala setiap 6 (enam) bulan.
(3) Pemantauan dan evaluasi sebagaimana dimaksud pada ayat (1) dilaksanakan paling sedikit 1 (satu) tahun sekali.
(4) Hasil pemantauan dan evaluasi sebagaimana dimaksud pada ayat (1) disampaikan kepada Kepala BNPB melalui Sekretaris Utama BNPB.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5375, 'perban-8-2025', 17, 'pasal', 'Pasal 14', 'BAB VI KETENTUAN PENUTUP', 6, 'Pendanaan pelaksanaan pengelolaan JDIH BNPB bersumber dari:
a. Anggaran Pendapatan dan Belanja Negara BNPB; dan
b. sumber lainnya yang sah sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5375, 'Pendanaan pelaksanaan pengelolaan JDIH BNPB bersumber dari:
a. Anggaran Pendapatan dan Belanja Negara BNPB; dan
b. sumber lainnya yang sah sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5376, 'perban-8-2025', 18, 'pasal', 'Pasal 15', 'BAB VI KETENTUAN PENUTUP', 6, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5376, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5377, 'perban-8-2025', 19, 'lain', 'Penutup', NULL, 7, 'Ditetapkan di Jakarta pada tanggal 03 November 2025 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2025 NOMOR Ж');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5377, 'Ditetapkan di Jakarta pada tanggal 03 November 2025 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2025 NOMOR Ж', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2025 tentang Jaringan Dokumentasi dan Informasi Hukum');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5378, 'perban-9-2025', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5378, 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah', 'Judul', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5379, 'perban-9-2025', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk meningkatkan ketangguhan pemerintah daerah dalam menghadapi bencana, serta mengurangi dampak bencana perlu pelaksanaan kesiapsiagaan penanggulangan bencana di daerah yang memiliki potensi ancaman bencana;
b. bahwa pelaksanaan kesiapsiagaan penanggulangan bencana daerah sebagaimana dimaksud dalam huruf a, diperlukan penyusunan dan uji coba rencana penanggulangan kedaruratan bencana daerah secara terpadu dan terkoordinasi;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5379, 'a. bahwa untuk meningkatkan ketangguhan pemerintah daerah dalam menghadapi bencana, serta mengurangi dampak bencana perlu pelaksanaan kesiapsiagaan penanggulangan bencana di daerah yang memiliki potensi ancaman bencana;
b. bahwa pelaksanaan kesiapsiagaan penanggulangan bencana daerah sebagaimana dimaksud dalam huruf a, diperlukan penyusunan dan uji coba rencana penanggulangan kedaruratan bencana daerah secara terpadu dan terkoordinasi;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Badan Nasional Penanggulangan Bencana tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah;', 'Menimbang', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5380, 'perban-9-2025', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
3. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 769);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5380, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
3. Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2019 Nomor 1) sebagaimana telah diubah dengan Peraturan Presiden Nomor 29 Tahun 2021 tentang Perubahan atas Peraturan Presiden Nomor 1 Tahun 2019 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2021 Nomor 103);
4. Peraturan Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2025 Nomor 769);', 'Mengingat', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5381, 'perban-9-2025', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENYUSUNAN DAN UJI COBA RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5381, 'Menetapkan : PERATURAN BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENYUSUNAN DAN UJI COBA RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH.', 'Menetapkan', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5382, 'perban-9-2025', 4, 'pasal', 'Pasal 1', 'BAB II MAKSUD DAN TUJUAN', 2, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Rencana Penanggulangan Kedaruratan Bencana Daerah yang selanjutnya disingkat RPKB Daerah adalah dokumen yang berisi kebijakan, strategi dan pembagian tugas dan tanggung jawab antar instansi/lembaga dalam penyelenggaraan penanggulangan kedaruratan bencana di tingkat provinsi atau kabupaten/kota dalam mewujudkan tata kelola penanggulangan kedaruratan bencana yang ditetapkan oleh pemerintah daerah.
2. Kajian Risiko Bencana yang selanjutnya disingkat KRB adalah pendekatan untuk memperlihatkan potensi dampak negatif yang mungkin timbul akibat suatu kejadian bencana.
3. Gladi Ruang adalah latihan berbentuk diskusi yang bertujuan untuk meningkatkan pemahaman, mencari solusi terhadap permasalahan, menghimpun masukan, membangun kesepakatan dan/atau memvalidasi berbagai kebijakan, prosedur dan rencana yang ada.
4. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintahan nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
5. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5382, 'Dalam Peraturan Badan ini yang dimaksud dengan:
1. Rencana Penanggulangan Kedaruratan Bencana Daerah yang selanjutnya disingkat RPKB Daerah adalah dokumen yang berisi kebijakan, strategi dan pembagian tugas dan tanggung jawab antar instansi/lembaga dalam penyelenggaraan penanggulangan kedaruratan bencana di tingkat provinsi atau kabupaten/kota dalam mewujudkan tata kelola penanggulangan kedaruratan bencana yang ditetapkan oleh pemerintah daerah.
2. Kajian Risiko Bencana yang selanjutnya disingkat KRB adalah pendekatan untuk memperlihatkan potensi dampak negatif yang mungkin timbul akibat suatu kejadian bencana.
3. Gladi Ruang adalah latihan berbentuk diskusi yang bertujuan untuk meningkatkan pemahaman, mencari solusi terhadap permasalahan, menghimpun masukan, membangun kesepakatan dan/atau memvalidasi berbagai kebijakan, prosedur dan rencana yang ada.
4. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintahan nonkementerian sebagaimana dimaksud dalam undang-undang tentang penanggulangan bencana.
5. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.', 'Pasal 1', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5383, 'perban-9-2025', 5, 'pasal', 'Pasal 2', 'BAB III KEDUDUKAN DAN CAKUPAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 2, '(1) Peraturan Badan ini dimaksudkan sebagai dasar dalam penyusunan dan uji coba RPKB Daerah.
(2) Peraturan Badan ini bertujuan untuk memberikan pedoman dalam penyusunan dan uji coba RPKB Daerah yang sistematis dan pelibatan pihak terkait di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5383, '(1) Peraturan Badan ini dimaksudkan sebagai dasar dalam penyusunan dan uji coba RPKB Daerah.
(2) Peraturan Badan ini bertujuan untuk memberikan pedoman dalam penyusunan dan uji coba RPKB Daerah yang sistematis dan pelibatan pihak terkait di daerah.', 'Pasal 2', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5384, 'perban-9-2025', 6, 'pasal', 'Pasal 3', 'BAB III KEDUDUKAN DAN CAKUPAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 3, '(1) RPKB Daerah menjadi acuan untuk:
a. penyelenggaraan penanggulangan kedaruratan bencana di daerah;
b. penyusunan rencana kontingensi; dan
c. penyusunan rencana operasi.
(2) RPKB Daerah disusun dengan mengacu pada:
a. KRB; dan
b. struktur organisasi tata kelola, tugas dan fungsi perangkat daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5384, '(1) RPKB Daerah menjadi acuan untuk:
a. penyelenggaraan penanggulangan kedaruratan bencana di daerah;
b. penyusunan rencana kontingensi; dan
c. penyusunan rencana operasi.
(2) RPKB Daerah disusun dengan mengacu pada:
a. KRB; dan
b. struktur organisasi tata kelola, tugas dan fungsi perangkat daerah.', 'Pasal 3', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5385, 'perban-9-2025', 7, 'pasal', 'Pasal 4', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 3, '(1) RPKB Daerah mencakup:
a. pembagian tugas dan tanggung jawab;
b. identifikasi sumber daya; dan
c. mekanisme komando penanganan darurat bencana.
(2) Pembagian tugas dan tanggung jawab sebagaimana dimaksud pada ayat (1) huruf a dengan menentukan perangkat yang terlibat dalam penanggulangan kedaruratan bencana.
(3) Identifikasi sumber daya sebagaimana dimaksud pada ayat (1) huruf b merupakan proses pendataan ketersediaan sumber daya yang digunakan saat penanggulangan kedaruratan bencana.
(4) Mekanisme komando penanganan darurat bencana sebagaimana dimaksud pada ayat (1) huruf c dilaksanakan sesuai ketentuan peraturan perundang-undangan mengenai sistem komando penanganan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5385, '(1) RPKB Daerah mencakup:
a. pembagian tugas dan tanggung jawab;
b. identifikasi sumber daya; dan
c. mekanisme komando penanganan darurat bencana.
(2) Pembagian tugas dan tanggung jawab sebagaimana dimaksud pada ayat (1) huruf a dengan menentukan perangkat yang terlibat dalam penanggulangan kedaruratan bencana.
(3) Identifikasi sumber daya sebagaimana dimaksud pada ayat (1) huruf b merupakan proses pendataan ketersediaan sumber daya yang digunakan saat penanggulangan kedaruratan bencana.
(4) Mekanisme komando penanganan darurat bencana sebagaimana dimaksud pada ayat (1) huruf c dilaksanakan sesuai ketentuan peraturan perundang-undangan mengenai sistem komando penanganan darurat bencana.', 'Pasal 4', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5386, 'perban-9-2025', 8, 'pasal', 'Pasal 5', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 3, '(1) RPKB Daerah disusun oleh pemerintah daerah sesuai kewenangannya.
(2) Penyusunan RPKB Daerah sebagaimana dimaksud pada ayat (1) dikoordinasikan oleh BPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5386, '(1) RPKB Daerah disusun oleh pemerintah daerah sesuai kewenangannya.
(2) Penyusunan RPKB Daerah sebagaimana dimaksud pada ayat (1) dikoordinasikan oleh BPBD.', 'Pasal 5', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5387, 'perban-9-2025', 9, 'pasal', 'Pasal 6', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 3, 'Penyusunan RPKB Daerah dilaksanakan sesuai dengan tahapan:
a. persiapan;
b. pelaksanaan; dan
c. finalisasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5387, 'Penyusunan RPKB Daerah dilaksanakan sesuai dengan tahapan:
a. persiapan;
b. pelaksanaan; dan
c. finalisasi.', 'Pasal 6', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5388, 'perban-9-2025', 10, 'pasal', 'Pasal 7', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 4, 'Persiapan sebagaimana dimaksud dalam Pasal 6 huruf a, meliputi:
a. penyusunan kerangka acuan kerja;
b. identifikasi para pihak;
c. pembentukan tim penyusun; dan
d. pengumpulan data.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5388, 'Persiapan sebagaimana dimaksud dalam Pasal 6 huruf a, meliputi:
a. penyusunan kerangka acuan kerja;
b. identifikasi para pihak;
c. pembentukan tim penyusun; dan
d. pengumpulan data.', 'Pasal 7', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5389, 'perban-9-2025', 11, 'pasal', 'Pasal 8', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 4, '(1) Penyusunan kerangka acuan kerja sebagaimana dimaksud dalam Pasal 7 huruf a paling sedikit memuat:
a. latar belakang;
b. maksud dan tujuan;
c. metode;
d. tahapan kegiatan dan waktu pelaksanaan; dan
e. pendanaan.
(2) Kerangka acuan kerja sebagaimana dimaksud pada ayat (1) disusun oleh BPBD dan dapat berkoordinasi dengan perangkat daerah lainnya.
(3) BPBD sebagaimana dimaksud pada ayat (2) dapat melaksanakan konsultasi awal kerangka acuan kerja.
(4) Konsultasi awal sebagaimana dimaksud pada ayat (3) dilaksanakan oleh:
a. pemerintah provinsi kepada unit kerja BNPB yang menyelenggarakan fungsi penyiapan penyusunan dan uji coba RPKB Daerah; dan
b. pemerintah kabupaten/kota kepada pemerintah provinsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5389, '(1) Penyusunan kerangka acuan kerja sebagaimana dimaksud dalam Pasal 7 huruf a paling sedikit memuat:
a. latar belakang;
b. maksud dan tujuan;
c. metode;
d. tahapan kegiatan dan waktu pelaksanaan; dan
e. pendanaan.
(2) Kerangka acuan kerja sebagaimana dimaksud pada ayat (1) disusun oleh BPBD dan dapat berkoordinasi dengan perangkat daerah lainnya.
(3) BPBD sebagaimana dimaksud pada ayat (2) dapat melaksanakan konsultasi awal kerangka acuan kerja.
(4) Konsultasi awal sebagaimana dimaksud pada ayat (3) dilaksanakan oleh:
a. pemerintah provinsi kepada unit kerja BNPB yang menyelenggarakan fungsi penyiapan penyusunan dan uji coba RPKB Daerah; dan
b. pemerintah kabupaten/kota kepada pemerintah provinsi.', 'Pasal 8', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5390, 'perban-9-2025', 12, 'pasal', 'Pasal 9', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 4, '(1) Identifikasi para pihak sebagaimana dimaksud dalam Pasal 7 huruf b dilakukan untuk menentukan pihak yang terlibat dalam proses penyusunan RPKB Daerah.
(2) Pihak sebagaimana dimaksud pada ayat (1) terdiri atas:
a. pelaksana; dan
b. pendukung.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5390, '(1) Identifikasi para pihak sebagaimana dimaksud dalam Pasal 7 huruf b dilakukan untuk menentukan pihak yang terlibat dalam proses penyusunan RPKB Daerah.
(2) Pihak sebagaimana dimaksud pada ayat (1) terdiri atas:
a. pelaksana; dan
b. pendukung.', 'Pasal 9', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5391, 'perban-9-2025', 13, 'pasal', 'Pasal 10', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 4, '(1) Pelaksana sebagaimana dimaksud dalam Pasal 9 pada ayat (2) huruf a terdiri atas:
a. tim penyusun; dan
b. sekretariat.
(2) Tim penyusun sebagaimana dimaksud pada ayat (1) huruf a, terdiri atas:
a. tim perumus; dan
b. tim penulis.
(3) Tim penyusun sebagaimana dimaksud pada ayat (2) ditetapkan melalui keputusan kepala daerah.
(4) Sekretariat sebagaimana dimaksud pada ayat (1) huruf b berasal dari BPBD.
(5) Tim perumus sebagaimana dimaksud pada ayat (2) huruf a terdiri atas perangkat daerah sesuai kewenangannya.
(6) Tim penulis sebagaimana dimaksud pada ayat (2) huruf b merupakan BPBD dan dapat dibantu oleh:
a. perangkat daerah;
b. akademisi; dan/atau
c. organisasi nonpemerintah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5391, '(1) Pelaksana sebagaimana dimaksud dalam Pasal 9 pada ayat (2) huruf a terdiri atas:
a. tim penyusun; dan
b. sekretariat.
(2) Tim penyusun sebagaimana dimaksud pada ayat (1) huruf a, terdiri atas:
a. tim perumus; dan
b. tim penulis.
(3) Tim penyusun sebagaimana dimaksud pada ayat (2) ditetapkan melalui keputusan kepala daerah.
(4) Sekretariat sebagaimana dimaksud pada ayat (1) huruf b berasal dari BPBD.
(5) Tim perumus sebagaimana dimaksud pada ayat (2) huruf a terdiri atas perangkat daerah sesuai kewenangannya.
(6) Tim penulis sebagaimana dimaksud pada ayat (2) huruf b merupakan BPBD dan dapat dibantu oleh:
a. perangkat daerah;
b. akademisi; dan/atau
c. organisasi nonpemerintah.', 'Pasal 10', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5392, 'perban-9-2025', 14, 'pasal', 'Pasal 11', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 5, 'Pendukung sebagaimana dimaksud dalam Pasal 9 ayat (2) huruf b merupakan lembaga atau perorangan yang memiliki kompetensi dan/atau kapasitas dalam penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5392, 'Pendukung sebagaimana dimaksud dalam Pasal 9 ayat (2) huruf b merupakan lembaga atau perorangan yang memiliki kompetensi dan/atau kapasitas dalam penanggulangan bencana.', 'Pasal 11', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5393, 'perban-9-2025', 15, 'pasal', 'Pasal 12', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 5, 'Pengumpulan data sebagaimana dimaksud dalam Pasal 7 huruf d merupakan kegiatan untuk mengumpulkan data sumber daya yang dibutuhkan dalam penanggulangan kedaruratan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5393, 'Pengumpulan data sebagaimana dimaksud dalam Pasal 7 huruf d merupakan kegiatan untuk mengumpulkan data sumber daya yang dibutuhkan dalam penanggulangan kedaruratan bencana.', 'Pasal 12', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5394, 'perban-9-2025', 16, 'pasal', 'Pasal 13', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 5, '(1) Pelaksanaan sebagaimana dimaksud dalam Pasal 6 huruf b, meliputi:
a. penentuan karakteristik ancaman bencana;
b. penyusunan kerangka penanggulangan kedaruratan bencana; dan
c. penulisan RPKB Daerah.
(2) Penentuan karakteristik ancaman bencana sebagaimana dimaksud pada ayat (1) huruf a dilakukan dengan memperhatikan jenis ancaman bencana berdasarkan hasil KRB.
(3) Penyusunan kerangka penanggulangan kedaruratan bencana sebagaimana dimaksud pada ayat (1) huruf b sesuai substansi RPKB Daerah.
(4) Penulisan RPKB Daerah sebagaimana dimaksud pada ayat (1) huruf c dilaksanakan sesuai panduan penyusunan RPKB Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5394, '(1) Pelaksanaan sebagaimana dimaksud dalam Pasal 6 huruf b, meliputi:
a. penentuan karakteristik ancaman bencana;
b. penyusunan kerangka penanggulangan kedaruratan bencana; dan
c. penulisan RPKB Daerah.
(2) Penentuan karakteristik ancaman bencana sebagaimana dimaksud pada ayat (1) huruf a dilakukan dengan memperhatikan jenis ancaman bencana berdasarkan hasil KRB.
(3) Penyusunan kerangka penanggulangan kedaruratan bencana sebagaimana dimaksud pada ayat (1) huruf b sesuai substansi RPKB Daerah.
(4) Penulisan RPKB Daerah sebagaimana dimaksud pada ayat (1) huruf c dilaksanakan sesuai panduan penyusunan RPKB Daerah.', 'Pasal 13', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5395, 'perban-9-2025', 17, 'pasal', 'Pasal 14', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 5, '(1) Finalisasi sebagaimana dimaksud dalam Pasal 6 huruf c dilaksanakan melalui tahapan:
a. asistensi;
b. konsultasi publik;
c. penyempurnaan rancangan RPKB Daerah; dan
d. penetapan.
(2) Asistensi sebagaimana dimaksud pada ayat (1) huruf a dilaksanakan untuk memastikan keselarasan substansi dan sistematika rancangan RPKB Daerah.
(3) Asistensi sebagaimana dimaksud pada ayat (2) dilaksanakan oleh:
a. unit kerja BNPB yang menyelenggarakan fungsi penyiapan penyusunan dan uji coba RPKB Daerah kepada pemerintah provinsi; dan
b. pemerintah provinsi kepada pemerintah kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5395, '(1) Finalisasi sebagaimana dimaksud dalam Pasal 6 huruf c dilaksanakan melalui tahapan:
a. asistensi;
b. konsultasi publik;
c. penyempurnaan rancangan RPKB Daerah; dan
d. penetapan.
(2) Asistensi sebagaimana dimaksud pada ayat (1) huruf a dilaksanakan untuk memastikan keselarasan substansi dan sistematika rancangan RPKB Daerah.
(3) Asistensi sebagaimana dimaksud pada ayat (2) dilaksanakan oleh:
a. unit kerja BNPB yang menyelenggarakan fungsi penyiapan penyusunan dan uji coba RPKB Daerah kepada pemerintah provinsi; dan
b. pemerintah provinsi kepada pemerintah kabupaten/kota.', 'Pasal 14', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5396, 'perban-9-2025', 18, 'pasal', 'Pasal 15', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 5, '(1) Konsultasi publik sebagaimana dimaksud dalam Pasal 14 ayat (1) huruf b merupakan kegiatan menghimpun masukan atas rancangan RPKB Daerah dari:
a. kementerian/lembaga;
b. perangkat daerah;
c. organisasi masyarakat;
d. perguruan tinggi;
e. media massa;
f. lembaga usaha; dan/atau
g. masyarakat.
(2) Konsultasi publik sebagaimana dimaksud pada ayat (1) dilaksanakan oleh BPBD dan berkoordinasi dengan bagian hukum pemerintah daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5396, '(1) Konsultasi publik sebagaimana dimaksud dalam Pasal 14 ayat (1) huruf b merupakan kegiatan menghimpun masukan atas rancangan RPKB Daerah dari:
a. kementerian/lembaga;
b. perangkat daerah;
c. organisasi masyarakat;
d. perguruan tinggi;
e. media massa;
f. lembaga usaha; dan/atau
g. masyarakat.
(2) Konsultasi publik sebagaimana dimaksud pada ayat (1) dilaksanakan oleh BPBD dan berkoordinasi dengan bagian hukum pemerintah daerah.', 'Pasal 15', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5397, 'perban-9-2025', 19, 'pasal', 'Pasal 16', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 6, 'Finalisasi pada tahap asistensi dan konsultasi publik sebagaimana dimaksud dalam Pasal 14 ayat (1) huruf a dan huruf b dapat dilengkapi dengan pelaksanaan Gladi Ruang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5397, 'Finalisasi pada tahap asistensi dan konsultasi publik sebagaimana dimaksud dalam Pasal 14 ayat (1) huruf a dan huruf b dapat dilengkapi dengan pelaksanaan Gladi Ruang.', 'Pasal 16', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5398, 'perban-9-2025', 20, 'pasal', 'Pasal 17', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 6, 'Penyempurnaan rancangan RPKB Daerah sebagaimana dimaksud dalam Pasal 14 ayat (1) huruf c merupakan kegiatan penyempurnaan substansi/materi dan sistematika rancangan RPKB Daerah berdasarkan hasil asistensi dan konsultasi publik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5398, 'Penyempurnaan rancangan RPKB Daerah sebagaimana dimaksud dalam Pasal 14 ayat (1) huruf c merupakan kegiatan penyempurnaan substansi/materi dan sistematika rancangan RPKB Daerah berdasarkan hasil asistensi dan konsultasi publik.', 'Pasal 17', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5399, 'perban-9-2025', 21, 'pasal', 'Pasal 18', 'BAB IV PENYUSUNAN RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 6, '(1) Penyempurnaan rancangan RPKB Daerah sebagaimana dimaksud dalam Pasal 17 untuk selanjutnya ditetapkan menjadi RPKB Daerah.
(2) Penetapan RPKB Daerah sebagaimana dimaksud pada ayat (1) dilaksanakan oleh kepala daerah dalam bentuk peraturan kepala daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5399, '(1) Penyempurnaan rancangan RPKB Daerah sebagaimana dimaksud dalam Pasal 17 untuk selanjutnya ditetapkan menjadi RPKB Daerah.
(2) Penetapan RPKB Daerah sebagaimana dimaksud pada ayat (1) dilaksanakan oleh kepala daerah dalam bentuk peraturan kepala daerah.', 'Pasal 18', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5400, 'perban-9-2025', 22, 'pasal', 'Pasal 19', 'BAB V MATERI DALAM RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 6, 'RPKB Daerah disusun sesuai panduan yang ditetapkan oleh kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5400, 'RPKB Daerah disusun sesuai panduan yang ditetapkan oleh kepala BNPB.', 'Pasal 19', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5401, 'perban-9-2025', 23, 'pasal', 'Pasal 20', 'BAB V MATERI DALAM RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 6, '(1) Materi RPKB Daerah meliputi:
a. karakteristik ancaman bencana; dan
b. tata kelola penanganan darurat bencana.
(2) Karakteristik ancaman bencana sebagaimana dimaksud pada ayat (1) huruf a berdasarkan jenis ancaman bencana prioritas pada dokumen KRB.
(3) Tata kelola penanganan darurat bencana sebagaimana dimaksud pada ayat (1) huruf b terdiri atas:
a. kebijakan dan strategi; dan
b. manajemen penanganan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5401, '(1) Materi RPKB Daerah meliputi:
a. karakteristik ancaman bencana; dan
b. tata kelola penanganan darurat bencana.
(2) Karakteristik ancaman bencana sebagaimana dimaksud pada ayat (1) huruf a berdasarkan jenis ancaman bencana prioritas pada dokumen KRB.
(3) Tata kelola penanganan darurat bencana sebagaimana dimaksud pada ayat (1) huruf b terdiri atas:
a. kebijakan dan strategi; dan
b. manajemen penanganan darurat bencana.', 'Pasal 20', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5402, 'perban-9-2025', 24, 'pasal', 'Pasal 21', 'BAB V MATERI DALAM RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 6, '(1) Kebijakan dan strategi sebagaimana dimaksud dalam Pasal 20 ayat (3) huruf a disusun berdasarkan kesepakatan tim perumus.
(2) Kebijakan sebagaimana dimaksud pada ayat (1) disusun untuk mendukung kegiatan penyelenggaraan penanggulangan bencana pada saat tanggap darurat bencana.
(3) Kebijakan sebagaimana dimaksud pada ayat (2) meliputi:
a. pengkajian secara cepat dan tepat terhadap lokasi, kerusakan, kerugian, dan sumber daya;
b. penentuan status keadaan darurat bencana;
c. penyelamatan dan evakuasi masyarakat terkena bencana;
d. pemenuhan kebutuhan dasar;
e. pelindungan terhadap kelompok rentan; dan
f. pemulihan dengan segera prasarana dan sarana vital.
(4) Strategi sebagaimana dimaksud pada ayat (1) disusun untuk melaksanakan kebijakan secara efektif dan terpadu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5402, '(1) Kebijakan dan strategi sebagaimana dimaksud dalam Pasal 20 ayat (3) huruf a disusun berdasarkan kesepakatan tim perumus.
(2) Kebijakan sebagaimana dimaksud pada ayat (1) disusun untuk mendukung kegiatan penyelenggaraan penanggulangan bencana pada saat tanggap darurat bencana.
(3) Kebijakan sebagaimana dimaksud pada ayat (2) meliputi:
a. pengkajian secara cepat dan tepat terhadap lokasi, kerusakan, kerugian, dan sumber daya;
b. penentuan status keadaan darurat bencana;
c. penyelamatan dan evakuasi masyarakat terkena bencana;
d. pemenuhan kebutuhan dasar;
e. pelindungan terhadap kelompok rentan; dan
f. pemulihan dengan segera prasarana dan sarana vital.
(4) Strategi sebagaimana dimaksud pada ayat (1) disusun untuk melaksanakan kebijakan secara efektif dan terpadu.', 'Pasal 21', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5403, 'perban-9-2025', 25, 'pasal', 'Pasal 22', 'BAB V MATERI DALAM RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 7, '(1) Manajemen penanganan darurat bencana sebagaimana dimaksud dalam Pasal 20 ayat (3) huruf b meliputi:
a. penentuan dan/atau penetapan status keadaan darurat bencana;
b. pelaksanaan operasi penanganan darurat bencana;
c. keterlibatan para pihak penanganan darurat bencana;
d. organisasi pelaksana penanganan darurat bencana; dan
e. pengendalian operasi penanganan darurat bencana.
(2) Penentuan dan/atau penetapan status keadaan darurat bencana sebagaimana dimaksud pada ayat (1) huruf a diawali dengan pelaksanaan kaji cepat.
(3) Pelaksanaan operasi penanganan darurat bencana sebagaimana dimaksud pada ayat (1) huruf b merupakan penjabaran operasi pada status darurat bencana.
(4) Keterlibatan para pihak penanganan darurat bencana sebagaimana dimaksud pada ayat (1) huruf c merupakan penjabaran peran pemerintah dan nonpemerintah dalam penanganan darurat bencana untuk pengerahan sumber daya.
(5) Organisasi pelaksana penanganan darurat bencana sebagaimana dimaksud pada ayat (1) huruf d merupakan sistem komando penanganan darurat bencana.
(6) Pengendalian operasi penanganan darurat bencana sebagaimana dimaksud pada ayat (1) huruf e dilaksanakan melalui mekanisme pengendalian operasi penanganan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5403, '(1) Manajemen penanganan darurat bencana sebagaimana dimaksud dalam Pasal 20 ayat (3) huruf b meliputi:
a. penentuan dan/atau penetapan status keadaan darurat bencana;
b. pelaksanaan operasi penanganan darurat bencana;
c. keterlibatan para pihak penanganan darurat bencana;
d. organisasi pelaksana penanganan darurat bencana; dan
e. pengendalian operasi penanganan darurat bencana.
(2) Penentuan dan/atau penetapan status keadaan darurat bencana sebagaimana dimaksud pada ayat (1) huruf a diawali dengan pelaksanaan kaji cepat.
(3) Pelaksanaan operasi penanganan darurat bencana sebagaimana dimaksud pada ayat (1) huruf b merupakan penjabaran operasi pada status darurat bencana.
(4) Keterlibatan para pihak penanganan darurat bencana sebagaimana dimaksud pada ayat (1) huruf c merupakan penjabaran peran pemerintah dan nonpemerintah dalam penanganan darurat bencana untuk pengerahan sumber daya.
(5) Organisasi pelaksana penanganan darurat bencana sebagaimana dimaksud pada ayat (1) huruf d merupakan sistem komando penanganan darurat bencana.
(6) Pengendalian operasi penanganan darurat bencana sebagaimana dimaksud pada ayat (1) huruf e dilaksanakan melalui mekanisme pengendalian operasi penanganan darurat bencana.', 'Pasal 22', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5404, 'perban-9-2025', 26, 'pasal', 'Pasal 23', 'BAB V MATERI DALAM RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 8, '(1) Pengerahan sumber daya sebagaimana dimaksud dalam Pasal 22 ayat (4), mencakup:
a. dukungan sumber daya manusia;
b. dukungan sumber daya peralatan;
c. dukungan sumber daya logistik; dan
d. dukungan sumber daya anggaran.
(2) Dukungan sumber daya manusia sebagaimana dimaksud pada ayat (1) huruf a berisikan kebijakan dan mekanisme pengerahan sumber daya manusia/personil berdasarkan keahlian untuk penanganan darurat bencana.
(3) Dukungan sumber daya peralatan sebagaimana dimaksud pada ayat (1) huruf b berisikan kebijakan dan mekanisme pengerahan sumber daya peralatan untuk penanganan darurat bencana.
(4) Dukungan sumber daya logistik sebagaimana dimaksud pada ayat (1) huruf c berisikan kebijakan dan mekanisme pengerahan sumber daya logistik untuk penanganan darurat bencana.
(5) Dukungan sumber daya anggaran sebagaimana dimaksud pada ayat (1) huruf d berisikan kebijakan dan mekanisme penggunaan anggaran dan sumber keuangan yang dapat dikelola dalam penanganan darurat bencana.
(6) Dalam hal dukungan sumber daya sebagaimana dimaksud pada ayat (1) belum tersedia, dapat diselenggarakan melalui mekanisme yang disepakati oleh para pihak penanganan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5404, '(1) Pengerahan sumber daya sebagaimana dimaksud dalam Pasal 22 ayat (4), mencakup:
a. dukungan sumber daya manusia;
b. dukungan sumber daya peralatan;
c. dukungan sumber daya logistik; dan
d. dukungan sumber daya anggaran.
(2) Dukungan sumber daya manusia sebagaimana dimaksud pada ayat (1) huruf a berisikan kebijakan dan mekanisme pengerahan sumber daya manusia/personil berdasarkan keahlian untuk penanganan darurat bencana.
(3) Dukungan sumber daya peralatan sebagaimana dimaksud pada ayat (1) huruf b berisikan kebijakan dan mekanisme pengerahan sumber daya peralatan untuk penanganan darurat bencana.
(4) Dukungan sumber daya logistik sebagaimana dimaksud pada ayat (1) huruf c berisikan kebijakan dan mekanisme pengerahan sumber daya logistik untuk penanganan darurat bencana.
(5) Dukungan sumber daya anggaran sebagaimana dimaksud pada ayat (1) huruf d berisikan kebijakan dan mekanisme penggunaan anggaran dan sumber keuangan yang dapat dikelola dalam penanganan darurat bencana.
(6) Dalam hal dukungan sumber daya sebagaimana dimaksud pada ayat (1) belum tersedia, dapat diselenggarakan melalui mekanisme yang disepakati oleh para pihak penanganan darurat bencana.', 'Pasal 23', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5405, 'perban-9-2025', 27, 'pasal', 'Pasal 24', 'BAB V MATERI DALAM RENCANA PENANGGULANGAN KEDARURATAN BENCANA DAERAH', 8, 'Pengendalian operasi penanganan darurat bencana sebagaimana dimaksud dalam Pasal 22 ayat (6) terdiri atas:
a. instruksi;
b. komando dan kendali;
c. koordinasi;
d. komunikasi; dan
e. pengelolaan informasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5405, 'Pengendalian operasi penanganan darurat bencana sebagaimana dimaksud dalam Pasal 22 ayat (6) terdiri atas:
a. instruksi;
b. komando dan kendali;
c. koordinasi;
d. komunikasi; dan
e. pengelolaan informasi.', 'Pasal 24', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5406, 'perban-9-2025', 28, 'pasal', 'Pasal 25', 'BAB VI PEMUTAKHIRAN', 8, '(1) Instruksi sebagaimana dimaksud dalam Pasal 23 huruf a memuat arahan, perintah, atau pokok-pokok mandat kepada organisasi komando penanganan darurat bencana yang diberikan oleh kepala daerah.
(2) Komando dan kendali sebagaimana dimaksud dalam Pasal 23 huruf b memuat kebijakan dan mekanisme komando dan pengendalian penanganan kedaruratan bencana.
(3) Koordinasi sebagaimana dimaksud dalam Pasal 23 huruf c memuat kebijakan dan mekanisme koordinasi dalam penanganan kedaruratan bencana.
(4) Komunikasi sebagaimana dimaksud dalam Pasal 23 huruf d memuat kebijakan dan mekanisme komunikasi dalam penanganan kedaruratan bencana.
(5) Pengelolaan informasi sebagaimana dimaksud dalam Pasal 23 huruf e memuat kebijakan dan mekanisme pengelolaan dan/atau penanganan informasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5406, '(1) Instruksi sebagaimana dimaksud dalam Pasal 23 huruf a memuat arahan, perintah, atau pokok-pokok mandat kepada organisasi komando penanganan darurat bencana yang diberikan oleh kepala daerah.
(2) Komando dan kendali sebagaimana dimaksud dalam Pasal 23 huruf b memuat kebijakan dan mekanisme komando dan pengendalian penanganan kedaruratan bencana.
(3) Koordinasi sebagaimana dimaksud dalam Pasal 23 huruf c memuat kebijakan dan mekanisme koordinasi dalam penanganan kedaruratan bencana.
(4) Komunikasi sebagaimana dimaksud dalam Pasal 23 huruf d memuat kebijakan dan mekanisme komunikasi dalam penanganan kedaruratan bencana.
(5) Pengelolaan informasi sebagaimana dimaksud dalam Pasal 23 huruf e memuat kebijakan dan mekanisme pengelolaan dan/atau penanganan informasi.', 'Pasal 25', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5407, 'perban-9-2025', 29, 'pasal', 'Pasal 26', 'BAB VII UJI COBA', 9, '(1) Untuk menjaga aktualitas dan validitas terhadap RPKB Daerah yang telah ditetapkan, RPKB Daerah dapat dilakukan pemutakhiran.
(2) Pemutakhiran sebagaimana dimaksud pada ayat (1) dilakukan jika terdapat:
a. perubahan ancaman bencana;
b. perubahan organisasi/instansi; dan/atau
c. hasil evaluasi penanganan darurat bencana.
(3) Proses pemutakhiran RPKB Daerah sebagaimana dimaksud pada ayat (2) dilaksanakan melalui kesepakatan para pihak.
(4) RPKB Daerah yang telah dimutakhirkan ditetapkan kembali oleh kepala daerah dalam bentuk peraturan kepala daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5407, '(1) Untuk menjaga aktualitas dan validitas terhadap RPKB Daerah yang telah ditetapkan, RPKB Daerah dapat dilakukan pemutakhiran.
(2) Pemutakhiran sebagaimana dimaksud pada ayat (1) dilakukan jika terdapat:
a. perubahan ancaman bencana;
b. perubahan organisasi/instansi; dan/atau
c. hasil evaluasi penanganan darurat bencana.
(3) Proses pemutakhiran RPKB Daerah sebagaimana dimaksud pada ayat (2) dilaksanakan melalui kesepakatan para pihak.
(4) RPKB Daerah yang telah dimutakhirkan ditetapkan kembali oleh kepala daerah dalam bentuk peraturan kepala daerah.', 'Pasal 26', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5408, 'perban-9-2025', 30, 'pasal', 'Pasal 27', 'BAB VIII DISEMINASI', 9, '(1) Sebagai upaya penguatan kesiapsiagaan, pemerintah daerah melaksanakan uji coba setelah RPKB Daerah ditetapkan.
(2) Uji coba sebagaimana dimaksud pada ayat (1) dilaksanakan melalui Gladi Ruang.
(3) Uji coba sebagaimana dimaksud pada ayat (2) dilaksanakan sesuai dengan panduan yang ditetapkan oleh kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5408, '(1) Sebagai upaya penguatan kesiapsiagaan, pemerintah daerah melaksanakan uji coba setelah RPKB Daerah ditetapkan.
(2) Uji coba sebagaimana dimaksud pada ayat (1) dilaksanakan melalui Gladi Ruang.
(3) Uji coba sebagaimana dimaksud pada ayat (2) dilaksanakan sesuai dengan panduan yang ditetapkan oleh kepala BNPB.', 'Pasal 27', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5409, 'perban-9-2025', 31, 'pasal', 'Pasal 28', 'BAB IX PENDANAAN', 9, '(1) Diseminasi RPKB Daerah dilakukan untuk memperkuat komitmen bersama pihak terkait penanganan kedaruratan bencana.
(2) Penyampaian RPKB Daerah sebagaimana dimaksud pada ayat (1) dilaksanakan secara kedinasan.
(3) RPKB Daerah disampaikan kepada BNPB sebagai laporan pelaksanaan penyusunan dan uji coba RPKB Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5409, '(1) Diseminasi RPKB Daerah dilakukan untuk memperkuat komitmen bersama pihak terkait penanganan kedaruratan bencana.
(2) Penyampaian RPKB Daerah sebagaimana dimaksud pada ayat (1) dilaksanakan secara kedinasan.
(3) RPKB Daerah disampaikan kepada BNPB sebagai laporan pelaksanaan penyusunan dan uji coba RPKB Daerah.', 'Pasal 28', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5410, 'perban-9-2025', 32, 'pasal', 'Pasal 29', 'BAB X KETENTUAN PENUTUP', 9, 'Pendanaan penyusunan dan uji coba RPKB Daerah bersumber dari:
a. anggaran pendapatan belanja negara;
b. anggaran pendapatan belanja daerah; dan/atau
c. sumber lain yang sah dan tidak mengikat sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5410, 'Pendanaan penyusunan dan uji coba RPKB Daerah bersumber dari:
a. anggaran pendapatan belanja negara;
b. anggaran pendapatan belanja daerah; dan/atau
c. sumber lain yang sah dan tidak mengikat sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 29', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5411, 'perban-9-2025', 33, 'pasal', 'Pasal 30', 'BAB X KETENTUAN PENUTUP', 10, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5411, 'Peraturan Badan ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Badan ini dan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 30', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5412, 'perban-9-2025', 34, 'lain', 'Penutup', NULL, 11, 'Ditetapkan di Jakarta pada tanggal 22 Desember 2025 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2025 NOMOR Ж');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5412, 'Ditetapkan di Jakarta pada tanggal 22 Desember 2025 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA REPUBLIK INDONESIA, Œ SUHARYANTO Diundangkan di Jakarta pada tanggal Д DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM REPUBLIK INDONESIA, Ѽ DHAHANA PUTRA BERITA NEGARA REPUBLIK INDONESIA TAHUN 2025 NOMOR Ж', 'Penutup', 'Peraturan Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2025 tentang Penyusunan dan Uji Coba Rencana Penanggulangan Kedaruratan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5413, 'perka-1-2008', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5413, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5414, 'perka-1-2008', 1, 'menimbang', 'Menimbang', NULL, 1, 'bahwa dalam rangka melaksanakan ketentuan Pasal 64 Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana, dipandang perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan. Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5414, 'bahwa dalam rangka melaksanakan ketentuan Pasal 64 Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana, dipandang perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan. Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5415, 'perka-1-2008', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
3. Keputusan Presiden Nomor 29/M Tahun 2008 tentang Pengangkatan Kepala Badan Nasional Penanggulangan Bencana;
Memperhatikan Persetujuan Menteri Negara Pendayagunaan Aparatur Negara dalam surat Nomor 1239/ M. PAN/ 5/ 2008 tanggal 12 Mei 2008;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5415, '1. Undang-undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
3. Keputusan Presiden Nomor 29/M Tahun 2008 tentang Pengangkatan Kepala Badan Nasional Penanggulangan Bencana;
Memperhatikan Persetujuan Menteri Negara Pendayagunaan Aparatur Negara dalam surat Nomor 1239/ M. PAN/ 5/ 2008 tanggal 12 Mei 2008;', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5416, 'perka-1-2008', 3, 'menetapkan', 'Menetapkan', NULL, 1, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG ORGANISASI DAN TATA KERJA BADAN NASIONAL PENANGGULANGAN BENCANA.
1');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5416, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG ORGANISASI DAN TATA KERJA BADAN NASIONAL PENANGGULANGAN BENCANA.
1', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5417, 'perka-1-2008', 4, 'pasal', 'Pasal 1', 'BAB I KEDUDUKAN, TUGAS DAN FUNGSI', 2, '(1) Badan Nasional Penanggulangan Bencana yang selanjutnya dalam Peraturan ini disebut BNPB, berada di bawah dan bertanggungjawab kepada Presiden.
(2) BNPB dipimpin oleh seorang Kepala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5417, '(1) Badan Nasional Penanggulangan Bencana yang selanjutnya dalam Peraturan ini disebut BNPB, berada di bawah dan bertanggungjawab kepada Presiden.
(2) BNPB dipimpin oleh seorang Kepala.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5418, 'perka-1-2008', 5, 'pasal', 'Pasal 2', 'BAB I KEDUDUKAN, TUGAS DAN FUNGSI', 2, 'BNPB mempunyai tugas
a. memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana yang mencakup pencegahan bencana, penanganan tanggap darurat, rehabilitasi, dan rekonstruksi secara adil dan setara;
b. menetapkan standardisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundangundangan;
c. menyampaikan informasi kegiatan penanggulangan bencana kepada masyarakat;
d. melaporkan penyelenggaraan penanggulangan bencana kepada Presiden setiap sebulan sekali dalam kondisi normal dan setiap saat dalam kondisi darurat bencana;
e. menggunakan dan mempertanggungjawabkan sumbangan/bantuan nasional dan internasional;
f. mempertanggungjawabkan penggunaan anggaran yang diterima dari Anggaran Pendapatan dan Belanja Negara;
g. melaksanakan kewajiban lain sesuai dengan peraturan perundangundangan; dan
h. menyusun pedoman pembentukan Badan Penanggulangan Bencana Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5418, 'BNPB mempunyai tugas
a. memberikan pedoman dan pengarahan terhadap usaha penanggulangan bencana yang mencakup pencegahan bencana, penanganan tanggap darurat, rehabilitasi, dan rekonstruksi secara adil dan setara;
b. menetapkan standardisasi dan kebutuhan penyelenggaraan penanggulangan bencana berdasarkan peraturan perundangundangan;
c. menyampaikan informasi kegiatan penanggulangan bencana kepada masyarakat;
d. melaporkan penyelenggaraan penanggulangan bencana kepada Presiden setiap sebulan sekali dalam kondisi normal dan setiap saat dalam kondisi darurat bencana;
e. menggunakan dan mempertanggungjawabkan sumbangan/bantuan nasional dan internasional;
f. mempertanggungjawabkan penggunaan anggaran yang diterima dari Anggaran Pendapatan dan Belanja Negara;
g. melaksanakan kewajiban lain sesuai dengan peraturan perundangundangan; dan
h. menyusun pedoman pembentukan Badan Penanggulangan Bencana Daerah.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5419, 'perka-1-2008', 6, 'pasal', 'Pasal 3', 'BAB II ORGANISASI BNPB; Bagian Pertama Susunan Organisasi', 2, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 2, BNPB menyelenggarakan fungsi
a. perumusan dan penetapan kebijakan penanggulangan bencana dan penanganan pengungsi dengan bertindak cepat dan tepat serta efektif dan efisien; dan
b. pengkoordinasian pelaksanaan kegiatan penanggulangan bencana secara terencana, terpadu, dan menyeluruh.
2');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5419, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 2, BNPB menyelenggarakan fungsi
a. perumusan dan penetapan kebijakan penanggulangan bencana dan penanganan pengungsi dengan bertindak cepat dan tepat serta efektif dan efisien; dan
b. pengkoordinasian pelaksanaan kegiatan penanggulangan bencana secara terencana, terpadu, dan menyeluruh.
2', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5420, 'perka-1-2008', 7, 'pasal', 'Pasal 4', 'BAB II ORGANISASI BNPB; Bagian Kedua Kepala', 3, 'BNPB terdiri atas :
a. Kepala;
b. Unsur Pengarah Penanggulangan Bencana; dan
c. Unsur Pelaksana Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5420, 'BNPB terdiri atas :
a. Kepala;
b. Unsur Pengarah Penanggulangan Bencana; dan
c. Unsur Pelaksana Penanggulangan Bencana.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5421, 'perka-1-2008', 8, 'pasal', 'Pasal 5', 'BAB II ORGANISASI BNPB; Bagian Ketiga Unsur Pengarah Penanggulangan Bencana', 3, 'Kepala mempunyai tugas memimpin BNPB dalam menjalankan tugas dan fungsi.
BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5421, 'Kepala mempunyai tugas memimpin BNPB dalam menjalankan tugas dan fungsi.
BNPB.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5422, 'perka-1-2008', 9, 'pasal', 'Pasal 6', 'BAB II ORGANISASI BNPB; Bagian Ketiga Unsur Pengarah Penanggulangan Bencana', 3, 'Unsur Pengarah Penanggulangan Bencana berada di bawah dan bertanggung jawab kepada Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5422, 'Unsur Pengarah Penanggulangan Bencana berada di bawah dan bertanggung jawab kepada Kepala BNPB.', 'Pasal 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5423, 'perka-1-2008', 10, 'pasal', 'Pasal 7', 'BAB II ORGANISASI BNPB; Bagian Ketiga Unsur Pengarah Penanggulangan Bencana', 3, 'Unsur Pengarah Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 6 mempunyai tugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5423, 'Unsur Pengarah Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 6 mempunyai tugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.', 'Pasal 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5424, 'perka-1-2008', 11, 'pasal', 'Pasal 8', 'BAB II ORGANISASI BNPB; Bagian Ketiga Unsur Pengarah Penanggulangan Bencana', 3, 'Untuk melaksanakan tugas sebagaimana dimaksud dalam Pasal 7, Unsur Pengarah Penanggulangan Bencana menyelenggarakan fungsi :
a. perumusan konsep kebijakan penanggulangan bencana nasional;
b. pemantauan; dan
c. evaluasi penyelenggaraan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5424, 'Untuk melaksanakan tugas sebagaimana dimaksud dalam Pasal 7, Unsur Pengarah Penanggulangan Bencana menyelenggarakan fungsi :
a. perumusan konsep kebijakan penanggulangan bencana nasional;
b. pemantauan; dan
c. evaluasi penyelenggaraan penanggulangan bencana.', 'Pasal 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5425, 'perka-1-2008', 12, 'pasal', 'Pasal 9', 'BAB II ORGANISASI BNPB; Bagian Ketiga Unsur Pengarah Penanggulangan Bencana', 3, 'Unsur Pengarah Penanggulangan Bencana terdiri dari Ketua yang dijabat oleh Kepala BNPB dan 19 (sembilan belas) anggota.
3');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5425, 'Unsur Pengarah Penanggulangan Bencana terdiri dari Ketua yang dijabat oleh Kepala BNPB dan 19 (sembilan belas) anggota.
3', 'Pasal 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5426, 'perka-1-2008', 13, 'pasal', 'Pasal 10', 'BAB II ORGANISASI BNPB; Bagian Keempat Unsur Pelaksana Penanggulangan Bencana', 4, '(1) Anggota Unsur Pengarah Penanggulangan Bencana terdiri dari
a. 10 (sepuluh) Pejabat Pemerintah Eselon I atau yang setingkat, yang diusulkan oleh Pimpinan Lembaga Pemerintah; dan
b. 9 (sembilan) Anggota masyarakat profesional.
(2) Pejabat Pemerintah sebagaimana dimaksud pada ayat (1) huruf a, mewakili:
a. Kementerian Koordinator Bidang Kesejahteraan Rakyat;
b. Departemen Dalam Negeri;
c. Departemen Sosial;
d. Departemen Pekerjaan Umum;
e. Departemen Kesehatan;
f. Departemen Keuangan;
g. Departemen Perhubungan;
h. Departemen Energi dan Sumberdaya Mineral;
i. Kepolisian Negara Republik Indonesia; dan
j. Tentara Nasional Republik Indonesia.
(3) Unsur Pengarah Penanggulangan Bencana dari anggota masyarakat profesional sebagaimana dimaksud pada ayat (1) huruf b, berasal dari pakar/ profesional dan/ atau tokoh masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5426, '(1) Anggota Unsur Pengarah Penanggulangan Bencana terdiri dari
a. 10 (sepuluh) Pejabat Pemerintah Eselon I atau yang setingkat, yang diusulkan oleh Pimpinan Lembaga Pemerintah; dan
b. 9 (sembilan) Anggota masyarakat profesional.
(2) Pejabat Pemerintah sebagaimana dimaksud pada ayat (1) huruf a, mewakili:
a. Kementerian Koordinator Bidang Kesejahteraan Rakyat;
b. Departemen Dalam Negeri;
c. Departemen Sosial;
d. Departemen Pekerjaan Umum;
e. Departemen Kesehatan;
f. Departemen Keuangan;
g. Departemen Perhubungan;
h. Departemen Energi dan Sumberdaya Mineral;
i. Kepolisian Negara Republik Indonesia; dan
j. Tentara Nasional Republik Indonesia.
(3) Unsur Pengarah Penanggulangan Bencana dari anggota masyarakat profesional sebagaimana dimaksud pada ayat (1) huruf b, berasal dari pakar/ profesional dan/ atau tokoh masyarakat.', 'Pasal 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5427, 'perka-1-2008', 14, 'pasal', 'Pasal 11', 'BAB II ORGANISASI BNPB; Bagian Keempat Unsur Pelaksana Penanggulangan Bencana', 4, 'Unsur Pelaksana Penanggulangan Bencana berada di bawah dan bertanggungjawab kepada Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5427, 'Unsur Pelaksana Penanggulangan Bencana berada di bawah dan bertanggungjawab kepada Kepala BNPB.', 'Pasal 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5428, 'perka-1-2008', 15, 'pasal', 'Pasal 12', 'BAB II ORGANISASI BNPB; Bagian Keempat Unsur Pelaksana Penanggulangan Bencana', 4, 'Unsur Pelaksana Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 11 mempunyai tugas melaksanakan penanggulangan bencana secara terintegrasi yang meliputi prabencana, saat tanggap darurat, dan pasca bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5428, 'Unsur Pelaksana Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 11 mempunyai tugas melaksanakan penanggulangan bencana secara terintegrasi yang meliputi prabencana, saat tanggap darurat, dan pasca bencana.', 'Pasal 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5429, 'perka-1-2008', 16, 'pasal', 'Pasal 13', 'BAB II ORGANISASI BNPB; Bagian Keempat Unsur Pelaksana Penanggulangan Bencana', 4, 'Unsur Pelaksana Penanggulangan Bencana menyelenggarakan fungsi:
a. koordinasi penyelenggaraan penanggulangan bencana;
b. komando penyelenggaraan penanggulangan bencana; dan
c. pelaksana dalam penyelenggaraan penanggulangan bencana.
4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5429, 'Unsur Pelaksana Penanggulangan Bencana menyelenggarakan fungsi:
a. koordinasi penyelenggaraan penanggulangan bencana;
b. komando penyelenggaraan penanggulangan bencana; dan
