INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5443, 'perka-1-2008', 30, 'pasal', 'Pasal 31', 'BAB II ORGANISASI BNPB; Bagian Keempat Unsur Pelaksana Penanggulangan Bencana', 7, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 30, Bagian Monitoring dan Evaluasi menyelenggarakan fungsi:
