INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5452, 'perka-1-2008', 39, 'pasal', 'Pasal 40', 'BAB II ORGANISASI BNPB; Bagian Keempat Unsur Pelaksana Penanggulangan Bencana', 8, '(1) Subbagian Anggaran I mempunyai tugas melakukan penyiapan bahan koordinasi penggunaan/pengeluaran dan penerimaan serta pengelolaan anggaran yang proses dan pertanggungjawabannya melalui KPKN, termasuk bantuan luar negeri yang menggunakan dana pendamping.
(2) Subbagian Anggaran II mempunyai tugas melakukan penyiapan bahan koordinasi penggunaan/pengeluaran dan penerimaan serta pengelolaan anggaran yang proses dan pertanggungjawabannya tidak melalui Kantor Perbendaaan dan Kas Negara (KPKN), dana masyarakat termasuk bantuan luar negeri.');
