INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5670, 'perka-1-2008', 257, 'pasal', 'Pasal 258', 'BAB II ORGANISASI BNPB; Bagian Keempat Unsur Pelaksana Penanggulangan Bencana', 50, 'Inspektorat I mempunyai tugas melaksanakan pengkoordinasian pengawasan fungsional terhadap pelaksanaan tugas dan fungsi di lingkungan Deputi Bidang Pencegahan dan Kesiapsiagaan, Deputi Bidang Rehabilitasi dan Rekonstruksi, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, serta Pusat Data, Informasi dan Humas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5670, 'Inspektorat I mempunyai tugas melaksanakan pengkoordinasian pengawasan fungsional terhadap pelaksanaan tugas dan fungsi di lingkungan Deputi Bidang Pencegahan dan Kesiapsiagaan, Deputi Bidang Rehabilitasi dan Rekonstruksi, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, serta Pusat Data, Informasi dan Humas.', 'Pasal 258', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5671, 'perka-1-2008', 258, 'pasal', 'Pasal 259', 'BAB II ORGANISASI BNPB; Bagian Keempat Unsur Pelaksana Penanggulangan Bencana', 50, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 258, Inspektorat I menyelenggarakan fungsi:
a. perumusan rencana dan program kerja pengawasan;
b. pelaksanaan pemeriksaan, penilaian dan pengujian kinerja di lingkungan Deputi Bidang Pencegahan dan Kesiapsiagaan, Deputi Bidang Rehabilitasi dan Rekonstruksi, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, serta Pusat Data, Informasi dan Humas;
c. pelaksanaan pemeriksaan, penilaian dan pengujian pengelolaan keuangan, barang dan jasa serta Sistem Akuntansi Instansi di lingkungan Deputi Bidang Pencegahan dan Kesiapsiagaan, Deputi Bidang Rehabilitasi dan Rekonstruksi, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, serta Pusat Data, Informasi dan Humas;
d. pelaksanaan pemeriksaan, penilaian, dan pengujian akuntabilitas di lingkungan Deputi Bidang Pencegahan dan Kesiapsiagaan, Deputi Bidang Rehabilitasi dan Rekonstruksi, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, serta Pusat Data, Informasi dan Humas;
e. pemantauan dan evaluasi seluruh pelaksanaan tugas di lingkungan Deputi Bidang Pencegahan dan Kesiapsiagaan, Deputi Bidang Rehabilitasi dan Rekonstruksi, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana dan Pusat Data, Informasi dan Humas;
51
f. pelaksanaan pemeriksaan, penilaian, dan pengujian khusus untuk tujuan tertentu di lingkungan Deputi Bidang Pencegahan dan Kesiapsiagaan, Deputi Bidang Rehabilitasi dan Rekonstruksi, Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, dan Pusat Data, Informasi dan Humas atas petunjuk Kepala BNPB; dan
g. penyusunan Laporan Hasil Pengawasan (LHP) Inspektorat I;');
