INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5675, 'perka-1-2008', 262, 'pasal', 'Pasal 263', 'BAB II ORGANISASI BNPB; Bagian Keempat Unsur Pelaksana Penanggulangan Bencana', 52, 'Pu sat Data, Informasi dan Humas mempunyai tugas melaksanakan pengkoordinasian pengelolaan data dan informasi, pengembangan basisdata dan sistem informasi, serta pelaksanaan hubungan masyarakat di bidang penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5675, 'Pu sat Data, Informasi dan Humas mempunyai tugas melaksanakan pengkoordinasian pengelolaan data dan informasi, pengembangan basisdata dan sistem informasi, serta pelaksanaan hubungan masyarakat di bidang penanggulangan bencana.', 'Pasal 263', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5676, 'perka-1-2008', 263, 'pasal', 'Pasal 264', 'BAB II ORGANISASI BNPB; Bagian Keempat Unsur Pelaksana Penanggulangan Bencana', 52, 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 263, Pusat Data, Informasi dan Humas menyelenggarakan fungsi:
