INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5703, 'Kelompok Jabatan Fungsional mempunyai tugas melaksanakan tugas sesuai dengan jabatan fungsional masing-masing berdasarkan peraturan perundang-undangan yang berlaku.', 'Pasal 291', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5704, 'perka-1-2008', 291, 'pasal', 'Pasal 292', 'BAB III TATA KERJA', 57, '(1) Kelompok Jabatan Fungsional terdiri atas sejumlah tenaga dalam jenjang jabatan fungsional yang diatur berdasarkan peraturan perundang-undangan yang berlaku.
(2) Kelompok Jabatan Fungsional tersebut pada ayat (1) pasal ini, dikoordinasikan oleh pejabat fungsional senior yang ditunjuk oleh Kepala BNPB.
(3) Jumlah tenaga fungsional tersebut pada ayat (1) pasal ini, ditentukan berdasarkan kebutuhan dan beban kerja.
(4) Jenis dan jenjang jabatan fungsional tersebut pada ayat (1) pasal ini, diatur berdasarkan peraturan perundang-undangan yang berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5704, '(1) Kelompok Jabatan Fungsional terdiri atas sejumlah tenaga dalam jenjang jabatan fungsional yang diatur berdasarkan peraturan perundang-undangan yang berlaku.
(2) Kelompok Jabatan Fungsional tersebut pada ayat (1) pasal ini, dikoordinasikan oleh pejabat fungsional senior yang ditunjuk oleh Kepala BNPB.
(3) Jumlah tenaga fungsional tersebut pada ayat (1) pasal ini, ditentukan berdasarkan kebutuhan dan beban kerja.
(4) Jenis dan jenjang jabatan fungsional tersebut pada ayat (1) pasal ini, diatur berdasarkan peraturan perundang-undangan yang berlaku.', 'Pasal 292', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5705, 'perka-1-2008', 292, 'pasal', 'Pasal 293', 'BAB III TATA KERJA', 57, '(1) Kepala BNPB mengendalikan pelaksanaan tugas dan fungsi BNPB.
(2) Unsur Pengarah melaksanakan sidang anggota secara berkala dan jatau sewaktu-waktu sesuai dengan kebutuhan yang ditetapkan oleh Kepala BNPB selaku Ketua Unsur Pengarah Penanggulangan Bencana.
(3) Unsur Pengarah Penanggulangan Bencana dapat mengundang lemabaga pemerintah baik pusat maupun daerah, lembaga usaha, lembaga internasional daniatau pihak lain yang dipandang perlu dalam sidang anggota Unsur Pengarah Penanggulangan Bencana.
58');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5705, '(1) Kepala BNPB mengendalikan pelaksanaan tugas dan fungsi BNPB.
(2) Unsur Pengarah melaksanakan sidang anggota secara berkala dan jatau sewaktu-waktu sesuai dengan kebutuhan yang ditetapkan oleh Kepala BNPB selaku Ketua Unsur Pengarah Penanggulangan Bencana.
(3) Unsur Pengarah Penanggulangan Bencana dapat mengundang lemabaga pemerintah baik pusat maupun daerah, lembaga usaha, lembaga internasional daniatau pihak lain yang dipandang perlu dalam sidang anggota Unsur Pengarah Penanggulangan Bencana.
58', 'Pasal 293', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5706, 'perka-1-2008', 293, 'pasal', 'Pasal 294', 'BAB III TATA KERJA', 58, 'Dalam melaksanakan tugasnya, setiap pimpinan satuan organisasi di lingkungan BNPB wajib menerapkan prinsip koordinasi, integrasi dan sinkronisasi baik di lingkungan masing-masing maupun antar unit organisasi dalam lingkungan BNPB serta dengan instansi lain di luar BNPB sesuai bidang tugasnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5706, 'Dalam melaksanakan tugasnya, setiap pimpinan satuan organisasi di lingkungan BNPB wajib menerapkan prinsip koordinasi, integrasi dan sinkronisasi baik di lingkungan masing-masing maupun antar unit organisasi dalam lingkungan BNPB serta dengan instansi lain di luar BNPB sesuai bidang tugasnya.', 'Pasal 294', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5707, 'perka-1-2008', 294, 'pasal', 'Pasal 295', 'BAB III TATA KERJA', 58, 'Setiap pimpinan satuan organisasi wajib melakukan pengawasan terhadap pelaksanaan tugas bawahan masing-masing, dan apabila terjadi penyimpangan wajib mengambil langkah-langkah yang diperlukan sesuai dengan peraturan perundang-undangan yang berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5707, 'Setiap pimpinan satuan organisasi wajib melakukan pengawasan terhadap pelaksanaan tugas bawahan masing-masing, dan apabila terjadi penyimpangan wajib mengambil langkah-langkah yang diperlukan sesuai dengan peraturan perundang-undangan yang berlaku.', 'Pasal 295', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5708, 'perka-1-2008', 295, 'pasal', 'Pasal 296', 'BAB III TATA KERJA', 58, 'Setiap pimpinan satuan organisasi di lingkungan BNPB bertanggung jawab memimpin dan mengkoordinasikan bawahannya masing-masing dan memberikan bimbingan serta petunjuk bagi pelaksanaan tugas bawahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5708, 'Setiap pimpinan satuan organisasi di lingkungan BNPB bertanggung jawab memimpin dan mengkoordinasikan bawahannya masing-masing dan memberikan bimbingan serta petunjuk bagi pelaksanaan tugas bawahan.', 'Pasal 296', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5709, 'perka-1-2008', 296, 'pasal', 'Pasal 297', 'BAB III TATA KERJA', 58, 'Setiap pimpinan satuan organisasi wajib mengikuti dan mematuhi petunjuk serta bertanggung jawab kepada atasan masing-masing dan menyampaikan laporan berkala tepat pada waktunya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5709, 'Setiap pimpinan satuan organisasi wajib mengikuti dan mematuhi petunjuk serta bertanggung jawab kepada atasan masing-masing dan menyampaikan laporan berkala tepat pada waktunya.', 'Pasal 297', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5710, 'perka-1-2008', 297, 'pasal', 'Pasal 298', 'BAB III TATA KERJA', 58, 'Setiap laporan yang diterima oleh pimpinan satuan organisasi dari bawahannya wajib diolah dan dipergunakan sebagai bahan untuk penyusunan laporan lebih lanjut dan untuk memberikan petunjuk kepada bawahannya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5710, 'Setiap laporan yang diterima oleh pimpinan satuan organisasi dari bawahannya wajib diolah dan dipergunakan sebagai bahan untuk penyusunan laporan lebih lanjut dan untuk memberikan petunjuk kepada bawahannya.', 'Pasal 298', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5711, 'perka-1-2008', 298, 'pasal', 'Pasal 299', 'BAB III TATA KERJA', 58, 'Dalam menyampaikan laporan kepada atasan, tembusan laporan wajib disampaikan pula kepada satuan-satuan organisasi lain yang secara fungsional mempunyai hubungan kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5711, 'Dalam menyampaikan laporan kepada atasan, tembusan laporan wajib disampaikan pula kepada satuan-satuan organisasi lain yang secara fungsional mempunyai hubungan kerja.', 'Pasal 299', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5712, 'perka-1-2008', 299, 'pasal', 'Pasal 300', 'BAB III TATA KERJA', 58, 'Dalam melakukan tugasnya setiap pimpinan satuan organisasi dibantu oleh kepala satuan organisasi di bawahnya, dan dalam rangka pemberian bimbingan kepada bawahan, pimpinan wajib mengadakan rapat berkala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5712, 'Dalam melakukan tugasnya setiap pimpinan satuan organisasi dibantu oleh kepala satuan organisasi di bawahnya, dan dalam rangka pemberian bimbingan kepada bawahan, pimpinan wajib mengadakan rapat berkala.', 'Pasal 300', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5713, 'perka-1-2008', 300, 'pasal', 'Pasal 301', 'BAB III TATA KERJA', 58, 'Setiap pimpinan satuan organisasi wajib melaksanakan sistem pengendalian inter di lingkungan masing-masing yang memungkinkan terlaksananya mekanisme uji silang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5713, 'Setiap pimpinan satuan organisasi wajib melaksanakan sistem pengendalian inter di lingkungan masing-masing yang memungkinkan terlaksananya mekanisme uji silang.', 'Pasal 301', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5714, 'perka-1-2008', 301, 'pasal', 'Pasal 302', 'BAB III TATA KERJA', 58, 'Fungsi koordinasi Unsur Pelaksana Penanggulangan Bencana dilaksanakan melalui koordinasi dengan lembaga pemerintah baik pusat maupun daerah, lembaga usaha, lembaga internasional dan/atau pihak lain yang dipandang perlu pada tahap pra-bencana dan pasca-bencana.
59');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5714, 'Fungsi koordinasi Unsur Pelaksana Penanggulangan Bencana dilaksanakan melalui koordinasi dengan lembaga pemerintah baik pusat maupun daerah, lembaga usaha, lembaga internasional dan/atau pihak lain yang dipandang perlu pada tahap pra-bencana dan pasca-bencana.
59', 'Pasal 302', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5715, 'perka-1-2008', 302, 'pasal', 'Pasal 303', 'BAB III TATA KERJA', 59, '(1) Fungsi komando Unsur Pelaksana Penanggulangan Bencana dilaksanakan melalui pengerahan sumberdaya manusia, peralatan dan logistik dari instansi terkait, Tentara Nasional Indonesia dan Kepolisian Negara Republik Indonesia serta langkah-langkah lain yang diperlukan dalam rangka penanganan darurat bencana.
(2) Pelaksanaan ketentuan sebagaimana dimaksud pada ayat (1) dilakukan sesuai dengan peraturan perundang-undangan yang berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5715, '(1) Fungsi komando Unsur Pelaksana Penanggulangan Bencana dilaksanakan melalui pengerahan sumberdaya manusia, peralatan dan logistik dari instansi terkait, Tentara Nasional Indonesia dan Kepolisian Negara Republik Indonesia serta langkah-langkah lain yang diperlukan dalam rangka penanganan darurat bencana.
(2) Pelaksanaan ketentuan sebagaimana dimaksud pada ayat (1) dilakukan sesuai dengan peraturan perundang-undangan yang berlaku.', 'Pasal 303', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5716, 'perka-1-2008', 303, 'pasal', 'Pasal 304', 'BAB IV KETENTUAN LAIN-LAIN', 59, 'Fungsi pelaksanaan Unsur Pelaksana Penanggulangan Bencana dilaksanakan secara terkoordinasi dan terintegrasi dengan lembaga pemerintah baik pusat maupun daerah, Tentara Nasional Indonesia dan Kepolisian Negara Republik Indonesia dengan memperhatikan kebijakan penyelenggaraan penanggulangan bencana dan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5716, 'Fungsi pelaksanaan Unsur Pelaksana Penanggulangan Bencana dilaksanakan secara terkoordinasi dan terintegrasi dengan lembaga pemerintah baik pusat maupun daerah, Tentara Nasional Indonesia dan Kepolisian Negara Republik Indonesia dengan memperhatikan kebijakan penyelenggaraan penanggulangan bencana dan ketentuan peraturan perundang-undangan.', 'Pasal 304', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5717, 'perka-1-2008', 304, 'pasal', 'Pasal 305', 'BAB IV KETENTUAN LAIN-LAIN', 59, 'Perubahan atas organisasi dan tata kerja BNPB sebagaimana diatur dalam Peraturan ini ditetapkan oleh Kepala BNPB setelah terlebih dahulu mendapat persetujuan tertulis dari Menteri yang bertanggungjawab di bidang pendayagunaan aparatur negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5717, 'Perubahan atas organisasi dan tata kerja BNPB sebagaimana diatur dalam Peraturan ini ditetapkan oleh Kepala BNPB setelah terlebih dahulu mendapat persetujuan tertulis dari Menteri yang bertanggungjawab di bidang pendayagunaan aparatur negara.', 'Pasal 305', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5718, 'perka-1-2008', 305, 'pasal', 'Pasal 306', 'BAB V KETENTUAN PERALIHAN', 59, '(1) Di lingkungan BNPB dapat dibentuk Unit Pelaksana Teknis sebagai pelaksana tugas teknis baik teknis penunjang maupun teknis operasional.
(2) Pembentukan organisasi dan tata kerja Unit Pelaksana Teknis sebagaimana dimaksud pada ayat (1), ditetapkan oleh Kepala BNPB setelah mendapat persetujuan tertulis dari Menteri yang bertanggungjawab di bidang pendayagunaan aparatur negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5718, '(1) Di lingkungan BNPB dapat dibentuk Unit Pelaksana Teknis sebagai pelaksana tugas teknis baik teknis penunjang maupun teknis operasional.
(2) Pembentukan organisasi dan tata kerja Unit Pelaksana Teknis sebagaimana dimaksud pada ayat (1), ditetapkan oleh Kepala BNPB setelah mendapat persetujuan tertulis dari Menteri yang bertanggungjawab di bidang pendayagunaan aparatur negara.', 'Pasal 306', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5719, 'perka-1-2008', 306, 'pasal', 'Pasal 307', 'BAB VI KETENTUAN PENUTUP', 59, 'Pada saat mulai berlakunya Peraturan ini, SATKORLAK PB Provinsi dan SATLAK PB Kabupaten/Kota tetap menjalankan tugas penanggulangan bencana sampai dengan dibentuknya Badan Penanggulangan Bencana Daerah (BPBD) Provinsi dan Kabupaten/Kota berdasarkan Peraturan Gubernur dan Bupati/Walikota.
60');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5719, 'Pada saat mulai berlakunya Peraturan ini, SATKORLAK PB Provinsi dan SATLAK PB Kabupaten/Kota tetap menjalankan tugas penanggulangan bencana sampai dengan dibentuknya Badan Penanggulangan Bencana Daerah (BPBD) Provinsi dan Kabupaten/Kota berdasarkan Peraturan Gubernur dan Bupati/Walikota.
60', 'Pasal 307', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5720, 'perka-1-2008', 307, 'pasal', 'Pasal 308', 'BAB VI KETENTUAN PENUTUP', 60, 'Dengan berlakunya Peraturan ini, Keputusan Kepala Pelaksana Harian BAKORNAS PB Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Pelaksana Harian BAKORNAS PB, dinyatakan tidak berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5720, 'Dengan berlakunya Peraturan ini, Keputusan Kepala Pelaksana Harian BAKORNAS PB Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Pelaksana Harian BAKORNAS PB, dinyatakan tidak berlaku.', 'Pasal 308', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5721, 'perka-1-2008', 308, 'pasal', 'Pasal 309', 'BAB VI KETENTUAN PENUTUP', 60, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5721, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 309', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5722, 'perka-1-2008', 309, 'lain', 'Penutup', NULL, 60, 'Ditetapkan di Jakarta pada tanggal 15 Mei 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
