INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5722, 'Ditetapkan di Jakarta pada tanggal 15 Mei 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
