INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5724, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2009 tentang Pedoman Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara di Lingkungan Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2009 tentang Pedoman Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5725, 'perka-1-2011', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2011 tentang Rencana Aksi Rehabilitasi Dan Rekonstuksi Pasca Bencana Gempa Bumi Yapen-Waropen Tahun 2010-2011');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5725, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2011 tentang Rencana Aksi Rehabilitasi Dan Rekonstuksi Pasca Bencana Gempa Bumi Yapen-Waropen Tahun 2010-2011', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2011 tentang Rencana Aksi Rehabilitasi Dan Rekonstuksi Pasca Bencana Gempa Bumi Yapen-Waropen Tahun 2010-2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5726, 'perka-1-2011', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka percepatan pemulihan kehidupan masyarakat dan pembangunan kembali prasarana dan sarana pasca bencana gempabumi di wilayah Yapen­ Waropen Provinsi Papua pada tanggal 16 Juni 2010, diperlukan Rencana Aksi Rehabilitasi dan Rekonstruksi;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Rencana Aksi Rehabilitasi dan Rekonstruksi Pascabencana Gempabumi Yapen - Waropen Provinsi Papua Tahun 2010 - 2011;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5726, 'a. bahwa dalam rangka percepatan pemulihan kehidupan masyarakat dan pembangunan kembali prasarana dan sarana pasca bencana gempabumi di wilayah Yapen­ Waropen Provinsi Papua pada tanggal 16 Juni 2010, diperlukan Rencana Aksi Rehabilitasi dan Rekonstruksi;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Rencana Aksi Rehabilitasi dan Rekonstruksi Pascabencana Gempabumi Yapen - Waropen Provinsi Papua Tahun 2010 - 2011;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2011 tentang Rencana Aksi Rehabilitasi Dan Rekonstuksi Pasca Bencana Gempa Bumi Yapen-Waropen Tahun 2010-2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5727, 'perka-1-2011', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia l\Jomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nemer 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
2. Undang-Undang Nornor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
6. Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Peraturan Presiden Nomor 54 Tahun 2010 tentang Pengadaan BarangjJasa Pemerintah;
8. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi Pasca Bencana;
9. Peraturan Direktur Jenderal Perbendaharaan Kementerian Keuangan Nomor: Per-26jPBj2010 Tanggal 30 Juli 2010;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5727, '1. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia l\Jomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nemer 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
2. Undang-Undang Nornor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
6. Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Peraturan Presiden Nomor 54 Tahun 2010 tentang Pengadaan BarangjJasa Pemerintah;
8. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi Pasca Bencana;
9. Peraturan Direktur Jenderal Perbendaharaan Kementerian Keuangan Nomor: Per-26jPBj2010 Tanggal 30 Juli 2010;', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2011 tentang Rencana Aksi Rehabilitasi Dan Rekonstuksi Pasca Bencana Gempa Bumi Yapen-Waropen Tahun 2010-2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5728, 'perka-1-2011', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG RENCANA AKSI REHABILITASI DAN REKONSTRUKSI PASCABENCANA GEMPABUMI YAPEN - WAROPEN PROVINSI PAPUA TAHUN 2010 - 2011.
Pasall Rencana Aksi Rehabilitasi dan Rekonstruksi Pascabencana Gempabumi Yapen ­ Waropen Provinsi Papua Tahun 2010 - 2011, merupakan acuan bagi pemerintah, pemerintah provinsi, pemerintah kabupaten serta pihak yang terkait dalam kegiatan rehabilitasi dan rekonstruksi pascabencana gempabumi di Yapen ­ Waropen di Provinsi Papua.
Pasal2 Rencana Aksi sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian yang tidak terpisahkan dari peraturan ini.
Pasal3 Peraturan ini mulai berlaku pada tanggal ditetapkan.
Ditetapkan di Jakarta pada tanggal i 2.. Januari 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BEI''JCANA DR. SYAMSUL MAARIF, M.Si.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5728, 'Menetapkan PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG RENCANA AKSI REHABILITASI DAN REKONSTRUKSI PASCABENCANA GEMPABUMI YAPEN - WAROPEN PROVINSI PAPUA TAHUN 2010 - 2011.
Pasall Rencana Aksi Rehabilitasi dan Rekonstruksi Pascabencana Gempabumi Yapen ­ Waropen Provinsi Papua Tahun 2010 - 2011, merupakan acuan bagi pemerintah, pemerintah provinsi, pemerintah kabupaten serta pihak yang terkait dalam kegiatan rehabilitasi dan rekonstruksi pascabencana gempabumi di Yapen ­ Waropen di Provinsi Papua.
Pasal2 Rencana Aksi sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian yang tidak terpisahkan dari peraturan ini.
Pasal3 Peraturan ini mulai berlaku pada tanggal ditetapkan.
Ditetapkan di Jakarta pada tanggal i 2.. Januari 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BEI''JCANA DR. SYAMSUL MAARIF, M.Si.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2011 tentang Rencana Aksi Rehabilitasi Dan Rekonstuksi Pasca Bencana Gempa Bumi Yapen-Waropen Tahun 2010-2011');
