INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5732, 'perka-1-2012', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN UMUM DESA/KELURAHAN TANGGUH BENCANA.
Pasal l Pedoman Desa/Kelurahan Tangguh Bencana merupakan panduan bagi Pemerintah dan/atau Pemerintah Daerah dalam melaksanakan pengembangan Desa/ Kelurahan Tangguh Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5732, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN UMUM DESA/KELURAHAN TANGGUH BENCANA.
Pasal l Pedoman Desa/Kelurahan Tangguh Bencana merupakan panduan bagi Pemerintah dan/atau Pemerintah Daerah dalam melaksanakan pengembangan Desa/ Kelurahan Tangguh Bencana.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2012 tentang Pedoman Umum Desa/Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5733, 'perka-1-2012', 4, 'menetapkan', 'Isi hal. 3', NULL, 3, 'Pasal 2 Pedoman dimaksud dalam Pasal 1 sebagaimana tercantum dalam lampiran Peraturan Kepala ini, merupakan bagian tak terpisahkan dari Peraturan Kepala ini.
Pasal 3 Peraturan Kepala ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5733, 'Pasal 2 Pedoman dimaksud dalam Pasal 1 sebagaimana tercantum dalam lampiran Peraturan Kepala ini, merupakan bagian tak terpisahkan dari Peraturan Kepala ini.
Pasal 3 Peraturan Kepala ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Isi hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2012 tentang Pedoman Umum Desa/Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5734, 'perka-1-2012', 5, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 10 Januari 2012 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 11 Agustus 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN www.peraturan.go.id 2014, No.1095 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5734, 'Ditetapkan di Jakarta pada tanggal 10 Januari 2012 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 11 Agustus 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN www.peraturan.go.id 2014, No.1095 4', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2012 tentang Pedoman Umum Desa/Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5735, 'perka-1-2012', 6, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 1 TAHUN 2012 TENTANG PEDOMAN UMUM DESA/KELURAHAN TANGGUH BENCANA BABI PENDAHULUAN A. Latar Belakang Wilayah Negara Kesatuan Republik Indonesia memiliki kondisi geologis, geografis, hidrologis, demografis dan sosiologis yang menjadikannya rawan terhadap bencana, baik bencana alam, non-alam, maupun bencana sosial. Data dan Informasi Bencana Indonesia (DIBI) BNPB (http: / /dibi.bnpb.go.id/) menunjukkan bahwa jumlah kejadian bencana dan korban meninggal per jenis kejadian bencana dalam periode antara tahun 1815-2011 terus meningkat. Dapat dikatakan bahwa dalam dua abad terakhir ini Indonesia telah mengalami ribuan bencana geologis maupun hidrometeorologis yang menimbulkan ratusan ribu korban jiwa manusia.
Bencana telah menghancurkan hasil-hasil pembangunan yang diperoleh dengan susah payah. Dana yang digunakan untuk tanggap darurat dan pemulihan pasca bencana juga telah mengurangi anggaran yang seharusnya dapat dimanfaatkan untuk pembangunan nasional dan program-program pemberantasan kemiskinan.
Jika terjadi bencana, masyarakat miskin dan kaum marjinal yang tinggal di kawasan rawan akan menjadi pihak yang paling dirugikan, karena jumlah korban terbesar biasanya berasal dari kelompok ini dan pemiskinan yang ditimbulkan oleh bencana sebagian besar akan menimpa mereka.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5735, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 1 TAHUN 2012 TENTANG PEDOMAN UMUM DESA/KELURAHAN TANGGUH BENCANA BABI PENDAHULUAN A. Latar Belakang Wilayah Negara Kesatuan Republik Indonesia memiliki kondisi geologis, geografis, hidrologis, demografis dan sosiologis yang menjadikannya rawan terhadap bencana, baik bencana alam, non-alam, maupun bencana sosial. Data dan Informasi Bencana Indonesia (DIBI) BNPB (http: / /dibi.bnpb.go.id/) menunjukkan bahwa jumlah kejadian bencana dan korban meninggal per jenis kejadian bencana dalam periode antara tahun 1815-2011 terus meningkat. Dapat dikatakan bahwa dalam dua abad terakhir ini Indonesia telah mengalami ribuan bencana geologis maupun hidrometeorologis yang menimbulkan ratusan ribu korban jiwa manusia.
Bencana telah menghancurkan hasil-hasil pembangunan yang diperoleh dengan susah payah. Dana yang digunakan untuk tanggap darurat dan pemulihan pasca bencana juga telah mengurangi anggaran yang seharusnya dapat dimanfaatkan untuk pembangunan nasional dan program-program pemberantasan kemiskinan.
Jika terjadi bencana, masyarakat miskin dan kaum marjinal yang tinggal di kawasan rawan akan menjadi pihak yang paling dirugikan, karena jumlah korban terbesar biasanya berasal dari kelompok ini dan pemiskinan yang ditimbulkan oleh bencana sebagian besar akan menimpa mereka.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2012 tentang Pedoman Umum Desa/Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5736, 'perka-1-2012', 7, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'Mengingat korban terbesar dari bencana adalah kaum miskin di tingkat masyarakat dan yang pertama-tama menghadapi bencana adalah masyarakat sendiri, pemerintah mengembangkan program pengurangan risiko bencana berbasis komunitas, sesuai dengan tanggung-jawab negara untuk melindungi segenap bangsa dan seluruh tumpah darah Indonesia sebagaimana diamanatkan dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945. Salah satu strategi yang akan digunakan untuk mewujudkan ini adalah melalui pengembangan desa-desa dan kelurahan-kelurahan yang tangguh terhadap bencana. Pengembangan Desa/Kelurahan Tangguh Bencana juga sejalan dengan Visi Badan Nasional Penanggulangan Bencana: "Ketangguhan bangsa dalam menghadapi bencana".
Upaya pengurangan risiko bencana berbasis komunitas yang akan dilaksanakan melalui pengembangan Desa/Kelurahan Tangguh Bencana perlu dipadukan ke dalam perencanaan dan praktik pembangunan reguler. Agar pemerintah, terutama di tingkat kabupaten dan kota, dapat melaksanakan program pengembangan Desa/Kelurahan Tangguh Bencana dan memadukannya sebagai bagian dari Rencana Pembangunan Jangka Menengah Kabupaten/Kota, dibutuhkan adanya pedoman umum yang akan menjadi acuan pelaksanaannya.
B. Tujuan
1. Memberikan panduan bagi pemerintah dan/atau pemerintah daerah dalam mengembangkan Desa/Kelurahan Tangguh Bencana sebagai bagian dari upaya untuk melaksanakan pengurangan risiko bencana berbasis masyarakat.
5 2014, No.1095');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5736, 'Mengingat korban terbesar dari bencana adalah kaum miskin di tingkat masyarakat dan yang pertama-tama menghadapi bencana adalah masyarakat sendiri, pemerintah mengembangkan program pengurangan risiko bencana berbasis komunitas, sesuai dengan tanggung-jawab negara untuk melindungi segenap bangsa dan seluruh tumpah darah Indonesia sebagaimana diamanatkan dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945. Salah satu strategi yang akan digunakan untuk mewujudkan ini adalah melalui pengembangan desa-desa dan kelurahan-kelurahan yang tangguh terhadap bencana. Pengembangan Desa/Kelurahan Tangguh Bencana juga sejalan dengan Visi Badan Nasional Penanggulangan Bencana: "Ketangguhan bangsa dalam menghadapi bencana".
Upaya pengurangan risiko bencana berbasis komunitas yang akan dilaksanakan melalui pengembangan Desa/Kelurahan Tangguh Bencana perlu dipadukan ke dalam perencanaan dan praktik pembangunan reguler. Agar pemerintah, terutama di tingkat kabupaten dan kota, dapat melaksanakan program pengembangan Desa/Kelurahan Tangguh Bencana dan memadukannya sebagai bagian dari Rencana Pembangunan Jangka Menengah Kabupaten/Kota, dibutuhkan adanya pedoman umum yang akan menjadi acuan pelaksanaannya.
B. Tujuan
1. Memberikan panduan bagi pemerintah dan/atau pemerintah daerah dalam mengembangkan Desa/Kelurahan Tangguh Bencana sebagai bagian dari upaya untuk melaksanakan pengurangan risiko bencana berbasis masyarakat.
5 2014, No.1095', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2012 tentang Pedoman Umum Desa/Kelurahan Tangguh Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5737, 'perka-1-2012', 8, 'lampiran', 'Lampiran hal. 5', NULL, 5, '2. Memberikan acuan bagi pelaksanaan pengembangan Desa/Kelurahan Tangguh Bencana bagi aparatur pelaksana dan pemangku kepentingan PRB C. Landasan Hukum
1. Undang-Undang Dasar Republik Indonesia Tahun 1945, Pembukaan,
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana,
3. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah,
