INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5779, 'perka-1-2014', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka pengelolaan arsip dinamis dan kemudahan akses arsip bagi publik serta perlindungan terhadap keamanannya maka perlu adanya klasifikasi atau pembatasan terhadap akses arsip dinamis di Lingkungan Badan Nasional Penanggulangan Bencana;
