INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5779, 'a. bahwa dalam rangka pengelolaan arsip dinamis dan kemudahan akses arsip bagi publik serta perlindungan terhadap keamanannya maka perlu adanya klasifikasi atau pembatasan terhadap akses arsip dinamis di Lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Petunjuk Pelaksanaan Klasifikasi Keamanan dan Akses Arsip Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2014 tentang Petunjuk Pelaksanaan Klasifikasi Keamanan dan Akses Arsip Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5780, 'perka-1-2014', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 58, www.djpp.kemenkumham.go.id 2014, No.205 2 Tambahan Lembaran Negara Republik Indonesia Nomor 4843);
