INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5781, 'perka-1-2014', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PETUNJUK PELAKSANAAN KLASIFIKASI KEAMANAN DAN AKSES ARSIP DINAMIS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5781, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PETUNJUK PELAKSANAAN KLASIFIKASI KEAMANAN DAN AKSES ARSIP DINAMIS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2014 tentang Petunjuk Pelaksanaan Klasifikasi Keamanan dan Akses Arsip Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5782, 'perka-1-2014', 4, 'pasal', 'Pasal 1', NULL, 3, 'Petunjuk Pelaksanaan Klasifikasi Keamanan dan Akses Arsip Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana adalah sebagaimana tercantum dalam Lampiran Peraturan ini yang merupakan bagian yang tidak terpisahkan dari Peraturan Kepala Badan Nasional Penanggulangan Bencana ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5782, 'Petunjuk Pelaksanaan Klasifikasi Keamanan dan Akses Arsip Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana adalah sebagaimana tercantum dalam Lampiran Peraturan ini yang merupakan bagian yang tidak terpisahkan dari Peraturan Kepala Badan Nasional Penanggulangan Bencana ini.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2014 tentang Petunjuk Pelaksanaan Klasifikasi Keamanan dan Akses Arsip Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5783, 'perka-1-2014', 5, 'pasal', 'Pasal 2', NULL, 3, 'Petunjuk Pelaksanaan Klasifikasi Keamanan dan Akses Arsip Dinamis di Lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 1 dipergunakan sebagai acuan dalam rangka menyediakan layanan informasi arsip dinamis kepada publik dengan prinsip cepat, tepat, murah, dan aman.');
