INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5787, 'perka-1-2015', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa berdasarkan ketentuan Pasal 9 ayat (1) Peraturan Menteri Tenaga Kerja dan Transmigrasi Nomor 5 Tahun 2012 tentang Sistem Standardisasi Kompetensi Kerja Nasional Indonesia, penerapannya dilakukan oleh Instansi Teknis yang mengusulkan;
b. bahwa berdasarkan ketentuan Pasal 4 ayat (2) huruf c Peraturan Menteri Tenaga Kerja dan Transmigrasi Nomor 8 Tahun 2012 tentang Tata Cara Penetapan Standar Kompetensi Kerja Nasional Indonesia, penetapan dan pemberlakuannya dilakukan oleh Instansi Teknis yang mengembangkan;
c. bahwa berdasarkan Keputusan Menteri Ketenagakerjaan Nomor 401 Tahun 2014 telah ditetapkan Penetapan Standar Kompetensi Kerja 2015, No.182 2 Nasional Indonesia Kategori Administrasi Pemerintahan Pertahanan dan Jaminan Sosial Wajib Golongan Pokok Administrasi Pemerintahan Pertahanan dan Jaminan Sosial Wajib Bidang Penanggulangan Bencana;
d. bahwa berdasarkan pertimbangan sebagaimana dimaksud pada huruf a, huruf b, dan huruf c, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Penetapan dan Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana;');
