INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5794, 'perka-1-2015', 8, 'pasal', 'Pasal 5', 'BAB III PENETAPAN DAN PEMBERLAKUAN STANDAR KOMPETENSI KERJA NASIONAL INDONESIA BIDANG PENANGGULANGAN BENCANA', 9, 'Kepala BNPB melakukan pembinaan dan pengendalian operasional SKKNI-PB sesuai dengan otoritasnya dan dikoordinasikan dengan Menteri yang menyelenggarakan urusan pemerintahan di bidang ketenagakerjaan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5794, 'Kepala BNPB melakukan pembinaan dan pengendalian operasional SKKNI-PB sesuai dengan otoritasnya dan dikoordinasikan dengan Menteri yang menyelenggarakan urusan pemerintahan di bidang ketenagakerjaan;', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2015 tentang Penetapan dan Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5795, 'perka-1-2015', 9, 'pasal', 'Pasal 6', 'BAB IV KETENTUAN PENUTUP', 9, '(1) SKKNI-PB sebagaimana dimaksud dalam Pasal 4 wajib diberlakukan dan dilaksanakan secara nasional;
(2) Peraturan ini juga berlaku untuk tenaga kerja asing yang melakukan kegiatan penanggulangan bencana di Indonesia;
(3) BNPB selaku pengembang SKKNI-PB mengembangkan kompetensi kerja bidang penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5795, '(1) SKKNI-PB sebagaimana dimaksud dalam Pasal 4 wajib diberlakukan dan dilaksanakan secara nasional;
(2) Peraturan ini juga berlaku untuk tenaga kerja asing yang melakukan kegiatan penanggulangan bencana di Indonesia;
(3) BNPB selaku pengembang SKKNI-PB mengembangkan kompetensi kerja bidang penanggulangan bencana.', 'Pasal 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2015 tentang Penetapan dan Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5796, 'perka-1-2015', 10, 'pasal', 'Pasal 7', 'BAB IV KETENTUAN PENUTUP', 9, 'Peraturan Kepala BNPB ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala BNPB ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5796, 'Peraturan Kepala BNPB ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala BNPB ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2015 tentang Penetapan dan Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5797, 'perka-1-2015', 11, 'lain', 'Penutup', NULL, 9, 'Ditetapkan di Jakarta pada tanggal 5 Januari 2015 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 4 Febuari 2015 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5797, 'Ditetapkan di Jakarta pada tanggal 5 Januari 2015 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 4 Febuari 2015 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2015 tentang Penetapan dan Pemberlakuan Standar Kompetensi Kerja Nasional Indonesia Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5798, 'perka-1-2016', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5798, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5799, 'perka-1-2016', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk melaksanakan ketentuan Pasal 10 Peraturan Presiden Nomor 86 Tahun 2016 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pelaksanaan Pemberian Tunjangan Kinerja bagi Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pelaksanaan Pemberian Tunjangan Kinerja bagi Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5799, 'a. bahwa untuk melaksanakan ketentuan Pasal 10 Peraturan Presiden Nomor 86 Tahun 2016 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pelaksanaan Pemberian Tunjangan Kinerja bagi Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pelaksanaan Pemberian Tunjangan Kinerja bagi Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2016 tentang Pelaksanaan Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5800, 'perka-1-2016', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 7, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
