INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5841, 'perka-1-2017', 15, 'pasal', 'Pasal 12', 'BAB IX PENUTUP', 8, '(1) Monitoring dan evaluasi pelaksanaan kegiatan penyaluran Bantuan Pemerintah dilakukan oleh tim monitoring dan evaluasi unit kerja eselon II bersama dengan unit sekretariat utama.
(2) Tim monitoring dan evaluasi sebagaimana dimaksud pada ayat (1) melakukan koordinasi dengan penerima Bantuan Pemerintah dalam penyampaian laporan hasil monitoring dan evaluasi kepada Kepala BNPB melalui Sekretaris Utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5841, '(1) Monitoring dan evaluasi pelaksanaan kegiatan penyaluran Bantuan Pemerintah dilakukan oleh tim monitoring dan evaluasi unit kerja eselon II bersama dengan unit sekretariat utama.
