INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5848, 'perka-10-2008', 4, 'pasal', 'Pasal 1', NULL, 2, 'Pedoman Komando Tanggap Darurat Bencana sebagaimana tersebut dalam Lampiran Peraturan ini merupakan pelaksanaan dari Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana yang tidak terpisahkan dari Peraturan ini.');
