INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5849, 'perka-10-2008', 5, 'pasal', 'Pasal 2', NULL, 2, 'Pedoman Komando Tanggap Darurat Bencana sebagaimana dimaksud dalam Pasal 1, dipergunakan sebagai acuan bagi setiap Pelaksana Penanggulangan Bencana.');
