INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5852, 'perka-10-2008', 8, 'lain', 'Penutup', NULL, 2, 'Ditetapkan di Jakarta pada tanggal 17.Desember 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5852, 'Ditetapkan di Jakarta pada tanggal 17.Desember 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5853, 'perka-10-2008', 9, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 10 TAHUN 2008 TANGGAL : 17 DESEMBER 2008 BAB I PENDAHULUAN A. Latar Belakang Bahwa wilayah Negara Kesatuan Republik Indonesia memiliki kondisi geografis, geologis, hidrologis dan demografis yang memungkinkan terjadinya bencana, baik yang disebabkan oleh faktor alam, faktor non alam maupun faktor manusia yang menyebabkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis yang dalam keadaan tertentu dapat menghambat pembangunan nasional.
Bencana alam adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang disebabkan oleh alam antara lain gempa bumi, tsunami, gunung meletus, banjir, kekeringan, angin topan dan tanah longsor. Bencana non alam adalah bencana yang diakibatkan oleh peristiwa atau rangkaian peristiwa non alam yang antara lain berupa kegagalan teknologi, kegagalan modernisasi, epidemi dan wabah penyakit. Bencana sosial adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang diakibatkan oleh manusia yang meliputi konflik sosial antar kelompok atau antar komunitas masyarakat, dan teror.
Dalam penanggulangan bencana perlu adanya koordinasi dan penanganan yang cepat, tepat, efektif, efisien, terpadu dan akuntabel, agar korban jiwa dan kerugian harta benda dapat diminimalisir.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5853, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 10 TAHUN 2008 TANGGAL : 17 DESEMBER 2008 BAB I PENDAHULUAN A. Latar Belakang Bahwa wilayah Negara Kesatuan Republik Indonesia memiliki kondisi geografis, geologis, hidrologis dan demografis yang memungkinkan terjadinya bencana, baik yang disebabkan oleh faktor alam, faktor non alam maupun faktor manusia yang menyebabkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis yang dalam keadaan tertentu dapat menghambat pembangunan nasional.
Bencana alam adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang disebabkan oleh alam antara lain gempa bumi, tsunami, gunung meletus, banjir, kekeringan, angin topan dan tanah longsor. Bencana non alam adalah bencana yang diakibatkan oleh peristiwa atau rangkaian peristiwa non alam yang antara lain berupa kegagalan teknologi, kegagalan modernisasi, epidemi dan wabah penyakit. Bencana sosial adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang diakibatkan oleh manusia yang meliputi konflik sosial antar kelompok atau antar komunitas masyarakat, dan teror.
Dalam penanggulangan bencana perlu adanya koordinasi dan penanganan yang cepat, tepat, efektif, efisien, terpadu dan akuntabel, agar korban jiwa dan kerugian harta benda dapat diminimalisir.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5854, 'perka-10-2008', 10, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'Penanggulangan bencana, khususnya pada saat tanggap darurat bencana harus dilakukan secara cepat, tepat dan dikoordinasikan dalam satu komando. Untuk melaksanakan penanganan tanggap darurat bencana, maka pemerintah/pemerintah daerah yang diwakili oleh Kepala BNPB/BPBD Provinsi/Kabupaten/Kota sesuai dengan kewenangannya dapat menunjuk seorang pejabat sebagai komandan penanganan tanggap darurat bencana sesuai Peraturan Pemerintah nomor 21 Tahun 2008 pasal 47 ayat (2).
Hal ini dimaksudkan sebagai upaya memudahkan akses untuk memerintahkan sektor dalam hal permintaan dan pengerahan sumberdaya manusia, peralatan, logistik, imigrasi, cukai dan karantina, perizinan, pengadaan barang/jasa, pengelolaan dan pertanggung jawaban atas uang dan atau barang, serta penyelamatan.
Untuk melaksanakan kemudahan akses di bidang komando tersebut, maka perlu disusun Pedoman Komando Tanggap Darurat Bencana.
B. Maksud dan Tujuan Pedoman Komando Tanggap Darurat Bencana ini dimaksudkan sebagai panduan BNPB/BPBD, instansi/lembaga/ organisasi terkait, Tentara Nasional Indonesia dan Kepolisian Republik Indonesia dalam penanganan tanggap darurat bencana, serta bertujuan agar semua pihak terkait tersebut dapat melaksanakan tugas penanganan tanggap darurat bencana secara cepat, tepat, efektif, efisien, terpadu dan akuntabel.
C. Landasan Hukum
1. Undang-Undang Dasar 1945, Pembukaan UUD 1945, alinea IV.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5854, 'Penanggulangan bencana, khususnya pada saat tanggap darurat bencana harus dilakukan secara cepat, tepat dan dikoordinasikan dalam satu komando. Untuk melaksanakan penanganan tanggap darurat bencana, maka pemerintah/pemerintah daerah yang diwakili oleh Kepala BNPB/BPBD Provinsi/Kabupaten/Kota sesuai dengan kewenangannya dapat menunjuk seorang pejabat sebagai komandan penanganan tanggap darurat bencana sesuai Peraturan Pemerintah nomor 21 Tahun 2008 pasal 47 ayat (2).
Hal ini dimaksudkan sebagai upaya memudahkan akses untuk memerintahkan sektor dalam hal permintaan dan pengerahan sumberdaya manusia, peralatan, logistik, imigrasi, cukai dan karantina, perizinan, pengadaan barang/jasa, pengelolaan dan pertanggung jawaban atas uang dan atau barang, serta penyelamatan.
Untuk melaksanakan kemudahan akses di bidang komando tersebut, maka perlu disusun Pedoman Komando Tanggap Darurat Bencana.
B. Maksud dan Tujuan Pedoman Komando Tanggap Darurat Bencana ini dimaksudkan sebagai panduan BNPB/BPBD, instansi/lembaga/ organisasi terkait, Tentara Nasional Indonesia dan Kepolisian Republik Indonesia dalam penanganan tanggap darurat bencana, serta bertujuan agar semua pihak terkait tersebut dapat melaksanakan tugas penanganan tanggap darurat bencana secara cepat, tepat, efektif, efisien, terpadu dan akuntabel.
C. Landasan Hukum
1. Undang-Undang Dasar 1945, Pembukaan UUD 1945, alinea IV.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5855, 'perka-10-2008', 11, 'lampiran', 'Lampiran hal. 4', NULL, 4, '2. Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana pasal 15 ayat (2), pasal 23 ayat (2), 50 ayat (1), pasal 77 dan pasal 78.
3. Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008, tentang Badan Nasional Penanggulangan Bencana.
4. Peraturan Pemerintah Republik Indonesia Nomor 21 Tahun 2008, tentang Penyelenggaraan Penanggulangan Bencana pasal 24, pasal 25, 26, 27, 47, 48, 49 dan pasal 50.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Penyelenggaraan penanggulanggan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
3. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan pengurusan pengungsi, penyelamatan, serta pemulihan prasarana dan sarana.
4. Korban bencana adalah orang atau kelompok orang yang menderita atau meninggal dunia akibat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5855, '2. Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana pasal 15 ayat (2), pasal 23 ayat (2), 50 ayat (1), pasal 77 dan pasal 78.
3. Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008, tentang Badan Nasional Penanggulangan Bencana.
4. Peraturan Pemerintah Republik Indonesia Nomor 21 Tahun 2008, tentang Penyelenggaraan Penanggulangan Bencana pasal 24, pasal 25, 26, 27, 47, 48, 49 dan pasal 50.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Penyelenggaraan penanggulanggan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
3. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan pengurusan pengungsi, penyelamatan, serta pemulihan prasarana dan sarana.
4. Korban bencana adalah orang atau kelompok orang yang menderita atau meninggal dunia akibat bencana.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5856, 'perka-10-2008', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, '5. Sistem Komando Tanggap Darurat Bencana adalah suatu sistem penanganan darurat bencana yang digunakan oleh semua instansi/lembaga dengan mengintegrasikan pemanfaatan sumberdaya manusia, peralatan dan anggaran.
6. Tim Reaksi Cepat BNPB/BPBD adalah tim yang ditugaskan oleh Kepala BNPB/BPBD sesuai dengan kewenangannya untuk melakukan kegiatan kaji cepat bencana dan dampak bencana, serta memberikan dukungan pendampingan dalam rangka penanganan darurat bencana.
7. Komando Tanggap Darurat Bencana adalah organisasi penanganan tanggap darurat bencana yang dipimpin oleh seorang Komandan Tanggap Darurat Bencana dan dibantu oleh Staf Komando dan Staf Umum, memiliki struktur organisasi standar yang menganut satu komando dengan mata rantai dan garis komando yang jelas dan memiliki satu kesatuan komando dalam mengkoordinasikan instansi/lembaga/organisasi terkait untuk pengerahan sumberdaya.
8. Staf Komando adalah pembantu Komandan Tanggap Darurat Bencana dalam menjalankan urusan sekretariat, hubungan masyarakat, perwakilan instansi/lembaga serta keselamatan dan keamanan.
9. Staf Umum adalah pembantu Komandan Tanggap Darurat Bencana dalam menjalankan fungsi utama komando untuk bidang operasi, bidang perencanaan, bidang logistik dan peralatan serta bidang administrasi keuangan untuk penanganan tanggap darurat bencana yang terjadi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5856, '5. Sistem Komando Tanggap Darurat Bencana adalah suatu sistem penanganan darurat bencana yang digunakan oleh semua instansi/lembaga dengan mengintegrasikan pemanfaatan sumberdaya manusia, peralatan dan anggaran.
6. Tim Reaksi Cepat BNPB/BPBD adalah tim yang ditugaskan oleh Kepala BNPB/BPBD sesuai dengan kewenangannya untuk melakukan kegiatan kaji cepat bencana dan dampak bencana, serta memberikan dukungan pendampingan dalam rangka penanganan darurat bencana.
7. Komando Tanggap Darurat Bencana adalah organisasi penanganan tanggap darurat bencana yang dipimpin oleh seorang Komandan Tanggap Darurat Bencana dan dibantu oleh Staf Komando dan Staf Umum, memiliki struktur organisasi standar yang menganut satu komando dengan mata rantai dan garis komando yang jelas dan memiliki satu kesatuan komando dalam mengkoordinasikan instansi/lembaga/organisasi terkait untuk pengerahan sumberdaya.
8. Staf Komando adalah pembantu Komandan Tanggap Darurat Bencana dalam menjalankan urusan sekretariat, hubungan masyarakat, perwakilan instansi/lembaga serta keselamatan dan keamanan.
9. Staf Umum adalah pembantu Komandan Tanggap Darurat Bencana dalam menjalankan fungsi utama komando untuk bidang operasi, bidang perencanaan, bidang logistik dan peralatan serta bidang administrasi keuangan untuk penanganan tanggap darurat bencana yang terjadi.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5857, 'perka-10-2008', 13, 'lampiran', 'Lampiran hal. 5', NULL, 5, '10. Fasilitas Komando Tanggap Darurat Bencana adalah personil, sarana dan prasarana pendukung penyelenggaraan penanganan tanggap darurat bencana yang dapat terdiri dari Pusat Komando, Personil Komando, gudang, sarana dan prasarana transportasi, peralatan, sarana dan prasarana komunikasi serta informasi.
E. Sistematika Pedoman Komando Tanggap Darurat Bencana ini disusun dengan sistematika sebagai berikut:
I. PENDAHULUAN
II. TAHAPAN PEMBENTUKAN KOMANDO TANGGAP DARURAT BENCANA
III. ORGANISASI DAN TATA KERJA KOMANDO TANGGAP DARURAT BENCANA
IV. POLA PENYELENGGARAN SISTEM KOMANDO TANGGAP DARURAT BENCANA
V. EVALUASI DAN PELAPORAN
VI. PENUTUP.
BAB II TAHAPAN PEMBENTUKAN KOMANDO TANGGAP DARURAT BENCANA Terbentuknya Komando Tanggap Darurat Bencana meliputi tahapan yang terdiri dari: ♦ Informasi Kejadian Awal ♦ Penugasan Tim Reaksi Cepat (TRC) ♦ Penetapan Status/Tingkat Bencana ♦ Pembentukan Komando Tanggap Darurat Bencana Tahapan pembentukan Komando Tanggap Darurat Bencana tersebut harus dilaksanakan secara keseluruhan menjadi satu rangkaian sistem komando yang terpadu. Rincian masing-masing tahapan tersebut adalah:
A. Informasi Kejadian Awal Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5857, '10. Fasilitas Komando Tanggap Darurat Bencana adalah personil, sarana dan prasarana pendukung penyelenggaraan penanganan tanggap darurat bencana yang dapat terdiri dari Pusat Komando, Personil Komando, gudang, sarana dan prasarana transportasi, peralatan, sarana dan prasarana komunikasi serta informasi.
E. Sistematika Pedoman Komando Tanggap Darurat Bencana ini disusun dengan sistematika sebagai berikut:
I. PENDAHULUAN
II. TAHAPAN PEMBENTUKAN KOMANDO TANGGAP DARURAT BENCANA
III. ORGANISASI DAN TATA KERJA KOMANDO TANGGAP DARURAT BENCANA
IV. POLA PENYELENGGARAN SISTEM KOMANDO TANGGAP DARURAT BENCANA
V. EVALUASI DAN PELAPORAN
VI. PENUTUP.
BAB II TAHAPAN PEMBENTUKAN KOMANDO TANGGAP DARURAT BENCANA Terbentuknya Komando Tanggap Darurat Bencana meliputi tahapan yang terdiri dari: ♦ Informasi Kejadian Awal ♦ Penugasan Tim Reaksi Cepat (TRC) ♦ Penetapan Status/Tingkat Bencana ♦ Pembentukan Komando Tanggap Darurat Bencana Tahapan pembentukan Komando Tanggap Darurat Bencana tersebut harus dilaksanakan secara keseluruhan menjadi satu rangkaian sistem komando yang terpadu. Rincian masing-masing tahapan tersebut adalah:
A. Informasi Kejadian Awal Bencana', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5858, 'perka-10-2008', 14, 'lampiran', 'Lampiran hal. 7', NULL, 7, '1. Informasi awal kejadian bencana diperoleh melalui berbagai sumber antara lain pelaporan, media massa, instansi/lembaga terkait, masyarakat, internet, dan informasi lain yang dapat dipercaya. BNPB dan/atau BPBD melakukan klarifikasi kepada instansi/lembaga/masyarakat di lokasi bencana. Informasi yang diperoleh dengan menggunakan rumusan pertanyaan terkait bencana yang terjadi, terdiri dari:
a. Apa : jenis bencana
b. Bilamana : hari, tanggal, bulan, tahun, jam, waktu setempat
c. Dimana : tempat/lokasi/daerah bencana
d. Berapa : jumlah korban, kerusakan sarana dan prasarana
e. Penyebab : penyebab terjadinya bencana
f. Bagaimana : upaya yang telah dilakukan
2. Penjelasan rumusan pertanyaan informasi kejadian awal yang harus dikumpulkan dapat dilihat pada Lampiran-1 pedoman ini.
B. Penugasan Tim Reaksi Cepat (TRC)
1. Dari informasi kejadian awal yang diperoleh, BNPB dan/atau BPBD menugaskan Tim Reaksi Cepat (TRC) tanggap darurat bencana, untuk melaksanakan tugas pengkajian secara cepat, tepat, dan dampak bencana, serta serta memberikan dukungan pendampingan dalam rangka penanganan darurat bencana.
2. Hasil pelaksanaan tugas TRC tanggap darurat dan masukan dari berbagai instansi/lembaga terkait merupakan bahan pertimbangan bagi :
a. Kepala BPBD Kabupaten/Kota untuk mengusulkan kepada Bupati/Walikota dalam rangka menetapkan status/tingkat bencana skala kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5858, '1. Informasi awal kejadian bencana diperoleh melalui berbagai sumber antara lain pelaporan, media massa, instansi/lembaga terkait, masyarakat, internet, dan informasi lain yang dapat dipercaya. BNPB dan/atau BPBD melakukan klarifikasi kepada instansi/lembaga/masyarakat di lokasi bencana. Informasi yang diperoleh dengan menggunakan rumusan pertanyaan terkait bencana yang terjadi, terdiri dari:
a. Apa : jenis bencana
b. Bilamana : hari, tanggal, bulan, tahun, jam, waktu setempat
c. Dimana : tempat/lokasi/daerah bencana
d. Berapa : jumlah korban, kerusakan sarana dan prasarana
e. Penyebab : penyebab terjadinya bencana
f. Bagaimana : upaya yang telah dilakukan
2. Penjelasan rumusan pertanyaan informasi kejadian awal yang harus dikumpulkan dapat dilihat pada Lampiran-1 pedoman ini.
B. Penugasan Tim Reaksi Cepat (TRC)
1. Dari informasi kejadian awal yang diperoleh, BNPB dan/atau BPBD menugaskan Tim Reaksi Cepat (TRC) tanggap darurat bencana, untuk melaksanakan tugas pengkajian secara cepat, tepat, dan dampak bencana, serta serta memberikan dukungan pendampingan dalam rangka penanganan darurat bencana.
2. Hasil pelaksanaan tugas TRC tanggap darurat dan masukan dari berbagai instansi/lembaga terkait merupakan bahan pertimbangan bagi :
a. Kepala BPBD Kabupaten/Kota untuk mengusulkan kepada Bupati/Walikota dalam rangka menetapkan status/tingkat bencana skala kabupaten/kota.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5859, 'perka-10-2008', 15, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'b. Kepala BPBD Provinsi untuk mengusulkan kepada Gubernur dalam rangka menetapkan status/tingkat bencana skala provinsi.
c. Kepala BNPB untuk mengusulkan kepada Presiden RI dalam rangka menetapkan status/tingkat bencana skala nasional.
C. Penetapan Status / Tingkat Bencana
1. Berdasarkan usul sesuai butir B.2 di atas dan berbagai masukan yang dapat dipertanggung jawabkan dalam forum rapat dengan instansi/lembaga terkait, maka :
a. Bupati/Walikota menetapkan status/tingkat bencana skala kabupaten/kota.
b. Gubernur menetapkan status/tingkat bencana skala provinsi.
c. Presiden RI menetapkan status/tingkat bencana skala nasional.
2. Tindak lanjut dari penetapan status/tingkat bencana tersebut, maka Kepala BNPB/BPBD Provinsi/BPBD Kabupaten/Kota sesuai dengan kewenangannya menunjuk seorang pejabat sebagai komandan penanganan tanggap darurat bencana sesuai status/tingkat bencana skala nasional/daerah.
D. Pembentukan Komando Tanggap Darurat Bencana
1. Kepala BNPB/BPBD Provinsi/BPBD Kabupaten/Kota sesuai status/tingkat bencana dan tingkat kewenangannya :
a. Mengeluarkan Surat Keputusan pembentukan Komando Tanggap Darurat Bencana.
b. Melaksanakan mobilisasi sumberdaya manusia, peralatan dan logistik serta dana dari instansi/lembaga terkait dan/atau masyarakat.
c. Meresmikan pembentukan Komando Tanggap Darurat Bencana.
2. Ilustrasi pembentukan Komando Tanggap Darurat Bencana dapat dilihat pada Lampiran-2.
BAB III ORGANISASI DAN TATA KERJA KOMANDO TANGGAP DARURAT BENCANA A. Organisasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5859, 'b. Kepala BPBD Provinsi untuk mengusulkan kepada Gubernur dalam rangka menetapkan status/tingkat bencana skala provinsi.
c. Kepala BNPB untuk mengusulkan kepada Presiden RI dalam rangka menetapkan status/tingkat bencana skala nasional.
C. Penetapan Status / Tingkat Bencana
1. Berdasarkan usul sesuai butir B.2 di atas dan berbagai masukan yang dapat dipertanggung jawabkan dalam forum rapat dengan instansi/lembaga terkait, maka :
a. Bupati/Walikota menetapkan status/tingkat bencana skala kabupaten/kota.
b. Gubernur menetapkan status/tingkat bencana skala provinsi.
c. Presiden RI menetapkan status/tingkat bencana skala nasional.
2. Tindak lanjut dari penetapan status/tingkat bencana tersebut, maka Kepala BNPB/BPBD Provinsi/BPBD Kabupaten/Kota sesuai dengan kewenangannya menunjuk seorang pejabat sebagai komandan penanganan tanggap darurat bencana sesuai status/tingkat bencana skala nasional/daerah.
D. Pembentukan Komando Tanggap Darurat Bencana
1. Kepala BNPB/BPBD Provinsi/BPBD Kabupaten/Kota sesuai status/tingkat bencana dan tingkat kewenangannya :
a. Mengeluarkan Surat Keputusan pembentukan Komando Tanggap Darurat Bencana.
b. Melaksanakan mobilisasi sumberdaya manusia, peralatan dan logistik serta dana dari instansi/lembaga terkait dan/atau masyarakat.
c. Meresmikan pembentukan Komando Tanggap Darurat Bencana.
2. Ilustrasi pembentukan Komando Tanggap Darurat Bencana dapat dilihat pada Lampiran-2.
BAB III ORGANISASI DAN TATA KERJA KOMANDO TANGGAP DARURAT BENCANA A. Organisasi', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5860, 'perka-10-2008', 16, 'lampiran', 'Lampiran hal. 9', NULL, 9, '1. Organisasi Komando Tanggap Darurat Bencana merupakan organisasi satu komando, dengan mata rantai dan garis komando serta tanggung jawab yang jelas. Instansi/lembaga dapat dikoordinasikan dalam satu organisasi berdasarkan satu kesatuan komando. Organisasi ini dapat dibentuk di semua tingkatan wilayah bencana baik di tingkat kabupaten/kota, provinsi maupun tingkat nasional.
2. Struktur organisasi komando tanggap darurat terdiri atas Komandan yang dibantu oleh staf komando dan staf umum, secara lengkap terdiri dari:
a. Komandan Tanggap Darurat Bencana
b. Wakil Komandan Tanggap Darurat Bencana
c. Staf Komando:
1) Sekretariat 2) Hubungan Masyarakat 3) Keselamatan dan Keamanan 4) Perwakilan instansi/lembaga
d. Staf Umum:
1) Bidang Operasi 2) Bidang Perencanaan 3) Bidang Logistik dan Peralatan 4) Bidang Administrasi Keuangan
3. Struktur organisasi ini merupakan organisasi standar dan dapat diperluas berdasarkan kebutuhan.
4. Sesuai dengan jenis, kebutuhan dan kompleksitas bencana dapat dibentuk unit organisasi dalam bentuk seksi-seksi yang berada di bawah bidang dan dipimpin oleh Kepala Seksi yang bertanggung jawab kepada Kepala Bidang.
5. Bagan struktur organisasi Komando Tanggap Darurat Bencana dapat dilihat pada Lampiran-3, 4 dan 5 sesuai dengan lokasi dan tingkatan bencana.
B. Tugas Pokok dan Fungsi Organisasi
1. Komando Tanggap Darurat Bencana memiliki tugas pokok untuk:
a. Merencanakan operasi penanganan tanggap darurat bencana.
b. Mengajukan permintaan kebutuhan bantuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5860, '1. Organisasi Komando Tanggap Darurat Bencana merupakan organisasi satu komando, dengan mata rantai dan garis komando serta tanggung jawab yang jelas. Instansi/lembaga dapat dikoordinasikan dalam satu organisasi berdasarkan satu kesatuan komando. Organisasi ini dapat dibentuk di semua tingkatan wilayah bencana baik di tingkat kabupaten/kota, provinsi maupun tingkat nasional.
2. Struktur organisasi komando tanggap darurat terdiri atas Komandan yang dibantu oleh staf komando dan staf umum, secara lengkap terdiri dari:
a. Komandan Tanggap Darurat Bencana
b. Wakil Komandan Tanggap Darurat Bencana
c. Staf Komando:
1) Sekretariat 2) Hubungan Masyarakat 3) Keselamatan dan Keamanan 4) Perwakilan instansi/lembaga
d. Staf Umum:
1) Bidang Operasi 2) Bidang Perencanaan 3) Bidang Logistik dan Peralatan 4) Bidang Administrasi Keuangan
3. Struktur organisasi ini merupakan organisasi standar dan dapat diperluas berdasarkan kebutuhan.
4. Sesuai dengan jenis, kebutuhan dan kompleksitas bencana dapat dibentuk unit organisasi dalam bentuk seksi-seksi yang berada di bawah bidang dan dipimpin oleh Kepala Seksi yang bertanggung jawab kepada Kepala Bidang.
5. Bagan struktur organisasi Komando Tanggap Darurat Bencana dapat dilihat pada Lampiran-3, 4 dan 5 sesuai dengan lokasi dan tingkatan bencana.
B. Tugas Pokok dan Fungsi Organisasi
1. Komando Tanggap Darurat Bencana memiliki tugas pokok untuk:
a. Merencanakan operasi penanganan tanggap darurat bencana.
b. Mengajukan permintaan kebutuhan bantuan.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5861, 'perka-10-2008', 17, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'c. Melaksanakan dan mengkoordinasikan pengerahan sumberdaya untuk penanganan tanggap darurat bencana secara cepat tepat, efisien dan efektif.
d. Melaksanakan pengumpulan informasi dengan menggunakan rumusan pertanyaan (lihat Lampiran-1), sebagai dasar perencanaan Komando Tanggap Darurat Bencana tingkat kabupaten/kota/provinsi/nasional.
e. Menyebarluaskan informasi mengenai kejadian bencana dan pananganannya kepada media massa dan masyarakat luas.
2. Fungsi Komando Tanggap Darurat Bencana adalah mengkoordinasikan, mengintegrasikan dan mensinkronisasikan seluruh unsur dalam organisasi komando tanggap darurat untuk penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan pengurusan pengungsi, penyelamatan serta pemulihan sarana dan prasarana dengan segera pada saat kejadian bencana.
C. Tugas dan Tanggung Jawab Unit Organisasi
1. Komandan Tanggap Darurat Bencana
a. Komandan Tanggap Darurat Bencana adalah personil dengan pangkat/jabatan senior peringkat pertama dalam Komando Tanggap Darurat Bencana sesuai tingkat dan kewenangannya.
b. Komandan bertugas:
1) Mengaktifkan dan meningkatkan Pusat Pengendalian Operasi (Pusdalops) menjadi Pos Komando Tanggap Darurat BPBD Kabupaten/Kota/Provinsi atau BNPB, sesuai dengan jenis, lokasi dan tingkatan bencana.
2) Membentuk Pos Komando Lapangan (Poskolap) di lokasi bencana di bawah komando Pos Komando Tanggap Darurat Bencana BPBD Kabupaten/Kota/Provinsi atau BNPB. Contoh tata letak Poskolap, lihat Lampiran-6.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5861, 'c. Melaksanakan dan mengkoordinasikan pengerahan sumberdaya untuk penanganan tanggap darurat bencana secara cepat tepat, efisien dan efektif.
d. Melaksanakan pengumpulan informasi dengan menggunakan rumusan pertanyaan (lihat Lampiran-1), sebagai dasar perencanaan Komando Tanggap Darurat Bencana tingkat kabupaten/kota/provinsi/nasional.
e. Menyebarluaskan informasi mengenai kejadian bencana dan pananganannya kepada media massa dan masyarakat luas.
2. Fungsi Komando Tanggap Darurat Bencana adalah mengkoordinasikan, mengintegrasikan dan mensinkronisasikan seluruh unsur dalam organisasi komando tanggap darurat untuk penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan pengurusan pengungsi, penyelamatan serta pemulihan sarana dan prasarana dengan segera pada saat kejadian bencana.
C. Tugas dan Tanggung Jawab Unit Organisasi
1. Komandan Tanggap Darurat Bencana
a. Komandan Tanggap Darurat Bencana adalah personil dengan pangkat/jabatan senior peringkat pertama dalam Komando Tanggap Darurat Bencana sesuai tingkat dan kewenangannya.
b. Komandan bertugas:
1) Mengaktifkan dan meningkatkan Pusat Pengendalian Operasi (Pusdalops) menjadi Pos Komando Tanggap Darurat BPBD Kabupaten/Kota/Provinsi atau BNPB, sesuai dengan jenis, lokasi dan tingkatan bencana.
2) Membentuk Pos Komando Lapangan (Poskolap) di lokasi bencana di bawah komando Pos Komando Tanggap Darurat Bencana BPBD Kabupaten/Kota/Provinsi atau BNPB. Contoh tata letak Poskolap, lihat Lampiran-6.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5862, 'perka-10-2008', 18, 'lampiran', 'Lampiran hal. 11', NULL, 11, '3) Membuat rencana strategis dan taktis, mengorganisasikan, melaksanakan dan mengendalikan operasi tanggap darurat bencana.
4) Melaksanakan komando dan pengendalian untuk pengerahan sumber daya manusia, peralatan, logistik dan penyelamatan serta berwenang memerintahkan para pejabat yang mewakili instansi/lembaga/organisasi yang terkait dalam memfasilitasi aksesibilitas penanganan tanggap darurat bencana.
c. Komandan Tanggap Darurat Bencana bertanggung jawab langsung kepada Kepala BNPB/BPBD Provinsi/ Kabupaten/Kota, sesuai dengan tingkat dan kewenangannya.
2. Wakil Komandan Tanggap Darurat Bencana Wakil Komandan Tanggap Darurat Bencana adalah personil dengan pangkat/jabatan senior peringkat kedua dalam Komando Tanggap Darurat Bencana sesuai tingkat dan kewenangannya.
a. Wakil Komandan Tanggap Darurat Bencana bertugas:
1) Membantu Komandan Tanggap Darurat Bencana dalam merencanakan, mengorganisasikan, melaksanakan dan mengendalikan komando tanggap darurat bencana.
2) Mengkoordinir tugas-tugas sekretariat, humas, keselamatan dan keamanan serta perwakilan instansi/lembaga.
3) Mewakili Komandan Tanggap Darurat Bencana, apabila Komandan Tanggap Darurat Bencana berhalangan.
b. Wakil Komandan Tanggap Darurat Bencana bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
3. Sekretariat Sekretariat dipimpin oleh seorang Sekretaris.
a. Sekretaris bertugas dan bertanggung jawab untuk:
1) Menyelenggarakan administrasi umum dan pelaporan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5862, '3) Membuat rencana strategis dan taktis, mengorganisasikan, melaksanakan dan mengendalikan operasi tanggap darurat bencana.
4) Melaksanakan komando dan pengendalian untuk pengerahan sumber daya manusia, peralatan, logistik dan penyelamatan serta berwenang memerintahkan para pejabat yang mewakili instansi/lembaga/organisasi yang terkait dalam memfasilitasi aksesibilitas penanganan tanggap darurat bencana.
c. Komandan Tanggap Darurat Bencana bertanggung jawab langsung kepada Kepala BNPB/BPBD Provinsi/ Kabupaten/Kota, sesuai dengan tingkat dan kewenangannya.
2. Wakil Komandan Tanggap Darurat Bencana Wakil Komandan Tanggap Darurat Bencana adalah personil dengan pangkat/jabatan senior peringkat kedua dalam Komando Tanggap Darurat Bencana sesuai tingkat dan kewenangannya.
a. Wakil Komandan Tanggap Darurat Bencana bertugas:
1) Membantu Komandan Tanggap Darurat Bencana dalam merencanakan, mengorganisasikan, melaksanakan dan mengendalikan komando tanggap darurat bencana.
2) Mengkoordinir tugas-tugas sekretariat, humas, keselamatan dan keamanan serta perwakilan instansi/lembaga.
3) Mewakili Komandan Tanggap Darurat Bencana, apabila Komandan Tanggap Darurat Bencana berhalangan.
b. Wakil Komandan Tanggap Darurat Bencana bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
3. Sekretariat Sekretariat dipimpin oleh seorang Sekretaris.
a. Sekretaris bertugas dan bertanggung jawab untuk:
1) Menyelenggarakan administrasi umum dan pelaporan.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5863, 'perka-10-2008', 19, 'lampiran', 'Lampiran hal. 11', NULL, 11, '2) Pelayanan akomodasi dan konsumsi bagi personil Komando Tanggap Darurat Bencana.
b. Sekretaris bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
4. Hubungan Masyarakat
a. Hubungan Masyarakat bertugas dan bertanggung jawab untuk:
1) Menghimpun data dan informasi penanganan bencana yang terjadi.
2) Membentuk jaringan informasi dan komunikasi serta menyebarkan informasi tentang bencana tersebut ke media massa dan masyarakat luas.
b. Kepala Humas bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
5. Keselamatan dan Keamanan
a. Keselamatan dan Keamanan bertugas dan bertanggung jawab untuk:
1) Menjamin kesehatan dan keselamatan seluruh personil Komando Tanggap Darurat Bencana dalam menjalankan tugasnya.
2) Menjaga keamanan penanganan tanggap darurat bencana serta mengantisipasi hal-hal di luar dugaan atau suatu keadaan yang berbahaya.
b. Kepala Keselamatan dan Keamanan bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
6. Perwakilan Instansi/Lembaga
a. Perwakilan instansi/lembaga bertugas untuk membantu Komandan Tanggap Darurat Bencana berkaitan dengan permintaan dan pengerahan sumberdaya yang dibutuhkan dari instansi/lembaga.
b. Perwakilan instansi/lembaga secara operasional bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana atas pelaksanaan tugasnya dan secara administratif bertanggung jawab kepada pimpinan instansi/lembaga terkait.
7. Bidang Operasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5863, '2) Pelayanan akomodasi dan konsumsi bagi personil Komando Tanggap Darurat Bencana.
b. Sekretaris bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
4. Hubungan Masyarakat
a. Hubungan Masyarakat bertugas dan bertanggung jawab untuk:
1) Menghimpun data dan informasi penanganan bencana yang terjadi.
2) Membentuk jaringan informasi dan komunikasi serta menyebarkan informasi tentang bencana tersebut ke media massa dan masyarakat luas.
b. Kepala Humas bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
5. Keselamatan dan Keamanan
a. Keselamatan dan Keamanan bertugas dan bertanggung jawab untuk:
1) Menjamin kesehatan dan keselamatan seluruh personil Komando Tanggap Darurat Bencana dalam menjalankan tugasnya.
2) Menjaga keamanan penanganan tanggap darurat bencana serta mengantisipasi hal-hal di luar dugaan atau suatu keadaan yang berbahaya.
b. Kepala Keselamatan dan Keamanan bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
6. Perwakilan Instansi/Lembaga
a. Perwakilan instansi/lembaga bertugas untuk membantu Komandan Tanggap Darurat Bencana berkaitan dengan permintaan dan pengerahan sumberdaya yang dibutuhkan dari instansi/lembaga.
b. Perwakilan instansi/lembaga secara operasional bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana atas pelaksanaan tugasnya dan secara administratif bertanggung jawab kepada pimpinan instansi/lembaga terkait.
7. Bidang Operasi', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5864, 'perka-10-2008', 20, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'a. Bidang Operasi bertugas dan bertanggung jawab atas semua pelaksanaan operasi penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan pengurusan pengungsi, penyelamatan, serta pemulihan prasarana dan sarana dengan cepat, tepat, efisien dan efektif berdasarkan satu kesatuan rencana tindakan penanganan tanggap darurat bencana.
b. Kepala Bidang Operasi bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
8. Bidang Perencanaan
a. Bidang Perencanaan bertugas dan bertanggung jawab atas pengumpulan, evaluasi, analisis data dan informasi yang berhubungan dengan penanganan tanggap darurat bencana serta menyiapkan dokumen rencana tindakan operasi tanggap darurat.
b. Kepala Bidang Perencanaan bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
9. Bidang Logistik dan Peralatan
a. Bidang Logistik dan Peralatan bertugas dan bertanggung jawab:
1) Penyediaan fasilitas, jasa, dan bahan-bahan serta perlengkapan tanggap darurat.
2) Melaksanakan penerimaan, penyimpanan, pendistribusian dan transportasi bantuan logistik dan peralatan.
3) Melaksanakan penyelenggaraan dukungan dapur umum, air bersih dan sanitasi umum.
4) Mengkoordinasikan semua bantuan logistik dan peralatan dari instansi/lembaga/organisasi yang terkait.
b. Kepala Bidang Logistik dan Peralatan bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
10. Bidang Administrasi Keuangan
a. Bidang Administrasi Keuangan bertugas dan bertanggung jawab:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5864, 'a. Bidang Operasi bertugas dan bertanggung jawab atas semua pelaksanaan operasi penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan pengurusan pengungsi, penyelamatan, serta pemulihan prasarana dan sarana dengan cepat, tepat, efisien dan efektif berdasarkan satu kesatuan rencana tindakan penanganan tanggap darurat bencana.
b. Kepala Bidang Operasi bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
8. Bidang Perencanaan
a. Bidang Perencanaan bertugas dan bertanggung jawab atas pengumpulan, evaluasi, analisis data dan informasi yang berhubungan dengan penanganan tanggap darurat bencana serta menyiapkan dokumen rencana tindakan operasi tanggap darurat.
b. Kepala Bidang Perencanaan bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
9. Bidang Logistik dan Peralatan
a. Bidang Logistik dan Peralatan bertugas dan bertanggung jawab:
1) Penyediaan fasilitas, jasa, dan bahan-bahan serta perlengkapan tanggap darurat.
2) Melaksanakan penerimaan, penyimpanan, pendistribusian dan transportasi bantuan logistik dan peralatan.
3) Melaksanakan penyelenggaraan dukungan dapur umum, air bersih dan sanitasi umum.
4) Mengkoordinasikan semua bantuan logistik dan peralatan dari instansi/lembaga/organisasi yang terkait.
b. Kepala Bidang Logistik dan Peralatan bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
10. Bidang Administrasi Keuangan
a. Bidang Administrasi Keuangan bertugas dan bertanggung jawab:', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5865, 'perka-10-2008', 21, 'lampiran', 'Lampiran hal. 13', NULL, 13, '1) Melaksanakan semua administrasi keuangan.
2) Menganilisa kebutuhan dana dalam rangka penanganan tanggap darurat bencana yang terjadi.
3) Mendukung keuangan yang dibutuhkan dalam rangka komando tanggap darurat bencana yang terjadi
b. Kepala Bidang Administrasi dan Keuangan bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
BAB IV POLA PENYELENGGARAAN SISTEM KOMANDO TANGGAP DARURAT BENCANA Sistem Komando Tanggap Darurat Bencana diselenggarakan dengan pola yang terdiri atas rencana operasi, permintaan, pengerahan/mobilisasi sumberdaya yang didukung dengan fasilitas komando yang diselenggarakan sesuai dengan jenis, lokasi dan tingkatan bencana.
Penyelenggaraan Sistem Komando Tanggap Darurat Bencana diakhiri oleh pembubaran Komando Tanggap Darurat Bencana.
Penyelenggaraan Sistem Komando Tanggap Darurat Bencana dilaksanakan sebagai berikut:
A. Rencana Operasi
1. Rencana Operasi Komando Tanggap Darurat Bencana berikut Rencana Tindakan Operasi penanganan tanggap darurat bencana, merupakan acuan bagi setiap unsur pelaksana dalam komando.
2. Format Rencana Operasi dapat dilihat pada Lampiran-7.
3. Contoh kegiatan operasi dapat dilihat pada Lampiran-8 B. Permintaan Sumberdaya Mekanisme permintaan sumberdaya untuk penanganan tanggap darurat bencana dilaksanakan sesuai dengan ketentuan sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5865, '1) Melaksanakan semua administrasi keuangan.
2) Menganilisa kebutuhan dana dalam rangka penanganan tanggap darurat bencana yang terjadi.
3) Mendukung keuangan yang dibutuhkan dalam rangka komando tanggap darurat bencana yang terjadi
b. Kepala Bidang Administrasi dan Keuangan bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
BAB IV POLA PENYELENGGARAAN SISTEM KOMANDO TANGGAP DARURAT BENCANA Sistem Komando Tanggap Darurat Bencana diselenggarakan dengan pola yang terdiri atas rencana operasi, permintaan, pengerahan/mobilisasi sumberdaya yang didukung dengan fasilitas komando yang diselenggarakan sesuai dengan jenis, lokasi dan tingkatan bencana.
Penyelenggaraan Sistem Komando Tanggap Darurat Bencana diakhiri oleh pembubaran Komando Tanggap Darurat Bencana.
Penyelenggaraan Sistem Komando Tanggap Darurat Bencana dilaksanakan sebagai berikut:
A. Rencana Operasi
1. Rencana Operasi Komando Tanggap Darurat Bencana berikut Rencana Tindakan Operasi penanganan tanggap darurat bencana, merupakan acuan bagi setiap unsur pelaksana dalam komando.
2. Format Rencana Operasi dapat dilihat pada Lampiran-7.
3. Contoh kegiatan operasi dapat dilihat pada Lampiran-8 B. Permintaan Sumberdaya Mekanisme permintaan sumberdaya untuk penanganan tanggap darurat bencana dilaksanakan sesuai dengan ketentuan sebagai berikut:', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5866, 'perka-10-2008', 22, 'lampiran', 'Lampiran hal. 14', NULL, 14, '1. Komandan Tanggap Darurat Bencana tingkat kabupaten/kota, atau tingkat provinsi yang terkena bencana, mengajukan permintaan kebutuhan sumberdaya kepada Kepala BPBD Kabupaten/Kota/Provinsi maupun kepada Kepala BNPB, berdasarkan atas ketersediaan sumberdaya di lokasi dan tingkatan bencana.
2. Kepala BPBD Kabupaten/Kota/Provinsi maupun Kepala BNPB, sesuai dengan lokasi dan tingkatan bencana, meminta dukungan sumberdaya manusia, logistik dan peralatan untuk menyelamatkan dan mengevakuasi korban, memenuhi kebutuhan dasar hidup dan memulihkan fungsi prasarana dan sarana vital yang rusak kepada pimpinan instansi/lembaga terkait sesuai tingkat kewenangannya.
3. Instansi/lembaga terkait dimaksud adalah: Departemen/Dinas Sosial, BULOG/DOLOG, Departemen/Dinas Kesehatan, Departemen/Dinas Pekerjaan Umum, Departemen/Dinas Perhubungan, Basarnas/Basarda Kabupaten/Kota, Tentara Nasional Indonesia, Kepolisian Republik Indonesia, Palang Merah Indonesia, Departemen/Dinas Energi dan Sumber Daya Mineral serta instansi/lembaga lainnya sesuai tingkat kewenangannya.
4. Instansi/lembaga terkait wajib segera mengirimkan serta memobilisasi sumberdaya manusia, logistik dan peralatan ke lokasi bencana.
5. Penerimaan serta penggunaan sumberdaya manusia, peralatan dan logistik di lokasi bencana sebagaimana dimaksud dilaksanakan dibawah kendali Kepala BPBD/BNPB dan atau Departemen Keuangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5866, '1. Komandan Tanggap Darurat Bencana tingkat kabupaten/kota, atau tingkat provinsi yang terkena bencana, mengajukan permintaan kebutuhan sumberdaya kepada Kepala BPBD Kabupaten/Kota/Provinsi maupun kepada Kepala BNPB, berdasarkan atas ketersediaan sumberdaya di lokasi dan tingkatan bencana.
2. Kepala BPBD Kabupaten/Kota/Provinsi maupun Kepala BNPB, sesuai dengan lokasi dan tingkatan bencana, meminta dukungan sumberdaya manusia, logistik dan peralatan untuk menyelamatkan dan mengevakuasi korban, memenuhi kebutuhan dasar hidup dan memulihkan fungsi prasarana dan sarana vital yang rusak kepada pimpinan instansi/lembaga terkait sesuai tingkat kewenangannya.
3. Instansi/lembaga terkait dimaksud adalah: Departemen/Dinas Sosial, BULOG/DOLOG, Departemen/Dinas Kesehatan, Departemen/Dinas Pekerjaan Umum, Departemen/Dinas Perhubungan, Basarnas/Basarda Kabupaten/Kota, Tentara Nasional Indonesia, Kepolisian Republik Indonesia, Palang Merah Indonesia, Departemen/Dinas Energi dan Sumber Daya Mineral serta instansi/lembaga lainnya sesuai tingkat kewenangannya.
4. Instansi/lembaga terkait wajib segera mengirimkan serta memobilisasi sumberdaya manusia, logistik dan peralatan ke lokasi bencana.
5. Penerimaan serta penggunaan sumberdaya manusia, peralatan dan logistik di lokasi bencana sebagaimana dimaksud dilaksanakan dibawah kendali Kepala BPBD/BNPB dan atau Departemen Keuangan.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5867, 'perka-10-2008', 23, 'lampiran', 'Lampiran hal. 15', NULL, 15, 'C. Pengerahan/Mobilisasi Sumberdaya Pengerahan/mobilisasi sumberdaya untuk penanganan tanggap darurat bencana diselenggarakan dengan ketentuan sebagai berikut:
1. Instansi/lembaga/organisasi terkait dalam mengirimkan sumberdaya harus didampingi oleh personil instansi/lembaga asal dan penyerahannya dilengkapi dengan administrasi sesuai ketentuan dan peraturan yang berlaku.
2. Apabila instansi/lembaga/organisasi terkait pada tingkat tertentu tidak memiliki kemampuan sumberdaya yang dibutuhkan, maka BPBD maupun BNPB sesuai dengan tingkat kewenangannya berkewajiban membantu/mendampingi pengiriman/mobilisasi sumber daya sampai ke lokasi bencana.
3. Ilustrasi permintaan dan pengerahan sumberdaya Komando Tanggap Darurat Bencana tingkat kabupaten/kota dapat dilihat pada Lampiran-9.
4. Ilustrasi permintaan dan pengerahan sumberdaya Komando Tanggap Darurat Bencana tingkat provinsi dilihat Lampiran-10.
D. Fasilitas Komando Tanggap Darurat Bencana
1. Untuk meningkatkan efektifitas dan mempercepat respons penanganan tanggap darurat bencana, Komando Tanggap Darurat Bencana perlu menyiapkan dan menghimpun dukungan operasi penanganan darurat bencana yang terdiri dari:
a. Pos Komando, meliputi Posko Tanggap Darurat dan Poskolap.
b. Personil Komando, adalah semua sumberdaya manusia yang bertugas dalam organisasi Komando Tanggap Darurat Bencana dengan kualifikasi dan kompetensi yang diperlukan untuk penugasan penanganan darurat bencana.
c. Gudang, tempat penyimpanan logistik dan peralatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5867, 'C. Pengerahan/Mobilisasi Sumberdaya Pengerahan/mobilisasi sumberdaya untuk penanganan tanggap darurat bencana diselenggarakan dengan ketentuan sebagai berikut:
1. Instansi/lembaga/organisasi terkait dalam mengirimkan sumberdaya harus didampingi oleh personil instansi/lembaga asal dan penyerahannya dilengkapi dengan administrasi sesuai ketentuan dan peraturan yang berlaku.
2. Apabila instansi/lembaga/organisasi terkait pada tingkat tertentu tidak memiliki kemampuan sumberdaya yang dibutuhkan, maka BPBD maupun BNPB sesuai dengan tingkat kewenangannya berkewajiban membantu/mendampingi pengiriman/mobilisasi sumber daya sampai ke lokasi bencana.
3. Ilustrasi permintaan dan pengerahan sumberdaya Komando Tanggap Darurat Bencana tingkat kabupaten/kota dapat dilihat pada Lampiran-9.
4. Ilustrasi permintaan dan pengerahan sumberdaya Komando Tanggap Darurat Bencana tingkat provinsi dilihat Lampiran-10.
D. Fasilitas Komando Tanggap Darurat Bencana
1. Untuk meningkatkan efektifitas dan mempercepat respons penanganan tanggap darurat bencana, Komando Tanggap Darurat Bencana perlu menyiapkan dan menghimpun dukungan operasi penanganan darurat bencana yang terdiri dari:
a. Pos Komando, meliputi Posko Tanggap Darurat dan Poskolap.
b. Personil Komando, adalah semua sumberdaya manusia yang bertugas dalam organisasi Komando Tanggap Darurat Bencana dengan kualifikasi dan kompetensi yang diperlukan untuk penugasan penanganan darurat bencana.
c. Gudang, tempat penyimpanan logistik dan peralatan.', 'Lampiran hal. 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5868, 'perka-10-2008', 24, 'lampiran', 'Lampiran hal. 16', NULL, 16, 'd. Sarana dan prasarana transportasi, baik yang merupakan fasilitas dasar maupun spesifik sesuai jenis bencana.
e. Peralatan, baik yang merupakan fasilitas dasar maupun fasilitas yang spesifik sesuai jenis bencana.
f. Alat komunikasi dan peralatan komputer.
g. Data serta informasi bencana dan dampak bencana.
2. Konfigurasi fasilitas alat komunikasi untuk Komando Tanggap Darurat Bencana dapat dilihat di Lampiran-11.
3. Tabel contoh kebutuhan fasilitas Komando Tanggap Darurat Bencana dapat dilihat di Lampiran-12.
E. Pengakhiran
1. Menjelang berakhirnya waktu pelaksanaan operasi tanggap darurat bencana, Kepala BPBD Kabupaten/Kota/Provinsi atau Kepala BNPB membuat rencana pengakhiran operasi tanggap darurat bencana dengan mengeluarkan Surat Perintah Pengakhiran Operasi Tanggap Darurat Bencana kepada Komandan Tanggap Darurat Bencana sesuai dengan kewenangannya.
2. Pada hari dan tanggal waktu berakhirnya operasi tanggap darurat bencana, Kepala BNPB/BPBD membubarkan Komando Tanggap Darurat Bencana dengan menerbitkan Surat Keputusan Pembubaran.
F. Pola Pengerahan Sumberdaya di Tingkat Kabupaten/Kota Pengerahan sumberdaya di tingkat kabupaten/kota dilaksanakan dengan pola sebagai berikut:
1. Dalam hal bencana tingkat kabupaten/kota, Kepala BPBD Kabupaten/Kota yang terkena bencana, mengerahkan sumberdaya manusia, peralatan dan logistik sesuai kebutuhan ke lokasi bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5868, 'd. Sarana dan prasarana transportasi, baik yang merupakan fasilitas dasar maupun spesifik sesuai jenis bencana.
e. Peralatan, baik yang merupakan fasilitas dasar maupun fasilitas yang spesifik sesuai jenis bencana.
f. Alat komunikasi dan peralatan komputer.
g. Data serta informasi bencana dan dampak bencana.
2. Konfigurasi fasilitas alat komunikasi untuk Komando Tanggap Darurat Bencana dapat dilihat di Lampiran-11.
3. Tabel contoh kebutuhan fasilitas Komando Tanggap Darurat Bencana dapat dilihat di Lampiran-12.
E. Pengakhiran
1. Menjelang berakhirnya waktu pelaksanaan operasi tanggap darurat bencana, Kepala BPBD Kabupaten/Kota/Provinsi atau Kepala BNPB membuat rencana pengakhiran operasi tanggap darurat bencana dengan mengeluarkan Surat Perintah Pengakhiran Operasi Tanggap Darurat Bencana kepada Komandan Tanggap Darurat Bencana sesuai dengan kewenangannya.
2. Pada hari dan tanggal waktu berakhirnya operasi tanggap darurat bencana, Kepala BNPB/BPBD membubarkan Komando Tanggap Darurat Bencana dengan menerbitkan Surat Keputusan Pembubaran.
F. Pola Pengerahan Sumberdaya di Tingkat Kabupaten/Kota Pengerahan sumberdaya di tingkat kabupaten/kota dilaksanakan dengan pola sebagai berikut:
1. Dalam hal bencana tingkat kabupaten/kota, Kepala BPBD Kabupaten/Kota yang terkena bencana, mengerahkan sumberdaya manusia, peralatan dan logistik sesuai kebutuhan ke lokasi bencana.', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5869, 'perka-10-2008', 25, 'lampiran', 'Lampiran hal. 17', NULL, 17, '2. Apabila kebutuhan tersebut tidak tersedia/tidak memadai, maka pemerintah kabupaten/kota yang bersangkutan dapat meminta bantuan kepada pemerintah kabupaten/kota terdekat baik dalam satu wilayah provinsi maupun provinsi lain.
3. Apabila pemerintah kabupaten/kota yang dimintai bantuan tidak memiliki ketersediaan sumberdaya/tidak memadai, maka pemerintah kabupaten/kota yang terkena bencana dapat meminta bantuan kepada pemerintah provinsi yang bersangkutan.
4. Biaya yang timbul akibat pengerahan bantuan ini ditanggung oleh pemerintah kabupaten/kota yang bersangkutan.
5. Pelaksanaan pengerahan sumber daya dari asal sampai dengan lokasi bencana dilaksanakan dibawah kendali Kepala BPBD Kabupaten/Kota yang bersangkutan.
6. Apabila terdapat keterbatasan sumberdaya manusia, peralatan dan logistik yang dikerahkan oleh Kepala BPBD Kabupaten/Kota, maka BNPB dapat membantu melalui pola pendampingan.
7. Pola pendampingan oleh BNPB dapat berupa dukungan biaya pengepakan, biaya pengiriman, jasa tenaga pengangkutan dan dukungan peralatan tanggap darurat bencana.
8. Ilustrasi pengerahan sumberdaya di tingkat kabupaten/kota lihat Lampiran-9.
G. Pola Pengerahan Sumberdaya di Tingkat Provinsi Pengerahan sumberdaya di tingkat provinsi dilaksanakan dengan pola sebagai berikut:
1. Dalam hal bencana tingkat provinsi, Kepala BPBD Provinsi yang terkena bencana mengerahkan sumberdaya manusia, peralatan dan logistik sesuai kebutuhan ke lokasi bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5869, '2. Apabila kebutuhan tersebut tidak tersedia/tidak memadai, maka pemerintah kabupaten/kota yang bersangkutan dapat meminta bantuan kepada pemerintah kabupaten/kota terdekat baik dalam satu wilayah provinsi maupun provinsi lain.
3. Apabila pemerintah kabupaten/kota yang dimintai bantuan tidak memiliki ketersediaan sumberdaya/tidak memadai, maka pemerintah kabupaten/kota yang terkena bencana dapat meminta bantuan kepada pemerintah provinsi yang bersangkutan.
4. Biaya yang timbul akibat pengerahan bantuan ini ditanggung oleh pemerintah kabupaten/kota yang bersangkutan.
5. Pelaksanaan pengerahan sumber daya dari asal sampai dengan lokasi bencana dilaksanakan dibawah kendali Kepala BPBD Kabupaten/Kota yang bersangkutan.
6. Apabila terdapat keterbatasan sumberdaya manusia, peralatan dan logistik yang dikerahkan oleh Kepala BPBD Kabupaten/Kota, maka BNPB dapat membantu melalui pola pendampingan.
7. Pola pendampingan oleh BNPB dapat berupa dukungan biaya pengepakan, biaya pengiriman, jasa tenaga pengangkutan dan dukungan peralatan tanggap darurat bencana.
8. Ilustrasi pengerahan sumberdaya di tingkat kabupaten/kota lihat Lampiran-9.
G. Pola Pengerahan Sumberdaya di Tingkat Provinsi Pengerahan sumberdaya di tingkat provinsi dilaksanakan dengan pola sebagai berikut:
1. Dalam hal bencana tingkat provinsi, Kepala BPBD Provinsi yang terkena bencana mengerahkan sumberdaya manusia, peralatan dan logistik sesuai kebutuhan ke lokasi bencana.', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5870, 'perka-10-2008', 26, 'lampiran', 'Lampiran hal. 17', NULL, 17, '2. Apabila kebutuhan tersebut tidak tersedia/tidak memadai, maka pemerintah provinsi yang bersangkutan dapat meminta bantuan kepada provinsi lain yang terdekat.
3. Apabila provinsi yang dimintai bantuan tidak memiliki ketersediaan sumberdaya/tidak memadai, maka pemerintah provinsi yang terkena bencana dapat meminta bantuan kepada Pemerintah Pusat.
4. Biaya yang timbul akibat pengerahan bantuan ini ditanggung oleh pemerintah provinsi yang bersangkutan.
5. Pelaksanaan pengerahan sumber daya dari asal sampai dengan lokasi bencana dilaksanakan dibawah kendali Kepala BPBD Provinsi yang bersangkutan.
6. Apabila terdapat keterbatasan sumberdaya manusia, peralatan dan logistik yang dikerahkan oleh Kepala BPBD Propinsi, maka BNPB dapat membantu melalui pola pendampingan.
7. Pola pendampingan oleh BNPB dapat berupa dukungan biaya pengepakan, biaya pengiriman, jasa tenaga pengangkutan dan dukungan peralatan tanggap darurat bencana.
H. Pola Penyelenggaraan di Tingkat Nasional Pendistribusian logistik kepada masyarakat dilaksanakan oleh Komando Tanggap Darurat Bencana sesuai dengan dinamika yang terjadi, terutama untuk pemenuhan kebutuhan dasar hidup meliputi pangan, sandang, air bersih, sanitasi, hunian sementara, pelayanan kesehatan dan lain-lain.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5870, '2. Apabila kebutuhan tersebut tidak tersedia/tidak memadai, maka pemerintah provinsi yang bersangkutan dapat meminta bantuan kepada provinsi lain yang terdekat.
3. Apabila provinsi yang dimintai bantuan tidak memiliki ketersediaan sumberdaya/tidak memadai, maka pemerintah provinsi yang terkena bencana dapat meminta bantuan kepada Pemerintah Pusat.
4. Biaya yang timbul akibat pengerahan bantuan ini ditanggung oleh pemerintah provinsi yang bersangkutan.
5. Pelaksanaan pengerahan sumber daya dari asal sampai dengan lokasi bencana dilaksanakan dibawah kendali Kepala BPBD Provinsi yang bersangkutan.
6. Apabila terdapat keterbatasan sumberdaya manusia, peralatan dan logistik yang dikerahkan oleh Kepala BPBD Propinsi, maka BNPB dapat membantu melalui pola pendampingan.
7. Pola pendampingan oleh BNPB dapat berupa dukungan biaya pengepakan, biaya pengiriman, jasa tenaga pengangkutan dan dukungan peralatan tanggap darurat bencana.
H. Pola Penyelenggaraan di Tingkat Nasional Pendistribusian logistik kepada masyarakat dilaksanakan oleh Komando Tanggap Darurat Bencana sesuai dengan dinamika yang terjadi, terutama untuk pemenuhan kebutuhan dasar hidup meliputi pangan, sandang, air bersih, sanitasi, hunian sementara, pelayanan kesehatan dan lain-lain.', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5871, 'perka-10-2008', 27, 'lampiran', 'Lampiran hal. 19', NULL, 19, 'BAB V EVALUASI DAN PELAPORAN A. Evaluasi Komandan Tanggap Darurat Bencana melakukan rapat evaluasi setiap hari dan merencanakan kegiatan hari berikutnya. Hasil evaluasi tersebut digunakan sebagai bahan laporan harian kepada Kepala BPBD atau Kepala BNPB dengan tembusan kepada pimpinan instansi/lembaga terkait.
B Pelaporan
1. Instansi/lembaga/organisasi yang terkait dalam penanganan darurat bencana berkewajiban membuat laporan kepada Kepala BPBD/BNPB sesuai tingkat kewenanganya dengan tembusan kepada Komandan Tanggap Darurat bencana sesuai tingkat kewenangannya.
2. Pelaporan meliputi pelaksanaan Komando Tanggap Darurat Bencana, jumlah/kekuatan sumber daya manusia, jumlah peralatan, jumlah setiap jenis/macam logistik dan sumber daya lainnya serta dilengkapi dengan sistem distribusinya secara tertib dan akuntabel.
3. Komandan Tanggap Darurat Bencana sesuai tingkat kewenangannya mengirimkan laporan harian, laporan khusus dan laporan insidentil tentang pelaksanaan operasi tanggap darurat bencana kepada Kepala BNPB/BPBD dengan tembusan kepada instansi/lembaga/ organisasi yang terkait.
4. Kepala BPBD melaporkan kepada Walikota/Bupati/Gubernur dan Kepala BNPB.
5. Kepala BNPB melaporkan penanganan tanggap darurat bencana kepada Presiden.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5871, 'BAB V EVALUASI DAN PELAPORAN A. Evaluasi Komandan Tanggap Darurat Bencana melakukan rapat evaluasi setiap hari dan merencanakan kegiatan hari berikutnya. Hasil evaluasi tersebut digunakan sebagai bahan laporan harian kepada Kepala BPBD atau Kepala BNPB dengan tembusan kepada pimpinan instansi/lembaga terkait.
B Pelaporan
1. Instansi/lembaga/organisasi yang terkait dalam penanganan darurat bencana berkewajiban membuat laporan kepada Kepala BPBD/BNPB sesuai tingkat kewenanganya dengan tembusan kepada Komandan Tanggap Darurat bencana sesuai tingkat kewenangannya.
2. Pelaporan meliputi pelaksanaan Komando Tanggap Darurat Bencana, jumlah/kekuatan sumber daya manusia, jumlah peralatan, jumlah setiap jenis/macam logistik dan sumber daya lainnya serta dilengkapi dengan sistem distribusinya secara tertib dan akuntabel.
3. Komandan Tanggap Darurat Bencana sesuai tingkat kewenangannya mengirimkan laporan harian, laporan khusus dan laporan insidentil tentang pelaksanaan operasi tanggap darurat bencana kepada Kepala BNPB/BPBD dengan tembusan kepada instansi/lembaga/ organisasi yang terkait.
4. Kepala BPBD melaporkan kepada Walikota/Bupati/Gubernur dan Kepala BNPB.
5. Kepala BNPB melaporkan penanganan tanggap darurat bencana kepada Presiden.', 'Lampiran hal. 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5872, 'perka-10-2008', 28, 'lampiran', 'Lampiran hal. 20', NULL, 20, 'BAB VI PENUTUP Pedoman Komando Tanggap Darurat Bencana ini dibuat agar dapat dijadikan panduan bagi BNPB/BPBD, instansi/lembaga/organisasi terkait, Tentara Nasional Indonesia, Kepolisian Republik Indonesia, agar tugas Komando Tanggap Darurat Bencana dapat dilaksanakan secara cepat, tepat, terpadu, efektif, efisien dan akuntabel.
Pedoman ini berlaku sepanjang tidak bertentangan dan belum dikeluarkan pedoman yang baru berdasarkan pedoman ini.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si.
LAMPIRAN Lampiran - 01');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5872, 'BAB VI PENUTUP Pedoman Komando Tanggap Darurat Bencana ini dibuat agar dapat dijadikan panduan bagi BNPB/BPBD, instansi/lembaga/organisasi terkait, Tentara Nasional Indonesia, Kepolisian Republik Indonesia, agar tugas Komando Tanggap Darurat Bencana dapat dilaksanakan secara cepat, tepat, terpadu, efektif, efisien dan akuntabel.
Pedoman ini berlaku sepanjang tidak bertentangan dan belum dikeluarkan pedoman yang baru berdasarkan pedoman ini.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si.
LAMPIRAN Lampiran - 01', 'Lampiran hal. 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5873, 'perka-10-2008', 29, 'penjelasan', 'Penjelasan hal. 22', NULL, 22, 'PENJELASAN RUMUSAN PERTANYAAN Hasil pelaksanaan tugas Tim Reaksi Cepat (TRC) Tanggap Darurat Bencana memuat rumusan pertanyaan ”5 W+1 H” sebagai berikut :
1. What = APA : menjelaskan macam/ jenis bencana
2. When = KAPAN : menjelaskan tanggal/waktu terjadinya bencana
3. Where = DIMANA : menjelaskan tempat/lokasi/daerah bencana
4. Who = SIAPA/BERAPA : menjelaskan siapa korban dan berapa jumlah korban manusia (meninggal dunia, luka berat, luka ringan, sakit), dan pengungsi, kerusakan bangunan, sarana dan prasarana umum.
5. Why = MENGAPA TERJADI : menjelaskan analisis singkat penyebab terjadinya bencana
6. HOW = Bagaimana Menangani Bencana. Melakukan analisis sumberdaya yang tersedia di daerah dan kebutuhan bantuan sumberdaya yang mendesak untuk penanggulangan tanggap darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5873, 'PENJELASAN RUMUSAN PERTANYAAN Hasil pelaksanaan tugas Tim Reaksi Cepat (TRC) Tanggap Darurat Bencana memuat rumusan pertanyaan ”5 W+1 H” sebagai berikut :
1. What = APA : menjelaskan macam/ jenis bencana
2. When = KAPAN : menjelaskan tanggal/waktu terjadinya bencana
3. Where = DIMANA : menjelaskan tempat/lokasi/daerah bencana
4. Who = SIAPA/BERAPA : menjelaskan siapa korban dan berapa jumlah korban manusia (meninggal dunia, luka berat, luka ringan, sakit), dan pengungsi, kerusakan bangunan, sarana dan prasarana umum.
5. Why = MENGAPA TERJADI : menjelaskan analisis singkat penyebab terjadinya bencana
6. HOW = Bagaimana Menangani Bencana. Melakukan analisis sumberdaya yang tersedia di daerah dan kebutuhan bantuan sumberdaya yang mendesak untuk penanggulangan tanggap darurat bencana.', 'Penjelasan hal. 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5874, 'perka-10-2008', 30, 'penjelasan', 'Penjelasan hal. 23', NULL, 23, 'Lampiran - 02 KOMANDO PENANGANAN TANGGAP DARURAT BENCANA Lampiran - 03 STRUKTUR ORGANISASI KOMANDO TANGGAP DARURAT BENCANA TINGKAT KABUPATEN/KOTA KETERANGAN : ____________ : Jalur Komando -------------------: Jalur Koordinasi Bidang Bidang Perencanaan Operasi KETERANGAN : ___________ : Jalur Komando KETERANGAN: ___________ : Jalur Komando Lampiran - 04 STRUKTUR ORGANISASI KOMANDO TANGGAP DARURAT BENCANA TINGKAT PROVINSI Bidang Bidang Perencanaan Operasi KETERANGAN: ___________ : Jalur Komando Lampiran - 05 STRUKTUR ORGANISASI KOMANDO TANGGAP DARURAT BENCANA TINGKAT NASIONAL KETERANGAN : ____________ : Jalur Komando --------------------- : Jalur Koordinasi KETERANGAN : ___________ : Jalur Komando Bidang Bidang Perencanaan Operasi KETERANGAN: ___________ : Jalur Komando Lampiran - 06 Contoh:
