INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5883, 'perka-10-2011', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 6 Tahun 2006 tentang Pengelolaan Barang Milik Negara/Daerah (Lembaran Negara Republik Indonesia Tahun 2006 2014, No.1421 2 Nomor 20, Tambahan Lembaran Negara Republik Indonesia Nomor 4609);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 03 Tahun 2008 tentang Pembentukan Badan Penanggulangan Bencana Daerah;
8. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah;
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik;');
