INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5887, 'perka-10-2011', 6, 'pasal', 'Pasal 3', NULL, 3, 'Peraturan Kepala ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5887, 'Peraturan Kepala ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2011 tentang Pedoman Inventarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5888, 'perka-10-2011', 7, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 30 November 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal, 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1421 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5888, 'Ditetapkan di Jakarta pada tanggal 30 November 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal, 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1421 4', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2011 tentang Pedoman Inventarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5889, 'perka-10-2011', 8, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 10 TAHUN 2011 TENTANG PEDOMAN INVENTARISASI LOGISTIK BAB I PENDAHULUAN A. Latar Belakang Dalam beberapa tahun terakhir, di Indonesia terjadi berbagai peristiwa bencana. Hal tersebut disebabkan karena Indonesia secara geografis dan struktur geologis terletak pada kawasan rawan bencana, sehingga sering terjadi gempa bumi, banjir, tanah longsor, badai, tsunami, kebakaran hutan serta lahan dan lain-lain. Selain itu, secara sosio demografis, Indonesia terdiri dari berbagai etnis, kelompok, pandangan politik, agama dan keyakinan, yang berbeda-beda. Di satu sisi, keragaman tersebut dapat menjadi kekuatan, tetapi di sisi lain dapat pula menjadi sumber terjadinya konflik atau bencana sosial.
Menyadari kondisi tersebut, maka pemerintah, pemerintah daerah dan masyarakat perlu melakukan kesiapsiagaan yang memadai dalam menghadapi bencana, salah satunya menyiapkan logistik untuk membantu meringankan penderitaan korban bencana. Bantuan dapat dihimpun dari pemerintah dan pemerintah daerah yang berasal dari APBN atau APBD, bantuan dunia usaha, masyarakat nasional maupun internasional berupa logistik untuk penanggulangan bencana.
Bantuan logistik untuk penanggulangan bencana harus dapat diterima oleh korban yang membutuhkan dengan tepat waktu, lokasi, sasaran, jumlah dan tepat kualitas. Pemerintah dan pemerintah daerah harus mempunyai data persediaan logistik untuk segera mengatasi permasalahan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5889, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 10 TAHUN 2011 TENTANG PEDOMAN INVENTARISASI LOGISTIK BAB I PENDAHULUAN A. Latar Belakang Dalam beberapa tahun terakhir, di Indonesia terjadi berbagai peristiwa bencana. Hal tersebut disebabkan karena Indonesia secara geografis dan struktur geologis terletak pada kawasan rawan bencana, sehingga sering terjadi gempa bumi, banjir, tanah longsor, badai, tsunami, kebakaran hutan serta lahan dan lain-lain. Selain itu, secara sosio demografis, Indonesia terdiri dari berbagai etnis, kelompok, pandangan politik, agama dan keyakinan, yang berbeda-beda. Di satu sisi, keragaman tersebut dapat menjadi kekuatan, tetapi di sisi lain dapat pula menjadi sumber terjadinya konflik atau bencana sosial.
Menyadari kondisi tersebut, maka pemerintah, pemerintah daerah dan masyarakat perlu melakukan kesiapsiagaan yang memadai dalam menghadapi bencana, salah satunya menyiapkan logistik untuk membantu meringankan penderitaan korban bencana. Bantuan dapat dihimpun dari pemerintah dan pemerintah daerah yang berasal dari APBN atau APBD, bantuan dunia usaha, masyarakat nasional maupun internasional berupa logistik untuk penanggulangan bencana.
Bantuan logistik untuk penanggulangan bencana harus dapat diterima oleh korban yang membutuhkan dengan tepat waktu, lokasi, sasaran, jumlah dan tepat kualitas. Pemerintah dan pemerintah daerah harus mempunyai data persediaan logistik untuk segera mengatasi permasalahan bencana.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2011 tentang Pedoman Inventarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5890, 'perka-10-2011', 9, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'Untuk itu perlunya dilaksanakan kegiatan inventarisasi logistik diseluruh wilayah.
Salah satu kegiatan inventarisasi adalah menghimpun data logistik pada instansi/lembaga terkait yang bekerja dalam penanggulangan bencana mulai dari tingkat provinsi, sampai kabupaten/kota, bahkan data yang ada pada unit-unit organisasi sosial/penanggulangan bencana dinilai sangat 5 2014, No.1421 bermanfaat bagi kesiapan dalam menghadapi bencana yang dapat terjadi sewaktu-waktu. Namun pada kenyataannya masih ada daerah yang belum memiliki data logistik. Padahal pada saat terjadinya bencana data tersebut sangat bermanfaat untuk pengerahan sumber daya, oleh karena itu dipandang perlu untuk melakukan inventarisasi logistik untuk mengetahui ketersediaan logistik dan perencanaan kebutuhan logistik penanggulangan bencana, sehingga kebutuhan logistik dapat terpenuhi dengan tepat.
Pada saat ini Badan Nasional Penanggulangan Bencana (BNPB) dan Badan Penanggulangan Bencana Daerah (BPBD) belum memiliki data ketersediaan dan kebutuhan logistik yang lengkap terutama pada daerah rawan bencana, serta untuk pemutakhiran data maka perlu dilakukan inventarisasi logistik.
Agar kegiatan inventarisasi logistik dapat dilaksanakan dengan baik, maka perlu disusun suatu pedoman inventarisasi logistik penanggulangan bencana.
B. Maksud Dan Tujuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5890, 'Untuk itu perlunya dilaksanakan kegiatan inventarisasi logistik diseluruh wilayah.
Salah satu kegiatan inventarisasi adalah menghimpun data logistik pada instansi/lembaga terkait yang bekerja dalam penanggulangan bencana mulai dari tingkat provinsi, sampai kabupaten/kota, bahkan data yang ada pada unit-unit organisasi sosial/penanggulangan bencana dinilai sangat 5 2014, No.1421 bermanfaat bagi kesiapan dalam menghadapi bencana yang dapat terjadi sewaktu-waktu. Namun pada kenyataannya masih ada daerah yang belum memiliki data logistik. Padahal pada saat terjadinya bencana data tersebut sangat bermanfaat untuk pengerahan sumber daya, oleh karena itu dipandang perlu untuk melakukan inventarisasi logistik untuk mengetahui ketersediaan logistik dan perencanaan kebutuhan logistik penanggulangan bencana, sehingga kebutuhan logistik dapat terpenuhi dengan tepat.
Pada saat ini Badan Nasional Penanggulangan Bencana (BNPB) dan Badan Penanggulangan Bencana Daerah (BPBD) belum memiliki data ketersediaan dan kebutuhan logistik yang lengkap terutama pada daerah rawan bencana, serta untuk pemutakhiran data maka perlu dilakukan inventarisasi logistik.
Agar kegiatan inventarisasi logistik dapat dilaksanakan dengan baik, maka perlu disusun suatu pedoman inventarisasi logistik penanggulangan bencana.
B. Maksud Dan Tujuan', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2011 tentang Pedoman Inventarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5891, 'perka-10-2011', 10, 'lampiran', 'Lampiran hal. 5', NULL, 5, '1. Maksud Sebagai acuan bagi BNPB, BPBD Provinsi, Kabupaten/Kota dan kementerian/lembaga terkait baik pusat maupun daerah dalam penyelenggaraan inventarisasi logistik penanggulangan bencana.
2. Tujuan Memudahkan petugas dan pemangku kepentingan dalam melakukan inventarisasi logistik secara cepat, tepat dan akuntabel, baik yang tersedia di pemerintah, pemerintah daerah, dunia usaha dan masyarakat nasional maupun internasional.
C. Landasan Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana;
2. Undang-Undang Nomor 11 Tahun 2009 tentang Kesejahteraan Sosial;
3. Peraturan Pemerintah Nomor 6 Tahun 2006 tentang Pengelolaan Barang Milik Negara/Daerah;
4. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana;
5. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana;
2014, No.1421 6
6. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana;
7. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
8. Peraturan Menteri Keuangan Nomor 171/PMK.05/2007 tentang Sistem Akuntansi dan Pelaporan Keuangan Pemerintah Pusat;
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008 tentang Pedoman Pembentukan Badan Penanggulangan Bencana Daerah;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5891, '1. Maksud Sebagai acuan bagi BNPB, BPBD Provinsi, Kabupaten/Kota dan kementerian/lembaga terkait baik pusat maupun daerah dalam penyelenggaraan inventarisasi logistik penanggulangan bencana.
2. Tujuan Memudahkan petugas dan pemangku kepentingan dalam melakukan inventarisasi logistik secara cepat, tepat dan akuntabel, baik yang tersedia di pemerintah, pemerintah daerah, dunia usaha dan masyarakat nasional maupun internasional.
C. Landasan Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana;
2. Undang-Undang Nomor 11 Tahun 2009 tentang Kesejahteraan Sosial;
3. Peraturan Pemerintah Nomor 6 Tahun 2006 tentang Pengelolaan Barang Milik Negara/Daerah;
4. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana;
5. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana;
2014, No.1421 6
6. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana;
7. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
8. Peraturan Menteri Keuangan Nomor 171/PMK.05/2007 tentang Sistem Akuntansi dan Pelaporan Keuangan Pemerintah Pusat;
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008 tentang Pedoman Pembentukan Badan Penanggulangan Bencana Daerah;', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2011 tentang Pedoman Inventarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5892, 'perka-10-2011', 11, 'lampiran', 'Lampiran hal. 6', NULL, 6, '10. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana;
11. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008 tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana;
12. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah;
13. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik;
14. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik Penanggulangan Bencana.
D. Pengertian-Pengertian
1. Bencana Peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
2. Penanggulangan Bencana Penanggulangan Bencana adalah serangkaian upaya yang meliputi : penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat dan rehabilitasi.
3. Inventarisasi Inventarisasi adalah kegiatan pendataan, pencatatan, dan pelaporan dalam rangka untuk menganalisis kebutuhan atas barang dan/atau peralatan.
7 2014, No.1421');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5892, '10. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana;
11. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008 tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana;
12. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah;
13. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik;
14. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik Penanggulangan Bencana.
D. Pengertian-Pengertian
1. Bencana Peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
2. Penanggulangan Bencana Penanggulangan Bencana adalah serangkaian upaya yang meliputi : penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat dan rehabilitasi.
3. Inventarisasi Inventarisasi adalah kegiatan pendataan, pencatatan, dan pelaporan dalam rangka untuk menganalisis kebutuhan atas barang dan/atau peralatan.
7 2014, No.1421', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2011 tentang Pedoman Inventarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5893, 'perka-10-2011', 12, 'lampiran', 'Lampiran hal. 7', NULL, 7, '4. Logistik Logistik adalah segala sesuatu yang berwujud dan dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri atas sandang, pangan dan papan atau turunannya. Termasuk dalam kategori logistik adalah barang yang habis pakai atau dikonsumsi misalnya: sembako, obat dan alat kesehatan habis pakai, pakaian dan kelengkapannya, air, tenda gulung, dan jas tidur (sleeping bag).
5. Inventarisasi Logistik Penanggulangan Bencana Inventarisasi Logistik Penanggulangan Bencana adalah kegiatan pendataan, pencatatan, dan pelaporan dalam rangka menganalisis kebutuhan logistik penanggulangan bencana.
E. Ruang Lingkup dan Sistematika
1. Ruang lingkup Pedoman inventarisasi logistik penanggulangan bencana meliputi penyelenggaraan inventarisasi logistik, prosedur penyelenggaraan inventarisasi, serta pemantauan dan evaluasi.
2. Sistematika Pedoman Inventarisasi Logistik ini, disusun dengan sistematika sebagai berikut:
BAB I PENDAHULUAN BAB II PENYELENGGARAAN INVENTARISASI LOGISTIK BAB III PROSEDUR PENYELENGGARAAN INVENTARISASI LOGISTIK BAB IV PEMANTAUAN DAN EVALUASI BAB V PENUTUP 2014, No.1421 8 BAB II PENYELENGGARAAN INVENTARISASI LOGISTIK A. Tujuan Inventarisasi Logistik Tujuan inventarisasi logistik penanggulangan bencana adalah:
a. Untuk memperoleh data dan informasi tentang; jenis, jumlah, kondisi logistik yang tersedia di pemerintah, pemerintah daerah, dunia usaha, dan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5893, '4. Logistik Logistik adalah segala sesuatu yang berwujud dan dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri atas sandang, pangan dan papan atau turunannya. Termasuk dalam kategori logistik adalah barang yang habis pakai atau dikonsumsi misalnya: sembako, obat dan alat kesehatan habis pakai, pakaian dan kelengkapannya, air, tenda gulung, dan jas tidur (sleeping bag).
5. Inventarisasi Logistik Penanggulangan Bencana Inventarisasi Logistik Penanggulangan Bencana adalah kegiatan pendataan, pencatatan, dan pelaporan dalam rangka menganalisis kebutuhan logistik penanggulangan bencana.
E. Ruang Lingkup dan Sistematika
1. Ruang lingkup Pedoman inventarisasi logistik penanggulangan bencana meliputi penyelenggaraan inventarisasi logistik, prosedur penyelenggaraan inventarisasi, serta pemantauan dan evaluasi.
2. Sistematika Pedoman Inventarisasi Logistik ini, disusun dengan sistematika sebagai berikut:
BAB I PENDAHULUAN BAB II PENYELENGGARAAN INVENTARISASI LOGISTIK BAB III PROSEDUR PENYELENGGARAAN INVENTARISASI LOGISTIK BAB IV PEMANTAUAN DAN EVALUASI BAB V PENUTUP 2014, No.1421 8 BAB II PENYELENGGARAAN INVENTARISASI LOGISTIK A. Tujuan Inventarisasi Logistik Tujuan inventarisasi logistik penanggulangan bencana adalah:
a. Untuk memperoleh data dan informasi tentang; jenis, jumlah, kondisi logistik yang tersedia di pemerintah, pemerintah daerah, dunia usaha, dan masyarakat.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2011 tentang Pedoman Inventarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5894, 'perka-10-2011', 13, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'b. Untuk menyediakan data dan informasi sebagai bahan perumusan kebijakan dan pengambilan keputusan tentang logistik.
c. Untuk menyediakan data dan informasi tentang logistik dalam rangka mendukung perencanaan dan pelaksanaan penanggulangan bencana.
d. Untuk menyediakan data dan informasi sebagai bahan analisis kebutuhan logistik.
e. Untuk menyediakan data dan informasi tentang logistik sebagai bahan pengawasan, pengendalian dan bahan laporan pertanggungjawaban.
B. Prinsip-Prinsip Inventarisasi Logistik Kegiatan inventarisasi logistik penanggulangan bencana harus dilaksanakan sesuai dengan prinsip-prinsip:
1. Akurasi Kegiatan inventarisasi logistik penanggulangan bencana harus menghasilkan data yang akurat mengenai, jenis, jumlah, dan kondisi logistik yang tersedia.
2. Kemutakhiran Kegiatan inventarisasi logistik penanggulangan bencana harus menghasilkan data yang terbaru.
3. Berkelanjutan Kegiatan inventarisasi logistik penanggulangan bencana harus dilakukan secara terus menerus (periodik) untuk menghasilkan data yang mutakhir.
4. Komprehensif Kegiatan inventarisasi logistik penanggulangan bencana harus menghasilkan data yang lengkap tentang jenis, jumlah dan kondisi logistik yang tersedia.
9 2014, No.1421
5. Akuntabilitas Kegiatan inventarisasi logistik penanggulangan bencana harus dilakukan secara terbuka dan dapat dipertanggungjawabkan secara etik dan hukum.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5894, 'b. Untuk menyediakan data dan informasi sebagai bahan perumusan kebijakan dan pengambilan keputusan tentang logistik.
c. Untuk menyediakan data dan informasi tentang logistik dalam rangka mendukung perencanaan dan pelaksanaan penanggulangan bencana.
d. Untuk menyediakan data dan informasi sebagai bahan analisis kebutuhan logistik.
e. Untuk menyediakan data dan informasi tentang logistik sebagai bahan pengawasan, pengendalian dan bahan laporan pertanggungjawaban.
B. Prinsip-Prinsip Inventarisasi Logistik Kegiatan inventarisasi logistik penanggulangan bencana harus dilaksanakan sesuai dengan prinsip-prinsip:
1. Akurasi Kegiatan inventarisasi logistik penanggulangan bencana harus menghasilkan data yang akurat mengenai, jenis, jumlah, dan kondisi logistik yang tersedia.
2. Kemutakhiran Kegiatan inventarisasi logistik penanggulangan bencana harus menghasilkan data yang terbaru.
3. Berkelanjutan Kegiatan inventarisasi logistik penanggulangan bencana harus dilakukan secara terus menerus (periodik) untuk menghasilkan data yang mutakhir.
4. Komprehensif Kegiatan inventarisasi logistik penanggulangan bencana harus menghasilkan data yang lengkap tentang jenis, jumlah dan kondisi logistik yang tersedia.
9 2014, No.1421
5. Akuntabilitas Kegiatan inventarisasi logistik penanggulangan bencana harus dilakukan secara terbuka dan dapat dipertanggungjawabkan secara etik dan hukum.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2011 tentang Pedoman Inventarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5895, 'perka-10-2011', 14, 'lampiran', 'Lampiran hal. 9', NULL, 9, '6. Koordinasi Kegiatan inventarisasi logistik penanggulangan bencana harus didasarkan pada koordinasi yang baik dan saling mendukung antar kementerian/lembaga terkait baik pusat maupun daerah dalam penanggulangan bencana.
7. Keterpaduan Kegiatan inventarisasi logistik penanggulangan bencana dilaksanakan oleh berbagai sektor secara terpadu yang didasarkan pada kerjasama yang baik dan saling mendukung.
8. Efektivitas dan Efisiensi Kegiatan inventarisasi logistik penanggulangan bencana dilaksanakan secara tepat guna dan berhasil guna.
C. Kebijakan dan Strategi
1. Kebijakan BNPB dan BPBD Provinsi, Kabupaten/kota mengupayakan tersedianya data dan informasi tentang logistik penanggulangan bencana secara komprehensif, akurat, dan terkini yang didukung sistem informasi logistik sebagai dasar untuk melakukan analisis kebutuhan logistik penanggulangan bencana.
2. Strategi
a. Koordinasi.
Kegiatan inventarisasi logistik penanggulangan bencana dilakukan secara terpadu dan terarah, diantara instansi pemerintah dan berbagai pemangku kepentingan penanggulangan bencana, yang dilakukan oleh BNPB pada tingkat pusat dan BPBD Provinsi, Kabupaten/kota pada tingkat daerah, baik secara vertikal maupun horizontal.
b. Kerja sama Kegiatan inventarisasi logistik penanggulangan bencana dilakukan melalui kerja sama diantara instansi pemerintah dan berbagai pemangku kepentingan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5895, '6. Koordinasi Kegiatan inventarisasi logistik penanggulangan bencana harus didasarkan pada koordinasi yang baik dan saling mendukung antar kementerian/lembaga terkait baik pusat maupun daerah dalam penanggulangan bencana.
7. Keterpaduan Kegiatan inventarisasi logistik penanggulangan bencana dilaksanakan oleh berbagai sektor secara terpadu yang didasarkan pada kerjasama yang baik dan saling mendukung.
8. Efektivitas dan Efisiensi Kegiatan inventarisasi logistik penanggulangan bencana dilaksanakan secara tepat guna dan berhasil guna.
C. Kebijakan dan Strategi
1. Kebijakan BNPB dan BPBD Provinsi, Kabupaten/kota mengupayakan tersedianya data dan informasi tentang logistik penanggulangan bencana secara komprehensif, akurat, dan terkini yang didukung sistem informasi logistik sebagai dasar untuk melakukan analisis kebutuhan logistik penanggulangan bencana.
2. Strategi
a. Koordinasi.
Kegiatan inventarisasi logistik penanggulangan bencana dilakukan secara terpadu dan terarah, diantara instansi pemerintah dan berbagai pemangku kepentingan penanggulangan bencana, yang dilakukan oleh BNPB pada tingkat pusat dan BPBD Provinsi, Kabupaten/kota pada tingkat daerah, baik secara vertikal maupun horizontal.
b. Kerja sama Kegiatan inventarisasi logistik penanggulangan bencana dilakukan melalui kerja sama diantara instansi pemerintah dan berbagai pemangku kepentingan penanggulangan bencana.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2011 tentang Pedoman Inventarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5896, 'perka-10-2011', 15, 'lampiran', 'Lampiran hal. 10', NULL, 10, '2014, No.1421 10 D. Lembaga Pelaksana Pelaksanaan kegiatan inventarisasi logistik dilakukan oleh kementerian/lembaga terkait tingkat pusat, provinsi dan kabupaten/kota.
1. BNPB
a. Mengkoordinasikan kegiatan inventarisasi logistik kementerian/ lembaga terkait.
b. Menyiapkan segala dokumen dan administrasi yang bersifat pendataan (daftar pertanyaan, form, dll).
c. Mengkoordinasikan untuk mendata persediaan logistik yang ada pada kementerian/lembaga lain yang terkait.
d. Membuat analisa terhadap hasil inventarisasi.
e. Membuat daftar kebutuhan berdasarkan hasil inventarisasi.
2. BPBD Provinsi
a. Mengkoordinasikan kegiatan inventarisasi logistik di provinsi.
b. Menyiapkan segala dokumen dan administrasi yang bersifat pendataan.
c. Mengkoordinir untuk mendata persediaan logistik yang ada pada instansi/lembaga lain yang terkait.
d. Membuat analisa terhadap hasil inventarisasi.
e. Membuat daftar kebutuhan provinsi berdasarkan hasil inventarisasi.
3. BPBD Kabupaten/Kota
a. Mengkoordinir kegiatan inventarisasi logistik di kabupaten/kota.
b. Menyiapkan segala dokumen dan administrasi yang bersifat pendataan.
c. Mengkoordinir untuk mendata persediaan logistik yang ada pada instansi/lembaga lain yang terkait.
d. Membuat analisa terhadap hasil inventarisasi.
e. Membuat daftar kebutuhan kabupaten/kota berdasarkan hasil inventarisasi.
4. Kementerian/Lembaga terkait
a. Melakukan inventarisasi logistik dilingkungan masing-masing sesuai dengan format yang diberikan oleh BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5896, '2014, No.1421 10 D. Lembaga Pelaksana Pelaksanaan kegiatan inventarisasi logistik dilakukan oleh kementerian/lembaga terkait tingkat pusat, provinsi dan kabupaten/kota.
1. BNPB
a. Mengkoordinasikan kegiatan inventarisasi logistik kementerian/ lembaga terkait.
b. Menyiapkan segala dokumen dan administrasi yang bersifat pendataan (daftar pertanyaan, form, dll).
c. Mengkoordinasikan untuk mendata persediaan logistik yang ada pada kementerian/lembaga lain yang terkait.
d. Membuat analisa terhadap hasil inventarisasi.
e. Membuat daftar kebutuhan berdasarkan hasil inventarisasi.
2. BPBD Provinsi
a. Mengkoordinasikan kegiatan inventarisasi logistik di provinsi.
b. Menyiapkan segala dokumen dan administrasi yang bersifat pendataan.
c. Mengkoordinir untuk mendata persediaan logistik yang ada pada instansi/lembaga lain yang terkait.
d. Membuat analisa terhadap hasil inventarisasi.
e. Membuat daftar kebutuhan provinsi berdasarkan hasil inventarisasi.
3. BPBD Kabupaten/Kota
a. Mengkoordinir kegiatan inventarisasi logistik di kabupaten/kota.
b. Menyiapkan segala dokumen dan administrasi yang bersifat pendataan.
c. Mengkoordinir untuk mendata persediaan logistik yang ada pada instansi/lembaga lain yang terkait.
d. Membuat analisa terhadap hasil inventarisasi.
e. Membuat daftar kebutuhan kabupaten/kota berdasarkan hasil inventarisasi.
4. Kementerian/Lembaga terkait
a. Melakukan inventarisasi logistik dilingkungan masing-masing sesuai dengan format yang diberikan oleh BNPB.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2011 tentang Pedoman Inventarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5897, 'perka-10-2011', 16, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'b. Menyampaikan hasil inventarisasi logistik kepada BNPB/ BPBD Provinsi, Kabupaten/kota secara berkala.
11 2014, No.1421 BAB III PROSEDUR PENYELENGGARAAN INVENTARISASI LOGISTIK Penyelenggaraan inventarisasi logistik dilaksanakan melalui prosedur persiapan, pelaksanaan, dan pelaporan dengan memanfaatkan sistem informasi logistik.
A. Persiapan
1. BNPB, BPBD Provinsi, Kabupaten/kota menyiapkan daftar/form inventarisasi logistik penanggulangan bencana sesuai dengan jenis logistik.
2. BNPB, BPBD Provinsi, Kabupaten/kota menyiapkan peralatan inventarisasi yang dibutuhkan seperti; kamera, tape recorder, handycam dan lain lain sebagai alat bantu dalam inventarisasi logistik penanggulangan bencana.
3. BNPB, BPBD Provinsi, Kabupaten/kota menyiapkan sumber daya manusia/ petugas yang akan melakukan kegiatan inventarisasi logistik penanggulangan bencana.
4. Melakukan koordinasi dengan instansi/lembaga terkait untuk melakukan inventarisasi logistik penanggulangan bencana secara berkala.
5. Kementerian/lembaga menyiapkan data inventarisasi logistik untuk penanggulangan bencana sesuai format BNPB dan BPBD Provinsi, Kabupaten/kota.
6. BNPB, BPBD Provinsi, Kabupaten/kota menyiapkan sistem informasi manajemen inventarisasi logistik penanggulangan bencana.
B. Pelaksanaan
1. Mengadakan pertemuan koordinasi dengan kementerian/lembaga terkait mengenai persediaan logistik secara berkala.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5897, 'b. Menyampaikan hasil inventarisasi logistik kepada BNPB/ BPBD Provinsi, Kabupaten/kota secara berkala.
11 2014, No.1421 BAB III PROSEDUR PENYELENGGARAAN INVENTARISASI LOGISTIK Penyelenggaraan inventarisasi logistik dilaksanakan melalui prosedur persiapan, pelaksanaan, dan pelaporan dengan memanfaatkan sistem informasi logistik.
A. Persiapan
1. BNPB, BPBD Provinsi, Kabupaten/kota menyiapkan daftar/form inventarisasi logistik penanggulangan bencana sesuai dengan jenis logistik.
2. BNPB, BPBD Provinsi, Kabupaten/kota menyiapkan peralatan inventarisasi yang dibutuhkan seperti; kamera, tape recorder, handycam dan lain lain sebagai alat bantu dalam inventarisasi logistik penanggulangan bencana.
3. BNPB, BPBD Provinsi, Kabupaten/kota menyiapkan sumber daya manusia/ petugas yang akan melakukan kegiatan inventarisasi logistik penanggulangan bencana.
4. Melakukan koordinasi dengan instansi/lembaga terkait untuk melakukan inventarisasi logistik penanggulangan bencana secara berkala.
5. Kementerian/lembaga menyiapkan data inventarisasi logistik untuk penanggulangan bencana sesuai format BNPB dan BPBD Provinsi, Kabupaten/kota.
6. BNPB, BPBD Provinsi, Kabupaten/kota menyiapkan sistem informasi manajemen inventarisasi logistik penanggulangan bencana.
B. Pelaksanaan
1. Mengadakan pertemuan koordinasi dengan kementerian/lembaga terkait mengenai persediaan logistik secara berkala.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2011 tentang Pedoman Inventarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5898, 'perka-10-2011', 17, 'lampiran', 'Lampiran hal. 11', NULL, 11, '2. Melakukan pendataan dan/atau verifikasi data persediaan logistik yang dimiliki kementerian/lembaga terkait di Pusat dan Daerah.
3. Kementerian/lembaga terkait memberikan data inventarisasi logistik kepada BNPB dan BPBD Provinsi, Kabupaten/kota.
2014, No.1421 12
4. BNPB dan BPBD Provinsi, Kabupaten/kota merekapitulasi data inventarisasi logistik dari masing-masing kementerian/lembaga terkait di Pusat dan Daerah antara lain: jenis, jumlah, kondisi, lokasi dan sumber perolehan logistik.
5. Membuat laporan inventarisasi hasil pendataan persediaan logistik secara periodik (bulanan, triwulan, semester, tahunan).
6. BNPB melakukan analisis terhadap laporan inventarisasi logistik dari kementerian/lembaga.
7. BNPB melakukan analisis kebutuhan logistik penanggulangan bencana pada suatu wilayah/daerah yang dilakukan dengan cara:
a. Mengidentifikasi jumlah penduduk dan jumlah kepala keluarga (KK) di suatu wilayah yang dianggap rawan bencana dan tingkat kerawanannya.
b. Menghitung jenis dan jumlah kebutuhan logistik di suatu wilayah berdasarkan standar minimal logistik yang perlu disediakan.
(Standar minimal logistik yang perlu disediakan adalah: (1) paket pangan sebanyak 1% dari jumlah penduduk kali 3 (tiga) hari, (2) paket sandang (3) logistik lain untuk setiap keluarga, (4) paket kematian sebanyak 1%.
c. Membandingkan jumlah logistik yang tersedia di suatu wilayah dengan jumlah kebutuhan logistik yang sesuai dengan standar minimal yang perlu disediakan untuk melihat kekurangannya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5898, '2. Melakukan pendataan dan/atau verifikasi data persediaan logistik yang dimiliki kementerian/lembaga terkait di Pusat dan Daerah.
3. Kementerian/lembaga terkait memberikan data inventarisasi logistik kepada BNPB dan BPBD Provinsi, Kabupaten/kota.
2014, No.1421 12
4. BNPB dan BPBD Provinsi, Kabupaten/kota merekapitulasi data inventarisasi logistik dari masing-masing kementerian/lembaga terkait di Pusat dan Daerah antara lain: jenis, jumlah, kondisi, lokasi dan sumber perolehan logistik.
5. Membuat laporan inventarisasi hasil pendataan persediaan logistik secara periodik (bulanan, triwulan, semester, tahunan).
6. BNPB melakukan analisis terhadap laporan inventarisasi logistik dari kementerian/lembaga.
7. BNPB melakukan analisis kebutuhan logistik penanggulangan bencana pada suatu wilayah/daerah yang dilakukan dengan cara:
a. Mengidentifikasi jumlah penduduk dan jumlah kepala keluarga (KK) di suatu wilayah yang dianggap rawan bencana dan tingkat kerawanannya.
b. Menghitung jenis dan jumlah kebutuhan logistik di suatu wilayah berdasarkan standar minimal logistik yang perlu disediakan.
(Standar minimal logistik yang perlu disediakan adalah: (1) paket pangan sebanyak 1% dari jumlah penduduk kali 3 (tiga) hari, (2) paket sandang (3) logistik lain untuk setiap keluarga, (4) paket kematian sebanyak 1%.
c. Membandingkan jumlah logistik yang tersedia di suatu wilayah dengan jumlah kebutuhan logistik yang sesuai dengan standar minimal yang perlu disediakan untuk melihat kekurangannya.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2011 tentang Pedoman Inventarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5899, 'perka-10-2011', 18, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'd. Menghitung dan menetapkan jenis dan jumlah logistik yang perlu disediakan di suatu wilayah untuk kesiapsiagaan menghadapi bencana berdasarkan tingkat kerawanan.
8. BNPB dan BPBD Provinsi, Kabupaten/kota berkoordinasi dengan kementerian/lembaga terkait untuk memberikan masukan dalam penyediaan logistik penanggulangan bencana.
9. BNPB dan BPBD Provinsi, Kabupaten/kota membuat kesepakatan dengan kementerian/lembaga terkait tentang pemenuhan kebutuhan logistik penangggulangan bencana.
C. Pelaporan BNPB dan BPBD Provinsi, Kabupaten/kota membuat laporan hasil inventarisasi logistik penanggulangan bencana, yang memuat informasi sekurang-kurangnya mencakup :
1. Jenis dan jumlah logistik yang tersedia disertai dengan dokumen.
13 2014, No.1421
2. Kondisi logistik yang tersedia (masa kadaluwarsa, rusak, hilang, dll).
3. Jenis dan jumlah logistik yang perlu disediakan di suatu wilayah.
4. Penyedia/sumber logistik (kementerian/lembaga terkait dan pemangku kepentingan).
5. Lokasi penyimpanan logistik penanggulangan bencana.
2014, No.1421 14 BAB IV PEMANTAUAN DAN EVALUASI A. Pemantauan Pemantauan pelaksanaan inventarisasi logistik penanggulangan bencana dimaksudkan agar kegiatan dapat terlaksana sesuai dengan rencana yang ditetapkan.
1. Pemantauan dilakukan oleh pimpinan unit kerja yang menyelenggarakan kegiatan inventarisasi logistik penanggulangan bencana.
2. Pemantauan dilakukan dengan cara monitoring dan supervisi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5899, 'd. Menghitung dan menetapkan jenis dan jumlah logistik yang perlu disediakan di suatu wilayah untuk kesiapsiagaan menghadapi bencana berdasarkan tingkat kerawanan.
8. BNPB dan BPBD Provinsi, Kabupaten/kota berkoordinasi dengan kementerian/lembaga terkait untuk memberikan masukan dalam penyediaan logistik penanggulangan bencana.
9. BNPB dan BPBD Provinsi, Kabupaten/kota membuat kesepakatan dengan kementerian/lembaga terkait tentang pemenuhan kebutuhan logistik penangggulangan bencana.
C. Pelaporan BNPB dan BPBD Provinsi, Kabupaten/kota membuat laporan hasil inventarisasi logistik penanggulangan bencana, yang memuat informasi sekurang-kurangnya mencakup :
1. Jenis dan jumlah logistik yang tersedia disertai dengan dokumen.
13 2014, No.1421
2. Kondisi logistik yang tersedia (masa kadaluwarsa, rusak, hilang, dll).
3. Jenis dan jumlah logistik yang perlu disediakan di suatu wilayah.
4. Penyedia/sumber logistik (kementerian/lembaga terkait dan pemangku kepentingan).
5. Lokasi penyimpanan logistik penanggulangan bencana.
2014, No.1421 14 BAB IV PEMANTAUAN DAN EVALUASI A. Pemantauan Pemantauan pelaksanaan inventarisasi logistik penanggulangan bencana dimaksudkan agar kegiatan dapat terlaksana sesuai dengan rencana yang ditetapkan.
1. Pemantauan dilakukan oleh pimpinan unit kerja yang menyelenggarakan kegiatan inventarisasi logistik penanggulangan bencana.
2. Pemantauan dilakukan dengan cara monitoring dan supervisi.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2011 tentang Pedoman Inventarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5900, 'perka-10-2011', 19, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'a. Monitoring dilakukan agar inventarisasi logistik dilaksanakan sesuai dengan ketentuan dan prosedur yang telah ditetapkan.
b. Supervisi dilakukan untuk memberikan dukungan kepada petugas inventarisasi, sehingga pelaksanaan inventarisasi logistik tidak mengalami kesulitan atau hambatan.
3. Aspek-aspek yang dipantau adalah:
a. Proses pelaksanaan inventarisasi logistik.
b. Hasil inventarisasi logistik.
c. Hambatan-hambatan dalam melaksanakan inventarisasi logistik.
4. Pemantauan dilakukan selama kegiatan inventarisasi logistik penanggulangan bencana.
B. Evaluasi Evaluasi dilakukan untuk mengetahui hasil dan hambatan dalam pelaksanaan kegiatan inventarisasi logistik penanggulangan bencana.
1. Evaluasi dilakukan oleh pimpinan unit kerja yang menyelenggarakan kegiatan inventarisasi logistik penanggulangan bencana.
2. Evaluasi dilakukan dengan cara: mempelajari laporan, diskusi dan presentasi.
3. Aspek-aspek yang dievaluasi adalah:
15 2014, No.1421
a. Penyelenggaraan kegiatan inventarisasi logistik, meliputi tahapan kegiatan persiapan, pelaksanaan dan pelaporan.
b. Hasil kegiatan inventarisasi logistik penanggulangan bencana, meliputi keakuratan, kelengkapan dan data logistik terkini.
c. Kebutuhan logistik di suatu wilayah yang perlu disediakan untuk kesiapsiagaan menghadapi bencana.
4. Evaluasi dilakukan pada akhir kegiatan inventarisasi logistik penanggulangan bencana.');
