INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5907, 'perka-10-2012', 4, 'pasal', 'Pasal 1', NULL, 3, 'Pedoman Pengelolaan Bantuan Logistik Pada Status Keadaan Darurat Bencana merupakan panduan/acuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/lembaga dan pemangku kepentingan penanggulangan bencana agar pelaksanaan pengelolaan bantuan logistik pada status keadaan darurat dilaksanakan dengan lancar, tertib, terpadu, aman dan dapat dipertanggungjawabkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5907, 'Pedoman Pengelolaan Bantuan Logistik Pada Status Keadaan Darurat Bencana merupakan panduan/acuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/lembaga dan pemangku kepentingan penanggulangan bencana agar pelaksanaan pengelolaan bantuan logistik pada status keadaan darurat dilaksanakan dengan lancar, tertib, terpadu, aman dan dapat dipertanggungjawabkan.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5908, 'perka-10-2012', 5, 'pasal', 'Pasal 2', NULL, 3, 'Pedoman sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian tak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5908, 'Pedoman sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian tak terpisahkan dari Peraturan ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5909, 'perka-10-2012', 6, 'pasal', 'Pasal 3', NULL, 3, 'Peraturan mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5909, 'Peraturan mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5910, 'perka-10-2012', 7, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 3 September 2012 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2012 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1426 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5910, 'Ditetapkan di Jakarta pada tanggal 3 September 2012 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2012 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1426 4', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5911, 'perka-10-2012', 8, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 10 TAHUN 2012 TENTANG PENGELOLAAN BANTUAN LOGISTIK PADA STATUS KEADAAN DARURAT BENCANA BAB I PENDAHULUAN A. Latar Belakang Wilayah Negara Kesatuan Republik Indonesia memiliki kondisi geografis, geologis, hidrologis, dan demografis yang memungkinkan terjadinya bencana, baik yang disebabkan oleh faktor alam, non alam maupun manusia. Potensi bencana yang disebabkan faktor alam seperti gempa bumi dan tsunami, letusan gunung berapi, banjir, tanah longsor, kekeringan, dan angin puting beliung. Bencana yang disebabkan faktor nonalam maupun faktor manusia diantaranya kebakaran hutan dan lahan, kegagalan teknologi, serta bencana sosial yang berupa konflik sosial.
Dampak bencana yang terjadi telah banyak menimbulkan korban jiwa, kerugian harta benda, dan rusaknya prasarana dan sarana publik, serta dampak psikologis yang dalam keadaan tertentu dapat menghambat pembangunan nasional. Sementara itu, waktu untuk bereaksi sangat singkat, sedangkan faktor-faktor risiko sangat tinggi. Penundaan terhadap respon darurat khususnya distribusi bantuan logistik yang tidak lancar dapat menimbulkan dampak yang buruk bagi korban bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5911, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 10 TAHUN 2012 TENTANG PENGELOLAAN BANTUAN LOGISTIK PADA STATUS KEADAAN DARURAT BENCANA BAB I PENDAHULUAN A. Latar Belakang Wilayah Negara Kesatuan Republik Indonesia memiliki kondisi geografis, geologis, hidrologis, dan demografis yang memungkinkan terjadinya bencana, baik yang disebabkan oleh faktor alam, non alam maupun manusia. Potensi bencana yang disebabkan faktor alam seperti gempa bumi dan tsunami, letusan gunung berapi, banjir, tanah longsor, kekeringan, dan angin puting beliung. Bencana yang disebabkan faktor nonalam maupun faktor manusia diantaranya kebakaran hutan dan lahan, kegagalan teknologi, serta bencana sosial yang berupa konflik sosial.
Dampak bencana yang terjadi telah banyak menimbulkan korban jiwa, kerugian harta benda, dan rusaknya prasarana dan sarana publik, serta dampak psikologis yang dalam keadaan tertentu dapat menghambat pembangunan nasional. Sementara itu, waktu untuk bereaksi sangat singkat, sedangkan faktor-faktor risiko sangat tinggi. Penundaan terhadap respon darurat khususnya distribusi bantuan logistik yang tidak lancar dapat menimbulkan dampak yang buruk bagi korban bencana.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5912, 'perka-10-2012', 9, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, khususnya dalam Pasal 6 dan Pasal 8 telah mengamanatkan bahwa Pemerintah dan Pemerintah Daerah bertanggung jawab dalam penyelenggaraan penanggulangan bencana, yang antara lain adalah memberikan perlindungan pada masyarakat dari dampak bencana, dan pemulihan kondisi dari dampak bencana, termasuk di dalamnya adalah bantuan logistik pada saat status keadaan darurat.
Pengelolaan bantuan logistik dilakukan pada status keadaan darurat dimulai sejak status siaga darurat, tanggap darurat, dan transisi darurat ke pemulihan sesuai dengan penjelasan pasal 23 ayat (1) Peraturan Pemerintah Republik Indonesia Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
Pengelolaan bantuan logistik pada status keadaan darurat adalah suatu kegiatan terpadu dalam mengelola barang bantuan penanggulangan bencana.
Pendekatan terpadu tersebut mencakup antara lain dalam pencarian sumber, pengadaan logistik, penjaminan kualitas, pengemasan, pengiriman pengangkutan, penyimpanan di gudang dan pengelolaan persediaan logistik.
5 2014, No.1426 Kegiatan ini banyak melibatkan pelaku yang melakukan berbeda aktivitas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5912, 'Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, khususnya dalam Pasal 6 dan Pasal 8 telah mengamanatkan bahwa Pemerintah dan Pemerintah Daerah bertanggung jawab dalam penyelenggaraan penanggulangan bencana, yang antara lain adalah memberikan perlindungan pada masyarakat dari dampak bencana, dan pemulihan kondisi dari dampak bencana, termasuk di dalamnya adalah bantuan logistik pada saat status keadaan darurat.
Pengelolaan bantuan logistik dilakukan pada status keadaan darurat dimulai sejak status siaga darurat, tanggap darurat, dan transisi darurat ke pemulihan sesuai dengan penjelasan pasal 23 ayat (1) Peraturan Pemerintah Republik Indonesia Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
Pengelolaan bantuan logistik pada status keadaan darurat adalah suatu kegiatan terpadu dalam mengelola barang bantuan penanggulangan bencana.
Pendekatan terpadu tersebut mencakup antara lain dalam pencarian sumber, pengadaan logistik, penjaminan kualitas, pengemasan, pengiriman pengangkutan, penyimpanan di gudang dan pengelolaan persediaan logistik.
5 2014, No.1426 Kegiatan ini banyak melibatkan pelaku yang melakukan berbeda aktivitas.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5913, 'perka-10-2012', 10, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'Oleh karena itu, setiap pelaku harus terkoordinasi, ditetapkan pengelolaannya dan dilakukan pemantauan yang tepat untuk memastikan bahwa semua bantuan dijaga hingga bantuan tersebut didistribusikan kepada penerima di tingkat rumah tangga (kepala keluarga). Dalam operasi darurat bantuan logistik diperlukan untuk mendukung organisasi dan pelaksanaan operasi status keadaan darurat dengan tujuan memastikan ketepatan waktu dan efisiensi.
Dukungan bantuan logistik harus tepat waktu, tepat lokasi, tepat sasaran, tepat kualitas, tepat kuantitas dan sesuai kebutuhan. Salah satu unsur penting yang harus diperhatikan adalah pengelolaan bantuan logistik harus dilakukan secara efektif dan efisien pada saat status keadaan darurat bencana. Berkaitan dengan hal tersebut, perlu disusun pedoman pengelolaan bantuan logistik pada masa status keadaan darurat bencana.
B. Maksud dan Tujuan
1. Maksud Pedoman ini dimaksudkan sebagai panduan bagi seluruh penyelenggara penanggulangan bencana pada umumnya, khususnya yang berkaitan dengan pengelolaan bantuan logistik pada status keadaan darurat bencana, dalam hal ini petugas pengelolaan bantuan logistik kebencanaan, baik dari BNPB/BPBD maupun instansi/lembaga/organisasi terkait.
2. Tujuan Pedoman ini bertujuan untuk memastikan pengelolaan bantuan logistik dilakukan secara cepat, efektif dan efisien, yakni diberikan pada tempat yang tepat, jumlah yang sesuai, kualitas yang memadai, serta penerima bantuan logistik yang tepat.
C. Landasan Hukum');
