INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5915, 'perka-10-2012', 12, 'lampiran', 'Lampiran hal. 6', NULL, 6, '13. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik;
14. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan;
15. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik Penanggulangan Bencana;
16. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana;
17. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 19 Tahun 2010 tentang Pedoman Penghapusan Logistik dan Peralatan Penanggulangan Bencana;
18. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2010 tentang Pedoman Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah Pada Saat Tanggapdarurat;
19. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6A Tahun 2011 tentang Pedoman Penggunaan Dana Siap Pakai.
D. Pengertian-Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan baik oleh faktor alam dan atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5915, '13. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik;
14. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan;
15. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik Penanggulangan Bencana;
16. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana;
17. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 19 Tahun 2010 tentang Pedoman Penghapusan Logistik dan Peralatan Penanggulangan Bencana;
18. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2010 tentang Pedoman Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah Pada Saat Tanggapdarurat;
19. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6A Tahun 2011 tentang Pedoman Penggunaan Dana Siap Pakai.
D. Pengertian-Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan baik oleh faktor alam dan atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5916, 'perka-10-2012', 13, 'lampiran', 'Lampiran hal. 6', NULL, 6, '2. Status Keadaan Darurat Bencana adalah suatu keadaan yang ditetapkan oleh Pemerintah untuk jangka waktu tertentu atas dasar rekomendasi lembaga yang diberi tugas untuk menanggulangi bencana yang dimulai sejak status siaga darurat, tanggap darurat, dan transisi darurat ke pemulihan.
3. Status Siaga Darurat Bencana adalah keadaan terdapat potensi bencana, yang merupakan peningkatan eskalasi ancaman yang penentunya didasarkan atas hasil pemantauan yang akurat oleh instansi yang berwenang dan juga mempertimbangkan kondisi nyata/dampak yang 7 2014, No.1426 terjadi di masyarakat. Penetapan status siaga darurat bencana dilakukan oleh pemerintah/pemerintah daerah atas usulan kepala BNPB/BPBD.
4. Status Tanggap Darurat Bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan pengurusan pengungsi, penyelamatan, serta pemulihan prasarana dan sarana.
5. Status Transisi Darurat Bencana ke Pemulihan adalah keadaan dimana penanganan darurat bersifat sementara/permanen (berdasarkan kajian teknis dari instansi yang berwenang) dengan tujuan agar sarana prasarana vital serta kegiatan sosial ekonomi masyarakat segera berfungsi, yang dilakukan sejak berlangsungnya tanggap darurat sampai dengan tahap rehabilitasi dan rekonstruksi dimulai.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5916, '2. Status Keadaan Darurat Bencana adalah suatu keadaan yang ditetapkan oleh Pemerintah untuk jangka waktu tertentu atas dasar rekomendasi lembaga yang diberi tugas untuk menanggulangi bencana yang dimulai sejak status siaga darurat, tanggap darurat, dan transisi darurat ke pemulihan.
3. Status Siaga Darurat Bencana adalah keadaan terdapat potensi bencana, yang merupakan peningkatan eskalasi ancaman yang penentunya didasarkan atas hasil pemantauan yang akurat oleh instansi yang berwenang dan juga mempertimbangkan kondisi nyata/dampak yang 7 2014, No.1426 terjadi di masyarakat. Penetapan status siaga darurat bencana dilakukan oleh pemerintah/pemerintah daerah atas usulan kepala BNPB/BPBD.
4. Status Tanggap Darurat Bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan pengurusan pengungsi, penyelamatan, serta pemulihan prasarana dan sarana.
5. Status Transisi Darurat Bencana ke Pemulihan adalah keadaan dimana penanganan darurat bersifat sementara/permanen (berdasarkan kajian teknis dari instansi yang berwenang) dengan tujuan agar sarana prasarana vital serta kegiatan sosial ekonomi masyarakat segera berfungsi, yang dilakukan sejak berlangsungnya tanggap darurat sampai dengan tahap rehabilitasi dan rekonstruksi dimulai.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5917, 'perka-10-2012', 14, 'lampiran', 'Lampiran hal. 7', NULL, 7, '6. Logistik adalah segala sesuatu yang berwujud yang dapat digunakan untuk memenuhi suatu kebutuhan dasar manusia yang habis pakai terdiri atas pangan, sandang dan papan atau turunannya. Termasuk dalam kategori logistik adalah barang yang habis pakai atau dikonsumsi, misalnya: sembako (sembilan bahan pokok), obat-obatan, pakaian dan kelengkapannya, air, kantong tidur (sleeping bag), perlengkapan bayi, perlengkapan keluarga (pembalut wanita, odol, sabun mandi, shampo, detergen, handuk).
7. Bantuan Logistik adalah logistik yang diberikan tanpa memperoleh penggantian atau dipinjam-pakaikan kepada pihak yang membutuhkan dalam rangka penanggulangan bencana.
8. Distribusi Bantuan Logistik adalah suatu sistem penyaluran dan atau pembagian bantuan logistik dalam rangka penanggulangan bencana dari daerah asal ke daerah tujuan sampai pada sasaran yang dituju.
9. Titik Distribusi adalah tempat atau fasilitas yang ditentukan atau ditetapkan untuk penyimpanan atau penyaluran bantuan logistik yang telah ditentukan oleh pejabat yang berwenang dalam rangka penanggulangan bencana.
10. Klaster Logistik adalah sekumpulan organisasi baik dari masyarakat, pemerintah dan dunia usaha yang bekerja bersama-sama untuk meningkatkan respon bidang logistik pada status keadaan darurat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5917, '6. Logistik adalah segala sesuatu yang berwujud yang dapat digunakan untuk memenuhi suatu kebutuhan dasar manusia yang habis pakai terdiri atas pangan, sandang dan papan atau turunannya. Termasuk dalam kategori logistik adalah barang yang habis pakai atau dikonsumsi, misalnya: sembako (sembilan bahan pokok), obat-obatan, pakaian dan kelengkapannya, air, kantong tidur (sleeping bag), perlengkapan bayi, perlengkapan keluarga (pembalut wanita, odol, sabun mandi, shampo, detergen, handuk).
7. Bantuan Logistik adalah logistik yang diberikan tanpa memperoleh penggantian atau dipinjam-pakaikan kepada pihak yang membutuhkan dalam rangka penanggulangan bencana.
8. Distribusi Bantuan Logistik adalah suatu sistem penyaluran dan atau pembagian bantuan logistik dalam rangka penanggulangan bencana dari daerah asal ke daerah tujuan sampai pada sasaran yang dituju.
9. Titik Distribusi adalah tempat atau fasilitas yang ditentukan atau ditetapkan untuk penyimpanan atau penyaluran bantuan logistik yang telah ditentukan oleh pejabat yang berwenang dalam rangka penanggulangan bencana.
10. Klaster Logistik adalah sekumpulan organisasi baik dari masyarakat, pemerintah dan dunia usaha yang bekerja bersama-sama untuk meningkatkan respon bidang logistik pada status keadaan darurat.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5918, 'perka-10-2012', 15, 'lampiran', 'Lampiran hal. 7', NULL, 7, '11. Masyarakat adalah kelompok, himpunan, asosiasi, organisasi, persekutuan, perkumpulan dan paguyuban yang bergerak dibidang penanggulangan bencana atau bergerak dibidang pembangunan lainnya baik yang berbadan hukum maupun tidak.
E. RUANG LINGKUP DAN SISTEMATIKA
1. Ruang Lingkup Pedoman Pengelolaan Bantuan Logistik mencakup sejak dimulainya status siaga darurat, tanggap darurat, dan transisi darurat sampai pemulihan, melalui kegiatan persiapan, perencanaan, pelaksanaan dan pengendalian.
2014, No.1426 8
2. Sistematika Pedoman Pengelolaan Bantuan Logistik pada status keadaan darurat bencana ini disusun dengan sistematika sebagai berikut:
BAB I PENDAHULUAN BAB II PERSIAPAN BAB III PERENCANAAN DAN ORGANISASI BAB IV PELAKSANAAN BAB V PENGENDALIAN BAB VI PENUTUP 9 2014, No.1426 BAB II PERSIAPAN A. Pemetaan Kapasitas Sumber Daya Kegiatan persiapan diawali dengan pemetaan sumber daya. Pemetaan sumber daya dilakukan untuk mengetahui ketersediaan logistik, gudang termasuk juga sumber daya manusia yang dapat dikerahkan dan digunakan pada saat status keadaan darurat bencana sekaligus untuk meningkatkan respon yang efektif dan tepat waktu, baik dari masyarakat, pemerintah dan pemerintah daerah, maupun dunia usaha.
Kegiatan pemetaan sumber daya yang dilakukan meliputi sebagai berikut:
1. Mengidentifikasi potensi sumber daya logistik yang ada dari semua pemangku kepentingan baik masyarakat, pemerintah, maupun dunia usaha dapat dipergunakan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5918, '11. Masyarakat adalah kelompok, himpunan, asosiasi, organisasi, persekutuan, perkumpulan dan paguyuban yang bergerak dibidang penanggulangan bencana atau bergerak dibidang pembangunan lainnya baik yang berbadan hukum maupun tidak.
E. RUANG LINGKUP DAN SISTEMATIKA
1. Ruang Lingkup Pedoman Pengelolaan Bantuan Logistik mencakup sejak dimulainya status siaga darurat, tanggap darurat, dan transisi darurat sampai pemulihan, melalui kegiatan persiapan, perencanaan, pelaksanaan dan pengendalian.
2014, No.1426 8
2. Sistematika Pedoman Pengelolaan Bantuan Logistik pada status keadaan darurat bencana ini disusun dengan sistematika sebagai berikut:
BAB I PENDAHULUAN BAB II PERSIAPAN BAB III PERENCANAAN DAN ORGANISASI BAB IV PELAKSANAAN BAB V PENGENDALIAN BAB VI PENUTUP 9 2014, No.1426 BAB II PERSIAPAN A. Pemetaan Kapasitas Sumber Daya Kegiatan persiapan diawali dengan pemetaan sumber daya. Pemetaan sumber daya dilakukan untuk mengetahui ketersediaan logistik, gudang termasuk juga sumber daya manusia yang dapat dikerahkan dan digunakan pada saat status keadaan darurat bencana sekaligus untuk meningkatkan respon yang efektif dan tepat waktu, baik dari masyarakat, pemerintah dan pemerintah daerah, maupun dunia usaha.
Kegiatan pemetaan sumber daya yang dilakukan meliputi sebagai berikut:
1. Mengidentifikasi potensi sumber daya logistik yang ada dari semua pemangku kepentingan baik masyarakat, pemerintah, maupun dunia usaha dapat dipergunakan;', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5919, 'perka-10-2012', 16, 'lampiran', 'Lampiran hal. 9', NULL, 9, '2. Mengidentifikasi sistem klaster logistik dalam penanggulangan bencana;
3. Memprediksi kendala pengelolaan bantuan logistik;
4. Memperpendek jalur pengiriman barang bantuan logistik;
5. Mengidentifikasi akses-akses alternatif ke penerima manfaat dalam memperoleh bantuan logistik;
6. Membangun sistem informasi bantuan logistik yang dapat diakses oleh semua masyarakat, pemerintah dan dunia usaha.
Kegiatan pemetaan sumberdaya memiliki tingkatan seperti berikut:
1. Pemetaan sumber daya pada tingkat nasional dikoordinasikan oleh BNPB;
2. Pemetaan sumber daya pada tingkat provinsi dikoordinasikan oleh BPBD Provinsi;
3. Pemetaan sumber daya pada tingkat kabupaten/kota dikoordinasikan oleh BPBD Kabupaten/Kota;
4. Pemetaan terhadap sumber daya dilakukan melalui kerja sama daerah.
Hasil dari kegiatan pemetaan sumber daya adalah:
1. Diperolehnya data dan informasi yang akurat dan lengkap tentang potensi sumber daya logistik, gudang dan sumber daya manusia (personil) untuk penanggulangan bencana di masing-masing lokasi;
2. Diperolehnya acuan untuk penyampaian pemenuhan kebutuhan logistik dalam penanggulangan bencana.
2014, No.1426 10 B. Membuat dan Mengembangkan Klaster Logistik Penanggulangan Bencana.
BNPB dan/atau BPBD dapat membentuk klaster logistik melalui wadah koordinasi yang tersedia pada tiap tingkatan, kecuali dinyatakan telah terbentuk.
Tujuan dari klaster logistik adalah:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5919, '2. Mengidentifikasi sistem klaster logistik dalam penanggulangan bencana;
3. Memprediksi kendala pengelolaan bantuan logistik;
4. Memperpendek jalur pengiriman barang bantuan logistik;
5. Mengidentifikasi akses-akses alternatif ke penerima manfaat dalam memperoleh bantuan logistik;
6. Membangun sistem informasi bantuan logistik yang dapat diakses oleh semua masyarakat, pemerintah dan dunia usaha.
Kegiatan pemetaan sumberdaya memiliki tingkatan seperti berikut:
1. Pemetaan sumber daya pada tingkat nasional dikoordinasikan oleh BNPB;
2. Pemetaan sumber daya pada tingkat provinsi dikoordinasikan oleh BPBD Provinsi;
3. Pemetaan sumber daya pada tingkat kabupaten/kota dikoordinasikan oleh BPBD Kabupaten/Kota;
4. Pemetaan terhadap sumber daya dilakukan melalui kerja sama daerah.
Hasil dari kegiatan pemetaan sumber daya adalah:
1. Diperolehnya data dan informasi yang akurat dan lengkap tentang potensi sumber daya logistik, gudang dan sumber daya manusia (personil) untuk penanggulangan bencana di masing-masing lokasi;
2. Diperolehnya acuan untuk penyampaian pemenuhan kebutuhan logistik dalam penanggulangan bencana.
2014, No.1426 10 B. Membuat dan Mengembangkan Klaster Logistik Penanggulangan Bencana.
BNPB dan/atau BPBD dapat membentuk klaster logistik melalui wadah koordinasi yang tersedia pada tiap tingkatan, kecuali dinyatakan telah terbentuk.
Tujuan dari klaster logistik adalah:', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5920, 'perka-10-2012', 17, 'lampiran', 'Lampiran hal. 10', NULL, 10, '1. Membangun koordinasi dan kolaborasi dari masyarakat, pemerintah dan dunia usaha untuk kesiapan dan ketersediaan logistik dalam penanggulangan bencana;
2. Meningkatkan respon logistik pada status keadaan darurat;
3. Mengidentifikasi kesenjangan, hambatan dan duplikasi di bidang logistik penanggulangan bencana.
Klaster logistik mempunyai tugas sebagai berikut:
1. Mengumpulkan, menganalisa dan menyebarluaskan informasi tentang logistik penanggulangan bencana;
2. Menyusun dan mengembangkan rencana operasi di bidang logistik penanggulangan bencana;
3. Memberikan saran dan bantuan teknis di bidang logistik penanggulangan bencana;
4. Memberikan fasilitas dan mobilisasi logistik penanggulangan bencana yang diperlukan;
5. Mengkoordinasikan masyarakat, pemerintah dan dunia usaha di bidang logistik penanggulangan bencana.
C. Membentuk Unit Respon Logistik yang bertugas untuk melakukan kaji cepat di bidang logistik pada saat awal terjadinya bencana.
1. Menyiapkan struktur;
2. Menyiapkan personil;
3. Menyiapkan dukungan operasional.
D. Membuat perjanjian kerja sama dan melakukan pencatatan dengan dunia usaha untuk penyediaan dan penggunaan fasilitas logistik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5920, '1. Membangun koordinasi dan kolaborasi dari masyarakat, pemerintah dan dunia usaha untuk kesiapan dan ketersediaan logistik dalam penanggulangan bencana;
2. Meningkatkan respon logistik pada status keadaan darurat;
3. Mengidentifikasi kesenjangan, hambatan dan duplikasi di bidang logistik penanggulangan bencana.
Klaster logistik mempunyai tugas sebagai berikut:
1. Mengumpulkan, menganalisa dan menyebarluaskan informasi tentang logistik penanggulangan bencana;
2. Menyusun dan mengembangkan rencana operasi di bidang logistik penanggulangan bencana;
3. Memberikan saran dan bantuan teknis di bidang logistik penanggulangan bencana;
4. Memberikan fasilitas dan mobilisasi logistik penanggulangan bencana yang diperlukan;
5. Mengkoordinasikan masyarakat, pemerintah dan dunia usaha di bidang logistik penanggulangan bencana.
C. Membentuk Unit Respon Logistik yang bertugas untuk melakukan kaji cepat di bidang logistik pada saat awal terjadinya bencana.
1. Menyiapkan struktur;
2. Menyiapkan personil;
3. Menyiapkan dukungan operasional.
D. Membuat perjanjian kerja sama dan melakukan pencatatan dengan dunia usaha untuk penyediaan dan penggunaan fasilitas logistik.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5921, 'perka-10-2012', 18, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'E. Koordinasi Bantuan logistik untuk korban bencana pada saat status keadaan darurat harus dapat diterima oleh korban yang membutuhkan dengan tepat waktu, tepat lokasi, tepat sasaran, tepat jumlah dan tepat kualitas. Pemerintah dan pemerintah daerah harus melakukan pengelolaan bantuan logistik secara cermat agar dapat segera mengatasi permasalahan korban bencana.
1. Nasional 11 2014, No.1426 Otoritas pemerintah dalam pengelolaan bantuan logistik pada saat status keadaan darurat dikoordinasikan oleh Badan Nasional Penanggulangan Bencana (BNPB). Dalam menjalankan peran tersebut BNPB mempunyai kemudahan akses dan berkoordinasi dengan masyarakat, pemerintah dan dunia usaha yang dapat membantu pengelolaan bantuan logistik untuk korban bencana.
Fungsi pengelolaan bantuan logistik pada saat keadaan darurat bencana di tingkat nasional adalah:
a. Seluruh komponen kementerian/lembaga mematuhi dan melaksanakan sistem pengelolaan bantuan logistik bencana yang telah ditetapkan, khususnya pada saat keadaan darurat bencana;
b. Menghimpun fakta dan informasi tentang kebutuhan dan sumber daya logistik yang diperlukan oleh masyarakat, pemerintah dan pemerintah daerah serta dunia usaha dari berbagai sumber yang dapat dipertanggungjawabkan;
c. Berperan aktif sebagai koordinator dan penanggung jawab seluruh sumberdaya dalam penanggulangan bencana yang berkaitan dengan bantuan logistik yang dipergunakan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5921, 'E. Koordinasi Bantuan logistik untuk korban bencana pada saat status keadaan darurat harus dapat diterima oleh korban yang membutuhkan dengan tepat waktu, tepat lokasi, tepat sasaran, tepat jumlah dan tepat kualitas. Pemerintah dan pemerintah daerah harus melakukan pengelolaan bantuan logistik secara cermat agar dapat segera mengatasi permasalahan korban bencana.
1. Nasional 11 2014, No.1426 Otoritas pemerintah dalam pengelolaan bantuan logistik pada saat status keadaan darurat dikoordinasikan oleh Badan Nasional Penanggulangan Bencana (BNPB). Dalam menjalankan peran tersebut BNPB mempunyai kemudahan akses dan berkoordinasi dengan masyarakat, pemerintah dan dunia usaha yang dapat membantu pengelolaan bantuan logistik untuk korban bencana.
Fungsi pengelolaan bantuan logistik pada saat keadaan darurat bencana di tingkat nasional adalah:
a. Seluruh komponen kementerian/lembaga mematuhi dan melaksanakan sistem pengelolaan bantuan logistik bencana yang telah ditetapkan, khususnya pada saat keadaan darurat bencana;
b. Menghimpun fakta dan informasi tentang kebutuhan dan sumber daya logistik yang diperlukan oleh masyarakat, pemerintah dan pemerintah daerah serta dunia usaha dari berbagai sumber yang dapat dipertanggungjawabkan;
c. Berperan aktif sebagai koordinator dan penanggung jawab seluruh sumberdaya dalam penanggulangan bencana yang berkaitan dengan bantuan logistik yang dipergunakan;', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5922, 'perka-10-2012', 19, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'd. Bertanggung jawab atas pengelolaan dan pendistribusian bantuan logistik yang bersumber dari dalam dan luar negeri dengan sistem satu pintu sesuai dengan peraturan perundang-undangan.
2. Daerah Otoritas pemerintah daerah provinsi dan kabupaten/kota dalam pengelolaan bantuan logistik pada saat status keadaan darurat dikoordinasikan oleh Badan Penanggulangan Bencana Daerah (BPBD) provinsi dan kabupaten/kota. Dalam menjalankan peran tersebut BPBD mempunyai kemudahan akses dan berkoordinasi dengan masyarakat, pemerintah dan dunia usaha yang dapat membantu dalam pengelolaan bantuan logistik untuk korban bencana.
Fungsi pengelolaan bantuan logistik di daerah adalah:
a. Pengelolaan bantuan logistik bencana pada saat status keadaan darurat bencana merupakan titik kontak utama bagi operasional di area bencana yang meliputi dua atau lebih kabupaten/kota yang berbatasan;
b. Bertanggung jawab atas dukungan fasilitas, pelayanan, personil, peralatan dan bahan atau material lain yang dibutuhkan oleh pusatpusat operasi (pos komando) di area bencana;
c. Mengkoordinasikan semua pelayanan dan pendistribusian bantuan logistik di area bencana;
d. Memelihara hubungan dan mengkoordinasikan semua lembaga yang terlibat dalam bantuan logistik bencana, dan melaporkannya secara periodik kepada kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5922, 'd. Bertanggung jawab atas pengelolaan dan pendistribusian bantuan logistik yang bersumber dari dalam dan luar negeri dengan sistem satu pintu sesuai dengan peraturan perundang-undangan.
2. Daerah Otoritas pemerintah daerah provinsi dan kabupaten/kota dalam pengelolaan bantuan logistik pada saat status keadaan darurat dikoordinasikan oleh Badan Penanggulangan Bencana Daerah (BPBD) provinsi dan kabupaten/kota. Dalam menjalankan peran tersebut BPBD mempunyai kemudahan akses dan berkoordinasi dengan masyarakat, pemerintah dan dunia usaha yang dapat membantu dalam pengelolaan bantuan logistik untuk korban bencana.
Fungsi pengelolaan bantuan logistik di daerah adalah:
a. Pengelolaan bantuan logistik bencana pada saat status keadaan darurat bencana merupakan titik kontak utama bagi operasional di area bencana yang meliputi dua atau lebih kabupaten/kota yang berbatasan;
b. Bertanggung jawab atas dukungan fasilitas, pelayanan, personil, peralatan dan bahan atau material lain yang dibutuhkan oleh pusatpusat operasi (pos komando) di area bencana;
c. Mengkoordinasikan semua pelayanan dan pendistribusian bantuan logistik di area bencana;
d. Memelihara hubungan dan mengkoordinasikan semua lembaga yang terlibat dalam bantuan logistik bencana, dan melaporkannya secara periodik kepada kepala BNPB.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5923, 'perka-10-2012', 20, 'lampiran', 'Lampiran hal. 12', NULL, 12, '2014, No.1426 12 BAB III PERENCANAAN DAN ORGANISASI A. Perencanaan Perencanaan pengelolaan bantuan logistik dilaksanakan setelah dilakukan pemetaan. Kegiataan perencanaan dilakukan melalui identifikasi dan analisis kebutuhan serta pengerahan sumber daya.
1. Identifikasi Identifikasi dan analisis kebutuhan merupakan kegiatan awal yang harus dilaksanakan pada perencanaan dalam bidang logistik.
a. Identifikasi korban dan pengungsi 1) Cakupan wilayah: jumlah desa, kecamatan, kabupaten/kota, provinsi yang terkena dampak bencana. Data ini untuk menentukan kebutuhan logistik di wilayah yang terkena dampak bencana.
2) Jumlah korban: a) Identifikasi korban meninggal, yakni melakukan pendataan terhadap jumlah korban meninggal berdasarkan jenis kelamin dan usia; b) Identifikasi korban hilang, yakni melakukan pendataan terhadap jumlah korban hilang berdasarkan jenis kelamin dan usia; c) Identifikasi korban luka berat berdasar jenis kelamin, usia dan jenis luka berat; d) Identifikasi korban luka ringan berdasarkan jenis kelamin, usia dan jenis luka ringan.
3) Jumlah pengungsi.
Melakukan pendataan terhadap pengungsi berdasarkan jenis kelamin, usia, dan kelompok rentan, yaitu balita, anak-anak (termasuk berkebutuhan khusus), ibu hamil, lanjut usia, dan orang dengan kecacatan.
b. Identifikasi akses dan kerusakan sarana dan prasarana.
1) Jalan, yaitu menghitung panjang jalan (km) yang mengalami kerusakan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5923, '2014, No.1426 12 BAB III PERENCANAAN DAN ORGANISASI A. Perencanaan Perencanaan pengelolaan bantuan logistik dilaksanakan setelah dilakukan pemetaan. Kegiataan perencanaan dilakukan melalui identifikasi dan analisis kebutuhan serta pengerahan sumber daya.
1. Identifikasi Identifikasi dan analisis kebutuhan merupakan kegiatan awal yang harus dilaksanakan pada perencanaan dalam bidang logistik.
a. Identifikasi korban dan pengungsi 1) Cakupan wilayah: jumlah desa, kecamatan, kabupaten/kota, provinsi yang terkena dampak bencana. Data ini untuk menentukan kebutuhan logistik di wilayah yang terkena dampak bencana.
2) Jumlah korban: a) Identifikasi korban meninggal, yakni melakukan pendataan terhadap jumlah korban meninggal berdasarkan jenis kelamin dan usia; b) Identifikasi korban hilang, yakni melakukan pendataan terhadap jumlah korban hilang berdasarkan jenis kelamin dan usia; c) Identifikasi korban luka berat berdasar jenis kelamin, usia dan jenis luka berat; d) Identifikasi korban luka ringan berdasarkan jenis kelamin, usia dan jenis luka ringan.
3) Jumlah pengungsi.
Melakukan pendataan terhadap pengungsi berdasarkan jenis kelamin, usia, dan kelompok rentan, yaitu balita, anak-anak (termasuk berkebutuhan khusus), ibu hamil, lanjut usia, dan orang dengan kecacatan.
b. Identifikasi akses dan kerusakan sarana dan prasarana.
1) Jalan, yaitu menghitung panjang jalan (km) yang mengalami kerusakan;', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5924, 'perka-10-2012', 21, 'lampiran', 'Lampiran hal. 12', NULL, 12, '2) Jembatan, yaitu menghitung jumlah jembatan yang mengalami kerusakan dan jenis kerusakannya;
3) Fasilitas transportasi dan perhubungan, yakni menghitung jumlah trasportasi yang rusak dan jenis kerusakannya;
4) Fasilitas pendidikan, yakni menghitung jumlah sekolah yang rusak dan jenis kerusakannya;
13 2014, No.1426 5) Fasilitas kesehatan, yakni menghitung jumlah rumah sakit yang rusak dan jenis kerusakannya;
6) Tempat ibadah yakni menghitung jumlah tempat ibadah yang rusak dan jenis kerusakannya;
7) Fasilitas ekonomi, yaitu menghitung jumlah pasar, gudang yang rusak dan jenis kerusakannya.
2. Analisis Kebutuhan
a. Pemenuhan kebutuhan dasar:
1) Sandang: menghitung kebutuhan sandang berdasarkan jumlah korban dan pengungsi, ketersediaan stok. Bantuan sandang terdiri dari pakaian pribadi berdasarkan karakteristik (jenis kelamin, usia, dll), kebersihan pribadi (sabun mandi, sabun cuci, pasta gigi, sikat gigi, pampers, pembalut bagi anak gadis, dll). Misalnya anak sekolah setidaknya memiliki 2 stel pakaian seragam sekolah dan sepasang sepatu yang sesuai ukurannya, setiap orang memiliki pakaian untuk ibadah, bayi memiliki selimut berukuran 100 x 70 cm;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5924, '2) Jembatan, yaitu menghitung jumlah jembatan yang mengalami kerusakan dan jenis kerusakannya;
3) Fasilitas transportasi dan perhubungan, yakni menghitung jumlah trasportasi yang rusak dan jenis kerusakannya;
4) Fasilitas pendidikan, yakni menghitung jumlah sekolah yang rusak dan jenis kerusakannya;
13 2014, No.1426 5) Fasilitas kesehatan, yakni menghitung jumlah rumah sakit yang rusak dan jenis kerusakannya;
6) Tempat ibadah yakni menghitung jumlah tempat ibadah yang rusak dan jenis kerusakannya;
7) Fasilitas ekonomi, yaitu menghitung jumlah pasar, gudang yang rusak dan jenis kerusakannya.
2. Analisis Kebutuhan
a. Pemenuhan kebutuhan dasar:
1) Sandang: menghitung kebutuhan sandang berdasarkan jumlah korban dan pengungsi, ketersediaan stok. Bantuan sandang terdiri dari pakaian pribadi berdasarkan karakteristik (jenis kelamin, usia, dll), kebersihan pribadi (sabun mandi, sabun cuci, pasta gigi, sikat gigi, pampers, pembalut bagi anak gadis, dll). Misalnya anak sekolah setidaknya memiliki 2 stel pakaian seragam sekolah dan sepasang sepatu yang sesuai ukurannya, setiap orang memiliki pakaian untuk ibadah, bayi memiliki selimut berukuran 100 x 70 cm;', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5925, 'perka-10-2012', 22, 'lampiran', 'Lampiran hal. 13', NULL, 13, '2) Pangan diberikan dalam bentuk bahan makanan, atau makanan yang disediakan oleh dapur umum, bantuan pangan untuk kelompok rentan diberikan dalam bentuk khusus. Misalnya Air minum diberikan sejumlah 2.5 liter per orang per hari (disesuaikan dengan kebutuhan). Bahan makanan beras sebanyak 400 gram per orang per hari, makanan siap saji diberikan dua kali sehari (dapur umum), besarnya bantuan makanan tersebut setara dengan 2100 kilo kalori;
3) Penampungan sementara diberikan dalam bentuk tendatenda, barak atau gedung fasilitas umum/sosial yang memungkinkan digunakan sebagai tempat tinggal sementara dengan ukuran 3 meter persegi per orang. Gedung harus memenuhi persyaratan keamanan dan kesehatan serta memiliki aksesibilitas terhadap fasilitas umum dan dapat menjamin privasi antar jenis kelamin dan berbagai kelompok usia;
4) Air bersih dan sanitasi. Air bersih diberikan dalam bentuk air yang berkuaklitas dan memadai untuk kebersihan pribadi maupun rumahtangga. Air bersih diberikan sebanyak 7 liter pada tiga hari pertama, selanjutnya 15 liter per orang per hari. Sumber air bersih harus berjarak 50 meter dari tempat penampungan sementara;
5) Kebutuhan kelompok rentan dilihat dari jenis kelompok rentan.
Misalnya anak-anak di bawah usia dua tahun harus diberikan selimut. Anak sekolah harus diberikan alas kaki, sepasang sepatu dan dua stel pakaian seragam.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5925, '2) Pangan diberikan dalam bentuk bahan makanan, atau makanan yang disediakan oleh dapur umum, bantuan pangan untuk kelompok rentan diberikan dalam bentuk khusus. Misalnya Air minum diberikan sejumlah 2.5 liter per orang per hari (disesuaikan dengan kebutuhan). Bahan makanan beras sebanyak 400 gram per orang per hari, makanan siap saji diberikan dua kali sehari (dapur umum), besarnya bantuan makanan tersebut setara dengan 2100 kilo kalori;
3) Penampungan sementara diberikan dalam bentuk tendatenda, barak atau gedung fasilitas umum/sosial yang memungkinkan digunakan sebagai tempat tinggal sementara dengan ukuran 3 meter persegi per orang. Gedung harus memenuhi persyaratan keamanan dan kesehatan serta memiliki aksesibilitas terhadap fasilitas umum dan dapat menjamin privasi antar jenis kelamin dan berbagai kelompok usia;
4) Air bersih dan sanitasi. Air bersih diberikan dalam bentuk air yang berkuaklitas dan memadai untuk kebersihan pribadi maupun rumahtangga. Air bersih diberikan sebanyak 7 liter pada tiga hari pertama, selanjutnya 15 liter per orang per hari. Sumber air bersih harus berjarak 50 meter dari tempat penampungan sementara;
5) Kebutuhan kelompok rentan dilihat dari jenis kelompok rentan.
Misalnya anak-anak di bawah usia dua tahun harus diberikan selimut. Anak sekolah harus diberikan alas kaki, sepasang sepatu dan dua stel pakaian seragam.', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5926, 'perka-10-2012', 23, 'lampiran', 'Lampiran hal. 13', NULL, 13, 'b. Pemenuhan kebutuhan lainnya, yaitu berkaitan dengan pemenuhan kebutuhan psikososial. Seperti fasilitas (ruangan) untuk memberikan pelayanan konseling bagi korban atau pengungsi yang mengalami trauma. Selain itu, paket peralatan terapi bermain bagi korban atau 2014, No.1426 14 pengungsi anak-anak berupa alat-alat permainan dan mainan anak-anak berdasarkan usia.
c. Analisis kebutuhan dilakukan dengan menghitung jumlah korban, pengungsi, dan infrastruktur yang rusak dengan standar minimal logistik yang dibutuhkan. Kebutuhan logistik tahap tanggap darurat didasarkan pada hasil analisis kebutuhan tanggap darurat termasuk kebutuhan air bersih (7 liter/orang/hari) dan kebutuhan sanitasi (sabun mandi, sikat gigi, pasta gigi, dan sabun cuci (1 paket/orang).
Bahan logistik lainnya yang seharusnya tersedia adalah pangan yang mencakup beras, lauk pauk (telur, ikan, daging) sebanyak 2100 kalori per orang per hari. Air minum sebanyak 1.5 liter per orang per hari.
Berdasarkan peraturan yang telah tersedia mengenai bantuan penanggulangan bencana, diharapkan agar bantuan yang diberikan pada korban sesuai dengan yang dibutuhkan, perlu dilakukan analisis kebutuhan dengan mempertimbangkan kelompok umur, jenis kelamin, dan kelompok rentan lainnya. Susunan daftar penerima bantuan dapat dijadikan data awal dalam mempertimbangkan kebutuhan penerima bantuan.
Mekanisme yang dilakukan pada kegiatan penilaian kebutuhan adalah sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5926, 'b. Pemenuhan kebutuhan lainnya, yaitu berkaitan dengan pemenuhan kebutuhan psikososial. Seperti fasilitas (ruangan) untuk memberikan pelayanan konseling bagi korban atau pengungsi yang mengalami trauma. Selain itu, paket peralatan terapi bermain bagi korban atau 2014, No.1426 14 pengungsi anak-anak berupa alat-alat permainan dan mainan anak-anak berdasarkan usia.
c. Analisis kebutuhan dilakukan dengan menghitung jumlah korban, pengungsi, dan infrastruktur yang rusak dengan standar minimal logistik yang dibutuhkan. Kebutuhan logistik tahap tanggap darurat didasarkan pada hasil analisis kebutuhan tanggap darurat termasuk kebutuhan air bersih (7 liter/orang/hari) dan kebutuhan sanitasi (sabun mandi, sikat gigi, pasta gigi, dan sabun cuci (1 paket/orang).
Bahan logistik lainnya yang seharusnya tersedia adalah pangan yang mencakup beras, lauk pauk (telur, ikan, daging) sebanyak 2100 kalori per orang per hari. Air minum sebanyak 1.5 liter per orang per hari.
Berdasarkan peraturan yang telah tersedia mengenai bantuan penanggulangan bencana, diharapkan agar bantuan yang diberikan pada korban sesuai dengan yang dibutuhkan, perlu dilakukan analisis kebutuhan dengan mempertimbangkan kelompok umur, jenis kelamin, dan kelompok rentan lainnya. Susunan daftar penerima bantuan dapat dijadikan data awal dalam mempertimbangkan kebutuhan penerima bantuan.
Mekanisme yang dilakukan pada kegiatan penilaian kebutuhan adalah sebagai berikut:', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5927, 'perka-10-2012', 24, 'lampiran', 'Lampiran hal. 14', NULL, 14, '1) Langkah-langkah a) Mengidentifikasi kebutuhan penerima bantuan (korban bencana).
(1) Mengidentifikasi kebutuhan penerima bantuan;
(2) Menentukan prioritas bantuan yang diperlukan;
(3) Menyusun daftar kebutuhan berdasarkan prioritas yang diperlukan.
2) Mengidentifikasi sumber. a) Mengidentifikasi barang-barang/asset yang masih dimiliki korban/penerima bantuan (lampiran 1. Data perkiraan asset yang masih dimiliki calon penerima bantuan); b) Mengidentifikasi pihak-pihak yang mungkin dilibatkan dalam penyediaan kebutuhan yang diperlukan penerima bantuan; c) Mengidentifikasi sumber-sumber lain di sekitar tempat penampungan.
3) Menentukan jenis bantuan yang diperlukan penerima bantuan (korban bencana) a) Berdasarkan identifikasi kebutuhan dan sumber, selanjutnya dapat ditentukan jenis bantuan apa saja yang diperlukan penerima bantuan (lampiran 2. Jenis bantuan yang diperlukan penerima bantuan); b) Selain daftar jenis bantuan dan pihak yang dapat dilibatkan, perlu disusun daftar kebutuhan yang diperlukan setiap hari, 15 2014, No.1426 seminggu sekali, atau sebulan sekali pada status keadaan darurat (lampiran 3. Daftar kebutuhan yang diperlukan setiap hari).
d. Teknik yang digunakan Kegiatan identifikasi kebutuhan dapat dilakukan dengan menggunakan teknik wawancara, observasi dan diskusi dengan calon penerima bantuan. Keterlibatan korban dalam kegiatan ini dimaksudkan agar bantuan yang akan diberikan sesuai dengan prioritas kebutuhan mereka.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5927, '1) Langkah-langkah a) Mengidentifikasi kebutuhan penerima bantuan (korban bencana).
(1) Mengidentifikasi kebutuhan penerima bantuan;
(2) Menentukan prioritas bantuan yang diperlukan;
(3) Menyusun daftar kebutuhan berdasarkan prioritas yang diperlukan.
2) Mengidentifikasi sumber. a) Mengidentifikasi barang-barang/asset yang masih dimiliki korban/penerima bantuan (lampiran 1. Data perkiraan asset yang masih dimiliki calon penerima bantuan); b) Mengidentifikasi pihak-pihak yang mungkin dilibatkan dalam penyediaan kebutuhan yang diperlukan penerima bantuan; c) Mengidentifikasi sumber-sumber lain di sekitar tempat penampungan.
3) Menentukan jenis bantuan yang diperlukan penerima bantuan (korban bencana) a) Berdasarkan identifikasi kebutuhan dan sumber, selanjutnya dapat ditentukan jenis bantuan apa saja yang diperlukan penerima bantuan (lampiran 2. Jenis bantuan yang diperlukan penerima bantuan); b) Selain daftar jenis bantuan dan pihak yang dapat dilibatkan, perlu disusun daftar kebutuhan yang diperlukan setiap hari, 15 2014, No.1426 seminggu sekali, atau sebulan sekali pada status keadaan darurat (lampiran 3. Daftar kebutuhan yang diperlukan setiap hari).
d. Teknik yang digunakan Kegiatan identifikasi kebutuhan dapat dilakukan dengan menggunakan teknik wawancara, observasi dan diskusi dengan calon penerima bantuan. Keterlibatan korban dalam kegiatan ini dimaksudkan agar bantuan yang akan diberikan sesuai dengan prioritas kebutuhan mereka.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5928, 'perka-10-2012', 25, 'lampiran', 'Lampiran hal. 15', NULL, 15, 'e. Waktu pelaksanaan Pelaksanaan kegiatan identifikasi kebutuhan dapat dilakukan setelah daftar penerima bantuan tersusun. Selanjutnya daftar penerima bantuan akan dijadikan salah satu acuan dalam melakukan identifikasi kebutuhan.
f. Pelaksana Pelaksanaan kegiatan ini dapat dilakukan oleh petugas/tim pengumpul data/pendamping lapangan yang telah terlatih atau memiliki pengalaman dalam melakukan penilaian kebutuhan.
3. Pengerahan Sumber Daya Pengerahan sumber daya mencakup hal-hal sebagai berikut:
a. Ketersediaan sumber daya provinsi, kabupaten/kota 1) Identifikasi sumber daya logistik, peralatan, sumber daya manusia yang tersedia di wilayah bencana, baik dimiliki oleh masyarakat, pemerintah dan dunia usaha;
2) Membandingkan ketersediaan potensi logistik dan kebutuhan logistik sesuai dengan hasil analisis di wilayah;
3) Kekurangan logistik yang diperlukan diatasi dengan pengerahan sumber daya baik yang dimiliki oleh masyarakat, pemerintah dan pemerintah daerah serta dunia usaha.
b. Pengerahan sumber daya dari instansi/lembaga terkait 1) Berdasarkan hasil pemetaan terhadap sumber daya yang tersedia dibangun sistem informasi logistik yang dapat diakses oleh masyarakat, pemerintah dan pemerintah daerah serta dunia usaha;
2) Kekurangan logistik dapat diatasi dengan mengakses sumber daya yang tersedia di provinsi dan kabupaten/kota terdekat dan apabila tidak mencukupi dapat mengajukan permintaan kepada pemerintah;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5928, 'e. Waktu pelaksanaan Pelaksanaan kegiatan identifikasi kebutuhan dapat dilakukan setelah daftar penerima bantuan tersusun. Selanjutnya daftar penerima bantuan akan dijadikan salah satu acuan dalam melakukan identifikasi kebutuhan.
f. Pelaksana Pelaksanaan kegiatan ini dapat dilakukan oleh petugas/tim pengumpul data/pendamping lapangan yang telah terlatih atau memiliki pengalaman dalam melakukan penilaian kebutuhan.
3. Pengerahan Sumber Daya Pengerahan sumber daya mencakup hal-hal sebagai berikut:
a. Ketersediaan sumber daya provinsi, kabupaten/kota 1) Identifikasi sumber daya logistik, peralatan, sumber daya manusia yang tersedia di wilayah bencana, baik dimiliki oleh masyarakat, pemerintah dan dunia usaha;
2) Membandingkan ketersediaan potensi logistik dan kebutuhan logistik sesuai dengan hasil analisis di wilayah;
3) Kekurangan logistik yang diperlukan diatasi dengan pengerahan sumber daya baik yang dimiliki oleh masyarakat, pemerintah dan pemerintah daerah serta dunia usaha.
b. Pengerahan sumber daya dari instansi/lembaga terkait 1) Berdasarkan hasil pemetaan terhadap sumber daya yang tersedia dibangun sistem informasi logistik yang dapat diakses oleh masyarakat, pemerintah dan pemerintah daerah serta dunia usaha;
2) Kekurangan logistik dapat diatasi dengan mengakses sumber daya yang tersedia di provinsi dan kabupaten/kota terdekat dan apabila tidak mencukupi dapat mengajukan permintaan kepada pemerintah;', 'Lampiran hal. 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2012 tentang Pengelolaan Bantuan Logistik pada Status Keadaan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5929, 'perka-10-2012', 26, 'lampiran', 'Lampiran hal. 15', NULL, 15, '3) Kekurangan logistik juga dapat diinformasikan kepada publik yang berminat untuk mengambil peran serta dalam dukungan logistik 2014, No.1426 16 pada penanganan darurat bencana, baik dari dalam maupun dari luar negeri.
B. Organisasi Pengelolaan bantuan logistik pada status keadaan darurat dipimpin oleh seorang koordinator bidang logistik yang ditunjuk oleh Komandan Posko Kedaruratan dibawah Kepala Bidang Logistik dan Peralatan dari instansi/dinas/lembaga/organisasi yang bergerak di bidang logistik. Bidang logistik ini beranggotakan para petugas perwakilan dari instansi/dinas/lembaga/organisasi/relawan yang bergerak di bidang logistik.
Tugas koordinator bidang logistik mencakup:
1. Mengkoordinasikan bantuan logistik dari instansi/ dinas/ lembaga/ organisasi yang terkait;
2. Mengkoordinasikan kegiatan dengan sekretariat;
3. Menerima, mengadministrasikan, dan menyalurkan bantuan logistik, kepada korban bencana;
4. Membuat pengajuan bantuan sesuai kebutuhan korban bencana kepada Komando Tanggap Darurat Bencana tingkat kabupaten/kota;
5. Mendukung penyelenggaraan Posko status keadaan darurat bencana;
6. Menyediakan fasilitas, jasa, dan bahan-bahan serta perlengkapan status keadaan darurat.
Koordinator Bidang Logistik bertanggung jawab kepada Komando Posko Lapangan melalui Kepala Bidang Logistik dan Peralatan.
Bidang logistik dibantu oleh seksi-seksi, antara lain:
1. Seksi Penerimaan Logistik;
2. Seksi Penyimpanan Logistik;
3. Seksi Distribusi Logistik;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5929, '3) Kekurangan logistik juga dapat diinformasikan kepada publik yang berminat untuk mengambil peran serta dalam dukungan logistik 2014, No.1426 16 pada penanganan darurat bencana, baik dari dalam maupun dari luar negeri.
B. Organisasi Pengelolaan bantuan logistik pada status keadaan darurat dipimpin oleh seorang koordinator bidang logistik yang ditunjuk oleh Komandan Posko Kedaruratan dibawah Kepala Bidang Logistik dan Peralatan dari instansi/dinas/lembaga/organisasi yang bergerak di bidang logistik. Bidang logistik ini beranggotakan para petugas perwakilan dari instansi/dinas/lembaga/organisasi/relawan yang bergerak di bidang logistik.
