INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5934, 'perka-10-2012', 31, 'lampiran', 'Lampiran hal. 21', NULL, 21, '2. Laporan Penyimpanan Logistik (Lampiran PERKA BNPB 13/2008);
