INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5938, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2013 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2013 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5939, 'perka-10-2013', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka melaksanakan ketentuan Pasal 64 Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana, telah ditetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana perlu lebih disesuaikan dengan Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana dan perkembangan keadaan;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, dipandang perlu mengubah Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 2013, No.1441 2 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana melalui Peraturan Kepala Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5939, 'a. bahwa dalam rangka melaksanakan ketentuan Pasal 64 Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana, telah ditetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana;
