INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5944, 'perka-10-2013', 6, 'pasal', 'Pasal 173', NULL, 6, 'Deputi Bidang Rehabilitasi dan Rekonstruksi terdiri dari :
a. Direktorat Penilaian Kerusakan;
b. Direktorat Pemulihan dan Peningkatan Fisik; dan
c. Direktorat Pemulihan dan Peningkatan Sosial Ekonomi.
(4) Ketentuan Pasal 211 sampai dengan Pasal 225 dihapus
(5) Ketentuan Pasal 307 dihapus.
Pasal 2 Upaya penyesuaian dan peralihan Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana yang dilaksanakan akibat dikeluarkannya peraturan ini, dilakukan sesuai ketentuan peraturan perundang-undangan.
Pasal 3 Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal diundangkan.
7 2013, No.1441 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
