INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5947, 'perka-10-2014', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka pelaksanaan sebagian fungsi pengawasan dan dalam rangka mencapai terwujudnya pemerintahan yang baik di lingkungan Badan Nasional Penanggulangan Bencana melalui pengelolaan anggaran yang diselenggarakan secara profesional dan bertanggung jawab, diperlukan verifikasi terhadap pelaksanaan anggaran agar sesuai dengan tujuan dan sesuai dengan ketentuan yang berlaku;
