INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5947, 'a. bahwa dalam rangka pelaksanaan sebagian fungsi pengawasan dan dalam rangka mencapai terwujudnya pemerintahan yang baik di lingkungan Badan Nasional Penanggulangan Bencana melalui pengelolaan anggaran yang diselenggarakan secara profesional dan bertanggung jawab, diperlukan verifikasi terhadap pelaksanaan anggaran agar sesuai dengan tujuan dan sesuai dengan ketentuan yang berlaku;
