INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5949, 'perka-10-2014', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN VERIFIKASI DOKUMEN PERTANGGUNGJAWABAN KEUANGAN DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5949, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN VERIFIKASI DOKUMEN PERTANGGUNGJAWABAN KEUANGAN DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5950, 'perka-10-2014', 4, 'pasal', 'Pasal 1', NULL, 3, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Verifikasi Dokumen Pertanggungjawaban Keuangan di Lingkungan Badan Nasional Penanggulangan Bencana ini dimaksudkan 2014, No.1601 4 sebagai acuan Satuan Kerja di lingkungan Badan Nasional Penanggulangan Bencana sebagai pengelola keuangan dalam melakukan verifikasi terhadap berkas atau dokumen pencairan pembayaran atau pertanggungjawaban dalam rangka pelaksanaan anggaran pendapatan dan belanja negara di lingkungan Badan Nasional Penanggulangan Bencana yang akan berakibat pada pembayaran oleh negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5950, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Verifikasi Dokumen Pertanggungjawaban Keuangan di Lingkungan Badan Nasional Penanggulangan Bencana ini dimaksudkan 2014, No.1601 4 sebagai acuan Satuan Kerja di lingkungan Badan Nasional Penanggulangan Bencana sebagai pengelola keuangan dalam melakukan verifikasi terhadap berkas atau dokumen pencairan pembayaran atau pertanggungjawaban dalam rangka pelaksanaan anggaran pendapatan dan belanja negara di lingkungan Badan Nasional Penanggulangan Bencana yang akan berakibat pada pembayaran oleh negara.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
