INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5954, 'perka-10-2014', 8, 'lain', 'Penutup', NULL, 4, 'Ditetapkan di Jakarta pada tanggal 16 Oktober 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 16 Oktober 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 5 2014, No.1601 PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 10 TAHUN 2014 TENTANG PEDOMAN VERIFIKASI DOKUMEN PERTANGGUNGJAWABAN KEUANGAN DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BADAN NASIONAL PENANGGULANGAN BENCANA 2014, No.1601 6 DAFTAR ISI LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 10 TAHUN 2014 TENTANG PEDOMAN VERIFIKASI DOKUMEN PERTANGGUNGJAWABAN DI LINGKUNGAN BNPB DAFTAR ISI');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5954, 'Ditetapkan di Jakarta pada tanggal 16 Oktober 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 16 Oktober 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 5 2014, No.1601 PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 10 TAHUN 2014 TENTANG PEDOMAN VERIFIKASI DOKUMEN PERTANGGUNGJAWABAN KEUANGAN DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BADAN NASIONAL PENANGGULANGAN BENCANA 2014, No.1601 6 DAFTAR ISI LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 10 TAHUN 2014 TENTANG PEDOMAN VERIFIKASI DOKUMEN PERTANGGUNGJAWABAN DI LINGKUNGAN BNPB DAFTAR ISI', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5955, 'perka-10-2014', 9, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'BAB I PENDAHULUAN 1 A. Latar Belakang 1 B. Maksud dan Tujuan 3 C. Ruang Lingkup 3 D. Pengertian 3 E. Sistematika 6 BAB II STRUKTUR DAN URAIAN TUGAS PENGELOLA ANGGARAN 7 A. Struktur Pengelola Anggaran pada BNPB 7 B. Uraian Tugas Pengelola Anggaran pada BNPB 7 BAB III ASPEK DAN VERIFIKASI DOKUMEN 11 A. Aspek Verifikasi 11 B. Pelaksanaan Verifikasi 13
1. Pelaksanaan Verifikasi Dana Nonpenanggulangan Bencana 14
2. Pelaksanaan Verifikasi Dana Penanggulangan Bencana 20 C. Hasil Verifikasi 30 D. Laporan Hasil Verifikasi 30 BAB IV PENUTUP 32 DAFTAR LAMPIRAN 7 2014, No.1601 LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 10 TAHUN 2014 TENTANG PEDOMAN VERIFIKASI DOKUMEN PERTANGGUNGJAWABAN KEUANGAN DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Badan Nasional Penanggulangan Bencana (BNPB) sebagai lembaga pemerintah nonkementerian mempunyai tugas menyelenggarakan sebagian tugas umum pemerintahan dan pembangunan di bidang penanggulangan bencana.
Pemerintah dan pemerintah daerah menjadi penanggung jawab dalam penyelenggaraan penanggulangan bencana. Hal tersebut sesuai dengan Pasal 5 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
Masyarakat pun berkewajiban melakukan kegiatan penanggulangan bencana, sebagaimana dinyatakan di dalam Pasal 27 Undang-Undang Nomor 24 Tahun 2007.
Untuk melaksanakan tugas tersebut BNPB diberi mandat oleh negara untuk mengelola anggaran melalui APBN yang digunakan pada tahap:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5955, 'BAB I PENDAHULUAN 1 A. Latar Belakang 1 B. Maksud dan Tujuan 3 C. Ruang Lingkup 3 D. Pengertian 3 E. Sistematika 6 BAB II STRUKTUR DAN URAIAN TUGAS PENGELOLA ANGGARAN 7 A. Struktur Pengelola Anggaran pada BNPB 7 B. Uraian Tugas Pengelola Anggaran pada BNPB 7 BAB III ASPEK DAN VERIFIKASI DOKUMEN 11 A. Aspek Verifikasi 11 B. Pelaksanaan Verifikasi 13
1. Pelaksanaan Verifikasi Dana Nonpenanggulangan Bencana 14
2. Pelaksanaan Verifikasi Dana Penanggulangan Bencana 20 C. Hasil Verifikasi 30 D. Laporan Hasil Verifikasi 30 BAB IV PENUTUP 32 DAFTAR LAMPIRAN 7 2014, No.1601 LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 10 TAHUN 2014 TENTANG PEDOMAN VERIFIKASI DOKUMEN PERTANGGUNGJAWABAN KEUANGAN DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Badan Nasional Penanggulangan Bencana (BNPB) sebagai lembaga pemerintah nonkementerian mempunyai tugas menyelenggarakan sebagian tugas umum pemerintahan dan pembangunan di bidang penanggulangan bencana.
Pemerintah dan pemerintah daerah menjadi penanggung jawab dalam penyelenggaraan penanggulangan bencana. Hal tersebut sesuai dengan Pasal 5 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
Masyarakat pun berkewajiban melakukan kegiatan penanggulangan bencana, sebagaimana dinyatakan di dalam Pasal 27 Undang-Undang Nomor 24 Tahun 2007.
Untuk melaksanakan tugas tersebut BNPB diberi mandat oleh negara untuk mengelola anggaran melalui APBN yang digunakan pada tahap:', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5956, 'perka-10-2014', 10, 'lampiran', 'Lampiran hal. 7', NULL, 7, '1. prabencana dalam situasi terdapat potensi terjadi bencana;
2. keadaan darurat bencana; dan
3. pascabencana.
Pada tahap-tahap tersebut terdapat alokasi dana masing-masing oleh pemerintah sesuai dengan kondisi bencana, yaitu pada tahap:
1. prabencana, dialokasikan Dana Kontinjensi Bencana;
2. keadaan darurat bencana, dialokasikan Dana Siap Pakai (on call); dan
3. pascabencana, dialokasikan Dana Bantuan Sosial Berpola Hibah.
Pelaksanaan tugas penanggulangan bencana dilaksanakan sesuai dengan rencana dan pedoman serta kriteria. Pelaksanaan tugas tersebut diwujudkan dalam bentuk pelaksanaan APBN. Di dalam proses pelaksanaan anggaran tersebut, tentu tidak terlepas dari proses pembayaran dan pada akhirnya bermuara pada proses pertanggungjawaban.
2014, No.1601 8 Setiap pelaksanaan proses kegiatan harus diawasi agar sesuai dengan rencana, pedoman, dan kriteria yang telah ditetapkan untuk menghindari terjadinya penyimpangan.
Dalam pelaksanaan anggaran atau pengelolaan keuangan, pengawasan pada umumnya bertujuan untuk menegakkan disiplin anggaran, yaitu ketaatan terhadap pedoman dan kriteria yang telah ditetapkan. Di dalam kaitan ini, pengawasan anggaran dilakukan melalui pengujian atas bukti pengeluaran anggaran tersebut sebelum dilakukan pembayaran. Pengujian tersebut di dalam istilah keuangan negara disebut juga dengan “verifikasi”.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5956, '1. prabencana dalam situasi terdapat potensi terjadi bencana;
2. keadaan darurat bencana; dan
3. pascabencana.
Pada tahap-tahap tersebut terdapat alokasi dana masing-masing oleh pemerintah sesuai dengan kondisi bencana, yaitu pada tahap:
1. prabencana, dialokasikan Dana Kontinjensi Bencana;
2. keadaan darurat bencana, dialokasikan Dana Siap Pakai (on call); dan
3. pascabencana, dialokasikan Dana Bantuan Sosial Berpola Hibah.
Pelaksanaan tugas penanggulangan bencana dilaksanakan sesuai dengan rencana dan pedoman serta kriteria. Pelaksanaan tugas tersebut diwujudkan dalam bentuk pelaksanaan APBN. Di dalam proses pelaksanaan anggaran tersebut, tentu tidak terlepas dari proses pembayaran dan pada akhirnya bermuara pada proses pertanggungjawaban.
2014, No.1601 8 Setiap pelaksanaan proses kegiatan harus diawasi agar sesuai dengan rencana, pedoman, dan kriteria yang telah ditetapkan untuk menghindari terjadinya penyimpangan.
Dalam pelaksanaan anggaran atau pengelolaan keuangan, pengawasan pada umumnya bertujuan untuk menegakkan disiplin anggaran, yaitu ketaatan terhadap pedoman dan kriteria yang telah ditetapkan. Di dalam kaitan ini, pengawasan anggaran dilakukan melalui pengujian atas bukti pengeluaran anggaran tersebut sebelum dilakukan pembayaran. Pengujian tersebut di dalam istilah keuangan negara disebut juga dengan “verifikasi”.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5957, 'perka-10-2014', 11, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'Di bidang perpajakan, istilah verifikasi disebutkan sebagai serangkaian kegiatan pengujian pemenuhan kewajiban subyektif dan obyektif atau penghitungan dan pembayaran pajak. Di dalam definisi tersebut, terdapat unsur penting, yaitu adanya istilah "pengujian". Di dalam Kamus Besar Bahasa Idonesia (KBBI), antara lain disebutkan sebagai pemeriksaan tentang kebenaran laporan, pernyataan, perhitungan uang, dan sebagainya.
Di dalam Pedoman Verifikasi ini, istilah "verifikasi" dapat dipadankan dengan istilah "pengujian". Kedua istilah tersebut dapat saling menggantikan.
Kegiatan pengujian dapat dilakukan sebelum terjadinya kegiatan pembayaran atau setelah terjadinya pembayaran. Pengujian yang dilakukan sebelum terjadinya pembayaran dapat dilakukan oleh Satuan Kerja sebagai unit operasional yang melaksanakan pekerjaan.
Di dalam Peraturan Pemerintah Nomor 45 Tahun 2013 tentang Tata Cara Pelaksanaan Anggaran Pendapatan dan Belanja Negara disebutkan bahwa pejabat perbendaharaan negara mempunyai tugas dan wewenang melakukan pengujian hak tagih kepada negara. Di dalam Peraturan Menteri Keuangan Nomor 190/PMK.05/2012 tentang Tata Cara Pembayaran Dalam Rangka Pelaksanaan Anggaran Pendapatan dan Belanja Negara juga disebutkan bahwa pengelola anggaran mempunyai tugas dan wewenang untuk melakukan pengujian dalam pelaksanaan anggaran.
Verifikasi dilakukan dengan:
1. Melakukan penilaian atas kebenaran dan kelengkapan dokumen pertanggungjawaban anggaran yang diterima dari satuan kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5957, 'Di bidang perpajakan, istilah verifikasi disebutkan sebagai serangkaian kegiatan pengujian pemenuhan kewajiban subyektif dan obyektif atau penghitungan dan pembayaran pajak. Di dalam definisi tersebut, terdapat unsur penting, yaitu adanya istilah "pengujian". Di dalam Kamus Besar Bahasa Idonesia (KBBI), antara lain disebutkan sebagai pemeriksaan tentang kebenaran laporan, pernyataan, perhitungan uang, dan sebagainya.
Di dalam Pedoman Verifikasi ini, istilah "verifikasi" dapat dipadankan dengan istilah "pengujian". Kedua istilah tersebut dapat saling menggantikan.
Kegiatan pengujian dapat dilakukan sebelum terjadinya kegiatan pembayaran atau setelah terjadinya pembayaran. Pengujian yang dilakukan sebelum terjadinya pembayaran dapat dilakukan oleh Satuan Kerja sebagai unit operasional yang melaksanakan pekerjaan.
Di dalam Peraturan Pemerintah Nomor 45 Tahun 2013 tentang Tata Cara Pelaksanaan Anggaran Pendapatan dan Belanja Negara disebutkan bahwa pejabat perbendaharaan negara mempunyai tugas dan wewenang melakukan pengujian hak tagih kepada negara. Di dalam Peraturan Menteri Keuangan Nomor 190/PMK.05/2012 tentang Tata Cara Pembayaran Dalam Rangka Pelaksanaan Anggaran Pendapatan dan Belanja Negara juga disebutkan bahwa pengelola anggaran mempunyai tugas dan wewenang untuk melakukan pengujian dalam pelaksanaan anggaran.
Verifikasi dilakukan dengan:
1. Melakukan penilaian atas kebenaran dan kelengkapan dokumen pertanggungjawaban anggaran yang diterima dari satuan kerja.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5958, 'perka-10-2014', 12, 'lampiran', 'Lampiran hal. 8', NULL, 8, '2. Menilai kewajaran pengeluaran dan belanja yang dilakukan.
3. Menilai administrasi pengelolaan anggaran apakah sudah dilakukan dengan baik dan benar.
4. Menilai pembebanan anggaran apakah sudah sesuai dengan maksud dan tujuan suatu kegiatan.
Di bidang keuangan negara, dikenal beberapa istilah berkaitan dengan penelitian/pemeriksaan terhadap bukti/dokumen keuangan pendukung lainnya di dalam pelaksanaan anggaran, yaitu:  Doelmatigheid, bahwa apakah suatu pembayaran sudah sesuai dengan tujuan pengeluaran;  Wetmatigheid, bahwa apakah pembayaran sudah sesuai dengan peraturan yang berlaku; dan 9 2014, No.1601  Rechmatigheid, bahwa apakah pembayaran sudah memenuhi hak penagih/yang berhak menerima.
Apakah bukti/dokumen keuangan pendukung untuk penagihan kepada negara, telah memenuhi prinsip-prinsip ketiga hal di atas. Oleh karena itu, verifikasi dimaksudkan untuk mencegah terjadinya penyimpangan sebelum dilakukan pembayaran, yang berarti untuk memperoleh kebenaran substantif dan formal, bahwa dokumen telah lengkap dan benar sesuai dengan peraturan dan perundang-undangan yang berlaku.
Berkenaan dengan hal tersebut, di dalam pelaksanaan APBN, dipandang perlu untuk menyusun pedoman verifikasi dokumen pertanggungjawaban keuangan di lingkungan BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5958, '2. Menilai kewajaran pengeluaran dan belanja yang dilakukan.
3. Menilai administrasi pengelolaan anggaran apakah sudah dilakukan dengan baik dan benar.
4. Menilai pembebanan anggaran apakah sudah sesuai dengan maksud dan tujuan suatu kegiatan.
Di bidang keuangan negara, dikenal beberapa istilah berkaitan dengan penelitian/pemeriksaan terhadap bukti/dokumen keuangan pendukung lainnya di dalam pelaksanaan anggaran, yaitu:  Doelmatigheid, bahwa apakah suatu pembayaran sudah sesuai dengan tujuan pengeluaran;  Wetmatigheid, bahwa apakah pembayaran sudah sesuai dengan peraturan yang berlaku; dan 9 2014, No.1601  Rechmatigheid, bahwa apakah pembayaran sudah memenuhi hak penagih/yang berhak menerima.
Apakah bukti/dokumen keuangan pendukung untuk penagihan kepada negara, telah memenuhi prinsip-prinsip ketiga hal di atas. Oleh karena itu, verifikasi dimaksudkan untuk mencegah terjadinya penyimpangan sebelum dilakukan pembayaran, yang berarti untuk memperoleh kebenaran substantif dan formal, bahwa dokumen telah lengkap dan benar sesuai dengan peraturan dan perundang-undangan yang berlaku.
Berkenaan dengan hal tersebut, di dalam pelaksanaan APBN, dipandang perlu untuk menyusun pedoman verifikasi dokumen pertanggungjawaban keuangan di lingkungan BNPB.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5959, 'perka-10-2014', 13, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'B. Maksud dan Tujuan Pedoman Verifikasi ini dimaksudkan sebagai acuan unit kerja di lingkungan BNPB sebagai pengelola keuangan di dalam melakukan verifikasi terhadap berkas atau dokumen yang akan berakibat pada pembayaran, sedangkan tujuannya adalah untuk terwujudnya administrasi pengelolaan keuangan negara yang baik dan benar sesuai dengan peraturan perundang-undangan tentang pengelolaan keuangan negara.
C. Ruang Lingkup Peraturan Kepala BNPB ini mengatur mengenai verifikasi berkas atau dokumen pencairan pembayaran dalam rangka pelaksanaan anggaran yang tertuang di dalam DIPA Satker BNPB, baik yang berasal dari Bagian Anggaran 103 maupun yang berasal dari sumber-sumber pembiayaan lainnya.
D. Pengertian Beberapa pengertian yang berkaitan dengan verifikasi di dalam Peraturan Kepala BNPB ini meliputi:
1. Anggaran Pendapatan dan Belanja Negara, yang selanjutnya disingkat APBN, adalah rencana keuangan tahunan pemerintahan negara yang disetujui oleh Dewan Perwakilan Rakyat.
2. Pembiayaan adalah setiap penerimaan yang perlu dibayar kembali dan/atau pengeluaran yang akan diterima kembali, baik pada tahun anggaran yang bersangkutan maupun tahun-tahun anggaran berikutnya.
3. Bagian Anggaran adalah kelompok anggaran menurut nomenklatur kementerian/lembaga dan menurut fungsi Bendahara Umum Negara.
4. Pengguna Anggaran yang selanjutnya disingkat PA adalah pejabat pemegang kewenangan penggunaan anggaran kementerian negara/lembaga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5959, 'B. Maksud dan Tujuan Pedoman Verifikasi ini dimaksudkan sebagai acuan unit kerja di lingkungan BNPB sebagai pengelola keuangan di dalam melakukan verifikasi terhadap berkas atau dokumen yang akan berakibat pada pembayaran, sedangkan tujuannya adalah untuk terwujudnya administrasi pengelolaan keuangan negara yang baik dan benar sesuai dengan peraturan perundang-undangan tentang pengelolaan keuangan negara.
C. Ruang Lingkup Peraturan Kepala BNPB ini mengatur mengenai verifikasi berkas atau dokumen pencairan pembayaran dalam rangka pelaksanaan anggaran yang tertuang di dalam DIPA Satker BNPB, baik yang berasal dari Bagian Anggaran 103 maupun yang berasal dari sumber-sumber pembiayaan lainnya.
D. Pengertian Beberapa pengertian yang berkaitan dengan verifikasi di dalam Peraturan Kepala BNPB ini meliputi:
1. Anggaran Pendapatan dan Belanja Negara, yang selanjutnya disingkat APBN, adalah rencana keuangan tahunan pemerintahan negara yang disetujui oleh Dewan Perwakilan Rakyat.
2. Pembiayaan adalah setiap penerimaan yang perlu dibayar kembali dan/atau pengeluaran yang akan diterima kembali, baik pada tahun anggaran yang bersangkutan maupun tahun-tahun anggaran berikutnya.
3. Bagian Anggaran adalah kelompok anggaran menurut nomenklatur kementerian/lembaga dan menurut fungsi Bendahara Umum Negara.
4. Pengguna Anggaran yang selanjutnya disingkat PA adalah pejabat pemegang kewenangan penggunaan anggaran kementerian negara/lembaga.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5960, 'perka-10-2014', 14, 'lampiran', 'Lampiran hal. 9', NULL, 9, '5. Kuasa Pengguna Anggaran yang selanjutnya disingkat KPA adalah pejabat yang memperoleh kuasa dari PA untuk melaksanakan sebagian 2014, No.1601 10 kewenangan dan tanggung jawab penggunaan anggaran pada kementerian negara/lembaga yang bersangkutan.
6. Dokumen adalah data, catatan, dan/atau keterangan yang berkaitan dengan pengelolaan dan tanggung jawab keuangan negara, baik tertulis di atas kertas atau sarana lain, maupun terekam dalam bentuk/corak apa pun.
7. Kegiatan adalah bagian dari program yang dilaksanakan oleh satu atau beberapa Satuan Kerja sebagai bagian dari pencapaian sasaran terukur pada suatu program dan terdiri dari sekumpulan tindakan pengerahan sumber daya baik yang berupa personil (sumber daya manusia), barang modal termasuk peralatan dan teknologi, dana, atau kombinasi dari beberapa atau kesemua jenis sumber daya tersebut sebagai masukan (input) untuk menghasilkan keluaran (output) dalam bentuk barang/ jasa.
8. Daftar Isian Pelaksanaan Anggaran yang selanjutnya disebut DIPA adalah Dokumen Pelaksanaan Anggaran yang digunakan sebagai acuan PA dalam melaksanakan kegiatan pemerintahan sebagai pelaksanaan APBN.
9. Pejabat Pembuat Komitmen yang selanjutnya disingkat PPK adalah pejabat yang diberi kewenangan oleh PA/KPA untuk mengambil keputusan dan/atau melakukan tindakan yang dapat mengakibatkan pengeluaran anggaran belanja negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5960, '5. Kuasa Pengguna Anggaran yang selanjutnya disingkat KPA adalah pejabat yang memperoleh kuasa dari PA untuk melaksanakan sebagian 2014, No.1601 10 kewenangan dan tanggung jawab penggunaan anggaran pada kementerian negara/lembaga yang bersangkutan.
6. Dokumen adalah data, catatan, dan/atau keterangan yang berkaitan dengan pengelolaan dan tanggung jawab keuangan negara, baik tertulis di atas kertas atau sarana lain, maupun terekam dalam bentuk/corak apa pun.
7. Kegiatan adalah bagian dari program yang dilaksanakan oleh satu atau beberapa Satuan Kerja sebagai bagian dari pencapaian sasaran terukur pada suatu program dan terdiri dari sekumpulan tindakan pengerahan sumber daya baik yang berupa personil (sumber daya manusia), barang modal termasuk peralatan dan teknologi, dana, atau kombinasi dari beberapa atau kesemua jenis sumber daya tersebut sebagai masukan (input) untuk menghasilkan keluaran (output) dalam bentuk barang/ jasa.
8. Daftar Isian Pelaksanaan Anggaran yang selanjutnya disebut DIPA adalah Dokumen Pelaksanaan Anggaran yang digunakan sebagai acuan PA dalam melaksanakan kegiatan pemerintahan sebagai pelaksanaan APBN.
9. Pejabat Pembuat Komitmen yang selanjutnya disingkat PPK adalah pejabat yang diberi kewenangan oleh PA/KPA untuk mengambil keputusan dan/atau melakukan tindakan yang dapat mengakibatkan pengeluaran anggaran belanja negara.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5961, 'perka-10-2014', 15, 'lampiran', 'Lampiran hal. 10', NULL, 10, '10. Pejabat Penandatangan Surat Perintah Membayar yang selanjutnya disingkat PPSPM adalah pejabat yang diberi kewenangan oleh PA/KPA untuk melakukan pengujian atas permintaan pembayaran dan menerbitkan perintah pembayaran.
11. Bendahara Umum Negara yang selanjutnya disingkat BUN adalah pejabat yang diberi tugas untuk melaksanakan fungsi BUN.
12. Surat Permintaan Pembayaran yang selanjutnya disingkat SPP adalah dokumen yang diterbitkan oleh KPA/PPK, yang berisi permintaan pembayaran tagihan kepada negara.
13. Surat Perintah Membayar yang selanjutnya disingkat SPM adalah dokumen yang diterbitkan oleh PA/KPA atau pejabat lain yang ditunjuk untuk mencairkan dana yang bersumber dari DIPA atau dokumen lain yang dipersamakan.
14. Surat Perintah Pencairan Dana yang selanjutnya disebut SP2D adalah surat perintah yang diterbitkan oleh KPPN selaku Kuasa BUN untuk pelaksanaan pengeluaran atas beban APBN berdasarkan SPM.
15. Bendahara Pengeluaran yang selanjutnya disingkat BP adalah orang yang ditunjuk untuk menerima, menyimpan, membayarkan, menatausahakan, dan mempertanggungjawabkan uang untuk keperluan Belanja Negara dalam rangka pelaksanaan APBN pada kantor/Satuan Kerja Kementerian Negara/Lembaga Pemerintah Nonkementerian.
16. Bendahara Pengeluaran Pembantu yang selanjutnya disingkat BPP adalah orang yang ditunjuk untuk membantu Bendahara Pengeluaran untuk 11 2014, No.1601 melaksanakan pembayaran kepada yang berhak guna kelancaran pelaksanaan kegiatan tertentu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5961, '10. Pejabat Penandatangan Surat Perintah Membayar yang selanjutnya disingkat PPSPM adalah pejabat yang diberi kewenangan oleh PA/KPA untuk melakukan pengujian atas permintaan pembayaran dan menerbitkan perintah pembayaran.
11. Bendahara Umum Negara yang selanjutnya disingkat BUN adalah pejabat yang diberi tugas untuk melaksanakan fungsi BUN.
12. Surat Permintaan Pembayaran yang selanjutnya disingkat SPP adalah dokumen yang diterbitkan oleh KPA/PPK, yang berisi permintaan pembayaran tagihan kepada negara.
13. Surat Perintah Membayar yang selanjutnya disingkat SPM adalah dokumen yang diterbitkan oleh PA/KPA atau pejabat lain yang ditunjuk untuk mencairkan dana yang bersumber dari DIPA atau dokumen lain yang dipersamakan.
14. Surat Perintah Pencairan Dana yang selanjutnya disebut SP2D adalah surat perintah yang diterbitkan oleh KPPN selaku Kuasa BUN untuk pelaksanaan pengeluaran atas beban APBN berdasarkan SPM.
15. Bendahara Pengeluaran yang selanjutnya disingkat BP adalah orang yang ditunjuk untuk menerima, menyimpan, membayarkan, menatausahakan, dan mempertanggungjawabkan uang untuk keperluan Belanja Negara dalam rangka pelaksanaan APBN pada kantor/Satuan Kerja Kementerian Negara/Lembaga Pemerintah Nonkementerian.
16. Bendahara Pengeluaran Pembantu yang selanjutnya disingkat BPP adalah orang yang ditunjuk untuk membantu Bendahara Pengeluaran untuk 11 2014, No.1601 melaksanakan pembayaran kepada yang berhak guna kelancaran pelaksanaan kegiatan tertentu.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5962, 'perka-10-2014', 16, 'lampiran', 'Lampiran hal. 11', NULL, 11, '17. Kantor Pelayanan Perbendaharaan Negara yang selanjutnya disingkat KPPN adalah instansi vertikal Direktorat Jenderal Perbendaharaan yang memperoleh kuasa dari BUN untuk melaksanakan sebagian fungsi Kuasa BUN.
18. Satuan Kerja yang selanjutnya disebut Satker adalah unit organisasi lini kementerian negara/lembaga atau unit organisasi Pemerintah Daerah yang melaksanakan kegiatan kementerian negara/lembaga dan memiliki kewenangan dan tanggung jawab penggunaan anggaran.
19. Uang Persediaan yang selanjutnya disingkat UP adalah uang muka kerja dalam jumlah tertentu yang diberikan kepada Bendahara Pengeluaran untuk membiayai kegiatan operasional sehari-hari Satker atau membiayai pengeluaran yang menurut sifat dan tujuannya tidak mungkin dilakukan melalui mekanisme pembayaran langsung.
20. Pembayaran Langsung yang selanjutnya disebut Pembayaran LS adalah pembayaran yang dilakukan langsung kepada Bendahara Pengeluaran/penerima hak lainnya atas dasar perjanjian kerja, surat keputusan, surat tugas atau surat perintah kerja lainnya melalui penerbitan Surat Perintah Membayar Langsung.
21. Surat Permintaan Pembayaran Langsung yang selanjutnya disebut SPP-LS adalah dokumen yang diterbitkan oleh PPK, dalam rangka pembayaran tagihan kepada penerima hak/Bendahara Pengeluaran.
22. Surat Permintaan Pembayaran Penggantian Uang Persediaan Nihil yang selanjutnya disebut SPP-GUP Nihil adalah dokumen yang diterbitkan oleh PPK, yang berisi pertanggungjawaban UP.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5962, '17. Kantor Pelayanan Perbendaharaan Negara yang selanjutnya disingkat KPPN adalah instansi vertikal Direktorat Jenderal Perbendaharaan yang memperoleh kuasa dari BUN untuk melaksanakan sebagian fungsi Kuasa BUN.
18. Satuan Kerja yang selanjutnya disebut Satker adalah unit organisasi lini kementerian negara/lembaga atau unit organisasi Pemerintah Daerah yang melaksanakan kegiatan kementerian negara/lembaga dan memiliki kewenangan dan tanggung jawab penggunaan anggaran.
19. Uang Persediaan yang selanjutnya disingkat UP adalah uang muka kerja dalam jumlah tertentu yang diberikan kepada Bendahara Pengeluaran untuk membiayai kegiatan operasional sehari-hari Satker atau membiayai pengeluaran yang menurut sifat dan tujuannya tidak mungkin dilakukan melalui mekanisme pembayaran langsung.
20. Pembayaran Langsung yang selanjutnya disebut Pembayaran LS adalah pembayaran yang dilakukan langsung kepada Bendahara Pengeluaran/penerima hak lainnya atas dasar perjanjian kerja, surat keputusan, surat tugas atau surat perintah kerja lainnya melalui penerbitan Surat Perintah Membayar Langsung.
21. Surat Permintaan Pembayaran Langsung yang selanjutnya disebut SPP-LS adalah dokumen yang diterbitkan oleh PPK, dalam rangka pembayaran tagihan kepada penerima hak/Bendahara Pengeluaran.
22. Surat Permintaan Pembayaran Penggantian Uang Persediaan Nihil yang selanjutnya disebut SPP-GUP Nihil adalah dokumen yang diterbitkan oleh PPK, yang berisi pertanggungjawaban UP.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5963, 'perka-10-2014', 17, 'lampiran', 'Lampiran hal. 11', NULL, 11, '23. Surat Permintaan Pembayaran Pertanggungjawaban Tambahan Uang Persediaan yang selanjutnya disebut SPP-PTUP adalah dokumen yang diterbitkan oleh PPK, yang berisi permintaan pertanggungjawaban atas TUP.
24. Surat Perintah Membayar Langsung yang selanjutnya disebut SPM-LS adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan dana yang bersumber dari DIPA dalam rangka pembayaran tagihan kepada penerima hak/Bendahara Pengeluaran.
25. Surat Perintah Membayar Uang Persediaan yang selanjutnya disebut SPM-UP adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan UP.
26. Surat Perintah Bayar yang selanjutnya discbut dengan SPBy adalah bukti perintah PPK atas nama KPA kepada BP/BPP untuk mengeluarkan uang persediaan yang dikelola oleh BP/BPP sebagai pembayaran kepada pihak yang dituju.
27. Arsip Data Komputer yang selanjutnya disingkat ADK adalah arsip data dalam bentuk softcopy yang disimpan dalam media penyimpanan digital.
28. Verifikasi adalah satu bentuk pengawasan melalui pengujian terhadap 2014, No.1601 12 dokumen keuangan secara administratif dengan berpedoman dan kriteria yang berlaku.
29. Verifikator Satker adalah petugas yang ditunjuk pada setiap satker untuk melakukan verfikasi terhadap seluruh dokumen administrasi keuangan sebelum dilakukan proses pencairan dana.
30. Verifikator Keuangan adalah petugas yang ditunjuk pada Biro Keuangan untuk melakukan verifikasi terhadap seluruh dokumen administrasi keuangan untuk diproses pencairannya ke KPPN.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5963, '23. Surat Permintaan Pembayaran Pertanggungjawaban Tambahan Uang Persediaan yang selanjutnya disebut SPP-PTUP adalah dokumen yang diterbitkan oleh PPK, yang berisi permintaan pertanggungjawaban atas TUP.
24. Surat Perintah Membayar Langsung yang selanjutnya disebut SPM-LS adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan dana yang bersumber dari DIPA dalam rangka pembayaran tagihan kepada penerima hak/Bendahara Pengeluaran.
25. Surat Perintah Membayar Uang Persediaan yang selanjutnya disebut SPM-UP adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan UP.
26. Surat Perintah Bayar yang selanjutnya discbut dengan SPBy adalah bukti perintah PPK atas nama KPA kepada BP/BPP untuk mengeluarkan uang persediaan yang dikelola oleh BP/BPP sebagai pembayaran kepada pihak yang dituju.
27. Arsip Data Komputer yang selanjutnya disingkat ADK adalah arsip data dalam bentuk softcopy yang disimpan dalam media penyimpanan digital.
28. Verifikasi adalah satu bentuk pengawasan melalui pengujian terhadap 2014, No.1601 12 dokumen keuangan secara administratif dengan berpedoman dan kriteria yang berlaku.
29. Verifikator Satker adalah petugas yang ditunjuk pada setiap satker untuk melakukan verfikasi terhadap seluruh dokumen administrasi keuangan sebelum dilakukan proses pencairan dana.
30. Verifikator Keuangan adalah petugas yang ditunjuk pada Biro Keuangan untuk melakukan verifikasi terhadap seluruh dokumen administrasi keuangan untuk diproses pencairannya ke KPPN.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5964, 'perka-10-2014', 18, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'E. Sistematika Pedoman Verfikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana ini disusun dengan sistematika sebagai berikut:
BAB I PENDAHULUAN BAB II STRUKTUR DAN URAIAN TUGAS PENGELOLA KEUANGAN BAB III ASPEK DAN VERIFIKASI DOKUMEN BAB IV PENUTUP LAMPIRAN 13 2014, No.1601 BAB II STRUKTUR DAN URAIAN TUGAS PENGELOLA KEUANGAN A. Struktur Pengelola Keuangan pada BNPB Di lingkungan BNPB, terdapat Bagian Anggaran 103 (BA 103) dan sumber-sumber pembiayaan lainnya. Untuk pelaksanaan bagian anggaran dimaksud, BNPB membentuk 1 (satu) Kuasa Pengguna Anggaran (KPA), 1 (satu) Bendahara Pengeluaran (BP). Pada setiap unit kerja setingkat eselon II dibentuk 1 (satu) Pejabat Pembuat Komitmen (PPK) dan Bendahara Pengeluaran Pembantu (BPP). Mengingat di lingkungan BNPB terdapat unsur pengarah penanggulangan bencana di samping unsur pelaksana penanggulangan bencana sesuai dengan Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, maka pada Biro Perencanaan dibentuk 2 (dua) BPP, yaitu BPP Unsur Pengarah dan BPP Biro Perencanaan sendiri. Pada Biro Umum juga dibentuk 2 (dua) BPP, yaitu BPP Unsur Pimpinan dan BPP Biro Umum sendiri.
Di dalam penanggulangan bencana yang melibatkan Badan Penanggulangan Bencana Daerah (BPBD): Provinsi, Kabupaten/Kota, dan/atau kementerian/lembaga lainnya, KPA dapat menunjuk PPK dan BPP sesuai dengan kebutuhan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5964, 'E. Sistematika Pedoman Verfikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana ini disusun dengan sistematika sebagai berikut:
BAB I PENDAHULUAN BAB II STRUKTUR DAN URAIAN TUGAS PENGELOLA KEUANGAN BAB III ASPEK DAN VERIFIKASI DOKUMEN BAB IV PENUTUP LAMPIRAN 13 2014, No.1601 BAB II STRUKTUR DAN URAIAN TUGAS PENGELOLA KEUANGAN A. Struktur Pengelola Keuangan pada BNPB Di lingkungan BNPB, terdapat Bagian Anggaran 103 (BA 103) dan sumber-sumber pembiayaan lainnya. Untuk pelaksanaan bagian anggaran dimaksud, BNPB membentuk 1 (satu) Kuasa Pengguna Anggaran (KPA), 1 (satu) Bendahara Pengeluaran (BP). Pada setiap unit kerja setingkat eselon II dibentuk 1 (satu) Pejabat Pembuat Komitmen (PPK) dan Bendahara Pengeluaran Pembantu (BPP). Mengingat di lingkungan BNPB terdapat unsur pengarah penanggulangan bencana di samping unsur pelaksana penanggulangan bencana sesuai dengan Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, maka pada Biro Perencanaan dibentuk 2 (dua) BPP, yaitu BPP Unsur Pengarah dan BPP Biro Perencanaan sendiri. Pada Biro Umum juga dibentuk 2 (dua) BPP, yaitu BPP Unsur Pimpinan dan BPP Biro Umum sendiri.
Di dalam penanggulangan bencana yang melibatkan Badan Penanggulangan Bencana Daerah (BPBD): Provinsi, Kabupaten/Kota, dan/atau kementerian/lembaga lainnya, KPA dapat menunjuk PPK dan BPP sesuai dengan kebutuhan.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5965, 'perka-10-2014', 19, 'lampiran', 'Lampiran hal. 13', NULL, 13, 'Kepala BNPB selaku PA menetapkan pegawai/pejabat di lingkungan BNPB sebagai pengelola anggaran yang bertanggung jawab dalam pelaksanaan pengelolaan DIPA BNPB, yang meliputi:
1. KPA;
2. BP;
3. BPP; dan
4. Petugas Pengelola Dana Bantuan Dari Dalam Negeri dan Luar Negeri Untuk Penanggulangan Bencana.
KPA menunjuk pejabat pengelola anggaran lainnya yang meliputi:
1. PPK;
2. Pejabat Penanda Tangan SPM (PPSPM);
3. Pembantu Pejabat Penanda Tangan SPM (PPPSPM);
4. Petugas Pegelola Keuangan (pembantu administrasi PPK); dan
5. Petugas Pegelola Keuangan (pembantu administrasi PPK sebagai verifikator pada unit kerja).
2014, No.1601 14 B. Tugas Pengelola Anggaran di Bidang Verifikasi Uraian tugas masing-masing pejabat pengelola anggaran berkaitan dengan verifikasi adalah sebagai berikut:
1. KPA Di bidang verifikasi, KPA melakukan pengujian tagihan dan perintah pembayaran atas beban anggaran negara.
2. PPK mempunyai tugas dan wewenang:
Menguji dan menandatangani surat bukti mengenai hak tagih kepada negara, yang dilakukan dengan:
a. Menguji kebenaran materiil dan keabsahan surat-surat bukti mengenai hak tagih kepada negara dengan menguji:
1) kelengkapan dokumen tagihan;
2) kebenaran perhitungan tagihan;
3) kebenaran data pihak yang berhak menerima pembayaran atas beban APBN;
4) kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum dalam perjanjian/kontrak dengan barang/jasa yang diserahkan oleh penyedia barang/jasa;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5965, 'Kepala BNPB selaku PA menetapkan pegawai/pejabat di lingkungan BNPB sebagai pengelola anggaran yang bertanggung jawab dalam pelaksanaan pengelolaan DIPA BNPB, yang meliputi:
1. KPA;
2. BP;
3. BPP; dan
4. Petugas Pengelola Dana Bantuan Dari Dalam Negeri dan Luar Negeri Untuk Penanggulangan Bencana.
KPA menunjuk pejabat pengelola anggaran lainnya yang meliputi:
1. PPK;
2. Pejabat Penanda Tangan SPM (PPSPM);
3. Pembantu Pejabat Penanda Tangan SPM (PPPSPM);
4. Petugas Pegelola Keuangan (pembantu administrasi PPK); dan
5. Petugas Pegelola Keuangan (pembantu administrasi PPK sebagai verifikator pada unit kerja).
2014, No.1601 14 B. Tugas Pengelola Anggaran di Bidang Verifikasi Uraian tugas masing-masing pejabat pengelola anggaran berkaitan dengan verifikasi adalah sebagai berikut:
1. KPA Di bidang verifikasi, KPA melakukan pengujian tagihan dan perintah pembayaran atas beban anggaran negara.
2. PPK mempunyai tugas dan wewenang:
Menguji dan menandatangani surat bukti mengenai hak tagih kepada negara, yang dilakukan dengan:
a. Menguji kebenaran materiil dan keabsahan surat-surat bukti mengenai hak tagih kepada negara dengan menguji:
1) kelengkapan dokumen tagihan;
2) kebenaran perhitungan tagihan;
3) kebenaran data pihak yang berhak menerima pembayaran atas beban APBN;
4) kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum dalam perjanjian/kontrak dengan barang/jasa yang diserahkan oleh penyedia barang/jasa;', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5966, 'perka-10-2014', 20, 'lampiran', 'Lampiran hal. 14', NULL, 14, '5) kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/ kontrak;
6) kebenaran, keabsahan serta akibat yang timbul dari penggunaan surat bukti mengenai hak tagih kepada negara; dan 7) ketepatan jangka waktu penyelesaian pekerjaan sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/kontrak.
b. Menguji kebenaran dan keabsahan dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai.
3. PPSPM mempunyai tugas dan wewenang sebagai berikut:
a. Menguji ulang (review) kebenaran SPP yang diajukan oleh Pejabat Pembuat Komitmen beserta dokumen pendukung yang meliputi:
1) kelengkapan dokumen pendukung SPP;
2) kesesuaian penandatangan SPP dengan spesimen tandatangan PPK;
3) kebenaran pengisian format SPP;
4) kesesuaian kode BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Unit Kerja termasuk menguji kesesuaian antara 15 2014, No.1601 pembebanan kode mata anggaran pengeluaran (akun 6 digit) dengan uraiannya.
5) ketersediaan pagu sesuai dengan BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran unit kerja;
6) kebenaran formal dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai;
7) kebenaran formal dokumen/surat bukti yang menjadi persyaratan/kelengkapan sehubungan dengan pengadaan barang/jasa;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5966, '5) kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/ kontrak;
6) kebenaran, keabsahan serta akibat yang timbul dari penggunaan surat bukti mengenai hak tagih kepada negara; dan 7) ketepatan jangka waktu penyelesaian pekerjaan sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/kontrak.
b. Menguji kebenaran dan keabsahan dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai.
3. PPSPM mempunyai tugas dan wewenang sebagai berikut:
a. Menguji ulang (review) kebenaran SPP yang diajukan oleh Pejabat Pembuat Komitmen beserta dokumen pendukung yang meliputi:
1) kelengkapan dokumen pendukung SPP;
2) kesesuaian penandatangan SPP dengan spesimen tandatangan PPK;
3) kebenaran pengisian format SPP;
4) kesesuaian kode BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Unit Kerja termasuk menguji kesesuaian antara 15 2014, No.1601 pembebanan kode mata anggaran pengeluaran (akun 6 digit) dengan uraiannya.
5) ketersediaan pagu sesuai dengan BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran unit kerja;
6) kebenaran formal dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai;
7) kebenaran formal dokumen/surat bukti yang menjadi persyaratan/kelengkapan sehubungan dengan pengadaan barang/jasa;', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5967, 'perka-10-2014', 21, 'lampiran', 'Lampiran hal. 15', NULL, 15, '8) kebenaran pihak yang berhak menerima pembayaran pada SPP sehubungan dengan perjanjian/kontrak/surat keputusan;
9) kebenaran perhitungan tagihan serta kewajiban di bidang perpajakan dari pihak yang mempunyai hak tagih;
10) kepastian telah terpenuhinya kewajiban pembayaran kepada negara oleh pihak yang mempunyai hak tagih kepada negara; dan 11) kesesuaian prestasi pekerjaan dengan ketentuan pembayaran dalam perjanjian/kontrak.
b. Menolak dan mengembalikan SPP, apabila SPP tidak memenuhi persyaratan untuk dibayarkan;
Untuk membantu PPSPM, KPA dapat menunjuk beberapa orang staf dalam pengujian SPP.
4. BP mempunyai tugas dan wewenang:
a. Bendahara Pengeluaran melaksanakan pengujian yang meliputi:
1) meneliti kelengkapan perintah pembayaran yang diterbitkan oleh PPK;
2) pemeriksaan kebenaran atas hak tagih meliputi: a) pihak yang ditunjuk untuk menerima pembayaran; b) nilai tagihan yang harus dibayar; c) jadwal waktu pembayaran; dan d) menguji ketersediaan dana yang bersangkutan.
3) pemeriksaan kesesuaian pencapaian keluaran antara spesifikasi teknis yang disebutkan dalam penerimaan barang/jasa dan spesifikasi teknis yang disebutkan dalam dokumen pembayaran;
4) pemeriksaan dan pengujian ketepatan penggunaan kode mata anggaran pengeluaran (akun 6 digit).
b. Dalam hal pembayaran yang dilakukan oleh BP/BPP merupakan uang muka kerja kepada penanggung jawab kegiatan atau pihak lainnya, SPBy harus dilampiri dokumen sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5967, '8) kebenaran pihak yang berhak menerima pembayaran pada SPP sehubungan dengan perjanjian/kontrak/surat keputusan;
9) kebenaran perhitungan tagihan serta kewajiban di bidang perpajakan dari pihak yang mempunyai hak tagih;
10) kepastian telah terpenuhinya kewajiban pembayaran kepada negara oleh pihak yang mempunyai hak tagih kepada negara; dan 11) kesesuaian prestasi pekerjaan dengan ketentuan pembayaran dalam perjanjian/kontrak.
b. Menolak dan mengembalikan SPP, apabila SPP tidak memenuhi persyaratan untuk dibayarkan;
Untuk membantu PPSPM, KPA dapat menunjuk beberapa orang staf dalam pengujian SPP.
4. BP mempunyai tugas dan wewenang:
a. Bendahara Pengeluaran melaksanakan pengujian yang meliputi:
1) meneliti kelengkapan perintah pembayaran yang diterbitkan oleh PPK;
2) pemeriksaan kebenaran atas hak tagih meliputi: a) pihak yang ditunjuk untuk menerima pembayaran; b) nilai tagihan yang harus dibayar; c) jadwal waktu pembayaran; dan d) menguji ketersediaan dana yang bersangkutan.
3) pemeriksaan kesesuaian pencapaian keluaran antara spesifikasi teknis yang disebutkan dalam penerimaan barang/jasa dan spesifikasi teknis yang disebutkan dalam dokumen pembayaran;
4) pemeriksaan dan pengujian ketepatan penggunaan kode mata anggaran pengeluaran (akun 6 digit).
b. Dalam hal pembayaran yang dilakukan oleh BP/BPP merupakan uang muka kerja kepada penanggung jawab kegiatan atau pihak lainnya, SPBy harus dilampiri dokumen sebagai berikut:', 'Lampiran hal. 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5968, 'perka-10-2014', 22, 'lampiran', 'Lampiran hal. 16', NULL, 16, '2014, No.1601 16 1) Rencana pelaksanaan kegiatan/pembayaran;
2) Rincian kebutuhan dana; dan 3) Surat pernyataan tentang batas waktu pertanggungjawaban penggunaan uang muka kerja, dari penerima uang muka kerja.
5. BPP mempunyai tugas dan wewenang:
Di bidang verifikasi, BPP melakukan pengujian dan pembayaran atas tagihan yang dananya bersumber dari UP.
6. Petugas Pengelola Keuangan (Pengelola Administrasi PPK) memiliki tugas dan wewenang:
Pengelola Keuangan Pembantu PPK sebagai Verifikator pada unit kerja bertugas:
a. Membantu tugas rutin PPK dalam meneliti pengelolaan administrasi Bendahara Pengeluaran Pembantu;
b. Melaksanakan verifikasi pertanggungjawaban keuangan Bendahara Pengeluaran Pembantu; dan
c. Mengerjakan Kartu Pengawasan Anggaran yang sekaligus berfungsi sebagai alat monitoring anggaran.
17 2014, No.1601 BAB III ASPEK DAN VERIFIKASI DOKUMEN Verifikasi atau pengujian dilakukan terhadap dokumen yang melengkapi berkas pengajuan pembayaran atau pertanggungjawaban sesuai dengan kegiatan yang akan dan/atau telah dilakukan kepada PPK dan kepada PPSPM.
Pengujian dokumen pengajuan pembayaran dan/atau pertanggungjawaban atas pembayaran sebelum diajukan kepada Biro Keuangan dalam hal ini PPSPM dilakukan oleh verifikator unit kerja yang mengajukan dokumen tersebut terlebih dahulu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5968, '2014, No.1601 16 1) Rencana pelaksanaan kegiatan/pembayaran;
2) Rincian kebutuhan dana; dan 3) Surat pernyataan tentang batas waktu pertanggungjawaban penggunaan uang muka kerja, dari penerima uang muka kerja.
5. BPP mempunyai tugas dan wewenang:
Di bidang verifikasi, BPP melakukan pengujian dan pembayaran atas tagihan yang dananya bersumber dari UP.
6. Petugas Pengelola Keuangan (Pengelola Administrasi PPK) memiliki tugas dan wewenang:
Pengelola Keuangan Pembantu PPK sebagai Verifikator pada unit kerja bertugas:
a. Membantu tugas rutin PPK dalam meneliti pengelolaan administrasi Bendahara Pengeluaran Pembantu;
b. Melaksanakan verifikasi pertanggungjawaban keuangan Bendahara Pengeluaran Pembantu; dan
c. Mengerjakan Kartu Pengawasan Anggaran yang sekaligus berfungsi sebagai alat monitoring anggaran.
17 2014, No.1601 BAB III ASPEK DAN VERIFIKASI DOKUMEN Verifikasi atau pengujian dilakukan terhadap dokumen yang melengkapi berkas pengajuan pembayaran atau pertanggungjawaban sesuai dengan kegiatan yang akan dan/atau telah dilakukan kepada PPK dan kepada PPSPM.
Pengujian dokumen pengajuan pembayaran dan/atau pertanggungjawaban atas pembayaran sebelum diajukan kepada Biro Keuangan dalam hal ini PPSPM dilakukan oleh verifikator unit kerja yang mengajukan dokumen tersebut terlebih dahulu.', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5969, 'perka-10-2014', 23, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'Untuk memperoleh keyakinan yang memadai bahwa bukti pengeluaran telah dilengkapi dengan dokumen pendukungnya sesuai dengan jenis masing-masing bukti pengeluaran dimaksud, dilakukan verifikasi kelengkapan bukti pengeluaran, berdasarkan checklist yang telah dipersiapkan oleh verifikator.
Hal lain yang lebih penting adalah seorang verifikator harus mengetahui dan memahami ketentuan peraturan perundang-undangan mengenai pengelolaan keuangan negara termasuk pengadaan barang/jasa untuk menjadi dasar dari pengambilan keputusannya. Misalnya, apakah di dalam pengadaan barang/jasa dengan nilai di atas Rp200 juta, dokumen pendukung cukup dengan Surat Perintah Kerja (SPK) atau bukan dengan surat perjanjian. Apabila verifikator tidak mengetahui memahami ketentuan dimaksud dan salah penerapannya, maka dapat berakibat penolakan oleh PPSPM pada saat pengajuan berkas pembayaran.
A. Aspek Verifikasi Verifikasi pada umumnya dilakukan mencakup beberapa aspek, yaitu:
1. Ketersediaan Dana Verifikasi ketersediaan dana dilakukan untuk memastikan bahwa dana untuk membiayai suatu kegiatan yang tercantum dalam tanda bukti masih cukup tersedia dalam DIPA.
Dokumen yang diperlukan dalam verifikasi ketersediaan dana, yaitu:  Petunjuk Operasional Kegiatan (POK);  Kartu Pengawasan Anggaran.
BPP memeriksa ketersediaan dana dengan membandingkan jumlah pencairan dana dengan kartu pengawasan anggaran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5969, 'Untuk memperoleh keyakinan yang memadai bahwa bukti pengeluaran telah dilengkapi dengan dokumen pendukungnya sesuai dengan jenis masing-masing bukti pengeluaran dimaksud, dilakukan verifikasi kelengkapan bukti pengeluaran, berdasarkan checklist yang telah dipersiapkan oleh verifikator.
Hal lain yang lebih penting adalah seorang verifikator harus mengetahui dan memahami ketentuan peraturan perundang-undangan mengenai pengelolaan keuangan negara termasuk pengadaan barang/jasa untuk menjadi dasar dari pengambilan keputusannya. Misalnya, apakah di dalam pengadaan barang/jasa dengan nilai di atas Rp200 juta, dokumen pendukung cukup dengan Surat Perintah Kerja (SPK) atau bukan dengan surat perjanjian. Apabila verifikator tidak mengetahui memahami ketentuan dimaksud dan salah penerapannya, maka dapat berakibat penolakan oleh PPSPM pada saat pengajuan berkas pembayaran.
A. Aspek Verifikasi Verifikasi pada umumnya dilakukan mencakup beberapa aspek, yaitu:
1. Ketersediaan Dana Verifikasi ketersediaan dana dilakukan untuk memastikan bahwa dana untuk membiayai suatu kegiatan yang tercantum dalam tanda bukti masih cukup tersedia dalam DIPA.
Dokumen yang diperlukan dalam verifikasi ketersediaan dana, yaitu:  Petunjuk Operasional Kegiatan (POK);  Kartu Pengawasan Anggaran.
BPP memeriksa ketersediaan dana dengan membandingkan jumlah pencairan dana dengan kartu pengawasan anggaran.', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5970, 'perka-10-2014', 24, 'lampiran', 'Lampiran hal. 18', NULL, 18, '2014, No.1601 18 Apabila dana yang hendak dicairkan tidak tersedia, maka BPP dapat mengembalikan dokumen pencairan dana kepada Pejabat Pembuat Komitmen untuk diperbaiki atau membatalkan proses pencairan dana.
2. Ketepatan Tujuan Pengeluaran Verifikasi ketepatan tujuan pengeluaran dilakukan untuk memperoleh kepastian bahwa pengeluaran yang tercantum pada tanda bukti transaksi telah sesuai dengan tujuan belanja dan tujuan kegiatan dalam DIPA.
Verifikator Unit kerja memeriksa ketepatan tujuan pengeluaran dengan melihat apakah tujuan pembayaran suatu tagihan telah sesuai dengan jenis/klasifikasi belanjanya dan telah sesuai dengan tujuan kegiatan dalam DIPA.
Apabila tujuan pembayaran tidak sesuai dengan jenis/klasifikasi belanjanya dan/atau tujuan kegiatan dalam DIPA, maka Verifikator di Biro Keuangan wajib mengembalikan dokumen pencairan dana kepada BPP untuk diperbaiki atau membatalkan proses pencairan dana apabila dianggap perlu.
3. Kesesuaian Pembebanan Anggaran Verifikasi kesesuaian pembebanan anggaran dilakukan untuk memperoleh kepastian bahwa pengeluaran yang tercantum dalam tanda bukti transaksi telah dibebankan sesuai dengan akun belanja pada kegiatan yang ditetapkan dalam DIPA.
Verifikator Keuangan memeriksa kebenaran pembebanan anggaran dengan melihat kesesuaian pembebanan antara pembebanan pada kertas kerja dan pembebanan yang dicantumkan pada dokumen pencairan dana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5970, '2014, No.1601 18 Apabila dana yang hendak dicairkan tidak tersedia, maka BPP dapat mengembalikan dokumen pencairan dana kepada Pejabat Pembuat Komitmen untuk diperbaiki atau membatalkan proses pencairan dana.
2. Ketepatan Tujuan Pengeluaran Verifikasi ketepatan tujuan pengeluaran dilakukan untuk memperoleh kepastian bahwa pengeluaran yang tercantum pada tanda bukti transaksi telah sesuai dengan tujuan belanja dan tujuan kegiatan dalam DIPA.
Verifikator Unit kerja memeriksa ketepatan tujuan pengeluaran dengan melihat apakah tujuan pembayaran suatu tagihan telah sesuai dengan jenis/klasifikasi belanjanya dan telah sesuai dengan tujuan kegiatan dalam DIPA.
Apabila tujuan pembayaran tidak sesuai dengan jenis/klasifikasi belanjanya dan/atau tujuan kegiatan dalam DIPA, maka Verifikator di Biro Keuangan wajib mengembalikan dokumen pencairan dana kepada BPP untuk diperbaiki atau membatalkan proses pencairan dana apabila dianggap perlu.
3. Kesesuaian Pembebanan Anggaran Verifikasi kesesuaian pembebanan anggaran dilakukan untuk memperoleh kepastian bahwa pengeluaran yang tercantum dalam tanda bukti transaksi telah dibebankan sesuai dengan akun belanja pada kegiatan yang ditetapkan dalam DIPA.
Verifikator Keuangan memeriksa kebenaran pembebanan anggaran dengan melihat kesesuaian pembebanan antara pembebanan pada kertas kerja dan pembebanan yang dicantumkan pada dokumen pencairan dana.', 'Lampiran hal. 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5971, 'perka-10-2014', 25, 'lampiran', 'Lampiran hal. 18', NULL, 18, 'Apabila pembebanan anggaran tidak sesuai dengan kertas kerja anggaran, maka Verifikator Keuangan dapat mengembalikan dokumen pencairan dana kepada Koordinator Verifikator untuk diperbaiki atau membatalkan proses pencairan dana apabila dianggap perlu dengan sepengetahuan PPSPM.
4. Kebenaran Tagihan Verifikasi kebenaran tagihan dilakukan untuk memperoleh kepastian kebenaran dalam hal perhitungan atas jumlah angka, kepastian kebenaran atas dokumen-dokumen yang terkait dengan proses pembayaran, apakah telah sesuai dengan ketentuan yang berlaku.
19 2014, No.1601 Verifikator di Biro Keuangan memeriksa kebenaran tagihan dengan memeriksa apakah seluruh isi pokok dokumen pencairan dana telah disusun sesuai dengan ketetentuan.
Verifikator di Biro Keuangan menguji perhitungan atas jumlah angka berupa penjumlahan, pengurangan, perkalian dan pembagian yang terdapat pada dokumen pencairan dana.
Apabila terdapat kesalahan perhitungan, kesalahan penyusunan isi pokok dokumen pencairan dana, maka Verifikator di Biro Keuangan wajib mengembalikan dokumen pencairan dana kepada Koordinator Verifikator untuk diperbaiki atau membatalkan proses pencairan dana apabila dianggap perlu.
5. Kelengkapan Dokumen Verifikasi kelengkapan bukti pengeluaran dilakukan untuk memperoleh kepastian bahwa dokumen pencairan dana telah lengkap untuk diproses lebih lanjut sesuai dengan ketentuan yang berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5971, 'Apabila pembebanan anggaran tidak sesuai dengan kertas kerja anggaran, maka Verifikator Keuangan dapat mengembalikan dokumen pencairan dana kepada Koordinator Verifikator untuk diperbaiki atau membatalkan proses pencairan dana apabila dianggap perlu dengan sepengetahuan PPSPM.
4. Kebenaran Tagihan Verifikasi kebenaran tagihan dilakukan untuk memperoleh kepastian kebenaran dalam hal perhitungan atas jumlah angka, kepastian kebenaran atas dokumen-dokumen yang terkait dengan proses pembayaran, apakah telah sesuai dengan ketentuan yang berlaku.
19 2014, No.1601 Verifikator di Biro Keuangan memeriksa kebenaran tagihan dengan memeriksa apakah seluruh isi pokok dokumen pencairan dana telah disusun sesuai dengan ketetentuan.
Verifikator di Biro Keuangan menguji perhitungan atas jumlah angka berupa penjumlahan, pengurangan, perkalian dan pembagian yang terdapat pada dokumen pencairan dana.
Apabila terdapat kesalahan perhitungan, kesalahan penyusunan isi pokok dokumen pencairan dana, maka Verifikator di Biro Keuangan wajib mengembalikan dokumen pencairan dana kepada Koordinator Verifikator untuk diperbaiki atau membatalkan proses pencairan dana apabila dianggap perlu.
5. Kelengkapan Dokumen Verifikasi kelengkapan bukti pengeluaran dilakukan untuk memperoleh kepastian bahwa dokumen pencairan dana telah lengkap untuk diproses lebih lanjut sesuai dengan ketentuan yang berlaku.', 'Lampiran hal. 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5972, 'perka-10-2014', 26, 'lampiran', 'Lampiran hal. 19', NULL, 19, 'Verifikator Keuangan memeriksa kelengkapan bukti pengeluaran dengan melakukan check list terhadap kelengkapan dokumen pencairan dana atau dokumen pertanggungjawaban.
Apabila dokumen pencairan dana tidak lengkap, maka Verifikator Keuangan dapat mengembalikan dokumen pencairan dana kepada Koordinator Administrasi untuk dilengkapi atau membatalkan proses pencairan dana apabila dianggap perlu dengan sepengetahuan Kepala Bagian Pelaksanaan Anggaran.
B. Pelaksanaan Verifikasi Pejabat Perbendaharaan Negara adalah Pengguna Anggaran (PA), Kuasa Pengguna Anggaran (KPA), Pejabat Pembuat Komitmen (PPK), Pejabat Penanda Tangan SPM (PPSPM), Bendahara Umum Negara (BUN), Bendahara Pengeluaran (BP), dan Bendahara Pengeluaran Pembantu (BPP). Para Pejabat Perbendaharaan Negara tersebut sesuai dengan peraturan perundang-undangan mempunyai tugas dan wewenang untuk melakukan pengujian terhadap dokumen pertanggungjawaban keuangan sebelum dilakukan pembayaran tagihan kepada negara.
Verifikasi yang dilakukan di lingkungan Biro Keuangan bertujuan mendapatkan kebenaran formal, yakni pelaksanaan verifikasi pada umumnya dilakukan dengan verifikasi kebenaran pengisian dokumen tanda bukti.
Verifikasi dilakukan berkaitan dengan kebenaran tagihan untuk memperoleh 2014, No.1601 20 kepastian bahwa pengeluaran telah benar dan dibuat sesuai dengan ketentuan yang berlaku serta kebenaran perhitungan terhadap dokumen yang bersangkutan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5972, 'Verifikator Keuangan memeriksa kelengkapan bukti pengeluaran dengan melakukan check list terhadap kelengkapan dokumen pencairan dana atau dokumen pertanggungjawaban.
Apabila dokumen pencairan dana tidak lengkap, maka Verifikator Keuangan dapat mengembalikan dokumen pencairan dana kepada Koordinator Administrasi untuk dilengkapi atau membatalkan proses pencairan dana apabila dianggap perlu dengan sepengetahuan Kepala Bagian Pelaksanaan Anggaran.
B. Pelaksanaan Verifikasi Pejabat Perbendaharaan Negara adalah Pengguna Anggaran (PA), Kuasa Pengguna Anggaran (KPA), Pejabat Pembuat Komitmen (PPK), Pejabat Penanda Tangan SPM (PPSPM), Bendahara Umum Negara (BUN), Bendahara Pengeluaran (BP), dan Bendahara Pengeluaran Pembantu (BPP). Para Pejabat Perbendaharaan Negara tersebut sesuai dengan peraturan perundang-undangan mempunyai tugas dan wewenang untuk melakukan pengujian terhadap dokumen pertanggungjawaban keuangan sebelum dilakukan pembayaran tagihan kepada negara.
Verifikasi yang dilakukan di lingkungan Biro Keuangan bertujuan mendapatkan kebenaran formal, yakni pelaksanaan verifikasi pada umumnya dilakukan dengan verifikasi kebenaran pengisian dokumen tanda bukti.
Verifikasi dilakukan berkaitan dengan kebenaran tagihan untuk memperoleh 2014, No.1601 20 kepastian bahwa pengeluaran telah benar dan dibuat sesuai dengan ketentuan yang berlaku serta kebenaran perhitungan terhadap dokumen yang bersangkutan.', 'Lampiran hal. 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5973, 'perka-10-2014', 27, 'lampiran', 'Lampiran hal. 20', NULL, 20, 'Kebenaran pengisian dokumen tanda bukti meliputi antara lain: kuitansi, perjanjian/kontrak, Surat Perintah Kerja (SPK), Berita Acara Pemeriksaan Hasil Pekerjaan/Penyerahan Barang, Berita Acara Serah Terima Pekerjaan, Berita Acara Pembayaran, dan/atau dokumen pembayaran lainnya.
Kebenaran Perhitungan meliputi: perhitungan perkalian, perhitungan penjumlahan, perhitungan potongan (pajak), dan/atau penerapan tarif yang sesuai dengan berlaku.
Pelaksanaan verifikasi di dalam Pedoman Verifikasi ini tidak termasuk pengaturan verifikasi yang berkaitan dengan pembayaran gaji dan pembayaran pendapatan lainnya bagi pegawai di lingkungan BNPB.
1. Pelaksanaan Verifikasi Dana Nonpenanggulangan Bencana
a. Verifikasi di Lingkungan unit kerja 1) Pelaksana Verifikasi Verifikasi di lingkungan unit kerja dilakukan oleh Pejabat Pembuat Komitmen (PPK), Bendahara Pengeluaran Pembantu (BPP) dan pengelola keuangan pada masing-masing unit kerja yang ditunjuk sebagai verifikator berdasarkan surat keputusan.
2) Proses Verifikasi Alur verifikasi sebagaimana bagan alur terlampir (Lampiran II). a) Verifikasi oleh Pengelola Keuangan Verifikasi yang dilakukan oleh Pengelola Keuangan meliputi:
(1) Ketersediaan anggaran, keluaran, dan kode akun dengan memperhatikan antara lain:  Ada/tidak Revisi, jika ya, sebutkan Revisi ke - dan Tanggal ---  Apakah biaya kegiatan tersedia dalam DIPA.  Adakah kesesuaian kode kegiatan.  Apakah kesesuaian kode output/komponen.  Apakah kesesuaian kode akun.
21 2014, No.1601');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5973, 'Kebenaran pengisian dokumen tanda bukti meliputi antara lain: kuitansi, perjanjian/kontrak, Surat Perintah Kerja (SPK), Berita Acara Pemeriksaan Hasil Pekerjaan/Penyerahan Barang, Berita Acara Serah Terima Pekerjaan, Berita Acara Pembayaran, dan/atau dokumen pembayaran lainnya.
Kebenaran Perhitungan meliputi: perhitungan perkalian, perhitungan penjumlahan, perhitungan potongan (pajak), dan/atau penerapan tarif yang sesuai dengan berlaku.
Pelaksanaan verifikasi di dalam Pedoman Verifikasi ini tidak termasuk pengaturan verifikasi yang berkaitan dengan pembayaran gaji dan pembayaran pendapatan lainnya bagi pegawai di lingkungan BNPB.
1. Pelaksanaan Verifikasi Dana Nonpenanggulangan Bencana
a. Verifikasi di Lingkungan unit kerja 1) Pelaksana Verifikasi Verifikasi di lingkungan unit kerja dilakukan oleh Pejabat Pembuat Komitmen (PPK), Bendahara Pengeluaran Pembantu (BPP) dan pengelola keuangan pada masing-masing unit kerja yang ditunjuk sebagai verifikator berdasarkan surat keputusan.
2) Proses Verifikasi Alur verifikasi sebagaimana bagan alur terlampir (Lampiran II). a) Verifikasi oleh Pengelola Keuangan Verifikasi yang dilakukan oleh Pengelola Keuangan meliputi:
(1) Ketersediaan anggaran, keluaran, dan kode akun dengan memperhatikan antara lain:  Ada/tidak Revisi, jika ya, sebutkan Revisi ke - dan Tanggal ---  Apakah biaya kegiatan tersedia dalam DIPA.  Adakah kesesuaian kode kegiatan.  Apakah kesesuaian kode output/komponen.  Apakah kesesuaian kode akun.
21 2014, No.1601', 'Lampiran hal. 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5974, 'perka-10-2014', 28, 'lampiran', 'Lampiran hal. 21', NULL, 21, '(2) Pengecekan aritmatik, nominal, standar, dan tanda tangan dengan memperhatikan antara lain:  Kebenaran pengalian dan penjumlahan.  Kebenaran penulisan kalimat “terbilang” pada kuitansi dan antar bukti terkait dalam penulisan angka dan huruf.  Kebenaran penulisan tanggal pada kuitansi dan bukti terkait.  Kebenaran pengenaan tarif dan jumlah perhitungan potongan pajak (PPN, PPh Pasal 21, Pasal 22, Pasal 23, Pasal 4 ayat (2) dan Pasal 15.  Apakah penulisan nominal pada kuitansi dan SPTB sudah sesuai.  Kebenaran penulisan nomor rekening dan NPWP.  Apakah penerapan tarif biaya sudah sesuai dengan Standar Biaya Masukan (SBM).  Kelengkapan tanda tangan dokumen terkait.
(3) Pengecekan lainnya Pengecekan lainnya sesuai dengan dokumen pertanggungjawaban/kelengkapan dokumen yang diajukan seperti: LS Bendahara, LS Pihak Ketiga, GU Nihil (TUP), GU Isi (GUP), dan/atau SPBy. b) Verifikasi oleh Bendahara Pengeluaran Pembantu Verifikasi yang dilakukan oleh Bendahara Pengeluaran Pembantu sesuai dengan SPBy sebagaimana terlampir pada contoh format Lampiran VI meliputi:
(1) Meneliti kelengkapan perintah pembayaran yang diterbitkan oleh PPK;
(2) Pemeriksaan kebenaran atas hak tagih, meliputi:  Pihak yang ditunjuk untuk menerima pembayaran;  Nilai tagihan yang harus dibayar;  Jadwal waktu pembayaran; dan  Menguji ketersediaan dana yang bersangkutan.
2014, No.1601 22');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5974, '(2) Pengecekan aritmatik, nominal, standar, dan tanda tangan dengan memperhatikan antara lain:  Kebenaran pengalian dan penjumlahan.  Kebenaran penulisan kalimat “terbilang” pada kuitansi dan antar bukti terkait dalam penulisan angka dan huruf.  Kebenaran penulisan tanggal pada kuitansi dan bukti terkait.  Kebenaran pengenaan tarif dan jumlah perhitungan potongan pajak (PPN, PPh Pasal 21, Pasal 22, Pasal 23, Pasal 4 ayat (2) dan Pasal 15.  Apakah penulisan nominal pada kuitansi dan SPTB sudah sesuai.  Kebenaran penulisan nomor rekening dan NPWP.  Apakah penerapan tarif biaya sudah sesuai dengan Standar Biaya Masukan (SBM).  Kelengkapan tanda tangan dokumen terkait.
(3) Pengecekan lainnya Pengecekan lainnya sesuai dengan dokumen pertanggungjawaban/kelengkapan dokumen yang diajukan seperti: LS Bendahara, LS Pihak Ketiga, GU Nihil (TUP), GU Isi (GUP), dan/atau SPBy. b) Verifikasi oleh Bendahara Pengeluaran Pembantu Verifikasi yang dilakukan oleh Bendahara Pengeluaran Pembantu sesuai dengan SPBy sebagaimana terlampir pada contoh format Lampiran VI meliputi:
(1) Meneliti kelengkapan perintah pembayaran yang diterbitkan oleh PPK;
(2) Pemeriksaan kebenaran atas hak tagih, meliputi:  Pihak yang ditunjuk untuk menerima pembayaran;  Nilai tagihan yang harus dibayar;  Jadwal waktu pembayaran; dan  Menguji ketersediaan dana yang bersangkutan.
2014, No.1601 22', 'Lampiran hal. 21', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5975, 'perka-10-2014', 29, 'lampiran', 'Lampiran hal. 22', NULL, 22, '(3) Pemeriksaan kesesuaian pencapaian keluaran antara spesifikasi teknis yang disebutkan dalam penerimaan barang/jasa dan spesifikasi teknis yang disebutkan dalam dokumen perjanjian/kontrak; dan
(4) Pemeriksaan dan pengujian ketepatan penggunaan kode mata anggaran pengeluaran (akun 6 digit)
(5) Pengecekan lainnya Pengecekan lainnya sesuai dengan dokumen pertanggungjawaban/kelengkapan dokumen yang diajukan seperti: LS Bendahara, LS Pihak Ketiga, GU Nihil (TUP), GU Isi (GUP), dan/atau SPBy. c) Verifikasi oleh Pejabat Pembuat Komitmen Verifikasi yang dilakukan oleh Pejabat Pembuat Komitmen meliputi:
(1) menguji kebenaran materiil dan keabsahan surat-surat bukti mengenai hak tagih kepada negara; dan/atau
(2) menguji kebenaran dan keabsahan dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai.
(3) Dalam hal surat-surat bukti mengenai hak tagih kepada negara berupa surat jaminan uang muka, pengujian kebenaran materiil dan keabsahan dilakukan dengan:  menguji syarat-syarat kebenaran dan keabsahan jaminan uang muka; dan  menguji tagihan uang muka berupa besaran uang muka yang dapat dibayarkan sesuai dengan ketentuan mengenai pengadaan barang/jasa pemerintah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5975, '(3) Pemeriksaan kesesuaian pencapaian keluaran antara spesifikasi teknis yang disebutkan dalam penerimaan barang/jasa dan spesifikasi teknis yang disebutkan dalam dokumen perjanjian/kontrak; dan
(4) Pemeriksaan dan pengujian ketepatan penggunaan kode mata anggaran pengeluaran (akun 6 digit)
(5) Pengecekan lainnya Pengecekan lainnya sesuai dengan dokumen pertanggungjawaban/kelengkapan dokumen yang diajukan seperti: LS Bendahara, LS Pihak Ketiga, GU Nihil (TUP), GU Isi (GUP), dan/atau SPBy. c) Verifikasi oleh Pejabat Pembuat Komitmen Verifikasi yang dilakukan oleh Pejabat Pembuat Komitmen meliputi:
(1) menguji kebenaran materiil dan keabsahan surat-surat bukti mengenai hak tagih kepada negara; dan/atau
(2) menguji kebenaran dan keabsahan dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai.
(3) Dalam hal surat-surat bukti mengenai hak tagih kepada negara berupa surat jaminan uang muka, pengujian kebenaran materiil dan keabsahan dilakukan dengan:  menguji syarat-syarat kebenaran dan keabsahan jaminan uang muka; dan  menguji tagihan uang muka berupa besaran uang muka yang dapat dibayarkan sesuai dengan ketentuan mengenai pengadaan barang/jasa pemerintah.', 'Lampiran hal. 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5976, 'perka-10-2014', 30, 'lampiran', 'Lampiran hal. 22', NULL, 22, '(4) Dalam membuat dan menandatangani SPP, menguji:  kelengkapan dokumen tagihan;  kebenaran perhitungan tagihan;  kebenaran data pihak yang berhak menerima pembayaran atas beban APBN;  kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum dalam perjanjian/ kontrak 23 2014, No.1601 dengan barang/jasa yang diserahkan oleh penyedia barang/jasa;  kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/ kontrak;  kebenaran, keabsahan serta akibat yang timbul dari penggunaan surat bukti mengenai hak tagih kepada negara; dan  ketepatan jangka waktu penyelesaian pekerjaan sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/ kontrak.
b. Verifikasi di Biro Keuangan 1) Pelaksana Verifikasi Setelah verifikasi dilaksanakan oleh unit kerja selanjutnya verifikasi secara formal dilaksanakan oleh Biro Keuangan yang meliputi:
(a) Petugas/Verifikator;
(b) Subkoordinator Verifikator;
(c) Koordinator Verifikator;
(d) Bendahara Pengeluaran; dan
(e) PPSPM.
2) Proses Verifikasi Verifikasi yang dilaksanakan oleh Biro Keuangan dilaksanakan oleh Petugas/Verifikator, Subkoordinator Verifikator, Koordinator Verifikator, Bendahara Pengeluaran, dan PPSPM dengan mekanisme alur verifikasi sebagaimana bagan alur terlampir (Lampiran III).
3) Petugas Verifikasi/Verifikator Verifikasi yang dilakukan oleh Petugas Verifikasi (Verifikator) meliputi:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5976, '(4) Dalam membuat dan menandatangani SPP, menguji:  kelengkapan dokumen tagihan;  kebenaran perhitungan tagihan;  kebenaran data pihak yang berhak menerima pembayaran atas beban APBN;  kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum dalam perjanjian/ kontrak 23 2014, No.1601 dengan barang/jasa yang diserahkan oleh penyedia barang/jasa;  kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/ kontrak;  kebenaran, keabsahan serta akibat yang timbul dari penggunaan surat bukti mengenai hak tagih kepada negara; dan  ketepatan jangka waktu penyelesaian pekerjaan sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/ kontrak.
b. Verifikasi di Biro Keuangan 1) Pelaksana Verifikasi Setelah verifikasi dilaksanakan oleh unit kerja selanjutnya verifikasi secara formal dilaksanakan oleh Biro Keuangan yang meliputi:
(a) Petugas/Verifikator;
(b) Subkoordinator Verifikator;
(c) Koordinator Verifikator;
(d) Bendahara Pengeluaran; dan
(e) PPSPM.
2) Proses Verifikasi Verifikasi yang dilaksanakan oleh Biro Keuangan dilaksanakan oleh Petugas/Verifikator, Subkoordinator Verifikator, Koordinator Verifikator, Bendahara Pengeluaran, dan PPSPM dengan mekanisme alur verifikasi sebagaimana bagan alur terlampir (Lampiran III).
3) Petugas Verifikasi/Verifikator Verifikasi yang dilakukan oleh Petugas Verifikasi (Verifikator) meliputi:', 'Lampiran hal. 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5977, 'perka-10-2014', 31, 'lampiran', 'Lampiran hal. 23', NULL, 23, '(a) Ketersediaan anggaran, keluaran, dan kode akun dengan memperhatikan antara lain:  Ada/tidak Revisi, jika ya, sebutkan Revisi ke - dan Tanggal – 2014, No.1601 24  Apakah biaya kegiatan tersedia dalam DIPA.  Adakah kesesuaian kode kegiatan.  Apakah kesesuaian kode output/komponen.  Apakah kesesuaian kode akun.
(b) Pengecekan aritmatik, nominal, standar, dan tanda tangan dengan memperhatikan antara lain:  Kebenaran pengalian dan penjumlahan.  Kebenaran penulisan kalimat “terbilang” pada kuitansi dan antar bukti terkait dalam penulisan angka dan huruf.  Kebenaran penulisan tanggal pada kuitansi dan bukti terkait.  Kebenaran pengenaan tarif dan jumlah perhitungan potongan pajak (PPN, PPh Pasal 21, Pasal 22, Pasal 23, Pasal 4 ayat (2) dan Pasal 15).  Apakah penulisan nominal pada kuitansi dan SPTB sudah sesuai.  Kebenaran penulisan nomor rekening dan NPWP.  Apakah penerapan tarif biaya sudah sesuai dengan Standar Biaya Masukan (SBM).  Kelengkapan tanda tangan dokumen terkait.
4) Subkoordinator Verifikator Verifikasi yang dilakukan oleh Subkoordinator meliputi:
(a) Ketersediaan anggaran, keluaran, dan kode akun dengan memperhatikan antara lain:  Ada/tidak Revisi, jika ya, sebutkan Revisi ke - dan Tanggal –  Apakah biaya kegiatan tersedia dalam DIPA.  Adakah kesesuaian kode kegiatan.  Apakah kesesuaian kode output/komponen.  Apakah kesesuaian kode akun.
(b) Pengecekan aritmatik, nominal, standar, dan tanda tangan dengan memperhatikan antara lain:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5977, '(a) Ketersediaan anggaran, keluaran, dan kode akun dengan memperhatikan antara lain:  Ada/tidak Revisi, jika ya, sebutkan Revisi ke - dan Tanggal – 2014, No.1601 24  Apakah biaya kegiatan tersedia dalam DIPA.  Adakah kesesuaian kode kegiatan.  Apakah kesesuaian kode output/komponen.  Apakah kesesuaian kode akun.
(b) Pengecekan aritmatik, nominal, standar, dan tanda tangan dengan memperhatikan antara lain:  Kebenaran pengalian dan penjumlahan.  Kebenaran penulisan kalimat “terbilang” pada kuitansi dan antar bukti terkait dalam penulisan angka dan huruf.  Kebenaran penulisan tanggal pada kuitansi dan bukti terkait.  Kebenaran pengenaan tarif dan jumlah perhitungan potongan pajak (PPN, PPh Pasal 21, Pasal 22, Pasal 23, Pasal 4 ayat (2) dan Pasal 15).  Apakah penulisan nominal pada kuitansi dan SPTB sudah sesuai.  Kebenaran penulisan nomor rekening dan NPWP.  Apakah penerapan tarif biaya sudah sesuai dengan Standar Biaya Masukan (SBM).  Kelengkapan tanda tangan dokumen terkait.
4) Subkoordinator Verifikator Verifikasi yang dilakukan oleh Subkoordinator meliputi:
(a) Ketersediaan anggaran, keluaran, dan kode akun dengan memperhatikan antara lain:  Ada/tidak Revisi, jika ya, sebutkan Revisi ke - dan Tanggal –  Apakah biaya kegiatan tersedia dalam DIPA.  Adakah kesesuaian kode kegiatan.  Apakah kesesuaian kode output/komponen.  Apakah kesesuaian kode akun.
(b) Pengecekan aritmatik, nominal, standar, dan tanda tangan dengan memperhatikan antara lain:', 'Lampiran hal. 23', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5978, 'perka-10-2014', 32, 'lampiran', 'Lampiran hal. 25', NULL, 25, '25 2014, No.1601  Kebenaran pengalian dan penjumlahan.  Kebenaran penulisan kalimat “terbilang” pada kuitansi dan antar bukti terkait dalam penulisan angka dan huruf.  Kebenaran penulisan tanggal pada kuitansi dan bukti terkait.  Kebenaran pengenaan tarif dan jumlah perhitungan potongan pajak (PPN, PPh Pasal 21, Pasal 22, Pasal 23, Pasal 4 ayat (2) dan Pasal 15).  Apakah penulisan nominal pada kuitansi dan SPTB sudah sesuai.  Kebenaran penulisan nomor rekening dan NPWP.  Apakah penerapan tarif biaya sudah sesuai dengan Standar Biaya Masukan (SBM).  Kelengkapan tanda tangan dokumen terkait.
5) Koordinator Verifikator Verifikasi yang dilakukan oleh Koordinator Verifikator adalah menitikberatkan pada hasil verifikasi yang telah dilakukan oleh petugas verifikator dan Subkoordinator verifikator.
6) Bendahara Pengeluaran Verifikasi yang dilakukan oleh Bendahara Pengeluaran sesuai dengan SPBy sebagaimana terlampir pada contoh format Lampiran VI meliputi:
(a) meneliti kelengkapan perintah pembayaran yang diterbitkan oleh PPK;
(b) pemeriksaan kebenaran atas hak tagih, meliputi:  pihak yang ditunjuk untuk menerima pembayaran;  nilai tagihan yang harus dibayar;  jadwal waktu pembayaran; dan  menguji ketersediaan dana yang bersangkutan.
(c) pemeriksaan kesesuaian pencapaian keluaran antara spesifikasi teknis yang disebutkan dalam penerimaan barang/jasa dan spesifikasi teknis yang disebutkan dalam dokumen perjanjian/kontrak; dan 2014, No.1601 26');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5978, '25 2014, No.1601  Kebenaran pengalian dan penjumlahan.  Kebenaran penulisan kalimat “terbilang” pada kuitansi dan antar bukti terkait dalam penulisan angka dan huruf.  Kebenaran penulisan tanggal pada kuitansi dan bukti terkait.  Kebenaran pengenaan tarif dan jumlah perhitungan potongan pajak (PPN, PPh Pasal 21, Pasal 22, Pasal 23, Pasal 4 ayat (2) dan Pasal 15).  Apakah penulisan nominal pada kuitansi dan SPTB sudah sesuai.  Kebenaran penulisan nomor rekening dan NPWP.  Apakah penerapan tarif biaya sudah sesuai dengan Standar Biaya Masukan (SBM).  Kelengkapan tanda tangan dokumen terkait.
5) Koordinator Verifikator Verifikasi yang dilakukan oleh Koordinator Verifikator adalah menitikberatkan pada hasil verifikasi yang telah dilakukan oleh petugas verifikator dan Subkoordinator verifikator.
6) Bendahara Pengeluaran Verifikasi yang dilakukan oleh Bendahara Pengeluaran sesuai dengan SPBy sebagaimana terlampir pada contoh format Lampiran VI meliputi:
(a) meneliti kelengkapan perintah pembayaran yang diterbitkan oleh PPK;
(b) pemeriksaan kebenaran atas hak tagih, meliputi:  pihak yang ditunjuk untuk menerima pembayaran;  nilai tagihan yang harus dibayar;  jadwal waktu pembayaran; dan  menguji ketersediaan dana yang bersangkutan.
(c) pemeriksaan kesesuaian pencapaian keluaran antara spesifikasi teknis yang disebutkan dalam penerimaan barang/jasa dan spesifikasi teknis yang disebutkan dalam dokumen perjanjian/kontrak; dan 2014, No.1601 26', 'Lampiran hal. 25', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5979, 'perka-10-2014', 33, 'lampiran', 'Lampiran hal. 26', NULL, 26, '(d) pemeriksaan dan pengujian ketepatan penggunaan kode mata anggaran pengeluaran (akun 6 digit).
Pengujian oleh BP adalah verifikasi atas dokumen usulan pembayaran biaya dan/atau pertanggungjawaban yang diajukan oleh unit kerja .
Dokumen pertanggungjawaban meliputi permintaan persekot kerja, pemindahbukuan dana siap pakai, dan dana rehabilitasi dan rekonstruksi.
7) Pejabat Penanda Tangan Surat Perintah Membayar (PPSPM) Verifikasi yang dilakukan oleh PPSPM meliputi:
(a) kelengkapan dokumen pendukung SPP;
(b) kesesuaian penanda tangan SPP dengan spesimen tanda tangan PPK;
(c) kebenaran pengisian format SPP;
(d) kesesuaian kode BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Satuan Kerja, termasuk menguji kesesuaian antara pembebanan kode mata anggaran pengeluaran (akun 6 digit) dengan uraiannya;
(e) ketersediaan pagu sesuai dengan BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Satuan Kerja;
(f) kebenaran formal dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai;
(g) kebenaran formal dokumen/surat bukti yang menjadi persyaratan/kelengkapan sehubungan dengan pengadaan barang/jasa;
(h) kebenaran pihak yang berhak menerima pembayaran pada SPP sehubungan dengan perjanjian/kontrak/surat keputusan;
(i) kebenaran perhitungan tagihan serta kewajiban di bidang perpajakan dari pihak yang mempunyai hak tagih;
(j) kepastian telah terpenuhinya kewajiban pembayaran kepada negara oleh pihak yang mempunyai hak tagih kepada negara; dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5979, '(d) pemeriksaan dan pengujian ketepatan penggunaan kode mata anggaran pengeluaran (akun 6 digit).
Pengujian oleh BP adalah verifikasi atas dokumen usulan pembayaran biaya dan/atau pertanggungjawaban yang diajukan oleh unit kerja .
Dokumen pertanggungjawaban meliputi permintaan persekot kerja, pemindahbukuan dana siap pakai, dan dana rehabilitasi dan rekonstruksi.
7) Pejabat Penanda Tangan Surat Perintah Membayar (PPSPM) Verifikasi yang dilakukan oleh PPSPM meliputi:
(a) kelengkapan dokumen pendukung SPP;
(b) kesesuaian penanda tangan SPP dengan spesimen tanda tangan PPK;
(c) kebenaran pengisian format SPP;
(d) kesesuaian kode BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Satuan Kerja, termasuk menguji kesesuaian antara pembebanan kode mata anggaran pengeluaran (akun 6 digit) dengan uraiannya;
(e) ketersediaan pagu sesuai dengan BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Satuan Kerja;
(f) kebenaran formal dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai;
(g) kebenaran formal dokumen/surat bukti yang menjadi persyaratan/kelengkapan sehubungan dengan pengadaan barang/jasa;
(h) kebenaran pihak yang berhak menerima pembayaran pada SPP sehubungan dengan perjanjian/kontrak/surat keputusan;
(i) kebenaran perhitungan tagihan serta kewajiban di bidang perpajakan dari pihak yang mempunyai hak tagih;
(j) kepastian telah terpenuhinya kewajiban pembayaran kepada negara oleh pihak yang mempunyai hak tagih kepada negara; dan', 'Lampiran hal. 26', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5980, 'perka-10-2014', 34, 'lampiran', 'Lampiran hal. 26', NULL, 26, '(k) kesesuaian prestasi pekerjaan dengan ketentuan pembayaran dalam perjanjian/kontrak.
27 2014, No.1601
(l) Pengujian kode BAS termasuk menguji kesesuaian antara pembebanan kode mata anggaran pengeluaran (akun 6 digit) dengan uraiannya.
PPSPM bertanggung jawab atas:
1) kebenaran, kelengkapan, dan keabsahan administrasi terhadap dokumen hak tagih pembayaran yang menjadi dasar penerbitan SPM dan akibat yang timbul dari pengujian yang dilakukannya; dan 2) ketepatan jangka waktu penerbitan dan penyampaian SPM kepada KPPN.
Lembar checklist yang dipergunakan untuk verifikasi adalah sebagaimana tercantum dalam contah Lampiran Va sampai dengan Vd.
2. Pelaksanaan Verifikasi Dana Penanggulangan Bencana Dana penanggulangan bencana dialokasikan untuk setiap tahapan, baik pada tahap prabencana, saat tanggap darurat, dan pascabencana.
Pada tahap prabencana, yang meliputi kegiatan kesiapsiagaan, pembangunan sistem peringatan dini, dan kegiatan mitigasi bencana, pemerintah mengalokasikan Dana Kontinjensi Bencana pada DIPA BNPB.
Pada tahap keadaan darurat bencana, yang meliputi kegiatan siaga darurat, tanggap darurat, dan transisi darurat ke pemulihan, pemerintah mengalokasikan Dana Siap Pakai (on call) yang disediakan pada DIPA BNPB. Sedangkan pada tahap pascabencana yang meliputi kegiatan rehabilitasi dan rekonstruksi pemerintah mengalokasikan Dana Bantuan Sosial Berpola Hibah pada DIPA BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5980, '(k) kesesuaian prestasi pekerjaan dengan ketentuan pembayaran dalam perjanjian/kontrak.
27 2014, No.1601
(l) Pengujian kode BAS termasuk menguji kesesuaian antara pembebanan kode mata anggaran pengeluaran (akun 6 digit) dengan uraiannya.
PPSPM bertanggung jawab atas:
1) kebenaran, kelengkapan, dan keabsahan administrasi terhadap dokumen hak tagih pembayaran yang menjadi dasar penerbitan SPM dan akibat yang timbul dari pengujian yang dilakukannya; dan 2) ketepatan jangka waktu penerbitan dan penyampaian SPM kepada KPPN.
Lembar checklist yang dipergunakan untuk verifikasi adalah sebagaimana tercantum dalam contah Lampiran Va sampai dengan Vd.
2. Pelaksanaan Verifikasi Dana Penanggulangan Bencana Dana penanggulangan bencana dialokasikan untuk setiap tahapan, baik pada tahap prabencana, saat tanggap darurat, dan pascabencana.
Pada tahap prabencana, yang meliputi kegiatan kesiapsiagaan, pembangunan sistem peringatan dini, dan kegiatan mitigasi bencana, pemerintah mengalokasikan Dana Kontinjensi Bencana pada DIPA BNPB.
Pada tahap keadaan darurat bencana, yang meliputi kegiatan siaga darurat, tanggap darurat, dan transisi darurat ke pemulihan, pemerintah mengalokasikan Dana Siap Pakai (on call) yang disediakan pada DIPA BNPB. Sedangkan pada tahap pascabencana yang meliputi kegiatan rehabilitasi dan rekonstruksi pemerintah mengalokasikan Dana Bantuan Sosial Berpola Hibah pada DIPA BNPB.', 'Lampiran hal. 26', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5981, 'perka-10-2014', 35, 'lampiran', 'Lampiran hal. 27', NULL, 27, 'Verifikasi di lingkungan Biro Keuangan dilakukan sebatas untuk pencairan dana penanggulangan bencana berdasarkan pada Keputusan Kepala BNPB tentang penetapan alokasi dana yang bersangkutan sebelum dipindahbukukan kepada rekening BPBD Provinsi, Kabupaten/Kota, dan/atau Kementerian/Lembaga pada Bank Pemerintah setempat.
Pemenuhan persyaratan usulan permintaan bantuan dana penanggulangan bencana sepenuhnya menjadi kewenangan deputi teknis yang bersangkutan, sedangkan pemenuhan kelengkapan dokumen untuk dapat dibayarkan/ dicairkan dananya diteliti oleh Biro Keuangan, setelah berkasnya lengkap Bendahara Pengeluaran memindahbukukan kepada rekening BPP pada BPBD.
2014, No.1601 28 Pada dasarnya mekanisme pelaksanaan anggaran pada tahap prabencana dalam situasi terdapat potensi terjadi bencana, keadaan darurat bencana, dan pascabencana berpedoman pada Peraturan Menteri Keuangan mengenai mekanisme pelaksanaan anggaran penanggulangan bencana, yaitu PMK Nomor 105/PMK.05/2013.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5981, 'Verifikasi di lingkungan Biro Keuangan dilakukan sebatas untuk pencairan dana penanggulangan bencana berdasarkan pada Keputusan Kepala BNPB tentang penetapan alokasi dana yang bersangkutan sebelum dipindahbukukan kepada rekening BPBD Provinsi, Kabupaten/Kota, dan/atau Kementerian/Lembaga pada Bank Pemerintah setempat.
Pemenuhan persyaratan usulan permintaan bantuan dana penanggulangan bencana sepenuhnya menjadi kewenangan deputi teknis yang bersangkutan, sedangkan pemenuhan kelengkapan dokumen untuk dapat dibayarkan/ dicairkan dananya diteliti oleh Biro Keuangan, setelah berkasnya lengkap Bendahara Pengeluaran memindahbukukan kepada rekening BPP pada BPBD.
2014, No.1601 28 Pada dasarnya mekanisme pelaksanaan anggaran pada tahap prabencana dalam situasi terdapat potensi terjadi bencana, keadaan darurat bencana, dan pascabencana berpedoman pada Peraturan Menteri Keuangan mengenai mekanisme pelaksanaan anggaran penanggulangan bencana, yaitu PMK Nomor 105/PMK.05/2013.', 'Lampiran hal. 27', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5982, 'perka-10-2014', 36, 'lampiran', 'Lampiran hal. 28', NULL, 28, 'a. Anggaran Penanggulangan Bencana Pada Tahap Prabencana (Dana Kontinjensi) 1) Pengujian oleh PPK pada Deputi Bidang Pencegahan dan Kesiapsiagaan Berdasarkan dokumen permohonan pencairan dana, PPK melakukan pengujian dan penelitian terhadap kelengkapan dan kebenaran dokumen yang diajukan, yang antara lain berupa:  Keputusan Kepala BNPB tentang Penetapan Alokasi Dana Kontinjensi Bencana;  Surat Perjanjian Kerja sama Operasional;  Ringkasan SPKO yang ditandatangani PPK Deputi Bidang Pencegahan dan Kesiapsiagaan;  Kuitansi yang ditandatangani oleh PJOK BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga dan diketahui oleh PPK Deputi Bidang Pencegahan dan Kesiapsiagaan;  Berita Acara Pembayaran antara PPK BNPB dengan PJOK BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga;  Surat Pernyataan Tanggung jawab Belanja;  Fotokopi Rekening Koran dan NPWP BPP pada BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga.
Apabila dari hasil pengujian dan penelitian dimaksud telah memenuhi syarat, maka PPK menyusun SPP-LS kegiatan Kesiapsiagaan, Pembangunan Sistem Peringatan Dini, dan Kegiatan Pengurangan Resiko Bencana, untuk BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga. SPP LS dimaksud selanjutnya disampaikan kepada KPA BNPB melalui Biro Keuangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5982, 'a. Anggaran Penanggulangan Bencana Pada Tahap Prabencana (Dana Kontinjensi) 1) Pengujian oleh PPK pada Deputi Bidang Pencegahan dan Kesiapsiagaan Berdasarkan dokumen permohonan pencairan dana, PPK melakukan pengujian dan penelitian terhadap kelengkapan dan kebenaran dokumen yang diajukan, yang antara lain berupa:  Keputusan Kepala BNPB tentang Penetapan Alokasi Dana Kontinjensi Bencana;  Surat Perjanjian Kerja sama Operasional;  Ringkasan SPKO yang ditandatangani PPK Deputi Bidang Pencegahan dan Kesiapsiagaan;  Kuitansi yang ditandatangani oleh PJOK BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga dan diketahui oleh PPK Deputi Bidang Pencegahan dan Kesiapsiagaan;  Berita Acara Pembayaran antara PPK BNPB dengan PJOK BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga;  Surat Pernyataan Tanggung jawab Belanja;  Fotokopi Rekening Koran dan NPWP BPP pada BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga.
Apabila dari hasil pengujian dan penelitian dimaksud telah memenuhi syarat, maka PPK menyusun SPP-LS kegiatan Kesiapsiagaan, Pembangunan Sistem Peringatan Dini, dan Kegiatan Pengurangan Resiko Bencana, untuk BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga. SPP LS dimaksud selanjutnya disampaikan kepada KPA BNPB melalui Biro Keuangan.', 'Lampiran hal. 28', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5983, 'perka-10-2014', 37, 'lampiran', 'Lampiran hal. 28', NULL, 28, 'Apabila ternyata dari hasil pengujian dan penelitian dimaksud tidak memenuhi syarat, maka PPK pada Deputi Bidang Pencegahan dan Kesiapsiagaan mengembalikan permohonan pencairan dana kontinjensi dimaksud kepada Kepala BPBD Provinsi, Kabupaten/Kota, Rektor Perguruan Tinggi, dan/atau Kepala 29 2014, No.1601 Kementerian Negara/Lembaga, untuk dilakukan perbaikan sesuai dengan ketentuan.
2) Pengujian di Biro Keuangan oleh PPSPM PPSPM melakukan pemeriksaan dan pengujian SPP-LS Dana Kegiatan Kesiapsiagaan, Pembangunan Sistem Peringatan Dini, dan Kegiatan Pengurangan Resiko Bencana yang diajukan sesuai dengan ketentuan, antara lain meliputi kelengkapan dokumen, kesesuaian penanda tangan SPP-LS dengan spesimen tanda tangan PPK, kebenaran pengisian format SPP-LS, kesesuaian kode BAS, dan ketersediaan pagu pada DIPA/POK/Rencana Kerja Anggaran Unit Kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5983, 'Apabila ternyata dari hasil pengujian dan penelitian dimaksud tidak memenuhi syarat, maka PPK pada Deputi Bidang Pencegahan dan Kesiapsiagaan mengembalikan permohonan pencairan dana kontinjensi dimaksud kepada Kepala BPBD Provinsi, Kabupaten/Kota, Rektor Perguruan Tinggi, dan/atau Kepala 29 2014, No.1601 Kementerian Negara/Lembaga, untuk dilakukan perbaikan sesuai dengan ketentuan.
2) Pengujian di Biro Keuangan oleh PPSPM PPSPM melakukan pemeriksaan dan pengujian SPP-LS Dana Kegiatan Kesiapsiagaan, Pembangunan Sistem Peringatan Dini, dan Kegiatan Pengurangan Resiko Bencana yang diajukan sesuai dengan ketentuan, antara lain meliputi kelengkapan dokumen, kesesuaian penanda tangan SPP-LS dengan spesimen tanda tangan PPK, kebenaran pengisian format SPP-LS, kesesuaian kode BAS, dan ketersediaan pagu pada DIPA/POK/Rencana Kerja Anggaran Unit Kerja.', 'Lampiran hal. 28', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5984, 'perka-10-2014', 38, 'lampiran', 'Lampiran hal. 29', NULL, 29, 'Apabila dari hasil pemeriksaan dan pengujian SPP-LS Dana untuk Kegiatan Kesiapsiagaan, Pembangunan Sistem Peringatan Dini, dan Kegiatan Pengurangan Resiko Bencana beserta dokumen pendukungnya memenuhi persyaratan, PPSPM menerbitkan, dan menandatangani SPM-LS Dana Untuk Kegiatan tersebut dan menyampaikannya kepada KPPN Jakarta, dengan melampirkan: a) Salinan Surat Keputusan Kepala BNPB tentang Penetapan Alokasi Dana Untuk Kegiatan Kesiapsiagaan, Pembangunan Sistem Peringatan Dini, dan Kegiatan Pengurangan Resiko Bencana; b) Surat Perjanjian Kerja sama Operasional (SPKO); c) Ringkasan SPKO yang ditandatangani PPK pada Deputi Bidang Pencegahan dan Kesiapsiagaan; d) Kuitansi yang ditandatangani oleh PJOK BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga dan diketahui oleh PPK pada Deputi Bidang Pencegahan dan Kesiapsiagaan; e) Berita Acara Pembayaran antara PPK BNPB dengan PJOK BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga; f) Surat Pernyataan Tanggung jawab Belanja; g) Fotokopi Rekening Koran dan NPWP BPP pada BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga; h) Arsip Data Komputer (ADK).
Dalam hal berkas pengajuan SPP-LS yang diajukan oleh PPK tidak memenuhi ketentuan, maka PPSPM wajib menolak untuk menerbitkan/menandatangani SPM.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5984, 'Apabila dari hasil pemeriksaan dan pengujian SPP-LS Dana untuk Kegiatan Kesiapsiagaan, Pembangunan Sistem Peringatan Dini, dan Kegiatan Pengurangan Resiko Bencana beserta dokumen pendukungnya memenuhi persyaratan, PPSPM menerbitkan, dan menandatangani SPM-LS Dana Untuk Kegiatan tersebut dan menyampaikannya kepada KPPN Jakarta, dengan melampirkan: a) Salinan Surat Keputusan Kepala BNPB tentang Penetapan Alokasi Dana Untuk Kegiatan Kesiapsiagaan, Pembangunan Sistem Peringatan Dini, dan Kegiatan Pengurangan Resiko Bencana; b) Surat Perjanjian Kerja sama Operasional (SPKO); c) Ringkasan SPKO yang ditandatangani PPK pada Deputi Bidang Pencegahan dan Kesiapsiagaan; d) Kuitansi yang ditandatangani oleh PJOK BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga dan diketahui oleh PPK pada Deputi Bidang Pencegahan dan Kesiapsiagaan; e) Berita Acara Pembayaran antara PPK BNPB dengan PJOK BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga; f) Surat Pernyataan Tanggung jawab Belanja; g) Fotokopi Rekening Koran dan NPWP BPP pada BPBD Provinsi, Kabupaten/Kota, Perguruan Tinggi, dan/atau Kementerian Negara/Lembaga; h) Arsip Data Komputer (ADK).
Dalam hal berkas pengajuan SPP-LS yang diajukan oleh PPK tidak memenuhi ketentuan, maka PPSPM wajib menolak untuk menerbitkan/menandatangani SPM.', 'Lampiran hal. 29', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5985, 'perka-10-2014', 39, 'lampiran', 'Lampiran hal. 30', NULL, 30, '2014, No.1601 30 Seluruh dokumen lainnya yang menjadi dasar pemeriksaan, pengujian dan penerbitan SPM-LS Dana Untuk Kegiatan Kesiapsiagaan, Pembangunan Sistem Peringatan Dini, dan Kegiatan Pengurangan Resiko Bencana disimpan oleh PPSPM untuk menjadi bahan pemeriksaan bagi aparat pemeriksa internal dan eksternal.
Lembar checklist yang dipergunakan untuk verifikasi adalah sebagaimana tercantum dalam contah Lampiran Va sampai dengan Vd, dan Vg.
b. Pelaksanaan Anggaran Penanggulangan Bencana Pada Tahap Keadaan Darurat Bencana (Dana Siap Pakai) Mekanisme pelaksanaan anggaran pada tahap ini menggunakan Dana Siap Pakai (on call) yang disediakan dalam bentuk Uang Persediaan (UP) pada BP BNPB.
1) Pengujian oleh PPK pada Deputi Bidang Penanganan Darurat a) kelengkapan dokumen tagihan yang terdiri dari:  Surat Perintah Pembayaran (SPP);  DRPP;  Rekapitulasi;  Surat Pernyataan;  Surat Pernyataan Tanggung Jawab Mutlak (SPTJM);  Memo/Nota Dinas dan Lembar Disposisi;  MoU/Nota Kesepahaman (Bantuan Dana di atas Rp1 M);  Pernyataan Darurat;  Berita Acara Serah Terima (BAST);  Kuitansi;  Tanda Tangan BPP/BP, PPK, KPA;  Rekening Koran/Referensi Bank (Nama & No. Rekening);  SK BPP dan PPK (Pengelola DSP).
Apabila pembayaran dengan LS Kontrak dilampiri:  Rekening Koran/Referensi Bank (Nama & No. Rekening);  NPWP;  SSP dan Faktur Pajak;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5985, '2014, No.1601 30 Seluruh dokumen lainnya yang menjadi dasar pemeriksaan, pengujian dan penerbitan SPM-LS Dana Untuk Kegiatan Kesiapsiagaan, Pembangunan Sistem Peringatan Dini, dan Kegiatan Pengurangan Resiko Bencana disimpan oleh PPSPM untuk menjadi bahan pemeriksaan bagi aparat pemeriksa internal dan eksternal.
Lembar checklist yang dipergunakan untuk verifikasi adalah sebagaimana tercantum dalam contah Lampiran Va sampai dengan Vd, dan Vg.
b. Pelaksanaan Anggaran Penanggulangan Bencana Pada Tahap Keadaan Darurat Bencana (Dana Siap Pakai) Mekanisme pelaksanaan anggaran pada tahap ini menggunakan Dana Siap Pakai (on call) yang disediakan dalam bentuk Uang Persediaan (UP) pada BP BNPB.
1) Pengujian oleh PPK pada Deputi Bidang Penanganan Darurat a) kelengkapan dokumen tagihan yang terdiri dari:  Surat Perintah Pembayaran (SPP);  DRPP;  Rekapitulasi;  Surat Pernyataan;  Surat Pernyataan Tanggung Jawab Mutlak (SPTJM);  Memo/Nota Dinas dan Lembar Disposisi;  MoU/Nota Kesepahaman (Bantuan Dana di atas Rp1 M);  Pernyataan Darurat;  Berita Acara Serah Terima (BAST);  Kuitansi;  Tanda Tangan BPP/BP, PPK, KPA;  Rekening Koran/Referensi Bank (Nama & No. Rekening);  SK BPP dan PPK (Pengelola DSP).
Apabila pembayaran dengan LS Kontrak dilampiri:  Rekening Koran/Referensi Bank (Nama & No. Rekening);  NPWP;  SSP dan Faktur Pajak;', 'Lampiran hal. 30', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5986, 'perka-10-2014', 40, 'lampiran', 'Lampiran hal. 31', NULL, 31, '31 2014, No.1601  SPK/Kontrak/Surat Perjanjian;  BAP;  SK BPP dan PPK (Pengelola DSP). b) kebenaran perhitungan tagihan; c) kebenaran data pihak yang berhak menerima pembayaran atas beban APBN; d) kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum dalam perjanjian/kontrak dengan barang/jasa yang diserahkan oleh penyedia barang/jasa; e) kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/kontrak; f) kebenaran, keabsahan serta akibat yang timbul dari penggunaan surat bukti mengenai hak tagih kepada negara; dan g) ketepatan jangka waktu penyelesaian pekerjaan sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/kontrak.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5986, '31 2014, No.1601  SPK/Kontrak/Surat Perjanjian;  BAP;  SK BPP dan PPK (Pengelola DSP). b) kebenaran perhitungan tagihan; c) kebenaran data pihak yang berhak menerima pembayaran atas beban APBN; d) kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum dalam perjanjian/kontrak dengan barang/jasa yang diserahkan oleh penyedia barang/jasa; e) kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/kontrak; f) kebenaran, keabsahan serta akibat yang timbul dari penggunaan surat bukti mengenai hak tagih kepada negara; dan g) ketepatan jangka waktu penyelesaian pekerjaan sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/kontrak.', 'Lampiran hal. 31', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5987, 'perka-10-2014', 41, 'lampiran', 'Lampiran hal. 31', NULL, 31, '2) Pengujian oleh PPSPM Pengujian terhadap SPP beserta dokumen pendukung yang dilakukan oleh PPSPM meliputi: kelengkapan dokumen pendukung SPP; a) kesesuaian penanda tangan SPP dengan spesimen tanda tangan PPK; b) kebenaran pengisian format SPP; c) kesesuaian kode Bagan Akun Standar (BAS) pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Satuan Kerja; d) ketersediaan pagu sesuai dengan BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran satuan kerja; e) kebenaran formal dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai; f) kebenaran formal dokumen/surat bukti yang menjadi persyaratan/kelengkapan sehubungan dengan pengadaan barang/jasa; g) kebenaran pihak yang berhak menerima pembayaran pada SPP sehubungan dengan perjanjian/kontrak/surat keputusan;
2014, No.1601 32 h) kebenaran perhitungan tagihan serta kewajiban di bidang perpajakan dari pihak yang mempunyai hak tagih; i) kepastian telah terpenuhinya kewajiban pembayaran kepada negara oleh pihak yang mempunyai hak tagih kepada negara; dan j) kesesuaian prestasi pekerjaan dengan ketentuan pembayaran dalam perjanjian/kontrak.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5987, '2) Pengujian oleh PPSPM Pengujian terhadap SPP beserta dokumen pendukung yang dilakukan oleh PPSPM meliputi: kelengkapan dokumen pendukung SPP; a) kesesuaian penanda tangan SPP dengan spesimen tanda tangan PPK; b) kebenaran pengisian format SPP; c) kesesuaian kode Bagan Akun Standar (BAS) pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Satuan Kerja; d) ketersediaan pagu sesuai dengan BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran satuan kerja; e) kebenaran formal dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai; f) kebenaran formal dokumen/surat bukti yang menjadi persyaratan/kelengkapan sehubungan dengan pengadaan barang/jasa; g) kebenaran pihak yang berhak menerima pembayaran pada SPP sehubungan dengan perjanjian/kontrak/surat keputusan;
2014, No.1601 32 h) kebenaran perhitungan tagihan serta kewajiban di bidang perpajakan dari pihak yang mempunyai hak tagih; i) kepastian telah terpenuhinya kewajiban pembayaran kepada negara oleh pihak yang mempunyai hak tagih kepada negara; dan j) kesesuaian prestasi pekerjaan dengan ketentuan pembayaran dalam perjanjian/kontrak.', 'Lampiran hal. 31', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5988, 'perka-10-2014', 42, 'lampiran', 'Lampiran hal. 32', NULL, 32, '3) Pengujian oleh BP a) meneliti kelengkapan perintah pembayaran yang diterbitkan oleh PPK; b) pemeriksaan kebenaran atas hak tagih, meliputi:  pihak yang ditunjuk untuk menerima pembayaran;  nilai tagihan yang harus dibayar;  jadwal waktu pembayaran; dan  menguji ketersediaan dana yang bersangkutan. c) Pemeriksaan kesesuaian pencapaian keluaran antara spesifikasi teknis yang disebutkan dalam penerimaan barang/jasa dan spesifikasi teknis yang disebutkan dalam dokumen perjanjian/kontrak; dan d) Pemeriksaan dan pengujian ketepatan penggunaan kode mata anggaran pengeluaran (akun 6 digit).
Lembar checklist yang dipergunakan untuk verifikasi adalah sebagaimana tercantum dalam contah Lampiran Va sampai dengan Ve.
c. Pelaksanaan Anggaran Penanggulangan Bencana Pada Tahap Pascabencana Dana penanggulangan bencana pada tahap pascabencana digunakan untuk kegiatan rehabilitasi dan/atau rekonstruksi, serta dilakukan dalam bentuk:  swakelola atau kontraktual baik yang dikerjakan sendiri maupun melibatkan BPBD;  pemberian bantuan langsung kepada masyarakat/kelompok masyarakat;  pemberian bantuan kepada pemerintah daerah yang terkena bencana berupa dana bantuan sosial berpola hibah.
33 2014, No.1601 BENTUK SWAKELOLA ATAU KONTRAKTUAL 1) Pengujian oleh PPK pada Deputi Bidang Rehabilitasi dan Rekonstruksi PPK pada Deputi Bidang Rehabilitasi dan Rekonstruksi pada BNPB melakukan pengujian sesuai dengan ketentuan, antara lain kelengkapan dokumen, dan kebenaran perhitungan UP yang diajukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5988, '3) Pengujian oleh BP a) meneliti kelengkapan perintah pembayaran yang diterbitkan oleh PPK; b) pemeriksaan kebenaran atas hak tagih, meliputi:  pihak yang ditunjuk untuk menerima pembayaran;  nilai tagihan yang harus dibayar;  jadwal waktu pembayaran; dan  menguji ketersediaan dana yang bersangkutan. c) Pemeriksaan kesesuaian pencapaian keluaran antara spesifikasi teknis yang disebutkan dalam penerimaan barang/jasa dan spesifikasi teknis yang disebutkan dalam dokumen perjanjian/kontrak; dan d) Pemeriksaan dan pengujian ketepatan penggunaan kode mata anggaran pengeluaran (akun 6 digit).
Lembar checklist yang dipergunakan untuk verifikasi adalah sebagaimana tercantum dalam contah Lampiran Va sampai dengan Ve.
c. Pelaksanaan Anggaran Penanggulangan Bencana Pada Tahap Pascabencana Dana penanggulangan bencana pada tahap pascabencana digunakan untuk kegiatan rehabilitasi dan/atau rekonstruksi, serta dilakukan dalam bentuk:  swakelola atau kontraktual baik yang dikerjakan sendiri maupun melibatkan BPBD;  pemberian bantuan langsung kepada masyarakat/kelompok masyarakat;  pemberian bantuan kepada pemerintah daerah yang terkena bencana berupa dana bantuan sosial berpola hibah.
33 2014, No.1601 BENTUK SWAKELOLA ATAU KONTRAKTUAL 1) Pengujian oleh PPK pada Deputi Bidang Rehabilitasi dan Rekonstruksi PPK pada Deputi Bidang Rehabilitasi dan Rekonstruksi pada BNPB melakukan pengujian sesuai dengan ketentuan, antara lain kelengkapan dokumen, dan kebenaran perhitungan UP yang diajukan.', 'Lampiran hal. 32', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5989, 'perka-10-2014', 43, 'lampiran', 'Lampiran hal. 33', NULL, 33, 'Kelengkapan dokumen meliputi:
(a) Pembayaran di bawah Rp50 juta  SPTB rangkap 1;  Daftar Rincian Permintaan Pembayaran (DRPP);  Surat Permintaan Pembayaran (SPP);  SSP dan Faktur Pajak (harus ada nomor seri);  Rekening Koran/Referenci Bank (Nama dan No. Rek);  NPWP;  Kuitansi;  Kelengkapan tanda tangan pada berkas;  Nota Dinas/Memo dan lembar disposisi.
(b) Pembayaran Rp50 juta - Rp200 juta  Ringkasan Kontrak;  Surat Perjanjian Kontrak/Surat Perjanjian;  Berita Acara Pembayaran;  BAST/BAPP/bukti penyelesaian lainnya.
(c) Pembayaran LS Kontrak di atas Rp200 juta  Surat Kuasa dan rangkapnya (dilegalisasi);  Surat Keabsahan dan rangkapnya (dilegalisasi);  Jamian Uang Muka;  Jaminan Pelaksanaan;  Jaminan Pemeliharaan;  Bank Garansi.
2014, No.1601 34 Apabila dari hasil pengujian terhadap permohonan UP yang diajukan BP BNPB telah memenuhi syarat, maka PPK pada Deputi Bidang Rehabilitasi dan Rekonstruksi pada BNPB menerbitkan SPP-UP untuk pembiayaan kegiatan rehabilitasi dan rekonstruksi yang dikerjakan sendiri oleh BNPB, dan selanjutnya disampaikan kepada PPSPM BNPB. SPP-UP dimaksud dilengkapi dengan perhitungan besaran kebutuhan dana sesuai dengan pengajuan dari BP.
2) PPSPM melakukan pengujian Pengujian terhadap SPP beserta dokumen pendukung yang dilakukan oleh PPSPM meliputi:
a. kelengkapan dokumen pendukung SPP;
b. kesesuaian penanda tangan SPP dengan spesimen tanda tangan PPK;
c. kebenaran pengisian format SPP;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5989, 'Kelengkapan dokumen meliputi:
(a) Pembayaran di bawah Rp50 juta  SPTB rangkap 1;  Daftar Rincian Permintaan Pembayaran (DRPP);  Surat Permintaan Pembayaran (SPP);  SSP dan Faktur Pajak (harus ada nomor seri);  Rekening Koran/Referenci Bank (Nama dan No. Rek);  NPWP;  Kuitansi;  Kelengkapan tanda tangan pada berkas;  Nota Dinas/Memo dan lembar disposisi.
(b) Pembayaran Rp50 juta - Rp200 juta  Ringkasan Kontrak;  Surat Perjanjian Kontrak/Surat Perjanjian;  Berita Acara Pembayaran;  BAST/BAPP/bukti penyelesaian lainnya.
(c) Pembayaran LS Kontrak di atas Rp200 juta  Surat Kuasa dan rangkapnya (dilegalisasi);  Surat Keabsahan dan rangkapnya (dilegalisasi);  Jamian Uang Muka;  Jaminan Pelaksanaan;  Jaminan Pemeliharaan;  Bank Garansi.
2014, No.1601 34 Apabila dari hasil pengujian terhadap permohonan UP yang diajukan BP BNPB telah memenuhi syarat, maka PPK pada Deputi Bidang Rehabilitasi dan Rekonstruksi pada BNPB menerbitkan SPP-UP untuk pembiayaan kegiatan rehabilitasi dan rekonstruksi yang dikerjakan sendiri oleh BNPB, dan selanjutnya disampaikan kepada PPSPM BNPB. SPP-UP dimaksud dilengkapi dengan perhitungan besaran kebutuhan dana sesuai dengan pengajuan dari BP.
2) PPSPM melakukan pengujian Pengujian terhadap SPP beserta dokumen pendukung yang dilakukan oleh PPSPM meliputi:
a. kelengkapan dokumen pendukung SPP;
b. kesesuaian penanda tangan SPP dengan spesimen tanda tangan PPK;
c. kebenaran pengisian format SPP;', 'Lampiran hal. 33', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5990, 'perka-10-2014', 44, 'lampiran', 'Lampiran hal. 34', NULL, 34, 'd. kesesuaian kode Bagan Akun Standar (BAS) pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Satuan Kerja;
e. ketersediaan pagu sesuai dengan BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran satuan kerja;
f. kebenaran formal dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai;
g. kebenaran formal dokumen/surat bukti yang menjadi persyaratan/kelengkapan sehubungan dengan pengadaan barang/jasa;
h. kebenaran pihak yang berhak menerima pembayaran pada SPP sehubungan dengan perjanjian/kontrak/ surat keputusan;
i. kebenaran perhitungan tagihan serta kewajiban di bidang perpajakan dari pihak yang mempunyai hak tagih;
j. kepastian telah terpenuhinya kewajiban pembayaran kepada negara oleh pihak yang mempunyai hak tagih kepada negara; dan
k. kesesuaian prestasi pekerjaan dengan ketentuan pembayaran dalam perjanjian/kontrak.
Apabila dari hasil pemeriksaan dan pengujian SPP-UP beserta dokumen pendukungnya memenuhi persyaratan, PPSPM menerbitkan, dan menandatangani SPM-UP untuk kegiatan 35 2014, No.1601 rehabilitasi dan rekonstruksi yang dikerjakan sendiri oleh BNPB, dan menyampaikannya kepada KPPN Jakarta, yang cukup dilampiri dengan ADK SPM-UP.
Seluruh dokumen sebagai dasar pemeriksaan, pengujian, dan penerbitan SPM-UP disimpan oleh PPSPM untuk menjadi bahan pemeriksaan bagi aparat pemeriksa internal dan eksternal.
BENTUK BANTUAN LANGSUNG KEPADA MASYARAKAT/ KELOMPOK MASYARAKAT');
