INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5993, 'perka-10-2014', 47, 'lampiran', 'Lampiran hal. 37', NULL, 37, '37 2014, No.1601  Keputusan Kepala BNPB tentang Penetapan Alokasi Dana Bantuan Sosial Berpola Hibah;  MoU/Nota Kesepahaman;  SPTB rangkap 1;  Daftar Rincian Permintaan Pembayaran (DRPP);  Surat Permintaan Pembayaran (SPP);  Surat Permintaan Dana Bansos Berpola HIbah;  Daftar nominatif kegiatan/proyek yang akan dibiayai dari dana bantuan sosial berpola hibah;  Kuitansi bermeterai, yang ditandatangani oleh BP dan diketahui oleh PPK pada BPBD Provinsi, Kabupaten/Kota;  Berita Acara Pembayaran antara PPK BNPB dengan PPK BPBD;  Surat Pernyataan Tanggung Jawab Mutlak (SPTJM); dan  Fotokopi Rekening Koran;  NPWP Bendahara Pengeluaran pada BPBD;  Nota Dinas/Memo dan lembar disposisi; dan  Kelengkapan tanda tangan pada berkas.
2) PPSPM melakukan pengujian a) kelengkapan dokumen pendukung SPP; b) kesesuaian penanda tangan SPP dengan spesimen tanda tangan PPK; c) kebenaran pengisian format SPP; d) kesesuaian kode Bagan Akun Standar (BAS) pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Satuan Kerja; e) ketersediaan pagu sesuai dengan BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran satuan kerja; f) kebenaran formal dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai; g) kebenaran formal dokumen/surat bukti yang menjadi persyaratan/kelengkapan sehubungan dengan pengadaan barang/jasa; h) kebenaran pihak yang berhak menerima pembayaran pada SPP sehubungan dengan perjanjian/kontrak/ surat keputusan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5993, '37 2014, No.1601  Keputusan Kepala BNPB tentang Penetapan Alokasi Dana Bantuan Sosial Berpola Hibah;  MoU/Nota Kesepahaman;  SPTB rangkap 1;  Daftar Rincian Permintaan Pembayaran (DRPP);  Surat Permintaan Pembayaran (SPP);  Surat Permintaan Dana Bansos Berpola HIbah;  Daftar nominatif kegiatan/proyek yang akan dibiayai dari dana bantuan sosial berpola hibah;  Kuitansi bermeterai, yang ditandatangani oleh BP dan diketahui oleh PPK pada BPBD Provinsi, Kabupaten/Kota;  Berita Acara Pembayaran antara PPK BNPB dengan PPK BPBD;  Surat Pernyataan Tanggung Jawab Mutlak (SPTJM); dan  Fotokopi Rekening Koran;  NPWP Bendahara Pengeluaran pada BPBD;  Nota Dinas/Memo dan lembar disposisi; dan  Kelengkapan tanda tangan pada berkas.
2) PPSPM melakukan pengujian a) kelengkapan dokumen pendukung SPP; b) kesesuaian penanda tangan SPP dengan spesimen tanda tangan PPK; c) kebenaran pengisian format SPP; d) kesesuaian kode Bagan Akun Standar (BAS) pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Satuan Kerja; e) ketersediaan pagu sesuai dengan BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran satuan kerja; f) kebenaran formal dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai; g) kebenaran formal dokumen/surat bukti yang menjadi persyaratan/kelengkapan sehubungan dengan pengadaan barang/jasa; h) kebenaran pihak yang berhak menerima pembayaran pada SPP sehubungan dengan perjanjian/kontrak/ surat keputusan;', 'Lampiran hal. 37', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5994, 'perka-10-2014', 48, 'lampiran', 'Lampiran hal. 38', NULL, 38, '2014, No.1601 38 i) kebenaran perhitungan tagihan serta kewajiban di bidang perpajakan dari pihak yang mempunyai hak tagih; j) kepastian telah terpenuhinya kewajiban pembayaran kepada negara oleh pihak yang mempunyai hak tagih kepada negara; dan k) kesesuaian prestasi pekerjaan dengan ketentuan pembayaran dalam perjanjian/kontrak.
Lembar checklist yang dipergunakan untuk verifikasi adalah sebagaimana tercantum dalam contah Lampiran Va sampai dengan Vd, dan Vf.
C. Hasil Verifikasi Sebagai tindak lanjut terhadap temuan-temuan verifikasi dilakukan sebagai berikut:
1. Dalam hal pelaksanaan pengujian dilakukan sebelum terjadinya pembayaran oleh Satker, maka apabila terdapat temuan berupa penyimpangan dari ketentuan-ketentuan yang berlaku, bukti pengeluaran yang bersangkutan dikembalikan kepada petugas yang bertanggung jawab untuk dilengkapi dan/atau diperbaiki, sehingga memenuhi persyaratan yang seharusnya.
Pengembalian tersebut dicatat di dalam tanda terima berkas verifikasi sebagaimana pada contoh format Lampiran IV.
2. Dalam hal pelaksanaan pengujian dilakukan oleh Biro Keuangan setelah terjadinya pembayaran yang dilakukan, maka apabila terdapat temuan berupa penyimpangan dari ketentuan yang berlaku, atas temuan tersebut, Biro Keuangan mengirimkan Nota Hasil Verifikasi kepada pimpinan unit kerja yang bersangkutan berisi hasil verifikasi dan saran untuk tindak lanjut yang harus dilakukan oleh pimpinan unit kerja dimaksud.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5994, '2014, No.1601 38 i) kebenaran perhitungan tagihan serta kewajiban di bidang perpajakan dari pihak yang mempunyai hak tagih; j) kepastian telah terpenuhinya kewajiban pembayaran kepada negara oleh pihak yang mempunyai hak tagih kepada negara; dan k) kesesuaian prestasi pekerjaan dengan ketentuan pembayaran dalam perjanjian/kontrak.
Lembar checklist yang dipergunakan untuk verifikasi adalah sebagaimana tercantum dalam contah Lampiran Va sampai dengan Vd, dan Vf.
C. Hasil Verifikasi Sebagai tindak lanjut terhadap temuan-temuan verifikasi dilakukan sebagai berikut:
1. Dalam hal pelaksanaan pengujian dilakukan sebelum terjadinya pembayaran oleh Satker, maka apabila terdapat temuan berupa penyimpangan dari ketentuan-ketentuan yang berlaku, bukti pengeluaran yang bersangkutan dikembalikan kepada petugas yang bertanggung jawab untuk dilengkapi dan/atau diperbaiki, sehingga memenuhi persyaratan yang seharusnya.
Pengembalian tersebut dicatat di dalam tanda terima berkas verifikasi sebagaimana pada contoh format Lampiran IV.
2. Dalam hal pelaksanaan pengujian dilakukan oleh Biro Keuangan setelah terjadinya pembayaran yang dilakukan, maka apabila terdapat temuan berupa penyimpangan dari ketentuan yang berlaku, atas temuan tersebut, Biro Keuangan mengirimkan Nota Hasil Verifikasi kepada pimpinan unit kerja yang bersangkutan berisi hasil verifikasi dan saran untuk tindak lanjut yang harus dilakukan oleh pimpinan unit kerja dimaksud.', 'Lampiran hal. 38', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (5995, 'perka-10-2014', 49, 'lampiran', 'Lampiran hal. 38', NULL, 38, 'D. Laporan Hasil Verifikasi PPSPM menyampaikan laporan bulanan terkait pelaksanaan tugas dan wewenangnya kepada KPA yang paling sedikit memuat:
1. Jumlah SPP yang diterima;
2. Jumlah SPM yang diterbitkan;
3. Jumlah SPP yang tidak dapat diterbitkan SPM-nya
4. Jumlah SPM yang sudah terbit SP2D-nya;
5. Jumlah SPM yang dikembalikan dari KPPN.
39 2014, No.1601 BAB IV PENUTUP Peraturan Kepala BNPB tentang Pedoman Verifikasi Dokumen Pertanggungjawaban Keuangan di Lingkungan BNPN, agar dijadikan acuan bagi para Pengelola Keuangan di dalam pelaksanaan anggaran dan kegiatan penanggulangan bencana.
Dengan penerbitan Peraturan Kepala ini, diharapkan kepada para pengelola keuangan dapat melakukan verifikasi dokumen pertanggungjawaban dengan baik dan diharapkan pengelolaan administrasi pengelolaan keuangan negara pun dapat tertib.
Hal lain yang lebih penting berkaitan dengan verifikasi adalah jangka waktu penyelesaian verifikasi dokumen, mulai dari verifikasi di lingkungan Satker sampai dengan penerbitan SPM oleh Pejabat Penanda tangan SPM, agar ditetapkan lebih lanjut oleh masing-masing pimpinan Satker eselon I yang berupa prosedur operasi standar atau Standard Operating Procedure (SOP).
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF 2014, No.1601 40 DAFTAR LAMPIRAN No. Uraian Lampiran
1. Struktur Organisasi Pengelola Keuangan di Lingkungan BNPB I
2. Mekanisme Alur Verifikasi Dokumen Usulan II Pertanggungjawaban di Unit Kerja');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (5995, 'D. Laporan Hasil Verifikasi PPSPM menyampaikan laporan bulanan terkait pelaksanaan tugas dan wewenangnya kepada KPA yang paling sedikit memuat:
1. Jumlah SPP yang diterima;
2. Jumlah SPM yang diterbitkan;
3. Jumlah SPP yang tidak dapat diterbitkan SPM-nya
4. Jumlah SPM yang sudah terbit SP2D-nya;
5. Jumlah SPM yang dikembalikan dari KPPN.
39 2014, No.1601 BAB IV PENUTUP Peraturan Kepala BNPB tentang Pedoman Verifikasi Dokumen Pertanggungjawaban Keuangan di Lingkungan BNPN, agar dijadikan acuan bagi para Pengelola Keuangan di dalam pelaksanaan anggaran dan kegiatan penanggulangan bencana.
Dengan penerbitan Peraturan Kepala ini, diharapkan kepada para pengelola keuangan dapat melakukan verifikasi dokumen pertanggungjawaban dengan baik dan diharapkan pengelolaan administrasi pengelolaan keuangan negara pun dapat tertib.
Hal lain yang lebih penting berkaitan dengan verifikasi adalah jangka waktu penyelesaian verifikasi dokumen, mulai dari verifikasi di lingkungan Satker sampai dengan penerbitan SPM oleh Pejabat Penanda tangan SPM, agar ditetapkan lebih lanjut oleh masing-masing pimpinan Satker eselon I yang berupa prosedur operasi standar atau Standard Operating Procedure (SOP).
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF 2014, No.1601 40 DAFTAR LAMPIRAN No. Uraian Lampiran
1. Struktur Organisasi Pengelola Keuangan di Lingkungan BNPB I
2. Mekanisme Alur Verifikasi Dokumen Usulan II Pertanggungjawaban di Unit Kerja', 'Lampiran hal. 38', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
