INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6010, '1. PEMBAYARAN BANTUAN LANGSUNG KE MASYARAKAT/KELOMPOK MASYARAKAT 19 Imou 7 NOTA KESEPAHAMAN SK Pemberian Bantuan Langsung Kepada Masyarakat yang memuat 20 | Nama Identitas, Jumlah Nominal Bantuan, Nomor Rekening Penerima Bantuan Daftar Nominatif Masyarakat/Kelompok Masyarakat yang 21 | mencantumkan Jumlah dana dan Nomor rekening bank masyarakat/kelompok masyarakat 22 (kuitansi dari Kelompok masyarakat 23 Jeap IM PEMBAYARAN DANA BANTUAN SOSIAL BERPOLA HIBAH za (Surat ketetapan hasil evaluasi dan verifikasi 25 |SK Kepala BNPB tentang Penetapan Alokasi Dana Bantuan 26 (SK PPK dan BPP BPBD 27 (MOU / NOTA KESEPAHAMAN 28 |Surat Permintaan Dana Bansos dari BPBD 29 (RAB dan Daftar Nominatif 30 (kuitansi 31 Jap 32 (seram 33 (Fotokopi rekening koran 3g (npwp 35 (Nota Dinas dan Disposisi 36 (Kelengkapan tanda tangan Yang Mengajukan Verifikator Unit TINDAK LANJUT No CATATAN PERBAIKAN use | susrooro.', 'Lampiran hal. 52', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2014 tentang Pedoman Verifikasi Dokumen Pertanggungjawaban di Lingkungan Badan Nasional Penanggulangan Bencana');
