INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6012, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6013, 'perka-11-2008', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka rehabilitasi dan rekonstruksi penanganan pasca bencana, diperlukan pedoman panduan dalam pelaksanaan rehabilitasi dan rekonstruksi;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Rehabilitasi dan Rekonstruksi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6013, 'a. bahwa dalam rangka rehabilitasi dan rekonstruksi penanganan pasca bencana, diperlukan pedoman panduan dalam pelaksanaan rehabilitasi dan rekonstruksi;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Rehabilitasi dan Rekonstruksi.', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6014, 'perka-11-2008', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Keputusan Presiden Nomor 29/M Tahun 2008 tentang Pengangkatan Kepala dan Pejabat Eselon I Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6014, '1. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Keputusan Presiden Nomor 29/M Tahun 2008 tentang Pengangkatan Kepala dan Pejabat Eselon I Badan Nasional Penanggulangan Bencana.', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6015, 'perka-11-2008', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN REHABILITASI DAN REKONSTRUKSI PASCA BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6015, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN REHABILITASI DAN REKONSTRUKSI PASCA BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6016, 'perka-11-2008', 4, 'pasal', 'Pasal 1', NULL, 2, 'Pedoman Rehabilitasi dan Rekonstruksi Pasca Bencana merupakan panduan bagi Pemerintah dan/atau Pemerintah Daerah dalam menyusun rencana Rehabilitasi dan Rekonstruksi Pasca Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6016, 'Pedoman Rehabilitasi dan Rekonstruksi Pasca Bencana merupakan panduan bagi Pemerintah dan/atau Pemerintah Daerah dalam menyusun rencana Rehabilitasi dan Rekonstruksi Pasca Bencana.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6017, 'perka-11-2008', 5, 'pasal', 'Pasal 2', NULL, 2, 'Pedoman dimaksud dalam Pasal 1 sebagaimana tercantum dalam lampiran keputusan ini, merupakan bagian tak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6017, 'Pedoman dimaksud dalam Pasal 1 sebagaimana tercantum dalam lampiran keputusan ini, merupakan bagian tak terpisahkan dari Peraturan ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6018, 'perka-11-2008', 6, 'pasal', 'Pasal 3', NULL, 2, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6018, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6019, 'perka-11-2008', 7, 'lain', 'Penutup', NULL, 2, 'Ditetapkan di Jakarta pada tanggal 17 Desember 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6019, 'Ditetapkan di Jakarta pada tanggal 17 Desember 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6020, 'perka-11-2008', 8, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'LAMPIRAN I : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 11 TAHUN 2008 TANGGAL : 17 DESEMBER 2008 PEDOMAN REHABILITASI PASCA BENCANA BAB I PENDAHULUAN A. Latar belakang Pembukaan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 mengamanatkan bahwa tujuan pembentukan Negara Republik Indonesia antara lain adalah melindungi segenap bangsa dan seluruh tumpah darah Indonesia. Di tengah fakta bahwa bangsa Indonesia hidup di negara yang secara geografis rawan bencana, maka menjadi tugas negara untuk melindungi bangsa dan seluruh tumpah darah Indonesia dari bencana.
Terjadinya bencana besar tsunami di Nanggroe Aceh Darussalam pada tahun 2004 dan gempa bumi di Yogyakarta dan Jawa Tengah (Kabupaten Klaten) pada tahun 2006 dan beberapa bencana lain sebelum dan sesudahnya telah mendorong bangsa Indonesia untuk menerima kenyataan hidup berdampingan dengan bencana. Sebagai konsekuensi atas penerimaan tersebut, bangsa Indonesia telah melahirkan Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Untuk merealisasikan Undang-Undang tersebut, pada tahun 2008 telah diterbitkan Peraturan Pemerintah Nomor 21 tentang Penyelenggaraan Penanggulangan Bencana, Peraturan Pemerintah Nomor 22 tentang Pendanaan dan Pengelolaan Bencana, Peraturan Pemerintah Nomor 23 tentang Peranserta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6020, 'LAMPIRAN I : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 11 TAHUN 2008 TANGGAL : 17 DESEMBER 2008 PEDOMAN REHABILITASI PASCA BENCANA BAB I PENDAHULUAN A. Latar belakang Pembukaan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 mengamanatkan bahwa tujuan pembentukan Negara Republik Indonesia antara lain adalah melindungi segenap bangsa dan seluruh tumpah darah Indonesia. Di tengah fakta bahwa bangsa Indonesia hidup di negara yang secara geografis rawan bencana, maka menjadi tugas negara untuk melindungi bangsa dan seluruh tumpah darah Indonesia dari bencana.
Terjadinya bencana besar tsunami di Nanggroe Aceh Darussalam pada tahun 2004 dan gempa bumi di Yogyakarta dan Jawa Tengah (Kabupaten Klaten) pada tahun 2006 dan beberapa bencana lain sebelum dan sesudahnya telah mendorong bangsa Indonesia untuk menerima kenyataan hidup berdampingan dengan bencana. Sebagai konsekuensi atas penerimaan tersebut, bangsa Indonesia telah melahirkan Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Untuk merealisasikan Undang-Undang tersebut, pada tahun 2008 telah diterbitkan Peraturan Pemerintah Nomor 21 tentang Penyelenggaraan Penanggulangan Bencana, Peraturan Pemerintah Nomor 22 tentang Pendanaan dan Pengelolaan Bencana, Peraturan Pemerintah Nomor 23 tentang Peranserta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6021, 'perka-11-2008', 9, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'Keberhasilan bangsa Indonesia dalam menangani bencana bukan saja terletak pada ketersediaan perangkat Undang-Undang dan Peraturan Pemerintah yang terkait dengan kebencanaan, tetapi juga implementasi perangkat kebijakan tersebut di lapangan.
Di hadapan perubahan politik, ekonomi, sosial dan budaya bangsa Indonesia serta perubahan global yang sangat cepat, bukan tidak mungkin implementasi Undang-Undang dan Peraturan Pemerintah Penanggulangan Bencana mengalami hambatan. Sebagai contoh, kebijakan otonomi daerah yang dimaksudkan untuk memberdayakan pemerintah daerah dan mendekatkan serta mengoptimalkan pelayanan dasar kepada masyarakat ternyata tidak dengan sendirinya meningkatkan kemampuan daerah menangani bencana. Kebijakan otonomi daerah sering dipahami terbatas sebagai keleluasaan untuk memanfaatkan sumberdaya tanpa dibarengi kesadaran untuk mengelolanya secara bertanggungjawab. Penggeseran wewenang dari pusat ke daerah seringkali tidak diiringi dengan pengalihan tanggung jawab pelayanan dan perlindungan kepada masyarakat. Akibatnya, pada saat bencana terjadi tanggapan daerah cenderung lambat dan seringkali tergantung pada pusat. Keadaan ini menjadi semakin rumit apabila bencana tersebut meliputi lebih dari satu daerah. Di lain pihak, pada saat terjadi bencana, kurangnya koordinasi antar tataran pemerintahan menghambat pelaksanaan tanggapan yang cepat, optimal dan efektif.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6021, 'Keberhasilan bangsa Indonesia dalam menangani bencana bukan saja terletak pada ketersediaan perangkat Undang-Undang dan Peraturan Pemerintah yang terkait dengan kebencanaan, tetapi juga implementasi perangkat kebijakan tersebut di lapangan.
Di hadapan perubahan politik, ekonomi, sosial dan budaya bangsa Indonesia serta perubahan global yang sangat cepat, bukan tidak mungkin implementasi Undang-Undang dan Peraturan Pemerintah Penanggulangan Bencana mengalami hambatan. Sebagai contoh, kebijakan otonomi daerah yang dimaksudkan untuk memberdayakan pemerintah daerah dan mendekatkan serta mengoptimalkan pelayanan dasar kepada masyarakat ternyata tidak dengan sendirinya meningkatkan kemampuan daerah menangani bencana. Kebijakan otonomi daerah sering dipahami terbatas sebagai keleluasaan untuk memanfaatkan sumberdaya tanpa dibarengi kesadaran untuk mengelolanya secara bertanggungjawab. Penggeseran wewenang dari pusat ke daerah seringkali tidak diiringi dengan pengalihan tanggung jawab pelayanan dan perlindungan kepada masyarakat. Akibatnya, pada saat bencana terjadi tanggapan daerah cenderung lambat dan seringkali tergantung pada pusat. Keadaan ini menjadi semakin rumit apabila bencana tersebut meliputi lebih dari satu daerah. Di lain pihak, pada saat terjadi bencana, kurangnya koordinasi antar tataran pemerintahan menghambat pelaksanaan tanggapan yang cepat, optimal dan efektif.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6022, 'perka-11-2008', 10, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'Diterbitkannya Undang-Undang dan Peraturan Pemerintah tentang kebencanaan serta pengalaman penanganan bencana-bencana besar yang telah terjadi menegaskan pentingnya suatu pedoman yang mengatur fungsi dan peran berbagai pihak terkait dalam penanganan bencana secara sistemik, terintegrasi dan komprehensif. Pedoman Rehabilitasi ini diharapkan dapat mengurangi kegamangan, mendorong koordinasi para pihak yang terlibat dalam tahap rehabilitasi bencana yang lebih jelas sehingga menghasilkan penanganan bencana yang lebih efektif. Sebagai pedoman umum, dokumen ini diharapkan dapat berlaku untuk berbagai jenis bencana di seluruh wilayah Indonesia dengan karakteristik masing-masing.
Sebagai bagian dari keseluruhan penanggulangan bencana, implementasi tahapan rehabilitasi harus dikaitkan dengan tahapan lain. Dalam pengertian ini, bukan saja kegiatan-kegiatan tahapan rehabilitasi berhubungan dengan tahap prabencana dan tanggap darurat tetapi juga berhubungan dengan tahapan rekonstruksi.
Hubungan dan koordinasi antar tahapan ini sangat menentukan efektifitas dan efisiensi penanggulangan bencana. Oleh karena itu, pentahapan penanggulangan bencana semestinya tidak ditempatkan sebagai tujuan melainkan cara untuk mencapai efisiensi dan efektifitas penanggulangan bencana secara keseluruhan. Di atas pengertian ini, sinkronisasi dan koordinasi semestinya merupakan kata kunci penanggulangan bencana yang harus dilaksanakan oleh berbagai pihak.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6022, 'Diterbitkannya Undang-Undang dan Peraturan Pemerintah tentang kebencanaan serta pengalaman penanganan bencana-bencana besar yang telah terjadi menegaskan pentingnya suatu pedoman yang mengatur fungsi dan peran berbagai pihak terkait dalam penanganan bencana secara sistemik, terintegrasi dan komprehensif. Pedoman Rehabilitasi ini diharapkan dapat mengurangi kegamangan, mendorong koordinasi para pihak yang terlibat dalam tahap rehabilitasi bencana yang lebih jelas sehingga menghasilkan penanganan bencana yang lebih efektif. Sebagai pedoman umum, dokumen ini diharapkan dapat berlaku untuk berbagai jenis bencana di seluruh wilayah Indonesia dengan karakteristik masing-masing.
Sebagai bagian dari keseluruhan penanggulangan bencana, implementasi tahapan rehabilitasi harus dikaitkan dengan tahapan lain. Dalam pengertian ini, bukan saja kegiatan-kegiatan tahapan rehabilitasi berhubungan dengan tahap prabencana dan tanggap darurat tetapi juga berhubungan dengan tahapan rekonstruksi.
Hubungan dan koordinasi antar tahapan ini sangat menentukan efektifitas dan efisiensi penanggulangan bencana. Oleh karena itu, pentahapan penanggulangan bencana semestinya tidak ditempatkan sebagai tujuan melainkan cara untuk mencapai efisiensi dan efektifitas penanggulangan bencana secara keseluruhan. Di atas pengertian ini, sinkronisasi dan koordinasi semestinya merupakan kata kunci penanggulangan bencana yang harus dilaksanakan oleh berbagai pihak.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6023, 'perka-11-2008', 11, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'B. Tujuan Tujuan dari diterbitkannya Pedoman Umum Rehabilitasi adalah:
1. Memberikan acuan/pegangan bagi penyelenggaraan rehabilitasi;
2. Menjamin ketertiban dan kelancaran penyelenggaraan rehabilitasi;
3. Menjamin pencapaian tujuan rehabilitasi.
C. Dasar Hukum
1. Undang-Undang Nomor 6 Tahun 1974 tentang Ketentuan Pokok Kesejahteraan Sosial.
2. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
3. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
4. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
5. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6023, 'B. Tujuan Tujuan dari diterbitkannya Pedoman Umum Rehabilitasi adalah:
1. Memberikan acuan/pegangan bagi penyelenggaraan rehabilitasi;
2. Menjamin ketertiban dan kelancaran penyelenggaraan rehabilitasi;
3. Menjamin pencapaian tujuan rehabilitasi.
C. Dasar Hukum
1. Undang-Undang Nomor 6 Tahun 1974 tentang Ketentuan Pokok Kesejahteraan Sosial.
2. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
3. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
4. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
5. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6024, 'perka-11-2008', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, '6. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
7. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
D. Pengertian dan batasan umum Pengertian dan batasan yang digunakan dalam pedoman ini adalah pengertian dan batasan sebagaimana yang tertuang dalam Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana dan Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, dan penjelasannya :
1. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pasca bencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.
2. Rehabilitasi dilakukan melalui kegiatan (a) perbaikan lingkungan daerah bencana; (b) perbaikan prasarana dan sarana umum;
(c) pemberian bantuan perbaikan rumah masyarakat;
(d) pemulihan sosial psikologis; (e) pelayanan kesehatan;
(f) rekonsiliasi dan resolusi konflik; (g) pemulihan sosial ekonomi budaya; (h) pemulihan keamanan dan ketertiban; (i) pemulihan fungsi pemerintahan; dan (j) pemulihan fungsi pelayanan publik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6024, '6. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
7. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
D. Pengertian dan batasan umum Pengertian dan batasan yang digunakan dalam pedoman ini adalah pengertian dan batasan sebagaimana yang tertuang dalam Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana dan Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, dan penjelasannya :
1. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pasca bencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.
2. Rehabilitasi dilakukan melalui kegiatan (a) perbaikan lingkungan daerah bencana; (b) perbaikan prasarana dan sarana umum;
(c) pemberian bantuan perbaikan rumah masyarakat;
(d) pemulihan sosial psikologis; (e) pelayanan kesehatan;
(f) rekonsiliasi dan resolusi konflik; (g) pemulihan sosial ekonomi budaya; (h) pemulihan keamanan dan ketertiban; (i) pemulihan fungsi pemerintahan; dan (j) pemulihan fungsi pelayanan publik.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6025, 'perka-11-2008', 13, 'lampiran', 'Lampiran hal. 6', NULL, 6, '3. Kegiatan rehabilitasi harus memperhatikan pengaturan mengenai standar konstruksi bangunan, kondisi sosial, adat istiadat, budaya dan ekonomi
4. Perbaikan lingkungan daerah bencana merupakan kegiatan fisik perbaikan lingkungan untuk memenuhi persyaratan teknis, sosial, ekonomi, dan budaya serta ekosistem suatu kawasan.
5. Kegiatan perbaikan fisik lingkungan sebagaimana dimaksud mencakup lingkungan kawasan permukiman, kawasan industri, kawasan usaha, dan kawasan bangunan gedung.
6. Perbaikan prasarana dan sarana umum merupakan kegiatan perbaikan prasarana dan sarana umum untuk memenuhi kebutuhan transportasi, kelancaran kegiatan ekonomi, dan kehidupan sosial budaya masyarakat.
7. Kegiatan perbaikan prasarana dan sarana umum mencakup:
(a) perbaikan infrastuktur dan (b) fasilitas sosial dan fasilitas umum.
8. Kegiatan perbaikan prasarana dan sarana umum memenuhi ketentuan mengenai: (a) persyaratan keselamatan; (b) persyaratan sistem sanitasi; (c) persyaratan penggunaan bahan bangunan; dan
(d) persyaratan standar teknis konstruksi jalan, jembatan, bangunan gedung dan bangunan air.
9. Pemberian bantuan perbaikan rumah masyarakat merupakan bantuan Pemerintah sebagai stimulan untuk membantu masyarakat memperbaiki rumahnya yang mengalami kerusakan akibat bencana untuk dapat dihuni kembali.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6025, '3. Kegiatan rehabilitasi harus memperhatikan pengaturan mengenai standar konstruksi bangunan, kondisi sosial, adat istiadat, budaya dan ekonomi
4. Perbaikan lingkungan daerah bencana merupakan kegiatan fisik perbaikan lingkungan untuk memenuhi persyaratan teknis, sosial, ekonomi, dan budaya serta ekosistem suatu kawasan.
5. Kegiatan perbaikan fisik lingkungan sebagaimana dimaksud mencakup lingkungan kawasan permukiman, kawasan industri, kawasan usaha, dan kawasan bangunan gedung.
6. Perbaikan prasarana dan sarana umum merupakan kegiatan perbaikan prasarana dan sarana umum untuk memenuhi kebutuhan transportasi, kelancaran kegiatan ekonomi, dan kehidupan sosial budaya masyarakat.
7. Kegiatan perbaikan prasarana dan sarana umum mencakup:
(a) perbaikan infrastuktur dan (b) fasilitas sosial dan fasilitas umum.
8. Kegiatan perbaikan prasarana dan sarana umum memenuhi ketentuan mengenai: (a) persyaratan keselamatan; (b) persyaratan sistem sanitasi; (c) persyaratan penggunaan bahan bangunan; dan
(d) persyaratan standar teknis konstruksi jalan, jembatan, bangunan gedung dan bangunan air.
9. Pemberian bantuan perbaikan rumah masyarakat merupakan bantuan Pemerintah sebagai stimulan untuk membantu masyarakat memperbaiki rumahnya yang mengalami kerusakan akibat bencana untuk dapat dihuni kembali.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6026, 'perka-11-2008', 14, 'lampiran', 'Lampiran hal. 6', NULL, 6, '10. Bantuan Pemerintah sebagaimana dimaksud dapat berupa bahan material, komponen rumah atau uang yang besarnya ditetapkan berdasarkan hasil verifikasi dan evaluasi tingkat kerusakan rumah yang dialami.
11. Bantuan Pemerintah untuk perbaikan rumah masyarakat sebagaimana dimaksud diberikan dengan pola pemberdayaan masyarakat dengan memperhatikan karakter daerah dan budaya masyarakat, yang mekanisme pelaksanaannya ditetapkan melalui koordinasi BPBD.
12. Tujuan pemberian bantuan perbaikan rumah masyarakat dimaksudkan untuk memperbaiki kondisi rumah masyarakat agar dapat mendukung kehidupan masyarakat, seperti komponen rumah, prasarana, dan sarana lingkungan perumahan yang memungkinkan berlangsungnya kehidupan sosial dan ekonomi yang memadai sesuai dengan standar pembangunan perumahan sebagaimana diatur dalam peraturan perundang-undangan.
13. Pemulihan sosial psikologis ditujukan untuk membantu masyarakat yang terkena dampak bencana, memulihkan kembali kehidupan sosial dan kondisi psikologis pada keadaan normal seperti kondisi sebelum bencana.
14. Kegiatan membantu masyarakat terkena dampak bencana sebagaimana dimaksud dilakukan melalui upaya pelayanan sosial psikologis berupa: (a) bantuan konseling dan konsultasi;
(b) pendampingan; (c) pelatihan; dan (d) kegiatan psikososial
15. Pelayanan kesehatan ditujukan untuk membantu masyarakat yang terkena dampak bencana dalam rangka memulihkan kondisi kesehatan masyarakat melalui pemulihan sistem pelayanan kesehatan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6026, '10. Bantuan Pemerintah sebagaimana dimaksud dapat berupa bahan material, komponen rumah atau uang yang besarnya ditetapkan berdasarkan hasil verifikasi dan evaluasi tingkat kerusakan rumah yang dialami.
11. Bantuan Pemerintah untuk perbaikan rumah masyarakat sebagaimana dimaksud diberikan dengan pola pemberdayaan masyarakat dengan memperhatikan karakter daerah dan budaya masyarakat, yang mekanisme pelaksanaannya ditetapkan melalui koordinasi BPBD.
12. Tujuan pemberian bantuan perbaikan rumah masyarakat dimaksudkan untuk memperbaiki kondisi rumah masyarakat agar dapat mendukung kehidupan masyarakat, seperti komponen rumah, prasarana, dan sarana lingkungan perumahan yang memungkinkan berlangsungnya kehidupan sosial dan ekonomi yang memadai sesuai dengan standar pembangunan perumahan sebagaimana diatur dalam peraturan perundang-undangan.
13. Pemulihan sosial psikologis ditujukan untuk membantu masyarakat yang terkena dampak bencana, memulihkan kembali kehidupan sosial dan kondisi psikologis pada keadaan normal seperti kondisi sebelum bencana.
14. Kegiatan membantu masyarakat terkena dampak bencana sebagaimana dimaksud dilakukan melalui upaya pelayanan sosial psikologis berupa: (a) bantuan konseling dan konsultasi;
(b) pendampingan; (c) pelatihan; dan (d) kegiatan psikososial
15. Pelayanan kesehatan ditujukan untuk membantu masyarakat yang terkena dampak bencana dalam rangka memulihkan kondisi kesehatan masyarakat melalui pemulihan sistem pelayanan kesehatan masyarakat.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6027, 'perka-11-2008', 15, 'lampiran', 'Lampiran hal. 7', NULL, 7, '16. Kegiatan pemulihan kondisi kesehatan masyarakat terkena dampak bencana sebagaimana dimaksud dilakukan melalui: (a) membantu perawatan lanjut korban bencana yang sakit dan mengalami luka; (b) menyediakan obat-obatan; (c) menyediakan peralatan kesehatan; (d) menyediakan tenaga medis dan paramedis; dan (e) memfungsikan kembali sistem pelayanan kesehatan termasuk sistem rujukan.
17. Rekonsiliasi ditujukan untuk membantu masyarakat di daerah bencana dan rawan konflik sosial untuk menurunkan eskalasi konflik sosial dan ketegangan serta memulihkan kondisi sosial kehidupan masyarakat.
18. Kegiatan rekonsiliasi dan resolusi konflik sebagaimana dimaksud dilakukan melalui upaya-upaya mediasi persuasif dengan melibatkan tokoh-tokoh masyarakat terkait dengan tetap memperhatikan situasi, kondisi, dan karakter serta budaya masyarakat setempat dan menjunjung rasa keadilan.
19. Pemulihan sosial ekonomi budaya ditujukan untuk membantu masyarakat terkena dampak bencana dalam rangka memulihkan kondisi kehidupan sosial, ekonomi, dan budaya seperti pada kondisi sebelum terjadi bencana.
20. Kegiatan pemulihan sosial, ekonomi, dan budaya sebagaimana dimaksud dilakukan dengan membantu masyarakat menghidupkan dan mengaktifkan kembali kegiatan sosial, ekonomi, dan budaya melalui: (a) layanan advokasi dan konseling;
(b) bantuan stimulan aktivitas; dan (c) pelatihan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6027, '16. Kegiatan pemulihan kondisi kesehatan masyarakat terkena dampak bencana sebagaimana dimaksud dilakukan melalui: (a) membantu perawatan lanjut korban bencana yang sakit dan mengalami luka; (b) menyediakan obat-obatan; (c) menyediakan peralatan kesehatan; (d) menyediakan tenaga medis dan paramedis; dan (e) memfungsikan kembali sistem pelayanan kesehatan termasuk sistem rujukan.
17. Rekonsiliasi ditujukan untuk membantu masyarakat di daerah bencana dan rawan konflik sosial untuk menurunkan eskalasi konflik sosial dan ketegangan serta memulihkan kondisi sosial kehidupan masyarakat.
18. Kegiatan rekonsiliasi dan resolusi konflik sebagaimana dimaksud dilakukan melalui upaya-upaya mediasi persuasif dengan melibatkan tokoh-tokoh masyarakat terkait dengan tetap memperhatikan situasi, kondisi, dan karakter serta budaya masyarakat setempat dan menjunjung rasa keadilan.
19. Pemulihan sosial ekonomi budaya ditujukan untuk membantu masyarakat terkena dampak bencana dalam rangka memulihkan kondisi kehidupan sosial, ekonomi, dan budaya seperti pada kondisi sebelum terjadi bencana.
20. Kegiatan pemulihan sosial, ekonomi, dan budaya sebagaimana dimaksud dilakukan dengan membantu masyarakat menghidupkan dan mengaktifkan kembali kegiatan sosial, ekonomi, dan budaya melalui: (a) layanan advokasi dan konseling;
(b) bantuan stimulan aktivitas; dan (c) pelatihan.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6028, 'perka-11-2008', 16, 'lampiran', 'Lampiran hal. 8', NULL, 8, '21. Pemulihan keamanan dan ketertiban ditujukan untuk membantu masyarakat dalam memulihkan kondisi keamanan dan ketertiban masyarakat di daerah terkena dampak bencana agar kembali seperti kondisi sebelum terjadi bencana.
22. Kegiatan pemulihan keamanan dan ketertiban dilakukan melalui upaya: (a) mengaktifkan kembali fungsi lembaga keamanan dan ketertiban di daerah bencana; (b) meningkatkan peranserta masyarakat dalam kegiatan pengamanan dan ketertiban; dan
(c) mengkoordinasi instansi/lembaga yang berwenang di bidang keamanan dan ketertiban.
23. Pemulihan fungsi pemerintahan ditujukan untuk memulihkan fungsi pemerintahan kembali seperti kondisi sebelum terjadi bencana.
24. Kegiatan pemulihan fungsi pemerintahan dilakukan melalui upaya: (a) mengaktifkan kembali pelaksanaan kegiatan tugas-tugas pemerintahan secepatnya; (b) penyelamatan dan pengamanan dokumen-dokumen negara dan pemerintahan;
(c) konsolidasi para petugas pemerintahan; (d) pemulihan fungsi-fungsi dan peralatan pendukung tugas-tugas pemerintahan; dan (e) pengaturan kembali tugas-tugas pemerintahan pada instansi/lembaga terkait.
25. Pemulihan fungsi pelayanan publik ditujukan untuk memulihkan kembali fungsi pelayanan kepada masyarakat pada kondisi seperti sebelum terjadi bencana.
26. Kegiatan pemulihan fungsi pelayanan publik sebagaimana dimaksud dilakukan melalui upaya-upaya : (a) rehabilitasi dan pemulihan fungsi prasarana dan sarana pelayanan publik;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6028, '21. Pemulihan keamanan dan ketertiban ditujukan untuk membantu masyarakat dalam memulihkan kondisi keamanan dan ketertiban masyarakat di daerah terkena dampak bencana agar kembali seperti kondisi sebelum terjadi bencana.
22. Kegiatan pemulihan keamanan dan ketertiban dilakukan melalui upaya: (a) mengaktifkan kembali fungsi lembaga keamanan dan ketertiban di daerah bencana; (b) meningkatkan peranserta masyarakat dalam kegiatan pengamanan dan ketertiban; dan
(c) mengkoordinasi instansi/lembaga yang berwenang di bidang keamanan dan ketertiban.
23. Pemulihan fungsi pemerintahan ditujukan untuk memulihkan fungsi pemerintahan kembali seperti kondisi sebelum terjadi bencana.
24. Kegiatan pemulihan fungsi pemerintahan dilakukan melalui upaya: (a) mengaktifkan kembali pelaksanaan kegiatan tugas-tugas pemerintahan secepatnya; (b) penyelamatan dan pengamanan dokumen-dokumen negara dan pemerintahan;
(c) konsolidasi para petugas pemerintahan; (d) pemulihan fungsi-fungsi dan peralatan pendukung tugas-tugas pemerintahan; dan (e) pengaturan kembali tugas-tugas pemerintahan pada instansi/lembaga terkait.
25. Pemulihan fungsi pelayanan publik ditujukan untuk memulihkan kembali fungsi pelayanan kepada masyarakat pada kondisi seperti sebelum terjadi bencana.
26. Kegiatan pemulihan fungsi pelayanan publik sebagaimana dimaksud dilakukan melalui upaya-upaya : (a) rehabilitasi dan pemulihan fungsi prasarana dan sarana pelayanan publik;', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6029, 'perka-11-2008', 17, 'lampiran', 'Lampiran hal. 8', NULL, 8, '(b) mengaktifkan kembali fungsi pelayanan publik pada instansi/lembaga terkait; dan (c) pengaturan kembali fungsi pelayanan publik.
BAB II KEBIJAKAN, STRATEGI DAN SASARAN A. Ketentuan Umum dalam Kebijakan Rehabilitasi Kebijakan penyelenggaraan rehabilitasi dilandaskan pada ketentuan sebagai berikut :
1. Kegiatan rehabilitasi merupakan tanggungjawab Pemerintah dan/atau Pemerintah Daerah yang terkena bencana.
2. Kegiatan rehabilitasi dilaksanakan oleh Satuan Kerja Pemerintah Daerah dan instansi/lembaga terkait yang dikoordinasikan oleh Kepala BPBD.
3. Dalam melaksanakan kegiatan rehabilitasi, Pemerintah Kabupaten/Kota wajib menggunakan dana penanggulangan bencana dari APBD Kabupaten/Kota.
4. Dalam hal APBD Kabupaten/Kota tidak memadai, Pemerintah Kabupaten/Kota dapat meminta bantuan dana kepada Pemerintah Provinsi dan/atau Pemerintah.
5. Dalam hal Pemerintah Kabupaten/Kota meminta bantuan kepada Pemerintah, permintaan tersebut harus melalui Pemerintah Provinsi yang bersangkutan.
6. Selain permintaan dana, Pemerintah Kabupaten/Kota dapat meminta bantuan tenaga ahli, peralatan dan/atau pembangunan prasarana kepada Pemerintah Provinsi dan/atau Pemerintah.
7. Terhadap usul permintaan bantuan dari Pemerintah Daerah dilakukan verifikasi oleh tim antar departemen/lembaga Pemerintah Nondepartemen yang dikoordinasikan oleh Kepala BNPB.
8. Verifikasi menentukan besaran bantuan yang akan diberikan Pemerintah kepada Pemerintah Daerah secara proporsional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6029, '(b) mengaktifkan kembali fungsi pelayanan publik pada instansi/lembaga terkait; dan (c) pengaturan kembali fungsi pelayanan publik.
BAB II KEBIJAKAN, STRATEGI DAN SASARAN A. Ketentuan Umum dalam Kebijakan Rehabilitasi Kebijakan penyelenggaraan rehabilitasi dilandaskan pada ketentuan sebagai berikut :
1. Kegiatan rehabilitasi merupakan tanggungjawab Pemerintah dan/atau Pemerintah Daerah yang terkena bencana.
2. Kegiatan rehabilitasi dilaksanakan oleh Satuan Kerja Pemerintah Daerah dan instansi/lembaga terkait yang dikoordinasikan oleh Kepala BPBD.
3. Dalam melaksanakan kegiatan rehabilitasi, Pemerintah Kabupaten/Kota wajib menggunakan dana penanggulangan bencana dari APBD Kabupaten/Kota.
4. Dalam hal APBD Kabupaten/Kota tidak memadai, Pemerintah Kabupaten/Kota dapat meminta bantuan dana kepada Pemerintah Provinsi dan/atau Pemerintah.
5. Dalam hal Pemerintah Kabupaten/Kota meminta bantuan kepada Pemerintah, permintaan tersebut harus melalui Pemerintah Provinsi yang bersangkutan.
6. Selain permintaan dana, Pemerintah Kabupaten/Kota dapat meminta bantuan tenaga ahli, peralatan dan/atau pembangunan prasarana kepada Pemerintah Provinsi dan/atau Pemerintah.
7. Terhadap usul permintaan bantuan dari Pemerintah Daerah dilakukan verifikasi oleh tim antar departemen/lembaga Pemerintah Nondepartemen yang dikoordinasikan oleh Kepala BNPB.
8. Verifikasi menentukan besaran bantuan yang akan diberikan Pemerintah kepada Pemerintah Daerah secara proporsional.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6030, 'perka-11-2008', 18, 'lampiran', 'Lampiran hal. 9', NULL, 9, '9. Terhadap penggunaan bantuan yang diberikan oleh Pemerintah kepada Pemerintah Daerah dilakukan pemantauan dan evaluasi oleh tim antar departemen/lembaga Pemerintah Nondepartemen dengan melibatkan BPBD yang dikoordinasikan oleh Kepala BNPB.
Dalam penentuan kebijakan rehabilitasi prinsip dasar yang digunakan adalah sebagai berikut :
1. Menempatkan masyarakat tidak saja sebagai korban bencana, namun juga sebagai pelaku aktif dalam kegiatan rehabilitasi.
2. Kegiatan rehabilitasi merupakan rangkaian kegiatan yang terkait dan terintegrasi dengan kegiatan prabencana, tanggap darurat dan pemulihan dini serta kegiatan rekonstruksi.
3. “Early recovery” dilakukan oleh “Rapid Assessment Team” segera setelah terjadi bencana.
4. Program Rehabilitasi dimulai segera setelah masa tanggap darurat (sesuai dengan Perpres tentang Penetapan Status dan Tingkatan Bencana) dan diakhiri setelah tujuan utama rehabilitasi tercapai.
B. Strategi Strategi penyelenggaraan kegiatan rehabilitasi adalah :
1. Melibatkan dan memberdayakan masyarakat dalam tahapan pelaksanaan rehabilitasi.
2. Memperhatikan karakter bencana, daerah dan budaya masyarakat setempat.
3. Mendasarkan pada kondisi aktual di lapangan (tingkat kerugian/ kerusakan serta kendala medan).
4. Menjadikan kegiatan rehabilitasi sebagai gerakan dalam masyarakat dengan menghimpun masyarakat sebagai korban maupun pelaku aktif kegiatan rehabilitasi dalam kelompok swadaya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6030, '9. Terhadap penggunaan bantuan yang diberikan oleh Pemerintah kepada Pemerintah Daerah dilakukan pemantauan dan evaluasi oleh tim antar departemen/lembaga Pemerintah Nondepartemen dengan melibatkan BPBD yang dikoordinasikan oleh Kepala BNPB.
Dalam penentuan kebijakan rehabilitasi prinsip dasar yang digunakan adalah sebagai berikut :
1. Menempatkan masyarakat tidak saja sebagai korban bencana, namun juga sebagai pelaku aktif dalam kegiatan rehabilitasi.
2. Kegiatan rehabilitasi merupakan rangkaian kegiatan yang terkait dan terintegrasi dengan kegiatan prabencana, tanggap darurat dan pemulihan dini serta kegiatan rekonstruksi.
3. “Early recovery” dilakukan oleh “Rapid Assessment Team” segera setelah terjadi bencana.
4. Program Rehabilitasi dimulai segera setelah masa tanggap darurat (sesuai dengan Perpres tentang Penetapan Status dan Tingkatan Bencana) dan diakhiri setelah tujuan utama rehabilitasi tercapai.
B. Strategi Strategi penyelenggaraan kegiatan rehabilitasi adalah :
1. Melibatkan dan memberdayakan masyarakat dalam tahapan pelaksanaan rehabilitasi.
2. Memperhatikan karakter bencana, daerah dan budaya masyarakat setempat.
3. Mendasarkan pada kondisi aktual di lapangan (tingkat kerugian/ kerusakan serta kendala medan).
4. Menjadikan kegiatan rehabilitasi sebagai gerakan dalam masyarakat dengan menghimpun masyarakat sebagai korban maupun pelaku aktif kegiatan rehabilitasi dalam kelompok swadaya.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6031, 'perka-11-2008', 19, 'lampiran', 'Lampiran hal. 10', NULL, 10, '5. Menyalurkan bantuan pada saat, bentuk, dan besaran yang tepat sehingga dapat memicu/membangkitkan gerakan rehabilitasi dan penanganan bencana yang menyeluruh.
C. Sasaran Sasaran kegiatan rehabilitasi adalah :
1. Kelompok manusia dan segenap kehidupan dan penghidupan yang terganggu oleh bencana
2. Sumberdaya buatan yang mengalami kerusakan akibat bencana sehingga berkurang nilai gunanya.
3. Ekosistem atau lingkungan alam untuk mengembalikan fungsi ekologisnya.
BAB III PROSEDUR UMUM Untuk menjamin efektifitas dan efisiensi penyelenggaraan, kegiatan rehabilitasi mengikuti prosedur umum sebagai berikut :
A. Sosialisasi dan Koordinasi Program
1. Koordinasi jajaran pemerintahan hingga tingkat Desa/Kelurahan.
2. Sosialisasi kepada masyarakat umum dan korban.
3. Membangun kebersamaan, solidaritas, dan kerelawanan.
B. Inventarisasi dan Identifikasi Kerusakan/Kerugian
1. Inventarisasi dan identifikasi tingkat kerusakan/kerugian bencana dilakukan oleh BNPB dan/atau BPBD dan/atau unsur-unsur lain yang dikoordinasikan oleh BNPB dan/atau BPBD.
2. Verifikasi atas hasil inventarisasi dan identifikasi kerusakan/ kerugian dapat dilakukan oleh BNPB dan/atau BPBD oleh karena adanya usulan, masukan, sanggahan dari masyarakat maupun karena timbulnya bencana susulan dan hal lain yang relevan.
3. Inventarisasi, identifikasi kerusakan/kerugian atau verifikasi atas hasilnya dilakukan pada pelaksanaan “rapid assessment” tahap tanggap darurat dan atau rehabilitasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6031, '5. Menyalurkan bantuan pada saat, bentuk, dan besaran yang tepat sehingga dapat memicu/membangkitkan gerakan rehabilitasi dan penanganan bencana yang menyeluruh.
C. Sasaran Sasaran kegiatan rehabilitasi adalah :
1. Kelompok manusia dan segenap kehidupan dan penghidupan yang terganggu oleh bencana
2. Sumberdaya buatan yang mengalami kerusakan akibat bencana sehingga berkurang nilai gunanya.
3. Ekosistem atau lingkungan alam untuk mengembalikan fungsi ekologisnya.
BAB III PROSEDUR UMUM Untuk menjamin efektifitas dan efisiensi penyelenggaraan, kegiatan rehabilitasi mengikuti prosedur umum sebagai berikut :
A. Sosialisasi dan Koordinasi Program
1. Koordinasi jajaran pemerintahan hingga tingkat Desa/Kelurahan.
2. Sosialisasi kepada masyarakat umum dan korban.
3. Membangun kebersamaan, solidaritas, dan kerelawanan.
B. Inventarisasi dan Identifikasi Kerusakan/Kerugian
1. Inventarisasi dan identifikasi tingkat kerusakan/kerugian bencana dilakukan oleh BNPB dan/atau BPBD dan/atau unsur-unsur lain yang dikoordinasikan oleh BNPB dan/atau BPBD.
2. Verifikasi atas hasil inventarisasi dan identifikasi kerusakan/ kerugian dapat dilakukan oleh BNPB dan/atau BPBD oleh karena adanya usulan, masukan, sanggahan dari masyarakat maupun karena timbulnya bencana susulan dan hal lain yang relevan.
3. Inventarisasi, identifikasi kerusakan/kerugian atau verifikasi atas hasilnya dilakukan pada pelaksanaan “rapid assessment” tahap tanggap darurat dan atau rehabilitasi.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6032, 'perka-11-2008', 20, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'C. Perencanaan dan Penetapan Prioritas
1. Perencanaan dan penetapan prioritas di tingkat masyarakat yang dilakukan secara partisipatif oleh kelompok masyarakat merupakan masukan penting bagi program rehabilitasi.
2. Sinkronisasi rencana dan program meliputi : sinkronisasi program tahapan rehabilitasi, prabencana, tanggap darurat dan rekonstruksi, sinkronisasi lintas-pelaku, sinkronisasi lintas-sektor, sinkronisasi lintas-wilayah.
3. Perencanaan, penetapan prioritas dan sinkronisasi program dilakukan oleh BPBD dan/atau BNPB.
D. Mobilisasi Sumberdaya Mobilisasi sumberdaya yang meliputi sumberdaya manusia, peralatan, material dan dana dilakukan dengan mempertimbangkan sumberdaya yang tersedia. Sumberdaya manusia yang memahami dan mempunyai ketrampilan secara profesional sangat diperlukan dalam semua proses dan kegiatan rehabilitasi pascabencana. Sumberdaya yang berupa peralatan, material dan dana disediakan dan siap dialokasikan untuk menunjang proses rehabilitasi.
E. Pelaksanaan Rehabilitasi Pelaksanaan rehabilitasi meliputi kegiatan perbaikan fisik dan pemulihan fungsi non-fisik. Kegiatan rehabilitasi dilaksanakan di wilayah yang terkena bencana maupun wilayah lain yang dimungkinkan untuk dijadikan wilayah sasaran kegiatan rehabilitasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6032, 'C. Perencanaan dan Penetapan Prioritas
1. Perencanaan dan penetapan prioritas di tingkat masyarakat yang dilakukan secara partisipatif oleh kelompok masyarakat merupakan masukan penting bagi program rehabilitasi.
2. Sinkronisasi rencana dan program meliputi : sinkronisasi program tahapan rehabilitasi, prabencana, tanggap darurat dan rekonstruksi, sinkronisasi lintas-pelaku, sinkronisasi lintas-sektor, sinkronisasi lintas-wilayah.
3. Perencanaan, penetapan prioritas dan sinkronisasi program dilakukan oleh BPBD dan/atau BNPB.
D. Mobilisasi Sumberdaya Mobilisasi sumberdaya yang meliputi sumberdaya manusia, peralatan, material dan dana dilakukan dengan mempertimbangkan sumberdaya yang tersedia. Sumberdaya manusia yang memahami dan mempunyai ketrampilan secara profesional sangat diperlukan dalam semua proses dan kegiatan rehabilitasi pascabencana. Sumberdaya yang berupa peralatan, material dan dana disediakan dan siap dialokasikan untuk menunjang proses rehabilitasi.
E. Pelaksanaan Rehabilitasi Pelaksanaan rehabilitasi meliputi kegiatan perbaikan fisik dan pemulihan fungsi non-fisik. Kegiatan rehabilitasi dilaksanakan di wilayah yang terkena bencana maupun wilayah lain yang dimungkinkan untuk dijadikan wilayah sasaran kegiatan rehabilitasi.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6033, 'perka-11-2008', 21, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'Kegiatan rehabilitasi dilakukan oleh BNPB jika status bencana adalah tingkat nasional atau atas inisiatif sendiri BNPB dan atau BPBD untuk status bencana daerah. Kegiatan rehabilitasi juga dimungkinkan untuk melibatkan banyak pemangku kepentingan dan masyarakat.
F. Monitoring, Evaluasi, dan Pelaporan Pemantauan penyelenggaraan rehabilitasi pascabencana diperlukan sebagai upaya untuk memantau secara terus-menerus terhadap proses dan kegiatan rehabilitasi.
Pelaksanaan pemantauan kegiatan rehabilitasi dilakukan oleh unsur pengarah beserta unsur pelaksana BNPB dan atau BPBD dan dapat melibatkan lembaga/institusi perencanaan di tingkat nasional dan/atau daerah, sebagai bahan menyeluruh dalam penyelenggaraan rehabilitasi.
Penyusunan laporan penyelenggaraan rehabilitasi pascabencana dilakukan oleh unsur pengarah dan/atau unsur pelaksana BNPB dan/atau BPBD. Laporan penyelenggaraan rehabilitasi selanjutnya digunakan untuk memverifikasi perencanaan program rehabilitasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6033, 'Kegiatan rehabilitasi dilakukan oleh BNPB jika status bencana adalah tingkat nasional atau atas inisiatif sendiri BNPB dan atau BPBD untuk status bencana daerah. Kegiatan rehabilitasi juga dimungkinkan untuk melibatkan banyak pemangku kepentingan dan masyarakat.
F. Monitoring, Evaluasi, dan Pelaporan Pemantauan penyelenggaraan rehabilitasi pascabencana diperlukan sebagai upaya untuk memantau secara terus-menerus terhadap proses dan kegiatan rehabilitasi.
Pelaksanaan pemantauan kegiatan rehabilitasi dilakukan oleh unsur pengarah beserta unsur pelaksana BNPB dan atau BPBD dan dapat melibatkan lembaga/institusi perencanaan di tingkat nasional dan/atau daerah, sebagai bahan menyeluruh dalam penyelenggaraan rehabilitasi.
Penyusunan laporan penyelenggaraan rehabilitasi pascabencana dilakukan oleh unsur pengarah dan/atau unsur pelaksana BNPB dan/atau BPBD. Laporan penyelenggaraan rehabilitasi selanjutnya digunakan untuk memverifikasi perencanaan program rehabilitasi.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6034, 'perka-11-2008', 22, 'lampiran', 'Lampiran hal. 13', NULL, 13, 'BAB IV RUANG LINGKUP PELAKSANAAN Ruang lingkup pelaksanaan rehabilitasi pascabencana dilakukan melalui kegiatan-kegiatan : perbaikan lingkungan daerah bencana, perbaikan prasarana dan sarana umum, pemberian bantuan perbaikan rumah masyarakat, pemulihan sosial psikologis, pelayanan kesehatan, rekonsiliasi dan resolusi konflik, pemulihan sosial, ekonomi dan budaya, pemulihan keamanan dan ketertiban, pemulihan fungsi pemerintahan, dan pemulihan fungsi pelayanan publik (Pasal 56, Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana).
A. Perbaikan Lingkungan Daerah Bencana
1. Cakupan Perbaikan lingkungan fisik meliputi kegiatan : perbaikan lingkungan fisik untuk kawasan permukiman, kawasan industri, kawasan usaha dan kawasan gedung
2. Indikator Capaian Kondisi lingkungan yang memenuhi persyaratan teknis, sosial, ekonomi, dan budaya serta ekosistem suatu kawasan sebagaimana sebelum terjadinya bencana.
Tabel Indikator Pencapaian Perbaikan Lingkungan Pascabencana Komponen Elemen Indikator
1. Kawasan Komponen lingkungan • Terciptanya lingkungan udara yang permukiman udara, lingkungan nyaman/tidak tercemar; perairan, lingkungan • Terciptanya lingkungan perairan yang vegetasi/tanaman, dan bersih dan sehat; lingkungan sosial
• Terciptanya lingkungan yang nyaman dengan tanaman yang menyejukkan;
• Terciptanya lingkungan permukiman/ sosial yang baik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6034, 'BAB IV RUANG LINGKUP PELAKSANAAN Ruang lingkup pelaksanaan rehabilitasi pascabencana dilakukan melalui kegiatan-kegiatan : perbaikan lingkungan daerah bencana, perbaikan prasarana dan sarana umum, pemberian bantuan perbaikan rumah masyarakat, pemulihan sosial psikologis, pelayanan kesehatan, rekonsiliasi dan resolusi konflik, pemulihan sosial, ekonomi dan budaya, pemulihan keamanan dan ketertiban, pemulihan fungsi pemerintahan, dan pemulihan fungsi pelayanan publik (Pasal 56, Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana).
A. Perbaikan Lingkungan Daerah Bencana
1. Cakupan Perbaikan lingkungan fisik meliputi kegiatan : perbaikan lingkungan fisik untuk kawasan permukiman, kawasan industri, kawasan usaha dan kawasan gedung
2. Indikator Capaian Kondisi lingkungan yang memenuhi persyaratan teknis, sosial, ekonomi, dan budaya serta ekosistem suatu kawasan sebagaimana sebelum terjadinya bencana.
Tabel Indikator Pencapaian Perbaikan Lingkungan Pascabencana Komponen Elemen Indikator
1. Kawasan Komponen lingkungan • Terciptanya lingkungan udara yang permukiman udara, lingkungan nyaman/tidak tercemar; perairan, lingkungan • Terciptanya lingkungan perairan yang vegetasi/tanaman, dan bersih dan sehat; lingkungan sosial
• Terciptanya lingkungan yang nyaman dengan tanaman yang menyejukkan;
• Terciptanya lingkungan permukiman/ sosial yang baik.', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6035, 'perka-11-2008', 23, 'lampiran', 'Lampiran hal. 13', NULL, 13, '2. Kawasan Komponen udara, air, • Terciptanya lingkungan udara yang industri tanaman dan area nyaman/tidak tercemar; parkir serta open • Terciptanya lingkungan perairan yang space/taman bersih dan sehat;
• Terciptanya lingkungan yang nyaman dengan tanaman yang menyejukkan.
Komponen Elemen Indikator
3. Kawasan Komponen udara, air, • Terciptanya lingkungan udara yang usaha dan kawasan hijau/ nyaman/tidak tercemar; taman • Terciptanya lingkungan perairan yang bersih dan sehat;
• Terciptanya lingkungan yang nyaman dengan tanaman yang menyejukkan.
4. Kawasan Komponen udara, air, • Terciptanya lingkungan udara yang bangunan tanaman/taman nyaman/tidak tercemar; gedung • Terciptanya lingkungan perairan yang bersih dan sehat;
• Terciptanya lingkungan yang nyaman dengan tanaman yang menyejukkan.
3. Prosedur/Persyaratan Teknis Perencanaan teknis perbaikan lingkungan paling sedikit memuat:
a. data kependudukan, sosial, budaya, ekonomi, prasarana, dan sarana sebelum terjadi bencana;
b. data kerusakan yang meliputi lokasi, data korban bencana, jumlah dan tingkat kerusakan bencana, dan perkiraan kerugian;
c. potensi sumber daya yang ada di daerah bencana;
d. peta tematik yang berisi sebagaimana dimaksud pada huruf a, huruf b, dan huruf c;
e. rencana program dan kegiatan;
f. gambar desain;
g. rencana anggaran; dan
h. jadwal kegiatan.
Deskripsi Perencanaan Teknis kegiatan di atas adalah sebagai berikut :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6035, '2. Kawasan Komponen udara, air, • Terciptanya lingkungan udara yang industri tanaman dan area nyaman/tidak tercemar; parkir serta open • Terciptanya lingkungan perairan yang space/taman bersih dan sehat;
• Terciptanya lingkungan yang nyaman dengan tanaman yang menyejukkan.
Komponen Elemen Indikator
3. Kawasan Komponen udara, air, • Terciptanya lingkungan udara yang usaha dan kawasan hijau/ nyaman/tidak tercemar; taman • Terciptanya lingkungan perairan yang bersih dan sehat;
• Terciptanya lingkungan yang nyaman dengan tanaman yang menyejukkan.
4. Kawasan Komponen udara, air, • Terciptanya lingkungan udara yang bangunan tanaman/taman nyaman/tidak tercemar; gedung • Terciptanya lingkungan perairan yang bersih dan sehat;
• Terciptanya lingkungan yang nyaman dengan tanaman yang menyejukkan.
3. Prosedur/Persyaratan Teknis Perencanaan teknis perbaikan lingkungan paling sedikit memuat:
a. data kependudukan, sosial, budaya, ekonomi, prasarana, dan sarana sebelum terjadi bencana;
b. data kerusakan yang meliputi lokasi, data korban bencana, jumlah dan tingkat kerusakan bencana, dan perkiraan kerugian;
c. potensi sumber daya yang ada di daerah bencana;
d. peta tematik yang berisi sebagaimana dimaksud pada huruf a, huruf b, dan huruf c;
e. rencana program dan kegiatan;
f. gambar desain;
g. rencana anggaran; dan
h. jadwal kegiatan.
Deskripsi Perencanaan Teknis kegiatan di atas adalah sebagai berikut :', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6036, 'perka-11-2008', 24, 'lampiran', 'Lampiran hal. 14', NULL, 14, '1. Data Kependudukan. Data ini memuat perkembangan jumlah penduduk, kepadatan penduduk, distribusi penduduk menurut ruang (per desa, kecamatan, kabupaten) dan dirinci sesuai dengan kebutuhan rehabilitasi. Misalnya data penduduk yang menyangkut jumlah usia rentan, jumlah penduduk usia produktif, jumlah penduduk usia sekolah, jumlah tenaga kerja, dan sebagainya. Selain itu juga diperlukan Peta Kependudukan sebelum terjadi bencana. Peta Kependudukan dibuat dengan skala yang memadai, misalnya skala 1 : 50.000 (untuk wilayah Kabupaten/Kota), skala 1 : 25.000 atau 1 : 10.000 (skala Kecamatan) dan skala 1 : 5000 (skala Desa).
2. Data kerusakan dilakukan oleh Tim Kaji Cepat (Rapid Assessment Team) yang dibentuk oleh BPBD dan atau BNPB dengan menggunakan metode baku yang berlaku; sedangkan data kerusakan rumah, bangunan, sarana dan prasarana, serta jasa lingkungan harus memuat lokasi, tingkat kerusakan (ringan, sedang, berat, sangat berat), dan analisis kerugian. Metode untuk memperkirakan lokasi dan tingkat kerusakan dapat dilakukan secara cepat dengan metode partisipatif sesuai dengan kapasitas sumberdaya manusia yang ada pada BPBD dan atau menggunakan teknologi geoinformasi melalui interpretasi citra penginderaan jauh dan menggunakan bantuan SIG (Sistem Informasi Geografis).
3. Kebutuhan dan persediaan potensi sumberdaya yang ada di daerah bencana mengacu pada Sistem Informasi Penanggulangan Bencana Indonesia (SIPBI) yang ada di BNPB dan atau BPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6036, '1. Data Kependudukan. Data ini memuat perkembangan jumlah penduduk, kepadatan penduduk, distribusi penduduk menurut ruang (per desa, kecamatan, kabupaten) dan dirinci sesuai dengan kebutuhan rehabilitasi. Misalnya data penduduk yang menyangkut jumlah usia rentan, jumlah penduduk usia produktif, jumlah penduduk usia sekolah, jumlah tenaga kerja, dan sebagainya. Selain itu juga diperlukan Peta Kependudukan sebelum terjadi bencana. Peta Kependudukan dibuat dengan skala yang memadai, misalnya skala 1 : 50.000 (untuk wilayah Kabupaten/Kota), skala 1 : 25.000 atau 1 : 10.000 (skala Kecamatan) dan skala 1 : 5000 (skala Desa).
2. Data kerusakan dilakukan oleh Tim Kaji Cepat (Rapid Assessment Team) yang dibentuk oleh BPBD dan atau BNPB dengan menggunakan metode baku yang berlaku; sedangkan data kerusakan rumah, bangunan, sarana dan prasarana, serta jasa lingkungan harus memuat lokasi, tingkat kerusakan (ringan, sedang, berat, sangat berat), dan analisis kerugian. Metode untuk memperkirakan lokasi dan tingkat kerusakan dapat dilakukan secara cepat dengan metode partisipatif sesuai dengan kapasitas sumberdaya manusia yang ada pada BPBD dan atau menggunakan teknologi geoinformasi melalui interpretasi citra penginderaan jauh dan menggunakan bantuan SIG (Sistem Informasi Geografis).
3. Kebutuhan dan persediaan potensi sumberdaya yang ada di daerah bencana mengacu pada Sistem Informasi Penanggulangan Bencana Indonesia (SIPBI) yang ada di BNPB dan atau BPBD.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6037, 'perka-11-2008', 25, 'lampiran', 'Lampiran hal. 15', NULL, 15, 'Potensi sumberdaya yang ada di daerah bencana sangat diperlukan dalam rangka pelaksanaan rehabilitasi.
4. Rencana program kerja rehabilitasi, jadwal waktu pelaksanaan dan anggaran agar dibuat sebelum rehabilitasi dilaksanakan dan disetujui oleh BNPB dan atau BPBD dengan melibatkan instansi yang relevan dan masyarakat.
B. Perbaikan Prasarana dan Sarana Umum
1. Cakupan
a. Yang dimaksud dengan prasarana dan sarana umum adalah jaringan infrastruktur dan fasilitas fisik yang menunjang kegiatan kehidupan sosial dan perekonomian masyarakat;
b. Prasarana umum atau jaringan infrastruktur fisik disini mencakup : 1) jaringan jalan/perhubungan; 2) jaringan air bersih; 3) jaringan listrik; 4) jaringan komunikasi;
5) jaringan sanitasi dan limbah; dan 6) jaringan irigasi/ pertanian.
c. Sarana umum atau fasilitas sosial dan umum disini mencakup:
1) fasilitas kesehatan; 2) fasilitas perekonomian; 3) fasilitas pendidikan; 4) fasilitas perkantoran pemerintah; dan 5) fasilitas peribadatan.
2. Indikator Capaian
a. Setiap program rehabilitasi harus memenuhi sarat-sarat indikator capaian tertentu, khususnya agar masing-masing komponen prasarana dan sarana umum dapat berfungsi kembali secara memadai untuk mendukung kelangsungan kembali kehidupan sosial dan ekonomi masyarakat di wilayah bencana;
b. Setiap program rehabilitasi harus dilakukan secepat-sepatnya, sesuai prioritas dan sumber daya yang ada;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6037, 'Potensi sumberdaya yang ada di daerah bencana sangat diperlukan dalam rangka pelaksanaan rehabilitasi.
4. Rencana program kerja rehabilitasi, jadwal waktu pelaksanaan dan anggaran agar dibuat sebelum rehabilitasi dilaksanakan dan disetujui oleh BNPB dan atau BPBD dengan melibatkan instansi yang relevan dan masyarakat.
