INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6046, 'perka-11-2008', 34, 'lampiran', 'Lampiran hal. 21', NULL, 21, '5) Monitoring & Evaluasi
• Monitoring periodik.
• Evaluasi akhir program.
4. Pelaksanaan dan Organisasi Pelaksana dalam rehabilitasi rumah masyarakat melibatkan pihak-pihak berikut:
a. BNPB dan atau BPBD yang memegang fungsi kendali dan koordinasi.
b. TNI/Polri, Bappeda, Dinas PU, Dinas Kesehatan, Dinas Pendidikan, dsb. sebagai pelaksana.
c. Organisasi dan Bantuan Internasional.
d. Organisasi Kemasyarakatan dan Nonpemerintah.
D. Pemulihan Sosial Psikologis
1. Cakupan Pengertian :
a. Yang dimaksud pemulihan sosial psikologis adalah pemberian bantuan kepada masyarakat yang terkena dampak bencana agar dapat berfungsi kembali secara normal.
b. Yang dimaksud dengan kegiatan psikososial adalah kegiatan mengaktifkan elemen-elemen masyarakat agar dapat kembali menjalankan fungsi sosial secara normal. Kegiatan ini dapat dilakukan oleh siapa saja yang sudah terlatih.
c. Yang dimaksud dengan kegiatan intervensi psikologis adalah pemberian pertolongan kepada masyarakat untuk meringankan beban psikologis akibat bencana dan mencegah terjadinya dampak psikologis lebih lanjut yang mengarah kepada gangguan mental. Intervensi diberikan oleh profesional.
d. Bantuan konseling dan konsultasi keluarga adalah pemberian pertolongan kepada individu atau keluarga untuk melepaskan ketegangan dan beban psikologis secara terstruktur.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6046, '5) Monitoring & Evaluasi
• Monitoring periodik.
• Evaluasi akhir program.
4. Pelaksanaan dan Organisasi Pelaksana dalam rehabilitasi rumah masyarakat melibatkan pihak-pihak berikut:
a. BNPB dan atau BPBD yang memegang fungsi kendali dan koordinasi.
b. TNI/Polri, Bappeda, Dinas PU, Dinas Kesehatan, Dinas Pendidikan, dsb. sebagai pelaksana.
c. Organisasi dan Bantuan Internasional.
d. Organisasi Kemasyarakatan dan Nonpemerintah.
D. Pemulihan Sosial Psikologis
1. Cakupan Pengertian :
a. Yang dimaksud pemulihan sosial psikologis adalah pemberian bantuan kepada masyarakat yang terkena dampak bencana agar dapat berfungsi kembali secara normal.
b. Yang dimaksud dengan kegiatan psikososial adalah kegiatan mengaktifkan elemen-elemen masyarakat agar dapat kembali menjalankan fungsi sosial secara normal. Kegiatan ini dapat dilakukan oleh siapa saja yang sudah terlatih.
c. Yang dimaksud dengan kegiatan intervensi psikologis adalah pemberian pertolongan kepada masyarakat untuk meringankan beban psikologis akibat bencana dan mencegah terjadinya dampak psikologis lebih lanjut yang mengarah kepada gangguan mental. Intervensi diberikan oleh profesional.
d. Bantuan konseling dan konsultasi keluarga adalah pemberian pertolongan kepada individu atau keluarga untuk melepaskan ketegangan dan beban psikologis secara terstruktur.', 'Lampiran hal. 21', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6047, 'perka-11-2008', 35, 'lampiran', 'Lampiran hal. 22', NULL, 22, 'e. Pendampingan pemulihan trauma adalah pendampingan terstruktur dengan berbabagai metode terapi psikologis yang tepat kepada individu yang mengalami trauma psikologis agar dapat berfungsi secara normal kembali.
f. Pelatihan pemulihan kondisi psikologis adalah pelatihan untuk pemuka komunitas, relawan dan pihak-pihak yang ditokohkan/mampu dalam masyarakat untuk memberikan dukungan psikologis kepada masyarakatnya.
g. Pemulihan sosial psikologis bertujuan agar masyarakat mampu melakukan tugas sosial seperti sebelum terjadi bencana, serta tercegah dari mengalami dampak psikologis lebih lanjut yang mengarah pada gangguan kesehatan mental.
2. Indikator Capaian Tabel Indikator Capaian Pemulihan Sosial Psikologis Indikator Fungsi Indikator Psikis Indikator Fisik Dapat menjalankan Dapat menerima kejadian Terbebas dari gejala-gejala fungsinya dalam bencana fisik yang disebabkan oleh keluarga secara normal faktor psikologis, seperti: gangguan tidur, gangguan lambung, dll Dapat menjalankan Dapat mengelola emosi dan fungsinya dalam luka psikologis sebagai masyarakat seperti akibat bencana semula Dapat menjalankan Terbebas dari ketegangan pekerjaan seperti dan kecemasan sebelum terjadi bencana Dapat mengelola beban psikologis sehingga tidak berlanjut kepada gangguan kesehatan mental
3. Prosedur/Persyaratan Teknis
a. Kegiatan pemulihan sosial psikologis dilakukan melalui:
1) Konseling individu maupun kelompok, 2) Kegiatan psikososial, 3) Pelatihan, 4) Psikoedukasi;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6047, 'e. Pendampingan pemulihan trauma adalah pendampingan terstruktur dengan berbabagai metode terapi psikologis yang tepat kepada individu yang mengalami trauma psikologis agar dapat berfungsi secara normal kembali.
f. Pelatihan pemulihan kondisi psikologis adalah pelatihan untuk pemuka komunitas, relawan dan pihak-pihak yang ditokohkan/mampu dalam masyarakat untuk memberikan dukungan psikologis kepada masyarakatnya.
g. Pemulihan sosial psikologis bertujuan agar masyarakat mampu melakukan tugas sosial seperti sebelum terjadi bencana, serta tercegah dari mengalami dampak psikologis lebih lanjut yang mengarah pada gangguan kesehatan mental.
2. Indikator Capaian Tabel Indikator Capaian Pemulihan Sosial Psikologis Indikator Fungsi Indikator Psikis Indikator Fisik Dapat menjalankan Dapat menerima kejadian Terbebas dari gejala-gejala fungsinya dalam bencana fisik yang disebabkan oleh keluarga secara normal faktor psikologis, seperti: gangguan tidur, gangguan lambung, dll Dapat menjalankan Dapat mengelola emosi dan fungsinya dalam luka psikologis sebagai masyarakat seperti akibat bencana semula Dapat menjalankan Terbebas dari ketegangan pekerjaan seperti dan kecemasan sebelum terjadi bencana Dapat mengelola beban psikologis sehingga tidak berlanjut kepada gangguan kesehatan mental
3. Prosedur/Persyaratan Teknis
a. Kegiatan pemulihan sosial psikologis dilakukan melalui:
1) Konseling individu maupun kelompok, 2) Kegiatan psikososial, 3) Pelatihan, 4) Psikoedukasi;', 'Lampiran hal. 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6048, 'perka-11-2008', 36, 'lampiran', 'Lampiran hal. 23', NULL, 23, 'b. Mekanisme dan teknis pemulihan sosial psikologis harus mempertimbangkan karakter masyarakat, budaya setempat, kearifan kontekstual serta nilai-nila kepercayaan yang dipegang teguh masyarakat setempat.
4. Pelaksanaan dan Organisasi
a. Program pemulihan sosial psikologis dilaksanakan oleh BPBD dan dibantu lembaga/dinas/instansi terkait;
b. Dalam hal program pemulihan yang dilakukan di wilayah yang meliputi lebih dari satu daerah Kabupaten/Kota, koordinasi dilakukan oleh BPBD Provinsi dan Pemerintah Provinsi dan/atau BNPB;
c. Dalam hal program pemulihan yang dilakukan di wilayah yang meliputi lebih dari satu daerah provinsi, kordinasi dilakukan BNPB;
d. Kegiatan pemulihan sosial psikologis mendorong tokoh-tokoh masyarakat untuk mampu menolong dan memberikan dukungan psikologis kepada komunitasnya;
e. Kegiatan pemulihan sosial psikologis dapat dilakukan di berbagai setting sosial, seperti sekolah, rumah sakit, tempat peribadatan, dll.
E. Pelayanan Kesehatan
1. Cakupan Pengertian :
a. Yang dimaksud dengan pemulihan pelayanan kesehatan adalah aktivitas memulihkan kembali segala bentuk pelayanan kesehatan sehingga minimal tercapai kondisi seperti sebelum terjadi bencana.
b. Pemulihan sistem pelayanan kesehatan adalah semua usaha yang dilakukan untuk memulihkan kembali fungsi sistem pelayanan kesehatan yang meliputi: 1) SDM Kesehatan;
2) sarana/prasarana kesehatan; 3) kepercayaan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6048, 'b. Mekanisme dan teknis pemulihan sosial psikologis harus mempertimbangkan karakter masyarakat, budaya setempat, kearifan kontekstual serta nilai-nila kepercayaan yang dipegang teguh masyarakat setempat.
4. Pelaksanaan dan Organisasi
a. Program pemulihan sosial psikologis dilaksanakan oleh BPBD dan dibantu lembaga/dinas/instansi terkait;
b. Dalam hal program pemulihan yang dilakukan di wilayah yang meliputi lebih dari satu daerah Kabupaten/Kota, koordinasi dilakukan oleh BPBD Provinsi dan Pemerintah Provinsi dan/atau BNPB;
c. Dalam hal program pemulihan yang dilakukan di wilayah yang meliputi lebih dari satu daerah provinsi, kordinasi dilakukan BNPB;
d. Kegiatan pemulihan sosial psikologis mendorong tokoh-tokoh masyarakat untuk mampu menolong dan memberikan dukungan psikologis kepada komunitasnya;
e. Kegiatan pemulihan sosial psikologis dapat dilakukan di berbagai setting sosial, seperti sekolah, rumah sakit, tempat peribadatan, dll.
