INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6105, 'perka-11-2011', 3, 'menetapkan', 'Menetapkan', NULL, 4, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN INVENTARISASI PERALATAN.');
