INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6106, 'perka-11-2011', 4, 'pasal', 'Pasal 1', NULL, 4, 'Pedoman Inventarisasi Peralatan merupakan panduan/acuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/lembaga dan pemangku kepentingan penanggulangan bencana lainnya agar pelaksanaan inventarisasi peralatan dapat dilakukan dengan lancar, tertib, terpadu, aman dan dapat dipertanggungjawabkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6106, 'Pedoman Inventarisasi Peralatan merupakan panduan/acuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/lembaga dan pemangku kepentingan penanggulangan bencana lainnya agar pelaksanaan inventarisasi peralatan dapat dilakukan dengan lancar, tertib, terpadu, aman dan dapat dipertanggungjawabkan.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6107, 'perka-11-2011', 5, 'pasal', 'Pasal 2', NULL, 4, 'Pedoman sebagaimana dimaksud dalam Pasal 1 tercantum dalam Lampiran Peraturan ini dan merupakan bagian yang tidak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6107, 'Pedoman sebagaimana dimaksud dalam Pasal 1 tercantum dalam Lampiran Peraturan ini dan merupakan bagian yang tidak terpisahkan dari Peraturan ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6108, 'perka-11-2011', 6, 'pasal', 'Pasal 3', NULL, 4, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6108, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6109, 'perka-11-2011', 7, 'lain', 'Penutup', NULL, 4, 'Ditetapkan di Jakarta pada tanggal 2 November 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, A Ato (ton SYAMSUL MAARIF, M.Si. va 1');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6109, 'Ditetapkan di Jakarta pada tanggal 2 November 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, A Ato (ton SYAMSUL MAARIF, M.Si. va 1', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6110, 'perka-11-2011', 8, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 11 TAHUN 2011 TANGGAL : 3 NOVEMBER 2011 BAB I PENDAHULUAN A. Latar Belakang Peralatan penanggulangan bencana yang tersedia di lokasi harus dapat digunakan dalam keadaan situasi darurat oleh petugas bencana. Pada saat situasi darurat banyak peralatan yang diperlukan, seperti peralatan angkutan (transportasi) untuk evakuasi korban baik di darat, perairan dan udara (truk, perahu karet, helikopter, dll). Demikian pula peralatan lainnya, misalnya peralatan telekomunikasi, generator listrik, peralatan penyelamatan (rescue), peralatan diteksi dini, bulldozer, forklift, dll.
Bantuan peralatan tersebut harus dapat diperoleh dengan cepat, tepat waktu, tepat lokasi, tepat sasaran, tepat jumlah, dan dapat berfungsi.
Dalam penanggulangan bencana banyak kendala yang dihadapi oleh petugas terhadap peralatan seperti tidak dapat digunakan, tidak berkualitas (cepat rusak), bahkan tidak memilik informasi tentang dimana tempat peralatan bencana yang kondisi layak pakai dan mudah di dapat. Ketika satuan tugas akan di berangkatkan ke lokasi bencana sering kali tidak memiliki informasi tetang tempat dimana peralatan mudah di dapat, sehingga lambat dalam melakukan tindakan yang pasti dan tepat. Oleh karena itu kegiatan inventarisasi peralatan penanggulangan bencana memiliki kontribusi yang sangat penting.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6110, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 11 TAHUN 2011 TANGGAL : 3 NOVEMBER 2011 BAB I PENDAHULUAN A. Latar Belakang Peralatan penanggulangan bencana yang tersedia di lokasi harus dapat digunakan dalam keadaan situasi darurat oleh petugas bencana. Pada saat situasi darurat banyak peralatan yang diperlukan, seperti peralatan angkutan (transportasi) untuk evakuasi korban baik di darat, perairan dan udara (truk, perahu karet, helikopter, dll). Demikian pula peralatan lainnya, misalnya peralatan telekomunikasi, generator listrik, peralatan penyelamatan (rescue), peralatan diteksi dini, bulldozer, forklift, dll.
Bantuan peralatan tersebut harus dapat diperoleh dengan cepat, tepat waktu, tepat lokasi, tepat sasaran, tepat jumlah, dan dapat berfungsi.
Dalam penanggulangan bencana banyak kendala yang dihadapi oleh petugas terhadap peralatan seperti tidak dapat digunakan, tidak berkualitas (cepat rusak), bahkan tidak memilik informasi tentang dimana tempat peralatan bencana yang kondisi layak pakai dan mudah di dapat. Ketika satuan tugas akan di berangkatkan ke lokasi bencana sering kali tidak memiliki informasi tetang tempat dimana peralatan mudah di dapat, sehingga lambat dalam melakukan tindakan yang pasti dan tepat. Oleh karena itu kegiatan inventarisasi peralatan penanggulangan bencana memiliki kontribusi yang sangat penting.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6111, 'perka-11-2011', 9, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'Kegiatan inventarisasi peralatan penanggulangan bencana pada hakekatnya merupakan pengumpulan data peralatan penanggulangan bencana yang sudah tersedia atau dimiliki kementerian, lembaga dan instansi yang mempunyai tanggungjawab dalam penanggulangan bencana. Kegiatan inventarisasi peralatan dilaksanakan pada pemerintah pusat (kementerian, lembaga dan instansi terkait), pemerintah daerah (propinsi, kabupaten/kota), dunia usaha dan masyarakat. Data peralatan penanggulangan bencana akan memiliki kontribusi yang besar bagi kesiapsiagaan, tanggap darurat dan pasca bencana di setiap daerah rawan bencana, jika sewaktu-waktu terjadi bencana. Pada saat ini belum semua daerah memiliki peralatan penanggulangan bencana yang memadai dan lengkap, serta 2 belum memiliki data dan informasi yang menerangkan daerah mana yang sudah siap dan daerah mana yang belum siap dalam hal peralatan penanggulangan bencana.
Oleh karena itu, kegiatan inventarisasi peralatan juga berguna untuk melakukan analisis kebutuhan peralatan penanggulangan bencana bagi semua daerah di seluruh wilayah Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6111, 'Kegiatan inventarisasi peralatan penanggulangan bencana pada hakekatnya merupakan pengumpulan data peralatan penanggulangan bencana yang sudah tersedia atau dimiliki kementerian, lembaga dan instansi yang mempunyai tanggungjawab dalam penanggulangan bencana. Kegiatan inventarisasi peralatan dilaksanakan pada pemerintah pusat (kementerian, lembaga dan instansi terkait), pemerintah daerah (propinsi, kabupaten/kota), dunia usaha dan masyarakat. Data peralatan penanggulangan bencana akan memiliki kontribusi yang besar bagi kesiapsiagaan, tanggap darurat dan pasca bencana di setiap daerah rawan bencana, jika sewaktu-waktu terjadi bencana. Pada saat ini belum semua daerah memiliki peralatan penanggulangan bencana yang memadai dan lengkap, serta 2 belum memiliki data dan informasi yang menerangkan daerah mana yang sudah siap dan daerah mana yang belum siap dalam hal peralatan penanggulangan bencana.
Oleh karena itu, kegiatan inventarisasi peralatan juga berguna untuk melakukan analisis kebutuhan peralatan penanggulangan bencana bagi semua daerah di seluruh wilayah Indonesia.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6112, 'perka-11-2011', 10, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'Badan Nasional Penanggulangan Bencana (BNPB) pada saat ini juga belum memiliki data kebutuhan peralatan yang memadai terutama pada daerah rawan bencana, maka perlu untuk melakukan inventarisasi atau pengumpulan data kebutuhan peralatan guna mengetahui besaran peralatan yang tersedia dengan kebutuhan nyata pada daerah rawan bencana. Dalam pelaksanaannya kegiatan inventarisasi peralatan ini memerlukan pedoman agar petugas memiliki tindakan yang pasti dan tepat.
B. Maksud Dan Tujuan
1. Maksud Sebagai acuan bagi BNPB, BPBD, Kementrian / Lembaga dan Instansi Terkait dalam penyelenggaraan inventarisasi peralatan penanggulangan bencana
2. Tujuan Memudahkan petugas dan pemangku kepentingan dalam melakukan inventarisasi peralatan yang tersedia pada pemerintah, pemerintah daerah, dunia usaha dan masyarakat yang dapat dilaksanakan secara, cepat, tepat, terpadu dan akuntabel C. Landasan Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana
3. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
4. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana.
5. Peraturan Pemerintah Nomor 38 Tahun 2008 tentang perubahan Peraturan Pemerintah Nomor 6 Tahun 2006 tentang Pengelolaan Barang Milik Negara/Daerah.
3');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6112, 'Badan Nasional Penanggulangan Bencana (BNPB) pada saat ini juga belum memiliki data kebutuhan peralatan yang memadai terutama pada daerah rawan bencana, maka perlu untuk melakukan inventarisasi atau pengumpulan data kebutuhan peralatan guna mengetahui besaran peralatan yang tersedia dengan kebutuhan nyata pada daerah rawan bencana. Dalam pelaksanaannya kegiatan inventarisasi peralatan ini memerlukan pedoman agar petugas memiliki tindakan yang pasti dan tepat.
B. Maksud Dan Tujuan
1. Maksud Sebagai acuan bagi BNPB, BPBD, Kementrian / Lembaga dan Instansi Terkait dalam penyelenggaraan inventarisasi peralatan penanggulangan bencana
2. Tujuan Memudahkan petugas dan pemangku kepentingan dalam melakukan inventarisasi peralatan yang tersedia pada pemerintah, pemerintah daerah, dunia usaha dan masyarakat yang dapat dilaksanakan secara, cepat, tepat, terpadu dan akuntabel C. Landasan Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana
3. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
4. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana.
5. Peraturan Pemerintah Nomor 38 Tahun 2008 tentang perubahan Peraturan Pemerintah Nomor 6 Tahun 2006 tentang Pengelolaan Barang Milik Negara/Daerah.
3', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6113, 'perka-11-2011', 11, 'lampiran', 'Lampiran hal. 7', NULL, 7, '6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
7. Peraturan Menteri Keuangan 171/PMK.05/2007 tentang Sistem Akuntasi dan Pelaporan Keuangan Keuangan Pemerintah Pusat.
8. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008 tentang Pedoman Pembentukan Badan Penanggulangan Bencana Daerah
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana.
10. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah.
11. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008 tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana.
12. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan.
13. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2009 tentang Pedoman Standarisasi Peralatan Penanggulangan Bencana D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6113, '6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
7. Peraturan Menteri Keuangan 171/PMK.05/2007 tentang Sistem Akuntasi dan Pelaporan Keuangan Keuangan Pemerintah Pusat.
8. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008 tentang Pedoman Pembentukan Badan Penanggulangan Bencana Daerah
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana.
10. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah.
11. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008 tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana.
12. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan.
13. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2009 tentang Pedoman Standarisasi Peralatan Penanggulangan Bencana D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6114, 'perka-11-2011', 12, 'lampiran', 'Lampiran hal. 7', NULL, 7, '2. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, serta kegiatan rehabilitasi dan rekonstruksi.
3. Peralatan adalah segala bentuk alat dan peralatan yang dapat dipergunakan untuk membantu terselenggaranya suatu kegiatan sehingga dengan bantuan alat tersebut manusia dapat memenuhi kebutuhannya dan dapat melaksanakan fungsi kehidupannya sebagai manusia. Termasuk dalam kategori peralatan ini misalnya 4 peralatan kesehatan, peralatan komunikasi, peralatan peringatan dini, peralatan teknik dan sebagainya.
4. Inventarisasi adalah kegiatan pendataan, pencatatan dan pelaporan kondisi fisik sebagai bahan analisis kebutuhan atas peralatan.
5. Inventarisasi Peralatan Penanggulangan Bencana adalah kegiatan pendataan, pencatatan, dan pelaporan sebagai bahan analisis kebutuhan peralatan penanggulangan bencana.
E. Ruang Lingkup Dan Sistematika
1. Ruang lingkup Pedoman inventarisasi peralatan penanggulangan bencana meliputi penyelenggaraan, prosedur, pemantauan dan evaluasi inventarisasi peralatan.
2. Sistematika Pedoman Inventarisasi Peralatan ini, disusun dengan sistematika sebagai berikut:
I. Pendahuluan
II. Penyelenggaraan Inventarisasi Peralatan
III. Prosedur Penyelenggaraan Inventarisasi Peralatan
IV. Pemantuan dan Evaluasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6114, '2. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, serta kegiatan rehabilitasi dan rekonstruksi.
3. Peralatan adalah segala bentuk alat dan peralatan yang dapat dipergunakan untuk membantu terselenggaranya suatu kegiatan sehingga dengan bantuan alat tersebut manusia dapat memenuhi kebutuhannya dan dapat melaksanakan fungsi kehidupannya sebagai manusia. Termasuk dalam kategori peralatan ini misalnya 4 peralatan kesehatan, peralatan komunikasi, peralatan peringatan dini, peralatan teknik dan sebagainya.
4. Inventarisasi adalah kegiatan pendataan, pencatatan dan pelaporan kondisi fisik sebagai bahan analisis kebutuhan atas peralatan.
5. Inventarisasi Peralatan Penanggulangan Bencana adalah kegiatan pendataan, pencatatan, dan pelaporan sebagai bahan analisis kebutuhan peralatan penanggulangan bencana.
E. Ruang Lingkup Dan Sistematika
1. Ruang lingkup Pedoman inventarisasi peralatan penanggulangan bencana meliputi penyelenggaraan, prosedur, pemantauan dan evaluasi inventarisasi peralatan.
2. Sistematika Pedoman Inventarisasi Peralatan ini, disusun dengan sistematika sebagai berikut:
I. Pendahuluan
II. Penyelenggaraan Inventarisasi Peralatan
III. Prosedur Penyelenggaraan Inventarisasi Peralatan
IV. Pemantuan dan Evaluasi', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6115, 'perka-11-2011', 13, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'V. Penutup 5 BAB II PENYELENGGARAAN INVENTARISASI PERALATAN A. Tujuan Inventarisasi Peralatan Tujuan Inventarisasi peralatan untuk :
1. Memperoleh data dan informasi tentang jenis, jumlah, kondisi dan sebaran peralatan penanggulangan bencana yang tersedia pada pemerintah, pemerintah daerah, dunia usaha dan masyarakat.
2. Penyusunan rencana dan pelaksanaan penanggulangan bencana.
3. Penunjang pengawasan dan pengendalian.
4. Melakukan analisis kebutuhan peralatan penanggulangan bencana.
5. Laporan pertanggungjawaban.
B. Prinsip-prinsip Inventarisasi Peralatan Kegiatan inventarisasi peralatan penanggulangan bencana harus dilaksanakan sesuai dengan prinsip-prinsip:
1. Akurat Kegiatan inventarisasi peralatan penangulangan bencana harus menghasilkan data yang akurat baik jenis, jumlah, kondisi dan sebaran peralatan yang tersedia dan yang perlu disediakan di suatu wilayah.
2. Terkini Kegiatan inventarisasi peralatan penangulangan bencana harus menghasilkan data yang terbaru.
3. Berkelanjutan Kegiatan inventarisasi peralatan penangulangan bencana harus dilakukan secara berkala dan kontinyu.
4. Komprehensif Kegiatan inventarisasi peralatan penanggulangan bencana harus menghasilkan data yang lengkap tentang jenis, jumlah dan kondisi, peralatan yang tersedia dan perlu disediakan.
5. Akuntabilitas Kegiatan inventarisasi peralatan penanggulangan bencana harus dilakukan secara terbuka dan dapat dipertanggungjawabkan secara etik dan hukum.
6');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6115, 'V. Penutup 5 BAB II PENYELENGGARAAN INVENTARISASI PERALATAN A. Tujuan Inventarisasi Peralatan Tujuan Inventarisasi peralatan untuk :
1. Memperoleh data dan informasi tentang jenis, jumlah, kondisi dan sebaran peralatan penanggulangan bencana yang tersedia pada pemerintah, pemerintah daerah, dunia usaha dan masyarakat.
2. Penyusunan rencana dan pelaksanaan penanggulangan bencana.
3. Penunjang pengawasan dan pengendalian.
4. Melakukan analisis kebutuhan peralatan penanggulangan bencana.
5. Laporan pertanggungjawaban.
B. Prinsip-prinsip Inventarisasi Peralatan Kegiatan inventarisasi peralatan penanggulangan bencana harus dilaksanakan sesuai dengan prinsip-prinsip:
1. Akurat Kegiatan inventarisasi peralatan penangulangan bencana harus menghasilkan data yang akurat baik jenis, jumlah, kondisi dan sebaran peralatan yang tersedia dan yang perlu disediakan di suatu wilayah.
2. Terkini Kegiatan inventarisasi peralatan penangulangan bencana harus menghasilkan data yang terbaru.
3. Berkelanjutan Kegiatan inventarisasi peralatan penangulangan bencana harus dilakukan secara berkala dan kontinyu.
4. Komprehensif Kegiatan inventarisasi peralatan penanggulangan bencana harus menghasilkan data yang lengkap tentang jenis, jumlah dan kondisi, peralatan yang tersedia dan perlu disediakan.
5. Akuntabilitas Kegiatan inventarisasi peralatan penanggulangan bencana harus dilakukan secara terbuka dan dapat dipertanggungjawabkan secara etik dan hukum.
6', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6116, 'perka-11-2011', 14, 'lampiran', 'Lampiran hal. 10', NULL, 10, '6. Koordinasi Kegiatan inventarisasi peralatan penanggulangan bencana harus didasarkan pada koordinasi yang baik dan saling mendukung antar lembaga/ instansi penanggulangan bencana.
7. Efektifitas dan efisiensi Kegiatan inventarisasi peralatan pananggulangan bencana dilaksanakan tepat guna dan hasil guna.
C. Kebijakan Dan Strategi
1. Kebijakan BNPB dan BPBD menyiapkan data dan informasi tentang peralatan penanggulangan bencana secara komprehensif, akurat, dan mutahir sebagai dasar untuk melakukan analisis kebutuhan peralatan penanggulangan bencana.
2. Strategi Strategi adalah suatu cara untuk melaksanakan inventarisasi peralatan penanggulangan bencana dalam mencapai sasaran dan tujuan yang ditetapkan oleh BNPB, antara lain :
a. Terencana
b. Terorganisir
c. Terkoordinasi
d. Terkontrol
e. Akuntabel D. Kelembagaan Pelaksana Inventarisasi Peralatan Pelaksana inventarisasi peralatan dilaksanakan mulai dari instansi/lembaga terkait tingkat pusat, provinsi, sampai kabupaten/kota.
1. Nasional/Pusat
a. BNPB mengkoordinir kegiatan inventarisasi peralatan instansi/lembaga terkait
b. BNPB menyiapkan segala dokumen dan administrasi yang bersifat pendataan (daftar pertanyaan, form dll)
c. BNPB mendapatkan data persediaan peralatan yang ada pada instansi / lembaga lain yang terkait.
d. BNPB membuat analisa terhadap hasil inventarisasi 7
e. BNPB membuat daftar kebutuhan berdasarkan hasil inventarisasi dari BPBD Provinsi
2. Provinsi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6116, '6. Koordinasi Kegiatan inventarisasi peralatan penanggulangan bencana harus didasarkan pada koordinasi yang baik dan saling mendukung antar lembaga/ instansi penanggulangan bencana.
7. Efektifitas dan efisiensi Kegiatan inventarisasi peralatan pananggulangan bencana dilaksanakan tepat guna dan hasil guna.
C. Kebijakan Dan Strategi
1. Kebijakan BNPB dan BPBD menyiapkan data dan informasi tentang peralatan penanggulangan bencana secara komprehensif, akurat, dan mutahir sebagai dasar untuk melakukan analisis kebutuhan peralatan penanggulangan bencana.
2. Strategi Strategi adalah suatu cara untuk melaksanakan inventarisasi peralatan penanggulangan bencana dalam mencapai sasaran dan tujuan yang ditetapkan oleh BNPB, antara lain :
a. Terencana
b. Terorganisir
c. Terkoordinasi
d. Terkontrol
e. Akuntabel D. Kelembagaan Pelaksana Inventarisasi Peralatan Pelaksana inventarisasi peralatan dilaksanakan mulai dari instansi/lembaga terkait tingkat pusat, provinsi, sampai kabupaten/kota.
1. Nasional/Pusat
a. BNPB mengkoordinir kegiatan inventarisasi peralatan instansi/lembaga terkait
b. BNPB menyiapkan segala dokumen dan administrasi yang bersifat pendataan (daftar pertanyaan, form dll)
c. BNPB mendapatkan data persediaan peralatan yang ada pada instansi / lembaga lain yang terkait.
d. BNPB membuat analisa terhadap hasil inventarisasi 7
e. BNPB membuat daftar kebutuhan berdasarkan hasil inventarisasi dari BPBD Provinsi
2. Provinsi', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6117, 'perka-11-2011', 15, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'a. BPBD mengkoordinir kegiatan inventarisasi peralatan di provinsi
b. BPBD menyiapkan segala dokumen dan administrasi yang bersifat pendataan
c. BPBD mengkoordinir untuk mendata persediaan peralatan yang ada pada instansi/lembaga lain yang terkait.
d. BPBD membuat analisa terhadap hasil inventarisasi
e. BPBD membuat daftar kebutuhan provinsi berdasarkan hasil inventarisasi
f. BPBD melaporkan hasil inventarisasi ke BNPB
3. Kabupaten/Kota
a. BPBD mengkoordinir kegiatan inventarisasi peralatan di kabupaten/ kota
b. BPBD menyiapkan segala dokumen dan administrasi yang bersifat pendataan
c. BPBD mengkoordinir untuk mendata persediaan peralatan yang ada pada instansi/lembaga lain yang terkait.
d. BPBD membuat analisa terhadap hasil inventarisasi
e. BPBD membuat daftar kebutuhan kabupaten/ kota berdasarkan hasil inventarisasi
f. BPBD melaporkan hasil inventarisasi ke BPBD Provinsi 8 BAB III MEKANISME PENYELENGGARAAN INVENTARISASI PERALATAN Penyelenggaraan inventarisasi peralatan dilaksanakan melalui prosedur persiapan, pelaksanaan dan pelaporan.
A. Persiapan
1. Menyiapkan daftar/form inventarisasi peralatan penanggulangan bencana sesuai dengan jenis peralatan.
2. Menyiapkan alat bantu inventarisasi yang dibutuhkan (camera, tape recorder, handycam, dll)
3. Menyiapkan sumber daya manusia (petugas) yang akan melakukan kegiatan inventarisasi peralatan penanggulangan bencana.
4. Menyiapkan surat tugas untuk tenaga pelaksana inventarisasi baik nasional maupun daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6117, 'a. BPBD mengkoordinir kegiatan inventarisasi peralatan di provinsi
b. BPBD menyiapkan segala dokumen dan administrasi yang bersifat pendataan
c. BPBD mengkoordinir untuk mendata persediaan peralatan yang ada pada instansi/lembaga lain yang terkait.
d. BPBD membuat analisa terhadap hasil inventarisasi
e. BPBD membuat daftar kebutuhan provinsi berdasarkan hasil inventarisasi
f. BPBD melaporkan hasil inventarisasi ke BNPB
3. Kabupaten/Kota
a. BPBD mengkoordinir kegiatan inventarisasi peralatan di kabupaten/ kota
b. BPBD menyiapkan segala dokumen dan administrasi yang bersifat pendataan
c. BPBD mengkoordinir untuk mendata persediaan peralatan yang ada pada instansi/lembaga lain yang terkait.
d. BPBD membuat analisa terhadap hasil inventarisasi
e. BPBD membuat daftar kebutuhan kabupaten/ kota berdasarkan hasil inventarisasi
f. BPBD melaporkan hasil inventarisasi ke BPBD Provinsi 8 BAB III MEKANISME PENYELENGGARAAN INVENTARISASI PERALATAN Penyelenggaraan inventarisasi peralatan dilaksanakan melalui prosedur persiapan, pelaksanaan dan pelaporan.
A. Persiapan
1. Menyiapkan daftar/form inventarisasi peralatan penanggulangan bencana sesuai dengan jenis peralatan.
2. Menyiapkan alat bantu inventarisasi yang dibutuhkan (camera, tape recorder, handycam, dll)
3. Menyiapkan sumber daya manusia (petugas) yang akan melakukan kegiatan inventarisasi peralatan penanggulangan bencana.
4. Menyiapkan surat tugas untuk tenaga pelaksana inventarisasi baik nasional maupun daerah.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6118, 'perka-11-2011', 16, 'lampiran', 'Lampiran hal. 12', NULL, 12, '5. Melakukan koordinasi dengan instansi/lembaga terkait untuk melakukan inventarisasi peralatan penanggulangan bencana.
B. Pelaksanaan
1. Mengadakan rapat koordinasi dengan instansi/lembaga terkait mengenai ketersediaan peralatan.
2. Melakukan pendataan dan/atau verifikasi data ketersediaan peralatan yang dimiliki instansi/lembaga terkait di Pusat dan Daerah.
3. Kementerian/ lembaga terkait memberikan data inventarisasi peralatan kepada BNPB/ BPBD
4. BNPB/ BPBD merekapitulasi data inventarisasi peralatan dari masing-masing kementerian/ lembaga terkait di Pusat dan daerah berdasarkan, jenis, jumlah dan kondisi peralatan.
5. BNPB/BPBD membuat laporan inventarisasi hasil pendataan peralatan secara periodik.
6. BNPB melakukan analisis terhadap terhadap laporan inventarisasi peralatan dari kementerian dan lembaga tekait dilakukan dengan cara:
a. Menghitung jenis, jumlah dan kondisi peralatan yang berada di suatu wilayah.
b. Membandingkan jumlah peralatan yang tersedia di suatu wilayah dengan standar minimal peralatan.
c. Menghitung dan menetapkan jenis dan jumlah peralatan yang dibutuhkan yang perlu disediakan di suatu wilayah untuk penanggulangan bencana.
9 C. Pelaporan Membuat laporan hasil inventarisasi peralatan penanggulangan bencana, yang memuat informasi tentang:
1. Jenis dan jumlah peralatan yang tersedia
2. Kondisi peralatan yang tersedia (berfungsi)
3. Jenis dan jumlah peralatan yang perlu disediakan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6118, '5. Melakukan koordinasi dengan instansi/lembaga terkait untuk melakukan inventarisasi peralatan penanggulangan bencana.
B. Pelaksanaan
1. Mengadakan rapat koordinasi dengan instansi/lembaga terkait mengenai ketersediaan peralatan.
2. Melakukan pendataan dan/atau verifikasi data ketersediaan peralatan yang dimiliki instansi/lembaga terkait di Pusat dan Daerah.
3. Kementerian/ lembaga terkait memberikan data inventarisasi peralatan kepada BNPB/ BPBD
4. BNPB/ BPBD merekapitulasi data inventarisasi peralatan dari masing-masing kementerian/ lembaga terkait di Pusat dan daerah berdasarkan, jenis, jumlah dan kondisi peralatan.
5. BNPB/BPBD membuat laporan inventarisasi hasil pendataan peralatan secara periodik.
6. BNPB melakukan analisis terhadap terhadap laporan inventarisasi peralatan dari kementerian dan lembaga tekait dilakukan dengan cara:
a. Menghitung jenis, jumlah dan kondisi peralatan yang berada di suatu wilayah.
b. Membandingkan jumlah peralatan yang tersedia di suatu wilayah dengan standar minimal peralatan.
c. Menghitung dan menetapkan jenis dan jumlah peralatan yang dibutuhkan yang perlu disediakan di suatu wilayah untuk penanggulangan bencana.
9 C. Pelaporan Membuat laporan hasil inventarisasi peralatan penanggulangan bencana, yang memuat informasi tentang:
1. Jenis dan jumlah peralatan yang tersedia
2. Kondisi peralatan yang tersedia (berfungsi)
3. Jenis dan jumlah peralatan yang perlu disediakan', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6119, 'perka-11-2011', 17, 'lampiran', 'Lampiran hal. 13', NULL, 13, '4. Penyedia sumber peralatan (kementerian/ lembaga terkait pemangku kepentingan) 10 BAB IV PEMANTAUAN DAN EVALUASI A. Pemantauan.
Pemantauan pelaksanaan inventarisasi peralatan penanggulangan bencana dimaksudkan agar kegiatan dapat terlaksana sesuai dengan rencana yang ditetapkan:
1. Pemantauan dilakukan oleh pimpinan unit kerja yang menyelenggarakan kegiatan inventarisasi peralatan penanggulangan bencana
2. Pemantauan dilaksanakan dengan cara monitoring dan supervisi
a. monitoring dilakukan agar inventarisasi peralatan dilaksanakan dengan ketentuan dan prosedur yang telah ditetapkan
b. supervisi dilakukan untuk memberikan dukungan kepada petugas inventarisasi sehingga pelaksanaan inventariasi peralatan tidak mengalami kesulitan dan hambatan.
3. Aspek-aspek yang dipantau adalah : (1) proses pelaksanaan inventarisasi peralatan, (2) kinerja petugas inventarisasi peralatan (3) hambatan dan kendala dalam melaksanakan inventarisasi peralatan dan (4) hasil inventarisasi peralatan.
4. Pemantauan dilaksanakan terhadap seluruh tahapan kegiatan inventarisasi peralatan penanggulangan bencana.
5. Mengumpulkan laporan secara tertulis hasil pelaksanaan tugas untuk evaluasi selanjutnya B. Evaluasi Evaluasi inventarisasi peralatan penanggulangan bencana dilakukan untuk mengetahui hasil dan hambatan dalam melakukan kegiatan inventarisasi peralatan penanggulangan bencana. Hal-hal yang dievaluasi meliputi:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6119, '4. Penyedia sumber peralatan (kementerian/ lembaga terkait pemangku kepentingan) 10 BAB IV PEMANTAUAN DAN EVALUASI A. Pemantauan.
Pemantauan pelaksanaan inventarisasi peralatan penanggulangan bencana dimaksudkan agar kegiatan dapat terlaksana sesuai dengan rencana yang ditetapkan:
1. Pemantauan dilakukan oleh pimpinan unit kerja yang menyelenggarakan kegiatan inventarisasi peralatan penanggulangan bencana
2. Pemantauan dilaksanakan dengan cara monitoring dan supervisi
a. monitoring dilakukan agar inventarisasi peralatan dilaksanakan dengan ketentuan dan prosedur yang telah ditetapkan
b. supervisi dilakukan untuk memberikan dukungan kepada petugas inventarisasi sehingga pelaksanaan inventariasi peralatan tidak mengalami kesulitan dan hambatan.
3. Aspek-aspek yang dipantau adalah : (1) proses pelaksanaan inventarisasi peralatan, (2) kinerja petugas inventarisasi peralatan (3) hambatan dan kendala dalam melaksanakan inventarisasi peralatan dan (4) hasil inventarisasi peralatan.
4. Pemantauan dilaksanakan terhadap seluruh tahapan kegiatan inventarisasi peralatan penanggulangan bencana.
5. Mengumpulkan laporan secara tertulis hasil pelaksanaan tugas untuk evaluasi selanjutnya B. Evaluasi Evaluasi inventarisasi peralatan penanggulangan bencana dilakukan untuk mengetahui hasil dan hambatan dalam melakukan kegiatan inventarisasi peralatan penanggulangan bencana. Hal-hal yang dievaluasi meliputi:', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2011 tentang Pedoman Inventarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6120, 'perka-11-2011', 18, 'lampiran', 'Lampiran hal. 14', NULL, 14, '1. Evaluasi dilakukan oleh pimpinan unit kerja yang meyelenggarakan kegiatan inventarisasi peralatan penanggulangan bencana.
2. Evaluasi dilakukan dengan cara mempelajari laporan tertulis, dialog, dan presentasi
3. Aspek yang dievaluasi adalah :
a. penyelenggara kegiatan inventarisasi peralatan penanggulangan bencana, meliputi tahapan persiapan, pelaksanaan dan pelaporan
b. hasil kegiatan inventarisasi peralatan penanggulangan bencana meliputi keakuratan, kelengkapan dan kekinian data peralatan 11
c. kebutuhan peralatan di suatu wilayah yang perlu disediakan untuk menghadapi penanggulangan bencana.
4. Evaluasi dilakukan pada akhir kegiatan inventarisasi peralatan penanggulangan bencana 12 BAB V PENUTUP Pedoman Inventarisasi Peralatan Penanggulangan Bencana ini dimaksudkan sebagai petunjuk praktis untuk dipergunakan oleh semua pihak dalam melaksanakan upaya pelaksanaan inventarisasi peralatan penanggulangan bencana. Dengan demikian diharapkan kegiatan inventarisasi peralatan penanggulangan bencana dapat berjalan secara efektif, efisien, dan terkoordinasi dengan baik.
Sesuai dengan perkembangan, pedoman ini terbuka untuk diperbaiki.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, R. SYAMSUL MAARIF, M.Si.
