INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6124, 'perka-11-2014', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2014 tentang Peran Serta Masyarakat Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6124, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2014 tentang Peran Serta Masyarakat Dalam Penyelenggaraan Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2014 tentang Peran Serta Masyarakat Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6125, 'perka-11-2014', 1, 'menimbang', 'Menimbang', NULL, 2, 'a. bahwa dalam pelaksanaan Pasal 26 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, Pasal 2 Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana dan Pasal 4 Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana, tentang Peran serta Masyarakat dalam Penanggulangan Bencana,
b. bahwa peran serta masyarakat dalam penanggulangan bencana merupakan perwujudan hak dan kewajiban masyarakat mendapat perlindungan dan kehidupan sosial yang harmonis, rasa aman, pendidikan, pelatihan dan keterampilan, informasi, pengambilan keputusan berkaitan dengan diri dan komunitasnya, melakukan pengawasan sesuai dengan mekanisme yang diatur dalam pelaksanaan penanggulangan bencana, memberikan informasi yang benar kepada publik serta melakukan kegiatan penanggulangan bencana yang bertujuan untuk menjamin terselenggaranya pelaksanaan penanggulangan bencana secara terencana, terpadu, terkoordinasi, dan menyeluruh dalam rangka memberikan perlindungan kepada masyarakat dari ancaman risiko dan dampak bencana,
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b dan huruf c perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Peran Serta Masyarakat dalam Penyelenggaraan Penanggulangan Bencana, BADAN NASIONAL PENANGGULANGAN BENCANA PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA | NOMOR 11 TAHUN 2014 | TENTANG PERAN SERTA MASYARAKAT DALAM | PENYELENGGARAAN PENANGGULANGAN BENCANA | DENGAN RAHMAT TUHAN YANG MAHA ESA KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, Menimbang
a. bahwa dalam pelaksanaan Pasal 26 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, Pasal 2 Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana dan Pasal 4 Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana, tentang Peran serta Masyarakat dalam Penanggulangan Bencana,
