INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6126, 'perka-11-2014', 2, 'mengingat', 'Mengingat', NULL, 3, '-
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 1828),
3. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829),
4. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana,
5. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2013 tentang Pedoman Pengelolaan Informasi dan Dokumentasi di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2013 Nomor 1485):
6. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 557),');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6126, '-
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 1828),
3. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829),
4. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana,
5. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2013 tentang Pedoman Pengelolaan Informasi dan Dokumentasi di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2013 Nomor 1485):
6. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 557),', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2014 tentang Peran Serta Masyarakat Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6127, 'perka-11-2014', 3, 'menetapkan', 'Menetapkan', NULL, 4, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PERAN SERTA ORGANISASI KEMASYARAKATAN DALAM PENYELENGGARAAN PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6127, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PERAN SERTA ORGANISASI KEMASYARAKATAN DALAM PENYELENGGARAAN PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 11 Tahun 2014 tentang Peran Serta Masyarakat Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6128, 'perka-11-2014', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM; Bagian Kesatu Ketangguhan Masyarakat', 4, 'Dalam Peraturan Kepala ini yang dimaksud dengan :
1. Peran Serta Masyarakat adalah proses keterlibatan masyarakat dalam perselenggaraan pelaksanaan penanggulangan bencana secara terencana, terpadu, terkoordinasi, dan menyeluruh dalam rangka memberikan perlindungan kepada masyarakat dari ancaman risiko.
Dan dampak bencana:
2. Manusia adalah makhluk sosial, memiliki kecenderungan yang kuat untuk berkumpul, membentuk masyarakat dan berorganisasi.
10. 1, Masyarakat adalah sekelompok orang yang membentuk sebuah sistem semi tertutup atau semi terbuka, dimana sebagian besar interaksi adalah antara individu-individu yang berada dalam kelompok tersebut.
Masyarakat adalah sebuah komunitas yang saling tergantung satu sama lain hidup bersama dalam satu komunitas yang teratur dan Masyarakat yang berstruktur atau organisasi masyarakat didirikan dan dibentuk oleh masyarakat secara sukarela berdasarkan kesamaan aspirasi, kehendak, kebutuhan, kepentingan, kegiatan, dan tujuan untuk berpartisipasi dalam pembangunan demi tercapainya tujuan Negara Kesatuan Republik Indonesia yang berdasarkan Pancasila, Perkumpulan adalah masyarakat yang lebih dari satu orang secara bersama melaksanakan penanggulangan bencana dibentuk oleh masyarakat, baik berbadan hukum maupun yang tidak berbadan hukum.
Klaster adalah model atau bentuk koordinasi dengan cara mengelompokkan para pelaku penanggulangan bencana dalam penanganan darurat bencana, berdasarkan gugus tugas.
Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
Pencegahan bencana adalah serangkaian kegiatan yang dilakukan sebelum terjadi bencana untuk mengurangi atau menghilangkan risiko bencana, baik melalui pengurangan ancaman bencana maupun kerentanan pihak yang terancam bencana.
Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, penyelamatan, serta pemulihan prasarana dan sarana.
Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pascabencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.
Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta masyarakat dalam segala aspek kehidupan bermasyarakat pada wilayah pascabencana.
12. Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan Pemerintahan Negara Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
13. Pemerintah Daerah adalah gubernur, bupati/walikota atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
14. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB, adalah lembaga pemerintah non-kementerian sesuai dengan ketentuan peraturan perundang-undangan.
15. Badan Penanggulangan Bencana Daerah, yang selanjutnya disingkat BPBD, adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6128, 'Dalam Peraturan Kepala ini yang dimaksud dengan :
1. Peran Serta Masyarakat adalah proses keterlibatan masyarakat dalam perselenggaraan pelaksanaan penanggulangan bencana secara terencana, terpadu, terkoordinasi, dan menyeluruh dalam rangka memberikan perlindungan kepada masyarakat dari ancaman risiko.
Dan dampak bencana:
2. Manusia adalah makhluk sosial, memiliki kecenderungan yang kuat untuk berkumpul, membentuk masyarakat dan berorganisasi.
10. 1, Masyarakat adalah sekelompok orang yang membentuk sebuah sistem semi tertutup atau semi terbuka, dimana sebagian besar interaksi adalah antara individu-individu yang berada dalam kelompok tersebut.
