INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6198, 'perka-12-2008', 22, 'lampiran', 'Lampiran hal. 18', NULL, 18, 'KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF 19 2014, No.1410 LAMPIRAN I PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 12 TAHUN 2008 TENTANG PEDOMAN KAJIAN PEMBENTUKAN DAN PENYELENGGARAAN UNIT PELAKSANA TEKNIS PETA RENCANA LOKASI UNIT PELAKSANA TEKNIS 2014, No.1410 20 LAMPIRAN II PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 12 TAHUN 2008 TENTANG PEDOMAN KAJIAN PEMBENTUKAN DAN PENYELENGGARAAN UNIT PELAKSANA TEKNIS PUSAT BANTUAN BENCANA INSTANSI LAIN A. DEPARTEMEN KESEHATAN
1. Pusat Penanggulangan Krisis (PPK) Kesehatan
2. Ada 9 Regional PPK Kesehatan, dengan wilayah pelayanan:
a. Medan: Sumut, Aceh, Riau, Kepri, Sumbar
b. Palembang: Sumsel, Jambi, Babel, Bengkulu
c. Jakarta: DKI, Banten, Jabar, Lampung, Kalbar
d. Semarang: Jateng, DIY
e. Surabaya: Jatim
f. Banjarmasin: Kalsel, Kalteng, Kaltim
g. Denpasar: Bali, NTB, NTT
h. Manado: Sulut, Gorontalo, Maluku Utara
i. Makassar: Sulsel, Sulteng, Sulbar, Sul-Tenggara, Maluku, Papua B. DEPARTEMEN SOSIAL
1. BSKBA Bantuan Sosial Korban Bencana Alam
2. Dinas Sosial di 33 Provinsi: Tagana, Depo Logistik (buffer stock) C. BADAN SAR NASIONAL
1. 24 UPT Basarnas, regionalisasi wilayah kerja');
