INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6199, 'perka-12-2008', 23, 'lampiran', 'Lampiran hal. 20', NULL, 20, '2. 48 UNIT Pos SAR 21 2014, No.1410 LAMPIRAN III PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 12 TAHUN 2008 TENTANG PEDOMAN KAJIAN PEMBENTUKAN DAN PENYELENGGARAAN UNIT PELAKSANA TEKNIS HASIL UJI PETIK KETIGA LOKASI CALON UPT Dalam rangka mendapatkan masukan dari daerah terhadap pembentukan UPT, dilakukan uji petik di tiga lokasi, yaitu Medan, Palembang dan Kupang. Uji Petik dilaksanakan dalam bentuk Focus Group Diskusi bersama-sama Pemerintah Provinsi, Badan Kesatuan Bangsa dan Perlindungan Masyarakat, Dinas Sosial, Dinas Pekerjaan Umum, TNI dan POLRI, PMI dan Badan SAR daerah.
Pada dasarnya di ketiga lokasi tersebut, pembentukan UPT disepakati dan disetujui oleh FGD, dengan alasan sebagai berikut :
1. Bahwa lokasi UPT (Medan, Kupang dan Palembang) aman terhadap bencana.
2. Bahwa kota-kota UPT tersebut memiliki aksesibilitas transportasi udara, laut dan darat yang mendukung kelancaran penanggulangan bencana.
3. Bahwa cakupan wilayah UPT Medan memperhatikan wilayah teritorial TNI/Kodam-I Bukit Barisan dan wilayah teritorial TNI/Kodam Iskandarmuda (untuk UPT Regional di Medan).
4. Bahwa Provinsi NTT merupakan daerah kepulauan urutan nomor lima di Indonesia yang rawan bencana, baik alam maupun sosial, yang merupakan dasar diperlukannya pembentukan UPT Regional Kupang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6199, '2. 48 UNIT Pos SAR 21 2014, No.1410 LAMPIRAN III PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 12 TAHUN 2008 TENTANG PEDOMAN KAJIAN PEMBENTUKAN DAN PENYELENGGARAAN UNIT PELAKSANA TEKNIS HASIL UJI PETIK KETIGA LOKASI CALON UPT Dalam rangka mendapatkan masukan dari daerah terhadap pembentukan UPT, dilakukan uji petik di tiga lokasi, yaitu Medan, Palembang dan Kupang. Uji Petik dilaksanakan dalam bentuk Focus Group Diskusi bersama-sama Pemerintah Provinsi, Badan Kesatuan Bangsa dan Perlindungan Masyarakat, Dinas Sosial, Dinas Pekerjaan Umum, TNI dan POLRI, PMI dan Badan SAR daerah.
Pada dasarnya di ketiga lokasi tersebut, pembentukan UPT disepakati dan disetujui oleh FGD, dengan alasan sebagai berikut :
