INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6211, 'perka-12-2010', 9, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 12 TAHUN 2010 TANGGAL : 14 SEPTEMBER 2010 BAB I PENDAHULUAN A. Latar Belakang.
Indonesia yang memiliki kondisi geografis, geologis, hidrologis dan demografis yang memungkinkan terjadinya bencana baik yang disebabkan oleh faktor alam, non alam maupun faktor manusia sehingga menyebabkan timbulnya korban manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis yang dalam keadaan tertentu kemungkinan dapat menghambat pembangunan nasional dan pengembangan potensi sumberdayanya untuk meningkatkan kesejahteraan.
Korban manusia, kerusakan lingkungan, kerugian harta benda dan dampak lain yang timbul harus dapat diminimalisir dengan berbagai cara mulai dari pencegahan, penanganan dan penanggulangan bencana. Dalam penanganan bencana salah satunya adalah dengan memberikan bantuan perbaikan darurat bencana yaitu upaya untuk pemulihan dengan segera prasarana dan sarana vital dengan memperbaiki dan/atau mengganti kerusakan akibat bencana sehingga kehidupan masyarakat tetap berlangsung.
Hasil yang diharapkan dalam pemberian bantuan perbaikan darurat adalah berfungsinya kembali secara minimal prasarana dan sarana yaitu fasilitas umum, ekonomi, dan sosial seperti jalan, jembatan, dermaga, irigasi, utilitas air minum, listrik, gas, dan jaringan komunikasi untuk menggerakkan kembali kehidupan ekonomi masyarakat baik pada saat bencana maupun setelah terjadinya bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6211, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 12 TAHUN 2010 TANGGAL : 14 SEPTEMBER 2010 BAB I PENDAHULUAN A. Latar Belakang.
Indonesia yang memiliki kondisi geografis, geologis, hidrologis dan demografis yang memungkinkan terjadinya bencana baik yang disebabkan oleh faktor alam, non alam maupun faktor manusia sehingga menyebabkan timbulnya korban manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis yang dalam keadaan tertentu kemungkinan dapat menghambat pembangunan nasional dan pengembangan potensi sumberdayanya untuk meningkatkan kesejahteraan.
Korban manusia, kerusakan lingkungan, kerugian harta benda dan dampak lain yang timbul harus dapat diminimalisir dengan berbagai cara mulai dari pencegahan, penanganan dan penanggulangan bencana. Dalam penanganan bencana salah satunya adalah dengan memberikan bantuan perbaikan darurat bencana yaitu upaya untuk pemulihan dengan segera prasarana dan sarana vital dengan memperbaiki dan/atau mengganti kerusakan akibat bencana sehingga kehidupan masyarakat tetap berlangsung.
Hasil yang diharapkan dalam pemberian bantuan perbaikan darurat adalah berfungsinya kembali secara minimal prasarana dan sarana yaitu fasilitas umum, ekonomi, dan sosial seperti jalan, jembatan, dermaga, irigasi, utilitas air minum, listrik, gas, dan jaringan komunikasi untuk menggerakkan kembali kehidupan ekonomi masyarakat baik pada saat bencana maupun setelah terjadinya bencana.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6212, 'perka-12-2010', 10, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'Pemulihan dengan segera prasarana dan sarana vital tersebut dilakukan oleh instansi/lembaga terkait yang dikoordinasikan oleh Kepala BNPB dan atau/kepala BPBD sesuai amanat Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Penanggulangan Bencana dan Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, Kepala BNPB mempunyai tugas memberikan bantuan bagi penanggulangan bencana. Salah satu bentuk tugas dari Kepala BNPB adalah menyusun Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat.
B. Maksud dan Tujuan
1. Maksud Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat ini disusun untuk memberikan acuan pelaksanaan pemberian bantuan perbaikan darurat.
2. Tujuan Tujuan dari pedoman ini adalah terlaksananya pemberian bantuan perbaikan darurat yang cepat, tepat, dan dapat dipertanggung jawabkan.
C. Landasan Hukum
1. Undang-Undang Dasar 1945, Pembukaan UUD 1945.
2. Undang-Undang Nomor 32 Tahun 2004, tentang Pemerintahan Daerah.
3. Undang-Undang Nomor 24 Tahun 2007, tentang Penanggulangan Bencana.
4. Peraturan Presiden, Nomor 8 Tahun 2008, tentang Badan Nasional Penanggulangan Bencana.
5. Peraturan Pemerintah Nomor 21 Tahun 2008, tentang Penyelenggaraan Penanggulangan Bencana.
6. Peraturan Pemerintah Nomor 22 Tahun 2008, tentang Pendanaan dan Pengelolaan Bantuan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6212, 'Pemulihan dengan segera prasarana dan sarana vital tersebut dilakukan oleh instansi/lembaga terkait yang dikoordinasikan oleh Kepala BNPB dan atau/kepala BPBD sesuai amanat Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Penanggulangan Bencana dan Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, Kepala BNPB mempunyai tugas memberikan bantuan bagi penanggulangan bencana. Salah satu bentuk tugas dari Kepala BNPB adalah menyusun Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat.
B. Maksud dan Tujuan
1. Maksud Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat ini disusun untuk memberikan acuan pelaksanaan pemberian bantuan perbaikan darurat.
2. Tujuan Tujuan dari pedoman ini adalah terlaksananya pemberian bantuan perbaikan darurat yang cepat, tepat, dan dapat dipertanggung jawabkan.
C. Landasan Hukum
1. Undang-Undang Dasar 1945, Pembukaan UUD 1945.
2. Undang-Undang Nomor 32 Tahun 2004, tentang Pemerintahan Daerah.
3. Undang-Undang Nomor 24 Tahun 2007, tentang Penanggulangan Bencana.
4. Peraturan Presiden, Nomor 8 Tahun 2008, tentang Badan Nasional Penanggulangan Bencana.
5. Peraturan Pemerintah Nomor 21 Tahun 2008, tentang Penyelenggaraan Penanggulangan Bencana.
6. Peraturan Pemerintah Nomor 22 Tahun 2008, tentang Pendanaan dan Pengelolaan Bantuan Bencana.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6213, 'perka-12-2010', 11, 'lampiran', 'Lampiran hal. 4', NULL, 4, '7. Peraturan Pemerintah Nomor 23 Tahun 2008, tentang Peran Serta lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana.
8. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008, tentang Pedoman Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah.
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008, tentang Pedoman Pembentukan Badan Penanggulangan Bencana Daerah.
10. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008, tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana.
11. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008, tentang Pedoman Penggunaan Dana Siap Pakai.
12. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2008, tentang Pedoman Tata Cara Pemberian Bantuan Kebutuhan Dasar.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Keadaan Darurat Bencana dimulai sejak status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.
3. Tanggap Darurat Bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6213, '7. Peraturan Pemerintah Nomor 23 Tahun 2008, tentang Peran Serta lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana.
8. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008, tentang Pedoman Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah.
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008, tentang Pedoman Pembentukan Badan Penanggulangan Bencana Daerah.
10. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008, tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana.
11. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008, tentang Pedoman Penggunaan Dana Siap Pakai.
12. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2008, tentang Pedoman Tata Cara Pemberian Bantuan Kebutuhan Dasar.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Keadaan Darurat Bencana dimulai sejak status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.
3. Tanggap Darurat Bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6214, 'perka-12-2010', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, '4. Sistem Komando Darurat Bencana disingkat SKD adalah suatu standar sistem penanganan darurat bencana yang digunakan oleh semua instansi/lembaga dengan mengintegrasikan pengerahan fasilitas, peralatan, personil, prosedur dan komunikasi dalam suatu struktur organisasi berdasarkan satu komando yang digunakan oleh BNPB/BPBD untuk mengerahkan sumberdaya dari Instansi/Lembaga, lembaga usaha dan masyarakat untuk mencapai penanganan darurat bencana yang efektif.
5. Komando Darurat Bencana adalah organisasi penanganan keadaan darurat bencana yang dipimpin oleh seorang Komandan Darurat Bencana dan dibantu oleh Staf Komando dan Staf Umum, memiliki struktur organisasi standar yang menganut satu komando dengan mata rantai dan garis komando yang jelas dan memiliki satu kesatuan komando dalam mengkoordinasikan Instansi/ Lembaga/ organisasi terkait untuk pengerahan sumberdaya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6214, '4. Sistem Komando Darurat Bencana disingkat SKD adalah suatu standar sistem penanganan darurat bencana yang digunakan oleh semua instansi/lembaga dengan mengintegrasikan pengerahan fasilitas, peralatan, personil, prosedur dan komunikasi dalam suatu struktur organisasi berdasarkan satu komando yang digunakan oleh BNPB/BPBD untuk mengerahkan sumberdaya dari Instansi/Lembaga, lembaga usaha dan masyarakat untuk mencapai penanganan darurat bencana yang efektif.
5. Komando Darurat Bencana adalah organisasi penanganan keadaan darurat bencana yang dipimpin oleh seorang Komandan Darurat Bencana dan dibantu oleh Staf Komando dan Staf Umum, memiliki struktur organisasi standar yang menganut satu komando dengan mata rantai dan garis komando yang jelas dan memiliki satu kesatuan komando dalam mengkoordinasikan Instansi/ Lembaga/ organisasi terkait untuk pengerahan sumberdaya.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6215, 'perka-12-2010', 13, 'lampiran', 'Lampiran hal. 5', NULL, 5, '6. Tim Kaji Cepat disingkat TKC adalah suatu tim yang dibentuk oleh Kepala BNPB/BPBD terdiri dari Instansi/Lembaga teknis/non teknis terkait yang bertugas melaksanakan kaji cepat bencana, meliputi identifikasi cakupan lokasi bencana, jumlah korban bencana, kerusakan sarana dan prasarana, gangguan terhadap fungsi pelayanan umum dan pemerintahan, serta kemampuan sumberdaya alam maupun buatan, dan dampak bencana pada saat tanggap darurat bencana meliputi penilaian kebutuhan (need assesment), penilaian kerusakan dan kerugian (damage and losses assesment) serta memberikan dukungan pendampingan dalam penanganan darurat bencana.
7. Pemulihan dengan segera Prasarana dan Sarana Vital adalah seperti misalnya pembersihan puing-puing, sampah, lumpur dan bahan-bahan yang rusak dan berbahaya serta perbaikan sarana darurat antara lain, instalasi air, jaringan listrik, telekomunikasi dan jaringan irigasi.
8. Bantuan Perbaikan Darurat adalah bantuan kemanusiaan yang terdiri atas bantuan perbaikan darurat untuk pembersihan puing-puing, sampah, lumpur dan bahan-bahan berbahaya serta perbaikan prasarana dan sarana darurat berupa infrastruktur seperti jalan, jembatan, bandara, pelabuhan, rumah sakit, sekolah dan infrastuktur pelayanan lain seperti: jaringan air bersih dan sanitasi, listrik dan/atau gas, dan jaringan komunikasi dan sebagainya.yang berfungsi sebagai fasilitas untuk memperlancar arus lalulintas manusia dan barang sehingga sektor-sektor dasar kehidupan tetap dapat berjalan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6215, '6. Tim Kaji Cepat disingkat TKC adalah suatu tim yang dibentuk oleh Kepala BNPB/BPBD terdiri dari Instansi/Lembaga teknis/non teknis terkait yang bertugas melaksanakan kaji cepat bencana, meliputi identifikasi cakupan lokasi bencana, jumlah korban bencana, kerusakan sarana dan prasarana, gangguan terhadap fungsi pelayanan umum dan pemerintahan, serta kemampuan sumberdaya alam maupun buatan, dan dampak bencana pada saat tanggap darurat bencana meliputi penilaian kebutuhan (need assesment), penilaian kerusakan dan kerugian (damage and losses assesment) serta memberikan dukungan pendampingan dalam penanganan darurat bencana.
7. Pemulihan dengan segera Prasarana dan Sarana Vital adalah seperti misalnya pembersihan puing-puing, sampah, lumpur dan bahan-bahan yang rusak dan berbahaya serta perbaikan sarana darurat antara lain, instalasi air, jaringan listrik, telekomunikasi dan jaringan irigasi.
8. Bantuan Perbaikan Darurat adalah bantuan kemanusiaan yang terdiri atas bantuan perbaikan darurat untuk pembersihan puing-puing, sampah, lumpur dan bahan-bahan berbahaya serta perbaikan prasarana dan sarana darurat berupa infrastruktur seperti jalan, jembatan, bandara, pelabuhan, rumah sakit, sekolah dan infrastuktur pelayanan lain seperti: jaringan air bersih dan sanitasi, listrik dan/atau gas, dan jaringan komunikasi dan sebagainya.yang berfungsi sebagai fasilitas untuk memperlancar arus lalulintas manusia dan barang sehingga sektor-sektor dasar kehidupan tetap dapat berjalan.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6216, 'perka-12-2010', 14, 'lampiran', 'Lampiran hal. 6', NULL, 6, '9. Prasarana Umum adalah semua fasilitas umum yang dapat membantu kelancaran kehidupan masyarakat sehari-hari berupa infrastruktur jalan, jembatan, bandara, pelabuhan, rumah sakit, pasar, sekolah dan infrastuktur lain yang berfungsi sebagai fasilitas untuk memperlancar arus lalulintas manusia dan barang sehingga sektor-sektor dasar kehidupan tetap dapat berjalan.
10. Sarana Umum (Utilitas), dalah semua sarana vital yang dapat membantu kehidupan manusia dalam rangka meningkatkan kualitas kehidupan manusia sehari-hari berupa sarana mekanikal & elektrikal seperti pelayanan: jaringan air bersih, listrik, atau gas, dan jaringan komunikasi dan sebagainya.
E. Ruang Lingkup Ruang lingkup pedoman ini meliputi batasan dan pengertian bantuan perbaikan darurat, mekanisme pemberian bantuan perbaikan darurat serta pertanggungjawabannya dengan sistematika sebagai berikut:
BAB I Pendahuluan BAB II Bantuan Perbaikan Darurat BAB III Mekanisme Pemberian Bantuan Perbaikan Darurat BAB IV Pemantauan, Pengawasan Evaluasi dan Pelaporan BAB V Penutup BAB II BANTUAN PERBAIKAN DARURAT A. Kategori Bantuan perbaikan darurat prasarana dan sarana vital dikategorikan menjadi:
1. Perbaikan Fasilitas Umum Perbaikan fasilitas umum meliputi perbaikan darurat sarana dan prasarana yang bersifat umum yang dapat dimanfaatkan oleh masyarakat luas seperti : jaringan jalan, jembatan, irigasi, bandara, dermaga, dan sarana prasarana sosial budaya masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6216, '9. Prasarana Umum adalah semua fasilitas umum yang dapat membantu kelancaran kehidupan masyarakat sehari-hari berupa infrastruktur jalan, jembatan, bandara, pelabuhan, rumah sakit, pasar, sekolah dan infrastuktur lain yang berfungsi sebagai fasilitas untuk memperlancar arus lalulintas manusia dan barang sehingga sektor-sektor dasar kehidupan tetap dapat berjalan.
10. Sarana Umum (Utilitas), dalah semua sarana vital yang dapat membantu kehidupan manusia dalam rangka meningkatkan kualitas kehidupan manusia sehari-hari berupa sarana mekanikal & elektrikal seperti pelayanan: jaringan air bersih, listrik, atau gas, dan jaringan komunikasi dan sebagainya.
E. Ruang Lingkup Ruang lingkup pedoman ini meliputi batasan dan pengertian bantuan perbaikan darurat, mekanisme pemberian bantuan perbaikan darurat serta pertanggungjawabannya dengan sistematika sebagai berikut:
BAB I Pendahuluan BAB II Bantuan Perbaikan Darurat BAB III Mekanisme Pemberian Bantuan Perbaikan Darurat BAB IV Pemantauan, Pengawasan Evaluasi dan Pelaporan BAB V Penutup BAB II BANTUAN PERBAIKAN DARURAT A. Kategori Bantuan perbaikan darurat prasarana dan sarana vital dikategorikan menjadi:
1. Perbaikan Fasilitas Umum Perbaikan fasilitas umum meliputi perbaikan darurat sarana dan prasarana yang bersifat umum yang dapat dimanfaatkan oleh masyarakat luas seperti : jaringan jalan, jembatan, irigasi, bandara, dermaga, dan sarana prasarana sosial budaya masyarakat.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6217, 'perka-12-2010', 15, 'lampiran', 'Lampiran hal. 8', NULL, 8, '2. Perbaikan Utilitas Perbaikan utilitas yaitu perbaikan sarana dan prasarana pendukung agar dapat berfungsi kembali, yang meliputi utilitas :
a. Komunikasi
b. Listrik
c. Air Bersih
d. Air Minum
e. Gas
f. Limbah/ Sanitasi Perbaikan prasarana dan sarana umum didasarkan kepada perencanaan teknis dengan memperhatikan masukan mengenai kegiatan dari instansi/lembaga terkait, tim kaji cepat BNPB dan aspirasi kebutuhan masyarakat.
B. Jenis Bantuan Jenis bantuan perbaikan darurat terdiri dari :
1. Pembersihan Lokasi Yang dimaksud dengan pembersihan lokasi adalah upaya yang dilakukan untuk membersihkan suatu lokasi dari lumpur, sampah, puing, dan bahan-bahan berbahaya yang ditimbulkan akibat kejadian bencana.
2. Perbaikan Sarana Prasarana Yang dimaksud dengan perbaikan fasilitas umum adalah upaya yang dilakukan untuk memperbaiki fasilitas sarana prasarana umum hingga tahap dapat berfungsi kembali. Perbaikan fasilitas umum meliputi :
a. Perbaikan Jalan
b. Perbaikan Jembatan
c. Perbaikan Tanggul
d. Perbaikan Dermaga
3. Perbaikan Darurat Utilitas Sesuai dengan Peraturan Pemerintah Nomor 21/2008 pasal 26 ayat (1) dan pasal 54 ayat (1), bahwa pengerahan sumberdaya manusia, peralatan dan logistik dilakukan untuk menyelamatkan dan mengevakuasi korban bencana, memenuhi kebutuhan dasar dan memulihkan prasarana dan sarana vital. Pemulihan prasarana dan sarana vital bertujuan untuk berfungsinya prasarana dan sarana vital dengan segera, agar kehidupan masyarakat tetap berlangsung.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6217, '2. Perbaikan Utilitas Perbaikan utilitas yaitu perbaikan sarana dan prasarana pendukung agar dapat berfungsi kembali, yang meliputi utilitas :
a. Komunikasi
b. Listrik
c. Air Bersih
d. Air Minum
e. Gas
f. Limbah/ Sanitasi Perbaikan prasarana dan sarana umum didasarkan kepada perencanaan teknis dengan memperhatikan masukan mengenai kegiatan dari instansi/lembaga terkait, tim kaji cepat BNPB dan aspirasi kebutuhan masyarakat.
B. Jenis Bantuan Jenis bantuan perbaikan darurat terdiri dari :
1. Pembersihan Lokasi Yang dimaksud dengan pembersihan lokasi adalah upaya yang dilakukan untuk membersihkan suatu lokasi dari lumpur, sampah, puing, dan bahan-bahan berbahaya yang ditimbulkan akibat kejadian bencana.
2. Perbaikan Sarana Prasarana Yang dimaksud dengan perbaikan fasilitas umum adalah upaya yang dilakukan untuk memperbaiki fasilitas sarana prasarana umum hingga tahap dapat berfungsi kembali. Perbaikan fasilitas umum meliputi :
a. Perbaikan Jalan
b. Perbaikan Jembatan
c. Perbaikan Tanggul
d. Perbaikan Dermaga
3. Perbaikan Darurat Utilitas Sesuai dengan Peraturan Pemerintah Nomor 21/2008 pasal 26 ayat (1) dan pasal 54 ayat (1), bahwa pengerahan sumberdaya manusia, peralatan dan logistik dilakukan untuk menyelamatkan dan mengevakuasi korban bencana, memenuhi kebutuhan dasar dan memulihkan prasarana dan sarana vital. Pemulihan prasarana dan sarana vital bertujuan untuk berfungsinya prasarana dan sarana vital dengan segera, agar kehidupan masyarakat tetap berlangsung.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6218, 'perka-12-2010', 16, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'Bantuan untuk perbaikan lingkungan daerah bencana dimaksudkan untuk mengembalikan kondisi lingkungan yang dapat mendukung kehidupan masyarakat, seperti lingkungan permukiman, lingkungan industri, lingkungan usaha dan kawasan konservasi yang disesuaikan dengan penataan ruang.
Bantuan perbaikan prasarana dan sarana umum dimaksudkan untuk mendukung kelancaran perekonomian dan kehidupan masyarakat seperti sistem jaringan jalan, berupa bantuan perbaikan badan dan fondasi jalan dengan lapisan dasar batu dan lapisan aspal penutup. Jembatan penghubung, berupa bantuan rangka baja dan struktur dari Departemen Pekerjaan Umum, dengan penutup kayu dolken. Air bersih dan sanitasi, listrik dan energi, serta jaringan komunikasi berupa bantuan perbaikan jaringan instalasi yang terputus atau terendam. Jaringan irigasi dapat diberikan bantuan berupa bronjong dan karung pasir sebagai penutup sementara tanggul.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6218, 'Bantuan untuk perbaikan lingkungan daerah bencana dimaksudkan untuk mengembalikan kondisi lingkungan yang dapat mendukung kehidupan masyarakat, seperti lingkungan permukiman, lingkungan industri, lingkungan usaha dan kawasan konservasi yang disesuaikan dengan penataan ruang.
Bantuan perbaikan prasarana dan sarana umum dimaksudkan untuk mendukung kelancaran perekonomian dan kehidupan masyarakat seperti sistem jaringan jalan, berupa bantuan perbaikan badan dan fondasi jalan dengan lapisan dasar batu dan lapisan aspal penutup. Jembatan penghubung, berupa bantuan rangka baja dan struktur dari Departemen Pekerjaan Umum, dengan penutup kayu dolken. Air bersih dan sanitasi, listrik dan energi, serta jaringan komunikasi berupa bantuan perbaikan jaringan instalasi yang terputus atau terendam. Jaringan irigasi dapat diberikan bantuan berupa bronjong dan karung pasir sebagai penutup sementara tanggul.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6219, 'perka-12-2010', 17, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'Bantuan pembersihan puing-puing, lumpur, sampah, dan bahan berbahaya serta pemberian bantuan rumah masyarakat dan lingkungannya dimaksudkan untuk memperbaiki kondisi rumah masyarakat dan lingkungannya agar dapat mendukung kehidupan masyarakat seperti komponen rumah, prasarana dan sarana lingkungan perumahan yang memungkinkan berlangsungnya kehidupan sosial dan ekonomi yang memadai sesuai dengan standar pembangunan perumahan sebagaimana diatur dalam peraturan perundang-undangan (Keputusan Menteri Pemukiman dan Prasarana Wilayah Nomor 534/kpts/m/2001 tentang Pedoman Penentuan Standar Pelayanan Minimal Bidang Penataan Ruang, Perumahan dan Permukiman dan Pekerjaan Umum).
Pemberian bantuan perbaikan darurat termasuk untuk biaya tindakan aksi (face fighting), yaitu tindakan langsung yang dilakukan pada saat terjadi bencana yang dimaksudkan untuk mengatasi dan atau mengurangi sumber bencana, seperti: pemadaman api (fire fighting), isolasi (isolation), pencarian dan penyisiran bom (searching and sweeping), pemasangan bronjong dan karung pasir penahan tanggul, dan sebagainya sesuai dengan prosedur tetap yang ditetapkan oleh instansi/lembaga terkait.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6219, 'Bantuan pembersihan puing-puing, lumpur, sampah, dan bahan berbahaya serta pemberian bantuan rumah masyarakat dan lingkungannya dimaksudkan untuk memperbaiki kondisi rumah masyarakat dan lingkungannya agar dapat mendukung kehidupan masyarakat seperti komponen rumah, prasarana dan sarana lingkungan perumahan yang memungkinkan berlangsungnya kehidupan sosial dan ekonomi yang memadai sesuai dengan standar pembangunan perumahan sebagaimana diatur dalam peraturan perundang-undangan (Keputusan Menteri Pemukiman dan Prasarana Wilayah Nomor 534/kpts/m/2001 tentang Pedoman Penentuan Standar Pelayanan Minimal Bidang Penataan Ruang, Perumahan dan Permukiman dan Pekerjaan Umum).
Pemberian bantuan perbaikan darurat termasuk untuk biaya tindakan aksi (face fighting), yaitu tindakan langsung yang dilakukan pada saat terjadi bencana yang dimaksudkan untuk mengatasi dan atau mengurangi sumber bencana, seperti: pemadaman api (fire fighting), isolasi (isolation), pencarian dan penyisiran bom (searching and sweeping), pemasangan bronjong dan karung pasir penahan tanggul, dan sebagainya sesuai dengan prosedur tetap yang ditetapkan oleh instansi/lembaga terkait.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6220, 'perka-12-2010', 18, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'C. Sumber Bantuan Sesuai dengan Peraturan Kepala BNPB Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai, Ketentuan Bab II Bahwa Dana Siap Pakai (on call) adalah dana yang selalu tersedia dan dicadangkan oleh Pemerintah untuk digunakan pada saat tanggap darurat bencana sampai dengan batas waktu tanggap darurat berakhir. Dasar pemberiannya adalah: Penetapan status kedaruratan bencana, usulan kepala daerah perihal permohonan dukungan bantuan, laporan Tim Kaji Cepat BNPB, hasil rapat koordinasi atau inisiatif BNPB.
Penggunaan dana siap pakai dapat digunakan terbatas pada pengadaan barang/jasa untuk pertolongan darurat, pencarian dan penyelamatan korban bencana, evakuasi korban bencana, kebutuhan air bersih dan sanitasi, pangan, sandang, pelayanan kesehatan, penampungan/tempat hunian sementara, serta pemulihan segera prasarana dan sarana vital.
Pengadaan barang dan jasa dengan menggunakan dana siap pakai ini dapat menggunakan penunjukkan langsung sesuai peraturan perundang-undangan yang berlaku.
BAB III MEKANISME BANTUAN PERBAIKAN DARURAT A. Dasar Pemberian Bantuan Perbaikan Darurat
1. Penetapan status keadaan darurat bencana
2. Usulan daerah perihal permohonan dukungan bantuan
3. Laporan Tim Reaksi Cepat BNPB
4. Hasil Rapat Koordinasi
5. Inisiatif BNPB Bantuan perbaikan darurat di berikan setelah melalui tata cara pemberian bantuan perbaikan darurat yang telah diverifikasi dan di tetapkan berdasarkan kesepakatan dan/atau keputusan.
B. Tata Cara Pemberian');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6220, 'C. Sumber Bantuan Sesuai dengan Peraturan Kepala BNPB Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai, Ketentuan Bab II Bahwa Dana Siap Pakai (on call) adalah dana yang selalu tersedia dan dicadangkan oleh Pemerintah untuk digunakan pada saat tanggap darurat bencana sampai dengan batas waktu tanggap darurat berakhir. Dasar pemberiannya adalah: Penetapan status kedaruratan bencana, usulan kepala daerah perihal permohonan dukungan bantuan, laporan Tim Kaji Cepat BNPB, hasil rapat koordinasi atau inisiatif BNPB.
Penggunaan dana siap pakai dapat digunakan terbatas pada pengadaan barang/jasa untuk pertolongan darurat, pencarian dan penyelamatan korban bencana, evakuasi korban bencana, kebutuhan air bersih dan sanitasi, pangan, sandang, pelayanan kesehatan, penampungan/tempat hunian sementara, serta pemulihan segera prasarana dan sarana vital.
Pengadaan barang dan jasa dengan menggunakan dana siap pakai ini dapat menggunakan penunjukkan langsung sesuai peraturan perundang-undangan yang berlaku.
BAB III MEKANISME BANTUAN PERBAIKAN DARURAT A. Dasar Pemberian Bantuan Perbaikan Darurat
1. Penetapan status keadaan darurat bencana
2. Usulan daerah perihal permohonan dukungan bantuan
3. Laporan Tim Reaksi Cepat BNPB
4. Hasil Rapat Koordinasi
5. Inisiatif BNPB Bantuan perbaikan darurat di berikan setelah melalui tata cara pemberian bantuan perbaikan darurat yang telah diverifikasi dan di tetapkan berdasarkan kesepakatan dan/atau keputusan.
B. Tata Cara Pemberian', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6221, 'perka-12-2010', 19, 'lampiran', 'Lampiran hal. 11', NULL, 11, '1. Pengusulan Bantuan perbaikan darurat yang diusulkan baik oleh Pemerintah atau Pemerintah Daerah (Provinsi/Kabupaten/ Kota) harus sesuai dengan kewenangan. Usulan bantuan perbaikan darurat diajukan oleh :
a. Pemerintah Daerah Pemerintah daerah yang terkena bencana, melalui kepala daerah (Gubernur/Bupati/Walikota) mengajukan usulan bantuan perbaikan darurat kepada kepala BNPB dengan menyampaikan surat permohonan yang dilengkapi dengan :
1) Laporan kejadian 2) Jumlah korban 3) Kerusakan dan kerugian 4) Upaya penanganan yang telah dilakukan 5) Bantuan yang diperlukan dalam rangka perbaikan darurat berupa uraian fisik kegiatan dan anggaran.
6) Pernyataan status darurat bencana
b. Instansi / Lembaga Instansi/lembaga terkait dapat mengajukan usulan bantuan perbaikan darurat kepada kepala BNPB atas dasar hasil rapat koordinasi dengan menyampaikan surat permohonan yang dilengkapi dengan :
1) Laporan kejadian 2) Jumlah korban 3) Kerusakan dan kerugian 4) Upaya penanganan yang telah dilakukan 5) Bantuan yang diperlukan dalam rangka perbaikan darurat berupa uraian fisik kegiatan dan anggaran.
6) Pernyataan status darurat bencana 7) Notulen Kesepakatan Rapat Koordinasi
2. Verifikasi dan Penelaahan Verifikasi dan telaahan usulan bantuan perbaikan darurat dilakukan oleh Tim Reaksi Cepat (TRC) BNPB yang terdiri dari perwakilan instansi/lembaga terkait bersama pemerintah daerah (Provinsi/ Kabupaten/Kota) yang terkena bencana melalui peninjauan lapangan dan rapat koordinasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6221, '1. Pengusulan Bantuan perbaikan darurat yang diusulkan baik oleh Pemerintah atau Pemerintah Daerah (Provinsi/Kabupaten/ Kota) harus sesuai dengan kewenangan. Usulan bantuan perbaikan darurat diajukan oleh :
a. Pemerintah Daerah Pemerintah daerah yang terkena bencana, melalui kepala daerah (Gubernur/Bupati/Walikota) mengajukan usulan bantuan perbaikan darurat kepada kepala BNPB dengan menyampaikan surat permohonan yang dilengkapi dengan :
1) Laporan kejadian 2) Jumlah korban 3) Kerusakan dan kerugian 4) Upaya penanganan yang telah dilakukan 5) Bantuan yang diperlukan dalam rangka perbaikan darurat berupa uraian fisik kegiatan dan anggaran.
6) Pernyataan status darurat bencana
b. Instansi / Lembaga Instansi/lembaga terkait dapat mengajukan usulan bantuan perbaikan darurat kepada kepala BNPB atas dasar hasil rapat koordinasi dengan menyampaikan surat permohonan yang dilengkapi dengan :
1) Laporan kejadian 2) Jumlah korban 3) Kerusakan dan kerugian 4) Upaya penanganan yang telah dilakukan 5) Bantuan yang diperlukan dalam rangka perbaikan darurat berupa uraian fisik kegiatan dan anggaran.
6) Pernyataan status darurat bencana 7) Notulen Kesepakatan Rapat Koordinasi
2. Verifikasi dan Penelaahan Verifikasi dan telaahan usulan bantuan perbaikan darurat dilakukan oleh Tim Reaksi Cepat (TRC) BNPB yang terdiri dari perwakilan instansi/lembaga terkait bersama pemerintah daerah (Provinsi/ Kabupaten/Kota) yang terkena bencana melalui peninjauan lapangan dan rapat koordinasi.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6222, 'perka-12-2010', 20, 'lampiran', 'Lampiran hal. 12', NULL, 12, '3. Penetapan Pemberian Bantuan
a. Penetapan pemberian bantuan perbaikan darurat dilakukan oleh Kepala BNPB selaku Pengguna Anggaran/Barang berdasarkan hasil rapat koordinasi, baik yang dilakukan di tingkat daerah maupun di tingkat pusat.
b. Kepala BNPB dalam melaksanakan fungsinya dapat mendelegasikan kewenangannya kepada pejabat yang ditunjuk.
C. Pelaksanaan Pemberian Bantuan Bantuan perbaikan darurat dapat diberikan kepada Pemerintah Daerah (Provinsi/Kabupaten/Kota) dan/atau intansi/lembaga terkait sesuai dengan kewenangannya.
1. Pemerintah Daerah Bantuan perbaikan darurat kepada Pemerintah Daerah (Provinsi/Kabupaten/Kota) diberikan kepada Kepala Daerah (Gubernur/Bupati/Walikota) atau Kepala BPBD/SATLAK PB yang dilengkapi dengan Berita Acara Serah Terima Bantuan dan kuitansi.
2. Instansi/Lembaga terkait Bantuan perbaikan darurat kepada Instansi/Lembaga terkait diberikan kepada pimpinan Instansi/Lembaga terkait yang dilengkapi dengan Nota Kesepahaman, Berita Acara Serah Terima Bantuan, dan kuitansi.
D. Waktu Pemberian Bantuan Bantuan perbaikan darurat diberikan pada saat status keadaan darurat yaitu dimulai pada saat tanggap darurat ditetapkan sampai dengan ketetapan tahap tanggap darurat selesai sesuai dengan besar kecilnya skala bencana yaitu 2 (dua) minggu sampai dengan 1 (satu) bulan setelah kejadian bencana dan dapat diperpanjang berdasarkan keputusan dari Presiden atau Kepala Daerah sesuai dengan kewenangannya.
E. Tata Cara Pelaksanaan Perbaikan Darurat');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6222, '3. Penetapan Pemberian Bantuan
a. Penetapan pemberian bantuan perbaikan darurat dilakukan oleh Kepala BNPB selaku Pengguna Anggaran/Barang berdasarkan hasil rapat koordinasi, baik yang dilakukan di tingkat daerah maupun di tingkat pusat.
b. Kepala BNPB dalam melaksanakan fungsinya dapat mendelegasikan kewenangannya kepada pejabat yang ditunjuk.
C. Pelaksanaan Pemberian Bantuan Bantuan perbaikan darurat dapat diberikan kepada Pemerintah Daerah (Provinsi/Kabupaten/Kota) dan/atau intansi/lembaga terkait sesuai dengan kewenangannya.
1. Pemerintah Daerah Bantuan perbaikan darurat kepada Pemerintah Daerah (Provinsi/Kabupaten/Kota) diberikan kepada Kepala Daerah (Gubernur/Bupati/Walikota) atau Kepala BPBD/SATLAK PB yang dilengkapi dengan Berita Acara Serah Terima Bantuan dan kuitansi.
2. Instansi/Lembaga terkait Bantuan perbaikan darurat kepada Instansi/Lembaga terkait diberikan kepada pimpinan Instansi/Lembaga terkait yang dilengkapi dengan Nota Kesepahaman, Berita Acara Serah Terima Bantuan, dan kuitansi.
D. Waktu Pemberian Bantuan Bantuan perbaikan darurat diberikan pada saat status keadaan darurat yaitu dimulai pada saat tanggap darurat ditetapkan sampai dengan ketetapan tahap tanggap darurat selesai sesuai dengan besar kecilnya skala bencana yaitu 2 (dua) minggu sampai dengan 1 (satu) bulan setelah kejadian bencana dan dapat diperpanjang berdasarkan keputusan dari Presiden atau Kepala Daerah sesuai dengan kewenangannya.
E. Tata Cara Pelaksanaan Perbaikan Darurat', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6223, 'perka-12-2010', 21, 'lampiran', 'Lampiran hal. 13', NULL, 13, '1. Perbaikan Darurat dilakukan oleh dinas/instansi/lembaga terkait yang dikoordinasikan oleh BPBD Provinsi/Kabupaten/Kota sesuai dengan kewenangannya.
2. Proses perbaikan darurat dapat dilakukan melalui penunjukkan langsung dan atau swakelola.
3. Penunjukkan langsung dilaksanakan pada saat tanggap darurat ditetapkan sampai dengan ketetapan tahap tanggap darurat selesai.
4. Pelaksanaan perbaikan darurat dengan proses penunjukkan langsung dapat dilakukan sampai dengan masa transisi menuju tahap pemulihan berdasarkan Surat Keputusan/Pernyataan berakhirnya masa tanggap darurat.
5. Swakelola BAB IV PEMANTAUAN, PENGAWASAN, EVALUASI, DAN PELAPORAN A. Pemantauan Semua kegiatan pelaksanaan pemberian bantuan perbaikan darurat senantiasa dilakukan pemantauan oleh BNPB/ BPBD/SATLAK PB, instansi/dinas/lembaga terkait sesuai dengan peraturan yang berlaku dan tingkat kewenangannya.
B. Pengawasan Pengawasan dilakukan secara berjenjang sesuai dengan tingkat kewenangannya oleh instansi/lembaga baik dari pihak internal BNPB/BPBD/SATLAK PB oleh Inspektur Utama dan Bawasda maupun pihak eksternal, seperti BPKP, BPK, dan lainnya.
C. Evaluasi Evaluasi dilakukan secara berkala sesuai dengan kemajuan pekerjaan (progress report) yang telah disepakati dalam perjanjian atau kontrak kerjasama antara pemberi bantuan dan penerima bantuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6223, '1. Perbaikan Darurat dilakukan oleh dinas/instansi/lembaga terkait yang dikoordinasikan oleh BPBD Provinsi/Kabupaten/Kota sesuai dengan kewenangannya.
2. Proses perbaikan darurat dapat dilakukan melalui penunjukkan langsung dan atau swakelola.
3. Penunjukkan langsung dilaksanakan pada saat tanggap darurat ditetapkan sampai dengan ketetapan tahap tanggap darurat selesai.
4. Pelaksanaan perbaikan darurat dengan proses penunjukkan langsung dapat dilakukan sampai dengan masa transisi menuju tahap pemulihan berdasarkan Surat Keputusan/Pernyataan berakhirnya masa tanggap darurat.
5. Swakelola BAB IV PEMANTAUAN, PENGAWASAN, EVALUASI, DAN PELAPORAN A. Pemantauan Semua kegiatan pelaksanaan pemberian bantuan perbaikan darurat senantiasa dilakukan pemantauan oleh BNPB/ BPBD/SATLAK PB, instansi/dinas/lembaga terkait sesuai dengan peraturan yang berlaku dan tingkat kewenangannya.
B. Pengawasan Pengawasan dilakukan secara berjenjang sesuai dengan tingkat kewenangannya oleh instansi/lembaga baik dari pihak internal BNPB/BPBD/SATLAK PB oleh Inspektur Utama dan Bawasda maupun pihak eksternal, seperti BPKP, BPK, dan lainnya.
C. Evaluasi Evaluasi dilakukan secara berkala sesuai dengan kemajuan pekerjaan (progress report) yang telah disepakati dalam perjanjian atau kontrak kerjasama antara pemberi bantuan dan penerima bantuan.', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6224, 'perka-12-2010', 22, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'D. Pelaporan Semua hasil pemantauan, pengawasan, dan evaluasi ini dituangkan dalam bentuk laporan atau berita acara hasil pemantauan, pengawasan dan evaluasi sebagai bahan dokumentasi yang dapat dipertanggungjawabkan.
Pelaporan atas penggunaan bantuan perbaikan darurat dilakukan secara berkala atau sesuai dengan kesepakatan atau kontrak yang telah disepakati bersama antara Kepala BNPB dengan instansi/lembaga/Kepala daerah provinsi, kabupaten/kota setempat.
Laporan pertanggungjawaban bantuan perbaikan darurat harus disertai dengan laporan Pertanggungjawaban administrasi, keuangan, kemajuan pekerjaan fisik yang dikerjakan disertai dengan bukti-bukti pendukung lainnya, seperti: Kontrak Perjanjian Kerja, Rencana Anggaran Biaya yang telah disepakati, Berita Acara Kemajuan Pekerjaan, Surat Perintah Kerja (SPK), Surat Pemberitahuan Pajak (SPP), foto-foto hasil pekerjaan dan dokumentasi lainnya.
BAB V PENUTUP Pedoman mekanisme pemberian bantuan perbaikan darurat ini diharapkan dapat menjadi pedoman penyelenggaraan pemberian bantuan perbaikan darurat yang lebih baik, efektif, efisien dan akuntabel. Semoga pedoman ini dapat dimanfaatkan oleh seluruh pejabat atau petugas yang terlibat dalam penanganan darurat bencana serta dapat terlaksana dengan cepat, tepat, tertib, sesuai sasaran dan peraturan yang berlaku. Pedoman yang berkaitan dengan pemberian bantuan perbaikan darurat tetap berlaku sepanjang tidak bertentangan dengan Peraturan Kepala Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6224, 'D. Pelaporan Semua hasil pemantauan, pengawasan, dan evaluasi ini dituangkan dalam bentuk laporan atau berita acara hasil pemantauan, pengawasan dan evaluasi sebagai bahan dokumentasi yang dapat dipertanggungjawabkan.
Pelaporan atas penggunaan bantuan perbaikan darurat dilakukan secara berkala atau sesuai dengan kesepakatan atau kontrak yang telah disepakati bersama antara Kepala BNPB dengan instansi/lembaga/Kepala daerah provinsi, kabupaten/kota setempat.
Laporan pertanggungjawaban bantuan perbaikan darurat harus disertai dengan laporan Pertanggungjawaban administrasi, keuangan, kemajuan pekerjaan fisik yang dikerjakan disertai dengan bukti-bukti pendukung lainnya, seperti: Kontrak Perjanjian Kerja, Rencana Anggaran Biaya yang telah disepakati, Berita Acara Kemajuan Pekerjaan, Surat Perintah Kerja (SPK), Surat Pemberitahuan Pajak (SPP), foto-foto hasil pekerjaan dan dokumentasi lainnya.
BAB V PENUTUP Pedoman mekanisme pemberian bantuan perbaikan darurat ini diharapkan dapat menjadi pedoman penyelenggaraan pemberian bantuan perbaikan darurat yang lebih baik, efektif, efisien dan akuntabel. Semoga pedoman ini dapat dimanfaatkan oleh seluruh pejabat atau petugas yang terlibat dalam penanganan darurat bencana serta dapat terlaksana dengan cepat, tepat, tertib, sesuai sasaran dan peraturan yang berlaku. Pedoman yang berkaitan dengan pemberian bantuan perbaikan darurat tetap berlaku sepanjang tidak bertentangan dengan Peraturan Kepala Badan Nasional Penanggulangan Bencana.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2010 tentang Pedoman Mekanisme Pemberian Bantuan Perbaikan Darurat');
