INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6227, 'perka-12-2014', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6227, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6228, 'perka-12-2014', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa masalah bencana terkait dengan hak dasar manusia yang dilaksanakan secara utuh Pemerintah, Pemerintah Daerah, Masyarakat, dan Dunia Usaha, dampak sosiologis masyarakat mengalami gangguan tidak aman, ketakutan, dan rusaknya lingkungan, masyarakat juga mengalami beban psikologis yang berpengaruh juga pada mental dan kejiwaan masyarakat dari dampak bencana, penanggulangan bencana perlu melibatkan peran serta lembaga usaha;
b. bahwa untuk melaksanakan ketentuan Pasal 28 dan Pasal 29 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan 2014, No.1603 2 Bencana tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6228, 'a. bahwa masalah bencana terkait dengan hak dasar manusia yang dilaksanakan secara utuh Pemerintah, Pemerintah Daerah, Masyarakat, dan Dunia Usaha, dampak sosiologis masyarakat mengalami gangguan tidak aman, ketakutan, dan rusaknya lingkungan, masyarakat juga mengalami beban psikologis yang berpengaruh juga pada mental dan kejiwaan masyarakat dari dampak bencana, penanggulangan bencana perlu melibatkan peran serta lembaga usaha;
b. bahwa untuk melaksanakan ketentuan Pasal 28 dan Pasal 29 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan 2014, No.1603 2 Bencana tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6229, 'perka-12-2014', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
3. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
4. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
5. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6229, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
3. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
4. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
5. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6230, 'perka-12-2014', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan: PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PERAN SERTA LEMBAGA USAHA DALAM PENYELENGGARAAN PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6230, 'Menetapkan: PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PERAN SERTA LEMBAGA USAHA DALAM PENYELENGGARAAN PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6231, 'perka-12-2014', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM', 2, 'Dalam Peraturan Kepala ini yang dimaksud dengan :
1. Peran serta adalah proses keterlibatan masyarakat yang terorganisasi di dalam Lembaga Usaha dalam perencanaan, pelaksanaan, pengawasan, pemantauan, evaluasi, dan pelaporan kegiatan penanggulangan bencana yang dilakukannya.
2. Lembaga Usaha adalah setiap badan hukum yang dapat berbentuk badan usaha milik negara, badan usaha milik daerah, koperasi, atau swasta yang didirikan sesuai dengan ketentuan peraturan perundang- 3 2014, No.1603 undangan yang menjalankan jenis usaha tetap dan terus-menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia.
3. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
4. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
5. Pencegahan bencana adalah serangkaian kegiatan yang dilakukan sebelum terjadi bencana untuk mengurangi atau menghilangkan risiko bencana, baik melalui pengurangan ancaman bencana maupun kerentanan pihak yang terancam bencana.
6. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, penyelamatan, serta pemulihan prasarana dan sarana.
7. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pascabencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.
8. Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta masyarakat dalam segala aspek kehidupan bermasyarakat pada wilayah pascabencana.
9. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB, adalah lembaga pemerintah non-kementerian sesuai dengan ketentuan peraturan perundang-undangan.
10. Pemerintah Daerah adalah gubernur, bupati/walikota atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
2014, No.1603 4
11. Badan Penanggulangan Bencana Daerah, yang selanjutnya disingkat BPBD, adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.');
