INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6232, 'perka-12-2014', 5, 'pasal', 'Pasal 2', 'BAB I KETENTUAN UMUM', 4, 'Peran serta Lembaga Usaha dalam penyelenggaraan penanggulangan bencana bertujuan untuk mendukung penguatan kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi secara berdayaguna, berhasilguna, dan dapat dipertanggungjawabkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6232, 'Peran serta Lembaga Usaha dalam penyelenggaraan penanggulangan bencana bertujuan untuk mendukung penguatan kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi secara berdayaguna, berhasilguna, dan dapat dipertanggungjawabkan.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6233, 'perka-12-2014', 6, 'pasal', 'Pasal 3', 'BAB I KETENTUAN UMUM', 4, '(1) Peran serta Lembaga Usaha dalam penyelenggaraan penanggulangan bencana meliputi tahap prabencana, keadaan darurat, dan pascabencana.
(2) Peran serta sebagaimana dimaksud pada ayat (1) dilakukan secara sendiri atau bersama dengan mitra kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6233, '(1) Peran serta Lembaga Usaha dalam penyelenggaraan penanggulangan bencana meliputi tahap prabencana, keadaan darurat, dan pascabencana.
(2) Peran serta sebagaimana dimaksud pada ayat (1) dilakukan secara sendiri atau bersama dengan mitra kerja.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6234, 'perka-12-2014', 7, 'pasal', 'Pasal 4', 'BAB II TATA CARA PERAN SERTA LEMBAGA USAHA; Bagian Kesatu Prabencana dan Pascabencana', 4, '(1) Rencana kegiatan pada tahap prabencana berisi usulan kegiatan yang dilakukan oleh Lembaga Usaha di wilayah kerja untuk mengurangi atau menghilangkan risiko bencana, baik melalui pengurangan ancaman bencana maupun kerentanan pihak yang terancam bencana.
(2) Kegiatan sebagaimana dimaksud pada ayat (1) meliputi:
a. pengenalan dan pemantauan risiko bencana;
b. perencanaan partisipatif penanggulangan bencana;
c. pengembangan budaya sadar bencana;
d. pengorganisasian, pemasangan, dan pengujian sistem peringatan dini;
e. pengorganisasian, penyuluhan, pelatihan, dan gladi tentang mekanisme tanggap darurat;
f. penyebarluasan informasi tentang peringatan bencana penyiapan jalur evakuasi; dan
g. kegiatan lain untuk mengurangi atau menghilangkan risiko bencana.
5 2014, No.1603');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6234, '(1) Rencana kegiatan pada tahap prabencana berisi usulan kegiatan yang dilakukan oleh Lembaga Usaha di wilayah kerja untuk mengurangi atau menghilangkan risiko bencana, baik melalui pengurangan ancaman bencana maupun kerentanan pihak yang terancam bencana.
(2) Kegiatan sebagaimana dimaksud pada ayat (1) meliputi:
a. pengenalan dan pemantauan risiko bencana;
b. perencanaan partisipatif penanggulangan bencana;
c. pengembangan budaya sadar bencana;
d. pengorganisasian, pemasangan, dan pengujian sistem peringatan dini;
e. pengorganisasian, penyuluhan, pelatihan, dan gladi tentang mekanisme tanggap darurat;
f. penyebarluasan informasi tentang peringatan bencana penyiapan jalur evakuasi; dan
g. kegiatan lain untuk mengurangi atau menghilangkan risiko bencana.
5 2014, No.1603', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6235, 'perka-12-2014', 8, 'pasal', 'Pasal 5', 'BAB II TATA CARA PERAN SERTA LEMBAGA USAHA; Bagian Kesatu Prabencana dan Pascabencana', 5, 'Lembaga Usaha yang akan berperan serta pada tahap prabencana atau pascabencana harus menyusun:
a. nota kesepahaman;
b. kerangka acuan kegiatan; dan
c. rencana kegiatan.
(1) Memorandum Saling Pengertian, kerangka acuan kegiatan, dan rencana kegiatan sebagaimana dimaksud pada ayat (1) disusun secara bersama-sama antara Lembaga Usaha dan BNPB atau BPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6235, 'Lembaga Usaha yang akan berperan serta pada tahap prabencana atau pascabencana harus menyusun:
a. nota kesepahaman;
b. kerangka acuan kegiatan; dan
c. rencana kegiatan.
(1) Memorandum Saling Pengertian, kerangka acuan kegiatan, dan rencana kegiatan sebagaimana dimaksud pada ayat (1) disusun secara bersama-sama antara Lembaga Usaha dan BNPB atau BPBD.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6236, 'perka-12-2014', 9, 'pasal', 'Pasal 6', 'BAB II TATA CARA PERAN SERTA LEMBAGA USAHA; Bagian Kesatu Prabencana dan Pascabencana', 5, 'Penyusunan Memorandum Saling Pengertian sebagaimana dimaksud dalam Pasal 5 ayat (2) didasarkan pada format yang dibuat oleh BNPB atau BPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6236, 'Penyusunan Memorandum Saling Pengertian sebagaimana dimaksud dalam Pasal 5 ayat (2) didasarkan pada format yang dibuat oleh BNPB atau BPBD.', 'Pasal 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6237, 'perka-12-2014', 10, 'pasal', 'Pasal 7', 'BAB II TATA CARA PERAN SERTA LEMBAGA USAHA; Bagian Kesatu Prabencana dan Pascabencana', 5, '(1) Penyusunan kerangka acuan kegiatan, dan rencana kegiatan sebagaimana dimaksud dalam Pasal 4 ayat (2) didasarkan pada kapasitas sumber daya Lembaga Usaha dan kebijakan penyelenggaraan penanggulangan bencana.
(2) Kebijakan penyelenggaraan penanggulangan bencana sebagaimana dimaksud pada ayat (1) disosialisasikan oleh BNPB atau BPBD, baik melalui forum pertemuan mapun melalui media massa dan jejaring sosial.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6237, '(1) Penyusunan kerangka acuan kegiatan, dan rencana kegiatan sebagaimana dimaksud dalam Pasal 4 ayat (2) didasarkan pada kapasitas sumber daya Lembaga Usaha dan kebijakan penyelenggaraan penanggulangan bencana.
(2) Kebijakan penyelenggaraan penanggulangan bencana sebagaimana dimaksud pada ayat (1) disosialisasikan oleh BNPB atau BPBD, baik melalui forum pertemuan mapun melalui media massa dan jejaring sosial.', 'Pasal 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6238, 'perka-12-2014', 11, 'pasal', 'Pasal 8', 'BAB II TATA CARA PERAN SERTA LEMBAGA USAHA; Bagian Kesatu Prabencana dan Pascabencana', 5, '(1) Rencana kegiatan pada tahap pascabencana berisi usulan kegiatan yang dilakukan oleh Lembaga Usaha di wilayah kerja, baik berupa perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai maupun pembangunan kembali prasarana dan sarana, kelembagaan pada wilayah pascabencana.
(2) Kegiatan sebagaimana dimaksud pada ayat (1) meliputi:
a. pengkajian kebutuhan pasca bencana dan penyusunan rencana aksi rehabilitasi dan rekonstruksi;
2014, No.1603 6
b. perbaikan lingkungan, prasarana dan sarana umum, dan pemberian bantuan perbaikan rumah;
c. pelayanan kesehatan, serta pemulihan sosial psikologis dan sosial ekonomi masyarakat;
d. pembangunan kembali prasarana dan sarana lingkungan dan sosial masyarakat;
e. peningkatan kondisi sosial, ekonomi, dan budaya;
f. pemantauan pelaksanaan rencana aksi rehabilitasi dan rekonstruksi terhadap kelompok sasaran; dan
g. kegiatan lain berupa perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai maupun pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6238, '(1) Rencana kegiatan pada tahap pascabencana berisi usulan kegiatan yang dilakukan oleh Lembaga Usaha di wilayah kerja, baik berupa perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai maupun pembangunan kembali prasarana dan sarana, kelembagaan pada wilayah pascabencana.
(2) Kegiatan sebagaimana dimaksud pada ayat (1) meliputi:
a. pengkajian kebutuhan pasca bencana dan penyusunan rencana aksi rehabilitasi dan rekonstruksi;
2014, No.1603 6
b. perbaikan lingkungan, prasarana dan sarana umum, dan pemberian bantuan perbaikan rumah;
c. pelayanan kesehatan, serta pemulihan sosial psikologis dan sosial ekonomi masyarakat;
d. pembangunan kembali prasarana dan sarana lingkungan dan sosial masyarakat;
e. peningkatan kondisi sosial, ekonomi, dan budaya;
f. pemantauan pelaksanaan rencana aksi rehabilitasi dan rekonstruksi terhadap kelompok sasaran; dan
g. kegiatan lain berupa perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai maupun pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana.', 'Pasal 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6239, 'perka-12-2014', 12, 'pasal', 'Pasal 9', 'BAB II TATA CARA PERAN SERTA LEMBAGA USAHA; Bagian Kedua Tanggap Darurat', 6, 'Dalam hal peran serta Lembaga Usaha dilakukan bersama mitra kerja, penyusunan nota kesepahaman dan kerangka acuan kegiatan sebagaimana dimaksud dalam Pasal 4 ayat (2) melibatkan mitra kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6239, 'Dalam hal peran serta Lembaga Usaha dilakukan bersama mitra kerja, penyusunan nota kesepahaman dan kerangka acuan kegiatan sebagaimana dimaksud dalam Pasal 4 ayat (2) melibatkan mitra kerja.', 'Pasal 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6240, 'perka-12-2014', 13, 'pasal', 'Pasal 10', 'BAB II TATA CARA PERAN SERTA LEMBAGA USAHA; Bagian Kedua Tanggap Darurat', 6, 'Lembaga Usaha yang akan berperan serta pada tahap keadaan darurat memberikan bantuan secara langsung kepada pos komando penanganan darurat BNPB atau BPBD.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6240, 'Lembaga Usaha yang akan berperan serta pada tahap keadaan darurat memberikan bantuan secara langsung kepada pos komando penanganan darurat BNPB atau BPBD.', 'Pasal 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6241, 'perka-12-2014', 14, 'pasal', 'Pasal 11', 'BAB III PELAKSANAAN PERAN SERTA LEMBAGA USAHA; Bagian Kesatu Umum', 6, '(1) Bantuan pada saat keadaan darurat yang diberikan oleh Lembaga Usaha didayagunakan bagi kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan.
(2) kegiatan sebagaimana dimaksud pada ayat (1) meliputi:
a. pencarian dan penyelamatan, serta evakuasi korban dan harta benda;
b. pemenuhan kebutuhan dasar;
c. perlindungan dan pengurusan pengungsi dan kelompok rentan;
d. penyelamatan dan pemulihan prasarana dan sarana vital; dan
e. kegiatan lain yang dilakukan dengan segera pada saat kejadian bencana.
7 2014, No.1603');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6241, '(1) Bantuan pada saat keadaan darurat yang diberikan oleh Lembaga Usaha didayagunakan bagi kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan.
(2) kegiatan sebagaimana dimaksud pada ayat (1) meliputi:
a. pencarian dan penyelamatan, serta evakuasi korban dan harta benda;
b. pemenuhan kebutuhan dasar;
c. perlindungan dan pengurusan pengungsi dan kelompok rentan;
d. penyelamatan dan pemulihan prasarana dan sarana vital; dan
e. kegiatan lain yang dilakukan dengan segera pada saat kejadian bencana.
7 2014, No.1603', 'Pasal 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6242, 'perka-12-2014', 15, 'pasal', 'Pasal 12', 'BAB III PELAKSANAAN PERAN SERTA LEMBAGA USAHA; Bagian Kesatu Umum', 7, '(1) BNPB atau BPBD memberikan jaminan perlindungan keamanaan kepada Lembaga Usaha dalam pelaksanaan kegiatan penanggulangan bencana.
(2) Pemberian jaminan perlindungan keamanan sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6242, '(1) BNPB atau BPBD memberikan jaminan perlindungan keamanaan kepada Lembaga Usaha dalam pelaksanaan kegiatan penanggulangan bencana.
(2) Pemberian jaminan perlindungan keamanan sebagaimana dimaksud pada ayat (1) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6243, 'perka-12-2014', 16, 'pasal', 'Pasal 13', 'BAB III PELAKSANAAN PERAN SERTA LEMBAGA USAHA; Bagian Kesatu Umum', 7, '(1) BNPB atau BPBD memberikan kemudahan dan fasilitas kepada Lembaga Usaha dalam pelaksanaan kegiatan penanggulangan bencana.
(2) Pemberian kemudahan dan fasilitas sebagaimana dimaksud pada ayat
(1) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6243, '(1) BNPB atau BPBD memberikan kemudahan dan fasilitas kepada Lembaga Usaha dalam pelaksanaan kegiatan penanggulangan bencana.
(2) Pemberian kemudahan dan fasilitas sebagaimana dimaksud pada ayat
(1) dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6244, 'perka-12-2014', 17, 'pasal', 'Pasal 14', 'BAB III PELAKSANAAN PERAN SERTA LEMBAGA USAHA; Bagian Kesatu Umum', 7, 'Dalam pelaksanaan kegiatan penanggulangan bencana, Lembaga Usaha wajib:
(1) menjalankan prinsip akuntabilitas;
(2) mematuhi asas, prinsip, tujuan, serta standar minimum layanan dan kompetensi berdasarkan ketentuan peraturan perundang-undangan di bidang penanggulangan bencana;
(3) memperhatikan standar dan norma kemanusiaan yang berlaku secara umum; dan
(4) menghormati latar belakang sosial, budaya, dan agama masyarakat setempat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6244, 'Dalam pelaksanaan kegiatan penanggulangan bencana, Lembaga Usaha wajib:
(1) menjalankan prinsip akuntabilitas;
(2) mematuhi asas, prinsip, tujuan, serta standar minimum layanan dan kompetensi berdasarkan ketentuan peraturan perundang-undangan di bidang penanggulangan bencana;
(3) memperhatikan standar dan norma kemanusiaan yang berlaku secara umum; dan
(4) menghormati latar belakang sosial, budaya, dan agama masyarakat setempat.', 'Pasal 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6245, 'perka-12-2014', 18, 'pasal', 'Pasal 15', 'BAB III PELAKSANAAN PERAN SERTA LEMBAGA USAHA; Bagian Kedua Prabencana dan Pascabencana', 7, 'Lembaga Usaha dalam pelaksanaan kegiatan penanggulangan bencana:
(1) melakukan kegiatan tidak berlatar belakang politik, pertahanan dan keamanan; dan
(2) melakukan kegiatan tidak bersifat eksploitasi terhadap korban terdampak bencana.
2014, No.1603 8');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6245, 'Lembaga Usaha dalam pelaksanaan kegiatan penanggulangan bencana:
(1) melakukan kegiatan tidak berlatar belakang politik, pertahanan dan keamanan; dan
(2) melakukan kegiatan tidak bersifat eksploitasi terhadap korban terdampak bencana.
2014, No.1603 8', 'Pasal 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6246, 'perka-12-2014', 19, 'pasal', 'Pasal 16', 'BAB III PELAKSANAAN PERAN SERTA LEMBAGA USAHA; Bagian Kedua Prabencana dan Pascabencana', 8, '(1) Dalam rangka pelaksanaan rencana kegiatan sebagaimana dimaksud dalam Pasal 8 dan Pasal 9, Lembaga Usaha harus mengumumkan rencana kegiatan tersebut kepada masyarakat pada wilayah kerja.
(2) Lembaga Usaha bekerjasama dengan masyarakat di wilayah kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6246, '(1) Dalam rangka pelaksanaan rencana kegiatan sebagaimana dimaksud dalam Pasal 8 dan Pasal 9, Lembaga Usaha harus mengumumkan rencana kegiatan tersebut kepada masyarakat pada wilayah kerja.
(2) Lembaga Usaha bekerjasama dengan masyarakat di wilayah kerja.', 'Pasal 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6247, 'perka-12-2014', 20, 'pasal', 'Pasal 17', 'BAB III PELAKSANAAN PERAN SERTA LEMBAGA USAHA; Bagian Ketiga Tanggap Darurat', 8, 'BNPB atau BPBD melakukan koordinasi pelaksanaan rencana kegiatan sebagaimana dimaksud dalam Pasal 8 dan Pasal 9.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6247, 'BNPB atau BPBD melakukan koordinasi pelaksanaan rencana kegiatan sebagaimana dimaksud dalam Pasal 8 dan Pasal 9.', 'Pasal 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6248, 'perka-12-2014', 21, 'pasal', 'Pasal 18', 'BAB III PELAKSANAAN PERAN SERTA LEMBAGA USAHA; Bagian Ketiga Tanggap Darurat', 8, '(1) Dalam rangka pemberian bantuan sebagaimana dimaksud dalam Pasal 10, Lembaga Usaha harus melaporkan identitas Lembaga Usaha, serta daftar jumlah dan keahlian personil, logistik dan peralatan kepada pos komando penanganan darurat BNPB atau BPBD.
(2) Penyampaian daftar jumlah dan keahlian personil logistik dan peralatan sebagaimana dimaksud pada ayat (1) dapat dilakukan sebelum, pada saat, dan sesudah bantuan tiba di wilayah bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6248, '(1) Dalam rangka pemberian bantuan sebagaimana dimaksud dalam Pasal 10, Lembaga Usaha harus melaporkan identitas Lembaga Usaha, serta daftar jumlah dan keahlian personil, logistik dan peralatan kepada pos komando penanganan darurat BNPB atau BPBD.
(2) Penyampaian daftar jumlah dan keahlian personil logistik dan peralatan sebagaimana dimaksud pada ayat (1) dapat dilakukan sebelum, pada saat, dan sesudah bantuan tiba di wilayah bencana.', 'Pasal 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6249, 'perka-12-2014', 22, 'pasal', 'Pasal 19', 'BAB III PELAKSANAAN PERAN SERTA LEMBAGA USAHA; Bagian Ketiga Tanggap Darurat', 8, 'Berdasarkan daftar jumlah personil logistik dan peralatan sebagaimana dimaksud dalam Pasal 18 ayat (2), Komandan pos komando penanganan darurat BNPB atau BPBD memberikan persetujuan sesuai dengan kebutuhan keadaan darurat di wilayah bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6249, 'Berdasarkan daftar jumlah personil logistik dan peralatan sebagaimana dimaksud dalam Pasal 18 ayat (2), Komandan pos komando penanganan darurat BNPB atau BPBD memberikan persetujuan sesuai dengan kebutuhan keadaan darurat di wilayah bencana.', 'Pasal 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6250, 'perka-12-2014', 23, 'pasal', 'Pasal 20', 'BAB IV PENGAWASAN, PELAPORAN DAN PENGHARGAAN PERAN SERTA LEMBAGA USAHA', 8, '(1) BNPB atau BPBD memegang komando atas pendayagunaan bantuan bagi kegiatan sebagaimana dimaksud pada Pasal 11 ayat (2).
(2) Dalam rangka berbagi kapasitas bersama para pihak, BNPB atau BPBD dapat menempatkan Lembaga Usaha dalam organisasi komando sebagaimana dimaksud pada ayat (1).
9 2014, No.1603');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6250, '(1) BNPB atau BPBD memegang komando atas pendayagunaan bantuan bagi kegiatan sebagaimana dimaksud pada Pasal 11 ayat (2).
(2) Dalam rangka berbagi kapasitas bersama para pihak, BNPB atau BPBD dapat menempatkan Lembaga Usaha dalam organisasi komando sebagaimana dimaksud pada ayat (1).
9 2014, No.1603', 'Pasal 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6251, 'perka-12-2014', 24, 'pasal', 'Pasal 21', 'BAB IV PENGAWASAN, PELAPORAN DAN PENGHARGAAN PERAN SERTA LEMBAGA USAHA', 9, '(1) BNPB atau BPBD melakukan pengawasan terhadap peran serta Lembaga Usaha dalam penyelenggaraan penanggulangan bencana.
(2) Pengawasan sebagaimana dimaksud pada ayat (1) dilakukan untuk menjamin dayaguna, hasilguna, akutabilitas peran serta Lembaga Usaha dalam penyelenggaraan penanggulangan bencana.
(3) Ketentuan mengenai tata cara pengawasan sebagaimana dimaksud pada ayat (1) diatur dengan Peraturan Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6251, '(1) BNPB atau BPBD melakukan pengawasan terhadap peran serta Lembaga Usaha dalam penyelenggaraan penanggulangan bencana.
(2) Pengawasan sebagaimana dimaksud pada ayat (1) dilakukan untuk menjamin dayaguna, hasilguna, akutabilitas peran serta Lembaga Usaha dalam penyelenggaraan penanggulangan bencana.
(3) Ketentuan mengenai tata cara pengawasan sebagaimana dimaksud pada ayat (1) diatur dengan Peraturan Kepala BNPB.', 'Pasal 21', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6252, 'perka-12-2014', 25, 'pasal', 'Pasal 22', 'BAB IV PENGAWASAN, PELAPORAN DAN PENGHARGAAN PERAN SERTA LEMBAGA USAHA', 9, '(1) Lembaga Usaha wajib menyampaikan laporan pelaksanaan kegiatan secara berkala, pada saat selesai kegiatan, atau sewaktu-waktu kepada BNPB atau BPBD;
(2) Laporan sebagaimana dimaksud pada ayat (1) diumumkan oleh BNPB atau BPBD kepada publik;
(3) Ketentuan mengenai tata cara pelaporan dan substansi laporan sebagaimana dimaksud pada ayat (1) diatur dengan Peraturan Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6252, '(1) Lembaga Usaha wajib menyampaikan laporan pelaksanaan kegiatan secara berkala, pada saat selesai kegiatan, atau sewaktu-waktu kepada BNPB atau BPBD;
(2) Laporan sebagaimana dimaksud pada ayat (1) diumumkan oleh BNPB atau BPBD kepada publik;
(3) Ketentuan mengenai tata cara pelaporan dan substansi laporan sebagaimana dimaksud pada ayat (1) diatur dengan Peraturan Kepala BNPB.', 'Pasal 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6253, 'perka-12-2014', 26, 'pasal', 'Pasal 23', 'BAB V KETENTUAN LAIN-LAIN', 9, '(1) BNPB atau BPBD memberikan penghargaan kepada Lembaga Usaha atas peran serta dalam penyelenggaraan penanggulangan bencana.
(2) Penghargaan kearsipan sebagaimana dimaksud pada ayat (1) dilakukan berdasarkan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6253, '(1) BNPB atau BPBD memberikan penghargaan kepada Lembaga Usaha atas peran serta dalam penyelenggaraan penanggulangan bencana.
(2) Penghargaan kearsipan sebagaimana dimaksud pada ayat (1) dilakukan berdasarkan peraturan perundang-undangan.', 'Pasal 23', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6254, 'perka-12-2014', 27, 'pasal', 'Pasal 24', 'BAB V KETENTUAN LAIN-LAIN', 9, 'Lembaga Usaha dalam pelaksanaan kegiatan penanggulangan bencana berbagi kapasitas bersama para pihak di bidang penanggulangan bencana melalui :
(1) pelibatan dalam penyusunan rencana kegiatan;
(2) pendampingan dalam pelaksanaan kegiatan;
(3) penyampaian umpan balik;
(4) peningkatan kapasitas bersama; dan
(5) kegiatan berbagi kapasitas lain.
2014, No.1603 10');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6254, 'Lembaga Usaha dalam pelaksanaan kegiatan penanggulangan bencana berbagi kapasitas bersama para pihak di bidang penanggulangan bencana melalui :
(1) pelibatan dalam penyusunan rencana kegiatan;
(2) pendampingan dalam pelaksanaan kegiatan;
(3) penyampaian umpan balik;
(4) peningkatan kapasitas bersama; dan
(5) kegiatan berbagi kapasitas lain.
2014, No.1603 10', 'Pasal 24', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6255, 'perka-12-2014', 28, 'pasal', 'Pasal 25', 'BAB V KETENTUAN LAIN-LAIN', 10, '(1) Lembaga Usaha dalam pelaksanaan kegiatan penanggulangan bencana melakukan pembelajaran bersama para pihak di bidang penanggulangan bencana bagi peningkatan kapasitas.
(2) Pembelajaran bersama sebagaimana dimaksud pada atas (1) difasilitasi oleh BNPB atau BPBD, baik melalui forum seminar, bimbingan teknis, maupun pendidikan dan pelatihan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6255, '(1) Lembaga Usaha dalam pelaksanaan kegiatan penanggulangan bencana melakukan pembelajaran bersama para pihak di bidang penanggulangan bencana bagi peningkatan kapasitas.
(2) Pembelajaran bersama sebagaimana dimaksud pada atas (1) difasilitasi oleh BNPB atau BPBD, baik melalui forum seminar, bimbingan teknis, maupun pendidikan dan pelatihan.', 'Pasal 25', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6256, 'perka-12-2014', 29, 'pasal', 'Pasal 26', 'BAB VI KETENTUAN SANKSI', 10, 'Setelah pelaksanaan kegiatan penanggulangan bencana, Lembaga Usaha menatausahakan pengalihan kepemilikan atas aset dari kegiatan melalui mekanisme hibah berdasarkan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6256, 'Setelah pelaksanaan kegiatan penanggulangan bencana, Lembaga Usaha menatausahakan pengalihan kepemilikan atas aset dari kegiatan melalui mekanisme hibah berdasarkan peraturan perundang-undangan.', 'Pasal 26', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6257, 'perka-12-2014', 30, 'pasal', 'Pasal 27', 'BAB VII KETENTUAN PENUTUP', 10, 'Lembaga Usaha yang melakukan pelanggaran terhadap ketentuan-ketentuan dalam Peraturan Kepala ini dikenakan sanksi pidana sesuai dengan peraturan perundang-undangan yang berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6257, 'Lembaga Usaha yang melakukan pelanggaran terhadap ketentuan-ketentuan dalam Peraturan Kepala ini dikenakan sanksi pidana sesuai dengan peraturan perundang-undangan yang berlaku.', 'Pasal 27', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 12 Tahun 2014 tentang Peran Serta Lembaga Usaha Dalam Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6258, 'perka-12-2014', 31, 'pasal', 'Pasal 28', 'BAB VII KETENTUAN PENUTUP', 10, 'Peraturan Kepala ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6258, 'Peraturan Kepala ini mulai berlaku pada tanggal diundangkan.
