INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6261, 'perka-13-2008', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka melaksanakan ketentuan pasal 18 Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, perlu dibuat pedoman manajemen logistik dan peralatan penanggulangan bencana.
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana.');
