INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6290, 'perka-13-2010', 1, 'menimbang', 'Menimbang', NULL, 3, 'bahwa untuk melaksanakan ketentuan Pasal 46 dan 51 Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Pencarian, Pertolongan dan Evakuasi;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6290, 'bahwa untuk melaksanakan ketentuan Pasal 46 dan 51 Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Pencarian, Pertolongan dan Evakuasi;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6291, 'perka-13-2010', 2, 'mengingat', 'Mengingat', NULL, 3, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
