INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6293, 'perka-13-2010', 4, 'pasal', 'Pasal 1', NULL, 4, 'Pedoman Pencarian, Pertolongan dan Evakuasi sebagaimana tersebut dalam Lampiran Peraturan ini merupakan pelaksanaan dari Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana yang tidak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6293, 'Pedoman Pencarian, Pertolongan dan Evakuasi sebagaimana tersebut dalam Lampiran Peraturan ini merupakan pelaksanaan dari Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana yang tidak terpisahkan dari Peraturan ini.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6294, 'perka-13-2010', 5, 'pasal', 'Pasal 2', NULL, 4, 'Pedoman Pencarian, Pertolongan dan Evakuasi sebagaimana dimaksud dalam Pasal 1, merupakan acuan bagi Pelaksana pencarian, pertolongan dan evakuasi.');
