INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6297, 'perka-13-2010', 8, 'lain', 'Penutup', NULL, 4, 'Ditetapkan di Jakarta pada tanggal 14 September 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA DR. SYAMSUL MAARIF, M.Si');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6297, 'Ditetapkan di Jakarta pada tanggal 14 September 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA DR. SYAMSUL MAARIF, M.Si', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6298, 'perka-13-2010', 9, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 13 TAHUN 2010 TANGGAL : 14 SEPTEMBER 2010 BAB I PENDAHULUAN A. Latar Belakang Kondisi geologis, geografis, hidrologis, demografis, klimatologis, sosial, budaya, politik, ekonomi dan teknologi menjadikan Indonesia sebagai negara yang rawan bencana, baik bencana alam, bencana non alam, maupun bencana sosial.
Bencana baik dalam skala kecil maupun besar dapat mengakibatkan timbulnya korban jiwa manusia, cacat, luka, hilang, pengungsi, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
Untuk mengurangi dampak bencana terhadap korban, maka perlu upaya penyelamatan melalui pencarian, pertolongan, dan evakuasi.
Dalam upaya penyelamatan tersebut perlu diprioritaskan pada masyarakat terkena bencana yang mengalami luka parah dan kelompok rentan. Terhadap masyarakat terkena bencana yang meninggal dunia dilakukan upaya identifikasi dan pemakaman.
Upaya penyelamatan masyarakat terkena bencana dilaksanakan oleh Tim Reaksi Cepat (TRC) Penanggulangan Bencana yang terdiri dari unsur BNPB/BPBD, BASARNAS/Kantor SAR, Departemen Teknis/Dinas, serta TNI dan POLRI dengan melibatkan unsur masyarakat dibawah komando Komandan Penanganan Darurat Bencana, sesuai dengan lokasi dan tingkatan bencananya. Dalam hal terjadi eskalasi bencana, BNPB dapat memberikan dukungan kepada BPBD untuk melakukan penyelamatan masyarakat terkena bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6298, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 13 TAHUN 2010 TANGGAL : 14 SEPTEMBER 2010 BAB I PENDAHULUAN A. Latar Belakang Kondisi geologis, geografis, hidrologis, demografis, klimatologis, sosial, budaya, politik, ekonomi dan teknologi menjadikan Indonesia sebagai negara yang rawan bencana, baik bencana alam, bencana non alam, maupun bencana sosial.
Bencana baik dalam skala kecil maupun besar dapat mengakibatkan timbulnya korban jiwa manusia, cacat, luka, hilang, pengungsi, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
Untuk mengurangi dampak bencana terhadap korban, maka perlu upaya penyelamatan melalui pencarian, pertolongan, dan evakuasi.
Dalam upaya penyelamatan tersebut perlu diprioritaskan pada masyarakat terkena bencana yang mengalami luka parah dan kelompok rentan. Terhadap masyarakat terkena bencana yang meninggal dunia dilakukan upaya identifikasi dan pemakaman.
Upaya penyelamatan masyarakat terkena bencana dilaksanakan oleh Tim Reaksi Cepat (TRC) Penanggulangan Bencana yang terdiri dari unsur BNPB/BPBD, BASARNAS/Kantor SAR, Departemen Teknis/Dinas, serta TNI dan POLRI dengan melibatkan unsur masyarakat dibawah komando Komandan Penanganan Darurat Bencana, sesuai dengan lokasi dan tingkatan bencananya. Dalam hal terjadi eskalasi bencana, BNPB dapat memberikan dukungan kepada BPBD untuk melakukan penyelamatan masyarakat terkena bencana.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6299, 'perka-13-2010', 10, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'Agar pencarian, pertolongan dan evakuasi korban bencana dapat lebih berhasil guna, perlu disusun suatu pedoman yang dapat digunakan sebagai acuan pemerintah, pemerintah daerah, lembaga usaha dan masyarakat.
B. Maksud dan Tujuan
1. Pedoman ini dimaksudkan sebagai panduan dalam melaksanakan pencarian, pertolongan, dan evakuasi korban bencana secara terkoordinasi, berhasil guna dan berdaya guna, dengan tujuan untuk : Meningkatkan pengerahan sumber daya dalam pencarian, pertolongan, dan evakuasi bagi korban bencana.
2. Menyelamatkan korban bencana secara cepat, tepat, dan dapat dipertanggungjawabkan.
C. Landasan Hukum
1. Undang-Undang Dasar Republik Indonesia Tahun 1945; Pasal 5 ayat (2).
2 Undang-undang Nomor 32 Tahun 2004 Tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844).Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723).
3. Peraturan Pemerintah Republik Indonesia No. 12 Tahun 2000 tentang Pencarian dan Pertolongan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6299, 'Agar pencarian, pertolongan dan evakuasi korban bencana dapat lebih berhasil guna, perlu disusun suatu pedoman yang dapat digunakan sebagai acuan pemerintah, pemerintah daerah, lembaga usaha dan masyarakat.
B. Maksud dan Tujuan
1. Pedoman ini dimaksudkan sebagai panduan dalam melaksanakan pencarian, pertolongan, dan evakuasi korban bencana secara terkoordinasi, berhasil guna dan berdaya guna, dengan tujuan untuk : Meningkatkan pengerahan sumber daya dalam pencarian, pertolongan, dan evakuasi bagi korban bencana.
2. Menyelamatkan korban bencana secara cepat, tepat, dan dapat dipertanggungjawabkan.
C. Landasan Hukum
1. Undang-Undang Dasar Republik Indonesia Tahun 1945; Pasal 5 ayat (2).
2 Undang-undang Nomor 32 Tahun 2004 Tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844).Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723).
3. Peraturan Pemerintah Republik Indonesia No. 12 Tahun 2000 tentang Pencarian dan Pertolongan.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6300, 'perka-13-2010', 11, 'lampiran', 'Lampiran hal. 6', NULL, 6, '4. Peraturan Pemerintah Republik Indonesia No. 36 Tahun 2006 tentang Pencarian dan Pertolongan.
5. Peraturan Pemerintah Republik Indonesia No. 99 Tahun 2007 tentang Badan SAR Nasional.
6. Peraturan Pemerintah Republik Indonesia No. 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
7. Peraturan Pemerintah Republik Indonesia No 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
8. Peraturan Pemerintah Republik Indonesia No 23 Tahun 2008 tentang Peran Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana.
9. Peraturan Presiden Republik Indonesia No. 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
10. Kepmendagri Republik Indonesia Nomor 46 Tahun 2008 tentang Badan Penanggulangan Bencana Daerah.
11. Keputusan Bersama Menteri Kesehatan RI dan Kapolri Nomor 1087/Menkes/SKB/IX/2004 dan Nomor Polisi: Kep/40/IX/2004 tentang Pedoman Pelaksanaan Identifikasi Korban Mati Pada Bencana Massal.
12. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana.
13. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana.
14. Kesepakatan Bersama antara Menteri Kesehatan RI dan Kapolri Nomor 1078/Menkes/SKB/VII/2003 dan Nomor Polisi:
B/3889/VII/2003 tentang Identifikasi Korban Mati Pada Bencana Massal.
D. Pengertian');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6300, '4. Peraturan Pemerintah Republik Indonesia No. 36 Tahun 2006 tentang Pencarian dan Pertolongan.
5. Peraturan Pemerintah Republik Indonesia No. 99 Tahun 2007 tentang Badan SAR Nasional.
6. Peraturan Pemerintah Republik Indonesia No. 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
7. Peraturan Pemerintah Republik Indonesia No 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
8. Peraturan Pemerintah Republik Indonesia No 23 Tahun 2008 tentang Peran Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana.
9. Peraturan Presiden Republik Indonesia No. 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
10. Kepmendagri Republik Indonesia Nomor 46 Tahun 2008 tentang Badan Penanggulangan Bencana Daerah.
11. Keputusan Bersama Menteri Kesehatan RI dan Kapolri Nomor 1087/Menkes/SKB/IX/2004 dan Nomor Polisi: Kep/40/IX/2004 tentang Pedoman Pelaksanaan Identifikasi Korban Mati Pada Bencana Massal.
12. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana.
13. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana.
14. Kesepakatan Bersama antara Menteri Kesehatan RI dan Kapolri Nomor 1078/Menkes/SKB/VII/2003 dan Nomor Polisi:
B/3889/VII/2003 tentang Identifikasi Korban Mati Pada Bencana Massal.
D. Pengertian', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6301, 'perka-13-2010', 12, 'lampiran', 'Lampiran hal. 7', NULL, 7, '1. Mekanisme adalah prosedur pelaksanaan suatu kegiatan yang menyangkut tata kerja TRC terhadap korban bencana pada situasi tanggap darurat.
2. Tim Reaksi Cepat (TRC) adalah tim yang terdiri dari petugas-petugas yang memiliki kualifikasi dalam melakukan, pencarian, pertolongan, dan evakuasi korban bencana, yang terdiri dari unsur BNPB/BPBD, BASARNAS/Kantor SAR, Departemen Teknis/Dinas, serta TNI/POLRI.
3. Triase adalah penetapan prioritas penanganan korban bencana berdasarkan status “sakit” korban.
4. Pencarian adalah kegiatan untuk menemukan korban bencana yang hilang atau dikhawatirkan hilang dalam situasi terjadi bencana atau situasi tanggap darurat
5. Pertolongan adalah kegiatan menolong korban bencana pada saat tanggap darurat.
6. Standar Keselamatan adalah persyaratan pelayanan minimal yang harus dipenuhi dalam pencarian, pertolongan, dan evakuasi korban bencana.
7. Evakuasi adalah kegiatan memindahkan korban bencana dari lokasi bencana ke tempat yang aman dan atau penampungan pertama untuk mendapatkan tindakan penanganan lebih lanjut.
8. Korban bencana adalah orang atau kelompok orang yang menderita atau meninggal dunia akibat bencana.
9. Gawat adalah suatu keadaan karena cedera maupun bukan cedera yang mengancam nyawa korban bencana.
10. Darurat adalah suatu keadaan karena cedera maupun bukan cedera yang membutuhkan pertolongan segera.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6301, '1. Mekanisme adalah prosedur pelaksanaan suatu kegiatan yang menyangkut tata kerja TRC terhadap korban bencana pada situasi tanggap darurat.
2. Tim Reaksi Cepat (TRC) adalah tim yang terdiri dari petugas-petugas yang memiliki kualifikasi dalam melakukan, pencarian, pertolongan, dan evakuasi korban bencana, yang terdiri dari unsur BNPB/BPBD, BASARNAS/Kantor SAR, Departemen Teknis/Dinas, serta TNI/POLRI.
3. Triase adalah penetapan prioritas penanganan korban bencana berdasarkan status “sakit” korban.
4. Pencarian adalah kegiatan untuk menemukan korban bencana yang hilang atau dikhawatirkan hilang dalam situasi terjadi bencana atau situasi tanggap darurat
5. Pertolongan adalah kegiatan menolong korban bencana pada saat tanggap darurat.
6. Standar Keselamatan adalah persyaratan pelayanan minimal yang harus dipenuhi dalam pencarian, pertolongan, dan evakuasi korban bencana.
7. Evakuasi adalah kegiatan memindahkan korban bencana dari lokasi bencana ke tempat yang aman dan atau penampungan pertama untuk mendapatkan tindakan penanganan lebih lanjut.
8. Korban bencana adalah orang atau kelompok orang yang menderita atau meninggal dunia akibat bencana.
9. Gawat adalah suatu keadaan karena cedera maupun bukan cedera yang mengancam nyawa korban bencana.
10. Darurat adalah suatu keadaan karena cedera maupun bukan cedera yang membutuhkan pertolongan segera.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6302, 'perka-13-2010', 13, 'lampiran', 'Lampiran hal. 8', NULL, 8, '11. Gawat darurat adalah suatu keadaan karena cedera maupun bukan cedera yang mengancam nyawa korban bencana dan membutuhkan pertolongan segera.
12. Kelompok Rentan adalah bayi, anak di bawah usia lima tahun, anak-anak, ibu hamil atau menyusui, penyandang cacat dan orang lanjut usia.
13. Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
14. Pemerintah Daerah adalah gubernur, bupati/walikota, atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
15. Lembaga Usaha adalah badan hukum yang dapat berbentuk badan usaha milik negara, badan usaha milik daerah, koperasi, atau swasta yang didirikan sesuai dengan ketentuan perundang-undangan yang menjalankan jenis usaha tetap dan terus menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia.
16. Lembaga Internasional adalah organisasi yang berada dalam lingkup struktur organisasi Perserikatan Bangsa-Bangsa atau yang menjalankan tugas-tugas mewakili Perserikatan Bangsa-Bangsa atau organisasi internasional lainnya dan lembaga asing non pemerintah dari negara lain di luar Perserikatan Bangsa-Bangsa.
17. Masyarakat adalah seluruh warga negara Negara Kesatuan Republik Indonesia yang mempunyai perhatian dan kepedulian terhadap penanggulangan bencana.
E. Prinsip');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6302, '11. Gawat darurat adalah suatu keadaan karena cedera maupun bukan cedera yang mengancam nyawa korban bencana dan membutuhkan pertolongan segera.
12. Kelompok Rentan adalah bayi, anak di bawah usia lima tahun, anak-anak, ibu hamil atau menyusui, penyandang cacat dan orang lanjut usia.
13. Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
14. Pemerintah Daerah adalah gubernur, bupati/walikota, atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
15. Lembaga Usaha adalah badan hukum yang dapat berbentuk badan usaha milik negara, badan usaha milik daerah, koperasi, atau swasta yang didirikan sesuai dengan ketentuan perundang-undangan yang menjalankan jenis usaha tetap dan terus menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia.
16. Lembaga Internasional adalah organisasi yang berada dalam lingkup struktur organisasi Perserikatan Bangsa-Bangsa atau yang menjalankan tugas-tugas mewakili Perserikatan Bangsa-Bangsa atau organisasi internasional lainnya dan lembaga asing non pemerintah dari negara lain di luar Perserikatan Bangsa-Bangsa.
17. Masyarakat adalah seluruh warga negara Negara Kesatuan Republik Indonesia yang mempunyai perhatian dan kepedulian terhadap penanggulangan bencana.
E. Prinsip', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6303, 'perka-13-2010', 14, 'lampiran', 'Lampiran hal. 9', NULL, 9, '1. Cepat dan tepat; bahwa dalam operasi pencarian, pertolongan, dan evakuasi korban bencana dilaksanakan secara cepat dan tepat sesuai dengan tuntutan keadaan.
2. Dapat diandalkan; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana dilakukan oleh TRC yang handal.
3. Prioritas; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana harus diutamakan kepada korban gawat darurat dan kelompok rentan.
4. Koordinasi; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana didasarkan pada pembagian tugas yang jelas dan saling mendukung.
5. Keterpaduan; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana dilaksanakan oleh berbagai sektor secara terpadu yang didasarkan pada kerjasama yang baik dan saling mendukung sesuai dengan peraturan kebencanaan yang ada.
6. Berhasil guna; bahwa dalam kegiatan pencarian, pertolongan, dan evakuasi korban harus berhasil, khususnya dalam mengatasi kesulitan korban bencana dengan tidak membuang waktu, tenaga, dan biaya yang berlebihan.
7. Transparansi; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana dilakukan secara terbuka dan dapat dipertanggung jawabkan.
8. Akuntabilitas; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana dilakukan secara terbuka dan dapat dipertanggung jawabkan secara etik dan hukum.
9. Kemitraan; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana harus melibatkan berbagai pihak secara seimbang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6303, '1. Cepat dan tepat; bahwa dalam operasi pencarian, pertolongan, dan evakuasi korban bencana dilaksanakan secara cepat dan tepat sesuai dengan tuntutan keadaan.
2. Dapat diandalkan; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana dilakukan oleh TRC yang handal.
3. Prioritas; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana harus diutamakan kepada korban gawat darurat dan kelompok rentan.
4. Koordinasi; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana didasarkan pada pembagian tugas yang jelas dan saling mendukung.
5. Keterpaduan; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana dilaksanakan oleh berbagai sektor secara terpadu yang didasarkan pada kerjasama yang baik dan saling mendukung sesuai dengan peraturan kebencanaan yang ada.
6. Berhasil guna; bahwa dalam kegiatan pencarian, pertolongan, dan evakuasi korban harus berhasil, khususnya dalam mengatasi kesulitan korban bencana dengan tidak membuang waktu, tenaga, dan biaya yang berlebihan.
7. Transparansi; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana dilakukan secara terbuka dan dapat dipertanggung jawabkan.
8. Akuntabilitas; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana dilakukan secara terbuka dan dapat dipertanggung jawabkan secara etik dan hukum.
9. Kemitraan; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana harus melibatkan berbagai pihak secara seimbang.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6304, 'perka-13-2010', 15, 'lampiran', 'Lampiran hal. 9', NULL, 9, '10. Pemberdayaan; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana dilakukan dengan melibatkan masyarakat korban bencana secara aktif.
11. Non-diskriminasi; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana tidak memberikan perlakuan yang berbeda terhadap jenis kelamin, suku, agama, ras, aliran politik maupun golongan.
12. Non-proletisi; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana dilarang menyebarkan agama atau keyakinan.
13. Keselamatan; bahwa dalam pencarian, pertolongan, dan evakuasi, keselamatan petugas diutamakan.
F. Ruang Lingkup Pedoman ini meliputi hal-hal yang berkaitan dengan mekanisme pencarian, pertolongan, dan evakuasi korban bencana.
G. Sistematika Pedoman ini disusun dengan sistematika :
BAB I Pendahuluan;
BAB II Kebijakan dan strategi;
BAB III Pengorganisasian;
BAB IV Mekanisme;
BAB V Waktu pencarian, pertolongan, dan evakuasi;
BAB VI Penutup.
BAB II KEBIJAKAN DAN STRATEGI A. Kebijakan
1. Pencarian, pertolongan dan evakuasi korban bencana dilaksanakan secara terpadu dan terkoordinasi yang melibatkan seluruh potensi pemerintah, swasta dan masyarakat.
2. Pelaksanaan pencarian, pertolongan dan evakuasi korban bencana dilakukan dengan memanfaatkan ilmu pengetahuan dan teknologi yang menghargai budaya, adat istiadat, kearifan lokal dan pengetahuan masyarakat setempat;
3. Peranserta lembaga internasional dan lembaga asing non pemerintah bersifat komplementer.
B. Strategi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6304, '10. Pemberdayaan; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana dilakukan dengan melibatkan masyarakat korban bencana secara aktif.
11. Non-diskriminasi; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana tidak memberikan perlakuan yang berbeda terhadap jenis kelamin, suku, agama, ras, aliran politik maupun golongan.
12. Non-proletisi; bahwa dalam pencarian, pertolongan, dan evakuasi korban bencana dilarang menyebarkan agama atau keyakinan.
13. Keselamatan; bahwa dalam pencarian, pertolongan, dan evakuasi, keselamatan petugas diutamakan.
F. Ruang Lingkup Pedoman ini meliputi hal-hal yang berkaitan dengan mekanisme pencarian, pertolongan, dan evakuasi korban bencana.
G. Sistematika Pedoman ini disusun dengan sistematika :
BAB I Pendahuluan;
BAB II Kebijakan dan strategi;
BAB III Pengorganisasian;
BAB IV Mekanisme;
BAB V Waktu pencarian, pertolongan, dan evakuasi;
BAB VI Penutup.
BAB II KEBIJAKAN DAN STRATEGI A. Kebijakan
1. Pencarian, pertolongan dan evakuasi korban bencana dilaksanakan secara terpadu dan terkoordinasi yang melibatkan seluruh potensi pemerintah, swasta dan masyarakat.
2. Pelaksanaan pencarian, pertolongan dan evakuasi korban bencana dilakukan dengan memanfaatkan ilmu pengetahuan dan teknologi yang menghargai budaya, adat istiadat, kearifan lokal dan pengetahuan masyarakat setempat;
3. Peranserta lembaga internasional dan lembaga asing non pemerintah bersifat komplementer.
B. Strategi', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6305, 'perka-13-2010', 16, 'lampiran', 'Lampiran hal. 11', NULL, 11, '1. Membentuk posko kedaruratan dan penetapan Organisasi Komando Penanganan Darurat.
2. Memobilisasi potensi sumber daya.
3. Memberdayakan masyarakat.
4. Mengkoordinasikan peran serta lembaga usaha, lembaga internasional dan lembaga asing non pemerintah dalam pencarian, pertolongan dan evakuasi korban bencana.
BAB III ORGANISASI PELAKSANA
1. Pelaksana pencarian, pertolongan, dan evakuasi korban bencana adalah TRC Penanggulangan Bencana;
2. TRC Penanggulangan Bencana merupakan bagian dari Tim Penanggulangan Bencana Saat Tanggap Darurat, yang terdiri dari unsur BNPB/BPBD, BASARNAS/Kantor SAR, Departemen Teknis/Dinas , TNI dan POLRI.
3. TRC Penanggulangan Bencana Nasional diangkat dan diberhentikan oleh Kepala Badan Nasional Penanggulangan Bencana;
4. TRC Penanggulangan Bencana Provinsi diangkat dan diberhentikan oleh Kepala Badan Penanggulangan Bencana Daerah Provinsi;
5. TRC Penanggulangan Bencana Kabupaten/Kota diangkat dan diberhentikan oleh Kepala Badan Penanggulangan Bencana Daerah Kabupaten/Kota;
6. Berdasarkan Struktur Organisasi Komando Tanggap Darurat Bencana, TRC berada di bawah Bidang Operasi, yang terdiri dari Seksi TRC, Sub Seksi Pencarian, Sub Seksi Pertolongan, dan Sub Seksi Evakuasi.
(Lampiran 1)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6305, '1. Membentuk posko kedaruratan dan penetapan Organisasi Komando Penanganan Darurat.
2. Memobilisasi potensi sumber daya.
3. Memberdayakan masyarakat.
4. Mengkoordinasikan peran serta lembaga usaha, lembaga internasional dan lembaga asing non pemerintah dalam pencarian, pertolongan dan evakuasi korban bencana.
BAB III ORGANISASI PELAKSANA
1. Pelaksana pencarian, pertolongan, dan evakuasi korban bencana adalah TRC Penanggulangan Bencana;
2. TRC Penanggulangan Bencana merupakan bagian dari Tim Penanggulangan Bencana Saat Tanggap Darurat, yang terdiri dari unsur BNPB/BPBD, BASARNAS/Kantor SAR, Departemen Teknis/Dinas , TNI dan POLRI.
3. TRC Penanggulangan Bencana Nasional diangkat dan diberhentikan oleh Kepala Badan Nasional Penanggulangan Bencana;
4. TRC Penanggulangan Bencana Provinsi diangkat dan diberhentikan oleh Kepala Badan Penanggulangan Bencana Daerah Provinsi;
5. TRC Penanggulangan Bencana Kabupaten/Kota diangkat dan diberhentikan oleh Kepala Badan Penanggulangan Bencana Daerah Kabupaten/Kota;
6. Berdasarkan Struktur Organisasi Komando Tanggap Darurat Bencana, TRC berada di bawah Bidang Operasi, yang terdiri dari Seksi TRC, Sub Seksi Pencarian, Sub Seksi Pertolongan, dan Sub Seksi Evakuasi.
(Lampiran 1)', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6306, 'perka-13-2010', 17, 'lampiran', 'Lampiran hal. 12', NULL, 12, '7. Lembaga internasional dan lembaga asing non pemerintah dapat berperan dalam Pencarian, Pertolongan, dan Evakuasi, dengan persetujuan Kepala BNPB, setelah berkoordinasi dengan instansi/lembaga terkait dan dalam operasinya berada di bawah komando Komandan Tanggap Darurat Bencana.
BAB IV MEKANISME PENCARIAN, PERTOLONGAN, DAN EVAKUASI A. Umum
1. Mekanisme pencarian, pertolongan, dan evakuasi korban bencana diselenggarakan dibawah komando Komandan Penanganan Darurat melalui tahapan rencana operasi, permintaan, pengerahan/mobilisasi sumber daya yang didukung dengan kemudahan akses sesuai dengan ketentuan peraturan perundang-undangan yang berlaku. Dalam pelaksanaan dilapangan penyelenggaraan pencarian, pertolongan, dan evakuasi korban bencana sesuai dengan jenis, lokasi, dan tingkatan bencana.
2. Dalam upaya memudahkan pencarian, pertolongan dan evakuasi korban bencana dan harta benda, Kepala BNPB/BPBD mempunyai kewenangan :
a. Menyingkirkan dan/atau memusnahkan barang atau benda dilokasi bencana yang dapat membahayakan jiwa dan dapat mengganggu proses penyelamatan;
b. Memerintahkan orang untuk keluar dari suatu lokasi atau melarang orang untuk memasuki suatu lokasi;
c. Mengisolasi atau menutup suatu lokasi baik milik publik maupun pribadi; dan
d. Memerintahkan kepada pimpinan instansi/lembaga terkait untuk mematikan aliran listrik, gas, atau menutup/membuka pintu air.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6306, '7. Lembaga internasional dan lembaga asing non pemerintah dapat berperan dalam Pencarian, Pertolongan, dan Evakuasi, dengan persetujuan Kepala BNPB, setelah berkoordinasi dengan instansi/lembaga terkait dan dalam operasinya berada di bawah komando Komandan Tanggap Darurat Bencana.
BAB IV MEKANISME PENCARIAN, PERTOLONGAN, DAN EVAKUASI A. Umum
1. Mekanisme pencarian, pertolongan, dan evakuasi korban bencana diselenggarakan dibawah komando Komandan Penanganan Darurat melalui tahapan rencana operasi, permintaan, pengerahan/mobilisasi sumber daya yang didukung dengan kemudahan akses sesuai dengan ketentuan peraturan perundang-undangan yang berlaku. Dalam pelaksanaan dilapangan penyelenggaraan pencarian, pertolongan, dan evakuasi korban bencana sesuai dengan jenis, lokasi, dan tingkatan bencana.
2. Dalam upaya memudahkan pencarian, pertolongan dan evakuasi korban bencana dan harta benda, Kepala BNPB/BPBD mempunyai kewenangan :
a. Menyingkirkan dan/atau memusnahkan barang atau benda dilokasi bencana yang dapat membahayakan jiwa dan dapat mengganggu proses penyelamatan;
b. Memerintahkan orang untuk keluar dari suatu lokasi atau melarang orang untuk memasuki suatu lokasi;
c. Mengisolasi atau menutup suatu lokasi baik milik publik maupun pribadi; dan
d. Memerintahkan kepada pimpinan instansi/lembaga terkait untuk mematikan aliran listrik, gas, atau menutup/membuka pintu air.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6307, 'perka-13-2010', 18, 'lampiran', 'Lampiran hal. 13', NULL, 13, '3. Tim Pencarian, Pertolongan dan Evakuasi merupakan bagian dari Tim Reaksi Cepat Penanggulangan Bencana, yang terdiri atas:
a. Tim pencarian terdiri atas tenaga terlatih dalam bidang pencarian korban bencana dan tenaga medis; serta melibatkan warga masyarakat setempat.
b. Tim penolong terdiri atas tenaga terlatih dalam bidang medis, psikolog, dan pekerja sosial dibantu oleh tenaga relawan; serta warga masyarakat setempat.
c. Tim evakuasi terdiri atas tenaga terlatih dalam bidang evakuasi, tenaga medis, pekerja sosial, dan psikolog; serta warga masyarakat setempat.
4. Tujuan Pencarian, Pertolongan dan Evakuasi :
a. Menemukan lokasi bencana, korban manusia, dan harta benda yang hilang atau yang dikhawatirkan akan hilang akibat bencana.
b. Menolong korban bencana yang sakit akibat bencana.
c. Memindahkan korban dari lokasi bencana ke tempat yang aman.
5. Sasaran
a. Lokasi Bencana. Dalam Pencarian, Pertolongan dan Evakuasi memerlukan kejelasan lokasi bencana, kondisi medan bencana dan tempat evakuasi.
b. Korban Bencana. Dalam hal ini di prioritaskan bagi korban bencana yang masih hidup, luka-luka dan kelompok rentan serta yang meninggal dunia.
B. Mekanisme
1. Pencarian Kegiatan pencarian dilakukan dengan langkah-langkah :
a. Tim pencarian menuju lokasi bencana setelah mendapat informasi kejadian bencana dan mendapat komando dari komandan tanggap darurat.
b. Memetakan kondisi cuaca, geografis, topografis, dan keadaan awal akibat bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6307, '3. Tim Pencarian, Pertolongan dan Evakuasi merupakan bagian dari Tim Reaksi Cepat Penanggulangan Bencana, yang terdiri atas:
a. Tim pencarian terdiri atas tenaga terlatih dalam bidang pencarian korban bencana dan tenaga medis; serta melibatkan warga masyarakat setempat.
b. Tim penolong terdiri atas tenaga terlatih dalam bidang medis, psikolog, dan pekerja sosial dibantu oleh tenaga relawan; serta warga masyarakat setempat.
c. Tim evakuasi terdiri atas tenaga terlatih dalam bidang evakuasi, tenaga medis, pekerja sosial, dan psikolog; serta warga masyarakat setempat.
4. Tujuan Pencarian, Pertolongan dan Evakuasi :
a. Menemukan lokasi bencana, korban manusia, dan harta benda yang hilang atau yang dikhawatirkan akan hilang akibat bencana.
b. Menolong korban bencana yang sakit akibat bencana.
c. Memindahkan korban dari lokasi bencana ke tempat yang aman.
5. Sasaran
a. Lokasi Bencana. Dalam Pencarian, Pertolongan dan Evakuasi memerlukan kejelasan lokasi bencana, kondisi medan bencana dan tempat evakuasi.
b. Korban Bencana. Dalam hal ini di prioritaskan bagi korban bencana yang masih hidup, luka-luka dan kelompok rentan serta yang meninggal dunia.
B. Mekanisme
1. Pencarian Kegiatan pencarian dilakukan dengan langkah-langkah :
a. Tim pencarian menuju lokasi bencana setelah mendapat informasi kejadian bencana dan mendapat komando dari komandan tanggap darurat.
b. Memetakan kondisi cuaca, geografis, topografis, dan keadaan awal akibat bencana;', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6308, 'perka-13-2010', 19, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'c. Menentukan lokasi bencana dan luas dampak bencana serta mengadakan pembagian daerah pencarian, dengan membuat batasan lokasi bencana berdasarkan klasifikasi tiga wilayah penanggulangan:
1) Ring I yaitu daerah tempat terjadinya bencana, kemungkinan ditemukan korban paling banyak dan bahaya, serta kemungkinan munculnya bencana susulan;
2) Ring II yaitu daerah sekitar terjadinya bencana yang masih dimungkinkan ditemukan korban;
3) Ring III yaitu daerah yang relatif aman untuk dijadikan tempat evakuasi sementara.
d. Memetakan kondisi serta jumlah korban : korban selamat, dan korban sakit. Pemetaan kondisi korban sakit menggunakan triase empat tingkat yaitu : (1) hijau, tidak gawat tidak darurat,
(2) kuning, gawat tidak darurat, (3) merah, gawat darurat, (4) hitam, meninggal dunia. Untuk kepentingan penyelidikan dan penyidikan perlu dilakukan identifikasi korban oleh pihak yang berwenang , terutama bagi korban bencana tertentu.
(Misalnya: terorisme, kegagalan teknologi, dan lain-lain).
e. Mengidentifikasi dan mengantisipasi kebutuhan yang diperlukan dalam pertolongan dan evakuasi korban bencana.
f. Mengidentifikasi sumberdaya lokal dan potensi risiko sekunder bagi keselamatan korban dan penolong.
g. Melaporkan kegiatan pencarian secara berkala per 3 jam atau per 6 jam atau sesuai kondisi. (Lampiran 2)
2. Pertolongan Kegiatan pertolongan dilakukan dengan langkah-langkah:
a. Tim menyusun rencana pertolongan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6308, 'c. Menentukan lokasi bencana dan luas dampak bencana serta mengadakan pembagian daerah pencarian, dengan membuat batasan lokasi bencana berdasarkan klasifikasi tiga wilayah penanggulangan:
1) Ring I yaitu daerah tempat terjadinya bencana, kemungkinan ditemukan korban paling banyak dan bahaya, serta kemungkinan munculnya bencana susulan;
2) Ring II yaitu daerah sekitar terjadinya bencana yang masih dimungkinkan ditemukan korban;
3) Ring III yaitu daerah yang relatif aman untuk dijadikan tempat evakuasi sementara.
d. Memetakan kondisi serta jumlah korban : korban selamat, dan korban sakit. Pemetaan kondisi korban sakit menggunakan triase empat tingkat yaitu : (1) hijau, tidak gawat tidak darurat,
(2) kuning, gawat tidak darurat, (3) merah, gawat darurat, (4) hitam, meninggal dunia. Untuk kepentingan penyelidikan dan penyidikan perlu dilakukan identifikasi korban oleh pihak yang berwenang , terutama bagi korban bencana tertentu.
(Misalnya: terorisme, kegagalan teknologi, dan lain-lain).
e. Mengidentifikasi dan mengantisipasi kebutuhan yang diperlukan dalam pertolongan dan evakuasi korban bencana.
f. Mengidentifikasi sumberdaya lokal dan potensi risiko sekunder bagi keselamatan korban dan penolong.
g. Melaporkan kegiatan pencarian secara berkala per 3 jam atau per 6 jam atau sesuai kondisi. (Lampiran 2)
2. Pertolongan Kegiatan pertolongan dilakukan dengan langkah-langkah:
a. Tim menyusun rencana pertolongan;', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6309, 'perka-13-2010', 20, 'lampiran', 'Lampiran hal. 15', NULL, 15, 'b. Tim penolong menuju lokasi bencana bersama tim pencarian dengan terlebih dahulu mempelajari batasan klasifikasi tiga wilayah penanggulangan yang telah ditetapkan oleh Tim Pencarian;
c. Memberikan pertolongan pertama kepada korban bencana di tempat kejadian;
d. Pengobatan sementara kepada korban bencana di tempat kejadian;
e. Melakukan rujukan bagi korban yang memerlukan tindakan lebih lanjut;
f. Melaporkan kegiatan pertolongan secara berkala per 3 jam atau per 6 jam atau sesuai kondisi. (Lampiran 3)
3. Evakuasi Kegiatan evakuasi dilakukan dengan langkah-langkah:
a. Tim evakuasi menuju lokasi bencana bersama tim pencarian dan tim penolong;
b. Memindahkan korban bencana keluar dari sumber bencana ke tempat yang lebih aman untuk mendapat tindakan selanjutnya;
c. Memberikan pengobatan sementara kepada korban bencana selama dalam perjalanan;
d. Memberikan dukungan sosial dan psikologis kepada korban bencana;
e. Melaporkan kegiatan evakuasi secara berkala per 3 jam atau per 6 jam atau sesuai kondisi. (Lampiran 4) C. Fasilitas Fasilitas yang dibutuhkan dalam pencarian, pertolongan dan evakuasi terdiri atas perlengkapan tim dan perlengkapan pribadi. (lampiran 5) BAB V WAKTU PENCARIAN, PERTOLONGAN, DAN EVAKUASI
1. Pencarian dan pertolongan terhadap korban bencana dihentikan jika seluruh korban telah ditemukan, ditolong dan dievakuasi. Atau setelah jangka waktu 7 (tujuh) hari sejak dimulainya pencarian, tidak ada tanda-tanda korban akan ditemukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6309, 'b. Tim penolong menuju lokasi bencana bersama tim pencarian dengan terlebih dahulu mempelajari batasan klasifikasi tiga wilayah penanggulangan yang telah ditetapkan oleh Tim Pencarian;
c. Memberikan pertolongan pertama kepada korban bencana di tempat kejadian;
d. Pengobatan sementara kepada korban bencana di tempat kejadian;
e. Melakukan rujukan bagi korban yang memerlukan tindakan lebih lanjut;
f. Melaporkan kegiatan pertolongan secara berkala per 3 jam atau per 6 jam atau sesuai kondisi. (Lampiran 3)
3. Evakuasi Kegiatan evakuasi dilakukan dengan langkah-langkah:
a. Tim evakuasi menuju lokasi bencana bersama tim pencarian dan tim penolong;
b. Memindahkan korban bencana keluar dari sumber bencana ke tempat yang lebih aman untuk mendapat tindakan selanjutnya;
c. Memberikan pengobatan sementara kepada korban bencana selama dalam perjalanan;
d. Memberikan dukungan sosial dan psikologis kepada korban bencana;
e. Melaporkan kegiatan evakuasi secara berkala per 3 jam atau per 6 jam atau sesuai kondisi. (Lampiran 4) C. Fasilitas Fasilitas yang dibutuhkan dalam pencarian, pertolongan dan evakuasi terdiri atas perlengkapan tim dan perlengkapan pribadi. (lampiran 5) BAB V WAKTU PENCARIAN, PERTOLONGAN, DAN EVAKUASI
1. Pencarian dan pertolongan terhadap korban bencana dihentikan jika seluruh korban telah ditemukan, ditolong dan dievakuasi. Atau setelah jangka waktu 7 (tujuh) hari sejak dimulainya pencarian, tidak ada tanda-tanda korban akan ditemukan.', 'Lampiran hal. 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2010 tentang Pedoman Pencarian, Pertolongan dan Evakuasi');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6310, 'perka-13-2010', 21, 'lampiran', 'Lampiran hal. 17', NULL, 17, '2. Penghentian pencarian dan pertolongan korban bencana, dapat dibuka kembali dengan pertimbangan adanya informasi baru mengenai indikasi keberadaan korban bencana.
