INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6314, 'perka-13-2014', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa penanggulangan bencana wajib memperhatikan prinsip-prinsip kemanusiaan dan keadilan agar dapat melindungi dan memenuhi hak-hak warga negara dalam setiap aspek penyelenggaraan penanggulangan bencana;
b. bahwa berbagai peraturan perundang-undangan yang mengatur pengarusutamaan gender telah dibentuk namun peraturan perundang-undangan terkait pengarusutamaan gender di bidang penanggulangan bencana belum ada;
c. bahwa penyelenggaraan penanggulangan bencana yang responsif gender perlu dilaksanakan untuk memastikan pemenuhan hak-hak dan kebutuhan laki-laki dan perempuan secara adil dan manusiawi;
d. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b dan huruf c, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana;');
