INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6316, 'perka-13-2014', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENGARUSUTAMAAN GENDER DI BIDANG PENANGGULANGAN BENCANA');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6316, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENGARUSUTAMAAN GENDER DI BIDANG PENANGGULANGAN BENCANA', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6317, 'perka-13-2014', 4, 'pasal', 'Pasal 1', 'BAB II MAKSUD, TUJUAN DAN LINGKUP PENGATURAN; Bagian Kesatu Maksud dan Tujuan', 3, 'Dalam Peraturan Kepala BNPB ini yang dimaksud dengan:
1. Pengarusutamaan gender adalah strategi yang dibangun untuk mengintegrasikan gender menjadi suatu dimensi terpadu dari perencanaan, penyusunan, pelaksanaan, pemantauan, dan pengendalian kebijakan dan program pembangunan nasional.
2. Gender adalah konsep yang mengacu pada pembedaan peran, atribut, sifat, sikap tindak atau perilaku, yang tumbuh dan berkembang dalam masyarakat atau yang dianggap masyarakat pantas untuk laki-laki dan perempuan.
3. Kesetaraan Gender adalah kesamaan kondisi bagi laki-laki dan perempuan untuk memperoleh kesempatan dan hak-haknya sebagai manusia, agar mampu berperan dan berpartisipasi dalam kegiatan politik, ekonomi, sosial budaya, pertahanan dan keamanan, dan kesamaan dalam menikmati hasil pembangunan.
4. Keadilan Gender adalah suatu proses untuk menjadi adil terhadap laki-laki dan perempuan.
5. Analisis gender adalah proses analisis data gender secara sistematis tentang kondisi laki-laki dan perempuan khususnya berkaitan dengan tingkat akses, partisipasi, kontrol dan perolehan manfaat dalam proses pembangunan untuk mengungkapkan akar permasalahan terjadinya ketimpangan kedudukan, fungsi, peran dan tanggung jawab antara laki-laki dan perempuan.
6. Responsif Gender adalah perhatian yang konsisten dan sistematis terhadap perbedaan-perbedaan perempuan dan laki-laki di dalam masyarakat yang disertai upaya menghapus hambatan-hambatan struktural dan kultural dalam mencapai kesetaraan gender.
2014, No.1604 4
7. Perencanaan Responsif Gender adalah perencanaan untuk mencapai kesetaraan dan keadilan gender, yang dilakukan melalui pengintegrasian pengalaman, aspirasi, kebutuhan, potensi, dan penyelesaian permasalahan perempuan dan laki-laki.
8. Perencanaan dan Penganggaran Responsif Gender yang selanjutnya disingkat PPRG adalah instrumen untuk mengatasi adanya perbedaan akses, partisipasi, kontrol dan manfaat pembangunan bagi laki-laki dan perempuan dengan tujuan untuk mewujudkan anggaran yang lebih berkeadilan.
9. Anggaran Responsif Gender yang selanjutnya disingkat ARG adalah anggaran yang respons terhadap kebutuhan perempuan dan laki-laki yang tujuannya untuk mewujudkan kesetaraan dan keadilan gender.
10. Gender Budget Statement yang selanjutnya disingkat GBS adalah dokumen pertanggungjawaban spesifik gender yang disusun pemerintah yang menunjukkan kesediaan instansi untuk melakukan kegiatan berdasarkan kesetaraan gender dan mengalokasikan anggaran untuk kegiatan-kegiatan tersebut.
11. Focal Point PUG, yang selanjutnya disebut Penggerak PUG, adalah aparatur kementerian/lembaga dan/atau SKPD yang mempunyai kemampuan dan ditunjuk untuk melakukan pengarusutamaan gender di unit kerjanya masing-masing.
12. Kelompok Kerja Pengarustamaan Gender yang selanjutnya disebut Pokja PUG adalah wadah konsultasi bagi pelaksana dan penggerak pengarustamaan gender dari berbagai instansi/lembaga di daerah.
13. Data terpilah adalah nilai hasil pengamatan/pengukuran suatu variabel yang telah dikelompokkan menurut berbagai ciri, seperti jenis kelamin, wilayah, status sosial ekonomi, dan waktu.
14. Kebutuhan khusus gender adalah kebutuhan praktis yang muncul akibat adanya pembedaan peran sosial dan domestik yang diharapkan dari perempuan dan laki-laki.
15. Kekerasan berbasis gender adalah tindakan kekerasan yang ditujukan pada individu atau sekelompok perempuan dan laki-laki akibat kesenjangan dalam relasi gender.
16. Kesenjangan gender adalah suatu kondisi ketika perempuan atau laki-laki tidak dapat menerima akses, partisipasi, kontrol dan manfaat pembangunan secara adil.
17. Penyintas adalah seseorang yang berhasil bertahan hidup setelah mengalami kejadian bencana atau guncangan lainnya.
5 2014, No.1604');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6317, 'Dalam Peraturan Kepala BNPB ini yang dimaksud dengan:
1. Pengarusutamaan gender adalah strategi yang dibangun untuk mengintegrasikan gender menjadi suatu dimensi terpadu dari perencanaan, penyusunan, pelaksanaan, pemantauan, dan pengendalian kebijakan dan program pembangunan nasional.
2. Gender adalah konsep yang mengacu pada pembedaan peran, atribut, sifat, sikap tindak atau perilaku, yang tumbuh dan berkembang dalam masyarakat atau yang dianggap masyarakat pantas untuk laki-laki dan perempuan.
3. Kesetaraan Gender adalah kesamaan kondisi bagi laki-laki dan perempuan untuk memperoleh kesempatan dan hak-haknya sebagai manusia, agar mampu berperan dan berpartisipasi dalam kegiatan politik, ekonomi, sosial budaya, pertahanan dan keamanan, dan kesamaan dalam menikmati hasil pembangunan.
4. Keadilan Gender adalah suatu proses untuk menjadi adil terhadap laki-laki dan perempuan.
5. Analisis gender adalah proses analisis data gender secara sistematis tentang kondisi laki-laki dan perempuan khususnya berkaitan dengan tingkat akses, partisipasi, kontrol dan perolehan manfaat dalam proses pembangunan untuk mengungkapkan akar permasalahan terjadinya ketimpangan kedudukan, fungsi, peran dan tanggung jawab antara laki-laki dan perempuan.
6. Responsif Gender adalah perhatian yang konsisten dan sistematis terhadap perbedaan-perbedaan perempuan dan laki-laki di dalam masyarakat yang disertai upaya menghapus hambatan-hambatan struktural dan kultural dalam mencapai kesetaraan gender.
2014, No.1604 4
7. Perencanaan Responsif Gender adalah perencanaan untuk mencapai kesetaraan dan keadilan gender, yang dilakukan melalui pengintegrasian pengalaman, aspirasi, kebutuhan, potensi, dan penyelesaian permasalahan perempuan dan laki-laki.
8. Perencanaan dan Penganggaran Responsif Gender yang selanjutnya disingkat PPRG adalah instrumen untuk mengatasi adanya perbedaan akses, partisipasi, kontrol dan manfaat pembangunan bagi laki-laki dan perempuan dengan tujuan untuk mewujudkan anggaran yang lebih berkeadilan.
9. Anggaran Responsif Gender yang selanjutnya disingkat ARG adalah anggaran yang respons terhadap kebutuhan perempuan dan laki-laki yang tujuannya untuk mewujudkan kesetaraan dan keadilan gender.
10. Gender Budget Statement yang selanjutnya disingkat GBS adalah dokumen pertanggungjawaban spesifik gender yang disusun pemerintah yang menunjukkan kesediaan instansi untuk melakukan kegiatan berdasarkan kesetaraan gender dan mengalokasikan anggaran untuk kegiatan-kegiatan tersebut.
11. Focal Point PUG, yang selanjutnya disebut Penggerak PUG, adalah aparatur kementerian/lembaga dan/atau SKPD yang mempunyai kemampuan dan ditunjuk untuk melakukan pengarusutamaan gender di unit kerjanya masing-masing.
12. Kelompok Kerja Pengarustamaan Gender yang selanjutnya disebut Pokja PUG adalah wadah konsultasi bagi pelaksana dan penggerak pengarustamaan gender dari berbagai instansi/lembaga di daerah.
13. Data terpilah adalah nilai hasil pengamatan/pengukuran suatu variabel yang telah dikelompokkan menurut berbagai ciri, seperti jenis kelamin, wilayah, status sosial ekonomi, dan waktu.
14. Kebutuhan khusus gender adalah kebutuhan praktis yang muncul akibat adanya pembedaan peran sosial dan domestik yang diharapkan dari perempuan dan laki-laki.
15. Kekerasan berbasis gender adalah tindakan kekerasan yang ditujukan pada individu atau sekelompok perempuan dan laki-laki akibat kesenjangan dalam relasi gender.
16. Kesenjangan gender adalah suatu kondisi ketika perempuan atau laki-laki tidak dapat menerima akses, partisipasi, kontrol dan manfaat pembangunan secara adil.
17. Penyintas adalah seseorang yang berhasil bertahan hidup setelah mengalami kejadian bencana atau guncangan lainnya.
5 2014, No.1604', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6318, 'perka-13-2014', 5, 'pasal', 'Pasal 2', 'BAB II MAKSUD, TUJUAN DAN LINGKUP PENGATURAN; Bagian Kedua Lingkup Pengaturan', 5, '(1) Peraturan Kepala BNPB ini disusun sebagai pedoman bagi Pemerintah, pemerintah daerah dan pihak non-pemerintah dalam melaksanakan pengarusutamaan gender di bidang penanggulangan bencana.
(2) Peraturan Kepala BNPB ini bertujuan untuk:
a. melaksanakan prinsip-prinsip keadilan dan kesetaraan gender dalam setiap komponen penyelenggaraan penanggulangan bencana;
b. mendorong pengarusutamaan gender dengan menyusun perencanaan dan penganggaran responsif gender dalam penanggulangan bencana;
c. mendorong terwujudnya perlindungan dan pemenuhan hak-hak perempuan dan laki-laki dalam penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6318, '(1) Peraturan Kepala BNPB ini disusun sebagai pedoman bagi Pemerintah, pemerintah daerah dan pihak non-pemerintah dalam melaksanakan pengarusutamaan gender di bidang penanggulangan bencana.
(2) Peraturan Kepala BNPB ini bertujuan untuk:
a. melaksanakan prinsip-prinsip keadilan dan kesetaraan gender dalam setiap komponen penyelenggaraan penanggulangan bencana;
b. mendorong pengarusutamaan gender dengan menyusun perencanaan dan penganggaran responsif gender dalam penanggulangan bencana;
c. mendorong terwujudnya perlindungan dan pemenuhan hak-hak perempuan dan laki-laki dalam penanggulangan bencana.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6319, 'perka-13-2014', 6, 'pasal', 'Pasal 3', 'BAB III PENYELENGGARAAN PENGARUSUTAMAAN GENDER; Bagian Kesatu Indikator', 5, 'Ruang lingkup Peraturan Kepala BNPB ini meliputi pengarusutamaan gender dalam penanggulangan bencana, baik pada saat pra-bencana, tanggap darurat maupun pasca-bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6319, 'Ruang lingkup Peraturan Kepala BNPB ini meliputi pengarusutamaan gender dalam penanggulangan bencana, baik pada saat pra-bencana, tanggap darurat maupun pasca-bencana.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6320, 'perka-13-2014', 7, 'pasal', 'Pasal 4', 'BAB III PENYELENGGARAAN PENGARUSUTAMAAN GENDER; Bagian Kedua Perencanaan dan Penganggaran Responsif Gender', 5, 'Pengarusutamaan gender di bidang penanggulangan bencana dilaksanakan dengan menggunakan indikator dalam empat aspek yaitu:
a. akses;
b. partisipasi;
c. kontrol terhadap sumber daya dan pengambilan keputusan; dan
d. manfaat dari kebijakan dan program.
2014, No.1604 6');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6320, 'Pengarusutamaan gender di bidang penanggulangan bencana dilaksanakan dengan menggunakan indikator dalam empat aspek yaitu:
a. akses;
b. partisipasi;
c. kontrol terhadap sumber daya dan pengambilan keputusan; dan
d. manfaat dari kebijakan dan program.
2014, No.1604 6', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6321, 'perka-13-2014', 8, 'pasal', 'Pasal 5', 'BAB III PENYELENGGARAAN PENGARUSUTAMAAN GENDER; Bagian Kedua Perencanaan dan Penganggaran Responsif Gender', 6, '(1) Perencanaan kebijakan, program dan kegiatan penanggulangan bencana responsif gender tertuang dalam Rencana Strategis dan Rencana Kerja Pemerintah dan pemerintah daerah serta mengacu pada Rencana Pembangunan Jangka Menengah Pemerintah dan pemerintah daerah.
(2) Penyusunan kebijakan, program dan kegiatan penanggulangan bencana responsif gender dilakukan berdasarkan analisis gender.
(3) Analisis gender sebagaimana dimaksud pada ayat (2) menggunakan:
a. data terpilah; dan
b. Metode Alur Kerja Analisis Gender (Gender Analysis Pathway) atau metode analisis lain yang sesuai.
(4) Pelaksanaan analisis gender sebagaimana dimaksud pada ayat (2) dapat dilakukan oleh pihak luar yang berkompeten.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6321, '(1) Perencanaan kebijakan, program dan kegiatan penanggulangan bencana responsif gender tertuang dalam Rencana Strategis dan Rencana Kerja Pemerintah dan pemerintah daerah serta mengacu pada Rencana Pembangunan Jangka Menengah Pemerintah dan pemerintah daerah.
(2) Penyusunan kebijakan, program dan kegiatan penanggulangan bencana responsif gender dilakukan berdasarkan analisis gender.
(3) Analisis gender sebagaimana dimaksud pada ayat (2) menggunakan:
a. data terpilah; dan
b. Metode Alur Kerja Analisis Gender (Gender Analysis Pathway) atau metode analisis lain yang sesuai.
(4) Pelaksanaan analisis gender sebagaimana dimaksud pada ayat (2) dapat dilakukan oleh pihak luar yang berkompeten.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6322, 'perka-13-2014', 9, 'pasal', 'Pasal 6', 'BAB III PENYELENGGARAAN PENGARUSUTAMAAN GENDER; Bagian Ketiga Pendanaan', 6, '(1) Perencanaan responsif gender sebagaimana dimaksud dalam pasal 5 menghasilkan Anggaran Responsif Gender.
(2) Anggaran Responsif Gender sebagaimana dimaksud pada ayat (1) harus dapat:
a. mengatasi masalah kesenjangan antara perempuan dan laki-laki dalam akses, partisipasi, manfaat dan kontrol terhadap sumber daya;
b. memperkuat pelembagaan pengarusutamaan gender, baik dalam hal pendataan maupun peningkatan kapasitas sumber daya manusia; dan
c. memenuhi kebutuhan dasar khusus perempuan dan/atau kebutuhan dasar khusus laki-laki berdasarkan analisis gender.
(3) Anggaran Responsif Gender sebagaimana yang dimaksud pada ayat (1) didokumentasikan dalam bentuk Gender Budget Statement.
(4) Gender Budget Statement sebagaimana yang dimaksud pada ayat (3) dilampirkan pada saat mengajukan rencana kerja dan anggaran.
7 2014, No.1604');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6322, '(1) Perencanaan responsif gender sebagaimana dimaksud dalam pasal 5 menghasilkan Anggaran Responsif Gender.
(2) Anggaran Responsif Gender sebagaimana dimaksud pada ayat (1) harus dapat:
a. mengatasi masalah kesenjangan antara perempuan dan laki-laki dalam akses, partisipasi, manfaat dan kontrol terhadap sumber daya;
b. memperkuat pelembagaan pengarusutamaan gender, baik dalam hal pendataan maupun peningkatan kapasitas sumber daya manusia; dan
c. memenuhi kebutuhan dasar khusus perempuan dan/atau kebutuhan dasar khusus laki-laki berdasarkan analisis gender.
(3) Anggaran Responsif Gender sebagaimana yang dimaksud pada ayat (1) didokumentasikan dalam bentuk Gender Budget Statement.
(4) Gender Budget Statement sebagaimana yang dimaksud pada ayat (3) dilampirkan pada saat mengajukan rencana kerja dan anggaran.
7 2014, No.1604', 'Pasal 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6323, 'perka-13-2014', 10, 'pasal', 'Pasal 7', 'BAB III PENYELENGGARAAN PENGARUSUTAMAAN GENDER; Bagian Keempat Pelaksanaan', 7, '(1) Pendanaan pelaksanaan program dan kegiatan pengarusutamaan gender di bidang penanggulangan bencana bersumber dari Anggaran Pendapatan dan Belanja Negara dan Anggaran Pendapatan dan Belanja Daerah.
(2) Pendanaan pelaksanaan program dan kegiatan pengarusutamaan gender di bidang penanggulangan bencana dapat bersumber dari pihak lain yang sah dan tidak mengikat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6323, '(1) Pendanaan pelaksanaan program dan kegiatan pengarusutamaan gender di bidang penanggulangan bencana bersumber dari Anggaran Pendapatan dan Belanja Negara dan Anggaran Pendapatan dan Belanja Daerah.
(2) Pendanaan pelaksanaan program dan kegiatan pengarusutamaan gender di bidang penanggulangan bencana dapat bersumber dari pihak lain yang sah dan tidak mengikat.', 'Pasal 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6324, 'perka-13-2014', 11, 'pasal', 'Pasal 8', 'BAB III PENYELENGGARAAN PENGARUSUTAMAAN GENDER; Bagian Keempat Pelaksanaan', 7, '(1) Dalam upaya percepatan pelembagaan pengarusutamaan gender, di lingkungan BNPB dan BPBD dibentuk Pokja PUG di lingkungan masing-masing.
(2) Struktur, keanggotaan dan masa tugas Pokja PUG di lingkungan BNPB ditetapkan dengan Surat Keputusan Sekretaris Utama.
(3) Struktur, keanggotaan dan masa tugas Pokja PUG di lingkungan BPBD ditetapkan dengan Surat Keputusan Kepala BPBD.
(4) Pokja PUG sebagaimana dimaksud pada ayat (1) mempunyai tugas:
a. mempromosikan dan memfasilitasi PUG di bidang penanggulangan bencana;
b. melaksanakan sosialisasi dan advokasi PUG di bidang penanggulangan bencana;
c. mendorong terwujudnya perencanaan dan penganggaran yang responsif gender di bidang penanggulangan bencana;
d. menyusun rencana kerja Pokja PUG setiap tahun;
e. merumuskan rekomendasi kebijakan;
f. menyusun Profil Gender di bidang penanggulangan bencana;
g. melakukan pemantauan pelaksanaan PUG; dan
h. mendorong dilaksanakannya pemilihan dan penetapan Penggerak PUG.
2014, No.1604 8');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6324, '(1) Dalam upaya percepatan pelembagaan pengarusutamaan gender, di lingkungan BNPB dan BPBD dibentuk Pokja PUG di lingkungan masing-masing.
(2) Struktur, keanggotaan dan masa tugas Pokja PUG di lingkungan BNPB ditetapkan dengan Surat Keputusan Sekretaris Utama.
(3) Struktur, keanggotaan dan masa tugas Pokja PUG di lingkungan BPBD ditetapkan dengan Surat Keputusan Kepala BPBD.
(4) Pokja PUG sebagaimana dimaksud pada ayat (1) mempunyai tugas:
a. mempromosikan dan memfasilitasi PUG di bidang penanggulangan bencana;
b. melaksanakan sosialisasi dan advokasi PUG di bidang penanggulangan bencana;
c. mendorong terwujudnya perencanaan dan penganggaran yang responsif gender di bidang penanggulangan bencana;
d. menyusun rencana kerja Pokja PUG setiap tahun;
e. merumuskan rekomendasi kebijakan;
f. menyusun Profil Gender di bidang penanggulangan bencana;
g. melakukan pemantauan pelaksanaan PUG; dan
h. mendorong dilaksanakannya pemilihan dan penetapan Penggerak PUG.
2014, No.1604 8', 'Pasal 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6325, 'perka-13-2014', 12, 'pasal', 'Pasal 9', 'BAB III PENYELENGGARAAN PENGARUSUTAMAAN GENDER; Bagian Keempat Pelaksanaan', 8, '(1) Penggerak PUG di BNPB adalah pejabat dan/atau staf yang membidangi tugas perencanaan dan/atau program.
(2) Penggerak PUG sebagaimana dimaksud pada ayat (1) menjabat sebagai Koordinator Pokja PUG.
(3) Penggerak PUG sebagaimana dimaksud pada ayat (1) ditetapkan dengan Surat Keputusan Sekretaris Utama.
(4) Penggerak PUG sebagaimana dimaksud pada ayat (1) mempunyai tugas:
a. mengkoordinasikan Perencanaan dan Penganggaran Responsif Gender di lingkungan BNPB;
b. memfasilitasi pelaksanaan analisis gender terhadap kebijakan, program, dan kegiatan pada masing-masing unit kerja;
c. melaporkan pelaksanaan PUG kepada pimpinan BNPB;
d. melaksanakan pelatihan, sosialisasi dan advokasi pengarusutamaan gender kepada seluruh pejabat dan staf di lingkungan BNPB; dan
f. memfasilitasi penyusunan data gender pada masing-masing unit kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6325, '(1) Penggerak PUG di BNPB adalah pejabat dan/atau staf yang membidangi tugas perencanaan dan/atau program.
(2) Penggerak PUG sebagaimana dimaksud pada ayat (1) menjabat sebagai Koordinator Pokja PUG.
(3) Penggerak PUG sebagaimana dimaksud pada ayat (1) ditetapkan dengan Surat Keputusan Sekretaris Utama.
(4) Penggerak PUG sebagaimana dimaksud pada ayat (1) mempunyai tugas:
a. mengkoordinasikan Perencanaan dan Penganggaran Responsif Gender di lingkungan BNPB;
b. memfasilitasi pelaksanaan analisis gender terhadap kebijakan, program, dan kegiatan pada masing-masing unit kerja;
c. melaporkan pelaksanaan PUG kepada pimpinan BNPB;
d. melaksanakan pelatihan, sosialisasi dan advokasi pengarusutamaan gender kepada seluruh pejabat dan staf di lingkungan BNPB; dan
f. memfasilitasi penyusunan data gender pada masing-masing unit kerja.', 'Pasal 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6326, 'perka-13-2014', 13, 'pasal', 'Pasal 10', 'BAB III PENYELENGGARAAN PENGARUSUTAMAAN GENDER; Bagian Kelima Pemantauan, Evaluasi dan Pelaporan', 8, '(1) BNPB bekerjasama dengan Kementerian yang membidangi pemberdayaan perempuan dan perlindungan anak melakukan koordinasi dengan Kementerian Dalam Negeri dan Kementerian dan/atau Lembaga negara non-kementerian terkait untuk menyelaraskan rencana dan pelaksanaan program pengarusutamaan gender di bidang penanggulangan bencana di tingkat nasional.
(2) BPBD bekerjasama dengan SKPD yang membidangi pemberdayaan perempuan dan perlindungan anak menyelaraskan rencana dan pelaksanaan program pengarusutamaan gender di bidang penanggulangan bencana di tingkat daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6326, '(1) BNPB bekerjasama dengan Kementerian yang membidangi pemberdayaan perempuan dan perlindungan anak melakukan koordinasi dengan Kementerian Dalam Negeri dan Kementerian dan/atau Lembaga negara non-kementerian terkait untuk menyelaraskan rencana dan pelaksanaan program pengarusutamaan gender di bidang penanggulangan bencana di tingkat nasional.
(2) BPBD bekerjasama dengan SKPD yang membidangi pemberdayaan perempuan dan perlindungan anak menyelaraskan rencana dan pelaksanaan program pengarusutamaan gender di bidang penanggulangan bencana di tingkat daerah.', 'Pasal 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6327, 'perka-13-2014', 14, 'pasal', 'Pasal 11', 'BAB IV PENGARUSUTAMAAN GENDER SAAT PRA-BENCANA; Bagian Kesatu Kajian Risiko Bencana Responsif Gender', 8, '(1) BNPB bekerjasama dengan kementerian yang membidangi pemberdayaan perempuan dan perlindungan anak melakukan 9 2014, No.1604 koordinasi dengan Kementerian Dalam Negeri dan Lembaga terkait untuk pemantauan, evaluasi dan pelaporan pelaksanaan pengarusutamaan gender di bidang penanggulangan bencana.
(2) BPBD melaporkan hasil pemantauan dan evaluasi pelaksanaan pengarusutamaan gender di bidang penanggulangan bencana kepada Gubernur untuk tingkat provinsi dan kepada Bupati/Walikota untuk tingkat kabupaten/kota dengan tembusan kepada BNPB.
(3) Laporan hasil pelaksanaan pengarusutamaan gender di bidang penanggulangan bencana yang dilakukan organisasi non-pemerintah dan para pihak lainnya dapat disampaikan kepada BNPB di tingkat nasional dan BPBD di tingkat daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6327, '(1) BNPB bekerjasama dengan kementerian yang membidangi pemberdayaan perempuan dan perlindungan anak melakukan 9 2014, No.1604 koordinasi dengan Kementerian Dalam Negeri dan Lembaga terkait untuk pemantauan, evaluasi dan pelaporan pelaksanaan pengarusutamaan gender di bidang penanggulangan bencana.
(2) BPBD melaporkan hasil pemantauan dan evaluasi pelaksanaan pengarusutamaan gender di bidang penanggulangan bencana kepada Gubernur untuk tingkat provinsi dan kepada Bupati/Walikota untuk tingkat kabupaten/kota dengan tembusan kepada BNPB.
(3) Laporan hasil pelaksanaan pengarusutamaan gender di bidang penanggulangan bencana yang dilakukan organisasi non-pemerintah dan para pihak lainnya dapat disampaikan kepada BNPB di tingkat nasional dan BPBD di tingkat daerah.', 'Pasal 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6328, 'perka-13-2014', 15, 'pasal', 'Pasal 12', 'BAB IV PENGARUSUTAMAAN GENDER SAAT PRA-BENCANA; Bagian Kesatu Kajian Risiko Bencana Responsif Gender', 9, 'Kajian risiko bencana responsif gender dilaksanakan dengan:
a. menggunakan data terpilah untuk mengkaji perbedaan dalam tingkat penerimaan risiko antara laki-laki dan perempuan;
b. memperhatikan perbedaan risiko yang dihadapi oleh laki-laki dan perempuan di setiap daerah dan/atau komunitas;
c. memperhatikan pengetahuan dan persepsi tradisional perempuan;
d. memetakan dan melibatkan organisasi-organisasi komunitas untuk memastikan partisipasi laki-laki dan perempuan dalam konsultasi ancaman dan pengumpulan data serta penyampaian informasi;
e. melibatkan perempuan dan laki-laki dalam proses kaji-ulang dan pemutakhiran data risiko tahunan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6328, 'Kajian risiko bencana responsif gender dilaksanakan dengan:
a. menggunakan data terpilah untuk mengkaji perbedaan dalam tingkat penerimaan risiko antara laki-laki dan perempuan;
b. memperhatikan perbedaan risiko yang dihadapi oleh laki-laki dan perempuan di setiap daerah dan/atau komunitas;
c. memperhatikan pengetahuan dan persepsi tradisional perempuan;
d. memetakan dan melibatkan organisasi-organisasi komunitas untuk memastikan partisipasi laki-laki dan perempuan dalam konsultasi ancaman dan pengumpulan data serta penyampaian informasi;
e. melibatkan perempuan dan laki-laki dalam proses kaji-ulang dan pemutakhiran data risiko tahunan.', 'Pasal 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6329, 'perka-13-2014', 16, 'pasal', 'Pasal 13', 'BAB IV PENGARUSUTAMAAN GENDER SAAT PRA-BENCANA; Bagian Kesatu Kajian Risiko Bencana Responsif Gender', 9, 'Penilaian kerentanan responsif gender dilaksanakan dengan:
a. memetakan dan mendokumentasikan perbedaan kerentanan terkait gender dalam aspek fisik, sosial, ekonomi, budaya, politik, keamanan, dan lingkungan;
b. mengidentifikasi kebutuhan, kepentingan dan pengetahuan perempuan dan laki-laki untuk semua jenis ancaman yang relevan;
c. mencakup analisis pengalaman dampak bencana yang dialami oleh laki-laki dan perempuan;
d. memastikan keterlibatan aktif dan berimbang antara laki-laki dan 2014, No.1604 10 perempuan berdasarkan wilayah, kelompok usia, disabilitas, akses informasi, mobilitas dan akses pada pendapatan dan sumber daya lain yang menjadi kunci penentu kerentanan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6329, 'Penilaian kerentanan responsif gender dilaksanakan dengan:
a. memetakan dan mendokumentasikan perbedaan kerentanan terkait gender dalam aspek fisik, sosial, ekonomi, budaya, politik, keamanan, dan lingkungan;
b. mengidentifikasi kebutuhan, kepentingan dan pengetahuan perempuan dan laki-laki untuk semua jenis ancaman yang relevan;
c. mencakup analisis pengalaman dampak bencana yang dialami oleh laki-laki dan perempuan;
d. memastikan keterlibatan aktif dan berimbang antara laki-laki dan 2014, No.1604 10 perempuan berdasarkan wilayah, kelompok usia, disabilitas, akses informasi, mobilitas dan akses pada pendapatan dan sumber daya lain yang menjadi kunci penentu kerentanan.', 'Pasal 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6330, 'perka-13-2014', 17, 'pasal', 'Pasal 14', 'BAB IV PENGARUSUTAMAAN GENDER SAAT PRA-BENCANA; Bagian Kedua Peringatan Dini Responsif Gender', 10, 'Identifikasi dan penilaian kapasitas responsif gender dilaksanakan dengan:
a. melibatkan laki-laki dalam proses kajian kapasitas pada kelompok, organisasi atau institusi yang berbasis perempuan;
b. mengidentifikasi fungsi khusus, peran dan tanggung jawab yang dimiliki perempuan dan laki-laki;
c. mengidentifikasi dan menyediakan mekanisme pendukung khusus yang dibutuhkan perempuan untuk dapat terlibat dalam program dan aksi manajemen risiko; dan
d. mengidentifikasi mekanisme untuk meningkatkan kapasitas laki-laki dan perempuan, serta memastikan program pengembangan kapasitas melibatkan partisipasi perempuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6330, 'Identifikasi dan penilaian kapasitas responsif gender dilaksanakan dengan:
a. melibatkan laki-laki dalam proses kajian kapasitas pada kelompok, organisasi atau institusi yang berbasis perempuan;
b. mengidentifikasi fungsi khusus, peran dan tanggung jawab yang dimiliki perempuan dan laki-laki;
c. mengidentifikasi dan menyediakan mekanisme pendukung khusus yang dibutuhkan perempuan untuk dapat terlibat dalam program dan aksi manajemen risiko; dan
d. mengidentifikasi mekanisme untuk meningkatkan kapasitas laki-laki dan perempuan, serta memastikan program pengembangan kapasitas melibatkan partisipasi perempuan.', 'Pasal 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6331, 'perka-13-2014', 18, 'pasal', 'Pasal 15', 'BAB IV PENGARUSUTAMAAN GENDER SAAT PRA-BENCANA; Bagian Ketiga Mitigasi dan Kesiapsiagaan Bencana Responsif Gender', 10, 'Peringatan dini responsif gender sebagaimana dimaksud pada ayat (1) dilaksanakan dengan:
a. menggunakan kemampuan dan pengetahuan lokal perempuan dan laki-laki;
b. melibatkan secara aktif kelompok perempuan dengan memanfaatkan praktik-praktik komunikasi tradisional setempat dalam penerimaan dan penyampaian informasi peringatan dini; dan
c. mengoptimalkan kemampuan respons perempuan dalam mengambil tindakan tepat dan cepat setelah menerima peringatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6331, 'Peringatan dini responsif gender sebagaimana dimaksud pada ayat (1) dilaksanakan dengan:
a. menggunakan kemampuan dan pengetahuan lokal perempuan dan laki-laki;
b. melibatkan secara aktif kelompok perempuan dengan memanfaatkan praktik-praktik komunikasi tradisional setempat dalam penerimaan dan penyampaian informasi peringatan dini; dan
c. mengoptimalkan kemampuan respons perempuan dalam mengambil tindakan tepat dan cepat setelah menerima peringatan.', 'Pasal 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6332, 'perka-13-2014', 19, 'pasal', 'Pasal 16', 'BAB V PENGARUSUTAMAAN GENDER SAAT TANGGAP DARURAT; Bagian Kesatu Tanggap Darurat Responsif Gender', 10, 'Mitigasi dan kesiapsiagaan bencana responsif gender dilaksanakan dengan:
a. melibatkan perempuan dan laki-laki secara aktif;
b. meningkatkan keterampilan perempuan dan laki-laki dalam pengurangan risiko bencana;
c. memperhatikan perbedaan cara pandang, pengetahuan dan kebutuhan antara perempuan dan laki-laki dalam perencanaan dan pelaksanaan.
11 2014, No.1604');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6332, 'Mitigasi dan kesiapsiagaan bencana responsif gender dilaksanakan dengan:
a. melibatkan perempuan dan laki-laki secara aktif;
b. meningkatkan keterampilan perempuan dan laki-laki dalam pengurangan risiko bencana;
c. memperhatikan perbedaan cara pandang, pengetahuan dan kebutuhan antara perempuan dan laki-laki dalam perencanaan dan pelaksanaan.
11 2014, No.1604', 'Pasal 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6333, 'perka-13-2014', 20, 'pasal', 'Pasal 17', 'BAB V PENGARUSUTAMAAN GENDER SAAT TANGGAP DARURAT; Bagian Kedua Pemenuhan Kebutuhan Dasar', 11, 'Tanggap darurat responsif gender dilaksanakan dengan:
a. melibatkan perempuan dan laki-laki secara aktif dalam menyusun rencana tanggap darurat;
b. memastikan adanya perwakilan yang seimbang antara laki-laki dan perempuan dalam tim kaji cepat;
c. memprioritaskan kelompok rentan untuk menghindari kekerasan berbasis gender.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6333, 'Tanggap darurat responsif gender dilaksanakan dengan:
a. melibatkan perempuan dan laki-laki secara aktif dalam menyusun rencana tanggap darurat;
b. memastikan adanya perwakilan yang seimbang antara laki-laki dan perempuan dalam tim kaji cepat;
c. memprioritaskan kelompok rentan untuk menghindari kekerasan berbasis gender.', 'Pasal 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6334, 'perka-13-2014', 21, 'pasal', 'Pasal 18', 'BAB V PENGARUSUTAMAAN GENDER SAAT TANGGAP DARURAT; Bagian Keempat Penampungan dan Hunian Sementara', 11, '(1) Pemenuhan kebutuhan dasar pada saat tanggap darurat dilaksanakan dengan melibatkan kelompok perempuan dan laki-laki secara aktif dan seimbang mulai dari pendataan hingga distribusi.
(2) Lokasi distribusi bantuan pangan mudah dijangkau oleh penyintas perempuan;
(3) Ukuran dan berat paket bantuan pangan dikemas sesuai dengan kemampuan perempuan untuk memindahkanya;
(4) Bantuan pangan memperhatikan perbedaan kebutuhan gizi antara perempuan, laki-laki dan anak-anak serta kelompok rentan lainnya;
(5) Pemenuhan kebutuhan dasar dapat dilaksanakan melalui pemberian perlakuan khusus.
(6) Perlakuan khusus sebagaimana dimaksud pada ayat (5) diberikan kepada:
a. perempuan kepala rumah tangga;
b. laki-laki kepala rumah tangga tanpa ibu rumah tangga;
c. ibu hamil dan menyusui;
d. kelompok rentan lainnya.
2014, No.1604 12');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6334, '(1) Pemenuhan kebutuhan dasar pada saat tanggap darurat dilaksanakan dengan melibatkan kelompok perempuan dan laki-laki secara aktif dan seimbang mulai dari pendataan hingga distribusi.
(2) Lokasi distribusi bantuan pangan mudah dijangkau oleh penyintas perempuan;
(3) Ukuran dan berat paket bantuan pangan dikemas sesuai dengan kemampuan perempuan untuk memindahkanya;
(4) Bantuan pangan memperhatikan perbedaan kebutuhan gizi antara perempuan, laki-laki dan anak-anak serta kelompok rentan lainnya;
(5) Pemenuhan kebutuhan dasar dapat dilaksanakan melalui pemberian perlakuan khusus.
(6) Perlakuan khusus sebagaimana dimaksud pada ayat (5) diberikan kepada:
a. perempuan kepala rumah tangga;
b. laki-laki kepala rumah tangga tanpa ibu rumah tangga;
c. ibu hamil dan menyusui;
d. kelompok rentan lainnya.
2014, No.1604 12', 'Pasal 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6335, 'perka-13-2014', 22, 'pasal', 'Pasal 19', 'BAB V PENGARUSUTAMAAN GENDER SAAT TANGGAP DARURAT; Bagian Kelima Kebutuhan Air Bersih dan Sanitasi', 12, 'Penyediaan sarana penampungan dan hunian sementara dilaksanakan dengan:
a. melibatkan perempuan dan laki-laki secara seimbang dalam hal:
1) perencanaan, pengalokasian dan pembangunan;
2) pengupahan yang sama untuk pekerjaan yang sama dalam pelaksanaan konstruksi;
3) pelatihan keterampilan terkait konstruksi;
b. memastikan informasi menyangkut pengelolaan fasilitas penampungan dan hunian sementara diterima penyintas laki-laki, perempuan dan anak-anak dengan mudah;
c. memastikan penyediaan kebutuhan khusus laki-laki, perempuan dan anak-anak dalam penampungan dan hunian sementara;
d. Memastikan penampungan dan hunian sementara aman bagi perempuan, anak dan kelompok rentan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6335, 'Penyediaan sarana penampungan dan hunian sementara dilaksanakan dengan:
a. melibatkan perempuan dan laki-laki secara seimbang dalam hal:
1) perencanaan, pengalokasian dan pembangunan;
2) pengupahan yang sama untuk pekerjaan yang sama dalam pelaksanaan konstruksi;
3) pelatihan keterampilan terkait konstruksi;
b. memastikan informasi menyangkut pengelolaan fasilitas penampungan dan hunian sementara diterima penyintas laki-laki, perempuan dan anak-anak dengan mudah;
c. memastikan penyediaan kebutuhan khusus laki-laki, perempuan dan anak-anak dalam penampungan dan hunian sementara;
d. Memastikan penampungan dan hunian sementara aman bagi perempuan, anak dan kelompok rentan.', 'Pasal 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6336, 'perka-13-2014', 23, 'pasal', 'Pasal 20', 'BAB V PENGARUSUTAMAAN GENDER SAAT TANGGAP DARURAT; Bagian Keenam Layanan Kesehatan', 12, '(1) Penyediaan layanan air bersih dan sarana sanitasi disesuaikan dengan kepentingan dan kebutuhan perempuan, laki-laki dan anak-anak serta mempertimbangkan nilai sosial-budaya setempat.
(2) Lokasi, mekanisme distribusi dan prosedur perawatan layanan air bersih dan sarana sanitasi mudah dijangkau oleh perempuan dan anak-anak.
(3) Sarana sanitasi dan mandi-cuci berada di lokasi yang aman terutama bagi perempuan dan anak-anak.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6336, '(1) Penyediaan layanan air bersih dan sarana sanitasi disesuaikan dengan kepentingan dan kebutuhan perempuan, laki-laki dan anak-anak serta mempertimbangkan nilai sosial-budaya setempat.
(2) Lokasi, mekanisme distribusi dan prosedur perawatan layanan air bersih dan sarana sanitasi mudah dijangkau oleh perempuan dan anak-anak.
(3) Sarana sanitasi dan mandi-cuci berada di lokasi yang aman terutama bagi perempuan dan anak-anak.', 'Pasal 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6337, 'perka-13-2014', 24, 'pasal', 'Pasal 21', 'BAB V PENGARUSUTAMAAN GENDER SAAT TANGGAP DARURAT; Bagian Ketujuh Layanan Pendidikan', 12, '(1) Pemilihan waktu dan lokasi layanan kesehatan mudah diakses oleh perempuan, laki-laki dan anak-anak.
(2) Penyediaan layanan kesehatan disesuaikan dengan kebiasaan dan nilai sosial-budaya setempat termasuk kebutuhan layanan spesifik.
13 2014, No.1604
(3) Jumlah petugas penyedia layanan kesehatan berimbang antara laki-laki dan perempuan untuk kebutuhan layanan kesehatan spesifik.
(4) Penyediaan layanan kesehatan 24 (dua puluh empat) jam untuk penyintas akibat kekerasan seksual, psikologis dan kekerasan berbasis gender.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6337, '(1) Pemilihan waktu dan lokasi layanan kesehatan mudah diakses oleh perempuan, laki-laki dan anak-anak.
(2) Penyediaan layanan kesehatan disesuaikan dengan kebiasaan dan nilai sosial-budaya setempat termasuk kebutuhan layanan spesifik.
13 2014, No.1604
(3) Jumlah petugas penyedia layanan kesehatan berimbang antara laki-laki dan perempuan untuk kebutuhan layanan kesehatan spesifik.
(4) Penyediaan layanan kesehatan 24 (dua puluh empat) jam untuk penyintas akibat kekerasan seksual, psikologis dan kekerasan berbasis gender.', 'Pasal 21', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6338, 'perka-13-2014', 25, 'pasal', 'Pasal 22', 'BAB V PENGARUSUTAMAAN GENDER SAAT TANGGAP DARURAT; Bagian Kedelapan Layanan Psikososial', 13, '(1) Perempuan dilibatkan secara aktif dalam mengidentifikasi kebutuhan, menganalisis, merancang, melaksanakan dan memantau layanan pendidikan dalam situasi bencana.
(2) Penyediaan layanan pendidikan memastikan lingkungan belajar aman, terlindungi, mudah diakses dan memperhatikan kondisi psikososial peserta didik, guru dan tenaga pendidikan lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6338, '(1) Perempuan dilibatkan secara aktif dalam mengidentifikasi kebutuhan, menganalisis, merancang, melaksanakan dan memantau layanan pendidikan dalam situasi bencana.
(2) Penyediaan layanan pendidikan memastikan lingkungan belajar aman, terlindungi, mudah diakses dan memperhatikan kondisi psikososial peserta didik, guru dan tenaga pendidikan lainnya.', 'Pasal 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6339, 'perka-13-2014', 26, 'pasal', 'Pasal 23', 'BAB V PENGARUSUTAMAAN GENDER SAAT TANGGAP DARURAT; Bagian Kesembilan Keamanan', 13, '(1) Pendampingan psikososial melibatkan perempuan dan laki-laki dalam pengumpulan data, perencanaan dan pelaksanaan.
(2) Pendampingan psikososial sebagaimana dimaksud pada ayat (1) dilaksanakan dengan memperhatikan kepentingan dan kebutuhan perempuan, laki-laki, dan anak-anak serta kelompok rentan lainnya.
(3) Pendampingan psikososial sebagaimana dimaksud pada ayat (1) disesuaikan dengan nilai sosial-budaya setempat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6339, '(1) Pendampingan psikososial melibatkan perempuan dan laki-laki dalam pengumpulan data, perencanaan dan pelaksanaan.
(2) Pendampingan psikososial sebagaimana dimaksud pada ayat (1) dilaksanakan dengan memperhatikan kepentingan dan kebutuhan perempuan, laki-laki, dan anak-anak serta kelompok rentan lainnya.
(3) Pendampingan psikososial sebagaimana dimaksud pada ayat (1) disesuaikan dengan nilai sosial-budaya setempat.', 'Pasal 23', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6340, 'perka-13-2014', 27, 'pasal', 'Pasal 24', 'BAB VI PENGARUSUTAMAAN GENDER SAAT PASCA BENCANA; Bagian Kesatu Rehabilitasi dan Rekonstruksi', 13, '(1) Upaya-upaya sistematis dan optimal dilakukan untuk mencegah terjadinya kekerasan dan pelecehan fisik serta verbal pada perempuan dan anak serta kelompok rentan lainnya.
(2) Upaya sistematis sebagaimana dimaksud pada ayat (1) dilaksanakan dengan melibatkan perempuan dan laki-laki.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6340, '(1) Upaya-upaya sistematis dan optimal dilakukan untuk mencegah terjadinya kekerasan dan pelecehan fisik serta verbal pada perempuan dan anak serta kelompok rentan lainnya.
(2) Upaya sistematis sebagaimana dimaksud pada ayat (1) dilaksanakan dengan melibatkan perempuan dan laki-laki.', 'Pasal 24', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6341, 'perka-13-2014', 28, 'pasal', 'Pasal 25', 'BAB VI PENGARUSUTAMAAN GENDER SAAT PASCA BENCANA; Bagian Kesatu Rehabilitasi dan Rekonstruksi', 13, '(1) Perempuan dan laki-laki berpartisipasi aktif dalam perencanaan, pelaksanaan dan pemantauan rehabilitasi dan rekonstruksi.
2014, No.1604 14
(2) Kebutuhan khusus perempuan dan laki-laki dipertimbangkan dalam proses perencanaan dan alokasi sumber daya rehabilitasi dan rekonstruksi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6341, '(1) Perempuan dan laki-laki berpartisipasi aktif dalam perencanaan, pelaksanaan dan pemantauan rehabilitasi dan rekonstruksi.
2014, No.1604 14
(2) Kebutuhan khusus perempuan dan laki-laki dipertimbangkan dalam proses perencanaan dan alokasi sumber daya rehabilitasi dan rekonstruksi.', 'Pasal 25', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6342, 'perka-13-2014', 29, 'pasal', 'Pasal 26', 'BAB VII KERJASAMA PARA PIHAK DAN PENGEMBANGAN KAPASITAS', 14, '(1) Upaya pemulihan dan peningkatan fisik, sosial dan ekonomi melibatkan perempuan dan laki-laki dalam proses konsultasi dan dialog.
(2) Pemulihan dan penguatan ekonomi masyarakat terdampak diarahkan untuk membangun keamanan pangan dan keberlanjutan ekonomi keluarga.
(3) Pemulihan dan penguatan ekonomi sebagaimana dimaksud pada ayat
(1) memberikan peluang bagi penyintas laki-laki maupun perempuan untuk memperoleh keterampilan tambahan.
(4) Pemulihan dan penguatan ekonomi sebagaimana dimaksud pada ayat
(1) memberikan prioritas kepada perempuan kepala rumah tangga, rumah tangga tanpa ibu dan rumah tangga rentan lainnya.
(5) Prioritas sebagaimana dimaksud pada ayat (3) berupa kepemilikan rumah dan lahan maupun bantuan khusus lainnya sesuai kondisi penyintas.
(6) Perlakuan khusus diberikan kepada laki-laki kepala keluarga yang memiliki balita berupa bantuan dalam pengasuhan anak.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6342, '(1) Upaya pemulihan dan peningkatan fisik, sosial dan ekonomi melibatkan perempuan dan laki-laki dalam proses konsultasi dan dialog.
(2) Pemulihan dan penguatan ekonomi masyarakat terdampak diarahkan untuk membangun keamanan pangan dan keberlanjutan ekonomi keluarga.
(3) Pemulihan dan penguatan ekonomi sebagaimana dimaksud pada ayat
(1) memberikan peluang bagi penyintas laki-laki maupun perempuan untuk memperoleh keterampilan tambahan.
(4) Pemulihan dan penguatan ekonomi sebagaimana dimaksud pada ayat
(1) memberikan prioritas kepada perempuan kepala rumah tangga, rumah tangga tanpa ibu dan rumah tangga rentan lainnya.
(5) Prioritas sebagaimana dimaksud pada ayat (3) berupa kepemilikan rumah dan lahan maupun bantuan khusus lainnya sesuai kondisi penyintas.
(6) Perlakuan khusus diberikan kepada laki-laki kepala keluarga yang memiliki balita berupa bantuan dalam pengasuhan anak.', 'Pasal 26', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6343, 'perka-13-2014', 30, 'pasal', 'Pasal 27', 'BAB VII KERJASAMA PARA PIHAK DAN PENGEMBANGAN KAPASITAS', 14, '(1) BNPB/BPBD bekerjasama dan berkoordinasi dengan kementerian/ lembaga dan SKPD terkait dalam penyusunan regulasi dan pengembangan kapasitas dalam penanggulangan bencana responsif gender.
(2) BNPB/BPBD bekerjasama dengan universitas, lembaga penelitian, lembaga usaha, organisasi non-pemerintah dan para pihak lainnya dalam mendorong penelitian-penelitian dalam penanggulangan bencana responsif gender.
(3) BNPB/BPBD bekerjasama dengan universitas, lembaga penelitian, lembaga usaha, organisasi non-pemerintah, media masa dan jejaring sosial mempromosikan dan melaksanakan program penanggulangan bencana responsif gender.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6343, '(1) BNPB/BPBD bekerjasama dan berkoordinasi dengan kementerian/ lembaga dan SKPD terkait dalam penyusunan regulasi dan pengembangan kapasitas dalam penanggulangan bencana responsif gender.
(2) BNPB/BPBD bekerjasama dengan universitas, lembaga penelitian, lembaga usaha, organisasi non-pemerintah dan para pihak lainnya dalam mendorong penelitian-penelitian dalam penanggulangan bencana responsif gender.
(3) BNPB/BPBD bekerjasama dengan universitas, lembaga penelitian, lembaga usaha, organisasi non-pemerintah, media masa dan jejaring sosial mempromosikan dan melaksanakan program penanggulangan bencana responsif gender.', 'Pasal 27', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6344, 'perka-13-2014', 31, 'pasal', 'Pasal 28', 'BAB VIII KETENTUAN PENUTUP', 14, '(1) BPNB/BPBD mengidentifikasi secara berkala kebutuhan pengembangan kapasitas dalam penanggulangan bencana responsif gender.
15 2014, No.1604
(2) Identifikasi kebutuhan sebagaimana dimaksud pada ayat (1) BNPB/BPBD merancang dan menyelenggarakan program-program pengembangan kapasitas dalam rangka penanggulangan bencana responsif gender.
(3) Dalam menyelenggarakan berbagai program pengembangan kapasitas sebagaimana dimaksud dalam ayat (1) BNPB/BPBD bekerjasama dengan kementerian/lembaga dan SKPD terkait serta pihak-pihak lain sesuai kebutuhan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6344, '(1) BPNB/BPBD mengidentifikasi secara berkala kebutuhan pengembangan kapasitas dalam penanggulangan bencana responsif gender.
15 2014, No.1604
(2) Identifikasi kebutuhan sebagaimana dimaksud pada ayat (1) BNPB/BPBD merancang dan menyelenggarakan program-program pengembangan kapasitas dalam rangka penanggulangan bencana responsif gender.
(3) Dalam menyelenggarakan berbagai program pengembangan kapasitas sebagaimana dimaksud dalam ayat (1) BNPB/BPBD bekerjasama dengan kementerian/lembaga dan SKPD terkait serta pihak-pihak lain sesuai kebutuhan.', 'Pasal 28', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6345, 'perka-13-2014', 32, 'pasal', 'Pasal 29', 'BAB VIII KETENTUAN PENUTUP', 15, 'Dengan ditetapkannya peraturan Kepala BNPB ini, maka peraturan-peraturan lain yang mengatur pengarusutamaan gender di bidang penanggulangan bencana menyesuaikan dengan peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6345, 'Dengan ditetapkannya peraturan Kepala BNPB ini, maka peraturan-peraturan lain yang mengatur pengarusutamaan gender di bidang penanggulangan bencana menyesuaikan dengan peraturan ini.', 'Pasal 29', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2014 tentang Pengarusutamaan Gender di Bidang Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6346, 'perka-13-2014', 33, 'pasal', 'Pasal 30', 'BAB VIII KETENTUAN PENUTUP', 15, 'Peraturan Kepala BNPB ini mulai berlaku pada tanggal diundangkan.
