b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6350, 'perka-14-2009', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 2 Tahun 1989 tentang Sistem Pendidikan Nasional (Lembaran Negara Republik Indonesia'' Tahun 1989 Nomor 6, Tambahan Lembaran Negara Republik Indonesia Nomor 3390);
