INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6351, 'perka-14-2009', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN UMUM PENYELENGGARAAN PELATIHAN PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6351, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN UMUM PENYELENGGARAAN PELATIHAN PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6352, 'perka-14-2009', 4, 'pasal', 'Pasal 1', 'BAB II MAKSUD, TUJUAN DAN LINGKUP PELATIHAN', 2, 'Dalam Peraturan Kepala Badan ini yang dimaksud dengan:
1. Penyelenggaraan Pelatihan Penanggulangan Bencana, adalah keseluruhan kegiatan yang berhubungan dengan pelatihan penanggulangan bencana mulai dari perencanaan, pelaksanaan, sampai dengan pengawasan dan pengendalian pelatihan.
2. Penyelenggara Pelatihan Penanggulangan Bencana, adalah Instansi/ Lembaga/Organisasi terkait yang mempunyai tugas pokok dan fungsi dibidang penanggulangan bencana, mernillki sarana dan prasarana yang mendukung terciptanya proses pelatihan.
3. Peserta Pelatihan Penanggulangan Bencana adalah peserta pelatihan yang berasal dari aparatur pemerintah pusat/daerah, masyarakat dan lembaga usaha/swasta yang berkaitan dengan upaya penanggulangan bencana dan ditunjuk oleh pimpinan dalam organisasi serta memenuhi kriteria yang ditetapkan oleh penyelenggara pelatihan.
3 2014, No.1415
4. Tenaga Pengajar adalah seseorang yang ditetapkan dan ditunjuk oleh institusi/lembaga tertentu dan memiliki sertifikat sebagai seorang tenaga pengajar sesuai keahliannya.
5. Kompetensi, adalah kemampuan dan karakteristik yang dimiliki oleh seorang yang mempunyai tanggung jawab dalam penanggulangan bencana berupa pengetahuan, keterampilan, dan sikap perilaku yang diperlukan dalam melaksanakan tugasnya.
6. Sertifikasi, adalah pengakuan resmi terhadap seseorang yang karena kepemilikan pengetahuan, keterampilan, dan kemampuannya di bidang penanggulangan bencana perlu diterbitkan sertifikat secara resmi.
7. Kurikulum, adalah seperangkat rencana dan pengaturan menqenal tujuan, isi dan materi pelatihan serta cara yang digunakan sebagai pedoman penyelenggaraan kegiatan pelatihan untuk mencapai tujuan pelatihan tertentu.
8. Modul adalah suatu pengajaran yang memuat satu unit konsep dari bahan pelajaran dan disusun untuk membantu peserta pelatihan mencapai sejumlah tujuan yang dirumuskan secara khusus dan jelas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6352, 'Dalam Peraturan Kepala Badan ini yang dimaksud dengan:
1. Penyelenggaraan Pelatihan Penanggulangan Bencana, adalah keseluruhan kegiatan yang berhubungan dengan pelatihan penanggulangan bencana mulai dari perencanaan, pelaksanaan, sampai dengan pengawasan dan pengendalian pelatihan.
2. Penyelenggara Pelatihan Penanggulangan Bencana, adalah Instansi/ Lembaga/Organisasi terkait yang mempunyai tugas pokok dan fungsi dibidang penanggulangan bencana, mernillki sarana dan prasarana yang mendukung terciptanya proses pelatihan.
3. Peserta Pelatihan Penanggulangan Bencana adalah peserta pelatihan yang berasal dari aparatur pemerintah pusat/daerah, masyarakat dan lembaga usaha/swasta yang berkaitan dengan upaya penanggulangan bencana dan ditunjuk oleh pimpinan dalam organisasi serta memenuhi kriteria yang ditetapkan oleh penyelenggara pelatihan.
3 2014, No.1415
4. Tenaga Pengajar adalah seseorang yang ditetapkan dan ditunjuk oleh institusi/lembaga tertentu dan memiliki sertifikat sebagai seorang tenaga pengajar sesuai keahliannya.
5. Kompetensi, adalah kemampuan dan karakteristik yang dimiliki oleh seorang yang mempunyai tanggung jawab dalam penanggulangan bencana berupa pengetahuan, keterampilan, dan sikap perilaku yang diperlukan dalam melaksanakan tugasnya.
6. Sertifikasi, adalah pengakuan resmi terhadap seseorang yang karena kepemilikan pengetahuan, keterampilan, dan kemampuannya di bidang penanggulangan bencana perlu diterbitkan sertifikat secara resmi.
7. Kurikulum, adalah seperangkat rencana dan pengaturan menqenal tujuan, isi dan materi pelatihan serta cara yang digunakan sebagai pedoman penyelenggaraan kegiatan pelatihan untuk mencapai tujuan pelatihan tertentu.
8. Modul adalah suatu pengajaran yang memuat satu unit konsep dari bahan pelajaran dan disusun untuk membantu peserta pelatihan mencapai sejumlah tujuan yang dirumuskan secara khusus dan jelas.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6353, 'perka-14-2009', 5, 'pasal', 'Pasal 2', 'BAB II MAKSUD, TUJUAN DAN LINGKUP PELATIHAN', 3, '(1) Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana ini dimaksudkan untuk digunakan sebagai panduan dalam penyelenggaraan pelatihan penanggulangan bencana yang diselenggarakan oleh BNPB atau Instansi/Lembaga/Organisasi terkait dalam penanggulangan bencana.
(2) Pedoman ini menjadi acuan bagi Instansi/Lembaga/Organisasi pemerintah dan pemerintah daerah, juga dapat menjadi acuan bagi para penyelenggara pelatihan penanggulangan bencana yang berasal dari lembaga/organisasi swasta.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6353, '(1) Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana ini dimaksudkan untuk digunakan sebagai panduan dalam penyelenggaraan pelatihan penanggulangan bencana yang diselenggarakan oleh BNPB atau Instansi/Lembaga/Organisasi terkait dalam penanggulangan bencana.
(2) Pedoman ini menjadi acuan bagi Instansi/Lembaga/Organisasi pemerintah dan pemerintah daerah, juga dapat menjadi acuan bagi para penyelenggara pelatihan penanggulangan bencana yang berasal dari lembaga/organisasi swasta.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6354, 'perka-14-2009', 6, 'pasal', 'Pasal 3', 'BAB II MAKSUD, TUJUAN DAN LINGKUP PELATIHAN', 3, 'Penyelenggaraan pelatihan penanggulangan bencana bertujuan untuk:
a. Meningkatkan kesadaran, kepedulian, kemampuan dan kesiapsiagaan masyarakat dan aparatur dalam menghadapi bencana;
b. Meningkatkan pengetahuan, keterampilan dan sikap masyarakat dan aparatur dalam penanggulangan bencana; dan
c. Meningkatkan kemampuan dan profesionalitas dalam pelaksanaan penanggulangan bencana.
2014, No.1415 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6354, 'Penyelenggaraan pelatihan penanggulangan bencana bertujuan untuk:
a. Meningkatkan kesadaran, kepedulian, kemampuan dan kesiapsiagaan masyarakat dan aparatur dalam menghadapi bencana;
b. Meningkatkan pengetahuan, keterampilan dan sikap masyarakat dan aparatur dalam penanggulangan bencana; dan
c. Meningkatkan kemampuan dan profesionalitas dalam pelaksanaan penanggulangan bencana.
2014, No.1415 4', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6355, 'perka-14-2009', 7, 'pasal', 'Pasal 4', 'BAB III PENYELENGGARAAN PELATIHAN', 4, 'Pedoman ini berlaku bagi para penyelenggara pelatihan penanggulangan bencana pada lingkup nasional, provinsi, kabupaten/kota dan instansi/lembaga/organisasi terkait yang menyelenggarakan pelatihan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6355, 'Pedoman ini berlaku bagi para penyelenggara pelatihan penanggulangan bencana pada lingkup nasional, provinsi, kabupaten/kota dan instansi/lembaga/organisasi terkait yang menyelenggarakan pelatihan penanggulangan bencana.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6356, 'perka-14-2009', 8, 'pasal', 'Pasal 5', 'BAB III PENYELENGGARAAN PELATIHAN; Bagian Kesatu Jenjang Pelatihan', 4, 'Penyelenggaraan pelatihan adalah keseluruhan proses kegiatan pelatihan penanggulangan bencana mulai dari perencanaan, pengorganisasian, pelaksanaan, pengawasan dan pengendalian pelatihan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6356, 'Penyelenggaraan pelatihan adalah keseluruhan proses kegiatan pelatihan penanggulangan bencana mulai dari perencanaan, pengorganisasian, pelaksanaan, pengawasan dan pengendalian pelatihan.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6357, 'perka-14-2009', 9, 'pasal', 'Pasal 6', 'BAB III PENYELENGGARAAN PELATIHAN; Bagian Kesatu Jenjang Pelatihan', 4, 'Jenjang pelatihan penanggulangan bencana terdiri dari :
a. Pelatihan Penanggulangan Bencana tingkat pengambilan keputusan:
b. Pelatihan Penanggulangan Bencana tingkat manajer; dan
c. Pelatihan Penanggulangan Bencanatingkat teknis.·');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6357, 'Jenjang pelatihan penanggulangan bencana terdiri dari :
a. Pelatihan Penanggulangan Bencana tingkat pengambilan keputusan:
b. Pelatihan Penanggulangan Bencana tingkat manajer; dan
c. Pelatihan Penanggulangan Bencanatingkat teknis.·', 'Pasal 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6358, 'perka-14-2009', 10, 'pasal', 'Pasal 7', 'BAB III PENYELENGGARAAN PELATIHAN; Bagian Kesatu Jenjang Pelatihan', 4, '(1) Pelatihan Penanggulangan Bencana tingkat pengambilan keputusan memberikan penguasaan pengetahuan dengan menitikberatkan pada tataran kemampuan mengendalikan kegiatan penanggulangan bencana.
(2) Pelatihan Penanggulangan Bencana tingkat manajer memberikan penguasaan pengetahuan dengan menitikberatkan pada tataran kemampuan dan keterampilan mengelola upaya penanggulangan bencana.
(3) Pelatihan Penanggulangan Bencana tingkat teknis operasional memberikan penguasaan pengetahuan dengan menitikberatkan pada tataran keterampilan dalam kegiatan operasional penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6358, '(1) Pelatihan Penanggulangan Bencana tingkat pengambilan keputusan memberikan penguasaan pengetahuan dengan menitikberatkan pada tataran kemampuan mengendalikan kegiatan penanggulangan bencana.
(2) Pelatihan Penanggulangan Bencana tingkat manajer memberikan penguasaan pengetahuan dengan menitikberatkan pada tataran kemampuan dan keterampilan mengelola upaya penanggulangan bencana.
(3) Pelatihan Penanggulangan Bencana tingkat teknis operasional memberikan penguasaan pengetahuan dengan menitikberatkan pada tataran keterampilan dalam kegiatan operasional penanggulangan bencana.', 'Pasal 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6359, 'perka-14-2009', 11, 'pasal', 'Pasal 8', 'BAB III PENYELENGGARAAN PELATIHAN; Bagian Kedua Penyelenggara', 4, 'Setiap jenjang pelatihan sebagaimana dimaksud dalam Pasal 6 diadakan pelatihan lanjutan, yaitu: Pelatihan untuk Pelatih (TOT) dan/ Pelatihan untuk Fasilitator (TOF).
5 2014, No.1415');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6359, 'Setiap jenjang pelatihan sebagaimana dimaksud dalam Pasal 6 diadakan pelatihan lanjutan, yaitu: Pelatihan untuk Pelatih (TOT) dan/ Pelatihan untuk Fasilitator (TOF).
5 2014, No.1415', 'Pasal 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6360, 'perka-14-2009', 12, 'pasal', 'Pasal 9', 'BAB III PENYELENGGARAAN PELATIHAN; Bagian Kedua Penyelenggara', 5, '(1) Pelatihan penanggulangan bencana diselenggarakan oleh Instansi/Lembaga/Organisasi setelah dikoordinasikan dengan Badan Nasional Penanggulangan Bencana;
(2) Dalam menyelenggarakan pelatihan penanggulangan bencana sebagaimana dimaksud dalam Ayat (1) dapat bekerjasama Instansi/Lembaga/Organisasi lainnya baik pemerintah maupun swasta.
(3) Pelatihan Penanggulangan Bencana tingkat pengambil keputusan diselenggarakan oleh Badan Nasional Penanggulangan Bencana;
(4) Setiap penyelenggara pelatihan penanggulangan bencana harus terakreditasi di Badan Nasional Penanggulangan Bencana (BNPB).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6360, '(1) Pelatihan penanggulangan bencana diselenggarakan oleh Instansi/Lembaga/Organisasi setelah dikoordinasikan dengan Badan Nasional Penanggulangan Bencana;
(2) Dalam menyelenggarakan pelatihan penanggulangan bencana sebagaimana dimaksud dalam Ayat (1) dapat bekerjasama Instansi/Lembaga/Organisasi lainnya baik pemerintah maupun swasta.
(3) Pelatihan Penanggulangan Bencana tingkat pengambil keputusan diselenggarakan oleh Badan Nasional Penanggulangan Bencana;
(4) Setiap penyelenggara pelatihan penanggulangan bencana harus terakreditasi di Badan Nasional Penanggulangan Bencana (BNPB).', 'Pasal 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6361, 'perka-14-2009', 13, 'pasal', 'Pasal 10', 'BAB III PENYELENGGARAAN PELATIHAN; Bagian Kedua Penyelenggara', 5, 'Penyelenggara pelatihan wajib menyediakan prasarana dan sarana sesuai dengan kebutuhan yang diperlukan dalam pelatihan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6361, 'Penyelenggara pelatihan wajib menyediakan prasarana dan sarana sesuai dengan kebutuhan yang diperlukan dalam pelatihan.', 'Pasal 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6362, 'perka-14-2009', 14, 'pasal', 'Pasal 11', 'BAB III PENYELENGGARAAN PELATIHAN; Bagian Ketiga Peserta', 5, 'Waktu dan lamanya penyelenggaraan pelatihan ditentukan berdasarkan kurikulum sesuai dengan jenis pelatihan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6362, 'Waktu dan lamanya penyelenggaraan pelatihan ditentukan berdasarkan kurikulum sesuai dengan jenis pelatihan.', 'Pasal 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6363, 'perka-14-2009', 15, 'pasal', 'Pasal 12', 'BAB III PENYELENGGARAAN PELATIHAN; Bagian Keempat Pelatih', 5, '(1) Peserta pelatihan penanggulangan bencana berasal dari aparatur pemerintah, masyarakat dan lembaga usaha sektor swasta.
(2) Peserta pelatihan penanggulangan bencana adalah sebagaimana dimaksud ayat (1) yang karena tugasnya melakukan atau berkaitan erat dengan penanggulangan bencana.
(3) Ketentuan peserta pelatihan penanggulangan bencana oleh masing-masing penyelenggara sesuai jenjang dan jenis pelatihan dengan memperhatikan bidang tugas dan tanggungjawab.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6363, '(1) Peserta pelatihan penanggulangan bencana berasal dari aparatur pemerintah, masyarakat dan lembaga usaha sektor swasta.
(2) Peserta pelatihan penanggulangan bencana adalah sebagaimana dimaksud ayat (1) yang karena tugasnya melakukan atau berkaitan erat dengan penanggulangan bencana.
(3) Ketentuan peserta pelatihan penanggulangan bencana oleh masing-masing penyelenggara sesuai jenjang dan jenis pelatihan dengan memperhatikan bidang tugas dan tanggungjawab.', 'Pasal 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6364, 'perka-14-2009', 16, 'pasal', 'Pasal 13', 'BAB III PENYELENGGARAAN PELATIHAN; Bagian Kelima Kurikulum', 5, '(1) Tenaga pengajar terdiri dari Nara surnber, Fasilitator, Pelatih dan Instruktur.
2014, No.1415 6
(2) Tenaga pengajar diutamakan yang telah memiliki sertifikat Training of Trainer (TOT)/Training of Fasilitator (TOF).
(3) Tenaga pengajar harus memiliki pengetahuan akademis, kapasitas dan pengalaman dalam penanggulangan bencana.
(4) Pelatihan yang diselenggarakan oleh sektor, materi dasar disampaikan oleh Tenaga Pengajar dari lembaga formal Penanggulangan Bencana dan/atau dari instansi/organisasi/lembaga yang memiliki kompetensi penanggulangan bencana.
(5) Pelatihan penanggulangan bencana dilingkungan Instansi/Lembaga/ Organisasi penyelenggara wajib mendayagunakan tenaga yang tersedia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6364, '(1) Tenaga pengajar terdiri dari Nara surnber, Fasilitator, Pelatih dan Instruktur.
2014, No.1415 6
(2) Tenaga pengajar diutamakan yang telah memiliki sertifikat Training of Trainer (TOT)/Training of Fasilitator (TOF).
(3) Tenaga pengajar harus memiliki pengetahuan akademis, kapasitas dan pengalaman dalam penanggulangan bencana.
(4) Pelatihan yang diselenggarakan oleh sektor, materi dasar disampaikan oleh Tenaga Pengajar dari lembaga formal Penanggulangan Bencana dan/atau dari instansi/organisasi/lembaga yang memiliki kompetensi penanggulangan bencana.
(5) Pelatihan penanggulangan bencana dilingkungan Instansi/Lembaga/ Organisasi penyelenggara wajib mendayagunakan tenaga yang tersedia.', 'Pasal 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6365, 'perka-14-2009', 17, 'pasal', 'Pasal 14', 'BAB III PENYELENGGARAAN PELATIHAN; Bagian Keenam Materi dan Pelasanaan', 6, '(1) Setiap jenjang dan jenis pelatihan dilengkapi dengan kurikulum.
(2) Susunan kurikulum dari setiap jenjang dan jenis pelatihan memuat materi dasar, materi pokok dan materi penunjang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6365, '(1) Setiap jenjang dan jenis pelatihan dilengkapi dengan kurikulum.
(2) Susunan kurikulum dari setiap jenjang dan jenis pelatihan memuat materi dasar, materi pokok dan materi penunjang.', 'Pasal 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6366, 'perka-14-2009', 18, 'pasal', 'Pasal 15', 'BAB III PENYELENGGARAAN PELATIHAN; Bagian Keenam Materi dan Pelasanaan', 6, '(1) Materi Dasar meliputi ;
a. Konsepsi Penanggulangan Bencana;
b. Karakteristik Bencana;
c. Prinsip-prinsip Dasar Manajemen Bencana; dan
d. Sistem Nasional Penanggulangan Bencana.
(2) Materi Pokok sepenuhnya diatur/ ditentukan oleh penyelenggara pelatihan sesuai dengan substansi yang merupakan tugas pokok dan fungsinya.
(3) Materi Penunjang disesuaikan dengan kebutuhan lembaga penyelenggara.
(4) Kedalaman masing-masing materi disesuaikandengan jenjang pelatihan.
Pasal16 Setiap jenjang dan jenis pelatihan diberikan kodefikasi serta diatur tersendiri.
7 2014, No.1415');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6366, '(1) Materi Dasar meliputi ;
