7 2014, No.1415', 'Pasal 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6367, 'perka-14-2009', 19, 'pasal', 'Pasal 17', 'BAB III PENYELENGGARAAN PELATIHAN; Bagian Ketujuh Metode Pelatihan', 7, 'Pelaksanaanpelatihan penanggulangan bencanaterdiri dari :
a. Persiapan ;
b. Pre Test;
c. Pemberian materi;
d. PosTest; dan
e. Evaluasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6367, 'Pelaksanaanpelatihan penanggulangan bencanaterdiri dari :
a. Persiapan ;
b. Pre Test;
c. Pemberian materi;
d. PosTest; dan
e. Evaluasi.', 'Pasal 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6368, 'perka-14-2009', 20, 'pasal', 'Pasal 18', 'BAB III PENYELENGGARAAN PELATIHAN; Bagian Kedelapan Sertifikat dan Brevet', 7, 'Metode pelatihan dipilih sesuai tujuan dan sasaran program dengan menggunakan pendekatan orang dewasa (andragogi).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6368, 'Metode pelatihan dipilih sesuai tujuan dan sasaran program dengan menggunakan pendekatan orang dewasa (andragogi).', 'Pasal 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6369, 'perka-14-2009', 21, 'pasal', 'Pasal 19', 'BAB IV PEMBINAAN DAN PEMANTAUAN', 7, '(1) Peserta pelatihan yang telah mengikuti keseluruhan program pelatihan dan dinyatakan lulus, diberikan Sertifikat;
(2) Sertifikat sebagaimana dimaksud pada ayat (1) dikeluarkan oleh penyelenggara dan dilaporkan kepada Badan Nasional Penanggulangan Bencana;
(3) Brevet diberikan kepada peserta yang berprestasi bersamaan dengan pemberian sertifikat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6369, '(1) Peserta pelatihan yang telah mengikuti keseluruhan program pelatihan dan dinyatakan lulus, diberikan Sertifikat;
(2) Sertifikat sebagaimana dimaksud pada ayat (1) dikeluarkan oleh penyelenggara dan dilaporkan kepada Badan Nasional Penanggulangan Bencana;
(3) Brevet diberikan kepada peserta yang berprestasi bersamaan dengan pemberian sertifikat.', 'Pasal 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6370, 'perka-14-2009', 22, 'pasal', 'Pasal 20', 'BAB V KETENTUAN PENUTUP', 7, '(1) Pembinaan dan pengendalian mutu pelatihan, penyelenggara wajib melaporkan pelaksanaan penyelenggaraan pelatihan ke Kepala Badan Nasional Penanggulangan Bencana/Badan Penanggulangan Bencana Daerah.
(2) Badan Nasional Penanggulangan Bencana/Badan Penanggulangan Bencana Daerah memantau dan mengevaluasi terhadap pelaksanaan kegiatan pelatihan penanggulangan bencana yang diselenggarakan oleh instansi/lembaga/organisasi yang terkait dengan penanggulangan bencana sesuai dengan mandat dan kewenangannya berdasarkan pedoman yang ditetapkan oleh BNPB.
2014, No.1415 8');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6370, '(1) Pembinaan dan pengendalian mutu pelatihan, penyelenggara wajib melaporkan pelaksanaan penyelenggaraan pelatihan ke Kepala Badan Nasional Penanggulangan Bencana/Badan Penanggulangan Bencana Daerah.
(2) Badan Nasional Penanggulangan Bencana/Badan Penanggulangan Bencana Daerah memantau dan mengevaluasi terhadap pelaksanaan kegiatan pelatihan penanggulangan bencana yang diselenggarakan oleh instansi/lembaga/organisasi yang terkait dengan penanggulangan bencana sesuai dengan mandat dan kewenangannya berdasarkan pedoman yang ditetapkan oleh BNPB.
2014, No.1415 8', 'Pasal 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6371, 'perka-14-2009', 23, 'pasal', 'Pasal 21', 'BAB V KETENTUAN PENUTUP', 8, 'Hal-hal yang belum diatur dalam pedoman ini, akan diatur kemudian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6371, 'Hal-hal yang belum diatur dalam pedoman ini, akan diatur kemudian.', 'Pasal 21', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6372, 'perka-14-2009', 24, 'pasal', 'Pasal 22', 'BAB V KETENTUAN PENUTUP', 8, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6372, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6373, 'perka-14-2009', 25, 'lain', 'Penutup', NULL, 8, 'Ditetapkan di Jakarta pada tanggal 22 Desember 2009 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6373, 'Ditetapkan di Jakarta pada tanggal 22 Desember 2009 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2009 tentang Pedoman Umum Penyelenggaraan Pelatihan Penanggulangan Bencana');
