INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6376, 'perka-14-2010', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
