INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6377, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN PEMBENTUKAN POS KOMANDO TANGGAP DARURAT BENCANA', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6378, 'perka-14-2010', 4, 'pasal', 'Pasal 1', NULL, 2, 'Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana sebagaimana tersebut dalam Lampiran Peraturan ini merupakan pelaksanaan dari Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana yang tidak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6378, 'Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana sebagaimana tersebut dalam Lampiran Peraturan ini merupakan pelaksanaan dari Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana yang tidak terpisahkan dari Peraturan ini.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6379, 'perka-14-2010', 5, 'pasal', 'Pasal 2', NULL, 2, 'Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana sebagaimana dimaksud dalam Pasal 1, merupakan acuan bagi Pelaksana Komando Tanggap Darurat Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6379, 'Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana sebagaimana dimaksud dalam Pasal 1, merupakan acuan bagi Pelaksana Komando Tanggap Darurat Bencana.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6380, 'perka-14-2010', 6, 'pasal', 'Pasal 3', NULL, 2, 'Hal-hal yang belum diatur dalam Peraturan ini, akan diatur kemudian.');
