INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6381, 'perka-14-2010', 7, 'pasal', 'Pasal 4', NULL, 2, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6381, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6382, 'perka-14-2010', 8, 'lain', 'Penutup', NULL, 2, 'Ditetapkan di Jakarta pada tanggal 14 September 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA DR. SYAMSUL MAARIF, M.Si');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6382, 'Ditetapkan di Jakarta pada tanggal 14 September 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA DR. SYAMSUL MAARIF, M.Si', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6383, 'perka-14-2010', 9, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 14 TAHUN 2010 TANGGAL : 14 SEPTEMBER 2010 BAB I PENDAHULUAN A. Latar Belakang Sebagian besar wilayah Indonesia berpotensi rawan dan sering mengalami kejadian bencana, baik bencana alam, bencana nonalam, maupun bencana sosial. Kejadian bencana dapat menimbulkan keadaan darurat yang ditandai dengan terancamnya keselamatan dan kesejahteraan masyarakat. Hampir semua jenis bencana dapat menimbulkan korban jiwa, kerugian harta benda, dan rusaknya prasarana dan sarana publik. Untuk itu diperlukan penanganan yang cepat dan tepat guna mengurangi timbulnya dampak yang lebih buruk.
Dalam situasi darurat bencana, sering terjadi kesimpang-siuran data dan informasi korban maupun kerusakan, sehingga mempersulit pengambilan kebijakan penanganan darurat. Pelaksanaan tanggap darurat juga sering kurang saling mendukung, distribusi bantuan dan pelayanan kurang cepat, kurang merata, sulit terpantau dengan baik, sehingga kemajuan hasil kegiatan tanggap darurat bencana kurang bisa terukur secara objektif. Situasi-situasi tersebut disebabkan antara lain karena kurangnya koordinasi antar instansi terkait dalam kegiatan tanggap darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6383, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 14 TAHUN 2010 TANGGAL : 14 SEPTEMBER 2010 BAB I PENDAHULUAN A. Latar Belakang Sebagian besar wilayah Indonesia berpotensi rawan dan sering mengalami kejadian bencana, baik bencana alam, bencana nonalam, maupun bencana sosial. Kejadian bencana dapat menimbulkan keadaan darurat yang ditandai dengan terancamnya keselamatan dan kesejahteraan masyarakat. Hampir semua jenis bencana dapat menimbulkan korban jiwa, kerugian harta benda, dan rusaknya prasarana dan sarana publik. Untuk itu diperlukan penanganan yang cepat dan tepat guna mengurangi timbulnya dampak yang lebih buruk.
Dalam situasi darurat bencana, sering terjadi kesimpang-siuran data dan informasi korban maupun kerusakan, sehingga mempersulit pengambilan kebijakan penanganan darurat. Pelaksanaan tanggap darurat juga sering kurang saling mendukung, distribusi bantuan dan pelayanan kurang cepat, kurang merata, sulit terpantau dengan baik, sehingga kemajuan hasil kegiatan tanggap darurat bencana kurang bisa terukur secara objektif. Situasi-situasi tersebut disebabkan antara lain karena kurangnya koordinasi antar instansi terkait dalam kegiatan tanggap darurat bencana.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6384, 'perka-14-2010', 10, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'Dalam kondisi seperti ini, diperlukan suatu institusi yang menjadi pusat komando kedaruratan bencana sesuai dengan lokasi dan tingkatan bencana. Pos komando tanggap darurat bencana dapat dilengkapi dengan pembentukan pos komando lapangan tanggap darurat bencana dan pos pendukung tanggap darurat bencana, yang merupakan satu kesatuan sistem penanganan tanggap darurat bencana. Untuk dapat membentuk pos komando tanggap darurat bencana yang efektif dan efisien serta akuntabel, perlu disusun sebuah pedoman.
B. Maksud dan Tujuan
1. Maksud Pedoman ini dimaksudkan untuk menjadi panduan dalam pembentukan pos komando tanggap darurat dan pos komando lapangan ataupun pos pendukung di lokasi bencana.
2. Tujuan
a. Tersedianya acuan pembentukan pos komando tanggap darurat bencana, pos komando lapangan tanggap darurat bencana, dan pos pendukung tanggap darurat bencana.
b. Tersedianya acuan tata hubungan kerja diantara pos komando tanggap darurat bencana, pos komando lapangan tanggap darurat bencana, dan pos pendukung tanggap darurat bencana dalam rangka peningkatan koordinasi, pengendalian, pemantauan dan evaluasi kegiatan penanganan tanggap darurat bencana.
C. Landasan Hukum
1. Undang-Undang Republik Indonesia Nomor 32 Tahun 2004 tentang Pemerintahan Daerah.
2. Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
3. Peraturan Pemerintah Republik Indonesia No. 21 Tahun 2007 tentang Penyelenggaraan Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6384, 'Dalam kondisi seperti ini, diperlukan suatu institusi yang menjadi pusat komando kedaruratan bencana sesuai dengan lokasi dan tingkatan bencana. Pos komando tanggap darurat bencana dapat dilengkapi dengan pembentukan pos komando lapangan tanggap darurat bencana dan pos pendukung tanggap darurat bencana, yang merupakan satu kesatuan sistem penanganan tanggap darurat bencana. Untuk dapat membentuk pos komando tanggap darurat bencana yang efektif dan efisien serta akuntabel, perlu disusun sebuah pedoman.
B. Maksud dan Tujuan
1. Maksud Pedoman ini dimaksudkan untuk menjadi panduan dalam pembentukan pos komando tanggap darurat dan pos komando lapangan ataupun pos pendukung di lokasi bencana.
2. Tujuan
a. Tersedianya acuan pembentukan pos komando tanggap darurat bencana, pos komando lapangan tanggap darurat bencana, dan pos pendukung tanggap darurat bencana.
b. Tersedianya acuan tata hubungan kerja diantara pos komando tanggap darurat bencana, pos komando lapangan tanggap darurat bencana, dan pos pendukung tanggap darurat bencana dalam rangka peningkatan koordinasi, pengendalian, pemantauan dan evaluasi kegiatan penanganan tanggap darurat bencana.
C. Landasan Hukum
1. Undang-Undang Republik Indonesia Nomor 32 Tahun 2004 tentang Pemerintahan Daerah.
2. Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
3. Peraturan Pemerintah Republik Indonesia No. 21 Tahun 2007 tentang Penyelenggaraan Penanggulangan Bencana.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6385, 'perka-14-2010', 11, 'lampiran', 'Lampiran hal. 4', NULL, 4, '4. Peraturan Pemerintah Republik Indonesia No 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
5. Peraturan Pemerintah Republik Indonesia No 23 Tahun 2008 tentang Peran Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana.
6. Peraturan Presiden Republik Indonesia No. 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
7. Peraturan Menteri Dalam Negeri Republik Indonesia Nomor 46 Tahun 2008 tentang Pedoman Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah.
8. Peraturan Kepala BNPB Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja BNPB.
9. Peraturan Kepala BNPB Nomor 3 Tahun 2008 tentang Pedoman Pembentukan BPBD.
10. Peraturan Kepala BNPB Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana.
D. Pengertian Dalam buku pedoman ini yang dimaksud dengan :
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia, sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tangap darurat, dan rehabilitasi, serta rekonstruksi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6385, '4. Peraturan Pemerintah Republik Indonesia No 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
5. Peraturan Pemerintah Republik Indonesia No 23 Tahun 2008 tentang Peran Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana.
6. Peraturan Presiden Republik Indonesia No. 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
7. Peraturan Menteri Dalam Negeri Republik Indonesia Nomor 46 Tahun 2008 tentang Pedoman Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah.
8. Peraturan Kepala BNPB Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja BNPB.
9. Peraturan Kepala BNPB Nomor 3 Tahun 2008 tentang Pedoman Pembentukan BPBD.
10. Peraturan Kepala BNPB Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana.
D. Pengertian Dalam buku pedoman ini yang dimaksud dengan :
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia, sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tangap darurat, dan rehabilitasi, serta rekonstruksi.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6386, 'perka-14-2010', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, '3. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, serta pemulihan prasarana dan sarana.
4. Masa tanggap darurat bencana adalah jangka waktu tertentu yang ditetapkan oleh pemerintah atau pemerintah daerah.
5. Pos Komando Kedaruratan adalah pos komando yang dibentuk pada saat keadaan darurat yang meliputi tahap siaga darurat, tahap tanggap darurat dan transisi dari tahap tanggap darurat ke tahap pemulihan yang dapat berupa pos komando tanggap darurat dan atau pos komando lapangan dan pos pendukung yang merupakan satu kesatuan sistem penanganan darurat.
6. Pos Komando Tanggap Darurat Bencana adalah institusi yang berfungsi sebagai pusat komando operasi tanggap darurat bencana, untuk mengkoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan tanggap darurat bencana.
7. Pos Komando Lapangan Tanggap Darurat Bencana merupakan institusi yang bertugas melakukan penanganan tanggap darurat bencana secara langsung di lokasi bencana.
8. Pos Pendukung Tanggap Darurat Bencana adalah pos yang membantu kelancaran akses dan mobilisasi/distribusi bantuan tanggap darurat bencana.
9. Komando adalah kewenangan untuk memberikan perintah, mengkoordinasikan, mengendalikan, memantau dan mengevaluasi kegiatan tanggap darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6386, '3. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, serta pemulihan prasarana dan sarana.
4. Masa tanggap darurat bencana adalah jangka waktu tertentu yang ditetapkan oleh pemerintah atau pemerintah daerah.
5. Pos Komando Kedaruratan adalah pos komando yang dibentuk pada saat keadaan darurat yang meliputi tahap siaga darurat, tahap tanggap darurat dan transisi dari tahap tanggap darurat ke tahap pemulihan yang dapat berupa pos komando tanggap darurat dan atau pos komando lapangan dan pos pendukung yang merupakan satu kesatuan sistem penanganan darurat.
6. Pos Komando Tanggap Darurat Bencana adalah institusi yang berfungsi sebagai pusat komando operasi tanggap darurat bencana, untuk mengkoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan tanggap darurat bencana.
7. Pos Komando Lapangan Tanggap Darurat Bencana merupakan institusi yang bertugas melakukan penanganan tanggap darurat bencana secara langsung di lokasi bencana.
8. Pos Pendukung Tanggap Darurat Bencana adalah pos yang membantu kelancaran akses dan mobilisasi/distribusi bantuan tanggap darurat bencana.
9. Komando adalah kewenangan untuk memberikan perintah, mengkoordinasikan, mengendalikan, memantau dan mengevaluasi kegiatan tanggap darurat bencana.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6387, 'perka-14-2010', 13, 'lampiran', 'Lampiran hal. 6', NULL, 6, '10. Koordinasi adalah kegiatan memadukan peran dan fungsi sektor-sektor yang terkait secara proporsional, sinergis dan saling mendukung dalam penanganan tanggap darurat bencana.
11. Pengendalian adalah kegiatan pengarahan oleh pos komando tanggap darurat bencana kepada pos komando lapangan dalam pelaksanaan operasi tanggap darurat bencana.
12. Pemantauan adalah kegiatan mengamati pelaksanaan penanganan tanggap darurat bencana untuk memperoleh data dan informasi sebagai bahan memberikan arahan.
13. Evaluasi adalah kegiatan penilaian terhadap seluruh kegiatan tanggap darurat bencana baik oleh pos komando tanggap darurat bencana, pos komando lapangan maupun pos pendukung tanggap darurat bencana.
14. Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
15. Pemerintah Daerah adalah gubernur, bupati/walikota, atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
16. Lembaga Usaha adalah badan hukum yang dapat berbentuk badan usaha milik negara, badan usaha milik daerah, koperasi, atau swasta yang didirikan sesuai dengan ketentuan perundang-undangan yang menjalankan jenis usaha tetap dan terus menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6387, '10. Koordinasi adalah kegiatan memadukan peran dan fungsi sektor-sektor yang terkait secara proporsional, sinergis dan saling mendukung dalam penanganan tanggap darurat bencana.
11. Pengendalian adalah kegiatan pengarahan oleh pos komando tanggap darurat bencana kepada pos komando lapangan dalam pelaksanaan operasi tanggap darurat bencana.
12. Pemantauan adalah kegiatan mengamati pelaksanaan penanganan tanggap darurat bencana untuk memperoleh data dan informasi sebagai bahan memberikan arahan.
13. Evaluasi adalah kegiatan penilaian terhadap seluruh kegiatan tanggap darurat bencana baik oleh pos komando tanggap darurat bencana, pos komando lapangan maupun pos pendukung tanggap darurat bencana.
14. Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
15. Pemerintah Daerah adalah gubernur, bupati/walikota, atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
16. Lembaga Usaha adalah badan hukum yang dapat berbentuk badan usaha milik negara, badan usaha milik daerah, koperasi, atau swasta yang didirikan sesuai dengan ketentuan perundang-undangan yang menjalankan jenis usaha tetap dan terus menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6388, 'perka-14-2010', 14, 'lampiran', 'Lampiran hal. 6', NULL, 6, '17. Lembaga Swadaya Masyarakat (LSM) adalah organisasi masyarakat yang berbadan hukum dan tidak berbadan hukum, sebagai wadah partisipasi masyarakat dalam penanganan kedaruratan bencana.
18. Lembaga Internasional adalah organisasi yang berada dalam lingkup struktur organisasi Perserikatan Bangsa-Bangsa atau yang menjalankan tugas-tugas mewakili Perserikatan Bangsa-Bangsa atau organisasi internasional lainnya.
19. Lembaga asing non pemerintah adalah suatu organisasi internasional yang terorganisasi secara fungsional bebas dari dan tidak mewakili pemerintahan suatu negara atau organisasi internasional yang dibentuk secara terpisah dari suatu negara dimana organisasi itu didirikan.
E. Ruang Lingkup
1. Pedoman ini membahas pembentukan pos komando tanggap darurat bencana, pos komando lapangan tanggap darurat bencana, pos pendukung tanggap darurat bencana, dan mekanisme hubungan kerja.
2. Pedoman ini berlaku bagi pemerintah dan pemerintah daerah dalam pembentukan pos komando kedaruratan bencana, serta dapat dijadikan acuan bagi masyarakat dan lembaga usaha untuk berpartisipasi dalam tanggap darurat bencana.
F. Sistematika Pedoman ini disusun dengan sistematika : pendahuluan; pembentukan pos komando tanggap darurat bencana; pembentukan pos komando lapangan tanggap darurat bencana; pembentukan pos pendukung tanggap darurat bencana; mekanisme hubungan kerja, dan penutup.
BAB II PEMBENTUKAN POS KOMANDO TANGGAP DARURAT BENCANA A. Kedudukan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6388, '17. Lembaga Swadaya Masyarakat (LSM) adalah organisasi masyarakat yang berbadan hukum dan tidak berbadan hukum, sebagai wadah partisipasi masyarakat dalam penanganan kedaruratan bencana.
18. Lembaga Internasional adalah organisasi yang berada dalam lingkup struktur organisasi Perserikatan Bangsa-Bangsa atau yang menjalankan tugas-tugas mewakili Perserikatan Bangsa-Bangsa atau organisasi internasional lainnya.
19. Lembaga asing non pemerintah adalah suatu organisasi internasional yang terorganisasi secara fungsional bebas dari dan tidak mewakili pemerintahan suatu negara atau organisasi internasional yang dibentuk secara terpisah dari suatu negara dimana organisasi itu didirikan.
E. Ruang Lingkup
1. Pedoman ini membahas pembentukan pos komando tanggap darurat bencana, pos komando lapangan tanggap darurat bencana, pos pendukung tanggap darurat bencana, dan mekanisme hubungan kerja.
2. Pedoman ini berlaku bagi pemerintah dan pemerintah daerah dalam pembentukan pos komando kedaruratan bencana, serta dapat dijadikan acuan bagi masyarakat dan lembaga usaha untuk berpartisipasi dalam tanggap darurat bencana.
F. Sistematika Pedoman ini disusun dengan sistematika : pendahuluan; pembentukan pos komando tanggap darurat bencana; pembentukan pos komando lapangan tanggap darurat bencana; pembentukan pos pendukung tanggap darurat bencana; mekanisme hubungan kerja, dan penutup.
BAB II PEMBENTUKAN POS KOMANDO TANGGAP DARURAT BENCANA A. Kedudukan', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6389, 'perka-14-2010', 15, 'lampiran', 'Lampiran hal. 8', NULL, 8, '1. Pos Komando Tanggap Darurat Bencana Nasional berkedudukan di ibu kota negara, Pos Komando Tanggap Darurat Bencana Provinsi berkedudukan di ibu kota provinsi, Pos Komando Tanggap Darurat Bencana Kabupaten/Kota berkedudukan di ibukota kabupaten/kota atau di tempat lain sesuai kondisi yang ada.
2. Pada bencana skala nasional dapat dibentuk Pos Komando Tanggap Darurat Aju di provinsi dan pada bencana skala provinsi dapat dibentuk Pos Komando Tanggap Darurat Aju di kabupaten/kota yang terkena bencana.
3. Jangka waktu keberadaan pos komando tanggap darurat bencana bersifat sementara selama masa tanggap darurat dan beroperasi selama 24 (dua puluh empat) jam setiap hari serta dapat diperpanjang atau diperpendek waktunya sesuai dengan pelaksanaan tanggap darurat.
B. Persyaratan Lokasi
1. Pos Komando Tanggap Darurat Bencana dapat menempati bangunan atau tenda.
2. Bangunan atau tenda pos komando tanggap darurat bencana menempati lokasi yang strategis dengan kriteria:
a. mudah diakses oleh berbagai pihak yang terlibat dalam kegiatan tanggap darurat bencana.
b. aman dan terbebas dari ancaman bencana.
c. memiliki lahan parkir yang memadai.
d. luas lahan sekurang-kurangnya 500 m 2.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6389, '1. Pos Komando Tanggap Darurat Bencana Nasional berkedudukan di ibu kota negara, Pos Komando Tanggap Darurat Bencana Provinsi berkedudukan di ibu kota provinsi, Pos Komando Tanggap Darurat Bencana Kabupaten/Kota berkedudukan di ibukota kabupaten/kota atau di tempat lain sesuai kondisi yang ada.
2. Pada bencana skala nasional dapat dibentuk Pos Komando Tanggap Darurat Aju di provinsi dan pada bencana skala provinsi dapat dibentuk Pos Komando Tanggap Darurat Aju di kabupaten/kota yang terkena bencana.
3. Jangka waktu keberadaan pos komando tanggap darurat bencana bersifat sementara selama masa tanggap darurat dan beroperasi selama 24 (dua puluh empat) jam setiap hari serta dapat diperpanjang atau diperpendek waktunya sesuai dengan pelaksanaan tanggap darurat.
B. Persyaratan Lokasi
1. Pos Komando Tanggap Darurat Bencana dapat menempati bangunan atau tenda.
2. Bangunan atau tenda pos komando tanggap darurat bencana menempati lokasi yang strategis dengan kriteria:
a. mudah diakses oleh berbagai pihak yang terlibat dalam kegiatan tanggap darurat bencana.
b. aman dan terbebas dari ancaman bencana.
c. memiliki lahan parkir yang memadai.
d. luas lahan sekurang-kurangnya 500 m 2.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6390, 'perka-14-2010', 16, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'C. Proses Pembentukan Pembentukan Pos Komando Tanggap Darurat Bencana, dapat dilakukan pada tahap siaga darurat untuk jenis bencana yang terjadi secara berangsur-angsur, seperti banjir dan gunung meletus, atau segera setelah dinyatakan status bencana untuk jenis bencana yang terjadi secara tiba-tiba, seperti tanah longsor, gempa dan tsunami.
Untuk jenis bencana yang terjadi secara berangsur-angsur, pembentukan Pos Komando Tanggap Darurat Bencana dengan cara meningkatkan status Pusat Pengendali Operasi Wilayah Provinsi/ Kabupaten/Kota. Sedangkan untuk jenis bencana yang terjadi secara tiba-tiba, proses pembentukan pos komando tanggap darurat bencana, dilakukan melalui 4 (empat) tahapan yang harus dilaksanakan secara keseluruhan menjadi satu rangkaian sistem komando yang terpadu, yaitu:
1. Informasi Kejadian Awal Bencana Informasi awal data kejadian bencana dapat diperoleh melalui berbagai sumber antara lain laporan instansi/lembaga terkait, media massa, masyarakat, dan internet. Kebenaran informasi tersebut diatas perlu dikonfirmasi dengan pertanyaan apa, kapan, dimana, bagaimana, berapa, penyebab, akibat yang ditimbulkan dan upaya yang telah dilakukan serta kebutuhan yang mendesak.
2. Penugasan Tim Reaksi Cepat Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6390, 'C. Proses Pembentukan Pembentukan Pos Komando Tanggap Darurat Bencana, dapat dilakukan pada tahap siaga darurat untuk jenis bencana yang terjadi secara berangsur-angsur, seperti banjir dan gunung meletus, atau segera setelah dinyatakan status bencana untuk jenis bencana yang terjadi secara tiba-tiba, seperti tanah longsor, gempa dan tsunami.
Untuk jenis bencana yang terjadi secara berangsur-angsur, pembentukan Pos Komando Tanggap Darurat Bencana dengan cara meningkatkan status Pusat Pengendali Operasi Wilayah Provinsi/ Kabupaten/Kota. Sedangkan untuk jenis bencana yang terjadi secara tiba-tiba, proses pembentukan pos komando tanggap darurat bencana, dilakukan melalui 4 (empat) tahapan yang harus dilaksanakan secara keseluruhan menjadi satu rangkaian sistem komando yang terpadu, yaitu:
1. Informasi Kejadian Awal Bencana Informasi awal data kejadian bencana dapat diperoleh melalui berbagai sumber antara lain laporan instansi/lembaga terkait, media massa, masyarakat, dan internet. Kebenaran informasi tersebut diatas perlu dikonfirmasi dengan pertanyaan apa, kapan, dimana, bagaimana, berapa, penyebab, akibat yang ditimbulkan dan upaya yang telah dilakukan serta kebutuhan yang mendesak.
2. Penugasan Tim Reaksi Cepat Penanggulangan Bencana', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6391, 'perka-14-2010', 17, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'a. Dari informasi kejadian awal yang diperoleh, BPBD/SATLAK PB dan atau BNPB menugaskan Tim Reaksi Cepat (TRC BNPB/BPBD/SATLAK PB) tanggap darurat bencana, untuk melaksanakan tugas pengkajian secara cepat dan tepat, serta memberikan dukungan pendampingan dalam rangka kegiatan tanggap darurat.
b. Hasil pelaksanaan tugas TRC BNPB/BPBD/SATLAK PB tanggap darurat dan masukan dari berbagai instansi/lembaga terkait merupakan bahan pertimbangan bagi:
1) Kepala BPBD/SATLAK PB Kabupaten/Kota untuk mengusulkan kepada Bupati/Walikota dalam rangka menetapkan status/tingkat bencana skala kabupaten/kota.
2) Kepala BPBD Provinsi untuk mengusulkan kepada Gubernur dalam rangka menetapkan status/tingkat bencana skala provinsi.
3) Kepala BNPB untuk mengusulkan kepada Presiden RI dalam rangka menetapkan status/tingkat bencana skala nasional.
3. Penetapan Status/Tingkat Bencana
a. Berdasarkan usul sesuai butir 2b di atas maka :
1) Bupati/Walikota menetapkan status/tingkat bencana skala kabupaten/kota.
2) Gubernur menetapkan status/tingkat bencana skala provinsi.
3) Presiden RI menetapkan status/tingkat bencana skala nasional.
b. Tindak lanjut dari penetapan status/tingkat bencana tersebut, maka Kepala BNPB/BPBD Provinsi/BPBD/SATLAK PB Kabupaten/Kota sesuai dengan kewenangannya dapat menunjuk seorang pejabat sebagai komandan tanggap darurat bencana sesuai status/tingkat bencana skala nasional/daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6391, 'a. Dari informasi kejadian awal yang diperoleh, BPBD/SATLAK PB dan atau BNPB menugaskan Tim Reaksi Cepat (TRC BNPB/BPBD/SATLAK PB) tanggap darurat bencana, untuk melaksanakan tugas pengkajian secara cepat dan tepat, serta memberikan dukungan pendampingan dalam rangka kegiatan tanggap darurat.
b. Hasil pelaksanaan tugas TRC BNPB/BPBD/SATLAK PB tanggap darurat dan masukan dari berbagai instansi/lembaga terkait merupakan bahan pertimbangan bagi:
1) Kepala BPBD/SATLAK PB Kabupaten/Kota untuk mengusulkan kepada Bupati/Walikota dalam rangka menetapkan status/tingkat bencana skala kabupaten/kota.
2) Kepala BPBD Provinsi untuk mengusulkan kepada Gubernur dalam rangka menetapkan status/tingkat bencana skala provinsi.
3) Kepala BNPB untuk mengusulkan kepada Presiden RI dalam rangka menetapkan status/tingkat bencana skala nasional.
3. Penetapan Status/Tingkat Bencana
a. Berdasarkan usul sesuai butir 2b di atas maka :
1) Bupati/Walikota menetapkan status/tingkat bencana skala kabupaten/kota.
2) Gubernur menetapkan status/tingkat bencana skala provinsi.
3) Presiden RI menetapkan status/tingkat bencana skala nasional.
b. Tindak lanjut dari penetapan status/tingkat bencana tersebut, maka Kepala BNPB/BPBD Provinsi/BPBD/SATLAK PB Kabupaten/Kota sesuai dengan kewenangannya dapat menunjuk seorang pejabat sebagai komandan tanggap darurat bencana sesuai status/tingkat bencana skala nasional/daerah.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6392, 'perka-14-2010', 18, 'lampiran', 'Lampiran hal. 10', NULL, 10, '4. Pembentukan Pos Komando Tanggap Darurat Bencana Presiden/Gubernur/Bupati/Walikota atas usul Kepala BNPB/ BPBD Provinsi/BPBD/SATLAK PB Kabupaten/Kota sesuai status/tingkat bencana dan tingkat kewenangannya :
a. Mengeluarkan Surat Keputusan pembentukan Pos Komando Tanggap Darurat Bencana.
b. Melaksanakan mobilisasi sumberdaya manusia, peralatan dan logistik serta dana dari instansi/lembaga terkait dan/atau masyarakat.
c. Meresmikan pembentukan Pos Komando Tanggap Darurat Bencana.
d. Bilamana pemerintah kabupaten/kota atau provinsi tidak ada BPBD, maka yang melaksanakan pembentukan Pos Komando Tanggap Darurat adalah instansi/ Satuan Kerja Perangkat Daerah (SKPD) yang menangani bencana.
D. Pengorganisasian
1. Organisasi Pos Komando Tanggap Darurat Bencana merupakan organisasi satu komando, dengan mata rantai dan garis komando serta tanggung jawab yang jelas. Instansi/lembaga dapat dikoordinasikan dalam satu organisasi berdasarkan satu kesatuan komando. Organisasi ini dapat dibentuk di semua tingkatan wilayah bencana baik di tingkat kabupaten/kota, provinsi maupun tingkat nasional.
2. Struktur organisasi pos komando tanggap darurat terdiri atas Komandan yang dibantu oleh staf komando dan staf umum, secara lengkap terdiri dari:
a. Komandan Tanggap Darurat Bencana
b. Wakil Komandan Tanggap Darurat Bencana
c. Staf Komando:
1) Sekretariat 2) Hubungan Masyarakat 3) Keselamatan dan Keamanan 4) Perwakilan instansi/lembaga
d. Staf Umum:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6392, '4. Pembentukan Pos Komando Tanggap Darurat Bencana Presiden/Gubernur/Bupati/Walikota atas usul Kepala BNPB/ BPBD Provinsi/BPBD/SATLAK PB Kabupaten/Kota sesuai status/tingkat bencana dan tingkat kewenangannya :
a. Mengeluarkan Surat Keputusan pembentukan Pos Komando Tanggap Darurat Bencana.
b. Melaksanakan mobilisasi sumberdaya manusia, peralatan dan logistik serta dana dari instansi/lembaga terkait dan/atau masyarakat.
c. Meresmikan pembentukan Pos Komando Tanggap Darurat Bencana.
d. Bilamana pemerintah kabupaten/kota atau provinsi tidak ada BPBD, maka yang melaksanakan pembentukan Pos Komando Tanggap Darurat adalah instansi/ Satuan Kerja Perangkat Daerah (SKPD) yang menangani bencana.
D. Pengorganisasian
1. Organisasi Pos Komando Tanggap Darurat Bencana merupakan organisasi satu komando, dengan mata rantai dan garis komando serta tanggung jawab yang jelas. Instansi/lembaga dapat dikoordinasikan dalam satu organisasi berdasarkan satu kesatuan komando. Organisasi ini dapat dibentuk di semua tingkatan wilayah bencana baik di tingkat kabupaten/kota, provinsi maupun tingkat nasional.
2. Struktur organisasi pos komando tanggap darurat terdiri atas Komandan yang dibantu oleh staf komando dan staf umum, secara lengkap terdiri dari:
a. Komandan Tanggap Darurat Bencana
b. Wakil Komandan Tanggap Darurat Bencana
c. Staf Komando:
1) Sekretariat 2) Hubungan Masyarakat 3) Keselamatan dan Keamanan 4) Perwakilan instansi/lembaga
d. Staf Umum:', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6393, 'perka-14-2010', 19, 'lampiran', 'Lampiran hal. 11', NULL, 11, '1) Bidang Operasi 2) Bidang Perencanaan 3) Bidang Logistik, Peralatan, dan Pengelolaan Bantuan 4) Bidang Administrasi Keuangan
3. Struktur organisasi ini dapat diperluas sesuai kebutuhan.
4. Sesuai dengan jenis, kebutuhan dan kompleksitas bencana dapat dibentuk unit organisasi dalam bentuk seksi-seksi yang berada di bawah bidang dan dipimpin oleh Kepala Seksi yang bertanggung jawab kepada Kepala Bidang.
Bagan struktur organisasi Pos Komando Tanggap Darurat Bencana dan perwakilan instansi/lembaga/organisasi terkait dapat dilihat pada lampiran 1, 2, 3, 4, 5 dan 6.
E. Tugas Pokok dan Fungsi Organisasi
1. Pos Komando Tanggap Darurat Bencana memiliki tugas pokok untuk:
a. Melaksanakan pengumpulan informasi dengan menggunakan pertanyaan sebagaimana tersebut pada butir C.1 dan perkembangan informasi lapangan sebagai dasar penyusunan rencana Operasi Tanggap Darurat Bencana tingkat kabupaten/ kota/provinsi/nasional.
b. Menyusun rencana operasi penanganan tanggap darurat bencana.
c. Mengajukan permintaan kebutuhan bantuan.
d. Merencanakan, mengkoordinasikan, mengendalikan, memantau pengerahan sumberdaya untuk penanganan tanggap darurat bencana secara cepat, tepat, efektif dan efisien serta mengevaluasi pelaksanaan penanganan tanggap darurat.
e. Melaporkan pelaksanaan penanganan darurat kepada Kepala BNPB/BPBD Provinsi/BPBD/SATLAK PB Kabupaten/Kota.
f. Menyebarluaskan informasi mengenai kejadian bencana dan penanganannya kepada media massa dan masyarakat luas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6393, '1) Bidang Operasi 2) Bidang Perencanaan 3) Bidang Logistik, Peralatan, dan Pengelolaan Bantuan 4) Bidang Administrasi Keuangan
3. Struktur organisasi ini dapat diperluas sesuai kebutuhan.
4. Sesuai dengan jenis, kebutuhan dan kompleksitas bencana dapat dibentuk unit organisasi dalam bentuk seksi-seksi yang berada di bawah bidang dan dipimpin oleh Kepala Seksi yang bertanggung jawab kepada Kepala Bidang.
Bagan struktur organisasi Pos Komando Tanggap Darurat Bencana dan perwakilan instansi/lembaga/organisasi terkait dapat dilihat pada lampiran 1, 2, 3, 4, 5 dan 6.
E. Tugas Pokok dan Fungsi Organisasi
1. Pos Komando Tanggap Darurat Bencana memiliki tugas pokok untuk:
a. Melaksanakan pengumpulan informasi dengan menggunakan pertanyaan sebagaimana tersebut pada butir C.1 dan perkembangan informasi lapangan sebagai dasar penyusunan rencana Operasi Tanggap Darurat Bencana tingkat kabupaten/ kota/provinsi/nasional.
b. Menyusun rencana operasi penanganan tanggap darurat bencana.
c. Mengajukan permintaan kebutuhan bantuan.
d. Merencanakan, mengkoordinasikan, mengendalikan, memantau pengerahan sumberdaya untuk penanganan tanggap darurat bencana secara cepat, tepat, efektif dan efisien serta mengevaluasi pelaksanaan penanganan tanggap darurat.
e. Melaporkan pelaksanaan penanganan darurat kepada Kepala BNPB/BPBD Provinsi/BPBD/SATLAK PB Kabupaten/Kota.
f. Menyebarluaskan informasi mengenai kejadian bencana dan penanganannya kepada media massa dan masyarakat luas.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6394, 'perka-14-2010', 20, 'lampiran', 'Lampiran hal. 12', NULL, 12, '2. Fungsi Komando Tanggap Darurat Bencana adalah mengkoordinasikan, mengintegrasikan dan mensinkronisasikan seluruh unsur dalam organisasi komando tanggap darurat untuk pencarian, penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan pengungsi, serta pemulihan sarana dan prasarana vital dengan segera pada saat status siaga darurat dan tanggap darurat.
F. Tugas dan Tanggung Jawab Unit Organisasi
1. Komandan Tanggap Darurat Bencana
a. Komandan Tanggap Darurat Bencana adalah personil dengan pangkat/jabatan senior peringkat pertama dalam Komando Tanggap Darurat Bencana sesuai tingkat dan kewenangannya.
b. Komandan bertugas:
1) Mengaktifkan dan meningkatkan Pusat Pengendalian Operasi (Pusdalops) menjadi Pos Komando Tanggap Darurat BPBD Kabupaten/Kota/Provinsi atau BNPB, sesuai dengan jenis, lokasi dan tingkatan bencana.
2) Dapat membentuk Pos Komando Lapangan (Poskolap) di lokasi bencana di bawah komando Pos Komando Tanggap Darurat Bencana BPBD Kabupaten/ Kota/Provinsi atau BNPB.
3) Membuat rencana operasi, mengorganisasikan, melaksanakan dan mengendalikan operasi tanggap darurat bencana.
4) Melaksanakan komando dan pengendalian untuk pengerahan sumber daya manusia, peralatan, logistik dan penyelamatan serta berwenang memerintahkan para pejabat yang mewakili instansi/lembaga/organisasi yang terkait dalam memfasilitasi aksesibilitas penanganan tanggap darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6394, '2. Fungsi Komando Tanggap Darurat Bencana adalah mengkoordinasikan, mengintegrasikan dan mensinkronisasikan seluruh unsur dalam organisasi komando tanggap darurat untuk pencarian, penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan pengungsi, serta pemulihan sarana dan prasarana vital dengan segera pada saat status siaga darurat dan tanggap darurat.
F. Tugas dan Tanggung Jawab Unit Organisasi
1. Komandan Tanggap Darurat Bencana
a. Komandan Tanggap Darurat Bencana adalah personil dengan pangkat/jabatan senior peringkat pertama dalam Komando Tanggap Darurat Bencana sesuai tingkat dan kewenangannya.
b. Komandan bertugas:
1) Mengaktifkan dan meningkatkan Pusat Pengendalian Operasi (Pusdalops) menjadi Pos Komando Tanggap Darurat BPBD Kabupaten/Kota/Provinsi atau BNPB, sesuai dengan jenis, lokasi dan tingkatan bencana.
2) Dapat membentuk Pos Komando Lapangan (Poskolap) di lokasi bencana di bawah komando Pos Komando Tanggap Darurat Bencana BPBD Kabupaten/ Kota/Provinsi atau BNPB.
3) Membuat rencana operasi, mengorganisasikan, melaksanakan dan mengendalikan operasi tanggap darurat bencana.
4) Melaksanakan komando dan pengendalian untuk pengerahan sumber daya manusia, peralatan, logistik dan penyelamatan serta berwenang memerintahkan para pejabat yang mewakili instansi/lembaga/organisasi yang terkait dalam memfasilitasi aksesibilitas penanganan tanggap darurat bencana.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6395, 'perka-14-2010', 21, 'lampiran', 'Lampiran hal. 12', NULL, 12, '5) Melaksanakan evaluasi melalui rapat koordinasi yang dilaksanakan minimal satu kali dalam sehari untuk menyusun rencana kegiatan berikutnya.
c. Dalam pelaksanaan tugasnya Komandan Tanggap Darurat Bencana bertanggung jawab langsung kepada Presiden, Gubernur, Bupati/Walikota melalui Kepala BNPB/BPBD Provinsi/SATLAK PB Kabupaten/Kota.
2. Wakil Komandan Tanggap Darurat Bencana Wakil Komandan Tanggap Darurat Bencana adalah personil dengan pangkat/jabatan senior peringkat kedua dalam Komando Tanggap Darurat Bencana sesuai tingkat dan kewenangannya.
a. Wakil Komandan Tanggap Darurat Bencana bertugas:
1) Membantu Komandan Tanggap Darurat Bencana dalam merencanakan, mengorganisasikan, melaksanakan dan mengendalikan komando tanggap darurat bencana.
2) Mengkoordinir tugas-tugas sekretariat, humas, keselamatan dan keamanan serta perwakilan instansi/lembaga.
3) Mewakili Komandan Tanggap Darurat Bencana, apabila Komandan Tanggap Darurat Bencana berhalangan.
b. Wakil Komandan Tanggap Darurat Bencana bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
3. Sekretariat Sekretariat dipimpin oleh seorang Sekretaris.
a. Sekretaris bertugas dan bertanggung jawab untuk:
1) Menyelenggarakan administrasi umum dan pelaporan.
2) Pelayanan akomodasi dan konsumsi bagi personil Komando Tanggap Darurat Bencana.
b. Sekretaris bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
4. Hubungan Masyarakat
a. Hubungan Masyarakat bertugas dan bertanggung jawab untuk:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6395, '5) Melaksanakan evaluasi melalui rapat koordinasi yang dilaksanakan minimal satu kali dalam sehari untuk menyusun rencana kegiatan berikutnya.
c. Dalam pelaksanaan tugasnya Komandan Tanggap Darurat Bencana bertanggung jawab langsung kepada Presiden, Gubernur, Bupati/Walikota melalui Kepala BNPB/BPBD Provinsi/SATLAK PB Kabupaten/Kota.
2. Wakil Komandan Tanggap Darurat Bencana Wakil Komandan Tanggap Darurat Bencana adalah personil dengan pangkat/jabatan senior peringkat kedua dalam Komando Tanggap Darurat Bencana sesuai tingkat dan kewenangannya.
a. Wakil Komandan Tanggap Darurat Bencana bertugas:
1) Membantu Komandan Tanggap Darurat Bencana dalam merencanakan, mengorganisasikan, melaksanakan dan mengendalikan komando tanggap darurat bencana.
2) Mengkoordinir tugas-tugas sekretariat, humas, keselamatan dan keamanan serta perwakilan instansi/lembaga.
3) Mewakili Komandan Tanggap Darurat Bencana, apabila Komandan Tanggap Darurat Bencana berhalangan.
b. Wakil Komandan Tanggap Darurat Bencana bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
3. Sekretariat Sekretariat dipimpin oleh seorang Sekretaris.
a. Sekretaris bertugas dan bertanggung jawab untuk:
1) Menyelenggarakan administrasi umum dan pelaporan.
2) Pelayanan akomodasi dan konsumsi bagi personil Komando Tanggap Darurat Bencana.
b. Sekretaris bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
4. Hubungan Masyarakat
a. Hubungan Masyarakat bertugas dan bertanggung jawab untuk:', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6396, 'perka-14-2010', 22, 'lampiran', 'Lampiran hal. 13', NULL, 13, '1) Menghimpun data dan informasi penanganan bencana yang terjadi.
2) Membentuk jaringan informasi dan komunikasi serta menyebarkan informasi tentang bencana tersebut ke media massa dan masyarakat luas atas persetujuan komandan tanggap darurat.
3) Mendokumentasi semua kegiatan posko tanggap darurat.
b. Kepala Humas bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
5. Keselamatan dan Keamanan
a. Keselamatan dan Keamanan bertugas dan bertanggung jawab untuk:
1) Menyediakan pelayanan kesehatan dan keselamatan seluruh personil Komando Tanggap Darurat Bencana dalam menjalankan tugasnya.
2) Menjaga keamanan penanganan tanggap darurat bencana serta mengantisipasi hal-hal di luar dugaan atau suatu keadaan yang berbahaya.
3) Memantau keberadaan petugas/militer/relawan asing
b. Kepala Keselamatan dan Keamanan bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
6. Perwakilan Instansi/Lembaga
a. Perwakilan instansi/lembaga bertugas untuk membantu Komandan Tanggap Darurat Bencana berkaitan dengan permintaan dan pengerahan sumberdaya yang dibutuhkan dari instansi/lembaga.
b. Perwakilan instansi/lembaga secara operasional bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana atas pelaksanaan tugasnya dan secara administratif bertanggung jawab kepada pimpinan instansi/lembaga terkait.
7. Bidang Operasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6396, '1) Menghimpun data dan informasi penanganan bencana yang terjadi.
2) Membentuk jaringan informasi dan komunikasi serta menyebarkan informasi tentang bencana tersebut ke media massa dan masyarakat luas atas persetujuan komandan tanggap darurat.
3) Mendokumentasi semua kegiatan posko tanggap darurat.
b. Kepala Humas bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
5. Keselamatan dan Keamanan
a. Keselamatan dan Keamanan bertugas dan bertanggung jawab untuk:
1) Menyediakan pelayanan kesehatan dan keselamatan seluruh personil Komando Tanggap Darurat Bencana dalam menjalankan tugasnya.
2) Menjaga keamanan penanganan tanggap darurat bencana serta mengantisipasi hal-hal di luar dugaan atau suatu keadaan yang berbahaya.
3) Memantau keberadaan petugas/militer/relawan asing
b. Kepala Keselamatan dan Keamanan bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
6. Perwakilan Instansi/Lembaga
a. Perwakilan instansi/lembaga bertugas untuk membantu Komandan Tanggap Darurat Bencana berkaitan dengan permintaan dan pengerahan sumberdaya yang dibutuhkan dari instansi/lembaga.
b. Perwakilan instansi/lembaga secara operasional bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana atas pelaksanaan tugasnya dan secara administratif bertanggung jawab kepada pimpinan instansi/lembaga terkait.
7. Bidang Operasi', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6397, 'perka-14-2010', 23, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'a. Bidang Operasi bertugas melaksanakan operasi pencarian, penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan pengungsi, serta pemulihan prasarana dan sarana vital dengan cepat, tepat, efisien dan efektif berdasarkan satu kesatuan rencana tindakan penanganan tanggap darurat bencana.
b. Kepala Bidang Operasi bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
8. Bidang Perencanaan
a. Bidang Perencanaan bertugas mengumpulkan, menginventarisir sumberdaya (personil, peralatan, dan dana) yang ada di masing-masing instansi, mengevaluasi, menganalisis data dan informasi yang berhubungan dengan penanganan tanggap darurat bencana serta menyiapkan dokumen rencana operasi tanggap darurat.
b. Kepala Bidang Perencanaan bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
9. Bidang Logistik, Peralatan dan Pengelolaan Bantuan
a. Bidang Logistik, Peralatan dan Pengelolaan Bantuan, bertugas:
1) Menyediakan fasilitas, jasa, dan bahan-bahan serta perlengkapan tanggap darurat.
2) Melaksanakan penerimaan, penyimpanan, pendistribusian dan transportasi bantuan logistik dan peralatan.
3) Melaksanakan penyelenggaraan dukungan dapur umum, air bersih dan sanitasi umum.
4) Mengkoordinasikan semua bantuan logistik dan peralatan dari instansi/ lembaga/organisasi yang terkait.
b. Kepala Bidang Logistik, Peralatan dan Pengelolaan Bantuan bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
10. Bidang Administrasi Keuangan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6397, 'a. Bidang Operasi bertugas melaksanakan operasi pencarian, penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan pengungsi, serta pemulihan prasarana dan sarana vital dengan cepat, tepat, efisien dan efektif berdasarkan satu kesatuan rencana tindakan penanganan tanggap darurat bencana.
b. Kepala Bidang Operasi bertanggung jawab langsung kepada Komandan Tanggap Darurat Bencana.
