INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6399, 'perka-14-2010', 25, 'lampiran', 'Lampiran hal. 16', NULL, 16, 'k. Peta Lokasi (geografi, peta lokasi wilayah terjadi, topografi)
l. Peta/Data Logistik (pangan dan nonpangan)
m. Peta/Data Personil
n. Peta/Data bantuan
o. Peta/Data Kebutuhan
p. Peta/Data Peralatan
q. Peta/Data NGO lokal dan asing
r. Jam dinding (waktu lokal, nasional, dan internasional)
s. Buku jurnal
t. Dan lain-lain H. Pembiayaan Biaya operasional Pos Komando Darurat Bencana bersumber dari:
1. APBD Kabupaten/Kota
2. APBD Provinsi
3. APBN
4. Bantuan lain yang tidak mengikat.
BAB III PEMBENTUKAN POS KOMANDO LAPANGAN TANGGAP DARURAT BENCANA A. Kedudukan
1. Pos Komando Lapangan Tanggap Darurat Bencana merupakan tempat berkoordinasi berbagai sumber daya penanganan kedaruratan bencana pada kesatuan wilayah lokasi bencana atau titik bencana, yang dikendalikan oleh komandan Posko Lapangan.
2. Wilayah kerja masing-masing Pos Komando Lapangan Tanggap Darurat Bencana mencakup satu kesatuan wilayah dimana bencana terjadi atau membawahi sebanyak-banyaknya dua kesatuan wilayah bencana jika salah satu kesatuan wilayah tersebut mengalami kelumpuhan total akibat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6399, 'k. Peta Lokasi (geografi, peta lokasi wilayah terjadi, topografi)
l. Peta/Data Logistik (pangan dan nonpangan)
m. Peta/Data Personil
n. Peta/Data bantuan
o. Peta/Data Kebutuhan
p. Peta/Data Peralatan
q. Peta/Data NGO lokal dan asing
r. Jam dinding (waktu lokal, nasional, dan internasional)
s. Buku jurnal
t. Dan lain-lain H. Pembiayaan Biaya operasional Pos Komando Darurat Bencana bersumber dari:
1. APBD Kabupaten/Kota
2. APBD Provinsi
3. APBN
4. Bantuan lain yang tidak mengikat.
BAB III PEMBENTUKAN POS KOMANDO LAPANGAN TANGGAP DARURAT BENCANA A. Kedudukan
1. Pos Komando Lapangan Tanggap Darurat Bencana merupakan tempat berkoordinasi berbagai sumber daya penanganan kedaruratan bencana pada kesatuan wilayah lokasi bencana atau titik bencana, yang dikendalikan oleh komandan Posko Lapangan.
2. Wilayah kerja masing-masing Pos Komando Lapangan Tanggap Darurat Bencana mencakup satu kesatuan wilayah dimana bencana terjadi atau membawahi sebanyak-banyaknya dua kesatuan wilayah bencana jika salah satu kesatuan wilayah tersebut mengalami kelumpuhan total akibat bencana.', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6400, 'perka-14-2010', 26, 'lampiran', 'Lampiran hal. 17', NULL, 17, '3. Jangka waktu keberadaan pos komando lapangan tanggap darurat bencana bersifat sementara, dan beroperasi selama 24 (dua puluh empat) jam setiap hari selama masa tanggap darurat bencana, serta dapat diperpanjang atau di perpendek sesuai dengan kebutuhan B. Persyaratan Lokasi Pos Komando Lapangan Tanggap Darurat Bencana dapat menempati bangunan yang ada atau menempati tenda yang didirikan pada lokasi yang idealnya memenuhi kriteria sebagai berikut :
1. Tempat yang cukup luas yang bisa menampung beberapa tenda.
2. Berdekatan dengan akses jalan utama memasuki wilayah bencana
3. Berdekatan dengan lokasi pengungsian
4. Lokasi aman dan terbebas dari ancaman bencana.
C. Proses Pembentukan Pos Komando Lapangan Tanggap Darurat Bencana dibentuk oleh Komandan Pos Komando Tanggap Darurat Kabupaten/Kota. Jika pemerintah kabupaten/kota tersebut tidak berfungsi akibat bencana, maka pembentukannya dilakukan oleh Komandan Pos Komando Tanggap Darurat Provinsi. Bila Pemerintah Provinsi tersebut tidak berfungsi akibat bencana, maka pembentukannya dilakukan oleh Komandan Pos Komando Tanggap Darurat Nasional.
Pembentukan Pos Komando Lapangan Tanggap Darurat dilakukan sesegera mungkin setelah kejadian bencana.
D. Tugas Pokok Tugas Pokok Pos Komando Lapangan Tanggap Darurat Bencana adalah menjamin berjalannya operasi tanggap darurat oleh berbagai pihak secara terpimpin, terkoordinasi, efektif dan efisien di lokasi bencana.
E. Fungsi Pos komando lapangan tanggap darurat bencana berfungsi :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6400, '3. Jangka waktu keberadaan pos komando lapangan tanggap darurat bencana bersifat sementara, dan beroperasi selama 24 (dua puluh empat) jam setiap hari selama masa tanggap darurat bencana, serta dapat diperpanjang atau di perpendek sesuai dengan kebutuhan B. Persyaratan Lokasi Pos Komando Lapangan Tanggap Darurat Bencana dapat menempati bangunan yang ada atau menempati tenda yang didirikan pada lokasi yang idealnya memenuhi kriteria sebagai berikut :
1. Tempat yang cukup luas yang bisa menampung beberapa tenda.
2. Berdekatan dengan akses jalan utama memasuki wilayah bencana
3. Berdekatan dengan lokasi pengungsian
4. Lokasi aman dan terbebas dari ancaman bencana.
C. Proses Pembentukan Pos Komando Lapangan Tanggap Darurat Bencana dibentuk oleh Komandan Pos Komando Tanggap Darurat Kabupaten/Kota. Jika pemerintah kabupaten/kota tersebut tidak berfungsi akibat bencana, maka pembentukannya dilakukan oleh Komandan Pos Komando Tanggap Darurat Provinsi. Bila Pemerintah Provinsi tersebut tidak berfungsi akibat bencana, maka pembentukannya dilakukan oleh Komandan Pos Komando Tanggap Darurat Nasional.
Pembentukan Pos Komando Lapangan Tanggap Darurat dilakukan sesegera mungkin setelah kejadian bencana.
D. Tugas Pokok Tugas Pokok Pos Komando Lapangan Tanggap Darurat Bencana adalah menjamin berjalannya operasi tanggap darurat oleh berbagai pihak secara terpimpin, terkoordinasi, efektif dan efisien di lokasi bencana.
E. Fungsi Pos komando lapangan tanggap darurat bencana berfungsi :', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6401, 'perka-14-2010', 27, 'lampiran', 'Lampiran hal. 18', NULL, 18, '1. Sebagai tempat berkumpul semua sumber daya untuk melaksanakan tanggap darurat pada wilayah kerja Pos Komando Lapangan.
2. Sebagai tempat mengkoordinasikan, mengintegrasikan dan mensinkronisasikan upaya-upaya tanggap darurat yang dilakukan oleh instansi/organisasi terkait;
3. Sebagai tempat mengerahkan dan mengendalikan kegiatan tanggap darurat bencana di lokasi bencana yang menjadi wilayah kerja Pos Komando Lapangan.
F. Uraian Tugas Uraian tugas Pos Komando Lapangan Tanggap Darurat Bencana adalah:
1. Melanjutkan kegiatan asesmen cepat terhadap kejadian bencana yang telah dilakukan oleh Tim Reaksi Cepat;
2. Melakukan kegiatan pencarian, penyelamatan, dan evakuasi korban bencana;
3. Memberikan pelayanan pemenuhan kebutuhan dasar bagi korban bencana;
4. Memberikan perlindungan terhadap korban bencana yang rentan;
5. Memberikan pelayanan kepada korban bencana yang mengungsi;
6. Melakukan perbaikan prasarana dan sarana vital dengan segera.
G. Struktur Struktur Pos Komando Lapangan Tanggap Darurat sekurang-kurangnya terdiri atas:
1. Komandan Posko,
2. Wakil Komandan Posko
3. Perwakilan instansi/lembaga
4. Sekretariat yang membawahi :
a. Sub Bagian Data, Informasi dan Komunikasi
b. Sub Bagian Administrasi
5. Bidang SAR
6. Bidang Dapur Umum Lapangan (DUMLAP),
7. Bidang Logistik, Peralatan dan Pengelolaan Bantuan
8. Bidang Layanan Kesehatan dan Psiko-sosial.
9. Bidang Pemulihan Darurat Prasarana dan Sarana Vital');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6401, '1. Sebagai tempat berkumpul semua sumber daya untuk melaksanakan tanggap darurat pada wilayah kerja Pos Komando Lapangan.
2. Sebagai tempat mengkoordinasikan, mengintegrasikan dan mensinkronisasikan upaya-upaya tanggap darurat yang dilakukan oleh instansi/organisasi terkait;
3. Sebagai tempat mengerahkan dan mengendalikan kegiatan tanggap darurat bencana di lokasi bencana yang menjadi wilayah kerja Pos Komando Lapangan.
F. Uraian Tugas Uraian tugas Pos Komando Lapangan Tanggap Darurat Bencana adalah:
1. Melanjutkan kegiatan asesmen cepat terhadap kejadian bencana yang telah dilakukan oleh Tim Reaksi Cepat;
2. Melakukan kegiatan pencarian, penyelamatan, dan evakuasi korban bencana;
3. Memberikan pelayanan pemenuhan kebutuhan dasar bagi korban bencana;
4. Memberikan perlindungan terhadap korban bencana yang rentan;
5. Memberikan pelayanan kepada korban bencana yang mengungsi;
6. Melakukan perbaikan prasarana dan sarana vital dengan segera.
G. Struktur Struktur Pos Komando Lapangan Tanggap Darurat sekurang-kurangnya terdiri atas:
1. Komandan Posko,
2. Wakil Komandan Posko
3. Perwakilan instansi/lembaga
4. Sekretariat yang membawahi :
a. Sub Bagian Data, Informasi dan Komunikasi
b. Sub Bagian Administrasi
5. Bidang SAR
6. Bidang Dapur Umum Lapangan (DUMLAP),
7. Bidang Logistik, Peralatan dan Pengelolaan Bantuan
8. Bidang Layanan Kesehatan dan Psiko-sosial.
9. Bidang Pemulihan Darurat Prasarana dan Sarana Vital', 'Lampiran hal. 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6402, 'perka-14-2010', 28, 'lampiran', 'Lampiran hal. 19', NULL, 19, '10. Bidang Keselamatan dan Keamanan Struktur tersebut masih bisa ditambah atau dikurangi sesuai dengan kebutuhan pada masing-masing kabupaten/kota yang mengalami bencana. Bagan struktur Pos Komando Lapangan Tanggap Darurat, leading sector dan keanggotaannya dapat dilihat pada lampiran 7 dan 8.
H. Uraian Tugas Jabatan dan Tanggungjawab
1. Komandan Pos Komando Lapangan Tanggap Darurat Bencana
a. Komandan Posko Lapangan Tanggap Darurat Bencana adalah salah seorang pejabat dari unsur Pemda atau TNI atau Kepolisian wilayah setempat yang ditunjuk oleh Komandan Pos Komando Lapangan yang ditunjuk oleh Komandan Posko Tanggap Darurat.
b. Uraian Tugas Komandan Posko Lapangan:
1) Mengaktifkan Pos Komando Lapangan sebagai Pusat Pengendalian Operasi (Pusdalops) Tanggap Darurat di satu titik lokasi bencana.
2) Membuat rencana operasi, mengorganisasikan, melaksanakan dan mengendalikan operasi tanggap darurat bencana.
3) Menempatkan petugas perwakilan instansi/lembaga/ organisasi terkait ke dalam bidang-bidang yang relevan.
4) Memimpin rapat-rapat Posko untuk memerintahkan, mengkoordinasikan, mensinergikan dan mensinkronisasikan operasi bidang-bidang.
5) Melaksanakan evaluasi melalui rapat koordinasi yang dilaksanakan minimal satu kali dalam sehari untuk menyusun rencana kegiatan berikutnya.
c. Komandan Posko Lapangan Tanggap Darurat Bencana bertanggungjawab kepada Komandan Tanggap Darurat Tingkat Kabupaten/Kota.
2. Wakil Komandan Pos Komando Lapangan Tanggap Darurat Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6402, '10. Bidang Keselamatan dan Keamanan Struktur tersebut masih bisa ditambah atau dikurangi sesuai dengan kebutuhan pada masing-masing kabupaten/kota yang mengalami bencana. Bagan struktur Pos Komando Lapangan Tanggap Darurat, leading sector dan keanggotaannya dapat dilihat pada lampiran 7 dan 8.
H. Uraian Tugas Jabatan dan Tanggungjawab
1. Komandan Pos Komando Lapangan Tanggap Darurat Bencana
a. Komandan Posko Lapangan Tanggap Darurat Bencana adalah salah seorang pejabat dari unsur Pemda atau TNI atau Kepolisian wilayah setempat yang ditunjuk oleh Komandan Pos Komando Lapangan yang ditunjuk oleh Komandan Posko Tanggap Darurat.
b. Uraian Tugas Komandan Posko Lapangan:
1) Mengaktifkan Pos Komando Lapangan sebagai Pusat Pengendalian Operasi (Pusdalops) Tanggap Darurat di satu titik lokasi bencana.
2) Membuat rencana operasi, mengorganisasikan, melaksanakan dan mengendalikan operasi tanggap darurat bencana.
3) Menempatkan petugas perwakilan instansi/lembaga/ organisasi terkait ke dalam bidang-bidang yang relevan.
4) Memimpin rapat-rapat Posko untuk memerintahkan, mengkoordinasikan, mensinergikan dan mensinkronisasikan operasi bidang-bidang.
5) Melaksanakan evaluasi melalui rapat koordinasi yang dilaksanakan minimal satu kali dalam sehari untuk menyusun rencana kegiatan berikutnya.
c. Komandan Posko Lapangan Tanggap Darurat Bencana bertanggungjawab kepada Komandan Tanggap Darurat Tingkat Kabupaten/Kota.
2. Wakil Komandan Pos Komando Lapangan Tanggap Darurat Bencana', 'Lampiran hal. 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6403, 'perka-14-2010', 29, 'lampiran', 'Lampiran hal. 20', NULL, 20, 'a. Wakil Komandan Pos Komando Lapangan Tanggap Darurat Bencana adalah salah seorang pejabat dari unsur Pemda, TNI atau Kepolisian wilayah setempat yang ditunjuk oleh Komandan Pos Komando Lapangan.
b. Uraian Tugas Wakil Komandan Posko Lapangan :
1) Membantu Komandan Posko Lapangan dalam merencanakan, mengorganisasikan, melaksanakan dan mengendalikan operasi tanggap darurat bencana.
2) Mengkoordinir tugas-tugas bagian sekretariat mencakup sub bagian Data, Informasi dan Komunikasi, Sub Bagian Layanan Internal, dan Sub Bagian Administrasi umum, keuangan intern dan pelaporan 3) Mewakili Komandan Posko Lapangan apabila berhalangan.
c. Wakil Komandan Pos Komando Lapangan Tanggap Darurat Bencana bertanggungjawab langsung kepada Kepala Pos Komando Lapangan.
3. Sekretariat
a. Sekretariat dipimpin oleh seorang Sekretaris dibantu Kepala Sub Bagian Data, Informasi dan Komunikasi; dan Kepala Sub Bagian Administrasi
b. Jabatan Sekretaris ditunjuk oleh Komandan Posko Lapangan dari unsur Pemda, TNI atau Kepolisian Wilayah setempat.
c. Jabatan Kepala Sub Bagian Data, Informasi dan Komunikasi ditunjuk oleh Komandan Posko Lapangan dari unsur Pemda atau BPBD, dengan staff dari unsur penyelenggara radio komunikasi seperti RAPI, ORARI, dan lain-lain.
d. Jabatan Kepala Sub Bagian Administrasi beserta beberapa staff ditunjuk oleh Komandan Posko Lapangan dari unsur BPBD/SATLAK PB.
e. Uraian Tugas Sekretariat:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6403, 'a. Wakil Komandan Pos Komando Lapangan Tanggap Darurat Bencana adalah salah seorang pejabat dari unsur Pemda, TNI atau Kepolisian wilayah setempat yang ditunjuk oleh Komandan Pos Komando Lapangan.
b. Uraian Tugas Wakil Komandan Posko Lapangan :
1) Membantu Komandan Posko Lapangan dalam merencanakan, mengorganisasikan, melaksanakan dan mengendalikan operasi tanggap darurat bencana.
2) Mengkoordinir tugas-tugas bagian sekretariat mencakup sub bagian Data, Informasi dan Komunikasi, Sub Bagian Layanan Internal, dan Sub Bagian Administrasi umum, keuangan intern dan pelaporan 3) Mewakili Komandan Posko Lapangan apabila berhalangan.
c. Wakil Komandan Pos Komando Lapangan Tanggap Darurat Bencana bertanggungjawab langsung kepada Kepala Pos Komando Lapangan.
3. Sekretariat
a. Sekretariat dipimpin oleh seorang Sekretaris dibantu Kepala Sub Bagian Data, Informasi dan Komunikasi; dan Kepala Sub Bagian Administrasi
b. Jabatan Sekretaris ditunjuk oleh Komandan Posko Lapangan dari unsur Pemda, TNI atau Kepolisian Wilayah setempat.
c. Jabatan Kepala Sub Bagian Data, Informasi dan Komunikasi ditunjuk oleh Komandan Posko Lapangan dari unsur Pemda atau BPBD, dengan staff dari unsur penyelenggara radio komunikasi seperti RAPI, ORARI, dan lain-lain.
d. Jabatan Kepala Sub Bagian Administrasi beserta beberapa staff ditunjuk oleh Komandan Posko Lapangan dari unsur BPBD/SATLAK PB.
e. Uraian Tugas Sekretariat:', 'Lampiran hal. 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6404, 'perka-14-2010', 30, 'lampiran', 'Lampiran hal. 21', NULL, 21, '1) Mengumpulkan, mengolah dan menyajikan data dan informasi tentang kronologis dan dampak bencana, serta menilai kerugian bencana secara cepat.
2) Membentuk jaringan informasi dan komunikasi serta menyebarkan informasi tentang bencana tersebut serta penanggulangannya ke media massa cetak dan elektronik serta masyarakat luas.
3) Menyelenggarakan administrasi umum, keuangan, dan personil.
4) Pelayanan akomodasi dan konsumsi bagi personil bidang-bidang operasional Pos Komando Lapangan Tanggap Darurat Bencana.
f. Tanggungjawab :
1) Sekretaris bertanggungjawab langsung kepada Komandan Posko Lapangan 2) Kepala Sub Bagian Data, Informasi dan Komunikasi bertanggungjawab langsung kepada Sekretaris 3) Kepala Sub Bagian Administrasi bertanggungjawab langsung kepada Sekretaris.
4. Bidang SAR
a. Bidang SAR dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/dinas/lembaga/organisasi yang bergerak dibidang SAR, beranggotakan para petugas dari instansi/ dinas/lembaga/organisasi/ relawan yang bergerak dibidang SAR.
b. Uraian tugas koordinator bidang SAR 1) Membuat rencana operasi SAR 2) Menghimpun dan mengkoordinasikan petugas/relawan dibidang SAR 3) Memimpin kegiatan pencarian, penyelamatan, dan evakuasi korban bencana 4) Mengkoordinasikan hasil kegiatan dengan sekretariat.
c. Koordinator Bidang SAR bertanggung jawab langsung kepada Komandan Posko Lapangan.
5. Bidang Dapur Umum Lapangan (DUMLAP)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6404, '1) Mengumpulkan, mengolah dan menyajikan data dan informasi tentang kronologis dan dampak bencana, serta menilai kerugian bencana secara cepat.
2) Membentuk jaringan informasi dan komunikasi serta menyebarkan informasi tentang bencana tersebut serta penanggulangannya ke media massa cetak dan elektronik serta masyarakat luas.
3) Menyelenggarakan administrasi umum, keuangan, dan personil.
4) Pelayanan akomodasi dan konsumsi bagi personil bidang-bidang operasional Pos Komando Lapangan Tanggap Darurat Bencana.
f. Tanggungjawab :
1) Sekretaris bertanggungjawab langsung kepada Komandan Posko Lapangan 2) Kepala Sub Bagian Data, Informasi dan Komunikasi bertanggungjawab langsung kepada Sekretaris 3) Kepala Sub Bagian Administrasi bertanggungjawab langsung kepada Sekretaris.
4. Bidang SAR
a. Bidang SAR dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/dinas/lembaga/organisasi yang bergerak dibidang SAR, beranggotakan para petugas dari instansi/ dinas/lembaga/organisasi/ relawan yang bergerak dibidang SAR.
b. Uraian tugas koordinator bidang SAR 1) Membuat rencana operasi SAR 2) Menghimpun dan mengkoordinasikan petugas/relawan dibidang SAR 3) Memimpin kegiatan pencarian, penyelamatan, dan evakuasi korban bencana 4) Mengkoordinasikan hasil kegiatan dengan sekretariat.
c. Koordinator Bidang SAR bertanggung jawab langsung kepada Komandan Posko Lapangan.
5. Bidang Dapur Umum Lapangan (DUMLAP)', 'Lampiran hal. 21', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6405, 'perka-14-2010', 31, 'lampiran', 'Lampiran hal. 22', NULL, 22, 'a. Bidang DUMLAP dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/dinas/lembaga/organisasi yang bergerak dibidang Dapur Umum Lapangan. Bidang Dapur Umum Lapangan beranggotakan para petugas dari instansi/dinas/lembaga /organisasi/relawan yang bergerak dibidang DUMLAP.
b. Uraian tugas koordinator bidang DUMLAP 1) Menghimpun dan mengkoordinasikan petugas/relawan dibidang DUMLAP 2) Memimpin kegiatan DUMLAP untuk kepentingan korban bencana.
3) Mengkoordinasikan hasil kegiatan dengan sekretariat.
c. Koordinator Bidang DUMLAP bertanggung jawab langsung kepada Komandan Posko Lapangan.
6. Bidang Logistik-Peralatan dan Pengelolaan Bantuan
a. Bidang Logistik-Peralatan dan Pengelolaan Bantuan dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/dinas/lembaga/organisasi yang bergerak dibidang logistik dan peralatan tanggap darurat.
Bidang Logistik-Peralatan dan Pengelolaan Bantuan beranggotakan para petugas dari instansi/dinas/lembaga/ organisasi yang bergerak dibidang logistik dan peralatan tanggap darurat dan para relawan yang mengabdikan diri membantu tugas-tugas bidang logistik, peralatan dan pengelolaan bantuan.
b. Uraian tugas koordinator bidang Logistik- Peralatan dan Pengelolaan Bantuan 1) Menyediakan fasilitas, jasa, dan bahan-bahan serta perlengkapan tanggap darurat.
2) Menerima, mengadministrasikan, dan menyalurkan bantuan pangan, sandang dan keuangan kepada korban bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6405, 'a. Bidang DUMLAP dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/dinas/lembaga/organisasi yang bergerak dibidang Dapur Umum Lapangan. Bidang Dapur Umum Lapangan beranggotakan para petugas dari instansi/dinas/lembaga /organisasi/relawan yang bergerak dibidang DUMLAP.
b. Uraian tugas koordinator bidang DUMLAP 1) Menghimpun dan mengkoordinasikan petugas/relawan dibidang DUMLAP 2) Memimpin kegiatan DUMLAP untuk kepentingan korban bencana.
3) Mengkoordinasikan hasil kegiatan dengan sekretariat.
c. Koordinator Bidang DUMLAP bertanggung jawab langsung kepada Komandan Posko Lapangan.
6. Bidang Logistik-Peralatan dan Pengelolaan Bantuan
a. Bidang Logistik-Peralatan dan Pengelolaan Bantuan dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/dinas/lembaga/organisasi yang bergerak dibidang logistik dan peralatan tanggap darurat.
Bidang Logistik-Peralatan dan Pengelolaan Bantuan beranggotakan para petugas dari instansi/dinas/lembaga/ organisasi yang bergerak dibidang logistik dan peralatan tanggap darurat dan para relawan yang mengabdikan diri membantu tugas-tugas bidang logistik, peralatan dan pengelolaan bantuan.
b. Uraian tugas koordinator bidang Logistik- Peralatan dan Pengelolaan Bantuan 1) Menyediakan fasilitas, jasa, dan bahan-bahan serta perlengkapan tanggap darurat.
2) Menerima, mengadministrasikan, dan menyalurkan bantuan pangan, sandang dan keuangan kepada korban bencana.', 'Lampiran hal. 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6406, 'perka-14-2010', 32, 'lampiran', 'Lampiran hal. 22', NULL, 22, '3) Mengkoordinasikan semua bantuan logistik dan peralatan dari instansi/ lembaga/organisasi yang terkait.
4) Membuat pengajuan bantuan sesuai kebutuhan korban bencana kepada Komando Tanggap Darurat Bencana tingkat kab/Kota 5) Mendukung penyelenggaraan Bidang DUMLAP, air bersih dan sanitasi umum.
6) Mengkoordinasikan kegiatan dengan sekretariat.
c. Koordinator Bidang Logistik-Peralatan dan Pengelolaan Bantuan bertanggung jawab langsung kepada Komandan Posko Lapangan.
7. Bidang Layanan Kesehatan dan Psikososial
a. Bidang Layanan Kesehatan dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/dinas/lembaga/organisasi yang bergerak dibidang pelayanan kesehatan dan psikososial untuk korban bencana.
Bidang Layanan Kesehatan dan Psikososial beranggotakan para petugas dari instansi/dinas/lembaga/ organisasi yang bergerak dibidang pelayanan kesehatan dan psikososial serta para relawan yang mengabdikan diri membantu tugas-tugas bidang pelayanan kesehatan dan psikososial bagi korban bencana.
b. Uraian tugas koordinator bidang Layanan Kesehatan dan Psikososial 1) Menyusun rencana kerja di bidang layanan kesehatan dan Psikososial 2) Menghimpun dan mengkoordinasikan petugas/relawan di bidang layanan kesehatan dan Psikososial 3) Memimpin kegiatan layanan kesehatan dan psikososial bagi korban bencana.
4) Mengkoordinasikan hasil kegiatan dengan sekretariat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6406, '3) Mengkoordinasikan semua bantuan logistik dan peralatan dari instansi/ lembaga/organisasi yang terkait.
4) Membuat pengajuan bantuan sesuai kebutuhan korban bencana kepada Komando Tanggap Darurat Bencana tingkat kab/Kota 5) Mendukung penyelenggaraan Bidang DUMLAP, air bersih dan sanitasi umum.
6) Mengkoordinasikan kegiatan dengan sekretariat.
c. Koordinator Bidang Logistik-Peralatan dan Pengelolaan Bantuan bertanggung jawab langsung kepada Komandan Posko Lapangan.
7. Bidang Layanan Kesehatan dan Psikososial
a. Bidang Layanan Kesehatan dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/dinas/lembaga/organisasi yang bergerak dibidang pelayanan kesehatan dan psikososial untuk korban bencana.
Bidang Layanan Kesehatan dan Psikososial beranggotakan para petugas dari instansi/dinas/lembaga/ organisasi yang bergerak dibidang pelayanan kesehatan dan psikososial serta para relawan yang mengabdikan diri membantu tugas-tugas bidang pelayanan kesehatan dan psikososial bagi korban bencana.
b. Uraian tugas koordinator bidang Layanan Kesehatan dan Psikososial 1) Menyusun rencana kerja di bidang layanan kesehatan dan Psikososial 2) Menghimpun dan mengkoordinasikan petugas/relawan di bidang layanan kesehatan dan Psikososial 3) Memimpin kegiatan layanan kesehatan dan psikososial bagi korban bencana.
4) Mengkoordinasikan hasil kegiatan dengan sekretariat.', 'Lampiran hal. 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6407, 'perka-14-2010', 33, 'lampiran', 'Lampiran hal. 23', NULL, 23, 'c. Koordinator Bidang Layanan Kesehatan dan Psikososial bertanggung jawab langsung kepada Komandan Posko Lapangan.
8. Bidang Pemulihan Darurat Prasarana dan Sarana Vital
a. Bidang Pemulihan Darurat Prasarana dan Sarana Vital dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/dinas/lembaga/ organisasi yang bergerak dibidang Pemulihan Darurat Prasarana dan Sarana Vital. Bidang Pemulihan Darurat Prasarana dan Sarana Vital beranggotakan para petugas dari instansi/dinas/lembaga/organisasi/relawan yang bergerak dibidang Pemulihan Darurat Prasarana dan Sarana Vital.
b. Uraian tugas koordinator bidang Pemulihan Darurat Prasarana dan Sarana Vital 1) Menyusun rencana kerja di bidang Pemulihan Darurat Prasarana dan Sarana Vital 2) Menghimpun dan mengkoordinasikan petugas/relawan di bidang Pemulihan Darurat Prasarana dan Sarana Vital 3) Memimpin kegiatan Pemulihan Darurat Prasarana dan Sarana Vital.
4) Mengkoordinasikan hasil kegiatan dengan sekretariat.
c. Koordinator Bidang Pemulihan Darurat Prasarana dan Sarana Vital bertanggung jawab langsung kepada Komandan Posko Lapangan.
9. Bidang Keselamatan dan Keamanan
a. Bidang Keselamatan dan Keamanan dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan.
b. Uraian tugas koordinator bidang Keselamatan dan Keamanan adalah:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6407, 'c. Koordinator Bidang Layanan Kesehatan dan Psikososial bertanggung jawab langsung kepada Komandan Posko Lapangan.
8. Bidang Pemulihan Darurat Prasarana dan Sarana Vital
a. Bidang Pemulihan Darurat Prasarana dan Sarana Vital dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/dinas/lembaga/ organisasi yang bergerak dibidang Pemulihan Darurat Prasarana dan Sarana Vital. Bidang Pemulihan Darurat Prasarana dan Sarana Vital beranggotakan para petugas dari instansi/dinas/lembaga/organisasi/relawan yang bergerak dibidang Pemulihan Darurat Prasarana dan Sarana Vital.
b. Uraian tugas koordinator bidang Pemulihan Darurat Prasarana dan Sarana Vital 1) Menyusun rencana kerja di bidang Pemulihan Darurat Prasarana dan Sarana Vital 2) Menghimpun dan mengkoordinasikan petugas/relawan di bidang Pemulihan Darurat Prasarana dan Sarana Vital 3) Memimpin kegiatan Pemulihan Darurat Prasarana dan Sarana Vital.
4) Mengkoordinasikan hasil kegiatan dengan sekretariat.
c. Koordinator Bidang Pemulihan Darurat Prasarana dan Sarana Vital bertanggung jawab langsung kepada Komandan Posko Lapangan.
9. Bidang Keselamatan dan Keamanan
a. Bidang Keselamatan dan Keamanan dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan.
b. Uraian tugas koordinator bidang Keselamatan dan Keamanan adalah:', 'Lampiran hal. 23', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6408, 'perka-14-2010', 34, 'lampiran', 'Lampiran hal. 24', NULL, 24, '1) Menyusun rencana kerja di bidang keselamatan dan keamanan 2) Menghimpun dan mengkoordinasikan petugas/relawan di bidang keselamatan dan keamanan 3) Menjaga keamanan dan keselamatan petugas/relawan tanggap darurat, posko lapangan tanggap darurat, dan masyakata serta lokasi bencana.
4) Mengkoordinasikan hasil kegiatan dengan sekretariat.
c. Koordinator Bidang Keselamatan dan Keamanan bertanggung jawab langsung kepada Komandan Posko Lapangan
