INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6417, 'perka-14-2010', 43, 'lampiran', 'Lampiran hal. 32', NULL, 32, '2. Mekanisme permintaan bantuan sumber daya :
a. Komandan Posko Lapangan Tanggap Darurat mengajukan permintaan bantuan sumberdaya baik berupa sumberdaya manusia, logistik maupun peralatan kepada Komandan Posko Tanggap Darurat Kabupaten/ kota/BPBD provinsi dan BNPB, berdasarkan atas kekurangan sumberdaya yang tersedia di lokasi dan tingkat kewenangannya.
b. Komandan Posko Tanggap Darurat Bencana Kabupaten/Kota meneruskan permintaan bantuan sumber daya kepada BPBD Provinsi
c. Kepala BPBD Provinsi meneruskan permintaan bantuan sumber daya kepada BNPB
3. Mekanisme Mobilisasi/pengerahan bantuan sumberdaya
a. Komandan Posko Tanggap Darurat Bencana Kabupaten/Kota/BPBD Provinsi dan BNPB melakukan analisis permintaan bantuan
b. Jika persediaan bantuan cukup memadai, selanjutnya :
1) BNPB mengerahkan bantuan sumberdaya melalui BPBD Provinsi atau secara langsung ke Posko Lapangan Tanggap Darurat Bencana dengan didampingi Pejabat BPBD Provinsi dan Posko Tanggap Darurat Kabupaten/Kota.
2) BPBD Provinsi mengerahkan bantuan sumberdaya melalui Posko Tanggap Darurat Kabupaten/Kota atau secara langsung ke Posko Lapangan Tanggap Darurat Bencana dengan didampingi Pejabat Posko Tanggap Darurat Kabupaten/Kota.
3) Komandan Posko Tanggap Darurat Bencana Kabupaten/Kota mengerahkan bantuan sumberdaya secara langsung ke Posko Lapangan Tanggap Darurat.');
