INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6418, 'perka-14-2010', 44, 'lampiran', 'Lampiran hal. 33', NULL, 33, 'c. Jika persediaan bantuan sumberdaya tidak memadai, maka Komandan Posko Tanggap Darurat Bencana Kabupaten/Kota memerintahkan Komandan Pos Pendukung Tanggap Darurat Bencana Kabupaten/Kota untuk mengerahkan bantuan sumberdaya ke Posko Lapangan Tanggap Darurat.
4. Mekanisme pelaporan Setelah bantuan sumberdaya dioperasionalkan, selanjutnya selambat-lambatnya dalam kurun waktu dua minggu sejak masa tanggap darurat bencana dinyatakan berakhir:
a. Komandan Posko Lapangan Tanggap Darurat Bencana melaporkan penggunaan bantuan sumberdaya kepada Komandan Posko Tanggap Darurat Kabupaten/Kota/ BPBD Provinsi/ BNPB sesuai dengan bantuan sumberdaya yang diterima dan digunakan.
b. Komandan Posko Tanggap Darurat Kabupaten/Kota memberikan laporan kepada Kepala BPBD/SKPD Kabupaten/Kota dan BPBD Provinsi tentang rekapitulasi permintaan dan penggunaan bantuan sumberdaya oleh semua Posko Lapangan Tanggap Darurat Bencana yang berada di wilayahnya.
c. BPBD Provinsi memberikan laporan kepada BNPB tentang rekapitulasi permintaan dan penggunaan bantuan sumberdaya oleh Posko Tanggap Darurat Bencana Kabupaten/Kota Mekanisme hubungan kerja Pos Komando Tanggap Darurat Bencana sebagaimana diuraikan diatas, disajikan dalam bentuk bagan yang dapat dilihat dalam lampiran 10, 11 dan 12.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6418, 'c. Jika persediaan bantuan sumberdaya tidak memadai, maka Komandan Posko Tanggap Darurat Bencana Kabupaten/Kota memerintahkan Komandan Pos Pendukung Tanggap Darurat Bencana Kabupaten/Kota untuk mengerahkan bantuan sumberdaya ke Posko Lapangan Tanggap Darurat.
4. Mekanisme pelaporan Setelah bantuan sumberdaya dioperasionalkan, selanjutnya selambat-lambatnya dalam kurun waktu dua minggu sejak masa tanggap darurat bencana dinyatakan berakhir:
a. Komandan Posko Lapangan Tanggap Darurat Bencana melaporkan penggunaan bantuan sumberdaya kepada Komandan Posko Tanggap Darurat Kabupaten/Kota/ BPBD Provinsi/ BNPB sesuai dengan bantuan sumberdaya yang diterima dan digunakan.
b. Komandan Posko Tanggap Darurat Kabupaten/Kota memberikan laporan kepada Kepala BPBD/SKPD Kabupaten/Kota dan BPBD Provinsi tentang rekapitulasi permintaan dan penggunaan bantuan sumberdaya oleh semua Posko Lapangan Tanggap Darurat Bencana yang berada di wilayahnya.
c. BPBD Provinsi memberikan laporan kepada BNPB tentang rekapitulasi permintaan dan penggunaan bantuan sumberdaya oleh Posko Tanggap Darurat Bencana Kabupaten/Kota Mekanisme hubungan kerja Pos Komando Tanggap Darurat Bencana sebagaimana diuraikan diatas, disajikan dalam bentuk bagan yang dapat dilihat dalam lampiran 10, 11 dan 12.', 'Lampiran hal. 33', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6419, 'perka-14-2010', 45, 'lampiran', 'Lampiran hal. 35', NULL, 35, 'BAB VI PENUTUP Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana disusun untuk dijadikan acuan bagi BNPB/BPBD/SATLAK PB Kabupaten/Kota, dalam pembentukan Pos Komando Tanggap Darurat Bencana, Pos Komando Lapangan Tanggap Darurat Bencana dan Pos Pendukung Tanggap Darurat Bencana di lokasi bencana, sehingga kegiatan tanggap darurat bencana akan lebih terkoordinasi, terarah, terpantau dan dapat dievaluasi secara lebih objektif.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA DR. SYAMSUL MAARIF, Lampiran 1 BAGAN STRUKTUR POS KOMANDO TANGGAP DARURAT BENCANA KABUPATEN/KOTA Bupati/ Walikota Kepala BPBD/ Satlak PB Kabupaten/Kota Dinas/ Lembaga Teknis/ Organisasi terkait Komandan Wakil Komandan Sekretariat Perwakilan Dinas/ Lembaga Teknis/ Organisasi terkait Humas Keselamatan & Keamanan Bidang Bidang Logistik, Bidang Perencanaan Bidang Peralatan &Penge- Administrasi Operasi lolaan Bantuan Keuangan Seksi Seksi Seksi Seksi Seksi Seksi Seksi Seksi Keterangan :
Garis Komando Lampiran 2 PERWAKILAN DINAS/LEMBAGA TEKNIS/ORGANISASI TERKAIT DALAM POSKO TANGGAP DARURAT BENCANA KABUPATEN/KOTA
1. Badan Penanggulangan Bencana Daerah (BPBD) Kabupaten/Kota
2. Komando Distrik Militer (KODIM)
3. Kepolisian Resort (POLRES) atau Kepolisian Kota Besar (POLTABES)
4. Dinas Kesehatan
5. Dinas Pendidikan
6. Dinas Sosial
7. Dinas Perhubungan
8. Dinas Pertambangan dan Energi
9. Dinas Pekerjaan Umum
10. Dinas Permukiman dan Perumahan
11. Kantor Departemen Agama
12. Dinas Pengelolaan Sumber Daya Air');
