INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6420, 'perka-14-2010', 46, 'lampiran', 'Lampiran hal. 37', NULL, 37, '13. Dinas Energi & Sumber Daya Mineral
14. Dinas Kehutanan
