INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6425, 'perka-14-2010', 51, 'lampiran', 'Lampiran hal. 45', NULL, 45, 'Garis Komando 0 Lampiran 10 BAGAN MEKANISME HUBUNGAN KERJA POS KOMANDO TANGGAP DARURAT BENCANA NASIONAL BNPB Pusdalops s Posko TD Nasional Pos Pendukung TD Nasional BPBD Provinsi Pusdalops PoskoTD Provinsi Pos Pendukung TD Provinsi BPBD /OPD Pusdalops Kab/Kota Posko TD Kab/Kota Pos Pendukung TD Kab/Kota Posko Lapangan TD Keterangan : Garis Komando :
Garis Koordinasi Garis permintaan bantuan Garis Mobilisasi bantuan 1 Garis pelaporan Lampiran 11 BAGAN MEKANISME HUBUNGAN KERJA POS KOMANDO TANGGAP DARURAT BENCANA PROVINSI BNPB BPBD Provinsi Pusdalops PoskoTD Provinsi Pos Pendukung TD Provinsi BPBD /OPD Pusdalops Kab/Kota Posko TD Kab/Kota Pos Pendukung TD Kab/Kota Posko Lapangan TD Keterangan : Garis Komando Garis Koordinasi Garis permintaan bantuan Garis Mobilisasi bantuan Garis pelaporan 2 Lampiran 12 BAGAN MEKANISME HUBUNGAN KERJA POS KOMANDO TANGGAP DARURAT BENCANA KABUPATEN/KOTA BNPB BPBD Provinsi BPBD /OPD Pusdalops Kab/Kota Posko TD Kab/Kota Pos Pendukung TD Kab/Kota Posko Lapangan TD Keterangan : Garis Komando Garis Koordinasi Garis permintaan bantuan Garis Mobilisasi bantuan Garis pelaporan 3 PEDOMAN PEMBENTUKAN POS KOMANDO KEDARURATAN BENCANA BADAN NASIONAL PENANGGULANGAN BENCANA JAKARTA 2009 4 LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : TAHUN 2009 TANGGAL :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6425, 'Garis Komando 0 Lampiran 10 BAGAN MEKANISME HUBUNGAN KERJA POS KOMANDO TANGGAP DARURAT BENCANA NASIONAL BNPB Pusdalops s Posko TD Nasional Pos Pendukung TD Nasional BPBD Provinsi Pusdalops PoskoTD Provinsi Pos Pendukung TD Provinsi BPBD /OPD Pusdalops Kab/Kota Posko TD Kab/Kota Pos Pendukung TD Kab/Kota Posko Lapangan TD Keterangan : Garis Komando :
Garis Koordinasi Garis permintaan bantuan Garis Mobilisasi bantuan 1 Garis pelaporan Lampiran 11 BAGAN MEKANISME HUBUNGAN KERJA POS KOMANDO TANGGAP DARURAT BENCANA PROVINSI BNPB BPBD Provinsi Pusdalops PoskoTD Provinsi Pos Pendukung TD Provinsi BPBD /OPD Pusdalops Kab/Kota Posko TD Kab/Kota Pos Pendukung TD Kab/Kota Posko Lapangan TD Keterangan : Garis Komando Garis Koordinasi Garis permintaan bantuan Garis Mobilisasi bantuan Garis pelaporan 2 Lampiran 12 BAGAN MEKANISME HUBUNGAN KERJA POS KOMANDO TANGGAP DARURAT BENCANA KABUPATEN/KOTA BNPB BPBD Provinsi BPBD /OPD Pusdalops Kab/Kota Posko TD Kab/Kota Pos Pendukung TD Kab/Kota Posko Lapangan TD Keterangan : Garis Komando Garis Koordinasi Garis permintaan bantuan Garis Mobilisasi bantuan Garis pelaporan 3 PEDOMAN PEMBENTUKAN POS KOMANDO KEDARURATAN BENCANA BADAN NASIONAL PENANGGULANGAN BENCANA JAKARTA 2009 4 LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : TAHUN 2009 TANGGAL :', 'Lampiran hal. 45', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6426, 'perka-14-2010', 52, 'lampiran', 'Lampiran hal. 50', NULL, 50, 'BAB I PENDAHULUAN G. Latar Belakang Sebagian besar wilayah Indonesia berpotensi rawan dan sering mengalami kejadian bencana, baik bencana alam, bencana nonalam, maupun bencana sosial. Kejadian bencana dapat menimbulkan keadaan darurat yang ditandai dengan terancamnya keselamatan dan kesejahteraan masyarakat. Hampir semua jenis bencana dapat menimbulkan korban jiwa, kerugian harta benda, dan rusaknya prasarana dan sarana publik. Untuk itu diperlukan penanganan yang cepat dan tepat guna mengurangi timbulnya dampak yang lebih buruk.
Dalam situasi darurat bencana, sering terjadi simpang-siur data dan informasi korban maupun kerusakan, sehingga mempersulit dalam pengambilan kebijakan penanganan darurat. Pelaksanaan tanggap darurat juga sering kurang saling mendukung, distribusi bantuan dan pelayanan yang kurang cepat, kurang merata, sulit terpantau dengan baik, serta kemajuan hasil kegiatan tanggap darurat bencana kurang bisa terukur secara objektif. Situasi-situasi tersebut disebabkan antara lain karena kurang adanya koordinasi antar instansi terkait dalam kegiatan tanggap darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6426, 'BAB I PENDAHULUAN G. Latar Belakang Sebagian besar wilayah Indonesia berpotensi rawan dan sering mengalami kejadian bencana, baik bencana alam, bencana nonalam, maupun bencana sosial. Kejadian bencana dapat menimbulkan keadaan darurat yang ditandai dengan terancamnya keselamatan dan kesejahteraan masyarakat. Hampir semua jenis bencana dapat menimbulkan korban jiwa, kerugian harta benda, dan rusaknya prasarana dan sarana publik. Untuk itu diperlukan penanganan yang cepat dan tepat guna mengurangi timbulnya dampak yang lebih buruk.
Dalam situasi darurat bencana, sering terjadi simpang-siur data dan informasi korban maupun kerusakan, sehingga mempersulit dalam pengambilan kebijakan penanganan darurat. Pelaksanaan tanggap darurat juga sering kurang saling mendukung, distribusi bantuan dan pelayanan yang kurang cepat, kurang merata, sulit terpantau dengan baik, serta kemajuan hasil kegiatan tanggap darurat bencana kurang bisa terukur secara objektif. Situasi-situasi tersebut disebabkan antara lain karena kurang adanya koordinasi antar instansi terkait dalam kegiatan tanggap darurat bencana.', 'Lampiran hal. 50', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6427, 'perka-14-2010', 53, 'lampiran', 'Lampiran hal. 50', NULL, 50, 'Dalam kondisi seperti ini, diperlukan suatu institusi yang menjadi pusat komando kedaruratan bencana, sesuai dengan lokasi dan tingkatan bencana pos komando tanggap darurat bencana dapat dilengkapi dengan pembentukan pos komando lapangan tanggap darurat bencana dan pos pendukung tanggap darurat bencana, yang merupakan satu kesatuan sistem penanganan tanggap darurat bencana. Untuk dapat membentuk pos komando kedaruratan bencana yang efektif dan efisien serta akuntabel, perlu disusun sebuah pedoman.
5 H. Maksud dan Tujuan
1. Maksud Pedoman ini dimaksudkan untuk menjadi panduan dalam pembentukan pos komando tanggap darurat dan pos komando lapangan ataupun pos pendukung di lokasi bencana.
2. Tujuan
a. Tersedianya acuan pembentukan pos komando tanggap darurat bencana, pos komando lapangan tanggap darurat bencana, dan pos pendukung tanggap darurat bencana.
c. Tersedianya acuan tata hubungan kerja diantara pos komando tanggap darurat bencana, pos komando lapangan tanggap darurat bencana, dan pos pendukung tanggap darurat bencana dalam rangka peningkatan koordinasi, pengendalian, pemantauan dan evaluasi kegiatan penanganan tanggap darurat bencana.
I. Landasan Hukum
11. Undang-Undang Republik Indonesia Nomor 32 Tahun 2004 tentang Pemerintahan Daerah
12. Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
13. Peraturan Pemerintah Republik Indonesia No. 21 Tahun 2007 tentang Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6427, 'Dalam kondisi seperti ini, diperlukan suatu institusi yang menjadi pusat komando kedaruratan bencana, sesuai dengan lokasi dan tingkatan bencana pos komando tanggap darurat bencana dapat dilengkapi dengan pembentukan pos komando lapangan tanggap darurat bencana dan pos pendukung tanggap darurat bencana, yang merupakan satu kesatuan sistem penanganan tanggap darurat bencana. Untuk dapat membentuk pos komando kedaruratan bencana yang efektif dan efisien serta akuntabel, perlu disusun sebuah pedoman.
5 H. Maksud dan Tujuan
1. Maksud Pedoman ini dimaksudkan untuk menjadi panduan dalam pembentukan pos komando tanggap darurat dan pos komando lapangan ataupun pos pendukung di lokasi bencana.
2. Tujuan
a. Tersedianya acuan pembentukan pos komando tanggap darurat bencana, pos komando lapangan tanggap darurat bencana, dan pos pendukung tanggap darurat bencana.
c. Tersedianya acuan tata hubungan kerja diantara pos komando tanggap darurat bencana, pos komando lapangan tanggap darurat bencana, dan pos pendukung tanggap darurat bencana dalam rangka peningkatan koordinasi, pengendalian, pemantauan dan evaluasi kegiatan penanganan tanggap darurat bencana.
I. Landasan Hukum
11. Undang-Undang Republik Indonesia Nomor 32 Tahun 2004 tentang Pemerintahan Daerah
12. Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
13. Peraturan Pemerintah Republik Indonesia No. 21 Tahun 2007 tentang Penyelenggaraan Penanggulangan Bencana', 'Lampiran hal. 50', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6428, 'perka-14-2010', 54, 'lampiran', 'Lampiran hal. 51', NULL, 51, '14. Peraturan Pemerintah Republik Indonesia No 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
15. Peraturan Pemerintah Republik Indonesia No 23 Tahun 2008 tentang Peran Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana.
16. Peraturan Presiden Republik Indonesia No. 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
17. Peraturan Menteri Dalam Negeri Republik Indonesia Nomor 46 Tahun 2008 tentang Pedoman Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah.
18.Peraturan Kepala BNPB Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja BNPB 6
19. Peraturan Kepala BNPB Nomor 3 Tahun 2008 tentang Pedoman Pembentukan BPBD
20. Peraturan Kepala BNPB Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana J. Pengertian Dalam buku pedoman ini yang dimaksud dengan :
20. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia, sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
21. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tangap darurat, dan rehabilitasi, serta rekonstruksi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6428, '14. Peraturan Pemerintah Republik Indonesia No 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
15. Peraturan Pemerintah Republik Indonesia No 23 Tahun 2008 tentang Peran Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana.
16. Peraturan Presiden Republik Indonesia No. 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
17. Peraturan Menteri Dalam Negeri Republik Indonesia Nomor 46 Tahun 2008 tentang Pedoman Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah.
18.Peraturan Kepala BNPB Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja BNPB 6
19. Peraturan Kepala BNPB Nomor 3 Tahun 2008 tentang Pedoman Pembentukan BPBD
20. Peraturan Kepala BNPB Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana J. Pengertian Dalam buku pedoman ini yang dimaksud dengan :
20. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia, sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
21. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tangap darurat, dan rehabilitasi, serta rekonstruksi.', 'Lampiran hal. 51', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6429, 'perka-14-2010', 55, 'lampiran', 'Lampiran hal. 52', NULL, 52, '22. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, serta pemulihan prasarana dan sarana.
23. Masa tanggap darurat bencana adalah jangka waktu tertentu yang ditetapkan oleh pemerintah atau pemerintah daerah.
24. Pos Komando Kedaruratan adalah pos komando yang dibentuk pada saat keadaan darurat yang meliputi tahap siaga darurat, tahap tanggap darurat dan transisi dari tahap tanggap darurat ke tahap pemulihan yang dapat berupa pos komando tanggap darurat dan atau pos komando lapangan dan pos pendukung yang merupakan satu kesatuan sistem penanganan darurat.
25. Pos Komando Tanggap Darurat Bencana adalah institusi yang berfungsi sebagai pusat komando operasi tanggap darurat bencana, untuk mengkoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan tanggap darurat bencana.
7
26. Pos Komando Lapangan Tanggap Darurat Bencana merupakan institusi yang bertugas melakukan penanganan tanggap darurat bencana secara langsung di lokasi bencana.
27. Pos Pendukung Tanggap Darurat Bencana adalah pos yang membantu kelancaran akses dan mobilisasi/distribusi bantuan tanggap darurat bencana.
28. Komando adalah kewenangan untuk memberikan perintah, mengkoordinasikan, mengendalikan, memantau dan mengevaluasi kegiatan tanggap darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6429, '22. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, serta pemulihan prasarana dan sarana.
23. Masa tanggap darurat bencana adalah jangka waktu tertentu yang ditetapkan oleh pemerintah atau pemerintah daerah.
24. Pos Komando Kedaruratan adalah pos komando yang dibentuk pada saat keadaan darurat yang meliputi tahap siaga darurat, tahap tanggap darurat dan transisi dari tahap tanggap darurat ke tahap pemulihan yang dapat berupa pos komando tanggap darurat dan atau pos komando lapangan dan pos pendukung yang merupakan satu kesatuan sistem penanganan darurat.
25. Pos Komando Tanggap Darurat Bencana adalah institusi yang berfungsi sebagai pusat komando operasi tanggap darurat bencana, untuk mengkoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan tanggap darurat bencana.
7
26. Pos Komando Lapangan Tanggap Darurat Bencana merupakan institusi yang bertugas melakukan penanganan tanggap darurat bencana secara langsung di lokasi bencana.
27. Pos Pendukung Tanggap Darurat Bencana adalah pos yang membantu kelancaran akses dan mobilisasi/distribusi bantuan tanggap darurat bencana.
28. Komando adalah kewenangan untuk memberikan perintah, mengkoordinasikan, mengendalikan, memantau dan mengevaluasi kegiatan tanggap darurat bencana.', 'Lampiran hal. 52', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6430, 'perka-14-2010', 56, 'lampiran', 'Lampiran hal. 53', NULL, 53, '29. Koordinasi adalah kegiatan memadukan peran dan fungsi sektor-sektor yang terkait secara proporsional, sinergis dan saling mendukung dalam penanganan tanggap darurat bencana
30. Pengendalian adalah kegiatan pengarahan oleh pos komando tanggap darurat bencana kepada pos komando lapangan dalam pelaksanaan operasi tanggap darurat bencana.
31. Pemantauan adalah kegiatan mengamati pelaksanaan penanganan tanggap darurat bencana untuk memperoleh data dan informasi sebagai bahan memberikan arahan.
32. Evaluasi adalah kegiatan penilaian terhadap seluruh kegiatan tanggap darurat bencana baik oleh pos komando tanggap darurat bencana, pos komando lapangan maupun pos pendukung tanggap darurat bencana.
33. Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
34. Pemerintah Daerah adalah gubernur, bupati/walikota, atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
35. Lembaga Usaha adalah badan hukum yang dapat berbentuk badan usaha milik negara, badan usaha milik daerah, koperasi, atau swasta yang didirikan sesuai dengan ketentuan perundang-undangan yang menjalankan jenis usaha tetap dan terus menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia.
8');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6430, '29. Koordinasi adalah kegiatan memadukan peran dan fungsi sektor-sektor yang terkait secara proporsional, sinergis dan saling mendukung dalam penanganan tanggap darurat bencana
30. Pengendalian adalah kegiatan pengarahan oleh pos komando tanggap darurat bencana kepada pos komando lapangan dalam pelaksanaan operasi tanggap darurat bencana.
31. Pemantauan adalah kegiatan mengamati pelaksanaan penanganan tanggap darurat bencana untuk memperoleh data dan informasi sebagai bahan memberikan arahan.
32. Evaluasi adalah kegiatan penilaian terhadap seluruh kegiatan tanggap darurat bencana baik oleh pos komando tanggap darurat bencana, pos komando lapangan maupun pos pendukung tanggap darurat bencana.
33. Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
34. Pemerintah Daerah adalah gubernur, bupati/walikota, atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
35. Lembaga Usaha adalah badan hukum yang dapat berbentuk badan usaha milik negara, badan usaha milik daerah, koperasi, atau swasta yang didirikan sesuai dengan ketentuan perundang-undangan yang menjalankan jenis usaha tetap dan terus menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia.
8', 'Lampiran hal. 53', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6431, 'perka-14-2010', 57, 'lampiran', 'Lampiran hal. 54', NULL, 54, '36. Lembaga Swadaya Masyarakat (LSM) adalah organisasi masyarakat yang berbadan hukum dan tidak berbadan hukum, sebagai wadah partisipasi masyarakat dalam penanganan kedaruratan bencana.
37. Lembaga Internasional adalah organisasi yang berada dalam lingkup struktur organisasi Perserikatan Bangsa-Bangsa atau yang menjalankan tugas-tugas mewakili Perserikatan Bangsa-Bangsa atau organisasi internasional lainnya.
38. Lembaga asing non pemerintah adalah suatu organisasi internasional yang terorganisasi secara fungsional bebas dari dan tidak mewakili pemerintahan suatu negara atau organisasi internasional yang dibentuk secara terpisah dari suatu negara dimana organisasi itu didirikan.
K. Ruang Lingkup
1. Pedoman ini membahas pembentukan pos komando tanggap darurat bencana, pos komando lapangan tanggap darurat bencana, pos pendukung tanggap darurat bencana, dan mekanisme hubungan kerja.
2. Pedoman ini berlaku bagi pemerintah dan pemerintah daerah dalam pembentukan pos komando kedaruratan bencana, serta dapat dijadikan acuan bagi masyarakat dan lembaga usaha untuk berpartisipasi dalam tanggap darurat bencana.
L. Sistematika Pedoman ini disusun dengan sistematika : pendahuluan; pembentukan pos komando tanggap darurat bencana; pembentukan pos komando lapangan tanggap darurat bencana; pos pendukung tanggap darurat bencana; mekanisme hubungan kerja, dan penutup.
9 BAB II PEMBENTUKAN POS KOMANDO TANGGAP DARURAT BENCANA
I. Kedudukan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6431, '36. Lembaga Swadaya Masyarakat (LSM) adalah organisasi masyarakat yang berbadan hukum dan tidak berbadan hukum, sebagai wadah partisipasi masyarakat dalam penanganan kedaruratan bencana.
37. Lembaga Internasional adalah organisasi yang berada dalam lingkup struktur organisasi Perserikatan Bangsa-Bangsa atau yang menjalankan tugas-tugas mewakili Perserikatan Bangsa-Bangsa atau organisasi internasional lainnya.
38. Lembaga asing non pemerintah adalah suatu organisasi internasional yang terorganisasi secara fungsional bebas dari dan tidak mewakili pemerintahan suatu negara atau organisasi internasional yang dibentuk secara terpisah dari suatu negara dimana organisasi itu didirikan.
K. Ruang Lingkup
1. Pedoman ini membahas pembentukan pos komando tanggap darurat bencana, pos komando lapangan tanggap darurat bencana, pos pendukung tanggap darurat bencana, dan mekanisme hubungan kerja.
2. Pedoman ini berlaku bagi pemerintah dan pemerintah daerah dalam pembentukan pos komando kedaruratan bencana, serta dapat dijadikan acuan bagi masyarakat dan lembaga usaha untuk berpartisipasi dalam tanggap darurat bencana.
L. Sistematika Pedoman ini disusun dengan sistematika : pendahuluan; pembentukan pos komando tanggap darurat bencana; pembentukan pos komando lapangan tanggap darurat bencana; pos pendukung tanggap darurat bencana; mekanisme hubungan kerja, dan penutup.
9 BAB II PEMBENTUKAN POS KOMANDO TANGGAP DARURAT BENCANA
I. Kedudukan', 'Lampiran hal. 54', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6432, 'perka-14-2010', 58, 'lampiran', 'Lampiran hal. 55', NULL, 55, '4. Pos Komando Tanggap Darurat Bencana Nasional berkedudukan di ibu kota negara, Pos Komando Tanggap Darurat Bencana Provinsi berkedudukan di ibu kota provinsi, Pos Komando Tanggap Darurat Bencana Kabupaten/kota berkedudukan di ibu kota kabupaten/kota atau di tempat lain sesuai kondisi yang ada.
5. Pada bencana skala nasional dapat dibentuk Pos Komando Tanggap Darurat Aju di provinsi dan pada bencana skala provinsi dapat dibentuk Pos Komando Tanggap Darurat Aju di kabupaten/kota yang terkena bencana.
6. Jangka waktu keberadaan pos komando tanggap darurat bencana bersifat sementara selama masa tanggap darurat dan beroperasi selama 24 (dua puluh empat) jam setiap hari serta dapat diperpanjang atau diperpendek waktunya sesuai dengan pelaksanaan tanggap darurat.
J. Persyaratan Lokasi Pos Komando Tanggap Darurat Bencana
3. Pos Komando Tanggap Darurat Bencana dapat menempati bangunan atau tenda.
4. Bangunan atau tenda pos komando tanggap darurat bencana menempati lokasi yang strategis dengan kriteria:
a. mudah diakses oleh berbagai pihak yang terlibat dalam kegiatan tanggap darurat bencana.
b. aman dan terbebas dari ancaman bencana.
c. memiliki lahan parkir yang memadai.
d. luas lahan sekurang-kurangnya 500 m2.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6432, '4. Pos Komando Tanggap Darurat Bencana Nasional berkedudukan di ibu kota negara, Pos Komando Tanggap Darurat Bencana Provinsi berkedudukan di ibu kota provinsi, Pos Komando Tanggap Darurat Bencana Kabupaten/kota berkedudukan di ibu kota kabupaten/kota atau di tempat lain sesuai kondisi yang ada.
5. Pada bencana skala nasional dapat dibentuk Pos Komando Tanggap Darurat Aju di provinsi dan pada bencana skala provinsi dapat dibentuk Pos Komando Tanggap Darurat Aju di kabupaten/kota yang terkena bencana.
6. Jangka waktu keberadaan pos komando tanggap darurat bencana bersifat sementara selama masa tanggap darurat dan beroperasi selama 24 (dua puluh empat) jam setiap hari serta dapat diperpanjang atau diperpendek waktunya sesuai dengan pelaksanaan tanggap darurat.
J. Persyaratan Lokasi Pos Komando Tanggap Darurat Bencana
3. Pos Komando Tanggap Darurat Bencana dapat menempati bangunan atau tenda.
4. Bangunan atau tenda pos komando tanggap darurat bencana menempati lokasi yang strategis dengan kriteria:
a. mudah diakses oleh berbagai pihak yang terlibat dalam kegiatan tanggap darurat bencana.
b. aman dan terbebas dari ancaman bencana.
c. memiliki lahan parkir yang memadai.
d. luas lahan sekurang-kurangnya 500 m2.', 'Lampiran hal. 55', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6433, 'perka-14-2010', 59, 'lampiran', 'Lampiran hal. 55', NULL, 55, '10 C. Proses Pembentukan Pembentukan Pos Komando Tanggap Darurat Bencana, dapat dilakukan pada tahap siaga darurat untuk jenis bencana yang terjadi secara berangsur-angsur, seperti banjir dan gunung meletus, atau segera setelah dinyatakan status bencana untuk jenis bencana yang terjadi secara tiba-tiba, seperti tanah longsor, gempa dan tsunami.
Untuk jenis bencana yang terjadi secara berangsur-angsur, pembentukan Pos Komando Tanggap Darurat Bencana dengan cara meningkatkan status Pusat Pengendali Operasi Wilayah Provinsi/Kabupaten/Kota. Sedangkan untuk jenis bencana yang terjadi secara tiba-tiba, proses pembentukan pos komando tanggap darurat bencana, dilakukan melalui 4 (empat) tahapan yang harus dilaksanakan secara keseluruhan menjadi satu rangkaian sistem komando yang terpadu, yaitu:
5. Informasi Kejadian Awal Bencana:
Informasi awal data kejadian bencana dapat diperoleh melalui berbagai sumber antara lain laporan instansi/lembaga terkait, media massa, masyarakat, dan internet. Kebenaran informasi tersebut diatas perlu dikonfirmasi dengan pertanyaan apa, kapan, dimana, bagaimana, berapa, penyebab, akibat yang ditimbulkan dan upaya yang telah dilakukan serta kebutuhan yang mendesak.
6. Penugasan Tim Reaksi Cepat Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6433, '10 C. Proses Pembentukan Pembentukan Pos Komando Tanggap Darurat Bencana, dapat dilakukan pada tahap siaga darurat untuk jenis bencana yang terjadi secara berangsur-angsur, seperti banjir dan gunung meletus, atau segera setelah dinyatakan status bencana untuk jenis bencana yang terjadi secara tiba-tiba, seperti tanah longsor, gempa dan tsunami.
Untuk jenis bencana yang terjadi secara berangsur-angsur, pembentukan Pos Komando Tanggap Darurat Bencana dengan cara meningkatkan status Pusat Pengendali Operasi Wilayah Provinsi/Kabupaten/Kota. Sedangkan untuk jenis bencana yang terjadi secara tiba-tiba, proses pembentukan pos komando tanggap darurat bencana, dilakukan melalui 4 (empat) tahapan yang harus dilaksanakan secara keseluruhan menjadi satu rangkaian sistem komando yang terpadu, yaitu:
5. Informasi Kejadian Awal Bencana:
Informasi awal data kejadian bencana dapat diperoleh melalui berbagai sumber antara lain laporan instansi/lembaga terkait, media massa, masyarakat, dan internet. Kebenaran informasi tersebut diatas perlu dikonfirmasi dengan pertanyaan apa, kapan, dimana, bagaimana, berapa, penyebab, akibat yang ditimbulkan dan upaya yang telah dilakukan serta kebutuhan yang mendesak.
6. Penugasan Tim Reaksi Cepat Penanggulangan Bencana', 'Lampiran hal. 55', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6434, 'perka-14-2010', 60, 'lampiran', 'Lampiran hal. 56', NULL, 56, 'c. Dari informasi kejadian awal yang diperoleh, BPBD/SATLAK PB dan atau BNPB menugaskan Tim Reaksi Cepat (TRC BNPB/BPBD/SATLAK PB) tanggap darurat bencana, untuk melaksanakan tugas pengkajian secara cepat dan tepat, serta memberikan dukungan pendampingan dalam rangka kegiatan tanggap darurat.
d. Hasil pelaksanaan tugas TRC BNPB/BPBD/SATLAK PB tanggap darurat dan masukan dari berbagai instansi/lembaga terkait merupakan bahan pertimbangan bagi:
4) Kepala BPBD/SATLAK PB Kabupaten/Kota untuk mengusulkan kepada Bupati/Walikota dalam rangka menetapkan status/tingkat bencana skala kabupaten/kota.
11 5) Kepala BPBD Provinsi untuk mengusulkan kepada Gubernur dalam rangka menetapkan status/tingkat bencana skala provinsi.
6) Kepala BNPB untuk mengusulkan kepada Presiden RI dalam rangka menetapkan status/tingkat bencana skala nasional.
3. Penetapan Status /Tingkat Bencana
c. Berdasarkan usul sesuai butir 2b di atas maka :
4) Bupati/Walikota menetapkan status/tingkat bencana skala kabupaten/kota.
5) Gubernur menetapkan status/tingkat bencana skala provinsi.
6) Presiden RI menetapkan status/tingkat bencana skala nasional.
d. Tindak lanjut dari penetapan status/tingkat bencana tersebut, maka Kepala BNPB/BPBD Provinsi/BPBD/SATLAK PB Kabupaten/Kota sesuai dengan kewenangannya dapat menunjuk seorang pejabat sebagai komandan tanggap darurat bencana sesuai status/tingkat bencana skala nasional/daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6434, 'c. Dari informasi kejadian awal yang diperoleh, BPBD/SATLAK PB dan atau BNPB menugaskan Tim Reaksi Cepat (TRC BNPB/BPBD/SATLAK PB) tanggap darurat bencana, untuk melaksanakan tugas pengkajian secara cepat dan tepat, serta memberikan dukungan pendampingan dalam rangka kegiatan tanggap darurat.
d. Hasil pelaksanaan tugas TRC BNPB/BPBD/SATLAK PB tanggap darurat dan masukan dari berbagai instansi/lembaga terkait merupakan bahan pertimbangan bagi:
4) Kepala BPBD/SATLAK PB Kabupaten/Kota untuk mengusulkan kepada Bupati/Walikota dalam rangka menetapkan status/tingkat bencana skala kabupaten/kota.
11 5) Kepala BPBD Provinsi untuk mengusulkan kepada Gubernur dalam rangka menetapkan status/tingkat bencana skala provinsi.
6) Kepala BNPB untuk mengusulkan kepada Presiden RI dalam rangka menetapkan status/tingkat bencana skala nasional.
3. Penetapan Status /Tingkat Bencana
c. Berdasarkan usul sesuai butir 2b di atas maka :
4) Bupati/Walikota menetapkan status/tingkat bencana skala kabupaten/kota.
5) Gubernur menetapkan status/tingkat bencana skala provinsi.
6) Presiden RI menetapkan status/tingkat bencana skala nasional.
d. Tindak lanjut dari penetapan status/tingkat bencana tersebut, maka Kepala BNPB/BPBD Provinsi/BPBD/SATLAK PB Kabupaten/Kota sesuai dengan kewenangannya dapat menunjuk seorang pejabat sebagai komandan tanggap darurat bencana sesuai status/tingkat bencana skala nasional/daerah.', 'Lampiran hal. 56', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6435, 'perka-14-2010', 61, 'lampiran', 'Lampiran hal. 57', NULL, 57, '4. Pembentukan Pos Komando Tanggap Darurat Bencana Presiden/Gubernur/Bupati/Walikota atas usul Kepala BNPB/BPBD Provinsi/ BPBD/SATLAK PB Kabupaten/Kota sesuai status/tingkat bencana dan tingkat kewenangannya :
e. Mengeluarkan Surat Keputusan pembentukan Pos Komando Tanggap Darurat Bencana.
f. Melaksanakan mobilisasi sumberdaya manusia, peralatan dan logistik serta dana dari instansi/lembaga terkait dan/atau masyarakat.
g. Meresmikan pembentukan Pos Komando Tanggap Darurat Bencana.
h. Bilamana pemerintah kabupaten/kota atau provinsi tidak ada BPBD, maka yang melaksanakan pembentukan Pos Komando Tanggap Darurat adalah instansi/ Satuan Kerja Perangkat Daerah (SKPD) yang menangani bencana.
12 D. Pengorganisasian
5. Organisasi Pos Komando Tanggap Darurat Bencana merupakan organisasi satu komando, dengan mata rantai dan garis komando serta tanggung jawab yang jelas. Instansi/lembaga dapat dikoordinasikan dalam satu organisasi berdasarkan satu kesatuan komando. Organisasi ini dapat dibentuk di semua tingkatan wilayah bencana baik di tingkat kabupaten/kota, provinsi maupun tingkat nasional.
6. Struktur organisasi pos komando tanggap darurat terdiri atas Komandan yang dibantu oleh staf komando dan staf umum, secara lengkap terdiri dari:
a. Komandan Tanggap Darurat Bencana
b. Wakil Komandan Tanggap Darurat Bencana
c. Staf Komando:
1) Sekretariat 2) Hubungan Masyarakat 3) Keselamatan dan Keamanan 4) Perwakilan instansi/lembaga
d. Staf Umum:');
