INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6446, '2. Wakil Komandan Pos Komando Lapangan Tanggap Darurat Bencana Wakil Komandan Pos Komando Lapangan Tanggap Darurat Bencana adalah salah seorang pejabat dari unsur Pemda, TNI atau Kepolisian wilayah setempat yang ditunjuk oleh Komandan Pos Komando Lapangan.
a. Uraian Tugas Wakil Komandan Posko Lapangan :
4) Membantu Komandan Posko Lapangan dalam merencanakan, mengorganisasikan, melaksanakan dan mengendalikan operasi tanggap darurat bencana.
5) Mengkoordinir tugas-tugas bagian sekretariat 23 mencakup sub bagian Data, Informasi dan Komunikasi, Sub Bagian Layanan Internal, dan Sub Bagian Administrasi umum, keuangan intern dan pelaporan 6) Mewakili Komandan Posko Lapangan apabila berhalangan.
b. Wakil Komandan Pos Komando Lapangan Tanggap Darurat Bencana bertanggungjawab langsung kepada Kepala Pos Komando Lapangan.
3. Sekretariat
a. Sekretariat dipimpin oleh seorang Sekretaris dibantu Kepala Sub Bagian Data, Informasi dan Komunikasi; dan Kepala Sub Bagian Administrasi 1) Jabatan Sekretaris ditunjuk oleh Komandan Posko Lapangan dari unsur Pemda, TNI atau Kepolisian Wilayah setempat.
2) Jabatan Kepala Sub Bagian Data, Informasi dan Komunikasi ditunjuk oleh Komandan Posko Lapangan dari unsur Pemda atau BPBD, dengan staff dari unsur penyelenggara radio komunikasi seperti RAPI, ORARI, dan lain-lain.
3) Jabatan Kepala Sub Bagian Administrasi beserta beberapa staff ditunjuk oleh Komandan Posko Lapangan dari unsur BPBD/SATLAK PB.
b. Uraian Tugas Sekretariat:', 'Lampiran hal. 68', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6447, 'perka-14-2010', 73, 'lampiran', 'Lampiran hal. 69', NULL, 69, '5) Mengumpulkan, mengolah dan menyajikan data dan informasi tentang kronologis dan dampak bencana, serta menilai kerugian bencana secara cepat.
6) Membentuk jaringan informasi dan komunikasi serta menyebarkan informasi tentang bencana tersebut serta penanggulangannya ke media massa cetak dan elektronik serta masyarakat luas.
7) Menyelenggarakan administrasi umum, keuangan, dan personil.
24 8) Pelayanan akomodasi dan konsumsi bagi personil bidang-bidang operasional Pos Komando Lapangan Tanggap Darurat Bencana.
c. Tanggungjawab :
1) Sekretaris bertanggungjawab langsung kepada Komandan Posko Lapangan 2) Kepala Sub Bagian Data, Informasi dan Komunikasi bertanggungjawab langsung kepada Sekretaris 3) Kepala Sub Bagian Administrasi bertanggungjawab langsung kepada Sekretaris
4. Bidang SAR
d. Bidang SAR dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/dinas/lembaga/organisasi yang bergerak dibidang SAR, beranggotakan para petugas dari instansi/ dinas/lembaga/organisasi/ relawan yang bergerak dibidang SAR.
e. Uraian tugas koordinator bidang SAR 5) Membuat rencana operasi SAR 6) Menghimpun dan mengkoordinasikan petugas/relawan dibidang SAR 7) Memimpin kegiatan pencarian, penyelamatan, dan evakuasi korban bencana 8) Mengkoordinasikan hasil kegiatan dengan sekretariat.
c. Koordinator Bidang SAR bertanggung jawab langsung kepada Komandan Posko Lapangan.
5. Bidang Dapur Umum Lapangan (DUMLAP)');
