INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6448, 'perka-14-2010', 74, 'lampiran', 'Lampiran hal. 70', NULL, 70, 'a. Bidang DUMLAP dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/dinas/lembaga/organisasi yang bergerak dibidang Dapur Umum Lapangan. Bidang Dapur Umum Lapangan 25 beranggotakan para petugas dari instansi/dinas/lembaga /organisasi/ relawan yang bergerak dibidang DUMLAP.
b. Uraian tugas koordinator bidang DUMLAP 4) Menghimpun dan mengkoordinasikan petugas/relawan dibidang DUMLAP 5) Memimpin kegiatan DUMLAP untuk kepentingan korban bencana.
6) Mengkoordinasikan hasil kegiatan dengan sekretariat.
c. Koordinator Bidang DUMLAP bertanggung jawab langsung kepada Komandan Posko Lapangan.
6. Bidang Logistik-Peralatan dan Pengelolaan Bantuan
d. Bidang Logistik-Peralatan dan Pengelolaan Bantuan dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/ dinas/lembaga/organisasi yang bergerak dibidang logistik dan peralatan tanggap darurat. Bidang Logistik-Peralatan dan Pengelolaan Bantuan beranggotakan para petugas dari instansi/dinas/lembaga/organisasi yang bergerak dibidang logistik dan peralatan tanggap darurat dan para relawan yang mengabdikan diri membantu tugas-tugas bidang logistik, peralatan dan pengelolaan bantuan.
e. Uraian tugas koordinator bidang Logistik- Peralatan dan Pengelolaan Bantuan 1) Menyediakan fasilitas, jasa, dan bahan-bahan serta perlengkapan tanggap darurat.
2) Menerima, mengadministrasikan, dan menyalurkan bantuan pangan, sandang dan keuangan kepada korban bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6448, 'a. Bidang DUMLAP dipimpin oleh seorang koordinator yang ditunjuk oleh Komandan Posko Lapangan dari instansi/dinas/lembaga/organisasi yang bergerak dibidang Dapur Umum Lapangan. Bidang Dapur Umum Lapangan 25 beranggotakan para petugas dari instansi/dinas/lembaga /organisasi/ relawan yang bergerak dibidang DUMLAP.
b. Uraian tugas koordinator bidang DUMLAP 4) Menghimpun dan mengkoordinasikan petugas/relawan dibidang DUMLAP 5) Memimpin kegiatan DUMLAP untuk kepentingan korban bencana.
6) Mengkoordinasikan hasil kegiatan dengan sekretariat.
c. Koordinator Bidang DUMLAP bertanggung jawab langsung kepada Komandan Posko Lapangan.
