INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6450, 'perka-14-2010', 76, 'lampiran', 'Lampiran hal. 72', NULL, 72, 'c. Koordinator Bidang Layanan Kesehatan dan Psikososial bertanggung jawab langsung kepada Komandan Posko Lapangan 14.Bidang Pemulihan Darurat Prasarana dan Sarana Vital
