INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6451, 'perka-14-2010', 77, 'lampiran', 'Lampiran hal. 73', NULL, 73, '1) Menyusun rencana kerja di bidang keselamatan dan keamanan 2) Menghimpun dan mengkoordinasikan petugas/relawan di bidang keselamatan dan keamanan 3) Menjaga keamanan dan keselamatan petugas/relawan tanggap darurat, posko lapangan tanggap darurat, dan masyakata serta lokasi bencana.
