INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6452, 'perka-14-2010', 78, 'lampiran', 'Lampiran hal. 74', NULL, 74, 'z. Media presentasi: lcd projector aa. Papan nama (Plang) bb. Papan data (daerah, data korban, kerusakan, kebutuhan mendesak, mengacu pada hasil kaji cepat TRC PB) cc. Peta Induk (peta tentang semua kegiatan Posko) dd. Peta Lokasi ee. Peta/Data Logistik ff. Peta/Data Personil gg. Peta/Data bantuan 29 hh. Peta/Data Kebutuhan ii. Peta/Data Peralatan jj. Peta/Data NGO lokal dan asing kk. Jam dinding ll. Buku jurnal J. Pembiayaan Biaya operasional Pos Komando LapanganTanggap Darurat Bencana bersumber dari:
1. APBD Kabupaten/Kota
2. APBD Provinsi
3. APBN
4. Bantuan lain yang tidak mengikat.
30 BAB IV PEMBENTUKAN POS PENDUKUNG TANGGAP DARURAT BENCANA H. Kedudukan
5. Pos Pendukung Tanggap Darurat Bencana merupakan pos yang membantu akses bantuan tanggap darurat guna mendukung keberadaan Pos Komando Tanggap Darurat Bencana.
6. Keberadaan Pos Pendukung Tanggap Darurat Bencana:
a. Pada bencana skala nasional berkedudukan di Bandara atau pelabuhan Internasional dan pangkalan militer
b. Pada bencana skala provinsi berkedudukan di bandara atau pelabuhan di provinsi yang mengalami bencana, dan pangkalan militer
c. Pada bencana skala kabupaten/kota berkedudukan di bandara atau pelabuhan atau lokasi yang dekat dan mudah diakses oleh Pos Komando Tanggap Darurat Bencana atau mudah diakses oleh Pos Komando Lapangan Tanggap Darurat Bencana.');
