INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6456, 'perka-14-2010', 82, 'lampiran', 'Lampiran hal. 80', NULL, 80, 'f. Komandan Posko Tanggap Darurat Bencana Provinsi meneruskan permintaan bantuan sumber daya ke Posko Tanggap Darurat Bencana Nasional
3. Mekanisme Mobilisasi/pengerahan bantuan sumberdaya
a. Komandan Posko Tanggap Darurat Bencana Kabupaten/Kota/Provinsi/ Nasional melakukan analisis permintaan bantuan
b. Jika persediaan bantuan cukup memadai, selanjutnya :
1) Komandan Posko Tanggap Darurat Bencana Nasional mengerahkan bantuan sumberdaya melalui Posko Tanggap Darurat Provinsi atau secara langsung ke Posko Lapangan Tanggap Darurat Bencana dengan didampingi Pejabat Posko Tanggap Darurat Provinsi dan Kabupaten/Kota.
2) Komandan Posko Tanggap Darurat Bencana Provinsi mengerahkan bantuan sumberdaya melalui Posko Tanggap Darurat Kabupaten/Kota atau secara langsung ke Posko Lapangan Tanggap Darurat Bencana dengan didampingi Pejabat Posko Tanggap Darurat Kabupaten/Kota.
35 3) Komandan Posko Tanggap Darurat Bencana Kabupaten/Kota mengerahkan bantuan sumberdaya secara langsung ke Posko Lapangan Tanggap Darurat.
c. Jika persediaan bantuan sumberdaya tidak memadai, maka :
4) Komandan Posko Tanggap Darurat Bencana Nasional memerintahkan Komandan Pos Pendukung Tanggap Darurat Bencana Nasional untuk mengerahkan bantuan sumberdaya ke Posko Tanggap Darurat Provinsi.
5) Komandan Posko Tanggap Darurat Bencana Provinsi memerintahkan Komandan Pos Pendukung Tanggap Darurat Bencana Provinsi untuk mengerahkan bantuan sumberdaya ke Posko Tanggap Darurat Kabupaten/Kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6456, 'f. Komandan Posko Tanggap Darurat Bencana Provinsi meneruskan permintaan bantuan sumber daya ke Posko Tanggap Darurat Bencana Nasional
