INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6478, '- ix - DAFTAR ISI Lampiran Berita Acara Serah Terima Hasil Pekerjaan Formulir 37 : 98 Barang/Jasa dari Kepala BPBD kepada KPA Surat Pernyataan Bersedia Menerima Pemindahtanganan Formulir 38 : 99 Hibah BMN Formulir 39 : Rincian Persiapan Lelang Paket Kontrak Persatuan Kerja 100 Formulir 40 : Rincian Proses Lelang Paket Kontrak Persatuan Kerja 101 Formulir 41 : Jadwal Pelaksanaan Kegiatan 103 Formulir 42 : Pelaksanaan Anggaran 104 Formulir 43 : Rincian Pekerjaan Persatuan Kerja 105 Formulir 44 : Pelaksanaan Fisik Persatuan Kerja 106 Formulir 45 : Laporan Pelaksanaan Anggaran Per Jenis Pekerjaan 107 Formulir 46 : Daftar Potensial Masalah Pelaksanaan Kegiatan Per Sektor 108 Formulir 47 : Rekapitulasi Potensial Masalah Pelaksanaan Kegiatan 109 Formulir 48 : Laporan Akhir Rekapitulasi Pelaksanaan Kegiatan 110 Surat Laporan Akhir Pekerjaan Pengelolaan Dana Formulir 49 : 111 Rehabilitasi dan Rekonstruksi Pascabencana Lampiran Surat Laporan Akhir Pekerjaan Pengelolaan Formulir 50 : 112 Dana Rehabilitasi dan Rekonstruksi Pascabencana Formulir 51 : Surat Pernyataan PPK telah Berakhirnya Kegiatan 113 Surat Pernyataan Gubernur/Bupati/Walikota telah Formulir 52 : 114 Berakhirnya Kegiatan Berita Acara Penyerahan Pengelolaan BMN Hasil Kegiatan Formulir 53 : 115 Rehabilitasi dan Rekonstruksi Daftar BMN Hasil Kegiatan Rehabilitasi dan Rekonstruksi Formulir 54 : 116 Pascabencana Berita Acara Serah Terima Pemindahtanganan/Hibah Formulir 55 : 117 Barang Milik Negara Hasil Kegiatan Lampiran', 'BAB V PENUTUP .................................................................. (lanjutan 3)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6479, 'perka-14-2011', 10, 'lain', 'BAB V PENUTUP .................................................................. (lanjutan 4)', NULL, 9, 'Berita Acara Serah Terima Pemindahtanganan/ Formulir 56 : 118 Hibah Barang Milik Negara Hasil Kegiatan PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 14 TAHUN 2011 TENTANG PETUNJUK TEKNIS TATACARA PENGAJUAN DAN PENGELOLAAN DANA BANTUAN SOSIAL BERPOLA HIBAH KEGIATAN REHABILITASI DAN REKONSTRUKSI PASCABENCANA TAHUN 2011 DENGAN RAHMAT TUHAN YANG MAHA ESA KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Menimbang : a. bahwa dalam rangka rehabilitasi dan rekonstruksi penanganan pascabencana di wilayah Negara Kesatuan Republik Indonesia, dan sesuai dengan ketentuan Pasal 23 ayat (1) Peraturan Pemerintah Republik Indonesia Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana mengenai bantuan sosial berpola hibah perlu dibuat Petunjuk Pelaksanaan Kegiatan Rehabilitasi dan Rekonstruksi sebagai acuan dalam penerapan kebijakan Pemerintah Daerah;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Petunjuk Teknis (Juknis) Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pascabencana Tahun 2011;
Mengingat : 1. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6479, 'Berita Acara Serah Terima Pemindahtanganan/ Formulir 56 : 118 Hibah Barang Milik Negara Hasil Kegiatan PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 14 TAHUN 2011 TENTANG PETUNJUK TEKNIS TATACARA PENGAJUAN DAN PENGELOLAAN DANA BANTUAN SOSIAL BERPOLA HIBAH KEGIATAN REHABILITASI DAN REKONSTRUKSI PASCABENCANA TAHUN 2011 DENGAN RAHMAT TUHAN YANG MAHA ESA KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Menimbang : a. bahwa dalam rangka rehabilitasi dan rekonstruksi penanganan pascabencana di wilayah Negara Kesatuan Republik Indonesia, dan sesuai dengan ketentuan Pasal 23 ayat (1) Peraturan Pemerintah Republik Indonesia Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana mengenai bantuan sosial berpola hibah perlu dibuat Petunjuk Pelaksanaan Kegiatan Rehabilitasi dan Rekonstruksi sebagai acuan dalam penerapan kebijakan Pemerintah Daerah;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Petunjuk Teknis (Juknis) Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pascabencana Tahun 2011;
Mengingat : 1. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);', 'BAB V PENUTUP .................................................................. (lanjutan 4)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6480, 'perka-14-2011', 11, 'lain', 'BAB V PENUTUP .................................................................. (lanjutan 5)', NULL, 11, '2. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
3. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
4. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
5. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
6. Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Peraturan Presiden Nomor 54 Tahun 2010 tentang Pengadaan Barang/Jasa Pemerintah;
8. Keputusan Presiden Nomor 29/M Tahun 2008 tentang Pengangkatan Kepala dan Pejabat Eselon I Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6480, '2. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
3. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
4. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
5. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
6. Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Peraturan Presiden Nomor 54 Tahun 2010 tentang Pengadaan Barang/Jasa Pemerintah;
8. Keputusan Presiden Nomor 29/M Tahun 2008 tentang Pengangkatan Kepala dan Pejabat Eselon I Badan Nasional Penanggulangan Bencana;', 'BAB V PENUTUP .................................................................. (lanjutan 5)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6481, 'perka-14-2011', 12, 'lain', 'BAB V PENUTUP .................................................................. (lanjutan 6)', NULL, 11, '9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja BNPB;
10. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana;
11. Peraturan Direktur Jenderal Perbendaharaan Kementerian Keuangan Nomor: Per-63/Pb/2011 Tanggal. 29 September 2011 tentang Tata Cara Pembayaran Dana Rehabilitasi dan Rekonstruksi Pascabencana Tahun 2011.
- xii - MEMUTUSKAN :
Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PETUNJUK TEKNIS TATACARA PENGAJUAN DAN PENGELOLAAN DANA BANTUAN SOSIAL BERPOLA HIBAH KEGIATAN REHABILITASI DAN REKONSTRUKSI PASCABENCANA TAHUN 2011.
Pasal 1 Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pascabencana Tahun 2011, yang selanjutnya dalam peraturan ini disebut Petunjuk Teknis atau Juknis, merupakan acuan bagi pemerintah, pemerintah provinsi, pemerintah kabupaten/kota serta pihak lain yang terkait dalam kegiatan rehabilitasi dan rekonstruksi pascabencana di Wilayah Negara Kesatuan Republik Indonesia.
Pasal 2 Petunjuk Teknis sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian yang tidak terpisahkan dari peraturan ini.
Pasal 3 Peraturan ini mulai berlaku pada tanggal ditetapkan.
Ditetapkan di Jakarta pada tanggal 21 Nopember 2011 KEPALA, TTD.
DR. SYAMSUL MAARIF, M.Si.');
