INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6483, 'perka-14-2011', 14, 'lampiran', 'LAMPIRAN : PERATURAN KEPALA BADAN', NULL, 13, 'NASIONAL PENANGGULANGAN BENCANA NOMOR : 14 Tahun 2001 TANGGAL : 21 November 2011');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6483, 'NASIONAL PENANGGULANGAN BENCANA NOMOR : 14 Tahun 2001 TANGGAL : 21 November 2011', 'LAMPIRAN : PERATURAN KEPALA BADAN', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6484, 'perka-14-2011', 15, 'lain', 'BAB I', NULL, 13, 'PENDAHULUAN A. Latar Belakang Penyelenggaraan penanggulangan bencana merupakan kegiatan mulai dari tahapan sebelum kejadian bencana, saat terjadi bencana, hingga tahapan pascabencana. Kewenangan dan tanggung jawab utama penyelenggaraan penanggulangan bencana terletak pada Pemerintah, pemerintah daerah dan masyarakat dilakukan secara terarah, terkoordinasi dan terpadu sejak penetapan kebijaksanaan pembangunan yang berisiko timbulnya bencana. Peraturan perundang-undangan yang bersifat jangka panjang menjadi bagian penting dalam upaya pembangunan. Penanggulangan bencana pada tahap pasca bencana meliputi rehabilitasi dan rekonstruksi.
Penyelenggaraan rehabilitasi dan rekonstruksi merupakan bagian tak terpisahkan dalam perencanaan pembangunan, memerlukan aspek perencanaan dan pendanaan sesuai yang diatur peraturan perundang-undangan oleh Pemerintah baik dalam bentuk kebijakan perencanaan, pendanaan dan kebijakan pembangunan daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6484, 'PENDAHULUAN A. Latar Belakang Penyelenggaraan penanggulangan bencana merupakan kegiatan mulai dari tahapan sebelum kejadian bencana, saat terjadi bencana, hingga tahapan pascabencana. Kewenangan dan tanggung jawab utama penyelenggaraan penanggulangan bencana terletak pada Pemerintah, pemerintah daerah dan masyarakat dilakukan secara terarah, terkoordinasi dan terpadu sejak penetapan kebijaksanaan pembangunan yang berisiko timbulnya bencana. Peraturan perundang-undangan yang bersifat jangka panjang menjadi bagian penting dalam upaya pembangunan. Penanggulangan bencana pada tahap pasca bencana meliputi rehabilitasi dan rekonstruksi.
Penyelenggaraan rehabilitasi dan rekonstruksi merupakan bagian tak terpisahkan dalam perencanaan pembangunan, memerlukan aspek perencanaan dan pendanaan sesuai yang diatur peraturan perundang-undangan oleh Pemerintah baik dalam bentuk kebijakan perencanaan, pendanaan dan kebijakan pembangunan daerah.', 'BAB I', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6485, 'perka-14-2011', 16, 'lain', 'BAB I (lanjutan 1)', NULL, 13, 'Secara teknis, pelaksanaan rehabilitasi dan rekonstruksi memerlukan dokumen perencanaan dalam bentuk rencana aksi atau proposal perencanaan lain yang disetarakan. Selaras dengan Pasal 5 Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana, Pemerintah menyediakan dana bantuan kepada daerah yang terkena bencana dalam bentuk dana bantuan sosial berpola hibah. Undang-Undang Nomor 10 Tahun 2010 tentang Anggaran Pendapatan dan Belanja Nasional (APBN) tahun 2011 menyatakan bahwa pengalokasian dana bantuan sosial berpola hibah ini berada di Badan Nasional Penanggulangan Bencana (BNPB).
Sehubungan dengan pelaksanaan ketentuan peraturan perundang-undangan mengenai pengalokasian dana bantuan sosial berpola hibah oleh BNPB kepada daerah yang terkena bencana, agar penggunaan dana bantuan sosial berpola hibah tersebut dapat dilakukan secara efektif, serta menganut azas-azas tata kelola yang baik dan benar, maka perlu diterbitkan Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pascabencana Tahun 2011 yang ditetapkan dengan Peraturan Kepala (Perka) BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6485, 'Secara teknis, pelaksanaan rehabilitasi dan rekonstruksi memerlukan dokumen perencanaan dalam bentuk rencana aksi atau proposal perencanaan lain yang disetarakan. Selaras dengan Pasal 5 Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana, Pemerintah menyediakan dana bantuan kepada daerah yang terkena bencana dalam bentuk dana bantuan sosial berpola hibah. Undang-Undang Nomor 10 Tahun 2010 tentang Anggaran Pendapatan dan Belanja Nasional (APBN) tahun 2011 menyatakan bahwa pengalokasian dana bantuan sosial berpola hibah ini berada di Badan Nasional Penanggulangan Bencana (BNPB).
Sehubungan dengan pelaksanaan ketentuan peraturan perundang-undangan mengenai pengalokasian dana bantuan sosial berpola hibah oleh BNPB kepada daerah yang terkena bencana, agar penggunaan dana bantuan sosial berpola hibah tersebut dapat dilakukan secara efektif, serta menganut azas-azas tata kelola yang baik dan benar, maka perlu diterbitkan Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pascabencana Tahun 2011 yang ditetapkan dengan Peraturan Kepala (Perka) BNPB.', 'BAB I (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6486, 'perka-14-2011', 17, 'lain', 'BAB I PENDAHULUAN', NULL, 14, 'B. Maksud dan Tujuan
1. Petunjuk teknis ini dimaksudkan sebagai:
a. Acuan BNPB untuk melaksanakan pengelolaan dana bantuan sosial berpola hibah sesuai dengan yang diatur dalam Peraturan Direktur Jenderal Perbendaharaan Kementerian Keuangan Nomor Per-63/Pb/2011 Tanggal 29 September 2011 tentang Tata Cara Pembayaran Dana Rehabilitasi dan Rekonstruksi Pascabencana Tahun Anggaran 2011.
b. Acuan Pemerintah Propinsi/Kabupaten/Kota untuk melakukan pengajuan dan pengelolaan dana bantuan sosial berpola hibah untuk kegiatan rehabilitasi dan rekonstruksi pascabencana tahun 2011.
2. Petunjuk teknis ini bertujuan untuk:
a. Memberi petunjuk kepada para pengelola dana bantuan sosial berpola hibah di Pemerintah, Pemerintah Propinsi/Kabupaten/Kota tentang tatacara pengajuan, pencairan, pembayaran dan pelaksanaan kegiatan rehabilitasi dan rekonstruksi, penyusunan laporan kegiatan dan pertanggungjawaban keuangan serta pemantauan dan evaluasi sesuai ketentuan perundang-undangan.
b. Menjamin ketertiban dan kelancaran pelaksanaan kegiatan rehabilitasi dan rekonstruksi pascabencana secara efektif, efisien, transparan dan akuntabel.
c. Meningkatkan kemampuan Pemerintah, Pemerintah Propinsi/Kabupaten/Kota dalam pelaksanaan kegiatan rehabilitasi dan rekonstruksi pascabencana.
C. Ruang Lingkup Petunjuk teknis ini mengatur mengenai :
1. Tatacara dan mekanisme prosedur pengajuan, pengelolaan dan pertanggungjawaban dana bantuan sosial berpola hibah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6486, 'B. Maksud dan Tujuan
1. Petunjuk teknis ini dimaksudkan sebagai:
a. Acuan BNPB untuk melaksanakan pengelolaan dana bantuan sosial berpola hibah sesuai dengan yang diatur dalam Peraturan Direktur Jenderal Perbendaharaan Kementerian Keuangan Nomor Per-63/Pb/2011 Tanggal 29 September 2011 tentang Tata Cara Pembayaran Dana Rehabilitasi dan Rekonstruksi Pascabencana Tahun Anggaran 2011.
b. Acuan Pemerintah Propinsi/Kabupaten/Kota untuk melakukan pengajuan dan pengelolaan dana bantuan sosial berpola hibah untuk kegiatan rehabilitasi dan rekonstruksi pascabencana tahun 2011.
2. Petunjuk teknis ini bertujuan untuk:
a. Memberi petunjuk kepada para pengelola dana bantuan sosial berpola hibah di Pemerintah, Pemerintah Propinsi/Kabupaten/Kota tentang tatacara pengajuan, pencairan, pembayaran dan pelaksanaan kegiatan rehabilitasi dan rekonstruksi, penyusunan laporan kegiatan dan pertanggungjawaban keuangan serta pemantauan dan evaluasi sesuai ketentuan perundang-undangan.
b. Menjamin ketertiban dan kelancaran pelaksanaan kegiatan rehabilitasi dan rekonstruksi pascabencana secara efektif, efisien, transparan dan akuntabel.
c. Meningkatkan kemampuan Pemerintah, Pemerintah Propinsi/Kabupaten/Kota dalam pelaksanaan kegiatan rehabilitasi dan rekonstruksi pascabencana.
C. Ruang Lingkup Petunjuk teknis ini mengatur mengenai :
1. Tatacara dan mekanisme prosedur pengajuan, pengelolaan dan pertanggungjawaban dana bantuan sosial berpola hibah.', 'BAB I PENDAHULUAN', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6487, 'perka-14-2011', 18, 'lain', 'BAB I PENDAHULUAN (lanjutan 1)', NULL, 14, '2. Penjelasan peran, fungsi dan tanggungjawab pengelola dana bantuan sosial berpola hibah
3. Pengaturan dan pertanggungjawaban pelaksanaan kegiatan dari BLM, perencanaan teknis, konstruksi dan non konstruksi, supervisi dan pendampingan.
D. Pengertian Dalam petunjuk teknis ini yang dimaksud dengan:
1. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat dan rehabilitasi.
2. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pascabencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6487, '2. Penjelasan peran, fungsi dan tanggungjawab pengelola dana bantuan sosial berpola hibah
3. Pengaturan dan pertanggungjawaban pelaksanaan kegiatan dari BLM, perencanaan teknis, konstruksi dan non konstruksi, supervisi dan pendampingan.
D. Pengertian Dalam petunjuk teknis ini yang dimaksud dengan:
1. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat dan rehabilitasi.
2. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pascabencana', 'BAB I PENDAHULUAN (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6488, 'perka-14-2011', 19, 'lain', 'BAB I PENDAHULUAN', NULL, 15, 'dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.
3. Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta masyarakat dalam segala aspek kehidupan bermasyarakat pada wilayah pascabencana.
4. Pemerintah pusat, selanjutnya disebut Pemerintah, adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
5. Pemerintah daerah adalah gubernur, bupati, atau walikota, dan perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
6. Anggaran Pendapatan dan Belanja Negara selanjutnya disebut APBN adalah rencana keuangan tahunan pemerintahan yang disetujui oleh Dewan Perwakilan Rakyat (DPR).
7. Dana bantuan sosial berpola hibah adalah dana yang disediakan pemerintah kepada pemerintah daerah sebagai bantuan penanganan pascabencana. Dalam hal ini berasal dari bagian anggaran 999.08 (belanja lain-lain), yang pelaksanaan dan pengelolaannya melalui mekanisme yang berlaku dalam pengelolaan APBN.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6488, 'dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.
3. Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta masyarakat dalam segala aspek kehidupan bermasyarakat pada wilayah pascabencana.
4. Pemerintah pusat, selanjutnya disebut Pemerintah, adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
5. Pemerintah daerah adalah gubernur, bupati, atau walikota, dan perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
6. Anggaran Pendapatan dan Belanja Negara selanjutnya disebut APBN adalah rencana keuangan tahunan pemerintahan yang disetujui oleh Dewan Perwakilan Rakyat (DPR).
7. Dana bantuan sosial berpola hibah adalah dana yang disediakan pemerintah kepada pemerintah daerah sebagai bantuan penanganan pascabencana. Dalam hal ini berasal dari bagian anggaran 999.08 (belanja lain-lain), yang pelaksanaan dan pengelolaannya melalui mekanisme yang berlaku dalam pengelolaan APBN.', 'BAB I PENDAHULUAN', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6489, 'perka-14-2011', 20, 'lain', 'BAB I PENDAHULUAN (lanjutan 1)', NULL, 15, '8. Badan Nasional Penanggulangan Bencana selanjutnya disebut BNPB adalah lembaga pemerintah non kementerian setingkat menteri, sebagai badan yang berwenang menyelenggarakan penanggulangan bencana pada tingkat nasional.
9. Badan Penanggulangan Bencana Daerah Provinsi/Kabupaten/Kota yang selanjutnya disebut BPBD Provinsi/Kabupaten/Kota, adalah perangkat daerah Provinsi/Kabupaten/Kota yang dibentuk dalam rangka melaksanakan tugas dan fungsi untuk melaksanakan penanggulangan bencana.
10. Satuan Kerja Perangkat Daerah (SKPD) adalah perangkat pemerintah daerah Provinsi/Kabupaten/Kota.
11. Pengguna Anggaran yang selanjutnya disebut PA adalah pejabat pemegang kewenangan penggunaan anggaran dalam hal ini Menteri Keuangan.
12. Kuasa Pengguna Anggaran yang selanjutnya disebut KPA adalah pejabat yang diberi kuasa oleh PA dalam hal ini Kepala BNPB mendelegasikan kepada Sekretaris Utama BNPB.
13. Pejabat Pembuat Komitmen yang selanjutnya disebut PPK adalah pejabat yang diberi kewenangan oleh PA/KPA untuk mengambil keputusan dan/atau tindakan yang dapat mengakibatkan pengeluaran atas beban belanja negara.
14. PPK Pusat adalah PPK yang berkedudukan di BNPB.
15. Atasan langsung PPK Daerah adalah Kepala Pelaksana BPBD sebagai pejabat penandatangan SPM-RR, yang diangkat dan ditetapkan oleh Sekretaris Utama BNPB/selaku KPA atas nama Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6489, '8. Badan Nasional Penanggulangan Bencana selanjutnya disebut BNPB adalah lembaga pemerintah non kementerian setingkat menteri, sebagai badan yang berwenang menyelenggarakan penanggulangan bencana pada tingkat nasional.
9. Badan Penanggulangan Bencana Daerah Provinsi/Kabupaten/Kota yang selanjutnya disebut BPBD Provinsi/Kabupaten/Kota, adalah perangkat daerah Provinsi/Kabupaten/Kota yang dibentuk dalam rangka melaksanakan tugas dan fungsi untuk melaksanakan penanggulangan bencana.
10. Satuan Kerja Perangkat Daerah (SKPD) adalah perangkat pemerintah daerah Provinsi/Kabupaten/Kota.
11. Pengguna Anggaran yang selanjutnya disebut PA adalah pejabat pemegang kewenangan penggunaan anggaran dalam hal ini Menteri Keuangan.
12. Kuasa Pengguna Anggaran yang selanjutnya disebut KPA adalah pejabat yang diberi kuasa oleh PA dalam hal ini Kepala BNPB mendelegasikan kepada Sekretaris Utama BNPB.
13. Pejabat Pembuat Komitmen yang selanjutnya disebut PPK adalah pejabat yang diberi kewenangan oleh PA/KPA untuk mengambil keputusan dan/atau tindakan yang dapat mengakibatkan pengeluaran atas beban belanja negara.
14. PPK Pusat adalah PPK yang berkedudukan di BNPB.
15. Atasan langsung PPK Daerah adalah Kepala Pelaksana BPBD sebagai pejabat penandatangan SPM-RR, yang diangkat dan ditetapkan oleh Sekretaris Utama BNPB/selaku KPA atas nama Kepala BNPB.', 'BAB I PENDAHULUAN (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6490, 'perka-14-2011', 21, 'lain', 'BAB I PENDAHULUAN', NULL, 16, '16. PPK Daerah adalah pejabat dari lingkungan BPBD Provinsi/Kabupaten/Kota yang diusulkan oleh Gubernur/Bupati/Walikota yang diangkat dan ditetapkan oleh Sekretaris Utama selaku KPA atas nama Kepala BNPB.
17. Bendahara Pengeluaran yang selanjutnya disebut BP berkedudukan di BNPB adalah orang yang ditunjuk untuk menerima, menyimpan, membayarkan, menatausahakan dan mempertanggungjawabkan uang untuk keperluan belanja negara dalam rangka pelaksanaan APBN pada BNPB.
18. Bendahara Pengeluaran Pembantu yang selanjutnya disebut BPP berkedudukan di BPBD Provinsi/Kabupaten/Kota adalah bendahara yang membantu BP untuk melaksanakan pembayaran kepada yang berhak guna kelancaran pelaksanaan kegiatan tertentu.
19. Penanggung Jawab Operasional Kegiatan (PJOK) adalah pejabat yang ditetapkan oleh Gubernur/Bupati/Walikota yang diusulkan oleh SKPD terkait melalui BPBD Propinsi/Kabupaten/Kota yang diberi kewenangan melaksanakan sebagian kewenangan PPK Daerah yaitu untuk melakukan pengadaan barang dan jasa dengan pihak ketiga (kecuali penandatanganan kontrak/SPK) dan/atau swakelola di SKPD terkait serta bertanggungjawab terhadap fisik dan keuangan yang dikelolanya.
20. Jasa konstruksi adalah layanan jasa konsultansi perencanaan pekerjaan konstruksi, layanan jasa pelaksanaan pekerjaan konstruksi, dan layanan jasa konsultansi pengawasan pekerjaan konstruksi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6490, '16. PPK Daerah adalah pejabat dari lingkungan BPBD Provinsi/Kabupaten/Kota yang diusulkan oleh Gubernur/Bupati/Walikota yang diangkat dan ditetapkan oleh Sekretaris Utama selaku KPA atas nama Kepala BNPB.
17. Bendahara Pengeluaran yang selanjutnya disebut BP berkedudukan di BNPB adalah orang yang ditunjuk untuk menerima, menyimpan, membayarkan, menatausahakan dan mempertanggungjawabkan uang untuk keperluan belanja negara dalam rangka pelaksanaan APBN pada BNPB.
18. Bendahara Pengeluaran Pembantu yang selanjutnya disebut BPP berkedudukan di BPBD Provinsi/Kabupaten/Kota adalah bendahara yang membantu BP untuk melaksanakan pembayaran kepada yang berhak guna kelancaran pelaksanaan kegiatan tertentu.
19. Penanggung Jawab Operasional Kegiatan (PJOK) adalah pejabat yang ditetapkan oleh Gubernur/Bupati/Walikota yang diusulkan oleh SKPD terkait melalui BPBD Propinsi/Kabupaten/Kota yang diberi kewenangan melaksanakan sebagian kewenangan PPK Daerah yaitu untuk melakukan pengadaan barang dan jasa dengan pihak ketiga (kecuali penandatanganan kontrak/SPK) dan/atau swakelola di SKPD terkait serta bertanggungjawab terhadap fisik dan keuangan yang dikelolanya.
20. Jasa konstruksi adalah layanan jasa konsultansi perencanaan pekerjaan konstruksi, layanan jasa pelaksanaan pekerjaan konstruksi, dan layanan jasa konsultansi pengawasan pekerjaan konstruksi.', 'BAB I PENDAHULUAN', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6491, 'perka-14-2011', 22, 'lain', 'BAB I PENDAHULUAN (lanjutan 1)', NULL, 16, '21. Jasa non konstruksi adalah layanan jasa keahlian profesional dalam berbagai bidang yang meliputi jasa perencanaan dan pengawasan non konstruksi (misal, pelayanan kesehatan, konseling, pengadaan sarana produksi, dan lain-lain) dalam rangka mencapai sasaran tertentu, disusun secara sistematis berdasarkan kerangka acuan kerja yang ditetapkan oleh pengguna jasa (PPK).
22. Perencanaan adalah dokumen yang digunakan sebagai acuan bagi penyelenggaraan program pelaksanaan konstruksi dan non konstruksi pascabencana yang memuat informasi gambaran umum daerah, volume/luasan yang akan direhabilitasi, tahap pengerjaan, besaran biaya, persyaratan teknis pelaksanaannya dan pihak-pihak yang terlibat dalam kegiatan serta jangka waktu pelaksanaan.
23. Perencanaan Rehabilitasi dan Rekonstruksi adalah dokumen yang digunakan dalam penentuan tindakan masa depan yang sejalan dengan perencanaan pembangunan dengan mendasarkan pada pengkajian kebutuhan pascabencana.
24. Pengkajian kebutuhan pascabencana adalah suatu rangkaian kegiatan pengkajian dan penilaian akibat, analisis dampak, dan perkiraan kebutuhan, yang menjadi dasar bagi penyusunan rencana aksi rehabilitasi dan rekonstruksi. Pengkajian dan penilaian meliputi identifikasi dan perhitungan kerusakan dan kerugian fisik dan non fisik yang menyangkut aspek kemanusiaan, perumahan atau pemukiman, infrastruktur, ekonomi, sosial dan lintas sektor.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6491, '21. Jasa non konstruksi adalah layanan jasa keahlian profesional dalam berbagai bidang yang meliputi jasa perencanaan dan pengawasan non konstruksi (misal, pelayanan kesehatan, konseling, pengadaan sarana produksi, dan lain-lain) dalam rangka mencapai sasaran tertentu, disusun secara sistematis berdasarkan kerangka acuan kerja yang ditetapkan oleh pengguna jasa (PPK).
22. Perencanaan adalah dokumen yang digunakan sebagai acuan bagi penyelenggaraan program pelaksanaan konstruksi dan non konstruksi pascabencana yang memuat informasi gambaran umum daerah, volume/luasan yang akan direhabilitasi, tahap pengerjaan, besaran biaya, persyaratan teknis pelaksanaannya dan pihak-pihak yang terlibat dalam kegiatan serta jangka waktu pelaksanaan.
23. Perencanaan Rehabilitasi dan Rekonstruksi adalah dokumen yang digunakan dalam penentuan tindakan masa depan yang sejalan dengan perencanaan pembangunan dengan mendasarkan pada pengkajian kebutuhan pascabencana.
24. Pengkajian kebutuhan pascabencana adalah suatu rangkaian kegiatan pengkajian dan penilaian akibat, analisis dampak, dan perkiraan kebutuhan, yang menjadi dasar bagi penyusunan rencana aksi rehabilitasi dan rekonstruksi. Pengkajian dan penilaian meliputi identifikasi dan perhitungan kerusakan dan kerugian fisik dan non fisik yang menyangkut aspek kemanusiaan, perumahan atau pemukiman, infrastruktur, ekonomi, sosial dan lintas sektor.', 'BAB I PENDAHULUAN (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6492, 'perka-14-2011', 23, 'lain', 'BAB I PENDAHULUAN (lanjutan 2)', NULL, 16, '25. Pemantauan adalah kegiatan mengamati perkembangan pelaksanaan rencana kegiatan rehabilitasi dan rekonstruksi dalam sistem pembangunan nasional dan daerah untuk mengidentifikasi, serta mengantisipasi permasalahan yang akan timbul untuk dapat diambil tindakan sedini mungkin.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6492, '25. Pemantauan adalah kegiatan mengamati perkembangan pelaksanaan rencana kegiatan rehabilitasi dan rekonstruksi dalam sistem pembangunan nasional dan daerah untuk mengidentifikasi, serta mengantisipasi permasalahan yang akan timbul untuk dapat diambil tindakan sedini mungkin.', 'BAB I PENDAHULUAN (lanjutan 2)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6493, 'perka-14-2011', 24, 'lain', 'BAB I PENDAHULUAN', NULL, 17, '26. Evaluasi adalah rangkaian kegiatan membandingkan realisasi masukan (input), keluaran (output), dan hasil (outcome) terhadap rencana kegiatan rehabilitasi dan rekonstruksi dan standar.
27. Rencana Aksi Rehabilitasi dan Rekonstruksi adalah dokumen perencanaan sebagai hasil penyusunan rencana rehabilitasi dan rekonstruksi yang akan dilakukan dalam periode waktu tertentu yang disusun secara bersama-sama antara BNPB dan/atau BPBD bersama Kementerian/Lembaga, SKPD serta pemangku kepentingan terkait.
28. Proposal adalah rencana yang dituangkan dalam bentuk rancangan kerja atau dengan kata lain usulan/uraian kegiatan yang direncanakan.
29. Perencanaan teknis konstruksi adalah dokumen yang disusun terhadap suatu kegiatan untuk merumuskan perincian jenis dan dimensi/spesifikasi teknis dalam hal kualitas, volume, perkiraan biaya dan jangka waktu pelaksanaan yang digunakan sebagai dasar dalam membangun konstruksi.
30. Perencanaan teknis non konstruksi adalah suatu kegiatan untuk merumuskan perincian jenis dan dimensi/spesifikasi teknis dalam hal kualitas, volume, perkiraan biaya dan jangka waktu pelaksanaan yang berbentuk Kerangka Acuan Kerja (KAK) dan digunakan sebagai dasar dalam melaksanakan kegiatan non konstruksi.
31. Supervisi/Pengawasan teknis adalah suatu kegiatan yang dilakukan pada saat pelaksanaan kegiatan konstruksi agar hasilnya sesuai dengan spesifikasi teknis yang ditetapkan dan dilaksanakan oleh konsultan supervisi/pengawas teknis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6493, '26. Evaluasi adalah rangkaian kegiatan membandingkan realisasi masukan (input), keluaran (output), dan hasil (outcome) terhadap rencana kegiatan rehabilitasi dan rekonstruksi dan standar.
27. Rencana Aksi Rehabilitasi dan Rekonstruksi adalah dokumen perencanaan sebagai hasil penyusunan rencana rehabilitasi dan rekonstruksi yang akan dilakukan dalam periode waktu tertentu yang disusun secara bersama-sama antara BNPB dan/atau BPBD bersama Kementerian/Lembaga, SKPD serta pemangku kepentingan terkait.
28. Proposal adalah rencana yang dituangkan dalam bentuk rancangan kerja atau dengan kata lain usulan/uraian kegiatan yang direncanakan.
29. Perencanaan teknis konstruksi adalah dokumen yang disusun terhadap suatu kegiatan untuk merumuskan perincian jenis dan dimensi/spesifikasi teknis dalam hal kualitas, volume, perkiraan biaya dan jangka waktu pelaksanaan yang digunakan sebagai dasar dalam membangun konstruksi.
30. Perencanaan teknis non konstruksi adalah suatu kegiatan untuk merumuskan perincian jenis dan dimensi/spesifikasi teknis dalam hal kualitas, volume, perkiraan biaya dan jangka waktu pelaksanaan yang berbentuk Kerangka Acuan Kerja (KAK) dan digunakan sebagai dasar dalam melaksanakan kegiatan non konstruksi.
31. Supervisi/Pengawasan teknis adalah suatu kegiatan yang dilakukan pada saat pelaksanaan kegiatan konstruksi agar hasilnya sesuai dengan spesifikasi teknis yang ditetapkan dan dilaksanakan oleh konsultan supervisi/pengawas teknis.', 'BAB I PENDAHULUAN', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6494, 'perka-14-2011', 25, 'lain', 'BAB I PENDAHULUAN (lanjutan 1)', NULL, 17, '32. Pendampingan adalah suatu kegiatan BPBD Provinsi untuk mendampingi pelaksanaan kegiatan di Provinsi/Kabupaten/Kota berupa pemantauan, evaluasi dan koordinasi termasuk menyiapkan fasilitator kelompok masyarakat (teknis dan non teknis), pelatihan, pengawasan teknis pada kegiatan pelaksanaan non konstruksi.
33. Kegiatan konstruksi adalah pemulihan dan pembangunan kembali fisik yang rusak akibat bencana yang mengandung unsur kegiatan mitigasi dan pengurangan risiko bencana.
34. Kegiatan non konstruksi adalah kegiatan pemulihan dan pembangunan kembali sendi kehidupan sosial ekonomi masyarakat yang hilang dan/atau rusak akibat bencana.
35. Koordinasi adalah kegiatan manajemen yang mencakup penyusunan rencana, pelaksanaan kegiatan, dan monitoring evaluasi yang dilakukan dalam bentuk pertemuan atau rapat; konsultasi; permintaan laporan, analisis dan umpan balik baik secara lisan maupun secara tertulis yang mengarah pada upaya penyelesaian permasalahan yang dihadapi untuk mencapai tujuan rehabilitasi dan rekonstruksi yang ditetapkan.
36. Surat Permintaan Pembayaran yang selanjutnya disebut SPP adalah dokumen yang diterbitkan oleh Pejabat Pembuat Komitmen yang berisi permintaan kepada Pejabat Penanda Tangan SPM untuk menerbitkan surat perintah membayar sejumlah uang atas beban bagian anggaran yang dikuasainya untuk pihak yang ditunjuk dan sesuai syarat-syarat yang ditentukan dalam dokumen perikatan yang menjadi dasar penerbitan SPP berkenaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6494, '32. Pendampingan adalah suatu kegiatan BPBD Provinsi untuk mendampingi pelaksanaan kegiatan di Provinsi/Kabupaten/Kota berupa pemantauan, evaluasi dan koordinasi termasuk menyiapkan fasilitator kelompok masyarakat (teknis dan non teknis), pelatihan, pengawasan teknis pada kegiatan pelaksanaan non konstruksi.
33. Kegiatan konstruksi adalah pemulihan dan pembangunan kembali fisik yang rusak akibat bencana yang mengandung unsur kegiatan mitigasi dan pengurangan risiko bencana.
34. Kegiatan non konstruksi adalah kegiatan pemulihan dan pembangunan kembali sendi kehidupan sosial ekonomi masyarakat yang hilang dan/atau rusak akibat bencana.
35. Koordinasi adalah kegiatan manajemen yang mencakup penyusunan rencana, pelaksanaan kegiatan, dan monitoring evaluasi yang dilakukan dalam bentuk pertemuan atau rapat; konsultasi; permintaan laporan, analisis dan umpan balik baik secara lisan maupun secara tertulis yang mengarah pada upaya penyelesaian permasalahan yang dihadapi untuk mencapai tujuan rehabilitasi dan rekonstruksi yang ditetapkan.
36. Surat Permintaan Pembayaran yang selanjutnya disebut SPP adalah dokumen yang diterbitkan oleh Pejabat Pembuat Komitmen yang berisi permintaan kepada Pejabat Penanda Tangan SPM untuk menerbitkan surat perintah membayar sejumlah uang atas beban bagian anggaran yang dikuasainya untuk pihak yang ditunjuk dan sesuai syarat-syarat yang ditentukan dalam dokumen perikatan yang menjadi dasar penerbitan SPP berkenaan.', 'BAB I PENDAHULUAN (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6495, 'perka-14-2011', 26, 'lain', 'BAB I PENDAHULUAN', NULL, 18, '37. Surat Perintah Membayar yang selanjutnya disebut SPM adalah surat perintah yang diterbitkan oleh Pejabat Penanda Tangan SPM untuk dan atas nama Pengguna Anggaran kepada Bendahara Umum Negara atau kuasanya berdasarkan SPP untuk melakukan pembayaran sejumlah uang kepada pihak dan atas beban anggaran yang ditunjuk dalam SPP berkenaan.
38. Surat Perintah Membayar Langsung selanjutnya disebut SPM-LS adalah surat perintah membayar langsung kepada pihak ketiga yang diterbitkan oleh Pengguna Anggaran/Kuasa Pengguna Anggaran atas dasar perjanjian kontrak kerja atau surat perintah kerja lainnya.
39. Surat Permintaan Pembayaran Rehabilitasi dan Rekonstruksi yang selanjutnya disebut SPP-RR adalah dokumen yang diterbitkan oleh Pejabat Pembuat Komitmen (PPK) Daerah yang berisi permintaan kepada Pejabat Penanda Tangan SPM-RR untuk menerbitkan surat perintah membayar sejumlah uang atas beban bagian anggaran rehabilitasi dan rekonstruksi yang dikuasainya untuk pihak yang ditunjuk dan sesuai syarat-syarat yang ditentukan dalam dokumen perikatan yang menjadi dasar penerbitan SPP-RR berkenaan.
40. Surat Perintah Membayar Rehabilitasi dan Rekonstruksi yang selanjutnya disebut SPM-RR adalah surat perintah yang diterbitkan oleh Pejabat Penanda Tangan SPM untuk dan atas nama Kuasa Pengguna Anggaran Kepada BPP atau kuasanya berdasarkan SPP-RR untuk melakukan pembayaran sejumlah uang kepada pihak dan atas beban anggaran rehabilitasi dan rekonstruksi yang ditunjuk dalam SPP-RR berkenaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6495, '37. Surat Perintah Membayar yang selanjutnya disebut SPM adalah surat perintah yang diterbitkan oleh Pejabat Penanda Tangan SPM untuk dan atas nama Pengguna Anggaran kepada Bendahara Umum Negara atau kuasanya berdasarkan SPP untuk melakukan pembayaran sejumlah uang kepada pihak dan atas beban anggaran yang ditunjuk dalam SPP berkenaan.
38. Surat Perintah Membayar Langsung selanjutnya disebut SPM-LS adalah surat perintah membayar langsung kepada pihak ketiga yang diterbitkan oleh Pengguna Anggaran/Kuasa Pengguna Anggaran atas dasar perjanjian kontrak kerja atau surat perintah kerja lainnya.
39. Surat Permintaan Pembayaran Rehabilitasi dan Rekonstruksi yang selanjutnya disebut SPP-RR adalah dokumen yang diterbitkan oleh Pejabat Pembuat Komitmen (PPK) Daerah yang berisi permintaan kepada Pejabat Penanda Tangan SPM-RR untuk menerbitkan surat perintah membayar sejumlah uang atas beban bagian anggaran rehabilitasi dan rekonstruksi yang dikuasainya untuk pihak yang ditunjuk dan sesuai syarat-syarat yang ditentukan dalam dokumen perikatan yang menjadi dasar penerbitan SPP-RR berkenaan.
40. Surat Perintah Membayar Rehabilitasi dan Rekonstruksi yang selanjutnya disebut SPM-RR adalah surat perintah yang diterbitkan oleh Pejabat Penanda Tangan SPM untuk dan atas nama Kuasa Pengguna Anggaran Kepada BPP atau kuasanya berdasarkan SPP-RR untuk melakukan pembayaran sejumlah uang kepada pihak dan atas beban anggaran rehabilitasi dan rekonstruksi yang ditunjuk dalam SPP-RR berkenaan.', 'BAB I PENDAHULUAN', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6496, 'perka-14-2011', 27, 'lain', 'BAB I PENDAHULUAN (lanjutan 1)', NULL, 18, '41. Surat Perintah Membayar Rehabilitasi dan Rekonstruksi selanjutnya disebut SPM-RR adalah surat perintah membayar langsung kepada pihak ketiga yang diterbitkan oleh dan/atau atas nama Pengguna Anggaran/Kuasa Pengguna Anggaran atas dasar perjanjian kontrak kerja atau surat perintah kerja kegiatan rehabilitasi dan rekonstruksi lainnya.
42. Surat Perintah Pencairan Dana selanjutnya disebut SP2D adalah surat perintah yang diterbitkan oleh KPPN selaku Kuasa Bendahara Umum Negara untuk pelaksanaan pengeluaran atas beban Anggaran Pendapatan dan Belanja Negara (APBN) berdasarkan SPM.
43. Bantuan Langsung Masyarakat selanjutnya disebut BLM adalah bantuan dari Pemerintah pusat/daerah yang diterima langsung oleh masyarakat dan/atau lembaga kemasyarakatan termasuk lembaga non-pemerintah bidang pendidikan dan keagamaan.
44. Non Bantuan Langsung Masyarakat selanjutnya disebut Non-BLM adalah bantuan dari Pemerintah pusat/daerah yang tidak langsung diterima oleh masyarakat dan/atau lembaga kemasyarakatan termasuk lembaga non-pemerintah bidang pendidikan dan keagamaan.
45. Laporan Keuangan adalah bentuk pertanggungjawaban pengelolaan keuangan negara/daerah selama suatu periode.
46. Kinerja adalah keluaran/hasil dari kegiatan/program yang hendak atau telah dicapai sehubungan dengan penggunaan anggaran dengan kuantitas dan kualitas terukur.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6496, '41. Surat Perintah Membayar Rehabilitasi dan Rekonstruksi selanjutnya disebut SPM-RR adalah surat perintah membayar langsung kepada pihak ketiga yang diterbitkan oleh dan/atau atas nama Pengguna Anggaran/Kuasa Pengguna Anggaran atas dasar perjanjian kontrak kerja atau surat perintah kerja kegiatan rehabilitasi dan rekonstruksi lainnya.
42. Surat Perintah Pencairan Dana selanjutnya disebut SP2D adalah surat perintah yang diterbitkan oleh KPPN selaku Kuasa Bendahara Umum Negara untuk pelaksanaan pengeluaran atas beban Anggaran Pendapatan dan Belanja Negara (APBN) berdasarkan SPM.
43. Bantuan Langsung Masyarakat selanjutnya disebut BLM adalah bantuan dari Pemerintah pusat/daerah yang diterima langsung oleh masyarakat dan/atau lembaga kemasyarakatan termasuk lembaga non-pemerintah bidang pendidikan dan keagamaan.
44. Non Bantuan Langsung Masyarakat selanjutnya disebut Non-BLM adalah bantuan dari Pemerintah pusat/daerah yang tidak langsung diterima oleh masyarakat dan/atau lembaga kemasyarakatan termasuk lembaga non-pemerintah bidang pendidikan dan keagamaan.
45. Laporan Keuangan adalah bentuk pertanggungjawaban pengelolaan keuangan negara/daerah selama suatu periode.
46. Kinerja adalah keluaran/hasil dari kegiatan/program yang hendak atau telah dicapai sehubungan dengan penggunaan anggaran dengan kuantitas dan kualitas terukur.', 'BAB I PENDAHULUAN (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6497, 'perka-14-2011', 28, 'lain', 'BAB I PENDAHULUAN', NULL, 19, '47. Laporan Kinerja adalah ikhtisar yang menjelaskan secara ringkas dan lengkap tentang capaian kinerja yang disusun berdasarkan rencana kerja yang ditetapkan dalam rangka pelaksanaan APBN/APBD.
48. Surat Keputusan Penetapan Alokasi selanjutnya disebut SKPA adalah surat keputusan Kepala BNPB yang menetapkan alokasi dana bantuan sosial berpola hibah kepada penerima bantuan.
49. Naskah Kesepakatan adalah bentuk perjanjian kerjasama antara Kepala BNPB dengan Gubernur/Bupati/Walikota dalam penggunaan dana bantuan sosial berpola hibah untuk kegiatan rehabilitasi dan rekonstruksi pascabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6497, '47. Laporan Kinerja adalah ikhtisar yang menjelaskan secara ringkas dan lengkap tentang capaian kinerja yang disusun berdasarkan rencana kerja yang ditetapkan dalam rangka pelaksanaan APBN/APBD.
48. Surat Keputusan Penetapan Alokasi selanjutnya disebut SKPA adalah surat keputusan Kepala BNPB yang menetapkan alokasi dana bantuan sosial berpola hibah kepada penerima bantuan.
49. Naskah Kesepakatan adalah bentuk perjanjian kerjasama antara Kepala BNPB dengan Gubernur/Bupati/Walikota dalam penggunaan dana bantuan sosial berpola hibah untuk kegiatan rehabilitasi dan rekonstruksi pascabencana.', 'BAB I PENDAHULUAN', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6498, 'perka-14-2011', 29, 'lain', 'BAB II KRITERIA, PRINSIP DASAR, KEBIJAKAN DAN STRATEGI', NULL, 20, 'BAB II KRITERIA, PRINSIP DASAR, KEBIJAKAN DAN STRATEGI');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6498, 'BAB II KRITERIA, PRINSIP DASAR, KEBIJAKAN DAN STRATEGI', 'BAB II KRITERIA, PRINSIP DASAR, KEBIJAKAN DAN STRATEGI', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6499, 'perka-14-2011', 30, 'lain', 'BAB II', NULL, 20, 'KRITERIA, PRINSIP DASAR, KEBIJAKAN DAN STRATEGI A. Kriteria Kriteria penggunaan dana bantuan sosial berpola hibah sebagaimana yang dimaksud dalam Naskah Kesepakatan adalah:
1. Sebagai pendukung strategis ekonomi daerah terkena bencana.
2. Untuk kegiatan mitigasi dan/atau peningkatan konstruksi selektif yang secara teknis harus segera ditangani.
3. Tidak ada duplikasi dalam pembiayaan.
4. Cepat, tepat dan segera bermanfaat bagi masyarakat.
5. Pemberian bantuan berupa stimulus, untuk kerusakan bangunan non pemerintah akibat bencana.
6. Bukan untuk operasional pemeliharaan kantor dan bukan untuk kegiatan penguatan kelembagaan (belanja modal, seperti: pembangunan gedung kantor, pembelian fasilitas kantor dan lain-lain).
7. Pendukung operasional pengelolaan kegiatan rehabilitasi dan rekonstruksi pascabencana, terdiri dari:
a. Pengadaan ATK, penggandaan dokumen.
b. Honorarium pengelola kegiatan.
c. Kegiatan koordinasi (rapat).
d. Perjalanan dinas.
e. Biaya penunjang pengadaan barang dan jasa.
f. Penunjang kegiatan rehabilitasi dan rekonstruksi pascabencana.
B. Prinsip Dasar
1. Pemerintah dan Pemerintah Daerah bersama masyarakat, Dunia Usaha dan BUMD/N bertanggung jawab dalam penyelenggaraan rehabilitasi dan rekonstruksi pascabencana.
2. Dana bantuan sosial berpola hibah digunakan untuk kegiatan rehabilitasi dan rekonstruksi pascabencana terhadap obyek-obyek fisik dan non fisik yang terkena dampak langsung bencana maupun tidak langsung sesuai ketentuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6499, 'KRITERIA, PRINSIP DASAR, KEBIJAKAN DAN STRATEGI A. Kriteria Kriteria penggunaan dana bantuan sosial berpola hibah sebagaimana yang dimaksud dalam Naskah Kesepakatan adalah:
1. Sebagai pendukung strategis ekonomi daerah terkena bencana.
2. Untuk kegiatan mitigasi dan/atau peningkatan konstruksi selektif yang secara teknis harus segera ditangani.
3. Tidak ada duplikasi dalam pembiayaan.
4. Cepat, tepat dan segera bermanfaat bagi masyarakat.
5. Pemberian bantuan berupa stimulus, untuk kerusakan bangunan non pemerintah akibat bencana.
6. Bukan untuk operasional pemeliharaan kantor dan bukan untuk kegiatan penguatan kelembagaan (belanja modal, seperti: pembangunan gedung kantor, pembelian fasilitas kantor dan lain-lain).
7. Pendukung operasional pengelolaan kegiatan rehabilitasi dan rekonstruksi pascabencana, terdiri dari:
a. Pengadaan ATK, penggandaan dokumen.
b. Honorarium pengelola kegiatan.
c. Kegiatan koordinasi (rapat).
d. Perjalanan dinas.
e. Biaya penunjang pengadaan barang dan jasa.
f. Penunjang kegiatan rehabilitasi dan rekonstruksi pascabencana.
B. Prinsip Dasar
1. Pemerintah dan Pemerintah Daerah bersama masyarakat, Dunia Usaha dan BUMD/N bertanggung jawab dalam penyelenggaraan rehabilitasi dan rekonstruksi pascabencana.
2. Dana bantuan sosial berpola hibah digunakan untuk kegiatan rehabilitasi dan rekonstruksi pascabencana terhadap obyek-obyek fisik dan non fisik yang terkena dampak langsung bencana maupun tidak langsung sesuai ketentuan.', 'BAB II', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6500, 'perka-14-2011', 31, 'lain', 'BAB II (lanjutan 1)', NULL, 20, '3. Dana bantuan sosial berpola hibah bukan dana transfer daerah, oleh karena itu tidak dimasukkan dalam sistem pengelolaan APBD. Jumlah dana yang diterima cukup dilaporkan sebagai Catatan atas Laporan Keuangan (CaLK) dalam pertanggungjawaban APBD.
4. Besarnya bantuan dana sosial berpola hibah maksimum diberikan sebesar Surat Keputusan Penetapan Alokasi, yang selanjutnya dapat dituangkan dalam Naskah Kesepakatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6500, '3. Dana bantuan sosial berpola hibah bukan dana transfer daerah, oleh karena itu tidak dimasukkan dalam sistem pengelolaan APBD. Jumlah dana yang diterima cukup dilaporkan sebagai Catatan atas Laporan Keuangan (CaLK) dalam pertanggungjawaban APBD.
4. Besarnya bantuan dana sosial berpola hibah maksimum diberikan sebesar Surat Keputusan Penetapan Alokasi, yang selanjutnya dapat dituangkan dalam Naskah Kesepakatan.', 'BAB II (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6501, 'perka-14-2011', 32, 'lain', 'BAB II KRITERIA, PRINSIP DASAR, KEBIJAKAN DAN STRATEGI', NULL, 21, '5. Penggunaan dana bantuan sosial berpola hibah dapat digunakan selama tahun anggaran berjalan sampai satu tahun anggaran berikutnya.
6. Penerima dana bantuan sosial berpola hibah wajib mempertanggungjawabkan pengelolaannya sesuai tatacara dan mekanisme pengelolaan APBN dengan beberapa penyesuaian yang diatur dalam pedoman.
7. Penerima dana bantuan sosial berpola hibah yang tidak dapat menyelesaikan penggunaan dana sesuai waktu yang telah ditetapkan, maka sisa dana termasuk pendapatan jasa giro disetor seluruhnya ke kas negara. Sebagai konsekuensinya, sisa pekerjaan yang belum dibayar wajib dibiayai dari dana APBD atau sumber lain yang sah.
C. Kebijakan
1. Menggunakan pendekatan tugas pokok dan fungsi serta kewenangan Pemerintah, Pemerintah Provinsi/Kabupaten/Kota dan institusi non pemerintah yang terkait.
2. Dana bantuan sosial berpola hibah ini dialokasikan bagi daerah yang telah membentuk BPBD Provinsi/Kabupaten/ Kota.
3. Badan Penanggulangan Bencana Daerah (BPBD) Provinsi/Kabupaten/Kota sebagai Koordinator, Satuan Kerja Perangkat Daerah (SKPD) terkait sebagai pelaksana pekerjaan kontruksi dan non konstruksi.
4. Menggunakan prinsip integrasi dan sinkronisasi sumberdaya secara komprehensif untuk mencapai efektivitas dan efisiensi.
5. Dilaksanakan tepat waktu secara terencana, terpadu, koordinatif dan berkesinambungan dengan perencanaan pembangunan daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6501, '5. Penggunaan dana bantuan sosial berpola hibah dapat digunakan selama tahun anggaran berjalan sampai satu tahun anggaran berikutnya.
6. Penerima dana bantuan sosial berpola hibah wajib mempertanggungjawabkan pengelolaannya sesuai tatacara dan mekanisme pengelolaan APBN dengan beberapa penyesuaian yang diatur dalam pedoman.
7. Penerima dana bantuan sosial berpola hibah yang tidak dapat menyelesaikan penggunaan dana sesuai waktu yang telah ditetapkan, maka sisa dana termasuk pendapatan jasa giro disetor seluruhnya ke kas negara. Sebagai konsekuensinya, sisa pekerjaan yang belum dibayar wajib dibiayai dari dana APBD atau sumber lain yang sah.
C. Kebijakan
1. Menggunakan pendekatan tugas pokok dan fungsi serta kewenangan Pemerintah, Pemerintah Provinsi/Kabupaten/Kota dan institusi non pemerintah yang terkait.
2. Dana bantuan sosial berpola hibah ini dialokasikan bagi daerah yang telah membentuk BPBD Provinsi/Kabupaten/ Kota.
3. Badan Penanggulangan Bencana Daerah (BPBD) Provinsi/Kabupaten/Kota sebagai Koordinator, Satuan Kerja Perangkat Daerah (SKPD) terkait sebagai pelaksana pekerjaan kontruksi dan non konstruksi.
4. Menggunakan prinsip integrasi dan sinkronisasi sumberdaya secara komprehensif untuk mencapai efektivitas dan efisiensi.
5. Dilaksanakan tepat waktu secara terencana, terpadu, koordinatif dan berkesinambungan dengan perencanaan pembangunan daerah.', 'BAB II KRITERIA, PRINSIP DASAR, KEBIJAKAN DAN STRATEGI', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6502, 'perka-14-2011', 33, 'lain', 'BAB II KRITERIA, PRINSIP DASAR, KEBIJAKAN DAN STRATEGI (lanjutan 1)', NULL, 21, '6. Untuk kejadian bencana lintas provinsi dan/atau antar kabupaten/kota dalam satu provinsi dan/atau dalam kondisi tertentu, maka Kepala BNPB dapat membentuk Tim Pendukung Teknis (TPT) dan/atau Unit Manajemen Proyek (UMP) sebagai lembaga yang bersifat sementara (ad hoc) dalam rangka pendampingan pelaksanaan kegiatan rehabilitasi dan rekonstruksi.
D. Strategi
1. Program rehabilitasi dan rekonstruksi sektor perumahan, sektor ekonomi, sektor sosial dan lintas sektor berbasis komunitas dirancang dengan strategi pengorganisasian masyarakat (Community Organizing) dan bertumpu pada inisiatif dan prakarsa masyarakat (Participatory Development) dengan tidak meninggalkan kearifan lokal.
2. Khusus untuk Bantuan Langsung Masyarakat (BLM) dilaksanakan melalui Kelompok Masyarakat (POKMAS) yang berbasis masyarakat.
3. Melaksanakan percepatan pengadaan penyedia jasa perencanaan teknis sebelum MoU. Penandatanganan kontrak jasa perencanaan teknis dilaksanakan setelah dokumen anggaran tersedia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6502, '6. Untuk kejadian bencana lintas provinsi dan/atau antar kabupaten/kota dalam satu provinsi dan/atau dalam kondisi tertentu, maka Kepala BNPB dapat membentuk Tim Pendukung Teknis (TPT) dan/atau Unit Manajemen Proyek (UMP) sebagai lembaga yang bersifat sementara (ad hoc) dalam rangka pendampingan pelaksanaan kegiatan rehabilitasi dan rekonstruksi.
D. Strategi
1. Program rehabilitasi dan rekonstruksi sektor perumahan, sektor ekonomi, sektor sosial dan lintas sektor berbasis komunitas dirancang dengan strategi pengorganisasian masyarakat (Community Organizing) dan bertumpu pada inisiatif dan prakarsa masyarakat (Participatory Development) dengan tidak meninggalkan kearifan lokal.
2. Khusus untuk Bantuan Langsung Masyarakat (BLM) dilaksanakan melalui Kelompok Masyarakat (POKMAS) yang berbasis masyarakat.
3. Melaksanakan percepatan pengadaan penyedia jasa perencanaan teknis sebelum MoU. Penandatanganan kontrak jasa perencanaan teknis dilaksanakan setelah dokumen anggaran tersedia.', 'BAB II KRITERIA, PRINSIP DASAR, KEBIJAKAN DAN STRATEGI (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6503, 'perka-14-2011', 34, 'lain', 'BAB II KRITERIA, PRINSIP DASAR, KEBIJAKAN DAN STRATEGI', NULL, 22, '4. Peran aktif BPBD dalam mengkoordinasikan dan mengendalikan SKPD terkait dan pihak lainnya dalam penyelenggaraan rehabilitasi dan rekonstruksi pascabencana.
5. Penentuan prioritas dan pemanfaatan sumberdaya lokal secara maksimal, komprehensif dan partisipatif berdasarkan penilaian kerusakan dan kerugian pascabencana secara cermat dan akurat baik meliputi aspek fisik dan non fisik serta aspek kemanusiaan.
6. Pengajuan/permintaan dana bantuan sosial berpola hibah dilakukan berdasarkan pada dokumen rencana aksi rehabilitasi dan rekonstruksi atau dokumen perencanaan lain yang disetarakan serta memuat penentuan prioritas.
7. Pekerjaan konstruksi harus menggunakan jasa pihak ketiga (kontraktual) dan dilaksanakan oleh penyedia barang dan jasa berbadan usaha yang dinyatakan ahli dan profesional dibidang pelaksanaan konstruksi.
8. Dapat melibatkan Badan Pengawasan Keuangan dan Pembangunan (BPKP) setempat untuk pendampingan dalam pelaksanaan kegiatan rehabilitasi dan rekonstruksi pascabencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6503, '4. Peran aktif BPBD dalam mengkoordinasikan dan mengendalikan SKPD terkait dan pihak lainnya dalam penyelenggaraan rehabilitasi dan rekonstruksi pascabencana.
5. Penentuan prioritas dan pemanfaatan sumberdaya lokal secara maksimal, komprehensif dan partisipatif berdasarkan penilaian kerusakan dan kerugian pascabencana secara cermat dan akurat baik meliputi aspek fisik dan non fisik serta aspek kemanusiaan.
6. Pengajuan/permintaan dana bantuan sosial berpola hibah dilakukan berdasarkan pada dokumen rencana aksi rehabilitasi dan rekonstruksi atau dokumen perencanaan lain yang disetarakan serta memuat penentuan prioritas.
7. Pekerjaan konstruksi harus menggunakan jasa pihak ketiga (kontraktual) dan dilaksanakan oleh penyedia barang dan jasa berbadan usaha yang dinyatakan ahli dan profesional dibidang pelaksanaan konstruksi.
8. Dapat melibatkan Badan Pengawasan Keuangan dan Pembangunan (BPKP) setempat untuk pendampingan dalam pelaksanaan kegiatan rehabilitasi dan rekonstruksi pascabencana di daerah.', 'BAB II KRITERIA, PRINSIP DASAR, KEBIJAKAN DAN STRATEGI', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6504, 'perka-14-2011', 35, 'lain', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', NULL, 23, 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6504, 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6505, 'perka-14-2011', 36, 'lain', 'BAB III', NULL, 23, 'TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN A. Tatacara Pengajuan
1. Pengajuan Tatacara pengajuan dana bantuan sosial berpola hibah dilakukan dengan cara sebagai berikut:
a. Bupati/Walikota mengajukan proposal kepada Kepala BNPB untuk bencana skala kabupaten/kota atas rekomendasi Gubernur setelah sebelumnya mengeluarkan pernyataan bencana.
b. Gubernur mengajukan kepada Kepala BNPB untuk kejadian bencana lintas kabupaten/kota atau kewenangan provinsi berdasarkan pernyataan bencana dari Bupati/Walikota setempat.
c. Gubernur/Bupati/Walikota dapat menyusun rencana aksi di daerah atau yang disetarakan dengan dokumen perencanaan lainnya.
d. Penyusunan rencana aksi dalam bentuk dokumen perencanaan dilakukan BPBD bersama-sama SKPD yang mengalami dampak bencana termasuk penyusunan rencana kerja teknis sampai dengan rencana pemantauan dan evaluasi.
e. Persyaratan pengajuan dana bantuan sosial berpola hibah berdasarkan pada kejadian bencana yang terjadi pada kurun waktu tahun berjalan dan satu tahun sebelumnya.
2. Persyaratan Persiapan dilakukan melalui persyaratan administratif dan persyaratan teknis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6505, 'TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN A. Tatacara Pengajuan
1. Pengajuan Tatacara pengajuan dana bantuan sosial berpola hibah dilakukan dengan cara sebagai berikut:
a. Bupati/Walikota mengajukan proposal kepada Kepala BNPB untuk bencana skala kabupaten/kota atas rekomendasi Gubernur setelah sebelumnya mengeluarkan pernyataan bencana.
b. Gubernur mengajukan kepada Kepala BNPB untuk kejadian bencana lintas kabupaten/kota atau kewenangan provinsi berdasarkan pernyataan bencana dari Bupati/Walikota setempat.
c. Gubernur/Bupati/Walikota dapat menyusun rencana aksi di daerah atau yang disetarakan dengan dokumen perencanaan lainnya.
d. Penyusunan rencana aksi dalam bentuk dokumen perencanaan dilakukan BPBD bersama-sama SKPD yang mengalami dampak bencana termasuk penyusunan rencana kerja teknis sampai dengan rencana pemantauan dan evaluasi.
e. Persyaratan pengajuan dana bantuan sosial berpola hibah berdasarkan pada kejadian bencana yang terjadi pada kurun waktu tahun berjalan dan satu tahun sebelumnya.
2. Persyaratan Persiapan dilakukan melalui persyaratan administratif dan persyaratan teknis.', 'BAB III', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6506, 'perka-14-2011', 37, 'lain', 'BAB III (lanjutan 1)', NULL, 23, 'a. Persyaratan Administratif 1) Gubernur/Bupati/Walikota mengusulkan pejabat pengelola dana bantuan sosial berpola hibah untuk kegiatan rehabilitasi dan rekonstruksi yang terdiri dari: Kepala Pelaksana BPBD sebagai Atasan Langsung, PPK Daerah, dan BPP. Berdasarkan usulan dimaksud, Sekretaris Utama/selaku KPA atas nama Kepala BNPB menetapkan Atasan Langsung, PPK Daerah dan BPP yang berkedudukan di BPBD Provinsi/Kabupaten/Kota.
2) Gubernur/Bupati/Walikota menunjuk Pejabat Penanggung Jawab Operasional Kegiatan (PJOK) sesuai kompetensi dari SKPD teknis atas usulan SKPD terkait yang ditetapkan oleh keputusan Kepala Daerah melalui BPBD.
3) Gubernur/Bupati/Walikota membentuk Unit Layanan Pengadaan (ULP) sesuai Peraturan Presiden Nomor 54 Tahun 2010 tentang Pengadaan Barang/Jasa Pemerintah (Perpres 54/2010), yang melakukan pemilihan penyedia barang/jasa pemerintah untuk pekerjaan perencanaan teknis, pekerjaan konstruksi, dan supervisi di lingkungan BPBD atas usul Kepala BPBD Provinsi/Kabupaten/Kota.
Dalam hal belum memungkinkan dapat ditunjuk Pejabat Pengadaan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6506, 'a. Persyaratan Administratif 1) Gubernur/Bupati/Walikota mengusulkan pejabat pengelola dana bantuan sosial berpola hibah untuk kegiatan rehabilitasi dan rekonstruksi yang terdiri dari: Kepala Pelaksana BPBD sebagai Atasan Langsung, PPK Daerah, dan BPP. Berdasarkan usulan dimaksud, Sekretaris Utama/selaku KPA atas nama Kepala BNPB menetapkan Atasan Langsung, PPK Daerah dan BPP yang berkedudukan di BPBD Provinsi/Kabupaten/Kota.
2) Gubernur/Bupati/Walikota menunjuk Pejabat Penanggung Jawab Operasional Kegiatan (PJOK) sesuai kompetensi dari SKPD teknis atas usulan SKPD terkait yang ditetapkan oleh keputusan Kepala Daerah melalui BPBD.
3) Gubernur/Bupati/Walikota membentuk Unit Layanan Pengadaan (ULP) sesuai Peraturan Presiden Nomor 54 Tahun 2010 tentang Pengadaan Barang/Jasa Pemerintah (Perpres 54/2010), yang melakukan pemilihan penyedia barang/jasa pemerintah untuk pekerjaan perencanaan teknis, pekerjaan konstruksi, dan supervisi di lingkungan BPBD atas usul Kepala BPBD Provinsi/Kabupaten/Kota.
Dalam hal belum memungkinkan dapat ditunjuk Pejabat Pengadaan', 'BAB III (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6507, 'perka-14-2011', 38, 'lain', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', NULL, 24, 'dan Panitia Pengadaan Barang/Jasa Pemerintah sesuai ketentuan yang berlaku.
4) Gubernur/Bupati/Walikota menunjuk Panitia Pemeriksaan dan Penerimaan Hasil Pekerjaan sesuai Perpres 54/2010, yang melakukan proses serah terima pekerjaan perencanaan teknis, pekerjaan konstruksi, dan supervisi. Dalam hal belum memungkinkan, Gubernur/Bupati/Walikota dapat menunjuk Panitia Penerima Barang/Jasa Pemerintah, serta Panitia PHO (Provisional Hand Over) dan Panitia FHO (Final Hand Over) untuk pekerjaan konstruksi.
b. Persyaratan Teknis 1) BPP membuka rekening giro pada Bank pemerintah yang telah menjadi Bank persepsi KPPN setempat dan telah disetujui oleh Menteri Keuangan cq. Direktur Jenderal Perbendaharaan selaku Bendahara Umum Negara, atau Kepala Kantor Pelayanan Perbendaharaan Negara (KPPN) setempat selaku Kuasa Bendahara Umum Negara, atas nama BPP/Dana Rehabilitasi dan Rekonstruksi Pascabencana BPBD setempat.
2) Kepala Pelaksana BPBD menetapkan pejabat/pegawai di lingkungan BPBD sebagai Petugas Verifikator SPP-RR yang diserahi tugas melakukan penelitian dan pengujian terhadap SPP-RR yang diajukan oleh PPK.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6507, 'dan Panitia Pengadaan Barang/Jasa Pemerintah sesuai ketentuan yang berlaku.
4) Gubernur/Bupati/Walikota menunjuk Panitia Pemeriksaan dan Penerimaan Hasil Pekerjaan sesuai Perpres 54/2010, yang melakukan proses serah terima pekerjaan perencanaan teknis, pekerjaan konstruksi, dan supervisi. Dalam hal belum memungkinkan, Gubernur/Bupati/Walikota dapat menunjuk Panitia Penerima Barang/Jasa Pemerintah, serta Panitia PHO (Provisional Hand Over) dan Panitia FHO (Final Hand Over) untuk pekerjaan konstruksi.
b. Persyaratan Teknis 1) BPP membuka rekening giro pada Bank pemerintah yang telah menjadi Bank persepsi KPPN setempat dan telah disetujui oleh Menteri Keuangan cq. Direktur Jenderal Perbendaharaan selaku Bendahara Umum Negara, atau Kepala Kantor Pelayanan Perbendaharaan Negara (KPPN) setempat selaku Kuasa Bendahara Umum Negara, atas nama BPP/Dana Rehabilitasi dan Rekonstruksi Pascabencana BPBD setempat.
2) Kepala Pelaksana BPBD menetapkan pejabat/pegawai di lingkungan BPBD sebagai Petugas Verifikator SPP-RR yang diserahi tugas melakukan penelitian dan pengujian terhadap SPP-RR yang diajukan oleh PPK.', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6508, 'perka-14-2011', 39, 'lain', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN (lanjutan 1)', NULL, 24, '3) Persyaratan teknis pengajuan BLM adalah sebagai berikut : a) PPK Daerah melampirkan surat keputusan penetapan POKMAS dari Bupati/Walikota, daftar Nominatif penerima BLM yang mencantumkan jumlah dana dan nomor rekening Bank masing-masing kelompok. b) Penetapan POKMAS seperti pada huruf a) di atas dilaksanakan melalui proses kegiatan pengorganisasian warga bersama Lurah/Kepala Desa. Kegiatan pengorganisasian tersebut dilaksanakan melalui:
i. Rapat warga untuk membangun kesepakatan jumlah maksimum keanggotaan 10-20 KK per kelompok. ii. Menyusun data dan kebutuhan administratif termasuk di dalamnya membuat daftar kegiatan, kebutuhan dana serta pembuatan nomor rekening. iii. Menetapkan ketua dan sekretaris masing-masing kelompok. iv. Seluruh proses pengorganisasian disusun dalam berita acara yang diketahui oleh Camat yang ditetapkan dalam Surat Keputusan Kepala Daerah melalui PPK Daerah. c) POKMAS menyertakan surat pernyataan terhadap data yang sudah diverifikasi/validasi dan diketahui oleh PJOK.
4) Persyaratan teknis pengajuan Non BLM adalah sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6508, '3) Persyaratan teknis pengajuan BLM adalah sebagai berikut : a) PPK Daerah melampirkan surat keputusan penetapan POKMAS dari Bupati/Walikota, daftar Nominatif penerima BLM yang mencantumkan jumlah dana dan nomor rekening Bank masing-masing kelompok. b) Penetapan POKMAS seperti pada huruf a) di atas dilaksanakan melalui proses kegiatan pengorganisasian warga bersama Lurah/Kepala Desa. Kegiatan pengorganisasian tersebut dilaksanakan melalui:
i. Rapat warga untuk membangun kesepakatan jumlah maksimum keanggotaan 10-20 KK per kelompok. ii. Menyusun data dan kebutuhan administratif termasuk di dalamnya membuat daftar kegiatan, kebutuhan dana serta pembuatan nomor rekening. iii. Menetapkan ketua dan sekretaris masing-masing kelompok. iv. Seluruh proses pengorganisasian disusun dalam berita acara yang diketahui oleh Camat yang ditetapkan dalam Surat Keputusan Kepala Daerah melalui PPK Daerah. c) POKMAS menyertakan surat pernyataan terhadap data yang sudah diverifikasi/validasi dan diketahui oleh PJOK.
4) Persyaratan teknis pengajuan Non BLM adalah sebagai berikut:', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6509, 'perka-14-2011', 40, 'lain', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', NULL, 25, 'a) BPBD Provinsi/Kabupaten/Kota melakukan koordinasi dengan SKPD terkait untuk menentukan paket prioritas penggunaan alokasi dana yang telah ditetapkan oleh BNPB. b) BP BNPB melakukan transfer kepada BPP di daerah sebesar maksimal 50% (lima puluh perseratus) dari nilai bantuan yang ditetapkan dalam Surat Keputusan Alokasi. c) BP BNPB melakukan transfer dana Tahap II kepada BPP di daerah sebesar sisa dana alokasi, dilaksanakan setelah sisa pembayaran Tahap I maksimal sebesar 10% (sepuluh perseratus). d) Pembayaran seperti ketentuan huruf b) dan c) di atas, dilaksanakan setelah dilakukan verifikasi terhadap dokumen permintaan yang diajukan oleh PPK Daerah oleh PPK Pusat.
Uraian tugas organisasi pelaksana dapat dilihat dalam lampiran 1a struktur organisasi BLM dan lampiran 1b struktur organisasi non BLM.
B. Tatacara Pencairan
1. Bantuan Langsung Masyarakat (BLM) Mekanisme pencairan BLM dengan sumber dana APBN dilaksanakan sesuai Peraturan Dirjen Perbendaharan Nomor Per-63/Pb/2011 Tanggal 29 September 2011 (PERDIRJEN PBN), yang secara garis besar sebagaimana dijelaskan pada gambar 1 berikut:
Gambar 1 Bagan Alur Pencairan Bantuan Langsung Masyarakat Sumber: Peraturan Dirjen Perbendaharaan Nomor Per-63/Pb/2011 Tanggal 29 September 2011 Tentang Tata Cara Pembayaran Dana Rehabilitasi dan Rekonstruksi Pascabencana Tahun Anggaran 2011.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6509, 'a) BPBD Provinsi/Kabupaten/Kota melakukan koordinasi dengan SKPD terkait untuk menentukan paket prioritas penggunaan alokasi dana yang telah ditetapkan oleh BNPB. b) BP BNPB melakukan transfer kepada BPP di daerah sebesar maksimal 50% (lima puluh perseratus) dari nilai bantuan yang ditetapkan dalam Surat Keputusan Alokasi. c) BP BNPB melakukan transfer dana Tahap II kepada BPP di daerah sebesar sisa dana alokasi, dilaksanakan setelah sisa pembayaran Tahap I maksimal sebesar 10% (sepuluh perseratus). d) Pembayaran seperti ketentuan huruf b) dan c) di atas, dilaksanakan setelah dilakukan verifikasi terhadap dokumen permintaan yang diajukan oleh PPK Daerah oleh PPK Pusat.
Uraian tugas organisasi pelaksana dapat dilihat dalam lampiran 1a struktur organisasi BLM dan lampiran 1b struktur organisasi non BLM.
B. Tatacara Pencairan
1. Bantuan Langsung Masyarakat (BLM) Mekanisme pencairan BLM dengan sumber dana APBN dilaksanakan sesuai Peraturan Dirjen Perbendaharan Nomor Per-63/Pb/2011 Tanggal 29 September 2011 (PERDIRJEN PBN), yang secara garis besar sebagaimana dijelaskan pada gambar 1 berikut:
Gambar 1 Bagan Alur Pencairan Bantuan Langsung Masyarakat Sumber: Peraturan Dirjen Perbendaharaan Nomor Per-63/Pb/2011 Tanggal 29 September 2011 Tentang Tata Cara Pembayaran Dana Rehabilitasi dan Rekonstruksi Pascabencana Tahun Anggaran 2011.', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6510, 'perka-14-2011', 41, 'lain', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN (lanjutan 1)', NULL, 25, 'Mekanisme pencairan BLM adalah sebagai berikut : a) PJOK sebagai pihak yang bertanggungjawab dalam pelaksanaan kegiatan di masyarakat sudah dapat mengajukan kelengkapan dokumen pencairan dana sesuai proposal POKMAS yang telah diverifikasi oleh Tim Fasilitator. Usulan PJOK kepada PPK daerah dilampiri dengan :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6510, 'Mekanisme pencairan BLM adalah sebagai berikut : a) PJOK sebagai pihak yang bertanggungjawab dalam pelaksanaan kegiatan di masyarakat sudah dapat mengajukan kelengkapan dokumen pencairan dana sesuai proposal POKMAS yang telah diverifikasi oleh Tim Fasilitator. Usulan PJOK kepada PPK daerah dilampiri dengan :', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6511, 'perka-14-2011', 42, 'lain', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', NULL, 26, '1) Surat keputusan penetapan kelompok masyarakat penerima bantuan dari Bupati/Walikota setempat dan disahkan oleh PPK Daerah.
2) Surat Perjanjian Pengelolaan Bantuan (SPPB) (Formulir 01).
3) Rencana Anggaran Biaya (RAB) perumahan masing-masing pemilik rumah (Formulir 02).
4) Gambar rencana sederhana masing-masing pemilik rumah (Formulir 03).
5) Daftar nominatif anggota POKMAS berikut file elektronik (softcopy) (Formulir 04).
6) Kuitansi tanda terima masing-masing POKMAS (Formulir 05). b) Sesuai dengan dokumen pencairan yang diterima, PPK Daerah pada Provinsi/Kabupaten/Kota akan menyusun daftar Nominatif. Selanjutnya dokumen yang masuk akan dikirim kepada PPK Pusat untuk menerbitkan Surat Permintaan Pembayaran (SPP-LS). PPK Daerah mengajukan permintaan pembayaran Bantuan Langsung Masyarakat kepada PPK Pusat (Formulir 06) dengan dilampiri:
1) Surat keputusan penetapan kelompok masyarakat penerima bantuan dari Bupati/Walikota setempat dan disahkan oleh PPK Daerah.
2) Daftar nominatif kelompok masyarakat penerima bantuan yang mencantumkan jumlah dana dan nomor rekening Bank masing-masing kelompok berikut file elektronik (softcopy) (Formulir 07).
3) Berita acara pembayaran BLM (Formulir 08).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6511, '1) Surat keputusan penetapan kelompok masyarakat penerima bantuan dari Bupati/Walikota setempat dan disahkan oleh PPK Daerah.
2) Surat Perjanjian Pengelolaan Bantuan (SPPB) (Formulir 01).
3) Rencana Anggaran Biaya (RAB) perumahan masing-masing pemilik rumah (Formulir 02).
4) Gambar rencana sederhana masing-masing pemilik rumah (Formulir 03).
5) Daftar nominatif anggota POKMAS berikut file elektronik (softcopy) (Formulir 04).
6) Kuitansi tanda terima masing-masing POKMAS (Formulir 05). b) Sesuai dengan dokumen pencairan yang diterima, PPK Daerah pada Provinsi/Kabupaten/Kota akan menyusun daftar Nominatif. Selanjutnya dokumen yang masuk akan dikirim kepada PPK Pusat untuk menerbitkan Surat Permintaan Pembayaran (SPP-LS). PPK Daerah mengajukan permintaan pembayaran Bantuan Langsung Masyarakat kepada PPK Pusat (Formulir 06) dengan dilampiri:
1) Surat keputusan penetapan kelompok masyarakat penerima bantuan dari Bupati/Walikota setempat dan disahkan oleh PPK Daerah.
2) Daftar nominatif kelompok masyarakat penerima bantuan yang mencantumkan jumlah dana dan nomor rekening Bank masing-masing kelompok berikut file elektronik (softcopy) (Formulir 07).
3) Berita acara pembayaran BLM (Formulir 08).', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6512, 'perka-14-2011', 43, 'lain', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN (lanjutan 1)', NULL, 26, '4) Kuitansi tanda terima BLM dari PPK Daerah (Formulir 09). c) Dokumen pencairan yang dilengkapi SPP-LS akan dikirim ke Pejabat Penandatangan Surat Perintah Membayar (SPM-LS) di BNPB untuk diproses pencairannya ke KPPN Jakarta I. PPK Pusat mengajukan SPP-LS kepada Pejabat Penandatanganan SPM-LS dengan dilampiri:
1) Surat Keputusan Kepala BNPB tentang penetapan alokasi dana rehabilitasi dan rekonstruksi pascabencana.
2) Surat keputusan penetapan kelompok masyarakat penerima bantuan dari Bupati/Walikota setempat yang disahkan oleh PPK Daerah.
3) Daftar nominatif kelompok masyarakat penerima bantuan yang mencantumkan jumlah dana dan nomor rekening Bank masing-masing kelompok berikut file elektronik (softcopy) (Formulir 07).
4) Kuitansi tanda terima dari PPK Daerah (Formulir 09) .
5) Berita acara pembayaran BLM (Formulir 08).
6) Surat Pernyataan Tanggung Jawab Belanja (SPTB) (Formulir 10). d) SPM-LS untuk pembayaran BLM disampaikan kepada KPPN Jakarta I dengan dilampiri:
1) Surat Pernyataan Tanggung Jawab Belanja (SPTB) (Formulir 10).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6512, '4) Kuitansi tanda terima BLM dari PPK Daerah (Formulir 09). c) Dokumen pencairan yang dilengkapi SPP-LS akan dikirim ke Pejabat Penandatangan Surat Perintah Membayar (SPM-LS) di BNPB untuk diproses pencairannya ke KPPN Jakarta I. PPK Pusat mengajukan SPP-LS kepada Pejabat Penandatanganan SPM-LS dengan dilampiri:
1) Surat Keputusan Kepala BNPB tentang penetapan alokasi dana rehabilitasi dan rekonstruksi pascabencana.
2) Surat keputusan penetapan kelompok masyarakat penerima bantuan dari Bupati/Walikota setempat yang disahkan oleh PPK Daerah.
3) Daftar nominatif kelompok masyarakat penerima bantuan yang mencantumkan jumlah dana dan nomor rekening Bank masing-masing kelompok berikut file elektronik (softcopy) (Formulir 07).
4) Kuitansi tanda terima dari PPK Daerah (Formulir 09) .
5) Berita acara pembayaran BLM (Formulir 08).
6) Surat Pernyataan Tanggung Jawab Belanja (SPTB) (Formulir 10). d) SPM-LS untuk pembayaran BLM disampaikan kepada KPPN Jakarta I dengan dilampiri:
1) Surat Pernyataan Tanggung Jawab Belanja (SPTB) (Formulir 10).', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6513, 'perka-14-2011', 44, 'lain', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', NULL, 27, '2) Daftar nominatif kelompok masyarakat penerima bantuan yang mencantumkan jumlah dana dan nomor rekening Bank masing-masing kelompok berikut file elektronik (softcopy) (Formulir 07).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6513, '2) Daftar nominatif kelompok masyarakat penerima bantuan yang mencantumkan jumlah dana dan nomor rekening Bank masing-masing kelompok berikut file elektronik (softcopy) (Formulir 07).', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6514, 'perka-14-2011', 45, 'lain', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN (lanjutan 1)', NULL, 27, '3) Arsip data komputer (ADK) SPM-LS termasuk di dalamnya memuat daftar nomor rekening. e) KPPN Jakarta I akan menerbitkan Surat Perintah Pencairan Dana (SP2D) yang ditujukan ke Bank Pelaksana dimana BP membuka rekening yang berisi perintah untuk mencairkan sejumlah dana ke rekening masing-masing POKMAS. f) Pada saat yang bersamaan dengan penerbitan SP2D ke Bank Pelaksana, KPPN juga akan mengirimkan SP2D ke Biro Keuangan BNPB (untuk ditatausahakan didalam pembukuan BP dan unit SAK). Selanjutnya Biro Keuangan menyampaikan fotokopi SP2D kepada PPK Pusat sebagai pihak penerbit SPP-LS untuk bukti bahwa perintah pembayaran seperti yang diminta BNPB sudah dijalankan. g) Atas dasar SP2D yang diterima, Bank Pelaksana akan mentransfer sejumlah dana langsung ke rekening masing-masing POKMAS yang akan digunakan sesuai peruntukannya. Dengan efektifnya dana di rekening POKMAS, maka pelaksanaan kegiatan di lapangan oleh masyarakat dapat mulai dilaksanakan. h) POKMAS sebagai pihak penerima bantuan sekaligus penanggungjawab pelaksanaan pembangunan rumah masing-masing anggota POKMAS, secara periodik harus membuat dan memberikan laporan progres pelaksanaan dan penggunaan dana bantuan kepada PJOK/PPK Daerah. i) Berdasarkan perencanaan dan kemajuan (progress) pelaksanaan pada huruf h) di atas, PJOK/PPK Daerah dapat menyusun kegiatan pendampingan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6514, '3) Arsip data komputer (ADK) SPM-LS termasuk di dalamnya memuat daftar nomor rekening. e) KPPN Jakarta I akan menerbitkan Surat Perintah Pencairan Dana (SP2D) yang ditujukan ke Bank Pelaksana dimana BP membuka rekening yang berisi perintah untuk mencairkan sejumlah dana ke rekening masing-masing POKMAS. f) Pada saat yang bersamaan dengan penerbitan SP2D ke Bank Pelaksana, KPPN juga akan mengirimkan SP2D ke Biro Keuangan BNPB (untuk ditatausahakan didalam pembukuan BP dan unit SAK). Selanjutnya Biro Keuangan menyampaikan fotokopi SP2D kepada PPK Pusat sebagai pihak penerbit SPP-LS untuk bukti bahwa perintah pembayaran seperti yang diminta BNPB sudah dijalankan. g) Atas dasar SP2D yang diterima, Bank Pelaksana akan mentransfer sejumlah dana langsung ke rekening masing-masing POKMAS yang akan digunakan sesuai peruntukannya. Dengan efektifnya dana di rekening POKMAS, maka pelaksanaan kegiatan di lapangan oleh masyarakat dapat mulai dilaksanakan. h) POKMAS sebagai pihak penerima bantuan sekaligus penanggungjawab pelaksanaan pembangunan rumah masing-masing anggota POKMAS, secara periodik harus membuat dan memberikan laporan progres pelaksanaan dan penggunaan dana bantuan kepada PJOK/PPK Daerah. i) Berdasarkan perencanaan dan kemajuan (progress) pelaksanaan pada huruf h) di atas, PJOK/PPK Daerah dapat menyusun kegiatan pendampingan.', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6515, 'perka-14-2011', 46, 'lain', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN (lanjutan 2)', NULL, 27, 'j) Dana yang tersedia pada rekening POKMAS (termasuk jasa giro) dipergunakan sesuai rencana dan arahan dari fasilitator teknis di bawah supervisi Tim Pengendali Kegiatan (TPK) dan Tim Pengendali Masyarakat (TPM) yang dibentuk oleh pemerintah daerah.
2. Non Bantuan Langsung Masyarakat KPPN Jakarta I mencairkan dana rehabilitasi dan rekonstruksi (Non-Bantuan Langsung Masyarakat) kepada BP BNPB dengan mekanisme seperti terdapat pada gambar 2 berikut ini :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6515, 'j) Dana yang tersedia pada rekening POKMAS (termasuk jasa giro) dipergunakan sesuai rencana dan arahan dari fasilitator teknis di bawah supervisi Tim Pengendali Kegiatan (TPK) dan Tim Pengendali Masyarakat (TPM) yang dibentuk oleh pemerintah daerah.
2. Non Bantuan Langsung Masyarakat KPPN Jakarta I mencairkan dana rehabilitasi dan rekonstruksi (Non-Bantuan Langsung Masyarakat) kepada BP BNPB dengan mekanisme seperti terdapat pada gambar 2 berikut ini :', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN (lanjutan 2)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6516, 'perka-14-2011', 47, 'lain', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', NULL, 28, 'Gambar 2 Mekanisme pencairan dana Non BLM Sumber: Peraturan Dirjen Perbendaharaan Nomor Per-63/Pb/2011 Tanggal 29 September 2011 Tentang Tata Cara Pembayaran Dana Rehabilitasi dan Rekonstruksi Pascabencana Tahun Anggaran 2011.
Pencairan dana Non BLM diuraikan sebagai berikut :
a. PPK Pusat mengajukan SPP-LS kepada Pejabat Penanda Tangan SPM untuk pembayaran Non-BLM dengan dilampiri:
1) Surat keputusan penetapan alokasi yang ditetapkan oleh Kepala BNPB.
2) MoU antara BNPB dan Pemerintah Provinsi/Kabupaten/Kota 3) Daftar nominatif BPP yang memuat jumlah dana dan nomor rekening Bank masing-masing BPP Daerah (Formulir 11).
4) Berita acara pembayaran Non BLM (Formulir 12).
5) Kuitansi dari PPK Daerah disetujui oleh PPK Pusat (Formulir 13).
6) Fotokopi Rekening Koran BPP.
7) Surat Pernyataan Tanggung Jawab Belanja (SPTB) (Formulir 10).
b. Penyampaian SPM-LS kepada KPPN Jakarta I dengan dilampiri:
1) Surat keputusan penetapan alokasi yang ditetapkan oleh Kepala BNPB.
2) Surat Pernyataan Tanggung Jawab Belanja (SPTB) (Formulir 10).
3) Daftar nominatif BPP yang memuat jumlah dana dan nomor rekening Bank masing-masing BPP Daerah (Formulir 11).
4) Arsip data komputer (ADK) SPM-LS.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6516, 'Gambar 2 Mekanisme pencairan dana Non BLM Sumber: Peraturan Dirjen Perbendaharaan Nomor Per-63/Pb/2011 Tanggal 29 September 2011 Tentang Tata Cara Pembayaran Dana Rehabilitasi dan Rekonstruksi Pascabencana Tahun Anggaran 2011.
Pencairan dana Non BLM diuraikan sebagai berikut :
a. PPK Pusat mengajukan SPP-LS kepada Pejabat Penanda Tangan SPM untuk pembayaran Non-BLM dengan dilampiri:
1) Surat keputusan penetapan alokasi yang ditetapkan oleh Kepala BNPB.
2) MoU antara BNPB dan Pemerintah Provinsi/Kabupaten/Kota 3) Daftar nominatif BPP yang memuat jumlah dana dan nomor rekening Bank masing-masing BPP Daerah (Formulir 11).
4) Berita acara pembayaran Non BLM (Formulir 12).
5) Kuitansi dari PPK Daerah disetujui oleh PPK Pusat (Formulir 13).
6) Fotokopi Rekening Koran BPP.
7) Surat Pernyataan Tanggung Jawab Belanja (SPTB) (Formulir 10).
b. Penyampaian SPM-LS kepada KPPN Jakarta I dengan dilampiri:
1) Surat keputusan penetapan alokasi yang ditetapkan oleh Kepala BNPB.
2) Surat Pernyataan Tanggung Jawab Belanja (SPTB) (Formulir 10).
3) Daftar nominatif BPP yang memuat jumlah dana dan nomor rekening Bank masing-masing BPP Daerah (Formulir 11).
4) Arsip data komputer (ADK) SPM-LS.', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6517, 'perka-14-2011', 48, 'lain', 'BAB III TATACARA PENGAJUAN, PENCAIRAN DAN PENATAUSAHAAN', NULL, 29, 'c. KPPN Jakarta I akan menerbitkan Surat Perintah Pencairan Dana (SP2D) yang ditujukan kepada Rekening BP BNPB.
d. Mekanisme pencairan dana ke daerah tahap I.
PPK Daerah mengajukan surat permintaan untuk dana Non-BLM Tahap I kepada PPK Pusat (Formulir 14) dengan dilampiri :
1) Berita acara pembayaran Non BLM (Formulir 12).
2) Rencana penggunaaan dana Tahap I (Formulir 15) 3) Kuitansi dari PPK Daerah disetujui oleh PPK Pusat (Formulir 13).
4) Fotokopi Rekening Koran BPP.
Pembayaran seperti ketentuan huruf d di atas, dilaksanakan setelah dilakukan verifikasi terhadap dokumen permintaan yang diajukan oleh PPK Daerah ke PPK Pusat.
e. Mekanisme pencairan dana ke daerah tahap II PPK Daerah mengajukan Permintaan Pembayaran dana Non BLM Tahap II kepada PPK Pusat (Formulir 16) dengan dilampiri:
1) Daftar rincian penggunaan Tahap I yang memuat belanja kontraktual dan swakelola (Formulir 17).
2) Resume kontrak setiap rekanan/pihak ketiga (Formulir 18).
3) Daftar nominatif rekanan/pihak ketiga (Formulir 19).
4) Berita acara pembayaran Non BLM (Formulir 20).
5) Kuitansi dari BPP yang ditandatangani oleh PPK Daerah (Formulir 13).
6) Kemajuan fisik dan keuangan (Formulir 21) 7) Laporan pertanggungjawaban keuangan (Formulir 22 dan Formulir 23).
8) Sisa dana tahap I dengan dilampiri rekening Koran BPP.
Pembayaran seperti ketentuan di atas, dilaksanakan setelah dilakukan verifikasi terhadap dokumen permintaan yang diajukan oleh PPK Daerah oleh PPK Pusat.');
