INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6546, 'produksi pertanian (pupuk, bibit, obat-obatan dan alat pertanian), pengadaan ternak, psikososial, psiko-edukasi, penyuluhan/konseling/ sosialisasi, pelatihan, penelitian dan lain-lainnya yang dapat dilaksanakan secara kontraktual maupun swakelola.
b. Pelaksanaan Kegiatan Konstruksi dan Non Konstruksi Kegiatan konstruksi dan non konstruksi dilaksanakan berdasarkan Penilaian Kebutuhan Pascabencana yang terdiri dari sektor dan sub sektor sebagai berikut:
Sektor Sub Sektor Permukiman • Perumahan
• Prasaranaa lingkungan permukiman Infrastruktur • Transportasi: (darat, air, udara)
• Sumber Daya Air (SDA)
• Energi
• Pos dan telekomunikasi
• Air bersih dan sanitasi
• Infrastruktur pertanian Ekonomi • Pertanian Produktif • Perikanan
• Perkebunan
