INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6581, 'perka-14-2011', 112, 'lampiran', 'LAMPIRAN 2 : FORMULIR PENGAJUAN DAN PEMBAYARAN BLM', NULL, 62, 'Lampiran 2 Formulir Pengajuan dan Pembayaran BLM');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6581, 'Lampiran 2 Formulir Pengajuan dan Pembayaran BLM', 'LAMPIRAN 2 : FORMULIR PENGAJUAN DAN PEMBAYARAN BLM', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6582, 'perka-14-2011', 113, 'lampiran', 'LAMPIRAN 2 : FORMULIR PENGAJUAN DAN PEMBAYARAN BLM', NULL, 63, 'Formulir 01 Surat Perjanjian Pengelolaan Bantuan (SPPB) SURAT PERJANJIAN PENGELOLAAN BANTUAN (SPPB) TENTANG PENYALURAN BANTUAN LANGSUNG MASYARAKAT DANA BANTUAN SOSIAL BERPOLA HIBAH KEGIATAN REHABILITASI DAN REKONSTRUKSI PERUMAHAN PASCABENCANA DI…………..KABUPATEN/KOTA………………..PROVINSI…………….
Pada hari ini……….tanggal………..bulan…………..tahun…………., kami yang bertanda tangan dibawah ini:
1. Nama : …………………………………… Alamat : …………………………………………….
Jabatan : sebagai Pejabat Penanggungjawab Operasional Kegiatan (PJOK) Kabupaten/Kota………….. Provinsi ………… sesuai dengan surat keputusan Bupati/Walikota………. Nomor : …………….. Tanggal…………., selanjutnya disebut PIHAK PERTAMA
2. Nama : …………………………………….
Alamat : ……………………………………………..
Jabatan : Ketua Kelompok Masyarakat (POKMAS) …………… berdasarkan keputusan Bupati/Walikota No. ….. Tanggal ….. dalam hal ini bertindak untuk dan atas nama POKMAS …………… Desa ……………, Kecamatan ………………….., Kabupaten …………………, selanjutnya disebut PIHAK KEDUA Kedua belah pihak disebut PARA PIHAK sepakat mengadakan perjanjian pemberian bantuan langsung perumahan masyarakat yang diatur dalam pasal-pasal sebagai berikut:
Pasal 1 Penyaluran Dana
1. PIHAK PERTAMA akan menyalurkan bantuan langsung dari pemerintah untuk melaksanakan rehabilitasi perumahan yang rusak akibat bencana …………… Tanggal …………. Kepada masyarakat langsung kepada rekening POKMAS.');
