INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6608, 'perka-14-2011', 139, 'lampiran', 'LAMPIRAN 3 : FORMULIR PENGAJUAN DAN PEMBAYARAN NON BLM', NULL, 82, 'Formulir 18 Resume Kontrak Rekanan/Pihak Ketiga RESUME KONTRAK Untuk Kegiatan yang dananya berasal dari Rupiah murni
1. Nomor dan tanggal DIPA : (1)
2. Kode Kegiatan/sub Kegiatan/MAK : (2)
3. Nomor dan tanggal SPK/kontrak : (3)
4. Nama Kontraktor/ perusahaan : (4)
5. Alamat Kontraktor : (5)
6. Nilai SPK/kontrak : (6)
7. Uraian dan volume pekerjaan : (7)
8. Cara Pembayaran nya : (8)
9. Jangka waktu pelaksanaan : (9)
10. Tanggal Penyelesaian Pekerjaan : (10)
11. Jangka Waktu Pemeliharaan : (11)
12. Ketentuan sanksi : (12) Catatan :
Apabila terjadi addendum Kontrak Tempat, tanggal….(13)…… data kontrak agar disesuaikan PPK dengan perubahannya (tanda tangan ) (14) (nama jelas) NIP. …… NOMOR URAIAN ISIAN
(1) Diisi tanggal dan nomor DIPA
(2) Diisi kode kegiatan (4 digit), kode sub kegiatan (4 digit), dan kode MAK (6 digit) sesuai DIPA pada isian (1)
(3) Diisi nomor tanggal SPK/ kontrak berkenaan
(4) Diisi nama rekenan dan nama perusahaan sesuai SPK/ kontrak
(5) Diisi alamat perusahaan rekenan yang bersangkutan dilihat dari NPWP rekanan
(6) Diisi nilai SPK/ Kontrakyang ciperjanjikan dengan angka dan huruf
(7) Diisi uraian pekerjaan dan volume pekerjaan sesuai SPK/ Kontrak
(8) Diisi cara/ tahap pembayaran kepada rekenan (termin,monthly certificate , dII) seperti no rekening dan nama bank
(9) Diisi jumlah hari peryelesaian pekerjaan
(10) Diisi tanggal penyelesaian pekerjaan
(11) Diisi jumlah hari masa pemeliharaan
(12) Diisi prosentase pinalti denda keterlambatan minimal dana maksimal');
