INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6612, 'perka-14-2011', 143, 'lampiran', 'LAMPIRAN 3 : FORMULIR PENGAJUAN DAN PEMBAYARAN NON BLM', NULL, 85, 'Keterangan:
1. No urut
2. Nama kegiatan/pekerjaan
3. Pagu dana
4. Lokasi kegiatan/pekerjaan
5. Volume kegiatan/pekerjaan
6. Nilai Prosentase
7. Nama rekanan/kontraktor
8. No. tanggal perjanjian kontrak atau pelaksana kegiatan
9. Nilai kontrak atau kegiatan
10. Nilai sisa pagu atau sisa tender = (3)-(9)
11. Nilai realisasi pembayaran kontrak atau kegiatan secara kumulatif s.d tanggal pelaporan dalam Rp.
12. Jumlah pembayaran nilai kontrak secara kumulatif s.d tanggal pelaporan dalam % = (10:8x100%)
13. Realisasi fisik dalam %
14. Realisasi fisik tertimbang
15. Sisa nilai kontrak atau kegiatan yang belum dibayarkan secara kumulatif s.d tanggal pelaporan = (9)-(11)
16. Tambahkan Informasi lainnya yang relevan');
