INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6615, 'perka-14-2011', 146, 'lain', 'I. BUKU KAS UMUM BENDAHARA PENGELUARAN PEMBANTU', NULL, 87, 'Bagian 1 : Halaman Muka BUKU KAS UMUM Kementrian/Lembaga : (…..)…………….. (1) Unit Organisasi : (…..)…………….. (2) Provinsi/Kabupaten/Kota : (…..)…………….. (3) Satuan Kerja : (…..)…………….. (4) Tanggal/No SK/Pengangkatan: (…..)…………….. (5)
1. BPP : ……, …………….. (6)
2. Pejabat Pembuat Komitmen: …... .…………….. (7) Mengetahui ….. …………….. (8) Pejabat Pembuat Komitmen, Bendahara Pengeluaran Pembantu, (9)………………………. (10)……………………….
NIP……………………… NIP………………………..
Petunjuk pengisian :
(1) : diisi kode dan nama Kementrian (8) : diisi tempat dan tanggal, bulan dan serta
(2) : diisi kode dan nama unit organisasi tahun buku kas umum dibuat
(3) : diisi kode dan nama provinsi/kabupaten/kota (9) : diisi tempat, dan tanggal, bulan serta tahun
(4) : diisi kode dan nama satuan kerja buku kas umum dibuat
(5) : diisi tanggal, bulan dan tahun serta nomor SK (10): diisi nama lengkap dan NIP pejabat pembuat pengangkatan BPP komitmen yang ditunjuk
(6) : diisi tanggal, bulan dan tahun serta nomor SK (11): diisi nama lengkap dan NIP bendahara pengangkatan pejabat pembuat komitmen pengeluaran pembantu yang ditunjuk
(7) : diisi tahun anggaran Bagian 2 : Halaman Isi Buku Kas Umum Tanggal Nomor Bukti Uraian Debet Kredit Saldo');
