(7) : diisi tahun anggaran Bagian 2 : Halaman Isi Buku Kas Umum Tanggal Nomor Bukti Uraian Debet Kredit Saldo', 'I. BUKU KAS UMUM BENDAHARA PENGELUARAN PEMBANTU', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6616, 'perka-14-2011', 147, 'lain', 'I. BUKU KAS UMUM BENDAHARA PENGELUARAN PEMBANTU (lanjutan 1)', NULL, 87, '(1) (2) (3) (4) (5) (6) Petunjuk Pengisian Halaman Isi Buku Kas Umum Kolom (1) : Diisi tanggal pembukuan (format: bulan-tanggal) Kolom (2) : Diisi nomor bukti bendahara Kolom (3) : Diisi uraian transaksi penerimaan /pengeluaran Kolom (4) : Diisi jumlah penerimaan yang tercantum dalam dokumen sumber Kolom (5) : Diisi jumlah setoran yang tercantum dalam dokumen sumber Kolom (6) : Diisi jumlah saldo setelah ditambah/dikurangi jumlah penerimaan/setoran yang tercantum dalam dokumen sumber');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6616, '(1) (2) (3) (4) (5) (6) Petunjuk Pengisian Halaman Isi Buku Kas Umum Kolom (1) : Diisi tanggal pembukuan (format: bulan-tanggal) Kolom (2) : Diisi nomor bukti bendahara Kolom (3) : Diisi uraian transaksi penerimaan /pengeluaran Kolom (4) : Diisi jumlah penerimaan yang tercantum dalam dokumen sumber Kolom (5) : Diisi jumlah setoran yang tercantum dalam dokumen sumber Kolom (6) : Diisi jumlah saldo setelah ditambah/dikurangi jumlah penerimaan/setoran yang tercantum dalam dokumen sumber', 'I. BUKU KAS UMUM BENDAHARA PENGELUARAN PEMBANTU (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
