INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6666, 'Propinsi (2) digit 10 Diisi dengan kode apakah satkernya Kantor Pusat (KP), Kantor Daerah (KD), dekonsentrasi (DK), Tugas Perbantuan (TP) atau Desentralisasi (DS) sebanyak (2) dua Digit 11 Diisi dengan nama/jabatan wajib setor/wajib bayar.
12 Diisi dengan alamat jelas wajib setor/wajib bayar 13 Diisi dengan kode mata anggaran pengembalian belanja (6) enam digit disertai dengan nilai rupiah untuk masing – masing mata anggaran. Dan bisa menggunakan lebih dari 1 mata anggaran pengembalian belanja.
14 Diisi dengan jumlah rupiah setoran pengembalian.
15 Diisi dengan jumlah rupiah yang dibayarkan dengan huruf.
16 Diisi keperluan pembayaran 17 Diisi sesuai dengan tempat dan tanggal dibuatnya SSPB.
