INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6716, 'perka-14-2011', 247, 'lampiran', 'LAMPIRAN BERITA ACARA', NULL, 134, 'SERAH TERIMA PEMINDAHTANGANAN/HIBAH BARANG MILIK NEGARA HASIL KEGIATAN REHABILITASI DAN REKONSTRUKSI PASCABENCANA PROVINSI/KABUPATEN/KOTA…….
TAHUN ANGGARAN…… NOMOR: ……………………………… No Nama Jenis/ Tanggal Volume/ Nilai Nilai Setelah Lokasi BMN Merk/Type Perolehan Kuantitas Perolehan/ Kapitalisasi Kontrak (Rp) (Rp) 1 2 3 4 5 6 7 8 Jumlah ………..
PIHAK KEDUA PIHAK PERTAMA Gubernur/Bupati/Walikota ……….. Kuasa Pengguna Anggaran Nama ……………. Nama …………….
NIP ……………… NIP. ……………… Petunjuk pengisian:
1. Diisi dengan nomor urut BMN
2. Diisi dengan nama BMN seperti: a) rehabilitasi/rekonstruksi jalan, jaringan irigasi, bangunan sekolah dst (yang memenuhi syarat kapitalisasi a.I meningkatkan manfaat ekonomi dikelompokkan sebagai Aset Tetap dalam Renovasi BMN). b) Kendaraan, computer, meja dst yang memenuhi kriteria Aset Tetap
3. Diisi dengan Jenis/Merk/Type BMN
4. Diisi dengan tanggal perolehan BMN (Tanggal BAST Pekerjaan Akhir/FHO)
5. Diisi dengan volume/kuantitas BMN seperti: a) panjang, lebar dan tebal jalan yang direhabilitasi/direkonstruksi, dan seterusnya sesuai dengan jenisnya dengan menggunakan satuan yang baku; b) jumlah computer, jumlah meja, jumlah kendaraan dan seterusnya dengan menggunakan satuan yang baku;
6. Diisi dengan nilai perolehan/ kontrak rehabilitasi dan rekonstruksi
7. Diisi dengan nilai perolehan/kontrak rehabilitasi dan rekonstruksi ditambah dengan seluruh biaya yang dikeluarkan untuk memperoleh BMN tsb.
Catatan:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6716, 'SERAH TERIMA PEMINDAHTANGANAN/HIBAH BARANG MILIK NEGARA HASIL KEGIATAN REHABILITASI DAN REKONSTRUKSI PASCABENCANA PROVINSI/KABUPATEN/KOTA…….
TAHUN ANGGARAN…… NOMOR: ……………………………… No Nama Jenis/ Tanggal Volume/ Nilai Nilai Setelah Lokasi BMN Merk/Type Perolehan Kuantitas Perolehan/ Kapitalisasi Kontrak (Rp) (Rp) 1 2 3 4 5 6 7 8 Jumlah ………..
PIHAK KEDUA PIHAK PERTAMA Gubernur/Bupati/Walikota ……….. Kuasa Pengguna Anggaran Nama ……………. Nama …………….
NIP ……………… NIP. ……………… Petunjuk pengisian:
1. Diisi dengan nomor urut BMN
2. Diisi dengan nama BMN seperti: a) rehabilitasi/rekonstruksi jalan, jaringan irigasi, bangunan sekolah dst (yang memenuhi syarat kapitalisasi a.I meningkatkan manfaat ekonomi dikelompokkan sebagai Aset Tetap dalam Renovasi BMN). b) Kendaraan, computer, meja dst yang memenuhi kriteria Aset Tetap
3. Diisi dengan Jenis/Merk/Type BMN
4. Diisi dengan tanggal perolehan BMN (Tanggal BAST Pekerjaan Akhir/FHO)
5. Diisi dengan volume/kuantitas BMN seperti: a) panjang, lebar dan tebal jalan yang direhabilitasi/direkonstruksi, dan seterusnya sesuai dengan jenisnya dengan menggunakan satuan yang baku; b) jumlah computer, jumlah meja, jumlah kendaraan dan seterusnya dengan menggunakan satuan yang baku;
6. Diisi dengan nilai perolehan/ kontrak rehabilitasi dan rekonstruksi
7. Diisi dengan nilai perolehan/kontrak rehabilitasi dan rekonstruksi ditambah dengan seluruh biaya yang dikeluarkan untuk memperoleh BMN tsb.
Catatan:', 'LAMPIRAN BERITA ACARA', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2011 tentang Petunjuk Teknis Tatacara Pengajuan dan Pengelolaan Dana Bantuan Sosial Berpola Hibah Kegiatan Rehabilitasi dan Rekonstruksi Pasca Bencana Tahun 2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6717, 'perka-14-2011', 248, 'lampiran', 'LAMPIRAN BERITA ACARA (lanjutan 1)', NULL, 134, 'Total nilai BMN berupa konstruksi adalah seluruh biaya yang dikeluarkan dalam rangka perolehan BMN yaitu sejak dari perencanaan, konstruksi, pengawasan dan biaya-biaya umum lainnya;
Total nilai BMN yang berasal dari pembelian adalah seluruh biaya yang dikeluarkan dalam rangka perolehan BMN sampai siap digunakan yaitu harga beli BMN, termasuk biaya perjalanan dinas, ongkos angkut, biaya instalasi/uji coba dan biaya konsultasi, surat-surat bukti kepemilikan dll.
BMN yang dibangun secara swakelola meliputi biaya langsung untuk tenaga kerja, bahan baku, dan biaya tidak langsung termasuk biaya perencanaan dan pengawasan, perlengkapan, tenaga listrik, sewa peralatan dan semua biaya lainnya yang terjadi berkenaan dengan BMN tersebut.
Apabila kontrak perencanaan, pengawasan dan biaya umum lainnya meliputi lebih dari 1 (satu) BMN, maka nilainya dikapitalisasi secara proporsional ke seluruh BMN yang dihasilkan.
8. Diisi dengan lokasi penempatan Barang Milik Negara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6717, 'Total nilai BMN berupa konstruksi adalah seluruh biaya yang dikeluarkan dalam rangka perolehan BMN yaitu sejak dari perencanaan, konstruksi, pengawasan dan biaya-biaya umum lainnya;
Total nilai BMN yang berasal dari pembelian adalah seluruh biaya yang dikeluarkan dalam rangka perolehan BMN sampai siap digunakan yaitu harga beli BMN, termasuk biaya perjalanan dinas, ongkos angkut, biaya instalasi/uji coba dan biaya konsultasi, surat-surat bukti kepemilikan dll.
