INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6730, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2014 tentang Penanganan, Perlindungan, dan Partisipasi Penyandang Disabilitas Dalam Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2014 tentang Penanganan, Perlindungan, dan Partisipasi Penyandang Disabilitas Dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6731, 'perka-14-2014', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa berdasarkan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, negara menjamin setiap orang bebas dari perlakuan diskriminatif atas dasar apapun dan berhak mendapatkan perlindungan dari perlakuan yang bersifat diskriminatif;
b. bahwa diskriminasi terhadap penyandang disabilitas merupakan pelanggaran terhadap martabat dan nilai kemanusiaan, oleh karena itu perlu menjamin perlindungan dan pemenuhan hak serta kemudahan akses dan partisipasi penyandang disabilitas dalam segala aspek penanggulangan bencana;
c. bahwa berbagai peraturan perundang-undangan yang mengatur perlindungan terhadap penyandang disabilitas telah dibentuk namun peraturan perundang-undangan terkait perlindungan penyandang disabilitas dalam penanggulangan bencana belum ada;
d. bahwa berdasarkan pertimbangan sebagaimana yang dimaksud dalam huruf a, huruf b dan huruf c, perlu 2014, No.1605 2 menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Penanganan, Perlindungan dan Partisipasi Penyandang Disabilitas dalam Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6731, 'a. bahwa berdasarkan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, negara menjamin setiap orang bebas dari perlakuan diskriminatif atas dasar apapun dan berhak mendapatkan perlindungan dari perlakuan yang bersifat diskriminatif;
b. bahwa diskriminasi terhadap penyandang disabilitas merupakan pelanggaran terhadap martabat dan nilai kemanusiaan, oleh karena itu perlu menjamin perlindungan dan pemenuhan hak serta kemudahan akses dan partisipasi penyandang disabilitas dalam segala aspek penanggulangan bencana;
c. bahwa berbagai peraturan perundang-undangan yang mengatur perlindungan terhadap penyandang disabilitas telah dibentuk namun peraturan perundang-undangan terkait perlindungan penyandang disabilitas dalam penanggulangan bencana belum ada;
d. bahwa berdasarkan pertimbangan sebagaimana yang dimaksud dalam huruf a, huruf b dan huruf c, perlu 2014, No.1605 2 menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Penanganan, Perlindungan dan Partisipasi Penyandang Disabilitas dalam Penanggulangan Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2014 tentang Penanganan, Perlindungan, dan Partisipasi Penyandang Disabilitas Dalam Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6732, 'perka-14-2014', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 39 Tahun 1999 tentang Hak Asasi Manusia (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 165, Tambahan Lembaran Negara Republik Indonesia Nomor 3886);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Undang-Undang Nomor 11 Tahun 2009 tentang Kesejahteraan Sosial (Lembaran Negara Republik Indonesia Tahun 2009 Nomor 12, Tambahan Lembaran Negara Republik Indonesia Nomor 4967);
4. Undang-Undang Nomor 19 Tahun 2011 tentang Pengesahan Konvensi Mengenai Hak-Hak Tentang Penyandang Disabilitas (Lembaran Negara Republik Indonesia Tahun 2011 Nomor 107, Tambahan Lembaran Negara Republik Indonesia Nomor 5251);
5. Peraturan Pemerintah Nomor 72 Tahun 1991 tentang Pendidikan Luar Biasa (Lembaran Negara Republik Indonesia Tahun 1991 Nomor 94, Tambahan Lembaran Negara Republik Indonesia Nomor 3460);
6. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
7. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;');
