INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6733, 'perka-14-2014', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENANGANAN, PERLINDUNGAN DAN PARTISIPASI PENYANDANG DISABILITAS DALAM PENANGGULANGAN BENCANA.
