INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6763, 'perka-15-2010', 5, 'pasal', 'Pasal 2', NULL, 4, 'Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan sebagaimana dimaksud dalam Pasal 1, merupakan acuan bagi Pelaksana Pemberi/Pengelola Bantuan Kecacatan.');
