INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6766, 'perka-15-2010', 8, 'lain', 'Penutup', NULL, 5, 'Ditetapkan di Jakarta pada tanggal 14 September 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA DR. SYAMSUL MAARIF, M.Si');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6766, 'Ditetapkan di Jakarta pada tanggal 14 September 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA DR. SYAMSUL MAARIF, M.Si', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2010 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6767, 'perka-15-2010', 9, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 15 TAHUN 2010 TANGGAL : 14 SEPTEMBER 2010 BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan wilayah yang memiliki potensi serta intensitas kejadian bencana cukup tinggi baik bencana alam, non alam maupun bencana sosial. Akibat bencana yang terjadi telah menimbulkan korban jiwa, kecacatan dan kerugian harta benda serta merusak sarana dan prasarana publik yang ada, terjadinya pengungsian, ketidaknormalan kehidupan dan penghidupan masyarakat serta terganggunya pelaksanaan pembangunan.
Ketika terjadi bencana, masyarakat yang menjadi korban sangat membutuhkan bantuan dari pihak luar. Namun terkadang keterlibatan pihak luar di dalam memberikan bantuan kepada masyarakat korban bencana, dapat menimbulkan masalah baru berupa ketidaksesuaian bantuan yang diberikan dengan kebutuhan masyarakat ataupun kecemburuan sosial diantara orang-orang yang merasa diperlakukan secara tidak adil. Persoalan lainnya yang sering terjadi yaitu ketika suatu bencana terjadi, banyak pihak yang terlibat memberikan bantuan tidak terkoordinir dengan baik sehingga menimbulkan kekacauan di lapangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6767, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 15 TAHUN 2010 TANGGAL : 14 SEPTEMBER 2010 BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan wilayah yang memiliki potensi serta intensitas kejadian bencana cukup tinggi baik bencana alam, non alam maupun bencana sosial. Akibat bencana yang terjadi telah menimbulkan korban jiwa, kecacatan dan kerugian harta benda serta merusak sarana dan prasarana publik yang ada, terjadinya pengungsian, ketidaknormalan kehidupan dan penghidupan masyarakat serta terganggunya pelaksanaan pembangunan.
Ketika terjadi bencana, masyarakat yang menjadi korban sangat membutuhkan bantuan dari pihak luar. Namun terkadang keterlibatan pihak luar di dalam memberikan bantuan kepada masyarakat korban bencana, dapat menimbulkan masalah baru berupa ketidaksesuaian bantuan yang diberikan dengan kebutuhan masyarakat ataupun kecemburuan sosial diantara orang-orang yang merasa diperlakukan secara tidak adil. Persoalan lainnya yang sering terjadi yaitu ketika suatu bencana terjadi, banyak pihak yang terlibat memberikan bantuan tidak terkoordinir dengan baik sehingga menimbulkan kekacauan di lapangan.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2010 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6768, 'perka-15-2010', 10, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'Peraturan Pemerintah Republik Indonesa Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana sebagai penjabaran dari Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana telah memberikan rambu-rambu bahwa bantuan bagi korban bencana antara lain mencakup santunan kecacatan (pasal 24 ayat 2, butir b). Santunan kecacatan diberikan kepada korban bencana yang mengalami kecacatan mental dan/atau fisik (pasal 26 ayat 1).
Untuk mengatur lebih lanjut mengenai bagaimana bantuan santunan kecacatan diberikan, dibutuhkan acuan yang jelas bagi pelaksana pemberi bantuan berupa Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan.
B. Maksud dan Tujuan
1. Maksud Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan dimaksudkan sebagai lampiran Peraturan Kepala Badan Nasional Penanggulangan Bencana (BNPB) yang mengatur pelaksanaan pemberian dan besaran bantuan santunan kecacatan bagi korban bencana sebagai penjabaran pasal 26 ayat (3) Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
2. Tujuan Tujuan Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan adalah memberikan acuan bagi pelaksana pemberi bantuan yang berasal dari lembaga pemerintah, pemerintah daerah, dan nonpemerintah pada lingkup daerah, nasional maupun internasional untuk :
a. Menentukan korban bencana yang memenuhi kriteria penerima bantuan santunan kecacatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6768, 'Peraturan Pemerintah Republik Indonesa Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana sebagai penjabaran dari Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana telah memberikan rambu-rambu bahwa bantuan bagi korban bencana antara lain mencakup santunan kecacatan (pasal 24 ayat 2, butir b). Santunan kecacatan diberikan kepada korban bencana yang mengalami kecacatan mental dan/atau fisik (pasal 26 ayat 1).
Untuk mengatur lebih lanjut mengenai bagaimana bantuan santunan kecacatan diberikan, dibutuhkan acuan yang jelas bagi pelaksana pemberi bantuan berupa Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan.
B. Maksud dan Tujuan
1. Maksud Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan dimaksudkan sebagai lampiran Peraturan Kepala Badan Nasional Penanggulangan Bencana (BNPB) yang mengatur pelaksanaan pemberian dan besaran bantuan santunan kecacatan bagi korban bencana sebagai penjabaran pasal 26 ayat (3) Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
2. Tujuan Tujuan Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan adalah memberikan acuan bagi pelaksana pemberi bantuan yang berasal dari lembaga pemerintah, pemerintah daerah, dan nonpemerintah pada lingkup daerah, nasional maupun internasional untuk :
a. Menentukan korban bencana yang memenuhi kriteria penerima bantuan santunan kecacatan.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2010 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6769, 'perka-15-2010', 11, 'lampiran', 'Lampiran hal. 7', NULL, 7, 'b. Menentukan kategori santunan bagi korban bencana yang mengalami kecacatan.
c. Memberikan santunan yang sesuai prosedur standar yang ditentukan di dalam panduan ini.
C. Landasan Hukum
1. Undang-Undang Dasar Republik Indonesia Tahun 1945;
2. Undang-Undang RI Nomor 4 Tahun 1997 tentang Penyandang Cacat;
3. Undang-Undang RI Nomor 39 Tahun 1999 tentang Hak Azasi Manusia;
4. Undang-Undang RI Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Noomor 4286);
5. Undang-Undang RI Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355)
6. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723).
7. Undang-undang Nomor 32 Tahun 2004 Tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6769, 'b. Menentukan kategori santunan bagi korban bencana yang mengalami kecacatan.
c. Memberikan santunan yang sesuai prosedur standar yang ditentukan di dalam panduan ini.
