INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6771, 'perka-15-2010', 13, 'lampiran', 'Lampiran hal. 9', NULL, 9, '1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam, faktor nonalam, maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis bagi manusia.
2. Bencana alam adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang ditimbulkan oleh alam, antara lain berupa gempa bumi, tsunami, gunung meletus, banjir, kekeringan, angin topan, dan tanah longsor.
3. Bencana nonalam adalah bencana yang diakibatkan oleh peristiwa atau rangkaian peristiwa nonalam, antara lain berupa gagal teknologi, gagal modernisasi, epidemi, dan wabah penyakit.
4. Bencana sosial adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang diakibatkan oleh manusia yang meliputi konflik sosial antar kelompok atau antarkomunitas masyarakat, dan teror.
5. Korban bencana adalah orang atau sekelompok orang yang menderita (secara fisik/mental) atau meninggal dunia akibat bencana.
6. Penyandang cacat korban bencana adalah seseorang atau sekelompok orang yang mempunyai kelainan fisik, dan/atau mental akibat bencana yang terjadi, sehingga tidak dapat melakukan kegiatan secara selayaknya.
7. Pelaksana pemberi bantuan adalah pihak yang memberikan santunan kecacatan, baik pemerintah, pemerintah daerah, maupun lembaga non pemerintah pada lingkup daerah, nasional maupun internasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6771, '1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam, faktor nonalam, maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis bagi manusia.
2. Bencana alam adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang ditimbulkan oleh alam, antara lain berupa gempa bumi, tsunami, gunung meletus, banjir, kekeringan, angin topan, dan tanah longsor.
3. Bencana nonalam adalah bencana yang diakibatkan oleh peristiwa atau rangkaian peristiwa nonalam, antara lain berupa gagal teknologi, gagal modernisasi, epidemi, dan wabah penyakit.
4. Bencana sosial adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang diakibatkan oleh manusia yang meliputi konflik sosial antar kelompok atau antarkomunitas masyarakat, dan teror.
5. Korban bencana adalah orang atau sekelompok orang yang menderita (secara fisik/mental) atau meninggal dunia akibat bencana.
6. Penyandang cacat korban bencana adalah seseorang atau sekelompok orang yang mempunyai kelainan fisik, dan/atau mental akibat bencana yang terjadi, sehingga tidak dapat melakukan kegiatan secara selayaknya.
7. Pelaksana pemberi bantuan adalah pihak yang memberikan santunan kecacatan, baik pemerintah, pemerintah daerah, maupun lembaga non pemerintah pada lingkup daerah, nasional maupun internasional.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2010 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6772, 'perka-15-2010', 14, 'lampiran', 'Lampiran hal. 9', NULL, 9, '8. Santunan kecacatan adalah bantuan yang diberikan oleh pelaksana pemberi bantuan berupa uang kepada korban bencana yang mengalami kecacatan.
E. Prinsip-prinsip
1. Penghargaan terhadap harkat dan martabat manusia, maksudnya bahwa santunan yang diberikan bertujuan untuk melindungi dan menghormati hak-hak azasi manusia, harkat dan martabat setiap warga negara.
2. Perlakuan adil, maksudnya bahwa santunan yang diberikan semata-mata atas dasar kebutuhan penyandang cacat korban bencana melalui kerangka kerja yang berlandaskan HAM, proporsionalitas, dan tidak mendiskriminasi.
3. Cepat dan tepat, maksudnya bahwa pemberian santunan harus dilaksanakan secara cepat dan tepat sesuai dengan tuntutan keadaan.
4. Transparansi dan akuntabilitas, maksudnya bahwa pemberian santunan dilakukan secara terbuka dan dapat dipertanggung jawabkan secara etik dan hukum.
5. Nondiskriminatif, maksudnya bahwa pemberian santunan tidak membedakan jenis kelamin, suku, agama, ras, dan aliran politik apapun.
6. Nonproletisi, maksudnya adalah bahwa dilarang menyebarkan agama atau keyakinan pada saat keadaan darurat bencana, terutama melalui pemberian bantuan dan pelayanan darurat bencana.
7. Kehati-hatian, maksudnya bahwa pemberian santunan harus cermat, teliti, aman, dan tertib sehingga sampai kepada sasaran.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6772, '8. Santunan kecacatan adalah bantuan yang diberikan oleh pelaksana pemberi bantuan berupa uang kepada korban bencana yang mengalami kecacatan.
E. Prinsip-prinsip
1. Penghargaan terhadap harkat dan martabat manusia, maksudnya bahwa santunan yang diberikan bertujuan untuk melindungi dan menghormati hak-hak azasi manusia, harkat dan martabat setiap warga negara.
2. Perlakuan adil, maksudnya bahwa santunan yang diberikan semata-mata atas dasar kebutuhan penyandang cacat korban bencana melalui kerangka kerja yang berlandaskan HAM, proporsionalitas, dan tidak mendiskriminasi.
3. Cepat dan tepat, maksudnya bahwa pemberian santunan harus dilaksanakan secara cepat dan tepat sesuai dengan tuntutan keadaan.
4. Transparansi dan akuntabilitas, maksudnya bahwa pemberian santunan dilakukan secara terbuka dan dapat dipertanggung jawabkan secara etik dan hukum.
5. Nondiskriminatif, maksudnya bahwa pemberian santunan tidak membedakan jenis kelamin, suku, agama, ras, dan aliran politik apapun.
6. Nonproletisi, maksudnya adalah bahwa dilarang menyebarkan agama atau keyakinan pada saat keadaan darurat bencana, terutama melalui pemberian bantuan dan pelayanan darurat bencana.
7. Kehati-hatian, maksudnya bahwa pemberian santunan harus cermat, teliti, aman, dan tertib sehingga sampai kepada sasaran.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2010 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6773, 'perka-15-2010', 15, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'F. Ruang Lingkup Pedoman pemberian dan besaran bantuan santunan kecacatan mengatur beberapa hal penting antara lain, kategori bantuan santunan kecacatan, kriteria kecacatan penerima bantuan, organisasi pelaksana dan koordinasi, mekanisme pemberian bantuan mulai persiapan dan pelaksanaan, serta ketentuan khusus, dan besaran bantuan santunan.
G. Sistematika Sistematika Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan mencakup:
BAB I Pendahuluan yang memuat tentang latar belakang, maksud dan tujuan, landasan hukum, pengertian, prinsip-prinsip, ruang lingkup, dan sistematika;
BAB II Kriteria sasaran, kategori dan besaran bantuan santunan kecacatan yang memuat tentang kriteria korban bencana, kriteria kecacatan korban bencana, kriteria penerima bantuan santunan kecacatan, kategori bantuan, dan besaran bantuan;
BAB III Organisasi pelaksana dan koordinasi yang memuat tentang organisasi pelaksana dan koordinasi;
BAB IV Mekanisme pemberian bantuan yang memuat tentang persiapan, pelaksanaan, dan ketentuan khusus;
BAB V Penutup.
BAB II Formatted: Font: Footlight MT Light, 12 pt KRITERIA SASARAN, KATEGORI DAN BESARAN BANTUAN SANTUNAN KECACATAN Formatted: Font: Footlight MT Light, 11.5 pt, A. Kriteria Sasaran English (U.S.)
1. Kriteria Korban Bencana
a. Seseorang yang mengalami kecacatan sebagai akibat langsung terjadinya bencana.
b. Seseorang yang mengalami kecacatan di pengungsian dan tempat lain sebagai akibat bencana pada masa darurat.
2. Kriteria Kecacatan Korban Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6773, 'F. Ruang Lingkup Pedoman pemberian dan besaran bantuan santunan kecacatan mengatur beberapa hal penting antara lain, kategori bantuan santunan kecacatan, kriteria kecacatan penerima bantuan, organisasi pelaksana dan koordinasi, mekanisme pemberian bantuan mulai persiapan dan pelaksanaan, serta ketentuan khusus, dan besaran bantuan santunan.
G. Sistematika Sistematika Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan mencakup:
BAB I Pendahuluan yang memuat tentang latar belakang, maksud dan tujuan, landasan hukum, pengertian, prinsip-prinsip, ruang lingkup, dan sistematika;
BAB II Kriteria sasaran, kategori dan besaran bantuan santunan kecacatan yang memuat tentang kriteria korban bencana, kriteria kecacatan korban bencana, kriteria penerima bantuan santunan kecacatan, kategori bantuan, dan besaran bantuan;
BAB III Organisasi pelaksana dan koordinasi yang memuat tentang organisasi pelaksana dan koordinasi;
BAB IV Mekanisme pemberian bantuan yang memuat tentang persiapan, pelaksanaan, dan ketentuan khusus;
BAB V Penutup.
BAB II Formatted: Font: Footlight MT Light, 12 pt KRITERIA SASARAN, KATEGORI DAN BESARAN BANTUAN SANTUNAN KECACATAN Formatted: Font: Footlight MT Light, 11.5 pt, A. Kriteria Sasaran English (U.S.)
1. Kriteria Korban Bencana
a. Seseorang yang mengalami kecacatan sebagai akibat langsung terjadinya bencana.
b. Seseorang yang mengalami kecacatan di pengungsian dan tempat lain sebagai akibat bencana pada masa darurat.
2. Kriteria Kecacatan Korban Bencana', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2010 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6774, 'perka-15-2010', 16, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'a. Cacat fisik; yaitu kecacatan secara fisik yang diakibatkan oleh bencana, baik bencana alam, nonalam maupun bencana sosial.
Kecacatan fisik dapat dikategorikan sebagai berikut :
1) Cacat Tubuh, yaitu keadaan cacat dimana korban bencana mengalami kerusakan bentuk tubuh atau hambatan pada tulang, otot, dan sendi dalam fungsinya yang normal. Ciri-cirinya antara lain : a) Kehilangan anggota tubuh seperti lengan, tangan dan kaki baik sebelah atau kedua-duanya. b) Kerusakan permukaan kulit akibat luka bakar derajat ketiga dan sekurang-kurangnya mengenai 20 % luas permukaan tubuh. c) Patah tulang.
2) Cacat netra, yaitu suatu keadaan cacat penglihatan sebagai akibat bencana, sehingga menjadi hambatan dalam melakukan kegiatan sehari-hari secara layak atau wajar.
Ciri-cirinya antara lain : a) Buta total, yaitu kedua belah mata tidak dapat melihat. b) Masih mempunyai sisa penglihatan atau kurang awas dengan cirinya tidak dapat menghitung jari tangan dari jarak satu meter di depannya walaupun memakai kacamata atau ada cukup cahaya untuk melihat.
3) Cacat rungu wicara, yaitu suatu keadaan cacat akibat bencana, dimana korban bencana tidak dapat mendengar dan berbicara dengan baik sehingga menjadi hambatan dalam melakukan kegiatan sehari-hari secara layak/wajar.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6774, 'a. Cacat fisik; yaitu kecacatan secara fisik yang diakibatkan oleh bencana, baik bencana alam, nonalam maupun bencana sosial.
Kecacatan fisik dapat dikategorikan sebagai berikut :
1) Cacat Tubuh, yaitu keadaan cacat dimana korban bencana mengalami kerusakan bentuk tubuh atau hambatan pada tulang, otot, dan sendi dalam fungsinya yang normal. Ciri-cirinya antara lain : a) Kehilangan anggota tubuh seperti lengan, tangan dan kaki baik sebelah atau kedua-duanya. b) Kerusakan permukaan kulit akibat luka bakar derajat ketiga dan sekurang-kurangnya mengenai 20 % luas permukaan tubuh. c) Patah tulang.
2) Cacat netra, yaitu suatu keadaan cacat penglihatan sebagai akibat bencana, sehingga menjadi hambatan dalam melakukan kegiatan sehari-hari secara layak atau wajar.
Ciri-cirinya antara lain : a) Buta total, yaitu kedua belah mata tidak dapat melihat. b) Masih mempunyai sisa penglihatan atau kurang awas dengan cirinya tidak dapat menghitung jari tangan dari jarak satu meter di depannya walaupun memakai kacamata atau ada cukup cahaya untuk melihat.
3) Cacat rungu wicara, yaitu suatu keadaan cacat akibat bencana, dimana korban bencana tidak dapat mendengar dan berbicara dengan baik sehingga menjadi hambatan dalam melakukan kegiatan sehari-hari secara layak/wajar.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2010 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6775, 'perka-15-2010', 17, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'Ciri-cirinya antara lain : a) Tidak dapat mendengar atau memahami perkataan yang disampaikan orang lain kepadanya dalam jarak satu meter tanpa alat bantu pendengaran. b) Tidak dapat berbicara sama sekali atau berbicara tidak jelas atau bicaranya tidak dapat dimengerti. c) Mengalami hambatan atau kesulitan dalam berkomunikasi dengan orang lain.
b. Gangguan mental yang diakibatkan oleh bencana, baik bencana alam, nonalam maupun bencana sosial, sehingga orang yang mengalaminya tidak dapat berperilaku seperti orang normal pada umumnya, dan menjadi hambatan dalam melakukan kegiatan sehari-hari secara layak/wajar. Kondisi korban yang mengalami gangguan mental ditetapkan oleh petugas yang berkompeten di bidangnya.
Jenis gangguan mental yang berlangsung dalam jangka waktu yang lama setelah terjadi bencana disebut Post Traumatic Stress Disorder (PTSD), dengan ciri-ciri gejalanya adalah :
1) Depersonalisasi, yaitu korban bencana mengalami perasaan yang ganjil, merasa terpisah antara tubuh/badan dan jiwa, atau merasa bahwa peristiwa yang terjadi pada dirinya harusnya terjadi juga pada orang lain.
2) Derealisasi, yaitu korban bencana mengalami perasaan bahwa apa yang dialami oleh korban terjadi lebih lama daripada keadaan yang sebenarnya, tidak percaya dengan kejadian yang berlangsung atau kejadian yang berlangsung dianggapnya sebagai halusinasi (persepsi yang keliru) atau delusi (keyakinan/kepercayaan yang keliru).
Post Traumatic Stress Disorder (PTSD) terdiri atas 3 jenis, yaitu :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6775, 'Ciri-cirinya antara lain : a) Tidak dapat mendengar atau memahami perkataan yang disampaikan orang lain kepadanya dalam jarak satu meter tanpa alat bantu pendengaran. b) Tidak dapat berbicara sama sekali atau berbicara tidak jelas atau bicaranya tidak dapat dimengerti. c) Mengalami hambatan atau kesulitan dalam berkomunikasi dengan orang lain.
b. Gangguan mental yang diakibatkan oleh bencana, baik bencana alam, nonalam maupun bencana sosial, sehingga orang yang mengalaminya tidak dapat berperilaku seperti orang normal pada umumnya, dan menjadi hambatan dalam melakukan kegiatan sehari-hari secara layak/wajar. Kondisi korban yang mengalami gangguan mental ditetapkan oleh petugas yang berkompeten di bidangnya.
Jenis gangguan mental yang berlangsung dalam jangka waktu yang lama setelah terjadi bencana disebut Post Traumatic Stress Disorder (PTSD), dengan ciri-ciri gejalanya adalah :
1) Depersonalisasi, yaitu korban bencana mengalami perasaan yang ganjil, merasa terpisah antara tubuh/badan dan jiwa, atau merasa bahwa peristiwa yang terjadi pada dirinya harusnya terjadi juga pada orang lain.
2) Derealisasi, yaitu korban bencana mengalami perasaan bahwa apa yang dialami oleh korban terjadi lebih lama daripada keadaan yang sebenarnya, tidak percaya dengan kejadian yang berlangsung atau kejadian yang berlangsung dianggapnya sebagai halusinasi (persepsi yang keliru) atau delusi (keyakinan/kepercayaan yang keliru).
Post Traumatic Stress Disorder (PTSD) terdiri atas 3 jenis, yaitu :', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2010 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6776, 'perka-15-2010', 18, 'lampiran', 'Lampiran hal. 12', NULL, 12, '1) PTSD akut, jika simptom (gejala) muncul kurang dari 3 bulan.
2) PTSD kronis, jika simptom muncul setelah 3 bulan atau lebih.
3) PTSD tertunda, jika simptom muncul paling kurang 6 bulan setelah peristiwa bencana.
c. Cacat fisik dan gangguan mental; yaitu kecacatan secara fisik dan gangguan mental yang diakibatkan oleh bencana, baik bencana alam, nonalam maupun bencana sosial.
Bencana dapat mengakibatkan seseorang menyandang 2 (dua) macam kecacatan yakni gangguan pada fungsi tubuh, antara lain gerak tubuh, penglihatan, pendengaran dan kemampuan berbicara, serta mengalami gangguan mental.
3. Kriteria Penerima Bantuan Santunan Kecacatan Penerima bantuan santunan kecacatan mencakup orang dari segala usia yang mengalami kecacatan akibat bencana, baik yang termasuk dalam kategori cacat fisik, gangguan mental maupun cacat fisik dan gangguan mental, yang status kecacatannya dinyatakan dengan keterangan dari petugas pelaksana penanggulangan bencana atau pihak-pihak yang berwenang.
Penerima bantuan santunan kecacatan digolongkan ke dalam 3 jenis :
a. Cacat Ringan, yaitu keadaan cacat akibat bencana dengan kriteria sebagai berikut :
1) Kehilangan pendengaran pada sebelah telinga.
2) Kehilangan ibu jari tangan kanan.
3) Kehilangan ibu jari tangan kiri.
4) Kehilangan telunjuk tangan kanan.
5) Kehilangan telunjuk tangan kiri.
6) Kehilangan salah satu jari lain tangan kanan.
7) Kehilangan salah satu jari lain tangan kiri.
8) Kehilangan ruas pertama telunjuk kanan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6776, '1) PTSD akut, jika simptom (gejala) muncul kurang dari 3 bulan.
2) PTSD kronis, jika simptom muncul setelah 3 bulan atau lebih.
3) PTSD tertunda, jika simptom muncul paling kurang 6 bulan setelah peristiwa bencana.
c. Cacat fisik dan gangguan mental; yaitu kecacatan secara fisik dan gangguan mental yang diakibatkan oleh bencana, baik bencana alam, nonalam maupun bencana sosial.
Bencana dapat mengakibatkan seseorang menyandang 2 (dua) macam kecacatan yakni gangguan pada fungsi tubuh, antara lain gerak tubuh, penglihatan, pendengaran dan kemampuan berbicara, serta mengalami gangguan mental.
3. Kriteria Penerima Bantuan Santunan Kecacatan Penerima bantuan santunan kecacatan mencakup orang dari segala usia yang mengalami kecacatan akibat bencana, baik yang termasuk dalam kategori cacat fisik, gangguan mental maupun cacat fisik dan gangguan mental, yang status kecacatannya dinyatakan dengan keterangan dari petugas pelaksana penanggulangan bencana atau pihak-pihak yang berwenang.
Penerima bantuan santunan kecacatan digolongkan ke dalam 3 jenis :
a. Cacat Ringan, yaitu keadaan cacat akibat bencana dengan kriteria sebagai berikut :
1) Kehilangan pendengaran pada sebelah telinga.
2) Kehilangan ibu jari tangan kanan.
3) Kehilangan ibu jari tangan kiri.
4) Kehilangan telunjuk tangan kanan.
5) Kehilangan telunjuk tangan kiri.
6) Kehilangan salah satu jari lain tangan kanan.
7) Kehilangan salah satu jari lain tangan kiri.
8) Kehilangan ruas pertama telunjuk kanan.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2010 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6777, 'perka-15-2010', 19, 'lampiran', 'Lampiran hal. 13', NULL, 13, '9) Kehilangan ruas pertama telunjuk kiri.
10) Kehilangan ruas pertama jari lain tangan kanan.
11) Kehilangan ruas pertama jari lain tangan kiri.
12) Kehilangan salah satu ibu jari kaki.
13) Kehilangan salah satu jari telunjuk kaki.
14) Kehilangan salah satu jari kaki lain.
15) Kehilangan daun telinga sebelah.
16) Kehilangan kedua belah daun telinga.
17) Kehilangan sebagian fungsi penglihatan.
b. Cacat Sedang, yaitu keadaan cacat akibat bencana dengan kriteria sebagai berikut :
1) Kehilangan/lumpuh lengan kanan dari sendi bahu ke bawah.
2) Kehilangan/lumpuh lengan kiri dari sendi bahu ke bawah.
3) Kehilangan/lumpuh lengan kanan dari atau dari atas siku ke bawah.
4) Kehilangan/lumpuh lengan kiri dari atau dari atas siku ke bawah.
5) Kehilangan/lumpuh tangan kanan dari atau dari atas pergelangan ke bawah.
6) Kehilangan/lumpuh tangan kiri dari atau dari atas pergelangan ke bawah.
7) Kehilangan/lumpuh sebelah kaki dari pangkal paha ke bawah.
8) Kehilangan/lumpuh sebelah kaki dari mata kaki ke bawah.
9) Kehilangan/kerusakan sebelah mata atau diplopia pada penglihatan dekat.
10) Kehilangan pendengaran pada kedua belah telinga.
11) Terkelupasnya kulit kepala lebih dari 50%.
12) Kehilangan cuping hidung.
c. Cacat Berat, yaitu keadaan cacat akibat bencana dengan criteria sebagai berikut :
1) Kehilangan/lumpuh kedua belah kaki dari pangkal paha ke bawah.
2) Kehilangan/lumpuh kedua belah kaki dari mata kaki ke bawah.
3) Kehilangan penglihatan kedua belah mata.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6777, '9) Kehilangan ruas pertama telunjuk kiri.
10) Kehilangan ruas pertama jari lain tangan kanan.
11) Kehilangan ruas pertama jari lain tangan kiri.
12) Kehilangan salah satu ibu jari kaki.
13) Kehilangan salah satu jari telunjuk kaki.
14) Kehilangan salah satu jari kaki lain.
15) Kehilangan daun telinga sebelah.
16) Kehilangan kedua belah daun telinga.
17) Kehilangan sebagian fungsi penglihatan.
b. Cacat Sedang, yaitu keadaan cacat akibat bencana dengan kriteria sebagai berikut :
1) Kehilangan/lumpuh lengan kanan dari sendi bahu ke bawah.
2) Kehilangan/lumpuh lengan kiri dari sendi bahu ke bawah.
3) Kehilangan/lumpuh lengan kanan dari atau dari atas siku ke bawah.
4) Kehilangan/lumpuh lengan kiri dari atau dari atas siku ke bawah.
5) Kehilangan/lumpuh tangan kanan dari atau dari atas pergelangan ke bawah.
6) Kehilangan/lumpuh tangan kiri dari atau dari atas pergelangan ke bawah.
7) Kehilangan/lumpuh sebelah kaki dari pangkal paha ke bawah.
8) Kehilangan/lumpuh sebelah kaki dari mata kaki ke bawah.
9) Kehilangan/kerusakan sebelah mata atau diplopia pada penglihatan dekat.
10) Kehilangan pendengaran pada kedua belah telinga.
11) Terkelupasnya kulit kepala lebih dari 50%.
12) Kehilangan cuping hidung.
c. Cacat Berat, yaitu keadaan cacat akibat bencana dengan criteria sebagai berikut :
1) Kehilangan/lumpuh kedua belah kaki dari pangkal paha ke bawah.
2) Kehilangan/lumpuh kedua belah kaki dari mata kaki ke bawah.
3) Kehilangan penglihatan kedua belah mata.', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2010 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Kecacatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6778, 'perka-15-2010', 20, 'lampiran', 'Lampiran hal. 14', NULL, 14, '4) Kehilangan kemampuan kerja mental tetap.
5) PTSD akut dan kronis.
d. Apabila korban bencana yang mengalami kecacatan tidak dapat berkomunikasi dengan orang lain, misalnya karena mengalami gangguan kejiwaan hilangnya kemampuan kerja mental tetap, PTSD akut dan kronis, maka bantuan dapat diserahkan kepada pihak keluarga atau kerabat korban atau Ketua RT/RW untuk selanjutnya diserahkan kepada korban yang bersangkutan.
B. Kategori dan Besaran Bantuan
1. Kategori Bantuan
a. Bantuan santunan keprihatinan bagi setiap korban bencana yang mengalami kecacatan ringan, dalam bentuk uang tunai yang dibayarkan satu kali.
b. Bantuan santunan keprihatinan bagi setiap korban bencana yang mengalami kecacatan sedang, dalam bentuk uang tunai yang dibayarkan satu kali.
c. Bantuan santunan keprihatinan bagi setiap korban bencana yang mengalami kecacatan berat, dalam bentuk uang tunai yang dibayarkan satu kali.
2. Besaran Bantuan Besaran bantuan santunan kecacatan disesuaikan dengan kategori kecacatan, sebagai berikut :
a. Besaran bantuan santunan bagi korban bencana yang mengalami cacat ringan maksimal sebesar Rp. 500.000,- (Lima ratus ribu rupiah) per jiwa, yang dibayarkan sekaligus satu kali.
b. Besaran bantuan santunan bagi korban bencana yang mengalami cacat sedang maksimal sebesar Rp. 1.000.000,- (Satu juta rupiah) per jiwa, yang dibayarkan sekaligus satu kali.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6778, '4) Kehilangan kemampuan kerja mental tetap.
5) PTSD akut dan kronis.
d. Apabila korban bencana yang mengalami kecacatan tidak dapat berkomunikasi dengan orang lain, misalnya karena mengalami gangguan kejiwaan hilangnya kemampuan kerja mental tetap, PTSD akut dan kronis, maka bantuan dapat diserahkan kepada pihak keluarga atau kerabat korban atau Ketua RT/RW untuk selanjutnya diserahkan kepada korban yang bersangkutan.
