INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6793, 'perka-15-2010', 35, 'lampiran', 'Lampiran hal. 31', NULL, 31, 'C. Permohonan bantuan santunan kecacatan ini dilengkapi dengan :
1. Surat Keterangan Kecacatan akibat bencana dari petugas medis yang berwenang, atau Lurah/Kepala Desa setempat.
2. Salinan/Copy KTP pemohon yang telah memiliki kewajiban memiliki KTP
3. Salinan/Copy Kartu Keluarga atau surat keterangan keluarga dari Kelurahan/Desa setempat Keterangan tersebut di atas saya buat dengan sebenarnya. Jika dikemudian hari ternyata terdapat hal yang tidak benar, saya wajib mengembalikan semua uang yang diterima dari hak tersebut di atas, serta bersedia dituntut di muka pengadilan. …………….., …… …..………………… ...… (tempat), (tanggal, bulan, tahun) Petugas Identifikasi, Pemohon, ___________________________ __________________________ Nama lengkap dan tanda tangan Nama lengkap dan tanda tangan *) coret yang tidak perlu Lampiran 6 Bagan Alur Mekanisme Penyaluran Bantuan Santunan Kecacatan dan Rujukan Korban ke Lembaga Pelayanan dan Rehabilitasi PENDATAAN IDENTIFIKASI VERIFIKASI RAPAT BNPB/ PENYALURAN BENCANA Penyandang BPBD DAN BANTUAN SANTUNAN Cacat Akibat INSTANSI KECACATAN Bencana TERKAIT KATEGORISASI KECACATAN CACAT CACAT CACAT RINGAN SEDANG BERAT Bagan Mekanisme Penyaluran Bantuan Santunan Kecacatan dalam Konteks Kedaruratan Bencana Rujukan LEMBAGA PELAYANAN & REHABILITASI MEDIS SOSIAL VOKASIONAL PENDIDIKAN Penyandang Cacat akibat bencana & akibat lainnya Bagan Rujukan Korban yang Telah Mendapatkan Santunan Kecacatan dalam Konteks Rehabilitasi & Rekonstruksi');
