INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6801, 'perka-15-2011', 7, 'lain', 'BAB IV PENUTUP... onn onar nnnnna nana 42 (lanjutan 1)', NULL, 4, '- iii - Tabel 2.4. : Substansi PDNA 9 Tabel 2.5. Pemaduan Substansi Rehabilitasi dan Rekonstruksi dalam 10 Pengkajian Akibat Bencana (Contoh) Tabel 2.6. Pemaduan Substansi Rehabilitasi dan Rekonstruksi dalam 11 Pengkajian Dampak Bencana Tabel 2.7. Pemaduan Substansi Rehabilitasi dan Rekonstruksi dalam 12 Pengkajian Kebutuhan Pemulihan (Contoh) Tabel 3.1. : Tujuan dan Keluaran dalam Tahap-Tahap Pelaksanaan PDNA 14 Tabel 3.2. : Struktur Kerangka Acuan Kerja PDNA 16 Tabel 3.3. : Metode Pengumpulan Data 20 Tabel 3.4. : Data dasar yang perlu dikumpulkan 23 Tabel 3.5. : Contoh Data Lapangan Pengkajian Akibat Bencana 25 Tabel 3.6. : Pengkajian Gangguan Akses 34 Tabel 3.7. : Pengkajian Gangguan Akses 35 Tabel 3.8. : Pengkajian Gangguan Akses 36 Tabel 3.9. : Pemaduan Substansi Rehabilitasi dan Rekonstruksi dalam 37 Pengkajian Dampak Bencana Tabel 3.10. : Contoh Pengkajian Kebutuhan Pemulihan 39 PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 15 TAHUN 2011 TENTANG PEDOMAN PENGKAJIAN KEBUTUHAN PASCA BENCANA DENGAN RAHMAT TUHAN YANG MAHA ESA KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Menimbang : a. bahwa untuk melaksanakan ketentuan Pasal 56 ayat (4) dan 76 ayat
(4) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana,
b. bahwa untuk melaksanakan ketentuan Pasal 6 dan 8 Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi Dan Rekonstruksi Pasca Bencana,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6801, '- iii - Tabel 2.4. : Substansi PDNA 9 Tabel 2.5. Pemaduan Substansi Rehabilitasi dan Rekonstruksi dalam 10 Pengkajian Akibat Bencana (Contoh) Tabel 2.6. Pemaduan Substansi Rehabilitasi dan Rekonstruksi dalam 11 Pengkajian Dampak Bencana Tabel 2.7. Pemaduan Substansi Rehabilitasi dan Rekonstruksi dalam 12 Pengkajian Kebutuhan Pemulihan (Contoh) Tabel 3.1. : Tujuan dan Keluaran dalam Tahap-Tahap Pelaksanaan PDNA 14 Tabel 3.2. : Struktur Kerangka Acuan Kerja PDNA 16 Tabel 3.3. : Metode Pengumpulan Data 20 Tabel 3.4. : Data dasar yang perlu dikumpulkan 23 Tabel 3.5. : Contoh Data Lapangan Pengkajian Akibat Bencana 25 Tabel 3.6. : Pengkajian Gangguan Akses 34 Tabel 3.7. : Pengkajian Gangguan Akses 35 Tabel 3.8. : Pengkajian Gangguan Akses 36 Tabel 3.9. : Pemaduan Substansi Rehabilitasi dan Rekonstruksi dalam 37 Pengkajian Dampak Bencana Tabel 3.10. : Contoh Pengkajian Kebutuhan Pemulihan 39 PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 15 TAHUN 2011 TENTANG PEDOMAN PENGKAJIAN KEBUTUHAN PASCA BENCANA DENGAN RAHMAT TUHAN YANG MAHA ESA KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Menimbang : a. bahwa untuk melaksanakan ketentuan Pasal 56 ayat (4) dan 76 ayat
(4) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana,
b. bahwa untuk melaksanakan ketentuan Pasal 6 dan 8 Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi Dan Rekonstruksi Pasca Bencana,', 'BAB IV PENUTUP... onn onar nnnnna nana 42 (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6802, 'perka-15-2011', 8, 'lain', 'BAB IV PENUTUP... onn onar nnnnna nana 42 (lanjutan 2)', NULL, 5, 'c. bahwa berdasarkan pertimbangan huruf a dan b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Pengkajian Dan Kebutuhan Pasca Bencana, Mengingat : 1. Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),
2. Peraturan Pemerintah Republik Indonesia Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828).
3. Peraturan Pemerintah Republik Indonesia Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829).
4. Peraturan Pemerintah Republik Indonesia Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non-Pemerintah Dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830).
5. Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
6. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 tahun 2008 tentang Organisasi Dan Tata Kerja Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6802, 'c. bahwa berdasarkan pertimbangan huruf a dan b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Pengkajian Dan Kebutuhan Pasca Bencana, Mengingat : 1. Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),
2. Peraturan Pemerintah Republik Indonesia Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828).
3. Peraturan Pemerintah Republik Indonesia Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829).
4. Peraturan Pemerintah Republik Indonesia Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non-Pemerintah Dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830).
5. Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
6. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 tahun 2008 tentang Organisasi Dan Tata Kerja Badan Nasional Penanggulangan Bencana;', 'BAB IV PENUTUP... onn onar nnnnna nana 42 (lanjutan 2)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6803, 'perka-15-2011', 9, 'lain', 'BAB IV PENUTUP... onn onar nnnnna nana 42 (lanjutan 3)', NULL, 6, '7. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008 tentang Pedoman Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah;
8. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi Pasca Bencana;
MEMUTUSKAN Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN PENGKAJIAN KEBUTUHAN PASCA BENCANA Pasal 1 Pedoman Pengkajian Kebutuhan Pasca Bencana yang selanjutnya disebut Pedoman Pengkajian Kebutuhan Pasca Bencana /Post Disaster Need Assessment (PDNA) merupakan panduan/acuan bagi Pemerintah, Pemerintah Provinsi dan Pemerintah Kabupaten/Kota untuk menjalankan proses penilaian atas kerusakan dan kerugian serta kebutuhan yang bersifat komprehensif baik aspek fisik maupun aspek kemanusiaan akibat bencana.
Pasal 2 Pedoman ini merupakan instrumen untuk melaksanakan konsep rehabilitasi dan rekonstruksi yang mencakup aspek pemulihan fisik dan aspek kemanusiaan dengan menggunakan prinsip dasar yaitu membangun yang lebih baik (build back better) dan pengurangan risiko bencana (disaster risk reduction).
Pasal 3 Pedoman sebagaimana dimaksud dalam Pasal 1 adalah sebagaimana dimaksud dalam lampiran, yang merupakan bagian tak terpisahkan dari Peraturan ini.
Pasal 4 Peraturan ini mulai berlaku pada tanggal ditetapkan.
Ditetapkan di : Jakarta padatanggal : 8 Desember 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd DR. SYAMSUL MAARIF, M.Si.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6803, '7. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008 tentang Pedoman Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah;
8. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi Pasca Bencana;
