INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6842, 'perka-15-2011', 48, 'lain', 'BAB III (lanjutan 16)', NULL, 31, '2. Pengumpulan Data Lapangan Tim Pengumpulan Data mengumpulkan data lapangan dengan metode pengumpulan data sebagaimana tertera di bagian sebelumnya. Contoh data lapangan yang diperlukan terdapat pada tabel 3.5. berikut.
Pengumpulan data lapangan terkait dengan kerusakan dan kerugian dilakukan dengan menggunakan formulir inventarisasi kerusakan dan kerugian sebagaimana terlampir dalam Formulir 4.
Pengumpulan data lapangan terkait dengan gangguan terhadap akses, gangguan terhadap fungsi, dan peningkatan risiko dilakukan dengan menggunakan kuesioner survei rumah tangga, dan kuesioner wawancara informan kunci/diskusi kelompok terfokus sebagaimana terlampir dalam Formulir 5 dan 6. unit status jembatan terhadap bahan demokrasi lainnya terganggu (nasional, provinsi pangan karena karena kendala dan kab/kota) dalam transportasi transportasi kerusakan berat, pendistribusian sedang, ringan. bahan pokok terganggu Bila ada : sarana dan prasarana kereta api, pelabuhan laut, udara dan jalan toll, menurut jumlah dan status kerusakan (berat, sedang dan ringan).
Gunakan sumber data resmi dari pengelolanya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6842, '2. Pengumpulan Data Lapangan Tim Pengumpulan Data mengumpulkan data lapangan dengan metode pengumpulan data sebagaimana tertera di bagian sebelumnya. Contoh data lapangan yang diperlukan terdapat pada tabel 3.5. berikut.
Pengumpulan data lapangan terkait dengan kerusakan dan kerugian dilakukan dengan menggunakan formulir inventarisasi kerusakan dan kerugian sebagaimana terlampir dalam Formulir 4.
Pengumpulan data lapangan terkait dengan gangguan terhadap akses, gangguan terhadap fungsi, dan peningkatan risiko dilakukan dengan menggunakan kuesioner survei rumah tangga, dan kuesioner wawancara informan kunci/diskusi kelompok terfokus sebagaimana terlampir dalam Formulir 5 dan 6. unit status jembatan terhadap bahan demokrasi lainnya terganggu (nasional, provinsi pangan karena karena kendala dan kab/kota) dalam transportasi transportasi kerusakan berat, pendistribusian sedang, ringan. bahan pokok terganggu Bila ada : sarana dan prasarana kereta api, pelabuhan laut, udara dan jalan toll, menurut jumlah dan status kerusakan (berat, sedang dan ringan).
Gunakan sumber data resmi dari pengelolanya.', 'BAB III (lanjutan 16)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6843, 'perka-15-2011', 49, 'lain', 'BAB III (lanjutan 17)', NULL, 33, 'Energi Jumlah dan kapasitas Nilai kerugian karena Hilangnya akses Gangguan pelayanan Tidak berfungsinya prasarana distribusi produksi terhenti terhadap pekerjaan kesehatan dan perangkat Early bahan bakar: unit akibat ketiadaan keluarga karena pendidikan karena Warning System SPBU, unit depo tenaga listrik dan rusaknya listrik mati (Tsunami Buoy dll) BBM dan tingkat bahan bakar. infrastruktur energi karena listrik mati kerusakan berat dan Meningkatnya beban ringan. perempuan dalam Jumlah dan kapasitas rumah tangga karena prasarana tidak bisa memasak ketenagalistrikan: dengan mudah jaringan utama dan Terganggunya proses jaringan distribusi, produksi di industri jalur distribusi rumah kecil karena tangga menurut ketiadaan listrik dan tingkat kerusakan bahan bakar (berat dan ringan).
Gunakan sumber data resmi dari pengelolanya.
Pos dan Jumlah insfrastruktur Nilai kerugian karena Hilangnya akses Terganggunya proses Meningkatnya risiko Telekomunikasi jaringan, satuan pengiriman barang terhadap informasi pengambilan terhadap bencana sambungan telepon terganggu terkini keputusan karena komunikasi menurut tingkat pemerintah karena terganggu Nilai kerugian dalam kerusakan (berat dan pengiriman pesan proses produksi Panggilan SOS ringan). dalam hubungan karena ternganggu antar lembaga Jumlah insfrastruktur telekomunikasi pemerintah terganggu Pengiriman logistik pengiriman logistik terganggu untuk bencana dan pos menurut terganggu tingkat kerusakan (berat dan ringan).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6843, 'Energi Jumlah dan kapasitas Nilai kerugian karena Hilangnya akses Gangguan pelayanan Tidak berfungsinya prasarana distribusi produksi terhenti terhadap pekerjaan kesehatan dan perangkat Early bahan bakar: unit akibat ketiadaan keluarga karena pendidikan karena Warning System SPBU, unit depo tenaga listrik dan rusaknya listrik mati (Tsunami Buoy dll) BBM dan tingkat bahan bakar. infrastruktur energi karena listrik mati kerusakan berat dan Meningkatnya beban ringan. perempuan dalam Jumlah dan kapasitas rumah tangga karena prasarana tidak bisa memasak ketenagalistrikan: dengan mudah jaringan utama dan Terganggunya proses jaringan distribusi, produksi di industri jalur distribusi rumah kecil karena tangga menurut ketiadaan listrik dan tingkat kerusakan bahan bakar (berat dan ringan).
Gunakan sumber data resmi dari pengelolanya.
Pos dan Jumlah insfrastruktur Nilai kerugian karena Hilangnya akses Terganggunya proses Meningkatnya risiko Telekomunikasi jaringan, satuan pengiriman barang terhadap informasi pengambilan terhadap bencana sambungan telepon terganggu terkini keputusan karena komunikasi menurut tingkat pemerintah karena terganggu Nilai kerugian dalam kerusakan (berat dan pengiriman pesan proses produksi Panggilan SOS ringan). dalam hubungan karena ternganggu antar lembaga Jumlah insfrastruktur telekomunikasi pemerintah terganggu Pengiriman logistik pengiriman logistik terganggu untuk bencana dan pos menurut terganggu tingkat kerusakan (berat dan ringan).', 'BAB III (lanjutan 17)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6844, 'perka-15-2011', 50, 'lain', 'BAB III (lanjutan 18)', NULL, 34, 'Gunakan sumber data resmi dari pengelolanya.
Air dan Sanitasi Jumlah dan kapasitas Nilai kerugian karena Hilangnya akses Bertambahnya waktu Meningkatnya risiko infrastruktur air bersih biaya mengakses air keluarga terhadap air dan sumber daya kekerasan berbasis yang rusak meliputi bersih semakin mahal bersih untuk mengakses air gender karena instalasi air bersih, bersih yang menjadi sumber air jauh dan Hilangnya sumber unit kerusakan pompa jauh letaknya tidak aman air bersih keluarga dan unit kerusakan dan masyarakat Bertambahnya beban prasarana pendukung perempuan untuk lainnya menurut mengambil air bersih tingkat kerusakan berat dan ringan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6844, 'Gunakan sumber data resmi dari pengelolanya.
Air dan Sanitasi Jumlah dan kapasitas Nilai kerugian karena Hilangnya akses Bertambahnya waktu Meningkatnya risiko infrastruktur air bersih biaya mengakses air keluarga terhadap air dan sumber daya kekerasan berbasis yang rusak meliputi bersih semakin mahal bersih untuk mengakses air gender karena instalasi air bersih, bersih yang menjadi sumber air jauh dan Hilangnya sumber unit kerusakan pompa jauh letaknya tidak aman air bersih keluarga dan unit kerusakan dan masyarakat Bertambahnya beban prasarana pendukung perempuan untuk lainnya menurut mengambil air bersih tingkat kerusakan berat dan ringan.', 'BAB III (lanjutan 18)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6845, 'perka-15-2011', 51, 'lain', 'BAB III (lanjutan 19)', NULL, 34, 'Pemerintahan Jumlah Kantor kepala Nilai kerugian Tidak berfungsinya Terganggunya proses Menurunnya umum daerah, kantor ekonomi karena layanan pengambilan koordinasi tingkat kecamatan, fasilitas pengurusan perijinan, kependudukan kebijakan publik di desa untuk merespon pemerintahan umum kepabeanan dan desa keadaan darurat lainnya yang rusak layanan publik yang akibat bencana terganggu Ekonomi Pertanian dan Jumlah kerusakan Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya peternakan infrastruktur irigasi gagal panen pada terhadap pekerjaan berfungsinya kerentanan karena menurut jenis (irigasi musim panen berikut bagi keluarga petani kelompok tani dan hancurnya sumber teknis, irigasi non hingga bisa panen kelompok ternak daya cadangan teknis, dan irigasi lagi keluarga berupa sederhana) menurut ternak dan tanaman tingkat kerusakan berat produksi dan ringan Perkebunan Jumlah tegakan dan Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya fasilitas kebun yang gagal panen pada terhadap pekerjaan berfungsinya kerentanan karena rusak akibat bencana musim panen berikut bagi keluarga kelompok kebun hancurnya sumber hingga bisa panen pekebun daya cadangan lagi keluarga berupa tanaman produksi Perikanan Luas kerusakan kolam Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya dan tambak budidaya gagal panen pada terhadap pekerjaan berfungsinya kerentanan karena perikanan menurut musim panen berikut bagi keluarga kelompok perikanan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6845, 'Pemerintahan Jumlah Kantor kepala Nilai kerugian Tidak berfungsinya Terganggunya proses Menurunnya umum daerah, kantor ekonomi karena layanan pengambilan koordinasi tingkat kecamatan, fasilitas pengurusan perijinan, kependudukan kebijakan publik di desa untuk merespon pemerintahan umum kepabeanan dan desa keadaan darurat lainnya yang rusak layanan publik yang akibat bencana terganggu Ekonomi Pertanian dan Jumlah kerusakan Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya peternakan infrastruktur irigasi gagal panen pada terhadap pekerjaan berfungsinya kerentanan karena menurut jenis (irigasi musim panen berikut bagi keluarga petani kelompok tani dan hancurnya sumber teknis, irigasi non hingga bisa panen kelompok ternak daya cadangan teknis, dan irigasi lagi keluarga berupa sederhana) menurut ternak dan tanaman tingkat kerusakan berat produksi dan ringan Perkebunan Jumlah tegakan dan Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya fasilitas kebun yang gagal panen pada terhadap pekerjaan berfungsinya kerentanan karena rusak akibat bencana musim panen berikut bagi keluarga kelompok kebun hancurnya sumber hingga bisa panen pekebun daya cadangan lagi keluarga berupa tanaman produksi Perikanan Luas kerusakan kolam Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya dan tambak budidaya gagal panen pada terhadap pekerjaan berfungsinya kerentanan karena perikanan menurut musim panen berikut bagi keluarga kelompok perikanan', 'BAB III (lanjutan 19)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6846, 'perka-15-2011', 52, 'lain', 'BAB III (lanjutan 20)', NULL, 34, 'hancurnya sumber tingkat kerusakannya hingga bisa panen atau tambak daya cadangan (berat, sedang, lagi keluarga ringan).
Industri Kecil Jumlah unit industri Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya dan Menengah yang rusak menurut kehilangan terhadap pekerjaan berfungsinya kerentanan karena jenis industri kesempatan bagi keluarga kelompok industri hancurnya sumber (kecil/menengah) dan berdagang akibat industri kecil dan daya cadangan jenis usahanya rusaknya alat menengah keluarga (kerajinan, konveksi, produksi dan bahan dll) dan tingkat baku kerusakannya (berat,sedang ringan).
Perdagangan Jumlah prasarana Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya perdagangan (pasar, kehilangan terhadap pekerjaan berfungsinya kerentanan karena los, kios, loket) kesempatan bagi keluarga distribusi bahan hancurnya sumber menurut kerusakan berdagang akibat pokok daya cadangan (berat, sedang, rusaknya pasar, kios, keluarga ringan). Data dapat toko dll. dipilah menurut pasar tradisional/modern dan kepemilikannya (pemerintah/swasta).
Pariwisata Jumlah bangunan atau Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya prasarana objek menurunnya terhadap pekerjaan berfungsinya kerentanan karena pariwisata komersial wisatawan bagi keluarga kelompok pemandu hancurnya sumber yang rusak dan tingkat wisata daya cadangan kerusakannya (berat, keluarga sedang dan ringan).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6846, 'hancurnya sumber tingkat kerusakannya hingga bisa panen atau tambak daya cadangan (berat, sedang, lagi keluarga ringan).
Industri Kecil Jumlah unit industri Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya dan Menengah yang rusak menurut kehilangan terhadap pekerjaan berfungsinya kerentanan karena jenis industri kesempatan bagi keluarga kelompok industri hancurnya sumber (kecil/menengah) dan berdagang akibat industri kecil dan daya cadangan jenis usahanya rusaknya alat menengah keluarga (kerajinan, konveksi, produksi dan bahan dll) dan tingkat baku kerusakannya (berat,sedang ringan).
Perdagangan Jumlah prasarana Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya perdagangan (pasar, kehilangan terhadap pekerjaan berfungsinya kerentanan karena los, kios, loket) kesempatan bagi keluarga distribusi bahan hancurnya sumber menurut kerusakan berdagang akibat pokok daya cadangan (berat, sedang, rusaknya pasar, kios, keluarga ringan). Data dapat toko dll. dipilah menurut pasar tradisional/modern dan kepemilikannya (pemerintah/swasta).
Pariwisata Jumlah bangunan atau Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya prasarana objek menurunnya terhadap pekerjaan berfungsinya kerentanan karena pariwisata komersial wisatawan bagi keluarga kelompok pemandu hancurnya sumber yang rusak dan tingkat wisata daya cadangan kerusakannya (berat, keluarga sedang dan ringan).', 'BAB III (lanjutan 20)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6847, 'perka-15-2011', 53, 'lain', 'BAB III (lanjutan 21)', NULL, 36, 'Perbankan Jumlah dan luas Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya bangunan sektor kehilangan terhadap pekerjaan berfungsinya layanan kerentanan karena keuangan/perbankan kesempatan atas bagi keluarga perbankan hancurnya sumber dengan tingkat pendapatan bunga daya cadangan Gangguan untuk kerusakan berat, keluarga mengakses tabungan sedang dan ringan sebagai sumber daya serta kepemilikan cadangan keluarga (pemerintah/swasta).
Sosial dan Kesehatan Jumlah bangunan Biaya penyediaan Masalah-masalah Jumlah tenaga medis Meningkatnya risiko Kemanusiaan layanan kesehatan fasilitas puskesmas pelayanan kesehatan dan paramedik yang karena bangunan seperti rumah sakit, atau rumah sakit akibat bencana meninggal, pelayanan kesehatan puskesmas, sementara seperti tenaga medis mengungsi dan rusak puskesmas pembantu, kurang, obat mahal, terluka berat.
Ongkos yang lebih posyandu dll dan jaminan sosial mahal karena harus tingkat kerusakannya terhenti dan lain-lain. berobat di tempat (berat, sedang dan yang lebih jauh ringan).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6847, 'Perbankan Jumlah dan luas Nilai kerugian karena Hilangnya akses Gangguan terhadap Meningkatnya bangunan sektor kehilangan terhadap pekerjaan berfungsinya layanan kerentanan karena keuangan/perbankan kesempatan atas bagi keluarga perbankan hancurnya sumber dengan tingkat pendapatan bunga daya cadangan Gangguan untuk kerusakan berat, keluarga mengakses tabungan sedang dan ringan sebagai sumber daya serta kepemilikan cadangan keluarga (pemerintah/swasta).
Sosial dan Kesehatan Jumlah bangunan Biaya penyediaan Masalah-masalah Jumlah tenaga medis Meningkatnya risiko Kemanusiaan layanan kesehatan fasilitas puskesmas pelayanan kesehatan dan paramedik yang karena bangunan seperti rumah sakit, atau rumah sakit akibat bencana meninggal, pelayanan kesehatan puskesmas, sementara seperti tenaga medis mengungsi dan rusak puskesmas pembantu, kurang, obat mahal, terluka berat.
Ongkos yang lebih posyandu dll dan jaminan sosial mahal karena harus tingkat kerusakannya terhenti dan lain-lain. berobat di tempat (berat, sedang dan yang lebih jauh ringan).', 'BAB III (lanjutan 21)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6848, 'perka-15-2011', 54, 'lain', 'BAB III (lanjutan 22)', NULL, 37, 'Pendidikan Jumlah bangunan Biaya penyediaan Masalah-masalah Jumlah dan kondisi Meningkatnya risiko layanan pendidikan fasilitas sekolah pelayanan tenaga pendidikan karena bangunan menurut jenjang dan sementara pendidikan akibat yang meninggal, sekolah rusak tingkat kerusakannya bencana seperti mengungsi dan Biaya sekolah (berat, sedang dan kehilangan seragam terluka berat tambahan (SPP) ringan). sekolah dan alat karena sekolah tulis siswa. terhenti Agama Jumlah dan luas Biaya tambahan Masalah-masalah Jumlah dan kondisi Meningkatnya risiko bangunan peribadatan untuk menjalankan dalam menjalankan pemimpin agama karena bangunan (masjid/mushola, ritual keagamaan hak untuk beribadah yang meninggal, tempat ibadah rusak gereja, vihara, pura, setelah bencana sesuai agama mengungsi dan Meningkatnya risiko dll), dan tingkat masing-masing terluka berat karena organisasi kerusakannya (berat, karena mengungsi Kendala dalam keagamaan berhenti sedang dan ringan). menyelengarakan mewartakan PRB Jumlah orang/tokoh ritual agama secara agama yang komunal. meninggal, berpindah dan terluka berat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6848, 'Pendidikan Jumlah bangunan Biaya penyediaan Masalah-masalah Jumlah dan kondisi Meningkatnya risiko layanan pendidikan fasilitas sekolah pelayanan tenaga pendidikan karena bangunan menurut jenjang dan sementara pendidikan akibat yang meninggal, sekolah rusak tingkat kerusakannya bencana seperti mengungsi dan Biaya sekolah (berat, sedang dan kehilangan seragam terluka berat tambahan (SPP) ringan). sekolah dan alat karena sekolah tulis siswa. terhenti Agama Jumlah dan luas Biaya tambahan Masalah-masalah Jumlah dan kondisi Meningkatnya risiko bangunan peribadatan untuk menjalankan dalam menjalankan pemimpin agama karena bangunan (masjid/mushola, ritual keagamaan hak untuk beribadah yang meninggal, tempat ibadah rusak gereja, vihara, pura, setelah bencana sesuai agama mengungsi dan Meningkatnya risiko dll), dan tingkat masing-masing terluka berat karena organisasi kerusakannya (berat, karena mengungsi Kendala dalam keagamaan berhenti sedang dan ringan). menyelengarakan mewartakan PRB Jumlah orang/tokoh ritual agama secara agama yang komunal. meninggal, berpindah dan terluka berat.', 'BAB III (lanjutan 22)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6849, 'perka-15-2011', 55, 'lain', 'BAB III (lanjutan 23)', NULL, 37, 'Budaya Kerusakan bangunan Biaya tambahan Hilangnya kegiatan Terganggunya Terganggunya cagar budaya dan untuk kebudayaan karena kegiatan budaya yang organisasi berbasis bangunan bersejarah menyelenggarakan bencana ada kemasyarakatan yang yang bukan kegiatan budaya berguna untuk merupakan objek setelah bencana mengurangi risiko wisata komersial dan bencana tingkat kerusakannya Terganggunya (berat, sedang dan kegiatan budaya ringan). yang mengurangi risiko bencana.
Perlindungan Jumlah bangunan Biaya tambahan Gangguan sistem Jumlah pengelola Tergangunya sosial lembaga-lembaga untuk menyediakan perlindungan lembaga sosial yang kelembagaan yang yang bergerak fasilitas perlindungan kelompok rentan meninggal, memberikan dibidang sosial seperti rumah aman berpindah dan perlindungan sosial Hilangnya fungsi kemasyarakatan miliki dan lain-lain keluarga dalam terluka berat. terhadap kelompok pemerintah atau memberikan rentan seperti anak bukan, seperti perlindungan yatim dan lansia yayasan-yayasan terhadap kelompok sosial tingkat rentan kerusakannya (berat,sedang dan ringan).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6849, 'Budaya Kerusakan bangunan Biaya tambahan Hilangnya kegiatan Terganggunya Terganggunya cagar budaya dan untuk kebudayaan karena kegiatan budaya yang organisasi berbasis bangunan bersejarah menyelenggarakan bencana ada kemasyarakatan yang yang bukan kegiatan budaya berguna untuk merupakan objek setelah bencana mengurangi risiko wisata komersial dan bencana tingkat kerusakannya Terganggunya (berat, sedang dan kegiatan budaya ringan). yang mengurangi risiko bencana.
Perlindungan Jumlah bangunan Biaya tambahan Gangguan sistem Jumlah pengelola Tergangunya sosial lembaga-lembaga untuk menyediakan perlindungan lembaga sosial yang kelembagaan yang yang bergerak fasilitas perlindungan kelompok rentan meninggal, memberikan dibidang sosial seperti rumah aman berpindah dan perlindungan sosial Hilangnya fungsi kemasyarakatan miliki dan lain-lain keluarga dalam terluka berat. terhadap kelompok pemerintah atau memberikan rentan seperti anak bukan, seperti perlindungan yatim dan lansia yayasan-yayasan terhadap kelompok sosial tingkat rentan kerusakannya (berat,sedang dan ringan).', 'BAB III (lanjutan 23)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6850, 'perka-15-2011', 56, 'lain', 'BAB III (lanjutan 24)', NULL, 38, 'Kependudukan Jumlah bangunan Biaya yang Hilangnya akses Pada saat-saat Hilangnya basis data layanan dibutuhkan untuk terhadap jaminan tertentu, dokumen kependudukan kependudukan menyediakan kembali sosial karena kependudukan karena bencana dapat menurut jenjang dokumen hilangnya dokumen dibutuhkan untuk berarti gangguan pemerintahan dan kependudukan warga kependudukan terlibat dalam proses dalam pendistrbusian tingkat kerusakannya yang hilang akibat misalnya untuk pemerintahan bantuan bencana (berat, sedang dan bencana mendapatkan beras misalnya pemilu atau ringan). miskin, pemeriksaan musrenbang. kesehatan dengan jaminan kesehatan dll Ketahanan Jumlah fasilitas terkait Biaya tambahan Akses terhadap Organisasi lumbung Risiko kelaparan pangan cadangan dan untuk re-stocking dan ketersediaan pangan pangan yang pascabencana karena distribusi pangan distribusi dalam 3 minggu ke terganggu karena faktor ketiadaan stok menurut wilayah depan bencana pangan atau cakupan dan tingkat distribusi yang Ketersediaan kerusakannya (berat, buruk. cadangan pangan sedang dan ringan). untuk beberapa waktu kedepan Keamanan Jumlah dan luas Biaya penyediaan Hilangnya Terganggunya patroli Menurunnya ketertiban kerusakan bangunan- fasilitas keamanan perlindungan keamanan dan kewaspadaan bangunan TNI/POLRI sementara terhadap potensi siskamling terhadap bencana dengan tingkat konflik sosial, kerusakan berat, kriminalitas dan lain-sedang dan ringan. lain.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6850, 'Kependudukan Jumlah bangunan Biaya yang Hilangnya akses Pada saat-saat Hilangnya basis data layanan dibutuhkan untuk terhadap jaminan tertentu, dokumen kependudukan kependudukan menyediakan kembali sosial karena kependudukan karena bencana dapat menurut jenjang dokumen hilangnya dokumen dibutuhkan untuk berarti gangguan pemerintahan dan kependudukan warga kependudukan terlibat dalam proses dalam pendistrbusian tingkat kerusakannya yang hilang akibat misalnya untuk pemerintahan bantuan bencana (berat, sedang dan bencana mendapatkan beras misalnya pemilu atau ringan). miskin, pemeriksaan musrenbang. kesehatan dengan jaminan kesehatan dll Ketahanan Jumlah fasilitas terkait Biaya tambahan Akses terhadap Organisasi lumbung Risiko kelaparan pangan cadangan dan untuk re-stocking dan ketersediaan pangan pangan yang pascabencana karena distribusi pangan distribusi dalam 3 minggu ke terganggu karena faktor ketiadaan stok menurut wilayah depan bencana pangan atau cakupan dan tingkat distribusi yang Ketersediaan kerusakannya (berat, buruk. cadangan pangan sedang dan ringan). untuk beberapa waktu kedepan Keamanan Jumlah dan luas Biaya penyediaan Hilangnya Terganggunya patroli Menurunnya ketertiban kerusakan bangunan- fasilitas keamanan perlindungan keamanan dan kewaspadaan bangunan TNI/POLRI sementara terhadap potensi siskamling terhadap bencana dengan tingkat konflik sosial, kerusakan berat, kriminalitas dan lain-sedang dan ringan. lain.', 'BAB III (lanjutan 24)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6851, 'perka-15-2011', 57, 'lain', 'BAB III (lanjutan 25)', NULL, 39, 'Lintas Sektor Tata kelola Rusaknya sarana dan Biaya tambahan Hilangnya hak atas Proses pengadaan Penanganan keluhan pemerintahan prasarana untuk karena proses informasi publik barang dan jasa yang masyarakat yang pengadaan barang dan administrasi berjalan karena fasilitas menurun tidak terkelola jasa publik secara manual publikasi pemerintah akuntabilitasnya rusak Rusaknya fasilitas complaint handling unit.
Lingkungan Luas lingkungan Biaya tambahan Hilangnya akses Terganggunya proses Berubahnya karakter hidup hidup khusus yang untuk memulihkan terhadap lingkungan konservasi yang ancaman karena mengalami kerusakan lingkungan hidup yang berkualitas selama ini ada lingkungan yang (misalnya kawasan (tegakan yang rusak, rusak (wabah karena Konflik sumberdaya mangrove, hutan sumber air dan lain-kerusakan hutan karena lindung, taman lain) lingkungan) pengelolaan nasional dll). terganggu Gender Peningkatan beban Biaya tambahan Menurunnya akses Terganggunya fungsi Meningkatnya risiko kelompok gender untuk terhadap layanan sosial dan kekerasan berbasis tertentu karena menyelenggarakan kesehatan reproduksi kemasyarakatan gender kerusakan perlindungan untuk pemenuhan infrastruktur terhadap gender kebutuhan gender minoritas tertentu seperti posyandu atau PKK.
3. Verifikasi dan Validasi Data Data yang diperoleh memerlukan pemeriksaan silang dengan berbagai sumber dengan cara-cara berikut ini:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6851, 'Lintas Sektor Tata kelola Rusaknya sarana dan Biaya tambahan Hilangnya hak atas Proses pengadaan Penanganan keluhan pemerintahan prasarana untuk karena proses informasi publik barang dan jasa yang masyarakat yang pengadaan barang dan administrasi berjalan karena fasilitas menurun tidak terkelola jasa publik secara manual publikasi pemerintah akuntabilitasnya rusak Rusaknya fasilitas complaint handling unit.
Lingkungan Luas lingkungan Biaya tambahan Hilangnya akses Terganggunya proses Berubahnya karakter hidup hidup khusus yang untuk memulihkan terhadap lingkungan konservasi yang ancaman karena mengalami kerusakan lingkungan hidup yang berkualitas selama ini ada lingkungan yang (misalnya kawasan (tegakan yang rusak, rusak (wabah karena Konflik sumberdaya mangrove, hutan sumber air dan lain-kerusakan hutan karena lindung, taman lain) lingkungan) pengelolaan nasional dll). terganggu Gender Peningkatan beban Biaya tambahan Menurunnya akses Terganggunya fungsi Meningkatnya risiko kelompok gender untuk terhadap layanan sosial dan kekerasan berbasis tertentu karena menyelenggarakan kesehatan reproduksi kemasyarakatan gender kerusakan perlindungan untuk pemenuhan infrastruktur terhadap gender kebutuhan gender minoritas tertentu seperti posyandu atau PKK.
3. Verifikasi dan Validasi Data Data yang diperoleh memerlukan pemeriksaan silang dengan berbagai sumber dengan cara-cara berikut ini:', 'BAB III (lanjutan 25)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6852, 'perka-15-2011', 58, 'lain', 'BAB III (lanjutan 26)', NULL, 40, 'a. Membandingkan data setelah bencana dengan data sebelum bencana, terutama dengan melihat konsistensi jumlah dan perubahan yang mungkin tidak masuk akal atau menimbulkan keraguan atas keakuratannya.
b. Membandingkan dengan laporan media massa atau laporan organisasi non-pemerin tah yang kredibel.
c. Mengkonfirmasikan kepada narasumber strategis yang kredibel, misalnya institusi pemerintah dan non pemerintah yang bekerja di lokasi bencana.
d. Memeriksa peta dan foto udara. Setelah terjadi bencana, umumnya tersedia peta daerah-daerah yang terkena dampak bencana beserta intensitasnya, sehingga dapat dibandingkan kesesuaian antara data kerusakan dengan intensitas bencana masing-masing daerah.
e. Mengunjungi lapangan. Mengunjungi lapangan adalah cara yang dapat dipercaya untuk melakukan pemeriksaan silang atas informasi sekunder yang diterima, namun juga merupakan cara yang banyak membutuhkan waktu dan biaya.
D. Tahap Analisis Data
1. Pengkajian Akibat Bencana Pengkajian akibat bencana meliputi pengkajian kerusakan, pengkajian kerugian, pengkajian gangguan akses, pengkajian gangguan fungsi dan pengkajian risiko.
1.a. Penilaian Kerusakan Nilai kerusakan diperoleh dengan mengkalikan data jumlah unit fisik yang rusak dengan harga satuan yang diperoleh saat pengumpulan data primer.
Nilai Kerusakan = Jumlah Unit Fisik Rusak Menurut Tingkat Kerusakan X harga (biaya) satuan Tingkat kerusakan terdiri dari kategori rusak berat, rusak sedang, dan rusak ringan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6852, 'a. Membandingkan data setelah bencana dengan data sebelum bencana, terutama dengan melihat konsistensi jumlah dan perubahan yang mungkin tidak masuk akal atau menimbulkan keraguan atas keakuratannya.
b. Membandingkan dengan laporan media massa atau laporan organisasi non-pemerin tah yang kredibel.
c. Mengkonfirmasikan kepada narasumber strategis yang kredibel, misalnya institusi pemerintah dan non pemerintah yang bekerja di lokasi bencana.
d. Memeriksa peta dan foto udara. Setelah terjadi bencana, umumnya tersedia peta daerah-daerah yang terkena dampak bencana beserta intensitasnya, sehingga dapat dibandingkan kesesuaian antara data kerusakan dengan intensitas bencana masing-masing daerah.
e. Mengunjungi lapangan. Mengunjungi lapangan adalah cara yang dapat dipercaya untuk melakukan pemeriksaan silang atas informasi sekunder yang diterima, namun juga merupakan cara yang banyak membutuhkan waktu dan biaya.
D. Tahap Analisis Data
1. Pengkajian Akibat Bencana Pengkajian akibat bencana meliputi pengkajian kerusakan, pengkajian kerugian, pengkajian gangguan akses, pengkajian gangguan fungsi dan pengkajian risiko.
1.a. Penilaian Kerusakan Nilai kerusakan diperoleh dengan mengkalikan data jumlah unit fisik yang rusak dengan harga satuan yang diperoleh saat pengumpulan data primer.
Nilai Kerusakan = Jumlah Unit Fisik Rusak Menurut Tingkat Kerusakan X harga (biaya) satuan Tingkat kerusakan terdiri dari kategori rusak berat, rusak sedang, dan rusak ringan.', 'BAB III (lanjutan 26)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6853, 'perka-15-2011', 59, 'lain', 'BAB III (lanjutan 27)', NULL, 40, 'Masing-masing kategori memiliki kriteria tersendiri. Harga (biaya) satuan berbeda menurut tingkat kerusakannya 1.b. Penilaian Kerugian Mengidentifikasi komponen kerugian untuk masing-masing sektor dan memperkirakan nilai kerugian. Setelah nilai kerusakan diperoleh, langkah selanjutnya adalah memperkirakan nilai kerugian, dengan terlebih dahulu mengidentifikasi komponen-komponen kerugian pada masing-masing sektor. Nilai kerugian didasarkan pada asumsi-asumsi, misalnya asumsi mengenai jangka waktu pemulihan.
Analisa penilaian kerusakan dan kerugian dilakukan dengan menggunakan formulir penilaian kerusakan dan kerugian yang terdapat pada lampiran 7. Setelah melakukan pengisian formulir penilaian kerusakan dan kerugian, penting untuk memeriksa penghitungan ganda, cakupan sektoral dan rasionalitas nilai kerusakan dan kerugian.
Kotak 1. Memeriksa Penghitungan Ganda, Cakupan Sektoral dan Rasionalitas Nilai Kerusakan dan Kerugian Setelah perhitungan selesai, selanjutnya koordinator pengolahan data perlu memeriksa ulang apakah terdapat perhitungan ganda yaitu suatu nilai kerusakan dan kerugian yang dihitung dua kali oleh dua sektor yang berbeda.
Beberapa contoh perhitungan ganda:
a. Nilai kerugian sektor pertanian menggunakan harga konsumen, padahal bagian keuntungan pedangan juga dihitung dalam sektor perdagangan.
b. Kerusakan fasilitas air minum dan sanitasi dihitung sebagai bagian dari kerusakan sektor perumahan dan dihitung lagi sebagai kerusakan sektor air dan sanitasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6853, 'Masing-masing kategori memiliki kriteria tersendiri. Harga (biaya) satuan berbeda menurut tingkat kerusakannya 1.b. Penilaian Kerugian Mengidentifikasi komponen kerugian untuk masing-masing sektor dan memperkirakan nilai kerugian. Setelah nilai kerusakan diperoleh, langkah selanjutnya adalah memperkirakan nilai kerugian, dengan terlebih dahulu mengidentifikasi komponen-komponen kerugian pada masing-masing sektor. Nilai kerugian didasarkan pada asumsi-asumsi, misalnya asumsi mengenai jangka waktu pemulihan.
Analisa penilaian kerusakan dan kerugian dilakukan dengan menggunakan formulir penilaian kerusakan dan kerugian yang terdapat pada lampiran 7. Setelah melakukan pengisian formulir penilaian kerusakan dan kerugian, penting untuk memeriksa penghitungan ganda, cakupan sektoral dan rasionalitas nilai kerusakan dan kerugian.
Kotak 1. Memeriksa Penghitungan Ganda, Cakupan Sektoral dan Rasionalitas Nilai Kerusakan dan Kerugian Setelah perhitungan selesai, selanjutnya koordinator pengolahan data perlu memeriksa ulang apakah terdapat perhitungan ganda yaitu suatu nilai kerusakan dan kerugian yang dihitung dua kali oleh dua sektor yang berbeda.
Beberapa contoh perhitungan ganda:
a. Nilai kerugian sektor pertanian menggunakan harga konsumen, padahal bagian keuntungan pedangan juga dihitung dalam sektor perdagangan.
b. Kerusakan fasilitas air minum dan sanitasi dihitung sebagai bagian dari kerusakan sektor perumahan dan dihitung lagi sebagai kerusakan sektor air dan sanitasi.', 'BAB III (lanjutan 27)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6854, 'perka-15-2011', 60, 'lain', 'BAB III (lanjutan 28)', NULL, 41, 'c. Kerusakan fasilitas usaha yang menyatu dengan tempat tinggal dihitung sebagai kerusakan sektor perdagangan, sementara rumah yang di dalamnya terdapat tempat usaha telah dihitung kerusakannya dalam sektor perumahan.
Selain melakukan cek silang atas perhitungan ganda, koordinator pengolahan data melakukan cek silang apakah semua sektor sudah tercakup.
1.c. Analisis Gangguan Akses Gangguan akses terhadap kebutuhan dasar dapat dikaji melalui tabel berikut ini.
Tabel ini menggunakan komponen hak ekonomi, sosial dan budaya sebagai hak-hak dasar yang harus bisa diakses oleh masyarakat terdampak bencana. Hak-hak ini diatur dalam Undang-Undang nomor 11 tahun 2005 tentang Ratifikasi Kovenan Hak Ekonomi, Sosial dan Budaya.
Tabel 3.6 Pengkajian Gangguan Akses Komponen Akses Isu Pengkajian Gangguan Akses Hak Bekerja 1. Apakah ‘Kepala Keluarga’ dapat bekerja seperti sebelum bencana
2. Apa bentuk bantuan yang dibutuhkan:
a. Modal
b. Alat
c. Ketrampilan.
Hak Jaminan 1. Bila menghadapi keadaan darurat, apakah keluarga memiliki Keamanan Sosial sumber daya cadangan.
2. Apakah kebutuhan pemulihan sumber daya cadangan keluarga.
Hak Memperoleh 1. Perlindungan terhadap kelompok rentan:
Perlindungan & a. Perempuan Bantuan Keluarga b. Anak
c. Lansia
d. Difabel
e. KK Miskin
2. Pemenuhan kebutuhan-kebutuhan hubungan suami-istri dan keluarga.
Hak Memperoleh 1. Sandang, Taraf Baku 2. Pangan/non pangan Kehidupan Memadai 3. Papan
4. Air bersih/sanitasi
5. MCK');
