INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6856, 'perka-15-2011', 62, 'lain', 'BAB III (lanjutan 30)', NULL, 43, '4. Bagaimana keadaannya setelah bencana?
