INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6857, 'perka-15-2011', 63, 'lain', 'BAB III (lanjutan 31)', NULL, 44, '5. Mengapa harus dengan cara itu? Pada saat melakukan analisis gangguan terhadap akses, gangguan terhadap fungsi dan peningkatan risiko akibat bencana, tim terlebih dahulu melakukan pengolahan data kuesioner survey rumah tangga, dengan menggunakan formulir pada Formulir
8. Kemudian tim melakukan analisa akibat berdasarkan hasil pengolahan data survey, hasil wawancara informan kunci/diskusi kelompok terfokus dan hasil pendataan ke OPD pada formulir yang terdapat di Formulir 9.
2. Pengkajian Dampak Bencana Berbasis pada pengkajian akibat bencana, tim melakukan penilaian dampak bencana melalui diskusi kelompok terfokus dengan melibatkan para ahli maupun praktisi dengan menggunakan panduan pertanyaan pada tabel berikut ini.
Tabel 3.9. Pemaduan Substansi Rehabilitasi dan Rekonstruksi dalam Pengkajian Dampak Bencana Isu Pengkajian Dampak Komponen Ekonomi dan Fiskal 1. Bagaimana akibat-akibat bencana berdampak pada penurunan besaran-besaran ekonomi seperti produksi regional atau nasional serta pendapatan domestik regional bruto, tingkat pengangguran, tingkat inflasi, tingkat konsumsi masyarakat, angka kemiskinan, tingkat kesenjangan pendapatan, investasi, impor serta ekspor.
2. Bagaimana akibat-akibat bencana berdampak bagi penurunan terhadap kapasitas fiskal pemerintah pusat dan pemerintah daerah.
3. Bagaimana kapasitas anggaran pemerintah untuk menjalankan fungsi alokasi, distribusi dan stabilisasinya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6857, '5. Mengapa harus dengan cara itu? Pada saat melakukan analisis gangguan terhadap akses, gangguan terhadap fungsi dan peningkatan risiko akibat bencana, tim terlebih dahulu melakukan pengolahan data kuesioner survey rumah tangga, dengan menggunakan formulir pada Formulir
8. Kemudian tim melakukan analisa akibat berdasarkan hasil pengolahan data survey, hasil wawancara informan kunci/diskusi kelompok terfokus dan hasil pendataan ke OPD pada formulir yang terdapat di Formulir 9.
2. Pengkajian Dampak Bencana Berbasis pada pengkajian akibat bencana, tim melakukan penilaian dampak bencana melalui diskusi kelompok terfokus dengan melibatkan para ahli maupun praktisi dengan menggunakan panduan pertanyaan pada tabel berikut ini.
Tabel 3.9. Pemaduan Substansi Rehabilitasi dan Rekonstruksi dalam Pengkajian Dampak Bencana Isu Pengkajian Dampak Komponen Ekonomi dan Fiskal 1. Bagaimana akibat-akibat bencana berdampak pada penurunan besaran-besaran ekonomi seperti produksi regional atau nasional serta pendapatan domestik regional bruto, tingkat pengangguran, tingkat inflasi, tingkat konsumsi masyarakat, angka kemiskinan, tingkat kesenjangan pendapatan, investasi, impor serta ekspor.
2. Bagaimana akibat-akibat bencana berdampak bagi penurunan terhadap kapasitas fiskal pemerintah pusat dan pemerintah daerah.
3. Bagaimana kapasitas anggaran pemerintah untuk menjalankan fungsi alokasi, distribusi dan stabilisasinya.', 'BAB III (lanjutan 31)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6858, 'perka-15-2011', 64, 'lain', 'BAB III (lanjutan 32)', NULL, 44, 'Sosial, Budaya dan 1. Bagaimana akibat-akibat bencana pada keenam substansi Politik berdampak bagi perubahan struktur sosial dan budaya dalam jangka menengah dan panjang setelah terjadi bencana.
2. Apakah ada perubahan cara dan perilaku kehidupan sosial di masyarakat setelah bencana.
3. Apakah ada peningkatan masalah-masalah sosial setelah bencana dapat menjadi tolok ukur adanya dampak sosial akibat bencana.
4. Bagaimana akibat bencana pada keenam substansi diatas berdampak bagi perubahan struktur dan perilaku politik dalam jangka menengah dan panjang setelah terjadi bencana.
5. Apakah ada peningkatan konflik berbasis politik karena perebutan sumber daya yang menipis setelah bencana.
6. Apakah ada penurunan kepercayaan publik terhadap pemimpin yang dipilih secara demokratis karena salah kelola dalam penanganan bencana.
Pembangunan 1. Bagaimana akibat-akibat bencana pada keenam substansi Manusia berpengaruh terhadap penurunan capaian pembangunan manusia.
2. Apakah bencana berdampak bencana terhadap jumlah anak yang bisa bersekolah, jumlah perempuan dan laki-laki yang bisa bekerja, jumlah keluarga yang memiliki akses terhadap air bersih serta tingkat akses terhadap pelayanan dasar seperti pendidikan, kesehatan kependudukan dan lain-lain.
Lingkungan 1. Bagaimana akibat-akibat bencana pada keenam substansi diatas berpengaruh bagi penurunan kualitas lingkungan yang membutuhkan pemulihan dalam jangka menengah dan jangka panjang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6858, 'Sosial, Budaya dan 1. Bagaimana akibat-akibat bencana pada keenam substansi Politik berdampak bagi perubahan struktur sosial dan budaya dalam jangka menengah dan panjang setelah terjadi bencana.
2. Apakah ada perubahan cara dan perilaku kehidupan sosial di masyarakat setelah bencana.
3. Apakah ada peningkatan masalah-masalah sosial setelah bencana dapat menjadi tolok ukur adanya dampak sosial akibat bencana.
4. Bagaimana akibat bencana pada keenam substansi diatas berdampak bagi perubahan struktur dan perilaku politik dalam jangka menengah dan panjang setelah terjadi bencana.
5. Apakah ada peningkatan konflik berbasis politik karena perebutan sumber daya yang menipis setelah bencana.
6. Apakah ada penurunan kepercayaan publik terhadap pemimpin yang dipilih secara demokratis karena salah kelola dalam penanganan bencana.
Pembangunan 1. Bagaimana akibat-akibat bencana pada keenam substansi Manusia berpengaruh terhadap penurunan capaian pembangunan manusia.
2. Apakah bencana berdampak bencana terhadap jumlah anak yang bisa bersekolah, jumlah perempuan dan laki-laki yang bisa bekerja, jumlah keluarga yang memiliki akses terhadap air bersih serta tingkat akses terhadap pelayanan dasar seperti pendidikan, kesehatan kependudukan dan lain-lain.
Lingkungan 1. Bagaimana akibat-akibat bencana pada keenam substansi diatas berpengaruh bagi penurunan kualitas lingkungan yang membutuhkan pemulihan dalam jangka menengah dan jangka panjang.', 'BAB III (lanjutan 32)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6859, 'perka-15-2011', 65, 'lain', 'BAB III (lanjutan 33)', NULL, 45, '2. Apakah ada penurunan kualitas lingkungan misalnya penurunan ketersediaan sumber air bersih, kerusakan hutan dan kerusakan daerah aliran sungai serta kepunahan spesies-spesies langka setelah bencana.
3. Perkiraan Kebutuhan Pemulihan Perkiraan kebutuhan pemulihan dilakukan dengan:
a. Mengidentifikasi komponen kebutuhan kegiatan pemulihan berdasarkan hasil penilaian akibat dan dampak bencana.
b. Mengidentifikasi nilai kebutuhan atau kebutuhan biaya berdasarkan hasil penilaian akibat dan dampak bencana
c. Mengidentifikasi kebutuhan berdasarkan jangka waktu pemulihan 3.1. Identifikasi komponen kebutuhan kegiatan pemulihan Kebutuhan (needs) pemulihan adalah kegiatan-kegiatan untuk membawa kembali penduduk dan daerah terdampak menuju kondisi semula atau lebih baik lagi, serta perkiraan kebutuhan anggarannya. Identfikasi kegiatan pemulihan dilakukan berdasarkan analisis pada indikator-indikator dalam hubungan sebab-akibat.
Perkiraan kebutuhan kegiatan rehabilitasi dan rekonstruksi dapat dikelompokkan menjadi:
a. Kebutuhan perbaikan atau pembangunan kembali asset dan property yang mengalami kerusakan akibat bencana.
b. Kebutuhan penggantian kerugian sebagai akibat bencana.
c. Kebutuhan penyediaan bantuan atau dukungan akses terhadap kebutuhan dasar (Provision).
d. Kebutuhan penunjang penyelenggaraan kembali proses-proses dan fungsi-fungsi kemasyarakatan dan pemerintahan (Resumption).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6859, '2. Apakah ada penurunan kualitas lingkungan misalnya penurunan ketersediaan sumber air bersih, kerusakan hutan dan kerusakan daerah aliran sungai serta kepunahan spesies-spesies langka setelah bencana.
