INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6870, 'perka-15-2011', 76, 'lain', 'KEEMPAT : Keputusan ini berlaku sejak tanggal ditetapkan, apabila (lanjutan 1)', NULL, 54, 'Kategori Sub-Kategori Jawaban Penduduk-Wilayah Jumlah laki-laki Jumlah perempuan Jumlah rumah tangga Kesehatan Sarana Kesehatan Jumlah rumah sakit Jumlah PUSKESMAS Jumlah PUSKESMAS Pembantu Jumlah POLINDES Jumlah POSYANDU Tenaga Kesehatan Jumlah dokter Jumlah paramedis Jumlah bidan Jumlahkader kesehatan Jumlah kunjungan ke Kunjungan ke PUSKESMAS PUSKESMAS Balita Jumlah balita Jumlah balita gizi buruk Jumlah balita gizi kurang Jumlah balita ditimbang di Posyandu Manula Jumlah manula Penerima JPS Kesehatan Jumlah penerima JPS kesehatan Jumlah cakupan rumah dengan air Sanitasi bersih Jumlah cakupan rumah dengan jamban (MCK) Ekonomi Jumlah Keluarga Pra-Kondisi Keluarga Sejahtera/Miskin Jumlah Keluarga Sejahtera-1 Jumlah Penduduk Miskin Jumlah Keluarga Penerima Beras Miskin Unit Kegiatan Ekonomi Jumlah rumah tangga pertanian Jumlah rumah tangga peternak Jumlah rumah tangga perikanan Jumlah rumah tangga perkebunan Jumlah industri kecil-menengah Jumlah pedagang kecil-menengah Jumlah koperasi/lembaga ekonomi masyarakat Jumlah tempat wisata umum /tempat menarik Jumlah pasar Jumlah tambang Sosial Dan Agama Sarana Ibadah Jumlah masjid Jumlah mushola Jumlah gereja Protestan/rumah kebaktian Jumlah gereja Katolik/kapel Jumlah wihara/ sejenis Jumlah pura/sejenis Jumlah Lembaga Sosial Masyarakat Islam (termasuk Ponpes) Katolik Protestan Budha Hindu Kepercayaan Kepemudaan Adat istiadat Penyandang PMKS Jumlah penyandang PMKS Rumah Jumlah rumah permanen Jumlah rumah semi permanen Jumlah rumah');
