INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6889, 'perka-15-2011', 95, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 4)', NULL, 73, 'Format 5. Pengumpulan Data Sektor Transportasi Jenis JUMLAH KERUSAKAN Jalan/Jembatan Jenis (Dalam Km) (Jalan Jalan/jembatan HARGA Perkiraan Ruas Jalan/Nama Nasional/Kab/Ko (Aspal, Batu, SATUAN/ Biaya URAIAN Jembatan ta/Desa) Tanah) BERAT SEDANG RINGAN M2 Perbaikan PERKIRAAN KERUSAKAN a) JALAN b) JEMBATAN Jenis Kendaraan c) Kerusakan (Tambahkan Jika KENDARAAN Perlu) Jumlah Satuan Diisi dengan jumlah unit Sedan dan kendaraan Darat dan laut Minibus:……………. Unit yang rusak Bus dan Truk: Unit Tidak perlu diisi Kendaraan Berat: Unit KAPAL LAUT: Unit BUS AIR:.. Unit SPEED BOAT: Unit Perahu Klotok Unit BERAT SEDANG RINGAN TERMINAL (Lengkapi informasi dengan luasan dan tipe) Unit DERMAGA(Lengkapi KERUSAKAN informasi dengan PRASARANA luasan dan tipe) Unit TRANSPORTASI BANDARA KEHILANGAN PENDAPATAN SEKTOR TRANSPORTASI B: JUMLAH ANGKUTAN YANG KEHILANGAN TERKENA PENDAPATAN A. PENDAPATAN DAMPAK:
ANGKUTAN DARAT PER HARI:…..RP Buah B: JUMLAH ANGKUTAN KEHILANGAN YANG PENDAPATAN TERKENA ANGKUTAN A. PENDAPATAN DAMPAK:
LAUT/SUNGAI PER HARI:…..RP Buah B: JUMLAH ANGKUTAN YANG KEHILANGAN TERKENA Tidak Perlu Diisi PENDAPATAN A. PENDAPATAN DAMPAK:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6889, 'Format 5. Pengumpulan Data Sektor Transportasi Jenis JUMLAH KERUSAKAN Jalan/Jembatan Jenis (Dalam Km) (Jalan Jalan/jembatan HARGA Perkiraan Ruas Jalan/Nama Nasional/Kab/Ko (Aspal, Batu, SATUAN/ Biaya URAIAN Jembatan ta/Desa) Tanah) BERAT SEDANG RINGAN M2 Perbaikan PERKIRAAN KERUSAKAN a) JALAN b) JEMBATAN Jenis Kendaraan c) Kerusakan (Tambahkan Jika KENDARAAN Perlu) Jumlah Satuan Diisi dengan jumlah unit Sedan dan kendaraan Darat dan laut Minibus:……………. Unit yang rusak Bus dan Truk: Unit Tidak perlu diisi Kendaraan Berat: Unit KAPAL LAUT: Unit BUS AIR:.. Unit SPEED BOAT: Unit Perahu Klotok Unit BERAT SEDANG RINGAN TERMINAL (Lengkapi informasi dengan luasan dan tipe) Unit DERMAGA(Lengkapi KERUSAKAN informasi dengan PRASARANA luasan dan tipe) Unit TRANSPORTASI BANDARA KEHILANGAN PENDAPATAN SEKTOR TRANSPORTASI B: JUMLAH ANGKUTAN YANG KEHILANGAN TERKENA PENDAPATAN A. PENDAPATAN DAMPAK:
ANGKUTAN DARAT PER HARI:…..RP Buah B: JUMLAH ANGKUTAN KEHILANGAN YANG PENDAPATAN TERKENA ANGKUTAN A. PENDAPATAN DAMPAK:
LAUT/SUNGAI PER HARI:…..RP Buah B: JUMLAH ANGKUTAN YANG KEHILANGAN TERKENA Tidak Perlu Diisi PENDAPATAN A. PENDAPATAN DAMPAK:', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 4)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6890, 'perka-15-2011', 96, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 5)', NULL, 75, 'ANGKUTAN UDARA PER HARI:…..RP Buah KEHILANGAN A. PENDAPATAN PENDAPATAN PER TERMINAL HARI:………...RP KEHILANGAN A. PENDAPATAN PENDAPATAN PER DERMAGA HARI:………...RP A. PENDAPATAN KEHILANGAN PER PENDAPATAN BANDARA HARI:………...RP KENAIKAN BIAYA A. BIAYA OPERASIONAL OPERASIONAL KENDARAAN AKIBAT KENDARAAN PENGGUNAAN JALAN SEBELUM YANG RUSAK BENCANA B. BIAYA OPERASIONAL KENDARAAN SETELAH BENCANA C. JUMLAH KENDARAAN BIAYA PEMASANGAN TERDAMPAK INFRASTRUKTUR A. JUMLAH UNIT DARURAT (Misalnya: TERDAMPAK Jembatan Bailey) B. BIAYA PER UNIT Format 7. SEKTOR LISTRIK Jumlah Kerusakan Harga URAIAN KOMPONEN Satuan Unit Satuan PERKIRAAN KERUSAKAN a) SISTEM TRANSMISI DAN DISTRIBUSI KABEL TIANG GARDU b) SISTEM PEMBANGKITAN PLTA PLTU PLTD PEMBANGKIT LAIN-LAIN…..KETERANGAN Perkiraan JANGKA WAKTU PEMULIHAN …..BULAN PEMBANGKIT LISTRIK DARURAT Genset ………Unit Biaya Pengadaan Per Genset ………Rp PERKIRAAN KEHILANGAN/PENURUNAN PENDAPATAN B. PERMINTAAN LISTRIK PER BULAN SEBELUM Tidak Perlu BENCANA Kwh Diisi C. PERMINTAAN LISTRIK PER BULAN PASCA BENCANA Kwh D. TARIF LISTRIK/KWH Rp E. PENURUNAN PENDAPATAN: (B-C)*D*A PERKIRAAN KENAIKAN BIAYA OPERASIONAL B. BIAYA OPERASIONAL PER BULAN SEBELUM BENCANA…… Rp C. BIAYA OPERASIONAL PER BULAN PASCA BENCANA….. Rp D. KENAIKAN BIAYA OPERASIONAL: (C-B)*A Format 8. SEKTOR TELKOM KABUPATEN Jumlah Harga URAIAN KOMPONEN Satuan Unit Satuan PERKIRAAN KERUSAKAN KERUSAKAN SARANA DAN PARASARANA PERKIRAAN KERUGIAN Perkiraan JANGKA WAKTU PEMULIHAN A.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6890, 'ANGKUTAN UDARA PER HARI:…..RP Buah KEHILANGAN A. PENDAPATAN PENDAPATAN PER TERMINAL HARI:………...RP KEHILANGAN A. PENDAPATAN PENDAPATAN PER DERMAGA HARI:………...RP A. PENDAPATAN KEHILANGAN PER PENDAPATAN BANDARA HARI:………...RP KENAIKAN BIAYA A. BIAYA OPERASIONAL OPERASIONAL KENDARAAN AKIBAT KENDARAAN PENGGUNAAN JALAN SEBELUM YANG RUSAK BENCANA B. BIAYA OPERASIONAL KENDARAAN SETELAH BENCANA C. JUMLAH KENDARAAN BIAYA PEMASANGAN TERDAMPAK INFRASTRUKTUR A. JUMLAH UNIT DARURAT (Misalnya: TERDAMPAK Jembatan Bailey) B. BIAYA PER UNIT Format 7. SEKTOR LISTRIK Jumlah Kerusakan Harga URAIAN KOMPONEN Satuan Unit Satuan PERKIRAAN KERUSAKAN a) SISTEM TRANSMISI DAN DISTRIBUSI KABEL TIANG GARDU b) SISTEM PEMBANGKITAN PLTA PLTU PLTD PEMBANGKIT LAIN-LAIN…..KETERANGAN Perkiraan JANGKA WAKTU PEMULIHAN …..BULAN PEMBANGKIT LISTRIK DARURAT Genset ………Unit Biaya Pengadaan Per Genset ………Rp PERKIRAAN KEHILANGAN/PENURUNAN PENDAPATAN B. PERMINTAAN LISTRIK PER BULAN SEBELUM Tidak Perlu BENCANA Kwh Diisi C. PERMINTAAN LISTRIK PER BULAN PASCA BENCANA Kwh D. TARIF LISTRIK/KWH Rp E. PENURUNAN PENDAPATAN: (B-C)*D*A PERKIRAAN KENAIKAN BIAYA OPERASIONAL B. BIAYA OPERASIONAL PER BULAN SEBELUM BENCANA…… Rp C. BIAYA OPERASIONAL PER BULAN PASCA BENCANA….. Rp D. KENAIKAN BIAYA OPERASIONAL: (C-B)*A Format 8. SEKTOR TELKOM KABUPATEN Jumlah Harga URAIAN KOMPONEN Satuan Unit Satuan PERKIRAAN KERUSAKAN KERUSAKAN SARANA DAN PARASARANA PERKIRAAN KERUGIAN Perkiraan JANGKA WAKTU PEMULIHAN A.', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 5)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6891, 'perka-15-2011', 97, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 6)', NULL, 75, '…..BULAN PERKIRAAN KEHILANGAN/PENURUNAN PENDAPATAN B. PERMINTAAN TELEKOMUNIKASI PER BULAN SEBELUM BENCANA C. PERMINTAAN TELEKOMUNIKASI PER BULAN PASCA BENCANA D. TARIF E. PENURUNAN PENDAPATAN: (B-C)*D*A PERKIRAAN KENAIKAN BIAYA OPERASIONAL B. BIAYA OPERASIONAL PER BULAN SEBELUM BENCANA…… C. BIAYA OPERASIONAL PER BULAN PASCA BENCANA…..
D. KENAIKAN BIAYA OPERASIONAL: (C-B)*A FORMAT 9: SEKTOR PERTANIAN/PERKEBUNAN NAMA KAMPUNG: NAMA DISTRIK:
Luasan Kerusakan Harga tanaman, dalam Umur Tanaman Panen Per Jenis Tanaman hektar Saat Bencana Kg Perkiraan Kerusakan a)Kerusakan Lahan Pertanian b) Kerusakan Bibit & Tanaman Perkiraan Luasan Luas Tanam Biaya c) Sarana irigasi Jenis Jaringan Kerusakan Terdampak Perbaikan Jaringan Primer:
Jaringan Tersier:
Jaringan Irigasi Desa:
Rusak Mesin dan Bangunan Harga Satuan Rusak Berat Rusak Sedang Ringan d) Mesin-mesin pertanian dan peralatan e) Kerusakan gudang dan bangunan lainnya Harga Luasan Panen Per a) Produksi yang Hilang Total Jenis Tanaman Tanaman Produktivitas/ha Kg Jangka Selisih Harga waktu Luasan Penurunan Panen Per Penurunan b) Penurunan Produksi Jenis Tanaman Tanaman Produktivitas Kg Produktivitas Selisih Kenaikan Luasan Ongkos c) Kenaikan Ongkos Produksi Jenis Tanaman Tanaman Produksi Tidak Perlu Diisi FORMAT 11: SEKTOR PETERNAKAN NAMA KAMPUNG: NAMA DISTRIK:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6891, '…..BULAN PERKIRAAN KEHILANGAN/PENURUNAN PENDAPATAN B. PERMINTAAN TELEKOMUNIKASI PER BULAN SEBELUM BENCANA C. PERMINTAAN TELEKOMUNIKASI PER BULAN PASCA BENCANA D. TARIF E. PENURUNAN PENDAPATAN: (B-C)*D*A PERKIRAAN KENAIKAN BIAYA OPERASIONAL B. BIAYA OPERASIONAL PER BULAN SEBELUM BENCANA…… C. BIAYA OPERASIONAL PER BULAN PASCA BENCANA…..
D. KENAIKAN BIAYA OPERASIONAL: (C-B)*A FORMAT 9: SEKTOR PERTANIAN/PERKEBUNAN NAMA KAMPUNG: NAMA DISTRIK:
Luasan Kerusakan Harga tanaman, dalam Umur Tanaman Panen Per Jenis Tanaman hektar Saat Bencana Kg Perkiraan Kerusakan a)Kerusakan Lahan Pertanian b) Kerusakan Bibit & Tanaman Perkiraan Luasan Luas Tanam Biaya c) Sarana irigasi Jenis Jaringan Kerusakan Terdampak Perbaikan Jaringan Primer:
Jaringan Tersier:
Jaringan Irigasi Desa:
Rusak Mesin dan Bangunan Harga Satuan Rusak Berat Rusak Sedang Ringan d) Mesin-mesin pertanian dan peralatan e) Kerusakan gudang dan bangunan lainnya Harga Luasan Panen Per a) Produksi yang Hilang Total Jenis Tanaman Tanaman Produktivitas/ha Kg Jangka Selisih Harga waktu Luasan Penurunan Panen Per Penurunan b) Penurunan Produksi Jenis Tanaman Tanaman Produktivitas Kg Produktivitas Selisih Kenaikan Luasan Ongkos c) Kenaikan Ongkos Produksi Jenis Tanaman Tanaman Produksi Tidak Perlu Diisi FORMAT 11: SEKTOR PETERNAKAN NAMA KAMPUNG: NAMA DISTRIK:', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 6)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
