INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6895, 'perka-15-2011', 101, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 10)', NULL, 90, 'KETERANGAN TINGKAT KERUSAKAN HARGA SATUAN Jenis Kerusakan RB RS RR RB RS RR Perkiraan Kerusakan a) Ekosistem Darat b) Ekosistem Laut c) Ekosistem Udara Perkiraan Kerugian a) Kehilangan Jasa Lingkungan Dasar Perhitungan b) Biaya akibat Pencemaran Air Dasar Perhitungan c) Biaya Pencemaran Udara Dasar Perhitungan Formulir 05 Kategori Kerusakan Akibat Bencana Masing-Masing Sektor
1. Sektor Perumahan Kriteria Kerusakan Bangunan Akibat Bencana No Kategori Kriteria Uraian Penjelasan . Kerusakan Kerusakan  Secara fisik kondisi kerusakan >70%  Bangunan roboh total  Sebagian besar struktur utama bangunan rusak;
Bangunan roboh  Sebagian besar dinding dan lantai bangunan Rusak atau sebagian besar patah/retak;
I Berat komponen rusak  Komponen penunjang lainnya rusak total;
(RB)  Membahayakan/berisiko difungsikan  Perbaikan dengan rekonstruksi  Secara fisik kerusakan 30% - 70%  Bangunan masih berdiri Bangunan masih  Sebagian kecil struktur utama bangunan berdiri, sebagian rusak; kecil komponen Rusak  Sebagian besarkomponen penunjang lainnya struktur rusak, dan II Sedang rusak; komponen (RS)  Relatif masih berfungsi penunjangnya rusak  Perbaikan dengan rehabilitasi  Secara fisik kerusakan <30%  Bangunan masih berdiri;  Sebagian kecil struktur bangunan rusak Bangunan masih ringan; berdiri, sebagian  Retak-retak pada dinding plesteran;
Rusak komponen struktur  Sebagian kecil komponen penunjang lainnya III Ringan retak (struktur masih rusak;');
