INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6911, 'perka-15-2011', 117, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 26)', NULL, 103, 'Pendapatan suami : ................ bidang:........
Pendapatan istri : .....................bidang :..........
Pendapatan anggota keluarga lainnya:............. bidang:.............
Ketentuan:
Masing-masing pewawancara memiliki komposisi responden sebagai berikut:  50% responden dengan penghasilan keluarga per bulan kurang dari satu juta rupiah  30% responden dengan penghasilan keluarga per bulan satu juta sampai dengan dua juta setengah.  20% responden dengan penghasilan keluarga per bulan lebih dari dua setengah juta.  50% responden adalah perempuan Formulir 07 Diskusi Kelompok Terfokus FGD membantu pengumpulan data kualitatif yang memberikan gambaran tentang masalah-masalah yang tidak tertampung dalam laporan statistic maupun survey.
FGD memungkinkan kita untuk mendapatkan gambaran pemikiran masyarakat tentang pemulihan dini. Silakan laksanakan FGD secara informal, singkat dan efektif.
Salah satu kuncinya adalah melalui perencanaan sesi FGD yang lebih baik dan perekaman yang teliti walau tidak harus rinci.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6911, 'Pendapatan suami : ................ bidang:........
Pendapatan istri : .....................bidang :..........
Pendapatan anggota keluarga lainnya:............. bidang:.............
Ketentuan:
Masing-masing pewawancara memiliki komposisi responden sebagai berikut:  50% responden dengan penghasilan keluarga per bulan kurang dari satu juta rupiah  30% responden dengan penghasilan keluarga per bulan satu juta sampai dengan dua juta setengah.  20% responden dengan penghasilan keluarga per bulan lebih dari dua setengah juta.  50% responden adalah perempuan Formulir 07 Diskusi Kelompok Terfokus FGD membantu pengumpulan data kualitatif yang memberikan gambaran tentang masalah-masalah yang tidak tertampung dalam laporan statistic maupun survey.
FGD memungkinkan kita untuk mendapatkan gambaran pemikiran masyarakat tentang pemulihan dini. Silakan laksanakan FGD secara informal, singkat dan efektif.
Salah satu kuncinya adalah melalui perencanaan sesi FGD yang lebih baik dan perekaman yang teliti walau tidak harus rinci.', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 26)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6912, 'perka-15-2011', 118, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 27)', NULL, 104, 'UMUM Desa/kelurahan asal:__________________ Kecamatan asal :___________________ Kabupaten asal:___________________________ Tanggal :______________________ Km dari Bencana: _____________________ (diisi oleh fasilitator/pencatat) Tempat sesi :___________________Desa/kel:_______________Kec: ________________ Jumlah peserta:_________ (perempuan: _________ laki-laki: __________) Gambaran komposisi peserta, misalnya pekerjaan, status sosial, kelompok umur, dsb. ______________________________________________________________________________ ______________________________________________________________________________ Penyelenggara Paraf Fasilitator:_________________________ _____________________ pencatat: _________________________ _____________________ Checklist Persiapan
1. Persiapan pra-FGD:  Ya  Tidak
2. Pembagian tugas pelaksana  Ya  Tidak
3. Perkenalan dan pengantar  Ya  Tidak
