INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6915, 'perka-15-2011', 121, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 30)', NULL, 106, '5. Mengapa harus dengan cara itu? Formulir 08 Formulir Pengolahan dan Analisis Data Penilaian Kerusakan dan Kerugian Data Harga Satuan Nilai Kerusakan Komponen Kerusakan (Rp.) (Damage) Perkiraan Sektor/Sub Kerusakan No Kerusakan Lokasi Kerugian Kebutuhan Sektor + Kerugian dan kerugian (Losses) RB RS RR RB RS RR RB RS RR Jumlah Total Formulir 09 Pengolahan Data dan Kuesioner No Pertanyaan Kategori jawaban Nomor Kuesioner* Jumlah*** Persentase**** 1 2 3 … … … … a Jenis kelamin responden Laki2 ** … … … Perempuan … b Umur ≤ 20 th … 21th – 30th 31th – 40th 41th – 50th > 50th c Desa/kelurahan (Isi nama desa/kelurahan) d Kecamatan (Isi nama kecamatan) e Kabupaten (Isi nama kabupaten) f Pendidikan terakhir SD SLTP SLTA PT g Apakah responden kepala Ya Rumah Tangga Perempuan Tidak h Jumlah anggota keluarga ≤3 3–5 >5 i Jumlah anak (di bwh 18th) 1 2 3 >3 g Jumlah anak balita 1 2 3 >3 h Tipe hunian sekarang Rumah tinggal sendiri Rumah tumpangan Pengungsian Fasilitas umum Lain-lain 1 Sebelum bencana, siapa Suami sajakah pencari nafkah keluarga? (bisa pilih lebih dari satu) Istri Anak (<18 tahun) Lainnya 2 Setelah bencana, siapa Suami pencari nafkah keluarga yang masih bekerja? (bisa pilih lebih dari satu) Istri Anak (<18 tahun) Lainnya 3 Sebutkan tiga sumber utama Pertanian penghasilan keluarga sebelum bencana? Peternakan Perdagangan Industri Jasa Pegawai Pertukangan Nelayan 4 Adakah sumber penghasilan Ada keluarga yang hilang/menurun setelah bencana? Tidak 5 Sebutkan satu bantuan yang');
