INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6919, 'perka-15-2011', 125, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 34)', NULL, 117, 'Rp 500.000 – Rp 1.500.000 Rp 1.500.000 – Rp 2.500.000 > Rp 2.500.000 Petunjuk Pengisian: * Isi nomor kuesioner yang sedang diolah datanya ** Isi 1 bila kategori jawaban dipilih oleh responden (kategori jawaban dilingkari atau disilang) Isi 0 bila kategori jawaban tidak dipilih oleh responden (kategori jawaban tidak dilingkari atau disilang) *** Isi jumlah dari tiap kategori jawaban responden. **** Isi persentase dari jumlah tiap kategori jawaban responden terhadap jumlah total jawaban responden pada satu pertanyaan yang sama Formulir 10 Analisa Data Akibat terhadap Akses, Fungsi dan Resiko, serta Analisa Kebutuhan Pemulihan Akibat terhadap akses, fungsi dan resiko Kebutuhan-kegiatan No Sektor-sub.sektor Lokasi Point penting Point penting hasil Point penting hasil pemulihan hasil pengolahan wawancara/FGD pendataan ke SKPD data survey 1 Perumahan Analisa kebutuhan pemulihan pada tiap-tiap sektor/sub-sektor dengan melihat pada akibat yang 2 Infrastuktur telah diidentifikasi ! Transportasi Energi dll 3 Ekonomi Produktif Pertanian Peternakan Perikanan dll 4 Sosial Pendidikan Kesehatan Agama Budaya dll.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6919, 'Rp 500.000 – Rp 1.500.000 Rp 1.500.000 – Rp 2.500.000 > Rp 2.500.000 Petunjuk Pengisian: * Isi nomor kuesioner yang sedang diolah datanya ** Isi 1 bila kategori jawaban dipilih oleh responden (kategori jawaban dilingkari atau disilang) Isi 0 bila kategori jawaban tidak dipilih oleh responden (kategori jawaban tidak dilingkari atau disilang) *** Isi jumlah dari tiap kategori jawaban responden. **** Isi persentase dari jumlah tiap kategori jawaban responden terhadap jumlah total jawaban responden pada satu pertanyaan yang sama Formulir 10 Analisa Data Akibat terhadap Akses, Fungsi dan Resiko, serta Analisa Kebutuhan Pemulihan Akibat terhadap akses, fungsi dan resiko Kebutuhan-kegiatan No Sektor-sub.sektor Lokasi Point penting Point penting hasil Point penting hasil pemulihan hasil pengolahan wawancara/FGD pendataan ke SKPD data survey 1 Perumahan Analisa kebutuhan pemulihan pada tiap-tiap sektor/sub-sektor dengan melihat pada akibat yang 2 Infrastuktur telah diidentifikasi ! Transportasi Energi dll 3 Ekonomi Produktif Pertanian Peternakan Perikanan dll 4 Sosial Pendidikan Kesehatan Agama Budaya dll.', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 34)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6920, 'perka-15-2011', 126, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 35)', NULL, 118, '5 Lintas sektor Pemerintahan Lingkungan hidup dll Jumlah Kebutuhan Formulir 11 Rekapitulasi Kebutuhan Pascabencana (PDNA) Komponen Harga Sektor Kegiatan Lokasi Volume Jumlah Keterangan Kebutuhan Satuan Pembangunan Penggantian Perumahan & Penyediaan Bantuan Pemukiman Pemulihan Fungsi Pengurangan Resiko Pembangunan Infrastruktur Penggantian Penyediaan Bantuan Pemulihan Fungsi Pengurangan Resiko Pembangunan Penggantian Ekonomi Produktif Penyediaan Bantuan Pemulihan Fungsi Pengurangan Resiko Pembangunan Sosial Penggantian Penyediaan Bantuan Pemulihan Fungsi Pengurangan Resiko Pembangunan Penggantian Lintas Sektor Penyediaan Bantuan Pemulihan Fungsi Pengurangan Resiko Formulir 12 Standar Penyusunan Kegiatan dan Anggaran untuk PKPB Pengkajian Kebutuhan Pascabencana/ Post Disaster Needs Assessment (PDNA) diantaranya adalah berisi tentang perkiraan kerugian akibat bencana, kebutuhan pemulihan pascabencana, termasuk pula perkiraan anggaran (budget). Penganggaran (budgeting) sebagai bentuk kegiatan yang sangat penting disusun untuk mendukung perkiraan kebutuhan anggaran untuk pemulihan pascabencana. Model penganggaran yang disusun dalam kontek ini bersifat umum (general) dengan batasan-batasan tertentu, sehingga dapat digunakan dalam waktu relatif cepat. Model penganggaran (budgeting) tersebut dirancang dengan sejumlah asumsi yang mendasarinya, sehingga harus digunakan secara tepat dan bijak. Tulisan ini berfungsi sebagai pedoman penganggaran yang terdiri dari tiga bagian yaitu:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6920, '5 Lintas sektor Pemerintahan Lingkungan hidup dll Jumlah Kebutuhan Formulir 11 Rekapitulasi Kebutuhan Pascabencana (PDNA) Komponen Harga Sektor Kegiatan Lokasi Volume Jumlah Keterangan Kebutuhan Satuan Pembangunan Penggantian Perumahan & Penyediaan Bantuan Pemukiman Pemulihan Fungsi Pengurangan Resiko Pembangunan Infrastruktur Penggantian Penyediaan Bantuan Pemulihan Fungsi Pengurangan Resiko Pembangunan Penggantian Ekonomi Produktif Penyediaan Bantuan Pemulihan Fungsi Pengurangan Resiko Pembangunan Sosial Penggantian Penyediaan Bantuan Pemulihan Fungsi Pengurangan Resiko Pembangunan Penggantian Lintas Sektor Penyediaan Bantuan Pemulihan Fungsi Pengurangan Resiko Formulir 12 Standar Penyusunan Kegiatan dan Anggaran untuk PKPB Pengkajian Kebutuhan Pascabencana/ Post Disaster Needs Assessment (PDNA) diantaranya adalah berisi tentang perkiraan kerugian akibat bencana, kebutuhan pemulihan pascabencana, termasuk pula perkiraan anggaran (budget). Penganggaran (budgeting) sebagai bentuk kegiatan yang sangat penting disusun untuk mendukung perkiraan kebutuhan anggaran untuk pemulihan pascabencana. Model penganggaran yang disusun dalam kontek ini bersifat umum (general) dengan batasan-batasan tertentu, sehingga dapat digunakan dalam waktu relatif cepat. Model penganggaran (budgeting) tersebut dirancang dengan sejumlah asumsi yang mendasarinya, sehingga harus digunakan secara tepat dan bijak. Tulisan ini berfungsi sebagai pedoman penganggaran yang terdiri dari tiga bagian yaitu:', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 35)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6921, 'perka-15-2011', 127, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 36)', NULL, 122, '1. Konsep dan Metode: menguraikan kerangka pikir dan kebutuhan penganggaran makro (estimasi) dalam penyusunan Pengkajian Kebutuhan Pascabencana
2. Tabel Satuan Biaya dan Cara Penggunaanya : menampilkan jenis-jenis kegiatan menurut sektor dalam Pengkajian Kebutuhan Pascabencana, satuan biaya, indeks perbedaan harga antar wilayah serta teknik penggunaannya.
3. Pemutakhiran : menguraikan prosedur yang perlu dilakukan untuk menyesuaikan tabel satuan biaya agar sesuai dengan kondisi terkini.
A. KONSEP DAN METODE Konsep Model penganggaran makro (macro budgeting model) adalah suatu pilihan bentuk-bentuk kegiatan umum dan perkiraan anggarannya untuk melakukan rekonstruksi dan rehabilitasi pascabencana.
Model tersebut dipandang sangat penting dalam penyusunan Pengkajian Kebutuhan Pascabencana (PDNA) adalah karena pertimbangan kecepatan respon, keterbatasan sumber daya dan implikasinya dalam merencanakan rekonstruksi dan rehabilitasi.
Penjelasan atas pertimbangan tersebut antara lain;
1. Pertimbangan kecepatan respon: perkiraan kebutuhan pemulihan pascabencana menunjukkan tanggungjawab pemerintah, solidaritas kemanusiaan dan kebangsaan.
Karena itu pemerintah (menurut tingkat intensitas bencananya) harus segera berkonsolidasi dan berkoordinasi dengan stakeholders kebencanaan untuk melaksanakan upaya-upaya pemulihan pascabencana. Untuk itu diperlukan perkiraan kebutuhan-kebutuhan kegiatan beserta perkiraan anggaran dalam waktu cepat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6921, '1. Konsep dan Metode: menguraikan kerangka pikir dan kebutuhan penganggaran makro (estimasi) dalam penyusunan Pengkajian Kebutuhan Pascabencana
2. Tabel Satuan Biaya dan Cara Penggunaanya : menampilkan jenis-jenis kegiatan menurut sektor dalam Pengkajian Kebutuhan Pascabencana, satuan biaya, indeks perbedaan harga antar wilayah serta teknik penggunaannya.
3. Pemutakhiran : menguraikan prosedur yang perlu dilakukan untuk menyesuaikan tabel satuan biaya agar sesuai dengan kondisi terkini.
A. KONSEP DAN METODE Konsep Model penganggaran makro (macro budgeting model) adalah suatu pilihan bentuk-bentuk kegiatan umum dan perkiraan anggarannya untuk melakukan rekonstruksi dan rehabilitasi pascabencana.
Model tersebut dipandang sangat penting dalam penyusunan Pengkajian Kebutuhan Pascabencana (PDNA) adalah karena pertimbangan kecepatan respon, keterbatasan sumber daya dan implikasinya dalam merencanakan rekonstruksi dan rehabilitasi.
Penjelasan atas pertimbangan tersebut antara lain;
1. Pertimbangan kecepatan respon: perkiraan kebutuhan pemulihan pascabencana menunjukkan tanggungjawab pemerintah, solidaritas kemanusiaan dan kebangsaan.
Karena itu pemerintah (menurut tingkat intensitas bencananya) harus segera berkonsolidasi dan berkoordinasi dengan stakeholders kebencanaan untuk melaksanakan upaya-upaya pemulihan pascabencana. Untuk itu diperlukan perkiraan kebutuhan-kebutuhan kegiatan beserta perkiraan anggaran dalam waktu cepat.', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 36)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6922, 'perka-15-2011', 128, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 37)', NULL, 122, '2. Pertimbangan keterbatasan sumber daya: dalam situasi waktu kejadian bencana yang berdekatan atau bersamaan, maka kecepatan penyusunan PDNA dapat mengalami masalah keterbatasan waktu dan SDM. Hal ini juga akan memperlambat respon penanganan dampak bencana di wilayah tersebut.
3. Pertimbangan implikasi. Apabila metode penyusunan relatif kurang terstandar, maka hal tersebut dapat menimbulkan alokasi anggaran yang kurang adil (improper budget allocation) antar daerah yang terjadi bencana.
Walaupun manfaat model tersebut diperkirakan cukup besar, namun dalam mewujudkannya ditemui sejumlah masalah dan hambatan. Diantaranya adalah;
1. Jenis kegiatan pemulihan pasca sangat bervariasi dari aspek fisik sarana dan prasarana, kemanusiaan, jenis bencana, karakteristik lokasi dan lain sebagainya.
2. Wilayah Indonesia sangat luas dan berbentuk kepulauan yang menyebar dengan tingkat ketersediaan sarana dan prasarana yang berbeda-beda, sehingga biaya pelaksanaan kegiatan sangat mungkin berbeda-beda menurut wilayah.
3. Belum ada ketetapan atau rujukan biaya satuan dalam proses penganggaran untuk bentuk-bentuk kegiatan dimaksud yang bersifat umum. Kalaupun ada terkadang umumnya tidak teritengrasi atau bersifat khusus. Keterbatasan informasi detil tentang biaya pelaksanaan kegiatan di suatu wilayah semakin meningkatkan subyektifitas proses penganggaran');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6922, '2. Pertimbangan keterbatasan sumber daya: dalam situasi waktu kejadian bencana yang berdekatan atau bersamaan, maka kecepatan penyusunan PDNA dapat mengalami masalah keterbatasan waktu dan SDM. Hal ini juga akan memperlambat respon penanganan dampak bencana di wilayah tersebut.
3. Pertimbangan implikasi. Apabila metode penyusunan relatif kurang terstandar, maka hal tersebut dapat menimbulkan alokasi anggaran yang kurang adil (improper budget allocation) antar daerah yang terjadi bencana.
Walaupun manfaat model tersebut diperkirakan cukup besar, namun dalam mewujudkannya ditemui sejumlah masalah dan hambatan. Diantaranya adalah;
1. Jenis kegiatan pemulihan pasca sangat bervariasi dari aspek fisik sarana dan prasarana, kemanusiaan, jenis bencana, karakteristik lokasi dan lain sebagainya.
2. Wilayah Indonesia sangat luas dan berbentuk kepulauan yang menyebar dengan tingkat ketersediaan sarana dan prasarana yang berbeda-beda, sehingga biaya pelaksanaan kegiatan sangat mungkin berbeda-beda menurut wilayah.
3. Belum ada ketetapan atau rujukan biaya satuan dalam proses penganggaran untuk bentuk-bentuk kegiatan dimaksud yang bersifat umum. Kalaupun ada terkadang umumnya tidak teritengrasi atau bersifat khusus. Keterbatasan informasi detil tentang biaya pelaksanaan kegiatan di suatu wilayah semakin meningkatkan subyektifitas proses penganggaran', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 37)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6923, 'perka-15-2011', 129, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 38)', NULL, 123, '4. Proses penetapan kegiatan dan penganggaran untuk rencana aksi pascabencana yang dilakukan selama ini menuntut ketersediaan sumber daya manusia dengan kapasitas dan pengalaman yang relatif tinggi serta memerlukan waktu yang cukup lama.
Permasalahan ini makin meningkat lagi bila terjadi bencana yang berdekatan waktunya.
Penempatan model penganggaran makro dalam alur perencanaan dan pelaksanaan kegiatan pemulihan pascabencana tampak pada gambar berikut ini.
Gambar 1. Penganggaran Makro Dalam Pemulihan Pascabencana TAHAP PENYUSUNAN PDNA Perkiraan Daftar JUMLAH INDIKASI SASARAN KEGIATAN P S kt P S kt Indeks Kemahalan Biaya Satuan Wilayah per Kegiatan ESTIMASI ANGGARAN PER SEKTOR PROSES TAHAP PEMANFAATAN PENYESUAIAN (Budget sebagai Ancar-Ancar Anggaran Renaksi) PDNA RENCANA PELAKSANAAN Pendetilan Budget Sesuai Kondisi Lapangan Berdasarkan survey PDNA, kemudian diterapkan model penganggaran berdasarkan Indikasi Kegiatan dan Jumlah Sasaran per sektor. Jenis kegiatan mengacu pada kebutuhan kegiatan yang relatif bersifat umum. Berdasarkan jenis kegiatan dan lokasi bencananya, kemudian dipilih biaya satuan yang sesuai serta daerah lokasi bencananya.
Hasil perkalian antara jumlah sasaran, biaya satuan dan lokasi (tabel konversi lokasi) adalah merupakan perkiraan (estimasi) anggaran untuk kebutuhan pemulihan pascabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6923, '4. Proses penetapan kegiatan dan penganggaran untuk rencana aksi pascabencana yang dilakukan selama ini menuntut ketersediaan sumber daya manusia dengan kapasitas dan pengalaman yang relatif tinggi serta memerlukan waktu yang cukup lama.
Permasalahan ini makin meningkat lagi bila terjadi bencana yang berdekatan waktunya.
Penempatan model penganggaran makro dalam alur perencanaan dan pelaksanaan kegiatan pemulihan pascabencana tampak pada gambar berikut ini.
Gambar 1. Penganggaran Makro Dalam Pemulihan Pascabencana TAHAP PENYUSUNAN PDNA Perkiraan Daftar JUMLAH INDIKASI SASARAN KEGIATAN P S kt P S kt Indeks Kemahalan Biaya Satuan Wilayah per Kegiatan ESTIMASI ANGGARAN PER SEKTOR PROSES TAHAP PEMANFAATAN PENYESUAIAN (Budget sebagai Ancar-Ancar Anggaran Renaksi) PDNA RENCANA PELAKSANAAN Pendetilan Budget Sesuai Kondisi Lapangan Berdasarkan survey PDNA, kemudian diterapkan model penganggaran berdasarkan Indikasi Kegiatan dan Jumlah Sasaran per sektor. Jenis kegiatan mengacu pada kebutuhan kegiatan yang relatif bersifat umum. Berdasarkan jenis kegiatan dan lokasi bencananya, kemudian dipilih biaya satuan yang sesuai serta daerah lokasi bencananya.
Hasil perkalian antara jumlah sasaran, biaya satuan dan lokasi (tabel konversi lokasi) adalah merupakan perkiraan (estimasi) anggaran untuk kebutuhan pemulihan pascabencana.', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 38)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6924, 'perka-15-2011', 130, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 39)', NULL, 124, 'Anggaran tersebut bersifat makro, atau berfungsi sebagai ancar-ancar (plafon) anggaran, sehingga pada saat rencana pelaksanaan disusun, diperlukan perincian anggaran (budget). Anggaran tersebut juga bersifat lokal, artinya tidak mempertimbangkan biaya-biaya pelaku atau sumber daya yang dari wilayah lain, karena variabilitasnya yang sangat tinggi.
Selanjutnya perlu disusun detil budget oleh pelaksana (pelaku) dengan mempertimbangkan kondisi lapangan (rentang wilayah), ketersediaan sumber daya manusia, aksesibilitas dan lain sebagainya.
Karakteristik Model Dalam lingkup pemulihan pascabencana dan dengan mempertimbangkan kebutuhan serta masalah dan hambatan, maka disusun model penganggaran makro yang memiliki ciri-ciri berikut:
• Quick; menyediakan alternatif daftar kegiatan dan estimasi kebutuhan anggarannya dalam waktu relatif cepat sehingga segera dapat dimanfaatkan untuk perencanaan maupun mengetahui profil kebutuhan pemulihan pascabencana.
• General; alternatif-alternatif kegiatan yang tersedia bersifat umum (general), yaitu standar/metode pelaksanaannya relatif sama pada wilayah yang berbeda-beda. Namun demikian pada lokasi dan kondisi spesifik atau khas daerah, dapat disusun kegiatan dan kebutuhan anggaran secara khusus.
• Local : satuan biaya bersifat lokal dalam arti kegiatan tersebut dikelola secara lokal. Karena itu dalam satuan biaya tersebut tidak memperhitungkan transportasi dari pusat ke daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6924, 'Anggaran tersebut bersifat makro, atau berfungsi sebagai ancar-ancar (plafon) anggaran, sehingga pada saat rencana pelaksanaan disusun, diperlukan perincian anggaran (budget). Anggaran tersebut juga bersifat lokal, artinya tidak mempertimbangkan biaya-biaya pelaku atau sumber daya yang dari wilayah lain, karena variabilitasnya yang sangat tinggi.
Selanjutnya perlu disusun detil budget oleh pelaksana (pelaku) dengan mempertimbangkan kondisi lapangan (rentang wilayah), ketersediaan sumber daya manusia, aksesibilitas dan lain sebagainya.
Karakteristik Model Dalam lingkup pemulihan pascabencana dan dengan mempertimbangkan kebutuhan serta masalah dan hambatan, maka disusun model penganggaran makro yang memiliki ciri-ciri berikut:
• Quick; menyediakan alternatif daftar kegiatan dan estimasi kebutuhan anggarannya dalam waktu relatif cepat sehingga segera dapat dimanfaatkan untuk perencanaan maupun mengetahui profil kebutuhan pemulihan pascabencana.
• General; alternatif-alternatif kegiatan yang tersedia bersifat umum (general), yaitu standar/metode pelaksanaannya relatif sama pada wilayah yang berbeda-beda. Namun demikian pada lokasi dan kondisi spesifik atau khas daerah, dapat disusun kegiatan dan kebutuhan anggaran secara khusus.
• Local : satuan biaya bersifat lokal dalam arti kegiatan tersebut dikelola secara lokal. Karena itu dalam satuan biaya tersebut tidak memperhitungkan transportasi dari pusat ke daerah.', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 39)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6925, 'perka-15-2011', 131, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 40)', NULL, 124, '• Total ; kebutuhan anggaran merupakan kebutuhan total untuk pemulihan, rehabilitasi dan rekonstruksi pascabencana tanpa mempertimbangkan sumber dan ketersediaan anggaran. Dalam situasi ini, justru harus diperkuat dengan upaya penggalangan dana.
• Estimation; hasil kebutuhan anggaran adalah bersifat ancar-ancar yaitu sebagai dasar kebutuhan anggaran bagi pelaku/pelaksana program, swadaya, donor dan pihak lain yang terkait.. Karena itu pada saat disusun Rencana Aksi, perlu lebih didetilkan sesuai dengan kondisi dan perubahan sasaran dan situasi kondisinya.
• Timely : biaya ini digunakan untuk masa 1 tahun anggaran yang kegiatannya dapat diatur frekuensinya menurut harian, mingguan, bulanan atau berdasarkan keluaran tertentu yang dilaksanakan dalam masa 1 tahun. Namun bila ada kegiatan berjangka menengah (multiyears), maka dapat digunakan berulang untuk tahun berikutnya.
Metode Penyusunan
1. Pengelompokan Menurut Bidang. Kegiatan-kegiatan pemulihan pascabencana menurut Peraturan Kepala BNPB No.17 Tahun 2010 dikelompokkan menurut sektor berikut:
• Sektor Kemanusiaan
• Sektor Perumahan dan Permukiman
• Sektor Infrastruktur
• Sektor Ekonomi
• Sektor Sosial');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6925, '• Total ; kebutuhan anggaran merupakan kebutuhan total untuk pemulihan, rehabilitasi dan rekonstruksi pascabencana tanpa mempertimbangkan sumber dan ketersediaan anggaran. Dalam situasi ini, justru harus diperkuat dengan upaya penggalangan dana.
• Estimation; hasil kebutuhan anggaran adalah bersifat ancar-ancar yaitu sebagai dasar kebutuhan anggaran bagi pelaku/pelaksana program, swadaya, donor dan pihak lain yang terkait.. Karena itu pada saat disusun Rencana Aksi, perlu lebih didetilkan sesuai dengan kondisi dan perubahan sasaran dan situasi kondisinya.
• Timely : biaya ini digunakan untuk masa 1 tahun anggaran yang kegiatannya dapat diatur frekuensinya menurut harian, mingguan, bulanan atau berdasarkan keluaran tertentu yang dilaksanakan dalam masa 1 tahun. Namun bila ada kegiatan berjangka menengah (multiyears), maka dapat digunakan berulang untuk tahun berikutnya.
Metode Penyusunan
1. Pengelompokan Menurut Bidang. Kegiatan-kegiatan pemulihan pascabencana menurut Peraturan Kepala BNPB No.17 Tahun 2010 dikelompokkan menurut sektor berikut:
• Sektor Kemanusiaan
• Sektor Perumahan dan Permukiman
• Sektor Infrastruktur
• Sektor Ekonomi
• Sektor Sosial', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 40)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pasca Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6926, 'perka-15-2011', 132, 'lain', 'II. PERKIRAAN KERUGIAN Satuan (lanjutan 41)', NULL, 125, '• Lintas Sektor Namun dalam praktiknya sektor-sektor tersebut saling memiliki keterkaitan bahkan di antaranya dapat saling bertumpuk, sehingga proses identifikasi kegiatan dan penganggarannya dapat menjadi rumit. Karena itu dalam proses penyusunan model penganggaran ini, kegiatan-kegiatan pemulihan dan satuan biaya dipisahkan dalam bidang yang utuh. Adapun bidang-bidang tersebut antara lain:
• Pendidikan
• Ekonomi
• Kesehatan
• Infrastruktur
• Sosial
• Pemerintahan
2. Penyusunan Biaya Satuan. Sejumlah pertimbangan untuk mengatasi berbagai permasalahan dan hambatan yang telah dijelaskan sebelumnya, maka dilakukan kombinasi dua pendekatan, yaitu:
Permasalahan • Keragaman kegiatan pemulihan pascabencana (fisik & non fisik) Pendekatan • Menggunakan kegiatan dalam anggaran belanja daerah (kab/kota) karena bersifat umum.
Referensi • Belanja Langsung APBD (Benchmark) Hasil • Tabel Biaya Satuan
• Kegiatan Tahunan (APBD dirancang dalam satu tahun Karakteristik anggaran.
• Tidak tersedia standar biaya yang komparatif antar daerah.
Teknik penyusunan Biaya Satuan Kegiatan (Standar Biaya):
1. Memperoleh data APBD Kota yang menjadi benchmark.
2. Mengelompokkan APBD menurut aspek /sektor yang mendekati isu sektor PDNA.
3. Mengambil contoh kegiatan-kegiatan yang relevan untuk menetapkan tipologi kegiatan yang mirip dengan PDNA dan mengambil data nilai kegiatan tersebut (pendekatan good practices)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6926, '• Lintas Sektor Namun dalam praktiknya sektor-sektor tersebut saling memiliki keterkaitan bahkan di antaranya dapat saling bertumpuk, sehingga proses identifikasi kegiatan dan penganggarannya dapat menjadi rumit. Karena itu dalam proses penyusunan model penganggaran ini, kegiatan-kegiatan pemulihan dan satuan biaya dipisahkan dalam bidang yang utuh. Adapun bidang-bidang tersebut antara lain:
