INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6948, 'perka-15-2014', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk meningkatkan pelayanan dalam penyelenggaraan penanggulangan bencana, memandang perlu untuk memelihara persatuan dan kesatuan pegawai, meningkatkan citra, wibawa, disiplin dan tanggung jawab pegawai serta membangun identitas Badan Nasional Penanggulangan Bencana;
b. bahwa Badan Nasional Penanggulangan Bencana selama ini telah memiliki dan menggunakan seragam dinas dan atribut tersendiri yang belum diatur sehingga memandang perlu mengatur mengenai pakaian dinas dan atribut bagi pegawai di lingkungan Badan Nasional Penanggulangan Bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud pada huruf a dan huruf b, perlu menetapkanPeraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana;');
