INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6950, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PAKAIAN DINAS DAN ATRIBUTBADAN NASIONAL PENANGGULANGAN BENCANA.
3 2014, No.2077', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6951, 'perka-15-2014', 4, 'pasal', 'Pasal 1', 'BAB I KETENTUAN UMUM', 3, 'Dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana ini yang dimaksud dengan:
1. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB, adalah lembaga pemerintah nonkementerian setingkat menteri sesuai dengan ketentuan peraturan perundang-undangan.
2. Pegawai BNPB adalah Pegawai Aparatur Sipil Negara di lingkungan BNPB yang terdiri dari pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan digaji berdasarkan peraturan perundangan.
3. Pakaian Dinas BNPB adalah pakaian yang digunakan oleh Pegawai BNPB dalam melaksanakan tugas kedinasan.
4. Atribut BNPB adalah karakter visual ataupun abstrak berupa tulisan, tanda, warna, gambar, suara yang menjadi ciri khas dan menjadi pembeda antara BNPB dengan pihak lain.
5. Logo BNPB adalah lambang atau simbol yang terdiri dari gambar dan tulisan yang merupakan identitas resmi BNPB.
6. Mars Tangguh adalah gubahan lagu yang membangun semangat kebersamaan dan semangat persatuan dan kesatuan dalam penanggulangan bencana.
7. Hymne BNPB adalah gubahan lagu yang membangun semangat kebersamaan dan semangat persatuan dan kesatuan Pegawai BNPB.
8. Pataka BNPB adalah panji pemersatu berbentuk bendera kebesaran yang mencerminkan falsafah kerja BNPB.
9. Tanda Jabatan adalah tanda yang digunakan bagi pejabat tertentu yang diberi kewenangan dalam struktur organisasi BNPB.
10. Tanda Kepangkatan BNPB adalah tanda yang menyatakan pangkat/golongan atau Jabatan seorang Pegawai BNPB.
11. Brevet Penanggulangan Bencana adalah tanda kecakapan atau kompetensi yang dikeluarkan oleh BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6951, 'Dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana ini yang dimaksud dengan:
1. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB, adalah lembaga pemerintah nonkementerian setingkat menteri sesuai dengan ketentuan peraturan perundang-undangan.
2. Pegawai BNPB adalah Pegawai Aparatur Sipil Negara di lingkungan BNPB yang terdiri dari pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan digaji berdasarkan peraturan perundangan.
3. Pakaian Dinas BNPB adalah pakaian yang digunakan oleh Pegawai BNPB dalam melaksanakan tugas kedinasan.
4. Atribut BNPB adalah karakter visual ataupun abstrak berupa tulisan, tanda, warna, gambar, suara yang menjadi ciri khas dan menjadi pembeda antara BNPB dengan pihak lain.
5. Logo BNPB adalah lambang atau simbol yang terdiri dari gambar dan tulisan yang merupakan identitas resmi BNPB.
6. Mars Tangguh adalah gubahan lagu yang membangun semangat kebersamaan dan semangat persatuan dan kesatuan dalam penanggulangan bencana.
7. Hymne BNPB adalah gubahan lagu yang membangun semangat kebersamaan dan semangat persatuan dan kesatuan Pegawai BNPB.
8. Pataka BNPB adalah panji pemersatu berbentuk bendera kebesaran yang mencerminkan falsafah kerja BNPB.
9. Tanda Jabatan adalah tanda yang digunakan bagi pejabat tertentu yang diberi kewenangan dalam struktur organisasi BNPB.
10. Tanda Kepangkatan BNPB adalah tanda yang menyatakan pangkat/golongan atau Jabatan seorang Pegawai BNPB.
11. Brevet Penanggulangan Bencana adalah tanda kecakapan atau kompetensi yang dikeluarkan oleh BNPB.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6952, 'perka-15-2014', 5, 'pasal', 'Pasal 2', 'BAB I KETENTUAN UMUM', 3, 'Penyelenggaraan peraturan Pakaian Dinas dan Atribut BNPB berdasarkan pada asas:
2014, No.2077 4
a. kemanusiaan;
b. keadilan dan kesetaraan;
c. keseimbangan, keselarasan, dan keserasian;
d. ketertiban dan kepastian hukum;
e. profesionalitas dan proporsionalitas;
f. keterpaduan;
g. nondiskriminatif; dan
h. persatuan dan kesatuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6952, 'Penyelenggaraan peraturan Pakaian Dinas dan Atribut BNPB berdasarkan pada asas:
2014, No.2077 4
a. kemanusiaan;
b. keadilan dan kesetaraan;
c. keseimbangan, keselarasan, dan keserasian;
d. ketertiban dan kepastian hukum;
e. profesionalitas dan proporsionalitas;
f. keterpaduan;
g. nondiskriminatif; dan
h. persatuan dan kesatuan.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6953, 'perka-15-2014', 6, 'pasal', 'Pasal 3', 'BAB II PAKAIAN DINAS', 4, 'Maksud dan Tujuan
(1) Maksud peraturan ini adalah sebagai pedoman bagi seluruh Pegawai BNPB dalam menggunakan dan memakai Atribut BNPB.
(2) Tujuan peraturan ini adalah untuk:
a. mempersatukan tekad, semangat, jiwa, cipta, rasa dan karsa seluruh Pegawai BNPB;
b. meningkatkandisiplin, kerapihan, citra, wibawa, dan kepercayaan publik terhadap tugas dan fungsi BNPB; danmendorong peningkatan sasaran kinerja Pegawai BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6953, 'Maksud dan Tujuan
(1) Maksud peraturan ini adalah sebagai pedoman bagi seluruh Pegawai BNPB dalam menggunakan dan memakai Atribut BNPB.
(2) Tujuan peraturan ini adalah untuk:
a. mempersatukan tekad, semangat, jiwa, cipta, rasa dan karsa seluruh Pegawai BNPB;
b. meningkatkandisiplin, kerapihan, citra, wibawa, dan kepercayaan publik terhadap tugas dan fungsi BNPB; danmendorong peningkatan sasaran kinerja Pegawai BNPB.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6954, 'perka-15-2014', 7, 'pasal', 'Pasal 4', 'BAB III ATRIBUT BNPB; Bagian Kesatu Terjemahan BNPB', 4, '(1) Jenis pakaian dinas di Lingkungan BNPB terdiri atas:
a. Pakaian Dinas Harian lengan panjang;
b. Pakaian Dinas Harian lengan pendek;
c. Pakaian Dinas Lapangan;
d. Pakaian Korps Pegawai Republik Indonesia;
e. Pakaian Batik;
f. Kaos Kerja Lapangan; dan
g. Rompi.
(2) Setiap Pegawai BNPB wajib memakai pakaian dinas pada hari kerja yang ditetapkan berdasarkan Peraturan ini.
(3) Pemakaian Pakaian Dinas sebagaimana dimaksud pada ayat (1) dan ayat (2), adalah sebagai berikut:
5 2014, No.2077
a. Pakaian Dinas Harian lengan panjang dipakai pada hari Senin;
b. Pakaian Dinas Harian lengan pendek dipakai pada hari Kamis;
c. Pakaian Dinas Lapangan dipakai pada saat bertugas di lapangan berdasarkan hari kalender;
d. Pakaian Korps Pegawai Republik Indonesia dipakai pada upacara hari besar nasional;
e. Pakaian Batik dipakai pada hari Selasa, hari Jum’at dan hari batik nasional;
f. Kaos Kerja Lapangan dipakai pada saat bertugas di lapangan berdasarkan hari kalender; dan
g. Rompi dipakai pada saat bertugas di lapangan berdasarkan hari kalender.
(4) Pakaian dinas sebagaimana dimaksud pada ayat (1) dilengkapi dengan atribut yang terkait dengan pakaian dinas.
(5) Setiap Pegawai BNPB wanita yang beragama Islam, dapat menggunakan jilbab sesuai dengan Peraturan ini.
(6) Ketentuan lebih lanjut tentang Pakaian Dinas akan diatur dalam Petunjuk Pelaksanaan yang ditetapkan oleh Sekretaris Utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6954, '(1) Jenis pakaian dinas di Lingkungan BNPB terdiri atas:
a. Pakaian Dinas Harian lengan panjang;
b. Pakaian Dinas Harian lengan pendek;
c. Pakaian Dinas Lapangan;
d. Pakaian Korps Pegawai Republik Indonesia;
e. Pakaian Batik;
f. Kaos Kerja Lapangan; dan
g. Rompi.
(2) Setiap Pegawai BNPB wajib memakai pakaian dinas pada hari kerja yang ditetapkan berdasarkan Peraturan ini.
(3) Pemakaian Pakaian Dinas sebagaimana dimaksud pada ayat (1) dan ayat (2), adalah sebagai berikut:
5 2014, No.2077
a. Pakaian Dinas Harian lengan panjang dipakai pada hari Senin;
b. Pakaian Dinas Harian lengan pendek dipakai pada hari Kamis;
c. Pakaian Dinas Lapangan dipakai pada saat bertugas di lapangan berdasarkan hari kalender;
d. Pakaian Korps Pegawai Republik Indonesia dipakai pada upacara hari besar nasional;
e. Pakaian Batik dipakai pada hari Selasa, hari Jum’at dan hari batik nasional;
f. Kaos Kerja Lapangan dipakai pada saat bertugas di lapangan berdasarkan hari kalender; dan
g. Rompi dipakai pada saat bertugas di lapangan berdasarkan hari kalender.
(4) Pakaian dinas sebagaimana dimaksud pada ayat (1) dilengkapi dengan atribut yang terkait dengan pakaian dinas.
(5) Setiap Pegawai BNPB wanita yang beragama Islam, dapat menggunakan jilbab sesuai dengan Peraturan ini.
(6) Ketentuan lebih lanjut tentang Pakaian Dinas akan diatur dalam Petunjuk Pelaksanaan yang ditetapkan oleh Sekretaris Utama.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6955, 'perka-15-2014', 8, 'pasal', 'Pasal 5', 'BAB III ATRIBUT BNPB; Bagian Kedua Mars Tangguh', 5, '(1) Untuk keperluan dinas dan publikasi dalam Bahasa Inggris, sebutan BNPB dapat diterjemahkan ke dalam Bahasa Inggris.
(2) Terjemahan BNPB dalam Bahasa Inggris adalah National Disaster Management Authority atau disingkat denganNDMA.
(3) Sebutan BNPB dalam Bahasa Inggris yang digunakan untuk dokumen resmi, baik cetak maupun elektronik, terlebih dahulu mencantumkan nama BNPB dalam Bahasa Indonesia satu kali.
(4) Penggunaan dan penempatan sebutan BNPB dalam Bahasa Inggris untuk kegiatan ketatalaksanaan administratif di Lingkungan BNPB diatur dalam Peraturan Kepala BNPB yang mengatur khusus tentang tata naskah dinas.
2014, No.2077 6');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6955, '(1) Untuk keperluan dinas dan publikasi dalam Bahasa Inggris, sebutan BNPB dapat diterjemahkan ke dalam Bahasa Inggris.
(2) Terjemahan BNPB dalam Bahasa Inggris adalah National Disaster Management Authority atau disingkat denganNDMA.
(3) Sebutan BNPB dalam Bahasa Inggris yang digunakan untuk dokumen resmi, baik cetak maupun elektronik, terlebih dahulu mencantumkan nama BNPB dalam Bahasa Indonesia satu kali.
(4) Penggunaan dan penempatan sebutan BNPB dalam Bahasa Inggris untuk kegiatan ketatalaksanaan administratif di Lingkungan BNPB diatur dalam Peraturan Kepala BNPB yang mengatur khusus tentang tata naskah dinas.
2014, No.2077 6', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6956, 'perka-15-2014', 9, 'pasal', 'Pasal 6', 'BAB III ATRIBUT BNPB; Bagian Ketiga Hymne BNPB', 6, '(1) Untuk membangun semangat kesatuan dan kebersamaan dalam penanggulangan bencana, ditetapkan Mars Tangguh sebagai mars resmi penanggulangan bencana.
(2) Mars Tangguh sebagaimana dimaksud pada ayat (1) dinyanyikan pada acara resmi BNPB atau kegiatan penanggulangan bencana lainnya.
(3) Mars Tangguh memuat judul, pencipta, tangga nada, irama, dan syair.
(4) Mars Tangguh sebagaimana tercantum dalam Lampiran I, merupakan bagian yang tidak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6956, '(1) Untuk membangun semangat kesatuan dan kebersamaan dalam penanggulangan bencana, ditetapkan Mars Tangguh sebagai mars resmi penanggulangan bencana.
(2) Mars Tangguh sebagaimana dimaksud pada ayat (1) dinyanyikan pada acara resmi BNPB atau kegiatan penanggulangan bencana lainnya.
(3) Mars Tangguh memuat judul, pencipta, tangga nada, irama, dan syair.
(4) Mars Tangguh sebagaimana tercantum dalam Lampiran I, merupakan bagian yang tidak terpisahkan dari Peraturan ini.', 'Pasal 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6957, 'perka-15-2014', 10, 'pasal', 'Pasal 7', 'BAB III ATRIBUT BNPB; Bagian Keempat Logo BNPB', 6, '(1) Hymne Bhakti Pertiwi ditetapkan sebagai Hymne resmi BNPB.
(2) Hymne BNPB sebagaimana dimaksud pada ayat (1) dinyanyikan pada acara resmi BNPB atau kegiatan penanggulangan bencana lainnya.
(3) Hymne BNPB memuat judul, pencipta, tangga nada, irama, dan syair.
(4) Hymne BNPB sebagaimana tercantum dalam Lampiran II, merupakan bagian yang tidak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6957, '(1) Hymne Bhakti Pertiwi ditetapkan sebagai Hymne resmi BNPB.
(2) Hymne BNPB sebagaimana dimaksud pada ayat (1) dinyanyikan pada acara resmi BNPB atau kegiatan penanggulangan bencana lainnya.
(3) Hymne BNPB memuat judul, pencipta, tangga nada, irama, dan syair.
(4) Hymne BNPB sebagaimana tercantum dalam Lampiran II, merupakan bagian yang tidak terpisahkan dari Peraturan ini.', 'Pasal 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6958, 'perka-15-2014', 11, 'pasal', 'Pasal 8', 'BAB III ATRIBUT BNPB; Bagian Kelima Pataka BNPB', 6, '(1) Sebagai identitas BNPB ditetapkan Logo BNPB.
(2) Logo BNPB sebagaimana dimaksud pada ayat (1) memuat gambar, ukuran, tata warna, tulisan, makna tertentu dan tulisan BNPB.
(3) Logo BNPB dipergunakan pada pakaian dinas, tanda pengenal, topi, ikat pinggang, sarana dan prasarana berupa logistik, peralatan, papan nama kantor, bendera, pataka, spanduk, stiker dan umbul-umbul.
(4) Selain penggunaan sebagaimana dimaksud pada ayat (3) logo dapat digunakan oleh masyarakat dan lembaga usaha dalam melaksanakan pekerjaan atau aktivitas yang berkaitan dengan program penanggulangan bencana setelah mendapat persetujuan dari BNPB.
(5) Penggunaan Logo BNPB sebagaimana dimaksud pada ayat (3) dan ayat (4) diatur lebih lanjut dalam Petunjuk Pelaksanaan yang ditetapkan oleh Sekretaris Utama BNPB.
7 2014, No.2077
(6) Logo BNPB juga digunakan untuk kegiatan ketatalaksanaan administratif sesuai dengan Peraturan Kepala BNPB tentang tata naskah dinas.
(7) Gambar, ukuran, warna dan arti Logo BNPB tercantum dalam Lampiran III yang merupakan bagian yang tidak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6958, '(1) Sebagai identitas BNPB ditetapkan Logo BNPB.
(2) Logo BNPB sebagaimana dimaksud pada ayat (1) memuat gambar, ukuran, tata warna, tulisan, makna tertentu dan tulisan BNPB.
(3) Logo BNPB dipergunakan pada pakaian dinas, tanda pengenal, topi, ikat pinggang, sarana dan prasarana berupa logistik, peralatan, papan nama kantor, bendera, pataka, spanduk, stiker dan umbul-umbul.
(4) Selain penggunaan sebagaimana dimaksud pada ayat (3) logo dapat digunakan oleh masyarakat dan lembaga usaha dalam melaksanakan pekerjaan atau aktivitas yang berkaitan dengan program penanggulangan bencana setelah mendapat persetujuan dari BNPB.
(5) Penggunaan Logo BNPB sebagaimana dimaksud pada ayat (3) dan ayat (4) diatur lebih lanjut dalam Petunjuk Pelaksanaan yang ditetapkan oleh Sekretaris Utama BNPB.
7 2014, No.2077
(6) Logo BNPB juga digunakan untuk kegiatan ketatalaksanaan administratif sesuai dengan Peraturan Kepala BNPB tentang tata naskah dinas.
(7) Gambar, ukuran, warna dan arti Logo BNPB tercantum dalam Lampiran III yang merupakan bagian yang tidak terpisahkan dari Peraturan ini.', 'Pasal 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6959, 'perka-15-2014', 12, 'pasal', 'Pasal 9', 'BAB III ATRIBUT BNPB; Bagian Keenam Bendera Jabatan dan Tanda Jabatan', 7, '(1) Sebagai tanda kesatuan dan kebesaran BNPB, ditetapkan Pataka BNPB.
(2) Pataka BNPB berupa bendera berwarna dasar oranye dengan Logo BNPB dan dihiasi rumbai-rumbai berwarna kuning emasdisisi luarnya.
(3) Pataka BNPB digunakan dan diletakkan disebelah kiri Bendera Merah Putih disetiap acara resmi BNPB.
(4) Pataka BNPB diserahterimakan pada setiap pergantian Kepala BNPB di dalam suatu acara internal BNPB.
(5) Pataka BNPB ditempatkan bersebelahan dengan Bendera Merah Putih dan bendera jabatan di ruang kerja Kepala BNPB.
(6) Gambar, ukuran, dan warna Pataka BNPB tercantum dalam Lampiran IV yang merupakan bagian yang tidak terpisahkan dari peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6959, '(1) Sebagai tanda kesatuan dan kebesaran BNPB, ditetapkan Pataka BNPB.
(2) Pataka BNPB berupa bendera berwarna dasar oranye dengan Logo BNPB dan dihiasi rumbai-rumbai berwarna kuning emasdisisi luarnya.
(3) Pataka BNPB digunakan dan diletakkan disebelah kiri Bendera Merah Putih disetiap acara resmi BNPB.
(4) Pataka BNPB diserahterimakan pada setiap pergantian Kepala BNPB di dalam suatu acara internal BNPB.
(5) Pataka BNPB ditempatkan bersebelahan dengan Bendera Merah Putih dan bendera jabatan di ruang kerja Kepala BNPB.
(6) Gambar, ukuran, dan warna Pataka BNPB tercantum dalam Lampiran IV yang merupakan bagian yang tidak terpisahkan dari peraturan ini.', 'Pasal 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6960, 'perka-15-2014', 13, 'pasal', 'Pasal 10', 'BAB III ATRIBUT BNPB; Bagian Ketujuh Tanda Kepangkatan', 7, '(1) Sebagai tanda kebesaran jabatan, ditetapkan Bendera Jabatan dan Tanda Jabatan BNPB yang digunakan oleh Kepala, Sekretaris Utama, Deputi, Inspektur Utama, Kepala Biro, Direktur, Inspekturdan Kepala Pusat di Lingkungan BNPB.
(2) Bendera Jabatan BNPB berupa bendera dengan warna dasar biru tua, yang dilengkapi dengan logo limas segitiga, logo brevet penanggulangan bencana, tulisan BNPB, dan rumbai-rumbaikuning emas disisi luarnya.
(3) Jumlah limas segitiga pada bagian tengah Bendera Jabatan melambangkan tanda jabatan:
a. 4 (empat) limas segitiga untuk Kepala BNPB;
b. 3 (tiga) limassegitiga untuk Sekretaris Utama;
2014, No.2077 8
c. 2 (dua) limassegitiga untuk Deputi dan Inspektur Utama; dan
d. 1 (satu) limassegitiga untuk Kepala Biro, Direktur, Inspektur, dan Kepala Pusat.
(4) Bendera Jabatan Kepala BNPB ditempatkan bersebelahan setelah Bendera Merah Putih dan Pataka BNPB di ruang kerja Kepala BNPB.
(5) Bendera Jabatan pejabat lainnya ditempatkan bersebelahan setelah Bendera Merah Putih di ruang kerja pejabat BNPB.
(6) Tanda Jabatan dipasang di saku atau dada pakaian dinas harian dan pakaian dinas lapangan sebelah kiri, serta hanya digunakan oleh pejabat di lingkungan BNPB untuk menunjukkan jabatannya.
(7) Gambar, ukuran, warna, Bendera Jabatan dan Tanda Jabatan tercantum dalam Lampiran V dan Lampiran VI yang merupakan bagian tidak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6960, '(1) Sebagai tanda kebesaran jabatan, ditetapkan Bendera Jabatan dan Tanda Jabatan BNPB yang digunakan oleh Kepala, Sekretaris Utama, Deputi, Inspektur Utama, Kepala Biro, Direktur, Inspekturdan Kepala Pusat di Lingkungan BNPB.
(2) Bendera Jabatan BNPB berupa bendera dengan warna dasar biru tua, yang dilengkapi dengan logo limas segitiga, logo brevet penanggulangan bencana, tulisan BNPB, dan rumbai-rumbaikuning emas disisi luarnya.
(3) Jumlah limas segitiga pada bagian tengah Bendera Jabatan melambangkan tanda jabatan:
a. 4 (empat) limas segitiga untuk Kepala BNPB;
b. 3 (tiga) limassegitiga untuk Sekretaris Utama;
2014, No.2077 8
c. 2 (dua) limassegitiga untuk Deputi dan Inspektur Utama; dan
d. 1 (satu) limassegitiga untuk Kepala Biro, Direktur, Inspektur, dan Kepala Pusat.
(4) Bendera Jabatan Kepala BNPB ditempatkan bersebelahan setelah Bendera Merah Putih dan Pataka BNPB di ruang kerja Kepala BNPB.
(5) Bendera Jabatan pejabat lainnya ditempatkan bersebelahan setelah Bendera Merah Putih di ruang kerja pejabat BNPB.
(6) Tanda Jabatan dipasang di saku atau dada pakaian dinas harian dan pakaian dinas lapangan sebelah kiri, serta hanya digunakan oleh pejabat di lingkungan BNPB untuk menunjukkan jabatannya.
(7) Gambar, ukuran, warna, Bendera Jabatan dan Tanda Jabatan tercantum dalam Lampiran V dan Lampiran VI yang merupakan bagian tidak terpisahkan dari Peraturan ini.', 'Pasal 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6961, 'perka-15-2014', 14, 'pasal', 'Pasal 11', 'BAB III ATRIBUT BNPB; Bagian Kedelapan Brevet Penanggulangan Bencana', 8, '(1) Sebagai penanda kepangkatan/golongan Pegawai BNPB, ditetapkan Tanda Kepangkatan BNPB.
(2) Tanda kepangkatan hanya digunakan oleh pejabat di Lingkungan BNPB untuk menunjukkan pangkatnya.
(3) Tanda Kepangkatan digunakan oleh Pegawai BNPB mulai dari berpangkat Pengatur Muda (I/a) sampai Pembina Utama (IV/e).
(4) Lebih lanjut tentang Tanda Kepangkatan diatur dalam Petunjuk Pelaksanaan yang ditetapkan oleh Sekretaris Utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6961, '(1) Sebagai penanda kepangkatan/golongan Pegawai BNPB, ditetapkan Tanda Kepangkatan BNPB.
(2) Tanda kepangkatan hanya digunakan oleh pejabat di Lingkungan BNPB untuk menunjukkan pangkatnya.
(3) Tanda Kepangkatan digunakan oleh Pegawai BNPB mulai dari berpangkat Pengatur Muda (I/a) sampai Pembina Utama (IV/e).
(4) Lebih lanjut tentang Tanda Kepangkatan diatur dalam Petunjuk Pelaksanaan yang ditetapkan oleh Sekretaris Utama.', 'Pasal 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6962, 'perka-15-2014', 15, 'pasal', 'Pasal 12', 'BAB IV HAK DAN KEWAJIBAN', 8, '(1) Sebagai bentuk pengakuan atas kompetensi kerja khusus, ditetapkan Brevet Penanggulangan Bencana.
(2) Yang berhak memperoleh Brevet Penanggulangan Bencana, adalah Warga Negara Indonesia dan Warga Negara Asing yaitu:
a. Para pejabat struktural BNPB/BPBD sesuai dengan tingkatan eselonnya dan telah dinyatakan lulus oleh Panitia Ujian Nasional Pendidikan dan Pelatihan Penanggulangan Bencana;
b. Para pelaku penanggulangan bencana yang telah mengikuti pendidikan dan pelatihan penanggulangan bencana dan 9 2014, No.2077 dinyatakan lulus oleh Panitia Ujian Nasional Pendidikan dan Pelatihan Penanggulangan Bencana; dan
c. Para pimpinan daerah atau tokoh masyarakat yang dianggap mampu memimpin penyelenggaraan upaya penanggulangan bencana baik di tingkat nasional maupun di tingkat daerah.
Pemberian brevet ini sebagai penghargaan dan ditentukan sepenuhnya oleh Kepala BNPB.
(3) Bagi pemilik brevet penghargaan dapat melakukan penyetaraan brevet pendidikan dan pelatihan sesuai ketentuan peraturan perundang-undangan.
(4) Penyelenggaraan pelatihan untuk mendapat Brevet Penanggulangan Bencana dilaksanakan secara bertahap, berjenjang dan berkelanjutan.
(5) Lebih lanjut tentang Brevet Penanggulangan Bencana diatur dalam Petunjuk Pelaksanaan yang ditetapkan oleh Kepala Pusat Pendidikan dan Pelatihan BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6962, '(1) Sebagai bentuk pengakuan atas kompetensi kerja khusus, ditetapkan Brevet Penanggulangan Bencana.
(2) Yang berhak memperoleh Brevet Penanggulangan Bencana, adalah Warga Negara Indonesia dan Warga Negara Asing yaitu:
a. Para pejabat struktural BNPB/BPBD sesuai dengan tingkatan eselonnya dan telah dinyatakan lulus oleh Panitia Ujian Nasional Pendidikan dan Pelatihan Penanggulangan Bencana;
b. Para pelaku penanggulangan bencana yang telah mengikuti pendidikan dan pelatihan penanggulangan bencana dan 9 2014, No.2077 dinyatakan lulus oleh Panitia Ujian Nasional Pendidikan dan Pelatihan Penanggulangan Bencana; dan
c. Para pimpinan daerah atau tokoh masyarakat yang dianggap mampu memimpin penyelenggaraan upaya penanggulangan bencana baik di tingkat nasional maupun di tingkat daerah.
Pemberian brevet ini sebagai penghargaan dan ditentukan sepenuhnya oleh Kepala BNPB.
(3) Bagi pemilik brevet penghargaan dapat melakukan penyetaraan brevet pendidikan dan pelatihan sesuai ketentuan peraturan perundang-undangan.
(4) Penyelenggaraan pelatihan untuk mendapat Brevet Penanggulangan Bencana dilaksanakan secara bertahap, berjenjang dan berkelanjutan.
(5) Lebih lanjut tentang Brevet Penanggulangan Bencana diatur dalam Petunjuk Pelaksanaan yang ditetapkan oleh Kepala Pusat Pendidikan dan Pelatihan BNPB.', 'Pasal 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6963, 'perka-15-2014', 16, 'pasal', 'Pasal 13', 'BAB V PEMBINAAN DAN PENGAWASAN', 9, '(1) Setiap Pegawai BNPB wajib menggunakan Pakaian Dinas dan Atribut BNPB sesuai dengan:
a. peraturan Kepala BNPB; dan
b. keahlian kompetensi atau jabatan.
(2) Setiap Pegawai BNPB wajib:
a. mengetahui, mengerti, dan menghayati Pakaian Dinas dan setiap Atribut BNPB;
b. menjaga nama baik BNPB setiap waktu ketika sedang menggunakan Pakaian Dinas, Atribut BNPB dan/atau sedang menjalankan tugas sebagai Pegawai BNPB; dan
c. melaporkan kepada atasan satu tingkat di atas masing-masing pegawai ketika melihat dan mengetahui penyalahgunaan Pakaian Dinas dan Atribut BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6963, '(1) Setiap Pegawai BNPB wajib menggunakan Pakaian Dinas dan Atribut BNPB sesuai dengan:
a. peraturan Kepala BNPB; dan
b. keahlian kompetensi atau jabatan.
(2) Setiap Pegawai BNPB wajib:
a. mengetahui, mengerti, dan menghayati Pakaian Dinas dan setiap Atribut BNPB;
b. menjaga nama baik BNPB setiap waktu ketika sedang menggunakan Pakaian Dinas, Atribut BNPB dan/atau sedang menjalankan tugas sebagai Pegawai BNPB; dan
c. melaporkan kepada atasan satu tingkat di atas masing-masing pegawai ketika melihat dan mengetahui penyalahgunaan Pakaian Dinas dan Atribut BNPB.', 'Pasal 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6964, 'perka-15-2014', 17, 'pasal', 'Pasal 14', 'BAB VI PERAN SERTA MASYARAKAT', 9, 'Pembinaan dan Pengawasan terhadap penggunaan Pakaian Dinas dan Atribut BNPB bagi Pegawai BNPB dilakukan oleh pimpinan setiap unit kerja di lingkungan BNPB.
2014, No.2077 10');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6964, 'Pembinaan dan Pengawasan terhadap penggunaan Pakaian Dinas dan Atribut BNPB bagi Pegawai BNPB dilakukan oleh pimpinan setiap unit kerja di lingkungan BNPB.
2014, No.2077 10', 'Pasal 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6965, 'perka-15-2014', 18, 'pasal', 'Pasal 15', 'BAB VII SANKSI', 10, '(1) Masyarakat dapat menggunakan Atribut BNPB berupa Logo, Nama, Mars dan Hymne BNPB dalam kegiatan penanggulangan bencana.
(2) Masyarakat dapat menggunakan Atribut BNPB yaitu kaos oranye berikut logo dan nama BNPB pada saat ikut serta dalam kegiatan penanggulangan bencana.
(3) Penggunaan Atribut sebagaimana dimaksud pada ayat (1) setelah mendapat izin dari unit kerja yang menjadi mitra atau unit kerja terkait dengan kegiatan yang akan dilaksanakan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6965, '(1) Masyarakat dapat menggunakan Atribut BNPB berupa Logo, Nama, Mars dan Hymne BNPB dalam kegiatan penanggulangan bencana.
(2) Masyarakat dapat menggunakan Atribut BNPB yaitu kaos oranye berikut logo dan nama BNPB pada saat ikut serta dalam kegiatan penanggulangan bencana.
(3) Penggunaan Atribut sebagaimana dimaksud pada ayat (1) setelah mendapat izin dari unit kerja yang menjadi mitra atau unit kerja terkait dengan kegiatan yang akan dilaksanakan.', 'Pasal 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6966, 'perka-15-2014', 19, 'pasal', 'Pasal 16', 'BAB VIII KETENTUAN LAIN-LAIN', 10, 'Penyalahgunaan Pakaian Dinas dan Atribut BNPB dapat dikenakan sanksi sesuai dengan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6966, 'Penyalahgunaan Pakaian Dinas dan Atribut BNPB dapat dikenakan sanksi sesuai dengan peraturan perundang-undangan.', 'Pasal 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6967, 'perka-15-2014', 20, 'pasal', 'Pasal 17', 'BAB IX KETENTUAN PERALIHAN', 10, 'Penggunaan Pakaian Dinas dan Atribut BNPB ini dapat diikuti dan disesuaikan oleh Badan Penanggulangan Bencana Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6967, 'Penggunaan Pakaian Dinas dan Atribut BNPB ini dapat diikuti dan disesuaikan oleh Badan Penanggulangan Bencana Daerah.', 'Pasal 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6968, 'perka-15-2014', 21, 'pasal', 'Pasal 18', 'BAB IX KETENTUAN PENUTUP', 10, 'Penyelenggaraan Pakaian Dinas dan Atribut BNPB yang diatur dalam peraturan BNPB lainnya tetap berlaku sepanjang tidak bertentangan dengan Peraturan ini.');
