INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6970, 'Ditetapkan di Jakarta pada tanggal 1 Desember 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 31 Desember 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY 2014, No.2077 12', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6971, 'perka-15-2014', 24, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'LAMPIRAN I PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 15 TAHUN 2014 TENTANG PAKAIAN DINAS DAN ATRIBUT BADAN NASIONAL PENANGGULANGAN BENCANA MARS TANGGUH KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF 13 2014, No.2077 LAMPIRAN II PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 15 TAHUN 2014 TENTANG PAKAIAN DINAS DAN ATRIBUT BADAN NASIONAL PENANGGULANGAN BENCANA HYMNE BHAKTI PERTIWI KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF 2014, No.2077 14 LAMPIRAN III PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 15 TAHUN 2014 TENTANG PAKAIAN DINAS DAN ATRIBUT BADAN NASIONAL PENANGGULANGAN BENCANA BENTUK, MAKNA, WARNA DAN UKURAN LOGO BADAN NASIONAL PENANGGULANGAN BENCANA BNPB A. BENTUK Lambang Badan Nasional Penanggulangan Bencana (BNPB) berbentuk lingkaran dan terdiri dari:
1. Segitiga berwarna biru, terletak ditengah-tengah lingkaran berwarna oranye.
2. Lingkaran berwarna merah dan putih sebagai bingkai lingkaran berwarna oranye.
Dalam bingkai lingkaran terdapat tulisan, yakni:
1. Tulisan BADAN NASIONAL dengan warna putih berada pada bingkai berwarna merah.
2. Tulisan PENANGGULANGAN BENCANA dengan warna merah berada pada bingkai berwarna putih.
B. MAKNA Makna dari bagian-bagian lambang:
1. Secara keseluruhan lambang BNPB yang berbentuk lingkaran tersebut menggambarkan perisai, melambangkan“Ketangguhan Bangsa Dalam Menghadapi Bencana”.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6971, 'LAMPIRAN I PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 15 TAHUN 2014 TENTANG PAKAIAN DINAS DAN ATRIBUT BADAN NASIONAL PENANGGULANGAN BENCANA MARS TANGGUH KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF 13 2014, No.2077 LAMPIRAN II PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 15 TAHUN 2014 TENTANG PAKAIAN DINAS DAN ATRIBUT BADAN NASIONAL PENANGGULANGAN BENCANA HYMNE BHAKTI PERTIWI KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF 2014, No.2077 14 LAMPIRAN III PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 15 TAHUN 2014 TENTANG PAKAIAN DINAS DAN ATRIBUT BADAN NASIONAL PENANGGULANGAN BENCANA BENTUK, MAKNA, WARNA DAN UKURAN LOGO BADAN NASIONAL PENANGGULANGAN BENCANA BNPB A. BENTUK Lambang Badan Nasional Penanggulangan Bencana (BNPB) berbentuk lingkaran dan terdiri dari:
1. Segitiga berwarna biru, terletak ditengah-tengah lingkaran berwarna oranye.
2. Lingkaran berwarna merah dan putih sebagai bingkai lingkaran berwarna oranye.
Dalam bingkai lingkaran terdapat tulisan, yakni:
1. Tulisan BADAN NASIONAL dengan warna putih berada pada bingkai berwarna merah.
2. Tulisan PENANGGULANGAN BENCANA dengan warna merah berada pada bingkai berwarna putih.
B. MAKNA Makna dari bagian-bagian lambang:
1. Secara keseluruhan lambang BNPB yang berbentuk lingkaran tersebut menggambarkan perisai, melambangkan“Ketangguhan Bangsa Dalam Menghadapi Bencana”.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2014 tentang Pakaian Dinas dan Atribut Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6972, 'perka-15-2014', 25, 'lampiran', 'Lampiran hal. 14', NULL, 14, '2. Segitiga berwarna biru ditengah lingkaran berwarna oranye, melambangkan misi BNPB, yakni:
15 2014, No.2077
a. Melindungi Bangsa dari Ancaman Bencana melalui Pengurangan Resiko;
b. Membangun Sistem Penanggulangan Bencana yang Handal;
c. Menyelenggarakan Penanggulangan Bencana secara Terencana, Terpadu, Terkoordinasi, dan Menyeluruh.
3. Selain itu segitiga berwarna biru juga melambangkan:
a. Perlindungan, yakni BNPB sebagai Lembaga Negara yang mempunyai tugas dan fungsi memberikan perlindungan kepada masyarakat dari ancaman bencana;
b. Dalam pelaksanaannya melibatkan peran serta dari Pemerintah, Masyarakat, dan Dunia Usaha.
4. Bingkai berwarna merah dan putih, melambangkan Bendera Negara Indonesia.
5. Singkatan BNPB, dengan kepanjangan Badan Nasional Penanggulangan Bencana sebagai Pelaksana Penanggulangan Bencana menyelenggarakan fungsi:
a. Koordinasi dalam penyelenggara penanggulangan bencana;
b. Komando dalam penyelenggara penanggulangan bencana; dan
c. Pelaksana dalam penyelenggaraan penanggulangan bencana.
C. WARNA
1. Segitiga berwarna biru, mempunyai makna bahwa BNPB sebagai salah satu Lembaga Negara yang bertugas untuk memberikan perlindungan kepada masyarakat dari ancaman bencana. Selain itu segitiga berwarna biru merupakan lambang yang akan mendapatkan perlindungan pada saat terjadi konflik senjata dan tidak boleh dijadikan sebagai obyek atau sasaran/target serangan militer.');
