INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6973, 'perka-15-2014', 26, 'lampiran', 'Lampiran hal. 15', NULL, 15, '2. Warna merah pada bingkai lingkaran bermakna sebagai kondisi darurat atau bahaya, sehingga BNPB harus senantiasa rensponsif dan aktif untuk segala situasi bencana, sedangkan warna putih pada bingkai lingkaran, bermakna bahwa BNPB dalam pelaksanaan tugasnya senantiasa mendasarkan pada ketulusan dan keikhlasan berkorban, bersifat netral dan tidak diskriminatif.
3. Warna oranyepada lingkaran, mempunyai makna bahwa BNPB harus selalu mengedepankan “Kesiapsiagaan” dalam pelaksanaan tugasnya.
4. GarisWarna hitam pada lingkaran, mempunyai makna bahwa BNPB harus selalu tampil dan tangguh dalam Penanggulangan Bencana.
