INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6984, 'perka-15-2014', 37, 'lampiran', 'Lampiran hal. 35', NULL, 35, 'b. Motif balairung melambangkan tempat dan wahana yang menghimpun seluruh anggota KORPRIguna mewujudkan Aparatur Negara yang netral, jujur dan adil, bersih serta berwibawa untuk mendukung Pemerintah RI yang stabil dan demokratis dalam mencapai cita-cita dan tujuan nasional;
c. Kelima tiang dari balairung melukiskan Pancasila sebagai dasar dalam kehidupan berorganisasi, bermasyarakat, berbangsa dan bernegara;
d. Motif sayap melambangkan kekuatan/kiprah/perjuangan KORPRI untuk mewujudkan organisasi yang mandiri, dinamis dan modern serta profesional dalam rangka mendukung terwujudnya cita-cita dan tujuan nasional RI;
e. Pangkal kedua sayap bersatu ditengah melambangkan sifat persatuan KORPRO didalam satu wadah yang melukiskan jiwa korsa yang bulat sebagai alat yang ampuh, bersatu padu dan setia kepada Pemerintah untuk menyelenggarakan tugas-tugas umum pemerintahan dan pembangunan serta kemasyarakatan;
f. Sayap yang mendukung balairung dan pohon menggambarkan hakekat tugas KORPRI sebagai pengabdi masyarakat yang mengutamakan kepentingan umum, bangsa dan Negara;
g. Pondamen yang melandasi dan mendukung bangunan balairung adalah sebagai lambang loyalitas tunggal KORPRI terhadap Pemerintah dan Negara, karena fungsi dari pondamen tiada lain adalah memberi kekokohan dan kemantapan bagi bangunan yang berada diatasnya;');
