INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6985, 'perka-15-2014', 38, 'lampiran', 'Lampiran hal. 35', NULL, 35, 'h. Pohon dengan dahan dan dedaunan yang tersusun rapih teratur melambangkan peran KORPRI sebagai pengayom dan pelindung bangsa sesuai dengan fungsi dan peranannya sebagai abdi negara dan abdi masyaraka didalam Negara Republik Indonesia;
i. Lantai gedung balairung yang tersusun harmonis pyramidal, melambangkan mental mutu/watak anggota KORPRI yang netral, jujur, adil yang tidak luntur sepanjang masa bekerja tanpa pamrih hanya semata-mata untuk kepentingan bangsa dan Negara; dan
j. Warna emas dari lambang mempunyai arti keluhuran dan keagungan cita-cita kemerdekaan Bangsa Indonesia.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF');
