INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6994, 'perka-16-2009', 8, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 31 Desember 2009 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1416 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6994, 'Ditetapkan di Jakarta pada tanggal 31 Desember 2009 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1416 4', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6995, 'perka-16-2009', 9, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 16 TAHUN 2008 TENTANG PEDOMAN PENGELOLAAN HIBAH LANGSUNG DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. LATAR BELAKANG Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara menetapkan bahwa dalam rangka membiayai dan mendukung kegiatan prioritas dalam rangka mencapai sasaran pembangunan, pemerintah dapat mengadakan pinjaman dan/atau menerima hibah baik yang berasal dari dalam negeri maupun dari luar negeri.
Disamping itu, sebagai amanat Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara, Pemerintah juga dituntut untuk melaksanakan tata kelola yang baik (Good Governence) dengan meningkatkan transparansi dan akuntabilitas dalam mekanisme pengadaan pinjaman maupun pendapatan hibah.
Penyajian dan pengungkapan (disclosure) laporan yang akurat dan informatif juga merupakan bagian yang tidak terpisahkan dalam mendukung aspek akuntabilitas dan transparansi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6995, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 16 TAHUN 2008 TENTANG PEDOMAN PENGELOLAAN HIBAH LANGSUNG DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. LATAR BELAKANG Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara menetapkan bahwa dalam rangka membiayai dan mendukung kegiatan prioritas dalam rangka mencapai sasaran pembangunan, pemerintah dapat mengadakan pinjaman dan/atau menerima hibah baik yang berasal dari dalam negeri maupun dari luar negeri.
Disamping itu, sebagai amanat Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara, Pemerintah juga dituntut untuk melaksanakan tata kelola yang baik (Good Governence) dengan meningkatkan transparansi dan akuntabilitas dalam mekanisme pengadaan pinjaman maupun pendapatan hibah.
Penyajian dan pengungkapan (disclosure) laporan yang akurat dan informatif juga merupakan bagian yang tidak terpisahkan dalam mendukung aspek akuntabilitas dan transparansi.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6996, 'perka-16-2009', 10, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'Sebagaimana diatur dalam Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara bahwa Menteri Keuangan selaku Bendahara Umum Negara berwenang melakukan Pengelolaan Utang dan Piutang dan dapat menunjuk Pejabat yang diberi kuasa atas nama Menteri Keuangan untuk mengadakan Utang Negara atau menerima Hibah yang berasal dari dalam negeri maupun luar negeri sesuai dengan ketentuan yang telah ditetapkan dalam Undang-Undang dan dalam Peraturan Pemerintah Republik Indonesia Nomor 2 Tahun 2006 tentang Tata cara Pengadaan Pinjaman dan/atau Penerimaan hibah dan Peraturan Pemerintah Nomor 57 Tahun 2005 tentang Hibah kepada Daerah serta penerusan pinjaman dan/atau hibah luar negeri mensiratkan bahwa baik pinjaman maupun hibah harus ditatakan, diadministrasikan dan diakuntasikan secara baik sehingga laporan yang disajikan akan memberikan manfaat bagi pengambil keputusan.
Namun demikian ketentuan-ketentuan diatas masih dirasakan kurang efektif mengingat masih terdapat hibah luar negeri Pemerintah yang 5 2014, No.1416 pelaksanaannya dilakukan secara langsung oleh pemberi hibah (donor) kepada penerima hibah (beneficiary) yang belum tercatat dalam APBN.
Seperti yang dialami Badan Nasional Penanggulangan Bencana dalam menangani korban bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6996, 'Sebagaimana diatur dalam Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara bahwa Menteri Keuangan selaku Bendahara Umum Negara berwenang melakukan Pengelolaan Utang dan Piutang dan dapat menunjuk Pejabat yang diberi kuasa atas nama Menteri Keuangan untuk mengadakan Utang Negara atau menerima Hibah yang berasal dari dalam negeri maupun luar negeri sesuai dengan ketentuan yang telah ditetapkan dalam Undang-Undang dan dalam Peraturan Pemerintah Republik Indonesia Nomor 2 Tahun 2006 tentang Tata cara Pengadaan Pinjaman dan/atau Penerimaan hibah dan Peraturan Pemerintah Nomor 57 Tahun 2005 tentang Hibah kepada Daerah serta penerusan pinjaman dan/atau hibah luar negeri mensiratkan bahwa baik pinjaman maupun hibah harus ditatakan, diadministrasikan dan diakuntasikan secara baik sehingga laporan yang disajikan akan memberikan manfaat bagi pengambil keputusan.
Namun demikian ketentuan-ketentuan diatas masih dirasakan kurang efektif mengingat masih terdapat hibah luar negeri Pemerintah yang 5 2014, No.1416 pelaksanaannya dilakukan secara langsung oleh pemberi hibah (donor) kepada penerima hibah (beneficiary) yang belum tercatat dalam APBN.
Seperti yang dialami Badan Nasional Penanggulangan Bencana dalam menangani korban bencana.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6997, 'perka-16-2009', 11, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'Berdasarkan kenyataan bahwa sampai saat ini diketahui bahwa di dalam pengelolaan dana hibah yang bersumber dari dalam maupun luar negeri (misalnya dari UNDP ~ SCDRR) masih ditemukan adanya masalah-masalah yang disebabkan kurangnya pemahaman didalam pengelolaan keuangan hibah baik pembukuan, pertanggungjawaban keuangan, maupun pelaporan secara inventarisasi dalam bentuk barang.
Demi terlaksananya kegiatan pengelolaan dana hibah secara optimal, perlu adanya dukungan manajemen berupa Pedoman Pengelolaan Hibah.
B. DASAR HUKUM.
1. Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara.
2. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara.
3. Undang-Undang Nomor 24 tahun 2007 tentang Penanggulangan Bencana.
4. Peraturan Pemerintah Republik Indonesia Nomor 2 Tahun 2006 tentang tata cara pengadaan pinjaman dan/atau penerimaan hibah.
5. Peraturan Pemerintah Nomor 57 Tahun 2005 tentang Hibah kepada Daerah serta penerusan pinjaman dan/atau hibah luar negeri.
6. Peraturan Pemerintah Nomor 24 Tahun 2005 tentang Standar Akuntansi Pemerintah.
7. Peraturan Direktur Jenderal Perbendaharaan No.18/PB/2007 tentang Mekanisme Penerbitan Surat Perintah Pembukuan/ Pengesahan atas Realisasi PHLN melalui pembayaran langsung dan letter of credit.
8. Peraturan Menteri Keuangan No.40/PMK.05/2009 tanggal 27 Februari 2009 tentang Sistem Akuntansi Hibah (SIKUBAH)
9. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6997, 'Berdasarkan kenyataan bahwa sampai saat ini diketahui bahwa di dalam pengelolaan dana hibah yang bersumber dari dalam maupun luar negeri (misalnya dari UNDP ~ SCDRR) masih ditemukan adanya masalah-masalah yang disebabkan kurangnya pemahaman didalam pengelolaan keuangan hibah baik pembukuan, pertanggungjawaban keuangan, maupun pelaporan secara inventarisasi dalam bentuk barang.
Demi terlaksananya kegiatan pengelolaan dana hibah secara optimal, perlu adanya dukungan manajemen berupa Pedoman Pengelolaan Hibah.
B. DASAR HUKUM.
1. Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara.
2. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara.
3. Undang-Undang Nomor 24 tahun 2007 tentang Penanggulangan Bencana.
4. Peraturan Pemerintah Republik Indonesia Nomor 2 Tahun 2006 tentang tata cara pengadaan pinjaman dan/atau penerimaan hibah.
5. Peraturan Pemerintah Nomor 57 Tahun 2005 tentang Hibah kepada Daerah serta penerusan pinjaman dan/atau hibah luar negeri.
6. Peraturan Pemerintah Nomor 24 Tahun 2005 tentang Standar Akuntansi Pemerintah.
7. Peraturan Direktur Jenderal Perbendaharaan No.18/PB/2007 tentang Mekanisme Penerbitan Surat Perintah Pembukuan/ Pengesahan atas Realisasi PHLN melalui pembayaran langsung dan letter of credit.
8. Peraturan Menteri Keuangan No.40/PMK.05/2009 tanggal 27 Februari 2009 tentang Sistem Akuntansi Hibah (SIKUBAH)
9. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6998, 'perka-16-2009', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, '10. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana
11. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana 2014, No.1416 6 C. MAKSUD DAN TUJUAN MAKSUD :
Pedoman ini dimaksudkan sebagai petunjuk operasional dalam pengelolaan hibah yang diterima langsung oleh BNPB, sehingga dapat dikelola secara transparan, akurat dan dapat dipertanggungjawabkan sesuai peraturan yang berlaku TUJUAN :
- Tercapainya persamaan persepsi tentang pengelolaan hibah di lingkungan BNPB.
- Terwujudnya pengelolaan administrasi hibah yang baik dan benar sesuai ketentuan perundang-undangan.
- Terciptanya transparasi dalam pengelolaan hibah.
- Pengelolaan hibah yang dapat dipertanggung jawabkan.
D. RUANG LINGKUP Hanya meliputi hibah yang diterima langsung oleh satker BNPB, yakni penerimaan yang berupa hibah atau termasuk bantuan teknik, proyek, kerjasama teknik dan kerjasama keuangan, serta belanja yang berasal dari Hibah:
- Berupa belanja barang (misalnya untuk penanganan tanggap darurat)
- Belanja Modal (akan diterus hibahkan ke Pemda) E. PENGERTIAN
1. Anggaran Pendapatan dan Belanja Negara yang selanjutnya disebut APBN adalah rencana keuangan tahunan pemerintah yang disetujui oleh Dewan Perwakilan Rakyat yang masa berlakunya dari tanggal 1 Januari sampai dengan tanggal 31 Desember tahun berkenaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6998, '10. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana
11. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana 2014, No.1416 6 C. MAKSUD DAN TUJUAN MAKSUD :
Pedoman ini dimaksudkan sebagai petunjuk operasional dalam pengelolaan hibah yang diterima langsung oleh BNPB, sehingga dapat dikelola secara transparan, akurat dan dapat dipertanggungjawabkan sesuai peraturan yang berlaku TUJUAN :
- Tercapainya persamaan persepsi tentang pengelolaan hibah di lingkungan BNPB.
- Terwujudnya pengelolaan administrasi hibah yang baik dan benar sesuai ketentuan perundang-undangan.
- Terciptanya transparasi dalam pengelolaan hibah.
- Pengelolaan hibah yang dapat dipertanggung jawabkan.
D. RUANG LINGKUP Hanya meliputi hibah yang diterima langsung oleh satker BNPB, yakni penerimaan yang berupa hibah atau termasuk bantuan teknik, proyek, kerjasama teknik dan kerjasama keuangan, serta belanja yang berasal dari Hibah:
- Berupa belanja barang (misalnya untuk penanganan tanggap darurat)
- Belanja Modal (akan diterus hibahkan ke Pemda) E. PENGERTIAN
1. Anggaran Pendapatan dan Belanja Negara yang selanjutnya disebut APBN adalah rencana keuangan tahunan pemerintah yang disetujui oleh Dewan Perwakilan Rakyat yang masa berlakunya dari tanggal 1 Januari sampai dengan tanggal 31 Desember tahun berkenaan.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (6999, 'perka-16-2009', 13, 'lampiran', 'Lampiran hal. 6', NULL, 6, '2. Daftar Isian Pelaksanaan Anggaran yang selanjutnya disebut DIPA adalah dokumen pelaksanaan anggaran yang dibuat oleh Menteri/Pimpinan Lembaga atau Satuan Kerja (Satker) serta disahkan oleh Direktur Jenderal Perbendaharaan atau Kepala Kantor Wilayah Direktur Jenderal atas nama Menteri Keuangan dan berfungsi sebagai dasar untuk melakukan tindakan yang mengakibatkan pengeluaran negara dan pencairan dana atas beban APBN serta dokumen pendukung kegiatan akuntansi pemerintah.
3. Hibah Luar Negeri adalah setiap penerimaan negara baik dalam bentuk devisa dan/atau devisa yang dirupiahkan, Rupiah maupun dalam bentuk barang dan/atau jasa termasuk tenaga ahli dan pelatihan yang diperoleh dari pemberian hibah luar negeri yang tidak perlu dibayar/diterima kembali oleh pemerintah.
7 2014, No.1416
4. Pemberi Hibah Luar Negeri yang selanjutnya disebut PHLN adalah pemerintah suatu negara asing, lembaga multilateral, lembaga keuangan dan lembaga non keuangan asing, yang berdomisili dan melakukan kegiatan usaha di luar wilayah negara Republik Indonesia, yang memberikan hibah kepada Pemerintah.
5. Hibah Luar Negeri yang dilaksanakan langsung yang selanjutnya disebut Hibah adalah Hibah Luar Negeri yang pada prakteknya pelaksanaan sebagian atau seluruh hibahnya dikelola secara langsung.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (6999, '2. Daftar Isian Pelaksanaan Anggaran yang selanjutnya disebut DIPA adalah dokumen pelaksanaan anggaran yang dibuat oleh Menteri/Pimpinan Lembaga atau Satuan Kerja (Satker) serta disahkan oleh Direktur Jenderal Perbendaharaan atau Kepala Kantor Wilayah Direktur Jenderal atas nama Menteri Keuangan dan berfungsi sebagai dasar untuk melakukan tindakan yang mengakibatkan pengeluaran negara dan pencairan dana atas beban APBN serta dokumen pendukung kegiatan akuntansi pemerintah.
3. Hibah Luar Negeri adalah setiap penerimaan negara baik dalam bentuk devisa dan/atau devisa yang dirupiahkan, Rupiah maupun dalam bentuk barang dan/atau jasa termasuk tenaga ahli dan pelatihan yang diperoleh dari pemberian hibah luar negeri yang tidak perlu dibayar/diterima kembali oleh pemerintah.
7 2014, No.1416
4. Pemberi Hibah Luar Negeri yang selanjutnya disebut PHLN adalah pemerintah suatu negara asing, lembaga multilateral, lembaga keuangan dan lembaga non keuangan asing, yang berdomisili dan melakukan kegiatan usaha di luar wilayah negara Republik Indonesia, yang memberikan hibah kepada Pemerintah.
5. Hibah Luar Negeri yang dilaksanakan langsung yang selanjutnya disebut Hibah adalah Hibah Luar Negeri yang pada prakteknya pelaksanaan sebagian atau seluruh hibahnya dikelola secara langsung.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7000, 'perka-16-2009', 14, 'lampiran', 'Lampiran hal. 7', NULL, 7, '6. Pengguna Anggaran/Kuasa Pengguna Anggaran yang selanjutnya disebut PA/KPA adalah Menteri/Pimpinan Lembaga atau kuasanya yang bertanggung jawab atas pengelolaan anggaran pada Kementerian Negara/Lembaga yang bersangkutan.
7. Bank Penata Usaha Dalam Negeri yang selanjutnya disebut Bank adalah Bank Pemerintah yang ditunjuk oleh PA/Kuasa PA untuk mengelola dana hibah yang diterima.
8. Kantor Pelayanan Perbendaharaan Negara Khusus : yang selanjutnya disebut KPPN Khusus adalah instansi vertikal Direktorat Jenderal Perbendaharaan yang berada di bawah dan bertanggung jawab langsung kepada Kantor Wilayah Direktorat Jenderal Perbendaharaan yang tugas pokoknya adalah memproses pembayaran yang menggunakan dana pinjaman dan/atau hibah luar negeri khususnya dalam bentuk valuta asing (valas).
9. Surat Permintaan Pengesahan adalah surat permintaan penerbitan dokumen pengesahan atas realisasi yang telah diberikan oleh PHLN yang diajukan oleh PA/Kuasa PA kepada KPPN Khusus Jakarta VI.
10. Surat Pengganti Withdrawal Application yang selanjutnya disebut Surat Pengganti WA adalah surat pengganti permintaan pembayaran hibah yang diterbitkan/disahkan oleh KPPN Khusus.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7000, '6. Pengguna Anggaran/Kuasa Pengguna Anggaran yang selanjutnya disebut PA/KPA adalah Menteri/Pimpinan Lembaga atau kuasanya yang bertanggung jawab atas pengelolaan anggaran pada Kementerian Negara/Lembaga yang bersangkutan.
7. Bank Penata Usaha Dalam Negeri yang selanjutnya disebut Bank adalah Bank Pemerintah yang ditunjuk oleh PA/Kuasa PA untuk mengelola dana hibah yang diterima.
8. Kantor Pelayanan Perbendaharaan Negara Khusus : yang selanjutnya disebut KPPN Khusus adalah instansi vertikal Direktorat Jenderal Perbendaharaan yang berada di bawah dan bertanggung jawab langsung kepada Kantor Wilayah Direktorat Jenderal Perbendaharaan yang tugas pokoknya adalah memproses pembayaran yang menggunakan dana pinjaman dan/atau hibah luar negeri khususnya dalam bentuk valuta asing (valas).
9. Surat Permintaan Pengesahan adalah surat permintaan penerbitan dokumen pengesahan atas realisasi yang telah diberikan oleh PHLN yang diajukan oleh PA/Kuasa PA kepada KPPN Khusus Jakarta VI.
10. Surat Pengganti Withdrawal Application yang selanjutnya disebut Surat Pengganti WA adalah surat pengganti permintaan pembayaran hibah yang diterbitkan/disahkan oleh KPPN Khusus.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7001, 'perka-16-2009', 15, 'lampiran', 'Lampiran hal. 7', NULL, 7, '11. Surat Perintah Pembukuan/Pengesahan yang selanjutnya disebut SP3 adalah surat perintah yang diterbitkan oleh KPPN Khusus selaku Kuasa Bendahara Umum Negara (yang fungsinya dipersamakan dengan Surat Perintah Membayar/Surat Perintah Pencairan Dana (SPM/SP2D)) kepada BI dan Satker untuk dibukukan/disahkan sebagai penerimaan dan pengeluaran dalam APBN atau realisasi penarikan dan hibah luar negeri (PHLN) melalui tata cara pembayaran langsung dan Letter Of Credit.
12. Pendapatan hibah Penerimaan pemerintah pusat berasal dari/untuk Badan/Lembaga dalam negeri atau perseorangan, pemerintah, Negara Asing, Badan/Lembaga Asing, Badan/Lembaga Internasional baik dalam bentuk devisa, Rupiah, maupun barang dan/atau jasa, termasuk tenaga ahli dan pelatihan yang tidak perlu dibayar/diterima kembali oleh pemerintah.
2014, No.1416 8
13. Belanja yang berasal dari hibah Pengeluaran pemerintah pusat dalam bentuk uang/barang atau jasa kepada pemerintah atau pemerintah lainnya, perusahaan daerah masyarakat dan organisasi kemasyarakatan yang secara spesifik telah ditetapkan peruntukannya, bersifat tidak wajib dan tidak mengikat, serta tidak secara terus menerus.
F. SISTEMATIKA Pedoman pengelolaan Hibah disusun dengan sistematika sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7001, '11. Surat Perintah Pembukuan/Pengesahan yang selanjutnya disebut SP3 adalah surat perintah yang diterbitkan oleh KPPN Khusus selaku Kuasa Bendahara Umum Negara (yang fungsinya dipersamakan dengan Surat Perintah Membayar/Surat Perintah Pencairan Dana (SPM/SP2D)) kepada BI dan Satker untuk dibukukan/disahkan sebagai penerimaan dan pengeluaran dalam APBN atau realisasi penarikan dan hibah luar negeri (PHLN) melalui tata cara pembayaran langsung dan Letter Of Credit.
12. Pendapatan hibah Penerimaan pemerintah pusat berasal dari/untuk Badan/Lembaga dalam negeri atau perseorangan, pemerintah, Negara Asing, Badan/Lembaga Asing, Badan/Lembaga Internasional baik dalam bentuk devisa, Rupiah, maupun barang dan/atau jasa, termasuk tenaga ahli dan pelatihan yang tidak perlu dibayar/diterima kembali oleh pemerintah.
2014, No.1416 8
13. Belanja yang berasal dari hibah Pengeluaran pemerintah pusat dalam bentuk uang/barang atau jasa kepada pemerintah atau pemerintah lainnya, perusahaan daerah masyarakat dan organisasi kemasyarakatan yang secara spesifik telah ditetapkan peruntukannya, bersifat tidak wajib dan tidak mengikat, serta tidak secara terus menerus.
F. SISTEMATIKA Pedoman pengelolaan Hibah disusun dengan sistematika sebagai berikut:', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7002, 'perka-16-2009', 16, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'BAB I : Pendahuluan BAB II : Pemahaman Hibah BAB III : Pengelolaan Hibah Yang Diterima Langsung Oleh BNPB BAB IV : Sistem Dan Prosedur Pelaksanaan Hibah Yang Diterima Langsung BAB V : Akuntansi Hibah yang diterima langsung Oleh BNPB BAB VI : Pelaporan Hibah BAB VII : Penutup 9 2014, No.1416 BAB II PEMAHAMAN HIBAH A. Pengertian Hibah adalah pendapatan/belanja pemerintah pusat yang berasal dari/untuk Badan/Lembaga dalam negeri atau perseorangan, pemerintah negara asing, badan/lembaga asing atau badan/lembaga internasional baik dalam bentuk devisa, Rupiah maupun barang dan/atau jasa, termasuk tenaga ahli dan pelatihan yang tidak perlu dibayar/diterima kembali, yang secara spesifik telah diterapkan peruntukannya, bersifat tidak wajib dan tidak mengikat, serta tidak secara terus menerus.
Pengelolaan hibah meliputi:
a. Pendapatan Hibah Pendapatan hibah adalah pendapatan pemerintah pusat yang berasal dari badan/lembaga dalam negeri atau perseorangan, pemerintah negara asing, badan/lembaga asing, badan/lembaga internasional baik dalam bentuk devisa, Rupiah maupun barang dan/atau jasa, termasuk tenaga ahli dan pelatihan yang tidak perlu dibayar kembali.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7002, 'BAB I : Pendahuluan BAB II : Pemahaman Hibah BAB III : Pengelolaan Hibah Yang Diterima Langsung Oleh BNPB BAB IV : Sistem Dan Prosedur Pelaksanaan Hibah Yang Diterima Langsung BAB V : Akuntansi Hibah yang diterima langsung Oleh BNPB BAB VI : Pelaporan Hibah BAB VII : Penutup 9 2014, No.1416 BAB II PEMAHAMAN HIBAH A. Pengertian Hibah adalah pendapatan/belanja pemerintah pusat yang berasal dari/untuk Badan/Lembaga dalam negeri atau perseorangan, pemerintah negara asing, badan/lembaga asing atau badan/lembaga internasional baik dalam bentuk devisa, Rupiah maupun barang dan/atau jasa, termasuk tenaga ahli dan pelatihan yang tidak perlu dibayar/diterima kembali, yang secara spesifik telah diterapkan peruntukannya, bersifat tidak wajib dan tidak mengikat, serta tidak secara terus menerus.
Pengelolaan hibah meliputi:
a. Pendapatan Hibah Pendapatan hibah adalah pendapatan pemerintah pusat yang berasal dari badan/lembaga dalam negeri atau perseorangan, pemerintah negara asing, badan/lembaga asing, badan/lembaga internasional baik dalam bentuk devisa, Rupiah maupun barang dan/atau jasa, termasuk tenaga ahli dan pelatihan yang tidak perlu dibayar kembali.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7003, 'perka-16-2009', 17, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'b. Belanja yang berasal dari Hibah Belanja yang berasal dari hibah adalah belanja pemerintah pusat dalam bentuk uang/barang atau jasa kepada pemerintah atau pemerintah lainnya, perusahaan daerah, masyarakat, dan organisasi kemasyarakatan, yang secara spesifik telah ditetapkan peruntukannya, bersifat tidak wajib dan tidak mengikat, serta tidak terus menerus.
B. KLASIFIKASI HIBAH Sumber Hibah:
Apabila hibah ditinjau dari sumber/asalnya maka dapat dibedakan menjadi:
1. Pendapatan Hibah dalam negeri
2. Pendapatan Hibah luar negeri Sumber/asal pendapatan Hibah dalam negeri dapat dibedakan atas:
1. Hibah dari Badan/Lembaga/Badan Usaha
2. Hibah dari kelompok Masyarakat/perorangan
3. Hibah dari Pemerintah Daerah Sedangkan sumber/asal pendapatan Hibah Luar Negeri dapat dibedakan menjadi:
1. Negara Asing
2. Lembaga Multilateral
3. Lembaga Keuangan dan Lembaga non keuangan asing; dan
4. Lembaga keuangan non asing yang berdomisili dan melakukan kegiatan usaha diluar wilayah negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7003, 'b. Belanja yang berasal dari Hibah Belanja yang berasal dari hibah adalah belanja pemerintah pusat dalam bentuk uang/barang atau jasa kepada pemerintah atau pemerintah lainnya, perusahaan daerah, masyarakat, dan organisasi kemasyarakatan, yang secara spesifik telah ditetapkan peruntukannya, bersifat tidak wajib dan tidak mengikat, serta tidak terus menerus.
B. KLASIFIKASI HIBAH Sumber Hibah:
Apabila hibah ditinjau dari sumber/asalnya maka dapat dibedakan menjadi:
1. Pendapatan Hibah dalam negeri
2. Pendapatan Hibah luar negeri Sumber/asal pendapatan Hibah dalam negeri dapat dibedakan atas:
1. Hibah dari Badan/Lembaga/Badan Usaha
2. Hibah dari kelompok Masyarakat/perorangan
3. Hibah dari Pemerintah Daerah Sedangkan sumber/asal pendapatan Hibah Luar Negeri dapat dibedakan menjadi:
1. Negara Asing
2. Lembaga Multilateral
3. Lembaga Keuangan dan Lembaga non keuangan asing; dan
4. Lembaga keuangan non asing yang berdomisili dan melakukan kegiatan usaha diluar wilayah negara Republik Indonesia.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7004, 'perka-16-2009', 18, 'lampiran', 'Lampiran hal. 10', NULL, 10, '2014, No.1416 10 C. Hibah yang langsung dikelola oleh BNPB Pada Tahun 2009 Bappenas bekerjasama dengan BNPB melaksanakan berbagai aspek pengurangan Resiko Bencana yang telah ditetapkan sebagai sasaran program SAFER COMMUNITY THROUGH DISASTER RISK REDUCTION (SCDRR) IN DEVELOPEMENT, yakni dukungan Hibah dari UNDP; adapun anggaran dan kegiatan dilakukan langsung oleh BNPB melalui program SCDRR sebagaimana yang telah disepakati dalam rapat Project Executive Board SCDRR dan telah dituangkan dalam Dokumen Naskah Perjanjian Kerjasama antara National Project Director (NPO) SCDRR dengan BNPB dan telah memperoleh nomor registrasi program SCDRR dari Departemen Keuangan.
- Bentuk Hibah Hibah diberikan dalam bentuk rupiah
- Peruntukannya:
Kegiatan yang dilaksanakan oleh BNPB dari hibah UNDP tersebut adalah untuk melaksanakan kegiatan Pengurangan Resiko Bencana (PRB).
11 2014, No.1416 BAB III PENGELOLAAN HIBAH YANG DITERIMA LANGSUNG OLEH BNPB A. PENGERTIAN Pengelolaan Hibah yang diterima langsung oleh BNPB adalah proses pencatatan, pelaporan, akuntansi dan pertanggung jawaban penerimaan dan belanja hibah dalam rangka penanganan bencana yang diterima dan dibelanjakan secara langsung oleh satker BNPB tanpa melalui mekanisme pencairan dana di KPPN. Pengelolaan Hibah ini sesuai ketentuan PMK Nomor 40/PMK.05/2009 diterima dan dibelanjakan pada tahun berjalan.
Setelah mendapatkan nomor registrasi, selanjutnya diproses dimasukan dalam APBN dengan menggunakan mekanisme revisi DIPA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7004, '2014, No.1416 10 C. Hibah yang langsung dikelola oleh BNPB Pada Tahun 2009 Bappenas bekerjasama dengan BNPB melaksanakan berbagai aspek pengurangan Resiko Bencana yang telah ditetapkan sebagai sasaran program SAFER COMMUNITY THROUGH DISASTER RISK REDUCTION (SCDRR) IN DEVELOPEMENT, yakni dukungan Hibah dari UNDP; adapun anggaran dan kegiatan dilakukan langsung oleh BNPB melalui program SCDRR sebagaimana yang telah disepakati dalam rapat Project Executive Board SCDRR dan telah dituangkan dalam Dokumen Naskah Perjanjian Kerjasama antara National Project Director (NPO) SCDRR dengan BNPB dan telah memperoleh nomor registrasi program SCDRR dari Departemen Keuangan.
- Bentuk Hibah Hibah diberikan dalam bentuk rupiah
- Peruntukannya:
Kegiatan yang dilaksanakan oleh BNPB dari hibah UNDP tersebut adalah untuk melaksanakan kegiatan Pengurangan Resiko Bencana (PRB).
11 2014, No.1416 BAB III PENGELOLAAN HIBAH YANG DITERIMA LANGSUNG OLEH BNPB A. PENGERTIAN Pengelolaan Hibah yang diterima langsung oleh BNPB adalah proses pencatatan, pelaporan, akuntansi dan pertanggung jawaban penerimaan dan belanja hibah dalam rangka penanganan bencana yang diterima dan dibelanjakan secara langsung oleh satker BNPB tanpa melalui mekanisme pencairan dana di KPPN. Pengelolaan Hibah ini sesuai ketentuan PMK Nomor 40/PMK.05/2009 diterima dan dibelanjakan pada tahun berjalan.
Setelah mendapatkan nomor registrasi, selanjutnya diproses dimasukan dalam APBN dengan menggunakan mekanisme revisi DIPA.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7005, 'perka-16-2009', 19, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'B. PEMANFAATAN HIBAH Pemanfaatan hibah yang diterima langsung oleh BNPB adalah hibah yang digunakan untuk penanganan pra bencana, tanggap darurat maupun rehabilitasi dan rekonstruksi pasca bencana.
C. PENDAPATAN HIBAH
1. Pendapatan hibah adalah penerimaan hibah baik dari dalam maupun dari luar negeri yang dikelola langsung oleh satker BNPB yang terdiri dari hibah langsung dan hibah yang diterima melalui perjanjian dengan pemberi hibah.
2. Hibah yang diterima langsung adalah hibah yang diterima tanpa melalui perjanjian dengan pemberi hibah. Hibah ini dapat diterima dari dalam maupun luar negeri baik dari masyarakat, lembaga non pemerintah maupun pemerintah negara tertentu.
3. Hibah yang diterima melaui perjanjian dengan pemberi hibah baik dari dalam maupun luar negeri. Perjanjian hibah ini dilakukan oleh Kepala BNPB atau oleh Menteri Keuangan sebagaimana diatur dalam peraturan pemerintah No. 02 Tahun 2006 tentang tata cara pengadaan pinjaman hibah dan/atau penerimaan serta penerusan pinjaman dan/atau hibah luar negeri.
D. Pencatatan Hibah Pendapatan Hibah wajib dicatat dan diadministrasikan dengan baik. Setelah hibah diotorisasi oleh Kepala Badan Nasional Penanggulangan Bencana atau setelah perjanjian hibah ditanda tangani maka selanjutnya Biro Keuangan mencatat dalam buku hibah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7005, 'B. PEMANFAATAN HIBAH Pemanfaatan hibah yang diterima langsung oleh BNPB adalah hibah yang digunakan untuk penanganan pra bencana, tanggap darurat maupun rehabilitasi dan rekonstruksi pasca bencana.
C. PENDAPATAN HIBAH
1. Pendapatan hibah adalah penerimaan hibah baik dari dalam maupun dari luar negeri yang dikelola langsung oleh satker BNPB yang terdiri dari hibah langsung dan hibah yang diterima melalui perjanjian dengan pemberi hibah.
2. Hibah yang diterima langsung adalah hibah yang diterima tanpa melalui perjanjian dengan pemberi hibah. Hibah ini dapat diterima dari dalam maupun luar negeri baik dari masyarakat, lembaga non pemerintah maupun pemerintah negara tertentu.
3. Hibah yang diterima melaui perjanjian dengan pemberi hibah baik dari dalam maupun luar negeri. Perjanjian hibah ini dilakukan oleh Kepala BNPB atau oleh Menteri Keuangan sebagaimana diatur dalam peraturan pemerintah No. 02 Tahun 2006 tentang tata cara pengadaan pinjaman hibah dan/atau penerimaan serta penerusan pinjaman dan/atau hibah luar negeri.
D. Pencatatan Hibah Pendapatan Hibah wajib dicatat dan diadministrasikan dengan baik. Setelah hibah diotorisasi oleh Kepala Badan Nasional Penanggulangan Bencana atau setelah perjanjian hibah ditanda tangani maka selanjutnya Biro Keuangan mencatat dalam buku hibah.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7006, 'perka-16-2009', 20, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'Pada saat hibah ini diterima maka hibah belum masuk dalam APBN, karena diterima pada saat tahun anggaran sedang berjalan, oleh karena itu wajib dimasukan dalam APBN dengan menggunakan mekanisme Revisi DIPA.
2014, No.1416 12 E. Registrasi Hibah Sebelum dilakukan revisi DIPA maka BNPB wajib mencatatkan hibah tersebut ke Direktorat Jenderal Pengelolaan Utang Departemen Keuangan (DJPU). Untuk keperluan tersebut Biro Keuangan BNPB setelah melakukan pencatatan hibah, menyiapkan dokumen hibah yang diperlukan untuk mencatatkan hibah tersebut ke DJPU. Kepala Badan menyampaikan laporan penerimaan hibah dengan dilampiri permohonan registrasi hibah kepada Menteri Keuangan cq. Ditjen. Pengelolaan utang untuk mendapatkan register terhadap penerimaan hibah.
F. Revisi DIPA Sebelum mengajukan revisi DIPA maka BNPB wajib mencatatkan hibah tersebut ke DJPU setelah menerbikan nomor register atas hibah yang diterima oleh BNPB mengajukan usulan revisi Satuan Anggaran Per Satuan Kerja (SAPSK) ke Direktorat Jenderal Anggaran Departemen Keuangan (DJA), atas usulan tersebut DJA menerbitkan revisi SAPSK. Sesuai dengan revisi SAPSK, BNPB mengajukan usulan revisi DIPA ke Direktorat Jenderal Perbendaharaan Departemen Keuangan (DJPBN), selanjutnya DJPBN menerbitkan revisi DIPA berupa penambahan pagu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7006, 'Pada saat hibah ini diterima maka hibah belum masuk dalam APBN, karena diterima pada saat tahun anggaran sedang berjalan, oleh karena itu wajib dimasukan dalam APBN dengan menggunakan mekanisme Revisi DIPA.
2014, No.1416 12 E. Registrasi Hibah Sebelum dilakukan revisi DIPA maka BNPB wajib mencatatkan hibah tersebut ke Direktorat Jenderal Pengelolaan Utang Departemen Keuangan (DJPU). Untuk keperluan tersebut Biro Keuangan BNPB setelah melakukan pencatatan hibah, menyiapkan dokumen hibah yang diperlukan untuk mencatatkan hibah tersebut ke DJPU. Kepala Badan menyampaikan laporan penerimaan hibah dengan dilampiri permohonan registrasi hibah kepada Menteri Keuangan cq. Ditjen. Pengelolaan utang untuk mendapatkan register terhadap penerimaan hibah.
F. Revisi DIPA Sebelum mengajukan revisi DIPA maka BNPB wajib mencatatkan hibah tersebut ke DJPU setelah menerbikan nomor register atas hibah yang diterima oleh BNPB mengajukan usulan revisi Satuan Anggaran Per Satuan Kerja (SAPSK) ke Direktorat Jenderal Anggaran Departemen Keuangan (DJA), atas usulan tersebut DJA menerbitkan revisi SAPSK. Sesuai dengan revisi SAPSK, BNPB mengajukan usulan revisi DIPA ke Direktorat Jenderal Perbendaharaan Departemen Keuangan (DJPBN), selanjutnya DJPBN menerbitkan revisi DIPA berupa penambahan pagu.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7007, 'perka-16-2009', 21, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'G. Belanja Hibah Bersamaan dengan proses registasi hibah di DJPU dan revisi DIPA di DJPBN, BNPB dapat melaksanakan kegiatan yang didanai dari hibah tersebut. Sesuai dengan kebutuhan dilapangan, maka hibah tersebut dapat digunakan untuk penanganan bencana tahap pra bencana, tanggap darurat dan pasca bencana. Untuk kegiatan penanganan bencana tersebut hibah dapat dikelompokan kedalam jenis belanja pegawai, belanja barang, belanja modal maupun belanja bantuan sosial. Pengelompokan hibah kedalam jenis belanja tersebut dilaksanakan sesuai dengan kebutuhan dilapangan atau sesuai dengan perjanjian dengan pemberi hibah.
H. Proses penerbitan Surat Perintah Pembukuan/Pengesahan Setelah kegiatan yang dibiayai dari dana hibah dilaksanakan maka proses selanjutnya adalah pengesahan belanja hibah oleh KPPN (KPPN Khusus).
Berdasarkan bukti-bukti pengeluaran belanja hibah, Biro Keuangan menyusun Surat Perintah Pembukuan/pengesahan belanja beserta dokumen pendukung untuk disampaikan ke KPPN (KPPN Khusus).
- Kementerian Negara/Lembaga BNPB merealisasikan hibah dan menatausahakan dokumen-dokumen realisasi hibah. Berdasarkan realisasi hibah, Kementerian Negara/Lembaga membuat dokumen pengesahan berupa Surat Perintah Pengesahan atas realisasi hibah langsung yang diterima oleh Kuasa Pengguna Anggaran (KPA) untuk disampaikan kepada KPPN Khusus Jakarta VI dengan melampirkan dokumen pendukung berupa :
13 2014, No.1416');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7007, 'G. Belanja Hibah Bersamaan dengan proses registasi hibah di DJPU dan revisi DIPA di DJPBN, BNPB dapat melaksanakan kegiatan yang didanai dari hibah tersebut. Sesuai dengan kebutuhan dilapangan, maka hibah tersebut dapat digunakan untuk penanganan bencana tahap pra bencana, tanggap darurat dan pasca bencana. Untuk kegiatan penanganan bencana tersebut hibah dapat dikelompokan kedalam jenis belanja pegawai, belanja barang, belanja modal maupun belanja bantuan sosial. Pengelompokan hibah kedalam jenis belanja tersebut dilaksanakan sesuai dengan kebutuhan dilapangan atau sesuai dengan perjanjian dengan pemberi hibah.
H. Proses penerbitan Surat Perintah Pembukuan/Pengesahan Setelah kegiatan yang dibiayai dari dana hibah dilaksanakan maka proses selanjutnya adalah pengesahan belanja hibah oleh KPPN (KPPN Khusus).
Berdasarkan bukti-bukti pengeluaran belanja hibah, Biro Keuangan menyusun Surat Perintah Pembukuan/pengesahan belanja beserta dokumen pendukung untuk disampaikan ke KPPN (KPPN Khusus).
- Kementerian Negara/Lembaga BNPB merealisasikan hibah dan menatausahakan dokumen-dokumen realisasi hibah. Berdasarkan realisasi hibah, Kementerian Negara/Lembaga membuat dokumen pengesahan berupa Surat Perintah Pengesahan atas realisasi hibah langsung yang diterima oleh Kuasa Pengguna Anggaran (KPA) untuk disampaikan kepada KPPN Khusus Jakarta VI dengan melampirkan dokumen pendukung berupa :
13 2014, No.1416', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7008, 'perka-16-2009', 22, 'lampiran', 'Lampiran hal. 13', NULL, 13, 'a. Bukti transfer dana Notice of Disburstment (NoD/DA) dari PHLN dan/atau rekening koran atas rekening tujuan/penerima hibah langsung yang disetujui Bendahara Umum Negara dan yang disahkan oleh Penguna Anggaran (PA)/Kuasa Pengguna Anggaran (KPA)/Pejabat Pembuat Komitmen (PPK);
b. Rekening koran atas rekening tujuan/penerimaan Hibah Luar Negeri dari Bank Sentral atau Bank Umum yang disetujui Bendahara Umum Negara dan disahkan oleh PA/Kuasa PA/PPK;
c. Surat Pernyataan Tanggung Jawab Mutlak (SPTJM) dari pengguna Anggaran/Kuasa PA/PPK
- Kementerian Negara/Lembaga/BNPB akan mencatat realisasi belanja yang bersumber dari Hibah berdasarkan SP-Pengesahan dan SP3 untuk kemudian dilaporkan dalam Laporan Realisasi Anggaran Belanja yang bersumber dari Pendapatan Hibah. Kementerian Negara/Lembaga BNPB juga mencatat perolehan Aset Tetap dalam Neraca atas Belanja Modal yang bersumber dari Hibah.
I. Pendapatan Hibah berupa aset tetap atau barang BNPB dapat menerima hibah berupa asset tetap yang terdiri dari asset untuk pemerintah pusat yang dalam hal ini akan menjadi barang milk/kekayaan Negara yang dikuasai oleh BNPB atau diterus hibahkan kepada pemerintah daerah atau lembaga non pemerintah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7008, 'a. Bukti transfer dana Notice of Disburstment (NoD/DA) dari PHLN dan/atau rekening koran atas rekening tujuan/penerima hibah langsung yang disetujui Bendahara Umum Negara dan yang disahkan oleh Penguna Anggaran (PA)/Kuasa Pengguna Anggaran (KPA)/Pejabat Pembuat Komitmen (PPK);
b. Rekening koran atas rekening tujuan/penerimaan Hibah Luar Negeri dari Bank Sentral atau Bank Umum yang disetujui Bendahara Umum Negara dan disahkan oleh PA/Kuasa PA/PPK;
c. Surat Pernyataan Tanggung Jawab Mutlak (SPTJM) dari pengguna Anggaran/Kuasa PA/PPK
- Kementerian Negara/Lembaga/BNPB akan mencatat realisasi belanja yang bersumber dari Hibah berdasarkan SP-Pengesahan dan SP3 untuk kemudian dilaporkan dalam Laporan Realisasi Anggaran Belanja yang bersumber dari Pendapatan Hibah. Kementerian Negara/Lembaga BNPB juga mencatat perolehan Aset Tetap dalam Neraca atas Belanja Modal yang bersumber dari Hibah.
I. Pendapatan Hibah berupa aset tetap atau barang BNPB dapat menerima hibah berupa asset tetap yang terdiri dari asset untuk pemerintah pusat yang dalam hal ini akan menjadi barang milk/kekayaan Negara yang dikuasai oleh BNPB atau diterus hibahkan kepada pemerintah daerah atau lembaga non pemerintah.', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7009, 'perka-16-2009', 23, 'lampiran', 'Lampiran hal. 13', NULL, 13, 'Hibah berupa asset tetap yang akan menjadi asset BNPB atau menjadi barang Milik Negara (BMN) yang menjadi asset BNPB maka sebelum asset dicatatkan dalam Sistem Informasi Manajemen Akuntansi Barang Milik Negara (SIMAK BMN) maka akan dibuatkan berita Acara Serah Terima Asset, selanjutnya berdasarkan berita acara ini bagian keuangan mencatat dalam buku pendapatan hibah. Kepala BNPB menyampaikan Surat Pernyataan Telah Menerima Hibah Langsung (SPTMHL) dalam bentuk asset tetap kepada DJPU untuk mendapatkan register, berdasarkan register dari DJPU maka BNPB mencatat asset tetap tersebut dalam sistem BMKN.
Hibah berupa asset tetap yang diterus hibahkan ke Pemerintah Daerah dan atau ke Lembaga non Pemerintah. Atas penerimaan ini BNPB menandatangani Berita Acara Serah Terima Asset bersama pemberi hibah dan menyampaikan SPTMHL ke DJPU untuk mendapatkan register dan mencatat dalam sistem BHMN. Kemudian mengajukan permohonan penghapusan asset kepada Menteri Keuangan. selanjutnya berdasarkan ijin penghapusan dari Menteri Keuangan dapat dilakukan Berita Acara Serah Terima Hibah yang ditandatangani oleh kepala BNPB bersama penerima hibah sebagai bukti penyerahan hibah.
DJPU akan mencatat realisasi Pendapatan Hibah berdasarkan Surat Perintah Pengesahan Hibah dan SP3 yang disampaikan oleh KPPN Khusus Jakarta VI.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7009, 'Hibah berupa asset tetap yang akan menjadi asset BNPB atau menjadi barang Milik Negara (BMN) yang menjadi asset BNPB maka sebelum asset dicatatkan dalam Sistem Informasi Manajemen Akuntansi Barang Milik Negara (SIMAK BMN) maka akan dibuatkan berita Acara Serah Terima Asset, selanjutnya berdasarkan berita acara ini bagian keuangan mencatat dalam buku pendapatan hibah. Kepala BNPB menyampaikan Surat Pernyataan Telah Menerima Hibah Langsung (SPTMHL) dalam bentuk asset tetap kepada DJPU untuk mendapatkan register, berdasarkan register dari DJPU maka BNPB mencatat asset tetap tersebut dalam sistem BMKN.
Hibah berupa asset tetap yang diterus hibahkan ke Pemerintah Daerah dan atau ke Lembaga non Pemerintah. Atas penerimaan ini BNPB menandatangani Berita Acara Serah Terima Asset bersama pemberi hibah dan menyampaikan SPTMHL ke DJPU untuk mendapatkan register dan mencatat dalam sistem BHMN. Kemudian mengajukan permohonan penghapusan asset kepada Menteri Keuangan. selanjutnya berdasarkan ijin penghapusan dari Menteri Keuangan dapat dilakukan Berita Acara Serah Terima Hibah yang ditandatangani oleh kepala BNPB bersama penerima hibah sebagai bukti penyerahan hibah.
DJPU akan mencatat realisasi Pendapatan Hibah berdasarkan Surat Perintah Pengesahan Hibah dan SP3 yang disampaikan oleh KPPN Khusus Jakarta VI.', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7010, 'perka-16-2009', 24, 'lampiran', 'Lampiran hal. 14', NULL, 14, '2014, No.1416 14 Ketentuan lebih lanjut mengenai tatacara mekanisme pengesahan terhadap hibah yang diterima langsung oleh BNPB diatur dalam Peraturan Direktur Jenderal Perbendaharaan (No PER-67/PB/2006).
Hibah Barang atau Jasa  BNPB melakukan penataan dokumen hibah  Membuat Surat Pernyataan Telah Menerima Hibah BNPB Langsung (SPTMHL)  Membuat SPH BJ untuk diungkapkan dalam CaLK Pelaksanaan hibah berbentuk barang atau jasa yang diterima secara langsung oleh BNPB dilaksanakan dengan prosedur sebagai berikut:
a. BNPB yang telah menerima hibah langsung berupa barang atau jasa wajib menatausahakan dokumen-dokumen pendukung terkait penerimaan hibah dan mencatat penerimaan hibah berupa Barang kedalam Neraca sebagai penambahan Aset Tetap yang bersumber dari Hibah. BNPB membuat Surat Pernyataan Telah Menerima Hibah Berupa Barang atau Jasa yang ditandatangani oleh Kuasa Pengguna Anggaran dan Surat Pengesahan Hibah berupa Barang atau Jasa (SPH-BJ) berdasarkan dokumen pendukung tersebut (format terlampir). SPH-BJ disertai Surat Pernyataan Telah Menerima Hibah Berupa Barang atau Jasa disampaikan kepada Direktorat Jenderal Pengelolaan Utang Departemen Keuangan untuk dilakukan pengesahan atas realisasi hibah berupa barang atau jasa.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7010, '2014, No.1416 14 Ketentuan lebih lanjut mengenai tatacara mekanisme pengesahan terhadap hibah yang diterima langsung oleh BNPB diatur dalam Peraturan Direktur Jenderal Perbendaharaan (No PER-67/PB/2006).
Hibah Barang atau Jasa  BNPB melakukan penataan dokumen hibah  Membuat Surat Pernyataan Telah Menerima Hibah BNPB Langsung (SPTMHL)  Membuat SPH BJ untuk diungkapkan dalam CaLK Pelaksanaan hibah berbentuk barang atau jasa yang diterima secara langsung oleh BNPB dilaksanakan dengan prosedur sebagai berikut:
a. BNPB yang telah menerima hibah langsung berupa barang atau jasa wajib menatausahakan dokumen-dokumen pendukung terkait penerimaan hibah dan mencatat penerimaan hibah berupa Barang kedalam Neraca sebagai penambahan Aset Tetap yang bersumber dari Hibah. BNPB membuat Surat Pernyataan Telah Menerima Hibah Berupa Barang atau Jasa yang ditandatangani oleh Kuasa Pengguna Anggaran dan Surat Pengesahan Hibah berupa Barang atau Jasa (SPH-BJ) berdasarkan dokumen pendukung tersebut (format terlampir). SPH-BJ disertai Surat Pernyataan Telah Menerima Hibah Berupa Barang atau Jasa disampaikan kepada Direktorat Jenderal Pengelolaan Utang Departemen Keuangan untuk dilakukan pengesahan atas realisasi hibah berupa barang atau jasa.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7011, 'perka-16-2009', 25, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'b. DJPU mengesahkan SPH-BJ yang disampaikan BNPB untuk dijadikan dasar pembukuan transaksi Pendapatan Hibah berupa Barang atau Jasa oleh DJPU. SPH-BJ yang telah disahkan oleh DJPU sebagai dasar bagi Kementerian Negara/Lembaga untuk mengungkapkan penerimaan 15 2014, No.1416 hibah dalam bentuk barang atau jasa dalam Catatan atas Laporan Keuangan BNPB.
c. Transaksi Pendapatan Hibah berupa Barang atau Jasa ini merupakan transaksi non Kas, sehingga tidak perlu dilakukan pengesahan oleh KPPN dan tidak dilaporkan dalam Laporan Arus Kas.
J. Pendapatan Hibah Berupa Jasa Penerimaan hibah berupa jasa wajib ditata usahakan dan di nilai dengan uang. Hibah ini juga dilaporkan ke DJPU dengan menggunakan SPTMHL untuk mendapat register.
2014, No.1416 16 BAB IV SISTEM DAN PROSEDUR PELAKSANAAN HIBAH YANG DITERIMA LANGSUNG A. Sistem Dan Prosedur Pelaksanaan Hibah Yang Diterima Langsung.
Hibah berupa kas pada BNPB BNPB Pelaksanaan hibah secara kas yang diterima secara langsung oleh BNPB dilaksanakan dengan prosedur sebagai berikut:
a. BNPB yang telah menerima hibah langsung berupa kas wajib menatausahakan dokumen-dokumen pendukung terkait penerimaan hibah. BNPB mengajukan ijin kepada Menteri Keuangan atas pembukaan rekening untuk menampung penerimaan hibah tersebut.
b. BNPB membuat pengesahan atas hibah yang diterimanya kepada Kuasa BUN dengan terlebih dahulu memintakan No.Register Hibah kepada DJPU dengan melampirkan NPHLN atau dokumen lain yang dipersamakan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7011, 'b. DJPU mengesahkan SPH-BJ yang disampaikan BNPB untuk dijadikan dasar pembukuan transaksi Pendapatan Hibah berupa Barang atau Jasa oleh DJPU. SPH-BJ yang telah disahkan oleh DJPU sebagai dasar bagi Kementerian Negara/Lembaga untuk mengungkapkan penerimaan 15 2014, No.1416 hibah dalam bentuk barang atau jasa dalam Catatan atas Laporan Keuangan BNPB.
c. Transaksi Pendapatan Hibah berupa Barang atau Jasa ini merupakan transaksi non Kas, sehingga tidak perlu dilakukan pengesahan oleh KPPN dan tidak dilaporkan dalam Laporan Arus Kas.
J. Pendapatan Hibah Berupa Jasa Penerimaan hibah berupa jasa wajib ditata usahakan dan di nilai dengan uang. Hibah ini juga dilaporkan ke DJPU dengan menggunakan SPTMHL untuk mendapat register.
2014, No.1416 16 BAB IV SISTEM DAN PROSEDUR PELAKSANAAN HIBAH YANG DITERIMA LANGSUNG A. Sistem Dan Prosedur Pelaksanaan Hibah Yang Diterima Langsung.
Hibah berupa kas pada BNPB BNPB Pelaksanaan hibah secara kas yang diterima secara langsung oleh BNPB dilaksanakan dengan prosedur sebagai berikut:
a. BNPB yang telah menerima hibah langsung berupa kas wajib menatausahakan dokumen-dokumen pendukung terkait penerimaan hibah. BNPB mengajukan ijin kepada Menteri Keuangan atas pembukaan rekening untuk menampung penerimaan hibah tersebut.
b. BNPB membuat pengesahan atas hibah yang diterimanya kepada Kuasa BUN dengan terlebih dahulu memintakan No.Register Hibah kepada DJPU dengan melampirkan NPHLN atau dokumen lain yang dipersamakan.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7012, 'perka-16-2009', 26, 'lampiran', 'Lampiran hal. 16', NULL, 16, 'c. Berdasarkan No.Register yang diberikan, DJPU menyampaikan Revisi DIPA Estimasi Pendapatan Hibah kepada DJA.
d. Berdasarkan No.Register yang diberikan, BNPB menyampaikan Revisi DIPA Belanja yang bersumber dari Hibah.
e. BNPB merealisasikan hibah dan menatausahakan dokumen-dokumen realisasi hibah. Berdasarkan realisasi hibah, BNPB membuat dokumen pengesahan berupa Surat Perintah Pengesahan 17 2014, No.1416 atas realisasi hibah langsung yang diterima oleh KPA/Kuasa PA untuk disampaikan kepada KPPN Khusus Jakarta VI dengan melampirkan dokumen pendukung berupa:  Bukti transfer dana (NOD/DA) dari PHLN dan/atau rekening koran atas rekening tujuan/penerima hibah langsung yang disetujui Bendahara Umum Negara dan yang disahkan oleh PA/Kuasa PA/PPK;  Rekening koran atas rekening tujuan/penerimaan Hibah Luar Negeri dari Bank Sentral atau Bank Umum yang disetujui Bendahara Umum Negara dan disahkan oleh PA/Kuasa PA/PPK;  Surat Pernyataan Tanggung Jawab Mutlak (SPTJM) dari pengguna Anggaran/Kuasa PA/PPK
f. KPPN Khusus Jakarta VI dapat mengesahkan realisasi hibah mendahului terbitnya revisi DIPA dengan menerbitkan SP3 sebagai dasar realisasi hibah (DIPA) dan Penerimaan APBN sebesar ekuivalen rupiah.
g. KPPN Khusus Jakarta VI menyampaikan Surat Perintah Pengesahan dan SP3 kepada DJPU.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7012, 'c. Berdasarkan No.Register yang diberikan, DJPU menyampaikan Revisi DIPA Estimasi Pendapatan Hibah kepada DJA.
d. Berdasarkan No.Register yang diberikan, BNPB menyampaikan Revisi DIPA Belanja yang bersumber dari Hibah.
e. BNPB merealisasikan hibah dan menatausahakan dokumen-dokumen realisasi hibah. Berdasarkan realisasi hibah, BNPB membuat dokumen pengesahan berupa Surat Perintah Pengesahan 17 2014, No.1416 atas realisasi hibah langsung yang diterima oleh KPA/Kuasa PA untuk disampaikan kepada KPPN Khusus Jakarta VI dengan melampirkan dokumen pendukung berupa:  Bukti transfer dana (NOD/DA) dari PHLN dan/atau rekening koran atas rekening tujuan/penerima hibah langsung yang disetujui Bendahara Umum Negara dan yang disahkan oleh PA/Kuasa PA/PPK;  Rekening koran atas rekening tujuan/penerimaan Hibah Luar Negeri dari Bank Sentral atau Bank Umum yang disetujui Bendahara Umum Negara dan disahkan oleh PA/Kuasa PA/PPK;  Surat Pernyataan Tanggung Jawab Mutlak (SPTJM) dari pengguna Anggaran/Kuasa PA/PPK
f. KPPN Khusus Jakarta VI dapat mengesahkan realisasi hibah mendahului terbitnya revisi DIPA dengan menerbitkan SP3 sebagai dasar realisasi hibah (DIPA) dan Penerimaan APBN sebesar ekuivalen rupiah.
g. KPPN Khusus Jakarta VI menyampaikan Surat Perintah Pengesahan dan SP3 kepada DJPU.', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7013, 'perka-16-2009', 27, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'h. BNPB akan mencatat realisasi belanja yang bersumber dari Hibah berdasarkan SP-Pengesahan dan SP3 untuk kemudian dilaporkan dalam Laporan Realisasi Anggaran Belanja yang bersumber dari Pendapatan Hibah. Kementerian Negara/Lembaga juga mencatat perolehan Aset Tetap dalam Neraca atas Belanja Modal yang bersumber dari Hibah.
i. DJPU akan mencatat realisasi Pendapatan Hibah berdasarkan Surat Perintah Pengesahan Hibah dan SP3 yang disampaikan oleh KPPN Khusus Jakarta VI.
Ketentuan lebih lanjut mengenai tatacara mekanisme pengesahan terhadap hibah yang diterima langsung oleh Kementerian Negara/ Lembaga diatur dalam Peraturan Direktur Jenderal Perbendaharaan.
B. Sistem dan Prosedur Rekonsiliasi Hibah Rekonsiliasi merupakan salah satu prosedur internal control untuk memastikan bahwa pendapatan hibah dan belanja hibah yang telah dicatat dengan angka yang sama antara BUN dan dengan Pengguna Anggaran/Kuasa Pengguna Anggaran Hibah. DJPU sebagai Pengguna Anggaran untuk Hibah melaksanakan rekonsiliasi untuk transaksi pendapatan hibah melalui mekanisme BUN dengan Direktorat Pengelolaan Kas Negara (Dit.PKN) Direktorat Jenderal Perbendaharaan dan KPPN Khusus Jakarta VI. Sedangkan DJPK melaksanakan rekonsiliasi untuk transaksi belanja hibah dengan Direktorat Pengelolaan Kas Negara (Dit.PKN) Direktorat Jenderal Perbendaharaan. Ketentuan lebih lanjut mengenai tatacara rekonsiliasi diatur dalam Peraturan Direktur Jenderal Perbendaharaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7013, 'h. BNPB akan mencatat realisasi belanja yang bersumber dari Hibah berdasarkan SP-Pengesahan dan SP3 untuk kemudian dilaporkan dalam Laporan Realisasi Anggaran Belanja yang bersumber dari Pendapatan Hibah. Kementerian Negara/Lembaga juga mencatat perolehan Aset Tetap dalam Neraca atas Belanja Modal yang bersumber dari Hibah.
i. DJPU akan mencatat realisasi Pendapatan Hibah berdasarkan Surat Perintah Pengesahan Hibah dan SP3 yang disampaikan oleh KPPN Khusus Jakarta VI.
Ketentuan lebih lanjut mengenai tatacara mekanisme pengesahan terhadap hibah yang diterima langsung oleh Kementerian Negara/ Lembaga diatur dalam Peraturan Direktur Jenderal Perbendaharaan.
B. Sistem dan Prosedur Rekonsiliasi Hibah Rekonsiliasi merupakan salah satu prosedur internal control untuk memastikan bahwa pendapatan hibah dan belanja hibah yang telah dicatat dengan angka yang sama antara BUN dan dengan Pengguna Anggaran/Kuasa Pengguna Anggaran Hibah. DJPU sebagai Pengguna Anggaran untuk Hibah melaksanakan rekonsiliasi untuk transaksi pendapatan hibah melalui mekanisme BUN dengan Direktorat Pengelolaan Kas Negara (Dit.PKN) Direktorat Jenderal Perbendaharaan dan KPPN Khusus Jakarta VI. Sedangkan DJPK melaksanakan rekonsiliasi untuk transaksi belanja hibah dengan Direktorat Pengelolaan Kas Negara (Dit.PKN) Direktorat Jenderal Perbendaharaan. Ketentuan lebih lanjut mengenai tatacara rekonsiliasi diatur dalam Peraturan Direktur Jenderal Perbendaharaan.', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7014, 'perka-16-2009', 28, 'lampiran', 'Lampiran hal. 18', NULL, 18, '2014, No.1416 18 BAB V AKUNTANSI HIBAH YANG DITERIMA LANGSUNG OLEH BNPB Pengertian Hibah yang diterima langsung oleh BNPB adalah Hibah yang belum dianggarkan dalam APBN dan dalam pelaksanaan penyalurannya langsung diterima oleh BNPB tanpa melalui mekanisme pencairan KPPN. Prosedur pencatatan atas transaksi hibah ini dapat dilaksanakan sebagai berikut :
a. Pada saat satker di BNPB telah menerima hibah atau sudah mendapatkan komitment dari donor atas pelaksanaan hibah misalnya sebesar Rp.10 M, dan dana hibah tersebut telah digunakan sesuai dengan kebutuhan dan berdasarkan peruntukan yang telah ditetapkan dan dapat di realisasikan dalam belanja dengan kode akun 51, 52, 53 dan 57 untuk selanjutnya satker melakukan registrasi atas hibah yang diterima kepada Direktorat Jenderal Pengelolaan Utang (DJPU) untuk mendapatkan No Register Hibah.
b. Atas Nomor Register yang telah diterbitkan oleh DJPU, DJPU mengusulkan Revisi DIPA atas Estimasi Pendapatan Hibah yang dialokasikan kepada DJA. Revisi DIPA yang telah terbit, maka DJPU akan membuat ayat jurnal Estimasi Pendapatan Hibah yang dialokasikan Rp. 10 M Utang Kepada KUN Rp. 10 M
c. Atas Nomor Register yang telah diterbitkan oleh DJPU, satuan kerja BNPB mengusulkan Revisi DIPA atas alokasi Belanja Barang yang akan digunakan berdasarkan dana yang bersumber dari Hibah. Atas Revisi DIPA yang telah terbit, Satker membuat ayat jurnal sebagai berikut :
Piutang dari KUN Rp. 10 M Allotment Belanja Barang Rp. 10 M');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7014, '2014, No.1416 18 BAB V AKUNTANSI HIBAH YANG DITERIMA LANGSUNG OLEH BNPB Pengertian Hibah yang diterima langsung oleh BNPB adalah Hibah yang belum dianggarkan dalam APBN dan dalam pelaksanaan penyalurannya langsung diterima oleh BNPB tanpa melalui mekanisme pencairan KPPN. Prosedur pencatatan atas transaksi hibah ini dapat dilaksanakan sebagai berikut :
a. Pada saat satker di BNPB telah menerima hibah atau sudah mendapatkan komitment dari donor atas pelaksanaan hibah misalnya sebesar Rp.10 M, dan dana hibah tersebut telah digunakan sesuai dengan kebutuhan dan berdasarkan peruntukan yang telah ditetapkan dan dapat di realisasikan dalam belanja dengan kode akun 51, 52, 53 dan 57 untuk selanjutnya satker melakukan registrasi atas hibah yang diterima kepada Direktorat Jenderal Pengelolaan Utang (DJPU) untuk mendapatkan No Register Hibah.
b. Atas Nomor Register yang telah diterbitkan oleh DJPU, DJPU mengusulkan Revisi DIPA atas Estimasi Pendapatan Hibah yang dialokasikan kepada DJA. Revisi DIPA yang telah terbit, maka DJPU akan membuat ayat jurnal Estimasi Pendapatan Hibah yang dialokasikan Rp. 10 M Utang Kepada KUN Rp. 10 M
c. Atas Nomor Register yang telah diterbitkan oleh DJPU, satuan kerja BNPB mengusulkan Revisi DIPA atas alokasi Belanja Barang yang akan digunakan berdasarkan dana yang bersumber dari Hibah. Atas Revisi DIPA yang telah terbit, Satker membuat ayat jurnal sebagai berikut :
Piutang dari KUN Rp. 10 M Allotment Belanja Barang Rp. 10 M', 'Lampiran hal. 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2009 tentang Pedoman Pengelolaan Hibah Langsung di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7015, 'perka-16-2009', 29, 'lampiran', 'Lampiran hal. 18', NULL, 18, 'd. Satker menerima hibah berupa kas sebesar Rp. 10 M dan telah digunakan untuk belanja barang sebesar Rp. 7 M. Atas realisasi pendapatan hibah ini, maka satker menyampaikan Surat Perintah Pengesahan Hibah (SP-Pengesahan Hibah) atas realisasi hibah tersebut.
e. KPPN menerbitkan SP3 Pengesahan Hibah yang disampaikan oleh satker atas realisasi hibah.
Atas transaksi ini KPPN akan membuat ayat jurnal transaksi sebagai berikut :
Pencatatan Revisi DIPA SAU Estimasi Pendapatan Hibah yang dialokasikan Rp. 10 M Utang Kepada KUN Rp. 10 M Piutang dari KUN Rp. 10 M Allotment Belanja Barang Rp. 10 M 19 2014, No.1416 Pengakuan Pendapatan SAU Utang Kepada KUN Rp. 10 M Pendapatan Hibah Rp. 10 M SAKUN Kas di BNPB Rp. 10 M Pendapatan Hibah Rp. 10 M Pengakuan Belanja SAU Belanja Barang Rp. 7 M Piutang dari KUN Rp. 7 M SAKUN Belanja Barang Rp. 7 M Kas di BNPB Rp. 7 M
f. Laporan yang dihasilkan dari masing-masing entitas akuntansi adalah sebagai berikut :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7015, 'd. Satker menerima hibah berupa kas sebesar Rp. 10 M dan telah digunakan untuk belanja barang sebesar Rp. 7 M. Atas realisasi pendapatan hibah ini, maka satker menyampaikan Surat Perintah Pengesahan Hibah (SP-Pengesahan Hibah) atas realisasi hibah tersebut.
e. KPPN menerbitkan SP3 Pengesahan Hibah yang disampaikan oleh satker atas realisasi hibah.
Atas transaksi ini KPPN akan membuat ayat jurnal transaksi sebagai berikut :
