INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7016, 'perka-16-2009', 30, 'lampiran', 'Lampiran hal. 19', NULL, 19, 'Laporan Realisasi Anggaran Perkiraan Satker DJPU KPPN Estimasi Pendapatan 0 10 M 10 M Hibah Realisasi Pendapatan 0 10 M 10 M Hibah Kelebihan/Kekurangan 0 0M 0M Allotment Belanja Barang 10 M - 10 M Realisasi Belanja Barang 7M - 7M Sisa Pagu 3M - 3M Laporan Neraca Perkiraan Satker DJPU KPPN Kas di BNPB 3M - 3M 2014, No.1416 20 Hibah berupa Barang atau Jasa Hibah berupa barang atau jasa adalah Hibah yang belum dianggarkan dalam APBN dan dalam pelaksanaan langsung diterima oleh Pemerintah Daerah (Pemda) (Belanja Hibah) atau satker (Pendapatan Hibah) tanpa melalui mekanisme pencairan melalui KPPN. Prosedur pencatatan atas transaksi hibah ini dapat dilaksanakana sebagai berikut :
1. Hibah Berupa Aset Tetap Pada saat Satker menghibahkan Aset Tetap kepada Pemda, maka setelah surat persetujuan penghapusan aset tetap telah disetujui oleh Direktorat Jenderal Kekayaan Negara (DJKN) dan Berita Acara Serah Terima Aset dari satker kepada Pemda telah ditandatangani, atas transaksi ini dilakukan pencatatan sebagai berikut :
Satker Satker akan mencatat penghapusan Aset Tetap melalui SIMAK BMN dan transaksi ini akan mengurangi nilai Neraca Aset Tetap sejumlah aset tetap yang telah dihibahkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7016, 'Laporan Realisasi Anggaran Perkiraan Satker DJPU KPPN Estimasi Pendapatan 0 10 M 10 M Hibah Realisasi Pendapatan 0 10 M 10 M Hibah Kelebihan/Kekurangan 0 0M 0M Allotment Belanja Barang 10 M - 10 M Realisasi Belanja Barang 7M - 7M Sisa Pagu 3M - 3M Laporan Neraca Perkiraan Satker DJPU KPPN Kas di BNPB 3M - 3M 2014, No.1416 20 Hibah berupa Barang atau Jasa Hibah berupa barang atau jasa adalah Hibah yang belum dianggarkan dalam APBN dan dalam pelaksanaan langsung diterima oleh Pemerintah Daerah (Pemda) (Belanja Hibah) atau satker (Pendapatan Hibah) tanpa melalui mekanisme pencairan melalui KPPN. Prosedur pencatatan atas transaksi hibah ini dapat dilaksanakana sebagai berikut :
