INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7018, 'perka-16-2009', 32, 'lampiran', 'Lampiran hal. 21', NULL, 21, 'Pengakuan Pendapatan Utang Kepada KUN Rp. 10 M Pendapatan Hibah Rp. 10 M Neraca dan Laporan Realisasi Anggaran dapat disajikan sebagai berikut :
Laporan Satker DJPU KPPN Neraca -
- Aset Tetap - 10 M - LRA Belanja
- Belanja Hibah Non Kas - 10 M -
3. Pendapatan Hibah Berupa Jasa Satker yang ada di BNPB Pada saat Satker menerima hibah berupa jasa, maka satker wajib menatausahakan dokumen-dokumen terkait transaksi realisasi hibah.
Penatausahaan dokumen tersebut dimaksudkan agar dapat dinilai jumlah hibah yang diterima. Berdasarkan jumlah hibah yang diterima, maka satker mencatat transaksi tersebut dalam catatan atas Laporan 2014, No.1416 22 Keuangan. Satker menyampaikan SPTMHL Barang/Jasa kepada DJPU untuk dilakukan pengesahan atas Pedapatan Hibah.
DJPU Atas transaksi pendapatan hibah berupa jasa ini, satker menginformasikan kepada DJPU berupa SPTMHL Barang/Jasa disertai dengan dokumen pendukung. Berdasarkan informasi ini DJPU akan mencatat dalam ayat jurnal sbb:
Utang Kepada KUN Rp. 10 M Pendapatan Hibah non kas Rp. 10 M Laporan Realisas Anggaran dapat disajikan sebagai berikut :
Laporan Satker DJPU KPPN
- Catatan Atas Laporan Keuangan 10 M - LRA Pendapatan');
