INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7037, 'perka-16-2012', 4, 'pasal', 'Pasal 1', NULL, 2, 'Pedoman Pengelolaan Gudang Logistik dan Peralatan dalam Status Keadaan Darurat Bencana merupakan panduan atau acuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/Lembaga dan pemangku kepentingan penanggulangan bencana agar pelaksanaan pengelolaan bantuan logistik pada status keadaan darurat dapat dilaksanakan dengan lancar, tertib, terpadu, aman dan dapat dipertanggungjawabkan.');
