INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7038, 'perka-16-2012', 5, 'pasal', 'Pasal 2', NULL, 2, 'Pedoman Pengelolaan Gudang Logistik dan Peralatan dalam Status Keadaan Darurat Bencana sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian tak terpisahkan dari peraturan Kepala Badan Nasional Penanggulangan Bencana ini.');
