INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7040, 'perka-16-2012', 7, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'LAMPIRAN Pasal 4 Pada saat berlakunya peraturan ini semua Peraturan Kepala Badan Nasional Penanggulangan Bencana yang berkaitan dengan pergudangan penanggulangan bencana dinyatakan tetap berlaku sepanjang tidak bertentangan atau belum dikeluarkan peraturan pelaksanaan baru berdasarkan peraturan ini.
