INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7043, 'perka-16-2014', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa Keprotokolan merupakan serangkaian kegiatan yang berkaitan dengan aturan dalam acara resmi yang meliputi tata tempat, tata upacara, tata penghormatan, rapat, kunjungan kerja, kunjungan tamu, jamuan, tata pakaian, standar dan prosedur pelayanan pimpinan sebagai bentuk penghormatan kepada seseorang sesuai dengan jabatan dan/atau kedudukannya dalam negara, pemerintahan, atau masyarakat di lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud pada huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7043, 'a. bahwa Keprotokolan merupakan serangkaian kegiatan yang berkaitan dengan aturan dalam acara resmi yang meliputi tata tempat, tata upacara, tata penghormatan, rapat, kunjungan kerja, kunjungan tamu, jamuan, tata pakaian, standar dan prosedur pelayanan pimpinan sebagai bentuk penghormatan kepada seseorang sesuai dengan jabatan dan/atau kedudukannya dalam negara, pemerintahan, atau masyarakat di lingkungan Badan Nasional Penanggulangan Bencana;
