INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7051, 'perka-16-2014', 9, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 6 November 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 31 Desember 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY 2014, No.2078 4 PETUNJUK PELAKSANAAN KEPROTOKOLAN DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Dalam Undang-Undang Republik Indonesia Nomor 9 Tahun 2010 tentang Keprotokolan dijelaskan bahwa Keprotokolan merupakan serangkaian kegiatan yang berkaitan dengan aturan dalam acara resmi yang meliputi Tata Tempat, Tata Upacara, dan Tata Penghormatan sebagai bentuk penghormatan kepada seseorang sesuai dengan jabatan dan/atau kedudukannya dalam negara, pemerintahan, atau masyarakat.
Badan Nasional Penanggulangan Bencana merupakan Lembaga');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7051, 'Ditetapkan di Jakarta pada tanggal 6 November 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 31 Desember 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY 2014, No.2078 4 PETUNJUK PELAKSANAAN KEPROTOKOLAN DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Dalam Undang-Undang Republik Indonesia Nomor 9 Tahun 2010 tentang Keprotokolan dijelaskan bahwa Keprotokolan merupakan serangkaian kegiatan yang berkaitan dengan aturan dalam acara resmi yang meliputi Tata Tempat, Tata Upacara, dan Tata Penghormatan sebagai bentuk penghormatan kepada seseorang sesuai dengan jabatan dan/atau kedudukannya dalam negara, pemerintahan, atau masyarakat.
Badan Nasional Penanggulangan Bencana merupakan Lembaga', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7052, 'perka-16-2014', 10, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'Pemerintah Non Kementerian yang dijabat oleh pejabat negara setingkat menteri atau Pejabat Negara/pimpinan dan anggota lembaga negara sebagaimana yang dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 dan Pejabat Negara yang secara tegas ditentukan dalam Undang-Undang. Badan Nasional Penanggulangan Bencana memiliki tugas pokok dan fungsi sesuai Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Sebagai lembaga pemerintah non kementerian yang didirikan pada tahun 2008, Badan Nasional Penanggulangan Bencana hingga saat ini belum memiliki aturan/tatanan keprotokolan sehingga pengetahuan maupun pengalaman tentang keprotokolan masih minim. Oleh karena itu untuk mewujudkan kegiatan yang berkaitan dengan aturan dalam acara resmi yang meliputi Tata Tempat, Tata Upacara, dan Tata Penghormatan sebagai bentuk penghormatan kepada seseorang sesuai dengan jabatan dan/atau kedudukannya dalam negara, pemerintahan, atau masyarakat, maka Badan Nasional Penanggulangan Bencana perlu menyusun suatu pedoman terkait dengan kegiatan keprotokolan dan pelayanan pimpinan.
B. Dasar
1. Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Undang-Undang Republik Indonesia Nomor 9 Tahun 2010 tentang Keprotokolan.
3. Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
5 2014, No.2078 C. Maksud dan Tujuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7052, 'Pemerintah Non Kementerian yang dijabat oleh pejabat negara setingkat menteri atau Pejabat Negara/pimpinan dan anggota lembaga negara sebagaimana yang dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 dan Pejabat Negara yang secara tegas ditentukan dalam Undang-Undang. Badan Nasional Penanggulangan Bencana memiliki tugas pokok dan fungsi sesuai Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Sebagai lembaga pemerintah non kementerian yang didirikan pada tahun 2008, Badan Nasional Penanggulangan Bencana hingga saat ini belum memiliki aturan/tatanan keprotokolan sehingga pengetahuan maupun pengalaman tentang keprotokolan masih minim. Oleh karena itu untuk mewujudkan kegiatan yang berkaitan dengan aturan dalam acara resmi yang meliputi Tata Tempat, Tata Upacara, dan Tata Penghormatan sebagai bentuk penghormatan kepada seseorang sesuai dengan jabatan dan/atau kedudukannya dalam negara, pemerintahan, atau masyarakat, maka Badan Nasional Penanggulangan Bencana perlu menyusun suatu pedoman terkait dengan kegiatan keprotokolan dan pelayanan pimpinan.
B. Dasar
1. Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Undang-Undang Republik Indonesia Nomor 9 Tahun 2010 tentang Keprotokolan.
3. Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
5 2014, No.2078 C. Maksud dan Tujuan', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7053, 'perka-16-2014', 11, 'lampiran', 'Lampiran hal. 5', NULL, 5, '1. Maksud Pedoman Keprotokolan ini dimaksudkan untuk dapat digunakan sebagai acuan dalam prosedur teknis pelaksanaan kegiatan keprotokolan di lingkungan Badan Nasional Penanggulangan Bencana.
2. Tujuan Memberikan pedoman penyelenggaraan suatu acara agar berjalan tertib, rapi, lancar, dan teratur sesuai dengan ketentuan dan kebiasaan yang berlaku, baik secara nasional maupun internasional sehingga kegiatan keprotokolan di lingkungan Badan Nasional Penanggulangan Bencana dapat terselenggara secara efektif, efisien dan sistematis.
D. Ruang Lingkup Pedoman Keprotokolan di lingkungan Badan Nasional Penanggulangan Bencana ini meliputi ketentuan umum, tata tempat, tata upacara dan tata penghormatan, serta standar dan prosedur pelayanan pimpinan.
E. Pengertian.
1. Keprotokolan. Keprotokolan adalah serangkaian kegiatan yang berkaitan dengan aturan dalam acara kenegaraan atau acara resmi yang meliputi tata tempat, tata upacara, dan tata penghormatan sebagai bentuk penghormatan kepada seseorang sesuai dengan jabatan dan/atau kedudukannya dalam negara, pemerintahan, atau masyarakat. Secara universal keprotokolan juga mengandung pengertian-pengertian sebagai berikut:
a. Kumpulan tatacara pengaturan upacara yang diikuti oleh semua pergaulan antar Kepala Negara dan Menteri-Menteri.
b. Tata tertib/sopan santun di dalam pergaulan Internasional.
c. Pedoman tatacara pergaulan Internasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7053, '1. Maksud Pedoman Keprotokolan ini dimaksudkan untuk dapat digunakan sebagai acuan dalam prosedur teknis pelaksanaan kegiatan keprotokolan di lingkungan Badan Nasional Penanggulangan Bencana.
2. Tujuan Memberikan pedoman penyelenggaraan suatu acara agar berjalan tertib, rapi, lancar, dan teratur sesuai dengan ketentuan dan kebiasaan yang berlaku, baik secara nasional maupun internasional sehingga kegiatan keprotokolan di lingkungan Badan Nasional Penanggulangan Bencana dapat terselenggara secara efektif, efisien dan sistematis.
D. Ruang Lingkup Pedoman Keprotokolan di lingkungan Badan Nasional Penanggulangan Bencana ini meliputi ketentuan umum, tata tempat, tata upacara dan tata penghormatan, serta standar dan prosedur pelayanan pimpinan.
E. Pengertian.
1. Keprotokolan. Keprotokolan adalah serangkaian kegiatan yang berkaitan dengan aturan dalam acara kenegaraan atau acara resmi yang meliputi tata tempat, tata upacara, dan tata penghormatan sebagai bentuk penghormatan kepada seseorang sesuai dengan jabatan dan/atau kedudukannya dalam negara, pemerintahan, atau masyarakat. Secara universal keprotokolan juga mengandung pengertian-pengertian sebagai berikut:
a. Kumpulan tatacara pengaturan upacara yang diikuti oleh semua pergaulan antar Kepala Negara dan Menteri-Menteri.
b. Tata tertib/sopan santun di dalam pergaulan Internasional.
c. Pedoman tatacara pergaulan Internasional.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7054, 'perka-16-2014', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'd. Petugas yang melaksanakan serta bertanggung jawab atas terlaksananya penerapan tatacara pengaturan/pelaksanaan suatu upacara.
e. Ikut menentukan terciptanya suasana/iklim yang mempengaruhi keberhasilan suatu tugas.
2014, No.2078 6
f. Menciptakan tata pergaulan yang mendekatkan satu sama lain dan dapat diterima oleh semua pihak, walaupun mengandung unsur-unsur yang membatasi gerak pribadi.
g. Terciptanya suatu upacara yang khidmat, tertib dan lancar.
h. Terciptanya pemberian perlindungan.
i. Terciptanya ketertiban dan rasa aman dalam menjalankan tugas.
2. Protokol. Protokol adalah pengaturan yang berisi norma-norma atau kebiasaan yang dianut dan/atau diyakini dalam Acara Kenegaraan atau Acara Resmi seseorang yang melakukan kegiatan keprotokolan.
3. Protokol Badan Nasional Penanggulangan Bencana (BNPB).
Protokol BNPB adalah pelaksana keprotokolan pada unit Sekretaris Utama dan sebagai koordinator keprotokolan di lingkungan BNPB.
4. Acara Kenegaraan. Acara Kenegaraan adalah acara yang diatur dan dilaksanakan oleh panitia negara secara terpusat, dihadiri oleh Presiden dan/atau Wakil Presiden, serta Pejabat Negara dan undangan lain.
5. Acara Resmi. Acara Resmi adalah acara yang diatur dan dilaksanakan oleh pemerintah atau lembaga negara dalam melaksanakan tugas dan fungsi tertentu dan dihadiri oleh Pejabat Negara dan/atau Pejabat Pemerintahan serta undangan lain.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7054, 'd. Petugas yang melaksanakan serta bertanggung jawab atas terlaksananya penerapan tatacara pengaturan/pelaksanaan suatu upacara.
e. Ikut menentukan terciptanya suasana/iklim yang mempengaruhi keberhasilan suatu tugas.
2014, No.2078 6
f. Menciptakan tata pergaulan yang mendekatkan satu sama lain dan dapat diterima oleh semua pihak, walaupun mengandung unsur-unsur yang membatasi gerak pribadi.
g. Terciptanya suatu upacara yang khidmat, tertib dan lancar.
h. Terciptanya pemberian perlindungan.
i. Terciptanya ketertiban dan rasa aman dalam menjalankan tugas.
2. Protokol. Protokol adalah pengaturan yang berisi norma-norma atau kebiasaan yang dianut dan/atau diyakini dalam Acara Kenegaraan atau Acara Resmi seseorang yang melakukan kegiatan keprotokolan.
3. Protokol Badan Nasional Penanggulangan Bencana (BNPB).
Protokol BNPB adalah pelaksana keprotokolan pada unit Sekretaris Utama dan sebagai koordinator keprotokolan di lingkungan BNPB.
4. Acara Kenegaraan. Acara Kenegaraan adalah acara yang diatur dan dilaksanakan oleh panitia negara secara terpusat, dihadiri oleh Presiden dan/atau Wakil Presiden, serta Pejabat Negara dan undangan lain.
5. Acara Resmi. Acara Resmi adalah acara yang diatur dan dilaksanakan oleh pemerintah atau lembaga negara dalam melaksanakan tugas dan fungsi tertentu dan dihadiri oleh Pejabat Negara dan/atau Pejabat Pemerintahan serta undangan lain.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7055, 'perka-16-2014', 13, 'lampiran', 'Lampiran hal. 6', NULL, 6, '6. Tata Tempat. Tata Tempat adalah pengaturan tempat bagi pejabat negara, pejabat pemerintahan, perwakilan negara asing dan/atau organisasi internasional, serta tokoh masyarakat tertentu dalam acara kenegaraan atau acara resmi.
7. Tata Upacara. Tata Upacara adalah aturan untuk melaksanakan upacara dalam acara kenegaraan atau acara resmi.
8. Tata Penghormatan. Tata Penghormatan adalah aturan untuk melaksanakan pemberian hormat bagi pejabat negara, pejabat pemerintahan, perwakilan negara asing dan/atau organisasi internasional, dan tokoh masyarakat tertentu dalam acara kenegaraan atau acara resmi.
7 2014, No.2078
9. Pejabat Negara. Pejabat Negara adalah pimpinan dan anggota lembaga negara sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 dan Pejabat Negara yang secara tegas ditentukan dalam Undang-Undang.
10. Pejabat Pemerintahan. Pejabat Pemerintahan adalah pejabat yang menduduki jabatan tertentu dalam pemerintahan, baik di pusat maupun di daerah.
11. Tamu Negara. Tamu Negara adalah pemimpin negara asing yang berkunjung secara kenegaraan, resmi, kerja, atau pribadi ke negara Indonesia.
12. Tokoh Masyarakat Tertentu. Tokoh Masyarakat Tertentu adalah tokoh masyarakat yang berdasarkan kedudukan sosialnya mendapat pengaturan keprotokolan.
13. Rapat. Rapat adalah suatu pertemuan atau kumpulan yang diadakan untuk membahas suatu masalah atau kegiatan yang berkenaan dengan bidang tugas dan pekerjaan yang dihadapi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7055, '6. Tata Tempat. Tata Tempat adalah pengaturan tempat bagi pejabat negara, pejabat pemerintahan, perwakilan negara asing dan/atau organisasi internasional, serta tokoh masyarakat tertentu dalam acara kenegaraan atau acara resmi.
7. Tata Upacara. Tata Upacara adalah aturan untuk melaksanakan upacara dalam acara kenegaraan atau acara resmi.
8. Tata Penghormatan. Tata Penghormatan adalah aturan untuk melaksanakan pemberian hormat bagi pejabat negara, pejabat pemerintahan, perwakilan negara asing dan/atau organisasi internasional, dan tokoh masyarakat tertentu dalam acara kenegaraan atau acara resmi.
7 2014, No.2078
9. Pejabat Negara. Pejabat Negara adalah pimpinan dan anggota lembaga negara sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 dan Pejabat Negara yang secara tegas ditentukan dalam Undang-Undang.
10. Pejabat Pemerintahan. Pejabat Pemerintahan adalah pejabat yang menduduki jabatan tertentu dalam pemerintahan, baik di pusat maupun di daerah.
11. Tamu Negara. Tamu Negara adalah pemimpin negara asing yang berkunjung secara kenegaraan, resmi, kerja, atau pribadi ke negara Indonesia.
12. Tokoh Masyarakat Tertentu. Tokoh Masyarakat Tertentu adalah tokoh masyarakat yang berdasarkan kedudukan sosialnya mendapat pengaturan keprotokolan.
13. Rapat. Rapat adalah suatu pertemuan atau kumpulan yang diadakan untuk membahas suatu masalah atau kegiatan yang berkenaan dengan bidang tugas dan pekerjaan yang dihadapi.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7056, 'perka-16-2014', 14, 'lampiran', 'Lampiran hal. 7', NULL, 7, '14. Acara. Acara adalah rangkaian kegiatan yang diikuti oleh sejumlah personel sebagai peserta acara, dipimpin oleh seorang pejabat yang ditunjuk/membidangi tujuan acara yang disebut sesuai dengan jabatan fungsionalnya dan disusun berupa barisan atau duduk yang disesuaikan dengan keadaan ruangan, di mana setiap peserta acara dalam melaksanakan kegiatan tidak selalu berdasarkan perintah dari pejabat yang ditunjuk.
15. Upacara. Upacara adalah rangkaian kegiatan yang diikuti oleh sejumlah personel sebagai peserta upacara, disusun dalam barisan di suatu lapangan/ruangan dengan bentuk Segaris atau U dipimpin oleh seorang Inspektur Upacara dan setiap kegiatan personel peserta upacara melakukan ketentuan-ketentuan yang baku melalui perintah seorang pemimpin upacara, di mana seluruh kegiatan tersebut direncanakan oleh penyelenggara upacara dalam rangka mencapai tujuan upacara.
16. Undangan. Undangan adalah pejabat atau orang yang akan dihadirkan dalam suatu acara dan upacara melalui berita tulisan (surat dan kartu) atau lisan (baik langsung maupun berita telepon).
2014, No.2078 8
17. Leading Sector. Leading Sector adalah unit kerja yang mempunyai tanggung jawab dan wewenang dalam pengambilan keputusan untuk suatu kegiatan yang akan dilaksanakan baik berupa upacara, rapat, dan acara.
18. Kenaikan pangkat. Kenaikan pangkat adalah suatu penghargaan yang diberikan kepada seseorang karena telah menunjukkan prestasi kerja yang baik dan telah memenuhi syarat-syarat administrasi kepegawaian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7056, '14. Acara. Acara adalah rangkaian kegiatan yang diikuti oleh sejumlah personel sebagai peserta acara, dipimpin oleh seorang pejabat yang ditunjuk/membidangi tujuan acara yang disebut sesuai dengan jabatan fungsionalnya dan disusun berupa barisan atau duduk yang disesuaikan dengan keadaan ruangan, di mana setiap peserta acara dalam melaksanakan kegiatan tidak selalu berdasarkan perintah dari pejabat yang ditunjuk.
15. Upacara. Upacara adalah rangkaian kegiatan yang diikuti oleh sejumlah personel sebagai peserta upacara, disusun dalam barisan di suatu lapangan/ruangan dengan bentuk Segaris atau U dipimpin oleh seorang Inspektur Upacara dan setiap kegiatan personel peserta upacara melakukan ketentuan-ketentuan yang baku melalui perintah seorang pemimpin upacara, di mana seluruh kegiatan tersebut direncanakan oleh penyelenggara upacara dalam rangka mencapai tujuan upacara.
16. Undangan. Undangan adalah pejabat atau orang yang akan dihadirkan dalam suatu acara dan upacara melalui berita tulisan (surat dan kartu) atau lisan (baik langsung maupun berita telepon).
2014, No.2078 8
17. Leading Sector. Leading Sector adalah unit kerja yang mempunyai tanggung jawab dan wewenang dalam pengambilan keputusan untuk suatu kegiatan yang akan dilaksanakan baik berupa upacara, rapat, dan acara.
18. Kenaikan pangkat. Kenaikan pangkat adalah suatu penghargaan yang diberikan kepada seseorang karena telah menunjukkan prestasi kerja yang baik dan telah memenuhi syarat-syarat administrasi kepegawaian.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7057, 'perka-16-2014', 15, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'BAB II KETENTUAN UMUM A. Umum Ketentuan umum tata tempat, tata upacara dan tata penghormatan di lingkungan Badan Nasional Penanggulangan Bencana perlu adanya batasan pembahasan yang menjadi ketentuan di dalam pelaksanaan tugas sehingga akan ada keselarasan. Pengaturan tata tempat, tata upacara dan tata penghormatan yang bertujuan untuk memberikan penghormatan kepada Pejabat Negara, Pejabat Pemerintahan, Perwakilan Negara Asing, Organisasi Internasional, Tokoh Masyarakat Tertentu, Tamu Negara serta Pejabat Badan Nasional Penanggulangan Bencana sesuai dengan kedudukan dalam negara, pemerintahan, dan masyarakat.
B. Tugas dan Fungsi Protokol
1. Lingkup tugas protokol menyangkut segi-segi, tercermin di dalam banyaknya macam acara yang harus dilaksanakan, yaitu seperti :
a. Penerimaan tamu/audensi
b. Kunjungan tamu (dalam dan luar negeri)
c. Perjalanan ke daerah/luar negeri
d. Pengaturan rapat/sidang
e. Penyelenggaraan resepsi/jamuan
f. Penyelenggaraan upacara-upacara :
1) Hari Besar Nasional 2) HUT Badan Nasional Penanggulangan Bencana 3) Peresmian Proyek 4) Pelantikan dan serah terima jabatan 5) Penandatanganan kerjasama internasional 9 2014, No.2078 6) Peresmian pembukaan/penutupan seminar/lokakarya dan lain sebagainya.
2. Protokol berfungsi sebagai salah satu staf pembantu pimpinan dalam mengelola fungsi.
C. Kriteria pelaksana keprotokolan
1. Secara teknis, setiap petugas harus menguasai bidang tugas masing-masing dan turut memperhatikan kepentingan bidang lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7057, 'BAB II KETENTUAN UMUM A. Umum Ketentuan umum tata tempat, tata upacara dan tata penghormatan di lingkungan Badan Nasional Penanggulangan Bencana perlu adanya batasan pembahasan yang menjadi ketentuan di dalam pelaksanaan tugas sehingga akan ada keselarasan. Pengaturan tata tempat, tata upacara dan tata penghormatan yang bertujuan untuk memberikan penghormatan kepada Pejabat Negara, Pejabat Pemerintahan, Perwakilan Negara Asing, Organisasi Internasional, Tokoh Masyarakat Tertentu, Tamu Negara serta Pejabat Badan Nasional Penanggulangan Bencana sesuai dengan kedudukan dalam negara, pemerintahan, dan masyarakat.
B. Tugas dan Fungsi Protokol
1. Lingkup tugas protokol menyangkut segi-segi, tercermin di dalam banyaknya macam acara yang harus dilaksanakan, yaitu seperti :
a. Penerimaan tamu/audensi
b. Kunjungan tamu (dalam dan luar negeri)
c. Perjalanan ke daerah/luar negeri
d. Pengaturan rapat/sidang
e. Penyelenggaraan resepsi/jamuan
f. Penyelenggaraan upacara-upacara :
1) Hari Besar Nasional 2) HUT Badan Nasional Penanggulangan Bencana 3) Peresmian Proyek 4) Pelantikan dan serah terima jabatan 5) Penandatanganan kerjasama internasional 9 2014, No.2078 6) Peresmian pembukaan/penutupan seminar/lokakarya dan lain sebagainya.
2. Protokol berfungsi sebagai salah satu staf pembantu pimpinan dalam mengelola fungsi.
C. Kriteria pelaksana keprotokolan
1. Secara teknis, setiap petugas harus menguasai bidang tugas masing-masing dan turut memperhatikan kepentingan bidang lainnya.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7058, 'perka-16-2014', 16, 'lampiran', 'Lampiran hal. 9', NULL, 9, '2. Dapat mewujudkan aparat pengelola yang efektif dalam iklim yang kompak, tertib dan berwibawa dalam suatu kondisi yang berazaskan kekeluargaan guna menjamin tercapainya keberhasilan pelaksanaan tugas.
3. Menguasai segala permasalahan, mengetahui apa pun aspek kegiatan yang perlu bagi suatu acara.
4. Mengerti arti pentingnya dekorasi, kebersihan dan keamanan.
5. Mengerti tentang prinsip-prinsip manajemen yang baik.
D. Persyaratan Keprotokolan
1. Administrasi.
Persetujuan tertulis atau lisan dari Kepala Badan Nasional Penanggulangan Bencana atas permohonan audiensi dan acara rapat, permohonan kehadiran sebagai pembicara, pemimpin rapat, undangan dan lain-lain.
2. Kompetensi.
a. mampu memahami dasar dan peraturan serta praktek keprotokolan yang berlaku;
b. mampu berkomunikasi dalam bahasa Indonesia dan asing dengan baik;
c. mampu bertindak sebagai komunikator yang baik;
d. mampu menjaga rahasia;
e. mampu menggali informasi dan menyampaikannya dengan tepat dan benar;
f. memiliki inisiatif dan langkah antisipatif;
g. memiliki kepribadian yang ramah, jujur, disiplin, sopan dan bertanggung jawab;
h. mampu mengoperasikan komputer.
2014, No.2078 10 E. Sarana dan Prasarana Pelayanan.
Alat tulis kantor, alat pengolah data dan presentasi, kendaraan, ruang kerja dan ruang rapat, serta pakaian sipil lengkap, pakaian dinas lapangan dan pakaian dinas harian.
F. Tempat Pelayanan Keprotokolan.');
