INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7059, 'perka-16-2014', 17, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'Kantor Badan Nasional Penanggulangan Bencana, Kantor Kepala Badan Nasional Penanggulangan Bencana, dan tempat lain yang menjadi kunjungan kerja Kepala Badan Nasional Penanggulangan Bencana.
G. Peringatan Keterlambatan penyiapan dukungan staf dan administrasi akan mengakibatkan acara dan kegiatan keprotokolan yang telah direncanakan terlambat, tertunda atau batal.
H. Jadwal Pelayanan Pelayanan keprotokolan diselenggarakan selama hari dan jam kerja kedinasan, dan dalam hal kebutuhan mendesak diselenggarakan di luar hari dan jam kerja kedinasan.
I. Penanganan Pengaduan Mekanisme Penanganan Pengaduan/Tindak Lanjut atas Masukan/Keluhan dari Pengguna Pelayanan Pengaduan/masukan berkaitan dengan pelayanan disampaikan kepada Sekretaris Utama, dan selanjutnya secara berjenjang dapat menugaskan kepada pejabat di bawahnya untuk menindaklanjuti pengaduan /masukan dimaksud.
J. Pembinaan dan Pelaksanaan
1. Dalam rangka pencapaian tujuan Keprotokolan dilakukan pembinaan yang meliputi kegiatan perencanaan, pelaksanaan, sosialisasi, pelatihan, monitoring, dan evaluasi.
2. Pembinaan Keprotokolan Badan Nasional Penanggulangan Bencana dilakukan oleh Biro Umum Sekretariat Utama.
3. Pembinaan Keprotokolan pada masing-masing unit organisasi di unit kerja Badan Nasional Penanggulangan Bencana dilakukan oleh Inspektur Utama, Deputi, Kepala Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, Kepala Pusat Data Informasi dan Hubungan Masyarakat, dan Kepala Unit Pelaksana Teknis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7059, 'Kantor Badan Nasional Penanggulangan Bencana, Kantor Kepala Badan Nasional Penanggulangan Bencana, dan tempat lain yang menjadi kunjungan kerja Kepala Badan Nasional Penanggulangan Bencana.
G. Peringatan Keterlambatan penyiapan dukungan staf dan administrasi akan mengakibatkan acara dan kegiatan keprotokolan yang telah direncanakan terlambat, tertunda atau batal.
H. Jadwal Pelayanan Pelayanan keprotokolan diselenggarakan selama hari dan jam kerja kedinasan, dan dalam hal kebutuhan mendesak diselenggarakan di luar hari dan jam kerja kedinasan.
I. Penanganan Pengaduan Mekanisme Penanganan Pengaduan/Tindak Lanjut atas Masukan/Keluhan dari Pengguna Pelayanan Pengaduan/masukan berkaitan dengan pelayanan disampaikan kepada Sekretaris Utama, dan selanjutnya secara berjenjang dapat menugaskan kepada pejabat di bawahnya untuk menindaklanjuti pengaduan /masukan dimaksud.
J. Pembinaan dan Pelaksanaan
1. Dalam rangka pencapaian tujuan Keprotokolan dilakukan pembinaan yang meliputi kegiatan perencanaan, pelaksanaan, sosialisasi, pelatihan, monitoring, dan evaluasi.
2. Pembinaan Keprotokolan Badan Nasional Penanggulangan Bencana dilakukan oleh Biro Umum Sekretariat Utama.
3. Pembinaan Keprotokolan pada masing-masing unit organisasi di unit kerja Badan Nasional Penanggulangan Bencana dilakukan oleh Inspektur Utama, Deputi, Kepala Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, Kepala Pusat Data Informasi dan Hubungan Masyarakat, dan Kepala Unit Pelaksana Teknis.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7060, 'perka-16-2014', 18, 'lampiran', 'Lampiran hal. 10', NULL, 10, '4. Pelaksana Keprotokolan Badan Nasional Penanggulangan Bencana meliputi:
a. Sekretariat Utama, sebagai koordinator kegiatan Keprotokolan di lingkungan BNPB;
11 2014, No.2078
b. Keprotokolan di unit organisasi dilaksanakan oleh:
1) Sekretariat Inspektorat Utama;
2) Sekretariat Deputi Bidang Pencegahan dan Kesiapsiagaan;
3) Sekretariat Deputi Bidang Penanganan Darurat;
4) Sekretariat Deputi Bidang Rehabilitasi dan Rekonstruksi;
5) Sekretariat Deputi Bidang Logistik dan Peralatan;
6) Sekretariat Pusat Pendidikan dan Pelatihan Penanggulangan Bencana;
7) Sekretariat Pusat Data Informasi dan Hubungan Masyarakat;
c. Keprotokolan di unit pelaksana teknis dilaksanakan oleh unit kerja yang menangani bidang Keprotokolan.
5. Pelaksana Keprotokolan BNPB dilaksanakan oleh petugas keprotokolan dan diberikan tanda pengenal keprotokolan.
6. Tanda pengenal ditetapkan dan dikukuhkan oleh Sekretaris Utama.
7. Keprotokolan BNPB dilaksanakan pada Acara Resmi Kepala BNPB, meliputi:
a. upacara bendera;
b. upacara bukan upacara bendera;
e. rapat;
d. kunjungan kerja;
e. kunjungan tamu;
f. jamuan resmi.
g. audiensi
8. Penyelenggaraan Acara Resmi dilaksanakan sesuai dengan aturan Tata Tempat, Tata Upaeara, dan Tata Penghormatan.
9. Dalam hal Acara Resmi yang diselenggarakan unit organisasi, unit pelaksana teknis, instansi dan/atau organisasi lain melibatkan Kepala BNPB, harus berkoordinasi dengan Protokol BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7060, '4. Pelaksana Keprotokolan Badan Nasional Penanggulangan Bencana meliputi:
a. Sekretariat Utama, sebagai koordinator kegiatan Keprotokolan di lingkungan BNPB;
11 2014, No.2078
b. Keprotokolan di unit organisasi dilaksanakan oleh:
1) Sekretariat Inspektorat Utama;
2) Sekretariat Deputi Bidang Pencegahan dan Kesiapsiagaan;
3) Sekretariat Deputi Bidang Penanganan Darurat;
4) Sekretariat Deputi Bidang Rehabilitasi dan Rekonstruksi;
5) Sekretariat Deputi Bidang Logistik dan Peralatan;
6) Sekretariat Pusat Pendidikan dan Pelatihan Penanggulangan Bencana;
7) Sekretariat Pusat Data Informasi dan Hubungan Masyarakat;
c. Keprotokolan di unit pelaksana teknis dilaksanakan oleh unit kerja yang menangani bidang Keprotokolan.
5. Pelaksana Keprotokolan BNPB dilaksanakan oleh petugas keprotokolan dan diberikan tanda pengenal keprotokolan.
6. Tanda pengenal ditetapkan dan dikukuhkan oleh Sekretaris Utama.
7. Keprotokolan BNPB dilaksanakan pada Acara Resmi Kepala BNPB, meliputi:
a. upacara bendera;
b. upacara bukan upacara bendera;
e. rapat;
d. kunjungan kerja;
e. kunjungan tamu;
f. jamuan resmi.
g. audiensi
8. Penyelenggaraan Acara Resmi dilaksanakan sesuai dengan aturan Tata Tempat, Tata Upaeara, dan Tata Penghormatan.
9. Dalam hal Acara Resmi yang diselenggarakan unit organisasi, unit pelaksana teknis, instansi dan/atau organisasi lain melibatkan Kepala BNPB, harus berkoordinasi dengan Protokol BNPB.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7061, 'perka-16-2014', 19, 'lampiran', 'Lampiran hal. 11', NULL, 11, '10. Protokol BNPB dapat memberikan masukan, saran, atau usulan terhadap Acara Resmi di masing-masing unit organisasi.
2014, No.2078 12 BAB III TATA TEMPAT, TATA UPACARA DAN TATA PENGHORMATAN A. Umum Kegiatan upacara, rapat, dan acara yang dilaksanakan di lingkungan Badan Nasional Penanggulangan Bencana perlu diatur secara khusus dengan menata tata tempat dan undangan berdasarkan kedudukan, jabatan dan golongan sebagai salah satu bentuk penghormatan kepada para pejabat negara, pemerintahan, perwakilan negara asing dan/atau organisasi internasional serta tokoh masyarakat. Mengingat tata tempat, tata upacara dan tata penghormatan sangat menentukan keberhasilan kegiatan keprotokolan di lingkungan Badan Nasional Penanggulangan Bencana, sehingga pelaksanaan upacara, rapat, dan acara dapat berjalan dengan tertib, aman, dan lancar.
B. Tata Tempat.
1. Tata Tempat dalam suatu Acara Resmi BNPB yang dihadiri oleh pejabat di luar BNPB serta tokoh masyarakat, ditentukan dengan urutan:
a. Menteri
b. anggota Dewan Perwakilan Rakyat Republik Indonesia,
c. anggota Dewan Perwakilan Daerah;
d. Duta Besar Luar Biasa dan Berkuasa Penuh;
e. pimpinan lembaga pemerintah non kementerian;
f. mantan Menteri;
g. Wakil Menteri;
h. Gubernur;
i. pejabat eselon I;
j. mantan pejabat eselon I;
k. Bupati/Walikota;
l. pejabat eselon II;
m. direksi badan usaha milik negara;
n. mantan pejabat eselon II;
o. pejabat eselon III; dan
p. pejabat eselon IV.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7061, '10. Protokol BNPB dapat memberikan masukan, saran, atau usulan terhadap Acara Resmi di masing-masing unit organisasi.
2014, No.2078 12 BAB III TATA TEMPAT, TATA UPACARA DAN TATA PENGHORMATAN A. Umum Kegiatan upacara, rapat, dan acara yang dilaksanakan di lingkungan Badan Nasional Penanggulangan Bencana perlu diatur secara khusus dengan menata tata tempat dan undangan berdasarkan kedudukan, jabatan dan golongan sebagai salah satu bentuk penghormatan kepada para pejabat negara, pemerintahan, perwakilan negara asing dan/atau organisasi internasional serta tokoh masyarakat. Mengingat tata tempat, tata upacara dan tata penghormatan sangat menentukan keberhasilan kegiatan keprotokolan di lingkungan Badan Nasional Penanggulangan Bencana, sehingga pelaksanaan upacara, rapat, dan acara dapat berjalan dengan tertib, aman, dan lancar.
B. Tata Tempat.
1. Tata Tempat dalam suatu Acara Resmi BNPB yang dihadiri oleh pejabat di luar BNPB serta tokoh masyarakat, ditentukan dengan urutan:
a. Menteri
b. anggota Dewan Perwakilan Rakyat Republik Indonesia,
c. anggota Dewan Perwakilan Daerah;
d. Duta Besar Luar Biasa dan Berkuasa Penuh;
e. pimpinan lembaga pemerintah non kementerian;
f. mantan Menteri;
g. Wakil Menteri;
h. Gubernur;
i. pejabat eselon I;
j. mantan pejabat eselon I;
k. Bupati/Walikota;
l. pejabat eselon II;
m. direksi badan usaha milik negara;
n. mantan pejabat eselon II;
o. pejabat eselon III; dan
p. pejabat eselon IV.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7062, 'perka-16-2014', 20, 'lampiran', 'Lampiran hal. 12', NULL, 12, '2. Dalam hal menghadiri Acara Resmi di luar BNPB, maka Tata Tempat mengikuti ketentuan peraturan perundang-undangan.
13 2014, No.2078
3. Tata tempat dalam acara resmi di lingkungan Badan Nasional Penanggulangan Bencana ditentukan dengan urutan :
a. Kepala Badan Nasional Penanggulangan Bencana;
b. Sekretaris Utama;
c. Inspektur Utama;
d. Unsur Pengarah;
e. Deputi Bidang Pencegahan dan Kesiapsiagaan, Deputi Bidang Penanganan Darurat, Deputi Bidang Rehabilitasi dan Rekonstruksi, Deputi Bidang Logistik dan Peralatan
f. Kepala Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, Kepala Pusat Data, Informasi dan Hubungan Masyarakat, Kepala Biro Perencanaan, Kepala Biro Keuangan, Kepala Biro Umum, Kepala Biro Hukum dan Kerjasama, Direktur Pengurangan Resiko Bencana, Direktur Kesiapsiagaan, Direktur Pemberdayaan Masyarakat, Direktur Tanggap Darurat, Direktur Bantuan Darurat, Direktur Perbaikan Darurat, Direktur Penilaian Kerusakan, Direktur Peningkatan dan Pemulihan Fisik, Direktur Peningkatan dan Pemulihan Sosial Ekonomi, Direktur Penanganan Pengungsi, Direktur Logistik dan Direktur Peralatan:
g. Para Kepala Bagian dan Pejabat Eselon III/Setingkat;
h. Para Kepala Sub Bagian dan Pejabat Eselon IV/Setingkat.
4. Tata Tempat bagi penyelenggara dan/atau pejabat tuan rumah dalam pelaksanaan Acara Resmi yang melibatkan Kepala BNPB, diatur sebagai berikut:
a. dalam hal Acara Resmi dihadiri Kepala BNPB, penyelenggara dan/ atau pejabat tuan rumah mendampingi Kepala BNPB; dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7062, '2. Dalam hal menghadiri Acara Resmi di luar BNPB, maka Tata Tempat mengikuti ketentuan peraturan perundang-undangan.
13 2014, No.2078
3. Tata tempat dalam acara resmi di lingkungan Badan Nasional Penanggulangan Bencana ditentukan dengan urutan :
a. Kepala Badan Nasional Penanggulangan Bencana;
b. Sekretaris Utama;
c. Inspektur Utama;
d. Unsur Pengarah;
e. Deputi Bidang Pencegahan dan Kesiapsiagaan, Deputi Bidang Penanganan Darurat, Deputi Bidang Rehabilitasi dan Rekonstruksi, Deputi Bidang Logistik dan Peralatan
f. Kepala Pusat Pendidikan dan Pelatihan Penanggulangan Bencana, Kepala Pusat Data, Informasi dan Hubungan Masyarakat, Kepala Biro Perencanaan, Kepala Biro Keuangan, Kepala Biro Umum, Kepala Biro Hukum dan Kerjasama, Direktur Pengurangan Resiko Bencana, Direktur Kesiapsiagaan, Direktur Pemberdayaan Masyarakat, Direktur Tanggap Darurat, Direktur Bantuan Darurat, Direktur Perbaikan Darurat, Direktur Penilaian Kerusakan, Direktur Peningkatan dan Pemulihan Fisik, Direktur Peningkatan dan Pemulihan Sosial Ekonomi, Direktur Penanganan Pengungsi, Direktur Logistik dan Direktur Peralatan:
g. Para Kepala Bagian dan Pejabat Eselon III/Setingkat;
h. Para Kepala Sub Bagian dan Pejabat Eselon IV/Setingkat.
4. Tata Tempat bagi penyelenggara dan/atau pejabat tuan rumah dalam pelaksanaan Acara Resmi yang melibatkan Kepala BNPB, diatur sebagai berikut:
a. dalam hal Acara Resmi dihadiri Kepala BNPB, penyelenggara dan/ atau pejabat tuan rumah mendampingi Kepala BNPB; dan', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7063, 'perka-16-2014', 21, 'lampiran', 'Lampiran hal. 13', NULL, 13, 'b. dalam hal Acara Resmi tidak dihadiri Kepala BNPB, penyelenggara dan/atau pejabat tuan rumah mendampingi pejabat yang mewakili Kepala BNPB.
5. Dalam hal pelaksanaan Acara Resmi dilakukan oleh unit organisasi dan tidak dihadiri oleh Kepala BNPB, Tata Tempat ditentukan oleh pimpinan unit organisasi.
6. Tata Tempat Pejabat Negara atau Pejabat Pemerintahan atau Tokoh Masyarakat Tertentu dalam Acara Resmi yang didamping isteri atau suami sebagai berikut:
a. dalam hal suami sebagai Pejabat Negara, Pejabat Pemerintahan, atau Tokoh Masyarakat Tertentu, isteri mengikuti urutan Tata Tempat suami; dan 2014, No.2078 14
b. dalam hal isteri sebagai Pejabat Negara, Pejabat Pemerintahan, atau Tokoh Masyarakat Tertentu, suami mendapat tempat sesuai dengan urutan Tata Tempat isteri.
7. Dalam hal Pejabat Negara, Pejabat Pemerintahan, kepala perwakilan negara asing dan/atau organisasi internasional, Tokoh Masyarakat Tertentu, dan/atau pimpinan unit organisasi berhalangan hadir pada Acara Resmi, tempatnya tidak diisi oleh yang mewakili, kecuali pada acara tertentu.
8. Seseorang yang mewakili mendapat tempat sesuai dengan kedudukan sosial dan kehormatan yang diterimanya atau jabatannya.
C. Tata Upacara.
1. Upacara Bendera
a. Lingkup Upacara Bendera 1) Upacara bendera hanya dapat dilaksanakan untuk Acara Resmi BNPB: a) Hari Ulang Tahun Proklamasi Kemerdekaan Republik Indonesia; b) hari besar nasional; c) hari jadi BNPB; dan d) apel bendera setiap tanggal 17 (tujuh belas).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7063, 'b. dalam hal Acara Resmi tidak dihadiri Kepala BNPB, penyelenggara dan/atau pejabat tuan rumah mendampingi pejabat yang mewakili Kepala BNPB.
5. Dalam hal pelaksanaan Acara Resmi dilakukan oleh unit organisasi dan tidak dihadiri oleh Kepala BNPB, Tata Tempat ditentukan oleh pimpinan unit organisasi.
6. Tata Tempat Pejabat Negara atau Pejabat Pemerintahan atau Tokoh Masyarakat Tertentu dalam Acara Resmi yang didamping isteri atau suami sebagai berikut:
a. dalam hal suami sebagai Pejabat Negara, Pejabat Pemerintahan, atau Tokoh Masyarakat Tertentu, isteri mengikuti urutan Tata Tempat suami; dan 2014, No.2078 14
b. dalam hal isteri sebagai Pejabat Negara, Pejabat Pemerintahan, atau Tokoh Masyarakat Tertentu, suami mendapat tempat sesuai dengan urutan Tata Tempat isteri.
7. Dalam hal Pejabat Negara, Pejabat Pemerintahan, kepala perwakilan negara asing dan/atau organisasi internasional, Tokoh Masyarakat Tertentu, dan/atau pimpinan unit organisasi berhalangan hadir pada Acara Resmi, tempatnya tidak diisi oleh yang mewakili, kecuali pada acara tertentu.
8. Seseorang yang mewakili mendapat tempat sesuai dengan kedudukan sosial dan kehormatan yang diterimanya atau jabatannya.
C. Tata Upacara.
1. Upacara Bendera
a. Lingkup Upacara Bendera 1) Upacara bendera hanya dapat dilaksanakan untuk Acara Resmi BNPB: a) Hari Ulang Tahun Proklamasi Kemerdekaan Republik Indonesia; b) hari besar nasional; c) hari jadi BNPB; dan d) apel bendera setiap tanggal 17 (tujuh belas).', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7064, 'perka-16-2014', 22, 'lampiran', 'Lampiran hal. 14', NULL, 14, '2) Penyelenggaraan upacara bendera disertai pengibaran Bendera Merah Putih sesuai dengan jenis peringatannya.
3) Khusus penyelenggaraan apel bendera setiap tanggal 17 (tujuh belas), posisi bendera sudah dalam keadaan berkibar.
4) Penentuan pelaksanaan upacara bendera ditetapkan oleh Pemerintah atau panitia nasional atau pimpinan unit organisasi.
b. Tata Upacara Bendera 1) Tata Upacara bendera dalam penyelenggaraan Acara Resmi meliputi: a) tata urutan dalam upacara bendera; b) tata Bendera Merah Putih dalam upacara bendera; c) tata Lagu Kebangsaan dalam upacara bendera; d) tata tempat dalam upacara bendera; dan e) tata pakaian dalam upacara bendera.
15 2014, No.2078 2) Tata urutan dalam upacara bendera meliputi: a) pengibaran Bendera Merah Putih diiringi lagu kebangsaaan Indonesia Raya; b) mengheningkan cipta; c) pembacaan naskah Pancasila; d) pembacaan naskah Pembukaan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945; dan e) pembacaan doa.
3) Tata Bendera Merah Putih dalam upacara bendera meliputi: a) Bendera Merah Putih dikibarkan sampai dengan saat matahari terbenam; b) tiang bendera didirikan di tempat upacara; dan c) penghormatan pada saat pengibaran atau penurunan bendera.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7064, '2) Penyelenggaraan upacara bendera disertai pengibaran Bendera Merah Putih sesuai dengan jenis peringatannya.
3) Khusus penyelenggaraan apel bendera setiap tanggal 17 (tujuh belas), posisi bendera sudah dalam keadaan berkibar.
4) Penentuan pelaksanaan upacara bendera ditetapkan oleh Pemerintah atau panitia nasional atau pimpinan unit organisasi.
b. Tata Upacara Bendera 1) Tata Upacara bendera dalam penyelenggaraan Acara Resmi meliputi: a) tata urutan dalam upacara bendera; b) tata Bendera Merah Putih dalam upacara bendera; c) tata Lagu Kebangsaan dalam upacara bendera; d) tata tempat dalam upacara bendera; dan e) tata pakaian dalam upacara bendera.
15 2014, No.2078 2) Tata urutan dalam upacara bendera meliputi: a) pengibaran Bendera Merah Putih diiringi lagu kebangsaaan Indonesia Raya; b) mengheningkan cipta; c) pembacaan naskah Pancasila; d) pembacaan naskah Pembukaan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945; dan e) pembacaan doa.
3) Tata Bendera Merah Putih dalam upacara bendera meliputi: a) Bendera Merah Putih dikibarkan sampai dengan saat matahari terbenam; b) tiang bendera didirikan di tempat upacara; dan c) penghormatan pada saat pengibaran atau penurunan bendera.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7065, 'perka-16-2014', 23, 'lampiran', 'Lampiran hal. 15', NULL, 15, '4) Tata Lagu Kebangsaan dalam upacara bendera meliputi: a) pengibaran atau penurunan Bendera Merah Putih dengan diiringi Lagu Kebangsaan; dan b) iringan Lagu Kebangsaan dalam pengibaran atau penurunan Bendera Merah Putih dilakukan oleh korps musik atau genderang dan/atau sangkakala, sedangkan seluruh peserta upacara mengambil sikap sempurna dan memberikan penghormatan menurut keadaan setempat. c) dalam hal tidak ada korps musik dan/atau genderang dan/atau sangkakala, pengibaran atau penurunan Bendera Merah Putih diiringi Lagu Kebangsaan yang dinyanyikan oleh se1uruh peserta upacara. d) pengiring lagu untuk pengibaran atau penurunan Bendera Merah Putih tidak dibenarkan menggunakan musik dari alat rekam.
5) Tata tempat dalam upacara bendera dilaksanakan sebagai berikut: a) Pembina upacara adalah Kepala BNPB dan/atau pimpinan unit organisasi yang ditunjuk; b) Pembina upacara berhadapan dengan pemimpin upacara;
2014, No.2078 16 c) pejabat eselon I di sebelah kanan pembina upacara dan pejabat eselon II di sebe1ah kiri pembina upacara; d) peserta upacara ditempatkan berhadapan dengan pembina upacara yang diatur oleh masing-masing pemimpin regu dari unit organisasi yang bersangkutan; dan e) pembawa acara dan para petugas pembaca naskah dan do’a di sebelah kiri Pembina upacara. f) Dalam hal terjadi situasi dan kondisi yang tidak memungkinkan, tata tempat dalam upacara bendera dilaksanakan dengan menyesuaikan situasi dan kondisi lapangan yang ada.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7065, '4) Tata Lagu Kebangsaan dalam upacara bendera meliputi: a) pengibaran atau penurunan Bendera Merah Putih dengan diiringi Lagu Kebangsaan; dan b) iringan Lagu Kebangsaan dalam pengibaran atau penurunan Bendera Merah Putih dilakukan oleh korps musik atau genderang dan/atau sangkakala, sedangkan seluruh peserta upacara mengambil sikap sempurna dan memberikan penghormatan menurut keadaan setempat. c) dalam hal tidak ada korps musik dan/atau genderang dan/atau sangkakala, pengibaran atau penurunan Bendera Merah Putih diiringi Lagu Kebangsaan yang dinyanyikan oleh se1uruh peserta upacara. d) pengiring lagu untuk pengibaran atau penurunan Bendera Merah Putih tidak dibenarkan menggunakan musik dari alat rekam.
5) Tata tempat dalam upacara bendera dilaksanakan sebagai berikut: a) Pembina upacara adalah Kepala BNPB dan/atau pimpinan unit organisasi yang ditunjuk; b) Pembina upacara berhadapan dengan pemimpin upacara;
2014, No.2078 16 c) pejabat eselon I di sebelah kanan pembina upacara dan pejabat eselon II di sebe1ah kiri pembina upacara; d) peserta upacara ditempatkan berhadapan dengan pembina upacara yang diatur oleh masing-masing pemimpin regu dari unit organisasi yang bersangkutan; dan e) pembawa acara dan para petugas pembaca naskah dan do’a di sebelah kiri Pembina upacara. f) Dalam hal terjadi situasi dan kondisi yang tidak memungkinkan, tata tempat dalam upacara bendera dilaksanakan dengan menyesuaikan situasi dan kondisi lapangan yang ada.', 'Lampiran hal. 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7066, 'perka-16-2014', 24, 'lampiran', 'Lampiran hal. 16', NULL, 16, '6) Tata pakaian dalam upacara bendera dalam Acara Kenegaraan atau Acara Resmi disesuaikan menurut jenis acara, sebagai berikut: a) Dalam Acara Kenegaraan digunakan pakaian sipil lengkap, pakaian dinas, pakaian kebesaran, atau pakaian nasional yang berlaku sesuai dengan jabatannya atau kedudukannya dalam masyarakat. b) Dalam Acara Resmi dapat digunakan pakaian sipil harian atau seragam resmi lain yang telah ditentukan. c) Tata pakaian upacara bendera Hari Ulang Tahun Proklamasi Kemerdekaan Republik Indonesia dan hari besar nasional untuk peserta upacara mengenakan seragam KORPRI, ce1ana panjang atau rok berwarna biru, dan peci hitam, atau pakaian lain yang ditetapkan oleh pimpinan unit organisasi. d) Tata pakaian upacara bendera hari BNPB dan apel bendera setiap tanggal 17 (tujuh belas) untuk peserta upacara mengenakan pakaian dinas lapangan dan topi lapangan.
7) Kelengkapan dan Perlengkapan Upacara Bendera a) Kelengkapan Upacara Bendera dalam Acara Resmi BNPB, terdiri atas pejabat dalam upacara bendera, petugas dalam upacara bendera, dan peserta upacara bendera.
(1) Pejabat dalam upacara bendera me1iputi:
(a) Pembina Upacara, merupakan pejabat tertinggi dalam upacara yang bertindak sebagai pimpinan upacara;
17 2014, No.2078
(b) pejabat upacara, merupakan pejabat dalam upacara yang bertugas menyusun rencana upacara dan mengendalikan jalannya tertib acara dalam suatu upacara;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7066, '6) Tata pakaian dalam upacara bendera dalam Acara Kenegaraan atau Acara Resmi disesuaikan menurut jenis acara, sebagai berikut: a) Dalam Acara Kenegaraan digunakan pakaian sipil lengkap, pakaian dinas, pakaian kebesaran, atau pakaian nasional yang berlaku sesuai dengan jabatannya atau kedudukannya dalam masyarakat. b) Dalam Acara Resmi dapat digunakan pakaian sipil harian atau seragam resmi lain yang telah ditentukan. c) Tata pakaian upacara bendera Hari Ulang Tahun Proklamasi Kemerdekaan Republik Indonesia dan hari besar nasional untuk peserta upacara mengenakan seragam KORPRI, ce1ana panjang atau rok berwarna biru, dan peci hitam, atau pakaian lain yang ditetapkan oleh pimpinan unit organisasi. d) Tata pakaian upacara bendera hari BNPB dan apel bendera setiap tanggal 17 (tujuh belas) untuk peserta upacara mengenakan pakaian dinas lapangan dan topi lapangan.
7) Kelengkapan dan Perlengkapan Upacara Bendera a) Kelengkapan Upacara Bendera dalam Acara Resmi BNPB, terdiri atas pejabat dalam upacara bendera, petugas dalam upacara bendera, dan peserta upacara bendera.
(1) Pejabat dalam upacara bendera me1iputi:
(a) Pembina Upacara, merupakan pejabat tertinggi dalam upacara yang bertindak sebagai pimpinan upacara;
17 2014, No.2078
(b) pejabat upacara, merupakan pejabat dalam upacara yang bertugas menyusun rencana upacara dan mengendalikan jalannya tertib acara dalam suatu upacara;', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7067, 'perka-16-2014', 25, 'lampiran', 'Lampiran hal. 17', NULL, 17, '(c) pemimpin upacara, merupakan pejabat dalam upacara yang memimpin seluruh pasukan upacara termasuk memimpin penghormatan kepada pembina upacara; dan
(d) pejabat lain sesuai dengan kebutuhan, antara lain bidang keamanan dan perlengkapan.
(2) Petugas dalam upacara bendera meliputi:
(a) pembawa acara, merupakan petugas yang mengantarkan susunan acara secara teratur;
(b) kelompok pengibar bendera, merupakan petugas yang ditunjuk untuk mengibarkan bendera, berjumlah 3 (tiga) orang dan/atau kelipatan yang telah dipilih dan dilatih;
(c) pembaca atau pengucap naskah, merupakan petugas pembaca atau pengucap naskah dalam upacara bendera;
(d) ajudan, merupakan satu kesatuan dengan pembina upacara dan mengambil tempat di sebelah kiri bawah mimbar pembina upacara;
(e) korps musik, merupakan pasukan yang telah terlatih dalam membunyikan, mengalunkan dan mengiringi lagu-Iagu dalam upacara bendera; dan
(f) pembaca doa, merupakan petugas yang memimpin doa dan/atau membacakan doa. b) Perlengkapan upacara meliputi:
(1) Bendera Merah Putih;
(2) tiang bendera dengan tali;
(3) mimbar upacara;
(4) naskah Proklamasi;
(5) naskah Pancasila;
(6) naskah pembukaan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945;
(7) naskah dan/atau teks lain sesuai jenis upacara;
2014, No.2078 18
(8) teks sambutan Pembina upacara;
(9) teks doa;
(10) lagu-Iagu yang diperlukan;
(11) pengeras suara atau sound system;
(12) dokumentasi dan perlengkapan lain yang diperlukan; dan');
