INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7068, 'perka-16-2014', 26, 'lampiran', 'Lampiran hal. 18', NULL, 18, '(13) papan petunjuk peserta upacara. c) Tata Acara Upacara Bendera, tata acara upacara bendera terdiri atas:
(1) acara pendahuluan;
(2) acara pokok; dan
(3) acara penutup. d) Upacara Hari Ulang Tahun Proklamasi Kemerdekaan Republik Indonesia
(1) Acara pendahuluan pada upacara Hari Ulang Tahun Proklamasi Kemerdekaan Republik Indonesia meliputi:
(a) laporan pejabat upacara; dan
(b) pembina upacara tiba di mimbar upacara.
(2) Acara pokok pada upacara Hari Ulang Tahun Proklamasi Kemerdekaan Republik Indonesia meliputi:
(a) penghormatan umum;
(b) laporan pemimpin upacara;
(c) pengibaran Bendera Merah Putih diiringi Lagu Kebangsaan Indonesia Raya;
(d) mengheningkan cipta dipimpin oleh pembina upacara diiringi lagu hening cipta;
(e) pembacaan naskah Proklamasi oleh pembina upacara;
(f) pembacaan naskah Pembukaan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945;
(g) sambutan pembina upacara;
(h) persembahan lagu perjuangan;
19 2014, No.2078
(i) pembacaan doa;
(j) andika bhayangkari;
(k) laporan pemimpin upacara; dan
(l) penghormatan umum
(3) Acara penutup pada upacara Hari Ulang Tahun Proklamasi Kemerdekaan Republik Indonesia meliputi:
(a) pembina upacara meninggalkan mimbar upacara;
(b) laporan pejabat upacara; dan
(c) pemimpin upacara membubarkan seluruh peserta upacara. e) Upacara Hari Besar Nasional.
(1) Acara pendahuluan pada upacara hari besar nasional meliputi:
(a) laporan pejabat upacara; dan
(b) pembina upacara tiba di mimbar upacara.');
