INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7071, 'perka-16-2014', 29, 'lampiran', 'Lampiran hal. 21', NULL, 21, '(2) Pengaturan upacara bendera dalam ruangan ditentukan sebagai berikut:
2014, No.2078 22
(a) Bendera Merah Putih diletakkan berada di samping kanan pembina upacara;
(b) penempatan dan jumlah peserta upacara disesuaikan dengan kondisi ruangan; dan
(c) tata acara upacara disederhanakan dan disesuaikan dengan kondisi ruangan.
(3) Kelengkapan dan perlengkapan upacara disesuai-kan dengan kondisi ruangan upacara. i) Dalam acara upacara bendera dapat dilakukan acara pemberian penghargaan dan/atau acara tambahan lainnya. j) Pemberian penghargaan dimaksud dilakukan sebelum sambutan pembina upacara dan dibacakan surat keputusan penghargaan.
2. Upacara Bukan Upacara Bendera
a. Lingkup upacara bukan upacara bendera meliputi:
1) upacara pengambilan sumpah pegawai negeri sipil;
2) upacara pelantikan pejabat struktural;
3) upacara serah terima jabatan;
4) upacara pengukuhan;
5) upacara penganugerahan tanda kehormatan;
6) upacara peletakan batu pertama;
7) upacara peresmian;
8) upacara pembukaan dan penutupan pendidikan dan pelatihan, kursus, penataran atau seminar;
9) upacara penandatanganan kerjasama;
10) upacara ziarah taman makam pahlawan;
11) upacara pisah sambut;
12) upacara pelepasan pegawai negeri sipil yang pensiun; dan 13) upacara hari ulang tahun BNPB.
b. Tata upacara bukan upacara bendera dalam penyelenggaraan Acara Resmi meliputi:
1) tata urutan upacara bukan upacara bendera, 2) tata Bendera Merah Putih dan Lambang Negara pada upacara bukan upacara bendera;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7071, '(2) Pengaturan upacara bendera dalam ruangan ditentukan sebagai berikut:
