INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7072, 'perka-16-2014', 30, 'lampiran', 'Lampiran hal. 23', NULL, 23, '23 2014, No.2078 3) tata tempat upacara bukan upacara bendera, dan 4) tata pakaian upacara bukan upacara bendera. a) Tata urutan upacara bukan upacara bendera meliputi:
(1) Lagu Kebangsaan Indonesia Raya dipimpin oleh dirigen dan/atau diiringi musik dan/atau paduan suara;
(2) pembukaan;
(3) acara pokok; dan
(4) penutup. b) Tata Bendera Merah Putih dan Lambang Negara upacara bukan upacara bendera meliputi:
(1) Bendera Merah Putih terpasang pada sebuah tiang bendera dan diletakkan di sebelah kanan mimbar;
(2) Panji BNPB dan/atau bendera asing dipasang pada tiang bendera dan diletakan di sebelah kiri;
(3) Bendera Merah Putih dibuat lebih besar dan dipasang lebih tinggi dari Panji BNPB atau unit organisasi;
(4) Lambang Negara terpasang ditempatkan di sebelah kiri dan Iebih tinggi dari Bendera Merah Putih; dan
(5) gambar resmi Presiden dan Wakil Presiden ditempatkan sejajar dan dipasang lebih rendah dari pada Lambang Negara. c) Tata tempat dan tata pakaian upacara bukan upacara bendera disesuaikan menurut lingkup upacara. d) Kelengkapan dan perlengkapan, serta tata acara dalam upacara bukan upacara bendera disesuaikan menurut lingkup upacara.
c. Upacara Pengambilan Sumpah Pegawai Negeri Sipil 1) Upacara pengambilan sumpah pegawai negeri sipil dilakukan terhadap calon Pegawai atau Pegawai yang belum melakukan sumpah pegawai negeri sipil dan dilaksanakan oleh unit organisasi masing-masing dan/atau gabungan unit organisasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7072, '23 2014, No.2078 3) tata tempat upacara bukan upacara bendera, dan 4) tata pakaian upacara bukan upacara bendera. a) Tata urutan upacara bukan upacara bendera meliputi:
(1) Lagu Kebangsaan Indonesia Raya dipimpin oleh dirigen dan/atau diiringi musik dan/atau paduan suara;
(2) pembukaan;
(3) acara pokok; dan
(4) penutup. b) Tata Bendera Merah Putih dan Lambang Negara upacara bukan upacara bendera meliputi:
(1) Bendera Merah Putih terpasang pada sebuah tiang bendera dan diletakkan di sebelah kanan mimbar;
(2) Panji BNPB dan/atau bendera asing dipasang pada tiang bendera dan diletakan di sebelah kiri;
(3) Bendera Merah Putih dibuat lebih besar dan dipasang lebih tinggi dari Panji BNPB atau unit organisasi;
(4) Lambang Negara terpasang ditempatkan di sebelah kiri dan Iebih tinggi dari Bendera Merah Putih; dan
(5) gambar resmi Presiden dan Wakil Presiden ditempatkan sejajar dan dipasang lebih rendah dari pada Lambang Negara. c) Tata tempat dan tata pakaian upacara bukan upacara bendera disesuaikan menurut lingkup upacara. d) Kelengkapan dan perlengkapan, serta tata acara dalam upacara bukan upacara bendera disesuaikan menurut lingkup upacara.
c. Upacara Pengambilan Sumpah Pegawai Negeri Sipil 1) Upacara pengambilan sumpah pegawai negeri sipil dilakukan terhadap calon Pegawai atau Pegawai yang belum melakukan sumpah pegawai negeri sipil dan dilaksanakan oleh unit organisasi masing-masing dan/atau gabungan unit organisasi.', 'Lampiran hal. 23', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7073, 'perka-16-2014', 31, 'lampiran', 'Lampiran hal. 23', NULL, 23, '2) Kelengkapan upacara meliputi: a) pejabat pengambil sumpah; b) Pegawaiyang disumpah;
2014, No.2078 24 c) rohaniwan; d) saksi; e) tamu undangan; dan f) petugas acara.
3) Pejabat pengambil sumpah adalah pimpinan unit organisasi yang bersangkutan dan/atau pejabat lain yang ditunjuk.
4) Perlengkapan upacara meliputi: a) undangan; b) naskah berita acara pengambilan sumpah pegawai negeri sipil; c) naskah sumpah pelantikan pegawai negeri sipil; d) teks sambutan; dan e) perlengkapan lain yang diperlukan.
5) Tata pakaian upacara pengambilan sumpah pegawai negeri sipil untuk Pegawai yang disumpah mengenakan pakaian KORPRI, celana panjang atau rok wama biru, dan peci hitam polos.
6) Tata acara upacara pengambilan sumpah pegawai negeri sipil meliputi: a) Lagu Kebangsaan Indonesia Raya; b) mars BNPB; c) pembukaan; d) pembacaan naskah sumpah pegawai negeri sipil; e) penandatanganan naskah berita acara pengambilan sumpah pegawai negeri sipil oleh Pegawai dan saksi; f) sambutan pengambil sumpah; g) pemberian ucapan selamat; dan h) ramah tamah.
d. Upacara Pelantikan Pejabat Struktural 1) Kelengkapan upacara meliputi: a) pejabat yang melantik; b) pejabat yang dilantik; c) pejabat yang digantikan;
25 2014, No.2078 d) pejabat pembaca surat keputusan pengangkatan jabatan; e) rohaniwan; f) saksi; g) pejabat dan tamu undangan lainnya; dan h) petugas acara.');
