INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7078, 'perka-16-2014', 36, 'lampiran', 'Lampiran hal. 28', NULL, 28, '(10) sambutan pelantikan;
