INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7079, 'perka-16-2014', 37, 'lampiran', 'Lampiran hal. 29', NULL, 29, '3) Pejabat yang ditentukan: a) Kepala BNPB, untuk serah terima jabatan pejabat eselon I; b) Sekretaris Utama, Inspektur Utama dan Deputi, untuk serah terima jabatan pejabat eselon II; dan c) pejabat eselon II dan/atau atasan langsung pejabat yang bersangkutan, untuk serah terima jabatan pejabat eselon III, dan eselon IV.
4) Pejabat yang diundang dalam upacara serah terima jabatan Kepala BNPB meliputi: a) mantan Kepala BNPB dan/atau mantan Sekretaris Utama; b) pimpinan dan anggota Komisi VIII Dewan Perwakilan Rakyat Republik Indonesia; c) pimpinan lembaga pemerintah non kementerian;
2014, No.2078 30 d) pejabat eselon I dan eselon II; e) mantan pejabat eselon I; f) asosiasi atau mitra kerja bidang BNPB; dan g) undangan lain yang ditentukan oleh pejabat yang berwenang.
5) Perlengkapan upacara meliputi: a) naskah berita acara serah terima jabatan; b) undangan; c) memorandum serah terima jabatan; d) teks sambutan; dan e) perlengkapan lain yang diperlukan.
6) Naskah berita acara ditandatangani secara berurutan oleh pejabat yang menyerahkan jabatan, pejabat yang menerima jabatan, dan pejabat yang menyaksikan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7079, '3) Pejabat yang ditentukan: a) Kepala BNPB, untuk serah terima jabatan pejabat eselon I; b) Sekretaris Utama, Inspektur Utama dan Deputi, untuk serah terima jabatan pejabat eselon II; dan c) pejabat eselon II dan/atau atasan langsung pejabat yang bersangkutan, untuk serah terima jabatan pejabat eselon III, dan eselon IV.
4) Pejabat yang diundang dalam upacara serah terima jabatan Kepala BNPB meliputi: a) mantan Kepala BNPB dan/atau mantan Sekretaris Utama; b) pimpinan dan anggota Komisi VIII Dewan Perwakilan Rakyat Republik Indonesia; c) pimpinan lembaga pemerintah non kementerian;
2014, No.2078 30 d) pejabat eselon I dan eselon II; e) mantan pejabat eselon I; f) asosiasi atau mitra kerja bidang BNPB; dan g) undangan lain yang ditentukan oleh pejabat yang berwenang.
5) Perlengkapan upacara meliputi: a) naskah berita acara serah terima jabatan; b) undangan; c) memorandum serah terima jabatan; d) teks sambutan; dan e) perlengkapan lain yang diperlukan.
6) Naskah berita acara ditandatangani secara berurutan oleh pejabat yang menyerahkan jabatan, pejabat yang menerima jabatan, dan pejabat yang menyaksikan.', 'Lampiran hal. 29', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7080, 'perka-16-2014', 38, 'lampiran', 'Lampiran hal. 30', NULL, 30, '7) Tata pakaian upacara serah terima jabatan meliputi: a) Kepala BNPB, Sekretaris Utama, atau pejabat eselon I yang melakukan serah terima jabatan, dan seluruh undangan mengenakan pakaian sipil lengkap, serta pendamping isteri/suami pejabat mengenakan pakaian nasional atau pakaian sipil lengkap; dan b) pejabat eselon II, eselon III dan eselon IV, yang melakukan serah terima jabatan, pejabat yang menyaksikan, dan undangan mengenakan pakaian dinas harian.
8) Tata acara upacara serah terima jabatan Kepala BNPB meliputi: a) Lagu Kebangsaan Indonesia Raya; b) mars BNPB; c) pembukaan; d) pembacaan ringkasan berita acara serah terima jabatan; e) penandatanganan naskah berita acara serah terima jabatan; f) penyerahan memorandum serah terima jabatan; g) sambutan pejabat eselon I yang mewakili; h) sambutan mantan Kepala BNPB;
31 2014, No.2078 1) sambutan Kepala BNPB; j) pemberian ucapan selamat; dan k) ramah tamah.
9) Tata acara upacara serah terima jabatan Sekretaris Utama, pejabat eselon I, eselon II, eselon III, dan eselon IV, meliputi: a) Lagu Kebangsaan Indonesia Raya; b) mars BNPB; c) pembukaan; d) pembacaan ringkasan berita acara serah terima jabatan; e) penandatanganan naskah berita acara serah terima jabatan; f) penyerahan memorandum serah terima jabatan; g) sambutan pejabat yang menyaksikan; h) pemberian ucapan selamat; dan 1) ramah tamah.
f. Upacara Pengukuhan 1) Upacara pengukuhan dilakukan terhadap pejabat fungsional atau profesi yang baru diangkat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7080, '7) Tata pakaian upacara serah terima jabatan meliputi: a) Kepala BNPB, Sekretaris Utama, atau pejabat eselon I yang melakukan serah terima jabatan, dan seluruh undangan mengenakan pakaian sipil lengkap, serta pendamping isteri/suami pejabat mengenakan pakaian nasional atau pakaian sipil lengkap; dan b) pejabat eselon II, eselon III dan eselon IV, yang melakukan serah terima jabatan, pejabat yang menyaksikan, dan undangan mengenakan pakaian dinas harian.
8) Tata acara upacara serah terima jabatan Kepala BNPB meliputi: a) Lagu Kebangsaan Indonesia Raya; b) mars BNPB; c) pembukaan; d) pembacaan ringkasan berita acara serah terima jabatan; e) penandatanganan naskah berita acara serah terima jabatan; f) penyerahan memorandum serah terima jabatan; g) sambutan pejabat eselon I yang mewakili; h) sambutan mantan Kepala BNPB;
31 2014, No.2078 1) sambutan Kepala BNPB; j) pemberian ucapan selamat; dan k) ramah tamah.
9) Tata acara upacara serah terima jabatan Sekretaris Utama, pejabat eselon I, eselon II, eselon III, dan eselon IV, meliputi: a) Lagu Kebangsaan Indonesia Raya; b) mars BNPB; c) pembukaan; d) pembacaan ringkasan berita acara serah terima jabatan; e) penandatanganan naskah berita acara serah terima jabatan; f) penyerahan memorandum serah terima jabatan; g) sambutan pejabat yang menyaksikan; h) pemberian ucapan selamat; dan 1) ramah tamah.
f. Upacara Pengukuhan 1) Upacara pengukuhan dilakukan terhadap pejabat fungsional atau profesi yang baru diangkat.', 'Lampiran hal. 30', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7081, 'perka-16-2014', 39, 'lampiran', 'Lampiran hal. 31', NULL, 31, '2) Kelengkapan upacara meliputi: a) pejabat yang dikukuhkan; b) pejabat yang mengukuhkan; c) pejabat dan tamu undangan; dan d) petugas upacara.
3) Pejabat yang mengukuhkan ditentukan: a) Kepala BNPB, untuk mengukuhkan jabatan fungsional atau profesi yang disetarakan sebagai pejabat eselon I; dan b) Sekretaris Utama dan Inspektur Utama, untuk mengukuhkan jabatan fungsional atau profesi yang disetarakan sebagai pejabat eselon II di lingkungan unit organisasi masing-masing.
4) Perlengkapan upacara meliputi: a) surat keputusan pengangkatan dalam jabatan fungsional dan petikannya;
2014, No.2078 32 b) undangan; c) naskah pengukuhan; d) teks sambutan pejabat yang mengukuhkan; dan e) perlengkapan lain yang diperlukan.
5) Tata pakaian upacara pengukuhan meliputi: a) dalam hal Kepala BNPB yang mengukuhkan:
(1) pejabat yang dikukuhkan pria mengenakan pakaian sipil lengkap dan peci hitam polos;
(2) pejabat yang dikukuhkan wanita mengenakan pakaian nasional; dan
(3) seluruh undangan mengenakan pakaian sipil lengkap; b) dalam hal pimpinan unit organisasi yang mengukuhkan, maka pejabat yang dikukuhkan dan se1uruh undangan mengenakan pakaian dinas harian.
6) Tata acara upacara pengukuhan meliputi: a) Lagu Kebangsaan Indonesia Raya; b) mars BNPB; c) pembukaan; d) persiapan penyerahan pengukuhan; e) pembacaan surat keputusan; f) pembacaan naskah pengukuhan; g) sambutan pejabat yang mengukuhkan; h) pembacaan doa; i) pemberian ucapan selamat; dan j) ramah tamah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7081, '2) Kelengkapan upacara meliputi: a) pejabat yang dikukuhkan; b) pejabat yang mengukuhkan; c) pejabat dan tamu undangan; dan d) petugas upacara.
3) Pejabat yang mengukuhkan ditentukan: a) Kepala BNPB, untuk mengukuhkan jabatan fungsional atau profesi yang disetarakan sebagai pejabat eselon I; dan b) Sekretaris Utama dan Inspektur Utama, untuk mengukuhkan jabatan fungsional atau profesi yang disetarakan sebagai pejabat eselon II di lingkungan unit organisasi masing-masing.
4) Perlengkapan upacara meliputi: a) surat keputusan pengangkatan dalam jabatan fungsional dan petikannya;
2014, No.2078 32 b) undangan; c) naskah pengukuhan; d) teks sambutan pejabat yang mengukuhkan; dan e) perlengkapan lain yang diperlukan.
5) Tata pakaian upacara pengukuhan meliputi: a) dalam hal Kepala BNPB yang mengukuhkan:
(1) pejabat yang dikukuhkan pria mengenakan pakaian sipil lengkap dan peci hitam polos;
(2) pejabat yang dikukuhkan wanita mengenakan pakaian nasional; dan
(3) seluruh undangan mengenakan pakaian sipil lengkap; b) dalam hal pimpinan unit organisasi yang mengukuhkan, maka pejabat yang dikukuhkan dan se1uruh undangan mengenakan pakaian dinas harian.
6) Tata acara upacara pengukuhan meliputi: a) Lagu Kebangsaan Indonesia Raya; b) mars BNPB; c) pembukaan; d) persiapan penyerahan pengukuhan; e) pembacaan surat keputusan; f) pembacaan naskah pengukuhan; g) sambutan pejabat yang mengukuhkan; h) pembacaan doa; i) pemberian ucapan selamat; dan j) ramah tamah.', 'Lampiran hal. 31', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7082, 'perka-16-2014', 40, 'lampiran', 'Lampiran hal. 32', NULL, 32, 'g. Upacara Penganugerahan Tanda Kehormatan 1) Upacara penganugerahan tanda kehormatan diberikan kepada: a) Pegawai, mitra kerja, dan masyarakat; atau b) Kepala BNPB, pejabat eselon I, dan/atau pejabat eselon II yang mendapat tanda kehormatan.
2) Penganugerahan tanda kehormatan diberikan atas jasa, pengabdian, peran serta, dan partisipasi dalam rangka penanganan kebencanaan.
33 2014, No.2078 3) Kelengkapan upacara meliputi: a) pejabat yang menganugerahkan; b) Kepala BNPB, pejabat eselon I dan II, pimpinan unit organisasi, Pegawai dan/atau masyarakat yang menerima tanda kehormatan; c) pejabat dan tamu undangan; dan d) petugas acara.
4) Pejabat yang menganugerahkan tanda kehormatan kepada Pegawai, mitra kerja, dan masyarakat adalah Kepala BNPB, Sekretaris Utama, Inspektur Utama atau pimpinan unit organisasi.
5) Perlengkapan upacara meliputi: a) surat keputusan penganugerahan tanda kehormatan; b) undangan; c) ringkasan surat keputusan yang akan dibaca; d) teks sambutan; dan e) perlengkapan lain yang diperlukan.
6) Tata pakaian upacara penganugerahan tanda kehormatan meliputi: a) pejabat yang menganugerahkan tanda kehormatan mengenakan pakaian sipil lengkap; b) penerima tanda kehormatan mengenakan pakaian sipil lengkap atau pakaian yang ditentukan; dan c) undangan mengenakan pakaian dinas harian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7082, 'g. Upacara Penganugerahan Tanda Kehormatan 1) Upacara penganugerahan tanda kehormatan diberikan kepada: a) Pegawai, mitra kerja, dan masyarakat; atau b) Kepala BNPB, pejabat eselon I, dan/atau pejabat eselon II yang mendapat tanda kehormatan.
2) Penganugerahan tanda kehormatan diberikan atas jasa, pengabdian, peran serta, dan partisipasi dalam rangka penanganan kebencanaan.
33 2014, No.2078 3) Kelengkapan upacara meliputi: a) pejabat yang menganugerahkan; b) Kepala BNPB, pejabat eselon I dan II, pimpinan unit organisasi, Pegawai dan/atau masyarakat yang menerima tanda kehormatan; c) pejabat dan tamu undangan; dan d) petugas acara.
4) Pejabat yang menganugerahkan tanda kehormatan kepada Pegawai, mitra kerja, dan masyarakat adalah Kepala BNPB, Sekretaris Utama, Inspektur Utama atau pimpinan unit organisasi.
5) Perlengkapan upacara meliputi: a) surat keputusan penganugerahan tanda kehormatan; b) undangan; c) ringkasan surat keputusan yang akan dibaca; d) teks sambutan; dan e) perlengkapan lain yang diperlukan.
6) Tata pakaian upacara penganugerahan tanda kehormatan meliputi: a) pejabat yang menganugerahkan tanda kehormatan mengenakan pakaian sipil lengkap; b) penerima tanda kehormatan mengenakan pakaian sipil lengkap atau pakaian yang ditentukan; dan c) undangan mengenakan pakaian dinas harian.', 'Lampiran hal. 32', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7083, 'perka-16-2014', 41, 'lampiran', 'Lampiran hal. 33', NULL, 33, '7) Tata acara upacara penganugerahan tanda kehormatan meliputi: a) Lagu Kebangsaan Indonesia Raya; b) mars BNPB; c) pembukaan; d) laporan; e) pembacaan ringkasan surat keputusan; f) pemberian tanda kehormatan; g) sambutan Menteri atau pimpinan unit organisasi; h) pemberian ucapan selamat; dan i) ramah tamah.
2014, No.2078 34
h. Upacara Peletakan Batu Pertama 1) Upacara peletakan batu pertama merupakan suatu tanda dimulainya pembangunan secara resmi.
2) Upacara peletakan batu pertama meliputi: a) peletakan batu pertama berupa batu bata; b) pemasangan tiang pancang; atau c) pengeboran.
3) Upacara peletakan batu pertama dilakukan oleh Kepala BNPB atau pejabat yang ditunjuk.
4) Kelengkapan upacara meliputi: a) pejabat yang meresmikan; b) pejabat penyelenggara; c) pejabat dan tamu undangan; dan d) petugas acara.
5) Perlengkapan upacara meliputi: a) undangan; b) teks sambutan Menteri; c) teks laporan pejabat penyelenggara; d) tempat upacara peletakan batu pertama; e) maket, miniatur, dan/atau gambar rencana pembangunan; dan f) perlengkapan lain yang diperlukan.
6) Persiapan dan pelaksanaan upacara peletakan batu pertama diatur sebagai berikut: a) dalam hal dilakukan oleh Kepala BNPB, Sekretaris Utama, atau Inspetur Utama maka dikoordinasikan melalui Biro Umum Sekretariat Utama; dan b) dalam hal dilakukan oleh pejabat eselon I di luar Sekretariat Utama, maka dikoordinasikan melalui sekretariat masing-masing unit organisasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7083, '7) Tata acara upacara penganugerahan tanda kehormatan meliputi: a) Lagu Kebangsaan Indonesia Raya; b) mars BNPB; c) pembukaan; d) laporan; e) pembacaan ringkasan surat keputusan; f) pemberian tanda kehormatan; g) sambutan Menteri atau pimpinan unit organisasi; h) pemberian ucapan selamat; dan i) ramah tamah.
