INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7089, 'perka-16-2014', 47, 'lampiran', 'Lampiran hal. 40', NULL, 40, '5) Tata tempat upacara penandatanganan kerjasama yang disaksikan oleh Kepala BNPB meliputi: a) Kepala BNPB mendampingi penandatanganan kerjasama; dan b) pejabat penandatangan berada di sebelah kanan dan mitra kerja berada di sebelah kiri.
6) Tata tempat bendera dalam upacara penandatanganan kerjasama dengan pihak pemerintahan negara asing ditentukan: a) Bendera Merah Putih ukuran besar ditempatkan di sebe1ah kanan pihak negara asing, dan bendera negara asing ukuran besar ditempatkan di sebelah kiri Kepala BNPB; dan b) Bendera Merah Putih ukuran kecil ditempatkan di hadapan Kepala BNPB dan Bendera Merah Putih asing ukuran kecil ditempatkan di hadapan pihak negara asing.
7) Tata tempat upacara penandatanganan kerjasama dapat dilakukan dalam posisi berdiri atau duduk;
8) Tata pakaian upacara penandatanganan kerjasama meliputi: a) dalam hal kerjasama dengan instansi dalam negeri, mengenakan pakaian dinas harian; dan b) dalam hal kerjasama dengan pemerintahan negara asing atau organisasi internasional, mengenakan pakaian sipil lengkap.
9) Tata acara upacara penandatanganan kerjasama antara Kepala BNPB dengan pimpinan instansi dalam negeri atau 41 2014, No.2078 organisasi internasional meliputi: a) pembukaan; b) pembacaan ringkasan kerjasama; c) penandatanganan kerjasama dilanjutkan dengan tukar menukar dokumen; d) sambutan pejabat dari mitra kerjasama; e) sambutan Kepala BNPB; dan f) ramah tamah.');
