INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7094, 'perka-16-2014', 52, 'lampiran', 'Lampiran hal. 46', NULL, 46, '1. Rapat Pimpinan. Rapat pimpinan dipimpin oleh Kepala BNPB dan dihadiri pejabat eselon I di lingkungan BNPB.
a. Kelengkapan rapat meliputi:
1) Kepala BNPB;
2) pejabat eselon I;
3) pejabat eselon II yang ditunjuk; dan 4) notulis pejabat eselon II yang ditunjuk.
b. Perlengkapan rapat meliputi:
1) bahan rapat pimpinan;
2) ruang rapat; dan 3) perlengkapan lain.
c. Tata tempat rapat pimpinan diatur sesuai ketentuan dan kebutuhan.
d. Tata pakaian rapat pimpinan mengenakan pakaian dinas harian atau pakaian lain ditentukan oleh pimpinan.
e. Tata acara rapat pimpinan meliputi:
1) pembukaan oleh pimpinan rapat;
2) paparan dari pimpinan unit organisasi;
3) arahan pimpinan rapat; dan 4) kesimpulan.
2. Rapat Kerja BNPB
a. Rapat kerja/koordinasi BNPB diselenggarakan dalam 1 (satu) tahun sekali.
b. Kelengkapan rapat meliputi:
1) pejabat eselon I dan pejabat eselon II;
2) kepala pelaksana BPBD tingkat provinsi, kabupaten, kota;
3) mitra kerja BNPB;
4) pembawa acara;
5) narasumber;
6) moderator; dan 7) notulis.
c. Perlengkapan rapat meliputi:
1) teks sambutan pimpinan;
47 2014, No.2078 2) laporan panitia;
3) bahan rapat kerja;
4) rekomendasi rapat kerja;
5) cinderamata;
6) buku panduan rapat kerja; dan 7) perlengkapan lain.
d. Tata tempat rapat kerja/koordinasi BNPB diatur dan disesuaikan dengan kebutuhan;
e. Tata pakaian rapat kerja/koordinasi BNPB mengenakan pakaian dinas harian.
f. Tata acara rapat kerja/koordinasi BNPB terdiri atas:
1) acara pembukaan;');
