INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7097, 'perka-16-2014', 55, 'lampiran', 'Lampiran hal. 50', NULL, 50, 'a. Kunjungan kerja dilakukan oleh Kepala BNPB dan/atau pimpinan unit organisasi
b. Kunjungan kerja terdiri atas:
1) kunjungan kerja dalam negeri; dan 2) kunjungan kerja luar negeri.
2. Kunjungan Kerja Dalam Negeri
a. Kunjungan kerja dalam negeri dilaksanakan dalam rangka:
1) mendampingi kunjungan kerja bersama Presiden dan/atau Wakil Presiden;
2) meresmikan proyek BNPB;
3) membuka dan/atau menutup rapat kerja, konferensi internasional, pe1atihan, seminar, workshop, ceramah kuliah umum di perguruan tinggi;
4) menghadiri undangan rapat terbatas atau acara Gubernur, Bupati, atau Walikota;
5) inspeksi mendadak atau meninjau suatu kegiatan atau proyek tertentu di bidang kebencanaan; dan 6) kunjungan pribadi.
b. Dalam melakukan kunjungan kerja, Kepala BNPB dan Sekretaris Utama mempunyai hak keprotokolan:
1) menggunakan nomor kendaraan dinas R.I. 75 atau nomor kendaraan yang ditetapkan oleh pihak yang berwenang; dan 51 2014, No.2078 2) pelayanan dalam bentuk pemberian akomodasi, keamanan dan kenyamanan selama kunjungan kerja.
c. Kelengkapan kunjungan kerja terdiri atas:
1) pejabat pendamping;
2) petugas pengawal/ajudan; dan 3) petugas keprotokolan.
d. Perlengkapan kunjungan kerja terdiri atas:
1) jadwal acara;
2) surat pemberitahuan kepada pemerintah daerah;
3) bahan kunjungan kerja;
4) akomodasi;
5) transportasi; dan 6) perlengkapan lain.
e. Penyiapan kunjungan kerja dilakukan oleh:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7097, 'a. Kunjungan kerja dilakukan oleh Kepala BNPB dan/atau pimpinan unit organisasi
b. Kunjungan kerja terdiri atas:
1) kunjungan kerja dalam negeri; dan 2) kunjungan kerja luar negeri.
2. Kunjungan Kerja Dalam Negeri
a. Kunjungan kerja dalam negeri dilaksanakan dalam rangka:
1) mendampingi kunjungan kerja bersama Presiden dan/atau Wakil Presiden;
2) meresmikan proyek BNPB;
3) membuka dan/atau menutup rapat kerja, konferensi internasional, pe1atihan, seminar, workshop, ceramah kuliah umum di perguruan tinggi;
4) menghadiri undangan rapat terbatas atau acara Gubernur, Bupati, atau Walikota;
5) inspeksi mendadak atau meninjau suatu kegiatan atau proyek tertentu di bidang kebencanaan; dan 6) kunjungan pribadi.
b. Dalam melakukan kunjungan kerja, Kepala BNPB dan Sekretaris Utama mempunyai hak keprotokolan:
1) menggunakan nomor kendaraan dinas R.I. 75 atau nomor kendaraan yang ditetapkan oleh pihak yang berwenang; dan 51 2014, No.2078 2) pelayanan dalam bentuk pemberian akomodasi, keamanan dan kenyamanan selama kunjungan kerja.
c. Kelengkapan kunjungan kerja terdiri atas:
1) pejabat pendamping;
2) petugas pengawal/ajudan; dan 3) petugas keprotokolan.
d. Perlengkapan kunjungan kerja terdiri atas:
1) jadwal acara;
2) surat pemberitahuan kepada pemerintah daerah;
3) bahan kunjungan kerja;
4) akomodasi;
5) transportasi; dan 6) perlengkapan lain.
e. Penyiapan kunjungan kerja dilakukan oleh:', 'Lampiran hal. 50', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 16 Tahun 2014 tentang Keprotokolan di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7098, 'perka-16-2014', 56, 'lampiran', 'Lampiran hal. 51', NULL, 51, '1) Biro Umum Sekretariat Utama, dalam hal kunjungan kerja Kepala BNPB dan/atau Sekretaris Utama; dan 2) Sekretariat masing-masing unit organisasi, dalam hal kunjungan kerja pimpinan unit organisasi.
3. Kunjungan Kerja Luar Negeri
a. Kunjungan kerja luar negeri dilaksanakan dalam rangka:
1) mendampingi kunjungan kerja bersama Presiden dan/atau Wakil Presiden;
2) menghadiri undangan negara asing dan/atau organisasi internasional; dan 3) kunjungan pribadi.
b. Kunjungan kerja ke luar negeri diperlukan izin dari Pemerintah dan diberitahukan kepada Kedutaan Besar Republik Indonesia yang dilalui meskipun hanya untuk keperluan transit.
c. Kelengkapan kunjungan kerja ke luar negeri terdiri atas:
1) pejabat pendamping; dan 2) petugas keprotokolan.
d. Perlengkapan kunjungan kerja ke luar negeri terdiri atas:
1) jadwal acara kunjungan;
2014, No.2078 52 2) surat izin dari Presiden kepada Kepala BNPB;
3) surat izin dari Kepala BNPB kepada pimpinan unit organisasi;
4) surat izin perjalanan luar negeri dari Sekretaris Kabinet;
5) surat exit permit dari Kementerian Luar Negeri;
6) surat permohonan visa ke kedutaan negara tujuan;
7) visa dari negara tujuan, kecuali negara ASEAN;
8) bahan kunjungan kerja;
9) akomodasi;
10) transportasi;
11) souvenir; dan 12) perlengkapan lain.
C. Kunjungan Tamu.
1. Kunjungan tamu BNPB danjatau tamu Menteri terdiri atas:
a. kunjungan tamu negara asing;
b. kunjungan tamu organisasi internasional; dan
c. kunjungan tamu dalam negeri.');
