INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7100, 'perka-16-2014', 58, 'lampiran', 'Lampiran hal. 53', NULL, 53, 'a. tamu yang paling dihormati duduk berhadapan dengan Kepala BNPB dan/atau Sekretaris Utama dan diapit oleh pejabat pendamping paling senior;
b. tamu yang paling dihormati duduk di sebelah kanan Kepala BNPB dan/atau Sekretaris Utama didampingi pejabat paling senior;
c. tamu yang paling dihormati hadir beserta istri, duduk berselang seling antara pria dan wanita, istri Kepala BNPB dan/atau Sekretaris Utama duduk di sebelah kanan tamu, sedangkan istri tamu duduk di sebelah kanan Kepala BNPB dan/atau Sekretaris Utama; dan
d. posisi duduk wanita tidak ditempatkan pada ujung meja jamuan.
4. Tata pakaian jamuan mengenakan pakaian sipil lengkap atau pakaian lain disesuaikan dengan waktu dan tempat acara.
2014, No.2078 54
