INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7102, 'perka-16-2014', 60, 'lampiran', 'Lampiran hal. 55', NULL, 55, '1) celana panjang hitam;
