INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7107, 'perka-16-2014', 65, 'lampiran', 'Lampiran hal. 59', NULL, 59, '1) Keberangkatan 2014, No.2078 60 a) Petugas antar jemput melakukan pengambilan bagasi dari kediaman Kepala Badan Nasional Penanggulangan Bencana dan early check-in di bandara; b) Persiapan VIP Room/Executive Lounge; c) Pembayaran biaya aiport tax/fiscal; d) Penyambutan Kepala Badan Nasional Penanggulangan Bencana di pintu masuk bandara; e) Mengantarkan Kepala Badan Nasional Penanggulangan Bencana ke VIP Room/Executive Lounge; f) Mengantarkan Kepala Badan Nasional Penanggulangan Bencana ke dalam pesawat.
2) Kegiatan di lokasi kunjungan kerja a) Mendampingi Kepala Badan Nasional Penanggulangan Bencana dalam kunjungan kerja; b) Pembuatan dokumentasi; c) Penyelesaian administrasi SPPD Kepala Badan Nasional Penanggulangan Bencana.
3) Kepulangan a) Persiapan kepulangan Kepala Badan Nasional Penanggulangan Bencana melalui koordinasi dengan petugas kawal dan petugas penjemputan di Jakarta; b) Check-in kepulangan di bandara asal tujuan kunjungan kerja; c) Pembayaran biaya airport tax, dll; d) Persiapan VIP Room/Executive Lounge di bandara tujuan kunjungan kerja; e) Mendampingi Kepala Badan Nasional Penanggulangan Bencana dalam perjalanan pulang; f) Persiapan VIP Room di bandara tujuan kepulangan; g) Pengambilan barang (bagasi) di bandara tujuan kepulangan.
c. Pelaporan.
1) Pembuatan laporan pelaksanaan antar jemput Kepala Badan Nasional Penanggulangan Bencana;
2) Pengiriman laporan tersebut kepada pimpinan/unit kerja terkait;');
