INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7108, 'perka-16-2014', 66, 'lampiran', 'Lampiran hal. 61', NULL, 61, '61 2014, No.2078 3) Pembuatan laporan pelaksanaan tugas dan pertanggung-jawaban SPPD.
