INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7115, 'perka-17-2009', 2, 'mengingat', 'Mengingat', NULL, 1, 'a. bahwadalamrangkapelaksanaan ketentuan Pasal18 ayat(3) Peraturan PemerintahNomor21Tahun 2008 tentang Penyelenggaraan PenanggulanganBencana, perludibuat standarisasiperalatan penanggulangan bencana;
1. Undang-Undang Nomor32 Tahun 2004tentang PemerintahanDaerah (LembaranNegaraRepublik IndonesiaTahun2004 Nomor 125,Tambahan LembaranNegara RepublikIndonesiaNomor4437) sebagaimana telah diubah beberapa kali, terakhir denganUndang-UndangNomor12Tahun2008tentang PerubahanKeduaatasUndang-UndangNomor32Tahun2004tentang PemerintahanDaerah(LembaranNegara RepublikIndonesiaTahun 2008Nomor59,Tambahan 2014, No.1089 2 LembaranNegaraRepublikIndonesiaNomor4844);
2. Undang-UndangNomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik IndonesiaTahun2007Nomor 66,TambahanLembaran NegaraRepublikIndonesiaNornor4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang PenyelenggaraanPenanggulanganBencana (Lembaran NegaraRepublikIndonesia Tahun 2008Nomor42, Tambahan Lembaran Negara Republik Indonesia Nomor4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008Nomor 43, Tambahan Lembaran Negara RepublikIndonesia Nomor4829);
5. PeraturanPemerintahNomor23Tahun 2008 tentang PeranSertaLembagaInternasionaldanLembagaAsing NonpemerintahdalamPenanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008Nomor 44, Tambahan Lembaran Republik IndonesiaNomor4830);
6. PeraturanPresidenNomor 8 Tahun 2008 tentangBadanNasionalPenanggulanganBencana;
7. KeputusanPresidenNomor 29/MTahun2008tanggal23 April 2008 tentang Pengangkatan Kepala BadanNasionalPenanggulanganBencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7115, 'a. bahwadalamrangkapelaksanaan ketentuan Pasal18 ayat(3) Peraturan PemerintahNomor21Tahun 2008 tentang Penyelenggaraan PenanggulanganBencana, perludibuat standarisasiperalatan penanggulangan bencana;
1. Undang-Undang Nomor32 Tahun 2004tentang PemerintahanDaerah (LembaranNegaraRepublik IndonesiaTahun2004 Nomor 125,Tambahan LembaranNegara RepublikIndonesiaNomor4437) sebagaimana telah diubah beberapa kali, terakhir denganUndang-UndangNomor12Tahun2008tentang PerubahanKeduaatasUndang-UndangNomor32Tahun2004tentang PemerintahanDaerah(LembaranNegara RepublikIndonesiaTahun 2008Nomor59,Tambahan 2014, No.1089 2 LembaranNegaraRepublikIndonesiaNomor4844);
2. Undang-UndangNomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik IndonesiaTahun2007Nomor 66,TambahanLembaran NegaraRepublikIndonesiaNornor4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang PenyelenggaraanPenanggulanganBencana (Lembaran NegaraRepublikIndonesia Tahun 2008Nomor42, Tambahan Lembaran Negara Republik Indonesia Nomor4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008Nomor 43, Tambahan Lembaran Negara RepublikIndonesia Nomor4829);
5. PeraturanPemerintahNomor23Tahun 2008 tentang PeranSertaLembagaInternasionaldanLembagaAsing NonpemerintahdalamPenanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008Nomor 44, Tambahan Lembaran Republik IndonesiaNomor4830);
6. PeraturanPresidenNomor 8 Tahun 2008 tentangBadanNasionalPenanggulanganBencana;
7. KeputusanPresidenNomor 29/MTahun2008tanggal23 April 2008 tentang Pengangkatan Kepala BadanNasionalPenanggulanganBencana;', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2009 tentang Pedoman Standarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7116, 'perka-17-2009', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONALPENANGGULANGAN BENCANA TENTANG PEDOMAN STANDARISASIPERALATAN PENANGGULANGAN BENCANA.
Pasal1 Pedoman Standarisasi PeralatanPenanggulangan Bencana merupakanpanduanbagiBadanNasional Penanggulangan Bencana,BadanPenanggulanganBencanaDaerah, Instansi/Lembaga dan penyelenggarapenanggulangan bencana agar terstandarnya peralatan minimal untuk kesiapsiagaan, pertolongan dan pelayanan kepada korban bencana secara maksimal,efektif,efisiendanakuntabel.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7116, 'Menetapkan : PERATURAN KEPALA BADAN NASIONALPENANGGULANGAN BENCANA TENTANG PEDOMAN STANDARISASIPERALATAN PENANGGULANGAN BENCANA.
Pasal1 Pedoman Standarisasi PeralatanPenanggulangan Bencana merupakanpanduanbagiBadanNasional Penanggulangan Bencana,BadanPenanggulanganBencanaDaerah, Instansi/Lembaga dan penyelenggarapenanggulangan bencana agar terstandarnya peralatan minimal untuk kesiapsiagaan, pertolongan dan pelayanan kepada korban bencana secara maksimal,efektif,efisiendanakuntabel.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2009 tentang Pedoman Standarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7117, 'perka-17-2009', 4, 'menetapkan', 'Isi hal. 2', NULL, 2, 'Pasal 2 Pedoman Standarisasi PeralatanPenanggulangan Bencana merupakan 3 2014, No.1089 lampiran dan bagianyangtidak terpisahkan dariperaturan ini.
Pasal3 Peraturan inimulaiberlaku padatanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7117, 'Pasal 2 Pedoman Standarisasi PeralatanPenanggulangan Bencana merupakan 3 2014, No.1089 lampiran dan bagianyangtidak terpisahkan dariperaturan ini.
Pasal3 Peraturan inimulaiberlaku padatanggal ditetapkan.
