INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7118, 'perka-17-2009', 5, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 31 Desember 2009 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 11 Agustus 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1089 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7118, 'Ditetapkan di Jakarta pada tanggal 31 Desember 2009 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 11 Agustus 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1089 4', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2009 tentang Pedoman Standarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7119, 'perka-17-2009', 6, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 17 TAHUN 2009 TENTANG 11 AGUSTUS 2014 PEDOMAN STANDARISASI PERALATAN PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan daerah rawan bencana dan bencana dapat terjadi disebabkan oleh alam maupun ulah manusia. Hal ini terbukti telah terjadi berbagai bencana di beberapa daerah seperti gempa bumi, tsunami, banjir dan banjir bandang, tanah longsor, letusan gunungapi, kebakaran, kebakaran hutan dan lahan, angin puting beliung, kegagalan teknologi, kecelakaan transportasi serta konflik sosial. Akibat dari bencana-bencana dimaksud berdampak pada rusaknya lingkungan, permukiman penduduk, sarana prasarana vital dan membawa kerugian harta benda dan penderitaan serta korban jiwa manusia.
Dalam rangka melakukan pencegahan, pengurangan resiko bencana, mitigasi bencana, peringatan dini, kesiapsiagaan pada pra-bencana, maupun pencarian, pertolongan dan evakuasi, pemulihan darurat pada saat terjadi bencana serta rehabilitasi dan rekonstruksi pada pasca-bencana, diperlukan peralatan-peralatan yang memadai dan sesuai dengan kejadian bencananya. Khususnya pada saat tanggap darurat kebutuhan peralatan yang tepat jumlah dan spesifikasinya dan dapat tersedia dengan cepat untuk melakukan pencarian, pertolongan dan evakuasi menjadi sangat penting, agar tujuan penanggulangan bencana untuk penyelamatan dan mengurangi penderitaan korban bencana dapat dilaksanakan secara efektif dan efisien.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7119, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 17 TAHUN 2009 TENTANG 11 AGUSTUS 2014 PEDOMAN STANDARISASI PERALATAN PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan daerah rawan bencana dan bencana dapat terjadi disebabkan oleh alam maupun ulah manusia. Hal ini terbukti telah terjadi berbagai bencana di beberapa daerah seperti gempa bumi, tsunami, banjir dan banjir bandang, tanah longsor, letusan gunungapi, kebakaran, kebakaran hutan dan lahan, angin puting beliung, kegagalan teknologi, kecelakaan transportasi serta konflik sosial. Akibat dari bencana-bencana dimaksud berdampak pada rusaknya lingkungan, permukiman penduduk, sarana prasarana vital dan membawa kerugian harta benda dan penderitaan serta korban jiwa manusia.
Dalam rangka melakukan pencegahan, pengurangan resiko bencana, mitigasi bencana, peringatan dini, kesiapsiagaan pada pra-bencana, maupun pencarian, pertolongan dan evakuasi, pemulihan darurat pada saat terjadi bencana serta rehabilitasi dan rekonstruksi pada pasca-bencana, diperlukan peralatan-peralatan yang memadai dan sesuai dengan kejadian bencananya. Khususnya pada saat tanggap darurat kebutuhan peralatan yang tepat jumlah dan spesifikasinya dan dapat tersedia dengan cepat untuk melakukan pencarian, pertolongan dan evakuasi menjadi sangat penting, agar tujuan penanggulangan bencana untuk penyelamatan dan mengurangi penderitaan korban bencana dapat dilaksanakan secara efektif dan efisien.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2009 tentang Pedoman Standarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7120, 'perka-17-2009', 7, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'Ancaman bencana di satu daerah dengan daerah lain di Indonesia diyakini tidak sama dan mempunyai ancaman yang berbeda-beda, oleh sebab itu peralatan untuk kesiapsiagaan menghadapi bencana berbeda-beda pula.
Pemerintah Pusat, pemerintah daerah Provinsi dan kabupaten/kota akan lebih tepat bila terlebih dahulu melakukan kajian ancaman bencana pada daerahnya masingmasing (dapat melalui perencanaan kontijensi). Sehingga dapat diketahui kebutuhan peralatan yang mendesak bila terjadi bencana.
Kebutuhan peralatan bencana baik jenis dan jumlah yang sesuai dengan ancaman bencananya di setiap daerah dipandang penting, agar diperoleh kesiapsiagaan yang maksimal.Untuk itu perlu dibuat Pedoman Standarisasi Peralatan Penanggulangan Bencana, agar penyelenggaraan penanggulangan bencana dapat berjalan dengan baik dan lancar, dan pada gilirannya penanggulangan bencana yang cepat dan tepat dapat direalisasikan dan dapat meminimalisir korban akibat bencana.
5 2014, No.1089 B. Maksud dan Tujuan Pedoman ini dimaksudkan sebagai panduan bagi pemangku kepentingan penanggulangan bencana dalam melakukan standarisasi peralatan penanggulangan bencana.
Tujuan dari pedoman standarisasi peralatan penanggulangan bencana ini adalah untuk meningkatkan kesiapsiagaan, pertolongan dan pelayanan kepada korban bencana secara maksimal, efektif dan efisien.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7120, 'Ancaman bencana di satu daerah dengan daerah lain di Indonesia diyakini tidak sama dan mempunyai ancaman yang berbeda-beda, oleh sebab itu peralatan untuk kesiapsiagaan menghadapi bencana berbeda-beda pula.
Pemerintah Pusat, pemerintah daerah Provinsi dan kabupaten/kota akan lebih tepat bila terlebih dahulu melakukan kajian ancaman bencana pada daerahnya masingmasing (dapat melalui perencanaan kontijensi). Sehingga dapat diketahui kebutuhan peralatan yang mendesak bila terjadi bencana.
Kebutuhan peralatan bencana baik jenis dan jumlah yang sesuai dengan ancaman bencananya di setiap daerah dipandang penting, agar diperoleh kesiapsiagaan yang maksimal.Untuk itu perlu dibuat Pedoman Standarisasi Peralatan Penanggulangan Bencana, agar penyelenggaraan penanggulangan bencana dapat berjalan dengan baik dan lancar, dan pada gilirannya penanggulangan bencana yang cepat dan tepat dapat direalisasikan dan dapat meminimalisir korban akibat bencana.
5 2014, No.1089 B. Maksud dan Tujuan Pedoman ini dimaksudkan sebagai panduan bagi pemangku kepentingan penanggulangan bencana dalam melakukan standarisasi peralatan penanggulangan bencana.
Tujuan dari pedoman standarisasi peralatan penanggulangan bencana ini adalah untuk meningkatkan kesiapsiagaan, pertolongan dan pelayanan kepada korban bencana secara maksimal, efektif dan efisien.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2009 tentang Pedoman Standarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7121, 'perka-17-2009', 8, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'C. Ruang Lingkup dan Sistematika Ruang lingkup Pedoman Standarisasi Peralatan Penanggulangan Bencana ini meliputi beberapa aspek standar peralatan minimal yang dimiliki oleh pemerintah pusat/daerah/instansi/lembaga untuk kepentingan penanggulangan bencana.
Pedoman ini disusun dengan sistematika sebagai berikut :
I. PENDAHULUAN.
II. STANDAR MINIMAL PERALATAN PENANGGULANGAN BENCANA SESUAI JENIS BENCANA.
III. STANDAR MINIMAL PERALATAN PENANGGULANGAN BENCANA TINGKAT NASIONAL DAN DAERAH.
IV. PENGENDALIAN DAN PENGAWASAN.
V. PENUTUP.
D. Landasan Hukum.
1. Undang-Undang Nomor 24 Tahun 2007 tentangPenanggulangan Bencana.
2. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara.
3. Undang-Undang Nomor 17 Tahun 2006 tentang Perubahan atas Undang-Undang Nomor 10 Tahun 1995 tentang Kepabeanan.
4. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
5. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
6. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana.
7. Peraturan Pemerintah Nomor 20 tahun 2006 tentangPengelolaan Barang Milik Negara.
8. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008 tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana.
2014, No.1089 6 E. Pengertian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7121, 'C. Ruang Lingkup dan Sistematika Ruang lingkup Pedoman Standarisasi Peralatan Penanggulangan Bencana ini meliputi beberapa aspek standar peralatan minimal yang dimiliki oleh pemerintah pusat/daerah/instansi/lembaga untuk kepentingan penanggulangan bencana.
Pedoman ini disusun dengan sistematika sebagai berikut :
I. PENDAHULUAN.
II. STANDAR MINIMAL PERALATAN PENANGGULANGAN BENCANA SESUAI JENIS BENCANA.
III. STANDAR MINIMAL PERALATAN PENANGGULANGAN BENCANA TINGKAT NASIONAL DAN DAERAH.
IV. PENGENDALIAN DAN PENGAWASAN.
V. PENUTUP.
D. Landasan Hukum.
1. Undang-Undang Nomor 24 Tahun 2007 tentangPenanggulangan Bencana.
2. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara.
3. Undang-Undang Nomor 17 Tahun 2006 tentang Perubahan atas Undang-Undang Nomor 10 Tahun 1995 tentang Kepabeanan.
4. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
5. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
6. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana.
7. Peraturan Pemerintah Nomor 20 tahun 2006 tentangPengelolaan Barang Milik Negara.
8. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008 tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana.
2014, No.1089 6 E. Pengertian.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2009 tentang Pedoman Standarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7122, 'perka-17-2009', 9, 'lampiran', 'Lampiran hal. 6', NULL, 6, '1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnyakorban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, serta kegiatan rehabilitasi dan rekonstruksi.
3. Standarisasi adalah suatu ukuran tertentu dalam pelaksanaan pemberian bantuan kepada korban bencana sesuai kejadian bencana yang meliputi pencegahan dan kesiapsiagaan, tanggap darurat, rehabilitasi dan rekonstruksi.
4. Peralatan adalah segala bentuk alat dan peralatan yang dapat dipergunakan untuk membantu terselenggaranya suatu kegiatan sehingga dengan bantuan alat tersebut manusia dapat memenuhi kebutuhannya dan dapat melaksanakan fungsi kehidupannya sebagai manusia. Termasuk dalam kategori peralatan ini misalnya peralatan kesehatan, peralatan komunikasi, peralatan peringatan dini, peralatan teknik dan sebagainya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7122, '1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnyakorban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, serta kegiatan rehabilitasi dan rekonstruksi.
3. Standarisasi adalah suatu ukuran tertentu dalam pelaksanaan pemberian bantuan kepada korban bencana sesuai kejadian bencana yang meliputi pencegahan dan kesiapsiagaan, tanggap darurat, rehabilitasi dan rekonstruksi.
4. Peralatan adalah segala bentuk alat dan peralatan yang dapat dipergunakan untuk membantu terselenggaranya suatu kegiatan sehingga dengan bantuan alat tersebut manusia dapat memenuhi kebutuhannya dan dapat melaksanakan fungsi kehidupannya sebagai manusia. Termasuk dalam kategori peralatan ini misalnya peralatan kesehatan, peralatan komunikasi, peralatan peringatan dini, peralatan teknik dan sebagainya.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2009 tentang Pedoman Standarisasi Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7123, 'perka-17-2009', 10, 'lampiran', 'Lampiran hal. 6', NULL, 6, '5. Bantuan Luar Negeri adalah bantuan/hibah dari negara-negara sahabat Republik Indonesia atau dari Lembaga Internasional dan Lembaga Asing non Pemerintah, masyarakat Internasional termasuk WNI yang tinggal di Luar Negeri, sukarela, tidak mengikat, berupa barang berwujud, untuk membantu meringankan beban korban bencana di Indonesia.
6. Peralatan Hibah dari luar negeri adalah peralatan penanggulangan bencana yang berasal dari bantuan luar negeri dan dihibahkan kepada pihak pemerintah Indonesia
7. Peralatan yang dipergunakan untuk sementara waktu adalah peralatan yang dimasukan ke wilayah NKRI untuk penanggulangan bencana dan nyata-nyata akan diekspor kembali.
7 2014, No.1089 BAB II STANDAR MINIMAL PERALATAN PENANGGULANGAN BENCANA SESUAI JENIS BENCANA A. Standar Minimal Jenis Peralatan Penanggulangan Bencana.
