INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7129, 'perka-17-2009', 16, 'lampiran', 'Lampiran hal. 11', NULL, 11, '10. Dump Truck BNPB/BPBD/Instasi/Lembaga 11 Beco BNPB/BPBD/Instasi/Lembaga O. Standar Peralatan Penanggulangan Bencana Bantuan dari Luar Negeri diatur dengan Peraturan dan Ketentuan yang berlaku dan dikoordinasikan oleh BNPB, dan proses importasinya sesuai dengan Peraturan Perundangan tentang Kepabeanan.
Peralatan bantuan luar negeri dapat dibedakan menjadi peralatan yang dihibahkan dan peralatan yang dipergunakn untuk sementara waktu yang akan dieksport kembali (re-eksport).
