INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7159, 'perka-17-2009', 46, 'lampiran', 'Lampiran hal. 54', NULL, 54, '3. Pemeliharaan peralatan penanggulangan bencana oleh pihak yang berwenang dan bertanggung jawab.
4. Penghapusan peralatan sesuai dengan peraturan yang berlaku.
5. Proses hibah peralatan penanggulangan bencana sesuai dengan peraturan dan ketentuan yang berlaku tentang Barang Milik Negara.
C. Pertanggungjawaban Pertanggungjawaban keuangan maupun kinerja dalam standarisasi peralatan ini, dilakukan pada setiap tahapan persiapan, proses dan setelah proses penggunaan peralatan penanggulanngan bencana dalam bentuk laporan secara berjenjang dan berkala sesuai dengan prinsip akuntabilitas dan transparansi.
D. Penghapusan Proses penghapusan peralatan penanggulangan bencana diatur dengan peraturan yang berlaku.
BAB V PENUTUP Pedoman Standarisasi Peralatan dalam penanggulangan bencana dimaksudkan sebagai petunjuk praktis yang dipergunakan oleh semua pihak dalam melaksanakan penyelenggaraan peralatan dalam upaya penanganan penanggulangan bencana sejak pra bencana, saat bencana dan pasca 55 2014, No.1089 bencana.Dengan demikian diharapkan pelaksanaan penyelenggaraan peralatan dapat berjalan secara efektif dan efisian dan terkoordinasi dengan baik serta dapat dipertanggungjawabkan.
Sesuai dengan perkembangan kebutuhan, serta situasi dan kondisi lingkungan, maka pedoman standarisasi peralatan penanggulangan bencana dapat dilakukan perbaikan dan penyempurnaan kearah yang lebih tepat.
KEPALABADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7159, '3. Pemeliharaan peralatan penanggulangan bencana oleh pihak yang berwenang dan bertanggung jawab.
