INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7160, 'perka-17-2010', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana');
