INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7161, 'perka-17-2010', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka pelaksanaan Pasal 56 ayat (4) dan Pasal 76 ayat (4) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, diperlukan pedoman umum dalam melaksanakan rehabilitasi dan rekonstruksi;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi Pasca Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7161, 'a. bahwa dalam rangka pelaksanaan Pasal 56 ayat (4) dan Pasal 76 ayat (4) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, diperlukan pedoman umum dalam melaksanakan rehabilitasi dan rekonstruksi;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi Pasca Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7162, 'perka-17-2010', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 32 Tahun 2004 tentangPemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang - Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 Tentang 2014, No.1553 2 Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 23 tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana;
8. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008 tentang Pedoman Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7162, '1. Undang-Undang Nomor 32 Tahun 2004 tentangPemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang - Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 Tentang 2014, No.1553 2 Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
