INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7177, 'perka-17-2010', 17, 'menetapkan', 'BAB VI', NULL, 16, 'KETENTUAN PENUTUP Pasal 13
(1) Dengan dikeluarkannya peraturan ini maka Peraturan Kepala BNPB Nomor 11 Tahun 2008 tentang Rehabilitasi dan Rekonstruksi Pasca Bencana dicabut dan dinyatakan tidak berlaku.
(2) Selain yang sudah ditetapkan dalam pedoman umum ini, pemerintah daerah dapat menyusun peraturan daerah atau ketentuan lain yang bersifat teknis operasional dalam penyelenggaraan rehabilitasi dan rekonstruksi.
Pasal 14 Peraturan Kepala ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
