INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7179, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7180, 'perka-17-2011', 1, 'menimbang', 'Menimbang', NULL, 4, 'a. bahwa penanggulangan bencana merupakan tanggung jawab bersama yang harus dilaksanakan oleh pemerintah, pemerintah daerah dan seluruh unsur serta lapisan masyarakat, termasuk perguruan tinggi dan dunia usaha;
b. bahwa dalam banyak kejadian bencana relawan dari berbagai instansi pemerintah, organisasi masyarakat, Lembaga Swadaya Masyarakat, Perguruan Tinggi dan Dunia Usaha telah banyak memainkan peran penting;
c. bahwa belum ada peraturan perundangan yang mengatur standar-standar dan kualifikasi relawan, pengembangan kapasitas relawan, dan kerjasama antar relawan dalam keseluruhan aspek penanggulangan bencana;
d. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, b dan c di atas, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana Tentang Pedoman Relawan Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7180, 'a. bahwa penanggulangan bencana merupakan tanggung jawab bersama yang harus dilaksanakan oleh pemerintah, pemerintah daerah dan seluruh unsur serta lapisan masyarakat, termasuk perguruan tinggi dan dunia usaha;
b. bahwa dalam banyak kejadian bencana relawan dari berbagai instansi pemerintah, organisasi masyarakat, Lembaga Swadaya Masyarakat, Perguruan Tinggi dan Dunia Usaha telah banyak memainkan peran penting;
c. bahwa belum ada peraturan perundangan yang mengatur standar-standar dan kualifikasi relawan, pengembangan kapasitas relawan, dan kerjasama antar relawan dalam keseluruhan aspek penanggulangan bencana;
d. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, b dan c di atas, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana Tentang Pedoman Relawan Penanggulangan Bencana.', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7181, 'perka-17-2011', 2, 'mengingat', 'Mengingat', NULL, 5, '1. Pasal 4 dan Pasal 27, 28, 29 dan 30 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang pemerintahan daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42 Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non-pemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44 Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
5. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
6. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008 tentang Pedoman Pembentukan Badan Penanggulangan Bencana Daerah;
7. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008 tentang Pedoman Organisasi dan tata kerja Badan Penanggulangan Bencana Daerah;
8. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7181, '1. Pasal 4 dan Pasal 27, 28, 29 dan 30 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang pemerintahan daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42 Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non-pemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44 Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
5. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
6. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008 tentang Pedoman Pembentukan Badan Penanggulangan Bencana Daerah;
7. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008 tentang Pedoman Organisasi dan tata kerja Badan Penanggulangan Bencana Daerah;
8. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana.', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7182, 'perka-17-2011', 3, 'menetapkan', 'Menetapkan', NULL, 6, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN RELAWAN PENANGGULANGAN BENCANA Pertama : Pedoman Relawan Penanggulangan Bencana sebagaimana diuraikan dalam Lampiran Peraturan ini merupakan acuan bagi Pemerintah, Pemerintah Provinsi dan Pemerintah Kabupaten/Kota dan lembaga-lembaga pembina relawan dalam mendorong dan mengelola kerelawanan dalam penanggulangan bencana.
Kedua : Pedoman sebagaimana dimaksud di atas merupakan bagian tak terpisahkan dari Peraturan ini.
Ketiga : Hal-hal yang belum diatur dalam Peraturan ini akan diatur kemudian.
Keempat : Peraturan ini mulai berlaku pada tanggal ditetapkan.
Ditetapkan di Jakarta Pada tanggal 30 Desember 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Ttd.
DR. SYAMSUL MAARIF, M.SI.
LAMPIRAN : PERATURAN KEPALA BNPB TENTANG PEDOMAN RELAWAN PENANGGULANGAN BENCANA NOMOR : 17 TAHUN 2011 TANGGAL : 30 DESEMBER 2011');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7182, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN RELAWAN PENANGGULANGAN BENCANA Pertama : Pedoman Relawan Penanggulangan Bencana sebagaimana diuraikan dalam Lampiran Peraturan ini merupakan acuan bagi Pemerintah, Pemerintah Provinsi dan Pemerintah Kabupaten/Kota dan lembaga-lembaga pembina relawan dalam mendorong dan mengelola kerelawanan dalam penanggulangan bencana.
Kedua : Pedoman sebagaimana dimaksud di atas merupakan bagian tak terpisahkan dari Peraturan ini.
Ketiga : Hal-hal yang belum diatur dalam Peraturan ini akan diatur kemudian.
Keempat : Peraturan ini mulai berlaku pada tanggal ditetapkan.
Ditetapkan di Jakarta Pada tanggal 30 Desember 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Ttd.
DR. SYAMSUL MAARIF, M.SI.
LAMPIRAN : PERATURAN KEPALA BNPB TENTANG PEDOMAN RELAWAN PENANGGULANGAN BENCANA NOMOR : 17 TAHUN 2011 TANGGAL : 30 DESEMBER 2011', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7183, 'perka-17-2011', 4, 'menetapkan', 'BAB I', NULL, 8, 'PENDAHULUAN A. Latar Belakang Indonesia adalah negeri yang rawan bencana, tetapi pada saat yang sama memiliki potensi sumber daya manusia yang besar. Penduduk Indonesia yang banyak dapat diberdayakan dalam menghadapi kedaruratan dan dalam upaya pengurangan risiko bencana. Undang-undang Nomor 24 tahun 2007 tentang Penanggulangan Bencana menetapkan bahwa Pemerintah dan pemerintah daerah adalah penanggung jawab penyelenggaraan penanggulangan bencana.
Namun, Pasal 27 UU tersebut menegaskan bahwa setiap orang berkewajiban untuk melakukan kegiatan penanggulangan bencana. UU ini juga mengatur keterlibatan pihak swasta, lembaga-lembaga non-pemerintah dan lembaga internasional dalam penanggulangan bencana.
Masyarakat dan pihak non-pemerintah dapat berpartisipasi dalam berbagai bentuk kerelawanan dalam penanggulangan bencana dan pengurangan risiko bencana. Agar keterlibatan para pemangku kepentingan dapat terarah dan terkoordinasi, perlu dirumuskan aturan-aturan bagi kerja relawan dalam penanggulangan bencana. Aturan yang dituangkan dalam bentuk pedoman ini akan mengatur peran, hak dan kewajiban relawan dalam menjalankan fungsi kerelawanan pada saat tidak terdapat bencana, dalam masa tanggap darurat, dan saat rehabilitasi-rekonstruksi pasca bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7183, 'PENDAHULUAN A. Latar Belakang Indonesia adalah negeri yang rawan bencana, tetapi pada saat yang sama memiliki potensi sumber daya manusia yang besar. Penduduk Indonesia yang banyak dapat diberdayakan dalam menghadapi kedaruratan dan dalam upaya pengurangan risiko bencana. Undang-undang Nomor 24 tahun 2007 tentang Penanggulangan Bencana menetapkan bahwa Pemerintah dan pemerintah daerah adalah penanggung jawab penyelenggaraan penanggulangan bencana.
Namun, Pasal 27 UU tersebut menegaskan bahwa setiap orang berkewajiban untuk melakukan kegiatan penanggulangan bencana. UU ini juga mengatur keterlibatan pihak swasta, lembaga-lembaga non-pemerintah dan lembaga internasional dalam penanggulangan bencana.
Masyarakat dan pihak non-pemerintah dapat berpartisipasi dalam berbagai bentuk kerelawanan dalam penanggulangan bencana dan pengurangan risiko bencana. Agar keterlibatan para pemangku kepentingan dapat terarah dan terkoordinasi, perlu dirumuskan aturan-aturan bagi kerja relawan dalam penanggulangan bencana. Aturan yang dituangkan dalam bentuk pedoman ini akan mengatur peran, hak dan kewajiban relawan dalam menjalankan fungsi kerelawanan pada saat tidak terdapat bencana, dalam masa tanggap darurat, dan saat rehabilitasi-rekonstruksi pasca bencana.', 'BAB I', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7184, 'perka-17-2011', 5, 'menetapkan', 'BAB I (lanjutan 1)', NULL, 8, 'Pedoman umum bagi relawan penanggulangan bencana ini berlaku bagi semua relawan, baik yang berasal dari organisasi masyarakat, LSM, perguruan tinggi, sektor swasta atau pihak lainnya. Pedoman diharapkan dapat meningkatkan kerjasama antara Pemerintah, pemerintah daerah, organisasi masyarakat, LSM, perguruan tinggi, sektor swasta dan pihak-pihak terkait lainnya dalam penanggulangan bencana. Selain membantu 1 mewujudkan kemudahan bagi relawan, pedoman ini juga akan berfungsi sebagai acuan bagi Pemerintah, pemerintah daerah, masyarakat dan para pemangku kepentingan lainnya dalam melaksanakan fungsi kerelawanan dalam penanggulangan bencana.
B. Maksud dan Tujuan
1. Maksud Pedoman Relawan Penanggulangan Bencana ini dimaksudkan untuk menjadi acuan dan panduan bagi relawan dan lembaga pembina relawan dalam melibatkan diri pada kegiatan-kegiatan penanggulangan bencana.
2. Tujuan
a. Meningkatkan keterlibatan dan peran serta relawan dalam kegiatan penanggulangan bencana.
b. Meningkatkan kapasitas relawan agar dapat bekerja dengan terkoordinasi, efektif dan efisien.
c. Meningkatkan kinerja serta daya dan hasil guna kegiatan relawan.
C. Ruang Lingkup Pedoman ini berisi panduan bagi para relawan, lembaga pembina dan lembaga pengguna untuk ikut ambil bagian dalam kegiatan penanggulangan bencana dan pengurangan risiko bencana. Relawan yang berasal dari luar negeri diatur melalui ketentuan perundangan yang lain.
D. Pengertian');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7184, 'Pedoman umum bagi relawan penanggulangan bencana ini berlaku bagi semua relawan, baik yang berasal dari organisasi masyarakat, LSM, perguruan tinggi, sektor swasta atau pihak lainnya. Pedoman diharapkan dapat meningkatkan kerjasama antara Pemerintah, pemerintah daerah, organisasi masyarakat, LSM, perguruan tinggi, sektor swasta dan pihak-pihak terkait lainnya dalam penanggulangan bencana. Selain membantu 1 mewujudkan kemudahan bagi relawan, pedoman ini juga akan berfungsi sebagai acuan bagi Pemerintah, pemerintah daerah, masyarakat dan para pemangku kepentingan lainnya dalam melaksanakan fungsi kerelawanan dalam penanggulangan bencana.
B. Maksud dan Tujuan
1. Maksud Pedoman Relawan Penanggulangan Bencana ini dimaksudkan untuk menjadi acuan dan panduan bagi relawan dan lembaga pembina relawan dalam melibatkan diri pada kegiatan-kegiatan penanggulangan bencana.
2. Tujuan
a. Meningkatkan keterlibatan dan peran serta relawan dalam kegiatan penanggulangan bencana.
b. Meningkatkan kapasitas relawan agar dapat bekerja dengan terkoordinasi, efektif dan efisien.
c. Meningkatkan kinerja serta daya dan hasil guna kegiatan relawan.
C. Ruang Lingkup Pedoman ini berisi panduan bagi para relawan, lembaga pembina dan lembaga pengguna untuk ikut ambil bagian dalam kegiatan penanggulangan bencana dan pengurangan risiko bencana. Relawan yang berasal dari luar negeri diatur melalui ketentuan perundangan yang lain.
D. Pengertian', 'BAB I (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7185, 'perka-17-2011', 6, 'menetapkan', 'BAB I (lanjutan 2)', NULL, 9, '1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan baik oleh faktor alam, faktor non-alam, maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis bagi manusia.
2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang mengurangi 2 risiko timbulnya bencana, kegiatan pencegahan, tanggap darurat dan rehabilitasi-rekonstruksi pasca bencana.
3. Korban Bencana adalah orang atau kelompok orang yang meninggal dunia, menderita sakit/cacat atau mengalami kerugian lainnya sebagai dampak dari suatu kejadian bencana.
4. Relawan Penanggulangan Bencana, yang selanjutnya disebut relawan, adalah seorang atau sekelompok orang yang memiliki kemampuan dan kepedulian untuk bekerja secara sukarela dan ikhlas dalam upaya penanggulangan bencana.
5. Kesiapsiagaan adalah serangkaian kegiatan yang dilakukan untuk mengantisipasi bencana melalui langkah-langkah yang tepat dan berdaya guna untuk menjamin adanya respons yang cepat dan efektif bila terjadi bencana.
6. Peringatan dini adalah serangkaian kegiatan pemantauan dan pengkajian risiko, serta penyampaian peringatan sesegera mungkin kepada masyarakat yang tinggal di kawasan rawan bencana, tentang kemungkinan terjadinya bencana di suatu tempat oleh lembaga yang berwenang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7185, '1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan baik oleh faktor alam, faktor non-alam, maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis bagi manusia.
2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang mengurangi 2 risiko timbulnya bencana, kegiatan pencegahan, tanggap darurat dan rehabilitasi-rekonstruksi pasca bencana.
3. Korban Bencana adalah orang atau kelompok orang yang meninggal dunia, menderita sakit/cacat atau mengalami kerugian lainnya sebagai dampak dari suatu kejadian bencana.
4. Relawan Penanggulangan Bencana, yang selanjutnya disebut relawan, adalah seorang atau sekelompok orang yang memiliki kemampuan dan kepedulian untuk bekerja secara sukarela dan ikhlas dalam upaya penanggulangan bencana.
5. Kesiapsiagaan adalah serangkaian kegiatan yang dilakukan untuk mengantisipasi bencana melalui langkah-langkah yang tepat dan berdaya guna untuk menjamin adanya respons yang cepat dan efektif bila terjadi bencana.
6. Peringatan dini adalah serangkaian kegiatan pemantauan dan pengkajian risiko, serta penyampaian peringatan sesegera mungkin kepada masyarakat yang tinggal di kawasan rawan bencana, tentang kemungkinan terjadinya bencana di suatu tempat oleh lembaga yang berwenang.', 'BAB I (lanjutan 2)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7186, 'perka-17-2011', 7, 'menetapkan', 'BAB I (lanjutan 3)', NULL, 10, '7. Mitigasi adalah serangkaian upaya untuk mengurangi risiko bencana, baik melalui pembangunan fisik-infrastruktur maupun upaya penyadaran dan peningkatan kemampuan dalam menghadapi ancaman bencana.
8. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang mungkin timbul, yang meliputi kegiatan pencarian, penyelamatan dan evakuasi korban, penyelamatan harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, dan pemulihan sarana-prasarana.
9. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat memadai dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat di wilayah pasca bencana.
10. Rekonstruksi adalah pembangunan kembali semua prasarana, sarana dan kelembagaan di wilayah pasca bencana, baik pada tingkat pemerintahan 3 maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta masyarakat dalam segala aspek kehidupan bermasyarakat.
11. Standar minimum kemampuan relawan adalah persyaratan minimal yang harus dipenuhi oleh seseorang untuk dapat terdaftar sebagai relawan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7186, '7. Mitigasi adalah serangkaian upaya untuk mengurangi risiko bencana, baik melalui pembangunan fisik-infrastruktur maupun upaya penyadaran dan peningkatan kemampuan dalam menghadapi ancaman bencana.
8. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang mungkin timbul, yang meliputi kegiatan pencarian, penyelamatan dan evakuasi korban, penyelamatan harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, dan pemulihan sarana-prasarana.
9. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat memadai dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat di wilayah pasca bencana.
10. Rekonstruksi adalah pembangunan kembali semua prasarana, sarana dan kelembagaan di wilayah pasca bencana, baik pada tingkat pemerintahan 3 maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta masyarakat dalam segala aspek kehidupan bermasyarakat.
11. Standar minimum kemampuan relawan adalah persyaratan minimal yang harus dipenuhi oleh seseorang untuk dapat terdaftar sebagai relawan penanggulangan bencana.', 'BAB I (lanjutan 3)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7187, 'perka-17-2011', 8, 'menetapkan', 'BAB I (lanjutan 4)', NULL, 11, '12. Lembaga pembina adalah instansi pemerintah, dunia usaha, lembaga internasional, perguruan tinggi dan organisasi masyarakat yang membentuk dan membina relawan penanggulangan bencana.
13. Lembaga pengguna adalah instansi pemerintah, dunia usaha, lembaga internasional, perguruan tinggi dan organisasi masyarakat yang menggunakan dan menggerakkan relawan
14. Lembaga usaha adalah badan hukum yang dapat berbentuk badan usaha milik negara, badan usaha milik daerah, koperasi, atau swasta yang dididirikan sesuai dengan ketentuan perundang-undangan yang menjalankan jenis usaha tetap dan terus-menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia.
15. Lembaga internasional adalah organisasi yang berada dalam lingkup struktur organisasi Perserikatan Bangsa-Bangsa atau yang menjalankan tugas-tugas mewakili Perserikatan Bangsa-Bangsa atau organisasi internasional lainnya dan lembaga asing non pemerintah dari negara lain di luar Perserikatan Bangsa-Bangsa.
16. Pembina Teknis adalah lembaga yang bertugas memberi pembinaan secara langsung kepada relawan dalam hal keterampilan-keterampilan teknis seperti keterampilan SAR, logistik, dapur umum, pengelolaan tempat evakuasi, dan keterampilan teknis terkait lainnya.
17. Pembina Fungsional adalah adalah lembaga yang bertugas melakukan pembinaan dan peningkatan kapasitas relawan atau kelompok relawan secara fungsional dan umum, termasuk pembinaan jiwa korsa dan semangat kepemimpinan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7187, '12. Lembaga pembina adalah instansi pemerintah, dunia usaha, lembaga internasional, perguruan tinggi dan organisasi masyarakat yang membentuk dan membina relawan penanggulangan bencana.
13. Lembaga pengguna adalah instansi pemerintah, dunia usaha, lembaga internasional, perguruan tinggi dan organisasi masyarakat yang menggunakan dan menggerakkan relawan
14. Lembaga usaha adalah badan hukum yang dapat berbentuk badan usaha milik negara, badan usaha milik daerah, koperasi, atau swasta yang dididirikan sesuai dengan ketentuan perundang-undangan yang menjalankan jenis usaha tetap dan terus-menerus yang bekerja dan berkedudukan dalam wilayah Negara Kesatuan Republik Indonesia.
15. Lembaga internasional adalah organisasi yang berada dalam lingkup struktur organisasi Perserikatan Bangsa-Bangsa atau yang menjalankan tugas-tugas mewakili Perserikatan Bangsa-Bangsa atau organisasi internasional lainnya dan lembaga asing non pemerintah dari negara lain di luar Perserikatan Bangsa-Bangsa.
16. Pembina Teknis adalah lembaga yang bertugas memberi pembinaan secara langsung kepada relawan dalam hal keterampilan-keterampilan teknis seperti keterampilan SAR, logistik, dapur umum, pengelolaan tempat evakuasi, dan keterampilan teknis terkait lainnya.
17. Pembina Fungsional adalah adalah lembaga yang bertugas melakukan pembinaan dan peningkatan kapasitas relawan atau kelompok relawan secara fungsional dan umum, termasuk pembinaan jiwa korsa dan semangat kepemimpinan.', 'BAB I (lanjutan 4)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
