INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7196, 'perka-17-2011', 17, 'menetapkan', 'VIII. PENUTUP', NULL, 12, '5');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7196, '5', 'VIII. PENUTUP', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7197, 'perka-17-2011', 18, 'menetapkan', 'BAB II', NULL, 13, 'RELAWAN PENANGGULANGAN BENCANA A. Asas dan Prinsip Kerja Relawan
1. Asas Relawan bekerja berdasarkan Pancasila dan Undang-Undang Dasar 1945.
2. Prinsip Kerja Relawan
a. Cepat dan tepat
b. Prioritas
c. Koordinasi
d. Berdaya guna dan berhasil guna
e. Transparansi
f. Akuntabilitas
g. Kemitraan
h. Pemberdayaan
i. Non-diskriminasi
j. Tidak menyebarkan agama
k. Kesetaraan gender
l. Menghormati kearifan lokal
3. Panca Darma Relawan Penanggulangan Bencana
a. Mandiri
b. Profesional
c. Solidaritas
d. Sinergi
e. Akuntabel 6 B. Kewajiban Relawan
a. Mentaati peraturan dan prosedur kebencanaan yang berlaku;
b. Menjunjung tinggi asas, prinsip dan panca darma relawan penanggulangan bencana.
c. Meningkatkan pengetahuan, keterampilan dan kemampuannya dalam penanggulangan bencana;
C. Hak Relawan Relawan penanggulangan bencana berhak untuk:
a. Memperoleh pengakuan dan tanda pengenal relawan penanggulangan bencana;
b. Mendapatkan peningkatan kapasitas yang berhubungan dengan penanggulangan bencana;
c. Mendapatkan perlindungan hukum dalam pelaksanaan tugas penanggulangan bencana.
D. Kecakapan Relawan Relawan penanggulangan bencana perlu memiliki kecakapan-kecakapan atau keterampilan khusus yang dibutuhkan dalam penanggulangan bencana.
Kemahiran relawan dapat digolongkan dalam kelompok kecakapan berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7197, 'RELAWAN PENANGGULANGAN BENCANA A. Asas dan Prinsip Kerja Relawan
1. Asas Relawan bekerja berdasarkan Pancasila dan Undang-Undang Dasar 1945.
2. Prinsip Kerja Relawan
a. Cepat dan tepat
b. Prioritas
c. Koordinasi
d. Berdaya guna dan berhasil guna
e. Transparansi
f. Akuntabilitas
g. Kemitraan
h. Pemberdayaan
i. Non-diskriminasi
j. Tidak menyebarkan agama
k. Kesetaraan gender
l. Menghormati kearifan lokal
3. Panca Darma Relawan Penanggulangan Bencana
a. Mandiri
b. Profesional
c. Solidaritas
d. Sinergi
e. Akuntabel 6 B. Kewajiban Relawan
a. Mentaati peraturan dan prosedur kebencanaan yang berlaku;
b. Menjunjung tinggi asas, prinsip dan panca darma relawan penanggulangan bencana.
c. Meningkatkan pengetahuan, keterampilan dan kemampuannya dalam penanggulangan bencana;
C. Hak Relawan Relawan penanggulangan bencana berhak untuk:
a. Memperoleh pengakuan dan tanda pengenal relawan penanggulangan bencana;
b. Mendapatkan peningkatan kapasitas yang berhubungan dengan penanggulangan bencana;
c. Mendapatkan perlindungan hukum dalam pelaksanaan tugas penanggulangan bencana.
D. Kecakapan Relawan Relawan penanggulangan bencana perlu memiliki kecakapan-kecakapan atau keterampilan khusus yang dibutuhkan dalam penanggulangan bencana.
Kemahiran relawan dapat digolongkan dalam kelompok kecakapan berikut:', 'BAB II', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7198, 'perka-17-2011', 19, 'menetapkan', 'BAB II (lanjutan 1)', NULL, 14, '1. Perencanaan Relawan yang telah menerima pelatihan dan/atau memiliki pengalaman terlibat dalam perencanaan penanggulangan bencana dapat mendukung proses perencanaan kontinjensi, perencanaan tanggap darurat dan perencanaan rehabilitasi dan rekonstruksi pasca bencana.
2. Pendidikan Relawan yang terdidik sebagai pendidik dan/atau berpengalaman menyelenggarakan pendidikan dalam situasi darurat dan pasca bencana dapat membantu petugas dalam penyelenggaraan pendidikan bagi para 7 penyitas bencana terutama anak-anak yang masih berada dalam usia sekolah.
3. Sistem Informasi Geografis dan Pemetaan Relawan yang terdidik dan/atau berpengalaman dalam bidang Sistem Informasi Geografis (SIG) dan pemetaan dapat mendukung petugas dalam mengadakan pemetaan dengan menggunakan sistem informasi geografis dalam situasi tidak ada bencana, saat tanggap darurat maupun pada tahap pasca bencana.
4. Pelatihan, Geladi dan Simulasi Bencana Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang pelatihan, geladi dan simulasi bencana dapat mendukung masyarakat dalam peningkatan kesiapsiagaan bencana melalui pelatihan, geladi dan simulasi bencana.
5. Kaji Cepat Bencana Relawan yang pernah menerima pelatihan dan/atau berpengalaman dalam kaji cepat bencana dapat mendampingi para petugas kaji cepat dalam melakukan pendataan korban, pengungsi dan kerusakan serta kerugian akibat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7198, '1. Perencanaan Relawan yang telah menerima pelatihan dan/atau memiliki pengalaman terlibat dalam perencanaan penanggulangan bencana dapat mendukung proses perencanaan kontinjensi, perencanaan tanggap darurat dan perencanaan rehabilitasi dan rekonstruksi pasca bencana.
2. Pendidikan Relawan yang terdidik sebagai pendidik dan/atau berpengalaman menyelenggarakan pendidikan dalam situasi darurat dan pasca bencana dapat membantu petugas dalam penyelenggaraan pendidikan bagi para 7 penyitas bencana terutama anak-anak yang masih berada dalam usia sekolah.
3. Sistem Informasi Geografis dan Pemetaan Relawan yang terdidik dan/atau berpengalaman dalam bidang Sistem Informasi Geografis (SIG) dan pemetaan dapat mendukung petugas dalam mengadakan pemetaan dengan menggunakan sistem informasi geografis dalam situasi tidak ada bencana, saat tanggap darurat maupun pada tahap pasca bencana.
4. Pelatihan, Geladi dan Simulasi Bencana Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang pelatihan, geladi dan simulasi bencana dapat mendukung masyarakat dalam peningkatan kesiapsiagaan bencana melalui pelatihan, geladi dan simulasi bencana.
5. Kaji Cepat Bencana Relawan yang pernah menerima pelatihan dan/atau berpengalaman dalam kaji cepat bencana dapat mendampingi para petugas kaji cepat dalam melakukan pendataan korban, pengungsi dan kerusakan serta kerugian akibat bencana.', 'BAB II (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7199, 'perka-17-2011', 20, 'menetapkan', 'BAB II (lanjutan 2)', NULL, 15, '6. Pencarian dan Penyelamatan (SAR) dan Evakuasi Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat membantu dalam upaya pencarian, penyelamatan dan evakuasi korban bencana.
7. Transportasi Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam transportasi darurat dapat mendukung para petugas tanggap darurat dalam mengelola transportasi dalam situasi darurat bencana.
8
8. Logistik Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang logistik bencana dapat membantu para petugas dalam mengelola penerimaan, penyimpanan dan distribusi logistik bencana, termasuk pencatatan dan pelaporannya.
9. Keamanan Pangan dan Nutrisi Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung para petugas dalam menjaga kecukupan pangan dan status nutrisi para penyitas bencana dalam penampungan sementara.
10. Dapur Umum Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang pengelolaan dapur umum dapat mendukung para petugas dalam menyiapkan makanan bagi para penyitas bencana dalam penampungan sementara, termasuk menjaga kecukupan, kualitas dan kehigienisan makanan yang disiapkan.
11. Pengelolaan Lokasi Pengungsian dan Huntara Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung para petugas dalam mengelola lokasi penampungan bagi para penyitas bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7199, '6. Pencarian dan Penyelamatan (SAR) dan Evakuasi Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat membantu dalam upaya pencarian, penyelamatan dan evakuasi korban bencana.
7. Transportasi Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam transportasi darurat dapat mendukung para petugas tanggap darurat dalam mengelola transportasi dalam situasi darurat bencana.
8
8. Logistik Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang logistik bencana dapat membantu para petugas dalam mengelola penerimaan, penyimpanan dan distribusi logistik bencana, termasuk pencatatan dan pelaporannya.
9. Keamanan Pangan dan Nutrisi Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung para petugas dalam menjaga kecukupan pangan dan status nutrisi para penyitas bencana dalam penampungan sementara.
10. Dapur Umum Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang pengelolaan dapur umum dapat mendukung para petugas dalam menyiapkan makanan bagi para penyitas bencana dalam penampungan sementara, termasuk menjaga kecukupan, kualitas dan kehigienisan makanan yang disiapkan.
11. Pengelolaan Lokasi Pengungsian dan Huntara Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung para petugas dalam mengelola lokasi penampungan bagi para penyitas bencana.', 'BAB II (lanjutan 2)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7200, 'perka-17-2011', 21, 'menetapkan', 'BAB II (lanjutan 3)', NULL, 16, '12. Pengelolaan Posko Penanggulangan Bencana Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung para petugas dalam mengelola posko penanggulangan bencana.
9
13. Kesehatan/Medis Relawan yang terdidik dalam bidang kesehatan dan/atau memiliki pengalaman dalam bidang medis dapat mendukung para petugas dalam menjaga kesehatan para penyitas bencana, termasuk dalam penyelenggaraan pelayanan kesehatan keliling.
14. Air Bersih, Sanitasi dan Kesehatan Lingkungan Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung para petugas dalam mencegah timbulnya penyakit di lokasi-lokasi penampungan para penyitas bencana melalui pengelolaan air bersih, sanitasi dan kesehatan lingkungan.
15. Keamanan dan Perlindungan Relawan yang terdidik atau telah menerima pelatihan dan/atau memiliki pengalaman dalam bidang ini dapat mendukung petugas dalam menyediakan keamanan dan perlindungan bagi para penyitas bencana dan aset mereka.
16. Gender dan Kelompok Rentan Relawan yang terdidik atau telah menerima pelatihan dan/atau berpengalaman dalam isu gender dan kelompok rentan dapat mendukung petugas dalam menjaga serta melindungi kepentingan kelompok-kelompok yang lebih rentan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7200, '12. Pengelolaan Posko Penanggulangan Bencana Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung para petugas dalam mengelola posko penanggulangan bencana.
9
13. Kesehatan/Medis Relawan yang terdidik dalam bidang kesehatan dan/atau memiliki pengalaman dalam bidang medis dapat mendukung para petugas dalam menjaga kesehatan para penyitas bencana, termasuk dalam penyelenggaraan pelayanan kesehatan keliling.
14. Air Bersih, Sanitasi dan Kesehatan Lingkungan Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung para petugas dalam mencegah timbulnya penyakit di lokasi-lokasi penampungan para penyitas bencana melalui pengelolaan air bersih, sanitasi dan kesehatan lingkungan.
15. Keamanan dan Perlindungan Relawan yang terdidik atau telah menerima pelatihan dan/atau memiliki pengalaman dalam bidang ini dapat mendukung petugas dalam menyediakan keamanan dan perlindungan bagi para penyitas bencana dan aset mereka.
16. Gender dan Kelompok Rentan Relawan yang terdidik atau telah menerima pelatihan dan/atau berpengalaman dalam isu gender dan kelompok rentan dapat mendukung petugas dalam menjaga serta melindungi kepentingan kelompok-kelompok yang lebih rentan.', 'BAB II (lanjutan 3)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7201, 'perka-17-2011', 22, 'menetapkan', 'BAB II (lanjutan 4)', NULL, 17, '17. Psikososial/Konseling/Penyembuhan Trauma Relawan yang terdidik atau pernah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung petugas dalam menjaga kesehatan jiwa penyitas bencana termasuk menangani dampak bencana pada hubungan keluarga.
10
18. Pertukangan dan Perekayasaan Relawan yang terdidik atau pernah menerima pelatihan dan/atau berpengalaman dalam bidang pertukangan dan perekayasaan dapat mendukung dalam pembangunan hunian sementara dan infrastruktur/ fasilitas publik lainnya bagi para penyitas bencana.
19. Pertanian, Peternakan dan Penghidupan Relawan yang terdidik atau pernah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung masyarakat penyitas bencana untuk segera memulihkan penghidupan ekonomi mereka baik melalui kegiatan-kegiatan pertanian, peternakan, perikanan, dan usaha-usaha kecil.
20. Administrasi Relawan yang telah menerima pendidikan atau pelatihan pengelolaan administrasi dan/atau berpengalaman dan menguasai prosedur adminisitrasi dapat membantu kegiatan-kegiatan administrasi dalam penanggulangan bencana.
21. Pengelolaan Keuangan Relawan yang telah menerima pendidikan atau pelatihan dan/atau berpengalaman dalam pengelolaan dan administrasi keuangan dapat membantu kegiatan pengelolaan keuangan dalam penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7201, '17. Psikososial/Konseling/Penyembuhan Trauma Relawan yang terdidik atau pernah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung petugas dalam menjaga kesehatan jiwa penyitas bencana termasuk menangani dampak bencana pada hubungan keluarga.
10
18. Pertukangan dan Perekayasaan Relawan yang terdidik atau pernah menerima pelatihan dan/atau berpengalaman dalam bidang pertukangan dan perekayasaan dapat mendukung dalam pembangunan hunian sementara dan infrastruktur/ fasilitas publik lainnya bagi para penyitas bencana.
19. Pertanian, Peternakan dan Penghidupan Relawan yang terdidik atau pernah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung masyarakat penyitas bencana untuk segera memulihkan penghidupan ekonomi mereka baik melalui kegiatan-kegiatan pertanian, peternakan, perikanan, dan usaha-usaha kecil.
20. Administrasi Relawan yang telah menerima pendidikan atau pelatihan pengelolaan administrasi dan/atau berpengalaman dan menguasai prosedur adminisitrasi dapat membantu kegiatan-kegiatan administrasi dalam penanggulangan bencana.
21. Pengelolaan Keuangan Relawan yang telah menerima pendidikan atau pelatihan dan/atau berpengalaman dalam pengelolaan dan administrasi keuangan dapat membantu kegiatan pengelolaan keuangan dalam penanggulangan bencana.', 'BAB II (lanjutan 4)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7202, 'perka-17-2011', 23, 'menetapkan', 'BAB II (lanjutan 5)', NULL, 18, '22. Bahasa Asing Relawan yang telah menerima pendidikan atau pelatihan bahasa asing dan/atau menguasai serta berpengalaman dalam menggunakan bahasa asing, dapat membantu mendampingi pihak-pihak asing yang terlibat dalam respons bencana di Indonesia.
11
23. Informasi dan Komunikasi Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung para petugas dalam mengelola penyampaian informasi, termasuk informasi peringatan dini jika bahaya masih mengancam, dan mendukung kelancaran komunikasi dalam situasi darurat bencana.
24. Hubungan Media dan Masyarakat Relawan yang telah menerima pendidikan dan pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung petugas dalam menyampaikan informasi kepada media dan masyarakat, termasuk menampung keluhan-keluhan dari pihak media dan masyarakat penyitas bencana maupun penduduk yang tinggal di sekitar lokasi penampungan sementara.
25. Pemantauan, Evaluasi dan Pelaporan Relawan yang telah menerima pelatihan pemantauan, evaluasi dan pelaporan dan/atau berpengalaman dan menguasai keterampilan-keterampilan ini dapat membantu kegiatan pemantauan, evaluasi dan pelaporan dalam penanggulangan bencana.
26. Promosi dan Mobilisasi Relawan Relawan yang terdidik atau pernah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat membantu upaya promosi kerelawanan serta memobilisasi relawan dalam situasi bencana.
E. Sanksi dan Penghargaan bagi Relawan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7202, '22. Bahasa Asing Relawan yang telah menerima pendidikan atau pelatihan bahasa asing dan/atau menguasai serta berpengalaman dalam menggunakan bahasa asing, dapat membantu mendampingi pihak-pihak asing yang terlibat dalam respons bencana di Indonesia.
11
23. Informasi dan Komunikasi Relawan yang telah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung para petugas dalam mengelola penyampaian informasi, termasuk informasi peringatan dini jika bahaya masih mengancam, dan mendukung kelancaran komunikasi dalam situasi darurat bencana.
24. Hubungan Media dan Masyarakat Relawan yang telah menerima pendidikan dan pelatihan dan/atau berpengalaman dalam bidang ini dapat mendukung petugas dalam menyampaikan informasi kepada media dan masyarakat, termasuk menampung keluhan-keluhan dari pihak media dan masyarakat penyitas bencana maupun penduduk yang tinggal di sekitar lokasi penampungan sementara.
25. Pemantauan, Evaluasi dan Pelaporan Relawan yang telah menerima pelatihan pemantauan, evaluasi dan pelaporan dan/atau berpengalaman dan menguasai keterampilan-keterampilan ini dapat membantu kegiatan pemantauan, evaluasi dan pelaporan dalam penanggulangan bencana.
26. Promosi dan Mobilisasi Relawan Relawan yang terdidik atau pernah menerima pelatihan dan/atau berpengalaman dalam bidang ini dapat membantu upaya promosi kerelawanan serta memobilisasi relawan dalam situasi bencana.
E. Sanksi dan Penghargaan bagi Relawan', 'BAB II (lanjutan 5)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7203, 'perka-17-2011', 24, 'menetapkan', 'BAB II (lanjutan 6)', NULL, 19, '(1) Relawan yang melanggar asas, prinsip, panca darma relawan penanggulangan bencana dan aturan serta norma yang disepakati bersama dalam penanggulangan bencana dapat dikenakan sanksi:
a. Sanksi diberikan secara bertingkat mulai dari teguran lisan dan teguran tertulis yang disampaikan oleh atasan langsung relawan 12 bersangkutan, sampai skorsing dan pemberhentian sebagai anggota relawan penanggulangan bencana yang dilakukan oleh lembaga pembina.
b. Sanksi hukum dapat diberikan kepada relawan yang melakukan pelanggaran hukum atau tindak pidana sesuai peraturan perundangan yang berlaku.
(2) Relawan dan organisasi induk relawan yang telah menunjukkan kinerja yang baik dalam upaya penanggulangan bencana dapat diberikan penghargaan.
13');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7203, '(1) Relawan yang melanggar asas, prinsip, panca darma relawan penanggulangan bencana dan aturan serta norma yang disepakati bersama dalam penanggulangan bencana dapat dikenakan sanksi:
a. Sanksi diberikan secara bertingkat mulai dari teguran lisan dan teguran tertulis yang disampaikan oleh atasan langsung relawan 12 bersangkutan, sampai skorsing dan pemberhentian sebagai anggota relawan penanggulangan bencana yang dilakukan oleh lembaga pembina.
b. Sanksi hukum dapat diberikan kepada relawan yang melakukan pelanggaran hukum atau tindak pidana sesuai peraturan perundangan yang berlaku.
(2) Relawan dan organisasi induk relawan yang telah menunjukkan kinerja yang baik dalam upaya penanggulangan bencana dapat diberikan penghargaan.
13', 'BAB II (lanjutan 6)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7204, 'perka-17-2011', 25, 'menetapkan', 'BAB III', NULL, 21, 'PERAN RELAWAN DALAM PENYELENGGARAAN PENANGGULANGAN BENCANA A. Peran Relawan pada Saat Tidak Terjadi Bencana
1. Pada saat tidak terjadi bencana, relawan dapat berperan dalam kegiatan:
a. Pengurangan Risiko Bencana atau mitigasi, antara lain melalui:
1) Penyelenggaraan pelatihan-pelatihan bersama masyarakat 2) Penyuluhan kepada masyarakat 3) Penyediaan informasi untuk meningkatkan kesadaran masyarakat dalam rangka pengurangan risiko bencana 4) Peningkatan kewaspadaan masyarakat
b. Pelatihan, antara lain pelatihan dasar/lanjutan manajemen, pelatihan teknis kebencanaan, geladi dan simulasi bencana
2. Pada situasi terdapat potensi bencana, relawan dapat berperan dalam kegiatan:
a. Kesiapsiagaan, antara lain melalui:
1) Pemantauan perkembangan ancaman dan kerentanan masyarakat 2) Penyuluhan, pelatihan, dan geladi tentang mekanisme tanggap darurat bencana 3) Penyediaan dan penyiapan barang pasokan pemenuhan kebutuhan dasar 4) Penyediaan dan penyiapan bahan, barang, dan peralatan untuk pemenuhan pemulihan prasarana dan sarana 5) Penyiapan lokasi evakuasi
b. Peringatan dini, antara lain melalui pemasangan dan pengujian sistem peringatan dini di tingkat masyarakat 14 B. Peran Relawan pada Saat Tanggap Darurat Pada saat Tanggap Darurat relawan dapat membantu dalam kegiatan:
1. Kaji cepat terhadap cakupan wilayah yang terkena, jumlah korban dan kerusakan, kebutuhan sumber daya, ketersediaan sumber daya serta prediksi perkembangan situasi ke depan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7204, 'PERAN RELAWAN DALAM PENYELENGGARAAN PENANGGULANGAN BENCANA A. Peran Relawan pada Saat Tidak Terjadi Bencana
1. Pada saat tidak terjadi bencana, relawan dapat berperan dalam kegiatan:
a. Pengurangan Risiko Bencana atau mitigasi, antara lain melalui:
1) Penyelenggaraan pelatihan-pelatihan bersama masyarakat 2) Penyuluhan kepada masyarakat 3) Penyediaan informasi untuk meningkatkan kesadaran masyarakat dalam rangka pengurangan risiko bencana 4) Peningkatan kewaspadaan masyarakat
b. Pelatihan, antara lain pelatihan dasar/lanjutan manajemen, pelatihan teknis kebencanaan, geladi dan simulasi bencana
2. Pada situasi terdapat potensi bencana, relawan dapat berperan dalam kegiatan:
a. Kesiapsiagaan, antara lain melalui:
1) Pemantauan perkembangan ancaman dan kerentanan masyarakat 2) Penyuluhan, pelatihan, dan geladi tentang mekanisme tanggap darurat bencana 3) Penyediaan dan penyiapan barang pasokan pemenuhan kebutuhan dasar 4) Penyediaan dan penyiapan bahan, barang, dan peralatan untuk pemenuhan pemulihan prasarana dan sarana 5) Penyiapan lokasi evakuasi
b. Peringatan dini, antara lain melalui pemasangan dan pengujian sistem peringatan dini di tingkat masyarakat 14 B. Peran Relawan pada Saat Tanggap Darurat Pada saat Tanggap Darurat relawan dapat membantu dalam kegiatan:
1. Kaji cepat terhadap cakupan wilayah yang terkena, jumlah korban dan kerusakan, kebutuhan sumber daya, ketersediaan sumber daya serta prediksi perkembangan situasi ke depan', 'BAB III', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7205, 'perka-17-2011', 26, 'menetapkan', 'BAB III (lanjutan 1)', NULL, 22, '2. Pencarian, penyelamatan dan evakuasi warga masyarakat terkena bencana
3. Penyediaan dapur umum
4. Pemenuhan kebutuhan dasar berupa air bersih, sandang, pangan, dan layanan kesehatan termasuk kesehatan lingkungan
5. Penyediaan tempat penampungan/hunian sementara
6. Perlindungan kepada kelompok rentan dengan memberikan prioritas pelayanan
7. Perbaikan/pemulihan darurat untuk kelancaran pasokan kebutuhan dasar kepada korban bencana
8. Penyediaan sistem informasi untuk penanganan kedaruratan
9. Pendampingan psikososial korban bencana
10. Kegiatan lain terkait sosial, budaya dan keagamaan
11. Kegiatan lain terkait kedaruratan.
C. Peran Relawan pada Saat Pasca-Bencana Pada situasi pasca-bencana relawan dapat membantu dalam kegiatan pengumpulan dan pengolahan data kerusakan dan kerugian dalam sektor perumahan, infrastruktur, sosial, ekonomi dan lintas sektor. Relawan juga dapat berpartisipasi dalam kegiatan-kegiatan rehabilitasi-rekonstruksi fisik dan non-fisik dalam masa pemulihan dini.
15');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7205, '2. Pencarian, penyelamatan dan evakuasi warga masyarakat terkena bencana
3. Penyediaan dapur umum
4. Pemenuhan kebutuhan dasar berupa air bersih, sandang, pangan, dan layanan kesehatan termasuk kesehatan lingkungan
5. Penyediaan tempat penampungan/hunian sementara
6. Perlindungan kepada kelompok rentan dengan memberikan prioritas pelayanan
7. Perbaikan/pemulihan darurat untuk kelancaran pasokan kebutuhan dasar kepada korban bencana
8. Penyediaan sistem informasi untuk penanganan kedaruratan
9. Pendampingan psikososial korban bencana
10. Kegiatan lain terkait sosial, budaya dan keagamaan
11. Kegiatan lain terkait kedaruratan.
C. Peran Relawan pada Saat Pasca-Bencana Pada situasi pasca-bencana relawan dapat membantu dalam kegiatan pengumpulan dan pengolahan data kerusakan dan kerugian dalam sektor perumahan, infrastruktur, sosial, ekonomi dan lintas sektor. Relawan juga dapat berpartisipasi dalam kegiatan-kegiatan rehabilitasi-rekonstruksi fisik dan non-fisik dalam masa pemulihan dini.
15', 'BAB III (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7206, 'perka-17-2011', 27, 'menetapkan', 'BAB IV', NULL, 23, 'PENDATAAN RELAWAN A. Alur Pengelolaan Pendataan Relawan Induk Organisasi BNPB B. Pengumpulan Data Relawan Registrasi relawan dilaksanakan oleh masing-masing organisasi induk relawan, dengan persyaratan antara lain:
1. Warga Negara Indonesia berusia 18 tahun ke atas
2. Sehat jasmani dan rohani
3. Memiliki jiwa kerelawanan, semangat pengabdian dan dedikasi tinggi
4. Mampu berkerja secara mandiri dan dapat bekerjasama dengan pihak lain
5. Memiliki pengetahuan, keahlian dan keterampilan yang bermanfaat dalam penanggulangan bencana
6. Tidak sedang terlibat dalam perkara hukum pidana atau tindak subversi
7. Telah diakui dan dikukuhkan sebagai relawan penanggulangan bencana oleh organisasi induk relawan
8. Persyaratan lain ditentukan oleh masing-masing organisasi 16 Induk organisasi relawan diharapkan dapat memberikan informasi data yang akurat tentang potensi dan kapasitas anggotanya (relawan) sehingga dapat tercatat/terregistrasi di BPBD.
C. Pengiriman Data Relawan Organisasi induk relawan mengumpulkan biodata relawan yang dimilikinya dan mengirimkannya ke BPBD di daerahnya. Selanjutnya BPBD akan mengirimkan ke BNPB untuk dicatat dalam database relawan. (Format biodata harus mengacu pada format di lampiran peraturan ini) D. Verifikasi Data dari formulir relawan yang telah tercatat untuk diverifikasi dan selanjutnya dilegalisasi sesuai peraturan administrasi BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7206, 'PENDATAAN RELAWAN A. Alur Pengelolaan Pendataan Relawan Induk Organisasi BNPB B. Pengumpulan Data Relawan Registrasi relawan dilaksanakan oleh masing-masing organisasi induk relawan, dengan persyaratan antara lain:
1. Warga Negara Indonesia berusia 18 tahun ke atas
2. Sehat jasmani dan rohani
3. Memiliki jiwa kerelawanan, semangat pengabdian dan dedikasi tinggi
4. Mampu berkerja secara mandiri dan dapat bekerjasama dengan pihak lain
5. Memiliki pengetahuan, keahlian dan keterampilan yang bermanfaat dalam penanggulangan bencana
6. Tidak sedang terlibat dalam perkara hukum pidana atau tindak subversi
7. Telah diakui dan dikukuhkan sebagai relawan penanggulangan bencana oleh organisasi induk relawan
8. Persyaratan lain ditentukan oleh masing-masing organisasi 16 Induk organisasi relawan diharapkan dapat memberikan informasi data yang akurat tentang potensi dan kapasitas anggotanya (relawan) sehingga dapat tercatat/terregistrasi di BPBD.
C. Pengiriman Data Relawan Organisasi induk relawan mengumpulkan biodata relawan yang dimilikinya dan mengirimkannya ke BPBD di daerahnya. Selanjutnya BPBD akan mengirimkan ke BNPB untuk dicatat dalam database relawan. (Format biodata harus mengacu pada format di lampiran peraturan ini) D. Verifikasi Data dari formulir relawan yang telah tercatat untuk diverifikasi dan selanjutnya dilegalisasi sesuai peraturan administrasi BNPB.', 'BAB IV', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7207, 'perka-17-2011', 28, 'menetapkan', 'BAB IV (lanjutan 1)', NULL, 24, 'E. Pendataan dan Pencatatan Pada dasarnya pendataan relawan dilaksanakan oleh masing-masing organisasi induk relawan dan selanjutnya dapat dikoordinasikan ke BPBD.
Seleksi, pemberian nomor, kecakapan dan pengkodean untuk kebutuhan database secara nasional dilaksanakan oleh BNPB, sedangkan untuk kebutuhan database daerah dikelola oleh BPBD.
Pengkodean relawan adalah sebagai berikut:
Provinsi : 2 digit Kabupaten/Kota : 2 digit Nomor Urut : 6 digit (1 huruf dan 5 angka) Kelompok kecakapan : 2 digit Total Kode Register : 12 digit Contoh :
11 . 01 . A. 00001 . . 01 Provinsi Kabupaten/ Kota Nomor Urut Kecakapan 17 F. Rekognisi Rekognisi adalah pengakuan bahwa relawan memiliki kecakapan dan kemampuan tertentu dalam penanggulangan bencana, baik dalam hal kegiatan-kegiatan pengurangan risiko bencana saat tidak terjadi bencana, kegiatan tanggap darurat maupun kegiatan pemulihan pasca bencana.
Selain memperoleh pengakuan, relawan dapat mengikuti uji kompetensi berdasarkan standar-standar kecakapan tertentu. Penilaian dilakukan oleh BNPB dan/atau lembaga-lembaga pembina relawan terkait.
Penilaian juga mempertimbangkan faktor-faktor lamanya pengabdian sebagai relawan dan/atau prestasi dalam kegiatan penanggulangan bencana. Relawan yang lulus penilaian kompetensi akan memperoleh penghargaan yang dapat berupa sertifikat, piagam atau brevet.
18');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7207, 'E. Pendataan dan Pencatatan Pada dasarnya pendataan relawan dilaksanakan oleh masing-masing organisasi induk relawan dan selanjutnya dapat dikoordinasikan ke BPBD.
Seleksi, pemberian nomor, kecakapan dan pengkodean untuk kebutuhan database secara nasional dilaksanakan oleh BNPB, sedangkan untuk kebutuhan database daerah dikelola oleh BPBD.
Pengkodean relawan adalah sebagai berikut:
Provinsi : 2 digit Kabupaten/Kota : 2 digit Nomor Urut : 6 digit (1 huruf dan 5 angka) Kelompok kecakapan : 2 digit Total Kode Register : 12 digit Contoh :
11 . 01 . A. 00001 . . 01 Provinsi Kabupaten/ Kota Nomor Urut Kecakapan 17 F. Rekognisi Rekognisi adalah pengakuan bahwa relawan memiliki kecakapan dan kemampuan tertentu dalam penanggulangan bencana, baik dalam hal kegiatan-kegiatan pengurangan risiko bencana saat tidak terjadi bencana, kegiatan tanggap darurat maupun kegiatan pemulihan pasca bencana.
Selain memperoleh pengakuan, relawan dapat mengikuti uji kompetensi berdasarkan standar-standar kecakapan tertentu. Penilaian dilakukan oleh BNPB dan/atau lembaga-lembaga pembina relawan terkait.
Penilaian juga mempertimbangkan faktor-faktor lamanya pengabdian sebagai relawan dan/atau prestasi dalam kegiatan penanggulangan bencana. Relawan yang lulus penilaian kompetensi akan memperoleh penghargaan yang dapat berupa sertifikat, piagam atau brevet.
18', 'BAB IV (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7208, 'perka-17-2011', 29, 'menetapkan', 'BAB V', NULL, 26, 'PEMBINAAN Pembinaan relawan mencakup segala usaha, tindakan dan kegiatan yang berhubungan dengan perencanaan, pendidikan dan pelatihan, pengembangan kapasitas, pengerahan, serta pengendalian kegiatan kerelawanan.
Pembinaan relawan bertujuan untuk:
1. Meningkatkan kompetensi (pengetahuan, sikap dan perilaku) dan integritas relawan;
2. Meningkatkan kapasitas relawan agar dapat bekerja dengan baik dan profesional, serta menunjukkan kinerja maksimal.
A. Aspek-aspek Pembinaan Aspek pembinaan yang dilakukan mencakup aspek kepemimpinan, kompetensi, pemupukan jiwa korsa dan aspek kelembagaan.
1. Pembinaan Kepemimpinan Pengurus Lembaga Pembina relawan di masing-masing tingkatan berkewajiban melakukan pembinaan kepemimpinan para relawan dalam hal:
a. Meningkatkan kesadaran dan pemahaman akan mandat utama, asas, prinsip kerja dan tanggung jawab relawan;
b. Membangun komitmen bersama dalam penanggulangan bencana yang kokoh;
c. Mengkoordinasikan perencanaan, pengorganisasian, pelaksanaan dan pengendalian kegiatan kerelawanan;
d. Memimpin dan membangun kerjasama tim.
2. Pembinaan Kompetensi Pengembangan kapasitas relawan dilaksanakan secara:
a. Bertahap, terarah dan berkesinambungan.
19
b. Proporsional dalam pembagian tugas dan tanggung jawab antara Pemerintah Pusat, Povinsi, Kabupaten/Kota dan lembaga pembina relawan.
c. Pengembangan kapasitas dilaksanakan agar relawan memiliki kompetensi dalam:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7208, 'PEMBINAAN Pembinaan relawan mencakup segala usaha, tindakan dan kegiatan yang berhubungan dengan perencanaan, pendidikan dan pelatihan, pengembangan kapasitas, pengerahan, serta pengendalian kegiatan kerelawanan.
Pembinaan relawan bertujuan untuk:
1. Meningkatkan kompetensi (pengetahuan, sikap dan perilaku) dan integritas relawan;
2. Meningkatkan kapasitas relawan agar dapat bekerja dengan baik dan profesional, serta menunjukkan kinerja maksimal.
A. Aspek-aspek Pembinaan Aspek pembinaan yang dilakukan mencakup aspek kepemimpinan, kompetensi, pemupukan jiwa korsa dan aspek kelembagaan.
1. Pembinaan Kepemimpinan Pengurus Lembaga Pembina relawan di masing-masing tingkatan berkewajiban melakukan pembinaan kepemimpinan para relawan dalam hal:
a. Meningkatkan kesadaran dan pemahaman akan mandat utama, asas, prinsip kerja dan tanggung jawab relawan;
b. Membangun komitmen bersama dalam penanggulangan bencana yang kokoh;
c. Mengkoordinasikan perencanaan, pengorganisasian, pelaksanaan dan pengendalian kegiatan kerelawanan;
d. Memimpin dan membangun kerjasama tim.
2. Pembinaan Kompetensi Pengembangan kapasitas relawan dilaksanakan secara:
a. Bertahap, terarah dan berkesinambungan.
19
b. Proporsional dalam pembagian tugas dan tanggung jawab antara Pemerintah Pusat, Povinsi, Kabupaten/Kota dan lembaga pembina relawan.
c. Pengembangan kapasitas dilaksanakan agar relawan memiliki kompetensi dalam:', 'BAB V', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7209, 'perka-17-2011', 30, 'menetapkan', 'BAB V (lanjutan 1)', NULL, 27, '1) Pencarian dan penyelamatan 2) Dapur umum 3) Logistik 4) Informasi dan komunikasi 5) Manajemen tempat evakuasi 6) Pengelolaan air, sanitasi dan kesehatan lingkungan 7) Kesehatan pengungsi 8) Penanganan psikososial 9) Standar-standar minimum dalam penanggulangan bencana 10) Pengurangan risiko bencanasesuai dengan renana kontinjens
d. Peningkatan kompetensi dapat dicapai melalui berbagai cara, antara lain:
1) Orientasi 2) Pendidikan dan pelatihan 3) Geladi 4) Simulasi
e. Pelatihan untuk relawan dibedakan menjadi pelatihan dasar, pelatihan lanjutan dan pelatihan manajerial. Pelatihan dasar, lanjutan dan manajerial ditangani langsung oleh lembaga pembina teknis, sedangkan pelatihan yang sifatnya spesifik akan ditangani oleh lembaga pembina fungsional.
f. Hal-hal yang terkait dengan pendidikan dan pelatihan relawan Penanggulangan Bencana akan diatur dalam peraturan tersendiri.
20
3. Pembinaan Jiwa Korsa dan Karakter
a. Pembinaan jiwa korsa menjadi tanggung jawab Lembaga Pembina Teknis dan Pembina Fungsional di masing-masing tingkatan.
b. Pelaksanaan pembinaan dikembangkan berdasarkan prinsip-prinsip dan aturan yang berlaku pada organisasi induk relawan.
4. Pembinaan Kelembagaan
a. BNPB dan BPBD membantu lembaga-lembaga relawan dalam melaksanakan pembinaan kelembagaan.
b. Pembinaan kelembagaan dapat dikembangkan melalui pemberian dukungan manajerial dan sumber daya untuk penguatan kelembagaan organisasi relawan.
B. Lembaga Pembina');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7209, '1) Pencarian dan penyelamatan 2) Dapur umum 3) Logistik 4) Informasi dan komunikasi 5) Manajemen tempat evakuasi 6) Pengelolaan air, sanitasi dan kesehatan lingkungan 7) Kesehatan pengungsi 8) Penanganan psikososial 9) Standar-standar minimum dalam penanggulangan bencana 10) Pengurangan risiko bencanasesuai dengan renana kontinjens
d. Peningkatan kompetensi dapat dicapai melalui berbagai cara, antara lain:
1) Orientasi 2) Pendidikan dan pelatihan 3) Geladi 4) Simulasi
e. Pelatihan untuk relawan dibedakan menjadi pelatihan dasar, pelatihan lanjutan dan pelatihan manajerial. Pelatihan dasar, lanjutan dan manajerial ditangani langsung oleh lembaga pembina teknis, sedangkan pelatihan yang sifatnya spesifik akan ditangani oleh lembaga pembina fungsional.
f. Hal-hal yang terkait dengan pendidikan dan pelatihan relawan Penanggulangan Bencana akan diatur dalam peraturan tersendiri.
20
3. Pembinaan Jiwa Korsa dan Karakter
a. Pembinaan jiwa korsa menjadi tanggung jawab Lembaga Pembina Teknis dan Pembina Fungsional di masing-masing tingkatan.
b. Pelaksanaan pembinaan dikembangkan berdasarkan prinsip-prinsip dan aturan yang berlaku pada organisasi induk relawan.
4. Pembinaan Kelembagaan
a. BNPB dan BPBD membantu lembaga-lembaga relawan dalam melaksanakan pembinaan kelembagaan.
b. Pembinaan kelembagaan dapat dikembangkan melalui pemberian dukungan manajerial dan sumber daya untuk penguatan kelembagaan organisasi relawan.
B. Lembaga Pembina', 'BAB V (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7210, 'perka-17-2011', 31, 'menetapkan', 'BAB V (lanjutan 2)', NULL, 28, 'a. Lembaga Pembina adalah: instansi/lembaga/organisasi yang menjadi induk organisasi relawan.
b. Lembaga pembina bertanggung jawab dalam merekrut, mengembangkan kapasitas, menfasilitasi dan membantu pengerahan relawan.
c. Lembaga pembina relawan penanggulangan bencana wajib berkoordinasi dan melaporkan keberadaannya ke BPBD.
C. Pembinaan Jaringan Relawan Pembinaan jaringan relawan dilaksanakan melalui:
1. Forum Relawan Forum Relawan merupakan bagian dari kebijakan strategis pembinaan relawan. Forum Relawan berfungsi sebagai sarana menjalin komunikasi dan koordinasi berkelanjutan antar relawan di 21 seluruh Indonesia. Forum ini membantu organisasi induk relawan dengan memberikan gagasan, pemikiran, saran dan pendapat bagi pengembangan manajemen relawan secara berkesinambungan.
Forum Relawan dapat sebagai wahana mediasi untuk membantu penyelesaian permasalahan dalam tugas dan fungsi serta kelembagaan relawan.
2. Pembuatan media sosial relawan Komunikasi antar relawan merupakan hal yang penting, terutama untuk saling berbagi pengalaman, dan bertukar informasi dalam menjalankan tugas penanggulangan bencana. Upaya meningkatkan komunikasi antar relawan dapat dicapai melalui pengembangan buletin, milis relawan penanggulangan bencana, atau media-media serupa lainnya yang mudah diakses relawan.
22');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7210, 'a. Lembaga Pembina adalah: instansi/lembaga/organisasi yang menjadi induk organisasi relawan.
b. Lembaga pembina bertanggung jawab dalam merekrut, mengembangkan kapasitas, menfasilitasi dan membantu pengerahan relawan.
c. Lembaga pembina relawan penanggulangan bencana wajib berkoordinasi dan melaporkan keberadaannya ke BPBD.
C. Pembinaan Jaringan Relawan Pembinaan jaringan relawan dilaksanakan melalui:
1. Forum Relawan Forum Relawan merupakan bagian dari kebijakan strategis pembinaan relawan. Forum Relawan berfungsi sebagai sarana menjalin komunikasi dan koordinasi berkelanjutan antar relawan di 21 seluruh Indonesia. Forum ini membantu organisasi induk relawan dengan memberikan gagasan, pemikiran, saran dan pendapat bagi pengembangan manajemen relawan secara berkesinambungan.
Forum Relawan dapat sebagai wahana mediasi untuk membantu penyelesaian permasalahan dalam tugas dan fungsi serta kelembagaan relawan.
2. Pembuatan media sosial relawan Komunikasi antar relawan merupakan hal yang penting, terutama untuk saling berbagi pengalaman, dan bertukar informasi dalam menjalankan tugas penanggulangan bencana. Upaya meningkatkan komunikasi antar relawan dapat dicapai melalui pengembangan buletin, milis relawan penanggulangan bencana, atau media-media serupa lainnya yang mudah diakses relawan.
22', 'BAB V (lanjutan 2)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7211, 'perka-17-2011', 32, 'menetapkan', 'BAB VI', NULL, 30, 'PENGERAHAN RELAWAN A. Persiapan Hal-hal yang harus dilakukan saat persiapan pengerahan:
1. Sebelum pengerahan Sebelum pengerahan relawan perlu dilakukan hal-hal berikut:
a. Penjelasan singkat tentang daerah bencana, dampak bencana, peta lokasi bencana, rute perjalanan, pos aju atau pos induk, jalur evakuasi, situasi terkini, lamanya waktu tugas, dan pihak-pihak yang harus dihubungi untuk koordinasi;
b. Pembagian tugas sesuai kompetensi yang dimiliki;
c. Pelengkapan sarana dan prasarana penugasan;
d. Pengecekan kesehatan relawan;
e. Pelaporan kegiatan berkala disampaikan kepada komandan;
f. Koordinasi dan komunikasi dengan pihak terkait di lapangan oleh organisasi induk relawan;
g. Evaluasi perkembangan situasi setiap hari bersama relawan lain atau pelaksana kegiatan kemanusiaan lainnya.
2. Pelengkapan Administrasi dan Sarana Pendukung Penugasan
a. Perlengkapan administrasi yang wajib dibawa relawan antara lain surat tugas, kartu pengenal individu, dan Kartu Anggota Relawan;
b. Untuk tanggap darurat relawan dibekali perlengkapan Alat Pengamanan Diri (APD) pribadi sesuai jenis bencana dan bidang tugas, dan kelengkapan regu sesuai kebutuhan;
c. Relawan harus membawa sendiri perlengkapan pribadi sehari-hari.
23 B. Pengerahan
1. Pengerahan Tingkat Kabupaten/Kota dan Provinsi
a. BPBD Provinsi/Kabupaten/Kota memberikan informasi kepada organisasi induk relawan tentang kebutuhan relawan untuk dikerahkan/penugasan dalam penanggulangan bencana sesuai kebutuhan di lokasi bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7211, 'PENGERAHAN RELAWAN A. Persiapan Hal-hal yang harus dilakukan saat persiapan pengerahan:
1. Sebelum pengerahan Sebelum pengerahan relawan perlu dilakukan hal-hal berikut:
a. Penjelasan singkat tentang daerah bencana, dampak bencana, peta lokasi bencana, rute perjalanan, pos aju atau pos induk, jalur evakuasi, situasi terkini, lamanya waktu tugas, dan pihak-pihak yang harus dihubungi untuk koordinasi;
b. Pembagian tugas sesuai kompetensi yang dimiliki;
c. Pelengkapan sarana dan prasarana penugasan;
d. Pengecekan kesehatan relawan;
e. Pelaporan kegiatan berkala disampaikan kepada komandan;
f. Koordinasi dan komunikasi dengan pihak terkait di lapangan oleh organisasi induk relawan;
g. Evaluasi perkembangan situasi setiap hari bersama relawan lain atau pelaksana kegiatan kemanusiaan lainnya.
2. Pelengkapan Administrasi dan Sarana Pendukung Penugasan
a. Perlengkapan administrasi yang wajib dibawa relawan antara lain surat tugas, kartu pengenal individu, dan Kartu Anggota Relawan;
b. Untuk tanggap darurat relawan dibekali perlengkapan Alat Pengamanan Diri (APD) pribadi sesuai jenis bencana dan bidang tugas, dan kelengkapan regu sesuai kebutuhan;
c. Relawan harus membawa sendiri perlengkapan pribadi sehari-hari.
23 B. Pengerahan
1. Pengerahan Tingkat Kabupaten/Kota dan Provinsi
a. BPBD Provinsi/Kabupaten/Kota memberikan informasi kepada organisasi induk relawan tentang kebutuhan relawan untuk dikerahkan/penugasan dalam penanggulangan bencana sesuai kebutuhan di lokasi bencana.', 'BAB VI', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7212, 'perka-17-2011', 33, 'menetapkan', 'BAB VI (lanjutan 1)', NULL, 31, 'b. Lembaga pembina tingkat Provinsi/Kabupaten/Kota menugaskan relawannya sesuai kriteria/kecakapan dan jumlah yang dibutuhkan di lokasi bencana.
c. Lembaga pembina segera berkoordinasi dengan lembaga/instansi pengguna dan/atau BPBD yang memerlukan dukungan relawan terkait dengan lokasi, beban/uraian tugas dan lama penugasan.
d. Pengendalian kegiatan di lapangan, mulai dari pemberangkatan hingga di lokasi tempat tugas sampai pemulangan selalu dipantau oleh lembaga pembina.
e. Setiap relawan yang ditugaskan harus bertanggung jawab terhadap pelaksanaan tugasnya dan menyampaikan laporan sesuai ketentuan yang berlaku.
2. Penugasan melalui Kerjasama dengan Pihak Lain
a. Penugasan Relawan dengan kerjasama lembaga/instansi maupun organisasi lain harus melalui surat resmi.
b. Bila dianggap perlu, penugasan relawan dapat disahkan melalui Surat Perjanjian antara lembaga-lembaga terkait
3. Mekanisme Pengerahan Relawan
a. Masyarakat/lembaga/instansi di lokasi bencana berkoordinasi dengan BPBD wilayah tersebut tentang permintaan dukungan relawan.
b. BPBD mengajukan/bersurat kepada organisasi induk relawan tentang kebutuhan jumlah tenaga relawan dan rincian kecakapan yang dibutuhkan untuk dikerahkan ke lokasi bencana.
24
c. Selanjutnya organisasi induk relawan menverifikasi kebutuhan relawan serta melengkapi administrasi berdasarkan permintaan.
d. Organisasi induk relawan menyerahkan relawan melalui BPBD dan/atau langsung melalui Komandan Tanggap Darurat/Koordinator Lapangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7212, 'b. Lembaga pembina tingkat Provinsi/Kabupaten/Kota menugaskan relawannya sesuai kriteria/kecakapan dan jumlah yang dibutuhkan di lokasi bencana.
c. Lembaga pembina segera berkoordinasi dengan lembaga/instansi pengguna dan/atau BPBD yang memerlukan dukungan relawan terkait dengan lokasi, beban/uraian tugas dan lama penugasan.
d. Pengendalian kegiatan di lapangan, mulai dari pemberangkatan hingga di lokasi tempat tugas sampai pemulangan selalu dipantau oleh lembaga pembina.
