INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7216, 'perka-17-2011', 37, 'menetapkan', 'BAB VIII', NULL, 36, 'PENUTUP Pedoman Relawan Penanggulangan Bencana ini dibuat untuk dijadikan acuan bagi relawan, lembaga pembina dan lembaga pengguna agar peran relawan dalam penanggulangan bencana dapat dilaksanakan secara cepat, tepat, terpadu, efektif, efisien, transparan dan bertanggung jawab.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7216, 'PENUTUP Pedoman Relawan Penanggulangan Bencana ini dibuat untuk dijadikan acuan bagi relawan, lembaga pembina dan lembaga pengguna agar peran relawan dalam penanggulangan bencana dapat dilaksanakan secara cepat, tepat, terpadu, efektif, efisien, transparan dan bertanggung jawab.', 'BAB VIII', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2011 tentang Pedoman Relawan Penangguangan Bencana');
