INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7219, 'perka-17-2011', 40, 'lampiran', 'Lampiran hal. 38', NULL, 38, '(berapa lama relawan harus memberikan komitmen waktunya) Lokasi kerja dan : waktu bertugas (tempat relawan akan bertugas dan waktu tugas di lokasi, misalnya rata-rata kerja lapangan sekitar 5 jam (10.00 – 15.00) dan sisanya stand-by di posko) Supervisi : /Pengawasan dan (jabarkan seperti apa pengawasan dan pemantauan yang akan dilakukan dan Pemantauan siapa yang melakukan) Jaminan : perlindungan 31 (Tuliskan hal-hal apa saja yang disediakan oleh lembaga yang meminta relawan, misalnya tempat tinggal, makan, biaya kesehatan, dll. Tuliskan pula hal-hal apa yang tidak disediakan) Nama dan kontak :
Koordinator Relawan (nama staf yang bertanggung jawab langsung terhadap posisi relawan) Tertanda, Lembaga yang Meminta Dukungan Relawan (Nama Lembaga) (tanda tangan personil yang diberi mandat oleh BNPB/BPBD untuk melakukan permintaan) 32 Contoh Form Jawaban atas Permintaan Relawan dari Jejaring/Lembaga Lain Lampiran 3 Disi oleh BNPB/BPBD bila Lembaga memberi dukungan terhadap permintaan Dukungan Relawan PB PEMBERIAN DUKUNGAN RELAWAN Kepada LEMBAGA .....................................
Berdasarkan permintaan dari ............................. (nama lembaga yang meminta dukungan relawan) kepada ....................... (nama lembaga yang dimintai dukungan relawan), maka Kami menugaskan ...... (orang) relawan untuk mendukung tugas-tugas sosial kemanusiaan dalam Lembaga Anda selama masa tugas .............
(tuliskan lamanya relawan ditugaskan).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7219, '(berapa lama relawan harus memberikan komitmen waktunya) Lokasi kerja dan : waktu bertugas (tempat relawan akan bertugas dan waktu tugas di lokasi, misalnya rata-rata kerja lapangan sekitar 5 jam (10.00 – 15.00) dan sisanya stand-by di posko) Supervisi : /Pengawasan dan (jabarkan seperti apa pengawasan dan pemantauan yang akan dilakukan dan Pemantauan siapa yang melakukan) Jaminan : perlindungan 31 (Tuliskan hal-hal apa saja yang disediakan oleh lembaga yang meminta relawan, misalnya tempat tinggal, makan, biaya kesehatan, dll. Tuliskan pula hal-hal apa yang tidak disediakan) Nama dan kontak :
