INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7223, 'perka-17-2011', 44, 'lampiran', 'Lampiran hal. 44', NULL, 44, 'VI. SURAT PERNYATAAN SEBAGAI RELAWAN PENANGGULANGAN BENCANA INDONESIA Dengan ini menyatakan bahwa saya bersedia menjadi relawan penanggulangan bencana Indonesia yang siap untuk ditugaskan ke lokasi kejadian bencana. Selama menjalankan tugas saya sebagai Relawan akan mentaati ketentuan yang ditetapkan oleh Badan Nasional Penanggulangan Bencana.
Demikian pernyataan ini saya buat dengan sungguh-sungguh dan penuh tanggung jawab. ……………, ……/….……………../…………… Mengetahui, Pimpinan Organisasi ttd ttd ( ) ( ) 37 Lampiran 6 Format Pemantauan dan Evaluasi Kegiatan Relawan Penanggulangan Bencana Nama Pelaksana Pemantauan dan Evaluasi :
Instansi :
Tempat/Tanggal :
Jenis Bencana :
