INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7227, 'perka-17-2014', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA CARA PEMBERIAN TUNJANGAN KINERJA PEGAWAI DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7227, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG TATA CARA PEMBERIAN TUNJANGAN KINERJA PEGAWAI DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7228, 'perka-17-2014', 4, 'pasal', 'Pasal 1', 'BAB II TUNJANGAN KINERJA, KELAS JABATAN, BESARNYA TUNJANGAN KINERJA, DAN PAJAK PENGHASILAN ATAS TUNJANGAN KINERJA', 3, 'Dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana ini yang dimaksud dengan :
1. Aparatur Sipil Negara yang selanjutnya disingkat ASN adalah profesi bagi pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang bekerja pada instansi pemerintah.
2. Pegawai Negeri Sipil yang selanjutnya disebut PNS adalah Pegawai Negeri Sipil di Lingkungan Badan Nasional Penanggulangan Bencana termasuk Calon Pegawai Negeri Sipil.
3. Pegawai Aparatur Sipil Negara yang selanjutnya disebut Pegawai ASN adalah pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan digaji berdasarkan peraturan perundang-undangan.
4. Tunjangan Kinerja adalah tunjangan sebagaimana diatur di dalam Peraturan Presiden Nomor 112 Tahun 2014 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.
5. Kelas Jabatan adalah pengelompokan sejumlah jabatan yang memiliki bobot yang relatif sama, dengan tujuan memberikan penghargaan kepada PNS sesuai dengan nilai jabatan pekerjaan.
6. Badan Pertimbangan Kepegawaian adalah unsur pembantu pimpinan yang bertugas memberikan pertimbangan dalam hal pengangkatan dan pemindahan jabatan, kenaikan pangkat istimewa serta penunjukan Pegawai Negeri Sipil sebagai peserta diklat jabatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7228, 'Dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana ini yang dimaksud dengan :
1. Aparatur Sipil Negara yang selanjutnya disingkat ASN adalah profesi bagi pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang bekerja pada instansi pemerintah.
2. Pegawai Negeri Sipil yang selanjutnya disebut PNS adalah Pegawai Negeri Sipil di Lingkungan Badan Nasional Penanggulangan Bencana termasuk Calon Pegawai Negeri Sipil.
3. Pegawai Aparatur Sipil Negara yang selanjutnya disebut Pegawai ASN adalah pegawai negeri sipil dan pegawai pemerintah dengan perjanjian kerja yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan digaji berdasarkan peraturan perundang-undangan.
4. Tunjangan Kinerja adalah tunjangan sebagaimana diatur di dalam Peraturan Presiden Nomor 112 Tahun 2014 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.
5. Kelas Jabatan adalah pengelompokan sejumlah jabatan yang memiliki bobot yang relatif sama, dengan tujuan memberikan penghargaan kepada PNS sesuai dengan nilai jabatan pekerjaan.
6. Badan Pertimbangan Kepegawaian adalah unsur pembantu pimpinan yang bertugas memberikan pertimbangan dalam hal pengangkatan dan pemindahan jabatan, kenaikan pangkat istimewa serta penunjukan Pegawai Negeri Sipil sebagai peserta diklat jabatan.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7229, 'perka-17-2014', 5, 'pasal', 'Pasal 2', 'BAB II TUNJANGAN KINERJA, KELAS JABATAN, BESARNYA TUNJANGAN KINERJA, DAN PAJAK PENGHASILAN ATAS TUNJANGAN KINERJA', 3, '(1) Tunjangan kinerja dibayarkan kepada PNS di Lingkungan Badan Nasional Penanggulangan Bencana setiap bulan.
2014, No.1831 4
(2) Besar tunjangan kinerja sebagaimana dimaksud dalam ayat (1) adalah sebagaimana tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Kepala ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7229, '(1) Tunjangan kinerja dibayarkan kepada PNS di Lingkungan Badan Nasional Penanggulangan Bencana setiap bulan.
2014, No.1831 4
(2) Besar tunjangan kinerja sebagaimana dimaksud dalam ayat (1) adalah sebagaimana tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari Peraturan Kepala ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7230, 'perka-17-2014', 6, 'pasal', 'Pasal 3', 'BAB II TUNJANGAN KINERJA, KELAS JABATAN, BESARNYA TUNJANGAN KINERJA, DAN PAJAK PENGHASILAN ATAS TUNJANGAN KINERJA', 4, '(1) Kepada PNS di Lingkungan Badan Nasional Penanggulangan Bencana selain penghasilan yang berhak diterima menurut peraturan perundang-undangan, diberikan Tunjangan Kinerja setiap bulan.
(2) Besarnya Tunjangan Kinerja sebagaimana dimaksud pada ayat (1) didasarkan pada kelas jabatan.
(3) Besarnya Tunjangan Kinerja untuk Calon Pegawai Negeri Sipil adalah 80% (delapan puluh perseratus) dari kelas jabatan fungsional umum di unit kerjanya, yang melaksanakan tugas dan pekerjaan yang sejenis.
(4) Kelas jabatan dan besarnya Tunjangan Kinerja sebagaimana dimaksud pada ayat (2) adalah sebagaimana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Kepala Badan Nasional Penanggulangan Bencana ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7230, '(1) Kepada PNS di Lingkungan Badan Nasional Penanggulangan Bencana selain penghasilan yang berhak diterima menurut peraturan perundang-undangan, diberikan Tunjangan Kinerja setiap bulan.
(2) Besarnya Tunjangan Kinerja sebagaimana dimaksud pada ayat (1) didasarkan pada kelas jabatan.
(3) Besarnya Tunjangan Kinerja untuk Calon Pegawai Negeri Sipil adalah 80% (delapan puluh perseratus) dari kelas jabatan fungsional umum di unit kerjanya, yang melaksanakan tugas dan pekerjaan yang sejenis.
(4) Kelas jabatan dan besarnya Tunjangan Kinerja sebagaimana dimaksud pada ayat (2) adalah sebagaimana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Kepala Badan Nasional Penanggulangan Bencana ini.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7231, 'perka-17-2014', 7, 'pasal', 'Pasal 4', 'BAB II TUNJANGAN KINERJA, KELAS JABATAN, BESARNYA TUNJANGAN KINERJA, DAN PAJAK PENGHASILAN ATAS TUNJANGAN KINERJA', 4, 'Tunjangan Kinerja sebagaimana dimaksud dalam Pasal 2 diberikan terhitung mulai tanggal 1 Juli 2014, sesuai peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7231, 'Tunjangan Kinerja sebagaimana dimaksud dalam Pasal 2 diberikan terhitung mulai tanggal 1 Juli 2014, sesuai peraturan perundang-undangan.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7232, 'perka-17-2014', 8, 'pasal', 'Pasal 5', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 4, 'Pajak penghasilan atas Tunjangan Kinerja sebagaimana dimaksud dalam Pasal 3 dibebankan kepada Anggaran Pendapatan dan Belanja Negara pada tahun anggaran yang berjalan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7232, 'Pajak penghasilan atas Tunjangan Kinerja sebagaimana dimaksud dalam Pasal 3 dibebankan kepada Anggaran Pendapatan dan Belanja Negara pada tahun anggaran yang berjalan.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7233, 'perka-17-2014', 9, 'pasal', 'Pasal 6', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 4, 'Tunjangan Kinerja sebagaimana dimaksud dalam Pasal 3 tidak diberikan kepada:
a. PNS yang dinyatakan tidak melaksanakan tugas/jabatan/pekerjaan tertentu pada Badan Nasional Penanggulangan Bencana.
b. PNS yang dipekerjakan atau diperbantukan di instansi lain.
c. PNS yang diberhentikan sementara dari jabatan negeri karena ditahan oleh pihak yang berwajib sampai dengan putusan pengadilan yang mempunyai kekuatan hukum tetap.
5 2014, No.1831
d. PNS yang diberhentikan dan sedang mengajukan banding administratif kepada Badan Pertimbangan Kepegawaian serta tidak diizinkan masuk bekerja atau mengajukan gugatan kepada Pengadilan Tata Usaha Negara.
e. PNS yang diberhentikan dengan hormat baik atas permintaan sendiri atau tidak atas permintaan sendiri.
f. PNS yang diberikan cuti di luar tanggungan negara atau dalam bebas tugas untuk menjalani masa persiapan pensiun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7233, 'Tunjangan Kinerja sebagaimana dimaksud dalam Pasal 3 tidak diberikan kepada:
a. PNS yang dinyatakan tidak melaksanakan tugas/jabatan/pekerjaan tertentu pada Badan Nasional Penanggulangan Bencana.
b. PNS yang dipekerjakan atau diperbantukan di instansi lain.
c. PNS yang diberhentikan sementara dari jabatan negeri karena ditahan oleh pihak yang berwajib sampai dengan putusan pengadilan yang mempunyai kekuatan hukum tetap.
5 2014, No.1831
d. PNS yang diberhentikan dan sedang mengajukan banding administratif kepada Badan Pertimbangan Kepegawaian serta tidak diizinkan masuk bekerja atau mengajukan gugatan kepada Pengadilan Tata Usaha Negara.
e. PNS yang diberhentikan dengan hormat baik atas permintaan sendiri atau tidak atas permintaan sendiri.
f. PNS yang diberikan cuti di luar tanggungan negara atau dalam bebas tugas untuk menjalani masa persiapan pensiun.', 'Pasal 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7234, 'perka-17-2014', 10, 'pasal', 'Pasal 7', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 5, 'Kepada Pegawai yang mengambil cuti tahunan, dikenakan pemotongan Tunjangan Kinerja sebesar 0 % (nol perseratus).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7234, 'Kepada Pegawai yang mengambil cuti tahunan, dikenakan pemotongan Tunjangan Kinerja sebesar 0 % (nol perseratus).', 'Pasal 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7235, 'perka-17-2014', 11, 'pasal', 'Pasal 8', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 5, '(1) Pembayaran dan pemotongan Tunjangan Kinerja sebagaimana dimaksud dalam Pasal 3 ayat (1) dilakukan dengan memperhitungkan ketidakhadiran dan hukuman disiplin sesuai peraturan perundang-undangan.
(2) Pemotongan Tunjangan Kinerja sebagaimana dimaksud pada ayat (1) dilakukan dalam hal :
a. Pegawai yang terlambat masuk bekerja;
b. Pegawai yang pulang sebelum waktunya;
c. Pegawai yang tidak masuk bekerja;
d. Pegawai yang sedang menjalani cuti sakit :
1. Rawat inap.
2. Rawat jalan.
3. Keguguran.
e. Pegawai yang sedang menjalani cuti bersalin :
1. persalinan pertama sampai ketiga.
2. persalinan keempat dan seterusnya
f. Pegawai yang menjalani cuti alasan penting :
1. Keluarga sakit atau meninggal.
2. Pengurusan ahli waris atau pernikahan pertama.
g. Pegawai yang sedang menjalani cuti besar; dan
h. Pegawai yang dijatuhi hukuman disiplin.
(3) Pemotongan Tunjangan Kinerja sebagaimana dimaksud pada ayat (2) dinyatakan dalam % (perseratus).
2014, No.1831 6
(4) Pemotongan Tunjangan Kinerja PNS sebagaimana dimaksud pada ayat (2), dihitung secara kumulatif dalam 1 (satu) bulan dan paling banyak sebesar 100% (seratus perseratus).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7235, '(1) Pembayaran dan pemotongan Tunjangan Kinerja sebagaimana dimaksud dalam Pasal 3 ayat (1) dilakukan dengan memperhitungkan ketidakhadiran dan hukuman disiplin sesuai peraturan perundang-undangan.
(2) Pemotongan Tunjangan Kinerja sebagaimana dimaksud pada ayat (1) dilakukan dalam hal :
a. Pegawai yang terlambat masuk bekerja;
b. Pegawai yang pulang sebelum waktunya;
c. Pegawai yang tidak masuk bekerja;
d. Pegawai yang sedang menjalani cuti sakit :
1. Rawat inap.
2. Rawat jalan.
3. Keguguran.
e. Pegawai yang sedang menjalani cuti bersalin :
1. persalinan pertama sampai ketiga.
2. persalinan keempat dan seterusnya
f. Pegawai yang menjalani cuti alasan penting :
1. Keluarga sakit atau meninggal.
2. Pengurusan ahli waris atau pernikahan pertama.
g. Pegawai yang sedang menjalani cuti besar; dan
h. Pegawai yang dijatuhi hukuman disiplin.
(3) Pemotongan Tunjangan Kinerja sebagaimana dimaksud pada ayat (2) dinyatakan dalam % (perseratus).
2014, No.1831 6
(4) Pemotongan Tunjangan Kinerja PNS sebagaimana dimaksud pada ayat (2), dihitung secara kumulatif dalam 1 (satu) bulan dan paling banyak sebesar 100% (seratus perseratus).', 'Pasal 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7236, 'perka-17-2014', 12, 'pasal', 'Pasal 9', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 6, '(1) PNS yang terlambat masuk bekerja atau pulang sebelum waktunya sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf a dan huruf b dikenakan pemotongan Tunjangan Kinerja sebagaimana tercantum dalam Lampiran II dan III Peraturan ini.
(2) PNS yang tidak masuk bekerja sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf c dikenakan pemotongan Tunjangan Kinerja sebagai berikut:
a. tidak masuk kerja tanpa keterangan dikenakan pemotongan sebesar 4% (empat perseratus) untuk tiap 1 (satu) hari tidak masuk bekerja; dan
b. tidak masuk kerja dengan keterangan yang sah dan bukan kedinasan dikenakan pemotongan sebesar 2% (dua perseratus) untuk tiap 1 (satu) hari tidak masuk bekerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7236, '(1) PNS yang terlambat masuk bekerja atau pulang sebelum waktunya sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf a dan huruf b dikenakan pemotongan Tunjangan Kinerja sebagaimana tercantum dalam Lampiran II dan III Peraturan ini.
(2) PNS yang tidak masuk bekerja sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf c dikenakan pemotongan Tunjangan Kinerja sebagai berikut:
a. tidak masuk kerja tanpa keterangan dikenakan pemotongan sebesar 4% (empat perseratus) untuk tiap 1 (satu) hari tidak masuk bekerja; dan
b. tidak masuk kerja dengan keterangan yang sah dan bukan kedinasan dikenakan pemotongan sebesar 2% (dua perseratus) untuk tiap 1 (satu) hari tidak masuk bekerja.', 'Pasal 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7237, 'perka-17-2014', 13, 'pasal', 'Pasal 10', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 6, '(1) PNS yang melaksanakan cuti sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf d dikenakan pemotongan Tunjangan Kinerja sebagai berikut:
a. cuti sakit yang dibuktikan dengan surat keterangan dokter, dikenakan pemotongan sebesar 2% (dua perseratus) untuk tiap 1 (satu) hari tidak masuk bekerja;
b. pegawai yang menjalani rawat inap yang dibuktikan dengan surat keterangan rawat inap untuk paling lama 20 (dua puluh) hari kerja, diberlakukan pemotongan Tunjangan Kinerja sebesar 0% (nol perseratus) dan untuk hari berikutnya dikenakan pemotongan Tunjangan Kinerja sebesar 2% (dua perseratus) per hari kerja;
c. pegawai yang menjalani rawat jalan setelah selesai menjalani rawat inap yang dibuktikan dengan surat keterangan dari dokter, diberlakukan pemotongan Tunjangan Kinerja sebesar 2% (dua perseratus) per hari kerja;
d. pegawai wanita yang mengalami gugur kandungan namun tidak menjalani rawat inap yang dibuktikan dengan surat keterangan dokter untuk paling lama 3 (tiga) hari kerja, dikenakan pemotongan Tunjangan Kinerja sebesar 0% (nol perseratus) dan untuk hari berikutnya dikenakan pemotongan Tunjangan Kinerja sebesar 2% (dua perseratus) per hari kerja.
7 2014, No.1831
(2) PNS yang melaksanakan cuti sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf e dikenakan pemotongan Tunjangan Kinerja sebagai berikut:
a. kepada pegawai yang sedang menjalani cuti bersalin untuk melaksanakan persalinan pertama sampai dengan ketiga sejak diangkat sebagai Calon Pegawai Negeri Sipil, dikenakan pemotongan Tunjangan Kinerja sebesar 0% (nol perseratus) selama 5 (lima) hari kerja pertama dan untuk hari berikutnya dikenakan pemotongan Tunjangan Kinerja sebesar 1,5% (satu koma lima perseratus) per hari kerja; dan
b. kepada pegawai yang melaksanakan persalinan yang keempat dan seterusnya sejak diangkat sebagai Calon Pegawai Negeri Sipil, dikenakan pemotongan Tunjangan Kinerja sebagaimana dimaksud dalam Pasal 6 huruf f.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7237, '(1) PNS yang melaksanakan cuti sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf d dikenakan pemotongan Tunjangan Kinerja sebagai berikut:
a. cuti sakit yang dibuktikan dengan surat keterangan dokter, dikenakan pemotongan sebesar 2% (dua perseratus) untuk tiap 1 (satu) hari tidak masuk bekerja;
b. pegawai yang menjalani rawat inap yang dibuktikan dengan surat keterangan rawat inap untuk paling lama 20 (dua puluh) hari kerja, diberlakukan pemotongan Tunjangan Kinerja sebesar 0% (nol perseratus) dan untuk hari berikutnya dikenakan pemotongan Tunjangan Kinerja sebesar 2% (dua perseratus) per hari kerja;
c. pegawai yang menjalani rawat jalan setelah selesai menjalani rawat inap yang dibuktikan dengan surat keterangan dari dokter, diberlakukan pemotongan Tunjangan Kinerja sebesar 2% (dua perseratus) per hari kerja;
d. pegawai wanita yang mengalami gugur kandungan namun tidak menjalani rawat inap yang dibuktikan dengan surat keterangan dokter untuk paling lama 3 (tiga) hari kerja, dikenakan pemotongan Tunjangan Kinerja sebesar 0% (nol perseratus) dan untuk hari berikutnya dikenakan pemotongan Tunjangan Kinerja sebesar 2% (dua perseratus) per hari kerja.
7 2014, No.1831
(2) PNS yang melaksanakan cuti sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf e dikenakan pemotongan Tunjangan Kinerja sebagai berikut:
a. kepada pegawai yang sedang menjalani cuti bersalin untuk melaksanakan persalinan pertama sampai dengan ketiga sejak diangkat sebagai Calon Pegawai Negeri Sipil, dikenakan pemotongan Tunjangan Kinerja sebesar 0% (nol perseratus) selama 5 (lima) hari kerja pertama dan untuk hari berikutnya dikenakan pemotongan Tunjangan Kinerja sebesar 1,5% (satu koma lima perseratus) per hari kerja; dan
b. kepada pegawai yang melaksanakan persalinan yang keempat dan seterusnya sejak diangkat sebagai Calon Pegawai Negeri Sipil, dikenakan pemotongan Tunjangan Kinerja sebagaimana dimaksud dalam Pasal 6 huruf f.', 'Pasal 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7238, 'perka-17-2014', 14, 'pasal', 'Pasal 11', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 7, 'PNS yang melaksanakan cuti sebagaimana dimaksud dalam Pasal 8 ayat
(2) huruf f dikenakan pemotongan Tunjangan Kinerja dengan ketentuan sebagai berikut :
a. cuti karena alasan penting karena orang tua/mertua, istri/suami, anak/menantu, atau saudara kandung sakit keras atau meninggal dunia dikenakan pemotongan pada setiap pengajuan cuti 0% (nol perseratus) untuk paling lama 5 (lima) hari kerja dan untuk hari berikutnya dikenakan pemotongan Tunjangan Kinerja sebesar 2% (dua perseratus) per hari kerja; dan
b. cuti karena alasan penting karena melakukan pengurusan hak sebagai ahli waris atau alasan melakukan pernikahan pertama diberlakukan pemotongan 0% (nol perseratus) untuk paling lama 3 (tiga) hari kerja pada setiap pengajuan cuti dan untuk hari berikutnya dikenakan pemotongan Tunjangan Kinerja sebesar 2% (dua perseratus) per hari kerja.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7238, 'PNS yang melaksanakan cuti sebagaimana dimaksud dalam Pasal 8 ayat
(2) huruf f dikenakan pemotongan Tunjangan Kinerja dengan ketentuan sebagai berikut :
a. cuti karena alasan penting karena orang tua/mertua, istri/suami, anak/menantu, atau saudara kandung sakit keras atau meninggal dunia dikenakan pemotongan pada setiap pengajuan cuti 0% (nol perseratus) untuk paling lama 5 (lima) hari kerja dan untuk hari berikutnya dikenakan pemotongan Tunjangan Kinerja sebesar 2% (dua perseratus) per hari kerja; dan
b. cuti karena alasan penting karena melakukan pengurusan hak sebagai ahli waris atau alasan melakukan pernikahan pertama diberlakukan pemotongan 0% (nol perseratus) untuk paling lama 3 (tiga) hari kerja pada setiap pengajuan cuti dan untuk hari berikutnya dikenakan pemotongan Tunjangan Kinerja sebesar 2% (dua perseratus) per hari kerja.', 'Pasal 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7239, 'perka-17-2014', 15, 'pasal', 'Pasal 12', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 7, 'PNS yag melaksanakan cuti sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf g dikenakan pemotongan Tunjangan Kinerja sebesar :
a. bulan pertama sebesar 50% (lima puluh perseratus);
b. bulan kedua sebesar 70% (tujuh puluh perseratus); dan
c. Bulan ketiga sebesar 90% (sembilan puluh perseratus).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7239, 'PNS yag melaksanakan cuti sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf g dikenakan pemotongan Tunjangan Kinerja sebesar :
a. bulan pertama sebesar 50% (lima puluh perseratus);
b. bulan kedua sebesar 70% (tujuh puluh perseratus); dan
c. Bulan ketiga sebesar 90% (sembilan puluh perseratus).', 'Pasal 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7240, 'perka-17-2014', 16, 'pasal', 'Pasal 13', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 7, 'PNS yang dijatuhi hukuman disiplin sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf h dikenakan pemotongan Tunjangan Kinerja sebagai berikut:
2014, No.1831 8
a. PNS yang dijatuhi hukuman disiplin tingkat ringan berupa:
1. teguran lisan, dikenakan pemotongan sebesar 15% (lima belas perseratus) selama 1 (satu) bulan;
2. teguran tertulis, dikenakan pemotongan sebesar 15% (lima belas perseratus) selama 2 (dua) bulan; dan
3. pernyataan tidak puas secara tertulis, dikenakan pemotongan sebesar 15% (lima belas perseratus) selama 3 (tiga) bulan.
b. PNS yang dijatuhi hukuman disiplin tingkat sedang berupa:
1. penundaan kenaikan gaji berkala selama 1 (satu) tahun dikenakan pemotongan sebesar 50% (lima puluh perseratus) selama 1 (satu) bulan;
2. penundaan kenaikan pangkat selama 1 (satu) tahun dikenakan pemotongan sebesar 50% (lima puluh perseratus) selama 2 (dua) bulan; dan
3. penurunan pangkat setingkat lebih rendah selama 1 (satu) tahun dikenakan pemotongan sebesar 50% (lima puluh perseratus) selama 3 (tiga) bulan.
c. PNS yang dijatuhi hukuman disiplin tingkat berat berupa:
1. Penurunan pangkat setingkat lebih rendah selama 3 (tiga) tahun dikenakan pemotongan sebesar 90% (sembilan puluh perseratus) selama 1 (satu) bulan;
2. pemindahan dalam rangka penurunan jabatan setingkat lebih rendah dikenakan pemotongan sebesar 90% (sembilan puluh perseratus) selama 2 (dua) bulan; dan
3. pembebasan dari jabatan dikenakan pemotongan sebesar 90% (sembilan puluh perseratus) selama 3 (tiga) bulan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7240, 'PNS yang dijatuhi hukuman disiplin sebagaimana dimaksud dalam Pasal 8 ayat (2) huruf h dikenakan pemotongan Tunjangan Kinerja sebagai berikut:
2014, No.1831 8
a. PNS yang dijatuhi hukuman disiplin tingkat ringan berupa:
1. teguran lisan, dikenakan pemotongan sebesar 15% (lima belas perseratus) selama 1 (satu) bulan;
2. teguran tertulis, dikenakan pemotongan sebesar 15% (lima belas perseratus) selama 2 (dua) bulan; dan
3. pernyataan tidak puas secara tertulis, dikenakan pemotongan sebesar 15% (lima belas perseratus) selama 3 (tiga) bulan.
b. PNS yang dijatuhi hukuman disiplin tingkat sedang berupa:
1. penundaan kenaikan gaji berkala selama 1 (satu) tahun dikenakan pemotongan sebesar 50% (lima puluh perseratus) selama 1 (satu) bulan;
2. penundaan kenaikan pangkat selama 1 (satu) tahun dikenakan pemotongan sebesar 50% (lima puluh perseratus) selama 2 (dua) bulan; dan
3. penurunan pangkat setingkat lebih rendah selama 1 (satu) tahun dikenakan pemotongan sebesar 50% (lima puluh perseratus) selama 3 (tiga) bulan.
c. PNS yang dijatuhi hukuman disiplin tingkat berat berupa:
1. Penurunan pangkat setingkat lebih rendah selama 3 (tiga) tahun dikenakan pemotongan sebesar 90% (sembilan puluh perseratus) selama 1 (satu) bulan;
2. pemindahan dalam rangka penurunan jabatan setingkat lebih rendah dikenakan pemotongan sebesar 90% (sembilan puluh perseratus) selama 2 (dua) bulan; dan
3. pembebasan dari jabatan dikenakan pemotongan sebesar 90% (sembilan puluh perseratus) selama 3 (tiga) bulan.', 'Pasal 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7241, 'perka-17-2014', 17, 'pasal', 'Pasal 14', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 8, '(1) PNS yang dijatuhi hukuman disiplin berupa pemberhentian dengan hormat tidak atas permintaan sendiri sebagai Pegawai Negeri Sipil, apabila pegawai yang bersangkutan mengajukan banding administratif ke Badan Pertimbangan Kepegawaian, dan putusan hukuman disiplinnya meringankan PNS, maka Tunjangan Kinerja yang bersangkutan untuk bulan berikutnya dilakukan pemotongan sebagaimana dimaksud dalam Pasal 13.
(2) PNS yang dijatuhi hukuman disiplin berupa pemberhentian dengan hormat tidak atas permintaan sendiri sebagai Pegawai Negeri Sipil, apabila pegawai yang bersangkutan mengajukan banding administratif ke Badan Pertimbangan Kepegawaian dan putusan hukuman disiplinnya dibatalkan, maka tunjangan kinerjanya dibayarkan kembali mulai bulan berikutnya.
9 2014, No.1831
(3) Pemotongan atau pembayaran kembali tunjangan kinerja sebagaimana dimaksud pada ayat (1) dan ayat (2) terhitung bulan berikutnya PNS yang bersangkutan dinyatakan telah melaksanakan tugas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7241, '(1) PNS yang dijatuhi hukuman disiplin berupa pemberhentian dengan hormat tidak atas permintaan sendiri sebagai Pegawai Negeri Sipil, apabila pegawai yang bersangkutan mengajukan banding administratif ke Badan Pertimbangan Kepegawaian, dan putusan hukuman disiplinnya meringankan PNS, maka Tunjangan Kinerja yang bersangkutan untuk bulan berikutnya dilakukan pemotongan sebagaimana dimaksud dalam Pasal 13.
(2) PNS yang dijatuhi hukuman disiplin berupa pemberhentian dengan hormat tidak atas permintaan sendiri sebagai Pegawai Negeri Sipil, apabila pegawai yang bersangkutan mengajukan banding administratif ke Badan Pertimbangan Kepegawaian dan putusan hukuman disiplinnya dibatalkan, maka tunjangan kinerjanya dibayarkan kembali mulai bulan berikutnya.
9 2014, No.1831
(3) Pemotongan atau pembayaran kembali tunjangan kinerja sebagaimana dimaksud pada ayat (1) dan ayat (2) terhitung bulan berikutnya PNS yang bersangkutan dinyatakan telah melaksanakan tugas.', 'Pasal 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7242, 'perka-17-2014', 18, 'pasal', 'Pasal 15', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 9, '(1) Pemotongan Tunjangan Kinerja sebagaimana dimaksud dalam Pasal 13, diberlakukan terhitung mulai bulan berikutnya sejak keputusan penjatuhan hukuman disiplin dinyatakan berlaku.
(2) Dalam hal hukuman disiplin sebagaimana dimaksud dalam Pasal 13 huruf b diajukan keberatan dan hukuman disiplinnya diubah, maka tunjangan kinerja yang bersangkutan dilakukan pemotongan sesuai dengan jenis hukuman disiplin yang ditetapkan.
(3) Pemotongan atau pembayaran kembali tunjangan kinerja sebagaimana dimaksud pada ayat (2) terhitung mulai bulan berikutnya sejak keputusan atas keberatan ditetapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7242, '(1) Pemotongan Tunjangan Kinerja sebagaimana dimaksud dalam Pasal 13, diberlakukan terhitung mulai bulan berikutnya sejak keputusan penjatuhan hukuman disiplin dinyatakan berlaku.
(2) Dalam hal hukuman disiplin sebagaimana dimaksud dalam Pasal 13 huruf b diajukan keberatan dan hukuman disiplinnya diubah, maka tunjangan kinerja yang bersangkutan dilakukan pemotongan sesuai dengan jenis hukuman disiplin yang ditetapkan.
(3) Pemotongan atau pembayaran kembali tunjangan kinerja sebagaimana dimaksud pada ayat (2) terhitung mulai bulan berikutnya sejak keputusan atas keberatan ditetapkan.', 'Pasal 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7243, 'perka-17-2014', 19, 'pasal', 'Pasal 16', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 9, '(1) Dalam hal PNS dijatuhi hukuman disiplin dan kemudian dijatuhi hukuman disiplin yang jenisnya sama, maka terhadap PNS yang bersangkutan diberlakukan pemotongan tunjangan kinerja PNS berdasarkan hukuman disiplin yang terakhir.
(2) Dalam hal PNS dijatuhi hukuman disiplin dan kemudian dijatuhi hukuman disiplin yang jenisnya lebih ringan atau lebih berat, maka terhadap PNS yang bersangkutan diberlakukan pemotongan tunjangan kinerja sebagai berikut:
a. dipotong sesuai jenis hukuman disiplin yang pertama; dan
b. dipotong kembali sesuai jenis hukuman disiplin yang berikutnya setelah selesainya pemotongan sebagaimana dimaksud pada huruf a.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7243, '(1) Dalam hal PNS dijatuhi hukuman disiplin dan kemudian dijatuhi hukuman disiplin yang jenisnya sama, maka terhadap PNS yang bersangkutan diberlakukan pemotongan tunjangan kinerja PNS berdasarkan hukuman disiplin yang terakhir.
(2) Dalam hal PNS dijatuhi hukuman disiplin dan kemudian dijatuhi hukuman disiplin yang jenisnya lebih ringan atau lebih berat, maka terhadap PNS yang bersangkutan diberlakukan pemotongan tunjangan kinerja sebagai berikut:
a. dipotong sesuai jenis hukuman disiplin yang pertama; dan
b. dipotong kembali sesuai jenis hukuman disiplin yang berikutnya setelah selesainya pemotongan sebagaimana dimaksud pada huruf a.', 'Pasal 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7244, 'perka-17-2014', 20, 'pasal', 'Pasal 17', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 9, '(1) PNS yang melaksanakan tugas kedinasan di luar kantor yang menyebabkan tidak mengisi daftar hadir secara manual dan/atau elektronik pada jam masuk dan/atau jam pulang, tidak dilakukan pemotongan Tunjangan Kinerja.
(2) Tugas kedinasan di luar kantor sebagaimana dimaksud pada ayat (1) harus dinyatakan dengan surat tugas kedinasan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7244, '(1) PNS yang melaksanakan tugas kedinasan di luar kantor yang menyebabkan tidak mengisi daftar hadir secara manual dan/atau elektronik pada jam masuk dan/atau jam pulang, tidak dilakukan pemotongan Tunjangan Kinerja.
(2) Tugas kedinasan di luar kantor sebagaimana dimaksud pada ayat (1) harus dinyatakan dengan surat tugas kedinasan.', 'Pasal 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7245, 'perka-17-2014', 21, 'pasal', 'Pasal 18', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 9, 'PNS yang dibebaskan sementara dari tugas jabatan/pekerjaannya karena melaksanakan tugas belajar tidak diberikan Tunjangan Kinerja selama PNS yang bersangkutan melaksanakan tugas belajar.
2014, No.1831 10');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7245, 'PNS yang dibebaskan sementara dari tugas jabatan/pekerjaannya karena melaksanakan tugas belajar tidak diberikan Tunjangan Kinerja selama PNS yang bersangkutan melaksanakan tugas belajar.
2014, No.1831 10', 'Pasal 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7246, 'perka-17-2014', 22, 'pasal', 'Pasal 19', 'BAB III PEMBERIAN, PEMOTONGAN, DAN PENGHENTIAN PEMBAYARAN TUNJANGAN KINERJA PEGAWAI', 10, '(1) PNS yang dikenakan pemberhentian sementara dari jabatan karena dilakukan penahanan oleh pihak yang berwajib, tidak diberikan Tunjangan Kinerja selama masa pemberhentian sementara dari jabatan.
(2) PNS yang dikenakan pemberhentian sementara dari jabatan karena dilakukan penahanan oleh pihak yang berwajib, apabila berdasarkan putusan pengadilan yang telah mempunyai kekuatan hukum yang tetap dinyatakan tidak bersalah, maka Tunjangan Kinerja dibayarkan kembali terhitung mulai bulan berikutnya PNS yang bersangkutan dinyatakan telah melaksanakan tugas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7246, '(1) PNS yang dikenakan pemberhentian sementara dari jabatan karena dilakukan penahanan oleh pihak yang berwajib, tidak diberikan Tunjangan Kinerja selama masa pemberhentian sementara dari jabatan.
(2) PNS yang dikenakan pemberhentian sementara dari jabatan karena dilakukan penahanan oleh pihak yang berwajib, apabila berdasarkan putusan pengadilan yang telah mempunyai kekuatan hukum yang tetap dinyatakan tidak bersalah, maka Tunjangan Kinerja dibayarkan kembali terhitung mulai bulan berikutnya PNS yang bersangkutan dinyatakan telah melaksanakan tugas.', 'Pasal 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7247, 'perka-17-2014', 23, 'pasal', 'Pasal 20', 'BAB IV KETENTUAN PENUTUP', 10, 'Pemberian, pemotongan, dan penghentian pembayaran Tunjangan Kinerja dilaksanakan berdasarkan Peraturan Presiden Nomor 112 Tahun 2014 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7247, 'Pemberian, pemotongan, dan penghentian pembayaran Tunjangan Kinerja dilaksanakan berdasarkan Peraturan Presiden Nomor 112 Tahun 2014 tentang Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7248, 'perka-17-2014', 24, 'pasal', 'Pasal 21', 'BAB IV KETENTUAN PENUTUP', 10, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal diundangkan.
11 2014, No.1831 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7248, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal diundangkan.
11 2014, No.1831 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 21', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7249, 'perka-17-2014', 25, 'lain', 'Penutup', NULL, 11, 'Ditetapkan di Jakarta pada tanggal 7 Nopember 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 28 Nopember 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY 2014, No.1831 12');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7249, 'Ditetapkan di Jakarta pada tanggal 7 Nopember 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 28 Nopember 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY 2014, No.1831 12', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2014 tentang Tata Cara Pemberian Tunjangan Kinerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
