INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7253, 'perka-18-2009', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka pelaksanaan ketentuan Pasal 18 ayat (3) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, perlu dibuat standarisasi logistik penanggulangan bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Standarisasi Logistik Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7253, 'a. bahwa dalam rangka pelaksanaan ketentuan Pasal 18 ayat (3) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, perlu dibuat standarisasi logistik penanggulangan bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Standarisasi Logistik Penanggulangan Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7254, 'perka-18-2009', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 2014, No.1090 2 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nornor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Republik Indonesia Nomor 4830);
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Keputusan Presiden Nomor 29/M Tahun 2008 tanggal 23 April 2008 tentang Pengangkatan Kepala Badan Nasional PenanggulanganBencana;');
