INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7260, 'perka-18-2009', 8, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'A. Latar Belakang ........................................................... 1 B. Maksud dan Tujuan ................................................... 2 C. Ruang Lingkup........................................................... 2 D. Pengertian .................................................................. 2 E. Landasan Hukum ...................................................... 3 BAB II KATEGORI, PAKET DAN STANDAR LOGISTIK PENANGGULANGAN BENCANA A. Kategori Logistik......................................................... 5 B. Paket Logistik ............................................................. 5 C. Standar Logistik Penanggulangan Bencana ................ 6 D. Standar Logistik Bantuan Dari Luar Negri .................. 8 BAB III PENGENDALIAN DAN PENGAWASAN A. Pengendalian.............................................................. 9 B. Pengawasan ............................................................... 9 C. Pertanggungjawaban .................................................. 9 D. Penghapusan ............................................................. 9 BAB IV PENUTUP ........................................................................ 10 2014, No.1090 6');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7260, 'A. Latar Belakang ........................................................... 1 B. Maksud dan Tujuan ................................................... 2 C. Ruang Lingkup........................................................... 2 D. Pengertian .................................................................. 2 E. Landasan Hukum ...................................................... 3 BAB II KATEGORI, PAKET DAN STANDAR LOGISTIK PENANGGULANGAN BENCANA A. Kategori Logistik......................................................... 5 B. Paket Logistik ............................................................. 5 C. Standar Logistik Penanggulangan Bencana ................ 6 D. Standar Logistik Bantuan Dari Luar Negri .................. 8 BAB III PENGENDALIAN DAN PENGAWASAN A. Pengendalian.............................................................. 9 B. Pengawasan ............................................................... 9 C. Pertanggungjawaban .................................................. 9 D. Penghapusan ............................................................. 9 BAB IV PENUTUP ........................................................................ 10 2014, No.1090 6', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7261, 'perka-18-2009', 9, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 18 TAHUN 2009 TENTANG PEDOMAN STANDARISASI LOGISTIK PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan daerah rawan bencana dan bencana dapat terjadi disebabkan oleh alam maupun ulah manusia. Hal ini terbukti telah terjadi berbagai bencana seperti gempa bumi, tsunami, banjir dan banjir bandang, tanah longsor, letusan gunung api, kebakaran, kebakaran hutan dan lahan, angin puting beliung, kegagalan teknologi dan konflik sosial di beberapa daerah. Akibat dari bencanabencana dimaksud berdampak pada terjadinya pengungsian yang disebabkan oleh rumah tinggalnya rusak atau ancaman lainya dan memaksa mereka mencari tempat lain yang lebih aman.
Dengan kondisi tersebut perlu upaya mempercepat untuk dilakukan berbagai langkah Penanggulangan antara lain pertolongan, penyelamatan, pemberian hunian sementara, pemenuhan kebutuhan dasar, pelayanan kesehatan dan kebutuhan air bersih serta sanitasi. Adanya berbagai tuntutan tersebut maka muncul yang disebut kebutuhan logistik untuk korban bencana.
Peningkatan kesiapsiagaan logistik pra bencana khususnya pada saat terjadi potensi bencana akan memperlancar Penanggulangan tanggap darurat, sebaliknya keterbatasan logistik pada saat tanggap darurat akan mempersulit pemberian bantuan khususnya pada pemberian pelayanan kebutuhan dasar korban bencana, baik kebutuhan pangan, sandang dan logistik lainnya, sebagaimana diutarakan diatas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7261, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 18 TAHUN 2009 TENTANG PEDOMAN STANDARISASI LOGISTIK PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan daerah rawan bencana dan bencana dapat terjadi disebabkan oleh alam maupun ulah manusia. Hal ini terbukti telah terjadi berbagai bencana seperti gempa bumi, tsunami, banjir dan banjir bandang, tanah longsor, letusan gunung api, kebakaran, kebakaran hutan dan lahan, angin puting beliung, kegagalan teknologi dan konflik sosial di beberapa daerah. Akibat dari bencanabencana dimaksud berdampak pada terjadinya pengungsian yang disebabkan oleh rumah tinggalnya rusak atau ancaman lainya dan memaksa mereka mencari tempat lain yang lebih aman.
Dengan kondisi tersebut perlu upaya mempercepat untuk dilakukan berbagai langkah Penanggulangan antara lain pertolongan, penyelamatan, pemberian hunian sementara, pemenuhan kebutuhan dasar, pelayanan kesehatan dan kebutuhan air bersih serta sanitasi. Adanya berbagai tuntutan tersebut maka muncul yang disebut kebutuhan logistik untuk korban bencana.
Peningkatan kesiapsiagaan logistik pra bencana khususnya pada saat terjadi potensi bencana akan memperlancar Penanggulangan tanggap darurat, sebaliknya keterbatasan logistik pada saat tanggap darurat akan mempersulit pemberian bantuan khususnya pada pemberian pelayanan kebutuhan dasar korban bencana, baik kebutuhan pangan, sandang dan logistik lainnya, sebagaimana diutarakan diatas.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7262, 'perka-18-2009', 10, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'Pedoman management logistik yang meliputi pengadaan, penyimpanan, penyaluran logistik diarahkan untuk mengoptimalkan ketersediaan/kesiapan logistik yang ada pada masing-masing instansi/lembaga terkait dalam jejaring kerja BNPB dan BPBD. Kepala BNPB dan Kepala BPBD pada saat terjadi bencana sesuai dengan tingkatannya berkewajiban mengerahkan logistik ke lokasi bencana yang disesuaikan dengan kebutuhan yang mendesak, selanjutnya instansi/lembaga terkait memobilisasi sumber daya logistik yang menjadi kewenangannya untuk mendukung penanggulangan bencana pada saat tanggap darurat.
Dalam rangka menjamin kelancaran pengerahan sumber daya logistik ke lokasi bencana yang sesuai dengan kualitas dan kuantitasnya dengan cepat dan tepat, maka perlu dibuat pedoman standarisasi logistik yang meliputi 7 2014, No.1090 kategori logistik, paket logistik dan standar logistik penanggulangan bencana, agar pengerahan sumber daya khusunya logistik dapat berjalan lancar, efektif dan efisien.
B. Maksud dan Tujuan
1. Maksud Pedoman ini dimaksudkan untuk memberikan panduan bagi petugas dan pemangku kepentingan penanggulangan bencana dalam melakukan standarisasi sumber daya logistik agar bantuan logistik penanggulangan bencana dilaksanakan dengan tepat sasaran, tepat waktu, tepat jumlah, tepat kualitas, tepat guna dan tepat kebutuhan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7262, 'Pedoman management logistik yang meliputi pengadaan, penyimpanan, penyaluran logistik diarahkan untuk mengoptimalkan ketersediaan/kesiapan logistik yang ada pada masing-masing instansi/lembaga terkait dalam jejaring kerja BNPB dan BPBD. Kepala BNPB dan Kepala BPBD pada saat terjadi bencana sesuai dengan tingkatannya berkewajiban mengerahkan logistik ke lokasi bencana yang disesuaikan dengan kebutuhan yang mendesak, selanjutnya instansi/lembaga terkait memobilisasi sumber daya logistik yang menjadi kewenangannya untuk mendukung penanggulangan bencana pada saat tanggap darurat.
Dalam rangka menjamin kelancaran pengerahan sumber daya logistik ke lokasi bencana yang sesuai dengan kualitas dan kuantitasnya dengan cepat dan tepat, maka perlu dibuat pedoman standarisasi logistik yang meliputi 7 2014, No.1090 kategori logistik, paket logistik dan standar logistik penanggulangan bencana, agar pengerahan sumber daya khusunya logistik dapat berjalan lancar, efektif dan efisien.
B. Maksud dan Tujuan
1. Maksud Pedoman ini dimaksudkan untuk memberikan panduan bagi petugas dan pemangku kepentingan penanggulangan bencana dalam melakukan standarisasi sumber daya logistik agar bantuan logistik penanggulangan bencana dilaksanakan dengan tepat sasaran, tepat waktu, tepat jumlah, tepat kualitas, tepat guna dan tepat kebutuhan.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7263, 'perka-18-2009', 11, 'lampiran', 'Lampiran hal. 7', NULL, 7, '2. Tujuan Tujuan dari pedoman standarisasi logistik penanggulangan bencana ini antara lain untuk meningkatkan kesiapsiagaan BPBD Daerah Provinsi khususnya kebutuhan logistik penanggulangan bencana dan memperlancar pengerahan logistik pada saat terjadi bencana untuk bantuan kepada korban bencana.
C. Ruang Lingkup Pedoman standarisasi logistik ini meliputi beberapa aspek kategori jenis logistik seperti pangan, sandang dan logistik lain. Selain itu juga aspek standar logistik sesuai dengan tahap kejadian bencana, seperti tahap kesiapsiagaan, tahap tanggap darurat dan tahap rehabilitasi dan rekonstruksi.
Pedoman ini disusun dengan sistematika sebagai berikut:
I. Pendahuluan
II. Kategori dan Standar Logistik Penanggulangan Bencana A. Kategori Logistik.
B. Paket Logistik.
C. Standar Logistik Penanggulangan Bencana
1. Tahap Kesiapsiagaan.
2. Tahap tanggap Darurat
3. Tahap Rehabilitasi dan Rekonstruksi D. Standar Logistik Bantuan Luar Negeri
III. Pengendalian dan Pengawasan
IV. Penutup D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang 2014, No.1090 8 disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7263, '2. Tujuan Tujuan dari pedoman standarisasi logistik penanggulangan bencana ini antara lain untuk meningkatkan kesiapsiagaan BPBD Daerah Provinsi khususnya kebutuhan logistik penanggulangan bencana dan memperlancar pengerahan logistik pada saat terjadi bencana untuk bantuan kepada korban bencana.
C. Ruang Lingkup Pedoman standarisasi logistik ini meliputi beberapa aspek kategori jenis logistik seperti pangan, sandang dan logistik lain. Selain itu juga aspek standar logistik sesuai dengan tahap kejadian bencana, seperti tahap kesiapsiagaan, tahap tanggap darurat dan tahap rehabilitasi dan rekonstruksi.
Pedoman ini disusun dengan sistematika sebagai berikut:
I. Pendahuluan
II. Kategori dan Standar Logistik Penanggulangan Bencana A. Kategori Logistik.
B. Paket Logistik.
C. Standar Logistik Penanggulangan Bencana
1. Tahap Kesiapsiagaan.
2. Tahap tanggap Darurat
3. Tahap Rehabilitasi dan Rekonstruksi D. Standar Logistik Bantuan Luar Negeri
III. Pengendalian dan Pengawasan
IV. Penutup D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang 2014, No.1090 8 disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7264, 'perka-18-2009', 12, 'lampiran', 'Lampiran hal. 8', NULL, 8, '2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, serta kegiatan rehabilitasi dan rekonstruksi.
3. Standarisasi adalah suatu ukuran tertentu dalam pelaksanaan pemberian bantuan kepada korban bencana sesuai kejadian bencana yang meliputi pencegahan dan kesiapsiagaan, tanggap darurat, rehabilitasi dan rekonstruksi.
4. Logistik adalah segala sesuatu yang berujud yang dapat digunakan untuk memenuhi suatu kebutuhan dasar manusia yang habis pakai terdiri atas pangan, sandang dan papan atau turunannya. Termasuk dalam kategori logistik adalah barang yang habis pakai atau dikonsumsi, misalnya: sembako (sembilan bahan pokok), obat-obatan, pakaian dan kelengkapannya, air, kantong tidur (sleeping bag), perlengkapan bayi, perlengkapan keluarga (pembalut wanita, odol, sabun mandi, shampo, detergen, handuk).
5. Pangan adalah logistik yang dikonsumsi untuk memenuhi kebutuhan lapar dan dahaga untuk kelangsungan hidup sesuai makanan pokok setempat.
6. Sandang adalah logistik yang digunakan untuk memenuhi kebutuhan dasar melindungi tubuh berupa pakaian dan perlengkapan pribadi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7264, '2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, serta kegiatan rehabilitasi dan rekonstruksi.
3. Standarisasi adalah suatu ukuran tertentu dalam pelaksanaan pemberian bantuan kepada korban bencana sesuai kejadian bencana yang meliputi pencegahan dan kesiapsiagaan, tanggap darurat, rehabilitasi dan rekonstruksi.
4. Logistik adalah segala sesuatu yang berujud yang dapat digunakan untuk memenuhi suatu kebutuhan dasar manusia yang habis pakai terdiri atas pangan, sandang dan papan atau turunannya. Termasuk dalam kategori logistik adalah barang yang habis pakai atau dikonsumsi, misalnya: sembako (sembilan bahan pokok), obat-obatan, pakaian dan kelengkapannya, air, kantong tidur (sleeping bag), perlengkapan bayi, perlengkapan keluarga (pembalut wanita, odol, sabun mandi, shampo, detergen, handuk).
5. Pangan adalah logistik yang dikonsumsi untuk memenuhi kebutuhan lapar dan dahaga untuk kelangsungan hidup sesuai makanan pokok setempat.
6. Sandang adalah logistik yang digunakan untuk memenuhi kebutuhan dasar melindungi tubuh berupa pakaian dan perlengkapan pribadi.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7265, 'perka-18-2009', 13, 'lampiran', 'Lampiran hal. 8', NULL, 8, '7. Bantuan Luar Negeri adalah bantuan/hibah dari negara-negara sahabat Republik Indonesia atau dari Lembaga Internasional dan Lembaga Asing non Pemerintah, masyarakat Internasional termasuk WNI yang tinggal di Luar Negeri, sukarela, tidak mengikat, berupa barang berwujud, untuk membantu meringankan beban korban bencana di Indonesia.
E. Landasan Hukum
1. Undang-undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Peraturan Pemerintah Nomor 25 Tahun 2000 tentang Kewenangan Pemerintah dan Kewenangan Provinsi sebagai Daerah Otonom.
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tantang Penyelenggaraan Penanggulangan Bencana.
4. Peraturan Pemerintah Nomor 22 Tahun 2008, tentang Pendanaan dan Pengelolaan Bantuan Bencana.
5. Peraturan Pemerintah Nomor 23 Tahun 2008, tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana.
9 2014, No.1090
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana
7. Peraturan Menteri Dalam Negeri Nomor 46 tahun 2008 tentang Pedoman Organisasi dan Tata Kerja BPBD.
8. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008 Tentang Pembentukan Badan Penanggulangan Bencana Daerah.
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2008 Tentang Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar.
10. Peraturan Kepala Badan Nasional Nomor 1 Tahun 2008 Tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana.');
