INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7266, 'perka-18-2009', 14, 'lampiran', 'Lampiran hal. 9', NULL, 9, '11. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008 tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana.
12. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 Tentang Pedoman Bantuan Logistik.
2014, No.1090 10 BAB II KATEGORI, PAKET DAN STANDAR LOGISTIK PENANGGULANGAN BENCANA A. Kategori Logistik Kategori bantuan logistik dalam penanggulangan bencana dapat dibedakan menjadi beberapa kategori yaitu :
1. Pangan, yang termasuk dalam kategori ini adalah makanan pokok (beras/sagu/jagung/ubi,dll), lauk-pauk, air bersih, bahan makanan pokok tambahan seperti mi, susu, kopi, teh, perlengkapan makan (food ware) dan sebagainya.
2. Sandang, yang termasuk dalam kategori ini adalah perlengkapan pribadi berupa baju, kaos dan celana anak-anak sampai dewasa laki-laki dan perempuan, sarung, kain batik panjang, handuk, selimut, daster, perangkat lengkap pakaian dalam, seragam sekolah laki-laki dan perempuan (SD dan SMP), sepatu/alas kaki sekolah dan turunannya.
3. Logistik lainnya, termasuk dalam kategori ini adalah, obat dan alat kesehatan habis pakai, tenda gulung, tikar, matras, alat dapur keluarga, kantong tidur (sleeping bag) dan sebagainya.
4. Paket kematian, termasuk dalam kategori ini adalah, kantong mayat, kain kafan dan sebagainya.
B. Paket Logistik Paket Logistik Penanggulangan Bencana adalah pengelompokkan jenis-jenis logistik kedalam satu paket agar memudahkan pemberian bantuan logistik, terdiri atas:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7266, '11. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008 tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana.
12. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 Tentang Pedoman Bantuan Logistik.
2014, No.1090 10 BAB II KATEGORI, PAKET DAN STANDAR LOGISTIK PENANGGULANGAN BENCANA A. Kategori Logistik Kategori bantuan logistik dalam penanggulangan bencana dapat dibedakan menjadi beberapa kategori yaitu :
1. Pangan, yang termasuk dalam kategori ini adalah makanan pokok (beras/sagu/jagung/ubi,dll), lauk-pauk, air bersih, bahan makanan pokok tambahan seperti mi, susu, kopi, teh, perlengkapan makan (food ware) dan sebagainya.
2. Sandang, yang termasuk dalam kategori ini adalah perlengkapan pribadi berupa baju, kaos dan celana anak-anak sampai dewasa laki-laki dan perempuan, sarung, kain batik panjang, handuk, selimut, daster, perangkat lengkap pakaian dalam, seragam sekolah laki-laki dan perempuan (SD dan SMP), sepatu/alas kaki sekolah dan turunannya.
3. Logistik lainnya, termasuk dalam kategori ini adalah, obat dan alat kesehatan habis pakai, tenda gulung, tikar, matras, alat dapur keluarga, kantong tidur (sleeping bag) dan sebagainya.
4. Paket kematian, termasuk dalam kategori ini adalah, kantong mayat, kain kafan dan sebagainya.
B. Paket Logistik Paket Logistik Penanggulangan Bencana adalah pengelompokkan jenis-jenis logistik kedalam satu paket agar memudahkan pemberian bantuan logistik, terdiri atas:', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7267, 'perka-18-2009', 15, 'lampiran', 'Lampiran hal. 10', NULL, 10, '1. Paket Pangan, terdiri atas: Beras 0,4 kg (bahan lain disesuaikan), lauk-pauk, mi instan 3 (tiga) bungkus, kecap 150 ml, Air minum 4 liter, Paket pangan ini untuk 1 (satu) jiwa, untuk 1 (satu) hari, dan dapat disiapkan makanan siap saji.
2. Paket Sandang, terdiri atas:
a. Memiliki satu perangkat lengkap pakaian dengan ukuran yang tepat sesuai jenis kelamin masing-masing, serta alas tidur yang memadai.
b. Perempuan dan anak-anak setidaknya memiliki dua perangkat lengkap pakaian dengan ukuran yang tepat sesuai budaya, iklim dan musim.
c. Anak sekolah setidaknya memiliki 2 stel seragam sekolah lengkap termasuk sepatu/ alas kaki dengan ukuran yang tepat sesuai jenis kelamin dan jenjang sekolah yang diikuti.
d. Setiap orang memiliki pakaian khusus untuk beribadah sesuai agama dan keyakinannya.
11 2014, No.1090
e. Setiap orang memiliki satu pasang alas kaki.
f. Bayi dan anak dibawah usia 2 tahun harus memiliki selimut dengan ukuran (100 X 70) cm.
g. Setiap orang memiliki 250 gram sabun mandi setiap bulan.
h. Setiap orang memiliki 200 gram sabun cuci setiap bulan.
i. Setiap perempuan dan anak-anak gadis yang sudah menstruasi memiliki bahan pembalut.
j. Setiap bayi dan anak-anak dibawah usia 2 tahun memiliki 12 popok cuci sesuai kebiasaan di tempat yang bersangkutan.
k. Setiap orang memiliki sikat gigi dan pasta gigi sesuai kebutuhan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7267, '1. Paket Pangan, terdiri atas: Beras 0,4 kg (bahan lain disesuaikan), lauk-pauk, mi instan 3 (tiga) bungkus, kecap 150 ml, Air minum 4 liter, Paket pangan ini untuk 1 (satu) jiwa, untuk 1 (satu) hari, dan dapat disiapkan makanan siap saji.
2. Paket Sandang, terdiri atas:
a. Memiliki satu perangkat lengkap pakaian dengan ukuran yang tepat sesuai jenis kelamin masing-masing, serta alas tidur yang memadai.
b. Perempuan dan anak-anak setidaknya memiliki dua perangkat lengkap pakaian dengan ukuran yang tepat sesuai budaya, iklim dan musim.
c. Anak sekolah setidaknya memiliki 2 stel seragam sekolah lengkap termasuk sepatu/ alas kaki dengan ukuran yang tepat sesuai jenis kelamin dan jenjang sekolah yang diikuti.
d. Setiap orang memiliki pakaian khusus untuk beribadah sesuai agama dan keyakinannya.
11 2014, No.1090
e. Setiap orang memiliki satu pasang alas kaki.
f. Bayi dan anak dibawah usia 2 tahun harus memiliki selimut dengan ukuran (100 X 70) cm.
g. Setiap orang memiliki 250 gram sabun mandi setiap bulan.
h. Setiap orang memiliki 200 gram sabun cuci setiap bulan.
i. Setiap perempuan dan anak-anak gadis yang sudah menstruasi memiliki bahan pembalut.
j. Setiap bayi dan anak-anak dibawah usia 2 tahun memiliki 12 popok cuci sesuai kebiasaan di tempat yang bersangkutan.
k. Setiap orang memiliki sikat gigi dan pasta gigi sesuai kebutuhan.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7268, 'perka-18-2009', 16, 'lampiran', 'Lampiran hal. 11', NULL, 11, '3. Paket Logistik Lain terdiri atas: Paket obat dan alat kesehatan habis pakai, tenda gulung, tikar dan matras, paket ini untuk satu Kepala Keluarga (empat jiwa)
4. Paket Kematian, terdiri atas: Kain kafan dan kelengkapannya dan kantong mayat, paket ini untuk satu jiwa.
C. Standar Logistik Penanggulangan Bencana
1. Tahap Kesiapsiagaan.
Standar Logistik yang tersedia pada tahap kesiapsiagaan berfungsi sebagai ”buffer stock”. Berdasarkan Provinsi dan jumlah penduduk, maka standar minimal logistik yang tersedia dapat diuraikan sebagai berikut:
a. Standar Umum.
Secara umum setiap wilayah Provinsi disiagakan paket pangan, paket sandang, paket logistik lainnya dan paket kematian. Standar minimal paket pangan yang tersedia adalah 1% dari jumlah penduduk selama 3 (tiga) hari. Paket sandang dan logistik lain untuk 1 (satu) Kepala keluarga.
Khusus untuk paket kematian 1% dari jumlah paket sandang.
b. Standar Khusus.
Secara khusus standar jumlah minimal setiap paket logistik yang tersedia di setiap Provinsi dapat dilihat pada tabel dibawah ini.
2014, No.1090 12 Tabel. 1 Standar minimal paket logistik kesiapsiagaan di setiap Provinsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7268, '3. Paket Logistik Lain terdiri atas: Paket obat dan alat kesehatan habis pakai, tenda gulung, tikar dan matras, paket ini untuk satu Kepala Keluarga (empat jiwa)
4. Paket Kematian, terdiri atas: Kain kafan dan kelengkapannya dan kantong mayat, paket ini untuk satu jiwa.
C. Standar Logistik Penanggulangan Bencana
1. Tahap Kesiapsiagaan.
Standar Logistik yang tersedia pada tahap kesiapsiagaan berfungsi sebagai ”buffer stock”. Berdasarkan Provinsi dan jumlah penduduk, maka standar minimal logistik yang tersedia dapat diuraikan sebagai berikut:
a. Standar Umum.
Secara umum setiap wilayah Provinsi disiagakan paket pangan, paket sandang, paket logistik lainnya dan paket kematian. Standar minimal paket pangan yang tersedia adalah 1% dari jumlah penduduk selama 3 (tiga) hari. Paket sandang dan logistik lain untuk 1 (satu) Kepala keluarga.
Khusus untuk paket kematian 1% dari jumlah paket sandang.
b. Standar Khusus.
Secara khusus standar jumlah minimal setiap paket logistik yang tersedia di setiap Provinsi dapat dilihat pada tabel dibawah ini.
2014, No.1090 12 Tabel. 1 Standar minimal paket logistik kesiapsiagaan di setiap Provinsi.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik');
