INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7269, 'Jumlah Paket Paket Paket Paket No Provinsi Penduduk Logistik Pangan Sandang Kematian (BPS,2005) Lain 1 NAD 3.970.612 119.118 993 993 99 2 Sumut 12.400.571 372.017 3.100 3.100 310 3 Riau 4.563.412 136.902 1.141 1.141 114 4 Kepri 1.274.227 38.227 319 319 32 5 Sumbar 4.555.812 136.674 1.139 1.139 114 6 Jambi 2.627.231 78.817 657 657 66 7 Bengkulu 1.546.342 46.390 387 387 39 8 Babel 1.042.828 31.285 261 261 26 9 Lampung 7.104.572 213.137 1.776 1.776 178 10 Sumsel 6.767.645 203.029 1.692 1.692 169 11 Banten 9.008.151 270.245 2.252 2.252 225 12 Jabar 38.886.975 1.166.609 9.722 9.722 972 13 DKI 8.839.247 265.177 2.210 2.210 221 14 Jateng 31.896.114 956.883 7.974 7.974 797 15 DIY 3.337.095 100.113 834 834 83 16 Jatim 18.058.107 541.743 4.515 4.515 451 17 Bali 3.378.092 101.343 845 845 84 18 NTB 4.169.695 125.091 1.042 1.042 104 19 NTT 4.243.128 127.294 1.061 1.061 106 20 Malut 881.867 26.456 220 220 22 21 Maluku 1.249.212 37.476 312 312 31 22 Papua Barat 622.275 18.668 156 156 16 23 Papua 1.844.519 55.336 461 461 46 24 Kalbar 4.042.817 121.285 1.011 1.011 101 25 Kalsel 3.271.413 98.142 818 818 82 26 Kalteng 1.913.026 57.391 478 478 48 13 2014, No.1090 27 Kaltim 2.840.874 85.226 710 710 71 28 Sulut 2.121.017 63.631 530 530 53 29 Gorontalo 920.015 27.600 230 230 23 30 Sulteng 2.290.969 68.729 573 573 57 31 Sultra 1.960.697 58.821 490 490 49 32 Sulbar 968.449 29.053 242 242 24 33 Sulsel 7.488.674 224.660 1.872 1.872 187 JUMLAH 200.085.680 6.002.570 50.021 50.021 5.002 Pengadaan', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7270, 'perka-18-2009', 18, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'logistik untuk standarisasi logistik, mengunakan Anggaran Pendapatan dan Belanja Nasional (APBN) dan Anggaran Pendapatan dan Belanja Daerah (APBD). Standar jumlah minimal paket logistik ini tersedia di Posko Penanggulangan Bencana atau di BPBD/Kesbang Linmas/Instansi/Lembaga terkait.
Khusus standar minimal beras sesuai dengan Cadangan Beras Pemerintah Reguler Bencana. Cadangan Minimal di Kota/Kabupaten sebanyak 5 (lima) ton. Kewenangan pengadaan oleh Bupati/Walikota sampai dengan 100 (seratus) ton. Cadangan minimal di Provinsi 50 (lima puluh) ton. Kewenangan pengadaan oleh Gubernur antara 100-200 ton, di tingkat nasional kewenangan pengadaan oleh Menteri Sosial diatas 200 (dua ratus) ton (menurut Depsos RI).
2. Tahap Tanggap Darurat.
Standar logistik pada tahap tanggap darurat menggunakan ”buffer stock” (standar logistik kesiapsiagaan), yang berfungsi sebagai pemberian layanan kebutuhan dasar minimal untuk korban bencana pada saat tanggap darurat. Kebutuhan logistik tahap tanggap darurat selanjutnya didasarkan pada hasil analisis need assesment tanggap darurat.
3. Tahap Rahabilitasi dan Rekonstruksi.
Standar Logistik pada tahap rehabilitasi dan rekonstruksi berfungsi sebagai pemberian layanan kebutuhan dasar minimal untuk kelangsungan kehidupan korban bencana pada saat berada dipengungsian. Standar jumlah minimal paket logistik yang tersedia ditentukan berdasarkan hasil analisis need assesment.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7270, 'logistik untuk standarisasi logistik, mengunakan Anggaran Pendapatan dan Belanja Nasional (APBN) dan Anggaran Pendapatan dan Belanja Daerah (APBD). Standar jumlah minimal paket logistik ini tersedia di Posko Penanggulangan Bencana atau di BPBD/Kesbang Linmas/Instansi/Lembaga terkait.
Khusus standar minimal beras sesuai dengan Cadangan Beras Pemerintah Reguler Bencana. Cadangan Minimal di Kota/Kabupaten sebanyak 5 (lima) ton. Kewenangan pengadaan oleh Bupati/Walikota sampai dengan 100 (seratus) ton. Cadangan minimal di Provinsi 50 (lima puluh) ton. Kewenangan pengadaan oleh Gubernur antara 100-200 ton, di tingkat nasional kewenangan pengadaan oleh Menteri Sosial diatas 200 (dua ratus) ton (menurut Depsos RI).
2. Tahap Tanggap Darurat.
Standar logistik pada tahap tanggap darurat menggunakan ”buffer stock” (standar logistik kesiapsiagaan), yang berfungsi sebagai pemberian layanan kebutuhan dasar minimal untuk korban bencana pada saat tanggap darurat. Kebutuhan logistik tahap tanggap darurat selanjutnya didasarkan pada hasil analisis need assesment tanggap darurat.
3. Tahap Rahabilitasi dan Rekonstruksi.
Standar Logistik pada tahap rehabilitasi dan rekonstruksi berfungsi sebagai pemberian layanan kebutuhan dasar minimal untuk kelangsungan kehidupan korban bencana pada saat berada dipengungsian. Standar jumlah minimal paket logistik yang tersedia ditentukan berdasarkan hasil analisis need assesment.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7271, 'perka-18-2009', 19, 'lampiran', 'Lampiran hal. 13', NULL, 13, 'D. Standar Logistik Bantuan dari Luar Negeri Standar logistik bantuan dari Luar Negeri disesuaikan dengan persyaratan yang ditetapkan oleh BNPB.
2014, No.1090 14 BAB III PENGENDALIAN DAN PENGAWASAN A. Pengendalian Pengendalian dalam bentuk pelaporan pengadaan, penggunaan dan pemeliharaan logistik penanggulangan bencana dilakukan oleh instansi/lembaga pemerintah yang berwenang.
B. Pengawasan Aspek yang diawasi :
1. Sasaran penerima bantuan yang sesuai dan tepat.
2. Mencocokkan antara data di manifest pengangkutan dengan jenis bantuan logistik yang diterima baik jenis, jumlah, berat, tujuan dan kondisi logistik.
3. Melihat catatan mengenai tempat pemberangkatan, tanggal waktu kedatangan, sarana transportasi, pengirim dan penerima logistik.
4. Mengecek berita acara serah terima dan bukti penerimaan.
5. Pelabelan logistik harus jelas, meliputi: Penerima, jenis dan jumlah logistik.
C. Pertanggungjawaban Pertanggungjawaban keuangan maupun kinerja dalam standarisasi logistik, dilakukan pada setiap tahapan persiapan, proses dan setelah proses pengiriman bantuan, dalam bentuk laporan secara berjenjang dan berkala sesuai dengan prinsip akuntabilitas dan transparansi, pada setiap tahap Penanggulangan bencana.
D. Penghapusan Penghapusan paket logistik disesuaikan dengan peraturan perundangan yang berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7271, 'D. Standar Logistik Bantuan dari Luar Negeri Standar logistik bantuan dari Luar Negeri disesuaikan dengan persyaratan yang ditetapkan oleh BNPB.
2014, No.1090 14 BAB III PENGENDALIAN DAN PENGAWASAN A. Pengendalian Pengendalian dalam bentuk pelaporan pengadaan, penggunaan dan pemeliharaan logistik penanggulangan bencana dilakukan oleh instansi/lembaga pemerintah yang berwenang.
B. Pengawasan Aspek yang diawasi :
1. Sasaran penerima bantuan yang sesuai dan tepat.
2. Mencocokkan antara data di manifest pengangkutan dengan jenis bantuan logistik yang diterima baik jenis, jumlah, berat, tujuan dan kondisi logistik.
3. Melihat catatan mengenai tempat pemberangkatan, tanggal waktu kedatangan, sarana transportasi, pengirim dan penerima logistik.
4. Mengecek berita acara serah terima dan bukti penerimaan.
5. Pelabelan logistik harus jelas, meliputi: Penerima, jenis dan jumlah logistik.
C. Pertanggungjawaban Pertanggungjawaban keuangan maupun kinerja dalam standarisasi logistik, dilakukan pada setiap tahapan persiapan, proses dan setelah proses pengiriman bantuan, dalam bentuk laporan secara berjenjang dan berkala sesuai dengan prinsip akuntabilitas dan transparansi, pada setiap tahap Penanggulangan bencana.
D. Penghapusan Penghapusan paket logistik disesuaikan dengan peraturan perundangan yang berlaku.', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2009 tentang Pedoman Standarisasi Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7272, 'perka-18-2009', 20, 'lampiran', 'Lampiran hal. 15', NULL, 15, '15 2014, No.1090 BAB IV PENUTUP Pedoman Standarisasi Logistik Penanggulangan Bencana dimaksudkan sebagai petunjuk praktis yang dipergunakan oleh semua pihak dalam melaksanakan penyelenggaraan kelogistikan dalam upaya Penanggulangan bencana sejak pra bencana (kesiapsiagaan), saat bencana dan pasca bencana. Dengan demikian diharapkan pelaksanaan penyelenggaraan logistik dapat berjalan secara efektif dan efisian, terkoordinasi dengan baik. Dan dapat dipertanggungjawabkan.
Sesuai dengan perkembangan kebutuhan, serta situasi dan kondisi lingkungan, maka pedoman standarisasi logistik masih jauh dari sempurna untuk itu masih dimungkinkan untuk perbaikan dan penyempurnaan.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF');
