INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7276, 'perka-18-2010', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan PERATURAN KEPALA BADAN NASIONAL PENANGGULANGANBENCANA TENTANG PEDOMAN DISTRIBUSI BANTUAN LOGISTIK DAN PERALATAN PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7276, 'Menetapkan PERATURAN KEPALA BADAN NASIONAL PENANGGULANGANBENCANA TENTANG PEDOMAN DISTRIBUSI BANTUAN LOGISTIK DAN PERALATAN PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2010 tentang Pedoman Distribusi Bantuan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7277, 'perka-18-2010', 4, 'menetapkan', 'Isi hal. 2', NULL, 2, 'Pasal 1 Pedoman Distribusi Bantuan Logistik dan Peralatan Penanggulangan Bencana merupakan panduanjacuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, 3 2014, No.1554 Instansr/Iembaga dan pemangku kepentingan penanggulangan bencana lainnya agar dapat melaksanakan distribusi dengan cepat, tepat, terpadu, efektif, efisien dan akuntabel.
Pasal2 Pedoman sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian tak terpisahkan dari Peraturan Kepala ini.
Pasal3 Peraturan Kepala ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Repu blik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7277, 'Pasal 1 Pedoman Distribusi Bantuan Logistik dan Peralatan Penanggulangan Bencana merupakan panduanjacuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, 3 2014, No.1554 Instansr/Iembaga dan pemangku kepentingan penanggulangan bencana lainnya agar dapat melaksanakan distribusi dengan cepat, tepat, terpadu, efektif, efisien dan akuntabel.
Pasal2 Pedoman sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian tak terpisahkan dari Peraturan Kepala ini.
Pasal3 Peraturan Kepala ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Repu blik Indonesia.', 'Isi hal. 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2010 tentang Pedoman Distribusi Bantuan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7278, 'perka-18-2010', 5, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 30 November 2010 KEPALABADAN NASIONAL PENANGGULANGANBENCANA, SYAMSULMAARIF Diundangkan di Jakarta pada tanggal 14 Oktober 2014 MENTERI HUKUMDAN HAKASASI MANUSIA REPUBLIKINDONESIA, AMIR SYAMSUDIN 2014, No.1554 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7278, 'Ditetapkan di Jakarta pada tanggal 30 November 2010 KEPALABADAN NASIONAL PENANGGULANGANBENCANA, SYAMSULMAARIF Diundangkan di Jakarta pada tanggal 14 Oktober 2014 MENTERI HUKUMDAN HAKASASI MANUSIA REPUBLIKINDONESIA, AMIR SYAMSUDIN 2014, No.1554 4', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2010 tentang Pedoman Distribusi Bantuan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7279, 'perka-18-2010', 6, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 18 TAHUN 2010 TENTANG PEDOMAN DISTRIBUSI DAN PERALATAN PENANGGULANGAN BENCANA BABI PENDAHULUAN A. Latar Belakang Wilayah Negara Kesatuan Republik Indonesia sangat luas, sebagian besar terdiri dari lautan dan ribuan pulau yang terbentang dari Sabang sampai Merauke. Memiliki kondisi geologi yang rawan beneana, geografi yang bervariasi, jumlah penduduk yang sangat besar.
Apabila terjadi beneana baik beneana alam, non alam maupun sosial akan menimbulkan korban manusia, kerugian harta benda, kerusakan lingkungan dan dampak psikologis. Pemerintah dan pemerintah daerah berkewajiban memberikan bantuan untuk meringankan penderitaan korban beneana. Bantuan dapat dihimpun dari pemerintah dan pemerintah daerah yang berasal dari APBN atau APBD, bantuan dunia usaha, masyarakat dalam dan luar negeri berupa logistik maupun peralatan untuk penanggulangan beneana.
Bantuan logistik dan peralatan untuk penanggulangan beneana harus dapat diterima oleh korban yang membutuhkan dengan tepat waktu, tepat lokasi, tepat sasaran, tepat jumlah dan tepat kualitas. Agar pendistribusian bantuan logistik dan peralatan yang efektif, efisien, eepat dan akuntabel perlu dibuat pedoman distribusi bantuan logistik dan peralatan untuk penanggulangan beneana.
B. Maksud Dan Tujuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7279, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 18 TAHUN 2010 TENTANG PEDOMAN DISTRIBUSI DAN PERALATAN PENANGGULANGAN BENCANA BABI PENDAHULUAN A. Latar Belakang Wilayah Negara Kesatuan Republik Indonesia sangat luas, sebagian besar terdiri dari lautan dan ribuan pulau yang terbentang dari Sabang sampai Merauke. Memiliki kondisi geologi yang rawan beneana, geografi yang bervariasi, jumlah penduduk yang sangat besar.
Apabila terjadi beneana baik beneana alam, non alam maupun sosial akan menimbulkan korban manusia, kerugian harta benda, kerusakan lingkungan dan dampak psikologis. Pemerintah dan pemerintah daerah berkewajiban memberikan bantuan untuk meringankan penderitaan korban beneana. Bantuan dapat dihimpun dari pemerintah dan pemerintah daerah yang berasal dari APBN atau APBD, bantuan dunia usaha, masyarakat dalam dan luar negeri berupa logistik maupun peralatan untuk penanggulangan beneana.
Bantuan logistik dan peralatan untuk penanggulangan beneana harus dapat diterima oleh korban yang membutuhkan dengan tepat waktu, tepat lokasi, tepat sasaran, tepat jumlah dan tepat kualitas. Agar pendistribusian bantuan logistik dan peralatan yang efektif, efisien, eepat dan akuntabel perlu dibuat pedoman distribusi bantuan logistik dan peralatan untuk penanggulangan beneana.
B. Maksud Dan Tujuan', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2010 tentang Pedoman Distribusi Bantuan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7280, 'perka-18-2010', 7, 'lampiran', 'Lampiran hal. 4', NULL, 4, '1. Maksud Sebagai pedoman bagi seluruh petugas penanggulangan beneana, terutama yang berkaitan dengan penyelenggaraan distribusi bantuan logistik dan peralatan penanggulangan beneana.
2. Tujuan Dalam mendistribusikan bantuan logistik dan peralatan dapat dilaksanakan seeara eepat, tepat, terpadu, efektif dan efisien.
5 2014, No.1554
c. Landasan Hukum
1. Undang-undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Peraturan Pemerintah Nomor 6 Tahun 2006 tentang Pengelolaan Barang Milik NegarajDaerah.
3. Peraturan Pemerintah RI Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana
4. Peraturan Pemerintah RI Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
5. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana.
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
7. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2006 tentang Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah.
8. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana.
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008 tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana.
10. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik.');
