INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7281, 'perka-18-2010', 8, 'lampiran', 'Lampiran hal. 5', NULL, 5, '11. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan.
12. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan.
D. Pengertian -Pengertian
1. Bencana Peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2014, No.1554 6
2. Bantuan Logistikdan Peralatan Logistik dan peralatan yang diberikan tanpa memperoleh penggantian atau dipinjam pakaikan kepada pihak yang membutuhkan dalam rangka penanggulangan bencana.
3. Logistik Logistik adalah segala sesuatu yang berwujud dan dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri atas sandang, pangan dan papan atau turunannya.
Termasuk dalam kategori logistik adalah barang yang habis pakai atau dikonsumsi misalnya: sembako, obat dan alat kesehatan habis pakai, pakaian dan kelengkapannya, air, tenda gulung, jas tidur.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7281, '11. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan.
12. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan.
D. Pengertian -Pengertian
1. Bencana Peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2014, No.1554 6
2. Bantuan Logistikdan Peralatan Logistik dan peralatan yang diberikan tanpa memperoleh penggantian atau dipinjam pakaikan kepada pihak yang membutuhkan dalam rangka penanggulangan bencana.
3. Logistik Logistik adalah segala sesuatu yang berwujud dan dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri atas sandang, pangan dan papan atau turunannya.
Termasuk dalam kategori logistik adalah barang yang habis pakai atau dikonsumsi misalnya: sembako, obat dan alat kesehatan habis pakai, pakaian dan kelengkapannya, air, tenda gulung, jas tidur.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2010 tentang Pedoman Distribusi Bantuan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7282, 'perka-18-2010', 9, 'lampiran', 'Lampiran hal. 6', NULL, 6, '4. Peralatan Peralatan adalah segala bentuk alat dan peralatan yang dapat dipergunakan untuk membantu penyelamatan dan evakuasi masyarakat terkena bencana, pemenuhan kebutuhan dasar dan pemulihan segera prasarana dan sarana vital. Termasuk dalam kategori ini misalnya : perahu karet, mobil rescue tactical unit, mobil dapur umum, mobil tangki air, tenda, pompa, peralatan kesehatan, peralatan komunikasi dan alat-ialat berat.
5. Distribusi Bantuan Logistikdan Peralatan Adalah suatu sistem penyaluran dan atau pembagian bantuan logistik dan peralatan dalam rangka penanggulangan bencana dari daerah asal ke daerah tujuan sampai pada sasaran yang dituju.
6. Titik Distribusi Tempat atau fasilitas yang ditentukan atau ditetapkan untuk penyimpanan atau penyaluran bantuan logistik dan peralatan yang telah ditentukan oleh pejabat berwenang untuk dalam rangka penanggulangan bencana yang mudah dijangkau, relatif aman serta terdapat saranaj prasarana yang memadai.
E. Ruang Lingkup Dan Sistematika
1. Ruang lingkup Pedoman distribusi bantuan logistik dan peralatan ini, meliputi ketentuan beberapa aspek operasional tentang pola penyelenggaraan, mekanisme penyelenggaraan, serta pengawasan dan pelaporan.
7 2014, No.1554
2. Sistematika Pedoman distribusi bantuan Logistik dan Peralatan ini, disusun dengan sistematika sebagai beriku t :
I. Pendahuluan
II. Penyelenggaraan Distribusi
III. Mekanisme Penyelenggaraan
IV. Pengawasan dan pelaporan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7282, '4. Peralatan Peralatan adalah segala bentuk alat dan peralatan yang dapat dipergunakan untuk membantu penyelamatan dan evakuasi masyarakat terkena bencana, pemenuhan kebutuhan dasar dan pemulihan segera prasarana dan sarana vital. Termasuk dalam kategori ini misalnya : perahu karet, mobil rescue tactical unit, mobil dapur umum, mobil tangki air, tenda, pompa, peralatan kesehatan, peralatan komunikasi dan alat-ialat berat.
5. Distribusi Bantuan Logistikdan Peralatan Adalah suatu sistem penyaluran dan atau pembagian bantuan logistik dan peralatan dalam rangka penanggulangan bencana dari daerah asal ke daerah tujuan sampai pada sasaran yang dituju.
6. Titik Distribusi Tempat atau fasilitas yang ditentukan atau ditetapkan untuk penyimpanan atau penyaluran bantuan logistik dan peralatan yang telah ditentukan oleh pejabat berwenang untuk dalam rangka penanggulangan bencana yang mudah dijangkau, relatif aman serta terdapat saranaj prasarana yang memadai.
E. Ruang Lingkup Dan Sistematika
1. Ruang lingkup Pedoman distribusi bantuan logistik dan peralatan ini, meliputi ketentuan beberapa aspek operasional tentang pola penyelenggaraan, mekanisme penyelenggaraan, serta pengawasan dan pelaporan.
7 2014, No.1554
2. Sistematika Pedoman distribusi bantuan Logistik dan Peralatan ini, disusun dengan sistematika sebagai beriku t :
I. Pendahuluan
II. Penyelenggaraan Distribusi
III. Mekanisme Penyelenggaraan
IV. Pengawasan dan pelaporan', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2010 tentang Pedoman Distribusi Bantuan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7283, 'perka-18-2010', 10, 'lampiran', 'Lampiran hal. 7', NULL, 7, 'V. Penutup 2014, No.1554 8 BABII PENYELENGGARAAN DISTRIBUSI A. Kebijakan Dan Strategi
1. Kebijakan Kebijakan distribusi bantuan logistik dan peralatan penanggulangan bencana didasarkan dengan mengutamakan skala prioritas, terencana, terpadu dan akuntabel.
2. Strategi Strategi distribusi merupakan rangkaian kegiatan yang dikoordinasikan dengan cepat dan tepat sehingga bantuan logistik dan peralatan yang disalurkan dapat diterima secara lengkap dan baik serta dapat digunakan secara optimal meliputi :
a. Mengutamakan daerah dalam darurat bencana, khususnya bantuan logistik dan peralatan untuk pencarian, penyelamatan, evakuasi korban dan pemulihan sarana vital yang rusak.
b. Pemenuhan persediaan (buffer stock) bantuan logistik dan peralatan dalam rangka kesiapsiagaan dilakukan dengan memperhatikan keterpaduan perencanaan kebutuhan.
c. Distribusi bantuan logistik dan peralatan penanggulangan bencana dilaksanakan secara cepat, tepat sasaran, efektif, efisien dan akuntabel.
B. Pola Penyelenggaraan Pelaksanaan distribusi bantuan logistik dan peralatan dilakukan secara cepat, tepat, efektif, efisien dan akuntabel dimulai dari tingkat pusat, provinsi, kabupatenjkota hingga ke gudangjpenampungan sementaraj lokasij sasaran sesuai dengan tujuannya dengan memanfaatkan titik-titik distribusi yang telah ditentukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7283, 'V. Penutup 2014, No.1554 8 BABII PENYELENGGARAAN DISTRIBUSI A. Kebijakan Dan Strategi
1. Kebijakan Kebijakan distribusi bantuan logistik dan peralatan penanggulangan bencana didasarkan dengan mengutamakan skala prioritas, terencana, terpadu dan akuntabel.
2. Strategi Strategi distribusi merupakan rangkaian kegiatan yang dikoordinasikan dengan cepat dan tepat sehingga bantuan logistik dan peralatan yang disalurkan dapat diterima secara lengkap dan baik serta dapat digunakan secara optimal meliputi :
a. Mengutamakan daerah dalam darurat bencana, khususnya bantuan logistik dan peralatan untuk pencarian, penyelamatan, evakuasi korban dan pemulihan sarana vital yang rusak.
b. Pemenuhan persediaan (buffer stock) bantuan logistik dan peralatan dalam rangka kesiapsiagaan dilakukan dengan memperhatikan keterpaduan perencanaan kebutuhan.
c. Distribusi bantuan logistik dan peralatan penanggulangan bencana dilaksanakan secara cepat, tepat sasaran, efektif, efisien dan akuntabel.
B. Pola Penyelenggaraan Pelaksanaan distribusi bantuan logistik dan peralatan dilakukan secara cepat, tepat, efektif, efisien dan akuntabel dimulai dari tingkat pusat, provinsi, kabupatenjkota hingga ke gudangjpenampungan sementaraj lokasij sasaran sesuai dengan tujuannya dengan memanfaatkan titik-titik distribusi yang telah ditentukan.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2010 tentang Pedoman Distribusi Bantuan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7284, 'perka-18-2010', 11, 'lampiran', 'Lampiran hal. 8', NULL, 8, '1. Pra dan Pasca Bencana Pada saat pra dan pasca bencana BNPB dan kementerianjlembaga terkait dalam melaksanakan distribusi bantuan logistik dan peralatan, sesuai dengan sistem distribusi masing-masing yang berlaku.
2. Tanggap Darurat
a. Nasional 1) BNPB menunjukjmenetapkan satu atau lebih titik distribusi.
9 2014, No.1554 2) BNPB berwenang untuk mengerahkan sarana distribusi dari instansi/lembaga lain yang terkait.
3) Dalam pemilihan moda transportasi untuk distribusi harus selalu mempertimbangkan faktor geografis, keaman an , kondisi lingkungan, cuaca dan ketersediaan prasarana dan sarana pendukung di daerah tujuan.
4) Kebutuhan biaya distribusi baik dari pusat ke daerah maupun dari daerah lain atas permintaan BNPB diatur sesuai dengan peraturan yang berlaku.
5) Pelaksanaan distribusi bantuan dikoordinasikan oleh BNPB
b. Provinsi 1) BPBD Provinsi menunjuk/menetapkan satu atau lebih titik distribusi.
2) BPBD Provinsi berwenang untuk mengerahkan sarana distribusi dari instansi/lembaga lain yang terkait.
3) Dalam pemilihan moda transportasi untuk distribusi harus selalu mempertimbangkan faktor geografis, keaman an , kondisi lingkungan, cuaca dan ketersediaan sarana prasarana pendukung di daerah tujuan.
4) Apabila moda transportasi yang dibutuhkan tidak terdapat di provinsi yang terkena bencana dapat meminta bantuan provmsi terdekat atau ke pusat (BNPB).
5) Segala biaya yang ditimbulkan akibat pengerahan/ distribusi terse but ditanggung oleh provinsi yang bersangkutan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7284, '1. Pra dan Pasca Bencana Pada saat pra dan pasca bencana BNPB dan kementerianjlembaga terkait dalam melaksanakan distribusi bantuan logistik dan peralatan, sesuai dengan sistem distribusi masing-masing yang berlaku.
2. Tanggap Darurat
a. Nasional 1) BNPB menunjukjmenetapkan satu atau lebih titik distribusi.
9 2014, No.1554 2) BNPB berwenang untuk mengerahkan sarana distribusi dari instansi/lembaga lain yang terkait.
3) Dalam pemilihan moda transportasi untuk distribusi harus selalu mempertimbangkan faktor geografis, keaman an , kondisi lingkungan, cuaca dan ketersediaan prasarana dan sarana pendukung di daerah tujuan.
4) Kebutuhan biaya distribusi baik dari pusat ke daerah maupun dari daerah lain atas permintaan BNPB diatur sesuai dengan peraturan yang berlaku.
5) Pelaksanaan distribusi bantuan dikoordinasikan oleh BNPB
b. Provinsi 1) BPBD Provinsi menunjuk/menetapkan satu atau lebih titik distribusi.
2) BPBD Provinsi berwenang untuk mengerahkan sarana distribusi dari instansi/lembaga lain yang terkait.
3) Dalam pemilihan moda transportasi untuk distribusi harus selalu mempertimbangkan faktor geografis, keaman an , kondisi lingkungan, cuaca dan ketersediaan sarana prasarana pendukung di daerah tujuan.
4) Apabila moda transportasi yang dibutuhkan tidak terdapat di provinsi yang terkena bencana dapat meminta bantuan provmsi terdekat atau ke pusat (BNPB).
5) Segala biaya yang ditimbulkan akibat pengerahan/ distribusi terse but ditanggung oleh provinsi yang bersangkutan.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2010 tentang Pedoman Distribusi Bantuan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7285, 'perka-18-2010', 12, 'lampiran', 'Lampiran hal. 9', NULL, 9, '6) Pelaksanaan distribusi bantuan dikoordinasikan oleh BPBDprovinsi yang bersangkutan.
c. Kabupatcrr/Kota 1) BPBD Kabupatcu/Kota menunjuk/menetapkan satu atau lebih tempaty titik distribusi.
2) BPBD Kabupaten./Kota berwenang untuk meminta/ mengerahkan sarana distribusi dari instansi/lembaga lain yang terkait 3) Dalam pemilihan moda transportasi untuk distribusi harus selalu mempertimbangkan faktor geografis, keaman an , kondisi lingkungan, cuaca dan ketersediaan prasarana dan sarana pendukung di daerah tujuan.
2014, No.1554 10 4) Apabila moda transportasi yang dibutuhkan tidak terdapat di daerahnya, dapat meminta bantuan ke Kabupatcrr/Kota terdekat dan atau ke BPBDProvinsi.
5) Segala biaya yang ditimbulkan akibat distribusi tersebut menjadi tanggung jawab Kabupaten./Kota yang bersangkutan.
6) Pelaksanaan distribusi dikoordinasikan oleh BPBD Kabupaten / Kota yang bersangku tan.
BABIII MEKANISME PENYELENGGARAAN A. Perencanaan Distribusi
1. Perencanaan distribusi bantuan logistik dan peralatan merupakan langkah awal untuk mengetahui jumlah, mutu, jenis, spesifikasi, waktu dan cara pendistribusiannya.
2. Perencanaan distribusi pada saat kesiapsiagaan dan pasca bencana dilaksanakan sebagaimana ketentuan yang berlaku, sesuai dengan jadwal dan perencanaan yang telah ditetapkan.
3. Perencanaan distribusi pada saat tanggap darurat dilakukan berdasar kan kemudahan akses sesuai peraturan yang berlaku dan mengacu kepada hasil kaji cepat kebutuhan (need assesment).
B. Persiapan Distribusi');
