INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7294, 'perka-18-2011', 4, 'pasal', 'Pasal 1', NULL, 2, 'Dalam Peraturan Kepala ini yang dimaksud dengan :
1. Arsip adalah rekaman kegiatan atau peristiwa dalam berbagai bentuk dan media sesuai dengan perkembangan teknologi informasi dan komunikasi yang dibuat dan diterima oleh lembaga negara, pemerintahan daerah, lembaga pendidikan, perusahaan, organisasi politik, organisasi kemasyarakatan, dan perseorangan dalam pelaksanaan kehidupan bermasyarakat, berbangsa, dan bernegara.
2. Arsip Fasilitatif Non Keuangan dan Non Kepegawaian adalah arsip yang berkaitan dengan bidang non keuangan/fiskal dan non 3 2014, No.1558 kepegawaian yang meliputi perencanaan, hukum dan kerjasama, kerumahtanggaan, ketatausahaan dan kearsipan, data informasi dan hubungan masyarakat, kepustakaan, pendidikan dan pelatihan penanggulangan bencana, pengawasan serta organisasi dan ketatalaksanaan;
3. Jadwal Retensi Arsip yang selanjutnya disingkat JRA adalah daftar yang berisi sekurang-kurangnya jangka waktu penyimpanan atau retensi, jenis arsip, dan keterangan yang berisi rekomendasi tentang penetapan suatu jenis arsip dimusnahkan, dinilai kembali, atau dipermanenkan yang dipergunakan sebagai pedoman penyusutan dan penyelamatan arsip.
4. Jadwal Retensi Arsip Fasilitatif Non Keuangan Dan Non Kepegawaian adalah daftar berisi jenis arsip Fasilitatif Non Keuangan Dan Non Kepegawaian beserta jangka waktu penyimpanannya sesuai degan nilai kegunaannya dan di pakai sebagai pedoman penyusutan arsip fasilitatif perencanaan, hukum dan kerjasama, kerumahtanggaan, ketatausahaan dan kearsipan, data informasi dan hubungan masyarakat, kepustakaan, pendidikan dan pelatihan penanggulangan bencana, pengawasan serta organisasi dan ketatalaksanaan.
5. Penyusutan Arsip adalah kegiatan pengurangan jumlah arsip dengan cara pemindahan arsip inaktif dari unit pengolah ke unit kearsipan, pemusnahan arsip yang telah habis retensi dan yang tidak memiliki nilai guna dilaksanakan sesuai dengan ketentuan peraturan perudang
- undangan serta penyerahan arsip statis oleh pencipta arsip kepada lembaga kearsipan.
6. Pemindahan Arsip lnaktif adalah kegiatan pengurangan arsip inaktif dan pengalihan tanggung jawab pengelolaan arsip inaktif dari Unit Pengolah ke Unit Kearsipan di lingkungan Lembaga-lembaga Negara dan Badan-badan Pemerintahan
7. Pemusnahan Arsip adalah kegiatan pengurangan arsip yang telah habis retensi dan berketerangan dimusnahkan berdasarkan JRA, tidak memiliki nilai guna, dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan dan tidak berkaitan dengan penyelesaian proses suatu perkara;
8. Nilai Guna Arsip adalah nilai arsip yang didasarkan pada kegunaannya bagi kepentingan pengguna arsip.
9. Nilai Guna Primer adalah nilai arsip yang didasarkan pada kegunaan arsip bagi kepentingan lembaga I instansi pencipta arsip.
10. Nilai Guna Sekunder adalah nilai arsip yang didasarkan pada kegunaan arsip bagi kepentingan lembaga/instansi lain dan atau kepentingan umum di luar lembaga/instansi pencipta arsip dan 2014, No.1558 4 kegunaannya sebagai bahan bukti dan bahan pertanggungjawaban nasional.
11. Jenis Arsip adalah kelompok dokumen yang diatur dalam suatu sistem pemberkasan tertentu atau dipertahankan sebagai satuan unit karena mereka tercipta dari kesamaan proses akumulasi dan pemberkasan, kesamaan aktivitas, memiliki bentuk khusus, atau karena beberapa keterkaitan erat lain yang muncul dari penerimaan, penciptaan atau penggunaannya.
12. Jangka Waktu Simpan (Retensi) adalah masa simpan minimal suatu jenis arsip pada Unit Pengolah dan atau Unit Kearsipan.
13. Jangka Waktu Simpan (Retensi) Aktif adalah masa simpan minimal suatu jenis arsip pada Unit Pengolah. Jangka waktu Simpan Arsip Aktif dihitung sejak arsip diciptakan mulai diregistrasi hingga selesai diproses.
14. Jangka Waktu Simpan (Retensi) lnaktif adalah masa simpan minimal suatu jenis arsip pada Unit Kearsipan/ Pusat arsip. Jangka waktu Simpan Arsip lnaktif dihitung sejak habisnya masa retensi arsip aktif sampai nilai gunanya untuk kepentingan referensi berakhir
15. "Musnah" pada kolom "Keterangan" adalah keterangan yang menyatakan bahwa arsip dapat dimusnahkan karena jangka waktu penyimpanan telah selesai dan tidak memiliki nilai guna lagi.
16. "Permanen" pada kolom "Keterangan" adalah keterangan yang menyatakan bahwa arsip memiliki nilai guna sekunder, wajib diserahkan kepada Arsip Nasional Republik lndonesia/Lembaga Kearsipan sesuai dengan lingkup kewenangan masing-masing.
17. "Dinilai Kembali" pada kolom "Keterangan" adalah keterangan yang menyatakan bahwa suatu jenis arsip belum dapat ditentukan nasib akhirnya apakah musnah atau permanen, sehingga perlu dilakukan penilaian dan pengkajian lagi.
18. Penyelenggaraan Kearsipan adalah keseluruhan kegiatan meliputi kebijakan, pembinaan kearsipan, dan pengelolaan arsip dalam suatu sistem kearsipan nasional yang didukung oleh sumber daya manusia, prasarana dan sarana, serta sumber daya lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7294, 'Dalam Peraturan Kepala ini yang dimaksud dengan :
1. Arsip adalah rekaman kegiatan atau peristiwa dalam berbagai bentuk dan media sesuai dengan perkembangan teknologi informasi dan komunikasi yang dibuat dan diterima oleh lembaga negara, pemerintahan daerah, lembaga pendidikan, perusahaan, organisasi politik, organisasi kemasyarakatan, dan perseorangan dalam pelaksanaan kehidupan bermasyarakat, berbangsa, dan bernegara.
2. Arsip Fasilitatif Non Keuangan dan Non Kepegawaian adalah arsip yang berkaitan dengan bidang non keuangan/fiskal dan non 3 2014, No.1558 kepegawaian yang meliputi perencanaan, hukum dan kerjasama, kerumahtanggaan, ketatausahaan dan kearsipan, data informasi dan hubungan masyarakat, kepustakaan, pendidikan dan pelatihan penanggulangan bencana, pengawasan serta organisasi dan ketatalaksanaan;
