INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7296, 'perka-18-2011', 6, 'pasal', 'Pasal 3', NULL, 5, 'Bentuk dan susunan Jadwal Retensi Arsip Fasilitatif Non Keuangan Dan Non Kepegawaian Badan Nasional Penanggulangan Bencana sebagaimana di maksud dalam Pasal 2 meliputi : kolom nomor, kolom jenis arsip, kolom jangka waktu simpan (Retensi) Aktif, lnaktif dan keterangan yang berisi pernyataan musnah, permanen atau dinilai kembali.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7296, 'Bentuk dan susunan Jadwal Retensi Arsip Fasilitatif Non Keuangan Dan Non Kepegawaian Badan Nasional Penanggulangan Bencana sebagaimana di maksud dalam Pasal 2 meliputi : kolom nomor, kolom jenis arsip, kolom jangka waktu simpan (Retensi) Aktif, lnaktif dan keterangan yang berisi pernyataan musnah, permanen atau dinilai kembali.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2011 tentang Jadwal Retensi Arsip Fasilitatif Non Keuangan dan Non Kepegawaian Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7297, 'perka-18-2011', 7, 'pasal', 'Pasal 4', NULL, 5, 'Jadwal Retensi Arsip sebagaimana dimaksud dalam Pasal 2 Peraturan ini dipakai sebagai pedoman penyusutan Arsip Non Keuangan Dan Non Kepegawaian di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7297, 'Jadwal Retensi Arsip sebagaimana dimaksud dalam Pasal 2 Peraturan ini dipakai sebagai pedoman penyusutan Arsip Non Keuangan Dan Non Kepegawaian di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2011 tentang Jadwal Retensi Arsip Fasilitatif Non Keuangan dan Non Kepegawaian Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7298, 'perka-18-2011', 8, 'pasal', 'Pasal 5', NULL, 5, 'Penyusutan Arsip Non Keuangan Dan Non Kepegawaian di lingkunggan BNPB, khususnya penyerahan arsip stalis perencanaan, hukum dan kerjasama, kerumahtanggaan, ketatausahaan dan kearsipan, data inforrnasi dan hubungan masyarakat, kepustakaan, pendidikan dan pelatihan penanggulangan bencana, pengawasan serta organisasi dan ketatalaksanaan merupakan bagian yang tidak terpisahkan dari penyerahan arsip stalis instansi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7298, 'Penyusutan Arsip Non Keuangan Dan Non Kepegawaian di lingkunggan BNPB, khususnya penyerahan arsip stalis perencanaan, hukum dan kerjasama, kerumahtanggaan, ketatausahaan dan kearsipan, data inforrnasi dan hubungan masyarakat, kepustakaan, pendidikan dan pelatihan penanggulangan bencana, pengawasan serta organisasi dan ketatalaksanaan merupakan bagian yang tidak terpisahkan dari penyerahan arsip stalis instansi.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2011 tentang Jadwal Retensi Arsip Fasilitatif Non Keuangan dan Non Kepegawaian Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7299, 'perka-18-2011', 9, 'pasal', 'Pasal 6', NULL, 5, 'Peraturan Kepala ini mulai berlaku sejak langgal diundangkan.
