INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7300, 'perka-18-2011', 10, 'lain', 'Penutup', NULL, 5, 'Ditetapkan di Jakarta pada tanggal 30 Desember 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 14 Oktober 2014 MENTERI HUKUM DAN HAK AZASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7300, 'Ditetapkan di Jakarta pada tanggal 30 Desember 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 14 Oktober 2014 MENTERI HUKUM DAN HAK AZASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2011 tentang Jadwal Retensi Arsip Fasilitatif Non Keuangan dan Non Kepegawaian Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7301, 'perka-18-2014', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2014 tentang Hari dan Jam Kerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
