INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7302, 'perka-18-2014', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka mendorong profesionalitas serta meningkatkan kinerja, guna mewujudkan kelancaran pelaksanaan tugas dan prestasi kerja Pegawai, perlu disiplin kerja bagi Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Hari dan Jam Kerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7302, 'a. bahwa dalam rangka mendorong profesionalitas serta meningkatkan kinerja, guna mewujudkan kelancaran pelaksanaan tugas dan prestasi kerja Pegawai, perlu disiplin kerja bagi Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Hari dan Jam Kerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 18 Tahun 2014 tentang Hari dan Jam Kerja Pegawai di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7303, 'perka-18-2014', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Undang-Undang Nomor 5 Tahun 2014 tentang Aparatur Sipil Negara (Lembaran Negara Republik 2014, No.2079 2 Indonesia Tahun 2014 Nomor 6, Tambahan Lembaran Negara Republik Indonesia Nomor 5494);
3. Peraturan Pemerintah Nomor 63 Tahun 2009 tentang Perubahan Atas Peraturan Pemerintah Nomor 9 Tahun 2003 tentang Wewenang Pengangkatan, Pemindahan, dan Pemberhentian Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2009 Nomor 164, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
4. Peraturan Pemerintah Nomor 53 Tahun 2010 tentang Disiplin Pegawai Negeri Sipil (Lembaran Negara Republik Indonesia Tahun 2010 Nomor 74, Tambahan Lembaran Negara Republik Indonesia Nomor 5135);
5. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
6. Keputusan Presiden Nomor 68 Tahun 1995 tentang Hari Kerja di Lingkungan Lembaga Pemerintah;
7. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2013 Nomor 1439);
8. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2013 tentang Perubahan Atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2013 Nomor 1441);');
