INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7333, 'perka-19-2010', 4, 'pasal', 'Pasal 1', NULL, 2, 'Pedoman Penghapusan Logistik dan Peralatan merupakan panduan/acuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/lembaga dan pemangku 3 2014, No.1418 kepentingan penanggulangan bencana lainnya agar pelaksanaan penghapusan dapat dilakukan dengan lancar, tertib, terpadu, aman dan akuntabel.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7333, 'Pedoman Penghapusan Logistik dan Peralatan merupakan panduan/acuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/lembaga dan pemangku 3 2014, No.1418 kepentingan penanggulangan bencana lainnya agar pelaksanaan penghapusan dapat dilakukan dengan lancar, tertib, terpadu, aman dan akuntabel.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 19 Tahun 2010 tentang Pedoman Penghapusan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7334, 'perka-19-2010', 5, 'pasal', 'Pasal 2', NULL, 3, 'Pedoman sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian tak terpisahkan dari Peraturan Kepala ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7334, 'Pedoman sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian tak terpisahkan dari Peraturan Kepala ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 19 Tahun 2010 tentang Pedoman Penghapusan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7335, 'perka-19-2010', 6, 'pasal', 'Pasal 3', NULL, 3, 'Peraturan Kepala ini mulai berlaku pada tanggal ditetapkan.
