INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7336, 'perka-19-2010', 7, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 30 November 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1418 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7336, 'Ditetapkan di Jakarta pada tanggal 30 November 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1418 4', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 19 Tahun 2010 tentang Pedoman Penghapusan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7337, 'perka-19-2010', 8, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 19 TAHUN 2010 TENTANG PEDOMAN PENGHAPUSAN LOGISTIK DAN PERALATAN PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Bencana yang terjadi di suatu wilayah selalu menyentuh rasa kemanusiaan masyarakat luas, baik dalam negeri maupun luar negeri.
Pemerintah/pemerintah daerah, kalangan usaha, masyarakat Indonesia, lembaga internasional maupun lembaga asing nonpemerintah turut serta memberikan bantuan logistik, peralatan, moril maupun tenaga relawan.
Banyaknya bantuan logistik dan peralatan yang terkumpul, didistribusikan ke lokasi agar segera dapat dimanfaatkan, namun seringkali terjadi adanya logistik dan peralatan yang berlebihan, tidak dapat digunakan, rusak atau hilang.
Bantuan logistik dan peralatan yang berlebihan, rusak, dan tidak dapat digunakan tersebut akan menumpuk di tempat distribusi/ gudang penyimpanan, bila dibiarkan tentu akan semakin rusak, bila dipelihara memerlukan biaya yang besar. Demi efisiensi biaya dan keamanan, maka langkah penghapusan perlu dilakukan.
Agar pelaksanaan penghapusan logistik dan peralatan dapat dilakukan dengan lancar, terpadu, aman dan akuntabel, perlu dibuat pedoman penghapusan logistik dan peralatan penanggulangan bencana.
B. Maksud Dan Tujuan
1. Maksud Sebagai pedoman bagi seluruh pemangku kepentingan penanggulangan bencana, terutama yang berkaitan dengan penghapusan logistik dan peralatan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7337, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 19 TAHUN 2010 TENTANG PEDOMAN PENGHAPUSAN LOGISTIK DAN PERALATAN PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Bencana yang terjadi di suatu wilayah selalu menyentuh rasa kemanusiaan masyarakat luas, baik dalam negeri maupun luar negeri.
