INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7339, 'perka-19-2010', 10, 'lampiran', 'Lampiran hal. 5', NULL, 5, '14. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan.
15. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan.
D. Pengertian-Pengertian
1. Bencana Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam, non alam dan manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2014, No.1418 6
2. Barang Milik Negara/Daerah Barang milik negara/daerah adalah semua barang yang dibeli atau diperoleh atas beban APBN dan atau APBD atau berasal dari perolehan lain yang sah.
3. Logistik Logistik adalah segala sesuatu yang berwujud dan dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri atas sandang, pangan, dan papan atau turunannya. Termasuk dalam kategori logistik adalah barang yang habis pakai atau dikonsumsi misalnya : sembako, obat dan alat kesehatan habis pakal, pakaian dan kelengkapannya, air, tenda gulung, jas tidur.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7339, '14. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan.
15. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan.
D. Pengertian-Pengertian
1. Bencana Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam, non alam dan manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2014, No.1418 6
2. Barang Milik Negara/Daerah Barang milik negara/daerah adalah semua barang yang dibeli atau diperoleh atas beban APBN dan atau APBD atau berasal dari perolehan lain yang sah.
3. Logistik Logistik adalah segala sesuatu yang berwujud dan dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri atas sandang, pangan, dan papan atau turunannya. Termasuk dalam kategori logistik adalah barang yang habis pakai atau dikonsumsi misalnya : sembako, obat dan alat kesehatan habis pakal, pakaian dan kelengkapannya, air, tenda gulung, jas tidur.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 19 Tahun 2010 tentang Pedoman Penghapusan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7340, 'perka-19-2010', 11, 'lampiran', 'Lampiran hal. 6', NULL, 6, '4. Peralatan Peralatan adalah segala bentuk alat dan peralatan yang dapat dipergunakan untuk membantu penyelamatan dan evakuasi masyarakat terkena bencana, pemenuhan kebutuhan dasar dan pemulihan segera prasarana dan sarana vital. Termasuk dalam kategori peralatan ini misalnya: perahu karet, mobil rescue tactical unit, mobil dapur umum, mobil tangki air, tenda, pompa, peralatan kesehatan, peralatan komunikasi dan alat-alat berat.
5. Penghapusan Penghapusan adalah tindakan menghapus Barang Milik Negara (logistik dan peralatan) dan daftar barang dengan menerbitkan surat keputusan dari pejabat yang berwenang untuk membebaskan pengguna barang (logistik dan peralatan) dari tanggung jawab administrasi dan fisik logistik dan peralatan yang berada dalam penguasaannya.
6. Pemindahtanganan Pemindahtanganan adalah pengalihan kepemilikan Barang Milik Negara sebagai tindak lanjut dari penghapusan dengan cara dijual, dipertukarkan, dihibahkan atau disertakan sebagai modal pemerintah.
7. Pemusnahan Pemusnahan adalah salah satu kegiatan lanjutan dari penghapusan terhadap logistik dan peralatan yang tidak dapat digunakan, tidak dapat dimanfaatkan, dan tidak dapat dipindah tangankan atau alasan lain sesuai ketentuan peraturan perundang-undangan yang berlaku.
Dilaksanakan dengan cara dibakar, ditanam, dihancurkan, diledakkan atau kombinasi dari cara-cara tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7340, '4. Peralatan Peralatan adalah segala bentuk alat dan peralatan yang dapat dipergunakan untuk membantu penyelamatan dan evakuasi masyarakat terkena bencana, pemenuhan kebutuhan dasar dan pemulihan segera prasarana dan sarana vital. Termasuk dalam kategori peralatan ini misalnya: perahu karet, mobil rescue tactical unit, mobil dapur umum, mobil tangki air, tenda, pompa, peralatan kesehatan, peralatan komunikasi dan alat-alat berat.
5. Penghapusan Penghapusan adalah tindakan menghapus Barang Milik Negara (logistik dan peralatan) dan daftar barang dengan menerbitkan surat keputusan dari pejabat yang berwenang untuk membebaskan pengguna barang (logistik dan peralatan) dari tanggung jawab administrasi dan fisik logistik dan peralatan yang berada dalam penguasaannya.
6. Pemindahtanganan Pemindahtanganan adalah pengalihan kepemilikan Barang Milik Negara sebagai tindak lanjut dari penghapusan dengan cara dijual, dipertukarkan, dihibahkan atau disertakan sebagai modal pemerintah.
7. Pemusnahan Pemusnahan adalah salah satu kegiatan lanjutan dari penghapusan terhadap logistik dan peralatan yang tidak dapat digunakan, tidak dapat dimanfaatkan, dan tidak dapat dipindah tangankan atau alasan lain sesuai ketentuan peraturan perundang-undangan yang berlaku.
Dilaksanakan dengan cara dibakar, ditanam, dihancurkan, diledakkan atau kombinasi dari cara-cara tersebut.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 19 Tahun 2010 tentang Pedoman Penghapusan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7341, 'perka-19-2010', 12, 'lampiran', 'Lampiran hal. 6', NULL, 6, '8. Tuntutan Ganti Rugi Setiap kerugian negara/daerah akibat kelalaian, penyalahgunaan/ pelanggaran hukum atas pengelolaan barang milik negara/daerah diselesaikan melatui tuntutan ganti rugi sesuai dengan peraturan perundang-undangan.
7 2014, No.1418
9. Panitia Penghapusan Panitia penghapusan adalah orang-orang atau pejabat di lingkungan pemangku kepentingan penanggulangan bencana yang dipercaya dan dipilih dengan surat perintah untuk melakukan pencelaan, lelang, hibah dan pemusnahan.
10. Panitia Pencelaan Panitia pencelaan adalah orang-orang atau pejabat di lingkungan pemangku kepentingan penanggulangan bencana yang dipercaya, dipilih dan ditetapkan dengan surat keputusan untuk memeriksa kerusakan/cacat/kekurangan logistik dan peralatan penanggulangan bencana.
11. Panitia Lelang Panitia lelang adalah orang-orang atau pejabat di lingkungan pemangku kepentingan penanggulangan bencana yang dipercaya, dipilih dan ditetapkan dengan surat keputusan untuk melaksanakan lelang terhadap logistik dan peralatan penanggulangan bencana.
12. Panitia Pemusnahan Panitia pemusnahan adalah orang-orang di lingkungan pemangku kepentingan penanggulangan bencana, tenaga ahli instansi terkait dan instansi keamanan yang dipercaya, dipilih dan ditetapkan dengan surat keputusan untuk melakukan pemusnahan terhadap logistik dan peralatan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7341, '8. Tuntutan Ganti Rugi Setiap kerugian negara/daerah akibat kelalaian, penyalahgunaan/ pelanggaran hukum atas pengelolaan barang milik negara/daerah diselesaikan melatui tuntutan ganti rugi sesuai dengan peraturan perundang-undangan.
7 2014, No.1418
9. Panitia Penghapusan Panitia penghapusan adalah orang-orang atau pejabat di lingkungan pemangku kepentingan penanggulangan bencana yang dipercaya dan dipilih dengan surat perintah untuk melakukan pencelaan, lelang, hibah dan pemusnahan.
10. Panitia Pencelaan Panitia pencelaan adalah orang-orang atau pejabat di lingkungan pemangku kepentingan penanggulangan bencana yang dipercaya, dipilih dan ditetapkan dengan surat keputusan untuk memeriksa kerusakan/cacat/kekurangan logistik dan peralatan penanggulangan bencana.
11. Panitia Lelang Panitia lelang adalah orang-orang atau pejabat di lingkungan pemangku kepentingan penanggulangan bencana yang dipercaya, dipilih dan ditetapkan dengan surat keputusan untuk melaksanakan lelang terhadap logistik dan peralatan penanggulangan bencana.
12. Panitia Pemusnahan Panitia pemusnahan adalah orang-orang di lingkungan pemangku kepentingan penanggulangan bencana, tenaga ahli instansi terkait dan instansi keamanan yang dipercaya, dipilih dan ditetapkan dengan surat keputusan untuk melakukan pemusnahan terhadap logistik dan peralatan penanggulangan bencana.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 19 Tahun 2010 tentang Pedoman Penghapusan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7342, 'perka-19-2010', 13, 'lampiran', 'Lampiran hal. 7', NULL, 7, '13. Pengelola Barang Pengelola barang adalah pejabat yang berwenang dan bertanggungjawab menetapkan kebijakan dan pedoman serta melakukan pengelolaan Barang Milik Negara.
E. Ruang Lingkup Dan Sistematika
a. Ruang lingkup Ruang lingkup pedoman penghapusan logistik dan peralatan ini, meliputi penyelenggaraan penghapusan, mekanisme penyelenggaraan, pengawasan dan pelaporan.
b. Sistematika Pedoman Penghapusan Logistik dan Peralatan ini, disusun dengan sistematika sebagai berikut ;
I. Pendahuluan
II. Penyelenggaraan Penghapusan
III. Mekanisme Penyelenggaraan
IV. Pengawasan dan Pelaporan
V. Penutup 2014, No.1418 8 BAB II PENYELENGGARAAN PENGHAPUSAN A. Kebijakan Dan Strategi
1. Kebijakan Kebijakan penghapusan logistik dan peralatan penanggulangan bencana yang tidak layak pakai, hilang, didasarkan dengan mengutamakan efisiensi, keamanan, terpadu dan akuntabel.
2. Strategi Penghapusan merupakan langkah terakhir dari rangkaian kegiatan pengelolaan logistik dan peralatan secara terencana, efisien, aman dan akuntabel, sebagai berikut :
a. Dikoordinasikan, direncanakan dan didukung dengan data yang akurat.
b. Dilakukan secara selektif dengan mempertimbangkan keslapan operasional pemangku kepentingan penanggulangan bencana.
c. Tidak ekonomis bila tetap dipelihara atau digunakan.
d. Dilaksanakan sesual aturan yang berlaku dan didukung dengan administrasi yang lengkap.
e. Pelaksanaan pemusnahan harus aman bagi manusia maupun lingkungan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7342, '13. Pengelola Barang Pengelola barang adalah pejabat yang berwenang dan bertanggungjawab menetapkan kebijakan dan pedoman serta melakukan pengelolaan Barang Milik Negara.
