INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7347, 'perka-19-2010', 18, 'lampiran', 'Lampiran hal. 13', NULL, 13, '13 2014, No.1418 BAB V PENUTUP Pedoman ini dimaksudkan sebagai petunjuk praktis untuk dipergunakan oleh semua pihak dalam rangka penghapusan bantuan logistik dan peralatan penanggulangan bencana. Dengan demikian diharapkan pelaksanaan penghapusan logistik dan peralatan dapat berjalan secara efisien, aman, terpadu, dan akuntabel.
Hal-hal teknis yang belum tercantum dalam pedoman ini akan diatur kemudian.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA SYAMSUL MAARIF');
