KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA SYAMSUL MAARIF', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 19 Tahun 2010 tentang Pedoman Penghapusan Logistik dan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7348, 'perka-19-2011', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 19 Tahun 2011 tentang Pedoman Penyelesaian Kerugian Negara di Lingkungan Badan Nasional Penanggulangan Bencana');
