INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7349, 'perka-2-2008', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7349, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7350, 'perka-2-2008', 1, 'menimbang', 'Menimbang', NULL, 1, 'bahwa dalam rangka melaksanakan ketentuan pasal 58 Peraturan Presiden Nomor 8 Tahun 2008, dipandang perlu menetapkan peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana pada Badan Nasional. Penanggulangan Bencana yang berasal dari masyarakat professional,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7350, 'bahwa dalam rangka melaksanakan ketentuan pasal 58 Peraturan Presiden Nomor 8 Tahun 2008, dipandang perlu menetapkan peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana pada Badan Nasional. Penanggulangan Bencana yang berasal dari masyarakat professional,', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
