INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7351, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),
2. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana,', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7352, 'perka-2-2008', 3, 'menetapkan', 'Menetapkan', NULL, 1, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA DARI MASYARAKAT PROFESIONAL PADA BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7352, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA DARI MASYARAKAT PROFESIONAL PADA BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7353, 'perka-2-2008', 4, 'pasal', 'Pasal 1', NULL, 1, 'Mekanisme pemilihan dan kriteria anggota unsur pengarah digunakan sebagai acuan/arahan dalam melakukan pemilihan untuk mendapatkan anggota unsur pengarah penanggulangan bencana dari masyarakat profesional sesuai dengan yang amanat peraturan perundangan.
Pasal 2...');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7353, 'Mekanisme pemilihan dan kriteria anggota unsur pengarah digunakan sebagai acuan/arahan dalam melakukan pemilihan untuk mendapatkan anggota unsur pengarah penanggulangan bencana dari masyarakat profesional sesuai dengan yang amanat peraturan perundangan.
Pasal 2...', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7354, 'perka-2-2008', 5, 'pasal', 'Pasal 2', NULL, 2, 'Mekanisme pemilihan dan kriteria sebagaimana dimaksud diktum Pertama adalah sebagaimana dalam Lampiran, yang merupakan bagian tak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7354, 'Mekanisme pemilihan dan kriteria sebagaimana dimaksud diktum Pertama adalah sebagaimana dalam Lampiran, yang merupakan bagian tak terpisahkan dari Peraturan ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7355, 'perka-2-2008', 6, 'pasal', 'Pasal 3', NULL, 2, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7355, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7356, 'perka-2-2008', 7, 'lain', 'Penutup', NULL, 2, 'Ditetapkan di Jakarta pada tanggal 3 Juli 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 41 oktober 201 4 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUD BERITA NEGARA REPUBLIK INDONESIA TAHUN 2014 NOMOR 1550');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7356, 'Ditetapkan di Jakarta pada tanggal 3 Juli 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 41 oktober 201 4 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUD BERITA NEGARA REPUBLIK INDONESIA TAHUN 2014 NOMOR 1550', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7357, 'perka-2-2008', 8, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 2 TAHUN 2008 TENTANG MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA DARI MASYARAKAT PROFESIONAL PADA BADAN NASIONAL PENANGGULANGAN BENCANA MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA DARI MASYARAKAT PROFESIONAL PADA BADAN NASIONAL PENANGGULANGAN BENCANA BAB I UMUM 1.1 Latar Belakang Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana memberikan mandat kepada Pemerintah dan Pemerintah Daerah sebagai penanggungjawab dalam penyelenggaraan penanggulangan bencana. Untuk menyelenggarakan penanggulangan bencana tersebut, dibentuk Badan Nasional Penanggulangan Bencana (BNPB) di tingkat Pusat dan Badan Penanggulangan Bencana Daerah (BPBD) di tingkat Daerah.
Sebagai tindak lanjut Peraturan Presiden Nomor 8 Tahun 2008, telah dibentuk BNPB yang terdiri atas Kepala, Unsur Pengarah penanggulangan bencana dan Unsur Pelaksana Penanggulangan Bencana. Untuk melaksanakan ketentuan pasal 58 Peraturan Presiden Nomor 8 Tahun 2008, perlu menetapkan mekanisme pemilihan dan kriterla anggota unsur pengarah penanggulangan bencana dari masyarakat professional.
12 Tujuan Mekanisme ini disusun untuk memberikan acuan/panduan dalam melakukan pem!lihan guna memperoleh anggota unsur pengarah penanggulangan bencana dari masyarakat profesional pada BNPB sesuai dengan amanat peraturan perundang-undangan.
1.3 Dasar Hukum');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7357, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 2 TAHUN 2008 TENTANG MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA DARI MASYARAKAT PROFESIONAL PADA BADAN NASIONAL PENANGGULANGAN BENCANA MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA DARI MASYARAKAT PROFESIONAL PADA BADAN NASIONAL PENANGGULANGAN BENCANA BAB I UMUM 1.1 Latar Belakang Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana memberikan mandat kepada Pemerintah dan Pemerintah Daerah sebagai penanggungjawab dalam penyelenggaraan penanggulangan bencana. Untuk menyelenggarakan penanggulangan bencana tersebut, dibentuk Badan Nasional Penanggulangan Bencana (BNPB) di tingkat Pusat dan Badan Penanggulangan Bencana Daerah (BPBD) di tingkat Daerah.
Sebagai tindak lanjut Peraturan Presiden Nomor 8 Tahun 2008, telah dibentuk BNPB yang terdiri atas Kepala, Unsur Pengarah penanggulangan bencana dan Unsur Pelaksana Penanggulangan Bencana. Untuk melaksanakan ketentuan pasal 58 Peraturan Presiden Nomor 8 Tahun 2008, perlu menetapkan mekanisme pemilihan dan kriterla anggota unsur pengarah penanggulangan bencana dari masyarakat professional.
12 Tujuan Mekanisme ini disusun untuk memberikan acuan/panduan dalam melakukan pem!lihan guna memperoleh anggota unsur pengarah penanggulangan bencana dari masyarakat profesional pada BNPB sesuai dengan amanat peraturan perundang-undangan.
1.3 Dasar Hukum', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7358, 'perka-2-2008', 9, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'a. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
b. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
14 Pengertian
a. Badan Nasional Penanggulangan Bencana, selanjutnya disebut BNPB adalah Lembaga Pemerintah Non Departemen setingkat menteri, berada di bawah dan bertanggungjawab langsung kepada Presiden, yang dibentuk dalam rangka menjalankan tugas dan fungsi penyelenggaraan penanggulangan bencana.
b. Unsur pengarah penanggulangan bencana adalah bagian/unsur BNPB yang bertugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.
c. Masyarakat Profesional adalah lembaga/ organisasi yang beranggotakan para pakar/profesional dan/atau tokoh masyarakat yang memiliki pengetahuan, kemampuan, keahlian dan pengalaman di bidang penanggulangan bencana,.
-
d. Lembaga independen adalah lembaga/organisasi yang mempunyai kemampuan untuk melakukan pemilihan caJon anggota unsur pengarah penanggulangan bencana dan tidak memiliki kepentingan atau keberpihakan terhadap pihak-pihak tertentu dalam pemilihan calon anggota unsur pengarah penanggulangan bencana 1.5 Sistematika Mekanisme ini berisi materi tentang tata cara/prosedur dalam pemilihan anggota unsur pengarah penanggulangan bencana dari masyarakat profesional, sebagai berikut :
1. UMUM
II. UNSUR PENGARAH PENANGGULANGAN BENCANA
III. MEKANISME PEMIUHAN DAN KRITERIA ANGGOTA PENANGGULANGAN BENCANA');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7358, 'a. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
b. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
14 Pengertian
a. Badan Nasional Penanggulangan Bencana, selanjutnya disebut BNPB adalah Lembaga Pemerintah Non Departemen setingkat menteri, berada di bawah dan bertanggungjawab langsung kepada Presiden, yang dibentuk dalam rangka menjalankan tugas dan fungsi penyelenggaraan penanggulangan bencana.
b. Unsur pengarah penanggulangan bencana adalah bagian/unsur BNPB yang bertugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.
c. Masyarakat Profesional adalah lembaga/ organisasi yang beranggotakan para pakar/profesional dan/atau tokoh masyarakat yang memiliki pengetahuan, kemampuan, keahlian dan pengalaman di bidang penanggulangan bencana,.
-
d. Lembaga independen adalah lembaga/organisasi yang mempunyai kemampuan untuk melakukan pemilihan caJon anggota unsur pengarah penanggulangan bencana dan tidak memiliki kepentingan atau keberpihakan terhadap pihak-pihak tertentu dalam pemilihan calon anggota unsur pengarah penanggulangan bencana 1.5 Sistematika Mekanisme ini berisi materi tentang tata cara/prosedur dalam pemilihan anggota unsur pengarah penanggulangan bencana dari masyarakat profesional, sebagai berikut :
1. UMUM
II. UNSUR PENGARAH PENANGGULANGAN BENCANA
III. MEKANISME PEMIUHAN DAN KRITERIA ANGGOTA PENANGGULANGAN BENCANA', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7359, 'perka-2-2008', 10, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'IV. PENGANGKATAN DAN PEMBERHENTIAN ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA
V. PENUTUP BAB II UNSUR PENGARAH PENANGGULANGAN BENCANA Unsur pengarah penanggulangan bencana merupakan bagian dari BNPB yang bersama-sama unsur pelaksana melaksanakan penyelenggaraan penanggulangan bencana.
2.1 Kedudukan, Tugas dan Fungsi
a. Unsur pengarah penanggulangan bencanaberada di bawah dan bertanggungjawab kepada Kepala BNPB.
b. Unsur pengarah penanggulangan bencana mempunyai tugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.
c. Untuk melaksanakan tugas sebagaimana tersebut huruf b, unsur pengarah penanggulangan bencana menyelenggarakan fungsi :
1) perumusan konsep kebijakan penanggulangan bencana nasional, 2) pemantauan, dan 3) evaluasi dalam penyelenggaraan penanggulangan bencana.
22 Keanggotaan
a. Unsur pengarah penanggulangan bencana terdiri dari Ketua dan Anggota.
b. Ketua unsur pengarah penanggulangan bencana dijabat oleh Kepala BNPB.
c. Keanggotaan unsur pengarah penanggulangan bencana berasal dari lembaga pemerintah dan masyarakat profesional. aa 31
d. Anggota unsur pengarah penanggulangan bencana berjumlah 19 (sembilan belas) anggota, terdiri dari :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7359, 'IV. PENGANGKATAN DAN PEMBERHENTIAN ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA
V. PENUTUP BAB II UNSUR PENGARAH PENANGGULANGAN BENCANA Unsur pengarah penanggulangan bencana merupakan bagian dari BNPB yang bersama-sama unsur pelaksana melaksanakan penyelenggaraan penanggulangan bencana.
2.1 Kedudukan, Tugas dan Fungsi
a. Unsur pengarah penanggulangan bencanaberada di bawah dan bertanggungjawab kepada Kepala BNPB.
b. Unsur pengarah penanggulangan bencana mempunyai tugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.
c. Untuk melaksanakan tugas sebagaimana tersebut huruf b, unsur pengarah penanggulangan bencana menyelenggarakan fungsi :
1) perumusan konsep kebijakan penanggulangan bencana nasional, 2) pemantauan, dan 3) evaluasi dalam penyelenggaraan penanggulangan bencana.
22 Keanggotaan
a. Unsur pengarah penanggulangan bencana terdiri dari Ketua dan Anggota.
b. Ketua unsur pengarah penanggulangan bencana dijabat oleh Kepala BNPB.
c. Keanggotaan unsur pengarah penanggulangan bencana berasal dari lembaga pemerintah dan masyarakat profesional. aa 31
d. Anggota unsur pengarah penanggulangan bencana berjumlah 19 (sembilan belas) anggota, terdiri dari :', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7360, 'perka-2-2008', 11, 'lampiran', 'Lampiran hal. 5', NULL, 5, '1) 10 (sepuluh) anggota berasal dari pejabat eselon I lembaga pemerintah atau yang setingkat yang diusulkan oleh Pimpinan Lembaga Pemerintah, yang mewakili : a) Kementerian Koordinator Bidang Kesejahteraan Rakyat b) Departemen Dalam Negeri c) Departemen Sosial d) Departemen Pekerjaan Umum ec) Departemen Kesehatan f) Departemen Keuangan g) Departemen Perhubungan h) Departemen Energi dan Sumber Daya Mineral i) Kepolisian Negara Republik Indonesia j) Tentara Nasional Indonesia 2) 9 (sembilan) anggota dari masyarakat profesional yang berasal dari pakar/profesional dan/atau tokoh masyarakat BAB III MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGUIANGAN BENCANA Mekanisme Pemilihan Pemilihan anggota unsur pengarah penanggulangan bencana dilaksanakan melalui mekanisme sebagai berikut:
a. Unsur pengarah penanggulangan bencana dari lembaga pemerintah Pemilihan anggota unsur pengarah penanggulangan bencana dari lembaga pemerintah dilakukan sesuai dengan ketentuan peraturan perundang- undangan yang berlaku.
b. Unsur pengarah penanggulangan bencana dari masyarakat professional, 1) Pemilihan calon anggota unsur pengarah penangguJangan bencana dari masyarakat profesional dilakukan dengan memberikan kesempatan seluas-luasnya kepada masyarakat dengan diumumkan melalui media.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7360, '1) 10 (sepuluh) anggota berasal dari pejabat eselon I lembaga pemerintah atau yang setingkat yang diusulkan oleh Pimpinan Lembaga Pemerintah, yang mewakili : a) Kementerian Koordinator Bidang Kesejahteraan Rakyat b) Departemen Dalam Negeri c) Departemen Sosial d) Departemen Pekerjaan Umum ec) Departemen Kesehatan f) Departemen Keuangan g) Departemen Perhubungan h) Departemen Energi dan Sumber Daya Mineral i) Kepolisian Negara Republik Indonesia j) Tentara Nasional Indonesia 2) 9 (sembilan) anggota dari masyarakat profesional yang berasal dari pakar/profesional dan/atau tokoh masyarakat BAB III MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGUIANGAN BENCANA Mekanisme Pemilihan Pemilihan anggota unsur pengarah penanggulangan bencana dilaksanakan melalui mekanisme sebagai berikut:
a. Unsur pengarah penanggulangan bencana dari lembaga pemerintah Pemilihan anggota unsur pengarah penanggulangan bencana dari lembaga pemerintah dilakukan sesuai dengan ketentuan peraturan perundang- undangan yang berlaku.
b. Unsur pengarah penanggulangan bencana dari masyarakat professional, 1) Pemilihan calon anggota unsur pengarah penangguJangan bencana dari masyarakat profesional dilakukan dengan memberikan kesempatan seluas-luasnya kepada masyarakat dengan diumumkan melalui media.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7361, 'perka-2-2008', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, '2) Pemilihan calon anggota unsur pengarah penangguiangan bencana sebagaimana dimaksud pada butir 1) dilaksanakan oleh lembaga independen yang mempunyai tugas menerima pendaftaran, meJaksanakan penjaringan, seleksi, dan menyampaikan hasil pemilihan kepada Kepala BNPB.
3) Lembaga independen sebagaimana dimaksud butir 2) ditunjuk/ ditetapkan oleh Kepala BNPB.
4) Kepala BNPB mengusulkan 18 (delapan belas) calon anggota unsur pengarah penanggulangan bencana dan masyarakat profesional hasH pemilihan kepada Presiden atau 2 (dua) kali lipat secara proporsional dari jumlah anggota Unsur pengarah penanggulangan bencana dari masyarakat profesional untuk dilakukan uji kepatutan dan uji kelayakan oleh DPR-RI.
5) Calon anggota unsur pengarah penanggulangan bencana yang dinyatakan lulus uji kepatutan dan uji kelayakan disampaikan oleh DPR- RI kepada Presiden untuk ditetapkan sebagai anggota unsur pengarah penanggulangan bencana secara definitif. -a 3.2 41 4.2.
6) BNPB mengumumkan kepada masyarakat luas hasil uji kepatutan dan uji kelayakan melalui media.
Kriteria Calon anggota unsur pengarah penanggulangan bencana dari masyarakat profesional harus memenuhi kriteria/persyaratan sebagai berikut:
a. Warga Negara Indonesia.
b. Sehatjasmani dan rohani.
c. Berkelakuan baik
d. Usia serendah-rendahnya 30 (tiga puluh) tahun dan setinggi-tingginya 65 (enam puluh lima ) tahun.
e. Memiliki wawasan kebangsaan. f Memiliki pengetahuan akademis dan pengalaman dalam penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7361, '2) Pemilihan calon anggota unsur pengarah penangguiangan bencana sebagaimana dimaksud pada butir 1) dilaksanakan oleh lembaga independen yang mempunyai tugas menerima pendaftaran, meJaksanakan penjaringan, seleksi, dan menyampaikan hasil pemilihan kepada Kepala BNPB.
3) Lembaga independen sebagaimana dimaksud butir 2) ditunjuk/ ditetapkan oleh Kepala BNPB.
4) Kepala BNPB mengusulkan 18 (delapan belas) calon anggota unsur pengarah penanggulangan bencana dan masyarakat profesional hasH pemilihan kepada Presiden atau 2 (dua) kali lipat secara proporsional dari jumlah anggota Unsur pengarah penanggulangan bencana dari masyarakat profesional untuk dilakukan uji kepatutan dan uji kelayakan oleh DPR-RI.
5) Calon anggota unsur pengarah penanggulangan bencana yang dinyatakan lulus uji kepatutan dan uji kelayakan disampaikan oleh DPR- RI kepada Presiden untuk ditetapkan sebagai anggota unsur pengarah penanggulangan bencana secara definitif. -a 3.2 41 4.2.
6) BNPB mengumumkan kepada masyarakat luas hasil uji kepatutan dan uji kelayakan melalui media.
Kriteria Calon anggota unsur pengarah penanggulangan bencana dari masyarakat profesional harus memenuhi kriteria/persyaratan sebagai berikut:
a. Warga Negara Indonesia.
b. Sehatjasmani dan rohani.
c. Berkelakuan baik
d. Usia serendah-rendahnya 30 (tiga puluh) tahun dan setinggi-tingginya 65 (enam puluh lima ) tahun.
e. Memiliki wawasan kebangsaan. f Memiliki pengetahuan akademis dan pengalaman dalam penanggulangan bencana.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7362, 'perka-2-2008', 13, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'g. Berpendidikan serendah-rendahnya Sarjana (S1).
h. Memiliki integritas tinggi. ii Non-partisan.
BAB IV PENGANGKATAN DAN PEMBERHENTIAN ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA Pengangkatan
a. Pengangkatan anggota unsur pengarah penanggulangan bencana ditetapkan oleh Presiden.
b. Anggota unsur pengarah penanggulangan bencana diangkat untuk masajabatan selama 5 (lima) tahun.
c. Tata cara/prosedur pengangkatan anggota unsur pengarah penanggulangan bencana dari lembaga pemerintah dan masyarakat profesional dilakukan sesuai dengan ketentuan peraturan perundang-undangan.
Pemberhentian dan Penggantian Antar Waktu
a. Pemberhentian anggota unsur pengarah penanggulangan bencana dari masyarakat profesional dilakukan setelah berkonsultasi dan mendapatkan persetujuan dari DPR-RI
b. Pergantlan antar waktu anggota unsur pengarah penangguJangan bencana dilakukan karena alasan sebagai berikut :
1) meninggal dunia.
2) mengundurkan diri sebagai anggota unsur pengarah penanggulangan bencana atas kemauan sendiri.
3) tidak dapat memenuhi kewajiban sebagai anggota unsur pengarah penanggulangan bencana.
c. Calon anggota pengganti berasal dari calon anggota yang telah mengikuti uji kepatutan dan uji kelayakan dan mewakili unsur/organisasi dari anggota yang digantikan. nk BAB V PENUTUP Mekanisme ini mulai berlaku pada tanggal ditetapkan.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
SYAMSUL MAARIF 2G');
