INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7367, 'perka-2-2009', 4, 'pasal', 'Pasal 1', NULL, 2, 'Tata Kerja dalam peraturan ini merupakan panduan/acuan bagi Unsur Pengarah Penanggulangan Bencana dalam menjalankan tugas dan fungsinya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7367, 'Tata Kerja dalam peraturan ini merupakan panduan/acuan bagi Unsur Pengarah Penanggulangan Bencana dalam menjalankan tugas dan fungsinya.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2009 tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana');
