INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7370, 'perka-2-2009', 7, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 29 Juni 2009 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 14 Oktober 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1551 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7370, 'Ditetapkan di Jakarta pada tanggal 29 Juni 2009 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 14 Oktober 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1551 4', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2009 tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7371, 'perka-2-2009', 8, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 2 TAHUN 2009 TENTANG TATA KERJA UNSUR PENGARAH PENANGGULANGAN BENCANA BAB I UMUM 1.1 Latar Belakang Undang-Undang Nomor 24 Tahun 2007 Bencana memberikan mandate kepada Pemerintah sebagai penanggungjawab dalam penyelenggaraan tentang Penanggulangan dan Pemerintah Daerah penanggulangan bencana. Untuk menyelenggarakan penanggulangan bencana tersebut dibentuk Badan Nasional Penanggulangan Bencana yang selanjutnya disebut BNPB di tingkat Pusat dan Badan Penanggulangan Bencana Daerah yang selanjutnya disebut BPBD di tingkat daerah Sebagai tindak lanjut telah ditetapkan Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana (BNPB), susunan organisasi terdiri atas Kepala, Unsur Pengarah Penanggulangan Bencana dan Unsur Pelaksana Penanggulangan Bencana.
Unsur Pengarah Penanggulangan Bencana mempunyai tugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana_ Dalam melaksanakan tugas tersebut, unsur pengarah penanggulangan bencana menyelenggarakan fungsi perumusan konsep kebijakan penanggulangan bencana nasional, pemantauan dan evaluasi dalam penyelenggaraan penanggulangan bencana.
Untuk memberikan pedoman bagi Unsur Pengarah Penanggulangan Bencana dalam menjalankan tugas dan fungsinya, perlu ditetapkan Peraturan Kepala BNPB tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7371, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 2 TAHUN 2009 TENTANG TATA KERJA UNSUR PENGARAH PENANGGULANGAN BENCANA BAB I UMUM 1.1 Latar Belakang Undang-Undang Nomor 24 Tahun 2007 Bencana memberikan mandate kepada Pemerintah sebagai penanggungjawab dalam penyelenggaraan tentang Penanggulangan dan Pemerintah Daerah penanggulangan bencana. Untuk menyelenggarakan penanggulangan bencana tersebut dibentuk Badan Nasional Penanggulangan Bencana yang selanjutnya disebut BNPB di tingkat Pusat dan Badan Penanggulangan Bencana Daerah yang selanjutnya disebut BPBD di tingkat daerah Sebagai tindak lanjut telah ditetapkan Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana (BNPB), susunan organisasi terdiri atas Kepala, Unsur Pengarah Penanggulangan Bencana dan Unsur Pelaksana Penanggulangan Bencana.
Unsur Pengarah Penanggulangan Bencana mempunyai tugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana_ Dalam melaksanakan tugas tersebut, unsur pengarah penanggulangan bencana menyelenggarakan fungsi perumusan konsep kebijakan penanggulangan bencana nasional, pemantauan dan evaluasi dalam penyelenggaraan penanggulangan bencana.
Untuk memberikan pedoman bagi Unsur Pengarah Penanggulangan Bencana dalam menjalankan tugas dan fungsinya, perlu ditetapkan Peraturan Kepala BNPB tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2009 tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7372, 'perka-2-2009', 9, 'lampiran', 'Lampiran hal. 4', NULL, 4, '1.2 Tujuan Pedoman ini bertujuan untuk memberikan acuan bagi Unsur Pengarah Penanggulangan Bencana dalam menjalankan tugas dan fungsinya.
5 2014, No.1551 1.3 Dasar Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan lembaran Negara Republik Indonesia Nomor 4828);
3. Peraturan Pemerintah Bencana Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
4. Peraturan Pemerlntah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga lnternasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
5. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
6. Keputusan Presiden Nomor 29/M Tahun 2008 tentang Pengangkatan Kepala Badan Nasional Penanggulangan Bencana;
7. Keputusan Presiden Nomor 24/P Tahun 2009 tentang Pengangkatan Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional.
1.4 Pengertian');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7372, '1.2 Tujuan Pedoman ini bertujuan untuk memberikan acuan bagi Unsur Pengarah Penanggulangan Bencana dalam menjalankan tugas dan fungsinya.
5 2014, No.1551 1.3 Dasar Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan lembaran Negara Republik Indonesia Nomor 4828);
3. Peraturan Pemerintah Bencana Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
4. Peraturan Pemerlntah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga lnternasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
5. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
6. Keputusan Presiden Nomor 29/M Tahun 2008 tentang Pengangkatan Kepala Badan Nasional Penanggulangan Bencana;
7. Keputusan Presiden Nomor 24/P Tahun 2009 tentang Pengangkatan Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional.
1.4 Pengertian', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2009 tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7373, 'perka-2-2009', 10, 'lampiran', 'Lampiran hal. 5', NULL, 5, '1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan baik oleh faktor alam dan/atau faktor non-alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis
2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, serta kegiatan rehabilitasi dan rekonstruksi
3. Pemerintah Pusat, selanjutnya disebut Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
2014, No.1551 6
4. Pemerintah Daerah adalah Gubernur, Bupati, Walikota, dan perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
5. Badan Nasional Penanggulangan Bencana, selanjutnya disebut BNPB adalah Lembaga Pemerintah Non Departemen, berada di bawah dan bertanggung jawab langsung kepada Presiden yang dibentuk dalam rangka menjalankan tugas dan fungsi penyelenggaraan penanggulangan bencana.
6. Badan Penanggulangan Bencana Daerah, selanjutnya disebut BPBD adalah perangkat daerah yang dibentuk untuk melaksanakan tugas dan fungsi penanggulangan bencana di daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7373, '1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan baik oleh faktor alam dan/atau faktor non-alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis
2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, serta kegiatan rehabilitasi dan rekonstruksi
3. Pemerintah Pusat, selanjutnya disebut Pemerintah adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
2014, No.1551 6
4. Pemerintah Daerah adalah Gubernur, Bupati, Walikota, dan perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.
5. Badan Nasional Penanggulangan Bencana, selanjutnya disebut BNPB adalah Lembaga Pemerintah Non Departemen, berada di bawah dan bertanggung jawab langsung kepada Presiden yang dibentuk dalam rangka menjalankan tugas dan fungsi penyelenggaraan penanggulangan bencana.
6. Badan Penanggulangan Bencana Daerah, selanjutnya disebut BPBD adalah perangkat daerah yang dibentuk untuk melaksanakan tugas dan fungsi penanggulangan bencana di daerah.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2009 tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7374, 'perka-2-2009', 11, 'lampiran', 'Lampiran hal. 6', NULL, 6, '7. Unsur Pengarah Penanggulangan Bencana adalah bagian/unsur BNPB yang bertugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.
8. Masyarakat Profesional adalah lembaga/organisasi yang memilki pengetahuan, kemampuan, keahlian dan pengalaman di bidang penangulangan bencana, yang berasal dari pakar/profesional dan/atau tokoh masyarakat.
1.5 Sistematika Pedoman ini berisi materi tata kerja unsur pengarah penanggulangan bencana yang disusun dalam sistimatika sebagai berikut :
I. UMUM
II. KEDUDUKAN, TUGAS DAN FUNGSI
III. SUSUNAN ORGANISASI
IV. TATA KERJA
V. PEMBIAYAAN
VI. KETENTUAN LAIN•LAIN VII.PENUTUP 7 2014, No.1551 BAB II KEDUDUKAN, TUGAS DAN FUNGSI A. Kedudukan
1. Unsur Pengarah Penanggulangan Bencana berkedudukan berada di bawah dan bertanggungjawab kepada Kepala Badan Nasional Penanggulangan Bencana.
2. Unsur Pengarah Penanggulangan dipimpin Kepala Badan Nasional Penanggulangan Bencana.
B. Tugas dan Fungsi
1. Unsur Pengarah Penanggulangan Bencana mempunyai tugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.
2. Unsur Pengarah Penanggulangan Bencana menyelenggarakan fungsi:
a. perumusan konsep kebijakan penanggulangan bencana;
b. pemantauan; dan
c. evaluasi dalam penyelenggaraan penanggulangan bencana.
BAB Ill SUSUNAN ORGANISASI
1. Susunan Organisasi Unsur Pengarah Penanggulangan Bencana terdiri dari Ketua yang dijabat oleh Kepala BNPB dan 19 (sembilan belas) anggota, yang terdiri dari :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7374, '7. Unsur Pengarah Penanggulangan Bencana adalah bagian/unsur BNPB yang bertugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.
8. Masyarakat Profesional adalah lembaga/organisasi yang memilki pengetahuan, kemampuan, keahlian dan pengalaman di bidang penangulangan bencana, yang berasal dari pakar/profesional dan/atau tokoh masyarakat.
1.5 Sistematika Pedoman ini berisi materi tata kerja unsur pengarah penanggulangan bencana yang disusun dalam sistimatika sebagai berikut :
I. UMUM
II. KEDUDUKAN, TUGAS DAN FUNGSI
III. SUSUNAN ORGANISASI
IV. TATA KERJA
V. PEMBIAYAAN
VI. KETENTUAN LAIN•LAIN VII.PENUTUP 7 2014, No.1551 BAB II KEDUDUKAN, TUGAS DAN FUNGSI A. Kedudukan
1. Unsur Pengarah Penanggulangan Bencana berkedudukan berada di bawah dan bertanggungjawab kepada Kepala Badan Nasional Penanggulangan Bencana.
2. Unsur Pengarah Penanggulangan dipimpin Kepala Badan Nasional Penanggulangan Bencana.
B. Tugas dan Fungsi
1. Unsur Pengarah Penanggulangan Bencana mempunyai tugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.
2. Unsur Pengarah Penanggulangan Bencana menyelenggarakan fungsi:
a. perumusan konsep kebijakan penanggulangan bencana;
b. pemantauan; dan
c. evaluasi dalam penyelenggaraan penanggulangan bencana.
BAB Ill SUSUNAN ORGANISASI
1. Susunan Organisasi Unsur Pengarah Penanggulangan Bencana terdiri dari Ketua yang dijabat oleh Kepala BNPB dan 19 (sembilan belas) anggota, yang terdiri dari :', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2009 tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7375, 'perka-2-2009', 12, 'lampiran', 'Lampiran hal. 7', NULL, 7, 'a. 10 (sepuluh) anggota dari Pejabat Pemerintah Eselon I atau setingkat, yang diusulkan oleh Pimpinan Lembaga Pemerintah; dan
b. 9 (sembilan) anggota dari Masyarakat Profesional.
2. Para Pejabat Pemerintah sebagaimana dimaksud pada butir 1 (a) mewakili:
1. Kementerian Koordinator Bidang Kesejahteraan Rakyat;
2. Departemen Dalam Negeri;
3. Departemen Sosial;
4. Departemen Pekerjaan Umum;
2014, No.1551 8
5. Departemen Kesehatan;
6. Departemen Keuangan;
7. Departemen Perhubungan;
8. Departemen Energi dan Sumberdaya Mineral;
9. Kepolisian Republik Indonesia; dan
10. Tentara Nasional Republik Indonesia.
3. Para anggota dari masyarakat profesional dipilih dan ditetapkan melalui seleksi dan uji kepatutan dari DPR RI.
4. Untuk pengaturan dalam menjalankan tugas dan fungsinya di pilih Ketua Harian oleh anggota unsur pengarah dan bergantian secara periodik.
5. Untuk dukungan teknis administratif dibentuk Sekretariat Unsur Pengarah Penanggulangan Bencana yang memberikan dukungan pelayanan ketata-usahaan, urusan rumah tangga dan perlengkapan.
BAB IV TATA KERJA Dalam menjalankan tugas dan fungsi Unsur Pengarah Penanggulangan Bencana diatur Tata Kerja sebagai berikut :
1. Dalam perumusan kebijakan penanggulangan bencana, Unsur Pengarah mengusulkan dan mengajukan konsep kepada Kepala BNPB untuk ditetapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7375, 'a. 10 (sepuluh) anggota dari Pejabat Pemerintah Eselon I atau setingkat, yang diusulkan oleh Pimpinan Lembaga Pemerintah; dan
b. 9 (sembilan) anggota dari Masyarakat Profesional.
2. Para Pejabat Pemerintah sebagaimana dimaksud pada butir 1 (a) mewakili:
1. Kementerian Koordinator Bidang Kesejahteraan Rakyat;
2. Departemen Dalam Negeri;
3. Departemen Sosial;
4. Departemen Pekerjaan Umum;
2014, No.1551 8
5. Departemen Kesehatan;
6. Departemen Keuangan;
7. Departemen Perhubungan;
8. Departemen Energi dan Sumberdaya Mineral;
9. Kepolisian Republik Indonesia; dan
10. Tentara Nasional Republik Indonesia.
3. Para anggota dari masyarakat profesional dipilih dan ditetapkan melalui seleksi dan uji kepatutan dari DPR RI.
4. Untuk pengaturan dalam menjalankan tugas dan fungsinya di pilih Ketua Harian oleh anggota unsur pengarah dan bergantian secara periodik.
5. Untuk dukungan teknis administratif dibentuk Sekretariat Unsur Pengarah Penanggulangan Bencana yang memberikan dukungan pelayanan ketata-usahaan, urusan rumah tangga dan perlengkapan.
BAB IV TATA KERJA Dalam menjalankan tugas dan fungsi Unsur Pengarah Penanggulangan Bencana diatur Tata Kerja sebagai berikut :
1. Dalam perumusan kebijakan penanggulangan bencana, Unsur Pengarah mengusulkan dan mengajukan konsep kepada Kepala BNPB untuk ditetapkan.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2009 tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7376, 'perka-2-2009', 13, 'lampiran', 'Lampiran hal. 8', NULL, 8, '2. Kebijakan sebagaimana dimaksud pada butir 1 meliputi kebijakan berslfat makro yang antara lain penyusunan rencana penanggulangan bencana, sistim nasional penanggulangan bencana dan kebijakan nasional serta internasional.
3. Unsur Pengarah dapat melakukan kajian dan analisa terhadap konsep usulan kebijakan dari unsur pelaksana penanggulangan bencana.
4. Dalam menjalankan tugas pemantauan dan evaluasi dalam penyelenggaraan penanggulangan bencana, Unsur Pengarah dapat melakukan secara sendirl-sendiri, dan/atau bersama-sama unsur pelaksana penanggulangan bencana.
9 2014, No.1551
5. Sidang rapat
a. Unsur Pengarah melaksanakan sidang/rapat secara berkala minimal 2 (dua) bulan sekali dan/atau sewaktu-waktu sesuai kebutuhan yang ditetapkan oleh kesepakatan dengan para anggota.
b. Unsur Pengarah dapat mengundang lembaga pemerintah baik pusat maupun daerah, lembaga usaha, lembaga internasional dan atau pihak lain yang dianggap perlu dalam sidang anggota unsur pengarah penanggulangan bencana.
6. Konsultasi dengan Unsur Pelaksana Penanggulangan Bencana.
a. Unsur Pengarah Penanggulangan Bencana dapat melakukan konsultasi secara periodic dan/atau sewaktu-waktu sesuai dengan kebutuhan.
b. Konsultasi dapat dilakukan melalui sidang/rapat dan/atau secara langsung atau diskusi.
BAB V PEMBIAYAAN Pembiayaan untuk mendukung pelaksanaan tugas dan fungsi Unsur Pengarah penanggulangan bencana dibebankan pada DIPA BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7376, '2. Kebijakan sebagaimana dimaksud pada butir 1 meliputi kebijakan berslfat makro yang antara lain penyusunan rencana penanggulangan bencana, sistim nasional penanggulangan bencana dan kebijakan nasional serta internasional.
3. Unsur Pengarah dapat melakukan kajian dan analisa terhadap konsep usulan kebijakan dari unsur pelaksana penanggulangan bencana.
4. Dalam menjalankan tugas pemantauan dan evaluasi dalam penyelenggaraan penanggulangan bencana, Unsur Pengarah dapat melakukan secara sendirl-sendiri, dan/atau bersama-sama unsur pelaksana penanggulangan bencana.
9 2014, No.1551
5. Sidang rapat
a. Unsur Pengarah melaksanakan sidang/rapat secara berkala minimal 2 (dua) bulan sekali dan/atau sewaktu-waktu sesuai kebutuhan yang ditetapkan oleh kesepakatan dengan para anggota.
b. Unsur Pengarah dapat mengundang lembaga pemerintah baik pusat maupun daerah, lembaga usaha, lembaga internasional dan atau pihak lain yang dianggap perlu dalam sidang anggota unsur pengarah penanggulangan bencana.
6. Konsultasi dengan Unsur Pelaksana Penanggulangan Bencana.
a. Unsur Pengarah Penanggulangan Bencana dapat melakukan konsultasi secara periodic dan/atau sewaktu-waktu sesuai dengan kebutuhan.
b. Konsultasi dapat dilakukan melalui sidang/rapat dan/atau secara langsung atau diskusi.
BAB V PEMBIAYAAN Pembiayaan untuk mendukung pelaksanaan tugas dan fungsi Unsur Pengarah penanggulangan bencana dibebankan pada DIPA BNPB.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2009 tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7377, 'perka-2-2009', 14, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'BAB VI KETENTUAN LAIN-LAIN Penyusunan laporan penyelenggaraan penanggulangan bencana yang dilakukan oleh Unsur Pengarah Penanggulangan Bencana :
1. Laporan pemantauan dan evaluasi penyelenggaraan penanggulangan bencana digunakan sebagai masukan dalam menetapkan kebijakan yang akan datang, evaluasi pencapaian kinerja dan review penyelenggaraan penanggulangan bencana.
2. Penyampaian laporan pemantauan dan evaluasi penyelenggaraan penanggulangan bencana dilakukan, sebagai berikut:
a. Dalam keadaan normal dilakukan I (satu) kali dalam setahun yaitu pada setiap akhir tahun, dan dalam kondisi darurat bencana dilakukan setiap saat sesuai dengan kebutuhan, disampaikan kepada Kepala BNPB/Ketua Unsur Pengarah.
2014, No.1551 10
b. Tembusan laporan disampaikan kepada Unsur Pelaksana.
3. Laporan pemantauan penyelenggaraan penanggulangan bencana memuat data/informasi tentang penyelenggaraan penanggulangan bencana pada tahap pra-bencana, saat tanggap darurat, dan pasca-bencana.
BAB VII PENUTUP Peraturan/pedoman yang berkaitan dengan tata kerja ini dapat diubah sesuai dengan kebutuhan atas persetujuan Kepala Badan Nasional Penanggulangan Bencana.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7377, 'BAB VI KETENTUAN LAIN-LAIN Penyusunan laporan penyelenggaraan penanggulangan bencana yang dilakukan oleh Unsur Pengarah Penanggulangan Bencana :
1. Laporan pemantauan dan evaluasi penyelenggaraan penanggulangan bencana digunakan sebagai masukan dalam menetapkan kebijakan yang akan datang, evaluasi pencapaian kinerja dan review penyelenggaraan penanggulangan bencana.
2. Penyampaian laporan pemantauan dan evaluasi penyelenggaraan penanggulangan bencana dilakukan, sebagai berikut:
a. Dalam keadaan normal dilakukan I (satu) kali dalam setahun yaitu pada setiap akhir tahun, dan dalam kondisi darurat bencana dilakukan setiap saat sesuai dengan kebutuhan, disampaikan kepada Kepala BNPB/Ketua Unsur Pengarah.
2014, No.1551 10
b. Tembusan laporan disampaikan kepada Unsur Pelaksana.
3. Laporan pemantauan penyelenggaraan penanggulangan bencana memuat data/informasi tentang penyelenggaraan penanggulangan bencana pada tahap pra-bencana, saat tanggap darurat, dan pasca-bencana.
BAB VII PENUTUP Peraturan/pedoman yang berkaitan dengan tata kerja ini dapat diubah sesuai dengan kebutuhan atas persetujuan Kepala Badan Nasional Penanggulangan Bencana.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2009 tentang Tata Kerja Unsur Pengarah Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7378, 'perka-2-2011', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2011 tentang Rencana Aksi Rehabilitasi Dan Rekonstuksi Pasca Bencana Banjir Bandang Wasior Kabupaten Teluk Wandoma Provinsi Papua Barat Tahun 2010-2011');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7378, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2011 tentang Rencana Aksi Rehabilitasi Dan Rekonstuksi Pasca Bencana Banjir Bandang Wasior Kabupaten Teluk Wandoma Provinsi Papua Barat Tahun 2010-2011', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2011 tentang Rencana Aksi Rehabilitasi Dan Rekonstuksi Pasca Bencana Banjir Bandang Wasior Kabupaten Teluk Wandoma Provinsi Papua Barat Tahun 2010-2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7379, 'perka-2-2011', 1, 'lain', 'Isi hal. 1', NULL, 1, 'BADAN NASIONAl PENANGGULANGAN BENCANA (BNPB) PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR: 01. TAHUN 2011 TENTANG RENCANA AKSI REHABILITASI DAN REKONSTRUKSI PASCABENCANA BANJIR BANDANG WASIOR KABUPATEN TELUK WONDAMA PROVINSI PAPUA BARAT TAHUN 2010 - 2011 DENGAN RAHMAT TUHAN YANG MAHA ESA KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA f''..1enimbang a. bahwa dalam rangka percepatan pemulihan kehidupan masyarakat dan pembangunan kembali prasarana dan sarana pasca bencana banjir bandang di wilayah Wasior Kabupaten Teluk Wondama Provinsi Papua Barat tanggal 4 Oktober 2010, diperlukan Rencana Aksi Rehabilitasi dan Rekonstruksi;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Rencana Aksi Rehabilitasi dan Rekonstruksi Pascabencana Banjir Bandang Wasior Kabupaten Teluk Wondama Provinsi Papua Barat Tahun 2010 - 2011;
Mengingat 1. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7379, 'BADAN NASIONAl PENANGGULANGAN BENCANA (BNPB) PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR: 01. TAHUN 2011 TENTANG RENCANA AKSI REHABILITASI DAN REKONSTRUKSI PASCABENCANA BANJIR BANDANG WASIOR KABUPATEN TELUK WONDAMA PROVINSI PAPUA BARAT TAHUN 2010 - 2011 DENGAN RAHMAT TUHAN YANG MAHA ESA KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA f''..1enimbang a. bahwa dalam rangka percepatan pemulihan kehidupan masyarakat dan pembangunan kembali prasarana dan sarana pasca bencana banjir bandang di wilayah Wasior Kabupaten Teluk Wondama Provinsi Papua Barat tanggal 4 Oktober 2010, diperlukan Rencana Aksi Rehabilitasi dan Rekonstruksi;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Rencana Aksi Rehabilitasi dan Rekonstruksi Pascabencana Banjir Bandang Wasior Kabupaten Teluk Wondama Provinsi Papua Barat Tahun 2010 - 2011;
Mengingat 1. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);', 'Isi hal. 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2011 tentang Rencana Aksi Rehabilitasi Dan Rekonstuksi Pasca Bencana Banjir Bandang Wasior Kabupaten Teluk Wandoma Provinsi Papua Barat Tahun 2010-2011');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7380, 'perka-2-2011', 2, 'lain', 'Isi hal. 1', NULL, 1, '2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
