MEMUTUSKAN :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7380, '2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
