INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7395, 'Pedoman Penyusutan Arsip di Lingkungan Badan Nasional Penanggulangan Bencana adalah sebagaimana tercantum dalam Lampiran yang merupakan bagian yang tidak terpisahkan dari Peraturan Kepala Badan Nasional Penanggulangan Bencana ini.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2013 tentang Pedoman Penyusutan Arsip di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7396, 'perka-2-2013', 5, 'pasal', 'Pasal 2', NULL, 2, 'Pedoman Penyusutan Arsip di Lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 1 mengatur hal-hal yang bersifat teknis operasional penyusutan arsip di Lingkungan Badan Nasional Penanggulangan Bencana. www.djpp.kemenkumham.go.id 3 2013, No.1173');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7396, 'Pedoman Penyusutan Arsip di Lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 1 mengatur hal-hal yang bersifat teknis operasional penyusutan arsip di Lingkungan Badan Nasional Penanggulangan Bencana. www.djpp.kemenkumham.go.id 3 2013, No.1173', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2013 tentang Pedoman Penyusutan Arsip di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7397, 'perka-2-2013', 6, 'pasal', 'Pasal 3', NULL, 3, 'Penyelenggaraan penyusutan arsip dilaksanakan berasaskan gabungan antara sentralisasi dan desentralisasi, yaitu:
a. Sentralisasi dalam hal:
1. pembakuan sistem;
2. pembinaan dan pengendalian sistem secara menyeluruh; dan
3. penyimpanan arsip inaktif di Pusat Arsip (Record Centre);
b. desentralisasi dalam hal pelaksanaan pengelolaan arsip aktif.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7397, 'Penyelenggaraan penyusutan arsip dilaksanakan berasaskan gabungan antara sentralisasi dan desentralisasi, yaitu:
a. Sentralisasi dalam hal:
1. pembakuan sistem;
2. pembinaan dan pengendalian sistem secara menyeluruh; dan
3. penyimpanan arsip inaktif di Pusat Arsip (Record Centre);
b. desentralisasi dalam hal pelaksanaan pengelolaan arsip aktif.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2013 tentang Pedoman Penyusutan Arsip di Lingkungan Badan Nasional Penanggulangan Bencana');
