INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7417, 'perka-2-2015', 7, 'pasal', 'Pasal 4', 'BAB III KLASIFIKASI ARSIP', 4, 'Ruang lingkup klasifikasi arsip meliputi pembuatan surat masuk, surat keluar dan kegiatan pemberkasan arsip di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7417, 'Ruang lingkup klasifikasi arsip meliputi pembuatan surat masuk, surat keluar dan kegiatan pemberkasan arsip di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2015 tentang Klasifikasi Arsip di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7418, 'perka-2-2015', 8, 'pasal', 'Pasal 5', 'BAB IV PENUTUP', 4, '(1) Klasifikasi arsip terdiri dari:
a. fungsi fasilitatif; dan
b. fungsi substantif.
(2) Fungsi klasifikasi arsip fasilitatif sebagaimana dimaksud pada ayat (1) huruf a adalah fungsi kelompok arsip yang menyangkut kegiatan-kegiatan unsur pembantu pimpinan.
(3) Fungsi klasifikasi arsip substantif sebagaimana dimaksud pada ayat
(1) huruf b adalah fungsi kelompok arsip yang menyangkut kegiatan-kegiatan unsur pelaksana tugas pokok instansi.
Pasal6 Klasifikasi arsip di lingkungan Badan Nasional Penanggulangan Bencana adalah sebagaimana tercantum dalam lampiran Peraturan Kepala Badan ini dan merupakan bagian yang tidak terpisahkan.');
