INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7422, 'perka-2-2015', 12, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 2 TAHUN 2015 TENTANG KLASIFIKASI ARSIP DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA KLASIFIKASI ARSIP DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA FUNGSI FASILITATIF PR. PERENCANAAN
01. Usulan Perencanaan Naskah-naskah yang berkaitan dengan usulan perencanaan program kerja masing-masing unit kerja.
02. Pokok-Pokok Kebijakan dan Strategi Pembangunan 02.01, Rencana Pembangunan Jangka Panjang (RPJP) Naskah-naskah yang berkaitan dengan penyusunan Rencana Pembangunan Jangka Panjang (RPJP).
02.02. Rencana Pembangunan Jangka Menengah (RPJM) Naskah-naskah yang berkaitan dengan Penyusunan Pembangunan Jangka Menengah (RPJM).
02.03. Rencana Strategis Naskah-naskah yang berkaitan dengan penyusunan Rencana Strategis.
03. Rencana Kerja Tahunan 03,01. Rencana Kerja Tahunan BNPB Naskah-naskah yang berkaitan dengan penyusunan rencana kerja tahunan BNPB, Rancangan awal rencana kerja pemerintah, Rencana Kerja Kementerian Lembaga (Renja-KL), Rencana Kerja Tahunan, Musrenbangnas dan Bangpus.
03.02. Penetapan Kontrak Kerja Naskah-naskah yang berkaitan dengan penetapan kontrak kerja.
03.03 Rencana Kerja Pemerintah Naskah-naskah yang berkaitan dengan penyusunan rencana kerja pemerintah.
04. Penyusunan Rencana Anggaran 04.01. Penyusunan Rencana Anggaran BNPB Naskah-naskah yang berkaitan dengan penyusunan rencana anggaran BNPB (RKAKL, DIPA, PO, SAAR).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7422, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 2 TAHUN 2015 TENTANG KLASIFIKASI ARSIP DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA KLASIFIKASI ARSIP DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA FUNGSI FASILITATIF PR. PERENCANAAN
