INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7424, 'perka-2-2015', 14, 'lampiran', 'Lampiran hal. 7', NULL, 7, '01.04, PENGELUARAN ANGGARAN Naskah-naskah yang berkaitan dengan kegiatan penyelenggaraan pelaksanaan anggaran pengeluaran, mulai dari surat permintaan pembayaran (SPP-GU, SPP-LS, SPP, SPP TUP), Surat Kuasa sampai Surat Perintah Membayar (SPM), Surat Perintah Pencairan Dana (SP2D), Juklak DIPA, dan Nota Keuangan Bulanan.
02. PENGELOLAAN PERBENDAHARAAN 02.01. PERBENDAHARAAN Naskah-naskah yang berkaitan dengan kegiatan pengelolaan perbendaharaan yang berupa Surat Keputusan Penunjukan dan Pengangkatan Kuasa Pengguna Anggaran, Pejabat Pembuat Komitmen, Pejabat Penguji dan Penandatanganan SPM dan Bendaharawan Pengeluaran DIPA, Bendaharawan dan atasan langsung Bendaharawan, Bendaharawan Pengeluaran dan Penerimaan, 02.02. KP4/ KEPEGAWAIAN Naskah-naskah yang berkaitan dengan kegiatan pengelolaan perbendaharaan yang berupa Surat KP4 yaitu Surat Keterangan untuk Mendapatkan Tunjangan Keluarga dan Surat Keterangan lainnya.
02.03, PAJAK Naskah-naskah yang berkaitan dengan kegiatan pengelolaan perbendaharaan yang berupa penerimaan dan Surat Setoran Pajak (SPP).
02.04. PENERIMAAN NON PAJAK Naskah-naskah yang berkaitan dengan kegiatan pengelolaan perbendaharaan yang berupa penerimaan dan Penyetoran Non Pajak (PNP) ke kas Negara.
02.05, PENGEMBALIAN BELANJA Naskah-naskah yang berkaitan dengan kegiatan pengelolaan perbendaharaan yang berupa penerimaan dan Penyetoran Non Pajak (PNP) ke kas Negara.');
