INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7425, 'perka-2-2015', 15, 'lampiran', 'Lampiran hal. 8', NULL, 8, '2015, No.1460 8 02.06, BERITA ACARA PEMERIKSAAN KAS Naskah-naskah yang berkaitan dengan kegiatan pengelolaan perbendaharaan yang berupa berita acara pemeriksaan kas.
02.07, VERIFIKASI ANGGARAN Naskah-naskah yang berkaitan dengan kegiatan pengelolaan perbendaharaan yang berkaitan dengan pengujian/penelitian kebenaran pertanggungjawaban pengeluaran disertai dengan penerimaan yang merupakan verifikasi anggaran, 02.08. PEMBUKUAN ANGGARAN Naskah-naskah yang berkaitan dengan kegiatan pengelolaan Anggaran yang berupa Buku Kas Umum (BKU) dan Buku Kas Pembantu (BKP) dan kartu-kartu realisasi anggaran DIPA dan kartu pengawasan realisasi anggaran.
03. PERHITUNGAN ANGGARAN Naskah-naskah yang berkaitan dengan perhitungan anggaran berupa LRA, Neraca dan Catatan Atas Laporan Keuangan (CALK).
04. KETATAUSAHAAN KEUANGAN 04.01. KETERANGAN PENGHASILAN Naskah-naskah yang berkaitan dengan kegiatan ketatausahaan — keuangan yang berupa keterangan penghasilan perorangan.
04.02, SKPP (Surat Keterangan Pemberhentian Pembayaran) Naskah-naskah yang berkaitan dengan kegiatan ketatausahaan keuangan yang berupa SKPP (Surat Keterangan Pemberhentian Pembayaran).
05. LAPORAN KEUANGAN Naskah-naskah yang berkaitan dengan kegiatan penyusunan laporan keuangan bendahara, bendahara pengeluaran pembantu.
06. SISTEM AKUNTANSI INSTANSI 06.01. MANUAL IMPLEMENTASI SISTEM AKUNTANSI INSTANSI Naskah-naskah yang berkaitan dengan kegiatan Sistem Akuntansi Instansi dan Manual Implementasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7425, '2015, No.1460 8 02.06, BERITA ACARA PEMERIKSAAN KAS Naskah-naskah yang berkaitan dengan kegiatan pengelolaan perbendaharaan yang berupa berita acara pemeriksaan kas.
02.07, VERIFIKASI ANGGARAN Naskah-naskah yang berkaitan dengan kegiatan pengelolaan perbendaharaan yang berkaitan dengan pengujian/penelitian kebenaran pertanggungjawaban pengeluaran disertai dengan penerimaan yang merupakan verifikasi anggaran, 02.08. PEMBUKUAN ANGGARAN Naskah-naskah yang berkaitan dengan kegiatan pengelolaan Anggaran yang berupa Buku Kas Umum (BKU) dan Buku Kas Pembantu (BKP) dan kartu-kartu realisasi anggaran DIPA dan kartu pengawasan realisasi anggaran.
03. PERHITUNGAN ANGGARAN Naskah-naskah yang berkaitan dengan perhitungan anggaran berupa LRA, Neraca dan Catatan Atas Laporan Keuangan (CALK).
04. KETATAUSAHAAN KEUANGAN 04.01. KETERANGAN PENGHASILAN Naskah-naskah yang berkaitan dengan kegiatan ketatausahaan — keuangan yang berupa keterangan penghasilan perorangan.
04.02, SKPP (Surat Keterangan Pemberhentian Pembayaran) Naskah-naskah yang berkaitan dengan kegiatan ketatausahaan keuangan yang berupa SKPP (Surat Keterangan Pemberhentian Pembayaran).
05. LAPORAN KEUANGAN Naskah-naskah yang berkaitan dengan kegiatan penyusunan laporan keuangan bendahara, bendahara pengeluaran pembantu.
06. SISTEM AKUNTANSI INSTANSI 06.01. MANUAL IMPLEMENTASI SISTEM AKUNTANSI INSTANSI Naskah-naskah yang berkaitan dengan kegiatan Sistem Akuntansi Instansi dan Manual Implementasi.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2015 tentang Klasifikasi Arsip di Lingkungan Badan Nasional Penanggulangan Bencana');
