INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7429, 'perka-2-2015', 19, 'lampiran', 'Lampiran hal. 10', NULL, 10, '02. KEARSIPAN 02.01, PENGELOLAAN ARSIP AKTIF Naskah-naskah yang berkaitan dengan kegiatan pengelolaan arsip aktif seperti penyimpanan, pemberkasan dan pembuatan daftar arsip, 02.02. PENGELOLAAN ARSIP INAKTIF Naskah-naskah yang berkaitan dengan pengelolaan arsip inaktif seperti kegiatan penyimpanan, pemberkasan, pembuatan daftar arsip dan pembenahan arsip.
02.03. PELAYANAN PEMINJAMAN ARSIP Naskah-naskah yang berkaitan dengan kegiatan peminjaman arsip aktif maupun arsip inaktif.
02.04. DATA KEARSIPAN Naskah-naskah yang berkaitan dengan kegiatan penyimpanan dan pengelolaan data kearsipan bersifat elektronik dan non elektronik.
02.05. PENYUSUTAN ARSIP Naskah-naskah yang berkaitan dengan kegiatan pemindahan arsip, pemusnahan arsip inaktif berdasarkan daftar arsip dan dilengkapi berita acara.
02.06. PEMBINAAN KEARSIPAN Naskah-naskah yang berkaitan dengan kegiatan sosialisasi/penyuluhan — kearsipan, bimbingan — teknis, supervisi, dan monitoring.
02.07. SISTEM INFORMASI PERSURATAN DAN KEARSIPAN Naskah-naskah yang berkaitan dengan kegiatan Sistem Informasi Persuratan/ Kearsipan.
03. PENGGANDAAN Naskah-naskah yang berkaitan dengan kegiatan penggandaan surat atau dokumen.');
