INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7439, 'perka-2-2015', 29, 'lampiran', 'Lampiran hal. 16', NULL, 16, '03. BARANG MILIK NEGARA 03.01, PEMANFAATAN ASET MILIK NEGARA Naskah-naskah yang berkaitan dengan kegiatan inventaris barang milik negara 03.02. LAPORAN BARANG MILIK NEGARA Naskah-naskah yang berkaitan dengan kegiatan laporan barang milik negara, 03.03. HIBAH BARANG Naskah-naskah yang berkaitan dengan kegiatan hibah barang milik BNPB atau barang yang di hibahkan kepada BNPB seperti pengajuan hibah sampai dengan berita acara pemeriksaan barang yang akan di hibahkan, 03.04. PENGHAPUSAN BARANG MILIK NEGARA Naskah-naskah yang berkaitan dengan kegiatan penghampusan barang milik negara baik barang yang hilang atau barang yang dihapuskan karena dihibahkan.
