INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7454, 'perka-2-2016', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2016 tentang Tata Cara Pengelolaan Dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7454, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2016 tentang Tata Cara Pengelolaan Dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara di Lingkungan Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2016 tentang Tata Cara Pengelolaan Dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7455, 'perka-2-2016', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka pelaksanaan kebijakan dan pengelolaan pertanggungjawaban negara, telah diatur dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan atas Beban Anggaran Pendapatan dan Belanja Negara di Lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan atas Beban Anggaran Pendapatan dan Belanja Negara di Lingkungan Badan Nasional Penanggulangan Bencana dalam implementasinya sudah tidak sesuai lagi dengan ketentuan yang berkaitan dengan pengelolaan keuangan negara, sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Tata Cara Pengelolaan dan Pertanggungjawaban Keuangan atas Beban Anggaran Pendapatan dan Belanja Negara di Lingkungan Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7455, 'a. bahwa dalam rangka pelaksanaan kebijakan dan pengelolaan pertanggungjawaban negara, telah diatur dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan atas Beban Anggaran Pendapatan dan Belanja Negara di Lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan atas Beban Anggaran Pendapatan dan Belanja Negara di Lingkungan Badan Nasional Penanggulangan Bencana dalam implementasinya sudah tidak sesuai lagi dengan ketentuan yang berkaitan dengan pengelolaan keuangan negara, sehingga perlu diganti;
