INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7542, 'perka-2-2016', 88, 'pasal', 'Pasal 84', 'BAB VII PERTANGGUNGJAWABAN PELAKSANAAN ANGGARAN; Bagian Ketujuh Laporan Pertanggungjawaban Bendahara', 61, '(1) Rekonsiliasi antara BNPB selaku Unit Akuntansi Pengguna Anggaran (UAPA) dengan Direktorat Akuntansi dan Pelaporan Keuangan Direktorat Jenderal Perbendaharaan selaku Bendahara Umum Negara terhadap kesesuaian Sistem Akuntansi Instansi (SAI) dengan Sistem Akuntansi Pusat (SiAP).
(2) Rekonsiliasi antara SAI dengan SAU meliputi Laporan Realisasi Anggaran yang terdiri Atas :
a. laporan realisasi anggaran belanja;
b. laporan realisasi anggaran pengembalian belanja;
