INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7545, 'perka-2-2016', 91, 'pasal', 'Pasal 87', 'BAB VII PERTANGGUNGJAWABAN PELAKSANAAN ANGGARAN; Bagian Kelima Laporan Realisasi Anggaran', 64, '(1) Dalam penyusunan laporan pertanggungjawaban pelaksanaan APBN, diperlukan data realisasi APBN, arus kas, neraca, dan catatan Atas laporan keuangan.
(2) KPA selaku UAKPA setiap bulan harus melakukan rekonsiliasi data realisasi anggaran dengan Kepala KPPN selaku Kuasa BUN.
(3) Kepala Badan Nasional Penanggulangan Bencana selaku Unit Akuntansi dan Pelaporan Keuangan Pengguna Anggaran (UAPA) setiap semester harus melakukan rekonsiliasi data realisasi anggaran dengan Kepala Direktorat Jenderal Perbendaharaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7545, '(1) Dalam penyusunan laporan pertanggungjawaban pelaksanaan APBN, diperlukan data realisasi APBN, arus kas, neraca, dan catatan Atas laporan keuangan.
(2) KPA selaku UAKPA setiap bulan harus melakukan rekonsiliasi data realisasi anggaran dengan Kepala KPPN selaku Kuasa BUN.
(3) Kepala Badan Nasional Penanggulangan Bencana selaku Unit Akuntansi dan Pelaporan Keuangan Pengguna Anggaran (UAPA) setiap semester harus melakukan rekonsiliasi data realisasi anggaran dengan Kepala Direktorat Jenderal Perbendaharaan.', 'Pasal 87', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2016 tentang Tata Cara Pengelolaan Dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7546, 'perka-2-2016', 92, 'pasal', 'Pasal 88', 'BAB VIII KETENTUAN PENUTUP', 64, '(1) Setiap awal bulan kepala unit kerja menyampaikan Laporan Realisasi Anggaran (LRA) dan Neraca beserta ADK kepada UAKPA.
(2) Bentuk Laporan Realisasi Anggaran dibuat sesuai dengan format tercantum dalam Lampiran XXIV, yang merupakan bagian tidak terpisahkan dari Peraturan Kepala Badan ini.
2016, No.1815 Pasal 87 Pada saat Peraturan Kepala Badan ini mulai berlaku:
a. Peraturan Kepala Badan Nasioal Penanggulagan Bencana Nomor 1 Tahun 2009 tentang Pedoman Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara di Lingkungan Badan Nasional Penanggulangan Bencana; dan
b. Peraturan Kepala Badan Nasioal Penanggulagan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara di Lingkungan Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 300), dicabut dan dinyatakan tidak berlaku.
Pasal 88 Peraturan Kepala Badan ini mulai berlaku pada tanggal diundangkan.
2016, No. 1815 -66- Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
