INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7568, 'perka-2-2016', 114, 'lampiran', 'Lampiran hal. 93', NULL, 93, 'Selanjutnya berdasarkan data tersebut, data transaksi dan Realisasi Saldo PK yang ada di BPP untuk dicocokkan dengan data yang ada pada BP terkait. Setelah rekonsiliasi dilakukan secara bersama-sama dan dengan melakukan proses pencocokan data, didapatkan hasil sebagai berikut:
1. Uang Muka Kerja/Persekot Kerja.
Tidak terdapat perbedaan saldo PK antara BP dengan data BPP.
2. Pertanggung jawaban keuangan/SPJ.
Tidak terdapat perbedaan SPJ antara BP dengan data BPP.
3. Penyetoran UP/TUP.
Tdak terdapat perbedaan Pengembalian Belanja dan setoran lainya antara BP dengan data BPP.
Demikian berita acara ini dibuat untuk dipergunakan sebagaimana mestinya.
