INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7569, 'perka-2-2016', 115, 'lampiran', 'Lampiran hal. 94', NULL, 94, 'Rekonsiliasi dilaksanakan secara bersama-sama dengan melakukan proses pencocokan data dengan hasil sebagai berikut:
