INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7570, 'perka-2-2016', 116, 'lampiran', 'Lampiran hal. 95', NULL, 95, '2016, No.1815 LAMPIRAN XVIII PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 02 TAHUN 2016 TENTANG TATA CARA PENGELOLAAN DAN PERTANGGUNGJAWABAN KEUANGAN ATAS BEBAN ANGGARAN PENDAPATAN DAN BELANJA NEGARA DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BERITA ACARA REKONSILIASI BULAN: ……………… Pada hari ini ….. tanggal ....... bulan ........tahun ........ telah diselenggarakan rekonsiliasi Laporan Realisasi Anggaran dan Neraca periode bulan ….. tahun …… antara Satuan Kerja Badan Nasional Penanggulangan Bencana kode (……) selaku Kuasa Pengguna Anggaran dengan Kantor Pelayanan Perbendaharaan Negara Jakarta VI (175) selaku Kuasa Bendahara Umum.
Kuasa Pengguna Anggaran menyampaikan Laporan Realisasi Anggaran berupa Laporan Realisasi Anggaran Belanja, Laporan Realisasi Anggaran Pengembalian Belanja; Laporan Realisasi Anggaran Pendapatan, Laporan Realisasi Anggaran Pengembalian Pendapatan; dan Neraca sebagai bahan rekonsiliasi periode …... Tahun Anggaran ….. beserta Arsip Data Komuper (ADK).
Selanjutnya Kuasa Bendahara Umum Negara menyediakan data transaksi, Laporan Realisasi Anggaran dan Neraca yang diproses berdasarkan SIstem Akuntansi Pusat (SiAP).
Rekonsiliasi dilaksanakan secara bersama-sama yang hasilnya dituangkan ke dalam Berita Acara Rekonsiliasi (BA) ini dengan hasil sebagai berikut:
No. Uraian SiAP (Rp) SAI (Rp) Selisih (Rp)
1. Pagu Belanja
2. Belanja
3. Pengembalian Belanja
4. Estimasi Pendapatan PNBP
5. Pendapatan PNBP
6. Pengembalian Pendapatan PNBP');
