INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7582, 'perka-2-2017', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN PENYUSUNAN STANDAR OPERASIONAL PROSEDUR DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7582, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN PENYUSUNAN STANDAR OPERASIONAL PROSEDUR DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7583, 'perka-2-2017', 4, 'pasal', 'Pasal 1', NULL, 3, 'Pedoman Penyusunan Standar Operasional Prosedur di Lingkungan Badan Nasional Penanggulangan Bencana yang selanjutnya disebut Pedoman Penyusunan SOP merupakan acuan bagi setiap pimpinan unit kerja di lingkungan Badan Nasional Penanggulangan Bencana dalam menyusun SOP kerja yang efisien, efektif, produktif, dan akuntabel sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7583, 'Pedoman Penyusunan Standar Operasional Prosedur di Lingkungan Badan Nasional Penanggulangan Bencana yang selanjutnya disebut Pedoman Penyusunan SOP merupakan acuan bagi setiap pimpinan unit kerja di lingkungan Badan Nasional Penanggulangan Bencana dalam menyusun SOP kerja yang efisien, efektif, produktif, dan akuntabel sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7584, 'perka-2-2017', 5, 'pasal', 'Pasal 2', NULL, 3, 'Setiap pimpinan unit kerja di lingkungan Badan Nasional Penanggulangan Bencana wajib menyusun SOP sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7584, 'Setiap pimpinan unit kerja di lingkungan Badan Nasional Penanggulangan Bencana wajib menyusun SOP sesuai dengan ketentuan peraturan perundang-undangan.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7585, 'perka-2-2017', 6, 'pasal', 'Pasal 3', NULL, 3, 'Pedoman Penyusunan SOP sebagaimana dimaksud dalam Pasal 1 tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Kepala Badan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7585, 'Pedoman Penyusunan SOP sebagaimana dimaksud dalam Pasal 1 tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Peraturan Kepala Badan ini.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7586, 'perka-2-2017', 7, 'pasal', 'Pasal 4', NULL, 3, 'SOP bersifat dinamis dan dapat dikembangkan sesuai dengan kebutuhan dan perkembangan unit kerja Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7586, 'SOP bersifat dinamis dan dapat dikembangkan sesuai dengan kebutuhan dan perkembangan unit kerja Badan Nasional Penanggulangan Bencana.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7587, 'perka-2-2017', 8, 'pasal', 'Pasal 5', NULL, 3, '(1) SOP disusun dan ditetapkan oleh setiap pimpinan unit eselon 1 atau Kepala Pusat sesuai dengan kewenangannya.
(2) SOP sebagaimana dimaksud pada ayat (1) wajib dilaporkan kepada Kepala Badan Nasional Penanggulangan Bencana melalui Sekretaris Utama.
2017, No.723 -4-
(3) Dalam hal terjadi perubahan terhadap SOP, pimpinan unit eselon 1 atau Kepala Pusat wajib melaporkan perubahan tersebut kepada Kepala Badan Nasional Penanggulangan Bencana melalui Sekretaris Utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7587, '(1) SOP disusun dan ditetapkan oleh setiap pimpinan unit eselon 1 atau Kepala Pusat sesuai dengan kewenangannya.
(2) SOP sebagaimana dimaksud pada ayat (1) wajib dilaporkan kepada Kepala Badan Nasional Penanggulangan Bencana melalui Sekretaris Utama.
2017, No.723 -4-
(3) Dalam hal terjadi perubahan terhadap SOP, pimpinan unit eselon 1 atau Kepala Pusat wajib melaporkan perubahan tersebut kepada Kepala Badan Nasional Penanggulangan Bencana melalui Sekretaris Utama.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7588, 'perka-2-2017', 9, 'pasal', 'Pasal 6', NULL, 4, 'Peraturan Kepala Badan ini mulai berlaku pada tanggal diundangkan.
