INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7589, 'perka-2-2017', 10, 'lain', 'Penutup', NULL, 4, 'Ditetapkan di Jakarta pada tanggal 31 Maret 2017 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 18 Mei 2017 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd WIDODO EKATJAHJANA 2017, No.723');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7589, 'Ditetapkan di Jakarta pada tanggal 31 Maret 2017 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 18 Mei 2017 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd WIDODO EKATJAHJANA 2017, No.723', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7590, 'perka-2-2017', 11, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 02 TAHUN 2017 TENTANG PEDOMAN PENYUSUNAN STANDAR OPERASIONAL PROSEDUR DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA PEDOMAN PENYUSUNAN SOP SISTEMATIKA BAB I PENDAHULUAN A. Latar Belakang B. Tujuan dan Sasaran C. Asas-asas Penyusunan Standar Operasional Prosedur D. Prinsip-prinsip pelaksanaan E. Ruang Lingkup BAB II JENIS DAN FORMAT STANDAR OPERASIONAL PROSEDUR A. Jenis Standar Operasional Prosedur B. Format Standar Operasional Prosedur C. Contoh Format BAB III MEKANISME PENYUSUNAN/PERUBAHAN STANDAR OPERASIONAL PROSEDUR A. Persiapan Penyusunan Standar Operasional Prosedur B. Penilaian Kebutuhan Standar Operasional Prosedur C. Pengembangan Standar Operasional Prosedur D. Penerapan Standar Operasional Prosedur E. Monitoring dan Evaluasi Standar Operasional Prosedur Format Penyusunan Standar Operasional Prosedur F. Contoh Penyusunan Standar Operasional Prosedur BAB IV PENUTUP 2017, No.723 -6- BAB I PENDAHULUAN A. Latar Belakang Salah satu aspek penting dalam rangka mewujudkan birokrasi yang memiliki kriteria efektif, efisien, dan ekonomis adalah dengan menerapkan standar operasional prosedur pada seluruh proses penyelenggaraan administrasi pemerintahan. Standar operasional prosedur adalah serangkaian instruksi tertulis yang dibakukan mengenai berbagai proses penyelenggaraan administrasi pemerintahan, bagaimana dan kapan harus dilakukan, dimana dan oleh siapa dilakukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7590, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 02 TAHUN 2017 TENTANG PEDOMAN PENYUSUNAN STANDAR OPERASIONAL PROSEDUR DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA PEDOMAN PENYUSUNAN SOP SISTEMATIKA BAB I PENDAHULUAN A. Latar Belakang B. Tujuan dan Sasaran C. Asas-asas Penyusunan Standar Operasional Prosedur D. Prinsip-prinsip pelaksanaan E. Ruang Lingkup BAB II JENIS DAN FORMAT STANDAR OPERASIONAL PROSEDUR A. Jenis Standar Operasional Prosedur B. Format Standar Operasional Prosedur C. Contoh Format BAB III MEKANISME PENYUSUNAN/PERUBAHAN STANDAR OPERASIONAL PROSEDUR A. Persiapan Penyusunan Standar Operasional Prosedur B. Penilaian Kebutuhan Standar Operasional Prosedur C. Pengembangan Standar Operasional Prosedur D. Penerapan Standar Operasional Prosedur E. Monitoring dan Evaluasi Standar Operasional Prosedur Format Penyusunan Standar Operasional Prosedur F. Contoh Penyusunan Standar Operasional Prosedur BAB IV PENUTUP 2017, No.723 -6- BAB I PENDAHULUAN A. Latar Belakang Salah satu aspek penting dalam rangka mewujudkan birokrasi yang memiliki kriteria efektif, efisien, dan ekonomis adalah dengan menerapkan standar operasional prosedur pada seluruh proses penyelenggaraan administrasi pemerintahan. Standar operasional prosedur adalah serangkaian instruksi tertulis yang dibakukan mengenai berbagai proses penyelenggaraan administrasi pemerintahan, bagaimana dan kapan harus dilakukan, dimana dan oleh siapa dilakukan.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7591, 'perka-2-2017', 12, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'Dengan adanya Standar Operasional Prosedur yang selanjutnya disingkat SOP, penyelenggaraan administrasi pemerintahan dapat berjalan dengan pasti, berbagai bentuk penyimpangan dapat dihindari, meskipun terjadi penyimpangan maka dapat ditemukan penyebabnya.
Dalam kondisi seperti ini sedikit demi sedikit kualitas pelayanan kepada publik akan menjadi lebih baik.
Selama ini penyelenggaraan administrasi pemerintahan belum berjalan secara efisien dan optimal sehingga masih ditemukan adanya mal administrasi. Dengan memiliki SOP, Badan Nasional Penanggulangan Bencana sebagai institusi yang menyelenggarakan urusan pemerintahan di bidang penaggulangan bencana diharapkan mampu mengadministrasikan kegiatannya secara baik. SOP pada dasarnya merupakan pedoman yang berisi prosedur operasional standar kegiatan yang dijalankan dalam organisasi Badan Nasional Penanggulangan Bencana yang digunakan untuk memastikan bahwa semua keputusan dan tindakan berjalan efektif sehingga membantu Badan Nasional Penanggulangan Bencana dalam mencapai tujuan organisasi.
B. Tujuan dan Sasaran Tujuan disusunnya pedoman penyusunan SOP ini untuk memberikan acuan bagi seluruh unit kerja di lingkungan Badan Nasional Penanggulangan Bencana dalam mengidentifikasi, merumuskan, menyusun, mengembangkan, memonitor serta mengevaluasi SOP sesuai dengan tugas dan fungsi masing-masing, sehingga diharapkan dapat:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7591, 'Dengan adanya Standar Operasional Prosedur yang selanjutnya disingkat SOP, penyelenggaraan administrasi pemerintahan dapat berjalan dengan pasti, berbagai bentuk penyimpangan dapat dihindari, meskipun terjadi penyimpangan maka dapat ditemukan penyebabnya.
Dalam kondisi seperti ini sedikit demi sedikit kualitas pelayanan kepada publik akan menjadi lebih baik.
Selama ini penyelenggaraan administrasi pemerintahan belum berjalan secara efisien dan optimal sehingga masih ditemukan adanya mal administrasi. Dengan memiliki SOP, Badan Nasional Penanggulangan Bencana sebagai institusi yang menyelenggarakan urusan pemerintahan di bidang penaggulangan bencana diharapkan mampu mengadministrasikan kegiatannya secara baik. SOP pada dasarnya merupakan pedoman yang berisi prosedur operasional standar kegiatan yang dijalankan dalam organisasi Badan Nasional Penanggulangan Bencana yang digunakan untuk memastikan bahwa semua keputusan dan tindakan berjalan efektif sehingga membantu Badan Nasional Penanggulangan Bencana dalam mencapai tujuan organisasi.
B. Tujuan dan Sasaran Tujuan disusunnya pedoman penyusunan SOP ini untuk memberikan acuan bagi seluruh unit kerja di lingkungan Badan Nasional Penanggulangan Bencana dalam mengidentifikasi, merumuskan, menyusun, mengembangkan, memonitor serta mengevaluasi SOP sesuai dengan tugas dan fungsi masing-masing, sehingga diharapkan dapat:', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7592, 'perka-2-2017', 13, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'a. menunjang kelancaran dalam proses pelaksanaan tugas dan kemudahan pengendalian di Badan Nasional Penanggulangan 2017, No.723 Bencana;
b. memberikan kepastian dan keseragaman dalam proses pelaksanaan tugas;
c. mempertegas tanggung jawab dalam pelaksanaan tugas bagi pegawai Badan Nasional Penanggulangan Bencana;
d. meningkatkan daya guna dan hasil guna secara berkelanjutan dalam melaksanakan pelayanan di bidang penaggulangan bencana dan tugas umum pemerintahan;
e. memberikan informasi mengenai pelaksanaan tugas yang dilakukan oleh pegawai Badan Nasional Penanggulangan Bencana secara proporsional;
f. memberikan kejelasan dan transparansi kepada pihak terkait mengenai hak dan kewajibannya dalam suatu uraian prosedur di Badan Nasional Penanggulangan Bencana;
g. menekan angka korupsi, kolusi, dan nepotisme; dan
h. memberikan kepastian waktu penyelesaian suatu pekerjaan.
Sasaran yang diharapkan dapat dicapai melalui pedoman ini adalah:
1. setiap unit kerja memiliki SOP nya masing-masing; dan
2. peningkatan kualitas pelayanan kepada masyarakat.
C. Asas Penyusunan SOP
1. Asas Pembakuan SOP disusun berdasarkan tata cara dan bentuk yang telah dibakukan sehingga dapat menjadi acuan yang baku dalam melaksanakan tugas.
2. Asas Pertanggungjawaban SOP dapat dipertanggungjawabkan baik dari sisi isi, bentuk, prosedur, dan standar yang ditetapkan maupun keabsahannya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7592, 'a. menunjang kelancaran dalam proses pelaksanaan tugas dan kemudahan pengendalian di Badan Nasional Penanggulangan 2017, No.723 Bencana;
b. memberikan kepastian dan keseragaman dalam proses pelaksanaan tugas;
c. mempertegas tanggung jawab dalam pelaksanaan tugas bagi pegawai Badan Nasional Penanggulangan Bencana;
d. meningkatkan daya guna dan hasil guna secara berkelanjutan dalam melaksanakan pelayanan di bidang penaggulangan bencana dan tugas umum pemerintahan;
e. memberikan informasi mengenai pelaksanaan tugas yang dilakukan oleh pegawai Badan Nasional Penanggulangan Bencana secara proporsional;
f. memberikan kejelasan dan transparansi kepada pihak terkait mengenai hak dan kewajibannya dalam suatu uraian prosedur di Badan Nasional Penanggulangan Bencana;
g. menekan angka korupsi, kolusi, dan nepotisme; dan
h. memberikan kepastian waktu penyelesaian suatu pekerjaan.
Sasaran yang diharapkan dapat dicapai melalui pedoman ini adalah:
1. setiap unit kerja memiliki SOP nya masing-masing; dan
2. peningkatan kualitas pelayanan kepada masyarakat.
C. Asas Penyusunan SOP
1. Asas Pembakuan SOP disusun berdasarkan tata cara dan bentuk yang telah dibakukan sehingga dapat menjadi acuan yang baku dalam melaksanakan tugas.
2. Asas Pertanggungjawaban SOP dapat dipertanggungjawabkan baik dari sisi isi, bentuk, prosedur, dan standar yang ditetapkan maupun keabsahannya.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7593, 'perka-2-2017', 14, 'lampiran', 'Lampiran hal. 7', NULL, 7, '3. Asas Keterkaitan Bahwa dalam pelaksanaannya SOP senantiasa terkait dengan kegiatan administrasi umum baik secara langsung maupun tidak langsung.
4. Asas Kecepatan dan Kelancaran Sebagai pendukung dalam melaksanakan tugas maka SOP dapat digunakan untuk menjamin terselesaikannya suatu tugas pekerjaan sesuai dengan waktu yang telah ditetapkan, tepat sasaran, menjamin 2017, No.723 -8- kemudahan dan kelancaran secara prosedural.
5. Asas Keamanan SOP harus aman sehingga dapat menjamin kepentingan semua pihak yang terlibat dalam pelaksanaan tugas sesuai dengan apa yang telah ditetapkan sehingga dapat tercipta kenyamanan dalam pelaksanaan tugas.
6. Asas Keterbukaan Adanya SOP dapat menciptakan suatu transparansi dalam pelaksanaan tugas sehingga tidak akan muncul kecurigaan.
D. Prinsip Pelaksanaan
1. Kemudahan SOP harus dibuat secara jelas dan sederhana sehingga mudah dipahami dan diterapkan.
2. Kejelasan SOP harus dapat memberikan kejelasan kapan dan siapa yang harus melaksanakan kegiatan, berapa lama waktu yang dibutuhkan dan sampai dimana tanggung jawab masing-masing pejabat/pegawai.
3. Keterukuran SOP dapat memberikan pedoman yang terukur baik mengenai norma waktu, hasil kerja yang tepat dan akurat, maupun rincian biaya pelayanan dan tata cara pembayaran bila diperlukan adanya biaya pelayanan.
4. Fleksibilitas Bahwa SOP harus mudah dirumuskan dan selalu bisa menyesuaikan dengan kebutuhan dan perkembangan kebijakan yang berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7593, '3. Asas Keterkaitan Bahwa dalam pelaksanaannya SOP senantiasa terkait dengan kegiatan administrasi umum baik secara langsung maupun tidak langsung.
4. Asas Kecepatan dan Kelancaran Sebagai pendukung dalam melaksanakan tugas maka SOP dapat digunakan untuk menjamin terselesaikannya suatu tugas pekerjaan sesuai dengan waktu yang telah ditetapkan, tepat sasaran, menjamin 2017, No.723 -8- kemudahan dan kelancaran secara prosedural.
5. Asas Keamanan SOP harus aman sehingga dapat menjamin kepentingan semua pihak yang terlibat dalam pelaksanaan tugas sesuai dengan apa yang telah ditetapkan sehingga dapat tercipta kenyamanan dalam pelaksanaan tugas.
6. Asas Keterbukaan Adanya SOP dapat menciptakan suatu transparansi dalam pelaksanaan tugas sehingga tidak akan muncul kecurigaan.
D. Prinsip Pelaksanaan
1. Kemudahan SOP harus dibuat secara jelas dan sederhana sehingga mudah dipahami dan diterapkan.
2. Kejelasan SOP harus dapat memberikan kejelasan kapan dan siapa yang harus melaksanakan kegiatan, berapa lama waktu yang dibutuhkan dan sampai dimana tanggung jawab masing-masing pejabat/pegawai.
3. Keterukuran SOP dapat memberikan pedoman yang terukur baik mengenai norma waktu, hasil kerja yang tepat dan akurat, maupun rincian biaya pelayanan dan tata cara pembayaran bila diperlukan adanya biaya pelayanan.
4. Fleksibilitas Bahwa SOP harus mudah dirumuskan dan selalu bisa menyesuaikan dengan kebutuhan dan perkembangan kebijakan yang berlaku.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7594, 'perka-2-2017', 15, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'E. Ruang Lingkup Ruang lingkup SOP meliputi berbagai prosedur pelaksanaan kegiatan tugas pokok dan fungsi atau pemberian pelayanan baik internal maupun eksternal Badan Nasional Penanggulangan Bencana yang dilakukan oleh unit kerja di Badan Nasional Penanggulangan Bencana.
2017, No.723 BAB II JENIS DAN FORMAT SOP A. Jenis SOP Jenis SOP dibedakan ke dalam dua jenis, yaitu:
1. SOP teknis SOP teknis yaitu SOP yang sangat rinci dan bersifat teknis, pada umumnya disusun untuk berbagai kegiatan teknis. Dalam penyelenggaraan kegiatan SOP teknis dapat digunakan pada tahap prabencana, pada saat tanggap darurat dan pascabencana. Dalam administrasi pemerintahan SOP teknis dapat digunakan pada bidang pemeliharaan sarana dan prasarana, kearsipan, pemeriksaan keuangan, korespondensi, pelayanan kepada masyarakat, dan kepegawaian.
2. SOP administratif SOP administratif yaitu SOP yang diperuntukkan bagi jenis pekerjaan yang bersifat administratif. Dalam pemerintahan mikro, SOP administratif dapat digunakan untuk proses administrasi dalam operasional seluruh instansi pemerintah, dari level unit organisasi paling kecil sampai pada organisasi menyeluruh dalam menjalankan tugas pokok dan fungsinya. Sedangkan dalam pemerintahan makro, SOP administratif dapat digunakan untuk proses perencanaan, penganggaran, atau secara garis besar proses dalam siklus penyelenggaraan administrasi pemerintahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7594, 'E. Ruang Lingkup Ruang lingkup SOP meliputi berbagai prosedur pelaksanaan kegiatan tugas pokok dan fungsi atau pemberian pelayanan baik internal maupun eksternal Badan Nasional Penanggulangan Bencana yang dilakukan oleh unit kerja di Badan Nasional Penanggulangan Bencana.
2017, No.723 BAB II JENIS DAN FORMAT SOP A. Jenis SOP Jenis SOP dibedakan ke dalam dua jenis, yaitu:
1. SOP teknis SOP teknis yaitu SOP yang sangat rinci dan bersifat teknis, pada umumnya disusun untuk berbagai kegiatan teknis. Dalam penyelenggaraan kegiatan SOP teknis dapat digunakan pada tahap prabencana, pada saat tanggap darurat dan pascabencana. Dalam administrasi pemerintahan SOP teknis dapat digunakan pada bidang pemeliharaan sarana dan prasarana, kearsipan, pemeriksaan keuangan, korespondensi, pelayanan kepada masyarakat, dan kepegawaian.
2. SOP administratif SOP administratif yaitu SOP yang diperuntukkan bagi jenis pekerjaan yang bersifat administratif. Dalam pemerintahan mikro, SOP administratif dapat digunakan untuk proses administrasi dalam operasional seluruh instansi pemerintah, dari level unit organisasi paling kecil sampai pada organisasi menyeluruh dalam menjalankan tugas pokok dan fungsinya. Sedangkan dalam pemerintahan makro, SOP administratif dapat digunakan untuk proses perencanaan, penganggaran, atau secara garis besar proses dalam siklus penyelenggaraan administrasi pemerintahan.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7595, 'perka-2-2017', 16, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'B. Format SOP Format SOP berbentuk Diagram Alir (Flowcharts). Flowcharts merupakan format yang biasa digunakan jika dalam SOP tersebut diperlukan pengambilan keputusan yang banyak (kompleks) dan membutuhkan jawaban “ya” atau “tidak” yang akan mempengaruhi sub langkah berikutnya. Format ini juga menyediakan mekanisme yang mudah untuk diikuti dan dilaksanakan oleh para pegawai melalui serangkaian langkah sebagai hasil dari keputusan yang telah diambil.
C. Penggunaan Simbol SOP Dalam Pedoman Penyusunan SOP di Badan Nasional Penanggulangan Bencana, beberapa simbol umum digunakan dalam 2017, No.723 -10- menggambarkan proses suatu kegiatan yang dilaksanakan. Simbol-simbol tersebut sebagai berikut:
Simbol Arti Kegiatan awal atau akhir dari prosedur Kegiatan prosedur Pengambilan keputusan Perpindahan halaman Garis alur prosedur D. Penomoran SOP Susunan penomoran pada SOP sebagai berikut:
1. Nomor naskah (nomor urut SOP dalam satu tahun di Badan Nasional Penanggulangan Bencana);
2. Kode unit kerja penyusun SOP;
3. Nomor urut SOP di unit kerja; dan
4. Tahun terbit.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7595, 'B. Format SOP Format SOP berbentuk Diagram Alir (Flowcharts). Flowcharts merupakan format yang biasa digunakan jika dalam SOP tersebut diperlukan pengambilan keputusan yang banyak (kompleks) dan membutuhkan jawaban “ya” atau “tidak” yang akan mempengaruhi sub langkah berikutnya. Format ini juga menyediakan mekanisme yang mudah untuk diikuti dan dilaksanakan oleh para pegawai melalui serangkaian langkah sebagai hasil dari keputusan yang telah diambil.
C. Penggunaan Simbol SOP Dalam Pedoman Penyusunan SOP di Badan Nasional Penanggulangan Bencana, beberapa simbol umum digunakan dalam 2017, No.723 -10- menggambarkan proses suatu kegiatan yang dilaksanakan. Simbol-simbol tersebut sebagai berikut:
Simbol Arti Kegiatan awal atau akhir dari prosedur Kegiatan prosedur Pengambilan keputusan Perpindahan halaman Garis alur prosedur D. Penomoran SOP Susunan penomoran pada SOP sebagai berikut:
1. Nomor naskah (nomor urut SOP dalam satu tahun di Badan Nasional Penanggulangan Bencana);
2. Kode unit kerja penyusun SOP;
3. Nomor urut SOP di unit kerja; dan
4. Tahun terbit.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7596, 'perka-2-2017', 17, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'Contoh: SOP Nomor 003/SU.010/2009 1 2 3 4 BAB III MEKANISME PENYUSUNAN SOP A. Persiapan Penyusunan SOP Perencanaan penyusunan SOP dapat dilaksanakan dengan membentuk tim yang secara khusus menanganinya. Tim penyusunan SOP dibentuk dengan anggota dari unit kerja yang secara fungsional menangani ketatalaksanaan internal unit kerja. Unit kerja dapat 2017, No.723 melibatkan tenaga yang kompeten sehingga bisa menghasilkan SOP yang optimal.
Tim penyusunan SOP bertugas melakukan identifikasi kebutuhan, mengumpulkan data, melakukan analisis prosedur, melakukan pengembangan, melakukan uji coba, melakukan sosialisasi, mengawal penerapan, memonitor dan melakukan evaluasi, melakukan penyempurnaan, menyajikan hasil pengembangan kepada pimpinan unit kerja, dan tugas lainnya.
B. Penilaian Kebutuhan SOP Penilaian kebutuhan adalah proses awal penyusunan SOP yang dilakukan untuk mengidentifikasi kebutuhan SOP yang akan disusun.
Bagi unit kerja yang sudah memiliki SOP, maka tahapan ini merupakan tahapan untuk melihat kembali SOP yang sudah dimilikinya dan mengidentifikasi perubahan yang diperlukan. Bagi unit kerja yang sama sekali belum memiliki SOP, maka proses ini merupakan proses identifikasi SOP yang dibutuhkan.
1. Tujuan penilaian kebutuhan.
Penilaian kebutuhan SOP bertujuan untuk mengetahui tingkat kebutuhan suatu unit kerja dalam mengembangkan SOP nya.
Penilaian kebutuhan akan sangat bermanfaat dalam menentukan ruang lingkup, jenis, dan jumlah SOP yang dibutuhkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7596, 'Contoh: SOP Nomor 003/SU.010/2009 1 2 3 4 BAB III MEKANISME PENYUSUNAN SOP A. Persiapan Penyusunan SOP Perencanaan penyusunan SOP dapat dilaksanakan dengan membentuk tim yang secara khusus menanganinya. Tim penyusunan SOP dibentuk dengan anggota dari unit kerja yang secara fungsional menangani ketatalaksanaan internal unit kerja. Unit kerja dapat 2017, No.723 melibatkan tenaga yang kompeten sehingga bisa menghasilkan SOP yang optimal.
Tim penyusunan SOP bertugas melakukan identifikasi kebutuhan, mengumpulkan data, melakukan analisis prosedur, melakukan pengembangan, melakukan uji coba, melakukan sosialisasi, mengawal penerapan, memonitor dan melakukan evaluasi, melakukan penyempurnaan, menyajikan hasil pengembangan kepada pimpinan unit kerja, dan tugas lainnya.
B. Penilaian Kebutuhan SOP Penilaian kebutuhan adalah proses awal penyusunan SOP yang dilakukan untuk mengidentifikasi kebutuhan SOP yang akan disusun.
Bagi unit kerja yang sudah memiliki SOP, maka tahapan ini merupakan tahapan untuk melihat kembali SOP yang sudah dimilikinya dan mengidentifikasi perubahan yang diperlukan. Bagi unit kerja yang sama sekali belum memiliki SOP, maka proses ini merupakan proses identifikasi SOP yang dibutuhkan.
1. Tujuan penilaian kebutuhan.
Penilaian kebutuhan SOP bertujuan untuk mengetahui tingkat kebutuhan suatu unit kerja dalam mengembangkan SOP nya.
Penilaian kebutuhan akan sangat bermanfaat dalam menentukan ruang lingkup, jenis, dan jumlah SOP yang dibutuhkan.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7597, 'perka-2-2017', 18, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'Ruang lingkup akan berkaitan dengan tugas mana yang prosedur operasionalnya akan menjadi target untuk distandarkan.
Jenis akan berkaitan dengan tipe dan format SOP yang sesuai untuk diterapkan. Jumlah akan berkaitan dengan berapa banyak SOP yang akan disusun sesuai dengan tingkatan kebutuhannya.
2. Aspek yang mempengaruhi penilaian kebutuhan.
Beberapa aspek yang perlu dipertimbangkan ketika melakukan penilaian kebutuhan, yaitu:
a. Lingkungan Operasional Yang dimaksud dengan lingkungan operasional adalah lingkungan yang harus dipertimbangkan oleh organisasi dalam melaksanakan operasinya, baik secara internal maupun secara eksternal.
2017, No.723 -12- Faktor internal antara lain struktur organisasi, tugas dan fungsi yang diemban, jumlah sumber daya manusia, sarana dan prasarana yang dibutuhkan, dan jenis layanan yang dilaksanakan.
Faktor eksternal antara lain tuntutan dan keinginan pengguna layanan, hubungan antar organisasi dengan berbagai pihak baik dalam maupun luar negeri, dan berbagai bentuk jaringan kerja.
b. Peraturan Perundang-undangan Keberadaan peraturan perundang-undangan mempengaruhi penyusunan SOP, mulai dari Undang-Undang, dan turunannya sampai kepada peraturan/keputusan Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7597, 'Ruang lingkup akan berkaitan dengan tugas mana yang prosedur operasionalnya akan menjadi target untuk distandarkan.
Jenis akan berkaitan dengan tipe dan format SOP yang sesuai untuk diterapkan. Jumlah akan berkaitan dengan berapa banyak SOP yang akan disusun sesuai dengan tingkatan kebutuhannya.
2. Aspek yang mempengaruhi penilaian kebutuhan.
Beberapa aspek yang perlu dipertimbangkan ketika melakukan penilaian kebutuhan, yaitu:
a. Lingkungan Operasional Yang dimaksud dengan lingkungan operasional adalah lingkungan yang harus dipertimbangkan oleh organisasi dalam melaksanakan operasinya, baik secara internal maupun secara eksternal.
2017, No.723 -12- Faktor internal antara lain struktur organisasi, tugas dan fungsi yang diemban, jumlah sumber daya manusia, sarana dan prasarana yang dibutuhkan, dan jenis layanan yang dilaksanakan.
Faktor eksternal antara lain tuntutan dan keinginan pengguna layanan, hubungan antar organisasi dengan berbagai pihak baik dalam maupun luar negeri, dan berbagai bentuk jaringan kerja.
b. Peraturan Perundang-undangan Keberadaan peraturan perundang-undangan mempengaruhi penyusunan SOP, mulai dari Undang-Undang, dan turunannya sampai kepada peraturan/keputusan Kepala BNPB.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2017 tentang Pedoman Penyusunan SOP di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7598, 'perka-2-2017', 19, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'c. Kebutuhan Organisasi dan Stakeholdersnya Penilaian kebutuhan organisasi dan stakeholders berkaitan erat dengan skala prioritas terhadap prosedur-prosedur yang harus distandarkan, karena perubahan struktur organisasi dan tugas dan fungsi, serta desakan stakeholders yang menginginkan perubahan kualitas layanan. SOP juga harus berubah karena perubahan pada sarana dan prasarana dan perkembangan teknologi informasi.
3. Langkah-langkah Penilaian Kebutuhan
a. Menyusun rencana tindak penilaian kebutuhan Pelaksanaan penilaian kebutuhan yang menyeluruh dapat menjadi sebuah proses yang cukup padat dan memakan waktu yang relatif lama. Oleh karena itu perlu disusun sebuah rencana dan target yang jelas, serta pembagian tugas siapa melakukan apa.
Membuat rencana tindak akan sangat membantu dalam menjaga komitmen kerja, menunjukkan akuntabilitas kerja, serta membantu untuk fokus pada apa yang ingin dicapai dari proses ini.
2017, No.723 Untuk membantu menyusun rencana tindak, dapat digunakan tabel berikut:
Tabel 1 Rencana Tindak Tim Penyusun SOP Unit Kerja No Uraian Out Penanggung Jadwal Kegiatan Put Jawab I II III IV (1… (2… (3… (4… (5…
