INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7614, 'perka-20-2010', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PETUNJUK PELAKSANAAN TATA NASKAH DINAS ELEKTRONIK DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.
Pasal1 Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik di lingkungan Badan Nasional Penanggulangan Bencana adalah sebagaimana tercantum dalam Lampiran Peraturan Kepala ini dan merupakan bagian yang tidak terpisahkan dari Peraturan Kepala ini.
Pasal2 Petunjuk PelaksanaanTata Naskah Dinas Elektronik di Lingkungan 3 2014, No.1552 Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Pasal1 merupakan acuan bagi seluruh pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.
Pasal3 Peraturan Kepala ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Republik Indonesia.
Ditetapkan di Jakarta pada tanggal 31Desember 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 14 Oktober 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1552 4 LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGU LANGAN BENCANA NOMOR 20 TAHUN 2010 TENTANG PETUNJUK PELAKSANAAN TATA NASKAH DINAS ELEKTRONIK DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7614, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PETUNJUK PELAKSANAAN TATA NASKAH DINAS ELEKTRONIK DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.
Pasal1 Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik di lingkungan Badan Nasional Penanggulangan Bencana adalah sebagaimana tercantum dalam Lampiran Peraturan Kepala ini dan merupakan bagian yang tidak terpisahkan dari Peraturan Kepala ini.
Pasal2 Petunjuk PelaksanaanTata Naskah Dinas Elektronik di Lingkungan 3 2014, No.1552 Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Pasal1 merupakan acuan bagi seluruh pegawai di Lingkungan Badan Nasional Penanggulangan Bencana.
Pasal3 Peraturan Kepala ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Republik Indonesia.
Ditetapkan di Jakarta pada tanggal 31Desember 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 14 Oktober 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1552 4 LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGU LANGAN BENCANA NOMOR 20 TAHUN 2010 TENTANG PETUNJUK PELAKSANAAN TATA NASKAH DINAS ELEKTRONIK DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7615, 'perka-20-2010', 4, 'menetapkan', 'BAB I', NULL, 4, 'PENDAHULUAN A. Latar Belakang E-government adalah penggunaan teknologi informasi untuk meningkatkan hubungan antar unit kerja Badan Nasional Penanggulangan Bencana dan pihak-pihak yang terkait. Penggunaan teknologi informasi dapat menghasilkan hubungan bentuk baru seperti: G2C (Government To Citizen), G2B (Government To Business), dan G2G (Government To Government). Dalam hal ini, E-Government mengacu pada penggunaan teknologi informasi pemerintah, antara lan melalui intranet dan internet, yang mempunyai kemampuan menghubungkan keperluan penduduk, bisnis dan kegiatan lainnya serta transaksi bisnis melalui sistem otomasi dan jaringan internet yang lebih dikenal dengan worid wide web.
Badan Nasional Penanggulangan Bencana selanjutnya dalam Lampiran Peraturan imi di sebut BNPB yang dibentuk berdasarkan Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008 dan dengan diterbitkannya Peraturan Kepala BNPB Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja BNPB, maka perlu dilaksanakan pembinaan beberapa sistem, salah satu diantaranya adalah pembinaan administrasi umum secara terus menerus yang disesuaikan dengan perkembangan ilmu pengetahuan dan teknologi. Oleh karena itu BNPB merasa perlu menyusun petunjuk pelaksanaan tentang Tata naskah dinas elektronik dan selanjutnya dalam Lampiran Peraturan ini disebut TNDE agar peran dan tugas pokok BNPB berjalan dengan lancar.
B. Maksud Dan Tujuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7615, 'PENDAHULUAN A. Latar Belakang E-government adalah penggunaan teknologi informasi untuk meningkatkan hubungan antar unit kerja Badan Nasional Penanggulangan Bencana dan pihak-pihak yang terkait. Penggunaan teknologi informasi dapat menghasilkan hubungan bentuk baru seperti: G2C (Government To Citizen), G2B (Government To Business), dan G2G (Government To Government). Dalam hal ini, E-Government mengacu pada penggunaan teknologi informasi pemerintah, antara lan melalui intranet dan internet, yang mempunyai kemampuan menghubungkan keperluan penduduk, bisnis dan kegiatan lainnya serta transaksi bisnis melalui sistem otomasi dan jaringan internet yang lebih dikenal dengan worid wide web.
Badan Nasional Penanggulangan Bencana selanjutnya dalam Lampiran Peraturan imi di sebut BNPB yang dibentuk berdasarkan Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008 dan dengan diterbitkannya Peraturan Kepala BNPB Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja BNPB, maka perlu dilaksanakan pembinaan beberapa sistem, salah satu diantaranya adalah pembinaan administrasi umum secara terus menerus yang disesuaikan dengan perkembangan ilmu pengetahuan dan teknologi. Oleh karena itu BNPB merasa perlu menyusun petunjuk pelaksanaan tentang Tata naskah dinas elektronik dan selanjutnya dalam Lampiran Peraturan ini disebut TNDE agar peran dan tugas pokok BNPB berjalan dengan lancar.
B. Maksud Dan Tujuan', 'BAB I', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7616, 'perka-20-2010', 5, 'menetapkan', 'BAB I (lanjutan 1)', NULL, 4, '1. Maksud Petunjuk Pelaksanaan TNDE di Lingkungan BNPB dimaksudkan sebagai acuan dalam melaksanakan TNDE di Lingkungan BNPB.
2. Tujuan Petunjuk Pelaksanaan TNDE ini bertujuan untuk menciptakan prosedur standar dalam melaksanakan TNDE di Lingkungan BNPB.
C. Sasaran Sasaran penetapan TNDE di Lingkungan BNPB adalah :
1. Tercapainya kesamaan pengertian dan penafsiran tentang penyelenggaraan TNDE di Lingkungan BNPB, 5 2014, No.1552
2. Terwujudnya keterpaduan pengelolaan TNDE di Lingkungan BNPB,
3. Lancarnya komunikasi dan kemudahan dalam pengurusan naskah dinas,
4. Tercapanya efektivtas dan efisiensi dalam penyelenggaraan Tata naskah dinas,
5. Terwujudnya pemanfaatan teknologi informasi dalam pengelolaan Tata naskah dinas.
D. Ruang Lingkup Ruang lingkup Petunjuk Pelaksanaan TNDE meliputi:
1. Media Perekaman Naskah Dinas.
2. Struktur :
a. Bentuk,
b. Susunan.
3. Penyiapan Naskah Dinas :
a. Naskah Dinas Eksternal 1 Surat Masuk beserta alur disposisinya.
2) Surat Keluar.
b. Naskah Dinas Internal 1 Surat Masuk beserta alur disposisinya.
2) Surat Keluar.
c. Template Management Pembuatan konsep Peraturan Kepala BNPB surat menggunakan template berdasarkan Nomor 7 Tahun 2009 tentang Petunjuk Pelaksanaan Tata Naskah Dinas di Lingkungan BNPB.
4. Pengabsahan dan Otentikasi.
5. Pengamanan.
6. Pengiriman.
E. Manfaat Manfaat dari petunjuk pelaksanaan ini meliputi hal-hal sebagai berikut :');
