INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7625, 'perka-20-2010', 14, 'menetapkan', 'BAB II (lanjutan 6)', NULL, 15, 'Mekanisme pembuatan sura! keluar yang tidak melalui proses disposisi diawali dengan pembuatan konsep sura! keluar.
a. Konsep Surat dibuat oleh suatu unit kerja yang mempunyai inisiatif membuat konsep Surat keluar. Konsep Surat dapat dibuat oleh pejabat eselon III, eselon IV, ataupun staf.
b. Konsep Surat dibuat dengan menggunakan template Tata naskah dinas yang disediakan.
Cc. Konsep Surat diajukan kepada atasan untuk mendapat persetujuan.
Proses persetujuan berlangsung sampai dengan pejabat yang berhak mengeluarkan Surat keluar, yaitu pejabat eselon satu.
2. Tindak lanjut laporan disposisi.
Laporan disposisi yang telah disepakati pada alur sebelumnya dapat menjadi draf Surat keluar.
3. Pembuatan agenda Surat keluar untuk mendapatkan nomor agenda, dapat dilakukan oleh:
a. Biro Umum Pembuatan agenda dilakukan oleh Biro Umum apabila diperlukan tanda Iangan oleh kepala BNPB atau Sekretaris Utama.
b. Tata Usaha Deputi Pembuatan agenda dilakukan oleh Tata usaha deputi apabila diperlukan tanda tangan oleh deputi.
4. Surat di beri nomor berdasarkan tanggal surat dan format penomoran yang di pilih.
5. Surat telah lengkap dan siap untuk di cetak.
6. Surat dilengkapi dengan tanda tangan dan cap.
7. Pemindaian dokumen terhadap surat yang telah dilengkapi dengan tanda tangan dan cap sehingga dapat disimpan secara elektronik.
2014, No.1552 16 BAB UI SPESIFIKASI SISTEM A. Spesifikasi Fungsional');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7625, 'Mekanisme pembuatan sura! keluar yang tidak melalui proses disposisi diawali dengan pembuatan konsep sura! keluar.
a. Konsep Surat dibuat oleh suatu unit kerja yang mempunyai inisiatif membuat konsep Surat keluar. Konsep Surat dapat dibuat oleh pejabat eselon III, eselon IV, ataupun staf.
b. Konsep Surat dibuat dengan menggunakan template Tata naskah dinas yang disediakan.
Cc. Konsep Surat diajukan kepada atasan untuk mendapat persetujuan.
Proses persetujuan berlangsung sampai dengan pejabat yang berhak mengeluarkan Surat keluar, yaitu pejabat eselon satu.
2. Tindak lanjut laporan disposisi.
Laporan disposisi yang telah disepakati pada alur sebelumnya dapat menjadi draf Surat keluar.
3. Pembuatan agenda Surat keluar untuk mendapatkan nomor agenda, dapat dilakukan oleh:
a. Biro Umum Pembuatan agenda dilakukan oleh Biro Umum apabila diperlukan tanda Iangan oleh kepala BNPB atau Sekretaris Utama.
b. Tata Usaha Deputi Pembuatan agenda dilakukan oleh Tata usaha deputi apabila diperlukan tanda tangan oleh deputi.
4. Surat di beri nomor berdasarkan tanggal surat dan format penomoran yang di pilih.
5. Surat telah lengkap dan siap untuk di cetak.
6. Surat dilengkapi dengan tanda tangan dan cap.
7. Pemindaian dokumen terhadap surat yang telah dilengkapi dengan tanda tangan dan cap sehingga dapat disimpan secara elektronik.
2014, No.1552 16 BAB UI SPESIFIKASI SISTEM A. Spesifikasi Fungsional', 'BAB II (lanjutan 6)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7626, 'perka-20-2010', 15, 'menetapkan', 'BAB II (lanjutan 7)', NULL, 16, '1. Manajemen Data Induk Fasilitas untuk mengatur data induk sistem TNDE berdasarkan data kepegawaian meliputi :
a. Data Induk Pengguna (Master Data Pegawai memfasilitasi manajemen data pengguna berupa penambahan data dan atau penon-aktifan pengguna, serta disusun sesuai data kepegawaian.
Menu ini hanya dapat diakses oleh Administrator aplikasi yang akan menjadi tanggung jawab Biro Umum.
b. Pemberian Kewenangan (Role) mengatur kewenangan setiap pengguna dalam hal : input agenda Surat, pembuatan disposisi, pembuatan Surat keluar, pembuatan konsep Surat, pemeriksaan Surat masuk dan persetujuan laporan disposisi. Dalam sistem TNDE, dimungkinkan seorang pengguna mendapatkan beberapa kewenangan sekaligus dalam suatu waktu, yang diatur oleh administrator, sesuai dengan penugasan yang diberikan.
2. Agenda Surat Masuk Penanganan agenda Surat masuk adalah sebagai berikut :
a. Input Agenda Fasilitas ini hanya dapat dilakukan oleh staf di Unit Tata Usaha (Biro Umum). Pencatatan Agenda Surat Masuk meliputi :
1 Tanggal penerimaan Surat, 2) Nomor, Tanggal dan Hal Surat, 3) Nama dan Alamat pengirim Surat, 4) Sifat Surat, meliputi : a). Sangat Rahasia b). Rahasia c). Biasa 5) Kecepatan langgapan, meliputi: a). Amat segera b). Segera c). Biasa 6) Isi ringkas: dan 7) Keterangan, antara lain lembusan dan salinan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7626, '1. Manajemen Data Induk Fasilitas untuk mengatur data induk sistem TNDE berdasarkan data kepegawaian meliputi :
a. Data Induk Pengguna (Master Data Pegawai memfasilitasi manajemen data pengguna berupa penambahan data dan atau penon-aktifan pengguna, serta disusun sesuai data kepegawaian.
Menu ini hanya dapat diakses oleh Administrator aplikasi yang akan menjadi tanggung jawab Biro Umum.
b. Pemberian Kewenangan (Role) mengatur kewenangan setiap pengguna dalam hal : input agenda Surat, pembuatan disposisi, pembuatan Surat keluar, pembuatan konsep Surat, pemeriksaan Surat masuk dan persetujuan laporan disposisi. Dalam sistem TNDE, dimungkinkan seorang pengguna mendapatkan beberapa kewenangan sekaligus dalam suatu waktu, yang diatur oleh administrator, sesuai dengan penugasan yang diberikan.
2. Agenda Surat Masuk Penanganan agenda Surat masuk adalah sebagai berikut :
a. Input Agenda Fasilitas ini hanya dapat dilakukan oleh staf di Unit Tata Usaha (Biro Umum). Pencatatan Agenda Surat Masuk meliputi :
1 Tanggal penerimaan Surat, 2) Nomor, Tanggal dan Hal Surat, 3) Nama dan Alamat pengirim Surat, 4) Sifat Surat, meliputi : a). Sangat Rahasia b). Rahasia c). Biasa 5) Kecepatan langgapan, meliputi: a). Amat segera b). Segera c). Biasa 6) Isi ringkas: dan 7) Keterangan, antara lain lembusan dan salinan.', 'BAB II (lanjutan 7)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7627, 'perka-20-2010', 16, 'menetapkan', 'BAB II (lanjutan 8)', NULL, 17, '17 2014, No.1552 Nomor urut agenda akan diberikan secara otomatis berdasar indeks terakhir nomor agenda yang tersimpan. Agenda Surat masuk yang lelah di simpan oleh petugas Tata Usaha akan diterima oleh Sekretaris Utama unluk dilakukan disposisi Surat.
b. Penyimpanan dokumen Setelah menyimpan data agenda Surat masuk, petugas dapat melakukan penyimpan dokumen dengan cara:
1) Pemindaian (scanning) menggunakan scanner apabila dokumen diterima dalam bentuk hardcopy.
2) Upload berkas dilakukan apabila Surat telah diterima dalam bentuk softcopy.
Secara otomatis, sistem akan menyimpan data tersebut sehingga pejabat yang ditunjuk akan dapat memeriksa agenda Surat masuk melalui aplikasi TNDE.
c. Melihat Detail Surat Masuk Sistem TNDE memungkinkan setiap data surat masuk dan berkas terkait yang telah disimpan dapat dilihat kembali secara mudah dan lengkap, serta menyediakan fasilitas pencarian untuk menampilkan daftar Surat masuk. Detail Surat masuk ini dapat terlihat oleh pejabat yang dituju, Sekretaris Utama, dan petugas Tata Usaha yang mencatat Surat masuk tersebut.
d. Membuat Disposisi Pejabat yang menerima Surat masuk membuat disposisi kepada bawahan setelah melihat detail Surat masuk. Disposisi dibuat menggunakan menu yang disediakan oleh sistem tanpa dicetak dalam kertas. Surat masuk yang menjadi referensi, secara otomatis akan menjadi bagian dari disposisi tersebut tanpa harus dilampirkan secara manual.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7627, '17 2014, No.1552 Nomor urut agenda akan diberikan secara otomatis berdasar indeks terakhir nomor agenda yang tersimpan. Agenda Surat masuk yang lelah di simpan oleh petugas Tata Usaha akan diterima oleh Sekretaris Utama unluk dilakukan disposisi Surat.
b. Penyimpanan dokumen Setelah menyimpan data agenda Surat masuk, petugas dapat melakukan penyimpan dokumen dengan cara:
1) Pemindaian (scanning) menggunakan scanner apabila dokumen diterima dalam bentuk hardcopy.
2) Upload berkas dilakukan apabila Surat telah diterima dalam bentuk softcopy.
Secara otomatis, sistem akan menyimpan data tersebut sehingga pejabat yang ditunjuk akan dapat memeriksa agenda Surat masuk melalui aplikasi TNDE.
c. Melihat Detail Surat Masuk Sistem TNDE memungkinkan setiap data surat masuk dan berkas terkait yang telah disimpan dapat dilihat kembali secara mudah dan lengkap, serta menyediakan fasilitas pencarian untuk menampilkan daftar Surat masuk. Detail Surat masuk ini dapat terlihat oleh pejabat yang dituju, Sekretaris Utama, dan petugas Tata Usaha yang mencatat Surat masuk tersebut.
d. Membuat Disposisi Pejabat yang menerima Surat masuk membuat disposisi kepada bawahan setelah melihat detail Surat masuk. Disposisi dibuat menggunakan menu yang disediakan oleh sistem tanpa dicetak dalam kertas. Surat masuk yang menjadi referensi, secara otomatis akan menjadi bagian dari disposisi tersebut tanpa harus dilampirkan secara manual.', 'BAB II (lanjutan 8)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7628, 'perka-20-2010', 17, 'menetapkan', 'BAB II (lanjutan 9)', NULL, 17, 'e. Membuat Laporan Disposisi Bawahan yang menerima perintah disposisi dari atasan dapat memeriksa isi perintah disposisi beserta Surat masuk yang berkaitan melalui sistem TNDE untuk kemudian membuat laporan kepada atasan. Apabi/a diperlukan, bawahan dapat melakukan disposisi lanjut sebelum membuat laporan. Laporan disposisi yang dibuat berisi antara lain:
1). Keterangan singkat mengenai hasil pelaksanaan perintah disposisi.
2). Usulan konsep Surat apabila diperlukan dalam membuat laporan disposisi.
3). Lampiran berupa attachment sofcopy berkas yang ingin disertakan dalam laporan disposisi.
f. Persetujuan Laporan Disposisi Pembuat disposisi memeriksa laporan disposisi menggunakan menu 2014, No.1552 18 yang telah disediakan dalam aplikasi guna mengambil keputusan: menyetujui laporan atau memberi caTata n kepada pembuat laporan disposisi. Persetujuan laporan disposisi berlanjut sampai dengan Pejabat Eselon Satu. Laporan disposisi yang telah disetujui dapat dikirimkan kepada Bagian Tata Usaha untuk dibuat agenda surat keluar.
3. Agenda Surat Keluar Surat Keluar dapat dibuat berdasarkan laporan disposisi ataupun konsep surat atas inisiatif sendiri.
a. Pembuatan Draf Surat Konsep surat dibuat dengan menggunakan aplikasi TNDE dengan dua cara yaitu:
1). Template Aplikasi TNDE menyediakan template yang mengacu pada Peraturan Kepala BNPB Nomor 7 Tahun 2009 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Di Lingkungan BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7628, 'e. Membuat Laporan Disposisi Bawahan yang menerima perintah disposisi dari atasan dapat memeriksa isi perintah disposisi beserta Surat masuk yang berkaitan melalui sistem TNDE untuk kemudian membuat laporan kepada atasan. Apabi/a diperlukan, bawahan dapat melakukan disposisi lanjut sebelum membuat laporan. Laporan disposisi yang dibuat berisi antara lain:
1). Keterangan singkat mengenai hasil pelaksanaan perintah disposisi.
2). Usulan konsep Surat apabila diperlukan dalam membuat laporan disposisi.
3). Lampiran berupa attachment sofcopy berkas yang ingin disertakan dalam laporan disposisi.
f. Persetujuan Laporan Disposisi Pembuat disposisi memeriksa laporan disposisi menggunakan menu 2014, No.1552 18 yang telah disediakan dalam aplikasi guna mengambil keputusan: menyetujui laporan atau memberi caTata n kepada pembuat laporan disposisi. Persetujuan laporan disposisi berlanjut sampai dengan Pejabat Eselon Satu. Laporan disposisi yang telah disetujui dapat dikirimkan kepada Bagian Tata Usaha untuk dibuat agenda surat keluar.
3. Agenda Surat Keluar Surat Keluar dapat dibuat berdasarkan laporan disposisi ataupun konsep surat atas inisiatif sendiri.
a. Pembuatan Draf Surat Konsep surat dibuat dengan menggunakan aplikasi TNDE dengan dua cara yaitu:
1). Template Aplikasi TNDE menyediakan template yang mengacu pada Peraturan Kepala BNPB Nomor 7 Tahun 2009 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Di Lingkungan BNPB.', 'BAB II (lanjutan 9)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7629, 'perka-20-2010', 18, 'menetapkan', 'BAB II (lanjutan 10)', NULL, 18, '2). Tanpa Template Selain menggunakan template yang sudah tersedia, pengguna juga dapat membuat konsep surat tanpa template apabila konsep surat tidak menggunakan format Tata naskah dinas yang diatur dalam Peraturan Kepala BNPB Nomor 7 Tahun 2009 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Di Lingkungan BNPB.
Konsep Surat yang diajukan juga dilengkapi dengan keterangan yang berisi: a) Pejabat yang akan menandatangani Surat tersebut b) Tujuan Surat c) Tanggal Surat
b. Persetujuan Konsep Surat Terdapat fasilitas untuk melakukan persetujuan atasan terhadap konsep Surat yang telah dibuat. Dalam proses persetujuan suatu konsep Surat, dimungkinkan terjadi koreksi dan revisi yang dilakukan secara berulang sampai didapat suatu konsep Surat yang disetujui. Persetujuan konsep Surat dilakukan secara bertingkat sampai dengan pejabat yang berwenang mengeluarkan Surat, yaitu pejabat eselon satu atau pejabat eselon dua pada surat-surat tertentu.
Cc. Pembuatan Agenda Surat Keluar Setelah konsep surat disetujui, kemudian dikirimkan kepada Bagian Tata Usaha melalui aplikasi TNDE untuk dibuat agenda Surat keluar dan pemberian nomor Surat.
19 2014, No.1552
d. Pemindaian (scanning) Surat Surat keluar yang telah dilengkapi dengan tanda Iangan dan cap disimpan dengan cara pemindaian menggunakan scanner.
4. Manajemen Template');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7629, '2). Tanpa Template Selain menggunakan template yang sudah tersedia, pengguna juga dapat membuat konsep surat tanpa template apabila konsep surat tidak menggunakan format Tata naskah dinas yang diatur dalam Peraturan Kepala BNPB Nomor 7 Tahun 2009 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Di Lingkungan BNPB.
Konsep Surat yang diajukan juga dilengkapi dengan keterangan yang berisi: a) Pejabat yang akan menandatangani Surat tersebut b) Tujuan Surat c) Tanggal Surat
b. Persetujuan Konsep Surat Terdapat fasilitas untuk melakukan persetujuan atasan terhadap konsep Surat yang telah dibuat. Dalam proses persetujuan suatu konsep Surat, dimungkinkan terjadi koreksi dan revisi yang dilakukan secara berulang sampai didapat suatu konsep Surat yang disetujui. Persetujuan konsep Surat dilakukan secara bertingkat sampai dengan pejabat yang berwenang mengeluarkan Surat, yaitu pejabat eselon satu atau pejabat eselon dua pada surat-surat tertentu.
Cc. Pembuatan Agenda Surat Keluar Setelah konsep surat disetujui, kemudian dikirimkan kepada Bagian Tata Usaha melalui aplikasi TNDE untuk dibuat agenda Surat keluar dan pemberian nomor Surat.
19 2014, No.1552
d. Pemindaian (scanning) Surat Surat keluar yang telah dilengkapi dengan tanda Iangan dan cap disimpan dengan cara pemindaian menggunakan scanner.
4. Manajemen Template', 'BAB II (lanjutan 10)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7630, 'perka-20-2010', 19, 'menetapkan', 'BAB II (lanjutan 11)', NULL, 19, 'a. Penggunaan Template Standar Sistem menyediakan template surat berdasarkan Peraturan Kepala BNPB Nomor 7 Tahun 2009 Tentang Petunjuk Pelaksanaan Tata Naskah Dinas di Lingkungan BNPB.
Jenis dan format template naskah dinas yang tersedia terdiri dari :
1) Naskah Dinas Arahan Diantaranya berisi : a) Peraturan, b) Pedoman, c) Petunjuk Pelaksanaan: d) Lnstruksi, e) Prosedur Tetap: f Surat Edaran:
9g) Surat Keputusan: h) Surat Perintah/ Surat Tugas.
2) Naskah Dinas Korespondensi a) Nota Dinas: b) Memorandum, c) Surat Dinas, d) Surat Undangan.
3) Naskah Dinas Khusus a) Surat Perjanjian, b) Surat Kuasa, c) Berita Acara: d) Surat Keterangan: e) Surat Pengantar. ? Pengumuman 4) Laporan 5) Telaahan staf 6) Formulir 2014, No.1552 20 Lebih jelas mengenai format setiap naskah dinas di alas beserta aturan yang berkaitan dengan penomoran dan penyusunannya dapat dilihat pada Peraturan Kepala BNPB Nomor 7 Tahun 2009 Tentang Petunjuk Pelaksanaan Tata Naskah Dinas di Lingkungan BNPB.
b. Pembuatan Template Baru Sistem aplikasi TNDE menyediakan fasilitas untuk membuat ataupun mengedit template baru yang belum ada pada pedoman lata naskah dinas, sehingga format Surat tambahan tetap dapat dimasukkan sebagai suatu template.
c. Penggunaan Template Dalam Pembuatan Konsep Surat.
Template yang leiah tersimpan terintegrasi dengan aplikasi TNDE, sehingga proses melengkapi Surat dapat langsung dilakukan melalui aplikasi tersebut tanpa memerlukan editor lain.
Keterangan:');
