INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7631, 'perka-20-2010', 20, 'menetapkan', 'BAB II (lanjutan 12)', NULL, 20, 'Surat yang bersifat rahasia dan sangat rahasia dicatat sebagai agenda tanpa dilakukan pemindaian dan alur penanganan seperti Surat yang bersifat biasa.
5. Pencarian Dokumen Semua history dokumen yang tersimpan dalam sistem dapat dicari berdasarkan kriteria pencarian yang ditentukan oleh pengguna. Pencarian ini meliputi kegiatan pencatatan agenda masuk, disposisi dan pembuatan agenda keluar.
B. Spesifikasi Non Fungsional Beberapa hal yang menjadi persyaratan non fungsional dari sistem adalah:
1. Keamanan Aplikasi Menjamin otentikasi pengguna yang melakukan pengaksesan terhadap aplikasi. Mekanisme otentikasi minimal dilakukan dengan menggunakan pengecekan username dan password sehingga aplikasi dapat diakses dengan menggunakan kewenangan yang Ieiah ditentukan untuk masing- masing pengguna.
Otentikasi dilengkapi dengan keamanan yang menjamin bahwa data dimasukkan oleh pengguna bukan oleh sistem lain atau virus, misalkan dengan menggunakan captcha ataupun security guestion. Dalam akses aplikasi, dijamin bahwa :
a. Hanya pengguna yang berhak yang dapat mengkases aplikasi.
b. Pengguna hanya dapat mengakses menu yang menjadi kewenangannya.
21 2014, No.1552 Cc. Dalam satu saat hanya terdapat satu username yang sama yang melakukan akses aplikasi, sehingga tidak dimungkinkan penggunaan username yang sama secara paralel dalam mengakses aplikasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7631, 'Surat yang bersifat rahasia dan sangat rahasia dicatat sebagai agenda tanpa dilakukan pemindaian dan alur penanganan seperti Surat yang bersifat biasa.
5. Pencarian Dokumen Semua history dokumen yang tersimpan dalam sistem dapat dicari berdasarkan kriteria pencarian yang ditentukan oleh pengguna. Pencarian ini meliputi kegiatan pencatatan agenda masuk, disposisi dan pembuatan agenda keluar.
B. Spesifikasi Non Fungsional Beberapa hal yang menjadi persyaratan non fungsional dari sistem adalah:
1. Keamanan Aplikasi Menjamin otentikasi pengguna yang melakukan pengaksesan terhadap aplikasi. Mekanisme otentikasi minimal dilakukan dengan menggunakan pengecekan username dan password sehingga aplikasi dapat diakses dengan menggunakan kewenangan yang Ieiah ditentukan untuk masing- masing pengguna.
Otentikasi dilengkapi dengan keamanan yang menjamin bahwa data dimasukkan oleh pengguna bukan oleh sistem lain atau virus, misalkan dengan menggunakan captcha ataupun security guestion. Dalam akses aplikasi, dijamin bahwa :
a. Hanya pengguna yang berhak yang dapat mengkases aplikasi.
b. Pengguna hanya dapat mengakses menu yang menjadi kewenangannya.
21 2014, No.1552 Cc. Dalam satu saat hanya terdapat satu username yang sama yang melakukan akses aplikasi, sehingga tidak dimungkinkan penggunaan username yang sama secara paralel dalam mengakses aplikasi.', 'BAB II (lanjutan 12)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7632, 'perka-20-2010', 21, 'menetapkan', 'BAB II (lanjutan 13)', NULL, 21, 'C. Pencatatan Log Aktivitas Pengguna Aplikasi mencatat setiap aktivitas pengguna yang berkaitan terhadap sistem. Log aktivitas ini dapat digunakan untuk melakukan audit terhadap segala proses persuratan yang memanfaatkan aplikasi TNDE.
D. Fitur Penghapusan dan pembatalan Aplikasi tidak melakukan penghapusan secara langsung (purge delete) terhadap dokumen ataupun agenda Surat yang Ieiah dibuat, tetapi akan digunakan mekanisme flag untuk menandakan status validitas suatu dokumen ataupun agenda Surat. Untuk penghapusan data secara permanen diperlukan berita acara sesuai ketentuan yang berlaku di BNPB.
E. Keamanan Penyimpanan Dokumen Aplikasi memberikan kepastian bahwa dokumen yang tersimpan tidak akan tumpang tindih dengan dokumen yang sudah ada sebelumnya, sehingga setiap pengguna dapat mengakses berkas dokumen yang benar. Penyimpanan yang dilakukan harus mempertimbangkan aspek keamanan dan pemeliharaan untuk mencegah kerusakan berkas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7632, 'C. Pencatatan Log Aktivitas Pengguna Aplikasi mencatat setiap aktivitas pengguna yang berkaitan terhadap sistem. Log aktivitas ini dapat digunakan untuk melakukan audit terhadap segala proses persuratan yang memanfaatkan aplikasi TNDE.
D. Fitur Penghapusan dan pembatalan Aplikasi tidak melakukan penghapusan secara langsung (purge delete) terhadap dokumen ataupun agenda Surat yang Ieiah dibuat, tetapi akan digunakan mekanisme flag untuk menandakan status validitas suatu dokumen ataupun agenda Surat. Untuk penghapusan data secara permanen diperlukan berita acara sesuai ketentuan yang berlaku di BNPB.
E. Keamanan Penyimpanan Dokumen Aplikasi memberikan kepastian bahwa dokumen yang tersimpan tidak akan tumpang tindih dengan dokumen yang sudah ada sebelumnya, sehingga setiap pengguna dapat mengakses berkas dokumen yang benar. Penyimpanan yang dilakukan harus mempertimbangkan aspek keamanan dan pemeliharaan untuk mencegah kerusakan berkas.', 'BAB II (lanjutan 13)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7633, 'perka-20-2010', 22, 'menetapkan', 'BAB IV', NULL, 21, 'PENUTUP Petunjuk Pelaksanaan ini merupakan acuan dalam pelaksanaan TNDE di Lingkungan BNPB, dengan harapan dapat tercapai kesamaan pengertian dan penafsiran tentang penyelenggaraan TNDE. serta terwujudnya sistem TNDE secara efektif dan efisien sehingga dapat menunjang tugas pokok dan fungsi BNPB dengan lebih baik.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7633, 'PENUTUP Petunjuk Pelaksanaan ini merupakan acuan dalam pelaksanaan TNDE di Lingkungan BNPB, dengan harapan dapat tercapai kesamaan pengertian dan penafsiran tentang penyelenggaraan TNDE. serta terwujudnya sistem TNDE secara efektif dan efisien sehingga dapat menunjang tugas pokok dan fungsi BNPB dengan lebih baik.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF', 'BAB IV', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2010 tentang Petunjuk Pelaksanaan Tata Naskah Dinas Elektronik Di Lingkungan Badan Nasional Penanggulangan Bencana');
