INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7638, 'perka-20-2011', 4, 'pasal', 'Pasal 1', NULL, 4, 'Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana merupakan panduan/acuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/lembaga dan pemangku kepentingan penanggulangan bencana lainnya agar pelaksanaan monitoring dan evaluasi manajemen logistik penanggulangan bencana dapat dilakukan dengan lancar, tertib, terpadu, aman dan dapat dipertanggungjawabkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7638, 'Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana merupakan panduan/acuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/lembaga dan pemangku kepentingan penanggulangan bencana lainnya agar pelaksanaan monitoring dan evaluasi manajemen logistik penanggulangan bencana dapat dilakukan dengan lancar, tertib, terpadu, aman dan dapat dipertanggungjawabkan.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2011 tentang Pedoman Monitoring dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7639, 'perka-20-2011', 5, 'pasal', 'Pasal 2', NULL, 4, 'Pedoman sebagaimana dimaksud dalam Pasal 1 tercantum dalam Lampiran Peraturan ini dan merupakan bagian yang tidak terpisahkan dari Peraturan ini.');
