INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7641, 'perka-20-2011', 7, 'lain', 'Penutup', NULL, 4, 'Ditetapkan di Jakarta pada tanggal 50 Desember 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, PA DR. SYAMSUL MAARIF, M.S PS PEDOMAN MONIRTORING DAN EVALUASI MANAJEMEN LOGISTIK PENANGGULANGAN BENCANA DAFTAR ISI BAB I PENDAHULUAN A. Latar Belakang …………………………………………………………… 1 B. Maksud dan Tujuan ……………………………………………………….. 1 C. Pengertian …………………………………………………………………….. 2 D. Prinsip ………………………………………………………………………….. 4 E. Landasan Hukum ……………………………………………………………. 4 F. Ruang Lingkup ……………………………………………………………….. 5 G. Sistematika ……………………………………………………………………. 5 BAB II MANAJEMEN LOGISTIK A. Manajemen Logistik ……………………………………………………… 6 B. Sistem Informasi Manajemen …………………………………………… 8 C. Laporan Pertanggungjawaban …………………………………………. 8 BAB III MONITORING DAN EVALUASI A. Tahapan dan langkah Kegiatan ……………………………………….. 9 B. Koordinasi …………………………………………………………………….. 10');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7641, 'Ditetapkan di Jakarta pada tanggal 50 Desember 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, PA DR. SYAMSUL MAARIF, M.S PS PEDOMAN MONIRTORING DAN EVALUASI MANAJEMEN LOGISTIK PENANGGULANGAN BENCANA DAFTAR ISI BAB I PENDAHULUAN A. Latar Belakang …………………………………………………………… 1 B. Maksud dan Tujuan ……………………………………………………….. 1 C. Pengertian …………………………………………………………………….. 2 D. Prinsip ………………………………………………………………………….. 4 E. Landasan Hukum ……………………………………………………………. 4 F. Ruang Lingkup ……………………………………………………………….. 5 G. Sistematika ……………………………………………………………………. 5 BAB II MANAJEMEN LOGISTIK A. Manajemen Logistik ……………………………………………………… 6 B. Sistem Informasi Manajemen …………………………………………… 8 C. Laporan Pertanggungjawaban …………………………………………. 8 BAB III MONITORING DAN EVALUASI A. Tahapan dan langkah Kegiatan ……………………………………….. 9 B. Koordinasi …………………………………………………………………….. 10', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2011 tentang Pedoman Monitoring dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7642, 'perka-20-2011', 8, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'C. Waktu Pelaksanaan ………………………………………………………… 11 D. Lokasi .............................................................................. 11 E. Tugas pokok pelaksana tim monitoring dan evaluasi ............ 11 F. Pelaksanaan Monitoring dan Evaluasi Manajemen Logistik .... 11 G. Laporan Monitoring dan Evaluasi ....................................... 14 H. Sumber Pembiayaan Pelaksanaan Monitoring dan Evaluasi ... 15 BAB IV PENUTUP ……………………………………….…………………………………. 16');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7642, 'C. Waktu Pelaksanaan ………………………………………………………… 11 D. Lokasi .............................................................................. 11 E. Tugas pokok pelaksana tim monitoring dan evaluasi ............ 11 F. Pelaksanaan Monitoring dan Evaluasi Manajemen Logistik .... 11 G. Laporan Monitoring dan Evaluasi ....................................... 14 H. Sumber Pembiayaan Pelaksanaan Monitoring dan Evaluasi ... 15 BAB IV PENUTUP ……………………………………….…………………………………. 16', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2011 tentang Pedoman Monitoring dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7643, 'perka-20-2011', 9, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'LAMPIRAN 1 LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 20 TAHUN 2011 TANGGAL : 30 DESEMBER 2011 BAB I PENDAHULUAN A. Latar Belakang Berbagai kemajuan signifikan dalam penanggulangan bencana selama beberapa tahun terakhir telah menjadikan Indonesia sebagai salah satu negara yang sangat progresif dalam upaya penanggulangan bencana untuk membangun ketangguhan masyarakatnya. Sebagai salah satu negara yang paling rentan terhadap bencana serta adanya ancaman yang relatif cukup jelas yang disebabkan kondisi geografis dan komposisi demografi, Indonesia masih akan terus mengalami dan mengelola bencana.
Bencana yang sering terjadi di Indonesia adalah banjir, kebakaran, angin topan, longsor, kekeringan, gempa bumi, gunung berapi dan tsunami.
Tercatat 2.836 kejadian bencana antara tahun sejak berdirinya BNPB tahun 2008 sampai dengan tahun 2010 yang menyebabkan 4.216 orang meninggal, 999 orang hilang, 1.067.103 orang mengungsi,dan 653.876 rumah rusak, serta 14.526 unit sarana dan prasarana rusak1. Dalam rangka meringankan beban masyarakat yang terkena bencana, pemerintah melalui BNPB memobilisasi logistik dari berbagai sumber daya untuk menghadapi berbagai bencana yang terjadi di Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7643, 'LAMPIRAN 1 LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 20 TAHUN 2011 TANGGAL : 30 DESEMBER 2011 BAB I PENDAHULUAN A. Latar Belakang Berbagai kemajuan signifikan dalam penanggulangan bencana selama beberapa tahun terakhir telah menjadikan Indonesia sebagai salah satu negara yang sangat progresif dalam upaya penanggulangan bencana untuk membangun ketangguhan masyarakatnya. Sebagai salah satu negara yang paling rentan terhadap bencana serta adanya ancaman yang relatif cukup jelas yang disebabkan kondisi geografis dan komposisi demografi, Indonesia masih akan terus mengalami dan mengelola bencana.
Bencana yang sering terjadi di Indonesia adalah banjir, kebakaran, angin topan, longsor, kekeringan, gempa bumi, gunung berapi dan tsunami.
Tercatat 2.836 kejadian bencana antara tahun sejak berdirinya BNPB tahun 2008 sampai dengan tahun 2010 yang menyebabkan 4.216 orang meninggal, 999 orang hilang, 1.067.103 orang mengungsi,dan 653.876 rumah rusak, serta 14.526 unit sarana dan prasarana rusak1. Dalam rangka meringankan beban masyarakat yang terkena bencana, pemerintah melalui BNPB memobilisasi logistik dari berbagai sumber daya untuk menghadapi berbagai bencana yang terjadi di Indonesia.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2011 tentang Pedoman Monitoring dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7644, 'perka-20-2011', 10, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'Logistik dibutuhkan di setiap tahapan kegiatan penanggulangan bencana (PB) baik kesiapsiagaan, tanggap darurat, pemulihan, rehabilitasi dan rekonstruksi. Sejak tahun 2009 BNPB telah memberikan dukungan Logistik dan Peralatan bagi BPBD Provinsi untuk penguatan kelembagaan dalam rangka kesiapsiagaan dan memberikan bantuan logistik dan peralatan bagi kabupaten / kota yang terkena bencana pada masa tanggap darurat atas usulan BPBD Provinsi. Bantuan kemanusiaan juga diberikan kepada negara yang terkena bencana seperti Pakistan, Haiti dan Jepang.
Dalam upaya mengukur pencapaian keberhasilan pelaksanaan Manajemen Logistik PB dan menganalisa manfaat bantuan logistik yang diberikan, diperlukan monitoring dan evaluasi secara komprehensif dimulai dari perencanaan, pengadaan, penerimaan, pergudangan, penyaluran, pengangkutan, pendistribusian sampai dengan penghapusan. Untuk itu dipandang perlu untuk menyusun Pedoman tentang Monitoring dan Evaluasi Manajemen Logistik.
B. Maksud dan Tujuan
1. Maksud Sebagai panduan pelaksanaan kegiatan manajemen logistik PB bagi Kementerian / Lembaga khususnya BNPB, Organisasi Perangkat Daerah 1 Sumber pusat data dan informasi BNPB tahun 2011 1 (OPD) termasuk BPBD, serta Organisasi nonpemerintah dalam melaksanakan monitoring dan evaluasi manajemen logistik, sesuai peraturan perundang – undangan.
2. Tujuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7644, 'Logistik dibutuhkan di setiap tahapan kegiatan penanggulangan bencana (PB) baik kesiapsiagaan, tanggap darurat, pemulihan, rehabilitasi dan rekonstruksi. Sejak tahun 2009 BNPB telah memberikan dukungan Logistik dan Peralatan bagi BPBD Provinsi untuk penguatan kelembagaan dalam rangka kesiapsiagaan dan memberikan bantuan logistik dan peralatan bagi kabupaten / kota yang terkena bencana pada masa tanggap darurat atas usulan BPBD Provinsi. Bantuan kemanusiaan juga diberikan kepada negara yang terkena bencana seperti Pakistan, Haiti dan Jepang.
Dalam upaya mengukur pencapaian keberhasilan pelaksanaan Manajemen Logistik PB dan menganalisa manfaat bantuan logistik yang diberikan, diperlukan monitoring dan evaluasi secara komprehensif dimulai dari perencanaan, pengadaan, penerimaan, pergudangan, penyaluran, pengangkutan, pendistribusian sampai dengan penghapusan. Untuk itu dipandang perlu untuk menyusun Pedoman tentang Monitoring dan Evaluasi Manajemen Logistik.
B. Maksud dan Tujuan
1. Maksud Sebagai panduan pelaksanaan kegiatan manajemen logistik PB bagi Kementerian / Lembaga khususnya BNPB, Organisasi Perangkat Daerah 1 Sumber pusat data dan informasi BNPB tahun 2011 1 (OPD) termasuk BPBD, serta Organisasi nonpemerintah dalam melaksanakan monitoring dan evaluasi manajemen logistik, sesuai peraturan perundang – undangan.
2. Tujuan', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2011 tentang Pedoman Monitoring dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7645, 'perka-20-2011', 11, 'lampiran', 'Lampiran hal. 7', NULL, 7, 'a. Memastikan setiap bantuan logistik yang didistribusikan sesuai dengan kebutuhan masyarakat yang terkena bencana, melalui proses manajemen logistik sesuai peraturan perundangan yang berlaku sampai dengan tingkat kabupaten/kota. a)
b. Membantu BNPB dan BPBD dalam pengambilan keputusan manajemen logistik secara tepat.
c. Mengkaji sejauh mana strategi manajemen logistik yang dikembangkan oleh BNPB/BPBD menjawab masalah penanggulangan bencana yang dikoordinasikan oleh BNPB/BPBD.
d. Menggali masukan, saran atau ide dari pelaksana manajemen logistik dan penerima bantuan untuk pelaksanaan kegiatan yang akan datang.
e. Mengidentifikasi faktor-faktor pendukung dan penghambat pencapaian tujuan program.
f. Membuat penilaian apakah semua sumber daya yang ada telah dipergunakan secara optimal.
A.
B.
C. Pengertian
1. Manajemen Logistik Manajemen logistik adalah proses pengelolaan logistik PB yang meliputi perencanaan/inventarisasi kebutuhan, pengadaan dan/atau penerimaan, pergudangan dan/atau penyimpanan, pendistribusian, pengangkutan, penerimaan di tujuan dan penghapusan.
2. Monitoring Monitoring adalah kegiatan memantau perkembangan pelaksanaan manajemen logistik dan mengidentifikasi, serta mengantisipasi permasalahan yang timbul untuk dapat diambil tindakan sedini mungkin.
3. Evaluasi Evaluasi adalah rangkaian kegiatan membandingkan realisasi masukan (input), keluaran (output), dan hasil (outcome) terhadap rencana dan standar. Evaluasi melihat manfaat untuk perencanaan selanjutnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7645, 'a. Memastikan setiap bantuan logistik yang didistribusikan sesuai dengan kebutuhan masyarakat yang terkena bencana, melalui proses manajemen logistik sesuai peraturan perundangan yang berlaku sampai dengan tingkat kabupaten/kota. a)
b. Membantu BNPB dan BPBD dalam pengambilan keputusan manajemen logistik secara tepat.
c. Mengkaji sejauh mana strategi manajemen logistik yang dikembangkan oleh BNPB/BPBD menjawab masalah penanggulangan bencana yang dikoordinasikan oleh BNPB/BPBD.
d. Menggali masukan, saran atau ide dari pelaksana manajemen logistik dan penerima bantuan untuk pelaksanaan kegiatan yang akan datang.
e. Mengidentifikasi faktor-faktor pendukung dan penghambat pencapaian tujuan program.
f. Membuat penilaian apakah semua sumber daya yang ada telah dipergunakan secara optimal.
A.
B.
C. Pengertian
1. Manajemen Logistik Manajemen logistik adalah proses pengelolaan logistik PB yang meliputi perencanaan/inventarisasi kebutuhan, pengadaan dan/atau penerimaan, pergudangan dan/atau penyimpanan, pendistribusian, pengangkutan, penerimaan di tujuan dan penghapusan.
2. Monitoring Monitoring adalah kegiatan memantau perkembangan pelaksanaan manajemen logistik dan mengidentifikasi, serta mengantisipasi permasalahan yang timbul untuk dapat diambil tindakan sedini mungkin.
3. Evaluasi Evaluasi adalah rangkaian kegiatan membandingkan realisasi masukan (input), keluaran (output), dan hasil (outcome) terhadap rencana dan standar. Evaluasi melihat manfaat untuk perencanaan selanjutnya.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2011 tentang Pedoman Monitoring dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7646, 'perka-20-2011', 12, 'lampiran', 'Lampiran hal. 7', NULL, 7, '4. Bantuan darurat bencana adalah bantuan yang diberikan untuk memenuhi kebutuhan dasar pada saat keadaan darurat.
5. Logistik adalah segala sesuatu yang berwujud dan dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri atas sandang, pangan dan hunian sementara atau turunannya yang habis dipakai atau dikonsumsi seperti sembilan bahan pokok, obat, pakaian dan kelengkapannya, air, tenda, baju tidur dan sebagainya.
1. 2
2. 3.
4. 5.
6. 7. Pendekatan Cluster adalah suatu model koordinasi dengan mengelompokan para pelaku kemanusiaan berdasarkan gugus kerja untuk memberikan respon darurat yang lebih dapat diperkirakan dengan penetapan “pimpinan” kelompok / Cluster. Pendekatan Cluster (Cluster Approach) dilaksanakan pada kejadian bencana berskala besar atau membutuhkan bantuan internasional dalam respon multi-sektor dengan partisipasi luas dari para pelaku kemanusiaan internasional.
Pimpinan Cluster bersama-sama dengan sektor-sektor Pemerintah membangun koordinasi baik dalam perencanaan maupun pelaksanaan.
Pendekatan Cluster bertujuan agar bantuan respon darurat dapat dilaksanakan secara lebih terkoordinasi antar pelaku baik dari pemerintah maupun nonpemerintah.
8. Pos Komando (Posko) adalah pusat pengkoordinasian, pengendalian, monitoring dan evaluasi penanganan tanggap darurat yang juga memiliki kewenangan dalam memberikan data dan informasi tentang penanganan tanggap darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7646, '4. Bantuan darurat bencana adalah bantuan yang diberikan untuk memenuhi kebutuhan dasar pada saat keadaan darurat.
5. Logistik adalah segala sesuatu yang berwujud dan dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri atas sandang, pangan dan hunian sementara atau turunannya yang habis dipakai atau dikonsumsi seperti sembilan bahan pokok, obat, pakaian dan kelengkapannya, air, tenda, baju tidur dan sebagainya.
