INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7658, 'perka-20-2011', 24, 'lampiran', 'Lampiran hal. 17', NULL, 17, '1. Perencanaan/Inventarisasi Kebutuhan (Lampiran 2) Monitoring dan evaluasi yang dilakukan adalah untuk memeriksa:
Logistik BNPB:
a. Laporan persediaan (yang memuat stok awal, penerimaan, penyaluran/distribusi, dan stok akhir).
b. Rencana Kontinjensi nasional yang memuat:
1) Pemetaan dan pendataan ketersediaan logistik secara nasional, provinsi dan kabupaten/kota.
2) Kebutuhan logistik 3) Kontak Organisasi dengan sumber daya logistiknya.
c. Dokumen permintaan logistik sesuai format terlampir.
d. Kesesuaian permintaan logistik dengan:
1) Rencana Nasional Penanggulangan Bencana 2) Rencana Operasi (pada saat keadaan darurat) 3) Standar minimal di satu wilayah 4) Dokumen permintaan logistik.
e. Perencanaan penyiapan kebutuhan logistik per tahun.
f. Perencanaan distribusi.
g. Pemutakhiran data.
Logistik BPBD:
a. Laporan persediaan (yang memuat stok awal, penerimaan, penyaluran/distribusi, dan stok akhir).
b. Rencana Kontinjensi Regional yang memuat:
1) Pemetaan dan pendataan ketersediaan logistik di Provinsi dan Kabupaten/Kota.
2) Kebutuhan logistik 3) Kontak Organisasi dengan sumber daya logistiknya.
c. Dokumen permintaan logistik dari daerah sesuai format terlampir.
d. Kesesuaian permintaan logistik daerah dengan:
1) Rencana Penanggulangan Bencana Daerah 2) Rencana Operasi (pada saat keadaan darurat) 3) Standar minimal di satu wilayah 4) Dokumen permintaan logistik (kebutuhan daerah)
e. Perencanaan penyiapan kebutuhan logistik per tahun.
f. Perencanaan distribusi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7658, '1. Perencanaan/Inventarisasi Kebutuhan (Lampiran 2) Monitoring dan evaluasi yang dilakukan adalah untuk memeriksa:
Logistik BNPB:
a. Laporan persediaan (yang memuat stok awal, penerimaan, penyaluran/distribusi, dan stok akhir).
b. Rencana Kontinjensi nasional yang memuat:
1) Pemetaan dan pendataan ketersediaan logistik secara nasional, provinsi dan kabupaten/kota.
2) Kebutuhan logistik 3) Kontak Organisasi dengan sumber daya logistiknya.
c. Dokumen permintaan logistik sesuai format terlampir.
d. Kesesuaian permintaan logistik dengan:
1) Rencana Nasional Penanggulangan Bencana 2) Rencana Operasi (pada saat keadaan darurat) 3) Standar minimal di satu wilayah 4) Dokumen permintaan logistik.
e. Perencanaan penyiapan kebutuhan logistik per tahun.
f. Perencanaan distribusi.
g. Pemutakhiran data.
Logistik BPBD:
a. Laporan persediaan (yang memuat stok awal, penerimaan, penyaluran/distribusi, dan stok akhir).
b. Rencana Kontinjensi Regional yang memuat:
1) Pemetaan dan pendataan ketersediaan logistik di Provinsi dan Kabupaten/Kota.
2) Kebutuhan logistik 3) Kontak Organisasi dengan sumber daya logistiknya.
c. Dokumen permintaan logistik dari daerah sesuai format terlampir.
d. Kesesuaian permintaan logistik daerah dengan:
1) Rencana Penanggulangan Bencana Daerah 2) Rencana Operasi (pada saat keadaan darurat) 3) Standar minimal di satu wilayah 4) Dokumen permintaan logistik (kebutuhan daerah)
e. Perencanaan penyiapan kebutuhan logistik per tahun.
f. Perencanaan distribusi.', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2011 tentang Pedoman Monitoring dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7659, 'perka-20-2011', 25, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'g. Pemutakhiran data.
Dalam hal perencanaan bantuan logistik yang melibatkan lembaga internasional dan lembaga asing nonpemerintah, koordinator cluster bertanggung jawab untuk melakukan monitoring dalam perencanaan 12 bantuan logistik sesuai dengan spesifikasi yang diperlukan berdasarkan peraturan perundangan yang mengatur peran serta lembaga internasional dan lembaga asing nonpemerintah pada saat tanggap darurat.
2. Pengadaan dan Penerimaan (Lampiran 3)
a. Pengadaan 1) Pengadaan Logistik BNPB/BPBD Pengadaan logistik berdasarkan pagu anggaran dan mekanisme yang dilakukan sesuai peraturan yang mengatur tentang pengadaan, seperti adanya dokumen pengadaan yang memuat dengan jelas sesuai dengan spesifikasi teknis (logo, label, dan warna).
2) Pengadaan logistik dari sumber lain dilakukan oleh pihak pemberi bantuan.
b. Penerimaan Monitoring dan evaluasi yang dilakukan pada tahap penerimaan adalah untuk memeriksa:
a. Kesesuaian logistik yang diterima dengan perencanaan, kebutuhan dan standar minimal sesuai peraturan yang mengatur tentang standar minimal logistik.
b. Kesesuaian logistik yang diterima dengan spesifikasi yang ditentukan dalam proses pengadaan:
1) Konsistensi satuan terkecil 2) Jumlah, jenis, waktu dan kondisi logistik pada saat diterima 3) Tanggal kadaluarsa 4) Waktu pengiriman logistik
c. Dokumen Berita Acara Serah Terima (Lampiran 5.4)
d. Proses penerimaan logistik: pemeriksaan dan pencatatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7659, 'g. Pemutakhiran data.
Dalam hal perencanaan bantuan logistik yang melibatkan lembaga internasional dan lembaga asing nonpemerintah, koordinator cluster bertanggung jawab untuk melakukan monitoring dalam perencanaan 12 bantuan logistik sesuai dengan spesifikasi yang diperlukan berdasarkan peraturan perundangan yang mengatur peran serta lembaga internasional dan lembaga asing nonpemerintah pada saat tanggap darurat.
2. Pengadaan dan Penerimaan (Lampiran 3)
a. Pengadaan 1) Pengadaan Logistik BNPB/BPBD Pengadaan logistik berdasarkan pagu anggaran dan mekanisme yang dilakukan sesuai peraturan yang mengatur tentang pengadaan, seperti adanya dokumen pengadaan yang memuat dengan jelas sesuai dengan spesifikasi teknis (logo, label, dan warna).
2) Pengadaan logistik dari sumber lain dilakukan oleh pihak pemberi bantuan.
b. Penerimaan Monitoring dan evaluasi yang dilakukan pada tahap penerimaan adalah untuk memeriksa:
a. Kesesuaian logistik yang diterima dengan perencanaan, kebutuhan dan standar minimal sesuai peraturan yang mengatur tentang standar minimal logistik.
b. Kesesuaian logistik yang diterima dengan spesifikasi yang ditentukan dalam proses pengadaan:
1) Konsistensi satuan terkecil 2) Jumlah, jenis, waktu dan kondisi logistik pada saat diterima 3) Tanggal kadaluarsa 4) Waktu pengiriman logistik
c. Dokumen Berita Acara Serah Terima (Lampiran 5.4)
d. Proses penerimaan logistik: pemeriksaan dan pencatatan.', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 20 Tahun 2011 tentang Pedoman Monitoring dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7660, 'perka-20-2011', 26, 'lampiran', 'Lampiran hal. 18', NULL, 18, '3. Pergudangan (Lampiran 4) Monitoring dan evaluasi dilakukan untuk memeriksa:
a. Kesesuaian gudang dengan spesifikasi gudang (nasional, provinsi, kabupaten/kota) yang telah ditetapkan oleh BNPB seperti lokasi yang bebas bencana, Aksesibilitas mudah, keamanan, kondisi gudang, peralatan, pemilahan logistik, logistik yang terdata dan penataan sesuai peraturan yang mengatur tentang pergudangan.
b. Penggunaan formulir penerimaan, pengeluaran, penyimpanan dan pergudangan sesuai dengan standar, mencakup jenis logistik.
4. Penyaluran/Pengeluaran Barang (Lampiran 5) Monitoring dan evaluasi dilakukan untuk memeriksa hal-hal sebagai berikut:
a. Dokumen permintaan pengeluaran logistik yang sudah di verifikasi juga memuat nama pejabat yang memiliki kewenangan untuk pengeluaran barang.
13
b. Pengisian dokumen pengeluaran logistik sesuai peraturan (formulir 5.2).
c. Surat jalan pengeluaran logistik dari gudang.
d. Berita Acara Serah Terima yang telah ditandatangani.
5. Pengangkutan (Lampiran 6) Monitoring dan evaluasi dilakukan untuk memeriksa hal-hal sebagai berikut:
a. Pemilihan moda transportasi yang sesuai.
b. Monitoring proses pengangkutan.
6. Pendistribusian (Lampiran 7) Monitoring dan evaluasi pada tahap pendistribusian untuk memeriksa hal-hal sebagai berikut:
a. Kesesuaian jumlah, jenis, waktu kadaluarsa dan kondisi logistik yang didistribusikan.
b. Daftar penerima bantuan logistik sesuai dengan rencana distribusi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7660, '3. Pergudangan (Lampiran 4) Monitoring dan evaluasi dilakukan untuk memeriksa:
