INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7661, 'perka-20-2011', 27, 'lampiran', 'Lampiran hal. 19', NULL, 19, 'c. Tertib administrasi distribusi bantuan logistik dengan didukung Berita Acara Serah Terima Bantuan
d. Kecepatan dan ketepatan pendistribusian logistik khusus pada masa tanggap darurat
e. Dokumentasi.
Dalam hal pendistribusian oleh BPBD sampai kepada penerima bantuan, maka BNPB dapat berkoordinasi dengan BPBD untuk melakukan uji petik pelaksanaan monitoring dan evaluasi.
7. Penghapusan (Lampiran 8) Monitoring dan evaluasi dilakukan untuk memeriksa hal-hal sebagai berikut:
a. Daftar logistik yang rusak, hilang dan kadaluarsa akan dihapus dengan persetujuan pejabat yang memiliki kewenangan untuk penghapusan barang.
b. Proses penghapusan logistik sesuai peraturan yang mengatur tentang penghapusan.
c. Dokumen Berita Acara penghapusan logistik.
d. Dokumentasi penghapusan logistik.
8. Manfaat Bantuan Logistik (Lampiran 9).
Monitoring dan evaluasi dilakukan untuk mengetahui:
a. Manfaat logistik yang diberikan pada saat pra bencana, saat tanggap darurat dan pasca bencana.
b. Manfaat logistik sesuai dengan peruntukannya.
c. Manfaat logistik dengan kebutuhan korban jiwa dan masyarakat terdampak.
d. Manfaat logistik sesuai kelompok rentan.
G. Laporan Monitoring dan Evaluasi (lampiran 1) 14
1. Setelah pengumpulan data dan hasil analisa diperoleh, Tim Monitoring dan Evaluasi menyiapkan laporan sesuai dengan format Laporan Monitoring dan Evaluasi yang diterbitkan oleh BNPB/BPBD. Laporan diserahkan kepada pimpinan bidang logistik dan peralatan dengan ketentuan:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7661, 'c. Tertib administrasi distribusi bantuan logistik dengan didukung Berita Acara Serah Terima Bantuan
