INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7692, 'Menetapkan 1 PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN MONITORING DAN EVALUASI MANAJEMEN PERALATAN PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2011 tentang Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7693, 'perka-21-2011', 4, 'pasal', 'Pasal 1', NULL, 4, 'Pedoman Monitoring Dan Evaluasi Manajemen Peralatan Penanggulangan Bencana merupakan panduan/acuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/lembaga dan pemangku kepentingan penanggulangan bencana lainnya agar pelaksanaan monitoring dan evaluasi manajemen peralatan penanggulangan bencana dapat dilakukan dengan lancar, tertib, terpadu, aman dan dapat dipertanggungjawabkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7693, 'Pedoman Monitoring Dan Evaluasi Manajemen Peralatan Penanggulangan Bencana merupakan panduan/acuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/lembaga dan pemangku kepentingan penanggulangan bencana lainnya agar pelaksanaan monitoring dan evaluasi manajemen peralatan penanggulangan bencana dapat dilakukan dengan lancar, tertib, terpadu, aman dan dapat dipertanggungjawabkan.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2011 tentang Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7694, 'perka-21-2011', 5, 'pasal', 'Pasal 2', NULL, 4, 'Pedoman sebagaimana dimaksud dalam Pasal 1 tercantum dalam Lampiran Peraturan ini dan merupakan bagian yang tidak terpisahkan dari Peraturan ini.');
