INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7696, 'Ditetapkan di Jakarta pada tanggal 30 Desember 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, Ay , DR. SYAMSUL MAARIF, M.Si.
PEDOMAN MONITORING DAN EVALUASI MANAJEMEN PERALATAN BADAN NASIONAL PENANGGULANGAN BENCANA (BNPB) 1', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2011 tentang Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7697, 'perka-21-2011', 8, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 21 TAHUN 2011 TANGGAL : 30 DESEMBER 2011 BAB I PENDAHULUAN A. Latar Belakang Berbagai kemajuan signifikan dalam penanggulangan bencana selama beberapa tahun terakhir telah menjadikan Indonesia sebagai salah satu negara yang sangat progresif dalam upaya penanggulangan bencana untuk membangun ketangguhan masyarakatnya. Sebagai salah satu negara yang paling rentan terhadap bencana serta adanya ancaman yang relatif cukup jelas yang disebabkan kondisi geografis dan komposisi demografi, Indonesia masih akan terus mengalami dan mengelola bencana.
Bencana yang sering terjadi di Indonesia adalah banjir, kebakaran, angin topan, longsor, kekeringan dan gempa bumi. Tercatat 2.836 kejadian bencana antara tahun 2008-2010 yang menyebabkan 4.216 orang meninggal, 999 orang hilang, 1.067.103 orang mengungsi,dan 653.876 rumah rusak, serta 14.526 unit sarana dan prasarana rusak. (data pusdatin BNPB 2011) Dalam rangka meringankan beban masyarakat yang terkena bencana, pemerintah melalui BNPB memobilisasi logistik dari berbagai sumber daya untuk menghadapi berbagai bencana yang terjadi di Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7697, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 21 TAHUN 2011 TANGGAL : 30 DESEMBER 2011 BAB I PENDAHULUAN A. Latar Belakang Berbagai kemajuan signifikan dalam penanggulangan bencana selama beberapa tahun terakhir telah menjadikan Indonesia sebagai salah satu negara yang sangat progresif dalam upaya penanggulangan bencana untuk membangun ketangguhan masyarakatnya. Sebagai salah satu negara yang paling rentan terhadap bencana serta adanya ancaman yang relatif cukup jelas yang disebabkan kondisi geografis dan komposisi demografi, Indonesia masih akan terus mengalami dan mengelola bencana.
Bencana yang sering terjadi di Indonesia adalah banjir, kebakaran, angin topan, longsor, kekeringan dan gempa bumi. Tercatat 2.836 kejadian bencana antara tahun 2008-2010 yang menyebabkan 4.216 orang meninggal, 999 orang hilang, 1.067.103 orang mengungsi,dan 653.876 rumah rusak, serta 14.526 unit sarana dan prasarana rusak. (data pusdatin BNPB 2011) Dalam rangka meringankan beban masyarakat yang terkena bencana, pemerintah melalui BNPB memobilisasi logistik dari berbagai sumber daya untuk menghadapi berbagai bencana yang terjadi di Indonesia.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2011 tentang Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7698, 'perka-21-2011', 9, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'Peralatan dibutuhkan di setiap tahapan kegiatan penanggulangan bencana (PB) baik kesiapsiagaan, tanggap darurat, pemulihan, rehabilitasi dan rekonstruksi. Sejak tahun 2009 BNPB telah memberikan dukungan Logistik dan Peralatan bagi BPBD Provinsi untuk penguatan kelembagaan dalam rangka kesiapsiagaan dan memberikan bantuan logistik dan peralatan bagi kabupaten / kota yang terkena bencana pada masa tanggap darurat atas usulan BPBD Provinsi. Bantuan kemanusiaan juga diberikan kepada negara yang terkena bencana seperti Pakistan, Haiti dan Jepang.
Dalam upaya mengukur pencapaian keberhasilan pelaksanaan Manajemen Peralatan PB dan menganalisa manfaat bantuan peralatan yang diberikan, diperlukan monitoring dan evaluasi secara komprehensif dimulai dari perencanaan, pengadaan, penerimaan, pergudangan, penyaluran, pengangkutan, pendistribusian, pemeliharaan sampai dengan penghapusan.
Untuk itu dipandang perlu menyusun Pedoman Monitoring dan Evaluasi Manajemen Peralatan.
1 B. Maksud dan Tujuan
1. Maksud Sebagai panduan pelaksanaan kegiatan manajemen Peralatan PB bagi Kementerian / Lembaga khususnya BNPB, Organisasi Perangkat Daerah (OPD) termasuk BPBD, serta Organisasi Nonpemerintah dalam melaksanakan monitoring dan evaluasi manajemen Peralatan, sesuai peraturan perundang – undangan.
2. Tujuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7698, 'Peralatan dibutuhkan di setiap tahapan kegiatan penanggulangan bencana (PB) baik kesiapsiagaan, tanggap darurat, pemulihan, rehabilitasi dan rekonstruksi. Sejak tahun 2009 BNPB telah memberikan dukungan Logistik dan Peralatan bagi BPBD Provinsi untuk penguatan kelembagaan dalam rangka kesiapsiagaan dan memberikan bantuan logistik dan peralatan bagi kabupaten / kota yang terkena bencana pada masa tanggap darurat atas usulan BPBD Provinsi. Bantuan kemanusiaan juga diberikan kepada negara yang terkena bencana seperti Pakistan, Haiti dan Jepang.
Dalam upaya mengukur pencapaian keberhasilan pelaksanaan Manajemen Peralatan PB dan menganalisa manfaat bantuan peralatan yang diberikan, diperlukan monitoring dan evaluasi secara komprehensif dimulai dari perencanaan, pengadaan, penerimaan, pergudangan, penyaluran, pengangkutan, pendistribusian, pemeliharaan sampai dengan penghapusan.
Untuk itu dipandang perlu menyusun Pedoman Monitoring dan Evaluasi Manajemen Peralatan.
1 B. Maksud dan Tujuan
1. Maksud Sebagai panduan pelaksanaan kegiatan manajemen Peralatan PB bagi Kementerian / Lembaga khususnya BNPB, Organisasi Perangkat Daerah (OPD) termasuk BPBD, serta Organisasi Nonpemerintah dalam melaksanakan monitoring dan evaluasi manajemen Peralatan, sesuai peraturan perundang – undangan.
2. Tujuan', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2011 tentang Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7699, 'perka-21-2011', 10, 'lampiran', 'Lampiran hal. 7', NULL, 7, 'a. Memastikan setiap bantuan peralatan yang didistribusikan sesuai dengan kebutuhan masyarakat yang terkena bencana, melalui proses manajemen peralatan sesuai peraturan perundangan yang berlaku sampai dengan tingkat kabupaten/kota. a)
b. Membantu BNPB dan BPBD dalam pengambilan keputusan manajemen peralatan secara tepat.
c. Mengkaji sejauh mana strategi manajemen peralatan yang dikembangkan oleh BNPB/BPBD menjawab masalah penanggulangan bencana yang dikoordinasikan oleh BNPB/BPBD.
d. Memberikan masukan, saran atau ide ke pelaksana manajemen peralatan dan penerima bantuan untuk pelaksanaan kegiatan yang akan datang.
e. Mengidentifikasi faktor-faktor pendukung dan penghambat pencapaian tujuan program.
f. Membuat penilaian apakah semua sumber daya yang ada telah dipergunakan secara optimal.
A.
B.
C. Pengertian
1. Manajemen Peralatan Manajemen Peralatan adalah proses pengelolaan peralatan penanggulangan bencana (PB) yang meliputi perencanaan/inventarisasi kebutuhan, pengadaan dan/atau penerimaan, pergudangan dan/atau penyimpanan, pendistribusian, pengangkutan, penerimaan di tujuan, penghapusan dan pemeliharaan.
2. Monitoring Monitoring adalah kegiatan memantau perkembangan pelaksanaan manajemen peralatan dan mengidentifikasi, serta mengantisipasi permasalahan yang timbul untuk dapat diambil tindakan sedini mungkin.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7699, 'a. Memastikan setiap bantuan peralatan yang didistribusikan sesuai dengan kebutuhan masyarakat yang terkena bencana, melalui proses manajemen peralatan sesuai peraturan perundangan yang berlaku sampai dengan tingkat kabupaten/kota. a)
b. Membantu BNPB dan BPBD dalam pengambilan keputusan manajemen peralatan secara tepat.
c. Mengkaji sejauh mana strategi manajemen peralatan yang dikembangkan oleh BNPB/BPBD menjawab masalah penanggulangan bencana yang dikoordinasikan oleh BNPB/BPBD.
d. Memberikan masukan, saran atau ide ke pelaksana manajemen peralatan dan penerima bantuan untuk pelaksanaan kegiatan yang akan datang.
e. Mengidentifikasi faktor-faktor pendukung dan penghambat pencapaian tujuan program.
f. Membuat penilaian apakah semua sumber daya yang ada telah dipergunakan secara optimal.
A.
B.
C. Pengertian
1. Manajemen Peralatan Manajemen Peralatan adalah proses pengelolaan peralatan penanggulangan bencana (PB) yang meliputi perencanaan/inventarisasi kebutuhan, pengadaan dan/atau penerimaan, pergudangan dan/atau penyimpanan, pendistribusian, pengangkutan, penerimaan di tujuan, penghapusan dan pemeliharaan.
2. Monitoring Monitoring adalah kegiatan memantau perkembangan pelaksanaan manajemen peralatan dan mengidentifikasi, serta mengantisipasi permasalahan yang timbul untuk dapat diambil tindakan sedini mungkin.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2011 tentang Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7700, 'perka-21-2011', 11, 'lampiran', 'Lampiran hal. 7', NULL, 7, '3. Evaluasi 2 Evaluasi adalah rangkaian kegiatan membandingkan realisasi masukan (input), keluaran (output), dan hasil (outcome) terhadap rencana dan standar. Evaluasi melihat manfaat untuk perencanaan selanjutnya.
4. Bantuan darurat bencana adalah bantuan yang diberikan untuk memenuhi kebutuhan dasar pada saat keadaan darurat.
5. Logistik adalah segala sesuatu yang berwujud dan dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri atas sandang, pangan dan papan atau turunannya. Termasuk dalam kategori Logistik adalah barang yang habis dipakai atau dikonsumsi, misalnya: Sembako (sembilan bahan pokok), obat, pakaian dan kelengkapannya, air, tenda, baju tidur dan sebagainya.
6. Peralatan dalam PB adalah segala bentuk alat dan peralatan yang dapat dipergunakan untuk membantu penyelamatan dan evakuasi masyarakat terkena bencana, pemenuhan kebutuhan dasar, dan pemulihan segera prasarana dan sarana vital. Misalnya : Mobil Resque, Motor Resque, Tenda, perahu karet, Mobil dapur lapangan, Mobil penjernih air, dan sebagainya.
1. 2.
3. 4.
5. 6.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7700, '3. Evaluasi 2 Evaluasi adalah rangkaian kegiatan membandingkan realisasi masukan (input), keluaran (output), dan hasil (outcome) terhadap rencana dan standar. Evaluasi melihat manfaat untuk perencanaan selanjutnya.
4. Bantuan darurat bencana adalah bantuan yang diberikan untuk memenuhi kebutuhan dasar pada saat keadaan darurat.
5. Logistik adalah segala sesuatu yang berwujud dan dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri atas sandang, pangan dan papan atau turunannya. Termasuk dalam kategori Logistik adalah barang yang habis dipakai atau dikonsumsi, misalnya: Sembako (sembilan bahan pokok), obat, pakaian dan kelengkapannya, air, tenda, baju tidur dan sebagainya.
6. Peralatan dalam PB adalah segala bentuk alat dan peralatan yang dapat dipergunakan untuk membantu penyelamatan dan evakuasi masyarakat terkena bencana, pemenuhan kebutuhan dasar, dan pemulihan segera prasarana dan sarana vital. Misalnya : Mobil Resque, Motor Resque, Tenda, perahu karet, Mobil dapur lapangan, Mobil penjernih air, dan sebagainya.
