INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7701, 'perka-21-2011', 12, 'lampiran', 'Lampiran hal. 8', NULL, 8, '7. Pendekatan Cluster adalah suatu model koordinasi dengan mengelompokkan para pelaku kemanusiaan berdasarkan gugus kerja untuk memberikan respon darurat yang lebih dapat diperkirakan dengan penetapan ‘pimpinan’ kelompok/cluster. Pendekatan Cluster dilaksanakan pada kejadian bencana berskala besar atau membutuhkan bantuan internasional dalam respon multi-sektor dengan partisipasi luas dari para pelaku kemanusiaan internasional. Pimpinan Cluster bersama-sama dengan sektor-sektor Pemerintah membangun koordinasi baik dalam perencanaan maupun pelaksanaan. Pendekatan Cluster bertujuan agar bantuan respon darurat dapat dilaksanakan secara lebih terkoordinasi antar pelaku baik dari pemerintah maupun nonpemerintah.
8. Pos Komando (Posko) adalah pusat pengkoordinasian, pengendalian, monitoring dan evaluasi penanganan tanggap darurat yang juga memiliki kewenangan dalam memberikan data dan informasi tentang penanganan tanggap darurat bencana.
9. Buffer Stock atau Safety Stock adalah peralatan yang berasal dari pembelian BNPB serta sumber – sumber lainnya yang masuk dalam gudang BNPB / BPBD dan Posko untuk kesiapsiagaan.
3
10. Perencanaan adalah langkah – langkah awal untuk mengetahui apa yang dibutuhkan, siapa yang membutuhkan, di mana, kapan dan bagaimana cara menyampaikan kebutuhannya.
11. Pengadaan dan penerimaan adalah suatu proses tersedianya barang dan jasa sesuai dengan peraturan yang berlaku');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7701, '7. Pendekatan Cluster adalah suatu model koordinasi dengan mengelompokkan para pelaku kemanusiaan berdasarkan gugus kerja untuk memberikan respon darurat yang lebih dapat diperkirakan dengan penetapan ‘pimpinan’ kelompok/cluster. Pendekatan Cluster dilaksanakan pada kejadian bencana berskala besar atau membutuhkan bantuan internasional dalam respon multi-sektor dengan partisipasi luas dari para pelaku kemanusiaan internasional. Pimpinan Cluster bersama-sama dengan sektor-sektor Pemerintah membangun koordinasi baik dalam perencanaan maupun pelaksanaan. Pendekatan Cluster bertujuan agar bantuan respon darurat dapat dilaksanakan secara lebih terkoordinasi antar pelaku baik dari pemerintah maupun nonpemerintah.
8. Pos Komando (Posko) adalah pusat pengkoordinasian, pengendalian, monitoring dan evaluasi penanganan tanggap darurat yang juga memiliki kewenangan dalam memberikan data dan informasi tentang penanganan tanggap darurat bencana.
9. Buffer Stock atau Safety Stock adalah peralatan yang berasal dari pembelian BNPB serta sumber – sumber lainnya yang masuk dalam gudang BNPB / BPBD dan Posko untuk kesiapsiagaan.
3
10. Perencanaan adalah langkah – langkah awal untuk mengetahui apa yang dibutuhkan, siapa yang membutuhkan, di mana, kapan dan bagaimana cara menyampaikan kebutuhannya.
11. Pengadaan dan penerimaan adalah suatu proses tersedianya barang dan jasa sesuai dengan peraturan yang berlaku', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2011 tentang Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7702, 'perka-21-2011', 13, 'lampiran', 'Lampiran hal. 9', NULL, 9, '12. Pergudangan adalah segala upaya pengelolaan peralatan digudang yang meliputi penerimaan, pencatatan, penyimpanan, pemeliharaan, pendistribusian, pengendalian dan penghapusan serta pelaporan agar kualitas dan kuantitas peralatan PB tetap terjamin
13. Penyaluran adalah suatu sistem penyaluran dan atau pembagian bantuan peralatan dari BNPB ke BPBD dalam rangka kesiapsiagaan penanggulangan bencana.
14. Pengangkutan adalah proses memindahkan peralatan dari gudang penyimpanan ke lokasi tujuan.
15. Pendistribusian adalah suatu sistem penyaluran dan atau pengiriman bantuan peralatan dalam rangka penanggulangan bencana dari gudang penyimpanan ke lokasi tujuan sampai pada sasaran.
16. Penghapusan adalah tindakan menghapus Barang Milik Negara (peralatan) dari daftar barang dengan menerbitkan surat keputusan dari pejabat yang berwenang untuk membebaskan pengguna barang (peralatan) dari tanggung jawab administrasi dan peralatan yang berada dalam penguasaannya.
17. Operasional dan Pemeliharaan adalah pengoperasian dan perawatan peralatan agar kondisi tetap terjamin dan siap pakai untuk dipergunakan dalam penanggulangan bencana secara efektif, efisien dan akuntabel.
D. Prinsip Untuk menjamin terselenggaranya penanggulangan bencana secara terencana, terpadu, terkoordinasi cepat dan tepat, diperlukan prinsip-prinsip sebagai berikut :
1. Bertanggung jawab.
BNPB dan BPBD bertanggung jawab terhadap kegiatan monitoring dan evaluasi manajemen peralatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7702, '12. Pergudangan adalah segala upaya pengelolaan peralatan digudang yang meliputi penerimaan, pencatatan, penyimpanan, pemeliharaan, pendistribusian, pengendalian dan penghapusan serta pelaporan agar kualitas dan kuantitas peralatan PB tetap terjamin
13. Penyaluran adalah suatu sistem penyaluran dan atau pembagian bantuan peralatan dari BNPB ke BPBD dalam rangka kesiapsiagaan penanggulangan bencana.
14. Pengangkutan adalah proses memindahkan peralatan dari gudang penyimpanan ke lokasi tujuan.
15. Pendistribusian adalah suatu sistem penyaluran dan atau pengiriman bantuan peralatan dalam rangka penanggulangan bencana dari gudang penyimpanan ke lokasi tujuan sampai pada sasaran.
16. Penghapusan adalah tindakan menghapus Barang Milik Negara (peralatan) dari daftar barang dengan menerbitkan surat keputusan dari pejabat yang berwenang untuk membebaskan pengguna barang (peralatan) dari tanggung jawab administrasi dan peralatan yang berada dalam penguasaannya.
17. Operasional dan Pemeliharaan adalah pengoperasian dan perawatan peralatan agar kondisi tetap terjamin dan siap pakai untuk dipergunakan dalam penanggulangan bencana secara efektif, efisien dan akuntabel.
D. Prinsip Untuk menjamin terselenggaranya penanggulangan bencana secara terencana, terpadu, terkoordinasi cepat dan tepat, diperlukan prinsip-prinsip sebagai berikut :
1. Bertanggung jawab.
BNPB dan BPBD bertanggung jawab terhadap kegiatan monitoring dan evaluasi manajemen peralatan.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2011 tentang Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7703, 'perka-21-2011', 14, 'lampiran', 'Lampiran hal. 9', NULL, 9, '2. Mengacu pada Sistem Manajemen Peralatan.
Monitoring dan evaluasi manajemen peralatan mengacu kepada kegiatan perencanaan, pengadaan dan penerimaan, pergudangan, penyaluran, pengangkutan, pendistribusian, operasional dan pemeliharaan serta penghapusan.
3. Koordinasi.
Pelaksanaan monitoring dan evaluasi manajemen Peralatan dilaksanakan melalui koordinasi secara aktif dengan Kementerian / Lembaga khususnya 4 BNPB, Organisasi Perangkat Daerah (OPD) termasuk BPBD, serta Organisasi nonpemerintah.
4. Tata kelola pemerintahan yang baik. (Good Governance) Pelaksanaan monitoring dan evaluasi manajemen Peralatan berdasarkan prinsip tata kelola pemerintahan yang baik antara lain : prioritas; koordinasi dan keterpaduan; berdaya guna dan berhasil guna; keberlanjutan program; transparansi; akuntabilitas; kemitraan; dan pemberdayaan.
E. Landasan Hukum
1. Undang – Undang No. 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Peraturan Presiden Nomor 8 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
3. Peraturan Presiden Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
4. Peraturan Presiden Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
5. Peraturan Presiden Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non Pemerintah Dalam Penanggulangan Bencana.
6. Peraturan Presiden Nomor 54 Tahun 2010 tentang Pengadaan Barang dan Jasa.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7703, '2. Mengacu pada Sistem Manajemen Peralatan.
Monitoring dan evaluasi manajemen peralatan mengacu kepada kegiatan perencanaan, pengadaan dan penerimaan, pergudangan, penyaluran, pengangkutan, pendistribusian, operasional dan pemeliharaan serta penghapusan.
3. Koordinasi.
Pelaksanaan monitoring dan evaluasi manajemen Peralatan dilaksanakan melalui koordinasi secara aktif dengan Kementerian / Lembaga khususnya 4 BNPB, Organisasi Perangkat Daerah (OPD) termasuk BPBD, serta Organisasi nonpemerintah.
4. Tata kelola pemerintahan yang baik. (Good Governance) Pelaksanaan monitoring dan evaluasi manajemen Peralatan berdasarkan prinsip tata kelola pemerintahan yang baik antara lain : prioritas; koordinasi dan keterpaduan; berdaya guna dan berhasil guna; keberlanjutan program; transparansi; akuntabilitas; kemitraan; dan pemberdayaan.
E. Landasan Hukum
1. Undang – Undang No. 24 Tahun 2007 tentang Penanggulangan Bencana.
2. Peraturan Presiden Nomor 8 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
3. Peraturan Presiden Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
4. Peraturan Presiden Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
5. Peraturan Presiden Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non Pemerintah Dalam Penanggulangan Bencana.
6. Peraturan Presiden Nomor 54 Tahun 2010 tentang Pengadaan Barang dan Jasa.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2011 tentang Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7704, 'perka-21-2011', 15, 'lampiran', 'Lampiran hal. 10', NULL, 10, '7. Peraturan Menteri Keuangan Nomor 120/PMK.06/2007 tentang Penatausahaan Barang Milik Negara.
8. Peraturan Menteri Keuangan Nomor 168/PMK.07/2008 tentang Hibah Daerah.
9. Peraturan Kepala BNPB Nomor 13 Tahun 2008 tentang Manajemen Logistik dan Peralatan.
10. Peraturan Menteri Dalam Negeri nomor 46 tahun 2008 tentang Pedoman Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah.
11. Peraturan Kepala BNPB Nomor 05 Tahun 2009 tentang Pedoman Bantuan peralatan.
12. Peraturan Kepala BNPB Nomor 06 Tahun 2009 tentang Pergudangan
13. Peraturan Kepala BNPB Nomor 17 Tahun 2009 tentang Pedoman Standarisasi Peralatan.
14. Peraturan Kepala BNPB Nomor 18 Tahun 2010 tentang Pedoman Distribusi Logistik dan Peralatan PB.
15. Peraturan Kepala BNPB Nomor 19 Tahun 2010 tentang Pedoman Penghapusan.
16. Peraturan Kepala BNPB Nomor 22 Tahun 2010 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah Pada Masa Tanggap Darurat.
D.
E.
F. Ruang Lingkup 5 Ruang lingkup pembahasan pedoman ini adalah monitoring dan evaluasi sistem manajemen peralatan.
G. Sistematika Pedoman Monitoring dan Evaluasi Manajemen peralatan ini disusun dengan sistematika sebagai berikut:
BAB I PENDAHULUAN BAB II SISTEM MANAJEMEN PERALATAN BAB III MONITORING DAN EVALUASI MANAJEMEN PERALATAN BAB IV PENUTUP LAMPIRAN BAB II SISTEM MANAJEMEN PERALATAN A. Sistem Manajemen Peralatan Sistem Manajemen Peralatan PB yang dilaksanakan oleh BNPB dan BPBD meliputi tahapan-tahapan sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7704, '7. Peraturan Menteri Keuangan Nomor 120/PMK.06/2007 tentang Penatausahaan Barang Milik Negara.
8. Peraturan Menteri Keuangan Nomor 168/PMK.07/2008 tentang Hibah Daerah.
9. Peraturan Kepala BNPB Nomor 13 Tahun 2008 tentang Manajemen Logistik dan Peralatan.
10. Peraturan Menteri Dalam Negeri nomor 46 tahun 2008 tentang Pedoman Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah.
11. Peraturan Kepala BNPB Nomor 05 Tahun 2009 tentang Pedoman Bantuan peralatan.
12. Peraturan Kepala BNPB Nomor 06 Tahun 2009 tentang Pergudangan
13. Peraturan Kepala BNPB Nomor 17 Tahun 2009 tentang Pedoman Standarisasi Peralatan.
14. Peraturan Kepala BNPB Nomor 18 Tahun 2010 tentang Pedoman Distribusi Logistik dan Peralatan PB.
15. Peraturan Kepala BNPB Nomor 19 Tahun 2010 tentang Pedoman Penghapusan.
16. Peraturan Kepala BNPB Nomor 22 Tahun 2010 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah Pada Masa Tanggap Darurat.
D.
E.
F. Ruang Lingkup 5 Ruang lingkup pembahasan pedoman ini adalah monitoring dan evaluasi sistem manajemen peralatan.
G. Sistematika Pedoman Monitoring dan Evaluasi Manajemen peralatan ini disusun dengan sistematika sebagai berikut:
BAB I PENDAHULUAN BAB II SISTEM MANAJEMEN PERALATAN BAB III MONITORING DAN EVALUASI MANAJEMEN PERALATAN BAB IV PENUTUP LAMPIRAN BAB II SISTEM MANAJEMEN PERALATAN A. Sistem Manajemen Peralatan Sistem Manajemen Peralatan PB yang dilaksanakan oleh BNPB dan BPBD meliputi tahapan-tahapan sebagai berikut:', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2011 tentang Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7705, 'perka-21-2011', 16, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'Pendistribusian Perencanaan Pengadaan Penyaluran operasional (kepada BPBD ; dan Pergudang (dari BNPB Pengang & atau Posko pada Penghapusan Inventarisasi Penerimaan an kepada kutan Pemelihara saat tanggap Kebutuhan BPBD) an darurat) Pelaporan
1. Perencanaan/Inventarisasi Kebutuhan Maksud dan tujuan perencanaan/inventarisasi kebutuhan adalah :
1) Pemetaan dan pendataan peralatan secara nasional, Provinsi dan Kabupaten / Kota dan data dengan sumber daya peralatannya.
2) Kebutuhan peralatan minimal per wilayah (Provinsi/kabupaten/kota).
3) Rencana mobilisasi untuk mengisi kekurangan peralatan pada suatu wilayah.
4) Analisa kesenjangan kebutuhan.
5) Ketersediaan sumber daya di daerah.
2. Pengadaan dan Penerimaan 6 Maksud dan tujuan pengadaan adalah:
a. Membuat rencana pengadaan berdasarkan rencana kontinjensi dan inventarisasi ketersediaan wilayah
b. Membuat permintaan pengadaan peralatan kepada Panitia pengadaan sesuai peraturan Perundang – undangan.
c. Pada saat masa tanggap darurat dapat dilakukan mekanisme yang berlaku sesuai dengan Peraturan Perundang – undangan.
Maksud dan tujuan penerimaan adalah:
a. Mengetahui jenis peralatan yang diterima dari berbagai sumber.
b. Untuk mencocokkan antara kebutuhan dengan ketersediaan peralatan.
c. Menginformasikan peralatan sesuai skala prioritas kebutuhan.
d. Sebagai upaya pengendalian dan pengawasan penggunaan peralatan.
e. Untuk menyesuaikan dalam hal penyimpanan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7705, 'Pendistribusian Perencanaan Pengadaan Penyaluran operasional (kepada BPBD ; dan Pergudang (dari BNPB Pengang & atau Posko pada Penghapusan Inventarisasi Penerimaan an kepada kutan Pemelihara saat tanggap Kebutuhan BPBD) an darurat) Pelaporan
1. Perencanaan/Inventarisasi Kebutuhan Maksud dan tujuan perencanaan/inventarisasi kebutuhan adalah :
1) Pemetaan dan pendataan peralatan secara nasional, Provinsi dan Kabupaten / Kota dan data dengan sumber daya peralatannya.
2) Kebutuhan peralatan minimal per wilayah (Provinsi/kabupaten/kota).
3) Rencana mobilisasi untuk mengisi kekurangan peralatan pada suatu wilayah.
4) Analisa kesenjangan kebutuhan.
5) Ketersediaan sumber daya di daerah.
2. Pengadaan dan Penerimaan 6 Maksud dan tujuan pengadaan adalah:
a. Membuat rencana pengadaan berdasarkan rencana kontinjensi dan inventarisasi ketersediaan wilayah
b. Membuat permintaan pengadaan peralatan kepada Panitia pengadaan sesuai peraturan Perundang – undangan.
c. Pada saat masa tanggap darurat dapat dilakukan mekanisme yang berlaku sesuai dengan Peraturan Perundang – undangan.
Maksud dan tujuan penerimaan adalah:
a. Mengetahui jenis peralatan yang diterima dari berbagai sumber.
b. Untuk mencocokkan antara kebutuhan dengan ketersediaan peralatan.
