INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7707, 'perka-21-2011', 18, 'lampiran', 'Lampiran hal. 13', NULL, 13, '6. Penerimaan Maksud dan Tujuan penerimaan di tujuan adalah untuk memastikan jumlah, jenis dan kondisi barang yang diterima sesuai dengan permintaan/kebutuhan.
7. Operasional dan Pemeliharaan Maksud dan Tujuan operasional dan pemeliharaan adalah untuk:
a. Memastikan jenis barang yang diterima dirawat sesuai dengan ketentuan.
b. Memastikan kondisi peralatan tetap terjamin dan siap dipakai dalam penanggulangan bencana.
8. Penghapusan Maksud dan tujuan penghapusan adalah untuk:
a. Memastikan barang yang hilang / rusak, tidak layak pakai dan tidak bernilai ekonomis dihapuskan sesuai dengan peraturan perundangan – undangan.
b. Mengeluarkan barang milik negara dari pertanggung jawaban administrasi.
B. Sistem Manajemen Informasi Tahapan manajemen peralatan dapat dijalankan secara profesional, maka diperlukan sistem manajemen informasi untuk dapat memenuhi kebutuhan:
1. Pemetaan dan pendataan peralatan sesuai dengan yang sudah diatur dalam huruf A angka 1 point b di dalam perencanaan.
2. Sistem pendataan barang milik negara yang tersedia C. Laporan pertanggungjawaban Setiap penyelesaian keseluruhan tahapan sistem manajemen peralatan, laporan pertanggungjawaban sesuai dengan format Laporan Pertanggungjawaban diterbitkan oleh BNPB/BPBD (formulir 5.4) dan diserahkan kepada Kepala BNPB melalui Deputi Bidang Logistik dan Peralatan BNPB setiap akhir bulan atau selambat – lambatnya setiap 3 (tiga) bulan .');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7707, '6. Penerimaan Maksud dan Tujuan penerimaan di tujuan adalah untuk memastikan jumlah, jenis dan kondisi barang yang diterima sesuai dengan permintaan/kebutuhan.
7. Operasional dan Pemeliharaan Maksud dan Tujuan operasional dan pemeliharaan adalah untuk:
a. Memastikan jenis barang yang diterima dirawat sesuai dengan ketentuan.
b. Memastikan kondisi peralatan tetap terjamin dan siap dipakai dalam penanggulangan bencana.
8. Penghapusan Maksud dan tujuan penghapusan adalah untuk:
