INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7712, 'perka-21-2011', 23, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'Dalam hal perencanaan bantuan peralatan yang melibatkan lembaga internasional dan lembaga asing Nonpemerintah, koordinator cluster bertanggung jawab untuk melakukan monitoring dalam perencanaan bantuan peralatan sesuai dengan spesifikasi yang diperlukan berdasarkan peraturan perundang – undangan yang mengatur peran serta lembaga internasional dan lembaga asing Nonpemerintah pada saat tanggap darurat.
2. Pengadaan dan Penerimaan (Lampiran 3)
a. Pengadaan Pengadaan Peralatan BNPB/BPBD Pengadaan peralatan berdasarkan pagu anggaran dan mekanisme yang dilakukan sesuai dengan peraturan perundang-undangan, seperti adanya dokumen pengadaan yang memuat dengan jelas sesuai dengan spesifikasi teknis. Pengadaan peralatan yang bersumber dari sumber lain.
b. Penerimaan Monitoring dan evaluasi yang dilakukan pada tahap penerimaan adalah untuk memeriksa:
a. Kesesuaian peralatan yang diterima dengan perencanaan, kebutuhan dan standar minimal sesuai peraturan perundang-undangan yang berkaitan dengan standar minimal peralatan.
b. Kesesuaian peralatan yang diterima dengan spesifikasi yang ditentukan dalam proses pengadaan:
1) Konsistensi satuan terkecil 2) Jumlah, jenis, waktu, dan kondisi peralatan pada saat diterima.
3) Waktu pengiriman peralatan
c. Dokumen Berita Acara serah terima (lampiran 5.4)
d. Proses penerimaan peralatan: pemeriksaan dan pencatatan.
3. Pergudangan (Lampiran 4) Monitoring dan evaluasi dilakukan untuk memeriksa:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7712, 'Dalam hal perencanaan bantuan peralatan yang melibatkan lembaga internasional dan lembaga asing Nonpemerintah, koordinator cluster bertanggung jawab untuk melakukan monitoring dalam perencanaan bantuan peralatan sesuai dengan spesifikasi yang diperlukan berdasarkan peraturan perundang – undangan yang mengatur peran serta lembaga internasional dan lembaga asing Nonpemerintah pada saat tanggap darurat.
2. Pengadaan dan Penerimaan (Lampiran 3)
a. Pengadaan Pengadaan Peralatan BNPB/BPBD Pengadaan peralatan berdasarkan pagu anggaran dan mekanisme yang dilakukan sesuai dengan peraturan perundang-undangan, seperti adanya dokumen pengadaan yang memuat dengan jelas sesuai dengan spesifikasi teknis. Pengadaan peralatan yang bersumber dari sumber lain.
b. Penerimaan Monitoring dan evaluasi yang dilakukan pada tahap penerimaan adalah untuk memeriksa:
a. Kesesuaian peralatan yang diterima dengan perencanaan, kebutuhan dan standar minimal sesuai peraturan perundang-undangan yang berkaitan dengan standar minimal peralatan.
b. Kesesuaian peralatan yang diterima dengan spesifikasi yang ditentukan dalam proses pengadaan:
1) Konsistensi satuan terkecil 2) Jumlah, jenis, waktu, dan kondisi peralatan pada saat diterima.
3) Waktu pengiriman peralatan
c. Dokumen Berita Acara serah terima (lampiran 5.4)
d. Proses penerimaan peralatan: pemeriksaan dan pencatatan.
3. Pergudangan (Lampiran 4) Monitoring dan evaluasi dilakukan untuk memeriksa:', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2011 tentang Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7713, 'perka-21-2011', 24, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'a. Kesesuaian gudang dengan spesifikasi gudang (nasional, provinsi, kabupaten/kota) yang telah ditetapkan oleh BNPB seperti lokasi yang bebas bencana, aksesibilitas mudah, keamanan, kondisi gudang, peralatan, pemilahan peralatan, dan peralatan yang terdata sesuai peraturan perundang-undangan yang berkaitan dengan pergudangan.
12
b. Penggunaan formulir penerimaan, pengeluaran, penyimpanan dan pergudangan (sesuai dengan standar, mencakup jenis peralatan).
4. Penyaluran (Lampiran 5) Monitoring dan evaluasi dilakukan untuk memeriksa hal-hal sebagai berikut:
a. Dokumen permintaan penyaluran peralatan yang sudah di verifikasi juga memuat nama pejabat yang memiliki kewenangan untuk pengeluaran barang.
b. Pengisian dokumen penyaluran peralatan sesuai peraturan (FORM Pal 004).
c. Surat jalan penyaluran peralatan dari gudang.
d. Berita Acara Serah Terima yang telah ditandatangani (lampiran 5.4).
5. Pengangkutan (Lampiran 6) Monitoring dan evaluasi dilakukan untuk memeriksa hal-hal sebagai berikut:
a. Pemilihan moda transportasi yang sesuai.
b. Monitoring proses pengangkutan.
6. Pendistribusian (Lampiran 7) Monitoring dan evaluasi pada tahap pendistribusian untuk memeriksa hal-hal sebagai berikut:
a. Kesesuaian jumlah, jenis dan kondisi peralatan.
b. Tertib administrasi distribusi bantuan peralatan dengan didukung dengan berita acara penerimaan bantuan.
c. Kecepatan dan ketepatan pendistribusian peralatan khusus pada masa tanggap darurat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7713, 'a. Kesesuaian gudang dengan spesifikasi gudang (nasional, provinsi, kabupaten/kota) yang telah ditetapkan oleh BNPB seperti lokasi yang bebas bencana, aksesibilitas mudah, keamanan, kondisi gudang, peralatan, pemilahan peralatan, dan peralatan yang terdata sesuai peraturan perundang-undangan yang berkaitan dengan pergudangan.
12
b. Penggunaan formulir penerimaan, pengeluaran, penyimpanan dan pergudangan (sesuai dengan standar, mencakup jenis peralatan).
4. Penyaluran (Lampiran 5) Monitoring dan evaluasi dilakukan untuk memeriksa hal-hal sebagai berikut:
a. Dokumen permintaan penyaluran peralatan yang sudah di verifikasi juga memuat nama pejabat yang memiliki kewenangan untuk pengeluaran barang.
b. Pengisian dokumen penyaluran peralatan sesuai peraturan (FORM Pal 004).
c. Surat jalan penyaluran peralatan dari gudang.
d. Berita Acara Serah Terima yang telah ditandatangani (lampiran 5.4).
5. Pengangkutan (Lampiran 6) Monitoring dan evaluasi dilakukan untuk memeriksa hal-hal sebagai berikut:
a. Pemilihan moda transportasi yang sesuai.
b. Monitoring proses pengangkutan.
6. Pendistribusian (Lampiran 7) Monitoring dan evaluasi pada tahap pendistribusian untuk memeriksa hal-hal sebagai berikut:
a. Kesesuaian jumlah, jenis dan kondisi peralatan.
b. Tertib administrasi distribusi bantuan peralatan dengan didukung dengan berita acara penerimaan bantuan.
c. Kecepatan dan ketepatan pendistribusian peralatan khusus pada masa tanggap darurat.', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2011 tentang Pedoman Monitoring Dan Evaluasi Manajemen Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7714, 'perka-21-2011', 25, 'lampiran', 'Lampiran hal. 18', NULL, 18, 'd. Dokumentasi pendistribusian sebagai bukti distribusi peralatan yang dilakukan.
Dalam hal pendistribusian oleh BPBD sampai kepada penerima bantuan, maka BNPB dapat berkoordinasi dengan BPBD untuk melakukan uji petik pelaksanaan monitoring dan evaluasi.
7. Operasional dan Pemeliharaan (Lampiran 8) Operasional dan Pemeliharaan merupakan kegiatan perawatan peralatan agar kondisi tetap terjamin dan siap pakai untuk dipergunakan dalam penanggulangan bencana dengan prinsip efektif, efisien dan akuntabel, melalui:
a. Penyusunan peralatan yang rapih dan teratur, sesuai dengan penempatannya.
b. Melaksanakan perawatan secara berkala untuk semua Peralatan yang ada digudang.
c. Pengalokasian anggaran operasional dan pemeliharaan peralatan.
8. Penghapusan (Lampiran 9) 13 Monitoring dan evaluasi dilakukan untuk memeriksa hal-hal sebagai berikut:
a. Daftar peralatan yang sudah rusak, hilang, tidak bernilai ekonomis dan habis masa manfaatnya.
b. Proses penghapusan peralatan dilaksanakan sesuai dengan peraturan perundangan – undangan.
c. Dokumen Berita Acara penghapusan peralatan.
d. Dokumentasi penghapusan peralatan.
H. Manfaat bantuan peralatan (LAMPIRAN 10) Monitoring dan evaluasi dilakukan untuk mengetahui manfaat bantuan peralatan yang diberikan:
a. Fungsi peralatan yang diberikan pada saat pra bencana, saat tanggap darurat dan pasca bencana.
b. Fungsi peralatan sesuai dengan peruntukannya (Karakteristik, jenis bencana, geografi dan kearifan lokal).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7714, 'd. Dokumentasi pendistribusian sebagai bukti distribusi peralatan yang dilakukan.
Dalam hal pendistribusian oleh BPBD sampai kepada penerima bantuan, maka BNPB dapat berkoordinasi dengan BPBD untuk melakukan uji petik pelaksanaan monitoring dan evaluasi.
7. Operasional dan Pemeliharaan (Lampiran 8) Operasional dan Pemeliharaan merupakan kegiatan perawatan peralatan agar kondisi tetap terjamin dan siap pakai untuk dipergunakan dalam penanggulangan bencana dengan prinsip efektif, efisien dan akuntabel, melalui:
