INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7749, 'perka-21-2014', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka dokumentasi dan pembelajaran praktek penanggulangan bencana yang telah dilakukan oleh BNPB, perlu dibentuk mekanisme berbagi pengetahuan dan pengalaman;
