INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7750, '1. Undang-Undang Nomor 24 Tahun 2007 tentang 2014, No.1836 2 Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
3. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
4. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non Pemerintah Dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
5. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2014 tentang Mekanisme Pembelajaran dan Pertukaran Ilmu Pengetahuan (Knowledge Sharing) serta Pengalaman Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7751, 'perka-21-2014', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG MEKANISME PEMBELAJARAN DAN PERTUKARAN ILMU PENGETAHUAN (KNOWLEDGE SHARING) SERTA PENGALAMAN PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7751, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG MEKANISME PEMBELAJARAN DAN PERTUKARAN ILMU PENGETAHUAN (KNOWLEDGE SHARING) SERTA PENGALAMAN PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2014 tentang Mekanisme Pembelajaran dan Pertukaran Ilmu Pengetahuan (Knowledge Sharing) serta Pengalaman Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7752, 'perka-21-2014', 4, 'pasal', 'Pasal 1', NULL, 2, 'Praktek penanggulangan bencana yang telah dilakukan oleh BNPB perlu dilakukan dokumentasi di setiap unit kerja, sehingga menjadi pengetahuan dan pengalaman berharga dalam rangka mengembangkan ilmu pengetahuan di bidang penanggulangan bencana secara komprehensif dan holistik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7752, 'Praktek penanggulangan bencana yang telah dilakukan oleh BNPB perlu dilakukan dokumentasi di setiap unit kerja, sehingga menjadi pengetahuan dan pengalaman berharga dalam rangka mengembangkan ilmu pengetahuan di bidang penanggulangan bencana secara komprehensif dan holistik.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2014 tentang Mekanisme Pembelajaran dan Pertukaran Ilmu Pengetahuan (Knowledge Sharing) serta Pengalaman Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7753, 'perka-21-2014', 5, 'pasal', 'Pasal 2', NULL, 2, 'Dokumentasi pelaksanaan program kegiatan penanggulangan bencana di tiap-tiap unit kerja di lingkungan BNPB didokumentasikan dalam bentuk data dan dikumpulkan dalam sebuah portal untuk dijadikan bahan pembelajaran dan pertukaran pengalaman dan pengembangan ilmu pengetahuan oleh Penanggung Jawab Pengelola INA-DRTG.
3 2014, No.1836');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7753, 'Dokumentasi pelaksanaan program kegiatan penanggulangan bencana di tiap-tiap unit kerja di lingkungan BNPB didokumentasikan dalam bentuk data dan dikumpulkan dalam sebuah portal untuk dijadikan bahan pembelajaran dan pertukaran pengalaman dan pengembangan ilmu pengetahuan oleh Penanggung Jawab Pengelola INA-DRTG.
3 2014, No.1836', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2014 tentang Mekanisme Pembelajaran dan Pertukaran Ilmu Pengetahuan (Knowledge Sharing) serta Pengalaman Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7754, 'perka-21-2014', 6, 'pasal', 'Pasal 3', NULL, 3, 'Tiap unit kerja di lingkungan BNPB wajib melaksanakan pertemuan berkala dalam rangka dokumentasi pelaksanaan program dan pertukaran pengalaman kegiatan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7754, 'Tiap unit kerja di lingkungan BNPB wajib melaksanakan pertemuan berkala dalam rangka dokumentasi pelaksanaan program dan pertukaran pengalaman kegiatan penanggulangan bencana.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2014 tentang Mekanisme Pembelajaran dan Pertukaran Ilmu Pengetahuan (Knowledge Sharing) serta Pengalaman Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7755, 'perka-21-2014', 7, 'pasal', 'Pasal 4', NULL, 3, '(1) Mekanisme knowledge sharing di INA-DRTG:
a. Di tingkat Internal, melakukan pengumpulan pengalaman dan data/informasi pada semua tahapan penanggulangan bencana di lingkungan BNPB baik secara formal Informal;
b. Di tingkat Domestik, melakukan pengumpulan pengalaman dan data/informasi pada semua tahapan penanggulangan bencana antara pemerintah/pemerintah daerah, masyarakat, dan dunia usaha baik secara formal maupun Informal;
c. Di tingkat Internasional, melakukan pertukaran ilmu pengetahuan dan pengalaman terbaik pada semua tahapan penanggulangan antara pemerintah Indonesia dengan negara, lembaga internasional, dan lembaga asing non-pemerintah.
(2) Knowledge sharing adalah program BNPB yang merupakan tanggung jawab tiap-tiap Kedeputian, Pusat Data Informasi dan Hubungan Masyarakat, serta Pusat Pendidikan dan Pelatihan Penanggaulangan Bencana.
(3) Knowledge sharing dapat melibatkan Kementerian/Lembaga, pemerintah daerah, masyarakat, dan dunia usaha yang berhubungan dengan penanggulangan bencana, dengan menempatkan Kementerian/Lembaga sebagai specialist agent, yang mempunyai keahlian khusus dalam menangani bencana.
(4) BNPB berperan sebagai host sekaligus centre dalam knowledge sharing.
(5) Pelaksanaan pembelajaran dan pertukaran sebagaimana dimaksud pada ayat (1) dapat melibatkan institusi pendidikan, akademisi, peneliti, perekayasa dan praktisi, serta pihak-pihak lain, baik dari dalam maupun luar negeri.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7755, '(1) Mekanisme knowledge sharing di INA-DRTG:
a. Di tingkat Internal, melakukan pengumpulan pengalaman dan data/informasi pada semua tahapan penanggulangan bencana di lingkungan BNPB baik secara formal Informal;
b. Di tingkat Domestik, melakukan pengumpulan pengalaman dan data/informasi pada semua tahapan penanggulangan bencana antara pemerintah/pemerintah daerah, masyarakat, dan dunia usaha baik secara formal maupun Informal;
c. Di tingkat Internasional, melakukan pertukaran ilmu pengetahuan dan pengalaman terbaik pada semua tahapan penanggulangan antara pemerintah Indonesia dengan negara, lembaga internasional, dan lembaga asing non-pemerintah.
(2) Knowledge sharing adalah program BNPB yang merupakan tanggung jawab tiap-tiap Kedeputian, Pusat Data Informasi dan Hubungan Masyarakat, serta Pusat Pendidikan dan Pelatihan Penanggaulangan Bencana.
(3) Knowledge sharing dapat melibatkan Kementerian/Lembaga, pemerintah daerah, masyarakat, dan dunia usaha yang berhubungan dengan penanggulangan bencana, dengan menempatkan Kementerian/Lembaga sebagai specialist agent, yang mempunyai keahlian khusus dalam menangani bencana.
(4) BNPB berperan sebagai host sekaligus centre dalam knowledge sharing.
(5) Pelaksanaan pembelajaran dan pertukaran sebagaimana dimaksud pada ayat (1) dapat melibatkan institusi pendidikan, akademisi, peneliti, perekayasa dan praktisi, serta pihak-pihak lain, baik dari dalam maupun luar negeri.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2014 tentang Mekanisme Pembelajaran dan Pertukaran Ilmu Pengetahuan (Knowledge Sharing) serta Pengalaman Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7756, 'perka-21-2014', 8, 'pasal', 'Pasal 5', NULL, 3, 'Pengumpulan data/informasi dan dokumen pelaksanaan penanggulangan bencana dari tiap unit kerja di lingkungan BNPB menjadi tanggung jawab Kepala Pusat Pendidikan dan Pelatihan Penanggulangan Bencana untuk bahan pengembangan ilmu pengetahuan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7756, 'Pengumpulan data/informasi dan dokumen pelaksanaan penanggulangan bencana dari tiap unit kerja di lingkungan BNPB menjadi tanggung jawab Kepala Pusat Pendidikan dan Pelatihan Penanggulangan Bencana untuk bahan pengembangan ilmu pengetahuan penanggulangan bencana.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 21 Tahun 2014 tentang Mekanisme Pembelajaran dan Pertukaran Ilmu Pengetahuan (Knowledge Sharing) serta Pengalaman Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7757, 'perka-21-2014', 9, 'pasal', 'Pasal 6', NULL, 3, '(1) Untuk melaksanakan Peraturan Kepala ini, dibentuk Kelompok Kerja di lingkungan BNPB.
