INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7764, 'perka-22-2014', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA DARI MASYARAKAT PROFESIONAL PADA BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7764, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA DARI MASYARAKAT PROFESIONAL PADA BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan Dan Kreteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7765, 'perka-22-2014', 4, 'pasal', 'Pasal 1', NULL, 2, 'Mekanisme pemilihan dan kriteria anggota unsur pengarah digunakan sebagai acuan/arahan dalam melakukan pemilihan untuk mendapatkan anggota unsur pengarah penanggulangan bencana dari masyarakat profesional sesuai dengan amanat peraturan perundangan-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7765, 'Mekanisme pemilihan dan kriteria anggota unsur pengarah digunakan sebagai acuan/arahan dalam melakukan pemilihan untuk mendapatkan anggota unsur pengarah penanggulangan bencana dari masyarakat profesional sesuai dengan amanat peraturan perundangan-undangan.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan Dan Kreteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7766, 'perka-22-2014', 5, 'pasal', 'Pasal 2', NULL, 2, 'Mekanisme pemilihan dan kriteria sebagaimana dimaksud Pasal 1 adalah sebagaimana dimaksud dalam Lampiran Peraturan Kepala Badan Nasional Penanggulangan Bencana ini, yang merupakan bagian tak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7766, 'Mekanisme pemilihan dan kriteria sebagaimana dimaksud Pasal 1 adalah sebagaimana dimaksud dalam Lampiran Peraturan Kepala Badan Nasional Penanggulangan Bencana ini, yang merupakan bagian tak terpisahkan dari Peraturan ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan Dan Kreteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7767, 'perka-22-2014', 6, 'pasal', 'Pasal 3', NULL, 2, 'Pada saat Peraturan ini mulai berlaku, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana, dicabut dan dinyatakan tidak berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7767, 'Pada saat Peraturan ini mulai berlaku, Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 2 Tahun 2008 tentang Mekanisme Pemilihan dan Kriteria Anggota Unsur Pengarah Penanggulangan Bencana Dari Masyarakat Profesional Pada Badan Nasional Penanggulangan Bencana, dicabut dan dinyatakan tidak berlaku.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan Dan Kreteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional');
