INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7769, 'perka-22-2014', 8, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 1 Desember 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 4 Desember 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY www.peraturan.go.id 2014, No.1858 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7769, 'Ditetapkan di Jakarta pada tanggal 1 Desember 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 4 Desember 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY www.peraturan.go.id 2014, No.1858 4', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan Dan Kreteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7770, 'perka-22-2014', 9, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 22 TAHUN 2014 TENTANG MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA DARI MASYARAKAT PROFESIONAL PADA BADAN NASIONAL PENANGGULANGAN BENCANA MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA DARI MASYARAKAT PROFESIONAL PADA BADAN NASIONAL PENANGGULANGAN BENCANA BAB I UMUM 1.1 Latar Belakang Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana memberikan mandat kepada Pemerintah dan Pemerintah Daerah sebagai penanggungjawab dalam penyelenggaraan penanggulangan bencana. Untuk menyelenggarakan penanggulangan bencana tersebut, dibentuk Badan Nasional Penanggulangan Bencana (BNPB) di tingkat Pusat dan Badan Penanggulangan Bencana Daerah (BPBD) di tingkat Daerah.
Sebagai tindak lanjut Peraturan Presiden Nomor 8 Tahun 2008, telah dibentuk BNPB yang terdiri atas Kepala, Unsur Pengarah penanggulangan bencana dan Unsur Pelaksana Penanggulangan Bencana. Unsur Pengarah terdiri dari 10 (sepuluh) anggota yang berasal dari pejabat eselon I atau yang setingkat dari lembaga pemerintah, dan 9 (sembilan) anggota dari masyarakat profesional.
Untuk melaksanakan ketentuan pasal 58 Peraturan Presiden Nomor 8 Tahun 2008, perlu menetapkan mekanisme pemilihan dan kriteria anggota unsur pengarah penanggulangan bencana dari masyarakat professional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7770, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 22 TAHUN 2014 TENTANG MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA DARI MASYARAKAT PROFESIONAL PADA BADAN NASIONAL PENANGGULANGAN BENCANA MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA DARI MASYARAKAT PROFESIONAL PADA BADAN NASIONAL PENANGGULANGAN BENCANA BAB I UMUM 1.1 Latar Belakang Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana memberikan mandat kepada Pemerintah dan Pemerintah Daerah sebagai penanggungjawab dalam penyelenggaraan penanggulangan bencana. Untuk menyelenggarakan penanggulangan bencana tersebut, dibentuk Badan Nasional Penanggulangan Bencana (BNPB) di tingkat Pusat dan Badan Penanggulangan Bencana Daerah (BPBD) di tingkat Daerah.
Sebagai tindak lanjut Peraturan Presiden Nomor 8 Tahun 2008, telah dibentuk BNPB yang terdiri atas Kepala, Unsur Pengarah penanggulangan bencana dan Unsur Pelaksana Penanggulangan Bencana. Unsur Pengarah terdiri dari 10 (sepuluh) anggota yang berasal dari pejabat eselon I atau yang setingkat dari lembaga pemerintah, dan 9 (sembilan) anggota dari masyarakat profesional.
Untuk melaksanakan ketentuan pasal 58 Peraturan Presiden Nomor 8 Tahun 2008, perlu menetapkan mekanisme pemilihan dan kriteria anggota unsur pengarah penanggulangan bencana dari masyarakat professional.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan Dan Kreteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7771, 'perka-22-2014', 10, 'lampiran', 'Lampiran hal. 4', NULL, 4, '1.2 Tujuan Mekanisme ini disusun untuk memberikan acuan/panduan dalam melakukan pemilihan guna memperoleh anggota unsur pengarah penanggulangan bencana dari masyarakat profesional pada BNPB sesuai dengan amanat peraturan perundang-undangan.
1.3 Dasar Hukum
a. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
b. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
5 2014, No.1858 1.4 Pengertian
a. Badan Nasional Penanggulangan Bencana, selanjutnya disebut BNPB adalah Lembaga Pemerintah Non Kementerian setingkat menteri, berada di bawah dan bertanggungjawab langsung kepada Presiden, yang dibentuk dalam rangka menjalankan tugas dan fungsi penyelenggaraan penanggulangan bencana.
b. Unsur pengarah penanggulangan bencana adalah bagian/unsur BNPB yang bertugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.
c. Masyarakat Profesional adalah lembaga/organisasi yan: beranggotakan para pakar/profesional dan/atau toko masyarakat yang memiliki pa etahuan, kemampuan, keahlian dan pengalaman i idang penanggulangan encana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7771, '1.2 Tujuan Mekanisme ini disusun untuk memberikan acuan/panduan dalam melakukan pemilihan guna memperoleh anggota unsur pengarah penanggulangan bencana dari masyarakat profesional pada BNPB sesuai dengan amanat peraturan perundang-undangan.
1.3 Dasar Hukum
a. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
b. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
5 2014, No.1858 1.4 Pengertian
a. Badan Nasional Penanggulangan Bencana, selanjutnya disebut BNPB adalah Lembaga Pemerintah Non Kementerian setingkat menteri, berada di bawah dan bertanggungjawab langsung kepada Presiden, yang dibentuk dalam rangka menjalankan tugas dan fungsi penyelenggaraan penanggulangan bencana.
b. Unsur pengarah penanggulangan bencana adalah bagian/unsur BNPB yang bertugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.
c. Masyarakat Profesional adalah lembaga/organisasi yan: beranggotakan para pakar/profesional dan/atau toko masyarakat yang memiliki pa etahuan, kemampuan, keahlian dan pengalaman i idang penanggulangan encana.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan Dan Kreteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7772, 'perka-22-2014', 11, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'd. Lembaga independen adalah lembaga/organisasi yang mempunyai kemampuan untuk melakukan pemilihan calon anggota unsur pengarah penanggulangan bencana dan tidak memiliki kepentingan atau keberpihakan terhadap pihak-pihak tertentu dalam pemilihan calon anggota unsur pengarah penanggulangan bencana 1.5 Sistematika Mekanisme ini berisi materi tentang tata cara/prosedur dalam pemilihan anggota unsur pengarah penanggulangan bencana dari masyarakat profesional, sebagai berikut:
I. UMUM
II. UNSUR PENGARAH PENANGGULANGAN BENCANA
III. MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA
IV. '' PENGANGKATAN DAN PEMBERHENTIAN ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA
V. PENUTUP 2014, No.1858 6 BAB II UNSUR PENGARAH PENANGGULANGAN BENCANA Unsur pengarah penanggulangan bencana merupakan bagian dari BNPB yang bersama-sama unsur pelaksana melaksanakan penyelenggaraan penanggulangan bencana.
21 Kedudukan, Tugas dan Fungsi
a. Unsurpengarahpenanggulangan bencana berada di bawah dan bertanggungjawab kepada Kepala BNPB.
b. Unsur pengarah penanggulangan bencana mempunyai tugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.
c. Untuk melaksanakan tugas sebagaimana tersebut huruf b, unsur pengarah penanggulangan bencana menyelenggarakan fungsi: l) perumusan konsep kebijakan penanggulangan bencana nasional, 2) pemantauan, dan 3) evaluasi dalam penyelenggaraan penanggulangan bencana.
22 Keanggotaan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7772, 'd. Lembaga independen adalah lembaga/organisasi yang mempunyai kemampuan untuk melakukan pemilihan calon anggota unsur pengarah penanggulangan bencana dan tidak memiliki kepentingan atau keberpihakan terhadap pihak-pihak tertentu dalam pemilihan calon anggota unsur pengarah penanggulangan bencana 1.5 Sistematika Mekanisme ini berisi materi tentang tata cara/prosedur dalam pemilihan anggota unsur pengarah penanggulangan bencana dari masyarakat profesional, sebagai berikut:
I. UMUM
II. UNSUR PENGARAH PENANGGULANGAN BENCANA
III. MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA
IV. '' PENGANGKATAN DAN PEMBERHENTIAN ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA
V. PENUTUP 2014, No.1858 6 BAB II UNSUR PENGARAH PENANGGULANGAN BENCANA Unsur pengarah penanggulangan bencana merupakan bagian dari BNPB yang bersama-sama unsur pelaksana melaksanakan penyelenggaraan penanggulangan bencana.
21 Kedudukan, Tugas dan Fungsi
a. Unsurpengarahpenanggulangan bencana berada di bawah dan bertanggungjawab kepada Kepala BNPB.
b. Unsur pengarah penanggulangan bencana mempunyai tugas memberikan masukan dan saran kepada Kepala BNPB dalam penanggulangan bencana.
c. Untuk melaksanakan tugas sebagaimana tersebut huruf b, unsur pengarah penanggulangan bencana menyelenggarakan fungsi: l) perumusan konsep kebijakan penanggulangan bencana nasional, 2) pemantauan, dan 3) evaluasi dalam penyelenggaraan penanggulangan bencana.
22 Keanggotaan', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan Dan Kreteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7773, 'perka-22-2014', 12, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'a. Unsur pengarah penanggulangan bencana terdiri dari Ketua dan Anggota,
b. Ketua unsur pengarah penanggulangan bencana dijabat oleh Kepala BNPB,
c. Keanggotaan unsur pengarah penanggulangan bencana berasal dari lembaga pemerintah dan masyarakat profesional, dan
d. Anggota unsur pengarah penanggulangan bencana berjumlah 19 (sembilan belas) anggota, terdiri dari:
1) 10 (sepuluh) anggota berasal dari pejabat eselon I atau setingkat dari lembaga pemerintah yang diusulkan oleh Pimpinan Lembaga Pemerintah, yang mewakili: a) Kementerian Koordinator Bidang Pembangunan Manusia dan Kebudayaan, b) Kementerian Dalam Negeri, c) Kementerian Sosial, d) Kementerian Pekerjaan Umum dan Perumahan Rakyat, e) Kementerian Kesehatan, f) Kementerian Keuangan, g) Kementerian Perhubungan, h) Kementerian Energi dan Sumber Daya Mineral, i) Kepolisian Negara Republik Indonesia, dan j) Tentara Nasional Indonesia.
2) 9 (sembilan) anggota dari masyarakat profesional yang berasal dari pakar/ profesional dan/atau tokoh masyarakat.
7 2014, No.1858 BAB III MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA 3.1 — Mekanisme Pemilihan Pemilihan anggota unsur pengarah penanggulangan bencana dilaksanakan melalui mekanisme sebagai berikut:
a. Unsur pengarah penanggulangan bencana dari lembaga pemerintah Pemilihan anggota unsur pengarah penanggulangan bencana dari lembaga pemerintah dilakukan sesuai dengan ketentuan peraturan perundang-undangan yang berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7773, 'a. Unsur pengarah penanggulangan bencana terdiri dari Ketua dan Anggota,
b. Ketua unsur pengarah penanggulangan bencana dijabat oleh Kepala BNPB,
c. Keanggotaan unsur pengarah penanggulangan bencana berasal dari lembaga pemerintah dan masyarakat profesional, dan
d. Anggota unsur pengarah penanggulangan bencana berjumlah 19 (sembilan belas) anggota, terdiri dari:
1) 10 (sepuluh) anggota berasal dari pejabat eselon I atau setingkat dari lembaga pemerintah yang diusulkan oleh Pimpinan Lembaga Pemerintah, yang mewakili: a) Kementerian Koordinator Bidang Pembangunan Manusia dan Kebudayaan, b) Kementerian Dalam Negeri, c) Kementerian Sosial, d) Kementerian Pekerjaan Umum dan Perumahan Rakyat, e) Kementerian Kesehatan, f) Kementerian Keuangan, g) Kementerian Perhubungan, h) Kementerian Energi dan Sumber Daya Mineral, i) Kepolisian Negara Republik Indonesia, dan j) Tentara Nasional Indonesia.
2) 9 (sembilan) anggota dari masyarakat profesional yang berasal dari pakar/ profesional dan/atau tokoh masyarakat.
7 2014, No.1858 BAB III MEKANISME PEMILIHAN DAN KRITERIA ANGGOTA UNSUR PENGARAH PENANGGULANGAN BENCANA 3.1 — Mekanisme Pemilihan Pemilihan anggota unsur pengarah penanggulangan bencana dilaksanakan melalui mekanisme sebagai berikut:
a. Unsur pengarah penanggulangan bencana dari lembaga pemerintah Pemilihan anggota unsur pengarah penanggulangan bencana dari lembaga pemerintah dilakukan sesuai dengan ketentuan peraturan perundang-undangan yang berlaku.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan Dan Kreteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7774, 'perka-22-2014', 13, 'lampiran', 'Lampiran hal. 7', NULL, 7, 'b. Unsur pengarah penanggulangan bencana dari masyarakat professional, 1) Pemilihan calon anggota unsur pengarah penanggulangan bencana dari masyarakat profesional dilakukan dengan memberikan kesempatan seluas-luasnya kepada masyarakat dengan diumumkan melalui media.
2) Pemilihan calon anggota unsur pengarah penanggulangan bencana sebagaimana dimaksud pada butir 1) dilaksanakan oleh lembaga independen — yang mempunyai tugas menerima pendaftaran, melaksanakan penyaringan, seleksi, dan menyampaikan hasil pemilihan kepada Kepala BNPB.
3) Lembaga independen sebagaimana dimaksud butir 2) ditunjuk/ditetapkan oleh Kepala BNPB.
4 Kepala BNPB mengusulkan 18 (delapan belas) calon anggota unsur pengarah penanggulangan bencana dan masyarakat profesional hasil pemilihan kepada Presiden atau 2 (dua) kali lipat secara proporsional dari jumlah anggota Unsur Pengarah penanggulangan bencana dari masyarakat profesional untuk dilakukan uji kepatutan dan uji kelayakan oleh DPR-RI.
5) Calon anggota unsur pengarah penanggulangan bencana yang dinyatakan lulus uji kepatutan dan uji kelayakan disampaikan oleh DPR-RI kepada Presiden untuk ditetapkan sebagai anggota unsur pengarah penanggulangan bencana secara definitif.
6) BNPB mengumumkan kepada masyarakat luas hasil uji kepatutan dan uji kelayakan melalui media.
3.2 Kriteria
a. Calon anggota unsur pengarah penanggulangan bencana dari masyarakat profesional harus memenuhi kriteria/ persyaratan sebagai berikut:
1) Warga Negara Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7774, 'b. Unsur pengarah penanggulangan bencana dari masyarakat professional, 1) Pemilihan calon anggota unsur pengarah penanggulangan bencana dari masyarakat profesional dilakukan dengan memberikan kesempatan seluas-luasnya kepada masyarakat dengan diumumkan melalui media.
2) Pemilihan calon anggota unsur pengarah penanggulangan bencana sebagaimana dimaksud pada butir 1) dilaksanakan oleh lembaga independen — yang mempunyai tugas menerima pendaftaran, melaksanakan penyaringan, seleksi, dan menyampaikan hasil pemilihan kepada Kepala BNPB.
3) Lembaga independen sebagaimana dimaksud butir 2) ditunjuk/ditetapkan oleh Kepala BNPB.
4 Kepala BNPB mengusulkan 18 (delapan belas) calon anggota unsur pengarah penanggulangan bencana dan masyarakat profesional hasil pemilihan kepada Presiden atau 2 (dua) kali lipat secara proporsional dari jumlah anggota Unsur Pengarah penanggulangan bencana dari masyarakat profesional untuk dilakukan uji kepatutan dan uji kelayakan oleh DPR-RI.
5) Calon anggota unsur pengarah penanggulangan bencana yang dinyatakan lulus uji kepatutan dan uji kelayakan disampaikan oleh DPR-RI kepada Presiden untuk ditetapkan sebagai anggota unsur pengarah penanggulangan bencana secara definitif.
6) BNPB mengumumkan kepada masyarakat luas hasil uji kepatutan dan uji kelayakan melalui media.
3.2 Kriteria
a. Calon anggota unsur pengarah penanggulangan bencana dari masyarakat profesional harus memenuhi kriteria/ persyaratan sebagai berikut:
1) Warga Negara Indonesia.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 22 Tahun 2014 tentang Mekanisme Pemilihan Dan Kreteria Anggota Unsur Pengarah Penanggulangan Bencana dari Masyarakat Profesional');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7775, 'perka-22-2014', 14, 'lampiran', 'Lampiran hal. 7', NULL, 7, '2) Sehatjasmani dan rohani.
3) Berkelakuan baik.
4) Usia serendah-rendahnya 45 (empat puluh lima) tahun dan setinggi-tingginya 60 (enam puluh lima) tahun.
5) Memiliki wawasan kebangsaan.
6) Memiliki pengetahuan akademis dan pengalaman dalam penanggulangan bencana.
2014, No.1858 8 7) Berpendidikan serendah-rendahnya Sarjana (S1).
8) Memiliki integritas tinggi.
9) Non-partisan.
b. Pembagian Bidang Pembagian Fungsi Tugas dan Tanggung Jawab Unsur Pengarah dibagi atas 9 (sembilan) fungsi kerja:
1) Unsur Pengarah Bidang Pencegahan dan Kesiapsiagaan.
Area Kerja: Perumusan kebijakan strategis terhadap perencanaan pencegahan dan kesiapsiagaan penanggulangan bencana.
2) Unsur Pengarah Bidang Penanganan Darurat Bencana.
Area Kerja: Perumusan kebijakan strategis terhadap perencanaan penanganan darurat bencana.
3) Unsur Pengarah Bidang Penanganan Pasca Bencana.
Area Kerja: Perumusan kebijakan strategis terhadap perencanaan pasca bencana.
4) Unsur Pengarah Bidang Logistik dan Peralatan.
Area Kerja: Perumusan kebijakan strategis terhadap pengadaan sarana pendukung untuk kegiatan perencanaan penanggulangan bencana, penanganan penanggulangan bencana, dan rekonstruksi pasca bencana.
5) Unsur Pengarah Bidang Kerjasama Strategis dan Lintas Fungsi.
Area Kerja: Perumusan kebijakan strategis hubungan kerjasama dengan pihak dalam maupun luar negeri, hubungan kerjasama secara internal dalam organisasi BNPB serta membuat perumusan peraturan perundang-undangan dan telaahan hukum.');
