INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7779, 'perka-23-2010', 1, 'menimbang', 'Menimbang', NULL, 2, 'a. bahwa dalam rangka Pelaksanaan Pasal 7 ayat 1 Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana mengamanatkan kepada Pernerintah Pusat dan Pemerintah Daerah untuk mendorong partisipasi masyarakat dalam penyediaan dana yang bersumber dari masyarakat untuk penanggulangan bencana;
