INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7781, 'perka-23-2010', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURANKEPALA BADAN NASIONALPENANGGULANGAN BENCANA TENTANG PEDOMAN PENGUMPULAN DAN PENGELOLAAN DANA MASYARAKAT UNTUK BANTUAN PENANGGULANGAN BENCANA.
BABI KETENTUAN UMUM Pasal1 Dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana yang dimaksud dengan:
1. Kepala Badan adalah Kepala Badan Nasional Penanggulangan Bencana (BNPB).
2. Dana Masyarakat untuk Bantuan Penanggulangan Bencana yang selanjutnya disebut Dana Bantuan Masyarakat adalah dana yang diterima dan dikumpulkan oleh Badan Nasional Penanggulangan Bencana dari masyarakat umum secara pribadi, kelompok danj atau golongan, lembaga usaha baik yang berasal dari dalam negeri maupun luar negeri secara suka-relajtanpa paksaan sebagai hibah kepada Negara untuk keperluan bantuan penanggulangan bencana diseluruh wilayah negara RepublikIndonesia.
3. RekeningBNPBuntuk Bantuan Penanggulangan Bencana adalah rekeningyang dikelola oleh bendahara pada bank pemerintah yang digunakan untuk menampung Dana Bantuan Masyarakat.
4. Bendahara Pengeluaran Pembantu pengelola rekening yang selanjutnya disebut BPP Pengelola Rekening adalah Bendahara yang bertanggungjawab terhadap pengelolaan rekening BNPBuntuk Bantuan Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7781, 'Menetapkan : PERATURANKEPALA BADAN NASIONALPENANGGULANGAN BENCANA TENTANG PEDOMAN PENGUMPULAN DAN PENGELOLAAN DANA MASYARAKAT UNTUK BANTUAN PENANGGULANGAN BENCANA.
BABI KETENTUAN UMUM Pasal1 Dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana yang dimaksud dengan:
1. Kepala Badan adalah Kepala Badan Nasional Penanggulangan Bencana (BNPB).
2. Dana Masyarakat untuk Bantuan Penanggulangan Bencana yang selanjutnya disebut Dana Bantuan Masyarakat adalah dana yang diterima dan dikumpulkan oleh Badan Nasional Penanggulangan Bencana dari masyarakat umum secara pribadi, kelompok danj atau golongan, lembaga usaha baik yang berasal dari dalam negeri maupun luar negeri secara suka-relajtanpa paksaan sebagai hibah kepada Negara untuk keperluan bantuan penanggulangan bencana diseluruh wilayah negara RepublikIndonesia.
3. RekeningBNPBuntuk Bantuan Penanggulangan Bencana adalah rekeningyang dikelola oleh bendahara pada bank pemerintah yang digunakan untuk menampung Dana Bantuan Masyarakat.
4. Bendahara Pengeluaran Pembantu pengelola rekening yang selanjutnya disebut BPP Pengelola Rekening adalah Bendahara yang bertanggungjawab terhadap pengelolaan rekening BNPBuntuk Bantuan Penanggulangan Bencana.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2010 tentang Pedoman Pengumpulan dan Pengelolaan Dana Masyarakat Untuk Bantuan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7782, 'perka-23-2010', 4, 'menetapkan', 'BAB II', NULL, 4, 'RUANGLINGKUP Pasal2 Ruang lingkup Peraturan Kepala Badan tentang Pengumpulan Dan Pengelolaan Dana Masyarakat Untuk Bantuan PenanggulanganBencanameliputi :
a. Pembukaan dan Pengelolaanrekening;
b. Pembentukan Tim Pengelola Rekening;
c. Pengelolaan dana masyarakat, penggunaan dana dan tata cara pencairan;
d. Akuntansi dan Pelaporan.
BABIII PELAKSANAAN PENGUMPULANDANA Bagian I Pelaksanaan Kegiatan dan Pembukaan Rekening Pasal3
(1) Kepala Badan menerbitkan Surat Keputusan mengenai Pengumpulan Dana Bantuan Masyarakat untuk keperluan bantuan penanggulangan bencana di seluruh wilayah Indonesia.
(2) untuk keperluan pelaksanaan kegiatan sebagaimana dimaksud pada ayat (1), Kepala Badan membuka rekening bank untuk menampung Dana Bantuan Masyarakat,menunjuk BPP pengelolarekening.
Pasal4
(1) Kepala Badan membuka rekening penampungan Dana Bantuan Masyarakat pada Bank Pemerintah.
(2) Apabila diperlukan Kepala Badan dapat membuka rekening bank khusus untuk menampungbantuan tunai berupa valuta asing.
(3) Pembukaan rekening bank sebagaimana dimaksud pada ayat (1) dan ayat (2) dilaksanakan setelah mendapat persetujuan Menteri Keuangan.
(4) Permohonan persetujuan pembukaan rekening bank sebagaimana dimaksud pada ayat (3) oleh Kepala BNPB disampaikan kepada Menteri Keuangan Up. Direktur Pengelolaan Kas Negara (PKN) dengan tembusan Direktur Jenderal Pengelolaan Utang.
(5) Rekening Bank sebagaimana dimaksud pada ayat (1) menggunakan nama Rekening BNPBuntuk Bantuan Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7782, 'RUANGLINGKUP Pasal2 Ruang lingkup Peraturan Kepala Badan tentang Pengumpulan Dan Pengelolaan Dana Masyarakat Untuk Bantuan PenanggulanganBencanameliputi :
a. Pembukaan dan Pengelolaanrekening;
b. Pembentukan Tim Pengelola Rekening;
c. Pengelolaan dana masyarakat, penggunaan dana dan tata cara pencairan;
d. Akuntansi dan Pelaporan.
BABIII PELAKSANAAN PENGUMPULANDANA Bagian I Pelaksanaan Kegiatan dan Pembukaan Rekening Pasal3
(1) Kepala Badan menerbitkan Surat Keputusan mengenai Pengumpulan Dana Bantuan Masyarakat untuk keperluan bantuan penanggulangan bencana di seluruh wilayah Indonesia.
(2) untuk keperluan pelaksanaan kegiatan sebagaimana dimaksud pada ayat (1), Kepala Badan membuka rekening bank untuk menampung Dana Bantuan Masyarakat,menunjuk BPP pengelolarekening.
Pasal4
(1) Kepala Badan membuka rekening penampungan Dana Bantuan Masyarakat pada Bank Pemerintah.
(2) Apabila diperlukan Kepala Badan dapat membuka rekening bank khusus untuk menampungbantuan tunai berupa valuta asing.
(3) Pembukaan rekening bank sebagaimana dimaksud pada ayat (1) dan ayat (2) dilaksanakan setelah mendapat persetujuan Menteri Keuangan.
(4) Permohonan persetujuan pembukaan rekening bank sebagaimana dimaksud pada ayat (3) oleh Kepala BNPB disampaikan kepada Menteri Keuangan Up. Direktur Pengelolaan Kas Negara (PKN) dengan tembusan Direktur Jenderal Pengelolaan Utang.
(5) Rekening Bank sebagaimana dimaksud pada ayat (1) menggunakan nama Rekening BNPBuntuk Bantuan Penanggulangan Bencana.', 'BAB II', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2010 tentang Pedoman Pengumpulan dan Pengelolaan Dana Masyarakat Untuk Bantuan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7783, 'perka-23-2010', 5, 'menetapkan', 'BAB II (lanjutan 1)', NULL, 5, 'Pasa15 Rekening BNPB untuk Penanggulangan Baneana digunakan untuk menampung bantuan tunai yang diterima dari masyarakat umum seeara pribadi, kelompok danj atau golongan, lembaga usaha baik yang berasal dari dalam negeri maupun luar negeri seeara suka-rela/tanpa paksaan sebagai hibah kepada Negara untuk keperluan bantuan penanggulangan beneana diseluruhwilayah negara Republik Indonesia.
Pasa16
(1) Rekening BNPB untuk Penanggulangan Baneana bersifat sementarajuntuk periode yang telah ditentukan.
(2) Penggunaan rekening sebagaimana dimaksud dalam Pasal 4 ayat (1) dapat diperpanjang oleh Kepala Badan sesuaikebutuhan.
(3) Kepala Badan melakukan penutupan Rekening untuk Penanggulangan Beneana apabila dinyatakan tidak diperlukan lagi.
(4) Penutupan rekening sebagaimana dimaksud pada ayat (3) dinyatakan melalui Surat KeputusanKepala Badan dan disampaikan kepadaMenteri Keuangan, Pasa17
(1) Agar masyarakat mengetahui pembukaan Rekening BNPB untuk Bantuan penanggulangan Beneana, BNPB dapat melakukan publikasi melalui media massa Nasional atau Intemasional kepada masyarakat tentang maksud dan tujuan dibukanya rekening Bank sebagaimana dimaksud dalam Pasal 3 kepada masyarakat.
(2) Biaya publikasi rekening sebagaimana dimaksud pada ayat (1) dibebankan pada Daftar Isian Pelaksanaan Anggaran BNPB.
Bagian II Pengelolaan Rekening Pasal8');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7783, 'Pasa15 Rekening BNPB untuk Penanggulangan Baneana digunakan untuk menampung bantuan tunai yang diterima dari masyarakat umum seeara pribadi, kelompok danj atau golongan, lembaga usaha baik yang berasal dari dalam negeri maupun luar negeri seeara suka-rela/tanpa paksaan sebagai hibah kepada Negara untuk keperluan bantuan penanggulangan beneana diseluruhwilayah negara Republik Indonesia.
Pasa16
(1) Rekening BNPB untuk Penanggulangan Baneana bersifat sementarajuntuk periode yang telah ditentukan.
(2) Penggunaan rekening sebagaimana dimaksud dalam Pasal 4 ayat (1) dapat diperpanjang oleh Kepala Badan sesuaikebutuhan.
(3) Kepala Badan melakukan penutupan Rekening untuk Penanggulangan Beneana apabila dinyatakan tidak diperlukan lagi.
(4) Penutupan rekening sebagaimana dimaksud pada ayat (3) dinyatakan melalui Surat KeputusanKepala Badan dan disampaikan kepadaMenteri Keuangan, Pasa17
(1) Agar masyarakat mengetahui pembukaan Rekening BNPB untuk Bantuan penanggulangan Beneana, BNPB dapat melakukan publikasi melalui media massa Nasional atau Intemasional kepada masyarakat tentang maksud dan tujuan dibukanya rekening Bank sebagaimana dimaksud dalam Pasal 3 kepada masyarakat.
(2) Biaya publikasi rekening sebagaimana dimaksud pada ayat (1) dibebankan pada Daftar Isian Pelaksanaan Anggaran BNPB.
Bagian II Pengelolaan Rekening Pasal8', 'BAB II (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2010 tentang Pedoman Pengumpulan dan Pengelolaan Dana Masyarakat Untuk Bantuan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7784, 'perka-23-2010', 6, 'menetapkan', 'BAB II (lanjutan 2)', NULL, 5, '(1) Kepala Badan menunjuk Bendahara Pengeluaran Pembantu ( BPP) Pengelola Rekening sebagai pengelola dan penanggungjawab Rekening BNPB untuk Bantuan PenanggulanganBeneana. ,
(2) BPP sebagaimana dimaksud pada ayat (1) melaksanakan tugas kebendaharaan sesuai ketentuan perundang-undangan termasuk melaksanakan pembukuan terhadap transaksi keuangan yang menyangkut rekening yang menjadi tanggungjawabnya.
Pasal9
(1) BPP Pengelola Rekening bertanggungjawab secara penuh terhadap Dana Bantuan masyarakat yang berada dalam pengelolaannya.
(2) BPPPengelolaRekeningberkoordinasi dengan Bendahara Pengeluarandalam hal pengelolaandana hibah.
Pasal10
(1) Dalam melaksanakan tugasnya BPP Pengelola Rekeningdapat dibantu oleh satu atau lebih pegawaisesuai kebutuhan.
(2) Pegawai sebagaimana dimaksud pad a ayat (1) membantu BPP Pengelola Rekening dalam penyelenggaraan administrasi bendahara.
BABIV PENGELOLAANDANAMASYARAKAT Bagian I Registrasi Dana dan Revisi Daftar Isian Pelaksanaan Anggaran (DIPA) Pasalll
(1) Berdasarkan laporan penerimaan dana dari Bendahara Pengeluaran, Kepala Badan mengajukan permintaan registrasi ke Direktorat Jenderal Pengelolaan Utang Kementerian Keuangan atas Dana Bantuan Masyarakat yang diterima sebagai hibah sesuai keten tuan berlaku.
(2) BPP Pengelola Dana menyiapkan dokumen yang diperlukan untuk kelengkapan permintaan registrasi dana masyarakat ke Direktorat Jenderal Pengelolaan Utang Kementerian Keuangan.
Pasal12');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7784, '(1) Kepala Badan menunjuk Bendahara Pengeluaran Pembantu ( BPP) Pengelola Rekening sebagai pengelola dan penanggungjawab Rekening BNPB untuk Bantuan PenanggulanganBeneana. ,
(2) BPP sebagaimana dimaksud pada ayat (1) melaksanakan tugas kebendaharaan sesuai ketentuan perundang-undangan termasuk melaksanakan pembukuan terhadap transaksi keuangan yang menyangkut rekening yang menjadi tanggungjawabnya.
