INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7790, 'perka-23-2010', 12, 'menetapkan', 'BAB VII (lanjutan 1)', NULL, 9, '(1) Organisasi Kernasyarakatan, organisasi keaga.maan dan media masa yang melaksanakan pengumpulan sumbangan untuk korban bencana berdasarkanijin Kementerian Sosial, Gubernur, Bupati/walikota harus menyampaikan laporan kepada Kernenterian Sosial, BNPB, Guberrrur, Bupati dan WaH Kota.
(2) Sistem penerimaan dan penyaluran bantuan bencana yang dilakukan oleh masyaraka t se bagaimana dimaksud pada aya t (1) secara tekhnis akan dia tur tersendiri.
(3) Bagi penyelenggara pengumpulan dan pengelolaan Dana Masyarakat untuk Bantuan Penanganan Bencana tersebut yang ti.dak mengi.ndahkan ketentuan pada ayat (1) dan atau melakukan penyimpangan dalam pelaksanaannya akan dikenakan sanksi sesuai ketentuan peraturan perundang-undangan yang berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7790, '(1) Organisasi Kernasyarakatan, organisasi keaga.maan dan media masa yang melaksanakan pengumpulan sumbangan untuk korban bencana berdasarkanijin Kementerian Sosial, Gubernur, Bupati/walikota harus menyampaikan laporan kepada Kernenterian Sosial, BNPB, Guberrrur, Bupati dan WaH Kota.
(2) Sistem penerimaan dan penyaluran bantuan bencana yang dilakukan oleh masyaraka t se bagaimana dimaksud pada aya t (1) secara tekhnis akan dia tur tersendiri.
(3) Bagi penyelenggara pengumpulan dan pengelolaan Dana Masyarakat untuk Bantuan Penanganan Bencana tersebut yang ti.dak mengi.ndahkan ketentuan pada ayat (1) dan atau melakukan penyimpangan dalam pelaksanaannya akan dikenakan sanksi sesuai ketentuan peraturan perundang-undangan yang berlaku.', 'BAB VII (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2010 tentang Pedoman Pengumpulan dan Pengelolaan Dana Masyarakat Untuk Bantuan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7791, 'perka-23-2010', 13, 'menetapkan', 'BAB VIII', NULL, 9, 'KETENTUANPENUTUP Pasa126 Dengan ditetapkannya Peraturan Kepala Badan ini, maka segala peraturan yang berkaitan dengan pengumpulan dana dari masyarakat untuk bantuan bencana yang setingkat dengan peraturan irn dinyatakan tetap berlaku sepanjang tidak bertentangan dengan peraturan ini.
Pasal 27 Peraturan ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7791, 'KETENTUANPENUTUP Pasa126 Dengan ditetapkannya Peraturan Kepala Badan ini, maka segala peraturan yang berkaitan dengan pengumpulan dana dari masyarakat untuk bantuan bencana yang setingkat dengan peraturan irn dinyatakan tetap berlaku sepanjang tidak bertentangan dengan peraturan ini.
Pasal 27 Peraturan ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'BAB VIII', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2010 tentang Pedoman Pengumpulan dan Pengelolaan Dana Masyarakat Untuk Bantuan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7792, 'perka-23-2010', 14, 'lain', 'Penutup', NULL, 9, 'Ditetapkan di Jakarta pada tanggal 31 Desember 2010 KEPALABADAN NASIONAL PENANGGULANGANBENCANA, S~AMSUL MAARIF J Diundangkan di Jakarta pada tanggal 29 Sep~ember 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, SERITA NEGARA REPUBLIK INDONESIA TAHUN 201~t NOMOR 1419 Salinan sesuai dengan aslinya Kepala Biro Hukum dan Kerjasama Badan Nasional Penan ulangan Bencana');
