INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7798, 'perka-23-2014', 5, 'pasal', 'Pasal 2', 'BAB III MAKSUD DAN TUJUAN', 4, 'Ruang lingkup peraturan ini, meliputi:
a. Prinsip dasar, kebijakan dan strategi standarisasi logistic
b. Kategori, paket dan standar persediaan logistic
c. Metode perhitungan persediaan logistik bagi BNPB, BPBD Propinsi dan Kabupaten/Kota
d. Pengendalian, pengawasan dan pertanggungjawaban;
5 2014, No.2080');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7798, 'Ruang lingkup peraturan ini, meliputi:
a. Prinsip dasar, kebijakan dan strategi standarisasi logistic
b. Kategori, paket dan standar persediaan logistic
c. Metode perhitungan persediaan logistik bagi BNPB, BPBD Propinsi dan Kabupaten/Kota
d. Pengendalian, pengawasan dan pertanggungjawaban;
5 2014, No.2080', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7799, 'perka-23-2014', 6, 'pasal', 'Pasal 3', 'BAB III MAKSUD DAN TUJUAN', 5, 'MAKSUD Memberikan panduan bagi BNPB dan BPBD dalam menetapkan persediaan logistik minimal pada masa kesiapsiagaan menghadapi keadaan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7799, 'MAKSUD Memberikan panduan bagi BNPB dan BPBD dalam menetapkan persediaan logistik minimal pada masa kesiapsiagaan menghadapi keadaan darurat bencana.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7800, 'perka-23-2014', 7, 'pasal', 'Pasal 4', 'BAB IV PRINSIP DASAR, KEBIJAKAN, DAN STRATEGI', 5, 'TUJUAN
(1) Pemenuhan jumlah persediaan minimal yang wajib dipenuhi baik oleh BPBD secara mandiri dan/atau bersama-sama pemangku kepentingan.
(2) Meningkatkan kesiapsiagaan dan memperlancar pengerahan logistik pada saat kejadian bencana untuk bantuan kepada korban bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7800, 'TUJUAN
(1) Pemenuhan jumlah persediaan minimal yang wajib dipenuhi baik oleh BPBD secara mandiri dan/atau bersama-sama pemangku kepentingan.
(2) Meningkatkan kesiapsiagaan dan memperlancar pengerahan logistik pada saat kejadian bencana untuk bantuan kepada korban bencana.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7801, 'perka-23-2014', 8, 'pasal', 'Pasal 5', 'BAB IV PRINSIP DASAR, KEBIJAKAN, DAN STRATEGI', 5, 'Prinsip dasar standarisasi logistik :
a. Menggunakan standar yang berlaku dan telah ditetapkan oleh pemerintah dan kaidah logistik secara umum.
b. Menyusun standar logistik yang diarahkan untuk memenuhi kebutuhan dasar berbasis pada korban bencana termasuk kelompok rentan.
c. Mempergunakan metode standarisasi yang mudah, cepat, tepat dan akuntabel.
d. Berdasarkan pada jumlah penduduk dan prosentase korban bencana di wilayah bencana.
e. Dalam memenuhi persediaan logistik minimal sepenuhnya memanfaatkan sumber daya internal daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7801, 'Prinsip dasar standarisasi logistik :
a. Menggunakan standar yang berlaku dan telah ditetapkan oleh pemerintah dan kaidah logistik secara umum.
b. Menyusun standar logistik yang diarahkan untuk memenuhi kebutuhan dasar berbasis pada korban bencana termasuk kelompok rentan.
c. Mempergunakan metode standarisasi yang mudah, cepat, tepat dan akuntabel.
d. Berdasarkan pada jumlah penduduk dan prosentase korban bencana di wilayah bencana.
e. Dalam memenuhi persediaan logistik minimal sepenuhnya memanfaatkan sumber daya internal daerah.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7802, 'perka-23-2014', 9, 'pasal', 'Pasal 6', 'BAB IV PRINSIP DASAR, KEBIJAKAN, DAN STRATEGI', 5, 'Kebijakan standarisasi logistik adalah:
a. Menetapkan standar logistik sebagai bahan pengambilan keputusan.
b. Menetapkan standar logistik diarahkan untuk memenuhi kebutuhan dasar kemanusiaan dan sesuai kebijakan pembangunan.
c. Menetapkan standar logistik didasarkan pada kebutuhan kelompok rentan seperti orang berkebutuhan khusus, penyandang disabilitas, lansia, perempuan dan anak.
2014, No.2080 6
d. Menetapkan standar logistik berdasarkan rumus jumlah penduduk dikali prosentase dikali hari (JP x PR x H).
e. Menetapkan standar logistik dilakukan melalui pemetaan sumberdaya yang ada didaerah serta mekanisme kerjasama antar pihak.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7802, 'Kebijakan standarisasi logistik adalah:
a. Menetapkan standar logistik sebagai bahan pengambilan keputusan.
b. Menetapkan standar logistik diarahkan untuk memenuhi kebutuhan dasar kemanusiaan dan sesuai kebijakan pembangunan.
c. Menetapkan standar logistik didasarkan pada kebutuhan kelompok rentan seperti orang berkebutuhan khusus, penyandang disabilitas, lansia, perempuan dan anak.
2014, No.2080 6
d. Menetapkan standar logistik berdasarkan rumus jumlah penduduk dikali prosentase dikali hari (JP x PR x H).
e. Menetapkan standar logistik dilakukan melalui pemetaan sumberdaya yang ada didaerah serta mekanisme kerjasama antar pihak.', 'Pasal 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7803, 'perka-23-2014', 10, 'pasal', 'Pasal 7', 'BAB V KATEGORI DAN PAKET LOGISTIK', 6, 'Strategi standarisasi logistik adalah:
a. Diutamakan untuk memenuhi kebutuhan logistik dalam keadaan siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.
b. Dilaksanakan bersama-sama dengan pemangku kepentingan yang bekerja pada bidang keadaan darurat bencana dan bidang logistik bencana.
c. Dijalankan melalui serangkaian perencanaan sampai pemantauan dan evaluasi.
d. Dilaksanakan dalam rangka pemenuhan kebutuhan dasar dan pengembalian hak korban bencana secara bermartabat.
e. Melaksanakan standar logistik yang ditetapkan dengan mengikutsertakan para pemangku kepentingan.
f. Dapat diperoleh melalui kerjasama pemesanan dan pembelian dengan pihak penyedia logistik sesuai mekanisme pasar dalam keadaan tidak tidak terjadi bencana.
g. Memperkuat koordinasi dan kerja sama antar pemangku kepentingan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7803, 'Strategi standarisasi logistik adalah:
a. Diutamakan untuk memenuhi kebutuhan logistik dalam keadaan siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.
b. Dilaksanakan bersama-sama dengan pemangku kepentingan yang bekerja pada bidang keadaan darurat bencana dan bidang logistik bencana.
c. Dijalankan melalui serangkaian perencanaan sampai pemantauan dan evaluasi.
d. Dilaksanakan dalam rangka pemenuhan kebutuhan dasar dan pengembalian hak korban bencana secara bermartabat.
e. Melaksanakan standar logistik yang ditetapkan dengan mengikutsertakan para pemangku kepentingan.
f. Dapat diperoleh melalui kerjasama pemesanan dan pembelian dengan pihak penyedia logistik sesuai mekanisme pasar dalam keadaan tidak tidak terjadi bencana.
g. Memperkuat koordinasi dan kerja sama antar pemangku kepentingan.', 'Pasal 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7804, 'perka-23-2014', 11, 'pasal', 'Pasal 8', 'BAB V KATEGORI DAN PAKET LOGISTIK', 6, 'Kategori logistik disusun berdasarkan:
a. Pangan, yang termasuk dalam kategori ini adalah makanan pokok (beras/sagu/jagung/ubi,dll), lauk-pauk, air bersih, bahan makanan pokok tambahan seperti mie, susu, kopi, teh, dan sebagainya;
b. Sandang, yang termasuk dalam kategori ini adalah perlengkapan pribadi berupa baju, kaos dan celana anak-anak sampai dewasa lakilaki dan perempuan, sarung, kain batik panjang, kantong tidur (sleeping bag), handuk, selimut, daster, perlengkapan ibadah, perangkat lengkap pakaian dalam dan sebagainya;
c. Papan yang termasuk dalam kategori ini adalah Tenda Gulung, Tikar, Matras dan lain sebagainya; dan
d. Logistik lainnya, termasuk dalam kategori ini adalah, obat dan alat kesehatan habis pakai, kantong mayat, peralatan dapur keluarga dan lain sebagainya.
7 2014, No.2080');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7804, 'Kategori logistik disusun berdasarkan:
a. Pangan, yang termasuk dalam kategori ini adalah makanan pokok (beras/sagu/jagung/ubi,dll), lauk-pauk, air bersih, bahan makanan pokok tambahan seperti mie, susu, kopi, teh, dan sebagainya;
b. Sandang, yang termasuk dalam kategori ini adalah perlengkapan pribadi berupa baju, kaos dan celana anak-anak sampai dewasa lakilaki dan perempuan, sarung, kain batik panjang, kantong tidur (sleeping bag), handuk, selimut, daster, perlengkapan ibadah, perangkat lengkap pakaian dalam dan sebagainya;
c. Papan yang termasuk dalam kategori ini adalah Tenda Gulung, Tikar, Matras dan lain sebagainya; dan
d. Logistik lainnya, termasuk dalam kategori ini adalah, obat dan alat kesehatan habis pakai, kantong mayat, peralatan dapur keluarga dan lain sebagainya.
7 2014, No.2080', 'Pasal 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7805, 'perka-23-2014', 12, 'pasal', 'Pasal 9', 'BAB VI STANDAR PERSEDIAAN DAN METODE PENGHITUNGAN', 7, 'Paket logistik disusun berdasarkan:
a. Paket pangan, terdiri dari: paket 9 bahan pokok, paket makanan siap saji, paket lauk pauk, paket tambahan gizi/kelompok rentan, paket tambahan gizi anak/kelompok rentan;
b. Paket sandang, terdiri dari: paket sandang keluarga (ayah ibu dan 2 anak), paket sandang anak (laki-laki dan perempuan usia 6-14 tahun), paket sandang balita (laki-laki dan perempuan usia di bawah 5 tahun);
c. Paket papan, terdiri dari: tenda gulung, tikar, matras dan lain-lain; dan
d. Paket logistik lainnya, terdiri dari: paket P3K, paket kesehatan, paket kebersihan, kantong mayat dan peralatan rumah tangga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7805, 'Paket logistik disusun berdasarkan:
a. Paket pangan, terdiri dari: paket 9 bahan pokok, paket makanan siap saji, paket lauk pauk, paket tambahan gizi/kelompok rentan, paket tambahan gizi anak/kelompok rentan;
b. Paket sandang, terdiri dari: paket sandang keluarga (ayah ibu dan 2 anak), paket sandang anak (laki-laki dan perempuan usia 6-14 tahun), paket sandang balita (laki-laki dan perempuan usia di bawah 5 tahun);
c. Paket papan, terdiri dari: tenda gulung, tikar, matras dan lain-lain; dan
d. Paket logistik lainnya, terdiri dari: paket P3K, paket kesehatan, paket kebersihan, kantong mayat dan peralatan rumah tangga.', 'Pasal 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7806, 'perka-23-2014', 13, 'pasal', 'Pasal 10', 'BAB VI STANDAR PERSEDIAAN DAN METODE PENGHITUNGAN', 7, 'Stándar logistik sebagai stándar persediaan logistik, dihitung berdasarkan:
a. pemenuhan jumlah persediaan minimal berdasarkan jumlah penduduk;
b. Pemenuhan jumlah persediaan minimal berdasarkan prosentase jumlah korban bencana;
c. Pemenuhan jumlah persediaan minimal berdasarkan hari;
d. Pemenuhan jumlah persediaan minimal pangan berdasarkan pola konsumsi setempat;
e. Pemenuhan jumlah jenis barang sesuai dengan jenis ancaman bencana; dan
f. Pemenuhan jumlah barang sesuai dengan kualitas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7806, 'Stándar logistik sebagai stándar persediaan logistik, dihitung berdasarkan:
a. pemenuhan jumlah persediaan minimal berdasarkan jumlah penduduk;
b. Pemenuhan jumlah persediaan minimal berdasarkan prosentase jumlah korban bencana;
c. Pemenuhan jumlah persediaan minimal berdasarkan hari;
d. Pemenuhan jumlah persediaan minimal pangan berdasarkan pola konsumsi setempat;
e. Pemenuhan jumlah jenis barang sesuai dengan jenis ancaman bencana; dan
f. Pemenuhan jumlah barang sesuai dengan kualitas.', 'Pasal 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7807, 'perka-23-2014', 14, 'pasal', 'Pasal 11', 'BAB VI STANDAR PERSEDIAAN DAN METODE PENGHITUNGAN', 7, 'Metode perhitungan persediaan logistik umum, sebagai berikut:
a. Rumus Perhitungan Paket Pangan: Jumlah Penduduk x Prosentase x Hari = Jumlah Persediaan Minimum (Buffer Stock);
b. Rumus Perhitungan Paket Sandang: Jumlah Penduduk x Prosentase x Hari/ 4 Jiwa = Jumlah Persediaan Minimum (Buffer Stock); dan
c. Rumus Perhitungan Paket Papan: Jumlah Penduduk x Prosentase x Hari/ 4 Jiwa = Jumlah Persediaan Minimum (Buffer Stock).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7807, 'Metode perhitungan persediaan logistik umum, sebagai berikut:
a. Rumus Perhitungan Paket Pangan: Jumlah Penduduk x Prosentase x Hari = Jumlah Persediaan Minimum (Buffer Stock);
b. Rumus Perhitungan Paket Sandang: Jumlah Penduduk x Prosentase x Hari/ 4 Jiwa = Jumlah Persediaan Minimum (Buffer Stock); dan
c. Rumus Perhitungan Paket Papan: Jumlah Penduduk x Prosentase x Hari/ 4 Jiwa = Jumlah Persediaan Minimum (Buffer Stock).', 'Pasal 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7808, 'perka-23-2014', 15, 'pasal', 'Pasal 12', 'BAB VI STANDAR PERSEDIAAN DAN METODE PENGHITUNGAN', 7, '(1) Jumlah Penduduk adalah Data BPS terakhir.
(2) Prosentase adalah 1% dari jumlah penduduk (asumsi).
2014, No.2080 8
(3) 1% adalah asumsi korban bencana dari total jumlah penduduk/tahun.
(4) Jumlah 1% tersebut adalah jumlah yang harus dipenuhi oleh BPBD secara mandiri dan/atau bersama para pemangku kepentingan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7808, '(1) Jumlah Penduduk adalah Data BPS terakhir.
(2) Prosentase adalah 1% dari jumlah penduduk (asumsi).
2014, No.2080 8
(3) 1% adalah asumsi korban bencana dari total jumlah penduduk/tahun.
(4) Jumlah 1% tersebut adalah jumlah yang harus dipenuhi oleh BPBD secara mandiri dan/atau bersama para pemangku kepentingan.', 'Pasal 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7809, 'perka-23-2014', 16, 'pasal', 'Pasal 13', 'BAB VI STANDAR PERSEDIAAN DAN METODE PENGHITUNGAN', 8, 'Metode perhitungan persediaan logistik khusus, sebagai berikut :
a. Rumus Perhitungan Paket Pangan : Jumlah Penduduk x Prosentase x Hari = Jumlah Persediaan Minimum (Buffer Stock);
b. Rumus Perhitungan Paket Sandang : Jumlah Penduduk x Prosentase x Hari/ 4 Jiwa = Jumlah Persediaan Minimum (Buffer Stock); dan
c. Rumus Perhitungan Paket Papan : Jumlah Penduduk x Prosentase x Hari/ 4 Jiwa = Jumlah Persediaan Minimum (Buffer Stock).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7809, 'Metode perhitungan persediaan logistik khusus, sebagai berikut :
a. Rumus Perhitungan Paket Pangan : Jumlah Penduduk x Prosentase x Hari = Jumlah Persediaan Minimum (Buffer Stock);
b. Rumus Perhitungan Paket Sandang : Jumlah Penduduk x Prosentase x Hari/ 4 Jiwa = Jumlah Persediaan Minimum (Buffer Stock); dan
c. Rumus Perhitungan Paket Papan : Jumlah Penduduk x Prosentase x Hari/ 4 Jiwa = Jumlah Persediaan Minimum (Buffer Stock).', 'Pasal 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7810, 'perka-23-2014', 17, 'pasal', 'Pasal 14', 'BAB VII PENGENDALIAN, PENGAWASAN DAN PERTANGGUNGJAWABAN', 8, '(1) Jumlah Penduduk adalah Data BPS terakhir.
(2) Prosentase adalah 4% dari jumlah penduduk (asumsi).
(3) 4% adalah asumsi korban bencana dari total jumlah penduduk/tahun dan Peta Index Rawan Bencana.
(4) Jumlah 4% tersebut adalah jumlah yang harus dipenuhi oleh BPBD secara mandiri dan/atau bersama para pemangku kepentingan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7810, '(1) Jumlah Penduduk adalah Data BPS terakhir.
(2) Prosentase adalah 4% dari jumlah penduduk (asumsi).
(3) 4% adalah asumsi korban bencana dari total jumlah penduduk/tahun dan Peta Index Rawan Bencana.
(4) Jumlah 4% tersebut adalah jumlah yang harus dipenuhi oleh BPBD secara mandiri dan/atau bersama para pemangku kepentingan.', 'Pasal 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7811, 'perka-23-2014', 18, 'pasal', 'Pasal 15', 'BAB VII PENGENDALIAN, PENGAWASAN DAN PERTANGGUNGJAWABAN', 8, 'Pengendalian Pengendalian standar logistik dalam bentuk pelaporan pengadaan, penggunaan dan pemeliharaan logistik penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7811, 'Pengendalian Pengendalian standar logistik dalam bentuk pelaporan pengadaan, penggunaan dan pemeliharaan logistik penanggulangan bencana.', 'Pasal 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 23 Tahun 2014 tentang Standarisasi Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7812, 'perka-23-2014', 19, 'pasal', 'Pasal 16', 'BAB VII PENGENDALIAN, PENGAWASAN DAN PERTANGGUNGJAWABAN', 8, 'Pengawasan Pengawasan terhadap:
