INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7813, 'perka-23-2014', 20, 'pasal', 'Pasal 17', 'BAB VIII PENUTUP', 8, 'Pertanggungjawaban Pertanggungjawaban keuangan maupun kinerja dalam standardisasi logistik dilakukan pada setiap tahapan persiapan, proses dan setelah proses pengiriman bantuan, dalam bentuk laporan secara berjenjang dan berkala sesuai dengan prinsip akuntabilitas dan transparansi.
