INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7820, 'perka-24-2010', 4, 'pasal', 'Pasal 1', NULL, 4, 'Pedoman Penyusunan Rencana Operasi Darurat Bencana sebagaimana tersebut dalam Lampiran Peraturan ini merupakan pelaksanaan dari Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana yang tidak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7820, 'Pedoman Penyusunan Rencana Operasi Darurat Bencana sebagaimana tersebut dalam Lampiran Peraturan ini merupakan pelaksanaan dari Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana yang tidak terpisahkan dari Peraturan ini.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7821, 'perka-24-2010', 5, 'pasal', 'Pasal 2', NULL, 4, 'Pedoman Penyusunan Rencana Operasi Darurat Bencana sebagaimana dimaksud dalam Pasal 1, merupakan acuan ba8.gi Pelaksana Komando Tanggap Darurat Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7821, 'Pedoman Penyusunan Rencana Operasi Darurat Bencana sebagaimana dimaksud dalam Pasal 1, merupakan acuan ba8.gi Pelaksana Komando Tanggap Darurat Bencana.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7822, 'perka-24-2010', 6, 'pasal', 'Pasal 3', NULL, 4, 'Hal-hal yang belum diatur dalam Peraturan ini, akan diatur kemudian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7822, 'Hal-hal yang belum diatur dalam Peraturan ini, akan diatur kemudian.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7823, 'perka-24-2010', 7, 'pasal', 'Pasal 4', NULL, 4, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7823, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7824, 'perka-24-2010', 8, 'lain', 'Penutup', NULL, 4, 'Ditetapkan di Jakarta pada tanggal 31 Desember 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA DR. SYAMSUL MAARIF, M.Si');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7824, 'Ditetapkan di Jakarta pada tanggal 31 Desember 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA DR. SYAMSUL MAARIF, M.Si', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7825, 'perka-24-2010', 9, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 24 TAHUN 2010 TANGGAL : 31 DESEMBER 2010 BAB I PENDAHULUAN A. Latar Belakang Wilayah Negara Kesatuan Republik Indonesia memiliki kondisi geografis, geologis, hidrologis dan demografis yang memungkinkan terjadinya bencana, baik yang disebabkan oleh faktor alam, faktor non alam maupun faktor manusia yang dapat menyebabkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis sehingga dalam keadaan tertentu dapat menghambat pembangunan nasional.
Dalam penanggulangan bencana, khususnya pada status keadaan darurat bencana, diperlukan penanganan bencana dalam satu komando berdasarkan sistem komando darurat bencana yang cepat, tepat, efektif, efisien, terpadu dan akuntabel, agar dapat meminimalkan korban manusia dan kerugian harta benda.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7825, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 24 TAHUN 2010 TANGGAL : 31 DESEMBER 2010 BAB I PENDAHULUAN A. Latar Belakang Wilayah Negara Kesatuan Republik Indonesia memiliki kondisi geografis, geologis, hidrologis dan demografis yang memungkinkan terjadinya bencana, baik yang disebabkan oleh faktor alam, faktor non alam maupun faktor manusia yang dapat menyebabkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis sehingga dalam keadaan tertentu dapat menghambat pembangunan nasional.
Dalam penanggulangan bencana, khususnya pada status keadaan darurat bencana, diperlukan penanganan bencana dalam satu komando berdasarkan sistem komando darurat bencana yang cepat, tepat, efektif, efisien, terpadu dan akuntabel, agar dapat meminimalkan korban manusia dan kerugian harta benda.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7826, 'perka-24-2010', 10, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'Penanganan darurat bencana pada status darurat bencana yang dimulai status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan memerlukan rencana operasi. Pada situasi status siaga darurat, dimana potensi terjadinya bencana makin meningkat, rencana operasi didasarkan kepada asumsi, prediksi kejadian bencana dan skenario-skenario. Pada situasi bencana telah terjadi (status tanggap darurat dan transisi darurat ke pemulihan) diperlukan rencana operasi untuk penyelenggaraan tanggap darurat dalam rangka penyelamatan, pertolongan dan evakuasi korban bencana, pemenuhan kebutuhan dasar dan penyediaan personil, logistik dan peralatan penanganan darurat.
Rencana operasi yang merupakan aktifasi dari rencana kontinjensi harus akurat sesuai dengan perkembangan bencana dan dapat mencerminkan informasi-informasi yang dihimpun dalam proses perencanaan. Rencana operasi harus dipersiapkan dan didistribusikan sebelum operasi dimulai, dibuat untuk setiap periode operasi, serta dimutakhirkan setiap hari.
Karena kompleksitas rencana operasi darurat bencana yang melibatkan berbagai institusi/lembaga dan organisasi terkait, maka perlu disusun pedoman penyusunan rencana operasi darurat bencana.
B. Maksud dan Tujuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7826, 'Penanganan darurat bencana pada status darurat bencana yang dimulai status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan memerlukan rencana operasi. Pada situasi status siaga darurat, dimana potensi terjadinya bencana makin meningkat, rencana operasi didasarkan kepada asumsi, prediksi kejadian bencana dan skenario-skenario. Pada situasi bencana telah terjadi (status tanggap darurat dan transisi darurat ke pemulihan) diperlukan rencana operasi untuk penyelenggaraan tanggap darurat dalam rangka penyelamatan, pertolongan dan evakuasi korban bencana, pemenuhan kebutuhan dasar dan penyediaan personil, logistik dan peralatan penanganan darurat.
Rencana operasi yang merupakan aktifasi dari rencana kontinjensi harus akurat sesuai dengan perkembangan bencana dan dapat mencerminkan informasi-informasi yang dihimpun dalam proses perencanaan. Rencana operasi harus dipersiapkan dan didistribusikan sebelum operasi dimulai, dibuat untuk setiap periode operasi, serta dimutakhirkan setiap hari.
Karena kompleksitas rencana operasi darurat bencana yang melibatkan berbagai institusi/lembaga dan organisasi terkait, maka perlu disusun pedoman penyusunan rencana operasi darurat bencana.
B. Maksud dan Tujuan', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7827, 'perka-24-2010', 11, 'lampiran', 'Lampiran hal. 6', NULL, 6, '1. Maksud Pedoman Penyusunan Rencana Operasi Darurat Bencana ini dimaksudkan untuk memberikan panduan kepada Badan Nasional Penanggulangan Bencana (BNPB)/Badan Penanggulangan Bencana Daerah (BPBD), komandan dan jajaran Komando Darurat Bencana, serta instansi/lembaga/organisasi terkait dalam penyusunan rencana operasi darurat bencana.
2. Tujuan Pedoman ini bertujuan agar Komando Darurat Bencana dan semua pihak terkait dalam operasi darurat bencana memiliki kesamaan persepsi sehingga dapat melaksanakan tugas penyelenggaraan operasi penanggulangan darurat bencana secara cepat, tepat, efektif, efisien, aman, terpadu dan akuntabel.
C. Landasan Hukum
1. Undang-Undang Dasar 1945, Pembukaan UUD 1945.
2. Undang-Undang Nomor 32 Tahun 2004, tentang Pemerintahan Daerah.
3. Undang-Undang Nomor 24 Tahun 2007, tentang Penanggulangan Bencana.
4. Peraturan Presiden, Nomor 8 Tahun 2008, tentang Badan Nasional Penanggulangan Bencana.
4. Peraturan Pemerintah Nomor 21 Tahun 2008, tentang Penyelenggaraan Penanggulangan Bencana.
5. Peraturan Pemerintah Nomor 22 Tahun 2008, tentang Pendanaan dan Pengelolaan Bantuan Bencana.
6. Peraturan Pemerintah Nomor 23 Tahun 2008, tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana.
7. Keputusan Menteri Dalam Negeri Nomor 46 Tahun 2008, tentang Pedoman Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7827, '1. Maksud Pedoman Penyusunan Rencana Operasi Darurat Bencana ini dimaksudkan untuk memberikan panduan kepada Badan Nasional Penanggulangan Bencana (BNPB)/Badan Penanggulangan Bencana Daerah (BPBD), komandan dan jajaran Komando Darurat Bencana, serta instansi/lembaga/organisasi terkait dalam penyusunan rencana operasi darurat bencana.
2. Tujuan Pedoman ini bertujuan agar Komando Darurat Bencana dan semua pihak terkait dalam operasi darurat bencana memiliki kesamaan persepsi sehingga dapat melaksanakan tugas penyelenggaraan operasi penanggulangan darurat bencana secara cepat, tepat, efektif, efisien, aman, terpadu dan akuntabel.
C. Landasan Hukum
1. Undang-Undang Dasar 1945, Pembukaan UUD 1945.
2. Undang-Undang Nomor 32 Tahun 2004, tentang Pemerintahan Daerah.
3. Undang-Undang Nomor 24 Tahun 2007, tentang Penanggulangan Bencana.
4. Peraturan Presiden, Nomor 8 Tahun 2008, tentang Badan Nasional Penanggulangan Bencana.
4. Peraturan Pemerintah Nomor 21 Tahun 2008, tentang Penyelenggaraan Penanggulangan Bencana.
5. Peraturan Pemerintah Nomor 22 Tahun 2008, tentang Pendanaan dan Pengelolaan Bantuan Bencana.
6. Peraturan Pemerintah Nomor 23 Tahun 2008, tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana.
7. Keputusan Menteri Dalam Negeri Nomor 46 Tahun 2008, tentang Pedoman Organisasi dan Tata Kerja Badan Penanggulangan Bencana Daerah.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7828, 'perka-24-2010', 12, 'lampiran', 'Lampiran hal. 7', NULL, 7, '8. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008, tentang Pedoman Pembentukan Badan Penanggulangan Bencana Daerah.
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008, tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana.
10. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008, tentang Pedoman Komando Tanggap Darurat Bencana.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Status Keadaan Darurat Bencana dimulai sejak status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.
3. Siaga Darurat adalah serangkaian kegiatan yang dilakukan dengan segera pada saat potensi bencana terjadi untuk menghadapi dampak buruk yang mungkin ditimbulkan, meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan kelompok rentan dan pengurusan pengungsi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7828, '8. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008, tentang Pedoman Pembentukan Badan Penanggulangan Bencana Daerah.
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008, tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana.
10. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008, tentang Pedoman Komando Tanggap Darurat Bencana.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Status Keadaan Darurat Bencana dimulai sejak status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.
3. Siaga Darurat adalah serangkaian kegiatan yang dilakukan dengan segera pada saat potensi bencana terjadi untuk menghadapi dampak buruk yang mungkin ditimbulkan, meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan kelompok rentan dan pengurusan pengungsi.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7829, 'perka-24-2010', 13, 'lampiran', 'Lampiran hal. 7', NULL, 7, '4. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan kelompok rentan, pengurusan pengungsi, serta pemulihan darurat.
5. Transisi darurat ke pemulihan adalah serangkaian kegiatan yang dilakukan dengan segera yang meliputi pemenuhan kebutuhan dasar, perlindungan kelompok rentan, dan perbaikan darurat.
6. Rencana Operasi Darurat Bencana adalah suatu proses perencanaan tindakan operasi darurat bencana dengan menyepakati tujuan operasi dan ketetapan tindakan teknis dan manejerial untuk penanganan darurat bencana dan disusun berdasarkan berbagai masukan penanganan bencana termasuk rencana kontinjensi dan informasi bencana untuk mencapai tujuan penanganan darurat bencana secara aman, efektif dan akuntabel.
7. Rencana Kontinjensi adalah suatu proses perencanaan ke depan terhadap keadaan yang tidak menentu untuk mencegah, atau menanggulangi secara lebih baik dalam situasi darurat atau kritis dengan menyepakati skenario dan tujuan, menetapkan tindakan teknis dan manejerial, serta tanggapan dan pengerahan yang telah disetujui bersama.
8. Korban bencana adalah orang atau kelompok orang yang menderita atau meninggal dunia akibat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7829, '4. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan kelompok rentan, pengurusan pengungsi, serta pemulihan darurat.
5. Transisi darurat ke pemulihan adalah serangkaian kegiatan yang dilakukan dengan segera yang meliputi pemenuhan kebutuhan dasar, perlindungan kelompok rentan, dan perbaikan darurat.
6. Rencana Operasi Darurat Bencana adalah suatu proses perencanaan tindakan operasi darurat bencana dengan menyepakati tujuan operasi dan ketetapan tindakan teknis dan manejerial untuk penanganan darurat bencana dan disusun berdasarkan berbagai masukan penanganan bencana termasuk rencana kontinjensi dan informasi bencana untuk mencapai tujuan penanganan darurat bencana secara aman, efektif dan akuntabel.
7. Rencana Kontinjensi adalah suatu proses perencanaan ke depan terhadap keadaan yang tidak menentu untuk mencegah, atau menanggulangi secara lebih baik dalam situasi darurat atau kritis dengan menyepakati skenario dan tujuan, menetapkan tindakan teknis dan manejerial, serta tanggapan dan pengerahan yang telah disetujui bersama.
8. Korban bencana adalah orang atau kelompok orang yang menderita atau meninggal dunia akibat bencana.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7830, 'perka-24-2010', 14, 'lampiran', 'Lampiran hal. 8', NULL, 8, '9. Sistem Komando Darurat Bencana selanjutnya disingkat SKD adalah suatu sistem penanganan darurat bencana berdasarkan satu komando yang digunakan oleh BNPB/BPBD untuk mengerahkan sumberdaya dari instansi/lembaga, lembaga usaha dan masyarakat untuk mencapai penanganan darurat bencana yang efektif.
10. Tim Reaksi Cepat disingkat TRC adalah suatu tim yang dibentuk oleh Kepala BNPB/BPBD terdiri dari instansi/lembaga teknis/non teknis terkait yang bertugas melaksanakan kaji cepat bencana, meliputi identifikasi cakupan lokasi bencana, jumlah korban bencana, kerusakan sarana dan prasarana, gangguan terhadap fungsi pelayanan umum dan pemerintahan, serta kemampuan sumberdaya alam maupun buatan, dan dampak bencana pada saat tanggap darurat bencana meliputi penilaian kebutuhan (need assesment), penilaian kerusakan dan kerugian (damage and losses assesment) serta memberikan dukungan pendampingan dalam penanganan darurat bencana.
11. Komando Darurat Bencana adalah organisasi penanganan keadaan darurat bencana yang dipimpin oleh seorang Komandan Darurat Bencana dan dibantu oleh Staf Komando dan Staf Umum, memiliki struktur organisasi standar yang menganut satu komando dengan mata rantai dan garis komando yang jelas dan memiliki satu kesatuan komando dalam mengkoordinasikan instansi/lembaga/ organisasi terkait untuk pengerahan sumberdaya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7830, '9. Sistem Komando Darurat Bencana selanjutnya disingkat SKD adalah suatu sistem penanganan darurat bencana berdasarkan satu komando yang digunakan oleh BNPB/BPBD untuk mengerahkan sumberdaya dari instansi/lembaga, lembaga usaha dan masyarakat untuk mencapai penanganan darurat bencana yang efektif.
10. Tim Reaksi Cepat disingkat TRC adalah suatu tim yang dibentuk oleh Kepala BNPB/BPBD terdiri dari instansi/lembaga teknis/non teknis terkait yang bertugas melaksanakan kaji cepat bencana, meliputi identifikasi cakupan lokasi bencana, jumlah korban bencana, kerusakan sarana dan prasarana, gangguan terhadap fungsi pelayanan umum dan pemerintahan, serta kemampuan sumberdaya alam maupun buatan, dan dampak bencana pada saat tanggap darurat bencana meliputi penilaian kebutuhan (need assesment), penilaian kerusakan dan kerugian (damage and losses assesment) serta memberikan dukungan pendampingan dalam penanganan darurat bencana.
11. Komando Darurat Bencana adalah organisasi penanganan keadaan darurat bencana yang dipimpin oleh seorang Komandan Darurat Bencana dan dibantu oleh Staf Komando dan Staf Umum, memiliki struktur organisasi standar yang menganut satu komando dengan mata rantai dan garis komando yang jelas dan memiliki satu kesatuan komando dalam mengkoordinasikan instansi/lembaga/ organisasi terkait untuk pengerahan sumberdaya.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7831, 'perka-24-2010', 15, 'lampiran', 'Lampiran hal. 9', NULL, 9, '12. Staf Komando (Command Staff) adalah pembantu Komandan Darurat Bencana dalam menjalankan urusan Sekretariat, Hubungan Masyarakat, Perwakilan instansi/lembaga serta Keselamatan dan Keamanan.
13. Staf Umum (General Staff) adalah pembantu Komandan Darurat Bencana dalam menjalankan fungsi utama Komando Darurat Bencana untuk Bidang Operasi, Bidang Perencanaan, Bidang Logistik dan Peralatan serta Bidang Administrasi Keuangan untuk penanganan darurat bencana yang terjadi.
14. Fasilitas Komando Tanggap Bencana adalah personil, sarana dan prasarana pendukung penyelenggaraan penanganan darurat bencana yang dapat terdiri dari pusat komando, personil komando, gudang, sarana dan prasarana transportasi, peralatan, komunikasi dan informasi.
E. Ruang Lingkup Ruang lingkup pedoman ini meliputi proses penyusunan rencana operasi darurat bencana dengan sistematika sebagai berikut:
BAB I Pendahuluan BAB II Proses Penyusunan Rencana Operasi Darurat Bencana BAB III Prosedur Penyusunan Rencana Operasi Darurat Bencana BAB IV Tingkatan Rencana Operasi Darurat Bencana BAB V Organisasi dan Tata Kerja Komando Darurat Bencana BAB VI Penutup BAB II PROSES PENYUSUNAN RENCANA OPERASI DARURAT BENCANA Proses penyusunan rencana operasi darurat bencana merupakan tahapan penting dalam penanganan darurat bencana yang perlu mendapat perhatian agar operasi darurat bencana dapat diselenggarakan secara efektif yang berlaku untuk status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7831, '12. Staf Komando (Command Staff) adalah pembantu Komandan Darurat Bencana dalam menjalankan urusan Sekretariat, Hubungan Masyarakat, Perwakilan instansi/lembaga serta Keselamatan dan Keamanan.
13. Staf Umum (General Staff) adalah pembantu Komandan Darurat Bencana dalam menjalankan fungsi utama Komando Darurat Bencana untuk Bidang Operasi, Bidang Perencanaan, Bidang Logistik dan Peralatan serta Bidang Administrasi Keuangan untuk penanganan darurat bencana yang terjadi.
14. Fasilitas Komando Tanggap Bencana adalah personil, sarana dan prasarana pendukung penyelenggaraan penanganan darurat bencana yang dapat terdiri dari pusat komando, personil komando, gudang, sarana dan prasarana transportasi, peralatan, komunikasi dan informasi.
E. Ruang Lingkup Ruang lingkup pedoman ini meliputi proses penyusunan rencana operasi darurat bencana dengan sistematika sebagai berikut:
BAB I Pendahuluan BAB II Proses Penyusunan Rencana Operasi Darurat Bencana BAB III Prosedur Penyusunan Rencana Operasi Darurat Bencana BAB IV Tingkatan Rencana Operasi Darurat Bencana BAB V Organisasi dan Tata Kerja Komando Darurat Bencana BAB VI Penutup BAB II PROSES PENYUSUNAN RENCANA OPERASI DARURAT BENCANA Proses penyusunan rencana operasi darurat bencana merupakan tahapan penting dalam penanganan darurat bencana yang perlu mendapat perhatian agar operasi darurat bencana dapat diselenggarakan secara efektif yang berlaku untuk status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7832, 'perka-24-2010', 16, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'Dalam Rencana Operasi ditetapkan tujuan, tindakan-tindakan taktis/teknis dan manejerial serta inventarisasi potensi sumberdaya yang ada, sehingga Komandan Darurat Bencana beserta seluruh jajarannya dan organisasi yang terkait dapat melaksanakan penanganan darurat bencana.
Proses penyusunan rencana operasi terdiri dari tahapan-tahapan, yang merupakan suatu siklus perencanaan operasi dan merupakan prosedur tetap dalam penyusunan rencana operasi, yaitu:
A. Tindakan Awal B. Penetapan Tujuan dan Sasaran C. Rapat Rencana Taktis D. Persiapan Rapat Rencana Operasi E. Rapat Rencana Operasi F. Penetapan Rencana Operasi G. Rapat Penjelasan Rencana Operasi H. Pelaksanaan dan Pengakhiran Proses perencanaan dilaksanakan untuk menghasilkan rencana operasi darurat bencana yang dapat diimplementasikan secara efektif. Rencana Operasi atau Rencana Tindakan disiapkan oleh Kepala Bidang Perencanaan. Bidang-Bidang lain serta organisasi terkait memberikan masukan data dan informasi. Lampiran-1 menggambarkan siklus penyusunan rencana operasi darurat bencana.
A. Tindakan Awal
1. Mengaktifkan rencana kontinjensi yang terkait yang disesuaikan dengan kondisi bencana yang terjadi.
2. Pada status siaga darurat, rencana tindakan operasi darurat bencana didasarkan atas asumsi kejadian dan pembuatan skenario sesuai dengan jenis bencana yang akan dihadapi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7832, 'Dalam Rencana Operasi ditetapkan tujuan, tindakan-tindakan taktis/teknis dan manejerial serta inventarisasi potensi sumberdaya yang ada, sehingga Komandan Darurat Bencana beserta seluruh jajarannya dan organisasi yang terkait dapat melaksanakan penanganan darurat bencana.
Proses penyusunan rencana operasi terdiri dari tahapan-tahapan, yang merupakan suatu siklus perencanaan operasi dan merupakan prosedur tetap dalam penyusunan rencana operasi, yaitu:
A. Tindakan Awal B. Penetapan Tujuan dan Sasaran C. Rapat Rencana Taktis D. Persiapan Rapat Rencana Operasi E. Rapat Rencana Operasi F. Penetapan Rencana Operasi G. Rapat Penjelasan Rencana Operasi H. Pelaksanaan dan Pengakhiran Proses perencanaan dilaksanakan untuk menghasilkan rencana operasi darurat bencana yang dapat diimplementasikan secara efektif. Rencana Operasi atau Rencana Tindakan disiapkan oleh Kepala Bidang Perencanaan. Bidang-Bidang lain serta organisasi terkait memberikan masukan data dan informasi. Lampiran-1 menggambarkan siklus penyusunan rencana operasi darurat bencana.
A. Tindakan Awal
1. Mengaktifkan rencana kontinjensi yang terkait yang disesuaikan dengan kondisi bencana yang terjadi.
2. Pada status siaga darurat, rencana tindakan operasi darurat bencana didasarkan atas asumsi kejadian dan pembuatan skenario sesuai dengan jenis bencana yang akan dihadapi.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7833, 'perka-24-2010', 17, 'lampiran', 'Lampiran hal. 11', NULL, 11, '3. Tindakan operasi setelah bencana terjadi, yaitu pada status tanggap darurat bencana dan status transisi darurat ke pemulihan, diawali dengan analisis keadaan darurat bencana termasuk mengkaji kejadian dan perkembangan kejadian bencana atas dasar masukan dari:
a. Informasi umum kejadian awal, yang dapat bersumber dari pemerintah daerah, instansi/lembaga, masyarakat dan sumber-sumber lainnya.
b. Informasi resmi yang berasal dari sumber-sumber yang dapat dipertanggung jawabkan sesuai dengan kewenangannya, seperti Badan Meteorologi Klimatologi dan Geofisika (BMKG), Badan Geologi Departemen Eenergi Sumber Daya Mineral (ESDM), Departemen Pekerjaan Umum (PU), Departemen Kehutanan, dan Departemen Pertanian.
c. Informasi dari TRC yang ditugaskan baik oleh BNPB maupun oleh BPBD yang meliputi :
1) Cakupan lokasi bencana 2) Jumlah korban bencana 3) Kerusakan prasarana dan sarana 4) Gangguan terhadap fungsi pelayanan umum serta pemerintahan 5) Kemampuan sumberdaya alam maupun sumberdaya buatan 6) Upaya-upaya yang telah dilakukan 7) Kebutuhan mendesak yang harus segera dipenuhi
4. Kepala Bidang Perencanaan menuangkan semua informasi kejadian awal ke dalam Formulir Informasi Bencana (Formulir 1a- 1d, Lampiran 03-06), yang memuat informasi mengenai:
a. Sketsa/peta darurat bencana, peta sumberdaya dan peta evakuasi
b. Permintaan bantuan sumberdaya yang dibutuhkan
c. Sumber bantuan sumberdaya (BNPB/BPBD, instansi/lembaga, dunia usaha dan masyarakat)
d. Lokasi tujuan bantuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7833, '3. Tindakan operasi setelah bencana terjadi, yaitu pada status tanggap darurat bencana dan status transisi darurat ke pemulihan, diawali dengan analisis keadaan darurat bencana termasuk mengkaji kejadian dan perkembangan kejadian bencana atas dasar masukan dari:
a. Informasi umum kejadian awal, yang dapat bersumber dari pemerintah daerah, instansi/lembaga, masyarakat dan sumber-sumber lainnya.
b. Informasi resmi yang berasal dari sumber-sumber yang dapat dipertanggung jawabkan sesuai dengan kewenangannya, seperti Badan Meteorologi Klimatologi dan Geofisika (BMKG), Badan Geologi Departemen Eenergi Sumber Daya Mineral (ESDM), Departemen Pekerjaan Umum (PU), Departemen Kehutanan, dan Departemen Pertanian.
c. Informasi dari TRC yang ditugaskan baik oleh BNPB maupun oleh BPBD yang meliputi :
1) Cakupan lokasi bencana 2) Jumlah korban bencana 3) Kerusakan prasarana dan sarana 4) Gangguan terhadap fungsi pelayanan umum serta pemerintahan 5) Kemampuan sumberdaya alam maupun sumberdaya buatan 6) Upaya-upaya yang telah dilakukan 7) Kebutuhan mendesak yang harus segera dipenuhi
4. Kepala Bidang Perencanaan menuangkan semua informasi kejadian awal ke dalam Formulir Informasi Bencana (Formulir 1a- 1d, Lampiran 03-06), yang memuat informasi mengenai:
a. Sketsa/peta darurat bencana, peta sumberdaya dan peta evakuasi
b. Permintaan bantuan sumberdaya yang dibutuhkan
c. Sumber bantuan sumberdaya (BNPB/BPBD, instansi/lembaga, dunia usaha dan masyarakat)
d. Lokasi tujuan bantuan', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7834, 'perka-24-2010', 18, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'e. Ringkasan tindakan operasi
f. Ringkasan bantuan sumberdaya
5. Formulir Informasi Bencana ditujukan untuk memberikan informasi dasar kepada Komandan dan seluruh Staf Komando dan Staf Umum Komando Darurat Bencana mengenai situasi bencana dan kebutuhan bantuan sumberdaya yang diperlukan dalam penanganan darurat bencana.
6. Informasi Bencana didistribusikan kepada Staf Komando dan Staf Umum Komando.
B. Penetapan Tujuan dan Sasaran
1. Dengan adanya analisis kejadian awal dan informasi mengenai kebutuhan bantuan, tahapan proses perencanaan selanjutnya adalah menetapkan Tujuan dan Sasaran yang akan dicapai dalam operasi.
2. Komandan Komando Darurat Bencana memberikan arahan mengenai tujuan dan sasaran umum operasi; menetapkan strategi umum, kebijakan, batasan anggaran dan hukum dalam mencapai tujuan dan sasaran operasi.
3. Tujuan dan Sasaran Operasi dalam garis besar meliputi tindakan-tindakan untuk:
a. Penyelamatan dan evakuasi korban bencana
b. Pemenuhan kebutuhan dasar korban bencana
c. Penyediaan dan distribusi personil, logistik dan peralatan
d. Perlindungan kelompok rentan
e. Pemulihan dengan segera fungsi sarana dan prasarana vital
4. Tujuan dan Sasaran operasi dapat diurai dalam bentuk yang lebih khusus dan spesifik, antara lain:
a. Pertolongan darurat untuk mengantisipasi meluasnya dampak bencana
b. Evakuasi korban
c. Penyediaan air bersih dan sanitasi
d. Penyediaan sandang dan pangan
e. Pelayanan kesehatan
f. Penyediaan hunian sementara korban');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7834, 'e. Ringkasan tindakan operasi
f. Ringkasan bantuan sumberdaya
5. Formulir Informasi Bencana ditujukan untuk memberikan informasi dasar kepada Komandan dan seluruh Staf Komando dan Staf Umum Komando Darurat Bencana mengenai situasi bencana dan kebutuhan bantuan sumberdaya yang diperlukan dalam penanganan darurat bencana.
6. Informasi Bencana didistribusikan kepada Staf Komando dan Staf Umum Komando.
B. Penetapan Tujuan dan Sasaran
1. Dengan adanya analisis kejadian awal dan informasi mengenai kebutuhan bantuan, tahapan proses perencanaan selanjutnya adalah menetapkan Tujuan dan Sasaran yang akan dicapai dalam operasi.
2. Komandan Komando Darurat Bencana memberikan arahan mengenai tujuan dan sasaran umum operasi; menetapkan strategi umum, kebijakan, batasan anggaran dan hukum dalam mencapai tujuan dan sasaran operasi.
3. Tujuan dan Sasaran Operasi dalam garis besar meliputi tindakan-tindakan untuk:
a. Penyelamatan dan evakuasi korban bencana
b. Pemenuhan kebutuhan dasar korban bencana
c. Penyediaan dan distribusi personil, logistik dan peralatan
d. Perlindungan kelompok rentan
e. Pemulihan dengan segera fungsi sarana dan prasarana vital
4. Tujuan dan Sasaran operasi dapat diurai dalam bentuk yang lebih khusus dan spesifik, antara lain:
a. Pertolongan darurat untuk mengantisipasi meluasnya dampak bencana
b. Evakuasi korban
c. Penyediaan air bersih dan sanitasi
d. Penyediaan sandang dan pangan
e. Pelayanan kesehatan
f. Penyediaan hunian sementara korban', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7835, 'perka-24-2010', 19, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'g. Tindakan aksi untuk mengatasi sumber bencana, seperti:
1) Pemadaman kebakaran hutan dan lahan serta bencana asap termasuk tindakan mengisolasi sumber api/asap dan tindakan pengeboman air dari udara.
2) Penanggulangan bencana kekeringan dengan penyediaan sistem air bersih dan air minum serta kecukupan pangan.
3) Pencarian dan penyisiran lokasi akibat bom.
4) Pemasangan bronjong dan karung pasir untuk penahan tanah longsor/tanggul (bencana banjir).
h. Pemulihan darurat sarana dan prasarana supaya dapat berfungsi kembali, antara lain:
1) Jalan dan jembatan yang terputus 2) Menyingkirkan tanah longsor yang menutup jalan dan jembatan 3) Tanggul yang jebol 4) Sarana komunikasi 5) Penyelamatan lingkungan.
5. Setelah pembahasan, tujuan dan sasaran operasi dituliskan ke dalam formulir Tujuan Operasi (Formulir 2, Lampiran-08), dan kemudian didistribusikan kepada Kepala Bidang Perencanaan, Kepala Bidang Operasi, Kepala Humas dan Perwakilan Instansi/Lembaga agar semua pihak terkait mengetahui strategi yang digunakan untuk Rencana Operasi periode akan datang.
6. Kepala Bidang Operasi harus menyatakan bahwa Tujuan Operasi dipahami dan dapat dilaksanakan.
7. Tujuan dan Sasaran Operasi harus dibuat jelas dan terukur agar pada siklus operasi selanjutnya jajaran Komando dapat mengetahui tindakan operasi yang sudah berhasil dicapai dalam satu shif operasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7835, 'g. Tindakan aksi untuk mengatasi sumber bencana, seperti:
1) Pemadaman kebakaran hutan dan lahan serta bencana asap termasuk tindakan mengisolasi sumber api/asap dan tindakan pengeboman air dari udara.
2) Penanggulangan bencana kekeringan dengan penyediaan sistem air bersih dan air minum serta kecukupan pangan.
3) Pencarian dan penyisiran lokasi akibat bom.
4) Pemasangan bronjong dan karung pasir untuk penahan tanah longsor/tanggul (bencana banjir).
h. Pemulihan darurat sarana dan prasarana supaya dapat berfungsi kembali, antara lain:
1) Jalan dan jembatan yang terputus 2) Menyingkirkan tanah longsor yang menutup jalan dan jembatan 3) Tanggul yang jebol 4) Sarana komunikasi 5) Penyelamatan lingkungan.
5. Setelah pembahasan, tujuan dan sasaran operasi dituliskan ke dalam formulir Tujuan Operasi (Formulir 2, Lampiran-08), dan kemudian didistribusikan kepada Kepala Bidang Perencanaan, Kepala Bidang Operasi, Kepala Humas dan Perwakilan Instansi/Lembaga agar semua pihak terkait mengetahui strategi yang digunakan untuk Rencana Operasi periode akan datang.
6. Kepala Bidang Operasi harus menyatakan bahwa Tujuan Operasi dipahami dan dapat dilaksanakan.
7. Tujuan dan Sasaran Operasi harus dibuat jelas dan terukur agar pada siklus operasi selanjutnya jajaran Komando dapat mengetahui tindakan operasi yang sudah berhasil dicapai dalam satu shif operasi.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7836, 'perka-24-2010', 20, 'lampiran', 'Lampiran hal. 13', NULL, 13, '8. Tujuan dan Sasaran Operasi harus dapat dicapai dengan mempertimbangkan ketersediaan personil, logistik dan peralatan pada shif operasi tersebut.
9. Tujuan dan Sasaran Operasi harus cukup fleksibel dan memberikan ruang bagi Kepala Bidang Operasi untuk mencapai solusi operasi yang optimal.
C. Rapat Rencana Taktis
1. Rapat Rencana Taktis (Teknis) Operasi bertujuan untuk:
a. Menentukan strategi cara pencapaian tujuan dan sasaran operasi darurat bencana yang telah ditetapkan.
b. Mengalokasikan bantuan sumberdaya, baik personil, logistik dan peralatan sebagai tindakan taktis operasi darurat bencana.
c. Menyiapkan sistem monitoring operasi sebagai alat untuk mengoreksi atau menyesuaikan rencana taktis yang telah ditetapkan apabila perkembangan lapangan membutuhkan.
2. Komandan darurat bencana dapat menunjuk Kepala Bidang Perencanaan menyiapkan dan memimpin Rapat Taktis Operasi.
3. Informasi Awal bencana (Formulir 1a-1d, Lampiran 03-06) dibahas dalam Rapat Rencana Taktis oleh Komandan bersama-sama dengan Kepala Bidang Perencanaan, Kepala Bidang Operasi dan pejabat terkait.
4. Kepala Bidang Operasi memberikan usulan mengenai rencana pengerahan sumberdaya dalam rangka menunjang tujuan dan sasaran operasi yag telah ditetapkan oleh Komandan.
5. Kepala Bidang Operasi menentukan garis pengendalian lokasi bencana sesuai dengan kewenangannya dengan memperhatikan batasan geografis tertentu untuk operasi darurat pada hari berikutnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7836, '8. Tujuan dan Sasaran Operasi harus dapat dicapai dengan mempertimbangkan ketersediaan personil, logistik dan peralatan pada shif operasi tersebut.
9. Tujuan dan Sasaran Operasi harus cukup fleksibel dan memberikan ruang bagi Kepala Bidang Operasi untuk mencapai solusi operasi yang optimal.
C. Rapat Rencana Taktis
1. Rapat Rencana Taktis (Teknis) Operasi bertujuan untuk:
a. Menentukan strategi cara pencapaian tujuan dan sasaran operasi darurat bencana yang telah ditetapkan.
b. Mengalokasikan bantuan sumberdaya, baik personil, logistik dan peralatan sebagai tindakan taktis operasi darurat bencana.
c. Menyiapkan sistem monitoring operasi sebagai alat untuk mengoreksi atau menyesuaikan rencana taktis yang telah ditetapkan apabila perkembangan lapangan membutuhkan.
2. Komandan darurat bencana dapat menunjuk Kepala Bidang Perencanaan menyiapkan dan memimpin Rapat Taktis Operasi.
3. Informasi Awal bencana (Formulir 1a-1d, Lampiran 03-06) dibahas dalam Rapat Rencana Taktis oleh Komandan bersama-sama dengan Kepala Bidang Perencanaan, Kepala Bidang Operasi dan pejabat terkait.
4. Kepala Bidang Operasi memberikan usulan mengenai rencana pengerahan sumberdaya dalam rangka menunjang tujuan dan sasaran operasi yag telah ditetapkan oleh Komandan.
5. Kepala Bidang Operasi menentukan garis pengendalian lokasi bencana sesuai dengan kewenangannya dengan memperhatikan batasan geografis tertentu untuk operasi darurat pada hari berikutnya.', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7837, 'perka-24-2010', 21, 'lampiran', 'Lampiran hal. 14', NULL, 14, '6. Setelah Rapat Rencana Taktis, Kepala Bidang Operasi melengkapi formulir Rencana Kebutuhan bantuan sumberdaya (Formulir 9, Lampiran 21).
7. Formulir 9 (Rencana Kebutuhan) digunakan untuk mengkomunikasikan kebutuhan sumberdaya (a.l. personil, logistik dan peralatan) kepada seluruh jajaran organisasi terkait.
8. Formulir 9 digunakan oleh Bidang Logistik dan Peralatan Komando Darurat Bencana sebagai dasar permintaan dan pengadaan bantuan logistik dan peralatan.
D. Persiapan Rapat Rencana Operasi Persiapan Rapat Rencana Operasi dilakukan oleh Bidang Perencanaan dan bertujuan untuk:
1. Menentukan periode operasi
2. Menyiapkan peta-peta ukuran besar
3. Menyiapkan formulir-formulir (Formulir 1-10)
4. Memaparkan matriks rencana kebutuhan (Formulir 9)
5. Menyiapkan informasi mengenai status situasi bencana dan perkembangannya E. Rapat Rencana Operasi Rapat Rencana Operasi dipimpin oleh Kepala Bidang Perencanaan, yang meliputi aktifitas:
1. Pembahasan secara singkat status dan perkembangan bencana berdasarkan informasi dari:
a. TRC
b. Formulir Informasi Bencana (Formulir 1a-1d)
c. Pemantauan dari lapangan
d. Laporan lainnya
2. Kepala Bidang Operasi menetapkan alokasi bantuan sumberdaya kepada masing-masing BPBD/Satkorlak PB/Satlak PB atau tim/kelompok untuk menjalankan tugas sesuai dengan kebutuhannya.
3. Kepala Bidang Perencanaan mengidentifikasi sumberdaya yang dibutuhkan berdasarkan rencana kebutuhan yang dibuat oleh Kepala Bidang Operasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7837, '6. Setelah Rapat Rencana Taktis, Kepala Bidang Operasi melengkapi formulir Rencana Kebutuhan bantuan sumberdaya (Formulir 9, Lampiran 21).
7. Formulir 9 (Rencana Kebutuhan) digunakan untuk mengkomunikasikan kebutuhan sumberdaya (a.l. personil, logistik dan peralatan) kepada seluruh jajaran organisasi terkait.
8. Formulir 9 digunakan oleh Bidang Logistik dan Peralatan Komando Darurat Bencana sebagai dasar permintaan dan pengadaan bantuan logistik dan peralatan.
D. Persiapan Rapat Rencana Operasi Persiapan Rapat Rencana Operasi dilakukan oleh Bidang Perencanaan dan bertujuan untuk:
1. Menentukan periode operasi
2. Menyiapkan peta-peta ukuran besar
3. Menyiapkan formulir-formulir (Formulir 1-10)
4. Memaparkan matriks rencana kebutuhan (Formulir 9)
5. Menyiapkan informasi mengenai status situasi bencana dan perkembangannya E. Rapat Rencana Operasi Rapat Rencana Operasi dipimpin oleh Kepala Bidang Perencanaan, yang meliputi aktifitas:
1. Pembahasan secara singkat status dan perkembangan bencana berdasarkan informasi dari:
a. TRC
b. Formulir Informasi Bencana (Formulir 1a-1d)
c. Pemantauan dari lapangan
d. Laporan lainnya
2. Kepala Bidang Operasi menetapkan alokasi bantuan sumberdaya kepada masing-masing BPBD/Satkorlak PB/Satlak PB atau tim/kelompok untuk menjalankan tugas sesuai dengan kebutuhannya.
3. Kepala Bidang Perencanaan mengidentifikasi sumberdaya yang dibutuhkan berdasarkan rencana kebutuhan yang dibuat oleh Kepala Bidang Operasi.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7838, 'perka-24-2010', 22, 'lampiran', 'Lampiran hal. 15', NULL, 15, 'Dengan menggunakan formulir rencana kebutuhan (Formulir 9), ditentukan berapa jumlah sumberdaya yang dibutuhkan untuk periode operasi hari berikutnya yang sudah tersedia di lokasi bencana atau sedang dalam perjalanan. Apabila sumberdaya yang dibutuhkan (kebutuhan) melampaui sumberdaya yang tersedia maka harus dilakukan permintaan/pengadaan (kekurangan) bantuan sumberdaya.
4. Kepala Bidang Perencanaan memastikan, bahwa Rencana Operasi Udara (Formulir 10) telah disiapkan oleh Kepala Bidang Operasi.
Rencana Operasi Udara memuat penugasan bantuan sumberdaya melalui udara dengan menyebutkan jenis dan jumlah pesawat yang dialokasikan serta tujuan/lokasi bantuan dan penerima bantuan.
5. Kepala Bidang Operasi bersama-sama dengan Kepala Kepala Bidang Perencanaan dan Bidang Logistik menetapkan fasilitas-fasilitas di lokasi bencana yang diperlukan untuk melaksanakan penanganan bantuan, seperti di staging area dan shelter.
6. Mentukan dukungan-dukungan lainnya, seperti: Jaring Komunikasi yang diperlukan untuk mengkoordinasikan operasi (Formulir 5), dukungan Rencana Medis (Formulir 6), dan dukungan Keselamatan serta Transportasi petugas operasi penanganan bencana.
7. Melengkapi Rencana Operasi yang memuat penetapan rencana tindakan operasi, yang terdiri dari:
a. Penetapan tujuan dan sasaran operasi
b. Penetapan struktur dan susunan pejabat organisasi Komando
c. Penugasan
d. Peta Lokasi Bencana
e. Penetapan alokasi jaring komunikasi
f. Rencana dukungan medis');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7838, 'Dengan menggunakan formulir rencana kebutuhan (Formulir 9), ditentukan berapa jumlah sumberdaya yang dibutuhkan untuk periode operasi hari berikutnya yang sudah tersedia di lokasi bencana atau sedang dalam perjalanan. Apabila sumberdaya yang dibutuhkan (kebutuhan) melampaui sumberdaya yang tersedia maka harus dilakukan permintaan/pengadaan (kekurangan) bantuan sumberdaya.
4. Kepala Bidang Perencanaan memastikan, bahwa Rencana Operasi Udara (Formulir 10) telah disiapkan oleh Kepala Bidang Operasi.
Rencana Operasi Udara memuat penugasan bantuan sumberdaya melalui udara dengan menyebutkan jenis dan jumlah pesawat yang dialokasikan serta tujuan/lokasi bantuan dan penerima bantuan.
5. Kepala Bidang Operasi bersama-sama dengan Kepala Kepala Bidang Perencanaan dan Bidang Logistik menetapkan fasilitas-fasilitas di lokasi bencana yang diperlukan untuk melaksanakan penanganan bantuan, seperti di staging area dan shelter.
6. Mentukan dukungan-dukungan lainnya, seperti: Jaring Komunikasi yang diperlukan untuk mengkoordinasikan operasi (Formulir 5), dukungan Rencana Medis (Formulir 6), dan dukungan Keselamatan serta Transportasi petugas operasi penanganan bencana.
7. Melengkapi Rencana Operasi yang memuat penetapan rencana tindakan operasi, yang terdiri dari:
a. Penetapan tujuan dan sasaran operasi
b. Penetapan struktur dan susunan pejabat organisasi Komando
c. Penugasan
d. Peta Lokasi Bencana
e. Penetapan alokasi jaring komunikasi
f. Rencana dukungan medis', 'Lampiran hal. 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7839, 'perka-24-2010', 23, 'lampiran', 'Lampiran hal. 16', NULL, 16, 'g. Rencana Transportasi/Operasi Udara
8. Kepala Bidang Perencanaan menentukan kebutuhan jenis formulir pendukung untuk setiap Rencana Operasi/Tindakan Operasi.
F. Penetapan Rencana Operasi
1. Kepala Bidang Perencanaan bertanggung jawab untuk memeriksa, bahwa Rencana Operasi sudah lengkap dan akurat :
a. Melengkapi lampiran rencana operasi (formulir-formulir pendukung) dan memastikan bahwa setiap formulir sudah disetujui oleh pejabat terkait.
b. Memastikan bahwa Rencana Operasi telah disetujui oleh Komandan.
c. Rencana Operasi dituangkan dalam bentuk Form 8 beserta semua dokumen pendukung sebagai lampiran.
2. Formulir 8 mengenai Rencana Operasi Tanggap Darurat terdapat pada Lampiran-18 s/d 20.
G. Rapat Penjelasan Rencana Operasi Rapat penjelasan rencana operasi terdiri dari aktifitas sebagai berikut:
1. Dokumen Rencana Operasi dibagikan kepada seluruh personil terkait.
2. Penjelasan operasi darurat bencana dilakukan oleh Kepala Bidang Perencanaan.
3. Penjelasan status darurat bencana dilakukan dengan berorientasi pada peta bencana.
4. Menyampaikan laporan terakhir dari ramalan cuaca.
5. Melengkapi data-data yang kurang.
6. Tanya-Jawab.
H. Pelaksanaan dan Pengakhiran
1. Dokumen Rencana Operasi yang telah ditetapkan, yang berlaku untuk periode operasi tertentu, didistribusikan kepada seluruh Kepala Seksi di jajaran Bidang Operasi Komando Darurat Bencana untuk dilaksanakan di lapangan.
2. Pelaksanaan Rencana Operasi dipimpin oleh Kepala Bidang Operasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7839, 'g. Rencana Transportasi/Operasi Udara
8. Kepala Bidang Perencanaan menentukan kebutuhan jenis formulir pendukung untuk setiap Rencana Operasi/Tindakan Operasi.
F. Penetapan Rencana Operasi
1. Kepala Bidang Perencanaan bertanggung jawab untuk memeriksa, bahwa Rencana Operasi sudah lengkap dan akurat :
a. Melengkapi lampiran rencana operasi (formulir-formulir pendukung) dan memastikan bahwa setiap formulir sudah disetujui oleh pejabat terkait.
b. Memastikan bahwa Rencana Operasi telah disetujui oleh Komandan.
c. Rencana Operasi dituangkan dalam bentuk Form 8 beserta semua dokumen pendukung sebagai lampiran.
2. Formulir 8 mengenai Rencana Operasi Tanggap Darurat terdapat pada Lampiran-18 s/d 20.
G. Rapat Penjelasan Rencana Operasi Rapat penjelasan rencana operasi terdiri dari aktifitas sebagai berikut:
1. Dokumen Rencana Operasi dibagikan kepada seluruh personil terkait.
2. Penjelasan operasi darurat bencana dilakukan oleh Kepala Bidang Perencanaan.
3. Penjelasan status darurat bencana dilakukan dengan berorientasi pada peta bencana.
4. Menyampaikan laporan terakhir dari ramalan cuaca.
5. Melengkapi data-data yang kurang.
6. Tanya-Jawab.
H. Pelaksanaan dan Pengakhiran
1. Dokumen Rencana Operasi yang telah ditetapkan, yang berlaku untuk periode operasi tertentu, didistribusikan kepada seluruh Kepala Seksi di jajaran Bidang Operasi Komando Darurat Bencana untuk dilaksanakan di lapangan.
2. Pelaksanaan Rencana Operasi dipimpin oleh Kepala Bidang Operasi.', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7840, 'perka-24-2010', 24, 'lampiran', 'Lampiran hal. 17', NULL, 17, '3. Pelaksanaan Rencana Operasi harus dimonitor dan dievaluasi pada setiap tahapan pengembangan dan implementasinya.
4. Kepala Bidang Operasi dapat melakukan koreksi dan penyesuaian terhadap pelaksanaan Rencana Operasi sesuai dengan perkembangan yang terjadi di lapangan.
5. Seluruh Kepala Bidang Komando Darurat Bencana harus memantau perkembangan operasi darurat bencana di lapangan.
6. Sebagai masukan untuk penetapan Tujuan dan Sasaran Operasi untuk periode operasi selanjutnya, semua Kepala Bidang memberikan rekomendasi kepada Komandan Darurat Bencana berdasarkan informasi dan umpan balik dari lapangan.
BAB III PROSEDUR PENYUSUNAN RENCANA OPERASI DARURAT BENCANA Penyusunan Rencanan Operasi dilaksanakan dengan menggunakan prosedur penyusunan rencana operasi darurat bencana, sebagai berikut:
A. Ketentuan Penyusunan Rencana Operasi Darurat Bencana disusun berdasarkan masukan yang dituangkan ke dalam formulir-formulir Sistem Komando Darurat Bencana (Formulir 1-10) dengan menggunakan Format seperti pada Lampiran 3 sampai dengan Lampiran 24, dengan ketentuan sebagai berikut:
1. Melengkapi Formulir Tujuan Operasi (Formulir 2, Lampiran 08) termasuk lampiran yang disesuaikan dengan kebutuhan, yaitu:
a. Formulir Informasi Bencana (Formulir 1a-1d, Lampiran 03 s/d 06)
b. Formulir Susunan Organisasi Komando (Formulir 3, Lampiran 10)
c. Bagan Organisasi Komando (Formulir 7, Lampiran-17)
d. Formulir Susunan Penugasan (Formulir 4, Lampiran-12)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7840, '3. Pelaksanaan Rencana Operasi harus dimonitor dan dievaluasi pada setiap tahapan pengembangan dan implementasinya.
4. Kepala Bidang Operasi dapat melakukan koreksi dan penyesuaian terhadap pelaksanaan Rencana Operasi sesuai dengan perkembangan yang terjadi di lapangan.
5. Seluruh Kepala Bidang Komando Darurat Bencana harus memantau perkembangan operasi darurat bencana di lapangan.
6. Sebagai masukan untuk penetapan Tujuan dan Sasaran Operasi untuk periode operasi selanjutnya, semua Kepala Bidang memberikan rekomendasi kepada Komandan Darurat Bencana berdasarkan informasi dan umpan balik dari lapangan.
BAB III PROSEDUR PENYUSUNAN RENCANA OPERASI DARURAT BENCANA Penyusunan Rencanan Operasi dilaksanakan dengan menggunakan prosedur penyusunan rencana operasi darurat bencana, sebagai berikut:
A. Ketentuan Penyusunan Rencana Operasi Darurat Bencana disusun berdasarkan masukan yang dituangkan ke dalam formulir-formulir Sistem Komando Darurat Bencana (Formulir 1-10) dengan menggunakan Format seperti pada Lampiran 3 sampai dengan Lampiran 24, dengan ketentuan sebagai berikut:
1. Melengkapi Formulir Tujuan Operasi (Formulir 2, Lampiran 08) termasuk lampiran yang disesuaikan dengan kebutuhan, yaitu:
a. Formulir Informasi Bencana (Formulir 1a-1d, Lampiran 03 s/d 06)
b. Formulir Susunan Organisasi Komando (Formulir 3, Lampiran 10)
c. Bagan Organisasi Komando (Formulir 7, Lampiran-17)
d. Formulir Susunan Penugasan (Formulir 4, Lampiran-12)', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7841, 'perka-24-2010', 25, 'lampiran', 'Lampiran hal. 18', NULL, 18, 'e. Formulir Jaring Komunikasi (Formulir 5, Lampiran-14)
f. Formulir Rencana Medis (Formulir 6, Lampiran-16)
g. Dan formulir lain sesuai dengan kebutuhan.
2. Melengkapi Formulir Rencana Kebutuhan Operasi (Formulir 9).
B. Rencana Operasi Rencana Operasi dapat dibuat dalam bentuk deskriptif atau dalam bentuk susunan formulir Tujuan Operasi yang dilengkapi dengan formulir-formulir pendukung.
1. Dalam bentuk Deskriptif
a. Rencana Operasi secara lengkap dapat dibuat dalam bentuk deskriptif (narasi) tertulis dengan menggunakan Formulir 8 (Rencana Operasi, Lampiran-18 s/d 20), dengan susunan yang terdiri dari penunjukan, daerah waktu, situasi, tugas pokok, pelaksanaan, administrasi dan logistik, komando dan pengendalian.
b. BNPB, BPBD/Satkorlak PB Provinsi, BPBD/Satlak PB Kabupaten/Kota menggunakan bentuk deskriptif untuk menuangkan Rencana Operasi penanganan darurat bencana.
c. Komando Darurat Bencana dapat membuat Rencana Operasi dalam bentuk deskriptif.
2. Dalam bentuk Susunan Formulir
a. Rencana Operasi Komando Darurat Bencana, secara lengkap dapat dibuat dalam bentuk kumpulan isian formulir seperti ketentuan penyusunan pada Ketentuan Khusus di atas.
b. Secara umum Rencana Operasi menggunakan isian Formulir Tujuan Operasi (Formulir 2), yang dilengkapi dengan lampiran yang dibutuhkan.
c. Rencana Operasi dalam bentuk formulir ini menjadi dokumen dasar untuk koordinasi dan komunikasi bagi semua organisasi terkait dalam pelaksanaan operasi penanganan darurat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7841, 'e. Formulir Jaring Komunikasi (Formulir 5, Lampiran-14)
f. Formulir Rencana Medis (Formulir 6, Lampiran-16)
g. Dan formulir lain sesuai dengan kebutuhan.
2. Melengkapi Formulir Rencana Kebutuhan Operasi (Formulir 9).
B. Rencana Operasi Rencana Operasi dapat dibuat dalam bentuk deskriptif atau dalam bentuk susunan formulir Tujuan Operasi yang dilengkapi dengan formulir-formulir pendukung.
1. Dalam bentuk Deskriptif
a. Rencana Operasi secara lengkap dapat dibuat dalam bentuk deskriptif (narasi) tertulis dengan menggunakan Formulir 8 (Rencana Operasi, Lampiran-18 s/d 20), dengan susunan yang terdiri dari penunjukan, daerah waktu, situasi, tugas pokok, pelaksanaan, administrasi dan logistik, komando dan pengendalian.
b. BNPB, BPBD/Satkorlak PB Provinsi, BPBD/Satlak PB Kabupaten/Kota menggunakan bentuk deskriptif untuk menuangkan Rencana Operasi penanganan darurat bencana.
c. Komando Darurat Bencana dapat membuat Rencana Operasi dalam bentuk deskriptif.
2. Dalam bentuk Susunan Formulir
a. Rencana Operasi Komando Darurat Bencana, secara lengkap dapat dibuat dalam bentuk kumpulan isian formulir seperti ketentuan penyusunan pada Ketentuan Khusus di atas.
b. Secara umum Rencana Operasi menggunakan isian Formulir Tujuan Operasi (Formulir 2), yang dilengkapi dengan lampiran yang dibutuhkan.
c. Rencana Operasi dalam bentuk formulir ini menjadi dokumen dasar untuk koordinasi dan komunikasi bagi semua organisasi terkait dalam pelaksanaan operasi penanganan darurat.', 'Lampiran hal. 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7842, 'perka-24-2010', 26, 'lampiran', 'Lampiran hal. 20', NULL, 20, 'BAB IV TINGKATAN RENCANA OPERASI DARURAT BENCANA Rencana Operasi Darurat Bencana disusun sesuai dengan dampak dan tingkatan bencana yang dinyatakan oleh Pemerintah atau pemerintah daerah.
Baik tahapan dalam proses penyusunan maupun rencana operasi di tingkatan penanganan darurat bencana tersebut, pada dasarnya memiliki kesamaan, sehingga pedoman penyusunan rencana operasi darurat bencana ini berlaku untuk semua tingkatan bencana.
A. Tingkat Pusat
1. Apabila dampak dan eskalasi bencana bersifat nasional, maka rencana operasi darurat bencana disusun oleh Komandan Darurat Bencana Tingkat Nasional yang ditunjuk oleh Presiden sesuai dengan tingkat dan kewenangannya.
2. Perencanaan Operasi bantuan BNPB kepada BPBD, baik yang diminta atau atas inisiatif BNPB pada saat siaga darurat, tanggap darurat dan transisi darurat ke pemulihan menggunakan Pedoman ini.
3. Rencana Operasi bantuan dari Luar Negeri pada saat siaga darurat, tanggap darurat dan transisi darurat ke pemulihan mengacu kepada Pedoman ini.
4. Rencana Operasi bantuan ke Luar Negeri mengacu kepada peraturan internasional dan regional yang berlaku.
B. Tingkat Provinsi/Kabupaten/Kota Berdasarkan dampak bencana dan tingkatan bencana maka:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7842, 'BAB IV TINGKATAN RENCANA OPERASI DARURAT BENCANA Rencana Operasi Darurat Bencana disusun sesuai dengan dampak dan tingkatan bencana yang dinyatakan oleh Pemerintah atau pemerintah daerah.
Baik tahapan dalam proses penyusunan maupun rencana operasi di tingkatan penanganan darurat bencana tersebut, pada dasarnya memiliki kesamaan, sehingga pedoman penyusunan rencana operasi darurat bencana ini berlaku untuk semua tingkatan bencana.
A. Tingkat Pusat
1. Apabila dampak dan eskalasi bencana bersifat nasional, maka rencana operasi darurat bencana disusun oleh Komandan Darurat Bencana Tingkat Nasional yang ditunjuk oleh Presiden sesuai dengan tingkat dan kewenangannya.
2. Perencanaan Operasi bantuan BNPB kepada BPBD, baik yang diminta atau atas inisiatif BNPB pada saat siaga darurat, tanggap darurat dan transisi darurat ke pemulihan menggunakan Pedoman ini.
3. Rencana Operasi bantuan dari Luar Negeri pada saat siaga darurat, tanggap darurat dan transisi darurat ke pemulihan mengacu kepada Pedoman ini.
4. Rencana Operasi bantuan ke Luar Negeri mengacu kepada peraturan internasional dan regional yang berlaku.
B. Tingkat Provinsi/Kabupaten/Kota Berdasarkan dampak bencana dan tingkatan bencana maka:', 'Lampiran hal. 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7843, 'perka-24-2010', 27, 'lampiran', 'Lampiran hal. 20', NULL, 20, '1. Pada saat keadaan darurat bencana, sesuai dengan tingkatan bencana, BPBD Provinsi/Kabupaten/Kota berdasarkan peraturan yang berlaku, membentuk Komando Darurat Bencana yang bertugas untuk melaksanakan penanganan darurat bencana, yaitu pada status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan dan menyusun Rencana Operasi sesuai dengan Pedoman ini.
2. Bagi pemerintah daerah yang tidak memiliki BPBD maka Rencana Operasi disusun oleh perangkat daerah yang sesuai dengan tugas pokok dan fungsi penanggulangan bencana.
3. Agar penanganan darurat bencana dapat dilaksanakan sesuai dengan sasaran yang ditetapkan secara efektif, Komando Darurat Bencana menyusun Rencana Operasi berdasarkan Pedoman ini.
BAB V ORGANISASI DAN TATA KERJA KOMANDO DARURAT BENCANA Pada saat terjadi darurat bencana, Komando Darurat Bencana adalah organisasi yang bertugas untuk perencanaan, pelaksanaan dan pengendalian operasi penanganan darurat bencana dengan mengaktifkan pusat pengendalian operasi. Perencanaan Operasi yang ditetapkan melalui proses penyusunan perencanaan seperti diuraikan pada Bab-Bab sebelumnya merupakan bagian dari tugas pokok Komando.
Contoh Tujuan Operasi dan Pelaksanaan Operasi Darurat Bencana ada pada Lampiran-25 Berikut ini diuraikan Organisasi, Tugas Pokok dan Fungsi serta Tanggung Jawab Komando Darurat Bencana dan Komandan serta stafnya.
A. Organisasi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7843, '1. Pada saat keadaan darurat bencana, sesuai dengan tingkatan bencana, BPBD Provinsi/Kabupaten/Kota berdasarkan peraturan yang berlaku, membentuk Komando Darurat Bencana yang bertugas untuk melaksanakan penanganan darurat bencana, yaitu pada status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan dan menyusun Rencana Operasi sesuai dengan Pedoman ini.
2. Bagi pemerintah daerah yang tidak memiliki BPBD maka Rencana Operasi disusun oleh perangkat daerah yang sesuai dengan tugas pokok dan fungsi penanggulangan bencana.
3. Agar penanganan darurat bencana dapat dilaksanakan sesuai dengan sasaran yang ditetapkan secara efektif, Komando Darurat Bencana menyusun Rencana Operasi berdasarkan Pedoman ini.
BAB V ORGANISASI DAN TATA KERJA KOMANDO DARURAT BENCANA Pada saat terjadi darurat bencana, Komando Darurat Bencana adalah organisasi yang bertugas untuk perencanaan, pelaksanaan dan pengendalian operasi penanganan darurat bencana dengan mengaktifkan pusat pengendalian operasi. Perencanaan Operasi yang ditetapkan melalui proses penyusunan perencanaan seperti diuraikan pada Bab-Bab sebelumnya merupakan bagian dari tugas pokok Komando.
Contoh Tujuan Operasi dan Pelaksanaan Operasi Darurat Bencana ada pada Lampiran-25 Berikut ini diuraikan Organisasi, Tugas Pokok dan Fungsi serta Tanggung Jawab Komando Darurat Bencana dan Komandan serta stafnya.
A. Organisasi', 'Lampiran hal. 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7844, 'perka-24-2010', 28, 'lampiran', 'Lampiran hal. 22', NULL, 22, '1. Organisasi Komando Darurat Bencana merupakan organisasi satu komando, dengan mata rantai dan garis komando serta tanggung jawab yang jelas. Instansi/Lembaga dapat dikoordinasikan dalam satu organisasi berdasarkan satu kesatuan komando. Organisasi ini dapat dibentuk di semua tingkatan wilayah bencana baik di tingkat Kabupaten/Kota, Provinsi maupun tingkat Nasional.
2. Struktur organisasi komando darurat bencana terdiri dari Komandan yang dibantu oleh Staf Komando dan Staf Umum, yang secara lengkap terdiri dari:
a. Komandan Darurat Bencana
b. Wakil Komandan Darurat Bencana
c. Staf Komando:
1) Sekretariat 2) Hubungan Masyarakat dan mas media 3) Keselamatan dan Keamanan 4) Perwakilan Instansi/Lembaga
d. Staf Umum:
1) Bidang Perencanaan 2) Bidang Operasi 3) Bidang Logistik dan Peralatan 4) Bidang Administrasi Keuangan
3. Struktur organisasi ini merupakan organisasi standar dan dapat diperluas berdasarkan kebutuhan.
4. Sesuai dengan jenis, kebutuhan dan kompleksitas bencana dapat dibentuk unit organisasi dalam bentuk seksi-seksi yang berada di bawah Bidang dan dipimpin oleh Kepala Seksi yang bertanggung jawab kepada Kepala Bidang.
B. Tugas Pokok dan Fungsi Organisasi
1. Komando Darurat Bencana memiliki tugas pokok untuk:
a. Merencanakan operasi penanganan darurat bencana.
b. Melakukan tindakan aksi yang dimaksudkan untuk mengatasi atau mengurangi sumber bencana.
c. Mengajukan permintaan kebutuhan bantuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7844, '1. Organisasi Komando Darurat Bencana merupakan organisasi satu komando, dengan mata rantai dan garis komando serta tanggung jawab yang jelas. Instansi/Lembaga dapat dikoordinasikan dalam satu organisasi berdasarkan satu kesatuan komando. Organisasi ini dapat dibentuk di semua tingkatan wilayah bencana baik di tingkat Kabupaten/Kota, Provinsi maupun tingkat Nasional.
2. Struktur organisasi komando darurat bencana terdiri dari Komandan yang dibantu oleh Staf Komando dan Staf Umum, yang secara lengkap terdiri dari:
a. Komandan Darurat Bencana
b. Wakil Komandan Darurat Bencana
c. Staf Komando:
1) Sekretariat 2) Hubungan Masyarakat dan mas media 3) Keselamatan dan Keamanan 4) Perwakilan Instansi/Lembaga
d. Staf Umum:
1) Bidang Perencanaan 2) Bidang Operasi 3) Bidang Logistik dan Peralatan 4) Bidang Administrasi Keuangan
3. Struktur organisasi ini merupakan organisasi standar dan dapat diperluas berdasarkan kebutuhan.
4. Sesuai dengan jenis, kebutuhan dan kompleksitas bencana dapat dibentuk unit organisasi dalam bentuk seksi-seksi yang berada di bawah Bidang dan dipimpin oleh Kepala Seksi yang bertanggung jawab kepada Kepala Bidang.
B. Tugas Pokok dan Fungsi Organisasi
1. Komando Darurat Bencana memiliki tugas pokok untuk:
a. Merencanakan operasi penanganan darurat bencana.
b. Melakukan tindakan aksi yang dimaksudkan untuk mengatasi atau mengurangi sumber bencana.
c. Mengajukan permintaan kebutuhan bantuan.', 'Lampiran hal. 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7845, 'perka-24-2010', 29, 'lampiran', 'Lampiran hal. 23', NULL, 23, 'd. Melaksanakan dan mengkoordinasikan pengerahan sumberdaya untuk penanganan tanggap darurat bencana secara cepat tepat, efisien dan efektif.
e. Menyebarluaskan informasi mengenai bencana dan pananganan bencana kepada media masa dan masyarakat luas.
2. Fungsi Komando Darurat Bencana adalah mengkoordinasikan, mengintegrasikan dan mensinkronisasikan seluruh unsur dalam organisasi Komando Darurat Bencana untuk penanganan darurat bencana.
C. Tugas dan Tanggung Jawab Unit Organisasi
1. Komandan Darurat Bencana
a. Komandan Darurat Bencana adalah personil yang ditunjuk oleh Presiden/Kepala Daerah sesuai dengan tingkat dan kewenangannya.
b. Komandan bertugas:
1) Mengaktifkan dan meningkatkan Pusat Pengendalian Operasi (Pusdalops) menjadi Pos Komando Darurat Bencana BPBD Kabupaten/Kota/Provinsi atau BNPB, sesuai dengan jenis, lokasi dan tingkatan bencana.
2) Membentuk Pos Komando Lapangan (Poskolap) di lokasi bencana di bawah komando Pos Komando Darurat Bencana BPBD Kabupaten/Kota/Provinsi atau BNPB.
3) Membuat rencana strategis dan taktis (teknis), mengorganisasikan, melaksanakan dan mengendalikan operasi darurat bencana.
4) Melaksanakan komando dan pengendalian untuk pengerahan sumber daya manusia, peralatan, logistik dan penyelamatan serta berwenang memerintahkan para pejabat yang mewakili Instansi/Lembaga/Organisasi yang terkait dalam memfasilitasi aksesibilitas penanganan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7845, 'd. Melaksanakan dan mengkoordinasikan pengerahan sumberdaya untuk penanganan tanggap darurat bencana secara cepat tepat, efisien dan efektif.
e. Menyebarluaskan informasi mengenai bencana dan pananganan bencana kepada media masa dan masyarakat luas.
2. Fungsi Komando Darurat Bencana adalah mengkoordinasikan, mengintegrasikan dan mensinkronisasikan seluruh unsur dalam organisasi Komando Darurat Bencana untuk penanganan darurat bencana.
C. Tugas dan Tanggung Jawab Unit Organisasi
1. Komandan Darurat Bencana
a. Komandan Darurat Bencana adalah personil yang ditunjuk oleh Presiden/Kepala Daerah sesuai dengan tingkat dan kewenangannya.
b. Komandan bertugas:
1) Mengaktifkan dan meningkatkan Pusat Pengendalian Operasi (Pusdalops) menjadi Pos Komando Darurat Bencana BPBD Kabupaten/Kota/Provinsi atau BNPB, sesuai dengan jenis, lokasi dan tingkatan bencana.
2) Membentuk Pos Komando Lapangan (Poskolap) di lokasi bencana di bawah komando Pos Komando Darurat Bencana BPBD Kabupaten/Kota/Provinsi atau BNPB.
3) Membuat rencana strategis dan taktis (teknis), mengorganisasikan, melaksanakan dan mengendalikan operasi darurat bencana.
4) Melaksanakan komando dan pengendalian untuk pengerahan sumber daya manusia, peralatan, logistik dan penyelamatan serta berwenang memerintahkan para pejabat yang mewakili Instansi/Lembaga/Organisasi yang terkait dalam memfasilitasi aksesibilitas penanganan darurat bencana.', 'Lampiran hal. 23', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7846, 'perka-24-2010', 30, 'lampiran', 'Lampiran hal. 24', NULL, 24, 'c. Komandan Darurat Bencana bertanggung jawab langsung kepada Presiden/Kepala Daerah, sesuai dengan tingkat dan kewenangannya.
2. Wakil Komandan Darurat Bencana Wakil Komandan Darurat Bencana adalah personil yang ditunjuk oleh Presiden/Kepala Daerah sesuai dengan tingkat dan kewenangannya.
a. Wakil Komandan Darurat Bencana bertugas:
1) Membantu Komandan Darurat Bencana dalam merencanakan, mengorganisasikan, melaksanakan dan mengendalikan Komando Darurat Bencana.
2) Mengkoordinir tugas-tugas Sekretariat, Humas, Keselamatan dan Keamanan serta Perwakilan Instansi/Lembaga.
3) Mewakili Komandan Darurat Bencana, apabila Komandan Darurat Bencana berhalangan.
b. Wakil Komandan Darurat Bencana bertanggung jawab langsung kepada Komandan Darurat Bencana.
3. Staf Komando
a. Sekretariat 1) Sekretariat dipimpin oleh seorang Sekretaris.
2) Sekretaris bertugas dan bertanggung jawab untuk: a) Menyelenggarakan administrasi umum dan pelaporan b) Pelayanan akomodasi dan konsumsi bagi personil komando darurat bencana c) Pengaturan pergantian shif personil 3) Sekretaris bertanggung jawab langsung kepada Komandan Darurat Bencana.
b. Hubungan Masyarakat 1) Kepala Hubungan Masyarakat bertugas dan bertanggung jawab untuk: a) Menghimpun data dan informasi penanganan bencana yang terjadi. b) Membentuk jaringan informasi dan komunikasi serta menyebarkan informasi tentang bencana tersebut ke media masa dan masyarakat luas.
2) Kepala Humas bertanggung jawab langsung kepada Komandan Darurat Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7846, 'c. Komandan Darurat Bencana bertanggung jawab langsung kepada Presiden/Kepala Daerah, sesuai dengan tingkat dan kewenangannya.
2. Wakil Komandan Darurat Bencana Wakil Komandan Darurat Bencana adalah personil yang ditunjuk oleh Presiden/Kepala Daerah sesuai dengan tingkat dan kewenangannya.
a. Wakil Komandan Darurat Bencana bertugas:
1) Membantu Komandan Darurat Bencana dalam merencanakan, mengorganisasikan, melaksanakan dan mengendalikan Komando Darurat Bencana.
2) Mengkoordinir tugas-tugas Sekretariat, Humas, Keselamatan dan Keamanan serta Perwakilan Instansi/Lembaga.
3) Mewakili Komandan Darurat Bencana, apabila Komandan Darurat Bencana berhalangan.
b. Wakil Komandan Darurat Bencana bertanggung jawab langsung kepada Komandan Darurat Bencana.
3. Staf Komando
a. Sekretariat 1) Sekretariat dipimpin oleh seorang Sekretaris.
2) Sekretaris bertugas dan bertanggung jawab untuk: a) Menyelenggarakan administrasi umum dan pelaporan b) Pelayanan akomodasi dan konsumsi bagi personil komando darurat bencana c) Pengaturan pergantian shif personil 3) Sekretaris bertanggung jawab langsung kepada Komandan Darurat Bencana.
b. Hubungan Masyarakat 1) Kepala Hubungan Masyarakat bertugas dan bertanggung jawab untuk: a) Menghimpun data dan informasi penanganan bencana yang terjadi. b) Membentuk jaringan informasi dan komunikasi serta menyebarkan informasi tentang bencana tersebut ke media masa dan masyarakat luas.
2) Kepala Humas bertanggung jawab langsung kepada Komandan Darurat Bencana.', 'Lampiran hal. 24', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7847, 'perka-24-2010', 31, 'lampiran', 'Lampiran hal. 25', NULL, 25, 'c. Keselamatan dan Keamanan 1) Kepala Keselamatan dan Keamanan bertugas dan bertanggung jawab untuk: a) Menjamin kesehatan dan keselamatan seluruh personil komando darurat bencana dalam menjalankan tugasnya. b) Menjaga keamanan penanganan darurat bencana serta mengantisipasi hal-hal di luar dugaan atau suatu keadaan yang berbahaya.
2) Kepala Keselamatan dan Kamanan bertanggung jawab langsung kepada Komandan Darurat Bencana.
d. Perwakilan Instansi/Lembaga 1) Perwakilan Instansi/Lembaga bertugas untuk membantu Komandan Darurat Bencana berkaitan dengan permintaan dan pengerahan sumberdaya yang dibutuhkan dari Instansi/Lembaga.
2) Perwakilan Instansi/Lembaga secara operasional bertanggung jawab langsung kepada Komandan atas pelaksanaan tugasnya dan secara administratif bertanggung jawab kepada pimpinan Instansi/Lembaga terkait.
4. Staf Umum
a. Bidang Operasi 1) Kepala Bidang Operasi bertugas dan bertanggung jawab atas semua pelaksanaan operasi penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, penyelamatan, pemulihan sarana dan prasarana serta tindakan aksi untuk mengatasi dan mengurangi sumber bencana dengan cepat, tepat, efisien dan efektif berdasarkan satu kesatuan rencana tindakan penanganan darurat bencana.
2) Kepala Bidang Operasi bertanggung jawab langsung kepada Komandan Darurat Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7847, 'c. Keselamatan dan Keamanan 1) Kepala Keselamatan dan Keamanan bertugas dan bertanggung jawab untuk: a) Menjamin kesehatan dan keselamatan seluruh personil komando darurat bencana dalam menjalankan tugasnya. b) Menjaga keamanan penanganan darurat bencana serta mengantisipasi hal-hal di luar dugaan atau suatu keadaan yang berbahaya.
2) Kepala Keselamatan dan Kamanan bertanggung jawab langsung kepada Komandan Darurat Bencana.
d. Perwakilan Instansi/Lembaga 1) Perwakilan Instansi/Lembaga bertugas untuk membantu Komandan Darurat Bencana berkaitan dengan permintaan dan pengerahan sumberdaya yang dibutuhkan dari Instansi/Lembaga.
2) Perwakilan Instansi/Lembaga secara operasional bertanggung jawab langsung kepada Komandan atas pelaksanaan tugasnya dan secara administratif bertanggung jawab kepada pimpinan Instansi/Lembaga terkait.
4. Staf Umum
a. Bidang Operasi 1) Kepala Bidang Operasi bertugas dan bertanggung jawab atas semua pelaksanaan operasi penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, penyelamatan, pemulihan sarana dan prasarana serta tindakan aksi untuk mengatasi dan mengurangi sumber bencana dengan cepat, tepat, efisien dan efektif berdasarkan satu kesatuan rencana tindakan penanganan darurat bencana.
2) Kepala Bidang Operasi bertanggung jawab langsung kepada Komandan Darurat Bencana.', 'Lampiran hal. 25', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7848, 'perka-24-2010', 32, 'lampiran', 'Lampiran hal. 26', NULL, 26, 'b. Bidang Perencanaan 1) Kepala Bidang Perencanaan bertugas dan bertanggung jawab atas pengumpulan, evaluasi dan analisis data dan informasi yang berhubungan dengan rencana operasi penanganan darurat bencana dan menyiapkan dokumen rencana tindakan operasi darurat.
2) Kepala Bidang Perencanaan bertanggung jawab langsung kepada Komandan Darurat Bencana.
c. Bidang Logistik dan Peralatan 1) Kepala Bidang Logistik dan Peralatan bertugas dan bertanggung jawab: a) Penyediaan fasilitas, jasa, dan bahan-bahan serta perlengkapan darurat bencana. b) Melaksanakan penerimaan, penyimpanan, pendistribusian dan transportasi bantuan logistik dan peralatan. c) Melaksanakan penyelenggaraan dukungan dapur umum, air bersih dan sanitasi umum. d) Mengkoordinasikan semua bantuan logistik dan peralatan dari instansi/lembaga/organisasi terkait.
2) Kepala Bidang Logistik dan Peralatan bertanggung jawab langsung kepada Komandan Darurat Bencana.
d. Bidang Administrasi Keuangan 1) Kepala Bidang Administrasi Keuangan bertugas dan bertanggung jawab: a) Atas semua administrasi keuangan b) Menganilisa kebutuhan dana dalam rangka penanganan darurat bencana yang terjadi. c) Mendukung keuangan yang dibutuhkan dalam rangka komando darurat bencana yang terjadi 2) Kepala Bidang Administrasi dan Keuangan bertanggung jawab langsung kepada Komandan Darurat Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7848, 'b. Bidang Perencanaan 1) Kepala Bidang Perencanaan bertugas dan bertanggung jawab atas pengumpulan, evaluasi dan analisis data dan informasi yang berhubungan dengan rencana operasi penanganan darurat bencana dan menyiapkan dokumen rencana tindakan operasi darurat.
2) Kepala Bidang Perencanaan bertanggung jawab langsung kepada Komandan Darurat Bencana.
c. Bidang Logistik dan Peralatan 1) Kepala Bidang Logistik dan Peralatan bertugas dan bertanggung jawab: a) Penyediaan fasilitas, jasa, dan bahan-bahan serta perlengkapan darurat bencana. b) Melaksanakan penerimaan, penyimpanan, pendistribusian dan transportasi bantuan logistik dan peralatan. c) Melaksanakan penyelenggaraan dukungan dapur umum, air bersih dan sanitasi umum. d) Mengkoordinasikan semua bantuan logistik dan peralatan dari instansi/lembaga/organisasi terkait.
2) Kepala Bidang Logistik dan Peralatan bertanggung jawab langsung kepada Komandan Darurat Bencana.
d. Bidang Administrasi Keuangan 1) Kepala Bidang Administrasi Keuangan bertugas dan bertanggung jawab: a) Atas semua administrasi keuangan b) Menganilisa kebutuhan dana dalam rangka penanganan darurat bencana yang terjadi. c) Mendukung keuangan yang dibutuhkan dalam rangka komando darurat bencana yang terjadi 2) Kepala Bidang Administrasi dan Keuangan bertanggung jawab langsung kepada Komandan Darurat Bencana.', 'Lampiran hal. 26', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7849, 'perka-24-2010', 33, 'lampiran', 'Lampiran hal. 27', NULL, 27, 'BAB VI PENUTUP Pedoman Penyusunan Rencana Operasi Darurat Bencana ini dibuat agar dapat dijadikan panduan bagi BNPB/BPBD Provinsi/Satkorlak PB/BPBD Kabupaten/Satlak PB, Komando Darurat Bencana, Instansi/ Lembaga/Organisasi terkait, sehingga tugas penanganan darurat bencana dapat dilaksanakan secara cepat, tepat, terpadu, aman, efektif, efisien, transparan dan akuntabel.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA DR. SYAMSUL MAARIF, M.Si Lampiran-01 SIKLUS PROSES PENYUSUNAN RENCANA OPERASI DARURAT BENCANA (Formulir 9) (Formulir 8) (Formulir 9) (Formulir 2) (Formulir 1a-1d) Lampiran-02 DAFTAR FORMULIR RENCANA OPERASI DARURAT BENCANA NOMOR NAMA KETERANGAN ISI FORMULIR FORMULIR FORMULIR Formulir 1 Informasi Memberikan informasi awal kepada Bencana Komandan dan Staf Komando Darurat Bencana mengenai situasi bencana dan kebutuhan bantuan sumberdaya. Informasi dari TRC dilampirkan.
Formulir 2 Tujuan Operasi Menjelaskan tujuan, sasaran dan strategi dasar operasi darurat bencana untuk periode tertentu.
Formulir 3 Susunan Memberikan informasi mengenai susunan Organisasi organisasi komando darurat bencana dan Komando personalia pimpinannya.
Formulir 4 Daftar Menginformasikan penugasan personil dalam Penugasan operasi darurat bencana Formulir 5 Jaring Memberikan informasi nomor komunikasi Komunikasi (telepon satelit, frekuensi radio komunikasi) yang ditetapkan kepada petugas pada satu lokasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7849, 'BAB VI PENUTUP Pedoman Penyusunan Rencana Operasi Darurat Bencana ini dibuat agar dapat dijadikan panduan bagi BNPB/BPBD Provinsi/Satkorlak PB/BPBD Kabupaten/Satlak PB, Komando Darurat Bencana, Instansi/ Lembaga/Organisasi terkait, sehingga tugas penanganan darurat bencana dapat dilaksanakan secara cepat, tepat, terpadu, aman, efektif, efisien, transparan dan akuntabel.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA DR. SYAMSUL MAARIF, M.Si Lampiran-01 SIKLUS PROSES PENYUSUNAN RENCANA OPERASI DARURAT BENCANA (Formulir 9) (Formulir 8) (Formulir 9) (Formulir 2) (Formulir 1a-1d) Lampiran-02 DAFTAR FORMULIR RENCANA OPERASI DARURAT BENCANA NOMOR NAMA KETERANGAN ISI FORMULIR FORMULIR FORMULIR Formulir 1 Informasi Memberikan informasi awal kepada Bencana Komandan dan Staf Komando Darurat Bencana mengenai situasi bencana dan kebutuhan bantuan sumberdaya. Informasi dari TRC dilampirkan.
Formulir 2 Tujuan Operasi Menjelaskan tujuan, sasaran dan strategi dasar operasi darurat bencana untuk periode tertentu.
Formulir 3 Susunan Memberikan informasi mengenai susunan Organisasi organisasi komando darurat bencana dan Komando personalia pimpinannya.
Formulir 4 Daftar Menginformasikan penugasan personil dalam Penugasan operasi darurat bencana Formulir 5 Jaring Memberikan informasi nomor komunikasi Komunikasi (telepon satelit, frekuensi radio komunikasi) yang ditetapkan kepada petugas pada satu lokasi.', 'Lampiran hal. 27', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7850, 'perka-24-2010', 34, 'lampiran', 'Lampiran hal. 29', NULL, 29, 'Formulir 6 Rencana Medis Memberikan informasi perihal posko kesehatan, alat transportasi medis (ambulans), rumah sakit yang ditetapkan untuk bantuan kesehatan dan prosedur tetap bantuan darurat kesehatan.
Formulir 7 Bagan Struktur organisasi Komando Darurat Organisasi bencana dengan susunan personalianya.
Komando Harus selalu diperbaharui pada setiap awal periode operasi.
Formulir 8 Rencana Format penyusunan Rencana Operasi secara Operasi deskriptif.
Formulir 9 Rencana Memberikan gambaran kebutuhan bantuan Kebutuhan sumberdaya untuk periode operasi selanjutnya. Informasi dari Formulir 9 ini menjadi dasar untuk daftar penugasan pada Formulir 4 Formulir 10 Ringkasan Memberikan informasi kepada Seksi Operasi Operasi Udara Udara dan jajarannya mengenai Jumlah, Jenis dan Lokasi pesawat serta penugasan pesawat tersebut.
