INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7851, 'perka-24-2010', 35, 'lampiran', 'Lampiran hal. 32', NULL, 32, '7. BAGAN ORGANISASI KOMANDO SAAT INI INFORMASI BENCANA
