INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7859, 'perka-24-2010', 43, 'lampiran', 'Lampiran hal. 46', NULL, 46, '4. Administrasi dan Logistik Diuraikan prosedur operasi yang digunakan, pengerahan dan pelibatan personil, alat peralatan, logistik, dukungan administrasi umum dan dukungan.
5. Anggaran Sebutkan sumber dan rencana penggunaan anggaran untuk operasi ini.
6. Komando dan Pengendalian
a. Komando: dipimpin oleh Komandan Komando Darurat Bencana sesuai dengan tingkat dan kewenangannya.
b. Pengendalian:
Lampiran-20 1) Supervisi dilakukan oleh BNPB/BPBD untuk menilai pelaksanaan Rencana Operasi. Hasil pelaksanaan operasi dilaporkan kepada Kepala Daerah dan BNPB/BPBD.
2) Diuraikan prosedur penggunaan komunikasi.
3) Pusat pengendalian berlokasi di tempat/ lokasi kantor Komando Darurat Bencana (nama jalan, nomor, nama kota, nomor telepon dan nomor facsimile).
7. Penutup Tanggal (penetapan) Ditetapkan oleh: Komandan Darurat Bencana Lampiran :
A. Surat Perintah B. Struktur Organisasi dan Susunan pejabat operasi (dari Form 7) C. Penjabaran tugas pejabat operasi D. Jaring Komunikasi (dari Form 5) E. Rencana Dukungan Anggaran Lampiran-21 FORMULIR RENCANA KEBUTUHAN OPERASI DARURAT BENCANA (Formulir 9) Formulir 9 Lampiran-22 Petunjuk Pengisian Formulir Rencana Kebutuhan (Formulir 9) NOMOR KETERANGAN PETUNJUK Rencana Kebutuhan menjelaskan jenis dan jumlah kebutuhan sumberdaya untuk masing-masing penugasan pada tindakan operasi pada periode tertentu.
Disebutkan Formulir ini digunakan oleh Kepala Bidang Logistik dan Peralatan untuk melakukan permintaan/ pengadaan kekurangan bantuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7859, '4. Administrasi dan Logistik Diuraikan prosedur operasi yang digunakan, pengerahan dan pelibatan personil, alat peralatan, logistik, dukungan administrasi umum dan dukungan.
