INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7860, 'perka-24-2010', 44, 'lampiran', 'Lampiran hal. 49', NULL, 49, 'Formulir kebutuhan dikerjakan oleh Kepala Bidang Perencanaan bersama Kepala Bidang Operasi.
1 Jenis/Lokasi Bencana Isi jenis dan lokasi bencana 2 Tanggal pembuatan Tulis tanggal Informasi dibuat (tanggal-bulan-tahun) Waktu pembuatan Tulis jam Informasi ini dibuat (jam-menit) 3 Periode Operasi Tulis jangka waktu operasi (tanggal dan waktu dari-sampai dengan) 4 Seksi/Sub- Tulis kelompok pelaksana operasi Seksi/Kelompok 5 Penugasan Kerja Tugas yang harus dilaksanakan oleh Kelompok Kerja dalamtindakan operasi tanggap darurat 6 Lokasi Tujuan Tulis lokasi tujuan bantuan 7 Permintaan Waktu Tulis keinginan waktu penerimaan Penerimaan di Tujuan bantuan di lokasi tujuan 8 Disiapkan oleh Tulis Nama dan Jabatan 9 Total Sumberdaya Jumlahkan total sumberdaya (logistik, peralatan) Kebutuhan Kebutuhan jumlah bantuan sumberdaya di lokasi bencana Tersedia Jumlah sumberdaya yang tersedia Kekurangan Jumlah kekurangan sumberdaya yang perlu dilakukan Permintaan atau Pengadaan Biaya Pengadaan Tulis biaya permintaan/pengadaan bantuan sumberdaya Lampiran-23 RINGKASAN OPERASI UDARA DARURAT BENCANA (Formulir 10) Formulir 10 Lampiran-24 Petunjuk Pengisian Formulir Ringkasan Operasi Udara Darurat Bencana (Formulir 10) NOMOR KETERANGAN PETUNJUK Ringkasan Operasi Udara memberikan informasi kepada Seksi Operasi Udara dan jajarannya mengenai Jumlah, Jenis dan Lokasi pesawat serta penugasan pesawat tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7860, 'Formulir kebutuhan dikerjakan oleh Kepala Bidang Perencanaan bersama Kepala Bidang Operasi.
1 Jenis/Lokasi Bencana Isi jenis dan lokasi bencana 2 Tanggal pembuatan Tulis tanggal Informasi dibuat (tanggal-bulan-tahun) Waktu pembuatan Tulis jam Informasi ini dibuat (jam-menit) 3 Periode Operasi Tulis jangka waktu operasi (tanggal dan waktu dari-sampai dengan) 4 Seksi/Sub- Tulis kelompok pelaksana operasi Seksi/Kelompok 5 Penugasan Kerja Tugas yang harus dilaksanakan oleh Kelompok Kerja dalamtindakan operasi tanggap darurat 6 Lokasi Tujuan Tulis lokasi tujuan bantuan 7 Permintaan Waktu Tulis keinginan waktu penerimaan Penerimaan di Tujuan bantuan di lokasi tujuan 8 Disiapkan oleh Tulis Nama dan Jabatan 9 Total Sumberdaya Jumlahkan total sumberdaya (logistik, peralatan) Kebutuhan Kebutuhan jumlah bantuan sumberdaya di lokasi bencana Tersedia Jumlah sumberdaya yang tersedia Kekurangan Jumlah kekurangan sumberdaya yang perlu dilakukan Permintaan atau Pengadaan Biaya Pengadaan Tulis biaya permintaan/pengadaan bantuan sumberdaya Lampiran-23 RINGKASAN OPERASI UDARA DARURAT BENCANA (Formulir 10) Formulir 10 Lampiran-24 Petunjuk Pengisian Formulir Ringkasan Operasi Udara Darurat Bencana (Formulir 10) NOMOR KETERANGAN PETUNJUK Ringkasan Operasi Udara memberikan informasi kepada Seksi Operasi Udara dan jajarannya mengenai Jumlah, Jenis dan Lokasi pesawat serta penugasan pesawat tersebut.', 'Lampiran hal. 49', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 24 Tahun 2010 tentang Pedoman Penyusunan Rencana Operasi Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7861, 'perka-24-2010', 45, 'lampiran', 'Lampiran hal. 51', NULL, 51, 'Kepala Bidang Operasi dan Kepala Seksi Operasi Udara bersama-sama melengkapi Formulir 10 dalam Rapat Perencanaan dengan merujuk kepada Form 9 mengenai kebutuhan bantuan bencana.
Isian Form 10 (kecuali item no.11) didistribusikan kepada Supervisor Support (Bantuan Udara). Supervisor Support melengkapi Siapa Penerima Bantuan Udara.
1 Jenis/Lokasi Bencana Isi Jenis dan Lokasi bencana 2 Jangka Waktu Operasi Tulis jangka waktu operasi (tanggal dan waktu dari-sampai dengan) 3 Distribusi Tandai kotak lalu tulis tanggal dan waktu Form 10 ini disampaikan kepada Fixed-Wing Base dan/atau Helibase.
4 Personil dan Tulis daftar personil dg jabatannya serta Komunikasi frequensi radio yang diberikan.
5 Catatan Tulis instruksi kepada personil operasi udara mengenai keselamatan, bahaya, dan prioritas2.
6 Lokasi/Fungsi Tulis lokasi tujuan bantuan udara dan fungsi pesawat.
7 Penugasan Tulis lingkup kerja yang harus dilaksanakan oleh pesawat.
8 Fixed-Wing Tulis jenis pesawat terbang sayap tetap yang tersedia untuk ke Lokasi dan dengan fungsi penugasan yg ditetapkan.
9 Helikopter Tulis jenis Helikopter yang tersedia untuk bantuan udara ke Lokasi dan dengan fungsi penugasan yg ditetapkan.
10 Waktu Tulis kapan pesawat tersedia untuk digunakan dan kapan selesainya.
11 Penerima Sebutkan Penerima Bantuan melalui pesawat ini.
12 Pangkalan Operasi Tulis dari pangkalan operasi udara mana bantuan diberangkatkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7861, 'Kepala Bidang Operasi dan Kepala Seksi Operasi Udara bersama-sama melengkapi Formulir 10 dalam Rapat Perencanaan dengan merujuk kepada Form 9 mengenai kebutuhan bantuan bencana.
