INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7862, 'perka-24-2010', 46, 'lampiran', 'Lampiran hal. 51', NULL, 51, '13 Total Jumlahkan pesawat terbang jenis sayap tetap (fixed-wing) dan helikopter yang mendapat penugasan dalam operasi darurat bencana ini.
14 Dibuat oleh/Tanggal Tulis Nama dan Jabatan yang membuat Form dan Waktu Pembuatan ini dan cantumkan tanggal dan waktu pembuatannya.
Lampiran-25 CONTOH OPERASI DARURAT BENCANA NO TUJUAN PELAKSANAAN 1 2 3
1. Rencana Evakuasi Persiapan tempat-tempat, peta dan jalur evakuasi.
