INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7864, 'perka-24-2014', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka meningkatkan upaya pemerintah dan pemerintah daerah dalam melaksanakan manajemen logistik penanggulangan bencana perlu menetapkan Pedoman Bantuan Logistik;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik perlu diubah karena sudah tidak sesuai dengan perkembangan keadaan masyarakat;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Perubahan Atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7864, 'a. bahwa dalam rangka meningkatkan upaya pemerintah dan pemerintah daerah dalam melaksanakan manajemen logistik penanggulangan bencana perlu menetapkan Pedoman Bantuan Logistik;
