INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7896, 'perka-24-2014', 33, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'LAMPIRAN I PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 24 TAHUN 2014 TENTANG PERUBAHAN ATAS PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 4 TAHUN 2009 TENTANG PEDOMAN BANTUAN LOGISTIK Alur Permintaan/ Distribusi Pada Saat Tanggap Darurat RAPAT KOORDINASI KOMANDAN TANGGAP LINTAS SEKTOR DARURAT PEMBAHASAN — Ia PROSES
