INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7897, 'perka-24-2014', 34, 'lampiran', 'Lampiran hal. 12', NULL, 12, '5. Melaporkan rekapitulasi pengeluaran gudang kepada Komandan Tanggap Darurat www .peraturan.go.id 13 2014, No.2081 LAMPIRAN II PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 24 TAHUN 2014 TENTANG PERUBAHAN ATAS PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 4 TAHUN 2009 TENTANG PEDOMAN BANTUAN LOGISTIK Alur Permintaan/ Distribusi Penguatan/ Kesiapsiagaan SURAT PERMOHONAN PERMINTAAN BANTUAN LOGISTIK 1Surat Permintaan Bantuan Logistik Kedaruratan dari BPBD Prov. /Kab.,/ Kota 2.Surat Permohonan Bantuan Logistik dari Deputi Penanganan Darurat 3.Kebijakan Pimpinan BNPB Y 4 TIDAK DIBANTU DIAGENDAKAN DI Masuk ke DEPUTI IV.
