INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7902, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENGELOLAAN PERTANGGUNGJAWABAN BANTUAN LOGISTIK PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 25 Tahun 2014 tentang Pengelolaan Pertanggungjawaban Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7903, 'perka-25-2014', 4, 'pasal', 'Pasal 1', NULL, 2, 'Pengelolaan pertanggungjawaban adalah melakukan suatu pekerjaan tertentu yang menjadi tanggung jawab sesuai hirarki, proses, prosedur dan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7903, 'Pengelolaan pertanggungjawaban adalah melakukan suatu pekerjaan tertentu yang menjadi tanggung jawab sesuai hirarki, proses, prosedur dan ketentuan peraturan perundang-undangan.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 25 Tahun 2014 tentang Pengelolaan Pertanggungjawaban Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7904, 'perka-25-2014', 5, 'pasal', 'Pasal 2', NULL, 2, 'Pengelolaan pertanggungjawaban bantuan logistik penanggulangan bencana BNPB, BPBD, Instansi/Lembaga dan pemangku kepentingan penanggulangan bencana agar pelaksanaan pengelolaan bantuan logistik pada status keadaan darurat dapat dilaksanakan dengan lancar, tertib, terpadu, aman dan dapat dipertanggungjawabkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7904, 'Pengelolaan pertanggungjawaban bantuan logistik penanggulangan bencana BNPB, BPBD, Instansi/Lembaga dan pemangku kepentingan penanggulangan bencana agar pelaksanaan pengelolaan bantuan logistik pada status keadaan darurat dapat dilaksanakan dengan lancar, tertib, terpadu, aman dan dapat dipertanggungjawabkan.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 25 Tahun 2014 tentang Pengelolaan Pertanggungjawaban Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7905, 'perka-25-2014', 6, 'pasal', 'Pasal 3', NULL, 2, 'Peraturan pengelolaan pertanggungjawaban bantuan logistik penanggulangan bencana mencakup tahap pra bencana, tahap status keadaan darurat dan pasca bencana, sesuai tingkatan kewenangan BNPB, BPBD provinsi dan kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7905, 'Peraturan pengelolaan pertanggungjawaban bantuan logistik penanggulangan bencana mencakup tahap pra bencana, tahap status keadaan darurat dan pasca bencana, sesuai tingkatan kewenangan BNPB, BPBD provinsi dan kabupaten/kota.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 25 Tahun 2014 tentang Pengelolaan Pertanggungjawaban Bantuan Logistik Penanggulangan Bencana');
