INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7907, 'perka-25-2014', 8, 'pasal', 'Pasal 5', NULL, 3, 'Peraturan Kepala ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7907, 'Peraturan Kepala ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 25 Tahun 2014 tentang Pengelolaan Pertanggungjawaban Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7908, 'perka-25-2014', 9, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal, 1 Desember 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal, 31 Desember 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY 2014, No.2082 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7908, 'Ditetapkan di Jakarta pada tanggal, 1 Desember 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal, 31 Desember 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY 2014, No.2082 4', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 25 Tahun 2014 tentang Pengelolaan Pertanggungjawaban Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7909, 'perka-25-2014', 10, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 25 TAHUN 2014 TENTANG PEDOMAN PENGELOLAAN PERTANGGUNGJAWABAN BANTUAN LOGISTIK PENANGGULANGAN BENCANA PEDOMAN PENGELOLAAN PERTANGGUNGJAWABAN BANTUAN LOGISTIK PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Sesuai amanat Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, Peraturan Pemer intah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana dan Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana, Kepala Badan Nasional Penanggulangan Bencana (BNPB) mempunyai tugas membangun sistem manajemen logistik dan peralatan serta menyusun berbagai pedoman yang diperlukan guna pelaksanaan bantuan bencana termasuk pertanggung jawaban bantuan logistik penanggulangan bencana.
Sebagaimana kondisi wilayah Indonesia yang merupakan negara kepulauan yang sedemikian luas dan dengan letak geografi serta topografi yang berbukit, lembah dan jurang merupakan tantangan tersendiri dalam distribusi bantuan logistik penanggulangan bencana. Hal ini terkait pemilihan moda transportasi dan sekaligus juga terkait dengan percepatan pertangung jawaban.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7909, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 25 TAHUN 2014 TENTANG PEDOMAN PENGELOLAAN PERTANGGUNGJAWABAN BANTUAN LOGISTIK PENANGGULANGAN BENCANA PEDOMAN PENGELOLAAN PERTANGGUNGJAWABAN BANTUAN LOGISTIK PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Sesuai amanat Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, Peraturan Pemer intah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana dan Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana, Kepala Badan Nasional Penanggulangan Bencana (BNPB) mempunyai tugas membangun sistem manajemen logistik dan peralatan serta menyusun berbagai pedoman yang diperlukan guna pelaksanaan bantuan bencana termasuk pertanggung jawaban bantuan logistik penanggulangan bencana.
Sebagaimana kondisi wilayah Indonesia yang merupakan negara kepulauan yang sedemikian luas dan dengan letak geografi serta topografi yang berbukit, lembah dan jurang merupakan tantangan tersendiri dalam distribusi bantuan logistik penanggulangan bencana. Hal ini terkait pemilihan moda transportasi dan sekaligus juga terkait dengan percepatan pertangung jawaban.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 25 Tahun 2014 tentang Pengelolaan Pertanggungjawaban Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7910, 'perka-25-2014', 11, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'Walaupun logistik dan peralatan harus diberikan secara cepat dan tepat, namun harus juga dapat dilaksanakan secara transparan dan dapat dipertanggung jawabkan baik secara administratif dan keuangan kepada negara dan masyarakat. Berdasarkan hal-hal tersebut diatas maka dipandang perlu disusun pedoman pertanggung jawaban bantuan logistik.
5 2014, No.2082 B. Maksud dan Tujuan
1. Memberikan pedoman bagi BNPB, Badan Penanggulangan Bencana Daerah (BPBD), Instansi terkait dan para pemangku kepentingan dalam menyusun pertanggung jawaban bantuan logistik penanggulangan bencana.
2. Tercapainya pengelolaan pertanggung jawaban bantuan logistik penanggulangan bencana yang akuntabel.
C. Ruang Lingkup Lingkup pertanggung jawaban bantuan logistik penanggulangan bencana mencakup tahap pra bencana, tahap status darurat dan pasca bencana, sesuai tingkatan kewenangan baik pusat, daerah (provinsi dan kabupaten/kota).
D. Landasan Hukum
1. Undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah;
2. Undang-undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana;
3. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
4. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana;
5. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana;
6. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7910, 'Walaupun logistik dan peralatan harus diberikan secara cepat dan tepat, namun harus juga dapat dilaksanakan secara transparan dan dapat dipertanggung jawabkan baik secara administratif dan keuangan kepada negara dan masyarakat. Berdasarkan hal-hal tersebut diatas maka dipandang perlu disusun pedoman pertanggung jawaban bantuan logistik.
5 2014, No.2082 B. Maksud dan Tujuan
1. Memberikan pedoman bagi BNPB, Badan Penanggulangan Bencana Daerah (BPBD), Instansi terkait dan para pemangku kepentingan dalam menyusun pertanggung jawaban bantuan logistik penanggulangan bencana.
2. Tercapainya pengelolaan pertanggung jawaban bantuan logistik penanggulangan bencana yang akuntabel.
C. Ruang Lingkup Lingkup pertanggung jawaban bantuan logistik penanggulangan bencana mencakup tahap pra bencana, tahap status darurat dan pasca bencana, sesuai tingkatan kewenangan baik pusat, daerah (provinsi dan kabupaten/kota).
D. Landasan Hukum
1. Undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah;
2. Undang-undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana;
3. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
4. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana;
5. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana;
6. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Non Pemerintah dalam Penanggulangan Bencana;', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 25 Tahun 2014 tentang Pengelolaan Pertanggungjawaban Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7911, 'perka-25-2014', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, '7. Peraturan Pemerintah Nomor 38 Tahun 2008 tentang Perubahan Peraturan Pemerintah Nomor 6 Tahun 2006 tentang Pengelolaan Barang Milik Negara/Daerah.
E. Sistematika Pedoman Pengelolaan Pertanggung jawaban Bantuan Logistik Penanggulangan Bencana ini disusun dengan sistematika sebagai berikut:
2014, No.2082 6 BAB I PENDAHULUAN BAB II PRINSIP DASAR, KEBIJAKAN, DAN STRATEGI BAB III LANGKAH PENYUSUNAN ADMINISTRASI PERTANGGUNGJAWABAN BAB IV PELAKSANAAN PENYUSUNAN PERTANGGUNG JAWABAN BAB V PENUTUP LAMPIRAN F. Pengertian 1.Anggaran Pendapatan dan Belanja Negara adalah rencana keuangan tahunan pemerintah negara Indonesia yang disetujui oleh Dewan Perwakilan Rakyat. APBN berisi daftar sistematis dan terperinci yang memuat rencana penerimaan dan pengeluaran negara selama satu tahun anggaran (1 Januari - 31 Desember).
APBN, perubahan APBN, dan pertanggung jawaban APBN setiap tahun ditetapkan dengan Undang-Undang.Perencanaan bantuan logistik penanggulangan bencana adalah proses mengidentifikasi dan menyusun barang bantuan logistik penanggulangan bencana dan sistem pendukungnya pada semua tahap penanggulangan bencana sesuai kewenangannya.
2.Bantuan logistik penanggulangan bencana adalah barang atau perlengkapan yang dimaksudkan dapat digunakan untuk memenuhi kebutuhan dasar manusia yang terdiri atas sandang, pangan dan papan atau turunannya untuk diserahkan kepada pihak yang membutuhkan dalam rangka pelayanan kepada masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7911, '7. Peraturan Pemerintah Nomor 38 Tahun 2008 tentang Perubahan Peraturan Pemerintah Nomor 6 Tahun 2006 tentang Pengelolaan Barang Milik Negara/Daerah.
E. Sistematika Pedoman Pengelolaan Pertanggung jawaban Bantuan Logistik Penanggulangan Bencana ini disusun dengan sistematika sebagai berikut:
2014, No.2082 6 BAB I PENDAHULUAN BAB II PRINSIP DASAR, KEBIJAKAN, DAN STRATEGI BAB III LANGKAH PENYUSUNAN ADMINISTRASI PERTANGGUNGJAWABAN BAB IV PELAKSANAAN PENYUSUNAN PERTANGGUNG JAWABAN BAB V PENUTUP LAMPIRAN F. Pengertian 1.Anggaran Pendapatan dan Belanja Negara adalah rencana keuangan tahunan pemerintah negara Indonesia yang disetujui oleh Dewan Perwakilan Rakyat. APBN berisi daftar sistematis dan terperinci yang memuat rencana penerimaan dan pengeluaran negara selama satu tahun anggaran (1 Januari - 31 Desember).
APBN, perubahan APBN, dan pertanggung jawaban APBN setiap tahun ditetapkan dengan Undang-Undang.Perencanaan bantuan logistik penanggulangan bencana adalah proses mengidentifikasi dan menyusun barang bantuan logistik penanggulangan bencana dan sistem pendukungnya pada semua tahap penanggulangan bencana sesuai kewenangannya.
2.Bantuan logistik penanggulangan bencana adalah barang atau perlengkapan yang dimaksudkan dapat digunakan untuk memenuhi kebutuhan dasar manusia yang terdiri atas sandang, pangan dan papan atau turunannya untuk diserahkan kepada pihak yang membutuhkan dalam rangka pelayanan kepada masyarakat.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 25 Tahun 2014 tentang Pengelolaan Pertanggungjawaban Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7912, 'perka-25-2014', 13, 'lampiran', 'Lampiran hal. 6', NULL, 6, '3.Persediaan bantuan logistik adalah aset lancar dalam bentuk barang bantuan logistik yang dimaksudkan untuk diberikan kepada pihak yang memerlukan dalam kegiatan operasional penanggulangan bencana, kemanusiaan.
4.Dokumen Sumber adalah dokumen yang berhubungan dengan perencanaan, pengadaan, pembelian, permintaan, penyimpanan, pergudangan, pengiriman (distribusi) dan penghapusan bantuan logistik yang digunakan sebagai sumber atau bukti untuk menghasilkan data akuntansi.
5.Pertanggungjawaban adalah melakukan suatu pekerjaan tertentu yang menjadi tanggungjawabnya sesuai hirarki, proses, prosedur dan ketentuan serta peraturan perundangan yang berlaku.
7 2014, No.2082 BAB II PRINSIP DASAR, KEBIJAKAN DAN STRATEGI.
A. PRINSIP DASAR.
Untuk menjamin terselenggaranya penanggulangan bencana secara cepat, tepat, transparan dan akuntabel diperlukan prinsip-prinsip sebagai berikut :
1. Akuntabel.
Bantuan logistik penanggulangan bencana yang dikelola oleh BNPB dan/atau BPBD harus dapat diterima oleh masyarakat yang terkena dampak bencana tepat waktu, tepat lokasi, tepat sasaran, tepat jumlah dan tepat kualitas.
2. Mengacu pada Sistem Manajemen Logistik.
Bantuan Logistik mengacu kepada kegiatan perencanaan, pengadaan, pendistribusian, penyaluran, penerimaan dan pengahapusan.
3. Koordinasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7912, '3.Persediaan bantuan logistik adalah aset lancar dalam bentuk barang bantuan logistik yang dimaksudkan untuk diberikan kepada pihak yang memerlukan dalam kegiatan operasional penanggulangan bencana, kemanusiaan.
4.Dokumen Sumber adalah dokumen yang berhubungan dengan perencanaan, pengadaan, pembelian, permintaan, penyimpanan, pergudangan, pengiriman (distribusi) dan penghapusan bantuan logistik yang digunakan sebagai sumber atau bukti untuk menghasilkan data akuntansi.
5.Pertanggungjawaban adalah melakukan suatu pekerjaan tertentu yang menjadi tanggungjawabnya sesuai hirarki, proses, prosedur dan ketentuan serta peraturan perundangan yang berlaku.
7 2014, No.2082 BAB II PRINSIP DASAR, KEBIJAKAN DAN STRATEGI.
A. PRINSIP DASAR.
Untuk menjamin terselenggaranya penanggulangan bencana secara cepat, tepat, transparan dan akuntabel diperlukan prinsip-prinsip sebagai berikut :
1. Akuntabel.
Bantuan logistik penanggulangan bencana yang dikelola oleh BNPB dan/atau BPBD harus dapat diterima oleh masyarakat yang terkena dampak bencana tepat waktu, tepat lokasi, tepat sasaran, tepat jumlah dan tepat kualitas.
2. Mengacu pada Sistem Manajemen Logistik.
Bantuan Logistik mengacu kepada kegiatan perencanaan, pengadaan, pendistribusian, penyaluran, penerimaan dan pengahapusan.
3. Koordinasi.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 25 Tahun 2014 tentang Pengelolaan Pertanggungjawaban Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7913, 'perka-25-2014', 14, 'lampiran', 'Lampiran hal. 7', NULL, 7, 'Pelaksanaan bantuan logistik penanggulangan bencana dilaksanakan melalui koordinasi secara secara berjenjang, berkoordinasi dengan Kementerian/Lembaga terkait, Organisasi Perangkat Daerah (OPD) termasuk BPBD serta Organisasi nonpemerintah.
4. Tata kelola pemerintahan yang baik (Good Governance).
Pelaksanaan bantuan Logistik penanggulangan bencana berdasarkan prinsip tata kelola pemerintahan yang baik antara lain : skala prioritas, terkoordinasi dan keterpaduan, berdaya guna dan berhasil guna, keberlanjutan program, transparansi, akuntabilitas.
5. Prioritas kelompok rentan.
Pelaksanaan pemberian bantuan Logistik dengan memprioritaskan kelompok rentan antara lain : perempuan, anak-anak, lanjut usia dan penyandang cacat.
2014, No.2082 8
6. Prioritas Wilayah.
Bantuan logistik diarahkan pada daerah rawan bencana dan yang terkena bencana.
B. KEBIJAKAN.
Kebijakan bantuan logistik diarahkan untuk memenuhi ketentuan dan peraturan perundangan yang berlaku dengan memperhatikan hal-hal sebagai berikut :
1. Penanggulangan bencana merupakan tanggung jawab Pemerintah dan Pemerintah Daerah sehingga pertanggung jawaban disusun berdasarkan penjenjangan dan hierarkhi kewenangan.
2. Memberikan peluang seluas-luasnya kepada pihak-pihak untuk mengetahui dan mengevaluasi pertanggung jawaban sesuai dengan ketentuan dan perundangan yang berlaku.
3. Dengan secara terbuka menerima masukan yang konstruktif guna perbaikan dan pelaksanaan bantuan logistik yang lebih baik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7913, 'Pelaksanaan bantuan logistik penanggulangan bencana dilaksanakan melalui koordinasi secara secara berjenjang, berkoordinasi dengan Kementerian/Lembaga terkait, Organisasi Perangkat Daerah (OPD) termasuk BPBD serta Organisasi nonpemerintah.
4. Tata kelola pemerintahan yang baik (Good Governance).
Pelaksanaan bantuan Logistik penanggulangan bencana berdasarkan prinsip tata kelola pemerintahan yang baik antara lain : skala prioritas, terkoordinasi dan keterpaduan, berdaya guna dan berhasil guna, keberlanjutan program, transparansi, akuntabilitas.
5. Prioritas kelompok rentan.
Pelaksanaan pemberian bantuan Logistik dengan memprioritaskan kelompok rentan antara lain : perempuan, anak-anak, lanjut usia dan penyandang cacat.
2014, No.2082 8
6. Prioritas Wilayah.
Bantuan logistik diarahkan pada daerah rawan bencana dan yang terkena bencana.
B. KEBIJAKAN.
Kebijakan bantuan logistik diarahkan untuk memenuhi ketentuan dan peraturan perundangan yang berlaku dengan memperhatikan hal-hal sebagai berikut :
1. Penanggulangan bencana merupakan tanggung jawab Pemerintah dan Pemerintah Daerah sehingga pertanggung jawaban disusun berdasarkan penjenjangan dan hierarkhi kewenangan.
2. Memberikan peluang seluas-luasnya kepada pihak-pihak untuk mengetahui dan mengevaluasi pertanggung jawaban sesuai dengan ketentuan dan perundangan yang berlaku.
3. Dengan secara terbuka menerima masukan yang konstruktif guna perbaikan dan pelaksanaan bantuan logistik yang lebih baik.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 25 Tahun 2014 tentang Pengelolaan Pertanggungjawaban Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7914, 'perka-25-2014', 15, 'lampiran', 'Lampiran hal. 8', NULL, 8, '4. Berupaya membangun dan memantapkan sistem informasi yang lebih baik dalam pelaksanaan bantuan logistik yang cepat, tepat, transparan dan akuntabel.
C. STRATEGI.
Agar pertanggung jawaban bantuan logistik dan peralatan dapat dilaksanakan dengan baik maka perlu strategi yang harus dilakukan sebagai berikut :
1. Adanya mekanisme yang jelas sejak persiapan, perencanaan dan pelaksanaan pendistribusian bantuan serta monitoring dan evaluasi baik ditingkat pusat, provinsi maupun kabupaten/kota.
2. Adanya instrumen pendukung berupa berupa dokumen dan fomulir-formulir yang diperlukan.
9 2014, No.2082 BAB III PELAKSANAAN PENYUSUNAN PERTANGGUNG JAWABAN Pertanggung jawaban bukan dinilai sekadar dari laporan akhir disampaikan, namun sejak awal proses persiapan, penelaahan, pengesahan bantuan logistik dan pelaksanaan distribusi serta penerimaan bantuan.
Pertanggungjawaban bukan sekadar dari sisi formalitas prosedur, melainkan secara substantif juga harus memenuhi unsur pertanggungjawaban yang benar sesuai dengan ketentuan dan perundangan yang berlaku.
Pertanggung jawaban bantuan logistik dilaksanakan dengan memperhatikan jenis bencana, sesuai kebutuhan, partisipasi dan pengawasan seluruh elemen.
BNPB dan BPBD harus melakukan pengelolaan bantuan logistik secara cermat dan transparan serta akuntabel agar dapat segera memulihkan situasi korban bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7914, '4. Berupaya membangun dan memantapkan sistem informasi yang lebih baik dalam pelaksanaan bantuan logistik yang cepat, tepat, transparan dan akuntabel.
C. STRATEGI.
Agar pertanggung jawaban bantuan logistik dan peralatan dapat dilaksanakan dengan baik maka perlu strategi yang harus dilakukan sebagai berikut :
1. Adanya mekanisme yang jelas sejak persiapan, perencanaan dan pelaksanaan pendistribusian bantuan serta monitoring dan evaluasi baik ditingkat pusat, provinsi maupun kabupaten/kota.
2. Adanya instrumen pendukung berupa berupa dokumen dan fomulir-formulir yang diperlukan.
9 2014, No.2082 BAB III PELAKSANAAN PENYUSUNAN PERTANGGUNG JAWABAN Pertanggung jawaban bukan dinilai sekadar dari laporan akhir disampaikan, namun sejak awal proses persiapan, penelaahan, pengesahan bantuan logistik dan pelaksanaan distribusi serta penerimaan bantuan.
Pertanggungjawaban bukan sekadar dari sisi formalitas prosedur, melainkan secara substantif juga harus memenuhi unsur pertanggungjawaban yang benar sesuai dengan ketentuan dan perundangan yang berlaku.
Pertanggung jawaban bantuan logistik dilaksanakan dengan memperhatikan jenis bencana, sesuai kebutuhan, partisipasi dan pengawasan seluruh elemen.
BNPB dan BPBD harus melakukan pengelolaan bantuan logistik secara cermat dan transparan serta akuntabel agar dapat segera memulihkan situasi korban bencana.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 25 Tahun 2014 tentang Pengelolaan Pertanggungjawaban Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7915, 'perka-25-2014', 16, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'Dalam hal ini melalui tingkatan kewenangan yang ada perlu kejelasan arah agar setiap petugas yang bertanggung jawab dalam menyusun pertanggung jawaban memahami akan tugas yang diembannya sebagaimana dijelaskan sebagai berikut:
1. Nasional
a. Kewajiban pertanggung jawaban bantuan logistik penanggulangan bencana pada saat pra bencana (kesiapsiagaan) dan status keadaan darurat dilaksanakan oleh BNPB.
b. Fungsi pertanggung jawaban bantuan logistik pada pra bencana dan pada status keadaan darurat bencana di tingkat nasional adalah:
1) Melaporkan tentang bantuan logistik yang telah didistribusikan sampai ditingkat Provinsi dan Kabupaten/Kota.
2) Melaporkan fakta dan informasi bantuan logistik yang dibutuhkan oleh masyarakat terdampak bencana yang dapat dipertanggungjawabkan secara akuntabel.
2014, No.2082 10 3) Menunjukkan komitmen Pemerintah sebagai pengelola dan penanggung jawab seluruh bantuan logistik penanggulangan bencana.
4) Mempertanggung jawabkan atas pengelolaan dan pendistribusian bantuan logistik penanggulangan bencana yang bersumber dari APBN sesuai dengan peraturan perundang-undangan.
2. Daerah BPBD provinsi dan BPBD kabupaten/kota dalam pengelolaan bantuan logistik pada tahap pra bencana (kesiapsiagaan) dan saat status keadaan darurat bertitik tolak pada bantuan yang diterima dari BNPB berdasarkan Berita Acara Serah Terima Barang (BAST).
Fungsi BPBD dalam pengelolaan bantuan logistik penanggulangan bencana adalah:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7915, 'Dalam hal ini melalui tingkatan kewenangan yang ada perlu kejelasan arah agar setiap petugas yang bertanggung jawab dalam menyusun pertanggung jawaban memahami akan tugas yang diembannya sebagaimana dijelaskan sebagai berikut:
1. Nasional
a. Kewajiban pertanggung jawaban bantuan logistik penanggulangan bencana pada saat pra bencana (kesiapsiagaan) dan status keadaan darurat dilaksanakan oleh BNPB.
b. Fungsi pertanggung jawaban bantuan logistik pada pra bencana dan pada status keadaan darurat bencana di tingkat nasional adalah:
1) Melaporkan tentang bantuan logistik yang telah didistribusikan sampai ditingkat Provinsi dan Kabupaten/Kota.
2) Melaporkan fakta dan informasi bantuan logistik yang dibutuhkan oleh masyarakat terdampak bencana yang dapat dipertanggungjawabkan secara akuntabel.
2014, No.2082 10 3) Menunjukkan komitmen Pemerintah sebagai pengelola dan penanggung jawab seluruh bantuan logistik penanggulangan bencana.
4) Mempertanggung jawabkan atas pengelolaan dan pendistribusian bantuan logistik penanggulangan bencana yang bersumber dari APBN sesuai dengan peraturan perundang-undangan.
2. Daerah BPBD provinsi dan BPBD kabupaten/kota dalam pengelolaan bantuan logistik pada tahap pra bencana (kesiapsiagaan) dan saat status keadaan darurat bertitik tolak pada bantuan yang diterima dari BNPB berdasarkan Berita Acara Serah Terima Barang (BAST).
Fungsi BPBD dalam pengelolaan bantuan logistik penanggulangan bencana adalah:', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 25 Tahun 2014 tentang Pengelolaan Pertanggungjawaban Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7916, 'perka-25-2014', 17, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'a. Basis bagi pendistribusian bantuan logistik penanggulangan bencana, oleh karena itu seluruh bantuan logistik penanggulangan bencana dari BNPB harus melalui BPBD.
b. Bertanggung jawab atas kelancaran distribusi bantuan logistik penanggulangan bencana.
c. Mengkoordinasikan semua pelayanan dan pendistribusian bantuan logistik penanggulangan bencana.
d. Mengkoordinasikan semua lembaga yang terlibat dalam bantuan logistik penanggulangan bencana, dan melaporkannya secara periodik kepada kepala BNPB.
BAB IV KETENTUAN DAN PERSYARATAN ADMINISTRASI PERTANGGUNG JAWABAN BANTUAN LOGISTIK PENANGGULANGAN BENCANA Berdasarkan kewenangan pengelolaan pertanggung jawaban bantuan logistik penanggulangan bencana pada saat pra bencana/kesiapsiagaan, status keadaan 11 2014, No.2082 darurat maupun pasca bencana dikelompokkan menjadi tingkat BNPB, BPBD tingkat Provinsi dan BPBD tingkat Kabupaten/Kota.
A. Dokumen pertanggung jawaban bantuan logistik BNPB adalah sebagai berikut:
1. Pra Bencana/Kesiapsiagaan dan Pasca Bencana.
a. Hasil inventarisasi tingkat Pusat dan/atau usulan bantuan logistik dari daerah secara berjenjang.
b. Tabel perhitungan setiap Provinsi yang akan menerima bantuan logistik yang berdasarkan standar minimal dan persediaan/stok yang dimiliki BNPB.
c. Surat Perintah Pengeluaran Barang (SPPB) dari Direktur Logistik.
d. Berita Acara Serah Terima (BAST) bantuan ditanda tangani oleh Sekretaris Utama BNPB dan Kepala Pelaksana BPBD.
e. Surat jalan yang dikeluarkan oleh kepala gudang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7916, 'a. Basis bagi pendistribusian bantuan logistik penanggulangan bencana, oleh karena itu seluruh bantuan logistik penanggulangan bencana dari BNPB harus melalui BPBD.
b. Bertanggung jawab atas kelancaran distribusi bantuan logistik penanggulangan bencana.
