INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7917, 'perka-25-2014', 18, 'lampiran', 'Lampiran hal. 11', NULL, 11, '2. Status Keadaan Darurat.
a. Laporan kejadian bencana dan/atau usulan bantuan logistik dari daerah.
b. Surat Pernyataan status keadaan darurat dari Kepala Daerah sesuai tingkatan bencana.
c. Telaahan rencana bantuan berdasarkan inisiatif Provinsi atau laporan dan usulan daerah.
d. Surat Perintah Pengeluaran Barang (SPPB) dari Direktur Logistik.
e. Berita Acara Serah Terima (BAST) bantuan logistik ditanda tangani oleh Sekretaris Utama BNPB dan Kepala Pelaksana BPBD.
f. Dokumen pengangkutan barang (SIM, STNK, Airway Bill, Bill of Lading, Surat Jalan dari Ekspedisi dan Manifest barang).
g. Surat Jalan yang dikeluarkan oleh kepala gudang.
Permintaan bantuan logistik dari internal BNPB dilengkapi BAST yang ditanda tangani oleh masing-masing penanggungjawab kedeputian.
2014, No.2082 12 B. Dokumen pertanggungjawaban bantuan logistik di BPBD tingkat Provinsi dan BPBD tingkat Kabupaten/Kota adalah sebagai berikut :
1. Pra Bencana/Kesiapsiagaan.
a. Tabel perhitungan bantuan logistik setiap Kabupaten/Kota/Kecamatan yang akan menerima bantuan logistik berdasarkan standar minimal, dan tingkat kerawanan bencana.
b. Surat Perintah Pengeluaran Barang (SPPB) dari Kepala Pelaksana BPBD.
c. Berita Acara Serah Terima (BAST) bantuan logistik ditanda tangani oleh Kepala Pelaksana BPBD dan penerima bantuan.
d. Surat Jalan yang dikeluarkan oleh kepala gudang.
2. Status Keadaan Darurat.
a. Surat Pernyataan status keadaan darurat dari Kepala Daerah sesuai tingkatan bencana.');
