INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7918, 'perka-25-2014', 19, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'b. Laporan kejadian bencana dan/atau permintaan bantuan logistik dari daerah.
c. Telaahan rencana bantuan berdasarkan inisiatif Provinsi atau laporan dan usulan daerah.
d. Surat Perintah Pengeluaran Barang (SPPB) dan Berita Acara Serah Terima (BAST) bantuan disiapkan oleh:
