INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7922, 'perka-26-2010', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG JADWAL RETENSI ARSIP KEPEGAWAIAN PEGAWAI NEGERI SIPIL DAN PEJABAT NEGARA BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7922, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG JADWAL RETENSI ARSIP KEPEGAWAIAN PEGAWAI NEGERI SIPIL DAN PEJABAT NEGARA BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2010 tentang Jadwal Retensi Arsip Kepegawaian Pegawai Negeri Sipil dan Pejabat Negara Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7923, 'perka-26-2010', 4, 'pasal', 'Pasal 1', NULL, 3, 'Dalam Peraturan Kepala ini yang dimaksud dengan:
1. Arsip adalah rekaman kegiatan atau peristiwa dalam berbagai bentuk dan media sesuai dengan perkembangan teknologi informasi dan komunikasi yang di buat dan di terima oleh lembaga Negara, pemerintahan daerah, lembaga pendidikan, perusahaan, organisasi politik, organisasi kemasyarakatan, dan perseorangan dalam pelaksanaan kehidupan bermasyarakat, berbangsa, dan bernegara.
2. Arsip Dinamis adalah arsip yang digunakan secara langsung dalam kegiatan pencipta arsip dan di simpan selama jangka waktu tertentu.
3. Arsip Vital adalah arsip yang keberadaannya merupakan persyaratan dasar bagi kelangsungan operasional pencipta arsip, tidak dapat diperbarui, dan tidak tergantikan apabila rusak atau hilang.
4. Arsip Aktif adalah arsip yang frekuensi penggunaannya tinggi dan/atau terus menerus.
5. Arsip lnaktif adalah arsip yang frekuensi penggunaannya telah menurun.
6. Arsip Statis adalah arsip yang dihasilkan oleh pencipta arsip karena memiliki nilai guna kesejarahan, telah habis retensinya, dan berketerangan dipermanenkan yang telah di versifikasi baik secara langsung maupun tidak langsung oleh Arsip Nasional Republik Indonesia dan/atau lembaga kearsipan.
7. Nilai Guna Arsip adalah nilai arsip yang didasarkan pada kegunaannya bagi kepentingan pengguna arsip.
8. Nilai Guna Primer adalah nilai arsip yang didasarkan pada kegunaan arsip bagi kepentingan lembaga I instansi pencipta arsip.
9. Nilai Guna Sekunder adalah nilai arsip yang didasarkan pada kegunaan arsip bagi kepentingan lembaga/instansi lain dan atau kepentingan umum di luar lembaga/instansi pencipta arsip dan kegunaannya sebagai bahan bukti dan bahan pertanggungjawaban nasional.
10. Jadwal Retensi Arsip yang selanjutnya disingkat JRA adalah daftar yang berisi sekurang - kurangnya jangka waktu penyimpanan atau 2014, No.1555 4 retensi, jenis arsip, dan keterangan yang berisi rekomendasi tentang penetapan suatu jenis arsip dimusnahkan, dinilai kembali, atau dipermanenkan yang dipergunakan sebagai acuan penyusutan dan penyelamatan arsip.
11. Jenis Arsip adalah unit-unt berkas yang di cipta, di atur dan di kelola sebagai suatu unit karena berhubungan secara fungsi atau subyek, merupakan hasil dari kegiatan yang sama.
12. Jangka Waktu Simpan adalah masa simpan minimal suatu jenis arsip pada Unit Pengolah dan/atau Unit Kearsipan.
13. Jangka Waktu Simpan Aktif adalah masa simpan minimal suatu jenis arsip pada Unit Pengolah.
14. Jangka Waktu Simpan lnaktif adalah masa simpan minimal suatu jenis arsip pada Unit Kearsipan/Pusat Arsip.
15. Keterangan Musnah adalah keterangan yang menyatakan bahwaarsip dapat dimusnahkan karena jangka waktu penyimpanan telah selesai dan tidak memiliki nilai guna lagi.
16. Keterangan Permanen adalah keterangan yang menyatakan bahwa arsip memiliki nilai guna sekunder, wajib diserahkan kepada Arsip Nasional Republik lndonesia/Lembaga Kearsipan sesuai dengan lingkup kewenangan masing-masing.
17. Keterangan Dinilai Kembaliadalah keterangan yang menyatakan bahwa suatu jenis arsip belum dapat ditentukan nasib akhirnya apakah musnah atau permanen, sehingga perlu dilakukan penilaian dan pengkajian lagi.
18. Pejabat Negara adalah pimpinan dan anggota lembaga negara dan pejabat lainnya berdasarkan ketentuan peraturan perundang-undangan.
19. Pegawai Negeri Sipil adalah Pegawai Negeri Sipil sebagaimana dimaksud dalam Undang-Undang Nomor 8 Tahun 1974 tentang Pokok-pokok Kepegawaian sebagaimana telah di ubah dengan Undang-Undang Nomor 43 Tahun 1999.
20. Jadwal Retensi Arsip Kepegawaian adalah jadwal retensi arsip mengenai arsip Pegawai Negeri Sipil dan Pejabat Negara.
21. Berkas Perseorangan adalah arsip yang tercipta dalam rangka perjalanan karier Pegawai Negeri Sipil di Lembaga-lembaga Negara dan Badan-badan Pemerintah.
22. Arsip Dokumentasi Kepegawaian adalah arsip yang tercipta dalam rangka perjalanan karier Pegawai Negeri yang tercipta dalam proses pembinaan kepegawaian oleh pejabat yang berwenang.
5 2014, No.1555
23. Data Kepegawaian adalah informasi mengenai perkembangan karier Pegawai Negeri Sipil yang di susun berdasarkan arsip dokumentasi kepegawaian dari instansi yang bersangkutan.
24. Jadwal Retensi Arsip Pejabat Negara, adalah jadwal retensi arsip mengenai arsip orang perseorangan yang merupakan rekaman perjalanan karier Pegawai Negeri/non Pegawai Negeri yang di angkat sebagai pejabat Negara.
25. Penyelenggaraan kearsipan adalah keseluruhan kegiatan meliputi kebijakan, pembinaan kearsipan, dan pengelolaan arsip dalam suatu sistem kearsipan nasional yang didukung oleh sumber daya manusia, prasarana dan sarana, serta sumber daya lainnya.
26. Pengelolaan Arsip Dinamis adalah proses pengendalian arsip dinamis secara efisien, efektif, dan sistematis meliputi penciptaan, penggunaan dan pemeliharaan, serta penyusutan arsip.
27. Unit Pengolah adalah satuan kerja pada pencipta arsip yang mempunyai tugas dan tanggung jawab mengolah semua arsip yang berkaitan dengan kegiatan penciptaan arsip dilingkungannya.
28. Unit Kearsipan adalah satuan ke a pada pencipta arsip yang mempunyai tugas dan tanggung jawab dalam penyelenggaraan kearsipan.
29. Penyusutan arsip adalah kegiatan pengurangan jumlah arsip dengan cara pemindahan arsip inaktif dari unit pengolah ke unit kearsipan, pemusnahan arsip yang tidak memiliki nilai guna, dan penyerahan arsip statis kepada lembaga kearsipan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7923, 'Dalam Peraturan Kepala ini yang dimaksud dengan:
1. Arsip adalah rekaman kegiatan atau peristiwa dalam berbagai bentuk dan media sesuai dengan perkembangan teknologi informasi dan komunikasi yang di buat dan di terima oleh lembaga Negara, pemerintahan daerah, lembaga pendidikan, perusahaan, organisasi politik, organisasi kemasyarakatan, dan perseorangan dalam pelaksanaan kehidupan bermasyarakat, berbangsa, dan bernegara.
2. Arsip Dinamis adalah arsip yang digunakan secara langsung dalam kegiatan pencipta arsip dan di simpan selama jangka waktu tertentu.
3. Arsip Vital adalah arsip yang keberadaannya merupakan persyaratan dasar bagi kelangsungan operasional pencipta arsip, tidak dapat diperbarui, dan tidak tergantikan apabila rusak atau hilang.
4. Arsip Aktif adalah arsip yang frekuensi penggunaannya tinggi dan/atau terus menerus.
5. Arsip lnaktif adalah arsip yang frekuensi penggunaannya telah menurun.
6. Arsip Statis adalah arsip yang dihasilkan oleh pencipta arsip karena memiliki nilai guna kesejarahan, telah habis retensinya, dan berketerangan dipermanenkan yang telah di versifikasi baik secara langsung maupun tidak langsung oleh Arsip Nasional Republik Indonesia dan/atau lembaga kearsipan.
7. Nilai Guna Arsip adalah nilai arsip yang didasarkan pada kegunaannya bagi kepentingan pengguna arsip.
8. Nilai Guna Primer adalah nilai arsip yang didasarkan pada kegunaan arsip bagi kepentingan lembaga I instansi pencipta arsip.
9. Nilai Guna Sekunder adalah nilai arsip yang didasarkan pada kegunaan arsip bagi kepentingan lembaga/instansi lain dan atau kepentingan umum di luar lembaga/instansi pencipta arsip dan kegunaannya sebagai bahan bukti dan bahan pertanggungjawaban nasional.
10. Jadwal Retensi Arsip yang selanjutnya disingkat JRA adalah daftar yang berisi sekurang - kurangnya jangka waktu penyimpanan atau 2014, No.1555 4 retensi, jenis arsip, dan keterangan yang berisi rekomendasi tentang penetapan suatu jenis arsip dimusnahkan, dinilai kembali, atau dipermanenkan yang dipergunakan sebagai acuan penyusutan dan penyelamatan arsip.
11. Jenis Arsip adalah unit-unt berkas yang di cipta, di atur dan di kelola sebagai suatu unit karena berhubungan secara fungsi atau subyek, merupakan hasil dari kegiatan yang sama.
12. Jangka Waktu Simpan adalah masa simpan minimal suatu jenis arsip pada Unit Pengolah dan/atau Unit Kearsipan.
13. Jangka Waktu Simpan Aktif adalah masa simpan minimal suatu jenis arsip pada Unit Pengolah.
14. Jangka Waktu Simpan lnaktif adalah masa simpan minimal suatu jenis arsip pada Unit Kearsipan/Pusat Arsip.
15. Keterangan Musnah adalah keterangan yang menyatakan bahwaarsip dapat dimusnahkan karena jangka waktu penyimpanan telah selesai dan tidak memiliki nilai guna lagi.
16. Keterangan Permanen adalah keterangan yang menyatakan bahwa arsip memiliki nilai guna sekunder, wajib diserahkan kepada Arsip Nasional Republik lndonesia/Lembaga Kearsipan sesuai dengan lingkup kewenangan masing-masing.
17. Keterangan Dinilai Kembaliadalah keterangan yang menyatakan bahwa suatu jenis arsip belum dapat ditentukan nasib akhirnya apakah musnah atau permanen, sehingga perlu dilakukan penilaian dan pengkajian lagi.
18. Pejabat Negara adalah pimpinan dan anggota lembaga negara dan pejabat lainnya berdasarkan ketentuan peraturan perundang-undangan.
19. Pegawai Negeri Sipil adalah Pegawai Negeri Sipil sebagaimana dimaksud dalam Undang-Undang Nomor 8 Tahun 1974 tentang Pokok-pokok Kepegawaian sebagaimana telah di ubah dengan Undang-Undang Nomor 43 Tahun 1999.
20. Jadwal Retensi Arsip Kepegawaian adalah jadwal retensi arsip mengenai arsip Pegawai Negeri Sipil dan Pejabat Negara.
21. Berkas Perseorangan adalah arsip yang tercipta dalam rangka perjalanan karier Pegawai Negeri Sipil di Lembaga-lembaga Negara dan Badan-badan Pemerintah.
22. Arsip Dokumentasi Kepegawaian adalah arsip yang tercipta dalam rangka perjalanan karier Pegawai Negeri yang tercipta dalam proses pembinaan kepegawaian oleh pejabat yang berwenang.
5 2014, No.1555
23. Data Kepegawaian adalah informasi mengenai perkembangan karier Pegawai Negeri Sipil yang di susun berdasarkan arsip dokumentasi kepegawaian dari instansi yang bersangkutan.
24. Jadwal Retensi Arsip Pejabat Negara, adalah jadwal retensi arsip mengenai arsip orang perseorangan yang merupakan rekaman perjalanan karier Pegawai Negeri/non Pegawai Negeri yang di angkat sebagai pejabat Negara.
25. Penyelenggaraan kearsipan adalah keseluruhan kegiatan meliputi kebijakan, pembinaan kearsipan, dan pengelolaan arsip dalam suatu sistem kearsipan nasional yang didukung oleh sumber daya manusia, prasarana dan sarana, serta sumber daya lainnya.
26. Pengelolaan Arsip Dinamis adalah proses pengendalian arsip dinamis secara efisien, efektif, dan sistematis meliputi penciptaan, penggunaan dan pemeliharaan, serta penyusutan arsip.
27. Unit Pengolah adalah satuan kerja pada pencipta arsip yang mempunyai tugas dan tanggung jawab mengolah semua arsip yang berkaitan dengan kegiatan penciptaan arsip dilingkungannya.
28. Unit Kearsipan adalah satuan ke a pada pencipta arsip yang mempunyai tugas dan tanggung jawab dalam penyelenggaraan kearsipan.
29. Penyusutan arsip adalah kegiatan pengurangan jumlah arsip dengan cara pemindahan arsip inaktif dari unit pengolah ke unit kearsipan, pemusnahan arsip yang tidak memiliki nilai guna, dan penyerahan arsip statis kepada lembaga kearsipan.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2010 tentang Jadwal Retensi Arsip Kepegawaian Pegawai Negeri Sipil dan Pejabat Negara Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7924, 'perka-26-2010', 5, 'pasal', 'Pasal 2', NULL, 5, 'Jadwal Retensi Arsip Kepegawaian Pegawai Negeri Sipil dan Pejabat Negara Badan Nasional Penanggulangan Bencana, sebagaimana tercantum dalam Lampiran Peraturan ini merupakan bagian yang tidak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7924, 'Jadwal Retensi Arsip Kepegawaian Pegawai Negeri Sipil dan Pejabat Negara Badan Nasional Penanggulangan Bencana, sebagaimana tercantum dalam Lampiran Peraturan ini merupakan bagian yang tidak terpisahkan dari Peraturan ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2010 tentang Jadwal Retensi Arsip Kepegawaian Pegawai Negeri Sipil dan Pejabat Negara Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7925, 'perka-26-2010', 6, 'pasal', 'Pasal 3', NULL, 5, 'Jadwal Retensi Arsip sebagaimana dimaksud pada Pasal 2 merupakan acuan penyusutan arsip yang berkaitan dengan arsip kepegawaian Pegawai Negeri Sipil dan Pejabat Negara di lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7925, 'Jadwal Retensi Arsip sebagaimana dimaksud pada Pasal 2 merupakan acuan penyusutan arsip yang berkaitan dengan arsip kepegawaian Pegawai Negeri Sipil dan Pejabat Negara di lingkungan Badan Nasional Penanggulangan Bencana.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2010 tentang Jadwal Retensi Arsip Kepegawaian Pegawai Negeri Sipil dan Pejabat Negara Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7926, 'perka-26-2010', 7, 'pasal', 'Pasal 4', NULL, 5, 'Bentuk dan susunan Jadwal Retensi Arsip Kepegawaian Pegawai Negeri Sipil dan Pejabat Negara Badan Nasional Penanggulangan Bencana sebagaimana di maksud dalam Pasal 2 meliputi: kolom nomor, jenis dokumen/arsip, jangka waktu simpan dan keterangan yang berisi pernyataan musnah, permanen atau dinilai kembali.
