INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7928, 'Peraturan Kepala ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2010 tentang Jadwal Retensi Arsip Kepegawaian Pegawai Negeri Sipil dan Pejabat Negara Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7929, 'perka-26-2010', 10, 'lain', 'Penutup', NULL, 6, 'Ditetapkan di Jakarta pada tanggal 31 Desember 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 14 Oktober 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7929, 'Ditetapkan di Jakarta pada tanggal 31 Desember 2010 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 14 Oktober 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2010 tentang Jadwal Retensi Arsip Kepegawaian Pegawai Negeri Sipil dan Pejabat Negara Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7930, 'perka-26-2014', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2014 tentang Pemanfaatan Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7930, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2014 tentang Pemanfaatan Bantuan Logistik Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2014 tentang Pemanfaatan Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7931, 'perka-26-2014', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa kondisi Indonesia secara geografis dan struktur geologi terletak pada kawasan rawan bencana, sehingga sering terjadi bencana gempa bumi, tsunami, gunung meletus, banjir, kekeringan, angin topan, dan tanah longsor. Untuk mengantisipasi bencana tersebut diperlukan dukungan logistik sebagai pemenuhan dasar;
b. bahwa pemanfaatan bantuan logistik penanggulangan bencana perlu diatur pemanfaatan bagi BNPB, BPBD, Instansi/Lembaga dan pemangku kepentingan penanggulangan bencana agar dapat dilaksanakan dengan lancar, tertib, terpadu, aman, dan dapat dipertanggungjawabkan;
c. bahwa berdasarkan pertimbangan sebagaimana di maksud huruf a dan huruf b, perlu menetapkan peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Pemanfaatan Bantuan Logistik Penanggulangan Bencana 2014, No.2083 2');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7931, 'a. bahwa kondisi Indonesia secara geografis dan struktur geologi terletak pada kawasan rawan bencana, sehingga sering terjadi bencana gempa bumi, tsunami, gunung meletus, banjir, kekeringan, angin topan, dan tanah longsor. Untuk mengantisipasi bencana tersebut diperlukan dukungan logistik sebagai pemenuhan dasar;
b. bahwa pemanfaatan bantuan logistik penanggulangan bencana perlu diatur pemanfaatan bagi BNPB, BPBD, Instansi/Lembaga dan pemangku kepentingan penanggulangan bencana agar dapat dilaksanakan dengan lancar, tertib, terpadu, aman, dan dapat dipertanggungjawabkan;
c. bahwa berdasarkan pertimbangan sebagaimana di maksud huruf a dan huruf b, perlu menetapkan peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Pemanfaatan Bantuan Logistik Penanggulangan Bencana 2014, No.2083 2', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2014 tentang Pemanfaatan Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7932, 'perka-26-2014', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
