INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7937, 'perka-26-2014', 7, 'pasal', 'Pasal 4', NULL, 4, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7937, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2014 tentang Pemanfaatan Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7938, 'perka-26-2014', 8, 'lain', 'Penutup', NULL, 4, 'Ditetapkan di Jakarta pada tanggal, 1 Desember 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal, 31 Desember 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY 5 2014, No.2083');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7938, 'Ditetapkan di Jakarta pada tanggal, 1 Desember 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal, 31 Desember 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY 5 2014, No.2083', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2014 tentang Pemanfaatan Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7939, 'perka-26-2014', 9, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 26 TAHUN 2014 TENTANG PEDOMAN PEMANFAATAN BANTUAN LOGISTIK PENANGGULANGAN BENCANA PEDOMAN PEMANFAATAN BANTUAN LOGISTIK PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. LATAR BELAKANG Kondisi Indonesia secara geografis dan struktur geologi terletak pada kawasan rawan bencana, sehingga sering terjadi bencana gempa bumi, banjir, tanah longsor, badai, tsunami, kebakaran hutan dan lahan, dan lain lain. Oleh karena itu untuk mengantisipasi bencana tersebut diperlukan dukungan logistik sebagai pemenuhan dasar.
Pemerintah Indonesia, melalui Badan Nasional Penanggulangan Bencana (BNPB) dan atau Badan Penanggulangan Bencana Daerah (BPBD) menyadari tantangan yang dihadapi dalam membangun ketangguhan bangsa mengingat tingkat kerentanan masyarakat terhadap bencana dan pentingnya kerja sama berbagai pihak untuk memainkan perannya secara konstruktif dan berkelanjutan untuk menghadapi berbagai ancaman bencana baik yang disebabkan alam maupun manusia, letak geografis dan karakteristiknya, serta fenomena perubahan iklim, membutuhkan dukungan dari berbagai elemen masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7939, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 26 TAHUN 2014 TENTANG PEDOMAN PEMANFAATAN BANTUAN LOGISTIK PENANGGULANGAN BENCANA PEDOMAN PEMANFAATAN BANTUAN LOGISTIK PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. LATAR BELAKANG Kondisi Indonesia secara geografis dan struktur geologi terletak pada kawasan rawan bencana, sehingga sering terjadi bencana gempa bumi, banjir, tanah longsor, badai, tsunami, kebakaran hutan dan lahan, dan lain lain. Oleh karena itu untuk mengantisipasi bencana tersebut diperlukan dukungan logistik sebagai pemenuhan dasar.
Pemerintah Indonesia, melalui Badan Nasional Penanggulangan Bencana (BNPB) dan atau Badan Penanggulangan Bencana Daerah (BPBD) menyadari tantangan yang dihadapi dalam membangun ketangguhan bangsa mengingat tingkat kerentanan masyarakat terhadap bencana dan pentingnya kerja sama berbagai pihak untuk memainkan perannya secara konstruktif dan berkelanjutan untuk menghadapi berbagai ancaman bencana baik yang disebabkan alam maupun manusia, letak geografis dan karakteristiknya, serta fenomena perubahan iklim, membutuhkan dukungan dari berbagai elemen masyarakat.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2014 tentang Pemanfaatan Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7940, 'perka-26-2014', 10, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'Bantuan logistik baik pada saat pra bencana/ kesiapsiagaan pada saat status keadaan darurat sangat penting dalam penanggulangan bencana, terutama untuk penanganan korban bencana. Logistik yang diperlukan, antara lain family kits, kidware, sandang, paket kebersihan, tikar, selimut , matras, dan lain-lain. Bantuan logistik tersebut harus didistribusi dengan cepat, tepat waktu, tepat lokasi, tepat sasaran, tepat jumlah, dan dapat dipertangungjawabkan.
Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, khususnya Pasal 6 dan pasal 8 telah mengamanatkan bahwa tanggung jawab Pemerintah dan Pemerintah Daerah dalam penyelenggaraan penanggulangan bencana antara lain adalah perlindungan masyarakat dari dampak bencana. Oleh karena 2014, No.2083 6 itu Pemerintah dan Pemerintah Daerah perlu melakukan kesiapsiagaan yang memadai dalam menghadapi bencana, salah satunya adalah menyiapkan bantuan logistik yang siap didistribusi untuk membantu meringankan penderitaan korban bencana.
Badan Nasional Penaggulangan Bencana (BNPB) telah berupaya memberikan dukungan logistik untuk kesiapsiagaan dan penguatan kelembagaan Badan Penanggulangan Bencana Daerah (BPBD), khususnya dalam rangka pemenuhan kebutuhan standar minimal logistik. Logistik dari BNPB hanya bersifat stimulan, sehingga daerah diharapkan daerah akan lebih berperan dalam pemenuhan kebutuhan logistik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7940, 'Bantuan logistik baik pada saat pra bencana/ kesiapsiagaan pada saat status keadaan darurat sangat penting dalam penanggulangan bencana, terutama untuk penanganan korban bencana. Logistik yang diperlukan, antara lain family kits, kidware, sandang, paket kebersihan, tikar, selimut , matras, dan lain-lain. Bantuan logistik tersebut harus didistribusi dengan cepat, tepat waktu, tepat lokasi, tepat sasaran, tepat jumlah, dan dapat dipertangungjawabkan.
Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, khususnya Pasal 6 dan pasal 8 telah mengamanatkan bahwa tanggung jawab Pemerintah dan Pemerintah Daerah dalam penyelenggaraan penanggulangan bencana antara lain adalah perlindungan masyarakat dari dampak bencana. Oleh karena 2014, No.2083 6 itu Pemerintah dan Pemerintah Daerah perlu melakukan kesiapsiagaan yang memadai dalam menghadapi bencana, salah satunya adalah menyiapkan bantuan logistik yang siap didistribusi untuk membantu meringankan penderitaan korban bencana.
Badan Nasional Penaggulangan Bencana (BNPB) telah berupaya memberikan dukungan logistik untuk kesiapsiagaan dan penguatan kelembagaan Badan Penanggulangan Bencana Daerah (BPBD), khususnya dalam rangka pemenuhan kebutuhan standar minimal logistik. Logistik dari BNPB hanya bersifat stimulan, sehingga daerah diharapkan daerah akan lebih berperan dalam pemenuhan kebutuhan logistik.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2014 tentang Pemanfaatan Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7941, 'perka-26-2014', 11, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'Bantuan logistik penanggulangan bencana yang telah diberikan tersebut dirasakan masih kurang dari standart minimal yang harus dimiliki daerah. Oleh karena itu diharapkan daerah memilikki kemampuan untuk memunuhi standar minimal daerahnya. Salah satu unsur yang harus diperhatikan dalam hal logistik adalah cara penanganan agar terjamin mutunya, pemanfaatannya dan pengolongannya.
Untuk dapat menggunakan dan memanfaatkan logistik penanggulangan bencana secara maksimal, maka perlu disusun petunjuk pelaksaanaan pemanfatan logistik penanggulangan bencana, yang sederhana dan dapat dipahami oleh pemangku kepentingan serta orang umum lainnya.
B. MAKSUD DAN TUJUAN
1. Maksud dari petunjuk pelaksanaan ini adalah sebagai panduan bagi BNPB, BPBD dan pemangku kepentingan terkait, dalam pemanfaatan persediaan logistik pada situasi pra bencana dan keadaan darurat.
2. Tujuan dari petunjuk pelaksanaan ini adalah:
a. Agar persediaan Logistik dapat digunakan secara benar, efektif, efisien dan tepat sasaran.
b. Menjaga jumlah dan mutu sehingga bermanfaat pada saat diperlukan.
c. Penggunaan yang transparan dan akuntabel.
C. LANDASAN HUKUM
1. Undang-undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negera Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana;
7 2014, No.2083');
