INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7942, '3. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana;
4. Keputusan Presiden Nomor 80 Tahun 2003 tentang Pedoman Pelaksanaan Pengadaan Barang / Jasa Pemerintah;
