INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7943, 'perka-26-2014', 13, 'lampiran', 'Lampiran hal. 7', NULL, 7, '1. Ruang Lingkup Petunjuk pelaksanaan pemanfaatan persediaan logistik ini meliputi pemanfaatan logistik pada saat situasi pra bencana dan keadaan darurat.
2. Sistematika Petunjuk pelaksaanaan pemanfatan logistik penanggulangan bencana ini disusun dengan sistematika sebagai berikut:
BAB I PENDAHULUAN BAB II PEMANFAATAN LOGISTIK BAB III PENGAWASAN DAN PENGENDALIAN BAB IV PENUTUP LAMPIRAN 2014, No.2083 8 E. PENGERTIAN
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, serta kegiatan rehabilitasi dan rekonstruksi.
3. Logistik adalah segala sesuatu yang berwujud yang dapat digunakan untuk memenuhi suatu kebutuhan dasar manusia yang habis pakai terdiri atas pangan, sandang dan papan atau turunannya. Termasuk dalam kategori logistik adalah barang yang habis pakai atau dikonsumsi.
4. Persediaan adalah jumlah bahan/barang yang disimpan dan akan digunakan untuk tujuan tertentu.
5. Pemanfaatan logistik bencana adalah penggunaan bahan/barang yang disimpan untuk tujuan atau kegiatan yang berhubungan dengan penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7943, '1. Ruang Lingkup Petunjuk pelaksanaan pemanfaatan persediaan logistik ini meliputi pemanfaatan logistik pada saat situasi pra bencana dan keadaan darurat.
2. Sistematika Petunjuk pelaksaanaan pemanfatan logistik penanggulangan bencana ini disusun dengan sistematika sebagai berikut:
BAB I PENDAHULUAN BAB II PEMANFAATAN LOGISTIK BAB III PENGAWASAN DAN PENGENDALIAN BAB IV PENUTUP LAMPIRAN 2014, No.2083 8 E. PENGERTIAN
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, serta kegiatan rehabilitasi dan rekonstruksi.
3. Logistik adalah segala sesuatu yang berwujud yang dapat digunakan untuk memenuhi suatu kebutuhan dasar manusia yang habis pakai terdiri atas pangan, sandang dan papan atau turunannya. Termasuk dalam kategori logistik adalah barang yang habis pakai atau dikonsumsi.
4. Persediaan adalah jumlah bahan/barang yang disimpan dan akan digunakan untuk tujuan tertentu.
5. Pemanfaatan logistik bencana adalah penggunaan bahan/barang yang disimpan untuk tujuan atau kegiatan yang berhubungan dengan penanggulangan bencana.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2014 tentang Pemanfaatan Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7944, 'perka-26-2014', 14, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'BAB II PEMANFAATAN LOGISTIK Pemanfaatan logistik bencana diselenggarakan berdasarkan kebutuhan keadaan pra bencana dan keadaan darurat, meliputi:
A. Perencanaan.
Perencanaan Pemanfaatan Logistik dimaksudkan untuk mengetahui dan memenuhi kebutuhan logistik pra bencana dan keadaan darurat.
1. Pra Bencana.
a. Logistik diberikan berdasarkan permintaan BPBD propinsi, kabupaten/kota secara berjenjang. Permintaan ini dibuat dalam bentuk proposal yang berisi antara lain:
1) Letak geografi dan kondisi demografi, 2) Data kejadian bencana, dan data stok logistik akhir, 3) Jenis dan jumlah kebutuhan logistik.
4) Rekomendasi atau surat pengantar kepala daerah.
b. Permintaan ini diverifikasi dan dianalisis secara berjenjang oleh BNPB dan atau BPBD propinsi sebelum dilaksanakan pengiriman.
9 2014, No.2083
c. Logistik diberikan atas inisiatif BNPB atau BPBD Propinsi berdasarkan analisis/telaah kebutuhan sesuai kondisi, dengan:
1) Mempelajari kejadian bencana yang pernah ada, 2) Penilaian kebutuhan daerah atau 3) Sesuai Pedoman Standarisasi Logistik.
2. Darurat.
a. Logistik diberikan berdasarkan Laporan Kejadian Bencana dan Permintaan BPBD atau Kepala Daerah, Kaji Cepat TRC, Keputusan hasil rapat Posko tanggap darurat atau inisiatif BNPB dan atau BPBD.
b. Permintaan diatas harus dipersiapkan dan diverifikasi oleh BNPB dan atau BPBD sebelum dilaksanakan pengirimannya.
c. Logistik diberikan atas inisiatif BNPB atau BPBD Propinsi berdasarkan :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7944, 'BAB II PEMANFAATAN LOGISTIK Pemanfaatan logistik bencana diselenggarakan berdasarkan kebutuhan keadaan pra bencana dan keadaan darurat, meliputi:
A. Perencanaan.
Perencanaan Pemanfaatan Logistik dimaksudkan untuk mengetahui dan memenuhi kebutuhan logistik pra bencana dan keadaan darurat.
1. Pra Bencana.
a. Logistik diberikan berdasarkan permintaan BPBD propinsi, kabupaten/kota secara berjenjang. Permintaan ini dibuat dalam bentuk proposal yang berisi antara lain:
1) Letak geografi dan kondisi demografi, 2) Data kejadian bencana, dan data stok logistik akhir, 3) Jenis dan jumlah kebutuhan logistik.
4) Rekomendasi atau surat pengantar kepala daerah.
b. Permintaan ini diverifikasi dan dianalisis secara berjenjang oleh BNPB dan atau BPBD propinsi sebelum dilaksanakan pengiriman.
9 2014, No.2083
c. Logistik diberikan atas inisiatif BNPB atau BPBD Propinsi berdasarkan analisis/telaah kebutuhan sesuai kondisi, dengan:
1) Mempelajari kejadian bencana yang pernah ada, 2) Penilaian kebutuhan daerah atau 3) Sesuai Pedoman Standarisasi Logistik.
2. Darurat.
a. Logistik diberikan berdasarkan Laporan Kejadian Bencana dan Permintaan BPBD atau Kepala Daerah, Kaji Cepat TRC, Keputusan hasil rapat Posko tanggap darurat atau inisiatif BNPB dan atau BPBD.
b. Permintaan diatas harus dipersiapkan dan diverifikasi oleh BNPB dan atau BPBD sebelum dilaksanakan pengirimannya.
c. Logistik diberikan atas inisiatif BNPB atau BPBD Propinsi berdasarkan :', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2014 tentang Pemanfaatan Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7945, 'perka-26-2014', 15, 'lampiran', 'Lampiran hal. 9', NULL, 9, '1) Informasi media massa yang dapat dipertanggungjawabkan 2) Instruksi Presiden, Gubernur, Bupati dan atau Walikota sesuai tingkatan.
3) Laporan perkembangan situasi dari instansi yang berwenang.
B. Pelaksanaan.
Pemanfaatan Logistik dimaksudkan untuk pemenuhan kebutuhan dasar yang dapat dilaksanakan lebih efektif dan efisien.
1. Situasi Pra Bencana.
a. Logistik yang diberikan dimaksudkan sebagai penyangga (buffer stock) agar kesiapan penanggulangan bencana lebih efektif dan efisien.
b. Logistik yang berada di BPBD Propinsi dan kabupaten/kota pada prinsipnya dipergunakan hanya untuk keadaan darurat bencana, namun apabila dipandang perlu dapat dimanfaatkan pada masa pra bencana sesuai dengan peraturan dan perundang-undangan.
c. Pemanfaatan logistik pada masa pra bencana untuk kebutuhan lain yang menunjang kegiatan kebencanaan diatur tersendiri atau atas persetujuan BNPB.
1) Logistik kategori pangan dapat dimanfaatkan apabila mendekati masa kadaluarsa (2 bulan sebelumnya).
2) Logistik kategori non pangan yang tidak ada masa kadaluarsanya tidak boleh digunakan untuk kegiatan ini kecuali ada kebijaksanaan khusus dari BNPB.
2014, No.2083 10 3) Logistik kategori non pangan yang sudah ada tanda-tanda perubahan dari spesifikasi awal, harus segera dimanfaatkan untuk menghindari terjadinya kerusakan lebih lanjut. (seizin BNPB) 4) Pengajuan pemanfaatan harus disertai dengan data persediaan/buffer stock.
2. Situasi Darurat Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7945, '1) Informasi media massa yang dapat dipertanggungjawabkan 2) Instruksi Presiden, Gubernur, Bupati dan atau Walikota sesuai tingkatan.
3) Laporan perkembangan situasi dari instansi yang berwenang.
B. Pelaksanaan.
Pemanfaatan Logistik dimaksudkan untuk pemenuhan kebutuhan dasar yang dapat dilaksanakan lebih efektif dan efisien.
1. Situasi Pra Bencana.
a. Logistik yang diberikan dimaksudkan sebagai penyangga (buffer stock) agar kesiapan penanggulangan bencana lebih efektif dan efisien.
b. Logistik yang berada di BPBD Propinsi dan kabupaten/kota pada prinsipnya dipergunakan hanya untuk keadaan darurat bencana, namun apabila dipandang perlu dapat dimanfaatkan pada masa pra bencana sesuai dengan peraturan dan perundang-undangan.
c. Pemanfaatan logistik pada masa pra bencana untuk kebutuhan lain yang menunjang kegiatan kebencanaan diatur tersendiri atau atas persetujuan BNPB.
1) Logistik kategori pangan dapat dimanfaatkan apabila mendekati masa kadaluarsa (2 bulan sebelumnya).
2) Logistik kategori non pangan yang tidak ada masa kadaluarsanya tidak boleh digunakan untuk kegiatan ini kecuali ada kebijaksanaan khusus dari BNPB.
2014, No.2083 10 3) Logistik kategori non pangan yang sudah ada tanda-tanda perubahan dari spesifikasi awal, harus segera dimanfaatkan untuk menghindari terjadinya kerusakan lebih lanjut. (seizin BNPB) 4) Pengajuan pemanfaatan harus disertai dengan data persediaan/buffer stock.
2. Situasi Darurat Bencana', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 26 Tahun 2014 tentang Pemanfaatan Bantuan Logistik Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7946, 'perka-26-2014', 16, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'a. Logistik diberikan sebagai dukungan untuk pemenuhan kebutuhan dasar masyarakat yang terkena dampak bencana pada saat status keadaan darurat.
b. Pemanfaatan logistik dalam keadaan darurat bencana dimanfaatkan dengan mengutamakan kelompok rentan.
BAB III PENGAWASAN DAN PENGENDALIAN.
A. Pengawasan.
Pengawasan dimaksudkan agar pemanfaatan logistik dapat dipertanggungjawabkan sesuai dengan peraturan dan perundang-undangan.
1. Pengawasan dilakukan oleh instansi yang berwenang secara internal oleh inspektorat utama, maupun secara eksternal oleh BPKP, Bawasda dan yang lain sesuai dengan tingkat kewenanganya.
2. Evaluasi dilaksanakan sejak perencanaan sampai dengan pelaksanaan pemanfaatan.
B. Pengendalian.
1. Pengendalian dilakukan secara berjenjang sesuai dengan tanggung jawab dan wewenang instansi yang bersangkutan.
2. Pengendalian dilakukan sejak perencanaan sampai dengan pelaksanaan pemanfaatan melalui Pemantauan, Pengarahan dan Bimbingan.
3. Pengendalian dilakukan untuk mengetahui kekurangan atau kelebihan dan penyebab Pemanfaatan Logistik agar sesuai dengan perencanaan pemanfaatan.
4. Pelaksanaan pengendalian dilakukan sesuai dengan peraturan dan perundangan.
11 2014, No.2083 BAB IV PENUTUP Pedoman pemanfatan bantuan logistik dimaksudkan sebagai pedoman dalam rangka pemanfaatan bantuan logistik dalam situasi kesiapsiagaan dan tanggap darurat dengan sumber pendanaan dari APBN. Diharapkan pedoman ini dapat dilaksanakan secara efektif, efisien dan tepat sasaran.');
