INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7947, 'perka-26-2014', 17, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'Sesuai dengan perkembangannya, pedoman ini terbuka untuk diperbaiki.
