INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7951, 'perka-3-2008', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN PEMBENTUKAN BADAN PENANGGULANGAN BENCANA DAERAH.');
