INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7952, 'perka-3-2008', 4, 'pasal', 'Pasal 1', NULL, 2, 'Pedoman Pembentukan Badan Penanggulangan Bencana Daerah merupakan panduan/acuan bagi Pemerintah Provinsi dan Pemerintah Kabupaten/Kota dalam menyusun Peraturan Daerah tentang Pembentukan Badan Penanggulangan Bencana Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7952, 'Pedoman Pembentukan Badan Penanggulangan Bencana Daerah merupakan panduan/acuan bagi Pemerintah Provinsi dan Pemerintah Kabupaten/Kota dalam menyusun Peraturan Daerah tentang Pembentukan Badan Penanggulangan Bencana Daerah.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008 tentang Pedoman Pembentukan Badan Penanggulangan Bencana Daerah');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7953, 'perka-3-2008', 5, 'pasal', 'Pasal 2', NULL, 2, 'Pedoman dimaksud dalam Pasal 1Isebagaimana tercantum dalam lampiran, merupakan bagian tak terpisahkan dari Peraturan ini.
