INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7953, 'Pedoman dimaksud dalam Pasal 1Isebagaimana tercantum dalam lampiran, merupakan bagian tak terpisahkan dari Peraturan ini.
