INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7974, 'perka-3-2008', 26, 'lampiran', 'Lampiran hal. 18', NULL, 18, '5. Laporan penyelenggaraan penanggulangan bencana meliputi kegiatan-kegiatan yang dilakukan pada prabencana, saat tanggap darurat dan pascabencana yang dibuat setiap bulan dan setiap tahun.
6. Laporan penerimaan dan penyaluran bantuan yang berasal dari sumbangan masyarakat.
