INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7979, 'perka-3-2013', 2, 'mengingat', 'Mengingat', NULL, 1, '(1) Peraturan Pemerintah Republik Indonesia Nomor 22 Tahun 2008 tentang Pendanaan Dan Pengelolaan Bantuan Bencana diperlukan Petunjuk Teknis Pelaksanaan Anggaran Kegiatan Rehabilitasi dan Rekonstruksi Wilayah Pascabencana;
1. Undang-Undang N omor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);
2. Undang-Undang Nomor 24 Tahun 2007 tentang 2013, No.1440 2 Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
