INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7994, 'perka-3-2014', 8, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 4 Februari 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 26 Februari 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.252 4 LAMPIRAN I PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 3 TAHUN 2014 TENTANG PETUNJUK PELAKSANAAN OPERASIONAL GUDANG PERALATAN PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan negara yang rawan bencana, baik berupa bencana alam (banjir, gempa bumi, gunung berapi, tsunami maupun longsor), bencana non alam (kegagalan teknologi, gagal modernisasi,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7994, 'Ditetapkan di Jakarta pada tanggal 4 Februari 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 26 Februari 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.252 4 LAMPIRAN I PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 3 TAHUN 2014 TENTANG PETUNJUK PELAKSANAAN OPERASIONAL GUDANG PERALATAN PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan negara yang rawan bencana, baik berupa bencana alam (banjir, gempa bumi, gunung berapi, tsunami maupun longsor), bencana non alam (kegagalan teknologi, gagal modernisasi,', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7995, 'perka-3-2014', 9, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'epidemic, dan wabah penyakit) maupun bencana sosial (konflik sosial).
Kondisi ini bila tidak diantisipasi maka jumlah korban diperkirakan akan banyak. Salah satu upaya untuk mengantisipasi hal tersebut pada saat ini hampir semua kabupaten / kota yang rawan dengan ancaman bencana telah membentuk BPBD.
Praktis hal ini juga berdampak terhadap kebutuhan akan ketersediaan logistik dan peralatan baik untuk kesiapsiagaan maupun situasi tanggap darurat. Permintaan yang tinggi terhadap ketersediaan peralatan ini menjadi dasar utama bagi Deputi Bidang Logistik dan Peralatan untuk pengadaan, sekaligus menyusun suatu aturan pengelolaan peralatan dimaksud. Saat ini kebutuhan peralatan masih sebatas pemenuhan peralatan minimal seperti, Peralatan Kendaraan (mobil rescue, mobil ambulans, mobil truk serbaguna, mobil dapur lapangan, mobil pengolah air bersih, mobil komunikasi, motor trail, perahu karet, mesin perahu), Peralatan hunian (Tenda posko, tenda pengungsi, tenda keluarga, genset, Velbed, dan pengolahan air minum) serta peralatan komunikasi (handy talky, rig, dan Single Side Band / SSB). Namun kedepan pengadaan peralatan harus menjangkau kebutuhan yang disesuaikan dengan jenis bencana seperti banjir, gempa bumi, gunung berapi, tsunami maupun lonsor. Semua ini perlu manajemen/pengelolaan yang khusus terhadap peralatan dimaksud yang dapat dipergunakan baik di tingkat pusat, Propinsi maupun Kabupaten/Kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7995, 'epidemic, dan wabah penyakit) maupun bencana sosial (konflik sosial).
Kondisi ini bila tidak diantisipasi maka jumlah korban diperkirakan akan banyak. Salah satu upaya untuk mengantisipasi hal tersebut pada saat ini hampir semua kabupaten / kota yang rawan dengan ancaman bencana telah membentuk BPBD.
Praktis hal ini juga berdampak terhadap kebutuhan akan ketersediaan logistik dan peralatan baik untuk kesiapsiagaan maupun situasi tanggap darurat. Permintaan yang tinggi terhadap ketersediaan peralatan ini menjadi dasar utama bagi Deputi Bidang Logistik dan Peralatan untuk pengadaan, sekaligus menyusun suatu aturan pengelolaan peralatan dimaksud. Saat ini kebutuhan peralatan masih sebatas pemenuhan peralatan minimal seperti, Peralatan Kendaraan (mobil rescue, mobil ambulans, mobil truk serbaguna, mobil dapur lapangan, mobil pengolah air bersih, mobil komunikasi, motor trail, perahu karet, mesin perahu), Peralatan hunian (Tenda posko, tenda pengungsi, tenda keluarga, genset, Velbed, dan pengolahan air minum) serta peralatan komunikasi (handy talky, rig, dan Single Side Band / SSB). Namun kedepan pengadaan peralatan harus menjangkau kebutuhan yang disesuaikan dengan jenis bencana seperti banjir, gempa bumi, gunung berapi, tsunami maupun lonsor. Semua ini perlu manajemen/pengelolaan yang khusus terhadap peralatan dimaksud yang dapat dipergunakan baik di tingkat pusat, Propinsi maupun Kabupaten/Kota.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7996, 'perka-3-2014', 10, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'Dalam rangka pengelolaan pergudangan penanggulangan bencana telah ditetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan Penanggulangan Bencana. Namun secara operasional, perlu disusun petunjuk pelaksanaan operasional pergudangan, agar dapat berjalan secara tertib, teratur dan akuntabel.
5 2014, No.252 Petunjuk pelaksanaan ini akan menjadi acuan bagi personil BNPB dan BPBD yang mengelola peralatan penanggulangan bencana, sehingga kedepan diharapkan petugas pergudangan dapat menjalankan tugasnya sesuai dengan panduan mulai dari organisasi, sistem penerimaan, penyimpanan, pemeriksaan, pemeliharaan, pendistribusian, pengangkutan, pengendalian dan pelaporan serta sistem informasi dan komputerisasi administrasi pergudangan.
B. Maksud dan Tujuan Maksud petunjuk pelaksanaan ini adalah sebagai panduan bagi pemangku kepentingan dalam mengelola pergudangan baik pusat maupun daerah.
Tujuan petunjuk pelaksanaan ini adalah mewujudkan:
1. Tertib Administrasi pergudangan;
2. Terjaganya kuantitas dan kualitas peralatan;
3. Tertatanya peralatan;
4. Tersedianya data dan informasi yang akurat, aktual dan akuntabel.
C. Landasan Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana;
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana;
3. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana;');
