INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7998, 'perka-3-2014', 12, 'lampiran', 'Lampiran hal. 6', NULL, 6, '1. Operasional adalah proses pengelolaan gudang mulai dari penerimaan, penyimpanan, pemeliharaan, pengeluaran, sampai dengan pelaporan.
2. Pergudangan adalah segala upaya pengelolaan gudang yang meliputi penerimaan, penyimpanan, pemeliharaan, pengeluaran, dan pelaporan peralatan penanggulangan bencana agar kualitas dan kuantitas tetap terjamin.
3. Peralatan adalah segala bentuk alat yang dapat dipergunakan untuk membantu pencarian, penyelamatan dan evakuasi masyarakat yang terkena bencana, membantu pemenuhan kebutuhan dasar dan untuk pemulihan segera prasarana dan sarana vital. Peralatan merupakan barang aset yang harus tercatat dalam Barang Milik Negara / Barang Milik Daerah.
4. Stock Opname adalah proses pemeriksaaan jenis, jumlah dan kondisi barang persediaan (stok) di gudang, yang dilakukan oleh pengelola gudang bersama-sama dengan Pimpinan BNPB/BPBD yang berwenang.
5. Kartu Stok adalah kartu yang mencatat posisi jumlah, jenis, dan informasi mengenai suatu barang yang tersimpan di gudang.
6. Kartu Pemeliharaan Barang adalah kartu yang digunakan untuk mencatat tahapan dan tanggal dalam proses pemeliharaan suatu barang, baik berupa kerusakan ataupun penggantian suku cadang.
7. Lay out gudang adalah gambar / sketsa gudang yang menyangkut tata letak ruangan dan rencana penempatan barang.
7 2014, No.252
8. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB adalah lembaga pemerintah non-kementrian sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7998, '1. Operasional adalah proses pengelolaan gudang mulai dari penerimaan, penyimpanan, pemeliharaan, pengeluaran, sampai dengan pelaporan.
2. Pergudangan adalah segala upaya pengelolaan gudang yang meliputi penerimaan, penyimpanan, pemeliharaan, pengeluaran, dan pelaporan peralatan penanggulangan bencana agar kualitas dan kuantitas tetap terjamin.
3. Peralatan adalah segala bentuk alat yang dapat dipergunakan untuk membantu pencarian, penyelamatan dan evakuasi masyarakat yang terkena bencana, membantu pemenuhan kebutuhan dasar dan untuk pemulihan segera prasarana dan sarana vital. Peralatan merupakan barang aset yang harus tercatat dalam Barang Milik Negara / Barang Milik Daerah.
4. Stock Opname adalah proses pemeriksaaan jenis, jumlah dan kondisi barang persediaan (stok) di gudang, yang dilakukan oleh pengelola gudang bersama-sama dengan Pimpinan BNPB/BPBD yang berwenang.
5. Kartu Stok adalah kartu yang mencatat posisi jumlah, jenis, dan informasi mengenai suatu barang yang tersimpan di gudang.
6. Kartu Pemeliharaan Barang adalah kartu yang digunakan untuk mencatat tahapan dan tanggal dalam proses pemeliharaan suatu barang, baik berupa kerusakan ataupun penggantian suku cadang.
7. Lay out gudang adalah gambar / sketsa gudang yang menyangkut tata letak ruangan dan rencana penempatan barang.
7 2014, No.252
8. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB adalah lembaga pemerintah non-kementrian sesuai dengan ketentuan peraturan perundang-undangan.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (7999, 'perka-3-2014', 13, 'lampiran', 'Lampiran hal. 7', NULL, 7, '9. Badan Penanggulangan Bencana Daerah, yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah BAB II KRITERIA, TATA KELOLA DAN STRUKTUR PENGELOLA GUDANG PERALATAN Dalam rangka mengoperasionalkan gudang agar berjalan efektif dan efisien diperlukan kriteria, tata kelola dan struktur pengelola gudang peralatan dengan penjelasan sebagai berikut :
A. Kriteria Gudang Gudang peralatan penanggulangan bencana minimal memenuhi persyaratan sebagai berikut :
1. Lokasi yang aman
2. Area yang terbuka
3. Mudah dicapai dengan kendaraan besar
4. Tanah yang tidak terkontaminasi
5. Struktur bangunan yang kuat dan mudah muat bongkar
6. Memiliki kapasitas penyimpanan yang memadai
7. Tersedia jaringan listrik
8. Tersedia fasilitas sanitasi
9. Berventilasi dan kering
10. Bersih B. Tata Kelola Gudang Tata kelola gudang penanggulangan bencana harus memperhatikan hal-hal sebagai berikut :
1. Lay Out Gudang Lay Out gudang merupakan gambar sistematik gudang yang akan dipergunakan di dalam aktivitas sesungguhnya yang akan memberikan kemudahan operasional dan menghindari pekerjaan yang kurang efisien serta menempatkan peralatan/barang sesuai dengan sifat dan karakteristiknya.
Lay out dibuat untuk dijadikan dasar-dasar penempatan 2014, No.252 8 rak/pallet, sarana kerja, jalur kerja dan kelancaran pergerakan manusia dan barang. Contoh lay out gudang dapat dilihat pada lampiran 6.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (7999, '9. Badan Penanggulangan Bencana Daerah, yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah BAB II KRITERIA, TATA KELOLA DAN STRUKTUR PENGELOLA GUDANG PERALATAN Dalam rangka mengoperasionalkan gudang agar berjalan efektif dan efisien diperlukan kriteria, tata kelola dan struktur pengelola gudang peralatan dengan penjelasan sebagai berikut :
A. Kriteria Gudang Gudang peralatan penanggulangan bencana minimal memenuhi persyaratan sebagai berikut :
1. Lokasi yang aman
2. Area yang terbuka
3. Mudah dicapai dengan kendaraan besar
4. Tanah yang tidak terkontaminasi
5. Struktur bangunan yang kuat dan mudah muat bongkar
6. Memiliki kapasitas penyimpanan yang memadai
7. Tersedia jaringan listrik
8. Tersedia fasilitas sanitasi
9. Berventilasi dan kering
10. Bersih B. Tata Kelola Gudang Tata kelola gudang penanggulangan bencana harus memperhatikan hal-hal sebagai berikut :
1. Lay Out Gudang Lay Out gudang merupakan gambar sistematik gudang yang akan dipergunakan di dalam aktivitas sesungguhnya yang akan memberikan kemudahan operasional dan menghindari pekerjaan yang kurang efisien serta menempatkan peralatan/barang sesuai dengan sifat dan karakteristiknya.
Lay out dibuat untuk dijadikan dasar-dasar penempatan 2014, No.252 8 rak/pallet, sarana kerja, jalur kerja dan kelancaran pergerakan manusia dan barang. Contoh lay out gudang dapat dilihat pada lampiran 6.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8000, 'perka-3-2014', 14, 'lampiran', 'Lampiran hal. 8', NULL, 8, '2. Pintu Masuk atau Keluar Barang Pintu masuk atau keluar barang merupakan akses dari luar gudang ke dalam gudang atau sebaliknya. Akses ini merupakan titik penting untuk jaminan keamanan kehilangan barang. Jika memungkinkan, pintu untuk barang dapat dipisahkan dengan pintu untuk petugas. Pemisahan pintu masuk dan pintu keluar untuk memastikan kemudahan didalam penanganan barang dan sekaligus menjamin keamanan barang yang masuk dan keluar serta terpisah dari keluar masuknya petugas.
3. Penyimpanan Barang Penyimpanan barang harus dibedakan antara barang baru, barang baik dan barang rusak dengan petunjuk yang jelas. Barang rusak harus dipisahkan dari barang baik untuk menjaga mutu dan kejelasan administrasi di suatu tempat guna memastikan barang yang rusak tidak dikirim dan memudahkan pada saat akan dilaksanakan perbaikan.
4. Atap Atap gudang merupakan sarana penting untuk menghindari kerusakan barang yang disebabkan oleh air hujan, angin dan panas yang berlebihan. Atap gudang juga berfungsi untuk menjaga keamanan barang.
5. Dinding Dinding gudang merupakan bagian penting dalam pelaksanaan aktifitas gudang peralatan. Dinding gudang peralatan harus bersifat permanen, aman dan tahan terhadap gangguan secara umum.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8000, '2. Pintu Masuk atau Keluar Barang Pintu masuk atau keluar barang merupakan akses dari luar gudang ke dalam gudang atau sebaliknya. Akses ini merupakan titik penting untuk jaminan keamanan kehilangan barang. Jika memungkinkan, pintu untuk barang dapat dipisahkan dengan pintu untuk petugas. Pemisahan pintu masuk dan pintu keluar untuk memastikan kemudahan didalam penanganan barang dan sekaligus menjamin keamanan barang yang masuk dan keluar serta terpisah dari keluar masuknya petugas.
3. Penyimpanan Barang Penyimpanan barang harus dibedakan antara barang baru, barang baik dan barang rusak dengan petunjuk yang jelas. Barang rusak harus dipisahkan dari barang baik untuk menjaga mutu dan kejelasan administrasi di suatu tempat guna memastikan barang yang rusak tidak dikirim dan memudahkan pada saat akan dilaksanakan perbaikan.
4. Atap Atap gudang merupakan sarana penting untuk menghindari kerusakan barang yang disebabkan oleh air hujan, angin dan panas yang berlebihan. Atap gudang juga berfungsi untuk menjaga keamanan barang.
5. Dinding Dinding gudang merupakan bagian penting dalam pelaksanaan aktifitas gudang peralatan. Dinding gudang peralatan harus bersifat permanen, aman dan tahan terhadap gangguan secara umum.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8001, 'perka-3-2014', 15, 'lampiran', 'Lampiran hal. 8', NULL, 8, '6. Lantai Lantai gudang harus memiliki kekuatan minimal yang dapat menjamin keberadaan barang diatasnya tidak terperosok atau amblas, sekaligus menjamin kesehatan petugas dan kebersihan barang serta kelancaran operasional, khususnya operasional hand pallet, pallet dan proses bongkar muat. Lantai gudang terbuat dari bahan yang kuat dan tahan lama.
7. Pintu Gudang Pintu harus memiliki ukuran yang seimbang antara lebar dan tingginya yang memungkinkan untuk kemudahan bongkar muat.
Bahan pintu harus mempunyai kekuatan yang dapat menjamin 9 2014, No.252 keamanan gudang dan barang serta manusia yang bekerja di dalamnya.
8. Perlengkapan Gudang Gudang peralatan penanggulangan bencana harus memiliki perlengkapan diantaranya: rak, palet, troli, handtruck/handpallet, forklift, lampu, alat pemadam kebakaran, alat-alat kebersihan, perkakas dan lain-lain.
9. Alat Pengamanan Keamanan yang baik akan memberikan ketenangan dan kenyamanan dan menciptakan rasa aman di dalam bekerja sehingga mendapatkan hasil yang maksimal. Alat pengamanan tersebut antara lain; alarm, CCTV, spotlight, dan menara kontrol.
C. Struktur Pengelola Struktur pengelola gudang peralatan dapat digambarkan sesuai dengan gambar berikut :
MANAJER GUDANG PETUGAS ADMINISTRASI PENGELOLA GUDANG PETUGAS ADMINISTRASI KEAMANAN KEBERSIHAN TEKNISI JURU HITUNG Gambar 1 : STRUKTUR PENGELOLA GUDANG PERALATAN
1. Manajer Gudang
2. Pengelola Gudang
3. Petugas Administrasi Gudang
4. Juru Hitung
5. Teknisi 2014, No.252 10
6. Petugas Keamanan');
