INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8002, 'perka-3-2014', 16, 'lampiran', 'Lampiran hal. 10', NULL, 10, '7. Petugas Kebersihan D. Tugas Dan Tanggung Jawab
1. Manajer Gudang a) Melakukan manajemen pergudangan meliputi stok, penerimaan, pemeliharaan, penyimpanan, dan pengeluaran barang; b) Melakukan manajemen petugas gudang untuk kepentingan operasional gudang; c) Bertanggung jawab atas stok, petugas dan gudang; d) Memastikan percepatan pengeluaran peralatan; e) Berfungsi sebagai koordinator untuk segala urusan yg berhubungan dengan gudang tentang status peralatan di dalam gudang pada saat pra, selama masa tanggap darurat dan pasca bencana; f) Memastikan laporan stok harian g) Memastikan semua dokumen tersimpan demi kepentingan audit; h) Melaporkan kepada BNPB / BPBD semua permasalahan yang berhubungan dengan stok, gudang, dan petugas di bawahnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8002, '7. Petugas Kebersihan D. Tugas Dan Tanggung Jawab
1. Manajer Gudang a) Melakukan manajemen pergudangan meliputi stok, penerimaan, pemeliharaan, penyimpanan, dan pengeluaran barang; b) Melakukan manajemen petugas gudang untuk kepentingan operasional gudang; c) Bertanggung jawab atas stok, petugas dan gudang; d) Memastikan percepatan pengeluaran peralatan; e) Berfungsi sebagai koordinator untuk segala urusan yg berhubungan dengan gudang tentang status peralatan di dalam gudang pada saat pra, selama masa tanggap darurat dan pasca bencana; f) Memastikan laporan stok harian g) Memastikan semua dokumen tersimpan demi kepentingan audit; h) Melaporkan kepada BNPB / BPBD semua permasalahan yang berhubungan dengan stok, gudang, dan petugas di bawahnya.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8003, 'perka-3-2014', 17, 'lampiran', 'Lampiran hal. 10', NULL, 10, '2. Pengelola Gudang a) Satu orang Pengelola Gudang bertanggung jawab untuk operasional satu unit gudang yang berhubungan dengan penerimaan, stok, pemeliharaan, penyimpanan dan pengeluaran; b) Menerima pelaksanaan tugas dari manajer gudang; c) Memastikan semua pergerakan peralatan di gudang tercatat; d) Melakukan koordinasi untuk kegiatan bongkar muat barang, penyimpanan dan pengeluaran; e) Membantu manajer untuk mensupervisi operasional gudang dan petugas gudang; f) Menandatangani semua surat jalan: barang masuk dan barang keluar; g) Memastikan administrasi pencatatan pergerakan peralatan terlaksana dengan baik; h) Melaporkan dan bertanggung jawab kepada manajer semua permasalahan yang berhubungan dengan stok, gudang, dan petugas di bawahnya.
11 2014, No.252
4. Petugas Administrasi Gudang a) Bertanggung jawab untuk melakukan kompilasi semua data tentang pergerakan peralatan: penerimaan, stock opname dan pengeluaran; b) Bertanggung jawab untuk membuat laporan stok harian dengan menggunakan program komputer; c) Memastikan semua dokumen pergerakan peralatan: penerimaan, stock opname dan pengeluaran, disimpan dengan baik dan dapat dilacak dengan mudah bilamana diperlukan; d) Melaporkan semua selisih angka stok (bila ada) kepada Pengelola Gudang e) Membantu juru hitung dalam memastikan pencatatan keluar masuk peralatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8003, '2. Pengelola Gudang a) Satu orang Pengelola Gudang bertanggung jawab untuk operasional satu unit gudang yang berhubungan dengan penerimaan, stok, pemeliharaan, penyimpanan dan pengeluaran; b) Menerima pelaksanaan tugas dari manajer gudang; c) Memastikan semua pergerakan peralatan di gudang tercatat; d) Melakukan koordinasi untuk kegiatan bongkar muat barang, penyimpanan dan pengeluaran; e) Membantu manajer untuk mensupervisi operasional gudang dan petugas gudang; f) Menandatangani semua surat jalan: barang masuk dan barang keluar; g) Memastikan administrasi pencatatan pergerakan peralatan terlaksana dengan baik; h) Melaporkan dan bertanggung jawab kepada manajer semua permasalahan yang berhubungan dengan stok, gudang, dan petugas di bawahnya.
11 2014, No.252
4. Petugas Administrasi Gudang a) Bertanggung jawab untuk melakukan kompilasi semua data tentang pergerakan peralatan: penerimaan, stock opname dan pengeluaran; b) Bertanggung jawab untuk membuat laporan stok harian dengan menggunakan program komputer; c) Memastikan semua dokumen pergerakan peralatan: penerimaan, stock opname dan pengeluaran, disimpan dengan baik dan dapat dilacak dengan mudah bilamana diperlukan; d) Melaporkan semua selisih angka stok (bila ada) kepada Pengelola Gudang e) Membantu juru hitung dalam memastikan pencatatan keluar masuk peralatan.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8004, 'perka-3-2014', 18, 'lampiran', 'Lampiran hal. 11', NULL, 11, '5. Juru Hitung a) Memastikan jumlah peralatan yang masuk dan keluar sesuai dengan dokumen surat jalan; b) Memeriksa armada yang akan digunakan untuk pengeluaran dalam keadaan baik dan aman; c) Mengumpulkan semua surat jalan pada hari pengeluaran dan diberikan kepada petugas administrasi gudang untuk dilakukan kompilasi dalam rangka pembuatan laporan stok harian; d) Membantu Pengelola Gudang untuk mengkoordinir buruh dan pihak ekspedisi; e) Melaporkan kepada Pengelola Gudang semua kendala dalam penerimaan dan pengiriman peralatan.
6. Teknisi a) Memastikan peralatan yang diterima dalam keadaan baik, dengan cara mencoba menjalankannya (bila memungkinkan) sebelum surat jalan penerimaan peralatan ditandatangani Pengelola Gudang; b) Melakukan pemeliharaan rutin terhadap semua peralatan yang disimpan; c) Meminta pelatihan penanganan peralatan produk baru (bila diperlukan); d) Melaporkan segala kerusakan peralatan dan gudang kepada Pengelola Gudang; e) Mengisi kartu pemeliharaan untuk setiap barang yang dirawat;
2014, No.252 12 f) Membantu juru hitung bila diperlukan.
7. Petugas Keamanan
a. Memastikan keamanan area gudang dan petugas;
b. Memastikan peraturan keamanan gudang dipatuhi oleh petugas dan pengunjung gudang;
c. Mencatat semua nomor kendaraan yang keluar dan masuk;
d. Tidak mengijinkan barang keluar dari gudang bila surat jalan tidak ditandatangani oleh Pengelola Gudang;
e. Meminta salinan dokumen surat jalan peralatan yang diterima dan dikeluarkan.
8. Petugas Kebersihan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8004, '5. Juru Hitung a) Memastikan jumlah peralatan yang masuk dan keluar sesuai dengan dokumen surat jalan; b) Memeriksa armada yang akan digunakan untuk pengeluaran dalam keadaan baik dan aman; c) Mengumpulkan semua surat jalan pada hari pengeluaran dan diberikan kepada petugas administrasi gudang untuk dilakukan kompilasi dalam rangka pembuatan laporan stok harian; d) Membantu Pengelola Gudang untuk mengkoordinir buruh dan pihak ekspedisi; e) Melaporkan kepada Pengelola Gudang semua kendala dalam penerimaan dan pengiriman peralatan.
6. Teknisi a) Memastikan peralatan yang diterima dalam keadaan baik, dengan cara mencoba menjalankannya (bila memungkinkan) sebelum surat jalan penerimaan peralatan ditandatangani Pengelola Gudang; b) Melakukan pemeliharaan rutin terhadap semua peralatan yang disimpan; c) Meminta pelatihan penanganan peralatan produk baru (bila diperlukan); d) Melaporkan segala kerusakan peralatan dan gudang kepada Pengelola Gudang; e) Mengisi kartu pemeliharaan untuk setiap barang yang dirawat;
2014, No.252 12 f) Membantu juru hitung bila diperlukan.
7. Petugas Keamanan
a. Memastikan keamanan area gudang dan petugas;
b. Memastikan peraturan keamanan gudang dipatuhi oleh petugas dan pengunjung gudang;
c. Mencatat semua nomor kendaraan yang keluar dan masuk;
d. Tidak mengijinkan barang keluar dari gudang bila surat jalan tidak ditandatangani oleh Pengelola Gudang;
e. Meminta salinan dokumen surat jalan peralatan yang diterima dan dikeluarkan.
8. Petugas Kebersihan', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8005, 'perka-3-2014', 19, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'a. Membersihkan semua peralatan didalam gudang secara berkala;
b. Memastikan kondisi gudang selalu terjaga bersih, terutama dari hama / serangga.
BAB III SISTEM OPERASIONAL GUDANG Operasional gudang peralatan Penanggulangan Bencana meliputi proses mulai dari Penerimaan, Penyimpanan, pemeliharaan, pengelolaan stok peralatan, sistem informasi dan pengeluaran.
A. Penerimaan Peralatan Penanggulangan Bencana Penerimaan merupakan proses penyerahan dan penerimaan barang di dalam gudang, dengan tahapan mulai dari pendataan nama, jumlah, dan kondisi peralatan pada saat penerimaan di gudang hingga pencatatan administrasi oleh petugas yang bertanggung jawab.
1. Penanggung jawab proses penerimaan barang a) Manajer Gudang bertanggung jawab untuk:
1) Mengkoordinasikan peralatan yang akan masuk kedalam gudang kepada petugas yang berwenang;
2) memastikan peralatan yang diterima sesuai dengan dokumen barang masuk;
3) mengkoordinir petugas di bawahnya untuk proses penerimaan barang;
4) memastikan semua aktivitas penerimaan peralatan tercatat.
13 2014, No.252 b) Pengelola Gudang;
1) memastikan peralatan yang diterima sesuai dengan yang telah diinstruksikan oleh manajer gudang;
2) memastikan petugas di bawahnya melakukan proses penerimaan dengan baik dan benar dan memperhatikan kualitas peralatan yang diterima sesuai dengan dokumen penerimaan barang;
3) mengkoordinir buruh untuk proses penerimaan peralatan;
4) merencanakan tempat penerimaan peralatan di dalam gudang;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8005, 'a. Membersihkan semua peralatan didalam gudang secara berkala;
b. Memastikan kondisi gudang selalu terjaga bersih, terutama dari hama / serangga.
BAB III SISTEM OPERASIONAL GUDANG Operasional gudang peralatan Penanggulangan Bencana meliputi proses mulai dari Penerimaan, Penyimpanan, pemeliharaan, pengelolaan stok peralatan, sistem informasi dan pengeluaran.
A. Penerimaan Peralatan Penanggulangan Bencana Penerimaan merupakan proses penyerahan dan penerimaan barang di dalam gudang, dengan tahapan mulai dari pendataan nama, jumlah, dan kondisi peralatan pada saat penerimaan di gudang hingga pencatatan administrasi oleh petugas yang bertanggung jawab.
1. Penanggung jawab proses penerimaan barang a) Manajer Gudang bertanggung jawab untuk:
1) Mengkoordinasikan peralatan yang akan masuk kedalam gudang kepada petugas yang berwenang;
2) memastikan peralatan yang diterima sesuai dengan dokumen barang masuk;
3) mengkoordinir petugas di bawahnya untuk proses penerimaan barang;
4) memastikan semua aktivitas penerimaan peralatan tercatat.
13 2014, No.252 b) Pengelola Gudang;
1) memastikan peralatan yang diterima sesuai dengan yang telah diinstruksikan oleh manajer gudang;
2) memastikan petugas di bawahnya melakukan proses penerimaan dengan baik dan benar dan memperhatikan kualitas peralatan yang diterima sesuai dengan dokumen penerimaan barang;
3) mengkoordinir buruh untuk proses penerimaan peralatan;
4) merencanakan tempat penerimaan peralatan di dalam gudang;', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8006, 'perka-3-2014', 20, 'lampiran', 'Lampiran hal. 13', NULL, 13, '5) Memastikan proses penerimaan tercatat dan melaporkan segera apabila terjadi permasalahan kepada manajer gudang. c) Juru Hitung 1) Memastikan peralatan yang masuk dihitung sesuai dengan surat penerimaan barang;
2) Mengkoordinir buruh dan pihak pengangkutan;
3) Memastikan proses penerimaan tercatat dan melaporkan segera apabila terjadi permasalahan kepada Store Keeper. d) Pihak keamanan 1) Memastikan keamanan selama proses penerimaan peralatan di gudang;
2) Membantu Juru Hitung dalam mengkoordinir buruh dan pihak pengangkutan;
3) Memastikan semua kendaraaan yang masuk kedalam lingkungan gudang dicatat ;
4) Melaporkan dengan segera apabila terjadi permasalahan kepada manajer gudang.
2. Alur penerimaan peralatan di gudang Dalam melakukan penerimaan peralatan di gudang perlu diperhatikan alur penerimaan peralatan sebagai mana gambar berikut:
2014, No.252 14 GUDANG MANAJER GUDANG PENGELOLA GUDANG JURU HITUNG ANGKUTAN/ ARMADA MASUK KE GUDANG BARANG MASUK Gambar 2 : Bagan Alur Penerimaan Peralatan
3. Dokumen penerimaan dan pencatatan barang Untuk proses penerimaan barang, dokumen pencatatan yang perlu dimiliki adalah: surat jalan, buku catatan penerimaan di dalam gudang, dan kartu stok. Sedangkan isian formulir penerimaan barang dan pencatatan sebagaimana dapat dilihat pada Lampiran 1.
4. Sistem dan prosedur Proses penerimaan peralatan :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8006, '5) Memastikan proses penerimaan tercatat dan melaporkan segera apabila terjadi permasalahan kepada manajer gudang. c) Juru Hitung 1) Memastikan peralatan yang masuk dihitung sesuai dengan surat penerimaan barang;
2) Mengkoordinir buruh dan pihak pengangkutan;
3) Memastikan proses penerimaan tercatat dan melaporkan segera apabila terjadi permasalahan kepada Store Keeper. d) Pihak keamanan 1) Memastikan keamanan selama proses penerimaan peralatan di gudang;
2) Membantu Juru Hitung dalam mengkoordinir buruh dan pihak pengangkutan;
3) Memastikan semua kendaraaan yang masuk kedalam lingkungan gudang dicatat ;
4) Melaporkan dengan segera apabila terjadi permasalahan kepada manajer gudang.
2. Alur penerimaan peralatan di gudang Dalam melakukan penerimaan peralatan di gudang perlu diperhatikan alur penerimaan peralatan sebagai mana gambar berikut:
2014, No.252 14 GUDANG MANAJER GUDANG PENGELOLA GUDANG JURU HITUNG ANGKUTAN/ ARMADA MASUK KE GUDANG BARANG MASUK Gambar 2 : Bagan Alur Penerimaan Peralatan
3. Dokumen penerimaan dan pencatatan barang Untuk proses penerimaan barang, dokumen pencatatan yang perlu dimiliki adalah: surat jalan, buku catatan penerimaan di dalam gudang, dan kartu stok. Sedangkan isian formulir penerimaan barang dan pencatatan sebagaimana dapat dilihat pada Lampiran 1.
4. Sistem dan prosedur Proses penerimaan peralatan :', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8007, 'perka-3-2014', 21, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'Penerimaan peralatan adalah menerima fisik peralatan yang disesuaikan dengan dokumen pengiriman barang dan dalam kondisi yang sesuai dengan persyaratan barang.
Dalam aktivitas penerimaan barang terdapat tiga hal penting yang harus diperhatikan yaitu: a) Fisik barang yang diterima Fisik barang adalah bentuk fisik yang dapat dilihat langsung;
Prinsip penerimaan barang adalah menerima barang secara fisik, berikut dokumennya secara langsung. b) Dokumentasi Dokumen merupakan pendamping barang yang secara fisik dapat dibaca dan dicocokkan dengan barang yang dikirimkan.
Dokumen yang dikirimkan minimal dokumen pengiriman atau surat jalan.
15 2014, No.252 c) Cara penanganan barang Persyaratan penanganan barang yang harus diperhatikan saat barang tersebut diterima :
1) Gunakan peralatan pendukung yang sesuai (palet, forklift ataupun alat manual pemindah palet);
2) Memahami aturan Keselamatan dan Kesehatan Kerja (K3).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8007, 'Penerimaan peralatan adalah menerima fisik peralatan yang disesuaikan dengan dokumen pengiriman barang dan dalam kondisi yang sesuai dengan persyaratan barang.
Dalam aktivitas penerimaan barang terdapat tiga hal penting yang harus diperhatikan yaitu: a) Fisik barang yang diterima Fisik barang adalah bentuk fisik yang dapat dilihat langsung;
Prinsip penerimaan barang adalah menerima barang secara fisik, berikut dokumennya secara langsung. b) Dokumentasi Dokumen merupakan pendamping barang yang secara fisik dapat dibaca dan dicocokkan dengan barang yang dikirimkan.
Dokumen yang dikirimkan minimal dokumen pengiriman atau surat jalan.
15 2014, No.252 c) Cara penanganan barang Persyaratan penanganan barang yang harus diperhatikan saat barang tersebut diterima :
1) Gunakan peralatan pendukung yang sesuai (palet, forklift ataupun alat manual pemindah palet);
2) Memahami aturan Keselamatan dan Kesehatan Kerja (K3).', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8008, 'perka-3-2014', 22, 'lampiran', 'Lampiran hal. 15', NULL, 15, '5. Tahapan Penerimaan Barang Penerimaan barang dilakukan melalui tahapan sebagai berikut: a) Masuk gudang Melakukan pengecekkan dokumen masuk di pos pintu masuk areal pergudangan. b) Bongkar muat Perlu dipastikan bahwa lokasi yang digunakan untuk membongkar muatan aman dan nyaman (juga terlindung dari hujan) untuk melakukan pembongkaran. Pastikan pada saat barang dibongkar sudah diketahui berapa standar per lapis, ataupun volume barang tersebut. c) Pengecekan kesesuaian barang dengan dokumen Lakukan pengecekan barang dengan dokumen agar tidak terjadi kekeliruan baik nama, jumlah, dan kondisi barang. d) Pencatatan transaksi barang (masuk-keluar) ke dalam Kartu Stok disetiap macam barang dan pencatatan pemeliharaan kedalam Kartu Pemeliharaan disetiap macam barang.
1) Kartu stok barang:
Pencatatan minimum yang diperlukan adalah nama barang, tipe / model / jenis barang, jumlah, tanggal diterima dan tanggal keluar, keterangan yang diperlukan jika ada, nama dan paraf petugas pencatatan. Contoh kartu stok barang dapat dilihat pada lampiran 2.
2) Kartu pemeliharaan barang:
Pencatatan minimum yang diperlukan adalah nama barang, tipe / model / jenis barang, tanggal diterima, nomor seri barang jika ada, spesifikasi perawatan barang, apa-apa yang harus diperiksa, dan tanggal perawatan / pemeriksaan berkala, nama & paraf petugas pemeliharaan. Contoh kartu pemeliharaan barang dapat dilihat pada lampiran 3.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8008, '5. Tahapan Penerimaan Barang Penerimaan barang dilakukan melalui tahapan sebagai berikut: a) Masuk gudang Melakukan pengecekkan dokumen masuk di pos pintu masuk areal pergudangan. b) Bongkar muat Perlu dipastikan bahwa lokasi yang digunakan untuk membongkar muatan aman dan nyaman (juga terlindung dari hujan) untuk melakukan pembongkaran. Pastikan pada saat barang dibongkar sudah diketahui berapa standar per lapis, ataupun volume barang tersebut. c) Pengecekan kesesuaian barang dengan dokumen Lakukan pengecekan barang dengan dokumen agar tidak terjadi kekeliruan baik nama, jumlah, dan kondisi barang. d) Pencatatan transaksi barang (masuk-keluar) ke dalam Kartu Stok disetiap macam barang dan pencatatan pemeliharaan kedalam Kartu Pemeliharaan disetiap macam barang.
1) Kartu stok barang:
Pencatatan minimum yang diperlukan adalah nama barang, tipe / model / jenis barang, jumlah, tanggal diterima dan tanggal keluar, keterangan yang diperlukan jika ada, nama dan paraf petugas pencatatan. Contoh kartu stok barang dapat dilihat pada lampiran 2.
2) Kartu pemeliharaan barang:
Pencatatan minimum yang diperlukan adalah nama barang, tipe / model / jenis barang, tanggal diterima, nomor seri barang jika ada, spesifikasi perawatan barang, apa-apa yang harus diperiksa, dan tanggal perawatan / pemeriksaan berkala, nama & paraf petugas pemeliharaan. Contoh kartu pemeliharaan barang dapat dilihat pada lampiran 3.', 'Lampiran hal. 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8009, 'perka-3-2014', 23, 'lampiran', 'Lampiran hal. 16', NULL, 16, '2014, No.252 16 e) Memasukkan data ke dalam sistem database (komputerisasi) Pastikan dokumen sesuai dengan fisik barang yang diterima, tercatat dalam kartu stok dan selanjutnya memasukkan data ke dalam sistem. f) Legitimasi dokumen Pastikan bahwa keabsahan dukumen sudah terjamin dengan melengkapi dokumen yang ditandatangani oleh petugas penerima barang, nama jelas, stempel dan data pendukung lainnya. Perhatikan dengan cermat dokumen surat jalan dari angkutan darat, packing list dari pengirim barang / vendor, manifes, bill of lading dari angkutan laut maupun airway bill dari angkutan udara.
B. Penyimpanan dan Pemeliharaan Peralatan Penanggulangan Bencana Penyimpanan merupakan proses kegiatan menyimpan peralatan di dalam gudang demi kepentingan manajemen stok sementara pemiliharaan adalah suatu proses kegiatan untuk mengendalikan mutu atau quality control akan peralatan yang disimpan.
1. Penanggung jawab proses penyimpanan barang a) Manajer gudang, bertanggung jawab untuk:
1) Memastikan barang tersimpan dengan baik dan benar sesuai dengan kebijaksanaan BNPB / BPBD;
2) Melakukan pengawasan rutin selama barang tersimpan didalam gudang;
3) Melaporkan segera bila terjadi penyimpangan dalam proses penyimpanan. b) Pengelola Gudang 1) Memastikan barang yang disimpan sesuai dengan yang telah diinstruksikan oleh manajer gudang;
2) Melakukan penghitungan rutin terhadap stok barang;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8009, '2014, No.252 16 e) Memasukkan data ke dalam sistem database (komputerisasi) Pastikan dokumen sesuai dengan fisik barang yang diterima, tercatat dalam kartu stok dan selanjutnya memasukkan data ke dalam sistem. f) Legitimasi dokumen Pastikan bahwa keabsahan dukumen sudah terjamin dengan melengkapi dokumen yang ditandatangani oleh petugas penerima barang, nama jelas, stempel dan data pendukung lainnya. Perhatikan dengan cermat dokumen surat jalan dari angkutan darat, packing list dari pengirim barang / vendor, manifes, bill of lading dari angkutan laut maupun airway bill dari angkutan udara.
B. Penyimpanan dan Pemeliharaan Peralatan Penanggulangan Bencana Penyimpanan merupakan proses kegiatan menyimpan peralatan di dalam gudang demi kepentingan manajemen stok sementara pemiliharaan adalah suatu proses kegiatan untuk mengendalikan mutu atau quality control akan peralatan yang disimpan.
1. Penanggung jawab proses penyimpanan barang a) Manajer gudang, bertanggung jawab untuk:
1) Memastikan barang tersimpan dengan baik dan benar sesuai dengan kebijaksanaan BNPB / BPBD;
2) Melakukan pengawasan rutin selama barang tersimpan didalam gudang;
3) Melaporkan segera bila terjadi penyimpangan dalam proses penyimpanan. b) Pengelola Gudang 1) Memastikan barang yang disimpan sesuai dengan yang telah diinstruksikan oleh manajer gudang;
2) Melakukan penghitungan rutin terhadap stok barang;', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8010, 'perka-3-2014', 24, 'lampiran', 'Lampiran hal. 16', NULL, 16, '3) Memastikan petugas di bawahnya melakukan process penyimpanan dan perawatan peralatan dengan baik dan benar sesuai dengan kebijakan BNPB / BPBD;
4) Memastikan kebersihan gudang;
5) Membuat catatan tersendiri untuk peralatan yang sudah dipakai. c) Juru Hitung dan Teknisi 1) Melakukan penghitungan / pengecekan rutin terhadap semua stok barang;
17 2014, No.252 2) Melakukan pemeliharaan barang;
3) Memastikan kebersihan gudang terjaga demikian juga stok barang.
2. Alur Proses Penyimpanan dan Pemeliharaan Barang Dalam rangka menjaga kualitas barang diperlukan proses penyimpanan dan pemeliharaan yang baik. Untuk itu perlu alur proses penyimpanan dan pemeliharaan barang yang terus menerus.
Adapun alur proses penyimpanan dan pemeliharaan sebagai berikut :
3. : Bagan Alur Proses Penyimpanan dan Pemeliharaan MANAJER GUDANG PENGELOLA BARANG YANG GUDANG DI SIMPAN KEAMANAN JURU HITUNG DAN TEKNISI a) Kartu stok barang Kartu Stok barang merupakan sumber informasi awal dalam pengelolaan stok. b) Kartu pemeliharaan barang Kartu Pemeliharaan barang merupakan sumber informasi awal yang berisikan risalah perawatan barang yang di lakukan oleh teknisi gudang.
3. Dalam penyimpanan barang terdapat dua hal penting :
a. Penempatan barang 1) Tentukan area penyimpanan sesuai dengan kelompok/ jenis barang dengan petunjuk /label yang jelas;
2) Tentukan batas maksimum penumpukan barang;
2014, No.252 18 3) Letakkan barang yang sering keluar/masuk di dekat pintu keluar/pintu masuk;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8010, '3) Memastikan petugas di bawahnya melakukan process penyimpanan dan perawatan peralatan dengan baik dan benar sesuai dengan kebijakan BNPB / BPBD;
4) Memastikan kebersihan gudang;
5) Membuat catatan tersendiri untuk peralatan yang sudah dipakai. c) Juru Hitung dan Teknisi 1) Melakukan penghitungan / pengecekan rutin terhadap semua stok barang;
17 2014, No.252 2) Melakukan pemeliharaan barang;
3) Memastikan kebersihan gudang terjaga demikian juga stok barang.
2. Alur Proses Penyimpanan dan Pemeliharaan Barang Dalam rangka menjaga kualitas barang diperlukan proses penyimpanan dan pemeliharaan yang baik. Untuk itu perlu alur proses penyimpanan dan pemeliharaan barang yang terus menerus.
Adapun alur proses penyimpanan dan pemeliharaan sebagai berikut :
3. : Bagan Alur Proses Penyimpanan dan Pemeliharaan MANAJER GUDANG PENGELOLA BARANG YANG GUDANG DI SIMPAN KEAMANAN JURU HITUNG DAN TEKNISI a) Kartu stok barang Kartu Stok barang merupakan sumber informasi awal dalam pengelolaan stok. b) Kartu pemeliharaan barang Kartu Pemeliharaan barang merupakan sumber informasi awal yang berisikan risalah perawatan barang yang di lakukan oleh teknisi gudang.
3. Dalam penyimpanan barang terdapat dua hal penting :
a. Penempatan barang 1) Tentukan area penyimpanan sesuai dengan kelompok/ jenis barang dengan petunjuk /label yang jelas;
2) Tentukan batas maksimum penumpukan barang;
2014, No.252 18 3) Letakkan barang yang sering keluar/masuk di dekat pintu keluar/pintu masuk;', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8011, 'perka-3-2014', 25, 'lampiran', 'Lampiran hal. 18', NULL, 18, '4) Jika perlu tentukan petugas yang menangani barang per kelompok/jenis barang;
5) Lengkapi dengan Pengawasan hama, monitor suhu, alat pendingin udara (jika diperlukan), cahaya dan sirkulasi udara yang memadai dan pastikan tidak ada kebocoran pada atap gudang.
b. Karakteristik barang Barang yang disimpan harus disesuaikan dengan karakteristik barang. Secara garis besar untuk peralatan dikelompokkan diantaranya sebagai berikut :
1) Peralatan komunikasi (contoh: radio, handy talky, antena) 2) Peralatan kendaraan (contoh: mobil, motor) 3) Peralatan kedaruratan/emergency (contoh: chain saw, bor) 4) Peralatan personal (contoh: rompi, tas, senter) 5) Peralatan tenda (contoh: tenda posko, personel) 6) Peralatan kesehatan (contoh: meja operasi, velbed) 7) Peralatan berat (contoh: traktor, eskavator)
4. Pemeliharaan Peralatan Pemeliharaan peralatan dilakukan terhadap barang yang sudah tercatat di dalam gudang. Apabila diperlukan pemeliharaan peralatan dapat dilakukan melalui kerja sama dengan pihak ketiga sesuai dengan sifat, jenis dan kondisi peralatan tersebut.
5. Dukungan Anggaran Pemerintah dan pemerintah daerah perlu menyediakan anggaran untuk operasional dan pemeliharaan pergudangan, yang mencakup biaya honor bulanan petugas, biaya administrasi dan pelaporan, biaya pemeliharaan dan perawatan barang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8011, '4) Jika perlu tentukan petugas yang menangani barang per kelompok/jenis barang;
5) Lengkapi dengan Pengawasan hama, monitor suhu, alat pendingin udara (jika diperlukan), cahaya dan sirkulasi udara yang memadai dan pastikan tidak ada kebocoran pada atap gudang.
b. Karakteristik barang Barang yang disimpan harus disesuaikan dengan karakteristik barang. Secara garis besar untuk peralatan dikelompokkan diantaranya sebagai berikut :
1) Peralatan komunikasi (contoh: radio, handy talky, antena) 2) Peralatan kendaraan (contoh: mobil, motor) 3) Peralatan kedaruratan/emergency (contoh: chain saw, bor) 4) Peralatan personal (contoh: rompi, tas, senter) 5) Peralatan tenda (contoh: tenda posko, personel) 6) Peralatan kesehatan (contoh: meja operasi, velbed) 7) Peralatan berat (contoh: traktor, eskavator)
4. Pemeliharaan Peralatan Pemeliharaan peralatan dilakukan terhadap barang yang sudah tercatat di dalam gudang. Apabila diperlukan pemeliharaan peralatan dapat dilakukan melalui kerja sama dengan pihak ketiga sesuai dengan sifat, jenis dan kondisi peralatan tersebut.
5. Dukungan Anggaran Pemerintah dan pemerintah daerah perlu menyediakan anggaran untuk operasional dan pemeliharaan pergudangan, yang mencakup biaya honor bulanan petugas, biaya administrasi dan pelaporan, biaya pemeliharaan dan perawatan barang.', 'Lampiran hal. 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8012, 'perka-3-2014', 26, 'lampiran', 'Lampiran hal. 18', NULL, 18, 'C. Manajemen Stok dan Sistem Informasi Tahapan ini merupakan tahapan yang paling penting dalam hal kredibilitas karena menjadi sumber informasi bagi manajer gudang dan pimpinan BNPB/BPBD guna mengetahui status stok yang ada di dalam gudang dan demikian juga dengan pengeluaran barang yang telah dilakukan.
1. Penanggung jawab manajemen stok a) Manajer gudang bertanggung jawab untuk memastikan 19 2014, No.252 manajemen stok dilakukan dengan benar dan semua data pergerakan stok tercatat dan terlacak. b) Pengelola Gudang 1) Memastikan semua transaksi pergerakan barang dicatat dengan benar;
2) Memastikan laporan stok dikeluarkan setiap harinya pada akhir kegiatan;
3) Memastikan petugas administrasi menyediakan data yang akurat. c) Petugas Administrasi 1) Adalah posisi yang bertanggung jawab dalam hal pencatatan, pelaporan segala sesuatu yang berhubungan dengan pergerakan stock mulai dari barang masuk – selama disimpan dan dikeluarkan;
2) Melaporkan kepada Manajer Gudang atas segala ketidak sesuaian yang ditemukan;
3) Membuat laporan stok harian;
4) Menyimpan semua file/dokumen barang;
5) Menyiapkan materi atau data yang akan diperlukan guna pembuatan laporan bulanan, tahunan dan pertanggung jawaban kepada Pengelola Gudang.
2. Alur proses manajemen stok Manajemen stok mempunyai alur proses sebagai berikut :
MANAJER GUDANG PENGELOLA GUDANG PETUGAS ADMINISTRASI LAPORAN STOCK STOK 2014, No.252 20 Gambar 4 : Bagan Alur Manajemen Stok');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8012, 'C. Manajemen Stok dan Sistem Informasi Tahapan ini merupakan tahapan yang paling penting dalam hal kredibilitas karena menjadi sumber informasi bagi manajer gudang dan pimpinan BNPB/BPBD guna mengetahui status stok yang ada di dalam gudang dan demikian juga dengan pengeluaran barang yang telah dilakukan.
1. Penanggung jawab manajemen stok a) Manajer gudang bertanggung jawab untuk memastikan 19 2014, No.252 manajemen stok dilakukan dengan benar dan semua data pergerakan stok tercatat dan terlacak. b) Pengelola Gudang 1) Memastikan semua transaksi pergerakan barang dicatat dengan benar;
2) Memastikan laporan stok dikeluarkan setiap harinya pada akhir kegiatan;
3) Memastikan petugas administrasi menyediakan data yang akurat. c) Petugas Administrasi 1) Adalah posisi yang bertanggung jawab dalam hal pencatatan, pelaporan segala sesuatu yang berhubungan dengan pergerakan stock mulai dari barang masuk – selama disimpan dan dikeluarkan;
2) Melaporkan kepada Manajer Gudang atas segala ketidak sesuaian yang ditemukan;
3) Membuat laporan stok harian;
4) Menyimpan semua file/dokumen barang;
5) Menyiapkan materi atau data yang akan diperlukan guna pembuatan laporan bulanan, tahunan dan pertanggung jawaban kepada Pengelola Gudang.
2. Alur proses manajemen stok Manajemen stok mempunyai alur proses sebagai berikut :
MANAJER GUDANG PENGELOLA GUDANG PETUGAS ADMINISTRASI LAPORAN STOCK STOK 2014, No.252 20 Gambar 4 : Bagan Alur Manajemen Stok', 'Lampiran hal. 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8013, 'perka-3-2014', 27, 'lampiran', 'Lampiran hal. 20', NULL, 20, '3. Stock opname dan pencatatan Merupakan suatu proses untuk mengawasi pergerakan stok, secara umum stock opname dilakukan sebulan sekali oleh Manajer gudang, Pengelola Gudang, Petugas Administrasi dan Juru Hitung.
Setiap bulannya manajer gudang berkewajiban mengeluarkan laporan stock opname kepada pimpinan BNPB/BPBD yang menyatakan posisi stok peralatan yang ada di dalam gudangnya. a) Sistem informasi gudang disini berlaku sejak penerimaan barang di gudang, penyimpanan barang, pemeliharaan barang, penghitungan stok dan pengeluaran barang dari gudang, dan dengan segala prosedurnya untuk memastikan semua data dapat tersimpan dengan baik di dalam sistem database, sehingga dapat menjamin keandalan sistem, dan dipercaya. b) Prosedur stock opname dan pencatatan 1) Bentuk tim stock opname dengan anggota minimal 2 orang, yang mana satu orang untuk melakukan penghitungan fisik barang dan satu orang lagi untuk pencatatan;
2) Pengelola Gudang memberikan lembar penghitungan stok periode tersebut kepada pencatat tim stock opname;
3) Pencatat memegang kartu stok barang yang sedang dihitung dan juga lembar penghitungan stok;
4) Pencatat memastikan jumlah yang dihitung sama dengan angka yang tertulis di kartu stok, dan mencatatkannya di lembar penghitungan stok dan kartu stok serta menyerahkannya setelah ditandatangani kepada Pengelola Gudang ;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8013, '3. Stock opname dan pencatatan Merupakan suatu proses untuk mengawasi pergerakan stok, secara umum stock opname dilakukan sebulan sekali oleh Manajer gudang, Pengelola Gudang, Petugas Administrasi dan Juru Hitung.
Setiap bulannya manajer gudang berkewajiban mengeluarkan laporan stock opname kepada pimpinan BNPB/BPBD yang menyatakan posisi stok peralatan yang ada di dalam gudangnya. a) Sistem informasi gudang disini berlaku sejak penerimaan barang di gudang, penyimpanan barang, pemeliharaan barang, penghitungan stok dan pengeluaran barang dari gudang, dan dengan segala prosedurnya untuk memastikan semua data dapat tersimpan dengan baik di dalam sistem database, sehingga dapat menjamin keandalan sistem, dan dipercaya. b) Prosedur stock opname dan pencatatan 1) Bentuk tim stock opname dengan anggota minimal 2 orang, yang mana satu orang untuk melakukan penghitungan fisik barang dan satu orang lagi untuk pencatatan;
2) Pengelola Gudang memberikan lembar penghitungan stok periode tersebut kepada pencatat tim stock opname;
3) Pencatat memegang kartu stok barang yang sedang dihitung dan juga lembar penghitungan stok;
4) Pencatat memastikan jumlah yang dihitung sama dengan angka yang tertulis di kartu stok, dan mencatatkannya di lembar penghitungan stok dan kartu stok serta menyerahkannya setelah ditandatangani kepada Pengelola Gudang ;', 'Lampiran hal. 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8014, 'perka-3-2014', 28, 'lampiran', 'Lampiran hal. 20', NULL, 20, '5) Bila Pencatat menemukan ketidaksesuaian antara jumlah yang dihitung dengan kartu stok, maka pencatat tetap menuliskan angka penghitungannya kedalam Lembar Penghitungan Stok tapi tidak mencatatkannya ke dalam Kartu Stok, dan menyerahkan hasil temuannya tersebut kepada Pengelola Gudang untuk ditindak lanjuti hingga ditemukan penyebabnya. Bila ditemukan ketidaksesuaian maka Pengelola Gudang membuat Berita Acara Ketidaksesuaian Stok;
6) Pengelola Gudang akan mengkompilasi semua hasil penghitungan stok dalam lembar penghitungan stok (termasuk berita acara ketidaksesuaian stok, bila ada) dan melaporkannya setelah ditandatangani kepada Manajer Gudang;
21 2014, No.252 7) Manajer Gudang memeriksa hasil penghitungan stok secara seksama, dan bila disetujui segera memerintahkan kepada Pengelola Gudang untuk membuat laporan stok bulanan dan menandatanganinya serta menyerahkannya kepada Pimpinan BNPB/BPBD. c) Jangka waktu stock opname dan pencatatan Stock opname/penghitungan stok dilakukan secara berkala (paling tidak satu bulan satu kali) terhadap semua jenis barang peralatan yang ada di gudang. d) Dokumen stock opname meliputi :
1) Kartu Stok 2) Kartu Pemeliharaan Peralatan 3) Lembar Penghitungan Stok 4) Berita Acara Ketidaksesuaian Stok 5) Laporan Stok Bulanan D. Pengeluaran Barang Pengeluaran merupakan tahapan dimana gudang mengeluarkan barang ke daerah yang terdampak bencana atau daerah tujuan sesuai dengan instruksi dari pimpinan BNPB/BPBD yang berwenang kepada Manajer Gudang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8014, '5) Bila Pencatat menemukan ketidaksesuaian antara jumlah yang dihitung dengan kartu stok, maka pencatat tetap menuliskan angka penghitungannya kedalam Lembar Penghitungan Stok tapi tidak mencatatkannya ke dalam Kartu Stok, dan menyerahkan hasil temuannya tersebut kepada Pengelola Gudang untuk ditindak lanjuti hingga ditemukan penyebabnya. Bila ditemukan ketidaksesuaian maka Pengelola Gudang membuat Berita Acara Ketidaksesuaian Stok;
6) Pengelola Gudang akan mengkompilasi semua hasil penghitungan stok dalam lembar penghitungan stok (termasuk berita acara ketidaksesuaian stok, bila ada) dan melaporkannya setelah ditandatangani kepada Manajer Gudang;
21 2014, No.252 7) Manajer Gudang memeriksa hasil penghitungan stok secara seksama, dan bila disetujui segera memerintahkan kepada Pengelola Gudang untuk membuat laporan stok bulanan dan menandatanganinya serta menyerahkannya kepada Pimpinan BNPB/BPBD. c) Jangka waktu stock opname dan pencatatan Stock opname/penghitungan stok dilakukan secara berkala (paling tidak satu bulan satu kali) terhadap semua jenis barang peralatan yang ada di gudang. d) Dokumen stock opname meliputi :
1) Kartu Stok 2) Kartu Pemeliharaan Peralatan 3) Lembar Penghitungan Stok 4) Berita Acara Ketidaksesuaian Stok 5) Laporan Stok Bulanan D. Pengeluaran Barang Pengeluaran merupakan tahapan dimana gudang mengeluarkan barang ke daerah yang terdampak bencana atau daerah tujuan sesuai dengan instruksi dari pimpinan BNPB/BPBD yang berwenang kepada Manajer Gudang.', 'Lampiran hal. 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8015, 'perka-3-2014', 29, 'lampiran', 'Lampiran hal. 21', NULL, 21, '1. Penanggung Jawab Pengeluaran a) Manajer Gudang, bertanggung jawab untuk:
1) Memastikan barang yang dikeluarkan sesuai dengan instruksi pimpinan BNPB/BPBD yang berwenang;
2) Mengkoordinir petugas di bawahnya untuk proses pengeluaran barang;
3) Memastikan semua aktivitas pengeluaran barang tercatat. b) Pengelola Gudang 1) Memastikan barang yang dikeluarkan sesuai dengan yang telah diinstruksikan oleh Manajer Gudang;
2) Memastikan petugas di bawahnya melakukan proses pengeluaran dengan baik dan benar dan juga memperhatikan kualitas barang yang dikeluarkan;
3) Memastikan proses pengeluaran barang tercatat dan melaporkan segera apabila terjadi permasalahan kepada Manajer Gudang.
2014, No.252 22 c) Juru Hitung 1) Memastikan barang yang keluar dihitung sesuai dengan surat perintah pengeluaran;
2) Mengkoordinir buruh dan pihak pengangkutan;
3) Memastikan proses pengeluaran tercatat dan melaporkan segera apabila terjadi permasalahan kepada manajer gudang. d) Petugas keamanan 1) Memastikan keamanan selama proses pengeluran barang di gudang;
2) Membantu Juru Hitung dalam mengkoordinir buruh dan pihak pengangkutan;
3) Memastikan semua kendaraaan yang keluar dari lingkungan gudang dicatat;
4) Melaporkan segera apabila terjadi permasalahan kepada manajer gudang.
2. Formulir Pengeluaran dan pengangkutan Untuk mengeluarkan barang dari gudang diperlukan adanya formulir pengeluaran barang dapat dilihat pada Lampiran 4.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8015, '1. Penanggung Jawab Pengeluaran a) Manajer Gudang, bertanggung jawab untuk:
1) Memastikan barang yang dikeluarkan sesuai dengan instruksi pimpinan BNPB/BPBD yang berwenang;
2) Mengkoordinir petugas di bawahnya untuk proses pengeluaran barang;
3) Memastikan semua aktivitas pengeluaran barang tercatat. b) Pengelola Gudang 1) Memastikan barang yang dikeluarkan sesuai dengan yang telah diinstruksikan oleh Manajer Gudang;
2) Memastikan petugas di bawahnya melakukan proses pengeluaran dengan baik dan benar dan juga memperhatikan kualitas barang yang dikeluarkan;
3) Memastikan proses pengeluaran barang tercatat dan melaporkan segera apabila terjadi permasalahan kepada Manajer Gudang.
2014, No.252 22 c) Juru Hitung 1) Memastikan barang yang keluar dihitung sesuai dengan surat perintah pengeluaran;
2) Mengkoordinir buruh dan pihak pengangkutan;
3) Memastikan proses pengeluaran tercatat dan melaporkan segera apabila terjadi permasalahan kepada manajer gudang. d) Petugas keamanan 1) Memastikan keamanan selama proses pengeluran barang di gudang;
2) Membantu Juru Hitung dalam mengkoordinir buruh dan pihak pengangkutan;
3) Memastikan semua kendaraaan yang keluar dari lingkungan gudang dicatat;
4) Melaporkan segera apabila terjadi permasalahan kepada manajer gudang.
2. Formulir Pengeluaran dan pengangkutan Untuk mengeluarkan barang dari gudang diperlukan adanya formulir pengeluaran barang dapat dilihat pada Lampiran 4.', 'Lampiran hal. 21', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8016, 'perka-3-2014', 30, 'lampiran', 'Lampiran hal. 22', NULL, 22, 'Dalam pengeluaran barang dari gudang, sangat diperlukan pemahaman yang sama akan petunjuk pelaksanaan ini dan kerja sama yang baik oleh Pihak Pemohon, Pimpinan/Pejabat Bidang Logistik dan Peralatan BNPB, Pimpinan/Pejabat Biro Umum BNPB, Pejabat/Petugas BMN-BNPB, dan Manajer Gudang Peralatan. a) Prosedur Pengeluaran Peralatan dari Gudang 1) Manajer Gudang menerima surat permohonan pengeluaran barang peralatan dari Pimpinan BNPB/BPBD yang berwenang;
2) Manajer Gudang memerintahkan pengeluaran barang dari gudang dengan mengeluarkan Lembar Pengeluaran Barang yang ditandatanganinya dan juga ditandatangani pengambil barang dan menyerahkannya kepada Pengelola Gudang ;
3) Pengelola Gudang menyerahkan Lembar Pengeluaran Barang tersebut kepada Petugas Administrasi sebagai lanjutan persiapan pengeluaran barang dan menyerahkan Lembar Hitung kepada Juru Hitung;
4) Juru Hitung memilih, mengambil dan menghitung barang yang diminta, dan mencatatkannya ke dalam Lembar 23 2014, No.252 Hitung. Contoh Lembar Hitung dapat dilihat pada lampiran 5;
5) Petugas Administrasi menyaksikan pengambilan dan penghitungan barang yang dilakukan Juru Hitung, dan mencatatkannya ke dalam Kartu Stok barang;
6) Petugas pengambil barang/pengemudi kendaraan, Juru Hitung Gudang dan Petugas Administrasi Gudang menyaksikan proses muat barang ke dalam kendaraan pengangkut barang;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8016, 'Dalam pengeluaran barang dari gudang, sangat diperlukan pemahaman yang sama akan petunjuk pelaksanaan ini dan kerja sama yang baik oleh Pihak Pemohon, Pimpinan/Pejabat Bidang Logistik dan Peralatan BNPB, Pimpinan/Pejabat Biro Umum BNPB, Pejabat/Petugas BMN-BNPB, dan Manajer Gudang Peralatan. a) Prosedur Pengeluaran Peralatan dari Gudang 1) Manajer Gudang menerima surat permohonan pengeluaran barang peralatan dari Pimpinan BNPB/BPBD yang berwenang;
2) Manajer Gudang memerintahkan pengeluaran barang dari gudang dengan mengeluarkan Lembar Pengeluaran Barang yang ditandatanganinya dan juga ditandatangani pengambil barang dan menyerahkannya kepada Pengelola Gudang ;
3) Pengelola Gudang menyerahkan Lembar Pengeluaran Barang tersebut kepada Petugas Administrasi sebagai lanjutan persiapan pengeluaran barang dan menyerahkan Lembar Hitung kepada Juru Hitung;
4) Juru Hitung memilih, mengambil dan menghitung barang yang diminta, dan mencatatkannya ke dalam Lembar 23 2014, No.252 Hitung. Contoh Lembar Hitung dapat dilihat pada lampiran 5;
5) Petugas Administrasi menyaksikan pengambilan dan penghitungan barang yang dilakukan Juru Hitung, dan mencatatkannya ke dalam Kartu Stok barang;
6) Petugas pengambil barang/pengemudi kendaraan, Juru Hitung Gudang dan Petugas Administrasi Gudang menyaksikan proses muat barang ke dalam kendaraan pengangkut barang;', 'Lampiran hal. 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8017, 'perka-3-2014', 31, 'lampiran', 'Lampiran hal. 23', NULL, 23, '7) Setelah pemuatan barang selesai, maka Lembar Hitung yang sudah diisi dan ditandatangani oleh Juru Hitung Gudang, Petugas Pengambil Barang/pengemudi kendaraan dan Petugas Administrasi Gudang diserahkan kepada Pengelola Gudang ;
8) Pengelola Gudang akan membuat Surat Jalan (rangkap-4) dan diserahkan kepada Manajer Gudang untuk ditandatangani dengan melampirkan Lembar Hitung dan Lembar Pengeluaran Barang;
9) Manajer Gudang menandatangani Surat Jalan (rangkap-4) dan menyerahkan kembali kepada Pengelola Gudang untuk selanjutnya diserahkan kepada Petugas Administrasi;
10) Petugas Administrasi memberikan Surat Jalan (rangkap-4) kepada pengambil barang/pengemudi kendaraan untuk ditandatangani. Distribusi Surat Jalan sebagai berikut:
(a) Rangkap satu dan dua, untuk pengambil barang/pengemudi kendaraan;
(b) Rangkap ketiga, diberikan kepada petugas keamanan gudang dan sebagai tanda bukti bahwa barang sudah diizinkan oleh Manajer Gudang untuk meninggalkan area gudang;
(c) Rangkap keempat, untuk pertinggal dan diserahkan kepada Store Keeper untuk diarsipkan. b) Dokumentasi/pencatatan pengeluaran barang dari gudang meliputi:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8017, '7) Setelah pemuatan barang selesai, maka Lembar Hitung yang sudah diisi dan ditandatangani oleh Juru Hitung Gudang, Petugas Pengambil Barang/pengemudi kendaraan dan Petugas Administrasi Gudang diserahkan kepada Pengelola Gudang ;
8) Pengelola Gudang akan membuat Surat Jalan (rangkap-4) dan diserahkan kepada Manajer Gudang untuk ditandatangani dengan melampirkan Lembar Hitung dan Lembar Pengeluaran Barang;
9) Manajer Gudang menandatangani Surat Jalan (rangkap-4) dan menyerahkan kembali kepada Pengelola Gudang untuk selanjutnya diserahkan kepada Petugas Administrasi;
10) Petugas Administrasi memberikan Surat Jalan (rangkap-4) kepada pengambil barang/pengemudi kendaraan untuk ditandatangani. Distribusi Surat Jalan sebagai berikut:
(a) Rangkap satu dan dua, untuk pengambil barang/pengemudi kendaraan;
(b) Rangkap ketiga, diberikan kepada petugas keamanan gudang dan sebagai tanda bukti bahwa barang sudah diizinkan oleh Manajer Gudang untuk meninggalkan area gudang;
(c) Rangkap keempat, untuk pertinggal dan diserahkan kepada Store Keeper untuk diarsipkan. b) Dokumentasi/pencatatan pengeluaran barang dari gudang meliputi:', 'Lampiran hal. 23', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2014 tentang Petunjuk Pelaksanaan Operasional Gudang Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8018, 'perka-3-2014', 32, 'lampiran', 'Lampiran hal. 23', NULL, 23, '1) Lembar instruksi pengeluaran barang 2) Lembar Hitung 3) Kartu Stok 4) Surat Jalan rangkap-4 (empat) 2014, No.252 24 BAB IV PENUTUP Sebagai penjelasan yang lebih teknis dari Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan Penanggulangan Bencana, Petunjuk Pelaksanaan Opersional Gudang Peralatan Penanggulangan Bencana ini diharapkan dapat bermanfaat dan membantu dalam mengelola dan mengoperasionalkan gudang penyimpanan peralatan Penanggulangan Bencana. Walaupun ada keterbatasan dalam jumlah maupun spesifikasi peralatan yang tersedia, namun dengan pengelolaan yang baik diharapkan dapat membantu pemanfaatan dan pendistribusian peralatan secara cepat dan tepat.
Sesuai dengan perkembangan, petunjuk pelaksanaan ini terbuka untuk disesuaikan dan diperbaiki. Adapun referensi lain tentang operasional pergudangan, dapat juga dimanfaatkan sepanjang tidak bertentangan dengan petunjuk pelaksanaan ini.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF 25 2014, No.252 LAMPIRAN II PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 3 TAHUN 2014 TENTANG PETUNJUK PELAKSANAAN OPERASIONAL GUDANG PERALATAN PENANGGULANGAN BENCANA CONTOH FORMULIR PENERIMAAN BARANG Nama Gudang :
