INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8021, 'perka-3-2014', 35, 'lampiran', 'Lampiran hal. 30', NULL, 30, '• Harus ada minimal 70 cm atau lebih, jarak gang (antara) tumpukan, dan antara tumpukan dengan dinding atau tiang. Jarak gang (antara) ini mungkin harus ditingkatkan untuk memungkinkan penanganan yang efisien.
• Lebar akses masuk akan tergantung pada jenis truk / kendaraan angkutan yang masuk ke gudang dan jenis peralatan penanganan (jika ada) yang akan digunakan
• Pasang poster yang mudah dilihat, rencana lantai dan rincian item peralatan yang sebenarnya disimpan dalam setiap zona gudang.');
