INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8023, 'perka-3-2015', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka mewujudkan proses pelaksanaan anggaran yang tertib, efisien, ekonomis, efektif, transparan, dan akuntabel, perlu didukung prasarana dan sarana kerja yang memadai;
b. bahwa mekanisme dari surat permintaan pembayaran sampai dengan penerbitan surat perintah membayar serta adanya informasi hasil verifikasi dan keuangan, perlu dikonsentrasikan di dalam ruangan yang terintegrasi;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Layanan Operasional Keuangan Terintegrasi di Lingkungan Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8023, 'a. bahwa dalam rangka mewujudkan proses pelaksanaan anggaran yang tertib, efisien, ekonomis, efektif, transparan, dan akuntabel, perlu didukung prasarana dan sarana kerja yang memadai;
