INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8025, 'perka-3-2015', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG LAYANAN OPERASIONAL KEUANGAN TERINTEGRASI DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8025, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG LAYANAN OPERASIONAL KEUANGAN TERINTEGRASI DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2015 tentang Layanan Operasional Keuangan Terintegrasi di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8026, 'perka-3-2015', 4, 'pasal', 'Pasal 1', 'BAB II MAKSUD DAN TUJUAN', 3, 'Dalam Peraturan Kepala Badan ini, yang dimaksud dengan:
1. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat BNPB adalah lembaga pemerintah Nonkementerian sesuai dengan ketentuan peraturan perundang-undangan.
2. Anggaran Pendapatan dan Belanja Negara, yang selanjutnya disingkat APBN adalah rencana keuangan tahunan pemerintahan negara yang disetujui oleh Dewan Perwakilan Rakyat.
3. Daftar Isian Pelaksanaan Anggaran, yang selanjutnya disingkat DIPA adalah Dokumen Pelaksanaan Anggaran yang digunakan sebagai acuan Pengguna Anggaran dalam melaksanakan kegiatan pemerintahan sebagai pelaksanaan APBN.
4. Pengguna Anggaran, yang selanjutnya disingkat PA adalah pejabat pemegang kewenangan penggunaan anggaran kementerian/lembaga.
5. Kuasa Pengguna Anggaran, yang selanjutnya disingkat KPA adalah pejabat yang memperoleh kuasa dari Pengguna Anggaran untuk melaksanakan sebagian kewenangan dan tanggung jawab penggunaan anggaran pada kementerian /lembaga yang bersangkutan.
6. Kantor Pelayanan Perbendaharaan Negara, yang selanjutnya disingkat KPPN adalah instansi vertikal Direktorat Jenderal Perbendaharaan yang memperoleh kuasa dari Bendahara Umum Negara untuk melaksanakan sebagian fungsi Kuasa Bendahara Umum Negara.
7. Unit kerja adalah satuan organisasi dari Badan Nasional Penanggulangan Bencana yang melaksanakan kegiatan serta memiliki kewenangan dan tanggung jawab penggunaan anggaran.
8. Pejabat Pembuat Komitmen, yang selanjutnya disingkat PPK adalah pejabat yang melaksanakan kewenangan Pengguna Anggaran/Kuasa Pengguna Anggaran untuk mengambil keputusan dan/atau tindakan yang dapat mengakibatkan pengeluaran atas beban Anggaran Pendapatan dan Belanja Negara.
9. Pejabat Penanda Tangan Surat Perintah Membayar, yang selanjutnya disingkat PPSPM adalah pejabat yang diberi kewenangan oleh Pengguna Anggaran/Kuasa Pengguna Anggaran untuk melakukan pengujian atas permintaan pembayaran dan menerbitkan perintah pembayaran.
2015, No.1461 4
10. Bendahara Pengeluaran adalah orang yang ditunjuk untuk menerima, menyimpan, membayarkan, menatausahakan, dan mempertanggungjawabkan uang untuk keperluan Belanja Negara dalam pelaksanaan Anggaran Pendapatan dan Belanja Negara pada kantor/satuan kerja kementerian/lembaga.
11. Bendahara pengeluaran Pembantu, yang selanjutnya disingkat BPP adalah orang yang ditunjuk untuk membantu bendahara pengeluaran untuk melaksanakan pembayaran kepada yang berhak guna kelancaran pelaksanaan kegiatan tertentu.
12. Petugas Pengelolaan Administrasi Belanja Pegawai, yang selanjutnya disingkat PPABP adalah pembantu Kuasa Pengguna Anggaran yang diberi tugas dan tanggung jawab untuk mengelola pelaksanaan belanja pegawai.
13. Uang Persediaan, yang selanjutnya disingkat UP adalah uang muka kerja dalam jumlah tertentu yang diberikan kepada bendahara pengeluaran untuk membiayai kegiatan operasional sehari-hari satuan kerja atau membiayai pengeluaran yang menurut sifat dan tujuannya tidak mungkin dilakukan melalui mekanisme pembayaran langsung.
14. Pembayaran Langsung, yang selanjutnya disingkat pembayaran LS adalah pembayaran yang dilakukan langsung kepada bendahara pengeluaran/penerima hak lainnya atas dasar perjanjian kerja, surat keputusan, surat tugas atau surat perintah kerja lainnya melalui penerbitan Surat Perintah Membayar Langsung.
15. Tambahan Uang Persediaan yang selanjutnya disingkat TUP adalah uang muka yang diberikan kepada bendahara pengeluaran untuk kebutuhan yang sangat mendesak dalam 1 (satu) bulan melebihi pagu uang persediaan yang telah ditetapkan.
16. Pertanggungjawaban Tambahan Uang Persediaan, yang selanjutnya disingkat PTUP adalah pertanggungjawaban atas tambahan uang persediaan.
17. Surat Permintaan Pembayaran, yang selanjutnya disingkat SPP adalah dokumen yang diterbitkan oleh Pejabat Pembuat Komitmen, yang berisi permintaan pembayaran tagihan kepada negara.
18. Surat Permintaan Pembayaran Langsung, yang selanjutnya disingkat SPP-LS adalah dokumen yang diterbitkan oleh Pejabat Pembuat Komitmen, dalam rangka pembayaran tagihan kepada penerima hak/bendahara pengeluaran.
19. Surat Permintaan Pembayaran Uang Persediaan, yang selanjutnya disingkat SPP-UP adalah dokumen yang diterbitkan oleh Pejabat Pembuat Komitmen, yang berisi permintaan pembayaran uang persediaan.
5 2015, No.1461
20. Surat Permintaan Pembayaran Tambahan Uang Persediaan, yang selanjutnya disingkat SPP-TUP adalah dokumen yang diterbitkan oleh Pejabat Pembuat Komitmen, yang berisi permintaan pembayaran tambahan uang persediaan.
21. Surat Permintaan Pembayaran Penggantian Uang Persediaan, yang selanjutnya disingkat SPP-GUP adalah dokumen yang diterbitkan oleh Pejabat Pembuat Komitmen, yang berisi pertanggungjawaban dan permintaan kembali pembayaran uang persediaan.
22. Surat Permintaan Pembayaran Penggantian Uang Persediaan Nihil, yang selanjutnya disingkat SPP-GUP Nihil adalah dokumen yang diterbitkan oleh Pejabat Pembuat Komitmen, yang berisi pertanggungjawaban uang persediaan.
23. Surat Permintaan Pembayaran Pertanggungjawaban Tambahan Uang Persediaan, yang selanjutnya disingkat SPP-PTUP adalah dokumen yang diterbitkan oleh Pejabat Pembuat Komitmen, yang berisi permintaan pertanggungjawaban atas tambahan uang persediaan.
24. Surat Perintah Membayar, yang selanjutnya disingkat SPM adalah dokumen yang diterbitkan oleh Pejabat Penanda Tangan Surat Perintah Membayar untuk mencairkan dana yang bersumber dari Daftar Isian Pelaksanaan Anggaran.
25. Surat Perintah Membayar Langsung, yang selanjutnya disingkat SPM-LS adalah dokumen yang diterbitkan oleh Pejabat Penanda Tangan Surat Perintah Membayar untuk mencairkan dana yang bersumber dari Daftar Isian Pelaksanaan Anggaran dalam rangka pembayaran tagihan kepada penerima hak/bendahara pengeluaran.
26. Surat Perintah Membayar Uang Persediaan, yang selanjutnya disingkat SPM-UP adalah dokumen yang diterbitkan oleh Pejabat Penanda Tangan Surat Perintah Membayar untuk mencairkan uang persediaan.');
