INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8044, 'perka-3-2015', 22, 'pasal', 'Pasal 18', 'BAB V TUGAS, JAM KERJA DAN PROSEDUR, SERTA TATA TERTIB LOKET; Bagian Kesatu Tugas', 9, 'Koordinator bertugas:
