INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8045, 'perka-3-2015', 23, 'pasal', 'Pasal 19', 'BAB V TUGAS, JAM KERJA DAN PROSEDUR, SERTA TATA TERTIB LOKET; Bagian Kedua Jam Kerja dan Prosedur', 9, 'PPSPM bertugas:
