INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8050, 'perka-3-2016', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa penyelenggaraan penanggulangan bencana pada saat status keadaan darurat bencana telah diatur dalam Pasal 47 ayat (1) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana dan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana dalam implementasinya sudah tidak sesuai lagi dengan ketentuan perkembangan penyelenggaraan penanganan darurat bencana sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Sistem Komando Penanganan Darurat Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8050, 'a. bahwa penyelenggaraan penanggulangan bencana pada saat status keadaan darurat bencana telah diatur dalam Pasal 47 ayat (1) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana;
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2008 tentang Pedoman Komando Tanggap Darurat Bencana dan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 14 Tahun 2010 tentang Pedoman Pembentukan Pos Komando Tanggap Darurat Bencana dalam implementasinya sudah tidak sesuai lagi dengan ketentuan perkembangan penyelenggaraan penanganan darurat bencana sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Sistem Komando Penanganan Darurat Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8051, 'perka-3-2016', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 5494);
2. Undang-Undang Republik Indonesia Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 244, Tambahan Lembaran Negara Republik Indonesia Nomor 5587) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor Nomor 9 tahun 2015 tentang Perubahan Kedua atas Undang-Undang Republik Indonesia Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2015 Nomor 58, Tambahan Lembaran Negara Republik Indonesia Nomor 5679);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8051, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 5494);
2. Undang-Undang Republik Indonesia Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 244, Tambahan Lembaran Negara Republik Indonesia Nomor 5587) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor Nomor 9 tahun 2015 tentang Perubahan Kedua atas Undang-Undang Republik Indonesia Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2015 Nomor 58, Tambahan Lembaran Negara Republik Indonesia Nomor 5679);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8052, 'perka-3-2016', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG SISTEM KOMANDO PENANGANAN DARURAT BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8052, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG SISTEM KOMANDO PENANGANAN DARURAT BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8053, 'perka-3-2016', 4, 'pasal', 'Pasal 1', 'BAB II PRINSIP', 3, 'Dalam Peraturan Kepala Badan ini yang dimaksud dengan:
1. Keadaan Darurat Bencana adalah suatu keadaan yang mengancam dan mengganggu kehidupan dan penghidupan sekelompok orang/masyarakat yang memerlukan tindakan penanganan segera dan memadai.
2. Status Keadaan Darurat Bencana adalah Keadaan Darurat Bencana yang ditetapkan oleh Pemerintah atau pemerintah daerah untuk jangka waktu tertentu atas dasar rekomendasi badan yang menyelenggarakan urusan di bidang penanggulangan bencana dimulai sejak status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.
3. Status Siaga Darurat adalah keadaan ketika potensi ancaman bencana sudah mengarah pada terjadinya bencana yang ditandai dengan adanya informasi peningkatan ancaman berdasarkan sistem peringatan dini yang diberlakukan dan pertimbangan dampak yang akan terjadi di masyarakat.
4. Status Tanggap Darurat adalah keadaan ketika ancaman bencana terjadi dan telah mengganggu kehidupan dan penghidupan sekelompok orang/masyarakat.
5. Status Transisi Darurat ke Pemulihan adalah keadaan ketika ancaman bencana yang terjadi cenderung menurun eskalasinya dan/atau telah berakhir, sedangkan gangguan kehidupan dan penghidupan sekelompok orang/masyarakat masih tetap berlangsung.
6. Penanganan Darurat Bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada keadaan darurat bencana untuk mengendalikan ancaman/penyebab bencana dan menanggulangi dampak yang ditimbulkan.
7. Bantuan Penanganan Darurat Bencana adalah bantuan untuk mengendalikan ancaman/penyebab bencana dan menanggulangi dampak yang ditimbulkan pada keadaan darurat bencana.
8. Komando adalah kewenangan untuk memberikan perintah, mengoordinasikan, mengendalikan, memantau dan mengevaluasi upaya penanganan darurat bencana.
9. Sistem Komando Penanganan Darurat Bencana adalah satu kesatuan upaya terstruktur dalam satu komando yang digunakan untuk mengintegrasikan kegiatan penanganan darurat secara efektif dan efisien dalam mengendalikan ancaman/penyebab bencana dan menanggulangi dampak pada saat keadaan darurat bencana.
10. Pos Komando Penanganan Darurat Bencana yang selanjutnya disingkat Posko PDB adalah institusi yang berfungsi sebagai pusat komando operasi penanganan darurat bencana yang merupakan posko utama di dalam Sistem Komando Penanganan Darurat Bencana, untuk mengoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan penanganan darurat bencana.
11. Pos Lapangan Penanganan Darurat Bencana yang selanjutnya disebut Pos Lapangan PDB adalah institusi yang berfungsi secara langsung sebagai pelaksana operasi penanganan darurat bencana baik di lokasi bencana, sekitar lokasi bencana maupun lokasi pengungsian.
12. Pos Pendukung Penanganan Darurat Bencana yang selanjutnya disebut Pos Pendukung PDB adalah institusi yang berfungsi membantu kelancaran akses masuk, keluar, dan mobilisasi/distribusi bantuan penanganan darurat bencana dari luar wilayah terdampak.
13. Pos Pendamping Penanganan Darurat Bencana adalah institusi yang berperan mengoordinasikan mobilisasi bantuan penanganan darurat bencana meliputi pos pendamping nasional penanganan darurat bencana, pos pendamping penanganan darurat bencana provinsi, dan pos pendamping penanganan darurat bencana wilayah.
14. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
15. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara pemerintahan daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
16. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan.
17. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
18. Komunitas Internasional adalah lembaga internasional, lembaga asing nonpemerintah, negara sahabat, atau perseorangan warga negara asing.
19. Klaster adalah pengelompokan para pelaku yang memiliki kompetensi sama dari Pemerintah atau pemerintah daerah, lembaga nonpemerintah, sektor swasta/lembaga usaha, dan kelompok masyarakat dalam upaya penanganan darurat bencana, dipimpin oleh koordinator yang berasal dari instansi/lembaga yang memiliki kewenangan teknis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8053, 'Dalam Peraturan Kepala Badan ini yang dimaksud dengan:
1. Keadaan Darurat Bencana adalah suatu keadaan yang mengancam dan mengganggu kehidupan dan penghidupan sekelompok orang/masyarakat yang memerlukan tindakan penanganan segera dan memadai.
2. Status Keadaan Darurat Bencana adalah Keadaan Darurat Bencana yang ditetapkan oleh Pemerintah atau pemerintah daerah untuk jangka waktu tertentu atas dasar rekomendasi badan yang menyelenggarakan urusan di bidang penanggulangan bencana dimulai sejak status siaga darurat, tanggap darurat dan transisi darurat ke pemulihan.
3. Status Siaga Darurat adalah keadaan ketika potensi ancaman bencana sudah mengarah pada terjadinya bencana yang ditandai dengan adanya informasi peningkatan ancaman berdasarkan sistem peringatan dini yang diberlakukan dan pertimbangan dampak yang akan terjadi di masyarakat.
4. Status Tanggap Darurat adalah keadaan ketika ancaman bencana terjadi dan telah mengganggu kehidupan dan penghidupan sekelompok orang/masyarakat.
5. Status Transisi Darurat ke Pemulihan adalah keadaan ketika ancaman bencana yang terjadi cenderung menurun eskalasinya dan/atau telah berakhir, sedangkan gangguan kehidupan dan penghidupan sekelompok orang/masyarakat masih tetap berlangsung.
6. Penanganan Darurat Bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada keadaan darurat bencana untuk mengendalikan ancaman/penyebab bencana dan menanggulangi dampak yang ditimbulkan.
7. Bantuan Penanganan Darurat Bencana adalah bantuan untuk mengendalikan ancaman/penyebab bencana dan menanggulangi dampak yang ditimbulkan pada keadaan darurat bencana.
8. Komando adalah kewenangan untuk memberikan perintah, mengoordinasikan, mengendalikan, memantau dan mengevaluasi upaya penanganan darurat bencana.
9. Sistem Komando Penanganan Darurat Bencana adalah satu kesatuan upaya terstruktur dalam satu komando yang digunakan untuk mengintegrasikan kegiatan penanganan darurat secara efektif dan efisien dalam mengendalikan ancaman/penyebab bencana dan menanggulangi dampak pada saat keadaan darurat bencana.
10. Pos Komando Penanganan Darurat Bencana yang selanjutnya disingkat Posko PDB adalah institusi yang berfungsi sebagai pusat komando operasi penanganan darurat bencana yang merupakan posko utama di dalam Sistem Komando Penanganan Darurat Bencana, untuk mengoordinasikan, mengendalikan, memantau dan mengevaluasi pelaksanaan penanganan darurat bencana.
11. Pos Lapangan Penanganan Darurat Bencana yang selanjutnya disebut Pos Lapangan PDB adalah institusi yang berfungsi secara langsung sebagai pelaksana operasi penanganan darurat bencana baik di lokasi bencana, sekitar lokasi bencana maupun lokasi pengungsian.
12. Pos Pendukung Penanganan Darurat Bencana yang selanjutnya disebut Pos Pendukung PDB adalah institusi yang berfungsi membantu kelancaran akses masuk, keluar, dan mobilisasi/distribusi bantuan penanganan darurat bencana dari luar wilayah terdampak.
13. Pos Pendamping Penanganan Darurat Bencana adalah institusi yang berperan mengoordinasikan mobilisasi bantuan penanganan darurat bencana meliputi pos pendamping nasional penanganan darurat bencana, pos pendamping penanganan darurat bencana provinsi, dan pos pendamping penanganan darurat bencana wilayah.
14. Pemerintah Pusat adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan negara Republik Indonesia yang dibantu oleh Wakil Presiden dan menteri sebagaimana dimaksud dalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.
15. Pemerintah Daerah adalah kepala daerah sebagai unsur penyelenggara pemerintahan daerah yang memimpin pelaksanaan urusan pemerintahan yang menjadi kewenangan daerah otonom.
16. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah nonkementerian yang melakukan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan peraturan perundang-undangan.
17. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
18. Komunitas Internasional adalah lembaga internasional, lembaga asing nonpemerintah, negara sahabat, atau perseorangan warga negara asing.
19. Klaster adalah pengelompokan para pelaku yang memiliki kompetensi sama dari Pemerintah atau pemerintah daerah, lembaga nonpemerintah, sektor swasta/lembaga usaha, dan kelompok masyarakat dalam upaya penanganan darurat bencana, dipimpin oleh koordinator yang berasal dari instansi/lembaga yang memiliki kewenangan teknis.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8054, 'perka-3-2016', 5, 'pasal', 'Pasal 2', 'BAB III AKTIVASI SISTEM KOMANDO PENANGANAN DARURAT BENCANA; Bagian Kesatu Aktivasi', 6, 'Penyelenggaraan penanganan darurat bencana dilaksanakan berdasarkan prinsip:
a. pengutamaan peran aktif pemerintah daerah kabupaten/kota; dan
b. pemerintah dan pemerintah daerah provinsi bertanggung jawab melakukan pendampingan terhadap pemerintah daerah kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8054, 'Penyelenggaraan penanganan darurat bencana dilaksanakan berdasarkan prinsip:
a. pengutamaan peran aktif pemerintah daerah kabupaten/kota; dan
b. pemerintah dan pemerintah daerah provinsi bertanggung jawab melakukan pendampingan terhadap pemerintah daerah kabupaten/kota.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8055, 'perka-3-2016', 6, 'pasal', 'Pasal 3', 'BAB III AKTIVASI SISTEM KOMANDO PENANGANAN DARURAT BENCANA; Bagian Kedua Perangkat Sistem Komando Penanganan Darurat Bencana', 6, '(1) Penyelenggaraan penanganan darurat bencana dilaksanakan melalui sistem komando penanganan darurat bencana yang diaktivasi berdasarkan penetapan status keadaan darurat bencana sesuai dengan ketentuan peraturan perundang-undangan.
(2) Penyelenggaraan sistem komando penanganan darurat bencana dibedakan berdasarkan:
a. status keadaan darurat bencana kabupaten/kota untuk kejadian bencana pada:
1. satu kabupaten/kota terdampak;
2. beberapa kabupaten/kota dalam satu provinsi; dan
3. beberapa kabupaten/kota di beberapa provinsi;
b. status keadaan darurat bencana provinsi untuk kejadian bencana pada satu atau lebih dari satu kabupaten/kota dalam satu provinsi; dan
c. status keadaan darurat bencana nasional.
(3) Penyelenggaraan sistem komando penanganan darurat bencana sebagaimana dimaksud pada ayat (2) disesuaikan dengan status keadaan darurat bencana yang diberlakukan, yaitu status siaga darurat, status tanggap darurat, dan status transisi darurat ke pemulihan.
(4) Ketentuan lebih lanjut mengenai sistem komando penanganan darurat bencana diatur dengan petunjuk pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8055, '(1) Penyelenggaraan penanganan darurat bencana dilaksanakan melalui sistem komando penanganan darurat bencana yang diaktivasi berdasarkan penetapan status keadaan darurat bencana sesuai dengan ketentuan peraturan perundang-undangan.
(2) Penyelenggaraan sistem komando penanganan darurat bencana dibedakan berdasarkan:
a. status keadaan darurat bencana kabupaten/kota untuk kejadian bencana pada:
1. satu kabupaten/kota terdampak;
2. beberapa kabupaten/kota dalam satu provinsi; dan
3. beberapa kabupaten/kota di beberapa provinsi;
b. status keadaan darurat bencana provinsi untuk kejadian bencana pada satu atau lebih dari satu kabupaten/kota dalam satu provinsi; dan
c. status keadaan darurat bencana nasional.
(3) Penyelenggaraan sistem komando penanganan darurat bencana sebagaimana dimaksud pada ayat (2) disesuaikan dengan status keadaan darurat bencana yang diberlakukan, yaitu status siaga darurat, status tanggap darurat, dan status transisi darurat ke pemulihan.
(4) Ketentuan lebih lanjut mengenai sistem komando penanganan darurat bencana diatur dengan petunjuk pelaksana.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8056, 'perka-3-2016', 7, 'pasal', 'Pasal 4', 'BAB IV PENYELENGGARAAN SISTEM KOMANDO PENANGANAN DARURAT BENCANA; Bagian Kesatu Status Keadaan Darurat Bencana Kabupaten/Kota', 7, 'Perangkat Sistem Komando Penanganan Darurat Bencana dalam penyelenggaraannya mencakup:
a. Posko PDB sebagai perangkat pengendali operasi;
b. Pos Lapangan PDB sebagai perangkat pelaksana operasi;
c. Pos Pendukung PDB sebagai perangkat pendukung operasi; dan
d. Pos Pendamping PDB sebagai perangkat pendamping operasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8056, 'Perangkat Sistem Komando Penanganan Darurat Bencana dalam penyelenggaraannya mencakup:
a. Posko PDB sebagai perangkat pengendali operasi;
b. Pos Lapangan PDB sebagai perangkat pelaksana operasi;
c. Pos Pendukung PDB sebagai perangkat pendukung operasi; dan
d. Pos Pendamping PDB sebagai perangkat pendamping operasi.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8057, 'perka-3-2016', 8, 'pasal', 'Pasal 5', 'BAB IV PENYELENGGARAAN SISTEM KOMANDO PENANGANAN DARURAT BENCANA; Bagian Kedua Status Keadaan Darurat Bencana Provinsi', 8, '(1) Pada saat status keadaan darurat bencana kabupaten/kota ditetapkan perangkat yang diaktifkan terdiri atas:
a. Posko PDB kabupaten/kota;
b. Pos Lapangan PDB;
c. Pos Pendukung PDB;
d. Pos Pendamping PDB provinsi; dan
e. Pos Pendamping Nasional PDB.
(2) Pos sebagaimana dimaksud pada ayat (1) huruf c, huruf d, dan huruf e diaktifkan apabila diperlukan.
(3) Dalam hal status keadaan darurat bencana ditetapkan di beberapa kabupaten/kota dalam 1 (satu) provinsi perangkat yang diaktifkan sebagaimana dimaksud pada ayat (1) dan ayat (2).
(4) Dalam hal status keadaan darurat bencana ditetapkan pada beberapa kabupaten/kota di beberapa provinsi maka perangkat yang diaktifkan sebagaimana dimaksud pada ayat (1) dan ayat (2).
(5) Ketentuan lebih lanjut mengenai mekanisme penyelenggaraan Sistem Komando Penanganan Darurat Bencana diatur dengan petunjuk pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8057, '(1) Pada saat status keadaan darurat bencana kabupaten/kota ditetapkan perangkat yang diaktifkan terdiri atas:
a. Posko PDB kabupaten/kota;
b. Pos Lapangan PDB;
c. Pos Pendukung PDB;
d. Pos Pendamping PDB provinsi; dan
e. Pos Pendamping Nasional PDB.
(2) Pos sebagaimana dimaksud pada ayat (1) huruf c, huruf d, dan huruf e diaktifkan apabila diperlukan.
(3) Dalam hal status keadaan darurat bencana ditetapkan di beberapa kabupaten/kota dalam 1 (satu) provinsi perangkat yang diaktifkan sebagaimana dimaksud pada ayat (1) dan ayat (2).
(4) Dalam hal status keadaan darurat bencana ditetapkan pada beberapa kabupaten/kota di beberapa provinsi maka perangkat yang diaktifkan sebagaimana dimaksud pada ayat (1) dan ayat (2).
(5) Ketentuan lebih lanjut mengenai mekanisme penyelenggaraan Sistem Komando Penanganan Darurat Bencana diatur dengan petunjuk pelaksana.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8058, 'perka-3-2016', 9, 'pasal', 'Pasal 6', 'BAB IV PENYELENGGARAAN SISTEM KOMANDO PENANGANAN DARURAT BENCANA; Bagian Ketiga Status Keadaan Darurat Bencana Nasional', 9, '(1) Pada saat status keadaan darurat bencana provinsi ditetapkan, maka perangkat yang diaktifkan terdiri atas:
a. Posko PDB Provinsi;
b. Pos Lapangan PDB;
c. Pos Pendukung PDB; dan
d. Pos Pendamping Nasional PDB.
(2) Pos sebagaimana dimaksud pada ayat (1) huruf c dan huruf huruf d, diaktifkan apabila diperlukan.
(3) Ketentuan lebih lanjut mengenai mekanisme penyelenggaraan Sistem Komando Penanganan Darurat Bencana diatur dengan petunjuk pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8058, '(1) Pada saat status keadaan darurat bencana provinsi ditetapkan, maka perangkat yang diaktifkan terdiri atas:
a. Posko PDB Provinsi;
b. Pos Lapangan PDB;
c. Pos Pendukung PDB; dan
d. Pos Pendamping Nasional PDB.
(2) Pos sebagaimana dimaksud pada ayat (1) huruf c dan huruf huruf d, diaktifkan apabila diperlukan.
(3) Ketentuan lebih lanjut mengenai mekanisme penyelenggaraan Sistem Komando Penanganan Darurat Bencana diatur dengan petunjuk pelaksana.', 'Pasal 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8059, 'perka-3-2016', 10, 'pasal', 'Pasal 7', 'BAB V KEDUDUKAN, TUGAS, FUNGSI DAN STRUKTUR ORGANISASI POS KOMANDO PENANGANAN DARURAT BENCANA; Bagian Kesatu Kedudukan', 9, '(1) Pada saat status keadaan darurat bencana nasional ditetapkan, maka perangkat yang diaktifkan terdiri atas:
a. Posko Nasional PDB;
b. Pos Lapangan PDB;
c. Pos Pendukung PDB; dan
d. Pos Pendamping PDB wilayah.
(2) Pos sebagaimana dimaksud pada ayat (1) huruf c dan huruf d, diaktifkan apabila diperlukan.
(3) Ketentuan lebih lanjut mengenai mekanisme penyelenggaraan Sistem Komando Penanganan Darurat Bencana diatur dengan petunjuk pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8059, '(1) Pada saat status keadaan darurat bencana nasional ditetapkan, maka perangkat yang diaktifkan terdiri atas:
a. Posko Nasional PDB;
b. Pos Lapangan PDB;
c. Pos Pendukung PDB; dan
d. Pos Pendamping PDB wilayah.
(2) Pos sebagaimana dimaksud pada ayat (1) huruf c dan huruf d, diaktifkan apabila diperlukan.
(3) Ketentuan lebih lanjut mengenai mekanisme penyelenggaraan Sistem Komando Penanganan Darurat Bencana diatur dengan petunjuk pelaksana.', 'Pasal 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8060, 'perka-3-2016', 11, 'pasal', 'Pasal 8', 'BAB V KEDUDUKAN, TUGAS, FUNGSI DAN STRUKTUR ORGANISASI POS KOMANDO PENANGANAN DARURAT BENCANA; Bagian Kedua Tugas Dan Fungsi', 10, '(1) Pada saat status keadaan darurat bencana kabupaten/kota ditetapkan, Posko PDB berkedudukan di ibukota kabupaten/kota atau di wilayah lain yang masih berada di dalam kabupaten/kota bersangkutan dengan mempertimbangkan kemudahan akses dan efektifitas.
(2) Pada saat status keadaan darurat bencana provinsi ditetapkan, Posko PDB berkedudukan di ibukota provinsi atau di wilayah lain yang masih berada di dalam wilayah provinsi bersangkutan dengan mempertimbangkan kemudahan akses dan efektifitas.
(3) Pada saat status keadaan darurat bencana nasional ditetapkan, Posko Nasional PDB berkedudukan di ibukota negara atau wilayah lain di Indonesia dengan mempertimbangkan kemudahan akses dan efektifitas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8060, '(1) Pada saat status keadaan darurat bencana kabupaten/kota ditetapkan, Posko PDB berkedudukan di ibukota kabupaten/kota atau di wilayah lain yang masih berada di dalam kabupaten/kota bersangkutan dengan mempertimbangkan kemudahan akses dan efektifitas.
(2) Pada saat status keadaan darurat bencana provinsi ditetapkan, Posko PDB berkedudukan di ibukota provinsi atau di wilayah lain yang masih berada di dalam wilayah provinsi bersangkutan dengan mempertimbangkan kemudahan akses dan efektifitas.
(3) Pada saat status keadaan darurat bencana nasional ditetapkan, Posko Nasional PDB berkedudukan di ibukota negara atau wilayah lain di Indonesia dengan mempertimbangkan kemudahan akses dan efektifitas.', 'Pasal 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8061, 'perka-3-2016', 12, 'pasal', 'Pasal 9', 'BAB V KEDUDUKAN, TUGAS, FUNGSI DAN STRUKTUR ORGANISASI POS KOMANDO PENANGANAN DARURAT BENCANA; Bagian Ketiga Struktur Organisasi Pos Komando Penanganan Darurat', 10, '(1) Pos komando mempunyai tugas:
a. melakukan kajian pemenuhan kebutuhan penanganan darurat bencana berdasarkan hasil kaji cepat dan rencana kontinjensi;
b. melakukan kajian awal upaya/rencana kegiatan rehabilitasi dan rekonstruksi;
c. menyusun rencana kegiatan operasi penanganan darurat bencana;
d. mengoordinasikan instansi/lembaga terkait;
e. mengendalikan pelaksanaan penanganan darurat bencana;
f. memantau dan mengevaluasi pelaksanaan penanganan darurat bencana;
g. melaksanakan manajemen informasi pelaksanaan penanganan darurat bencana;
h. Posko PDB kabupaten/kota atau provinsi melaporkan pelaksanaan operasi penanganan darurat bencana kepada kepala BPBD kabupaten/kota atau provinsi tembusan instansi/lembaga terkait; dan
i. Posko Nasional PDB melaporkan pelaksanaan operasi penanganan darurat bencana kepada Kepala BNPB tembusan kementerian/lembaga terkait.
(2) Pos komando mempunyai fungsi:
a. pengkajian pemenuhan kebutuhan penanganan darurat bencana dan perencanaan kegiatan rehabilitasi dan rekonstruksi;
b. perencanaan, pengendalian, pengoordinasian kegiatan operasi, pemantauan, evaluasi dan pelaporan penanganan darurat bencana; dan
c. pengelolaan data dan informasi penanganan darurat bencana.
Bencana Kabupaten/Kota Dan Provinsi');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8061, '(1) Pos komando mempunyai tugas:
a. melakukan kajian pemenuhan kebutuhan penanganan darurat bencana berdasarkan hasil kaji cepat dan rencana kontinjensi;
b. melakukan kajian awal upaya/rencana kegiatan rehabilitasi dan rekonstruksi;
c. menyusun rencana kegiatan operasi penanganan darurat bencana;
d. mengoordinasikan instansi/lembaga terkait;
e. mengendalikan pelaksanaan penanganan darurat bencana;
f. memantau dan mengevaluasi pelaksanaan penanganan darurat bencana;
g. melaksanakan manajemen informasi pelaksanaan penanganan darurat bencana;
h. Posko PDB kabupaten/kota atau provinsi melaporkan pelaksanaan operasi penanganan darurat bencana kepada kepala BPBD kabupaten/kota atau provinsi tembusan instansi/lembaga terkait; dan
i. Posko Nasional PDB melaporkan pelaksanaan operasi penanganan darurat bencana kepada Kepala BNPB tembusan kementerian/lembaga terkait.
(2) Pos komando mempunyai fungsi:
a. pengkajian pemenuhan kebutuhan penanganan darurat bencana dan perencanaan kegiatan rehabilitasi dan rekonstruksi;
b. perencanaan, pengendalian, pengoordinasian kegiatan operasi, pemantauan, evaluasi dan pelaporan penanganan darurat bencana; dan
c. pengelolaan data dan informasi penanganan darurat bencana.
Bencana Kabupaten/Kota Dan Provinsi', 'Pasal 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8062, 'perka-3-2016', 13, 'pasal', 'Pasal 10', 'BAB V KEDUDUKAN, TUGAS, FUNGSI DAN STRUKTUR ORGANISASI POS KOMANDO PENANGANAN DARURAT BENCANA; Bagian Keempat Struktur Organisasi Pos Komando Nasional', 11, '(1) Posko PDB dipimpin seorang Komandan Posko PDB dibantu oleh:
a. wakil komandan;
b. sekretariat;
c. bagian data, informasi dan humas;
d. bagian perencanaan;
e. perwakilan instansi/lembaga terkait; dan
f. bidang operasi.
(2) Sekretariat, bagian, dan bidang sebagaimana dimaksud pada ayat (1) dapat dilengkapi dengan subbagian dan seksi sesuai dengan ketentuan peraturan perundang-undangan.
(3) Struktur organisasi sebagaimana dimaksud pada ayat
(1) dapat diubah sesuai dengan kebutuhan penanganan darurat bencana dan jenis ancaman bencana yang terjadi.
(4) Ketentuan lebih lanjut mengenai struktur organisasi dan uraian tugas unit organisasi Posko PDB diatur dengan petunjuk pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8062, '(1) Posko PDB dipimpin seorang Komandan Posko PDB dibantu oleh:
a. wakil komandan;
b. sekretariat;
c. bagian data, informasi dan humas;
d. bagian perencanaan;
e. perwakilan instansi/lembaga terkait; dan
f. bidang operasi.
(2) Sekretariat, bagian, dan bidang sebagaimana dimaksud pada ayat (1) dapat dilengkapi dengan subbagian dan seksi sesuai dengan ketentuan peraturan perundang-undangan.
(3) Struktur organisasi sebagaimana dimaksud pada ayat
(1) dapat diubah sesuai dengan kebutuhan penanganan darurat bencana dan jenis ancaman bencana yang terjadi.
(4) Ketentuan lebih lanjut mengenai struktur organisasi dan uraian tugas unit organisasi Posko PDB diatur dengan petunjuk pelaksana.', 'Pasal 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8063, 'perka-3-2016', 14, 'pasal', 'Pasal 11', 'BAB VI KEDUDUKAN, TUGAS, FUNGSI DAN STRUKTUR ORGANISASI POS LAPANGAN PENANGANAN DARURAT BENCANA; Bagian Kesatu Kedudukan', 12, '(1) Posko Nasional PDB dipimpin seorang komandan dibantu oleh:
a. wakil komandan;
b. sekretariat;
c. bagian perencanaan;
d. bagian data, informasi dan humas;
e. perwakilan kementerian/lembaga terkait, pemerintah daerah provinsi, dan koordinator bantuan komunitas internasional; dan
f. bidang/klaster.
(2) Sekretariat, bagian, dan bidang/klaster sebagaimana dimaksud pada ayat (1) dapat dilengkapi dengan subbagian dan seksi/subklaster sesuai dengan ketentuan peraturan perundang-undangan.
(3) Struktur organisasi sebagaimana dimaksud pada ayat
(1) dapat diubah sesuai dengan kebutuhan penanganan darurat bencana dan jenis ancaman bencana yang terjadi.
(4) Ketentuan lebih lanjut mengenai struktur organisasi dan uraian tugas unit organisasi Posko Nasional PDB diatur dengan petunjuk pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8063, '(1) Posko Nasional PDB dipimpin seorang komandan dibantu oleh:
a. wakil komandan;
b. sekretariat;
c. bagian perencanaan;
d. bagian data, informasi dan humas;
e. perwakilan kementerian/lembaga terkait, pemerintah daerah provinsi, dan koordinator bantuan komunitas internasional; dan
f. bidang/klaster.
(2) Sekretariat, bagian, dan bidang/klaster sebagaimana dimaksud pada ayat (1) dapat dilengkapi dengan subbagian dan seksi/subklaster sesuai dengan ketentuan peraturan perundang-undangan.
(3) Struktur organisasi sebagaimana dimaksud pada ayat
(1) dapat diubah sesuai dengan kebutuhan penanganan darurat bencana dan jenis ancaman bencana yang terjadi.
(4) Ketentuan lebih lanjut mengenai struktur organisasi dan uraian tugas unit organisasi Posko Nasional PDB diatur dengan petunjuk pelaksana.', 'Pasal 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8064, 'perka-3-2016', 15, 'pasal', 'Pasal 12', 'BAB VI KEDUDUKAN, TUGAS, FUNGSI DAN STRUKTUR ORGANISASI POS LAPANGAN PENANGANAN DARURAT BENCANA; Bagian Kedua Tugas Dan Fungsi', 13, 'Pos Lapangan PDB berkedudukan baik di lokasi bencana maupun lokasi pengungsian atau di wilayah sekitar lokasi bencana dengan mempertimbangkan kemudahan akses dan efektifitas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8064, 'Pos Lapangan PDB berkedudukan baik di lokasi bencana maupun lokasi pengungsian atau di wilayah sekitar lokasi bencana dengan mempertimbangkan kemudahan akses dan efektifitas.', 'Pasal 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8065, 'perka-3-2016', 16, 'pasal', 'Pasal 13', 'BAB VI KEDUDUKAN, TUGAS, FUNGSI DAN STRUKTUR ORGANISASI POS LAPANGAN PENANGANAN DARURAT BENCANA; Bagian Ketiga Struktur Organisasi Pos Lapangan', 13, '(1) Pos Lapangan PDB mempunyai tugas:
a. melakukan kajian kebutuhan operasional lapangan;
b. menyusun rencana uraian kerja lapangan sesuai dengan rencana operasi yang telah disusun oleh Posko PDB;
c. melaksanakan operasi di wilayah kerja;
d. mengajukan permintaan sumber daya yang dibutuhkan untuk pelaksanaan operasi kepada Posko PDB;
e. mengelola bantuan logistik dan peralatan untuk pelaksanaan operasi;
f. melakukan evaluasi pelaksanaan operasi;
g. melaksanakan manajemen data dan informasi pelaksanaan operasi; dan
h. melaporkan pelaksanaan operasi kepada Komandan Posko PDB.
(2) Pos Lapangan PDB mempunyai fungsi:
a. pengkajian pemenuhan kebutuhan penanganan;
b. perencanaan, pelaksanaan, evaluasi, dan pelaporan operasi lapangan;
c. pengelolaan logistik dan peralatan; dan
d. pengelolaan data dan informasi.
Penanganan Darurat Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8065, '(1) Pos Lapangan PDB mempunyai tugas:
