INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8069, 'perka-3-2016', 20, 'pasal', 'Pasal 17', 'BAB VII KEDUDUKAN, TUGAS, FUNGSI DAN STRUKTUR ORGANISASI POS PENDUKUNG PENANGANAN DARURAT BENCANA; Bagian Ketiga Struktur Organisasi Pos Pendukung', 18, '(1) Pos Pendukung PDB bantuan dalam negeri dipimpin seorang koordinator dibantu oleh:
a. sekretariat;
b. bidang logistik dan peralatan;
c. bidang sumber daya manusia dan satuan satwa; dan
d. bidang transportasi.
(2) Struktur organisasi sebagaimana dimaksud pada ayat
(1) merupakan struktur organisasi standar yang dapat diubah sesuai dengan kebutuhan penanganan darurat bencana dan jenis ancaman bencana yang terjadi.
(3) Ketentuan lebih lanjut mengenai struktur organisasi dan uraian tugas unit organisasi Pos Pendukung PDB bantuan dalam negeri diatur dengan petunjuk pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8069, '(1) Pos Pendukung PDB bantuan dalam negeri dipimpin seorang koordinator dibantu oleh:
a. sekretariat;
b. bidang logistik dan peralatan;
c. bidang sumber daya manusia dan satuan satwa; dan
d. bidang transportasi.
(2) Struktur organisasi sebagaimana dimaksud pada ayat
(1) merupakan struktur organisasi standar yang dapat diubah sesuai dengan kebutuhan penanganan darurat bencana dan jenis ancaman bencana yang terjadi.
(3) Ketentuan lebih lanjut mengenai struktur organisasi dan uraian tugas unit organisasi Pos Pendukung PDB bantuan dalam negeri diatur dengan petunjuk pelaksana.', 'Pasal 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8070, 'perka-3-2016', 21, 'pasal', 'Pasal 18', 'BAB VIII KEDUDUKAN, TUGAS, FUNGSI DAN STRUKTUR ORGANISASI POS PENDAMPING PENANGANAN DARURAT BENCANA; Bagian Kesatu Kedudukan', 18, '(1) Pos Pendukung PDB bantuan dalam negeri dan komunitas internasional dipimpin seorang koordinator dibantu oleh:
a. sekretariat;
b. bidang karantina;
c. bidang imigrasi;
d. bidang bea dan cukai;
e. bidang perijinan bantuan bersumber dari militer/kepolisian asing;
f. bidang logistik dan peralatan;
g. bidang sumber daya manusia dan satuan satwa; dan
h. bidang transportasi.
(2) Struktur organisasi sebagaimana dimaksud pada ayat
(1) merupakan struktur organisasi standar yang dapat diubah sesuai dengan kebutuhan penanganan darurat bencana dan jenis ancaman bencana yang terjadi.
(3) Ketentuan lebih lanjut mengenai struktur organisasi dan uraian tugas unit organisasi Pos Pendukung PDB bantuan dalam negeri dan komunitas internasional diatur dengan petunjuk pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8070, '(1) Pos Pendukung PDB bantuan dalam negeri dan komunitas internasional dipimpin seorang koordinator dibantu oleh:
a. sekretariat;
b. bidang karantina;
c. bidang imigrasi;
d. bidang bea dan cukai;
e. bidang perijinan bantuan bersumber dari militer/kepolisian asing;
f. bidang logistik dan peralatan;
g. bidang sumber daya manusia dan satuan satwa; dan
h. bidang transportasi.
(2) Struktur organisasi sebagaimana dimaksud pada ayat
(1) merupakan struktur organisasi standar yang dapat diubah sesuai dengan kebutuhan penanganan darurat bencana dan jenis ancaman bencana yang terjadi.
(3) Ketentuan lebih lanjut mengenai struktur organisasi dan uraian tugas unit organisasi Pos Pendukung PDB bantuan dalam negeri dan komunitas internasional diatur dengan petunjuk pelaksana.', 'Pasal 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8071, 'perka-3-2016', 22, 'pasal', 'Pasal 19', 'BAB VIII KEDUDUKAN, TUGAS, FUNGSI DAN STRUKTUR ORGANISASI POS PENDAMPING PENANGANAN DARURAT BENCANA; Bagian Kedua Tugas dan Fungsi', 19, '(1) Pada saat status keadaan darurat bencana kabupaten/kota ditetapkan, Pos Pendamping PDB provinsi berkedudukan di ibukota provinsi atau di wilayah lain yang masih berada di dalam provinsi bersangkutan dengan mempertimbangkan kemudahan akses dan efektifitas.
(2) Pada saat status keadaan darurat bencana nasional ditetapkan, Pos Pendamping PDB wilayah berkedudukan di satu wilayah tertentu dengan mempertimbangkan kemudahan akses dan efektifitas.
(3) Pada saat status keadaan darurat bencana kabupaten/kota atau provinsi ditetapkan, Pos Pendamping Nasional PDB berkedudukan di ibukota negara atau wilayah lain di Indonesia dengan mempertimbangkan kemudahan akses dan efektifitas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8071, '(1) Pada saat status keadaan darurat bencana kabupaten/kota ditetapkan, Pos Pendamping PDB provinsi berkedudukan di ibukota provinsi atau di wilayah lain yang masih berada di dalam provinsi bersangkutan dengan mempertimbangkan kemudahan akses dan efektifitas.
(2) Pada saat status keadaan darurat bencana nasional ditetapkan, Pos Pendamping PDB wilayah berkedudukan di satu wilayah tertentu dengan mempertimbangkan kemudahan akses dan efektifitas.
(3) Pada saat status keadaan darurat bencana kabupaten/kota atau provinsi ditetapkan, Pos Pendamping Nasional PDB berkedudukan di ibukota negara atau wilayah lain di Indonesia dengan mempertimbangkan kemudahan akses dan efektifitas.', 'Pasal 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8072, 'perka-3-2016', 23, 'pasal', 'Pasal 20', 'BAB VIII KEDUDUKAN, TUGAS, FUNGSI DAN STRUKTUR ORGANISASI POS PENDAMPING PENANGANAN DARURAT BENCANA; Bagian Ketiga Struktur Organisasi Pos Pendamping', 20, '(1) Pos Pendamping PDB provinsi mempunyai tugas:
a. melakukan pengkajian cepat kebutuhan sumber daya melalui koordinasi dengan Posko PDB kabupaten/kota;
b. melakukan mobilisasi bantuan darurat bencana dari instansi/lembaga terkait di tingkat provinsi dan kabupaten/kota di wilayahnya yang tidak terdampak bencana;
c. mengajukan permintaan bantuan sumber daya kepada Pos Pendamping Nasional atau BNPB jika diperlukan;
d. menyiapkan bantuan sumber daya sesuai hasil pengkajian cepat kebutuhan;
e. melakukan distribusi bantuan penanganan darurat bencana kepada Posko PDB sesuai kebutuhan;
f. melakukan evaluasi pelaksanaan kegiatan; dan
g. melaporkan pelaksanaan kegiatan kepada BPBD provinsi dengan tembusan kepada perangkat daerah/lembaga terkait tingkat provinsi.
(2) Pos Pendamping PDB wilayah mempunyai tugas:
a. melakukan pengkajian cepat kebutuhan sumber daya berkoordinasi dengan Pos Lapangan PDB;
b. mengajukan permintaan bantuan sumber daya kepada Posko Nasional PDB;
c. mengelola bantuan penanganan darurat bencana yang diterima dari tingkat provinsi dan nasional;
d. menyiapkan bantuan sumber daya sesuai hasil pengkajian cepat kebutuhan;
e. melakukan distribusi bantuan penanganan darurat bencana kepada Pos Lapangan PDB sesuai kebutuhan;
f. melakukan evaluasi pelaksanaan kegiatan; dan
g. melaporkan pelaksanaan kegiatan kepada Posko Nasional PDB dengan tembusan kepada pemerintah daerah provinsi setempat.
(3) Pos Pendamping Nasional PDB mempunyai tugas:
a. melakukan pengkajian cepat kebutuhan sumber daya berkoordinasi dengan Komandan Posko PDB dan atau Pos Pendamping PDB wilayah;
b. melakukan mobilisasi bantuan penanganan darurat bencana dari kementerian/lembaga terkait dan provinsi yang wilayahnya tidak terdampak bencana;
c. mengelola bantuan yang diterima dari komunitas internasional;
d. menyiapkan bantuan sumber daya sesuai hasil pengkajian cepat kebutuhan;
e. melakukan distribusi bantuan penanganan darurat bencana kepada Posko PDB atau Pos Pendamping PDB wilayah;
f. melakukan evaluasi pelaksanaan kegiatan; dan
g. melaporkan pelaksanaan kegiatan kepada BNPB dengan tembusan kepada kementerian/lembaga terkait.
(4) Pos Pendamping PDB Provinsi, Pos Pendamping wilayah dan Pos Pendamping Nasional PDB mempunyai fungsi:
a. pengkajian cepat kebutuhan sumber daya;
b. pengelolaan bantuan sumber daya; dan
c. pencatatan, evaluasi dan pelaporan kegiatan.
Penanganan Darurat Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8072, '(1) Pos Pendamping PDB provinsi mempunyai tugas:
a. melakukan pengkajian cepat kebutuhan sumber daya melalui koordinasi dengan Posko PDB kabupaten/kota;
b. melakukan mobilisasi bantuan darurat bencana dari instansi/lembaga terkait di tingkat provinsi dan kabupaten/kota di wilayahnya yang tidak terdampak bencana;
c. mengajukan permintaan bantuan sumber daya kepada Pos Pendamping Nasional atau BNPB jika diperlukan;
d. menyiapkan bantuan sumber daya sesuai hasil pengkajian cepat kebutuhan;
e. melakukan distribusi bantuan penanganan darurat bencana kepada Posko PDB sesuai kebutuhan;
f. melakukan evaluasi pelaksanaan kegiatan; dan
g. melaporkan pelaksanaan kegiatan kepada BPBD provinsi dengan tembusan kepada perangkat daerah/lembaga terkait tingkat provinsi.
(2) Pos Pendamping PDB wilayah mempunyai tugas:
a. melakukan pengkajian cepat kebutuhan sumber daya berkoordinasi dengan Pos Lapangan PDB;
b. mengajukan permintaan bantuan sumber daya kepada Posko Nasional PDB;
c. mengelola bantuan penanganan darurat bencana yang diterima dari tingkat provinsi dan nasional;
d. menyiapkan bantuan sumber daya sesuai hasil pengkajian cepat kebutuhan;
e. melakukan distribusi bantuan penanganan darurat bencana kepada Pos Lapangan PDB sesuai kebutuhan;
f. melakukan evaluasi pelaksanaan kegiatan; dan
g. melaporkan pelaksanaan kegiatan kepada Posko Nasional PDB dengan tembusan kepada pemerintah daerah provinsi setempat.
(3) Pos Pendamping Nasional PDB mempunyai tugas:
a. melakukan pengkajian cepat kebutuhan sumber daya berkoordinasi dengan Komandan Posko PDB dan atau Pos Pendamping PDB wilayah;
b. melakukan mobilisasi bantuan penanganan darurat bencana dari kementerian/lembaga terkait dan provinsi yang wilayahnya tidak terdampak bencana;
c. mengelola bantuan yang diterima dari komunitas internasional;
d. menyiapkan bantuan sumber daya sesuai hasil pengkajian cepat kebutuhan;
e. melakukan distribusi bantuan penanganan darurat bencana kepada Posko PDB atau Pos Pendamping PDB wilayah;
f. melakukan evaluasi pelaksanaan kegiatan; dan
g. melaporkan pelaksanaan kegiatan kepada BNPB dengan tembusan kepada kementerian/lembaga terkait.
(4) Pos Pendamping PDB Provinsi, Pos Pendamping wilayah dan Pos Pendamping Nasional PDB mempunyai fungsi:
a. pengkajian cepat kebutuhan sumber daya;
b. pengelolaan bantuan sumber daya; dan
c. pencatatan, evaluasi dan pelaporan kegiatan.
Penanganan Darurat Bencana', 'Pasal 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8073, 'perka-3-2016', 24, 'pasal', 'Pasal 21', 'BAB VIII KEDUDUKAN, TUGAS, FUNGSI DAN STRUKTUR ORGANISASI POS PENDAMPING PENANGANAN DARURAT BENCANA; Bagian Ketiga Struktur Organisasi Pos Pendamping', 21, '(1) Pos Pendamping PDB provinsi dan Pos Pendamping PDB wilayah dipimpin seorang koordinator dibantu oleh:
a. wakil koordinator;
b. sekretariat;
c. bagian data, informasi dan humas;
d. perwakilan instansi/lembaga terkait; dan
e. bidang operasi.
(2) Struktur organisasi sebagaimana dimaksud pada ayat
(1) merupakan struktur organisasi standar yang dapat diubah sesuai dengan kebutuhan penanganan darurat bencana dan jenis ancaman bencana yang terjadi.
(3) Ketentuan lebih lanjut mengenai struktur organisasi dan uraian tugas unit organisasi Pos Pendamping PDB provinsi dan Pos Pendamping PDB wilayah diatur dengan petunjuk pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8073, '(1) Pos Pendamping PDB provinsi dan Pos Pendamping PDB wilayah dipimpin seorang koordinator dibantu oleh:
a. wakil koordinator;
b. sekretariat;
c. bagian data, informasi dan humas;
d. perwakilan instansi/lembaga terkait; dan
e. bidang operasi.
(2) Struktur organisasi sebagaimana dimaksud pada ayat
(1) merupakan struktur organisasi standar yang dapat diubah sesuai dengan kebutuhan penanganan darurat bencana dan jenis ancaman bencana yang terjadi.
(3) Ketentuan lebih lanjut mengenai struktur organisasi dan uraian tugas unit organisasi Pos Pendamping PDB provinsi dan Pos Pendamping PDB wilayah diatur dengan petunjuk pelaksana.', 'Pasal 21', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8074, 'perka-3-2016', 25, 'pasal', 'Pasal 22', 'BAB IX MONITORING DAN EVALUASI; Bagian Kesatu Monitoring', 22, '(1) Pos Pendamping Nasional PDB dipimpin seorang koordinator dibantu oleh:
a. wakil koordinator;
b. sekretariat;
c. bagian data, informasi dan humas;
d. perwakilan kementerian/lembaga terkait dan bagian koordinasi bantuan komunitas internasional; dan
e. bidang/klaster.
(2) Struktur organisasi sebagaimana dimaksud pada ayat
(1) merupakan struktur organisasi standar yang dapat diubah sesuai dengan kebutuhan penanganan darurat bencana dan jenis ancaman bencana yang terjadi.
(3) Ketentuan lebih lanjut mengenai struktur organisasi dan uraian tugas unit organisasi Pos Pendamping Nasional PDB diatur dengan petunjuk pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8074, '(1) Pos Pendamping Nasional PDB dipimpin seorang koordinator dibantu oleh:
a. wakil koordinator;
b. sekretariat;
c. bagian data, informasi dan humas;
d. perwakilan kementerian/lembaga terkait dan bagian koordinasi bantuan komunitas internasional; dan
e. bidang/klaster.
(2) Struktur organisasi sebagaimana dimaksud pada ayat
(1) merupakan struktur organisasi standar yang dapat diubah sesuai dengan kebutuhan penanganan darurat bencana dan jenis ancaman bencana yang terjadi.
(3) Ketentuan lebih lanjut mengenai struktur organisasi dan uraian tugas unit organisasi Pos Pendamping Nasional PDB diatur dengan petunjuk pelaksana.', 'Pasal 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8075, 'perka-3-2016', 26, 'pasal', 'Pasal 23', 'BAB IX MONITORING DAN EVALUASI; Bagian Kedua Evaluasi', 23, '(1) Monitoring bertujuan untuk memastikan pelaksanaan penanganan darurat bencana sesuai dengan rencana yang telah ditetapkan menyangkut prosedur, waktu pelaksanaan dan sasaran kerja yang dilakukan secara berkala selama masa keadaan darurat bencana diberlakukan.
(2) Kegiatan monitoring penanganan darurat bencana dilakukan secara berjenjang sebagai berikut:
a. pelaksanaan operasi lapangan oleh petugas lapangan dimonitor oleh Koordinator Pos Lapangan PDB;
b. Pos Lapangan PDB dan Pos Pendukung PDB dimonitor oleh Komandan Posko PDB;
c. Posko PDB dimonitor oleh BPBD/BNPB sesuai kewenangannya melalui koordinasi dengan perangkat daerah/lembaga terkait untuk tingkat provinsi dan kabupaten/kota serta kementerian/lembaga terkait untuk tingkat pusat;
d. Pos Pendamping PDB provinsi dimonitor oleh BPBD provinsi berkoordinasi dengan perangkat daerah/lembaga terkait;
e. Pos Pendamping PDB wilayah yang di bawah kendali Posko Nasional PDB dimonitor langsung oleh Posko Nasional PDB; dan
f. Pos Pendamping Nasional PDB dimonitor oleh BNPB berkoordinasi dengan kementerian/lembaga terkait.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8075, '(1) Monitoring bertujuan untuk memastikan pelaksanaan penanganan darurat bencana sesuai dengan rencana yang telah ditetapkan menyangkut prosedur, waktu pelaksanaan dan sasaran kerja yang dilakukan secara berkala selama masa keadaan darurat bencana diberlakukan.
(2) Kegiatan monitoring penanganan darurat bencana dilakukan secara berjenjang sebagai berikut:
a. pelaksanaan operasi lapangan oleh petugas lapangan dimonitor oleh Koordinator Pos Lapangan PDB;
b. Pos Lapangan PDB dan Pos Pendukung PDB dimonitor oleh Komandan Posko PDB;
c. Posko PDB dimonitor oleh BPBD/BNPB sesuai kewenangannya melalui koordinasi dengan perangkat daerah/lembaga terkait untuk tingkat provinsi dan kabupaten/kota serta kementerian/lembaga terkait untuk tingkat pusat;
d. Pos Pendamping PDB provinsi dimonitor oleh BPBD provinsi berkoordinasi dengan perangkat daerah/lembaga terkait;
e. Pos Pendamping PDB wilayah yang di bawah kendali Posko Nasional PDB dimonitor langsung oleh Posko Nasional PDB; dan
f. Pos Pendamping Nasional PDB dimonitor oleh BNPB berkoordinasi dengan kementerian/lembaga terkait.', 'Pasal 23', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8076, 'perka-3-2016', 27, 'pasal', 'Pasal 24', 'BAB IX MONITORING DAN EVALUASI; Bagian Kedua Evaluasi', 24, '(1) Evaluasi merupakan kegiatan penilaian capaian hasil pelaksanaan kegiatan penanganan darurat bencana.
(2) Evaluasi terhadap kegiatan Pos Lapangan PDB, Posko PDB, Pos Pendukung PDB maupun Pos Pendamping PDB dilakukan baik secara rutin maupun pada saat tertentu sesuai kebutuhan dan setelah status keadaan darurat bencana berakhir.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8076, '(1) Evaluasi merupakan kegiatan penilaian capaian hasil pelaksanaan kegiatan penanganan darurat bencana.
(2) Evaluasi terhadap kegiatan Pos Lapangan PDB, Posko PDB, Pos Pendukung PDB maupun Pos Pendamping PDB dilakukan baik secara rutin maupun pada saat tertentu sesuai kebutuhan dan setelah status keadaan darurat bencana berakhir.', 'Pasal 24', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8077, 'perka-3-2016', 28, 'pasal', 'Pasal 25', 'BAB X KETENTUAN PENUTUP', 24, 'Pelaksanaan monitoring dan evaluasi sebagaimana dimaksud dalam Pasal 23 dan Pasal 24 diatur dengan petunjuk pelaksana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8077, 'Pelaksanaan monitoring dan evaluasi sebagaimana dimaksud dalam Pasal 23 dan Pasal 24 diatur dengan petunjuk pelaksana.', 'Pasal 25', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8078, 'perka-3-2016', 29, 'pasal', 'Pasal 26', 'BAB X KETENTUAN PENUTUP', 24, 'Pada saat Peraturan Kepala Badan ini mulai berlaku:
