INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8079, 'perka-3-2016', 30, 'pasal', 'Pasal 27', 'BAB X KETENTUAN PENUTUP', 24, 'Peraturan Kepala Badan ini mulai berlaku pada tanggal diundangkan.
