INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8083, 'Bantuan Dalam Negeri dan Komunitas Internasional KOORDINATOR SEKRETARIAT BIDANG BIDANG BIDANG BIDANG BIDANG BIDANG PERIJINAN BANTUAN BIDANG BEA DAN LOGISTIK DAN SUMBER DAYA KARANTINA IMIGRASI BERSUMBER DARI MANUSIA DAN TRANSPORTASI CUKAI PERALATAN MILITER/KEPOLISIAN SATUAN SATWA ASING KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, Ttd, WILLEM RAMPANGILEI LAMPIRAN IV PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 03 TAHUN 2016 TENTANG SISTEM KOMANDO PENANGANAN DARURAT BENCANA Struktur Organisasi Pos Pendamping Penanganan Darurat Bencana A. Provinsi dan Wilayah KOORDINATOR WAKIL KOORDINATOR BAGIAN PERWAKILAN SEKRETARIAT DATA, INFORMASI INSTANSI/LEMBAGA DAN HUMAS TERKAIT BIDANG OPERASI B. Nasional KOORDINATORK WAKIL KOORDINATOR BAGIAN PERWAKILAN DATA, INFORMASI KEMENTERIAN/LEMBAGA TERKAIT DAN BAGIAN SEKRETARIAT DAN HUMAS KOORDINASI BANTUAN KOMUNITAS BIDANG/KLASTER KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, Ttd, WILLEM RAMPANGILEI', 'Lampiran hal. 26', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2016 tentang Sistem Komando Penanganan Darurat Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8084, 'perka-3-2017', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2017 tentang Laporan Harta Kekayaan Penyelenggaraan Negara di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8084, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2017 tentang Laporan Harta Kekayaan Penyelenggaraan Negara di Lingkungan Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2017 tentang Laporan Harta Kekayaan Penyelenggaraan Negara di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8085, 'perka-3-2017', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk melaksanakan ketentuan Pasal 23 Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggara Negara yang Bersih dan Bebas dari Korupsi, Kolusi, dan Nepotisme, setiap Penyelenggara Negara harus melaporkan dan mengumumkan harta kekayaannya dan bersedia dilakukan pemeriksaan terhadap kekayaannya;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Laporan Harta Kekayaan Penyelenggara Negara di Lingkungan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8085, 'a. bahwa untuk melaksanakan ketentuan Pasal 23 Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggara Negara yang Bersih dan Bebas dari Korupsi, Kolusi, dan Nepotisme, setiap Penyelenggara Negara harus melaporkan dan mengumumkan harta kekayaannya dan bersedia dilakukan pemeriksaan terhadap kekayaannya;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Laporan Harta Kekayaan Penyelenggara Negara di Lingkungan;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2017 tentang Laporan Harta Kekayaan Penyelenggaraan Negara di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8086, 'perka-3-2017', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Negara Yang Bersih dan Bebas dari Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3851);
2. Undang-Undang Nomor 20 Tahun 2001 tentang Perubahan atas Undang-Undang Nomor 31 Tahun 1999 2017, No.898 -2- tentang Pemberantasan Tindak Pidana Korupsi (Lembaran Negara Republik Indonesia Tahun 2001 Nomor 134, Tambahan Lembaran Negara Republik Indonesia Nomor 4150);
