INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8098, 'perka-3-2017', 14, 'lain', 'Penutup', NULL, 9, 'Ditetapkan di Jakarta pada tanggal 4 Juli 2017 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 4 Juli 2017 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd WIDODO EKATJAHJANA');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8098, 'Ditetapkan di Jakarta pada tanggal 4 Juli 2017 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 4 Juli 2017 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd WIDODO EKATJAHJANA', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2017 tentang Laporan Harta Kekayaan Penyelenggaraan Negara di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8099, 'perka-4-2008', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8099, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8100, 'perka-4-2008', 1, 'mengingat', 'Mengingat', NULL, 1, 'Dalam rangka pelaksanaan penyelenggaraan Pasal 35 dan Pasal 36 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, dipandang perlu menyusun pedoman pedoman perencanaan penanggulangan bencana.
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Bencana.
3. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 89, Tambahan Lembaran Negara Republik Indonesia Nomor 3952);
4. Keputusan Presiden Nomor 29/M Tahun 2008 tentang Pengangkatan Kepala Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8100, 'Dalam rangka pelaksanaan penyelenggaraan Pasal 35 dan Pasal 36 Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, dipandang perlu menyusun pedoman pedoman perencanaan penanggulangan bencana.
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Bencana.
3. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 89, Tambahan Lembaran Negara Republik Indonesia Nomor 3952);
4. Keputusan Presiden Nomor 29/M Tahun 2008 tentang Pengangkatan Kepala Badan Nasional Penanggulangan Bencana.', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8101, 'perka-4-2008', 2, 'menetapkan', 'Menetapkan', NULL, 1, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN PENYUSUNAN RENCANA PENANGGULANGAN BENCANA.
2 Pertama : Pedoman Penyusunan Rencana Penanggulangan Bencana merupakan panduan/acuan bagi Pemerintah Provinsi dan Pemerintah Kabupaten / Kota dalam menyusun perencanaan penanggulangan bencana di daerah di daerah masing-masing.
Kedua : Pedoman sebagaimana dimaksud diktum Pertama adalah sebagaimana dimaksud dalam Lampiran, yang merupakan bagian tak terpisahkan dari Peraturan ini.
Ketiga : Peraturan ini berlaku sejak tanggal ditetapkan.
Ditetapkan di : J a k a r t a Pada tanggal : 17 Desember 2008 BADAN NASIONAL PENANGGULANGAN BENCANA KEPALA, ttd DR. SYAMSUL MA’ARIF, S.IP. M.Si.
SALINAN Peraturan ini disampaikan kepada:
1. Para Menteri Kabinet Indonesia Bersatu
2. KAPOLRI
3. Panglima TNI
4. Para Gubernur
5. Para Ketua DPRD Propinsi
6. Para Bupati dan Walikota
7. Para Ketua DPRD Kabupaten/Kota LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 4 TAHUN 2008 TANGGAL : 17 DESEMBER 2008');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8101, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN PENYUSUNAN RENCANA PENANGGULANGAN BENCANA.
2 Pertama : Pedoman Penyusunan Rencana Penanggulangan Bencana merupakan panduan/acuan bagi Pemerintah Provinsi dan Pemerintah Kabupaten / Kota dalam menyusun perencanaan penanggulangan bencana di daerah di daerah masing-masing.
Kedua : Pedoman sebagaimana dimaksud diktum Pertama adalah sebagaimana dimaksud dalam Lampiran, yang merupakan bagian tak terpisahkan dari Peraturan ini.
Ketiga : Peraturan ini berlaku sejak tanggal ditetapkan.
Ditetapkan di : J a k a r t a Pada tanggal : 17 Desember 2008 BADAN NASIONAL PENANGGULANGAN BENCANA KEPALA, ttd DR. SYAMSUL MA’ARIF, S.IP. M.Si.
SALINAN Peraturan ini disampaikan kepada:
1. Para Menteri Kabinet Indonesia Bersatu
2. KAPOLRI
3. Panglima TNI
4. Para Gubernur
5. Para Ketua DPRD Propinsi
6. Para Bupati dan Walikota
7. Para Ketua DPRD Kabupaten/Kota LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 4 TAHUN 2008 TANGGAL : 17 DESEMBER 2008', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8102, 'perka-4-2008', 3, 'menetapkan', 'BAB I', NULL, 3, 'PENDAHULUAN A. Latar Belakang Indonesia yang terdiri dari gugusan kepulauan mempunyai potensi bencana yang sangat tinggi dan juga sangat bervariasi dari aspek jenis bencana. Kondisi alam terseut serta adanya keanekaragaman penduduk dan budaya di Indonesia menyebabkan timbulnya risiko terjadinya bencana alam, bencana ulah manusia dan kedaruratan kompleks, meskipun disisi lain juga kaya akan sumberdaya alam.
Pada umumnya risiko bencana alam meliputi bencana akibat faktor geologi (gempabumi, tsunami dan letusan gunung api), bencana akibat hydrometeorologi (banjir, tanah longsor, kekeringan, angin topan), bencana akibat faktor biologi (wabah penyakit manusia, penyakit tanaman/ternak, hama tanaman) serta kegagalan teknologi (kecelakan industri, kecelakaan transportasi, radiasi nuklir, pencemaran bahan kimia). Bencana akibat ulah manusia terkait dengan konflik antar manusia akibat perebutan sumberdaya yang terbatas, alasan ideologi, religius serta politik. Sedangkan kedaruratan kompleks merupakan kombinasi dari situasi bencana pada suatu daerah konflik.
Kompleksitas dari permasalahan bencana tersebut memerlukan suatu penataan atau perencanaan yang matang dalam penanggulangannya, sehingga dapat dilaksanakan secara terarah dan terpadu.
Penanggulangan yang dilakukan selama ini belum didasarkan pada langkah-langkah yang sistematis dan terencana, sehingga seringkali terjadi tumpang tindih dan bahkan terdapat langkah upaya yang penting tidak tertangani.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8102, 'PENDAHULUAN A. Latar Belakang Indonesia yang terdiri dari gugusan kepulauan mempunyai potensi bencana yang sangat tinggi dan juga sangat bervariasi dari aspek jenis bencana. Kondisi alam terseut serta adanya keanekaragaman penduduk dan budaya di Indonesia menyebabkan timbulnya risiko terjadinya bencana alam, bencana ulah manusia dan kedaruratan kompleks, meskipun disisi lain juga kaya akan sumberdaya alam.
Pada umumnya risiko bencana alam meliputi bencana akibat faktor geologi (gempabumi, tsunami dan letusan gunung api), bencana akibat hydrometeorologi (banjir, tanah longsor, kekeringan, angin topan), bencana akibat faktor biologi (wabah penyakit manusia, penyakit tanaman/ternak, hama tanaman) serta kegagalan teknologi (kecelakan industri, kecelakaan transportasi, radiasi nuklir, pencemaran bahan kimia). Bencana akibat ulah manusia terkait dengan konflik antar manusia akibat perebutan sumberdaya yang terbatas, alasan ideologi, religius serta politik. Sedangkan kedaruratan kompleks merupakan kombinasi dari situasi bencana pada suatu daerah konflik.
Kompleksitas dari permasalahan bencana tersebut memerlukan suatu penataan atau perencanaan yang matang dalam penanggulangannya, sehingga dapat dilaksanakan secara terarah dan terpadu.
Penanggulangan yang dilakukan selama ini belum didasarkan pada langkah-langkah yang sistematis dan terencana, sehingga seringkali terjadi tumpang tindih dan bahkan terdapat langkah upaya yang penting tidak tertangani.', 'BAB I', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8103, 'perka-4-2008', 4, 'menetapkan', 'BAB I (lanjutan 1)', NULL, 3, 'Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana mengamanatkan pada pasal 35 dan 36 agar setiap daerah dalam upaya penanggulangan bencana, mempunyai perencanaan penanggulangan bencana. Secara lebih rinci disebutkan di dalam Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
Pedoman Penyusunan Rencana Penanggulangan Bencana 1 B. Tujuan Memberikan pedoman atau panduan dalam menyusun Rencana Penanggulangan Bencana (disaster management plan) yang menyeluruh, terarah dan terpadu di tingkat Propinsi / Kabupaten / Kota.
C. Ruang Lingkup Penyusunan Rencana Penanggulangan Bencana ini meliputi :
1. pengenalan dan pengkajian ancaman bencana;
2. pemahaman tentang kerentanan masyarakat;
3. analisis kemungkinan dampak bencana;
4. pilihan tindakan pengurangan risiko bencana;
5. penentuan mekanisme kesiapan dan penanggulangan dampak bencana; dan
6. alokasi tugas, kewenangan, dan sumber daya yang tersedia.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8103, 'Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana mengamanatkan pada pasal 35 dan 36 agar setiap daerah dalam upaya penanggulangan bencana, mempunyai perencanaan penanggulangan bencana. Secara lebih rinci disebutkan di dalam Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
Pedoman Penyusunan Rencana Penanggulangan Bencana 1 B. Tujuan Memberikan pedoman atau panduan dalam menyusun Rencana Penanggulangan Bencana (disaster management plan) yang menyeluruh, terarah dan terpadu di tingkat Propinsi / Kabupaten / Kota.
C. Ruang Lingkup Penyusunan Rencana Penanggulangan Bencana ini meliputi :
1. pengenalan dan pengkajian ancaman bencana;
2. pemahaman tentang kerentanan masyarakat;
3. analisis kemungkinan dampak bencana;
4. pilihan tindakan pengurangan risiko bencana;
5. penentuan mekanisme kesiapan dan penanggulangan dampak bencana; dan
6. alokasi tugas, kewenangan, dan sumber daya yang tersedia.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.', 'BAB I (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8104, 'perka-4-2008', 5, 'menetapkan', 'BAB I (lanjutan 2)', NULL, 4, '2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
3. Pencegahan bencana adalah serangkaian kegiatan yang dilakukan untuk mengurangi atau menghilangkan risiko bencana, baik melalui pengurangan ancaman bencana maupun kerentanan pihak yang terancam bencana.
4. Kesiapsiagaan adalah serangkaian yang dilakukan untuk mengantisipasi bencana melalui pengorganisasian serta melalui langkah yang tepat guna dan berdaya guna.
5. Peringatan dini adalah serangkaian kegiatan pemberian peringatan sesegera mungkin kepada masyarakat tentang kemungkinan terjadinya bencana pada suatu tempat oleh lembaga yang berwenang.
6. Mitigasi adalah serangkaian upaya untuk mengurangi risiko bencana, baik melalui pembangunan fisik maupun penyadaran dan peningkatan kemampuan menghadapi ancaman bencana 2 Pedoman Penyusunan Rencana Penanggulangan Bencana
7. Risiko bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, mengungsi, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8104, '2. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
3. Pencegahan bencana adalah serangkaian kegiatan yang dilakukan untuk mengurangi atau menghilangkan risiko bencana, baik melalui pengurangan ancaman bencana maupun kerentanan pihak yang terancam bencana.
4. Kesiapsiagaan adalah serangkaian yang dilakukan untuk mengantisipasi bencana melalui pengorganisasian serta melalui langkah yang tepat guna dan berdaya guna.
5. Peringatan dini adalah serangkaian kegiatan pemberian peringatan sesegera mungkin kepada masyarakat tentang kemungkinan terjadinya bencana pada suatu tempat oleh lembaga yang berwenang.
6. Mitigasi adalah serangkaian upaya untuk mengurangi risiko bencana, baik melalui pembangunan fisik maupun penyadaran dan peningkatan kemampuan menghadapi ancaman bencana 2 Pedoman Penyusunan Rencana Penanggulangan Bencana
7. Risiko bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, mengungsi, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.', 'BAB I (lanjutan 2)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8105, 'perka-4-2008', 6, 'menetapkan', 'BAB I (lanjutan 3)', NULL, 5, '8. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, penyelamatan, serta pemulihan prasarana dan sarana.
9. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik ataumasyarakat sampai tingkat yang memadai pada wilayah pascabencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.
10. Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta masyarakat dalam segala aspek kehidupan bermasyarakat pada wilayah pascabencana.
11. Pemerintah Pusat, yang selanjutnya disebut Pemerintah, adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar NegaraRepublik Indonesia Tahun 1945.
12. Pemerintah daerah adalah gubernur, bupati/walikota atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8105, '8. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, penyelamatan, serta pemulihan prasarana dan sarana.
9. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik ataumasyarakat sampai tingkat yang memadai pada wilayah pascabencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.
10. Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta masyarakat dalam segala aspek kehidupan bermasyarakat pada wilayah pascabencana.
11. Pemerintah Pusat, yang selanjutnya disebut Pemerintah, adalah Presiden Republik Indonesia yang memegang kekuasaan pemerintahan Negara Kesatuan Republik Indonesia sebagaimana dimaksud dalam Undang-Undang Dasar NegaraRepublik Indonesia Tahun 1945.
12. Pemerintah daerah adalah gubernur, bupati/walikota atau perangkat daerah sebagai unsur penyelenggara pemerintahan daerah.', 'BAB I (lanjutan 3)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8106, 'perka-4-2008', 7, 'menetapkan', 'BAB I (lanjutan 4)', NULL, 5, '13. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB, adalah lembaga pemerintah non-departemen sesuai dengan ketentuan peraturan perundang-undangan.
14. Badan Penanggulangan Bencana Daerah, yang selanjutnya disingkat BPBD, adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
Pedoman Penyusunan Rencana Penanggulangan Bencana 3 E. Landasan Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
a. Pasal 35
b. Pasal 36
c. Pasal 40 ayat (1) dan ayat (2)
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaran Penanggulangan Bencana
a. Pasal 5
b. Pasal 6 F. Sistematika Pedoman ini disusun dengan bab-bab sebagai berikut :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8106, '13. Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat dengan BNPB, adalah lembaga pemerintah non-departemen sesuai dengan ketentuan peraturan perundang-undangan.
14. Badan Penanggulangan Bencana Daerah, yang selanjutnya disingkat BPBD, adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
Pedoman Penyusunan Rencana Penanggulangan Bencana 3 E. Landasan Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
