INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8117, 'perka-4-2008', 18, 'menetapkan', 'BAB II', NULL, 7, 'PERENCANAAN DALAM PENANGGULANGAN BENCANA A. Penyelenggaraan Penanggulangan Bencana Pemerintah dan pemerintah daerah bertanggung jawab dalam penyelenggaraan penanggulangan bencana. Sebagaimana didefinisikan dalam UU 24 Tahun 2007 tentang Penanggulangan Bencana, penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
Rangkaian kegiatan tersebut apabila digambarkan dalam siklus penanggulangan bencana adalah sebagai berikut :
Pada dasarnya penyelenggaraan adalah tiga tahapan yakni :
1. Pra bencana yang meliputi:
- situasi tidak terjadi bencana
- situasi terdapat potensi bencana
2. Saat Tanggap Darurat yang dilakukan dalam situasi terjadi bencana
3. Pascabencana yang dilakukan dalam saat setelah terjadi bencana Tahapan bencana yang digambarkan di atas, sebaiknya tidak dipahami sebagai suatu pembagian tahapan yang tegas, dimana kegiatan pada tahap tertentu akan berakhir pada saat tahapan berikutnya dimulai. Akan tetapi harus dipahami bahwa setiap waktu semua tahapan dilaksanakan secara bersama-sama dengan porsi kegiatan yang berbeda. Misalnya pada tahap pemulihan, kegiatan utamanya adalah pemulihan tetapi kegiatan pencegahan dan mitigasi juga sudah dimulai untuk mengantisipasi bencana yang akan datang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8117, 'PERENCANAAN DALAM PENANGGULANGAN BENCANA A. Penyelenggaraan Penanggulangan Bencana Pemerintah dan pemerintah daerah bertanggung jawab dalam penyelenggaraan penanggulangan bencana. Sebagaimana didefinisikan dalam UU 24 Tahun 2007 tentang Penanggulangan Bencana, penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
Rangkaian kegiatan tersebut apabila digambarkan dalam siklus penanggulangan bencana adalah sebagai berikut :
Pada dasarnya penyelenggaraan adalah tiga tahapan yakni :
1. Pra bencana yang meliputi:
- situasi tidak terjadi bencana
- situasi terdapat potensi bencana
2. Saat Tanggap Darurat yang dilakukan dalam situasi terjadi bencana
3. Pascabencana yang dilakukan dalam saat setelah terjadi bencana Tahapan bencana yang digambarkan di atas, sebaiknya tidak dipahami sebagai suatu pembagian tahapan yang tegas, dimana kegiatan pada tahap tertentu akan berakhir pada saat tahapan berikutnya dimulai. Akan tetapi harus dipahami bahwa setiap waktu semua tahapan dilaksanakan secara bersama-sama dengan porsi kegiatan yang berbeda. Misalnya pada tahap pemulihan, kegiatan utamanya adalah pemulihan tetapi kegiatan pencegahan dan mitigasi juga sudah dimulai untuk mengantisipasi bencana yang akan datang.', 'BAB II', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8118, 'perka-4-2008', 19, 'menetapkan', 'BAB II (lanjutan 1)', NULL, 7, 'B. Perencanaan dalam Penyelenggaraan Penanggulangan Bencana Secara umum perencanaan dalam penanggulangan bencana dilakukan pada setiap tahapan dalam penyelenggaran penanggulangan bencana Pedoman Penyusunan Rencana Penanggulangan Bencana 5 PEMULIHAN PENCEGAHAN & MITIGASI RENCANA PB RENCANA RENCANA PEMULIHAN MITIGASI RENCANA RENCANA OPERASI KONTINJENSI Bencana Kajian Kilat 1 TANGGAP DARURAT KESIAPSIAGAAN Dalam penyelenggaraan penanggulangan bencana, agar setiap kegiatan dalam setiap tahapan dapat berjalan dengan terarah, maka disusun suatu rencana yang spesifik pada setiap tahapan penyelenggaraan penanggulangan bencana.
1. Pada tahap Prabencana dalam situasi tidak terjadi bencana, dilakukan penyusunan Rencana Penanggulangan Bencana (Disaster Management Plan), yang merupakan rencana umum dan menyeluruh yang meliputi seluruh tahapan / bidang kerja kebencanaan. Secara khusus untuk upaya pencegahan dan mitigasi bencana tertentu terdapat rencana yang disebut rencana mitigasi misalnya Rencana Mitigasi Bencana Banjir DKI Jakarta.
2. Pada tahap Prabencana dalam situasi terdapat potensi bencana dilakukan penyusunan Rencana Kesiapsiagaan untuk menghadapi keadaan darurat yang didasarkan atas skenario menghadapi bencana tertentu (single hazard) maka disusun satu rencana yang disebut Rencana Kontinjensi (Contingency Plan).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8118, 'B. Perencanaan dalam Penyelenggaraan Penanggulangan Bencana Secara umum perencanaan dalam penanggulangan bencana dilakukan pada setiap tahapan dalam penyelenggaran penanggulangan bencana Pedoman Penyusunan Rencana Penanggulangan Bencana 5 PEMULIHAN PENCEGAHAN & MITIGASI RENCANA PB RENCANA RENCANA PEMULIHAN MITIGASI RENCANA RENCANA OPERASI KONTINJENSI Bencana Kajian Kilat 1 TANGGAP DARURAT KESIAPSIAGAAN Dalam penyelenggaraan penanggulangan bencana, agar setiap kegiatan dalam setiap tahapan dapat berjalan dengan terarah, maka disusun suatu rencana yang spesifik pada setiap tahapan penyelenggaraan penanggulangan bencana.
1. Pada tahap Prabencana dalam situasi tidak terjadi bencana, dilakukan penyusunan Rencana Penanggulangan Bencana (Disaster Management Plan), yang merupakan rencana umum dan menyeluruh yang meliputi seluruh tahapan / bidang kerja kebencanaan. Secara khusus untuk upaya pencegahan dan mitigasi bencana tertentu terdapat rencana yang disebut rencana mitigasi misalnya Rencana Mitigasi Bencana Banjir DKI Jakarta.
2. Pada tahap Prabencana dalam situasi terdapat potensi bencana dilakukan penyusunan Rencana Kesiapsiagaan untuk menghadapi keadaan darurat yang didasarkan atas skenario menghadapi bencana tertentu (single hazard) maka disusun satu rencana yang disebut Rencana Kontinjensi (Contingency Plan).', 'BAB II (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8119, 'perka-4-2008', 20, 'menetapkan', 'BAB II (lanjutan 2)', NULL, 8, '3. Pada Saat Tangap Darurat dilakukan Rencana Operasi (Operational Plan) yang merupakan operasionalisasi/aktivasi dari Rencana Kedaruratan atau Rencana Kontinjensi yang telah disusun sebelumnya.
4. Pada Tahap Pemulihan dilakukan Penyusunan Rencana Pemulihan (Recovery Plan) yang meliputi rencana rehabilitasi dan rekonstruksi yang dilakukan pada pasca bencana. Sedangkan jika bencana belum terjadi, maka untuk mengantisipasi kejadian bencana dimasa mendatang dilakukan penyusunan petunjuk /pedoman mekanisme penanggulangan pasca bencana.
6 Pedoman Penyusunan Rencana Penanggulangan Bencana C. Perencanaan Penanggulangan Bencana Perencanaan penanggulangan bencana disusun berdasarkan hasil analisis risiko bencana dan upaya penanggulangannya yang dijabarkan dalam program kegiatan penanggulangan bencana dan rincian anggarannya.
Perencanaan penanggulangan bencana merupakan bagian dari perencanaan pembangunan. Setiap rencana yang dihasilkan dalam perencanaan ini merupakan program/kegiatan yang terkait dengan pencegahan, mitigasi dan kesiapsiagaan yang dimasukkan dalam Rencana Pembangunan Jangka Panjang (RPJP), Jangka Menengah (RPJM) maupun Rencana Kerja Pemerintah (RKP) tahunan.
Rencana penanggulangan bencanaditetapkan oleh Pemerintah dan pemerintah daerah sesuai dengan kewenangan untuk jangka waktu 5 (lima) tahun.
Penyusunan rencana penanggulangan bencana dikoordinasikan oleh:
1. BNPB untuk tingkat nasional;
2. BPBD provinsi untuk tingkat provinsi; dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8119, '3. Pada Saat Tangap Darurat dilakukan Rencana Operasi (Operational Plan) yang merupakan operasionalisasi/aktivasi dari Rencana Kedaruratan atau Rencana Kontinjensi yang telah disusun sebelumnya.
4. Pada Tahap Pemulihan dilakukan Penyusunan Rencana Pemulihan (Recovery Plan) yang meliputi rencana rehabilitasi dan rekonstruksi yang dilakukan pada pasca bencana. Sedangkan jika bencana belum terjadi, maka untuk mengantisipasi kejadian bencana dimasa mendatang dilakukan penyusunan petunjuk /pedoman mekanisme penanggulangan pasca bencana.
6 Pedoman Penyusunan Rencana Penanggulangan Bencana C. Perencanaan Penanggulangan Bencana Perencanaan penanggulangan bencana disusun berdasarkan hasil analisis risiko bencana dan upaya penanggulangannya yang dijabarkan dalam program kegiatan penanggulangan bencana dan rincian anggarannya.
Perencanaan penanggulangan bencana merupakan bagian dari perencanaan pembangunan. Setiap rencana yang dihasilkan dalam perencanaan ini merupakan program/kegiatan yang terkait dengan pencegahan, mitigasi dan kesiapsiagaan yang dimasukkan dalam Rencana Pembangunan Jangka Panjang (RPJP), Jangka Menengah (RPJM) maupun Rencana Kerja Pemerintah (RKP) tahunan.
Rencana penanggulangan bencanaditetapkan oleh Pemerintah dan pemerintah daerah sesuai dengan kewenangan untuk jangka waktu 5 (lima) tahun.
Penyusunan rencana penanggulangan bencana dikoordinasikan oleh:
1. BNPB untuk tingkat nasional;
2. BPBD provinsi untuk tingkat provinsi; dan', 'BAB II (lanjutan 2)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8120, 'perka-4-2008', 21, 'menetapkan', 'BAB II (lanjutan 3)', NULL, 9, '3. BPBD kabupaten/kota untuk tingkat kabupaten/kota.
Rencana penanggulangan bencana ditinjau secara berkala setiap 2 (dua) tahun atau sewaktu-waktu apabila terjadi bencana.
D. Proses Penyusunan Rencana Penanggulangan Bencana Secara garis besar proses penyusunan/penulisan rencana penanggulangan bencana adalah sebagai berikut :
Pedoman Penyusunan Rencana Penanggulangan Bencana 7 E. Uraian Proses Perencanaan Penanggulangan Bencana Sebagaimana diuraikan di atas bahwa langkah pertama adalah pengenalan bahaya / anaman bencana yang mengancam wilayah tersebut. Kemudian bahaya / ancaman tersebut di buat daftar dan di disusun langkah-langkah / kegiatan untuk penangulangannya.
Sebagai prinsip dasar dalam melakukan Penyusunan Rencana Penanggulangan Bencana ini adalah menerapkan paradigma pengelolaan risiko bencana secara holistik. Pada hakekatnya bencana adalah sesuatu yang tidak dapat terpisahkan dari kehidupan.
Pandangan ini memberikan arahan bahwa bencana harus dikelola secara menyeluruh sejak sebelum, pada saat dan setelah kejadian bencana.
8 Pedoman Penyusunan Rencana Penanggulangan Bencana');
