INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8131, 'perka-4-2008', 32, 'menetapkan', 'BAB V', NULL, 18, 'PILIHAN TINDAKAN PENANGGULANGAN BENCANA Pilihan tindakan yang dimaksud di sini adalah berbagai upaya penanggulangan yang akan dilakukan berdasarkan perkiraan ancaman bahaya yang akan terjadi dan kemungkinan dampak yang ditimbulkan.
Secara lebih rinci pilihan tindakan tersebut dapat diuraikan sebagai berikut:
A. Pencegahan dan Mitigasi Upaya atau kegiatan dalam rangka pencegahan dan mitigasi yang dilakukan, bertujuan untuk menghindari terjadinya bencana serta mengurangi risiko yang ditimbulkan oleh bencana. Tindakan mitigasi dilihat dari sifatnya dapat digolongkan menjadi 2 (dua) bagian, yaitu mitigasi pasif dan mitigasi aktif.
Tindakan pencegahan yang tergolong dalam mitigasi pasif antara lain adalah:
1. Penyusunan peraturan perundang-undangan
2. Pembuatan peta rawan bencana dan pemetaan masalah.
3. Pembuatan pedoman/standar/prosedur
4. Pembuatan brosur/leaflet/poster
5. Penelitian / pengkajian karakteristik bencana
6. Pengkajian / analisis risiko bencana
7. Internalisasi PB dalam muatan lokal pendidikan
8. Pembentukan organisasi atau satuan gugus tugas bencana
9. Perkuatan unit-unit sosial dalam masyarakat, seperti forum
10. Pengarus-utamaan PB dalam perencanaan pembangunan Sedangkan tindakan pencegahan yang tergolong dalam mitigasi aktif antara lain:
1. Pembuatan dan penempatan tanda-tanda peringatan, bahaya, larangan memasuki daerah rawan bencana dsb.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8131, 'PILIHAN TINDAKAN PENANGGULANGAN BENCANA Pilihan tindakan yang dimaksud di sini adalah berbagai upaya penanggulangan yang akan dilakukan berdasarkan perkiraan ancaman bahaya yang akan terjadi dan kemungkinan dampak yang ditimbulkan.
Secara lebih rinci pilihan tindakan tersebut dapat diuraikan sebagai berikut:
A. Pencegahan dan Mitigasi Upaya atau kegiatan dalam rangka pencegahan dan mitigasi yang dilakukan, bertujuan untuk menghindari terjadinya bencana serta mengurangi risiko yang ditimbulkan oleh bencana. Tindakan mitigasi dilihat dari sifatnya dapat digolongkan menjadi 2 (dua) bagian, yaitu mitigasi pasif dan mitigasi aktif.
Tindakan pencegahan yang tergolong dalam mitigasi pasif antara lain adalah:
1. Penyusunan peraturan perundang-undangan
2. Pembuatan peta rawan bencana dan pemetaan masalah.
3. Pembuatan pedoman/standar/prosedur
4. Pembuatan brosur/leaflet/poster
5. Penelitian / pengkajian karakteristik bencana
6. Pengkajian / analisis risiko bencana
7. Internalisasi PB dalam muatan lokal pendidikan
8. Pembentukan organisasi atau satuan gugus tugas bencana
9. Perkuatan unit-unit sosial dalam masyarakat, seperti forum
10. Pengarus-utamaan PB dalam perencanaan pembangunan Sedangkan tindakan pencegahan yang tergolong dalam mitigasi aktif antara lain:
1. Pembuatan dan penempatan tanda-tanda peringatan, bahaya, larangan memasuki daerah rawan bencana dsb.', 'BAB V', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8132, 'perka-4-2008', 33, 'menetapkan', 'BAB V (lanjutan 1)', NULL, 18, '2. Pengawasan terhadap pelaksanaan berbagai peraturan tentang penataan ruang, ijin mendirikan bangunan (IMB), dan peraturan lain yang berkaitan dengan pencegahan bencana.
3. Pelatihan dasar kebencanaan bagi aparat dan masyarakat.
4. Pemindahan penduduk dari daerah yang rawan bencana ke daerah yang lebih aman.
5. Penyuluhan dan peningkatan kewaspadaan masyarakat.
16 Pedoman Penyusunan Rencana Penanggulangan Bencana
6. Perencanaan daerah penampungan sementara dan jalur-jalur evakuasi jika terjadi bencana.
7. Pembuatan bangunan struktur yang berfungsi untuk mencegah, mengamankan dan mengurangi dampak yang ditimbulkan oleh bencana, seperti: tanggul, dam, penahan erosi pantai, bangunan tahan gempa dan sejenisnya.
Adakalanya kegiatan mitigasi ini digolongkan menjadi mitigasi yang bersifat non-struktural (berupa peraturan, penyuluhan, pendidikan) dan yang bersifat struktural (berupa bangunan dan prasarana).
B. Kesiapsiagaan Kesiapsiagaan dilaksanakan untuk mengantisipasi kemungkinan terjadinya bencana guna menghindari jatuhnya korban jiwa, kerugian harta benda dan berubahnya tata kehidupan masyarakat. Upaya kesiapsiagaan dilakukan pada saat bencana mulai teridentifikasi akan terjadi, kegiatan yang dilakukan antara lain:
1. Pengaktifan pos-pos siaga bencana dengan segenap unsur pendukungnya.
2. Pelatihan siaga / simulasi / gladi / teknis bagi setiap sektor Penanggulangan bencana (SAR, sosial, kesehatan, prasarana dan pekerjaan umum).
3. Inventarisasi sumber daya pendukung kedaruratan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8132, '2. Pengawasan terhadap pelaksanaan berbagai peraturan tentang penataan ruang, ijin mendirikan bangunan (IMB), dan peraturan lain yang berkaitan dengan pencegahan bencana.
3. Pelatihan dasar kebencanaan bagi aparat dan masyarakat.
4. Pemindahan penduduk dari daerah yang rawan bencana ke daerah yang lebih aman.
5. Penyuluhan dan peningkatan kewaspadaan masyarakat.
16 Pedoman Penyusunan Rencana Penanggulangan Bencana
6. Perencanaan daerah penampungan sementara dan jalur-jalur evakuasi jika terjadi bencana.
7. Pembuatan bangunan struktur yang berfungsi untuk mencegah, mengamankan dan mengurangi dampak yang ditimbulkan oleh bencana, seperti: tanggul, dam, penahan erosi pantai, bangunan tahan gempa dan sejenisnya.
Adakalanya kegiatan mitigasi ini digolongkan menjadi mitigasi yang bersifat non-struktural (berupa peraturan, penyuluhan, pendidikan) dan yang bersifat struktural (berupa bangunan dan prasarana).
B. Kesiapsiagaan Kesiapsiagaan dilaksanakan untuk mengantisipasi kemungkinan terjadinya bencana guna menghindari jatuhnya korban jiwa, kerugian harta benda dan berubahnya tata kehidupan masyarakat. Upaya kesiapsiagaan dilakukan pada saat bencana mulai teridentifikasi akan terjadi, kegiatan yang dilakukan antara lain:
1. Pengaktifan pos-pos siaga bencana dengan segenap unsur pendukungnya.
2. Pelatihan siaga / simulasi / gladi / teknis bagi setiap sektor Penanggulangan bencana (SAR, sosial, kesehatan, prasarana dan pekerjaan umum).
3. Inventarisasi sumber daya pendukung kedaruratan', 'BAB V (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8133, 'perka-4-2008', 34, 'menetapkan', 'BAB V (lanjutan 2)', NULL, 19, '4. Penyiapan dukungan dan mobilisasi sumberdaya/logistik.
5. Penyiapan sistem informasi dan komunikasi yang cepat dan terpadu guna mendukung tugas kebencanaan.
6. Penyiapan dan pemasangan instrumen sistem peringatan dini (early warning)
7. Penyusunan rencana kontinjensi (contingency plan)
8. Mobilisasi sumber daya (personil dan prasarana/sarana peralatan) C. Tanggap Darurat Tahap Tanggap Darurat merupakan tahap penindakan atau pengerahan pertolongan untuk membantu masyarakat yang tertimpa bencana, guna menghindari bertambahnya korban jiwa.
Penyelenggaraan penanggulangan bencana pada saat tanggap darurat meliputi:
1. pengkajian secara cepat dan tepat terhadap lokasi, kerusakan, kerugian, dan sumber daya;
2. penentuan status keadaan darurat bencana;
Pedoman Penyusunan Rencana Penanggulangan Bencana 17
3. penyelamatan dan evakuasi masyarakat terkena bencana;
4. pemenuhan kebutuhan dasar;
5. perlindungan terhadap kelompok rentan; dan
6. pemulihan dengan segera prasarana dan sarana vital.
D. Pemulihan Tahap pemulihan meliputi tahap rehabilitasi dan rekonstruksi. Upaya yang dilakukan pada tahap rehabilitasi adalah untuk mengembalikan kondisi daerah yang terkena bencana yang serba tidak menentu ke kondisi normal yang lebih baik, agar kehidupan dan penghidupan masyarakat dapat berjalan kembali.
Kegiatan-kegiatan yang dilakukan meliputi:
1. perbaikan lingkungan daerah bencana;
2. perbaikan prasarana dan sarana umum;
3. pemberian bantuan perbaikan rumah masyarakat;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8133, '4. Penyiapan dukungan dan mobilisasi sumberdaya/logistik.
5. Penyiapan sistem informasi dan komunikasi yang cepat dan terpadu guna mendukung tugas kebencanaan.
6. Penyiapan dan pemasangan instrumen sistem peringatan dini (early warning)
7. Penyusunan rencana kontinjensi (contingency plan)
8. Mobilisasi sumber daya (personil dan prasarana/sarana peralatan) C. Tanggap Darurat Tahap Tanggap Darurat merupakan tahap penindakan atau pengerahan pertolongan untuk membantu masyarakat yang tertimpa bencana, guna menghindari bertambahnya korban jiwa.
