INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8135, 'perka-4-2008', 36, 'menetapkan', 'BAB VI', NULL, 21, 'MEKANISME KESIAPAN DAN PENANGGULANGAN DAMPAK BENCANA Dalam melaksanakan penanggulangan bencana, maka penyelenggaraan penanggulangan bencana meliputi :
• tahap prabencana,
• saat tanggap darurat, dan
• pascabencana.
A. Pada Pra Bencana Pada tahap pra bencana ini meliputi dua keadaan yaitu :
• Dalam situasi tidak terjadi bencana
• Dalam situasi terdapat potensi bencana
1. Situasi Tidak Terjadi Bencana Situasi tidak ada potensi bencana yaitu kondisi suatu wilayah yang berdasarkan analisis kerawanan bencana pada periode waktu tertentu tidak menghadapi ancaman bencana yang nyata.
Penyelenggaraan penanggulangan bencana dalam situasi tidak terjadi bencana meliputi :
a. perencanaan penanggulangan bencana;
b. pengurangan risiko bencana;
c. pencegahan;
d. pemaduan dalam perencanaan pembangunan;
e. persyaratan analisis risiko bencana;
f. pelaksanaan dan penegakan rencana tata ruang;
g. pendidikan dan pelatihan; dan
h. persyaratan standar teknis penanggulangan bencana.
2. Situasi Terdapat Potensi Bencana Pada situasi ini perlu adanya kegiatan-kegiatan kesiap siagaan, peringatan dini dan mitigasi bencana dalam penanggulangan bencana.
a. Kesiapsiagaan
b. Peringatan Dini
c. Mitigasi Bencana Kegiatan-kegiatan pra-bencana ini dilakukan secara lintas sector dan multi stakeholder,oleh karena itu fungsi BNPB/BPBD adalah fungsi koordinasi.
Pedoman Penyusunan Rencana Penanggulangan Bencana 19 B. Saat Tanggap Darurat Penyelenggaraan penanggulangan bencana pada saat tanggap darurat meliputi:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8135, 'MEKANISME KESIAPAN DAN PENANGGULANGAN DAMPAK BENCANA Dalam melaksanakan penanggulangan bencana, maka penyelenggaraan penanggulangan bencana meliputi :
• tahap prabencana,
• saat tanggap darurat, dan
• pascabencana.
A. Pada Pra Bencana Pada tahap pra bencana ini meliputi dua keadaan yaitu :
• Dalam situasi tidak terjadi bencana
• Dalam situasi terdapat potensi bencana
1. Situasi Tidak Terjadi Bencana Situasi tidak ada potensi bencana yaitu kondisi suatu wilayah yang berdasarkan analisis kerawanan bencana pada periode waktu tertentu tidak menghadapi ancaman bencana yang nyata.
Penyelenggaraan penanggulangan bencana dalam situasi tidak terjadi bencana meliputi :
a. perencanaan penanggulangan bencana;
b. pengurangan risiko bencana;
c. pencegahan;
d. pemaduan dalam perencanaan pembangunan;
e. persyaratan analisis risiko bencana;
f. pelaksanaan dan penegakan rencana tata ruang;
g. pendidikan dan pelatihan; dan
h. persyaratan standar teknis penanggulangan bencana.
2. Situasi Terdapat Potensi Bencana Pada situasi ini perlu adanya kegiatan-kegiatan kesiap siagaan, peringatan dini dan mitigasi bencana dalam penanggulangan bencana.
a. Kesiapsiagaan
b. Peringatan Dini
c. Mitigasi Bencana Kegiatan-kegiatan pra-bencana ini dilakukan secara lintas sector dan multi stakeholder,oleh karena itu fungsi BNPB/BPBD adalah fungsi koordinasi.
Pedoman Penyusunan Rencana Penanggulangan Bencana 19 B. Saat Tanggap Darurat Penyelenggaraan penanggulangan bencana pada saat tanggap darurat meliputi:', 'BAB VI', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8136, 'perka-4-2008', 37, 'menetapkan', 'BAB VI (lanjutan 1)', NULL, 22, '1. pengkajian secara cepat dan tepat terhadap lokasi, kerusakan, dan sumber daya;
2. penentuan status keadaan darurat bencana;
3. penyelamatan dan evakuasi masyarakat terkena bencana;
4. pemenuhan kebutuhan dasar;
5. perlindungan terhadap kelompok rentan; dan
6. pemulihan dengan segera prasarana dan sarana vital.
C. Pasca Bencana Penyelenggaraan penanggulangan bencana pada tahap pasca bencana meliputi:
1. rehabilitasi; dan
2. rekonstruksi.
Secara lebih rinci antara lain dapat dilihat pada Bab VI (Bab Pilihan Tindakan Penanggulangan Bencana).
D. Mekanisme Penanggulangan Bencana Mekanisme penanggulangan bencana yang akan dianut dalam hal ini adalah mengacu pada UU No 24 Tahun 2007 Tentang Penanggulangan Bencana dan Peraturan Pemerintah No 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
Dari peraturan perundang-undangan tersebut di atas, dinyatakan bahwa mekanismetersebut dibagi ke dalam tiga tahapan yaitu :
1. Pada pra bencana maka fungsi BPBD bersifat koordinasi dan pelaksana,
2. Pada saat Darurat bersifat koordinasi, komando dan pelaksana
3. Pada pasca bencana bersifat koordinasi dan pelaksana.
20 Pedoman Penyusunan Rencana Penanggulangan Bencana');
