INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8137, 'perka-4-2008', 38, 'menetapkan', 'BAB VII', NULL, 23, 'ALOKASI DAN PERAN PELAKU KEGIATAN PENANGGULANGAN BENCANA A. Peran dan Fungsi Instansi Pemerintahan Terkait Dalam melaksanakan penanggulangan becana di daerah akan memerlukan koordinasi dengan sektor. Secara garis besar dapat diuraikan peran lintas sektor sebagai berikut :
1. Sektor Pemerintahan, mengendalikan kegiatan pembinaan pembangunan daerah
2. Sektor Kesehatan, merencanakan pelayanan kesehatan dan medik termasuk obat-obatan dan para medis
3. Sektor Sosial, merencanakan kebutuhan pangan, sandang, dan kebutuhan dasar lainnya untuk para pengungsi
4. Sektor Pekerjaan Umum, merencanakan tata ruang daerah, penyiapan lokasi dan jalur evakuasi, dan kebutuhan pemulihan sarana dan prasarana.
5. Sektor Perhubungan, melakukan deteksi dini dan informasi cuaca/meteorologi dan merencanakan kebutuhan transportasi dan komunikasi
6. Sektor Energi dan Sumber Daya Mineral, merencanakan dan mengendalikan upaya mitigatif di bidang bencana geologi dan bencana akibat ulah manusia yang terkait dengan bencana geologi sebelumnya
7. Sektor Tenaga Kerja dan Transmigrasi, merencanakan pengerahan dan pemindahan korban bencana ke daerah yang aman bencana.
8. Sektor Keuangan, penyiapan anggaran biaya kegiatan penyelenggaraan penanggulangan bencana pada masa pra bencana
9. Sektor Kehutanan, merencanakan dan mengendalikan upaya mitigatif khususnya kebakaran hutan/lahan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8137, 'ALOKASI DAN PERAN PELAKU KEGIATAN PENANGGULANGAN BENCANA A. Peran dan Fungsi Instansi Pemerintahan Terkait Dalam melaksanakan penanggulangan becana di daerah akan memerlukan koordinasi dengan sektor. Secara garis besar dapat diuraikan peran lintas sektor sebagai berikut :
1. Sektor Pemerintahan, mengendalikan kegiatan pembinaan pembangunan daerah
2. Sektor Kesehatan, merencanakan pelayanan kesehatan dan medik termasuk obat-obatan dan para medis
3. Sektor Sosial, merencanakan kebutuhan pangan, sandang, dan kebutuhan dasar lainnya untuk para pengungsi
4. Sektor Pekerjaan Umum, merencanakan tata ruang daerah, penyiapan lokasi dan jalur evakuasi, dan kebutuhan pemulihan sarana dan prasarana.
5. Sektor Perhubungan, melakukan deteksi dini dan informasi cuaca/meteorologi dan merencanakan kebutuhan transportasi dan komunikasi
6. Sektor Energi dan Sumber Daya Mineral, merencanakan dan mengendalikan upaya mitigatif di bidang bencana geologi dan bencana akibat ulah manusia yang terkait dengan bencana geologi sebelumnya
7. Sektor Tenaga Kerja dan Transmigrasi, merencanakan pengerahan dan pemindahan korban bencana ke daerah yang aman bencana.
8. Sektor Keuangan, penyiapan anggaran biaya kegiatan penyelenggaraan penanggulangan bencana pada masa pra bencana
9. Sektor Kehutanan, merencanakan dan mengendalikan upaya mitigatif khususnya kebakaran hutan/lahan', 'BAB VII', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8138, 'perka-4-2008', 39, 'menetapkan', 'BAB VII (lanjutan 1)', NULL, 23, '10. Sektor Lingkungan Hidup, merencanakan dan mengendalikan upaya yang bersifat preventif, advokasi, dan deteksi dini dalam pencegahan bencana.
11. Sektor Kelautan merencanakan dan mengendalikan upaya mitigatif di bidang bencana tsunami dan abrasi pantai.
12. Sektor Lembaga Penelitian dan Peendidikan Tinggi, melakukan kajian dan penelitian sebagai bahan untuk merencanakan penyelenggaraan penanggulangan bencana pada masa pra bencana, tanggap darurat, rehabilitasi dan rekonstruksi.
Pedoman Penyusunan Rencana Penanggulangan Bencana 21
13. TNI/POLRI membantu dalam kegiatan SAR, dan pengamanan saat darurat termasuk mengamankan lokasi yang ditinggalkan karena penghuninya mengungsi.
B. Peran dan Potensi Masyarakat
1. Masyarakat Masyarakat sebagai pelaku awal penanggulangan bencana sekaligus korban bencana harus mampu dalam batasan tertentu menangani bencana sehingga diharapkan bencana tidak berkembang ke skala yang lebih besar.
2. Swasta Peran swasta belum secara optimal diberdayakan. Peran swasta cukup menonjol pada saat kejadian bencana yaitu saat pemberian bantuan darurat. Partisipasi yang lebih luas dari sektor swasta ini akan sangat berguna bagi peningkatan ketahanan nasional dalam menghadapi bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8138, '10. Sektor Lingkungan Hidup, merencanakan dan mengendalikan upaya yang bersifat preventif, advokasi, dan deteksi dini dalam pencegahan bencana.
11. Sektor Kelautan merencanakan dan mengendalikan upaya mitigatif di bidang bencana tsunami dan abrasi pantai.
12. Sektor Lembaga Penelitian dan Peendidikan Tinggi, melakukan kajian dan penelitian sebagai bahan untuk merencanakan penyelenggaraan penanggulangan bencana pada masa pra bencana, tanggap darurat, rehabilitasi dan rekonstruksi.
Pedoman Penyusunan Rencana Penanggulangan Bencana 21
13. TNI/POLRI membantu dalam kegiatan SAR, dan pengamanan saat darurat termasuk mengamankan lokasi yang ditinggalkan karena penghuninya mengungsi.
B. Peran dan Potensi Masyarakat
1. Masyarakat Masyarakat sebagai pelaku awal penanggulangan bencana sekaligus korban bencana harus mampu dalam batasan tertentu menangani bencana sehingga diharapkan bencana tidak berkembang ke skala yang lebih besar.
2. Swasta Peran swasta belum secara optimal diberdayakan. Peran swasta cukup menonjol pada saat kejadian bencana yaitu saat pemberian bantuan darurat. Partisipasi yang lebih luas dari sektor swasta ini akan sangat berguna bagi peningkatan ketahanan nasional dalam menghadapi bencana.', 'BAB VII (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8139, 'perka-4-2008', 40, 'menetapkan', 'BAB VII (lanjutan 2)', NULL, 24, '3. Lembaga Non-Pemerintah Lembaga-lembaga Non Pemerintah pada dasarnya memiliki fleksibilitas dan kemampuan yang memadai dalam upaya penanggulangan bencana. Dengan koordinasi yang baik lembaga Non Pemerintah ini akan dapat memberikan kontribusi dalam upaya penanggulangan bencana mulai dari tahap sebelum, pada saat dan pasca bencana.
4. Perguruan Tinggi / Lembaga Penelitian Penanggulangan bencana dapat efektif dan efisien jika dilakukan berdasarkan penerapan ilmupengetahuan dan teknologi yang tepat. Untuk itu diperlukan kontribusi pemikiran dari para ahli dari lembaga-lembaga pendidikan dan penelitian.
5. Media Media memiliki kemampuan besar untuk membentuk opini publik. Untuk itu peran media sangat penting dalam hal membangun ketahanan masyarakat menghadapi bencana melalui kecepatan dan ketepatan dalam memberikan informasi kebencanaan berupa peringatan dini, kejadian bencana serta upaya penanggulangannya, serta pendidikan kebencanaan kepada masyarakat.
6. Lembaga Internasional Pada dasarnya Pemerintah dapat menerima bantuan dari lembaga internasional, baik pada saat pra bencana, saat tanggap darurta maupun pasca bencana. Namun demikian harus mengikuti peraturan dan perundang-undangan yang berlaku.
22 Pedoman Penyusunan Rencana Penanggulangan Bencana Sebagai gambaran lebih rinci, dapat diperiksa pada tabel contoh berikut :');
