INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8140, 'perka-4-2008', 41, 'menetapkan', 'BAB VII (lanjutan 3)', NULL, 25, 'Dep.ESDM TNI/POLRI Depdagri Pilihan Instansi Depkes Depsos Dep PU Tindakan Kegiatan BNPB BMG LSM dll Pra bencana 1. Pembuatan Peta Rawan saat tidak terja- 2.Penyuluhan di bencana 3.Pelatihan 4.Pengembangan SDM 5.Analisis risiko & bahaya 6 Litbang 7.Dan lain-lain Pra bencana 1 Pembentukan POSKO saat terdapat 2.Peringatan Potensi bencana 3..Rencana Kontinjensi 4.Dan lain-lain Pada Saat 1.Pernyataan Bencana Tanggap 2. Bantuan Darurat Darurat 3.Dan lain-lain Pasca Bencana 1. Kaji Bencana
2. Rehabilitasi
3. Rekonstruksi O = Penanggung Jawab ∆ = Terlibat Langsung + = Terlibat Tidak Langsung C. Pendanaan Sebagian besar pembiayaan untuk kegiatan-kegiatan Penanggulangan bencana terintegrasikan dalam kegiatan-kegiatan pemerintahan dan pembangunan yang dibiayai dari anggaran pendapatan dan belanja nasional, propinsi atau kabupaten/kota. Kegiatan sektoral dibiayai dari anggaran masing-masing sektor yang bersangkutan.
Kegiatan-kegiatan khusus seperti pelatihan, kesiapan, penyediaan peralatan khusus dibiayai dari pos-pos khusus dari anggaran pendapatan dan belanja nasional, propinsi atau kabupaten/kota.
Pemerintah dapat menganggarkan dana kontinjensi untuk mengantisipasi diperlukannya dana tambahan untuk menanggulangi kedaruratan. Besarnya dan tatacara akses serta penggunaannya diatur bersama dengan DPR yang bersangkutan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8140, 'Dep.ESDM TNI/POLRI Depdagri Pilihan Instansi Depkes Depsos Dep PU Tindakan Kegiatan BNPB BMG LSM dll Pra bencana 1. Pembuatan Peta Rawan saat tidak terja- 2.Penyuluhan di bencana 3.Pelatihan 4.Pengembangan SDM 5.Analisis risiko & bahaya 6 Litbang 7.Dan lain-lain Pra bencana 1 Pembentukan POSKO saat terdapat 2.Peringatan Potensi bencana 3..Rencana Kontinjensi 4.Dan lain-lain Pada Saat 1.Pernyataan Bencana Tanggap 2. Bantuan Darurat Darurat 3.Dan lain-lain Pasca Bencana 1. Kaji Bencana
2. Rehabilitasi
3. Rekonstruksi O = Penanggung Jawab ∆ = Terlibat Langsung + = Terlibat Tidak Langsung C. Pendanaan Sebagian besar pembiayaan untuk kegiatan-kegiatan Penanggulangan bencana terintegrasikan dalam kegiatan-kegiatan pemerintahan dan pembangunan yang dibiayai dari anggaran pendapatan dan belanja nasional, propinsi atau kabupaten/kota. Kegiatan sektoral dibiayai dari anggaran masing-masing sektor yang bersangkutan.
Kegiatan-kegiatan khusus seperti pelatihan, kesiapan, penyediaan peralatan khusus dibiayai dari pos-pos khusus dari anggaran pendapatan dan belanja nasional, propinsi atau kabupaten/kota.
Pemerintah dapat menganggarkan dana kontinjensi untuk mengantisipasi diperlukannya dana tambahan untuk menanggulangi kedaruratan. Besarnya dan tatacara akses serta penggunaannya diatur bersama dengan DPR yang bersangkutan.', 'BAB VII (lanjutan 3)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8141, 'perka-4-2008', 42, 'menetapkan', 'BAB VII (lanjutan 4)', NULL, 25, 'Pedoman Penyusunan Rencana Penanggulangan Bencana 23 Bantuan dari masyarakat dan sektor non-pemerintah, termasuk badan-badan PBB dan masyarakat internasional, dikelola secara transparan oleh unit-unit koordinasi.
Contoh rekapitulasi (matriks) Rencana Penanggulangan Bencana :
No Kagiatan Pelaku Sumber dana Keterangan 1 Pambuatan Dinas PU DIPA Tanggul 2 Penyuluhan BNPB, Pemerintah : DIPA Pengurangan Depkes, LSM : Mandiri Risiko LSM .. dan seterusnya 24 Pedoman Penyusunan Rencana Penanggulangan Bencana');
