INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8149, 'perka-4-2008', 50, 'menetapkan', 'BAB IX', NULL, 28, 'PENGESAHAN Dalam penyusunan rencana penanggulangan bencana, hendaknya dilegalkan dengan ditandatangani oleh instansi yang berwenang (Kepala Wilayah). Hal tersebut selain mempunyai kekuatan hukum untuk dapat dilaksanakan, juga dapat menjadi perekat dari masing-masing instansi sekaligus untuk mengetahui tugas dan fungsi masing-masing pelaku di dalam wilayah tersebut.
26 Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8149, 'PENGESAHAN Dalam penyusunan rencana penanggulangan bencana, hendaknya dilegalkan dengan ditandatangani oleh instansi yang berwenang (Kepala Wilayah). Hal tersebut selain mempunyai kekuatan hukum untuk dapat dilaksanakan, juga dapat menjadi perekat dari masing-masing instansi sekaligus untuk mengetahui tugas dan fungsi masing-masing pelaku di dalam wilayah tersebut.
26 Pedoman Penyusunan Rencana Penanggulangan Bencana', 'BAB IX', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8150, 'perka-4-2008', 51, 'menetapkan', 'BAB X', NULL, 29, 'RENCANA AKSI DAERAH Pengurangan Risiko Bencana adalah sebuah pendekatan sistematis yaitu mengidentifikasi, mengkaji dan mengurangi risiko-risiko bencana, bertujuan untuk mengurangi kerentanan-kerentanan sosial-ekonomi terhadap bencana dan menangani bahaya-bahaya lingkungan maupun bahaya-bahaya lain yang menimbulkan kerentanan.
Pengurangan Risiko Bencana merupakan tanggung jawab lembaga-lembaga yang bergerak dalam bidang pembangunan maupun lembaga-lembaga bantuan kemanusiaan dan harus menjadi bagian terpadu dari kerja-kerja organisasi semacam ini, bukan sekedar kegiatan tambahan atau kegiatan terpisah yang dilakukan sesekali saja. Oleh karenanya, upaya Pengurangan Risiko Bencana sangat luas. Dalam setiap sektor dari kerja pembangunan dan bantuan kemanusiaan terdapat peluang untuk melaksanakan prakarsa-prakarsa Pengurangan Risiko Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8150, 'RENCANA AKSI DAERAH Pengurangan Risiko Bencana adalah sebuah pendekatan sistematis yaitu mengidentifikasi, mengkaji dan mengurangi risiko-risiko bencana, bertujuan untuk mengurangi kerentanan-kerentanan sosial-ekonomi terhadap bencana dan menangani bahaya-bahaya lingkungan maupun bahaya-bahaya lain yang menimbulkan kerentanan.
Pengurangan Risiko Bencana merupakan tanggung jawab lembaga-lembaga yang bergerak dalam bidang pembangunan maupun lembaga-lembaga bantuan kemanusiaan dan harus menjadi bagian terpadu dari kerja-kerja organisasi semacam ini, bukan sekedar kegiatan tambahan atau kegiatan terpisah yang dilakukan sesekali saja. Oleh karenanya, upaya Pengurangan Risiko Bencana sangat luas. Dalam setiap sektor dari kerja pembangunan dan bantuan kemanusiaan terdapat peluang untuk melaksanakan prakarsa-prakarsa Pengurangan Risiko Bencana.', 'BAB X', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8151, 'perka-4-2008', 52, 'menetapkan', 'BAB X (lanjutan 1)', NULL, 29, 'Konsep Pengurangan Risiko Bencana melihat bencana sebagai sebuah permasalahan kompleks yang menuntut adanya penanganan kolektif yang melibatkan berbagai disiplin dan kelompok kelembagaan yang berbeda. Ini merupakan hal penting untuk dipertimbangkan dalam melihat karakteristik-karakteristik masyarakat yang tahan bencana, karena lembaga-lembaga harus menentukan sendiri di mana akan memfokuskan upaya-upaya mereka dan bagaimana akan bekerjasama dengan para mitra untuk menjamin agar aspek-aspek penting lain dari ketahanan tidak terlupakan. Penting diperhatikan bahwa tabel-tabel yang dimuat dalam catatan panduan ini dimaksudkan sebagai sebuah sumber bagi berbagai macam organisasi yang bekerja di tingkat lokal dan tingkat masyarakat, bersama dengan organisasi-organisasi lain ataupun sendiri-sendiri: unsur-unsur ketahanan tertentu mungkin lebih relevan bagi beberapa organisasi dan konteks tertentu daripada bagi organisasi dan konteks lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8151, 'Konsep Pengurangan Risiko Bencana melihat bencana sebagai sebuah permasalahan kompleks yang menuntut adanya penanganan kolektif yang melibatkan berbagai disiplin dan kelompok kelembagaan yang berbeda. Ini merupakan hal penting untuk dipertimbangkan dalam melihat karakteristik-karakteristik masyarakat yang tahan bencana, karena lembaga-lembaga harus menentukan sendiri di mana akan memfokuskan upaya-upaya mereka dan bagaimana akan bekerjasama dengan para mitra untuk menjamin agar aspek-aspek penting lain dari ketahanan tidak terlupakan. Penting diperhatikan bahwa tabel-tabel yang dimuat dalam catatan panduan ini dimaksudkan sebagai sebuah sumber bagi berbagai macam organisasi yang bekerja di tingkat lokal dan tingkat masyarakat, bersama dengan organisasi-organisasi lain ataupun sendiri-sendiri: unsur-unsur ketahanan tertentu mungkin lebih relevan bagi beberapa organisasi dan konteks tertentu daripada bagi organisasi dan konteks lainnya.', 'BAB X (lanjutan 1)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8152, 'perka-4-2008', 53, 'menetapkan', 'BAB X (lanjutan 2)', NULL, 29, 'Tindakan-tindakan Pengurangan Risiko Bencana selanjutnya diwadahi dalam dokumen Rencana Aksi Daerah ( RAD ) yang berlaku untuk periode tiga tahunan, yaitu dokumen daerah yang disusun melalui proses koordinasi dan partisipasi stake holder yang memuat landasan, prioritas, rencana aksi serta mekanisme pelaksanaan dan kelembagaannya bagi terlaksananya pengurangan Risiko bencana di daerah. Rencana Aksi Daerah Pengurangan Risiko Bencana yang selanjutnya disebut RAD PRB secara substansi merupakan kumpulan program kegiatan yang komprehensif dan sinergis dari seluruh pemangku kepentingan dan tanggungjawab semua pihak yang terkait. RAD PRB berisi prioritas dan strategi pemerintah daerah untuk mengurangi risiko bencana dalam Pedoman Penyusunan Rencana Penanggulangan Bencana 27 rangka membangun kesiapsiagaan dan ketangguhan masyarakat dalam menghadapi ancaman bencana.
Dalam menentukan kegiatan-kegiatan pengurangan risiko (Rencana Aksi Daerah) ini memang harus didahului dengan penyusunan Rencana Penanggulangan Bencana, karena aktivitas pengurangan risiko adalah tindakan yang lebih rinci dari rencana penanggulangan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8152, 'Tindakan-tindakan Pengurangan Risiko Bencana selanjutnya diwadahi dalam dokumen Rencana Aksi Daerah ( RAD ) yang berlaku untuk periode tiga tahunan, yaitu dokumen daerah yang disusun melalui proses koordinasi dan partisipasi stake holder yang memuat landasan, prioritas, rencana aksi serta mekanisme pelaksanaan dan kelembagaannya bagi terlaksananya pengurangan Risiko bencana di daerah. Rencana Aksi Daerah Pengurangan Risiko Bencana yang selanjutnya disebut RAD PRB secara substansi merupakan kumpulan program kegiatan yang komprehensif dan sinergis dari seluruh pemangku kepentingan dan tanggungjawab semua pihak yang terkait. RAD PRB berisi prioritas dan strategi pemerintah daerah untuk mengurangi risiko bencana dalam Pedoman Penyusunan Rencana Penanggulangan Bencana 27 rangka membangun kesiapsiagaan dan ketangguhan masyarakat dalam menghadapi ancaman bencana.
Dalam menentukan kegiatan-kegiatan pengurangan risiko (Rencana Aksi Daerah) ini memang harus didahului dengan penyusunan Rencana Penanggulangan Bencana, karena aktivitas pengurangan risiko adalah tindakan yang lebih rinci dari rencana penanggulangan bencana.', 'BAB X (lanjutan 2)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8153, 'perka-4-2008', 54, 'menetapkan', 'BAB X (lanjutan 3)', NULL, 30, 'Perbedaan antara Rencana Penanggulangan Bencana dengan Rencana Aksi Daerah, terutama pada kedalaman. Jika rencana penanggulangan bencana itu merupakan rencana yang menyeluruh dari pra bencana sampai pasca bencana, akan tetapi terbatas pada apa kegiatan yang akan dilaksanakan dan siapa pelakunya serta sumber dana yang akan dipakai, maka rencana aksi ini hanya terbatas pada pra bencana (pencegahan, mitigasi dan kesiapsiagaan), akan tetapi lebih rinci, yaitu sampai pada kapan dilaksanakan, di mana dilaksanakan, berapa dana yang dibutuhkan dll.
Contoh Tabel Matrik Rencana Aksi Pengurangan Risiko Bencana Besarnya Waktu No Kagiatan Pelaku Lokasi Sumber dana Anggaran Pelaksanaan 1 Pambuatan Dinas DIPA Tanggul PU 2 Penyuluhan BNPB, Pemerintah:
Pengurangan Depkes, DIPA Risiko LSM LSM:Mandiri dan seterusnya 28 Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8153, 'Perbedaan antara Rencana Penanggulangan Bencana dengan Rencana Aksi Daerah, terutama pada kedalaman. Jika rencana penanggulangan bencana itu merupakan rencana yang menyeluruh dari pra bencana sampai pasca bencana, akan tetapi terbatas pada apa kegiatan yang akan dilaksanakan dan siapa pelakunya serta sumber dana yang akan dipakai, maka rencana aksi ini hanya terbatas pada pra bencana (pencegahan, mitigasi dan kesiapsiagaan), akan tetapi lebih rinci, yaitu sampai pada kapan dilaksanakan, di mana dilaksanakan, berapa dana yang dibutuhkan dll.
Contoh Tabel Matrik Rencana Aksi Pengurangan Risiko Bencana Besarnya Waktu No Kagiatan Pelaku Lokasi Sumber dana Anggaran Pelaksanaan 1 Pambuatan Dinas DIPA Tanggul PU 2 Penyuluhan BNPB, Pemerintah:
Pengurangan Depkes, DIPA Risiko LSM LSM:Mandiri dan seterusnya 28 Pedoman Penyusunan Rencana Penanggulangan Bencana', 'BAB X (lanjutan 3)', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2008 tentang Pedoman Penyusunan Rencana Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8154, 'perka-4-2008', 55, 'menetapkan', 'BAB XI', NULL, 31, 'PENUTUP Pedoman Penyusunan Rencana Penanggulangan Bencana ini dimaksudkan untuk menjadi acuan bagi semua pihak dalam melaksanakan upaya penanggulangan bencana di daerah, sejak pra bencana, saat bencana dan setelah bencana.
Sangat disadari bahwa kondisi masing-masing wilayah tentu berbeda, sehingga perlu penyesuaian beberapa aspek agar dapat diterapkan pada wilayah masing-masing.
