INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8155, 'perka-4-2008', 56, 'menetapkan', 'BAB XI (lanjutan 1)', NULL, 32, '- Cross-section/penampang Sungai, Jaringan Saluran Irigasi dan Jaringan Drainase/Saluran Pembuangan
