INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8158, 'perka-4-2009', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka pelaksanaan ketentuan Pasal 18 ayat (3) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, perlu dibuat manajemen bantuan logistik;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Bantuan Logistik;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8158, 'a. bahwa dalam rangka pelaksanaan ketentuan Pasal 18 ayat (3) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, perlu dibuat manajemen bantuan logistik;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Bantuan Logistik;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8159, 'perka-4-2009', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik 2014, No.1413 2 Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nornor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Republik Indonesia Nomor 4830);
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Keputusan Presiden Nomor 29/M Tahun 2008 tanggal 23 April 2008 tentang Pengangkatan Kepala Badan Nasional PenanggulanganBencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8159, '1. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik 2014, No.1413 2 Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nornor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Republik Indonesia Nomor 4830);
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Keputusan Presiden Nomor 29/M Tahun 2008 tanggal 23 April 2008 tentang Pengangkatan Kepala Badan Nasional PenanggulanganBencana;', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8160, 'perka-4-2009', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN BANTUAN LOGISTIK.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8160, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN BANTUAN LOGISTIK.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8161, 'perka-4-2009', 4, 'pasal', 'Pasal 1', NULL, 2, 'Pedoman bantuan Logistik merupakan panduan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/Lembaga dan penyelenggara penanggulangan bencana agar pemberian bantuan logistik kepada korban bencana dapat dilaksanakan dengan cepat, tepat, terpadu, efektif, efisien dan akuntabel.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8161, 'Pedoman bantuan Logistik merupakan panduan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/Lembaga dan penyelenggara penanggulangan bencana agar pemberian bantuan logistik kepada korban bencana dapat dilaksanakan dengan cepat, tepat, terpadu, efektif, efisien dan akuntabel.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8162, 'perka-4-2009', 5, 'pasal', 'Pasal 2', NULL, 2, 'Pedoman sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian yang tidak terpisahkan dari peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8162, 'Pedoman sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian yang tidak terpisahkan dari peraturan ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8163, 'perka-4-2009', 6, 'pasal', 'Pasal 3', NULL, 2, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.
3 2014, No.1413 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8163, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.
3 2014, No.1413 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8164, 'perka-4-2009', 7, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 25 September 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1413 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8164, 'Ditetapkan di Jakarta pada tanggal 25 September 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1413 4', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8165, 'perka-4-2009', 8, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 4 TAHUN 2009 TENTANG PEDOMAN BANTUAN LOGISTIK BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan negara yang berada di wilayah rawan bencana. Kerawanan bencana ini ditandai dengan banyaknya bencana yang terjadi seperti: gempa bumi, tsunami, letusan gunung apl, banjir, tanah longsor, angin puting beliung, kekeringan, kebakaran hutan dan lahan, kegagalan teknologi, konflik sosial, pandemi yang mengakibatkan korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
Pemerintah dan pemerintah daerah berkewajiban memberikan bantuan untuk meringankan penderitaan korban bencana. Bantuan dapat dihimpun dan dikerahkan dari Pemerintah dan pemerintah daerah yang berasal dari APBN/APBD, bantuan Dunia Usaha serta Masyarakat dalam dan luar negeri, berupa logistik untuk penanggulangan bencana.
Bantuan Logistik dibutuhkan untuk penanggulangan bencana khususnya pada saat terjadi bencana. Dukungan bantuan logistik harus tepat waktu, lokasl, sasaran, kualitas, kuantitas, dan kebutuhan. Untuk mencapai pendistribusian bantuan logistik yang efektif, efisien, cepat dan akuntabel perlu dibuat Pedoman Bantuan Logistik untuk penanggulangan bencana.
B. Maksud dan Tujuan
1. Maksud pedoman ini adalah sebagai panduan bagi seluruh petugas penanggulangan bencana terutama yang berkaitan dengan pengelolaan bantuan logistik.
5 2014, No.1413
2. Tujuan dari pedoman ini adalah agar proses:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8165, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 4 TAHUN 2009 TENTANG PEDOMAN BANTUAN LOGISTIK BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan negara yang berada di wilayah rawan bencana. Kerawanan bencana ini ditandai dengan banyaknya bencana yang terjadi seperti: gempa bumi, tsunami, letusan gunung apl, banjir, tanah longsor, angin puting beliung, kekeringan, kebakaran hutan dan lahan, kegagalan teknologi, konflik sosial, pandemi yang mengakibatkan korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
Pemerintah dan pemerintah daerah berkewajiban memberikan bantuan untuk meringankan penderitaan korban bencana. Bantuan dapat dihimpun dan dikerahkan dari Pemerintah dan pemerintah daerah yang berasal dari APBN/APBD, bantuan Dunia Usaha serta Masyarakat dalam dan luar negeri, berupa logistik untuk penanggulangan bencana.
Bantuan Logistik dibutuhkan untuk penanggulangan bencana khususnya pada saat terjadi bencana. Dukungan bantuan logistik harus tepat waktu, lokasl, sasaran, kualitas, kuantitas, dan kebutuhan. Untuk mencapai pendistribusian bantuan logistik yang efektif, efisien, cepat dan akuntabel perlu dibuat Pedoman Bantuan Logistik untuk penanggulangan bencana.
B. Maksud dan Tujuan
1. Maksud pedoman ini adalah sebagai panduan bagi seluruh petugas penanggulangan bencana terutama yang berkaitan dengan pengelolaan bantuan logistik.
5 2014, No.1413
2. Tujuan dari pedoman ini adalah agar proses:', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8166, 'perka-4-2009', 9, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'a. Perencanaan bantuan logistik dalam penanggulangan bencana sesuai kebutuhan.
b. Pengadaan bantuan logistik dalam penanggulangan bencana mengacu pada peraturan yang berlaku sesuai dengan jumlah, jenis dan mutu bantuan.
c. Pendistribusian bantuan logistik dalam penanggulangan bencana efektif, efisien, tepat sasaran dan akuntabel.
C. Landasan Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 38 Tahun 2007, Tentang Pembagian Urusan Pemerintahan Antara Pemerintah, Pemerintahan Daerah Provinsi, dan Pemerintahan Daerah Kabupaten/Kota;
3. Peraturan Pemerintah Nomor 21 Tahun 2008, tentang Penyelenggaraan Penanggulangan Bencana;
4. Peraturan Pemerintah Nomor 22 Tahun 2008, tentang Pendanaan dan Pengelolaan Bantuan Bencana;
5. Peraturan Pemerintah Nomor 23 Tahun 2008, tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana;
6. Keputusan Presiden Nomor 80 Tahun 2003, tentang Pedoman Pelaksanaan Pengadaan Barang/Jasa Pemerintah;
7. Peraturan Presiden Nomor 8 Tahun 2008, tentang Badan Nasional Penanggulangan Bencana;
8. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008, tentang Pedoman Organisasi dan Tata Kerja BPBD;
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008, tentang Pedoman Pembentukan BPBD;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8166, 'a. Perencanaan bantuan logistik dalam penanggulangan bencana sesuai kebutuhan.
b. Pengadaan bantuan logistik dalam penanggulangan bencana mengacu pada peraturan yang berlaku sesuai dengan jumlah, jenis dan mutu bantuan.
c. Pendistribusian bantuan logistik dalam penanggulangan bencana efektif, efisien, tepat sasaran dan akuntabel.
C. Landasan Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 38 Tahun 2007, Tentang Pembagian Urusan Pemerintahan Antara Pemerintah, Pemerintahan Daerah Provinsi, dan Pemerintahan Daerah Kabupaten/Kota;
3. Peraturan Pemerintah Nomor 21 Tahun 2008, tentang Penyelenggaraan Penanggulangan Bencana;
4. Peraturan Pemerintah Nomor 22 Tahun 2008, tentang Pendanaan dan Pengelolaan Bantuan Bencana;
5. Peraturan Pemerintah Nomor 23 Tahun 2008, tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana;
6. Keputusan Presiden Nomor 80 Tahun 2003, tentang Pedoman Pelaksanaan Pengadaan Barang/Jasa Pemerintah;
7. Peraturan Presiden Nomor 8 Tahun 2008, tentang Badan Nasional Penanggulangan Bencana;
8. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008, tentang Pedoman Organisasi dan Tata Kerja BPBD;
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 3 Tahun 2008, tentang Pedoman Pembentukan BPBD;', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8167, 'perka-4-2009', 10, 'lampiran', 'Lampiran hal. 5', NULL, 5, '10.Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008, tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana;
D. Pengertian
1. Bantuan adalah segala sesuatu yang diperoleh dari hasil bantuan dan atau sumbangan dari berbagai pihak yang diberikan kepada pihak yang membutuhkan.
2014, No.1413 6
2. Logistik adalah sesuatu yang berwujud dan dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri dari atas sandang, pangan dan papan atau turunannya. Termasuk dalam kategori logistik adalah barang habis pakai atau dikonsumsi, misalnya sembako (sembilan bahan pokok), obat-obatan, pakaian dan kelengkapannya, air, jas tidur dan sebagainya.
3. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
E. Ruang Lingkup dan Sistematika Pedoman bantuan logistik penanggulangan bencana ini meliputi beberapa aspek tentang penyelenggaraan, mekanisme, pengawasan dan pelaporan.
Pedoman ini disusun dengan sistematika sebagai berikut:
I. PENDAHULUAN
II. PENYELENGGARAAN BANTUAN LOGISTIK
III. MEKANISME PENYELENGGARAAN BANTUAN LOGISTIK
IV. PENGAWASAN DAN PELAPORAN
V. PENUTUP 7 2014, No.1413 BAB II PENYELENGGARAAN BANTUAN LOGISTIK A. Strategi dan Kebijakan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8167, '10.Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008, tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana;
D. Pengertian
1. Bantuan adalah segala sesuatu yang diperoleh dari hasil bantuan dan atau sumbangan dari berbagai pihak yang diberikan kepada pihak yang membutuhkan.
2014, No.1413 6
2. Logistik adalah sesuatu yang berwujud dan dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri dari atas sandang, pangan dan papan atau turunannya. Termasuk dalam kategori logistik adalah barang habis pakai atau dikonsumsi, misalnya sembako (sembilan bahan pokok), obat-obatan, pakaian dan kelengkapannya, air, jas tidur dan sebagainya.
3. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
E. Ruang Lingkup dan Sistematika Pedoman bantuan logistik penanggulangan bencana ini meliputi beberapa aspek tentang penyelenggaraan, mekanisme, pengawasan dan pelaporan.
Pedoman ini disusun dengan sistematika sebagai berikut:
I. PENDAHULUAN
II. PENYELENGGARAAN BANTUAN LOGISTIK
III. MEKANISME PENYELENGGARAAN BANTUAN LOGISTIK
IV. PENGAWASAN DAN PELAPORAN
V. PENUTUP 7 2014, No.1413 BAB II PENYELENGGARAAN BANTUAN LOGISTIK A. Strategi dan Kebijakan', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8168, 'perka-4-2009', 11, 'lampiran', 'Lampiran hal. 7', NULL, 7, '1. Strategi Strategi bantuan logistik merupakan perencanaan umum dalam rangka mengelola bantuan logistik penanggulangan bencana.
Strategi dalam bantuan logistik ini adalah adanya koordinasi dan dukungan logistik dalam rangka penyelenggaraan penanggulangan bencana.
2. Kebijakan Kebijakan bantuan logistik merupakan pelaksanaan prioritas pengelolaan bantuan logistik penanggulangan bencana yang meliputi:
a. Bantuan logistik penanggulangan bencana diberikan kepada daerah pada keadaan darurat bencana sesuai kebutuhan.
b. Bantuan logistik penanggulangan bencana diberikan kepada daerah rawan bencana sebagai bufer stok dalam rangka kesiapsiagaan.
c. Diberikan kepada pemerintah daerah/BPBD dan/atau instansi/lembaga yang terkait dalam penanggulangan bencana.
d. Bantuan logistik penanggulangan bencana harus menjamin jumlah, mutu, sasaran, efektif, efrsien dan akuntabel.
B. Pola Penyelenggaraan Bantuan logistik dilaksanakan dengan menganut pola penyelenggaraan yang melibatkan beberapa lembaga/Instansi dalam sistem kelembagaan dalam berbagai wilayah yang dilaksanakan secara terpadu:
1. Nasional
2. Provinsi
3. Kabupaten/Kota Masing-masing tingkat kelembagaan dalam menyelenggarakan bantuan logistik penanggulangan bencana menggunakan mekanisme bantuan logistik, yang pada masing-masing tingkatan memiliki ciri-ciri khusus sesuai dengan tingkat kewenangannya.
1. Nasional Pengerahan bantuan logistik di Pemerintah Pusat dilaksanakan dengan pola sebagai berikut:
2014, No.1413 8');
