INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8169, 'perka-4-2009', 12, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'a. Dalam hal bencana di Kabupaten/Kota dan Provinsi, BNPB mengerahkan sumber daya logistik dari Unit Pelaksana Teknis (UPT) regional, instansi/lembaga, dunia usaha dan masyarakat sesual kebutuhan ke lokasi bencana.
b. Apabila kebutuhan tersebut tidak tersedia/tidak mencukupi, maka BNPB dapat mengerahkan bantuan kepada BPBD Provinsi lain, atau sumber lain baik dari dalam dan luar negeri.
c. Apabila terdapat keterbatasan bantuan logistik yang dikerahkan oleh Kepala BPBD Provinsi, maka BNPB dapat membantu melalui pola pendampingan dana siap pakai khusus digunakan pada saat tanggap darurat dan sumber dana lain yang sudah dialokasikan.
2. Provinsi Pengerahan bantuan logistik di Provinsi dilaksanakan dengan pola sebagai berikut:
a. Dalam hal bencana di Provinsi, BPBD Provinsi yang terkena bencana mengerahkan sumber daya logistik dari Instansi/ Lembaga, Dunia Usaha dan Masyarakat sesuai kebutuhan ke lokasi bencana.
b. Apabila kebutuhan tersebut tidak tersedia/tidak mencukupi, maka pemerintah Provinsi yang bersangkutan dapat meminta bantuan logistik kepada Provinsi lain yang terdekat.
c. Apabila Provinsi yang diminta bantuan tidak memiliki ketersediaan sumber daya logistik/tidak mencukupi, maka pemerintah Provinsi yang terkena bencana dapat meminta bantuan kepada Pemerintah Pusat (BNPB).
d. Biaya yang timbul akibat pengerahan bantuan logistik ini ditanggung oleh pemerintah Provinsi yang bersangkutan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8169, 'a. Dalam hal bencana di Kabupaten/Kota dan Provinsi, BNPB mengerahkan sumber daya logistik dari Unit Pelaksana Teknis (UPT) regional, instansi/lembaga, dunia usaha dan masyarakat sesual kebutuhan ke lokasi bencana.
b. Apabila kebutuhan tersebut tidak tersedia/tidak mencukupi, maka BNPB dapat mengerahkan bantuan kepada BPBD Provinsi lain, atau sumber lain baik dari dalam dan luar negeri.
c. Apabila terdapat keterbatasan bantuan logistik yang dikerahkan oleh Kepala BPBD Provinsi, maka BNPB dapat membantu melalui pola pendampingan dana siap pakai khusus digunakan pada saat tanggap darurat dan sumber dana lain yang sudah dialokasikan.
2. Provinsi Pengerahan bantuan logistik di Provinsi dilaksanakan dengan pola sebagai berikut:
a. Dalam hal bencana di Provinsi, BPBD Provinsi yang terkena bencana mengerahkan sumber daya logistik dari Instansi/ Lembaga, Dunia Usaha dan Masyarakat sesuai kebutuhan ke lokasi bencana.
b. Apabila kebutuhan tersebut tidak tersedia/tidak mencukupi, maka pemerintah Provinsi yang bersangkutan dapat meminta bantuan logistik kepada Provinsi lain yang terdekat.
c. Apabila Provinsi yang diminta bantuan tidak memiliki ketersediaan sumber daya logistik/tidak mencukupi, maka pemerintah Provinsi yang terkena bencana dapat meminta bantuan kepada Pemerintah Pusat (BNPB).
d. Biaya yang timbul akibat pengerahan bantuan logistik ini ditanggung oleh pemerintah Provinsi yang bersangkutan.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8170, 'perka-4-2009', 13, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'e. Pelaksanaan pengerahan sumber daya logistik dari asal sampai dengan lokasi bencana dilaksanakan dibawah koordinasi/ kendali Kepala BPBD Provinsi yang bersangkutan.
3. Kabupaten/Kota Pengerahan bantuan logistik di tingkat Kabupaten/Kota dilaksanakan dengan pola sebagai berikut:
a. Dalam hal bencana di Kabupaten/Kota, BPBD Kabupaten/Kota yang terkena bencana, mengerahkan sumber daya logistik dari Instansi/Lembaga, Dunia Usaha dan Masyarakat sesuai kebutuhan ke lokasi bencana.
9 2014, No.1413
b. Apabila kebutuhan tersebut tidak tersedia/tidak mencukupi, maka pemerintah Kabupaten/Kota yang bersangkutan dapat meminta bantuan logistik kepada pemerintah Kabupaten/Kota terdekat baik dalam satu wilayah provinsi maupun provinsi lain.
c. Apabila pemerintah Kabupaten/Kota yang diminta bantuan peralatan tidak memiliki ketersediaan sumberdaya/tidak mencukupi, maka pemerintah Kabupaten/Kota yang terkena bencana dapat meminta bantuan logistik kepada pemerintah provinsi yang bersangkutan.
d. Biaya yang timbul akibat pengerahan bantuan peralatan ini ditanggung oleh pemerintah Kabupaten/Kota yang bersangkutan.
e. Pelaksanaan pengerahan bantuan logistik dari asal sampai dengan lokasi bencana dilaksanakan dibawah koordinasi/ kendali Kepala BPBD Kabupaten/Kota yang bersangkutan.
Lampiran I menggambarkan alur Permintaan bantuan logistik dan lampiran II menggambarkan alur Pendistribusian bantuan logistik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8170, 'e. Pelaksanaan pengerahan sumber daya logistik dari asal sampai dengan lokasi bencana dilaksanakan dibawah koordinasi/ kendali Kepala BPBD Provinsi yang bersangkutan.
