INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8179, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8180, 'perka-4-2010', 1, 'menimbang', 'Menimbang', NULL, 1, 'bahwa untuk melaksanakan ketentuan Pasal 2 Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Pelaporan Keuangan dan Kinerja Instansi Pemerintah, agar pengelolaan dan penatausahaan persediaan dapat dilaksanakan secara tertib dan konsisten, maka dipandang perlu menetapkan Peraturan Kepala Badan tentang Pedoman Akuntansi Persediaan di Lingkungan Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8180, 'bahwa untuk melaksanakan ketentuan Pasal 2 Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Pelaporan Keuangan dan Kinerja Instansi Pemerintah, agar pengelolaan dan penatausahaan persediaan dapat dilaksanakan secara tertib dan konsisten, maka dipandang perlu menetapkan Peraturan Kepala Badan tentang Pedoman Akuntansi Persediaan di Lingkungan Badan Nasional Penanggulangan Bencana.', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8181, 'perka-4-2010', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Dasar Republik Indonesia Tahun 1945;
