5. Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Pelaporan Keuangan dan Kinerja Instansi Pemerintah (Lembaran Negara Republik Indonesia Tahun 2006 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
7. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
8. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
9. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
10. Peraturan Menteri Keuangan Nomor; 171/PMK.05/2007 tentang Sistem Akuntansi dan Pelaporan Keuangan Pemerintah Pusat.', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8182, 'perka-4-2010', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN AKUNTANSI PERSEDIAAN DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA (BNPB);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8182, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN AKUNTANSI PERSEDIAAN DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA (BNPB);', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8183, 'perka-4-2010', 4, 'pasal', 'Pasal 1', NULL, 2, 'Pedoman Akuntansi Persediaan di Lingkungan BNPB merupakan acuan bagi Unit Kerja dalam melaksanakan pencatatan dan pelaporan persediaan agar memiliki persepsi yang sama sehingga tercipta keseragaman dalam penatausahaan persediaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8183, 'Pedoman Akuntansi Persediaan di Lingkungan BNPB merupakan acuan bagi Unit Kerja dalam melaksanakan pencatatan dan pelaporan persediaan agar memiliki persepsi yang sama sehingga tercipta keseragaman dalam penatausahaan persediaan.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8184, 'perka-4-2010', 5, 'pasal', 'Pasal 2', NULL, 2, 'Pedoman Akuntansi Persediaan sebagaimana dimaksud dalam Pasal 1, adalah seperti tercantum dalam Lampiran, yang merupakan bagian talc terpisahkan dari Peraturan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8184, 'Pedoman Akuntansi Persediaan sebagaimana dimaksud dalam Pasal 1, adalah seperti tercantum dalam Lampiran, yang merupakan bagian talc terpisahkan dari Peraturan', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8185, 'perka-4-2010', 6, 'pasal', 'Pasal 3', NULL, 3, 'Hal-hal yang belum diatur dan/atau belum cukup diatur dalam Peraturan ini, akan diatur kemudian oleh Sekretariat Utama selaku Unit Akuntansi Pengguna Anggaran Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8185, 'Hal-hal yang belum diatur dan/atau belum cukup diatur dalam Peraturan ini, akan diatur kemudian oleh Sekretariat Utama selaku Unit Akuntansi Pengguna Anggaran Badan Nasional Penanggulangan Bencana.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8186, 'perka-4-2010', 7, 'pasal', 'Pasal 4', NULL, 3, 'Peraturan ini mulai berlaku sejak tanggal ditetapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8186, 'Peraturan ini mulai berlaku sejak tanggal ditetapkan.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8187, 'perka-4-2010', 8, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta Pada tanggal 13 sionucwi aolo KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, 7ii DR, SYAMSUL MAARIF, M.Si.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8187, 'Ditetapkan di Jakarta Pada tanggal 13 sionucwi aolo KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, 7ii DR, SYAMSUL MAARIF, M.Si.', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8188, 'perka-4-2010', 9, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : TAHUN 2010 TANGGAL : i3 Januarir aolc) MB I PENDAHULUAN A. Latar Belakang UU No. 1 Tahun 2004 pasal 44 menyatakan Pengguna Barang dan/atau Kuasa Pengguna Barang wajib mengelola dan menatausahakan barang milik negara yang berada dalam penguasaannya dengan sebaik-baiknya.
Barang Milik Negara (BMN) merupakan bagian dari aset pemerintah yang berwujud. Barang Milik Negara dapat dikelompokkan menjadi aset lancar dan aset tetap. Aset lancar adalah aset yang diharapkan untuk segera direalisasikan, dipakai, atau dimiliki untuk dijual dalam waktu 12 (dua belas) bulan sejak tanggal pelaporan. BMN yang masuk dalam kategori aset lancar adalah persediaan.
Menurut PSAP Nomor 05 disebutkan bahwa persediaan mencakup barang atau perlengkapan yang dibeli dan disimpan untuk digunakan, misalnya barang habis pakai seperti alat tulis kantor, barang tak habis pakai seperti komponen peralatan dan pipa, dan barang bekas pakai seperti komponen bekas, Di lingkungan Badan Nasional Penanggulangan Bencana (BNBP) selama ini pengadaan barang yang di antaranya berupa barang persediaan dilaksanakan oleh masing-masing Unit Eselon I. bails untuk keperluan Pra Bencana, Saat Tanggap Darurat dan Pasca Bencana.
Mengingat hal tersebut diatas dan untuk tert b administrasi, maka peril] dibuat Pedoman tentang Akuntansi Persediaan di lingkungan Badan Nasional Penanggulangan Bencana (BNPB) agar terwujud keseragaman dalam pencatatan dan pelaporannya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8188, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : TAHUN 2010 TANGGAL : i3 Januarir aolc) MB I PENDAHULUAN A. Latar Belakang UU No. 1 Tahun 2004 pasal 44 menyatakan Pengguna Barang dan/atau Kuasa Pengguna Barang wajib mengelola dan menatausahakan barang milik negara yang berada dalam penguasaannya dengan sebaik-baiknya.
Barang Milik Negara (BMN) merupakan bagian dari aset pemerintah yang berwujud. Barang Milik Negara dapat dikelompokkan menjadi aset lancar dan aset tetap. Aset lancar adalah aset yang diharapkan untuk segera direalisasikan, dipakai, atau dimiliki untuk dijual dalam waktu 12 (dua belas) bulan sejak tanggal pelaporan. BMN yang masuk dalam kategori aset lancar adalah persediaan.
Menurut PSAP Nomor 05 disebutkan bahwa persediaan mencakup barang atau perlengkapan yang dibeli dan disimpan untuk digunakan, misalnya barang habis pakai seperti alat tulis kantor, barang tak habis pakai seperti komponen peralatan dan pipa, dan barang bekas pakai seperti komponen bekas, Di lingkungan Badan Nasional Penanggulangan Bencana (BNBP) selama ini pengadaan barang yang di antaranya berupa barang persediaan dilaksanakan oleh masing-masing Unit Eselon I. bails untuk keperluan Pra Bencana, Saat Tanggap Darurat dan Pasca Bencana.
Mengingat hal tersebut diatas dan untuk tert b administrasi, maka peril] dibuat Pedoman tentang Akuntansi Persediaan di lingkungan Badan Nasional Penanggulangan Bencana (BNPB) agar terwujud keseragaman dalam pencatatan dan pelaporannya.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8189, 'perka-4-2010', 10, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'B. Maksud dan Tujuan
1. Maksud Sebagai petunjuk operasional bagi Unit Kerja dalam melaksanakan pencatatan dan pelaporan persediaan agar Laporan Keuangan BNBP dapat diselesaikan secara tepat waktu, transparan dan akurat serta dapat dipertanggungjawabkan sesuai ketentuan yang berlaku (akuntabel).
2. Tujuan
a. Menyediakan informasi yang akurat dan tepat waktu tentang jenis, volume, dan nilai persediaan yang terdapat di lingkungan BNPB;
b. Mengamankan setiap transaksi persediaan melalui pencatatan, penyimpanan, pendistribusian, dan pelaporan transaksi persediaan yang tertib dan konsisten;
c. Mendukung penyelenggaraan SA1 yang menghasilkan informasi persediaan sebagai dasar pertanggungjawaban dan pengambilan keputusan Pimpinan BNPB.
C. Ruang Lingkup Pedoman Akuntansi Persediaan ini berlaku untuk seluruh unit kerja di lingkungan BNPB yang mengelola persediaan.
Pengertian 1, Anggaran Pendapatan dan Belanja Negara yang selanjutnya disebut APBN adalah rencana keuangan tahunan pemerintahan negara yang disetujui oleh Dewan Perwakilan Rakyat,
2. Persediaan adalah aset lancar dalam bentuk barang atau perlengkapan yang dimaksudkan untuk mendukimg kegiatan operasional pemerintah, dan barang-barang yang dimaksudkan untuk dijual dan/atau diserahkan dalam rangka pelayanan kepada masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8189, 'B. Maksud dan Tujuan
1. Maksud Sebagai petunjuk operasional bagi Unit Kerja dalam melaksanakan pencatatan dan pelaporan persediaan agar Laporan Keuangan BNBP dapat diselesaikan secara tepat waktu, transparan dan akurat serta dapat dipertanggungjawabkan sesuai ketentuan yang berlaku (akuntabel).
2. Tujuan
a. Menyediakan informasi yang akurat dan tepat waktu tentang jenis, volume, dan nilai persediaan yang terdapat di lingkungan BNPB;
b. Mengamankan setiap transaksi persediaan melalui pencatatan, penyimpanan, pendistribusian, dan pelaporan transaksi persediaan yang tertib dan konsisten;
c. Mendukung penyelenggaraan SA1 yang menghasilkan informasi persediaan sebagai dasar pertanggungjawaban dan pengambilan keputusan Pimpinan BNPB.
C. Ruang Lingkup Pedoman Akuntansi Persediaan ini berlaku untuk seluruh unit kerja di lingkungan BNPB yang mengelola persediaan.
Pengertian 1, Anggaran Pendapatan dan Belanja Negara yang selanjutnya disebut APBN adalah rencana keuangan tahunan pemerintahan negara yang disetujui oleh Dewan Perwakilan Rakyat,
2. Persediaan adalah aset lancar dalam bentuk barang atau perlengkapan yang dimaksudkan untuk mendukimg kegiatan operasional pemerintah, dan barang-barang yang dimaksudkan untuk dijual dan/atau diserahkan dalam rangka pelayanan kepada masyarakat.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8190, 'perka-4-2010', 11, 'lampiran', 'Lampiran hal. 6', NULL, 6, '3. Entitas Akuntansi adalah unit kerja pemerintah setingkat Kuasa Pengguna Anggaran/Kuasa Pengguna Barang, dan oleh karenanya wajib menyelenggarakan akuntansi dan menyusun laporan keuangan untuk digabungkan pada entitas pelaporan.
4. Entitas Pelaporan adalah unit kerja pemerintah yang terdiri dari satu atau lebih entitas akuntansi yang menurut ketentuan peraturan perundang-undangan wajib menyampaikan laporan pertanggungjawaban berupa laporan keuangan.
5. Sistem Akuntansi Instansi, yang selanjutnya disingkat SAI adalah serangkaian prosedur manual maupun yang terkomputerisasi mulai dari pengumpulan data, pencatatan, pengikhtisaran sampai dengan pelaporan posisi keuangan dan operasi keuangan pada Kementerian Negara/Lembaga.
6. Sistem Informasi Manajemen dan Akuntansi Barang Milik Negara, yang selanjutnya disingkat SIMAK-BMN, adalah subsistem dari SAI yang merupakan serangkaian prosedur yang saling berhubungan untuk mengolah dokumen sumber dalam rangka menghasilkan informasi untuk penyusunan neraca dan laporan BMN serta laporan manajerial lainnya sesuai ketentuan yang berlaku.
7. Satuan Kerja adalah kuasa pengguna anggaran/pengguna barang yang merupakan bagian dari suatu unit organisasi pada kementerian negara/lembaga yang melaksanakan satu atau beberapa kegiatan dari suatu program.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8190, '3. Entitas Akuntansi adalah unit kerja pemerintah setingkat Kuasa Pengguna Anggaran/Kuasa Pengguna Barang, dan oleh karenanya wajib menyelenggarakan akuntansi dan menyusun laporan keuangan untuk digabungkan pada entitas pelaporan.
4. Entitas Pelaporan adalah unit kerja pemerintah yang terdiri dari satu atau lebih entitas akuntansi yang menurut ketentuan peraturan perundang-undangan wajib menyampaikan laporan pertanggungjawaban berupa laporan keuangan.
5. Sistem Akuntansi Instansi, yang selanjutnya disingkat SAI adalah serangkaian prosedur manual maupun yang terkomputerisasi mulai dari pengumpulan data, pencatatan, pengikhtisaran sampai dengan pelaporan posisi keuangan dan operasi keuangan pada Kementerian Negara/Lembaga.
6. Sistem Informasi Manajemen dan Akuntansi Barang Milik Negara, yang selanjutnya disingkat SIMAK-BMN, adalah subsistem dari SAI yang merupakan serangkaian prosedur yang saling berhubungan untuk mengolah dokumen sumber dalam rangka menghasilkan informasi untuk penyusunan neraca dan laporan BMN serta laporan manajerial lainnya sesuai ketentuan yang berlaku.
7. Satuan Kerja adalah kuasa pengguna anggaran/pengguna barang yang merupakan bagian dari suatu unit organisasi pada kementerian negara/lembaga yang melaksanakan satu atau beberapa kegiatan dari suatu program.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8191, 'perka-4-2010', 12, 'lampiran', 'Lampiran hal. 6', NULL, 6, '8, Sistem Akuntansi Barang Milik Negara adalah subsistem dari SAI yang merupakan serangkaian prosedur yang saling berhubungan untuk mengolah dokumen sumber dalam rangka menghasilkan informasi untuk penyusunan neraca dan Laporan BMN serta laporan manajerial lainnya sesuai ketentuan yang berlaku.
9. Unit Akuntansi Instansi adalah unit organisasi kementerian negara/lembaga yang bersifat fungsional yang melaksanakan fungsi akuntansi dan pelaporan keuangan instansi yang terdiri dari Unit Akuntansi Keuangan dan Unit Akuntansi Baran?, 3
10. Unit Akuntansi Kuasa Pengguna Anggaran, yang selanjutnya disebut UAKPA, adalah unit akuntansi instansi yang melakukan kegiatan akuntansi dan pelaporan tingkat satuan kerja.
11. Unit Akuntansi Kuasa Pengguna Barang, yang selanjutnya disebut UAKPB, adalah satuan kerja/kuasa pengguna barang yang memiliki wewenang mengurus dan atau menggunakan BMN.
12. Unit Akuntansi Pembantu Pengguna Barang, yang selanjutnya disebut UAPPB-W, adalah unit akuntansi BMN pada tingkat wilayah atau unit kerja lain yang ditetapkan sebagai UAPPB-W dan melakukan kegiatan penggabungan Laporan BMN dari UAKPB, penanggungjawabnya adalah Kepala Kantor Wilayah atau Kepala unit kerja yang ditetapkan sebagai UAPPB-W,
13. Unit Kerja adalah Sekretariat Utama, Kedeputian, Inspektorat Utama serta Pusat-Pusat di lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Peraturan Pemerintah No. 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8191, '8, Sistem Akuntansi Barang Milik Negara adalah subsistem dari SAI yang merupakan serangkaian prosedur yang saling berhubungan untuk mengolah dokumen sumber dalam rangka menghasilkan informasi untuk penyusunan neraca dan Laporan BMN serta laporan manajerial lainnya sesuai ketentuan yang berlaku.
9. Unit Akuntansi Instansi adalah unit organisasi kementerian negara/lembaga yang bersifat fungsional yang melaksanakan fungsi akuntansi dan pelaporan keuangan instansi yang terdiri dari Unit Akuntansi Keuangan dan Unit Akuntansi Baran?, 3
10. Unit Akuntansi Kuasa Pengguna Anggaran, yang selanjutnya disebut UAKPA, adalah unit akuntansi instansi yang melakukan kegiatan akuntansi dan pelaporan tingkat satuan kerja.
11. Unit Akuntansi Kuasa Pengguna Barang, yang selanjutnya disebut UAKPB, adalah satuan kerja/kuasa pengguna barang yang memiliki wewenang mengurus dan atau menggunakan BMN.
12. Unit Akuntansi Pembantu Pengguna Barang, yang selanjutnya disebut UAPPB-W, adalah unit akuntansi BMN pada tingkat wilayah atau unit kerja lain yang ditetapkan sebagai UAPPB-W dan melakukan kegiatan penggabungan Laporan BMN dari UAKPB, penanggungjawabnya adalah Kepala Kantor Wilayah atau Kepala unit kerja yang ditetapkan sebagai UAPPB-W,
13. Unit Kerja adalah Sekretariat Utama, Kedeputian, Inspektorat Utama serta Pusat-Pusat di lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Peraturan Pemerintah No. 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8192, 'perka-4-2010', 13, 'lampiran', 'Lampiran hal. 7', NULL, 7, '14. Badan Nasional Penanggulangan Bencana yang selanjutnya disebut BNPB adalah Lembaga Pemerintah Non Departemen sebagaimana dimaksud dalam Undang-Undang No. 24 Tahun 2007 tentang Penanggulangan Bencana, 15, Unit Akuntansi Pembantu Pengguna Barang Eselon I, yang selanjutnya disebut UAPPBEI, adalah unit akuntansi BMN pada tingkat eselon I yang melakukan kegiatan - penggabungan Laporan BMN dari UAPPB-W, dan UAKPB yang langsung berada di bawahnya yang penanggungjawabnya adalah pejabat eselon I.
16, Unit Akuntansi Pengguna Barang, yang selanjutnya disebut UAPB, adalah unit akuntansi BMN pada tingkat Kementerian Negara/Lembaga yang melakukan segiatan penggabungan Laporan BMN dari UAPPB-El , yang penanggungjawabnya adalah Menteri/Pimpinan Lembaga.
E. Sistematika Sistematika Pedoman Akuntansi Persediaan meliputi BAB I PENDAHULUAN yang memuat tentang latar belakang, maksud dan tujuan, ruang Iingkup, pengertian, dan sistematika.
BAB II ADMINISTRASI PENGELOLAAN PERSEDIAAN yang meliputi Penatausahaan dan Pencatatan Persediaan, serta Formulir-Formulir yang Digunakan.
BAB III AKUNTANSI PENGELOLAAN PERSEDIAAN yang meliputi Kebijakan Akuntansi, Siklus Akuntansi Persediaan, dan Proses Akuntansi.
BAB IV PELAPORAN PERSEDIAAN yang memuat Penyajian dalam Neraca, dan Pengungkapan dalam CaLK.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8192, '14. Badan Nasional Penanggulangan Bencana yang selanjutnya disebut BNPB adalah Lembaga Pemerintah Non Departemen sebagaimana dimaksud dalam Undang-Undang No. 24 Tahun 2007 tentang Penanggulangan Bencana, 15, Unit Akuntansi Pembantu Pengguna Barang Eselon I, yang selanjutnya disebut UAPPBEI, adalah unit akuntansi BMN pada tingkat eselon I yang melakukan kegiatan - penggabungan Laporan BMN dari UAPPB-W, dan UAKPB yang langsung berada di bawahnya yang penanggungjawabnya adalah pejabat eselon I.
16, Unit Akuntansi Pengguna Barang, yang selanjutnya disebut UAPB, adalah unit akuntansi BMN pada tingkat Kementerian Negara/Lembaga yang melakukan segiatan penggabungan Laporan BMN dari UAPPB-El , yang penanggungjawabnya adalah Menteri/Pimpinan Lembaga.
E. Sistematika Sistematika Pedoman Akuntansi Persediaan meliputi BAB I PENDAHULUAN yang memuat tentang latar belakang, maksud dan tujuan, ruang Iingkup, pengertian, dan sistematika.
BAB II ADMINISTRASI PENGELOLAAN PERSEDIAAN yang meliputi Penatausahaan dan Pencatatan Persediaan, serta Formulir-Formulir yang Digunakan.
BAB III AKUNTANSI PENGELOLAAN PERSEDIAAN yang meliputi Kebijakan Akuntansi, Siklus Akuntansi Persediaan, dan Proses Akuntansi.
BAB IV PELAPORAN PERSEDIAAN yang memuat Penyajian dalam Neraca, dan Pengungkapan dalam CaLK.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8193, 'perka-4-2010', 14, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'BAB V PENUTUP BAB II ADMINISTRASI PENGELOLAAN PERSEDIAAN A. Penatausahaan dan Pencatatan Persediaan 1, Penatausahaan persediaan dilaksanakan oleh UAKPB di masing-masing Unit Eselon I sesuai dengan PMK No. 171/PMK.05/2007 tentang Sistem Akuntansi dan Pelaporan Keuangan Pemerintah Pusat serta mengacu kepada Keputusan Menteri Keuangan Republik Indonesia nomor 18/KMK.018/1999 tentang Kodefikasi Barang Milik Negara,
2. Persediaan dicatat dalam Buku Persediaan (dalam bentuk kartu) untuk setiap jenis barang. Berdasarkan saldo per jenis persediaan pada Buku Persediaan disusun Laporan Persediaan, Laporan Persediaan disusun menurut Subkelompok Barang dan dilaporkan setiap semester. Laporan Persediaan dibuat didasarkan pada saldo pada akhir periode pelaporan berdasarkan basil opname fisik.
Laporan Persediaan dari masing2 UAKPB (Unit Eselon I) dikirimkan ke UAPB di Sekretariat Utama, untuk selanjutnya dilakukan evaluasi dan kompilasi menjadi Laporan Persediaan Badan Nasional Penanggulangan Bencana.
3. UAKPB membuat mapping data persediaan berdasarkan Laporan Persediaan dan harga pembelian terakhir yang diperoleh dari UAKPA. Penyajian perkiraan persediaan dalam Neraca didasarkan pada basil proses mapping lclasifilcasi BMN sesuai Keputusan Menteri Keuangan nomor 18/KMK,018/1999 dengan perkiraan buku besar neraca, B. Formulir-Formulir yang Digunakan Dokumen yang digunakan dalam pelaksanaan pencatatan persediaan adalah isebagai berikut');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8193, 'BAB V PENUTUP BAB II ADMINISTRASI PENGELOLAAN PERSEDIAAN A. Penatausahaan dan Pencatatan Persediaan 1, Penatausahaan persediaan dilaksanakan oleh UAKPB di masing-masing Unit Eselon I sesuai dengan PMK No. 171/PMK.05/2007 tentang Sistem Akuntansi dan Pelaporan Keuangan Pemerintah Pusat serta mengacu kepada Keputusan Menteri Keuangan Republik Indonesia nomor 18/KMK.018/1999 tentang Kodefikasi Barang Milik Negara,
2. Persediaan dicatat dalam Buku Persediaan (dalam bentuk kartu) untuk setiap jenis barang. Berdasarkan saldo per jenis persediaan pada Buku Persediaan disusun Laporan Persediaan, Laporan Persediaan disusun menurut Subkelompok Barang dan dilaporkan setiap semester. Laporan Persediaan dibuat didasarkan pada saldo pada akhir periode pelaporan berdasarkan basil opname fisik.
Laporan Persediaan dari masing2 UAKPB (Unit Eselon I) dikirimkan ke UAPB di Sekretariat Utama, untuk selanjutnya dilakukan evaluasi dan kompilasi menjadi Laporan Persediaan Badan Nasional Penanggulangan Bencana.
3. UAKPB membuat mapping data persediaan berdasarkan Laporan Persediaan dan harga pembelian terakhir yang diperoleh dari UAKPA. Penyajian perkiraan persediaan dalam Neraca didasarkan pada basil proses mapping lclasifilcasi BMN sesuai Keputusan Menteri Keuangan nomor 18/KMK,018/1999 dengan perkiraan buku besar neraca, B. Formulir-Formulir yang Digunakan Dokumen yang digunakan dalam pelaksanaan pencatatan persediaan adalah isebagai berikut', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8194, 'perka-4-2010', 15, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'a. Surat Perintah Pencairan Dana (SP2D), Surat Perintah Membayar (SPM) dan dokumen pendukung lainnya (Faktur, Kuitansi, Kontrak/SPK, Berita Acara Serail Terima); --b. Buku Persediaan, 6 Dad pencatatan persediaan dimaksud nantinya menghasilkan: Laporan Persediaan; dan Laporan Masa Mapping seperti pada lampiran I.
