INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8197, 'perka-4-2010', 18, 'lampiran', 'Lampiran hal. 15', NULL, 15, '12. t_lraian Barang Diisi danger] a an barang
