INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8198, 'perka-4-2010', 19, 'lampiran', 'Lampiran hal. 16', NULL, 16, 'c. Laporan Persediaan harus memberikan informasi jumlah persediaan yang rusak atau usang. Persediaan yang telah usang adalah persediaan yang tidak dapat dimanfaatkan untuk kegiatan operasional bukan hanya karena usianya tapi juga karena sudah ketinggalan teknologi atau ketidaksesuaian spesifikasi.
Laporan Hasil Mapping
a. Laporan Hasil Mapping dibuat setiap akhir semester pada suatu periode akuntansi setelah membuat Laporan Persediaan,
b. Laporan Hasil Mapping memberikan informasi jumlah nilai serta kuantitas persediaan berdasarkan Laporan Persediaan yang disesuaikan menjadi nilai serta kuantitas persediaan berdasarkan Bagan Perkiraan Standar (PMK nomor 13/PMK,06/2005).
c. Laporan Persediaan dibuat oleh Petugas yang menangani persediaan dan diketahui oleh penanggung jawab UAKPB, 13 BAB III AKUNTANSI PENGELOLAAN PERSEDIAAN A. Kebijakan Akuntansi Kebijakan akuntansi mencakup pengertian, pengakuan, pengukuran, dan pengungkapan pos persediaan dalam Laporan Keuangan.
1. Pengertian Persediaan Secara umum Persediaan adalah merupakan aset yang berwujud yang meliputi: a, Barang atau perlengkapan (supplies) yang digunakan dalam rangka kegiatan operasional pemerintah;
b. Bahan atau perlengkapan (supplies) yang digunakan dalam proses produksi;
c. Barang dalam proses produksi yang dimaksudkan untuk dijual atau diserahkan kepada masyarakat ;
d. Barang yang disimpan untuk dijual atau diserahkan kepada masyarakat dalam rangka kegiatan pemerintahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8198, 'c. Laporan Persediaan harus memberikan informasi jumlah persediaan yang rusak atau usang. Persediaan yang telah usang adalah persediaan yang tidak dapat dimanfaatkan untuk kegiatan operasional bukan hanya karena usianya tapi juga karena sudah ketinggalan teknologi atau ketidaksesuaian spesifikasi.
Laporan Hasil Mapping
a. Laporan Hasil Mapping dibuat setiap akhir semester pada suatu periode akuntansi setelah membuat Laporan Persediaan,
b. Laporan Hasil Mapping memberikan informasi jumlah nilai serta kuantitas persediaan berdasarkan Laporan Persediaan yang disesuaikan menjadi nilai serta kuantitas persediaan berdasarkan Bagan Perkiraan Standar (PMK nomor 13/PMK,06/2005).
c. Laporan Persediaan dibuat oleh Petugas yang menangani persediaan dan diketahui oleh penanggung jawab UAKPB, 13 BAB III AKUNTANSI PENGELOLAAN PERSEDIAAN A. Kebijakan Akuntansi Kebijakan akuntansi mencakup pengertian, pengakuan, pengukuran, dan pengungkapan pos persediaan dalam Laporan Keuangan.
1. Pengertian Persediaan Secara umum Persediaan adalah merupakan aset yang berwujud yang meliputi: a, Barang atau perlengkapan (supplies) yang digunakan dalam rangka kegiatan operasional pemerintah;
b. Bahan atau perlengkapan (supplies) yang digunakan dalam proses produksi;
c. Barang dalam proses produksi yang dimaksudkan untuk dijual atau diserahkan kepada masyarakat ;
d. Barang yang disimpan untuk dijual atau diserahkan kepada masyarakat dalam rangka kegiatan pemerintahan.', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8199, 'perka-4-2010', 20, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'Persediaan juga mencakup barang atau perlengkapan yang dibeli dan disimpan untuk digunakan, misalnya barang habis pakai seperti alat tulis kantor, barang tak habis pakai seperti komponen peralatan dan pipa, dan barang bekas pakai seperti komponen bekas.
Persediaan dapat meliputi:
a. Barang konsumsi;
b. Amunisi;
c. Bahan untuk pemeliharaan;
d. Suku cadang;
e. Persediaan untuk tujuan strategis/berjaga-jaga ;
f. Pita cukai dan leges;
g. Bahan baku;
h. Barang dalam proses/setengah jadi;
i. Tanah/bangunan untuk dijual atau diserahkan kepada masyarakat.
j. Hewan clan tandinant-tintuk dijual atau diserahkan kepada-nra-syarakat 14 Persediaan untuk tujuan strategic seperti cadangan energi (misalnya minyak) atau untuk tujuan berjaga-jaga seperti cadangan pangan (misalnya beras), barang-barang dimaksud diakui sebagai persediaan. Hewan dan tanaman untuk dijual atau diserahkan kepada masyarakat antara lain berupa sapi, kuda, ikan, benih padi, dan bibit tanaman.
Persediaan dengan kondisi rusak atau usang tidak dilaporkan dalam neraca, tetapi diungkapkan dalam Catatan atas Laporan Keuangan.
2. Pengakuan Persediaan Persediaan diakui pada saat potensi manfaat ekonomi masa depan diperoleh pemerintah dan mempunyai nilai atau biaya yang dapat diukur dengan andal. Persediaan diakui pada saat diterima atau hak kepemilikannya dan/atau kepenguasaannya berpindah. Pada akhir periode akuntansi, persediaan dicatat berdasarkan basil inventarisasi fisik.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8199, 'Persediaan juga mencakup barang atau perlengkapan yang dibeli dan disimpan untuk digunakan, misalnya barang habis pakai seperti alat tulis kantor, barang tak habis pakai seperti komponen peralatan dan pipa, dan barang bekas pakai seperti komponen bekas.
Persediaan dapat meliputi:
a. Barang konsumsi;
b. Amunisi;
c. Bahan untuk pemeliharaan;
d. Suku cadang;
e. Persediaan untuk tujuan strategis/berjaga-jaga ;
f. Pita cukai dan leges;
g. Bahan baku;
h. Barang dalam proses/setengah jadi;
i. Tanah/bangunan untuk dijual atau diserahkan kepada masyarakat.
j. Hewan clan tandinant-tintuk dijual atau diserahkan kepada-nra-syarakat 14 Persediaan untuk tujuan strategic seperti cadangan energi (misalnya minyak) atau untuk tujuan berjaga-jaga seperti cadangan pangan (misalnya beras), barang-barang dimaksud diakui sebagai persediaan. Hewan dan tanaman untuk dijual atau diserahkan kepada masyarakat antara lain berupa sapi, kuda, ikan, benih padi, dan bibit tanaman.
Persediaan dengan kondisi rusak atau usang tidak dilaporkan dalam neraca, tetapi diungkapkan dalam Catatan atas Laporan Keuangan.
2. Pengakuan Persediaan Persediaan diakui pada saat potensi manfaat ekonomi masa depan diperoleh pemerintah dan mempunyai nilai atau biaya yang dapat diukur dengan andal. Persediaan diakui pada saat diterima atau hak kepemilikannya dan/atau kepenguasaannya berpindah. Pada akhir periode akuntansi, persediaan dicatat berdasarkan basil inventarisasi fisik.', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8200, 'perka-4-2010', 21, 'lampiran', 'Lampiran hal. 18', NULL, 18, 'Persediaan bahan baku dan perlengkapan yang dimiliki proyek swakelola dan dibebankan ice suatu perlciraan aset untuk kontruksi dalam pengerjaan, tidak dimasukkan sebagai persediaan.
3. Pengukuran Persediaan Persediaan disajikan sebesan
a. Biaya perolehan apabila diperoleh dengan pembelian.
Biaya perolehan persediaan meliputi harga pembelian, biaya pengangkutani biaya penanganan dan biaya_ lainnya yang secara langsung dapat dibebankan pada perolehan persediaan. Potongan harga, rabat, dan lainnya yang serupa mengurangi biaya perolehan.
Nilai pembelian yang digunakan adalah biaya perolehan persediaan yang terakhir diperoleh. Barang persediaan yang memiliki nilai nominal yang dimaksudkan untuk dijual, seperti pita cukai, dinilai dengan biaya perolehan terakhir.
b. Biaya standar apabila diperoleh dengan memproduksi sendiri, Biaya standar persediaan meliputi biaya langsung yang terkait dengan persediaan yang diproduksi dan biaya overhead tetap dan variabel yang dialokasikan secara sistematis yang terjadi dalam proses konversi bahan menjadi persediaan.
15
c. Nilai wajar, apabila diperoleh dengan cara lainnya seperti donasi/rampasan.
d. Harga/nilai wajar persediaan meliputi nilai tukar aset atau penyelesaian kewajiban antar pihak yang memahami dan berkeinginan melakukan transaksi wajar. Persediaan hewan dan tanaman yang dikembangbiakkan serta persediaan yang diperoleh dengan cara lainnya seperti donasi/rampasan dinilai dengan menggunakan nilai wajar.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8200, 'Persediaan bahan baku dan perlengkapan yang dimiliki proyek swakelola dan dibebankan ice suatu perlciraan aset untuk kontruksi dalam pengerjaan, tidak dimasukkan sebagai persediaan.
3. Pengukuran Persediaan Persediaan disajikan sebesan
a. Biaya perolehan apabila diperoleh dengan pembelian.
Biaya perolehan persediaan meliputi harga pembelian, biaya pengangkutani biaya penanganan dan biaya_ lainnya yang secara langsung dapat dibebankan pada perolehan persediaan. Potongan harga, rabat, dan lainnya yang serupa mengurangi biaya perolehan.
Nilai pembelian yang digunakan adalah biaya perolehan persediaan yang terakhir diperoleh. Barang persediaan yang memiliki nilai nominal yang dimaksudkan untuk dijual, seperti pita cukai, dinilai dengan biaya perolehan terakhir.
b. Biaya standar apabila diperoleh dengan memproduksi sendiri, Biaya standar persediaan meliputi biaya langsung yang terkait dengan persediaan yang diproduksi dan biaya overhead tetap dan variabel yang dialokasikan secara sistematis yang terjadi dalam proses konversi bahan menjadi persediaan.
15
c. Nilai wajar, apabila diperoleh dengan cara lainnya seperti donasi/rampasan.
d. Harga/nilai wajar persediaan meliputi nilai tukar aset atau penyelesaian kewajiban antar pihak yang memahami dan berkeinginan melakukan transaksi wajar. Persediaan hewan dan tanaman yang dikembangbiakkan serta persediaan yang diperoleh dengan cara lainnya seperti donasi/rampasan dinilai dengan menggunakan nilai wajar.', 'Lampiran hal. 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2010 tentang Pedoman Akuntansi Persediaan Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8201, 'perka-4-2010', 22, 'lampiran', 'Lampiran hal. 19', NULL, 19, '4. Pengungkapan Persediaan Persediaan disajikan di neraca sebesar nilai moneternya dan diungkapkan dalam Catatan atas Laporan Keuangan (CaLK), berupa: a, Kebijakan akuntansi yang digunakan dalam pengukuran persediaan ;
b. Penjelasan lebih lanjut persediaan seperti barang atau perlengkapan yang digunakan dalam pelayanan masyarakat, barang atau perlengkapan yang digunakan dalam proses produksi, barang yang disimpan untuk dijual atau diserahkan kepada masyarakat, dan barang yang masih dalam proses produksi yang dimaksudkan untuk dijual atau diserahkan kepada masyarakat;
c. Kondisi persediaan; cl. Hal-hal lain yang perlu diungkapkan berkaitan dengan persediaan, misalnya persediaan yang diperoleh melalui hibah atau rampasan.
Sedangkan untuk persediaan bahan baku dan perlengkapan yang dirniliki proyek swakelola dan dibebankan ke suatu perkiraan aset untuk kontruksi dalam pengerjaan, tidak dimasukkan sebagai persediaan, B. Siklus Akuntansi Persediaan (Flowchart) Akuntansi persediaan oleh UAKPB dapat dilakukan secara ''manual atau menggunakan aplikasi persediaan, maksudnya:
a. Apabila akuntansi persediaan sudah dilakukan dengan menggunakan aplikasi persediaan maka jurnal penyesuaian persediaan akan terbentuk secara otomatis dari sistem aplikasi persediaan. UAKPB me-ngirimkan file data jurnal penyesuaian kepada UAKPA.
16');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8201, '4. Pengungkapan Persediaan Persediaan disajikan di neraca sebesar nilai moneternya dan diungkapkan dalam Catatan atas Laporan Keuangan (CaLK), berupa: a, Kebijakan akuntansi yang digunakan dalam pengukuran persediaan ;
b. Penjelasan lebih lanjut persediaan seperti barang atau perlengkapan yang digunakan dalam pelayanan masyarakat, barang atau perlengkapan yang digunakan dalam proses produksi, barang yang disimpan untuk dijual atau diserahkan kepada masyarakat, dan barang yang masih dalam proses produksi yang dimaksudkan untuk dijual atau diserahkan kepada masyarakat;
c. Kondisi persediaan; cl. Hal-hal lain yang perlu diungkapkan berkaitan dengan persediaan, misalnya persediaan yang diperoleh melalui hibah atau rampasan.
Sedangkan untuk persediaan bahan baku dan perlengkapan yang dirniliki proyek swakelola dan dibebankan ke suatu perkiraan aset untuk kontruksi dalam pengerjaan, tidak dimasukkan sebagai persediaan, B. Siklus Akuntansi Persediaan (Flowchart) Akuntansi persediaan oleh UAKPB dapat dilakukan secara ''manual atau menggunakan aplikasi persediaan, maksudnya:
a. Apabila akuntansi persediaan sudah dilakukan dengan menggunakan aplikasi persediaan maka jurnal penyesuaian persediaan akan terbentuk secara otomatis dari sistem aplikasi persediaan. UAKPB me-ngirimkan file data jurnal penyesuaian kepada UAKPA.
