INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8209, 'perka-4-2010', 30, 'lampiran', 'Lampiran hal. 28', NULL, 28, 'Setiap semester UAKPB membuat Laporan Persediaan beserta data transaksi serta menyerahkan laporan beserta data transaksi tersebut kepada unit vertikal di atasnya untuk dikompilasi, UAKPB juga menyerahkan laporan beserta data transaksi tersebut kepada UAKPA, Untuk selanjutnya berdasarkan laporan tersebut, UAKPA membuat jurnal penambahan/pengurangan nilai persediaan. Berdasarkan jurnal tersebut, akun persediaan disajikan neraca.
Contoh penyajian akun persediaan dalam neraca ;
ASET LANCAR KEWAJIBAN LANCAR Kas di Bendaharawan Dengeluaran Uang Foluka dari I<DJr< <as di Bendaharawan Penerimaan Hutang kepada KUN Piu:ang Persediaan , .
Effkiii fig EA gi c Cadanaan Piutang Cadantian Persediaan 111•111,1•3•■■ •■■
• •tli.
MET ETA EKUITAS DIINVESTASIKAN el-aka n Mesin Ditrorensikpn dat;71) asod 25 B. Pengungkapan Persediaan dalam Catatan atas Laporan Keuangan.
Persediaan disajikan di neraca sebesar nilai moneternya dan diungkapkan dalam Catatan atas Laporan Keuangan (CaLK), berupa :
a. Kebijakan akuntansi yang digunakan dalam pengukuran persediaan;
b. Penjelasan lebih lanjut persediaan seperti barang atau perlengkapan yang digunakan dalam pelayanan masyarakat, barang atau perlengkapan yang digunakan dalam proses produksi, barang yang disimpan untuk dijual atau diserahkan kepada masyarakat, dan barang yang masih dalam proses produksi yang dimaksudkan untuk dijual atau diserahkan kepada masyarakat;
c. Kondisi persediaan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8209, 'Setiap semester UAKPB membuat Laporan Persediaan beserta data transaksi serta menyerahkan laporan beserta data transaksi tersebut kepada unit vertikal di atasnya untuk dikompilasi, UAKPB juga menyerahkan laporan beserta data transaksi tersebut kepada UAKPA, Untuk selanjutnya berdasarkan laporan tersebut, UAKPA membuat jurnal penambahan/pengurangan nilai persediaan. Berdasarkan jurnal tersebut, akun persediaan disajikan neraca.
Contoh penyajian akun persediaan dalam neraca ;
ASET LANCAR KEWAJIBAN LANCAR Kas di Bendaharawan Dengeluaran Uang Foluka dari I<DJr< <as di Bendaharawan Penerimaan Hutang kepada KUN Piu:ang Persediaan , .
Effkiii fig EA gi c Cadanaan Piutang Cadantian Persediaan 111•111,1•3•■■ •■■
• •tli.
MET ETA EKUITAS DIINVESTASIKAN el-aka n Mesin Ditrorensikpn dat;71) asod 25 B. Pengungkapan Persediaan dalam Catatan atas Laporan Keuangan.
