INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8220, 'perka-4-2012', 9, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 30 April 2012 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1424 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8220, 'Ditetapkan di Jakarta pada tanggal 30 April 2012 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 2014, No.1424 4', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8221, 'perka-4-2012', 10, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 4 TAHUN 2012 TENTANG PEDOMAN PENERAPAN SEKOLAH/ MADRASAH AMAN DARI BENCANA BAB I PENDAHULUAN 1.1. Latar belakang Dalam rangka membangun bangsa yang tangguh terhadap bencana dan mengambil pelajaran dalam menanggulangi bencana, Pemerintah dengan persetujuan DPR telah menerbitkan Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Undang-undang ini disusun dengan menggunakan paradigma bahwa penanggulangan bencana harus dilakukan secara terencana, terpadu dan terkoordinasi dengan melibatkan para pemangku kepentingan. Undang-undang ini telah memberi mandat pada pemerintah untuk memberikan perlindungan pada masyarakat dari ancaman bencana, sebagai wujud dari pengejawantahan Pembukaan Undang-Undang Dasar Tahun 1945.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8221, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 4 TAHUN 2012 TENTANG PEDOMAN PENERAPAN SEKOLAH/ MADRASAH AMAN DARI BENCANA BAB I PENDAHULUAN 1.1. Latar belakang Dalam rangka membangun bangsa yang tangguh terhadap bencana dan mengambil pelajaran dalam menanggulangi bencana, Pemerintah dengan persetujuan DPR telah menerbitkan Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana. Undang-undang ini disusun dengan menggunakan paradigma bahwa penanggulangan bencana harus dilakukan secara terencana, terpadu dan terkoordinasi dengan melibatkan para pemangku kepentingan. Undang-undang ini telah memberi mandat pada pemerintah untuk memberikan perlindungan pada masyarakat dari ancaman bencana, sebagai wujud dari pengejawantahan Pembukaan Undang-Undang Dasar Tahun 1945.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8222, 'perka-4-2012', 11, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'Pengurangan risiko bencana merupakan bagian penting dalam Undang-Undang Nomor 24 Tahun 2007, sebagai upaya proaktif dalam mengelola bencana. Pada bulan Desember Tahun 2003, Majelis Umum Perserikan Bangsa-Bangsa telah mengadopsi resolusi 57/254 untuk menempatkan Dekade Pendidikan bagi Pembangunan Berkelanjutan mulai Tahun 2005- 2014, dibawah koordinasi UNESCO. Pendidikan untuk pengurangan risiko bencana (alam) telah diidentifikasi sebagai masalah inti. Dalam Undang-Undang Nomor 20 Tahun 2003 tentang Sistem Pendidikan Nasional pasal 32 ayat 2, juga telah mengakomodasi kebutuhan pendidikan bencana dalam terminologi pendidikan layanan khusus, yakni pendidikan bagi peserta didik di daerah terpencil atau terbelakang, masyarakat adat yang terpencil, dan/atau mengalami bencana alam, bencana sosial, dan tidak mampu dari segi ekonomi.
Indonesia yang terbentuk dari pertemuan 3 (tiga) lempeng tektonik dunia merupakan wilayah yang rawan terhadap gempabumi. Sejarah bencana gempabumi di Indonesia mengindikasikan terdapat banyaknya sekolah/madrasah yang rusak maupun hancur. Peristiwa terakhir 5 2014, No.1424 gempabumi di Padang telah menghancurkan sekolah/madrasah dimana banyak anak didik yang menjadi korban dalam bencana tersebut.
Dalam Rencana Nasional Penanggulangan Bencana 2010-2014 telah direncanakan adanya implementasi kesiapsiagaan bencana di sekolah/ madrasah. Hal ini penting, mengingat banyak sekolah/madrasah yang berada di wilayah rawan bencana gempabumi dan tsunami.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8222, 'Pengurangan risiko bencana merupakan bagian penting dalam Undang-Undang Nomor 24 Tahun 2007, sebagai upaya proaktif dalam mengelola bencana. Pada bulan Desember Tahun 2003, Majelis Umum Perserikan Bangsa-Bangsa telah mengadopsi resolusi 57/254 untuk menempatkan Dekade Pendidikan bagi Pembangunan Berkelanjutan mulai Tahun 2005- 2014, dibawah koordinasi UNESCO. Pendidikan untuk pengurangan risiko bencana (alam) telah diidentifikasi sebagai masalah inti. Dalam Undang-Undang Nomor 20 Tahun 2003 tentang Sistem Pendidikan Nasional pasal 32 ayat 2, juga telah mengakomodasi kebutuhan pendidikan bencana dalam terminologi pendidikan layanan khusus, yakni pendidikan bagi peserta didik di daerah terpencil atau terbelakang, masyarakat adat yang terpencil, dan/atau mengalami bencana alam, bencana sosial, dan tidak mampu dari segi ekonomi.
Indonesia yang terbentuk dari pertemuan 3 (tiga) lempeng tektonik dunia merupakan wilayah yang rawan terhadap gempabumi. Sejarah bencana gempabumi di Indonesia mengindikasikan terdapat banyaknya sekolah/madrasah yang rusak maupun hancur. Peristiwa terakhir 5 2014, No.1424 gempabumi di Padang telah menghancurkan sekolah/madrasah dimana banyak anak didik yang menjadi korban dalam bencana tersebut.
Dalam Rencana Nasional Penanggulangan Bencana 2010-2014 telah direncanakan adanya implementasi kesiapsiagaan bencana di sekolah/ madrasah. Hal ini penting, mengingat banyak sekolah/madrasah yang berada di wilayah rawan bencana gempabumi dan tsunami.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8223, 'perka-4-2012', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'Sekolah/madrasah pada jam-jam pelajaran merupakan tempat berkumpulnya anak didik yang tentunya mempunyai kerentanan tinggi.
Apabila tidak dilakukan upaya pengurangan risiko bencana, maka sekolah/madrasah menjadi tempat yang berisiko tinggi. Secara kuantitatif yakni sebanyak 75% sekolah di Indonesia berada pada risiko sedang hingga tinggi dari bencana. Kemdikbud mendata sampai akhir tahun 2011 sebanyak 194.844 ruang kelas rusak berat di SD/SDLB dan SMP/SMPLB. Tahun 2011 telah terealisasi rehabilitasi sebanyak 21.500 ruang kelas, sisanya sebanyak 173.344 ruang kelas rusak berat akan direhabilitasi pada tahun anggaran 2012. Sementara data Kemenag menunjukkan dari 208.214 ruang kelas MI dan MTs, sebanyak 13.247 ruang kelas rusak berat dan 51.036 ruang kelas rusak ringan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8223, 'Sekolah/madrasah pada jam-jam pelajaran merupakan tempat berkumpulnya anak didik yang tentunya mempunyai kerentanan tinggi.
Apabila tidak dilakukan upaya pengurangan risiko bencana, maka sekolah/madrasah menjadi tempat yang berisiko tinggi. Secara kuantitatif yakni sebanyak 75% sekolah di Indonesia berada pada risiko sedang hingga tinggi dari bencana. Kemdikbud mendata sampai akhir tahun 2011 sebanyak 194.844 ruang kelas rusak berat di SD/SDLB dan SMP/SMPLB. Tahun 2011 telah terealisasi rehabilitasi sebanyak 21.500 ruang kelas, sisanya sebanyak 173.344 ruang kelas rusak berat akan direhabilitasi pada tahun anggaran 2012. Sementara data Kemenag menunjukkan dari 208.214 ruang kelas MI dan MTs, sebanyak 13.247 ruang kelas rusak berat dan 51.036 ruang kelas rusak ringan.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8224, 'perka-4-2012', 13, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'Untuk menghadapi peningkatan ancaman bencana terutama oleh gempabumi dalam kaitannya dengan perlindungan terhadap sarana prasarana pendidikan, Indonesia memerlukan suatu panduan penerapan sekolah/madrasah aman dari bencana. Panduan ini mengintegrasikan kebijakan yang telah dibuat Kementerian/Lembaga terkait sekolah/madrasah aman dari bencana. Kementerian Pekerjaan Umum telah menerbitkan Peta Hazard Gempabumi Indonesia 2010, SNI-03-1726-2002 dan Permen Pu mengenai standar gedung dan bangunan. Kementerian Pendidikan Nasional Republik Indonesia telah menerbitkan Surat Edaran Mendiknas Nomor : 70a/MPN/SE/2010 yang ditujukan kepada Gubernur, Walikota/Bupati di seluruh Indonesia yang berisi permohonan untuk memperhatikan penyelenggaraan penanggulangan bencana melalui pelaksanaan strategi pengarusutamaan pengurangan risiko bencana di sekolah baik secara struktural dan non-struktural. Badan Nasional Penanggulangan Bencana telah menerbitkan Panduan Teknis Rehabilitasi Sekolah Aman dengan Dana Alokasi Khusus Pendidikan Tahun 2011.
Sekolah/madrasah aman dari bencana adalah sekolah/madrasah yang menerapkan standar sarana dan prasarana serta budaya yang mampu melindungi warga sekolah dan lingkungan di sekitarnya dari bahaya bencana. Penerapan sekolah/madrasah aman dari bencana terutama didasarkan pada pertimbangan sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8224, 'Untuk menghadapi peningkatan ancaman bencana terutama oleh gempabumi dalam kaitannya dengan perlindungan terhadap sarana prasarana pendidikan, Indonesia memerlukan suatu panduan penerapan sekolah/madrasah aman dari bencana. Panduan ini mengintegrasikan kebijakan yang telah dibuat Kementerian/Lembaga terkait sekolah/madrasah aman dari bencana. Kementerian Pekerjaan Umum telah menerbitkan Peta Hazard Gempabumi Indonesia 2010, SNI-03-1726-2002 dan Permen Pu mengenai standar gedung dan bangunan. Kementerian Pendidikan Nasional Republik Indonesia telah menerbitkan Surat Edaran Mendiknas Nomor : 70a/MPN/SE/2010 yang ditujukan kepada Gubernur, Walikota/Bupati di seluruh Indonesia yang berisi permohonan untuk memperhatikan penyelenggaraan penanggulangan bencana melalui pelaksanaan strategi pengarusutamaan pengurangan risiko bencana di sekolah baik secara struktural dan non-struktural. Badan Nasional Penanggulangan Bencana telah menerbitkan Panduan Teknis Rehabilitasi Sekolah Aman dengan Dana Alokasi Khusus Pendidikan Tahun 2011.
Sekolah/madrasah aman dari bencana adalah sekolah/madrasah yang menerapkan standar sarana dan prasarana serta budaya yang mampu melindungi warga sekolah dan lingkungan di sekitarnya dari bahaya bencana. Penerapan sekolah/madrasah aman dari bencana terutama didasarkan pada pertimbangan sebagai berikut:', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8225, 'perka-4-2012', 14, 'lampiran', 'Lampiran hal. 5', NULL, 5, '(1) Mengurangi gangguan terhadap kegiatan pendidikan, sehingga memberikan jaminan kesehatan, keselamatan, kelayakan termasuk bagi 2014, No.1424 6 anak berkebutuhan khusus, kenyamanan dan keamanan di sekolah dan madrasah setiap saat;
(2) Tempat belajar yang lebih aman memungkinkan identifikasi dan dukungan terhadap bantuan kemanusiaan lainnya untuk anak dalam situasi darurat sampai pemulihan pasca bencana;
(3) Dapat dijadikan pusat kegiatan masyarakat dan merupakan sarana sosial yang sangat penting dalam memerangi kemiskinan, buta huruf dan gangguan kesehatan;
(4) Dapat menjadi pusat kegiatan masyarakat dalam mengkoordinasi tanggap dan pemulihan setelah terjadi bencana;
(5) Dapat menjadi rumah darurat untuk melindungi bukan saja populasi sekolah/madrasah tapi juga komunitas dimana sekolah itu berada.
1.2. Tujuan Tujuan penyusunan pedoman penerapan sekolah/madrasah aman dari bencana adalah:
(1) Mengidentifikasi lokasi sekolah/madrasah pada prioritas daerah rawan bencana gempabumi dan tsunami;
(2) Memberikan acuan dalam penerapan Sekolah/Madrasah Aman dari bencana baik secara struktural dan non-struktural;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8225, '(1) Mengurangi gangguan terhadap kegiatan pendidikan, sehingga memberikan jaminan kesehatan, keselamatan, kelayakan termasuk bagi 2014, No.1424 6 anak berkebutuhan khusus, kenyamanan dan keamanan di sekolah dan madrasah setiap saat;
(2) Tempat belajar yang lebih aman memungkinkan identifikasi dan dukungan terhadap bantuan kemanusiaan lainnya untuk anak dalam situasi darurat sampai pemulihan pasca bencana;
(3) Dapat dijadikan pusat kegiatan masyarakat dan merupakan sarana sosial yang sangat penting dalam memerangi kemiskinan, buta huruf dan gangguan kesehatan;
(4) Dapat menjadi pusat kegiatan masyarakat dalam mengkoordinasi tanggap dan pemulihan setelah terjadi bencana;
(5) Dapat menjadi rumah darurat untuk melindungi bukan saja populasi sekolah/madrasah tapi juga komunitas dimana sekolah itu berada.
1.2. Tujuan Tujuan penyusunan pedoman penerapan sekolah/madrasah aman dari bencana adalah:
(1) Mengidentifikasi lokasi sekolah/madrasah pada prioritas daerah rawan bencana gempabumi dan tsunami;
(2) Memberikan acuan dalam penerapan Sekolah/Madrasah Aman dari bencana baik secara struktural dan non-struktural;', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8226, 'perka-4-2012', 15, 'lampiran', 'Lampiran hal. 6', NULL, 6, '1.3. Ruang Lingkup Ruang lingkup Pedoman Penerapan Sekolah/Madrasah Aman Bencana difokuskan pada ancaman bencana gempa bumi dan tsunami, mengingat kedua ancaman ini memiliki dampak pada keselamatan jiwa manusia dan kerusakan terhadap sarana dan prasarana yang tinggi. Selanjutnya ruang lingkup pedoman penerapan sekolah/madrasah aman dari bencana diarahkan pada aspek mendasar, yaitu:
(1) Kerangka Kerja Struktural Terdiri dari:
- Lokasi aman
- Struktur bangunan aman
- Desain dan penataan kelas aman
- Dukungan sarana dan prasarana aman
(2) Kerangka Kerja Non Struktural
- Peningkatan pengetahuan, sikap dan tindakan
- Kebijakan sekolah/madrasah aman
- Perencanaan kesiapsiagaan
- Mobilitasi sumberdaya 7 2014, No.1424 1.4. Landasan Hukum
1. Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 amandemen pasal 28 dan Pasal 31, Pasal 34 ayat 2
2. Undang-undang Nomor 36 Tahun 1999 tentang Hak Azasi Manusia
3. Undang-Undang Nomor 23 Tahun 2002 tentang Perlindungan Anak
4. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana
5. Undang-undang Nomor 20 Tahun 2003 tentang Sistem Pendidikan Nasional (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 78, Tambahan Lembaran Negara Republik Indonesia Nomor 4301);
6. Undang-undang Nomor 11 Tahun 2005 tentang pengesahan Kovenan Internasional tentang Hak Ekonomi Sosial Budaya
7. Undang-undang Republik Indonesia Nomor 26 tahun 2007, tentang Penataan Ruang;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8226, '1.3. Ruang Lingkup Ruang lingkup Pedoman Penerapan Sekolah/Madrasah Aman Bencana difokuskan pada ancaman bencana gempa bumi dan tsunami, mengingat kedua ancaman ini memiliki dampak pada keselamatan jiwa manusia dan kerusakan terhadap sarana dan prasarana yang tinggi. Selanjutnya ruang lingkup pedoman penerapan sekolah/madrasah aman dari bencana diarahkan pada aspek mendasar, yaitu:
(1) Kerangka Kerja Struktural Terdiri dari:
- Lokasi aman
- Struktur bangunan aman
- Desain dan penataan kelas aman
- Dukungan sarana dan prasarana aman
(2) Kerangka Kerja Non Struktural
- Peningkatan pengetahuan, sikap dan tindakan
- Kebijakan sekolah/madrasah aman
- Perencanaan kesiapsiagaan
- Mobilitasi sumberdaya 7 2014, No.1424 1.4. Landasan Hukum
1. Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 amandemen pasal 28 dan Pasal 31, Pasal 34 ayat 2
2. Undang-undang Nomor 36 Tahun 1999 tentang Hak Azasi Manusia
3. Undang-Undang Nomor 23 Tahun 2002 tentang Perlindungan Anak
4. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana
5. Undang-undang Nomor 20 Tahun 2003 tentang Sistem Pendidikan Nasional (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 78, Tambahan Lembaran Negara Republik Indonesia Nomor 4301);
6. Undang-undang Nomor 11 Tahun 2005 tentang pengesahan Kovenan Internasional tentang Hak Ekonomi Sosial Budaya
7. Undang-undang Republik Indonesia Nomor 26 tahun 2007, tentang Penataan Ruang;', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8227, 'perka-4-2012', 16, 'lampiran', 'Lampiran hal. 7', NULL, 7, '8. Undang-Undang Republik Indonesia Nomor 28 tahun 2002, tentang Bangunan Gedung;
9. Undang-Undang Republik Indonesia Nomor 4 Tahun 1992, tentang Perumahan dan Permukiman; yang akan segera digantikan dengan peraturan perundangan terbaru yaitu Undang-Undang Republik Indonesia Nomor 1 Tahun 2011, tentang Perumahan dan Kawasan Permukiman;
10. Peraturan Pemerintah Republik Indonesia Nomor 36 Tahun 2005, tentang peraturan Pelaksanaan UU Nomor 28 tahun 2002 tentang Bangunan Gedung;
11. Peraturan Pemerintah Nomor 80 Tahun 1999, tentang Kawasan Siap Bangun dan Lingkungan Siap Bangun yang Berdiri Sendiri;
12. Peraturan Presiden Nomor 73 Tahun 2011, tentang Pembangunan Bangunan Gedung Negara;
13. Keputusan Presiden Nomor 63 Tahun 2003, tentang Badan Kebijaksanaan dan Pengendalian Pembangunan Perumahan dan Permukiman Nasional;
14. Keputusan Presiden Nomor 36 Tahun 1990, tentang Ratifikasi Konvensi Hak Anak;
15. Instruksi Presiden Nomor 3 Tahun 2010, tentang Program Pembangunan Berkeadilan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8227, '8. Undang-Undang Republik Indonesia Nomor 28 tahun 2002, tentang Bangunan Gedung;
9. Undang-Undang Republik Indonesia Nomor 4 Tahun 1992, tentang Perumahan dan Permukiman; yang akan segera digantikan dengan peraturan perundangan terbaru yaitu Undang-Undang Republik Indonesia Nomor 1 Tahun 2011, tentang Perumahan dan Kawasan Permukiman;
10. Peraturan Pemerintah Republik Indonesia Nomor 36 Tahun 2005, tentang peraturan Pelaksanaan UU Nomor 28 tahun 2002 tentang Bangunan Gedung;
11. Peraturan Pemerintah Nomor 80 Tahun 1999, tentang Kawasan Siap Bangun dan Lingkungan Siap Bangun yang Berdiri Sendiri;
12. Peraturan Presiden Nomor 73 Tahun 2011, tentang Pembangunan Bangunan Gedung Negara;
13. Keputusan Presiden Nomor 63 Tahun 2003, tentang Badan Kebijaksanaan dan Pengendalian Pembangunan Perumahan dan Permukiman Nasional;
14. Keputusan Presiden Nomor 36 Tahun 1990, tentang Ratifikasi Konvensi Hak Anak;
15. Instruksi Presiden Nomor 3 Tahun 2010, tentang Program Pembangunan Berkeadilan.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8228, 'perka-4-2012', 17, 'lampiran', 'Lampiran hal. 7', NULL, 7, '1.5. Proses Penyusunan Proses penyusunan Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana dirancang dengan melibatkan berbagai pemangku kepentingan, terutama dari Kementerian-Lembaga terkait dan lembaga-lembaga non-pemerintah kunci di tingkat nasional yang berkepentingan dengan sekolah/madrasah aman dari bencana. Keseluruhan proses penyusunan ini dikoordinasikan oleh Badan Nasional Penanggulangan Bencana, sementara pemangku kepentingan lainnya dilibatkan dalam berbagai proses konsultasi dan penyusunan dokumen Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana. Dalam rangka pemaduan Pedoman Penerapan 2014, No.1424 8 Sekolah/Madrasah Aman dari Bencana ke dalam implementasinya, BNPB didukung oleh Kementerian Pendidikan dan Kebudayaan, Kementerian Agama, dan Kementerian Pekerjaan Umum sebagai instansi yang bertanggung jawab atas penerapan sekolah dan madrasah aman dari bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8228, '1.5. Proses Penyusunan Proses penyusunan Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana dirancang dengan melibatkan berbagai pemangku kepentingan, terutama dari Kementerian-Lembaga terkait dan lembaga-lembaga non-pemerintah kunci di tingkat nasional yang berkepentingan dengan sekolah/madrasah aman dari bencana. Keseluruhan proses penyusunan ini dikoordinasikan oleh Badan Nasional Penanggulangan Bencana, sementara pemangku kepentingan lainnya dilibatkan dalam berbagai proses konsultasi dan penyusunan dokumen Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana. Dalam rangka pemaduan Pedoman Penerapan 2014, No.1424 8 Sekolah/Madrasah Aman dari Bencana ke dalam implementasinya, BNPB didukung oleh Kementerian Pendidikan dan Kebudayaan, Kementerian Agama, dan Kementerian Pekerjaan Umum sebagai instansi yang bertanggung jawab atas penerapan sekolah dan madrasah aman dari bencana.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8229, 'perka-4-2012', 18, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'Secara teknis penyusunan pedoman ini melibatkan kelompok teknis melalui serangkaian konsultasi dan koordinasi dengan para pemangku kepentingan dari Kementerian/Lembaga yang meliputi Badan Nasional Penanggulangan (BNPB), Kementerian Koordinator Bidang Kesejahteraan Rakyat (KemenKoKesra), Kementerian Pendidikan dan Kebudayaan (Kemdikbud), Kementerian Agama (Kemenag), Kementerian Kesehatan (KemKes), Kementerian Dalam Negeri (Kemdagri), Kementerian Pekerjaan Umum (KemPU), Kementerian Keuangan (KemKeu), Kementerian Pemberdayaan Perempuan dan Perlindungan Anak (KPP-PA), Kementerian Lingkungan Hidup (KLH), Badan Pengkajian dan Penerapan Teknologi (BPPT), dan Badan Perencanaan Pembangunan Nasional (BAPPENAS).
Pedoman ini juga mendapat masukan dari berbagai Masyarakat Madani yang bergerak dalam bidang Pendidikan Kebencanaan baik dalam dan luar negeri melalui berbagai Seminar, Diskusi Kelompok Terarah dan Forum Konsultasi lainnya. Penyusunan dokumen ini juga melibatkan peran serta masyarakat baik pribadi maupun lembaga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8229, 'Secara teknis penyusunan pedoman ini melibatkan kelompok teknis melalui serangkaian konsultasi dan koordinasi dengan para pemangku kepentingan dari Kementerian/Lembaga yang meliputi Badan Nasional Penanggulangan (BNPB), Kementerian Koordinator Bidang Kesejahteraan Rakyat (KemenKoKesra), Kementerian Pendidikan dan Kebudayaan (Kemdikbud), Kementerian Agama (Kemenag), Kementerian Kesehatan (KemKes), Kementerian Dalam Negeri (Kemdagri), Kementerian Pekerjaan Umum (KemPU), Kementerian Keuangan (KemKeu), Kementerian Pemberdayaan Perempuan dan Perlindungan Anak (KPP-PA), Kementerian Lingkungan Hidup (KLH), Badan Pengkajian dan Penerapan Teknologi (BPPT), dan Badan Perencanaan Pembangunan Nasional (BAPPENAS).
Pedoman ini juga mendapat masukan dari berbagai Masyarakat Madani yang bergerak dalam bidang Pendidikan Kebencanaan baik dalam dan luar negeri melalui berbagai Seminar, Diskusi Kelompok Terarah dan Forum Konsultasi lainnya. Penyusunan dokumen ini juga melibatkan peran serta masyarakat baik pribadi maupun lembaga.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8230, 'perka-4-2012', 19, 'lampiran', 'Lampiran hal. 8', NULL, 8, '1.6. Kaidah Pelaksanaan Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana merupakan bentuk komitmen Pemerintah Indonesia dalam mewujudkan Sekolah/Madrasah Aman dari Bencana sebagaimana diamanatkan Undang-Undang Nomor 24 Tahun 2007 sejalan dengan prakarsa United Nation International Strategy for Disaster Reduction (UNISDR) terkait Kampanye Sejuta Sekolah dan Rumah Sakit Aman tahun 2010, Hyogo Framework for Action (HFA) tahun 2005-2015, The Dakkar Framework of Education for All (EFA) tahun 2000-2015. Pedoman ini bagian tak terpisahkan dari berbagai kerangka peraturan yang terkait dengan usaha Pengurangan Risiko Bencana dalam memenuhi capaian Millenium Development Goals (MDGs) tahun 2000-2015.
Kaidah-kaidah pelaksanaan Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana adalah sebagai berikut:
(1) Kementerian Pekerjaan Umum (KemPU) menyusun kebijakan dan standar-standar bangunan sekolah/madrasah aman dari ancaman bencana khususnya gempabumi dan tsunami dan menyiapkan standar 9 2014, No.1424 lainya yang terkait dengan standar tata ruang dan tata wilayah yang aman dari bencana;
(2) Kementerian Pendidikan dan Kebudayaan (Kemdikbud) menyusun kebijakan dan mengalokasikan anggaran bagi perencanaan, penyelenggaraan, pemantauan dan evaluasi penerapan sekolah aman dari bencana;
(3) Kementerian Agama (Kemenag) menyusun kebijakan dan mengalokasikan anggaran perencanaan, penyelenggaraan, pemantauan dan evaluasi penerapan madrasah aman dari bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8230, '1.6. Kaidah Pelaksanaan Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana merupakan bentuk komitmen Pemerintah Indonesia dalam mewujudkan Sekolah/Madrasah Aman dari Bencana sebagaimana diamanatkan Undang-Undang Nomor 24 Tahun 2007 sejalan dengan prakarsa United Nation International Strategy for Disaster Reduction (UNISDR) terkait Kampanye Sejuta Sekolah dan Rumah Sakit Aman tahun 2010, Hyogo Framework for Action (HFA) tahun 2005-2015, The Dakkar Framework of Education for All (EFA) tahun 2000-2015. Pedoman ini bagian tak terpisahkan dari berbagai kerangka peraturan yang terkait dengan usaha Pengurangan Risiko Bencana dalam memenuhi capaian Millenium Development Goals (MDGs) tahun 2000-2015.
Kaidah-kaidah pelaksanaan Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana adalah sebagai berikut:
(1) Kementerian Pekerjaan Umum (KemPU) menyusun kebijakan dan standar-standar bangunan sekolah/madrasah aman dari ancaman bencana khususnya gempabumi dan tsunami dan menyiapkan standar 9 2014, No.1424 lainya yang terkait dengan standar tata ruang dan tata wilayah yang aman dari bencana;
(2) Kementerian Pendidikan dan Kebudayaan (Kemdikbud) menyusun kebijakan dan mengalokasikan anggaran bagi perencanaan, penyelenggaraan, pemantauan dan evaluasi penerapan sekolah aman dari bencana;
(3) Kementerian Agama (Kemenag) menyusun kebijakan dan mengalokasikan anggaran perencanaan, penyelenggaraan, pemantauan dan evaluasi penerapan madrasah aman dari bencana;', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8231, 'perka-4-2012', 20, 'lampiran', 'Lampiran hal. 9', NULL, 9, '(4) Kementerian Keuangan (KemKeu) menyusun kebijakan perencanaan, pemantauan dan evaluasi alokasi anggaran dalam pelaksanaan Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana.
(5) Kementerian Dalam Negeri menyusun Kebijakan Pelaksanaan Pedoman sebagai acuan pelaksanaan, pemantauan dan evaluasi oleh Pemerintah Daerah.
(6) Badan Nasional Penanggulangan Bencana (BNPB) menyusun Pedoman penerapan sekolah/madrasah aman dari bencana, serta mengkoordinasi pemantauan, evaluasi dan pelaporan pelaksanaan penerapan sekolah/madrasah aman dari bencana di tingkat nasional melalui suatu tim yang dibentuk bersama dengan Kementerian Pendidikan dan Kebudayaan, Kementerian Agama, Kementerian Pekerjaan Umum, Kementerian Dalam Negeri dan Kementerian Keuangan, serta dibantu oleh profesional dan unsur masyarakat madani. Pembentukan tim ini sesuai Juknis yang disepakati antara Badan Nasional Penanggulangan Bencana, Kementerian Pendidikan dan Kebudayaan, Kementerian Agama, Kementerian Pekerjaan Umum, dan Kementerian Dalam Negeri.
(7) Pemerintah Daerah melaksanakan Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana sesuai dengan Kebijakan yang digaris Pemerintah Pusat c/q Kementerian Dalam Negeri.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8231, '(4) Kementerian Keuangan (KemKeu) menyusun kebijakan perencanaan, pemantauan dan evaluasi alokasi anggaran dalam pelaksanaan Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana.
(5) Kementerian Dalam Negeri menyusun Kebijakan Pelaksanaan Pedoman sebagai acuan pelaksanaan, pemantauan dan evaluasi oleh Pemerintah Daerah.
(6) Badan Nasional Penanggulangan Bencana (BNPB) menyusun Pedoman penerapan sekolah/madrasah aman dari bencana, serta mengkoordinasi pemantauan, evaluasi dan pelaporan pelaksanaan penerapan sekolah/madrasah aman dari bencana di tingkat nasional melalui suatu tim yang dibentuk bersama dengan Kementerian Pendidikan dan Kebudayaan, Kementerian Agama, Kementerian Pekerjaan Umum, Kementerian Dalam Negeri dan Kementerian Keuangan, serta dibantu oleh profesional dan unsur masyarakat madani. Pembentukan tim ini sesuai Juknis yang disepakati antara Badan Nasional Penanggulangan Bencana, Kementerian Pendidikan dan Kebudayaan, Kementerian Agama, Kementerian Pekerjaan Umum, dan Kementerian Dalam Negeri.
(7) Pemerintah Daerah melaksanakan Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana sesuai dengan Kebijakan yang digaris Pemerintah Pusat c/q Kementerian Dalam Negeri.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8232, 'perka-4-2012', 21, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'Untuk pelaksanaan monitoring dan evaluasi di daerah akan dilaksanakan oleh suatu tim yang dikoordinasikan oleh Badan Penanggulangan Bencana Daerah (BPBD) baik di Tingkat Provinsi dan Kabupaten/Kota dengan melibatkan Dinas/Instansi terkait dan masyarakat madani yang bergerak di bidang Pendidikan Kebencanaan sesuai juknis yang dibuat.
1.7. Pengertian
1. Pengurangan Risiko Bencana (PRB) adalah upaya untuk mengurangi risiko yang ditimbulkan akibat satu jenis bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, mengungsi, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
2. Sekolah aman adalah komunitas pembelajar yang berkomitmen akan budaya aman dan sehat, sadar akan risiko, memiliki rencana yang 2014, No.1424 10 matang dan mapan sebelum, saat, dan sesudah bencana, dan selalu siap untuk merespons pada saat darurat dan bencana.
3. Rehabilitasi adalah perbaikan dan pemulihan aspek pelayanan publik baik dari segi struktural maupun non-struktural di Sekolah/Madrasah agar penyelenggaraan pendidikan berjalan sesuai standar pelayanan minimum yang sudah ditetapkan.
4. Retrofitting atau perkuatan bangunan gedung adalah perbaikan struktur bangunan tanpa harus mengubah wajahnya, untuk mencegah meluasnya penurunan kualitas bahan serta mengembalikannya pada kondisi semula.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8232, 'Untuk pelaksanaan monitoring dan evaluasi di daerah akan dilaksanakan oleh suatu tim yang dikoordinasikan oleh Badan Penanggulangan Bencana Daerah (BPBD) baik di Tingkat Provinsi dan Kabupaten/Kota dengan melibatkan Dinas/Instansi terkait dan masyarakat madani yang bergerak di bidang Pendidikan Kebencanaan sesuai juknis yang dibuat.
1.7. Pengertian
1. Pengurangan Risiko Bencana (PRB) adalah upaya untuk mengurangi risiko yang ditimbulkan akibat satu jenis bencana pada suatu wilayah dan kurun waktu tertentu yang dapat berupa kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, mengungsi, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.
2. Sekolah aman adalah komunitas pembelajar yang berkomitmen akan budaya aman dan sehat, sadar akan risiko, memiliki rencana yang 2014, No.1424 10 matang dan mapan sebelum, saat, dan sesudah bencana, dan selalu siap untuk merespons pada saat darurat dan bencana.
3. Rehabilitasi adalah perbaikan dan pemulihan aspek pelayanan publik baik dari segi struktural maupun non-struktural di Sekolah/Madrasah agar penyelenggaraan pendidikan berjalan sesuai standar pelayanan minimum yang sudah ditetapkan.
4. Retrofitting atau perkuatan bangunan gedung adalah perbaikan struktur bangunan tanpa harus mengubah wajahnya, untuk mencegah meluasnya penurunan kualitas bahan serta mengembalikannya pada kondisi semula.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8233, 'perka-4-2012', 22, 'lampiran', 'Lampiran hal. 10', NULL, 10, '5. Pemeliharaan bangunan gedung adalah kegiatan menjaga keandalan bangunan gedung beserta prasarana dan sarananya agar bangunan gedung selalu laik fungsi.
Perawatan bangunan gedung adalah kegiatan memperbaiki dan/atau mengganti bagian bangunan gedung, komponen, bahan bangunan, dan/atau prasarana dan sarana agar bangunan gedung tetap laik fungsi 11 2014, No.1424 BAB II ANCAMAN GEMPABUMI DAN TSUNAMI 2.1. Ancaman Gempabumi Pengertian gempabumi adalah berguncangnya bumi yang disebabkan oleh tumbukan antar lempeng bumi, aktivitas gunungapi atau runtuhan batuan.
Kekuatan gempabumi akibat gunungapi dan runtuhan batuan relatif kecil sehingga gempabumi dalam perka ini lebih banyak membahas gempabumi akibat tumbukan lempeng dan patahan aktif.
Catatan sejarah dan rekaman alat menunjukan bahwa bencana gempabumi sudah sering terjadi di berbagai wilayah kepulauan Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8233, '5. Pemeliharaan bangunan gedung adalah kegiatan menjaga keandalan bangunan gedung beserta prasarana dan sarananya agar bangunan gedung selalu laik fungsi.
Perawatan bangunan gedung adalah kegiatan memperbaiki dan/atau mengganti bagian bangunan gedung, komponen, bahan bangunan, dan/atau prasarana dan sarana agar bangunan gedung tetap laik fungsi 11 2014, No.1424 BAB II ANCAMAN GEMPABUMI DAN TSUNAMI 2.1. Ancaman Gempabumi Pengertian gempabumi adalah berguncangnya bumi yang disebabkan oleh tumbukan antar lempeng bumi, aktivitas gunungapi atau runtuhan batuan.
Kekuatan gempabumi akibat gunungapi dan runtuhan batuan relatif kecil sehingga gempabumi dalam perka ini lebih banyak membahas gempabumi akibat tumbukan lempeng dan patahan aktif.
Catatan sejarah dan rekaman alat menunjukan bahwa bencana gempabumi sudah sering terjadi di berbagai wilayah kepulauan Indonesia.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8234, 'perka-4-2012', 23, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'Seringnya gempabumi disebabkan karena wilayah Kepulauan Indonesia terletak pada zona batas dari empat lempeng besar, yaitu: lempeng Eurasia, Lempeng India dan Australia, dan Lempeng Pacifik. Selain deformasi pada batas lempeng, pergerakan tektonik dari empat lempeng bumi ini menyebabkan pembentukan banyak patahan-patahan aktif baik di wilayah daratan maupun di dasar lautan. Batas lempeng dan patahan-patahan aktif ini menjadi sumber dari gempa-gempa tektonik yang dapat menimbulkan bencana bagi manusia. Gempabumi mempunyai potensi bencana dari deformasi tanah di sepanjang jalur patahannya, dan efek goncangan yang menyebar ke wilayah di sekelilingnya sampai radius beratus-ratus kilometer jauhnya tergantung dari besarnya kekuatan gempa.
Disamping itu, getaran gempa juga dapat memicu terjadinya bencana ikutan berupa longsor dan amblasan tanah. Apabila sumber gempabuminya di bawah laut maka pergerakannya dapat menyebabkan gelombang tsunami.
Dengan karakteristik tersebut dapat dipastikan gempabumi dapat menghancurkan bangunan termasuk sekolah/madrasah. Saat ini gempabumi belum dapat diprediksi, tetapi lokasinya sudah dapat diketahui berdasarkan sejarah kejadiannya. Upaya yang bisa dilakukan adalah mitigasi dan kesiapsiagaan, sehingga setiap sekolah/madrasah perlu melakukan kedua kegiatan tersebut terutama sekalah/madrasah yang berada dalam zonasi ancaman gempabumi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8234, 'Seringnya gempabumi disebabkan karena wilayah Kepulauan Indonesia terletak pada zona batas dari empat lempeng besar, yaitu: lempeng Eurasia, Lempeng India dan Australia, dan Lempeng Pacifik. Selain deformasi pada batas lempeng, pergerakan tektonik dari empat lempeng bumi ini menyebabkan pembentukan banyak patahan-patahan aktif baik di wilayah daratan maupun di dasar lautan. Batas lempeng dan patahan-patahan aktif ini menjadi sumber dari gempa-gempa tektonik yang dapat menimbulkan bencana bagi manusia. Gempabumi mempunyai potensi bencana dari deformasi tanah di sepanjang jalur patahannya, dan efek goncangan yang menyebar ke wilayah di sekelilingnya sampai radius beratus-ratus kilometer jauhnya tergantung dari besarnya kekuatan gempa.
Disamping itu, getaran gempa juga dapat memicu terjadinya bencana ikutan berupa longsor dan amblasan tanah. Apabila sumber gempabuminya di bawah laut maka pergerakannya dapat menyebabkan gelombang tsunami.
Dengan karakteristik tersebut dapat dipastikan gempabumi dapat menghancurkan bangunan termasuk sekolah/madrasah. Saat ini gempabumi belum dapat diprediksi, tetapi lokasinya sudah dapat diketahui berdasarkan sejarah kejadiannya. Upaya yang bisa dilakukan adalah mitigasi dan kesiapsiagaan, sehingga setiap sekolah/madrasah perlu melakukan kedua kegiatan tersebut terutama sekalah/madrasah yang berada dalam zonasi ancaman gempabumi.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8235, 'perka-4-2012', 24, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'Dalam mengantisipasi dampak yang ditimbulkan gempabumi, pemerintah Indonesia telah memiliki standar peraturan perencanaan ketahanan gempabumi untuk struktur bangunan gedung yaitu SNI-03-1726-2002.
Dengan demikian bangunan sekolah/madrasah yang ada di zonasi ancaman gempabumi harus mengacu pada SNI tersebut. Khusus sekolah/madrasah yang berada di kawasan pesisir yang rawan tsunami, 2014, No.1424 12 harus mempunyai lokasi evakuasi dengan ketinggian minimal 1 meter diatas hasil kajian tsunami.
2.2. Zonasi Ancaman Gempabumi Sebagai acuan perencanaan dan perancangan infrastruktur tahan gempabumi, Kementerian Pekerjaan Umum telah menerbitkan Peta Zonasi Ancaman Gempabumi di Indonesia. Dengan adanya peta ini dapat dijadikan acuan untuk menilai kembali struktur bangunan di Indonesia termasuk bangunan sekolah/madrasah. Ada 18 kelas yang berbeda-beda mengenai respon spektra percepatan 0.2 detik di batuan dasar SB untuk probabilitas terlampaui 2 % dalam 50 tahun (redaman 5 %). Dimana SB adalah lapisan batuan di bawah permukaan tanah yang memiliki kecepatan rambat gelombang geser (Vs) mencapai 750 m/detik dan tidak ada lapisan batuan lain dibawahnya yang memiliki nilai kecepatan rambat gelombang geser yang kurang dari itu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8235, 'Dalam mengantisipasi dampak yang ditimbulkan gempabumi, pemerintah Indonesia telah memiliki standar peraturan perencanaan ketahanan gempabumi untuk struktur bangunan gedung yaitu SNI-03-1726-2002.
Dengan demikian bangunan sekolah/madrasah yang ada di zonasi ancaman gempabumi harus mengacu pada SNI tersebut. Khusus sekolah/madrasah yang berada di kawasan pesisir yang rawan tsunami, 2014, No.1424 12 harus mempunyai lokasi evakuasi dengan ketinggian minimal 1 meter diatas hasil kajian tsunami.
2.2. Zonasi Ancaman Gempabumi Sebagai acuan perencanaan dan perancangan infrastruktur tahan gempabumi, Kementerian Pekerjaan Umum telah menerbitkan Peta Zonasi Ancaman Gempabumi di Indonesia. Dengan adanya peta ini dapat dijadikan acuan untuk menilai kembali struktur bangunan di Indonesia termasuk bangunan sekolah/madrasah. Ada 18 kelas yang berbeda-beda mengenai respon spektra percepatan 0.2 detik di batuan dasar SB untuk probabilitas terlampaui 2 % dalam 50 tahun (redaman 5 %). Dimana SB adalah lapisan batuan di bawah permukaan tanah yang memiliki kecepatan rambat gelombang geser (Vs) mencapai 750 m/detik dan tidak ada lapisan batuan lain dibawahnya yang memiliki nilai kecepatan rambat gelombang geser yang kurang dari itu.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8236, 'perka-4-2012', 25, 'lampiran', 'Lampiran hal. 12', NULL, 12, '2.3. Kajian Risiko Bencana Bencana akan terjadi dan menimbulkan dampak kerugian bila skala dari ancaman terlalu tinggi, kerentanan terlalu besar, dan kapasitas serta kesiapan yang dimiliki masyarakat atau pemerintah tidak cukup memadai untuk mengatasinya. Ancaman atau bahaya tidak akan menjadi bencana apabila kejadian tersebut tidak menimbulkan kerugian baik fisik maupun korban jiwa. Secara teknis, bencana terjadi karena adanya ancaman dan kerentanan yang bekerjasama secara sistematis serta dipicu oleh faktor-faktor luar sehingga menjadikan potensi ancaman yang tersembunyi muncul ke permukaan sebagai ancaman nyata.
Kajian risiko bencana menjadi landasan untuk memilih strategi yang dinilai mampu mengurangi risiko bencana. Kajian risiko bencana ini harus mampu menjadi dasar yang memadai bagi daerah untuk menyusun kebijakan 13 2014, No.1424 penanggulangan bencana. Ditingkat masyarakat hasil pengkajian diharapkan dapat dijadikan dasar yang kuat dalam perencanaan upaya pengurangan risiko bencana. Untuk mendapatkan nilai risiko bencana tergantung dari besarnya ancaman dan kerentanan yang berinteraksi.
Interaksi ancaman, kerentanan dan faktor-faktor luar menjadi dasar untuk melakukan pengkajian risiko bencana terhadap suatu daerah.
Kajian risiko bencana dilakukan dengan melakukan identifikasi, klasifikasi dan evaluasi risiko melalui beberapa langkah, yaitu:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8236, '2.3. Kajian Risiko Bencana Bencana akan terjadi dan menimbulkan dampak kerugian bila skala dari ancaman terlalu tinggi, kerentanan terlalu besar, dan kapasitas serta kesiapan yang dimiliki masyarakat atau pemerintah tidak cukup memadai untuk mengatasinya. Ancaman atau bahaya tidak akan menjadi bencana apabila kejadian tersebut tidak menimbulkan kerugian baik fisik maupun korban jiwa. Secara teknis, bencana terjadi karena adanya ancaman dan kerentanan yang bekerjasama secara sistematis serta dipicu oleh faktor-faktor luar sehingga menjadikan potensi ancaman yang tersembunyi muncul ke permukaan sebagai ancaman nyata.
Kajian risiko bencana menjadi landasan untuk memilih strategi yang dinilai mampu mengurangi risiko bencana. Kajian risiko bencana ini harus mampu menjadi dasar yang memadai bagi daerah untuk menyusun kebijakan 13 2014, No.1424 penanggulangan bencana. Ditingkat masyarakat hasil pengkajian diharapkan dapat dijadikan dasar yang kuat dalam perencanaan upaya pengurangan risiko bencana. Untuk mendapatkan nilai risiko bencana tergantung dari besarnya ancaman dan kerentanan yang berinteraksi.
Interaksi ancaman, kerentanan dan faktor-faktor luar menjadi dasar untuk melakukan pengkajian risiko bencana terhadap suatu daerah.
Kajian risiko bencana dilakukan dengan melakukan identifikasi, klasifikasi dan evaluasi risiko melalui beberapa langkah, yaitu:', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8237, 'perka-4-2012', 26, 'lampiran', 'Lampiran hal. 13', NULL, 13, '1. Pengkajian Ancaman Pengkajian ancaman dimaknai sebagai cara untuk memahami unsur-unsur ancaman yang berisiko bagi daerah dan masyarakat. Karakter-karakter ancaman pada suatu daerah dan masyarakatnya berbeda dengan daerah dan masyarakat lain. Pengkajian karakter ancaman dilakukan sesuai tingkatan yang diperlukan dengan mengidentifikasikan unsur-unsur berisiko oleh berbagai ancaman di lokasi tertentu.
Penentuan tingkat ancaman bencana menggunakan matriks tingkat ancaman, dengan memadukan indeks ancaman dengan indeks penduduk terpapar. Titik pertemuan antara indeks ancaman dengan indeks penduduk terkapar adalah tingkat ancaman. Skala indeks ancaman dibagi dalam 3 kategori yaitu: rendah, sedang, dan tinggi, dengan masing-masing nilai indeks sebagai berikut :
(1) Rendah : 0,0-0,3, apabila kepadatan jumlah penduduk terpapar kurang dari 500 jiwa / Km2 , dan jumlah penduduk kelompok rentan kurang dari 20%
(2) Sedang : >0,3-0,6, apabila kepadatan jumlah penduduk terpapar 500-1000 jiwa/Km2, dan jumlah penduduk kelompok rentan 20% – 40%
(3) Tinggi : >0,6-1,0, apabila kepadatan jumlah penduduk terpapar lebih dari 1000 jiwa/Km2, dan jumlah penduduk kelompok rentan lebih dari 40%.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8237, '1. Pengkajian Ancaman Pengkajian ancaman dimaknai sebagai cara untuk memahami unsur-unsur ancaman yang berisiko bagi daerah dan masyarakat. Karakter-karakter ancaman pada suatu daerah dan masyarakatnya berbeda dengan daerah dan masyarakat lain. Pengkajian karakter ancaman dilakukan sesuai tingkatan yang diperlukan dengan mengidentifikasikan unsur-unsur berisiko oleh berbagai ancaman di lokasi tertentu.
Penentuan tingkat ancaman bencana menggunakan matriks tingkat ancaman, dengan memadukan indeks ancaman dengan indeks penduduk terpapar. Titik pertemuan antara indeks ancaman dengan indeks penduduk terkapar adalah tingkat ancaman. Skala indeks ancaman dibagi dalam 3 kategori yaitu: rendah, sedang, dan tinggi, dengan masing-masing nilai indeks sebagai berikut :
(1) Rendah : 0,0-0,3, apabila kepadatan jumlah penduduk terpapar kurang dari 500 jiwa / Km2 , dan jumlah penduduk kelompok rentan kurang dari 20%
(2) Sedang : >0,3-0,6, apabila kepadatan jumlah penduduk terpapar 500-1000 jiwa/Km2, dan jumlah penduduk kelompok rentan 20% – 40%
(3) Tinggi : >0,6-1,0, apabila kepadatan jumlah penduduk terpapar lebih dari 1000 jiwa/Km2, dan jumlah penduduk kelompok rentan lebih dari 40%.', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8238, 'perka-4-2012', 27, 'lampiran', 'Lampiran hal. 13', NULL, 13, '2. Pengkajian Kerentanan Pengkajian kerentanan dapat dilakukan dengan menganalisa kondisi dan karakteristik suatu masyarakat dan lokasi penghidupan mereka untuk menentukan faktor-faktor yang dapat mengurangi kemampuan masyarakat dalam menghadapi bencana. Kerentanan dapat ditentukan dengan mengkaji aspek keamanan lokasi penghidupan mereka atau kondisi-kondisi yang diakibatkan oleh faktor-faktor atau proses-proses fisik, sosial ekonomi dan lingkungan hidup yang bisa meningkatkan kerawanan suatu masyarakat terhadap ancaman dan dampak bencana.
2014, No.1424 14 Kerentanan bencana ditinjau dari komponen sosial budaya, fisik, ekonomi dan lingkungan. Penghitungan kerentanan suatu kawasan bila terpapar oleh suatu ancaman bencana terdiri dari 3 indeks kerentanan. Indeks tersebut adalah Indeks Penduduk Terpapar (dalam satuan jiwa), Indeks Kerugian (dalam satuan Rupiah) dan Indeks Kerusakan Lingkungan (dalam satuan hektar).
3. Pengkajian Kapasitas Pengkajian kapasitas dilakukan dengan mengidentifikasikan status kemampuan individu, masyarakat, lembaga pemerintah atau non pemerintah dan aktor lain dalam menangani ancaman dengan sumber daya yang tersedia untuk melakukan tindakan pencegahan, mitigasi, dan mempersiapkan penanganan darurat, serta menangani kerentanan yang ada dengan kapasitas yang dimiliki oleh masyarakat tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8238, '2. Pengkajian Kerentanan Pengkajian kerentanan dapat dilakukan dengan menganalisa kondisi dan karakteristik suatu masyarakat dan lokasi penghidupan mereka untuk menentukan faktor-faktor yang dapat mengurangi kemampuan masyarakat dalam menghadapi bencana. Kerentanan dapat ditentukan dengan mengkaji aspek keamanan lokasi penghidupan mereka atau kondisi-kondisi yang diakibatkan oleh faktor-faktor atau proses-proses fisik, sosial ekonomi dan lingkungan hidup yang bisa meningkatkan kerawanan suatu masyarakat terhadap ancaman dan dampak bencana.
2014, No.1424 14 Kerentanan bencana ditinjau dari komponen sosial budaya, fisik, ekonomi dan lingkungan. Penghitungan kerentanan suatu kawasan bila terpapar oleh suatu ancaman bencana terdiri dari 3 indeks kerentanan. Indeks tersebut adalah Indeks Penduduk Terpapar (dalam satuan jiwa), Indeks Kerugian (dalam satuan Rupiah) dan Indeks Kerusakan Lingkungan (dalam satuan hektar).
3. Pengkajian Kapasitas Pengkajian kapasitas dilakukan dengan mengidentifikasikan status kemampuan individu, masyarakat, lembaga pemerintah atau non pemerintah dan aktor lain dalam menangani ancaman dengan sumber daya yang tersedia untuk melakukan tindakan pencegahan, mitigasi, dan mempersiapkan penanganan darurat, serta menangani kerentanan yang ada dengan kapasitas yang dimiliki oleh masyarakat tersebut.', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8239, 'perka-4-2012', 28, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'Kapasitas/kemampuan adalah segala upaya yang dapat dilakukan oleh individu maupun kelompok dalam rangka menghadapi bahaya atau ancaman bencana. Aspek kemampuan antara lain kebijakan, kesiapsiagaan, dan partisipasi masyarakat. Penilaian kemampuan dilakukan pada sumberdaya orang per orang, rumah tangga, dan kelompok untuk mengatasi suatu ancaman atau bertahan atas dampak dari sebuah bahaya bencana. Pengukurannya dapat dilakukan berdasarkan aspek kebijakan, kesiapsiagaan, dan peran serta masyarakat.
4. Pengkajian Risiko Pengkajian risiko merupakan pengemasan hasil pengkajian ancaman, kerentanan dankemampuan/ketahanan suatu daerah terhadap bencana untuk menentukan skala prioritas tindakan yang dibuat dalam bentuk rencana kerja dan rekomendasi guna meredam risiko bencana.
Peta Risiko Bencana disusun dengan melakukan overlay Peta Ancaman, Peta Kerentanan dan Peta Kapasitas. Peta Risiko Bencana disusun untuk bencana yang mengancam suatu daerah. Peta kerentanan baru dapat disusun setelah Peta Ancaman selesai. Peta Risiko telah dipersiapkan berdasarkan grid indeks atas peta Ancaman, peta Kerentanan dan peta Kapasitas.
2.3.1. Bencana Gempabumi Berdasarkan Pedoman Nasional Pengkajian Risiko Bencana, ancaman bencana gempa bumi dapat dibagi menjadi 3 (tiga) kelas Indeks Ancaman.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8239, 'Kapasitas/kemampuan adalah segala upaya yang dapat dilakukan oleh individu maupun kelompok dalam rangka menghadapi bahaya atau ancaman bencana. Aspek kemampuan antara lain kebijakan, kesiapsiagaan, dan partisipasi masyarakat. Penilaian kemampuan dilakukan pada sumberdaya orang per orang, rumah tangga, dan kelompok untuk mengatasi suatu ancaman atau bertahan atas dampak dari sebuah bahaya bencana. Pengukurannya dapat dilakukan berdasarkan aspek kebijakan, kesiapsiagaan, dan peran serta masyarakat.
4. Pengkajian Risiko Pengkajian risiko merupakan pengemasan hasil pengkajian ancaman, kerentanan dankemampuan/ketahanan suatu daerah terhadap bencana untuk menentukan skala prioritas tindakan yang dibuat dalam bentuk rencana kerja dan rekomendasi guna meredam risiko bencana.
Peta Risiko Bencana disusun dengan melakukan overlay Peta Ancaman, Peta Kerentanan dan Peta Kapasitas. Peta Risiko Bencana disusun untuk bencana yang mengancam suatu daerah. Peta kerentanan baru dapat disusun setelah Peta Ancaman selesai. Peta Risiko telah dipersiapkan berdasarkan grid indeks atas peta Ancaman, peta Kerentanan dan peta Kapasitas.
2.3.1. Bencana Gempabumi Berdasarkan Pedoman Nasional Pengkajian Risiko Bencana, ancaman bencana gempa bumi dapat dibagi menjadi 3 (tiga) kelas Indeks Ancaman.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8240, 'perka-4-2012', 29, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'Komponen dari indeks tersebut adalah peta bahaya gempa bumi dan peta zonasi gempa bumi tahun 2010. Kelas Indeks Rendah Ancaman Bencana Gempa Bumi dengan nilai pga value kurang dari 0,2501. Kelas Indeks Ancaman Sedang Bencana Gempa Bumi dengan nilai pga value antara 15 2014, No.1424 0,2501-0,70. Sedangkan kelas Indeks Tinggi Ancaman Bencana Gempa Bumi dengan nilai pga value lebih dari 0,70. Perhitungan untuk mendapatkan kelas Indeks Ancaman dari luas kawasan terpapar dilaksanakan dalam pengkajian risiko bencana dalam Dokumen Kajian Risiko Bencana Daerah.
Berdasarkan Indeks Ancaman, Indeks Penduduk terpapar dan Indeks Kerugian serta Indeks Kapasitas diperoleh tingkat risiko untuk bencana gempabumi. Tingkat risiko bencana gempabumi dapat dilihat pada Lampiran 1 dan peta risiko gempabumi seperti ditunjukkan berikut.
2.3.2. Bencana Tsunami Pada wilayah pesisir yang rawan terhadap tsunami, maka perlu diperhitungkan maksimal tinggi tsunami. Masing-masing daerah memiliki catatan tinggi maksimal tsunami yang berbeda-beda antara daerah satu dengan daerah lainnya. Tinggi maksimal tsunami ini bisa diperoleh dengan melakukan kajian ancaman tsunami dan tabel ketinggiaannya dapat dilihat pada Lampiran 2.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8240, 'Komponen dari indeks tersebut adalah peta bahaya gempa bumi dan peta zonasi gempa bumi tahun 2010. Kelas Indeks Rendah Ancaman Bencana Gempa Bumi dengan nilai pga value kurang dari 0,2501. Kelas Indeks Ancaman Sedang Bencana Gempa Bumi dengan nilai pga value antara 15 2014, No.1424 0,2501-0,70. Sedangkan kelas Indeks Tinggi Ancaman Bencana Gempa Bumi dengan nilai pga value lebih dari 0,70. Perhitungan untuk mendapatkan kelas Indeks Ancaman dari luas kawasan terpapar dilaksanakan dalam pengkajian risiko bencana dalam Dokumen Kajian Risiko Bencana Daerah.
Berdasarkan Indeks Ancaman, Indeks Penduduk terpapar dan Indeks Kerugian serta Indeks Kapasitas diperoleh tingkat risiko untuk bencana gempabumi. Tingkat risiko bencana gempabumi dapat dilihat pada Lampiran 1 dan peta risiko gempabumi seperti ditunjukkan berikut.
2.3.2. Bencana Tsunami Pada wilayah pesisir yang rawan terhadap tsunami, maka perlu diperhitungkan maksimal tinggi tsunami. Masing-masing daerah memiliki catatan tinggi maksimal tsunami yang berbeda-beda antara daerah satu dengan daerah lainnya. Tinggi maksimal tsunami ini bisa diperoleh dengan melakukan kajian ancaman tsunami dan tabel ketinggiaannya dapat dilihat pada Lampiran 2.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8241, 'perka-4-2012', 30, 'lampiran', 'Lampiran hal. 16', NULL, 16, '2014, No.1424 16 BAB III DASAR PENERAPAN SEKOLAH/MADRASAH AMAN DARI BENCANA Sekolah aman dibagi menjadi tiga definisi, yaitu definisi umum, definisi khusus dan definisi terkait PRB. Berikut rinciannya: (a) Pengertian umum: Sekolah aman adalah sekolah yang mengakui dan melindungi hak-hak anak dengan menyediakan suasana dan lingkungan yang menjamin proses pembelajaran, kesehatan, keselamatan, dan keamanan siswanya terjamin setiap saat; (b) Pengertian Definisi Khusus: Sekolah aman adalah sekolah yang menerapkan standar sarana dan prasarana yang mampu melindungi warga sekolah dan lingkungan di sekitarnya dari bahaya bencana; (c) Pengertian terkait PRB:
Sekolah aman adalah komunitas pembelajar yang berkomitmen akan budaya aman dan sehat, sadar akan risiko, memiliki rencana yang matang dan mapan sebelum, saat, dan sesudah bencana, dan selalu siap untuk merespons pada saat darurat dan bencana.
Prinsip-prinsip Pendidikan Ramah Anak yang dikembangkan dalam membentuk Nilai-Nilai dan Prinsip-Prinsip Penerapan Sekolah/Madrasah Aman dari Bencana adalah panduan bagi para pemangku kepentingan di sekolah/madrasah termasuk anak. Nilai-nilai, Prinsip-Prinsip, Strategi dan Kerangka kerja Sekolah/Madrasah Aman dari Bencana adalah sebagai berikut:
3.1. Nilai-Nilai Pelaksanaan Sekolah/Madrasah aman dari bencana dalam pedoman ini mempertimbangkan nilai-nilai:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8241, '2014, No.1424 16 BAB III DASAR PENERAPAN SEKOLAH/MADRASAH AMAN DARI BENCANA Sekolah aman dibagi menjadi tiga definisi, yaitu definisi umum, definisi khusus dan definisi terkait PRB. Berikut rinciannya: (a) Pengertian umum: Sekolah aman adalah sekolah yang mengakui dan melindungi hak-hak anak dengan menyediakan suasana dan lingkungan yang menjamin proses pembelajaran, kesehatan, keselamatan, dan keamanan siswanya terjamin setiap saat; (b) Pengertian Definisi Khusus: Sekolah aman adalah sekolah yang menerapkan standar sarana dan prasarana yang mampu melindungi warga sekolah dan lingkungan di sekitarnya dari bahaya bencana; (c) Pengertian terkait PRB:
Sekolah aman adalah komunitas pembelajar yang berkomitmen akan budaya aman dan sehat, sadar akan risiko, memiliki rencana yang matang dan mapan sebelum, saat, dan sesudah bencana, dan selalu siap untuk merespons pada saat darurat dan bencana.
Prinsip-prinsip Pendidikan Ramah Anak yang dikembangkan dalam membentuk Nilai-Nilai dan Prinsip-Prinsip Penerapan Sekolah/Madrasah Aman dari Bencana adalah panduan bagi para pemangku kepentingan di sekolah/madrasah termasuk anak. Nilai-nilai, Prinsip-Prinsip, Strategi dan Kerangka kerja Sekolah/Madrasah Aman dari Bencana adalah sebagai berikut:
3.1. Nilai-Nilai Pelaksanaan Sekolah/Madrasah aman dari bencana dalam pedoman ini mempertimbangkan nilai-nilai:', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8242, 'perka-4-2012', 31, 'lampiran', 'Lampiran hal. 16', NULL, 16, 'a. Perubahan Budaya. Penerapan Sekolah/Madrasah Aman dari Bencana ditujukan untuk menghasilkan perubahan budaya yang lebih aman dari bencana dan perubahan dari aman menjadi berketahanan dalam upaya mewujudkan masyarakat Indonesia yang tangguh bencana.
b. Berorientasi Pemberdayaan. Meningkatkan kemampuan pengelolaan sekolah/madrasah dan warga sekolah/madrasah termasuk anak untuk menerapkan Sekolah/Madrasah Aman dari Bencana dalam pengembangan kurikulum, sarana prasarana, pendidik dan tenaga kependidikan, pengelolaan dan pembiayaan di sekolah/madrasah.
c. Kemandirian. Mengoptimalkan pendayagunaan sumberdaya yang dimiliki sekolah/madrasah.
d. Pendekatan berbasis hak. Hak-hak asasi manusia termasuk hak-hak anak sebagai pertimbangan utama dalam upaya penerapan Sekolah/Madrasah Aman dari Bencana.
e. Keberlanjutan. Mengutamakan terbentuknya pelembagaan aktivitas warga sekolah/madrasah termasuk anak dalam upaya penerapan 17 2014, No.1424 sekolah/madrasah dari bencana dengan mengaktifkan lembaga yang sudah ada seperti TP UKS, Komite Sekolah, OSIS, Ekstrakurikuler, dsb.
f. Kearifan lokal. Menggali dan mendayagunakan kearifan lokal yang mendukung upaya penerapan sekolah/madrasah aman dari bencana.
g. Kemitraan. Berupaya melibatkan pemangku kepentingan termasuk anak secara individu maupun dalam kelompok untuk bekerjasama dalam mencapai tujuan berdasarkan prinsip-prinsip Sekolah/ Madrasah Aman dari bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8242, 'a. Perubahan Budaya. Penerapan Sekolah/Madrasah Aman dari Bencana ditujukan untuk menghasilkan perubahan budaya yang lebih aman dari bencana dan perubahan dari aman menjadi berketahanan dalam upaya mewujudkan masyarakat Indonesia yang tangguh bencana.
b. Berorientasi Pemberdayaan. Meningkatkan kemampuan pengelolaan sekolah/madrasah dan warga sekolah/madrasah termasuk anak untuk menerapkan Sekolah/Madrasah Aman dari Bencana dalam pengembangan kurikulum, sarana prasarana, pendidik dan tenaga kependidikan, pengelolaan dan pembiayaan di sekolah/madrasah.
c. Kemandirian. Mengoptimalkan pendayagunaan sumberdaya yang dimiliki sekolah/madrasah.
d. Pendekatan berbasis hak. Hak-hak asasi manusia termasuk hak-hak anak sebagai pertimbangan utama dalam upaya penerapan Sekolah/Madrasah Aman dari Bencana.
e. Keberlanjutan. Mengutamakan terbentuknya pelembagaan aktivitas warga sekolah/madrasah termasuk anak dalam upaya penerapan 17 2014, No.1424 sekolah/madrasah dari bencana dengan mengaktifkan lembaga yang sudah ada seperti TP UKS, Komite Sekolah, OSIS, Ekstrakurikuler, dsb.
f. Kearifan lokal. Menggali dan mendayagunakan kearifan lokal yang mendukung upaya penerapan sekolah/madrasah aman dari bencana.
g. Kemitraan. Berupaya melibatkan pemangku kepentingan termasuk anak secara individu maupun dalam kelompok untuk bekerjasama dalam mencapai tujuan berdasarkan prinsip-prinsip Sekolah/ Madrasah Aman dari bencana.', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8243, 'perka-4-2012', 32, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'h. Inklusivitas. Memperhatikan kepentingan warga sekolah/madrasah terutama anak berkebutuhan khusus.
3.2. Prinsip-Prinsip Pelaksanaan Sekolah/Madrasah aman dari bencana dalam pedoman ini mempertimbangkan prinsip-prinsip sebagai berikut:
a. Berbasis hak. Penerapan Sekolah/Madrasah Aman dari Bencana harus didasari sebagai pemenuhan hak pendidikan anak dalam menerapkan keempat prinsip hak anak, yakni (1) Tidak ada satu anak pun yang sampai menderita akibat diskriminasi dan sikap tidak hormat yang menyangkut SARA, jenis kelamin, sikap, bahasa, pendapat, kebangsaan, kepemilikan, kecacatan fisik dan mental, status kelahiran dan lainnya,
(2) Anak-anak memiliki hak atas kelangsungan dan tumbuh kembangnya dalam semua aspek kehidupannya, termasuk aspek fisik, emosional, psikososial, kognitif, sosial dan budaya, (3) Kepentingan terbaik anak harus selalu menjadi pertimbangan didalam seluruh keputusan atau aksi yang mempengaruhi anak dan kelompok anak, termasuk keputusan yang dibuat oleh pemerintah, pemerintah daerah, aparat hukum, bahkan yang diatur didalam keluarga anak itu sendiri, dan (4) Anak-anak memiliki hak untuk berkumpul secara damai, berpartisipasi aktif dalam setiap aspek yang mempengaruhi kehidupan mereka, untuk mengekspresikan dengan bebas dan mendapatkan pendapat mereka didengar dan ditanggapi dengan sungguh-sungguh.
b. Interdisiplin dan Menyeluruh. Penerapan Sekolah/Madrasah Aman dari Bencana terintegrasi dalam standar pelayanan minimum pendidikan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8243, 'h. Inklusivitas. Memperhatikan kepentingan warga sekolah/madrasah terutama anak berkebutuhan khusus.
3.2. Prinsip-Prinsip Pelaksanaan Sekolah/Madrasah aman dari bencana dalam pedoman ini mempertimbangkan prinsip-prinsip sebagai berikut:
a. Berbasis hak. Penerapan Sekolah/Madrasah Aman dari Bencana harus didasari sebagai pemenuhan hak pendidikan anak dalam menerapkan keempat prinsip hak anak, yakni (1) Tidak ada satu anak pun yang sampai menderita akibat diskriminasi dan sikap tidak hormat yang menyangkut SARA, jenis kelamin, sikap, bahasa, pendapat, kebangsaan, kepemilikan, kecacatan fisik dan mental, status kelahiran dan lainnya,
(2) Anak-anak memiliki hak atas kelangsungan dan tumbuh kembangnya dalam semua aspek kehidupannya, termasuk aspek fisik, emosional, psikososial, kognitif, sosial dan budaya, (3) Kepentingan terbaik anak harus selalu menjadi pertimbangan didalam seluruh keputusan atau aksi yang mempengaruhi anak dan kelompok anak, termasuk keputusan yang dibuat oleh pemerintah, pemerintah daerah, aparat hukum, bahkan yang diatur didalam keluarga anak itu sendiri, dan (4) Anak-anak memiliki hak untuk berkumpul secara damai, berpartisipasi aktif dalam setiap aspek yang mempengaruhi kehidupan mereka, untuk mengekspresikan dengan bebas dan mendapatkan pendapat mereka didengar dan ditanggapi dengan sungguh-sungguh.
b. Interdisiplin dan Menyeluruh. Penerapan Sekolah/Madrasah Aman dari Bencana terintegrasi dalam standar pelayanan minimum pendidikan.', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8244, 'perka-4-2012', 33, 'lampiran', 'Lampiran hal. 17', NULL, 17, 'Menyeluruh dimaksudkan bahwa penerapan sekolah/madrasah aman dari bencana dilaksanakan secara terpadu untuk mencapai standar nasional pendidikan.
c. Komunikasi Antar-Budaya (Intercultural Approach). Pendekatan Penerapan Sekolah/Madrasah Aman dari Bencana harus mengutamakan komunikasi antar-pribadi yang memiliki latar belakang budaya yang berbeda (ras, etnik, atau sosio- ekonomi) sesuai dengan jati diri bangsa dan nilai–nilai luhur kemanusiaan.
2014, No.1424 18 3.3. Strategi Masih tingginya tingkat kerusakan sekolah/madrasah di daerah rawan bencana di Indonesia, mendorong pemerintah untuk melakukan sinkronisasi kebijakan dalam upaya Penerapan Sekolah/Madrasah Aman dari bencana. Sekolah/madrasah diharapkan menjadi suatu lingkungan yang aman terhadap ancaman bencana dan secara terus menerus mengimplementasikan upaya pengurangan risiko bencana.
Pembentukan karakter anak didik baik laki-laki maupun perempuan di Sekolah/Madrasah sangat dipengaruhi kondisi pendidik dan tenaga kependidikan, infrastruktur, fasilitas, pengelolaan dan pembiayaan yang bertanggung jawab, dan terutama proses pembelajaran yang dialami siswa.
Hal ini sejalan dengan tema strategis bidang pendidikan pada periode tahun 2010-2015 yang menekankan pada pembangunan dan penguatan pelayanan prima pendidikan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8244, 'Menyeluruh dimaksudkan bahwa penerapan sekolah/madrasah aman dari bencana dilaksanakan secara terpadu untuk mencapai standar nasional pendidikan.
c. Komunikasi Antar-Budaya (Intercultural Approach). Pendekatan Penerapan Sekolah/Madrasah Aman dari Bencana harus mengutamakan komunikasi antar-pribadi yang memiliki latar belakang budaya yang berbeda (ras, etnik, atau sosio- ekonomi) sesuai dengan jati diri bangsa dan nilai–nilai luhur kemanusiaan.
2014, No.1424 18 3.3. Strategi Masih tingginya tingkat kerusakan sekolah/madrasah di daerah rawan bencana di Indonesia, mendorong pemerintah untuk melakukan sinkronisasi kebijakan dalam upaya Penerapan Sekolah/Madrasah Aman dari bencana. Sekolah/madrasah diharapkan menjadi suatu lingkungan yang aman terhadap ancaman bencana dan secara terus menerus mengimplementasikan upaya pengurangan risiko bencana.
Pembentukan karakter anak didik baik laki-laki maupun perempuan di Sekolah/Madrasah sangat dipengaruhi kondisi pendidik dan tenaga kependidikan, infrastruktur, fasilitas, pengelolaan dan pembiayaan yang bertanggung jawab, dan terutama proses pembelajaran yang dialami siswa.
Hal ini sejalan dengan tema strategis bidang pendidikan pada periode tahun 2010-2015 yang menekankan pada pembangunan dan penguatan pelayanan prima pendidikan.', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8245, 'perka-4-2012', 34, 'lampiran', 'Lampiran hal. 18', NULL, 18, 'Dalam rencana Penerapan Sekolah/Madrasah Aman dari Bencana dengan jangka panjang, Pedoman ini menggunakan tiga tema strategis, yaitu (1) Sinkronisasi Kebijakan (2) Peningkatan Partisipasi Publik termasuk anak (3) Pelembagaan.
a. Sinkronisasi Kebijakan Pemetaan kebijakan dari berbagai K/L/D/I menjadi bahan pertimbangan utama dalam tema strategi sinkronisasi kebijakan. Dasar hukum dalam pedoman ini disusun berdasarkan hasil sinkronisasi kebijakan yang menjunjung tinggi nilai-nilai dan prinsip-prinsip penerapan sekolah/madrasah aman dari bencana.
b. Peningkatan Partisipasi Publik termasuk Anak Tema strategis peningkatan partisipasi publik termasuk anak dalam pedoman ini adalah menjadikan anak dan kaum muda mitra dalam Penerapan Sekolah/Madrasah Aman dari Bencana. Kegiatan penerapan sekolah/madrasah aman terintegrasi dengan pengetahuan dan keterampilan yang sudah dimiliki warga sekolah seperti Sekolah Sehat, Sekolah Hijau, Sekolah Adiwiyata, Lingkungan Inklusi dan Ramah Pembelajaran serta model-model Pendidikan Ramah Anak lainnya.
c. Pelembagaan Penerapan sekolah/madrasah aman dari bencana sejalan dengan peran dan fungsi masing-masing K/L/D/I terkait melalui pembentukan kelembagaan yang sesuai dengan peraturan perundang-undangan yang berlaku.
19 2014, No.1424 3.4. Peran Pemangku Kepentingan 1) Peran peserta didik
(a) Peserta didik melembagakan aktivitas pengurangan risiko bencana
(b) Peserta didik menjadi tutor sebaya bagi sekolah yang belum memenuhi standar sekolah aman.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8245, 'Dalam rencana Penerapan Sekolah/Madrasah Aman dari Bencana dengan jangka panjang, Pedoman ini menggunakan tiga tema strategis, yaitu (1) Sinkronisasi Kebijakan (2) Peningkatan Partisipasi Publik termasuk anak (3) Pelembagaan.
a. Sinkronisasi Kebijakan Pemetaan kebijakan dari berbagai K/L/D/I menjadi bahan pertimbangan utama dalam tema strategi sinkronisasi kebijakan. Dasar hukum dalam pedoman ini disusun berdasarkan hasil sinkronisasi kebijakan yang menjunjung tinggi nilai-nilai dan prinsip-prinsip penerapan sekolah/madrasah aman dari bencana.
b. Peningkatan Partisipasi Publik termasuk Anak Tema strategis peningkatan partisipasi publik termasuk anak dalam pedoman ini adalah menjadikan anak dan kaum muda mitra dalam Penerapan Sekolah/Madrasah Aman dari Bencana. Kegiatan penerapan sekolah/madrasah aman terintegrasi dengan pengetahuan dan keterampilan yang sudah dimiliki warga sekolah seperti Sekolah Sehat, Sekolah Hijau, Sekolah Adiwiyata, Lingkungan Inklusi dan Ramah Pembelajaran serta model-model Pendidikan Ramah Anak lainnya.
c. Pelembagaan Penerapan sekolah/madrasah aman dari bencana sejalan dengan peran dan fungsi masing-masing K/L/D/I terkait melalui pembentukan kelembagaan yang sesuai dengan peraturan perundang-undangan yang berlaku.
19 2014, No.1424 3.4. Peran Pemangku Kepentingan 1) Peran peserta didik
(a) Peserta didik melembagakan aktivitas pengurangan risiko bencana
(b) Peserta didik menjadi tutor sebaya bagi sekolah yang belum memenuhi standar sekolah aman.', 'Lampiran hal. 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8246, 'perka-4-2012', 35, 'lampiran', 'Lampiran hal. 19', NULL, 19, '2) Peran orangtua
(a) Membantu merumuskan program Sekolah/Madrasah Aman dengan Komite sekolah.
(b) Orangtua membantu menyebarluaskan penerapan Sekolah/Madrasah aman 3) Peran Pendidik dan Profesional Lainnya
(a) Meningkatkan pengetahuan dan keterampilan mengenai bahaya, kerentanan dan kapasitas sekolah/madrasah termasuk anak dalam upaya pengurangan risiko bencana.
(b) Melakukan usaha-usaha terencana guna mewujudkan suasana belajar dan proses pembelajaran agar peserta didik aktif dalam penerapan sekolah/madrasah aman dari bencana secara non-struktural
(c) Bekerja sama dengan warga sekolah lainnya termasuk anak dalam upaya penerapan sekolah/madrasah aman dari bencana secara struktural maupun non-struktural 4) Peran Komite Sekolah/Madrasah
(a) Membentuk forum orangtua dan guru dalam upaya penerapan sekolah/madrasah aman dari bencana melalui pengenalan materi PRB kepada para peserta didik, pembuatan jalur evakuasi dan upaya-upaya untuk mewujudkan sekolah/ madrasah yang lebih aman, sehat dan nyaman termasuk bagi anak berkebutuhan khusus.
(b) Komite Sekolah/Madrasah melakukan Pemantauan, pemeriksaan Kelayakan Gedung, Pemeliharaan dan perawatan Gedung.
5) Peran Organisasi Non-pemerintah, Nasional, Internasional
(a) Membantu sekolah/madrasah dalam melakukan upaya pengurangan risiko bencana termasuk anak didik berkebutuhan khusus.
(b) Mendukung kemitraan dan membangun jejaring pengetahuan antar sekolah/madrasah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8246, '2) Peran orangtua
(a) Membantu merumuskan program Sekolah/Madrasah Aman dengan Komite sekolah.
(b) Orangtua membantu menyebarluaskan penerapan Sekolah/Madrasah aman 3) Peran Pendidik dan Profesional Lainnya
(a) Meningkatkan pengetahuan dan keterampilan mengenai bahaya, kerentanan dan kapasitas sekolah/madrasah termasuk anak dalam upaya pengurangan risiko bencana.
(b) Melakukan usaha-usaha terencana guna mewujudkan suasana belajar dan proses pembelajaran agar peserta didik aktif dalam penerapan sekolah/madrasah aman dari bencana secara non-struktural
(c) Bekerja sama dengan warga sekolah lainnya termasuk anak dalam upaya penerapan sekolah/madrasah aman dari bencana secara struktural maupun non-struktural 4) Peran Komite Sekolah/Madrasah
(a) Membentuk forum orangtua dan guru dalam upaya penerapan sekolah/madrasah aman dari bencana melalui pengenalan materi PRB kepada para peserta didik, pembuatan jalur evakuasi dan upaya-upaya untuk mewujudkan sekolah/ madrasah yang lebih aman, sehat dan nyaman termasuk bagi anak berkebutuhan khusus.
(b) Komite Sekolah/Madrasah melakukan Pemantauan, pemeriksaan Kelayakan Gedung, Pemeliharaan dan perawatan Gedung.
5) Peran Organisasi Non-pemerintah, Nasional, Internasional
(a) Membantu sekolah/madrasah dalam melakukan upaya pengurangan risiko bencana termasuk anak didik berkebutuhan khusus.
(b) Mendukung kemitraan dan membangun jejaring pengetahuan antar sekolah/madrasah.', 'Lampiran hal. 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8247, 'perka-4-2012', 36, 'lampiran', 'Lampiran hal. 19', NULL, 19, '(c) Mengembangkan dan menyediakan materi-materi pendidikan, pengurangan risiko bencana.
(d) Memberikan bantuan teknis penerapan sekolah/madrasah aman dari bencana secara struktural maupun non-struktural
(e) Membantu pemerintah dan pemerintah daerah dalam penerapan sekolah/madrasah aman dari bencana secara struktural maupun non-struktural 2014, No.1424 20 6) Peran Kementerian/Lembaga dan Pemerintah Daerah
(a) Melakukan kegiatan-kegiatan penerapan sekolah/madrasah aman dari bencana sejalan dengan ketiga tema strategis, prinsip-prinsip, nilai-nilai dan kerangka kerja.
(b) Memperkuat mekanisme pemantauan, evaluasi dan pelaporan penerapan sekolah/madrasah aman dari bencana termasuk pemutahiran data rehabilitasi sekolah, baik secara elektronik maupun manual
(c) Menyediakan pedoman dan petunjuk teknis yang diperlukan oleh sekolah/madrasah dalam penerapan sekolah/madrasah aman dari bencana secara struktural dan non-struktural.
(d) Mendorong pembinaan berkelanjutan dengan mengintegrasikan penerapan Sekolah/Madrasah Aman dari Bencana kedalam revisi SKB 4 Menteri mengenai Pembinaan dan Pengembangan Usaha Kesehatan Sekolah
(e) Memastikan perencanaan Penerapan Sekolah/Madrasah Aman dari Bencana sebagai bagian dari Rencana Penanggulangan Bencana.
7) Peran Media Massa
(a) Media massa melakukan Sosialisasi dan advokasi penerapan sekolah/madrasah aman dari bencana kepada masyarakat luas.
(b) Media massa berperan sebagai alat kontrol dalam penerapan sekolah/madrasah aman dari bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8247, '(c) Mengembangkan dan menyediakan materi-materi pendidikan, pengurangan risiko bencana.
(d) Memberikan bantuan teknis penerapan sekolah/madrasah aman dari bencana secara struktural maupun non-struktural
(e) Membantu pemerintah dan pemerintah daerah dalam penerapan sekolah/madrasah aman dari bencana secara struktural maupun non-struktural 2014, No.1424 20 6) Peran Kementerian/Lembaga dan Pemerintah Daerah
(a) Melakukan kegiatan-kegiatan penerapan sekolah/madrasah aman dari bencana sejalan dengan ketiga tema strategis, prinsip-prinsip, nilai-nilai dan kerangka kerja.
(b) Memperkuat mekanisme pemantauan, evaluasi dan pelaporan penerapan sekolah/madrasah aman dari bencana termasuk pemutahiran data rehabilitasi sekolah, baik secara elektronik maupun manual
(c) Menyediakan pedoman dan petunjuk teknis yang diperlukan oleh sekolah/madrasah dalam penerapan sekolah/madrasah aman dari bencana secara struktural dan non-struktural.
(d) Mendorong pembinaan berkelanjutan dengan mengintegrasikan penerapan Sekolah/Madrasah Aman dari Bencana kedalam revisi SKB 4 Menteri mengenai Pembinaan dan Pengembangan Usaha Kesehatan Sekolah
(e) Memastikan perencanaan Penerapan Sekolah/Madrasah Aman dari Bencana sebagai bagian dari Rencana Penanggulangan Bencana.
7) Peran Media Massa
(a) Media massa melakukan Sosialisasi dan advokasi penerapan sekolah/madrasah aman dari bencana kepada masyarakat luas.
(b) Media massa berperan sebagai alat kontrol dalam penerapan sekolah/madrasah aman dari bencana.', 'Lampiran hal. 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8248, 'perka-4-2012', 37, 'lampiran', 'Lampiran hal. 21', NULL, 21, '21 2014, No.1424 BAB IV KERANGKA KERJA PENERAPAN SEKOLAH/MADRASAH AMAN DARI BENCANA Kerangka kerja penerapan sekolah/madrasah aman merupakan kerangka kerja yang dibagi ke dalam struktural dan non struktural.
4.1. Kerangka Kerja Struktural
a. Pengertian Dalam pedoman ini yang dimaksud dengan kerangka kerja struktural adalah konstruksi fisik sekolah/madrasah untuk mengurangi risiko bencana.
b. Aspek Mendasar 1) Lokasi aman dari bencana
(a) Lahan sesuai dengan peruntukan lokasi yang diatur dalam Peraturan Daerah tentang Rencana Tata Ruang Wilayah Kabupaten/Kota atau rencana lain yang lebih rinci dan mengikat, dan mendapat izin pemanfaatan tanah dari Pemerintah Daerah setempat mengacu pada PerMenPU No. 29 Tahun 2006.
(b) Luas lahan yang dapat digunakan secara efektif untuk membangun prasarana sekolah/madrasah berupa bangunan dan tempat bermain dan berolahraga.
(c) Lahan terhindar dari potensi bahaya yang mengancam kesehatan dan keselamatan jiwa, terhindar dari gangguan pencemaran air, kebisingan, dan pencemaran udara serta memiliki akses untuk penyelamatan dalam keadaan darurat.
- Tidak terletak di lahan bekas pembuangan sampah akhir (TPA) dan daerah bekas pertambangan
- Jauh dari gangguan atau jaringan listrik tegangan tinggi (minimal 0.5 Km)
- Bangunan sekolah sebaiknya berada cukup jauh dari sungai dan berada di ketinggian yang aman dari bahaya banjir.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8248, '21 2014, No.1424 BAB IV KERANGKA KERJA PENERAPAN SEKOLAH/MADRASAH AMAN DARI BENCANA Kerangka kerja penerapan sekolah/madrasah aman merupakan kerangka kerja yang dibagi ke dalam struktural dan non struktural.
4.1. Kerangka Kerja Struktural
a. Pengertian Dalam pedoman ini yang dimaksud dengan kerangka kerja struktural adalah konstruksi fisik sekolah/madrasah untuk mengurangi risiko bencana.
b. Aspek Mendasar 1) Lokasi aman dari bencana
(a) Lahan sesuai dengan peruntukan lokasi yang diatur dalam Peraturan Daerah tentang Rencana Tata Ruang Wilayah Kabupaten/Kota atau rencana lain yang lebih rinci dan mengikat, dan mendapat izin pemanfaatan tanah dari Pemerintah Daerah setempat mengacu pada PerMenPU No. 29 Tahun 2006.
(b) Luas lahan yang dapat digunakan secara efektif untuk membangun prasarana sekolah/madrasah berupa bangunan dan tempat bermain dan berolahraga.
(c) Lahan terhindar dari potensi bahaya yang mengancam kesehatan dan keselamatan jiwa, terhindar dari gangguan pencemaran air, kebisingan, dan pencemaran udara serta memiliki akses untuk penyelamatan dalam keadaan darurat.
- Tidak terletak di lahan bekas pembuangan sampah akhir (TPA) dan daerah bekas pertambangan
- Jauh dari gangguan atau jaringan listrik tegangan tinggi (minimal 0.5 Km)
- Bangunan sekolah sebaiknya berada cukup jauh dari sungai dan berada di ketinggian yang aman dari bahaya banjir.', 'Lampiran hal. 21', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8249, 'perka-4-2012', 38, 'lampiran', 'Lampiran hal. 21', NULL, 21, '- Tidak di atas tebing atau kemiringan lahan tidak boleh melebihi 6% kecuali kalau sudah diambil langkah besar untuk mengendalikan erosi dan drainase
(d) Memenuhi ketentuan rasio minimum luas lahan terhadap peserta didik
(e) Peletakan bangunan sekolah agak jauh dari sempadan jalan yang ada.
2014, No.1424 22 2) Struktur bangunan Secara umum bangunan harus memenuhi persyaratan keselamatan, kesehatan, kemudahan termasuk kelayakan bagi anak berkebutuhan khusus, kenyamanan dan keamanan sesuai dengan PerMenPU No.29 Tahun 2006 dan Pedoman Teknis Rumah dan Bangungan Gedung Tahan Gempa yang dikeluarkan oleh Kementerian PU Tahun 2006. Beberapa hal yang terkait dengan struktur bangunan sekolah/madrasah aman dari bencana adalah sebagai berikut:
(a) Bangunan harus didesain berdasarkan standar teknis baku dan mutu yang berlaku untuk desain bangunan, material bahan bangunan yang digunakan, serta tata cara pelaksanaan konstruksi, dengan mengacu pada SNI dan peraturan perundangan yang berlaku
(b) Desain bangunan harus memperhitungkan analisa gempa sesuai SNI yang mengatur tentang Perencanaan Ketahanan Gempa untuk Struktur Bangunan Gedung dan mengacu pada peta zonasi gempa yang terbaru
(c) Penggunaan material bahan bangunan harus mempertimbangkan kearifan lokal, dengan menggunakan bahan bangunan yang sesuai standar mutu, mudah diperoleh di daerah setempat, namun tidak menimbulkan kerusakan lingkungan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8249, '- Tidak di atas tebing atau kemiringan lahan tidak boleh melebihi 6% kecuali kalau sudah diambil langkah besar untuk mengendalikan erosi dan drainase
(d) Memenuhi ketentuan rasio minimum luas lahan terhadap peserta didik
(e) Peletakan bangunan sekolah agak jauh dari sempadan jalan yang ada.
2014, No.1424 22 2) Struktur bangunan Secara umum bangunan harus memenuhi persyaratan keselamatan, kesehatan, kemudahan termasuk kelayakan bagi anak berkebutuhan khusus, kenyamanan dan keamanan sesuai dengan PerMenPU No.29 Tahun 2006 dan Pedoman Teknis Rumah dan Bangungan Gedung Tahan Gempa yang dikeluarkan oleh Kementerian PU Tahun 2006. Beberapa hal yang terkait dengan struktur bangunan sekolah/madrasah aman dari bencana adalah sebagai berikut:
(a) Bangunan harus didesain berdasarkan standar teknis baku dan mutu yang berlaku untuk desain bangunan, material bahan bangunan yang digunakan, serta tata cara pelaksanaan konstruksi, dengan mengacu pada SNI dan peraturan perundangan yang berlaku
(b) Desain bangunan harus memperhitungkan analisa gempa sesuai SNI yang mengatur tentang Perencanaan Ketahanan Gempa untuk Struktur Bangunan Gedung dan mengacu pada peta zonasi gempa yang terbaru
(c) Penggunaan material bahan bangunan harus mempertimbangkan kearifan lokal, dengan menggunakan bahan bangunan yang sesuai standar mutu, mudah diperoleh di daerah setempat, namun tidak menimbulkan kerusakan lingkungan', 'Lampiran hal. 21', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8250, 'perka-4-2012', 39, 'lampiran', 'Lampiran hal. 22', NULL, 22, '(d) Sumber Daya Manusia (SDM) yang melaksanakan perencanaan, pelaksanaan konstruksi, pengawasan, pemeliharaan, perawatan, perbaikan maupun pemeriksaan berkala bangunan harus mempunyai kompetensi dan keahlian dalam bidang yang terkait penyelenggaraan bangunan sesuai peraturan perundangan yang berlaku
(e) Bangunan harus didesain dengan menyediakan jalur evakuasi yang cukup dan tidak terhalang sebagai antisipasi kondisi darurat bencana
(f) Bangunan harus didesain dengan menyediakan prasarana kemudahan akses (aksesibilitas) bagi mereka yang berkebutuhan khusus dan lansia
(g) Bangunan harus didesain dengan menyediakan penghawaan dan sirkulasi udara serta pencahayaan alami yang cukup memadai untuk kelangsungan kegiatan pembelajaran
(h) Bangunan harus didesain dengan memperhitungkan akses yang cukup dan memadai untuk penyediaan air bersih dan sanitasi (air kotor, sampah, dan drainase)
(i) Desain sekolah/madrasah disesuaikan dengan potensi karakteristik jenis ancaman bencana di lokasi sekolah/madrasah tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8250, '(d) Sumber Daya Manusia (SDM) yang melaksanakan perencanaan, pelaksanaan konstruksi, pengawasan, pemeliharaan, perawatan, perbaikan maupun pemeriksaan berkala bangunan harus mempunyai kompetensi dan keahlian dalam bidang yang terkait penyelenggaraan bangunan sesuai peraturan perundangan yang berlaku
(e) Bangunan harus didesain dengan menyediakan jalur evakuasi yang cukup dan tidak terhalang sebagai antisipasi kondisi darurat bencana
(f) Bangunan harus didesain dengan menyediakan prasarana kemudahan akses (aksesibilitas) bagi mereka yang berkebutuhan khusus dan lansia
(g) Bangunan harus didesain dengan menyediakan penghawaan dan sirkulasi udara serta pencahayaan alami yang cukup memadai untuk kelangsungan kegiatan pembelajaran
(h) Bangunan harus didesain dengan memperhitungkan akses yang cukup dan memadai untuk penyediaan air bersih dan sanitasi (air kotor, sampah, dan drainase)
(i) Desain sekolah/madrasah disesuaikan dengan potensi karakteristik jenis ancaman bencana di lokasi sekolah/madrasah tersebut.', 'Lampiran hal. 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8251, 'perka-4-2012', 40, 'lampiran', 'Lampiran hal. 23', NULL, 23, '23 2014, No.1424 3) Desain dan Penataan Kelas Pengaturan ruang kelas harus ideal sehingga memiliki risiko sekecil mungkin bila sewaktu-waktu terjadi bencana mengacu pada PerMenPU No.29 Tahun 2006. Beberapa hal yang harus ditambahkan dalam mendesain dan menata ruang kelas sekolah/madrasah aman dari bencana antara lain: a) tiap kelas harus memiliki dua pintu dengan pintu membuka keluar, b) memiliki jalur evakuasi dan akses yang aman yang dapat dicapai dengan mudah dan dilengkapi penunjuk arah yang jelas dan dikenal dengan baik oleh anak, termasuk anak berkebutuhan khusus terutama jika terjadi bencana kebakaran, gempabumi dan/atau bencana lainnya.
4) Dukungan Sarana Prasarana.
Dukungan sarana dan prasarana mengacu pada PerMenPU No.29 Tahun 2006. Kriteria minimum sarana dan prasarana untuk mendukung keberlangsungan kegiatan belajar mengajar mencakup: a) Kriteria minimum sarana yang terdiri dari perabot, peralatan pendidikan, media pendidikan, buku dan sumber belajar lainnya, teknologi informasi dan komunikasi, serta perlengkapan lain yang wajib dimiliki oleh setiap sekolah/madrasah; b) Bangunan harus dilengkapi dengan sarana dan prasarana pencegahan dan penanggulangan kebakaran, minimal berupa Alat Pemadam Api Ringan (APAR) pada setiap lantai dan diletakkan di tempat yang mudah dijangkau dan tidak terhalang');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8251, '23 2014, No.1424 3) Desain dan Penataan Kelas Pengaturan ruang kelas harus ideal sehingga memiliki risiko sekecil mungkin bila sewaktu-waktu terjadi bencana mengacu pada PerMenPU No.29 Tahun 2006. Beberapa hal yang harus ditambahkan dalam mendesain dan menata ruang kelas sekolah/madrasah aman dari bencana antara lain: a) tiap kelas harus memiliki dua pintu dengan pintu membuka keluar, b) memiliki jalur evakuasi dan akses yang aman yang dapat dicapai dengan mudah dan dilengkapi penunjuk arah yang jelas dan dikenal dengan baik oleh anak, termasuk anak berkebutuhan khusus terutama jika terjadi bencana kebakaran, gempabumi dan/atau bencana lainnya.
4) Dukungan Sarana Prasarana.
Dukungan sarana dan prasarana mengacu pada PerMenPU No.29 Tahun 2006. Kriteria minimum sarana dan prasarana untuk mendukung keberlangsungan kegiatan belajar mengajar mencakup: a) Kriteria minimum sarana yang terdiri dari perabot, peralatan pendidikan, media pendidikan, buku dan sumber belajar lainnya, teknologi informasi dan komunikasi, serta perlengkapan lain yang wajib dimiliki oleh setiap sekolah/madrasah; b) Bangunan harus dilengkapi dengan sarana dan prasarana pencegahan dan penanggulangan kebakaran, minimal berupa Alat Pemadam Api Ringan (APAR) pada setiap lantai dan diletakkan di tempat yang mudah dijangkau dan tidak terhalang', 'Lampiran hal. 23', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8252, 'perka-4-2012', 41, 'lampiran', 'Lampiran hal. 23', NULL, 23, 'c. Pemeriksaan Struktur Bangunan 1) Metode Pemeriksaan Pemeriksaan bangunan dilakukan untuk menjamin seluruh komponen bangunan gedung laik fungsi, terutama dalam kondisi setelah terjadi bencana maupun untuk menyesuaikan dengan peraturan teknis bangunan gedung yang berlaku. Formulir untuk pemeriksaan struktur bangunan pada Lampiran 3. Prosedur pemeriksaan kerentanan bangunan terhadap gempa secara umum terdiri dari tiga tahapan, yaitu Pemeriksaan Visual Secara Cepat (Rapid Visual Screening), Pemeriksaan Struktur Secara Cepat (Quick Structural Evaluation), and Pemeriksaan terinci (Detailed Assessment).
2014, No.1424 24 a) Pemeriksaan Visual Secara Cepat (Rapid Visual Screening) Penilaian Cepat Secara Visual merupakan tahap pertama pemeriksaan kerentanan bangunan secara cepat yang dilakukan dengan tujuan menetapkan bangunan–bangunan berisiko.
Pemeriksaan visual terdiri dari pemeriksaan terhadap konfigurasi bangunan berdasarkan tata letak bangunan dan konfigurasinya, termasuk alur pembebanan, lantai lemah (weak story), lantai lunak (soft story), bentuk geometri, massa efektif, torsi, dan benturan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8252, 'c. Pemeriksaan Struktur Bangunan 1) Metode Pemeriksaan Pemeriksaan bangunan dilakukan untuk menjamin seluruh komponen bangunan gedung laik fungsi, terutama dalam kondisi setelah terjadi bencana maupun untuk menyesuaikan dengan peraturan teknis bangunan gedung yang berlaku. Formulir untuk pemeriksaan struktur bangunan pada Lampiran 3. Prosedur pemeriksaan kerentanan bangunan terhadap gempa secara umum terdiri dari tiga tahapan, yaitu Pemeriksaan Visual Secara Cepat (Rapid Visual Screening), Pemeriksaan Struktur Secara Cepat (Quick Structural Evaluation), and Pemeriksaan terinci (Detailed Assessment).
2014, No.1424 24 a) Pemeriksaan Visual Secara Cepat (Rapid Visual Screening) Penilaian Cepat Secara Visual merupakan tahap pertama pemeriksaan kerentanan bangunan secara cepat yang dilakukan dengan tujuan menetapkan bangunan–bangunan berisiko.
Pemeriksaan visual terdiri dari pemeriksaan terhadap konfigurasi bangunan berdasarkan tata letak bangunan dan konfigurasinya, termasuk alur pembebanan, lantai lemah (weak story), lantai lunak (soft story), bentuk geometri, massa efektif, torsi, dan benturan.', 'Lampiran hal. 23', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8253, 'perka-4-2012', 42, 'lampiran', 'Lampiran hal. 24', NULL, 24, 'Hasil pemeriksaan akan membantu pelaksanaan analisis struktural secara detail. Keluaran pemeriksaan visual adalah penentuan bangunan dengan pengelompokan: rentan dan tidak rentan. Dokumentasi hasil pengamatan visual menjadi dasar bagi pemeriksaan struktural selanjutnya. b) Pemeriksaan Struktur Secara Cepat (Quick Structural Evaluation) Ketika sebuah bangunan diidentifikasikan sebagai bangunan yang berisiko melalui Penilaian Cepat Secara Visual, hal itu berlanjut pada prosedur perhitungan kedua, yaitu Evaluasi Struktur Secara Cepat. Evaluasi ini meliputi pemeriksaan kekuatan secara umum terkait dengan aspek desain struktur seperti geser dan tegangan aksial pada elemen vertikal penahan beban gempa. c) Pemeriksaan Terinci (Detailed Assessment).
Selanjutnya, ketika bangunan diidentifikasikan berisiko melalui Evaluasi Struktur Secara Cepat, maka dilakukan pemeriksaan tahap berikutnya dengan Pemeriksaan Rinci. Pemeriksaan ini merupakan evaluasi yang kuantitatif dan akurat terhadap bangunan yang berisiko. Pemeriksaan Rinci termasuk perhitungan secara detail mengenai sistem struktur pemikul beban gempa, begitu pula pada elemen-elemen non-struktural (sebagai contoh, isi bangunan, elemen-elemen arsitektur dan elemen–elemen yang tidak tahan terhadap beban gempa).
2) Klasifikasi Hasil Pemeriksaan Klasifikasi Pemerikasaan mengacu pada Pedoman Teknis Rumah dan Bangungan Gedung Tahan Gempa yang dikeluarkan oleh Kementerian PU Tahun 2006. Klasifikasi hasil pemeriksaan adalah sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8253, 'Hasil pemeriksaan akan membantu pelaksanaan analisis struktural secara detail. Keluaran pemeriksaan visual adalah penentuan bangunan dengan pengelompokan: rentan dan tidak rentan. Dokumentasi hasil pengamatan visual menjadi dasar bagi pemeriksaan struktural selanjutnya. b) Pemeriksaan Struktur Secara Cepat (Quick Structural Evaluation) Ketika sebuah bangunan diidentifikasikan sebagai bangunan yang berisiko melalui Penilaian Cepat Secara Visual, hal itu berlanjut pada prosedur perhitungan kedua, yaitu Evaluasi Struktur Secara Cepat. Evaluasi ini meliputi pemeriksaan kekuatan secara umum terkait dengan aspek desain struktur seperti geser dan tegangan aksial pada elemen vertikal penahan beban gempa. c) Pemeriksaan Terinci (Detailed Assessment).
Selanjutnya, ketika bangunan diidentifikasikan berisiko melalui Evaluasi Struktur Secara Cepat, maka dilakukan pemeriksaan tahap berikutnya dengan Pemeriksaan Rinci. Pemeriksaan ini merupakan evaluasi yang kuantitatif dan akurat terhadap bangunan yang berisiko. Pemeriksaan Rinci termasuk perhitungan secara detail mengenai sistem struktur pemikul beban gempa, begitu pula pada elemen-elemen non-struktural (sebagai contoh, isi bangunan, elemen-elemen arsitektur dan elemen–elemen yang tidak tahan terhadap beban gempa).
2) Klasifikasi Hasil Pemeriksaan Klasifikasi Pemerikasaan mengacu pada Pedoman Teknis Rumah dan Bangungan Gedung Tahan Gempa yang dikeluarkan oleh Kementerian PU Tahun 2006. Klasifikasi hasil pemeriksaan adalah sebagai berikut:', 'Lampiran hal. 24', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8254, 'perka-4-2012', 43, 'lampiran', 'Lampiran hal. 25', NULL, 25, '25 2014, No.1424 a) Kerusakan Ringan Disebut rusak struktur tingkat ringan apabila terjadi hal-hal sebagai berikut:
- Retak kecil (lebar celah antara 0,075 hingga 0,6 cm) pada dinding;
- Plesteran berjatuhan;
- Mencakup luas yang besar;
- Kerusakan bagian-bagian nonstruktur seperti cerobong, lisplang, dsb;
- Kemampuan struktur untuk memikul beban tidak banyak berkurang;
- Masih layak fungsi/huni.
Tindakan yang perlu dilakukan adalah perbaikan yang bersifat arsitektur agar daya tahan bangunan tetap terpelihara.
Perbaikan dengan kerusakan ringan pada struktur dapat dilakukan tanpa mengosongkan bangunan. b) Kerusakan Sedang Disebut kerusakan sedang apabila terjadi hal-hal sebagai berikut:
- Retak besar (lebar celah lebih besar dari 0,6 cm) pada dinding;
- Retak menyebar luas di banyak tempat, seperti pada dinding pemikul beban, kolom; cerobong miring; dan runtuh;
- Kemampuan struktur untuk memikul beban sudah berkurang sebagian;
- Masih layak fungsi/huni.
Tindakan yang perlu dilakukan menentuan prioritas retrofitting atau perkuatan untuk menahan beban gempa; melakukan perbaikan secara arsitektur; dan bangunan dikosongkan serta dapat dihuni kembali setelah proses retrofitting selesai. c) Kerusakan Berat Disebut kerusakan berat apabila terjadi hal-hal sebagai berikut:
- Dinding pemikul beban terbelah dan runtuh;
- Bangunan terpisah akibat kegagalan unsur-unsur pengikat;
- Lebih dari 45% elemen utama mengalami kerusakan;
- Tidak layak fungsi/huni.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8254, '25 2014, No.1424 a) Kerusakan Ringan Disebut rusak struktur tingkat ringan apabila terjadi hal-hal sebagai berikut:
- Retak kecil (lebar celah antara 0,075 hingga 0,6 cm) pada dinding;
- Plesteran berjatuhan;
- Mencakup luas yang besar;
- Kerusakan bagian-bagian nonstruktur seperti cerobong, lisplang, dsb;
- Kemampuan struktur untuk memikul beban tidak banyak berkurang;
- Masih layak fungsi/huni.
Tindakan yang perlu dilakukan adalah perbaikan yang bersifat arsitektur agar daya tahan bangunan tetap terpelihara.
Perbaikan dengan kerusakan ringan pada struktur dapat dilakukan tanpa mengosongkan bangunan. b) Kerusakan Sedang Disebut kerusakan sedang apabila terjadi hal-hal sebagai berikut:
- Retak besar (lebar celah lebih besar dari 0,6 cm) pada dinding;
- Retak menyebar luas di banyak tempat, seperti pada dinding pemikul beban, kolom; cerobong miring; dan runtuh;
- Kemampuan struktur untuk memikul beban sudah berkurang sebagian;
- Masih layak fungsi/huni.
Tindakan yang perlu dilakukan menentuan prioritas retrofitting atau perkuatan untuk menahan beban gempa; melakukan perbaikan secara arsitektur; dan bangunan dikosongkan serta dapat dihuni kembali setelah proses retrofitting selesai. c) Kerusakan Berat Disebut kerusakan berat apabila terjadi hal-hal sebagai berikut:
- Dinding pemikul beban terbelah dan runtuh;
- Bangunan terpisah akibat kegagalan unsur-unsur pengikat;
- Lebih dari 45% elemen utama mengalami kerusakan;
- Tidak layak fungsi/huni.', 'Lampiran hal. 25', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8255, 'perka-4-2012', 44, 'lampiran', 'Lampiran hal. 26', NULL, 26, '2014, No.1424 26 Tindakan yang perlu dilakukan adalah merubuhkan bangunan atau dilakukan retrofitting (perkuatan) secara menyeluruh sebelum bangunan dihuni kembali. Dalam kondisi kerusakan seperti ini, bangunan menjadi sangat berbahaya sehingga harus dikosongkan. d) Kerusakan Total Disebut rusak total apabila terjadi hal-hal sebagai berikut:
- Bangunan roboh seluruhnya (> 65%)
- Sebagian besar komponen utama struktur rusak
- Tidak layak fungsi/ huni Tindakan yang perlu dilakukan adalah merubuhkan bangunan, membersihkan lokasi, dan mendirikan bangunan baru yang memenuhi standar aman dari bencana.
4.2. Kerangka Kerja Non Struktural
a. Pengertian Dalam pedoman ini yang dimaksud dengan kerangka kerja non struktural adalah adalah upaya mengurangi risiko bencana yang tidak melibatkan konstruksi fisik. Termasuk disini bisa berupa upaya pembuatan kebijakan seperti pembuatan suatu peraturan, legislasi, kampanye penyadaran masyarakat, membangun sikap dan tindakan kesiapsiagaan kepada seluruh warga sekolah/ madrasah dalam menghadapi bencana, yaitu penyiapan sumber daya manusia melalui pendidikan dan pelatihan.
b. Aspek Mendasar 1) Pengetahuan, Sikap dan Tindakan Dasar dari setiap sikap dan tindakan manusia adalah adanya persepsi, pengetahuan dan keterampilan yang dimilikinya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8255, '2014, No.1424 26 Tindakan yang perlu dilakukan adalah merubuhkan bangunan atau dilakukan retrofitting (perkuatan) secara menyeluruh sebelum bangunan dihuni kembali. Dalam kondisi kerusakan seperti ini, bangunan menjadi sangat berbahaya sehingga harus dikosongkan. d) Kerusakan Total Disebut rusak total apabila terjadi hal-hal sebagai berikut:
- Bangunan roboh seluruhnya (> 65%)
- Sebagian besar komponen utama struktur rusak
- Tidak layak fungsi/ huni Tindakan yang perlu dilakukan adalah merubuhkan bangunan, membersihkan lokasi, dan mendirikan bangunan baru yang memenuhi standar aman dari bencana.
4.2. Kerangka Kerja Non Struktural
a. Pengertian Dalam pedoman ini yang dimaksud dengan kerangka kerja non struktural adalah adalah upaya mengurangi risiko bencana yang tidak melibatkan konstruksi fisik. Termasuk disini bisa berupa upaya pembuatan kebijakan seperti pembuatan suatu peraturan, legislasi, kampanye penyadaran masyarakat, membangun sikap dan tindakan kesiapsiagaan kepada seluruh warga sekolah/ madrasah dalam menghadapi bencana, yaitu penyiapan sumber daya manusia melalui pendidikan dan pelatihan.
b. Aspek Mendasar 1) Pengetahuan, Sikap dan Tindakan Dasar dari setiap sikap dan tindakan manusia adalah adanya persepsi, pengetahuan dan keterampilan yang dimilikinya.', 'Lampiran hal. 26', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8256, 'perka-4-2012', 45, 'lampiran', 'Lampiran hal. 26', NULL, 26, 'Sekolah/Madrasah Aman dari Bencana ingin membangun kemampuan seluruh warga. sekolah/madrasah, baik individu maupun warga sekolah/madrasah secara kolektif, untuk menghadapi bencana secara cepat dan tepat guna. Dengan demikian, seluruh warga sekolah/madrasah menjadi target sasaran termasuk anak.
27 2014, No.1424 2) Kebijakan Sekolah/Madrasah Kebijakan sekolah/madrasah adalah keputusan yang dibuat secara formal oleh sekolah/madrasah mengenai hal-hal yang perlu didukung dalam pelaksanaan Penerapan sekolah/ Madrasah Aman dari Bencana, baik secara khusus maupun terpadu. Keputusan tersebut bersifat mengikat. Pada praktiknya, kebijakan sekolah/Madrasah akan landasan, panduan, arahan pelaksanaan kegiatan terkait dengan Penerapan Sekolah/Madrasah Aman dari Bencana.
3) Perencanaan Kesiapsiagaan Perencanaan kesiapsiaagaan bertujuan untuk menjamin adanya tindakan cepat dan tepat guna pada saat terjadi bencana dengan memadukan dan mempertimbangkan sistem penanggulangan bencana di daerah dan disesuaikan kondisi wilayah setempat. Bentuk atau produk dari perencanaan ini adalah dokumen-dokumen, seperti protap kesiapsiagaan, rencana kedaruratan/kontinjensi, dan dokumen pendukung kesiapsiagaan terkait, termasuk sistem peringatan dini yang disusun dengan mempertimbangkan akurasi dan kontektualitas lokal.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8256, 'Sekolah/Madrasah Aman dari Bencana ingin membangun kemampuan seluruh warga. sekolah/madrasah, baik individu maupun warga sekolah/madrasah secara kolektif, untuk menghadapi bencana secara cepat dan tepat guna. Dengan demikian, seluruh warga sekolah/madrasah menjadi target sasaran termasuk anak.
27 2014, No.1424 2) Kebijakan Sekolah/Madrasah Kebijakan sekolah/madrasah adalah keputusan yang dibuat secara formal oleh sekolah/madrasah mengenai hal-hal yang perlu didukung dalam pelaksanaan Penerapan sekolah/ Madrasah Aman dari Bencana, baik secara khusus maupun terpadu. Keputusan tersebut bersifat mengikat. Pada praktiknya, kebijakan sekolah/Madrasah akan landasan, panduan, arahan pelaksanaan kegiatan terkait dengan Penerapan Sekolah/Madrasah Aman dari Bencana.
3) Perencanaan Kesiapsiagaan Perencanaan kesiapsiaagaan bertujuan untuk menjamin adanya tindakan cepat dan tepat guna pada saat terjadi bencana dengan memadukan dan mempertimbangkan sistem penanggulangan bencana di daerah dan disesuaikan kondisi wilayah setempat. Bentuk atau produk dari perencanaan ini adalah dokumen-dokumen, seperti protap kesiapsiagaan, rencana kedaruratan/kontinjensi, dan dokumen pendukung kesiapsiagaan terkait, termasuk sistem peringatan dini yang disusun dengan mempertimbangkan akurasi dan kontektualitas lokal.', 'Lampiran hal. 26', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8257, 'perka-4-2012', 46, 'lampiran', 'Lampiran hal. 27', NULL, 27, '4) Mobilisasi Sumberdaya Sekolah/madrasah harus menyiapkan sumber daya manusia, sarana, dan prasarana, serta finansial dalam pengelolaan untuk menjamin kesiapsiagaan bencana sekolah. Mobilisasi sumber daya didasarkan pada kemampuan sekolah/madrasah dan pemangku kepentingan sekolah/madrasah. Mobilisasi ini juga terbuka bagi peluang partisipasi dari para pemangku kepentingan lainnya.
Keempat parameter di atas adalah perangkat pengukuran kesiapsiagaan bencana di sekolah/madrasah yang dirumuskan multipihak. Dalam pengukuran, masing- masing parameter itu tidak berdiri sendiri, melainkan saling terkait satu sama lainnya. Dari ukuran yang didapat dari sekolahmadrasah terkait, dapat diketahui mengenai tingkat ketahanan sekolah/madrasah terhadap ancaman bencana tertentu. Dalam praktiknya, kesiapsiagaan sekolah/madrasah juga dipadukan dengan upaya kesiapsiagaan aparat pemerintah dan masyarakat di daerah atau lingkungan terdekat sekolah/madrasah.
c. Penilaian non struktural Secara garis besar penilaian non struktural dalam Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana berupa parameter, indikator, dan penilaian adalah sebagai berikut:');
