INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8264, 'perka-4-2012', 53, 'lampiran', 'Lampiran hal. 35', NULL, 35, '1. Undang-Undang Nomor 15 Tahun 2004 tentang Pemeriksaan, Pengelolaan dan Tanggung Jawab Keuangan Negara.
2. Undang-Undang Nomor 25 Tahun 2004 tentang Sistem Perencanaan Pembangunan Nasional.
3. Peraturan Pemerintah Nomor 2 Tahun 2006 tentang Tata Cara Pengadaan Pinjaman dan/atau Penerimaan Hibah Serta Penerusan Pinjaman dan/atau Hibah Luar Negeri.
4. Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Pelaporan Keuangan dan Kinerja Instansi Pemerintah.
5. Peraturan Pemerintah Nomor 39 Tahun 2006 tentang Tata Cara Pengendalian dan Evaluasi Pelaksanaan Rencana Pembangunan.
6. Surat Keputusan Bersama Menteri Keuangan dan Menteri Negara PPN/Kepala Bappenas No. Kep-102/Mk.2/2002 dan No. Kep.
292/M.Ppn/09/2002 tentang Sistem Pemantauan dan Pelaporan Pelaksanaan Proyek Pembangunan.
5.1. Pemantauan Pemantauan yang dimaksud adalah kegiatan mengamati perkembangan pelaksanaan penerapan sekolah/madrasah aman dari bencana dan mengidentifikasi serta mengantisipasi permasalahan yang timbul agar dapat diambil tindakan sedini mungkin. Pemantauan dilakukan terhadap perkembangan realisasi penyerapan dana, realisasi pencapaian target keluaran (output) dan kendala yang dihadapi. Pemantauan harus dilakukan secara berkala untuk mendapatkan informasi akurat tentang pelaksanaan kegiatan, kinerja program serta hasil-hasil yang dicapai.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8264, '1. Undang-Undang Nomor 15 Tahun 2004 tentang Pemeriksaan, Pengelolaan dan Tanggung Jawab Keuangan Negara.
2. Undang-Undang Nomor 25 Tahun 2004 tentang Sistem Perencanaan Pembangunan Nasional.
3. Peraturan Pemerintah Nomor 2 Tahun 2006 tentang Tata Cara Pengadaan Pinjaman dan/atau Penerimaan Hibah Serta Penerusan Pinjaman dan/atau Hibah Luar Negeri.
4. Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Pelaporan Keuangan dan Kinerja Instansi Pemerintah.
5. Peraturan Pemerintah Nomor 39 Tahun 2006 tentang Tata Cara Pengendalian dan Evaluasi Pelaksanaan Rencana Pembangunan.
6. Surat Keputusan Bersama Menteri Keuangan dan Menteri Negara PPN/Kepala Bappenas No. Kep-102/Mk.2/2002 dan No. Kep.
292/M.Ppn/09/2002 tentang Sistem Pemantauan dan Pelaporan Pelaksanaan Proyek Pembangunan.
5.1. Pemantauan Pemantauan yang dimaksud adalah kegiatan mengamati perkembangan pelaksanaan penerapan sekolah/madrasah aman dari bencana dan mengidentifikasi serta mengantisipasi permasalahan yang timbul agar dapat diambil tindakan sedini mungkin. Pemantauan dilakukan terhadap perkembangan realisasi penyerapan dana, realisasi pencapaian target keluaran (output) dan kendala yang dihadapi. Pemantauan harus dilakukan secara berkala untuk mendapatkan informasi akurat tentang pelaksanaan kegiatan, kinerja program serta hasil-hasil yang dicapai.', 'Lampiran hal. 35', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8265, 'perka-4-2012', 54, 'lampiran', 'Lampiran hal. 35', NULL, 35, 'Selain untuk menemukan dan menyelesaikan kendala yang dihadapi, kegiatan ini juga berguna untuk meningkatkan efisiensi dan efektivitas pelaksanaan penerapan sekolah/madrasah aman dari bencana serta mendorong transparansi dan akuntabilitas dalam pelaksanaan kegiatan-kegiatan pengurangan risiko bencana.
2014, No.1424 36 Pelaksanaan pemantauan (dan juga evaluasi) dilaksanakan dengan memperhatikan asas Efisiensi, yakni derajat hubungan antara barang/jasa yang dihasilkan melalui suatu program/kegiatan dan sumber daya yang diperlukan untuk menghasilkan barang/jasa tersebut yang diukur dengan biaya per unit keluaran (output); Efektivitas, yakni tingkat seberapa jauh program/kegiatan mencapai hasil dan manfaat yang diharapkan; dan Kemanfaatan, yaitu kondisi yang diharapkan akan dicapai bila keluaran (output) dapat diselesaikan tepat waktu, tepat lokasi dan tepat sasaran serta berfungsi dengan optimal. Selain ketiga asas tersebut, pelaksanaan pemantauan sebaiknya juga menilai aspek Konsistensi, Koordinasi, Konsultasi, Kapasitas dan Keberlanjutan dari pelaksanaan suatu rencana program/kegiatan.
Secara umum, target pemantauan penerapan sekolah/madrasah aman dari bencana adalah sebagai berikut:
(1) memantau efektivitas input (dana, SDM, waktu, dan sumberdaya lainnya), tatalaksana penyelenggaraan kegiatan, administrasi dan pengelolaan keuangan oleh sekolah/madrasah dalam rangka mencapai sasaran penerapan sekolah/madrasah aman dari bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8265, 'Selain untuk menemukan dan menyelesaikan kendala yang dihadapi, kegiatan ini juga berguna untuk meningkatkan efisiensi dan efektivitas pelaksanaan penerapan sekolah/madrasah aman dari bencana serta mendorong transparansi dan akuntabilitas dalam pelaksanaan kegiatan-kegiatan pengurangan risiko bencana.
2014, No.1424 36 Pelaksanaan pemantauan (dan juga evaluasi) dilaksanakan dengan memperhatikan asas Efisiensi, yakni derajat hubungan antara barang/jasa yang dihasilkan melalui suatu program/kegiatan dan sumber daya yang diperlukan untuk menghasilkan barang/jasa tersebut yang diukur dengan biaya per unit keluaran (output); Efektivitas, yakni tingkat seberapa jauh program/kegiatan mencapai hasil dan manfaat yang diharapkan; dan Kemanfaatan, yaitu kondisi yang diharapkan akan dicapai bila keluaran (output) dapat diselesaikan tepat waktu, tepat lokasi dan tepat sasaran serta berfungsi dengan optimal. Selain ketiga asas tersebut, pelaksanaan pemantauan sebaiknya juga menilai aspek Konsistensi, Koordinasi, Konsultasi, Kapasitas dan Keberlanjutan dari pelaksanaan suatu rencana program/kegiatan.
Secara umum, target pemantauan penerapan sekolah/madrasah aman dari bencana adalah sebagai berikut:
(1) memantau efektivitas input (dana, SDM, waktu, dan sumberdaya lainnya), tatalaksana penyelenggaraan kegiatan, administrasi dan pengelolaan keuangan oleh sekolah/madrasah dalam rangka mencapai sasaran penerapan sekolah/madrasah aman dari bencana', 'Lampiran hal. 35', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8266, 'perka-4-2012', 55, 'lampiran', 'Lampiran hal. 36', NULL, 36, '(2) memantau kinerja organisasi pelaksana penerapan sekolah/madrasah aman dari bencana
(3) memantau proses dan hasil pelaksanaan penerapan sekolah/madrasah aman dari bencana berdasarkan aspek dan kerangka kerja sekolah aman, meliputi: proses sosialisasi program, proses penilaian proposal, proses pengolahan data, penentuan urutan prioritas sekolah calon penerima program, pelaksanaan dan pemanfaatan program.
(4) memantau pemanfaatan sarana-prasarana sekolah/madrasah yang telah diperbaiki sesuai fungsinya disesuaikan dengan desain dan penataan sekolah/madrasah aman.
(5) memantau kegiatan pemenuhan indikator sekolah/madrasah aman dari baik struktural maupun non- struktural di tingkat sekolah/madrasah
(6) mengidentifikasi kendala dalam penerapan sekolah/madrasah aman dari bencana
(7) terkumpulnya data yang menyeluruh tentang kegiatan sekolah/madrasah aman dari bencana baik data kegiatan struktural maupun non struktural.
5.2. Evaluasi Evaluasi akan menilai aspek-aspek penerapan sekolah/madrasah aman sesuai dengan indikator sekolah/madrasah aman dari bencana baik struktural maupun non struktural sehingga dapat mengkategorikan tingkat amannya bagi setiap sekolah/madrasah terhadap gempa bumi dan/atau tsunami yang meliputi:
37 2014, No.1424
(1) Penilaian tingkat pemenuhan perencanaan dengan pelaksanaan penerapan sekolah/madrasah aman dari bencana serta kegiatan non-struktural.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8266, '(2) memantau kinerja organisasi pelaksana penerapan sekolah/madrasah aman dari bencana
(3) memantau proses dan hasil pelaksanaan penerapan sekolah/madrasah aman dari bencana berdasarkan aspek dan kerangka kerja sekolah aman, meliputi: proses sosialisasi program, proses penilaian proposal, proses pengolahan data, penentuan urutan prioritas sekolah calon penerima program, pelaksanaan dan pemanfaatan program.
(4) memantau pemanfaatan sarana-prasarana sekolah/madrasah yang telah diperbaiki sesuai fungsinya disesuaikan dengan desain dan penataan sekolah/madrasah aman.
(5) memantau kegiatan pemenuhan indikator sekolah/madrasah aman dari baik struktural maupun non- struktural di tingkat sekolah/madrasah
(6) mengidentifikasi kendala dalam penerapan sekolah/madrasah aman dari bencana
(7) terkumpulnya data yang menyeluruh tentang kegiatan sekolah/madrasah aman dari bencana baik data kegiatan struktural maupun non struktural.
5.2. Evaluasi Evaluasi akan menilai aspek-aspek penerapan sekolah/madrasah aman sesuai dengan indikator sekolah/madrasah aman dari bencana baik struktural maupun non struktural sehingga dapat mengkategorikan tingkat amannya bagi setiap sekolah/madrasah terhadap gempa bumi dan/atau tsunami yang meliputi:
37 2014, No.1424
(1) Penilaian tingkat pemenuhan perencanaan dengan pelaksanaan penerapan sekolah/madrasah aman dari bencana serta kegiatan non-struktural.', 'Lampiran hal. 36', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8267, 'perka-4-2012', 56, 'lampiran', 'Lampiran hal. 37', NULL, 37, '(2) Penilaian penerapan aspek dan kerangka kerja sekolah/madrasah aman dalam pelaksanaan rehabilitasi dan rekonstruksi sekolah/madrasah meliputi:
(a) Proses sosialisasi program,
(b) Proses penilaian proposal,
(c) Proses pengolahan data,
(d) Penentuan urutan prioritas sekolah calon penerima program,
(e) Pelaksanaan dan pemanfaatan program
(3) Penilaian setiap sekolah/madrasah dalam memenuhi indikator sekolah/madrasah aman dari bencana dan melakukan kategorisasi dengan perincian sbb:
Kategori 1: Memenuhi salah satu aspek yang mendasar dan parameter sekolah/madrasah aman dari bencana.
Kategori 2: Memenuhi lebih dari dua aspek yang mendasar dan parameter sekolah/ madrasah aman dari bencana.
Kategori 3: Memenuhi seluruh aspek yang mendasar dan parameter sekolah/madrasah aman dari bencana.
5.3. Pelaporan Pelaksanaan penerapan sekolah/madrasah aman dari bencana harus dilaporkan dalam sebuah laporan tertulis. Pelaporan yang mencakup hasil pemantauan dan evaluasi penerapan sekolah/madrasah aman dari bencana baik kemajuan dan capaian fisik maupun penggunaan dana, yang disampaikan secara berkala dan dilaksanakan secara berjenjang mulai dari laporan panitia tingkat sekolah, kepala sekolah, laporan masing-masing SKPD terkait, laporan kabupaten/kota, laporan provinsi dan laporan pusat dan disusun serta diserahkan secara berkala sesuai dengan ketentuan yang berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8267, '(2) Penilaian penerapan aspek dan kerangka kerja sekolah/madrasah aman dalam pelaksanaan rehabilitasi dan rekonstruksi sekolah/madrasah meliputi:
(a) Proses sosialisasi program,
(b) Proses penilaian proposal,
(c) Proses pengolahan data,
(d) Penentuan urutan prioritas sekolah calon penerima program,
(e) Pelaksanaan dan pemanfaatan program
(3) Penilaian setiap sekolah/madrasah dalam memenuhi indikator sekolah/madrasah aman dari bencana dan melakukan kategorisasi dengan perincian sbb:
Kategori 1: Memenuhi salah satu aspek yang mendasar dan parameter sekolah/madrasah aman dari bencana.
Kategori 2: Memenuhi lebih dari dua aspek yang mendasar dan parameter sekolah/ madrasah aman dari bencana.
Kategori 3: Memenuhi seluruh aspek yang mendasar dan parameter sekolah/madrasah aman dari bencana.
5.3. Pelaporan Pelaksanaan penerapan sekolah/madrasah aman dari bencana harus dilaporkan dalam sebuah laporan tertulis. Pelaporan yang mencakup hasil pemantauan dan evaluasi penerapan sekolah/madrasah aman dari bencana baik kemajuan dan capaian fisik maupun penggunaan dana, yang disampaikan secara berkala dan dilaksanakan secara berjenjang mulai dari laporan panitia tingkat sekolah, kepala sekolah, laporan masing-masing SKPD terkait, laporan kabupaten/kota, laporan provinsi dan laporan pusat dan disusun serta diserahkan secara berkala sesuai dengan ketentuan yang berlaku.', 'Lampiran hal. 37', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8268, 'perka-4-2012', 57, 'lampiran', 'Lampiran hal. 37', NULL, 37, 'Pelaporan bertujuan sebagai pertanggungjawaban dari kegiatan penerapan sekolah/madrasah aman dari bencana baik secara formal maupun sebagai pertanggungjawaban kepada publik. Pelaporan penerapan sekolah/madrasah aman dari bencana di tingkat pusat dikoordinasikan oleh BNPB melalui suatu tim yang dibentuk bersama dengan Kementerian Pendidikan dan Kebudayaan, Kementerian Agama, Kementerian Pekerjaan Umum, Kementerian Dalam Negeri dan Kementerian Keuangan, serta dibantu oleh profesional dan unsur masyarakat madani. Hal ini juga berlaku di daerah dimana BPBD Provinsi/Kabupaten/Kota 2014, No.1424 38 mengkoordinasikan melalui suatu tim. Pembentukan tim ini sesuai Juknis yang disepakati antara Badan Nasional Penanggulangan Bencana, Kementerian Pendidikan dan Kebudayaan, Kementerian Agama, Kementerian Pekerjaan Umum, dan Kementerian Dalam Negeri.
39 2014, No.1424 BAB VI PENUTUP Pedoman ini disusun dengan harapan semua pemangku kepentingan yang terkait dengan pelaksanaan penerapan sekolah/madrasah Aman dari bencana mendapatkan acuan yang jelas. Keterlibatan aktif para pemangku kepentingan termasuk anak menjadi bagian penting dalam pelaksanaan pedoman ini.
Masukan dan perbaikan terhadap isi dari pedoman ini sangat diharapkan guna mewujudkan sekolah/madrasah aman dalam pemenuhan hak pendidikan dan perlindungan anak di Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8268, 'Pelaporan bertujuan sebagai pertanggungjawaban dari kegiatan penerapan sekolah/madrasah aman dari bencana baik secara formal maupun sebagai pertanggungjawaban kepada publik. Pelaporan penerapan sekolah/madrasah aman dari bencana di tingkat pusat dikoordinasikan oleh BNPB melalui suatu tim yang dibentuk bersama dengan Kementerian Pendidikan dan Kebudayaan, Kementerian Agama, Kementerian Pekerjaan Umum, Kementerian Dalam Negeri dan Kementerian Keuangan, serta dibantu oleh profesional dan unsur masyarakat madani. Hal ini juga berlaku di daerah dimana BPBD Provinsi/Kabupaten/Kota 2014, No.1424 38 mengkoordinasikan melalui suatu tim. Pembentukan tim ini sesuai Juknis yang disepakati antara Badan Nasional Penanggulangan Bencana, Kementerian Pendidikan dan Kebudayaan, Kementerian Agama, Kementerian Pekerjaan Umum, dan Kementerian Dalam Negeri.
39 2014, No.1424 BAB VI PENUTUP Pedoman ini disusun dengan harapan semua pemangku kepentingan yang terkait dengan pelaksanaan penerapan sekolah/madrasah Aman dari bencana mendapatkan acuan yang jelas. Keterlibatan aktif para pemangku kepentingan termasuk anak menjadi bagian penting dalam pelaksanaan pedoman ini.
Masukan dan perbaikan terhadap isi dari pedoman ini sangat diharapkan guna mewujudkan sekolah/madrasah aman dalam pemenuhan hak pendidikan dan perlindungan anak di Indonesia.', 'Lampiran hal. 37', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8269, 'perka-4-2012', 58, 'lampiran', 'Lampiran hal. 39', NULL, 39, 'KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF 2014, No.1424 40 Parameter Indikator Penilaian Pengetahuan, Tersedianya e Struktur dan Sikap dan pengetahuan Muatan Kurikulum Tindakan mengenai bahaya | memuat (jenis bahaya), pengetahuan Kerentanan, mengenai Bahaya Kapasitas, Risiko | (jenis, sumber dan sejarah bahaya dan besaran bencana yang bahaya), terjadi Kerentanan, dilingkungan Kapasitas, Risiko sekolah atau dan Sejarah yang daerahnya terjadi di lingkungan sekolah/madrasah atau daerahnya. e Kegiatan sekolah/madrasah bagi peserta didik untuk mengobservasi Bahaya (jenis bahaya, sumber bahaya dan besaran bahaya), Kerentanan, Kapasitas dan Risiko yang ada di lingkungan sekolah/madrasah, termasuk yang bersumber pada lokasi dan infrastruktur sekolah/madrasah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8269, 'KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF 2014, No.1424 40 Parameter Indikator Penilaian Pengetahuan, Tersedianya e Struktur dan Sikap dan pengetahuan Muatan Kurikulum Tindakan mengenai bahaya | memuat (jenis bahaya), pengetahuan Kerentanan, mengenai Bahaya Kapasitas, Risiko | (jenis, sumber dan sejarah bahaya dan besaran bencana yang bahaya), terjadi Kerentanan, dilingkungan Kapasitas, Risiko sekolah atau dan Sejarah yang daerahnya terjadi di lingkungan sekolah/madrasah atau daerahnya. e Kegiatan sekolah/madrasah bagi peserta didik untuk mengobservasi Bahaya (jenis bahaya, sumber bahaya dan besaran bahaya), Kerentanan, Kapasitas dan Risiko yang ada di lingkungan sekolah/madrasah, termasuk yang bersumber pada lokasi dan infrastruktur sekolah/madrasah.', 'Lampiran hal. 39', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8270, 'perka-4-2012', 59, 'lampiran', 'Lampiran hal. 41', NULL, 41, '41 2014, No.1424 Parameter Indikator Penilaian Tersedianya e Struktur dan Muatan pengetahuan Kurikulum yang mengenai upaya memuat pengetahuan yang bias mengenai upaya yang dilakukan untuk bisa dilakukan untuk mengurangi risiko mengurangi risiko bencana di bencana di sekolah/madrasah | sekolah/madrasah. e Kegiatan sekolah/madrasah untuk mengidentifikasi upaya yang bias mengurangi risiko bencana Sekolah/madrasah secara berkala melakukan penilaian kerentanan sekolah/madrasah Keterampilan (Warga warga sekolah/madrasah sekolah/madrasah (termasuk anak termasuk anak Imenjalankan simulasi dalam menerapkan (rencana kesiapsiagaan rencana aksi Ipada saat simulasi. sekolah/madrasah aman Terlaksananya Laporan Simulasi sosialisasi Jumlah sosialisasi rutin mengenai dan berkelanjutan di pengetahuan PRB, sekolah/madrasah. sekolah/madrasah Aman dari bencana dan kesiapsiagaan kepada warga sekolah/madrasah termasuk anak.
