INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8290, 'KABUPATEN/ KOTA PROVINSI KEDATANGAN MAKSIMUM TSUNAMI (menit) (METER) 150 Halmahera Selatan Malut 8 6 151 Halmahera Utara Malut 5 22 152 Halmahera Timur Malut 7 22 153 Kota Ternate Malut 13 16 154 Kota Tidore Malut 8 19 155 Fak Fak Papua Brt 2 17 156 Kaimana Papua Brt 1 54 157 Manokwari Papua Brt 8 5 158 Sorong Papua Brt 7 25 159 Raja Ampat Papua Brt 6 15 160 Kota Sorong Papua Brt 5 37 161 Teluk Bintuni Papua Brt 2 17 162 Teluk Wondama Papua Brt 5 30 163 Jayapura Papua 6 16 164 Nabire Papua 4 31 165 Yapen Papua 6 5 166 Waropen Papua 6 16 167 Biak Numfor Papua 7 14 168 Sarmi Papua 10 12 169 Mimika Papua 1 60 170 Mappi Papua 1 90 171 Merauke Papua 1 90 172 Kota Jayapura Papua 6 17 Sumber : Tsunami Risk Assessment, 2012 (BNPB) 2014, No.1424 68 Lampiran – 03 Perangkat Pemeriksaan Kerentanan Bangunan Sekolah1 Nama sekolah :
Nama bangunan :
Alamat sekolah :
1Diadopsi dari surat lampiran rekomendasi kepala BNPB kepada Kemendikbud melalui wakil menteri bidang pendidikan per tanggal 18 Pebruari 2011 mengenai Panduan Teknis Rehabilitasi Sekolah 69 2014, No.1424 Penjelasan Pengisian Formulir Pemeriksaan oleh Sekolah Dalam formulir pemeriksaan ini, ada 2 Aspek yang periksa, yaitu', 'Lampiran hal. 47', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8291, 'perka-4-2012', 80, 'lampiran', 'Lampiran hal. 69', NULL, 69, '1. Aspek sarana dan Prasarana Sekolah/madrasah Dalam aspek ada 6 kategori isian yang harus diisi oleh guru maupun komunitas sekolah. Kategori tersebut antara lain informasi umum dari sekolah, kondisi dan perencanaan sekolah, komponen struktural, komponen arsitektural, perabotan dan isinya, utilitas dan sekitarnya dan.
Untuk membantu pemeriksa memahami apa saja komponen struktural, beberapa gambar mengenai komponen-komponen bangunan telah diberikan.
Cara mengisi lembar pemeriksaan ini adalah sebagai berikut:
a. Kategori pertama Informasi Umum (1xx) diisi sesuai dengan data-data pemeriksa, deskripsi data bangunan dan kondisi sekolaah terhadap paparan bencana.
b. Kategori kedua kondisi dan perencanaan (2xx) dipilih menggunakan tanda centang (√) pada gambar yang sesuai dengan kondisi bangunan
c. Kategori ketiga sampai keenam (3xx-6xx) menggunakan tanda centang (√) “ya” atau “tidak” dalam pemeriksaannya');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8291, '1. Aspek sarana dan Prasarana Sekolah/madrasah Dalam aspek ada 6 kategori isian yang harus diisi oleh guru maupun komunitas sekolah. Kategori tersebut antara lain informasi umum dari sekolah, kondisi dan perencanaan sekolah, komponen struktural, komponen arsitektural, perabotan dan isinya, utilitas dan sekitarnya dan.
Untuk membantu pemeriksa memahami apa saja komponen struktural, beberapa gambar mengenai komponen-komponen bangunan telah diberikan.
Cara mengisi lembar pemeriksaan ini adalah sebagai berikut:
a. Kategori pertama Informasi Umum (1xx) diisi sesuai dengan data-data pemeriksa, deskripsi data bangunan dan kondisi sekolaah terhadap paparan bencana.
b. Kategori kedua kondisi dan perencanaan (2xx) dipilih menggunakan tanda centang (√) pada gambar yang sesuai dengan kondisi bangunan
c. Kategori ketiga sampai keenam (3xx-6xx) menggunakan tanda centang (√) “ya” atau “tidak” dalam pemeriksaannya', 'Lampiran hal. 69', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2012 tentang Pedoman Penerapan Sekolah/Madrasah Aman dari Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8292, 'perka-4-2012', 81, 'lampiran', 'Lampiran hal. 69', NULL, 69, 'd. Kategori Kriteria ambang dibawah ini akan membantu pemeriksa atau pengambil kebijakan dalam membuat rekomendasi.  Jika nilai dari isian kedua (kondisi dan perencanaan/2xx) melebihi 4, disarankan bahwa gedung tersebut perlu pemeriksaan lebih lanjut oleh ahli bangunan.  Jika jumlah jawaban “tidak” pada isian ketiga (komponen struktural/3xx) melebihi 1, sangat disarankan gedung tersebut untuk diperiksa lebih lanjut oleh ahli bangunan.  Jika jumlah jawaban “tidak” pada isian keempat (komponen arsitektural/4xx) melebihi 5 disarankan bahwa gedung tersebut perlu perbaikan komponen arsitektural.  Jika jumlah jawaban “tidak” pada isian kelima (perabotan dan isinya/5xx) melebihi 10 sangat disarankan bahwa gedung tersebut perlu perkuatan pada perabotan dan isinya. Apabila nilainya dibawah 11, perkuatan cukup dilakukan oleh guru atau komunitas sekolah.  Jika jumlah jawaban “tidak” pada isian keenam (utilitas dan sekitarnya/6xx) melebihi 3 sangat disarankan gedung tersebut 2014, No.1424 70 memerlukan bantuan teknis untuk perkuatan komponen tersebut oleh ahli bangunan.
Semua ambang tersebut dapat diabaikan, jika dengan pengetahuan dari pemeriksa, ada beberapa hal kritis yang harus segera diperbaiki/diperkuat, walaupun belum melampaui batasan ambang tersebut. Dalam kasus ini, mohon diberikan catatan yang disertai dengan gambar-gambar dokumentasi (jika tersedia).
Catatan:');
