INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8309, 'perka-4-2013', 5, 'pasal', 'Pasal 2', NULL, 3, 'Petunjuk Teknis sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian yang tidak terpisahkan dari peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8309, 'Petunjuk Teknis sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian yang tidak terpisahkan dari peraturan ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2013 tentang Petunjuk Teknis Rehabilitasi dan Rekonstruksi Pascabencana Sektor Pemukiman');
