INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8310, 'Petunjuk Teknis Rehabilitasi dan Rekonstruksi Pascabencana Sektor Permukiman disusun dengan sistematika sebagai berikut:
SEKTOR PERMUKIMAN', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2013 tentang Petunjuk Teknis Rehabilitasi dan Rekonstruksi Pascabencana Sektor Pemukiman');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8311, 'perka-4-2013', 7, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'LAMPIRAN Pasal 4 Dengan dikeluarkannya peraturan ini, maka Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2012 tentang Petunjuk Teknis Rehabilitasi dan Rekonstruksi Pascabencana serta Permukiman Wilayah Kabupaten Kepulauan Mentawai Tahun 2011-2013 dan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2012 tentang Petunjuk Teknis Pembangunan Sektor Permukiman Pasacbencana Erupsi Gunung Merapi 2010 dan Banjir Lahar di Provinsi Daerah Istimewa Yogyakarta dan Provinsi Jawa Tengah dicabut dan dinyatakan tidak berlaku.
Pasal 5 Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal diundangkan.
2013, No.1329 4 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8311, 'LAMPIRAN Pasal 4 Dengan dikeluarkannya peraturan ini, maka Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2012 tentang Petunjuk Teknis Rehabilitasi dan Rekonstruksi Pascabencana serta Permukiman Wilayah Kabupaten Kepulauan Mentawai Tahun 2011-2013 dan Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2012 tentang Petunjuk Teknis Pembangunan Sektor Permukiman Pasacbencana Erupsi Gunung Merapi 2010 dan Banjir Lahar di Provinsi Daerah Istimewa Yogyakarta dan Provinsi Jawa Tengah dicabut dan dinyatakan tidak berlaku.
Pasal 5 Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal diundangkan.
2013, No.1329 4 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2013 tentang Petunjuk Teknis Rehabilitasi dan Rekonstruksi Pascabencana Sektor Pemukiman');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8312, 'perka-4-2013', 8, 'lain', 'Penutup', NULL, 4, 'Ditetapkan di Jakarta pada tanggal 4 Oktober 2013 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 13 November 2013 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8312, 'Ditetapkan di Jakarta pada tanggal 4 Oktober 2013 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 13 November 2013 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2013 tentang Petunjuk Teknis Rehabilitasi dan Rekonstruksi Pascabencana Sektor Pemukiman');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8313, 'perka-4-2014', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8313, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8314, 'perka-4-2014', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka Pelaksanaan Daftar Isian Pelaksanaan Anggaran Badan Nasional Penanggulangan Bencana, tercapai persamaan persepsi, serta terwujudnya pertanggungjawaban pengelolaan keuangan yang transparan dan akuntabel diperlukan Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan atas beban Anggaran Pendapatan dan Belanja Negara di lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana 300, No.300 2 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara di lingkungan Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8314, 'a. bahwa dalam rangka Pelaksanaan Daftar Isian Pelaksanaan Anggaran Badan Nasional Penanggulangan Bencana, tercapai persamaan persepsi, serta terwujudnya pertanggungjawaban pengelolaan keuangan yang transparan dan akuntabel diperlukan Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan atas beban Anggaran Pendapatan dan Belanja Negara di lingkungan Badan Nasional Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana 300, No.300 2 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara di lingkungan Badan Nasional Penanggulangan Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8315, 'perka-4-2014', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Nomor 4286);
2. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);
3. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
4. Peraturan Pemerintah Nomor 6 Tahun 2006 tentang Pengelolaan Barang Milik Negara/Daerah (Lembaran Negara Republik Indonesia Tahun 2006 Nomor 20, Tambahan Lembaran Negara Republik Indonesia Nomor 4609) sebagimana telah diubah dengan Peraturan Pemerintah Nomor 38 Tahun 2008 (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 28, Tambahan Lembaran Negara Republik Indonesia Nomor 4855);
5. Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Pelaporan Keuangan dan Kinerja Instansi Pemerintah Lembaran Negara Indonesia Tahun 2006 Nomor 25, Tambahan Lembaran Negara Republik Indonesia Nomor 4614);
6. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
7. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
8. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing 3 2014, No.300 Non Pemerintah Dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
9 Peraturan Pemerintah Nomor 71 Tahun 2010 tentang Standar Akutansi Pemerintah (Lembaran Negara Republik Indonesia Tahun 2010 Nomor 123, Tambahan Lembaran Negara Republik Indonesia Nomor 5165);
10. Peraturan Pemerintah Nomor 45 Tahun 2013 tentang Tata Cara Pelaksanaan Anggaran Pendapatan dan Belanja Negara (Lembaran Negara Republik Indonesia Tahun 2013 Nomor 103, Tambahan Lembaran Negara Republik Indonesia Nomor 5423);
11. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
12. Peraturan Menteri Keuangan Nomor 171/PMK.05/2007 tentang Sistem Akuntansi dan Pelaporan Keuangan Pemerintah Pusat sebagaimana telah diubah dengan Peraturan Menteri Keuangan Nomor 233/PMK.05/2011, (Berita Negara Republik Indonesia Tahun 2011 Nomor 894);
13. Peraturan Menteri Keuangan Nomor 73/PMK.05/2008 tentang Tata Cara Penatausahaan dan Penyusunan Laporan Pertanggungjawaban Bendahara Kementerian/ Lembaga/Kantor/Satuan Kerja;
14. Peraturan Menteri Keuangan Nomor 113/PMK.05/2012 tentang Perjalanan Dinas Dalam Negeri bagi Pejabat Negara, Pegawai Negeri, dan Pegawai Tidak Tetap (Berita Negara Republik Indonesia Tahun 2012 Nomor 678);
15. Peraturan Menteri Keuangan Nomor 190/PMK.05/2012 tentang Tata Cara Pembayaran Dalam Rangka Pelaksanaan Anggaran Pendapatan dan Belanja Negara (Berita Negara Republik Indonesia Tahun 2012 Nomor 1191);
16. Peraturan Menteri Keuangan Nomor 105/PMK.05/2013 tentang Mekanisme Pelaksanaan Anggaran Penanggu-langan Bencana (Berita Negara Republik Indonesia Tahun 2013 Nomor 971);
300, No.300 4');
