INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8316, 'perka-4-2014', 3, 'menetapkan', 'Menetapkan', NULL, 4, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PETUNJUK PELAKSANAAN PENGELOLAAN DAN PERTANGGUNGJAWABAN KEUANGAN ATAS BEBAN ANGGARAN DAN PENDAPATAN BELANJA NEGARA DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8316, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PETUNJUK PELAKSANAAN PENGELOLAAN DAN PERTANGGUNGJAWABAN KEUANGAN ATAS BEBAN ANGGARAN DAN PENDAPATAN BELANJA NEGARA DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8317, 'perka-4-2014', 4, 'pasal', 'Pasal 1', NULL, 4, 'Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara di lingkungan Badan Nasional Penanggulangan Bencana, merupakan acuan pengelolaan keuangan pada Satuan Kerja Badan Nasional Penanggulangan Bencana yang melaksanakan program dan kegiatan penanggulangan bencana, baik pada tahap prabencana, dalam situasi terdapat potensi terjadi bencana, keadaan darurat bencana, dan pascabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8317, 'Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara di lingkungan Badan Nasional Penanggulangan Bencana, merupakan acuan pengelolaan keuangan pada Satuan Kerja Badan Nasional Penanggulangan Bencana yang melaksanakan program dan kegiatan penanggulangan bencana, baik pada tahap prabencana, dalam situasi terdapat potensi terjadi bencana, keadaan darurat bencana, dan pascabencana.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8318, 'perka-4-2014', 5, 'pasal', 'Pasal 2', NULL, 4, 'Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara di lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian yang tidak terpisahkan dari Peraturan Kepala ini.');
