INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8325, 'perka-4-2014', 12, 'lampiran', 'Lampiran hal. 8', NULL, 8, '9. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing non Pemerintah dalam Penanggulangan Bencana;
