INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8325, '9. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing non Pemerintah dalam Penanggulangan Bencana;
10. Peraturan Pemerintah Nomor 71 Tahun 2010 tentang Standar Akuntansi Pemerintah;
11. Peraturan Presiden Nomor 8 Tahun 2008 tentang BNPB;
12. Peraturan Menteri Keuangan Nomor 171/PMK.05/2007 tentang Sistem Akutansi dan Pelaporan Keuangan Pemerintah Pusat sebagaimana telah diubah dengan Peraturan Menteri Keuangan Nomor 233/PMK.05/2011;
13. Peraturan Menteri Keuangan Nomor 73/PMK.05/2008 tentang Tata Cara Penatausahaan dan Penyusunan Laporan Pertanggung-jawaban Bendahara Kementeriaan Negara/Lembaga/ Kantor/Satuan Kerja;
14. Peraturan Menteri Keuangan Nomor 113/PMK.05/2012 tentang Perjalanan Dinas Dalam Negeri Bagi Pejabat Negara, Pegawai Negeri, dan Pegawai Tidak Tetap;
15. Peraturan Menteri Keuangan Nomor 190/PMK.05/2012 tentang Tata Cara Pembayaran dalam Rangka Pelaksanaan Anggaran Pendapatan dan Belanja Negara;
16. Peraturan Menteri Keuangan Nomor 105/PMK.05/2013 tentang Mekanisme Pelaksanaan Anggaran Penanggulangan Bencana;
17. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja BNPB;
9 2014, No.300
18. Peraturan Direktur Jenderal Perbendaharaan Nomor PER- 47/PB/2009 tentang Petunjuk Pelaksanaan Penatausahaan dan Penyusunan Laporan Pertanggungjawaban Bendahara Kementeriaan Negara/Lembaga/ Kantor/Satuan Kerja;', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8326, 'perka-4-2014', 13, 'lampiran', 'Lampiran hal. 9', NULL, 9, '19. Peraturan Direktur Jenderal Perbendaharaan Nomor PER- 19/PB/2012 tentang Tatacara Pembayaran dan Pengembalian Uang Muka atas beban Anggaran Pendapatan dan Belanja Negara;
20. Peraturan Direktur Jenderal Perbendaharaan Nomor PER- 22/PB/2012 tentang Ketentuan Lebih Lanjut Pelaksanaan Perjalanan Dinas Dalam Negeri bagi Pejabat Negara,Pegawai Negeri, dan Pegawai Tidak Tetap;dan
21. Peraturan Direktur Jenderal Perbendaharaan Nomor PER- 57/PB/2013 tentang Pedoman Penyusunan Laporan Keuangan Kementerian Negara/Lembaga.
E. Pengertian
1. Anggaran Pendapatan dan Belanja Negara yang selanjutnya disingkat APBN adalah rencana keuangan tahunan pemerintahan negara yang disetujui oleh Dewan Perwakilan Rakyat.
2. Badan Nasional Penanggulangan Bencana yang selanjutnya dalam Peraturan Presiden ini disebut dengan BNPB adalah Lembaga Pemerintah Nondepartemen setingkat menteri sebagaimana dimaksud dalam Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
3. Daftar Isian Pelaksanaan Anggaran yang selanjutnya disebut DIPA adalah Dokumen Pelaksanaan Anggaran yang digunakan sebagai acuan Pengguna Anggaran dalam melaksanakan kegiatan pemerintahan sebagai pelaksanaan APBN.
4. Keuangan Negara adalah semua hak dan kewajiban negara yang dapat dinilai dengan uang, serta segala sesuatu baik berupa uang maupun berupa barang yang dapat dijadikan milik negara berhubung dengan pelaksanaan hak dan kewajiban tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8326, '19. Peraturan Direktur Jenderal Perbendaharaan Nomor PER- 19/PB/2012 tentang Tatacara Pembayaran dan Pengembalian Uang Muka atas beban Anggaran Pendapatan dan Belanja Negara;
20. Peraturan Direktur Jenderal Perbendaharaan Nomor PER- 22/PB/2012 tentang Ketentuan Lebih Lanjut Pelaksanaan Perjalanan Dinas Dalam Negeri bagi Pejabat Negara,Pegawai Negeri, dan Pegawai Tidak Tetap;dan
21. Peraturan Direktur Jenderal Perbendaharaan Nomor PER- 57/PB/2013 tentang Pedoman Penyusunan Laporan Keuangan Kementerian Negara/Lembaga.
E. Pengertian
1. Anggaran Pendapatan dan Belanja Negara yang selanjutnya disingkat APBN adalah rencana keuangan tahunan pemerintahan negara yang disetujui oleh Dewan Perwakilan Rakyat.
2. Badan Nasional Penanggulangan Bencana yang selanjutnya dalam Peraturan Presiden ini disebut dengan BNPB adalah Lembaga Pemerintah Nondepartemen setingkat menteri sebagaimana dimaksud dalam Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
3. Daftar Isian Pelaksanaan Anggaran yang selanjutnya disebut DIPA adalah Dokumen Pelaksanaan Anggaran yang digunakan sebagai acuan Pengguna Anggaran dalam melaksanakan kegiatan pemerintahan sebagai pelaksanaan APBN.
4. Keuangan Negara adalah semua hak dan kewajiban negara yang dapat dinilai dengan uang, serta segala sesuatu baik berupa uang maupun berupa barang yang dapat dijadikan milik negara berhubung dengan pelaksanaan hak dan kewajiban tersebut.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8327, 'perka-4-2014', 14, 'lampiran', 'Lampiran hal. 9', NULL, 9, '5. Menteri/Pimpinan Lembaga adalah pejabat yang bertanggung jawab atas pengelolaan kementerian negara/lembaga yang bersangkutan.
6. Perbendaharaan Negara adalah pengelolaan dan pertanggungjawaban keuangan negara, termasuk investasi dan kekayaan yang dipisahkan, yang ditetapkan dalam APBN dan APBD.
7. Pengguna Anggaran yang selanjutnya disebut PA adalah pejabat pemegang kewenangan penggunaan anggaran kementerian negara/ lembaga.
8. Kuasa Pengguna Anggaran yang selanjutnya disingkat KPA adalah 300, No.300 10 pejabat yang memperoleh kuasa dari PA untuk melaksanakan sebagian kewenangan dan tanggung jawab penggunaan anggaran pada kementerian negara/lembaga yang bersangkutan.
9. Pejabat Pembuat Komitmen yang selanjutnya disingkat PPK adalah pejabat yang melaksanakan kewenangan PA/KPA untuk mengambil keputusan dan/atau tindakan yang dapat mengakibatkan pengeluaran atas beban APBN.
10. Pejabat Penanda Tangan Surat Perintah Membayar yang selanjutnya disebut PPSPM adalah pejabat yang diberi kewenangan oleh PA/KPA untuk melakukan pengujian atas permintaan pembayaran dan menerbitkan perintah pembayaran.
11. Bendahara Pengeluaran adalah pejabat yang ditunjuk untuk menerima, menyimpan, membayar dan menyerahkan, menatausahakan dan mempertanggungjawabkan uang untuk keperluan belanja negara dalam rangka pelaksanaan APBN pada kantor/satker kementerian negara/lembaga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8327, '5. Menteri/Pimpinan Lembaga adalah pejabat yang bertanggung jawab atas pengelolaan kementerian negara/lembaga yang bersangkutan.
6. Perbendaharaan Negara adalah pengelolaan dan pertanggungjawaban keuangan negara, termasuk investasi dan kekayaan yang dipisahkan, yang ditetapkan dalam APBN dan APBD.
7. Pengguna Anggaran yang selanjutnya disebut PA adalah pejabat pemegang kewenangan penggunaan anggaran kementerian negara/ lembaga.
8. Kuasa Pengguna Anggaran yang selanjutnya disingkat KPA adalah 300, No.300 10 pejabat yang memperoleh kuasa dari PA untuk melaksanakan sebagian kewenangan dan tanggung jawab penggunaan anggaran pada kementerian negara/lembaga yang bersangkutan.
9. Pejabat Pembuat Komitmen yang selanjutnya disingkat PPK adalah pejabat yang melaksanakan kewenangan PA/KPA untuk mengambil keputusan dan/atau tindakan yang dapat mengakibatkan pengeluaran atas beban APBN.
10. Pejabat Penanda Tangan Surat Perintah Membayar yang selanjutnya disebut PPSPM adalah pejabat yang diberi kewenangan oleh PA/KPA untuk melakukan pengujian atas permintaan pembayaran dan menerbitkan perintah pembayaran.
11. Bendahara Pengeluaran adalah pejabat yang ditunjuk untuk menerima, menyimpan, membayar dan menyerahkan, menatausahakan dan mempertanggungjawabkan uang untuk keperluan belanja negara dalam rangka pelaksanaan APBN pada kantor/satker kementerian negara/lembaga.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8328, 'perka-4-2014', 15, 'lampiran', 'Lampiran hal. 10', NULL, 10, '12. Bagian Anggaran adalah kelompok anggaran menurut nomenklatur Kementerian Negara/Lembaga dan menurut fungsi Bendahara Umum Negara.
13. Bendahara Umum Negara yang selanjutnya disingkat BUN adalah pejabat yang diberi tugas melaksanakan fungsi BUN.
14. Kuasa Bendahara Umum Negara yang selanjutnya disebut Kuasa BUN adalah pejabat yang diangkat oleh BUN untuk melaksanakan tugas kebendaharaan dalam rangka pelaksanaan APBN dalam wilayah kerja yang ditetapkan.
15. Kantor Pelayanan Perbendaharaan Negara yang selanjutnya disingkat KPPN adalah instansi vertikal Direktorat Jenderal Perbendaharaan yang memperoleh kuasa dari BUN untuk melaksanakan sebagian fungsi Kuasa BUN.
16. Satuan Kerja yang selanjutnya disebut satker adalah unit organisasi lini kementerian negara/lembaga atau unit organisasi pemerintah daerah yang melaksanakan kegiatan kementerian negara/lembaga dan memiliki kewenangan dan tanggung jawab penggunaan anggaran.
17. Bendahara Pengeluaran adalah orang yang ditunjuk untuk menerima, menyimpan, membayarkan, menatausahakan, dan mempertanggung-jawabkan uang untuk keperluan Belanja Negara dalam pelaksanaan APBN pada kantor/satker kementerian negara/lembaga.
18. Bendahara Pengeluaran Pembantu yang selanjutnya disingkat BPP 11 2014, No.300 adalah orang yang ditunjuk untuk membantu Bendahara Pengeluaran untuk melaksanakan pembayaran kepada yang berhak guna kelancaran pelaksanaan kegiatan tertentu.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8328, '12. Bagian Anggaran adalah kelompok anggaran menurut nomenklatur Kementerian Negara/Lembaga dan menurut fungsi Bendahara Umum Negara.
13. Bendahara Umum Negara yang selanjutnya disingkat BUN adalah pejabat yang diberi tugas melaksanakan fungsi BUN.
14. Kuasa Bendahara Umum Negara yang selanjutnya disebut Kuasa BUN adalah pejabat yang diangkat oleh BUN untuk melaksanakan tugas kebendaharaan dalam rangka pelaksanaan APBN dalam wilayah kerja yang ditetapkan.
15. Kantor Pelayanan Perbendaharaan Negara yang selanjutnya disingkat KPPN adalah instansi vertikal Direktorat Jenderal Perbendaharaan yang memperoleh kuasa dari BUN untuk melaksanakan sebagian fungsi Kuasa BUN.
16. Satuan Kerja yang selanjutnya disebut satker adalah unit organisasi lini kementerian negara/lembaga atau unit organisasi pemerintah daerah yang melaksanakan kegiatan kementerian negara/lembaga dan memiliki kewenangan dan tanggung jawab penggunaan anggaran.
17. Bendahara Pengeluaran adalah orang yang ditunjuk untuk menerima, menyimpan, membayarkan, menatausahakan, dan mempertanggung-jawabkan uang untuk keperluan Belanja Negara dalam pelaksanaan APBN pada kantor/satker kementerian negara/lembaga.
18. Bendahara Pengeluaran Pembantu yang selanjutnya disingkat BPP 11 2014, No.300 adalah orang yang ditunjuk untuk membantu Bendahara Pengeluaran untuk melaksanakan pembayaran kepada yang berhak guna kelancaran pelaksanaan kegiatan tertentu.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8329, 'perka-4-2014', 16, 'lampiran', 'Lampiran hal. 11', NULL, 11, '19. Petugas Pengelolaan Administrasi Belanja Pegawai, yang selanjutnya disingkat PPABP adalah pembantu KPA yang diberi tugas dan tanggung jawab untuk mengelola pelaksanaan belanja pegawai.
20. Uang Persediaan yang selanjutnya disingkat UP adalah uang muka kerja dalam jumlah tertentu yang diberikan kepada Bendahara Pengeluaran untuk membiayai kegiatan operasional sehari-hari Satker atau membiayai pengeluaran yang menurut sifat dan tujuannya tidak mungkin dilakukan melalui mekanisme pembayaran langsung.
21. Pembayaran Langsung yang selanjutnya disebut Pembayaran LS adalah pembayaran yang dilakukan langsung kepada Bendahara Pengeluaran/Penerima hak lainnya atas dasar perjanjian kerja, surat keputusan, surat tugas atau surat perintah lainnya melalui penerbitan Surat Perintah Membayar Langsung.
22. Sistem Akuntansi Instansi yang selanjutnya disingkat SAI adalah serangkaian prosedur manual maupun yang terkomputerisasi mulai dari pengumpulan data, pencatatan, pengikhtisaran sampai dengan pelaporan posisi keuangan dan operasi keuangan pada kementerian negara/lembaga.
23. Sistem Akuntansi Keuangan (SAK) adalah subsistem dari SAI yang merupakan serangkaian prosedur yang saling berhubungan untuk mengolah dokumen sumber dalam rangka menghasilkan informasi untuk penyusunan neraca, realisasi anggaran, dan laporan keuangan serta laporan manajerial sesuai ketentuan yang berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8329, '19. Petugas Pengelolaan Administrasi Belanja Pegawai, yang selanjutnya disingkat PPABP adalah pembantu KPA yang diberi tugas dan tanggung jawab untuk mengelola pelaksanaan belanja pegawai.
20. Uang Persediaan yang selanjutnya disingkat UP adalah uang muka kerja dalam jumlah tertentu yang diberikan kepada Bendahara Pengeluaran untuk membiayai kegiatan operasional sehari-hari Satker atau membiayai pengeluaran yang menurut sifat dan tujuannya tidak mungkin dilakukan melalui mekanisme pembayaran langsung.
21. Pembayaran Langsung yang selanjutnya disebut Pembayaran LS adalah pembayaran yang dilakukan langsung kepada Bendahara Pengeluaran/Penerima hak lainnya atas dasar perjanjian kerja, surat keputusan, surat tugas atau surat perintah lainnya melalui penerbitan Surat Perintah Membayar Langsung.
22. Sistem Akuntansi Instansi yang selanjutnya disingkat SAI adalah serangkaian prosedur manual maupun yang terkomputerisasi mulai dari pengumpulan data, pencatatan, pengikhtisaran sampai dengan pelaporan posisi keuangan dan operasi keuangan pada kementerian negara/lembaga.
23. Sistem Akuntansi Keuangan (SAK) adalah subsistem dari SAI yang merupakan serangkaian prosedur yang saling berhubungan untuk mengolah dokumen sumber dalam rangka menghasilkan informasi untuk penyusunan neraca, realisasi anggaran, dan laporan keuangan serta laporan manajerial sesuai ketentuan yang berlaku.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8330, 'perka-4-2014', 17, 'lampiran', 'Lampiran hal. 11', NULL, 11, '24. Sistem Informasi Manajemen dan Akuntansi Barang Milik Negara yang selanjutnya disingkat SIMAK-BMN, adalah subsistem dari SAI yang merupakan serangkaian prosedur yang saling berhubungan untuk mengolah dokumen sumber dalam rangka menghasilkan informasi untuk penyusunsn neraca dan laporan BMN serta laporan manajerial lainnya sesuai ketentuan yang berlaku.
25. Dokumen Sumber adalah dokumen yang berhubungan dengan transaksi keuangan yang digunakan sebagai sumber atau bukti untuk menghasilkan data akuntansi.
26. Laporan Keuangan adalah bentuk pertanggungjawaban pemerintah atas pelaksanaan Anggaran Pendapatan dan Belanja Negara berupa Laporan Realisasi Anggaran, Neraca, Laporan Arus Kas dan Catatan atas Laporan Keuangan.
27. Unit Akuntansi Instansi yang selanjutnya disingkat UAI adalah unit 300, No.300 12 organisasi Kementerian Negara/Lembaga yang bersifat fungsional yang melaksanakan fungsi akuntansi dan pelaporan keuangan instansi yang terdiri dari Unit Akuntansi Keuangan dan Unit Akuntansi Barang.
28. Tambahan Uang Persediaan yang selanjutnya disebut TUP adalah uang muka yang diberikan kepada Bendahara Pengeluaran untuk kebutuhan yang sangat mendesak dalam 1 (satu) bulan melebihi pagu UP yang telah ditetapkan.
29. Pertanggungjawaban Tambahan Uang Persediaan yang selanjutnya disingkat PTUP adalah pertanggungjawaban atas TUP.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8330, '24. Sistem Informasi Manajemen dan Akuntansi Barang Milik Negara yang selanjutnya disingkat SIMAK-BMN, adalah subsistem dari SAI yang merupakan serangkaian prosedur yang saling berhubungan untuk mengolah dokumen sumber dalam rangka menghasilkan informasi untuk penyusunsn neraca dan laporan BMN serta laporan manajerial lainnya sesuai ketentuan yang berlaku.
25. Dokumen Sumber adalah dokumen yang berhubungan dengan transaksi keuangan yang digunakan sebagai sumber atau bukti untuk menghasilkan data akuntansi.
26. Laporan Keuangan adalah bentuk pertanggungjawaban pemerintah atas pelaksanaan Anggaran Pendapatan dan Belanja Negara berupa Laporan Realisasi Anggaran, Neraca, Laporan Arus Kas dan Catatan atas Laporan Keuangan.
27. Unit Akuntansi Instansi yang selanjutnya disingkat UAI adalah unit 300, No.300 12 organisasi Kementerian Negara/Lembaga yang bersifat fungsional yang melaksanakan fungsi akuntansi dan pelaporan keuangan instansi yang terdiri dari Unit Akuntansi Keuangan dan Unit Akuntansi Barang.
28. Tambahan Uang Persediaan yang selanjutnya disebut TUP adalah uang muka yang diberikan kepada Bendahara Pengeluaran untuk kebutuhan yang sangat mendesak dalam 1 (satu) bulan melebihi pagu UP yang telah ditetapkan.
29. Pertanggungjawaban Tambahan Uang Persediaan yang selanjutnya disingkat PTUP adalah pertanggungjawaban atas TUP.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8331, 'perka-4-2014', 18, 'lampiran', 'Lampiran hal. 12', NULL, 12, '30. Surat Permintaan Pembayaran yang selanjutnya disingkat SPP adalah dokumen yang diterbitkan oleh PPK, yang berisi permintaan pembayaran tagihan kepada negara.
31. Surat Permintaan Pembayaran Langsung yang selanjutnya disingkat SPP-LS adalah dokumen yang diterbitkan oleh PPK, dalam rangka pembayaran tagihan kepada penerima hak/Bendahara Pengeluaran.
32. Surat Permintaan Pembayaran Uang Persediaan yang selanjutnya disingkat SPP-UP adalah dokumen yang diterbitkan oleh PPK, yang berisi permintaan pembayaran UP.
33. Surat Permintaan Pembayaran Tambahan Uang Persediaan yang selanjutnya disingkat SPP-TUP adalah dokumen yang diterbitkan oleh PPK, yang berisi permintaan pembayaran TUP.
34. Surat Permintaan Pembayaran Penggantian Uang Persediaan yang selanjutnya disingkat SPP-GUP adalah dokumen yang diterbitkan oleh PPK, yang berisi pertanggungjawaban dan permintaan kembali pembayaran UP.
35. Surat Permintaan Pembayaran Penggantian Uang Persediaan Nihil yang selanjutnya disingkat SPP-GUP Nihil adalah dokumen yang diterbitkan oleh PPK, yang berisi pertanggungjawaban UP.
36. Surat Permintaan Pembayaran Pertanggungjawaban Tambahan Uang Persediaan yang selanjutnya disingkat SPP-PTUP adalah dokumen yang diterbitkan oleh PPK, yang berisi pertanggungjawaban atas TUP.
37. Surat Perintah Membayar yang selanjutnya disebut SPM adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan dana yang bersumber dari DIPA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8331, '30. Surat Permintaan Pembayaran yang selanjutnya disingkat SPP adalah dokumen yang diterbitkan oleh PPK, yang berisi permintaan pembayaran tagihan kepada negara.
31. Surat Permintaan Pembayaran Langsung yang selanjutnya disingkat SPP-LS adalah dokumen yang diterbitkan oleh PPK, dalam rangka pembayaran tagihan kepada penerima hak/Bendahara Pengeluaran.
32. Surat Permintaan Pembayaran Uang Persediaan yang selanjutnya disingkat SPP-UP adalah dokumen yang diterbitkan oleh PPK, yang berisi permintaan pembayaran UP.
33. Surat Permintaan Pembayaran Tambahan Uang Persediaan yang selanjutnya disingkat SPP-TUP adalah dokumen yang diterbitkan oleh PPK, yang berisi permintaan pembayaran TUP.
34. Surat Permintaan Pembayaran Penggantian Uang Persediaan yang selanjutnya disingkat SPP-GUP adalah dokumen yang diterbitkan oleh PPK, yang berisi pertanggungjawaban dan permintaan kembali pembayaran UP.
35. Surat Permintaan Pembayaran Penggantian Uang Persediaan Nihil yang selanjutnya disingkat SPP-GUP Nihil adalah dokumen yang diterbitkan oleh PPK, yang berisi pertanggungjawaban UP.
36. Surat Permintaan Pembayaran Pertanggungjawaban Tambahan Uang Persediaan yang selanjutnya disingkat SPP-PTUP adalah dokumen yang diterbitkan oleh PPK, yang berisi pertanggungjawaban atas TUP.
37. Surat Perintah Membayar yang selanjutnya disebut SPM adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan dana yang bersumber dari DIPA.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8332, 'perka-4-2014', 19, 'lampiran', 'Lampiran hal. 12', NULL, 12, '38. Surat Perintah Membayar Langsung yang selanjutnya disebut SPM-LS adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan dana yang bersumber dari DIPA dalam rangka pembayaran tagihan kepada penerima hak/Bendahara Pengeluaran.
13 2014, No.300
39. Surat Perintah Membayar Uang Persediaan yang selanjutnya disebut SPM-UP adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan UP.
40. Surat Perintah Membayar Tambahan Uang Persediaan yang selanjutnya disebut SPM-TUP adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan TUP.
41. Surat Perintah Membayar Penggantian Uang Persediaan yang selanjutnya disebut SPM-GUP adalah dokumen yang diterbitkan oleh PPSPM dengan membebani DIPA, yang dananya dipergunakan untuk menggantikan UP yang telah dipakai.
42. Surat Perintah Membayar Penggantian Uang Persediaan Nihil yang selanjutnya disebut SPM-GUP Nihil adalah dokumen yang diterbitkan oleh PPSPM sebagai pertanggungjawaban UP yang membebani DIPA.
43. Surat Perintah Bayar (SPBy) adalah Surat Perintah yang diterbitkan oleh PPK berdasarkan hak dan bukti-bukti yang sah untuk memperoleh pembayaran yang ditujukan kepada Bendahara Pengeluaran untuk melakukan pembayaran.
44. Surat Perintah Pencairan Dana yang selanjutnya disebut SP2D adalah surat perintah yang diterbitkan oleh KPPN selaku Kuasa BUN untuk pelaksanaan pengeluaran atas beban APBN berdasarkan SPM.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8332, '38. Surat Perintah Membayar Langsung yang selanjutnya disebut SPM-LS adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan dana yang bersumber dari DIPA dalam rangka pembayaran tagihan kepada penerima hak/Bendahara Pengeluaran.
13 2014, No.300
39. Surat Perintah Membayar Uang Persediaan yang selanjutnya disebut SPM-UP adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan UP.
40. Surat Perintah Membayar Tambahan Uang Persediaan yang selanjutnya disebut SPM-TUP adalah dokumen yang diterbitkan oleh PPSPM untuk mencairkan TUP.
41. Surat Perintah Membayar Penggantian Uang Persediaan yang selanjutnya disebut SPM-GUP adalah dokumen yang diterbitkan oleh PPSPM dengan membebani DIPA, yang dananya dipergunakan untuk menggantikan UP yang telah dipakai.
42. Surat Perintah Membayar Penggantian Uang Persediaan Nihil yang selanjutnya disebut SPM-GUP Nihil adalah dokumen yang diterbitkan oleh PPSPM sebagai pertanggungjawaban UP yang membebani DIPA.
43. Surat Perintah Bayar (SPBy) adalah Surat Perintah yang diterbitkan oleh PPK berdasarkan hak dan bukti-bukti yang sah untuk memperoleh pembayaran yang ditujukan kepada Bendahara Pengeluaran untuk melakukan pembayaran.
44. Surat Perintah Pencairan Dana yang selanjutnya disebut SP2D adalah surat perintah yang diterbitkan oleh KPPN selaku Kuasa BUN untuk pelaksanaan pengeluaran atas beban APBN berdasarkan SPM.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8333, 'perka-4-2014', 20, 'lampiran', 'Lampiran hal. 13', NULL, 13, '45. Surat Pernyataan Tanggung Jawab Belanja yang selanjutnya disebut SPTB adalah pernyataan tanggungjawab belanja yang dibuat oleh PPK atas nama PA/KPA terhadap transaksi belanja sampai dengan jumlah tertentu.
46. Surat Keterangan Tanggung Jawab Mutlak, yang selanjutnya disebut SKTJM, adalah surat keterangan yang menyatakan bahwa segala akibat dari tindakan pejabat/seseorang yang dapat mengakibatkan kerugian negara menjadi tanggungjawab sepenuhnya dari pejabat/seseorang yang mengambil tindakan dimaksud.
47. Bagan Akun Standar yang selanjutnya disingkat BAS adalah daftar perkiraan buku besar meliputi kode dan uraian organisasi, fungsi dan subfungsi, program, kegiatan output, bagian anggaran/unit organisasi eselon I/satker dan kode perkiraan yang ditetapkan dan disusun secara sistematis untuk memudahkan perencanaan, pelaksanaan anggaran, serta pertanggungjawaban, dan laporan keuangan pemerintah pusat.
48. Penerimaan Negara Bukan Pajak yang selanjutnya disingkat PNBP adalah seluruh penerimaan pemerintah pusat yang tidak berasal dari pajak.
300, No.300 14
49. Bank Operasional adalah bank umum yang ditunjuk oleh Menteri Keuangan selaku BUN atau pejabat yang diberi kuasa untuk melaksanakan pemindahbukuan sejumlah uang dari Kas Negara ke rekening sebagaimana yang tercantum dalam SP2D.
50. Arsip Data Komputer yang selanjutnya disebut ADK adalah arsip data dalam bentuk softcopy yang disimpan dalam media penyimpanan digital.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8333, '45. Surat Pernyataan Tanggung Jawab Belanja yang selanjutnya disebut SPTB adalah pernyataan tanggungjawab belanja yang dibuat oleh PPK atas nama PA/KPA terhadap transaksi belanja sampai dengan jumlah tertentu.
46. Surat Keterangan Tanggung Jawab Mutlak, yang selanjutnya disebut SKTJM, adalah surat keterangan yang menyatakan bahwa segala akibat dari tindakan pejabat/seseorang yang dapat mengakibatkan kerugian negara menjadi tanggungjawab sepenuhnya dari pejabat/seseorang yang mengambil tindakan dimaksud.
47. Bagan Akun Standar yang selanjutnya disingkat BAS adalah daftar perkiraan buku besar meliputi kode dan uraian organisasi, fungsi dan subfungsi, program, kegiatan output, bagian anggaran/unit organisasi eselon I/satker dan kode perkiraan yang ditetapkan dan disusun secara sistematis untuk memudahkan perencanaan, pelaksanaan anggaran, serta pertanggungjawaban, dan laporan keuangan pemerintah pusat.
48. Penerimaan Negara Bukan Pajak yang selanjutnya disingkat PNBP adalah seluruh penerimaan pemerintah pusat yang tidak berasal dari pajak.
300, No.300 14
49. Bank Operasional adalah bank umum yang ditunjuk oleh Menteri Keuangan selaku BUN atau pejabat yang diberi kuasa untuk melaksanakan pemindahbukuan sejumlah uang dari Kas Negara ke rekening sebagaimana yang tercantum dalam SP2D.
50. Arsip Data Komputer yang selanjutnya disebut ADK adalah arsip data dalam bentuk softcopy yang disimpan dalam media penyimpanan digital.', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8334, 'perka-4-2014', 21, 'lampiran', 'Lampiran hal. 14', NULL, 14, '51. Gaji Induk adalah gaji yang dibayarkan secara rutin bulanan kepada pegawai negeri yang telah diangkat oleh pejabat yang berwenang dengan surat keputusan sesuai ketentuan perundang-undangan pada Satker yang meliputi gaji pokok dan tunjangan yang melekat pada gaji.
52. Bantuan Langsung Kepada Masyarakat/Kelompok Masyarakat adalah bantuan dari Pemerintah/Pemerintah Daerah yang diterima langsung oleh masyarakat dan/atau lembaga kemasyarakatan termasuk di dalamnya bantuan untuk lembaga nonpemerintah bidang pendidikan dan keagamaan.
53. Dana Bantuan Sosial Berpola Hibah adalah dana yang disediakan Pemerintah kepada Pemerintah Daerah sebagai bantuan penanganan untuk kegiatan pada tahap pascabencana.
54. Dana Kontinjensi adalah dana yang dicadangkan untuk menghadapi kemungkinan terjadinya bencana tertentu.
55. Dana Siap Pakai (on call) adalah dana yang selalu tersedia dan dicadangkan oleh Pemerintah untuk digunakan pada saat keadaan darurat bencana sampai dengan batas waktu keadaan darurat berakhir.
56. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pascabencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8334, '51. Gaji Induk adalah gaji yang dibayarkan secara rutin bulanan kepada pegawai negeri yang telah diangkat oleh pejabat yang berwenang dengan surat keputusan sesuai ketentuan perundang-undangan pada Satker yang meliputi gaji pokok dan tunjangan yang melekat pada gaji.
52. Bantuan Langsung Kepada Masyarakat/Kelompok Masyarakat adalah bantuan dari Pemerintah/Pemerintah Daerah yang diterima langsung oleh masyarakat dan/atau lembaga kemasyarakatan termasuk di dalamnya bantuan untuk lembaga nonpemerintah bidang pendidikan dan keagamaan.
53. Dana Bantuan Sosial Berpola Hibah adalah dana yang disediakan Pemerintah kepada Pemerintah Daerah sebagai bantuan penanganan untuk kegiatan pada tahap pascabencana.
54. Dana Kontinjensi adalah dana yang dicadangkan untuk menghadapi kemungkinan terjadinya bencana tertentu.
55. Dana Siap Pakai (on call) adalah dana yang selalu tersedia dan dicadangkan oleh Pemerintah untuk digunakan pada saat keadaan darurat bencana sampai dengan batas waktu keadaan darurat berakhir.
56. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pascabencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8335, 'perka-4-2014', 22, 'lampiran', 'Lampiran hal. 14', NULL, 14, '57. Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peranserta masyarakat dalam segala aspek kehidupan bermasyarakat pada wilayah pascabencana.
58. Surat Perjalanan Dinas yang selanjutnya disingkat SPD adalah dokumen yang diterbitkan oleh Pejabat Pembuat Komitmen dalam 15 2014, No.300 rangka pelaksanaan Perjalanan Dinas bagi Pejabat Negara, Pegawai Negeri, Pegawai Tidak Tetap, dan Pihak Lain.
59. Pelaksana SPD adalah Pejabat Negara, Pegawai Negeri, dan Pegawai Tidak Tetap yang melaksanakan perjalanan dinas.
BAB II STRUKTUR DAN URAIAN TUGAS PENGELOLA ANGGARAN A. Struktur Pengelola Anggaran pada Satker BNPB Menteri/Pimpinan Lembaga dalam hal ini Kepala Badan Nasional Penanggulangan Bencana menguasai Bagian Anggaran (BA 103) dan BA 999.08 (sebatas yang dikuasakan) mempunyai kewenangan atas penggunaan anggaran di lingkungan BNPB.
BNPB memiliki satu KPA, satu Bendahara Pengeluaran, beberapa PPK/BPP pada setiap unit kerja setingkat eselon II ditetapkan satu PPK/BPP. Untuk unit eselon II (Biro Perencanaan) memiliki 2 BPP, yaitu BPP Unsur Pengarah dan BPP Biro Perencanaan, serta unit eselon II (Biro Umum) memiliki 2 BPP, yaitu BPP Unsur Pimpinan dan BPP Biro Umum.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8335, '57. Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peranserta masyarakat dalam segala aspek kehidupan bermasyarakat pada wilayah pascabencana.
58. Surat Perjalanan Dinas yang selanjutnya disingkat SPD adalah dokumen yang diterbitkan oleh Pejabat Pembuat Komitmen dalam 15 2014, No.300 rangka pelaksanaan Perjalanan Dinas bagi Pejabat Negara, Pegawai Negeri, Pegawai Tidak Tetap, dan Pihak Lain.
59. Pelaksana SPD adalah Pejabat Negara, Pegawai Negeri, dan Pegawai Tidak Tetap yang melaksanakan perjalanan dinas.
BAB II STRUKTUR DAN URAIAN TUGAS PENGELOLA ANGGARAN A. Struktur Pengelola Anggaran pada Satker BNPB Menteri/Pimpinan Lembaga dalam hal ini Kepala Badan Nasional Penanggulangan Bencana menguasai Bagian Anggaran (BA 103) dan BA 999.08 (sebatas yang dikuasakan) mempunyai kewenangan atas penggunaan anggaran di lingkungan BNPB.
BNPB memiliki satu KPA, satu Bendahara Pengeluaran, beberapa PPK/BPP pada setiap unit kerja setingkat eselon II ditetapkan satu PPK/BPP. Untuk unit eselon II (Biro Perencanaan) memiliki 2 BPP, yaitu BPP Unsur Pengarah dan BPP Biro Perencanaan, serta unit eselon II (Biro Umum) memiliki 2 BPP, yaitu BPP Unsur Pimpinan dan BPP Biro Umum.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8336, 'perka-4-2014', 23, 'lampiran', 'Lampiran hal. 15', NULL, 15, 'Di samping itu dalam rangka pelaksanaan penanggulangan bencana yang meliputi tahap prabencana, keadaan darurat bencana, dan pascabencana dalam hal BNPB melibatkan BPBD Provinsi, Kabupaten/Kota, dan/atau Kementerian Negara/Lembaga lainnya KPA dapat menunjuk PPK dan BPP sesuai dengan kebutuhan.
Kepala BNPB selaku Pengguna Anggaran menetapkan Pegawai/Pejabat di lingkungan BNPB yang ditunjuk sebagai pengelola anggaran yang bertanggung jawab dalam pelaksanaan pengelolaan DIPA BNPB.
Adapun Pengelola Anggaran yang ditunjuk meliputi:
1. Kuasa Pengguna Anggaran;
2. Bendahara Pengeluaran;
3. Bendahara Pengeluaran Pembantu; dan
4. Bendahara Dana Masyarakat.
Untuk selanjutnya Kuasa Pengguna Anggaran menunjuk pejabat pengelola anggaran lainnya yang meliputi:
1. Pejabat Pembuat Komitmen;
2. Pejabat Penandatangan SPM;
3. Pembantu Pejabat Penandatangan SPM;
300, No.300 16
4. Petugas Pengelola Administrasi Belanja Pegawai (PPABP);
5. Petugas Pengelola Keuangan (Pembatu Administrasi PPK); dan
6. Petugas Pengelola Keuangan (Pembantu Administrasi PPK sebagai verifikator di unit kerja).
Bagan Struktur Pengelola Anggaran di lingkungan BNPB adalah sebagaimana terlampir (Lampiran I).
B. Uraian Tugas Pengelola Anggaran pada Satker BNPB Uraian tugas masing-masing pejabat pengelola anggaran adalah sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8336, 'Di samping itu dalam rangka pelaksanaan penanggulangan bencana yang meliputi tahap prabencana, keadaan darurat bencana, dan pascabencana dalam hal BNPB melibatkan BPBD Provinsi, Kabupaten/Kota, dan/atau Kementerian Negara/Lembaga lainnya KPA dapat menunjuk PPK dan BPP sesuai dengan kebutuhan.
Kepala BNPB selaku Pengguna Anggaran menetapkan Pegawai/Pejabat di lingkungan BNPB yang ditunjuk sebagai pengelola anggaran yang bertanggung jawab dalam pelaksanaan pengelolaan DIPA BNPB.
Adapun Pengelola Anggaran yang ditunjuk meliputi:
1. Kuasa Pengguna Anggaran;
2. Bendahara Pengeluaran;
3. Bendahara Pengeluaran Pembantu; dan
4. Bendahara Dana Masyarakat.
Untuk selanjutnya Kuasa Pengguna Anggaran menunjuk pejabat pengelola anggaran lainnya yang meliputi:
1. Pejabat Pembuat Komitmen;
2. Pejabat Penandatangan SPM;
3. Pembantu Pejabat Penandatangan SPM;
300, No.300 16
4. Petugas Pengelola Administrasi Belanja Pegawai (PPABP);
5. Petugas Pengelola Keuangan (Pembatu Administrasi PPK); dan
6. Petugas Pengelola Keuangan (Pembantu Administrasi PPK sebagai verifikator di unit kerja).
Bagan Struktur Pengelola Anggaran di lingkungan BNPB adalah sebagaimana terlampir (Lampiran I).
B. Uraian Tugas Pengelola Anggaran pada Satker BNPB Uraian tugas masing-masing pejabat pengelola anggaran adalah sebagai berikut:', 'Lampiran hal. 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8337, 'perka-4-2014', 24, 'lampiran', 'Lampiran hal. 16', NULL, 16, '1. Pengguna Anggaran (PA) memiliki tugas dan wewenang: a) Menetapkan KPA/Kepala Satker; b) Menetapkan Bendahara Penerimaan/Bendahara Pengeluaran/ Bendahara Pengeluaran Pembantu. Kewenangan ini dapat didelegasikan kepada KPA/Kepala Satker dengan Surat Keputusan; c) Menetapkan Unit Kerja yang diberi kewenangan sebagai Unit Pelayanan Pengadaan (ULP), dan mengangkat Pejabat-pejabatnya; d) Apabila Unit Pelayanan Pengadaan belum dibentuk, PA mengangkat Panitia Pengadaan Barang dan Jasa; e) Mengangkat Pejabat Pengadaan; f) Menetapkan Pejabat Penerima Hasil Pekerjaan/Barang/Jasa; g) Menyusun dan Menetapkan Rencana Pembangunan Jangka Menengah dan Rencana Kerja Tahunan; h) Menyusun dan Menetapkan Rencana Kerja Anggaran; i) Menyusun DIPA; j) Mengusulkan dan/atau menetapkan revisi DIPA; k) Menetapkan Petunjuk Operasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8337, '1. Pengguna Anggaran (PA) memiliki tugas dan wewenang: a) Menetapkan KPA/Kepala Satker; b) Menetapkan Bendahara Penerimaan/Bendahara Pengeluaran/ Bendahara Pengeluaran Pembantu. Kewenangan ini dapat didelegasikan kepada KPA/Kepala Satker dengan Surat Keputusan; c) Menetapkan Unit Kerja yang diberi kewenangan sebagai Unit Pelayanan Pengadaan (ULP), dan mengangkat Pejabat-pejabatnya; d) Apabila Unit Pelayanan Pengadaan belum dibentuk, PA mengangkat Panitia Pengadaan Barang dan Jasa; e) Mengangkat Pejabat Pengadaan; f) Menetapkan Pejabat Penerima Hasil Pekerjaan/Barang/Jasa; g) Menyusun dan Menetapkan Rencana Pembangunan Jangka Menengah dan Rencana Kerja Tahunan; h) Menyusun dan Menetapkan Rencana Kerja Anggaran; i) Menyusun DIPA; j) Mengusulkan dan/atau menetapkan revisi DIPA; k) Menetapkan Petunjuk Operasional.', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8338, 'perka-4-2014', 25, 'lampiran', 'Lampiran hal. 16', NULL, 16, '2. Kuasa Pengguna Anggaran (KPA) memiliki tugas dan wewenang: a) Menetapkan PPK untuk melakukan tindakan yang mengakibatkan pengeluaran anggaran belanja Negara; b) Menetapkan PPSPM untuk melakukan pengujian tagihan dan menertibkan SPM atas beban anggaran belanja Negara; c) Menetapkan panitia/pejabat yang terlibat dalam pelaksanaan kegiatan dan pengelola anggaran keuangan; d) Menetapkan rencana pelaksanaan kegiatan dan rencana penarikan dana; e) Memberikan supervisi dan konsultasi dalam pelaksanaan 17 2014, No.300 kegiatan dan penarikan dana; f) Mengawasi penatausahaan dokumen dan transaksi yang berkaitan dengan pelaksanaan kegiatan dan anggaran; g) Menyusun laporan keuangan dan kinerja atas pelaksanaan anggaran sesuai dengan peraturan perundang-undangan; h) Dalam 1 (satu) DIPA, KPA menetapkan 1 (satu) atau lebih PPK dan 1 (satu) PPSPM; i) Bertanggung jawab atas pelaksanaan kegiatan dan anggaran yang berada dalam penguasaannya kepada PA; j) Pelaksanaan tanggung jawab KPA dilakukan dalam bentuk:
1) Mengesahkan rencana pelaksanaan kegiatan dan rencana penarikan dana;
2) Merumuskan standar operasional pelaksanaan pengadaan barang/jasa sesuai dengan ketentuan tentang pengadaan barang/jasa pemerintah;
3) Menyusun sistem pengawasan pengendalian agar proses penyelesaian tagihan atas beban APBN dilaksanakan sesuai dengan peraturan perundang-undangan;
4) Melakukan pengawasan agar pelaksanaan kegiatan dan pengadaan barang/jasa sesuai dengan keluaran (out put) yang ditetapkan dalam DIPA;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8338, '2. Kuasa Pengguna Anggaran (KPA) memiliki tugas dan wewenang: a) Menetapkan PPK untuk melakukan tindakan yang mengakibatkan pengeluaran anggaran belanja Negara; b) Menetapkan PPSPM untuk melakukan pengujian tagihan dan menertibkan SPM atas beban anggaran belanja Negara; c) Menetapkan panitia/pejabat yang terlibat dalam pelaksanaan kegiatan dan pengelola anggaran keuangan; d) Menetapkan rencana pelaksanaan kegiatan dan rencana penarikan dana; e) Memberikan supervisi dan konsultasi dalam pelaksanaan 17 2014, No.300 kegiatan dan penarikan dana; f) Mengawasi penatausahaan dokumen dan transaksi yang berkaitan dengan pelaksanaan kegiatan dan anggaran; g) Menyusun laporan keuangan dan kinerja atas pelaksanaan anggaran sesuai dengan peraturan perundang-undangan; h) Dalam 1 (satu) DIPA, KPA menetapkan 1 (satu) atau lebih PPK dan 1 (satu) PPSPM; i) Bertanggung jawab atas pelaksanaan kegiatan dan anggaran yang berada dalam penguasaannya kepada PA; j) Pelaksanaan tanggung jawab KPA dilakukan dalam bentuk:
1) Mengesahkan rencana pelaksanaan kegiatan dan rencana penarikan dana;
2) Merumuskan standar operasional pelaksanaan pengadaan barang/jasa sesuai dengan ketentuan tentang pengadaan barang/jasa pemerintah;
3) Menyusun sistem pengawasan pengendalian agar proses penyelesaian tagihan atas beban APBN dilaksanakan sesuai dengan peraturan perundang-undangan;
4) Melakukan pengawasan agar pelaksanaan kegiatan dan pengadaan barang/jasa sesuai dengan keluaran (out put) yang ditetapkan dalam DIPA;', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8339, 'perka-4-2014', 26, 'lampiran', 'Lampiran hal. 17', NULL, 17, '5) Melakukan monitoring dan evaluasi agar pembuatan perjanjian/kontrak pengadaan barang/jasa dan pembayaran atas beban APBN sesuai dengan keluaran (output) yang ditetapkan dalam DIPA serta rencana yang telah ditetapkan;
6) Merumuskan kebijakan agar pembayaran atas beban APBN sesuai dengan keluaran (output) yang ditetapkan dalam DIPA; dan 7) Melakukan pengawasan, monitoring, dan evaluasi atas pertanggungjawaban pelaksanaan anggaran dalam rangka penyusunan laporan keuangan.
3. Pejabat Pembuat Komitmen (PPK) memiliki tugas dan wewenang:
a. Melaksanakan kewenangan KPA untuk melakukan tindakan yang mengakibatkan pengeluaran belanja negara dengan mempedomani pelaksanaan tanggung jawab KPA kepada PA;
b. Melakukan tindakan yang dapat mengakibatkan pengeluaran anggaran belanja negara, PPK memiliki tugas dan wewenang:
1) Menyusun rencana pelaksanaan kegiatan dan rencana 300, No.300 18 penarikan dana berdasarkan DIPA yang dilakukan dengan: a) Menyusun jadwal waktu pelaksanaan kegiatan termasuk rencana penarikan dananya; b)Menyusun perhitungan kebutuhan UP/TUP sebagai dasar pembuatan SPP-UP/TUP; dan c) Mengusulkan revisi POK/DIPA kepada KPA.
2) Menerbitkan Surat Penunjukan Penyedia Barang/Jasa;
3) Membuat, menandatangani, dan melaksanakan perjanjian/kontrak dengan Penyedia Barang/Jasa;
4) Melaksanakan kegiatan swakelola;
5) Memberitahukan kepada Kuasa BUN atas perjanjian/kontrak yang dilakukannya;
6) Mengendalikan pelaksanaan perjanjian/kontrak;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8339, '5) Melakukan monitoring dan evaluasi agar pembuatan perjanjian/kontrak pengadaan barang/jasa dan pembayaran atas beban APBN sesuai dengan keluaran (output) yang ditetapkan dalam DIPA serta rencana yang telah ditetapkan;
6) Merumuskan kebijakan agar pembayaran atas beban APBN sesuai dengan keluaran (output) yang ditetapkan dalam DIPA; dan 7) Melakukan pengawasan, monitoring, dan evaluasi atas pertanggungjawaban pelaksanaan anggaran dalam rangka penyusunan laporan keuangan.
3. Pejabat Pembuat Komitmen (PPK) memiliki tugas dan wewenang:
a. Melaksanakan kewenangan KPA untuk melakukan tindakan yang mengakibatkan pengeluaran belanja negara dengan mempedomani pelaksanaan tanggung jawab KPA kepada PA;
b. Melakukan tindakan yang dapat mengakibatkan pengeluaran anggaran belanja negara, PPK memiliki tugas dan wewenang:
1) Menyusun rencana pelaksanaan kegiatan dan rencana 300, No.300 18 penarikan dana berdasarkan DIPA yang dilakukan dengan: a) Menyusun jadwal waktu pelaksanaan kegiatan termasuk rencana penarikan dananya; b)Menyusun perhitungan kebutuhan UP/TUP sebagai dasar pembuatan SPP-UP/TUP; dan c) Mengusulkan revisi POK/DIPA kepada KPA.
2) Menerbitkan Surat Penunjukan Penyedia Barang/Jasa;
3) Membuat, menandatangani, dan melaksanakan perjanjian/kontrak dengan Penyedia Barang/Jasa;
4) Melaksanakan kegiatan swakelola;
5) Memberitahukan kepada Kuasa BUN atas perjanjian/kontrak yang dilakukannya;
6) Mengendalikan pelaksanaan perjanjian/kontrak;', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8340, 'perka-4-2014', 27, 'lampiran', 'Lampiran hal. 18', NULL, 18, '7) Menguji dan menandatangani surat bukti mengenai hak tagih kepada negara, yang dilakukan dengan: a) Menguji kebenaran materiil dan keabsahan surat-surat bukti mengenai hak tagih kepada negara dengan menguji: o kelengkapan dokumen tagihan; o kebenaran perhitungan tagihan; o kebenaran data pihak yang berhak menerima pembayaran atas beban APBN; o kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum dalam perjanjian/kontrak dengan barang/jasa yang diserahkan oleh penyedia barang/jasa; o kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/kontrak; o kebenaran, keabsahan serta akibat yang timbul dari penggunaan surat bukti mengenai hak tagih kepada negara; dan o ketepatan jangka waktu penyelesaian pekerjaan sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/kontrak; b)Menguji kebenaran dan keabsahan dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai.
19 2014, No.300 8) Membuat dan menandatangani SPP;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8340, '7) Menguji dan menandatangani surat bukti mengenai hak tagih kepada negara, yang dilakukan dengan: a) Menguji kebenaran materiil dan keabsahan surat-surat bukti mengenai hak tagih kepada negara dengan menguji: o kelengkapan dokumen tagihan; o kebenaran perhitungan tagihan; o kebenaran data pihak yang berhak menerima pembayaran atas beban APBN; o kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum dalam perjanjian/kontrak dengan barang/jasa yang diserahkan oleh penyedia barang/jasa; o kesesuaian spesifikasi teknis dan volume barang/jasa sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/kontrak; o kebenaran, keabsahan serta akibat yang timbul dari penggunaan surat bukti mengenai hak tagih kepada negara; dan o ketepatan jangka waktu penyelesaian pekerjaan sebagaimana yang tercantum pada dokumen serah terima barang/jasa dengan dokumen perjanjian/kontrak; b)Menguji kebenaran dan keabsahan dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai.
19 2014, No.300 8) Membuat dan menandatangani SPP;', 'Lampiran hal. 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8341, 'perka-4-2014', 28, 'lampiran', 'Lampiran hal. 19', NULL, 19, '9) Melaporkan pelaksanaan/penyelesaian kegiatan kepada KPA, berupa laporan atas pelaksanaan kegiatan, penyelesaian kegiatan dan penyelesaian tagihan kepada negara serta laporan bulanan yang terkait pelaksanaan tugas dan wewenang kepada KPA dengan isi laporan paling kurang memuat: a) perjanjian/kontrak dengan penyedia barang/jasa yang telah ditandatangani; b)tagihan yang belum dan telah disampaikan penyedia barang/jasa; c) tagihan yang belum dan telah diterbitkan SPP-nya; dan d)jangka waktu penyelesaian tagihan.
10) Menyerahkan hasil pekerjaan pelaksanaan kegiatan kepada KPA dengan Berita Acara Penyerahan;
11) Menyimpan dan menjaga keutuhan seluruh dokumen pelaksanaan kegiatan; dan 12) Melaksanakan tugas dan wewenang lainnya yang berkaitan dengan tindakan yang mengakibatkan pengeluaran anggaran belanja negara sesuai ketentuan peraturan perundang-undangan, meliputi: a) menetapkan rencana pelaksanaan pengadaan barang/jasa; b) memastikan telah terpenuhinya kewajiban pembayaran kepada negara oleh pihak yang mempunyai hak tagih kepada negara; c) mengajukan permintaan pembayaran atas tagihan berdasarkan kegiatan; d) memastikan ketepatan jangka waktu penyelesaian tagihan kepada negara; dan e) menetapkan besaran uang muka yang akan dibayarkan kepada penyedia barang/jasa untuk: o mobilisasi alat dan tenaga kerja; o pembayaran uang muka tanda jadi kepada pemasok barang/material; dan/atau o persiapan teknis lain yang diperlukan bagi pelaksanaan pengadaan barang/jasa.
300, No.300 20');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8341, '9) Melaporkan pelaksanaan/penyelesaian kegiatan kepada KPA, berupa laporan atas pelaksanaan kegiatan, penyelesaian kegiatan dan penyelesaian tagihan kepada negara serta laporan bulanan yang terkait pelaksanaan tugas dan wewenang kepada KPA dengan isi laporan paling kurang memuat: a) perjanjian/kontrak dengan penyedia barang/jasa yang telah ditandatangani; b)tagihan yang belum dan telah disampaikan penyedia barang/jasa; c) tagihan yang belum dan telah diterbitkan SPP-nya; dan d)jangka waktu penyelesaian tagihan.
10) Menyerahkan hasil pekerjaan pelaksanaan kegiatan kepada KPA dengan Berita Acara Penyerahan;
11) Menyimpan dan menjaga keutuhan seluruh dokumen pelaksanaan kegiatan; dan 12) Melaksanakan tugas dan wewenang lainnya yang berkaitan dengan tindakan yang mengakibatkan pengeluaran anggaran belanja negara sesuai ketentuan peraturan perundang-undangan, meliputi: a) menetapkan rencana pelaksanaan pengadaan barang/jasa; b) memastikan telah terpenuhinya kewajiban pembayaran kepada negara oleh pihak yang mempunyai hak tagih kepada negara; c) mengajukan permintaan pembayaran atas tagihan berdasarkan kegiatan; d) memastikan ketepatan jangka waktu penyelesaian tagihan kepada negara; dan e) menetapkan besaran uang muka yang akan dibayarkan kepada penyedia barang/jasa untuk: o mobilisasi alat dan tenaga kerja; o pembayaran uang muka tanda jadi kepada pemasok barang/material; dan/atau o persiapan teknis lain yang diperlukan bagi pelaksanaan pengadaan barang/jasa.
300, No.300 20', 'Lampiran hal. 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8342, 'perka-4-2014', 29, 'lampiran', 'Lampiran hal. 20', NULL, 20, '4. Pejabat Penandatangan SPM (PPSPM) memiliki tugas dan wewenang sebagai berikut:
a. Menguji ulang (review) kebenaran SPP yang diajukan oleh Pejabat Pembuat Komitmen beserta dokumen pendukung yang meliputi:
1) kelengkapan dokumen pendukung SPP.
2) kesesuaian penandatangan SPP dengan spesimen tandatangan PPK.
3) kebenaran pengisian format SPP.
4) kesesuaian kode BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Satker termasuk menguji kesesuaian antara pembebanan kode mata anggaran pengeluaran (akun 6 digit) dengan uraiannya.
5) ketersediaan pagu sesuai dengan BAS pada SPP dengan DIPA/POK/ Rencana Kerja Anggaran Satker.
6) kebenaran formal dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai;
7) kebenaran formal dokumen/surat bukti yang menjadi persyaratan/kelengkapan sehubungan dengan pengadaan barang/jasa;
8) kebenaran pihak yang berhak menerima pembayaranpada SPP sehubungan dengan perjanjian/kontrak/surat keputusan;
9) kebenaran perhitungan tagihan serta kewajiban di bidang perpajakan dari pihak yang mempunyai hak tagih;
10) kepastian telah terpenuhinya kewajiban pembayaran kepada negara oleh pihak yang mempunyai hak tagih kepada negara; dan 11) kesesuaian prestasi pekerjaan dengan ketentuan pembayaran dalam perjanjian/kontrak.
b. Menolak dan mengembalikan SPP, apabila SPP tidak memenuhi persayaratan untuk dibayarkan;
c. Membebankan tagihan pada mata anggaran yang telah disediakan;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8342, '4. Pejabat Penandatangan SPM (PPSPM) memiliki tugas dan wewenang sebagai berikut:
a. Menguji ulang (review) kebenaran SPP yang diajukan oleh Pejabat Pembuat Komitmen beserta dokumen pendukung yang meliputi:
1) kelengkapan dokumen pendukung SPP.
2) kesesuaian penandatangan SPP dengan spesimen tandatangan PPK.
3) kebenaran pengisian format SPP.
4) kesesuaian kode BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Satker termasuk menguji kesesuaian antara pembebanan kode mata anggaran pengeluaran (akun 6 digit) dengan uraiannya.
5) ketersediaan pagu sesuai dengan BAS pada SPP dengan DIPA/POK/ Rencana Kerja Anggaran Satker.
6) kebenaran formal dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai;
7) kebenaran formal dokumen/surat bukti yang menjadi persyaratan/kelengkapan sehubungan dengan pengadaan barang/jasa;
8) kebenaran pihak yang berhak menerima pembayaranpada SPP sehubungan dengan perjanjian/kontrak/surat keputusan;
9) kebenaran perhitungan tagihan serta kewajiban di bidang perpajakan dari pihak yang mempunyai hak tagih;
10) kepastian telah terpenuhinya kewajiban pembayaran kepada negara oleh pihak yang mempunyai hak tagih kepada negara; dan 11) kesesuaian prestasi pekerjaan dengan ketentuan pembayaran dalam perjanjian/kontrak.
b. Menolak dan mengembalikan SPP, apabila SPP tidak memenuhi persayaratan untuk dibayarkan;
c. Membebankan tagihan pada mata anggaran yang telah disediakan;', 'Lampiran hal. 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8343, 'perka-4-2014', 30, 'lampiran', 'Lampiran hal. 20', NULL, 20, 'd. Menerbitkan SPM dengan melakukan hal-hal sebagai berikut:
1) mencatat pagu, realisasi belanja, sisa pagu, dana UP/TUP, dan sisa dana UP/TUP pada kartu pengawasan DIPA;
2) menandatangani SPM; dan 3) memasukkan Personal Identification Number (PIN) PPSPM sebagai tanda tangan elektronik pada ADK SPM.
21 2014, No.300
e. Menyimpan dan menjaga kelengkapan dan keutuhan seluruh dokumen hak tagih;
f. Melaporkan pelaksanaan perintah pembayaran kepada KPA pelaksanaan tugas dan wewenangnya paling sedikit memuat informasi jumlah SPP yang diterima, jumlah SPM yang diterbitkan dan jumlah SPP yang tidak dapat diterbitkan SPM;
g. Melaksanakan tugas dan wewenang lainnya yang berkaitan dengan pelaksanaan perintah pembayaran.
h. Dalam melaksanakan tugas dan wewenangnya PPSPM bertanggung jawab atas ketepatan jangka waktu penerbitan dan penyampaian SPM kepada KPPN; dan
i. PPSPM ikut bertanggung jawab atas kebenaran, kelengkapan, dan keabsahan administrasi terhadap dokumen hak tagih pembayaran yang menjadi dasar penerbitan SPM dan akibat yang timbul dari pengujian yang dilakukannya.
5. Pembantu Pejabat Penandatangan SPM memiliki tugas dan wewenang sebagai berikut:
a. Menguji kebenaran SPP beserta dokumen pendukung yang meliputi:
1) kelengkapan dokumen pendukung SPP;
2) kesesuaian penandatangan SPP dengan spesimen tandatangan PPK;
3) kebenaran pengisian format SPP;');
