INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8344, 'perka-4-2014', 31, 'lampiran', 'Lampiran hal. 21', NULL, 21, '4) kesesuaian kode BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Satker termasuk menguji kesesuaian antara pembebanan kode mata anggaran pengeluaran (akun 6 digit) dengan uraiannya;
5) ketersediaan pagu sesuai BAS pada SPP dengan DIPA/POK/Rencana Kerja Anggaran Satker;
6) kebenaran formal dokumen/surat keputusan yang menjadi persyaratan/kelengkapan pembayaran belanja pegawai;
7) kebenaran formal dokumen/surat bukti yang menjadi persyaratan/ kelengkapan sehubungan dengan pengadaan barang/jasa;
