INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8363, 'perka-4-2014', 50, 'lampiran', 'Lampiran hal. 36', NULL, 36, 'Pembayaran lembur dilengkapi dengan daftar pembayaran perhitungan lembur yang ditandatangani oleh kuasa PA/pejabat yang ditunjuk dan bendahara pengeluaran yang bersangkutan, dan SPP PPh Pasal 21.
SPP-LS Belanja Perjalanan Dinas Untuk pelaksanaan kegiatan perjalanan dinas, PPK dapat mengajukan Surat Permintaan Pembayaran Langsung (SPP-LS).
Belanja perjalanan dinas dilaksanakan dengan memperhatikan prinsip sebagai berikut:
a. Selektif, yaitu hanya untuk kepentingan yang sangat tinggi dan prioritas yang berkaitan dengan penyelenggaraan pemerintahan;
b. Ketersediaan anggaran dan kesesuaian dengan pencapaian kinerja Kementerian Negara/Lembaga;
c. Efisiensi penggunaan belanja negara; dan
d. Akuntabilitas pemberian perintah pelaksanaan Perjalanan Dinas dan pembebanan biaya perjalanan dinas.
Belanja Perjalanan Dinas dengan mekanisme pembayaran LS harus memperhatikan ketentuan meliputi: kegiatan yang akan 37 2014, No.300 dilaksanakan sudah pasti baik lokasi, tempat pelaksanaan kegiatan, waktu dan nama peserta yang terlibat (contoh rapat kerja, diklat, pelaksanaan audit, monev dan sejenisnya).
SPP-LS perjalanan dinas diajukan dengan lampiran sebagai berikut:
a. Surat Permintaan Pembayaran (SPP);
b. Surat Pernyataan Tanggungjawab Belanja (SPTB);
c. Daftar Rincian Permintaan Pembayaran; dan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8363, 'Pembayaran lembur dilengkapi dengan daftar pembayaran perhitungan lembur yang ditandatangani oleh kuasa PA/pejabat yang ditunjuk dan bendahara pengeluaran yang bersangkutan, dan SPP PPh Pasal 21.
