7. | Nota Kesepahaman (MOU) DSP Lampiran VII
8. | Berita Acara Serah Terima Bantuan Lampiran VIII/ 1-1', 'Lampiran hal. 79', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8427, 'perka-4-2014', 114, 'lampiran', 'Lampiran hal. 80', NULL, 80, '9. | Contoh Format Kwitansi Lampiran IX/1-1
10. | Ringkasan Kontrak / SPK Lampiran X/1-1
11. | Format Daftar Nominatif Pejabat Yang Melakukan Lampiran XI/ 1-1 Perjalanan Dinas');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8427, '9. | Contoh Format Kwitansi Lampiran IX/1-1
