INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8437, 'perka-4-2014', 124, 'lampiran', 'Lampiran hal. 89', NULL, 89, '1) DIPA BNPB Tahun 20xx telah dialokasikan dana untuk kegiatan Rutin sebagai dukungan dana pembiayaan Tugas dan Fungsi serta Dana Siap Pakai (DSP/Onca//) Penanggulangan Bencana yang terjadi di wilayah nusantara yang sifatnya mendesak dan kedaruratan, 2) Sehubungan dengan bencana di Provinsi:x0000000x,20000x, »00000x, dan daerah lainnya di seluruh wilayah Indonesia yang berdampak pada kehidupan masyarakatnya segera mendapatkan pertolongan, maka untuk mendukung pelaksanaan kegiatan penanggulangan bencana dimaksud, kamimengajukan permohonan TUP dana DSP/on calkebesar Rproxx.xxx.xxx.xex,xx(terbilang X000000xxK0000KxxKKOOKN) guna kesiapan ketersediaan dana yang memadai,mohon kiranya dapat dipenuhi dalam waktu dekat.
Adapun rincian penggunaan dana serta saldo rekening sebagaimana terlampir.
Demikian, atas bantuan serta perhatiannya, kami ucapkan terima kasih.
Sekretaris Utama Selaku Kuasa Pengguna Anggaran Tembusan Yth:
1. Kepala Badan Nasional Penanggulangan Bencana (sebagai laporan):
2. Direktur Jenderal Anggaran Kementerian Keuangan RI:
3. Direktur Jenderal Perbendaharaan Kementerian Keuangan RI, 4, Direktur Pelaksanaan Anggaran Ditjen. Perbendaharaan Kementerian Keuangan RI:
5. Kepala KPPN Jakarta IV.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8437, '1) DIPA BNPB Tahun 20xx telah dialokasikan dana untuk kegiatan Rutin sebagai dukungan dana pembiayaan Tugas dan Fungsi serta Dana Siap Pakai (DSP/Onca//) Penanggulangan Bencana yang terjadi di wilayah nusantara yang sifatnya mendesak dan kedaruratan, 2) Sehubungan dengan bencana di Provinsi:x0000000x,20000x, »00000x, dan daerah lainnya di seluruh wilayah Indonesia yang berdampak pada kehidupan masyarakatnya segera mendapatkan pertolongan, maka untuk mendukung pelaksanaan kegiatan penanggulangan bencana dimaksud, kamimengajukan permohonan TUP dana DSP/on calkebesar Rproxx.xxx.xxx.xex,xx(terbilang X000000xxK0000KxxKKOOKN) guna kesiapan ketersediaan dana yang memadai,mohon kiranya dapat dipenuhi dalam waktu dekat.
Adapun rincian penggunaan dana serta saldo rekening sebagaimana terlampir.
Demikian, atas bantuan serta perhatiannya, kami ucapkan terima kasih.
Sekretaris Utama Selaku Kuasa Pengguna Anggaran Tembusan Yth:
1. Kepala Badan Nasional Penanggulangan Bencana (sebagai laporan):
2. Direktur Jenderal Anggaran Kementerian Keuangan RI:
3. Direktur Jenderal Perbendaharaan Kementerian Keuangan RI, 4, Direktur Pelaksanaan Anggaran Ditjen. Perbendaharaan Kementerian Keuangan RI:
5. Kepala KPPN Jakarta IV.', 'Lampiran hal. 89', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2014 tentang Petunjuk Pelaksanaan Pengelolaan dan Pertanggungjawaban Keuangan Atas Beban Anggaran Pendapatan dan Belanja Negara Di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8438, 'perka-4-2014', 125, 'lampiran', 'Lampiran hal. 90', NULL, 90, '300, No.300 90 LAMPIRAN VII PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR TAHUN 2014 TENTANG PETUNJUK PELAKSANAAN PENGELOLAAN DAN PERTANGGUNGJAWABAN KEUANGAN ATAS BEBAN ANGGARAN PENDAPATAN DAN BELANJA NEGARA DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA NOTA KESEPAHAMAN ANTARA BADAN NASIONAL PENANGGULANGAN BENCANA (BNPB) DENGAN PEMERINTAH PROVINSI ..................
NOMOR : /BNPB/XX/20XX NOMOR 1 XXXIXXXIXXXIBPBD/2OXX TENTANG BANTUAN DANA SIAP PAKAI UNTUK PENANGANAN SIAGA DARURAT BENCANA BANJIR DI WILAYAH PROVINSI ...
TAHUN 20xx Pada hari ini, ........ tanggal ... yang bertanda ta ngan di bawah ini 4 “«) 1 Sekretaris Utama Badan Nasional Penanggulangan Bencana, dalam hal ini bertindak untuk dan atas nama Badan Nasional Penanggulangan Bencana (BNPB) yang berkedudukan di Jalan Ir. H. Djuanda Nomor 36 Jakarta Pusat, selanjutnya disebut PIHAK KESATU. : Kepala Pelaksana Badan Penanggulangan Bencana Daerah Provinsi ... dalam hal ini bertindak untuk dan atas nama Pemerintah Provinsi ... yang berkedudukan di Jalan ..., Provinsi ... yang selanjutnya disebut PIHAK KEDUA. . bertempat di Jakarta, 91 2014, No.300 PIHAK KESATU dan PIHAK KEDUA secara terpisah disebut sebagai PIHAK dan secara bersama-sama selanjutnya disebut PARA PIHAK.
PARA PIHAK terlebih dahulu menyepakati hal-hal sebagai berikut:');
