INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8451, 'perka-4-2014', 138, 'lampiran', 'Lampiran hal. 99', NULL, 99, 'Damn Sri Sabamingsih, S.Sos 334 644 30- 216 O NIP. 195811171985032001 300, No.300 100 LAMPIRAN XIII/ 1-4 PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA “ NOMOR TAHUN 2014 TENTANG PETUNJUK PELAKSANAAN PENGELOLAAN DAN PERTANGGUNGJAWABAN KEUANGAN ATAS BEBAN ANGGARAN PENDAPATAN DAN BELANJA NEGARA DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BNPB SURAT PERJANJIAN KERJASAMA OPERASIONAL ANTARA BADAN NASIONAL PENANGGULANGAN BENCANA DENGAN BADAN PENANGGULANGAN BENCANA DAERAH PROVINSI NUSA TENGGARA BARAT TENTANG KEGIATAN PENGUATAN KELEMBAGAAN BIDANG KESIAPSIAGAAN TAHUN ANGGARAN 2013 NOMOR: SPKO.S1/BNPB/03/2013 3 NOMOR : SPKO.900/245/BPBD.NTB/1!I/2013 Pada hari ini, Rabu tanggal Dua Puluh bulan Maret tahun Dua Ribu Tiga Belas, bertempat di Jakarta, yang bertanda tangan di bawah ini :
NAMA : Ir. Medi Herlianto, CES, MM JABATAN 1 Direktur Kesiapsiagaan selaku Pejabat Pembuat Komitmen Direktorat Kesiapsiagaan - Dalam hal ini bertindak untuk dan atas nama Badan Nasional Penanggulangan Bencana yang berkedudukan Jl. Ir. H Juanda Nomor 36 - Jakarta Pusat, selanjutnya disebut sebagai PIHAK KESATU. :
NAMA : Drs. Bachrudin, M.Pd JABATAN : Kepala Pelaksana Badan Penanggulangan Bencana Daerah Provinsi Nusa Tenggara Barat Dalam hal ini bertindak untuk dan atas nama Badan Penanggulangan Bencana Daerah Provinsi Nusa Tenggara Barat yang berkedudukan di Jl. Dr. Soedjono Lingkar Selatan, Mataram, untuk selanjutnya disebut sebagai PIHAK KEDUA.');
