INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8468, 'perka-4-2014', 155, 'lampiran', 'Lampiran hal. 115', NULL, 115, 'Selanjutnya berdasarkan data tersebut, BP menyediakan data transaksi dan Realisasi Saldo PK yang ada di BPP untuk dicocokkan dengan BP-BPP terkait.
