INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8475, 'perka-4-2015', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2015 tentang Hibah Dari Pemerintah Pusat Kepada Pemda Dalam Rangka Bantuan Pendanaan Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8475, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2015 tentang Hibah Dari Pemerintah Pusat Kepada Pemda Dalam Rangka Bantuan Pendanaan Rehabilitasi dan Rekonstruksi Pascabencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2015 tentang Hibah Dari Pemerintah Pusat Kepada Pemda Dalam Rangka Bantuan Pendanaan Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8476, 'perka-4-2015', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka penyelenggaraan penanggulangan bencana, perlu dilaksanakan pemulihan kehidupan dan penghidupan masyarakat serta pemulihan pelayanan umum secara terencana, terkoordinasi, dan terpadu;
b. bahwa dalam rangka melakukan rehabilitasi dan rekonstruksi, pemerintah kabupaten/kota wajib menggunakan dana penanggulangan bencana dari APBD kabupaten/kota, dan dalam hal APBD tidak memadai, pemerintah kabupaten/kota dapat meminta bantuan dana kepada pemerintah provinsi dan/atau Pemerintah untuk melaksanakan kegiatan rehabilitasi dan rekonstruksi;
c. bahwa dana bantuan rehabilitasi dan rekonstruksi pascabencana dari Pemerintah Pusat kepada Pemerintah Daerah diberikan dalam bentuk hibah;
d. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, dan huruf c perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Hibah Dari 2 2015, No.1443 Pemerintah Pusat Kepada Pemerintah Daerah Dalam Rangka Bantuan Pendanaan Rehabilitasi Dan Rekonstruksi Pascabencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8476, 'a. bahwa dalam rangka penyelenggaraan penanggulangan bencana, perlu dilaksanakan pemulihan kehidupan dan penghidupan masyarakat serta pemulihan pelayanan umum secara terencana, terkoordinasi, dan terpadu;
b. bahwa dalam rangka melakukan rehabilitasi dan rekonstruksi, pemerintah kabupaten/kota wajib menggunakan dana penanggulangan bencana dari APBD kabupaten/kota, dan dalam hal APBD tidak memadai, pemerintah kabupaten/kota dapat meminta bantuan dana kepada pemerintah provinsi dan/atau Pemerintah untuk melaksanakan kegiatan rehabilitasi dan rekonstruksi;
c. bahwa dana bantuan rehabilitasi dan rekonstruksi pascabencana dari Pemerintah Pusat kepada Pemerintah Daerah diberikan dalam bentuk hibah;
d. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, dan huruf c perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Hibah Dari 2 2015, No.1443 Pemerintah Pusat Kepada Pemerintah Daerah Dalam Rangka Bantuan Pendanaan Rehabilitasi Dan Rekonstruksi Pascabencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2015 tentang Hibah Dari Pemerintah Pusat Kepada Pemda Dalam Rangka Bantuan Pendanaan Rehabilitasi dan Rekonstruksi Pascabencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8477, 'perka-4-2015', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);
2. Undang-Undang Nomor 24 tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 244, Tambahan Lembaran Negara Republik Indonesia Nomor 5587);
4. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
5. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang pendanaan Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
6. Peraturan Pemerintah Nomor 2 Tahun 2012 tentang Hibah Daerah (Lembaran Negara Republik Indonesia Tahun 2012 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 5272);
7. Peraturan Presiden Nomor 4 Tahun 2015 tentang Perubahan Keempat Peraturan Presiden Nomor 54 Tahun 2010 tentang Pengadaan Barang/Jasa Pemerintah (Lembaran Negara Republik Indonesia Tahun 2015 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 5655);
8. Peraturan Menteri Keuangan Nomor 162/PMK.07/2015 Tanggal 21 Agustus 2015 tentang Hibah dari Pemerintah Pusat kepada Pemerintah Daerah Dalam Rangka Bantuan Pendanaan Rehabilitasi dan Rekonstruksi Pascabencana (Berita Negara Republik Indonesia Tahun 2015 Nomor 1263);
9. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 17 Tahun 2010 tentang Pedoman Umum Penyelenggaraan Rehabilitasi dan Rekonstruksi 2015, No.1443 3 Pascabencana (Berita Negara Republik Indonesia Tahun 2014 Nomor 1553);
10. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 15 Tahun 2011 tentang Pedoman Pengkajian Kebutuhan Pascabencana;
11. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2012 tentang Pedoman Pemantauan dan Evaluasi Pelaksanaan Rehabilitasi dan Rekonstruksi Pascabencana;');
