INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8506, 'perka-4-2016', 7, 'pasal', 'Pasal 4', 'BAB III KURIKULUM, BAHAN AJAR, PEMBELAJARAN, DAN PENILAIAN; Bagian Kesatu Kurikulum', 6, '(1) Kurikulum Diklat PB dikembangkan berdasarkan hasil analisis kebutuhan.
(2) Analisis kebutuhan sebagaimana yang dimaksud pada ayat (1) merupakan kesenjangan kemampuan pegawai 2016, No.1836 yang terjadi karena adanya perbedaan antara kemampuan sebagai tuntutan pelaksanaan tugas dalam organisasi dengan kemampuan yang ada.
(3) Analisis kebutuhan sebagaimana dimaksud pada ayat (1) dilakukan oleh Pusdiklat PB Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8506, '(1) Kurikulum Diklat PB dikembangkan berdasarkan hasil analisis kebutuhan.
(2) Analisis kebutuhan sebagaimana yang dimaksud pada ayat (1) merupakan kesenjangan kemampuan pegawai 2016, No.1836 yang terjadi karena adanya perbedaan antara kemampuan sebagai tuntutan pelaksanaan tugas dalam organisasi dengan kemampuan yang ada.
(3) Analisis kebutuhan sebagaimana dimaksud pada ayat (1) dilakukan oleh Pusdiklat PB Badan Nasional Penanggulangan Bencana.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2016 tentang Pendidikan dan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8507, 'perka-4-2016', 8, 'pasal', 'Pasal 5', 'BAB III KURIKULUM, BAHAN AJAR, PEMBELAJARAN, DAN PENILAIAN; Bagian Kesatu Kurikulum', 7, '(1) Kurikulum setiap program Diklat PB disusun berbasis kompetensi dengan berpedoman pada standar profesi Kerangka Kerja Nasional Indonesia.
(2) Kurikulum sebagaimana dimaksud pada ayat (1) disusun oleh Pusdiklat PB Badan Nasional Penanggulangan Bencana.
(3) Kurikulum Diklat PB meliputi:
a. standar kompetensi;
b. kompetensi dasar;
c. indikator pencapaian kompetensi;
d. metode Diklat PB;
e. alokasi waktu;
f. media pembelajaran; dan
g. sumber belajar.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8507, '(1) Kurikulum setiap program Diklat PB disusun berbasis kompetensi dengan berpedoman pada standar profesi Kerangka Kerja Nasional Indonesia.
(2) Kurikulum sebagaimana dimaksud pada ayat (1) disusun oleh Pusdiklat PB Badan Nasional Penanggulangan Bencana.
(3) Kurikulum Diklat PB meliputi:
a. standar kompetensi;
b. kompetensi dasar;
c. indikator pencapaian kompetensi;
d. metode Diklat PB;
e. alokasi waktu;
f. media pembelajaran; dan
g. sumber belajar.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2016 tentang Pendidikan dan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8508, 'perka-4-2016', 9, 'pasal', 'Pasal 6', 'BAB III KURIKULUM, BAHAN AJAR, PEMBELAJARAN, DAN PENILAIAN; Bagian Kesatu Kurikulum', 7, '(1) Standar kompetensi sebagaimana dimaksud dalam Pasal 5 ayat (3) huruf a mencakup sikap pengetahuan dan kecakapan.
(2) Standar kompetensi sebagaimana dimaksud pada ayat (1) harus dikuasai oleh peserta Diklat PB pada setiap tingkatan materi untuk kualifikasi jenjang operator, teknisi/analis dan ahli pada tahap prabencana, saat tanggap darurat bencana, dan pascabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8508, '(1) Standar kompetensi sebagaimana dimaksud dalam Pasal 5 ayat (3) huruf a mencakup sikap pengetahuan dan kecakapan.
(2) Standar kompetensi sebagaimana dimaksud pada ayat (1) harus dikuasai oleh peserta Diklat PB pada setiap tingkatan materi untuk kualifikasi jenjang operator, teknisi/analis dan ahli pada tahap prabencana, saat tanggap darurat bencana, dan pascabencana.', 'Pasal 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2016 tentang Pendidikan dan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8509, 'perka-4-2016', 10, 'pasal', 'Pasal 7', 'BAB III KURIKULUM, BAHAN AJAR, PEMBELAJARAN, DAN PENILAIAN; Bagian Kesatu Kurikulum', 7, 'Kompetensi dasar sebagaimana dimaksud dalam Pasal 5 ayat
