INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8532, 'perka-4-2016', 33, 'pasal', 'Pasal 30', 'BAB XIII KETENTUAN PENUTUP', 17, 'Peraturan Kepala Badan ini mulai berlaku pada tanggal diundangkan.
