INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8533, 'perka-4-2016', 34, 'lain', 'Penutup', NULL, 17, 'Ditetapkan di Jakarta pada tanggal 28 November 2016 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 1 Desember 2016 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd WIDODO EKATJAHJANA');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8533, 'Ditetapkan di Jakarta pada tanggal 28 November 2016 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 1 Desember 2016 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd WIDODO EKATJAHJANA', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2016 tentang Pendidikan dan Pelatihan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8534, 'perka-4-2017', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2017 tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8534, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2017 tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2017 tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8535, 'perka-4-2017', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa untuk mewujudkan penyelenggaraan negara yang bersih dan bebas dari korupsi, kolusi dan nepotisme di lingkungan Badan Nasional Penanggulangan Bencana, perlu upaya mendorong terwujudnya integritas pengelola dan penyelenggaraan negara;
b. bahwa untuk terwujudnya integritas pengelola dan penyelenggara negara di lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam huruf a, perlu diatur pengendalian terhadap Gratifikasi;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8535, 'a. bahwa untuk mewujudkan penyelenggaraan negara yang bersih dan bebas dari korupsi, kolusi dan nepotisme di lingkungan Badan Nasional Penanggulangan Bencana, perlu upaya mendorong terwujudnya integritas pengelola dan penyelenggaraan negara;
b. bahwa untuk terwujudnya integritas pengelola dan penyelenggara negara di lingkungan Badan Nasional Penanggulangan Bencana sebagaimana dimaksud dalam huruf a, perlu diatur pengendalian terhadap Gratifikasi;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2017 tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8536, 'perka-4-2017', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Negara yang Bersih dan Bebas dari 2017, No.1440 -2- Korupsi, Kolusi, dan Nepotisme, (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);
2. Undang-Undang Nomor 31 Tahun 1999 tentang Pemberantasan Tindak Pidana Korupsi (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 78, Tambahan Lembaran Negara Republik Indonesia Nomor 4301) sebagaimana telah diubah dengan Undang-Undang Nomor 20 Tahun 2001 tentang Pemberantasan Tindak Pidana Korupsi (Lembaran Negara Republik Indonesia Tahun 2001 Nomor 134, Tambahan Lembaran Negara Republik Indonesia Nomor 4150);
3. Peraturan Presiden Nomor 55 Tahun 2012 tentang Strategi Nasional Pencegahan dan Pemberantasan Korupsi Jangka Panjang Tahun 2012- 2025 (Lembaran Negara Republik Indonesia Tahun 2012 Nomor 122);
4. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2013 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2013 Nomor 1441);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8536, '1. Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Negara yang Bersih dan Bebas dari 2017, No.1440 -2- Korupsi, Kolusi, dan Nepotisme, (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);
2. Undang-Undang Nomor 31 Tahun 1999 tentang Pemberantasan Tindak Pidana Korupsi (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 78, Tambahan Lembaran Negara Republik Indonesia Nomor 4301) sebagaimana telah diubah dengan Undang-Undang Nomor 20 Tahun 2001 tentang Pemberantasan Tindak Pidana Korupsi (Lembaran Negara Republik Indonesia Tahun 2001 Nomor 134, Tambahan Lembaran Negara Republik Indonesia Nomor 4150);
3. Peraturan Presiden Nomor 55 Tahun 2012 tentang Strategi Nasional Pencegahan dan Pemberantasan Korupsi Jangka Panjang Tahun 2012- 2025 (Lembaran Negara Republik Indonesia Tahun 2012 Nomor 122);
4. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2013 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana (Berita Negara Republik Indonesia Tahun 2013 Nomor 1441);', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2017 tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8537, 'perka-4-2017', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENGENDALIAN GRATIFIKASI DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8537, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENGENDALIAN GRATIFIKASI DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2017 tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8538, 'perka-4-2017', 4, 'pasal', 'Pasal 1', 'BAB II PENCEGAHAN GRATIFIKASI', 2, 'Dalam Peraturan Kepala Badan ini yang dimaksud dengan:
1. Gratifikasi adalah pemberian uang, barang, rabat (discount), komisi, pinjaman tanpa bunga, tiket 2017, No.1440 perjalanan, fasilitas penginapan, perjalanan wisata, pengobatan cuma-cuma, dan fasilitas lainnya, baik yang diterima di dalam negeri maupun di luar negeri, yang dilakukan dengan menggunakan sarana elektronik atau tanpa sarana elektronik.
2. Kepala Badan adalah Kepala Badan Nasional Penanggulangan Bencana.
3. Pegawai Aparatur Sipil Negara yang selanjutnya disebut Pegawai adalah Pegawai Negeri Sipil, Pegawai pemerintah dengan perjanjian kerja, dan penyelenggara negara yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan digaji berdasarkan ketentuan peraturan perundang-undangan.
4. Pihak Lain adalah seluruh pihak, warga negara, penduduk sebagai perseorangan, kelompok, badan hukum yang memiliki kepentingan terhadap kebijakan, berkedudukan sebagai penerima manfaat pelayanan publik, atau dapat terkait dan berpengaruh secara langsung ataupun tidak langsung terhadap suatu kebijakan Badan Nasional Penanggulangan Bencana.
5. 6. Berlaku Umum adalah perlakuan yang sama bersifat objektif dan yang menyangkut khusus/tertentu saja.
7. Unit Pengendalian Gratifikasi yang selanjutnya disingkat UPG adalah kelompok kerja berkedudukan di Inspektorat Utama beranggotakan dari unit kerja di lingkungan Badan Nasional Penanggulangan Bencana.
8. Kedinasan adalah seluruh aktivitas resmi pegawai yang berhubungan dengan pelaksanaan tugas fungsi serta jabatannya.
2017, No.1440 -4-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8538, 'Dalam Peraturan Kepala Badan ini yang dimaksud dengan:
1. Gratifikasi adalah pemberian uang, barang, rabat (discount), komisi, pinjaman tanpa bunga, tiket 2017, No.1440 perjalanan, fasilitas penginapan, perjalanan wisata, pengobatan cuma-cuma, dan fasilitas lainnya, baik yang diterima di dalam negeri maupun di luar negeri, yang dilakukan dengan menggunakan sarana elektronik atau tanpa sarana elektronik.
2. Kepala Badan adalah Kepala Badan Nasional Penanggulangan Bencana.
3. Pegawai Aparatur Sipil Negara yang selanjutnya disebut Pegawai adalah Pegawai Negeri Sipil, Pegawai pemerintah dengan perjanjian kerja, dan penyelenggara negara yang diangkat oleh pejabat pembina kepegawaian dan diserahi tugas dalam suatu jabatan pemerintahan atau diserahi tugas negara lainnya dan digaji berdasarkan ketentuan peraturan perundang-undangan.
4. Pihak Lain adalah seluruh pihak, warga negara, penduduk sebagai perseorangan, kelompok, badan hukum yang memiliki kepentingan terhadap kebijakan, berkedudukan sebagai penerima manfaat pelayanan publik, atau dapat terkait dan berpengaruh secara langsung ataupun tidak langsung terhadap suatu kebijakan Badan Nasional Penanggulangan Bencana.
5. 6. Berlaku Umum adalah perlakuan yang sama bersifat objektif dan yang menyangkut khusus/tertentu saja.
7. Unit Pengendalian Gratifikasi yang selanjutnya disingkat UPG adalah kelompok kerja berkedudukan di Inspektorat Utama beranggotakan dari unit kerja di lingkungan Badan Nasional Penanggulangan Bencana.
8. Kedinasan adalah seluruh aktivitas resmi pegawai yang berhubungan dengan pelaksanaan tugas fungsi serta jabatannya.
2017, No.1440 -4-', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2017 tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8539, 'perka-4-2017', 5, 'pasal', 'Pasal 2', 'BAB II PENCEGAHAN GRATIFIKASI', 4, 'Gratifikasi yang diterima oleh Pegawai terdiri atas:
a. gratifikasi wajib dilaporkan; dan
b. gratifikasi tidak wajib dilaporkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8539, 'Gratifikasi yang diterima oleh Pegawai terdiri atas:
a. gratifikasi wajib dilaporkan; dan
b. gratifikasi tidak wajib dilaporkan.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2017 tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8540, 'perka-4-2017', 6, 'pasal', 'Pasal 3', 'BAB II PENCEGAHAN GRATIFIKASI', 4, 'Gratifikasi wajib dilaporkan sebagaimana dimaksud dalam Pasal 2 huruf a yang diterima oleh Pegawai berhubungan dengan jabatannya dan berlawanan dengan kewajiban atau tugasnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8540, 'Gratifikasi wajib dilaporkan sebagaimana dimaksud dalam Pasal 2 huruf a yang diterima oleh Pegawai berhubungan dengan jabatannya dan berlawanan dengan kewajiban atau tugasnya.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2017 tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8541, 'perka-4-2017', 7, 'pasal', 'Pasal 4', 'BAB III UNIT PENGENDALIAN GRATIFIKASI (UPG)', 4, 'Gratifikasi tidak wajib dilaporkan sebagaimana dimaksud dalam Pasal 2 huruf b meliputi:
a. hadiah langsung/undian, diskon/rabat, voucher, point rewards, atau souvenir yang Berlaku Umum dan tidak terkait dengan Kedinasan;
b. prestasi akademis atau nonakademis (kejuaraan/ perlombaan/kompetisi) dengan biaya sendiri dan tidak terkait dengan Kedinasan;
c. keuntungan/bunga dari penempatan dana, investasi atau kepemilikan saham pribadi yang Berlaku Umum dan tidak terkait dengan Kedinasan;
d. kompensasi atas profesi di luar Kedinasan yang tidak terkait dengan tugas fungsi dari pegawai negeri atau penyelenggara negara, dan tidak melanggar benturan kepentingan dan kode etik Pegawai;
e. pemberian karena hubungan keluarga sedarah dalam garis keturunan lurus dua derajat atau dalam garis keturunan ke samping satu derajat sepanjang tidak mempunyai benturan kepentingan dengan penerima Gratifikasi;
f. pemberian karena hubungan keluarga sedarah dalam garis keturunan lurus satu derajat atau dalam garis 2017, No.1440 keturunan ke samping satu derajat sepanjang tidak mempunyai benturan kepentingan dengan penerima Gratifikasi;
g. pemberian yang berasal dari pihak lain sebagai hadiah perkawinan, khitanan anak, ulang tahun, kegiatan keagamaan/adat/tradisi, dengan nilai keseluruhan paling banyak Rpl.000.000,00 (satu juta rupiah) dari masing-masing pemberi pada setiap kegiatan atau peristiwa tersebut dan bukan dari pihak yang mempunyai benturan kepentingan dengan penerima Gratifikasi; dan
h. pemberian dari pihak lain terkait dengan musibah dan bencana, dan bukan dari pihak yang mempunyai benturan kepentingan dengan penerima Gratifikasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8541, 'Gratifikasi tidak wajib dilaporkan sebagaimana dimaksud dalam Pasal 2 huruf b meliputi:
a. hadiah langsung/undian, diskon/rabat, voucher, point rewards, atau souvenir yang Berlaku Umum dan tidak terkait dengan Kedinasan;
b. prestasi akademis atau nonakademis (kejuaraan/ perlombaan/kompetisi) dengan biaya sendiri dan tidak terkait dengan Kedinasan;
c. keuntungan/bunga dari penempatan dana, investasi atau kepemilikan saham pribadi yang Berlaku Umum dan tidak terkait dengan Kedinasan;
d. kompensasi atas profesi di luar Kedinasan yang tidak terkait dengan tugas fungsi dari pegawai negeri atau penyelenggara negara, dan tidak melanggar benturan kepentingan dan kode etik Pegawai;
e. pemberian karena hubungan keluarga sedarah dalam garis keturunan lurus dua derajat atau dalam garis keturunan ke samping satu derajat sepanjang tidak mempunyai benturan kepentingan dengan penerima Gratifikasi;
f. pemberian karena hubungan keluarga sedarah dalam garis keturunan lurus satu derajat atau dalam garis 2017, No.1440 keturunan ke samping satu derajat sepanjang tidak mempunyai benturan kepentingan dengan penerima Gratifikasi;
g. pemberian yang berasal dari pihak lain sebagai hadiah perkawinan, khitanan anak, ulang tahun, kegiatan keagamaan/adat/tradisi, dengan nilai keseluruhan paling banyak Rpl.000.000,00 (satu juta rupiah) dari masing-masing pemberi pada setiap kegiatan atau peristiwa tersebut dan bukan dari pihak yang mempunyai benturan kepentingan dengan penerima Gratifikasi; dan
h. pemberian dari pihak lain terkait dengan musibah dan bencana, dan bukan dari pihak yang mempunyai benturan kepentingan dengan penerima Gratifikasi.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2017 tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8542, 'perka-4-2017', 8, 'pasal', 'Pasal 5', 'BAB III UNIT PENGENDALIAN GRATIFIKASI (UPG)', 5, '(1) Pengendalian gratifikasi di lingkungan Badan Nasional Penanggulangan Bencana dilaksanakan oleh Kepala Badan.
(2) Dalam melakukan pengendalian Gratifikasi sebagaimana dimaksud pada ayat (1), Kepala Badan membentuk UPG.
(3) UPG sebagaimana dimaksud pada ayat (2) berkedudukan di Inpektorat Utama dan bertanggung jawab kepada Kepala Badan melalui Inpektur Utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8542, '(1) Pengendalian gratifikasi di lingkungan Badan Nasional Penanggulangan Bencana dilaksanakan oleh Kepala Badan.
(2) Dalam melakukan pengendalian Gratifikasi sebagaimana dimaksud pada ayat (1), Kepala Badan membentuk UPG.
(3) UPG sebagaimana dimaksud pada ayat (2) berkedudukan di Inpektorat Utama dan bertanggung jawab kepada Kepala Badan melalui Inpektur Utama.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2017 tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8543, 'perka-4-2017', 9, 'pasal', 'Pasal 6', 'BAB IV TATA CARA PELAPORAN GRATIFIKASI', 5, '(1) Unsur keanggotaan UPG terdiri atas:
a. ketua merangkap anggota;
b. wakil ketua merangkap anggota;
c. sekretaris merangkap anggota; dan
d. anggota.
(2) Ketua UPG sebagaimana dimaksud pada ayat (1) huruf a dijabat oleh Inspektur.
2017, No.1440 -6-
(3) Wakil ketua UPG sebagaimana dimaksud pada ayat (1) huruf b dijabat oleh auditor madya.
(4) Sekretaris UPG sebagaimana dimaksud pada ayat (1) huruf c dijabat oleh Kepala Subbagian Tata Usaha Inspektorat Utama.
(5) Anggota UPG sebagaimana dimaksud pada ayat (1) huruf d berasal dari unsur di lingkungan Badan Nasional Penanggulangan Bencana yaitu.:
a. pejabat struktural;
b. pejabat fungsional tertentu; dan
c. pejabat fungsional umum.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8543, '(1) Unsur keanggotaan UPG terdiri atas:
a. ketua merangkap anggota;
b. wakil ketua merangkap anggota;
c. sekretaris merangkap anggota; dan
d. anggota.
(2) Ketua UPG sebagaimana dimaksud pada ayat (1) huruf a dijabat oleh Inspektur.
2017, No.1440 -6-
(3) Wakil ketua UPG sebagaimana dimaksud pada ayat (1) huruf b dijabat oleh auditor madya.
(4) Sekretaris UPG sebagaimana dimaksud pada ayat (1) huruf c dijabat oleh Kepala Subbagian Tata Usaha Inspektorat Utama.
(5) Anggota UPG sebagaimana dimaksud pada ayat (1) huruf d berasal dari unsur di lingkungan Badan Nasional Penanggulangan Bencana yaitu.:
a. pejabat struktural;
b. pejabat fungsional tertentu; dan
c. pejabat fungsional umum.', 'Pasal 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 4 Tahun 2017 tentang Pengendalian Gratifikasi di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8544, 'perka-4-2017', 10, 'pasal', 'Pasal 7', 'BAB IV TATA CARA PELAPORAN GRATIFIKASI', 6, '(1) Penyampaian laporan penerimaan Gratifikasi oleh Pelapor dilakukan dengan ketentuan sebagai berikut:
a. pelapor menyampaikan laporan penerimaan Gratifikasi kepada Komisi Pemberantasan Korupsi melalui UPG pada unit kerja Pelapor dengan mengisi formulir laporan Gratifikasi.
b. pelapor menyampaikan laporan penerimaan Gratifikasi baik secara manual maupun melalui media elektronik.
c. laporan penerima Gratifikasi disampaikan paling lambat 7 (tujuh) hari kerja;
d. penyampaian laporan penerima Gratifikasi melebihi 7 (tujuh) hari kerja terhitung sejak diterimanya Gratifikasi, pelapor menyampaikan laporan penerimaan Gratifikasi secara langsung kepada Komisi Pemberatasan Korupsi; dan
e. jika pelapor menyampaikan laporan penerimaan Gratifikasi melalui UPG sebagaimana dimaksud dalam huruf a, laporan penerimaan Gratifikasi memuat:
1. nama;
2017, No.1440
2. alamat lengkap;
3. jabatan;
4. tempat dan waktu penerimaan Gratifikasi;
5. uraian jenis Gratifikasi dengan melampirkan bukti dalam bentuk sampel atau foto;
6. nilai atau taksiran nilai Gratifikasi yang diterima; dan
7. kronologis penerimaan Gratifikasi.
(2) Laporan penerimaan Gratifikasi sebagaimana dimaksud pada ayat (1) selanjutnya dicatat dan dilakukan reviu oleh UPG pada unit kerja pelapor.
(3) Reviu sebagaimana dimaksud pada ayat (2) dilakukan oleh UPG terdiri atas:
a. reviu atas kelengkapan data/berkas terkait laporan penerimaan Gratifikasi; dan
b. reviu atas laporan penerimaan Gratifikasi.
(4) UPG pada unit kerja pelapor, dapat meminta keterangan/konfirmasi laporan penerimaan Gratifikasi kepada Pelapor atas hasil reviu.
(5) Jika hasil reviu sebagaimana dimaksud pada ayat (4) dinyatakan kategori Gratifikasi maka UPG pada unit kerja pelapor menyampaikan laporan penerimaan Gratifikasi tersebut kepada Komisi Pemberantasan Korupsi.
(6) Laporan Gratifikasi kepada Komisi Pemberantasan Korupsi paling lambat 7 (tujuh) hari kerja terhitung sejak tanggal laporan penerimaan Gratifikasi diterima.
(7) Jika penerima Gratifikasi menyampaikan secara langsung kepada Komisi Pemberantasan Korupsi, harus menyampaikan laporan Gratifikasi juga kepada UPG pada unit kerjanya.
(8) Menyampaikan laporan Gratifikasi sebagaimana dimaksud pada ayat (7) disertai dengan bukti lapor dari Komisi Pemberantasan Korupsi.
2017, No.1440 -8-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8544, '(1) Penyampaian laporan penerimaan Gratifikasi oleh Pelapor dilakukan dengan ketentuan sebagai berikut:
