INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8556, 'perka-5-2009', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, tera khir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 www.peraturan.go.id 2014, No.1413 2 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Keputusan Presiden Nomor 29/M Tahun 2008 tanggal 23 April 2008 tentang Pengangkatan Kepala Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8556, '1. Undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, tera khir dengan Undang-Undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 www.peraturan.go.id 2014, No.1413 2 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lembaga Internasional dan Lembaga Asing Nonpemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
6. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
7. Keputusan Presiden Nomor 29/M Tahun 2008 tanggal 23 April 2008 tentang Pengangkatan Kepala Badan Nasional Penanggulangan Bencana.', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8557, 'perka-5-2009', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN BANTUAN PERALATAN.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8557, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN BANTUAN PERALATAN.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8558, 'perka-5-2009', 4, 'pasal', 'Pasal 1', NULL, 2, 'Pedoman Bantuan Peralatan merupakan panduan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/Lembaga dan penyelenggara penanggulangan bencana agar pemberian bantuan peralatan kepada korban bencana dapat dilaksanakan dengan cepat, tepat, terpadu, efektif, efisien dan akuntabel. www.peraturan.go.id 3 2014, No.1413');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8558, 'Pedoman Bantuan Peralatan merupakan panduan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/Lembaga dan penyelenggara penanggulangan bencana agar pemberian bantuan peralatan kepada korban bencana dapat dilaksanakan dengan cepat, tepat, terpadu, efektif, efisien dan akuntabel. www.peraturan.go.id 3 2014, No.1413', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8559, 'perka-5-2009', 5, 'pasal', 'Pasal 2', NULL, 3, 'Pedoman sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian yang tidak terpisah kan dari peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8559, 'Pedoman sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian yang tidak terpisah kan dari peraturan ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8560, 'perka-5-2009', 6, 'pasal', 'Pasal 3', NULL, 3, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8560, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8561, 'perka-5-2009', 7, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta Pada tanggal 25 September 2009 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN www.peraturan.go.id 2014, No.1413 4 PEDOMAN BANTUAN PERALATAN PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan negara yang berada di wilayah rawan bencana.
Kerawanan bencana ini ditandai dengan banyaknya bencana yang terjadi seperti : gempa bumi, tsunami, letusan gunung api, banjir, tanah longsor, angin puting beliung, kekeringan, kebakaran hutan dan lahan, kegagalan teknologi, konflik sosial, teroris, pandemi yang mengakibatkan korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
Pemerintah dan pemerintah daerah berkewajiban memberikan bantuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8561, 'Ditetapkan di Jakarta Pada tanggal 25 September 2009 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN www.peraturan.go.id 2014, No.1413 4 PEDOMAN BANTUAN PERALATAN PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan negara yang berada di wilayah rawan bencana.
Kerawanan bencana ini ditandai dengan banyaknya bencana yang terjadi seperti : gempa bumi, tsunami, letusan gunung api, banjir, tanah longsor, angin puting beliung, kekeringan, kebakaran hutan dan lahan, kegagalan teknologi, konflik sosial, teroris, pandemi yang mengakibatkan korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
Pemerintah dan pemerintah daerah berkewajiban memberikan bantuan', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8562, 'perka-5-2009', 8, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'untuk meringankan penderitaan korban bencana. Bantuan dapat dihimpun dan dikerahkan dari Pemerintah dan pemerintah daerah yang berasal dari APBN/APBD, bantuan Dunia Usaha serta Masyarakat dalam dan luar negeri, berupa peralatan untuk penanggulangan bencana.
Bantuan peralatan dibutuhkan untuk penanggulangan bencana khususnya pada saat terjadi bencana. Dukungan bantuan peralatan harus tepat waktu, lokasi, sasaran, kualitas, kuantitas, dan kebutuhan. Untuk mencapai pendistribusian bantuan peralatan yang efektif, efisien, cepat 5 2014, No.1413 dan akuntabel perlu disusun Pedoman Bantuan Peralatan untuk penanggulangan bencana.
B. Maksud dan Tujuan
1. Maksud pedoman ini adalah sebagai panduan bagi seluruh petugas penanggulangan bencana terutama yang berkaitan dengan pengelolaan bantuan peralatan.
2. Tujuan dari pedoman ini adalah agar proses :
a. Perencanaan bantuan peralatan dalam penanggulangan bencana sesuai kebutuhan.
b. Pengadaan bantuan peralatan dalam penanggulangan bencana mengacu pada peraturan yang berlaku sesuai dengan jumlah, jenis dan mutu bantuan.
c. Pendistribusian bantuan peralatan dalam penanggulangan bencana efektif, efisien, tepat sasaran dan akuntabel.
C. Landasan Hukum
1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723),');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8562, 'untuk meringankan penderitaan korban bencana. Bantuan dapat dihimpun dan dikerahkan dari Pemerintah dan pemerintah daerah yang berasal dari APBN/APBD, bantuan Dunia Usaha serta Masyarakat dalam dan luar negeri, berupa peralatan untuk penanggulangan bencana.
