INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8573, 'perka-5-2011', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2011 tentang Penetapan Rencana Aksi Rehabilitasi Dan Rekonstuksi Wilayah Pasca Rencana Erupsi Gunung Merapi Di Provinsi Daerah Istimewa Yogyakarta Dan Provinsi Jawa Tengah Tahun 2011-2013');
