INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8574, 'perka-5-2011', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka pelaksanaan ketentuan Pasal 57 ayat (2) dan Pasal 76 ayat (2) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, diperlukan pengaturan tentang perencanaan, penganggaran, pelaksanaan, pelaporan dan pertanggungjawaban penggunaan dana penanggulangan bencana yang bersumber dari APBN dan APBD serta dana lain yang sah dan tidak mengikat pada tahap pasca-bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana ten tang Penetapan Rencana Aksi Rehabilitasi dan Rekonstruksi Wilayah Pasca Bencana Erupsi Cunung Merapi di Provinsi Daerah Istimewa Yogyakarta dan ProvinsiJawa Tengah Tahun 2011 - 2013;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8574, 'a. bahwa dalam rangka pelaksanaan ketentuan Pasal 57 ayat (2) dan Pasal 76 ayat (2) Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana, diperlukan pengaturan tentang perencanaan, penganggaran, pelaksanaan, pelaporan dan pertanggungjawaban penggunaan dana penanggulangan bencana yang bersumber dari APBN dan APBD serta dana lain yang sah dan tidak mengikat pada tahap pasca-bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana ten tang Penetapan Rencana Aksi Rehabilitasi dan Rekonstruksi Wilayah Pasca Bencana Erupsi Cunung Merapi di Provinsi Daerah Istimewa Yogyakarta dan ProvinsiJawa Tengah Tahun 2011 - 2013;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2011 tentang Penetapan Rencana Aksi Rehabilitasi Dan Rekonstuksi Wilayah Pasca Rencana Erupsi Gunung Merapi Di Provinsi Daerah Istimewa Yogyakarta Dan Provinsi Jawa Tengah Tahun 2011-2013');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8575, 'perka-5-2011', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lernbaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);
2. Undang-undang Nomor 25 Tahun 2004 tentang Sistem Perencanaan Pembangunan Nasional (Lembaran Negara Tahun 2004 Nomor 104, Tarnbahan Lembaran Negara Nomor 4421);
3. Undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lernbaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lernbaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah beberapa kali, terakhir dengan Undang-undang Nomor 12 Tahun 2008 tentang Perubahan Kedua atas Undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lernbaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Republik Indonesia Nomor 4844) ;
4. Undang-undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lernbaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
5. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
6. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lernbaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
7. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran Serta Lernbaga Internasional dan Lernbaga Asing Nonpemerintah Dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 44, Tambahan Lernbaran Negara Republik Indonesia Nomor 4830);
8. Peraturan Presiden Nomor 8 Tahun 2008 ten tang Badan Nasional Penanggulangan Bencana; . 9. Keputusan Presiden Nomor 16 Tahun 2011 tentang Tim Koordinasi Rehabilitasi dan Rekonstruksi Wilayah Pasca Bencana Erupsi Gunung Merapi di Provinsi Daerah Istimewa Yogyakarta dan Provinsi jawa Tengah;');
