INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8576, 'perka-5-2011', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENUAPAN RENCANA AKSI REHABIUTASI DAN REKONsrRUKSI WILAYAH PASCA BENCANA ERUPSI GUNUNG MERAPI DI PROVINSI DAERAH ISTIMEWA YOGYAKARTA DAN PROVINSI JAWA TENGAH TAHUN 2011 - 2013. z');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8576, 'Menetapkan PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PENUAPAN RENCANA AKSI REHABIUTASI DAN REKONsrRUKSI WILAYAH PASCA BENCANA ERUPSI GUNUNG MERAPI DI PROVINSI DAERAH ISTIMEWA YOGYAKARTA DAN PROVINSI JAWA TENGAH TAHUN 2011 - 2013. z', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2011 tentang Penetapan Rencana Aksi Rehabilitasi Dan Rekonstuksi Wilayah Pasca Rencana Erupsi Gunung Merapi Di Provinsi Daerah Istimewa Yogyakarta Dan Provinsi Jawa Tengah Tahun 2011-2013');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8577, 'perka-5-2011', 4, 'pasal', 'Pasal 1', NULL, 3, 'Rencana Alesi Rehabilitasi dan Rekonstruksi Wilayah Pasca Bencana Erupsi Gunung Merapi di Provinsi Daerah Istimewa Yogyakarta dan Provinsi Jawa Tengah iru merupakan panduanl acuan bagi pemerintah, pemerintah provinsi, pemerintah kabupaten/kota dan pihak-pihak lain yang terkait dalam kegiatan rehabilitasi dan rekonstruksi pasca bencana erupsi gunung Merapi di Provinsi Daerah Istimewa Yogyakarta dan ProvinsiJawa Tengah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8577, 'Rencana Alesi Rehabilitasi dan Rekonstruksi Wilayah Pasca Bencana Erupsi Gunung Merapi di Provinsi Daerah Istimewa Yogyakarta dan Provinsi Jawa Tengah iru merupakan panduanl acuan bagi pemerintah, pemerintah provinsi, pemerintah kabupaten/kota dan pihak-pihak lain yang terkait dalam kegiatan rehabilitasi dan rekonstruksi pasca bencana erupsi gunung Merapi di Provinsi Daerah Istimewa Yogyakarta dan ProvinsiJawa Tengah.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2011 tentang Penetapan Rencana Aksi Rehabilitasi Dan Rekonstuksi Wilayah Pasca Rencana Erupsi Gunung Merapi Di Provinsi Daerah Istimewa Yogyakarta Dan Provinsi Jawa Tengah Tahun 2011-2013');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8578, 'perka-5-2011', 5, 'pasal', 'Pasal 2', NULL, 3, 'Rencana Alesi Rehabilitasi dan Rekonstruksi sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian tak terpisahkan dari peraturan ini.');
