INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8593, 'a. bahwa dalam rangka pelaksanaan penyimpanan kendaraan penanggulangan bencana yang dihibahkan Badan Nasional Penanggulangan Bencana kepada Badan Penanggulangan Bencana Daerah Provinsi/Kabupaten/ Kota perlu diatur Tata Cara Penyimpanan Kendaraan Penanggulangan Bencana;
