INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8594, 'perka-5-2015', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5 Tambahan Lembaran Negara Republik Indonesia Nomor 4355);
