INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8611, 'perka-5-2016', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa beberapa ketentuan dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2009 tentang Petunjuk Pelaksanaan Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana masih terdapat kekurangan dan sudah tidak sesuai lagi dengan pedoman umum tata naskah dinas sebagaimana diatur dalam Peraturan Menteri Pendayagunaan Apatur Negara dan Reformasi Birokrasi Nomor 80 Tahun 2012 tentang Pedoman Tata Naskah Dinas Instansi Pemerintah (Berita Negara Republik Indonesia Tahun 2013 Nomor 69);
b. bahwa Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2009 tentang Petunjuk Pelaksanaan Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana perlu disesuaikan dengan ketentuan peraturan perundang-undangan dan perkembangan keadaan saat ini sehingga perlu diganti;
c. bahwa berdasarkan pertimbangan sebagaimana 2016, No.1970 -2- dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana;');
