INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8619, 'perka-5-2016', 9, 'lain', 'Penutup', NULL, 5, 'Ditetapkan di Jakarta pada tanggal 19 Desember 2016 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 22 Desember 2016 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd.
WIDODO EKATJAHJANA 2016, No.1970 "');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8619, 'Ditetapkan di Jakarta pada tanggal 19 Desember 2016 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, ttd.
WILLEM RAMPANGILEI Diundangkan di Jakarta pada tanggal 22 Desember 2016 DIREKTUR JENDERAL PERATURAN PERUNDANG-UNDANGAN KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, ttd.
WIDODO EKATJAHJANA 2016, No.1970 "', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2016 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8620, 'perka-5-2016', 10, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 5 TAHUN 2016 TENTANG TATA NASKAH DINAS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA TATA NASKAH DINAS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Ketatalaksanaan pemerintah merupakan pengaturan tentang cara melaksanakan tugas dan fungsi dalam berbagai bidang kegiatan pemerintahan di lingkungan instansi pemerintah, seperti lembaga tinggi negara, kementerian dan lembaga pemerintah non kementerian serta lembaga pemerintah lainnya di pusat dan daerah.
Mengacu pada Peraturan Menteri Negara Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 80 Tahun 2012 tentang Pedoman Tata Naskah Dinas Instansi Pemerintah, disebutkan bahwa salah satu komponen penting dalam ketatalaksanaan pemerintah adalah administrasi umum. Ruang lingkup administrasi umum meliputi tata naskah dinas, penamaan lembaga, singkatan dan akronim, kearsipan, serta tata ruang perkantoran.
Tata naskah dinas sebagai salah satu unsur administrasi umum meliputi antara lain pengaturan tentang jenis dan format naskah dinas, penyusunan naskah dinas, penggunaan lambang negara, logo dan cap dinas, penggunaan Bahasa Indonesia yang baik dan benar, pengurusan naskah dinas korespodensi, kewenangan, perubahan, pencabutan dan pembatalan produk hukum serta ralat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8620, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 5 TAHUN 2016 TENTANG TATA NASKAH DINAS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA TATA NASKAH DINAS DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. Latar Belakang Ketatalaksanaan pemerintah merupakan pengaturan tentang cara melaksanakan tugas dan fungsi dalam berbagai bidang kegiatan pemerintahan di lingkungan instansi pemerintah, seperti lembaga tinggi negara, kementerian dan lembaga pemerintah non kementerian serta lembaga pemerintah lainnya di pusat dan daerah.
Mengacu pada Peraturan Menteri Negara Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 80 Tahun 2012 tentang Pedoman Tata Naskah Dinas Instansi Pemerintah, disebutkan bahwa salah satu komponen penting dalam ketatalaksanaan pemerintah adalah administrasi umum. Ruang lingkup administrasi umum meliputi tata naskah dinas, penamaan lembaga, singkatan dan akronim, kearsipan, serta tata ruang perkantoran.
Tata naskah dinas sebagai salah satu unsur administrasi umum meliputi antara lain pengaturan tentang jenis dan format naskah dinas, penyusunan naskah dinas, penggunaan lambang negara, logo dan cap dinas, penggunaan Bahasa Indonesia yang baik dan benar, pengurusan naskah dinas korespodensi, kewenangan, perubahan, pencabutan dan pembatalan produk hukum serta ralat.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2016 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8621, 'perka-5-2016', 11, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'Dengan diterbitkannya Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2013 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana maka perlu penyesuaian dalam pembinaan administrasi umum yang disesuaikan dengan perkembangan keadaan, D.
2016, No.1970 ilmu pengetahuan dan teknologi, agar peran dan tugas pokok Badan Nasional Penanggulangan Bencana berjalan dengan lancar.
Maksud dan Tujuan
1. Maksud Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana dimaksudkan sebagai acuan bagi seluruh unit kerja eselon I, Kepala Pusat Data, Informasi dan Humas, Kepala Pusat Pendidikan dan Pelatihan Penanggulangan Bencana dan pejabat di lingkungan Badan Nasional Penanggulangan Bencana.
2. Tujuan Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana bertujuan menciptakan kelancaran komunikasi tulis yang efektif dan efisien dalam penyelenggaraan pemerintahan.
Sasaran Sasaran penetapan Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana adalah:
1. tercapainya kesamaan pengertian dan pemahaman dalam penyelenggaraan tata naskah dinas di lingkungan Badan Nasional Penanggulangan Bencana,
2. terwujudnya keterpaduan penyelenggaraan tata naskah dinas dengan unsur lainnya dalam lingkup administrasi umum,
3. terwujudnya kemudahan dan kelancaran dalam komunikasi tulis,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8621, 'Dengan diterbitkannya Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 10 Tahun 2013 tentang Perubahan atas Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja Badan Nasional Penanggulangan Bencana maka perlu penyesuaian dalam pembinaan administrasi umum yang disesuaikan dengan perkembangan keadaan, D.
2016, No.1970 ilmu pengetahuan dan teknologi, agar peran dan tugas pokok Badan Nasional Penanggulangan Bencana berjalan dengan lancar.
