INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8623, 'perka-5-2016', 13, 'lampiran', 'Lampiran hal. 8', NULL, 8, '1. Ruang lingkup Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana meliputi pengaturan tentang jenis dan format naskah dinas, penyusunan naskah dinas, pengurusan naskah dinas korespondensi, pejabat penanda tangan naskah dinas, penggunaan lambang negara, logo dan cap dinas dalam naskah dinas, perubahan, pencabutan, pembatalan, dan ralat naskah dinas.
2. Tata urut Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana sebagai berikut:
a. Babl Pendahuluan,
b. Babll Jenis dan Format Naskah Dinas,
c. BablIl Penyusunan Naskah Dinas,
d. BabIvVv Pengurusan Naskah Dinas Korespondensi,
e. Bab V Pejabat Penanda Tangan Naskah Dinas,
f. BabVI Penggunaan Lambang Negara, Logo dan Cap Dinas dalam Naskah Dinas:
g. Bab VII Perubahan, Pencabutan, Pembatalan, dan Ralat Naskah Dinas,
h. Bab VIII Penutup.
