INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8626, 'perka-5-2016', 16, 'lampiran', 'Lampiran hal. 11', NULL, 11, '(1) Frase Dengan Rahmat Tuhan Yang Maha Esa diketik seluruhnya dengan huruf kapital yang diletakkan di tengah margin,
(2) Tulisan Kepala Badan Nasional Penanggulangan Bencana yang diketik seluruhnya dengan huruf kapital yang diletakkan di tengah margin dan diakhiri dengan tanda baca koma,
(3) Konsideran diawali dengan kata Menimbang :
(a) konsideran memuat urajan singkat mengenai pokok-pokok pikiran yang menjadi latar belakang dan alasan pembuatan peraturan,
(b) pokok-pokok pikiran pada konsideran memuat unsur filosofis, yuridis, dan sosiologis yang menjadi latar belakang pembuatannya,
(c) jika konsideran memuat lebih dari satu pokok pikiran, tiap-tiap pokok pikiran dirumuskan dalam rangkaian kalimat yang merupakan kesatuan pengertian, dan
(d) tiap-tiap pokok pikiran diawali dengan huruf abjad dan dirumuskan dalam satu kalimat yang diawali dengan kata bahwa dan diakhiri dengan tanda baca titik koma.
4) Dasar hukum diawali dengan kata Mengingat : fa) dasar hukum memuat dasar kewenangan pembuatan peraturan,
(b) peraturan perundang-undangan yang digunakan sebagai dasar hukum hanya peraturan perundang-undangan yang 2016, No.1970 12 tingkatannya sama atau lebih tinggi,
(c) jika jumlah peraturan perundang-undangan yang dijadikan dasar hukum lebih dari satu, urutan pencantuman perlu memperhatikan tata urutan peraturan perundang-undangan dan jika tingkatannya sama disusun secara kronologis berdasarkan saat penetapan atau pengundangan,');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8626, '(1) Frase Dengan Rahmat Tuhan Yang Maha Esa diketik seluruhnya dengan huruf kapital yang diletakkan di tengah margin,
