INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8629, 'perka-5-2016', 19, 'lampiran', 'Lampiran hal. 14', NULL, 14, '4 Jenis Huruf dan Ukuran Kertas Naskah peraturan diketik dengan jenis huruf Bookman Old Style ukuran 12 point (pt) di atas kertas ukuran F4 bebas asam.
