INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8637, 'perka-5-2016', 27, 'lampiran', 'Lampiran hal. 24', NULL, 24, '3) Susunan a) Kepala Bagian kepala surat edaran terdiri dari:
