INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8640, 'perka-5-2016', 30, 'lampiran', 'Lampiran hal. 27', NULL, 27, 'Ditetapkan di pada tanggal Kota sesuai dengan alamat Instansi dan NAMA JABATAN, tanggal Nama jabatan dan nama lengkap yang ditulis huruf kapital Tanda Tangan dan Cap Instansi NAMA LENGKAP 2016, No.1970 .28-
2. Naskah Dinas Penetapan (Keputusan) Jenis naskah dinas penetapan hanya ada satu macam, yaitu keputusan.
a. Pengertian Keputusan adalah naskah dinas yang memuat kebijakan yang bersifat menetapkan, tidak bersifat mengatur, dan merupakan pelaksanaan kegiatan, yang digunakan untuk:
1) menetapkan/mengubah status kepegawaian/personal/ keanggotaan/material/ peristiwa, 2) menetapkan/mengubah/membubarkan suatu kepanitiaan/ tim, dan 3) menetapkan pelimpahan wewenang.
b. Wewenang Penetapan dan Penandatanganan Pejabat yang berwenang menetapkan dan menandatangani keputusan adalah Kepala Badan Nasional Penanggulangan Bencana atau pejabat lain yang berwewenang berdasarkan lingkup tugas, wewenang dan tanggung jawabnya.');
