INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8642, 'perka-5-2016', 32, 'lampiran', 'Lampiran hal. 29', NULL, 29, 'Diktum Bagian diktum keputusan terdiri dari: a) diktum dimulai dengan kata Memutuskan yang ditulis dengan huruf kapital secara simetris dan diikuti kata menetapkan di tepi kiri sejajar dengan kata Mengingat, menggunakan huruf awal kapital, b) substansi kebijakan yang ditetapkan dicantumkan setelah kata menetapkan yang ditulis dengan huruf kapital, dan c) untuk keperluan tertentu, keputusan dapat dilengkapi dengan salinan dan petikan sesuai dengan peraturan perundang-undangan.
Batang Tubuh Sistematika dan cara penulisan bagian batang tubuh keputusan sama dengan ketentuan dalam penyusunan peraturan, tetapi substansi keputusan diuraikan bukan dalam pasal-pasal, melainkan diawali dengan bilangan bertingkat/diktum Kesatu, Kedua, Ketiga, dan seterusnya yang ditulis seluruhnya dengan huruf kapital.
Kaki Bagian kaki keputusan terdiri dari : a) tempat dan tanggal penetapan keputusan, b) jabatan pejabat yang menetapkan, yang ditulis dengan huruf kapital, dan diakhiri dengan tanda baca koma, c) tanda tangan pejabat yang menetapkan keputusan, 2016, No.1970 30 d) nama lengkap pejabat yang menandatangani keputusan, ditulis dengan huruf kapital tanpa mencantumkan gelar, dan ec) cap dinas.
6) Lampiran (jika diperlukan)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8642, 'Diktum Bagian diktum keputusan terdiri dari: a) diktum dimulai dengan kata Memutuskan yang ditulis dengan huruf kapital secara simetris dan diikuti kata menetapkan di tepi kiri sejajar dengan kata Mengingat, menggunakan huruf awal kapital, b) substansi kebijakan yang ditetapkan dicantumkan setelah kata menetapkan yang ditulis dengan huruf kapital, dan c) untuk keperluan tertentu, keputusan dapat dilengkapi dengan salinan dan petikan sesuai dengan peraturan perundang-undangan.
Batang Tubuh Sistematika dan cara penulisan bagian batang tubuh keputusan sama dengan ketentuan dalam penyusunan peraturan, tetapi substansi keputusan diuraikan bukan dalam pasal-pasal, melainkan diawali dengan bilangan bertingkat/diktum Kesatu, Kedua, Ketiga, dan seterusnya yang ditulis seluruhnya dengan huruf kapital.
Kaki Bagian kaki keputusan terdiri dari : a) tempat dan tanggal penetapan keputusan, b) jabatan pejabat yang menetapkan, yang ditulis dengan huruf kapital, dan diakhiri dengan tanda baca koma, c) tanda tangan pejabat yang menetapkan keputusan, 2016, No.1970 30 d) nama lengkap pejabat yang menandatangani keputusan, ditulis dengan huruf kapital tanpa mencantumkan gelar, dan ec) cap dinas.
