INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8643, 'perka-5-2016', 33, 'lampiran', 'Lampiran hal. 30', NULL, 30, 'd. Pengabsahan 1) Pengabsahan merupakan suatu pernyataan bahwa sebelum digandakan dan didistribusikan dengan sah, suatu keputusan telah dicatat dan diteliti sehingga dapat diumumkan oleh pejabat yang bertanggung jawab di bidang hukum atau administrasi umum atau pejabat yang ditunjuk sesuai dengan substansi keputusan.
2) Pengabsahan dicantumkan di bawah ruang tanda tangan sebelah kiri bawah, yang terdiri atas kata salinan sesuai dengan aslinya, nama jabatan, tanda tangan, nama pejabat penanda tangan, ditulis dengan huruf awal kapital dan dibubuhi cap dinas.
3) Pengabsahan sebagaimana tersebut pada angka 2 dibuatkan salinan yang ditandatangani oleh pejabat yang menerima pendelegasian wewenang.
e. Distribusi Keputusan yang telah ditetapkan didistribusikan kepada yang berkepentingan.
f. Hal yang perlu diperhatikan 1) Naskah asli dan salinan yang diparaf harus disimpan sebagai arsip.
2) Pengajuan draf surat keputusan yang ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana atau Sekretaris Utama terlebih dahulu diparaf oleh pemrakarsa, pemeriksa, dan pejabat lain yang terkait menggunakan nota dinas sebagai pengantar.
Format keputusan dapat dilihat pada contoh SA, 5B, 5C, dan 5D.');
