INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8653, 'perka-5-2016', 43, 'lampiran', 'Lampiran hal. 40', NULL, 40, '1) kop naskah dinas, yang berisi lambang negara dan tulisan Kepala Badan Nasional Penanggulangan Bencana atau logo Badan Nasional Penanggulangan Bencana dan tulisan Badan Nasional Penanggulangan Bencana yang ditulis dengan huruf kapital secara simetris, 2) kata surat perintah ditulis dengan huruf kapital secara simetris, dan 3) kata nomor yang berada di bawah tulisan surat perintah, ditulis dengan huruf kapital secara simetris. b) Batang Tubuh Bagian batang tubuh surat perintah terdiri dari hal berikut:
1) konsideran meliputi pertimbangan dan/atau dasar, pertimbangan memuat alasan atau tujuan ditetapkannya surat perintah, sedangkan dasar memuat ketentuan yang dijadikan landasan ditetapkannya surat perintah tersebut, dan 2) diktum dimulai dengan frasa memberi perintah, yang ditulis dengan huruf awal kapital dicantumkan secara simetris, diikuti kata kepada di tepi kiri serta nama dan jabatan pegawai yang mendapat perintah. Di bawah kata kepada ditulis A1. 2016, No.1970 kata untuk disertai perintah-perintah yang harus dilaksanakan. c) Kaki Bagian kaki surat perintah terdiri dari:
1) tempat dan tanggal surat perintah, 2) nama jabatan pejabat yang menandatangani, ditulis dengan huruf awal kapital pada setiap awal unsurnya, dan diakhiri dengan tanda baca koma, 3) tanda tangan pejabat yang memerintahkan, 4) nama lengkap pejabat yang menandatangani surat perintah, ditulis dengan huruf awal kapital pada setiap awal unsurnya, dan 5) cap dinas.');
