INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8666, 'perka-5-2016', 56, 'lampiran', 'Lampiran hal. 58', NULL, 58, 'Memuat materi ..(Alinea Pembuka) La . . yang bersifat mengingatkan suatu — masalah atau AAlinea ISi) ................ooo Laman menyampaikan . arahan, peringatan, saran/pendapat . (Alinea Penutup) kaka kedinasan Nama jabatan Nama Jabatan, dan nama . lengkap ditulis (Tanda Tangan dan Cap Instansi) dengan huruf Nama Lengkap awal kapital, Tembusan:
1 2 3
3. z9. 2016, No.1970 Surat Undangan
a. Pengertian Surat undangan adalah surat dinas yang memuat undangan kepada pejabat/pegawai yang tersebut pada alamat tujuan untuk menghadiri suatu acara kedinasan tertentu, seperti rapat, upacara, dan pertemuan.
b. Kewenangan Surat undangan ditandatangani oleh pejabat sesuai dengan tugas, fungsi, wewenang, dan tanggung jawahnya.
c. Susunan 1) Kepala Bagian kepala surat undangan terdiri dari: a) kop surat undangan, yang berisi lambang negara dan tulisan Kepala Badan Nasional Penanggulangan Bencana atau logo Badan Nasional Penanggulangan Bencana dan tulisan Badan Nasional Penanggulangan Bencana, b) kata nomor, sifat, lampiran, dan hal, diketik di sebelah kiri di bawah kop surat undangan, c) kata tempat dan tanggal pembuatan surat, diketik di sebelah kanan atas sejajar/sebaris dengan nomor, dan d) singkatan Yth, ditulis di bawah hal, diikuti dengan nama jabatan, dan alamat yang dikirimi surat (jika diperlukan).
2) Batang Tubuh Bagian batang tubuh surat undangan terdiri dari: a) alinea pembuka, b) isi undangan yang meliputi hari, tanggal, waktu, tempat, dan acara, dan c) alinea penutup.');
