INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8684, 'perka-5-2016', 74, 'lampiran', 'Lampiran hal. 80', NULL, 80, 'c. Susunan 1) Kepala Bagian kepala pengumuman terdiri dari : a) kop naskah dinas yang memuat logo Badan Nasional Penanggulangan Bencana dan tulisan Badan Nasional Penanggulangan Bencana dengan huruf kapital secara simetris, b) kata pengumuman dicantumkan di bawah logo Badan Nasional Penanggulangan Bencana, yang ditulis dengan huruf kapital secara simetris dan nomor pengumuman dicantumkan di bawahnya, c) kata tentang, dicantumkan di bawah pengumuman ditulis dengan huruf kapital secara simetris, dan d) rumusan judul pengumuman, ditulis dengan huruf kapital secara simetris di bawah kata tentang.
