INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8694, 'perka-5-2016', 84, 'lampiran', 'Lampiran hal. 94', NULL, 94, 'b. kode jabatan penanda tangan,
