INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8701, 'perka-5-2016', 91, 'lampiran', 'Lampiran hal. 101', NULL, 101, 'c. 101 2016, No.1970 Cara Melipat dan Memasukkan Surat ke dalam Sampul Surat dilipat dengan sudut saling bertemu dan lipatannya harus lurus dan tidak kusut. Sebelum surat dinas dilipat, harus dipertimbangkan sampul yang akan digunakan. Surat dinas dilipat dengan cara sepertiga bagian bawah lembaran surat dilipat ke depan dan sepertiga bagian atas dilipat ke belakang.
Selanjutnya surat dimasukan ke dalam sampul dengan bagian kepala surat menghadap ke depan ke arah penerima/pembaca surat.
Cara melipat surat dapat dilihat pada contoh 21A.
