INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8702, 'perka-5-2016', 92, 'lampiran', 'Lampiran hal. 103', NULL, 103, 'a. Kop Surat Nama Jabatan 1 Kop surat nama Jabatan adalah kepala surat yang menunjukkan jabatan Kepala Badan Nasional Penanggulangan Bencana. Kertas dengan Kop Surat Nama Jabatan hanya digunakan untuk surat yang ditandatangani oleh Kepala Badan Nasional Penanggulangan Bencana.
2) Kop Surat Nama Jabatan terdiri atas Lambang Negara di letakkan di tengah bagian atas dan nama jabatan Kepala Badan Nasional Penanggulangan Bencana diletakkan di bawah lambang negara. Perbandingan ukuran Lambang Negara dan huruf yang digunakan hendaknya serasi sesuai dengan ukuran kertas.
Kop surat kepala BNPB dapat dilihat pada contoh 22A
b. Kop Surat Nama Instansi 1 Kop surat nama instansi adalah kepala surat yang menunjukkan nama instansi yaitu Badan Nasional Penanggulangan Bencana dan alamat Badan Nasional Penanggulangan Bencana. Kertas dengan kop surat dimaksud digunakan untuk kemudahan dalam surat menyurat.
2) Kop surat nama instansi menggunakan logo Badan Nasional Penanggulangan Bencana diletakkan di kiri atas, dan tulisan Badan Nasional Penanggulangan Bencana dicetak satu baris, diletakkan disebelah kanan logo dan dibawahnya tertulis alamat Badan Nasional Penanggulangan Bencana, logo Badan Nasional Penanggulangan Bencana dicetak setingkat lebih tinggi di atas tulisan Badan Nasional Penanggulangan Bencana.
2016, No.1970 104 3) Surat jenis nota dinas dan memorandum tidak menggunakan kop surat berlogo BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8702, 'a. Kop Surat Nama Jabatan 1 Kop surat nama Jabatan adalah kepala surat yang menunjukkan jabatan Kepala Badan Nasional Penanggulangan Bencana. Kertas dengan Kop Surat Nama Jabatan hanya digunakan untuk surat yang ditandatangani oleh Kepala Badan Nasional Penanggulangan Bencana.
2) Kop Surat Nama Jabatan terdiri atas Lambang Negara di letakkan di tengah bagian atas dan nama jabatan Kepala Badan Nasional Penanggulangan Bencana diletakkan di bawah lambang negara. Perbandingan ukuran Lambang Negara dan huruf yang digunakan hendaknya serasi sesuai dengan ukuran kertas.
Kop surat kepala BNPB dapat dilihat pada contoh 22A
b. Kop Surat Nama Instansi 1 Kop surat nama instansi adalah kepala surat yang menunjukkan nama instansi yaitu Badan Nasional Penanggulangan Bencana dan alamat Badan Nasional Penanggulangan Bencana. Kertas dengan kop surat dimaksud digunakan untuk kemudahan dalam surat menyurat.
2) Kop surat nama instansi menggunakan logo Badan Nasional Penanggulangan Bencana diletakkan di kiri atas, dan tulisan Badan Nasional Penanggulangan Bencana dicetak satu baris, diletakkan disebelah kanan logo dan dibawahnya tertulis alamat Badan Nasional Penanggulangan Bencana, logo Badan Nasional Penanggulangan Bencana dicetak setingkat lebih tinggi di atas tulisan Badan Nasional Penanggulangan Bencana.
2016, No.1970 104 3) Surat jenis nota dinas dan memorandum tidak menggunakan kop surat berlogo BNPB.', 'Lampiran hal. 103', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2016 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8703, 'perka-5-2016', 93, 'lampiran', 'Lampiran hal. 104', NULL, 104, '4) Pada surat yang berbentuk formulir, kepala surat yang dicetak, diketik, dicap, atau ditulis tangan hanya digunakan pada halaman pertama surat dan mulai pengetikan pada baris kelima dari tepi atas kertas.
5) Surat yang mempunyai Kop Surat Nama Instansi ditandatangani oleh pimpinan Instansi yang bersangkutan atau pejabat lain yang ditunjuk oleh kepala instansi yang bersangkutan.
Jenis Kop Surat Nama Instansi di lingkungan Badan Nasional Penanggulangan Bencana, terdiri dari: a) Kop surat Kepala Badan Nasional Penanggulangan Bencana, dan b) Kop surat Badan Nasional Penanggulangan Bencana, Kop surat Instansi/Unit Kerja dapat dilihat pada contoh 23A. “105 2016, No.1970 CONTOH 22A KOP SURAT KEPALA BNPB KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA Nama Jabatan, (Tanda Tangan dan Cap Jabatan) Nama Lengkap Gedung Graha BNPB Jalan Pramuka Raya KAV. 38, Jakarta Timur 13120 Telepon 021-21281200, Faksimile : 02121281200.
Situs : hip/wwmw.bnpb.go.id 2016, No.1970 106 CONTOH 23A KOP SURAT INSTANSI BADAN NASIONAL PENANGGULANGAN BENCANA BADAN NASIONAL PENANGGULANGAN BENCANA Gedung Graha BNPB Jalan Pramuka Raya KAV. 38, Jakarta Timur 13120 Telepon 021-21281200, Faksinile : 02121281200.
Situs : http/hwww.bnpb.go.id Nama Jabatan (Tanda Tangan dan Cap Instansi ) Nama Lengkap .107- 2016, No.1970
2. Tanggal Surat Tanggal surat ditulis dengan tata urut sebagai berikut:
a. tanggal ditulis dengan angka Arab,
b. bulan ditulis lengkap, dan
c. tahun ditulis lengkap empat digit dengan angka Arab.');
