INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8708, 'perka-5-2016', 98, 'lampiran', 'Lampiran hal. 112', NULL, 112, 'a. Penyelenggaraan urusan kedinasan melalui surat-menyurat dinas harus dilaksanakan secara cermat dan teliti agar tidak menimbulkan salah penafsiran.
b. Urusan kedinasan yang dilakukan dengan menggunakan tata cara dan prosedur surat-menyurat harus menggunakan sarana komunikasi resmi.
c. Jawaban terhadap surat yang masuk 1) Instansi pengirim harus segera mengiformasikan kepada penerima surat atas keterlambatan jawaban dalam suatu proses komunikasi: dan 2) Instansi penerima harus segera memberikan jawaban terhadap konfirmasi yang dilakukan oleh instansi pengirim.
2. Pengurusan Surat Masuk Surat masuk adalah semua surat dinas yang diterima. Untuk memudahkan pengawasan dan pengendalian, penerimaan surat masuk dipusatkan di Bagian Tata Usaha, Biro Umum Sekretariat Utama.
Penanganan surat masuk dilaksanakan melalui tahapan berikut : -a
b. Ba Ken 2016, No.1970 Penerimaan Surat masuk yang diterima dalam sampul tertutup dikelompokkan berdasarkan tingkat keamanan (SR, R, dan B) dan tingkat kecepatan penyampaiannya (kilat, sangat segera, segera, dan biasa). Selanjutnya, surat ditangani sesuai dengan tingkat keamanan dan tingkat kecepatan penyampaiannya.
Pencatatan 1) Surat masuk yang diterima diinput dalam komputer menurut tingkat keamanan.
2) Penginputan surat dinas yang mempunyai tingkat keamanan SR dan R dilakukan oleh pimpinan kesekretariatan atau pejabat tertentu yang mendapatkan kewenangan dari Kepala Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8708, 'a. Penyelenggaraan urusan kedinasan melalui surat-menyurat dinas harus dilaksanakan secara cermat dan teliti agar tidak menimbulkan salah penafsiran.
b. Urusan kedinasan yang dilakukan dengan menggunakan tata cara dan prosedur surat-menyurat harus menggunakan sarana komunikasi resmi.
c. Jawaban terhadap surat yang masuk 1) Instansi pengirim harus segera mengiformasikan kepada penerima surat atas keterlambatan jawaban dalam suatu proses komunikasi: dan 2) Instansi penerima harus segera memberikan jawaban terhadap konfirmasi yang dilakukan oleh instansi pengirim.
2. Pengurusan Surat Masuk Surat masuk adalah semua surat dinas yang diterima. Untuk memudahkan pengawasan dan pengendalian, penerimaan surat masuk dipusatkan di Bagian Tata Usaha, Biro Umum Sekretariat Utama.
Penanganan surat masuk dilaksanakan melalui tahapan berikut : -a
b. Ba Ken 2016, No.1970 Penerimaan Surat masuk yang diterima dalam sampul tertutup dikelompokkan berdasarkan tingkat keamanan (SR, R, dan B) dan tingkat kecepatan penyampaiannya (kilat, sangat segera, segera, dan biasa). Selanjutnya, surat ditangani sesuai dengan tingkat keamanan dan tingkat kecepatan penyampaiannya.
Pencatatan 1) Surat masuk yang diterima diinput dalam komputer menurut tingkat keamanan.
2) Penginputan surat dinas yang mempunyai tingkat keamanan SR dan R dilakukan oleh pimpinan kesekretariatan atau pejabat tertentu yang mendapatkan kewenangan dari Kepala Badan Nasional Penanggulangan Bencana.', 'Lampiran hal. 112', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2016 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8709, 'perka-5-2016', 99, 'lampiran', 'Lampiran hal. 113', NULL, 113, '3) Pencatatan surat dinas yang mempunyai tingkat keamanan B dilakukan oleh Kepala Sub Bagian Persuratan Arsip dan Dokumentasi.
4) Pencatatan surat dilaksanakan dengan prioritas sesuai dengan tingkat kecepatan penyampaian.
5) Pencatatan dilakukan pula pada lembar disposisi dan buku tanda terima mengenai nomor agenda dan tanggal penerimaan.
6) Pencatatan surat masuk dimulai dari nomor 1 pada bulan Januari dan berakhir pada nomor terakhir dalam satu tahun, yaitu nomor terakhir pada tanggal 31 Desember.
7) Pencatatan surat selalu dilakukan pada setiap terjadi pemindahan dan penyimpanan.
Penilaian 1) Kegiatan penilaian surat masuk mulai dilaksanakan pada tahap pencatatan.
2) Pada tahap penilaian, surat dinilai apakah akan disampaikan kepada Sekretaris Utama/Kepala Badan Nasional Penanggulangan Bencana atau dapat disampaikan langsung kepada pejabat yang tertentu.
3) Selain penilaian penyampaian surat, dilakukan pula penilaian penanganan surat, apakah surat masuk itu akan diproses biasa atau melalui proses pemberkasan naskah.
2016, No.1970 ia 4) Surat masuk yang beralamat pribadi (nama orang) dinilai termasuk surat yang harus disampaikan langsung kepada yang bersangkutan dalam keadaan sampul tertutup.
5) Penilaian dilakukan dengan berpedoman kepada tingkat keamanan dan tingkat kecepatan penyampaian surat.
d. Pengolahan 1) Pada tahap pengolahan, pimpinan/pejabat memutuskan tindakan yang akan diambil sehubungan dengan surat masuk tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8709, '3) Pencatatan surat dinas yang mempunyai tingkat keamanan B dilakukan oleh Kepala Sub Bagian Persuratan Arsip dan Dokumentasi.
4) Pencatatan surat dilaksanakan dengan prioritas sesuai dengan tingkat kecepatan penyampaian.
5) Pencatatan dilakukan pula pada lembar disposisi dan buku tanda terima mengenai nomor agenda dan tanggal penerimaan.
6) Pencatatan surat masuk dimulai dari nomor 1 pada bulan Januari dan berakhir pada nomor terakhir dalam satu tahun, yaitu nomor terakhir pada tanggal 31 Desember.
7) Pencatatan surat selalu dilakukan pada setiap terjadi pemindahan dan penyimpanan.
Penilaian 1) Kegiatan penilaian surat masuk mulai dilaksanakan pada tahap pencatatan.
2) Pada tahap penilaian, surat dinilai apakah akan disampaikan kepada Sekretaris Utama/Kepala Badan Nasional Penanggulangan Bencana atau dapat disampaikan langsung kepada pejabat yang tertentu.
3) Selain penilaian penyampaian surat, dilakukan pula penilaian penanganan surat, apakah surat masuk itu akan diproses biasa atau melalui proses pemberkasan naskah.
2016, No.1970 ia 4) Surat masuk yang beralamat pribadi (nama orang) dinilai termasuk surat yang harus disampaikan langsung kepada yang bersangkutan dalam keadaan sampul tertutup.
5) Penilaian dilakukan dengan berpedoman kepada tingkat keamanan dan tingkat kecepatan penyampaian surat.
d. Pengolahan 1) Pada tahap pengolahan, pimpinan/pejabat memutuskan tindakan yang akan diambil sehubungan dengan surat masuk tersebut.', 'Lampiran hal. 113', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 5 Tahun 2016 tentang Tata Naskah Dinas di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8710, 'perka-5-2016', 100, 'lampiran', 'Lampiran hal. 114', NULL, 114, '2) Dari hasil pengolahan dapat diputuskan tindakan lanjutnya, yaitu langsung disimpan atau dibuat naskah dinas baru.
3) Pengolahan surat masuk dapat menggunakan proses pemberkasan naskah atau proses administrasi biasa sesuai dengan kebutuhan.
e. Penyimpanan 1) Surat dinas harus disimpan sedemikian rupa sehingga mudah ditemukan kembali jika diperlukan.
2) Surat masuk yang melalui proses pemberkasan naskah disimpan dalam berkas naskah dinas menurut bidang permasalahan.
3) Surat masuk yang diproses tidak melalui proses pemberkasan, naskah dinas disimpan dalam himpunan sesuai dengan kebutuhan.
Beberapa cara menghimpun surat adalah sebagai berikut: a) Seri adalah himpunan satu jenis surat dinas yang berdasarkan format surat atau jenis naskah dinas, misalnya keputusan, petunjuk pelaksanaan, dan surat edaran, disusun secara kronologis. Himpunan menurut seri selain dibatasi oleh kemampuan map juga dibatasi oleh tahun naskah dinas. b) Rubrik adalah himpunan dari satu macam masalah/hal/pokok persoalan yang disusun secara kronologis, misalnya cuti, kunjungan dinas, kerja lapangan. Himpunan menurut rubrik dibatasi dengan tahun atau dibatasi sampai dengan masalah selesai. f£.
115 2016, No.1970 c) Dosir adalah himpunan satu macam kegiatan atau persoalan yang disusun secara kronologis dari awal sampai akhir. Misalnya, file/berkas pegawai adalah himpunan naskah dinas mulai dari lamaran sampai dengan pemberhentian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8710, '2) Dari hasil pengolahan dapat diputuskan tindakan lanjutnya, yaitu langsung disimpan atau dibuat naskah dinas baru.
3) Pengolahan surat masuk dapat menggunakan proses pemberkasan naskah atau proses administrasi biasa sesuai dengan kebutuhan.
e. Penyimpanan 1) Surat dinas harus disimpan sedemikian rupa sehingga mudah ditemukan kembali jika diperlukan.
