INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8716, 'perka-5-2016', 106, 'lampiran', 'Lampiran hal. 119', NULL, 119, 'b. Untuk Beliau (u.b.) Untuk beliau yang disingkat (u.b.) digunakan jika yang diberikan kuasa memberikan kuasa lagi kepada pejabat satu tingkat dibawahnya, sehingga untuk beliau fu.b.) digunakan setelah atas nama (a.n.). Pelimpahan wewenang ini mengikuti urutan sampai dua tingkat struktural di bawahnya.
