INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8719, 'perka-5-2016', 109, 'lampiran', 'Lampiran hal. 123', NULL, 123, 'Surat keputusan yang ditetapkan oleh pejabat eselon 1 adalah keputusan yang berkaitan dengan kelompok kerja dan tidak menimbulkan anggaran.
2016, No.1970 190- BAB VI PENGGUNAAN LAMBANG NEGARA DAN LOGO DALAM NASKAH DINAS Lambang negara logo dan cap dinas digunakan dalam tata naskah dinas sebagai tanda pengenal atau identifikasi yang bersifat tetap dan resmi. Untuk memperoleh keseragaman dalam penyelenggaraan tata naskah dinas di lingkungan Badan Nasional Penanggulangan Bencana, perlu ditentukan penggunaan lambang negara dan logo pada kertas surat dan sampul.
A. Penggunaan Lambang Negara
1. Ketentuan Penggunaan Lambang Negara Ketentuan penggunaan lambang negara untuk tata naskah dinas adalah sebagai berikut:
a. lambang negara digunakan dalam tata naskah dinas sebagai tanda pengenal atau identifikasi yang bersifat tetap dan resmi, dan
b. Pejabat yang berwenang menggunakan kop naskah dinas jabatan dan cap jabatan dengan lambang negara adalah Kepala Badan Nasional Penanggulangan Bencana (pejabat negara).
2. Kop Naskah Dinas Jabatan dengan Lambang Negara Bentuk dan spesifikasi kop naskah dinas jabatan dengan lambang negara adalah sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8719, 'Surat keputusan yang ditetapkan oleh pejabat eselon 1 adalah keputusan yang berkaitan dengan kelompok kerja dan tidak menimbulkan anggaran.
