INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8734, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai', 'Judul', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8735, 'perka-6-2008', 1, 'menimbang', 'Menimbang', NULL, 1, 'bahwa untuk melaksanakan ketentuan Pasal 17 ayat (3) Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Penanggulangan Bencana perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Penggunaan Dana Siap Pakai;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8735, 'bahwa untuk melaksanakan ketentuan Pasal 17 ayat (3) Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Penanggulangan Bencana perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pedoman Penggunaan Dana Siap Pakai;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8736, 'perka-6-2008', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
3. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
4. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8736, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
2. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
3. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
4. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8737, 'perka-6-2008', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN PENGGUNAAN DANA SIAP PAKAI');
