INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8738, 'perka-6-2008', 4, 'pasal', 'Pasal 1', NULL, 2, 'Pedoman Penggunaan Dana Siap Pakai sebagaimana tersebut dalam Lampiran Peraturan ini merupakan pelaksanaan dari Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana yang tidak terpisahkan dari Peraturan ini.');
