INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8739, 'perka-6-2008', 5, 'pasal', 'Pasal 2', NULL, 2, 'Pedoman Penggunaan Dana Siap Pakai sebagaimana dimaksud dalam Pasal 1, merupakan acuan bagi Pelaksana Dana Siap Pakai.');
