INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8742, 'perka-6-2008', 8, 'lain', 'Penutup', NULL, 2, 'Ditetapkan di Jakarta pada tanggal 17 Desember 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8742, 'Ditetapkan di Jakarta pada tanggal 17 Desember 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8743, 'perka-6-2008', 9, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 6 TAHUN 2008 TANGGAL : 17 DESEMBER 2008 BAB I PENDAHULUAN A. Latar Belakang Bencana baik karena faktor alam, faktor non-alam, maupun faktor manusia (UU Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, Bab 1 Pasal 1), selalu mendatangkan kerugian, penderitaan, dan kesengsaraan bagi umat manusia. Akhir-akhir ini semakin dirasakan meningkatnya intensitas kejadian bencana di Indonesia yang menimbulkan korban jiwa serta kerugian di bidang sarana-prasarana dan ekonomi. Bencana yang umumnya terjadi dalam waktu singkat seringkali menghancurkan hasil pembangunan yang telah dirintis dan diperjuangkan dalam waktu yang lama.
Penanganan bencana, terutama pada tahap tanggap darurat harus serba cepat sehingga selain menuntut pengambilan keputusan yang cepat juga membutuhkan fasilitas pendukung yang memadai, agar dapat mengurangi serta meminimalkan penderitaan korban bencana.
Di pihak lain, pencairan dana penanggulangan bencana konvensional memerlukan jangka waktu tertentu dalam proses pencairan dananya, yang tidak sesuai untuk diterapkan dalam keadaan darurat bencana.
Terkait dengan hal tersebut, komitmen pemerintah dalam Penanggulangan Bencana adalah mengalokasikan dana siap pakai yang dapat digunakan pada tahap tanggap darurat (UU Nomor 24 Tahun 2007 tentang Penanggulangan Bencana Jo Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Penanggulangan Bencana).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8743, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 6 TAHUN 2008 TANGGAL : 17 DESEMBER 2008 BAB I PENDAHULUAN A. Latar Belakang Bencana baik karena faktor alam, faktor non-alam, maupun faktor manusia (UU Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, Bab 1 Pasal 1), selalu mendatangkan kerugian, penderitaan, dan kesengsaraan bagi umat manusia. Akhir-akhir ini semakin dirasakan meningkatnya intensitas kejadian bencana di Indonesia yang menimbulkan korban jiwa serta kerugian di bidang sarana-prasarana dan ekonomi. Bencana yang umumnya terjadi dalam waktu singkat seringkali menghancurkan hasil pembangunan yang telah dirintis dan diperjuangkan dalam waktu yang lama.
Penanganan bencana, terutama pada tahap tanggap darurat harus serba cepat sehingga selain menuntut pengambilan keputusan yang cepat juga membutuhkan fasilitas pendukung yang memadai, agar dapat mengurangi serta meminimalkan penderitaan korban bencana.
Di pihak lain, pencairan dana penanggulangan bencana konvensional memerlukan jangka waktu tertentu dalam proses pencairan dananya, yang tidak sesuai untuk diterapkan dalam keadaan darurat bencana.
Terkait dengan hal tersebut, komitmen pemerintah dalam Penanggulangan Bencana adalah mengalokasikan dana siap pakai yang dapat digunakan pada tahap tanggap darurat (UU Nomor 24 Tahun 2007 tentang Penanggulangan Bencana Jo Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Penanggulangan Bencana).', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8744, 'perka-6-2008', 10, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'Dana Siap Pakai hendaknya digunakan secara efektif dan efisien.
Untuk menghindari kesalahan dan penyimpangan pelaksanaannya, penggunaan Dana Siap Pakai harus dilaporkan dan dipertanggungjawabkan sesuai prinsip akuntabilitas dan transparansi. Sehubungan dengan hal tersebut maka dipandang penting untuk disusun suatu pedoman penggunaan dan pemberian bantuan Dana Siap Pakai yang dikelola Badan Nasional Penanggulangan Bencana.
B. Tujuan Pedoman Penggunaan Dana Siap Pakai disusun sebagai acuan bagi pengelola dan pengguna Dana Siap Pakai pada saat tanggap darurat.
Dengan demikian penanganan terhadap bencana serta korban yang ditimbulkan dapat dilaksanakan dengan cepat dan tepat. Disamping itu pelaporan dan pertanggungjawaban atas penggunaan bantuan Dana Siap Pakai dapat dilaksanakan oleh pemerintah dengan baik, transparan dan memenuhi prinsip akuntabilitas.
C. Ruang Lingkup Pedoman Penggunaan Dana Siap Pakai ini mengatur pengelolaan dan penggunaan Dana Siap Pakai yang bersumber dari APBN yang dialokasikan pada anggaran BNPB (PP Nomor 22 Tahun 2008 Pasal 4 dan Pasal 5 ayat 3).
D. Landasan Hukum
1. Undang-Undang Dasar Republik Indonesia Tahun 1945.
2. Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara.
3. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara.
4. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, pasal 6 huruf f, pasal 62.
5. Peraturan Pemerintah Nomor 24 Tahun 2005 tentang Standar Akuntansi Pemerintahan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8744, 'Dana Siap Pakai hendaknya digunakan secara efektif dan efisien.
Untuk menghindari kesalahan dan penyimpangan pelaksanaannya, penggunaan Dana Siap Pakai harus dilaporkan dan dipertanggungjawabkan sesuai prinsip akuntabilitas dan transparansi. Sehubungan dengan hal tersebut maka dipandang penting untuk disusun suatu pedoman penggunaan dan pemberian bantuan Dana Siap Pakai yang dikelola Badan Nasional Penanggulangan Bencana.
B. Tujuan Pedoman Penggunaan Dana Siap Pakai disusun sebagai acuan bagi pengelola dan pengguna Dana Siap Pakai pada saat tanggap darurat.
Dengan demikian penanganan terhadap bencana serta korban yang ditimbulkan dapat dilaksanakan dengan cepat dan tepat. Disamping itu pelaporan dan pertanggungjawaban atas penggunaan bantuan Dana Siap Pakai dapat dilaksanakan oleh pemerintah dengan baik, transparan dan memenuhi prinsip akuntabilitas.
C. Ruang Lingkup Pedoman Penggunaan Dana Siap Pakai ini mengatur pengelolaan dan penggunaan Dana Siap Pakai yang bersumber dari APBN yang dialokasikan pada anggaran BNPB (PP Nomor 22 Tahun 2008 Pasal 4 dan Pasal 5 ayat 3).
D. Landasan Hukum
1. Undang-Undang Dasar Republik Indonesia Tahun 1945.
2. Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara.
3. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara.
4. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, pasal 6 huruf f, pasal 62.
5. Peraturan Pemerintah Nomor 24 Tahun 2005 tentang Standar Akuntansi Pemerintahan.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8745, 'perka-6-2008', 11, 'lampiran', 'Lampiran hal. 4', NULL, 4, '6. Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Pelaporan Keuangan dan Kinerja Instansi Pemerintah pasal 5, dan penjelasan pasal 24.
7. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana: pasal 21, pasal 23 penjelasan ayat 1, pasal 25, pasal 26, pasal 28, pasal 29, pasal 30, pasal 39 ayat 3, pasal 41, pasal 42, pasal 43, pasal 44, pasal 45.
8. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Penanggulangan Bencana: pasal 1, pasal 4, pasal 5 ayat 3, pasal 6 ayat 2, 3, dan 4, pasal 7, pasal 8, pasal 9, pasal 10, pasal 11, pasal 15 ayat 1 huruf b, pasal 16, pasal 17, pasal 18, pasal 28, pasal 29, pasal 30, pasal 31, pasal 32, pasal 33, pasal 34, pasal 35, serta pasal 36.
9. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana: pasal 2 dan 3.
10. Keputusan Presiden Nomor 42 Tahun 2002 tentang Pedoman Pelaksanaan Anggaran Pendapatan dan Belanja Negara pasal 14 dan pasal 15.
11. Keputusan Presiden Nomor 80 Tahun 2003 tentang Pedoman Pelaksanaan Pengadaan Barang/jasa Pemerintah pasal 6.
12. Peraturan Menteri Dalam Negeri Republik Indonesia Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah.
13. Peraturan Menteri Keuangan Republik Indonesia Nomor 171/PMK.05/2007 tentang Sistem Akuntansi dan Pelaporan Keuangan Pemerintah Pusat.
14. Peraturan Direktur Jenderal Perbendaharaan Nomor PER 24/PB Tahun 2006 tentang Penyusunan Laporan Keuangan Kementerian Negara/Lembaga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8745, '6. Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Pelaporan Keuangan dan Kinerja Instansi Pemerintah pasal 5, dan penjelasan pasal 24.
7. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana: pasal 21, pasal 23 penjelasan ayat 1, pasal 25, pasal 26, pasal 28, pasal 29, pasal 30, pasal 39 ayat 3, pasal 41, pasal 42, pasal 43, pasal 44, pasal 45.
8. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Penanggulangan Bencana: pasal 1, pasal 4, pasal 5 ayat 3, pasal 6 ayat 2, 3, dan 4, pasal 7, pasal 8, pasal 9, pasal 10, pasal 11, pasal 15 ayat 1 huruf b, pasal 16, pasal 17, pasal 18, pasal 28, pasal 29, pasal 30, pasal 31, pasal 32, pasal 33, pasal 34, pasal 35, serta pasal 36.
9. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana: pasal 2 dan 3.
10. Keputusan Presiden Nomor 42 Tahun 2002 tentang Pedoman Pelaksanaan Anggaran Pendapatan dan Belanja Negara pasal 14 dan pasal 15.
11. Keputusan Presiden Nomor 80 Tahun 2003 tentang Pedoman Pelaksanaan Pengadaan Barang/jasa Pemerintah pasal 6.
12. Peraturan Menteri Dalam Negeri Republik Indonesia Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah.
13. Peraturan Menteri Keuangan Republik Indonesia Nomor 171/PMK.05/2007 tentang Sistem Akuntansi dan Pelaporan Keuangan Pemerintah Pusat.
14. Peraturan Direktur Jenderal Perbendaharaan Nomor PER 24/PB Tahun 2006 tentang Penyusunan Laporan Keuangan Kementerian Negara/Lembaga.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8746, 'perka-6-2008', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'E. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
2. Status keadaan darurat bencana adalah suatu keadaan yang ditetapkan oleh Pemerintah untuk jangka waktu tertentu atas dasar rekomendasi Badan yang diberi tugas untuk menanggulangi bencana. Status keadaan darurat dimulai sejak status siaga darurat, tanggap darurat dan transisi dari darurat ke pemulihan.
3. Tanggap Darurat adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, penyelamatan, serta pemulihan prasarana dan sarana.
4. Bantuan darurat bencana adalah upaya memberikan bantuan untuk memenuhi kebutuhan dasar pada saat status keadaan darurat.
5. Dana Siap Pakai adalah dana yang selalu tersedia dan dicadangkan oleh Pemerintah untuk digunakan pada saat tanggap darurat bencana sampai dengan batas waktu tanggap darurat berakhir.
6. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah non departemen sesuai dengan ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8746, 'E. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
2. Status keadaan darurat bencana adalah suatu keadaan yang ditetapkan oleh Pemerintah untuk jangka waktu tertentu atas dasar rekomendasi Badan yang diberi tugas untuk menanggulangi bencana. Status keadaan darurat dimulai sejak status siaga darurat, tanggap darurat dan transisi dari darurat ke pemulihan.
3. Tanggap Darurat adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, penyelamatan, serta pemulihan prasarana dan sarana.
4. Bantuan darurat bencana adalah upaya memberikan bantuan untuk memenuhi kebutuhan dasar pada saat status keadaan darurat.
5. Dana Siap Pakai adalah dana yang selalu tersedia dan dicadangkan oleh Pemerintah untuk digunakan pada saat tanggap darurat bencana sampai dengan batas waktu tanggap darurat berakhir.
6. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB adalah lembaga pemerintah non departemen sesuai dengan ketentuan peraturan perundang-undangan.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8747, 'perka-6-2008', 13, 'lampiran', 'Lampiran hal. 6', NULL, 6, '7. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
8. Pengungsi adalah orang atau kelompok orang yang terpaksa atau dipaksa keluar dari tempat tinggalnya untuk jangka waktu yang belum pasti sebagai akibat dampak buruk bencana.
9. Korban bencana adalah orang atau sekelompok orang yang menderita atau meninggal dunia akibat bencana.
10. Sistem Komando Tanggap Darurat adalah suatu sistem dalam penanganan bencana pada status keadaan darurat, yang dalam sistem tersebut Kepala BNPB/BPBD memiliki kemudahan akses berupa fungsi komando untuk memerintahkan sektor/lembaga dalam satu komando guna pengerahan sumber daya manusia, peralatan, logistik, dan penyelamatan.
11. Tim Reaksi Cepat BNPB/BPBD adalah tim yang ditugaskan oleh Kepala BNPB/BPBD sesuai dengan kewenangannya untuk melakukan kegiatan kaji cepat bencana dan dampak bencana, serta memberikan dukungan pendampingan dalam rangka penanganan darurat bencana.
12. Komandan Tanggap Darurat Bencana adalah seorang pejabat yang ditunjuk oleh Kepala BNPB/BPBD untuk melaksanakan fungsi Komando Tanggap Darurat Bencana.
F. Sistematika Pedoman Penyusunan Pedoman Penggunaan Dana Siap Pakai dilakukan dengan sistematika (outline) sebagai berikut:
I. PENDAHULUAN A. Latar Belakang B. Tujuan C. Ruang Lingkup D. Landasan Hukum E. Pengertian F. Sistematika Pedoman');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8747, '7. Badan Penanggulangan Bencana Daerah yang selanjutnya disingkat BPBD adalah badan pemerintah daerah yang melakukan penyelenggaraan penanggulangan bencana di daerah.
8. Pengungsi adalah orang atau kelompok orang yang terpaksa atau dipaksa keluar dari tempat tinggalnya untuk jangka waktu yang belum pasti sebagai akibat dampak buruk bencana.
9. Korban bencana adalah orang atau sekelompok orang yang menderita atau meninggal dunia akibat bencana.
10. Sistem Komando Tanggap Darurat adalah suatu sistem dalam penanganan bencana pada status keadaan darurat, yang dalam sistem tersebut Kepala BNPB/BPBD memiliki kemudahan akses berupa fungsi komando untuk memerintahkan sektor/lembaga dalam satu komando guna pengerahan sumber daya manusia, peralatan, logistik, dan penyelamatan.
11. Tim Reaksi Cepat BNPB/BPBD adalah tim yang ditugaskan oleh Kepala BNPB/BPBD sesuai dengan kewenangannya untuk melakukan kegiatan kaji cepat bencana dan dampak bencana, serta memberikan dukungan pendampingan dalam rangka penanganan darurat bencana.
12. Komandan Tanggap Darurat Bencana adalah seorang pejabat yang ditunjuk oleh Kepala BNPB/BPBD untuk melaksanakan fungsi Komando Tanggap Darurat Bencana.
F. Sistematika Pedoman Penyusunan Pedoman Penggunaan Dana Siap Pakai dilakukan dengan sistematika (outline) sebagai berikut:
I. PENDAHULUAN A. Latar Belakang B. Tujuan C. Ruang Lingkup D. Landasan Hukum E. Pengertian F. Sistematika Pedoman', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8748, 'perka-6-2008', 14, 'lampiran', 'Lampiran hal. 7', NULL, 7, 'II. DANA SIAP PAKAI A. Penggunaan Dana B. Bentuk Bantuan Dana Siap Pakai C. Pengguna Dana Siap Pakai D. Waktu Penggunaan Dana Siap Pakai
III. PROSEDUR PENYALURAN DAN PENGGUNAAN DANA SIAP PAKAI A. Usulan B. Penetapan C. Penyaluran Bantuan D. Pengelolaan E. Pertanggungjawaban F. Pengembalian Dana Siap Pakai
IV. PEMANTAUAN DAN PELAPORAN A. Pemantauan B. Pelaporan
V. PENGAWASAN, SANKSI, DAN PENGADUAN MASYARAKAT A. Pengawasan B. Sanksi C. Pengaduan Masyarakat
VI. PENUTUP BAB II DANA SIAP PAKAI Dana Siap Pakai adalah dana yang selalu tersedia dan dicadangkan oleh Pemerintah untuk digunakan pada saat tanggap darurat bencana sampai dengan batas waktu tanggap darurat berakhir.
A. Dasar Pemberian Dana Siap Pakai Pemberian Dana Siap Pakai berdasarkan:
1. Penetapan status kedaruratan bencana;
2. Usulan daerah perihal permohonan dukungan bantuan;
3. Laporan Tim Reaksi Cepat BNPB;
4. Hasil Rapat Koordinasi atau;
5. Inisiatif BNPB.
B. Penggunaan Dana Dana Siap Pakai digunakan sesuai kebutuhan tanggap darurat terbatas pada pengadaan barang dan/atau jasa (PP Nomor 22 Tahun 2008 Pasal 17) untuk :
1. Pencarian dan penyelamatan korban bencana Penggunaan Dana Siap Pakai untuk kegiatan pencarian dan penyelamatan korban bencana meliputi :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8748, 'II. DANA SIAP PAKAI A. Penggunaan Dana B. Bentuk Bantuan Dana Siap Pakai C. Pengguna Dana Siap Pakai D. Waktu Penggunaan Dana Siap Pakai
III. PROSEDUR PENYALURAN DAN PENGGUNAAN DANA SIAP PAKAI A. Usulan B. Penetapan C. Penyaluran Bantuan D. Pengelolaan E. Pertanggungjawaban F. Pengembalian Dana Siap Pakai
IV. PEMANTAUAN DAN PELAPORAN A. Pemantauan B. Pelaporan
V. PENGAWASAN, SANKSI, DAN PENGADUAN MASYARAKAT A. Pengawasan B. Sanksi C. Pengaduan Masyarakat
VI. PENUTUP BAB II DANA SIAP PAKAI Dana Siap Pakai adalah dana yang selalu tersedia dan dicadangkan oleh Pemerintah untuk digunakan pada saat tanggap darurat bencana sampai dengan batas waktu tanggap darurat berakhir.
A. Dasar Pemberian Dana Siap Pakai Pemberian Dana Siap Pakai berdasarkan:
1. Penetapan status kedaruratan bencana;
2. Usulan daerah perihal permohonan dukungan bantuan;
3. Laporan Tim Reaksi Cepat BNPB;
4. Hasil Rapat Koordinasi atau;
5. Inisiatif BNPB.
B. Penggunaan Dana Dana Siap Pakai digunakan sesuai kebutuhan tanggap darurat terbatas pada pengadaan barang dan/atau jasa (PP Nomor 22 Tahun 2008 Pasal 17) untuk :
1. Pencarian dan penyelamatan korban bencana Penggunaan Dana Siap Pakai untuk kegiatan pencarian dan penyelamatan korban bencana meliputi :', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8749, 'perka-6-2008', 15, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'a. Transportasi tim pencarian dan pertolongan korban berupa sewa sarana transportasi darat, air, udara dan atau pembelian BBM. ♦ Yang dimaksud dengan transportasi darat antara lain: motor, mobil, truk, bus; ♦ Yang dimaksud dengan transportasi laut/sungai antara lain: perahu, motor boat, kapal; ♦ Yang dimaksud dengan transportasi udara, antara lain: helikopter, pesawat terbang; ♦ Sarana transportasi ini diperlukan oleh tim/regu penolong yang tergabung dalam pencarian dan penyelamatan korban bencana; ♦ Tidak diperkenankan untuk membeli alat transporasi kecuali perahu, gethek, rakit.
b. Peralatan, berupa pembelian dan atau sewa peralatan SAR. ♦ Yang dimaksud dengan peralatan SAR antara lain: sepatu bot, masker, tali temali, lampu senter, genset mobile, kabel, lampu, alat berat, dan peralatan SAR lainnya.
2. Pertolongan darurat Penggunaan Dana Siap Pakai untuk pertolongan darurat meliputi:
a. Pengadaan barang dan jasa/sewa peralatan darurat termasuk alat transportasi darurat darat, laut, dan udara. ♦ Yang dimaksud dengan pertolongan darurat adalah segala upaya yang dilakukan dengan segera untuk mencegah meluasnya dampak bencana.
b. Pengadaan, bahan, dan jasa berupa peralatan dan atau bahan serta jasa yang diperlukan untuk pembersihan puing/longsor, perbaikan tanggul, serta perbaikan/pengadaan rintisan jalan/jembatan/dermaga darurat dan perlatan lainnya.
3. Evakuasi korban bencana Penggunaan Dana Siap Pakai untuk evakuasi korban bencana meliputi :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8749, 'a. Transportasi tim pencarian dan pertolongan korban berupa sewa sarana transportasi darat, air, udara dan atau pembelian BBM. ♦ Yang dimaksud dengan transportasi darat antara lain: motor, mobil, truk, bus; ♦ Yang dimaksud dengan transportasi laut/sungai antara lain: perahu, motor boat, kapal; ♦ Yang dimaksud dengan transportasi udara, antara lain: helikopter, pesawat terbang; ♦ Sarana transportasi ini diperlukan oleh tim/regu penolong yang tergabung dalam pencarian dan penyelamatan korban bencana; ♦ Tidak diperkenankan untuk membeli alat transporasi kecuali perahu, gethek, rakit.
b. Peralatan, berupa pembelian dan atau sewa peralatan SAR. ♦ Yang dimaksud dengan peralatan SAR antara lain: sepatu bot, masker, tali temali, lampu senter, genset mobile, kabel, lampu, alat berat, dan peralatan SAR lainnya.
2. Pertolongan darurat Penggunaan Dana Siap Pakai untuk pertolongan darurat meliputi:
a. Pengadaan barang dan jasa/sewa peralatan darurat termasuk alat transportasi darurat darat, laut, dan udara. ♦ Yang dimaksud dengan pertolongan darurat adalah segala upaya yang dilakukan dengan segera untuk mencegah meluasnya dampak bencana.
b. Pengadaan, bahan, dan jasa berupa peralatan dan atau bahan serta jasa yang diperlukan untuk pembersihan puing/longsor, perbaikan tanggul, serta perbaikan/pengadaan rintisan jalan/jembatan/dermaga darurat dan perlatan lainnya.
3. Evakuasi korban bencana Penggunaan Dana Siap Pakai untuk evakuasi korban bencana meliputi :', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8750, 'perka-6-2008', 16, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'a. Mobilisasi korban, berupa sewa sarana transportasi darat, air, udara, dan atau pembelian BBM. ♦ Sarana transportasi tersebut diperlukan untuk menolong korban yang perlu dipindahkan ke tempat yang lebih aman.
b. Alat dan bahan evakuasi, berupa peralatan dan atau bahan evakuasi. ♦ Yang dimaksud dengan peralatan dan bahan evakuasi antara lain: kantong mayat, tandu, tali temali, sarung tangan, formalin, peralatan dan bahan evakuasi lainnya.
4. Kebutuhan air bersih dan sanitasi Penggunaan Dana Siap Pakai untuk pemenuhan kebutuhan air bersih dan sanitasi meliputi :
a. Pengadaan air bersih, baik pengadaan air bersih di lokasi bencana maupun mendatangkan dari luar. ♦ Yang dimaksud dengan pengadaan air bersih adalah mengambil dan atau membeli air bersih termasuk melakukan proses penyaringan.
b. Pengadaan/perbaikan sanitasi, berupa:
1) Perbaikan/pembuatan saluran air buangan untuk MCK dan drainase lingkungan.
2) Pengadaan MCK darurat.
c. Alat dan bahan pembuatan air bersih, berupa peralatan yang diperlukan dalam penyediaan air bersih dan sanitasi.
d. Transportasi, berupa sewa sarana transportasi darat, air, udara, dan atau pembelian BBM untuk pengiriman air bersih, pengiriman peralatan dan bahan yang diperlukan dalam penyediaan air bersih, dan peralatan sanitasi ke lokasi penampungan.
5. Pangan Penggunaan Dana Siap Pakai untuk pemenuhan kebutuhan pangan meliputi :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8750, 'a. Mobilisasi korban, berupa sewa sarana transportasi darat, air, udara, dan atau pembelian BBM. ♦ Sarana transportasi tersebut diperlukan untuk menolong korban yang perlu dipindahkan ke tempat yang lebih aman.
b. Alat dan bahan evakuasi, berupa peralatan dan atau bahan evakuasi. ♦ Yang dimaksud dengan peralatan dan bahan evakuasi antara lain: kantong mayat, tandu, tali temali, sarung tangan, formalin, peralatan dan bahan evakuasi lainnya.
4. Kebutuhan air bersih dan sanitasi Penggunaan Dana Siap Pakai untuk pemenuhan kebutuhan air bersih dan sanitasi meliputi :
a. Pengadaan air bersih, baik pengadaan air bersih di lokasi bencana maupun mendatangkan dari luar. ♦ Yang dimaksud dengan pengadaan air bersih adalah mengambil dan atau membeli air bersih termasuk melakukan proses penyaringan.
b. Pengadaan/perbaikan sanitasi, berupa:
1) Perbaikan/pembuatan saluran air buangan untuk MCK dan drainase lingkungan.
2) Pengadaan MCK darurat.
c. Alat dan bahan pembuatan air bersih, berupa peralatan yang diperlukan dalam penyediaan air bersih dan sanitasi.
d. Transportasi, berupa sewa sarana transportasi darat, air, udara, dan atau pembelian BBM untuk pengiriman air bersih, pengiriman peralatan dan bahan yang diperlukan dalam penyediaan air bersih, dan peralatan sanitasi ke lokasi penampungan.
5. Pangan Penggunaan Dana Siap Pakai untuk pemenuhan kebutuhan pangan meliputi :', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8751, 'perka-6-2008', 17, 'lampiran', 'Lampiran hal. 10', NULL, 10, 'a. Pengadaan pangan, berupa makanan siap saji dan penyediaan bahan makanan. ♦ Yang dimaksud dengan makanan siap saji seperti nasi bungkus, roti dan sejenisnya. ♦ Dalam penyediaan pangan perlu diperhatikan keperluan pangan khusus untuk bayi, ibu hamil, ibu menyusui, dan lansia. ♦ Yang dimaksud dengan pangan adalah makanan dan bahan pangan untuk korban bencana dan tim penolong.
b. Pengadaan dapur umum, berupa dapur lapangan siap pakai, alat dan bahan pembuatan dapur umum seperti batu bata, semen, tenda, dan perlengkapan dapur umum lainnya, termasuk didalamnya adalah pengadaan perlengkapan makan darurat.
c. Transportasi untuk distribusi bantuan pangan, berupa sewa sarana transportasi darat, air, udara, dan atau pembelian BBM. ♦ Sarana transportasi tersebut diperlukan untuk pengiriman pangan dari tempat lain ke lokasi kejadian, maupun dari dapur umum ke tempat pengungsian dan atau tempat terisolir, termasuk pengiriman alat dan bahan pengadan dapur umum.
6. Sandang Penggunaan Dana Siap Pakai untuk pemenuhan kebutuhan sandang meliputi:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8751, 'a. Pengadaan pangan, berupa makanan siap saji dan penyediaan bahan makanan. ♦ Yang dimaksud dengan makanan siap saji seperti nasi bungkus, roti dan sejenisnya. ♦ Dalam penyediaan pangan perlu diperhatikan keperluan pangan khusus untuk bayi, ibu hamil, ibu menyusui, dan lansia. ♦ Yang dimaksud dengan pangan adalah makanan dan bahan pangan untuk korban bencana dan tim penolong.
b. Pengadaan dapur umum, berupa dapur lapangan siap pakai, alat dan bahan pembuatan dapur umum seperti batu bata, semen, tenda, dan perlengkapan dapur umum lainnya, termasuk didalamnya adalah pengadaan perlengkapan makan darurat.
c. Transportasi untuk distribusi bantuan pangan, berupa sewa sarana transportasi darat, air, udara, dan atau pembelian BBM. ♦ Sarana transportasi tersebut diperlukan untuk pengiriman pangan dari tempat lain ke lokasi kejadian, maupun dari dapur umum ke tempat pengungsian dan atau tempat terisolir, termasuk pengiriman alat dan bahan pengadan dapur umum.
6. Sandang Penggunaan Dana Siap Pakai untuk pemenuhan kebutuhan sandang meliputi:', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8752, 'perka-6-2008', 18, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'a. Pengadaan sandang, berupa pakaian umum dewasa dan anak, perlengkapan sandang bayi, keperluan tidur, dan perlengkapan khusus wanita dewasa. ♦ Yang dimaksud dengan pakaian umum dewasa dan anak antara lain celana, daster, kaos, seragam dan sepatu anak sekolah, dan sejenisnya. ♦ Yang dimaksud dengan sandang bayi antara lain popok, bedongan, selendang, selimut bayi, kelambu untuk bayi dan sejenisnya. ♦ Yang dimaksud dengan keperluan tidur antara lain kain sarung, kain, selimut, piyama, dan sejenisnya. ♦ Yang dimaksud dengan perkengkapan khusus wanita dewasa adalah pembalut wanita dan sejenisnya.
b. Transportasi untuk distribusi bantuan sandang, berupa sewa sarana transportasi darat, air, udara, dan atau pembelian BBM. ♦ Sarana transportasi tersebut diperlukan untuk pengiriman bantuan sandang dari tempat lain ke lokasi kejadian.
7. Pelayanan kesehatan Penggunaan Dana Siap Pakai untuk pelayanan kesehatan meliputi:
a. Pengadaan obat-obatan, termasuk didalamnya perlengkapan untuk fogging.
b. Pengadaan peralatan hygiene seperti sabun, shampo, sikat gigi, pasta gigi dan sejenisnya.
c. Transportasi untuk distribusi bantuan obat-obatan, berupa sewa sarana transportasi darat, air, udara, dan atau pembelian BBM. ♦ Sarana transportasi tersebut diperlukan untuk pengiriman bantuan obat-obatan dari tempat lain ke lokasi kejadian.
8. Penampungan serta tempat hunian sementara Penggunaan Dana Siap Pakai untuk penampungan serta tempat hunian sementara meliputi :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8752, 'a. Pengadaan sandang, berupa pakaian umum dewasa dan anak, perlengkapan sandang bayi, keperluan tidur, dan perlengkapan khusus wanita dewasa. ♦ Yang dimaksud dengan pakaian umum dewasa dan anak antara lain celana, daster, kaos, seragam dan sepatu anak sekolah, dan sejenisnya. ♦ Yang dimaksud dengan sandang bayi antara lain popok, bedongan, selendang, selimut bayi, kelambu untuk bayi dan sejenisnya. ♦ Yang dimaksud dengan keperluan tidur antara lain kain sarung, kain, selimut, piyama, dan sejenisnya. ♦ Yang dimaksud dengan perkengkapan khusus wanita dewasa adalah pembalut wanita dan sejenisnya.
b. Transportasi untuk distribusi bantuan sandang, berupa sewa sarana transportasi darat, air, udara, dan atau pembelian BBM. ♦ Sarana transportasi tersebut diperlukan untuk pengiriman bantuan sandang dari tempat lain ke lokasi kejadian.
7. Pelayanan kesehatan Penggunaan Dana Siap Pakai untuk pelayanan kesehatan meliputi:
a. Pengadaan obat-obatan, termasuk didalamnya perlengkapan untuk fogging.
b. Pengadaan peralatan hygiene seperti sabun, shampo, sikat gigi, pasta gigi dan sejenisnya.
c. Transportasi untuk distribusi bantuan obat-obatan, berupa sewa sarana transportasi darat, air, udara, dan atau pembelian BBM. ♦ Sarana transportasi tersebut diperlukan untuk pengiriman bantuan obat-obatan dari tempat lain ke lokasi kejadian.
8. Penampungan serta tempat hunian sementara Penggunaan Dana Siap Pakai untuk penampungan serta tempat hunian sementara meliputi :', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8753, 'perka-6-2008', 19, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'a. Pengadaan tenda, perlengkapan tidur, dan sarana penerangan lapangan. ♦ Dalam pengadaan tenda perlu memperhatikan tenda khusus untuk kelompok rentan (wanita, balita, lansia, penyandang cacat). ♦ Perlangkapan tidur adalah bantal, guling, alas tidur (matras/velbed/tikar), selimut, dan sejenisnya. ♦ Sarana penerangan antara lain genset, kabel, lampu, dan sejenisnya.
b. Alat dan bahan, berupa peralatan dan bahan yang diperlukan untuk pembuatan tempat penampungan dan tempat hunian sementara, seperti alat pertukangan sederhana.
c. Transportasi dalam rangka distribusi peralatan untuk pengadaan penampungan serta tempat hunian sementara, berupa sewa sarana transportasi darat, air, udara, dan atau pembelian BBM. ♦ Sarana transportasi tersebut diperlukan untuk pengiriman bantuan peralatan dan bahan pengadaan penampungan dan tempat hunian sementara dari tempat lain ke lokasi kejadian.
9. Lain-lain Penggunaan Dana Siap Pakai untuk penanganan darurat lainnya termasuk bantuan kemanusiaan diluar butir 1 s/d 8 dimungkinkan sesuai dengan arahan/kebijakan pimpinan.
Catatan:
1) Dana Siap Pakai dapat digunakan untuk pembayaran uang lelah semua kegiatan yang memerlukan tenaga yang telah direkrut dalam Sistem Komando Tanggap Darurat.
2) BNPB/BPBD pada saat tanggap darurat dapat melaksanakan pengadaan barang dan/atau jasa sesuai kebutuhan kondisi dan karakteristik wilayah bencana yang dilaksanakan oleh Pejabat sesuai kewenangannya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8753, 'a. Pengadaan tenda, perlengkapan tidur, dan sarana penerangan lapangan. ♦ Dalam pengadaan tenda perlu memperhatikan tenda khusus untuk kelompok rentan (wanita, balita, lansia, penyandang cacat). ♦ Perlangkapan tidur adalah bantal, guling, alas tidur (matras/velbed/tikar), selimut, dan sejenisnya. ♦ Sarana penerangan antara lain genset, kabel, lampu, dan sejenisnya.
b. Alat dan bahan, berupa peralatan dan bahan yang diperlukan untuk pembuatan tempat penampungan dan tempat hunian sementara, seperti alat pertukangan sederhana.
c. Transportasi dalam rangka distribusi peralatan untuk pengadaan penampungan serta tempat hunian sementara, berupa sewa sarana transportasi darat, air, udara, dan atau pembelian BBM. ♦ Sarana transportasi tersebut diperlukan untuk pengiriman bantuan peralatan dan bahan pengadaan penampungan dan tempat hunian sementara dari tempat lain ke lokasi kejadian.
9. Lain-lain Penggunaan Dana Siap Pakai untuk penanganan darurat lainnya termasuk bantuan kemanusiaan diluar butir 1 s/d 8 dimungkinkan sesuai dengan arahan/kebijakan pimpinan.
Catatan:
1) Dana Siap Pakai dapat digunakan untuk pembayaran uang lelah semua kegiatan yang memerlukan tenaga yang telah direkrut dalam Sistem Komando Tanggap Darurat.
2) BNPB/BPBD pada saat tanggap darurat dapat melaksanakan pengadaan barang dan/atau jasa sesuai kebutuhan kondisi dan karakteristik wilayah bencana yang dilaksanakan oleh Pejabat sesuai kewenangannya.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8754, 'perka-6-2008', 20, 'lampiran', 'Lampiran hal. 13', NULL, 13, '3) Pengadaan barang/jasa pada saat tanggap darurat dilakukan secara khusus melalui pembelian/pengadaan langsung yang efektif dan efisien sesuai dengan kondisi pada saat keadaan tanggap darurat.
4) Barang yang pengadaannya melalui pembelian dari Dana Siap Pakai sesuai dengan jenis dan dapat ditetapkan sebagai: a) Barang inventaris yang dikelola sesuai peraturan yang berlaku. Barang tersebut diinventarisir dan diserahkan pengelolaannya kepada Deputi yang mengurus logistik. b) Barang hibah yang pengelolaannya diserahkan kepada Pemerintah Daerah Provinsi/Kabupaten/Kota dan atau BPBD Provinsi/Kabupaten/Kota.
C. Bentuk Bantuan Dana Siap Pakai Pengadaan barang dan atau jasa sebagaimana diuraikan pada bagian 2.1 yang bersumber dari Dana Siap Pakai dapat diberikan kepada daerah yang terkena bencana dalam bentuk :
1. Dana (uang tunai/giro).
2. Peralatan dan logistik.
3. Bantuan Transportasi (darat, air, udara).
4. Bantuan sumberdaya manusia (jasa).
D. Pengguna Dana Siap Pakai Pengguna Dana Siap Pakai adalah lembaga yang mempunyai tugas pokok dan fungsi penanggulangan bencana sebagai berikut:
1. Badan Nasional Penanggulangan Bencana (BNPB) dan instansi/lembaga terkait penanggulangan bencana ditingkat pusat.
2. Badan Penanggulangan Bencana Daerah (BPBD) tingkat Provinsi.
3. Badan Penanggulangan Bencana Daerah (BPBD) tingkat Kabupaten/Kota.
4. Perangkat daerah yang memiliki tugas dan fungsi penanggulangan bencana (khusus bagi daerah yang belum memiliki BPBD).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8754, '3) Pengadaan barang/jasa pada saat tanggap darurat dilakukan secara khusus melalui pembelian/pengadaan langsung yang efektif dan efisien sesuai dengan kondisi pada saat keadaan tanggap darurat.
4) Barang yang pengadaannya melalui pembelian dari Dana Siap Pakai sesuai dengan jenis dan dapat ditetapkan sebagai: a) Barang inventaris yang dikelola sesuai peraturan yang berlaku. Barang tersebut diinventarisir dan diserahkan pengelolaannya kepada Deputi yang mengurus logistik. b) Barang hibah yang pengelolaannya diserahkan kepada Pemerintah Daerah Provinsi/Kabupaten/Kota dan atau BPBD Provinsi/Kabupaten/Kota.
C. Bentuk Bantuan Dana Siap Pakai Pengadaan barang dan atau jasa sebagaimana diuraikan pada bagian 2.1 yang bersumber dari Dana Siap Pakai dapat diberikan kepada daerah yang terkena bencana dalam bentuk :
1. Dana (uang tunai/giro).
2. Peralatan dan logistik.
3. Bantuan Transportasi (darat, air, udara).
4. Bantuan sumberdaya manusia (jasa).
D. Pengguna Dana Siap Pakai Pengguna Dana Siap Pakai adalah lembaga yang mempunyai tugas pokok dan fungsi penanggulangan bencana sebagai berikut:
1. Badan Nasional Penanggulangan Bencana (BNPB) dan instansi/lembaga terkait penanggulangan bencana ditingkat pusat.
2. Badan Penanggulangan Bencana Daerah (BPBD) tingkat Provinsi.
3. Badan Penanggulangan Bencana Daerah (BPBD) tingkat Kabupaten/Kota.
4. Perangkat daerah yang memiliki tugas dan fungsi penanggulangan bencana (khusus bagi daerah yang belum memiliki BPBD).', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8755, 'perka-6-2008', 21, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'E. Waktu Penggunaan Dana Siap Pakai Batas waktu penggunaan Dana Siap Pakai adalah pada waktu status keadaan darurat, yaitu dimulai saat tanggap darurat ditetapkan sampai ketetapan tahap tanggap darurat selesai.
Jangka waktu tanggap darurat beragam sesuai dengan besar kecilnya skala bencana yaitu 2 (dua) minggu sampai dengan 1 (satu) bulan setelah kejadian bencana dan dapat diperpanjang berdasarkan keputusan dari Presiden/Kepala Daerah.
BAB III PROSEDUR PENYALURAN DAN PENGGUNAAN DANA SIAP PAKAI A. Usulan Pemerintah/Pemerintah Provinsi/Kabupaten/Kota yang terkena bencana dapat mengusulkan bantuan Dana Siap Pakai kepada Kepala BNPB dengan menyampaikan laporan kejadian, jumlah korban, kerusakan, kerugian dan bantuan yang diperlukan.
B. Penetapan
1. Penetapan besar bantuan (uang tunai, barang dan jasa) dapat dilakukan berdasarkan usulan dari daerah/instansi/lembaga terkait, laporan Tim Reaksi Cepat (TRC), hasil rapat koordinasi atau inisiatif dari BNPB.
2. Pejabat yang berwenang mengeluarkan Dana Siap Pakai adalah Kuasa Pengguna Anggaran/Barang BNPB setelah mendapat penetapan dan persetujuan Kepala BNPB selaku Pengguna Anggaran/Barang.
3. Kepala BNPB dalam melaksanakan fungsinya dapat mendelegasikan kewenangannya kepada pejabat yang ditunjuk.
C. Penyaluran Bantuan');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8755, 'E. Waktu Penggunaan Dana Siap Pakai Batas waktu penggunaan Dana Siap Pakai adalah pada waktu status keadaan darurat, yaitu dimulai saat tanggap darurat ditetapkan sampai ketetapan tahap tanggap darurat selesai.
Jangka waktu tanggap darurat beragam sesuai dengan besar kecilnya skala bencana yaitu 2 (dua) minggu sampai dengan 1 (satu) bulan setelah kejadian bencana dan dapat diperpanjang berdasarkan keputusan dari Presiden/Kepala Daerah.
BAB III PROSEDUR PENYALURAN DAN PENGGUNAAN DANA SIAP PAKAI A. Usulan Pemerintah/Pemerintah Provinsi/Kabupaten/Kota yang terkena bencana dapat mengusulkan bantuan Dana Siap Pakai kepada Kepala BNPB dengan menyampaikan laporan kejadian, jumlah korban, kerusakan, kerugian dan bantuan yang diperlukan.
B. Penetapan
1. Penetapan besar bantuan (uang tunai, barang dan jasa) dapat dilakukan berdasarkan usulan dari daerah/instansi/lembaga terkait, laporan Tim Reaksi Cepat (TRC), hasil rapat koordinasi atau inisiatif dari BNPB.
2. Pejabat yang berwenang mengeluarkan Dana Siap Pakai adalah Kuasa Pengguna Anggaran/Barang BNPB setelah mendapat penetapan dan persetujuan Kepala BNPB selaku Pengguna Anggaran/Barang.
3. Kepala BNPB dalam melaksanakan fungsinya dapat mendelegasikan kewenangannya kepada pejabat yang ditunjuk.
C. Penyaluran Bantuan', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8756, 'perka-6-2008', 22, 'lampiran', 'Lampiran hal. 15', NULL, 15, '1. Penyaluran bantuan Dana Siap Pakai dari BNPB dapat diserahkan secara langsung kepada provinsi/kabupaten/kota yang terkena bencana. Penyaluran bantuan Dana Siap Pakai dilengkapi dengan bukti penerimaan berupa kwitansi (lampiran 1), dan berita acara penyerahan bantuan uang (lampiran 2).
2. Penyaluran bantuan Dana Siap Pakai kepada instansi/lembaga pemerintah terkait dilengkapi kwitansi, Berita Acara Serah Terima serta Nota Kesepahaman.
3. Penyaluran bantuan Dana Siap Pakai dapat diberikan dalam bentuk uang, barang dan jasa dengan mempertimbangkan beberapa hal, antara lain aspek kemudahan, ketersediaan dan kelancaran distribusi. Setiap penyaluran harus dilakukan pencatatan. Penyerahan bantuan dalam bentuk peralatan dan logistik dibuat berita acara tersendiri (lampiran 3).
4. Penyaluran bantuan kepada penerima dalam bentuk uang seperti uang lauk pauk (ULP) dan lain-lain dicatat sesuai format penyaluran (lampiran 4).
5. Penyaluran bantuan kepada penerima dalam bentuk barang seperti pakaian, tikar, masker dan lain-lain, dicatat dan dilampiri kwitansi belanja barang sebagai tanda bukti transaksi dan dicatat dalam rekapitulasi belanja barang (lampiran 5) serta diadministrasikan sesuai dengan format lampiran 6 dan lampiran 8. Pengadaan barang tersebut dapat dilakukan setelah mendapat persetujuan Kepala BNPB. Persetujuan Kepala BNPB dapat diberikan secara lisan diikuti dengan persetujuan secara tertulis maksimal 3 x 24 jam.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8756, '1. Penyaluran bantuan Dana Siap Pakai dari BNPB dapat diserahkan secara langsung kepada provinsi/kabupaten/kota yang terkena bencana. Penyaluran bantuan Dana Siap Pakai dilengkapi dengan bukti penerimaan berupa kwitansi (lampiran 1), dan berita acara penyerahan bantuan uang (lampiran 2).
2. Penyaluran bantuan Dana Siap Pakai kepada instansi/lembaga pemerintah terkait dilengkapi kwitansi, Berita Acara Serah Terima serta Nota Kesepahaman.
3. Penyaluran bantuan Dana Siap Pakai dapat diberikan dalam bentuk uang, barang dan jasa dengan mempertimbangkan beberapa hal, antara lain aspek kemudahan, ketersediaan dan kelancaran distribusi. Setiap penyaluran harus dilakukan pencatatan. Penyerahan bantuan dalam bentuk peralatan dan logistik dibuat berita acara tersendiri (lampiran 3).
4. Penyaluran bantuan kepada penerima dalam bentuk uang seperti uang lauk pauk (ULP) dan lain-lain dicatat sesuai format penyaluran (lampiran 4).
5. Penyaluran bantuan kepada penerima dalam bentuk barang seperti pakaian, tikar, masker dan lain-lain, dicatat dan dilampiri kwitansi belanja barang sebagai tanda bukti transaksi dan dicatat dalam rekapitulasi belanja barang (lampiran 5) serta diadministrasikan sesuai dengan format lampiran 6 dan lampiran 8. Pengadaan barang tersebut dapat dilakukan setelah mendapat persetujuan Kepala BNPB. Persetujuan Kepala BNPB dapat diberikan secara lisan diikuti dengan persetujuan secara tertulis maksimal 3 x 24 jam.', 'Lampiran hal. 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8757, 'perka-6-2008', 23, 'lampiran', 'Lampiran hal. 16', NULL, 16, '6. Penyaluran bantuan dalam bentuk jasa seperti jasa evakuasi dan, penyelamatan bagi relawan, distribusi bantuan bagi petugas dan lain-lain diadministrasikan sesuai format lampiran 7, lampiran 8, dan lampiran 9. Pengadaan jasa tersebut dapat dilakukan setelah mendapat persetujuan Kepala BNPB. Persetujuan Kepala BNPB dapat diberikan secara lisan diikuti dengan persetujuan secara tertulis maksimal 3 x 24 jam.
7. Seluruh bantuan Dana Siap Pakai yang telah disalurkan direkapitulasi dan diadministrasikan sesuai format lampiran 10.
D. Pengelola
1. Pejabat yang berwenang mengelola bantuan Dana Siap Pakai di daerah adalah Kepala BPBD tingkat Provinsi dan atau Kepala BPBD tingkat Kabupaten/Kota. Jika di daerah tersebut belum terbentuk BPBD, pengelolaannya langsung berada di bawah wewenang Gubernur/Bupati/Walikota.
2. Instansi/lembaga pemerintah terkait dalam mengelola bantuan Dana Siap Pakai dapat melimpahkan kewenangannya kepada pejabat yang ditunjuk.
E. Pertanggungjawaban
1. Penerima bantuan Dana Siap Pakai harus memberikan laporan pertanggungjawaban sesuai ketentuan yang berlaku.
2. Pertanggungjawaban penggunaan Dana Siap Pakai diberikan perlakuan khusus, yaitu pengadaan barang/jasa untuk penyelenggaraan tanggap darurat bencana dilakukan secara khusus melalui pembelian/pengadaan langsung yang efektif dan efisien sesuai dengan kondisi pada saat keadaan tanggap darurat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8757, '6. Penyaluran bantuan dalam bentuk jasa seperti jasa evakuasi dan, penyelamatan bagi relawan, distribusi bantuan bagi petugas dan lain-lain diadministrasikan sesuai format lampiran 7, lampiran 8, dan lampiran 9. Pengadaan jasa tersebut dapat dilakukan setelah mendapat persetujuan Kepala BNPB. Persetujuan Kepala BNPB dapat diberikan secara lisan diikuti dengan persetujuan secara tertulis maksimal 3 x 24 jam.
7. Seluruh bantuan Dana Siap Pakai yang telah disalurkan direkapitulasi dan diadministrasikan sesuai format lampiran 10.
D. Pengelola
1. Pejabat yang berwenang mengelola bantuan Dana Siap Pakai di daerah adalah Kepala BPBD tingkat Provinsi dan atau Kepala BPBD tingkat Kabupaten/Kota. Jika di daerah tersebut belum terbentuk BPBD, pengelolaannya langsung berada di bawah wewenang Gubernur/Bupati/Walikota.
2. Instansi/lembaga pemerintah terkait dalam mengelola bantuan Dana Siap Pakai dapat melimpahkan kewenangannya kepada pejabat yang ditunjuk.
E. Pertanggungjawaban
1. Penerima bantuan Dana Siap Pakai harus memberikan laporan pertanggungjawaban sesuai ketentuan yang berlaku.
2. Pertanggungjawaban penggunaan Dana Siap Pakai diberikan perlakuan khusus, yaitu pengadaan barang/jasa untuk penyelenggaraan tanggap darurat bencana dilakukan secara khusus melalui pembelian/pengadaan langsung yang efektif dan efisien sesuai dengan kondisi pada saat keadaan tanggap darurat.', 'Lampiran hal. 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8758, 'perka-6-2008', 24, 'lampiran', 'Lampiran hal. 17', NULL, 17, '3. Yang dimaksud dengan perlakuan secara khusus adalah meskipun bukti pertanggungjawaban tidak sesuai dengan ketentuan yang berlaku namun bukti pertanggungjawaban tersebut diperlakukan sebagai dokumen pertanggungjawaban keuangan yang sah.
4. Pertanggungjawaban baik keuangan maupun kinerja dilaporkan paling lambat 3 (tiga) bulan setelah bantuan diterima, dilengkapi dan dilampiri bukti-bukti pengeluaran antara lain : ♦ Kwitansi dan Berita Acara Penyerahan bantuan. ♦ Rekapitulasi SPJ. ♦ Bukti Penyaluran Bantuan yang diketahui oleh pejabat setempat. ♦ Bukti transaksi pengadaan peralatan dan logistik. ♦ Bukti sewa kendaraan untuk pengiriman bantuan termasuk personil. ♦ Bukti pengepakan dan pengiriman bantuan sampai ke lokasi bencana. ♦ Surat Keputusan penunjukkan dan lain-lain. ♦ Kontrak/Surat Perintah Kerja (SPK) dalam hal pengadaan jasa. ♦ Bukti-bukti lainnya yang sah.
F. Pengembalian Dana Siap Pakai Sisa Dana Siap Pakai disetorkan ke Kas Negara dimana bukti setoran disampaikan kepada BNPB.
Penyetoran Dana Siap Pakai pakai dilakukan bersamaan dengan masa pertanggungjawaban Dana Siap Pakai yaitu paling lambat tiga bulan setelah masa tanggap darurat selesai.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8758, '3. Yang dimaksud dengan perlakuan secara khusus adalah meskipun bukti pertanggungjawaban tidak sesuai dengan ketentuan yang berlaku namun bukti pertanggungjawaban tersebut diperlakukan sebagai dokumen pertanggungjawaban keuangan yang sah.
4. Pertanggungjawaban baik keuangan maupun kinerja dilaporkan paling lambat 3 (tiga) bulan setelah bantuan diterima, dilengkapi dan dilampiri bukti-bukti pengeluaran antara lain : ♦ Kwitansi dan Berita Acara Penyerahan bantuan. ♦ Rekapitulasi SPJ. ♦ Bukti Penyaluran Bantuan yang diketahui oleh pejabat setempat. ♦ Bukti transaksi pengadaan peralatan dan logistik. ♦ Bukti sewa kendaraan untuk pengiriman bantuan termasuk personil. ♦ Bukti pengepakan dan pengiriman bantuan sampai ke lokasi bencana. ♦ Surat Keputusan penunjukkan dan lain-lain. ♦ Kontrak/Surat Perintah Kerja (SPK) dalam hal pengadaan jasa. ♦ Bukti-bukti lainnya yang sah.
F. Pengembalian Dana Siap Pakai Sisa Dana Siap Pakai disetorkan ke Kas Negara dimana bukti setoran disampaikan kepada BNPB.
Penyetoran Dana Siap Pakai pakai dilakukan bersamaan dengan masa pertanggungjawaban Dana Siap Pakai yaitu paling lambat tiga bulan setelah masa tanggap darurat selesai.', 'Lampiran hal. 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8759, 'perka-6-2008', 25, 'lampiran', 'Lampiran hal. 18', NULL, 18, 'BAB IV PEMANTAUAN DAN PELAPORAN Agar pengelolaan dana berjalan lancar dan transparan maka perlu dilakukan pemantauan dan pelaporan yang dilakukan secara efektif dan terpadu. Pemantauan dan pelaporan dilakukan BNPB dan BPBD serta instansi terkait. Setelah kegiatan selesai, yaitu setelah selesainya masa tanggap darurat, pengelola bantuan Dana Siap Pakai harus melaporkan semua kegiatan dan laporan pertanggungjawaban keuangan kepada Kepala BNPB.
A. Pemantauan
1. BNPB bersama dengan instansi/lembaga terkait secara selektif memantau pelaksanaan penggunaan Dana Siap Pakai mulai dari proses pelaksanaan administrasi sampai dengan fisik kegiatan.
2. Pemantauan terhadap penggunaan Dana Siap Pakai di daerah dilakukan oleh pejabat yang ditunjuk oleh Kepala BNPB bersama dengan pejabat yang ditunjuk oleh Gubernur/Kepala BPBD tingkat Provinsi dan Bupati/Walikota/Ketua BPBD tingkat Kabupaten/Kota.
B. Pelaporan
1. Penerima bantuan Dana Siap Pakai wajib menyampaikan laporan pertanggungjawaban pelaksanaan penggunaan Dana Siap Pakai.
2. Laporan pertanggungjawaban selambat-lambatnya disampaikan 3 (tiga) bulan setelah masa tanggap darurat dan ditujukan kepada Kepala Badan Nasional Penanggulangan Bencana.
Laporan pertanggungjawaban meliputi:
a. Realisasi fisik
b. Realisasi anggaran');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8759, 'BAB IV PEMANTAUAN DAN PELAPORAN Agar pengelolaan dana berjalan lancar dan transparan maka perlu dilakukan pemantauan dan pelaporan yang dilakukan secara efektif dan terpadu. Pemantauan dan pelaporan dilakukan BNPB dan BPBD serta instansi terkait. Setelah kegiatan selesai, yaitu setelah selesainya masa tanggap darurat, pengelola bantuan Dana Siap Pakai harus melaporkan semua kegiatan dan laporan pertanggungjawaban keuangan kepada Kepala BNPB.
A. Pemantauan
1. BNPB bersama dengan instansi/lembaga terkait secara selektif memantau pelaksanaan penggunaan Dana Siap Pakai mulai dari proses pelaksanaan administrasi sampai dengan fisik kegiatan.
2. Pemantauan terhadap penggunaan Dana Siap Pakai di daerah dilakukan oleh pejabat yang ditunjuk oleh Kepala BNPB bersama dengan pejabat yang ditunjuk oleh Gubernur/Kepala BPBD tingkat Provinsi dan Bupati/Walikota/Ketua BPBD tingkat Kabupaten/Kota.
B. Pelaporan
1. Penerima bantuan Dana Siap Pakai wajib menyampaikan laporan pertanggungjawaban pelaksanaan penggunaan Dana Siap Pakai.
2. Laporan pertanggungjawaban selambat-lambatnya disampaikan 3 (tiga) bulan setelah masa tanggap darurat dan ditujukan kepada Kepala Badan Nasional Penanggulangan Bencana.
Laporan pertanggungjawaban meliputi:
a. Realisasi fisik
b. Realisasi anggaran', 'Lampiran hal. 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8760, 'perka-6-2008', 26, 'lampiran', 'Lampiran hal. 18', NULL, 18, 'c. Data pendukung lainnya BAB V PENGAWASAN, SANKSI, DAN PENGADUAN MASYARAKAT A. Pengawasan Kegiatan pengawasan yang dimaksud adalah kegiatan yang bertujuan untuk mengurangi atau menghindari masalah yang berhubungan dengan penyalahgunaan wewenang dan segala bentuk penyimpangan lainnya, yang dapat berakibat pada pemborosan keuangan negara.
Pengawasan dalam pengelolaan Dana Siap Pakai meliputi pengawasan melekat (Waskat), pengawasan eksternal serta internal pemerintah, dan pengawasan masyarakat.
1. Pengawasan Melekat Pengawasan melekat dilakukan oleh pimpinan masing-masing instansi kepada bawahannya baik di tingkat pusat, provinsi, kabupaten/kota.
2. Pengawasan Eksternal dan Internal Pemerintah
a. Pengawas eksternal dilakukan oleh Badan Pemeriksa Keuangan (BPK).
b. Pengawas internal dilakukan oleh Inspektur Utama BNPB, Badan Pengawasan Keuangan dan Pembangunan (BPKP).
Instansi tersebut bertanggungjawab untuk melakukan audit sesuai dengan kebutuhan lembaga tersebut atau permintaan instansi yang akan diaudit.
3. Pengawasan Masyarakat Dalam rangka transparansi dalam pemanfaatan Dana Siap Pakai, pengawasannya juga dapat dilakukan oleh unsur masyarakat.
Masyarakat melakukan pengawasan dalam rangka memantau pelaksanaan dalam pengelolaan Dana Siap Pakai, namun tidak melakukan audit. Apabila terdapat indikasi penyimpangan dalam pengelolaan Dana Siap Pakai, masyarakat dapat melaporkannya kepada instansi yang berwenang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8760, 'c. Data pendukung lainnya BAB V PENGAWASAN, SANKSI, DAN PENGADUAN MASYARAKAT A. Pengawasan Kegiatan pengawasan yang dimaksud adalah kegiatan yang bertujuan untuk mengurangi atau menghindari masalah yang berhubungan dengan penyalahgunaan wewenang dan segala bentuk penyimpangan lainnya, yang dapat berakibat pada pemborosan keuangan negara.
Pengawasan dalam pengelolaan Dana Siap Pakai meliputi pengawasan melekat (Waskat), pengawasan eksternal serta internal pemerintah, dan pengawasan masyarakat.
1. Pengawasan Melekat Pengawasan melekat dilakukan oleh pimpinan masing-masing instansi kepada bawahannya baik di tingkat pusat, provinsi, kabupaten/kota.
2. Pengawasan Eksternal dan Internal Pemerintah
a. Pengawas eksternal dilakukan oleh Badan Pemeriksa Keuangan (BPK).
b. Pengawas internal dilakukan oleh Inspektur Utama BNPB, Badan Pengawasan Keuangan dan Pembangunan (BPKP).
Instansi tersebut bertanggungjawab untuk melakukan audit sesuai dengan kebutuhan lembaga tersebut atau permintaan instansi yang akan diaudit.
3. Pengawasan Masyarakat Dalam rangka transparansi dalam pemanfaatan Dana Siap Pakai, pengawasannya juga dapat dilakukan oleh unsur masyarakat.
Masyarakat melakukan pengawasan dalam rangka memantau pelaksanaan dalam pengelolaan Dana Siap Pakai, namun tidak melakukan audit. Apabila terdapat indikasi penyimpangan dalam pengelolaan Dana Siap Pakai, masyarakat dapat melaporkannya kepada instansi yang berwenang.', 'Lampiran hal. 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2008 tentang Pedoman Penggunaan Dana Siap Pakai');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8761, 'perka-6-2008', 27, 'lampiran', 'Lampiran hal. 19', NULL, 19, 'B. Sanksi Terhadap penyalahgunaan wewenang yang dapat merugikan negara akan dikenakan sanksi oleh aparat/pejabat yang berwenang sesuai peraturan yang berlaku. Sanksi kepada oknum yang melakukan penyalahgunaan wewenang dapat diberikan dalam berbagai bentuk diantaranya:
1. penerapan sanksi administratif.
2. penerapan tuntutan perbendaharaan dan atau tuntutan ganti rugi.
3. penerapan sanksi pidana sesuai dengan ketentuan perundang-undangan yang berlaku.
C. Pengaduan Masyarakat Masyarakat yang menemukan masalah atau hal-hal yang perlu diklarifikasi dapat mengakses http:www.bnpb.go.id atau telepon ke nomor (021) 3458400, fax ke nomor (021) 3458500 atau email ke posko@bnpb.go.id. BPBD di tingkat Provinsi dan Kabupaten/Kota diharapkan menyediakan nomor telepon/email untuk menampung pertanyaan/ pengaduan masyarakat di masing-masing wilayah yang menjadi tanggungjawabnya.
BAB VI PENUTUP Dengan berlakunya pedoman ini maka pedoman/peraturan sebelumnya yang mengatur hal yang sama dinyatakan tidak berlaku lagi.
Peraturan ini berlaku sejak tanggal ditetapkan, dengan ketentuan apabila terdapat perubahan akan diperbaiki sebagaimana mestinya.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si.
LAMPIRAN Lampiran - 1 Badan Nasional Penanggulangan Bencana (BNPB) KWITANSI Sudah terima dari : BADAN NASIONAL PENANGGULANGAN BENCANA Uang sebesar : Rp.
Terbilang :');
