7. Keputusan Presiden Nomor 29/M Tahun 2008 tanggal 23 April 2008 tentang Pengangkatan Kepala Badan Nasional Penanggulangan Bencana;', 'Mengingat', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8771, 'perka-6-2009', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEDOMAN PERGUDANGAN.');
