INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8772, 'perka-6-2009', 4, 'pasal', 'Pasal 1', NULL, 2, 'Pedoman pergudangan merupakan panduan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/Lembaga dan penyelenggara penanggulangan bencana agar terwujudnya efektifitas dan efisiensi dalam pengelolaan logistik dan peralatan. www.peraturan.go.id 3 2014, No. 1414');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8772, 'Pedoman pergudangan merupakan panduan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/Lembaga dan penyelenggara penanggulangan bencana agar terwujudnya efektifitas dan efisiensi dalam pengelolaan logistik dan peralatan. www.peraturan.go.id 3 2014, No. 1414', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8773, 'perka-6-2009', 5, 'pasal', 'Pasal 2', NULL, 3, 'Pedoman sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian yang tidak terpisahkan dari peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8773, 'Pedoman sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian yang tidak terpisahkan dari peraturan ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8774, 'perka-6-2009', 6, 'pasal', 'Pasal 3', NULL, 3, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8774, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8775, 'perka-6-2009', 7, 'lain', 'Penutup', NULL, 3, 'Ditetapkan di Jakarta pada tanggal 25 September 2009 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN www.peraturan.go.id 2014, No. 1414 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8775, 'Ditetapkan di Jakarta pada tanggal 25 September 2009 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 29 September 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN www.peraturan.go.id 2014, No. 1414 4', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8776, 'perka-6-2009', 8, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 6 TAHUN 2009 TENTANG PEDOMAN PERGUDANGAN BAB I PENDAHULUAN A. Latar Belakang Dalam rangka penanggulangan bencana telah ditetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana No. 13 Tahun 2008, tentang Pedoman Manajemen Logistik dan Peralatan agar pengelolaan logistik dan peralatan dapat dilaksanakan dengan cepat, tepat, terpadu dan akuntabel.
Pergudangan merupakan bagian dari mata rantai pasokan sehingga menjadi bagian penting dari tahapan dalam proses manajemen logistik dan peralatan. Pergudangan meliputi penerimaan dan penanganan, penyimpanan, pemeliharaan, pendistribusian, pengendalian dan pemusnahan serta pelaporan logistik dan peralatan penanggulangan bencana agar kualitas dan kuantitas tetap terjamin.
Manfaat pergudangan adalah untuk:
1. Terjaganya kualitas dan kuantitas logistik dan peralatan.
2. Tertatanya logistik dan peralatan.
3. Peningkatanpelayanan pendistribusian.
4. Tersedianya data dan informasi yang lebih akurat, aktual dan akuntabel.
5. Kemudahan akses dalarn pengendalian dan pengawasan.
6. Tertib administrasi.
Untuk mewujudkan efektifitas dan efisiensi dalam pengelolaan logistik dan peralatan dalam penanggulangan bencana perlu Pedoman Pergudangan.
B. Maksud dan Tujuan Maksud pedoman ini adalah sebagai panduan untuk pengelolaan pergudangan logistik dan peralatan dalam rangka penanggulangan bencana, bagi pengelola gudang baik di pusat maupun daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8776, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 6 TAHUN 2009 TENTANG PEDOMAN PERGUDANGAN BAB I PENDAHULUAN A. Latar Belakang Dalam rangka penanggulangan bencana telah ditetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana No. 13 Tahun 2008, tentang Pedoman Manajemen Logistik dan Peralatan agar pengelolaan logistik dan peralatan dapat dilaksanakan dengan cepat, tepat, terpadu dan akuntabel.
Pergudangan merupakan bagian dari mata rantai pasokan sehingga menjadi bagian penting dari tahapan dalam proses manajemen logistik dan peralatan. Pergudangan meliputi penerimaan dan penanganan, penyimpanan, pemeliharaan, pendistribusian, pengendalian dan pemusnahan serta pelaporan logistik dan peralatan penanggulangan bencana agar kualitas dan kuantitas tetap terjamin.
