INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8778, 'perka-6-2009', 10, 'lampiran', 'Lampiran hal. 5', NULL, 5, '10. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008, tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana;
D. Pengertian
1. Pergudangan adalah segala upaya pengelolaan gudang yang meliputi penerimaan, penyimpanan, pemeliharaan, pendistribusian, pengendalian dan pemusnahan serta pelaporan logistik dan peralatan penanggulangan bencana agar kualitas dan kuantitas tetap terjamin.
2. Logistik adalah segala sesuatu yang berujud yang dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri atas sandang, pangan dan papan atau turunannya. Termasuk dalam www.peraturan.go.id 2014, No. 1414 6 kategori logistik adalah barang yang habis pakai atau dikonsumsi, misalnya sembako (sembilan bahan pokok), obat-obatan, pakaian dan kelengkapannya, air, jas tidur dan sebagainya.
3. Peralatan adalah segala bentuk alat dan peralatan yang dapat dipergunakan untuk membantu pencarian, penyelamatan dan evakuasi masyarakat terkena bencana, membantu pemenuhan kebutuhan dasar dan untuk pemulihan segera prasarana dan sarana vital.
E. Ruang Lingkup dan Sistematika Pedoman pergudangan logistik dan peralatan penanggulangan bencana ini meliputi beberapa aspek tentang penerimaan, penyimpanan, pemeliharaan, perindustrian dan pengendalian logistik dan peralatan yang harus dilaksanakan oleh pengelola gudang.
Pedoman ini disusun dengan sistematika sebagai berikut:
I. PENDAHULUAN
II. PENGELOLAAN PERGUDANGAN
III. DENAH, SARANA DAN KEAMANAN GUDANG');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8778, '10. Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 13 Tahun 2008, tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana;
D. Pengertian
1. Pergudangan adalah segala upaya pengelolaan gudang yang meliputi penerimaan, penyimpanan, pemeliharaan, pendistribusian, pengendalian dan pemusnahan serta pelaporan logistik dan peralatan penanggulangan bencana agar kualitas dan kuantitas tetap terjamin.
2. Logistik adalah segala sesuatu yang berujud yang dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri atas sandang, pangan dan papan atau turunannya. Termasuk dalam www.peraturan.go.id 2014, No. 1414 6 kategori logistik adalah barang yang habis pakai atau dikonsumsi, misalnya sembako (sembilan bahan pokok), obat-obatan, pakaian dan kelengkapannya, air, jas tidur dan sebagainya.
3. Peralatan adalah segala bentuk alat dan peralatan yang dapat dipergunakan untuk membantu pencarian, penyelamatan dan evakuasi masyarakat terkena bencana, membantu pemenuhan kebutuhan dasar dan untuk pemulihan segera prasarana dan sarana vital.
E. Ruang Lingkup dan Sistematika Pedoman pergudangan logistik dan peralatan penanggulangan bencana ini meliputi beberapa aspek tentang penerimaan, penyimpanan, pemeliharaan, perindustrian dan pengendalian logistik dan peralatan yang harus dilaksanakan oleh pengelola gudang.
Pedoman ini disusun dengan sistematika sebagai berikut:
I. PENDAHULUAN
II. PENGELOLAAN PERGUDANGAN
III. DENAH, SARANA DAN KEAMANAN GUDANG', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8779, 'perka-6-2009', 11, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'IV. SISTEM INFORMASI PERGUDANGAN
V. PENGELOLA GUDANG
VI. PENUTUP www.peraturan.go.id 7 2014, No. 1414 BAB II PENGELOLAAN PERGUDANGAN A. Strategi dan Kebijakan
1. Strategi Strategi pengelolaan pergudangan merupakan perencanaan umum dalam rangka mengelola gudang sebagai tempat penyimpanan bantuan logistik dan peralatan penanggulangan bencana. Strategi dalam pengelolaan gudang ini merupakan upaya penjaminan jumlah, jenis dan mutu bantuan logistik dan peralatan penanggulangan bencana.
2. Kebijakan Kebijakan pengelolaan pergudangan merupakan pelaksanaan pengelolaan bantuan logistik dan peralatan yang meliputi:
a. Penerimaan bantuan logistik dan peralatan untuk persediaan penanggulangan bencana.
b. Penyimpanan bantuan logistik dan peralatan penanggulangan bencana menjamin jumlah, jenis dan mutu bantuan logistik dan peralatan.
c. Pemeliharaan bantuan logistik dan peralatan penanggulangan bencana menjamin mutu bantuan logistik dan peralatan.
d. Pengamanan bantuan logistik dan peralatan penanggulangan bencana untuk menjamin keselamatan.
B. Mekanisme Pergudangan Mekanisme pergudangan meliputi proses sebagai berikut:
1. Penerimaaan Penerimaan merupakan proses penyerahan dan penerimaan logistik dan peralatan di gudang. Dalam proses penyerahan dan penerimaan ini dilakukan:
a. Pendataan jumlah dan mutu logistik dan peralatan harus sesuai dengan ketentuan yang berlaku/layak untuk diberikan kepada korban bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8779, 'IV. SISTEM INFORMASI PERGUDANGAN
V. PENGELOLA GUDANG
VI. PENUTUP www.peraturan.go.id 7 2014, No. 1414 BAB II PENGELOLAAN PERGUDANGAN A. Strategi dan Kebijakan
1. Strategi Strategi pengelolaan pergudangan merupakan perencanaan umum dalam rangka mengelola gudang sebagai tempat penyimpanan bantuan logistik dan peralatan penanggulangan bencana. Strategi dalam pengelolaan gudang ini merupakan upaya penjaminan jumlah, jenis dan mutu bantuan logistik dan peralatan penanggulangan bencana.
2. Kebijakan Kebijakan pengelolaan pergudangan merupakan pelaksanaan pengelolaan bantuan logistik dan peralatan yang meliputi:
a. Penerimaan bantuan logistik dan peralatan untuk persediaan penanggulangan bencana.
b. Penyimpanan bantuan logistik dan peralatan penanggulangan bencana menjamin jumlah, jenis dan mutu bantuan logistik dan peralatan.
c. Pemeliharaan bantuan logistik dan peralatan penanggulangan bencana menjamin mutu bantuan logistik dan peralatan.
d. Pengamanan bantuan logistik dan peralatan penanggulangan bencana untuk menjamin keselamatan.
B. Mekanisme Pergudangan Mekanisme pergudangan meliputi proses sebagai berikut:
1. Penerimaaan Penerimaan merupakan proses penyerahan dan penerimaan logistik dan peralatan di gudang. Dalam proses penyerahan dan penerimaan ini dilakukan:
a. Pendataan jumlah dan mutu logistik dan peralatan harus sesuai dengan ketentuan yang berlaku/layak untuk diberikan kepada korban bencana.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8780, 'perka-6-2009', 12, 'lampiran', 'Lampiran hal. 7', NULL, 7, 'b. Pencatatan administratif sebagai dokumen yang dapat dipertanggung jawabkan oleh petugas yang bersangkutan.
2. Penyimpanan Penyimpanan merupakan proses kegiatan penyimpanan logistik dan peralatan di gudang dengan cara menempatkan logistik dan peralatan yang diterima:
a. Penempatan sesuai dengan denah. www.peraturan.go.id 2014, No. 1414 8
b. Aman dari pencurian.
c. Aman dari gangguan fisik.
d. Aman dari pencemaran secara kimiawi dan biologi yang dapat merusak kualitas dan kuantitas.
e. Aman dari kebakaran.
f. Penataan sesuai dengan standar pergudangan.
3. Pemeliharaan Pemeliharaan merupakan kegiatan perawatan logistik dan peralatan agar kondisi tetap terjamin dan siap pakai untuk dipergunakan dalam penanggulangan bencana secara efektif dan efisien dan akuntabel, melalui prinsip:
a. 5R = Ringkas, Rapih, Resik (bersih), Rawat, Rajin (secara terus menerus).
b. First In First Out (FIFO) yaitu logistik dan peralatan yang pertama masuk adalah yang pertama harus keluar.
c. First Expired Date First Out (FEFO) yaitu logistik dan peralatan yang pertama kadaluwarsa harus yang pertama keluar untuk didistribusikan. Dalam penyusunan logistik dan peralatan yang punya masa kedaluwarsanya lebih awal atau yang diterima lebih awal harus digunakan lebih awal sebab logistik dan peralatan yang datang lebih awal biasanya juga diproduksi lebih awal dan umurnya relatif lebih tua dan masa kadaluwarsanya mungkin lebih awal.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8780, 'b. Pencatatan administratif sebagai dokumen yang dapat dipertanggung jawabkan oleh petugas yang bersangkutan.
2. Penyimpanan Penyimpanan merupakan proses kegiatan penyimpanan logistik dan peralatan di gudang dengan cara menempatkan logistik dan peralatan yang diterima:
a. Penempatan sesuai dengan denah. www.peraturan.go.id 2014, No. 1414 8
b. Aman dari pencurian.
c. Aman dari gangguan fisik.
d. Aman dari pencemaran secara kimiawi dan biologi yang dapat merusak kualitas dan kuantitas.
e. Aman dari kebakaran.
f. Penataan sesuai dengan standar pergudangan.
3. Pemeliharaan Pemeliharaan merupakan kegiatan perawatan logistik dan peralatan agar kondisi tetap terjamin dan siap pakai untuk dipergunakan dalam penanggulangan bencana secara efektif dan efisien dan akuntabel, melalui prinsip:
a. 5R = Ringkas, Rapih, Resik (bersih), Rawat, Rajin (secara terus menerus).
b. First In First Out (FIFO) yaitu logistik dan peralatan yang pertama masuk adalah yang pertama harus keluar.
c. First Expired Date First Out (FEFO) yaitu logistik dan peralatan yang pertama kadaluwarsa harus yang pertama keluar untuk didistribusikan. Dalam penyusunan logistik dan peralatan yang punya masa kedaluwarsanya lebih awal atau yang diterima lebih awal harus digunakan lebih awal sebab logistik dan peralatan yang datang lebih awal biasanya juga diproduksi lebih awal dan umurnya relatif lebih tua dan masa kadaluwarsanya mungkin lebih awal.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8781, 'perka-6-2009', 13, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'd. Logistik dan peralatan disusun di atas pallet secara rapih dan teratur, sesuai dengan ketentuan.
4. Pendistribusian Pendistribusian merupakan proses kegiatan pengeluaran dan penyaluran logistik dan peralatan dari gudang untuk diserahkan kepada yang berhak, melalui suatu proses serah terima yang dapat dipertanggung jawabkan, disertai dengan bukti serah terima. Hal ini dilakukan berdasarkan permintaan sesuaidengan kebutuhan penanggulangan bencana.
5. Pengendalian Pengendalian merupakan proses kegiatan pengawasan atas pergerakan masuk keluarnya logistik dan peralatan dari dan ke gudang agar persediaan dan penempatan dapat diketahui secara cepat, tepat dan akurat serta akuntabel. Pengendalian dilaksanakan dengan menggunakan formulir dalam lampiran.
6. Penghapusan. www.peraturan.go.id 9 2014, No. 1414
a. Penghapusan merupakan rangkaian kegiatan pemusnahan logistik dan peralatan dalam rangka pembebasan barang milik/kekayaan negara dari tanggung jawab berdasarkan peraturan perundangan-undangan yang berlaku.
b. Tujuan penghapusan adalah sebagai berikut:
1) Penghapusan merupakan bentuk pertanggung jawaban administrasi petugas terhadap logistik dan peralatan yang dikelola, yang sudah ditetapkan untuk dihapuskan/ dimusnahkan sesuai dengan ketentuan yang berlaku.
2) Menghindari pembiayaan (biaya penyimpanan, pemeliharaan, penjagaan dan lain-lain) atau barang yang sudah tidak layak untuk dipelihara.
3) Menjaga keselamatan agar terhindar dari pencemaran lingkungan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8781, 'd. Logistik dan peralatan disusun di atas pallet secara rapih dan teratur, sesuai dengan ketentuan.
4. Pendistribusian Pendistribusian merupakan proses kegiatan pengeluaran dan penyaluran logistik dan peralatan dari gudang untuk diserahkan kepada yang berhak, melalui suatu proses serah terima yang dapat dipertanggung jawabkan, disertai dengan bukti serah terima. Hal ini dilakukan berdasarkan permintaan sesuaidengan kebutuhan penanggulangan bencana.
5. Pengendalian Pengendalian merupakan proses kegiatan pengawasan atas pergerakan masuk keluarnya logistik dan peralatan dari dan ke gudang agar persediaan dan penempatan dapat diketahui secara cepat, tepat dan akurat serta akuntabel. Pengendalian dilaksanakan dengan menggunakan formulir dalam lampiran.
6. Penghapusan. www.peraturan.go.id 9 2014, No. 1414
a. Penghapusan merupakan rangkaian kegiatan pemusnahan logistik dan peralatan dalam rangka pembebasan barang milik/kekayaan negara dari tanggung jawab berdasarkan peraturan perundangan-undangan yang berlaku.
b. Tujuan penghapusan adalah sebagai berikut:
1) Penghapusan merupakan bentuk pertanggung jawaban administrasi petugas terhadap logistik dan peralatan yang dikelola, yang sudah ditetapkan untuk dihapuskan/ dimusnahkan sesuai dengan ketentuan yang berlaku.
2) Menghindari pembiayaan (biaya penyimpanan, pemeliharaan, penjagaan dan lain-lain) atau barang yang sudah tidak layak untuk dipelihara.
3) Menjaga keselamatan agar terhindar dari pencemaran lingkungan.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8782, 'perka-6-2009', 14, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'c. Kegiatan Penghapusan adalah sebagai berikut:
1) Membuat daftar logistik dan peralatan yang akan dihapuskan beserta alasan-alasannya.
2) Pisahkan logistik dan peralatan yang kadaluwarsa/rusak pada tempat tertentu sampai pelaksanaan pemusnahan.
3) Melaporkan kepada atasan mengenai logistik dan peralatan yang akan dihapuskan.
4) Membentuk panitia pencelaan dan penghapusan logistik dan peralatan melalui Surat Keputusan dari pejabat yang berwenang.
5) Membuat berita acara hasil pencelaan dan penghapusan logistik dan peralatan yang akan dihapuskan.
6) Melaporkan hasil pencelaan dan penghapusan kepada pejabat yang berwenang.
7) Melaksanakan penghapusan dan pemusnahan setelah ada keputusan dari pejabat yang berwenang.
Pada Lampiran I sampai dengan Lampiran IV dapat dilihat contoh formulir yang dapat mendukung pencatatan logistik dan peralatan dalam pengelolaan pergudangan. www.peraturan.go.id 2014, No. 1414 10 BAB III DENAH, SARANA DAN KEAMANAN GUDANG A. Denah Gudang Untuk memudahkan dalam penerimaan, penyimpanan, penyusunan, pemeliharaan, pencarian, pendistribusian dan pengawasan logistik dan peralatan, maka diperlukan pengaturan tata letak ruang gudang dengan baik. Faktor-faktor yang perlu dipertimbangkan dalam merancang tata letak gudang adalah sebagai berikut:
1. Untuk kemudahan bergerak, gudang jangan disekat-sekat, kecuali jika diperlukan. Perhatikan posisi dinding dan pintu untuk mempermudah gerakan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8782, 'c. Kegiatan Penghapusan adalah sebagai berikut:
1) Membuat daftar logistik dan peralatan yang akan dihapuskan beserta alasan-alasannya.
2) Pisahkan logistik dan peralatan yang kadaluwarsa/rusak pada tempat tertentu sampai pelaksanaan pemusnahan.
3) Melaporkan kepada atasan mengenai logistik dan peralatan yang akan dihapuskan.
4) Membentuk panitia pencelaan dan penghapusan logistik dan peralatan melalui Surat Keputusan dari pejabat yang berwenang.
5) Membuat berita acara hasil pencelaan dan penghapusan logistik dan peralatan yang akan dihapuskan.
6) Melaporkan hasil pencelaan dan penghapusan kepada pejabat yang berwenang.
7) Melaksanakan penghapusan dan pemusnahan setelah ada keputusan dari pejabat yang berwenang.
Pada Lampiran I sampai dengan Lampiran IV dapat dilihat contoh formulir yang dapat mendukung pencatatan logistik dan peralatan dalam pengelolaan pergudangan. www.peraturan.go.id 2014, No. 1414 10 BAB III DENAH, SARANA DAN KEAMANAN GUDANG A. Denah Gudang Untuk memudahkan dalam penerimaan, penyimpanan, penyusunan, pemeliharaan, pencarian, pendistribusian dan pengawasan logistik dan peralatan, maka diperlukan pengaturan tata letak ruang gudang dengan baik. Faktor-faktor yang perlu dipertimbangkan dalam merancang tata letak gudang adalah sebagai berikut:
1. Untuk kemudahan bergerak, gudang jangan disekat-sekat, kecuali jika diperlukan. Perhatikan posisi dinding dan pintu untuk mempermudah gerakan.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8783, 'perka-6-2009', 15, 'lampiran', 'Lampiran hal. 10', NULL, 10, '2. Berdasarkan arah arus penerimaan dan pengeluaran logistik dan peralatan, tata letak ruang gudang perlu memiliki lorong dapat ditata berdasarkansistem:
a. Arus garis lurus
b. Arus huruf U
c. Arus huruf L
3. Pengaturan sirkulasi udara: salah satu faktor penting dalam merancang gudang adalah adanya sirkulasi udara yang cukup didalam ruangan, termasuk pengaturan kelembaban udara dan pengaturan pencahayaan.
4. Penggunaan rak dan pallet yang tepat dapat meningkatkan sirkulasi udara, perlindungan terhadap banjir, serangan hama, kelembaban dan efisiensi penanganan.
5. Penyimpanan khusus
a. Obat, Vaksin dan serum memerlukan tempat khusus seperti lemari pendingin khusus (cold chain) dan harus dilindungi dari kemungkinan putusnya aliran listrik.
b. Bahan kimia harus disimpan dalam bangunan khusus yang terpisah dari gudang induk.
c. Peralatan besar/alat berat memerlukan tempat khusus yang cukup untuk penyimpanan dan pemeliharaannya.
B. Peralatan Sarana Pendukung Pergudangan Penyediaan peralatan sarana dalam mendukung manajemen pergudangan yang baik, bertujuan untuk mendukung kelancaran penerimaan dan pengeluaran barang sehingga setiap saat mudah dimobilisasi dan didistribusikan bila terjadi bencana. Adapun sarana yang sebaiknya tersedia adalah sebagai berikut:
1. Gedung/bangunan gudang
2. Pembangkit Listrik atau lainnya www.peraturan.go.id 11 2014, No. 1414
3. Alat angkutan/transportasi: kendaraan roda dua, roda empat, forklift dan lainnya');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8783, '2. Berdasarkan arah arus penerimaan dan pengeluaran logistik dan peralatan, tata letak ruang gudang perlu memiliki lorong dapat ditata berdasarkansistem:
a. Arus garis lurus
b. Arus huruf U
c. Arus huruf L
3. Pengaturan sirkulasi udara: salah satu faktor penting dalam merancang gudang adalah adanya sirkulasi udara yang cukup didalam ruangan, termasuk pengaturan kelembaban udara dan pengaturan pencahayaan.
