INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8793, 'perka-6-2009', 25, 'lampiran', 'Lampiran hal. 22', NULL, 22, '3. Tanggung a. Menjaga keamanan barang di gudang pada setiap jawab saat agar kondisi, kuantitas serta kualitas isi gudang beserta petugas pengelolanya terjamin baik dan berfungsi baik untuk dapat segera membantu korban bencana sesuai peraturan yang berlaku.
b. Menjaga keamanan, keselamatan dan pemeliharaan aset negara berupa gudang beserta barang logistik dan peralatan.
c. Mengkoordinasikan semua aktivitas dan informasi pengamanan dan keamanan dengan pihak terkait seperti kepolisian maupun TNI.
d. Meningkatkan kapasitas dan kemampuan keamanan pergudangan yang lebih efektif dan efisien. www.peraturan.go.id 23 2014, No. 1414 BAB VI PENUTUP Pedoman pergudangan ini diharapkan dapat bermanfaat dan membantu dalam penerimaan dan penanganan, penyimpanan, pemeliharaan, pendistribusian dan pengendalian logistik dan peralatan di pusat dan daerah. Walaupun ada keterbatasan tenaga, dana, sarana dan prasarana pendukungnya, bila penyimpanan logistik dan peralatan dilakukan secara baik diharapkan dapat diketahui jumlah dan jenis persediaan logistik dan peralatan di gudang secara cepat dan tepat.
Sesuai dengan perkembangan, Pedoman ini terbuka untuk disesuaikan dan diperbaiki. Pedoman yang berkaitan dengan pergudangan tetap berlaku sepanjang tidak bertentangan dengan Peraturan Kepala Badan Nasional Penanggulangan Bencana ini.');
