INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8797, 'perka-6-2009', 29, 'lampiran', 'Lampiran hal. 28', NULL, 28, '- ruang penyimpanan utama (..m?) 3 Ruang penjaga malam (...m?) Tinggi bangunan : jarak lantai dari langit-langit minimal 4,5 m- 5 m Langit-langit : Dari triplek 5 mm dengan konstruksi menempel pada bagian atap untuk memaksimalkan kapasitas penyimpanan. Sebaiknya dilindungi teralis besi Ventilasi : Tiap 5 m lebar dinding yang berhadapan dengan bagian luar bangunan dilengkapi jendela kecil berukuran 1,5x0,5m. Sebaiknya dilengkapi exhaust fan dan teralis Pagar : terbuat dari beton setinggi minimal ...m dari permukaan tanah (bagian belakang dan samping kiri - kanan), untuk bagian depan terbuat dari besi dengan tinggi minimal Pintu Gerbang : terbuat dari besi dengan Lebar Tinggi ...m lebar ...m, dilengkapi switch alarm magnetik Pintu : Lebar x tinggi 2x5m dengan pengamanan ganda loading/transito-in bagian luar dilengkapi pintu berteralis dari besi & diameter 12 inch unloading/transito-out Lantai : Keramik warna putih Bagian yang bersinggungan dengan dinding tidak membentuk sudut Dinding : 38 m dari permukaaan lantai dilapisi keramik Dinding dicat berwarna terang Sumber air : Saluran air bersih PAM atau sumur bor Listrik 1 nana watt Saluran air kotor ! sekeliling gudang dilengkapi dengan saluran air kotor Pengamanan : Seluruh ventilasi dan kusen jendela dilengkapi dengan teralis. Pengamanan dengan sistem alarm magnetik sangat dianjurkan, dan diaktifkan pada saat malam hari.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8797, '- ruang penyimpanan utama (..m?) 3 Ruang penjaga malam (...m?) Tinggi bangunan : jarak lantai dari langit-langit minimal 4,5 m- 5 m Langit-langit : Dari triplek 5 mm dengan konstruksi menempel pada bagian atap untuk memaksimalkan kapasitas penyimpanan. Sebaiknya dilindungi teralis besi Ventilasi : Tiap 5 m lebar dinding yang berhadapan dengan bagian luar bangunan dilengkapi jendela kecil berukuran 1,5x0,5m. Sebaiknya dilengkapi exhaust fan dan teralis Pagar : terbuat dari beton setinggi minimal ...m dari permukaan tanah (bagian belakang dan samping kiri - kanan), untuk bagian depan terbuat dari besi dengan tinggi minimal Pintu Gerbang : terbuat dari besi dengan Lebar Tinggi ...m lebar ...m, dilengkapi switch alarm magnetik Pintu : Lebar x tinggi 2x5m dengan pengamanan ganda loading/transito-in bagian luar dilengkapi pintu berteralis dari besi & diameter 12 inch unloading/transito-out Lantai : Keramik warna putih Bagian yang bersinggungan dengan dinding tidak membentuk sudut Dinding : 38 m dari permukaaan lantai dilapisi keramik Dinding dicat berwarna terang Sumber air : Saluran air bersih PAM atau sumur bor Listrik 1 nana watt Saluran air kotor ! sekeliling gudang dilengkapi dengan saluran air kotor Pengamanan : Seluruh ventilasi dan kusen jendela dilengkapi dengan teralis. Pengamanan dengan sistem alarm magnetik sangat dianjurkan, dan diaktifkan pada saat malam hari.', 'Lampiran hal. 28', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2009 tentang Pedoman Pergudangan');
