INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8820, 'perka-6-2014', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka penyelenggaraan penanggulangan bencana, Badan Nasional Penanggulangan Bencana memberikan pedoman dan pengarahan serta merumuskan kebijakan sesuai dengan kewenangannya;
b. bahwa perlu menciptakan tertib administrasi, peningkatan koordinasi dan kelancaran proses penyusunan peraturan perundang-undangan sesuai dengan Undang-Undang Nomor 12 Tahun 2011 tentang Pembentukan Peraturan Perundang-Undangan;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Pembentukan Produk Hukum di lingkungan Badan Nasional Penanggulangan Bencana;');
