INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8822, 'perka-6-2014', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEMBENTUKAN PRODUK HUKUM DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8822, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PEMBENTUKAN PRODUK HUKUM DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8823, 'perka-6-2014', 4, 'pasal', 'Pasal 1', 'BAB II PEMBENTUKAN RANCANGAN UNDANG-UNDANG, PERATURAN PEMERINTAH PENGGANTI UNDANG-UNDANG, PERATURAN PEMERINTAH,', 3, 'Dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana ini yang dimaksud dengan:
1. Produk hukum adalah peraturan perundang-undangan maupun dokumen kebijakan non-perundang-undangan yang sesuai dengan peraturan perundang-undangan yang berlaku.
2. Pembentukan produk hukum adalah proses pembuatan peraturan perundang-undangan maupun dokumen kebijakan non-perundang-undangan.
3. Pembentukan peraturan perundang-undangan adalah proses pembuatan peraturan perundang-undangan yang mencakup tahapan perencanaan, penyusunan, pembahasan, pengesahan atau penetapan, dan pengundangan.
4. Peraturan Perundang-undangan adalah peraturan tertulis yang memuat norma hukum yang mengikat secara umum dan dibentuk atau ditetapkan oleh lembaga negara atau pejabat yang berwenang melalui prosedur yang ditetapkan dalam Peraturan Perundang-undangan.
5. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB, adalah lembaga pemerintah Non-Kementerian setingkat Menteri sesuai dengan ketentuan peraturan perundang-undangan.
6. Peraturan Kepala Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat Peraturan Kepala BNPB, adalah peraturan yang dibuat oleh Kepala BNPB.
7. Program Legislasi Penanggulangan Bencana, yang selanjutnya disingkat Proleg PB, adalah perencanaan program pembentukan peraturan perundang-undangan di lingkungan BNPB.
8. Pemrakarsa adalah pihak di lingkungan BNPB yang mengusulkan pembentukan peraturan perundang-undangan.
9. Tim Teknis adalah Tim yang dibentuk oleh pemrakarsa untuk keperluan pembentukan peraturan perundang-undangan.
557, No.2014 4
10. Panitia antar Kedeputian adalah panitia yang dibentuk oleh Sekretaris Utama untuk keperluan pembentukan peraturan perundang-undangan.
DAN PERATURAN PRESIDEN');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8823, 'Dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana ini yang dimaksud dengan:
1. Produk hukum adalah peraturan perundang-undangan maupun dokumen kebijakan non-perundang-undangan yang sesuai dengan peraturan perundang-undangan yang berlaku.
2. Pembentukan produk hukum adalah proses pembuatan peraturan perundang-undangan maupun dokumen kebijakan non-perundang-undangan.
3. Pembentukan peraturan perundang-undangan adalah proses pembuatan peraturan perundang-undangan yang mencakup tahapan perencanaan, penyusunan, pembahasan, pengesahan atau penetapan, dan pengundangan.
4. Peraturan Perundang-undangan adalah peraturan tertulis yang memuat norma hukum yang mengikat secara umum dan dibentuk atau ditetapkan oleh lembaga negara atau pejabat yang berwenang melalui prosedur yang ditetapkan dalam Peraturan Perundang-undangan.
5. Badan Nasional Penanggulangan Bencana yang selanjutnya disingkat BNPB, adalah lembaga pemerintah Non-Kementerian setingkat Menteri sesuai dengan ketentuan peraturan perundang-undangan.
6. Peraturan Kepala Badan Nasional Penanggulangan Bencana, yang selanjutnya disingkat Peraturan Kepala BNPB, adalah peraturan yang dibuat oleh Kepala BNPB.
7. Program Legislasi Penanggulangan Bencana, yang selanjutnya disingkat Proleg PB, adalah perencanaan program pembentukan peraturan perundang-undangan di lingkungan BNPB.
8. Pemrakarsa adalah pihak di lingkungan BNPB yang mengusulkan pembentukan peraturan perundang-undangan.
9. Tim Teknis adalah Tim yang dibentuk oleh pemrakarsa untuk keperluan pembentukan peraturan perundang-undangan.
557, No.2014 4
10. Panitia antar Kedeputian adalah panitia yang dibentuk oleh Sekretaris Utama untuk keperluan pembentukan peraturan perundang-undangan.
DAN PERATURAN PRESIDEN', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8824, 'perka-6-2014', 5, 'pasal', 'Pasal 2', 'BAB II PEMBENTUKAN RANCANGAN UNDANG-UNDANG, PERATURAN PEMERINTAH PENGGANTI UNDANG-UNDANG, PERATURAN PEMERINTAH,', 4, 'Pembentukan rancangan undang-undang, peraturan pemerintah pengganti undang-undang, peraturan pemerintah, dan peraturan presiden dilaksanakan sesuai dengan peraturan perundang-undangan yang berlaku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8824, 'Pembentukan rancangan undang-undang, peraturan pemerintah pengganti undang-undang, peraturan pemerintah, dan peraturan presiden dilaksanakan sesuai dengan peraturan perundang-undangan yang berlaku.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8825, 'perka-6-2014', 6, 'pasal', 'Pasal 3', 'BAB III PEMBENTUKAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Kesatu Perencanaan', 4, '(1) BNPB menyiapkan draft awal rancangan undang-undang, rancangan peraturan pemerintah pengganti undang-undang, rancangan peraturan pemerintah, dan rancangan peraturan presiden.
(2) Tata cara penyiapan draft awal sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8825, '(1) BNPB menyiapkan draft awal rancangan undang-undang, rancangan peraturan pemerintah pengganti undang-undang, rancangan peraturan pemerintah, dan rancangan peraturan presiden.
(2) Tata cara penyiapan draft awal sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8826, 'perka-6-2014', 7, 'pasal', 'Pasal 4', 'BAB III PEMBENTUKAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Kesatu Perencanaan', 4, '(1) Perencanaan pembentukan Peraturan Kepala BNPB dilaksanakan dalam Proleg PB.
(2) Proleg PB disusun oleh Tim Penyusun Proleg PB.
(3) Proleg PB ditetapkan dengan Surat Keputusan Kepala BNPB.
(4) Proleg PB ditetapkan berdasarkan skala prioritas dalam jangka waktu 1 (satu) tahun.
(5) Proleg PB wajib memuat analisis pengurangan risiko bencana.
(6) Proleg PB wajib memuat analisis gender.
(7) Proleg PB wajib memuat analisis disabilitas.
5 2014, No.557');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8826, '(1) Perencanaan pembentukan Peraturan Kepala BNPB dilaksanakan dalam Proleg PB.
(2) Proleg PB disusun oleh Tim Penyusun Proleg PB.
(3) Proleg PB ditetapkan dengan Surat Keputusan Kepala BNPB.
(4) Proleg PB ditetapkan berdasarkan skala prioritas dalam jangka waktu 1 (satu) tahun.
(5) Proleg PB wajib memuat analisis pengurangan risiko bencana.
(6) Proleg PB wajib memuat analisis gender.
(7) Proleg PB wajib memuat analisis disabilitas.
5 2014, No.557', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8827, 'perka-6-2014', 8, 'pasal', 'Pasal 5', 'BAB III PEMBENTUKAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Kedua Penyusunan', 5, 'Dalam penyusunan Proleg PB sebagaimana dimaksud dalam Pasal 4, penyusunan daftar Rancangan Peraturan Kepala BNPB didasarkan atas:
a. perintah peraturan perundang-undangan yang lebih tinggi;
b. Rencana Strategis Badan;
c. Rencana Kerja tahunan Badan;
d. pelaksanaan kewenangan penyelenggaraan pemerintahan dalam penanggulangan bencana; dan
e. aspirasi serta kebutuhan hukum masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8827, 'Dalam penyusunan Proleg PB sebagaimana dimaksud dalam Pasal 4, penyusunan daftar Rancangan Peraturan Kepala BNPB didasarkan atas:
a. perintah peraturan perundang-undangan yang lebih tinggi;
b. Rencana Strategis Badan;
c. Rencana Kerja tahunan Badan;
d. pelaksanaan kewenangan penyelenggaraan pemerintahan dalam penanggulangan bencana; dan
e. aspirasi serta kebutuhan hukum masyarakat.', 'Pasal 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8828, 'perka-6-2014', 9, 'pasal', 'Pasal 6', 'BAB III PEMBENTUKAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Kedua Penyusunan', 5, 'Penyusunan rancangan Peraturan Kepala BNPB dapat diprakarsai oleh:
a. Sekretaris Utama;
b. Deputi Bidang Pencegahan dan Kesiapsiagaan;
c. Deputi Bidang Penanganan Darurat;
d. Deputi Bidang Rehabilitasi dan Rekonstruksi;
e. Deputi Bidang Logistik dan Peralatan;
f. Inspektur Utama;
g. Kepala Pusat Data, Informasi dan Hubungan Masyarakat; dan
h. Kepala Pusat Pendidikan dan Pelatihan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8828, 'Penyusunan rancangan Peraturan Kepala BNPB dapat diprakarsai oleh:
a. Sekretaris Utama;
b. Deputi Bidang Pencegahan dan Kesiapsiagaan;
c. Deputi Bidang Penanganan Darurat;
d. Deputi Bidang Rehabilitasi dan Rekonstruksi;
e. Deputi Bidang Logistik dan Peralatan;
f. Inspektur Utama;
g. Kepala Pusat Data, Informasi dan Hubungan Masyarakat; dan
h. Kepala Pusat Pendidikan dan Pelatihan.', 'Pasal 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8829, 'perka-6-2014', 10, 'pasal', 'Pasal 7', 'BAB III PEMBENTUKAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Kedua Penyusunan', 5, '(1) Penyusunan rancangan Peraturan Kepala BNPB sebagaimana dimaksud dalam Pasal 6 dilakukan melalui pembentukan Tim Teknis dan Panitia antar Kedeputian.
(2) Tim Teknis sebagaimana dimaksud pada ayat (1) dibentuk oleh Pemrakarsa.
(3) Panitia antar Kedeputian sebagaimana dimaksud pada ayat (1) dibentuk oleh Sekretaris Utama.
(4) Keanggotaan, tata cara kerja dan hal-hal teknis lain yang berkaitan dengan Tim Teknis dan Panitia antar Kedeputian diatur dalam Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8829, '(1) Penyusunan rancangan Peraturan Kepala BNPB sebagaimana dimaksud dalam Pasal 6 dilakukan melalui pembentukan Tim Teknis dan Panitia antar Kedeputian.
(2) Tim Teknis sebagaimana dimaksud pada ayat (1) dibentuk oleh Pemrakarsa.
(3) Panitia antar Kedeputian sebagaimana dimaksud pada ayat (1) dibentuk oleh Sekretaris Utama.
(4) Keanggotaan, tata cara kerja dan hal-hal teknis lain yang berkaitan dengan Tim Teknis dan Panitia antar Kedeputian diatur dalam Petunjuk Pelaksanaan.', 'Pasal 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8830, 'perka-6-2014', 11, 'pasal', 'Pasal 8', 'BAB III PEMBENTUKAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Kedua Penyusunan', 5, '(1) Tim Teknis menyusun rancangan Peraturan Kepala BNPB berdasarkan Proleg PB.
557, No.2014 6
(2) Tim Teknis menyusun rancangan Peraturan Kepala BNPB di luar Proleg PB, setelah terlebih dahulu mengajukan permohonan izin prakarsa kepada Kepala BNPB.
(3) Dalam menyusun draft awal rancangan Peraturan Kepala BNPB, Tim Teknis terlebih dahulu menyusun kajian mengenai materi yang akan diatur.
(4) Kajian sebagaimana dimaksud pada ayat (3) memuat dasar-dasar pemikiran, pokok dan lingkup materi yang akan diatur.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8830, '(1) Tim Teknis menyusun rancangan Peraturan Kepala BNPB berdasarkan Proleg PB.
557, No.2014 6
(2) Tim Teknis menyusun rancangan Peraturan Kepala BNPB di luar Proleg PB, setelah terlebih dahulu mengajukan permohonan izin prakarsa kepada Kepala BNPB.
(3) Dalam menyusun draft awal rancangan Peraturan Kepala BNPB, Tim Teknis terlebih dahulu menyusun kajian mengenai materi yang akan diatur.
(4) Kajian sebagaimana dimaksud pada ayat (3) memuat dasar-dasar pemikiran, pokok dan lingkup materi yang akan diatur.', 'Pasal 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8831, 'perka-6-2014', 12, 'pasal', 'Pasal 9', 'BAB III PEMBENTUKAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Ketiga Pembahasan', 6, 'Panitia antar Kedeputian bertugas untuk:
a. menyempurnakan kajian yang disusun oleh Tim Teknis;
b. menyempurnakan rancangan awal Peraturan Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8831, 'Panitia antar Kedeputian bertugas untuk:
a. menyempurnakan kajian yang disusun oleh Tim Teknis;
b. menyempurnakan rancangan awal Peraturan Kepala BNPB.', 'Pasal 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8832, 'perka-6-2014', 13, 'pasal', 'Pasal 10', 'BAB III PEMBENTUKAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Ketiga Pembahasan', 6, '(1) Pembahasan rancangan Peraturan Kepala BNPB dilaksanakan oleh Panitia antar Kedeputian.
(2) Ketentuan teknis pembahasan sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8832, '(1) Pembahasan rancangan Peraturan Kepala BNPB dilaksanakan oleh Panitia antar Kedeputian.
(2) Ketentuan teknis pembahasan sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.', 'Pasal 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8833, 'perka-6-2014', 14, 'pasal', 'Pasal 11', 'BAB III PEMBENTUKAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keempat Pengesahan', 6, '(1) Dalam rangka penyempurnaan rancangan Peraturan Kepala BNPB, Ketua Panitia antar Kedeputian dapat:
a. menyebarluaskan rancangan Peraturan Kepala BNPB kepada masyarakat untuk mendapatkan masukan; dan
b. meminta tanggapan dan/atau saran atas rancangan Peraturan Kepala BNPB dari Menteri dan/atau Kepala lembaga pemerintah non-kementerian terkait, perguruan tinggi, lembaga sosial masyarakat, dan/atau lembaga kemasyarakatan lainnya sesuai dengan kebutuhan.
(2) Masukan dari masyarakat sebagaimana dimaksud pada ayat (1) huruf a dan tanggapan dan/atau saran sebagaimana dimaksud pada ayat
(1) huruf b merupakan bahan penyempurnaan rancangan Peraturan Kepala BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8833, '(1) Dalam rangka penyempurnaan rancangan Peraturan Kepala BNPB, Ketua Panitia antar Kedeputian dapat:
a. menyebarluaskan rancangan Peraturan Kepala BNPB kepada masyarakat untuk mendapatkan masukan; dan
b. meminta tanggapan dan/atau saran atas rancangan Peraturan Kepala BNPB dari Menteri dan/atau Kepala lembaga pemerintah non-kementerian terkait, perguruan tinggi, lembaga sosial masyarakat, dan/atau lembaga kemasyarakatan lainnya sesuai dengan kebutuhan.
(2) Masukan dari masyarakat sebagaimana dimaksud pada ayat (1) huruf a dan tanggapan dan/atau saran sebagaimana dimaksud pada ayat
(1) huruf b merupakan bahan penyempurnaan rancangan Peraturan Kepala BNPB.', 'Pasal 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8834, 'perka-6-2014', 15, 'pasal', 'Pasal 12', 'BAB III PEMBENTUKAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Kelima Pengundangan', 6, '(1) Jika perumusan akhir rancangan Peraturan Kepala BNPB tidak mengandung permasalahan baik dari segi substansi maupun teknik 7 2014, No.557 penyusunan peraturan perundang-undangan, Ketua Panitia Antar Kedeputian menyampaikan rancangan Peraturan Kepala BNPB kepada Kepala BNPB guna mendapatkan pengesahan.
(2) Rancangan Peraturan Kepala BNPB disahkan oleh Kepala BNPB dengan membubuhkan tanda tangan.
(3) Ketentuan teknis pengesahan sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8834, '(1) Jika perumusan akhir rancangan Peraturan Kepala BNPB tidak mengandung permasalahan baik dari segi substansi maupun teknik 7 2014, No.557 penyusunan peraturan perundang-undangan, Ketua Panitia Antar Kedeputian menyampaikan rancangan Peraturan Kepala BNPB kepada Kepala BNPB guna mendapatkan pengesahan.
(2) Rancangan Peraturan Kepala BNPB disahkan oleh Kepala BNPB dengan membubuhkan tanda tangan.
(3) Ketentuan teknis pengesahan sebagaimana dimaksud pada ayat (1) diatur dalam Petunjuk Pelaksanaan.', 'Pasal 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8835, 'perka-6-2014', 16, 'pasal', 'Pasal 13', 'BAB III PEMBENTUKAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Keenam Penyebarluasan', 7, '(1) Peraturan Kepala BNPB yang telah ditetapkan wajib diundangkan dalam Berita Negara Republik Indonesia.
(2) Pengundangan sebagaimana dimaksud pada ayat (1) dilaksanakan oleh lembaga yang berwenang sesuai dengan peraturan perundang-undangan.
(3) Pengaturan teknis pengundangan sebagaimana dimaksud pada ayat
(1) diatur dalam Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8835, '(1) Peraturan Kepala BNPB yang telah ditetapkan wajib diundangkan dalam Berita Negara Republik Indonesia.
(2) Pengundangan sebagaimana dimaksud pada ayat (1) dilaksanakan oleh lembaga yang berwenang sesuai dengan peraturan perundang-undangan.
(3) Pengaturan teknis pengundangan sebagaimana dimaksud pada ayat
(1) diatur dalam Petunjuk Pelaksanaan.', 'Pasal 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8836, 'perka-6-2014', 17, 'pasal', 'Pasal 14', 'BAB III PEMBENTUKAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA; Bagian Ketujuh Pembiayaan', 7, '(1) Penyebarluasan Peraturan Kepala BNPB dilakukan oleh Biro Hukum dan Kerjasama.
(2) Penyebarluasan sebagaimana dimaksud pada ayat (1) dilakukan untuk memberikan informasi melalui media cetak, elektronik dan media terkait lainnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8836, '(1) Penyebarluasan Peraturan Kepala BNPB dilakukan oleh Biro Hukum dan Kerjasama.
(2) Penyebarluasan sebagaimana dimaksud pada ayat (1) dilakukan untuk memberikan informasi melalui media cetak, elektronik dan media terkait lainnya.', 'Pasal 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8837, 'perka-6-2014', 18, 'pasal', 'Pasal 15', 'BAB IV PEMBENTUKAN PERATURAN KEBIJAKAN', 7, 'Pembiayaan kegiatan pembentukan dan penyebarluasan peraturan perundang-undangan menggunakan anggaran Biro Hukum dan Kerjasama atau sumber pendanaan lain yang tidak mengikat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8837, 'Pembiayaan kegiatan pembentukan dan penyebarluasan peraturan perundang-undangan menggunakan anggaran Biro Hukum dan Kerjasama atau sumber pendanaan lain yang tidak mengikat.', 'Pasal 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8838, 'perka-6-2014', 19, 'pasal', 'Pasal 16', 'BAB IV PEMBENTUKAN PERATURAN KEBIJAKAN', 7, 'Dalam rangka membentuk kebijakan yang bersifat menetapkan dan tidak bersifat mengatur, dapat disusun:
557, No.2014 8
a. Keputusan Kepala BNPB;
b. Keputusan Sekretaris Utama;
c. Keputusan Deputi; atau
d. Keputusan Inspektur Utama.');
