INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8839, 'perka-6-2014', 20, 'pasal', 'Pasal 17', 'BAB V KETENTUAN PERALIHAN', 8, 'Pembentukan kebijakan sebagaimana dimaksud dalam Pasal 16 diatur lebih lanjut dalam Petunjuk Pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8839, 'Pembentukan kebijakan sebagaimana dimaksud dalam Pasal 16 diatur lebih lanjut dalam Petunjuk Pelaksanaan.', 'Pasal 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8840, 'perka-6-2014', 21, 'pasal', 'Pasal 18', 'BAB VI KETENTUAN PENUTUP', 8, 'Pada saat Peraturan Kepala BNPB ini mulai berlaku, rancangan peraturan perundang-undangan yang sedang dalam proses penyusunan tetap dilanjutkan dan disesuaikan dengan Peraturan Kepala BNPB ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8840, 'Pada saat Peraturan Kepala BNPB ini mulai berlaku, rancangan peraturan perundang-undangan yang sedang dalam proses penyusunan tetap dilanjutkan dan disesuaikan dengan Peraturan Kepala BNPB ini.', 'Pasal 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8841, 'perka-6-2014', 22, 'pasal', 'Pasal 19', 'BAB VI KETENTUAN PENUTUP', 8, 'Peraturan Kepala BNPB ini mulai berlaku pada tanggal diundangkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala BNPB ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8841, 'Peraturan Kepala BNPB ini mulai berlaku pada tanggal diundangkan.
