INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8842, 'perka-6-2014', 23, 'lain', 'Penutup', NULL, 8, 'Ditetapkan di Jakarta pada tanggal 1 April 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 24 April 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8842, 'Ditetapkan di Jakarta pada tanggal 1 April 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 24 April 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2014 tentang Pembentukan Produk Hukum di Lingkungan Badan Nasional Penanggulangan Bencana');
