INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8844, 'perka-6-2015', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka pelaksanaan penyimpanan peralatan dasar penanggulangan bencana yang dihibahkan Badan Nasional Penanggulangan Bencana kepada Badan Penanggulangan Bencana Daerah Provinsi/Kabupaten/Kota diperlukan Tata Cara Penyimpanan Peralatan Dasar Penanggulangan Bencana;
