INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8844, 'a. bahwa dalam rangka pelaksanaan penyimpanan peralatan dasar penanggulangan bencana yang dihibahkan Badan Nasional Penanggulangan Bencana kepada Badan Penanggulangan Bencana Daerah Provinsi/Kabupaten/Kota diperlukan Tata Cara Penyimpanan Peralatan Dasar Penanggulangan Bencana;
