INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8852, 'perka-6-2015', 9, 'pasal', 'Pasal 6', 'BAB III PENGELOLAAN TEMPAT PENYIMPANAN; Bagian Kesatu Umum', 6, 'Pengelolaan penyimpanan peralatan dasar penanggulangan bencana meliputi:
