INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8865, 'perka-6-2015', 22, 'pasal', 'Pasal 19', 'BAB IV PELAKSANAAN; Bagian Kelima Kelompok Peralatan Kedaruratan', 13, 'Mekanisme penyimpanan lampu solar sel sebagai berikut:
