INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8866, 'perka-6-2015', 23, 'pasal', 'Pasal 20', 'BAB IV PELAKSANAAN; Bagian Kelima Kelompok Peralatan Kedaruratan', 13, 'Mekanisme penyimpanan lampu senter high intensity discharge sebagai berikut:
