INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8867, 'perka-6-2015', 24, 'pasal', 'Pasal 21', 'BAB IV PELAKSANAAN; Bagian Keenam Kelompok Peralatan Mesin', 13, 'Mekanisme penyimpanan chainsaw sebagai berikut:
a. bersihkan peralatan dengan menggunakan lap dan kuas;
b. berikan pelumas pada pisau rantai;
c. kosongkan tangki bahan bakar yang ada di karburator dan pastikan kran saluran bensin dalam kondisi tertutup; dan
d. simpan di rak penyimpanan dan hindarkan dari hawa panas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8867, 'Mekanisme penyimpanan chainsaw sebagai berikut:
