INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8868, 'perka-6-2015', 25, 'pasal', 'Pasal 22', 'BAB IV PELAKSANAAN; Bagian Keenam Kelompok Peralatan Mesin', 13, 'Mekanisme penyimpanan mesin perahu sebagai berikut:
a. bersihkan mesin dengan air tawar dan keringkan;
b. kosongkan tangki bahan bakar dan selang bensin dalam keadaan menempel pada tangki;
2015, No.1660 -14-
c. posisi penyimpanan dalam keadaan tergantung vertikal di rak, posisi baling-baling berada di bawah;
d. tutup kap mesin dengan rapat;
e. kunci mesin dalam kondisi terpasang di mesin; dan
f. simpan dalam ruang tertutup.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8868, 'Mekanisme penyimpanan mesin perahu sebagai berikut:
