INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8869, 'perka-6-2015', 26, 'pasal', 'Pasal 23', 'BAB IV PELAKSANAAN; Bagian Keenam Kelompok Peralatan Mesin', 14, 'Mekanisme penyimpanan kelompok genset sebagai berikut:
a. buang sisa bensin pada karburator sehingga karbirator dalam kondisi kosong;
b. bersihkan genset dengan menggunakan lap;
c. gulung kabel dengan rapih masukkan ke dalam kotak penyimpan; dan
d. simpan genset di atas pallet.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8869, 'Mekanisme penyimpanan kelompok genset sebagai berikut:
a. buang sisa bensin pada karburator sehingga karbirator dalam kondisi kosong;
b. bersihkan genset dengan menggunakan lap;
c. gulung kabel dengan rapih masukkan ke dalam kotak penyimpan; dan
d. simpan genset di atas pallet.', 'Pasal 23', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2015 tentang Tata Cara Penyimpanan Peralatan Dasar Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8870, 'perka-6-2015', 27, 'pasal', 'Pasal 24', 'BAB IV PELAKSANAAN; Bagian Keenam Kelompok Peralatan Mesin', 14, 'Mekanisme penyimpanan pompa air apung sebagai berikut:
a. lepaskan mesin dari alat apung dan simpan mur dan bautnya;
b. cuci dan sikat alat apung dengan sabun serta keringkan;
c. bersihkan dan keringkan mesin pompa;
d. tutup kran bensin dan buang sisa bensin pada karburator; dan
e. simpan di atas pallet di tempat yang kering dan terlindung dari sinar matahari dan terhindar dari sumber panas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8870, 'Mekanisme penyimpanan pompa air apung sebagai berikut:
a. lepaskan mesin dari alat apung dan simpan mur dan bautnya;
b. cuci dan sikat alat apung dengan sabun serta keringkan;
c. bersihkan dan keringkan mesin pompa;
d. tutup kran bensin dan buang sisa bensin pada karburator; dan
e. simpan di atas pallet di tempat yang kering dan terlindung dari sinar matahari dan terhindar dari sumber panas.', 'Pasal 24', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 6 Tahun 2015 tentang Tata Cara Penyimpanan Peralatan Dasar Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8871, 'perka-6-2015', 28, 'pasal', 'Pasal 25', 'BAB V KETENTUAN PENUTUP', 14, 'Mekanisme penyimpanan water treatment portable sebagai berikut:
a. matikan semua sistem kelistrikan dengan mengatur tombol power dalam posisi off;
b. lepaskan sambungan antara rangkaian reverse osmosis, filtrasi dan genset sehingga dalam keadaan terpisah;
c. bersihkan dan keringkan semua sisa air dan kotoran yang menempel di 3 (tiga) rangkaian;
2015, No.1660
d. bersihkan dan cuci semua media filtrasi dengan air bersih dengan cara backwash dan flashrinse;
e. lakukan pencucian ultra filtrasi (tabung stenlis panjang);
f. cuci dan lepaskan 3 (tiga) buah sedimen (tabung bening) dan keringkan kemudian pasang kembali;
g. buang sisa air yang menempel di rangkaian micro computer dan keringkan;
h. simpan water treatment portable dan hindari dari sinar matahari langsung;
i. buang sisa air minum yang berada pada tabung penyimpanan air hingga kosong; dan
j. semprotkan minyak pelumas pada mesin pompa untuk menghindari karatan pada bearing dan as dinamo.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8871, 'Mekanisme penyimpanan water treatment portable sebagai berikut:
