INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8882, 'perka-7-2008', 8, 'lain', 'Penutup', NULL, 2, 'Ditetapkan di Jakarta pada tanggal 17..Desember 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8882, 'Ditetapkan di Jakarta pada tanggal 17..Desember 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si.', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2008 tentang Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8883, 'perka-7-2008', 9, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 7. TAHUN 2008 TANGGAL : 17 DESEMBER 2008 BAB I PENDAHULUAN A. Latar Belakang Wilayah Negara Kesatuan Republik Indonesia memiliki kondisi geologis, geografis, hidrologis, demografis, sosiografis yang menjadikannya potensial, rawan, dan sering mengalami bencana, baik bencana alam, bencana non alam, maupun bencana sosial.
Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana pasal 26 ayat (2) menyatakan bahwa setiap orang yang menjadi korban bencana berhak mendapatkan bantuan pemenuhan kebutuhan dasar.
Menurut Peraturan Pemerintah Republik Indonesa Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana pasal 28 ayat (1) bahwa bantuan pemenuhan kebutuhan dasar sebagaimana dimaksud dalam pasal 24 ayat (2) huruf d, diberikan kepada korban bencana dalam bentuk penampungan sementara, bantuan pangan, sandang, air bersih dan sanitasi, dan pelayanan kesehatan.
Bantuan darurat bencana untuk pemenuhan kebutuhan dasar korban bencana diberikan dengan memperhatikan standar minimal kebutuhan dasar dan memperhatikan prioritas kepada kelompok rentan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8883, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 7. TAHUN 2008 TANGGAL : 17 DESEMBER 2008 BAB I PENDAHULUAN A. Latar Belakang Wilayah Negara Kesatuan Republik Indonesia memiliki kondisi geologis, geografis, hidrologis, demografis, sosiografis yang menjadikannya potensial, rawan, dan sering mengalami bencana, baik bencana alam, bencana non alam, maupun bencana sosial.
Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana pasal 26 ayat (2) menyatakan bahwa setiap orang yang menjadi korban bencana berhak mendapatkan bantuan pemenuhan kebutuhan dasar.
Menurut Peraturan Pemerintah Republik Indonesa Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana pasal 28 ayat (1) bahwa bantuan pemenuhan kebutuhan dasar sebagaimana dimaksud dalam pasal 24 ayat (2) huruf d, diberikan kepada korban bencana dalam bentuk penampungan sementara, bantuan pangan, sandang, air bersih dan sanitasi, dan pelayanan kesehatan.
Bantuan darurat bencana untuk pemenuhan kebutuhan dasar korban bencana diberikan dengan memperhatikan standar minimal kebutuhan dasar dan memperhatikan prioritas kepada kelompok rentan.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2008 tentang Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8884, 'perka-7-2008', 10, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'Agar pemberian bantuan pemenuhan kebutuhan dasar bagi korban bencana tersebut berdaya guna dan berhasil guna, perlu disusun sebuah pedoman yang berisi tentang tata cara pemberian bantuan pemenuhan kebutuhan dasar bagi korban bencana yang memenuhi standar minimal, sehingga dapat dijadikan acuan oleh pemerintah, pemerintah daerah, masyarakat nasional dan internasional, lembaga non pemerintah, baik daerah, nasional, maupun internasional.
B. Maksud dan Tujuan Pedoman Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar dimaksudkan untuk menjadi panduan dalam melaksanakan pemberian bantuan guna memenuhi kebutuhan dasar korban bencana secara terkoordinasi, efektif, dan akuntabel.
Tujuan Pedoman Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar ini adalah:
1. Meningkatnya mobilisasi sumber daya bantuan dari pemberi bantuan kepada penerima bantuan.
2. Tersalurkannya pemberian bantuan pemenuhan kebutuhan dasar kepada korban bencana secara cepat, tepat, dan dapat dipertanggungjawabkan.
3. Terselenggaranya proses pemberian bantuan sesuai dengan prosedur dan mekanisme yang ditentukan.
C. Ruang Lingkup Pedoman ini meliputi : pendahuluan, pengertian dan prinsip, kebijakan dan strategi, jenis bantuan, penyelenggaraan pemberian bantuan, serta penutup.
Pedoman ini berlaku bagi para pelaksana pemberi bantuan korban bencana pada lingkup nasional maupun propinsi dan kabupaten/kota yang berasal dari lembaga pemerintah/non pemerintah, baik daerah, nasional, maupun internasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8884, 'Agar pemberian bantuan pemenuhan kebutuhan dasar bagi korban bencana tersebut berdaya guna dan berhasil guna, perlu disusun sebuah pedoman yang berisi tentang tata cara pemberian bantuan pemenuhan kebutuhan dasar bagi korban bencana yang memenuhi standar minimal, sehingga dapat dijadikan acuan oleh pemerintah, pemerintah daerah, masyarakat nasional dan internasional, lembaga non pemerintah, baik daerah, nasional, maupun internasional.
B. Maksud dan Tujuan Pedoman Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar dimaksudkan untuk menjadi panduan dalam melaksanakan pemberian bantuan guna memenuhi kebutuhan dasar korban bencana secara terkoordinasi, efektif, dan akuntabel.
Tujuan Pedoman Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar ini adalah:
1. Meningkatnya mobilisasi sumber daya bantuan dari pemberi bantuan kepada penerima bantuan.
2. Tersalurkannya pemberian bantuan pemenuhan kebutuhan dasar kepada korban bencana secara cepat, tepat, dan dapat dipertanggungjawabkan.
3. Terselenggaranya proses pemberian bantuan sesuai dengan prosedur dan mekanisme yang ditentukan.
C. Ruang Lingkup Pedoman ini meliputi : pendahuluan, pengertian dan prinsip, kebijakan dan strategi, jenis bantuan, penyelenggaraan pemberian bantuan, serta penutup.
Pedoman ini berlaku bagi para pelaksana pemberi bantuan korban bencana pada lingkup nasional maupun propinsi dan kabupaten/kota yang berasal dari lembaga pemerintah/non pemerintah, baik daerah, nasional, maupun internasional.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2008 tentang Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8885, 'perka-7-2008', 11, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'D. Landasan Hukum
1. Undang-Undang Dasar Republik Indonesia Tahun 1945; Pasal 5 ayat (2).
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
3. Peraturan Pemerintah Republik Indonesia Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
4. Peraturan Pemerintah Republik Indonesia Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
5. Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
6. Keputusan Menteri Kesehatan Nomor 979/Menkes/SK/IX/2001 tentang Prosedur Tetap Pelayanan Kesehatan Penanganan Bencana dan Penanganan Pengungsi.
7. Keputusan Menteri Permukiman dan Prasarana Wilayah Nomor 534/kpts/m/2001 tentang Pedoman Penentuan Standar Pelayanan Minimal Bidang Penataan Ruang, Perumahan dan Permukiman dan Pekerjaan Umum.
8. Keputusan Dirjen Bantuan dan Jaminan Sosial Departemen Sosial RI Nomor 57/BJS/2003 tentang Pedoman Umum Bantuan Sosial Korban Bencana Alam.
BAB II PENGERTIAN DAN PRINSIP A. Pengertian
1. Tata cara pemberian bantuan merupakan mekanisme atau prosedur yang menghubungkan antara pemberi bantuan dan penerima bantuan pada suatu situasi kebencanaan.
2. Bantuan dalam hal ini adalah bantuan kemanusiaan yang terdiri dari penampungan sementara, bantuan pangan, sandang, air bersih dan sanitasi, serta pelayanan kesehatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8885, 'D. Landasan Hukum
1. Undang-Undang Dasar Republik Indonesia Tahun 1945; Pasal 5 ayat (2).
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
3. Peraturan Pemerintah Republik Indonesia Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
4. Peraturan Pemerintah Republik Indonesia Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
5. Peraturan Presiden Republik Indonesia Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
6. Keputusan Menteri Kesehatan Nomor 979/Menkes/SK/IX/2001 tentang Prosedur Tetap Pelayanan Kesehatan Penanganan Bencana dan Penanganan Pengungsi.
7. Keputusan Menteri Permukiman dan Prasarana Wilayah Nomor 534/kpts/m/2001 tentang Pedoman Penentuan Standar Pelayanan Minimal Bidang Penataan Ruang, Perumahan dan Permukiman dan Pekerjaan Umum.
8. Keputusan Dirjen Bantuan dan Jaminan Sosial Departemen Sosial RI Nomor 57/BJS/2003 tentang Pedoman Umum Bantuan Sosial Korban Bencana Alam.
BAB II PENGERTIAN DAN PRINSIP A. Pengertian
1. Tata cara pemberian bantuan merupakan mekanisme atau prosedur yang menghubungkan antara pemberi bantuan dan penerima bantuan pada suatu situasi kebencanaan.
2. Bantuan dalam hal ini adalah bantuan kemanusiaan yang terdiri dari penampungan sementara, bantuan pangan, sandang, air bersih dan sanitasi, serta pelayanan kesehatan.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2008 tentang Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8886, 'perka-7-2008', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, '3. Penampungan/hunian sementara adalah tempat tinggal sementara selama korban bencana mengungsi, baik berupa tempat penampungan massal maupun keluarga, atau individual.
4. Bantuan pangan dan non pangan adalah bantuan bahan makanan dan bantuan lainnya di luar bantuan pangan yang diberikan kepada korban bencana demi kelangsungan hidup sesuai dengan makanan pokok setempat.
5. Sandang adalah keperluan individu berupa pakaian dan perlengkapan pribadi.
6. Air Bersih adalah air yang kualitasnya memadai untuk diminum serta digunakan bagi kebersihan pribadi dan rumah tangga tanpa menyebabkan risiko yang berarti terhadap kesehatan.
7. Sanitasi adalah kebersihan dan kesehatan lingkungan yang berkaitan dengan saluran air (drainase), pengelolaan limbah cair dan padat, pengendalian vektor (sumber penyebar penyakit), dan pembuangan tinja.
8. Pelayanan Kesehatan adalah pelayanan pemeriksaan kesehatan dan pemberian obat-obatan bagi korban bencana, baik untuk pengobatan maupun untuk pencegahan penyakit.
9. Standar Minimal Kebutuhan Dasar adalah tingkat minimal yang harus dipenuhi dalam pemenuhan kebutuhan penampungan/ hunian sementara, bantuan pangan, sandang, air bersih, sanitasi, dan pelayanan kesehatan.
10. Kelompok Rentan adalah bayi, anak usia dibawah lima tahun, anak-anak, ibu hamil atau menyusui, penyandang cacat, orang sakit, dan orang lanjut usia.
B. Prinsip Prinsip-prinsip dalam pemberian bantuan pemenuhan kebutuhan dasar:
1. Cepat dan Tepat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8886, '3. Penampungan/hunian sementara adalah tempat tinggal sementara selama korban bencana mengungsi, baik berupa tempat penampungan massal maupun keluarga, atau individual.
4. Bantuan pangan dan non pangan adalah bantuan bahan makanan dan bantuan lainnya di luar bantuan pangan yang diberikan kepada korban bencana demi kelangsungan hidup sesuai dengan makanan pokok setempat.
5. Sandang adalah keperluan individu berupa pakaian dan perlengkapan pribadi.
6. Air Bersih adalah air yang kualitasnya memadai untuk diminum serta digunakan bagi kebersihan pribadi dan rumah tangga tanpa menyebabkan risiko yang berarti terhadap kesehatan.
7. Sanitasi adalah kebersihan dan kesehatan lingkungan yang berkaitan dengan saluran air (drainase), pengelolaan limbah cair dan padat, pengendalian vektor (sumber penyebar penyakit), dan pembuangan tinja.
8. Pelayanan Kesehatan adalah pelayanan pemeriksaan kesehatan dan pemberian obat-obatan bagi korban bencana, baik untuk pengobatan maupun untuk pencegahan penyakit.
9. Standar Minimal Kebutuhan Dasar adalah tingkat minimal yang harus dipenuhi dalam pemenuhan kebutuhan penampungan/ hunian sementara, bantuan pangan, sandang, air bersih, sanitasi, dan pelayanan kesehatan.
10. Kelompok Rentan adalah bayi, anak usia dibawah lima tahun, anak-anak, ibu hamil atau menyusui, penyandang cacat, orang sakit, dan orang lanjut usia.
B. Prinsip Prinsip-prinsip dalam pemberian bantuan pemenuhan kebutuhan dasar:
1. Cepat dan Tepat.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2008 tentang Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8887, 'perka-7-2008', 13, 'lampiran', 'Lampiran hal. 6', NULL, 6, 'Cepat dan tepat adalah bahwa dalam pemberian bantuan pemenuhan kebutuhan dasar dilaksanakan secara cepat dan tepat sesuai dengan tuntutan keadaan.
2. Prioritas.
Prioritas adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar harus diutamakan kepada kelompok rentan.
3. Koordinasi dan Keterpaduan.
Koordinasi adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar didasarkan pada koordinasi yang baik dan saling mendukung.
Keterpaduan adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar dilaksanakan oleh berbagai sektor secara terpadu yang didasarkan pada kerjasama yang baik dan saling mendukung.
4. Berdaya Guna dan Berhasil Guna.
Berdaya guna adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar dilakukan dengan tidak membuang waktu, tenaga, dan biaya yang berlebihan.
Berhasil guna adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar harus berhasil guna, khususnya dalam mengatasi kesulitan korban bencana dengan tidak membuang waktu, tenaga, dan biaya yang berlebihan.
5. Transparansi dan Akuntabilitas.
Transparansi adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar dilakukan secara terbuka dan dapat dipertanggungjawabkan.
Akuntabilitas adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar dilakukan secara terbuka dan dapat dipertanggungjawabkan secara etika dan hukum.
6. Kemitraan.
Kemitraan adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar harus melibatkan berbagai pihak secara seimbang.
7. Pemberdayaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8887, 'Cepat dan tepat adalah bahwa dalam pemberian bantuan pemenuhan kebutuhan dasar dilaksanakan secara cepat dan tepat sesuai dengan tuntutan keadaan.
2. Prioritas.
Prioritas adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar harus diutamakan kepada kelompok rentan.
3. Koordinasi dan Keterpaduan.
Koordinasi adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar didasarkan pada koordinasi yang baik dan saling mendukung.
Keterpaduan adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar dilaksanakan oleh berbagai sektor secara terpadu yang didasarkan pada kerjasama yang baik dan saling mendukung.
4. Berdaya Guna dan Berhasil Guna.
Berdaya guna adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar dilakukan dengan tidak membuang waktu, tenaga, dan biaya yang berlebihan.
Berhasil guna adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar harus berhasil guna, khususnya dalam mengatasi kesulitan korban bencana dengan tidak membuang waktu, tenaga, dan biaya yang berlebihan.
5. Transparansi dan Akuntabilitas.
Transparansi adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar dilakukan secara terbuka dan dapat dipertanggungjawabkan.
Akuntabilitas adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar dilakukan secara terbuka dan dapat dipertanggungjawabkan secara etika dan hukum.
6. Kemitraan.
Kemitraan adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar harus melibatkan berbagai pihak secara seimbang.
7. Pemberdayaan.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2008 tentang Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8888, 'perka-7-2008', 14, 'lampiran', 'Lampiran hal. 7', NULL, 7, 'Pemberdayaan adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar dilakukan dengan melibatkan korban bencana secara aktif.
8. Non Diskriminatif.
Non Diskriminatif adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar tidak memberikan perlakuan yang berbeda terhadap jenis kelamin, suku, agama, ras, dan aliran politik apapun.
9. Non Proletisi.
Non Proletisi adalah bahwa dalam pemberian bantuan pemenuhan kebutuhan dasar dilarang menyebarkan agama atau keyakinan.
BAB III KEBIJAKAN DAN STRATEGI A. Kebijakan
1. Penanggulangan bencana dilaksanakan secara terpadu dan terkoordinasi yang melibatkan seluruh potensi pemerintah, swasta dan masyarakat, baik pada tahap pra bencana, saat terjadi bencana maupun pasca bencana.
2. Memberikan penjaminan pemenuhan hak masyarakat korban bencana dan pengungsi yang terkena bencana terutama pelayanan kebutuhan dasar secara adil dan sesuai dengan standar minimal.
B. Strategi
1. Pemerintah memfasilitasi penyiapan dan penyediaan sumber daya sedekat mungkin dengan lokasi rawan bencana.
2. Mengupayakan terpenuhinya standar minimum dalam pemenuhan kebutuhan dasar.
BAB IV JENIS BANTUAN A. Bantuan Tempat Penampungan/Hunian Sementara Bantuan penampungan/hunian sementara diberikan dalam bentuk tenda-tenda, barak, atau gedung fasilitas umum/sosial, seperti tempat ibadah, gedung olah raga, balai desa, dan sebagainya, yang memungkinkan untuk digunakan sebagai tempat tinggal sementara.
Standar Minimal Bantuan :
a. Berukuran 3 (tiga) meter persegi per orang.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8888, 'Pemberdayaan adalah bahwa pemberian bantuan pemenuhan kebutuhan dasar dilakukan dengan melibatkan korban bencana secara aktif.
8. Non Diskriminatif.
