INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8892, 'perka-7-2008', 18, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'd. Setiap bayi dan anak-anak di bawah usia dua tahun memiliki 12 popok cuci sesuai kebiasaan di tempat yang bersangkutan.
e. Setiap orang memiliki sikat gigi dan pasta gigi sesuai kebutuhan.
E. Bantuan Air Bersih dan Sanitasi
1. Bantuan Air Bersih Diberikan dalam bentuk air yang kualitasnya memadai untuk kebersihan pribadi maupun rumah tangga tanpa menyebabkan risiko yang berarti terhadap kesehatan. Bantuan air bersih diberikan dalam bentuk sumber air beserta peralatannya.
Standar Minimal Bantuan :
a. Bantuan air bersih diberikan sejumlah 7 liter pada tiga hari pertama, selanjutnya 15 liter per orang per hari.
b. Jarak terjauh tempat penampungan sementara dengan jamban keluarga adalah 50 meter.
c. Jarak terjauh sumber air dari tempat penampungan sementara dengan titik air terdekat adalah 500 meter.
2. Bantuan Air Minum Diberikan dalam bentuk air yang dapat diminum langsung atau air yang memenuhi persyaratan kesehatan untuk dapat diminum.
Standar Minimal Bantuan :
a. Bantuan air minum diberikan sejumlah 2.5 liter per orang per hari.
b. Rasa air minum dapat diterima dan kualitasnya cukup memadai untuk diminum tanpa menyebabkan resiko kesehatan.
3. Bantuan Sanitasi Diberikan dalam bentuk pelayanan kebersihan dan kesehatan lingkungan yang berkaitan dengan saluran air (drainase), pengelolaan limbah cair dan limbah padat, pengendalian vektor, serta pembuangan tinja.
Standar Minimal Bantuan :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8892, 'd. Setiap bayi dan anak-anak di bawah usia dua tahun memiliki 12 popok cuci sesuai kebiasaan di tempat yang bersangkutan.
e. Setiap orang memiliki sikat gigi dan pasta gigi sesuai kebutuhan.
E. Bantuan Air Bersih dan Sanitasi
1. Bantuan Air Bersih Diberikan dalam bentuk air yang kualitasnya memadai untuk kebersihan pribadi maupun rumah tangga tanpa menyebabkan risiko yang berarti terhadap kesehatan. Bantuan air bersih diberikan dalam bentuk sumber air beserta peralatannya.
