INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8895, 'perka-7-2008', 21, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'b. Kesehatan Reproduksi
c. Aspek Kejiwaan dan Sosial Kesehatan
d. Penyakit Kronis Standar Minimal Bantuan :
a. Korban bencana memperoleh pelayanan tepat untuk mengatasi cedera.
b. Korban bencana memperoleh pelayanan untuk memenuhi kebutuhan kesehatan reproduksi.
c. Korban bencana memperoleh pelayanan kesehatan sosial dan mental sesuai kebutuhan.
BAB V PENYELENGGARAAN PEMBERIAN BANTUAN A. Pengorganisasian Pengorganisasian atau tata cara pemberian bantuan pemenuhan kebutuhan dasar dikoordinasikan oleh Badan Nasional Penanggulangan Bencana (BNPB) serta Badan Penanggulangan Bencana Daerah (BPBD) sesuai dengan tingkatan bencana, melalui Sistem Komando Tanggap Darurat bencana.
Negara donor atau NGO yang akan memberikan bantuan kepada Indonesia harus menghubungi kantor kedutaan atau kantor perwakilan. Selanjutnya, kedutaan atau kantor perwakilan akan berkoordinasi dengan Departemen Luar Negeri perihal jenis bantuan.
Informasi tentang bantuan tersebut akan diteruskan kepada BNPB.
Selanjutnya berdasarkan hasil penilaian cepat atau rapid assessment, BNPB menentukan jenis dan jumlah kebutuhan dasar yang diperlukan, untuk disampaikan kepada pihak yang akan memberikan bantuan. Pihak imigrasi, bea cukai, Mabes POLRI dan TNI, serta Departemen Perhubungan harus mempermudah prosedur tersebut.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8895, 'b. Kesehatan Reproduksi
c. Aspek Kejiwaan dan Sosial Kesehatan
d. Penyakit Kronis Standar Minimal Bantuan :
a. Korban bencana memperoleh pelayanan tepat untuk mengatasi cedera.
b. Korban bencana memperoleh pelayanan untuk memenuhi kebutuhan kesehatan reproduksi.
c. Korban bencana memperoleh pelayanan kesehatan sosial dan mental sesuai kebutuhan.
BAB V PENYELENGGARAAN PEMBERIAN BANTUAN A. Pengorganisasian Pengorganisasian atau tata cara pemberian bantuan pemenuhan kebutuhan dasar dikoordinasikan oleh Badan Nasional Penanggulangan Bencana (BNPB) serta Badan Penanggulangan Bencana Daerah (BPBD) sesuai dengan tingkatan bencana, melalui Sistem Komando Tanggap Darurat bencana.
Negara donor atau NGO yang akan memberikan bantuan kepada Indonesia harus menghubungi kantor kedutaan atau kantor perwakilan. Selanjutnya, kedutaan atau kantor perwakilan akan berkoordinasi dengan Departemen Luar Negeri perihal jenis bantuan.
Informasi tentang bantuan tersebut akan diteruskan kepada BNPB.
Selanjutnya berdasarkan hasil penilaian cepat atau rapid assessment, BNPB menentukan jenis dan jumlah kebutuhan dasar yang diperlukan, untuk disampaikan kepada pihak yang akan memberikan bantuan. Pihak imigrasi, bea cukai, Mabes POLRI dan TNI, serta Departemen Perhubungan harus mempermudah prosedur tersebut.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2008 tentang Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8896, 'perka-7-2008', 22, 'lampiran', 'Lampiran hal. 15', NULL, 15, '1. Pemberi Bantuan dari Luar Negeri Bantuan dari masyarakat/NGO luar negeri diberikan melalui BNPB atau BPBD kepada korban bencana, atau langsung kepada korban bencana setelah berkoordinasi dengan BNPB atau BPBD.
2. Pemberi dan Penyalur Bantuan
a. Tingkat pusat : BNPB/Departemen terkait.
Tugas : Menerima dan menyalurkan bantuan.
b. Tingkat Provinsi : BPBD Provinsi/Dinas tingkat Provinsi.
Tugas : Menerima dan menyalurkan bantuan.
c. Tingkat Kabupaten/Kota : BPBD Kabupaten/Kota dan Dinas tingkat Kabupaten/Kota.
Tugas : Menerima dan menyalurkan bantuan.
3. Penerima bantuan : Korban bencana.
B. Pelaksana Pemberian Bantuan
1. Pemberian bantuan pemenuhan kebutuhan dasar dilaksanakan oleh Tim Pelaksana Pemberi Bantuan.
2. Tim Pelaksana Pemberi Bantuan sebagaimana dimaksud pada ayat (1) dipimpin oleh seorang Koordinator Lapangan yang dibantu oleh :
a. Petugas Administrasi
b. Petugas Medis
c. Petugas Keamanan
d. Petugas Dapur Umum Lapangan
e. Pekerja Sosial
f. Psikolog
g. Petugas teknis sesuai kebutuhan, seperti teknisi pendirian tenda, teknisi air bersih, teknisi sanitasi, teknisi penerangan, teknisi komunikasi.
h. Partisipan lain yang memiliki kepedulian dalam penanggulangan bencana.
3. Tim pelaksana pemberi bantuan dapat berasal dari :
a. Pemerintah daerah, desa/kelurahan
b. Instansi pemerintah
c. TNI / POLRI
d. LSM
e. PMI
f. Perguruan Tinggi
g. Anggota masyarakat lainnya
4. Tim Pelaksana Pemberi Bantuan sebagaimana dimaksud pada ayat');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8896, '1. Pemberi Bantuan dari Luar Negeri Bantuan dari masyarakat/NGO luar negeri diberikan melalui BNPB atau BPBD kepada korban bencana, atau langsung kepada korban bencana setelah berkoordinasi dengan BNPB atau BPBD.
2. Pemberi dan Penyalur Bantuan
a. Tingkat pusat : BNPB/Departemen terkait.
Tugas : Menerima dan menyalurkan bantuan.
b. Tingkat Provinsi : BPBD Provinsi/Dinas tingkat Provinsi.
Tugas : Menerima dan menyalurkan bantuan.
c. Tingkat Kabupaten/Kota : BPBD Kabupaten/Kota dan Dinas tingkat Kabupaten/Kota.
Tugas : Menerima dan menyalurkan bantuan.
3. Penerima bantuan : Korban bencana.
B. Pelaksana Pemberian Bantuan
