INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8937, 'perka-7-2013', 3, 'menetapkan', 'Menetapkan', NULL, 3, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PETUNJUK PELAKSANAAN PENGGUNAAN DAN PEMELIHARAAN PERALATAN PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8937, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PETUNJUK PELAKSANAAN PENGGUNAAN DAN PEMELIHARAAN PERALATAN PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8938, 'perka-7-2013', 4, 'pasal', 'Pasal 1', NULL, 3, 'Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana merupakan panduan/acuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/lembaga dan pemangku kepentingan penanggulangan bencana lainnya agar penggunaan peralatan penanggulangan bencana dapat bermanfaat dan dilakukan secara maksimal dalam penanganan korban bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8938, 'Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana merupakan panduan/acuan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/lembaga dan pemangku kepentingan penanggulangan bencana lainnya agar penggunaan peralatan penanggulangan bencana dapat bermanfaat dan dilakukan secara maksimal dalam penanganan korban bencana.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8939, 'perka-7-2013', 5, 'pasal', 'Pasal 2', NULL, 3, 'Petunjuk pelaksanaan penggunaan dan pemeliharaan peralatan penanggulangan bencana sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian tidak terpisahkan dari peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8939, 'Petunjuk pelaksanaan penggunaan dan pemeliharaan peralatan penanggulangan bencana sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian tidak terpisahkan dari peraturan ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8940, 'perka-7-2013', 6, 'pasal', 'Pasal 3', NULL, 3, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal ditetapkan.
2015, No.822 4 Agar setiap orang mengetahuinya, memerintahkan pengundangan peraturan Kepala Badan Nasional Penanggulangan Bencana dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8940, 'Peraturan Kepala Badan Nasional Penanggulangan Bencana ini mulai berlaku pada tanggal ditetapkan.
2015, No.822 4 Agar setiap orang mengetahuinya, memerintahkan pengundangan peraturan Kepala Badan Nasional Penanggulangan Bencana dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8941, 'perka-7-2013', 7, 'lain', 'Penutup', NULL, 4, 'Ditetapkan di Jakarta pada tanggal 18 September 2013 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 3 Juni 2015 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY 5 2015, No.822');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8941, 'Ditetapkan di Jakarta pada tanggal 18 September 2013 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 3 Juni 2015 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, YASONNA H. LAOLY 5 2015, No.822', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8942, 'perka-7-2013', 8, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'LAMPIRAN I PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 7 TAHUN 2013 TENTANG PETUNJUK PELAKSANAAN PENGGUNAAN DAN PEMELIHARAAN PERALATAN PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. LATAR BELAKANG Kondisi Indonesia secara geografis dan struktur geologi terletak pada kawasan rawan bencana, sehingga sering terjadi bencana gempa bumi, banjir, tanah longsor, badai, tsunami, kebakaran hutan dan lahan, dan lain lain. Oleh karena itu untuk mengantisipasi bencana tersebut diperlukan dukungan peralatan yang memadai sesuai jenis bencananya.
Peralatan sangat penting dalam penanggulangan bencana, terutama pada saat situasi kedaruratan. Peralatan penanggulangan bencana harus dapat diterima dan digunakan baik oleh petugas yang terdapat di institusi /lembaga terkait maupun oleh korban. Pada saat situasi kedaruratan banyak peralatan yang diperlukan, seperti peralatan angkutan (transportasi) untuk evakuasi korban baik di daratan maupun di perairan (truk, perahu karet, helikopter, dll).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8942, 'LAMPIRAN I PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 7 TAHUN 2013 TENTANG PETUNJUK PELAKSANAAN PENGGUNAAN DAN PEMELIHARAAN PERALATAN PENANGGULANGAN BENCANA BAB I PENDAHULUAN A. LATAR BELAKANG Kondisi Indonesia secara geografis dan struktur geologi terletak pada kawasan rawan bencana, sehingga sering terjadi bencana gempa bumi, banjir, tanah longsor, badai, tsunami, kebakaran hutan dan lahan, dan lain lain. Oleh karena itu untuk mengantisipasi bencana tersebut diperlukan dukungan peralatan yang memadai sesuai jenis bencananya.
Peralatan sangat penting dalam penanggulangan bencana, terutama pada saat situasi kedaruratan. Peralatan penanggulangan bencana harus dapat diterima dan digunakan baik oleh petugas yang terdapat di institusi /lembaga terkait maupun oleh korban. Pada saat situasi kedaruratan banyak peralatan yang diperlukan, seperti peralatan angkutan (transportasi) untuk evakuasi korban baik di daratan maupun di perairan (truk, perahu karet, helikopter, dll).', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8943, 'perka-7-2013', 9, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'Demikian pula peralatan lainnya, misalnya peralatan telekomunikasi, generator listrik, peralatan penyelamatan (rescue), peralatan deteksi dini, bulldozer, forklift, dll. Bantuan peralatan tersebut harus dapat diperoleh dengan cepat, tepat waktu, tepat lokasi, tepat sasaran, tepat jumlah, dan dapat berfungsi. Permasalahan sering muncul ketika bantuan peralatan sulit diperoleh, tidak dapat digunakan, tidak berfungsi, tidak berkualitas (cepat rusak), sehingga mengakibatkan korban menjadi semakin lebih banyak.
Menyadari kondisi tersebut, maka sesuai Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, khususnya Pasal 6 dan pasal 8 telah mengamanatkan bahwa tanggung jawab Pemerintah dan Pemerintah Daerah dalam penyelenggaraan penanggulangan bencana antara lain adalah perlindungan masyarakat dari dampak bencana. Dalam hal ini Pemerintah dan Pemerintah Daerah perlu melakukan kesiapsiagaan yang memadai dalam menghadapi bencana, salah satunya adalah menyiapkan bantuan peralatan yang siap pakai untuk dapat membantu meringankan penderitaan korban bencana.
Badan Nasional Penaggulangan Bencana (BNPB) telah berupaya memberikan dukungan peralatan untuk kesiapsiagaan dan penguatan kelembagaan Badan Penanggulangan Bencana Daerah (BPBD), khususnya dalam rangka pemenuhan kebutuhan standar minimal peralatan. Namun demikian bantuan peralatan dari BNPB hanya bersifat stimulan, sehingga daerah diharapkan akan lebih berperan dalam pemenuhan kebutuhan peralatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8943, 'Demikian pula peralatan lainnya, misalnya peralatan telekomunikasi, generator listrik, peralatan penyelamatan (rescue), peralatan deteksi dini, bulldozer, forklift, dll. Bantuan peralatan tersebut harus dapat diperoleh dengan cepat, tepat waktu, tepat lokasi, tepat sasaran, tepat jumlah, dan dapat berfungsi. Permasalahan sering muncul ketika bantuan peralatan sulit diperoleh, tidak dapat digunakan, tidak berfungsi, tidak berkualitas (cepat rusak), sehingga mengakibatkan korban menjadi semakin lebih banyak.
Menyadari kondisi tersebut, maka sesuai Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana, khususnya Pasal 6 dan pasal 8 telah mengamanatkan bahwa tanggung jawab Pemerintah dan Pemerintah Daerah dalam penyelenggaraan penanggulangan bencana antara lain adalah perlindungan masyarakat dari dampak bencana. Dalam hal ini Pemerintah dan Pemerintah Daerah perlu melakukan kesiapsiagaan yang memadai dalam menghadapi bencana, salah satunya adalah menyiapkan bantuan peralatan yang siap pakai untuk dapat membantu meringankan penderitaan korban bencana.
Badan Nasional Penaggulangan Bencana (BNPB) telah berupaya memberikan dukungan peralatan untuk kesiapsiagaan dan penguatan kelembagaan Badan Penanggulangan Bencana Daerah (BPBD), khususnya dalam rangka pemenuhan kebutuhan standar minimal peralatan. Namun demikian bantuan peralatan dari BNPB hanya bersifat stimulan, sehingga daerah diharapkan akan lebih berperan dalam pemenuhan kebutuhan peralatan.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8944, 'perka-7-2013', 10, 'lampiran', 'Lampiran hal. 5', NULL, 5, 'Bantuan peralatan penanggulangan bencana yang telah diberikan tersebut, harus dapat digunakan dan dimanfaatkan secara optimal dengan sumber daya 2015, No.822 6 yang terlatih dalam mengoperasikan peralatan penanggulangan bencana.
Salah satu unsur penting yang harus diperhatikan adalah cara penggunaan peralatan secara efektif dan efisien untuk mencapai hasil yang diinginkan.
Selain itu perlu diperhatikan juga bagaimana cara pemelihaaraan peralatan tersebut agar tidak mudah rusak dan dapat dipergunakan kembali, serta siap pakai bila sewaktu-waktu terjadi bencana.
Untuk dapat mengunakan dan memanfaatkan serta pemelihaaraan peralatan penanggulangan bencana secara maksimal, maka perlu disusun petunjuk pelaksanaan penggunaan peralatan penanggulangan bencana yang sederhana dan dapat dipahami oleh pemangku kepentingan.
B. MAKSUD DAN TUJUAN
1. Maksud dari petunjuk pelaksanaan ini adalah sebagai panduan bagi seluruh petugas penanggulangan bencana, terutama yang berkaitan dengan penggunaan bantuan peralatan penanggulangan bencana.
2. Tujuan dari petunjuk pelaksanaan ini adalah agar:
a. Peralatan penanggulangan bencana dapat digunakan secara efektif, efisien dan tepat sasaran,
b. Menjaga mutu peralatan sehingga dapat digunakan sesuai dengan prosedur standar dari masing-masing peralatan.
C. LANDASAN HUKUM
1. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, tambahan lembaran negara),');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8944, 'Bantuan peralatan penanggulangan bencana yang telah diberikan tersebut, harus dapat digunakan dan dimanfaatkan secara optimal dengan sumber daya 2015, No.822 6 yang terlatih dalam mengoperasikan peralatan penanggulangan bencana.
Salah satu unsur penting yang harus diperhatikan adalah cara penggunaan peralatan secara efektif dan efisien untuk mencapai hasil yang diinginkan.
