INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8949, 'perka-7-2013', 15, 'lampiran', 'Lampiran hal. 9', NULL, 9, '1. Tali pengikat digunakan untuk mengikat alas sandaran ke tandu supaya alas sandaran dalam posisi stabil.
2. Alas Bantal digunakan untuk merekatkan bantal sandaran.
3. Penahan dagu dibuka yang didalamnya terdapat bahan yang halus, material yang anti slip untuk menolong kestabilan kepala pasien dari pergerakan / goncangan. Mengamankan kepala bagian atas (dahi) dengan tali pengikat.
Penggunaannya:
1) Petugas ambulance yang terlatih atau berkompetensi harus membantu kondisi pasien dan mengikuti prosedur penggunaan alat dengan baik.
2) Posisi satu petugas diatas kepala dari pasien. Posisikan alas bantal tepat dibawah kepala pasien. Minimalkan gerakan dari pasien. Rekatkan Bantal kepala ke atas bantal pastikan lubang bantal kepala pas pada kiri dan kanan telinga. Rekatkan alas bantal bagian kiri, kanan dan atas ke bantal kepala.
3) Buka bantal dari penahan kepala dan tempatkan permukaan yang halus diatas alis mata atau dahi pasien. Eratkan pengikatnya.
4) Tempatkan penahan dagu yang kedua dibawah dagu.dan silangkan ke bagian atas penyangga leher. Pastikan pengikatnya terikat dengan erat.
c. Base Stretcher Base Stretcher dirancang untuk menstabilkan stretcher dari goncangan. Termasuk Landasan Tandu, Penahan Tandu, Kunci Tandu, Pengait Kunci Tandu, Tutup landasan dan Kunci Tutup Landasan.
Fungsi alat:
1) Landasan Tandu digunakan saat tandu naik turun dari mobil supaya tandu dalam keadaan datar tidak miring.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8949, '1. Tali pengikat digunakan untuk mengikat alas sandaran ke tandu supaya alas sandaran dalam posisi stabil.
2. Alas Bantal digunakan untuk merekatkan bantal sandaran.
3. Penahan dagu dibuka yang didalamnya terdapat bahan yang halus, material yang anti slip untuk menolong kestabilan kepala pasien dari pergerakan / goncangan. Mengamankan kepala bagian atas (dahi) dengan tali pengikat.
Penggunaannya:
1) Petugas ambulance yang terlatih atau berkompetensi harus membantu kondisi pasien dan mengikuti prosedur penggunaan alat dengan baik.
2) Posisi satu petugas diatas kepala dari pasien. Posisikan alas bantal tepat dibawah kepala pasien. Minimalkan gerakan dari pasien. Rekatkan Bantal kepala ke atas bantal pastikan lubang bantal kepala pas pada kiri dan kanan telinga. Rekatkan alas bantal bagian kiri, kanan dan atas ke bantal kepala.
3) Buka bantal dari penahan kepala dan tempatkan permukaan yang halus diatas alis mata atau dahi pasien. Eratkan pengikatnya.
4) Tempatkan penahan dagu yang kedua dibawah dagu.dan silangkan ke bagian atas penyangga leher. Pastikan pengikatnya terikat dengan erat.
c. Base Stretcher Base Stretcher dirancang untuk menstabilkan stretcher dari goncangan. Termasuk Landasan Tandu, Penahan Tandu, Kunci Tandu, Pengait Kunci Tandu, Tutup landasan dan Kunci Tutup Landasan.
Fungsi alat:
1) Landasan Tandu digunakan saat tandu naik turun dari mobil supaya tandu dalam keadaan datar tidak miring.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8950, 'perka-7-2013', 16, 'lampiran', 'Lampiran hal. 9', NULL, 9, '2) Penahan Tandu digunakan untuk Penahan tandu agar tidak keluar dari landasan tandu.
3) Kunci Tandu digunakan untuk menstabilkan tandu dari guncangan.
4) Pengait Kunci Tandu digunakan untuk membuka Kunci Tandu.
5) Kunci Tutup landasan digunakan untuk membuka dan menutup tutup landasan.
Penggunaannya:
1) Petugas ambulance yang berkualitas harus membantu kondisi pasien dan mengikuti prosedur penggunaan alat dengan baik.
2) Ketika memasukkan tandu dorong, petugas harus mengangkat dan menahan berat dari tandu dorong, pasien, dan peralatannya pada ketinggian yang cukup sampai tandu dorong dalam keadaan 253 2015, No.822 10 terlipat masuk ke mobil. Gunakan kunci tandu untuk menstabilkan tandu dengan memutar ke kanan lalu mendorongnya agar tandu terkunci (posisi stabil).
3) Untuk menurunkan tandu tarik pengait kunci tandu kemudian tarik kunci tandu dan putar kekiri. Turunkan tandu dorong.
4) Buka kunci tutup landasan dengan memutar tombol kekanan kemudian angkat keatas tutup landasan. (di bawah tutup landasan digunakan untuk menyimpan scoopstretcher). Untuk menutup kembali tinggal menurunkan saja tutup Landasannya dan akan secara automatis terkunci sendiri.
d. Folding Stretcher Folding Stretcher dibuat dengan maksud untuk memberikan pertolongan pertama untuk mengangkat pasien yang mengalami luka di lapangan.
Folding Stretcher terbuat dari aluminium dan Nylon reinforced vinyl fabric.
Ukuran Panjang : 2100 mm Tinggi : 100 mm Lebar 1: 550 mm Berat 1 5.8 kg Penggunaannya :');
