INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8968, 'perka-7-2013', 34, 'lampiran', 'Lampiran hal. 19', NULL, 19, 'Antenna Telescopic Mast Sebelum mengoperasikan Telescopic mast pastikan pada panel ME aliran listrik dari genset atau PLN sudah tersedia dan MCB untuk Outlet Air Compressor sudah dalam posisi ON.
Cara pengoperasiannya adalah sebagai berikut:
- Buka cover telescopic mast di roof.
- Pastikan stop kontak compressor sudah terpasang pada outlet ruang compressor. Apabila sudah terpasang maka pilot lamp pada remote akan menyala.
- Jika pilot lamp pada remote compressor sudah menyala maka telescopic mast sudah dapat digunakan dengan menekan tombol Up untuk menaikkan telescopic mast dan tombol Down untuk menurunkan telescopic mast.
- Sedangkan tombol Off berfungsi untuk menghentikan telescopic mast jika ketinggian yang kita inginkan sudah tercapai.
- Periksalah tempat operasional apakah disekelilingnya terdapat pepohonan atau kabel listrik karena akan mengganggu proses pengoperasian telescopic mast tersebut.
- Perhatikan Pressure Gauge yang terdapat pada komperlamen tersebut tekanan max dari compressor untuk menaikkan antenna tersebut adalah 2 bar. Apabila melebihi dari tekanan yang ditentukan maka akan mengakibatkan kerusakan komponen dari antenna tersebut. . Sliding Generator Set Sliding Generator Set / genset berfungsi untuk memudahkan maintenance genset. Seperti penambahan air accu, pemerikasaan oli mesin yang tidak bisa dilakukan apabila posisi genset berada di ruang genset pada kendaraan.
Cara pengoperasiannya adalah sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8968, 'Antenna Telescopic Mast Sebelum mengoperasikan Telescopic mast pastikan pada panel ME aliran listrik dari genset atau PLN sudah tersedia dan MCB untuk Outlet Air Compressor sudah dalam posisi ON.
Cara pengoperasiannya adalah sebagai berikut:
- Buka cover telescopic mast di roof.
- Pastikan stop kontak compressor sudah terpasang pada outlet ruang compressor. Apabila sudah terpasang maka pilot lamp pada remote akan menyala.
- Jika pilot lamp pada remote compressor sudah menyala maka telescopic mast sudah dapat digunakan dengan menekan tombol Up untuk menaikkan telescopic mast dan tombol Down untuk menurunkan telescopic mast.
- Sedangkan tombol Off berfungsi untuk menghentikan telescopic mast jika ketinggian yang kita inginkan sudah tercapai.
- Periksalah tempat operasional apakah disekelilingnya terdapat pepohonan atau kabel listrik karena akan mengganggu proses pengoperasian telescopic mast tersebut.
- Perhatikan Pressure Gauge yang terdapat pada komperlamen tersebut tekanan max dari compressor untuk menaikkan antenna tersebut adalah 2 bar. Apabila melebihi dari tekanan yang ditentukan maka akan mengakibatkan kerusakan komponen dari antenna tersebut. . Sliding Generator Set Sliding Generator Set / genset berfungsi untuk memudahkan maintenance genset. Seperti penambahan air accu, pemerikasaan oli mesin yang tidak bisa dilakukan apabila posisi genset berada di ruang genset pada kendaraan.
Cara pengoperasiannya adalah sebagai berikut:', 'Lampiran hal. 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8969, 'perka-7-2013', 35, 'lampiran', 'Lampiran hal. 19', NULL, 19, '- Posisi genset berada di bagian belakang kendaraan.
- Pada saat standby posisi genset tersebut berada di dalam ruang.
Peringatan: jangan menyalakan genset terlalu lama apabila posisi genset masih standby karena akan menyebabkan over heat pada genset tersebut.
- Bukalah baut pengunci yang berada di atas rel genset 2015, No.822 20
- Setelah baut tersebut dibuka maka tariklah genset tersebut kea rah luar sampai dengan lubang pengunci kedua pas atau rata dengan yang menempel pada brecket sliding.
- Apabila sliding genset sudah terkunci pada pengunci kedua maka genset tersebut sudah dapat digunakan. Peringatan: sebelum menyalakan genset tersebut pastikan grounding bar dan kabel sudah terpasang.
- Untuk mengembalikan posisi genset kembali ke posisi standby lakukan langkah-langkah sebaliknya.
h. Panduan Penggunaan VSAT Bergerak (MobileVSAT)
- Cara Pengoperasian secara Auto
1. Buka penutup antenna GPS (samping kanan kendaraan)
2. Tekan saklar Power ke: ON Tunggu beberapa saat sampai GPS VALID (GPS VD)"), sehingga layar controller seperti di bawah ini:
AUTO ISTART) MANUAL IPLuS)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8969, '- Posisi genset berada di bagian belakang kendaraan.
- Pada saat standby posisi genset tersebut berada di dalam ruang.
Peringatan: jangan menyalakan genset terlalu lama apabila posisi genset masih standby karena akan menyebabkan over heat pada genset tersebut.
- Bukalah baut pengunci yang berada di atas rel genset 2015, No.822 20
- Setelah baut tersebut dibuka maka tariklah genset tersebut kea rah luar sampai dengan lubang pengunci kedua pas atau rata dengan yang menempel pada brecket sliding.
- Apabila sliding genset sudah terkunci pada pengunci kedua maka genset tersebut sudah dapat digunakan. Peringatan: sebelum menyalakan genset tersebut pastikan grounding bar dan kabel sudah terpasang.
- Untuk mengembalikan posisi genset kembali ke posisi standby lakukan langkah-langkah sebaliknya.
h. Panduan Penggunaan VSAT Bergerak (MobileVSAT)
- Cara Pengoperasian secara Auto
1. Buka penutup antenna GPS (samping kanan kendaraan)
2. Tekan saklar Power ke: ON Tunggu beberapa saat sampai GPS VALID (GPS VD)"), sehingga layar controller seperti di bawah ini:
AUTO ISTART) MANUAL IPLuS)', 'Lampiran hal. 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8970, 'perka-7-2013', 36, 'lampiran', 'Lampiran hal. 20', NULL, 20, '3. Operasi AUTO"): a) Tekan tombol “START”, antenna akan bergerak otomatis mengarah ke satelit. Layar akan menampilkan gerakan Elevasi, Polarisasi, dan Azimuth. b) Setelah itu, layar controller akan berganti membaca modem dan melakukan FINE TUNING (Soft Track) “) Jika GPS Not Valid, antenna tidak bisa digerakan secara Otomatis “#) Selama dioperasikan, antenna direkomendasikan sambil diawasi pergerakannya, jika ada keadaan darurat, dapat segera dihentikan. c) Setelah t 3 - 6 menit, jika arah antenna telah sempurna, lampu LED “Modem Lock” akan menyala d) Diikuti lampu LED di modem satellite “ONLINE” menyala , serta LED “TX” berkedip. e) MVSAT siap digunakan f) Untuk menutup antenna, tekan tombol “STOW” selama # 4 detik g) Tekan tombol “DISH CLOSED”, antenna akan bergerak menutup ke arah depan dan lampu LED “Dish Stow” akan berkedip. h) Setelah antenna benar-benar menutup sempurna lampu LED “Dish Stow” akan menyala terus.
1) Matikan controller j) Tutup pintu penutup GPS (samping kanan kanan kendaraan).
21 2015, No.822
- Cara Pengoperasian secara Manual a) Saat controller VSAT sudah siap tekan tombol “PLUS” AUTO ISTART) MANUAL (PLus) b) Muncul menu jenis pengoperasian manual, tekan tombol “PLUS” AUTO ISTART) MANUAL IPLus) c) Layar menampilkan kecepatan motor penggerak. Jika ingin merubah tekan tombol “#? untuk menaikkan dan “-” untuk menurunkan kecepatan motor penggerak. Tekan “START” untuk memulai menggerakkan/mengarahkan VSAT secara manual.');
