INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8974, 'perka-7-2013', 40, 'lampiran', 'Lampiran hal. 24', NULL, 24, 'a. Menyiapkan mobil dapur lapangan:
- Buka pintu belakang dan pintu samping
- Turunkan box peralatan (2 unit)
- Turunkan kompor Lapangan/portable (2 unit)
- Pasang Tangga
- Pasang Tenda yang ada diatas mobil
- Keluarkan Genset dengan kunci letter T ,lalu pasang penyangganya
- Turunkan tabung pemadam di tempat yang mudah terjangkau
b. Cara mengalirkan gas:
- Pasang selang regulator ke tabung gas lalu dikencangkan (2 tabung)
- Buka kran di tabung gas ke posisi open
- Buka kran di selang gas 1 dan 2 (posisi open)
- Lalu buka kran yang ada di tengah pipa kuning (jalur gas)
- Lihat petunjuk pengaturan tekanan volome gas, atur valvenya di posisi diatas 1 bar
- Untuk mengalirkan gas ke arah penanak nasi, buka kran (jalur pipa kuning) yang letaknya di sebelah kiri bawah kompor yang ada diatas mobil
- Untuk mengalirkan gas ke kompor permanen yang diatas mobil, buka kran yang ada di bawah kompor paling kanan (yang menyambung langsung dengan pipa) :20- 25 2015, No.822
- Untuk mengalirkan gas ke kompor portable yang ada di lapangan,buka kran yang ada ditengah bawah kompor yang ada diatas mobil (kran yang menyambung langsung dengan selang gas yang menuju ke bawah) terdapat dua kran untuk dua kompor . Cara mengalirkan air untuk memasak dan mencuci:
- Isi tabung air yang terdapat di atas mobil (ada tiga tabung dengan kapasitas keseluruhan 600 liter)
- Buka kran kran yang terletak di pipa silver (jalur air)
- Ada tiga kran untuk tiga tabung yang ada di atas');
