INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8976, 'perka-7-2013', 42, 'lampiran', 'Lampiran hal. 26', NULL, 26, 'h. Cara menyalakan kompor gas yang ada di mobil:
- Putar pilot kran ( kran gas kecil) warna hitam ke arah open
- Nyalakan kompor dengan pemantik
- Putar kran gas besar ( warna merah ) untuk mengatur besar kecilnya api
- Putar pilot kran ( kran gas kecil) warna hitam ke arah stop/tutup
3. Pemeliharaan Mobil Dapur Lapangan:
Perawatan Mobil Dapur Lapangan sesuai dengan standar pabrikan dan pemanasan mobil minimal dua hari sekali, serta pengecekan peralatan pendukung.
Berikut adalah hal-hal penting yang harus diperhatikan dalam menggunakan mobil dapur lapangan:
a. Sebelum:
- Periksa bensin genset sebelum nyalakan jangan sampai kosong karena akan mempengaruhi kerja genset yang berakibat kerusakan pada alat-alat listrik.
- Pastikan regulator gas terpasang dengan benar.
- Sumber daya listrik dari genset boleh dipakai setelah suara/bunyi genset stabil
- Jangan membuka pemantik api terlalu besar yang berakibat api kompor menyala langsung besar.
- Pastikan semua valve / selang gas terpasang dengan benar dan kencang.
- Bila tercium bau gas berarti ada kebocoran.
- Bila kompor sudah menyala valve pemantik harus di tutup kembali (valve kecil warna hitam).
- Perhatikan jalur dan selang gas.
b. Sesudah:
- bersihkan semua peralatan yang telah digunakan.
- Simpan kembali peralatan yang telah digunakan ketempat semula atau yang disediakan.
F. Mobil Penjernih Air Tawar (Water Treatment Vehicle)');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8976, 'h. Cara menyalakan kompor gas yang ada di mobil:
- Putar pilot kran ( kran gas kecil) warna hitam ke arah open
- Nyalakan kompor dengan pemantik
- Putar kran gas besar ( warna merah ) untuk mengatur besar kecilnya api
- Putar pilot kran ( kran gas kecil) warna hitam ke arah stop/tutup
3. Pemeliharaan Mobil Dapur Lapangan:
Perawatan Mobil Dapur Lapangan sesuai dengan standar pabrikan dan pemanasan mobil minimal dua hari sekali, serta pengecekan peralatan pendukung.
Berikut adalah hal-hal penting yang harus diperhatikan dalam menggunakan mobil dapur lapangan:
a. Sebelum:
- Periksa bensin genset sebelum nyalakan jangan sampai kosong karena akan mempengaruhi kerja genset yang berakibat kerusakan pada alat-alat listrik.
- Pastikan regulator gas terpasang dengan benar.
- Sumber daya listrik dari genset boleh dipakai setelah suara/bunyi genset stabil
- Jangan membuka pemantik api terlalu besar yang berakibat api kompor menyala langsung besar.
- Pastikan semua valve / selang gas terpasang dengan benar dan kencang.
- Bila tercium bau gas berarti ada kebocoran.
- Bila kompor sudah menyala valve pemantik harus di tutup kembali (valve kecil warna hitam).
- Perhatikan jalur dan selang gas.
b. Sesudah:
- bersihkan semua peralatan yang telah digunakan.
- Simpan kembali peralatan yang telah digunakan ketempat semula atau yang disediakan.
F. Mobil Penjernih Air Tawar (Water Treatment Vehicle)', 'Lampiran hal. 26', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8977, 'perka-7-2013', 43, 'lampiran', 'Lampiran hal. 26', NULL, 26, '1. Pengertian Mobil Penjernih Air Tawar (Water Treatment Vehicle) adalah mobil yang berguna untuk mengolah air baku menjadi air siap minum.
2. Fungsi dan Penggunaan Mobil Penjernih Air (Water Treatment Vehicle):
Peralatan penjernih air langsung minum yang dapat membuang partikel yang berbahaya di dalam sumber air baku seperti logam-logam berat, pestisida, racun-racun, zat kimia, partikel-partikel radio aktif, bakteri, virus, garam, endapan dsb dalam rangka pemenuhan kebutuhan dasar.
27 2015, No.822 Sumber air baku diproses melalui sistem ultrafiltrasi terlebih dahulu sebelum diproses ke Water Purifier. Dalam kasus ini dicontohkan air banjir.
Air banjir ini melalui terlebih dahulu tabung kaporit (Chlorinator) kemudian melalui pompa hisap. Air banjir setelah keluar dari pompa hisap tersebut diproses / dicampur dengan cairan kimia ( coagulant ) yang diatur oleh Dosing Pump dengan tujuan supaya kotoran-kotoran tersebut dapat menggumpal. Setelah itu melalui suatu proses secara bertahap dalam tangki air, air tersebut dapat menjadi lebih bersih. Air proses tersebut kemudian diproses ke tahap selanjutnya yaitu menuju Sistem Water Purifier dan Reverse Osmosis.
RO (Reverse Osmosis) dalam tahapan proses penyaringan sebagai berikut:
a. Screen / Saringan
- Screen / Saringan yang berfungsi menahan/menyaring kotoran-kotoran besar, Screen / Saringan ini harus selalu dilakukan pemeriksaan agar mencegah dari penyumbatan. Lakukan pembersihan bila terjadi penyumbatan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8977, '1. Pengertian Mobil Penjernih Air Tawar (Water Treatment Vehicle) adalah mobil yang berguna untuk mengolah air baku menjadi air siap minum.
2. Fungsi dan Penggunaan Mobil Penjernih Air (Water Treatment Vehicle):
Peralatan penjernih air langsung minum yang dapat membuang partikel yang berbahaya di dalam sumber air baku seperti logam-logam berat, pestisida, racun-racun, zat kimia, partikel-partikel radio aktif, bakteri, virus, garam, endapan dsb dalam rangka pemenuhan kebutuhan dasar.
27 2015, No.822 Sumber air baku diproses melalui sistem ultrafiltrasi terlebih dahulu sebelum diproses ke Water Purifier. Dalam kasus ini dicontohkan air banjir.
Air banjir ini melalui terlebih dahulu tabung kaporit (Chlorinator) kemudian melalui pompa hisap. Air banjir setelah keluar dari pompa hisap tersebut diproses / dicampur dengan cairan kimia ( coagulant ) yang diatur oleh Dosing Pump dengan tujuan supaya kotoran-kotoran tersebut dapat menggumpal. Setelah itu melalui suatu proses secara bertahap dalam tangki air, air tersebut dapat menjadi lebih bersih. Air proses tersebut kemudian diproses ke tahap selanjutnya yaitu menuju Sistem Water Purifier dan Reverse Osmosis.
RO (Reverse Osmosis) dalam tahapan proses penyaringan sebagai berikut:
a. Screen / Saringan
- Screen / Saringan yang berfungsi menahan/menyaring kotoran-kotoran besar, Screen / Saringan ini harus selalu dilakukan pemeriksaan agar mencegah dari penyumbatan. Lakukan pembersihan bila terjadi penyumbatan.', 'Lampiran hal. 26', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8978, 'perka-7-2013', 44, 'lampiran', 'Lampiran hal. 27', NULL, 27, 'b. Tabung kaporit Tabung kaporit harus selalu dalam kondisi terisi pada saat pengoperasian. Kaporit berfungsi sebagai disinfektan dan Oksidasi.
Penggunaan/pemakaian:
- Pompa dalam keadaan mati, tutup Ballvalve 1
- Buka tutup tabung
- Masukkan tablet kaporit kedalam tabung. Isi 2-4 butir
- Tutup kembali hingga rapat.
c. Air siap diproses oleh media filter tahap pertama Setelah air baku masuk siap diproses dengan tekanan pompa menuju filter pertama / tabung pertama.
Tabung pertama terdiri dari :
Pasir Silika, Bangka dengan dicampur Greensand Mangganese (BIRM) Fungsi :
- Menyaring partikel padat
- Mengurangi tingkat kekeruhan dalam air (Turbidity)
- Mengurangi kadar besi dalam air.
Cara Pengunaan:
- Periksa watermur apakah dalam keadaan tertutup rapat (watermur berfungsi sebagai sistem mur/baut agar memudahkan pembongkaran atau penggantian media. Sehingga tidak diperlukan pemotongan pipa.
- Posisi Three Way Valve, dalam keadaan backwash (hanya untuk pertama kali penggunaan/pengoperasian) lakukan hingga kondisi air dalam keadaan sama dengan air baku pada umumnya, pada pertama kali pengoperasian dilakukan selama 20-30 menit.
2015, No.822 28
- Putar valve ke posisi rinse, untuk melakukan pembilasan, biasanya air berangsur akan menjadi lebih bening cukup lakukan 1-2 menit saja, lalu putar kembali kedalam posisi backwash.
- Lakukan proses pada no.3 tersebut berulang-ulang hingga air menjadi lebih bening.
- Lakukan proses Filter air telah dalam kondisi sama dengan air baku.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8978, 'b. Tabung kaporit Tabung kaporit harus selalu dalam kondisi terisi pada saat pengoperasian. Kaporit berfungsi sebagai disinfektan dan Oksidasi.
