INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8980, 'perka-7-2013', 46, 'lampiran', 'Lampiran hal. 29', NULL, 29, '29 2015, No.822 Cara Pengunaan:
Mesin pada awal pengoperasiannya dalam keadaan sudah aktif cukup dilakukan backwash, fast rinsing dan In-Serve (sebagai fungsi filter).
Pada saat filter mulai tidak aktif, maka Softener tersebut harus dilakukan Regenerasi (pengaktifan kembali): Merupakan proses pengaktifan Cation Exchange Resin dimana dilakukan pada saat mulai jenuh, untuk regenerasi rutin, (secara umum dilakukan setiap 2 minggu sekali) Proses Kerja :
- Isi brain tank dengan NaCL (garam) sebanyak 5 kg, isi Brain tank dengan air dengan memutar valve ke posisi Brain Refill.
- Setelah penuh putar posisi valve kearah regeneration, maka air pada tangki garam akan tersedot secara perlahan hingga, lakukan proses ini hingga air dalam tangki garam habis, dan setelah air habis lakukan hal berikut ini.
- Putar valve ke posisi backwash, lakukan hal ini hingga air tidak asin lagi lalu lanjutkan ke tahap berikut.
- Putar valve ke posisi fast rinse, cek hingga TDS air masuk - TDS air keluar. Setelah dilakukan pengecekan maka valve siap diputar kearah In-serve untuk proses filter.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8980, '29 2015, No.822 Cara Pengunaan:
Mesin pada awal pengoperasiannya dalam keadaan sudah aktif cukup dilakukan backwash, fast rinsing dan In-Serve (sebagai fungsi filter).
Pada saat filter mulai tidak aktif, maka Softener tersebut harus dilakukan Regenerasi (pengaktifan kembali): Merupakan proses pengaktifan Cation Exchange Resin dimana dilakukan pada saat mulai jenuh, untuk regenerasi rutin, (secara umum dilakukan setiap 2 minggu sekali) Proses Kerja :
- Isi brain tank dengan NaCL (garam) sebanyak 5 kg, isi Brain tank dengan air dengan memutar valve ke posisi Brain Refill.
- Setelah penuh putar posisi valve kearah regeneration, maka air pada tangki garam akan tersedot secara perlahan hingga, lakukan proses ini hingga air dalam tangki garam habis, dan setelah air habis lakukan hal berikut ini.
- Putar valve ke posisi backwash, lakukan hal ini hingga air tidak asin lagi lalu lanjutkan ke tahap berikut.
- Putar valve ke posisi fast rinse, cek hingga TDS air masuk - TDS air keluar. Setelah dilakukan pengecekan maka valve siap diputar kearah In-serve untuk proses filter.', 'Lampiran hal. 29', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8981, 'perka-7-2013', 47, 'lampiran', 'Lampiran hal. 29', NULL, 29, 'Air siap diproses menuju Filter Cartridge 5 mikron Pada proses ini air akan melalui Filter 2 buah Cartridge 1 ukuran (size 20”), Sedimen 0.5 mikron & 0.1 mikron, berfungsi menyaring kotoran dengan ukuran » 0.5 mikron & 0.1 mikron Spesifikasi produk : Cartridge size 20”, daya saring 0.5 mikro meter & 0.1 mikro meter. . Proses air masuk menuju ultra filtrasi (0.01 mikron) Tahapan proses pemurnian air minum den hnologi Reverse Osmosis See.
Lampiran 4 Ultra Firasi vm OI Miron Proses .an Tinggi —— Pipa Air siap konsumsi Reverse Osmosis| "5 Watermur System BI Ballvalve 225 2015, No.822 30 Proses produksi Ultra Filtrasi 0.01 mikron
- Pressure operasi pada posisi 2.5 bar. Peningkatan pada pressure berarti terjadi pemampatan/penyumbatan sehingga harus dilakukan backwash.
- Proses backwash dilakukan setiap produksi 5.000 liter atau minimal 1(satu) kali setiap hari dengan cara menutup valve 3.
- Tutup valve 3 ,tutup valve 5 dan buka valve 4, buka valve 6, maka air akan mengalir ke arah air pembuangan
- Proses Rinse/cross flow dilakukan dengan cara:
Tutup valve 4 dan 5 , buka valve 3 dan 6
- Proses Produksi, dilakukan dengan cara:
Tutup valve 4, 6 dan 8, buka valve 3, 5 dan 7 Maka air siap masuk ke dalam tangki mobil (5.000 liter) atau dapat dilakukan bypass langsung ke mesin RO dengan melakukan
- Tutup valve 4, 6, 7 dan 9, buka valve 3, 5 dan 8 (OPTIONAL dalam keadaan mendesak saja) Setelah melalui proses Ultra filtrasi air harus dalam kondisi :
- Aman dari bakteri dan virus');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8981, 'Air siap diproses menuju Filter Cartridge 5 mikron Pada proses ini air akan melalui Filter 2 buah Cartridge 1 ukuran (size 20”), Sedimen 0.5 mikron & 0.1 mikron, berfungsi menyaring kotoran dengan ukuran » 0.5 mikron & 0.1 mikron Spesifikasi produk : Cartridge size 20”, daya saring 0.5 mikro meter & 0.1 mikro meter. . Proses air masuk menuju ultra filtrasi (0.01 mikron) Tahapan proses pemurnian air minum den hnologi Reverse Osmosis See.
Lampiran 4 Ultra Firasi vm OI Miron Proses .an Tinggi —— Pipa Air siap konsumsi Reverse Osmosis| "5 Watermur System BI Ballvalve 225 2015, No.822 30 Proses produksi Ultra Filtrasi 0.01 mikron
- Pressure operasi pada posisi 2.5 bar. Peningkatan pada pressure berarti terjadi pemampatan/penyumbatan sehingga harus dilakukan backwash.
- Proses backwash dilakukan setiap produksi 5.000 liter atau minimal 1(satu) kali setiap hari dengan cara menutup valve 3.
- Tutup valve 3 ,tutup valve 5 dan buka valve 4, buka valve 6, maka air akan mengalir ke arah air pembuangan
- Proses Rinse/cross flow dilakukan dengan cara:
