INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8984, 'perka-7-2013', 50, 'lampiran', 'Lampiran hal. 31', NULL, 31, '- Petunjuk BUKA/TUTUP kran untuk pengisian air 1) Proses dari air banjir langsung ke ke Tangki Air No.1-4(air endapan) via pompa Nochi a) Kran No. 3 BUKA b) MCB A dan MCB 1 ON 2) Proses dari Air Banjir ke Tangki No.5 (air bersih) Kran No. 1 TUTUP Kran No. 2 BUKA Kran No. 3 BUKA Kran No. 4 TUTUP Kran No. 5 TUTUP Kran No. 6 BUKA Kran No. 7 TUTUP Kran No. 8 BUKA Kran No. 9 TUTUP Kran No.10 BUKA MCB A, MCB 1 dan MCB 4 ON 2015, No.822 39 3) Proses dari Air Tanah/Kran/PDAM ke Tangki No.5 (air bersih) Kran No. 1 BUKA Kran No. 2 TUTUP Kran No. 3 TUTUP Kran No. 4 TUTUP Kran No. 5 TUTUP Kran No. 6 BUKA Kran No. 7 TUTUP Kran No. 8 BUKA Kran No. 9 TUTUP Kran No.10 BUKA MCB A dan MCB 4 ON 4) Proses air minum dari air tanah langsung ke mesin RO (Via pompa Wasser HIJAU) Kran No. 1 BUKA Kran No. 2 TUTUP Kran No. 3 TUTUP Kran No. 4 TUTUP Kran No. 5 TUTUP Kran No. 6 BUKA Kran No. 7 TUTUP Kran No. 8 BUKA Kran No. 9 BUKA Kran No.10 TUTUP MCBA ” MCB4 PF MCB2&3 “ MCB5ON 5) Proses air minum dari air Tangki No.5 ke mesin RO (Via pompa Wasser HIJAU) Kran No. 1 TUTUP Kran No. 2 TUTUP Kran No. 3 TUTUP Kran No. 4 BUKA Kran No. 5 BUKA Kran No. 6 TUTUP Kran No. 7 TUTUP Kran No. 8 BUKA Kran No. 9 BUKA Kran No.10 TUTUP MCBA ST MCB4 “ MCB2&3 P”MCB5ON 33 2015, No.822');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8984, '- Petunjuk BUKA/TUTUP kran untuk pengisian air 1) Proses dari air banjir langsung ke ke Tangki Air No.1-4(air endapan) via pompa Nochi a) Kran No. 3 BUKA b) MCB A dan MCB 1 ON 2) Proses dari Air Banjir ke Tangki No.5 (air bersih) Kran No. 1 TUTUP Kran No. 2 BUKA Kran No. 3 BUKA Kran No. 4 TUTUP Kran No. 5 TUTUP Kran No. 6 BUKA Kran No. 7 TUTUP Kran No. 8 BUKA Kran No. 9 TUTUP Kran No.10 BUKA MCB A, MCB 1 dan MCB 4 ON 2015, No.822 39 3) Proses dari Air Tanah/Kran/PDAM ke Tangki No.5 (air bersih) Kran No. 1 BUKA Kran No. 2 TUTUP Kran No. 3 TUTUP Kran No. 4 TUTUP Kran No. 5 TUTUP Kran No. 6 BUKA Kran No. 7 TUTUP Kran No. 8 BUKA Kran No. 9 TUTUP Kran No.10 BUKA MCB A dan MCB 4 ON 4) Proses air minum dari air tanah langsung ke mesin RO (Via pompa Wasser HIJAU) Kran No. 1 BUKA Kran No. 2 TUTUP Kran No. 3 TUTUP Kran No. 4 TUTUP Kran No. 5 TUTUP Kran No. 6 BUKA Kran No. 7 TUTUP Kran No. 8 BUKA Kran No. 9 BUKA Kran No.10 TUTUP MCBA ” MCB4 PF MCB2&3 “ MCB5ON 5) Proses air minum dari air Tangki No.5 ke mesin RO (Via pompa Wasser HIJAU) Kran No. 1 TUTUP Kran No. 2 TUTUP Kran No. 3 TUTUP Kran No. 4 BUKA Kran No. 5 BUKA Kran No. 6 TUTUP Kran No. 7 TUTUP Kran No. 8 BUKA Kran No. 9 BUKA Kran No.10 TUTUP MCBA ST MCB4 “ MCB2&3 P”MCB5ON 33 2015, No.822', 'Lampiran hal. 31', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8985, 'perka-7-2013', 51, 'lampiran', 'Lampiran hal. 33', NULL, 33, '- Proses / Cara mengaktifkan Mesin Water Purifier 1) Sumber air baku dari sumber air diluar tangki sendiri a) Pastikan sumber air TIDAK mengandung partikel tanah/keruh karena Bisa mengakibatkan filter cepat mampat. Jika air keruh mengandung Partikel tanah, endapkan air di bak penampungan dan ambil air dibagian atasnya yang lebih jernih. b) Sambungkan pipa air ke mesin Pompa hisap Wasser hijau. c) Pilih Posisi Kran pada Petunjuk proses dari Air Tanah Langsung Ke RO diatas. d) Pilih posisi ON untuk MCB No. 4 (Pompa air) e) PERHATIAN : Pompa Wasser Hijau TIDAK BEKERJA Jika :
Tidak ada Air yang disedot atau Air di tangki sudah PENUH (cek radar).
2) Sebelum menjalankan mesin RO, PASTIKAN posisi jarum pada Pressure Gauge sebelah kiri panel acrylic depan harus diatas 20 Kg/Psi.
3) Power ON Mesin RO a) Tunggu Proses Micro Computer panel display led dari Huruf : F (flushing) menguras hingga berhenti setelah Huruf O (pump) bekerja. b) Petunjuk panel display led : -I (source) sumber air kurang, 8 (full) air sudah penuh, S (strong washing) mencuci dan membilas, 7 (over haul) sumber air tidak ada pompa menjadi panas.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8985, '- Proses / Cara mengaktifkan Mesin Water Purifier 1) Sumber air baku dari sumber air diluar tangki sendiri a) Pastikan sumber air TIDAK mengandung partikel tanah/keruh karena Bisa mengakibatkan filter cepat mampat. Jika air keruh mengandung Partikel tanah, endapkan air di bak penampungan dan ambil air dibagian atasnya yang lebih jernih. b) Sambungkan pipa air ke mesin Pompa hisap Wasser hijau. c) Pilih Posisi Kran pada Petunjuk proses dari Air Tanah Langsung Ke RO diatas. d) Pilih posisi ON untuk MCB No. 4 (Pompa air) e) PERHATIAN : Pompa Wasser Hijau TIDAK BEKERJA Jika :
Tidak ada Air yang disedot atau Air di tangki sudah PENUH (cek radar).
2) Sebelum menjalankan mesin RO, PASTIKAN posisi jarum pada Pressure Gauge sebelah kiri panel acrylic depan harus diatas 20 Kg/Psi.
3) Power ON Mesin RO a) Tunggu Proses Micro Computer panel display led dari Huruf : F (flushing) menguras hingga berhenti setelah Huruf O (pump) bekerja. b) Petunjuk panel display led : -I (source) sumber air kurang, 8 (full) air sudah penuh, S (strong washing) mencuci dan membilas, 7 (over haul) sumber air tidak ada pompa menjadi panas.', 'Lampiran hal. 33', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8986, 'perka-7-2013', 52, 'lampiran', 'Lampiran hal. 33', NULL, 33, 'PERHATIKAN : Air Buangan RO akan keluar dari pipa sebelah kiri Accu mobil. Air Buangan ini tidak boleh diproses kembali ataupun diminum. Air Buangan RO hanya untuk mencuci atau mandi c) Periksa kebocoran Air. Bila ada kebocoran, segera matikan mesin RO dan segera perbaiki. d) Periksa Pressure Gauge yang ada disisi kanan Mobil didepan Tabung air Wellmate. Bila air hasil RO mengalir, jarum Pressure Gauge ini akan naik. e) Pastikan lampu merah petunjuk Ultra Violet yang ada pada Box listrik UV menyala tanda Ultra Violet telah bekerja. f) Buka kran kran yang ada untuk mengalirkan air yang siap diminum dan steril karena telah melewati Ultra Violet. g) Perlu dilakukan Manual Flush untuk membersihkan RO setelah 2 jam beroperasi agar RO tetap terawat dan air yang dihasilkan tetap terjaga mutunya.
2015, No.822 34 h) Lakukan pembukaan kran seperti di bagian 2b untuk pengisian air hasil filter ke tangki bersamaan dengan produksi air minum RO.
4) Sumber air dari tangki No.5 a) Pastikan air tangki berasal dari hasil filtrasi dengan pembukaan kran pada bagian 2b dan air masuk dari pompa hisap Wasser hijau sehingga air melewati klorinator yang berisi kaporit tablet. b) Pastikan sumber air dari tangki tidak boleh kurang dari pipa hisap air untuk mencegah pompa Nochi Stainless steel hitam dari panas dan kerusakan. c) Lakukan prosedur seperti pada bagian 3a.l dan seterusnya. d) Buka kran air minum yang tersedia bila ingin mendapatkan air siap minum.
k. Informasi reverse osmosis sistem');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8986, 'PERHATIKAN : Air Buangan RO akan keluar dari pipa sebelah kiri Accu mobil. Air Buangan ini tidak boleh diproses kembali ataupun diminum. Air Buangan RO hanya untuk mencuci atau mandi c) Periksa kebocoran Air. Bila ada kebocoran, segera matikan mesin RO dan segera perbaiki. d) Periksa Pressure Gauge yang ada disisi kanan Mobil didepan Tabung air Wellmate. Bila air hasil RO mengalir, jarum Pressure Gauge ini akan naik. e) Pastikan lampu merah petunjuk Ultra Violet yang ada pada Box listrik UV menyala tanda Ultra Violet telah bekerja. f) Buka kran kran yang ada untuk mengalirkan air yang siap diminum dan steril karena telah melewati Ultra Violet. g) Perlu dilakukan Manual Flush untuk membersihkan RO setelah 2 jam beroperasi agar RO tetap terawat dan air yang dihasilkan tetap terjaga mutunya.
2015, No.822 34 h) Lakukan pembukaan kran seperti di bagian 2b untuk pengisian air hasil filter ke tangki bersamaan dengan produksi air minum RO.
4) Sumber air dari tangki No.5 a) Pastikan air tangki berasal dari hasil filtrasi dengan pembukaan kran pada bagian 2b dan air masuk dari pompa hisap Wasser hijau sehingga air melewati klorinator yang berisi kaporit tablet. b) Pastikan sumber air dari tangki tidak boleh kurang dari pipa hisap air untuk mencegah pompa Nochi Stainless steel hitam dari panas dan kerusakan. c) Lakukan prosedur seperti pada bagian 3a.l dan seterusnya. d) Buka kran air minum yang tersedia bila ingin mendapatkan air siap minum.
k. Informasi reverse osmosis sistem', 'Lampiran hal. 33', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8987, 'perka-7-2013', 53, 'lampiran', 'Lampiran hal. 34', NULL, 34, '- Low Pressure Switch: Switch control sebagai indicator bahwa pompa RO cukup mendapat supply air.
Bila supply air terhenti maka switch ini menginformasikan ke pompa utuk segera mati
- TDS Meter air masuk:
Indikasi untuk TDS input (TDS air masuk/air baku)
- Micro Computer Controller :
Sebagai indikator TDS Hasil, merupakan central auto control dari RO System, mengatur: a) automatic pencucian membrane b) TDS Hasil c) Selenoid Control
- Flow Meter Air Produk Indikator air hasil per menit dalam hitungan LPM (liter per minute) dan GPM (gallon per minute) Note : 1 gallon - 3.78 liter
- Flow Meter Air Limbah Indikator air buangan per menit dalam hitungan LPM (liter per minute) dan GPM (gallon per minute) Note : 1 gallon - 3.78 liter Sebaiknya kedua flow meter ini memiliki hitungan 2.5-3 liter/menit untuk air hasil dan 5-5.5 litr/menit untuk air limbah
- On/off switch Switch untuk menghidupkan dan mematikan arus listrik pada RO system 35 2015, No.822
- Manual Flushing Switch Switch pencucian membrane secara manual Membrane/ operating Pressure Switch Indikator tekanan pada saat RO beroperasi, pada saat sistem beroperasi tekanan akan menunjukkan pada 150-175 psi
- Inlet/feed Water Pressure Tekanan pompa air masuk kedalam PROCON, Indikator Tekanan air masuk ke Pompa Beroperasi secara normal pada 30-40 psi. bila indikator ini menunjukkan pada 0 psi maka RO akan mati dan tidak stabil beroperasi.
Segera matikan Switch On/ Off. Periksa kondisi air masuk.
- Recycle Valve :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8987, '- Low Pressure Switch: Switch control sebagai indicator bahwa pompa RO cukup mendapat supply air.
Bila supply air terhenti maka switch ini menginformasikan ke pompa utuk segera mati
- TDS Meter air masuk:
Indikasi untuk TDS input (TDS air masuk/air baku)
- Micro Computer Controller :
Sebagai indikator TDS Hasil, merupakan central auto control dari RO System, mengatur: a) automatic pencucian membrane b) TDS Hasil c) Selenoid Control
- Flow Meter Air Produk Indikator air hasil per menit dalam hitungan LPM (liter per minute) dan GPM (gallon per minute) Note : 1 gallon - 3.78 liter
- Flow Meter Air Limbah Indikator air buangan per menit dalam hitungan LPM (liter per minute) dan GPM (gallon per minute) Note : 1 gallon - 3.78 liter Sebaiknya kedua flow meter ini memiliki hitungan 2.5-3 liter/menit untuk air hasil dan 5-5.5 litr/menit untuk air limbah
- On/off switch Switch untuk menghidupkan dan mematikan arus listrik pada RO system 35 2015, No.822
- Manual Flushing Switch Switch pencucian membrane secara manual Membrane/ operating Pressure Switch Indikator tekanan pada saat RO beroperasi, pada saat sistem beroperasi tekanan akan menunjukkan pada 150-175 psi
- Inlet/feed Water Pressure Tekanan pompa air masuk kedalam PROCON, Indikator Tekanan air masuk ke Pompa Beroperasi secara normal pada 30-40 psi. bila indikator ini menunjukkan pada 0 psi maka RO akan mati dan tidak stabil beroperasi.
Segera matikan Switch On/ Off. Periksa kondisi air masuk.
- Recycle Valve :', 'Lampiran hal. 34', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8988, 'perka-7-2013', 54, 'lampiran', 'Lampiran hal. 35', NULL, 35, 'Mengatur banyaknya air buangan untuk diolah lagi kedalam membrane.
Semakin besar valve dibuka semakn besar air limbah diolah lagi kedalam membrane RO.
- Needle Valve:
Pengatur — Tekanan ke membrane diindikasikan dengan meningkat/menurunnya tekanan pada Membrane/ operating Pressure Guide Air hasil reverse osmosis sistem ditampung Setelah air diproses melalui sistem RO maka air ditampung pada Pressure Tank Well Mate Tanki dilengkapi dengan WLC (Water Level Control) bila tangki sudah penuh maka RO system akan mati secara otomatis Bila tangki sudah kosong maka, RO System akan bekerja kembali. . Pendistribusian air minum Setelah keluar dari Tangki Penampungan air hasil maka terdapat pipa distribusi untuk proses pengisian air sebuah valve distribusi.
Pada sistem distribusi ini juga dilengkapi dengan pressure guide untuk melihat tekanan /pressure pada Tanki Well mate.
Sebelum melalui distribusi pengisian maka sistem akan melalui sebuah sistem Ultra Violet sebagai proses sterilisasi unit, sehingga siap untuk diminum.
Sistem dirancang knock down dengan watermur untuk pembongkaran atau perbaikan bila memang diperlukan.
DILARANG :
- Memasukkan kembali air buangan/limbah RO untuk disaring kembali atau dijadikan air sumber sebagai air baku, karena akan merusak membrane.
- Menyumbat atau memperkecil air buangan atau limbah, karena akan merusak membrane.
231- 2015, No.822 36');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8988, 'Mengatur banyaknya air buangan untuk diolah lagi kedalam membrane.
Semakin besar valve dibuka semakn besar air limbah diolah lagi kedalam membrane RO.
- Needle Valve:
Pengatur — Tekanan ke membrane diindikasikan dengan meningkat/menurunnya tekanan pada Membrane/ operating Pressure Guide Air hasil reverse osmosis sistem ditampung Setelah air diproses melalui sistem RO maka air ditampung pada Pressure Tank Well Mate Tanki dilengkapi dengan WLC (Water Level Control) bila tangki sudah penuh maka RO system akan mati secara otomatis Bila tangki sudah kosong maka, RO System akan bekerja kembali. . Pendistribusian air minum Setelah keluar dari Tangki Penampungan air hasil maka terdapat pipa distribusi untuk proses pengisian air sebuah valve distribusi.
Pada sistem distribusi ini juga dilengkapi dengan pressure guide untuk melihat tekanan /pressure pada Tanki Well mate.
Sebelum melalui distribusi pengisian maka sistem akan melalui sebuah sistem Ultra Violet sebagai proses sterilisasi unit, sehingga siap untuk diminum.
Sistem dirancang knock down dengan watermur untuk pembongkaran atau perbaikan bila memang diperlukan.
DILARANG :
- Memasukkan kembali air buangan/limbah RO untuk disaring kembali atau dijadikan air sumber sebagai air baku, karena akan merusak membrane.
- Menyumbat atau memperkecil air buangan atau limbah, karena akan merusak membrane.
231- 2015, No.822 36', 'Lampiran hal. 35', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8989, 'perka-7-2013', 55, 'lampiran', 'Lampiran hal. 36', NULL, 36, '- Bila RO tidak dipergunakan cukup lama atau lebih dari 2 x 24 jam , maka buanglah air didalam tangki dan produksi selama 20 menit, baru dapat dikonsumsi.
3. Pemeliharaan Melakukan perawatan berkala mobil pengolahan air dan semua peralatan yang ada di dalamnya. Mobil dipanaskan minimal dua hari sekali.
G. Trailer Bangunan Runtuh (Collapsed Building Trailer) Trailer Bangunan Runtuh merupakan Peralatan Penyelamatan Pada Bangunan Runtuh yang ditempatkan pada Trailer, berfungsi untuk melakukan penyelamatan pada korban-korban yang terjebak dalam bangunan runtuh.
Peralatan yang terdapat dalam Trailer pada umumnya adalah peralatan untuk mencari, menemukan serta memindahkan korban pada tempat yang aman.
Sedangkan dari fungsinya, peralatan dalam Trailer ini memiliki fungsi sebagai alat deteksi, pemotong, penyangga, pengangkat, pemecah, penerangan, penandaan serta peralatan pertukangan umum.
Peralatan ini sebaiknya dioperasikan oleh operator yang telah dilatih dalam Penyelamatan Bangunan Runtuh atau CSSR atau USAR, serta mengikuti standard NFPA 1600 atau yang setara.
Penting untuk diingat bahwa penggunaan peralatan ini harus diikuti pemakaian peralatan pelindung personil seperti :
1. Helm Keselamatan
2. Kacamata Keselamatan
3. Penutup Telinga
4. Penutup Hidung
5. Sarung Tangan Keselamatan, anti potong dan anti panas
6. Pelindung lutuh, dengkul, lengan.
7. Sepatu Keselamatan.
8. Cara Penggunaan dan Pengoperasian :
a. PERALATAN DETEKSI KORBAN HIDUP');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8989, '- Bila RO tidak dipergunakan cukup lama atau lebih dari 2 x 24 jam , maka buanglah air didalam tangki dan produksi selama 20 menit, baru dapat dikonsumsi.
