INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (8996, 'perka-7-2013', 62, 'lampiran', 'Lampiran hal. 45', NULL, 45, '- Terdapat PENUTUP pada sambungan sensor paling akhir, selalu pastikan bahwa penutup terpasang ditempatnya.
2Rl3 2015, No.822 46 TATA CARA PEMASANGAN SENSOR AKUSTIK “- Cara pemasangan atau cara menyambung menggunakan cara yang sama dengan sambungan pada sensor seismic. “ Sensor disambungkan pada port yang terdapat pada konsol DISPLAY. “ Sensor akustik 1 letakkan di sebelah paling kiri, sedangkan sensor akustik 2 diletakkan pada paling kanan. “ Jangan menambah sensor akustik pada setiap DISPLAY, kecuali yang disebutkan diatas. “ Perhatikan gambar dibawah untuk tata cara pemasangan sensor akustik.
DO NOT TWIST! TATA CARA PEMASANGAN TELESKOP PROBE o Buka ring pengaman o Sesuaikan kabel pada sensor o Ikuti gambar berikut untuk pemasangannya TATA CARA PEMASANGAN HEADPHONE PADA DISPLAY
- Terdapat dua fasilitas port tersedia
- Memungkinkan mendengarkan secara simultan diantara dua orang.
- Memungkinkan terintegrasi dengan sistem intercom.
- Dapat digunakan dengan “protective headgear''
- Perhatikan cara pemasangan pada gambar berikut.
SAP 47 2015, No.822 Adjustable Strap Boom Microphone Headphone Ports Gambar : Rangkaian Headphone pada Display
b. Kamera Pencari Korban (Merk : Scorpe Vibrascope) Kamera Pencari Korban buatan SCORPE yang dikenal dengan nama Vibrascope adalah peralatan berupa kamera yang berfungsi sebagai alat untuk pencari korban yang hidup dibalik reruntuhan khususnya memastikan kondisi korban.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (8996, '- Terdapat PENUTUP pada sambungan sensor paling akhir, selalu pastikan bahwa penutup terpasang ditempatnya.
