INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9006, 'perka-7-2013', 72, 'lampiran', 'Lampiran hal. 66', NULL, 66, '2. Gunakan choke jika dalam kondisi susah dihidupkan.
