INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9014, 'perka-7-2013', 80, 'lampiran', 'Lampiran hal. 76', NULL, 76, 'Motor trail berfungsi untuk memantauan kejadian bencana sekaligus untuk kaji cepat ke lokasi bencana yang sulit dijangkau oleh kendaraan roda empat.
3. Pemeliharaan:
Perawatan Motor Trail sesuai dengan standar pabrikan dan pemasan mobil minimal dua hari sekali, serta pengecekan peralatan pendukung.
J. Perahu Karet Tanpa Mesin (Rubber Boat)
1. Pengertian Perahu Karet Tanpa mesin (Rubber Boat) adalah perahu yang berbahan dasar dari karet dan sejenisnya yang berisi udara (Pending)
2. Fungsi dan Penggunaan Perahu Karet Tanpa Mesin (Rubber Boat):
Perahu karet adalah alat angkut yang berfungsi untuk Evakuasi korban di air.
Penggunaannya:
H.Pemasangan deck Pemasangan deck untuk setiap ukuran sama, berikut pemasangan deck yang benar : -Masukkan deck nomor 1 ke bagian depan lantai perahu dan masukkan deck nomor 4 ke bagian belakang lantai perahu sampai tertahan oleh kuncian dek di transom.
2725 77 2015, No.822
- Masukkan deck nomor 2 di antara deck nomor 1 dan nomor 3, dan ditekan kebawah sampai rata.
- Kemudian pasang stringer ke samping deck lantai yang sudah tertata rapi, lalu dorong stringer ke arah dalam perahu sampai benar-benar terkunci.
- Setelah pemasangan selesai, pompalah badan perahu sesuai tekanan angin yang direkomendasikan. -Jika badan sudah terpompa, kemudian dilanjutkan dengan pemompaan keel hingga badan perahu terangkat dan lantai perahu mengembang dan terbentuk. . Pengisian tabung');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9014, 'Motor trail berfungsi untuk memantauan kejadian bencana sekaligus untuk kaji cepat ke lokasi bencana yang sulit dijangkau oleh kendaraan roda empat.
3. Pemeliharaan:
Perawatan Motor Trail sesuai dengan standar pabrikan dan pemasan mobil minimal dua hari sekali, serta pengecekan peralatan pendukung.
J. Perahu Karet Tanpa Mesin (Rubber Boat)
1. Pengertian Perahu Karet Tanpa mesin (Rubber Boat) adalah perahu yang berbahan dasar dari karet dan sejenisnya yang berisi udara (Pending)
2. Fungsi dan Penggunaan Perahu Karet Tanpa Mesin (Rubber Boat):
Perahu karet adalah alat angkut yang berfungsi untuk Evakuasi korban di air.
Penggunaannya:
H.Pemasangan deck Pemasangan deck untuk setiap ukuran sama, berikut pemasangan deck yang benar : -Masukkan deck nomor 1 ke bagian depan lantai perahu dan masukkan deck nomor 4 ke bagian belakang lantai perahu sampai tertahan oleh kuncian dek di transom.
2725 77 2015, No.822
- Masukkan deck nomor 2 di antara deck nomor 1 dan nomor 3, dan ditekan kebawah sampai rata.
- Kemudian pasang stringer ke samping deck lantai yang sudah tertata rapi, lalu dorong stringer ke arah dalam perahu sampai benar-benar terkunci.
- Setelah pemasangan selesai, pompalah badan perahu sesuai tekanan angin yang direkomendasikan. -Jika badan sudah terpompa, kemudian dilanjutkan dengan pemompaan keel hingga badan perahu terangkat dan lantai perahu mengembang dan terbentuk. . Pengisian tabung', 'Lampiran hal. 76', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9015, 'perka-7-2013', 81, 'lampiran', 'Lampiran hal. 77', NULL, 77, '- Atur semua posisi valve untuk pengisian tekanan udara. -Untuk hasil terbaik, pompa kaki harus berada di atas permukaan yang rata. Untuk pengisian tabung, beri tekanan udara dari pompa dengan cepat tetapi lembut.
- JANGAN GUNAKAN kompresor udara untuk lebih amannya gunakan blower.
- Tabung akan mengembang dengan tekanan udara sebesar 0.2 bar/ 3.0 PSI.
- Pompa tabung perahu dengan benar sampai dinding pemisah/sekat terlihat rata. Pemompaan harus seimbang dari bagian depan hingga bagian belakang.
Catatan :
- Temperatur udara sekitar sangat berpengaruh pada tekanan dalam perahu. -Jika terjadi perubahan temperatur yang drastis, periksa dan sesuaikan tekanan tabung sesuai dengan tekanan yang dianjurkan antara 0.17 bar/ 2,5 PSI hingga 0.22 bar/ 3,5 PSI.
- Tekanan udara yang berlebihan dapat menyebabkan tabung perahu pecah.
2015, No.822 78 J. Penyimpanan Melipat perahu
- Kosongkan perahu dari semua air dan pasir dengan membuka drain plug, lalu biarkan kering.
- Kempiskan perahu, kemudian letakkan perahu di lantai.
- Lipat perahu ke tengah perahu hingga selebar transom. -Lipat perahu dengan cara menggulungnya dari depan. Hal ini membantu untuk mengeluarkan udara. Pastikan semua katup berada di posisi terbuka.
- Setelah dilipat dengan baik, simpan perahu dan perlengkapannya pada tempatnya.
3. Cara pemeliharaan perahu karet adalah sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9015, '- Atur semua posisi valve untuk pengisian tekanan udara. -Untuk hasil terbaik, pompa kaki harus berada di atas permukaan yang rata. Untuk pengisian tabung, beri tekanan udara dari pompa dengan cepat tetapi lembut.
