INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9019, 'perka-7-2013', 85, 'lampiran', 'Lampiran hal. 81', NULL, 81, '- Bila tetap berbunyi, periksa pendingin mesin dan coba beri lem besi pada pax yang mengalami kebocoran oli.
- Cuci mesin dengan detergen setelah digunakan (tunggu mesin dingin terlebih dahulu) lalu dibilas dengan air bersih.
- Setelah dicuci, semprot body mesin dengan solar # oli (jangan dilap, biarkan begitu saja)
- Tutup body mesin dengan terpal atau bahan anti air, utk melindungi korosi hawa laut setelah disemprot oli.
- Panaskan mesin bila perahu tidak dipakai min 2-3 hari sekali.
- Ganti oli/tap oli sesuai anjuran mesin.
2015, No.822 82 BAB III HUNIAN DAN PERALATAN PENDUKUNG Hunian Sementara adalah tempat tinggal sementara selama korban bencana mengungsi, baik berupa tempat penampungan massal maupun keluarga atau individual. Bantuan peralatan hunian sementara diberikan dalam bentuk tenda dan alat pendukung lainnya.Berikut adalah beberapa peralatan yang berfungsi sebagai hunian sementara:
I. Hunian A. Tenda Posko Pengertian : digunakan sebagai tempat administrasi darurat untuk komando dengan ukuran (6 X 12 M2).
Fungsi : sebagai pengganti kantor sementara yang mengurusi bencana 1) Penggunaan Tenda Posko a) Material tenda posko terbagi dalam 4 (empat) peti yaitu: 1. Tiang utama, 2. Tiang penghubung, 3. Konektor (palu dan patok), 4. Daun tenda. dan harus di pasang berkisar 12 orang, adapun cara pemasangannya adalah sebagai berikut :
(1) Buka masing-masing peti.
(2) Lihat buku petunjuk tahapan tenda yang ada dalam peti.
(3) Keluarkan pipa-pipa kerangka tenda.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9019, '- Bila tetap berbunyi, periksa pendingin mesin dan coba beri lem besi pada pax yang mengalami kebocoran oli.
- Cuci mesin dengan detergen setelah digunakan (tunggu mesin dingin terlebih dahulu) lalu dibilas dengan air bersih.
- Setelah dicuci, semprot body mesin dengan solar # oli (jangan dilap, biarkan begitu saja)
- Tutup body mesin dengan terpal atau bahan anti air, utk melindungi korosi hawa laut setelah disemprot oli.
