INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9022, 'perka-7-2013', 88, 'lampiran', 'Lampiran hal. 84', NULL, 84, 'Fungsi : sebagai hunian tempat penampungan masal, tempat tinggal sementara pada korban bencana.
1) Penggunaan Tenda Peleton a.Material tenda Peleton terbagi dalam 4 (empat) peti dan harus di pasang berkisar 12 orang, adapun cara pemasangannya adalah sebagai berikut :
(1) Buka masing-masing peti.
(2) Lihat buku petunjuk tahapan tenda yang ada dalam peti.
(3) Keluarkan pipa-pipa kerangka tenda.
(4) Cek kelengkapan komponen tenda.
(5) Siapkan daun tenda.
(6) Bentangkan daun tenda dengan menarik keempat sudut daun tenda.
(7) Rapikan tenda dengan melipat dinding tenda kearah dalam.
(8) Pasang 4 tiang utama dengan 3 pipa penghubung dan kaitkan ke 4 buah.
(9) lubang di bagian atap tenda.
(10) Pastikan rangkaian tiang utama dengan pipa penghubung terpasang dengan benar.
(11) Lipat sisi sebelah daun tenda kearah bagian tiang.
(12) Kaitkan ujung tali tiang utama (ukr 10mm) sebanyak 10 buah ke masing- masing tiang utama, tiang utama pinggir masing-masing 3 tali dan tiang utama tengah 2 tali.
(13) Pastikan tali terpasang dengan kuat dan sempurna.
(14) Lepas ikatan tali yang terpasang pada ventilasi atap.
(15) Siapkan 4 orang untuk menarik tali yang terikat di tiang utama dan 4 orang untuk menahan di sisi lain hingga berdiri tegak.
(16) Pasang patok disesuaikan dengan bentangan tali tiang utama.
(17) Pasang tali tiang utama ke patok tenda sisi sebelahnya.
(18) Pasang seluruh tali tiang utama dengan sempurna (sebanyak 10 buah).
(19) Pasang semua tiang samping yang sejajar tiang utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9022, 'Fungsi : sebagai hunian tempat penampungan masal, tempat tinggal sementara pada korban bencana.
1) Penggunaan Tenda Peleton a.Material tenda Peleton terbagi dalam 4 (empat) peti dan harus di pasang berkisar 12 orang, adapun cara pemasangannya adalah sebagai berikut :
(1) Buka masing-masing peti.
(2) Lihat buku petunjuk tahapan tenda yang ada dalam peti.
(3) Keluarkan pipa-pipa kerangka tenda.
(4) Cek kelengkapan komponen tenda.
(5) Siapkan daun tenda.
(6) Bentangkan daun tenda dengan menarik keempat sudut daun tenda.
(7) Rapikan tenda dengan melipat dinding tenda kearah dalam.
(8) Pasang 4 tiang utama dengan 3 pipa penghubung dan kaitkan ke 4 buah.
(9) lubang di bagian atap tenda.
(10) Pastikan rangkaian tiang utama dengan pipa penghubung terpasang dengan benar.
(11) Lipat sisi sebelah daun tenda kearah bagian tiang.
(12) Kaitkan ujung tali tiang utama (ukr 10mm) sebanyak 10 buah ke masing- masing tiang utama, tiang utama pinggir masing-masing 3 tali dan tiang utama tengah 2 tali.
(13) Pastikan tali terpasang dengan kuat dan sempurna.
(14) Lepas ikatan tali yang terpasang pada ventilasi atap.
(15) Siapkan 4 orang untuk menarik tali yang terikat di tiang utama dan 4 orang untuk menahan di sisi lain hingga berdiri tegak.
(16) Pasang patok disesuaikan dengan bentangan tali tiang utama.
(17) Pasang tali tiang utama ke patok tenda sisi sebelahnya.
(18) Pasang seluruh tali tiang utama dengan sempurna (sebanyak 10 buah).
(19) Pasang semua tiang samping yang sejajar tiang utama.', 'Lampiran hal. 84', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9023, 'perka-7-2013', 89, 'lampiran', 'Lampiran hal. 84', NULL, 84, '(20) Ikat masing-masing tiang samping dengan tali tiang samping (ukr. 6Emm) Ke patok tenda.
(21) Stel tegangan ikatan tali ke patok sampai dinding terpasang lurus dan sejajar. Demikian juga berturut turut pemasangan dinding samping sebelahnya.
85 2015, No.822
(22) Pasang tali dinding dengan mengikat ke tiang samping dan lubang logam ring dinding tenda.
(23) Jika di perlukan gulung penutup jendela tenda.
(24) Pasang alas tenda (karpet).
b. Adapun cara pembongkarannya adalah sebagai berikut :
(1) Lepaskan tiang samping di seluruh sisi tenda.
(2) Lepaskan tali tiang utama dari pathok besi.
(3) Turunkan tiang utama ke satu sisi secara perlahan dan bersamaan.
(4) Lepaskan tali tiang utama.
(5) Keluarkan tiang utama dari daun tenda.
(6) Kelompokkan tiang sesuai dengan jenis dan ukurannya.
(7) Bentangkan,lipat serta letakan kain sekat ruangan sebelum digulung dengan rapi.
(8) Letakkan daun tenda pada pembungkus daun tenda yang telah disediakan lalu diikat serta dirapikan.
(9) Masukkan seluruh komponen ke dalam peti.
(10) Tutup kembali masing-masing peti.
C. Tenda Regu (8 X4”2 M2) Pemasangan dan pembongkaran tenda regu memiliki kesamaan dengan tenda peleton. Perbedaan hanya pada ukuran tenda regu lebih kecil.
Pengertian : digunakan sebagai tempat penampungan darurat dengan ukuran (8 X4”: M2?) yang dapat di huni oleh 15 orang (ukuran Velbed).
Fungsi : sebagai hunian tempat penampungan masal, tempat tinggal sementara pada korban bencana.');
