INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9024, 'perka-7-2013', 90, 'lampiran', 'Lampiran hal. 85', NULL, 85, 'D. Tenda Keluarga (4X4M?) Penggunaan dan Pemeliharaan Tenda Keluarga:
Pengertian : digunakan sebagai tempat penampungan darurat dengan ukuran (4X 4 M? ) yang dapat di huni oleh 4 orang (ukuran Velbed).
Fungsi : sebagai hunian tempat penampungan masal, tempat tinggal sementara pada korban bencana.
Persiapan pemasangan tenda keluarga
(1) Buka masing-masing peti.
(2) Lihat buku petunjuk tahapan tenda yang ada dalam peti.
(3) Keluarkan pipa-pipa kerangka tenda.
(4) Cek kelengkapan komponen tenda.
(5) Siapkan rangkaian kerangka atap tenda.
2015, No.822 86
(6) Pasang konstruksi kerangka atap tenda bagian atas (bubungan rangka atap).
(7) Pastikan pemasangan bubungan rangka atap dengan benar.
(8) Rangkai pipa bubungan rangka atap yang sudah terpasang dengan pipa kerucut atap di kedua sisi kanan dan kiri.
(9) Siapkan rangkaian kerangka atap tenda.
(10) Pasang pipa penghubung tiang tenda.
(11) Pasang konektor pipa penguat di bubungan rangka atap dengan pipa penguat atap.
(12) Pastikan kerangka atap terpasang sempurna.
(13) Buka daun tenda disisi kerangka atap yang terpasang.
(14) Pasangkan daun tenda hingga menutup atap dengan sempurna.
(15) Siapkan rangkaian tiang-tiang dinding tenda.
(16) Pasangkan tiang utama (dinding) dengan pipa konektor rangka atap tenda secara bersama-sama untuk kedua sisi tenda secara bergantian.
(17) Pasang tiang utama dengan konektor landasan dan pipa penghubung landasan dengan kokoh.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9024, 'D. Tenda Keluarga (4X4M?) Penggunaan dan Pemeliharaan Tenda Keluarga:
