INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9026, 'perka-7-2013', 92, 'lampiran', 'Lampiran hal. 87', NULL, 87, '2. Tenda kamar bedah / kebidanan, fungsi tindakan operasi dan persalinan
3. Tenda perawatan, fungsi perawatan umum dan semi intensif.
Syarat pemasangan tenda Rumah Sakit Lapangan:
a. Jika fasilitas pelayanan kesehatan lumpuh di area bencana,
b. Jauh, tidak ada pusat sarana pelayanan kesehatan,
c. Perhatikan kondisi tanah rata,
d. Lahan harus bersih dari benda tajam, kerikil dan batu,
e. Dekat dengan sumber air bersih,
f. Ada akses ambulan,
g. Ukuran standart area 40 X 45 M2, jika tidak ada area seluas area yang dibutuhkan minimal 10 X 20 M2 untuk mendirikan tenda UGD dan Kamar Operasi,
h. Pendirian 1 unit tenda di pasang oleh 6 orang.
Petunjuk pendirian Tenda Rumah Sakit Lapangan:
1. Siapkan box tenda sesuai dengan yang ingin didirikan ( perhatikan kegunaan tenda pada list yang tertera pada box), lihat denah rumah sakit lapangan pada lampiran.
2. Buka box tenda dan keluarkan semua item yang ada di dalam box (perhatikan list yang ada pada box).
3. Buka sabuk pengikat tenda, dan keluarkan tenda dari bungkus tenda.
4. Untuk tenda kamar operasi sebelum merentangkan / mendirikan tenda, harap dipasang leveling tile (alas untuk meratakan tenda) pada tempat yang ingin didirikan.
5. Rentangkan tenda pada lokasi yang ingin didirikan.
6. Persiapkan elektrik inflator (pompa angin/udara), dan sambungkan elektrik inflator pada sumber listrik / genset.
7. Pasang selang pengisi udara dari elektrik inflator ke 4 pentil tenda.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9026, '2. Tenda kamar bedah / kebidanan, fungsi tindakan operasi dan persalinan
3. Tenda perawatan, fungsi perawatan umum dan semi intensif.
Syarat pemasangan tenda Rumah Sakit Lapangan:
a. Jika fasilitas pelayanan kesehatan lumpuh di area bencana,
b. Jauh, tidak ada pusat sarana pelayanan kesehatan,
c. Perhatikan kondisi tanah rata,
d. Lahan harus bersih dari benda tajam, kerikil dan batu,
e. Dekat dengan sumber air bersih,
f. Ada akses ambulan,
g. Ukuran standart area 40 X 45 M2, jika tidak ada area seluas area yang dibutuhkan minimal 10 X 20 M2 untuk mendirikan tenda UGD dan Kamar Operasi,
h. Pendirian 1 unit tenda di pasang oleh 6 orang.
Petunjuk pendirian Tenda Rumah Sakit Lapangan:
1. Siapkan box tenda sesuai dengan yang ingin didirikan ( perhatikan kegunaan tenda pada list yang tertera pada box), lihat denah rumah sakit lapangan pada lampiran.
2. Buka box tenda dan keluarkan semua item yang ada di dalam box (perhatikan list yang ada pada box).
3. Buka sabuk pengikat tenda, dan keluarkan tenda dari bungkus tenda.
4. Untuk tenda kamar operasi sebelum merentangkan / mendirikan tenda, harap dipasang leveling tile (alas untuk meratakan tenda) pada tempat yang ingin didirikan.
5. Rentangkan tenda pada lokasi yang ingin didirikan.
6. Persiapkan elektrik inflator (pompa angin/udara), dan sambungkan elektrik inflator pada sumber listrik / genset.
7. Pasang selang pengisi udara dari elektrik inflator ke 4 pentil tenda.', 'Lampiran hal. 87', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9027, 'perka-7-2013', 93, 'lampiran', 'Lampiran hal. 87', NULL, 87, '8. Pasang selang pengatur tekanan otomatis tenda dari elektrik inflator ke sisi tenda bagian dalam (pintu samping tenda).
9. Tekan saklar on pada elektrik inflator dan atur tombol ke posisi Auto untuk pengaturan tekanan tenda secara otomatis, maka electrik inflator akan otomatis berhenti meniup udara ketika tekanan tenda telah mencapai 28 dan akan menyala otomatis ketika tekanan pada posisi 18.
2015, No.822 28
10. Setelah tenda berdiri, pasang patok tenda pada tali yang telah tersedia, dan tancapkan pada tanah.
11. Pasang innersheet (kain flafon) tenda bagian dalam untuk masing-masing tenda.
12. Tenda TAG 29 (5,6 X 5,15 M2) terdiri dari :
a. 1 set innersheet 19402621
b. 1 set innersheet 19402623
13. Tenda TAG 42 (7,55 X 5,6 M2) terdiri dari :
a. 1 set innersheet 19402611
b. 2 set innersheet 19402623
c. 1 set innersheet 19407295
14. Pasang spacing bar (tiang penyangga antar kolom) pada tenda.
15. Pasang elektric system (lampu utama, lampu emergensi, lampu koridor, stop kontak) pada tenda.
16. Pasang enterence module ( pintu masuk) pada tenda.
17. Pasang joining coridor untuk penghubung dengan tenda lainnya.
18. Masukkan peralatan medis kedalam tenda sesuai dengan peruntukan tenda ( lihat list peralatan medis masing-masing tenda ), lihat lampiran alat terlampir.
Cara Pembongkaran, Pemeliharaan dan Penyimpanan Tenda Rumah Sakit Lapangan :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9027, '8. Pasang selang pengatur tekanan otomatis tenda dari elektrik inflator ke sisi tenda bagian dalam (pintu samping tenda).
9. Tekan saklar on pada elektrik inflator dan atur tombol ke posisi Auto untuk pengaturan tekanan tenda secara otomatis, maka electrik inflator akan otomatis berhenti meniup udara ketika tekanan tenda telah mencapai 28 dan akan menyala otomatis ketika tekanan pada posisi 18.
2015, No.822 28
10. Setelah tenda berdiri, pasang patok tenda pada tali yang telah tersedia, dan tancapkan pada tanah.
