INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9033, 'perka-7-2013', 99, 'lampiran', 'Lampiran hal. 92', NULL, 92, 'c. Lensa depan terbuat dari kaca yang khusus, pastikan agar tidak pecah. Jika pecah, maka harus segera diganti secepatnya.
d. Pastikan segel kedap air ditutup rapat dengan baik.
e. Pastikan untuk mengikuti instruksi yang ada pada saat membuka dan mengganti baterai.
f. Jangan pernah menggunakan minyak sejenis jelly (vaselin) pada segel karena itu akan menurunkan fungsi kerjanya.
g. Jika ada masalah dengan tingkat penerangannya, segera hubungi penyedia/pabrik yang mengeluarkan peralatan ini, jangan melakukan perbaikan apapun untuk penerangan cahaya.
h. PERINGATAN, jangan mengarahkan caraha ke mata seseorang dalam jarak dekat.
D. Alat Penjernih Air (Water Treatment Portable) Pengertian: merupakan mesin pengolah air langsung minum yang dapat membuang polutan-polutan berbahaya didalam air PAM atau air sumur (jangan digunakan untuk air laut atau air panas) seperti logam-logam berat, pestisida, racun-racun, zat kimia, partikel-partikel radio aktif, bakteri, virus, garam, endapan dsb.
Fungsi:
Sistem Air Bersih dan Air Minum Teknologi di rancang khusus berdasarkan pengalaman kami dalam melakukan instalasi dengan Sistem RO yang menggunakan filter2 yang bisa memproses kemurnian air dari yang paling kasar hingga sistem setirilisasi bakteri yang berlapis adapun tahapannya.
93 2015, No.822 Menyaring partikel yang besar seperti : kotoran, lumpur, pasir, debu, karat, bahan kapur,dan menggunakakan sistem steirilisasi.
Tahapan Filter RO air secara umum antara lain :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9033, 'c. Lensa depan terbuat dari kaca yang khusus, pastikan agar tidak pecah. Jika pecah, maka harus segera diganti secepatnya.
d. Pastikan segel kedap air ditutup rapat dengan baik.
e. Pastikan untuk mengikuti instruksi yang ada pada saat membuka dan mengganti baterai.
