INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9039, 'perka-7-2013', 105, 'lampiran', 'Lampiran hal. 100', NULL, 100, 'Catridge 2, CTO Actived Carbon, berfungsi Menyerap (absorb) warna, bau, rasa dan juga menyaring kotoran 20.5 mikron Spesifikasi produk : Catridge size 20”, daya saring 0.5 mikro meter, BL Catridge 3, Sedimen 0.1 mikron, berfungsi menyaring kotoran dengan ukuran » 0.1 £. mikron Spesifikasi produk : Catridge dengan daya saring 0.1 mikro meter, 101 2015, No.822 V .i .TABUNG PENAMPUNGAN AIR HASIL PROSES REVERSE OSMOSIS.
