INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9041, 'perka-7-2013', 107, 'lampiran', 'Lampiran hal. 103', NULL, 103, '6) Tanda VOX'' akan muncul jika fungsi VOX tersedia.
7) Tanda KEY” menunjukkan bahwa tombol berada dalam keadaan terkunci.
8) Jika KEY berfungsi maka tombol PTT tidak berfungsi.
9) Jika tombol dalam keadaan terkunci maka PTT akan berfungsi.
c. Putar tombol “Power/ Volume” berlawanan arah jarum jam untuk mematikan radio. Tombol ini juga berfungsi untuk menaikkan (searah jarum jam) atau menurunkan (berlawanan arah jarum jam) volume suara. . Pemeliharan Seperti kebanyakan alat elektronik, radio komunikasi (HT/Rig) mempunyai komponen-komponen yang membutuhkan perlakuan khusus. Musuh utamanya adalah arus listrik, air dan kelembaban. Beberapa HT/RIG mempunyai fitur waterproof (tahan air), dustproof (tahan debu), shockproof (tahan goncangan) dan bahkan submersible (tahan direndam sampai beberapa menit pada kedalaman 1 meter).
Untuk menjamin operasional HT/RIG secara maksimal, ada beberapa hal yang perlu diperhatikan:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9041, '6) Tanda VOX'' akan muncul jika fungsi VOX tersedia.
7) Tanda KEY” menunjukkan bahwa tombol berada dalam keadaan terkunci.
8) Jika KEY berfungsi maka tombol PTT tidak berfungsi.
9) Jika tombol dalam keadaan terkunci maka PTT akan berfungsi.
c. Putar tombol “Power/ Volume” berlawanan arah jarum jam untuk mematikan radio. Tombol ini juga berfungsi untuk menaikkan (searah jarum jam) atau menurunkan (berlawanan arah jarum jam) volume suara. . Pemeliharan Seperti kebanyakan alat elektronik, radio komunikasi (HT/Rig) mempunyai komponen-komponen yang membutuhkan perlakuan khusus. Musuh utamanya adalah arus listrik, air dan kelembaban. Beberapa HT/RIG mempunyai fitur waterproof (tahan air), dustproof (tahan debu), shockproof (tahan goncangan) dan bahkan submersible (tahan direndam sampai beberapa menit pada kedalaman 1 meter).
Untuk menjamin operasional HT/RIG secara maksimal, ada beberapa hal yang perlu diperhatikan:', 'Lampiran hal. 103', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9042, 'perka-7-2013', 108, 'lampiran', 'Lampiran hal. 103', NULL, 103, 'a. Catu daya Pastikan pasokan catu daya, baik HT maupun Rig, terjaga kestabilannya, dan sesuai dengan spesifikasi yang dibutuhkan. Khusus untuk HT, saat ini ada dua jenis baterai yang digunakan: Lithium dan NiIMH. Kedua baterai ini sudah tidak mempunyai efek memory sehingga tidak harus menunggu sampai bebar-benar habis unutk proses charging atau pengisiannya, tidak seperti baterai tipe NiCD. Untuk Rig, usahakan agar catu daya tidak melebih spesifikasi yang ditentukan (standar voltase untuk Rig biasanya 13,8V). Jika tidak, maka usia final power akan lebih pendek karena panas yang dihasilkan apabila voltase catu daya terlalu tinggi.
Khusus untuk HT, beberapa tipe HT sangat sensitif terhadap daya.
Sebisa mungkin usahakan agar jangan sampai unit HT digunakan untuk transmit apabila kondisi baterai sudah benar-benar low, karena pada beberapa kasus, seringkali saat transmit dan kemudian unit HT mati karena habis baterainya, maka ini akan menyebabkan memory / ROM pada HT akan menjadi kacau (kasus yang sudah pernah adalah pada unit Alinco DJ-180).
2015, No.822 104
b. Air Seperti halnya semua alat elektronik lainnya, air adalah musuh utama.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9042, 'a. Catu daya Pastikan pasokan catu daya, baik HT maupun Rig, terjaga kestabilannya, dan sesuai dengan spesifikasi yang dibutuhkan. Khusus untuk HT, saat ini ada dua jenis baterai yang digunakan: Lithium dan NiIMH. Kedua baterai ini sudah tidak mempunyai efek memory sehingga tidak harus menunggu sampai bebar-benar habis unutk proses charging atau pengisiannya, tidak seperti baterai tipe NiCD. Untuk Rig, usahakan agar catu daya tidak melebih spesifikasi yang ditentukan (standar voltase untuk Rig biasanya 13,8V). Jika tidak, maka usia final power akan lebih pendek karena panas yang dihasilkan apabila voltase catu daya terlalu tinggi.
Khusus untuk HT, beberapa tipe HT sangat sensitif terhadap daya.
Sebisa mungkin usahakan agar jangan sampai unit HT digunakan untuk transmit apabila kondisi baterai sudah benar-benar low, karena pada beberapa kasus, seringkali saat transmit dan kemudian unit HT mati karena habis baterainya, maka ini akan menyebabkan memory / ROM pada HT akan menjadi kacau (kasus yang sudah pernah adalah pada unit Alinco DJ-180).
2015, No.822 104
b. Air Seperti halnya semua alat elektronik lainnya, air adalah musuh utama.', 'Lampiran hal. 103', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9043, 'perka-7-2013', 109, 'lampiran', 'Lampiran hal. 104', NULL, 104, 'Bukan karena sifatnya yang merusak seperti air asam atau air keras, namun air adalah konduktor listrik paling bagus sehingga, apabila unit HT/Rig sampai terkena air, terutama bagian dalamnya, maka dijamin akan langsung berasap atau terbakar akibat korsleting yang terjadi pada sirkuit. Namun demikian, ada beberapa unit RIG/HT yang memiliki fitur tahan air dan bahkan tahan celup. Contoh Rig yang tahan air antara lain Yaesu FTM-10R, dan untuk HT yang tahan air antara lain Icom IC-V80, Yaesu FT-270R, FT-250R dan untuk yang tahan celup antara lain Yaesu VX7R, VX8R, dan FT-270R. Untuk unit yang tidak memiliki fitur di atas, maka bisa menggunakan kantung plastik 1 kg untuk membungkus HT saat kondisi hujan dan HT masih bisa digunakan dengan sempurna.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9043, 'Bukan karena sifatnya yang merusak seperti air asam atau air keras, namun air adalah konduktor listrik paling bagus sehingga, apabila unit HT/Rig sampai terkena air, terutama bagian dalamnya, maka dijamin akan langsung berasap atau terbakar akibat korsleting yang terjadi pada sirkuit. Namun demikian, ada beberapa unit RIG/HT yang memiliki fitur tahan air dan bahkan tahan celup. Contoh Rig yang tahan air antara lain Yaesu FTM-10R, dan untuk HT yang tahan air antara lain Icom IC-V80, Yaesu FT-270R, FT-250R dan untuk yang tahan celup antara lain Yaesu VX7R, VX8R, dan FT-270R. Untuk unit yang tidak memiliki fitur di atas, maka bisa menggunakan kantung plastik 1 kg untuk membungkus HT saat kondisi hujan dan HT masih bisa digunakan dengan sempurna.', 'Lampiran hal. 104', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9044, 'perka-7-2013', 110, 'lampiran', 'Lampiran hal. 104', NULL, 104, 'c. Kelembaban Kelembaban erat kaitannya dengan air. Saat terjadi kelembaban, maka yang muncul adalah munculnya butiran-butiran air yang juga bisa menjadi konduktor sehingga menyebabkan korsleting. Selain itu, kelembaban juga menyebabkan munculnya jamur pada batre, dan juga sirkuit. Akibatnya, juga sama, fungsi sirkuit jadi terganggu dan kemungkinan juga terjadi korsleting. Untuk menghindari terjadinya hal ini, usahakan agar penyimpanan HT/RIG, terutama yang tidak sering digunakan, bebar-benar mempertimbangkan faktor kelembaban relatif dan/atau suhu ruangan. Jika memungkinkan, simpan HT/RIG menggunakan dry cabinet yang memiliki kontrol suhu/kelembaban. Jika tidak memungkinkan, biarkan di ruangan terbuka dan nyalakan perangkat minimal 2 minggu sekali untuk memanaskan bagian sirkuit.
d. Petunjuk Praktis Penggunaan di Lapangan :
1). Baterai a) Bersihkan baterai dengan kain yang bersih dan tidak berserat untuk menghilangkan kotoran, minyak atau bahan lain. Hal ini untuk mencegah kontak listrik. b) Jika kontak sangat kotor, bisa dibersihkan dengan penghapus pensil (karet), jangan memakai penghapus tinta. c) Jangan menggunakan cairan, alkohol atau pembersih aerosol.
2). Konektor a) Harus ditutup dengan alat penutupnya jika tidak dipakai. b) Pakai alat penutup yang sesuai untuk menutup konektor.
3). Pengisian baterai a) Pastikan radio dalam keadaan mati (off). b) Untuk mengisi baterai diperlukan waktu 8 jam. c) Jangan dicabut sebelum baterai terisi penuh.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9044, 'c. Kelembaban Kelembaban erat kaitannya dengan air. Saat terjadi kelembaban, maka yang muncul adalah munculnya butiran-butiran air yang juga bisa menjadi konduktor sehingga menyebabkan korsleting. Selain itu, kelembaban juga menyebabkan munculnya jamur pada batre, dan juga sirkuit. Akibatnya, juga sama, fungsi sirkuit jadi terganggu dan kemungkinan juga terjadi korsleting. Untuk menghindari terjadinya hal ini, usahakan agar penyimpanan HT/RIG, terutama yang tidak sering digunakan, bebar-benar mempertimbangkan faktor kelembaban relatif dan/atau suhu ruangan. Jika memungkinkan, simpan HT/RIG menggunakan dry cabinet yang memiliki kontrol suhu/kelembaban. Jika tidak memungkinkan, biarkan di ruangan terbuka dan nyalakan perangkat minimal 2 minggu sekali untuk memanaskan bagian sirkuit.
d. Petunjuk Praktis Penggunaan di Lapangan :
1). Baterai a) Bersihkan baterai dengan kain yang bersih dan tidak berserat untuk menghilangkan kotoran, minyak atau bahan lain. Hal ini untuk mencegah kontak listrik. b) Jika kontak sangat kotor, bisa dibersihkan dengan penghapus pensil (karet), jangan memakai penghapus tinta. c) Jangan menggunakan cairan, alkohol atau pembersih aerosol.
2). Konektor a) Harus ditutup dengan alat penutupnya jika tidak dipakai. b) Pakai alat penutup yang sesuai untuk menutup konektor.
3). Pengisian baterai a) Pastikan radio dalam keadaan mati (off). b) Untuk mengisi baterai diperlukan waktu 8 jam. c) Jangan dicabut sebelum baterai terisi penuh.', 'Lampiran hal. 104', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9045, 'perka-7-2013', 111, 'lampiran', 'Lampiran hal. 105', NULL, 105, '105 2015, No.822 d) Jangan memotong terminal baterai karena bisa menimbulkan kebakaran/api dan ledakan. e) Jangan membuang baterai yang rusak ke dalam api karena akan menimbulkan ledakan, ikuti petunjuk yang ada. ) Untuk menghindari kerusakan kabel daya dari pengisi daya baterai, jangan memasukkan apapun di atasnya. Masukkan steker ke soket yang disediakan dan menyentuh tanah.
B. RIG RIG merupakan radio komunikasi yang tidak dapat dibawa-bawa, namun dapat ditempatkan di suatu ruangan atau di mobil.
1. Fungsi
a. RIG VHF Rig VHF memiliki frekuensi yang sama dengan HT, tetapi yang membedakannya adalah daya pancar yang dimilikinya, yaitu berkisar antara 30 Watt sampai dengan 100 Watt. Daya pancar sebesar ini membuat jarak jangkauan pancar rig ini bisa mencapai 50 km line-of-sight.
b. RIG HF (HF MobileTranceiver) Rig HF bekerja pada frekuensi HF (atau bagi orang awam sering dikenal sebagai SW). Dengan daya 50 Watt sampai dengan 250 Watt, rig ini dapat digunakan komunikasi 500 sampai dengan ribuan km.
Masalah utama di frekuensi HF adalah tinggi-nya noise sehingga diperlukan teknik dan kesabaran yang lebih tinggi untuk komunikasi data / internet.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9045, '105 2015, No.822 d) Jangan memotong terminal baterai karena bisa menimbulkan kebakaran/api dan ledakan. e) Jangan membuang baterai yang rusak ke dalam api karena akan menimbulkan ledakan, ikuti petunjuk yang ada. ) Untuk menghindari kerusakan kabel daya dari pengisi daya baterai, jangan memasukkan apapun di atasnya. Masukkan steker ke soket yang disediakan dan menyentuh tanah.
B. RIG RIG merupakan radio komunikasi yang tidak dapat dibawa-bawa, namun dapat ditempatkan di suatu ruangan atau di mobil.
1. Fungsi
a. RIG VHF Rig VHF memiliki frekuensi yang sama dengan HT, tetapi yang membedakannya adalah daya pancar yang dimilikinya, yaitu berkisar antara 30 Watt sampai dengan 100 Watt. Daya pancar sebesar ini membuat jarak jangkauan pancar rig ini bisa mencapai 50 km line-of-sight.
b. RIG HF (HF MobileTranceiver) Rig HF bekerja pada frekuensi HF (atau bagi orang awam sering dikenal sebagai SW). Dengan daya 50 Watt sampai dengan 250 Watt, rig ini dapat digunakan komunikasi 500 sampai dengan ribuan km.
Masalah utama di frekuensi HF adalah tinggi-nya noise sehingga diperlukan teknik dan kesabaran yang lebih tinggi untuk komunikasi data / internet.', 'Lampiran hal. 105', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2013 tentang Petunjuk Pelaksanaan Penggunaan dan Pemeliharaan Peralatan Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9046, 'perka-7-2013', 112, 'lampiran', 'Lampiran hal. 105', NULL, 105, '2. Petunjuk Penggunaan RIG pada prinsipnya sama dengan HT. Ketika kita akan melakukan hubungan komunikasi pada suatu kegiatan terlebih dahulu diperhatikan kanal frekuensi yang digunakan kegiatan, untuk itu agar tidak terjadi penggunaan frekuensi yang sama serta pada wilayah yang sama pula maka libatkanlah organisasi komunikasi yang telah ditunjuk Pemerintah guna dapat memberikan saran dan arahan yang benar di dalam penggunaan kanal frekuensi. Sehingga tidak terkesan menggunakan frekuensi seenaknya saja, paling tidak dapat memberikan bimbingan tentang cara menggunakan frekuensi secara benar serta tidak merugikan pengguna frekuensi lain.
Petunjuk praktis cara penggunaan RIG sebagai berikut :
a. Pastikan perangkat komunikasi yang akan dipakai dalam kondisi baik dan siap on-line:
1) Antena telah terpasang 2) Baterai terpasang dan siap pakai 2015, No.822 106
b. Tentukan dan pastikan kanal frekuensi yang akan digunakan benar-benar kosong
c. Tentukan nama panggilan baik perseorangan maupun pada suatu kegiatan
d. Bawalah kelompok dan siapkan ATK sebelum kegiatan komunikasi dimulai
e. Persiapkan personil yang siap, tanggap dan bertanggung jawab
f. Selalu adakan koordinasi untuk menghindari salah komunikasi.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9046, '2. Petunjuk Penggunaan RIG pada prinsipnya sama dengan HT. Ketika kita akan melakukan hubungan komunikasi pada suatu kegiatan terlebih dahulu diperhatikan kanal frekuensi yang digunakan kegiatan, untuk itu agar tidak terjadi penggunaan frekuensi yang sama serta pada wilayah yang sama pula maka libatkanlah organisasi komunikasi yang telah ditunjuk Pemerintah guna dapat memberikan saran dan arahan yang benar di dalam penggunaan kanal frekuensi. Sehingga tidak terkesan menggunakan frekuensi seenaknya saja, paling tidak dapat memberikan bimbingan tentang cara menggunakan frekuensi secara benar serta tidak merugikan pengguna frekuensi lain.
Petunjuk praktis cara penggunaan RIG sebagai berikut :
