INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9053, 'perka-7-2013', 119, 'lampiran', 'Lampiran hal. 110', NULL, 110, '4. Tombol Kontrol ICLARITY) supaya dapat (CLARITYJ diputar | menerima audio dengan terlalu jauh. baik 3) Solusi Kerusakan pada bagian TRANSMIT Jenis Masalah Kemungkinan Penyebab Solusi kerusakan Jarak Jangkau 1.Antenna tuner tidak 1.Tekan tombol (TUNE) Sinyal ”Match” untuk Berkurang secara benar dengan menala/ tune Antenna frekuensi Operasi Tuner ketika atau pilih "Automatic melakukan manual Tuning” tuning pada saat melakukanSet 2.Mode CW atau FSK mode dipilih 2.Tekan tombol (MODE) untuk transmisi sinyal | untuk suara memilih mode USB (atau AM, R3E dil) Sinyal yang 1.Pemilihan mode 1.Tekan tombol /MODE) ditransmit tidak | operasi untuk bagus atau yang salah memilih mode operasi terdistorsi 2.Posisi Microphone yang terlalu benar dekat ke mulut 2.Posisi Microphine tidak terlalu dekat ke mulut 111 2015, No.822 4) Solusi Kerusakan pada bagian DISPLAY Jenis Masalah Kemungkinan Penyebab Solusi kerusakan Semua indikator | 1.Setting Kontras display | 1.Melakukan setting ON dan angka pada kontras Channel tidak posisi maksimum display secara benar dapat dibaca dalam set mode Lampiran : Gambaran umum, pengertian, bagian-bagian radio, dan spesifikasi teknis SSB A. Pengertian
1. Telekomunikasi adalah setiap pemancaran, pengiriman dan atau penerimaan dari setiap informasi dalam bentuk tanda-tanda,isyarat, tulisan, gambar, dan bunyi melalui sistem kawat, optik, radio atau sistem elektromagnetik lainnya.');
