INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9063, 'perka-7-2014', 1, 'menimbang', 'Menimbang', NULL, 2, 'a. bahwa dalam rangka meningkatkan pelayanan kepada masyarakat, mewujudkan sumber daya manusia yang kompeten, serta memberikan pengakuan dan penghargaan profesi di bidang Penanggulangan Bencana, dipandang perlu untuk membentuk Lembaga Sertifikasi Profesi Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9063, 'a. bahwa dalam rangka meningkatkan pelayanan kepada masyarakat, mewujudkan sumber daya manusia yang kompeten, serta memberikan pengakuan dan penghargaan profesi di bidang Penanggulangan Bencana, dipandang perlu untuk membentuk Lembaga Sertifikasi Profesi Penanggulangan Bencana;
b. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9064, 'perka-7-2014', 2, 'mengingat', 'Mengingat', NULL, 2, '1. Undang-Undang Nomor 13 Tahun 2003 tentang Ketenagakerjaan (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 39, Tambahan Lembaran Negara Republik Indonesia Nomor 4279);
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 23 Tahun 2004 tentt} Badan Nasional Sertifikasi Profesi (Lembaran Neg a Republik Indonesia Tahun 2004 Nomor I 8, Tambahan Lembaran Negara Republik Indonesia Nomor 4408); /
4. Peraturan Pemerintah Nomor 21 Tahun 2001tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
5. Peraturan Pemerintah Nomor 22 Tahun 2008 ten tang Pendanaan dan Pengelolaan Ban tuan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
6. Peraturan Pemerintah Nomor 23 Tahun 2008 tentang Peran serta Lembaga Internasional dan Lembaga Asing Non pemerintah dalam Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 44, Tambahan Lembaran Negara Republik Indonesia Nomor 4830);
7. Peraturan Presiden Nomor 8 Tahun 2008 ten tang Badan Nasional Penanggulangan Bencana;
8. Peraturan Menteri Tenaga Kerja dan Transrnigrasi Nomor 5 Tahun 2012 tentang Standar Kompetensi Kerja Nasional Indonesia (Berita Negara Republik Indonesia Tahun 2012 Nomor 338);
9. Peraturan Menteri Tenaga Kerja dan Transrnigrasi Nomor 8 Tahun 2012 ten tang Tata Cara Penetapan Standar Kompetensi Kerja Nasional Indonesia (Berita Negara Republik Indonesia Tahun 2012 Nomor 364);
10. Peraturan Kepala Badan Nasional Sertifikasi Profesi Nomor 01jBNSP.210jXj2013 tentang Pedoman Persyaratan Umum Pengembangan dan Pemeliharaan Sertifikasi Profesi;
11. Peraturan Kepala Badan Nasional Sertifikasi Profesi Nomor 06jBNSP.201jXIj2013 tentang Pedoman Penilaian Kesesuaian Persyaratan Umum Lembaga Sertifikasi Profesi;
12. Peraturan Kepala Badan Nasional Sertifikasi Profesi Nomor 07/BNSP.202/XI/2013 tentang Pedoman Pembentukan Lembaga Sertifikasi Profesi;
