INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9068, 'perka-7-2014', 6, 'pasal', 'Pasal 7', 'BAB II KEDUDUKAN', 6, 'Wewenang LSP PB memiliki kewenangan antara lain:
a. menetapkan biaya uji kompetensi;
