INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9069, 'perka-7-2014', 7, 'pasal', 'Pasal 9', 'BAB II KEDUDUKAN', 6, 'Susunan Organisasi LSP PB terdiri atas:
(1)Dewan Pengarah, terdiri dari:
a. Ketua;
b. Wakil Ketua;
c. Anggota.
(2)Pclaksana LSP PB, terdiri dari:
a. Ketua;
b. Wakil Ketua;
c. Sekretaris, yang membawahi:
