INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9070, 'perka-7-2014', 8, 'pasal', 'Pasal 10', 'BAB II KEDUDUKAN', 7, 'Dewan Pengarah
(1) Ketua Dewan Pengarah LSP PB adalah Kepala BNPB;
(2) Ketua Dewan Pengarah merangkap sebagai Anggota Dewan Pengarah;
(3) Ketua Dewan Pengarah mengangkat dan memberhentikan Anggota Dewan Pengarah, Ketua, Wakil Ketua, dan Sekretaris LSP PB;
(4) Anggota Dewan Pengarah LSP PB berjumlah 5 (lima) orang yang mewakili Pernerintah, Masyarakat dan LembagaJDunia Usaha;
(5) Dewan Pengarah menetapkan kebijakan lembaga yang mencakup:
a. visi, misi dan tujuan LSP PB;
b. rencana strategis, program kerja dan anggaran belanja;
c. menetapkan honorarium Dewan Pengarah dan Pelaksana LSP PB sesuai peraturan perundangan melalui Daftar Isian Pelaksanaan Anggaran BNPB;
d. membina komunikasi dengan para pemangku kepentingan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9070, 'Dewan Pengarah
(1) Ketua Dewan Pengarah LSP PB adalah Kepala BNPB;
(2) Ketua Dewan Pengarah merangkap sebagai Anggota Dewan Pengarah;
(3) Ketua Dewan Pengarah mengangkat dan memberhentikan Anggota Dewan Pengarah, Ketua, Wakil Ketua, dan Sekretaris LSP PB;
(4) Anggota Dewan Pengarah LSP PB berjumlah 5 (lima) orang yang mewakili Pernerintah, Masyarakat dan LembagaJDunia Usaha;
(5) Dewan Pengarah menetapkan kebijakan lembaga yang mencakup:
a. visi, misi dan tujuan LSP PB;
b. rencana strategis, program kerja dan anggaran belanja;
c. menetapkan honorarium Dewan Pengarah dan Pelaksana LSP PB sesuai peraturan perundangan melalui Daftar Isian Pelaksanaan Anggaran BNPB;
d. membina komunikasi dengan para pemangku kepentingan.', 'Pasal 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2014 tentang Lembaga Sertifikasi Profesi Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9071, 'perka-7-2014', 9, 'pasal', 'Pasal 11', 'BAB II KEDUDUKAN', 7, 'Pelaksana
(1) Ketua LSP PB mengangkat dan memberhentikan Kepala Bidarig, Kepala Bagian dan Tenaga Pendukung LSP PB.
(2) Ketua LSP PB dapat mendelegasikan sebagian kewenangannya kepada Pelaksana LSP PB di dalam tugas-tugasnya, termasuk tugas yang berkaitan dengan lembaga peradilan dan hukum.
(3) Pelaksana LSP PB adalah personil yang mempunyai sertifikat kompetensi.
(4) Pelaksana LSP PB dapat membentuk kelompok kerja sesuai dengan kebutuhan yang terdiri atas personil yang mempunyai kompetensi dan bersertifikat dalam bidang tugas yang diperlukan.
(5) Ketua LSP PB menyusun dan menetapkan Anggaran Dasar dan Anggaran Rumah Tangga.
(6) Pelaksana LSP PB melaksanakan Anggaran Dasar dan Anggaran Rumah Tangga.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9071, 'Pelaksana
