INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9073, 'perka-7-2014', 11, 'pasal', 'Pasal 14', 'BAB II KEDUDUKAN', 8, 'Peraturan Kepala BNPB ini mulai berlaku pada tanggal diundangkan.
