INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9077, 'perka-7-2015', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa ancaman bencana di wilayah Negara Kesatuan Republik Indonesia meliputi bahaya gempa bumi, tsunami, erupsi gunung api, gerakan tanah, banjir, dan kebakaran hutan dan lahan yang berpotensi terjadi bencana mengakibatkan timbulnya korban jiwa, kerusakan prasarana dan sarana serta kerugian harta benda;
b. bahwa untuk melindungi seluruh masyarakat di wilayah berpotensi timbulnya ancaman bencana perlu penyampaian informasi bencana melalui ketersediaan petunjuk yang standar berupa rambu dan papan informasi bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Rambu dan Papan Informasi Bencana;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9077, 'a. bahwa ancaman bencana di wilayah Negara Kesatuan Republik Indonesia meliputi bahaya gempa bumi, tsunami, erupsi gunung api, gerakan tanah, banjir, dan kebakaran hutan dan lahan yang berpotensi terjadi bencana mengakibatkan timbulnya korban jiwa, kerusakan prasarana dan sarana serta kerugian harta benda;
b. bahwa untuk melindungi seluruh masyarakat di wilayah berpotensi timbulnya ancaman bencana perlu penyampaian informasi bencana melalui ketersediaan petunjuk yang standar berupa rambu dan papan informasi bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Kepala Badan Nasional Penanggulangan Bencana tentang Rambu dan Papan Informasi Bencana;', 'Menimbang', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9078, 'perka-7-2015', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
