INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9085, 'perka-7-2015', 9, 'pasal', 'Pasal 8', 'BAB II RAMBU BENCANA; Bagian Kedua Ukuran, Warna, dan Bentuk Rambu', 5, '(1) Rambu Bencana sebagaimana dimaksud dalam Pasal 6 ayat (1) terdiri atas:
a. tiang rambu; dan
b. daun rambu.
(2) Tiang Rambu sebagaimana dimaksud pada ayat (1) huruf a dapat berupa tiang tunggal dan/atau tiang ganda.
(3) Daun rambu sebagaimana dimaksud pada ayat (1) huruf b berupa rambu ukuran kecil, sedang, besar, dan sangat besar.
(4) Ukuran daun rambu sebagaimana dimaksud pada ayat
(3) tercantum dalam Lampiran I yang merupakan bagian tidak terpisahkan dari peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9085, '(1) Rambu Bencana sebagaimana dimaksud dalam Pasal 6 ayat (1) terdiri atas:
a. tiang rambu; dan
