INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9087, 'perka-7-2015', 11, 'pasal', 'Pasal 10', 'BAB II RAMBU BENCANA; Bagian Kedua Ukuran, Warna, dan Bentuk Rambu', 6, '(1) Rambu peringatan bencana sebagaimana dimaksud dalam Pasal 6 ayat (1) huruf b memiliki warna dasar kuning, garis tepi hitam, lambang hitam, huruf dan angka hitam, dan tulisan hitam.
