INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9087, '(1) Rambu peringatan bencana sebagaimana dimaksud dalam Pasal 6 ayat (1) huruf b memiliki warna dasar kuning, garis tepi hitam, lambang hitam, huruf dan angka hitam, dan tulisan hitam.
(2) Bentuk, lambang, warna, dan arti rambu peringatan bencana sebagaimana dimaksud dalam Pasal 6 ayat (1) huruf b tercantum dalam Lampiran II yang merupakan bagian tidak terpisahkan dari peraturan ini.', 'Pasal 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9088, 'perka-7-2015', 12, 'pasal', 'Pasal 11', 'BAB III PAPAN TAMBAHAN', 6, '(1) Rambu larangan kebencanaan sebagaimana dimaksud dalam Pasal 6 ayat (1) huruf c memiliki warna dasar putih, garis tepi merah, lambang hitam, huruf dan/atau angka hitam, dan warna tulisan merah.
2015, No.2033
(2) Bentuk, lambang, warna, dan arti rambu larangan bencana sebagaimana dimaksud dalam Pasal 6 ayat (1) huruf c tercantum dalam Lampiran II yang merupakan bagian tidak terpisahkan dari peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9088, '(1) Rambu larangan kebencanaan sebagaimana dimaksud dalam Pasal 6 ayat (1) huruf c memiliki warna dasar putih, garis tepi merah, lambang hitam, huruf dan/atau angka hitam, dan warna tulisan merah.
2015, No.2033
(2) Bentuk, lambang, warna, dan arti rambu larangan bencana sebagaimana dimaksud dalam Pasal 6 ayat (1) huruf c tercantum dalam Lampiran II yang merupakan bagian tidak terpisahkan dari peraturan ini.', 'Pasal 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9089, 'perka-7-2015', 13, 'pasal', 'Pasal 12', 'BAB IV PAPAN INFORMASI BENCANA', 7, '(1) Rambu bencana dilengkapi dengan papan tambahan dengan warna dasar putih, warna garis tepi hitam, warna huruf atau angka hitam dan warna kata hitam.
(2) Papan tambahan sebagaimana dimaksud pada ayat (1) digunakan untuk memberi keterangan tambahan untuk menyatakan rambu bencana hanya berlaku pada nilai tertentu, arah tertentu, dan hal tertentu dengan kata dan nilai.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9089, '(1) Rambu bencana dilengkapi dengan papan tambahan dengan warna dasar putih, warna garis tepi hitam, warna huruf atau angka hitam dan warna kata hitam.
(2) Papan tambahan sebagaimana dimaksud pada ayat (1) digunakan untuk memberi keterangan tambahan untuk menyatakan rambu bencana hanya berlaku pada nilai tertentu, arah tertentu, dan hal tertentu dengan kata dan nilai.', 'Pasal 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9090, 'perka-7-2015', 14, 'pasal', 'Pasal 13', 'BAB IV PAPAN INFORMASI BENCANA', 7, 'Papan Informasi Bencana berisi informasi mengenai kawasan rawan bencana atau bahayanya, informasi kejadian bencana yang pernah terjadi dan/atau berpotensi akan terjadi terjadi serta lokasi tempat kumpul sementara atau tempat pengungsian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9090, 'Papan Informasi Bencana berisi informasi mengenai kawasan rawan bencana atau bahayanya, informasi kejadian bencana yang pernah terjadi dan/atau berpotensi akan terjadi terjadi serta lokasi tempat kumpul sementara atau tempat pengungsian.', 'Pasal 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9091, 'perka-7-2015', 15, 'pasal', 'Pasal 14', 'BAB V PENYELENGGARAAN RAMBU DAN PAPAN INFORMASI BENCANA; Bagian Kesatu Perencanaan', 7, '(1) Papan Informasi Bencana terdiri atas:
a. papan informasi jenis bahaya;
b. papan informasi kejadian bencana;
c. papan informasi memasuki kawasan rawan bencana;
d. papan informasi jalur evakuasi bencana; dan
e. papan informasi penanda tempat.
2015, No.2033 -8-
(2) Papan informasi jenis bahaya sebagaimana dimaksud pada ayat (1) huruf a berisi informasi atau himbauan mengenai jenis ancaman bencana tertentu bagi masyarakat yang berada pada kawasan rawan bencana.
(3) Papan informasi kejadian bencana sebagaimana dimaksud pada ayat (1) huruf b berisi informasi mengenai kejadian bencana bagi masyarakat yang berada pada kawasan rawan bencana.
(4) Papan informasi memasuki kawasan rawan bencana sebagaimana dimaksud pada ayat (1) huruf c berisi informasi atau himbauan mengenai kawasan rawan bencana tertentu bagi masyarakat yang berada pada kawasan rawan bencana.
(5) Papan informasi jalur evakuasi bencana sebagaimana dimaksud pada ayat (1) huruf d berisi informasi mengenai jalur evakuasi menuju tempat aman bagi masyarakat yang berada pada kawasan rawan bencana.
(6) Papan informasi penanda tempat sebagaimana dimaksud pada ayat (1) huruf e berisi informasi atau himbauan mengenai penanda tempat bagi masyarakat yang berada pada kawasan rawan bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9091, '(1) Papan Informasi Bencana terdiri atas:
a. papan informasi jenis bahaya;
b. papan informasi kejadian bencana;
c. papan informasi memasuki kawasan rawan bencana;
d. papan informasi jalur evakuasi bencana; dan
e. papan informasi penanda tempat.
2015, No.2033 -8-
(2) Papan informasi jenis bahaya sebagaimana dimaksud pada ayat (1) huruf a berisi informasi atau himbauan mengenai jenis ancaman bencana tertentu bagi masyarakat yang berada pada kawasan rawan bencana.
(3) Papan informasi kejadian bencana sebagaimana dimaksud pada ayat (1) huruf b berisi informasi mengenai kejadian bencana bagi masyarakat yang berada pada kawasan rawan bencana.
(4) Papan informasi memasuki kawasan rawan bencana sebagaimana dimaksud pada ayat (1) huruf c berisi informasi atau himbauan mengenai kawasan rawan bencana tertentu bagi masyarakat yang berada pada kawasan rawan bencana.
(5) Papan informasi jalur evakuasi bencana sebagaimana dimaksud pada ayat (1) huruf d berisi informasi mengenai jalur evakuasi menuju tempat aman bagi masyarakat yang berada pada kawasan rawan bencana.
(6) Papan informasi penanda tempat sebagaimana dimaksud pada ayat (1) huruf e berisi informasi atau himbauan mengenai penanda tempat bagi masyarakat yang berada pada kawasan rawan bencana.', 'Pasal 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9092, 'perka-7-2015', 16, 'pasal', 'Pasal 15', 'BAB V PENYELENGGARAAN RAMBU DAN PAPAN INFORMASI BENCANA; Bagian Kedua Pengadaan', 8, '(1) Perencanaan penyelenggaraan rambu dan papan informasi bencana dilaksanakan oleh Pemerintah dan/atau pemerintah daerah.
(2) Perencanaan sebagaimana dimaksud pada ayat (1), pemerintah daerah dapat berkoordinasi dengan kementerian/lembaga terkait.
2015, No.2033');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9092, '(1) Perencanaan penyelenggaraan rambu dan papan informasi bencana dilaksanakan oleh Pemerintah dan/atau pemerintah daerah.
(2) Perencanaan sebagaimana dimaksud pada ayat (1), pemerintah daerah dapat berkoordinasi dengan kementerian/lembaga terkait.
2015, No.2033', 'Pasal 15', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9093, 'perka-7-2015', 17, 'pasal', 'Pasal 16', 'BAB V PENYELENGGARAAN RAMBU DAN PAPAN INFORMASI BENCANA; Bagian Ketiga Pemasangan', 9, '(1) Pengadaan penyelenggaraan rambu dan papan informasi bencana dilaksanakan oleh Pemerintah dan/atau pemerintah daerah.
(2) Dalam hal pengadaan dilaksanakan oleh masyarakat atau lembaga Usaha terlebih dahulu berkoordinasi dengan pemerintah daerah.
(3) Pengadaan rambu dan papan informasi bencana berdasarkan perencanaan yang telah ditentukan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9093, '(1) Pengadaan penyelenggaraan rambu dan papan informasi bencana dilaksanakan oleh Pemerintah dan/atau pemerintah daerah.
(2) Dalam hal pengadaan dilaksanakan oleh masyarakat atau lembaga Usaha terlebih dahulu berkoordinasi dengan pemerintah daerah.
(3) Pengadaan rambu dan papan informasi bencana berdasarkan perencanaan yang telah ditentukan.', 'Pasal 16', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9094, 'perka-7-2015', 18, 'pasal', 'Pasal 17', 'BAB V PENYELENGGARAAN RAMBU DAN PAPAN INFORMASI BENCANA; Bagian Ketiga Pemasangan', 9, '(1) Pemasangan rambu dan papan informasi bencana dilaksanakan oleh penyelenggara yang mengadakan rambu dan papan informasi bencana.
(2) Pemasangan sebagaimana dimaksud pada ayat (1) berdasarkan perencanaan yang telah ditentukan.
(3) Pemasangan sebagaimana dimaksud pada ayat (1) yang dilaksanakan oleh masyarakat atau lembaga usaha terlebih dahulu berkoordinasi dengan pemerintah Daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9094, '(1) Pemasangan rambu dan papan informasi bencana dilaksanakan oleh penyelenggara yang mengadakan rambu dan papan informasi bencana.
(2) Pemasangan sebagaimana dimaksud pada ayat (1) berdasarkan perencanaan yang telah ditentukan.
(3) Pemasangan sebagaimana dimaksud pada ayat (1) yang dilaksanakan oleh masyarakat atau lembaga usaha terlebih dahulu berkoordinasi dengan pemerintah Daerah.', 'Pasal 17', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9095, 'perka-7-2015', 19, 'pasal', 'Pasal 18', 'BAB V PENYELENGGARAAN RAMBU DAN PAPAN INFORMASI BENCANA; Bagian Keempat Pemeliharaan', 9, '(1) Pemasangan sebagaimana dimaksud dalam Pasal 17 berdasarkan ketentuan peraturan perundang-undangan.
(2) Pemasangan sebagaimana dimaksud pada ayat (1) dilakukan terlebih dahulu berkoordinasi dengan instansi yang berwenang dalam urusan pemerintahan di bidang lalu lintas dan jalan raya.
2015, No.2033 -10-');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9095, '(1) Pemasangan sebagaimana dimaksud dalam Pasal 17 berdasarkan ketentuan peraturan perundang-undangan.
(2) Pemasangan sebagaimana dimaksud pada ayat (1) dilakukan terlebih dahulu berkoordinasi dengan instansi yang berwenang dalam urusan pemerintahan di bidang lalu lintas dan jalan raya.
2015, No.2033 -10-', 'Pasal 18', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9096, 'perka-7-2015', 20, 'pasal', 'Pasal 19', 'BAB V PENYELENGGARAAN RAMBU DAN PAPAN INFORMASI BENCANA; Bagian Kelima Penghapusan', 10, '(1) Pemeliharaan rambu dan papan informasi bencana dilaksanakan oleh pemerintah daerah atau Penyelenggara.
(2) Dalam hal menjaga kondisi rambu dan papan informasi bencana agar dapat berfungsi dengan baik, perlu dilakukan peninjauan ulang ke lokasi pemasangan secara periodik.
(3) Peninjauan ulang sebagaimana dimaksud pada ayat (2) dilakukan apabila terdapat perubahan kawasan rawan bencana.
(4) Hasil peninjauan ulang yang mengakibatkan perubahan lokasi pemasangan, penyelenggara wajib memindahkan rambu dan papan informasi bencana atau menggantinya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9096, '(1) Pemeliharaan rambu dan papan informasi bencana dilaksanakan oleh pemerintah daerah atau Penyelenggara.
(2) Dalam hal menjaga kondisi rambu dan papan informasi bencana agar dapat berfungsi dengan baik, perlu dilakukan peninjauan ulang ke lokasi pemasangan secara periodik.
(3) Peninjauan ulang sebagaimana dimaksud pada ayat (2) dilakukan apabila terdapat perubahan kawasan rawan bencana.
(4) Hasil peninjauan ulang yang mengakibatkan perubahan lokasi pemasangan, penyelenggara wajib memindahkan rambu dan papan informasi bencana atau menggantinya.', 'Pasal 19', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9097, 'perka-7-2015', 21, 'pasal', 'Pasal 20', 'BAB V PENYELENGGARAAN RAMBU DAN PAPAN INFORMASI BENCANA; Bagian Kelima Penghapusan', 10, '(1) Penghapusan rambu dan papan informasi bencana dilakukan berdasarkan:
a. umur teknis; dan
b. keberadaan fisik.
(2) Umur teknis sebagaimana dimaksud pada ayat (1) huruf a sekurang-kurangnya 5 (lima) tahun.
(3) Keberadaan fisik rambu sebagaimana dimaksud pada ayat (1) huruf b meliputi rusak dan hilang.
(4) Penghapusan sebagaimana dimaksud pada ayat (1) sesuai ketentuan peraturan perundang-undangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9097, '(1) Penghapusan rambu dan papan informasi bencana dilakukan berdasarkan:
a. umur teknis; dan
b. keberadaan fisik.
(2) Umur teknis sebagaimana dimaksud pada ayat (1) huruf a sekurang-kurangnya 5 (lima) tahun.
(3) Keberadaan fisik rambu sebagaimana dimaksud pada ayat (1) huruf b meliputi rusak dan hilang.
(4) Penghapusan sebagaimana dimaksud pada ayat (1) sesuai ketentuan peraturan perundang-undangan.', 'Pasal 20', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9098, 'perka-7-2015', 22, 'pasal', 'Pasal 21', 'BAB VI PENYEBARLUASAN INFORMASI PERINGATAN BENCANA', 10, 'Ketentuan lebih lanjut tentang penyelenggaraan rambu dan papan informasi bencana diatur dengan petunjuk pelaksanaan.
2015, No.2033');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9098, 'Ketentuan lebih lanjut tentang penyelenggaraan rambu dan papan informasi bencana diatur dengan petunjuk pelaksanaan.
2015, No.2033', 'Pasal 21', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9099, 'perka-7-2015', 23, 'pasal', 'Pasal 22', 'BAB VII PEMBINAAN DAN PENGAWASAN TEKNIS; Bagian Kesatu Pembinaan Teknis', 11, '(1) Penyebarluasan informasi peringatan bencana dengan rambu dan papan informasi peringatan bencana dilakukan oleh Pemerintah, bersama pemerintah daerah, masyarakat dan lembaga usaha penyelenggara.
(2) Penyebarluasan sebagaimana dimaksud pada ayat (1) dilakukan untuk memberikan informasi peringatan bencana kepada masyarakat di wilayah potensi bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9099, '(1) Penyebarluasan informasi peringatan bencana dengan rambu dan papan informasi peringatan bencana dilakukan oleh Pemerintah, bersama pemerintah daerah, masyarakat dan lembaga usaha penyelenggara.
(2) Penyebarluasan sebagaimana dimaksud pada ayat (1) dilakukan untuk memberikan informasi peringatan bencana kepada masyarakat di wilayah potensi bencana.', 'Pasal 22', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9100, 'perka-7-2015', 24, 'pasal', 'Pasal 23', 'BAB VII PEMBINAAN DAN PENGAWASAN TEKNIS; Bagian Kesatu Pembinaan Teknis', 11, '(1) Pembinaan dan pengawasan teknis rambu dan papan informasi bencana dilakukan oleh Pemerintah dan/atau pemerintah daerah.
(2) Pembinaan teknis meliputi penentuan persyaratan, dan/atau tata cara penyelenggaraan.
(3) Pengawasan teknis meliputi kegiatan pemantauan dan penilaian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9100, '(1) Pembinaan dan pengawasan teknis rambu dan papan informasi bencana dilakukan oleh Pemerintah dan/atau pemerintah daerah.
(2) Pembinaan teknis meliputi penentuan persyaratan, dan/atau tata cara penyelenggaraan.
(3) Pengawasan teknis meliputi kegiatan pemantauan dan penilaian.', 'Pasal 23', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9101, 'perka-7-2015', 25, 'pasal', 'Pasal 24', 'BAB VII PEMBINAAN DAN PENGAWASAN TEKNIS; Bagian Kedua Pengawasan Teknis', 11, '(1) Pembinaan sebagaimana dimaksud dalam Pasal 23 apabila penyelenggara pembinaanya adalah pemerintah daerah, maka pembinaan teknisnya dilakukan oleh BNPB.
(2) Pembinaan sebagaimana dimaksud pada ayat (1) apabila penyelenggara pembinaannya adalah masyarakat atau lembaga usaha, maka pembinaan teknisnya dilakukan oleh pemerintah daerah.
2015, No.2033 -12-
(3) Pembinaan teknis dapat dilakukan dengan melibatkan instansi teknis terkait sesuai dengan jenis bencananya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9101, '(1) Pembinaan sebagaimana dimaksud dalam Pasal 23 apabila penyelenggara pembinaanya adalah pemerintah daerah, maka pembinaan teknisnya dilakukan oleh BNPB.
(2) Pembinaan sebagaimana dimaksud pada ayat (1) apabila penyelenggara pembinaannya adalah masyarakat atau lembaga usaha, maka pembinaan teknisnya dilakukan oleh pemerintah daerah.
2015, No.2033 -12-
(3) Pembinaan teknis dapat dilakukan dengan melibatkan instansi teknis terkait sesuai dengan jenis bencananya.', 'Pasal 24', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9102, 'perka-7-2015', 26, 'pasal', 'Pasal 25', 'BAB VII PEMBINAAN DAN PENGAWASAN TEKNIS; Bagian Kedua Pengawasan Teknis', 12, '(1) Pengawasan apabila penyelenggara pengawasannya adalah pemerintah daerah, maka pengawasan teknisnya dilakukan oleh BNPB.
(2) Pengawasan sebagaimana dimaksud pada ayat (1) apabila penyelenggara pengawasan teknisnya adalah masyarakat atau lembaga usaha, maka pengawasan teknisnya dilakukan oleh pemerintah daerah.
(3) Pengawasan sebagaimana dimaksud pada ayat (1) dapat dilakukan dengan melibatkan instansi teknis terkait sesuai dengan jenis bencananya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9102, '(1) Pengawasan apabila penyelenggara pengawasannya adalah pemerintah daerah, maka pengawasan teknisnya dilakukan oleh BNPB.
(2) Pengawasan sebagaimana dimaksud pada ayat (1) apabila penyelenggara pengawasan teknisnya adalah masyarakat atau lembaga usaha, maka pengawasan teknisnya dilakukan oleh pemerintah daerah.
(3) Pengawasan sebagaimana dimaksud pada ayat (1) dapat dilakukan dengan melibatkan instansi teknis terkait sesuai dengan jenis bencananya.', 'Pasal 25', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9103, 'perka-7-2015', 27, 'pasal', 'Pasal 26', 'BAB VII PEMBINAAN DAN PENGAWASAN TEKNIS; Bagian Kedua Pengawasan Teknis', 12, 'Ketentuan lebih lanjut tentang pembinaan dan pengawasan rambu dan papan informasi bencana diatur dengan petunjuk pelaksanaan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9103, 'Ketentuan lebih lanjut tentang pembinaan dan pengawasan rambu dan papan informasi bencana diatur dengan petunjuk pelaksanaan.', 'Pasal 26', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 7 Tahun 2015 tentang Rambu dan Papan Informasi Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9104, 'perka-7-2015', 28, 'pasal', 'Pasal 27', 'BAB IX', 12, 'Rambu dan papan informasi bencana yang telah dipasang sebelum ditetapkannya peraturan ini tetap berlaku.
Ketentuan Penutup');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9104, 'Rambu dan papan informasi bencana yang telah dipasang sebelum ditetapkannya peraturan ini tetap berlaku.
