INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9109, 'perka-7-2015', 33, 'lampiran', 'Lampiran hal. 29', NULL, 29, '29. 2015, No.2033 LAMPIRAN II PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR TAHUN 2015 TENTANG RAMBU DAN PAPAN INFORMASI BENCANA BENTUK, LAMBANG, WARNA, DAN ARTI RAMBU DAN PAPAN INFORMASI BENCANA A. BENTUK, LAMBANG, WARNA, DAN ARTI RAMBU
1. BENTUK, LAMBANG, WARNA, DAN ARTI RAMBU PETUNJUK
a. Bentuk, Lambang, Warna, dan Arti Rambu Petunjuk dengan Simbol Petunjuk tempat kumpul sementara Petunjuk tempat a.2 ? pengungsian 2015, No.2033 -30- Petunjuk lokasi a3 posko Petunjuk tempat untuk membuat api, a4 perhatikan: segera padamkan api jika selesai dipergunakan
b. Bentuk, Warna, dan Arti Rambu Petunjuk dengan Kata b.1 & «JALUR EVAKUASI sai ungai EVACUATION ROUTE jalur evakuasi Petunjuk TEMPAT PENGUNGSIAN 750 kada Luss STADION MAGUWO m tempa pengungsian
31. 2015, No.2033
2. BENTUK, LAMBANG, WARNA, DAN ARTI RAMBU PERINGATAN
a. Bentuk, Lambang, Warna, dan Arti Rambu Peringatan dengan Simbol Peringatan telah berada a.l pada kawasan rawan bencana gunung api Peringatan telah berada a.2 pada kawasan rawan bencana gempa bumi Peringatan telah berada a.3 pada kawasan rawan bencana gerakan tanah 2015, No.2033 -32- Peringatan telah berada a4 pada kawasan rawan bencana gerakan tanah Peringatan telah berada pada kawasan rawan bencana tsunami KA Peringatan telah berada a.6 pada kawasan rawan bencana banjir Peringatan rawan a.7 kebakaran hutan 33 2015, No.2033
b. Bentuk, Warna, dan Arti Rambu Peringatan dengan Kata HATI HATI JALUR AWAN PANAS');
