INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9110, 'perka-7-2015', 34, 'lampiran', 'Lampiran hal. 33', NULL, 33, '3. Bentuk, Lambang, Warna, dan Arti Rambu Larangan
