INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9114, 'perka-8-2008', 2, 'mengingat', 'Mengingat', NULL, 1, '1. Undang-Undang Dasar Republik Indonesia Tahun 1945;
