INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9116, 'perka-8-2008', 4, 'pasal', 'Pasal 1', NULL, 2, 'Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita sebagaimana tersebut dalam Lampiran Peraturan ini merupakan pelaksanaan dari Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana yang tidak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9116, 'Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita sebagaimana tersebut dalam Lampiran Peraturan ini merupakan pelaksanaan dari Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana yang tidak terpisahkan dari Peraturan ini.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9117, 'perka-8-2008', 5, 'pasal', 'Pasal 2', NULL, 2, 'Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita sebagaimana dimaksud dalam Pasal 1, dipergunakan sebagai acuan bagi setiap Pelaksana Pemberi Bantuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9117, 'Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita sebagaimana dimaksud dalam Pasal 1, dipergunakan sebagai acuan bagi setiap Pelaksana Pemberi Bantuan.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9118, 'perka-8-2008', 6, 'pasal', 'Pasal 3', NULL, 2, 'Hal-hal yang belum diatur dalam Peraturan ini, akan diatur kemudian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9118, 'Hal-hal yang belum diatur dalam Peraturan ini, akan diatur kemudian.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9119, 'perka-8-2008', 7, 'pasal', 'Pasal 4', NULL, 2, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9119, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9120, 'perka-8-2008', 8, 'lain', 'Penutup', NULL, 2, 'Ditetapkan di Jakarta pada tanggal 17 Desember 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9120, 'Ditetapkan di Jakarta pada tanggal 17 Desember 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9121, 'perka-8-2008', 9, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 8.. TAHUN 2008 TANGGAL : 17..DESEMBER 2008 BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan wilayah yang memiliki potensi serta intensitas kejadian bencana cukup tinggi baik bencana alam, non alam maupun bencana sosial. Hal demikian tentunya pantas untuk dipedulikan, mengingat akibat yang ditimbulkan oleh suatu kejadian bencana memiliki dampak yang luas, baik secara sosial, psikis, ekonomi, bahkan politik. Hampir semua jenis bencana alam, non alam dan bencana sosial telah menimbulkan korban jiwa, kecacatan dan kerugian harta benda serta merusak sarana dan prasarana publik yang ada, pengungsian, ketidaknormalan kehidupan dan penghidupan masyarakat serta pelaksanaan pembangunan.
Ketika bencana muncul, suatu masyarakat yang menjadi korban sangat membutuhkan bantuan dari pihak luar. Namun terkadang keterlibatan pihak luar di dalam memberikan bantuan kepada masyarakat korban bencana, dapat menimbulkan masalah baru berupa ketidaksesuaian bantuan yang diberikan dengan kebutuhan masyarakat ataupun kecemburuan sosial diantara orang-orang yang merasa diperlakukan secara tidak adil.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9121, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 8.. TAHUN 2008 TANGGAL : 17..DESEMBER 2008 BAB I PENDAHULUAN A. Latar Belakang Indonesia merupakan wilayah yang memiliki potensi serta intensitas kejadian bencana cukup tinggi baik bencana alam, non alam maupun bencana sosial. Hal demikian tentunya pantas untuk dipedulikan, mengingat akibat yang ditimbulkan oleh suatu kejadian bencana memiliki dampak yang luas, baik secara sosial, psikis, ekonomi, bahkan politik. Hampir semua jenis bencana alam, non alam dan bencana sosial telah menimbulkan korban jiwa, kecacatan dan kerugian harta benda serta merusak sarana dan prasarana publik yang ada, pengungsian, ketidaknormalan kehidupan dan penghidupan masyarakat serta pelaksanaan pembangunan.
Ketika bencana muncul, suatu masyarakat yang menjadi korban sangat membutuhkan bantuan dari pihak luar. Namun terkadang keterlibatan pihak luar di dalam memberikan bantuan kepada masyarakat korban bencana, dapat menimbulkan masalah baru berupa ketidaksesuaian bantuan yang diberikan dengan kebutuhan masyarakat ataupun kecemburuan sosial diantara orang-orang yang merasa diperlakukan secara tidak adil.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9122, 'perka-8-2008', 10, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'Bahwa bantuan yang diberikan kepada masyarakat yang terkena bencana sangat bernilai tinggi dan bermanfaat. Namun tidak sedikit pula yang memandang bahwa bantuan memiliki sisi-sisi negatif yang dapat mengganggu keleluasaan (privacy) dan harga diri masyarakat bersangkutan. Persoalan lainnya yang sering terjadi yaitu ketika suatu bencana terjadi, banyak pihak yang terlibat memberikan bantuan tidak terkoordinir dengan baik sehingga menimbulkan kekacauan di lapangan.
Berbagai persoalan dan permasalahan di atas disamping membutuhkan organisasi yang mampu mengkoordinasikan dan mengelola bantuan sehingga bermanfaat dan membantu bagi yang membutuhkannya, juga membutuhkan partisipasi aktif masyarakat baik secara individual maupun kolektif. Semua ini secara mendasar membutuhkan arah kebijakan yang jelas dan tegas.
Peraturan Pemerintah Republik Indonesia Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana sebagai penjabaran dari Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana telah memberikan rambu-rambu bahwa bantuan bagi korban bencana antara lain mencakup santunan duka cita (pasal 24). Santunan duka cita diberikan dalam bentuk biaya pemakaman dan/atau uang duka (pasal 25).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9122, 'Bahwa bantuan yang diberikan kepada masyarakat yang terkena bencana sangat bernilai tinggi dan bermanfaat. Namun tidak sedikit pula yang memandang bahwa bantuan memiliki sisi-sisi negatif yang dapat mengganggu keleluasaan (privacy) dan harga diri masyarakat bersangkutan. Persoalan lainnya yang sering terjadi yaitu ketika suatu bencana terjadi, banyak pihak yang terlibat memberikan bantuan tidak terkoordinir dengan baik sehingga menimbulkan kekacauan di lapangan.
Berbagai persoalan dan permasalahan di atas disamping membutuhkan organisasi yang mampu mengkoordinasikan dan mengelola bantuan sehingga bermanfaat dan membantu bagi yang membutuhkannya, juga membutuhkan partisipasi aktif masyarakat baik secara individual maupun kolektif. Semua ini secara mendasar membutuhkan arah kebijakan yang jelas dan tegas.
Peraturan Pemerintah Republik Indonesia Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana sebagai penjabaran dari Undang-Undang Republik Indonesia Nomor 24 Tahun 2007 tentang Penanggulangan Bencana telah memberikan rambu-rambu bahwa bantuan bagi korban bencana antara lain mencakup santunan duka cita (pasal 24). Santunan duka cita diberikan dalam bentuk biaya pemakaman dan/atau uang duka (pasal 25).', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9123, 'perka-8-2008', 11, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'Permasalahan yang timbul sebagai akibat peristiwa bencana alam, non alam maupun bencana sosial merupakan dampak bencana yang bersifat primer yaitu menyengsarakan orang dan merusak lingkungan secara langsung pada saat bencana terjadi antara lain menimbulkan kematian. Dampak bencana yang bersifat sekunder yaitu timbulnya masalah keluarga terutama apabila kepala keluarga meninggal dunia.
Bantuan yang tidak tepat akan menimbulkan masalah bagi korban bencana yang menyebabkan mereka tidak berdaya untuk memulihkan fungsi sosial dan ekonomi.
Untuk mengatur lebih lanjut mengenai bagaimana bantuan santuan duka cita diberikan, dibutuhkan acuan yang jelas bagi pelaksana pemberi bantuan berupa Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita.
B. Maksud dan Tujuan
1. Maksud Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita dimaksudkan sebagai lampiran Peraturan Kepala Badan Nasional Penanggulangan Bencana (BNPB) yang mengatur pelaksanaan pemberian dan besaran bantuan santunan duka cita bagi korban yang meninggal dunia sebagai penjabaran pasal 25 ayat (4) Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
2. Tujuan Tujuan Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita adalah memberikan pedoman bagi pelaksana pemberi bantuan untuk :
a. menentukan korban bencana yang memenuhi kriteria penerima santunan duka cita.
b. menentukan kategori santunan bagi korban bencana yang meninggal dunia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9123, 'Permasalahan yang timbul sebagai akibat peristiwa bencana alam, non alam maupun bencana sosial merupakan dampak bencana yang bersifat primer yaitu menyengsarakan orang dan merusak lingkungan secara langsung pada saat bencana terjadi antara lain menimbulkan kematian. Dampak bencana yang bersifat sekunder yaitu timbulnya masalah keluarga terutama apabila kepala keluarga meninggal dunia.
Bantuan yang tidak tepat akan menimbulkan masalah bagi korban bencana yang menyebabkan mereka tidak berdaya untuk memulihkan fungsi sosial dan ekonomi.
Untuk mengatur lebih lanjut mengenai bagaimana bantuan santuan duka cita diberikan, dibutuhkan acuan yang jelas bagi pelaksana pemberi bantuan berupa Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita.
B. Maksud dan Tujuan
1. Maksud Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita dimaksudkan sebagai lampiran Peraturan Kepala Badan Nasional Penanggulangan Bencana (BNPB) yang mengatur pelaksanaan pemberian dan besaran bantuan santunan duka cita bagi korban yang meninggal dunia sebagai penjabaran pasal 25 ayat (4) Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
2. Tujuan Tujuan Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita adalah memberikan pedoman bagi pelaksana pemberi bantuan untuk :
a. menentukan korban bencana yang memenuhi kriteria penerima santunan duka cita.
b. menentukan kategori santunan bagi korban bencana yang meninggal dunia.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9124, 'perka-8-2008', 12, 'lampiran', 'Lampiran hal. 4', NULL, 4, 'c. memberikan santunan yang sesuai prosedur standar yang ditentukan di dalam panduan ini.
C. Ruang Lingkup
1. Pedoman ini berlaku bagi para pelaksana pemberi bantuan korban bencana pada lingkup nasional, provinsi dan kabupaten/kota.
2. Pedoman ini selain menjadi acuan pemerintah dan pemerintah daerah, juga dapat menjadi acuan bagi para pelaksana pemberi bantuan yang berasal dari lembaga non pemerintah, baik daerah, nasional maupun internasional.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam, faktor nonalam, maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis bagi manusia.
2. Bencana alam adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang ditimbulkan oleh alam, antara lain berupa gempa bumi, tsunami, gunung meletus, banjir, kekeringan, angin topan, dan tanah longsor.
3. Bencana nonalam adalah bencana yang diakibatkan oleh peristiwa atau rangkaian peristiwa nonalam, antara lain berupa gagal teknologi, gagal modernisasi, epidemi, dan wabah penyakit.
4. Bencana sosial adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang diakibatkan oleh manusia yang meliputi konflik sosial antar kelompok atau antarkomunitas masyarakat, dan teror.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9124, 'c. memberikan santunan yang sesuai prosedur standar yang ditentukan di dalam panduan ini.
C. Ruang Lingkup
1. Pedoman ini berlaku bagi para pelaksana pemberi bantuan korban bencana pada lingkup nasional, provinsi dan kabupaten/kota.
2. Pedoman ini selain menjadi acuan pemerintah dan pemerintah daerah, juga dapat menjadi acuan bagi para pelaksana pemberi bantuan yang berasal dari lembaga non pemerintah, baik daerah, nasional maupun internasional.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam, faktor nonalam, maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis bagi manusia.
2. Bencana alam adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang ditimbulkan oleh alam, antara lain berupa gempa bumi, tsunami, gunung meletus, banjir, kekeringan, angin topan, dan tanah longsor.
3. Bencana nonalam adalah bencana yang diakibatkan oleh peristiwa atau rangkaian peristiwa nonalam, antara lain berupa gagal teknologi, gagal modernisasi, epidemi, dan wabah penyakit.
4. Bencana sosial adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang diakibatkan oleh manusia yang meliputi konflik sosial antar kelompok atau antarkomunitas masyarakat, dan teror.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9125, 'perka-8-2008', 13, 'lampiran', 'Lampiran hal. 5', NULL, 5, '5. Korban bencana adalah seseorang atau sekelompok manusia yang mengalami penderitaan (secara fisik/mental) atau meninggal dunia akibat bencana yang terjadi.
6. Pelaksana pemberi bantuan adalah pihak yang memberikan santunan duka cita, baik pemerintah dan pemerintah daerah, maupun lembaga non pemerintah, baik daerah, nasional maupun internasional.
7. Santunan Duka Cita adalah santunan yang diberikan oleh pemerintah, pemerintah daerah, lembaga nonpemerintah berupa uang yang diberikan kepada ahli waris dari korban bencana yang meninggal dunia.
8. Biaya Pemakaman adalah bantuan sejumlah uang yang diberikan kepada ahli waris korban bencana yang meninggal dunia untuk membiayai proses pemakaman.
9. Ahli waris adalah orang yang berhak menerima warisan santunan duka cita, dalam hal ini orang tua korban (ayah atau ibu), suami atau isteri korban, atau anak sah korban.
E. Landasan Hukum
1. Undang-Undang Dasar Republik Indonesia Tahun 1945;
2. Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara;
3. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara;
4. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007, tambahan Lembaran Negara Republik Indonesia Nomor 4723);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9125, '5. Korban bencana adalah seseorang atau sekelompok manusia yang mengalami penderitaan (secara fisik/mental) atau meninggal dunia akibat bencana yang terjadi.
6. Pelaksana pemberi bantuan adalah pihak yang memberikan santunan duka cita, baik pemerintah dan pemerintah daerah, maupun lembaga non pemerintah, baik daerah, nasional maupun internasional.
7. Santunan Duka Cita adalah santunan yang diberikan oleh pemerintah, pemerintah daerah, lembaga nonpemerintah berupa uang yang diberikan kepada ahli waris dari korban bencana yang meninggal dunia.
8. Biaya Pemakaman adalah bantuan sejumlah uang yang diberikan kepada ahli waris korban bencana yang meninggal dunia untuk membiayai proses pemakaman.
9. Ahli waris adalah orang yang berhak menerima warisan santunan duka cita, dalam hal ini orang tua korban (ayah atau ibu), suami atau isteri korban, atau anak sah korban.
E. Landasan Hukum
1. Undang-Undang Dasar Republik Indonesia Tahun 1945;
2. Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara;
3. Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara;
4. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007, tambahan Lembaran Negara Republik Indonesia Nomor 4723);', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9126, 'perka-8-2008', 14, 'lampiran', 'Lampiran hal. 6', NULL, 6, '5. Peraturan Pemerintah Nomor 38 Tahun 2007 tentang Pembagian Urusan Pemerintahan antara Pemerintah, Pemerintah Daerah Provinsi dan Kabupaten/Kota (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 82, Tambahan Lembaran Negara Republik Indonesia Nomor 4737);
6. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana;
7. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
8. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
F. Prinsip
1. Penghargaan terhadap harkat dan martabat manusia, maksudnya bahwa santunan yang diberikan bertujuan untuk melindungi dan menghormati hak-hak azasi manusia, harkat dan martabat setiap warga negara.
2. Perlakuan adil, adalah bahwa santunan yang diberikan kepada korban bencana semata-mata atas dasar kebutuhan mereka, dalam prinsip ini terkandung kerangka kerja yang berlandaskan HAM, proporsionalitas, dan tidak mendiskriminasi.
3. Cepat dan tepat, maksudnya adalah bahwa dalam pemberian santunan harus dilaksanakan secara cepat dan tepat sesuai dengan tuntutan keadaan.
4. Transparansi dan Akuntabilitas, maksudnya adalah bahwa pemberian santunan dilakukan secara terbuka dan dapat dipertanggungjawabkan secara etika dan hukum.
5. Nondiskriminatif, maksudnya adalah bahwa dalam pemberian santunan tidak membedakan jenis kelamin, suku, agama, ras, dan aliran politik apa pun.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9126, '5. Peraturan Pemerintah Nomor 38 Tahun 2007 tentang Pembagian Urusan Pemerintahan antara Pemerintah, Pemerintah Daerah Provinsi dan Kabupaten/Kota (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 82, Tambahan Lembaran Negara Republik Indonesia Nomor 4737);
6. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana;
7. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
8. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana;
F. Prinsip
1. Penghargaan terhadap harkat dan martabat manusia, maksudnya bahwa santunan yang diberikan bertujuan untuk melindungi dan menghormati hak-hak azasi manusia, harkat dan martabat setiap warga negara.
2. Perlakuan adil, adalah bahwa santunan yang diberikan kepada korban bencana semata-mata atas dasar kebutuhan mereka, dalam prinsip ini terkandung kerangka kerja yang berlandaskan HAM, proporsionalitas, dan tidak mendiskriminasi.
3. Cepat dan tepat, maksudnya adalah bahwa dalam pemberian santunan harus dilaksanakan secara cepat dan tepat sesuai dengan tuntutan keadaan.
4. Transparansi dan Akuntabilitas, maksudnya adalah bahwa pemberian santunan dilakukan secara terbuka dan dapat dipertanggungjawabkan secara etika dan hukum.
5. Nondiskriminatif, maksudnya adalah bahwa dalam pemberian santunan tidak membedakan jenis kelamin, suku, agama, ras, dan aliran politik apa pun.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9127, 'perka-8-2008', 15, 'lampiran', 'Lampiran hal. 7', NULL, 7, '6. Nonproletisi, maksudnya adalah bahwa dilarang menyebarkan agama atau keyakinan pada saat keadaan darurat bencana, terutama melalui pemberian bantuan dan pelayanan darurat bencana.
7. Kehati-hatian, maksudnya adalah bahwa pemberian santunan harus cermat, teliti, aman, dan tertib sehingga sampai kepada sasaran.
G. Sistematika Sistematika Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita mencakup:
BAB I PENDAHULUAN yang memuat tentang latar belakang, maksud dan tujuan, ruang lingkup, pengertian, landasan hukum, prinsip dan sistematika.
BAB II ORGANISASI PELAKSANA DAN KOORDINASI yang memuat tentang organisasi pelaksana, dan koordinasi.
BAB III KRITERIA, KATEGORI, DAN BESARAN BANTUAN SANTUNAN DUKA CITA yang memuat tentang kriteria korban bencana, kriteria penerima bantuan, kategori bantuan dan besaran bantuan.
BAB IV MEKANISME PEMBERIAN BANTUAN yang memuat tentang persiapan, pelaksanaan, dan ketentuan khusus.
BAB V PENUTUP.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9127, '6. Nonproletisi, maksudnya adalah bahwa dilarang menyebarkan agama atau keyakinan pada saat keadaan darurat bencana, terutama melalui pemberian bantuan dan pelayanan darurat bencana.
7. Kehati-hatian, maksudnya adalah bahwa pemberian santunan harus cermat, teliti, aman, dan tertib sehingga sampai kepada sasaran.
G. Sistematika Sistematika Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita mencakup:
BAB I PENDAHULUAN yang memuat tentang latar belakang, maksud dan tujuan, ruang lingkup, pengertian, landasan hukum, prinsip dan sistematika.
BAB II ORGANISASI PELAKSANA DAN KOORDINASI yang memuat tentang organisasi pelaksana, dan koordinasi.
BAB III KRITERIA, KATEGORI, DAN BESARAN BANTUAN SANTUNAN DUKA CITA yang memuat tentang kriteria korban bencana, kriteria penerima bantuan, kategori bantuan dan besaran bantuan.
BAB IV MEKANISME PEMBERIAN BANTUAN yang memuat tentang persiapan, pelaksanaan, dan ketentuan khusus.
BAB V PENUTUP.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9128, 'perka-8-2008', 16, 'lampiran', 'Lampiran hal. 8', NULL, 8, 'BAB II ORGANISASI PELAKSANA DAN KOORDINASI A. Organisasi Pelaksana Organisasi pelaksana pemberi bantuan santunan duka cita sesuai ayat (2) pasal 25 PP 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana, adalah instansi/lembaga yang berwenang yang dikoordinasikan oleh BNPB atau BPBD sesuai dengan kewenangannya. Kewenangan instansi/lembaga yang berwenang menjadi pelaksana diperoleh berdasarkan peraturan perundangan-undangan yang mengatur tugas pokok dan fungsi instansi/lembaga seperti untuk instansi Pemerintah diatur berdasarkan Peraturan Pemerintah dan Peraturan Presiden, untuk instansi Pemerintah Provinsi diatur dengan Peraturan Daerah serta Peraturan/Keputusan Gubernur, dan untuk instansi kabupaten/Kota diatur dengan Peraturan Daerah dan Peraturan Bupati/Walikota.
B. Koordinasi Badan Nasional Penanggulangan Bencana (BNPB) dan Badan Penanggulangan Bencana Daerah (BPBD) sebagai lembaga yang memiliki tugas pokok melaksanakan penanggulangan bencana, juga memiliki fungsi mengkoordinasikan instansi/lembaga dalam lingkup kewenangannya. BNPB, BPBD Provinsi dan BPBD Kabupaten/Kota berfungsi mengkoordinasikan instansi/lembaga pemberi bantuan santunan sesuai kewenangannya.
Koordinasi dilakukan pada beberapa tahap:
1. Tahap penyusunan program. Koordinasi pada tahap ini diperlukan agar tidak terjadi duplikasi program antar instansi/lembaga yang berwenang menangani bantuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9128, 'BAB II ORGANISASI PELAKSANA DAN KOORDINASI A. Organisasi Pelaksana Organisasi pelaksana pemberi bantuan santunan duka cita sesuai ayat (2) pasal 25 PP 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana, adalah instansi/lembaga yang berwenang yang dikoordinasikan oleh BNPB atau BPBD sesuai dengan kewenangannya. Kewenangan instansi/lembaga yang berwenang menjadi pelaksana diperoleh berdasarkan peraturan perundangan-undangan yang mengatur tugas pokok dan fungsi instansi/lembaga seperti untuk instansi Pemerintah diatur berdasarkan Peraturan Pemerintah dan Peraturan Presiden, untuk instansi Pemerintah Provinsi diatur dengan Peraturan Daerah serta Peraturan/Keputusan Gubernur, dan untuk instansi kabupaten/Kota diatur dengan Peraturan Daerah dan Peraturan Bupati/Walikota.
B. Koordinasi Badan Nasional Penanggulangan Bencana (BNPB) dan Badan Penanggulangan Bencana Daerah (BPBD) sebagai lembaga yang memiliki tugas pokok melaksanakan penanggulangan bencana, juga memiliki fungsi mengkoordinasikan instansi/lembaga dalam lingkup kewenangannya. BNPB, BPBD Provinsi dan BPBD Kabupaten/Kota berfungsi mengkoordinasikan instansi/lembaga pemberi bantuan santunan sesuai kewenangannya.
Koordinasi dilakukan pada beberapa tahap:
1. Tahap penyusunan program. Koordinasi pada tahap ini diperlukan agar tidak terjadi duplikasi program antar instansi/lembaga yang berwenang menangani bantuan.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9129, 'perka-8-2008', 17, 'lampiran', 'Lampiran hal. 8', NULL, 8, '2. Tahap pelaksanaan program, yakni pada saat tanggap darurat bencana dan pasca bencana. Koordinasi pada tahap ini diperlukan untuk menjamin bahwa instansi/lembaga yang berwenang menangani bantuan dapat melaksanakan tugasnya dan agar para ahli waris korban bencana mendapatkan hak-haknya.
3. Tahap setelah pelaksanaan program bantuan santunan untuk mengetahui hasil-hasil program yang telah dilaksanakan.
BAB III KRITERIA, KATEGORI, DAN BESARAN BANTUAN SANTUNAN DUKA CITA A. Kriteria Korban Bencana
1. Seseorang yang meninggal sebagai akibat langsung terjadinya bencana.
2. Seseorang yang meninggal di pengungsian dan tempat lain sebagai akibat bencana pada masa darurat.
Kriteria tentang meninggalnya seseorang tersebut di atas dinyatakan dengan keterangan dari petugas pelaksana penanggulangan bencana atau pihak-pihak yang berwenang.
B. Kriteria Penerima Bantuan Santunan Duka Cita
1. Ahli waris korban bencana yang sudah dewasa (minimal berusia 18 tahun atau mereka yang berumur di bawah 18 tahun namun sudah berstatus menikah) dan diketahui oleh pihak yang berwenang (RT, RW, atau Kepala Desa/Kelurahan setempat).
2. Apabila ahli waris korban bencana dimaksud ternyata berusia di bawah 18 tahun, maka bantuan diserahkan kepada wali atau orang tua atau keluarga asuh atau panti/lembaga pelayanan sosial yang menggantikan peran orang tua/pengasuh (misalnya panti asuhan, orang tua angkat, keluarga luar yang mengambil alih tugas pengasuhan).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9129, '2. Tahap pelaksanaan program, yakni pada saat tanggap darurat bencana dan pasca bencana. Koordinasi pada tahap ini diperlukan untuk menjamin bahwa instansi/lembaga yang berwenang menangani bantuan dapat melaksanakan tugasnya dan agar para ahli waris korban bencana mendapatkan hak-haknya.
3. Tahap setelah pelaksanaan program bantuan santunan untuk mengetahui hasil-hasil program yang telah dilaksanakan.
BAB III KRITERIA, KATEGORI, DAN BESARAN BANTUAN SANTUNAN DUKA CITA A. Kriteria Korban Bencana
1. Seseorang yang meninggal sebagai akibat langsung terjadinya bencana.
2. Seseorang yang meninggal di pengungsian dan tempat lain sebagai akibat bencana pada masa darurat.
Kriteria tentang meninggalnya seseorang tersebut di atas dinyatakan dengan keterangan dari petugas pelaksana penanggulangan bencana atau pihak-pihak yang berwenang.
B. Kriteria Penerima Bantuan Santunan Duka Cita
1. Ahli waris korban bencana yang sudah dewasa (minimal berusia 18 tahun atau mereka yang berumur di bawah 18 tahun namun sudah berstatus menikah) dan diketahui oleh pihak yang berwenang (RT, RW, atau Kepala Desa/Kelurahan setempat).
2. Apabila ahli waris korban bencana dimaksud ternyata berusia di bawah 18 tahun, maka bantuan diserahkan kepada wali atau orang tua atau keluarga asuh atau panti/lembaga pelayanan sosial yang menggantikan peran orang tua/pengasuh (misalnya panti asuhan, orang tua angkat, keluarga luar yang mengambil alih tugas pengasuhan).', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9130, 'perka-8-2008', 18, 'lampiran', 'Lampiran hal. 9', NULL, 9, 'C. Kategori Bantuan Bantuan santunan duka cita terdiri dari biaya pemakaman dan atau uang duka, dengan rincian sebagai berikut:
1. Biaya Pemakaman Biaya pemakaman diberikan kepada ahli waris dan dipergunakan untuk pemakaman korban meninggal dunia. Bantuan diberikan dalam bentuk uang, apabila ahli waris atau lingkungan terjadinya bencana mampu menyelenggarakan pemakaman atas korban.
Apabila keluarga korban karena satu dan lain hal tidak mampu/sanggup untuk melaksanakan pemakaman, maka pemakaman dilakukan oleh aparat pemerintah dan keluarga korban tidak berhak menerima santunan biaya pemakaman ini.
2. Uang Duka
a. Penyerahan uang duka diberikan kepada ahli waris yang sudah cukup dewasa (minimal berusia 18 tahun atau mereka yang berumur di bawah 18 tahun namun sudah berstatus menikah).
b. Pemberian uang duka ini dimaksudkan untuk meringankan beban keluarga atau ahli waris yang ditinggalkan korban bencana yang meninggal.
c. Uang duka diberikan per satuan korban yang meninggal dunia karena bencana.
D. Besaran Bantuan
1. Besaran bantuan santunan duka cita bagi ahli waris korban bencana meninggal dunia sesuai persetujuan Menteri Keuangan (DIPA).
2. Alokasi besaran bantuan santunan duka cita bagi ahli waris korban bencana meninggal dunia sesuai peraturan ini yang disesuaikan dengan persetujuan Menteri Keuangan.
3. Besaran bantuan santunan duka cita bagi ahli waris korban bencana meninggal dunia per jiwa dalam bentuk biaya pemakaman dan atau uang duka.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9130, 'C. Kategori Bantuan Bantuan santunan duka cita terdiri dari biaya pemakaman dan atau uang duka, dengan rincian sebagai berikut:
1. Biaya Pemakaman Biaya pemakaman diberikan kepada ahli waris dan dipergunakan untuk pemakaman korban meninggal dunia. Bantuan diberikan dalam bentuk uang, apabila ahli waris atau lingkungan terjadinya bencana mampu menyelenggarakan pemakaman atas korban.
Apabila keluarga korban karena satu dan lain hal tidak mampu/sanggup untuk melaksanakan pemakaman, maka pemakaman dilakukan oleh aparat pemerintah dan keluarga korban tidak berhak menerima santunan biaya pemakaman ini.
2. Uang Duka
a. Penyerahan uang duka diberikan kepada ahli waris yang sudah cukup dewasa (minimal berusia 18 tahun atau mereka yang berumur di bawah 18 tahun namun sudah berstatus menikah).
b. Pemberian uang duka ini dimaksudkan untuk meringankan beban keluarga atau ahli waris yang ditinggalkan korban bencana yang meninggal.
c. Uang duka diberikan per satuan korban yang meninggal dunia karena bencana.
D. Besaran Bantuan
1. Besaran bantuan santunan duka cita bagi ahli waris korban bencana meninggal dunia sesuai persetujuan Menteri Keuangan (DIPA).
2. Alokasi besaran bantuan santunan duka cita bagi ahli waris korban bencana meninggal dunia sesuai peraturan ini yang disesuaikan dengan persetujuan Menteri Keuangan.
3. Besaran bantuan santunan duka cita bagi ahli waris korban bencana meninggal dunia per jiwa dalam bentuk biaya pemakaman dan atau uang duka.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9131, 'perka-8-2008', 19, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'BAB IV MEKANISME PEMBERIAN BANTUAN A. Persiapan
1. Pendataan Pendataan adalah kegiatan pengumpulan data yang bertujuan untuk menyediakan data yang lengkap, terpercaya dan dapat dipertanggungjawabkan mengenai keseluruhan jumlah korban bencana yang meninggal dunia pada suatu wilayah lokasi bencana. Pendataan dapat dilakukan pada saat tanggap darurat dan pasca bencana di lokasi bencana maupun di lokasi pengungsian.
Pendataan dilakukan oleh para petugas dari instansi/lembaga yang berwenang, dengan menggunakan format isian (lampiran 1).
2. Identifikasi Identifikasi merupakan langkah lanjutan setelah pendataan, yang dimaksudkan untuk mengetahui atau mengenal lebih lanjut mengenai ahli waris dari korban bencana yang meninggal dunia.
Petugas dari instansi/lembaga yang berwenang, mengidentifikasi karakteristik korban dan ahli waris (calon penerima bantuan) sebagai kelengkapan data, dengan format identifikasi (lampiran 2).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9131, 'BAB IV MEKANISME PEMBERIAN BANTUAN A. Persiapan
1. Pendataan Pendataan adalah kegiatan pengumpulan data yang bertujuan untuk menyediakan data yang lengkap, terpercaya dan dapat dipertanggungjawabkan mengenai keseluruhan jumlah korban bencana yang meninggal dunia pada suatu wilayah lokasi bencana. Pendataan dapat dilakukan pada saat tanggap darurat dan pasca bencana di lokasi bencana maupun di lokasi pengungsian.
Pendataan dilakukan oleh para petugas dari instansi/lembaga yang berwenang, dengan menggunakan format isian (lampiran 1).
2. Identifikasi Identifikasi merupakan langkah lanjutan setelah pendataan, yang dimaksudkan untuk mengetahui atau mengenal lebih lanjut mengenai ahli waris dari korban bencana yang meninggal dunia.
Petugas dari instansi/lembaga yang berwenang, mengidentifikasi karakteristik korban dan ahli waris (calon penerima bantuan) sebagai kelengkapan data, dengan format identifikasi (lampiran 2).', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9132, 'perka-8-2008', 20, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'Jika korban yang meninggal dunia tidak lagi meninggalkan keluarga, dalam pengertian bahwa korban tersebut hidup sebatang kara atau seluruh keluarga juga meninggal dunia, maka petugas perlu mengidentifikasi saudara atau kerabat dari korban bencana yang meninggal dunia. Dalam hal ini petugas tersebut mencari dan menemukan siapa yang paling bertanggung jawab terhadap korban. Seandainya sudah tidak terdapat saudara atau kerabat korban, maka pemuka masyarakat seperti Ketua RT/RW atau tokoh agama bisa menjadi pihak yang bertanggungjawab terhadap pengurusan pemakaman korban. Salah satu pihak tersebut diatas dapat direkomendasikan oleh petugas untuk menerima santunan duka cita dan diberikan kewenangan untuk mengurus segala sesuatu berkaitan dengan pemakaman dan upacara ritual keagamaan sesuai kebiasaan yang berlaku pada keluarga korban.
3. Verifikasi Hasil identifikasi sebagaimana tahap 4.1. point B diatas, selanjutnya dilaporkan oleh petugas kepada pimpinan lembaga yang berwenang memberikan bantuan santunan duka cita.
Lembaga yang berwenang kemudian memiliki kewajiban melakukan verifikasi terhadap kebenaran laporan petugas identifikasi. Hal ini dapat dilakukan dengan cara menugaskan bagian/sub bagian teknis atau petugas seksi penyaluran bantuan untuk melaksanakan verifikasi ke lapangan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9132, 'Jika korban yang meninggal dunia tidak lagi meninggalkan keluarga, dalam pengertian bahwa korban tersebut hidup sebatang kara atau seluruh keluarga juga meninggal dunia, maka petugas perlu mengidentifikasi saudara atau kerabat dari korban bencana yang meninggal dunia. Dalam hal ini petugas tersebut mencari dan menemukan siapa yang paling bertanggung jawab terhadap korban. Seandainya sudah tidak terdapat saudara atau kerabat korban, maka pemuka masyarakat seperti Ketua RT/RW atau tokoh agama bisa menjadi pihak yang bertanggungjawab terhadap pengurusan pemakaman korban. Salah satu pihak tersebut diatas dapat direkomendasikan oleh petugas untuk menerima santunan duka cita dan diberikan kewenangan untuk mengurus segala sesuatu berkaitan dengan pemakaman dan upacara ritual keagamaan sesuai kebiasaan yang berlaku pada keluarga korban.
3. Verifikasi Hasil identifikasi sebagaimana tahap 4.1. point B diatas, selanjutnya dilaporkan oleh petugas kepada pimpinan lembaga yang berwenang memberikan bantuan santunan duka cita.
Lembaga yang berwenang kemudian memiliki kewajiban melakukan verifikasi terhadap kebenaran laporan petugas identifikasi. Hal ini dapat dilakukan dengan cara menugaskan bagian/sub bagian teknis atau petugas seksi penyaluran bantuan untuk melaksanakan verifikasi ke lapangan.', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9133, 'perka-8-2008', 21, 'lampiran', 'Lampiran hal. 12', NULL, 12, 'Verifikasi dilakukan dengan cara mendatangi pihak-pihak yang memiliki hubungan dengan korban bencana calon penerima bantuan, untuk mengecek kebenaran data dan informasi yang dibuat petugas identifikasi. Petugas verifikasi dapat menghubungi langsung orang-orang yang termasuk keluarga korban, saudara, kerabat atau pemuka masyarakat, mengajukan pertanyaan-pertanyaan, mengobservasi, mencatat dan mendokumentasikan bukti-bukti kebenaran data dan informasi tentang korban yang sudah dimiliki sebelumnya.
Sebagian dari orang-orang yang dihubungi petugas verifikasi disamping menjadi sumber informasi juga diminta bertindak sebagai saksi atas kebenaran data identifikasi dengan membubuhkan tandatangannya pada lembaran hasil verifikasi, jika ternyata data dan informasi petugas identifikasi benar adanya.
Kegiatan pendataan yang dilakukan dikoordinasikan oleh BNPB dan atau BPBD.
Hasil pendataan, identifikasi dan verifikasi yang telah dilakukan kemudian dirapatkan oleh BNPB dan atau BPBD, untuk kemudian diputuskan .
B. Pelaksanaan Penyaluran santunan duka cita dilakukan setelah langkah persiapan.
Petugas penyaluran santunan dapat menghubungi langsung ahli waris dari korban bencana yang menjadi sasaran bantuan (sanak keluarga/kerabat) dari korban yang meninggal dunia.
Proses penyerahan bantuan dapat mengikuti tata cara formal sebagai berikut:
1. Pembukaan Pembukaan dapat dilakukan oleh petugas pemberi bantuan atau oleh pemuka masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9133, 'Verifikasi dilakukan dengan cara mendatangi pihak-pihak yang memiliki hubungan dengan korban bencana calon penerima bantuan, untuk mengecek kebenaran data dan informasi yang dibuat petugas identifikasi. Petugas verifikasi dapat menghubungi langsung orang-orang yang termasuk keluarga korban, saudara, kerabat atau pemuka masyarakat, mengajukan pertanyaan-pertanyaan, mengobservasi, mencatat dan mendokumentasikan bukti-bukti kebenaran data dan informasi tentang korban yang sudah dimiliki sebelumnya.
Sebagian dari orang-orang yang dihubungi petugas verifikasi disamping menjadi sumber informasi juga diminta bertindak sebagai saksi atas kebenaran data identifikasi dengan membubuhkan tandatangannya pada lembaran hasil verifikasi, jika ternyata data dan informasi petugas identifikasi benar adanya.
Kegiatan pendataan yang dilakukan dikoordinasikan oleh BNPB dan atau BPBD.
Hasil pendataan, identifikasi dan verifikasi yang telah dilakukan kemudian dirapatkan oleh BNPB dan atau BPBD, untuk kemudian diputuskan .
B. Pelaksanaan Penyaluran santunan duka cita dilakukan setelah langkah persiapan.
Petugas penyaluran santunan dapat menghubungi langsung ahli waris dari korban bencana yang menjadi sasaran bantuan (sanak keluarga/kerabat) dari korban yang meninggal dunia.
Proses penyerahan bantuan dapat mengikuti tata cara formal sebagai berikut:
1. Pembukaan Pembukaan dapat dilakukan oleh petugas pemberi bantuan atau oleh pemuka masyarakat.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9134, 'perka-8-2008', 22, 'lampiran', 'Lampiran hal. 13', NULL, 13, '2. Kata Sambutan Penyampaian pesan oleh petugas pemberi bantuan dan sambutan oleh korban bencana atau yang mewakili.
3. Penyerahan Bantuan Penyerahan bantuan santunan oleh petugas kepada sasaran dilakukan secara terbuka (transparan) dihadapan saksi-saksi yang sebelumnya diminta oleh petugas. Orang-orang yang diminta bertindak sebagai saksi adalah orang-orang yang mengetahui seluk beluk bencana yang dialami oleh korban, yang pada tahap verifikasi memberikan keterangan atas kebenaran data dan informasi yang diverifikasi.
4. Penandatanganan Berita Acara Serah terima bantuan santunan didokumentasikan dalam bentuk berita acara serah terima bantuan yang ditandatangani oleh petugas, sasaran dan saksi-saksi. Format Berita Acara Penyerahan Bantuan dapat dilihat dalam lampiran 3.
Selain itu, proses serah terima bantuan santunan bisa didokumentasikan dalam bentuk foto kegiatan.
5. Penutup Kata penutup dilakukan oleh pembawa acara dan bisa disisipkan didalamnya dengan pembacaan doa.
C. Ketentuan Khusus
1. Alokasi Bantuan Santunan Duka Cita
a. Korban yang meninggal akibat bencana sampai dengan 5 orang per lokasi kejadian pada kabupaten/kota, mendapat santunan dari pemerintah kabupaten/kota setempat.
b. Korban yang meninggal akibat bencana lebih dari 5 sampai dengan 10 orang per lokasi kejadian pada kabupaten/kota, mendapat santunan dari pemerintah provinsi setempat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9134, '2. Kata Sambutan Penyampaian pesan oleh petugas pemberi bantuan dan sambutan oleh korban bencana atau yang mewakili.
3. Penyerahan Bantuan Penyerahan bantuan santunan oleh petugas kepada sasaran dilakukan secara terbuka (transparan) dihadapan saksi-saksi yang sebelumnya diminta oleh petugas. Orang-orang yang diminta bertindak sebagai saksi adalah orang-orang yang mengetahui seluk beluk bencana yang dialami oleh korban, yang pada tahap verifikasi memberikan keterangan atas kebenaran data dan informasi yang diverifikasi.
4. Penandatanganan Berita Acara Serah terima bantuan santunan didokumentasikan dalam bentuk berita acara serah terima bantuan yang ditandatangani oleh petugas, sasaran dan saksi-saksi. Format Berita Acara Penyerahan Bantuan dapat dilihat dalam lampiran 3.
Selain itu, proses serah terima bantuan santunan bisa didokumentasikan dalam bentuk foto kegiatan.
5. Penutup Kata penutup dilakukan oleh pembawa acara dan bisa disisipkan didalamnya dengan pembacaan doa.
C. Ketentuan Khusus
1. Alokasi Bantuan Santunan Duka Cita
a. Korban yang meninggal akibat bencana sampai dengan 5 orang per lokasi kejadian pada kabupaten/kota, mendapat santunan dari pemerintah kabupaten/kota setempat.
b. Korban yang meninggal akibat bencana lebih dari 5 sampai dengan 10 orang per lokasi kejadian pada kabupaten/kota, mendapat santunan dari pemerintah provinsi setempat.', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9135, 'perka-8-2008', 23, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'Dalam hal ini pejabat yang berwenang di pemerintah kabupaten/kota mengajukan usulan bantuan santunan duka cita kepada pemerintah provinsi.
c. Korban yang meninggal akibat bencana lebih dari 10 orang per lokasi kejadian pada kabupaten/kota, mendapat santunan dari Pemerintah (Departemen Sosial RI). Dalam hal ini pejabat yang berwenang di pemerintah provinsi mengajukan usulan bantuan santunan duka cita kepada pemerintah.
2. Persyaratan Usulan Bantuan Santunan Duka Cita Usulan untuk memperoleh bantuan santunan duka cita ke pemerintah dilengkapi dengan persyaratan sebagai berikut :
a. Laporan jenis kejadian bencana oleh BPBD setempat.
b. Surat keterangan meninggal bagi korban bencana dari RT/RW dan Kepala Desa/Lurah setempat/Dokter/Rumah Sakit.
c. Surat keterangan Ahli Waris dari RT/RW dan Kepala Desa/ Lurah setempat.
d. Fotocopy Kartu Tanda Pengenal (KTP) dan atau Kartu Keluarga (KK) milik korban dan ahli waris korban yang dilegalisir.
e. Daftar nama-nama calon ahli waris dari BPBD provinsi dan atau kabupaten/kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9135, 'Dalam hal ini pejabat yang berwenang di pemerintah kabupaten/kota mengajukan usulan bantuan santunan duka cita kepada pemerintah provinsi.
c. Korban yang meninggal akibat bencana lebih dari 10 orang per lokasi kejadian pada kabupaten/kota, mendapat santunan dari Pemerintah (Departemen Sosial RI). Dalam hal ini pejabat yang berwenang di pemerintah provinsi mengajukan usulan bantuan santunan duka cita kepada pemerintah.
2. Persyaratan Usulan Bantuan Santunan Duka Cita Usulan untuk memperoleh bantuan santunan duka cita ke pemerintah dilengkapi dengan persyaratan sebagai berikut :
a. Laporan jenis kejadian bencana oleh BPBD setempat.
b. Surat keterangan meninggal bagi korban bencana dari RT/RW dan Kepala Desa/Lurah setempat/Dokter/Rumah Sakit.
c. Surat keterangan Ahli Waris dari RT/RW dan Kepala Desa/ Lurah setempat.
d. Fotocopy Kartu Tanda Pengenal (KTP) dan atau Kartu Keluarga (KK) milik korban dan ahli waris korban yang dilegalisir.
e. Daftar nama-nama calon ahli waris dari BPBD provinsi dan atau kabupaten/kota.', 'Lampiran hal. 14', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2008 tentang Pedoman Pemberian dan Besaran Bantuan Santunan Duka Cita');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9136, 'perka-8-2008', 24, 'lampiran', 'Lampiran hal. 14', NULL, 14, '3. Dalam situasi dimana keberadaan korban bencana yang memenuhi karakteristik penerima bantuan santunan tidak diketahui sehingga ahli waris dari korban yang meninggal dunia tidak mendapatkan hak-haknya, maka ahli waris bisa mengajukan surat permohonan yang diketahui oleh Kepala Desa/Lurah setempat untuk mendapatkan bantuan dari instansi/lembaga yang berwenang memberikan bantuan duka cita. Contoh Formulir Permohonan Mendapatkan Santunan Duka Cita dapat dilihat pada lampiran 4.
BAB V PENUTUP Pelaksanaan tugas pemberian bantuan santunan duka cita kepada ahli waris dari korban bencana yang meninggal dunia akan dapat berjalan lancar, tertib dan efektif apabila semua pihak yang berkepentingan baik pemerintah, pemerintah daerah maupun masyarakat memperhatikan dan mengacu pada pedoman ini beserta peraturan perundang-undangan terkait yang masih berlaku.
Hal-hal teknis lainnya yang belum tercantum dalam pedoman ini, dapat dilihat dalam panduan yang dijabarkan oleh instansi/lembaga terkait sesuai dengan karakteristik dan kebutuhan masing-masing.
KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si.
LAMPIRAN Lampiran - 01 FORMAT PENDATAAN Alamat Tempat Kondisi No Nama L/ P Tinggal Korban 1 2 3 4 5 dst ………….., … …………… ...… Petugas Identifikasi, __________________________ Nama lengkap dan tanda tangan Petunjuk Pengisian :
• Kolom 1 berisi nomor urut yang keseluruhannya berfungsi untuk mengetahui jumlah korban bencana yang dicatat.');
