INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9137, 'perka-8-2008', 25, 'lampiran', 'Lampiran hal. 17', NULL, 17, '• Kolom 2 berisi nama korban yang diupayakan sebisa mungkin lengkap keterkaitannya dengan nama orangtua. Misalnya A bin B atau C binti D. Kolom 3 berisi keterangan tentang jenis kelamin apakah laki-laki (L) atau perempuan (P).
• Kolom 4 berisi keterangan tentang alamat korban yang sebisa mungkin lengkap dengan nama jalan, nomor rumah, RT/RW, Kelurahan/Desa, Kecamatan dan Kota/Kabupaten.
• Kolom 5 berisi kondisi korban yang memberikan informasi apakah korban bencana yang dicatat meninggal dunia.
