INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9138, 'perka-8-2008', 26, 'lampiran', 'Lampiran hal. 18', NULL, 18, '• Riwayat singkat kematian Pada bagian ini petugas bisa memaparkan secara singkat (1) penyebab kematian korban, seperti meninggal karena bencana gempa, banjir, tanah longsor, dan lain-lain; (2) ciri-ciri masalah korban, misalnya korban meninggal dalam keadaan cacat ringan, sedang atau berat seperti kehilangan sebelah tangan, kaki, hilang ingatan, dan lain-lain;
(3) lokasi kematian, misalnya korban meninggal di tempat kejadian bencana, meninggal di tempat penampungan, meninggal di rumah sakit, dan lain-lain.
• Rekomendasi petugas Petugas identifikasi dapat merekomendasikan bantuan santunan duka cita bagi ahli waris korban yang ditinggalkan yang paling bertanggungjawab terhadap kelangsungan keluarga korban tersebut. …………….., … …………… ...… Petugas Identifikasi, __________________________ Nama lengkap dan tanda tangan *) coret yang tidak perlu Lampiran - 03 FORMAT BERITA ACARA PENYERAHAN BANTUAN BERITA ACARA PENYERAHAN BANTUAN SANTUNAN DUKA CITA Pada hari ini .........., tanggal ....., bulan..... tahun......., bertempat di................ telah dilaksanakan serah terima bantuan santunan duka cita sebesar Rp............................... (terbilang : .........................................................), dari:
Nama petugas : ........................................ (L/P *) Instansi : ........................................
Alamat : ........................................ untuk korban bencana .................di ...........');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9138, '• Riwayat singkat kematian Pada bagian ini petugas bisa memaparkan secara singkat (1) penyebab kematian korban, seperti meninggal karena bencana gempa, banjir, tanah longsor, dan lain-lain; (2) ciri-ciri masalah korban, misalnya korban meninggal dalam keadaan cacat ringan, sedang atau berat seperti kehilangan sebelah tangan, kaki, hilang ingatan, dan lain-lain;
(3) lokasi kematian, misalnya korban meninggal di tempat kejadian bencana, meninggal di tempat penampungan, meninggal di rumah sakit, dan lain-lain.
