INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9147, 'perka-8-2011', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG STANDARDISASI DATA KEBENCANAAN.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9147, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG STANDARDISASI DATA KEBENCANAAN.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9148, 'perka-8-2011', 4, 'pasal', 'Pasal 1', NULL, 2, 'Standardisasi Data Kebencanaan merupakan panduan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/Lembaga dan pemangku kepentingan penanggulangan bencana agar pencatatan data bencana di seluruh Indonesia dapat dilakukan secara efisien dan efektif.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9148, 'Standardisasi Data Kebencanaan merupakan panduan bagi Badan Nasional Penanggulangan Bencana, Badan Penanggulangan Bencana Daerah, Instansi/Lembaga dan pemangku kepentingan penanggulangan bencana agar pencatatan data bencana di seluruh Indonesia dapat dilakukan secara efisien dan efektif.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9149, 'perka-8-2011', 5, 'pasal', 'Pasal 2', NULL, 2, 'Standardisasi data kebencanaan sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian tak terpisahkan dari peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9149, 'Standardisasi data kebencanaan sebagaimana dimaksud dalam Pasal 1 merupakan lampiran dan bagian tak terpisahkan dari peraturan ini.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9150, 'perka-8-2011', 6, 'pasal', 'Pasal 3', NULL, 2, 'Peraturan Kepala ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9150, 'Peraturan Kepala ini mulai berlaku pada tanggal ditetapkan.
Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Kepala ini dengan penempatannya dalam Berita Negara Republik Indonesia.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9151, 'perka-8-2011', 7, 'lain', 'Penutup', NULL, 2, 'Ditetapkan di Jakarta pada tanggal 14 Oktober 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 11 Agustus 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 3 2014, No.1093');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9151, 'Ditetapkan di Jakarta pada tanggal 14 Oktober 2011 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 11 Agustus 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN 3 2014, No.1093', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9152, 'perka-8-2011', 8, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 8 TAHUN 2011 TENTANG STANDARDISASI DATA KEBENCANAAN BAB I PENDAHULUAN A. Latar Belakang Indonesia termasuk daerah yang rawan bencana dan memiliki jumlah penduduk yang besar. Bencana yang datang dapat disebabkan oleh faktor alam maupun akibat dari ulah manusia. Hal ini terbukti dengan semakin meningkatnya jumlah kejadian bencana setiap tahunnya. Bencana seperti gempa bumi, tanah longsor, banjir, angin topan, letusan gunungapi, kebakaran, kebakaran hutan dan lahan, kecelakaan transportasi, dan kecelakaan industri sering kali menjadi ancaman yang serius bagi peduduk Indonesia. Ancaman bencana dapat menyebabkan korban jiwa dan kerusakan harta benda.
Trend kejadian bencana menunjukkan peningkatan kejadian bencana dari tahun ke tahun. Pencatatan data bencana yang sistematis akan mempermudah dalam pengolahan data bencana, membantu dalam perencanaan pengurangan risiko bencana serta program rehabilitasi dan rekonstruksi pasca bencana ke depannya. Terdapat perbedaan format pelaporan data antara provinsi/kabupaten/kota yang satu dengan yang lain. Format yang berbeda tersebut menyebabkan kesulitan dalam membuat rekapitulasi data bencana secara nasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9152, 'LAMPIRAN PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 8 TAHUN 2011 TENTANG STANDARDISASI DATA KEBENCANAAN BAB I PENDAHULUAN A. Latar Belakang Indonesia termasuk daerah yang rawan bencana dan memiliki jumlah penduduk yang besar. Bencana yang datang dapat disebabkan oleh faktor alam maupun akibat dari ulah manusia. Hal ini terbukti dengan semakin meningkatnya jumlah kejadian bencana setiap tahunnya. Bencana seperti gempa bumi, tanah longsor, banjir, angin topan, letusan gunungapi, kebakaran, kebakaran hutan dan lahan, kecelakaan transportasi, dan kecelakaan industri sering kali menjadi ancaman yang serius bagi peduduk Indonesia. Ancaman bencana dapat menyebabkan korban jiwa dan kerusakan harta benda.
Trend kejadian bencana menunjukkan peningkatan kejadian bencana dari tahun ke tahun. Pencatatan data bencana yang sistematis akan mempermudah dalam pengolahan data bencana, membantu dalam perencanaan pengurangan risiko bencana serta program rehabilitasi dan rekonstruksi pasca bencana ke depannya. Terdapat perbedaan format pelaporan data antara provinsi/kabupaten/kota yang satu dengan yang lain. Format yang berbeda tersebut menyebabkan kesulitan dalam membuat rekapitulasi data bencana secara nasional.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9153, 'perka-8-2011', 9, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'Badan Nasional Penanggulangan Bencana (BNPB) sebagai badan negara yang menangani masalah bencana perlu membakukan dan menyeragamkan data bencana di seluruh wilayah Indonesia. Standardisasi data kebencanaan disusun agar dapat menjadi acuan dan pedoman bagi Badan Penanggulangan Bencana Daerah (BPBD) dalam pelaporan kejadian bencana. Dalam standardisasi data kebencanaan ini, terdiri dari data pra bencana, tanggap darurat dan pasca bencana.
B. Tujuan Standardisasi data kebencanaan bertujuan untuk:
1. Menyamakan persepsi antara BNPB, BPBD, Kementerian/Lembaga Terkait dan pemangku kepentingan lainnya yang melakukan pengelelaan data bencana.
2014, No.1093 4
2. Memberikan panduan dalam pengelelaan data bencana.
3. Mempermudah BNPB, BPBD, Kementerian/Lembaga Terkait dan pemangku kepentingan lainya dalam pengumpulan, pemresesan, analisis dan pelaperan data bencana, pada saat pra bencana, tanggap darurat maupun rehabilitasi dan rekenstruksi.
C. Landasan Hukum
1. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah;
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana;
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana;
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana;
5. Peraturan Kepala BNPB Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja BNPB;
6. Peraturan Kepala BNPB Nomor 3 Tahun 2008 tentang Pedoman Pembentukan Badan Penanggulangan Bencana Daerah;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9153, 'Badan Nasional Penanggulangan Bencana (BNPB) sebagai badan negara yang menangani masalah bencana perlu membakukan dan menyeragamkan data bencana di seluruh wilayah Indonesia. Standardisasi data kebencanaan disusun agar dapat menjadi acuan dan pedoman bagi Badan Penanggulangan Bencana Daerah (BPBD) dalam pelaporan kejadian bencana. Dalam standardisasi data kebencanaan ini, terdiri dari data pra bencana, tanggap darurat dan pasca bencana.
B. Tujuan Standardisasi data kebencanaan bertujuan untuk:
1. Menyamakan persepsi antara BNPB, BPBD, Kementerian/Lembaga Terkait dan pemangku kepentingan lainnya yang melakukan pengelelaan data bencana.
2014, No.1093 4
2. Memberikan panduan dalam pengelelaan data bencana.
3. Mempermudah BNPB, BPBD, Kementerian/Lembaga Terkait dan pemangku kepentingan lainya dalam pengumpulan, pemresesan, analisis dan pelaperan data bencana, pada saat pra bencana, tanggap darurat maupun rehabilitasi dan rekenstruksi.
C. Landasan Hukum
1. Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah;
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana;
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana;
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana;
5. Peraturan Kepala BNPB Nomor 1 Tahun 2008 tentang Organisasi dan Tata Kerja BNPB;
6. Peraturan Kepala BNPB Nomor 3 Tahun 2008 tentang Pedoman Pembentukan Badan Penanggulangan Bencana Daerah;', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9154, 'perka-8-2011', 10, 'lampiran', 'Lampiran hal. 4', NULL, 4, '7. Peraturan Kepala BNPB Nomor 07 Tahun 2008 tentang Pedoman Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar;
8. Peraturan Kepala BNPB Nomor 09 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat BNPB;
9. Peraturan Kepala BNPB Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pasca Bencana;
10. Peraturan Kepala BNPB Nomor 13 Tahun 2008 tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana;
11. Peraturan Kepala BNPB Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik;
12. Peraturan Kepala BNPB Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan;
D. Pengertian
1. Standardisasi adalah penyesuaian bentuk yang meliputi ukuran, kualitas, dan sebagainya dengan pedoman (standar) yang telah ditetapkan.
2. Standardisasi Data Kebencanaan adalah pedoman bagi BNPB, BPBD, Kementerian/Lembaga Terkait dan pemangku kepentingan lainya dalam pengumpulan, pemrosesan, analisis data, interpretasi dan penyajian yang menghasilkan informasi berupa pelaporan dan publikasi pada saat pra bencana, saat maupun pasca bencana.
3. Organisasi Perangkat Daerah adalah organisasi pernagkat yang ditetapkan dengan Peraturan Daerah dengan berpedoman pada 5 2014, No.1093 Peraturan Pemerintah yang mengatur mengenai susunan, kedudukan dan tugas pokok organisasi perangkat daerah.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9154, '7. Peraturan Kepala BNPB Nomor 07 Tahun 2008 tentang Pedoman Tata Cara Pemberian Bantuan Pemenuhan Kebutuhan Dasar;
8. Peraturan Kepala BNPB Nomor 09 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat BNPB;
9. Peraturan Kepala BNPB Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pasca Bencana;
10. Peraturan Kepala BNPB Nomor 13 Tahun 2008 tentang Pedoman Manajemen Logistik dan Peralatan Penanggulangan Bencana;
11. Peraturan Kepala BNPB Nomor 4 Tahun 2009 tentang Pedoman Bantuan Logistik;
12. Peraturan Kepala BNPB Nomor 5 Tahun 2009 tentang Pedoman Bantuan Peralatan;
D. Pengertian
1. Standardisasi adalah penyesuaian bentuk yang meliputi ukuran, kualitas, dan sebagainya dengan pedoman (standar) yang telah ditetapkan.
2. Standardisasi Data Kebencanaan adalah pedoman bagi BNPB, BPBD, Kementerian/Lembaga Terkait dan pemangku kepentingan lainya dalam pengumpulan, pemrosesan, analisis data, interpretasi dan penyajian yang menghasilkan informasi berupa pelaporan dan publikasi pada saat pra bencana, saat maupun pasca bencana.
3. Organisasi Perangkat Daerah adalah organisasi pernagkat yang ditetapkan dengan Peraturan Daerah dengan berpedoman pada 5 2014, No.1093 Peraturan Pemerintah yang mengatur mengenai susunan, kedudukan dan tugas pokok organisasi perangkat daerah.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9155, 'perka-8-2011', 11, 'lampiran', 'Lampiran hal. 5', NULL, 5, '4. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
5. Bencana alam adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang disebabkan oleh alam antara lain berupa gempa bumi, tsunami, gunung meletus, banjir, kekeringan, angin topan dan tanah longsor.
6. Bencana non alam adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa non alam antara lain berupa gagal teknologi, gagal modernisasi, epidemi, dan wabah penyakit.
7. Bencana sosial adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang diakibatkan oleh manusia yang meliputi konflik sosial antar kelompok atau antar komunitas masyarakat, dan teror.
8. Kejadian Bencana adalah peristiwa bencana yang terjadi dan dicatat berdasarkan tanggal kejadian, lokasi, jenis bencana, korban dan/ataupun kerusakan. Jika terjadi bencana pada tanggal yang sama dan melanda lebih dari satu wilayah, maka dihitung sebagai satu kejadian.
9. Gempa bumi adalah getaran atau guncangan yang terjadi di permukaan bumi yang disebabkan oleh tumbukan antar lempeng bumi, patahan aktif, akitivitas gunung api atau runtuhan batuan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9155, '4. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor non alam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa, kerusakan lingkungan, kerugian harta benda dan dampak psikologis.
5. Bencana alam adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang disebabkan oleh alam antara lain berupa gempa bumi, tsunami, gunung meletus, banjir, kekeringan, angin topan dan tanah longsor.
6. Bencana non alam adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa non alam antara lain berupa gagal teknologi, gagal modernisasi, epidemi, dan wabah penyakit.
7. Bencana sosial adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang diakibatkan oleh manusia yang meliputi konflik sosial antar kelompok atau antar komunitas masyarakat, dan teror.
8. Kejadian Bencana adalah peristiwa bencana yang terjadi dan dicatat berdasarkan tanggal kejadian, lokasi, jenis bencana, korban dan/ataupun kerusakan. Jika terjadi bencana pada tanggal yang sama dan melanda lebih dari satu wilayah, maka dihitung sebagai satu kejadian.
9. Gempa bumi adalah getaran atau guncangan yang terjadi di permukaan bumi yang disebabkan oleh tumbukan antar lempeng bumi, patahan aktif, akitivitas gunung api atau runtuhan batuan.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9156, 'perka-8-2011', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, '10. Letusan gunung api merupakan bagian dari aktivitas vulkanik yang dikenal dengan istilah "erupsi". Bahaya letusan gunung api dapat berupa awan panas, lontaran material (pijar), hujan abu lebat, lava, gas racun, tsunami dan banjir lahar.
11. Tsunami berasal dari bahasa Jepang yang berarti gelombang ombak lautan ("tsu" berarti lautan, "nami" berarti gelombang ombak). Tsunami adalah serangkaian gelombang ombak laut raksasa yang timbul karena adanya pergeseran di dasar laut akibat gempa bumi.
12. Tanah longsor merupakan salah satu jenis gerakan massa tanah atau batuan, ataupun percampuran keduanya, menuruni atau keluar lereng akibat terganggunya kestabilan tanah atau batuan penyusun lereng.
13. Banjir adalah peristiwa atau keadaan dimana terendamnya suatu daerah atau daratan karena volume air yang meningkat.
14. Banjir bandang adalah banjir yang datang secara tiba-tiba dengan debit air yang besar yang disebabkan terbendungnya aliran sungai pada alur sungai.
2014, No.1093 6
15. Kekeringan adalah ketersediaan air yang jauh di bawah kebutuhan air untuk kebutuhan hidup, pertanian, kegiatan ekonomi dan lingkungan.
Adapun yang dimaksud kekeringan di bidang pertanian adalah kekeringan yang terjadi di lahan pertanian yang ada tanaman (padi, jagung, kedelai dan lain-lain) yang sedang dibudidayakan.
16. Kebakaran adalah situasi dimana bangunan pada suatu tempat seperti rumah/pemukiman, pabrik, pasar, gedung dan lain-lain dilanda api yang menimbulkan korban dan/atau kerugian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9156, '10. Letusan gunung api merupakan bagian dari aktivitas vulkanik yang dikenal dengan istilah "erupsi". Bahaya letusan gunung api dapat berupa awan panas, lontaran material (pijar), hujan abu lebat, lava, gas racun, tsunami dan banjir lahar.
11. Tsunami berasal dari bahasa Jepang yang berarti gelombang ombak lautan ("tsu" berarti lautan, "nami" berarti gelombang ombak). Tsunami adalah serangkaian gelombang ombak laut raksasa yang timbul karena adanya pergeseran di dasar laut akibat gempa bumi.
12. Tanah longsor merupakan salah satu jenis gerakan massa tanah atau batuan, ataupun percampuran keduanya, menuruni atau keluar lereng akibat terganggunya kestabilan tanah atau batuan penyusun lereng.
13. Banjir adalah peristiwa atau keadaan dimana terendamnya suatu daerah atau daratan karena volume air yang meningkat.
14. Banjir bandang adalah banjir yang datang secara tiba-tiba dengan debit air yang besar yang disebabkan terbendungnya aliran sungai pada alur sungai.
2014, No.1093 6
15. Kekeringan adalah ketersediaan air yang jauh di bawah kebutuhan air untuk kebutuhan hidup, pertanian, kegiatan ekonomi dan lingkungan.
Adapun yang dimaksud kekeringan di bidang pertanian adalah kekeringan yang terjadi di lahan pertanian yang ada tanaman (padi, jagung, kedelai dan lain-lain) yang sedang dibudidayakan.
16. Kebakaran adalah situasi dimana bangunan pada suatu tempat seperti rumah/pemukiman, pabrik, pasar, gedung dan lain-lain dilanda api yang menimbulkan korban dan/atau kerugian.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9157, 'perka-8-2011', 13, 'lampiran', 'Lampiran hal. 6', NULL, 6, '17. Kebakaran hutan dan lahan adalah suatu keadaan di mana hutan dan lahan dilanda api, sehingga mengakibatkan kerusakan hutan dan lahan yang menimbulkan kerugian ekonomis dan atau nilai lingkungan.
Kebakaran hutan dan lahan seringkali menyebabkan bencana asap yang dapat mengganggu aktivitas dan kesehatan masyarakat sekitar.
18. Angin puting beliung adalah angin kencang yang datang secara tiba-tiba, mempunyai pusat, bergerak melingkar menyerupai spiral dengan kecepatan 40-50 km/jam hingga menyentuh permukaan bumi dan akan hilang dalam waktu singkat (3-5 menit).
19. Gelombang pasang atau badai adalah gelombang tinggi yang ditimbulkan karena efek terjadinya siklon tropis di sekitar wilayah Indonesia dan berpotensi kuat menimbulkan bencana alam. Indonesia bukan daerah lintasan siklon tropis tetapi keberadaan siklon tropis akan memberikan pengaruh kuat terjadinya angin kencang, gelombang tinggi disertai hujan deras.
20. Abrasi adalah proses pengikisan pantai oleh tenaga gelombang laut dan arus laut yang bersifat merusak. Abrasi biasanya disebut juga erosi pantai. Kerusakan garis pantai akibat abrasi ini dipicu oleh terganggunya keseimbangan alam daerah pantai tersebut. Walaupun abrasi bisa disebabkan oleh gejala alami, namun manusia sering disebut sebagai penyebab utama abrasi.
21. Kecelakaan transportasi adalah kecelakaan moda transportasi yang terjadi di darat, laut dan udara.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9157, '17. Kebakaran hutan dan lahan adalah suatu keadaan di mana hutan dan lahan dilanda api, sehingga mengakibatkan kerusakan hutan dan lahan yang menimbulkan kerugian ekonomis dan atau nilai lingkungan.
Kebakaran hutan dan lahan seringkali menyebabkan bencana asap yang dapat mengganggu aktivitas dan kesehatan masyarakat sekitar.
18. Angin puting beliung adalah angin kencang yang datang secara tiba-tiba, mempunyai pusat, bergerak melingkar menyerupai spiral dengan kecepatan 40-50 km/jam hingga menyentuh permukaan bumi dan akan hilang dalam waktu singkat (3-5 menit).
19. Gelombang pasang atau badai adalah gelombang tinggi yang ditimbulkan karena efek terjadinya siklon tropis di sekitar wilayah Indonesia dan berpotensi kuat menimbulkan bencana alam. Indonesia bukan daerah lintasan siklon tropis tetapi keberadaan siklon tropis akan memberikan pengaruh kuat terjadinya angin kencang, gelombang tinggi disertai hujan deras.
20. Abrasi adalah proses pengikisan pantai oleh tenaga gelombang laut dan arus laut yang bersifat merusak. Abrasi biasanya disebut juga erosi pantai. Kerusakan garis pantai akibat abrasi ini dipicu oleh terganggunya keseimbangan alam daerah pantai tersebut. Walaupun abrasi bisa disebabkan oleh gejala alami, namun manusia sering disebut sebagai penyebab utama abrasi.
21. Kecelakaan transportasi adalah kecelakaan moda transportasi yang terjadi di darat, laut dan udara.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9158, 'perka-8-2011', 14, 'lampiran', 'Lampiran hal. 6', NULL, 6, '22. Kecelakaan industri adalah kecelakaan yang disebabkan oleh dua faktor, yaitu perilaku kerja yang berbahaya (unsafe human act) dan kondisi yang berbahaya (unsafe conditions). Adapun jenis kecelakaan yang terjadi sangat bergantung pada macam industrinya, misalnya bahan dan peralatan kerja yang dipergunakan, proses kerja, kondisi tempat kerja, bahkan pekerja yang terlibat di dalamnya.
23. Kejadian Luar Biasa (KLB) adalah timbulnya atau meningkatnya kejadian kesakitan atau kematian yang bermakna secara epidemiologis pada suatu daerah dalam kurun waktu tertentu. Status Kejadian Luar Biasa diatur oleh Peraturan Menteri Kesehatan RI No.
949/MENKES/SK/VII/2004.
24. Konflik Sosial atau kerusuhan sosial atau huru hara adalah suatu gerakan massal yang bersifat merusak tatanan dan tata tertib sosial 7 2014, No.1093 yang ada, yang dipicu oleh kecemburuan sosial, budaya dan ekonomi yang biasanya dikemas sebagai pertentangan antar suku, agama, ras (SARA).
25. Aksi Teror adalah aksi yang dilakukan oleh setiap orang yang dengan sengaja menggunakan kekerasan atau ancaman kekerasan sehingga menimbulkan suasana teror atau rasa takut terhadap orang secara meluas atau menimbulkan korban yang bersifat masal, dengan cara merampas kemerdekaan sehingga mengakibatkan hilangnya nyawa dan harta benda, mengakibatkan kerusakan atau kehancuran terhadap obyek-obyek vital yang strategis atau lingkungan hidup atau fasilitas publik internasional.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9158, '22. Kecelakaan industri adalah kecelakaan yang disebabkan oleh dua faktor, yaitu perilaku kerja yang berbahaya (unsafe human act) dan kondisi yang berbahaya (unsafe conditions). Adapun jenis kecelakaan yang terjadi sangat bergantung pada macam industrinya, misalnya bahan dan peralatan kerja yang dipergunakan, proses kerja, kondisi tempat kerja, bahkan pekerja yang terlibat di dalamnya.
23. Kejadian Luar Biasa (KLB) adalah timbulnya atau meningkatnya kejadian kesakitan atau kematian yang bermakna secara epidemiologis pada suatu daerah dalam kurun waktu tertentu. Status Kejadian Luar Biasa diatur oleh Peraturan Menteri Kesehatan RI No.
949/MENKES/SK/VII/2004.
24. Konflik Sosial atau kerusuhan sosial atau huru hara adalah suatu gerakan massal yang bersifat merusak tatanan dan tata tertib sosial 7 2014, No.1093 yang ada, yang dipicu oleh kecemburuan sosial, budaya dan ekonomi yang biasanya dikemas sebagai pertentangan antar suku, agama, ras (SARA).
25. Aksi Teror adalah aksi yang dilakukan oleh setiap orang yang dengan sengaja menggunakan kekerasan atau ancaman kekerasan sehingga menimbulkan suasana teror atau rasa takut terhadap orang secara meluas atau menimbulkan korban yang bersifat masal, dengan cara merampas kemerdekaan sehingga mengakibatkan hilangnya nyawa dan harta benda, mengakibatkan kerusakan atau kehancuran terhadap obyek-obyek vital yang strategis atau lingkungan hidup atau fasilitas publik internasional.', 'Lampiran hal. 6', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9159, 'perka-8-2011', 15, 'lampiran', 'Lampiran hal. 7', NULL, 7, '26. Sabotase adalah tindakan yang dilakukan untuk melemahkan musuh melalui subversi, penghambatan, pengacauan dan/ atau penghancuran.
Dalam perang, istilah ini digunakan untuk mendiskripsikan aktivitas individu atau grup yang tidak berhubungan dengan militer, tetapi dengan spionase. Sabotase dapat dilakukan terhadap beberapa sruktur penting, seperti infrastruktur, struktur ekonomi, dan lain-lain.
27. Korban adalah orang/sekelompok orang yang mengalami dampak buruk akibat bencana, seperti kerusakan dan atau kerugian harta benda, penderitaan dan atau kehilangan jiwa. Korban dapat dipilah berdasarkan klasifikasi korban meninggal, hilang, luka/sakit, menderita dan mengungsi.
28. Korban meninggal adalah orang yang dilaporkan tewas atau meninggal dunia akibat bencana.
29. Korban hilang adalah orang yang dilaporkan hilang atau tidak ditemukan atau tidak diketahui keberadaannya setelah terjadi bencana.
30. Korban luka/sakit adalah orang yang mengalami luka-luka atau sakit, dalam keadaan luka ringan, maupun luka parah/berat, baik yang berobat jalan maupun rawat inap.
31. Penderita/terdampak adalah orang atau sekelompok orang yang menderita akibat dampak buruk bencana, seperti kerusakan dan atau kerugian harta benda, namun masih dapat menempati tempat tinggalnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9159, '26. Sabotase adalah tindakan yang dilakukan untuk melemahkan musuh melalui subversi, penghambatan, pengacauan dan/ atau penghancuran.
Dalam perang, istilah ini digunakan untuk mendiskripsikan aktivitas individu atau grup yang tidak berhubungan dengan militer, tetapi dengan spionase. Sabotase dapat dilakukan terhadap beberapa sruktur penting, seperti infrastruktur, struktur ekonomi, dan lain-lain.
27. Korban adalah orang/sekelompok orang yang mengalami dampak buruk akibat bencana, seperti kerusakan dan atau kerugian harta benda, penderitaan dan atau kehilangan jiwa. Korban dapat dipilah berdasarkan klasifikasi korban meninggal, hilang, luka/sakit, menderita dan mengungsi.
28. Korban meninggal adalah orang yang dilaporkan tewas atau meninggal dunia akibat bencana.
29. Korban hilang adalah orang yang dilaporkan hilang atau tidak ditemukan atau tidak diketahui keberadaannya setelah terjadi bencana.
30. Korban luka/sakit adalah orang yang mengalami luka-luka atau sakit, dalam keadaan luka ringan, maupun luka parah/berat, baik yang berobat jalan maupun rawat inap.
31. Penderita/terdampak adalah orang atau sekelompok orang yang menderita akibat dampak buruk bencana, seperti kerusakan dan atau kerugian harta benda, namun masih dapat menempati tempat tinggalnya.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9160, 'perka-8-2011', 16, 'lampiran', 'Lampiran hal. 7', NULL, 7, '32. Pengungsi adalah orang/sekelompok orang yang terpaksa atau dipaksa keluar dari tempat tinggalnya ketempat yang lebih aman dalam upaya menyelamatkan diri/jiwa untuk jangka waktu yang belum pasti sebagai akibat dampak buruk bencana.
33. Kerusakan harta benda meliputi rumah, fasilitas pendidikan (sekolah, madrasah atau pesantren), fasilitas kesehatan (rumah sakit, puskesmas, puskesmas pembantu/pustu), fasilitas peribadatan (masjid, gereja, vihara dan pura), bangunan lain (kantor, pasar, kios) dan jalan yang mengalami kerusakan (rusak ringan, sedang dan berat atau hancur atau roboh) serta sawah yang terkena bencana dan puso (gagal panen).
2014, No.1093 8
34. Rusak berat adalah kriteria kerusakan yang mengakibatkan bangunan roboh atau sebagian besar komponen struktur rusak, sebagai contoh : (1) bangunan roboh total/sebagian besar struktur utama bangunan rusak; (2) sebagian besar dinding dan lantai bangunan bendung atau dam patah; (3) sebagian besar tanggul jebol atau putus;
(4) saluran pengairan tidak dapat berfungsi).
35. Rusak sedang adalah kriteria kerusakan yang mengakibatkan sebagian kecil komponen struktur rusak, dan komponen penunjang rusak namun bangunan masih tetap berdiri, sebagai contoh : (1) sebagian kecil struktur utama bangunan rusak; (2) sebagian besar pintu-pintu air dan komponen penunjang lainnya rusak; (3) saluran pengairan terputus.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9160, '32. Pengungsi adalah orang/sekelompok orang yang terpaksa atau dipaksa keluar dari tempat tinggalnya ketempat yang lebih aman dalam upaya menyelamatkan diri/jiwa untuk jangka waktu yang belum pasti sebagai akibat dampak buruk bencana.
33. Kerusakan harta benda meliputi rumah, fasilitas pendidikan (sekolah, madrasah atau pesantren), fasilitas kesehatan (rumah sakit, puskesmas, puskesmas pembantu/pustu), fasilitas peribadatan (masjid, gereja, vihara dan pura), bangunan lain (kantor, pasar, kios) dan jalan yang mengalami kerusakan (rusak ringan, sedang dan berat atau hancur atau roboh) serta sawah yang terkena bencana dan puso (gagal panen).
2014, No.1093 8
34. Rusak berat adalah kriteria kerusakan yang mengakibatkan bangunan roboh atau sebagian besar komponen struktur rusak, sebagai contoh : (1) bangunan roboh total/sebagian besar struktur utama bangunan rusak; (2) sebagian besar dinding dan lantai bangunan bendung atau dam patah; (3) sebagian besar tanggul jebol atau putus;
(4) saluran pengairan tidak dapat berfungsi).
35. Rusak sedang adalah kriteria kerusakan yang mengakibatkan sebagian kecil komponen struktur rusak, dan komponen penunjang rusak namun bangunan masih tetap berdiri, sebagai contoh : (1) sebagian kecil struktur utama bangunan rusak; (2) sebagian besar pintu-pintu air dan komponen penunjang lainnya rusak; (3) saluran pengairan terputus.', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9161, 'perka-8-2011', 17, 'lampiran', 'Lampiran hal. 8', NULL, 8, '36. Rusak ringan adalah kriteria kerusakan yang mengakibatkan sebagian komponen struktur retak (struktur masih bisa digunakan) dan bangunan masih tetap berdiri, sebagai contoh : (1) sebagian kecil struktur bangunan rusak ringan; (2) retak-retak pada dinding plesteran;
(3) sebagian kecil pintu-pintu air dan komponen penunjang lainnya rusak; (4) saluran pengairan masih bisa digunakan.
37. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
38. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pascabencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.
39. Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta masyarakat dalam segala aspek kehidupan bermasyarakat pada wilayah pascabencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9161, '36. Rusak ringan adalah kriteria kerusakan yang mengakibatkan sebagian komponen struktur retak (struktur masih bisa digunakan) dan bangunan masih tetap berdiri, sebagai contoh : (1) sebagian kecil struktur bangunan rusak ringan; (2) retak-retak pada dinding plesteran;
(3) sebagian kecil pintu-pintu air dan komponen penunjang lainnya rusak; (4) saluran pengairan masih bisa digunakan.
37. Penyelenggaraan penanggulangan bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang berisiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
38. Rehabilitasi adalah perbaikan dan pemulihan semua aspek pelayanan publik atau masyarakat sampai tingkat yang memadai pada wilayah pascabencana dengan sasaran utama untuk normalisasi atau berjalannya secara wajar semua aspek pemerintahan dan kehidupan masyarakat pada wilayah pascabencana.
39. Rekonstruksi adalah pembangunan kembali semua prasarana dan sarana, kelembagaan pada wilayah pascabencana, baik pada tingkat pemerintahan maupun masyarakat dengan sasaran utama tumbuh dan berkembangnya kegiatan perekonomian, sosial dan budaya, tegaknya hukum dan ketertiban, dan bangkitnya peran serta masyarakat dalam segala aspek kehidupan bermasyarakat pada wilayah pascabencana.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 8 Tahun 2011 tentang Standarisasi Data Kebencanaan');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9162, 'perka-8-2011', 18, 'lampiran', 'Lampiran hal. 8', NULL, 8, '40. Logistik adalah sesuatu yang berwujud dan dapat digunakan untuk memenuhi kebutuhan dasar hidup manusia yang terdiri atas sandang, pangan dan papan atau turunannya. Termasuk dalam kategori logistik adalah barang yang habis pakai atau dikonsumsi, misalnya: sembako (sembilan bahan pokok), obat- obatan, pakaian dan kelengkapannya, air, tenda, jas tidur dan sebagainya.
41. Peralatan adalah segala bentuk alat dan peralatan yang dapat dipergunakan untuk membantu pencarian, penyelamatan dan evakuasi masyarakat terkena bencana, membantu pemenuhan kebutuhan dasar dan untuk pemulihan segera prasarana dan sarana vital.
9 2014, No.1093 E. Ruang Lingkup
1. Standardisasi data kebencanaan membahas tiga formulir yang digunakan dalam proses pendataan, yaitu: (1) Formulir Profil Daerah, (2) Formulir Kejadian Bencana, dan (3) Formulir Rehabilitasi dan Rekonstruksi.
2. Standardisasi data bencana ini berlaku bagi BNPB, BPBD, Kementerian/Lembaga Terkait dan pemangku kepentingan lainnya dalam pengumpulan, pengelolaan, pelaporan sampai penyusunan basis data kebencanaan di wilayah masing- masing.
F. Sistematika Standardisasi data kebencanaan ini disusun dengan sistematika sebagai berikut:');
