INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9174, 'perka-8-2011', 30, 'lampiran', 'Lampiran hal. 29', NULL, 29, 'Pengisian formulir ini mencakup penilaian kerusakan dan kerugian berikut status kepemilikan aset. Di samping penilaian formulir di atas, juga diperlukan pengisian untuk penilaian kebutuhan pemulihan kemanusiaan. Formulir tersebut mengacu pada Peraturan Kepala BNPB Nomor 11 Tahun 2008 tentang Pedoman Rehabilitasi dan Rekonstruksi Pasca Bencana.
Hasil pengisian ini digunakan untuk penilaian kebutuhan pasca bencana, sebagai hasil untuk pelaksanaan rehabilitasi dan rekonstruksi pasca bencana.
(Formulir lengkap untuk proses penilaian kerusakan dan kerugian serta kebutuhan pasca bencana, mengacu ke Pedoman Inventarisasi dan Verifikasi serta Pedoman Penilaian Kebutuhan Pasca Bencana). Formulir ini diisi oleh BPBD/OPD yang menangani bencana yang bersumber dari OPD yang mengelola data terkait dengan rehabilitasi dan rekonstruksi dengan petunjuk pengisian seperti Lampiran 3.
