INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9178, 'perka-8-2011', 34, 'lampiran', 'Lampiran hal. 35', NULL, 35, '9. Irigasi : diisi jenis irigasi (teknis, setengah teknis, non teknis), panjang saluran, jumlah bendungan air, dan jumlah pintu air.
10. Listrik : diisi jenis sumber energi (PLN, PLTD, PLTU, PLTA) dan daya tersambung (kva) per kecamatan.
11. Telekomunikasi : diisi jumlah sambungan telepon, jumlah tower, dan keterangan (penyedia layanan) per kecamatan.
12. Demografi : diisi jumlah penduduk berdasarkan klasifikasi usia dan jenis kelamin, mulai dari kurang 1 tahun sampai dengan lebih dari 60 tahun, dan total penduduk per kecamatan.
13. Sarana pendidikan : jumlah bangunan sekolah berdasarkan klasifikasi tingkat pendidikan dari TK, SLB, SD/MI, SMP/MTS, SMA/SMK/MA dan Perguruan Tinggi.
14. Bandar udara : diisi nama lokasi bandara, kelas bandara, panjang landasan, jenis landasan, disertai sarana dan prasarana.
15. Lokasi Pelabuhan Laut/Sungai/Danau : diisi nama Pelabuhan Laut/Sungai/Danau, kelas pelabuhan, panjang dermaga, sarana dan prasarana.
16. Sarana Kesehatan: diisi Rumah Sakit, Puskesmas, Pustu.
17. Sarana Peribadatan: diisi Jumlah masjid, gereja, pura, wihara dan lainnya.
Ketersediaan Sumber Daya
1. Logistik: diisi pangan, sandang, logistik lainya, paket kematian
2. Peralatan: diisi standar minimal jenis peralatan penanggulangan bencana
3. Sumber Daya Manusia: diisi relawan, tenaga kesehatan, TNI/Polri, tenaga SAR dan desa siaga.');
