INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9179, 'perka-8-2011', 35, 'lampiran', 'Lampiran hal. 36', NULL, 36, '2014, No.1093 36 LAMPIRAN II PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR 8 TAHUN 2011 TENTANG STANDARDISASI DATA KEBENCANAAN Petunjuk Pengisian Data Tanggap Darurat No Uraian
1. Kejadian Bencana
1. Jenis bencana : (gempa bumi, banjir, tanah longsor dan lain-lain)
2. Tanggal kejadian : (tanggal pada saat terjadinya bencana, bukan tanggal perkembangan bencana)
3. Waktu kejadian : waktu terjadinya bencana pertama kali (jam kejadian bencana)
4. Lokasi bencana : (provinsi, kabupaten, daerah cakupan bencana (desa/kel, kecamatan))
5. Letak geografi : koordinat bencana (long X, lat y), cakupan dampak bencana (panjang,lebar,radius), khusus bencana banjir (luas dan tinggi genangan)
6. Penyebab bencana : (pemicu terjadinya bencana)
7. Deskripsi tentang bencana tersebut.
8. Kondisi Cuaca: diisi cuaca pada saat pelaporan
2. Jumlah korban : diisi jumlah total korban meninggal, hilang, luka berat, luka ringan, pengungsi dan penderita/terdampak namun dibedakan per usia dan jenis kelaminnya.
3. Meninggal : diisi nama korban yang meninggal beserta alamat, jenis kelamin, usia, ahli waris dan keterangan (informasi lainnnya).
4. Hilang : diisi nama korban yang hilang beserta alamat, jenis kelamin, usia, lokasi hilang, ahli waris dan keterangan (informasi lainnya).
5. Luka ringan : diisi nama korban luka ringan beserta alamat, jenis kelamin, usia dan keterangan (informasi lainnya).');
