INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9182, 'perka-8-2011', 38, 'lampiran', 'Lampiran hal. 38', NULL, 38, '1. 1. Kejadian bencana (gempa bumi, banjir, tanah longsor, dan lain-lain)
2. Tanggal kejadian (tanggal saat terjadinya bencana)
3. Lokasi bencana (provinsi, kabupaten kota, dan kecamatan)
2. Penilaian kerusakan berisi :
1. Bidang/sector.
2. Lokasi.
3. Tingkat kerusakan (rusak berat, rusak sedang dan rusak ringan) dan satuannya mengacu pada data kerusakan saat tanggap darurat.
4. Harga satuan (rusak berat, rusak sedang, rusak ringan) diisi berdasarkan penilaian dari bidang rehabilitasi dan rekonstruksi.
5. Nilai kerusakan merupakan penjumlahan dari perkalian masing-masing tingkat kerusakan dengan harga satuan Nilai Kerusakan =(RB pada Tk.
Kerusakan x RB pada Harga satuan) + (RS pada Tk. Kerusakan x RS pada Harga satuan) + (RR pada Tk. Kerusakan x RR pada Harga satuan).
6. Taksiran kerugian berasal dari penilaian kerugian dari tabel penilaian Taksiran kerugian.
7. Hasil verifikasi BNPB/BPBD/KL di isi oleh tim dari BNPB/BPBD/KL.
8. Kepemilikan (pemerintah dan non pemerintah).
3. Penilaian taksiran kerugian berisi sub sektor/jenis sub sektor, lokasi, rincian kerugian, asumsi perhitungan, jumlah, satuan, harga satuan, penilaian kerugian (jumlah x harga satuan) dan keterangan (informasi lainnya).');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9182, '1. 1. Kejadian bencana (gempa bumi, banjir, tanah longsor, dan lain-lain)
2. Tanggal kejadian (tanggal saat terjadinya bencana)
3. Lokasi bencana (provinsi, kabupaten kota, dan kecamatan)
