INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9206, 'perka-9-2008', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PROSEDUR TETAP TIM REAKSI CEPAT BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9206, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG PROSEDUR TETAP TIM REAKSI CEPAT BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9207, 'perka-9-2008', 4, 'pasal', 'Pasal 1', NULL, 2, 'Prosedur Tetap Tim Reaksi Cepat BNPB sebagaimana tersebut dalam Lampiran Peraturan ini merupakan pelaksanaan dari Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana yang tidak terpisahkan dari Peraturan ini.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9207, 'Prosedur Tetap Tim Reaksi Cepat BNPB sebagaimana tersebut dalam Lampiran Peraturan ini merupakan pelaksanaan dari Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana yang tidak terpisahkan dari Peraturan ini.', 'Pasal 1', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9208, 'perka-9-2008', 5, 'pasal', 'Pasal 2', NULL, 2, 'Prosedur Tetap Tim Reaksi Cepat BNPB sebagaimana dimaksud dalam Pasal 1, dipergunakan sebagai acuan bagi Tim Reaksi Cepat BNPB dalam melaksanakan tugas penanganan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9208, 'Prosedur Tetap Tim Reaksi Cepat BNPB sebagaimana dimaksud dalam Pasal 1, dipergunakan sebagai acuan bagi Tim Reaksi Cepat BNPB dalam melaksanakan tugas penanganan darurat bencana.', 'Pasal 2', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9209, 'perka-9-2008', 6, 'pasal', 'Pasal 3', NULL, 2, 'Hal-hal yang belum diatur dalam Peraturan ini, akan diatur kemudian.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9209, 'Hal-hal yang belum diatur dalam Peraturan ini, akan diatur kemudian.', 'Pasal 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9210, 'perka-9-2008', 7, 'pasal', 'Pasal 4', NULL, 2, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9210, 'Peraturan ini mulai berlaku pada tanggal ditetapkan.', 'Pasal 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9211, 'perka-9-2008', 8, 'lain', 'Penutup', NULL, 2, 'Ditetapkan di Jakarta pada tanggal 17 Desember 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9211, 'Ditetapkan di Jakarta pada tanggal 17 Desember 2008 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA ttd DR. SYAMSUL MAARIF, M.Si', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9212, 'perka-9-2008', 9, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 9 TAHUN 2008 TANGGAL : 17 DESEMBER 2008 BAB I PENDAHULUAN A. Latar Belakang Negara Indonesia memiliki wilayah yang rawan dari berbagai bencana dan apabila terjadi bencana, maka masyarakat yang terkena bencana berhak mendapat pelayanan dan perlindungan berdasarkan standar pelayanan minimum mulai dari pencarian, penyelamatan, evakuasi, pertolongan darurat, pemenuhan kebutuhan dasar korban bencana meliputi pangan, sandang, air bersih dan sanitasi, pelayanan kesehatan, dan penampungan/hunian sementara.
Untuk itu perlu kegiatan pengkajian/penilaian cepat terhadap korban meninggal dunia, luka-luka, pengungsi, kerusakan perumahan/kantor/sarana ibadah/sarana pendidikan, sarana dan prasarana vital lainnya.
Pada saat tanggap darurat bencana terdapat berbagai permasalahan antara lain waktu yang sangat singkat, kebutuhan yang mendesak dan berbagai kesulitan koordinasi antara lain yang disebabkan karena banyaknya institusi yang terlibat dalam penanganan darurat bencana, kompetisi dalam pengerahan sumberdaya, otonomi yang berlebihan dan ketidakpercayaan kepada instansi pemerintah. Hal ini perlu dilakukan koordinasi yang lebih intensif dalam rangka memperlancar penyelenggaraan penanganan darurat bencana.
Sehubungan dengan hal tersebut diatas perlu ditugaskan Tim Reaksi Cepat dari berbagai instansi/institusi yang bekerja berdasarkan Prosedur Tetap Tim Reaksi Cepat BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9212, 'LAMPIRAN : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA NOMOR : 9 TAHUN 2008 TANGGAL : 17 DESEMBER 2008 BAB I PENDAHULUAN A. Latar Belakang Negara Indonesia memiliki wilayah yang rawan dari berbagai bencana dan apabila terjadi bencana, maka masyarakat yang terkena bencana berhak mendapat pelayanan dan perlindungan berdasarkan standar pelayanan minimum mulai dari pencarian, penyelamatan, evakuasi, pertolongan darurat, pemenuhan kebutuhan dasar korban bencana meliputi pangan, sandang, air bersih dan sanitasi, pelayanan kesehatan, dan penampungan/hunian sementara.
Untuk itu perlu kegiatan pengkajian/penilaian cepat terhadap korban meninggal dunia, luka-luka, pengungsi, kerusakan perumahan/kantor/sarana ibadah/sarana pendidikan, sarana dan prasarana vital lainnya.
Pada saat tanggap darurat bencana terdapat berbagai permasalahan antara lain waktu yang sangat singkat, kebutuhan yang mendesak dan berbagai kesulitan koordinasi antara lain yang disebabkan karena banyaknya institusi yang terlibat dalam penanganan darurat bencana, kompetisi dalam pengerahan sumberdaya, otonomi yang berlebihan dan ketidakpercayaan kepada instansi pemerintah. Hal ini perlu dilakukan koordinasi yang lebih intensif dalam rangka memperlancar penyelenggaraan penanganan darurat bencana.
Sehubungan dengan hal tersebut diatas perlu ditugaskan Tim Reaksi Cepat dari berbagai instansi/institusi yang bekerja berdasarkan Prosedur Tetap Tim Reaksi Cepat BNPB.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9213, 'perka-9-2008', 10, 'lampiran', 'Lampiran hal. 3', NULL, 3, 'B. Tujuan Prosedur Tetap Tim Reaksi Cepat BNPB bertujuan memberikan panduan bagi personil yang tergabung dalam Tim Reaksi Cepat BNPB untuk dapat melaksanakan tugas secara cepat dan tepat sesuai dengan perkembangan kondisi bencana yang terjadi.
C. Dasar Hukum
1. Undang-Undang Dasar Tahun 1945.
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
5. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
6. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008 tentang Pedoman Organisasi dan Tata Kerja BPBD.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Bencana alam adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang disebabkan oleh alam antara lain berupa gempa bumi, tsunami, gunung meletus, banjir, kekeringan, angin topan, dan tanah longsor.
3. Bencana nonalam adalah bencana yang diakibatkan oleh peristiwa atau rangkaian peristiwa nonalam yang antara lain berupa gagal teknologi, gagal modernisasi, epidemi, dan wabah penyakit.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9213, 'B. Tujuan Prosedur Tetap Tim Reaksi Cepat BNPB bertujuan memberikan panduan bagi personil yang tergabung dalam Tim Reaksi Cepat BNPB untuk dapat melaksanakan tugas secara cepat dan tepat sesuai dengan perkembangan kondisi bencana yang terjadi.
C. Dasar Hukum
1. Undang-Undang Dasar Tahun 1945.
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana.
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana.
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana.
5. Peraturan Presiden Nomor 8 Tahun 2008 tentang Badan Nasional Penanggulangan Bencana.
6. Peraturan Menteri Dalam Negeri Nomor 46 Tahun 2008 tentang Pedoman Organisasi dan Tata Kerja BPBD.
D. Pengertian
1. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2. Bencana alam adalah bencana yang diakibatkan oleh peristiwa atau serangkaian peristiwa yang disebabkan oleh alam antara lain berupa gempa bumi, tsunami, gunung meletus, banjir, kekeringan, angin topan, dan tanah longsor.
3. Bencana nonalam adalah bencana yang diakibatkan oleh peristiwa atau rangkaian peristiwa nonalam yang antara lain berupa gagal teknologi, gagal modernisasi, epidemi, dan wabah penyakit.', 'Lampiran hal. 3', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9214, 'perka-9-2008', 11, 'lampiran', 'Lampiran hal. 4', NULL, 4, '4. Bencana sosial adalah bencana yang diakibatkan oleh peristiwa atau rangkaian peristiwa yang diakibatkan oleh manusia yang meliputi konflik sosial antar kelompok atau antar komunitas masyarakat, dan teror.
5. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
6. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, penyelamatan, prasarana dan sarana.
7. Bantuan darurat bencana adalah upaya memberikan bantuan untuk memenuhi kebutuhan dasar pada saat keadaan darurat.
8. Pengungsi adalah orang atau sekelompok orang yang terpaksa atau dipaksa keluar dari tempat tinggalnya untuk jangka waktu yang belum pasti sebagai akibat dampak buruk bencana.
9. Korban bencana adalah orang atau sekelompok orang yang menderita atau meninggal dunia akibat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9214, '4. Bencana sosial adalah bencana yang diakibatkan oleh peristiwa atau rangkaian peristiwa yang diakibatkan oleh manusia yang meliputi konflik sosial antar kelompok atau antar komunitas masyarakat, dan teror.
5. Penyelenggaraan Penanggulangan Bencana adalah serangkaian upaya yang meliputi penetapan kebijakan pembangunan yang beresiko timbulnya bencana, kegiatan pencegahan bencana, tanggap darurat, dan rehabilitasi.
6. Tanggap darurat bencana adalah serangkaian kegiatan yang dilakukan dengan segera pada saat kejadian bencana untuk menangani dampak buruk yang ditimbulkan, yang meliputi kegiatan penyelamatan dan evakuasi korban, harta benda, pemenuhan kebutuhan dasar, perlindungan, pengurusan pengungsi, penyelamatan, prasarana dan sarana.
7. Bantuan darurat bencana adalah upaya memberikan bantuan untuk memenuhi kebutuhan dasar pada saat keadaan darurat.
8. Pengungsi adalah orang atau sekelompok orang yang terpaksa atau dipaksa keluar dari tempat tinggalnya untuk jangka waktu yang belum pasti sebagai akibat dampak buruk bencana.
9. Korban bencana adalah orang atau sekelompok orang yang menderita atau meninggal dunia akibat bencana.', 'Lampiran hal. 4', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9215, 'perka-9-2008', 12, 'lampiran', 'Lampiran hal. 5', NULL, 5, '10. Tim Reaksi Cepat BNPB disingkat TRC BNPB adalah suatu Tim yang dibentuk oleh Kepala BNPB, terdiri dari instansi/lembaga teknis/non teknis terkait yang bertugas melaksanakan kegiatan kaji cepat bencana dan dampak bencana pada saat tanggap darurat meliputi penilaian kebutuhan (Needs Assessment), penilaian kerusakan dan kerugian (Damage and Loses Assessment) serta memberikan dukungan pendampingan (membantu SATKORLAK PB/BPBD Provinsi/ SATLAK PB/BPBD Kabupaten/Kota) dalam penanganan darurat bencana.
11. Penilaian kebutuhan (Needs Assessment) adalah serangkaian kegiatan untuk menentukan jumlah dan jenis bantuan yang diperlukan dalam upaya penyelamatan korban bencana meliputi SAR, bantuan medis, penyediaan pangan, penyiapan penampungan sementara, penyediaan air bersih dan sanitasi.
12. Penilaian kerusakan dan kerugian (Damage and Loses Assessment) adalah serangkaian kegiatan untuk pengumpulan data primer dan sekunder tentang jenis, waktu, lokasi dan penyebab bencana serta kondisi mutakhir (korban, kerusakan dan kerugian serta dampak bencana).
13. Mengaktivasi Posko adalah serangkaian kegiatan untuk meningkatkan kemampuan personil, sarana dan prasarana Pusdalops menjadi Posko dalam rangka efektifitas penanganan darurat bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9215, '10. Tim Reaksi Cepat BNPB disingkat TRC BNPB adalah suatu Tim yang dibentuk oleh Kepala BNPB, terdiri dari instansi/lembaga teknis/non teknis terkait yang bertugas melaksanakan kegiatan kaji cepat bencana dan dampak bencana pada saat tanggap darurat meliputi penilaian kebutuhan (Needs Assessment), penilaian kerusakan dan kerugian (Damage and Loses Assessment) serta memberikan dukungan pendampingan (membantu SATKORLAK PB/BPBD Provinsi/ SATLAK PB/BPBD Kabupaten/Kota) dalam penanganan darurat bencana.
11. Penilaian kebutuhan (Needs Assessment) adalah serangkaian kegiatan untuk menentukan jumlah dan jenis bantuan yang diperlukan dalam upaya penyelamatan korban bencana meliputi SAR, bantuan medis, penyediaan pangan, penyiapan penampungan sementara, penyediaan air bersih dan sanitasi.
12. Penilaian kerusakan dan kerugian (Damage and Loses Assessment) adalah serangkaian kegiatan untuk pengumpulan data primer dan sekunder tentang jenis, waktu, lokasi dan penyebab bencana serta kondisi mutakhir (korban, kerusakan dan kerugian serta dampak bencana).
13. Mengaktivasi Posko adalah serangkaian kegiatan untuk meningkatkan kemampuan personil, sarana dan prasarana Pusdalops menjadi Posko dalam rangka efektifitas penanganan darurat bencana.', 'Lampiran hal. 5', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9216, 'perka-9-2008', 13, 'lampiran', 'Lampiran hal. 7', NULL, 7, 'BAB II TUGAS POKOK DAN FUNGSI TRC BNPB A. Tugas Pokok TRC BNPB TRC BNPB mempunyai tugas pengkajian secara cepat dan tepat di lokasi bencana dalam waktu tertentu dalam rangka mengidentifikasi cakupan lokasi bencana, jumlah korban, kerusakan prasarana dan sarana, gangguan terhadap fungsi pelayanan umum dan pemerintahan serta kemampuan sumber daya alam maupun buatan serta saran yang tepat dalam upaya penanganan bencana dengan tugas tambahan membantu SATKORLAK PB/BPBD Provinsi/ SATLAK PB/BPBD Kabupaten/Kota untuk mengkoordinasikan sektor yang terkait dalam penanganan darurat bencana.
B. Fungsi TRC BNPB Untuk melaksanakan tugas tersebut diatas, TRC BNPB mempunyai fungsi sebagai berikut :
1. Melaksanakan pengkajian awal segera setelah terjadi bencana pada saat tanggap darurat.
2. Membantu SATKORLAK PB/BPBD Provinsi/SATLAK PB/BPBD Kabupaten/Kota untuk :
a. Mengaktivasi Posko SATKORLAK PB/BPBD Provinsi/SATLAK PB/BPBD Kabupaten/Kota.
b. Memperlancar koordinasi dengan seluruh sektor yang terlibat dalam penanganan bencana.
c. Menyampaikan saran yang tepat dalam untuk upaya penanganan bencana.
3. Melaporkan hasil pelaksanaan tugas secara periodik kepada Kepala BNPB dengan tembusan atasan langsung anggota Tim dari sektor terkait dan SATKORLAK PB/BPBD Provinsi/SATLAK PB/BPBD Kabupaten/Kota :
a. Laporan awal setelah tiba di lokasi bencana.
b. Laporan berkala/perkembangan (harian dan insidentil/ khusus).
c. Laporan lengkap/akhir penugasan.
C. Persyaratan Anggota TRC BNPB');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9216, 'BAB II TUGAS POKOK DAN FUNGSI TRC BNPB A. Tugas Pokok TRC BNPB TRC BNPB mempunyai tugas pengkajian secara cepat dan tepat di lokasi bencana dalam waktu tertentu dalam rangka mengidentifikasi cakupan lokasi bencana, jumlah korban, kerusakan prasarana dan sarana, gangguan terhadap fungsi pelayanan umum dan pemerintahan serta kemampuan sumber daya alam maupun buatan serta saran yang tepat dalam upaya penanganan bencana dengan tugas tambahan membantu SATKORLAK PB/BPBD Provinsi/ SATLAK PB/BPBD Kabupaten/Kota untuk mengkoordinasikan sektor yang terkait dalam penanganan darurat bencana.
B. Fungsi TRC BNPB Untuk melaksanakan tugas tersebut diatas, TRC BNPB mempunyai fungsi sebagai berikut :
1. Melaksanakan pengkajian awal segera setelah terjadi bencana pada saat tanggap darurat.
2. Membantu SATKORLAK PB/BPBD Provinsi/SATLAK PB/BPBD Kabupaten/Kota untuk :
a. Mengaktivasi Posko SATKORLAK PB/BPBD Provinsi/SATLAK PB/BPBD Kabupaten/Kota.
b. Memperlancar koordinasi dengan seluruh sektor yang terlibat dalam penanganan bencana.
c. Menyampaikan saran yang tepat dalam untuk upaya penanganan bencana.
3. Melaporkan hasil pelaksanaan tugas secara periodik kepada Kepala BNPB dengan tembusan atasan langsung anggota Tim dari sektor terkait dan SATKORLAK PB/BPBD Provinsi/SATLAK PB/BPBD Kabupaten/Kota :
a. Laporan awal setelah tiba di lokasi bencana.
b. Laporan berkala/perkembangan (harian dan insidentil/ khusus).
c. Laporan lengkap/akhir penugasan.
C. Persyaratan Anggota TRC BNPB', 'Lampiran hal. 7', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9217, 'perka-9-2008', 14, 'lampiran', 'Lampiran hal. 8', NULL, 8, '1. Kualifikasi Personil
a. Sehat jasmani/rohani.
b. Telah mengikuti pelatihan/workshop TRC.
c. Berpengalaman di bidang kedaruratan bencana.
2. Bersedia ditugaskan ke lokasi bencana minimal 3 s.d 7 hari.
3. Setiap saat, selama masa penugasannya siap sedia dengan perlengkapan perorangannya di kantor/kendaraan atau di rumah yang dapat diambil dalam waktu relatif singkat/cepat.
D. Perlengkapan TRC BNPB Perlengkapan TRC BNPB terdiri dari perlengkapan perorangan dan perlengkapan Tim (Format-1).
BAB III PENUGASAN TRC BNPB TRC BNPB melaksanakan tugas dengan tahapan meliputi Tahap Persiapan, Tahap Pelaksanaan dan Tahap Pengakhiran sebagai berikut :
A. Tahap Persiapan
1. Informasi Awal Darurat Bencana Deputi Bidang Penanganan Darurat BNPB Up. Direktur Tanggap Darurat akan mengirimkan informasi kepada seluruh personil TRC BNPB dengan tembusan kepada atasan masing-masing sesaat setelah terjadinya bencana dengan eskalasi tertentu melalui sarana komunikasi telepon/HP/facsimile/sms/email.
2. Penugasan Tim Reaksi Cepat
a. Konfirmasi Kesediaan Perorangan.
1) Anggota TRC BNPB pada kesempatan pertama melaporkan kepada atasan masing-masing tentang kesiapan untuk melaksanakan tugas.
2) Atasan dari Anggota TRC BNPB memberikan jawaban atas kesiapan anggotanya untuk melaksanakan tugas dalam Tim Reaksi Cepat BNPB.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9217, '1. Kualifikasi Personil
a. Sehat jasmani/rohani.
b. Telah mengikuti pelatihan/workshop TRC.
c. Berpengalaman di bidang kedaruratan bencana.
2. Bersedia ditugaskan ke lokasi bencana minimal 3 s.d 7 hari.
3. Setiap saat, selama masa penugasannya siap sedia dengan perlengkapan perorangannya di kantor/kendaraan atau di rumah yang dapat diambil dalam waktu relatif singkat/cepat.
D. Perlengkapan TRC BNPB Perlengkapan TRC BNPB terdiri dari perlengkapan perorangan dan perlengkapan Tim (Format-1).
BAB III PENUGASAN TRC BNPB TRC BNPB melaksanakan tugas dengan tahapan meliputi Tahap Persiapan, Tahap Pelaksanaan dan Tahap Pengakhiran sebagai berikut :
A. Tahap Persiapan
1. Informasi Awal Darurat Bencana Deputi Bidang Penanganan Darurat BNPB Up. Direktur Tanggap Darurat akan mengirimkan informasi kepada seluruh personil TRC BNPB dengan tembusan kepada atasan masing-masing sesaat setelah terjadinya bencana dengan eskalasi tertentu melalui sarana komunikasi telepon/HP/facsimile/sms/email.
2. Penugasan Tim Reaksi Cepat
a. Konfirmasi Kesediaan Perorangan.
1) Anggota TRC BNPB pada kesempatan pertama melaporkan kepada atasan masing-masing tentang kesiapan untuk melaksanakan tugas.
2) Atasan dari Anggota TRC BNPB memberikan jawaban atas kesiapan anggotanya untuk melaksanakan tugas dalam Tim Reaksi Cepat BNPB.', 'Lampiran hal. 8', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9218, 'perka-9-2008', 15, 'lampiran', 'Lampiran hal. 9', NULL, 9, '3) Anggota TRC BNPB wajib segera membalas dan memberikan jawaban dalam waktu yang telah ditentukan pada informasi awal darurat bencana kepada Deputi Bidang Penanganan Darurat BNPB Up. Direktur Tanggap Darurat tentang kesiapan melaksanakan tugas melalui sarana komunikasi.
b. Penetapan Penugasan.
1) Memilih dan menyusun komposisi anggota TRC BNPB yang disesuaikan dengan macam/jenis bencana dan keahliannya yang dituangkan dalam Surat Perintah Kepala BNPB terdiri dari : a) Ketua Tim : Personil BNPB atau Instansi/ Lembaga terkait b) Anggota : Personil BNPB dan Instansi/ Lembaga terkait c) Petugas Administrasi : Personil BNPB 2) Mengirimkan informasi kepada personil yang ditunjuk untuk melaksanakan tugas sebagai personil TRC BNPB untuk macam/jenis bencana yang terjadi.
3) Memberikan informasi dan ucapan terima kasih kepada personil yang siap untuk melaksanakan tugas, tetapi tidak ditunjuk dalam TRC BNPB.
3. Mobilisasi Awal
a. BNPB menyelesaikan kelengkapan administrasi, keuangan dan perlengkapan yang diperlukan Tim.
b. BNPB menyampaikan informasi penugasan TRC BNPB kepada pejabat yang berwenang di SATKORLAK PB/BPBD Provinsi/ SATLAK PB/BPBD Kabupaten/Kota.
c. Segera setelah penetapan TRC dilakukan pembagian tugas sebagai berikut:
1) Ketua Tim a) Membuat konsep awal Rencana Kedatangan dan Rencana Aksi (Format-2). b) Melaksanakan pengecekan kesiapan personil Tim melalui sarana komunikasi telepon/HP.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9218, '3) Anggota TRC BNPB wajib segera membalas dan memberikan jawaban dalam waktu yang telah ditentukan pada informasi awal darurat bencana kepada Deputi Bidang Penanganan Darurat BNPB Up. Direktur Tanggap Darurat tentang kesiapan melaksanakan tugas melalui sarana komunikasi.
b. Penetapan Penugasan.
1) Memilih dan menyusun komposisi anggota TRC BNPB yang disesuaikan dengan macam/jenis bencana dan keahliannya yang dituangkan dalam Surat Perintah Kepala BNPB terdiri dari : a) Ketua Tim : Personil BNPB atau Instansi/ Lembaga terkait b) Anggota : Personil BNPB dan Instansi/ Lembaga terkait c) Petugas Administrasi : Personil BNPB 2) Mengirimkan informasi kepada personil yang ditunjuk untuk melaksanakan tugas sebagai personil TRC BNPB untuk macam/jenis bencana yang terjadi.
3) Memberikan informasi dan ucapan terima kasih kepada personil yang siap untuk melaksanakan tugas, tetapi tidak ditunjuk dalam TRC BNPB.
3. Mobilisasi Awal
a. BNPB menyelesaikan kelengkapan administrasi, keuangan dan perlengkapan yang diperlukan Tim.
b. BNPB menyampaikan informasi penugasan TRC BNPB kepada pejabat yang berwenang di SATKORLAK PB/BPBD Provinsi/ SATLAK PB/BPBD Kabupaten/Kota.
c. Segera setelah penetapan TRC dilakukan pembagian tugas sebagai berikut:
1) Ketua Tim a) Membuat konsep awal Rencana Kedatangan dan Rencana Aksi (Format-2). b) Melaksanakan pengecekan kesiapan personil Tim melalui sarana komunikasi telepon/HP.', 'Lampiran hal. 9', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9219, 'perka-9-2008', 16, 'lampiran', 'Lampiran hal. 10', NULL, 10, '2) Personil BNPB yang bertugas sebagai Petugas Administrasi Tim menyelesaikan administrasi keuangan, tiket transportasi, peralatan dan dukungan sarana pendukung Tim.
3) Anggota Tim dari sektor terkait berangkat dari kantor/rumah masing-masing dengan membawa perlengkapan pribadi dan sarana pendukung tugas menuju ke BNPB atau tempat yang telah ditentukan.
4) Setelah seluruh personil Tim berkumpul di BNPB atau tempat yang telah ditentukan: a) Menyempurnakan Rencana Kedatangan dan Rencana Aksi (Format-2). b) Pembagian tugas personil Tim. c) Menyelesaikan administrasi dan pengecekan kesiapan personil, perlengkapan dan sarana pendukung lainnya. d) Penyerahan dan penerimaan peralatan, dokumen dan keuangan dari BNPB.
B. Tahap Pelaksanaan
1. Pemberangkatan TRC BNPB TRC BNPB berangkat menuju ibukota Provinsi/Kabupaten/Kota lokasi bencana dengan sarana transportasi yang telah ditentukan.
2. Tiba di Daerah Lokasi Bencana
a. Mengadakan pertemuan awal dengan Kepala Daerah atau pejabat yang ditunjuk untuk melakukan hal-hal sebagai berikut:
1) Memperkenalkan personil Tim.
2) Menyampaikan maksud, tujuan dan tugas Tim untuk melaksanakan tugas di daerah bencana.
3) Menghimpun informasi mutahir tentang kejadian bencana, korban, kerusakan, dampak bencana dan upaya yang telah dilakukan serta kebutuhan yang mendesak.
4) Menyampaikan permintaan personil pendamping dari SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9219, '2) Personil BNPB yang bertugas sebagai Petugas Administrasi Tim menyelesaikan administrasi keuangan, tiket transportasi, peralatan dan dukungan sarana pendukung Tim.
3) Anggota Tim dari sektor terkait berangkat dari kantor/rumah masing-masing dengan membawa perlengkapan pribadi dan sarana pendukung tugas menuju ke BNPB atau tempat yang telah ditentukan.
4) Setelah seluruh personil Tim berkumpul di BNPB atau tempat yang telah ditentukan: a) Menyempurnakan Rencana Kedatangan dan Rencana Aksi (Format-2). b) Pembagian tugas personil Tim. c) Menyelesaikan administrasi dan pengecekan kesiapan personil, perlengkapan dan sarana pendukung lainnya. d) Penyerahan dan penerimaan peralatan, dokumen dan keuangan dari BNPB.
B. Tahap Pelaksanaan
1. Pemberangkatan TRC BNPB TRC BNPB berangkat menuju ibukota Provinsi/Kabupaten/Kota lokasi bencana dengan sarana transportasi yang telah ditentukan.
2. Tiba di Daerah Lokasi Bencana
a. Mengadakan pertemuan awal dengan Kepala Daerah atau pejabat yang ditunjuk untuk melakukan hal-hal sebagai berikut:
1) Memperkenalkan personil Tim.
2) Menyampaikan maksud, tujuan dan tugas Tim untuk melaksanakan tugas di daerah bencana.
3) Menghimpun informasi mutahir tentang kejadian bencana, korban, kerusakan, dampak bencana dan upaya yang telah dilakukan serta kebutuhan yang mendesak.
4) Menyampaikan permintaan personil pendamping dari SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota.', 'Lampiran hal. 10', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9220, 'perka-9-2008', 17, 'lampiran', 'Lampiran hal. 11', NULL, 11, 'b. Membantu SATKORLAK PB /BPBD Provinsi atau SATLAK PB/ BPBD Kabupaten/Kota untuk :
1) Mengaktivasi Posko SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota dengan melakukan kegiatan antara lain: a) Penyiapan tempat, alat komunikasi dan sarana pendukung lainnya. b) Penataan peta bencana, deskripsi bencana, data-data korban, pengungsi, sumber daya (stock, telah disalurkan dan masih tersedia), jadwal piket Posko, upaya yang telah dilakukan dan kebutuhan yang mendesak. c) Memberikan asistensi teknis bidang Posko dan arus informasi penanganan bencana. d) Ketua Tim menyerahkan bantuan dukungan BNPB untuk penguatan Posko.
2) Menyelenggarakan rapat guna memperlancar koordinasi dengan seluruh sektor yang terlibat dalam penanggulangan bencana.
c. Memberikan saran yang tepat untuk upaya penanganan darurat bencana
d. Melaksanakan koordinasi dengan sektor terkait untuk melengkapi data / informasi bencana (Format-3).
e. Menyempurnakan Rencana Aksi Tim (Format-2).
f. Melaksanakan pembagian tugas dalam Sub Tim sesuai kebutuhan.
g. Mengirimkan laporan awal (Format-4 dan 5) kepada Kepala BNPB dengan tembusan atasan masing-masing anggota Tim, Posko BNPB dan SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota melalui telepon/facsimile/ HP/sms/email.
3. Peninjauan Lapangan di Lokasi Bencana
a. Masing-masing Sub Tim melaksanakan peninjauan lapangan untuk melakukan :');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9220, 'b. Membantu SATKORLAK PB /BPBD Provinsi atau SATLAK PB/ BPBD Kabupaten/Kota untuk :
1) Mengaktivasi Posko SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota dengan melakukan kegiatan antara lain: a) Penyiapan tempat, alat komunikasi dan sarana pendukung lainnya. b) Penataan peta bencana, deskripsi bencana, data-data korban, pengungsi, sumber daya (stock, telah disalurkan dan masih tersedia), jadwal piket Posko, upaya yang telah dilakukan dan kebutuhan yang mendesak. c) Memberikan asistensi teknis bidang Posko dan arus informasi penanganan bencana. d) Ketua Tim menyerahkan bantuan dukungan BNPB untuk penguatan Posko.
2) Menyelenggarakan rapat guna memperlancar koordinasi dengan seluruh sektor yang terlibat dalam penanggulangan bencana.
c. Memberikan saran yang tepat untuk upaya penanganan darurat bencana
d. Melaksanakan koordinasi dengan sektor terkait untuk melengkapi data / informasi bencana (Format-3).
e. Menyempurnakan Rencana Aksi Tim (Format-2).
f. Melaksanakan pembagian tugas dalam Sub Tim sesuai kebutuhan.
g. Mengirimkan laporan awal (Format-4 dan 5) kepada Kepala BNPB dengan tembusan atasan masing-masing anggota Tim, Posko BNPB dan SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota melalui telepon/facsimile/ HP/sms/email.
3. Peninjauan Lapangan di Lokasi Bencana
a. Masing-masing Sub Tim melaksanakan peninjauan lapangan untuk melakukan :', 'Lampiran hal. 11', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9221, 'perka-9-2008', 18, 'lampiran', 'Lampiran hal. 12', NULL, 12, '1) Identifikasi terhadap cakupan lokasi bencana, jumlah korban, kerusakan prasarana dan sarana, gangguan terhadap fungsi pelayanan umum serta pemerintahan.
2) Identifikasi kebutuhan yang mendesak untuk : a) Pencarian dan penyelamatan korban bencana dan evakuasi korban bencana (Format-7). b) Pemenuhan kebutuhan dasar (pangan, sandang, air bersih/minum dan sanitasi, pelayanan kesehatan) (Format-8). c) Penampungan sementara (tenda, tikar, genset, MCK, dapur umum) (Format-9). d) Perlindungan terhadap kelompok rentan (balita, ibu hamil, lansia, cacat) (Format-10). e) Pemulihan darurat sarana dan prasarana, antara lain pembersihan puing/lumpur/tanah longsor, jalan/ jembatan/tanggul, fasilitas pelayanan kesehatan, transportasi, telekomunikasi dan energi (Format-11).
b. TRC BNPB membantu melalui pola pendampingan SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota dengan sektor terkait untuk melaksanakan rapat evaluasi dan tindak lanjut yang diselenggarakan pada sore hari untuk membahas :
1) Hasil peninjauan di lapangan.
2) Pelaksanaan harian penanganan darurat bencana.
3) Perkembangan dampak bencana.
4) Sumber daya yang masih tersedia, dukungan yang masih dalam perjalanan dan kebutuhan yang mendesak.
5) Kendala/hambatan yang dihadapi dan upaya mengatasi.
6) Analisa kebutuhan sampai dengan berakhirnya masa tanggap darurat bencana.
7) Rencana kegiatan penanganan darurat bencana dan pengerahan sumber daya untuk hari berikutnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9221, '1) Identifikasi terhadap cakupan lokasi bencana, jumlah korban, kerusakan prasarana dan sarana, gangguan terhadap fungsi pelayanan umum serta pemerintahan.
2) Identifikasi kebutuhan yang mendesak untuk : a) Pencarian dan penyelamatan korban bencana dan evakuasi korban bencana (Format-7). b) Pemenuhan kebutuhan dasar (pangan, sandang, air bersih/minum dan sanitasi, pelayanan kesehatan) (Format-8). c) Penampungan sementara (tenda, tikar, genset, MCK, dapur umum) (Format-9). d) Perlindungan terhadap kelompok rentan (balita, ibu hamil, lansia, cacat) (Format-10). e) Pemulihan darurat sarana dan prasarana, antara lain pembersihan puing/lumpur/tanah longsor, jalan/ jembatan/tanggul, fasilitas pelayanan kesehatan, transportasi, telekomunikasi dan energi (Format-11).
b. TRC BNPB membantu melalui pola pendampingan SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota dengan sektor terkait untuk melaksanakan rapat evaluasi dan tindak lanjut yang diselenggarakan pada sore hari untuk membahas :
1) Hasil peninjauan di lapangan.
2) Pelaksanaan harian penanganan darurat bencana.
3) Perkembangan dampak bencana.
4) Sumber daya yang masih tersedia, dukungan yang masih dalam perjalanan dan kebutuhan yang mendesak.
5) Kendala/hambatan yang dihadapi dan upaya mengatasi.
6) Analisa kebutuhan sampai dengan berakhirnya masa tanggap darurat bencana.
7) Rencana kegiatan penanganan darurat bencana dan pengerahan sumber daya untuk hari berikutnya.', 'Lampiran hal. 12', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9222, 'perka-9-2008', 19, 'lampiran', 'Lampiran hal. 13', NULL, 13, 'c. Setelah selesai pelaksanaan rapat, TRC BNPB membantu SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota untuk memberikan Press Release kepada mass media cetak/elektronika.
d. Mengirimkan laporan Tim (Format 4 dan 6) tentang perkembangan bencana dan upaya yang telah dilakukan serta kebutuhan yang mendesak kepada Kepala BNPB dengan tembusan atasan langsung masing-masing anggota Tim dan SATKORLAK PB/BPBD Provinsi/SATLAK PB/BPBD Kabupaten/Kota.
4. Evaluasi
a. Melanjutkan peninjauan lapangan pada daerah yang belum sempat ditinjau.
b. TRC BNPB setiap sore hari membantu SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota dan sektor terkait untuk melaksanakan rapat evaluasi dan tindak lanjut :
1) Melanjutkan peninjauan lapangan.
2) Pelaksanaan harian penanganan bencana.
3) Perkembangan dampak bencana.
4) Sumber daya yang masih tersedia, dukungan yang masih dalam perjalanan dan kebutuhan yang mendesak.
5) Kendala yang dihadapi dan upaya mengatasi.
6) Analisa kebutuhan sampai dengan berakhirnya masa tanggap darurat bencana.
7) Rencana kegiatan penanganan bencana dan pengerahan sumber daya untuk hari berikutnya.
c. Setelah selesai pelaksanaan rapat, TRC BNPB membantu SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota untuk memberikan Press Realesse kepada mass media cetak/elektronika.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9222, 'c. Setelah selesai pelaksanaan rapat, TRC BNPB membantu SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota untuk memberikan Press Release kepada mass media cetak/elektronika.
d. Mengirimkan laporan Tim (Format 4 dan 6) tentang perkembangan bencana dan upaya yang telah dilakukan serta kebutuhan yang mendesak kepada Kepala BNPB dengan tembusan atasan langsung masing-masing anggota Tim dan SATKORLAK PB/BPBD Provinsi/SATLAK PB/BPBD Kabupaten/Kota.
4. Evaluasi
a. Melanjutkan peninjauan lapangan pada daerah yang belum sempat ditinjau.
b. TRC BNPB setiap sore hari membantu SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota dan sektor terkait untuk melaksanakan rapat evaluasi dan tindak lanjut :
1) Melanjutkan peninjauan lapangan.
2) Pelaksanaan harian penanganan bencana.
3) Perkembangan dampak bencana.
4) Sumber daya yang masih tersedia, dukungan yang masih dalam perjalanan dan kebutuhan yang mendesak.
5) Kendala yang dihadapi dan upaya mengatasi.
6) Analisa kebutuhan sampai dengan berakhirnya masa tanggap darurat bencana.
7) Rencana kegiatan penanganan bencana dan pengerahan sumber daya untuk hari berikutnya.
c. Setelah selesai pelaksanaan rapat, TRC BNPB membantu SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota untuk memberikan Press Realesse kepada mass media cetak/elektronika.', 'Lampiran hal. 13', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2008 tentang Prosedur Tetap Tim Reaksi Cepat Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9223, 'perka-9-2008', 20, 'lampiran', 'Lampiran hal. 14', NULL, 14, 'd. Mengirimkan laporan Tim (Format-4 dan 6) tentang perkembangan bencana dan upaya yang telah dilakukan serta kebutuhan yang mendesak kepada Kepala BNPB dengan tembusan atasan langsung masing-masing anggota Tim dan SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota.
C. Tahap Pengakhiran
1. Pengakhiran tugas TRC BNPB berdasarkan perintah dari Kepala BNPB.
2. Persiapan Meninggalkan Lokasi Bencana.
a. Melaksanakan pengecekan kelengkapan peralatan Tim dan perlengkapan perorangan.
b. Menyusun laporan lengkap pelaksanaan tugas TRC BNPB.
c. Menyerahterimakan tugas dan dokumen pendukung bencana kepada kepala daerah.
d. Menghadap Gubernur/Bupati/Walikota untuk mohon pamit untuk meninggalkan daerah bencana kembali ke Jakarta, karena pelaksanaan tugas Tim telah selesai dan menyerahkan laporan sementara hasil pelaksanaan tugas Tim (Format-12).
e. TRC BNPB meninggalkan daerah bencana dengan sarana transportasi yang telah ditentukan menuju Jakarta.
3. Tiba di BNPB
a. Mengembalikan peralatan inventaris BNPB kepada BNPB.
b. Menghadap Kepala BNPB Up. Deputi Bidang Penanganan Darurat untuk laporan selesai melaksanakan tugas dan menyerahkan laporan pelaksanaan tugas Tim (Format-12).
c. Menyerahkan bukti-bukti pertanggungjawaban administrasi keuangan kepada pejabat yang berwenang.
d. Masing-masing anggota Tim dari sektor terkait membawa laporan pelaksanaan tugas Tim untuk disampaikan kepada atasan langsungnya.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9223, 'd. Mengirimkan laporan Tim (Format-4 dan 6) tentang perkembangan bencana dan upaya yang telah dilakukan serta kebutuhan yang mendesak kepada Kepala BNPB dengan tembusan atasan langsung masing-masing anggota Tim dan SATKORLAK PB/BPBD Provinsi atau SATLAK PB/BPBD Kabupaten/Kota.
