INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9240, 'perka-9-2008', 37, 'lampiran', 'Lampiran hal. 32', NULL, 32, 'Yth. Kepala BNPB. Laporan awal TRC BNPB tgl …....…… jam ......…. tugas ke Prov./Kab./Kota …….. : Tim jml …org (…BNPB, …Depsos, ….Depkes, Dep PU, dst) tiba di Kab/Kota ……. tgl …….. jam …… selanjutnya menghadap Gub./Bupati/Walikota atau pejabat yg berwenang, bencana …............… (jenis bencana) pd tgl …...... jam …....., lokasi ……., penyebab bencana ………, korban (meninggal, luka berat, luka ringan, hilang, pengungsi), kerusakan (rmh, ktr, fas kes/dik/ibadah/umum, jembatan, jalan, tanggul, sawah, lahan pertanian, dll), upaya yg telah dilakukan : Tim membantu mengaktivasi Posko Satkorlak PB/Satlak PB/ BPBD, Satkorlak PB/Satlak PB/BPBD melaks penyelamatan/evakuasi, melaks yankes, pendirian dapur umum, pendistribusian permakanan, pengerahan tenaga Aparat Pemda, TNI, Polri, SAR, Tagana, kegiatan lainnya, dampak bencana (bencana susulan, kegiatan masyarakat, dll), kondisi Kamtibmas, kendala/hambatan, kebutuhan mendesak, saran bantuan dari BNPB.
(Ketua Tim, nama …................). CC. De-2 BNPB, Atasan masing-masing anggota Tim, Satkorlak PB/Satlak PB/BPBD dan Posko BNPB.');
