INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9241, 'perka-9-2008', 38, 'lampiran', 'Lampiran hal. 32', NULL, 32, '2. Laporan hari berikutnya Yth. Kepala BNPB. Laporan TRC BNPB tgl …....…… jam ......…. tugas ke Prov/Kab/Kota …….. : Tim jml …org, laporan perkembangan bencana …… (jenis bencana), korban (meninggal,luka berat, luka ringan, hilang, pengungsi), kerusakan (rmh, ktr, fas kes/dik/ibadah/umum, jembatan, jalan, tanggul, sawah, lahan pertanian, dll), upaya yg telah dilakukan : SatkorlakPB/Satlak PB/BPBD melaks penyelamatan/evakuasi, melaks yankes, pendirian dapur umum, pendistribusian permakanan, pengerahan tenaga Aparat Pemda,TNI, Polri, SAR, Tagana, kegiatan lainnya, dampak bencana (bencana susulan, kegiatan masyarakat, dll), kondisi Kamtibmas, kendala/hambatan, kebutuhan mendesak, saran bantuan dari BNPB.
