INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9262, 'perka-9-2014', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG UNIT LAYANAN PENGADAAN BARANG/JASA PEMERINTAH DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9262, 'Menetapkan : PERATURAN KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA TENTANG UNIT LAYANAN PENGADAAN BARANG/JASA PEMERINTAH DI LINGKUNGAN BADAN NASIONAL PENANGGULANGAN BENCANA.', 'Menetapkan', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2014 tentang Unit Layanan Pengadaan Barang/Jasa Pemerintah di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9263, 'perka-9-2014', 4, 'pasal', 'Pasal 1', 'BAB II MAKSUD DAN TUJUAN', 2, 'Dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana ini yang dimaksud dengan :
1. Pengadaan Barang/Jasa Pemerintah yang selanjutnya disebut dengan Pengadaan Barang/Jasa adalah kegiatan untuk memperoleh Barang/Jasa oleh Kementerian/Lembaga/Satuan Kerja Perangkat Daerah/Institusi lainnya yang prosesnya dimulai dari perencanaan kebutuhan sampai diselesaikannya seluruh kegiatan untuk memperoleh Barang/Jasa.
3 2014, No.600
2. Lembaga Kebijakan Pengadaan Barang/Jasa Pemerintah yang selanjutnya disebut LKPP adalah lembaga Pemerintah yang bertugas mengembangkan dan merumuskan kebijakan Pengadaan Barang/Jasa sebagaimana dimaksud dalam Peraturan Presiden Nomor 106 Tahun 2007 tentang Lembaga Kebijakan Pengadaan Barang/Jasa Pemerintah.
3. Unit Layanan Pengadaan Secara Elektronik yang selanjutnya disingkat unit LPSE adalah unit yang melayani proses pengadaan Barang/Jasa secara elektronik di lingkungan Badan Nasional Penanggulangan Bencana.
4. Unit Layanan Pengadaan yang selanjutnya disingkat ULP adalah unit organisasi pemerintah yang berfungsi melaksanakan pengadaan Barang/Jasa di lingkungan Badan Nasional Penanggulangan Bencana.
5. E-Procurement adalah Proses Pengadaan Barang/Jasa Pemerintah yang pelaksanaannya dilakukan secara elektronik yang berbasis web/internet dengan memanfaatkan fasilitas teknologi komunikasi dan informasi yang meliputi pelelangan umum secara elektronik yang diselenggarakan oleh Layanan Pengadaan Secara Elektronik (LPSE) melalui http://lpse.bnpb.go.id/eproc/
6. Pengguna Anggaran yang selanjutnya disingkat PA adalah Kepala Badan Nasional Penanggulangan Bencana.
7. Kuasa Pengguna Anggaran selanjutnya disebut KPA adalah pejabat yang diberi kuasa untuk melaksanakan sebagian kewenangan pengguna anggaran dalam melaksanakan sebagian tugas dan fungsi satuan Kerja.
8. Pejabat Pembuat Komitmen selanjutnya disebut PPK adalah pejabat yang diangkat oleh pengguna anggaran/kuasa pengguna anggaran yang bertanggungjawab atas pelaksanaan pengadaan Barang/Jasa.
9. Kelompok Kerja Pengadaan, selanjutnya disebut Pokja adalah Tim yang terdiri atas Pegawai Negeri Sipil bersertifikat keahlian yang bertindak sebagai panitia pengadaan yang bertugas untuk melaksanakan pemilihan penyedia Barang/Jasa di dalam ULP.
10. Pejabat Pengadaan adalah personil yang memiliki Sertifikat Keahlian Pengadaan Barang/ Jasa yang ditetapkan oleh KPA untuk melaksanakan pengadaan barang/ jasa dalam satuan kerja.
11. Badan Nasional Penanggulangan Bencana, selanjutnya disebut BNPB adalah lembaga pemerintah Non Kementerian yang berada di bawah dan bertanggung jawab kepada Presiden.
12. Kepala Badan Nasional Penanggulangan Bencana adalah Kepala Badan Nasional yang menyelenggarakan urusan pemerintahan di bidang penanggulangan bencana.
2014, No.600 4');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9263, 'Dalam Peraturan Kepala Badan Nasional Penanggulangan Bencana ini yang dimaksud dengan :
