INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9277, 'perka-9-2014', 18, 'pasal', 'Pasal 15', 'BAB VI KETENTUAN PENUTUP', 9, 'Peraturan Kepala BNPB ini mulai berlaku pada tanggal diundangkan.
