INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9278, 'Ditetapkan di Jakarta pada tanggal 25 April 2014 KEPALA BADAN NASIONAL PENANGGULANGAN BENCANA, SYAMSUL MAARIF Diundangkan di Jakarta pada tanggal 6 Mei 2014 MENTERI HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA, AMIR SYAMSUDIN', 'Penutup', 'Peraturan Kepala Badan Nasional Penanggulangan Bencana Nomor 9 Tahun 2014 tentang Unit Layanan Pengadaan Barang/Jasa Pemerintah di Lingkungan Badan Nasional Penanggulangan Bencana');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9279, 'perpres-17-2018', 0, 'judul', 'Judul', NULL, 1, 'Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9279, 'Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu', 'Judul', 'Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9280, 'perpres-17-2018', 1, 'menimbang', 'Menimbang', NULL, 1, 'a. bahwa dalam rangka melaksanakan penanggulangan bencana secara terkoordinasi, terencana, dan terpadu perlu memperhatikan aspek good governance dan bersikap hati-hati;
b. bahwa dalam keadaan tertentu dimana status keadaan darurat Bencana belum ditetapkan atau status keadaan darurat Bencana telah berakhir dan/atau tidak diperpanjang, namun diperlukan atau masih diperlukan tindakan guna mengurangi risiko Bencana dan dampak yang lebih luas maka perlu untuk memberikan penugasan dan kewenangan kepada Badan Nasional Penanggulangan Bencana untuk dapat melakukan penyelenggaraan penanggulangan bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Presiden tentang Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu;');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9280, 'a. bahwa dalam rangka melaksanakan penanggulangan bencana secara terkoordinasi, terencana, dan terpadu perlu memperhatikan aspek good governance dan bersikap hati-hati;
b. bahwa dalam keadaan tertentu dimana status keadaan darurat Bencana belum ditetapkan atau status keadaan darurat Bencana telah berakhir dan/atau tidak diperpanjang, namun diperlukan atau masih diperlukan tindakan guna mengurangi risiko Bencana dan dampak yang lebih luas maka perlu untuk memberikan penugasan dan kewenangan kepada Badan Nasional Penanggulangan Bencana untuk dapat melakukan penyelenggaraan penanggulangan bencana;
c. bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Peraturan Presiden tentang Penyelenggaraan Penanggulangan Bencana Dalam Keadaan Tertentu;', 'Menimbang', 'Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9281, 'perpres-17-2018', 2, 'mengingat', 'Mengingat', NULL, 2, '2018, No.34 -2-
1. Pasal 4 ayat (1) Undang-Undang Dasar Negara Republik Indonesia Tahun 1945;
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9281, '2018, No.34 -2-
1. Pasal 4 ayat (1) Undang-Undang Dasar Negara Republik Indonesia Tahun 1945;
2. Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3. Peraturan Pemerintah Nomor 21 Tahun 2008 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan Lembaran Negara Republik Indonesia Nomor 4828);
4. Peraturan Pemerintah Nomor 22 Tahun 2008 tentang Pendanaan dan Pengelolaan Bantuan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);', 'Mengingat', 'Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9282, 'perpres-17-2018', 3, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan : PERATURAN PRESIDEN TENTANG PENYELENGGARAAN PENANGGULANGAN BENCANA DALAM KEADAAN TERTENTU.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9282, 'Menetapkan : PERATURAN PRESIDEN TENTANG PENYELENGGARAAN PENANGGULANGAN BENCANA DALAM KEADAAN TERTENTU.', 'Menetapkan', 'Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9283, 'perpres-17-2018', 4, 'pasal', 'Pasal 1', NULL, 2, 'Dalam Peraturan Presiden ini yang dimaksud dengan:
1. Keadaan Tertentu adalah suatu keadaan dimana status Keadaan Darurat Bencana belum ditetapkan atau status Keadaan Darurat Bencana telah berakhir dan/atau tidak diperpanjang, namun diperlukan atau masih diperlukan tindakan guna mengurangi Risiko Bencana dan dampak yang lebih luas.
2. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2018, No.34
3. Keadaan Darurat Bencana adalah suatu keadaan yang mengancam dan mengganggu kehidupan dan penghidupan sekelompok orang/masyarakat yang memerlukan tindakan penanganan segera dan memadai, yang meliputi kondisi siaga darurat, tanggap darurat, dan transisi darurat ke pemulihan.
4. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat merupakan kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, mengungsi, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9283, 'Dalam Peraturan Presiden ini yang dimaksud dengan:
1. Keadaan Tertentu adalah suatu keadaan dimana status Keadaan Darurat Bencana belum ditetapkan atau status Keadaan Darurat Bencana telah berakhir dan/atau tidak diperpanjang, namun diperlukan atau masih diperlukan tindakan guna mengurangi Risiko Bencana dan dampak yang lebih luas.
2. Bencana adalah peristiwa atau rangkaian peristiwa yang mengancam dan mengganggu kehidupan dan penghidupan masyarakat yang disebabkan, baik oleh faktor alam dan/atau faktor nonalam maupun faktor manusia sehingga mengakibatkan timbulnya korban jiwa manusia, kerusakan lingkungan, kerugian harta benda, dan dampak psikologis.
2018, No.34
3. Keadaan Darurat Bencana adalah suatu keadaan yang mengancam dan mengganggu kehidupan dan penghidupan sekelompok orang/masyarakat yang memerlukan tindakan penanganan segera dan memadai, yang meliputi kondisi siaga darurat, tanggap darurat, dan transisi darurat ke pemulihan.
4. Risiko Bencana adalah potensi kerugian yang ditimbulkan akibat bencana pada suatu wilayah dan kurun waktu tertentu yang dapat merupakan kematian, luka, sakit, jiwa terancam, hilangnya rasa aman, mengungsi, kerusakan atau kehilangan harta, dan gangguan kegiatan masyarakat.', 'Pasal 1', 'Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9284, 'perpres-17-2018', 5, 'pasal', 'Pasal 2', NULL, 3, '(1) Penentuan status Keadaan Darurat Bencana dilaksanakan oleh pemerintah atau pemerintah daerah sesuai dengan tingkatan bencana.
(2) Penentuan status Keadaan Darurat Bencana sebagaimana dimaksud pada ayat (1) untuk tingkat nasional ditetapkan oleh Presiden, tingkat daerah provinsi oleh gubernur, dan tingkat daerah kabupaten/kota oleh bupati/wali kota.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9284, '(1) Penentuan status Keadaan Darurat Bencana dilaksanakan oleh pemerintah atau pemerintah daerah sesuai dengan tingkatan bencana.
(2) Penentuan status Keadaan Darurat Bencana sebagaimana dimaksud pada ayat (1) untuk tingkat nasional ditetapkan oleh Presiden, tingkat daerah provinsi oleh gubernur, dan tingkat daerah kabupaten/kota oleh bupati/wali kota.', 'Pasal 2', 'Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9285, 'perpres-17-2018', 6, 'pasal', 'Pasal 3', NULL, 3, '(1) Dalam Keadaan Tertentu, Kepala Badan Nasional Penanggulangan Bencana dapat melaksanakan penyelenggaraan penanggulangan Bencana termasuk kemudahan akses dalam penanganan darurat bencana sampai batas waktu tertentu, setelah mendapatkan keputusan dalam rapat koordinasi antarkementerian/ lembaga yang dikoordinasikan oleh Menteri Koordinator yang membidangi koordinasi penyelenggaraan penanggulangan bencana.
(2) Penyelenggaraan penanggulangan Bencana sebagaimana dimaksud pada ayat (1), dilakukan pada kondisi:
2018, No.34 -4-
a. adanya potensi Bencana dengan tingkat ancaman maksimum; dan
b. telah terjadi evakuasi/penyelamatan/ pengungsian atau gangguan fungsi pelayanan umum yang berdampak luas terhadap kehidupan sosial dan ekonomi masyarakat.
(3) Pelaksanaan penyelenggaraan penanggulangan Bencana termasuk kemudahan akses dalam penanganan darurat bencana sebagaimana dimaksud pada ayat (1), dilakukan sesuai dengan ketentuan peraturan perundang-undangan.
(4) Ketentuan lebih lanjut mengenai kondisi dan tata cara pelaksanaan penyelenggaraan penanggulangan Bencana sebagaimana dimaksud pada ayat (2) dan ayat (3), diatur dalam pedoman yang ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9285, '(1) Dalam Keadaan Tertentu, Kepala Badan Nasional Penanggulangan Bencana dapat melaksanakan penyelenggaraan penanggulangan Bencana termasuk kemudahan akses dalam penanganan darurat bencana sampai batas waktu tertentu, setelah mendapatkan keputusan dalam rapat koordinasi antarkementerian/ lembaga yang dikoordinasikan oleh Menteri Koordinator yang membidangi koordinasi penyelenggaraan penanggulangan bencana.
(2) Penyelenggaraan penanggulangan Bencana sebagaimana dimaksud pada ayat (1), dilakukan pada kondisi:
2018, No.34 -4-
a. adanya potensi Bencana dengan tingkat ancaman maksimum; dan
b. telah terjadi evakuasi/penyelamatan/ pengungsian atau gangguan fungsi pelayanan umum yang berdampak luas terhadap kehidupan sosial dan ekonomi masyarakat.
(3) Pelaksanaan penyelenggaraan penanggulangan Bencana termasuk kemudahan akses dalam penanganan darurat bencana sebagaimana dimaksud pada ayat (1), dilakukan sesuai dengan ketentuan peraturan perundang-undangan.
(4) Ketentuan lebih lanjut mengenai kondisi dan tata cara pelaksanaan penyelenggaraan penanggulangan Bencana sebagaimana dimaksud pada ayat (2) dan ayat (3), diatur dalam pedoman yang ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana.', 'Pasal 3', 'Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9286, 'perpres-17-2018', 7, 'pasal', 'Pasal 4', NULL, 4, 'Peraturan Presiden ini mulai berlaku pada tanggal diundangkan.
2018, No.34 Agar setiap orang mengetahuinya, memerintahkan pengundangan Peraturan Presiden ini dengan penempatannya dalam Lembaran Negara Republik Indonesia.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9286, 'Peraturan Presiden ini mulai berlaku pada tanggal diundangkan.
