INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9289, 'perpres-46-2026', 1, 'mengingat', 'Mengingat', NULL, 1, 'a bahwa dalam rangka melaksanakan penanggulangan bencana secara terkoordinasi, terencana, dan terpadu perlu memperhatikan aspek good gouemance dan bersikap hati-hati serta upaya penciptaan suasana yang aman, tenteram, tertib, damai, dan sejahtera, sebagai wujud hak setiap orang atas peiindungan terhadap bencana; b bahwa dalam keadaan tertentu diperlukan atau masih diperlukan tindakan guna mengurangi risiko bencana dan/atau konflik sosial perlu memberikan penugasan dan kewenangan kepada Badan Nasional Penanggulangan Bencana untuk dapat melakukan penyelenggaraan penanggulangan bencana; c bahwa ketentuan dalam Peraturan Presiden Nomor l7 Tahun 20 1 8 tentang Penyelenggaraan penanggulangan Bencana dalam Keadaan Tertentu belum komprehensif mengatur penanggulangan bencana pada kondisi yang wilayahnya terkena dampak konflik sosial sesuai dengan dinamika dan kebutuhan hukum masyarakat sehingga perlu diubah; d bahwa berdasarkal pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, dan huruf c, perlu menetapkan Peratural presiden tentang Perubahan atas Peraturan presiden Nomor lT Tahun 2O I 8 tentang Penyelenggaraan penanggulangan Bencana dalam Keadaan Tertentu; . . .
REPUBUK INOONESI,A Mengingat : 1 Pasal 4 ayat (1) Undang-Undang Dasar Negara Republik Indonesia Tahun 1945;
2 Undang-Undang Nomor 24 Tahun 2OO7 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2OO7 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3 Peraturan Pemerintah Nomor 21 Tahun 2OO8 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan lrmbaran Negara Republik Indonesia Nomor 4828);
4 Peraturan Pemerintah Nomor 22 Tahun 20O8 tentalg Pendanaan dan Pengelolaan Bantuan Bencana (kmbaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5 Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu (Lembaran Negara Republik Indonesia Tahun 2O18 Nomor 34);
MEMUTUSI(AN:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9289, 'a bahwa dalam rangka melaksanakan penanggulangan bencana secara terkoordinasi, terencana, dan terpadu perlu memperhatikan aspek good gouemance dan bersikap hati-hati serta upaya penciptaan suasana yang aman, tenteram, tertib, damai, dan sejahtera, sebagai wujud hak setiap orang atas peiindungan terhadap bencana; b bahwa dalam keadaan tertentu diperlukan atau masih diperlukan tindakan guna mengurangi risiko bencana dan/atau konflik sosial perlu memberikan penugasan dan kewenangan kepada Badan Nasional Penanggulangan Bencana untuk dapat melakukan penyelenggaraan penanggulangan bencana; c bahwa ketentuan dalam Peraturan Presiden Nomor l7 Tahun 20 1 8 tentang Penyelenggaraan penanggulangan Bencana dalam Keadaan Tertentu belum komprehensif mengatur penanggulangan bencana pada kondisi yang wilayahnya terkena dampak konflik sosial sesuai dengan dinamika dan kebutuhan hukum masyarakat sehingga perlu diubah; d bahwa berdasarkal pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, dan huruf c, perlu menetapkan Peratural presiden tentang Perubahan atas Peraturan presiden Nomor lT Tahun 2O I 8 tentang Penyelenggaraan penanggulangan Bencana dalam Keadaan Tertentu; . . .
REPUBUK INOONESI,A Mengingat : 1 Pasal 4 ayat (1) Undang-Undang Dasar Negara Republik Indonesia Tahun 1945;
2 Undang-Undang Nomor 24 Tahun 2OO7 tentang Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2OO7 Nomor 66, Tambahan Lembaran Negara Republik Indonesia Nomor 4723);
3 Peraturan Pemerintah Nomor 21 Tahun 2OO8 tentang Penyelenggaraan Penanggulangan Bencana (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 42, Tambahan lrmbaran Negara Republik Indonesia Nomor 4828);
4 Peraturan Pemerintah Nomor 22 Tahun 20O8 tentalg Pendanaan dan Pengelolaan Bantuan Bencana (kmbaran Negara Republik Indonesia Tahun 2008 Nomor 43, Tambahan Lembaran Negara Republik Indonesia Nomor 4829);
5 Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu (Lembaran Negara Republik Indonesia Tahun 2O18 Nomor 34);
MEMUTUSI(AN:', 'Mengingat', 'Peraturan Presiden Nomor 46 Tahun 2026 tentang Perubahan atas Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9290, 'perpres-46-2026', 2, 'menetapkan', 'Menetapkan', NULL, 2, 'Menetapkan PERATURAN PRESIDEN TENTANG PERUBAHAN ATAS PERATURAN PRESIDEN NOMOR 17 TAHUN 2018 TENTANG PENYELENGGARAAN PENANGGULANGAN BENCANA DALAM KEADAAN TERTENTU.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9290, 'Menetapkan PERATURAN PRESIDEN TENTANG PERUBAHAN ATAS PERATURAN PRESIDEN NOMOR 17 TAHUN 2018 TENTANG PENYELENGGARAAN PENANGGULANGAN BENCANA DALAM KEADAAN TERTENTU.', 'Menetapkan', 'Peraturan Presiden Nomor 46 Tahun 2026 tentang Perubahan atas Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9291, 'perpres-46-2026', 3, 'pasal', 'Pasal I', NULL, 2, 'Ketentuan ayal (21 Pasal 3 Peraturan Presiden Nomor 17 Tahun 2Ol8 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu (Lembaran Negara Republik Indonesia Tahun 2018 Nomor 34) diubah sehingga Pasal 3 berbunyi sebagai berikut:');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9291, 'Ketentuan ayal (21 Pasal 3 Peraturan Presiden Nomor 17 Tahun 2Ol8 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu (Lembaran Negara Republik Indonesia Tahun 2018 Nomor 34) diubah sehingga Pasal 3 berbunyi sebagai berikut:', 'Pasal I', 'Peraturan Presiden Nomor 46 Tahun 2026 tentang Perubahan atas Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu');
INSERT INTO hukum_segmen (id, dok, urut, jenis, label, bab, halaman, teks) VALUES (9292, 'perpres-46-2026', 4, 'pasal', 'Pasal 3', NULL, 3, '-3 Pasal 3
(1) Dalam Keadaan Tertentu, Kepala Badan Nasional Penanggulangan Bencana dapat melaksanakan penyelenggaraan penanggulangan bencana termasuk kemudahan akses dalam penanganan darurat bencana sampai batas waktu tertentu, setelah mendapatkan keputusan dalam rapat koordinasi antarkementerian/lembaga yang dikoordinasikan oleh menteri koordinator yang membidangi koordinasi penyelenggaraan penanggulangan bencana.
(21 Penyelenggaraan penanggulangan bencana sebagaimana dimaksud pada ayat (1), dilakukan pada kondisi:
a. adanya potensi Bencana dengan tingkat ancaman maksimum yang disebabkan oleh faktor alam, nonalam, dan/atau sosial;
b. telah terjadi evakuasi/penyelamatan/ pengungsian atau gangguan fungsi pelayanan umum yang berdampak luas terhadaP kehidupan sosial dan ekonomi masyarakat; dan/ atau
c. pemerintah daerah yang wilayahnya dalam proses rekonsiliasi pascakonflik sosial dan memiliki kapasitas fiskal sangat rendah atau rendah sesuai dengan ketentuan peraturan perundang-undangan di bidang keuangan negara.
(3) Pelaksanaan penyelenggaraan penanggulangan bencana termasuk kemudahan akses dalam penanganan darurat bencana sebagaimana dimaksud pada ayat (1), dilakukan sesuai dengan ketentuan peraturan perundang-undangan.
(4) Ketentuan lebih lanjut mengenai kondisi dan tata cara pelaksanaan penyelenggaraan penanggulangan bencana sebagaimana dimaksud pada ayat (2) dan ayat (3), diatur dalam pedoman yang ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana.');
INSERT INTO hukum_fts (rowid, teks, label, judul) VALUES (9292, '-3 Pasal 3
(1) Dalam Keadaan Tertentu, Kepala Badan Nasional Penanggulangan Bencana dapat melaksanakan penyelenggaraan penanggulangan bencana termasuk kemudahan akses dalam penanganan darurat bencana sampai batas waktu tertentu, setelah mendapatkan keputusan dalam rapat koordinasi antarkementerian/lembaga yang dikoordinasikan oleh menteri koordinator yang membidangi koordinasi penyelenggaraan penanggulangan bencana.
(21 Penyelenggaraan penanggulangan bencana sebagaimana dimaksud pada ayat (1), dilakukan pada kondisi:
a. adanya potensi Bencana dengan tingkat ancaman maksimum yang disebabkan oleh faktor alam, nonalam, dan/atau sosial;
b. telah terjadi evakuasi/penyelamatan/ pengungsian atau gangguan fungsi pelayanan umum yang berdampak luas terhadaP kehidupan sosial dan ekonomi masyarakat; dan/ atau
c. pemerintah daerah yang wilayahnya dalam proses rekonsiliasi pascakonflik sosial dan memiliki kapasitas fiskal sangat rendah atau rendah sesuai dengan ketentuan peraturan perundang-undangan di bidang keuangan negara.
(3) Pelaksanaan penyelenggaraan penanggulangan bencana termasuk kemudahan akses dalam penanganan darurat bencana sebagaimana dimaksud pada ayat (1), dilakukan sesuai dengan ketentuan peraturan perundang-undangan.
(4) Ketentuan lebih lanjut mengenai kondisi dan tata cara pelaksanaan penyelenggaraan penanggulangan bencana sebagaimana dimaksud pada ayat (2) dan ayat (3), diatur dalam pedoman yang ditetapkan oleh Kepala Badan Nasional Penanggulangan Bencana.', 'Pasal 3', 'Peraturan Presiden Nomor 46 Tahun 2026 tentang Perubahan atas Peraturan Presiden Nomor 17 Tahun 2018 tentang Penyelenggaraan Penanggulangan Bencana dalam Keadaan Tertentu');
